TEST(AgradMixMatrixRowsDotProduct,fv_vector_vector_1stDeriv) {
  using stan::math::vector_d;
  using stan::math::vector_fv;
  vector_d vd_1(3), vd_2(3);
  vector_fv vv_1(3), vv_2(3);

  vd_1 << 1, 3, -5;
  vv_1 << 1, 3, -5;
   vv_1(0).d_ = 1.0;
   vv_1(1).d_ = 1.0;
   vv_1(2).d_ = 1.0;
  vd_2 << 4, -2, -1;
  vv_2 << 4, -2, -1;
   vv_2(0).d_ = 1.0;
   vv_2(1).d_ = 1.0;
   vv_2(2).d_ = 1.0;

  vector_fv output(3);
  output = rows_dot_product(vv_1, vd_2);
