int crypto_box_beforenm(uint8_t *k, const uint8_t *y, const uint8_t *x) {
    uint8_t s[32];
    if (crypto_scalarmult(s, x, y) != 0) return -1;
    if (has_small_order(s) != 0) return -1;
    return crypto_core_hsalsa20(k, _0, s, sigma);
}

