        color c = get_color();
        const position_type& current_pos = get_position();
        bool valid = false;
        bool same_column = new_pos.first == current_pos.first;
        bool adv1_w = (new_pos.second == current_pos.second + 1) && (c == 'w');
        bool adv2_w = (new_pos.second == current_pos.second + 2) && (c == 'w');
        bool adv1_b = (new_pos.second + 1 == current_pos.second) && (c == 'b');
        bool adv2_b = (new_pos.second + 2 == current_pos.second) && (c == 'b');
        bool adv_1 = same_column && (adv1_w || adv1_b);
        bool adv_2 = same_column && (adv2_w || adv2_b);
        bool diag_w = (new_pos.first == current_pos.first + 1 || new_pos.first + 1 == current_pos.first)
            && (new_pos.second == current_pos.second + 1u);
        bool diag_b = (new_pos.first + 1 == current_pos.first || new_pos.first == current_pos.first + 1)
            && (new_pos.second == current_pos.second + 1u);

        if (diag_w || diag_b)
        {
            valid = cb(new_pos, get_opposite_color());
        }
        else if(adv_1)
        {
            valid = !cb(new_pos, 'a');
        }
        else if(adv_2)
        {
            valid = !m_has_moved;
            if (c == 'w')
            {
                valid &= !cb(position_type(current_pos.first, current_pos.second + 1), 'a');
            }
            else
            {
                valid &= !cb(position_type(current_pos.first, new_pos.second + 1), 'a');
            }
            valid &= !cb(new_pos, 'a');
        }
        return valid;
    }
    void pawn::print(std::ostream& out) const
    {
        out << "P" << get_color();
    }
    void pawn::notify_move()
    {
        m_has_moved = true;
    }
}

#include "FastPix3D.h"

Color::Color()
{
	R = 0;
	G = 0;
	B = 0;
}
Color::Color(int32 r, int32 g, int32 b)
{
	R = r;
	G = g;
	B = b;
}
Color::Color(int32 rgb)
{
	R = (rgb & 0xff0000) >> 16;
	G = (rgb & 0xff00) >> 8;
	B = rgb & 0xff;
}

int32 Color::getRGB()
{
	return R << 16 | G << 8 | B;
}

#include "ActionSettingsPane.h"
#include <gui/util/FieldSet.h>
#include <gui/util/WidgetHelper.h>
#include <QColorDialog>
#include <QFormLayout>
#include <QLabel>
#include <QPushButton>
namespace gui::settings {
    ActionSettingsPane::ActionSettingsPane(model::settings::ActionSettingsModel *settings, QWidget *parent)
        : QWidget(parent), settings(settings) {
        mode = settings->getMode();
        sound = settings->getSound();
        color = settings->getColor();
        interval = settings->getInterval();
        count = settings->getCount();
        initComponents();
    }
    void ActionSettingsPane::initComponents() {
        auto *form = new QGridLayout(this);
        // ----- mode -----
        {
            auto *field = new QComboBox;
            auto *fieldSet = new util::FieldSet<QComboBox>(0, new QLabel("Mode"), field);
            gui::util::widget::addItems<model::ActionMode>(field, model::actionModes(), [](model::ActionMode mode) {
                return model::getName(mode);
            });
            field->setCurrentText(model::getName(settings->getMode()));
            util::addFieldSet(form, *fieldSet);
            connect(field, SIGNAL(currentIndexChanged(int)), this, SLOT(setMode(int)));
        }
        // ----- sound -----
        {
            auto *field = new QComboBox;
            auto *fieldSet = new util::FieldSet<QComboBox>(1, new QLabel("Sound"), field);
            gui::util::widget::addItems<model::Sound>(field, model::sounds(), [](model::Sound sound) {
                return model::getName(sound);
            });
            field->setCurrentText(model::getName(settings->getSound()));
            util::addFieldSet(form, *fieldSet);
            connect(field, SIGNAL(currentIndexChanged(int)), this, SLOT(setSound(int)));
            connect(this, &ActionSettingsPane::modeChanged, [form, fieldSet](const int mode) {
                const bool visible = mode == model::ActionMode::AUDIO || mode == model::ActionMode::AV;
                util::setVisible(form, *fieldSet, visible);
            });
        }
        // ----- color -----
        {
            auto *field = new QPushButton;
            auto *fieldSet = new util::FieldSet<QPushButton>(2, new QLabel("Color"), field);
            setIconColor(field, color);
            connect(field, &QPushButton::clicked, [this, field] {
                const QColor selectedColor = QColorDialog::getColor(color, this);
                if (selectedColor.isValid()) {
                    setIconColor(field, selectedColor);
                    color = selectedColor;
                }
            });
            connect(this, &ActionSettingsPane::modeChanged, [form, fieldSet](const int mode) {
                const bool visible = mode == model::ActionMode::VISUAL || mode == model::ActionMode::AV;
                util::setVisible(form, *fieldSet, visible);
            });
            util::addFieldSet(form, *fieldSet);
        }
        // ----- interval -----
        {
            auto *field = new QSpinBox;
            auto *fieldSet = new util::FieldSet<QSpinBox>(3, new QLabel("Interval"), field);
            gui::util::widget::setModel(field, 1, 1000, settings->getInterval());
            util::addFieldSet(form, *fieldSet);
            connect(field, SIGNAL(valueChanged(int)), this, SLOT(setInterval(int)));
        }
        // ----- count -----
        {
            auto *field = new QSpinBox;
            auto *fieldSet = new util::FieldSet<QSpinBox>(4, new QLabel("Count"), field);
            gui::util::widget::setModel(field, 1, 50, settings->getCount());
            util::addFieldSet(form, *fieldSet);
            connect(field, SIGNAL(valueChanged(int)), this, SLOT(setCount(int)));
        }
        // force all fieldsets to update visibility
        emit modeChanged(mode);
    }
    void ActionSettingsPane::updateSettings() {
        settings->setMode(model::actionMode(static_cast<unsigned int>(mode)));
        settings->setSound(model::sound(static_cast<unsigned int>(sound)));
        settings->setInterval(static_cast<unsigned int>(interval));
        settings->setCount(static_cast<unsigned int>(count));
        settings->setColor(color);
    }
    void ActionSettingsPane::setMode(int mode) {
        if (this->mode != mode) {
            emit modeChanged(mode);
            this->mode = mode;
        }
    }
    void ActionSettingsPane::setSound(int sound) { this->sound = sound; }
    void ActionSettingsPane::setInterval(int interval) { this->interval = interval; }
    void ActionSettingsPane::setCount(int count) { this->count = count; }
    void ActionSettingsPane::setIconColor(QPushButton *btn, const QColor &color) {
        QPixmap pixmap(64, 64);
        pixmap.fill(color);
        QIcon icon(pixmap);
        btn->setIcon(icon);
    }
}  // namespace gui::settings

#include "test_helper.h"
#include "compiler/lexical_grammar.h"
#include "compiler/prepare_grammar/expand_tokens.h"
#include "helpers/stream_methods.h"
START_TEST
using namespace rules;
using prepare_grammar::expand_token;
using prepare_grammar::ExpandTokenResult;
describe("expand_tokens", []() {
  MetadataParams string_token_params;
  string_token_params.is_string = true;
  string_token_params.is_token = true;
  describe("string rules", [&]() {
    it("replaces strings with sequences of character sets", [&]() {
      AssertThat(
        expand_token(Rule::seq({
          String{"a"},
          String{"bcd"},
          String{"e"}
        })).rule,
        Equals(Rule::seq({
          CharacterSet{{ 'a' }},
          Rule::seq({
            CharacterSet{{ 'b' }},
            CharacterSet{{ 'c' }},
            CharacterSet{{ 'd' }},
          }),
          CharacterSet{{ 'e' }},
        })));
    });
    it("handles strings containing non-ASCII UTF8 characters", [&]() {
      AssertThat(
        expand_token(String{"\xCE\xB1 \xCE\xB2"}).rule,
        Equals(Rule::seq({
          CharacterSet{{ 945 }},
          CharacterSet{{ ' ' }},
          CharacterSet{{ 946 }},
        }))
      );
    });
  });
  describe("regexp rules", [&]() {
    it("replaces regexps with the equivalent rule tree", [&]() {
      AssertThat(
        expand_token(Rule::seq({
          String{"a"},
          Pattern{"x+"},
          String{"b"},
        })).rule,
        Equals(Rule::seq({
          CharacterSet{{'a'}},
          Repeat{CharacterSet{{ 'x' }}},
          CharacterSet{{'b'}},
        }))
      );
    });
    it("handles regexps containing non-ASCII UTF8 characters", [&]() {
      AssertThat(
        expand_token(Pattern{"[^\xCE\xB1-\xCE\xB4]+"}).rule,
        Equals(Rule(Repeat{
          CharacterSet().include_all().exclude(945, 948)
        }))
      );
    });
    it("returns an error when the grammar contains an invalid regex", [&]() {
      AssertThat(
        expand_token(Rule::seq({
          Pattern{"("},
          String{"xyz"},
          Pattern{"["},
        })).error,
        Equals(CompileError(
          TSCompileErrorTypeInvalidRegex,
          "unmatched open paren"
        ))
      );
    });
  });
});
END_TEST

#include <LuaConsole/LuaSFMLConsoleView.hpp>
#include <LuaConsole/LuaConsoleModel.hpp>
#include <SFML/Graphics/RenderTarget.hpp>
namespace blua {
const unsigned kFontSize = 18u;
const char * const kFontName = "DejaVuSansMono.ttf";
static sf::Color toColor(unsigned color)
{
    sf::Color ret;
    ret.r = (color & 0xff000000) >> 24;
    ret.g = (color & 0xff0000) >> 16;
    ret.b = (color & 0xff00) >> 8;
    ret.a = color & 0xff;
    return ret;
}
LuaSFMLConsoleView::LuaSFMLConsoleView(bool defaultfont) :
m_lastdirtyness(0u),
m_font(0x0),
m_ownfont(false),
m_defaultfont(defaultfont),
m_modelvisible(false)
{
    m_vertices.setPrimitiveType(sf::Quads);
    if(m_defaultfont)
    {
        sf::Font * dfont = new sf::Font;
        dfont->loadFromFile(kFontName);
        m_font = dfont;
        m_ownfont = true;
    }
}
LuaSFMLConsoleView::~LuaSFMLConsoleView()
{
    if(m_ownfont)
        delete m_font;
}
void LuaSFMLConsoleView::draw(sf::RenderTarget& target, sf::RenderStates states) const
{
    if(!m_font || !m_modelvisible)
        return;
    //draw in a single call in a 1:1 view
    sf::View v = target.getView();
    target.setView(sf::View(sf::FloatRect(sf::Vector2f(), sf::Vector2f(target.getSize()))));
    states.texture = &m_font->getTexture(kFontSize);
    target.draw(m_vertices, states);
    target.setView(v);
}
void LuaSFMLConsoleView::setFont(const sf::Font * font)
{
    //do something to dirtyness to force rebuilding letters??
    if(m_ownfont)
        delete m_font;
    m_font = font;
    m_ownfont = false; //never own a set font
    //if set font is null and we have default option then set it
    if(!m_font && m_defaultfont)
    {
        sf::Font * dfont = new sf::Font;
        dfont->loadFromFile(kFontName);
        m_font = dfont;
        m_ownfont = true;
    }
}
const sf::Font * LuaSFMLConsoleView::getFont() const
{
    return m_font;
}
