RTDECL(int) RTZipTarFsStreamFromIoStream(RTVFSIOSTREAM hVfsIosIn, uint32_t fFlags, PRTVFSFSSTREAM phVfsFss)
{
    /*
     * Input validation.
     */
    AssertPtrReturn(phVfsFss, VERR_INVALID_HANDLE);
    *phVfsFss = NIL_RTVFSFSSTREAM;
    AssertPtrReturn(hVfsIosIn, VERR_INVALID_HANDLE);
    AssertReturn(!fFlags, VERR_INVALID_PARAMETER);
    RTFOFF const offStart = RTVfsIoStrmTell(hVfsIosIn);
    AssertReturn(offStart >= 0, (int)offStart);
    uint32_t cRefs = RTVfsIoStrmRetain(hVfsIosIn);
    AssertReturn(cRefs != UINT32_MAX, VERR_INVALID_HANDLE);
    /*
     * Retain the input stream and create a new filesystem stream handle.
     */
    PRTZIPTARFSSTREAM pThis;
    RTVFSFSSTREAM     hVfsFss;
    int rc = RTVfsNewFsStream(&rtZipTarFssOps, sizeof(*pThis), NIL_RTVFS, NIL_RTVFSLOCK, true /*fReadOnly*/,
                              &hVfsFss, (void **)&pThis);
    if (RT_SUCCESS(rc))
    {
        pThis->hVfsIos              = hVfsIosIn;
        pThis->hVfsCurObj           = NIL_RTVFSOBJ;
        pThis->pCurIosData          = NULL;
        pThis->offStart             = offStart;
        pThis->offNextHdr           = offStart;
        pThis->fEndOfStream         = false;
        pThis->rcFatal              = VINF_SUCCESS;
        pThis->TarReader.enmPrevType= RTZIPTARTYPE_INVALID;
        pThis->TarReader.enmType    = RTZIPTARTYPE_INVALID;
        pThis->TarReader.enmState   = RTZIPTARREADERSTATE_FIRST;
        /* Don't check if it's a TAR stream here, do that in the
           rtZipTarFss_Next. */
        *phVfsFss = hVfsFss;
        return VINF_SUCCESS;
    }
    RTVfsIoStrmRelease(hVfsIosIn);
    return rc;
}

#include "steering_wheel_shield.h"
#include "steering_wheel_definitions.h"
namespace steering_wheel_shield {
    inline void set_csx() { GPIOC_PSOR = CSX_MASK; }
    inline void clr_csx() { GPIOC_PCOR = CSX_MASK; }
    inline void set_dcx() { GPIOC_PSOR = DCX_MASK; }
    inline void clr_dcx() { GPIOC_PCOR = DCX_MASK; }
    inline void set_wrx() { GPIOC_PSOR = WRX_MASK; }
    inline void clr_wrx() { GPIOC_PCOR = WRX_MASK; }
    inline void set_rdx() { GPIOC_PSOR = RDX_MASK; }
    inline void clr_rdx() { GPIOC_PCOR = RDX_MASK; }
    inline void set_rst() { GPIOE_PSOR = RST_MASK; }
    inline void clr_rst() { GPIOE_PCOR = RST_MASK; }
    inline void clr_data() {
        GPIOB_PCOR = PORTB_DATA_MASK;
        GPIOC_PCOR = PORTC_DATA_MASK;
    };
    void write_command(uint8_t* data, uint8_t n) {
        clr_csx();
        clr_dcx();
        GPIOC_PSOR = data[0] << 4;
        clr_wrx();
        NOPN(0, 0, 9);
        set_wrx();
        NOPN(0, 0, 3);
        GPIOC_PCOR = data[0] << 4;
        set_dcx();
        for (int i = 1; i < n; i++) {
            GPIOC_PSOR = data[i] << 4;
            clr_wrx();
            NOPN(0, 0, 9);
            set_wrx();
            NOPN(0, 0, 3);
            GPIOC_PCOR = data[i] << 4;
        }
        set_csx();
    }
    void set_window(uint16_t start_x, uint16_t end_x, uint16_t start_y, uint16_t end_y) {
        uint8_t buf[5];
        buf[0] = HX8357_SET_COLUMN_ADDRESS;
        buf[1] = (start_x >> 8) & 0xFF;
        buf[2] = start_x & 0xFF;
        buf[3] = (end_x >> 8) & 0xFF;
        buf[4] = end_x & 0xFF;
        write_command(buf, 5);
        buf[0] = HX8357_SET_PAGE_ADDRESS;
        buf[1] = (start_y >> 8) & 0xFF;
        buf[2] = start_y & 0xFF;
        buf[3] = (end_y >> 8) & 0xFF;
        buf[4] = end_y & 0xFF;
        write_command(buf, 5);
    }
    void fill_screen() {
        clr_csx();
        clr_dcx();
        GPIOC_PSOR = HX8357_WRITE_MEMORY_START << 4;
        clr_wrx();
        NOPN(0, 0, 9);
        set_wrx();
        NOPN(0, 0, 3);
        GPIOC_PCOR = HX8357_WRITE_MEMORY_START << 4;
        set_dcx();
        GPIOC_PSOR = 0x000003F0;
        for (int i = 0; i < 320; i++) {
            for (int j = 0; j < 480; j++) {
                clr_wrx();
                NOPN(0, 0, 9);
                set_wrx();
                NOPN(0, 0, 3);
            }
        }
        GPIOC_PCOR = 0x000003F0;
    }
    void reset() {
        set_csx();
        set_dcx();
        set_wrx();
        set_rdx();
        set_rst();
        clr_data();
        delay(100);
        clr_rst();
        delay(100);
        set_rst();
        delay(100);
        uint8_t buf[16];
        buf[0] = HX8357_SET_POWER;
        buf[1] = 0x44;
        buf[2] = 0x41;
        buf[3] = 0x06;
        write_command(buf, 4);
        buf[0] = HX8357_SET_VCOM;
        buf[1] = 0x40;
        buf[2] = 0x10;
        write_command(buf, 3);
        buf[0] = HX8357_SET_POWER_NORMAL;
        buf[1] = 0x05;
        buf[2] = 0x12;
        write_command(buf, 3);
        buf[0] = HX8357_SET_PANEL_DRIVING;
        buf[1] = 0x14;
