}
void sqlrconfigs::getEnabledIds(const char *urls,
					linkedlist< char * > *idlist) {
	debugFunction();
	// separate the urls
	char		**url;
	uint64_t	urlcount;
	charstring::split(urls,",",true,&url,&urlcount);
	// for each url...
	for (uint64_t i=0; i<urlcount; i++) {
		const char	*u=url[i];
		// parse out the protocol
	 	char		*protocol=NULL;
		const char	*colon=charstring::findFirst(u,':');
		if (colon) {
			protocol=charstring::duplicate(u,colon-u);
		}
		// try to load a config plugin for that protocol
	 	if (protocol) {
	 		loadConfig(protocol);
			delete[] protocol;
	 	}
		// fall back to the xml plugin if that plugin failed to load
		if (!cfg) {
			loadConfig("xmldom");
		}
		// get the enabled ids for the specified url
		if (cfg) {
			cfg->getEnabledIds(u,idlist);
		}
		// clean up
		delete cfg;
		cfg=NULL;
		delete dl;
		dl=NULL;
	}
	// clean up
	for (uint64_t i=0; i<urlcount; i++) {
		delete[] url[i];
	}
	delete[] url;
}
sqlrconfig *sqlrconfigs::load(const char *urls, const char *id) {
	debugFunction();
	// sanity check
	if (charstring::isNullOrEmpty(urls) || charstring::isNullOrEmpty(id)) {
		return NULL;
	}
	debugPrintf("urls: %s\n",urls);
	debugPrintf("id: %s\n",id);
	// separate the urls
	char		**url;
	uint64_t	urlcount;
	charstring::split(urls,",",true,&url,&urlcount);
	// for each url...
	for (uint64_t i=0; i<urlcount; i++) {
		const char	*u=url[i];
		debugPrintf("    url: %s\n",u);
		// parse out the protocol
	 	char	*protocol=NULL;
		const char	*colon=charstring::findFirst(u,':');
		if (colon) {
			protocol=charstring::duplicate(u,colon-u);
		}
		// try to load a config plugin for that protocol
	 	if (protocol) {
	 		loadConfig(protocol);
			delete[] protocol;
	 	}
		// fall back to the xml plugin if that plugin failed to load
		if (!cfg) {
			loadConfig("xmldom");
		}
		// load the configuration for the specified id
		if (cfg) {
			if (cfg->load(u,id)) {
				break;
			} else {
				delete cfg;
				cfg=NULL;
			}
		}
	}
	// clean up
	for (uint64_t i=0; i<urlcount; i++) {
		delete[] url[i];
	}
	delete[] url;
	// warn the user if the specified instance wasn't found
	if (!cfg) {
		stderror.printf("Couldn't find id %s.\n",id);
	}
	return cfg;
}
void sqlrconfigs::loadConfig(const char *module) {
	debugFunction();
	debugPrintf("loading config: %s\n",module);
#ifdef SQLRELAY_ENABLE_SHARED
	// load the config module
	stringbuffer	modulename;
	modulename.append(libexecdir);
	modulename.append(SQLR);
	modulename.append("config_");
	modulename.append(module)->append(".")->append(SQLRELAY_MODULESUFFIX);
	dl=new dynamiclib();
	if (!dl->open(modulename.getString(),true,true)) {
		debugPrintf("failed to load config module: %s\n",module);
		char	*error=dl->getError();
		debugPrintf("%s\n",error);
		delete[] error;
		delete dl;
		return;
	}
	// load the config itself
	stringbuffer	functionname;
	functionname.append("new_sqlrconfig_")->append(module);
	sqlrconfig *(*newConfig)()=
			(sqlrconfig *(*)())
				dl->getSymbol(functionname.getString());
	if (!newConfig) {
		debugPrintf("failed to create config: %s\n",module);
		char	*error=dl->getError();
		debugPrintf("%s\n",error);
		delete[] error;
		dl->close();
		delete dl;
		dl=NULL;
		return;
	}
	cfg=(*newConfig)();
#else
	#include "sqlrconfigassignments.cpp"
	{
		cfg=NULL;
	}
#endif
}

#include <BladePCH.h>
#include <utility/StringTable.h>
namespace Blade
{
	/************************************************************************/
	/*                                                                      */
	/************************************************************************/
	//////////////////////////////////////////////////////////////////////////
	tchar* StringTable::readStrings(IOBuffer& buffer, StringInfoList& info, uint32& count, uint32& bytes, IPool* pool/* = Memory::getResourcePool() */)
	{
		if( pool == NULL )
		{
			assert(false);
			return NULL;
		}
		count = 0;
		bytes = 0;
		buffer.read(&count);
		buffer.read(&bytes);
		if( count == 0 || bytes == 0)
			return NULL;
		info.create(count);
		IOBuffer tbuffer;
		for(uint32 i = 0; i < count; ++i)
		{
			//convert utf8 string to tstring
			TString tstr;
			buffer.readTString(tstr);
			tbuffer.writeTStringRAW(tstr);
			info[i].start = (i == 0 ? 0: info[i-1].start + info[i-1].size+1);
			info[i].size = (uint32)tstr.size();
		}
		assert(buffer.eof());
		bytes = (uint32)tbuffer.tell();
		tchar* stringBuffer = (tchar*)pool->allocate( (size_t)bytes );
		std::memcpy(stringBuffer, tbuffer.getData(), (size_t)bytes );
		return stringBuffer;
	}
	//////////////////////////////////////////////////////////////////////////
	tchar* StringTable::readStrings(const HSTREAM& stream, StringInfoList& info, uint32& count, uint32& bytes, IPool* pool/* = Memory::getResourcePool()*/)
	{
		if( stream != NULL && pool != NULL && (stream->getAccesMode()&IStream::AM_READ) )
		{
			count = 0;
			bytes = 0;
			stream->readAtom(count);
			stream->readAtom(bytes);
			if( count == 0 || bytes == 0)
				return NULL;
			IOBuffer buffer;
			buffer.reserve( (size_t)bytes + sizeof(uint32)*2 );
			buffer.write(&count);
			buffer.write(&bytes);
			stream->readData(buffer.getCurrentData(), bytes);
			buffer.rewind();
			return StringTable::readStrings(buffer, info, count, bytes, pool);
		}
		return NULL;
	}
	//////////////////////////////////////////////////////////////////////////
	bool StringTable::writeStrings(IOBuffer& buffer, const TString* stringArray, uint32 count)
	{
		if( stringArray == NULL && count != 0)
		{
			assert(false);
			return false;
		}
		//convert to utf8 string
		IOBuffer cache;
		for(size_t i = 0; i < count; ++i)
			cache.writeTString( stringArray[i] );
		buffer.write(&count);
		uint32 bytes = (uint32)cache.tell();
		buffer.write(&bytes);
		buffer.writeData(cache.getData(), bytes);
		return true;
	}
	//////////////////////////////////////////////////////////////////////////
	bool StringTable::writeStrings(const HSTREAM& stream, const TString* stringArray, uint32 count)
	{
		IOBuffer buffer;
		if( stream != NULL && (stream->getAccesMode()&IStream::AM_WRITE) && StringTable::writeStrings(buffer, stringArray, count) )
			return buffer.saveToStream(stream);
		return false;
	}
	/************************************************************************/
	/*                                                                      */
	/************************************************************************/
	//////////////////////////////////////////////////////////////////////////
	bool StringTableCache::persist(const TStringParam& params, StringTable& table, IPool* pool/* = Memory::getResourcePool()*/)
	{
		IOBuffer buffer;
		if( !StringTable::writeStrings(buffer, params) )
			return false;
		buffer.rewind();
		return StringTable::readStrings(buffer, table, pool);
	}

