FeatureCloudPCLwc RBFilter::getPredictedMeasurement(PredictionHypothesis hypothesis)
{
    FeatureCloudPCLwc predicted_measurement;
    switch(hypothesis)
    {
    case BASED_ON_VELOCITY:
        predicted_measurement = *(this->_predicted_measurement_pc_vh);
