#include "ProfilingUtils.hpp"
#include <armnn/Exceptions.hpp>
#include <boost/test/unit_test.hpp>
using namespace armnn::profiling;
BOOST_AUTO_TEST_SUITE(BufferTests)
BOOST_AUTO_TEST_CASE(PacketBufferTest0)
{
    IPacketBufferPtr packetBuffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(packetBuffer->GetSize() == 0);
    // Write data to the buffer
    WriteUint32(packetBuffer, 0, 10);
    WriteUint32(packetBuffer, 4, 20);
    WriteUint32(packetBuffer, 8, 30);
    WriteUint32(packetBuffer, 12, 40);
    // Commit
    packetBuffer->Commit(16);
    // Size of buffer is equal to committed data
    BOOST_TEST(packetBuffer->GetSize() == 16);
    // Read data from the buffer
    auto readBuffer = packetBuffer->GetReadableData();
    uint32_t readData0 = ReadUint32(readBuffer, 0);
    uint32_t readData1 = ReadUint32(readBuffer, 4);
    uint32_t readData2 = ReadUint32(readBuffer, 8);
    uint32_t readData3 = ReadUint32(readBuffer, 12);
    // Check that data is correct
    BOOST_TEST(readData0 == 10);
    BOOST_TEST(readData1 == 20);
    BOOST_TEST(readData2 == 30);
    BOOST_TEST(readData3 == 40);
    // Mark read
    packetBuffer->MarkRead();
    // Size of buffer become 0 after marked read
    BOOST_TEST(packetBuffer->GetSize() == 0);
}
BOOST_AUTO_TEST_CASE(PacketBufferTest1)
{
    IPacketBufferPtr packetBuffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(packetBuffer->GetSize() == 0);
    // Write data to the buffer using GetWritableData
    auto writeBuffer = packetBuffer->GetWritableData();
    WriteUint32(writeBuffer, 0, 10);
    WriteUint32(writeBuffer, 4, 20);
    WriteUint32(writeBuffer, 8, 30);
    WriteUint32(writeBuffer, 12, 40);
    packetBuffer->Commit(16);
    BOOST_TEST(packetBuffer->GetSize() == 16);
    // Read data from the buffer
    auto readBuffer = packetBuffer->GetReadableData();
    uint32_t readData0 = ReadUint32(readBuffer, 0);
    uint32_t readData1 = ReadUint32(readBuffer, 4);
    uint32_t readData2 = ReadUint32(readBuffer, 8);
    uint32_t readData3 = ReadUint32(readBuffer, 12);
    BOOST_TEST(readData0 == 10);
    BOOST_TEST(readData1 == 20);
    BOOST_TEST(readData2 == 30);
    BOOST_TEST(readData3 == 40);
    packetBuffer->MarkRead();
    BOOST_TEST(packetBuffer->GetSize() == 0);
}
BOOST_AUTO_TEST_CASE(PacketBufferReleaseTest) {
    IPacketBufferPtr packetBuffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(packetBuffer->GetSize() == 0);
    auto writeBuffer = packetBuffer->GetWritableData();
    WriteUint32(writeBuffer, 0, 10);
    WriteUint32(writeBuffer, 4, 20);
    WriteUint32(writeBuffer, 8, 30);
    WriteUint32(writeBuffer, 12, 40);
    packetBuffer->Release();
    // Size of buffer become 0 after release
    BOOST_TEST(packetBuffer->GetSize() == 0);
}
BOOST_AUTO_TEST_CASE(PacketBufferCommitErrorTest)
{
    IPacketBufferPtr packetBuffer = std::make_unique<PacketBuffer>(8);
    // Cannot commit data bigger than the max size of the buffer
    BOOST_CHECK_THROW(packetBuffer->Commit(16);, armnn::RuntimeException);
}
BOOST_AUTO_TEST_CASE(BufferReserveTest)
{
    BufferManager bufferManager(1, 512);
    unsigned int reservedSize = 0;
    auto packetBuffer = bufferManager.Reserve(512, reservedSize);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize == 512);
    BOOST_TEST(packetBuffer.get());
}
BOOST_AUTO_TEST_CASE(BufferReserveExceedingSpaceTest)
{
    BufferManager bufferManager(1, 512);
    unsigned int reservedSize = 0;
    // Cannot reserve buffer bigger than maximum buffer size
    auto reservedBuffer = bufferManager.Reserve(1024, reservedSize);
    BOOST_TEST(reservedSize == 0);
    BOOST_TEST(!reservedBuffer.get());
}
BOOST_AUTO_TEST_CASE(BufferExhaustionTest)
{
    BufferManager bufferManager(1, 512);
    unsigned int reservedSize = 0;
    auto packetBuffer = bufferManager.Reserve(512, reservedSize);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize == 512);
    BOOST_TEST(packetBuffer.get());
    // Cannot reserve buffer when buffer is not available
    auto reservedBuffer = bufferManager.Reserve(512, reservedSize);
    BOOST_TEST(reservedSize == 0);
    BOOST_TEST(!reservedBuffer.get());
}
BOOST_AUTO_TEST_CASE(BufferReserveMultipleTest)
{
    BufferManager bufferManager(3, 512);
    unsigned int reservedSize0 = 0;
    auto packetBuffer0 = bufferManager.Reserve(512, reservedSize0);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize0 == 512);
    BOOST_TEST(packetBuffer0.get());
    unsigned int reservedSize1 = 0;
    auto packetBuffer1 = bufferManager.Reserve(128, reservedSize1);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize1 == 128);
    BOOST_TEST(packetBuffer1.get());
    unsigned int reservedSize2 = 0;
    auto packetBuffer2 = bufferManager.Reserve(512, reservedSize2);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize2 == 512);
    BOOST_TEST(packetBuffer2.get());
    // Cannot reserve when buffer is not available
    unsigned int reservedSize3 = 0;
    auto reservedBuffer = bufferManager.Reserve(512, reservedSize3);
    BOOST_TEST(reservedSize3 == 0);
    BOOST_TEST(!reservedBuffer.get());
}
BOOST_AUTO_TEST_CASE(BufferReleaseTest)
{
    BufferManager bufferManager(2, 512);
    unsigned int reservedSize0 = 0;
    auto packetBuffer0 = bufferManager.Reserve(512, reservedSize0);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize0 == 512);
    BOOST_TEST(packetBuffer0.get());
    unsigned int reservedSize1 = 0;
    auto packetBuffer1 = bufferManager.Reserve(128, reservedSize1);
    // Successfully reserved the buffer with requested size
    BOOST_TEST(reservedSize1 == 128);
    BOOST_TEST(packetBuffer1.get());
    // Cannot reserve when buffer is not available
    unsigned int reservedSize2 = 0;
    auto reservedBuffer = bufferManager.Reserve(512, reservedSize2);
    BOOST_TEST(reservedSize2 == 0);
    BOOST_TEST(!reservedBuffer.get());
    bufferManager.Release(packetBuffer0);
    // Buffer should become available after release
    auto packetBuffer2 = bufferManager.Reserve(128, reservedSize2);
    BOOST_TEST(reservedSize2 == 128);
    BOOST_TEST(packetBuffer2.get());
}
BOOST_AUTO_TEST_CASE(BufferCommitTest)
{
    BufferManager bufferManager(2, 512);
    unsigned int reservedSize0 = 0;
    auto packetBuffer0 = bufferManager.Reserve(512, reservedSize0);
    BOOST_TEST(reservedSize0 == 512);
    BOOST_TEST(packetBuffer0.get());
    unsigned int reservedSize1 = 0;
    auto packetBuffer1 = bufferManager.Reserve(128, reservedSize1);
    BOOST_TEST(reservedSize1 == 128);
    BOOST_TEST(packetBuffer1.get());
    unsigned int reservedSize2 = 0;
    auto reservedBuffer = bufferManager.Reserve(512, reservedSize2);
    BOOST_TEST(reservedSize2 == 0);
    BOOST_TEST(!reservedBuffer.get());
    bufferManager.Commit(packetBuffer0, 256);
    // Buffer should become readable after commit
    auto packetBuffer2 = bufferManager.GetReadableBuffer();
    BOOST_TEST(packetBuffer2.get());
    BOOST_TEST(packetBuffer2->GetSize() == 256);
    // Buffer not set back to available list after commit
    unsigned int reservedSize = 0;
    reservedBuffer = bufferManager.Reserve(512, reservedSize);
    BOOST_TEST(reservedSize == 0);
    BOOST_TEST(!reservedBuffer.get());
}
BOOST_AUTO_TEST_CASE(BufferMarkReadTest)
{
    BufferManager bufferManager(2, 512);
    unsigned int reservedSize0 = 0;
    auto packetBuffer0 = bufferManager.Reserve(512, reservedSize0);
    BOOST_TEST(reservedSize0 == 512);
    BOOST_TEST(packetBuffer0.get());
    unsigned int reservedSize1 = 0;
    auto packetBuffer1 = bufferManager.Reserve(128, reservedSize1);
    BOOST_TEST(reservedSize1 == 128);
    BOOST_TEST(packetBuffer1.get());
    // Cannot reserve when buffer is not available
    unsigned int reservedSize2 = 0;
    auto reservedBuffer = bufferManager.Reserve(512, reservedSize2);
    BOOST_TEST(reservedSize2 == 0);
    BOOST_TEST(!reservedBuffer.get());
    bufferManager.Commit(packetBuffer0, 256);
    // Buffer should become readable after commit
    auto packetBuffer2 = bufferManager.GetReadableBuffer();
    BOOST_TEST(packetBuffer2.get());
    BOOST_TEST(packetBuffer2->GetSize() == 256);
    // Buffer not set back to available list after commit
    reservedBuffer = bufferManager.Reserve(512, reservedSize2);
    BOOST_TEST(reservedSize2 == 0);
    BOOST_TEST(!reservedBuffer.get());
    bufferManager.MarkRead(packetBuffer2);
    //Buffer should set back to available list after marked read and can be reserved
    auto readBuffer = bufferManager.GetReadableBuffer();
    BOOST_TEST(!readBuffer);
    unsigned int reservedSize3 = 0;
    auto packetBuffer3 = bufferManager.Reserve(56, reservedSize3);
    BOOST_TEST(reservedSize3 == 56);
    BOOST_TEST(packetBuffer3.get());
}
BOOST_AUTO_TEST_SUITE_END()

#include "UEBoidManager.h"
#include "Components/BrushComponent.h"
#include "UEBoids.h"
#include "Runtime\Core\Public\Math\Box.h"
#include "Runtime\Engine\Classes\Kismet\KismetMathLibrary.h"
#include "Runtime/Engine/Classes/Components/InstancedStaticMeshComponent.h"
ABoidManager::ABoidManager(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	PrimaryActorTick.bCanEverTick = true;
	SetActorTickEnabled(true);
	myMeshComponent = CreateDefaultSubobject<UInstancedStaticMeshComponent>(TEXT("myMeshComponent"));
	myMeshComponent->SetupAttachment(RootComponent);
	GetBrushComponent()->Mobility = EComponentMobility::Static;
	BrushColor = FColor(255, 255, 255, 255);
	bColored = true;
}
ABoidManager::~ABoidManager()
{
	myBoidData.Empty();
}
void ABoidManager::BeginPlay()
{
	Super::BeginPlay();
	myMeshComponent->SetStaticMesh(myMesh);
	myBoidData.Reserve(myParameters.myNumBoids);
	myBounds = GetComponentsBoundingBox(false);
	myAABBMin = myBounds.GetCenter() - myBounds.GetExtent();
	myAABBMax = myBounds.GetCenter() + myBounds.GetExtent();
	for (int i = 0; i < myParameters.myNumBoids; i++)
	{
		int index = myBoidData.Emplace();
		BoidData& data = myBoidData[index];

		data.myPosition = (FMath::RandPointInBox(GetComponentsBoundingBox(true)) / GetTransform().GetScale3D());
		data.myVelocity = FVector(FMath::VRand());
		FTransform tx;
		tx.SetLocation(data.myPosition);
		tx.SetScale3D(FVector(myMeshScale));
		myMeshComponent->AddInstance(tx);
	}
	myParameters.Update();
}
void ABoidManager::Tick(float DeltaSeconds)
{
	Super::Tick(DeltaSeconds);
	int i = 0;
	for (BoidData& data : myBoidData)
	{
		FVector meanPos(0.f);
		FVector meanVel(0.f);
		FVector avoidance(0.f);
		int numInCohesionRange = 0;
		int numInAlignRange = 0;
		int j = 0;
		for (const BoidData& innerBoid : myBoidData)
		{
			if (i != j)
			{
				float dist2 = FVector::DistSquared(data.myPosition, innerBoid.myPosition);
				// Calculate our values for Cohesion, Avoidance, and Alignment
				// For Cohesion, we need the mean position of nearby boids
				if (dist2 < myParameters.myCohesionRange2)
				{
					meanPos += innerBoid.myPosition;
					numInCohesionRange++;
				}
				// For avoidance, we add a vector pointing away from any nearby boids in range
				if (dist2 < (myParameters.myAvoidRange2))
				{
					avoidance +=  data.myPosition - innerBoid.myPosition;
				}
				// For alignment, we need the mean velocity of nearby boids
				if (dist2 < (myParameters.myAlignRange2))
				{
					meanVel += innerBoid.myVelocity;
				}

			}
			++j;
		}
		// Coherence is a vector pointing from current pos towards the mean position of other boids within range
		if(numInCohesionRange)
			meanPos /= numInCohesionRange;
		FVector coherence = (meanPos - data.myPosition) * myParameters.myCohesionWeight;
		if (numInAlignRange)
			meanVel /= numInAlignRange;
		FVector alignment = meanVel * myParameters.myAlignWeight;
		// Calculate bounds vector, push us back inside the volume if we leave it
		FVector bounds(0.f);
		if (data.myPosition.X < myAABBMin.X) {
			bounds.X = myParameters.myAvoidBoundsWeight;
		} else if (data.myPosition.X > myAABBMax.X) {
			bounds.X = -myParameters.myAvoidBoundsWeight;
		}
		if (data.myPosition.Y < myAABBMin.Y) {
			bounds.Y = myParameters.myAvoidBoundsWeight;
		} else if (data.myPosition.Y > myAABBMax.Y) {
			bounds.Y = -myParameters.myAvoidBoundsWeight;
		}
		if (data.myPosition.Z < myAABBMin.Z) {
			bounds.Z = myParameters.myAvoidBoundsWeight;
		} else if (data.myPosition.Z > myAABBMax.Z) {
			bounds.Z = -myParameters.myAvoidBoundsWeight;
		}
		bounds *= myParameters.myAvoidBoundsWeight;
		// Add up the component vectors, and Lerp towards to the new velocity to keep things smooth.
		data.myVelocity = FMath::Lerp(data.myVelocity, (data.myVelocity + (coherence + avoidance + alignment + bounds)).GetClampedToMaxSize(myParameters.myVelocityMax), DeltaSeconds * 10.f);
		data.myPosition += data.myVelocity * DeltaSeconds;
		// Calculate instance transform. Probably a more efficient way to calculate rotation here?
		FTransform tx; 
		myMeshComponent->GetInstanceTransform(i, tx);
		FQuat lookAtRotator = FRotationMatrix::MakeFromX(data.myVelocity).ToQuat();
		tx.SetRotation(lookAtRotator);
		tx.SetLocation(data.myPosition);
		// Apply the new transform
		myMeshComponent->UpdateInstanceTransform(i, tx, false, i == myBoidData.Num() - 1, true);
		++i;
	}
}

#include "types.h"
#include <3ds.h>
#include "csvc.h"
#include "CTRPluginFrameworkImpl/Graphics.hpp"
#include "CTRPluginFrameworkImpl/System.hpp"
#include "CTRPluginFrameworkImpl/Preferences.hpp"
#include "CTRPluginFramework/System/System.hpp"
#include "CTRPluginFramework/Utils/Utils.hpp"
#include "CTRPluginFramework/Graphics/OSD.hpp"
namespace CTRPluginFramework
{
    using namespace CTRPluginFrameworkImpl::Services;
    #define REG(x)          *(vu32 *)(x)
    #define REG32(x)        *(vu32 *)((x) | (1u << 31))
    #define LCDREG(offset)  REG(this->_LCDSetup + offset)
    struct ScreensFramebuffers
    {
        u8  topFramebuffer0[400 * 240 * 2];
        u8  topFramebuffer1[400 * 240 * 2];
        u8  bottomFramebuffer0[320 * 240 * 2];
        u8  bottomFramebuffer1[320 * 240 * 2];
    } PACKED;
    // Reserve the place for the Screen objects
    static u8  _topBuf[sizeof(ScreenImpl)] ALIGN(4);
    static u8  _botBuf[sizeof(ScreenImpl)] ALIGN(4);
    ScreenImpl  *ScreenImpl::Top = nullptr;
    ScreenImpl  *ScreenImpl::Bottom = nullptr;
    u32 GetBPP(GSPGPU_FramebufferFormat format)
    {
        switch(format)
        {
            case GSP_RGBA8_OES:
                return 4;
            case GSP_BGR8_OES:
                return 3;
            case GSP_RGB565_OES:
            case GSP_RGB5_A1_OES:
            case GSP_RGBA4_OES:
                return 2;
        }
        return 3;
    }
    ScreenImpl::ScreenImpl(const u32 lcdSetupInfo, const u32 fillColorAddress, const bool isTopScreen) :
        _LCDSetup(lcdSetupInfo),
        _FillColor(fillColorAddress),
        _backlightOffset{isTopScreen ? 0x40u : 0x840u},
        _currentBuffer(0),
        _width(isTopScreen ? 400 : 320),
        _stride(0), _rowSize(0), _bytesPerPixel(0),
        _isTopScreen(isTopScreen), _format()
    {
    }
    void    ScreenImpl::Initialize(void)
    {
        auto *screensFbs = reinterpret_cast<ScreensFramebuffers *>(FwkSettings::Header->heapVA);
        Top = new (_topBuf) ScreenImpl(0x10400400 | (1u << 31), (0x10202000 | (1u << 31)) + 0x204, true);
        Bottom = new (_botBuf) ScreenImpl(0x10400500 | (1u << 31), (0x10202000 | (1u << 31)) + 0xA04);
        // Top screen
        GSP::FrameBufferInfo* fb = &Top->_frameBufferInfo.fbInfo[0];
        fb->active_framebuf = 0;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(screensFbs->topFramebuffer0);
        fb->framebuf1_vaddr = fb->framebuf0_vaddr;
        fb->framebuf_widthbytesize = 240 * 2; // Enforce RGB565
        fb->format = 0x42; // GSP_RGB565_OES;
        fb->framebuf_dispselect = 0;
        fb = &Top->_frameBufferInfo.fbInfo[1];
        fb->active_framebuf = 1;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(screensFbs->topFramebuffer1);
        fb->framebuf1_vaddr = fb->framebuf0_vaddr;
        fb->framebuf_widthbytesize = 240 * 2; // Enforce RGB565
        fb->format = 0x42; // GSP_RGB565_OES;
        fb->framebuf_dispselect = 1;
        // Bottom screen
        fb = &Bottom->_frameBufferInfo.fbInfo[0];
        fb->active_framebuf = 0;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(screensFbs->bottomFramebuffer0);
        fb->framebuf1_vaddr = nullptr;
        fb->framebuf_widthbytesize = 240 * 2; // Enforce RGB565
        fb->format = GSP_RGB565_OES;
        fb->framebuf_dispselect = 0;
        fb = &Bottom->_frameBufferInfo.fbInfo[1];
        fb->active_framebuf = 1;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(screensFbs->bottomFramebuffer1);
        fb->framebuf1_vaddr = nullptr;
        fb->framebuf_widthbytesize = 240 * 2; // Enforce RGB565
        fb->format = GSP_RGB565_OES;
        fb->framebuf_dispselect = 1;
    }
    void    ScreenImpl::ApplyCtrpfScreens(void)
    {
            Top->_frameBufferInfo.header.screen = Top->_currentBuffer;
            Bottom->_frameBufferInfo.header.screen = Bottom->_currentBuffer;
            GSP::SetFrameBufferInfo(Top->_frameBufferInfo, 0, true);
            GSP::SetFrameBufferInfo(Bottom->_frameBufferInfo, 1, true);
    }
    void    ScreenImpl::Fade(const float fade)
    {
        const u32   size = GetFrameBufferSize() / _bytesPerPixel;
        u8         *frameBuf = GetLeftFrameBuffer();
        PrivColor::SetFormat(_format);
        for (int i = size; i > 0; --i)
        {
            frameBuf = PrivColor::ToFramebuffer(frameBuf, PrivColor::FromFramebuffer(frameBuf).Fade(fade));
        }
    }
    u32     ScreenImpl::Acquire(bool fade)
    {
        // Fetch game frame buffers & check validity
        if (ImportFromGsp())
            return -1;
        // Copy images and convert to RGB565 to ctrpf's frame buffer (0)
        _frameBufferInfo.FillFrameBuffersFrom(_gameFrameBufferInfo);
        _format = GSP_RGB565_OES;
        _stride = 240*2;
        _bytesPerPixel = 2;
        _rowSize = 240;
        auto &fbInfo = _frameBufferInfo.fbInfo;
        _leftFrameBuffers[0] = reinterpret_cast<u32>(fbInfo[0].framebuf0_vaddr);
        _leftFrameBuffers[1] = reinterpret_cast<u32>(fbInfo[1].framebuf0_vaddr);
        _rightFrameBuffers[0] = reinterpret_cast<u32>(fbInfo[0].framebuf1_vaddr);
        _rightFrameBuffers[1] = reinterpret_cast<u32>(fbInfo[1].framebuf1_vaddr);
        // Set fb1 as current
        _currentBuffer = _frameBufferInfo.header.screen = 1;
        // Apply fade to fb0
        if (fade)
            Fade(0.3f);
        // Copy to fb1
        _currentBuffer = 0;
        Copy();
        // Flush fb0
        _currentBuffer = 1;
        Flush();
        // Apply current frame buffers
        GSP::SetFrameBufferInfo(_frameBufferInfo, !_isTopScreen, true);
        _isGspAcquired = true;
        return 0;
    }
    u32     ScreenImpl::ImportFromGsp(void)
    {
        // GSP screens are plugin screens, so don't fetch
        if (_isGspAcquired)
            return 0;
        // Fetch game frame buffers
        if (GSP::ImportFrameBufferInfo(_gameFrameBufferInfo, !_isTopScreen))
            return -1;
        // Check frame buffers validity
        const u32 displayed = _gameFrameBufferInfo.header.screen;
        if (!Process::CheckAddress(reinterpret_cast<u32>(_gameFrameBufferInfo.fbInfo[displayed].framebuf0_vaddr)))
            return -1;
        return 0;
    }
    void    ScreenImpl::Release(void)
    {
        GSP::SetFrameBufferInfo(_gameFrameBufferInfo, !_isTopScreen, false);
        _isGspAcquired = false;
    }
    void    ScreenImpl::Acquire(u32 left, u32 right, u32 stride, u32 format, bool backup)
    {
        _currentBuffer = 1;
        _format = static_cast<GSPGPU_FramebufferFormat>(format & 7);
        _stride = stride;
        _bytesPerPixel = GetBPP(_format);
        _rowSize = _stride / _bytesPerPixel;
        _leftFrameBuffers[0] = left;
        _rightFrameBuffers[0] = right;
        _gameFrameBufferInfo.header.screen = 0;
        GSP::FrameBufferInfo& fbInfo = _gameFrameBufferInfo.fbInfo[0];
        fbInfo.active_framebuf = 0;
        fbInfo.framebuf0_vaddr = reinterpret_cast<u32 *>(left);
        fbInfo.framebuf1_vaddr = reinterpret_cast<u32 *>(right);
        fbInfo.framebuf_widthbytesize = stride;
        fbInfo.format = format;
        fbInfo.framebuf_dispselect = 0;
    }
    void    ScreenImpl::Flush(void)
    {
        u32 size = GetFrameBufferSize();
        // Flush currentBuffer
        svcFlushProcessDataCache(CUR_PROCESS_HANDLE, (u32)GetLeftFrameBuffer(), size);
    }
    void    ScreenImpl::Invalidate(void)
    {
        u32 size = GetFrameBufferSize();
        // Invalidate currentBuffer
        svcInvalidateProcessDataCache(CUR_PROCESS_HANDLE, (u32)GetLeftFrameBuffer(), size);
    }
    void    ScreenImpl::Clear(bool applyFlagForCurrent)
    {
        const u32 displayed = _gameFrameBufferInfo.header.screen;
        _frameBufferInfo.fbInfo[!_currentBuffer].FillFrameBufferFrom(_gameFrameBufferInfo.fbInfo[displayed]);
        Fade(0.3f);
        if (!applyFlagForCurrent)
            return;
        s32 val = GSP::__ldrex__(&GSP::BufferFlags);
        val |= (_isTopScreen ? GSP::FB_TOP_NEED_CLEAR : GSP::FB_BOTTOM_NEED_CLEAR);
        GSP::__strex__(&GSP::BufferFlags, val);
    }
    void    ScreenImpl::Copy(void)
    {
        u32 size = GetFrameBufferSize();
        u8 *dst = GetLeftFrameBuffer();
        u8 *src = GetLeftFrameBuffer(true);
        std::copy(src, src + size, dst);
    }
