#include "CMemoryHub.h"
#include <memory.h>
#include "HAtomicOperator.h"
namespace app {
CMemoryHub::CMemoryHub() :
    mReferenceCount(1) {
    setPageCount(16);
}
CMemoryHub::~CMemoryHub() {
    APP_ASSERT(0 == mReferenceCount);
}
void CMemoryHub::grab() {
    APP_ASSERT(mReferenceCount > 0);
    AppAtomicIncrementFetch(&mReferenceCount);
}
void CMemoryHub::drop() {
    s32 ret = AppAtomicDecrementFetch(&mReferenceCount);
    APP_ASSERT(ret >= 0);
    if(0 == ret) {
        delete this;
    }
}
void CMemoryHub::setPageCount(s32 cnt) {
    mPool128.setPageSize(128 * cnt);
    mPool512.setPageSize(512 * cnt);
    mPool2048.setPageSize(2048 * cnt);
    mPool8192.setPageSize(8192 * cnt);
    mPool10K.setPageSize(10240 * cnt);
}
s8* CMemoryHub::allocateAndClear(u64 bytesWanted, u64 align/* = sizeof(void*)*/) {
    s8* ret = allocate(bytesWanted, align);
    memset(ret, 0, bytesWanted);
    return ret;
}
s8* CMemoryHub::allocate(u64 bytesWanted, u64 align/* = sizeof(void*)*/) {
#if defined(APP_DEBUG)
    grab();
#endif
    align = align < sizeof(SMemHead) ? sizeof(SMemHead) : align;
    bytesWanted += align;
    bytesWanted = APP_ALIGN_DATA(bytesWanted, align);
#ifdef APP_DISABLE_BYTE_POOL
    return malloc(bytesWanted);
#endif
    s8* out;
    if(bytesWanted <= 128) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.lock();
#endif
        out = (s8*) mPool128.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.unlock();
#endif
        return getUserPointer(out, align, EMT_128);
    }
    if(bytesWanted <= 512) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.lock();
#endif
        out = (s8*) mPool512.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.unlock();
#endif
        return getUserPointer(out, align, EMT_512);
    }
    if(bytesWanted <= 2048) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.lock();
#endif
        out = (s8*) mPool2048.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.unlock();
#endif
        return getUserPointer(out, align, EMT_2048);
    }
    if(bytesWanted <= 8192) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.lock();
#endif
        out = (s8*) mPool8192.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.unlock();
#endif
        return getUserPointer(out, align, EMT_8192);
    }
    if(bytesWanted <= 10240) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.lock();
#endif
        out = (s8*) mPool10K.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.unlock();
#endif
        return getUserPointer(out, align, EMT_10K);
    }
    out = (s8*) ::malloc(bytesWanted + 1);
    return getUserPointer(out, align, EMT_DEFAULT);
}
void CMemoryHub::release(void* data) {
    if(!data) {
        return;
    }
#if defined(APP_DEBUG)
    drop();
#endif
#ifdef APP_DISABLE_BYTE_POOL
    ::free(data);
#endif
    s8* realData;
    switch(getRealPointer(data, realData)) {
    case EMT_128:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.lock();
#endif
        mPool128.release((u8(*)[128]) realData);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.unlock();
#endif
        break;
    case EMT_512:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.lock();
#endif
        mPool512.release((u8(*)[512]) realData);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.unlock();
#endif
        break;
    case EMT_2048:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.lock();
#endif
        mPool2048.release((u8(*)[2048]) realData);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.unlock();
#endif
        break;
    case EMT_8192:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.lock();
#endif
        mPool8192.release((u8(*)[8192]) realData);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.unlock();
#endif
        break;
    case EMT_10K:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.lock();
#endif
        mPool10K.release((u8(*)[10240]) realData);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.unlock();
#endif
        break;
    case EMT_DEFAULT:
        ::free(realData);
        break;
    default:
        APP_ASSERT(0);
        break;
    }
}
void CMemoryHub::clear() {
#ifdef APP_THREADSAFE_MEMORY_POOL
    mPool128.clear();
    mPool512.clear();
    mPool2048.clear();
    mPool8192.clear();
    mPool10K.clear();
#endif //APP_THREADSAFE_MEMORY_POOL
}
