        PyObject *lst = PyList_New(data.n_rows());
        for(int i=0;i<data.n_rows();i++){
            PyObject *row = PyList_New(data.n_cols());
            for(int j=0;j<data.n_cols();j++){
                PyList_SET_ITEM(row, j, PyFloat_FromDouble(data(i,j)));
