void resize_Chain_Data(Chain_Data* x, long long size)
{
	if (size + 1 > x->size) {
		x->size = size + 1;
		kroundup64(x->size);
		REALLOC(x->score, x->size);
		REALLOC(x->pre, x->size);
		REALLOC(x->indels, x->size);
		REALLOC(x->self_length, x->size);
        REALLOC(x->occ, x->size);
		REALLOC(x->tmp, x->size);
	}
}
