void dr_cuda_backward_batch(at::Tensor grad_sino_bxhxwxd,
        at::Tensor image_bxhxwxd, at::Tensor imidx_vf,
        at::Tensor cntvisible_bxhxwx1, at::Tensor firstidx_bxhxwx1,
