// ---------------------- FilePacket --------------------
// constructor from data
// serialization
FilePacket::FilePacket(uint32_t id, int flag, int derived_size, uint32_t fd, uint32_t file_id, 
 uint32_t stripe_id, uint32_t chunk_num, uint32_t offset, int32_t count) 
 : Packet(id, flag, derived_size + data_size),
   fd(fd),
   file_id(file_id),
   stripe_id(stripe_id),
   chunk_num(chunk_num),
   offset(offset),
   count(count) {
  uint32_t* base = (uint32_t*)(((uint8_t*)packet) + Packet::dataSize());
  base[0] = fd;
  base[1] = file_id;
  base[2] = stripe_id;
  base[3] = chunk_num;
  base[4] = offset;
  base[5] = count;
}
// constructor from a buffer 
// deserialization
FilePacket::FilePacket(void* buf, ssize_t size) : Packet(buf, size) {
  uint32_t* base = (uint32_t*)(((uint8_t*)buf) + Packet::dataSize());
  fd = base[0];
  file_id = base[1];
  stripe_id = base[2];
  chunk_num = base[3];
  offset = base[4];
  count = base[5];
}
