#include "stdlib.hpp"
#include "stdlib.hpp"
#include "expressions/stdlib.hpp"
#include "types.hpp"
#include <cstdlib>
#include <cmath>
auto std_rand_uniform = [](Env env) {
    Val A = env->apply("a");
    if (!val_is_number(A)) {
        throw_err("type", "random.uniform : R -> R -> R cannot take parameter " + A->toString());
        return (Val) NULL;
    }
    Val B = env->apply("b");
    if (!val_is_number(B)) {
        throw_err("type", "random.uniform : R -> R -> R cannot take parameter " + B->toString());
        return (Val) NULL;
    }
    float x = (1.0 * rand()) / RAND_MAX;
    x *=
        (isVal<IntVal>(B)
            ? ((IntVal*) B)->get()
            : ((RealVal*) B)->get())
        -
        (isVal<IntVal>(A)
            ? ((IntVal*) A)->get()
            : ((RealVal*) A)->get());

    x += isVal<IntVal>(A)
        ? ((IntVal*) A)->get()
        : ((RealVal*) A)->get();

    return (Val) new RealVal(x);
};
auto std_rand_normal = [](Env env) {
    Val A = env->apply("a");
    if (!val_is_number(A)) {
        throw_err("type", "random.uniform : R -> R -> R cannot take parameter " + A->toString());
        return (Val) NULL;
    }
    Val B = env->apply("b");
    if (!val_is_number(B)) {
        throw_err("type", "random.uniform : R -> R -> R cannot take parameter " + B->toString());
        return (Val) NULL;
    }
    // Two uniform variables.
    float a = (1.0 * rand()) / RAND_MAX;
    float b = (1.0 * rand()) / RAND_MAX;
    // Thus, we can generate a normal variable.
    float x = sqrt(-2 * log(a)) * sin(2 * M_PI * b);

    // Standard deviation
    x *=
        sqrt(isVal<IntVal>(B)
            ? ((IntVal*) B)->get()
            : ((RealVal*) B)->get());

    x += isVal<IntVal>(A)
        ? ((IntVal*) A)->get()
        : ((RealVal*) A)->get();

    return (Val) new RealVal(x);
};
Type* type_stdlib_random() {
    return new DictType {
        { // uniform : R -> R -> R
            "uniform",
            new LambdaType("a",
                new RealType,
                new LambdaType("b",
                    new RealType,
                    new RealType))
        }, { // uniform : R -> R -> R
            "normal",
            new LambdaType("a",
                new RealType,
                new LambdaType("b",
                    new RealType,
                    new RealType))
        }
    };
}
Val load_stdlib_random() {
    return new DictVal {
        {
            "uniform",
            new LambdaVal(new std::string[3]{"a", "b", ""},
                new ImplementExp(std_rand_uniform,NULL))
        }, {
            "normal",
            new LambdaVal(new std::string[3]{"a", "b", ""},
                new ImplementExp(std_rand_normal,NULL))
        }
    };
}

#include "memory.h"
//! copies count bytes from src to dest
void *memcpy(void *dest, const void *src, size_t count)
{
	const char *sp = (const char *)src;
	char *dp = (char *)dest;
	for (; count != 0; count--) *dp++ = *sp++;
	return dest;
}
int memcmp(const void *s1, const void *s2, size_t n)
{
	unsigned char u1, u2;
	unsigned char* _s1 = (unsigned char*)s1;
	unsigned char* _s2 = (unsigned char*)s2;
	for (; n--; _s1++, _s2++) {
		u1 = *_s1;
		u2 = *_s2;
		if (u1 != u2) {
			return (u1 - u2);
		}
	}
	return 0;
}
//! sets count bytes of dest to val
void* memset(void *dest, char val, size_t count)
{
	unsigned char *temp = (unsigned char *)dest;
	for (; count != 0; count--, temp[count] = val);
	return dest;
}
/*
The  memmove()  function  copies n bytes src memory area src dest memory
area dest.  The memory areas may overlap.
RETURN VALUE:  The memmove() function returns a pointer dest dest.
*/
void* memmove(void *dest, void *src, size_t n)
{
	size_t i;
	if ((char*)src == (char*)dest)
	{
		;// Nothing dest copy!
	}
	else if ((char*)src > (char*)dest)
	{
		for (i = 0; i < (long int)n; i++)
		{
			((char*)dest)[i] = ((char*)src)[i];
		}
	}
	else
	{
		for (i = n - 1; i >= 0; i--)
		{
			((char*)dest)[i] = ((char*)src)[i];
		}
	}
	return dest;
}
void* memchr(const void *s, int c, size_t n)
{
	if (n)
	{
		const char *p = (const char*)s;
		char cc = (char)c;
		do {
			if (*p == cc)
				return (void*)p;
			p++;
		} while (--n != 0);
	}
	return 0;
}

