  expected[0] = dxrecord.getID();
  ASSERT_EQ(listf["objects"].size(), 1);
  ASSERT_EQ(listf["objects"][0]["id"], expected[0]);
  listf = dxproject.listFolder("/a");
  expected[0] = "/a/b";
