  listf = dxproject.listFolder("/a/b");
  expected[0] = "/a/b/c";
  ASSERT_EQ(listf["folders"], expected);
  listf = dxproject.listFolder("/a/b/c");
  expected[0] = "/a/b/c/d";
  ASSERT_EQ(listf["folders"], expected);
  listf = dxproject.listFolder("/a/b/c/d");
  ASSERT_EQ(listf["folders"], JSON(JSON_ARRAY));
