void Representador::dibujar_hud(DLibV::Pantalla& pantalla, const DLibV::Fuente_TTF& f, const std::string& cad_tiempo, bool aviso_tiempo, int max_vel, int act_vel, int tot_vel)
{
	auto color=aviso_tiempo ? SDL_Color{255, 32, 32, 255} : SDL_Color{255, 255, 255, 255};
	DLibV::Representacion_TTF txt(f, color, cad_tiempo);
	txt.ir_a(16, 70);
	txt.volcar(pantalla);
	DLibV::Representacion_bitmap sprite(DLibV::Gestor_texturas::obtener(r_graficos::g_hud));
	sprite.establecer_modo_blend(DLibV::Representacion::BLEND_ALPHA);
	auto fd=[&pantalla, &sprite](int& act, int max, int xrec, int alpha)
	{
		sprite.establecer_recorte(xrec, 0, 31, 40);
		sprite.establecer_alpha(alpha);
		while(act <= max)
		{
			sprite.establecer_posicion( (act * 33) + 16 , 16, 31, 40);
			sprite.volcar(pantalla);
			++act;
		}
	};
	//Primero la velocidad actual...
	sprite.establecer_recorte(31, 0, 31, 40);
	sprite.establecer_alpha(255);
	int xvel=0;
	//Marcando velocidad actual...
	fd(xvel, act_vel, 31, 255);
	//Aviso de 
	if(aviso_velocidad_minima.tiempo && xvel <= aviso_velocidad_minima.velocidad) 
	{
		int alpha=int( (aviso_velocidad_minima.tiempo * 255) / 1.2f);
		int cp=xvel;
		fd(cp, aviso_velocidad_minima.velocidad, 62, alpha < 128 ? 128 : alpha);
	}
	if(xvel <= max_vel) fd(xvel, max_vel, 0, 128);
	if(xvel <= tot_vel) fd(xvel, tot_vel, 93, 128);
}
void Representador::turno(float delta)
{
	if(aviso_velocidad_minima.tiempo)
	{
		aviso_velocidad_minima.tiempo-=delta;
		if(aviso_velocidad_minima.tiempo < 0.0f) aviso_velocidad_minima.tiempo=0.0f;
	}
}
void Representador::avisar_velocidad_minima(int vel)
{
	aviso_velocidad_minima={vel, 1.2f};
}

#include "reduction_utils.hpp"
#include <CL/sycl.hpp>
#include <cassert>
using namespace cl::sycl;
template <typename T, bool B> class KName;
template <int Dims>
std::ostream &operator<<(std::ostream &OS, const range<Dims> &Range) {
  OS << "{" << Range[0];
  if constexpr (Dims > 1)
    OS << ", " << Range[1];
  if constexpr (Dims > 2)
    OS << ", " << Range[2];
  OS << "}";
  return OS;
}
template <typename Name, bool IsSYCL2020Mode, access::mode Mode, typename T,
          int AccDim = 1, class BinaryOperation, int Dims>
void test(queue &Q, T Identity, T Init, BinaryOperation BOp,
          range<Dims> Range) {
  std::string StdMode = IsSYCL2020Mode ? "SYCL2020" : "ONEAPI  ";
  std::cout << "Running the test case: " << StdMode
            << " {T=" << typeid(T).name()
            << ", BOp=" << typeid(BinaryOperation).name() << ", Range=" << Range
            << std::endl;
  // Skip the test for such big arrays now.
  constexpr size_t TwoGB = 2LL * 1024 * 1024 * 1024;
  if (Range.size() > TwoGB)
    return;
  buffer<T, Dims> InBuf(Range);
  buffer<T, 1> OutBuf(1);
  // Initialize.
  T CorrectOut;
  initInputData(InBuf, CorrectOut, Identity, BOp, Range);
  if constexpr (Mode == access::mode::read_write) {
    CorrectOut = BOp(CorrectOut, Init);
  }
  // The value assigned here must be discarded (if IsReadWrite is true).
  // Verify that it is really discarded and assign some value.
  (OutBuf.template get_access<access::mode::write>())[0] = Init;
  // Compute.
  if constexpr (IsSYCL2020Mode) {
    Q.submit([&](handler &CGH) {
      auto In = InBuf.template get_access<access::mode::read>(CGH);
      property_list PropList = getPropertyList<Mode>();
      auto Redu = sycl::reduction(OutBuf, CGH, Identity, BOp, PropList);
      CGH.parallel_for<Name>(
          Range, Redu, [=](id<Dims> Id, auto &Sum) { Sum.combine(In[Id]); });
    });
  } else {
    Q.submit([&](handler &CGH) {
      auto In = InBuf.template get_access<access::mode::read>(CGH);
      accessor<T, AccDim, Mode, access::target::global_buffer> Out(OutBuf, CGH);
      auto Redu = ext::oneapi::reduction(Out, Identity, BOp);
      CGH.parallel_for<Name>(
          Range, Redu, [=](id<Dims> Id, auto &Sum) { Sum.combine(In[Id]); });
    });
  }
  // Check correctness.
  auto Out = OutBuf.template get_access<access::mode::read>();
  T ComputedOut = *(Out.get_pointer());
  if (ComputedOut != CorrectOut) {
    printDeviceInfo(Q, true);
    std::cerr << "Error: Range = " << Range << ", "
              << "Computed value: " << ComputedOut
              << ", Expected value: " << CorrectOut << "\n";
    assert(0 && "Wrong value.");
  }
}
template <typename Name, access::mode Mode, typename T, class BinaryOperation,
          int Dims>
void testBoth(queue &Q, T Identity, T Init, BinaryOperation BOp,
              range<Dims> Range) {
  test<KName<Name, false>, false, Mode>(Q, Identity, Init, BOp, Range);
  test<KName<Name, true>, true, Mode>(Q, Identity, Init, BOp, Range);
}

void ExtensionServiceBackend::LoadSingleExtension(const FilePath& path_in) {
CHECK(BrowserThread::CurrentlyOn(BrowserThread::FILE));
FilePath extension_path = path_in;
file_util::AbsolutePath(&extension_path);
int flags = Extension::ShouldAlwaysAllowFileAccess(Extension::LOAD) ?
Extension::ALLOW_FILE_ACCESS : Extension::NO_FLAGS;
if (Extension::ShouldDoStrictErrorChecking(Extension::LOAD))
flags |= Extension::STRICT_ERROR_CHECKS;
std::string error;
scoped_refptr<const Extension> extension(extension_file_util::LoadExtension(
extension_path,
Extension::LOAD,
flags,
&error));
if (!extension) {
if (!BrowserThread::PostTask(
BrowserThread::UI, FROM_HERE,
NewRunnableMethod(
this,
&ExtensionServiceBackend::ReportExtensionLoadError,
extension_path, error)))
NOTREACHED() << error;
return;
}
// Report this as an installed extension so that it gets remembered in the
// prefs.
if (!BrowserThread::PostTask(
BrowserThread::UI, FROM_HERE,
NewRunnableMethod(
this,
              &ExtensionServiceBackend::OnExtensionInstalled,
extension)))
NOTREACHED();
}

