template<>
class frg::hash<guid_t> {
public:
    unsigned int operator() (const guid_t &guid) const {
        unsigned int hash = guid.d1;
        hash += 31 * hash + guid.d2;
        hash += 31 * hash + guid.d3;
        for(size_t i = 0; i < 8; i++) {
            hash += 31 * hash + guid.d4[i];
        }
        return hash;
    }
};
