#include <cstring>
#include <Utilities/memstream.h>
#include <Utilities/BigEndianIStream.h>
void NumToString(long theNum, Str255 theString)
{
	int rc = snprintf(theString+1, 254, "%ld", theNum);
	theString[0] = (rc < 0 || rc > 255) ? 0 : (unsigned char)rc;
}
int NumToStringC(long theNum, Str255 theString)
{
	return snprintf(theString, 256, "%ld", theNum);
}
void GetIndStringC(Str255 theStringC, short strListID, short index)
{
	theStringC[0] = '\0';
	Handle strListHandle = GetResource('STR#', strListID);
	if (!strListHandle)
		return;
	memstream substream(*strListHandle, GetHandleSize(strListHandle));
	Pomme::BigEndianIStream f(substream);
	int16_t nStrings = f.Read<int16_t>();
	if (index > nStrings)		// index starts at 1, hence '>' rather than '>='
	{
		ReleaseResource(strListHandle);
		return;
	}
	// Skip to requested string
	uint8_t pstrlen = 0;
	for (int i = 1; i < index; i++)		// index starts at 1
	{
		pstrlen = f.Read<uint8_t>();
		f.Skip(pstrlen);
	}
	pstrlen = f.Read<uint8_t>();
	f.Read(theStringC, pstrlen);
	theStringC[pstrlen] = '\0';
	static_assert(sizeof(Str255) == 256);
	ReleaseResource(strListHandle);
}

import {UNDEFINED} from '../../../../src/ol/functions.js';
import {listen} from '../../../../src/ol/events.js';
import {shared as iconImageCache} from '../../../../src/ol/style/IconImageCache.js';
import IconImage from '../../../../src/ol/style/IconImage.js';
describe('ol.style.IconImageCache', function() {
  let originalMaxCacheSize;
  beforeEach(function() {
    iconImageCache.clear();
    originalMaxCacheSize = iconImageCache.maxCacheSize;
    iconImageCache.maxCacheSize_ = 4;
  });
  afterEach(function() {
    iconImageCache.maxCacheSize_ = originalMaxCacheSize;
    iconImageCache.clear();
  });
  describe('#expire', function() {
    it('expires images when expected', function() {
      let i, src, iconImage;
      for (i = 0; i < 4; ++i) {
        src = i + '';
        iconImage = new IconImage(null, src);
        iconImageCache.set(src, null, null, iconImage);
      }
      expect(iconImageCache.cacheSize_).to.eql(4);
      iconImageCache.expire();
      expect(iconImageCache.cacheSize_).to.eql(4);
      src = '4';
      iconImage = new IconImage(null, src);
      iconImageCache.set(src, null, null, iconImage);
      expect(iconImageCache.cacheSize_).to.eql(5);
      iconImageCache.expire(); // remove '0' and '4'
      expect(iconImageCache.cacheSize_).to.eql(3);
      src = '0';
      iconImage = new IconImage(null, src);
      listen(iconImage, 'change', UNDEFINED, false);
      iconImageCache.set(src, null, null, iconImage);
      expect(iconImageCache.cacheSize_).to.eql(4);
      src = '4';
      iconImage = new IconImage(null, src);
      listen(iconImage, 'change', UNDEFINED, false);
      iconImageCache.set(src, null, null, iconImage);
      expect(iconImageCache.cacheSize_).to.eql(5);
      // check that '0' and '4' are not removed from the cache
      iconImageCache.expire();
      expect(iconImageCache.get('0', null, null)).to.not.be(null);
      expect(iconImageCache.get('4', null, null)).to.not.be(null);
    });
  });
  describe('#setSize', function() {
    it('sets max cache size and expires cache', function() {
      let i, src, iconImage;
      for (i = 0; i < 3; ++i) {
        src = i + '';
        iconImage = new IconImage(null, src);
        iconImageCache.set(src, null, null, iconImage);
      }
      expect(iconImageCache.cacheSize_).to.eql(3);
      iconImageCache.setSize(2);
      expect(iconImageCache.maxCacheSize_).to.eql(2);
      expect(iconImageCache.cacheSize_).to.eql(2);
    });
  });
});

#include <iostream>
#include <vector>
#include "ds_stack.h"
Stack::Stack() {
  stack = std::vector<int>();
}
Stack::~Stack() {}
bool Stack::isEmpty() const {
  return stack == std::vector<int>();
}
int Stack::peek() const {
  if (!isEmpty()) {
    return stack.back();
  } else {
    throw std::out_of_range("The stack is empty");
  }
}
void Stack::push(int item) {
  stack.push_back(item);
}
int Stack::pop() {
  if (!isEmpty()) {
    auto back = stack.back();
    stack.pop_back();
    return back;
  } else {
    throw std::out_of_range("The stack is empty");
  }
}
int Stack::size() const {
  return stack.size();
}
void Stack::show() const {
  for (int i = 0; i < stack.size(); i++) {
    std::cout << stack[i] << " ";
  }
}
int main() {
  Stack s;
  // Output: true.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  s.push(1);
  s.push(2);
  s.push(3);
  // Output: false; 1 2 3; 3; 3.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  std::cout << "Peek: " << s.peek() << std::endl;
  s.pop();
  s.pop();
  // Output: fals; 1; 1; 1.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  std::cout << "Peek: " << s.peek() << std::endl;
  s.pop();
  // Output: true; ; 0.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  return 0;
}

