#include "ShaderImporter.h"
#include "EngineCore/Renderer/Material/Shader.h"
#include "RenderAPI/Interface/Shader.h"
namespace cube
{
	Resource* ShaderImporter::Import(SPtr<platform::File>& file, const FrameJsonValue& info)
	{
		uint64_t size = file->GetFileSize();
		char* rawData = (char*)malloc(size + 1);
		uint64_t readSize = 0;
		file->Read(rawData, size, readSize);
		rawData[size] = '\0';
		ShaderCompileDesc desc = GetCompileDesc(info);
		render::ShaderAttribute shaderInit;
		shaderInit.language = desc.language;
		shaderInit.type = desc.type;
		shaderInit.entryPoint = desc.entryPoint.c_str();
		shaderInit.code = rawData;
		Shader* shader = new Shader();
		shader->_LoadShader(mDevice, shaderInit);
		free(rawData);
		return shader;
	}
	ShaderCompileDesc ShaderImporter::GetCompileDesc(const FrameJsonValue& info)
	{
		using namespace render;
		ShaderCompileDesc desc;
		U8String language = info["language"].GetString();
		U8String type = info["type"].GetString();
		U8String entryPoint = info["entry_point"].GetString();
		if(language == "glsl") {
			desc.language = ShaderLanguage::GLSL;
		} else if(language == "hsls") {
			desc.language = ShaderLanguage::HLSL;
		} else if(language == "spir-v") {
			desc.language = ShaderLanguage::SPIRV;
		}
		if(type == "vertex") {
			desc.type = ShaderType::Vertex;
		} else if(type == "fragment") {
			desc.type = ShaderType::Pixel;
		} else if(type == "pixel") {
			desc.type = ShaderType::Pixel;
		} else if(type == "compute") {
			desc.type = ShaderType::Compute;
		}
		desc.entryPoint = entryPoint;
		return desc;
	}
} // namespace cube

#include "caf/detail/set_thread_name.hpp"
#include "caf/config.hpp"
#ifndef CAF_WINDOWS
#  include <pthread.h>
#endif // CAF_WINDOWS
#if defined(CAF_LINUX)
#  include <sys/prctl.h>
#elif defined(CAF_BSD) && !defined(CAF_NET_BSD)
#  include <pthread_np.h>
#endif // defined(...)
#include <thread>
#include <type_traits>
namespace caf::detail {
void set_thread_name(const char* name) {
  CAF_IGNORE_UNUSED(name);
#ifdef CAF_WINDOWS
  // nop
#else // CAF_WINDOWS
  static_assert(std::is_same<std::thread::native_handle_type, pthread_t>::value,
                "std::thread not based on pthread_t");
#  if defined(CAF_MACOS)
  pthread_setname_np(name);
#  elif defined(CAF_LINUX)
  prctl(PR_SET_NAME, name, 0, 0, 0);
#  elif defined(CAF_NET_BSD)
  pthread_setname_np(pthread_self(), name, NULL);
#  elif defined(CAF_BSD)
  pthread_set_name_np(pthread_self(), name);
#  endif // defined(...)
#endif   // CAF_WINDOWS
}
} // namespace caf::detail

