#include "wav.h"
#include "win32_file_io.h"
#include <stdlib.h>
#include <string.h>
#ifdef DEBUG
#include <assert.h>
#else
#define assert(x)
#endif
#define UNUSED_VAR(x) x
//
// Chunks fourcc
//
u32 constexpr kWavFourCC_RIFF = 'FFIR';
u32 constexpr kWavFourCC_DATA = 'atad';
u32 constexpr kWavFourCC_FMT  = ' tmf';
u32 constexpr kWavFourCC_WAVE = 'EVAW';
u32 constexpr kWavFourCC_XWMA = 'AMWX';
//
// Structs
//
struct wav_data_info
{
    u8 *StartOfBuffer = nullptr;
    size_t CurrentIndex = 0;
    size_t SizeOfBuffer = 0;
    b32 Error = false;
};
//
// Helper funtions
//
b32 IsEOF(wav_data_info *Data, u32 BytesToAdvance = 0)
{
    b32 Result = false;

    if (!Data->StartOfBuffer || ((Data->CurrentIndex + BytesToAdvance) > Data->SizeOfBuffer))
    {
        Data->Error = true;
        Result = true;
    }

    return Result;
}
b32 IsValid(wav_data_info *Data)
{
    b32 Result = false;

    if (!Data->Error || !IsEOF(Data))
    {
        Result = true;
    }

    return Result;
}
void Advance(wav_data_info *Data, u32 BytesToAdvance)
{
    if (!IsEOF(Data, BytesToAdvance))
    {
        Data->CurrentIndex += BytesToAdvance;
    }
}
u8 *GetCurrentAddress(wav_data_info *Data)
{
    u8 *Result = nullptr;

    if (IsValid(Data))
    {
        Result = Data->StartOfBuffer + Data->CurrentIndex;
    }

    return Result;
}
u32 Peek_u32(wav_data_info *Data)
{
    u32 Result = 0;

    if (IsValid(Data))
    {
        Result = *((u32 *)GetCurrentAddress(Data));
    }

    return Result;
}
u32 Get_u32(wav_data_info *Data)
{
    u32 Result = 0;

    if (IsValid(Data))
    {
        Result = *((u32 *)GetCurrentAddress(Data));
        Advance(Data, 4);
    }

    return Result;
}
u16 Get_u16(wav_data_info *Data)
{
    u16 Result = 0;

    if (IsValid(Data))
    {
        Result = *((u16 *)GetCurrentAddress(Data));
        Advance(Data, 2);
    }

    return Result;
}
b32 ParseRIFF(wav_data_info *Data, wav *Output)
{
    b32 Result = false;

    if (IsValid(Data))
    {
        u32 FourCC = Peek_u32(Data);
        if (FourCC == kWavFourCC_RIFF)
        {
            Advance(Data, 4);

            u32 FileSize = Get_u32(Data);
            UNUSED_VAR(FileSize);
            // From MSDN: "The value of fileSize includes the size of fileType FOURCC plus the size of the data that follows, but
            // does not include the size of the "RIFF" FOURCC or the size of fileSize. The data consists of chunks in any order".
            //Output->FileSize = FileSize - ? or +, we probably don't need to store this

            u32 FileType = Get_u32(Data);
            if (FileType == kWavFourCC_WAVE) // We only support wav for now
            {
                Output->Type = WavType_Wave;
                Result = true;
            }
#if 0
            else if (FileType == kWavFourCC_XWMA) // We only support wav for now
            {
                Output->Type = WavType_XWMA;
                Result = true;
            }
#endif
        }
    }

    Data->Error = Result;
    return Result;
}
b32 ParseFMT_(wav_data_info *Data, wav *Output)
{
    b32 Result = false;

    if (IsValid(Data))
    {
        u32 FourCC = Peek_u32(Data);
        if (FourCC == kWavFourCC_FMT)
        {
            Advance(Data, 4);

            u32 ChunkSize = Get_u32(Data);
            UNUSED_VAR(ChunkSize);

            wav_format *Fmt = &Output->Format;
            Fmt->Compression = Get_u16(Data);
            Fmt->NumberOfChannels = Get_u16(Data);
            Fmt->SampleRate = Get_u32(Data);
            Fmt->AverageBytesPerSecond = Get_u32(Data);
            Fmt->BlockAlign = Get_u16(Data);
            Fmt->SignificantBitsPerSample = Get_u16(Data);

            if (ChunkSize > 16) // Extra bytes maybe, should only be in the case of compressed data
            {
                Fmt->ExtraFormatBytes = Get_u16(Data);
                Advance(Data, Fmt->ExtraFormatBytes); // We don't care about the extra bytes for now...
            }

            if (Fmt->Compression != 1) // We only support uncompressed data for the moment.
            {
                assert(0);
            }

            if (Fmt->SignificantBitsPerSample % 8 != 0) // Byte aligned?
            {
                assert(0);
            }

            Result = true;
        }
    }

    Data->Error = Result;
    return Result;
}
b32 ParseDATA(wav_data_info *Data, wav *Output)
{
    b32 Result = false;

    if (IsValid(Data))
    {
        u32 FourCC = Peek_u32(Data);
        if (FourCC == kWavFourCC_DATA)
        {
            Advance(Data, 4);

            Output->DataSize = Get_u32(Data);
            Output->Data = static_cast<u8 *>(malloc(Output->DataSize));
            assert(Output->Data);

            memcpy(Output->Data, GetCurrentAddress(Data), Output->DataSize);

            Result = true;
        }
    }

    return Result;
}
//
// "Public" functions
//
b32 ParseWAV(u8 *Data, size_t DataSize, wav *Output)
{
    b32 Result = false;

    if (Output && Data && DataSize > 0)
    {
        wav_data_info DataInfo;
        DataInfo.StartOfBuffer = Data;
        DataInfo.CurrentIndex = 0;
        DataInfo.SizeOfBuffer = DataSize;

        Result = ParseRIFF(&DataInfo, Output);
        assert(Result);

        Result = ParseFMT_(&DataInfo, Output);
        assert(Result);

        Result = ParseDATA(&DataInfo, Output);
        assert(Result);
    }

    return Result;
}
void Free(wav *Data)
{
    if (Data)
    {
        if (Data->Data)
        {
            free(Data->Data);
            memset(Data, 0, sizeof(wav));
        }
    }
}

#include <gtest/gtest.h>
#include "StateMachine.hpp"
#include <functional>
class SingleStateTest : public StateMachine, public ::testing::Test
{
public:
	SingleStateTest()
		: g1(false)
		, g2(false)
		, g3(false)
	{
		InitStateMachine();
	}
	std::string Log() const { return log; }
	std::string CurrentStateName() const
	{
		return StateNames.at(CurrentState());
	}
protected:
	bool g1;
	bool g2;
	bool g3;
private:
	void AddToLog(const std::string& message)
	{
		if (!log.empty()) { log += ':'; }
		log += message;
	}
	void A0() override { AddToLog("Initial"); }
	void A1() override { AddToLog("A1"); }
	void A2() override { AddToLog("A2"); }
	void A3() override { AddToLog("A3"); }
	void A4() override { AddToLog("A4"); }
	void A5() override { AddToLog("A5"); }
	void A6() override { AddToLog("A6"); }
	void EntryAction() override { AddToLog("Entry"); }
	void ExitAction() override { AddToLog("Exit"); }
	bool G1() const override { return g1; }
	bool G2() const override { return g2; }
	std::string log;
};
TEST_F(SingleStateTest, InitialState)
{
    EXPECT_EQ("S", CurrentStateName());
}
TEST_F(SingleStateTest, InitialActionAndEntryActionExecuted)
{
    EXPECT_EQ("Initial:Entry", Log());
}
TEST_F(SingleStateTest, ActionExecutedOnInternalEvent)
{
    E1();
    EXPECT_EQ("Initial:Entry:A1", Log());
    EXPECT_EQ("S", CurrentStateName());
}
TEST_F(SingleStateTest, ActionExecutedTwice)
{
    E1();
    E1();
    EXPECT_EQ("Initial:Entry:A1:A1", Log());
    EXPECT_EQ("S", CurrentStateName());
}
TEST_F(SingleStateTest, TransitionToSelf)
{
    E2();
    EXPECT_EQ("Initial:Entry:Exit:A2:Entry", Log());
    EXPECT_EQ("S", CurrentStateName());
}
TEST_F(SingleStateTest, TransitionToFinalState)
{
    E3();
    EXPECT_EQ("Initial:Entry:Exit:A3", Log());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", CurrentStateName());
}
TEST_F(SingleStateTest, NoActionsExecutedInFinalState)
{
    E3();
    EXPECT_EQ("Initial:Entry:Exit:A3", Log());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", CurrentStateName());
    E1();
    E2();
    E3();
    EXPECT_EQ("Initial:Entry:Exit:A3", Log());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", CurrentStateName());
}
TEST_F(SingleStateTest, ActionOrNoActionDependingOnGuard)
{
    g1 = false;
    E4();
    EXPECT_EQ("Initial:Entry", Log());

    g1 = true;
    E4();
    EXPECT_EQ("Initial:Entry:A4", Log());

    g1 = false;
    E4();
    EXPECT_EQ("Initial:Entry:A4", Log());
    EXPECT_EQ("S", CurrentStateName());
}
TEST_F(SingleStateTest, ActionOrOtherActionDependingOnGuard)
{
    g2 = true;
    E5();
    EXPECT_EQ("Initial:Entry:A5", Log());
    g2 = false;
    E5();
    EXPECT_EQ("Initial:Entry:A5:A6", Log());
    EXPECT_EQ("S", CurrentStateName());
}

