	/* make a map from node_index to memb_list index. -1 means no exist*/
	map = (int*)ecalloc(vnodecount, sizeof(int));
	omap = (int*)ecalloc(n, sizeof(int));
	for (i=0; i < vnodecount; ++i) {
		map[i] = -1;
	}
	for (i=0; i < n; ++i) {
		map[ml->nodelist[i]->v_node_index] = i;
	}
#if 0
