TEST_CASE("Write random data to file - expect success", "[file]")
{
  std::string pathOut = "./../../content/file_tests/file1.txt";
  std::vector<uint8_t> bytes {34, 32, 156, 4, 4, 4, 9};
  plz::FileStatus s = plz::File::ToFile(pathOut, bytes);
