static constexpr uint16_t FLAGS_PACKET_TYPE_BITS = 1;
static constexpr uint16_t FLAGS_PACKET_TYPE_SHIFT = 15;
static constexpr uint16_t FLAGS_PACKET_TYPE_MASK = ((1 << FLAGS_PACKET_TYPE_BITS) - 1) << FLAGS_PACKET_TYPE_SHIFT;
static constexpr uint16_t FLAGS_OPCODE_BITS = 4;
static constexpr uint16_t FLAGS_OPCODE_SHIFT = 11;
static constexpr uint16_t FLAGS_OPCODE_MASK = ((1 << FLAGS_OPCODE_BITS) - 1) << FLAGS_OPCODE_SHIFT;
static constexpr uint16_t FLAGS_AUTH_ANSWER_BITS = 1;
static constexpr uint16_t FLAGS_AUTH_ANSWER_SHIFT = 10;
static constexpr uint16_t FLAGS_AUTH_ANSWER_MASK = ((1 << FLAGS_AUTH_ANSWER_BITS) - 1) << FLAGS_AUTH_ANSWER_SHIFT;
static constexpr uint16_t FLAGS_TRUNCATION_BITS = 1;
static constexpr uint16_t FLAGS_TRUNCATION_SHIFT = 9;
static constexpr uint16_t FLAGS_TRUNCATION_MASK = ((1 << FLAGS_TRUNCATION_BITS) - 1) << FLAGS_TRUNCATION_SHIFT;
static constexpr uint16_t FLAGS_RECURSION_DESIRED_BITS = 1;
static constexpr uint16_t FLAGS_RECURSION_DESIRED_SHIFT = 8;
static constexpr uint16_t FLAGS_RECURSION_DESIRED_MASK = ((1 << FLAGS_RECURSION_DESIRED_BITS) - 1) << FLAGS_RECURSION_DESIRED_SHIFT;
static constexpr uint16_t FLAGS_RECURSION_AVAILABLE_BITS = 1;
static constexpr uint16_t FLAGS_RECURSION_AVAILABLE_SHIFT = 7;
static constexpr uint16_t FLAGS_RECURSION_AVAILABLE_MASK = ((1 << FLAGS_RECURSION_AVAILABLE_BITS) - 1) << FLAGS_RECURSION_AVAILABLE_SHIFT;
static constexpr uint16_t FLAGS_RESERVED_BITS = 3;
static constexpr uint16_t FLAGS_RESERVED_SHIFT = 4;
static constexpr uint16_t FLAGS_RESERVED_MASK = ((1 << FLAGS_RESERVED_BITS) - 1) << FLAGS_RESERVED_SHIFT;
static constexpr uint16_t FLAGS_RESPONSE_CODE_BITS = 4;
static constexpr uint16_t FLAGS_RESPONSE_CODE_SHIFT = 0;
static constexpr uint16_t FLAGS_RESPONSE_CODE_MASK = ((1 << FLAGS_RESPONSE_CODE_BITS) - 1) << FLAGS_RESPONSE_CODE_SHIFT;
void PacketFlags::setType(PacketType type) {
  value_ &= ~FLAGS_PACKET_TYPE_MASK;
  value_ |= uint16_t(type) << FLAGS_PACKET_TYPE_SHIFT;
}
PacketType PacketFlags::type() { return PacketType((value_ & FLAGS_PACKET_TYPE_MASK) >> FLAGS_PACKET_TYPE_SHIFT); }
void PacketFlags::setOpcode(Opcode opcode) {
  value_ &= ~FLAGS_OPCODE_MASK;
  value_ |= (uint16_t(opcode) << FLAGS_OPCODE_SHIFT) & FLAGS_OPCODE_MASK;
}
Opcode PacketFlags::opcode() { return Opcode((value_ & FLAGS_OPCODE_MASK) >> FLAGS_OPCODE_SHIFT); }
void PacketFlags::setAuthoritativeAnswer(bool authAnswer) {
  value_ &= ~FLAGS_AUTH_ANSWER_MASK;
  value_ |= (uint16_t(authAnswer) << FLAGS_AUTH_ANSWER_SHIFT) & FLAGS_AUTH_ANSWER_MASK;
}
bool PacketFlags::authoritativeAnswer() { return bool((value_ & FLAGS_AUTH_ANSWER_MASK) >> FLAGS_AUTH_ANSWER_SHIFT); }
void PacketFlags::setTruncation(bool truncation) {
  value_ &= ~FLAGS_TRUNCATION_MASK;
  value_ |= (uint16_t(truncation) << FLAGS_TRUNCATION_SHIFT) & FLAGS_TRUNCATION_MASK;
}
bool PacketFlags::truncation() { return bool((value_ & FLAGS_TRUNCATION_MASK) >> FLAGS_TRUNCATION_SHIFT); }
void PacketFlags::setRecursionDesired(bool recDesired) {
  value_ &= ~FLAGS_RECURSION_DESIRED_MASK;
  value_ |= (uint16_t(recDesired) << FLAGS_RECURSION_DESIRED_SHIFT) & FLAGS_RECURSION_DESIRED_MASK;
}
bool PacketFlags::recursionDesired() { return bool((value_ & FLAGS_RECURSION_DESIRED_MASK) >> FLAGS_RECURSION_DESIRED_SHIFT); }
void PacketFlags::setRecursionAvailable(bool recAvail) {
  value_ &= ~FLAGS_RECURSION_AVAILABLE_MASK;
  value_ |= (uint16_t(recAvail) << FLAGS_RECURSION_AVAILABLE_SHIFT) & FLAGS_RECURSION_AVAILABLE_MASK;
}
bool PacketFlags::recursionAvailable() { return bool((value_ & FLAGS_RECURSION_AVAILABLE_MASK) >> FLAGS_RECURSION_AVAILABLE_SHIFT); }
void PacketFlags::setReservedBits(ReservedFlagsTriple reserved) {
  value_ &= ~FLAGS_RESERVED_MASK;
  value_ |= (uint16_t(reserved) << FLAGS_RESERVED_SHIFT) & FLAGS_RESERVED_MASK;
}
ReservedFlagsTriple PacketFlags::reservedBits() { return ReservedFlagsTriple((value_ & FLAGS_RESERVED_MASK) >> FLAGS_RESERVED_SHIFT); }
void PacketFlags::setResponseCode(ResponseCode code) {
  value_ &= ~FLAGS_RESPONSE_CODE_MASK;
  value_ |= (uint16_t(code) << FLAGS_RESPONSE_CODE_SHIFT) & FLAGS_RESPONSE_CODE_MASK;
}
ResponseCode PacketFlags::responseCode() { return ResponseCode((value_ & FLAGS_RESPONSE_CODE_MASK) >> FLAGS_RESPONSE_CODE_SHIFT); }
// =============================================
// Record Data (toBytes)
// =============================================
std::vector<uint8_t> RecordData::toBytes() const {
  std::vector<uint8_t> v;
  toBytes(v);
  return v;
}
void RecordDataIPv4::toBytes(std::vector<uint8_t> &v) const {
  v.clear();
  v.push_back(uint8_t(this->addr_ >> 24));
  v.push_back(uint8_t(this->addr_ >> 16));
  v.push_back(uint8_t(this->addr_ >> 8));
  v.push_back(uint8_t(this->addr_));
}
void RecordDataGeneric::toBytes(std::vector<uint8_t> &v) const {
  v.clear();
  std::copy(data_.begin(), data_.end(), std::back_inserter(v));
}
