#define __ ACCESS_MASM(masm)
static void StoreIC_PushArgs(MacroAssembler* masm) {
  __ Push(StoreWithVectorDescriptor::ValueRegister(),
          StoreWithVectorDescriptor::SlotRegister(),
          StoreWithVectorDescriptor::VectorRegister(),
          StoreWithVectorDescriptor::ReceiverRegister(),
          StoreWithVectorDescriptor::NameRegister());
}
void KeyedStoreIC::GenerateMiss(MacroAssembler* masm) {
  StoreIC_PushArgs(masm);
  __ TailCallRuntime(Runtime::kKeyedStoreIC_Miss);
}
void KeyedStoreIC::GenerateSlow(MacroAssembler* masm) {
  StoreIC_PushArgs(masm);
  // The slow case calls into the runtime to complete the store without causing
  // an IC miss that would otherwise cause a transition to the generic stub.
  __ TailCallRuntime(Runtime::kKeyedStoreIC_Slow);
}
#undef __
Condition CompareIC::ComputeCondition(Token::Value op) {
  switch (op) {
    case Token::EQ_STRICT:
    case Token::EQ:
      return eq;
    case Token::LT:
      return lt;
    case Token::GT:
      return gt;
    case Token::LTE:
      return le;
    case Token::GTE:
      return ge;
    default:
      UNREACHABLE();
      return kNoCondition;
  }
}
bool CompareIC::HasInlinedSmiCode(Address address) {
  // The address of the instruction following the call.
  Address cmp_instruction_address =
      Assembler::return_address_from_call_start(address);
  // If the instruction following the call is not a CHI, nothing
  // was inlined.
  return (Instruction::S390OpcodeValue(cmp_instruction_address) == CHI);
}
//
// This code is paired with the JumpPatchSite class in full-codegen-s390.cc
//
void PatchInlinedSmiCode(Isolate* isolate, Address address,
                         InlinedSmiCheck check) {
  Address cmp_instruction_address =
      Assembler::return_address_from_call_start(address);
  // If the instruction following the call is not a cmp rx, #yyy, nothing
  // was inlined.
  Instr instr = Assembler::instr_at(cmp_instruction_address);
  if (Instruction::S390OpcodeValue(cmp_instruction_address) != CHI) {
    return;
  }
  if (Instruction::S390OpcodeValue(address) != BRASL) {
    return;
  }
  // The delta to the start of the map check instruction and the
  // condition code uses at the patched jump.
  int delta = instr & 0x0000ffff;
  // If the delta is 0 the instruction is cmp r0, #0 which also signals that
  // nothing was inlined.
  if (delta == 0) {
    return;
  }
  if (FLAG_trace_ic) {
    PrintF("[  patching ic at %p, cmp=%p, delta=%d\n",
           static_cast<void*>(address),
           static_cast<void*>(cmp_instruction_address), delta);
  }
  // Expected sequence to enable by changing the following
  //   CR/CGR  Rx, Rx    // 2 / 4 bytes
  //   LR  R0, R0        // 2 bytes   // 31-bit only!
  //   BRC/BRCL          // 4 / 6 bytes
  // into
  //   TMLL    Rx, XXX   // 4 bytes
  //   BRC/BRCL          // 4 / 6 bytes
  // And vice versa to disable.
  // The following constant is the size of the CR/CGR + LR + LR
  const int kPatchAreaSizeNoBranch = 4;
  Address patch_address = cmp_instruction_address - delta;
  Address branch_address = patch_address + kPatchAreaSizeNoBranch;
  Instr instr_at_patch = Assembler::instr_at(patch_address);
  SixByteInstr branch_instr = Assembler::instr_at(branch_address);
  // This is patching a conditional "jump if not smi/jump if smi" site.
  size_t patch_size = 0;
  if (Instruction::S390OpcodeValue(branch_address) == BRC) {
    patch_size = kPatchAreaSizeNoBranch + 4;
  } else if (Instruction::S390OpcodeValue(branch_address) == BRCL) {
    patch_size = kPatchAreaSizeNoBranch + 6;
  } else {
    DCHECK(false);
  }
  CodePatcher patcher(isolate, patch_address, patch_size);
  Register reg;
  reg.reg_code = instr_at_patch & 0xf;
  if (check == ENABLE_INLINED_SMI_CHECK) {
    patcher.masm()->TestIfSmi(reg);
  } else {
    // Emit the NOP to ensure sufficient place for patching
    // (replaced by LR + NILL)
    DCHECK(check == DISABLE_INLINED_SMI_CHECK);
    patcher.masm()->CmpP(reg, reg);
#ifndef V8_TARGET_ARCH_S390X
    patcher.masm()->nop();
#endif
  }
  Condition cc = al;
  if (Instruction::S390OpcodeValue(branch_address) == BRC) {
    cc = static_cast<Condition>((branch_instr & 0x00f00000) >> 20);
    DCHECK((cc == ne) || (cc == eq));
    cc = (cc == ne) ? eq : ne;
    patcher.masm()->brc(cc, Operand(branch_instr & 0xffff));
  } else if (Instruction::S390OpcodeValue(branch_address) == BRCL) {
    cc = static_cast<Condition>(
        (branch_instr & (static_cast<uint64_t>(0x00f0) << 32)) >> 36);
    DCHECK((cc == ne) || (cc == eq));
    cc = (cc == ne) ? eq : ne;
    patcher.masm()->brcl(cc, Operand(branch_instr & 0xffffffff));
  } else {
    DCHECK(false);
  }
}
}  // namespace internal
}  // namespace v8
#endif  // V8_TARGET_ARCH_S390

#include <bits/stdc++.h>
using namespace std;
struct node {
  int a, b, c, cnt; int ans;
  bool operator< (const node& r) const { return a == r.a ? (b == r.b ? c < r.c : b < r.b) : a < r.a; }
  bool operator== (const node& r) const { return a == r.a && b == r.b && c == r.c; }
} a[100005], b[100005]; int ans[100005];
struct BIT {
  int t[200005];
  inline void clear() { memset(t, 0, sizeof(t)); }
  inline int lowbit(int x) { return x & (-x); }
  inline int get(int x) { int _=0; for (; x; x -= lowbit(x)) _ += t[x]; return _; }
  inline void add(int x, int v=1) { for (; x <= 200000; x += lowbit(x)) t[x] += v; }
  inline int rng(int l, int r) { return l <= r ? (get(r) - (l ? get(l - 1) : 0)) : 0; }
} T;
void cdq(int l, int r, bool sorted=1) {
  if (l >= r) return;
  int mid = l + r >> 1;
  cdq(l, mid); cdq(mid + 1, r);
  int x = l; for (int y = mid + 1; y <= r; ++y) {
    while (x <= mid && b[x].b <= b[y].b) T.add(b[x].c, b[x].cnt), ++x;
    b[y].ans += T.get(b[y].c);
  }
  for (int y = l; y < x; ++y) T.add(b[y].c, -b[y].cnt);
  if (sorted) sort(b+l, b+r+1, [](const node &a, const node &b) { return a.b < b.b; });
}
int main() {
  int n, k;
  scanf("%d%d", &n,&k);
  for (int i = 1; i <= n; ++i) {
    scanf("%d%d%d", &a[i].a, &a[i].b, &a[i].c);
    a[i].cnt = 1;
  }
  sort(a + 1, a + 1 + n);
  int m = 1; b[1] = a[1];
  for (int i = 2; i <= n; ++i) {
    if (a[i] == a[i-1]) ++b[m].cnt;
    else b[++m] = a[i];
  }
  cdq(1, m, 0);
  for (int i = 1; i <= m; ++i) {
    ans[b[i].ans + b[i].cnt - 1] += b[i].cnt;
  }
  for (int i = 0; i < n; ++i) printf("%d\n", ans[i]);
  return 0;
}

#include <stdio.h>
