//Independent Parameters
const double E = 200e9;
const double G = 80e9;
const double rad = 0.001;
const double rho = 8000;
const Vector3d g = -9.81*Vector3d::UnitX();
const double L = 0.5;
const int N = 40; //Number of spatial points
const double dt = 2e-3; //Time step
const double alpha = -0.2; //Parameter for implicit time discretization
const double T = 25; //Total simulation time
const double initial_tip_mass = 0.02; //Weight for ICs, released at t0+
const double Bs = 0; //Shearing material damping
const double Be = 0; //Extension material damping
const double Bb = 0; //Bending material damping
const double Bt = 0; //Torsional material damping
//Dependent parameter calculations
static Vector3d F = initial_tip_mass*g;
const double c0 = TimeManagerBdfAlpha::getC0(dt,alpha);
const double A = pi*pow(rad,2);
const double I = pi*pow(rad,4)/4;
const DiagonalMatrix<double, 3> Kse(G*A,G*A,E*A);
const Vector3d Kse_e3(0, 0, E*A);
const DiagonalMatrix<double, 3> Kbt(E*I,E*I,G*2*I);
const DiagonalMatrix<double, 3> Kse_inv = DiagonalMatrix<double, 3>(G*A,G*A,E*A).inverse();
const DiagonalMatrix<double, 3> Kbt_inv = DiagonalMatrix<double, 3>(E*I,E*I,G*2*I).inverse();
const DiagonalMatrix<double, 3> rhoJ = rho*DiagonalMatrix<double, 3>(I, I, 2*I);
const DiagonalMatrix<double, 3> Bse(Bs, Bs, Be);
const DiagonalMatrix<double, 3> Bbt(Bb, Bb, Bt);
const DiagonalMatrix<double, 3> inv_of_Kse_c0Bse (1/(G*A + c0*Bs), 1/(G*A + c0*Bs), 1/(E*A + c0*Be));
const DiagonalMatrix<double, 3> inv_of_Kbt_c0Bbt (1/(E*I + c0*Bb), 1/(E*I + c0*Bb), 1/(G*2*I + c0*Bt));
const double rhoA = rho*A;
const Vector3d rhoAg = rho*A*g;
//ODE describing elastic rod statics
void cosseratRodOde(VectorXd& y_s_out, Map<VectorXd> z_out, Map<VectorXd> y){
    //Unpack state vector
    Matrix3d R = Map<Matrix3d>(&y[3]);
    Map<Vector3d> n(&y[12]);
    Map<Vector3d> m(&y[15]);
    //Hard-coded constitutive law w/ no precurvature
    Vector3d v = Kse_inv*transposeMultiply(R,n); v(2) += 1;
    Vector3d u = Kbt_inv*transposeMultiply(R,m);
    //Refer to the state vector derivative by its components
    Map<Vector3d> p_s (&y_s_out[0]);
    Map<Matrix3d> R_s (&y_s_out[3]);
    Map<Vector3d> n_s (&y_s_out[12]);
    Map<Vector3d> m_s (&y_s_out[15]);
    Map<Vector3d> q_s (&y_s_out[18]);
    Map<Vector3d> w_s (&y_s_out[21]);
    //ODEs
    p_s = R*v;
    R_s = hat_postmultiply(R,u);
    n_s = -rhoAg;
    m_s = -p_s.cross(n);
    q_s = Vector3d::Zero();
    w_s = Vector3d::Zero();
    //Output argument for variables with time derivatives
    z_out << Vector6d::Zero(), v, u;
}
//PDE semi-discretized in time describing elastic rod dynamics
void cosseratRodPDE(VectorXd& y_s_out, Map<VectorXd> z_out, Map<VectorXd> y, Map<VectorXd> z_h){
    //Unpack state vector
    Matrix3d R = Map<Matrix3d>(&y[3]);
    Vector3d n = Map<Vector3d>(&y[12]);
    Vector3d m = Map<Vector3d>(&y[15]);
    Vector3d q = Map<Vector3d>(&y[18]);
    Vector3d w = Map<Vector3d>(&y[21]);
    //Unpack history terms
    Map<Vector3d> q_h (&z_h[0]);
    Map<Vector3d> w_h (&z_h[3]);
    Map<Vector3d> v_h (&z_h[6]);
    Map<Vector3d> u_h (&z_h[9]);
    Vector3d q_t = c0*q + q_h;
    Vector3d w_t = c0*w + w_h;
    //Material constitutive equation
    Vector3d v = inv_of_Kse_c0Bse*(transposeMultiply(R,n) + Kse_e3 - Bse*v_h);
    Vector3d u = inv_of_Kbt_c0Bbt*(transposeMultiply(R,m) - Bbt*u_h);
    Vector3d v_t = c0*v + v_h;
    Vector3d u_t = c0*u + u_h;
    //Pack state vector derivative
    Map<Vector3d> p_s (&y_s_out[0]);
    Map<Matrix3d> R_s (&y_s_out[3]);
    Map<Vector3d> n_s (&y_s_out[12]);
    Map<Vector3d> m_s (&y_s_out[15]);
    Map<Vector3d> q_s (&y_s_out[18]);
    Map<Vector3d> w_s (&y_s_out[21]);
    //ODEs
    p_s = R*v;
    R_s = hat_postmultiply(R,u);
    n_s = rhoA*R*(q_t + w.cross(q)) - rhoAg;
    m_s = R*(rhoJ*w_t + w.cross(rhoJ*w)) - p_s.cross(n);
    q_s = v_t - u.cross(q) + w.cross(v);
    w_s = u_t - u.cross(w);
    //Output argument for variables with time derivatives
    z_out << q, w, v, u;
}
static MatrixXd Y(24,N); //State variables (which have arclength derivatives)
static MatrixXd Z(12,N); //Variables with time derivatives
static MatrixXd Z_h(12,N); //History terms
template<bool is_dynamic>
VectorXd objFunc(VectorXd guess){
    VectorXd y0(24);
    y0 << 0, 0, 0, 1, 0, 0, 0, 1, 0, 0, 0, 1, guess, Vector6d::Zero();
    //Numerically integrate the semi-discretized rod PDEs
    if(is_dynamic) TimeBdfAlpha_SpaceEuler<cosseratRodPDE,24,12,N>(Y,Z,y0,L,Z_h);
    else           euler<cosseratRodOde,24,12,N>(Y,Z,y0,L);
    Vector3d nL_shooting = Y.block<3,1>(12, N-1);
    Vector3d mL_shooting = Y.block<3,1>(15, N-1);
    Vector6d distal_error;
    if(is_dynamic) distal_error << nL_shooting, mL_shooting;     //No tip mass
    else           distal_error << nL_shooting - F, mL_shooting; //Tip mass determines ICs
    return distal_error;
}
int main(int, char**){
    //Solve initial conditions
    Vector6d guess = Vector6d::Zero();
    Vector6d reaction_wrench = solveLevenbergMarquardt<objFunc<false> >(guess);
    TimeManagerBdfAlpha time_scheme(Z, Z_h, dt, alpha);
    F = Vector3d::Zero(); //The tip load is removed
    int M = static_cast<int>(T/dt);
    MatrixXd px(M,N), pz(M,N);
    std::clock_t start = std::clock();
    for(int i = 0; i < M; i++){
        px.row(i) = Y.row(0);
        pz.row(i) = Y.row(2);
        time_scheme.advanceTime(); //Update Z_h from history of Z
        //Solve dynamic problem
        reaction_wrench = solveLevenbergMarquardt<objFunc<true> >(reaction_wrench);
    }
    double duration = ( std::clock() - start ) / static_cast<double>(CLOCKS_PER_SEC);
    std::cout << "Time elasped: " << duration << "s" << std::endl;
    std::cout << "Real-time ratio: " << T/duration << std::endl;
    #ifdef QT_CORE_LIB
    playAnimation(pz, px, dt, "Dynamic Cantilever", "z (m)", "x (m)");
    #endif
    return 0;
}

#include "SwiftTargetInfo.h"
#include "IRGenModule.h"
#include "llvm/ADT/Triple.h"
#include "llvm/IR/DataLayout.h"
#include "swift/ABI/System.h"
#include "swift/AST/ASTContext.h"
#include "swift/AST/IRGenOptions.h"
using namespace swift;
using namespace irgen;
/// Initialize a bit vector to be equal to the given bit-mask.
static void setToMask(SpareBitVector &bits, unsigned size, uint64_t mask) {
  bits.clear();
  bits.add(size, mask);
}
/// Configures target-specific information for arm64 platforms.
static void configureARM64(IRGenModule &IGM, const llvm::Triple &triple,
                           SwiftTargetInfo &target) {
  setToMask(target.PointerSpareBits, 64,
            SWIFT_ABI_ARM64_SWIFT_SPARE_BITS_MASK);
  setToMask(target.ObjCPointerReservedBits, 64,
            SWIFT_ABI_ARM64_OBJC_RESERVED_BITS_MASK);
  setToMask(target.IsObjCPointerBit, 64, SWIFT_ABI_ARM64_IS_OBJC_BIT);
  if (triple.isOSDarwin()) {
    target.LeastValidPointerValue =
      SWIFT_ABI_DARWIN_ARM64_LEAST_VALID_POINTER;
  }
  // arm64 has no special objc_msgSend variants, not even stret.
  target.ObjCUseStret = false;
  // arm64 requires marker assembly for objc_retainAutoreleasedReturnValue.
  target.ObjCRetainAutoreleasedReturnValueMarker =
    "mov\tfp, fp\t\t// marker for objc_retainAutoreleaseReturnValue";
  // arm64 requires ISA-masking.
  target.ObjCUseISAMask = true;
  // arm64 tops out at 56 effective bits of address space and reserves the high
  // half for the kernel.
  target.SwiftRetainIgnoresNegativeValues = true;
}
/// Configures target-specific information for x86-64 platforms.
static void configureX86_64(IRGenModule &IGM, const llvm::Triple &triple,
                            SwiftTargetInfo &target) {
  setToMask(target.PointerSpareBits, 64,
            SWIFT_ABI_X86_64_SWIFT_SPARE_BITS_MASK);
  setToMask(target.ObjCPointerReservedBits, 64,
            SWIFT_ABI_X86_64_OBJC_RESERVED_BITS_MASK);
  setToMask(target.IsObjCPointerBit, 64, SWIFT_ABI_X86_64_IS_OBJC_BIT);
  if (triple.isOSDarwin()) {
    target.LeastValidPointerValue =
      SWIFT_ABI_DARWIN_X86_64_LEAST_VALID_POINTER;
  }
  // x86-64 has every objc_msgSend variant known to humankind.
  target.ObjCUseFPRet = true;
  target.ObjCUseFP2Ret = true;
  // x86-64 requires ISA-masking.
  target.ObjCUseISAMask = true;

  // x86-64 only has 48 effective bits of address space and reserves the high
  // half for the kernel.
  target.SwiftRetainIgnoresNegativeValues = true;
}
/// Configures target-specific information for 32-bit x86 platforms.
static void configureX86(IRGenModule &IGM, const llvm::Triple &triple,
                         SwiftTargetInfo &target) {
  // x86 uses objc_msgSend_fpret but not objc_msgSend_fp2ret.
  target.ObjCUseFPRet = true;
  setToMask(target.IsObjCPointerBit, 32, SWIFT_ABI_I386_IS_OBJC_BIT);
}
/// Configures target-specific information for 32-bit arm platforms.
static void configureARM(IRGenModule &IGM, const llvm::Triple &triple,
                         SwiftTargetInfo &target) {
  // ARM requires marker assembly for objc_retainAutoreleasedReturnValue.
  target.ObjCRetainAutoreleasedReturnValueMarker =
    "mov\tr7, r7\t\t// marker for objc_retainAutoreleaseReturnValue";
  // armv7k has opaque ISAs which must go through the ObjC runtime.
  if (triple.getSubArch() == llvm::Triple::SubArchType::ARMSubArch_v7k)
    target.ObjCHasOpaqueISAs = true;
  setToMask(target.IsObjCPointerBit, 32, SWIFT_ABI_ARM_IS_OBJC_BIT);
}
/// Configures target-specific information for powerpc64 platforms.
static void configurePowerPC64(IRGenModule &IGM, const llvm::Triple &triple,
                               SwiftTargetInfo &target) {
  setToMask(target.PointerSpareBits, 64,
            SWIFT_ABI_POWERPC64_SWIFT_SPARE_BITS_MASK);
}
/// Configures target-specific information for SystemZ platforms.
static void configureSystemZ(IRGenModule &IGM, const llvm::Triple &triple,
                             SwiftTargetInfo &target) {
  setToMask(target.PointerSpareBits, 64,
            SWIFT_ABI_S390X_SWIFT_SPARE_BITS_MASK);
}
/// Configure a default target.
SwiftTargetInfo::SwiftTargetInfo(
  llvm::Triple::ObjectFormatType outputObjectFormat,
  unsigned numPointerBits)
  : OutputObjectFormat(outputObjectFormat),
    HeapObjectAlignment(numPointerBits / 8),
    LeastValidPointerValue(SWIFT_ABI_DEFAULT_LEAST_VALID_POINTER)
{
  setToMask(PointerSpareBits, numPointerBits,
            SWIFT_ABI_DEFAULT_SWIFT_SPARE_BITS_MASK);
  setToMask(ObjCPointerReservedBits, numPointerBits,
            SWIFT_ABI_DEFAULT_OBJC_RESERVED_BITS_MASK);
  setToMask(FunctionPointerSpareBits, numPointerBits,
            SWIFT_ABI_DEFAULT_FUNCTION_SPARE_BITS_MASK);
}
SwiftTargetInfo SwiftTargetInfo::get(IRGenModule &IGM) {
  const llvm::Triple &triple = IGM.Context.LangOpts.Target;
  auto pointerSize = IGM.DataLayout.getPointerSizeInBits();
  // Prepare generic target information.
  SwiftTargetInfo target(triple.getObjectFormat(), pointerSize);

  // On Apple platforms, we implement "once" using dispatch_once,
  // which exposes a barrier-free inline path with -1 as the "done" value.
  if (triple.isOSDarwin())
    target.OnceDonePredicateValue = -1L;
  // Other platforms use std::call_once() and we don't
  // assume that they have a barrier-free inline fast path.

  switch (triple.getArch()) {
  case llvm::Triple::x86_64:
    configureX86_64(IGM, triple, target);
    break;
  case llvm::Triple::x86:
    configureX86(IGM, triple, target);
    break;
  case llvm::Triple::arm:
  case llvm::Triple::thumb:
    configureARM(IGM, triple, target);
    break;
  case llvm::Triple::aarch64:
    configureARM64(IGM, triple, target);
    break;
  case llvm::Triple::ppc64:
  case llvm::Triple::ppc64le:
    configurePowerPC64(IGM, triple, target);
    break;
  case llvm::Triple::systemz:
    configureSystemZ(IGM, triple, target);
    break;
  default:
    // FIXME: Complain here? Default target info is unlikely to be correct.
    break;
  }
  return target;
}
bool SwiftTargetInfo::hasObjCTaggedPointers() const {
  return ObjCPointerReservedBits.any();
}

#include <chrono>
#include <exception>
#include <functional>
#include <intrin0.h>
#include <mutex>
#include <stdexcept>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string>
#include <thread>
#include <vector>


using namespace std;
using namespace std::placeholders;

long g_last_successful_line(0);

void verify(const bool b, const long line) {
    if (b) {
        _InterlockedExchange(&g_last_successful_line, line);
    } else {
        printf("Last successful line was %ld.\n", _InterlockedCompareExchange(&g_last_successful_line, 0, 0));
        printf("Failed on line %ld.\n", line);
        abort();
    }
}

#define VERIFY(B) verify(B, __LINE__)

struct WritePlaceholder {
    template <typename T>
    void operator()(const T&, int* const p) const {
        *p = is_placeholder_v<T>;
    }
};

void ThrowingFunc(int* const p) {
    ++*p;

    switch (*p) {
    case 1:
        throw overflow_error("one");
    case 2:
        throw underflow_error("two");
    default:
        break;
    }
}

// ***** Machinery to test the XP codepath: *****
// extern "C" {
//     extern void * __encodedKERNEL32Functions[40 /* eMaxKernel32Function */];
//     extern uintptr_t __security_cookie;
// }

void run_tests() {

    // ***** Machinery to test the XP codepath: *****
    // __encodedKERNEL32Functions[5 /* eInitOnceExecuteOnce */] = reinterpret_cast<void *>(__security_cookie);

    // Basic check.
    {
        once_flag flag;
        auto inc = [](int* const p) { ++*p; };
        int i    = 0;

        VERIFY(i == 0);
        call_once(flag, inc, &i);
        VERIFY(i == 1);
        call_once(flag, inc, &i);
        VERIFY(i == 1);
    }

    // call_once() should use INVOKE().
    {
        struct Meow {
            int x;
            int y;

            void write_sum(int* const p) const {
                *p = x + y;
            }
        };

        once_flag flag;
        Meow m = {1700, 29};
        int i  = 0;

        call_once(flag, &Meow::write_sum, &m, &i);
        VERIFY(i == 1729);
    }

    // call_once() should NOT use bind().
    {
        once_flag flag1;
        int i1 = -1;

        call_once(flag1, WritePlaceholder(), 3.14, &i1);
        VERIFY(i1 == 0);


        once_flag flag2;
        int i2 = -1;

        call_once(flag2, WritePlaceholder(), _5, &i2);
        VERIFY(i2 == 5);
    }

    // Test DevDiv#1086953 "Throwing exception from std::call_once does not allow other threads to enter".
    // EH, single-threaded.
    {
        once_flag flag;

        int i = 0;

        try {
            call_once(flag, ThrowingFunc, &i);
            VERIFY(false);
        } catch (const overflow_error& e) {
            VERIFY(i == 1);
            VERIFY(e.what() == "one"s);
        } catch (...) {
            VERIFY(false);
        }

        try {
            call_once(flag, ThrowingFunc, &i);
            VERIFY(false);
        } catch (const underflow_error& e) {
            VERIFY(i == 2);
            VERIFY(e.what() == "two"s);
        } catch (...) {
            VERIFY(false);
        }

        try {
            call_once(flag, ThrowingFunc, &i);
            VERIFY(i == 3);

            call_once(flag, ThrowingFunc, &i);
            VERIFY(i == 3);
        } catch (...) {
            VERIFY(false);
        }
    }

    // Test DevDiv#1086953 "Throwing exception from std::call_once does not allow other threads to enter".
    // EH, multi-threaded.
    {
        long ready = 0;
        once_flag flag;
        int i = 0;

        auto lambda = [&ready, &flag, &i] {
            while (!_InterlockedCompareExchange(&ready, 0, 0)) {
            }

            try {
                call_once(flag, ThrowingFunc, &i);
                VERIFY(i == 3);
            } catch (const overflow_error& e) {
                VERIFY(e.what() == "one"s);
            } catch (const underflow_error& e) {
                VERIFY(e.what() == "two"s);
            } catch (...) {
                VERIFY(false);
            }
        };

        vector<thread> v;

        // Want 5 threads: 2 exceptional, 1 returning, 2 passive.
        for (int n = 0; n < 5; ++n) {
            v.emplace_back(lambda);
        }

        _InterlockedExchange(&ready, 1);

        for (auto& t : v) {
            t.join();
        }

        VERIFY(i == 3);
    }

    // Test DevDiv#1092852 "concurrent std::call_once calls seem to be blocking somewhere on a shared variable".
    // Also test stateful callable objects.
    {
        long atom = 0;

        thread t1([&atom] {
            once_flag flag1;

            auto lambda1 = [&atom] {
                _InterlockedExchange(&atom, 100);
                while (_InterlockedCompareExchange(&atom, 111, 200) != 200) {
                }
            };

            call_once(flag1, lambda1);
        });

        thread t2([&atom] {
            once_flag flag2;

            auto lambda2 = [&atom] {
                while (_InterlockedCompareExchange(&atom, 200, 100) != 100) {
                }
                while (_InterlockedCompareExchange(&atom, 222, 111) != 111) {
                }
            };

            call_once(flag2, lambda2);
        });

        t1.join();
        t2.join();

        VERIFY(atom == 222);
    }

    // Verify that active executions don't occur simultaneously.
    {
        once_flag flag;
        long atom = 0;

        auto thread_lambda = [&flag, &atom] {
            try {
                call_once(flag, [&atom] {
                    VERIFY(_InterlockedIncrement(&atom) == 1);
                    this_thread::sleep_for(50ms);
                    VERIFY(_InterlockedDecrement(&atom) == 0);
                    throw runtime_error("woof");
                });
                VERIFY(false);
            } catch (const runtime_error& e) {
                VERIFY(e.what() == "woof"s);
            } catch (...) {
                VERIFY(false);
            }
        };

        vector<thread> v;

        for (int n = 0; n < 5; ++n) {
            v.emplace_back(thread_lambda);
        }

        for (auto& t : v) {
            t.join();
        }
    }

    // Test LWG-2442 "call_once() shouldn't DECAY_COPY()".
    {
        once_flag flag;
        int n       = 0;
        auto lambda = [](int& r) { r = 1729; };

        VERIFY(n == 0);
        call_once(flag, lambda, n);
        VERIFY(n == 1729);
    }
}

int main() {
    try {
        run_tests();
    } catch (const exception& e) {
        puts(e.what());
        VERIFY(false);
    }

    puts("Passed.");
}

