        mpDoHelpEvent->init();
    }
    else if( dynamic_cast<const CloseLineInput*>(evPtr) )
    {
        mpLineInput = nullptr;
    }
    else if( auto savegame = dynamic_cast<const SaveGameEvent*>(evPtr) )
    {
        savegame->save();
    }
