    }
#else
	off_t ret = lseek( _fileDescriptor, 0, SEEK_CUR );
    if (ret == (off_t)-1)
    {
        _NotifyIOError("CFile::GetPosition");
        return 0;
    }
#endif
    if (ret > INT_MAX)
    {
        _NotifyIOError("CFile::GetPosition (length)");
