#include "llvm/MC/MCSectionXCOFF.h"
#include "llvm/MC/MCAsmInfo.h"
#include "llvm/MC/MCExpr.h"
#include "llvm/Support/raw_ostream.h"
using namespace llvm;
MCSectionXCOFF::~MCSectionXCOFF() = default;
static StringRef getMappingClassString(XCOFF::StorageMappingClass SMC) {
  switch (SMC) {
  case XCOFF::XMC_DS:
    return "DS";
  case XCOFF::XMC_RW:
    return "RW";
  case XCOFF::XMC_PR:
    return "PR";
  default:
    report_fatal_error("Unhandled storage-mapping class.");
  }
}
void MCSectionXCOFF::PrintSwitchToSection(const MCAsmInfo &MAI, const Triple &T,
                                          raw_ostream &OS,
                                          const MCExpr *Subsection) const {
  if (getKind().isText()) {
    if (getMappingClass() != XCOFF::XMC_PR)
      report_fatal_error("Unhandled storage-mapping class for .text csect");
    OS << "\t.csect " << getSectionName() << "["
       << getMappingClassString(getMappingClass())
       << "]" << '\n';
    return;
  }
  if (getKind().isData()) {
    switch (getMappingClass()) {
    case XCOFF::XMC_RW:
    case XCOFF::XMC_DS:
      OS << "\t.csect " << getSectionName() << "["
         << getMappingClassString(getMappingClass()) << "]" << '\n';
      break;
    case XCOFF::XMC_TC0:
      OS << "\t.toc\n";
      break;
    default:
      report_fatal_error(
          "Unhandled storage-mapping class for .data csect.");
    }
    return;
  }
  if (getKind().isBSSLocal() || getKind().isCommon()) {
    assert((getMappingClass() == XCOFF::XMC_RW ||
            getMappingClass() == XCOFF::XMC_BS) &&
           "Generated a storage-mapping class for a common/bss csect we don't "
           "understand how to switch to.");
    assert(getCSectType() == XCOFF::XTY_CM &&
           "wrong csect type for .bss csect");
    // Don't have to print a directive for switching to section for commons.
    // '.comm' and '.lcomm' directives for the variable will create the needed
    // csect.
    return;
  }
  report_fatal_error("Printing for this SectionKind is unimplemented.");
}
bool MCSectionXCOFF::UseCodeAlign() const { return getKind().isText(); }
bool MCSectionXCOFF::isVirtualSection() const { return XCOFF::XTY_CM == Type; }

#include<iostream>
#include<algorithm>
using namespace std;
// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* left, TreeNode* right) : val(x), left(left), right(right) {}
};
class Solution {
public:
    int maxDepth(TreeNode* root, int depth) {
        if (root == nullptr)   return depth;
        depth++;
        return max(maxDepth(root->left, depth), maxDepth(root->right, depth));
    }
    int maxDepth(TreeNode* root) {
        if (!root)   return 0;
        return max(maxDepth(root->left), maxDepth(root->right)) + 1;
    }
};
int main() {
    TreeNode l1(2);
    TreeNode n1(1, &l1, nullptr);
    Solution solution;
    cout << "\n " << solution.maxDepth(&n1) << endl;
    return 0;
}

#include "Helpers/KeySequence.hpp"
namespace CTRPluginFramework
{
    KeySequence::KeySequence(KeyVector sequence) : 
    _sequence(sequence), _indexInSequence(0)
    {            
    }
    bool  KeySequence::operator()(void)
    {
        if (Controller::IsKeyDown(_sequence[_indexInSequence]))
        {
            _indexInSequence++;
            if (_indexInSequence >= _sequence.size())
            {
                _indexInSequence = 0;
                return (true);
            }
            _timer.Restart();
        }
        if (_timer.HasTimePassed(Seconds(1.f)))
        {
            _indexInSequence = 0;
            _timer.Restart();
        }
        return (false);
    }
}

