#include "tasks/write_buffer_aggregator.h"
#include <utility>
namespace eloqstore
{
WriteBufferAggregator::WriteBufferAggregator(size_t buffer_size)
    : buffer_size_(buffer_size)
{
}
void WriteBufferAggregator::Reset()
{
    buffer_ = nullptr;
    buffer_index_ = 0;
    use_fixed_ = true;
    file_id_ = 0;
    start_offset_ = 0;
    next_offset_ = 0;
    used_ = 0;
    pages_.clear();
    release_ptrs_.clear();
    release_indices_.clear();
}
bool WriteBufferAggregator::HasBuffer() const
{
    return buffer_ != nullptr;
}
bool WriteBufferAggregator::HasData() const
{
    return buffer_ != nullptr && used_ > 0;
}
void WriteBufferAggregator::SetBuffer(char *buffer,
                                      uint16_t buffer_index,
                                      FileId file_id,
                                      uint64_t start_offset,
                                      bool use_fixed)
{
    buffer_ = buffer;
    buffer_index_ = buffer_index;
    use_fixed_ = use_fixed;
    file_id_ = file_id;
    start_offset_ = start_offset;
    next_offset_ = start_offset;
    used_ = 0;
    pages_.clear();
    release_ptrs_.clear();
    release_indices_.clear();
}
bool WriteBufferAggregator::CanAppend(FileId file_id,
                                      uint64_t offset,
                                      size_t size) const
{
    if (buffer_ == nullptr)
    {
        return false;
    }
    if (file_id != file_id_)
    {
        return false;
    }
    if (offset != next_offset_)
    {
        LOG(INFO) << "WriteBufferAggregator::CanAppend non-contiguous offset="
                  << offset << " expected=" << next_offset_
                  << " file_id=" << file_id_;
        return false;
    }
    if (used_ + size > buffer_size_)
    {
        return false;
    }
    return true;
}
char *WriteBufferAggregator::TryReserve(FileId file_id,
                                        uint64_t offset,
                                        size_t size)
{
    if (!CanAppend(file_id, offset, size))
    {
        return nullptr;
    }
    char *ptr = buffer_ + used_;
    used_ += size;
    next_offset_ += size;
    return ptr;
}
void WriteBufferAggregator::AddPage(VarPage page,
                                    char *release_ptr,
                                    uint16_t release_index)
{
    pages_.push_back(std::move(page));
    release_ptrs_.push_back(release_ptr);
    release_indices_.push_back(release_index);
}
bool WriteBufferAggregator::ShouldFlush(size_t next_size) const
{
    if (buffer_ == nullptr)
    {
        return false;
    }
    return used_ + next_size > buffer_size_;
}
WriteBufferBatch WriteBufferAggregator::TakeBatch()
{
    WriteBufferBatch batch;
    batch.buffer = buffer_;
    batch.buffer_index = buffer_index_;
    batch.use_fixed = use_fixed_;
    batch.file_id = file_id_;
    batch.start_offset = start_offset_;
    batch.bytes = used_;
    batch.pages = std::move(pages_);
    batch.release_ptrs = std::move(release_ptrs_);
    batch.release_indices = std::move(release_indices_);
    buffer_ = nullptr;
    buffer_index_ = 0;
    use_fixed_ = true;
    file_id_ = 0;
    start_offset_ = 0;
    next_offset_ = 0;
    used_ = 0;
    pages_.clear();
    release_ptrs_.clear();
    release_indices_.clear();
    return batch;
}
}  // namespace eloqstore

#include <algorithm>
#include "yaml-cpp/node/convert.h"
namespace {
// we're not gonna mess with the mess that is all the isupper/etc. functions
bool IsLower(char ch) { return 'a' <= ch && ch <= 'z'; }
bool IsUpper(char ch) { return 'A' <= ch && ch <= 'Z'; }
char ToLower(char ch) { return IsUpper(ch) ? ch + 'a' - 'A' : ch; }
std::string tolower(const std::string& str) {
  std::string s(str);
  std::transform(s.begin(), s.end(), s.begin(), ToLower);
  return s;
}
template <typename T>
bool IsEntirely(const std::string& str, T func) {
  for (std::size_t i = 0; i < str.size(); i++)
    if (!func(str[i]))
      return false;
  return true;
}
// IsFlexibleCase
// . Returns true if 'str' is:
//   . UPPERCASE
//   . lowercase
//   . Capitalized
bool IsFlexibleCase(const std::string& str) {
  if (str.empty())
    return true;
  if (IsEntirely(str, IsLower))
    return true;
  bool firstcaps = IsUpper(str[0]);
  std::string rest = str.substr(1);
  return firstcaps && (IsEntirely(rest, IsLower) || IsEntirely(rest, IsUpper));
}
}
namespace YAML {
bool convert<bool>::decode(const Node& node, bool& rhs) {
  if (!node.IsScalar())
    return false;
  // we can't use iostream bool extraction operators as they don't
  // recognize all possible values in the table below (taken from
  // http://yaml.org/type/bool.html)
  static const struct {
    std::string truename, falsename;
  } names[] = {
      {"y", "n"}, {"yes", "no"}, {"true", "false"}, {"on", "off"},
  };
  if (!IsFlexibleCase(node.Scalar()))
    return false;
  for (unsigned i = 0; i < sizeof(names) / sizeof(names[0]); i++) {
    if (names[i].truename == tolower(node.Scalar())) {
      rhs = true;
      return true;
    }
    if (names[i].falsename == tolower(node.Scalar())) {
      rhs = false;
      return true;
    }
  }
  return false;
}
}

#include "focuscontroller.hpp"
#include "application/model/clientmanager.hpp"
#include "application/model/focusedclientstack.hpp"
#include "application/model/kakouneclient.hpp"
void FocusController::init(FocusedClientStack *focused_client_stack, ClientManager *client_manager,
                           PaneLayout *layout_controller, domain::Window *window) {
    m_focused_client_stack = focused_client_stack;
    m_pane_layout = layout_controller;
    m_client_manager = client_manager;
    m_client_manager->onClientAdded([this](KakouneClient *client) {
        m_focused_client_stack->focus(client);
    });
    m_client_manager->onClientRemoved([this](KakouneClient *client) {
        m_focused_client_stack->remove(client);
    });
    window->onMouseMove([this](float x, float y) {
        onMouseMove(x, y);
    });
    window->onMouseButton([this](domain::MouseButtonEvent event) {
        onMouseButton(event);
    });
}
void FocusController::onMouseMove(float x, float y) {
    if (m_is_mouse_pressed) {
        return;
    }
    Pane *pane = m_pane_layout->findPaneAt(x, y);
    if (pane && pane->client != m_focused_client_stack->focused()) {
        m_focused_client_stack->focus(pane->client);
    }
}
void FocusController::onMouseButton(domain::MouseButtonEvent event) {
    if (event.action == domain::MouseButtonAction::PRESS) {
        m_is_mouse_pressed = true;
    } else if (event.action == domain::MouseButtonAction::RELEASE) {
        m_is_mouse_pressed = false;
        onMouseMove(event.x, event.y);
    }
}

class Solution {
public:
       int subarrayBitwiseORs(vector<int> A) {
        unordered_set<int> res, cur, cur2;
        for (int i: A) {
            cur2 = {i};
            for (int j: cur) cur2.insert(i|j);
            for (int j: cur = cur2) res.insert(j);
        }
        return res.size();
    }
};

