#include <cstring>
#include <fcntl.h>
namespace Core {
    namespace Network {
        TCPServer::TCPServer(int port) {
            server_fd = socket(AF_INET, SOCK_STREAM, 0);
            if (server_fd == -1) {
                success = false;
                return;
            }

            addr = {};
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = INADDR_ANY;
            addr.sin_port = htons(port);
            if (bind(server_fd, (sockaddr*)&addr, sizeof(addr)) < 0) {
                success = false;
                return;
            }
            success = true;
        }
        TCPServer::~TCPServer() {
            if (client_fd > 0) close(client_fd);
            if (server_fd > 0) close(server_fd);
            client_fd = -1;
            server_fd = -1;
        }
        std::string TCPServer::getHostName() {
            struct in_addr host_id;
            host_id.s_addr = gethostid();
            if (host_id.s_addr == INADDR_NONE)
                return "";
            return std::string(inet_ntoa(host_id));
        }
        bool TCPServer::waitConnection(WaitConnectionCallback callback) {
            aborted = false;
            if (listen(server_fd, 1) < 0)
                return false;
            fd_set set;
            timeval timeout;
            while (true) {
                if (callback != nullptr && !callback()) {
                    aborted = true;
                    return false;
                }
                FD_ZERO(&set);
                FD_SET(server_fd, &set);
                int waitMs = 100;
                timeout.tv_sec = waitMs / 1000;
                timeout.tv_usec = (waitMs % 1000) * 1000;
                int rv = select(server_fd + 1, &set, nullptr, nullptr, &timeout);
                if (rv == -1)
                    return false;
                else if (rv == 0)
                    continue;
                else {
                    client_fd = accept(server_fd, nullptr, nullptr);
                    if (client_fd < 0)
                        return false;
                    break;
                }
            }
            return true;
        }
        bool TCPServer::send_all(void *data, size_t size) {
            const char* ptr = reinterpret_cast<const char*>(data);
            size_t total_sent = 0;
            while (total_sent < size) {
                ssize_t sent = send(client_fd, ptr + total_sent, size - total_sent, 0);
                if (sent < 0) {
                    if (errno == EINTR)
                        continue;
                    return false;
                }
                if (sent == 0)
                    return false;
                total_sent += sent;
            }
            return true;
        }
        bool TCPServer::recv(void *buffer, size_t size) {
            size_t bytesRead = 0;
            while (bytesRead < size) {
                size_t len = read(client_fd, (char*)buffer + bytesRead, size - bytesRead);
                if (len <= 0)
                    return false;
                bytesRead += len;
            }
            return bytesRead == size;
        }
    }
}

#include "pybind11_qt/pybind11_qt_basic.h"
#include <type_traits>
#include <pybind11/stl/filesystem.h>
#include "pybind11_qt/details/pybind11_qt_utils.h"
// need to import containers to get QVariantList and QVariantMap
#include "pybind11_qt/pybind11_qt_containers.h"
namespace pybind11::detail {
    template <class CharT>
    QString qstring_from_stdstring(std::basic_string<CharT> const& s)
    {
        if constexpr (std::is_same_v<CharT, char>) {
            return QString::fromStdString(s);
        }
        else if constexpr (std::is_same_v<CharT, wchar_t>) {
            return QString::fromStdWString(s);
        }
        else if constexpr (std::is_same_v<CharT, char16_t>) {
            return QString::fromStdU16String(s);
        }
        else if constexpr (std::is_same_v<CharT, char32_t>) {
            return QString::fromStdU32String(s);
        }
    }
    /**
     * Conversion part 1 (Python->C++): convert a PyObject into a QString
     * instance or return false upon failure. The second argument
     * indicates whether implicit conversions should be applied.
     */
    bool type_caster<QString>::load(handle src, bool)
    {
        PyObject* objPtr = src.ptr();
        if (PyBytes_Check(objPtr)) {
            value = QString::fromUtf8(PyBytes_AsString(objPtr));
            return true;
        }
        else if (PyUnicode_Check(objPtr)) {
            switch (PyUnicode_KIND(objPtr)) {
            case PyUnicode_1BYTE_KIND:
                value = QString::fromUtf8(PyUnicode_AsUTF8(objPtr));
                break;
            case PyUnicode_2BYTE_KIND:
                value = QString::fromUtf16(
                    reinterpret_cast<char16_t*>(PyUnicode_2BYTE_DATA(objPtr)),
                    PyUnicode_GET_LENGTH(objPtr));
                break;
            case PyUnicode_4BYTE_KIND:
                value = QString::fromUcs4(
                    reinterpret_cast<char32_t*>(PyUnicode_4BYTE_DATA(objPtr)),
                    PyUnicode_GET_LENGTH(objPtr));
                break;
            default:
                return false;
            }
            return true;
        }
        else {
            return false;
        }
    }
    /**
     * Conversion part 2 (C++ -> Python): convert an QString instance into
     * a Python object. The second and third arguments are used to
     * indicate the return value policy and parent object (for
     * ``return_value_policy::reference_internal``) and are generally
     * ignored by implicit casters.
     */
    handle type_caster<QString>::cast(QString src, return_value_policy /* policy */,
                                      handle /* parent */)
    {
        return PyUnicode_DecodeUTF16(reinterpret_cast<const char*>(src.utf16()),
                                     2 * src.length(), nullptr, 0);
    }
    bool type_caster<QVariant>::load(handle src, bool)
    {
        // test for string first otherwise PyList_Check also works
        if (PyBytes_Check(src.ptr()) || PyUnicode_Check(src.ptr())) {
            value = src.cast<QString>();
            return true;
        }
        else if (PySequence_Check(src.ptr())) {
            // we could check if all the elements can be converted to QString
            // and store a QStringList in the QVariant but I am not sure that is
            // really useful.
            value = src.cast<QVariantList>();
            return true;
        }
        else if (PyMapping_Check(src.ptr())) {
            value = src.cast<QVariantMap>();
            return true;
        }
        else if (src.is(pybind11::none())) {
            value = QVariant();
            return true;
        }
        else if (PyDict_Check(src.ptr())) {
            value = src.cast<QVariantMap>();
            return true;
        }
        // PyBool will also return true for PyLong_Check but not the other way
        // around, so the order here is relevant.
        else if (PyBool_Check(src.ptr())) {
            value = src.cast<bool>();
            return true;
        }
        else if (PyLong_Check(src.ptr())) {
            // QVariant doesn't have long. It has int or long long. Given that
            // on m/s, long is 32 bits for 32- and 64- bit code...
            value = src.cast<int>();
            return true;
        }
        else {
            return false;
        }
    }
    handle type_caster<QVariant>::cast(QVariant var, return_value_policy policy,
                                       handle parent)
    {
        switch (var.typeId()) {
        case QMetaType::UnknownType:
            return Py_None;
        case QMetaType::Int:
            return PyLong_FromLong(var.toInt());
        case QMetaType::UInt:
            return PyLong_FromUnsignedLong(var.toUInt());
        case QMetaType::Bool:
            return PyBool_FromLong(var.toBool());
        case QMetaType::QString:
            return type_caster<QString>::cast(var.toString(), policy, parent);
        // We need to check for StringList here because these are not considered
        // List since List is QList<QVariant> will StringList is QList<QString>:
        case QMetaType::QStringList:
            return type_caster<QStringList>::cast(var.toStringList(), policy, parent);
        case QMetaType::QVariantList:
            return type_caster<QVariantList>::cast(var.toList(), policy, parent);
        case QMetaType::QVariantMap:
            return type_caster<QVariantMap>::cast(var.toMap(), policy, parent);
        default: {
            PyErr_Format(PyExc_TypeError, "type unsupported: %d", var.userType());
            throw pybind11::error_already_set();
        }
        }
    }
}  // namespace pybind11::detail

bool X3DImporter::FindNodeElement_FromRoot(const std::string &pID, const X3DElemType pType, X3DNodeElementBase **pElement) {
    for (std::list<X3DNodeElementBase *>::iterator it = NodeElement_List.begin(); it != NodeElement_List.end(); ++it) {
        if (((*it)->Type == pType) && ((*it)->ID == pID)) {
            if (pElement != nullptr) *pElement = *it;
            return true;
        }
    } // for(std::list<CX3DImporter_NodeElement*>::iterator it = NodeElement_List.begin(); it != NodeElement_List.end(); it++)
    return false;
}
bool X3DImporter::FindNodeElement_FromNode(X3DNodeElementBase *pStartNode, const std::string &pID,
        const X3DElemType pType, X3DNodeElementBase **pElement) {
    bool found = false; // flag: true - if requested element is found.
    // Check if pStartNode - this is the element, we are looking for.
    if ((pStartNode->Type == pType) && (pStartNode->ID == pID)) {
        found = true;
        if (pElement != nullptr) {
            *pElement = pStartNode;
        }
        goto fne_fn_end;
    } // if((pStartNode->Type() == pType) && (pStartNode->ID() == pID))
    // Check childs of pStartNode.
    for (std::list<X3DNodeElementBase *>::iterator ch_it = pStartNode->Children.begin(); ch_it != pStartNode->Children.end(); ++ch_it) {
        found = FindNodeElement_FromNode(*ch_it, pID, pType, pElement);
        if (found) {
            break;
        }
    } // for(std::list<CX3DImporter_NodeElement*>::iterator ch_it = it->Children.begin(); ch_it != it->Children.end(); ch_it++)
fne_fn_end:
    return found;
}
bool X3DImporter::FindNodeElement(const std::string &pID, const X3DElemType pType, X3DNodeElementBase **pElement) {
    X3DNodeElementBase *tnd = mNodeElementCur; // temporary pointer to node.
    bool static_search = false; // flag: true if searching in static node.
    // At first check if we have deal with static node. Go up through parent nodes and check flag.
    while (tnd != nullptr) {
        if (tnd->Type == X3DElemType::ENET_Group) {
            if (((X3DNodeElementGroup *)tnd)->Static) {
                static_search = true; // Flag found, stop walking up. Node with static flag will holded in tnd variable.
                break;
            }
        }
        tnd = tnd->Parent; // go up in graph.
    } // while (tnd != nullptr)
    // at now call appropriate search function.
    if (static_search) {
        return FindNodeElement_FromNode(tnd, pID, pType, pElement);
    } else {
        return FindNodeElement_FromRoot(pID, pType, pElement);
    }
}
