    String str = try$(Posix::resolve(url)).str();
    auto raw = ::open(str.buf(), O_RDWR | O_CREAT, 0644);
    if (raw < 0)
        return Posix::fromLastErrno();
    auto fd = makeRc<Posix::Fd>(raw);
    if (try$(fd->stat()).type == Type::DIR)
