    infos.name = Str::fromNullterminated(getenv("USER"));
    infos.home.scheme = "file"_sym;
    infos.home.path = Ref::Path::parse(getenv("HOME"));
    infos.shell.scheme = "file"_sym;
    infos.shell.path = Ref::Path::parse(getenv("SHELL"));
