    ftp.close();
    connection->close();
    connection = nullptr;
    throw;
  }
  ftp.close();
  connection->close();
  connection = nullptr;
}
void UnitTests::JSonLogTest() {
  auto connection =
      MavLinkConnection::connectSerial("px4", com_port_, baud_rate_);
  MavLinkFileLog log;
  auto tempPath = FileSystem::getTempFolder();
  tempPath = FileSystem::combine(tempPath, "test.mavlink");
  log.openForWriting(tempPath, true);
  int count = 0;
  Semaphore received;
  auto id = connection->subscribe(
      [&](std::shared_ptr<MavLinkConnection> con, const MavLinkMessage& msg) {
        count++;
        log.write(msg);
        if (count > 50) {
          received.post();
        }
      });
  if (!received.timed_wait(30000)) {
    throw std::runtime_error("PX4 is not sending 50 messages in 30 seconds.");
  }
  connection->unsubscribe(id);
  connection->close();
  log.close();
  // Now verification
  nlohmann::json doc;
  std::ifstream s;
  FileSystem::openTextFile(tempPath, s);
  if (!s.fail()) {
    s >> doc;
  } else {
    throw std::runtime_error(
        Utils::stringf("Cannot open json file at '%s'.", tempPath.c_str()));
  }
  if (doc.count("rows") == 1) {
    nlohmann::json rows = doc["rows"].get<nlohmann::json>();
    int found = 0;
    int imu = 0;
    if (rows.is_array()) {
      size_t size = rows.size();
      for (size_t i = 0; i < size; i++) {
        auto ptr = rows[i];
        if (ptr.is_object()) {
          if (ptr.count("name") == 1) {
            auto name = ptr["name"].get<std::string>();
            if (name == "HIGHRES_IMU") {
              imu++;
            }
            found++;
          }
        }
      }
    }
    printf("found %d valid rows in the json file, and %d HIGHRES_IMU records\n",
           found, imu);
  }
}

