    end = input.find(delimiter, start);
    size_t count = (end == std::string::npos) ? std::string::npos : end - start;
    strings.push_back(input.substr(start, count));
    start = end + delimiter.size();
  }
  return strings;
}
}  // namespace String
}  // namespace Zeal

