      MGM_ARG("result", String, Mandatory, "Result"), MGM_END()};
  const Properties *prop;
  prop = ndb_mgm_call(handle, reply, "get connection parameter", &args);
  CHECK_REPLY(handle, prop, -3);
  int res = -1;
  do {
