namespace {
void assignError(std::string* error, const std::string& message) {
	if (error != nullptr) {
		*error = message;
	}
}
std::string makeWin32ErrorMessage(const char* phase, DWORD err) {
	std::ostringstream oss;
	oss << phase << " failed, err=" << err;
	return oss.str();
}
}  // namespace
namespace infra {
namespace win {
namespace capture {
bool captureDesktopRectBgr(const RECT& screenRect, cv::Mat* outBgr, std::string* error) {
	if (outBgr == nullptr) {
		assignError(error, "capture output pointer is null");
		return false;
	}
	outBgr->release();
	const int width = screenRect.right - screenRect.left;
	const int height = screenRect.bottom - screenRect.top;
	if (width <= 1 || height <= 1 || width > 9999 || height > 9999) {
		std::ostringstream oss;
		oss << "invalid capture rect: left=" << screenRect.left
			<< ", top=" << screenRect.top
			<< ", right=" << screenRect.right
			<< ", bottom=" << screenRect.bottom;
		assignError(error, oss.str());
		return false;
	}
	HDC screenDc = GetDC(nullptr);
	if (screenDc == nullptr) {
		assignError(error, makeWin32ErrorMessage("GetDC", GetLastError()));
		return false;
	}
	HDC memDc = CreateCompatibleDC(screenDc);
	if (memDc == nullptr) {
		assignError(error, makeWin32ErrorMessage("CreateCompatibleDC", GetLastError()));
		ReleaseDC(nullptr, screenDc);
		return false;
	}
	HBITMAP bitmap = CreateCompatibleBitmap(screenDc, width, height);
	if (bitmap == nullptr) {
		assignError(error, makeWin32ErrorMessage("CreateCompatibleBitmap", GetLastError()));
		DeleteDC(memDc);
		ReleaseDC(nullptr, screenDc);
		return false;
	}
	HGDIOBJ oldObj = SelectObject(memDc, bitmap);
	if (oldObj == nullptr || oldObj == HGDI_ERROR) {
		assignError(error, makeWin32ErrorMessage("SelectObject", GetLastError()));
		DeleteObject(bitmap);
		DeleteDC(memDc);
		ReleaseDC(nullptr, screenDc);
		return false;
	}
	if (BitBlt(
		memDc,
		0,
		0,
		width,
		height,
		screenDc,
		screenRect.left,
		screenRect.top,
		SRCCOPY | CAPTUREBLT) == FALSE) {
		assignError(error, makeWin32ErrorMessage("BitBlt", GetLastError()));
		SelectObject(memDc, oldObj);
		DeleteObject(bitmap);
		DeleteDC(memDc);
		ReleaseDC(nullptr, screenDc);
		return false;
	}
	BITMAPINFOHEADER bi{};
	bi.biSize = sizeof(BITMAPINFOHEADER);
	bi.biWidth = width;
	bi.biHeight = -height;  // top-down
	bi.biPlanes = 1;
	bi.biBitCount = 32;
	bi.biCompression = BI_RGB;
	cv::Mat bgra(height, width, CV_8UC4);
	const int dibRc = GetDIBits(
		memDc,
		bitmap,
		0,
		static_cast<UINT>(height),
		bgra.data,
		reinterpret_cast<BITMAPINFO*>(&bi),
		DIB_RGB_COLORS);
	SelectObject(memDc, oldObj);
	DeleteObject(bitmap);
	DeleteDC(memDc);
	ReleaseDC(nullptr, screenDc);
	if (dibRc == 0) {
		assignError(error, makeWin32ErrorMessage("GetDIBits", GetLastError()));
		return false;
	}
	cv::cvtColor(bgra, *outBgr, cv::COLOR_BGRA2BGR);
	if (outBgr->empty()) {
		assignError(error, "capture produced empty image");
		return false;
	}
	return true;
}
}  // namespace capture
}  // namespace win
}  // namespace infra

#include "meta_ham/MoveRatingHistory.h"
#include "meta/FixedSizeSaveable.h"
#include "meta/FixedSizeSaveableStream.h"
void MoveRatingHistory::SaveFixed(FixedSizeSaveableStream &fs) const {
    int size = unk8.size();
    static int sMaxSize = 0x4000;
    if (size > 0x4000) {
        MILO_NOTIFY(
            "The move awards history size is greater than the maximum supplied! size=%i max=%i",
            size,
            sMaxSize
        );
        size = 0x4000;
    }
    fs.Tell();
    fs << size;
    FOREACH (it, unk8) {
        FixedSizeSaveable::SaveSymbolID(fs, it->first.unk0);
        for (int i = 0; i < 4; i++) {
            fs << it->second.unk0[i];
        }
    }
    if (size < 0x4000) {
        FixedSizeSaveable::PadStream(fs, (0x4000 - size) * 20);
    }
    const_cast<MoveRatingHistory *>(this)->unk20 = false;
}
void MoveRatingHistory::LoadFixed(FixedSizeSaveableStream &fs, int i2) {
    if (unk8.size() > 0) {
        MILO_NOTIFY("Move award history map is not empty on load!");
        unk8.clear();
    }
    int size;
    fs >> size;
    for (int i = 0; i < size; i++) {
        Key key;
        FixedSizeSaveable::LoadSymbolFromID(fs, key.unk0);
        for (int j = 0; j < 4; j++) {
            fs >> (int &)unk8[key].unk0[j];
        }
    }
    if (size < 0x4000) {
        FixedSizeSaveable::DepadStream(fs, (0x4000 - size) * 20);
    }
}
void MoveRatingHistory::Clear() {
    unk8.clear();
    unk20 = false;
}
int MoveRatingHistory::GetRating(Symbol s1, int i2) {
    Key key;
    key.unk0 = s1;
    if (HasRatingHistory(key)) {
        return unk8[key].unk0[i2];
    } else {
        return -1;
    }
}
int MoveRatingHistory::SaveSize(int) { return 0x50004; }
void MoveRatingHistory::AddHistory(Symbol s1, int i2) {
    Key key;
    key.unk0 = s1;
    RatingHistory &history = unk8[key];
    MoveRating old = history.unk0[0];
    history.unk0[1] = old;
    history.unk0[2] = old;
    history.unk0[3] = old;
    history.unk0[0] = (MoveRating)i2;
    unk20 = true;
}

#include <SavePlayerDataProcessor.h>
#include <google/protobuf/util/json_util.h>
#include <PlayerDatabase.h>
#include <PlayerData.pb.h>
static const std::string endOfConfigJson = "\"inputBindingsVersion\": 3";
SavePlayerDataProcessor::SavePlayerDataProcessor(SpectreRpcType rpcType) :
	WebsocketPacketProcessor(rpcType) {
}
void SavePlayerDataProcessor::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
	const char* strbegin = reinterpret_cast<const char*>(packet.GetRawBuffer()->cdata().data());
	std::string reqFormatted = "{\"playerId\": \"" + sock.GetPlayerId() + "\",\"data\":";
	int index = 0;
	char curChar;
	for (; index < packet.GetRawBuffer()->size(); index++) {
		curChar = strbegin[index];
		if (curChar == '\"' && strbegin[index + 1] == '{') {
			index++; // skip the " character at the start of data str
			break;
		}
	}
	for (; index < packet.GetRawBuffer()->size(); index++) {
		curChar = strbegin[index];
		if (curChar == '\\') {
			if (strbegin[index + 1] == '\"') {
				reqFormatted += '\"';
			}
			index++;
		}
		else if (curChar == '}') {
			if (reqFormatted.compare(reqFormatted.size() - endOfConfigJson.size(), endOfConfigJson.size(), endOfConfigJson.c_str()) == 0) {
				reqFormatted += curChar;
				index += 2;
				break;
			}
			else {
				reqFormatted += curChar;
			}
		}
		else {
			reqFormatted += curChar;
		}
	}
	for (; index < packet.GetRawBuffer()->size() - 1; index++) {
		curChar = strbegin[index];
		reqFormatted += curChar;
	}
	PlayerData playerData;
	auto status = pbuf::util::JsonStringToMessage(reqFormatted, &playerData);
	if (!status.ok()) {
		spdlog::error("failed to read PlayerConfigData in SavePlayerDataProcessor: {}", status.message());
		throw;
	}
	// mt does this thing where they leave all the other fields blank if they just want to update the data str
	if (playerData.attackeroutfitloadoutid() == "") {
		// Only copy the extra data field
		std::unique_ptr<PlayerData> existingData = PlayerDatabase::Get().GetField<PlayerData>(FieldKey::PLAYER_DATA, sock.GetPlayerId());
		existingData->mutable_data()->CopyFrom(playerData.data());
		PlayerDatabase::Get().SetField(FieldKey::PLAYER_DATA, existingData.get(), sock.GetPlayerId());
	}
	else {
		spdlog::warn("attacker outfit loadout id set in SetPlayerData request from {}, this is not seen behavior, likely to cause bugs", sock.GetPlayerId());
		PlayerDatabase::Get().SetField(FieldKey::PLAYER_DATA, &playerData, sock.GetPlayerId());
	}
	std::shared_ptr<json> res = packet.GetBaseJsonResponse();
	(*res)["payload"]["success"] = true;
	sock.SendPacket(res);
}

