void ios_base::clear(iostate state) {
  if (__rdbuf_)
    __rdstate_ = state;
  else
    __rdstate_ = state | badbit;
  if (((state | (__rdbuf_ ? goodbit : badbit)) & __exceptions_) != 0)
    std::__throw_failure("ios_base::clear");
}
