#include "shaderprogram.hpp"
#include "glm/gtc/type_ptr.hpp"
#include "opengl.hpp"
#include <stdexcept>
const char *vertexShaderSource = R"(
#version 330 core
layout (location = 0) in vec2 position;
layout (location = 1) in vec2 texCoords;
out vec2 TexCoords;
uniform mat4 projection;
void main()
{
    gl_Position = projection * vec4(position, 0.0, 1.0);
    TexCoords = texCoords;
}
)";
const char *fragmentShaderSource = R"(
#version 330 core
in vec2 TexCoords;
out vec4 color;
uniform sampler2D text;
uniform vec4 textColor;
uniform vec4 rectColor;
uniform int renderType;
uniform vec4 rectBounds;
uniform float shadowRadius; // Shadow blur radius in pixels
uniform vec4 cornerRadii; // top-left, top-right, bottom-right, bottom-left
float sdBox(vec2 p, vec2 b) {
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}
float sdRoundedBox(vec2 p, vec2 b, float r) {
    vec2 q = abs(p) - b + r;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
}
float sdRoundedBoxPerCorner(vec2 p, vec2 b, vec4 r) {
    float radius;
    if (p.x < 0.0 && p.y < 0.0) {
        radius = r.x; // top-left
    } else if (p.x >= 0.0 && p.y < 0.0) {
        radius = r.y; // top-right
    } else if (p.x >= 0.0 && p.y >= 0.0) {
        radius = r.z; // bottom-right
    } else {
        radius = r.w; // bottom-left
    }
    vec2 q = abs(p) - b + radius;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - radius;
}
void main()
{
   if (renderType == 0) { // Text
       vec4 sampled = vec4(1.0, 1.0, 1.0, texture(text, TexCoords).r);
       color = textColor * sampled;
   } else if (renderType == 1) { // ColoredText
       color = texture(text, TexCoords);
   } else if (renderType == 2) { // Rectangle
       color = rectColor;
   } else if (renderType == 3) { // Shadow
      vec2 rectPos = rectBounds.xy + rectBounds.zw * 0.5;
      vec2 rectSize = rectBounds.zw;
      vec2 pixelPos = gl_FragCoord.xy;
      vec2 localPos = pixelPos - rectPos;
      float dist = sdBox(localPos, rectSize * 0.5);
      float shadowAlpha = 1.0 - smoothstep(0.0, shadowRadius, dist);
      color = vec4(vec3(0.0), 0.25 * shadowAlpha);
   } else if (renderType == 4) { // RoundedRectangle
      vec2 rectPos = rectBounds.xy + rectBounds.zw * 0.5;
      vec2 rectSize = rectBounds.zw;
      vec2 pixelPos = gl_FragCoord.xy;
      vec2 localPos = pixelPos - rectPos;
      float dist = sdRoundedBoxPerCorner(localPos, rectSize * 0.5, cornerRadii);
      float alpha = 1.0 - smoothstep(-1.0, 1.0, dist);
      color = vec4(rectColor.rgb, rectColor.a * alpha);
   } else if (renderType == 5) { // RoundedShadow
      vec2 rectPos = rectBounds.xy + rectBounds.zw * 0.5;
      vec2 rectSize = rectBounds.zw;
      vec2 pixelPos = gl_FragCoord.xy;
      vec2 localPos = pixelPos - rectPos;
      float dist = sdRoundedBoxPerCorner(localPos, rectSize * 0.5, cornerRadii);
      float shadowAlpha = 1.0 - smoothstep(0.0, shadowRadius, dist);
      color = vec4(vec3(0.0), 0.25 * shadowAlpha);
   }
}
)";
opengl::ShaderProgram::ShaderProgram() {
}
void opengl::ShaderProgram::compile() {
    unsigned int vertexShader = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vertexShader, 1, &vertexShaderSource, NULL);
    glCompileShader(vertexShader);
    int success;
    char infoLog[512];
    glGetShaderiv(vertexShader, GL_COMPILE_STATUS, &success);
    if (!success)
    {
        glGetShaderInfoLog(vertexShader, 512, NULL, infoLog);
        throw std::runtime_error("Shader vertex compilation failed: " + std::string(infoLog));
    }
    unsigned int fragmentShader = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fragmentShader, 1, &fragmentShaderSource, NULL);
    glCompileShader(fragmentShader);
    glGetShaderiv(fragmentShader, GL_COMPILE_STATUS, &success);
    if (!success)
    {
        glGetShaderInfoLog(fragmentShader, 512, NULL, infoLog);
        throw std::runtime_error("Shader fragment compilation failed: " + std::string(infoLog));
    }
    m_shader_program = glCreateProgram();
    glAttachShader(m_shader_program, vertexShader);
    glAttachShader(m_shader_program, fragmentShader);
    glLinkProgram(m_shader_program);
    glGetProgramiv(m_shader_program, GL_LINK_STATUS, &success);
    if (!success)
    {
        glGetProgramInfoLog(m_shader_program, 512, NULL, infoLog);
        throw std::runtime_error("Shader program linking failed: " + std::string(infoLog));
    }
    glDeleteShader(vertexShader);
    glDeleteShader(fragmentShader);
    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
}
void opengl::ShaderProgram::use() {
    glUseProgram(m_shader_program);
}
void opengl::ShaderProgram::setRenderType(opengl::RenderType type) {
    setInt("renderType", (int)type);
    if (type == RenderType::ColoredText) {
        glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
    }else {
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    }
}
void opengl::ShaderProgram::setFloat(const std::string &name, float value) {
    glUniform1f(glGetUniformLocation(m_shader_program, name.c_str()), value);
}
void opengl::ShaderProgram::setInt(const std::string& name, int value) {
    glUniform1i(glGetUniformLocation(m_shader_program, name.c_str()), value);
}
void opengl::ShaderProgram::setVector4f(const std::string& name, float x, float y, float z, float w) {
    glUniform4f(glGetUniformLocation(m_shader_program, name.c_str()), x, y, z, w);
}
void opengl::ShaderProgram::setMatrix4(const std::string& name, const glm::mat4& mat)
{
    glUniformMatrix4fv(glGetUniformLocation(m_shader_program, "projection"), 1, GL_FALSE, glm::value_ptr(mat));
}

#include "client_singleton.h"
#include "SocketCommand.h"
bool ReadProcessMemoryBytes(uint64_t address, uint32_t size,
                            std::vector<unsigned char> &out, PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int handle) -> bool {
#pragma pack(1)
        struct { unsigned char command; CeReadProcessMemoryInput input; } op;
#pragma pack()
        op.command = CMD_READPROCESSMEMORY;
        op.input.handle = handle;
        op.input.address = address;
        op.input.size = size;
        op.input.compress = 0;
        if (!client->Send(&op, sizeof(op)))
            return false;
        CeReadProcessMemoryOutput outHdr{};
        if (!client->Receive(&outHdr, sizeof(outHdr)))
            return false;
        out.resize(size);
        client->Receive(out.data(), out.size());
        if (outHdr.read <= 0) {
            out.clear();
            return false;
        }
        return true;
    });
}
bool WriteProcessMemoryBytes(uint64_t address, uint32_t size,
                             std::vector<unsigned char> &data, PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int handle) -> bool {
#pragma pack(1)
        struct { unsigned char command; CeWriteProcessMemoryInput input; } op;
#pragma pack()
        op.command = CMD_WRITEPROCESSMEMORY;
        op.input.handle = handle;
        op.input.address = address;
        op.input.size = size;
        if (!client->Send(&op, sizeof(op)))
            return false;
        client->Send(data.data(), data.size());
        CeWriteProcessMemoryOutput output;
        if (!client->Receive(&output, sizeof(output)))
            return false;
        return output.written == size;
    });
}
bool ReadProcessMemory_(uint64_t address, uint32_t size, void *out,
                        int32_t &Realread, PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int handle) -> bool {
#pragma pack(1)
        struct { unsigned char command; CeReadProcessMemoryInput input; } op;
#pragma pack()
        op.command = CMD_READPROCESSMEMORY;
        op.input.handle = handle;
        op.input.address = address;
        op.input.size = size;
        op.input.compress = 0;
        if (!client->Send(&op, sizeof(op)))
            return false;
        client->Receive(&Realread, sizeof(Realread));
        client->Receive(out, size);
        if (Realread <= 0)
            return false;
        return true;
    });
}
bool ReadBratchMemory(uint64_t address, uint32_t size,
                      std::vector<std::pair<uint64_t, std::vector<uint8_t>>> &out,
                      PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int handle) -> bool {
#pragma pack(1)
        struct { unsigned char command; int handle; uint64_t address; uint32_t size; } op;
#pragma pack()
        op.command = CMD_READBRATCHMEMORY;
        op.handle = handle;
        op.address = address;
        op.size = size;
        if (!client->Send(&op, sizeof(op)))
            return false;
        int len = 0;
        if (!client->Receive(&len, sizeof(len)))
            return false;
        if (len <= 0) {
            out.clear();
            return true;
        }
        out.resize(len);
        for (int i = 0; i < len; i++) {
            uint64_t addr = 0;
            std::vector<unsigned char> data(4096);
            if (!client->Receive(&addr, sizeof(addr)))
                return false;
            if (!client->Receive(data.data(), 4096))
                return false;
            out[i] = {addr, data};
        }
        return true;
    });
}
bool ReadBratchAddr(std::vector<std::pair<uint64_t, int32_t>> &addrs,
                    std::vector<std::pair<uint64_t, std::vector<uint8_t>>> &out,
                    PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int handle) -> bool {
        unsigned char command = CMD_READBRATCHADDR;
        if (!SocketCommand::sendCommandWithHandle(client, command, handle))
            return false;
        int len = addrs.size();
        if (!client->Send(&len, sizeof(len)))
            return false;
        std::vector<CeReadBratchAddr> input(len);
        for (int i = 0; i < len; i++) {
            input[i].addr = addrs[i].first;
            input[i].size = addrs[i].second;
        }
        if (!client->Send(input.data(), len * sizeof(CeReadBratchAddr)))
            return false;
        out.clear();
        out.resize(len);
        int result = 0;
        if (!client->Receive(&result, sizeof(result)))
            return false;
        for (int i = 0; i < len; i++) {
            uint64_t addr = 0;
            int32_t sz = input[i].size;
            std::vector<unsigned char> data(sz);
            if (!client->Receive(&addr, sizeof(addr)))
                return false;
            if (!client->Receive(data.data(), sz))
                return false;
            out[i] = {addr, data};
        }
        return true;
    });
}

#include "quadrants/rhi/amdgpu/amdgpu_device.h"
#include "quadrants/rhi/llvm/device_memory_pool.h"
#include "quadrants/jit/jit_module.h"
namespace quadrants {
namespace lang {
namespace amdgpu {
AmdgpuDevice::AmdgpuDevice() {
  // Initialize the device memory pool
  DeviceMemoryPool::get_instance(Arch::amdgpu, false /*merge_upon_release*/);
}
AmdgpuDevice::AllocInfo AmdgpuDevice::get_alloc_info(
    const DeviceAllocation handle) {
  validate_device_alloc(handle);
  return allocations_[handle.alloc_id];
}
RhiResult AmdgpuDevice::allocate_memory(const AllocParams &params,
                                        DeviceAllocation *out_devalloc) {
  AllocInfo info;
  auto &mem_pool = DeviceMemoryPool::get_instance(Arch::amdgpu,
                                                  false /*merge_upon_release*/);
  bool managed = params.host_read || params.host_write;
  void *ptr =
      mem_pool.allocate(params.size, DeviceMemoryPool::page_size, managed);
  if (ptr == nullptr) {
    return RhiResult::out_of_memory;
  }
  info.ptr = ptr;
  info.size = params.size;
  info.is_imported = false;
  info.use_cached = false;
  info.use_preallocated = false;
  if (info.ptr == nullptr) {
    return RhiResult::out_of_memory;
  }
  AMDGPUDriver::get_instance().memset((void *)info.ptr, 0, info.size);
  *out_devalloc = DeviceAllocation{};
  out_devalloc->alloc_id = allocations_.size();
  out_devalloc->device = this;
  allocations_.push_back(info);
  return RhiResult::success;
}
DeviceAllocation AmdgpuDevice::allocate_memory_runtime(
    const LlvmRuntimeAllocParams &params) {
  AllocInfo info;
  info.size = quadrants::iroundup(params.size, quadrants_page_size);
  if (params.host_read || params.host_write) {
    QD_NOT_IMPLEMENTED
  } else {
    info.ptr = DeviceMemoryPool::get_instance(Arch::amdgpu,
                                              false /*merge_upon_release*/)
                   .allocate_with_cache(this, params);
    QD_ASSERT(info.ptr != nullptr);
    AMDGPUDriver::get_instance().memset((void *)info.ptr, 0, info.size);
  }
  info.is_imported = false;
  info.use_cached = true;
  info.use_preallocated = true;
  DeviceAllocation alloc;
  alloc.alloc_id = allocations_.size();
  alloc.device = this;
  allocations_.push_back(info);
  return alloc;
}
uint64_t *AmdgpuDevice::allocate_llvm_runtime_memory_jit(
    const LlvmRuntimeAllocParams &params) {
  params.runtime_jit->call<void *, std::size_t, std::size_t>(
      "runtime_memory_allocate_aligned", params.runtime, params.size,
      quadrants_page_size, params.result_buffer);
  AMDGPUDriver::get_instance().stream_synchronize(nullptr);
  uint64 *ret{nullptr};
  AMDGPUDriver::get_instance().memcpy_device_to_host(&ret, params.result_buffer,
                                                     sizeof(uint64));
  return ret;
}
void AmdgpuDevice::dealloc_memory(DeviceAllocation handle) {
  // After reset, all allocations are invalid
  if (allocations_.empty()) {
    return;
  }
  validate_device_alloc(handle);
  AllocInfo &info = allocations_[handle.alloc_id];
  if (info.ptr == nullptr) {
    QD_ERROR("the DeviceAllocation is already deallocated");
  }
  QD_ASSERT(!info.is_imported);
  if (info.use_cached) {
    DeviceMemoryPool::get_instance(Arch::amdgpu, false /*merge_upon_release*/)
        .release(info.size, (uint64_t *)info.ptr, false);
  } else if (!info.use_preallocated) {
    DeviceMemoryPool::get_instance(Arch::amdgpu, false /*merge_upon_release*/)
        .release(info.size, info.ptr);
  }
  info.ptr = nullptr;
}
RhiResult AmdgpuDevice::map(DeviceAllocation alloc, void **mapped_ptr) {
  AllocInfo &info = allocations_[alloc.alloc_id];
  size_t size = info.size;
  info.mapped = new char[size];
  // FIXME: there should be a better way to do this...
  AMDGPUDriver::get_instance().memcpy_device_to_host(info.mapped, info.ptr,
                                                     size);
  *mapped_ptr = info.mapped;
  return RhiResult::success;
}
void AmdgpuDevice::unmap(DeviceAllocation alloc) {
  AllocInfo &info = allocations_[alloc.alloc_id];
  AMDGPUDriver::get_instance().memcpy_host_to_device(info.ptr, info.mapped,
                                                     info.size);
  delete[] static_cast<char *>(info.mapped);
  return;
}
void AmdgpuDevice::memcpy_internal(DevicePtr dst,
                                   DevicePtr src,
                                   uint64_t size) {
  void *dst_ptr =
      static_cast<char *>(allocations_[dst.alloc_id].ptr) + dst.offset;
  void *src_ptr =
      static_cast<char *>(allocations_[src.alloc_id].ptr) + src.offset;
  AMDGPUDriver::get_instance().memcpy_device_to_device(dst_ptr, src_ptr, size);
}
DeviceAllocation AmdgpuDevice::import_memory(void *ptr, size_t size) {
  AllocInfo info;
  info.ptr = ptr;
  info.size = size;
  info.is_imported = true;
  DeviceAllocation alloc;
  alloc.alloc_id = allocations_.size();
  alloc.device = this;
  allocations_.push_back(info);
  return alloc;
}
}  // namespace amdgpu
}  // namespace lang
}  // namespace quadrants

#include "cpy.hpp"
#include <float.h>
#include "dequantize.hpp"
#include "ggml-sycl/common.hpp"
#include "ggml-sycl/presets.hpp"
#include "ggml.h"
static void cpy_1_f32_f32(const char * cxi, char * cdsti) {
    const float * xi   = (const float *) cxi;
    float *       dsti = (float *) cdsti;
    *dsti = *xi;
}
static void cpy_1_f32_f16(const char * cxi, char * cdsti) {
    const float * xi   = (const float *) cxi;
    sycl::half *  dsti = (sycl::half *) cdsti;
    *dsti = sycl::vec<float, 1>(*xi).convert<sycl::half, sycl::rounding_mode::automatic>()[0];
}
static void cpy_1_f16_f16(const char * cxi, char * cdsti) {
    const sycl::half * xi   = (const sycl::half *) cxi;
    sycl::half *       dsti = (sycl::half *) cdsti;
    *dsti = *xi;
}
static void cpy_1_f16_f32(const char * cxi, char * cdsti) {
    const sycl::half * xi   = (const sycl::half *) cxi;
    float *            dsti = (float *) cdsti;
    *dsti = *xi;
}
static void cpy_1_i16_i16(const char * cxi, char * cdsti) {
    const int16_t * xi   = (const int16_t *) cxi;
    int16_t *       dsti = (int16_t *) cdsti;
    *dsti = *xi;
}
static void cpy_1_i32_i32(const char * cxi, char * cdsti) {
    const int32_t * xi   = (const int32_t *) cxi;
    int32_t *       dsti = (int32_t *) cdsti;
    *dsti = *xi;
}
template <cpy_kernel_t cpy_1>
static void cpy_f32_f16(const char * cx, char * cdst, const int ne, const int ne00, const int ne01, const int ne02,
                        const int nb00, const int nb01, const int nb02, const int nb03, const int ne10, const int ne11,
                        const int ne12, const int nb10, const int nb11, const int nb12, const int nb13,
                        const sycl::nd_item<3> & item_ct1) {
    const int i = item_ct1.get_local_range(2) * item_ct1.get_group(2) + item_ct1.get_local_id(2);
    if (i >= ne) {
        return;
    }
    // determine indices i02/i12, i01/i11, i00/i10 as a function of index i of flattened tensor
    // then combine those indices with the corresponding byte offsets to get the total offsets
    const int i03      = i / (ne00 * ne01 * ne02);
    const int i02      = (i - i03 * ne00 * ne01 * ne02) / (ne00 * ne01);
    const int i01      = (i - i03 * ne00 * ne01 * ne02 - i02 * ne01 * ne00) / ne00;
    const int i00      = i - i03 * ne00 * ne01 * ne02 - i02 * ne01 * ne00 - i01 * ne00;
    const int x_offset = i00 * nb00 + i01 * nb01 + i02 * nb02 + i03 * nb03;
    const int i13        = i / (ne10 * ne11 * ne12);
    const int i12        = (i - i13 * ne10 * ne11 * ne12) / (ne10 * ne11);
    const int i11        = (i - i13 * ne10 * ne11 * ne12 - i12 * ne10 * ne11) / ne10;
    const int i10        = i - i13 * ne10 * ne11 * ne12 - i12 * ne10 * ne11 - i11 * ne10;
    const int dst_offset = i10 * nb10 + i11 * nb11 + i12 * nb12 + i13 * nb13;
    cpy_1(cx + x_offset, cdst + dst_offset);
}
/* quantized type same copy */
template<typename T>
static void cpy_blck_q_q(const char * cxi, char * cdsti) {
    const T * xi = (const T *) cxi;
    T * dsti = (T *) cdsti;
    *dsti = *xi;
}
static void cpy_blck_q8_0_f32(const char * cxi, char * cdsti) {
    float * cdstf = (float *) (cdsti);
    for (int j = 0; j < QK8_0; j += 2) {
        dfloat2 dq;
        dequantize_q8_0(cxi, 0, j, dq);
        *(cdstf + j)     = dq.x();
        *(cdstf + j + 1) = dq.y();
    }
}
template <dequantize_kernel_t dequant, int qk> static void cpy_blck_q_f32(const char * cxi, char * cdsti) {
    float * cdstf = (float *) (cdsti);
    for (int j = 0; j < qk / 2; j++) {
        dfloat2 dq;
        dequant(cxi, 0, j, dq);
        *(cdstf + j)          = dq.x();
        *(cdstf + j + qk / 2) = dq.y();
    }
}
template <typename T, int qk>
static void cpy_q_q(const char * cx, char * cdst, const int ne, const int ne00, const int ne01, const int ne02,
                      const int nb00, const int nb01, const int nb02, const int nb03, const int ne10, const int ne11,
                      const int ne12, const int nb10, const int nb11, const int nb12, const int nb13,
                      const sycl::nd_item<3> & item_ct1) {
    const int i = (item_ct1.get_local_range(2) * item_ct1.get_group(2) + item_ct1.get_local_id(2)) * qk;
    if (i >= ne) {
        return;
    }
    const int i03      = i / (ne00 * ne01 * ne02);
    const int i02      = (i - i03 * ne00 * ne01 * ne02) / (ne00 * ne01);
    const int i01      = (i - i03 * ne00 * ne01 * ne02 - i02 * ne01 * ne00) / ne00;
    const int i00      = i - i03 * ne00 * ne01 * ne02 - i02 * ne01 * ne00 - i01 * ne00;
    const int x_offset = (i00 / qk) * nb00 + i01 * nb01 + i02 * nb02 + i03 * nb03;
    const int i13        = i / (ne10 * ne11 * ne12);
    const int i12        = (i - i13 * ne10 * ne11 * ne12) / (ne10 * ne11);
    const int i11        = (i - i13 * ne10 * ne11 * ne12 - i12 * ne10 * ne11) / ne10;
    const int i10        = i - i13 * ne10 * ne11 * ne12 - i12 * ne10 * ne11 - i11 * ne10;
    const int dst_offset = (i10 / qk) * nb10 + i11 * nb11 + i12 * nb12 + i13 * nb13;
    cpy_blck_q_q<T>(cx + x_offset, cdst + dst_offset);
}
