#include "StdAfx.h"
#include "packet_decoder_mp3_common.h"
#include "mp3_utils.h"

unsigned packet_decoder_mp3_common::parseDecoderSetup( const GUID & p_owner,t_size p_param1,const void * p_param2,t_size p_param2size )
{
    if (p_owner == owner_MP3) return 3;
    else if (p_owner == owner_MP2) return 2;
    else if (p_owner == owner_MP1) return 1;
    else if (p_owner == owner_MP4)
    {
        switch(p_param1)
        {
			case 0x6B:
				return 3;
				break;
			case 0x69:
				return 3;
				break;
			default:
                return 0;
        }
    }
    else if (p_owner == owner_matroska)
    {
        if (p_param2size==sizeof(matroska_setup))
        {
            const matroska_setup * setup = (const matroska_setup*) p_param2;
            if (!strcmp(setup->codec_id,"A_MPEG/L3")) return 3;
            else if (!strcmp(setup->codec_id,"A_MPEG/L2")) return 2;
            else if (!strcmp(setup->codec_id,"A_MPEG/L1")) return 1;
            else return 0;
        }
        else return 0;
    }
    else return 0;
}

unsigned packet_decoder_mp3_common::layer_from_frame(const void * frame, size_t size) {
	using namespace mp3_utils;
	TMPEGFrameInfo info;
	if (!ParseMPEGFrameHeader(info, frame, size)) throw exception_io_data();
	return info.m_layer;
}

#include <gtest/gtest.h>
#include "SmallVector.h"
class SmallVectorTest : public ::testing::Test {
};
TEST_F(SmallVectorTest, PushBackClear) {
    SmallVector<int, 3> vec;
    vec.push_back(1);
    vec.push_back(2);
    vec.push_back(3);
    vec.push_back(4);
    vec.push_back(5);
    ASSERT_EQ(vec.size(), 5);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
    ASSERT_EQ(vec[2], 3);
    ASSERT_EQ(vec[3], 4);
    ASSERT_EQ(vec[4], 5);
    vec.clear();
    ASSERT_EQ(vec.size(), 0);
}
TEST_F(SmallVectorTest, SmallCapacity) {
    SmallVector<int, 4> vec;
    vec.push_back(1);
    vec.push_back(2);
    ASSERT_EQ(vec.size(), 2);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
}
TEST_F(SmallVectorTest, Empty) {
    SmallVector<int, 4> vec;
    ASSERT_TRUE(vec.empty());
    vec.push_back(1);
    ASSERT_FALSE(vec.empty());
    vec.clear();
    ASSERT_TRUE(vec.empty());
}
TEST_F(SmallVectorTest, Grow) {
    SmallVector<int, 4> vec;
    vec.push_back(1);
    vec.push_back(2);
    ASSERT_EQ(vec.size(), 2);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
    vec.push_back(3);
    vec.push_back(4);
    vec.push_back(5);
    ASSERT_EQ(vec.size(), 5);
    ASSERT_EQ(vec[0], 1);
    ASSERT_EQ(vec[1], 2);
    ASSERT_EQ(vec[2], 3);
    ASSERT_EQ(vec[3], 4);
    ASSERT_EQ(vec[4], 5);
    vec.clear();
    ASSERT_EQ(vec.size(), 0);
    vec.push_back(6);
    vec.push_back(7);
    vec.push_back(8);
    ASSERT_EQ(vec.size(), 3);
    ASSERT_EQ(vec[0], 6);
    ASSERT_EQ(vec[1], 7);
    ASSERT_EQ(vec[2], 8);
    vec.push_back(9);
    vec.push_back(10);
    vec.push_back(11);
    ASSERT_EQ(vec.size(), 6);
    ASSERT_EQ(vec[0], 6);
    ASSERT_EQ(vec[1], 7);
    ASSERT_EQ(vec[2], 8);
    ASSERT_EQ(vec[3], 9);
    ASSERT_EQ(vec[4], 10);
    ASSERT_EQ(vec[5], 11);
    vec.clear();
    ASSERT_EQ(vec.size(), 0);
}
TEST_F(SmallVectorTest, Iterator) {
    constexpr size_t SMALL_CAPACITY = 4;
    std::vector<int> vec;
    SmallVector<int, SMALL_CAPACITY> smallVec;
    // Small
    for (size_t i = 0; i < SMALL_CAPACITY; ++i) {
        smallVec.push_back(i);
        vec.push_back(i);
    }
    ASSERT_EQ(smallVec.size(), vec.size());
    ASSERT_EQ(smallVec, vec);
    size_t i = 0;
    for (auto it = smallVec.begin(); it != smallVec.end(); ++it, ++i) {
        ASSERT_EQ(*it, vec[i]);
    }
    i = 0;
    for (int x : smallVec) {
        ASSERT_EQ(x, vec[i]);
        ++i;
    }
}
TEST_F(SmallVectorTest, Map) {
    constexpr size_t size = 100000;
    SmallVector<int, 100> smallVec;
    for (size_t i = 0; i < size; ++i) {
        smallVec.push_back(i);
    }
    std::vector<int> vec;
    smallVec.map([&vec](int x) {
        vec.push_back(x);
    });
    ASSERT_EQ(smallVec, vec);
}

#include "Rect2i.h"
#include <algorithm>
#include <windows.h>
Rect2i::Rect2i(int x, int y, int width, int height) {
    xPos         = x;
    yPos         = y;
    this->width  = width;
    this->height = height;
}
Rect2i* Rect2i::intersect(const Rect2i* other) {
    int x0 = xPos;
    int y0 = yPos;
    int x1 = xPos + width;
    int y1 = yPos + height;
    int x2 = other->getX();
    int y2 = other->getY();
    int x3 = x2 + other->getWidth();
    int y3 = y2 + other->getHeight();
    xPos   = std::max(x0, x2);
    yPos   = std::max(y0, y2);
    width  = std::max(0, std::min(x1, x3) - xPos);
    height = std::max(0, std::min(y1, y3) - yPos);
    return this;
}
int Rect2i::getX() const { return xPos; }
int Rect2i::getY() const { return yPos; }
void Rect2i::setX(int x) { xPos = x; }
void Rect2i::setY(int y) { yPos = y; }
int Rect2i::getWidth() const { return width; }
int Rect2i::getHeight() const { return height; }
void Rect2i::setWidth(int width) { this->width = width; }
void Rect2i::setHeight(int height) { this->height = height; }
void Rect2i::setPosition(int x, int y) {
    xPos = x;
    yPos = y;
}

