#include "events.h"
namespace LVMon {
CEvents::CEvents(void) : conditionvariable_(), mutex_(), useventSet_() {}
CEvents::~CEvents() {}
bool CEvents::GetEventSet(CEvents::Event *peventRet) {
  bool fGotEvent = false;
  std::unique_lock<std::mutex> ul(mutex_);
  if (!useventSet_.empty()) {
    auto it = useventSet_.begin();
    *peventRet = *it;
    useventSet_.erase(it);
    ul.unlock();
    fGotEvent = true;
  }
  return (fGotEvent);
}
void CEvents::Set(Event event) {
  std::unique_lock<std::mutex> ul(mutex_);
  useventSet_.insert(event);
  conditionvariable_.notify_one();
}
void CEvents::Reset(Event event) {
  std::unique_lock<std::mutex> ul(mutex_);
  useventSet_.erase(event);
}
CEvents::WaitResult CEvents::Wait(Event event) {
  WaitResult waitresultRet = kWaitResultFail;
  std::unique_lock<std::mutex> ul(mutex_);
  conditionvariable_.wait(ul, [&]() {
    auto it = useventSet_.find(event);
    if (it == useventSet_.end())
      return (false);
    else {
      useventSet_.erase(event);
      waitresultRet = kWaitResultEvent0;
      return (true);
    }
  });
  return (waitresultRet);
}
CEvents::WaitResult CEvents::WaitForMultiple(size_t cevent, Event *rgevent) {
  WaitResult waitresultRet = kWaitResultFail;
  std::unique_lock<std::mutex> ul(mutex_);
  conditionvariable_.wait(ul, [&]() {
    for (auto *pevent = rgevent, *peventMax = rgevent + cevent;
         pevent < peventMax; ++pevent) {
      auto it = useventSet_.find(*pevent);
      if (it != useventSet_.end()) {
        useventSet_.erase(it);
        waitresultRet = kWaitResultEvent0 + (pevent - rgevent);
        return (true);
      }
    }
    return (false);
  });
  return (waitresultRet);
}
}  // namespace LVMon

class Solution {
public:
    bool isPalindrome(int x){
        if(x < 0) return false;
        if(x == 0) return true;

        // x is positive
        // let x = 453, 21......9
        // x_r   = 354, 9......12
        int last;
        long long int x_r = 0;
        int x_c = x;
        while(x_c > 0){ // O(number of digits in x), O(log(x))
            last = x_c % 10;        //   3,   5,   4
            x_c = x_c / 10;         // 45,   4,   0
            x_r = x_r * 10 + last;  // 3,   35, 354
            // delete from right of x, insert in right of x_r
        }
        // last = 4, leftmost digit of x
        // x_c = 0
        // x_r = 354
        if((long long int) x == x_r) return true;
        else return false;
    }
};

#include "Face3D.hpp"

using std::inner_product;
using namespace MadVoro;
 
MadVoro::Face3D::Face3D(point_vec_v const& vert,std::size_t neighbor1,std::size_t neighbor2):
  vertices(vert),neighbors(neighbor1,neighbor2) {}

Face3D& MadVoro::Face3D::operator=(const Face3D& other)
{
  vertices = other.vertices;
  neighbors = other.neighbors;
  return *this;
}

MadVoro::Face3D::Face3D(void): vertices(), neighbors() {}

MadVoro::Face3D::~Face3D(void)
{}

MadVoro::Face3D::Face3D(Face3D const& other):
  vertices(other.vertices),
  neighbors(other.neighbors) {}

double MadVoro::Face3D::GetArea(void) const
{
  const Point3D& ref = vertices[0];
  return inner_product(vertices.begin()+1,
		       vertices.end()-1,
		       vertices.begin()+2,
		       0,
		       [](const double x, const double y)
		       {return x+y;},
		       [&ref](const Point3D& u, const Point3D& v)
		       {return 0.5*fastabs(CrossProduct(u-ref,v-ref));});
}

Point3D calc_centroid(const Face3D& face)
{
  const Point3D& ref = face.vertices[0];
  return inner_product(face.vertices.begin()+1,
		       face.vertices.end()-1,
		       face.vertices.begin()+2,
		       Point3D(0,0,0),
		       [](const Point3D& x, const Point3D& y)
		       {return x+y;},
		       [&ref](const Point3D& u, const Point3D& v)
		       {
			 const double area = 0.5*fastabs
			   (CrossProduct(u-ref, v-ref));
			 return area*(u+v+ref)/3;
		       });
}

