popup_message_v3::query_t popup_message_v3::setupMessageBox(fb2k::hwnd_t parent, const char* msg, const char* title, unsigned flags) {
	query_t q = {};
	q.title = title;
	q.msg = msg;
	q.wndParent = parent;

	switch (flags & 0xF) {
	default:
	case MB_OK:
		q.buttons = buttonOK;
		q.defButton = buttonOK;
		break;
	case MB_OKCANCEL:
		q.buttons = buttonOK | buttonCancel;
		q.defButton = (flags & MB_DEFBUTTON2) ? buttonCancel : buttonOK;
		break;
	case MB_ABORTRETRYIGNORE:
		q.buttons = buttonAbort | buttonRetry | buttonIgnore;
		if (flags & MB_DEFBUTTON3) q.defButton = buttonIgnore;
		else if (flags & MB_DEFBUTTON2) q.defButton = buttonRetry;
		else q.defButton = buttonAbort;
		break;
	case MB_YESNOCANCEL:
		q.buttons = buttonYes | buttonNo | buttonCancel;
		if (flags & MB_DEFBUTTON3) q.defButton = buttonCancel;
		else if (flags & MB_DEFBUTTON2) q.defButton = buttonNo;
		else q.defButton = buttonYes;
		break;
	case MB_YESNO:
		q.buttons = buttonYes | buttonNo;
		q.defButton = (flags & MB_DEFBUTTON2) ? buttonNo : buttonYes;
		break;
	case MB_RETRYCANCEL:
		q.buttons = buttonRetry | buttonCancel;
		q.defButton = (flags & MB_DEFBUTTON2) ? buttonCancel : buttonRetry;
		break;
	}
	switch (flags & 0xF0) {
	case MB_ICONHAND:
		q.icon = iconError;
		break;
	case MB_ICONQUESTION:
		q.icon = iconQuestion;
		break;
	case MB_ICONEXCLAMATION:
		q.icon = iconWarning;
		break;
	case MB_ICONASTERISK:
		q.icon = iconInformation;
		break;
	}

	return q;
}
int popup_message_v3::messageBoxReply(uint32_t status) {
	if (status & buttonOK) return IDOK;
	if (status & buttonCancel) return IDCANCEL;
	if (status & buttonYes) return IDYES;
	if (status & buttonNo) return IDNO;
	if (status & buttonRetry) return IDRETRY;
	if (status & buttonAbort) return IDABORT;
	if (status & buttonIgnore) return IDIGNORE;

	return -1;
}
void popup_message_v3::messageBoxAsync(fb2k::hwnd_t parent, const char* msg, const char* title, unsigned flags, std::function<void (int)> reply) {
	PFC_ASSERT( core_api::is_main_thread() );
	auto q = setupMessageBox(parent, msg, title, flags);
	if (reply) {
		q.reply = fb2k::makeCompletionNotify([reply](unsigned code) {
			reply(messageBoxReply(code));
			});
	}
	this->show_query(q);
}
int popup_message_v3::messageBox(fb2k::hwnd_t parent, const char* msg, const char* title, unsigned flags) {
	PFC_ASSERT( core_api::is_main_thread() );
	auto q = setupMessageBox(parent, msg, title, flags);
	uint32_t status = this->show_query_modal(q);
	return messageBoxReply(status);
}

#if MODE_METABALLS
#include "modes/MetaballsMode.h"
#include "extensions/MicrophoneExtension.h"
#include "services/DisplayService.h" // NOLINT(misc-include-cleaner)
void MetaballsMode::configure()
{
    for (uint16_t i = 0; i < contributions.size(); ++i)
    {
        contributions[i] = ((UINT8_MAX - i) * (UINT8_MAX - i) * (1U << 6U)) >> 16U;
    }
    for (Ball &ball : balls)
    {
        ball.x = static_cast<float>(random(GRID_COLUMNS));
        ball.y = static_cast<float>(random(GRID_ROWS));
        ball.xVelocity = speed * static_cast<float>(random(1, multiplier) * ((random(2) * 2) - 1));
        ball.yVelocity = speed * static_cast<float>(random(1, multiplier) * ((random(2) * 2) - 1));
    }
}
void MetaballsMode::handle()
{
#if EXTENSION_MICROPHONE
    if (Microphone->isTriggered())
#endif // EXTENSION_MICROPHONE
    {
#if PITCH_HORIZONTAL != PITCH_VERTICAL
        const bool rotated = (static_cast<uint8_t>(Display.getOrientation()) % 2) != 0;
        const float xRatio = static_cast<float>(2 * (rotated ? PITCH_VERTICAL : PITCH_HORIZONTAL)) /
                             static_cast<float>(PITCH_VERTICAL + PITCH_HORIZONTAL);
        const float yRatio = static_cast<float>(2 * (rotated ? PITCH_HORIZONTAL : PITCH_VERTICAL)) /
                             static_cast<float>(PITCH_VERTICAL + PITCH_HORIZONTAL);
#endif // PITCH_HORIZONTAL == PITCH_VERTICAL
        for (const Ball &ball : balls)
        {
            const uint8_t xMin = max<int8_t>(ball.x - radius - max<float>(ball.xVelocity, 0), 0);
            const uint8_t yMin = max<int8_t>(ball.y - radius - max<float>(ball.yVelocity, 0), 0);
            const uint8_t xMax = min<int8_t>(ceilf(ball.x + radius - min<float>(ball.xVelocity, 0)), GRID_COLUMNS - 1);
            const uint8_t yMax = min<int8_t>(ceilf(ball.y + radius - min<float>(ball.yVelocity, 0)), GRID_ROWS - 1);
            for (uint8_t x = xMin; x <= xMax; ++x)
            {
                for (uint8_t y = yMin; y <= yMax; ++y)
                {
                    uint8_t brightness = 0;
                    for (const Ball &ball : balls)
                    {
#if PITCH_HORIZONTAL == PITCH_VERTICAL
                        const float xDistance = (ball.x - static_cast<float>(x));
                        const float yDistance = (ball.y - static_cast<float>(y));
#else
                        const float xDistance = (ball.x - static_cast<float>(x)) * xRatio;
                        const float yDistance = (ball.y - static_cast<float>(y)) * yRatio;
#endif // PITCH_HORIZONTAL == PITCH_VERTICAL
                        const float distanceSq = (xDistance * xDistance) + (yDistance * yDistance);
                        if (distanceSq < radiusSq)
                        {
                            brightness = min<uint8_t>(
                                brightness + contributions[static_cast<uint8_t>(distanceSq * UINT8_MAX / radiusSq)],
                                UINT8_MAX);
                            if (brightness >= UINT8_MAX)
                            {
                                break;
                            }
                        }
                    }
                    Display.setPixel(x, y, brightness);
                }
            }
        }
        for (Ball &ball : balls)
        {
            ball.x += ball.xVelocity;
            ball.y += ball.yVelocity;
            if (ball.x < 0)
            {
                ball.x = 0;
                ball.xVelocity = speed * static_cast<float>(random(1, multiplier));
            }
            else if (ball.x > GRID_COLUMNS - 1)
            {
                ball.x = GRID_COLUMNS - 1;
                ball.xVelocity = -speed * static_cast<float>(random(1, multiplier));
            }
            if (ball.y < 0)
            {
                ball.y = 0;
                ball.yVelocity = speed * static_cast<float>(random(1, multiplier));
            }
            else if (ball.y > GRID_ROWS - 1)
            {
                ball.y = GRID_ROWS - 1;
                ball.yVelocity = -speed * static_cast<float>(random(1, multiplier));
            }
        }
    }
}
