    auto expr2 = symbolic::add(offset_32, symbolic::mul(stride_3, offset_28));
    expr2 = symbolic::add(expr2, symbolic::mul(symbolic::mul(stride_3, stride_2), _24));
    expr2 = symbolic::add(expr2, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));
    EXPECT_FALSE(symbolic::maps::intersects({expr1}, {expr2}, _13, assums1, assums2));
    EXPECT_TRUE(symbolic::maps::intersects({expr1}, {expr2}, _24, assums1, assums2));
    // 1 + _32 + (2 + _3)*_28 + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expr3 = symbolic::add(offset_32, symbolic::mul(stride_3, _28));
    expr3 = symbolic::add(expr3, symbolic::mul(symbolic::mul(stride_3, stride_2), offset_24));
    expr3 = symbolic::add(expr3, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));
    EXPECT_FALSE(symbolic::maps::intersects({expr1}, {expr3}, _13, assums1, assums2));
    EXPECT_TRUE(symbolic::maps::intersects({expr1}, {expr3}, _28, assums1, assums2));
    // _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expr4 = symbolic::add(_32, symbolic::mul(stride_3, offset_28));
    expr4 = symbolic::add(expr4, symbolic::mul(symbolic::mul(stride_3, stride_2), offset_24));
    expr4 = symbolic::add(expr4, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));
    EXPECT_FALSE(symbolic::maps::intersects({expr1}, {expr4}, _13, assums1, assums2));
    EXPECT_TRUE(symbolic::maps::intersects({expr1}, {expr4}, _32, assums1, assums2));
}

#include "test.h"
template <typename T>
Array<uint64_t, 2> hash(const T &item) noexcept {
    auto data = memory::viewCast(item);
    Array<uint64_t, 2> hashValue;
    MurmurHash3_x64_128(data, _nc<int>(data.size()), 0, hashValue.data());
    return hashValue;
}
uint64_t nthHash(uint8_t n, uint64_t hashA, uint64_t hashB,
                 uint64_t filterSize) noexcept {
    return (hashA + n * hashB) % filterSize;
}
struct BloomFilter {
    BloomFilter(uint64_t size, uint8_t numHashes) noexcept
        : m_bits(size), m_numHashes(numHashes) {}
    template <typename T>
    void add(const T &item) noexcept {
        auto data = memory::viewCast(item);
        auto hashValues = hash(data);
        for (uint8_t n = 0; n < m_numHashes; n++) {
            m_bits[nthHash(n, hashValues[0], hashValues[1], m_bits.size())] =
                true;
        }
    }
    template <typename T>
    bool possiblyContains(const T &item) const noexcept {
        auto data = memory::viewCast(item);
        auto hashValues = hash(data);
        for (uint8_t n = 0; n < m_numHashes; n++) {
            if (!m_bits[nthHash(n, hashValues[0], hashValues[1],
                                m_bits.size())]) {
                return false;
            }
        }
        return true;
    }
private:
    uint8_t m_numHashes;
    std::vector<bool> m_bits;
};
TEST_CASE("util::BloomFilter") {
    BloomFilter filter(1'000, 13);
    // Add every even number
    auto added = 0;
    for (auto i = 0; i < 1'000; i++) {
        if (!(i % 2)) {
            filter.add(i);
            added++;
        }
    }
    // Verify now that all the events possibly exist and all the ods definitely
    // don't exist
    auto possible = 0, notPossible = 0, errors = 0;
    for (auto i = 0; i < 1'000; i++) {
        auto possiblyContains = false;
        if (!(i % 2))
            possiblyContains = filter.possiblyContains(i);
        else
            possiblyContains = filter.possiblyContains(i);
        if (possiblyContains)
            possible++;
        else {
            notPossible++;
            if (!(i % 2)) {
                LOG(Test, "Filter incorrectly says {} is not possible...", i);
                errors++;
            }
        }
    }
    LOG(Test, "Possible: {,c} Not possible: {,c} Added: {,c} Errors: {,c}",
        possible, notPossible, added, errors);
}

