NgMat *NgMat::sCurrent;
RndRenderState::ClampMode sTexWrapClampModes[6] = {
    (RndRenderState::ClampMode)2, (RndRenderState::ClampMode)0,
    (RndRenderState::ClampMode)6, (RndRenderState::ClampMode)6,
    (RndRenderState::ClampMode)1, (RndRenderState::ClampMode)0
};
NgMat::NgMat() {}
NgMat::~NgMat() {
    if (sCurrent == this)
        sCurrent = nullptr;
}
bool NgMat::AllowFog() const {
    return mBlend != kBlendDest && mBlend != kBlendAdd && mBlend != kBlendSubtract
        && mBlend != kBlendSrcAlphaAdd;
}
bool NgMat::AllowHDR() const {
    return (mBlend != kBlendSrcAlpha && mBlend != kBlendSrcAlphaAdd
            && mBlend != kPreMultAlpha)
        && !mAlphaCut && !mAlphaWrite;
}
void NgMat::SetupShader(bool b1, bool b2) {
    if (b2)
        SetupAmbient();
    if (this != sCurrent || mDirty) {
        if (mDirty & 2) {
            RefreshState();
        }
        SetBasicState();
        if (b2) {
            SetRegularShaderConst(b1);
        }
        mDirty = 0;
        sCurrent = this;
    }
}
void NgMat::SetBasicState() {
    RndRenderState::CullMode cm;
    switch (mCull) {
    case kCullNone:
        cm = (RndRenderState::CullMode)0;
        break;
    case kCullRegular:
        cm = (RndRenderState::CullMode)2;
        break;
    case kCullBackwards:
        cm = (RndRenderState::CullMode)6;
        break;
    default:
        cm = (RndRenderState::CullMode)2;
        break;
    }
    TheRenderState.SetCullMode(cm);
    TheRenderState.SetBlendEnable(mBlendEnable);
    TheRenderState.SetBlendOp(mBlendOp);
    TheRenderState.SetBlend(unk23c, unk240, unk23c, unk240);
    TheRenderState.SetAlphaTestEnable(mAlphaCut);
    if (mAlphaCut) {
        TheRenderState.SetAlphaFunc((RndRenderState::TestFunc)5, mAlphaThreshold);
    }
    TheRenderState.SetDepthTestEnable(mDepthTestEnable);
    TheRenderState.SetDepthWriteEnable(mDepthWriteEnable);
    TheRenderState.SetDepthFunc(mDepthFunc);
    if (mStencilMode == kStencilIgnore) {
        TheRenderState.SetStencilTestEnable(false);
    } else {
        TheRenderState.SetStencilTestEnable(true);
        TheRenderState.SetStencilFunc(mStencilFunc, 0);
        TheRenderState.SetStencilOp(
            (RndRenderState::StencilOp)0, (RndRenderState::StencilOp)0, unk250
        );
    }
    RndRenderState::ClampMode cur = sTexWrapClampModes[mTexWrap];
    if (mDiffuseTex) {
        TheRenderState.SetTextureClamp(0, cur);
    }
    if (mDiffuseTex2) {
        TheRenderState.SetTextureClamp(6, cur);
    }
    if (mNormalMap) {
        TheRenderState.SetTextureClamp(1, cur);
    }
    if (mSpecularMap) {
        TheRenderState.SetTextureClamp(2, cur);
    }
    if (mEmissiveMap) {
        TheRenderState.SetTextureClamp(3, cur);
    }
    if (cur == 6) {
        bool white = mTexWrap == kTexBorderWhite;
        TheRenderState.SetBorderColor(0, white);
        TheRenderState.SetBorderColor(6, white);
        TheRenderState.SetBorderColor(1, white);
        TheRenderState.SetBorderColor(2, white);
        TheRenderState.SetBorderColor(3, white);
    }
}
void NgMat::SetupAmbient() {
    if (mUseEnviron) {
        const Vector4 &v4 =
            reinterpret_cast<const Vector4 &>(RndEnviron::Current()->AmbientColor());
        TheShaderMgr.SetVConstant((VShaderConstant)1, v4);
        TheShaderMgr.SetPConstant((PShaderConstant)1, v4);
    } else {
        Vector4 v4(1, 1, 1, 1);
        TheShaderMgr.SetVConstant((VShaderConstant)1, v4);
        TheShaderMgr.SetPConstant((PShaderConstant)1, v4);
    }
}

#include "WebAssemblyTypeUtilities.h"
#include "llvm/ADT/StringSwitch.h"
// Get register classes enum.
#define GET_REGINFO_ENUM
#include "WebAssemblyGenRegisterInfo.inc"
using namespace llvm;
MVT WebAssembly::parseMVT(StringRef Type) {
  return StringSwitch<MVT>(Type)
      .Case("i32", MVT::i32)
      .Case("i64", MVT::i64)
      .Case("f32", MVT::f32)
      .Case("f64", MVT::f64)
      .Case("i64", MVT::i64)
      .Case("v16i8", MVT::v16i8)
      .Case("v8i16", MVT::v8i16)
      .Case("v4i32", MVT::v4i32)
      .Case("v2i64", MVT::v2i64)
      .Case("funcref", MVT::funcref)
      .Case("externref", MVT::externref)
      .Default(MVT::INVALID_SIMPLE_VALUE_TYPE);
}
wasm::ValType WebAssembly::toValType(MVT Type) {
  switch (Type.SimpleTy) {
  case MVT::i32:
    return wasm::ValType::I32;
  case MVT::i64:
    return wasm::ValType::I64;
  case MVT::f32:
    return wasm::ValType::F32;
  case MVT::f64:
    return wasm::ValType::F64;
  case MVT::v16i8:
  case MVT::v8i16:
  case MVT::v4i32:
  case MVT::v2i64:
  case MVT::v4f32:
  case MVT::v2f64:
    return wasm::ValType::V128;
  case MVT::funcref:
    return wasm::ValType::FUNCREF;
  case MVT::externref:
    return wasm::ValType::EXTERNREF;
  default:
    llvm_unreachable("unexpected type");
  }
}
void WebAssembly::wasmSymbolSetType(MCSymbolWasm *Sym, const Type *GlobalVT,
                                    const ArrayRef<MVT> &VTs) {
  assert(!Sym->getType());
  // Tables are represented as Arrays in LLVM IR therefore
  // they reach this point as aggregate Array types with an element type
  // that is a reference type.
  wasm::ValType ValTy;
  bool IsTable = false;
  if (WebAssembly::isWebAssemblyTableType(GlobalVT)) {
    IsTable = true;
    const Type *ElTy = GlobalVT->getArrayElementType();
    if (WebAssembly::isWebAssemblyExternrefType(ElTy))
      ValTy = wasm::ValType::EXTERNREF;
    else if (WebAssembly::isWebAssemblyFuncrefType(ElTy))
      ValTy = wasm::ValType::FUNCREF;
    else
      report_fatal_error("unhandled reference type");
  } else if (VTs.size() == 1) {
    ValTy = WebAssembly::toValType(VTs[0]);
  } else
    report_fatal_error("Aggregate globals not yet implemented");
  if (IsTable) {
    Sym->setType(wasm::WASM_SYMBOL_TYPE_TABLE);
    Sym->setTableType(ValTy);
  } else {
    Sym->setType(wasm::WASM_SYMBOL_TYPE_GLOBAL);
    Sym->setGlobalType(wasm::WasmGlobalType{uint8_t(ValTy), /*Mutable=*/true});
  }
}

#include "MavLinkLog.hpp"
#include <chrono>
#include "Utils.hpp"
using namespace mavlinkcom;
using namespace mavlink_utils;
uint64_t MavLinkFileLog::getTimeStamp() {
  return std::chrono::duration_cast<std::chrono::microseconds>(
             std::chrono::high_resolution_clock::now().time_since_epoch())
      .count();
}
MavLinkFileLog::MavLinkFileLog() {
  ptr_ = nullptr;
  reading_ = false;
  writing_ = false;
  json_ = false;
}
MavLinkFileLog::~MavLinkFileLog() { close(); }
bool MavLinkFileLog::isOpen() { return reading_ || writing_; }
void MavLinkFileLog::openForReading(const std::string& filename) {
  close();
  file_name_ = filename;
  ptr_ = fopen(filename.c_str(), "rb");
  if (ptr_ == nullptr) {
    throw std::runtime_error(Utils::stringf(
        "Could not open the file %s, error=%d", filename.c_str(), errno));
  }
  fseek(ptr_, 0, SEEK_SET);
  reading_ = true;
  writing_ = false;
}
void MavLinkFileLog::openForWriting(const std::string& filename, bool json) {
  close();
  json_ = json;
  file_name_ = filename;
  ptr_ = fopen(filename.c_str(), "wb");
  if (ptr_ == nullptr) {
    throw std::runtime_error(Utils::stringf(
        "Could not open the file %s, error=%d", filename.c_str(), errno));
  }
  if (json) {
    fprintf(ptr_, "{ \"rows\": [\n");
  }
  reading_ = false;
  writing_ = true;
}
void MavLinkFileLog::close() {
  FILE* temp = ptr_;
  if (json_ && ptr_ != nullptr) {
    fprintf(ptr_,
            "    {}\n");  // so that trailing comma on last row isn't a problem.
    fprintf(ptr_, "]}\n");
  }
  ptr_ = nullptr;
  if (temp != nullptr) {
    fclose(temp);
  }
  reading_ = false;
  writing_ = false;
}
uint64_t FlipEndianness(uint64_t v) {
  uint64_t result = 0;
  uint64_t shift = v;
  const int size = sizeof(uint64_t);
  for (int i = 0; i < size; i++) {
    uint64_t low = (shift & 0xff);
    result = (result << 8) + low;
    shift >>= 8;
  }
  return result;
}
void MavLinkFileLog::write(const mavlinkcom::MavLinkMessage& msg,
                           uint64_t timestamp) {
  if (ptr_ != nullptr) {
    if (reading_) {
      throw std::runtime_error("Log file was opened for reading");
    }
    if (json_) {
      MavLinkMessageBase* strongTypedMsg = MavLinkMessageBase::lookup(msg);
      if (strongTypedMsg != nullptr) {
        strongTypedMsg->timestamp = timestamp;
        std::string line = strongTypedMsg->toJSon();
        fprintf(ptr_, "    %s\n", line.c_str());
        delete strongTypedMsg;
      }
    } else {
      if (timestamp == 0) {
        timestamp = getTimeStamp();
      }
      // for compatibility with QGroundControl we have to save the time field in
      // big endian.
      // todo: mavlink2 support?
      timestamp = FlipEndianness(timestamp);
      fwrite(&timestamp, sizeof(uint64_t), 1, ptr_);
      fwrite(&msg.magic, 1, 1, ptr_);
      fwrite(&msg.len, 1, 1, ptr_);
      fwrite(&msg.seq, 1, 1, ptr_);
      fwrite(&msg.sysid, 1, 1, ptr_);
      fwrite(&msg.compid, 1, 1, ptr_);
      uint8_t msgid = msg.msgid & 0xff;  // truncate to mavlink1 msgid
      fwrite(&msgid, 1, 1, ptr_);
      fwrite(&msg.payload64, 1, msg.len, ptr_);
      fwrite(&msg.checksum, sizeof(uint16_t), 1, ptr_);
    }
  }
}
bool MavLinkFileLog::read(mavlinkcom::MavLinkMessage& msg,
                          uint64_t& timestamp) {
  if (ptr_ != nullptr) {
    if (writing_) {
      throw std::runtime_error("Log file was opened for writing");
    }
    uint64_t time;
    size_t s = fread(&time, 1, sizeof(uint64_t), ptr_);
    if (s < sizeof(uint64_t)) {
      int hr = errno;
      return false;
    }
    timestamp = FlipEndianness(time);
    s = fread(&msg.magic, 1, 1, ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.len, 1, 1, ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.seq, 1, 1, ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.sysid, 1, 1, ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.compid, 1, 1, ptr_);
    if (s == 0) {
      return false;
    }
    uint8_t msgid = 0;
    s = fread(&msgid, 1, 1, ptr_);
    msg.msgid = msgid;
    if (s < 1) {
      return false;
    }
    s = fread(&msg.payload64, 1, msg.len, ptr_);
    if (s < msg.len) {
      return false;
    }
    s = fread(&msg.checksum, 1, sizeof(uint16_t), ptr_);
    if (s < sizeof(uint16_t)) {
      return false;
    }
    return true;
  }
  return false;
}

#include "ipc/event_listener.h"
#include "log/fanylog.h"
#include "window/ime_windows.h"
#include <thread>
#include "ipc/ipc.h"
#include "config/ime_config.h"
int CALLBACK WinMain(_In_ HINSTANCE hInstance, _In_ HINSTANCE hPrevInstance, _In_ LPSTR lpCmdLine, _In_ int nCmdShow)
{
    SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);
    // #ifdef FANY_DEBUG
    // Initialize for logging
    InitializeSpdLog();
    // #endif
    // Initialize config
    InitImeConfig();
    ::InitIpc();
    ::InitNamedPipe();
    g_dictQuery = std::make_shared<DictionaryUlPb>();
    RegisterCandidateWindowMessage();
    WNDCLASSEX wcex;
    RegisterIMEWindowsClass(wcex, hInstance);
    //
    // Pipe
    //
    /* Named Pipe for IPC between tsf and server */
    std::thread pipe_worker(FanyNamedPipe::WorkerThread);
    std::thread pipe_listener(FanyNamedPipe::EventListenerLoopThread);
    /* Named Pipe for IPC, used to pass data to TSF */
    std::thread to_tsf_pipe_listener(FanyNamedPipe::ToTsfPipeEventListenerLoopThread);
    ::mainPipeThread = pipe_listener.native_handle();
    ::toTsfPipeThread = to_tsf_pipe_listener.native_handle();
    /* To Tsf Worker Thread Named Pipe for IPC, used to pass data to TSF */
    std::thread to_tsf_worker_thread_pipe_listener(FanyNamedPipe::ToTsfWorkerThreadPipeEventListenerLoopThread);
    ::toTsfWorkerThreadPipeThread = to_tsf_worker_thread_pipe_listener.native_handle();
    /* Aux Named Pipe for reconnecting main pipe */
    std::thread aux_pipe_listener(FanyNamedPipe::AuxPipeEventListenerLoopThread);
    int ret = CreateCandidateWindow(hInstance);
    pipe_running = false;
    pipe_queueCv.notify_one();
    pipe_worker.join();
    pipe_listener.join();
    // To Tsf Pipe
    to_tsf_pipe_listener.join();
    to_tsf_worker_thread_pipe_listener.join();
    aux_pipe_listener.join();
    return ret;
}

