void changeMusicLED(int index) {
    long color;
    int currentColorIndex;
    do {
        currentColorIndex = random(0, 7);
    } while (currentColorIndex == lastColorIndex);
    lastColorIndex = currentColorIndex;
    switch (currentColorIndex) {
        case 0:
            color = RED_COLOR;
            break;
        case 1:
            color = GREEN_COLOR;
            break;
        case 2:
            color = BLUE_COLOR;
            break;
        case 3:
            color = YELLOW_COLOR;
            break;
        case 4:
            color = WHITE_COLOR;
            break;
        case 5:
            color = CYAN_COLOR;
            break;
        case 6:
            color = MAGENTA_COLOR;
            break;
        case 7:
            color = ORANGE_COLOR;
            break;
    }
    changeLED(index, color);
