        changeLED(7, WHITE_COLOR);
        setMMUServoPosition(filamentPositions[7]);
    } else {
        changeLED(0, WHITE_COLOR);
        setMMUServoPosition(filamentPositions[0]);
    }
    restoreLEDStates();
}
bool swapFinish() {
    if (hubStateStucked || filamentStates[activeFilament] == HIGH) {
