void MavLinkFtpClientImpl::listDirectory() {
  MavLinkFileTransferProtocol ftp;
  FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
  ftp.target_component = getTargetComponentId();
  ftp.target_system = getTargetSystemId();
  payload->opcode = kCmdListDirectory;
  setPayloadFilename(payload, remote_file_.c_str());
  payload->offset = file_index_;
  sendMessage(ftp);
  recordMessageSent();
}
bool MavLinkFtpClientImpl::openSourceFile() {
  file_ptr_ = fopen(local_file_.c_str(), "rb");
  if (file_ptr_ == nullptr) {
    if (progress_ != nullptr) {
      progress_->error = errno;
      progress_->message =
          Utils::stringf("Error opening file '%s' for reading, rc=%d",
                         remote_file_.c_str(), progress_->error);
    }
    return false;
  }
  fseek(file_ptr_, 0, SEEK_END);
  long pos = ftell(file_ptr_);
  fseek(file_ptr_, 0, SEEK_SET);
  file_size_ = static_cast<uint64_t>(pos);
  if (progress_ != nullptr) {
    progress_->goal = file_size_;
  }
  return true;
}
bool MavLinkFtpClientImpl::createLocalFile() {
  if (file_ptr_ == nullptr) {
    auto path = FileSystem::getFullPath(local_file_);
    if (FileSystem::isDirectory(path)) {
      // user was lazy, only told us where to put the file, so we borrow the
      // name of the file from the source.
      auto remote = FileSystem::getFileName(normalize(remote_file_));
      local_file_ = FileSystem::combine(path, remote);
    } else {
      // check if directory exists.
      FileSystem::removeLeaf(path);
      if (FileSystem::isDirectory(path)) {
        // perfect.
      } else if (FileSystem::exists(path)) {
        if (progress_ != nullptr) {
          progress_->error = errno;
          progress_->message = Utils::stringf(
              "Error opening file because '%s' is not a directory",
              path.c_str());
        }
        return false;
      } else {
        if (progress_ != nullptr) {
          progress_->error = errno;
          progress_->message = Utils::stringf(
              "Error opening file because '%s' should be a directory but it "
              "was not found",
              path.c_str());
        }
        return false;
      }
    }
    file_ptr_ = fopen(local_file_.c_str(), "wb");
    if (file_ptr_ == nullptr) {
      if (progress_ != nullptr) {
        progress_->error = errno;
        progress_->message =
            Utils::stringf("Error opening file '%s' for writing, rc=%d",
                           local_file_.c_str(), errno);
      }
      return false;
    }
    file_size_ = 0;
  }
  return true;
}
void MavLinkFtpClientImpl::readFile() {
  if (!remote_file_open_) {
    MavLinkFileTransferProtocol ftp;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    payload->opcode = kCmdOpenFileRO;
    setPayloadFilename(payload, remote_file_.c_str());
    sendMessage(ftp);
    recordMessageSent();
  } else {
    if (createLocalFile()) {
      // use last_message_ so we preserve the sessionid.
      FtpPayload* payload =
          reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
      payload->opcode = kCmdReadFile;
      payload->offset = bytes_read_;
      last_message_.target_component = getTargetComponentId();
      last_message_.target_system = getTargetSystemId();
      sendMessage(last_message_);
      recordMessageSent();
      if (progress_ != nullptr) {
        progress_->current = bytes_read_;
      }
    } else {
      // could not create the local file, so stop.
      waiting_ = false;
    }
  }
}
void MavLinkFtpClientImpl::writeFile() {
  if (!remote_file_open_) {
    MavLinkFileTransferProtocol ftp;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    payload->opcode = kCmdOpenFileWO;
    strcpy(reinterpret_cast<char*>(&payload->data), remote_file_.c_str());
    payload->size = static_cast<uint8_t>(remote_file_.size());
    sendMessage(ftp);
    recordMessageSent();
  } else {
    // must use last_message_ so we preserve the session id.
    MavLinkFileTransferProtocol& ftp = last_message_;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    payload->opcode = kCmdWriteFile;
    payload->seq_number = sequence_;
    fseek(file_ptr_, bytes_written_, SEEK_SET);
    uint8_t* data = &payload->data;
    size_t bytes = fread(data, 1, 251 - 12, file_ptr_);
    if (progress_ != nullptr) {
      progress_->current = bytes_written_;
    }
    if (bytes == 0) {
      success_ = true;
      reset();
      int err = ferror(file_ptr_);
      if (err != 0) {
        if (progress_ != nullptr) {
          progress_->error = err;
          progress_->message =
              Utils::stringf("error reading local file, errno=%d", err);
        }
      }
      fclose(file_ptr_);
      file_ptr_ = nullptr;
      waiting_ = false;
    } else {
      payload->offset = bytes_written_;
      payload->size = static_cast<uint8_t>(bytes);
      ftp.target_component = getTargetComponentId();
      ftp.target_system = getTargetSystemId();
      sendMessage(ftp);
      recordMessageSent();
    }
  }
}
void MavLinkFtpClientImpl::cancel() {
  // todo: wait for any pending responses from PX4 so we can safely start a new
  // command.
  reset();
}
void MavLinkFtpClientImpl::close() {
  if (file_ptr_ != nullptr) {
    reset();
    fclose(file_ptr_);
    file_ptr_ = nullptr;
  }
  if (subscription_ != 0) {
    getConnection()->unsubscribe(subscription_);
    subscription_ = 0;
  }
}
void MavLinkFtpClientImpl::reset() {
  MavLinkFileTransferProtocol ftp;
  ftp.target_component = getTargetComponentId();
  ftp.target_system = getTargetSystemId();
  FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
  payload->opcode = kCmdResetSessions;
  sendMessage(ftp);
  recordMessageSent();
}
void MavLinkFtpClientImpl::handleListResponse() {
  FtpPayload* payload =
      reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
  if (payload->offset != file_index_) {
    // todo: error handling here? sequence is out of order...
    Utils::log(
        Utils::stringf("list got offset %d, but expecting file index %d\n",
                       payload->offset, file_index_),
        Utils::kLogLevelError);
    retry();
    return;
  }
  if (payload->offset == 0 && payload->size == 0) {
    // directory must be empty then, can't do nextStep because
    // it will just loop for ever re-requesting zero offset into
    // empty directory.
    reset();
    success_ = true;
    waiting_ = false;
    return;
  }
  // result should be a list of null terminated file names.
  uint8_t* data = &payload->data;
  for (int offset = 0; offset < payload->size;) {
    uint8_t dirType = data[offset];
    offset++;
    retries_ = 0;
    file_index_++;
    int len = 0;
    std::string name = reinterpret_cast<char*>(&data[offset]);
    if (dirType == kDirentSkip) {
      // skipping this entry
    } else if (dirType == kDirentFile) {
      size_t i = name.find_last_of('\t');
      MavLinkFileInfo info;
      info.is_directory = false;
      len = static_cast<int>(name.size());
      if (i > 0) {
        // remove the file size field.
        std::string size(name.begin() + i + 1, name.end());
        info.size = Utils::to_integer(size);
        name.erase(name.begin() + i, name.end());
      }
      info.name = name;
      // printf("%s\n", name.c_str());
      if (files_ != nullptr) {
        files_->push_back(info);
      }
    } else if (dirType == kDirentDir) {
      MavLinkFileInfo info;
      info.is_directory = true;
      info.name = name;
      len = static_cast<int>(name.size());
      if (files_ != nullptr) {
        files_->push_back(info);
      }
    }
    offset += len + 1;
  }
  if (progress_ != nullptr) {
    progress_->current = file_index_;
  }
  // request the next batch.
  nextStep();
}
void MavLinkFtpClientImpl::handleReadResponse() {
  FtpPayload* payload =
      reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
  if (payload->req_opcode == kCmdOpenFileRO) {
    remote_file_open_ = true;
    bytes_read_ = 0;
    retries_ = 0;
    sequence_ = payload->seq_number;
    uint32_t* size = reinterpret_cast<uint32_t*>(&payload->data);
    file_size_ = static_cast<uint64_t>(*size);
    if (progress_ != nullptr) {
      progress_->goal = file_size_;
    }
    nextStep();
  } else if (payload->req_opcode == kCmdReadFile) {
    int seq = static_cast<int>(payload->seq_number);
    if (seq != sequence_ + 1) {
      Utils::log(
          Utils::stringf("packet %d is out of sequence, expecting number %d\n",
                         seq, sequence_ + 1),
          Utils::kLogLevelError);
      // perhaps this was a late response after we did a retry, so ignore it.
      return;
    } else if (file_ptr_ != nullptr) {
      sequence_ = payload->seq_number;
      fwrite(&payload->data, payload->size, 1, file_ptr_);
      bytes_read_ += payload->size;
      retries_ = 0;
      nextStep();
    }
  }
}
void MavLinkFtpClientImpl::handleWriteResponse() {
  FtpPayload* payload =
      reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
  if (payload->req_opcode == kCmdOpenFileWO) {
    remote_file_open_ = true;
    bytes_written_ = 0;
    retries_ = 0;
    sequence_ = payload->seq_number;
    nextStep();
  } else if (payload->req_opcode == kCmdWriteFile) {
    int seq = static_cast<int>(payload->seq_number);
    if (seq != sequence_ + 1) {
      Utils::log(
          Utils::stringf("packet %d is out of sequence, expecting number %d\n",
                         seq, sequence_ + 1),
          Utils::kLogLevelError);
      // perhaps this was a late response after we did a retry, so ignore it.
      return;
    }
    uint32_t* size = reinterpret_cast<uint32_t*>(&payload->data);
    // payload->size contains the bytes_written from PX4, so that's how much we
    // advance.
    bytes_written_ += static_cast<int>(*size);
    retries_ = 0;
    sequence_++;
    nextStep();
  }
}
void MavLinkFtpClientImpl::handleRemoveResponse() {
  success_ = true;
  waiting_ = false;
}
void MavLinkFtpClientImpl::handleRmdirResponse() {
  success_ = true;
  waiting_ = false;
}
void MavLinkFtpClientImpl::handleMkdirResponse() {
  success_ = true;
  waiting_ = false;
}
void MavLinkFtpClientImpl::handleResponse(const MavLinkMessage& msg) {
  if (msg.msgid ==
      static_cast<int>(
          MavLinkMessageIds::MAVLINK_MSG_ID_FILE_TRANSFER_PROTOCOL)) {
    last_message_.decode(msg);
    recordMessageReceived();
    FtpPayload* payload =
        reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
    if (payload->opcode == kRspNak) {
      // reached the end of the list or the file.
      if (file_ptr_ != nullptr) {
        fclose(file_ptr_);
        file_ptr_ = nullptr;
      }
      int error = static_cast<int>(payload->data);
      if (error == kErrEOF) {
        // end of file or directory listing.
        success_ = true;
        error = 0;
      } else {
        success_ = false;
        if (progress_ != nullptr) {
          if (error == kErrFailErrno) {
            const uint8_t* data = &(payload->data);
            error = static_cast<int>(data[1]);
            progress_->error = error;
            progress_->message = Utils::stringf("ftp kErrFailErrno %d", error);
          } else {
            progress_->error = error;
            progress_->message = Utils::stringf("ftp error %d", error);
          }
        }
      }
      errorCode_ = error;
      waiting_ = false;
      reset();
    } else if (payload->opcode == kRspAck) {
      if (progress_ != nullptr) {
        progress_->message_count++;
      }
      // success, data should be following...
      switch (payload->req_opcode) {
        case kCmdListDirectory:
          handleListResponse();
          break;
        case kCmdOpenFileRO:
        case kCmdReadFile:
          handleReadResponse();
          break;
        case kCmdOpenFileWO:
        case kCmdWriteFile:
          handleWriteResponse();
          break;
        case kCmdResetSessions:
          // ack on this cmd is a noop
          break;
        case kCmdRemoveFile:
          handleRemoveResponse();
          break;
        case kCmdRemoveDirectory:
          handleRmdirResponse();
          break;
        case kCmdCreateDirectory:
          handleMkdirResponse();
          break;
        default:
          // todo: how to handle this? For now we ignore it and let the watchdog
          // kick in and do a retry.
          Utils::log(Utils::stringf("Unexpected ACK with req_opcode=%d\n",
                                    static_cast<int>(payload->req_opcode)),
                     Utils::kLogLevelWarn);
          break;
      }
    }
  }
}
void MavLinkFtpClientImpl::MavLinkFtpClientImpl::retry() {
  retries_++;
  if (retries_ < 10) {
    Utils::log(Utils::stringf("retry %d\n", retries_), Utils::kLogLevelWarn);
    nextStep();
  } else {
    // give up then.
    errorCode_ = kErrRetriesExhausted;
    success_ = false;
    waiting_ = false;
    reset();
  }
}
void MavLinkFtpClientImpl::recordMessageSent() {
  // tell watchdog we are sending a request
  std::lock_guard<std::mutex> guard(mutex_);
  start_time_ = std::chrono::duration_cast<milliseconds>(
      std::chrono::system_clock::now().time_since_epoch());
}
void MavLinkFtpClientImpl::recordMessageReceived() {
  std::lock_guard<std::mutex> guard(mutex_);
  messages_++;
  milliseconds endTime = std::chrono::duration_cast<milliseconds>(
      std::chrono::system_clock::now().time_since_epoch());
  milliseconds duration = endTime - start_time_;
  total_time_ += duration;
  if (progress_ != nullptr && duration.count() > progress_->longest_delay) {
    progress_->longest_delay = static_cast<double>(duration.count());
  }
}
std::string MavLinkFtpClientImpl::replaceAll(std::string s, char toFind,
                                             char toReplace) {
  size_t pos = s.find_first_of(toFind, 0);
  while (pos != std::string::npos) {
    s.replace(pos, 1, 1, toReplace);
    pos = s.find_first_of(toFind, 0);
  }
  return s;
}
std::string MavLinkFtpClientImpl::normalize(std::string arg) {
  if (FileSystem::kPathSeparator == '\\') {
    return replaceAll(arg, '/',
                      '\\');  // make sure user input matches what FileSystem
                              // will do when resolving paths.
  }
  return arg;
}
std::string MavLinkFtpClientImpl::toPX4Path(std::string arg) {
  if (FileSystem::kPathSeparator == '\\') {
    return replaceAll(arg, '\\', '/');  // PX4 uses '/'
  }
  return arg;
}

#include <gtest/gtest.h>
#include "kindr/common/gtest_eigen.hpp"
#include "kindr/phys_quant/PhysicalType.hpp"
#include "kindr/phys_quant/PhysicalQuantities.hpp"
#include "kindr/vectors/Vector.hpp"
struct ScalarTest : public ::testing::Test {
  using Acceleration = kindr::Acceleration3D;
  using Force = kindr::Force3D;
  using Mass = kindr::MassD;
  Acceleration acceleration;
  Force force;
  Mass mass;
  ScalarTest() : acceleration(1., 2., 3.), force(5., 10., 15.), mass(5.) {}
};
TEST_F(ScalarTest, multiplicationWithScalar) {
  EXPECT_EQ(acceleration * mass, force);
  EXPECT_EQ(mass * acceleration, force);
}
TEST_F(ScalarTest, divisionByScalar) {
  EXPECT_EQ(force / mass, acceleration);
}
TEST_F(ScalarTest, multiplyTwoScalars) {
  kindr::Acceleration<double, 1> accelerationScalar(2.);
  kindr::Force<double, 1> forceScalar(10.);
  EXPECT_EQ(accelerationScalar * mass, forceScalar);
  EXPECT_EQ(mass * accelerationScalar, forceScalar);
}
TEST_F(ScalarTest, divideTwoScalars) {
  kindr::Acceleration<double, 1> accelerationScalar(2.);
  kindr::Force<double, 1> forceScalar(10.);
  EXPECT_EQ(forceScalar / mass, accelerationScalar);
  EXPECT_EQ(forceScalar / accelerationScalar, mass);
}
TEST_F(ScalarTest, assignment) {
  const kindr::VectorTypeless<double, 1> typeless(5.);
  acceleration *= typeless;
  EXPECT_EQ(acceleration, kindr::Acceleration3D(5., 10., 15.));
  force /= typeless;
  EXPECT_EQ(force, kindr::Force3D(1., 2., 3.));
}

#include "async_web_server_cpp/websocket_connection.hpp"
#include <boost/bind/bind.hpp>
#include <boost/make_shared.hpp>
#include <limits>
namespace async_web_server_cpp
{
WebsocketConnection::WebsocketConnection(HttpConnectionPtr connection)
    : connection_(connection)
{
}
void WebsocketConnection::set_message_handler(MessageHandler& handler)
{
    handler_ = handler;
}
bool WebsocketConnection::sendTextMessage(const std::string& content)
{
    async_web_server_cpp::WebsocketMessage m;
    m.type = async_web_server_cpp::WebsocketMessage::type_text;
    m.content = content;
    return sendMessage(m);
}
bool WebsocketConnection::sendPingMessage(const std::string& content)
{
    async_web_server_cpp::WebsocketMessage m;
    m.type = async_web_server_cpp::WebsocketMessage::type_ping;
    m.content = content;
    return sendMessage(m);
}
bool WebsocketConnection::sendMessage(const WebsocketMessage& message)
{
    WebsocketFrame frame;
    if (frame.fromMessage(message))
    {
        return sendFrame(frame);
    }
    return false;
}
bool WebsocketConnection::sendFrame(WebsocketFrame& frame)
{
    std::vector<unsigned char> buffer;
    if (frame.serialize(buffer))
    {
        connection_->write_and_clear(buffer);
        return true;
    }
    return false;
}
void WebsocketConnection::static_handle_read(
    WebsocketConnectionWeakPtr weak_this, const char* begin, const char* end)
{
    WebsocketConnectionPtr _this = weak_this.lock();
    if (_this)
        _this->handle_read(begin, end);
}
void WebsocketConnection::handle_read(const char* begin, const char* end)
{
    boost::tribool frame_result;
    const char* parse_end = begin;
    while (parse_end < end)
    {
        boost::tie(frame_result, parse_end) =
            frame_parser_.parse(frame_, parse_end, end);
        if (frame_result)
        {
            frame_parser_.reset();
            boost::tribool message_result =
                frame_buffer_.consume(message_, frame_);
            if (message_result)
            {
                if (handler_)
                    handler_(message_);
            }
        }
        else if (!boost::logic::indeterminate(frame_result))
        {
            frame_parser_.reset();
            message_.type = WebsocketMessage::type_unknown;
        }
    }
    WebsocketConnectionWeakPtr this_weak(shared_from_this());
    connection_->async_read(boost::bind(
        &WebsocketConnection::static_handle_read, this_weak, boost::placeholders::_1, boost::placeholders::_2));
}
}  // namespace async_web_server_cpp

#include <QtTest/QtTest>
#include "core.h"
#include "imports/import_reclass_xml.h"
using namespace rcx;
class TestImportXml : public QObject {
    Q_OBJECT
private slots:
    void importSmallXml();
};
void TestImportXml::importSmallXml() {
    // Create a minimal XML in a temp file and test parsing
    QTemporaryFile tmp;
    tmp.setAutoRemove(true);
    QVERIFY(tmp.open());
    tmp.write(R"(<?xml version="1.0" encoding="UTF-8"?>
<ReClass>
    <!--ReClassEx-->
    <Class Name="TestClass" Type="28" Comment="" Offset="0" strOffset="0" Code="">
        <Node Name="vtable" Type="9" Size="8" bHidden="false" Comment=""/>
        <Node Name="health" Type="13" Size="4" bHidden="false" Comment=""/>
        <Node Name="name" Type="18" Size="32" bHidden="false" Comment=""/>
        <Node Name="position" Type="23" Size="12" bHidden="false" Comment=""/>
        <Node Name="pNext" Type="8" Size="8" bHidden="false" Comment="" Pointer="TestClass"/>
    </Class>
</ReClass>
)");
    tmp.flush();
    QString error;
    NodeTree tree = importReclassXml(tmp.fileName(), &error);
    QVERIFY2(!tree.nodes.isEmpty(), qPrintable(error));
    // Should have 1 root struct + 5 children = 6 nodes
    QCOMPARE(tree.nodes.size(), 6);
    // Root struct
    QCOMPARE(tree.nodes[0].kind, NodeKind::Struct);
    QCOMPARE(tree.nodes[0].name, QStringLiteral("TestClass"));
    // vtable = Int64
    QCOMPARE(tree.nodes[1].kind, NodeKind::Int64);
    QCOMPARE(tree.nodes[1].name, QStringLiteral("vtable"));
    QCOMPARE(tree.nodes[1].offset, 0);
    // health = Float
    QCOMPARE(tree.nodes[2].kind, NodeKind::Float);
    QCOMPARE(tree.nodes[2].name, QStringLiteral("health"));
    QCOMPARE(tree.nodes[2].offset, 8);
    // name = UTF8 with strLen=32
    QCOMPARE(tree.nodes[3].kind, NodeKind::UTF8);
    QCOMPARE(tree.nodes[3].strLen, 32);
    QCOMPARE(tree.nodes[3].offset, 12);
    // position = Vec3
    QCOMPARE(tree.nodes[4].kind, NodeKind::Vec3);
    QCOMPARE(tree.nodes[4].offset, 44);
    // pNext = Pointer64 with resolved refId
    QCOMPARE(tree.nodes[5].kind, NodeKind::Pointer64);
    QCOMPARE(tree.nodes[5].name, QStringLiteral("pNext"));
    QVERIFY(tree.nodes[5].refId != 0);
    QCOMPARE(tree.nodes[5].refId, tree.nodes[0].id); // points to TestClass
}
QTEST_MAIN(TestImportXml)
