 */
namespace VGLibNative {
    Value native_donut(std::vector<Value>& args) {
        if (args.size() < 2) throw std::runtime_error("donut() requires A and B arguments");
        std::printf("\x1b[H\x1b[?25l\x1b[J");
        float A = static_cast<float>(args[0].asFloat());
        float B = static_cast<float>(args[1].asFloat());
        float z[1760];
        char b[1760];
        std::memset(b, 32, 1760);
        std::memset(z, 0, sizeof(z));
        float sinA = std::sin(A), cosA = std::cos(A);
        float sinB = std::sin(B), cosB = std::cos(B);
        for (float j = 0; j < 6.28f; j += 0.07f) {
            float ct = std::cos(j), st = std::sin(j);
            for (float i = 0; i < 6.28f; i += 0.02f) {
                float sp = std::sin(i), cp = std::cos(i);
                float h = ct + 2;
                float D = 1 / (sp * h * sinA + st * cosA + 5);
                float t = sp * h * cosA - st * sinA;
                int x = static_cast<int>(40 + 30 * D * (cp * h * cosB - t * sinB));
                int y = static_cast<int>(12 + 15 * D * (cp * h * sinB + t * cosB));
                int o = x + 80 * y;
                int N = static_cast<int>(8 * ((st * sinA - sp * ct * cosA) * cosB - sp * ct * sinA - st * cosA - cp * ct * sinB));
                if (22 > y && y > 0 && x > 0 && 80 > x && D > z[o]) {
                    z[o] = D;
                    b[o] = ".,-~:;=!*#$@"[N > 0 ? (N < 12 ? N : 11) : 0];
                }
            }
        }
        char output[2000];
        int p = 0;
        for (int j = 0; j < 22; j++) {
            for (int i = 0; i < 80; i++) {
                output[p++] = b[i + j * 80];
            }
            output[p++] = '\n';
        }
        std::fwrite(output, 1, p, stdout);
        std::fflush(stdout);
        return Value();
    }
}
void setupVGLib(SymbolContainer& env, StringPool& pool) {
    const std::string& path = "vglib";

    if (env.find(path) == env.end()) {
        env[path] = SymbolTable();
    }
    auto& vglib = env[path];
    // VGLib methods
    vglib[pool.intern("donut")]    = Value(VGLibNative::native_donut);
    // VGLib properties
    vglib[pool.intern("version")]  = Value("v0.0.1-alpha").setReadOnly();
}

#include <fuerte/connection.h>
#include <yaclib/algo/wait_group.hpp>
#include "basics/logger/logger.h"
namespace sdb::fuerte {
Connection::~Connection() {
  SDB_DEBUG("xxxxx", Logger::FUERTE, "Destroying Connection");
}
// sendRequest and wait for it to finished.
std::unique_ptr<Response> Connection::sendRequest(
  std::unique_ptr<Request> request) {
  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): before send");
  // TODO(mbkkt) just atomic, aka one shot event without multiple wait
  yaclib::OneShotEvent wg;
  std::unique_ptr<Response> rv;
  auto error = Error::NoError;
  auto cb = [&](Error e, std::unique_ptr<Request> request,
                std::unique_ptr<Response> response) {
    rv = std::move(response);
    error = e;
    wg.Set();
  };
  {
    // Start asynchronous request
    sendRequest(std::move(request), cb);
    // Wait for request to finish.
    SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): before wait");
    wg.Wait();
  }
  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): done");
  if (error != Error::NoError) {
    throw error;
  }
  return rv;
}
std::string Connection::endpoint() const {
  std::string endpoint;
  endpoint.reserve(32);
  // http
  endpoint.append(fuerte::ToString(_config.protocol_type));
  endpoint.push_back('+');
  // tcp/ssl/unix
  endpoint.append(fuerte::ToString(_config.socket_type));
  endpoint.append("://");
  // domain name or IP (xxx.xxx.xxx.xxx)
  endpoint.append(_config.host);
  if (_config.socket_type != SocketType::Unix) {
    endpoint.push_back(':');
    endpoint.append(_config.port);
  }
  return endpoint;
}
}  // namespace sdb::fuerte

#include "stringpiece.h"
#include <ostream>
#include "util.h"
namespace lbug {
namespace regex {
const StringPiece::size_type StringPiece::npos; // initialized in stringpiece.h
StringPiece::size_type StringPiece::copy(char* buf, size_type n, size_type pos) const {
    size_type ret = std::min(size_ - pos, n);
    memcpy(buf, data_ + pos, ret);
    return ret;
}
StringPiece StringPiece::substr(size_type pos, size_type n) const {
    if (pos > size_)
        pos = size_;
    if (n > size_ - pos)
        n = size_ - pos;
    return StringPiece(data_ + pos, n);
}
StringPiece::size_type StringPiece::find(const StringPiece& s, size_type pos) const {
    if (pos > size_)
        return npos;
    const_pointer result = std::search(data_ + pos, data_ + size_, s.data_, s.data_ + s.size_);
    size_type xpos = result - data_;
    return xpos + s.size_ <= size_ ? xpos : npos;
}
StringPiece::size_type StringPiece::find(char c, size_type pos) const {
    if (size_ <= 0 || pos >= size_)
        return npos;
    const_pointer result = std::find(data_ + pos, data_ + size_, c);
    return result != data_ + size_ ? result - data_ : npos;
}
StringPiece::size_type StringPiece::rfind(const StringPiece& s, size_type pos) const {
    if (size_ < s.size_)
        return npos;
    if (s.size_ == 0)
        return std::min(size_, pos);
    const_pointer last = data_ + std::min(size_ - s.size_, pos) + s.size_;
    const_pointer result = std::find_end(data_, last, s.data_, s.data_ + s.size_);
    return result != last ? result - data_ : npos;
}
StringPiece::size_type StringPiece::rfind(char c, size_type pos) const {
    if (size_ <= 0)
        return npos;
    for (size_t i = std::min(pos + 1, size_); i != 0;) {
        if (data_[--i] == c)
            return i;
    }
    return npos;
}
std::ostream& operator<<(std::ostream& o, const StringPiece& p) {
    o.write(p.data(), p.size());
    return o;
}
} // namespace regex
} // namespace lbug

