MultiSfxItem *MultiSfxTester::openSfxByArg(QString musPath)
{
    auto* it = new MultiSfxItem(musPath, this);
    m_items.push_back(it);
    QObject::connect(it,
                     &MultiSfxItem::wannaClose,
                     this,
                     &MultiSfxTester::wannaClose);
