	for (; i > 0; i--) {
		int k = y->sig.length - 1;
		int j = i - k - 1;
		int l;
		int t;
		const u8* jp;
		const u8* kp;
		if (j < 0) {
			j = 0;
			k = i - 1;
		}
		jp = x->sig.text + j;
		kp = y->sig.text + k;
		l  = k + 1;
		t  = x->sig.length - j;
		if (l > t)
			l = t;
		for (; l > 0; l--, jp++, kp--) {
