BOOL __equals_dec(const decimal* x, const decimal* y)
{
	if (x->sig.text[0] == 0) {
		if (y->sig.text[0] == 0)
			return TRUE;
		return FALSE;
	}
	if (y->sig.text[0] == 0) {
		if (x->sig.text[0] == 0)
			return TRUE;
		return FALSE;
	}
	if (x->exp == y->exp) {
		int i;
		int l = x->sig.length;
		if (l > y->sig.length) {
			l = y->sig.length;
		}
		for (i = 0; i < l; i++) {
			if (x->sig.text[i] != y->sig.text[i]) {
				return FALSE;
			}
		}
		if (l == x->sig.length) {
			for (; i < y->sig.length; ++i) {
				if (y->sig.text[i] != 0) {
					return FALSE;
				}
			}
		} else {
			for (; i < x->sig.length; ++i) {
				if (x->sig.text[i] != 0) {
					return FALSE;
				}
			}
		}
		return TRUE;
	}
	return FALSE;
}
