{
    bool isWebGPUDriverEnabled = false;
#ifdef EMSCRIPTEN
    isWebGPUDriverEnabled =
        GetRenderingBackendName(taskManager->GetRenderIndex()) == HgiTokens->WebGPU;
#endif
