extern "C" void __declspec(naked) __cdecl Hook_SCURK1996_OwlMainCommandLineFix(void) {
	int nArgs;
	char **pArgs;
	__asm {
		mov [nArgs], ebx
		mov eax, [ebp+0xC]
		mov [pArgs], eax
	}
	BOOL bValidFileEntry;
	char *pRet;
	bValidFileEntry = FALSE;
	if (nArgs >= 2)
		pRet = L_SCURK1996_ProcessCmdLine(pArgs[0], TAppInitCmdLine_SCURK1996->p->array, &bValidFileEntry);
	if (!bValidFileEntry)
		pRet = NULL;
	_chdir(szGamePath);
	__asm {
		mov esi, [pRet]
	}
	GAMEJMP(0x45A7F6);
}
