    SDL_Window* window         = fromHwnd(hWindow);
    if (!isDisplayValid(displayId))
      return false;
    uint32_t flags = ModeSwitch
        ? SDL_WINDOW_FULLSCREEN
        : SDL_WINDOW_FULLSCREEN_DESKTOP;

    // TODO: Set this on the correct monitor.
