void TextEdit::CreateComponents()
{
	vert_scrollbar = new Scrollbar(this);
	vert_scrollbar->FuncScroll = [this]() { OnVerticalScroll(); };
	vert_scrollbar->SetVisible(false);
	vert_scrollbar->SetVertical();
}
void TextEdit::OnVerticalScroll()
{
}
void TextEdit::UpdateVerticalScroll()
{
	Rect rect(
		GetWidth() - vert_scrollbar->GetPreferredWidth(),
		0.0,
		vert_scrollbar->GetPreferredWidth(),
		GetHeight());
	vert_scrollbar->SetFrameGeometry(rect);
	double total_height = GetTotalLineHeight();
	double height_per_line = std::max(1.0, total_height / std::max(1.0, (double)lines.size()));
	bool visible = total_height > GetHeight();
	vert_scrollbar->SetRanges((int)std::round(GetHeight() / height_per_line), (int)std::round(total_height / height_per_line));
	vert_scrollbar->SetLineStep(1);
	vert_scrollbar->SetVisible(visible);
	if (visible == false)
		vert_scrollbar->SetPosition(0);
}
void TextEdit::MoveVerticalScroll()
{
	double total_height = GetTotalLineHeight();
	double height_per_line = std::max(1.0, total_height / std::max((size_t)1, lines.size()));
	int lines_fit = (int)(GetHeight() / height_per_line);
	if (cursor_pos.y >= vert_scrollbar->GetPosition() + lines_fit)
	{
		vert_scrollbar->SetPosition(cursor_pos.y - lines_fit + 1);
	}
	else if (cursor_pos.y < vert_scrollbar->GetPosition())
	{
		vert_scrollbar->SetPosition(cursor_pos.y);
	}
}
double TextEdit::GetTotalLineHeight()
{
	double total = 0;
	for (std::vector<Line>::const_iterator iter = lines.begin(); iter != lines.end(); iter++)
	{
		total += iter->layout.GetSize().height;
	}
	return total;
}
void TextEdit::Move(int steps, bool shift, bool ctrl)
{
	if (shift && selection_length == 0)
		selection_start = cursor_pos;
	// Jump over words if control is pressed.
	if (ctrl)
	{
		if (steps < 0 && cursor_pos.x == 0 && cursor_pos.y > 0)
		{
			cursor_pos.x = (int)lines[cursor_pos.y - 1].text.size();
			cursor_pos.y--;
		}
		else if (steps > 0 && cursor_pos.x == (int)lines[cursor_pos.y].text.size() && cursor_pos.y + 1 < (int)lines.size())
		{
			cursor_pos.x = 0;
			cursor_pos.y++;
		}
		ivec2 new_pos;
		if (steps < 0)
			new_pos = FindPreviousBreakCharacter(cursor_pos);
		else
			new_pos = FindNextBreakCharacter(cursor_pos);
		cursor_pos = new_pos;
	}
	else if (steps < 0 && cursor_pos.x == 0 && cursor_pos.y > 0)
	{
		cursor_pos.x = (int)lines[cursor_pos.y - 1].text.size();
		cursor_pos.y--;
	}
	else if (steps > 0 && cursor_pos.x == (int)lines[cursor_pos.y].text.size() && cursor_pos.y + 1 < (int)lines.size())
	{
		cursor_pos.x = 0;
		cursor_pos.y++;
	}
	else
	{
		UTF8Reader utf8_reader(lines[cursor_pos.y].text.data(), lines[cursor_pos.y].text.length());
		utf8_reader.set_position(cursor_pos.x);
		if (steps > 0)
		{
			for (int i = 0; i < steps; i++)
				utf8_reader.next();
		}
		else if (steps < 0)
		{
			for (int i = 0; i < -steps; i++)
				utf8_reader.prev();
		}
		cursor_pos.x = (int)utf8_reader.position();
	}
	if (shift)
	{
		selection_length = (int)ToOffset(cursor_pos) - (int)ToOffset(selection_start);
	}
	else
	{
		// Clear the selection if a cursor key is pressed but shift isn't down. 
		selection_start = ivec2(0, 0);
		selection_length = 0;
	}
	MoveVerticalScroll();
	Update();
	undo_info.first_text_insert = true;
}
std::string TextEdit::break_characters = " ::;,.-";
TextEdit::ivec2 TextEdit::FindNextBreakCharacter(ivec2 search_start)
{
	search_start.x++;
	if (search_start.x >= int(lines[search_start.y].text.size()) - 1)
		return ivec2(lines[search_start.y].text.size(), search_start.y);
	size_t pos = lines[search_start.y].text.find_first_of(break_characters, search_start.x);
	if (pos == std::string::npos)
		return ivec2(lines[search_start.y].text.size(), search_start.y);
	return ivec2((int)pos, search_start.y);
}
TextEdit::ivec2 TextEdit::FindPreviousBreakCharacter(ivec2 search_start)
{
	search_start.x--;
	if (search_start.x <= 0)
		return ivec2(0, search_start.y);
	size_t pos = lines[search_start.y].text.find_last_of(break_characters, search_start.x);
	if (pos == std::string::npos)
		return ivec2(0, search_start.y);
	return ivec2((int)pos, search_start.y);
}
void TextEdit::InsertText(ivec2 pos, const std::string& str)
{
	undo_info.first_erase = false;
	if (undo_info.first_text_insert)
	{
		undo_info.undo_text = GetText();
		undo_info.first_text_insert = false;
	}
	// checking if insert exceeds max length
	if (ToOffset(ivec2((int)lines[lines.size() - 1].text.size(), (int)lines.size() - 1)) + str.length() > (size_t)max_length)
	{
		return;
	}
	std::string::size_type start = 0;
	while (true)
	{
		std::string::size_type next_newline = str.find('\n', start);
		lines[pos.y].text.insert(pos.x, str.substr(start, next_newline - start));
		lines[pos.y].invalidated = true;
		if (next_newline == std::string::npos)
			break;
		pos.x += next_newline - start;
		Line line{this};
		line.text = lines[pos.y].text.substr(pos.x);
		lines.insert(lines.begin() + pos.y + 1, line);
		lines[pos.y].text = lines[pos.y].text.substr(0, pos.x);
		lines[pos.y].invalidated = true;
		pos = ivec2(0, pos.y + 1);
		start = next_newline + 1;
	}
	MoveVerticalScroll();
	Update();
}
void TextEdit::Backspace()
{
	if (undo_info.first_erase)
	{
		undo_info.first_erase = false;
		undo_info.undo_text = GetText();
	}
	if (GetSelectionLength() != 0)
	{
		DeleteSelectedText();
		ClearSelection();
		Update();
	}
	else
	{
		if (cursor_pos.x > 0)
		{
			UTF8Reader utf8_reader(lines[cursor_pos.y].text.data(), lines[cursor_pos.y].text.length());
			utf8_reader.set_position(cursor_pos.x);
			utf8_reader.prev();
			int length = utf8_reader.char_length();
			lines[cursor_pos.y].text.erase(cursor_pos.x - length, length);
			lines[cursor_pos.y].invalidated = true;
			cursor_pos.x -= length;
			Update();
		}
		else if (cursor_pos.y > 0)
		{
			selection_start = ivec2(lines[cursor_pos.y - 1].text.length(), cursor_pos.y - 1);
			selection_length = 1;
			DeleteSelectedText();
		}
	}
	MoveVerticalScroll();
}
void TextEdit::Del()
{
	if (undo_info.first_erase)
	{
		undo_info.first_erase = false;
		undo_info.undo_text = GetText();
	}
	if (GetSelectionLength() != 0)
	{
		DeleteSelectedText();
		ClearSelection();
		Update();
	}
	else
	{
		if (cursor_pos.x < (int)lines[cursor_pos.y].text.size())
		{
			UTF8Reader utf8_reader(lines[cursor_pos.y].text.data(), lines[cursor_pos.y].text.length());
			utf8_reader.set_position(cursor_pos.x);
			int length = utf8_reader.char_length();
			lines[cursor_pos.y].text.erase(cursor_pos.x, length);
			lines[cursor_pos.y].invalidated = true;
			Update();
		}
		else if (cursor_pos.y + 1 < (int)lines.size())
		{
			selection_start = ivec2((int)lines[cursor_pos.y].text.length(), cursor_pos.y);
			selection_length = 1;
			DeleteSelectedText();
		}
	}
	MoveVerticalScroll();
}
void TextEdit::OnTimerExpired()
{
	if (IsVisible() == false)
	{
		timer->Stop();
		return;
	}
	if (cursor_blink_visible)
		timer->Start(500);
	else
		timer->Start(500);
	cursor_blink_visible = !cursor_blink_visible;
	Update();
}
void TextEdit::OnGeometryChanged()
{
	Canvas* canvas = GetCanvas();
	for (auto& line : lines)
	{
		line.invalidated = true;
	}
	vertical_text_align = canvas->verticalTextAlign();
	clip_start_offset = 0;
	UpdateVerticalScroll();
}
void TextEdit::OnScrollTimerExpired()
{
	if (mouse_moves_left)
		Move(-1, false, false);
	else
		Move(1, false, false);
}
void TextEdit::OnEnableChanged()
{
	bool enabled = IsEnabled();
	if (!enabled)
	{
		cursor_blink_visible = false;
		timer->Stop();
	}
	Update();
}
bool TextEdit::InputMaskAcceptsInput(ivec2 cursor_pos, const std::string& str)
{
	return str.find_first_not_of(input_mask) == std::string::npos;
}
std::string::size_type TextEdit::ToOffset(ivec2 pos) const
{
	if (pos.y < (int)lines.size())
	{
		std::string::size_type offset = 0;
		for (int line = 0; line < pos.y; line++)
		{
			offset += lines[line].text.size() + 1;
		}
		return offset + std::min((size_t)pos.x, lines[pos.y].text.size());
	}
	else
	{
		std::string::size_type offset = 0;
		for (size_t line = 0; line < lines.size(); line++)
		{
			offset += lines[line].text.size() + 1;
		}
		return offset - 1;
	}
}
TextEdit::ivec2 TextEdit::FromOffset(std::string::size_type offset) const
{
	int line_offset = 0;
	for (int line = 0; line < (int)lines.size(); line++)
	{
		if (offset <= line_offset + lines[line].text.size())
		{
			return ivec2(offset - line_offset, line);
		}
		line_offset += lines[line].text.size() + 1;
	}
	return ivec2(lines.back().text.size(), lines.size() - 1);
}
double TextEdit::GetTotalHeight()
{
	Canvas* canvas = GetCanvas();
	LayoutLines(canvas);
	if (!lines.empty())
	{
		return lines.back().box.bottom();
	}
	else
	{
		return GetHeight();
	}
}
void TextEdit::LayoutLines(Canvas* canvas)
{
	ivec2 sel_start;
	ivec2 sel_end;
	if (selection_length > 0)
	{
		sel_start = selection_start;
		sel_end = FromOffset(ToOffset(selection_start) + selection_length);
	}
	else if (selection_length < 0)
	{
		sel_start = FromOffset(ToOffset(selection_start) + selection_length);
		sel_end = selection_start;
	}
	Colorf textColor = GetStyleColor("color");
	Point draw_pos;
	for (size_t i = (size_t)vert_scrollbar->GetPosition(); i < lines.size(); i++)
	{
		Line& line = lines[i];
		if (line.invalidated)
		{
			line.layout.Clear();
			if (!line.text.empty())
				line.layout.AddText(line.text, font, textColor);
			else
				line.layout.AddText(" ", font, textColor); // Draw one space character to get the correct height
			line.layout.Layout(canvas, GetWidth() - vert_scrollbar->GetPreferredWidth());
			line.box = Rect(draw_pos, line.layout.GetSize());
			line.invalidated = false;
		}
		if (sel_start != sel_end && sel_start.y <= (int)i && sel_end.y >= (int)i)
		{
			line.layout.SetSelectionRange(sel_start.y < (int)i ? 0 : sel_start.x, sel_end.y > (int)i ? line.text.size() : sel_end.x);
		}
		else
		{
			line.layout.SetSelectionRange(0, 0);
		}
		line.layout.HideCursor();
		if (HasFocus())
		{
			if (cursor_blink_visible && cursor_pos.y == (int)i)
			{
				line.layout.SetCursorPos(cursor_pos.x);
				line.layout.SetCursorColor(textColor);
				line.layout.ShowCursor();
			}
		}
		line.box.x = draw_pos.x;
		line.box.y = draw_pos.y;
		line.layout.SetPosition(line.box.topLeft());
		draw_pos = line.box.bottomLeft();
	}
	UpdateVerticalScroll();
}
void TextEdit::OnPaint(Canvas* canvas)
{
	LayoutLines(canvas);
	for (size_t i = (size_t)vert_scrollbar->GetPosition(); i < lines.size(); i++)
		lines[i].layout.DrawLayout(canvas);
}
TextEdit::ivec2 TextEdit::GetCharacterIndex(Point mouse_wincoords)
{
	Canvas* canvas = GetCanvas();
	for (size_t i = 0; i < lines.size(); i++)
	{
		Line& line = lines[i];
		if (line.box.top() <= mouse_wincoords.y && line.box.bottom() > mouse_wincoords.y)
		{
			SpanLayout::HitTestResult result = line.layout.HitTest(canvas, mouse_wincoords);
			switch (result.type)
			{
			case SpanLayout::HitTestResult::inside:
				return ivec2(clamp(result.offset, (size_t)0, line.text.size()), i);
			case SpanLayout::HitTestResult::outside_left:
				return ivec2(0, i);
			default:
			case SpanLayout::HitTestResult::outside_right:
				return ivec2(line.text.size(), i);
			}
		}
	}
	return ivec2(lines.back().text.size(), lines.size() - 1);
}

#include "WALRUS.hh"
#include <fstream>
#include <algorithm>
/*! @file
 * @brief implements the try and check of a time step
*/
double WALRUS::fGS_dG(double dG) {
  return (cD - _dG - _hS) * std::max(cD - dG, _hS) / cG;
}
void WALRUS::calctryvalues(double tend) {
  double cumP = get_cum(fc_P, _time, tend);
  double cumETpot = get_cum(fc_ETpot, _time, tend);
  P_try = cumP;
  ETpot_try = cumETpot;
  fXG_try = get_cum(fc_XG, _time, tend);
  fXS_try = get_cum(fc_XS, _time, tend);
  fXSact_try = fXS_try;
  _W = W_dV(_dV);
  _dVeq = dVeq_dG(_dG);
  PQ_try = cumP * _W * aG;
  PV_try = cumP * (1 - _W) * aG;
  PS_try = cumP * aS;
  ETV_try = cumETpot * beta_dV(_dV) * aG;
  if (_hS > hSzeroforET) {
    ETS_try = cumETpot * aS;
  } else {
    ETS_try = 0;
  }
  double dt = (tend - _time) / 3600; // dt is in hours now
  ETact_try = ETV_try + ETS_try;
  fQS_try = _hQ / cQ * dt;
  fGS_try = fGS_dG(_dG) * dt;
  Q_try = Q_hS(_hS) * dt;
  // now states, save the changes for later control
  dV_try = _dV + (-fXG_try - PV_try + ETV_try + fGS_try) / aG;
  hQ_try = _hQ + (PQ_try - fQS_try) / aG;
 // update March2018, update May 2021
  if (hQ_try < min_h ) {
        fQS_try = fQS_try + (hQ_try - min_h) * aG;
        hQ_try = min_h ;
  }
  // end update
  hS_try = _hS + (fXSact_try + PS_try - ETS_try + fGS_try + fQS_try - Q_try) / aS;
 // update March2018
  if (hS_try < 0 && fXSact_try < 0) {
    fXSact_try = fXSact_try - hS_try * aS;
    hS_try = 0;
  }
  // end update
  dG_try = _dG + (_dV - _dVeq) / cV * dt;
  // special case: large scale ponding and flooding
  if ((dV_try < 0) || (hS_try > cD)) {
    if ((dV_try < 0) && (hS_try <= cD)) {
      // ponding and no flooding
      // hS_try = _hS - dV_try * aG / aS;  GP 6may2021
      hS_try = hS_try - dV_try * aG / aS;
      // all ponds to surface water
      dV_try = 0;
      // soil completely saturated
      // addition GP for stability/quick convergence
      if (hS_try > cD) {
      // flooding and no ponding
      dV_try = dV_try + (-hS_try + cD) * aS / aG;
      hS_try = cD;
      }
    }
    else if ((dV_try >= 0) && (hS_try > cD)) {
      // flooding and no ponding
      // dV_try = _dV + (-hS_try + cD) * aS / aG;  GP 6may2021 ok
      dV_try = dV_try + (-hS_try + cD) * aS / aG;
      // flood goes all in soil
      hS_try = cD;
      // bankfull
    }
    else if ((dV_try < 0) && (hS_try > cD)) {
      // ponding and flooding
      // dV_try = _dV * aG - (hS_try - cD) * aS;   GP 6may2021
      dV_try = dV_try - (hS_try - cD) * aS / aG ;
      // compute total excess water
      // hS_try = cD - dV_try;
      hS_try = cD;
    }
    if (dV_try < 0) {
      dG_try = dV_try;
      // groundwater to pond level
    }
  }
}
double WALRUS::pred_time_tries_OK(double tend) {
  if (tend < _time + min_deltime) {
    return tend;
  }
  //return tend;
  double tc = tend;
  // check op < ipv <=
  if (hS_try < min_h) {
    double f = (_hS - min_h) / (_hS - hS_try);
    double thS = f * (tend) + (1 - f) * _time;
    if (thS < tc) {
      tc = thS;
    }
    hS_try = min_h; // avoid negative heights
  }
  // check op < ipv <=
  if (hQ_try < min_h) {
    double f = (_hQ - min_h) / (_hQ - hQ_try);
    double thQ = f * (tend) + (1 - f) * _time;
    if (thQ < tc) {
      tc = thQ;
    }
    hQ_try = min_h; // avoid negative heights
  }
  double P_step = get_cum(fc_P, _time, tend);
  if (P_step > max_Pstep) {
    double f = max_Pstep / P_step;
    double tP = f * (tend) + (1 - f) * _time;
    if (tP < tc) {
      tc = tP;
    }
  }
  double ETpot_step = get_cum(fc_ETpot, _time, tend);
  if (ETpot_step > max_Pstep) {
    double f = max_Pstep / ETpot_step;
    double tETpot = f * (tend) + (1 - f) * _time;
    if (tETpot < tc) {
      tc = tETpot;
    }
  }
  double fXG_step = get_cum(fc_XG, _time, tend);
  if (fXG_step > max_Pstep) {
    double f = max_Pstep / fXG_step;
    double tfXG = f * (tend) + (1 - f) * _time;
    if (tfXG < tc) {
      tc = tfXG;
    }
  }
  double fXS_step = get_cum(fc_XS, _time, tend);
  if (fXS_step > max_Pstep) {
    double f = max_Pstep / fXS_step;
    double tfXS = f * (tend) + (1 - f) * _time;
    if (tfXS < tc) {
      tc = tfXS;
    }
  }
  double abs_hS_change_step = std::fabs(hS_try - _hS);
  if (abs_hS_change_step > max_h_change) {
    double f = max_h_change / abs_hS_change_step;
    double thS_change = f * (tend) + (1 - f) * _time;
    if (thS_change < tc) {
      tc = thS_change;
    }
  }
  double abs_hQ_change_step = std::fabs(hQ_try - _hQ);
  if (abs_hQ_change_step > max_h_change) {
    double f = max_h_change / abs_hQ_change_step;
    double thQ_change = f * (tend) + (1 - f) * _time;
    if (thQ_change < tc) {
      tc = thQ_change;
    }
  }
  double abs_dG_change_step = std::fabs(dG_try - _dG);
  if (abs_dG_change_step > max_h_change) {
    double f = max_h_change / abs_dG_change_step;
    double tdG_change = f * (tend) + (1 - f) * _time;
    if (tdG_change < tc) {
      tc = tdG_change;
    }
  }
  if (tc <= _time) {
     tc = _time + min_deltime;
  }
  if (tc > tend) {
     tc = tend;
  }
  return tc;
}

