    {                                                                                                                  \
        EXPECT_EQ(ExecuteProcess("StackOverflow", #module), STACK_OVERFLOW_RETURN_CODE);                                  \
        VerifyErrorOutput("StackOverflow", #module);                                                                   \
    }
