            la_xvreplve0_d(mask, src2);
            la_xvldi(temp, VLDI_IMM_TYPE0(3, 63));
            la_xvsle_du(mask, mask, temp);
        } else {
            la_xvreplve0_d(mask, src2);
            la_xvslei_du(mask, mask, max_count);
