    int max_count;
    switch (ir1_opcode(pir1)) {
        case dt_X86_INS_VPSRAW:
            rep_inst = la_xvreplve0_h;
            tr_inst_i = la_xvsrai_h;
            tr_inst_r = la_xvsra_h;
