struct StackRGBA
{
	StackRGBA& operator +=(const StackRGBA& other)
	{
		this->r += other.r;
		this->g += other.g;
		this->b += other.b;
		this->a += other.a;
		return *this;
	}
	StackRGBA& operator -=(const StackRGBA& other)
	{
		this->r -= other.r;
		this->g -= other.g;
		this->b -= other.b;
		this->a -= other.a;
		return *this;
	}
	StackRGBA& operator -=(const uint8_t* ptr)
	{
		this->r -= ptr[0];
		this->g -= ptr[1];
		this->b -= ptr[2];
		this->a -= ptr[3];
		return *this;
	}
	void Add(const uint8_t* ptr, uint8_t multiplier = 1)
	{
		r += ptr[0] * multiplier;
		g += ptr[1] * multiplier;
		b += ptr[2] * multiplier;
		a += ptr[3] * multiplier;
	}
	void Reset()
	{
		r = 0;
		g = 0;
		b = 0;
		a = 0;
	}
	uint32_t r{}, g{}, b{}, a{};
};
StackBlur::StackBlur(uint8_t p_radius, const D2D1_SIZE_U& p_size) : radius(std::clamp<uint8_t>(p_radius, 2, 254)), size(p_size)
{
	div = (radius * 2U) + 1U;
	cores = std::max(1U, std::thread::hardware_concurrency());
	shr_sum = stackblur_shr[radius];
	mul_sum = stackblur_mul[radius];
}
void StackBlur::Run(uint8_t* src) noexcept
{
	const uint32_t stack_size = div * 4U * cores;
	std::vector<uint8_t> stack(stack_size);
	std::vector<std::thread> workers(cores);
	for (uint32_t core = 0; core < cores; ++core)
	{
		workers[core] = std::thread([&, core]
			{
				const uint32_t offset = div * 4U * core;
				StackBlurThread(1, core, src, &stack[offset]);
			});
	}
	for (auto&& worker : workers)
	{
		worker.join();
	}
	for (uint32_t core = 0; core < cores; ++core)
	{
		workers[core] = std::thread([&, core]
			{
				const uint32_t offset = div * 4U * core;
				StackBlurThread(2, core, src, &stack[offset]);
			});
	}
	for (auto&& worker : workers)
	{
		worker.join();
	}
}
void StackBlur::InitPtr(uint8_t* ptr, const StackRGBA& sum) noexcept
{
	ptr[0] = static_cast<uint8_t>((sum.r * mul_sum) >> shr_sum);
	ptr[1] = static_cast<uint8_t>((sum.g * mul_sum) >> shr_sum);
	ptr[2] = static_cast<uint8_t>((sum.b * mul_sum) >> shr_sum);
	ptr[3] = static_cast<uint8_t>((sum.a * mul_sum) >> shr_sum);
}
void StackBlur::StackBlurThread(uint32_t step, uint32_t core, uint8_t* src, uint8_t* stack) noexcept
{
	StackRGBA sum, sum_in, sum_out;
	uint8_t* stack_ptr;
	uint8_t* src_ptr;
	uint8_t* dst_ptr;
	const uint32_t wm = size.width - 1;
	const uint32_t hm = size.height - 1;
	const uint32_t w4 = size.width * 4;
	uint32_t sp{}, stack_start{};
	if (step == 1)
	{
		const uint32_t minY = core * size.height / cores;
		const uint32_t maxY = (core + 1) * size.height / cores;
		for (uint32_t y = minY; y < maxY; ++y)
		{
			sum.Reset();
			sum_in.Reset();
			sum_out.Reset();
			src_ptr = src + w4 * y;
			for (uint8_t i = 0; i <= radius; ++i)
			{
				stack_ptr = &stack[i * 4];
				memcpy(stack_ptr, src_ptr, 4);
				sum.Add(src_ptr, i + 1);
				sum_out.Add(src_ptr);
			}
			for (uint8_t i = 1; i <= radius; ++i)
			{
				if (i <= wm) src_ptr += 4;
				stack_ptr = &stack[4 * (i + radius)];
				memcpy(stack_ptr, src_ptr, 4);
				sum.Add(src_ptr, radius + 1 - i);
				sum_in.Add(src_ptr);
			}
			sp = radius;
			uint32_t xp = std::min<uint32_t>(radius, wm);
			src_ptr = src + 4 * (xp + y * size.width);
			dst_ptr = src + y * w4;
			for (uint32_t x = 0; x < size.width; ++x)
			{
				InitPtr(dst_ptr, sum);
				dst_ptr += 4;
				stack_start = sp + div - radius;
				if (stack_start >= div)
				{
					stack_start -= div;
				}
				stack_ptr = &stack[4 * stack_start];
				if (xp < wm)
				{
					src_ptr += 4;
					++xp;
				}
				sum -= sum_out;
				sum_out -= stack_ptr;
				memcpy(stack_ptr, src_ptr, 4);
				sum_in.Add(src_ptr);
				sum += sum_in;
				++sp;
				if (sp >= div)
				{
					sp = 0;
				}
				stack_ptr = &stack[sp * 4];
				sum_out.Add(stack_ptr);
				sum_in -= stack_ptr;
			}
		}
	}
	else if (step == 2)
	{
		const uint32_t minX = core * size.width / cores;
		const uint32_t maxX = (core + 1) * size.width / cores;
		for (uint32_t x = minX; x < maxX; ++x)
		{
			sum.Reset();
			sum_in.Reset();
			sum_out.Reset();
			src_ptr = src + 4 * x;
			for (uint8_t i = 0; i <= radius; ++i)
			{
				stack_ptr = &stack[i * 4];
				memcpy(stack_ptr, src_ptr, 4);
				sum.Add(src_ptr, i + 1);
				sum_out.Add(src_ptr);
			}
			for (uint8_t i = 1; i <= radius; ++i)
			{
				if (i <= hm)
				{
					src_ptr += w4;
				}
				stack_ptr = &stack[4 * (i + radius)];
				memcpy(stack_ptr, src_ptr, 4);
				sum.Add(src_ptr, radius + 1 - i);
				sum_in.Add(src_ptr);
			}
			sp = radius;
			uint32_t yp = std::min<uint32_t>(radius, hm);
			src_ptr = src + 4 * (x + yp * size.width);
			dst_ptr = src + 4 * x;
			for (uint32_t y = 0; y < size.height; ++y)
			{
				InitPtr(dst_ptr, sum);
				dst_ptr += w4;
				stack_start = sp + div - radius;
				if (stack_start >= div)
				{
					stack_start -= div;
				}
				stack_ptr = &stack[4 * stack_start];
				if (yp < hm)
				{
					src_ptr += w4;
					++yp;
				}
				sum -= sum_out;
				sum_out -= stack_ptr;
				memcpy(stack_ptr, src_ptr, 4);
				sum_in.Add(src_ptr);
				sum += sum_in;
				++sp;
				if (sp >= div)
				{
					sp = 0;
				}
				stack_ptr = &stack[sp * 4];
				sum_out.Add(stack_ptr);
				sum_in -= stack_ptr;
			}
		}
	}
}

#include "TwoElevenLogic.h"
#include "TwoElevenHelpers.h"
#include <stdlib.h>
#include <time.h>
#include <string.h>
/**
 * @brief Initialize the matrix with two random tiles
 */
void init_matrix_num(uint16_t matrix_size, uint16_t **matrix)
{
    for (uint8_t x = 0; x < matrix_size; x++) {
        for (uint8_t y = 0; y < matrix_size; y++) {
            matrix[x][y] = 0;
        }
    }
    // Add two random tiles
    add_random(matrix_size, matrix);
    add_random(matrix_size, matrix);
}
/**
 * @brief Add a random tile (2 or 4) to the matrix
 */
void add_random(uint16_t matrix_size, uint16_t **matrix)
{
    static bool initialized = false;
    if (!initialized) {
        srand((unsigned int)time(NULL));
        initialized = true;
    }
    uint16_t empty[matrix_size * matrix_size][2];
    uint16_t len = 0;
    for (uint8_t x = 0; x < matrix_size; x++) {
        for (uint8_t y = 0; y < matrix_size; y++) {
            if (matrix[x][y] == 0) {
                empty[len][0] = x;
                empty[len][1] = y;
                len++;
            }
        }
    }
    if (len > 0) {
        uint16_t r = rand() % len;
        uint8_t x = empty[r][0];
        uint8_t y = empty[r][1];
        uint16_t n = (rand() % 10 == 0) ? 2 : 1; // 10% chance for 4, else 2
        matrix[x][y] = n;
    }
}
/**
 * @brief Move up (or left/right/down via rotation)
 */
bool move_up(uint16_t * score, uint16_t matrix_size, uint16_t **matrix) {
    bool success = false;
    for (uint8_t x = 0; x < matrix_size; x++) {
        success |= slide_array(score, matrix_size, matrix[x]);
    }
    return success;
}
bool move_down(uint16_t * score, uint16_t matrix_size, uint16_t **matrix) {
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    bool success = move_up(score, matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    return success;
}
bool move_left(uint16_t * score, uint16_t matrix_size, uint16_t **matrix) {
    rotate_matrix(matrix_size, matrix);
    bool success = move_up(score, matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    return success;
}
bool move_right(uint16_t * score, uint16_t matrix_size, uint16_t **matrix) {
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    bool success = move_up(score, matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    return success;
}
/**
 * @brief Check if the game is over (no moves left)
 *        Does not mutate the original matrix
 */
bool game_over(uint16_t matrix_size, const uint16_t **matrix) {
    if (count_empty(matrix_size, matrix) > 0) return false;
    if (find_pair_down(matrix_size, matrix)) return false;
    // Check for possible moves in rotated matrices
    uint16_t **temp = lv_malloc(matrix_size * sizeof(uint16_t*));
    for (uint16_t i = 0; i < matrix_size; i++) {
        temp[i] = lv_malloc(matrix_size * sizeof(uint16_t));
        memcpy(temp[i], matrix[i], matrix_size * sizeof(uint16_t));
    }
    rotate_matrix(matrix_size, temp);
    if (find_pair_down(matrix_size, (const uint16_t **)temp)) {
        for (uint16_t i = 0; i < matrix_size; i++) lv_free(temp[i]);
        lv_free(temp);
        return false;
    }
    rotate_matrix(matrix_size, temp);
    if (find_pair_down(matrix_size, (const uint16_t **)temp)) {
        for (uint16_t i = 0; i < matrix_size; i++) lv_free(temp[i]);
        lv_free(temp);
        return false;
    }
    rotate_matrix(matrix_size, temp);
    if (find_pair_down(matrix_size, (const uint16_t **)temp)) {
        for (uint16_t i = 0; i < matrix_size; i++) lv_free(temp[i]);
        lv_free(temp);
        return false;
    }
    for (uint16_t i = 0; i < matrix_size; i++) lv_free(temp[i]);
    lv_free(temp);
    return true;
}
/**
 * @brief Get the current score
 */
uint32_t twoeleven_get_score(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return 0;
    return game_2048->score;
}
/**
 * @brief Get the game over status
 */
bool twoeleven_get_status(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return true;
    return game_2048->game_over;
}
/**
 * @brief Get the best tile value
 */
uint16_t twoeleven_get_best_tile(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return 0;
    uint16_t best_tile = 0;
    for (uint8_t x = 0; x < game_2048->matrix_size; x++) {
        for (uint8_t y = 0; y < game_2048->matrix_size; y++) {
            if (best_tile < game_2048->matrix[x][y]) {
                best_tile = game_2048->matrix[x][y];
            }
        }
    }
    return (uint16_t)(1 << best_tile);
}

