//  Other Public Functions
char *
Stream::LocalHandle(
    void)
{
    return this->local.handle;
}
char *
Stream::RemoteHandle(
    void)
{
    if (this->connected)
        return this->remote.handle;
    else
    {
        switch (streamtype)
        {
#if defined(WITH_MPI)
        case Stream::MPI:
            return (char *)"[mpi]:*:*";
#endif
        case Stream::TCPIP:
            return (char *)"[unknown]:0";
        default:
            return NULL;
        }
    }
}
