        std::string text = args.arg2;
        if (args.rest.length() > 0) {
            text = args.arg2 + " " + args.rest;
        }

        if (text.length() == 0) {
            printLine("Usage: base64 encode <text>");
            printLine("       base64 decode <text>");
            return;
        }

        base64Command(operation, text);
    }   
