    }
    else if (baseCmd == "help" || baseCmd == "h") {
        if (args.arg1.length() == 0) {
            showHelp();
        } else if (args.arg1 == "file") {
            showHelpFile();
        } else if (args.arg1 == "system") {
            showHelpSystem();
        } else if (args.arg1 == "network") {
            showHelpNetwork();
