void MemSlotVector::takeover(PhyloNeighbor *nei, PhyloNeighbor *taken_nei) {
    ASSERT(taken_nei->partial_lh);
    nei->partial_lh = taken_nei->partial_lh;
    nei->scale_num = taken_nei->scale_num;
    taken_nei->partial_lh = NULL;
    taken_nei->scale_num = NULL;
    taken_nei->partial_lh_computed &= ~1; // clear bit
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;
    iterator id = findNei(taken_nei);
//    if (id->status & MEM_SPECIAL)
//        return;
    nei_id_map.erase(nei_id_map.find(taken_nei));
    nei_id_map[nei] = id - begin();
    if (id->nei == taken_nei) {
        id->nei = nei;
    }
}
void MemSlotVector::replace(PhyloNeighbor *new_nei, PhyloNeighbor *old_nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;
    iterator it = findNei(old_nei);
    ASSERT(it->partial_lh == old_nei->partial_lh);
    it->saved_nei = it->nei;
    it->nei = new_nei;
    it->partial_lh = new_nei->partial_lh;
    it->scale_num = new_nei->scale_num;
    it->status = MEM_LOCKED + MEM_SPECIAL;
    nei_id_map[new_nei] = it-begin();
//    nei_id_map.erase(old_nei);
    cout << "slot " << distance(begin(), it) << " replaced" << endl;
}
void MemSlotVector::restore(PhyloNeighbor *new_nei, PhyloNeighbor *old_nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;
    iterator it = findNei(new_nei);
    ASSERT(it->nei == new_nei);
    ASSERT(nei_id_map[old_nei] == it-begin());
    it->nei = it->saved_nei;
    it->saved_nei = NULL;
    it->partial_lh = old_nei->partial_lh;
    it->scale_num = old_nei->scale_num;
    it->status = 0;
    nei_id_map.erase(new_nei);
//    nei_id_map[old_nei] = it;
    cout << "slot " << distance(begin(), it) << " restored" << endl;
}

#include "Utils/Parallel/MultiThreading.h"
// Initializes a pthread mutex.
PPMutex::PPMutex() {
  int res = pthread_mutex_init(&mutex, nullptr);
  is_valid = (res == 0);
}
// Destroys the pthread mutex.
PPMutex::~PPMutex() {
  pthread_mutex_destroy(&mutex);
  is_valid = false;
}
// Returns true if the mutex was successfully initialized.
bool PPMutex::isValid() { return is_valid; }
// Locks the mutex. Returns true on success.
bool PPMutex::lock() {
  if (!isValid()) {
    return false;
  }
  int res = pthread_mutex_lock(&mutex);
  return res == 0;
}
// Unlocks the mutex. Returns true on success.
bool PPMutex::unlock() {
  if (!isValid()) {
    return false;
  }
  int res = pthread_mutex_unlock(&mutex);
  return res == 0;
}
// Initializes a pthread read-write lock.
PPReadWriteLock::PPReadWriteLock() {
  int res = pthread_rwlock_init(&mutex, nullptr);
  is_valid = (res == 0);
}
// Destroys the pthread read-write lock.
PPReadWriteLock::~PPReadWriteLock() {
  pthread_rwlock_destroy(&mutex);
  is_valid = false;
}
// Returns true if the read-write lock was successfully initialized.
bool PPReadWriteLock::isValid() { return is_valid; }
// Acquires a read lock. Returns true on success.
bool PPReadWriteLock::rdLock() {
  if (!isValid()) {
    return false;
  }
  int res = pthread_rwlock_rdlock(&mutex);
  return res == 0;
}
// Acquires a write lock. Returns true on success.
bool PPReadWriteLock::wrLock() {
  if (!isValid()) {
    return false;
  }
  int res = pthread_rwlock_wrlock(&mutex);
  return res == 0;
}
// Releases a read lock. Returns true on success.
bool PPReadWriteLock::rdUnlock() {
  if (!isValid()) {
    return false;
  }
  int res = pthread_rwlock_unlock(&mutex);
  return res == 0;
}
// Releases a write lock. Returns true on success.
bool PPReadWriteLock::wrUnlock() {
  if (!isValid()) {
    return false;
  }
  int res = pthread_rwlock_unlock(&mutex);
  return res == 0;
}
// Initializes thread-specific data with a destructor.
PPThreadData::PPThreadData(void (*destructor)(void *)) {
  int res = pthread_key_create(&key, destructor);
  is_valid = (res == 0);
}
// Destroys the thread-specific data key.
PPThreadData::~PPThreadData() {
  pthread_key_delete(key);
  is_valid = false;
}
// Returns true if the thread data was successfully initialized.
bool PPThreadData::isValid() { return is_valid; }
// Sets thread-specific data. Returns true on success.
bool PPThreadData::setValue(void *data) {
  if (!isValid()) {
    return false;
  }
  int res = pthread_setspecific(key, data);
  return res == 0;
}
// Gets thread-specific data. Returns nullptr if invalid.
void *PPThreadData::getValue() {
  if (!isValid()) {
    return nullptr;
  }
  return pthread_getspecific(key);
}
// Returns the current thread ID.
PPThreadIDType getCurrentThreadID() { return pthread_self(); }

#include "ftpdaemon.h"
#include <circle/logger.h>
#include <circle/net/in.h>
#include <circle/net/ipaddress.h>
#include <circle/net/netsubsystem.h>
#include <circle/string.h>
#include "ftpworker.h"
LOGMODULE("ftpd");
constexpr u16 ListenPort = 21;
constexpr u8 MaxConnections = 1;
CFTPDaemon::CFTPDaemon(const char* pUser, const char* pPassword)
    : CTask(TASK_STACK_SIZE, true),
      m_pListenSocket(nullptr),
      m_pUser(pUser),
      m_pPassword(pPassword) {
}
CFTPDaemon::~CFTPDaemon() {
    if (m_pListenSocket)
        delete m_pListenSocket;
}
bool CFTPDaemon::Initialize() {
    CNetSubSystem* const pNet = CNetSubSystem::Get();
    if ((m_pListenSocket = new CSocket(pNet, IPPROTO_TCP)) == nullptr)
        return false;
    if (m_pListenSocket->Bind(ListenPort) != 0) {
        LOGERR("Couldn't bind to port %d", ListenPort);
        return false;
    }
    if (m_pListenSocket->Listen() != 0) {
        LOGERR("Failed to listen on control socket");
        return false;
    }
    // We started as a suspended task; run now that initialization is successful
    Start();
    return true;
}
void CFTPDaemon::Run() {
    assert(m_pListenSocket != nullptr);
    LOGNOTE("Listener task spawned");
    while (true) {
        CIPAddress ClientIPAddress;
        u16 nClientPort;
        LOGDBG("Listener: waiting for connection");
        CSocket* pConnection = m_pListenSocket->Accept(&ClientIPAddress, &nClientPort);
        if (pConnection == nullptr) {
            LOGERR("Unable to accept connection");
            continue;
        }
        CString IPAddressString;
        ClientIPAddress.Format(&IPAddressString);
        LOGNOTE("Incoming connection from %s:%d", static_cast<const char*>(IPAddressString), nClientPort);
        if (CFTPWorker::GetInstanceCount() >= MaxConnections) {
            pConnection->Send("421 Maximum number of connections reached.\r\n", 45, 0);
            delete pConnection;
            LOGWARN("Maximum number of connections reached");
            continue;
        }
        // Spawn new worker
        new CFTPWorker(pConnection, m_pUser, m_pPassword);
    }
}

