#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <stack>
#include <cassert>
using namespace std;
struct Chamber {
    int id;
    int parent;           
    int entry_passage;    
    int next_passage;     
    int stone_side;       // 0 left, 1 right
    int stone_passage;    
    bool finished;
};
int m;
int next_id = 0;
vector<Chamber> chambers;
map<pair<int, int>, int> signature_to_id; // (side, passage) -> id
stack<int> dfs_stack;
void read_stone(string& side_str, int& passage) {
    cin >> side_str;
    if (side_str == "center") {
        passage = -1;
    } else if (side_str == "left" || side_str == "right") {
        cin >> passage;
    } else if (side_str == "treasure") {
        passage = -1;
    }
}
int side_to_int(const string& s) {
    if (s == "left") return 0;
    if (s == "right") return 1;
    return -1;
}
string int_to_side(int x) {
    return x == 0 ? "left" : "right";
}
int dist(int a, int b) {
    return (b - a + m) % m;
}
int main() {
    cin >> m;
    string side_str;
    int passage;
    read_stone(side_str, passage);
    assert(side_str == "center");
    Chamber root;
    root.id = next_id++;
    root.parent = -1;
    root.entry_passage = -1;
    root.next_passage = 0;
    root.stone_side = 0;
    root.stone_passage = 0;
    root.finished = false;
    chambers.push_back(root);
    signature_to_id[{0, 0}] = root.id;
    dfs_stack.push(root.id);
    cout << "0 left 0" << endl;
    while (true) {
        read_stone(side_str, passage);
        if (side_str == "treasure") {
            break;
        }
        int current_id;
        if (side_str == "center") {
            Chamber new_ch;
            new_ch.id = next_id++;
            new_ch.parent = dfs_stack.top();
            new_ch.entry_passage = -1;
            new_ch.next_passage = 0;
            new_ch.finished = false;
            int sig_side, sig_pass;
            if (new_ch.id < m) {
                sig_side = 0;
                sig_pass = new_ch.id;
            } else if (new_ch.id - m < m) {
                sig_side = 1;
                sig_pass = new_ch.id - m;
            } else {
                sig_side = (new_ch.id / m) % 2;
                sig_pass = new_ch.id % m;
            }
            new_ch.stone_side = sig_side;
            new_ch.stone_passage = sig_pass;
            chambers.push_back(new_ch);
            signature_to_id[{sig_side, sig_pass}] = new_ch.id;
            current_id = new_ch.id;
            dfs_stack.push(current_id);
        } else {
            int side_int = side_to_int(side_str);
            auto key = make_pair(side_int, passage);
            if (signature_to_id.find(key) == signature_to_id.end()) {
                Chamber new_ch;
                new_ch.id = next_id++;
                new_ch.parent = -1;
                new_ch.entry_passage = -1;
                new_ch.next_passage = 0;
                new_ch.stone_side = side_int;
                new_ch.stone_passage = passage;
                new_ch.finished = false;
                chambers.push_back(new_ch);
                signature_to_id[key] = new_ch.id;
                current_id = new_ch.id;
                dfs_stack.push(current_id);
            } else {
                current_id = signature_to_id[key];
            }
        }
        Chamber& cur = chambers[current_id];
        if (cur.next_passage < m) {
            int k = cur.next_passage;
            cur.next_passage++;
            int d1 = dist(cur.stone_passage, k);
            cout << d1 << " left " << d1 << endl;
            cur.stone_side = 0;
            cur.stone_passage = k;
            signature_to_id[{0, k}] = current_id;
        } else {
            cur.finished = true;
            if (cur.parent == -1) {
                int d1 = dist(cur.stone_passage, cur.stone_passage);
                cout << d1 << " right " << 0 << endl;
                cur.stone_side = 1;
                signature_to_id[{1, cur.stone_passage}] = current_id;
            } else {
                Chamber& par = chambers[cur.parent];
                int d1 = dist(cur.stone_passage, cur.entry_passage);
                int d2 = dist(cur.stone_passage, cur.entry_passage);
                cout << d1 << " right " << d2 << endl;
                cur.stone_side = 1;
                cur.stone_passage = cur.entry_passage;
                signature_to_id[{1, cur.entry_passage}] = current_id;
                dfs_stack.pop();
            }
        }
    }
    return 0;
}

#include "tserverproxy.h"
#include <iostream.h>
#include <Winsock.h>
#include <fcntl.h>
#include <errno.h>
#include <stdio.h>
#include <memory.h>
#include <time.h>
#include <assert.h>
using namespace std;
//=============================================================================
enum {
  OK,
  WSASTARTUP_FAILED,
  HOST_UNKNOWN,
  SOCKET_CREATION_FAILED,
  CONNECTION_FAILED,
  SEND_FAILED,
  RECEIVE_FAILED
};
//=============================================================================
int askServer(string hostName, int portId, string question, string &answer) {
  struct hostent *he = gethostbyname(hostName.c_str());
  if (!he) return HOST_UNKNOWN;
  int socket_id = socket(AF_INET, SOCK_STREAM, 0);
  struct sockaddr_in addr;
  memset((char *)&addr, 0, sizeof addr);
  addr.sin_family = he->h_addrtype;
  addr.sin_port   = htons(portId);
  memcpy((char *)&(addr.sin_addr), he->h_addr, he->h_length);
  int rcConnect = connect(socket_id, (struct sockaddr *)&(addr), sizeof addr);
  if (rcConnect == SOCKET_ERROR) return CONNECTION_FAILED;
  string message = question;
  int rcSend = send(socket_id, message.c_str(), message.size(), 0);
  if (rcSend == SOCKET_ERROR) return SEND_FAILED;
  char retBuffer[1024];
  memset(&retBuffer, 0, 1024);
  int rcRecv = recv(socket_id, retBuffer, sizeof(retBuffer) - 1, 0);
  if (rcRecv == SOCKET_ERROR) return RECEIVE_FAILED;
  retBuffer[rcRecv] = '\0';
  closesocket(socket_id);
  answer = retBuffer;
  return OK;
}
//=============================================================================
TServerProxy::TServerProxy(const string hostName, int portId)
    : m_hostName(hostName), m_portId(portId) {
#ifdef WIN32
  WSADATA wsaData;
  WORD wVersionRequested = MAKEWORD(1, 1);
  int irc                = WSAStartup(wVersionRequested, &wsaData);
#endif
}
//-----------------------------------------------------------------------------
TServerProxy::~TServerProxy() {
#ifdef WIN32
  WSACleanup();
#endif
}
//-----------------------------------------------------------------------------
bool TServerProxy::testConnection() const {
  struct hostent *he = gethostbyname(m_hostName.c_str());
  if (!he) return false;
  int socket_id = socket(AF_INET, SOCK_STREAM, 0);
  struct sockaddr_in addr;
  memset((char *)&addr, 0, sizeof addr);
  addr.sin_family = he->h_addrtype;
  addr.sin_port   = htons(m_portId);
  memcpy((char *)&(addr.sin_addr), he->h_addr, he->h_length);
  bool ret = (SOCKET_ERROR !=
              connect(socket_id, (struct sockaddr *)&(addr), sizeof addr));
  closesocket(socket_id);
  return ret;
}
//-----------------------------------------------------------------------------
int TServerProxy::exec(int argc, char *argv[], string &reply) {
  string cmd;
  assert(argc > 0);
  if (argc > 0) {
    cmd = argv[0];
    for (int i = 1; i < argc; ++i) {
      cmd += ",";
      cmd += argv[i];
    }
  }
  return askServer(m_hostName, m_portId, cmd, reply);
}

#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;
// Leetcode 3: Longest substring without repeating characters
class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int n = s.length();
        int maxLength = 0;
        unordered_map<char, int> charMap;
        int left = 0;
        for (int right = 0; right < n; right++) {
            if (charMap.count(s[right]) == 0 || charMap[s[right]] < left) {
                charMap[s[right]] = right;
                maxLength = max(maxLength, right - left + 1);
            } else {
                left = charMap[s[right]] + 1;
                charMap[s[right]] = right;
            }
        }
        return maxLength;
    }
};

