template <>
void LaunchContextBuilder::set_arg<TypedConstant>(int arg_id, TypedConstant d) {
  if (is_real(d.dt)) {
    set_arg_float(arg_id, d.val_float());
  } else if (is_signed(d.dt)) {
    set_arg_int(arg_id, d.val_int());
  } else {
