QString previous_game = "default";
bool isHelpOpen = false;
HelpDialog* helpDialog;
EditorDialog::EditorDialog(QWidget* parent) : QDialog(parent) {
    setWindowTitle(tr("Edit Keyboard + Mouse and Controller input bindings"));
    resize(600, 400);
    // Create the editor widget
    editor = new QPlainTextEdit(this);
    editorFont.setPointSize(10); // Set default text size
    editor->setFont(editorFont); // Apply font to the editor
    // Create the game selection combo box
    gameComboBox = new QComboBox(this);
    gameComboBox->addItem("default"); // Add default option
    // Load all installed games
    loadInstalledGames();
    QCheckBox* unifiedInputCheckBox = new QCheckBox(tr("Use Per-Game configs"), this);
    unifiedInputCheckBox->setChecked(!Config::GetUseUnifiedInputConfig());
    // Connect checkbox signal
    connect(unifiedInputCheckBox, &QCheckBox::toggled, this, [](bool checked) {
        Config::SetUseUnifiedInputConfig(!checked);
        Config::save(Common::FS::GetUserPath(Common::FS::PathType::UserDir) / "config.toml");
    });
    // Create Save, Cancel, and Help buttons
    QPushButton* saveButton = new QPushButton("Save", this);
    QPushButton* cancelButton = new QPushButton("Cancel", this);
    QPushButton* helpButton = new QPushButton("Help", this);
    QPushButton* defaultButton = new QPushButton("Default", this);
    // Layout for the game selection and buttons
    QHBoxLayout* topLayout = new QHBoxLayout();
    topLayout->addWidget(unifiedInputCheckBox);
    topLayout->addWidget(gameComboBox);
    topLayout->addStretch();
    topLayout->addWidget(saveButton);
    topLayout->addWidget(cancelButton);
    topLayout->addWidget(defaultButton);
    topLayout->addWidget(helpButton);
    // Main layout with editor and buttons
    QVBoxLayout* layout = new QVBoxLayout(this);
    layout->addLayout(topLayout);
    layout->addWidget(editor);
    // Load the default config file content into the editor
    loadFile(gameComboBox->currentText());
    // Connect button and combo box signals
    connect(saveButton, &QPushButton::clicked, this, &EditorDialog::onSaveClicked);
    connect(cancelButton, &QPushButton::clicked, this, &EditorDialog::onCancelClicked);
    connect(helpButton, &QPushButton::clicked, this, &EditorDialog::onHelpClicked);
    connect(defaultButton, &QPushButton::clicked, this, &EditorDialog::onResetToDefaultClicked);
    connect(gameComboBox, &QComboBox::currentTextChanged, this,
            &EditorDialog::onGameSelectionChanged);
}
void EditorDialog::loadFile(QString game) {
    const auto config_file = Config::GetFoolproofInputConfigFile(game.toStdString());
    QFile file(config_file);
    if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
        QTextStream in(&file);
        editor->setPlainText(in.readAll());
        originalConfig = editor->toPlainText();
        file.close();
    } else {
        QMessageBox::warning(this, tr("Error"), tr("Could not open the file for reading"));
    }
}
void EditorDialog::saveFile(QString game) {
    const auto config_file = Config::GetFoolproofInputConfigFile(game.toStdString());
    QFile file(config_file);
    if (file.open(QIODevice::WriteOnly | QIODevice::Text)) {
        QTextStream out(&file);
        out << editor->toPlainText();
        file.close();
    } else {
        QMessageBox::warning(this, tr("Error"), tr("Could not open the file for writing"));
    }
}
// Override the close event to show the save confirmation dialog only if changes were made
void EditorDialog::closeEvent(QCloseEvent* event) {
    if (isHelpOpen) {
        helpDialog->close();
        isHelpOpen = false;
        // at this point I might have to add this flag and the help dialog to the class itself
    }
    if (hasUnsavedChanges()) {
        QMessageBox::StandardButton reply;
        reply = QMessageBox::question(this, tr("Save Changes"), tr("Do you want to save changes?"),
                                      QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel);
        if (reply == QMessageBox::Yes) {
            saveFile(gameComboBox->currentText());
            event->accept(); // Close the dialog
        } else if (reply == QMessageBox::No) {
            event->accept(); // Close the dialog without saving
        } else {
            event->ignore(); // Cancel the close event
        }
    } else {
        event->accept(); // No changes, close the dialog without prompting
    }
}
void EditorDialog::keyPressEvent(QKeyEvent* event) {
    if (event->key() == Qt::Key_Escape) {
        if (isHelpOpen) {
            helpDialog->close();
            isHelpOpen = false;
        }
        close(); // Trigger the close action, same as pressing the close button
    } else {
        QDialog::keyPressEvent(event); // Call the base class implementation for other keys
    }
}
void EditorDialog::onSaveClicked() {
    if (isHelpOpen) {
        helpDialog->close();
        isHelpOpen = false;
    }
    saveFile(gameComboBox->currentText());
    reject(); // Close the dialog
}
void EditorDialog::onCancelClicked() {
    if (isHelpOpen) {
        helpDialog->close();
        isHelpOpen = false;
    }
    reject(); // Close the dialog
}
void EditorDialog::onHelpClicked() {
    if (!isHelpOpen) {
        helpDialog = new HelpDialog(&isHelpOpen, this);
        helpDialog->setWindowTitle(tr("Help"));
        helpDialog->setAttribute(Qt::WA_DeleteOnClose); // Clean up on close
        // Get the position and size of the Config window
        QRect configGeometry = this->geometry();
        int helpX = configGeometry.x() + configGeometry.width() + 10; // 10 pixels offset
        int helpY = configGeometry.y();
        // Move the Help dialog to the right side of the Config window
        helpDialog->move(helpX, helpY);
        helpDialog->show();
        isHelpOpen = true;
    } else {
        helpDialog->close();
        isHelpOpen = false;
    }
}
void EditorDialog::onResetToDefaultClicked() {
    bool default_default = gameComboBox->currentText() == "default";
    QString prompt =
        default_default
            ? tr("Do you want to reset your custom default config to the original default config?")
            : tr("Do you want to reset this config to your custom default config?");
    QMessageBox::StandardButton reply = QMessageBox::question(this, tr("Reset to Default"), prompt,
                                                              QMessageBox::Yes | QMessageBox::No);
    if (reply == QMessageBox::Yes) {
        if (default_default) {
            const auto default_file = Config::GetFoolproofInputConfigFile("default");
            std::filesystem::remove(default_file);
        }
        const auto config_file = Config::GetFoolproofInputConfigFile("default");
        QFile file(config_file);
        if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
            QTextStream in(&file);
            editor->setPlainText(in.readAll());
            file.close();
        } else {
            QMessageBox::warning(this, tr("Error"), tr("Could not open the file for reading"));
        }
        // saveFile(gameComboBox->currentText());
    }
}
bool EditorDialog::hasUnsavedChanges() {
    // Compare the current content with the original content to check if there are unsaved changes
    return editor->toPlainText() != originalConfig;
}
void EditorDialog::loadInstalledGames() {
    previous_game = "default";
    QStringList filePaths;
    for (const auto& installLoc : Config::getGameInstallDirs()) {
        QString installDir;
        Common::FS::PathToQString(installDir, installLoc);
        QDir parentFolder(installDir);
        QFileInfoList fileList = parentFolder.entryInfoList(QDir::Dirs | QDir::NoDotAndDotDot);
        for (const auto& fileInfo : fileList) {
            if (fileInfo.isDir() && (!fileInfo.filePath().endsWith("-UPDATE") ||
                                     !fileInfo.filePath().endsWith("-patch"))) {
                gameComboBox->addItem(fileInfo.fileName()); // Add game name to combo box
            }
        }
    }
}
void EditorDialog::onGameSelectionChanged(const QString& game) {
    saveFile(previous_game);
    loadFile(gameComboBox->currentText()); // Reload file based on the selected game
    previous_game = gameComboBox->currentText();
}

#include "Stochastic.hpp"
namespace MayaFlux::Kinesis::Stochastic {
Stochastic::Stochastic(Algorithm algo)
    : m_engine(std::random_device {}())
    , m_algorithm(algo)
    , m_xorshift_state(std::random_device {}() | (static_cast<uint64_t>(std::random_device {}()) << 32))
{
    if (m_xorshift_state == 0)
        m_xorshift_state = 0xDEADBEEFCAFEBABE;
}
void Stochastic::seed(uint64_t seed)
{
    m_engine.seed(static_cast<std::mt19937::result_type>(seed));
    m_xorshift_state = seed;
    if (m_xorshift_state == 0)
        m_xorshift_state = 0xDEADBEEFCAFEBABE;
    reset_state();
}
void Stochastic::set_algorithm(Algorithm algo)
{
    if (m_algorithm != algo) {
        m_algorithm = algo;
        reset_state();
        m_dist_dirty = true;
    }
}
void Stochastic::configure(const std::string& key, std::any value)
{
    m_config[key] = std::move(value);
    m_dist_dirty = true;
}
std::optional<std::any> Stochastic::get_config(const std::string& key) const
{
    auto it = m_config.find(key);
    if (it != m_config.end()) {
        return it->second;
    }
    return std::nullopt;
}
double Stochastic::operator()(double min, double max)
{
    validate_range(min, max);
    switch (m_algorithm) {
    case Algorithm::UNIFORM:
    case Algorithm::NORMAL:
    case Algorithm::EXPONENTIAL:
    case Algorithm::POISSON:
        return generate_memoryless(min, max);
    case Algorithm::PERLIN:
        return generate_perlin_impl(m_state.phase, 0.0, 0.0);
    case Algorithm::GENDY:
        return generate_gendy_impl(min, max);
    case Algorithm::BROWNIAN:
        return generate_brownian_impl(min, max);
    case Algorithm::PINK:
    case Algorithm::BLUE:
        return generate_colored_noise_impl(min, max);
    default:
        return generate_memoryless(min, max);
    }
}
double Stochastic::at(double x, double y, double z)
{
    if (m_algorithm != Algorithm::PERLIN) {
        throw std::runtime_error("Multi-dimensional access only supported for PERLIN algorithm");
    }
    return generate_perlin_impl(x, y, z);
}
std::vector<double> Stochastic::batch(double min, double max, size_t count)
{
    validate_range(min, max);
    std::vector<double> result;
    result.reserve(count);
    for (size_t i = 0; i < count; ++i) {
        result.push_back((*this)(min, max));
    }
    return result;
}
void Stochastic::reset_state()
{
    m_state.reset();
}
double Stochastic::generate_memoryless(double min, double max)
{
    if (min != m_cached_min || max != m_cached_max) {
        m_cached_min = min;
        m_cached_max = max;
        m_dist_dirty = true;
    }
    double raw_value = 0.0;
    switch (m_algorithm) {
    [[likely]] case Algorithm::UNIFORM:
        return min + fast_uniform() * (max - min);
    case Algorithm::NORMAL: {
        rebuild_distributions_if_needed(min, max);
        raw_value = m_normal_dist(m_engine);
        return std::clamp(raw_value, min, max);
    }
    case Algorithm::EXPONENTIAL: {
        rebuild_distributions_if_needed(min, max);
        raw_value = m_exponential_dist(m_engine);
        raw_value /= max;
        return min + raw_value * (max - min);
    }
    case Algorithm::POISSON: {
        std::poisson_distribution<int> dist(static_cast<int>(max - min));
        return static_cast<double>(dist(m_engine));
    }
    default:
        return min + fast_uniform() * (max - min);
    }
}
double Stochastic::generate_stateful(double min, double max)
{
    m_state.step_count++;
    return m_state.current_value;
}
double Stochastic::generate_perlin_impl(double x, double y, double z)
{
    return 0.0;
}
double Stochastic::generate_gendy_impl(double min, double max)
{
    return min + fast_uniform() * (max - min);
}
double Stochastic::generate_brownian_impl(double min, double max)
{
    double step_size = 0.01;
    if (auto cfg = get_config("step_size"); cfg.has_value()) {
        step_size = std::any_cast<double>(*cfg);
    }
    double step = (fast_uniform() - 0.5) * 2.0 * step_size;
    m_state.current_value += step;
    m_state.current_value = std::clamp(m_state.current_value, min, max);
    m_state.step_count++;
    return m_state.current_value;
}
double Stochastic::generate_colored_noise_impl(double min, double max)
{
    return min + fast_uniform() * (max - min);
}
void Stochastic::validate_range(double min, double max) const
{
    if (min > max) {
        throw std::invalid_argument("Stochastic: min must be <= max");
    }
}
void Stochastic::rebuild_distributions_if_needed(double min, double max)
{
    if (!m_dist_dirty)
        return;
    const double range = max - min;
    if (m_algorithm == Algorithm::NORMAL) {
        double spread = 4.0;
        if (auto cfg = get_config("spread"); cfg.has_value()) {
            spread = std::any_cast<double>(*cfg);
        }
        m_normal_dist = std::normal_distribution<double>(0.0, range / spread);
    } else if (m_algorithm == Algorithm::EXPONENTIAL) {
        m_exponential_dist = std::exponential_distribution<double>(1.0);
    }
    m_dist_dirty = false;
}
}

#include "bishengir/Dialect/HIVM/Transforms/InjectSync/MoveSyncState.h"
#include "bishengir/Dialect/HIVM/Transforms/InjectSync/SyncCommon.h"
#include "llvm/ADT/STLExtras.h"
#define DEBUG_TYPE "hivm-inject-sync"
using namespace mlir;
using namespace mlir::hivm;
void MoveSyncState::StateOptimize() {
  MoveOutBranchSync();
  MoveForSync();
}
void MoveSyncState::MoveOutBranchSync() {
  for (auto &e : syncIR) {
    if (auto *branchElement = dyn_cast<BranchInstanceElement>(e.get())) {
      if (branchElement->getBranchKind() == KindOfBranch::IF_BEGIN) {
        std::pair<unsigned, unsigned> bound = {branchElement->beginId,
                                               branchElement->endId};
        for (unsigned i = branchElement->beginId + 1;
             i < branchElement->branchId; i++) {
          PlanMoveOutBranchSync(
              syncIR[i].get(),
              {branchElement->beginId, branchElement->branchId}, bound);
        }
        if (branchElement->endId == branchElement->branchId) {
          continue;
        }
        for (unsigned i = branchElement->branchId + 1; i < branchElement->endId;
             i++) {
          PlanMoveOutBranchSync(syncIR[i].get(),
                                {branchElement->branchId, branchElement->endId},
                                bound);
        }
      }
    }
  }
}
void MoveSyncState::PlanMoveOutBranchSync(
    InstanceElement *e, std::pair<unsigned int, unsigned int> pair,
    std::pair<unsigned int, unsigned int> bound) {
  checkCondition(
      pair.first < e->GetIndex() && e->GetIndex() < pair.second,
      "PlanMoveOutBranchSync expected element to be within pair bounds");
  SyncOps newPipeBefore;
  for (auto &s : e->pipeBefore) {
    PlanMoveOutIfWaitSync(newPipeBefore, s, pair, bound);
  }
  SyncOps newPipeAfter;
  for (auto &s : llvm::reverse(e->pipeAfter)) {
    PlanMoveOutIfSetSync(newPipeAfter, s, pair, bound);
  }
  e->pipeAfter = newPipeAfter;
  e->pipeBefore = newPipeBefore;
}
void MoveSyncState::PlanMoveOutIfWaitSync(
    SyncOps &newPipeBefore, SyncOperation *s,
    std::pair<unsigned int, unsigned int> pair,
    std::pair<unsigned int, unsigned int> bound) {
  if (s->GetType() != SyncOperation::TYPE::WAIT_EVENT &&
      s->GetType() != SyncOperation::TYPE::SYNC_BLOCK_WAIT) {
    newPipeBefore.push_back(s);
    return;
  }
  auto &syncPair = syncOperations[s->GetSyncIndex()];
  checkCondition(!syncPair.empty(), "expected syncPair not to be empty");
  auto *setSync = syncPair[0].get();
  if ((setSync->GetSyncIRIndex() >= pair.second) ||
      (setSync->GetSyncIRIndex() <= pair.first)) {
    // Process the following scenarios:
    // setFlag
    // if():
    //    waitFlag
    //    compound
    // change to :
    // setFlag
    // waitFlag
    // if():
    //    compound
    checkSyncIRIndex(syncIR, bound.first);
    syncIR[bound.first]->pipeBefore.push_back(s);
    s->SetSyncIRIndex(bound.first);
  } else {
    newPipeBefore.push_back(s);
  }
}
void MoveSyncState::PlanMoveOutIfSetSync(
    SyncOps &newPipeAfter, SyncOperation *s,
    std::pair<unsigned int, unsigned int> pair,
    std::pair<unsigned int, unsigned int> bound) {
  if (s->GetType() != SyncOperation::TYPE::SET_EVENT &&
      s->GetType() != SyncOperation::TYPE::SYNC_BLOCK_SET) {
    newPipeAfter.push_back(s);
    return;
  }
  auto &syncPair = syncOperations[s->GetSyncIndex()];
  checkCondition(syncPair.size() > 1, "expected syncPair size > 1");
  auto *waitSync = syncPair[1].get();
  if ((waitSync->GetSyncIRIndex() >= pair.second) ||
      (waitSync->GetSyncIRIndex() <= pair.first)) {
    // Process the following scenarios:
    // if():
    //    compound
    //    setFlag
    // waitFlag
    // change to :
    // if():
    //    compound
    // setFlag
    // waitFlag
    checkSyncIRIndex(syncIR, bound.second);
    syncIR[bound.second]->pipeAfter.push_front(s);
    s->SetSyncIRIndex(bound.second);
  } else {
    newPipeAfter.push_back(s);
  }
}
void MoveSyncState::MoveForSync() {
  for (auto &e : syncIR) {
    if (auto *forCompound = dyn_cast<LoopInstanceElement>(e.get())) {
      if (forCompound->getLoopKind() == KindOfLoop::LOOP_END) {
        if (forCompound->ignore_block_sync_move_out) {
          continue;
        }
        for (unsigned i = forCompound->beginId + 1; i < forCompound->endId; i++)
          MoveOutSync(syncIR[i].get(),
                      {forCompound->beginId, forCompound->endId});
      }
    }
  }
}
void MoveSyncState::MoveOutSync(InstanceElement *e,
                                std::pair<unsigned int, unsigned int> pair) {
  checkCondition(pair.first < e->GetIndex() && e->GetIndex() < pair.second,
                 "MoveOutSync expected element to be within pair bounds");
  SyncOps newPipeBefore;
  for (auto &s : e->pipeBefore) {
    PlanMoveOutWaitSync(newPipeBefore, s, pair);
  }
  SyncOps newPipeAfter;
  for (auto &s : llvm::reverse(e->pipeAfter)) {
    PlanMoveOutSetSync(newPipeAfter, s, pair);
  }
  e->pipeAfter = newPipeAfter;
  e->pipeBefore = newPipeBefore;
}
void MoveSyncState::PlanMoveOutWaitSync(
    SyncOps &newPipeBefore, SyncOperation *s,
    std::pair<unsigned int, unsigned int> pair) {
  if (s->GetType() != SyncOperation::TYPE::WAIT_EVENT &&
      s->GetType() != SyncOperation::TYPE::SYNC_BLOCK_WAIT) {
    newPipeBefore.push_back(s);
    return;
  }
  auto &syncPair = syncOperations[s->GetSyncIndex()];
  checkCondition(!syncPair.empty(), "expected syncPair not to be empty");
  auto *setSync = syncPair[0].get();
  if ((setSync->GetSyncIRIndex() > pair.second) ||
      (setSync->GetSyncIRIndex() < pair.first)) {
    // Process the following scenarios:
    // setFlag
    // for():
    //    waitFlag
    //    compound
    // change to :
    // setFlag
    // waitFlag
    // for():
    //    compound
    checkSyncIRIndex(syncIR, pair.first);
    syncIR[pair.first]->pipeBefore.push_back(s);
    s->SetSyncIRIndex(pair.first);
    return;
  }
  newPipeBefore.push_back(s);
}
void MoveSyncState::PlanMoveOutSetSync(
    SyncOps &newPipeAfter, SyncOperation *s,
    const std::pair<unsigned int, unsigned int> pair) {
  if (s->GetType() != SyncOperation::TYPE::SET_EVENT &&
      s->GetType() != SyncOperation::TYPE::SYNC_BLOCK_SET) {
    newPipeAfter.push_back(s);
    return;
  }
  auto &syncPair = syncOperations[s->GetSyncIndex()];
  checkCondition(syncPair.size() > 1, "expected syncPair size > 1");
  auto *waitSync = syncPair[1].get();
  if ((waitSync->GetSyncIRIndex() > pair.second) ||
      (waitSync->GetSyncIRIndex() < pair.first)) {
    // Process the following scenarios:
    // for():
    //    compound
    //    setFlag
    // waitFlag
    // change to :
    // for():
    //    compound
    // setFlag
    // waitFlag
    checkSyncIRIndex(syncIR, pair.second);
    syncIR[pair.second]->pipeAfter.push_front(s);
    s->SetSyncIRIndex(pair.second);
    return;
  }
  newPipeAfter.push_back(s);
}

#include <sycl/sycl.hpp>
#include "../utils.h"
#include "../dispatch_utils.h"
namespace vllm {
namespace GroupedTopKImpl {
enum class ScoringFunc {
  DEFAULT = 0,
  SOFTMAX = 1,
  SIGMOID = 2,
};
template <typename T, int MAX_EXPERT_GROUPS>
struct Fused_Grouped_Topk {
  static constexpr int sub_group_size = 32;
  static constexpr int max_group_size = 1024;
  static constexpr int malloc_per_item = MAX_EXPERT_GROUPS;
  static constexpr float kNegInfinity = INFINITY * -1;
  Fused_Grouped_Topk(
      float* topk_weights,
      int* topk_ids,
      const T* gating_output,
      const T* e_score_correction_bias,
      const double routed_scaling_factor,
      const ScoringFunc scoring_mode,
      const bool renormalize,
      const int tokens,
      const int experts,
      const int top_k,
      const int num_expert_group,
      const int topk_group)
      : topk_weights(topk_weights),
        topk_ids(topk_ids),
        gating_output(gating_output),
        e_score_correction_bias(e_score_correction_bias),
        routed_scaling_factor(routed_scaling_factor),
        scoring_mode(scoring_mode),
        renormalize(renormalize),
        tokens(tokens),
        experts(experts),
        top_k(top_k),
        num_expert_group(num_expert_group),
        topk_group(topk_group) {}
  static inline sycl::nd_range<3>
  get_nd_range(const int tokens, const int experts) {
    int calc_per_item = (experts + sub_group_size - 1) / sub_group_size;
    int group_size = (experts + calc_per_item - 1) / calc_per_item;
    group_size = group_size < sub_group_size ? sub_group_size : group_size;
    group_size = group_size < max_group_size ? group_size : max_group_size;
    int sub_groups_per_group =
        (group_size + sub_group_size - 1) / sub_group_size;
    group_size = sub_groups_per_group * sub_group_size;
    int global_size =
        (tokens + sub_groups_per_group - 1) / sub_groups_per_group;
    sycl::range<3> local(1, 1, group_size);
    sycl::range<3> global(1, 1, global_size);
    return sycl::nd_range<3>(global * local, local);
  }
  static inline float Sigmoid(float x) {
    return 1.0f / (1.0f + sycl::native::exp(-x));
  }
  [[sycl::reqd_sub_group_size(sub_group_size)]] void
  operator()(sycl::nd_item<3> item) const {
    int group_id = item.get_group_linear_id();
    int local_range = item.get_local_range(2);
    int sub_groups_per_group = local_range / sub_group_size;
    int calc_per_item = (experts + sub_group_size - 1) / sub_group_size;
    int experts_per_group = experts / num_expert_group;
    sycl::sub_group sg = item.get_sub_group();
    int sg_id = sg.get_group_id();
    int sg_local_id = sg.get_local_id();
    int tid = group_id * sub_groups_per_group + sg_id;
    if (tid >= tokens) {
      return;  // Out of bounds
    }
    T load_elems[malloc_per_item];
    int local_idx[malloc_per_item];
    T bias[malloc_per_item];
    int start_offset = sg_local_id * calc_per_item;
    int local_num = calc_per_item;
    if (start_offset + local_num >= experts) {
      local_num = experts - start_offset;
      if (local_num < 0) {
        local_num = 0;  // No elements to process
      }
    }
    for (int e = 0; e < calc_per_item; ++e) {
      load_elems[e] = kNegInfinity;
      local_idx[e] = -1;
      bias[e] = 0.0f;  // Initialize bias to zero
    }
    for (int e = 0; e < local_num; ++e) {
      load_elems[e] = gating_output[tid * experts + start_offset + e];
    }
    T local_elems[malloc_per_item];
    for (int e = 0; e < local_num; ++e) {
      local_elems[e] = load_elems[e];
      local_idx[e] = start_offset + e;
    }
    if (scoring_mode == ScoringFunc::SOFTMAX) {
      float softmax_max = kNegInfinity;
      for (int e = 0; e < local_num; ++e) {
        float s = load_elems[e];
        softmax_max = (softmax_max > s) ? softmax_max : s;
      }
      for (int offset = sub_group_size / 2; offset > 0; offset /= 2) {
        float other_val = sycl::permute_group_by_xor(sg, softmax_max, offset);
        softmax_max = (softmax_max > other_val) ? softmax_max : other_val;
      }
      float softmax_sum = 0.0f;
      for (int e = 0; e < local_num; ++e) {
        float s = local_elems[e];
        softmax_sum += sycl::native::exp(s - softmax_max);
      }
      for (int offset = sub_group_size / 2; offset > 0; offset /= 2) {
        float other_val = sycl::permute_group_by_xor(sg, softmax_sum, offset);
        softmax_sum += other_val;
      }
      for (int e = 0; e < local_num; ++e) {
        float s = local_elems[e];
        local_elems[e] = sycl::native::exp(s - softmax_max) / softmax_sum;
      }
    } else if (scoring_mode == ScoringFunc::SIGMOID) {
      for (int e = 0; e < local_num; ++e) {
        float s = load_elems[e];
        load_elems[e] = Sigmoid(s);
      }
      for (int e = 0; e < local_num; ++e) {
        local_elems[e] = load_elems[e];
      }
    }
    bool has_bias = e_score_correction_bias != nullptr;
    if (has_bias) {
      for (int e = 0; e < local_num; ++e) {
        bias[e] = e_score_correction_bias[start_offset + e];
      }
    }
    // perform topk_group groups
    // 1 calculate each group scores
    float group_scores[malloc_per_item * 2];
    for (int i = 0; i < num_expert_group * 2; ++i) {
      group_scores[i] = kNegInfinity;
    }
    for (int i = 0; i < local_num; ++i) {
      float b = bias[i];
      float score = local_elems[i] + b;
      int i_group = (calc_per_item * sg_local_id + i) / experts_per_group;
      float group_max = group_scores[i_group];
      float group_next_max = group_scores[num_expert_group + i_group];
      if (score > group_max) {
        group_next_max = group_max;
        group_max = score;
      } else if (score > group_next_max) {
        group_next_max = score;
      }
      group_scores[i_group] = group_max;
      group_scores[num_expert_group + i_group] = group_next_max;
    }
    for (int i = 0; i < num_expert_group; ++i) {
      float group_max = group_scores[i];
      float group_next_max = group_scores[num_expert_group + i];
      float max1 = sycl::reduce_over_group(
          sg, sycl::max(group_max, group_next_max), sycl::maximum<>());
      float local_second =
          (group_max < max1 && group_max > -INFINITY) ? group_max : -INFINITY;
      local_second = (group_next_max < max1 && group_next_max > local_second)
                         ? group_next_max
                         : local_second;
      float max2 = sycl::reduce_over_group(sg, local_second, sycl::maximum<>());
      group_scores[i] = max1 + (has_bias ? max2 : 0.0f);
    }
    // 2 find topk_group groups as kNegInfinity
    int group_topk_idx[malloc_per_item];
    for (int k = 0; k < topk_group; ++k) {
      float k_max = group_scores[0];
      int k_max_idx = 0;
      for (int e = 1; e < num_expert_group; ++e) {
        float score = group_scores[e];
        if (score > k_max) {
          k_max = score;
          k_max_idx = e;
        }
      }
      group_scores[k_max_idx] = kNegInfinity;
      group_topk_idx[k] = k_max_idx;
    }
    // 3 mask no-topk_group groups
    for (int i = 0; i < calc_per_item; ++i) {
      bool is_masked = true;
      for (int k = 0; k < topk_group; ++k) {
        if ((local_idx[i] / experts_per_group) == group_topk_idx[k]) {
          is_masked = false;
          break;
        }
      }
      if (is_masked) {
        local_elems[i] = kNegInfinity;
      }
    }
    // Perform top-k selection
    T topk_weights_local[malloc_per_item];
    int topk_ids_local[malloc_per_item];
    for (int k = 0; k < top_k; ++k) {
      float k_max = kNegInfinity;
      int k_max_idx = -1;
      int remove_ix = -1;
      for (int e = 0; e < calc_per_item; ++e) {
        float le = local_elems[e];
        float b = bias[e];
        float my_val = le + b;
        int my_idx = local_idx[e];
        for (int offset = sub_group_size / 2; offset > 0; offset /= 2) {
          float other_val = sycl::permute_group_by_xor(sg, my_val, offset);
          int other_idx = sycl::permute_group_by_xor(sg, my_idx, offset);
          if (other_val > my_val ||
              (other_val == my_val && other_idx < my_idx)) {
            my_val = other_val;
            my_idx = other_idx;
          }
        }
        if (my_val > k_max || (my_val == k_max && my_idx < k_max_idx)) {
          k_max = my_val;
          k_max_idx = my_idx;
          if (k_max_idx == local_idx[e]) {
            remove_ix = e;  // Mark this index for removal
          } else
            remove_ix = -1;
        }
      }
      int select_item = k_max_idx / calc_per_item;
      int select_elem = k_max_idx % calc_per_item;
      k_max = local_elems[select_elem];
      k_max = sycl::group_broadcast(sg, k_max, select_item);
      if (remove_ix != -1) {
        local_elems[remove_ix] =
            kNegInfinity;  // Reset the score to avoid re-selection
        local_idx[remove_ix] = -1;
        remove_ix = -1;
      }
      topk_weights_local[k] = k_max;
      topk_ids_local[k] = k_max_idx < 0 ? k : k_max_idx;
    }
    if (renormalize) {
      // Renormalize the top-k weights
      float sum = 0;
      for (int i = 0; i < top_k; ++i) {
        sum += topk_weights_local[i];
      }
      if (sum > 0) {
        for (int i = 0; i < top_k; ++i) {
          topk_weights_local[i] /= sum;
        }
      }
    }
    if (sg_local_id == 0) {
      int offset = tid * top_k;
      for (int i = 0; i < top_k; ++i) {
        topk_weights[offset + i] =
            topk_weights_local[i] * routed_scaling_factor;
        if (!(topk_ids_local[i] >= 0 && topk_ids_local[i] < experts)) {
          // Ensure valid index
          topk_ids[offset + i] = 0;
          continue;
        }
        topk_ids[offset + i] = topk_ids_local[i];
      }
    }
  }
  float* topk_weights;
  int* topk_ids;
  const T* gating_output;
  const T* e_score_correction_bias;
  const double routed_scaling_factor;
  const ScoringFunc scoring_mode;
  const bool renormalize;
  const int tokens;
  const int experts;
  const int top_k;
  const int num_expert_group;
  const int topk_group;
};
template <typename T, int MAX_EXPERT_GROUPS>
void launch_fused_grouped_topk(
    sycl::queue& queue,
    float* topk_weights,
    int* topk_ids,
    const T* gating_output,
    const T* e_score_correction_bias,
    const double routed_scaling_factor,
    const ScoringFunc scoring_mode,
    const bool renormalize,
    const int tokens,
    const int experts,
    const int top_k,
    const int num_expert_group,
    const int topk_group) {
  using Kernel = Fused_Grouped_Topk<T, MAX_EXPERT_GROUPS>;
  auto range = Kernel::get_nd_range(tokens, experts);
  queue.submit([&](sycl::handler& cgh) {
    Kernel task(
        topk_weights,
        topk_ids,
        gating_output,
        e_score_correction_bias,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        tokens,
        experts,
        top_k,
        num_expert_group,
        topk_group);
    cgh.parallel_for(range, task);
  });
}
template <typename T>
void fused_grouped_topk(
    float* topk_weights,
    int* topk_ids,
    const T* gating_output,
    const T* e_score_correction_bias,
    const double routed_scaling_factor,
    const ScoringFunc scoring_mode,
    const bool renormalize,
    const int tokens,
    const int experts,
    const int top_k,
    const int num_expert_group,
    const int topk_group) {
  auto& queue = vllm::xpu::vllmGetQueue();
  TORCH_CHECK(
      topk_group <= num_expert_group,
      "topk_group must be less than or equal to num_expert_group");
  TORCH_CHECK(
      experts % num_expert_group == 0,
      "The number of experts (experts=",
      experts,
      ") must be divisible by num_expert_group (",
      num_expert_group,
      ").");
  int max_expert_group = ((num_expert_group + 7) / 8) * 8;
#define CASE_TOPK(K)                 \
  case K:                            \
    launch_fused_grouped_topk<T, K>( \
        queue,                       \
        topk_weights,                \
        topk_ids,                    \
        gating_output,               \
        e_score_correction_bias,     \
        routed_scaling_factor,       \
        scoring_mode,                \
        renormalize,                 \
        tokens,                      \
        experts,                     \
        top_k,                       \
        num_expert_group,            \
        topk_group);                 \
    break;
  switch (max_expert_group) {
    CASE_TOPK(8)
    CASE_TOPK(16)
    default:
      TORCH_CHECK(
          false, "error: not support num_expert_group=%d,\n", num_expert_group);
  }
#undef CASE_TOPK
}
};  // namespace GroupedTopKImpl
}  // namespace vllm
/**
 * @brief Perform grouped topk after sigmoid/addbias on gating_output.
 * @param gating_output The gating output tensor of shape [n_tokens, n_experts].
 * @param n_topk The number of top experts to select.
 * @param n_topk_group The number of top experts to select in the group.
 * @return A tuple of tensors (topk_weights, topk_indices).
 */
std::tuple<torch::Tensor, torch::Tensor> fused_grouped_topk(
    const torch::Tensor& hidden_states,
    const torch::Tensor& gating_output,
    const int64_t n_topk,
    const bool renormalize,
    const int64_t n_expert_group,
    const int64_t n_topk_group,
    const c10::string_view scoring_func,
    const double routed_scaling_factor,
    const c10::optional<torch::Tensor>& bias) {
  auto shape = gating_output.sizes().vec();
  TORCH_CHECK(
      hidden_states.sizes()[0] == gating_output.sizes()[0],
      "Number of tokens mismatch")
  TORCH_CHECK(
      shape.size() == 2,
      "gating_output must be 2D tensor, but got ",
      shape.size(),
      "D");
  if (bias.has_value()) {
    auto shape_bias = bias->sizes().vec();
    TORCH_CHECK(
        shape_bias[0] == shape[1],
        "gating_output and bias must has same innermost dimension, but got ",
        shape,
        " and ",
        shape_bias);
  }
  int n_tokens = shape[0];
  int n_experts = shape[1];
  vllm::GroupedTopKImpl::ScoringFunc scoring_mode;
  if (scoring_func == "sigmoid") {
    scoring_mode = vllm::GroupedTopKImpl::ScoringFunc::SIGMOID;
  } else if (scoring_func == "softmax") {
    scoring_mode = vllm::GroupedTopKImpl::ScoringFunc::SOFTMAX;
  } else {
    scoring_mode = vllm::GroupedTopKImpl::ScoringFunc::DEFAULT;
  }
  auto topk_weights =
      torch::empty({n_tokens, n_topk}, at::dtype(at::kFloat).device(at::kXPU));
  auto topk_indices =
      torch::empty({n_tokens, n_topk}, at::dtype(at::kInt).device(at::kXPU));
  if (gating_output.scalar_type() == at::kBFloat16) {
    using scalar_t = sycl::ext::oneapi::bfloat16;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr())
                         : nullptr,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  } else if (gating_output.scalar_type() == at::kHalf) {
    using scalar_t = sycl::half;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr())
                         : nullptr,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  } else {
    using scalar_t = float;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr())
                         : nullptr,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  }
  return std::make_tuple(topk_weights, topk_indices);
}

