void gdraw_D3D_PreReset(void)
{
   if (!gdraw) return;
   GDrawStats stats={0};
   flush_rendertargets(&stats);
   // we may end up resizing the frame buffer
   gdraw->frametex_width = 0;
   gdraw->frametex_height = 0;
