#define NOINLINE __attribute__((noinline))
#define LOG_TAG "NativeLeakTest"
#define NR_TEST_THREAD 10
#define NR_TEST_CASE 10
#define KB(x) ((x) * 1024L)
#define MB(x) (KB(x) * 1024L)
#define LOGI(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)
static NOINLINE void TestMallocLeak() {
  for (int i = 0; i < NR_TEST_CASE; i++) {
    size_t size = MB(std::rand() % 10);
    auto ptr = malloc(size);
    if (i % 2) {
      LOGI("%s %p size %u", __FUNCTION__, ptr, size);
    } else {
      free(ptr);
    }
  }
}
static NOINLINE void TestReallocLeak() {
  for (int i = 0; i < NR_TEST_CASE; i++) {
    size_t size = KB(std::rand() % 1000);
    auto ptr = realloc(nullptr, size);
    if (i % 2) {
      LOGI("%s %p size %u", __FUNCTION__, ptr, size);
    } else {
      free(ptr);
    }
  }
}
static NOINLINE void TestCallocLeak() {
  for (int i = 0; i < NR_TEST_CASE; i++) {
    size_t size = std::rand() % 1000;
    auto ptr = calloc(size, 8);
    if (i % 2) {
      LOGI("%s %p size %u", __FUNCTION__, ptr, size);
    } else {
      free(ptr);
    }
  }
}
static NOINLINE void TestMemalignLeak() {
  for (int i = 0; i < NR_TEST_CASE; i++) {
    size_t size = KB(std::rand() % 1000);
    auto ptr = memalign(16, size);
    if (i % 2) {
      LOGI("%s %p size %u", __FUNCTION__, ptr, size);
    } else {
      free(ptr);
    }
  }
}
static NOINLINE void TestNewLeak() {
  for (int i = 0; i < NR_TEST_CASE; i++) {
    auto str_ptr = new std::string("test_leak_string");
    if (i % 2) {
      LOGI("%s %p size %u", __FUNCTION__, str_ptr, str_ptr->size());
    } else {
      delete str_ptr;
    }
  }
}
static NOINLINE void TestNewArrayLeak() {
  for (int i = 0; i < NR_TEST_CASE; i++) {
    size_t size = std::rand() % 1000;
    auto array_ptr = new std::string[size];
    if (i % 2) {
      LOGI("%s %p size %u", __FUNCTION__, array_ptr, size * sizeof(std::string));
    } else {
      delete[] array_ptr;
    }
  }
}
static NOINLINE void TestContainerLeak() {
  std::vector<std::string *> str_vector(NR_TEST_CASE);
  for (int i = 0; i < NR_TEST_CASE; i++) {
    str_vector[i] = new std::string("test_leak_container");
  }
}
static NOINLINE jlong TestJavaRefNative() {
  auto native_ptr = (void **) malloc(sizeof(void *) * NR_TEST_CASE);
  LOGI("%s Holder addr %p", __FUNCTION__, native_ptr);
  for (int i = 0; i < NR_TEST_CASE; i++) {
    size_t size = std::rand() % 1000;
    native_ptr[i] = malloc(size);
    LOGI("%s %p size %u", __FUNCTION__, native_ptr[i], size);
  }
  return reinterpret_cast<jlong>(native_ptr);
}
extern "C" JNIEXPORT jlong
Java_com_kwai_koom_demo_nativeleak_NativeLeakTest_triggerLeak(
    JNIEnv *env,
    jclass,
    jobject unuse/* this */) {
  auto leak_test = []() {
    TestMallocLeak();
    TestCallocLeak();
    TestReallocLeak();
    TestMemalignLeak();
    TestNewLeak();
    TestNewArrayLeak();
    TestContainerLeak();
  };
  for (int i = 0; i < NR_TEST_THREAD; i++) {
    std::thread test_thread(leak_test);
    test_thread.detach();
  }
  return TestJavaRefNative();
}

#include "Core/Utils/FileLoader.hpp"
#include <algorithm>
#include "Core/Utils/Utils.hpp"
#include "CoreConstants.hpp"
static int l_custom_loadfile(lua_State *L)
{
    const char *filename = luaL_checkstring(L, 1);
    {
    std::string strippedFilename = filename;
    std::string scriptContent = Core::Utils::LoadFile(filename);
    if (scriptContent.empty()) {
        lua_pushfstring(L, "cannot open %s", filename);
        goto __error;
    }
    Core::Utils::Replace(strippedFilename, PLUGIN_FOLDER "/", ""); // To remove the prefix if in an known directory
    if (luaL_loadbuffer(L, scriptContent.c_str(), scriptContent.size(), strippedFilename.c_str()) != 0)
        goto __error;
    return 1;
    }
    __error:
    return lua_error(L);
}
static int l_custom_dofile(lua_State *L) 
{
    lua_getglobal(L, "loadfile");
    lua_pushvalue(L, 1);
    if (lua_pcall(L, 1, 1, 0) != 0)
        return lua_error(L);
    if (!lua_isfunction(L, -1))
        return luaL_error(L, "Failed to load");
    lua_Debug ar;
    if (lua_getstack(L, 1, &ar) && lua_getinfo(L, "f", &ar)) {
        lua_getfenv(L, -1);
        lua_remove(L, -2);
    } else {
        lua_pushvalue(L, LUA_GLOBALSINDEX);
    }
    lua_setfenv(L, -2);
    lua_remove(L, 1);
    int baseTop = lua_gettop(L);
    if (lua_pcall(L, 0, LUA_MULTRET, 0) != 0)
        return lua_error(L);

    int newtop = lua_gettop(L);
    return newtop - baseTop + 1;
}
static int l_custom_loader(lua_State *L) 
{
    const char *module_name = luaL_checkstring(L, 1);
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "path");
    const char *path_template = lua_tostring(L, -1);
    lua_pop(L, 2);
    {
    std::string module_path(module_name);
    std::replace(module_path.begin(), module_path.end(), '.', '/');
    std::string paths(path_template);
    size_t pos = 0;
    std::string error_msgs = "\n\tno file with name '"+std::string(module_name)+"' found";
    while (pos < paths.size()) {
        size_t next = paths.find(';', pos);
        std::string path = paths.substr(pos, next - pos);
        size_t qmark = path.find('?');
        if (qmark != std::string::npos)
            path.replace(qmark, 1, module_path);

        std::string scriptContent = Core::Utils::LoadFile(path);
        if (!scriptContent.empty()) {
            if (luaL_loadbuffer(L, scriptContent.c_str(), scriptContent.size(), path.c_str()) == 0)
                return 1;
            else
                goto __error;
        }
        if (next == std::string::npos)
            break;
        pos = next + 1;
    }
    lua_pushstring(L, error_msgs.c_str());
    goto __error;
    }
    __error:
    return lua_error(L);
}
bool Core::RegisterCustomFileLoader(lua_State *L)
{
    lua_pushcfunction(L, l_custom_loadfile);
    lua_setglobal(L, "loadfile");
    lua_pushcfunction(L, l_custom_dofile);
    lua_setglobal(L, "dofile");
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "loaders");
    if (lua_istable(L, -1)) {
        for (int i = lua_objlen(L, -1) + 1; i > 1; --i) {
            lua_rawgeti(L, -1, i - 1);
            lua_rawseti(L, -2, i);
        }
        lua_pushcfunction(L, l_custom_loader);
        lua_rawseti(L, -2, 1);
    }
    else {
        lua_pop(L, 2);
        return false;
    }
    lua_pop(L, 2);
    return true;
}

#include "ParseHelper.h"
namespace glslang {
//
// The inductive loop-body traverser.
//
// Just look at things that might modify the loop index.
//
class TInductiveTraverser : public TIntermTraverser {
public:
    TInductiveTraverser(long long id, TSymbolTable& st)
    : loopId(id), symbolTable(st), bad(false)  { }
    virtual bool visitBinary(TVisit, TIntermBinary* node);
    virtual bool visitUnary(TVisit, TIntermUnary* node);
    virtual bool visitAggregate(TVisit, TIntermAggregate* node);
    long long loopId;           // unique ID of the symbol that's the loop inductive variable
    TSymbolTable& symbolTable;
    bool bad;
    TSourceLoc badLoc;
protected:
    TInductiveTraverser(TInductiveTraverser&);
    TInductiveTraverser& operator=(TInductiveTraverser&);
};
// check binary operations for those modifying the loop index
bool TInductiveTraverser::visitBinary(TVisit /* visit */, TIntermBinary* node)
{
    if (node->modifiesState() && node->getLeft()->getAsSymbolNode() &&
                                 node->getLeft()->getAsSymbolNode()->getId() == loopId) {
        bad = true;
        badLoc = node->getLoc();
    }
    return true;
}
// check unary operations for those modifying the loop index
bool TInductiveTraverser::visitUnary(TVisit /* visit */, TIntermUnary* node)
{
    if (node->modifiesState() && node->getOperand()->getAsSymbolNode() &&
                                 node->getOperand()->getAsSymbolNode()->getId() == loopId) {
        bad = true;
        badLoc = node->getLoc();
    }
    return true;
}
// check function calls for arguments modifying the loop index
bool TInductiveTraverser::visitAggregate(TVisit /* visit */, TIntermAggregate* node)
{
    if (node->getOp() == EOpFunctionCall) {
        // see if an out or inout argument is the loop index
        const TIntermSequence& args = node->getSequence();
        for (int i = 0; i < (int)args.size(); ++i) {
            if (args[i]->getAsSymbolNode() && args[i]->getAsSymbolNode()->getId() == loopId) {
                TSymbol* function = symbolTable.find(node->getName());
                const TType* type = (*function->getAsFunction())[i].type;
                if (type->getQualifier().storage == EvqOut ||
                    type->getQualifier().storage == EvqInOut) {
                    bad = true;
                    badLoc = node->getLoc();
                }
            }
        }
    }
    return true;
}
//
// External function to call for loop check.
//
void TParseContext::inductiveLoopBodyCheck(TIntermNode* body, long long loopId, TSymbolTable& symbolTable)
{
    TInductiveTraverser it(loopId, symbolTable);
    if (body == nullptr)
        return;
    body->traverse(&it);
    if (it.bad)
        error(it.badLoc, "inductive loop index modified", "limitations", "");
}
//
// The "constant-index-expression" tranverser.
//
// Just look at things that can form an index.
//
class TIndexTraverser : public TIntermTraverser {
public:
    TIndexTraverser(const TIdSetType& ids) : inductiveLoopIds(ids), bad(false) { }
    virtual void visitSymbol(TIntermSymbol* symbol);
    virtual bool visitAggregate(TVisit, TIntermAggregate* node);
    const TIdSetType& inductiveLoopIds;
    bool bad;
    TSourceLoc badLoc;
protected:
    TIndexTraverser(TIndexTraverser&);
    TIndexTraverser& operator=(TIndexTraverser&);
};
// make sure symbols are inductive-loop indexes
void TIndexTraverser::visitSymbol(TIntermSymbol* symbol)
{
    if (inductiveLoopIds.find(symbol->getId()) == inductiveLoopIds.end()) {
        bad = true;
        badLoc = symbol->getLoc();
    }
}
// check for function calls, assuming they are bad; spec. doesn't really say
bool TIndexTraverser::visitAggregate(TVisit /* visit */, TIntermAggregate* node)
{
    if (node->getOp() == EOpFunctionCall) {
        bad = true;
        badLoc = node->getLoc();
    }
    return true;
}
//
// External function to call for loop check.
//
void TParseContext::constantIndexExpressionCheck(TIntermNode* index)
{
#ifndef GLSLANG_WEB
    TIndexTraverser it(inductiveLoopIds);
    index->traverse(&it);
    if (it.bad)
        error(it.badLoc, "Non-constant-index-expression", "limitations", "");
#endif
}
