  }
  TTile *tile = reinterpret_cast<TTile *>(handle);
  tile->getRaster()->unlock();
  return 0;
}
int tile_interface_get_raw_stride(toonz_tile_handle_t handle, int *stride) {
  if (!handle || !stride) return -1;  // inval
  TTile *tile = reinterpret_cast<TTile *>(handle);
  //	return stride in byte, not in pixel
  *stride = tile->getRaster()->getWrap() * tile->getRaster()->getPixelSize();
  return 0;
}
int tile_interface_get_element_type(toonz_tile_handle_t handle, int *element) {
  if (!handle || !element) return -1;  // inval
  TTile *tile     = reinterpret_cast<TTile *>(handle);
  TRasterP raster = tile->getRaster();
  if (false)
    ;
  else if (TRaster32P(raster))
    *element = TOONZ_TILE_TYPE_32P;
  else if (TRaster64P(raster))
    *element = TOONZ_TILE_TYPE_64P;
  else if (TRasterGR8P(raster))
    *element = TOONZ_TILE_TYPE_GR8P;
  else if (TRasterGR16P(raster))
    *element = TOONZ_TILE_TYPE_GR16P;
  else if (TRasterGRDP(raster))
    *element = TOONZ_TILE_TYPE_GRDP;
  else if (TRasterYUV422P(raster))
    *element = TOONZ_TILE_TYPE_YUV422P;
  else {
    *element = TOONZ_TILE_TYPE_NONE;
    return -1;
  }
  return 0;
}
int tile_interface_copy_rect(toonz_tile_handle_t handle, int left, int top,
                             int width, int height, void *dst, int dststride) {
  if (!handle || !dst || !dststride) return -1;  // inval
  if (!width || !height) return 0;               // do nothing
  TTile *tile     = reinterpret_cast<TTile *>(handle);
  TRasterP raster = tile->getRaster();
  if (!(0 <= left && left + width <= raster->getLx() && 0 <= top &&
        top + height <= raster->getLy())) {
    return -1;
  }
  for (int y = 0; y < height; y++) {
    memcpy((UCHAR *)dst + y * dststride, raster->getRawData(left, top + y),
           width * raster->getPixelSize());
  }
  return 0;
}
int tile_interface_create_from(toonz_tile_handle_t handle,
                               toonz_tile_handle_t *newhandle) {
  if (!handle || !newhandle) return -1;  // inval
  TTile *tile    = reinterpret_cast<TTile *>(handle);
  TTile *newtile = new TTile(tile->getRaster());
  *newhandle     = reinterpret_cast<toonz_tile_handle_t *>(newtile);
  return 0;
}
int tile_interface_create(toonz_tile_handle_t *newhandle) {
  if (!newhandle) return -1;  // inval
  *newhandle = reinterpret_cast<toonz_tile_handle_t *>(new TTile());
  return 0;
}
int tile_interface_destroy(toonz_tile_handle_t handle) {
  if (!handle) return -1;  // inval
  TTile *tile = reinterpret_cast<TTile *>(handle);
  delete tile;
  return 0;
}
int tile_interface_get_rectangle(toonz_tile_handle_t handle,
                                 toonz_rect_t *rect) {
  if (!handle || !rect) {
    return -1;  // inval
  }
  TTile *tile = reinterpret_cast<TTile *>(handle);
  rect->x0    = tile->m_pos.x;
  rect->y0    = tile->m_pos.y;
  rect->x1    = tile->m_pos.x + tile->getRaster()->getLx();
  rect->y1    = tile->m_pos.y + tile->getRaster()->getLy();
  return 0;
}

#include "client/renderer/block/Variant.hpp"
#include <sstream>
#include <stdexcept>
Variant::Variant(ResourceLocation modelLocation, const ModelRotation& rotation, bool uvLock, int weight) :
    m_modelLocation(std::move(modelLocation)), m_rotation(rotation), m_uvLock(uvLock), m_weight(weight) {}
const ResourceLocation& Variant::getModelLocation() const { return m_modelLocation; }
const ModelRotation& Variant::getRotation() const { return m_rotation; }
bool Variant::isUvLock() const { return m_uvLock; }
int Variant::getWeight() const { return m_weight; }
bool Variant::operator==(const Variant& other) const {
    return m_modelLocation == other.m_modelLocation && m_rotation == other.m_rotation && m_uvLock == other.m_uvLock &&
        m_weight == other.m_weight;
}
bool Variant::operator!=(const Variant& other) const { return !(*this == other); }
std::size_t Variant::hashCode() const {
    // Mirror Java: chain of 31*h + next
    std::size_t h = ResourceLocation::Hash{}(m_modelLocation);
    h = 31 * h + m_rotation.hashCode();
    h = 31 * h + std::hash<bool>{}(m_uvLock);
    h = 31 * h + static_cast<std::size_t>(m_weight);
    return h;
}
std::string Variant::toString() const {
    std::ostringstream oss;
    oss << "Variant{"
        << "modelLocation=" << m_modelLocation.toString() << ", rotation=" << m_rotation.toString()
        << ", uvLock=" << (m_uvLock ? "true" : "false") << ", weight=" << m_weight << '}';
    return oss.str();
}
static ResourceLocation resolveBlockLocation(const std::string& model) {
    ResourceLocation base(model);
    return ResourceLocation(base.getResourceDomain(), "block/" + base.getResourcePath());
}
static ModelRotation parseModelRotation(const nlohmann::json& j) {
    int x = j.value("x", 0);
    int y = j.value("y", 0);
    auto rotation = ModelRotation::getModelRotation(x, y);
    if (!rotation)
        throw nlohmann::json::parse_error::create(
            101, 0, "Invalid BlockModelRotation x: " + std::to_string(x) + ", y: " + std::to_string(y), nullptr);
    return *rotation;
}
static int parseWeight(const nlohmann::json& j) {
    int weight = j.value("weight", 1);
    if (weight < 1)
        throw nlohmann::json::parse_error::create(
            101, 0, "Invalid weight " + std::to_string(weight) + " found, expected integer >= 1", nullptr);
    return weight;
}
Variant Variant::fromJson(const nlohmann::json& j) {
    const std::string model = j.at("model").get<std::string>();
    ModelRotation rotation = parseModelRotation(j);
    bool uvLock = j.value("uvlock", false);
    int weight = parseWeight(j);
    return Variant(resolveBlockLocation(model), rotation, uvLock, weight);
}
void from_json(const nlohmann::json& j, Variant& v) {
    const std::string model = j.at("model").get<std::string>();
    ModelRotation rotation = parseModelRotation(j);
    bool uvLock = j.value("uvlock", false);
    int weight = parseWeight(j);
    v = Variant(resolveBlockLocation(model), rotation, uvLock, weight);
}
void to_json(nlohmann::json& j, const Variant& v) {
    j = nlohmann::json{{"model", v.getModelLocation().toString()},
                       {"x", v.getRotation().getX()},
                       {"y", v.getRotation().getY()},
                       {"uvlock", v.isUvLock()},
                       {"weight", v.getWeight()}};
}

