            toml::get<std::chrono::system_clock::time_point>(v1));
    std::tm t;
    t.tm_year = 2018 - 1900;
    t.tm_mon  = 4    - 1;
    t.tm_mday = 1;
    t.tm_hour = 12;
    t.tm_min  = 30;
    t.tm_sec  = 45;
    t.tm_isdst = -1;
    const auto c = std::mktime(&t);
    CHECK_EQ(c, date);
}
TEST_CASE("testing toml::get<time_point>(offset_datetime)")
{
    using value_type = toml::value;
    {
        value_type v1(toml::offset_datetime(
                    toml::local_date{2018, toml::month_t::Apr, 1},
                    toml::local_time{12, 30, 0},
                    toml::time_offset{9, 0}));
        //    2018-04-01T12:30:00+09:00
        // == 2018-04-01T03:30:00Z
        const auto date = toml::get<std::chrono::system_clock::time_point>(v1);
        const auto timet = std::chrono::system_clock::to_time_t(date);
        // get time_t as gmtime (2018-04-01T03:30:00Z)
        const auto tm = toml::detail::gmtime_s(std::addressof(timet));
        CHECK_EQ(tm.tm_year + 1900, 2018);
        CHECK_EQ(tm.tm_mon  + 1,       4);
        CHECK_EQ(tm.tm_mday,           1);
        CHECK_EQ(tm.tm_hour,           3);
        CHECK_EQ(tm.tm_min,           30);
        CHECK_EQ(tm.tm_sec,            0);
    }
    {
        value_type v1(toml::offset_datetime(
                    toml::local_date{2018, toml::month_t::Apr, 1},
                    toml::local_time{12, 30, 0},
                    toml::time_offset{-8, 0}));
        //    2018-04-01T12:30:00-08:00
        //, 2018-04-01T20:30:00Z
        const auto date = toml::get<std::chrono::system_clock::time_point>(v1);
        const auto timet = std::chrono::system_clock::to_time_t(date);
        // get time_t as gmtime (2018-04-01T03:30:00Z)
        const auto tm = toml::detail::gmtime_s(std::addressof(timet));
        CHECK_EQ(tm.tm_year + 1900, 2018);
        CHECK_EQ(tm.tm_mon  + 1,       4);
        CHECK_EQ(tm.tm_mday,           1);
        CHECK_EQ(tm.tm_hour,          20);
        CHECK_EQ(tm.tm_min,           30);
        CHECK_EQ(tm.tm_sec,            0);
    }
}

#include "LogOverlay.h"
#include <QTextEdit>
#include <QPainter>
#include <QEvent>

LogOverlay::LogOverlay(QWidget* parent)
    : QWidget(parent)
{
    setAttribute(Qt::WA_StyledBackground, true);
    setAttribute(Qt::WA_TransparentForMouseEvents, true); // geen clicks nodig; zet op false als je selectie wil
    setFocusPolicy(Qt::NoFocus);

    m_text = new QTextEdit(this);
    m_text->setReadOnly(true);
    m_text->setFrameStyle(QFrame::NoFrame);
    m_text->setStyleSheet("QTextEdit { background: transparent; color: white; }");
}

void LogOverlay::attachTo(QWidget* target)
{
    m_target = target;
    if (!m_target) return;

    setParent(m_target);
    m_target->installEventFilter(this);
    updateGeometryToBottom();
    raise();
    hide(); // start onzichtbaar
}

void LogOverlay::setOverlayHeight(int h)
{
    m_height = qMax(0, h);
    updateGeometryToBottom();
    update();
}

void LogOverlay::showOverlay(bool on)
{
    if (on) {
        updateGeometryToBottom();
        show();
        raise();
    } else {
        hide();
    }
}

bool LogOverlay::eventFilter(QObject* obj, QEvent* ev)
{
    if (obj == m_target) {
        switch (ev->type()) {
        case QEvent::Resize:
        case QEvent::Move:
        case QEvent::Show:
            updateGeometryToBottom();
            raise();
            break;
        default: break;
        }
    }
    return QWidget::eventFilter(obj, ev);
}

void LogOverlay::updateGeometryToBottom()
{
    if (!m_target) return;
    const int w = m_target->width();
    const int h = m_height;
    setGeometry(0, m_target->height() - h, w, h);
    if (m_text) m_text->setGeometry(rect().adjusted(8, 6, -8, -6));
}

void LogOverlay::paintEvent(QPaintEvent* e)
{
    Q_UNUSED(e);
    // semi-transparant paneel achter de tekst
    QPainter p(this);
    p.setRenderHint(QPainter::Antialiasing, true);
    QRect r = rect().adjusted(2, 2, -2, -2);
    QColor bg(0,0,0,150);
    p.setPen(Qt::NoPen);
    p.setBrush(bg);
    p.drawRoundedRect(r, 8, 8);
}

