        Y[x] = m1;
        for (int i = 1; i <= n1; i++) {
            for (int j = 1; j <= m1; j++) {
                c[x][i][j] = get();
                Cnt[x][c[x][i][j]]++;
            }
        }
    }
    while (1) {
        int pos = 0;
        for (int i = 1; i <= k; i++) {
            int res = 0, p = 0;
            for (int j = 0; j < 128; j++) {
                res += max(0ll, Cnt[i][j] - cnt[j]);
                if (Cnt[i][j] && cnt[j]) p = 1;
            }
            if (res <= cnt[32] && p) {
