                    swap(b[xx][yy], b[xx + 1][yy]);
                    xx++;
                }
                while (yy < j) {
                    ans.pb({-1, {xx, yy}});
                    swap(b[xx][yy], b[xx][yy + 1]);
                    yy++;
                }
                while (yy > j) {
                    ans.pb({-2, {xx, yy}});
                    swap(b[xx][yy], b[xx][yy - 1]);
                    yy--;
                }
                while (xx > i) {
                    ans.pb({-4, {xx, yy}});
                    swap(b[xx][yy], b[xx - 1][yy]);
