                }
                vis[i][j] = 1;
                cnt[b[i][j]]--;
                b[i][j] = ' ';
                cnt[b[i][j]]++;
            }
        }
        ans.pb({pos, {1, 1}});
        while (1) {
            int xx = 0, yy = 0;
            for (int i = 1; i <= n; i++) {
                for (int j = 1; j <= m; j++) {
