                        }
                        while (xx > i) {
                            ans.pb({-4, {xx, yy}});
                            swap(b[xx][yy], b[xx - 1][yy]);
                            xx--;
                        }
                        cnt[b[i][j]]--;
                        b[i][j] = ' ';
