            if (!xx) {
                for (int x = 1; x <= n; x++) {
                    for (int y = 1; y <= m; y++) {
                        if (vis[x][y]) continue;
                        if (b[x][y] == ' ') {
                            xx = x;
                            yy = y;
                            break;
                        }
                    }
                    if (xx) break;
                }
            }
            if (!xx) {
                P = 0;
                break;
            }
            while (xx < i) {
                ans.pb({-3, {xx, yy}});
                swap(b[xx][yy], b[xx + 1][yy]);
