#include <vector>
#include <map>

class Solution {
public:
  // Counts elements that have their successor in the array
  int countElements(std::vector<int>& arr) {
    int count = 0;
    std::map<int, int> dict;

    // Build frequency map
    for (int x : arr) {
      dict[x]++;
    }

    // Check for each element if x+1 exists
    for (int x : arr) {
      if (dict[x + 1] > 0) {
        count++;
      }
    }

    return count;
  }
};

