class Solution {
public:
    // Moves all zeroes to the end of the array while maintaining relative order
    static void moveZeroes(std::vector<int>& nums) noexcept;
};

void Solution::moveZeroes(std::vector<int>& nums) noexcept
{
    // Use stable_partition to move non-zero elements to the front
    std::stable_partition(
        std::begin(nums),
        std::end(nums),
        [](const auto x) noexcept { return x != 0; }
    );
}

