#include "RandomWordIterator.h"

// Initialize random distribution if dictionary size changed
void RandomWordIterator::initRandom()
{
    if (lastSize != dict.Size()) // size changed
    {
        dist = std::unique_ptr<std::uniform_int_distribution<size_t> >(
            new std::uniform_int_distribution<size_t>(0, dict.Size() - 1)
        );
        lastSize = dict.Size();
    }
}

// Get next random word satisfying the predicate
std::string RandomWordIterator::Next()
{
    if (!HasNext())
    {
        return "";
    }

    initRandom();

    std::string word;
    do
    {
        word = dict[(*dist)(engine)];
    }
    while (!pred(word));

    return word;
}

// Check if any word satisfies the predicate
bool RandomWordIterator::HasNext()
{
    bool found = false;
    for (size_t i = 0; i < dict.Size(); ++i)
    {
        if (pred(dict[i]))
        {
            found = true;
            break;
        }
    }
    return found;
}

