class Solution {
public:
    // Constructor initializes the object with the given array
    Solution(vector<int>& nums) : origin(nums), nums(nums), n(nums.size()) {}

    /** Resets the array to its original configuration and return it. */
    vector<int> reset() {
        return origin;
    }

    /** Returns a random shuffling of the array. */
    vector<int> shuffle() {
        for(int i = n - 1; i >= 1; --i) {
            uniform_int_distribution<int> unif(0, i);
            int u = unif(gen);
            swap(nums[u], nums[i]);
        }
        return nums;
    }

private:
    vector<int> origin;
    vector<int> nums;
    int n;
    default_random_engine gen;
};

