// Extra POSIX/ANSI routines for Win32 when when using Visual Studio C++. Please
// refer to The Open Group Base Specification for specification of the correct
// semantics for these functions.
// (http://www.opengroup.org/onlinepubs/000095399/)
#ifdef _MSC_VER
#include <float.h>

// Classify floating point number - usually defined in math.h
int fpclassify(double x) 
{
    // Use the MS-specific _fpclass() for classification.
    int flags = _fpclass(x);

    // Determine class. We cannot use a switch statement because
    // the _FPCLASS_ constants are defined as flags.
    if (flags & (_FPCLASS_PN | _FPCLASS_NN)) 
        return FP_NORMAL;

    if (flags & (_FPCLASS_PZ | _FPCLASS_NZ)) 
        return FP_ZERO;

    if (flags & (_FPCLASS_PD | _FPCLASS_ND)) 
        return FP_SUBNORMAL;

    if (flags & (_FPCLASS_PINF | _FPCLASS_NINF)) 
        return FP_INFINITE;

    // All cases should be covered by the code above.
    ASSERT(flags & (_FPCLASS_SNAN | _FPCLASS_QNAN));
    return FP_NAN;
}
#endif  // _MSC_VER

#ifdef SOLARIS
#include <ieeefp.h>

// Classify floating point number
int fpclassify(double x) 
{
    fpclass_t rv = fpclass(x);
    switch (rv) 
    {
        case FP_SNAN:
        case FP_QNAN: 
            return FP_NAN;

        case FP_NINF:
        case FP_PINF: 
            return FP_INFINITE;

        case FP_NDENORM:
        case FP_PDENORM: 
            return FP_SUBNORMAL;

        case FP_NZERO:
        case FP_PZERO: 
            return FP_ZERO;

        default:
            ASSERT(rv == FP_NNORM || rv == FP_PNORM);
            return FP_NORMAL;
    }
}
#endif // SOLARIS

