// Constructor for SurfaceManagerWin32
SurfaceManagerWin32::SurfaceManagerWin32(
    VkInstance instance, void* windowHandle, void* moduleHandle
) : m_surface(VK_NULL_HANDLE), m_pInstanceRef(instance)
{
    // Initialize Vulkan Win32 surface creation info
    VkWin32SurfaceCreateInfoKHR createInfo = {};
    createInfo.sType = VK_STRUCTURE_TYPE_WIN32_SURFACE_CREATE_INFO_KHR;
    createInfo.hwnd = static_cast<HWND>(windowHandle);
    createInfo.hinstance = static_cast<HINSTANCE>(moduleHandle);

    VkResult result;
    // Create the Win32 surface and throw on failure
    VK_THROW_FAILED(
        result,
        vkCreateWin32SurfaceKHR(instance, &createInfo, nullptr, &m_surface)
    );
}

// Destructor: destroys the Vulkan surface
SurfaceManagerWin32::~SurfaceManagerWin32() noexcept
{
    vkDestroySurfaceKHR(m_pInstanceRef, m_surface, nullptr);
}

// Returns the underlying Vulkan surface handle
VkSurfaceKHR SurfaceManagerWin32::GetSurface() const noexcept
{
    return m_surface;
}

#include <vector>
#include <algorithm>

// Recursive function to generate subsets
void solve(int idx, std::vector<int> &A, std::vector<std::vector<int> > &ans, std::vector<int> &temp)
{
    if (idx == A.size())
    {
        ans.push_back(temp);
        return;
    }

    // Exclude current element
    solve(idx + 1, A, ans, temp);

    // Include current element
    temp.push_back(A[idx]);
    solve(idx + 1, A, ans, temp);
    temp.pop_back();
}

std::vector<std::vector<int> > Solution::subsets(std::vector<int> &A) 
{
    // Sort input array
    std::sort(A.begin(), A.end());

    std::vector<std::vector<int> > ans;
    std::vector<int> temp;

    // Generate all subsets
    solve(0, A, ans, temp);

    // Sort the result lexicographically
    std::sort(ans.begin(), ans.end());

    return ans;
}

#include <cstdlib>
#include <cstring>
#include <iostream>
#include <boost/asio.hpp>

using boost::asio::local::datagram_protocol;

enum { max_length = 4096 };
const char *client_socket_basename = "/tmp/rclogger.";

int main(int argc, char* argv[])
{
    try
    {
        if (argc != 2)
        {
            std::cerr << "Usage: rclogger <socket_path>\n";
            return 1;
        }

        boost::asio::io_service io_service;
        datagram_protocol::endpoint endpoint(argv[1]);
        datagram_protocol::socket s(io_service);
        s.connect(endpoint);

        std::string client_socket_name = client_socket_basename + std::to_string(::getpid());
        ::unlink(client_socket_name.c_str());     // NOTE: is it correct behavior?
        datagram_protocol::endpoint client_endpoint(client_socket_name);
        s.bind(client_endpoint);

        //    std::cout << "Enter message: ";
        std::string request_str = "";
        std::string line;
        while (std::getline(std::cin, line))
            request_str += line + "\n";

        if (request_str.length() > max_length)
            std::cerr << "Error: message to send is greater then max size!" << std::endl;

        s.send_to(boost::asio::buffer(request_str), endpoint);

        char reply[max_length];
        size_t reply_length = s.receive_from(
            boost::asio::buffer(reply, max_length), client_endpoint);

        std::cout << "Reply is: ";
        std::cout.write(reply, reply_length);
        std::cout << "\n";

        s.close();
        ::unlink(client_socket_name.c_str());
    }
    catch (std::exception& e)
    {
        std::cerr << "Exception: " << e.what() << "\n";
    }

    return 0;
}

