        case TVariantIndexV<TString, TValue>:
            return String;

        case TVariantIndexV<i64, TValue>:
            return Int64;

        case TVariantIndexV<ui64, TValue>:
            return Uint64;

        case TVariantIndexV<double, TValue>:
