// Propagates format information between source and destination images if needed
inline bool Vulkan::CopyImagePass::PropagateSubresourceInfos(std::span<SubresourceMetadataPayload> inoutMetadataPayloads)
{
    uint32_t srcImageIndex = (size_t)PassSubresourceId::SrcImage;
    uint32_t dstImageIndex = (size_t)PassSubresourceId::DstImage;

    bool propagationHappened = false;

    // Propagate from dst to src if src format is undefined
    if(inoutMetadataPayloads[srcImageIndex].Format == VK_FORMAT_UNDEFINED && 
       inoutMetadataPayloads[dstImageIndex].Format != VK_FORMAT_UNDEFINED)
    {
        inoutMetadataPayloads[srcImageIndex].Format = inoutMetadataPayloads[dstImageIndex].Format;
        propagationHappened = true;
    }

    // Propagate from src to dst if dst format is undefined
    if(inoutMetadataPayloads[dstImageIndex].Format == VK_FORMAT_UNDEFINED && 
       inoutMetadataPayloads[srcImageIndex].Format != VK_FORMAT_UNDEFINED)
    {
        inoutMetadataPayloads[dstImageIndex].Format = inoutMetadataPayloads[srcImageIndex].Format;
        propagationHappened = true;
    }

    return propagationHappened;
}

// Returns descriptor type for subresource (none in this pass)
inline VkDescriptorType Vulkan::CopyImagePass::GetSubresourceDescriptorType([[maybe_unused]] uint_fast16_t subresourceId)
{
    return VK_DESCRIPTOR_TYPE_MAX_ENUM; // No subresources in this pass have an associated descriptor type
}

