// Main Perlin noise function
double Perlin::perlin(double x, double y, double z)
{
    // Handle repetition if enabled
    if(repeat > 0)
    {
        // If we have any repeat on, change the coordinates to their "local" repetitions
        x = (int) x % repeat;
        y = (int) y % repeat;
        z = (int) z % repeat;
    }

    // Calculate the "unit cube" that the point asked will be located in
    // The left bound is ( |_x_|,|_y_|,|_z_| ) and the right bound is that
    // plus 1.  Next we calculate the location (from 0.0 to 1.0) in that cube.
    int xi = (int) x & 255;
    int yi = (int) y & 255;
    int zi = (int) z & 255;

    // We also fade the location to smooth the result.
    double xf = x - (int) x;
    double yf = y - (int) y;
    double zf = z - (int) z;

    double u = fade(xf);
    double v = fade(yf);
    double w = fade(zf);

    //    u = v = w = 0.5;

    int aaa, aba, aab, abb, baa, bba, bab, bbb;

    aaa = p[p[p[xi] + yi] + zi];
    aba = p[p[p[xi] + inc(yi)] + zi];
    aab = p[p[p[xi] + yi] + inc(zi)];
    abb = p[p[p[xi] + inc(yi)] + inc(zi)];
    baa = p[p[p[inc(xi)] + yi] + zi];
    bba = p[p[p[inc(xi)] + inc(yi)] + zi];
    bab = p[p[p[inc(xi)] + yi] + inc(zi)];
    bbb = p[p[p[inc(xi)] + inc(yi)] + inc(zi)];

    double x1, x2, y1, y2;

    // The gradient function calculates the dot product between a pseudorandom
    // gradient vector and the vector from the input coordinate to the 8
    // surrounding points in its unit cube.
    // This is all then lerped together as a sort of weighted average based on the faded (u,v,w)
    // values we made earlier.

    x1 = lerp(grad(aaa, xf, yf, zf),
              grad(baa, xf - 1, yf, zf),
              u);
    x2 = lerp(grad(aba, xf, yf - 1, zf),
              grad(bba, xf - 1, yf - 1, zf),
              u);
    y1 = lerp(x1, x2, v);

    x1 = lerp(grad(aab, xf, yf, zf - 1),
              grad(bab, xf - 1, yf, zf - 1),
              u);
    x2 = lerp(grad(abb, xf, yf - 1, zf - 1),
              grad(bbb, xf - 1, yf - 1, zf - 1),
              u);
    y2 = lerp(x1, x2, v);

    // For convenience we bound it to 0 - 1 (theoretical min/max before is -1 - 1)
    return (lerp(y1, y2, w) + 1) / 2;
}

// Increment with wrap-around support
int Perlin::inc(int num)
{
    num++;
    if(repeat > 0)
        num %= repeat;
    return num;
}

