// Gradient function using bit manipulation
double Perlin::grad(int hash, double x, double y, double z)
{
    // Take the hashed value and take the first 4 bits of it (15 == 0b1111)
    int h = hash & 15;

    // If the most significant bit (MSB) of the hash is 0 then set u = x.  Otherwise y.
    double u = h < 8 /* 0b1000 */ ? x : y;

    // In <NAME>'s original implementation this was another conditional operator (?:).  I
    // expanded it for readability.
    double v;

    //    v = h < 4 ? y : (h == 12 || h == 14 ? x : z);
    if(h < 4 /* 0b0100 */) // If the first and second significant bits are 0 set v = y
        v = y;
    else if(h == 12 /* 0b1100 */ ||
            h == 14 /* 0b1110*/) // If the first and second significant bits are 1 set v = x
        v = x;
    else // If the first and second significant bits are not equal (0/1, 1/0) set v = z
        v = z;

    // Use the last 2 bits to decide if u and v are positive or negative. Then return their addition.
    return ((h & 1) == 0 ? u : -u) + ((h & 2) == 0 ? v : -v);
}

// Fade function for smoothing interpolation
double Perlin::fade(double t)
{
    // Fade function as defined by <NAME>.  This eases coordinate values
    // so that they will "ease" towards integral values.  This ends up smoothing
    // the final output.
    return t * t * t * (t * (t * 6 - 15) + 10);            // 6t^5 - 15t^4 + 10t^3
}

// Linear interpolation helper
double Perlin::lerp(double a, double b, double x)
{
    return a + x * (b - a);
}

// Octave-based Perlin noise generator
double Perlin::OctavePerlin(double x, double y, double z, int octaves, double persistence)
{
    double total = 0;
    double frequency = 1;
    //    frequency = 2;
    double amplitude = 1;
    //    amplitude = persistence;
    double maxValue = 0;            // Used for normalizing result to 0.0 - 1.0

    for(int i = 0; i < octaves; i++)
    {
        total += perlin(x * frequency, y * frequency, z * frequency) * amplitude;
        //        auto t = perlin(x * frequency, y * frequency, z * frequency) * amplitude;
        //        if(t < 0)
        //            std::cout << x << y << z << t << std::endl;
        maxValue += amplitude;
        amplitude *= persistence;
        frequency *= 2;
        //        frequency += 2;
    }

    return total / maxValue;
}

