}

// ---------------------- FileDataPacket ------------
FileDataPacket::FileDataPacket(void* buf, ssize_t size)
    : FilePacket(buf, size) {
  if (count > 0) {
    data_buffer = ((uint8_t*)buf) + FilePacket::dataSize();
  } else {
    data_buffer = NULL;
  }
}

FileDataPacket::FileDataPacket(uint32_t id, int flag, int derived_size,
                               uint32_t fd, uint32_t file_id,
                               uint32_t stripe_id, uint32_t chunk_num,
                               uint32_t offset, int32_t count,
                               const uint8_t* buf)
    : FilePacket(id, flag, std::max(0, count), fd, file_id, stripe_id,
                 chunk_num, offset, count) {
  data_buffer = ((uint8_t*)packet) + FilePacket::dataSize();
  if (count > 0) {
    memcpy(data_buffer, buf, count);
  }
}

int FileDataPacket::dataSize() const {
  return FilePacket::dataSize() + data_size;
}

std::ostream& FileDataPacket::print(std::ostream& stream) const {
  stream << "FileDataPacket" << std::endl;
  stream << "data_buffer: ";
  if (data_buffer) {
    stream.write((const char*)data_buffer, count);
  } else {
    stream << "<NULL>";
  }
  stream << std::endl;
  return FilePacket::print(stream);
}

std::ostream& operator<<(std::ostream& stream, const FileDataPacket &packet) {
  return packet.print(stream);
}

