namespace Program
{
    // Signal handler for various system signals
    static void SignalHandler(int sig)
    {
        switch (sig)
        {
            case SIGABRT:
            case SIGINT:
            case SIGTERM:
                Exit(0);
                break;
            case SIGFPE:
                HardError("Signal: Floating point exception.");
                break;
            case SIGILL:
                HardError("Signal: Illegal instruction.");
                break;
            case SIGSEGV:
                HardError("Signal: Segmentation fault.");
                break;
            default:
                HardError("Signal: Unknown.");
                break;
        }
    }

    // C++ exception termination handler
    static void TerminateHandler()
    {
        if (std::exception_ptr e = std::current_exception())
        {
            try
            {
                std::rethrow_exception(e);
            }
            catch (std::exception &e)
            {
                std::string error;
                ExceptionToString(e, [&](const char *message)
                {
                    if (!error.empty())
                        error += "\n";
                    error += message;
                });
                HardError(error);
            }
            catch (...)
            {
                HardError("Unknown exception.");
            }
        }
        HardError("Terminated.");
    }

    // Flag to track whether handlers have been set
    static bool handers_set = false;

    // Display hard error and exit
    void HardError(const std::string &message)
    {
        static bool first = true;
        if (!first)
            Exit(1);
        first = 0;
        Interface::MessageBox(Interface::MessageBoxType::error, "Error", "Error: " + message);
        Exit(1);
    }

    // Set up error handling (signal and terminate handlers)
    void SetErrorHandlers(bool only_if_not_set_before)
    {
        if (only_if_not_set_before && handers_set)
            return;
        static constexpr int signal_enums[] {SIGSEGV, SIGABRT, SIGINT, SIGTERM, SIGFPE, SIGILL};
        for (int sig : signal_enums)
            std::signal(sig, SignalHandler);
        std::set_terminate(TerminateHandler);
        handers_set = true;
    }
}

