#include <concepts>

// Concept to check if a callable returns an integral type
template <typename T>
concept invoke_integral = requires (T a) {
    { a() } -> std::integral;
};

// Function template constrained by the concept
template <invoke_integral T>
void function(const T& f) {};

int main()
{
    // OK: lambda returns int (integral)
    function([](){ return 1; });

    // Error: lambda returns double (not integral)
    function([](){ return 1.0; });

    // Error: int is not callable
    function(1);
}

