// Main function to process prime counts in ranges
int main(int argc, char *argv[])
{
    const int max = 100001;
    // Allocate memory for prime checking array
    std::unique_ptr<bool[]> isPrime_ptr(new bool[max]);
    bool* isPrime = isPrime_ptr.get();

    // Initialize all numbers as prime
    for(int i=0; i<max; ++i)
    {
        isPrime[i] = true;
    }

    // 0 and 1 are not prime
    isPrime[0] = isPrime[1] = false;

    // Sieve of Eratosthenes to mark non-primes
    for(int i=2; i<max; ++i)
    {
        if(isPrime[i])
        {
            for(int j=i*2; j<max; j+=i)
            {
                isPrime[j] = false;
            }
        }
    }

    // Allocate memory for prefix sum of prime counts
    std::unique_ptr<int[]> countOfPrimeNumber_ptr(new int[Size]);
    int* countOfPrimeNumber = countOfPrimeNumber_ptr.get();

    // Initialize first element
    countOfPrimeNumber[0] = isPrime[Data[0]];

    // Build prefix sum array
    for(int i=1; i<Size; ++i)
    {
        countOfPrimeNumber[i] = countOfPrimeNumber[i-1] + isPrime[Data[i]];
    }

    // Validate command line arguments
    if(argc % 2 != 1 || argc == 1)
    {
        return -1;
    }

    // Process each query
    for(int k=1; k<argc; k+=2)
    {
        int n = atoi(argv[k]);
        int m = atoi(argv[k+1]);

        // Check if range is valid
        if(m < n)
        {
            std::cout<<0<<std::endl;
            return 0;
        }

        // Find index of n in Data array
        int i = 0;
        while(i < Size && Data[i] != n)
        {
            ++i;
        }

        // If n not found
        if(i >= Size)
        {
            std::cout<<0<<std::endl;
            return 0;
        }

        // Find index of m in Data array
        int j = Size - 1;
        while(j >= 0 && Data[j] != m)
        {
            --j;
        }

        // If m not found
        if(j < 0)
        {
            std::cout<<0<<std::endl;
            return 0;
        }

        // Calculate and output count of primes in range [n, m]
        std::cout<<countOfPrimeNumber[j] - countOfPrimeNumber[i] + isPrime[Data[i]]<<std::endl;
    }

    return 0;
}

