class Solution {
public:
    // Returns the product of array except self
    vector<int> productExceptSelf(vector<int>& nums)
    {
        vector<int> ans;
        int n = nums.size(), cur = 1;

        // Left products
        for(int i=0; i<n; ++i)
        {
            ans.push_back(cur);
            cur *= nums[i];
        }

        // Right products and final result
        cur = 1;
        for(int i=n-1; i>=0; --i)
        {
            ans[i] *= cur;
            cur *= nums[i];
        }

        return ans;
    }
};

