class NumMatrix {
public:
    // 3D sparse table: [row][start_index][power]
    std::vector<std::vector<std::vector<int>>> st;
    int k; // max power of 2 needed

    NumMatrix(std::vector<std::vector<int>>& matrix) {
        int m = matrix.size();
        int n = matrix[0].size();
        k = std::log2(n);

        // Resize sparse table
        st.resize(m, std::vector<std::vector<int>>(n, std::vector<int>(k + 1)));

        // Initialize base case (j=0)
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < n; j++) {
                st[i][j][0] = matrix[i][j];
            }
        }

        // Build sparse table for each row
        for (int row = 0; row < m; row++) {
            for (int j = 1; j <= k; j++) {
                for (int i = 0; i + (1 << j) <= n; i++) {
                    st[row][i][j] = st[row][i][j - 1] + st[row][i + (1 << (j - 1))][j - 1];
                }
            }
        }
    }

    int sumRegion(int row1, int col1, int row2, int col2) {
        int ans = 0;
        int l = col1;

        // Sum over rows from row1 to row2 using sparse table
        for (int j = k; j >= 0; j--) {
            if (l + (1 << j) - 1 <= col2) {
                for (int row = row1; row <= row2; row++) {
                    ans += st[row][l][j];
                }
                l += (1 << j);
            }
        }

        return ans;
    }
};

