	/* triang */
	for (i = n - 1; i > 0; --i) {
		int pin = pld->pindex[i];
		if (pin > -1) {
			double p;
			p = pld->a[i] / pld->d[i];
			pld->d[pin] -= p * pld->b[i];
			pld->rhs[pin] -= p * pld->rhs[i];
		}
	}
	/* bksub */
	for (i=0; i < n; ++i) {
		int pin = pld->pindex[i];
		if (pin > -1) {
			pld->rhs[i] -= pld->b[i] * pld->rhs[pin];
		}
		pld->rhs[i] /= pld->d[i];
	}
	/* update answer */
	for (i=0; i < n; ++i) {
		int mi = pld->mindex[i];
		data[mi][di] = pld->rhs[i];
	}
}

