        void to_string::operator()(std::string const& ast) const
        {
            if (util::is_repr(out_))
            {
                out_ << "\"";
                for (char c : ast)
                {
                    switch (c)
                    {
                    case '\b':  out_ << "\\\b"; break;
                    case '\n':  out_ << "\\n"; break;
                    case '\r':  out_ << "\\r"; break;
                    case '\t':  out_ << "\\t"; break;
                    case '\\':  out_ << "\\\\"; break;
                    case '\"':  out_ << "\\\""; break;
                    default:    out_ << c;
                    }
                }
                out_ << "\"";
            }
            else
            {
                for (char c : ast)
                {
                    out_ << c;
                }
            }
        }
