void
ensure(int which, bool claim)
{
  if (not claim)
    std::exit(which);
}

int
main()
{
  {
    exempt_ptr<int> p;
    ensure(11, !p);
    ensure(12, p == nullptr);
    ensure(13, nullptr == p);
    ensure(14, p == 0);
    ensure(15, 0 == p);
  }

  { // non-const => const
    int* p = new int(0);
    exempt_ptr<int const> ep(p);
  }

  {
    exempt_ptr<double const> p = make_exempt_ptr(new double(42.0));
    ensure(21, p != nullptr);
    ensure(22, nullptr != p);
    ensure(23, *p == 42.0);
  }

#if 0
  { // const => non-const (ought fail to compile)
    int const * p = new int(0);
    exempt_ptr<int> ep(p);
  }
#endif // 0

  {
    exempt_ptr<int> p(new int(16));
    ensure(31, p != nullptr);
    ensure(32, nullptr != p);
    ensure(33, *p == 16);

    exempt_ptr<int> q(p);
    ensure(34, p == q);
    ensure(35, *p == *q);

    p.reset(new int(0));
    return *p;
  }
} // main()

#include <vector>
#include <queue>

class Solution {
public:
    // Finds the root nodes of minimum height trees
    vector<int> findMinHeightTrees(int n, vector<vector<int>>& edges)
    {
        // Build adjacency list and degree count
        vector<int> tree[n];
        vector<int> edge(n, 0);

        for(auto e : edges)
        {
            tree[e[1]].push_back(e[0]);
            tree[e[0]].push_back(e[1]);
            edge[e[0]]++;
            edge[e[1]]++;
        }

        int index = n;

        // Trim leaves until we have 2 or fewer nodes
        while(index > 2)
        {
            queue<int> q;

            // Find all current leaves (degree == 1)
            for(int i = 0; i < n; i++)
            {
                if(edge[i] == 1)
                {
                    q.push(i);
                    edge[i] = -1;  // Mark as removed
                    index--;
                }
            }

            // Remove leaves and update degrees of their neighbors
            while(!q.empty())
            {
                int f = q.front();
                q.pop();

                for(int g : tree[f])
                {
                    edge[g]--;
                }
            }
        }

        // Collect remaining nodes (roots of MHTs)
        vector<int> result;
        for(int i = 0; i < n; i++)
        {
            if(edge[i] == 0 || edge[i] == 1)
            {
                result.push_back(i);
            }
        }

        return result;
    }
};

#include <string>
#include <cmath>

class Solution {
public:
    // Finds the smallest good base for the given number
    std::string smallestGoodBase(std::string n) {
        unsigned long long tn = (unsigned long long)stoll(n);
        unsigned long long x = 1;

        // Iterate from maximum possible base down to 1
        for (int i = 62; i >= 1; --i) {
            if ((x << i) < tn) {
                unsigned long long cur = mysolve(tn, i);
                if (cur != 0) return to_string(cur);
            }
        }
        return to_string(tn - 1);
    }

    // Helper function to solve for base given length d
    unsigned long long mysolve(unsigned long long n, int d) {
        double tn = (double)n;
        unsigned long long right = (unsigned long long)(pow(tn, 1.0 / d) + 1);
        unsigned long long left = 1;

        while (left <= right) {
            unsigned long long mid = left + (right - left) / 2;
            unsigned long long sum = 1;
            unsigned long long cur = 1;

            // Calculate sum: 1 + mid + mid^2 + ... + mid^d
            for (int i = 1; i <= d; ++i) {
                cur *= mid;
                sum += cur;
            }

            if (sum == n) return mid;
            if (sum > n) right = mid - 1;
            else left = mid + 1;
        }
        return 0;
    }
};

