// Initialize JayD system
void JayDImpl::begin()
{
    // Check and initialize PSRAM if available
    if(psramFound()){
        Serial.printf("PSRAM init: %s, free: %d B\n", psramInit() ? "Yes" : "No", ESP.getFreePsram());
    }else{
        Serial.println("No PSRAM detected");
    }

    // Disable watchdog timers
    disableCore0WDT();
    disableCore1WDT();

    // Turn off WiFi and Bluetooth
    WiFi.mode(WIFI_OFF);
    btStop();

    // Initialize SPI bus
    SPI.begin(SPI_SCK, SPI_MISO, SPI_MOSI, SPI_SS);
    SPI.setFrequency(60000000);

    // Check SD card
    if(!SD.begin(SD_CS, SPI)){
        Serial.println("No SD card");
    }

    // Initialize SPIFFS
    if(!SPIFFS.begin()){
        Serial.println("SPIFFS error");
    }

    // Initialize display
    display.begin();
    SPI.setFrequency(20000000);

    // Initialize LED matrix
    if(!LEDmatrix.begin(I2C_SDA, I2C_SCL)){
        Serial.println("couldn't start matrix");
    }

    // Add loop listeners
    LoopManager::addListener(&Sched);
    LoopManager::addListener(&matrixManager);
    LoopManager::addListener(new InputJayD());
    InputJayD::getInstance()->begin();

    // Initialize settings and set brightness
    Settings.begin();
    LEDmatrix.setBrightness(80.0f * (float) Settings.get().brightnessLevel / 255.0f);
}

