// Arc error tolerance
const double arcError = 0.01;

// Offset benchmark function
static void offset(NoSetup, TestProfile const &profile)
{
    for(std::size_t i=1;i<=profile.offsetCount;++i)
    {
        double offset = i * profile.offsetDelta;
        cavc::parallelOffset(profile.pline, offset);
        cavc::parallelOffset(profile.pline, -offset);
    }
}

// Create benchmarks with default settings
CAVC_CREATE_BENCHMARKS(offset, NoSetup, offset, benchmark::kMillisecond)

// Create benchmarks without arcs
CAVC_CREATE_NO_ARCS_BENCHMARKS(offset, NoSetup, offset, arcError, benchmark::kMillisecond)

// Main benchmark entry point
BENCHMARK_MAIN();

#include "../common.h"
#include <rpi/vcprops.h>

// Initialize VC memory mapping
static void initVCMem()
{
    VCPROPS props;
    if (!vcPropsAlloc(&props, 256))
    {
        kputs("Cannot allocate VCProps buffer!\n");
        return;
    }

    vu32* tag = vcPropsAddTag(&props, VCTag_GetVCMem, 0, 2*4);
    if (!vcPropsExecute(&props))
    {
        vcPropsFree(&props);
        kputs("Mailbox request error!\n");
        return;
    }

    u32 vcMemStart = tag[0];
    u32 vcMemSize = tag[1];

    vcPropsFree(&props);

    int startIdx = L1_INDEX(phys2virt(vcMemStart));
    int endIdx = startIdx + (vcMemSize>>20);

    u32 curPos = vcMemStart - BIT(20);
    int i;

    for (i = startIdx; i < endIdx; i++)
        MASTER_PAGETABLE[i] = MMU_L1_SECT1MB | (curPos+=BIT(20)) | MMU_L1_RWNA | MMU_L1_UNCACHED;

    kprintf("VC memory @ addr %p (%u bytes)\n", vcMemStart, vcMemSize);
}

void DevInitPlatform()
{
    initVCMem();
    LINK_MODULE(RPiFramebuffer);
}

#include "game_hooks.hpp"

// Flag to ensure hooking happens only once
bool hook_done = false;

// This function is included to allow adding DLL to import address table
// It is never called
__declspec(dllexport) void __stdcall bean() { 
    return; 
}

BOOL APIENTRY DllMain(HMODULE hModule, DWORD ul_reason_for_call,
                      LPVOID lpReserved) {
    switch (ul_reason_for_call) {
        case DLL_PROCESS_ATTACH:
            if (!hook_done) {
                hook_done = true;
                doTheHook();
            }
            break;  // Added missing break for consistency
        case DLL_THREAD_ATTACH:
        case DLL_THREAD_DETACH:
        case DLL_PROCESS_DETACH:
            break;
    }
    return TRUE;
}

