// Constructor: default initialization
CRenderTarget::CRenderTarget()
{
    CreateRenderTarget(0, 0, RTKIND_COLOR);
}

// Constructor: with parameters
CRenderTarget::CRenderTarget(unsigned int w, unsigned int h, UCHAR kind)
{
    CreateRenderTarget(w, h, kind);
}

// Destructor
CRenderTarget::~CRenderTarget()
{
    Release();
}

// Release resources and handle cleanup
void CRenderTarget::Release()
{
    if (DelRef())
    {
        LPDIRECT3DSURFACE9 surf;
        RENDERER->GetDevice()->GetRenderTarget(0, &surf);
        if (surf == mSurfaceHandle)
        {
            RENDERER->SetRenderTarget(nullptr);
        }
        SAFE_RELEASE(mTextureHandle);
        SAFE_RELEASE(mSurfaceHandle);
        SAFE_RELEASE(mDepthStencilSurfaceHandle);
        delete this;
    }
}

// Bind the render target for rendering
void CRenderTarget::Bind()
{
    RENDERER->SetRenderTarget(this);
}

// Create the actual render target surface and texture
void CRenderTarget::CreateRenderTarget(unsigned int w, unsigned int h, UCHAR kind)
{
    mKind = kind;
    mTextureHandle = nullptr;
    mSurfaceHandle = nullptr;
    mDepthStencilSurfaceHandle = nullptr;

    D3DSURFACE_DESC dp = RENDERER->GetDisplayDesc();

    // Supported formats array
    D3DFORMAT formats[] = {dp.Format, D3DFMT_R32F, D3DFMT_A16B16G16R16F, D3DFMT_A32B32G32R32F};

    // Calculate dimensions
    unsigned int width = w != 0u ? w : dp.Width;
    unsigned int height = h != 0u ? h : dp.Height;

    // Create texture
    LRESULT res = RENDERER->GetDevice()->CreateTexture(
        width,
        height,
        1,
        D3DUSAGE_RENDERTARGET,
        formats[kind],
        D3DPOOL_DEFAULT,
        &mTextureHandle,
        nullptr
    );

    if (FAILED(res))
    {
        MessageBoxA(nullptr, "Failed to create render target!", "Renderer error", MB_OK);
        ENGINE->Shutdown();
        return;
    }

    // Create depth-stencil surface if not depth-only target
    if (kind != RTKIND_DEPTH)
    {
        RENDERER->GetDevice()->CreateDepthStencilSurface(
            width,
            height,
            D3DFMT_D24S8,
            D3DMULTISAMPLE_NONE,
            0,
            TRUE,
            &mDepthStencilSurfaceHandle,
            nullptr
        );
    }

    // Get surface level from texture
    mTextureHandle->GetSurfaceLevel(0, &mSurfaceHandle);
}

#include "../../template.hpp"

// Recursive helper function to count set bits
int rec_(int n)
{
    if (n == 0) return 0;
    return rec_(n >> 1) + (n & 1);
}

// Recursive approach to generate bit counts for 0..n
vi rec(int n)
{
    vi ans;
    for (int i = 0; i <= n; ++i)
    {
        ans.push_back(rec_(i));
    }
    return ans;
}

// Tabulation approach to generate bit counts for 0..n
vi tab(const int n)
{
    vi dp(n + 1);
    vi ans = {0};
    for (int i = 1; i <= n; ++i)
    {
        dp[i] = dp[i >> 1] + (i & 1);
        ans.push_back(dp[i]);
    }
    return ans;
}

int main() { TimeMeasure _; __x();
    // Output results using recursive method
    cout << rec(0) << endl; // 0
    cout << rec(2) << endl; // 0,1,1
    cout << rec(5) << endl; // 0,1,1,2,1,2
    cout << endl;

    // Output results using tabulation method
    cout << tab(0) << endl; // 0
    cout << tab(2) << endl; // 0,1,1
    cout << tab(5) << endl; // 0,1,1,2,1,2
}

