// Error handling macro: throws a JavaScript TypeError with the given message
#define EE(s) {TypeError::New(e, s).ThrowAsJavaScriptException(); return e.Null();}

using namespace Napi;

// Helper: convert JS Number to C int, checking for integer-ness
static inline I ii(Value v) {
    F d = v.As<Number>().DoubleValue();
    R (I)d == d;
}

// Get element i from JS array v
Value oi(Value v, I i) {
    Array a = v.As<Array>();
    R a[i];
}

// Determine K type from JS Value
I to(Value v) {
    if (v.IsNumber()) {
        P(ii(v), 'j');
        R 'f';
    }
    P(v.IsArray(), ' ');
    R 0;
}

// Convert JS Value to K object
K ko(Value v) {
    S(to(v),
      C(0, 0)
      C('j', kj(v.As<Number>().Int64Value()))
      C('f', kf(v.As<Number>().DoubleValue())),
      K x = k(' ', v.As<Array>().Length());
      N(xn, Xx = ko(oi(v, i));
      P(!Xx, 0))
      x
    )
}

// Convert K object back to JS Value
Value ok(Env e, K x) {
    S(tx,
      C(KJ, Number::New(e, (F)xj))
      C(KF, Number::New(e, xf)),
      Array v = Array::New(e, xn);
      N(xn, v[i] = ok(e, Xx))
      v
    )
}

// Main exported function: k(functionName, argsArray)
Value _(const CallbackInfo& i) {
    Env e = i.Env();
    // Validate arguments
    if (i.Length() != 2) EE("format: k(function name, args array)");
    if (!i[0].IsString() || !i[1].IsObject()) EE("Wrong args");

    Value v;
    S cf = i[0].ToString().Utf8Value().c_str();
    K x = ko(i[1]);

    // Execute and handle errors
    R !x || ERR(x = k((K)cf, x)) ?
        TypeError::New(e, "ex").ThrowAsJavaScriptException(), e.Null() :
        (v = ok(e, x), k(0, x), v);
}

// Module initialization
Object Init(Env e, Object exp) {
    exp.Set(String::New(e, "k"), Function::New(e, _));
    R exp;
}

NODE_API_MODULE(k, Init);

