using namespace std;
using namespace std::placeholders;

// Global variable tracking last successful verification line
long g_last_successful_line(0);

// Verification helper: updates last successful line if condition holds; otherwise reports failure and aborts
void verify(const bool b, const long line)
{
    if (b)
    {
        _InterlockedExchange(&g_last_successful_line, line);
    }
    else
    {
        printf("Last successful line was %ld.\n", _InterlockedCompareExchange(&g_last_successful_line, 0, 0));
        printf("Failed on line %ld.\n", line);
        abort();
    }
}

// Macro to simplify verification with automatic line number
#define VERIFY(B) verify(B, __LINE__)

// Placeholder writer functor for testing placeholder handling
struct WritePlaceholder
{
    template<typename T>
    void operator()(const T&, int* const p) const
    {
        *p = is_placeholder_v<T>;
    }
};

// Function that throws exceptions based on counter value
void ThrowingFunc(int* const p)
{
    ++(*p);

    switch (*p)
    {
    case 1:
        throw overflow_error("one");
    case 2:
        throw underflow_error("two");
    default:
        break;
    }
}

// ***** Machinery to test the XP codepath: *****
// extern "C" {
//     extern void * __encodedKERNEL32Functions[40 /* eMaxKernel32Function */];
//     extern uintptr_t __security_cookie;
// }

void run_tests()
{
    // Basic call_once usage test
    {
        once_flag flag;
        auto inc = [](int* const p) { ++(*p); };
        int i = 0;

        VERIFY(i == 0);
        call_once(flag, inc, &i);
        VERIFY(i == 1);
        call_once(flag, inc, &i);
        VERIFY(i == 1);
    }

    // Test INVOKE() usage via member function pointer
    {
        struct Meow
        {
            int x;
            int y;

            void write_sum(int* const p) const
            {
                *p = x + y;
            }
        };

        once_flag flag;
        Meow m = {1700, 29};
        int i = 0;

        call_once(flag, &Meow::write_sum, &m, &i);
        VERIFY(i == 1729);
    }

    // Verify call_once does NOT use bind internally (uses placeholders directly)
    {
        once_flag flag1;
        int i1 = -1;

        call_once(flag1, WritePlaceholder(), 3.14, &i1);
        VERIFY(i1 == 0);

        once_flag flag2;
        int i2 = -1;

        call_once(flag2, WritePlaceholder(), _5, &i2);
        VERIFY(i2 == 5);
    }

    // DevDiv#1086953: Exception handling — single-threaded
    {
        once_flag flag;
        int i = 0;

        try
        {
            call_once(flag, ThrowingFunc, &i);
            VERIFY(false);
        }
        catch (const overflow_error& e)
        {
            VERIFY(i == 1);
            VERIFY(e.what() == "one"s);
        }
        catch (...)
        {
            VERIFY(false);
        }

        try
        {
            call_once(flag, ThrowingFunc, &i);
            VERIFY(false);
        }
        catch (const underflow_error& e)
        {
            VERIFY(i == 2);
            VERIFY(e.what() == "two"s);
        }
        catch (...)
        {
            VERIFY(false);
        }

        try
        {
            call_once(flag, ThrowingFunc, &i);
            VERIFY(i == 3);

            call_once(flag, ThrowingFunc, &i);
            VERIFY(i == 3);
        }
        catch (...)
        {
            VERIFY(false);
        }
    }

    // DevDiv#1086953: Exception handling — multi-threaded
    {
        long ready = 0;
        once_flag flag;
        int i = 0;

        auto lambda = [&ready, &flag, &i]
        {
            while (!_InterlockedCompareExchange(&ready, 0, 0))
            {
            }

            try
            {
                call_once(flag, ThrowingFunc, &i);
                VERIFY(i == 3);
            }
            catch (const overflow_error& e)
            {
                VERIFY(e.what() == "one"s);
            }
            catch (const underflow_error& e)
            {
                VERIFY(e.what() == "two"s);
            }
            catch (...)
            {
                VERIFY(false);
            }
        };

        vector<thread> v;

        // Launch 5 threads: 2 exceptional, 1 success, 2 passive
        for (int n = 0; n < 5; ++n)
        {
            v.emplace_back(lambda);
        }

        _InterlockedExchange(&ready, 1);

        for (auto& t : v)
        {
            t.join();
        }

        VERIFY(i == 3);
    }

    // DevDiv#1092852: Concurrent calls should not block unnecessarily
    {
        long atom = 0;

        thread t1([&atom]
        {
            once_flag flag1;

            auto lambda1 = [&atom]
            {
                _InterlockedExchange(&atom, 100);
                while (_InterlockedCompareExchange(&atom, 111, 200) != 200)
                {
                }
            };

            call_once(flag1, lambda1);
        });

        thread t2([&atom]
        {
            once_flag flag2;

            auto lambda2 = [&atom]
            {
                while (_InterlockedCompareExchange(&atom, 200, 100) != 100)
                {
                }
                while (_InterlockedCompareExchange(&atom, 222, 111) != 111)
                {
                }
            };

            call_once(flag2, lambda2);
        });

        t1.join();
        t2.join();

        VERIFY(atom == 222);
    }

    // Ensure active executions do not overlap
    {
        once_flag flag;
        long atom = 0;

        auto thread_lambda = [&flag, &atom]
        {
            try
            {
                call_once(flag, [&atom]
                {
                    VERIFY(_InterlockedIncrement(&atom) == 1);
                    this_thread::sleep_for(50ms);
                    VERIFY(_InterlockedDecrement(&atom) == 0);
                    throw runtime_error("woof");
                });
                VERIFY(false);
            }
            catch (const runtime_error& e)
            {
                VERIFY(e.what() == "woof"s);
            }
            catch (...)
            {
                VERIFY(false);
            }
        };

        vector<thread> v;

        for (int n = 0; n < 5; ++n)
        {
            v.emplace_back(thread_lambda);
        }

        for (auto& t : v)
        {
            t.join();
        }
    }

    // LWG-2442: call_once shouldn't DECAY_COPY arguments
    {
        once_flag flag;
        int n = 0;
        auto lambda = [](int& r) { r = 1729; };

        VERIFY(n == 0);
        call_once(flag, lambda, n);
        VERIFY(n == 1729);
    }
}

int main()
{
    try
    {
        run_tests();
    }
    catch (const exception& e)
    {
        puts(e.what());
        VERIFY(false);
    }

    puts("Passed.");
}

#include "cameraserver/CameraServerShared.h"
