                    mCursor++;
                mC = key_None;
                mCursorMoved = true;
                break;
            case sc_Home:
                mCursor = 0;
                mC = key_None;
                mCursorMoved = true;
                break;
            case sc_End:
                mCursor = mStr.size();
                mC = key_None;
                mCursorMoved = true;
                break;
            case sc_Return:
                strcpy(mBuf, mStr.c_str());
                mDone = true;
                mResult = true;
                mC = key_None;
                break;
            case sc_Escape:
                if (mEscok)
                {
                    mDone = true;
                    mResult = false;
                }
                mC = key_None;
                break;
            case sc_BackSpace:
                if (mCursor)
                {
                    auto sCur = mStr.substr(mCursor);
                    mStr.replace(mCursor - 1, sCur.size(), sCur);
                    mCursor--;
                    mRedraw = true;
                }
                mC = key_None;
                mCursorMoved = true;
                break;
            case sc_Delete:
                if (mStr[mCursor])
                {
                    auto sCur = mStr.substr(mCursor + 1);
                    mStr.replace(mCursor, sCur.size(), sCur);
                    mRedraw = true;
                }
                mC = key_None;
                mCursorMoved = true;
                break;
            case 0x4c:	// Keypad 5
            case sc_UpArrow:
            case sc_DownArrow:
            case sc_PgUp:
            case sc_PgDn:
            case sc_Insert:
                mC = key_None;
                break;
            }
            if (mC)
            {
                uint16_t w, h;
                const auto len = mStr.size();
                USL_MeasureString(mStr.c_str(), NULL, &w, &h);
                if (isprint(mC)
                        && (len < MaxString - 1)
                        && ((!mMaxchars) || (len < mMaxchars))
                        && ((!mMaxwidth) || (w < mMaxwidth)))
                {
                    mStr.insert(mCursor, 1, mC);
                    mRedraw = true;
                }
            }*/

            // Let the system set a name;
            mDone = true;
            mResult = true;
            time_t rawtime;
            struct tm *timeinfo;
            time(&rawtime);
            timeinfo = localtime(&rawtime);
            std::string slotStr = asctime(timeinfo);
            mStr = slotStr;
            mRedraw = true;
            strcpy(mBuf, mStr.c_str());

            /*if(gInput.getPressedCommand(IC_BACK))
            {
                // Let the system set a name;
                mDone = true;
                mResult = false;
                return;
            }*/

            if (mRedraw)
            {
                px = mx;
                py = my;
                USL_DrawString(oldStr.c_str(), NULL);
                oldStr = mStr;
                px = mx;
                py = my;
                USL_DrawString(oldStr.c_str(), NULL);
                mRedraw = false;
            }

            if (mCursorMoved)
            {
                mCursorvis = false;
                mLasttime = SD_GetTimeCount() - TickBase;
                mCursorMoved = false;
            }

            if (SD_GetTimeCount() - mLasttime > TickBase / 2)
            {
                mLasttime = SD_GetTimeCount();
                mCursorvis ^= true;
            }
        }
        else
        {
            gInput.flushAll();
            if (!mResult)
            {
                px = mx;
                py = my;
                USL_DrawString(oldStr.c_str(), NULL);
            }

            VW_ShowCursor();
            VW_UpdateScreen();
            IN_ClearKeysDown();
            gEventManager.add(new CloseLineInput);
            gEventManager.add(new SaveGameEvent(mStr, true, true, mN));
        }
        //return(result);
    }

    void LineInput::render()
    {
        if (mCursorvis)
        {
            USL_XORICursor(mx, my, mStr.c_str(), mCursor);
        }

        VW_UpdateScreen();
    }
}

