#include "circular_buffer.hpp"
#include <iostream>

// Main function demonstrating CircularQueue and CircularBuffer usage
int main()
{
    std::cout << "Queue" << std::endl;

    // Test CircularQueue with int, capacity 3
    CircularQueue<int, 3> buffer;
    buffer.pushBack(3);
    buffer.pushBack(4);
    std::cout << "Full (2/3)? " << buffer.full() << std::endl;
    buffer.pushBack(5);
    std::cout << "Full (3/3)? " << buffer.full() << std::endl;
    std::cout << "Front (should be 3) " << buffer.front() << std::endl;
    buffer.popFront();
    buffer.popFront();
    std::cout << "Front (should be 5) " << buffer.front() << std::endl;
    std::cout << "Empty (1/3)? " << buffer.empty() << std::endl;
    buffer.popFront();
    std::cout << "Full (0/3)? " << buffer.full() << std::endl;
    std::cout << "Empty (0/3)? " << buffer.empty() << std::endl;
    std::cout << std::endl;

    // Test CircularQueue with float, capacity 2
    CircularQueue<float, 2> buffer2;
    buffer2.pushBack(3.3);
    buffer2.pushBack(4.4);
    buffer2.popFront();
    buffer2.pushBack(5.5);
    std::cout << "Front (should be 4.4) " << buffer2.front() << std::endl;
    std::cout << "Size (2/2) " << buffer2.size() << std::endl;
    buffer2.popFront();
    std::cout << "Size (1/2) " << buffer2.size() << std::endl;
    buffer2.popFront();
    std::cout << "Size (0/2) " << buffer2.size() << std::endl;
    std::cout << std::endl;

    // Test CircularBuffer with custom struct
    std::cout << "Buffer" << std::endl;
    struct Inside {
        float value;
        int index;
    };
    CircularBuffer<Inside, &Inside::index, 3> buffer3;
    buffer3.insert({3.3, 3});
    buffer3.insert({4.4, 4});
    std::cout << "Size is (should be 2) " << buffer3.size() << std::endl;
    std::cout << "Is 3 there? (should be) " << buffer3.has(3) << std::endl;
    std::cout << "Is 5 there? (shouldn't be) " << buffer3.has(5) << std::endl;
    std::cout << "What is on 4? (4.4) " << buffer3.get(4).value << std::endl;
    std::cout << "Extracting 3. (3.3) " << buffer3.extract(3).value << std::endl;
    std::cout << "Is 3 there? (shouldn't be) " << buffer3.has(3) << std::endl;
    std::cout << "Size is (should be 1) " << buffer3.size() << std::endl;
    std::cout << "Extracting 4. (4.4) " << buffer3.extract(4).value << std::endl;
    std::cout << "Size is (should be 0) " << buffer3.size() << std::endl;
    std::cout << "Can get 4 now? (shouldn't) " << bool(buffer3.tryGet(4)) << std::endl;

    return 0;
}

#include <iostream>
using namespace std;

// Main function to process kingdom transformations
int main()
{
    int * kingdom1 = new int[10000], * kingdom2 = new int[10000];
    int N, R, C, K;

    // Process each test case
    while (cin >> N >> R >> C >> K && !(N == 0 && R == 0 && C == 0 && K == 0))
    {
        // Read initial kingdom state
        for (int i = 0; i < R; i++)
            for (int j = 0; j < C; j++)
                cin >> kingdom1[i*100 + j];

        // Apply K transformations
        for (int b = 0; b < K; b++)
        {
            int * k1 = (b & 1 ? kingdom2: kingdom1);
            int * k2 = (b & 1 ? kingdom1: kingdom2);

            for (int i = 0; i < R; i++)
                for (int j = 0; j < C; j++)
                {
                    int attacked = 0, auxi = (k1[i*100 + j] + N - 1) % N;

                    // Check adjacent cells
                    if (i > 0) attacked |= k1[(i-1)*100 + j] == auxi;
                    if (j > 0) attacked |= k1[i*100 + j-1] == auxi;
                    if (i < R - 1) attacked |= k1[(i+1)*100 + j] == auxi;
                    if (j < C - 1) attacked |= k1[i*100 + j+1] == auxi;

                    // Update cell value based on attack status
                    if (attacked) k2[i*100 + j] = auxi;
                    else k2[i*100 + j] = k1[i*100 + j];
                }
        }

        // Output final state
        int * k = (K & 1 ? kingdom2: kingdom1);
        for (int i = 0; i < R; i++)
        {
            bool first = false;
            for (int j = 0; j < C; j++)
            {
                if (first) printf(" ");
                else first = true;
                printf("%d", k[i*100 + j]);
            }
            printf("\n");
        }
    }

    // Clean up memory
    delete [] kingdom1;
    delete [] kingdom2;

    return 0;
}

#include "CameraMan.h"

// CameraMan constructor
CameraMan::CameraMan(Camera* cam)
	: mCamera(0)
	, mTarget(0)
{
	setCamera(cam);
	setTarget(mTarget ? mTarget : mCamera->getSceneManager()->getRootSceneNode());
	mCamera->setFixedYawAxis(true);
	setYawPitchDist(Degree(0), Degree(15), 150);
}

// Destructor
CameraMan::~CameraMan() {}

// Set camera
void CameraMan::setCamera(Camera* cam) {
	mCamera = cam;
}

// Get camera
Camera* CameraMan::getCamera() {
	return mCamera;
}

// Set target scene node
void CameraMan::setTarget(SceneNode* target) {
	if (target != mTarget) {
		mTarget = target;
		if(target) {
			setYawPitchDist(Degree(0), Degree(15), 150);
			mCamera->setAutoTracking(true, mTarget);
		} else {
			mCamera->setAutoTracking(false);
		}
	}
}

// Get target scene node
SceneNode* CameraMan::getTarget() {
	return mTarget;
}

// Set yaw, pitch and distance relative to target
void CameraMan::setYawPitchDist(Radian yaw, Radian pitch, Real dist) {
	mCamera->setPosition(mTarget->_getDerivedPosition());
	mCamera->setOrientation(mTarget->_getDerivedOrientation());
	mCamera->yaw(yaw);
	mCamera->pitch(-pitch);
	mCamera->moveRelative(Ogre::Vector3(0, 0, dist));
}

// Handle mouse movement input
void CameraMan::injectMouseMove(const MouseEvent& evt) {
	Real dist = (mCamera->getPosition() - mTarget->_getDerivedPosition()).length();

	mCamera->setPosition(mTarget->_getDerivedPosition());

	mCamera->yaw(Degree(-evt.state.X.rel * 0.25f));
	mCamera->pitch(Degree(-evt.state.Y.rel * 0.25f));
	mTarget->yaw(Degree(-evt.state.X.rel * 0.25f));

	mCamera->moveRelative(Ogre::Vector3(0, 0, dist));

	if(evt.state.Z.rel != 0) {
		mCamera->moveRelative(Ogre::Vector3(0, 0, -evt.state.Z.rel * 0.0008f * dist));
	}
}

#include "llvm/TextAPI/Architecture.h"
#include "llvm/ADT/StringSwitch.h"
