    lookupFunc(func);
    lua_pushstring(_lua, a);
    lua_pushstring(_lua, b);
    lua_pushstring(_lua, c);
    lua_pushstring(_lua, d);
    lua_pushstring(_lua, e);
    return doCall(5);
}

