#include <utils/LogDefines.h>
#include <string>     // std::string, std::stoul, std::getline

using json = nlohmann::json;

int main(int argc, char *argv[])
{
    using namespace httplib;
    Server svr;

    // Check the number of parameters
    if (argc < 3) {
        // Tell the user how to run the program
        std::cerr << "Usage: " << argv[0] << " <ENDPOINT> <PORT>" << std::endl;
        return 1;
    }

    char* pAddress = argv[1];
    uint32_t port = std::stoul(argv[2]);

    LOG_INF("Running server on endpoint {}:{}", pAddress, port);

    svr.Get("/hi", [](const httplib::Request &, httplib::Response &res) {
        res.set_content("Hello World!", "text/plain");
    });

    svr.Post("/configure", [](const Request& req, Response& res) {
        json jRequest = json::parse(req.body);
        json jResponse;
        res.status = Controller::setup(jRequest, jResponse);
        res.set_content("{\"teste\": \"Hello World!\"s}", "application/json");
    });

    svr.Post("/createSession", [](const Request &req, Response &res) {
        json jRequest = json::parse(req.body);
        json jResponse;
        res.status = Controller::createSesssion(jRequest, jResponse);
        res.set_content("{\"teste\": \"Hello World!\"s}", "application/json");
    });

    svr.listen(pAddress, port);
}

#include "clang/Basic/SourceMgrAdapter.h"
#include "clang/Basic/Diagnostic.h"

using namespace clang;

// Handle diagnostic from LLVM SourceMgr
void SourceMgrAdapter::handleDiag(const llvm::SMDiagnostic &diag, void *context) {
    static_cast<SourceMgrAdapter *>(context)->handleDiag(diag);
}

// Constructor: initialize members with provided parameters
SourceMgrAdapter::SourceMgrAdapter(SourceManager &srcMgr,
                                   DiagnosticsEngine &diag,
                                   unsigned errorDiagID,
                                   unsigned warningDiagID,
                                   unsigned noteDiagID,
                                   const FileEntry *defaultFile)
    : SrcMgr(srcMgr), Diag(diag), ErrorDiagID(errorDiagID),
      WarningDiagID(warningDiagID), NoteDiagID(noteDiagID),
      DefaultFile(defaultFile) { }

// Destructor
SourceMgrAdapter::~SourceMgrAdapter() { }

// Map an LLVM source location to Clang's SourceLocation
SourceLocation SourceMgrAdapter::mapLocation(const llvm::SourceMgr &llvmSrcMgr,
                                             llvm::SMLoc loc) {
    // Handle invalid locations
    if (!loc.isValid())
        return SourceLocation();

    // Find the buffer containing the location
    unsigned bufferID = llvmSrcMgr.FindBufferContainingLoc(loc);
    if (!bufferID)
        return SourceLocation();

    // Get the memory buffer
    auto buffer = llvmSrcMgr.getMemoryBuffer(bufferID);

    // Check if we've already mapped this buffer
    auto knownBuffer = FileIDMapping.find(std::make_pair(&llvmSrcMgr, bufferID));
    if (knownBuffer == FileIDMapping.end()) {
        FileID fileID;
        if (DefaultFile) {
            // Use default file for mapping
            fileID = SrcMgr.createFileID(DefaultFile, SourceLocation(),
                                         SrcMgr::C_User);
            DefaultFile = nullptr;  // Only do this once
        } else {
            // Create a copy of the memory buffer
            StringRef bufferName = buffer->getBufferIdentifier();
            auto bufferCopy = std::unique_ptr<llvm::MemoryBuffer>(
                llvm::MemoryBuffer::getMemBufferCopy(buffer->getBuffer(), bufferName));

            // Add buffer to Clang's source manager
            fileID = SrcMgr.createFileID(std::move(bufferCopy));
        }

        // Store the mapping
        knownBuffer = FileIDMapping.insert(
            std::make_pair(std::make_pair(&llvmSrcMgr, bufferID), fileID)).first;
    }

    // Compute offset within the buffer and translate to Clang location
    unsigned offset = loc.getPointer() - buffer->getBufferStart();
    return SrcMgr.getLocForStartOfFile(knownBuffer->second).getLocWithOffset(offset);
}

// Map an LLVM source range to Clang's SourceRange
SourceRange SourceMgrAdapter::mapRange(const llvm::SourceMgr &llvmSrcMgr,
                                       llvm::SMRange range) {
    if (!range.isValid())
        return SourceRange();

    SourceLocation start = mapLocation(llvmSrcMgr, range.Start);
    SourceLocation end = mapLocation(llvmSrcMgr, range.End);
    return SourceRange(start, end);
}

// Core diagnostic handler implementation
void SourceMgrAdapter::handleDiag(const llvm::SMDiagnostic &diag) {
    // Map the diagnostic location
    SourceLocation loc;
    if (auto *llvmSrcMgr = diag.getSourceMgr())
        loc = mapLocation(*llvmSrcMgr, diag.getLoc());

    // Extract message text
    StringRef message = diag.getMessage();

    // Determine diagnostic kind and ID
    unsigned diagID;
    switch (diag.getKind()) {
    case llvm::SourceMgr::DK_Error:
        diagID = ErrorDiagID;
        break;
    case llvm::SourceMgr::DK_Warning:
        diagID = WarningDiagID;
        break;
    case llvm::SourceMgr::DK_Note:
        diagID = NoteDiagID;
        break;
    }

    // Report the diagnostic to Clang's diagnostics engine
    DiagnosticBuilder builder = Diag.Report(loc, diagID) << message;

    // Process ranges and fix-its if available
    if (auto *llvmSrcMgr = diag.getSourceMgr()) {
        // Adjust start-of-line for ranges
        SourceLocation startOfLine = loc.getLocWithOffset(-diag.getColumnNo());

        // Add source ranges
        for (auto range : diag.getRanges()) {
            builder << SourceRange(startOfLine.getLocWithOffset(range.first),
                                   startOfLine.getLocWithOffset(range.second));
        }

        // Add fix-it hints
        for (const llvm::SMFixIt &fixIt : diag.getFixIts()) {
            CharSourceRange range(mapRange(*llvmSrcMgr, fixIt.getRange()), false);
            builder << FixItHint::CreateReplacement(range, fixIt.getText());
        }
    }
}

#include <iostream>
#include <cstdlib>
