#include "simdjson/simdjson.h"

// Parse a JSON document found in buf, requires preallocated ParsedJson
WARN_UNUSED
int json_parse(const uint8_t *buf, size_t len, ParsedJson &pj, bool reallocifneeded)
{
    if (pj.bytecapacity < len) {
        return simdjson::CAPACITY;
    }

    bool reallocated = false;

    if (reallocifneeded) {
        // Realloc is needed if the end of the memory crosses a page boundary
#ifdef _MSC_VER
        SYSTEM_INFO sysInfo;
        GetSystemInfo(&sysInfo);
        long pagesize = sysInfo.dwPageSize;
#else
        long pagesize = sysconf(_SC_PAGESIZE);
#endif

        if ((reinterpret_cast<uintptr_t>(buf + len - 1) % pagesize) < SIMDJSON_PADDING) {
            const uint8_t *tmpbuf = buf;
            buf = (uint8_t *)allocate_padded_buffer(len);
            if (buf == NULL) return simdjson::MEMALLOC;
            memcpy((void *)buf, tmpbuf, len);
            reallocated = true;
        }
    }

    // find_structural_bits returns a boolean, not an int; we invert its result to keep consistent with res == 0 meaning success
    int res = !find_structural_bits(buf, len, pj);

    if (!res) {
        res = unified_machine(buf, len, pj);
    }

    if (reallocated) {
        aligned_free((void *)buf);
    }

    return res;
}

WARN_UNUSED
ParsedJson build_parsed_json(const uint8_t *buf, size_t len, bool reallocifneeded)
{
    ParsedJson pj;
    bool ok = pj.allocateCapacity(len);

    if (ok) {
        int res = json_parse(buf, len, pj, reallocifneeded);
        ok = res == simdjson::SUCCESS;
        assert(ok == pj.isValid());
    } else {
        std::cerr << "failure during memory allocation " << std::endl;
    }

    return pj;
}

#include <string>
#include <unordered_map>

class Solution {
public:
    // Public method to check if two strings are isomorphic
    bool isIsomorphic(std::string s, std::string t) 
    {
        return soln_2(s, t);
    }

    // Correct solution using mapping arrays
    bool soln_2(std::string s, std::string t)
    {
        int m1[256] = {0}, m2[256] = {0}, n = s.size();

        for (int i = 0; i < n; ++i) 
        {
            if (m1[s[i]] != m2[t[i]]) 
                return false;

            m1[s[i]] = i + 1; // i+1 because initially we used 0 which would cause issues when index is 0
            m2[t[i]] = i + 1;
        }

        return true;
    }

    // Wrong Solution *-* find the edge cases
    bool soln_1(std::string s, std::string t)
    {
        int n = s.length();
        int m = t.length();

        if(n != m) 
            return false;

        std::unordered_map<char,char> mp;

        for(int i=0; i<n; i++)
        {
            if(mp.find(s[i]) == mp.end() && mp.find(t[i]) == mp.end())
            {
               mp[s[i]] = t[i];
            } 
            else if(mp[s[i]] != t[i])
            {
                return false;
            }
        }

        return true;
    }
};

