// Main function for DG-SWEMV2 MPI-based simulation
int main(int argc, char* argv[])
{
    // Check command line arguments
    if (argc != 2)
    {
        std::cerr << "Usage\n"
                  << "    /path/to/dgswemv2-ompi input_file\n";
        return 1;
    }
    else
    {
        // Start timing
        auto t1 = std::chrono::high_resolution_clock::now();

        // Initialize MPI with thread support
        int provided;
        MPI_Init_thread(&argc, &argv, MPI_THREAD_MULTIPLE, &provided);

        // Verify thread support level
        if (provided != MPI_THREAD_MULTIPLE)
        {
            if (omp_get_max_threads() > 1)
            {
                std::cerr << "dgswemv2 with ompi parallelization was submitted with more than \n"
                          << "1 thread per MPI rank and MPI_THREAD_MULTIPLE is not provided!\n"
                          << "Please either find an MPI implementation that supports MPI_THREAD_MULTIPLE,\n"
                          << " or resubmit the job with one thread per MPI rank and set the\n"
                          << " environment variable OMP_NUM_THREADS=1\n";
                MPI_Abort(MPI_COMM_WORLD, MPI_ERR_OTHER);
                return 1;
            }
        }

#ifdef HAS_PETSC
        // Initialize PETSc if available
        PetscInitialize(&argc, &argv, (char*)nullptr, nullptr);
#endif

        // Process input file
        std::string input_string = std::string(argv[1]);
        std::unique_ptr<OMPISimulationBase> simulation = OMPISimulationFactory::Create(input_string);
        simulation->Run();

        // Synchronize all processes
        MPI_Barrier(MPI_COMM_WORLD);

        // End timing and report elapsed time on root process
        auto t2 = std::chrono::high_resolution_clock::now();
        int locality_id;
        MPI_Comm_rank(MPI_COMM_WORLD, &locality_id);
        if (locality_id == 0)
        {
            std::cout << "Time Elapsed (in us): "
                      << std::chrono::duration_cast<std::chrono::microseconds>(t2 - t1).count() << std::endl;
        }

        // Cleanup
        simulation->Finalize();

#ifdef HAS_PETSC
        // Finalize PETSc if initialized
        PetscFinalize();
#endif

        // Finalize MPI
        MPI_Finalize();
        return 0;
    }
}

#include "ThreadTests.hpp"
#include "Utilities.hpp"
#include "Thread.hpp"

namespace
{
    static Logger tlog;
}

class CustomThread : public gusc::Threads::Thread
{
};

void callableFunction()
{
    tlog << "Callable function thread ID: " + tidToStr(std::this_thread::get_id());
}

class MethodWrapper
{
public:
    void callableMethod()
    {
        tlog << "Callable method thread ID: " + tidToStr(std::this_thread::get_id());
    }
};

struct CallableStruct
{
    void operator()() const
    {
        tlog << "Callable struct thread ID: " + tidToStr(std::this_thread::get_id());
    }
};

static const auto globalConstLambda = [](){
    tlog << "Global const lambda thread ID: " + tidToStr(std::this_thread::get_id());
};

static auto globalLambda = [](){
    tlog << "Global lambda thread ID: " + tidToStr(std::this_thread::get_id());
};

void runThreadTests()
{
    tlog << "Thread Tests";

    gusc::Threads::ThisThread mt;
    gusc::Threads::Thread t1;
    CustomThread t2;

    tlog << "Main thread ID: " + tidToStr(std::this_thread::get_id());

    // Test function
    callableFunction();
    mt.send(&callableFunction);
    t1.send(&callableFunction);
    t2.send(&callableFunction);

    // Test object method
    MethodWrapper o;
    o.callableMethod();
    mt.send(std::bind(&MethodWrapper::callableMethod, &o));
    t1.send(std::bind(&MethodWrapper::callableMethod, &o));
    t2.send(std::bind(&MethodWrapper::callableMethod, &o));

    // Test callable struct
    const CallableStruct cb;
    cb();
    mt.send(cb);
    t1.send(cb);
    t2.send(cb);

    // Test callable struct temporary
    mt.send(CallableStruct{});
    t1.send(CallableStruct{});
    t2.send(CallableStruct{});

    // Test local lambda
    auto localLambda = [](){
        tlog << "Local lambda thread ID: " + tidToStr(std::this_thread::get_id());
    };
    localLambda();
    mt.send(localLambda);
    t1.send(localLambda);
    t2.send(localLambda);

    // Test global lambda
    globalLambda();
    mt.send(globalLambda);
    t1.send(globalLambda);
    t2.send(globalLambda);

    // Test global const lambda
    globalConstLambda();
    mt.send(globalConstLambda);
    t1.send(globalConstLambda);
    t2.send(globalConstLambda);

    // Test anonymous lambda
    mt.send([](){
        tlog << "Anonymous lambda thread ID: " + tidToStr(std::this_thread::get_id());
    });
    t1.send([](){
        tlog << "Anonymous lambda thread ID: " + tidToStr(std::this_thread::get_id());
    });
    t2.send([](){
        tlog << "Anonymous lambda thread ID: " + tidToStr(std::this_thread::get_id());
    });

    // Signal main thread to quit (this effectivelly stops processing all the messages)
    mt.stop();

    // Start all threads and main run-loop
    t1.start();
    t2.start();
    mt.start();
}

#include <gtest/gtest.h>
#include "ocs2_sqp/MultipleShootingSolver.h"
#include <ocs2_core/initialization/DefaultInitializer.h>
#include <ocs2_oc/test/circular_kinematics.h>

// Test case 1: Solve with projected equality constraints
TEST(test_circular_kinematics, solve_projected_EqConstraints) {
    // optimal control problem
    ocs2::OptimalControlProblem problem = ocs2::createCircularKinematicsProblem("/tmp/sqp_test_generated");

    // Initializer
    ocs2::DefaultInitializer zeroInitializer(2);

    // Solver settings
    ocs2::multiple_shooting::Settings settings;
    settings.dt = 0.01;
    settings.sqpIteration = 20;
    settings.projectStateInputEqualityConstraints = true;
    settings.useFeedbackPolicy = true;
    settings.printSolverStatistics = true;
    settings.printSolverStatus = true;
    settings.printLinesearch = true;
    settings.nThreads = 1;

    // Additional problem definitions
    const ocs2::scalar_t startTime = 0.0;
    const ocs2::scalar_t finalTime = 1.0;
    const ocs2::vector_t initState = (ocs2::vector_t(2) << 1.0, 0.0).finished();  // radius 1.0
    const ocs2::scalar_array_t partitioningTimes{0.0};                            // doesn't matter

    // Solve
    ocs2::MultipleShootingSolver solver(settings, problem, zeroInitializer);
    solver.run(startTime, initState, finalTime, partitioningTimes);

    // Inspect solution
    const auto primalSolution = solver.primalSolution(finalTime);
    for (int i = 0; i < primalSolution.timeTrajectory_.size(); i++) {
        std::cout << "time: " << primalSolution.timeTrajectory_[i] 
                  << "\t state: " << primalSolution.stateTrajectory_[i].transpose()
                  << "\t input: " << primalSolution.inputTrajectory_[i].transpose() 
                  << std::endl;
    }

    // Check initial condition
    ASSERT_TRUE(primalSolution.stateTrajectory_.front().isApprox(initState));
    ASSERT_DOUBLE_EQ(primalSolution.timeTrajectory_.front(), startTime);
    ASSERT_DOUBLE_EQ(primalSolution.timeTrajectory_.back(), finalTime);

    // Check constraint satisfaction.
    const auto performance = solver.getPerformanceIndeces();
    ASSERT_LT(performance.stateEqConstraintISE, 1e-6);
    ASSERT_LT(performance.stateInputEqConstraintISE, 1e-6);

    // Check feedback controller
    for (int i = 0; i < primalSolution.timeTrajectory_.size() - 1; i++) {
        const auto t = primalSolution.timeTrajectory_[i];
        const auto& x = primalSolution.stateTrajectory_[i];
        const auto& u = primalSolution.inputTrajectory_[i];
        // Feed forward part
        ASSERT_TRUE(u.isApprox(primalSolution.controllerPtr_->computeInput(t, x)));
    }
}

