namespace mms {

QTextStream* Logging::STDOUT = nullptr;

// Initialize logging system
void Logging::init()
{
    ASSERT_TR(STDOUT == nullptr);
    STDOUT = new QTextStream(stdout);
    qInstallMessageHandler(handler);
}

// Message handler for Qt logging
void Logging::handler(
        QtMsgType type,
        const QMessageLogContext& context,
        const QString& msg)
{
    ASSERT_FA(STDOUT == nullptr);

    // Mapping from Qt message types to string representations
    static const QMap<QtMsgType, QString> mapping {
        {QtDebugMsg,    "DEBUG"   },
        {QtInfoMsg,     "INFO"    },
        {QtWarningMsg,  "WARN"    },
        {QtCriticalMsg, "CRITICAL"},
        {QtFatalMsg,    "FATAL"   },
    };

    // Format the log message
    QString formatted = QString("[%1][%2:%3] - %4").arg(
        mapping.value(type),
        context.file,
        QString::number(context.line),
        msg
    );

    *STDOUT << formatted << endl;
}

