// Converts global integers to local variables in main function
void global_int_to_local(CompileUnit &c)
{
    std::unordered_map<MemObject *, MemObject *> S;

    // Collect single-variable global memobjects
    c.scope.for_each([&](MemObject *m) {
        if (m->is_single_var()) {
            S[m] = NULL;
        }
    });

    // Remove globals that are referenced via LoadAddr in non-main functions
    c.for_each([&](NormalFunc *f) {
        if (f->name != "main") {
            f->for_each([&](Instr *i) {
                Case(LoadAddr, i0, i) {
                    auto m = i0->offset;
                    if (m->global) S.erase(m);
                }
            });
        }
    });

    // Create new local memobjects for remaining globals in main
    NormalFunc *main = c.funcs["main"].get();
    for (auto &kv : S) {
        kv.second = main->scope.new_MemObject(kv.first->name);
        kv.second->size = 4;
    }

    // Replace references to global memobjects with local ones in main
    main->for_each([&](Instr *i) {
        Case(LoadAddr, i0, i) {
            auto &m = i0->offset;
