#include <vector>
#include <algorithm>

// First solution using DP arrays
class Solution {
public:
    int maxProduct(std::vector<int>& nums) {
        int len = nums.size();
        if (len == 1) return nums[0];

        std::vector<int> dpmax(len, 0);
        std::vector<int> dpmin(len, 0);

        int res = nums[0];
        dpmax[0] = nums[0];
        dpmin[0] = nums[0];

        for (int i = 1; i < len; ++i) {
            dpmax[i] = std::max(std::max(dpmax[i - 1] * nums[i], dpmin[i - 1] * nums[i]), nums[i]);
            dpmin[i] = std::min(std::min(dpmax[i - 1] * nums[i], dpmin[i - 1] * nums[i]), nums[i]);
            res = std::max(res, dpmax[i]);
        }

        return res;
    }
};

// Second solution with optimized space complexity
class Solution {
public:
    int maxProduct(std::vector<int>& nums) {
        int len = nums.size();
        if (len == 1) return nums[0];

        int res = nums[0];
        int dpmax = nums[0];
        int dpmin = nums[0];
        int mmax;
        int mmin;

        for (int i = 1; i < len; ++i) {
            mmax = std::max(std::max(dpmax * nums[i], dpmin * nums[i]), nums[i]);
            mmin = std::min(std::min(dpmax * nums[i], dpmin * nums[i]), nums[i]);

            dpmax = mmax;
            dpmin = mmin;

            res = std::max(res, mmax);
        }

        return res;
    }
};

#include "EnginePrivate.h"
#include "DebugRenderSceneProxy.h"
