#include "profile.hpp"
#include "../../utils/utils.hpp"
#include <cerrno>

// Main function to process profile and output SMT-LIB-like code
int main(int argc, const char *argv[])
{
    // Check argument count
    if (argc != 2)
        fatal("usage: sptcounts <profile>");

    // Open the profile file
    FILE *f = fopen(argv[1], "r");
    if (!f)
        fatalx(errno, "failed to open %s for reading", argv[1]);

    // Load profile from file
    AnytimeProfile prof(f);
    fclose(f);

    // Output SMT-LIB structure
    puts("(let* (");
    puts("	(sols (");

    // Iterate over time and cost dimensions
    for (unsigned int q = 0; q < prof.ncost; q++) {
        for (unsigned int t = 0; t < prof.ntime; t++) {
            printf("\t\t(%u %u %u)\n", t, q, prof.qtcount(q, t));
        }
    }

    puts("	))");
    puts("	(heatmap (heatmap-dataset");
    puts("		:bin-size (1 1)");
    puts("		:triples sols))");
    puts("	(plot (num-by-num-plot");
    puts("		:x-label \"time\"");
    puts("		:y-label \"cost\"");
    puts("		:dataset heatmap)))");
    puts("	(display plot))");

    return 0;
}

