// Fibonacci function definition
int fib(int n)
{
    if (n == 1)
        return 0;
    if (n == 2)
        return 1;
    return fib(n - 1) + fib(n - 2);
}

// Factorial function definition
int factorial(int n)
{
    cout << n << endl;
    if (n <= 0)
        return 1;
    else
        return n * factorial(n - 1);
}

int main()
{
    int x = factorial(4);
    cout << x << endl;
    x = fib(6);
    cout << x << endl;
    return 0;
}

