#include "mex.h"

// Use squared distance for KDTree
#define KDTREE_USE_SQUARED_DISTANCE

#include <kdtree++/kdtree.hpp>
#include <stdlib.h>
#include <list>
#include <set>

// Point structure with ID and 2D coordinates
struct Pnt {
    int id;
    double coord[2];

    // Equality operator for point comparison
    bool operator==(const Pnt& other) const {
        return id == other.id && coord[0] == other.coord[0] && coord[1] == other.coord[1];
    }
};

// Helper function to extract coordinate for KDTree
inline double tac2(Pnt t, size_t k) { 
    return t.coord[k]; 
}

// Define KDTree type for 2D points
typedef KDTree::KDTree<2, Pnt, std::pointer_to_binary_function<Pnt,size_t,double> > tree_type2;

// Structure representing a 2D double vector (for compatibility)
typedef struct {
    double x;
    double y;
} double2;

// Match structure to store distances and indices
struct Match {
    double d;
    int A;
    int B;
};

// Comparator for multiset: smaller distance has higher priority
struct Comparator {
    bool operator()(const Match& lhs, const Match& rhs) {
        return lhs.d > rhs.d;
    }
};

/* Computes squared Euclidean distance between two points */
inline static double double2_dist2(double2* A, double2* B) {
    return (A->x - B->x) * (A->x - B->x) + (A->y - B->y) * (A->y - B->y);
}

void doWork(double2* Adata, double2* Bdata, int N, int* cdata)
{
    // Construct KD-tree for points in B
    tree_type2 Btree(std::ptr_fun(tac2));

    // Insert all points from B into the tree
    for (int i = 0; i < N; ++i) {
        Pnt p = {i, Bdata[i].x, Bdata[i].y};
        Btree.insert(p);
    }

    // Optimize (balance) the tree
    Btree.optimise();

    // Multiset to store matches sorted by distance
    std::multiset<Match, Comparator> Aset;

    // List of incoming matches at each point in B
    std::vector<std::list<int>> Blist(N);

    // First step: assign each point in A to its nearest neighbor in B
    for (int i = 0; i < N; ++i) {
        Pnt query = {-1, Adata[i].x, Adata[i].y};
        std::pair<tree_type2::const_iterator, double> found = Btree.find_nearest(query);

        if (found.first != Btree.end()) {
            Match m = {found.second, i, found.first->id};
            Aset.insert(m);
            Blist[m.B].push_back(m.A);
        } else {
            mexErrMsgIdAndTxt("pmRefinement:initMatch", "Couldn't find initial match.");
            return;
        }
    }

    // Iteratively resolve conflicts until all points are matched
    while (!Aset.empty()) {
        // Get the match with largest distance (first element due to comparator)
        Match m = *Aset.begin();

        // Store final assignment
        cdata[m.A] = m.B;

        // Remove this match from candidate set
        Aset.erase(m);

        // Remove matched point from B from the tree
        Pnt pntB = {m.B, Bdata[m.B].x, Bdata[m.B].y};
        Btree.erase_exact(pntB);

        // Update other candidates that previously matched to same B point
        if (Blist[m.B].size() > 1) {
            for (auto it = Blist[m.B].begin(); it != Blist[m.B].end(); ++it) {
                int a = *it;

                // Skip the already-assigned point
                if (a != m.A) {
                    // Re-query nearest neighbor for this point
                    Pnt query = {-1, Adata[a].x, Adata[a].y};
                    std::pair<tree_type2::const_iterator, double> found = Btree.find_nearest(query);

                    int cc = found.first->id;   // new closest match index
                    double dd = found.second;   // new squared distance

                    // Remove old match from set
                    double dist = double2_dist2(&Adata[a], &Bdata[m.B]);
                    Match md = {dist, a, m.B};
                    Aset.erase(md);

                    // Add updated match
                    md.B = cc;
                    md.d = dd;
                    Aset.insert(md);

                    // Record new incoming link at new B node
                    Blist[md.B].push_back(md.A);
                }
            }
        }

        // Clear list for processed B node
        Blist[m.B].clear();
    }
}

// MEX function entry point
void mexFunction(int nlhs, mxArray *plhs[], int nrhs, const mxArray *prhs[])
{
    double2 *setA, *setB;
    int nOfRowsA, nOfColumnsA, nOfRowsB, nOfColumnsB;
    int* p;

    // Check input/output arguments
    if (nrhs != 2) {
        mexErrMsgIdAndTxt("pmRefinement:nrhs", "Two inputs required.");
        return;
    }
    if (nlhs != 1) {
        mexErrMsgIdAndTxt("pmRefinement:nlhs", "One output required.");
        return;
    }

    // Get dimensions and data pointers for input matrices
    nOfRowsA    = (int)mxGetM(prhs[0]);  // Should be 2
    nOfColumnsA = (int)mxGetN(prhs[0]);  // Number of points N
    setA = (double2*)mxGetPr(prhs[0]);

    nOfRowsB    = (int)mxGetM(prhs[1]);  // Should be 2
    nOfColumnsB = (int)mxGetN(prhs[1]);  // Number of points N
    setB = (double2*)mxGetPr(prhs[1]);

    // Validate input sizes
    if (nOfRowsA != nOfRowsB || nOfColumnsA != nOfColumnsB) {
        mexErrMsgIdAndTxt("pmRefinement:prhs", "Input matrices of different size.");
        return;
    }
    if (nOfRowsA != 2) {
        mexErrMsgIdAndTxt("pmRefinement:prhs", "Points must be 2D.");
        return;
    }

    // Create output array
    plhs[0] = mxCreateNumericMatrix(1, nOfColumnsA, mxINT32_CLASS, mxREAL);
    p = (int*)mxGetData(plhs[0]);

    // Perform matching
    doWork(setA, setB, nOfColumnsA, p);

    // Adjust indices for MATLAB (1-based indexing)
    for (int i = 0; i < nOfColumnsA; ++i)
        p[i] += 1;
}

