#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    // Finds the longest common prefix among a vector of strings
    string longestCommonPrefix(vector<string>& strs) {
        // Handle edge cases: empty input or single string
        if (strs.size() == 0) return "";
        if (strs.size() < 2) return strs[0];

        // Check for any empty strings in the input
        for (auto str : strs) if (str.size() == 0) return "";

        // Find common prefix between first two strings
        int index = -1;
        while (strs[0][index + 1] == strs[1][index + 1]) {
            index++;
        }

        // If no common prefix found, return empty string
        if (index < 0) return "";

        // Compare with remaining strings to refine the common prefix
        for (int i = 2; i < strs.size(); ++i) {
            // Adjust index if current string is shorter than current prefix length
            if (strs[i].size() - 1 < index) index = strs[i].size() - 1;

            // Reduce prefix length until it matches current string
            while (strs[i][index] != strs[i - 1][index]) {
                index--;
                if (index < 0) return "";
            }
        }

        // Return the common prefix substring
        return strs[0].substr(0, index + 1);
    }
};

