        case GL_RGBA8_SNORM:
        case GL_RGBA16:
        case GL_RGBA16I:
        case GL_RGBA16UI:
        case GL_RGBA16F:
        case GL_RGBA16_SNORM:
        case GL_RGBA32I:
        case GL_RGBA32UI:
        case GL_RGBA32F:
            return Image::DataFormat::RGBA;
    }
    // should never be reached, maybe new channel formats were added?
    throw std::runtime_error("ERROR: glEnumToImageDataFormat(): Unknown GL channel format");
