// Constants
const uint16_t kSymphonyZeroMark = 400;
const uint16_t kSymphonyZeroSpace = 1250;
const uint16_t kSymphonyOneMark = kSymphonyZeroSpace;
const uint16_t kSymphonyOneSpace = kSymphonyZeroMark;
const uint32_t kSymphonyFooterGap = 4 * (kSymphonyZeroMark +
                                         kSymphonyZeroSpace);

#if SEND_SYMPHONY

/// Send a Symphony packet.
/// Status:  STABLE / Should be working.
/// @param[in] data The message to be sent.
/// @param[in] nbits The number of bits of message to be sent.
/// @param[in] repeat The number of times the command is to be repeated.
void IRsend::sendSymphony(uint64_t data, uint16_t nbits, uint16_t repeat)
{
    sendGeneric(0, 0,
                kSymphonyOneMark, kSymphonyOneSpace,
                kSymphonyZeroMark, kSymphonyZeroSpace,
                0, kSymphonyFooterGap,
                data, nbits, 38000, true, repeat, kDutyDefault);
}

#endif  // SEND_SYMPHONY

#if DECODE_SYMPHONY

/// Decode the supplied Symphony packet/message.
/// Status: STABLE / Should be working.
/// @param[in,out] results Ptr to the data to decode & where to store the result
/// @param[in] offset The starting index to use when attempting to decode the
///   raw data. Typically/Defaults to kStartOffset.
/// @param[in] nbits The number of data bits to expect.
/// @param[in] strict Flag indicating if we should perform strict matching.
/// @return True if it can decode it, false if it can't.
bool IRrecv::decodeSymphony(decode_results *results, uint16_t offset,
                            const uint16_t nbits, const bool strict)
{
    uint64_t data = 0;

    if(results->rawlen < 2*nbits + offset - 1)
        return false;  // Not enough entries to ever be SYMPHONY.

    // Compliance
    if(strict && nbits != kSymphonyBits) return false;

    if(!matchGenericConstBitTime(results->rawbuf + offset, &data,
                                 results->rawlen - offset,
                                 nbits,
                                 0, 0,  // No Header
                                 kSymphonyOneMark, kSymphonyZeroMark,
                                 0, kSymphonyFooterGap, true,
                                 _tolerance, 0))
        return false;

    // Success
    results->value = data;
    results->decode_type = decode_type_t::SYMPHONY;
    results->bits = nbits;
    results->address = 0;
    results->command = 0;

    return true;
}

#endif  // DECODE_SYMPHONY

#ifdef SJTU_AUXTREE_HPP
#ifndef SJTU_AUXTREE_CPP
#define SJTU_AUXTREE_CPP

// pay attention to srand(time(NULL)) !!!
template<class T, class A, class M>
void AuxTree<T, A, M>::LL(AuxNode<T, A, M>* &t)
{
    AuxNode<T, A, M>* k = t->child[1];
    k->pushTagTree();
    t->child[1] = k->child[0];
    k->child[0] = t;
    t->update();
    k->update();
    t = k;
}

template<class T, class A, class M>
void AuxTree<T, A, M>::RR(AuxNode<T, A, M>* &t)
{
    AuxNode<T, A, M>* k = t->child[0];
    k->pushTagTree();
    t->child[0] = k->child[1];
    k->child[1] = t;
    t->update();
    k->update();
    t = k;
}

template<class T, class A, class M>
AuxNode<T, A, M>* AuxTree<T, A, M>::Treap_find(const int &key, AuxNode<T, A, M>* t)
{
    if(t == NULL) return NULL;
    t->pushTagTree();
    if(key < (t->data->id))
        return Treap_find(key, t->child[0]);
    else if(key > (t->data->id))
        return Treap_find(key, t->child[1]);
    else
        return t;
}

template<class T, class A, class M>
AuxNode<T, A, M>* AuxTree<T, A, M>::find(const AuxNode<T, A, M> &rhs)
{
    int Key = rhs.data->id;
    return Treap_find(Key, root);
}

template<class T, class A, class M>
void AuxTree<T, A, M>::Treap_Insert(const AuxNode<T, A, M> &rhs, AuxNode<T, A, M>* &t)
{
    if(t == NULL)
    {
        t = new AuxNode<T, A, M>(rhs.data, rand());
        t->update();
        return;
    }
    t->pushTagTree();
    if(rhs.data->id < (t->data->id))
    {
        Treap_Insert(rhs, t->child[0]);
        if((t->child[0]->getrand()) < (t->getrand()))
            RR(t);
    }
    else
    {
        Treap_Insert(rhs, t->child[1]);
        if((t->child[1]->getrand()) < (t->getrand()))
            LL(t);
    }
    t->update();
}

template<class T, class A, class M>
void AuxTree<T, A, M>::insert(const AuxNode<T, A, M> &rhs)
{
    if(find(rhs) != NULL) throw "This ID exist!";
    Treap_Insert(rhs, root);
}

template<class T, class A, class M>
void AuxTree<T, A, M>::Treap_Delete(const AuxNode<T, A, M> &rhs, AuxNode<T, A, M>* &t)
{
    t->pushTagTree();
    if((t->data->id) == (rhs.data->id))
    {
        if(t->child[0] == NULL || t->child[1] == NULL)
        {
            AuxNode<T, A, M>* k = t;
            if(t->child[0] != NULL)
                t = t->child[0];
            else
                t = t->child[1];
            delete k;
        }
        else
        {
            if((t->child[0]->getrand()) < (t->child[1]->getrand()))
            {
                RR(t);
                Treap_Delete(rhs, t->child[1]);
                t->update();
            }
            else
            {
                LL(t);
                Treap_Delete(rhs, t->child[0]);
                t->update();
            }
        }
        return;
    }
    if((rhs.data->id) < (t->data->id))
        Treap_Delete(rhs, t->child[0]);
    else
        Treap_Delete(rhs, t->child[1]);
    t->update();
}

template<class T, class A, class M>
void AuxTree<T, A, M>::erase(const AuxNode<T, A, M> &rhs)
{
    if(find(rhs) == NULL) throw "This ID doesn't exist!";
    Treap_Delete(rhs, root);
}

template<class T, class A, class M>
void AuxTree<T, A, M>::Treap_Clear(const AuxNode<T, A, M>* t)
{
    if(t->child[0] != NULL) Treap_Clear(t->child[0]);
    if(t->child[1] != NULL) Treap_Clear(t->child[1]);
    delete t;
}
