// Solution class for maximum events problem
class Solution {
public:
    int maxEvents(std::vector<std::vector<int>>& events) {
        // Sort events by end day
        std::sort(begin(events), end(events), [](const auto& a, const auto& b) {
            return a[1] < b[1];
        });

        // Find minimum start day and maximum end day
        int max_d = INT_MIN;
        int min_d = INT_MAX;

        for (const auto &e : events) {
            min_d = std::min(min_d, e[0]);
            max_d = std::max(max_d, e[1]);
        }

        // Create set of available days
        std::vector<int> days(max_d - min_d + 1);
        std::iota(begin(days), end(days), min_d);
        std::set<int> s(begin(days), end(days));

        int ans = 0;

        // Process each event
        for (auto &e : events) {
            auto it = s.lower_bound(e[0]);
            if (it == s.end() || *it > e[1]) continue;
            s.erase(it);
            ++ans;
        }

        return ans;
    }
};

