// Converts remote path to use forward slashes
String remotePath(TCchar* path)
{
    String s = path;
    int    n = s.length();
    int    i;
    for (i = 0; i < n; i++) if (s[i] == _T('\\')) s[i] = _T('/');
    return s;
}

// Converts local path to use backslashes
String localPath(TCchar* path)
{
    String s = path;
    int    n = s.length();
    int    i;
    for (i = 0; i < n; i++) if (s[i] == _T('/')) s[i] = _T('\\');
    return s;
}

// Extracts the file name from a path
String parseName(TCchar* path)
{
    String s   = path;
    int    pos = s.findLastOf(_T('\\'));   if (pos < 0) return s;
    return s.substr(pos + 1);
}

// Ensures root path ends with a backslash
void fixRootPath(String& root)
{
    if (root[root.length() - 1] != _T('\\')) root += _T('\\');
}

#include "ozz/animation/runtime/skeleton_utils.h"
