// Unpacks skeleton bind pose stored in soa format by the skeleton.
ozz::math::Transform GetJointLocalBindPose(const Skeleton& _skeleton,
                                           int _joint) {
  assert(_joint >= 0 && _joint < _skeleton.num_joints() &&
         "Joint index out of range.");

  const ozz::math::SoaTransform& soa_transform =
      _skeleton.bind_pose()[_joint / 4];

  // Transpose SoA data to AoS.
  ozz::math::SimdFloat4 translations[4];
  ozz::math::Transpose3x4(&soa_transform.translation.x, translations);

  ozz::math::SimdFloat4 rotations[4];
  ozz::math::Transpose4x4(&soa_transform.rotation.x, rotations);

  ozz::math::SimdFloat4 scales[4];
  ozz::math::Transpose3x4(&soa_transform.scale.x, scales);

  // Stores to the Transform object.
  math::Transform bind_pose;
  const int offset = _joint % 4;

  ozz::math::Store3PtrU(translations[offset], &bind_pose.translation.x);
  ozz::math::StorePtrU(rotations[offset], &bind_pose.rotation.x);
  ozz::math::Store3PtrU(scales[offset], &bind_pose.scale.x);

  return bind_pose;
}

// Helper macro used to detect if a joint has a brother.
#define _HAS_SIBLING(_i, _num_joints, _properties) \
  ((_i + 1 < _num_joints) &&                       \
   (_properties[_i].parent == _properties[_i + 1].parent))

// Implement joint hierarchy depth-first traversal.
// Uses a non-recursive implementation to control stack usage (ie: making
// algorithm behavior (stack consumption) independent off the data being
// processed).
void IterateJointsDF(const Skeleton& _skeleton, int _from,
                     JointsIterator* _iterator) {
  assert(_iterator);

  const int num_joints = _skeleton.num_joints();
  Range<const Skeleton::JointProperties> properties =
      _skeleton.joint_properties();

  // Initialize iterator.
  _iterator->num_joints = 0;

  // Validates input range first.
  if (num_joints == 0) {
    return;
  }

  if ((_from < 0 || _from >= num_joints) && _from != Skeleton::kNoParentIndex) {
    return;
  }

  // Simulate a stack to unroll usual recursive implementation.
  struct Context {
    uint16_t joint : 15;
    uint16_t has_brother : 1;
  };

  Context stack[Skeleton::kMaxJoints];
  int stack_size = 0;

  // Initializes iteration start.
  Context start;
  if (_from != Skeleton::kNoParentIndex) {
    start.joint = _from;
    start.has_brother = false;  // Disallow brother processing.
  } else {  // num_joints > 0, which was tested as pre-conditions.
    start.joint = 0;
    start.has_brother = _HAS_SIBLING(0, num_joints, properties.begin);
  }

  stack[stack_size++] = start;

  for (; stack_size != 0;) {
    // Process next joint on the stack.
    const Context& top = stack[stack_size - 1];

    // Push that joint to the list and then process its child.
    _iterator->joints[_iterator->num_joints++] = top.joint;

    // Skip all the joints until the first child is found.
    if (!properties.begin[top.joint].is_leaf) {  // A leaf has no child anyway.
      uint16_t next_joint = top.joint + 1;
      for (; next_joint < num_joints &&
             top.joint != properties.begin[next_joint].parent;
           ++next_joint) {
      }

      if (next_joint < num_joints) {
        Context& next = stack[stack_size++];  // Push child and process it.
        next.joint = next_joint;
        next.has_brother =
            _HAS_SIBLING(next_joint, num_joints, properties.begin);
        continue;
      }
    }

    // Rewind the stack while there's no brother to process.
    for (; stack_size != 0 && !stack[stack_size - 1].has_brother;
         --stack_size) {
    }

    // Replace top joint by its brother.
    if (stack_size != 0) {
      Context& next = stack[stack_size - 1];
      assert(next.has_brother && next.joint + 1 < num_joints);
      ++next.joint;  // The brother is the next joint in breadth-first order.
      next.has_brother = _HAS_SIBLING(next.joint, num_joints, properties.begin);
    }
  }
}

#undef _HAS_SIBLING

}  // namespace animation
}  // namespace ozz

#include "Transforms/MultiTransformer.h"

// Setup the multi-transformer with required managers and providers
void UMultiTransformer::Setup(UInteractiveGizmoManager* GizmoManagerIn, IToolContextTransactionProvider* TransactionProviderIn)
{
	GizmoManager = GizmoManagerIn;
	TransactionProvider = TransactionProviderIn;

	ActiveGizmoFrame = FFrame3d();
	ActiveGizmoScale = FVector3d::One();
	ActiveMode = EMultiTransformerMode::DefaultGizmo;

	// Create a new TransformGizmo and associated TransformProxy. The TransformProxy will not be the
	// parent of any Components in this case, we just use its transform and change delegate.
	TransformProxy = NewObject<UTransformProxy>(this);
	TransformProxy->SetTransform(ActiveGizmoFrame.ToFTransform());

	UpdateShowGizmoState(true);

	// listen for changes to the proxy and update the transform frame when that happens
	TransformProxy->OnTransformChanged.AddUObject(this, &UMultiTransformer::OnProxyTransformChanged);
	TransformProxy->OnBeginTransformEdit.AddUObject(this, &UMultiTransformer::OnBeginProxyTransformEdit);
	TransformProxy->OnEndTransformEdit.AddUObject(this, &UMultiTransformer::OnEndProxyTransformEdit);
}

// Clean up resources and destroy gizmos
void UMultiTransformer::Shutdown()
{
	GizmoManager->DestroyAllGizmosByOwner(this);
}

// Set override coordinate system for gizmo
void UMultiTransformer::SetOverrideGizmoCoordinateSystem(EToolContextCoordinateSystem CoordSystem)
{
	if (GizmoCoordSystem != CoordSystem || bForceGizmoCoordSystem == false)
	{
		bForceGizmoCoordSystem = true;
		GizmoCoordSystem = CoordSystem;

		if (TransformGizmo != nullptr)
		{
			UpdateShowGizmoState(false);
			UpdateShowGizmoState(true);
		}
	}
}

// Configure which sub-elements of the gizmo are enabled
void UMultiTransformer::SetEnabledGizmoSubElements(ETransformGizmoSubElements EnabledSubElements)
{
	if (ActiveGizmoSubElements != EnabledSubElements)
	{
		ActiveGizmoSubElements = EnabledSubElements;

		if (TransformGizmo != nullptr)
		{
			UpdateShowGizmoState(false);
			UpdateShowGizmoState(true);
		}
	}
}

// Change active mode of the transformer
void UMultiTransformer::SetMode(EMultiTransformerMode NewMode)
{
	if (NewMode != ActiveMode)
	{
		if (NewMode == EMultiTransformerMode::DefaultGizmo)
		{
			UpdateShowGizmoState(true);
		}
		else
		{
			UpdateShowGizmoState(false);
		}
		ActiveMode = NewMode;
	}
}

// Control visibility of the gizmo
void UMultiTransformer::SetGizmoVisibility(bool bVisible)
{
	if (bShouldBeVisible != bVisible)
	{
		bShouldBeVisible = bVisible;

		if (TransformGizmo != nullptr)
		{
			TransformGizmo->SetVisibility(bVisible);
		}
	}
}

// Set function for world grid snapping
void UMultiTransformer::SetSnapToWorldGridSourceFunc(TUniqueFunction<bool()> EnableSnapFunc)
{
	EnableSnapToWorldGridFunc = MoveTemp(EnableSnapFunc);
}

// Tick update for gizmo behavior
void UMultiTransformer::Tick(float DeltaTime)
{
	if (TransformGizmo != nullptr)
	{
		// todo this
		TransformGizmo->bSnapToWorldGrid =
			(EnableSnapToWorldGridFunc) ? EnableSnapToWorldGridFunc() : false;
	}
}

// Initialize gizmo position from world frame
void UMultiTransformer::InitializeGizmoPositionFromWorldFrame(const FFrame3d& Frame, bool bResetScale)
{
	ActiveGizmoFrame = Frame;

	if (bResetScale)
	{
		ActiveGizmoScale = FVector3d::One();
	}

	if (TransformGizmo != nullptr)
	{
		// this resets the child scale to one
		TransformGizmo->ReinitializeGizmoTransform(ActiveGizmoFrame.ToFTransform());
	}
}

// Update gizmo position from world frame
void UMultiTransformer::UpdateGizmoPositionFromWorldFrame(const FFrame3d& Frame, bool bResetScale)
{
	ActiveGizmoFrame = Frame;

	if (bResetScale)
	{
		ActiveGizmoScale = FVector3d::One();
	}

	if (TransformGizmo != nullptr)
	{
		// this resets the child scale to one
		TransformGizmo->SetNewGizmoTransform(ActiveGizmoFrame.ToFTransform());
	}
}

// Reset gizmo scale to default
void UMultiTransformer::ResetScale()
{
	ActiveGizmoScale = FVector3d::One();

	if (TransformGizmo != nullptr)
	{
		TransformGizmo->SetNewChildScale(FVector::OneVector);
	}
}

// Handle proxy transform change event
void UMultiTransformer::OnProxyTransformChanged(UTransformProxy* Proxy, FTransform Transform)
{
	ActiveGizmoFrame = FFrame3d(Transform);
	ActiveGizmoScale = FVector3d(Transform.GetScale3D());
	OnTransformUpdated.Broadcast();
}

// Begin transform edit callback
void UMultiTransformer::OnBeginProxyTransformEdit(UTransformProxy* Proxy)
{
	bInGizmoEdit = true;
	OnTransformStarted.Broadcast();
}

// End transform edit callback
void UMultiTransformer::OnEndProxyTransformEdit(UTransformProxy* Proxy)
{
	bInGizmoEdit = false;
	OnTransformCompleted.Broadcast();
}

// Internal helper to show/hide gizmo
void UMultiTransformer::UpdateShowGizmoState(bool bNewVisibility)
{
	if (bNewVisibility == false)
	{
		GizmoManager->DestroyAllGizmosByOwner(this);
		TransformGizmo = nullptr;
	}
	else
	{
		check(TransformGizmo == nullptr);

		TransformGizmo = GizmoManager->CreateCustomTransformGizmo(ActiveGizmoSubElements, this);

		if (bForceGizmoCoordSystem)
		{
			TransformGizmo->bUseContextCoordinateSystem = false;
			TransformGizmo->CurrentCoordinateSystem = GizmoCoordSystem;
		}

		TransformGizmo->SetActiveTarget(TransformProxy, TransactionProvider);
		TransformGizmo->ReinitializeGizmoTransform(ActiveGizmoFrame.ToFTransform());
		TransformGizmo->SetVisibility(bShouldBeVisible);
	}
}

