#include <qdebug.h>
#include "quirc/quirc_internal.h"

// Constructor
QrDecoder::QrDecoder()
    : m_qr(quirc_new())
{
}

// Destructor
QrDecoder::~QrDecoder()
{
    quirc_destroy(m_qr);
}

// Decode QR codes from image
QVector<QString> QrDecoder::decode(const QImage &image)
{
    QVector<QString> result;

    // Check if QR context is valid
    if (m_qr == nullptr)
    {
        return result;
    }

    // Resize QR context to match image dimensions
    if (quirc_resize(m_qr, image.width(), image.height()) < 0)
    {
        return result;
    }

    // Get raw image buffer
    uint8_t *rawImage = quirc_begin(m_qr, nullptr, nullptr);
    if (rawImage == nullptr)
    {
        return result;
    }

    // Copy image data to QR context
    std::copy(image.constBits(), image.constBits() + image.width()*image.height(), rawImage);

    // Process the image
    quirc_end(m_qr);

    // Count detected QR codes
    const int count = quirc_count(m_qr);
    if (count < 0)
    {
        return result;
    }

    // Extract and decode each QR code
    for (int index = 0; index < count; ++index)
    {
        quirc_code code;
        quirc_extract(m_qr, index, &code);
        quirc_data data;
        const quirc_decode_error_t err = quirc_decode(&code, &data);
        if (err == QUIRC_SUCCESS)
        {
            result.append(QLatin1String((const char *)data.payload));
        }
    }

    return result;
}

