#include "OpenColorIOEditorSettings.h"

// Retrieves viewport settings for a given viewport identifier
const FOpenColorIODisplayConfiguration* UOpenColorIOLevelViewportSettings::GetViewportSettings(FName ViewportIdentifier) const
{
    // Find matching viewport settings
    const FPerViewportDisplaySettingPair* Pair = ViewportsSettings.FindByPredicate(
        [ViewportIdentifier](const FPerViewportDisplaySettingPair& Other)
        {
            return Other.ViewportIdentifier == ViewportIdentifier;
        }
    );

    if (Pair)
    {
        return &Pair->DisplayConfiguration;
    }

    return nullptr;
}

// Sets or updates viewport settings for a given viewport identifier
void UOpenColorIOLevelViewportSettings::SetViewportSettings(FName ViewportIdentifier, const FOpenColorIODisplayConfiguration& Configuration)
{
    // Attempt to find existing entry
    FPerViewportDisplaySettingPair* Pair = ViewportsSettings.FindByPredicate(
        [ViewportIdentifier](const FPerViewportDisplaySettingPair& Other)
        {
            return Other.ViewportIdentifier == ViewportIdentifier;
        }
    );

    if (Pair)
    {
        // Update existing configuration
        Pair->DisplayConfiguration = Configuration;
    }
    else
    {
        // Add new entry if viewport is not found
        FPerViewportDisplaySettingPair NewEntry;
        NewEntry.ViewportIdentifier = ViewportIdentifier;
        NewEntry.DisplayConfiguration = Configuration;
        ViewportsSettings.Emplace(MoveTemp(NewEntry));
    }
}

#include <OTwo/Network/Packet.hpp>
#include <Genode/System/Exception.hpp>
#include <ced/compact_enc_det.h>
#include <algorithm>
#include <codecvt>
#include <locale>

// Set endianness for packet
void Packet::SetEndianness(const Gx::Endian endianness)
{
    m_endianness = endianness;
}

// Get current endianness
Gx::Endian Packet::GetEndianness() const
{
    return m_endianness;
}

// Append raw data to packet
void Packet::Append(const void* data, const std::size_t sizeInBytes)
{
    if (data && sizeInBytes > 0)
    {
        // ReSharper disable once CppReinterpretCastFromVoidPtr
        const auto* begin = reinterpret_cast<const std::byte*>(data);
        const auto* end   = begin + sizeInBytes;
        m_data.insert(m_data.end(), begin, end);
    }
}

// Get current read position
std::size_t Packet::GetReadPosition() const
{
    return m_readPos;
}

// Clear packet contents and reset state
void Packet::Clear()
{
    m_data.clear();
    m_readPos = 0;
    m_isValid = true;
}

// Get pointer to internal data buffer
const void* Packet::GetData() const
{
    return !m_data.empty() ? &m_data[0] : nullptr;
}

// Get size of data in bytes
std::size_t Packet::GetDataSize() const
{
    return m_data.size();
}

// Check if we've reached the end of the packet
bool Packet::EndOfPacket() const
{
    return m_readPos >= m_data.size();
}

// Boolean conversion operator
Packet::operator bool() const
{
    return m_isValid;
}

// Read boolean value
Packet& Packet::operator>>(bool& data)
{
    std::uint8_t value{};
    if (*this >> value)
        data = (value != 0);
    return *this;
}

// Read signed 8-bit integer
Packet& Packet::operator>>(std::int8_t& data)
{
    Read(&data, sizeof(data));
    return *this;
}

// Read unsigned 8-bit integer
Packet& Packet::operator>>(std::uint8_t& data)
{
    Read(&data, sizeof(data));
    return *this;
}

// Read signed 16-bit integer with endianness transformation
Packet& Packet::operator>>(std::int16_t& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read unsigned 16-bit integer with endianness transformation
Packet& Packet::operator>>(std::uint16_t& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read signed 32-bit integer with endianness transformation
Packet& Packet::operator>>(std::int32_t& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read unsigned 32-bit integer with endianness transformation
Packet& Packet::operator>>(std::uint32_t& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read signed 64-bit integer with endianness transformation
Packet& Packet::operator>>(std::int64_t& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read unsigned 64-bit integer with endianness transformation
Packet& Packet::operator>>(std::uint64_t& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read float with endianness transformation
Packet& Packet::operator>>(float& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read double with endianness transformation
Packet& Packet::operator>>(double& data)
{
    Read(&data, sizeof(data));
    data = Transform(data);
    return *this;
}

// Read null-terminated C-string
Packet& Packet::operator>>(char* data)
{
    if (!data)
        throw Gx::ArgumentOutOfRangeException("Packet::operator>> Data must not be null");
    while (m_isValid)
    {
        std::uint8_t character{};
        *this >> character;
        *data++ = character;
        if (character == 0x00)
            break;
    }
    return *this;
}

// Read null-terminated std::string
Packet& Packet::operator>>(std::string& data)
{
    data.clear();
    while (m_isValid)
    {
        std::uint8_t character{};
        *this >> character;
        if (character == 0x00)
            break;
        data += static_cast<char>(character);
    }
    return *this;
}

// Read null-terminated wide character string
Packet& Packet::operator>>(wchar_t* data)
{
    while (m_isValid)
    {
        std::uint32_t character{};
        *this >> character;
        *data++ = static_cast<wchar_t>(character);
        if (character == 0x00)
            break;
    }
    return *this;
}

// Read null-terminated std::wstring
Packet& Packet::operator>>(std::wstring& data)
{
    data.clear();
    while (m_isValid)
    {
        std::uint16_t character{};
        *this >> character;
        if (character == 0x00)
            break;
        data += static_cast<wchar_t>(character);
    }
    return *this;
}

// Read sf::String with encoding detection
Packet& Packet::operator>>(sf::String& data)
{
    data.clear();
    auto bytes = std::vector<char>{};
    while (m_isValid)
    {
        std::uint8_t character{};
        *this >> character;
        if (character == 0x00)
            break;
        bytes.push_back(character);
    }
    bool reliable = false;
    int consumed = 0;
    const auto encoding = CompactEncDet::DetectEncoding(
        bytes.data(),
        bytes.size(),
        nullptr,
        nullptr,
        nullptr,
        0,
        Language::UNKNOWN_LANGUAGE,
        CompactEncDet::TextCorpusType::QUERY_CORPUS,
        true,
        &consumed,
        &reliable
    );
    switch (encoding)
    {
        case Encoding::ASCII_7BIT:
        case Encoding::UTF8:
        case Encoding::UTF8UTF8:
        {
            data = sf::String::fromUtf8(bytes.begin(), bytes.end());
            break;
        }
        case Encoding::UTF32LE:
        case Encoding::UTF32BE:
        case Encoding::GB18030:
        {
            // TODO: Handle Big Endian
            auto* ptr = reinterpret_cast<std::uint32_t*>(bytes.data());
            data = sf::String::fromUtf16(ptr, ptr + bytes.size() / sizeof(std::uint32_t));
            break;
        }
        default:
        {
            // TODO: Handle Big Endian
            auto* ptr = reinterpret_cast<std::uint16_t*>(bytes.data());
            data = sf::String::fromUtf16(ptr, ptr + bytes.size() / sizeof(std::uint16_t));
            break;
        }
    }
    return *this;
}

// Write boolean value
Packet& Packet::operator<<(const bool data)
{
    *this << static_cast<std::uint8_t>(data);
    return *this;
}

