// Write null-terminated C-string
Packet& Packet::operator<<(const char* data)
{
    if (data)
        *this << std::string(data);
    return *this;
}

// Write null-terminated std::string
Packet& Packet::operator<<(const std::string& data)
{
    if (data.size() > 0)
    {
        Append(data.c_str(), data.size());
        if (data.back() != 0x00)
            *this << static_cast<std::uint8_t>(0);
    }
    return *this;
}

// Write null-terminated wide character string
Packet& Packet::operator<<(const wchar_t* data)
{
    *this << std::wstring(data ? data : L"");
    return *this;
}

// Write null-terminated std::wstring
Packet& Packet::operator<<(const std::wstring& data)
{
    if (data.size() > 0)
    {
        for (const wchar_t c : data)
            *this << static_cast<std::uint16_t>(c);
        if (static_cast<std::uint16_t>(data.back()) != 0x00)
            *this << static_cast<std::uint16_t>(0);
    }
    return *this;
}

// Write sf::String
Packet& Packet::operator<<(const sf::String& data)
{
    if (data.getSize() > 0)
    {
        for (const std::uint32_t c : data)
        {
            if (c <= std::numeric_limits<std::uint8_t>::max())
                *this << static_cast<std::uint8_t>(c);
            else if (c <= std::numeric_limits<std::uint16_t>::max())
                *this << static_cast<std::uint16_t>(c);
            else
                *this << c;
        }
        if (static_cast<std::uint32_t>(*(data.end() - 1)) != 0x00)
            *this << static_cast<std::uint8_t>(0);
    }
    return *this;
}

// Prepare packet for sending
const void* Packet::OnSend(std::size_t& size)
{
    size = GetDataSize();
    return GetData();
}

// Process received data
void Packet::OnReceive(const void* data, const std::size_t size)
{
    Append(data, size);
}

// Internal read operation
void Packet::Read(void* data, const std::size_t size)
{
    if (m_readPos + size <= m_data.size())
    {
        std::memcpy(data, &m_data[m_readPos], size);
        m_readPos += size;
    }
    else
    {
        m_isValid = false;
    }
}

