    init_csv_context(csv_context);
    csv_context->num_rows = 3;
    csv_context->rows = rows;
    csv_context->num_columns = 1;
    csv_context->num_column_defs = 1;
    csv_context->column_def_index[0] = 0;
    csv_context->column_defs[0] = (csv_column_def_t){
