 * Error handling
 *****************************************************************************/

/**
 * Get latest error associated with a handle
 */
extern "C" int ndb_mgm_get_latest_error(const NdbMgmHandle h)
{
  if (!h) return NDB_MGM_ILLEGAL_SERVER_HANDLE;
  return h->last_error;
}

extern "C" const char *ndb_mgm_get_latest_error_desc(const NdbMgmHandle h)
{
  if (!h) return "";
  return h->last_error_desc;
}

extern "C" int ndb_mgm_get_latest_error_line(const NdbMgmHandle h)
{
  if (!h) return 0;
  return h->last_error_line;
}

extern "C" const char *ndb_mgm_get_latest_error_msg(const NdbMgmHandle h)
{
  const int last_err = ndb_mgm_get_latest_error(h);
  for (int i = 0; i < ndb_mgm_noOfErrorMsgs; i++)
  {
    if (ndb_mgm_error_msgs[i].code == last_err)
      return ndb_mgm_error_msgs[i].msg;
  }
  return "Error";  // Unknown Error message
}

static const Properties *handle_authorization_failure(NdbMgmHandle handle,
                                                      InputStream &in)
{
  /* Read the failure details and set the internal error conditions. */
  handle->last_error = NDB_MGM_NOT_AUTHORIZED;
  const ParserRow<ParserDummy> details[] =
  {
      MGM_CMD("Authorization failed", nullptr, ""),
      MGM_ARG("Error", String, Mandatory, "Error message"), MGM_END()};
  Parser_t::Context ctx;
  ParserDummy session(handle->socket);
  Parser_t parser(details, in);
  const Properties *reply = parser.parse(ctx, session);
  const char *reason = nullptr;
  if (reply && reply->get("Error", &reason))
  {
    if (strcmp(reason, "Requires TLS Client Certificate") == 0)
      handle->last_error = NDB_MGM_AUTH_REQUIRES_CLIENT_CERT;
    else if (strcmp(reason, "Requires TLS") == 0)
      handle->last_error = NDB_MGM_AUTH_REQUIRES_TLS;
  }
  delete reply;
  return nullptr;
}

/*
  ndb_mgm_call
  Send command, command arguments and any command bulk data to
  ndb_mgmd.
  Read and return result
  @param handle The mgmapi handle
  @param command_reply List describing the expected reply
  @param cmd Name of the command to call
  @param cmd_args Arguments for the command
  @param cmd_bulk Any bulk data to send after the command
 */
static const Properties *ndb_mgm_call(
    NdbMgmHandle handle, const ParserRow<ParserDummy> *command_reply,
    const char *cmd, const Properties *cmd_args,
    const char *cmd_bulk = nullptr)
{
  DBUG_ENTER("ndb_mgm_call");
  DBUG_PRINT("enter", ("handle->socket: %s, cmd: %s",
                       handle->socket.to_string().c_str(), cmd));
  SocketOutputStream out(handle->socket, handle->timeout);
  SocketInputStream in(handle->socket, handle->timeout);
  out.println("%s", cmd);
#ifdef MGMAPI_LOG
  /**
   * Print command to  log file
   */
  FileOutputStream f(handle->logfile);
  f.println("OUT: %s", cmd);
#endif
  if (cmd_args != nullptr)
  {
    Properties::Iterator iter(cmd_args);
    const char *name;
    while ((name = iter.next()) != nullptr)
    {
      PropertiesType t;
      Uint32 val_i;
      Uint64 val_64;
      BaseString val_s;
      if (!cmd_args->getTypeOf(name, &t))
      {
        BaseString errStr = "Failed to get type of argument: ";
        errStr.append(name);
        SET_ERROR(handle, NDB_MGM_USAGE_ERROR, errStr.c_str());
        DBUG_RETURN(nullptr);
      }
      switch (t)
      {
        case PropertiesType_Uint32:
          cmd_args->get(name, &val_i);
          out.println("%s: %u", name, val_i);
          break;
        case PropertiesType_Uint64:
          cmd_args->get(name, &val_64);
          out.println("%s: %llu", name, val_64);
          break;
        case PropertiesType_char:
        {
          const char *strfmt = "%s:\"%s\"";
          // '\n' and '\0' are appended by println
          const int reserved_bytes_for_format = 5;  // 2 x '"', ':', '\n', '\0'
          cmd_args->get(name, val_s);
          /**
           *  MaxParseBytes is 512, check if line length is exceeded.
           *  Todo:
           *  To support sending of longer strings to mgmd, the append
           *  capability of LongString must be used, i.e sending the
           *  string in chunks with a "+" prefix to the argument name
           *  from the second chunk onwards.
           *  Another notable problem that needs to be solved related to
           *  this is that the chunks are sent out of order since iterations
           *  over Properties object aren't ordered.
           */
          if ((reserved_bytes_for_format + strlen(name) + val_s.length()) >
              512)
          {
            BaseString errStr = "Line length exceeded due to argument: ";
            errStr.append(name);
            SET_ERROR(handle, NDB_MGM_USAGE_ERROR, errStr.c_str());
            DBUG_RETURN(nullptr);
          }
          // send to mgmd
          out.println(strfmt, name, val_s.c_str());
          break;
        }
        case PropertiesType_Properties:
          DBUG_PRINT("info", ("Ignoring PropertiesType_Properties."));
          /* Ignore */
          break;
        default:
          DBUG_PRINT("info", ("Ignoring PropertiesType: %d.", t));
      }
    }
#ifdef MGMAPI_LOG
    /**
     * Print arguments to  log file
     */
    cmd_args->print(handle->logfile, "OUT: ");
#endif
  }
  out.println("%s", "");
  if (cmd_bulk)
  {
    out.write(cmd_bulk, strlen(cmd_bulk));
    out.write("\n", 1);
  }
  CHECK_TIMEDOUT_RET(handle, in, out, nullptr, cmd);
  Parser_t::Context ctx;
  ParserDummy session(handle->socket);
  Parser_t parser(command_reply, in);
  const Properties *p = parser.parse(ctx, session);
  if (p == nullptr)
  {
    if (!ndb_mgm_is_connected(handle))
    {
      CHECK_TIMEDOUT_RET(handle, in, out, nullptr, cmd);
      DBUG_RETURN(nullptr);
    }
    else
    {
      CHECK_TIMEDOUT_RET(handle, in, out, nullptr, cmd);
      if (ctx.m_status == Parser_t::Eof || ctx.m_status == Parser_t::NoLine)
      {
        ndb_mgm_disconnect(handle);
        CHECK_TIMEDOUT_RET(handle, in, out, nullptr, cmd);
        DBUG_RETURN(nullptr);
      }
      /* Check for Authorization failure */
      if (strcmp(ctx.m_tokenBuffer, "Authorization failed") == 0)
      {
        RewindInputStream str(in, ctx.m_tokenBuffer);
        DBUG_RETURN(handle_authorization_failure(handle, str));
      }
      /**
       * Print some info about why the parser returns NULL
       */
      fprintf(handle->errstream,
              "Error in mgm protocol parser. cmd: >%s< status: %d curr: %s\n",
              cmd, (Uint32)ctx.m_status,
              (ctx.m_currentToken) ? ctx.m_currentToken : "NULL");
      DBUG_PRINT("info", ("ctx.status: %d, ctx.m_currentToken: %s",
                          ctx.m_status, ctx.m_currentToken));
    }
  }
#ifdef MGMAPI_LOG
  else
  {
    /**
     * Print reply to log file
     */
    p->print(handle->logfile, "IN: ");
  }
#endif
  if (p && (in.timedout() || out.timedout())) delete p;
  CHECK_TIMEDOUT_RET(handle, in, out, nullptr, cmd);
  DBUG_RETURN(p);
}

/*
  ndb_mgm_call_slow
  Some commands are synchronous and known to take longer time
  to complete(for example restart and stop). Increase the timeout
  value before sending command if the timeout value is set lower
  than what is normal.
  Unfortunately the restart or stop may take longer than the
  default min timeout value selected, mgmapi users can workaround
  this problem by setting an even larger timeout for all commands
  or only around restart and stop.
*/
static inline const Properties *ndb_mgm_call_slow(
    NdbMgmHandle handle, const ParserRow<ParserDummy> *command_reply,
    const char *cmd, const Properties *cmd_args,
    unsigned int min_timeout = 5 * 60 * 1000,  // ms
    const char *cmd_bulk = nullptr)
{
  const unsigned int save_timeout = handle->timeout;
  if (min_timeout > save_timeout) handle->timeout = min_timeout;
  const Properties *reply =
      ndb_mgm_call(handle, command_reply, cmd, cmd_args, cmd_bulk);
  // Restore saved timeout value
  handle->timeout = save_timeout;
  return reply;
}

/**
 * Returns true if connected
 */
extern "C" int ndb_mgm_is_connected(NdbMgmHandle handle)
{
  if (!handle) return 0;
  if (handle->connected)
  {
    if (handle->socket.check_hup())
    {
      handle->connected = 0;
      handle->socket.close();
    }
  }
  return handle->connected;
}

extern "C" int ndb_mgm_set_connect_timeout(NdbMgmHandle handle,
                                           unsigned int seconds)
{
  return ndb_mgm_set_timeout(handle, seconds * 1000);
}

extern "C" int ndb_mgm_set_timeout(NdbMgmHandle handle,
                                   unsigned int timeout_ms)
{
  if (!handle) return -1;
  handle->timeout = timeout_ms;
  return 0;
}

extern "C" int ndb_mgm_number_of_mgmd_in_connect_string(NdbMgmHandle handle)
{
  int count = 0;
  Uint32 i;
  LocalConfig &cfg = handle->cfg;
  for (i = 0; i < cfg.ids.size(); i++)
  {
    if (cfg.ids[i].type != MgmId_TCP) continue;
    count++;
  }
  return count;
}

static int ndb_mgm_set_version(NdbMgmHandle handle)
{
  DBUG_ENTER("ndb_mgm_set_version");
  CHECK_HANDLE(handle, -1);
  CHECK_CONNECTED(handle, -1);
  Properties args;
  args.put("major", Uint32(NDB_VERSION_MAJOR));
  args.put("minor", Uint32(NDB_VERSION_MINOR));
  args.put("build", Uint32(NDB_VERSION_BUILD));
  const ParserRow<ParserDummy> set_clientversion_reply[] =
  {
      MGM_CMD("set clientversion reply", nullptr, ""),
      MGM_ARG("result", String, Mandatory, "Error message"), MGM_END()};
  const Properties *reply =
      ndb_mgm_call(handle, set_clientversion_reply, "set clientversion", &args);
  CHECK_REPLY(handle, reply, -1);
  BaseString result;
  reply->get("result", result);
  delete reply;
  if (result != "Ok")
  {
    SET_ERROR(handle, NDB_MGM_ILLEGAL_SERVER_REPLY, result.c_str());
    DBUG_RETURN(-1);
  }
  DBUG_RETURN(0);
}

static inline bool get_mgmd_version(NdbMgmHandle handle)
{
  assert(handle->connected);
  if (handle->mgmd_version_major >= 0)
    return true;  // Already fetched version of mgmd
  char buf[2];  // Not used -> keep short
  if (!ndb_mgm_get_version(handle, &(handle->mgmd_version_major),
                           &(handle->mgmd_version_minor),
                           &(handle->mgmd_version_build), sizeof(buf), buf))
    return false;
  /* If MGMD supports it, tell it our version */
  if (NDB_MAKE_VERSION(handle->mgmd_version_major, handle->mgmd_version_minor,
                       handle->mgmd_version_build) >=
      NDB_MAKE_VERSION(8, 0, 20))
  {
    // Inform MGMD of our version
    // MGMD gained support for set version command in 8.0.20
    if (ndb_mgm_set_version(handle) != 0) return false;
  }
  return true;
}

/**
 * Connect to a management server
 * no_retries = 0, return immediately,
 * no_retries < 0, retry infinitely,
 * else retry no_retries times.
 */
extern "C" int ndb_mgm_connect(NdbMgmHandle handle, int no_retries,
                               int retry_delay_in_seconds, int verbose)
{
  DBUG_ENTER("ndb_mgm_connect");
  CHECK_HANDLE(handle, -1);
  SET_ERROR(handle, NDB_MGM_NO_ERROR, "Executing: ndb_mgm_connect");
  if (handle->connected)
  {
    ndb_mgm_disconnect(handle);
  }
  require(!handle->socket.is_valid());
#ifdef MGMAPI_LOG
  /**
   * Open the log file
   */
  char logname[64];
  BaseString::snprintf(logname, 64, "mgmapi.log");
  handle->logfile = fopen(logname, "w");
#endif
  char buf[1024];
  /**
   * Do connect
   */
  LocalConfig &cfg = handle->cfg;
  NdbSocket sock;
#ifndef _WIN32
  if (ndb_socket_can_disable_sigpipe())
    sock.disable_sigpipe();
  else if (handle->ignore_sigpipe)
  {
    // Check whether a non-default signal handler has been installed
    struct sigaction current;
    int r = sigaction(SIGPIPE, nullptr, &current);
    assert(r == 0);
    if (r == 0 && current.sa_handler == SIG_DFL) signal(SIGPIPE, SIG_IGN);
  }
#endif
  Uint32 i = Uint32(~0);
  while (!sock.is_valid())
  {
    Uint32 invalid_Address = 0;
    // do all the mgmt servers
    for (i = 0; i < cfg.ids.size(); i++)
    {
      if (cfg.ids[i].type != MgmId_TCP) continue;
      const char *bind_address = nullptr;
      unsigned short bind_address_port = 0;
      if (handle->m_bindaddress)
      {
        bind_address = handle->m_bindaddress;
        bind_address_port = handle->m_bindaddress_port;
      }
      else if (cfg.ids[i].bind_address.length())
      {
        bind_address = cfg.ids[i].bind_address.c_str();
        bind_address_port = cfg.ids[i].bind_address_port;
      }
      ndb_sockaddr bind_addr;
      if (bind_address)
      {
        if (Ndb_getAddr(&bind_addr, bind_address) != 0)
        {
          if (!handle->m_bindaddress)
          {
            // retry with next mgmt server
            continue;
          }
          if (verbose > 0)
            fprintf(handle->errstream,
                    "Unable to resolve local bind address: %s\n", bind_address);
          setError(handle, NDB_MGM_ILLEGAL_CONNECT_STRING, __LINE__,
                   "Unable to resolve local bind address: %s\n", bind_address);
          DBUG_RETURN(-1);
        }
        bind_addr.set_port(bind_address_port);
      }
      // return immediately when all the hostnames are invalid.
      ndb_sockaddr addr;
      if (Ndb_getAddr(&addr, cfg.ids[i].name.c_str()) != 0)
      {
        invalid_Address++;
        if (cfg.ids.size() - invalid_Address == 0)
        {
          if (verbose > 0)
            fprintf(handle->errstream,
                    "Unable to resolve any of the address"
                    " in connect string: %s\n",
                    cfg.makeConnectString(buf, sizeof(buf)));
          setError(handle, NDB_MGM_ILLEGAL_CONNECT_STRING, __LINE__,
                   "Unable to resolve any of the address"
                   " in connect string: %s\n",
                   cfg.makeConnectString(buf, sizeof(buf)));
          DBUG_RETURN(-1);
        }
        else
        {
          continue;
        }
      }
      addr.set_port(cfg.ids[i].port);
      SocketClient s;
      s.set_connect_timeout(handle->timeout);
      if (!s.init(addr.get_address_family()))
      {
        if (verbose > 0)
          fprintf(handle->errstream,
                  "Unable to create socket, "
                  "while trying to connect with connect string: %s\n",
                  cfg.makeConnectString(buf, sizeof(buf)));
        setError(handle, NDB_MGM_COULD_NOT_CONNECT_TO_SOCKET, __LINE__,
                 "Unable to create socket, "
                 "while trying to connect with connect string: %s\n",
                 cfg.makeConnectString(buf, sizeof(buf)));
        DBUG_RETURN(-1);
      }
      if (bind_address)
      {
        int err;
        if ((err = s.bind(bind_addr)) != 0)
        {
          if (!handle->m_bindaddress)
          {
            // retry with next mgmt server
            continue;
          }
          char buf[512];
          char *sockaddr_string = Ndb_combine_address_port(
              buf, sizeof(buf), bind_address, bind_address_port);
          if (verbose > 0)
            fprintf(handle->errstream,
                    "Unable to bind local address '%s' errno: %d, "
                    "while trying to connect with connect string: '%s'\n",
                    sockaddr_string, err,
                    cfg.makeConnectString(buf, sizeof(buf)));
          setError(handle, NDB_MGM_BIND_ADDRESS, __LINE__,
                   "Unable to bind local address '%s' errno: %d, "
                   "while trying to connect with connect string: '%s'\n",
                   sockaddr_string, err,
                   cfg.makeConnectString(buf, sizeof(buf)));
          DBUG_RETURN(-1);
        }
      }
      sock = s.connect(addr);
      if (sock.is_valid()) break;
    }
    if (sock.is_valid()) break;
#ifndef NDEBUG
    {
      DBUG_PRINT("error", ("Unable to connect with connect string: %s",
                           cfg.makeConnectString(buf, sizeof(buf))));
    }
#endif
    if (verbose > 0)
    {
      fprintf(handle->errstream,
              "ERROR: Unable to connect with connect string: %s\n",
              cfg.makeConnectString(buf, sizeof(buf)));
      verbose = -1;
    }
    if (no_retries == 0)
    {
      setError(handle, NDB_MGM_COULD_NOT_CONNECT_TO_SOCKET, __LINE__,
               "ERROR: Unable to connect with connect string: %s",
               cfg.makeConnectString(buf, sizeof(buf)));
      if (verbose == -2) fprintf(handle->errstream, ", failed.\n");
      DBUG_RETURN(-1);
    }
    if (verbose == -1)
    {
      fprintf(handle->errstream, "Retrying every %d seconds",
              retry_delay_in_seconds);
      if (no_retries > 0)
        fprintf(handle->errstream, ". Attempts left:");
      else
        fprintf(handle->errstream, ", until connected.");
      fflush(handle->errstream);
      verbose = -2;
    }
    if (no_retries > 0)
    {
      if (verbose == -2)
      {
        fprintf(handle->errstream, " %d", no_retries);
        fflush(handle->errstream);
      }
      no_retries--;
    }
    else
    {
      // no_retries < 0, retrying infinitely
      if (verbose == -2)
      {
        fprintf(handle->errstream, ".");
        fflush(handle->errstream);
      }
    }
    NdbSleep_SecSleep(retry_delay_in_seconds);
  }
  if (verbose == -2)
  {
    fprintf(handle->errstream, "\n");
    fflush(handle->errstream);
  }
  handle->cfg_i = i;
  handle->socket = std::move(sock);
  handle->connected = 1;
  // Version of the connected ndb_mgmd is not yet known
  handle->mgmd_version_major = -1;
  handle->mgmd_version_minor = -1;
  handle->mgmd_version_build = -1;
  DBUG_RETURN(0);
}

/**
 * Only used for low level testing
 * Never to be used by end user.
 * Or anybody who doesn't know exactly what they're doing.
 */
extern "C" socket_t ndb_mgm_get_fd(NdbMgmHandle handle)
{
  return handle->socket.native_socket();
}

/**
 * Disconnect from mgm server without error checking
 * Should be used internally only.
 * e.g. on timeout, we leave NdbMgmHandle disconnected
 */
int ndb_mgm_disconnect_quiet(NdbMgmHandle handle)
{
  if (handle->socket.is_valid()) handle->socket.close();
  handle->connected = 0;
  return 0;
}

/**
 * Disconnect from a mgm server
 */
extern "C" int ndb_mgm_disconnect(NdbMgmHandle handle)
{
  DBUG_ENTER("ndb_mgm_disconnect");
  CHECK_HANDLE(handle, -1);
  SET_ERROR(handle, NDB_MGM_NO_ERROR, "Executing: ndb_mgm_disconnect");
  CHECK_CONNECTED(handle, -1);
  DBUG_RETURN(ndb_mgm_disconnect_quiet(handle));
}

struct ndb_mgm_type_atoi
{
  const char *str;
  const char *alias;
  enum ndb_mgm_node_type value;
};

static struct ndb_mgm_type_atoi type_values[] =
{
    /*
     * Note, keep NDB as primary name for database node since this is used by
     * MGMAPI and changing it to DB would break backward compatibility.  This is
     * shown when running for example `ndb_mgm -eshow` there it prints
     * `[ndbd(NDB)]` for data nodes.
     *
     * Note, that in config.ini only DB and ndbd are valid for data nodes, not
     * NDB.
     */
    {"NDB", "ndbd", NDB_MGM_NODE_TYPE_NDB},
    {"DB", "ndbd", NDB_MGM_NODE_TYPE_NDB},
    {"API", "mysqld", NDB_MGM_NODE_TYPE_API},
    {"MGM", "ndb_mgmd", NDB_MGM_NODE_TYPE_MGM}};

const int no_of_type_values = (sizeof(type_values) / sizeof(ndb_mgm_type_atoi));

extern "C" ndb_mgm_node_type ndb_mgm_match_node_type(const char *type)
{
  if (type == nullptr) return NDB_MGM_NODE_TYPE_UNKNOWN;
  for (int i = 0; i < no_of_type_values; i++)
    if (strcmp(type, type_values[i].str) == 0)
      return type_values[i].value;
    else if (strcmp(type, type_values[i].alias) == 0)
      return type_values[i].value;
  return NDB_MGM_NODE_TYPE_UNKNOWN;
}

extern "C" const char *ndb_mgm_get_node_type_string(
    enum ndb_mgm_node_type type)
{
  for (int i = 0; i < no_of_type_values; i++)
    if (type_values[i].value == type) return type_values[i].str;
  return nullptr;
}

extern "C" const char *ndb_mgm_get_node_type_alias_string(
    enum ndb_mgm_node_type type, const char **str)
{
  for (int i = 0; i < no_of_type_values; i++)
    if (type_values[i].value == type)
    {
      if (str) *str = type_values[i].str;
      return type_values[i].alias;
    }
  return nullptr;
}

struct ndb_mgm_status_atoi
{
  const char *str;
  enum ndb_mgm_node_status value;
};

static struct ndb_mgm_status_atoi status_values[] =
{
    {"UNKNOWN", NDB_MGM_NODE_STATUS_UNKNOWN},
    {"NO_CONTACT", NDB_MGM_NODE_STATUS_NO_CONTACT},
    {"NOT_STARTED", NDB_MGM_NODE_STATUS_NOT_STARTED},
    {"STARTING", NDB_MGM_NODE_STATUS_STARTING},
    {"STARTED", NDB_MGM_NODE_STATUS_STARTED},
    {"SHUTTING_DOWN", NDB_MGM_NODE_STATUS_SHUTTING_DOWN},
    {"RESTARTING", NDB_MGM_NODE_STATUS_RESTARTING},
    {"SINGLE USER MODE", NDB_MGM_NODE_STATUS_SINGLEUSER},
    {"SINGLE USER MODE", NDB_MGM_NODE_STATUS_SINGLEUSER},
    {"RESUME", NDB_MGM_NODE_STATUS_RESUME},
    {"CONNECTED", NDB_MGM_NODE_STATUS_CONNECTED}};

const int no_of_status_values =
    (sizeof(status_values) / sizeof(ndb_mgm_status_atoi));

extern "C" ndb_mgm_node_status ndb_mgm_match_node_status(const char *status)
{
  if (status == nullptr) return NDB_MGM_NODE_STATUS_UNKNOWN;
  for (int i = 0; i < no_of_status_values; i++)
    if (strcmp(status, status_values[i].str) == 0)
      return status_values[i].value;
  return NDB_MGM_NODE_STATUS_UNKNOWN;
}

extern "C" const char *ndb_mgm_get_node_status_string(
    enum ndb_mgm_node_status status)
{
  int i;
  for (i = 0; i < no_of_status_values; i++)
    if (status_values[i].value == status) return status_values[i].str;
  for (i = 0; i < no_of_status_values; i++)
    if (status_values[i].value == NDB_MGM_NODE_STATUS_UNKNOWN)
      return status_values[i].str;
  return nullptr;
}

static int status_ackumulate(struct ndb_mgm_node_state *state,
                             const char *field, const char *value)
{
  if (strcmp("type", field) == 0)
  {
    state->node_type = ndb_mgm_match_node_type(value);
  }
  else if (strcmp("status", field) == 0)
  {
    state->node_status = ndb_mgm_match_node_status(value);
  }
  else if (strcmp("startphase", field) == 0)
  {
    state->start_phase = atoi(value);
  }
  else if (strcmp("dynamic_id", field) == 0)
  {
    state->dynamic_id = atoi(value);
  }
  else if (strcmp("node_group", field) == 0)
  {
    state->node_group = atoi(value);
  }
  else if (strcmp("version", field) == 0)
  {
    state->version = atoi(value);
  }
  else if (strcmp("connect_count", field) == 0)
  {
    state->connect_count = atoi(value);
  }
  else if (strcmp("address", field) == 0)
  {
    strncpy(state->connect_address, value, sizeof(state->connect_address));
    state->connect_address[sizeof(state->connect_address) - 1] = 0;
  }
  else if (strcmp("mysql_version", field) == 0)
  {
    state->mysql_version = atoi(value);
  }
  else if (strcmp("is_single_user", field) == 0)
  {
    // Do nothing
  }
  else
  {
    g_eventLogger->info("Unknown field: %s", field);
    return -1;
  }
  return 0;
}

static int status_ackumulate2(struct ndb_mgm_node_state2 *state,
                              const char *field, const char *value)
{
  if (strcmp("type", field) == 0)
  {
    state->node_type = ndb_mgm_match_node_type(value);
  }
  else if (strcmp("status", field) == 0)
  {
    state->node_status = ndb_mgm_match_node_status(value);
  }
  else if (strcmp("startphase", field) == 0)
  {
    state->start_phase = atoi(value);
  }
  else if (strcmp("dynamic_id", field) == 0)
  {
    state->dynamic_id = atoi(value);
  }
  else if (strcmp("node_group", field) == 0)
  {
    state->node_group = atoi(value);
  }
  else if (strcmp("version", field) == 0)
  {
    state->version = atoi(value);
  }
  else if (strcmp("connect_count", field) == 0)
  {
    state->connect_count = atoi(value);
  }
  else if (strcmp("mysql_version", field) == 0)
  {
    state->mysql_version = atoi(value);
  }
  else if (strcmp("is_single_user", field) == 0)
  {
    state->is_single_user = atoi(value);
  }
  else if (strcmp("address", field) == 0)
  {
    strncpy(state->connect_address, value, sizeof(state->connect_address));
    state->connect_address[sizeof(state->connect_address) - 1] = 0;
  }
  else
  {
    g_eventLogger->info("Unknown field: %s", field);
    return -1;
  }
  return 0;
}

/**
 * Compare function for qsort() that sorts ndb_mgm_node_state in
 * node_id order
 */
static int cmp_state(const void *_a, const void *_b)
{
  const struct ndb_mgm_node_state *a, *b;
  a = (const struct ndb_mgm_node_state *)_a;
  b = (const struct ndb_mgm_node_state *)_b;
  if (a->node_id > b->node_id) return 1;
  return -1;
}

extern "C" struct ndb_mgm_cluster_state *ndb_mgm_get_status(
    NdbMgmHandle handle)
{
  return ndb_mgm_get_status2(handle, nullptr);
}

extern "C" struct ndb_mgm_cluster_state *ndb_mgm_get_status2(
    NdbMgmHandle handle, const enum ndb_mgm_node_type types[])
{
  DBUG_ENTER("ndb_mgm_get_status2");
  CHECK_HANDLE(handle, nullptr);
  SET_ERROR(handle, NDB_MGM_NO_ERROR, "Executing: ndb_mgm_get_status");
  CHECK_CONNECTED(handle, nullptr);
  if (!get_mgmd_version(handle)) DBUG_RETURN(nullptr);
  char typestring[1024];
  typestring[0] = 0;
  if (types != nullptr)
  {
    int pos = 0;
    for (Uint32 i = 0; types[i] != NDB_MGM_NODE_TYPE_UNKNOWN; i++)
    {
      if (int(types[i]) < NDB_MGM_NODE_TYPE_MIN ||
          int(types[i]) > NDB_MGM_NODE_TYPE_MAX)
      {
        SET_ERROR(handle, EINVAL,
                  "Incorrect node type for ndb_mgm_get_status2");
        DBUG_RETURN(nullptr);
      }
      /**
       * Check for duplicates
       */
      for (Int32 j = i - 1; j >= 0; j--)
      {
        if (types[i] == types[j])
        {
          SET_ERROR(handle, EINVAL, "Duplicate types for ndb_mgm_get_status2");
          DBUG_RETURN(nullptr);
        }
      }
      int left = sizeof(typestring) - pos;
      int len = BaseString::snprintf(typestring + pos, left, "%s ",
                                     ndb_mgm_get_node_type_string(types[i]));
      if (len >= left)
      {
        SET_ERROR(handle, EINVAL,
                  "Out of memory for type-string for ndb_mgm_get_status2");
        DBUG_RETURN(nullptr);
      }
      pos += len;
    }
  }
  SocketOutputStream out(handle->socket, handle->timeout);
  SocketInputStream in(handle->socket, handle->timeout);
  const char *get_status_str = "get status";

#include <sycl/sycl.hpp>
#include "../utils.h"
#include "../dispatch_utils.h"

#define MAX(a, b) ((a) > (b) ? (a) : (b))
#define MIN(a, b) ((a) < (b) ? (a) : (b))

static constexpr int WARP_SIZE = 32;

namespace vllm {
namespace moe {

// ====================== Softmax things ===============================
// We have our own implementation of softmax here so we can support transposing
// the output in the softmax kernel when we extend this module to support
// expert-choice routing.
template <int TPB, typename InputdType>
class moeSoftmax {
 public:
  moeSoftmax(
      sycl::local_accessor<float, 1>& slm,
      const InputdType* input,
      const bool* finished,
      float* output,
      const int num_cols)
      : slm(slm),
        input(input),
        finished(finished),
        output(output),
        num_cols(num_cols) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_SIZE)]] (sycl::nd_item<1> item) const {
    void* slm_ptr = static_cast<void*>(
        slm.template get_multi_ptr<sycl::access::decorated::no>().get());
    float* normalizing_factor = reinterpret_cast<float*>(slm_ptr);
    float* float_max = normalizing_factor + 1;
    auto group = item.get_group();
    auto local_id_x = item.get_local_id(0);
    auto group_id_x = item.get_group(0);
    const int thread_row_offset = group_id_x * num_cols;
    float threadData(INFINITY * -1);

    // Don't touch finished rows.
    if ((finished != nullptr) && finished[group_id_x]) {
      return;
    }

    for (int ii = local_id_x; ii < num_cols; ii += TPB) {
      const int idx = thread_row_offset + ii;
      threadData = MAX(static_cast<float>(input[idx]), threadData);
    }

    const float maxElem =
        sycl::reduce_over_group(group, threadData, sycl::maximum<float>());
    if (local_id_x == 0) {
      *float_max = maxElem;
    }
    item.barrier(sycl::access::fence_space::local_space);

    threadData = 0;
    for (int ii = local_id_x; ii < num_cols; ii += TPB) {
      const int idx = thread_row_offset + ii;
      threadData += sycl::exp((static_cast<float>(input[idx]) - *float_max));
    }

    const auto Z = sycl::reduce_over_group(group, threadData, sycl::plus<>());
    if (local_id_x == 0) {
      *normalizing_factor = 1.f / Z;
    }
    item.barrier(sycl::access::fence_space::local_space);

    for (int ii = local_id_x; ii < num_cols; ii += TPB) {
      const int idx = thread_row_offset + ii;
      const float val =
          sycl::exp((static_cast<float>(input[idx]) - (*float_max))) *
          (*normalizing_factor);
      output[idx] = val;
    }
  }

 private:
  sycl::local_accessor<float, 1> slm;
  const InputdType* input;
  const bool* finished;
  float* output;
  const int num_cols;
};

template <int TPB, typename IndType>
class moeTopK {
 public:
  moeTopK(
      const float* inputs_after_softmax,
      const bool* finished,
      float* output,
      IndType* indices,
      int* source_rows,
      const int num_experts,
      const int k,
      const int start_expert,
      const int end_expert,
      const bool renormalize)
      : inputs_after_softmax(inputs_after_softmax),
        finished(finished),
        output(output),
        indices(indices),
        source_rows(source_rows),
        num_experts(num_experts),
        k(k),
        start_expert(start_expert),
        end_expert(end_expert),
        renormalize(renormalize) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_SIZE)]] (sycl::nd_item<1> item) const {
    int kIdx;
    float kVal;
    auto group = item.get_group();
    auto local_id_x = item.get_local_id(0);
    auto group_id_x = item.get_group(0);
    const int num_rows = item.get_group_range(0);
    const int block_row = group_id_x;
    const bool row_is_active = finished ? !finished[block_row] : true;
    const int thread_read_offset = group_id_x * num_experts;
    float sum_val = 0.0f;

    for (int k_idx = 0; k_idx < k; ++k_idx) {
      kIdx = 0;
      kVal = -1.f;  // This is OK because inputs are probabilities
      int inpIdx;
      float inpVal;

      for (int expert = local_id_x; expert < num_experts; expert += TPB) {
        const int idx = thread_read_offset + expert;
        inpIdx = expert;
        inpVal = inputs_after_softmax[idx];

        for (int prior_k = 0; prior_k < k_idx; ++prior_k) {
          const int prior_winning_expert = indices[k * block_row + prior_k];
          if (prior_winning_expert == expert) {
            inpIdx = kIdx;
            inpVal = kVal;
          }
        }

        if (inpVal > kVal) {
          kIdx = inpIdx;
          kVal = inpVal;
        }
      }

      const float resultVal =
          sycl::reduce_over_group(group, kVal, sycl::maximum<float>());
      const int resultIdx = sycl::reduce_over_group(
          group, resultVal == kVal ? kIdx : 0x7FFFFFFF, sycl::minimum<int>());

      sum_val += resultVal;

      if (local_id_x == 0) {
        // Ignore experts the node isn't responsible for with expert parallelism
        const int expert = resultIdx;
        const bool node_uses_expert =
            expert >= start_expert && expert < end_expert;
        const bool should_process_row = row_is_active && node_uses_expert;
        const int idx = k * block_row + k_idx;
        output[idx] = resultVal;
        indices[idx] =
            should_process_row ? (expert - start_expert) : num_experts;
        // Note: indices[idx] is always >= 0 by construction
        source_rows[idx] = k_idx * num_rows + block_row;
      }
      item.barrier(sycl::access::fence_space::local_space);
    }

    if (renormalize) {
      auto local_range_x = item.get_local_range(0);
      for (int k_idx = local_id_x; k_idx < k; k_idx += local_range_x) {
        const int idx = k * block_row + k_idx;
        output[idx] /= sum_val;
      }
    }
  }

 private:
  const float* inputs_after_softmax;
  const bool* finished;
  float* output;
  IndType* indices;
  int* source_rows;
  const int num_experts;
  const int k;
  const int start_expert;
  const int end_expert;
  const bool renormalize;
};

// ====================== TopK softmax things ===============================
/*
  A Top-K gating softmax written to exploit when the number of experts in the
  MoE layers are a small power of 2. This allows us to cleanly share the rows
  among the threads in a single warp and eliminate communication between warps
  (so no need to use shared mem).
  It fuses the softmax, max and argmax into a single kernel.
  Limitations:
  1) This implementation is optimized for when the number of experts is a small
  power of 2. Additionally it also supports when number of experts is multiple
  of 64 which is still faster than the computing softmax and topK separately. 2)
  This implementation assumes k is small, but will work for any k.
*/
template <
    int VPT,
    int NUM_EXPERTS,
    int WARPS_PER_CTA,
    int BYTES_PER_LDG,
    int WARP_SIZE_PARAM,
    typename InputdType,
    typename IndType>
class topkGatingSoftmax {
 public:
  topkGatingSoftmax(
      const InputdType* input,
      const bool* finished,
      float* output,
      const int num_rows,
      IndType* indices,
      int* source_rows,
      const int k,
      const int start_expert,
      const int end_expert,
      const bool renormalize)
      : input(input),
        finished(finished),
        output(output),
        num_rows(num_rows),
        indices(indices),
        source_rows(source_rows),
        k(k),
        start_expert(start_expert),
        end_expert(end_expert),
        renormalize(renormalize) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_SIZE)]] (sycl::nd_item<2> item) const {
    auto sg = item.get_sub_group();
    auto local_id_x = item.get_local_id(1);
    auto local_id_y = item.get_local_id(0);
    auto group_id_x = item.get_group(1);

    // We begin by enforcing compile time assertions and setting up compile time
    // constants.
    static_assert(
        BYTES_PER_LDG == (BYTES_PER_LDG & -BYTES_PER_LDG),
        "BYTES_PER_LDG must be power of 2");
    static_assert(BYTES_PER_LDG <= 16, "BYTES_PER_LDG must be leq 16");

    // Number of bytes each thread pulls in per load
    static constexpr int ELTS_PER_LDG = BYTES_PER_LDG / sizeof(InputdType);
    static constexpr int ELTS_PER_ROW = NUM_EXPERTS;
    static constexpr int THREADS_PER_ROW = ELTS_PER_ROW / VPT;
    static constexpr int LDG_PER_THREAD = VPT / ELTS_PER_LDG;

    // Restrictions based on previous section.
    static_assert(
        VPT % ELTS_PER_LDG == 0,
        "The elements per thread must be a multiple of the elements per ldg");
    static_assert(
        WARP_SIZE_PARAM % THREADS_PER_ROW == 0,
        "The threads per row must cleanly divide the threads per warp");
    static_assert(
        THREADS_PER_ROW == (THREADS_PER_ROW & -THREADS_PER_ROW),
        "THREADS_PER_ROW must be power of 2");
    static_assert(
        THREADS_PER_ROW <= WARP_SIZE_PARAM,
        "THREADS_PER_ROW can be at most warp size");

    // We have NUM_EXPERTS elements per row. We specialize for small #experts
    static constexpr int ELTS_PER_WARP = WARP_SIZE_PARAM * VPT;
    static constexpr int ROWS_PER_WARP = ELTS_PER_WARP / ELTS_PER_ROW;
    static constexpr int ROWS_PER_CTA = WARPS_PER_CTA * ROWS_PER_WARP;

    // Restrictions for previous section.
    static_assert(
        ELTS_PER_WARP % ELTS_PER_ROW == 0,
        "The elts per row must cleanly divide the total elt per warp");

    // ===================== From this point, we finally start computing
    // run-time variables. ========================
    // Compute CTA and warp rows. We pack multiple rows into a single warp, and
    // a block contains WARPS_PER_CTA warps. This, each block processes a chunk
    // of rows. We start by computing the start row for each block.
    const int cta_base_row = group_id_x * ROWS_PER_CTA;

    // Now, using the base row per thread block, we compute the base row per
    // warp.
    const int warp_base_row = cta_base_row + local_id_y * ROWS_PER_WARP;

    // The threads in a warp are split into sub-groups that will work on a row.
    // We compute row offset for each thread sub-group
    const int thread_row_in_warp = local_id_x / THREADS_PER_ROW;
    const int thread_row = warp_base_row + thread_row_in_warp;

    // Threads with indices out of bounds should early exit here.
    if (thread_row >= num_rows) {
      return;
    }

    const bool row_is_active = finished ? !finished[thread_row] : true;

    // We finally start setting up the read pointers for each thread. First,
    // each thread jumps to the start of the row it will read.
    const InputdType* thread_row_ptr = input + thread_row * ELTS_PER_ROW;

    // Now, we compute the group each thread belong to in order to determine the
    // first column to start loads.
    const int thread_group_idx = local_id_x % THREADS_PER_ROW;
    const int first_elt_read_by_thread = thread_group_idx * ELTS_PER_LDG;
    const InputdType* thread_read_ptr =
        thread_row_ptr + first_elt_read_by_thread;

    // Finally, we pull in the data from global mem
    InputdType row_chunk_load[VPT];
#pragma unroll
    for (int ii = 0; ii < LDG_PER_THREAD; ++ii) {
#pragma unroll
      for (int jj = 0; jj < ELTS_PER_LDG; ++jj) {
        row_chunk_load[ii * ELTS_PER_LDG + jj] =
            thread_read_ptr[ii * THREADS_PER_ROW * ELTS_PER_LDG + jj];
      }
    }

    float row_chunk[VPT];
#pragma unroll
    for (int ii = 0; ii < VPT; ++ii) {
      row_chunk[ii] = static_cast<float>(row_chunk_load[ii]);
    }

    // First, we perform a max reduce within the thread. We can do the max in
    // fp16 safely (I think) and just convert to float afterwards for the exp +
    // sum reduction.
    float thread_max = row_chunk[0];
#pragma unroll
    for (int ii = 1; ii < VPT; ++ii) {
      thread_max = MAX(thread_max, row_chunk[ii]);
    }

    // Now, we find the max within the thread group and distribute among the
    // threads. We use a butterfly reduce.
#pragma unroll
    for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
      auto other_thread_max = sycl::permute_group_by_xor(sg, thread_max, mask);
      thread_max =
          thread_max > other_thread_max ? thread_max : other_thread_max;
    }

    // From this point, thread max in all the threads have the max within the
    // row. Now, we subtract the max from each element in the thread and take
    // the exp. We also compute the thread local sum.
    float row_sum = 0;
#pragma unroll
    for (int ii = 0; ii < VPT; ++ii) {
      row_chunk[ii] = sycl::exp(row_chunk[ii] - thread_max);
      row_sum += row_chunk[ii];
    }

    // Now, we perform the sum reduce within each thread group. Similar to the max
    // reduce, we use a bufferfly pattern.
#pragma unroll
    for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
      row_sum += sycl::permute_group_by_xor(sg, row_sum, mask);
    }

    // From this point, all threads have the max and the sum for their rows in
    // the thread_max and thread_sum variables respectively. Finally, we can
    // scale the rows for the softmax. Technically, for top-k gating we don't
    // need to compute the entire softmax row. We can likely look at the maxes
    // and only compute for the top-k values in the row. However, this kernel
    // will likely not be a bottle neck and it seems better to closer match
    // torch and find the argmax after computing the softmax.
    const float reciprocal_row_sum = 1.f / row_sum;
#pragma unroll
    for (int ii = 0; ii < VPT; ++ii) {
      row_chunk[ii] = row_chunk[ii] * reciprocal_row_sum;
    }

    // Now, softmax_res contained the softmax of the row chunk. Now, I want to
    // find the topk elements in each row, along with the max index.
    int start_col = first_elt_read_by_thread;
    static constexpr int COLS_PER_GROUP_LDG = ELTS_PER_LDG * THREADS_PER_ROW;
    float sum_val = 0.0f;

    for (int k_idx = 0; k_idx < k; ++k_idx) {
      // First, each thread does the local argmax
      float max_val = row_chunk[0];
      int expert_local = start_col;
      int max_val_idx = 0;
#pragma unroll
      for (int ldg = 0, col = start_col; ldg < LDG_PER_THREAD;
           ++ldg, col += COLS_PER_GROUP_LDG) {
#pragma unroll
        for (int ii = 0; ii < ELTS_PER_LDG; ++ii) {
          float val = row_chunk[ldg * ELTS_PER_LDG + ii];
          // No check on the experts here since columns with the smallest index
          // are processed first and only updated if > (not >=)
          if (val > max_val) {
            max_val = val;
            expert_local = col + ii;
            max_val_idx = ldg * ELTS_PER_LDG + ii;
          }
        }
      }

      // Now, we perform the argmax reduce. We use the butterfly pattern so
      // threads reach consensus about the max. This will be useful for K > 1 so
      // that the threads can agree on "who" had the max value. That thread can
      // then blank out their max with -inf and the warp can run more
      // iterations...
      int expert = expert_local;
#pragma unroll
      for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
        float other_max = sycl::permute_group_by_xor(sg, max_val, mask);
        int other_expert = sycl::permute_group_by_xor(sg, expert, mask);
        // We want lower indices to "win" in every thread so we break ties this
        // way
        if (other_max > max_val ||
            (other_max == max_val && other_expert < expert)) {
          max_val = other_max;
          expert = other_expert;
        }
      }

      sum_val += max_val;

      // Write the max for this k iteration to global memory.
      if (thread_group_idx == 0) {
        // Add a guard to ignore experts not included by this node
        const bool node_uses_expert =
            expert >= start_expert && expert < end_expert;
        const bool should_process_row = row_is_active && node_uses_expert;
        // The lead thread from each sub-group will write out the final results
        // to global memory. (This will be a single) thread per row of the
        // input/output matrices.
        const int idx = k * thread_row + k_idx;
        output[idx] = max_val;
        indices[idx] =
            should_process_row ? (expert - start_expert) : NUM_EXPERTS;
        source_rows[idx] = k_idx * num_rows + thread_row;
      }

      // Finally, we clear the value in the thread with the current max if there
      // is another iteration to run.
      if (expert == expert_local) {
        row_chunk[max_val_idx] = -10000.f;
      }
    }

    if (renormalize) {
      for (int k_idx = thread_group_idx; k_idx < k; k_idx += THREADS_PER_ROW) {
        const int idx = k * thread_row + k_idx;
        output[idx] /= sum_val;
      }
    }
  }

 private:
  const InputdType* input;
  const bool* finished;
  float* output;
  const int num_rows;
  IndType* indices;
  int* source_rows;
  const int k;
  const int start_expert;
  const int end_expert;
  const bool renormalize;
};

namespace detail {
// Constructs some constants needed to partition the work across threads at
// compile time.
template <
    int EXPERTS,
    int BYTES_PER_LDG,
    int WARP_SIZE_PARAM,
    typename InputdType>
struct TopkConstants {
  static constexpr int ELTS_PER_LDG = BYTES_PER_LDG / sizeof(InputdType);
  static_assert(
      EXPERTS / (ELTS_PER_LDG * WARP_SIZE_PARAM) == 0 ||
          EXPERTS % (ELTS_PER_LDG * WARP_SIZE_PARAM) == 0,
      "");
  static constexpr int VECs_PER_THREAD =
      MAX(1, EXPERTS / (ELTS_PER_LDG * WARP_SIZE_PARAM));
  static constexpr int VPT = VECs_PER_THREAD * ELTS_PER_LDG;
  static constexpr int THREADS_PER_ROW = EXPERTS / VPT;
  static const int ROWS_PER_WARP = WARP_SIZE_PARAM / THREADS_PER_ROW;
};
}  // namespace detail

template <
    int EXPERTS,
    int WARPS_PER_TB,
    int WARP_SIZE_PARAM,
    int MAX_BYTES_PER_LDG,
    typename InputdType,
    typename IndType>
void topkGatingSoftmaxLauncherHelper(
    const InputdType* input,
    const bool* finished,
    float* output,
    IndType* indices,
    int* source_row,
    const int num_rows,
    const int k,
    const int start_expert,
    const int end_expert,
    bool renormalize,
    sycl::queue& queue) {
  static constexpr int BYTES_PER_LDG =
      MIN(MAX_BYTES_PER_LDG, sizeof(InputdType) * EXPERTS);
  using Constants = detail::
      TopkConstants<EXPERTS, BYTES_PER_LDG, WARP_SIZE_PARAM, InputdType>;
  static constexpr int VPT = Constants::VPT;
  static constexpr int ROWS_PER_WARP = Constants::ROWS_PER_WARP;

  const int num_warps = (num_rows + ROWS_PER_WARP - 1) / ROWS_PER_WARP;
  const int num_blocks = (num_warps + WARPS_PER_TB - 1) / WARPS_PER_TB;

  sycl::range<2> grid(1, num_blocks);
  sycl::range<2> block(WARPS_PER_TB, WARP_SIZE_PARAM);

  queue.submit([&](sycl::handler& cgh) {
    cgh.parallel_for(
        sycl::nd_range<2>(grid * block, block),
        topkGatingSoftmax<
            VPT,
            EXPERTS,
            WARPS_PER_TB,
            BYTES_PER_LDG,
            WARP_SIZE_PARAM,
            InputdType,
            IndType>(
            input,
            finished,
            output,
            num_rows,
            indices,
            source_row,
            k,
            start_expert,
            end_expert,
            renormalize));
  });
}

#define LAUNCH_SOFTMAX(NUM_EXPERTS, WARPS_PER_TB, MAX_BYTES)                   \
  static_assert(                                                               \
      WARP_SIZE == 32, "Unsupported warp size. Only 32 is supported for XPU"); \
  topkGatingSoftmaxLauncherHelper<                                             \
      NUM_EXPERTS,                                                             \
      WARPS_PER_TB,                                                            \
      WARP_SIZE,                                                               \
      MAX_BYTES>(                                                              \
      gating_output,                                                           \
      nullptr,                                                                 \
      topk_weights,                                                            \
      topk_indices,                                                            \
      token_expert_indices,                                                    \
      num_tokens,                                                              \
      topk,                                                                    \
      0,                                                                       \
      num_experts,                                                             \
      renormalize,                                                             \
      queue);

template <typename InputdType, typename IndType>
void topkGatingSoftmaxKernelLauncher(
    const InputdType* gating_output,
    float* topk_weights,
    IndType* topk_indices,
    int* token_expert_indices,
    float* softmax_workspace,
    const int num_tokens,
    const int num_experts,
    const int topk,
    const bool renormalize,
    sycl::queue& queue) {
  static constexpr int WARPS_PER_TB = 4;
  static constexpr int BYTES_PER_LDG_POWER_OF_2 = 16;
  static constexpr int BYTES_PER_LDG_MULTIPLE_64 = 2 * sizeof(InputdType);

  switch (num_experts) {
    case 1:
      LAUNCH_SOFTMAX(1, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 2:
      LAUNCH_SOFTMAX(2, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 4:
      LAUNCH_SOFTMAX(4, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 8:
      LAUNCH_SOFTMAX(8, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 16:
      LAUNCH_SOFTMAX(16, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 32:
      LAUNCH_SOFTMAX(32, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 64:
      LAUNCH_SOFTMAX(64, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 128:
      LAUNCH_SOFTMAX(128, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 256:
      LAUNCH_SOFTMAX(256, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 512:
      LAUNCH_SOFTMAX(512, WARPS_PER_TB, BYTES_PER_LDG_POWER_OF_2);
      break;
    case 192:
      LAUNCH_SOFTMAX(192, WARPS_PER_TB, BYTES_PER_LDG_MULTIPLE_64);
      break;
    case 320:
      LAUNCH_SOFTMAX(320, WARPS_PER_TB, BYTES_PER_LDG_MULTIPLE_64);
      break;
    case 384:
      LAUNCH_SOFTMAX(384, WARPS_PER_TB, BYTES_PER_LDG_MULTIPLE_64);
      break;
    case 448:
      LAUNCH_SOFTMAX(448, WARPS_PER_TB, BYTES_PER_LDG_MULTIPLE_64);
      break;
    case 576:
      LAUNCH_SOFTMAX(576, WARPS_PER_TB, BYTES_PER_LDG_MULTIPLE_64);
      break;
    default: {
      TORCH_CHECK(
          softmax_workspace != nullptr,
          "softmax_workspace must be provided for num_experts that are "
          "not a power of 2 or multiple of 64.");
      static constexpr int TPB = 256;
      sycl::range<1> grid1(num_tokens);
      sycl::range<1> block1(TPB);
      queue.submit([&](sycl::handler& cgh) {
        sycl::local_accessor<float, 1> slm(sycl::range<1>(2), cgh);
        cgh.parallel_for(
            sycl::nd_range<1>(grid1 * block1, block1),
            moeSoftmax<TPB, InputdType>(
                slm, gating_output, nullptr, softmax_workspace, num_experts));
      });
      sycl::range<1> grid2(num_tokens);
      sycl::range<1> block2(TPB);
      queue.submit([&](sycl::handler& cgh) {
        cgh.parallel_for(
            sycl::nd_range<1>(grid2 * block2, block2),
            moeTopK<TPB, IndType>(
                softmax_workspace,
                nullptr,
                topk_weights,
                topk_indices,
                token_expert_indices,
                num_experts,
                topk,
                0,
                num_experts,
                renormalize));
      });
    }
  }
}
}  // namespace moe
}  // namespace vllm

void topk_softmax(
    torch::Tensor& topk_weights,          // [num_tokens, topk]
    torch::Tensor& topk_indices,          // [num_tokens, topk]
    torch::Tensor& token_expert_indices,  // [num_tokens, topk]
    torch::Tensor& gating_output,         // [num_tokens, num_experts]
    const bool renormalize) {
  const int num_experts = gating_output.size(-1);
  const auto num_tokens = gating_output.numel() / num_experts;
  const int topk = topk_weights.size(-1);
  const bool is_pow_2 =
      (num_experts != 0) && ((num_experts & (num_experts - 1)) == 0);
  const bool needs_workspace = !is_pow_2 || num_experts > 256;
  const int64_t workspace_size = needs_workspace ? num_tokens * num_experts : 0;
  const at::DeviceGuard device_guard(gating_output.device());
  auto& queue = vllm::xpu::vllmGetQueue();
  torch::Tensor softmax_workspace = torch::empty(
      {workspace_size}, gating_output.options().dtype(torch::kFloat));

#define LAUNCH_TOPK_SOFTMAX(INPUTDTYPE, INDTYPE)                       \
  vllm::moe::topkGatingSoftmaxKernelLauncher(                          \
      reinterpret_cast<INPUTDTYPE*>(gating_output.mutable_data_ptr()), \
      topk_weights.data_ptr<float>(),                                  \
      topk_indices.data_ptr<INDTYPE>(),                                \
      token_expert_indices.data_ptr<int>(),                            \
      softmax_workspace.data_ptr<float>(),                             \
      num_tokens,                                                      \
      num_experts,                                                     \
      topk,                                                            \
      renormalize,                                                     \
      queue);

  if (topk_indices.scalar_type() == at::ScalarType::Int) {
    if (gating_output.scalar_type() == at::ScalarType::Float)
      LAUNCH_TOPK_SOFTMAX(float, int)
    else if (gating_output.scalar_type() == at::ScalarType::Half)
      LAUNCH_TOPK_SOFTMAX(sycl::half, int)
    else
      LAUNCH_TOPK_SOFTMAX(sycl::ext::oneapi::bfloat16, int)
  } else if (topk_indices.scalar_type() == at::ScalarType::UInt32) {
    if (gating_output.scalar_type() == at::ScalarType::Float)
      LAUNCH_TOPK_SOFTMAX(float, uint32_t)
    else if (gating_output.scalar_type() == at::ScalarType::Half)
      LAUNCH_TOPK_SOFTMAX(sycl::half, uint32_t)
    else
      LAUNCH_TOPK_SOFTMAX(sycl::ext::oneapi::bfloat16, uint32_t)
  } else {
    TORCH_CHECK(topk_indices.scalar_type() == at::ScalarType::Long);
    if (gating_output.scalar_type() == at::ScalarType::Float)
      LAUNCH_TOPK_SOFTMAX(float, int64_t)
    else if (gating_output.scalar_type() == at::ScalarType::Half)
      LAUNCH_TOPK_SOFTMAX(sycl::half, int64_t)
    else
      LAUNCH_TOPK_SOFTMAX(sycl::ext::oneapi::bfloat16, int64_t)
  }

#undef LAUNCH_TOPK_SOFTMAX
}

