// Convert Z3 expression to uint64_t
uint64_t expr_to_uint(const z3::expr &e) {
  uint64_t result;
  bool succ = Z3_get_numeral_uint64(e.ctx(), e, &result);
  (void)succ;
  assert(succ && "unsupported conversion from numeral");
  return result;
}

// Convert Z3 expression to int64_t (with sign extension if needed)
int64_t expr_to_int(const z3::expr &e) {
  uint64_t res;
  bool succ = Z3_get_numeral_uint64(e.ctx(), e, &res);
  int64_t result = (int64_t)res;

  if (!succ)
    std::cerr << e << '\n';

  assert(succ && "unsupported conversion from numeral");
  unsigned int size = e.get_sort().bv_size();

  if (size < 64 && (result & (1L << (size - 1L)))) {
    // need to sign extend
    result = ~((1L << size) - 1L) | result;
  }

  return result;
}

// Convert Z3 boolean expression to C++ bool
bool expr_to_bool(const z3::expr &e) {
  assert(e.is_const());
  assert(e.is_bool());
  return z3::eq(e, e.ctx().bool_val(true));
}

// Check if model defines a given symbol
bool model_defines(const z3::model &model, const z3::symbol &sym) {
  for (unsigned i = 0; i < model.num_consts(); i++) {
    if (model.get_const_decl(i).name() == sym)
      return true;
  }
  return false;
}

// Check if expression is unsatisfiable
bool is_unsat(z3::expr e) {
  z3::solver solver(e.ctx());
  solver.add(e);
  return solver.check() == z3::unsat;
}

// Extract all uninterpreted constants from an expression
std::vector<expr> expr_constants(const expr &e) {
  auto &ctx = e.ctx();
  auto compare_func = [](const expr &a, const expr &b) {
    Z3_symbol sym_a = a.decl().name();
    Z3_symbol sym_b = b.decl().name();
    return sym_a < sym_b;
  };

  std::set<expr, decltype(compare_func)> syms(compare_func);
  std::function<void(const expr &)> recur = [&recur, &syms, &ctx](const expr &e) {
    assert(Z3_is_app(ctx, e));
    auto app = Z3_to_app(ctx, e);
    unsigned n_args = Z3_get_app_num_args(ctx, app);
    auto fdecl = Z3_get_app_decl(ctx, app);

    if (n_args == 0 && Z3_get_decl_kind(ctx, fdecl) == Z3_OP_UNINTERPRETED)
      syms.insert(e);

    for (unsigned i = 0; i < n_args; ++i) {
      z3::expr arg(ctx, Z3_get_app_arg(ctx, app, i));
      recur(arg);
    }
  };

  recur(e);
  return std::vector<expr>(syms.begin(), syms.end());
}

// Adjust bitwidth of a bitvector expression
z3::expr adjustBitwidth(z3::expr op, unsigned int to_size) {
  assert(op.is_bv() && "Only Bitvectors supported here!");
  unsigned int from_size = op.get_sort().bv_size();

  if (to_size < from_size) // truncate
    return z3_ext::extract(to_size - 1, 0, op);
  else if (to_size > from_size) // zero extend
    return z3_ext::zext(to_size - from_size, op);
  else
    return op;
}

// Create a constant integer expression from LLVM ConstantInt
z3::expr makeConstantInt(z3::context *ctx, const llvm::ConstantInt *value) {
  int bits = value->getType()->getIntegerBitWidth();
  assert(bits <= 64 && "TODO: support bigger ints");
  uint64_t val = llvm::dyn_cast<llvm::ConstantInt>(value)->getLimitedValue();
  z3::expr cexpr = ctx->bv_val((uint64_t)val, bits);
  return cexpr;
}

// Create tuple sort with two fields
void makePairSort(z3::context &ctx, z3::sort &dest_sort,
                  z3::func_decl &dest_get_a, z3::func_decl &dest_get_b,
                  z3::func_decl &dest_constr, const char *src_get_a_name,
                  z3::sort src_get_a_sort, const char *src_get_b_name,
                  z3::sort src_get_b_sort, const char *src_constr_name) {
  Z3_symbol mk_tuple_name = Z3_mk_string_symbol(ctx, src_constr_name);
  Z3_symbol proj_names[2];
  Z3_sort proj_sorts[2];
  Z3_func_decl constr_decl;
  Z3_func_decl proj_decls[2];

  proj_names[0] = Z3_mk_string_symbol(ctx, src_get_a_name);
  proj_names[1] = Z3_mk_string_symbol(ctx, src_get_b_name);
  proj_sorts[0] = src_get_a_sort;
  proj_sorts[1] = src_get_b_sort;

  Z3_sort res = Z3_mk_tuple_sort(ctx, mk_tuple_name, 2, proj_names, proj_sorts,
                                 &constr_decl, proj_decls);

  dest_sort = z3::to_sort(ctx, res);
  dest_get_a = z3::to_func_decl(ctx, proj_decls[0]);
  dest_get_b = z3::to_func_decl(ctx, proj_decls[1]);
  dest_constr = z3::to_func_decl(ctx, constr_decl);
}

#ifndef _STLP_STRING_IO_C
#define _STLP_STRING_IO_C

#ifndef _STLP_STRING_IO_H
#  include <stl/_string_io.h>
#endif

#ifndef _STLP_INTERNAL_CTYPE_H
#  include <stl/_ctype.h>
#endif

_STLP_BEGIN_NAMESPACE

// Helper function to fill stream buffer with a character
template <class _CharT, class _Traits>
bool _STLP_CALL
__stlp_string_fill(basic_ostream<_CharT, _Traits>& __os,
                   basic_streambuf<_CharT, _Traits>* __buf,
                   streamsize __n) {
  _CharT __f = __os.fill();
  for (streamsize __i = 0; __i < __n; ++__i) {
    if (_Traits::eq_int_type(__buf->sputc(__f), _Traits::eof()))
      return false;
  }
  return true;
}

// Output operator for basic_string
template <class _CharT, class _Traits, class _Alloc>
basic_ostream<_CharT, _Traits>& _STLP_CALL
operator << (basic_ostream<_CharT, _Traits>& __os, 
             const basic_string<_CharT,_Traits,_Alloc>& __s) {
  typedef basic_ostream<_CharT, _Traits> __ostream;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  // Static assertion that size_type is unsigned
  typedef char __static_assert_unsigned_size_type[__STATIC_CAST(size_type, -1) > 0];

  typename __ostream::sentry __sentry(__os);
  bool __ok = false;

  if (__sentry) {
    __ok = true;
    size_type __n = __s.size();
    const bool __left = (__os.flags() & __ostream::left) != 0;
    const streamsize __w = __os.width(0);
    basic_streambuf<_CharT, _Traits>* __buf = __os.rdbuf();

    const bool __need_pad = (((sizeof(streamsize) > sizeof(size_t)) && (__STATIC_CAST(streamsize, __n) < __w)) ||
                             ((sizeof(streamsize) <= sizeof(size_t)) && (__n < __STATIC_CAST(size_t, __w))));
    streamsize __pad_len = __need_pad ? __w - __n : 0;

    if (!__left)
      __ok = __stlp_string_fill(__os, __buf, __pad_len);    
    __ok = __ok && (__buf->sputn(__s.data(), streamsize(__n)) == streamsize(__n));
    if (__left)
      __ok = __ok && __stlp_string_fill(__os, __buf, __pad_len);
  }

  if (!__ok)
    __os.setstate(__ostream::failbit);

  return __os;
}

// Input operator for basic_string
template <class _CharT, class _Traits, class _Alloc>
basic_istream<_CharT, _Traits>& _STLP_CALL 
operator >> (basic_istream<_CharT, _Traits>& __is,
             basic_string<_CharT,_Traits, _Alloc>& __s) {
  typedef basic_istream<_CharT, _Traits> __istream;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  // Static assertion that size_type is unsigned
  typedef char __static_assert_unsigned_size_type[__STATIC_CAST(size_type, -1) > 0];

  typename __istream::sentry __sentry(__is);

  if (__sentry) {
    basic_streambuf<_CharT, _Traits>* __buf = __is.rdbuf();
    typedef ctype<_CharT> _C_type;
    const locale& __loc = __is.getloc();
    const _C_type& _Ctype = use_facet<_C_type>(__loc);

    __s.clear();
    streamsize __width = __is.width(0);
    size_type __n;

    if (__width <= 0)
      __n = __s.max_size();
    /* __width can only overflow size_type if sizeof(streamsize) > sizeof(size_type)
     * because here we know that __width is positive and the static assertion check 
     * that size_type is unsigned.
     */
    else if (sizeof(streamsize) > sizeof(size_type) && 
             (__width > __STATIC_CAST(streamsize, __s.max_size())))
      __n = 0;
    else {
      __n = __STATIC_CAST(size_type, __width);
      __s.reserve(__n);
    }

    while (__n-- > 0) {
      typename _Traits::int_type __c1 = __buf->sbumpc();
      if (_Traits::eq_int_type(__c1, _Traits::eof())) {
        __is.setstate(__istream::eofbit);
        break;
      }
      else {
        _CharT __c = _Traits::to_char_type(__c1);
        if (_Ctype.is(_C_type::space, __c)) {
          if (_Traits::eq_int_type(__buf->sputbackc(__c), _Traits::eof()))
            __is.setstate(__istream::failbit);
          break;
        }
        else
          __s.push_back(__c);
      }
    }

    // If we have read no characters, then set failbit.
    if (__s.empty())
      __is.setstate(__istream::failbit);
  }
  else
    __is.setstate(__istream::failbit);

  return __is;
}

// getline function for basic_string
template <class _CharT, class _Traits, class _Alloc>    
basic_istream<_CharT, _Traits>& _STLP_CALL 
getline(basic_istream<_CharT, _Traits>& __is,
        basic_string<_CharT,_Traits,_Alloc>& __s,
        _CharT __delim) {
  typedef basic_istream<_CharT, _Traits> __istream;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  size_type __nread = 0;
  typename basic_istream<_CharT, _Traits>::sentry __sentry(__is, true);

  if (__sentry) {
    basic_streambuf<_CharT, _Traits>* __buf = __is.rdbuf();
    __s.clear();

    while (__nread < __s.max_size()) {
      int __c1 = __buf->sbumpc();
      if (_Traits::eq_int_type(__c1, _Traits::eof())) {
        __is.setstate(__istream::eofbit);
        break;
      }
      else {
        ++__nread;
        _CharT __c = _Traits::to_char_type(__c1);
        if (!_Traits::eq(__c, __delim)) 
          __s.push_back(__c);
        else
          break;              // Character is extracted but not appended.
      }
    }
  }

  if (__nread == 0 || __nread >= __s.max_size())
    __is.setstate(__istream::failbit);

  return __is;
}

