// Constructor for EditChain
EditChain::EditChain(QWidget *parent) : QWidget(parent), ui(new Ui::EditChain)
{
    ui->setupUi(this);
}

// Destructor
EditChain::~EditChain()
{
    delete ui;
}

// Initialize with a proxy entity
void EditChain::onStart(std::shared_ptr<Configs::ProxyEntity> _ent)
{
    this->ent = _ent;
    auto bean = this->ent->ChainBean();
    for (auto id : bean->list)
    {
        AddProfileToListIfExist(id);
    }
}

// Finalize and validate the chain configuration
bool EditChain::onEnd()
{
    if (get_edit_text_name().isEmpty())
    {
        MessageBoxWarning(software_name, tr("Name cannot be empty."));
        return false;
    }

    auto bean = this->ent->ChainBean();
    QList<int> idList;

    for (int i = 0; i < ui->listWidget->count(); i++)
    {
        idList << ui->listWidget->item(i)->data(114514).toInt();
    }

    bean->list = idList;
    return true;
}

// Handle clicking the "select profile" button
void EditChain::on_select_profile_clicked()
{
    // get_edit_dialog()->hide();
    auto window = new DialogGroupChooseProxy(this);
    window->setWindowTitle(QCoreApplication::translate(
        "DialogGroupChooseProxy", "Add proxy"));

    QObject::connect(window, &DialogGroupChooseProxy::set_proxy,
                     this, [this](int id)
                     { AddProfileToListIfExist(id); });

    window->show();
}

// Add a profile to the list if it exists and is valid
void EditChain::AddProfileToListIfExist(int profileId)
{
    auto _ent = Configs::profileManager->GetProfile(profileId);

    if (_ent != nullptr && _ent->type != "chain" && _ent->type != "extracore")
    {
        auto wI = new QListWidgetItem();
        wI->setData(114514, profileId);

        auto w = new ProxyItem(this, _ent, wI);
        ui->listWidget->addItem(wI);
        ui->listWidget->setItemWidget(wI, w);

        // Setup change button handler
        connect(w->get_change_button(), &QPushButton::clicked, w, [=, this]
                {
            auto window = new DialogGroupChooseProxy(this);
            window->setWindowTitle(QCoreApplication::translate(
                "DialogGroupChooseProxy", "Replace %1 proxy").arg(w->ent->bean->DisplayName()));
            QObject::connect(window, &DialogGroupChooseProxy::set_proxy,
                this, [w, this](int newId)
                { ReplaceProfile(w, newId); });
            window->show(); });
    }
}

// Replace an existing profile item with a new one
void EditChain::ReplaceProfile(ProxyItem *w, int profileId)
{
    auto _ent = Configs::profileManager->GetProfile(profileId);

    if (_ent != nullptr && _ent->type != "chain" && _ent->type != "extracore")
    {
        w->item->setData(114514, profileId);
        w->ent = _ent;
        w->refresh_data();
    }
}

#include "locale.hpp"
#include <ostream>

namespace xdgpp {

// Returns the system locale by querying LC_MESSAGES
Locale Locale::system()
{
  setlocale(LC_MESSAGES, "");
  const char *messagesLocale = setlocale(LC_MESSAGES, nullptr);
  return Locale::parse(messagesLocale);
}

// Checks if this locale matches only the specified components of rhs
bool Locale::matchesOnly(const Locale &rhs, int components)
{
  if (rhs.flags() != components) return false;
  if (components & Component::LANG && m_lang != rhs.lang()) return false;
  if (components & Component::COUNTRY && m_country != rhs.country()) return false;
  if (components & Component::MODIFIER && m_modifier != rhs.modifier()) return false;
  return true;
}

// Returns a bitmask indicating which components are present
int Locale::flags() const
{
  int value = static_cast<int>(Component::LANG);
  if (m_country) value |= Component::COUNTRY;
  if (m_modifier) value |= Component::MODIFIER;
  return value;
}

// Parses a locale string (e.g., "en_US.UTF-8@modifier")
Locale Locale::parse(std::string_view data)
{
  enum class State { Lang, Country, Encoding, Mod } state = State::Lang;
  size_t i = 0;
  std::string lang;
  std::string country;
  std::string encoding;
  std::string mod;

  while (i < data.size() && data[i] != ']')
  {
    const char c = data[i];
    switch (state)
    {
      case State::Lang:
      {
        if (std::isalpha(c))
        {
          lang += c;
        }
        else
        {
          if (c == '_')
          {
            state = State::Country;
          }
          else if (c == '.')
          {
            state = State::Encoding;
          }
          else if (c == '@')
          {
            state = State::Mod;
          }
        }
        break;
      }
      case State::Country:
      {
        if (std::isalpha(c))
        {
          country += c;
        }
        else
        {
          if (c == '.')
          {
            state = State::Encoding;
          }
          else if (c == '@')
          {
            state = State::Mod;
          }
        }
        break;
      }
      case State::Encoding:
      {
        if (std::isalnum(c))
        {
          encoding += c;
        }
        else
        {
          if (c == '@') { state = State::Mod; }
        }
        break;
      }
      case State::Mod:
      {
        if (std::isalpha(c))
        {
          mod += c;
        }
        else
        {
          // Ignore non-alphabetic characters after modifier starts
        }
        break;
      }
    }
    ++i;
  }

  Locale locale;
  locale.setLang(lang);
  if (!country.empty()) locale.setCountry(country);
  if (!encoding.empty()) locale.setEncoding(encoding);
  if (!mod.empty()) locale.setModifier(mod);
  return locale;
}

// Default constructor
Locale::Locale() = default;

// Constructor from string view
Locale::Locale(std::string_view data) { *this = Locale::parse(data); }

// Converts locale to string representation
std::string Locale::toString() const
{
  std::string s = lang();
  if (country())
  {
    s += '_';
    s.append(*country());
  }
  if (encoding())
  {
    s += '.';
    s.append(*encoding());
  }
  if (modifier())
  {
    s += '@';
    s.append(*modifier());
  }
  return s;
}

// Output stream operator for Locale
std::ostream &operator<<(std::ostream &ofs, const xdgpp::Locale &locale)
{
  ofs << locale.toString();
  return ofs;
}

