#include "ztimer.h"

// ZTimer constructor (default)
ZTimer::ZTimer()
{
}

// ZTimer constructor with duration
ZTimer::ZTimer(Duration duration_ms) : m_timerDuration(duration_ms)
{
}

// ZTimer constructor with duration and callback
ZTimer::ZTimer(Duration duration_ms, CallbackFunc callback)
            : m_timerDuration(duration_ms), m_callback(callback)
{
}

// Destructor: stops the timer
ZTimer::~ZTimer()
{
    Stop();
}

// Start the timer
void ZTimer::Start()
{
    m_startTime = Clock::now();
    m_currentTime = m_startTime;
    m_timerStarted = true;
    m_timerFinished = false;
}

// Stop the timer
void ZTimer::Stop()
{
    m_timerStarted = false;
}

// Set duration (only if not running)
void ZTimer::SetDuration(Duration duration_ms)
{
    if (m_timerStarted)
        return;
    m_timerDuration = duration_ms;
}

// Set callback (only if not running)
void ZTimer::SetCallback(std::function<void()> callback)
{
    if (m_timerStarted)
        return;
    m_callback = callback;
}

// Set repeating mode (only if not running)
void ZTimer::SetRepeating(bool value)
{
    if (m_timerStarted)
        return;
    m_repeatingTimer = value;
}

// Update timer state
void ZTimer::Update(Duration deltaTime)
{
    if (!m_timerStarted)
        return;

    m_currentTime += deltaTime;

    // Check if timer has completed
    if (m_currentTime >= m_startTime + m_timerDuration)
    {
        m_callback();

        if (!m_repeatingTimer)
        {
            Stop();
            m_timerFinished = true;
        }
        else
            Start();
    }
}

#include "sealock.h"
