// Constants and global variables for pointer register management
static constexpr uint32_t kPointerRegisterSize = 100000;
static std::array<void *, kPointerRegisterSize> gPointerRegister;
static std::queue<uint32_t> gPointerRegisterFreeList;
static uint32_t gPointerRegisterBackIndex = 1;

// Check if a pointer ID is invalid
inline bool IsInvalidPointerID( uint32_t id )
{
    return id == OTDUPointer::kInvalidID || id == 0xcdcdcdcd ||
           id == 0xdddddddd || id == 0x0;
}

// Allocate a new pointer entry from the free list or increment the back index
static uint32_t AllocatePointerEntry()
{
    uint32_t ID = OTDUPointer::kInvalidID;
    if ( !gPointerRegisterFreeList.empty() )
    {
        ID = gPointerRegisterFreeList.front();
        gPointerRegisterFreeList.pop();
    }
    else
    {
        ID = gPointerRegisterBackIndex++;
    }
    return ID;
}

// Initialize the pointer register array
static bool InitializePointerRegister()
{
    gPointerRegister[0] = nullptr;
    return true;
}

// Constructor: initialize register and allocate an ID
OTDUPointer::OTDUPointer()
{
    InitializePointerRegister(); // TODO: Probably want to call this somewhere
                                 // near the entry point instead...
    OTDU_ASSERT_FATAL( gPointerRegisterBackIndex < kPointerRegisterSize );
    if ( !gPointerRegisterFreeList.empty() )
    {
        ID = gPointerRegisterFreeList.front();
        gPointerRegisterFreeList.pop();
    }
    else
    {
        ID = gPointerRegisterBackIndex++;
    }
}

// Destructor: return ID to the free list if valid
OTDUPointer::~OTDUPointer()
{
    if ( !IsInvalidPointerID( ID ) )
        gPointerRegisterFreeList.push( ID );
}

// Assignment operator: store pointer in the register
OTDUPointer &OTDUPointer::operator=( const void *pPointer )
{
    OTDU_ASSERT( ID != OTDUPointer::kInvalidID );
    if ( IsInvalidPointerID( ID ) )
    {
        ID = AllocatePointerEntry();
    }
    gPointerRegister[ID] = const_cast<void *>( pPointer );
    return *this;
}

// Retrieve stored pointer by ID, return nullptr if invalid
void *OTDUPointer::retrievePointerFromCache() const
{
    return !IsInvalidPointerID( ID ) ? gPointerRegister[ID] : nullptr;
}

