// Entity constructor
Entity::Entity(World* world) : m_world(world) {}

// Move entity to position with rotation
void Entity::MoveTo(mc::Vector3f pos, float yaw, float pitch)
{
    pos.y += heightOffset;
    position = pos;
    oldPosition = pos;
    deltaPosition = pos;
    yRot = yaw;
    xRot = pitch;
    SetPos(pos);
}

// Move entity relative to its current facing direction
void Entity::MoveRelative(float x, float z, float speed)
{
    float len = x * x + z * z;
    if (len >= 0.01f)
    {
        len = speed / std::sqrt(len);
        x *= len;
        z *= len;
        // Use cyclic yRot (between 0 and 360 degrees)
        float yRotRad = (this->yRot * M_PI / 180.0f);
        float sinYaw = std::sin(yRotRad);
        float cosYaw = std::cos(yRotRad);
        deltaPosition.x += x * cosYaw - z * sinYaw;
        deltaPosition.z += z * cosYaw + x * sinYaw;
    }
}

// Set entity rotation
void Entity::SetRot(float yaw, float pitch)
{
    yRot = yaw;
    xRot = pitch;
}

// Set entity position and update bounding box
void Entity::SetPos(mc::Vector3f pos)
{
    position = pos;
    float halfSize = bbWidth / 2;
    float lowY = pos.y - heightOffset + ySlideOffset;
    bb = AABB(pos.x - halfSize, lowY, pos.z - halfSize, pos.x + halfSize, lowY + bbHeight, pos.z + halfSize);
}

// Reset position (placeholder)
void Entity::ResetPos() {}

// Set entity size
void Entity::SetSize(float bbWidth, float bbHeight)
{
    this->bbWidth = bbWidth;
    this->bbHeight = bbHeight;
}

// Turn entity by rotation deltas
void Entity::Turn(float yRotDelta, float xRotDelta)
{
    yRot += yRotDelta * 0.15f;
    xRot = std::clamp(xRot - xRotDelta * 0.15f, -90.0f, 90.0f);
    yRot = std::remainder(yRot, 360.0f);
    if (yRot < 0.0f)
        yRot += 360.0f;
}

// Check for fall damage
void Entity::CheckFallDamage(float deltaY, bool HitGround)
{
    if (HitGround)
    {
        if (m_fallDistance > 0.0f)
        {
            CauseFallDamage(m_fallDistance);
            m_fallDistance = 0.0f;
        }
    }
    else if (deltaY < 0.0f)
    {
        m_fallDistance -= deltaY;
    }
}

// Apply fall damage (placeholder)
void Entity::CauseFallDamage(float distance) {}

// Update entity state per tick
void Entity::Tick()
{
    deltaPosition = position;
}

#ifdef _MSC_VER
#include <windows.h>

typedef HRESULT(FAR PASCAL* p_SetThreadDescription)(void*, const wchar_t*);

#define EXCEPTION_SET_THREAD_NAME ((DWORD)0x406D1388)

typedef struct _THREADNAME_INFO
{
    DWORD dwType;     /* must be 0x1000 */
    LPCSTR szName;    /* pointer to name (in user addr space) */
    DWORD dwThreadID; /* thread ID (-1=caller thread) */
    DWORD dwFlags;    /* reserved for future use, must be zero */
} THREADNAME_INFO;

void SetThreadName(DWORD dwThreadID, LPCSTR szThreadName)
{
    THREADNAME_INFO info;
    DWORD infosize;
    HANDLE hThread;

    /* because loonix is SHIT and limits thread names to 16 bytes */
    wchar_t thr_name_w[16];
    p_SetThreadDescription _SetThreadDescription;

    /* current win10 flights now have a new named-thread API, let's try to use
     * that first! */
    /* first, dlsym(2) the new call from system library */
    hThread = NULL;
    _SetThreadDescription = (p_SetThreadDescription)GetProcAddress(GetModuleHandle("kernel32"), "SetThreadDescription");

    if (_SetThreadDescription)
    {
        /* grab another reference to the thread */
        hThread = OpenThread(THREAD_SET_LIMITED_INFORMATION, FALSE, dwThreadID);

        /* windows takes unicode, our input is utf-8 or plain ascii */
        MultiByteToWideChar(CP_ACP, 0, szThreadName, -1, thr_name_w, 16);

        if (hThread)
            _SetThreadDescription(hThread, thr_name_w);
        else
            goto old; /* for whatever reason, we couldn't get a handle to the thread.
                         Just use the old method. */
    }
    else
    {
    old:
        info.dwType = 0x1000;
        info.szName = szThreadName;
        info.dwThreadID = dwThreadID;
        info.dwFlags = 0;
        infosize = sizeof(info) / sizeof(DWORD);

        __try
        {
            RaiseException(EXCEPTION_SET_THREAD_NAME, 0, infosize, (DWORD*)&info);
        }
        __except (EXCEPTION_EXECUTE_HANDLER)
        {}
    }

    /* clean up */
    if (hThread)
        CloseHandle(hThread);
}
#endif

