// Main entry point
auto main() -> int
{
    // Initialize logger
    logger::initialize();

    const auto title = std::format("{} {}", PROJECT_NAME, PROJECT_VERSION);

    spdlog::info("{} created by jonah/nopjo", title);
    spdlog::info("Github: https://github.com/nopjo/roblox-dumper\n");

    // Attach to Roblox process
    if (!process::g_process.attach("RobloxPlayerBeta.exe"))
    {
        MessageBoxA(
            nullptr,
            "Failed to attach to Roblox, please rerun the Dumper when Roblox has fully loaded.",
            title.c_str(), MB_OK | MB_ICONERROR);
        return 1;
    }

    spdlog::info("Attached to Roblox. PID: {}\n", process::g_process.get_pid());

    // Start control server
    if (!control::g_control.start(8080))
    {
        MessageBoxA(nullptr,
                    "Failed to start control server, make sure you have no applications running on "
                    "port 8080.",
                    title.c_str(), MB_OK | MB_ICONERROR);
        return 1;
    }

    spdlog::info("Control server started on port 8080\n");

    // Measure dump duration
    const auto start_time = std::chrono::steady_clock::now();
    dumper::g_dumper.start();
    const auto end_time = std::chrono::steady_clock::now();
    const auto elapsed =
        std::chrono::duration_cast<std::chrono::milliseconds>(end_time - start_time);

    spdlog::info("Finished in {} ms ({:.2f} seconds)", elapsed.count(), elapsed.count() / 1000.0);

    // Write output files
    dumper::writer::g_header_writer.write("offsets", elapsed);
    dumper::writer::g_json_writer.write("offsets", elapsed);
    dumper::writer::g_python_writer.write("offsets", elapsed);
    dumper::writer::g_csharp_writer.write("offsets", elapsed);

    // Print error summary
    logger::print_error_summary();

    return 0;
}

#include "mwm_diff/diff.hpp"
#include "base/cancellable.hpp"
#include <cstring>
#include <iostream>

// Main function for mwm diff tool
int main(int argc, char ** argv)
{
    // Lambda to show usage information
    auto const ShowUsage = [argv]()
    {
        std::cout << "Usage: " << argv[0]
                  << " make|apply olderMWMPath newerMWMPath diffPath\n"
                     "make\n"
                     "  Creates the diff between newer and older MWMs at `diffPath`\n"
                     "apply\n"
                     "  Applies the diff at `diffPath` to the mwm at `olderMWMPath` and stores result at `newerMWMPath`.\n"
                     "WARNING: THERE IS NO MWM VALIDITY CHECK!\n";
    };

    // Check argument count
    if (argc < 5)
    {
        ShowUsage();
        return -1;
    }

    // Lambda to compare command string
    auto const IsEqualUsage = [argv](char const * s) { return 0 == std::strcmp(argv[1], s); };

    // Extract path arguments
    char const *olderMWMPath{argv[2]}, *newerMWMPath{argv[3]}, *diffPath{argv[4]};

    // Handle 'make' command
    if (IsEqualUsage("make"))
    {
        if (generator::mwm_diff::MakeDiff(olderMWMPath, newerMWMPath, diffPath))
            return 0;
    }
    // Handle 'apply' command
    else if (IsEqualUsage("apply"))
    {
        base::Cancellable cancellable;
        auto const res = generator::mwm_diff::ApplyDiff(olderMWMPath, newerMWMPath, diffPath, cancellable);
        if (res == generator::mwm_diff::DiffApplicationResult::Ok)
            return 0;
    }
    // Invalid command
    else
        ShowUsage();

    return -1;  // Failed or cancelled
}

