    {                                                   \
        const std::string json(jsonstr);                \
        fmt::println("{}", json);                       \
                                                        \
        auto res = JsonImporter::import(batch, json);   \
        fmt::println("{}\n", res.error().fmtMessage()); \
        ASSERT_FALSE(res);                              \
    }

