    INVALID_JSON("[]");
    INVALID_JSON("[ {} ]");
    INVALID_JSON("[ { \"hello\": \"world\" } ]");
    INVALID_JSON("[ { \"id\": 5.2 } ]");
    INVALID_JSON("[ { \"id\": \"hello\" } ]");
    INVALID_JSON("[ { \"id\": true } ]");
    INVALID_JSON("[ { \"id\": -5 } ]");
    INVALID_JSON("[ { \"id\": 5 } ]");
    INVALID_JSON("[ { \"id\": {} } ]");
    INVALID_JSON("[ { \"id\": [] } ]");
    INVALID_JSON("[ { \"id\": 5, \"hello\": [] } ]");
