    INVALID_JSON("[ { \"id\": 5, \"vector\": {} } ]");
    INVALID_JSON("[ { \"id\": 5, \"vector\": [] } ]");
    INVALID_JSON("[ { \"id\": 5, \"vector\": [5] } ]");
    INVALID_JSON("[ { \"id\": 5, \"vector\": [[]] } ]");
