// Draws a bar representing the meter
void DebugMeter::DrawBar(
    float startNorm, 
    float endNorm, 
    const Hmx::Color color, 
    float scaleX, 
    float scaleY
) {
    float rectWidth = width * endNorm;
    float rectHeight = height * scaleX;
    float rectX = width * startNorm + x;
    float rectY = height * scaleY + y;

    TheRnd.DrawRectScreen(
        Hmx::Rect(rectX, rectY, rectWidth, rectHeight), 
        color, 
        nullptr, 
        nullptr, 
        nullptr
    );
}

