  ASSERT(g_fidWorkingTimespan, (jni::DescribeException()));
  g_fidClosedTimespans =
      env->GetFieldID(g_clazzTimetable, "closedTimespans", "[Lapp/organicmaps/sdk/editor/data/Timespan;");
