#include "MsDbMgr.h"
#include <stdio.h>
#include <string>

// Singleton instance and mutex
unique_ptr<MsDbMgr> MsDbMgr::m_instance;
mutex MsDbMgr::m_mutex;

// Constructor
MsDbMgr::MsDbMgr() : m_sql(nullptr) {}

// Destructor - closes database connection
MsDbMgr::~MsDbMgr() {
    if (m_sql) {
        sqlite3_close(m_sql);
    }
}

// Initialize database and create tables
int MsDbMgr::Init()
{
    int rc = sqlite3_open("conf/media_server.db", &m_sql);
    if (rc) {
        printf("Can't open database: %s\n", sqlite3_errmsg(m_sql));
        return -1;
    }

    char *zErrMsg = 0;
    string sql;

    // Create t_file table
    sql = "create table if not exists t_file (\
        file_id    INTEGER PRIMARY KEY,\
        name       TEXT NOT NULL,\
        size       INTEGER NOT NULL,\
        codec      TEXT NOT NULL,\
        res        TEXT NOT NULL,\
        duration   REAL DEFAULT 0,\
        frame_rate REAL DEFAULT 0\
        )";
    rc = sqlite3_exec(m_sql, sql.c_str(), NULL, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        printf("database error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        return 1;
    }

    // Create device table
    sql = "create table if not exists device (\
        id INTEGER PRIMARY KEY ,\
        device_id TEXT NOT NULL UNIQUE,\
        parent_id TEXT NOT NULL,\
        domain_id TEXT NOT NULL,\
        name TEXT NOT NULL,\
        status TEXT NOT NULL,\
        manufacturer TEXT NOT NULL,\
        model TEXT NOT NULL,\
        owner TEXT NOT NULL,\
        civil_code TEXT NOT NULL,\
        address TEXT NOT NULL,\
        ip_addr TEXT NOT NULL,\
        user TEXT NOT NULL,\
        pass TEXT NOT NULL,\
        longitude  TEXT NOT NULL,\
        latitude  TEXT NOT NULL,\
        url TEXT NOT NULL,\
        ptz_type INTEGER NOT NULL,\
        type INTEGER NOT NULL,\
        protocol INTEGER NOT NULL,\
        port INTEGER NOT NULL,\
        bind_ip  TEXT NOT NULL,\
        remark  TEXT NOT NULL,\
        codec TEXT DEFAULT 'unknown',\
        resolution TEXT DEFAULT 'unknown',\
        onvif_profile  TEXT DEFAULT '',\
        onvif_ptz_url  TEXT DEFAULT '' \
        )";
    rc = sqlite3_exec(m_sql, sql.c_str(), NULL, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        printf("database error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        return 1;
    }

    // Create group_dev table
    sql = "create table if not exists group_dev  (\
            group_id  TEXT NOT NULL,\
            device_id  TEXT NOT NULL,\
            name  TEXT NOT NULL,\
            type  INTEGER NOT NULL,\
            PRIMARY KEY( group_id ,  device_id ) \
            ) ";
    rc = sqlite3_exec(m_sql, sql.c_str(), NULL, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        printf("database error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        return 1;
    }

    return 0;
}

// Get database handle with locking
sqlite3 *MsDbMgr::GetSql()
{
    m_sqlMutex.lock();
    return m_sql;
}

// Release database handle lock
void MsDbMgr::RelSql()
{
    m_sqlMutex.unlock();
}

// Singleton instance getter
MsDbMgr *MsDbMgr::Instance()
{
    if (MsDbMgr::m_instance.get()) {
        return MsDbMgr::m_instance.get();
    } else {
        lock_guard<mutex> lk(MsDbMgr::m_mutex);
        if (MsDbMgr::m_instance.get()) {
            return MsDbMgr::m_instance.get();
        } else {
            MsDbMgr::m_instance = make_unique<MsDbMgr>();
            return MsDbMgr::m_instance.get();
        }
    }
}

#include "sdfg/symbolic/sets.h"
#include <gtest/gtest.h>
#include "sdfg/symbolic/maps.h"
#include "sdfg/types/scalar.h"

using namespace sdfg;

// Test for disjointness of stencil 7-point expressions
TEST(MapsTest, IsDisjoint_Stencil7P) {
    types::Scalar desc_i64(types::PrimitiveType::Int32);
    types::Scalar desc_i32(types::PrimitiveType::Int32);

    // Bounds
    auto _19 = symbolic::symbol("_19");
    auto assum_19 = symbolic::Assumption::create(_19, desc_i32);
    assum_19.lower_bound_deprecated(symbolic::one());
    assum_19.constant(true);

    auto _1 = symbolic::symbol("_1");
    auto assum_1 = symbolic::Assumption::create(_1, desc_i64);
    assum_1.lower_bound_deprecated(symbolic::one());
    assum_1.constant(true);

    auto _2 = symbolic::symbol("_2");
    auto assum_2 = symbolic::Assumption::create(_2, desc_i64);
    assum_2.lower_bound_deprecated(symbolic::one());
    assum_2.constant(true);

    auto _3 = symbolic::symbol("_3");
    auto assum_3 = symbolic::Assumption::create(_3, desc_i64);
    assum_3.lower_bound_deprecated(symbolic::one());
    assum_3.constant(true);

    // Indvars
    auto _13 = symbolic::symbol("_13");
    auto assum_13 = symbolic::Assumption::create(_13, desc_i64);
    assum_13.lower_bound_deprecated(symbolic::zero());
    assum_13.upper_bound_deprecated(symbolic::sub(_19, symbolic::one()));
    assum_13.map(symbolic::add(_13, symbolic::one()));

    auto _24 = symbolic::symbol("_24");
    auto assum_24 = symbolic::Assumption::create(_24, desc_i64);
    assum_24.lower_bound_deprecated(symbolic::zero());
    assum_24.upper_bound_deprecated(symbolic::sub(_1, symbolic::one()));
    assum_24.map(symbolic::add(_24, symbolic::one()));

    auto _28 = symbolic::symbol("_28");
    auto assum_28 = symbolic::Assumption::create(_28, desc_i64);
    assum_28.lower_bound_deprecated(symbolic::zero());
    assum_28.upper_bound_deprecated(symbolic::sub(_2, symbolic::one()));
    assum_28.map(symbolic::add(_28, symbolic::one()));

    auto _32 = symbolic::symbol("_32");
    auto assum_32 = symbolic::Assumption::create(_32, desc_i64);
    assum_32.lower_bound_deprecated(symbolic::zero());
    assum_32.upper_bound_deprecated(symbolic::sub(_3, symbolic::one()));
    assum_32.map(symbolic::add(_32, symbolic::one()));

    symbolic::Assumptions assums1;
    assums1.insert({_13, assum_13});
    assums1.insert({_24, assum_24});
    assums1.insert({_28, assum_28});
    assums1.insert({_32, assum_32});
    assums1.insert({_19, assum_19});
    assums1.insert({_1, assum_1});
    assums1.insert({_2, assum_2});
    assums1.insert({_3, assum_3});

    auto assums2 = assums1;

    // 1 + _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto stride_1 = symbolic::add(symbolic::integer(2), _1);
    auto stride_2 = symbolic::add(symbolic::integer(2), _2);
    auto stride_3 = symbolic::add(symbolic::integer(2), _3);
    auto offset_32 = symbolic::add(symbolic::one(), _32);
    auto offset_28 = symbolic::add(symbolic::one(), _28);
    auto offset_24 = symbolic::add(symbolic::one(), _24);

    auto expr1 = symbolic::add(offset_32, symbolic::mul(stride_3, offset_28));
    expr1 = symbolic::add(expr1, symbolic::mul(symbolic::mul(stride_3, stride_2), offset_24));
    expr1 = symbolic::add(expr1, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));

    // 1 + _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*_24 + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expr2 = symbolic::add(offset_32, symbolic::mul(stride_3, offset_28));
    expr2 = symbolic::add(expr2, symbolic::mul(symbolic::mul(stride_3, stride_2), _24));
    expr2 = symbolic::add(expr2, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));

    EXPECT_FALSE(symbolic::maps::intersects({expr1}, {expr2}, _13, assums1, assums2));
    EXPECT_TRUE(symbolic::maps::intersects({expr1}, {expr2}, _24, assums1, assums2));

    // 1 + _32 + (2 + _3)*_28 + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expr3 = symbolic::add(offset_32, symbolic::mul(stride_3, _28));
    expr3 = symbolic::add(expr3, symbolic::mul(symbolic::mul(stride_3, stride_2), offset_24));
    expr3 = symbolic::add(expr3, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));

    EXPECT_FALSE(symbolic::maps::intersects({expr1}, {expr3}, _13, assums1, assums2));
    EXPECT_TRUE(symbolic::maps::intersects({expr1}, {expr3}, _28, assums1, assums2));

    // _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expr4 = symbolic::add(_32, symbolic::mul(stride_3, offset_28));
    expr4 = symbolic::add(expr4, symbolic::mul(symbolic::mul(stride_3, stride_2), offset_24));
    expr4 = symbolic::add(expr4, symbolic::mul(symbolic::mul(symbolic::mul(stride_3, stride_2), stride_1), _13));

    EXPECT_FALSE(symbolic::maps::intersects({expr1}, {expr4}, _13, assums1, assums2));
    EXPECT_TRUE(symbolic::maps::intersects({expr1}, {expr4}, _32, assums1, assums2));
}

#include "test.h"

// Template function to compute a 128-bit hash using MurmurHash3
template <typename T>
Array<uint64_t, 2> hash(const T &item) noexcept
{
    auto data = memory::viewCast(item);
    Array<uint64_t, 2> hashValue;
    MurmurHash3_x64_128(data, _nc<int>(data.size()), 0, hashValue.data());
    return hashValue;
}

// Compute the nth hash value for Bloom filter indexing
uint64_t nthHash(uint8_t n, uint64_t hashA, uint64_t hashB,
                 uint64_t filterSize) noexcept
{
    return (hashA + n * hashB) % filterSize;
}

// Bloom filter implementation
struct BloomFilter
{
    // Constructor: initialize with given size and number of hash functions
    BloomFilter(uint64_t size, uint8_t numHashes) noexcept
        : m_bits(size), m_numHashes(numHashes)
    {
    }

    // Add an item to the filter
    template <typename T>
    void add(const T &item) noexcept
    {
        auto data = memory::viewCast(item);
        auto hashValues = hash(data);
        for (uint8_t n = 0; n < m_numHashes; n++)
        {
            m_bits[nthHash(n, hashValues[0], hashValues[1], m_bits.size())] =
                true;
        }
    }

    // Check if an item might be in the filter
    template <typename T>
    bool possiblyContains(const T &item) const noexcept
    {
        auto data = memory::viewCast(item);
        auto hashValues = hash(data);
        for (uint8_t n = 0; n < m_numHashes; n++)
        {
            if (!m_bits[nthHash(n, hashValues[0], hashValues[1],
                                m_bits.size())])
            {
                return false;
            }
        }
        return true;
    }

private:
    uint8_t m_numHashes;
    std::vector<bool> m_bits;
};

// Unit test for BloomFilter
TEST_CASE("util::BloomFilter")
{
    BloomFilter filter(1'000, 13);

    // Add every even number
    auto added = 0;
    for (auto i = 0; i < 1'000; i++)
    {
        if (!(i % 2))
        {
            filter.add(i);
            added++;
        }
    }

    // Verify correctness: evens should be possibly present, odds definitely absent
    auto possible = 0, notPossible = 0, errors = 0;
    for (auto i = 0; i < 1'000; i++)
    {
        auto possiblyContains = false;
        if (!(i % 2))
            possiblyContains = filter.possiblyContains(i);
        else
            possiblyContains = filter.possiblyContains(i);

        if (possiblyContains)
            possible++;
        else
        {
            notPossible++;
            if (!(i % 2))
            {
                LOG(Test, "Filter incorrectly says {} is not possible...", i);
                errors++;
            }
        }
    }

    LOG(Test, "Possible: {,c} Not possible: {,c} Added: {,c} Errors: {,c}",
        possible, notPossible, added, errors);
}

#include <Genode/Graphics/Font.hpp>
#include <Genode/UI/InputField.hpp>
#include <Genode/Utilities/StringHelper.hpp>
#include <SFML/Window/Clipboard.hpp>

// Namespace for helper functions related to word boundary detection
namespace
{
    // Checks if a character acts as a word separator (space, tab, or punctuation)
    bool IsSeparator(const std::uint32_t ch)
    {
        if (ch == U' ' || ch == U'\t')
            return true;

        static constexpr std::u32string_view separators = U".,;:!?()[]{}/\\-_@#%&*";
        return separators.find(static_cast<char32_t>(ch)) != std::u32string_view::npos;
    }

    // Finds the starting index of the word containing or preceding 'from'
    size_t FindWordStart(const sf::String& str, const size_t from)
    {
        size_t left = from;

        // Skip over separators first
        while (left > 0)
        {
            const auto ch = str[left - 1];
            if (IsSeparator(ch))
                left--;
            else
                break;
        }

        // Then skip over non-separators to find the start of the word
        while (left > 0)
        {
            const auto ch = str[left - 1];
            if (!IsSeparator(ch))
                left--;
            else
                break;
        }

        return left;
    }

    // Finds the ending index of the word containing or following 'from'
    size_t FindWordEnd(const sf::String& str, const size_t from)
    {
        size_t right = from;
        const size_t size = str.getSize();

        // Skip over non-separators first
        while (right < size)
        {
            const auto ch = str[right];
            if (IsSeparator(ch))
                right++;
            else
                break;
        }

        // Then skip over separators to find the end of the word
        while (right < size)
        {
            const auto ch = str[right];
            if (!IsSeparator(ch))
                right++;
            else
                break;
        }

        return right;
    }
}

