// Global vectors for the sqrt decomposition structure
vector<long long> a, b, lazy;

struct SqrtDecomposition {
  const int block_size, n;
  vector<int> ls, rs;
  vector<bool> to_be_eval;
  vector<vector<pair<int,int>>> first;

  explicit SqrtDecomposition(const int n_)
      : block_size((int)max(1.0, floor(sqrt((double)n_)))),
        n((n_ + block_size - 1) / block_size) {
    ls.resize(n);
    rs.resize(n);
    to_be_eval.assign(n, false);
    first.resize(n);
    for (int i = 0; i < n; ++i) {
      ls[i] = block_size * i;
      rs[i] = (i + 1 == n ? n_ : block_size * (i + 1));
      first[i].reserve((rs[i] - ls[i]) * 2);
    }
  }

  // Rebuilds the map for a specific block
  void rebuild_block(int b) {
    vector<pair<int,int>> tmp;
    tmp.reserve(rs[b] - ls[b]);
    for (int i = ls[b]; i < rs[b]; ++i) tmp.emplace_back((int)a[i], i);
    sort(tmp.begin(), tmp.end(), [](const pair<int,int>& x, const pair<int,int>& y){
      if (x.first != y.first) return x.first < y.first;
      return x.second < y.second;
    });
    auto &mp = first[b];
    mp.clear();
    mp.reserve(tmp.size());
    int last_key = INT_MIN;
    for (auto &p : tmp) {
      if (p.first != last_key) {
        last_key = p.first;
        mp.emplace_back(p.first, p.second);
      }
    }
  }

  // Builds maps for all blocks
  void build_maps() {
    for (int b = 0; b < n; ++b) rebuild_block(b);
  }

  // Gets the real value at index idx considering lazy propagation
  inline int get_real(int idx) const {
    int blk = idx / block_size;
    return (int)(a[idx] + lazy[blk]);
  }

  // Finds the leftmost index <= uptoIdx with value equal to target
  int find_leftmost_equal(int uptoIdx, int target) const {
    int br = uptoIdx / block_size;
    for (int b = 0; b < br; ++b) {
      int key = target - (int)lazy[b];
      const auto &vec = first[b];
      auto it = lower_bound(vec.begin(), vec.end(), key,
        [](const pair<int,int>& p, int val){ return p.first < val; });
      if (it != vec.end() && it->first == key) return it->second;
    }
    int key_lazy = (int)lazy[br];
    for (int i = ls[br]; i <= uptoIdx; ++i) {
      if ((int)(a[i] + key_lazy) == target) return i;
    }
    return -1;
  }

  // Performs range add and rebuilds affected blocks
  void range_add_and_fix(int l, int r, int val) {
    if (r <= l) return;
    const int b_l = l / block_size, b_r = (r - 1) / block_size;
    update(l, r, val);
    if (b_l == b_r) {
      rebuild_block(b_l);
    } else {
      if (l != ls[b_l]) rebuild_block(b_l);
      if (r != rs[b_r]) rebuild_block(b_r);
    }
  }

  // Updates a single element in partial mode
  template <typename T>
  void partial_update(const int idx, const T val) {
    a[idx] += val;
    b[idx / block_size] += val;
  }

  // Updates an entire block using lazy propagation
  template <typename T>
  void total_update(const int idx, const T val) {
    lazy[idx] += val;
    to_be_eval[idx] = true;
  }

  // Main update function handling full and partial blocks
  template <typename T>
  void update(const int l, const int r, const T val) {
    if (r <= l) return;
    const int b_l = l / block_size, b_r = (r - 1) / block_size;
    if (b_l < b_r) {
      if (l == ls[b_l]) {
        total_update(b_l, val);
      } else {
        for (int i = l; i < rs[b_l]; ++i) {
          partial_update(i, val);
        }
      }
      for (int i = b_l + 1; i < b_r; ++i) {
        total_update(i, val);
      }
      if (r == rs[b_r]) {
        total_update(b_r, val);
      } else {
        for (int i = ls[b_r]; i < r; ++i) {
          partial_update(i, val);
        }
      }
    } else {
      for (int i = l; i < r; ++i) {
        partial_update(i, val);
      }
    }
  }

  // Queries a single element with lazy evaluation
  template <typename T>
  void partial_query(const int idx, T* val) {
    const int block = idx / block_size;
    if (to_be_eval[block]) {
      for (int i = ls[block]; i < rs[block]; ++i) {
        partial_update(i, lazy[block]);
      }
      lazy[block] = 0;
      to_be_eval[block] = false;
      const_cast<SqrtDecomposition*>(this)->rebuild_block(block);
    }
    *val += a[idx];
  }

  // Queries an entire block
  template <typename T>
  void total_query(const int idx, T* val) {
    *val += b[idx] + lazy[idx] * (rs[idx] - ls[idx]);
  }

  // Range query over [l, r)
  template <typename T>
  T query(const int l, const int r, const T id) {
    const int b_l = l / block_size, b_r = (r - 1) / block_size;
    T res = id;
    if (b_l < b_r) {
      if (l == ls[b_l]) {
        total_query(b_l, &res);
      } else {
        for (int i = l; i < rs[b_l]; ++i) {
          partial_query(i, &res);
        }
      }
      for (int i = b_l + 1; i < b_r; ++i) {
        total_query(i, &res);
      }
      if (r == rs[b_r]) {
        total_query(b_r, &res);
      } else {
        for (int i = ls[b_r]; i < r; ++i) {
          partial_query(i, &res);
        }
      }
    } else {
      for (int i = l; i < r; ++i) {
        partial_query(i, &res);
      }
    }
    return res;
  }
};

class Solution {
public:
    int longestBalanced(vector<int>& nums) 
    {
        int n = nums.size();
        int N = n + 1;
        SqrtDecomposition sd(N);
        a.assign(N, 0);
        b.assign(sd.n, 0);
        lazy.assign(sd.n, 0);
        sd.build_maps();

        int MAXV = 100000;
        vector<int> last(MAXV + 1, -1);
        int ans = 0;

        for (int r = 0; r < n; r++) {
            int x = nums[r];
            int pre = last[x];
            int d = (x & 1) ? +1 : -1;
            sd.range_add_and_fix(pre + 1, r + 1, d);
            last[x] = r;

            int t = sd.get_real(r + 1);
            int j = sd.find_leftmost_equal(r, t);
            if (j != -1)
                ans = max(ans, r - j + 1);
        }
        return ans;
    }
};

#define INVALID_BASE64_BYTE 64

#include "llvm/Support/Base64.h"

// Decodes a single base64 byte
static char decodeBase64Byte(uint8_t Ch) {
    constexpr char Inv = INVALID_BASE64_BYTE;
    static const char DecodeTable[] = {
        Inv, Inv, Inv, Inv, Inv, Inv, Inv, Inv, // ........
        Inv, Inv, Inv, Inv, Inv, Inv, Inv, Inv, // ........
        Inv, Inv, Inv, Inv, Inv, Inv, Inv, Inv, // ........
        Inv, Inv, Inv, Inv, Inv, Inv, Inv, Inv, // ........
        Inv, Inv, Inv, Inv, Inv, Inv, Inv, Inv, // ........
        Inv, Inv, Inv, 62,  Inv, Inv, Inv, 63,  // ...+.../
        52,  53,  54,  55,  56,  57,  58,  59,  // 01234567
        60,  61,  Inv, Inv, Inv, 0,   Inv, Inv, // 89...=..
        Inv, 0,   1,   2,   3,   4,   5,   6,   // .ABCDEFG
        7,   8,   9,   10,  11,  12,  13,  14,  // HIJKLMNO
        15,  16,  17,  18,  19,  20,  21,  22,  // PQRSTUVW
        23,  24,  25,  Inv, Inv, Inv, Inv, Inv, // XYZ.....
        Inv, 26,  27,  28,  29,  30,  31,  32,  // .abcdefg
        33,  34,  35,  36,  37,  38,  39,  40,  // hijklmno
        41,  42,  43,  44,  45,  46,  47,  48,  // pqrstuvw
        49,  50,  51                            // xyz.....
    };

    if (Ch >= sizeof(DecodeTable))
        return Inv;

    return DecodeTable[Ch];
}

// Decodes a base64-encoded string into raw bytes
llvm::Error llvm::decodeBase64(llvm::StringRef Input,
                               std::vector<char> &Output) {
    constexpr char Base64InvalidByte = INVALID_BASE64_BYTE;

    Output.clear();

    const uint64_t InputLength = Input.size();

    if (InputLength == 0)
        return Error::success();

    // Ensure input length is a multiple of 4
    if ((InputLength % 4) != 0)
        return createStringError(std::errc::illegal_byte_sequence,
                                 "Base64 encoded strings must be a multiple of 4 "
                                 "bytes in length");

    const uint64_t FirstValidEqualIdx = InputLength - 2;
    char Hex64Bytes[4];

    for (uint64_t Idx = 0; Idx < InputLength; Idx += 4) {
        for (uint64_t ByteOffset = 0; ByteOffset < 4; ++ByteOffset) {
            const uint64_t ByteIdx = Idx + ByteOffset;
            const char Byte = Input[ByteIdx];
            const char DecodedByte = decodeBase64Byte(Byte);

            bool Illegal = DecodedByte == Base64InvalidByte;

            if (!Illegal && Byte == '=') {
                if (ByteIdx < FirstValidEqualIdx) {
                    // '=' not allowed before last two positions
                    Illegal = true;
                } else if (ByteIdx == FirstValidEqualIdx &&
                           Input[ByteIdx + 1] != '=') {
                    // Second-to-last '=' without final '=' is invalid
                    Illegal = true;
                }
            }

            if (Illegal)
                return createStringError(
                    std::errc::illegal_byte_sequence,
                    "Invalid Base64 character %#2.2x at index %" PRIu64, Byte, ByteIdx);

            Hex64Bytes[ByteOffset] = DecodedByte;
        }

        // Reconstruct original bytes from 6-bit groups
        Output.push_back((Hex64Bytes[0] << 2) + ((Hex64Bytes[1] >> 4) & 0x03));
        Output.push_back((Hex64Bytes[1] << 4) + ((Hex64Bytes[2] >> 2) & 0x0f));
        Output.push_back((Hex64Bytes[2] << 6) + (Hex64Bytes[3] & 0x3f));
    }

    // Remove padding bytes if trailing '=' characters were present
    if (Input.back() == '=') {
        Output.pop_back();
        if (Input[InputLength - 2] == '=')
            Output.pop_back();
    }

    return Error::success();
}

