namespace quadrants {
namespace bit {

// Default constructor for Bitset
Bitset::Bitset() {
}

// Constructor with specified size n (rounded up to multiple of kBits)
Bitset::Bitset(int n) {
  if (n % kBits != 0) {
    n += kBits - n % kBits;
  }
  vec_ = std::vector<value_t>(n / kBits, 0);
}

// Returns total number of bits represented by this bitset
std::size_t Bitset::size() const {
  return vec_.size() * kBits;
}

// Resets all bits to zero
void Bitset::reset() {
  for (auto &value : vec_) {
    value = 0;
  }
}

// Flips the bit at position x
void Bitset::flip(int x) {
  vec_[x / kBits] ^= ((value_t)1) << (x % kBits);
}

// Checks if any bit is set to 1
bool Bitset::any() const {
  for (auto &val : vec_) {
    if (val)
      return true;
  }
  return false;
}

// Checks if no bits are set (i.e., all zeros)
bool Bitset::none() const {
  return !any();
}

// Returns a reference to the bit at position x
Bitset::reference Bitset::operator[](int x) {
  return reference(vec_, x);
}

// In-place bitwise AND with another bitset
Bitset &Bitset::operator&=(const Bitset &other) {
  const int len = vec_.size();
  QD_ASSERT(len == other.vec_.size());
  for (int i = 0; i < len; i++) {
    vec_[i] &= other.vec_[i];
  }
  return *this;
}

// Returns bitwise AND of two bitsets
Bitset Bitset::operator&(const Bitset &other) const {
  Bitset result = *this;
  result &= other;
  return result;
}

// In-place bitwise OR with another bitset
Bitset &Bitset::operator|=(const Bitset &other) {
  const int len = vec_.size();
  QD_ASSERT(len == other.vec_.size());
  for (int i = 0; i < len; i++) {
    vec_[i] |= other.vec_[i];
  }
  return *this;
}

// Returns bitwise OR of two bitsets
Bitset Bitset::operator|(const Bitset &other) const {
  Bitset result = *this;
  result |= other;
  return result;
}

// In-place bitwise XOR with another bitset
Bitset &Bitset::operator^=(const Bitset &other) {
  const int len = vec_.size();
  QD_ASSERT(len == other.vec_.size());
  for (int i = 0; i < len; i++) {
    vec_[i] ^= other.vec_[i];
  }
  return *this;
}

// Returns bitwise complement of the bitset
Bitset Bitset::operator~() const {
  Bitset result(size());
  const int len = vec_.size();
  for (int i = 0; i < len; i++) {
    result.vec_[i] = ~vec_[i];
  }
  return result;
}

// Finds the index of the first set bit (starting from 0)
int Bitset::find_first_one() const {
  return lower_bound(0);
}

// Finds the lowest index >= x that has a set bit; returns -1 if none found
int Bitset::lower_bound(int x) const {
  const int len = vec_.size();
  if (x >= len * kBits) {
    return -1;
  }
  if (x < 0) {
    x = 0;
  }
  int i = x / kBits;
  if (x % kBits != 0) {
    if (auto test = vec_[i] & (kMask ^ ((1ULL << (x % kBits)) - 1))) {
      return i * kBits + log2int(lowbit(test));
    }
    i++;
  }
  for (; i < len; i++) {
    if (vec_[i]) {
      return i * kBits + log2int(lowbit(vec_[i]));
    }
  }
  return -1;
}

// Performs in-place OR with 'other', returns list of newly set bit indices
std::vector<int> Bitset::or_eq_get_update_list(const Bitset &other) {
  const int len = vec_.size();
  QD_ASSERT(len == other.vec_.size());
  std::vector<int> result;
  for (int i = 0; i < len; i++) {
    auto update = other.vec_[i] & ~vec_[i];
    if (update) {
      vec_[i] |= update;
      for (int j = 0; j < kBits; j++) {
        if ((update >> j) & 1) {
          result.push_back((i * kBits) | j);
        }
      }
    }
  }
  return result;
}

// Reference class implementation: represents a single bit as an lvalue

// Constructor initializes internal pointer and bit mask
Bitset::reference::reference(std::vector<value_t> &vec, int x)
    : pos_(&vec[x / kBits]), digit_(((value_t)1) << (x % kBits)) {
}

// Conversion to bool: checks whether the bit is set
Bitset::reference::operator bool() const {
  return *pos_ & digit_;
}

// Bitwise NOT of the referenced bit
bool Bitset::reference::operator~() const {
  return ~*pos_ & digit_;
}

// Assignment operator for boolean values
Bitset::reference &Bitset::reference::operator=(bool x) {
  if (x)
    *pos_ |= digit_;
  else
    *pos_ &= kMask ^ digit_;
  return *this;
}

// Copy assignment from another reference
Bitset::reference &Bitset::reference::operator=(
    const Bitset::reference &other) {
  *this = bool(other);
  return *this;
}

// Flip the referenced bit
Bitset::reference &Bitset::reference::flip() {
  *pos_ ^= digit_;
  return *this;
}

// Output stream operator: prints bits in little-endian order per word
std::ostream &operator<<(std::ostream &os, const Bitset &b) {
  for (auto &val : b.vec_)
    for (int j = 0; j < Bitset::kBits; j++)
      os << ((val >> j) & 1 ? '1' : '0');
  return os;
}

}  // namespace bit

using namespace bit;

// Example usage of bit fields via macro-based helper
struct Flags : public Bits<32> {
  using Base = Bits<32>;
  QD_BIT_FIELD(bool, apple, 0);
  QD_BIT_FIELD(bool, banana, 1);
  QD_BIT_FIELD(uint8, cherry, 2);
};

QD_TEST("bit") {
  Bits<32> b;
  b.set<5>(1);
  CHECK(b.get() == 32);
  b.set<10, 8>(255);
  CHECK(b.get() == 255 * 1024 + 32);
  b.set<11, 1>(0);
  CHECK(b.get() == 255 * 1024 + 32 - 2048);
  b.set<11, 2>(3);
  CHECK(b.get() == 255 * 1024 + 32);
  b.set<11, 2>(0);
  CHECK(b.get() == 255 * 1024 + 32 - 2 * 3072);
  b.set<11, 2>(1);
  CHECK(b.get() == 255 * 1024 + 32 - 4096);

  Flags f;
  f.set_apple(true);
  CHECK(f.get_apple() == true);
  f.set_apple(false);
  CHECK(f.get_apple() == false);
  f.set_banana(true);
  CHECK(f.get_banana() == true);
  CHECK(f.get_apple() == false);
  f.set_apple(false);
  CHECK(f.get_apple() == false);
  f.set_apple(true);
  f.set_cherry(63);
  CHECK(f.get_cherry() == 63);
  f.set_banana(false);
  CHECK(f.get_cherry() == 63);

  struct Decomp {
    uint8 a, b, c, d;
  };
  uint32 v = 0xabcd1234;
  auto &dec = reinterpret_bits<Decomp>(v);
  CHECK(dec.a == 0x34);
  CHECK(dec.b == 0x12);
  CHECK(dec.c == 0xcd);
  CHECK(dec.d == 0xab);
  dec.d = 0xef;
  CHECK(v == 0xefcd1234);
  CHECK(reinterpret_bits<float32>(reinterpret_bits<uint32>(1.32_f32)) ==
        1.32_f32);
  // float64 t = 123.456789;
  // auto e = extract(t);
  // QD_P(std::get<0>(e));
  // QD_P(std::get<1>(e));
  // CHECK(t == compress(std::get<0>(e), std::get<1>(e)));
}

