}

// Instantiate parameterized tests
INSTANTIATE_TEST_SUITE_P(
  HelperTest,
  HelperTest,
  testing::Values("ICP", "PLANE_ICP", "GICP", "VGICP"),
  [](const auto& info) { return info.param; }
);

// Align using Eigen::Matrix-based interface
TEST_P(HelperTest, AlignEigen) {
  const std::string method = GetParam();
  RegistrationSetting setting;

  if (method == "ICP") {
    setting.type = RegistrationSetting::ICP;
  } else if (method == "PLANE_ICP") {
    setting.type = RegistrationSetting::PLANE_ICP;
  } else if (method == "GICP") {
    setting.type = RegistrationSetting::GICP;
  } else if (method == "VGICP") {
    setting.type = RegistrationSetting::VGICP;
  } else {
    std::cerr << "error: unknown method " << method << std::endl;
  }

  // Forward alignment test
  auto result = align(target_raw->points, source_raw->points, Eigen::Isometry3d::Identity(), setting);
  EXPECT_TRUE(compare_transformation(T_target_source, result.T_target_source));

  // Backward alignment test
  auto result2 = align(source_raw->points, target_raw->points, Eigen::Isometry3d::Identity(), setting);
  EXPECT_TRUE(compare_transformation(T_target_source, result2.T_target_source.inverse()));
}

// Align using preprocessed point clouds and voxel maps
TEST_P(HelperTest, AlignSmall) {
  const std::string method = GetParam();
  RegistrationSetting setting;

  if (method == "ICP") {
    setting.type = RegistrationSetting::ICP;
  } else if (method == "PLANE_ICP") {
    setting.type = RegistrationSetting::PLANE_ICP;
  } else if (method == "GICP") {
    setting.type = RegistrationSetting::GICP;
  } else if (method == "VGICP") {
    setting.type = RegistrationSetting::VGICP;
  } else {
    std::cerr << "error: unknown method " << method << std::endl;
  }

  RegistrationResult result;

  // Preprocess point clouds
  auto [target, target_tree] = preprocess_points(*target_raw, 0.1, 10, 1);
  auto [source, source_tree] = preprocess_points(*source_raw, 0.1, 10, 1);

  // Forward alignment
  if (method != "VGICP") {
    result = align(*target, *source, *target_tree, Eigen::Isometry3d::Identity(), setting);
  } else {
    auto target_voxelmap = create_gaussian_voxelmap(*target, 1.0);
    result = align(*target_voxelmap, *source, Eigen::Isometry3d::Identity(), setting);
  }
  EXPECT_TRUE(compare_transformation(T_target_source, result.T_target_source));

  // Backward alignment
  if (method != "VGICP") {
    result = align(*source, *target, *source_tree, Eigen::Isometry3d::Identity(), setting);
  } else {
    auto source_voxelmap = create_gaussian_voxelmap(*source, 1.0);
    result = align(*source_voxelmap, *target, Eigen::Isometry3d::Identity(), setting);
  }
  EXPECT_TRUE(compare_transformation(T_target_source, result.T_target_source.inverse()));
}

#include "humanoid_controllers/humanoidController.h"
#include <thread>

using Duration = std::chrono::duration<double>;
using Clock = std::chrono::high_resolution_clock;

bool pause_flag = false;

// Callback function to handle pause flag updates
void pauseCallback(const std_msgs::Bool::ConstPtr &msg)
{
    pause_flag = msg->data;
    std::cerr << "pause_flag: " << pause_flag << std::endl;
}

int main(int argc, char **argv)
{
    ros::Duration elapsedTime_;

    // Initialize ROS node
    ros::init(argc, argv, "humanoid_controller_node");
    ros::NodeHandle nh;

    humanoid_controller::HybridJointInterface *robot_hw;

    // Create subscriber for pause flag
    ros::Subscriber pause_sub = nh.subscribe<std_msgs::Bool>("pauseFlag", 1, pauseCallback);

    // Initialize controller
    humanoid_controller::humanoidCheaterController controller;
    if (!controller.init(robot_hw, nh))
    {
        ROS_ERROR("Failed to initialize the humanoid controller!");
        return -1;
    }

    // Record start times
    auto startTime = Clock::now();
    auto startTimeROS = ros::Time::now();
    controller.starting(startTimeROS);

    auto lastTime = startTime;

    // Create and detach thread for ROS spinning
    std::thread spin_thread([]()
                            { ros::spin(); });
    spin_thread.detach();

    // Get control frequency from parameter server
    double controlFrequency = 500.0; // Default: 500Hz
    nh.getParam("/wbc_frequency", controlFrequency);
    std::cout << "Wbc control frequency: " << controlFrequency << std::endl;

    ros::Rate rate(controlFrequency);

    struct timespec next_time;
    clock_gettime(CLOCK_MONOTONIC, &next_time);

    // Main control loop
    while (ros::ok())
    {
        if (!pause_flag)
        {
            const auto currentTime = Clock::now();

            // Compute elapsed time since last iteration
            Duration time_span = std::chrono::duration_cast<Duration>(currentTime - lastTime);
            elapsedTime_ = ros::Duration(time_span.count());
            lastTime = currentTime;

            // Execute controller update
            controller.update(ros::Time::now(), elapsedTime_);

            // Sleep to maintain desired control frequency
            const auto beforeSleep = Clock::now();

            // Advance next sleep time by one period
            next_time.tv_sec += (next_time.tv_nsec + static_cast<long>(1.0 / controlFrequency * 1e9)) / 1000000000L;
            next_time.tv_nsec = (int)(next_time.tv_nsec + static_cast<long>(1.0 / controlFrequency * 1e9)) % 1000000000;
            clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &next_time, NULL);

            // Monitor cycle time for performance issues
            const auto cycleTime = std::chrono::duration_cast<std::chrono::milliseconds>(Clock::now() - currentTime).count();
            if (cycleTime > 1000)
            {
                ROS_INFO_STREAM("Cycle time exceeded 1 second: " << cycleTime << "ms");
                const auto sleepTime = std::chrono::duration_cast<std::chrono::milliseconds>(Clock::now() - beforeSleep).count();
                ROS_INFO_STREAM("Sleep time: " << sleepTime << "ms");
                const auto proccedTime = std::chrono::duration_cast<std::chrono::milliseconds>(beforeSleep - currentTime).count();
                ROS_INFO_STREAM("proccedTime duration: " << proccedTime << "s");
            }
        }
    }

    return 0;
}

