	// Constructor for ListCommandItem
	ListCommandItem::ListCommandItem(joaat_t id, std::optional<std::string> label_override) :
	    m_Command(Commands::GetCommand<ListCommand>(id)),
	    m_LabelOverride(label_override)
	{
	}

	// Draws the list command UI element
	void ListCommandItem::Draw()
	{
		if (!m_Command)
		{
			ImGui::Text("Unknown list!");
			return;
		}

		int current_val = m_Command->GetState();
		auto& list = m_Command->GetList();

		const char* largest_string = "";
		std::size_t largest_string_len = 0;

		// Calculate the largest string width if not already cached
		if (!m_SelectedItem.has_value() || !m_ItemWidth.has_value())
		{
			for (auto& item : list)
			{
				if (item.first == current_val)
				{
					m_SelectedItem = item.second;
				}

				int length = strlen(item.second);
				if (length > largest_string_len)
				{
					largest_string = item.second;
					largest_string_len = length;
				}
			}

			if (!m_SelectedItem.has_value())
				m_SelectedItem = "";

			auto size = ImGui::CalcTextSize(largest_string);
			m_ItemWidth = size.x + 40.0f;
		}

		ImGui::SetNextItemWidth(m_ItemWidth.value());

		if (ImGui::BeginCombo(m_LabelOverride.value_or(m_Command->GetLabel()).c_str(), m_SelectedItem.value().c_str()))
		{
			for (auto& el : list)
			{
				if (ImGui::Selectable(el.second, el.first == current_val))
				{
					current_val = el.first;
					m_Command->SetState(el.first);
				}

				if (el.first == current_val)
				{
					m_SelectedItem = el.second; // just in case
					ImGui::SetItemDefaultFocus();
				}
			}
			ImGui::EndCombo();
		}
	}
}

#include "script-output-tokenizer.hpp"
#include <utility>
#include "ui/omni-painter/omni-painter.hpp"

// Tokenizes script output with ANSI escape sequences and URLs
ScriptOutputTokenizer::ScriptOutputTokenizer(QStringView str) : m_data(str) {}

std::optional<ScriptOutputTokenizer::Token> ScriptOutputTokenizer::next()
{
    static const auto urlSchemes = {QStringLiteral("http://"), QStringLiteral("https://")};

    if (std::cmp_greater_equal(m_cursor, m_data.size()))
        return {};

    Token tok;
    std::vector<uint8_t> colorCodes;

    while (std::cmp_less(m_cursor, m_data.size()))
    {
        QChar const ch = m_data.at(m_cursor);
        QStringView rem = m_data.sliced(m_cursor);

        switch (m_state)
        {
            case State::Normal:
            {
                if (ch == '\033')
                {
                    if (tok.fmt)
                        return tok;

                    m_state = State::Escape;
                }
                else
                {
                    bool const maybeUrl =
                        std::ranges::any_of(urlSchemes, [&](const auto &s) { return rem.startsWith(s); });

                    if (maybeUrl)
                    {
                        m_state = Url;
                        return tok;
                    }

                    tok.text.append(ch);
                }

                break;
            }

            case State::Url:
            {
                if (isValidUrlChar(ch))
                {
                    tok.text.append(ch);
                }
                else
                {
                    m_state = State::Normal;
                    tok.url = true;
                    return tok;
                }

                break;
            }

            case State::Escape:
            {
                if (ch == '[')
                {
                    if (!tok.text.isEmpty())
                    {
                        return tok;
                    }

                    colorCodes.clear();
                    colorCodes.emplace_back(0);
                    m_state = State::Color;
                }

                break;
            }

            case State::Color:
            {
                if (ch.isNumber())
                {
                    char const n = ch.toLatin1() - 48;
                    colorCodes.back() = colorCodes.back() * 10 + n;
                }
                else if (ch == ';')
                {
                    colorCodes.emplace_back(0);
                }
                else if (ch == 'm')
                {
                    tok.fmt = parseColor(colorCodes);
                    m_state = Normal;
                }

                break;
            }
        }

        ++m_cursor;
    }

    return tok;
}

size_t ScriptOutputTokenizer::cursor() const
{
    return m_cursor;
}

void ScriptOutputTokenizer::setCursor(size_t cursor)
{
    m_cursor = cursor;
}

ScriptOutputTokenizer::Format ScriptOutputTokenizer::parseColor(const std::vector<std::uint8_t> &codes)
{
    Format fmt;

    for (const auto code : codes)
    {
        if (code >= 30 && code <= 37)
        {
            fmt.fg = parseFgColor(code);
        }
        else if (code >= 40 && code <= 47)
        {
            fmt.bg = parseFgColor(code - 10);
        }
        else if (code == 0)
        {
            fmt.reset = true;
        }
        else if (code == 1)
        {
            // should brighten next foreground color, we ignore this for now
        }
        else if (code >= 90 && code <= 97)
        {
            fmt.fg = parseFgColor(code - 60);
        }
    }

    return fmt;
}

QColor ScriptOutputTokenizer::parseBgColor(int code)
{
    return OmniPainter::resolveColor(getStandardColor(code - 10));
}

bool ScriptOutputTokenizer::isValidUrlChar(QChar c)
{
    return c.isPrint() && !c.isSpace() && c != '"' && c != '\'' && c != ')' && c != '(';
}

QColor ScriptOutputTokenizer::parseFgColor(std::uint8_t code)
{
    return OmniPainter::resolveColor(getStandardColor(code));
}

ColorLike ScriptOutputTokenizer::getStandardColor(std::uint8_t code)
{
    switch (code)
    {
        case 0:
            return QColor(Qt::transparent);
        case 30:
            return QColor(Qt::black);
        case 31:
            return SemanticColor::Red;
        case 32:
            return SemanticColor::Green;
        case 33:
            return SemanticColor::Yellow;
        case 34:
            return SemanticColor::Blue;
        case 35:
            return SemanticColor::Magenta;
        case 36:
            return SemanticColor::Cyan;
        case 97:
            return QColor(Qt::white);
        default:
            return SemanticColor::TextPrimary;
    }
}

