// Built-in keyword list
ims_static const std::string s_kw[] =
{
    ims_keywords::subspace,
    ims_keywords::root,
    ims_keywords::section,
    ims_keywords::camera,
    ims_keywords::palette,
    ims_keywords::background,
    ims_keywords::colorize,
    ims_keywords::light,
