using namespace ChromaPrint3D;

// Projection function for Lab color space
struct LabProjection {
    const Lab& operator()(const Lab& lab) const { return lab; }
};

// Type alias for the KDTree
using TestTree = kdt::KDTree<Lab, 3, LabProjection, std::size_t, float>;

// Test nearest neighbor search with a single point
TEST(KDTree, NearestSinglePoint)
{
    std::vector<Lab> points          = {Lab(50.0f, 0.0f, 0.0f)};
    std::vector<std::size_t> indices = {0};
    TestTree tree;
    tree.Reset(points, indices, LabProjection{});

    auto result = tree.Nearest(Lab(51.0f, 0.0f, 0.0f));
    EXPECT_EQ(result.index, 0u);
    EXPECT_NEAR(result.dist2, 1.0f, 1e-5f);
}

// Test correctness of nearest neighbor search with multiple points
TEST(KDTree, NearestCorrectness)
{
    std::vector<Lab> points = {
        Lab(0.0f, 0.0f, 0.0f),
        Lab(50.0f, 0.0f, 0.0f),
        Lab(100.0f, 0.0f, 0.0f),
    };
    std::vector<std::size_t> indices = {0, 1, 2};
    TestTree tree;
    tree.Reset(points, indices, LabProjection{});

    auto r0 = tree.Nearest(Lab(10.0f, 0.0f, 0.0f));
    EXPECT_EQ(r0.index, 0u);

    auto r1 = tree.Nearest(Lab(48.0f, 0.0f, 0.0f));
    EXPECT_EQ(r1.index, 1u);

    auto r2 = tree.Nearest(Lab(90.0f, 0.0f, 0.0f));
    EXPECT_EQ(r2.index, 2u);
}

// Test k-nearest neighbors search
TEST(KDTree, KNearestNeighbors)
{
    std::vector<Lab> points;
    std::vector<std::size_t> indices;
    for (int i = 0; i < 20; ++i)
    {
        points.emplace_back(static_cast<float>(i * 5), 0.0f, 0.0f);
        indices.push_back(static_cast<std::size_t>(i));
    }

    TestTree tree;
    tree.Reset(points, indices, LabProjection{});

    std::vector<kdt::Neighbor<std::size_t, float>> neighbors;
    tree.KNearest(Lab(52.0f, 0.0f, 0.0f), 3, neighbors);

    EXPECT_EQ(neighbors.size(), 3u);

    bool found_closest = false;
    for (const auto& n : neighbors)
    {
        if (n.index == 10) { found_closest = true; }
    }
    EXPECT_TRUE(found_closest);
}

// Test exact match scenario
TEST(KDTree, ExactMatch)
{
    std::vector<Lab> points          = {Lab(42.0f, 10.0f, -5.0f)};
    std::vector<std::size_t> indices = {0};
    TestTree tree;
    tree.Reset(points, indices, LabProjection{});

    auto result = tree.Nearest(Lab(42.0f, 10.0f, -5.0f));
    EXPECT_EQ(result.index, 0u);
    EXPECT_NEAR(result.dist2, 0.0f, 1e-10f);
}

#include <iostream>
#include <cmath>

// Computes intermediate values for rotation-related calculations
int main()
{
    // Precompute powers and sums of omega components
    Scalar const c0 = pow(omega[0], 2);
    Scalar const c1 = pow(omega[1], 2);
    Scalar const c2 = pow(omega[2], 2);
    Scalar const c3 = c0 + c1 + c2;
    Scalar const c4 = sqrt(c3);
    Scalar const c5 = 1.0 / c4;
    Scalar const c6 = 0.5 * c4;
    Scalar const c7 = sin(c6);
    Scalar const c8 = c5 * c7;

    // Higher-order terms involving c3
    Scalar const c9 = pow(c3, -3.0 / 2.0);
    Scalar const c10 = c7 * c9;
    Scalar const c11 = 1.0 / c3;
    Scalar const c12 = 0.5 * c11 * cos(c6);

    // Cross-product related expressions
    Scalar const c13 = c10 * omega[0];
    Scalar const c14 = omega[0] * omega[1];
    Scalar const c15 = c12 * c14 - c13 * omega[1];
    Scalar const c16 = omega[0] * omega[2];
    Scalar const c17 = c12 * c16 - c13 * omega[2];
    Scalar const c18 = omega[1] * omega[2];
    Scalar const c19 = -c10 * c18 + c12 * c18;

    // Additional trigonometric combinations
    Scalar const c20 = 0.5 * c8;
    Scalar const c21 = sin(c4);
    Scalar const c22 = -c21 + c4;

    // Negative squared components
    Scalar const c23 = -c1;
    Scalar const c24 = -c2;
    Scalar const c25 = c23 + c24;
    Scalar const c26 = c25 * c9;

    // Cosine-based terms
    Scalar const c27 = cos(c4);
    Scalar const c28 = 1 - c27;
    Scalar const c29 = c11 * c28;
    Scalar const c30 = c29 * omega[2];
    Scalar const c31 = c22 * c9;
    Scalar const c32 = c31 * omega[1];
    Scalar const c33 = c32 * omega[0];
    Scalar const c34 = c29 * omega[1];
    Scalar const c35 = c31 * omega[2];
    Scalar const c36 = c35 * omega[0];

    // Higher-order corrections
    Scalar const c37 = 3 * c22 / pow(c3, 5.0 / 2.0);
    Scalar const c38 = c25 * c37;
    Scalar const c39 = c5 * omega[0];
    Scalar const c40 = -c27 * c39 + c39;
    Scalar const c41 = c40 * c9;
    Scalar const c42 = c0 * c37;
    Scalar const c43 = c16 * c41 + c35 - c42 * omega[2];
    Scalar const c44 = c21 * c9;
    Scalar const c45 = c14 * c44;
    Scalar const c46 = 2 * c28 / pow(c3, 2);
    Scalar const c47 = c14 * c46;
    Scalar const c48 = c45 - c47;
    Scalar const c49 = c14 * c41 + c32 - c42 * omega[1];
    Scalar const c50 = c16 * c44;
    Scalar const c51 = c16 * c46;
    Scalar const c52 = -c50 + c51;
    Scalar const c53 = -2 * c32;
    Scalar const c54 = c5 * omega[1];
    Scalar const c55 = -c27 * c54 + c54;
    Scalar const c56 = c1 * c44;
    Scalar const c57 = c1 * c46;
    Scalar const c58 = c55 * c9;
    Scalar const c59 = c16 * c58;
    Scalar const c60 = c37 * omega[0];
    Scalar const c61 = -c18 * c60;
    Scalar const c62 = c29 + c61;
    Scalar const c63 = c31 * omega[0];
    Scalar const c64 = -c1 * c60 + c14 * c58 + c63;
    Scalar const c65 = c18 * c44;
    Scalar const c66 = c18 * c46;
    Scalar const c67 = -c65 + c66;
    Scalar const c68 = -2 * c35;
    Scalar const c69 = c5 * omega[2];
    Scalar const c70 = -c27 * c69 + c69;
    Scalar const c71 = c2 * c44;
    Scalar const c72 = c2 * c46;
    Scalar const c73 = c70 * c9;
    Scalar const c74 = c14 * c73;
    Scalar const c75 = -c29 + c61;
    Scalar const c76 = c65 - c66;
    Scalar const c77 = c16 * c73 - c2 * c60 + c63;

    // More negative component combinations
    Scalar const c78 = -c0;
    Scalar const c79 = c24 + c78;
    Scalar const c80 = c29 * omega[0];
    Scalar const c81 = c32 * omega[2];
    Scalar const c82 = -2 * c63;
    Scalar const c83 = c79 * c9;
    Scalar const c84 = c0 * c44;
    Scalar const c85 = c0 * c46;
    Scalar const c86 = c18 * c41;
    Scalar const c87 = c50 - c51;
    Scalar const c88 = c37 * c79;
    Scalar const c89 = -c45 + c47;
    Scalar const c90 = c37 * omega[2];
    Scalar const c91 = -c1 * c90 + c18 * c58 + c35;
    Scalar const c92 = c37 * omega[1];
    Scalar const c93 = c18 * c73 - c2 * c92 + c32;
    Scalar const c94 = c23 + c78;
    Scalar const c95 = c9 * c94;

    // Initialize result array
    result[0] = 0;
    result[1] = 0;
    result[2] = 0;
    result[3] = -c0 * c10 + c0 * c12 + c8;
    result[4] = c15;
    result[5] = c17;
    result[6] = 0;
    result[7] = 0;
    result[8] = 0;
    result[9] = c15;
    result[10] = -c1 * c10 + c1 * c12 + c8;
    result[11] = c19;
    result[12] = 0;
    result[13] = 0;
    result[14] = 0;
    result[15] = c17;
    result[16] = c19;
    result[17] = -c10 * c2 + c12 * c2 + c8;
    result[18] = 0;
    result[19] = 0;
    result[20] = 0;
    result[21] = -c20 * omega[0];
    result[22] = -c20 * omega[1];
    result[23] = -c20 * omega[2];

    // Rotation matrix entries
    result[24] = c22 * c26 + 1;
    result[25] = -c30 + c33;
    result[26] = c34 + c36;
    result[27] = upsilon[0] * (c26 * c40 - c38 * omega[0]) + upsilon[1] * (c49 + c52) + upsilon[2] * (c43 + c48);
    result[28] = upsilon[0] * (c26 * c55 - c38 * omega[1] + c53) + upsilon[1] * (c64 + c67) + upsilon[2] * (c56 - c57 + c59 + c62);
    result[29] = upsilon[0] * (c26 * c70 - c38 * omega[2] + c68) + upsilon[1] * (-c71 + c72 + c74 + c75) + upsilon[2] * (c76 + c77);
    result[30] = c30 + c33;
    result[31] = c31 * c79 + 1;
    result[32] = -c80 + c81;
    result[33] = upsilon[0] * (c49 + c87) + upsilon[1] * (c40 * c83 - c60 * c79 + c82) + upsilon[2] * (c75 - c84 + c85 + c86);
    result[34] = upsilon[0] * (c64 + c76) + upsilon[1] * (c55 * c83 - c88 * omega[1]) + upsilon[2] * (c89 + c91);
    result[35] = upsilon[0] * (c62 + c71 - c72 + c74) + upsilon[1] * (c68 + c70 * c83 - c88 * omega[2]) + upsilon[2] * (c52 + c93);
    result[36] = -c34 + c36;
    result[37] = c80 + c81;
    result[38] = c31 * c94 + 1;
    result[39] = upsilon[0] * (c43 + c89) + upsilon[1] * (c62 + c84 - c85 + c86) + upsilon[2] * (c40 * c95 - c60 * c94 + c82);
    result[40] = upsilon[0] * (-c56 + c57 + c59 + c75) + upsilon[1] * (c48 + c91) + upsilon[2] * (c53 + c55 * c95 - c92 * c94);
    result[41] = upsilon[0] * (c67 + c77) + upsilon[1] * (c87 + c93) + upsilon[2] * (c70 * c95 - c90 * c94);

    return 0;
}

#include <string>
#include <iostream>
#include <duktape.h>
#include <duk_module_node.h>
#include "utils/string.h"
#include "utils/string_hash.h"
#include "handler/webget.h"
#include "handler/multithread.h"
#include "utils/base64/base64.h"
#include "utils/network.h"

extern int gCacheConfig;
extern std::string gProxyConfig;

std::string parseProxy(const std::string &source);

// Folds path string by resolving ".." components
std::string foldPathString(const std::string &path)
{
    std::string output = path;
    string_size pos_up, pos_slash, pos_unres = 0;

    do
    {
        pos_up = output.find("../", pos_unres);

        if(pos_up == output.npos)
            break;

        if(pos_up == 0)
        {
            pos_unres = pos_up + 3;
            continue;
        }

        pos_slash = output.rfind("/", pos_up - 1);

        if(pos_slash != output.npos)
        {
            pos_slash = output.rfind("/", pos_slash - 1);

            if(pos_slash != output.npos)
                output.erase(pos_slash + 1, pos_up - pos_slash + 2);
            else
                output.erase(0, pos_up + 3);
        }
        else
            pos_unres = pos_up + 3;

    } while(pos_up != output.npos);

    return output;
}

// Helper function to extract arguments as strings from Duktape stack
static int duktape_get_arguments_str(duk_context *ctx, duk_idx_t min_count, duk_idx_t max_count, ...)
{
    duk_idx_t nargs = duk_get_top(ctx);

    if((min_count >= 0 && nargs < min_count) || (max_count >= 0 && nargs > max_count))
        return 0;

    va_list vl;
    va_start(vl, max_count);

    for(duk_idx_t idx = 0; idx < nargs; idx++)
    {
        std::string *arg = va_arg(vl, std::string*);

        if(arg)
            *arg = duk_safe_to_string(ctx, idx);
    }

    va_end(vl);
    return 1;
}

// Module resolution callback
duk_ret_t cb_resolve_module(duk_context *ctx)
{
    const char *requested_id = duk_get_string(ctx, 0);
    const char *parent_id = duk_get_string(ctx, 1);  /* calling module */

    std::string resolved_id, parent_path = parent_id;

    if(!parent_path.empty())
    {
        string_size pos = parent_path.rfind("/");

        if(pos != parent_path.npos)
            resolved_id += parent_path.substr(0, pos + 1);
    }

    resolved_id += requested_id;

    if(!endsWith(resolved_id, ".js"))
        resolved_id += ".js";

    resolved_id = foldPathString(resolved_id);

    if(!fileExist(resolved_id))
        duk_push_undefined(ctx);
    else
        duk_push_string(ctx, resolved_id.c_str());

    return 1;  /*nrets*/
}

// Module loading callback
duk_ret_t cb_load_module(duk_context *ctx)
{
    const char *resolved_id = duk_get_string(ctx, 0);
    std::string module_source = fileGet(resolved_id, true);

    duk_push_string(ctx, module_source.c_str());
    return 1;  /*nrets*/
}

// Native print function
static duk_ret_t native_print(duk_context *ctx)
{
	duk_push_string(ctx, " ");
	duk_insert(ctx, 0);
	duk_join(ctx, duk_get_top(ctx) - 1);
	printf("%s\n", duk_safe_to_string(ctx, -1));
	return 0;
}

// Fetch function for HTTP requests
static duk_ret_t fetch(duk_context *ctx)
{
    std::string filepath, proxy, method, postdata, content;

    if(duktape_get_arguments_str(ctx, 1, 4, &filepath, &proxy, &method, &postdata) == 0)
        return 0;

    switch(hash_(method))
    {
    case "POST"_hash:
        webPost(filepath, postdata, proxy, string_array{}, &content);
        break;
    default:
        content = fetchFile(filepath, proxy, gCacheConfig);
        break;
    }

    duk_push_lstring(ctx, content.c_str(), content.size());
    return 1;
}

// atob: base64 encode
static duk_ret_t atob(duk_context *ctx)
{
    std::string data = duk_safe_to_string(ctx, -1);
    duk_push_string(ctx, base64Encode(data).c_str());
    return 1;
}

// btoa: base64 decode
static duk_ret_t btoa(duk_context *ctx)
{
    std::string data = duk_safe_to_string(ctx, -1);
    data = base64Decode(data, true);
    duk_push_lstring(ctx, data.c_str(), data.size());
    return 1;
}

// geoip lookup
static duk_ret_t getGeoIP(duk_context *ctx)
{
    std::string address, proxy;
    duktape_get_arguments_str(ctx, 1, 2, &address, &proxy);

    if(!isIPv4(address) && !isIPv6(address))
        address = hostnameToIPAddr(address);

    if(address.empty())
        duk_push_undefined(ctx);
    else
        duk_push_string(ctx, fetchFile("https://api.ip.sb/geoip/" + address, parseProxy(proxy), gCacheConfig).c_str());

    return 1;
}

// Initialize Duktape context with custom functions and modules
duk_context *duktape_init()
{
    duk_context *ctx = duk_create_heap_default();

    if(!ctx)
        return NULL;

    /// init module
    duk_push_object(ctx);
    duk_push_c_function(ctx, cb_resolve_module, DUK_VARARGS);
    duk_put_prop_string(ctx, -2, "resolve");
    duk_push_c_function(ctx, cb_load_module, DUK_VARARGS);
    duk_put_prop_string(ctx, -2, "load");
    duk_module_node_init(ctx);

    duk_push_c_function(ctx, native_print, DUK_VARARGS);
    duk_put_global_string(ctx, "print");

    duk_push_c_function(ctx, fetch, DUK_VARARGS);
    duk_put_global_string(ctx, "fetch");

    duk_push_c_function(ctx, atob, 1);
    duk_put_global_string(ctx, "atob");

    duk_push_c_function(ctx, btoa, 1);
    duk_put_global_string(ctx, "btoa");

    duk_push_c_function(ctx, getGeoIP, DUK_VARARGS);
    duk_put_global_string(ctx, "geoip");

    return ctx;
}

// Evaluate script
int duktape_peval(duk_context *ctx, const std::string &script)
{
    return duk_peval_string(ctx, script.c_str());
}

// Call JavaScript function
int duktape_call_function(duk_context *ctx, const std::string &name, size_t nargs, ...)
{
    duk_get_global_string(ctx, name.c_str());

    va_list vl;
    va_start(vl, nargs);

    size_t index = 0;

    while(index < nargs)
    {
        std::string *arg = va_arg(vl, std::string*);

        if(arg != NULL)
            duk_push_string(ctx, arg->c_str());
        else
            duk_push_undefined(ctx);

        index++;
    }

    va_end(vl);
    return duk_pcall(ctx, nargs);
}

// Push nodeInfo object to stack
int duktape_push_nodeinfo(duk_context *ctx, const nodeInfo &node)
{
    duk_push_object(ctx);

    duk_push_string(ctx, node.group.c_str());
    duk_put_prop_string(ctx, -2, "Group");

    duk_push_int(ctx, node.groupID);
    duk_put_prop_string(ctx, -2, "GroupID");

    duk_push_int(ctx, node.id);
    duk_put_prop_string(ctx, -2, "Index");

    duk_push_string(ctx, node.remarks.c_str());
    duk_put_prop_string(ctx, -2, "Remark");

    duk_push_string(ctx, node.proxyStr.c_str());
    duk_put_prop_string(ctx, -2, "ProxyInfo");

    return 0;
}

// Push nodeInfo object using define property
int duktape_push_nodeinfo_arr(duk_context *ctx, const nodeInfo &node, duk_idx_t index)
{
    duk_push_object(ctx);

    duk_push_string(ctx, "Group");
    duk_push_string(ctx, node.group.c_str());
    duk_def_prop(ctx, index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "GroupID");
    duk_push_int(ctx, node.groupID);
    duk_def_prop(ctx, index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "Index");
    duk_push_int(ctx, node.id);
    duk_def_prop(ctx, index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "Remark");
    duk_push_string(ctx, node.remarks.c_str());
    duk_def_prop(ctx, index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "ProxyInfo");
    duk_push_string(ctx, node.proxyStr.c_str());
    duk_def_prop(ctx, index - 2, DUK_DEFPROP_HAVE_VALUE);

    return 0;
}

// Get integer result from stack
int duktape_get_res_int(duk_context *ctx)
{
    int retval = duk_to_int(ctx, -1);
    duk_pop(ctx);
    return retval;
}

// Get string result from stack
std::string duktape_get_res_str(duk_context *ctx)
{
    if(duk_is_null_or_undefined(ctx, -1))
        return "";

    std::string retstr = duk_safe_to_string(ctx, -1);
    duk_pop(ctx);
    return retstr;
}

// Get boolean result from stack
bool duktape_get_res_bool(duk_context *ctx)
{
    bool ret = duk_to_boolean(ctx, -1);
    duk_pop(ctx);
    return ret;
}

// Get error stack trace
std::string duktape_get_err_stack(duk_context *ctx)
{
    duk_get_prop_string(ctx, -1, "stack");
    std::string stackstr = duk_get_string(ctx, -1);
    duk_pop(ctx);
    return stackstr;
}

#include "TypeCheckerImpl.h"

using namespace Cangjie;
using namespace AST;

// Synthesize type for parenthesized expression
Ptr<Ty> TypeChecker::TypeCheckerImpl::SynParenExpr(ASTContext& ctx, ParenExpr& pe)
{
    (void)Synthesize(ctx, pe.expr.get());

    // Check if expression or its type is invalid
    if (!pe.expr || !Ty::IsTyCorrect(pe.expr->ty)) {
        pe.ty = TypeManager::GetInvalidTy();
        return TypeManager::GetInvalidTy();
    }

    // Replace ideal type if needed
    if (pe.expr->ty->IsIdeal()) {
        ReplaceIdealTy(*pe.expr);
    }

    // Propagate type and const properties
    pe.ty = pe.expr->ty;
    if (pe.expr->isConst) {
        pe.isConst = true;
        pe.constNumValue = pe.expr->constNumValue;
    }

    return pe.ty;
}

// Check parenthesized expression against target type
bool TypeChecker::TypeCheckerImpl::ChkParenExpr(ASTContext& ctx, Ty& target, ParenExpr& pe)
{
    if (Check(ctx, &target, pe.expr.get())) {
        // When Check returns true, pe.expr must not be nullptr
        CJC_NULLPTR_CHECK(pe.expr);

        pe.ty = pe.expr->ty;
        if (pe.expr->isConst) {
            pe.isConst = true;
            pe.constNumValue = pe.expr->constNumValue;
        }
        return true;
    } else {
        pe.ty = TypeManager::GetInvalidTy();
        return false;
    }
}

