// Structure representing a pixel stack entry with RGBA components
struct StackRGBA
{
    // Add another StackRGBA to this one
    StackRGBA& operator +=(const StackRGBA& other)
    {
        this->r += other.r;
        this->g += other.g;
        this->b += other.b;
        this->a += other.a;
        return *this;
    }

    // Subtract another StackRGBA from this one
    StackRGBA& operator -=(const StackRGBA& other)
    {
        this->r -= other.r;
        this->g -= other.g;
        this->b -= other.b;
        this->a -= other.a;
        return *this;
    }

    // Subtract raw RGBA bytes from this stack entry
    StackRGBA& operator -=(const uint8_t* ptr)
    {
        this->r -= ptr[0];
        this->g -= ptr[1];
        this->b -= ptr[2];
        this->a -= ptr[3];
        return *this;
    }

    // Accumulate scaled pixel values into this stack entry
    void Add(const uint8_t* ptr, uint8_t multiplier = 1)
    {
        r += ptr[0] * multiplier;
        g += ptr[1] * multiplier;
        b += ptr[2] * multiplier;
        a += ptr[3] * multiplier;
    }

    // Reset all components to zero
    void Reset()
    {
        r = 0;
        g = 0;
        b = 0;
        a = 0;
    }

    // Component storage
    uint32_t r{}, g{}, b{}, a{};
};

// Constructor: initialize blur parameters
StackBlur::StackBlur(uint8_t p_radius, const D2D1_SIZE_U& p_size)
    : radius(std::clamp<uint8_t>(p_radius, 2, 254)), size(p_size)
{
    div = (radius * 2U) + 1U;
    cores = std::max(1U, std::thread::hardware_concurrency());
    shr_sum = stackblur_shr[radius];
    mul_sum = stackblur_mul[radius];
}

// Main execution method: performs horizontal then vertical blur passes
void StackBlur::Run(uint8_t* src) noexcept
{
    const uint32_t stack_size = div * 4U * cores;
    std::vector<uint8_t> stack(stack_size);
    std::vector<std::thread> workers(cores);

    // Horizontal pass
    for (uint32_t core = 0; core < cores; ++core)
    {
        workers[core] = std::thread([&, core]
            {
                const uint32_t offset = div * 4U * core;
                StackBlurThread(1, core, src, &stack[offset]);
            });
    }
    for (auto&& worker : workers)
    {
        worker.join();
    }

    // Vertical pass
    for (uint32_t core = 0; core < cores; ++core)
    {
        workers[core] = std::thread([&, core]
            {
                const uint32_t offset = div * 4U * core;
                StackBlurThread(2, core, src, &stack[offset]);
            });
    }
    for (auto&& worker : workers)
    {
        worker.join();
    }
}

// Write final blurred value to output pointer using precomputed constants
void StackBlur::InitPtr(uint8_t* ptr, const StackRGBA& sum) noexcept
{
    ptr[0] = static_cast<uint8_t>((sum.r * mul_sum) >> shr_sum);
    ptr[1] = static_cast<uint8_t>((sum.g * mul_sum) >> shr_sum);
    ptr[2] = static_cast<uint8_t>((sum.b * mul_sum) >> shr_sum);
    ptr[3] = static_cast<uint8_t>((sum.a * mul_sum) >> shr_sum);
}

// Core thread function implementing the stack-based blur algorithm
void StackBlur::StackBlurThread(uint32_t step, uint32_t core, uint8_t* src, uint8_t* stack) noexcept
{
    StackRGBA sum, sum_in, sum_out;
    uint8_t* stack_ptr;
    uint8_t* src_ptr;
    uint8_t* dst_ptr;

    const uint32_t wm = size.width - 1;
    const uint32_t hm = size.height - 1;
    const uint32_t w4 = size.width * 4;
    uint32_t sp{}, stack_start{};

    if (step == 1) // Horizontal pass
    {
        const uint32_t minY = core * size.height / cores;
        const uint32_t maxY = (core + 1) * size.height / cores;

        for (uint32_t y = minY; y < maxY; ++y)
        {
            sum.Reset();
            sum_in.Reset();
            sum_out.Reset();

            src_ptr = src + w4 * y;

            // Initialize stack with first pixels
            for (uint8_t i = 0; i <= radius; ++i)
            {
                stack_ptr = &stack[i * 4];
                memcpy(stack_ptr, src_ptr, 4);
                sum.Add(src_ptr, i + 1);
                sum_out.Add(src_ptr);
            }

            // Fill remaining stack entries
            for (uint8_t i = 1; i <= radius; ++i)
            {
                if (i <= wm) src_ptr += 4;
                stack_ptr = &stack[4 * (i + radius)];
                memcpy(stack_ptr, src_ptr, 4);
                sum.Add(src_ptr, radius + 1 - i);
                sum_in.Add(src_ptr);
            }

            sp = radius;
            uint32_t xp = std::min<uint32_t>(radius, wm);
            src_ptr = src + 4 * (xp + y * size.width);
            dst_ptr = src + y * w4;

            // Process each pixel in row
            for (uint32_t x = 0; x < size.width; ++x)
            {
                InitPtr(dst_ptr, sum);
                dst_ptr += 4;

                stack_start = sp + div - radius;
                if (stack_start >= div)
                {
                    stack_start -= div;
                }

                stack_ptr = &stack[4 * stack_start];

                if (xp < wm)
                {
                    src_ptr += 4;
                    ++xp;
                }

                sum -= sum_out;
                sum_out -= stack_ptr;
                memcpy(stack_ptr, src_ptr, 4);
                sum_in.Add(src_ptr);
                sum += sum_in;

                ++sp;
                if (sp >= div)
                {
                    sp = 0;
                }

                stack_ptr = &stack[sp * 4];
                sum_out.Add(stack_ptr);
                sum_in -= stack_ptr;
            }
        }
    }
    else if (step == 2) // Vertical pass
    {
        const uint32_t minX = core * size.width / cores;
        const uint32_t maxX = (core + 1) * size.width / cores;

        for (uint32_t x = minX; x < maxX; ++x)
        {
            sum.Reset();
            sum_in.Reset();
            sum_out.Reset();

            src_ptr = src + 4 * x;

            // Initialize stack with first pixels
            for (uint8_t i = 0; i <= radius; ++i)
            {
                stack_ptr = &stack[i * 4];
                memcpy(stack_ptr, src_ptr, 4);
                sum.Add(src_ptr, i + 1);
                sum_out.Add(src_ptr);
            }

            // Fill remaining stack entries
            for (uint8_t i = 1; i <= radius; ++i)
            {
                if (i <= hm)
                {
                    src_ptr += w4;
                }
                stack_ptr = &stack[4 * (i + radius)];
                memcpy(stack_ptr, src_ptr, 4);
                sum.Add(src_ptr, radius + 1 - i);
                sum_in.Add(src_ptr);
            }

            sp = radius;
            uint32_t yp = std::min<uint32_t>(radius, hm);
            src_ptr = src + 4 * (x + yp * size.width);
            dst_ptr = src + 4 * x;

            // Process each pixel in column
            for (uint32_t y = 0; y < size.height; ++y)
            {
                InitPtr(dst_ptr, sum);
                dst_ptr += w4;

                stack_start = sp + div - radius;
                if (stack_start >= div)
                {
                    stack_start -= div;
                }

                stack_ptr = &stack[4 * stack_start];

                if (yp < hm)
                {
                    src_ptr += w4;
                    ++yp;
                }

                sum -= sum_out;
                sum_out -= stack_ptr;
                memcpy(stack_ptr, src_ptr, 4);
                sum_in.Add(src_ptr);
                sum += sum_in;

                ++sp;
                if (sp >= div)
                {
                    sp = 0;
                }

                stack_ptr = &stack[sp * 4];
                sum_out.Add(stack_ptr);
                sum_in -= stack_ptr;
            }
        }
    }
}

