void GLModel::init_from(Geometry &&data)
{
    if (is_initialized())
    {
        // call reset() if you want to reuse this model
        assert(false);
        return;
    }
    if (data.vertices.empty() || data.indices.empty())
    {
        assert(false);
        return;
    }
    m_render_data.geometry = std::move(data);

    // update bounding box
    for (size_t i = 0; i < vertices_count(); ++i)
    {
        const size_t position_stride = Geometry::position_stride_floats(data.format);
        if (position_stride == 3)
            m_bounding_box.merge(m_render_data.geometry.extract_position_3(i).cast<double>());
        else if (position_stride == 2)
        {
            const Vec2f position = m_render_data.geometry.extract_position_2(i);
            m_bounding_box.merge(Vec3f(position.x(), position.y(), 0.0f).cast<double>());
        }
    }
}

#if ENABLE_SMOOTH_NORMALS
void GLModel::init_from(const TriangleMesh &mesh, bool smooth_normals)
{
    if (smooth_normals)
    {
        if (is_initialized())
        {
            // call reset() if you want to reuse this model
            assert(false);
            return;
        }
        if (mesh.its.vertices.empty() || mesh.its.indices.empty())
        {
            assert(false);
            return;
        }

        std::vector<stl_normal> normals;
        smooth_normals_corner(mesh, normals);

        const indexed_triangle_set &its = mesh.its;
        Geometry &data = m_render_data.geometry;
        data.format = {Geometry::EPrimitiveType::Triangles, Geometry::EVertexLayout::P3N3};
        data.reserve_vertices(3 * its.indices.size());
        data.reserve_indices(3 * its.indices.size());

        // vertices
        for (size_t i = 0; i < its.vertices.size(); ++i)
        {
            data.add_vertex(its.vertices[i], normals[i]);
        }

        // indices
        for (size_t i = 0; i < its.indices.size(); ++i)
        {
            const stl_triangle_vertex_indices &idx = its.indices[i];
            data.add_triangle((unsigned int) idx(0), (unsigned int) idx(1), (unsigned int) idx(2));
        }

        // update bounding box
        for (size_t i = 0; i < vertices_count(); ++i)
        {
            m_bounding_box.merge(m_render_data.geometry.extract_position_3(i).cast<double>());
        }
    }
    else
        init_from(mesh.its);
}
#else
void GLModel::init_from(const TriangleMesh &mesh)
{
    init_from(mesh.its);
}
#endif // ENABLE_SMOOTH_NORMALS

void GLModel::init_from(const indexed_triangle_set &its)
{
    if (is_initialized())
    {
        // call reset() if you want to reuse this model
        assert(false);
        return;
    }
    if (its.vertices.empty() || its.indices.empty())
    {
        assert(false);
        return;
    }

    Geometry &data = m_render_data.geometry;
    data.format = {Geometry::EPrimitiveType::Triangles, Geometry::EVertexLayout::P3N3};
    data.reserve_vertices(3 * its.indices.size());
    data.reserve_indices(3 * its.indices.size());

    // vertices + indices
    unsigned int vertices_counter = 0;
    for (uint32_t i = 0; i < its.indices.size(); ++i)
    {
        const stl_triangle_vertex_indices face = its.indices[i];
        const stl_vertex vertex[3] = {its.vertices[face[0]], its.vertices[face[1]], its.vertices[face[2]]};
        const stl_vertex n = face_normal_normalized(vertex);
        for (size_t j = 0; j < 3; ++j)
        {
            data.add_vertex(vertex[j], n);
        }
        vertices_counter += 3;
        data.add_triangle(vertices_counter - 3, vertices_counter - 2, vertices_counter - 1);
    }

    // update bounding box
    for (size_t i = 0; i < vertices_count(); ++i)
    {
        m_bounding_box.merge(data.extract_position_3(i).cast<double>());
    }
}

void GLModel::init_from(const Polygon &polygon, float z)
{
    if (is_initialized())
    {
        // call reset() if you want to reuse this model
        assert(false);
        return;
    }

    Geometry &data = m_render_data.geometry;
    data.format = {Geometry::EPrimitiveType::Lines, Geometry::EVertexLayout::P3};
    const size_t segments_count = polygon.points.size();
    data.reserve_vertices(2 * segments_count);
    data.reserve_indices(2 * segments_count);

    // vertices + indices
    unsigned int vertices_counter = 0;
    for (size_t i = 0; i < segments_count; ++i)
    {
        const Point &p0 = polygon.points[i];
        const Point &p1 = (i == segments_count - 1) ? polygon.points.front() : polygon.points[i + 1];
        data.add_vertex(Vec3f(unscale<float>(p0.x()), unscale<float>(p0.y()), z));
        data.add_vertex(Vec3f(unscale<float>(p1.x()), unscale<float>(p1.y()), z));
        vertices_counter += 2;
        data.add_line(vertices_counter - 2, vertices_counter - 1);
    }

    // update bounding box
    for (size_t i = 0; i < vertices_count(); ++i)
    {
        m_bounding_box.merge(data.extract_position_3(i).cast<double>());
    }
}

void GLModel::init_from(const Polygons &polygons, float z)
{
    if (is_initialized())
    {
        // call reset() if you want to reuse this model
        assert(false);
        return;
    }
    if (polygons.empty())
    {
        assert(false);
        return;
    }

    Geometry &data = m_render_data.geometry;
    data.format = {Geometry::EPrimitiveType::Lines, Geometry::EVertexLayout::P3};
    size_t segments_count = 0;
    for (const Polygon &polygon : polygons)
    {
        segments_count += polygon.points.size();
    }
    data.reserve_vertices(2 * segments_count);
    data.reserve_indices(2 * segments_count);

    // vertices + indices
    unsigned int vertices_counter = 0;
    for (const Polygon &poly : polygons)
    {
        for (size_t i = 0; i < poly.points.size(); ++i)
        {
            const Point &p0 = poly.points[i];
            const Point &p1 = (i == poly.points.size() - 1) ? poly.points.front() : poly.points[i + 1];
            data.add_vertex(Vec3f(unscale<float>(p0.x()), unscale<float>(p0.y()), z));
            data.add_vertex(Vec3f(unscale<float>(p1.x()), unscale<float>(p1.y()), z));
            vertices_counter += 2;
            data.add_line(vertices_counter - 2, vertices_counter - 1);
        }
    }

    // update bounding box
    for (size_t i = 0; i < vertices_count(); ++i)
    {
        m_bounding_box.merge(data.extract_position_3(i).cast<double>());
    }
}

bool GLModel::init_from_file(const std::string &filename)
{
    if (!boost::filesystem::exists(filename))
        return false;
    if (!boost::algorithm::iends_with(filename, ".stl"))
        return false;

    TriangleMesh mesh;
    try
    {
        mesh = FileReader::load_mesh(filename);
    }
    catch (std::exception &)
    {
        return false;
    }

    init_from(mesh);
    m_filename = filename;
    return true;
}

void GLModel::reset()
{
    // release gpu memory
    if (m_render_data.ibo_id > 0)
    {
        glsafe(::glDeleteBuffers(1, &m_render_data.ibo_id));
        m_render_data.ibo_id = 0;
#if ENABLE_GLMODEL_STATISTICS
        s_statistics.gpu_memory.indices.current -= indices_size_bytes();
#endif // ENABLE_GLMODEL_STATISTICS
    }
    if (m_render_data.vbo_id > 0)
    {
        glsafe(::glDeleteBuffers(1, &m_render_data.vbo_id));
        m_render_data.vbo_id = 0;
#if ENABLE_GLMODEL_STATISTICS
        s_statistics.gpu_memory.vertices.current -= vertices_size_bytes();
#endif // ENABLE_GLMODEL_STATISTICS
    }

#if !SLIC3R_OPENGL_ES
    if (OpenGLManager::get_gl_info().is_core_profile())
    {
#endif // !SLIC3R_OPENGL_ES
        if (m_render_data.vao_id > 0)
        {
            glsafe(::glDeleteVertexArrays(1, &m_render_data.vao_id));
            m_render_data.vao_id = 0;
        }
#if !SLIC3R_OPENGL_ES
    }
#endif // !SLIC3R_OPENGL_ES

    m_render_data.vertices_count = 0;
    m_render_data.indices_count = 0;
    m_render_data.geometry.vertices = std::vector<float>();
    m_render_data.geometry.indices = std::vector<unsigned int>();
    m_bounding_box = BoundingBoxf3();
    m_filename = std::string();
}

static GLenum get_primitive_mode(const GLModel::Geometry::Format &format)
{
    switch (format.type)
    {
    case GLModel::Geometry::EPrimitiveType::Points:
    {
        return GL_POINTS;
    }
    default:
    case GLModel::Geometry::EPrimitiveType::Triangles:
    {
        return GL_TRIANGLES;
    }
    case GLModel::Geometry::EPrimitiveType::TriangleStrip:
    {
        return GL_TRIANGLE_STRIP;
    }
    case GLModel::Geometry::EPrimitiveType::TriangleFan:
    {
        return GL_TRIANGLE_FAN;
    }
    case GLModel::Geometry::EPrimitiveType::Lines:
    {
        return GL_LINES;
    }
    case GLModel::Geometry::EPrimitiveType::LineStrip:
    {
        return GL_LINE_STRIP;
    }
    case GLModel::Geometry::EPrimitiveType::LineLoop:
    {
        return GL_LINE_LOOP;
    }
    }
}

static GLenum get_index_type(const GLModel::Geometry &data)
{
    switch (data.index_type)
    {
    default:
    case GLModel::Geometry::EIndexType::UINT:
    {
        return GL_UNSIGNED_INT;
    }
    case GLModel::Geometry::EIndexType::USHORT:
    {
        return GL_UNSIGNED_SHORT;
    }
    case GLModel::Geometry::EIndexType::UBYTE:
    {
        return GL_UNSIGNED_BYTE;
    }
    }
}

void GLModel::render()
{
    render(std::make_pair<size_t, size_t>(0, indices_count()));
}

void GLModel::render(const std::pair<size_t, size_t> &range)
{
    if (m_render_disabled)
        return;
    if (range.second == range.first)
        return;

    GLShaderProgram *shader = wxGetApp().get_current_shader();
    if (shader == nullptr)
        return;

    // sends data to gpu if not done yet
    if (m_render_data.vbo_id == 0 || m_render_data.ibo_id == 0)
    {
        if (m_render_data.geometry.vertices_count() > 0 && m_render_data.geometry.indices_count() > 0 && !send_to_gpu())
            return;
    }

    const Geometry &data = m_render_data.geometry;
    const GLenum mode = get_primitive_mode(data.format);
    const GLenum index_type = get_index_type(data);
    const size_t vertex_stride_bytes = Geometry::vertex_stride_bytes(data.format);
    const bool position = Geometry::has_position(data.format);
    const bool normal = Geometry::has_normal(data.format);
    const bool tex_coord = Geometry::has_tex_coord(data.format);
    const bool extra = Geometry::has_extra(data.format);

#if !SLIC3R_OPENGL_ES
    if (OpenGLManager::get_gl_info().is_core_profile())
    {
#endif // !SLIC3R_OPENGL_ES
        glsafe(::glBindVertexArray(m_render_data.vao_id));
#if !SLIC3R_OPENGL_ES
    }
#endif // !SLIC3R_OPENGL_ES

    // the following binding is needed to set the vertex attributes
    glsafe(::glBindBuffer(GL_ARRAY_BUFFER, m_render_data.vbo_id));

    int position_id = -1;
    int normal_id = -1;
    int tex_coord_id = -1;
    int extra_id = -1;

    if (position)
    {
        position_id = shader->get_attrib_location("v_position");
        if (position_id != -1)
        {
            glsafe(::glVertexAttribPointer(position_id, Geometry::position_stride_floats(data.format), GL_FLOAT,
                                           GL_FALSE, vertex_stride_bytes,
                                           (const void *) Geometry::position_offset_bytes(data.format)));
            glsafe(::glEnableVertexAttribArray(position_id));
        }
    }

    if (normal)
    {
        normal_id = shader->get_attrib_location("v_normal");
        if (normal_id != -1)
        {
            glsafe(::glVertexAttribPointer(normal_id, Geometry::normal_stride_floats(data.format), GL_FLOAT, GL_FALSE,
                                           vertex_stride_bytes,
                                           (const void *) Geometry::normal_offset_bytes(data.format)));
            glsafe(::glEnableVertexAttribArray(normal_id));
        }
    }

    if (tex_coord)
    {
        tex_coord_id = shader->get_attrib_location("v_tex_coord");
        if (tex_coord_id != -1)
        {
            glsafe(::glVertexAttribPointer(tex_coord_id, Geometry::tex_coord_stride_floats(data.format), GL_FLOAT,
                                           GL_FALSE, vertex_stride_bytes,
                                           (const void *) Geometry::tex_coord_offset_bytes(data.format)));
            glsafe(::glEnableVertexAttribArray(tex_coord_id));
        }
    }

    if (extra)
    {
        extra_id = shader->get_attrib_location("v_extra");
        if (extra_id != -1)
        {
            glsafe(::glVertexAttribPointer(extra_id, Geometry::extra_stride_floats(data.format), GL_FLOAT, GL_FALSE,
                                           vertex_stride_bytes,
                                           (const void *) Geometry::extra_offset_bytes(data.format)));
            glsafe(::glEnableVertexAttribArray(extra_id));
        }
    }

    shader->set_uniform("uniform_color", data.color);

    glsafe(::glBindBuffer(GL_ELEMENT_ARRAY_BUFFER, m_render_data.ibo_id));
    glsafe(::glDrawElements(mode, range.second - range.first, index_type,
                            (const void *) (range.first * Geometry::index_stride_bytes(data))));

    if (extra_id != -1)
        glsafe(::glDisableVertexAttribArray(extra_id));
    if (tex_coord_id != -1)
        glsafe(::glDisableVertexAttribArray(tex_coord_id));
    if (normal_id != -1)
        glsafe(::glDisableVertexAttribArray(normal_id));
    if (position_id != -1)
        glsafe(::glDisableVertexAttribArray(position_id));

    glsafe(::glBindBuffer(GL_ARRAY_BUFFER, 0));

#if !SLIC3R_OPENGL_ES
    if (OpenGLManager::get_gl_info().is_core_profile())
    {
#endif // !SLIC3R_OPENGL_ES
        glsafe(::glBindVertexArray(0));
#if !SLIC3R_OPENGL_ES
    }
#endif // !SLIC3R_OPENGL_ES

#if ENABLE_GLMODEL_STATISTICS
    ++s_statistics.render_calls;
#endif // ENABLE_GLMODEL_STATISTICS
}

void GLModel::render_instanced(unsigned int instances_vbo, unsigned int instances_count)
{
    if (instances_vbo == 0 || instances_count == 0)
        return;

    GLShaderProgram *shader = wxGetApp().get_current_shader();
    if (shader == nullptr || !boost::algorithm::iends_with(shader->get_name(), "_instanced"))
        return;

    // vertex attributes
    const GLint position_id = shader->get_attrib_location("v_position");
    const GLint normal_id = shader->get_attrib_location("v_normal");
    if (position_id == -1 || normal_id == -1)
        return;

    // instance attributes
    const GLint offset_id = shader->get_attrib_location("i_offset");
    const GLint scales_id = shader->get_attrib_location("i_scales");
    if (offset_id == -1 || scales_id == -1)
        return;

    if (m_render_data.vbo_id == 0 || m_render_data.ibo_id == 0)
    {
        if (!send_to_gpu())
            return;
    }

#if !SLIC3R_OPENGL_ES
    if (OpenGLManager::get_gl_info().is_core_profile())
    {
#endif // !SLIC3R_OPENGL_ES
        glsafe(::glBindVertexArray(m_render_data.vao_id));
#if !SLIC3R_OPENGL_ES
    }
#endif // !SLIC3R_OPENGL_ES

    glsafe(::glBindBuffer(GL_ARRAY_BUFFER, instances_vbo));
    const size_t instance_stride = 5 * sizeof(float);
    glsafe(::glVertexAttribPointer(offset_id, 3, GL_FLOAT, GL_FALSE, instance_stride, (const void *) 0));
    glsafe(::glEnableVertexAttribArray(offset_id));
    glsafe(::glVertexAttribDivisor(offset_id, 1));

    glsafe(
        ::glVertexAttribPointer(scales_id, 2, GL_FLOAT, GL_FALSE, instance_stride, (const void *) (3 * sizeof(float))));
    glsafe(::glEnableVertexAttribArray(scales_id));
    glsafe(::glVertexAttribDivisor(scales_id, 1));

    const Geometry &data = m_render_data.geometry;
    const GLenum mode = get_primitive_mode(data.format);
    const GLenum index_type = get_index_type(data);
    const size_t vertex_stride_bytes = Geometry::vertex_stride_bytes(data.format);
    const bool position = Geometry::has_position(data.format);
    const bool normal = Geometry::has_normal(data.format);

    // the following binding is needed to set the vertex attributes
    glsafe(::glBindBuffer(GL_ARRAY_BUFFER, m_render_data.vbo_id));

    if (position)
    {
        glsafe(::glVertexAttribPointer(position_id, Geometry::position_stride_floats(data.format), GL_FLOAT, GL_FALSE,
                                       vertex_stride_bytes,
                                       (const void *) Geometry::position_offset_bytes(data.format)));
        glsafe(::glEnableVertexAttribArray(position_id));
    }

    if (normal)
    {
        glsafe(::glVertexAttribPointer(normal_id, Geometry::normal_stride_floats(data.format), GL_FLOAT, GL_FALSE,
                                       vertex_stride_bytes, (const void *) Geometry::normal_offset_bytes(data.format)));
        glsafe(::glEnableVertexAttribArray(normal_id));
    }

    shader->set_uniform("uniform_color", data.color);

    glsafe(::glDrawElementsInstanced(mode, indices_count(), index_type, (const void *) 0, instances_count));

    if (normal)
        glsafe(::glDisableVertexAttribArray(normal_id));
    if (position)
        glsafe(::glDisableVertexAttribArray(position_id));

    glsafe(::glDisableVertexAttribArray(scales_id));
    glsafe(::glDisableVertexAttribArray(offset_id));

    glsafe(::glBindBuffer(GL_ARRAY_BUFFER, 0));

#if !SLIC3R_OPENGL_ES
    if (OpenGLManager::get_gl_info().is_core_profile())
    {
#endif // !SLIC3R_OPENGL_ES
        glsafe(::glBindVertexArray(0));
#if !SLIC3R_OPENGL_ES
    }
#endif // !SLIC3R_OPENGL_ES

#if ENABLE_GLMODEL_STATISTICS
    ++s_statistics.render_instanced_calls;
#endif // ENABLE_GLMODEL_STATISTICS
}

bool GLModel::send_to_gpu()
{
    if (m_render_data.vbo_id > 0 || m_render_data.ibo_id > 0)
    {
        assert(false);
        return false;
    }

    Geometry &data = m_render_data.geometry;
    if (data.vertices.empty() || data.indices.empty())
    {
        assert(false);
        return false;
    }

#if !SLIC3R_OPENGL_ES
    if (OpenGLManager::get_gl_info().is_core_profile())
    {
#endif // !SLIC3R_OPENGL_ES
        glsafe(::glGenVertexArrays(1, &m_render_data.vao_id));
        glsafe(::glBindVertexArray(m_render_data.vao_id));
#if !SLIC3R_OPENGL_ES
    }
#endif // !SLIC3R

#include "pch.h"
#include "exif.h"
#include <algorithm>
#include <cstdint>
#include <stdio.h>
#include <vector>

using std::string;

namespace {

// Structure representing a rational number (numerator/denominator)
struct Rational {
  uint32_t numerator, denominator;

  // Conversion operator to double
  operator double() const {
    if (denominator < 1e-20) {
      return 0;
    }
    return static_cast<double>(numerator) / static_cast<double>(denominator);
  }
};

// IF Entry class for EXIF data parsing
class IFEntry {
 public:
  using byte_vector = std::vector<uint8_t>;
  using ascii_vector = std::string;
  using short_vector = std::vector<uint16_t>;
  using long_vector = std::vector<uint32_t>;
  using rational_vector = std::vector<Rational>;

  // Default constructor
  IFEntry()
      : tag_(0xFF), format_(0xFF), data_(0), length_(0), val_byte_(nullptr) {}

  // Delete copy operations
  IFEntry(const IFEntry &) = delete;
  IFEntry &operator=(const IFEntry &) = delete;

  // Move constructor
  IFEntry(IFEntry &&other)
      : tag_(other.tag_),
        format_(other.format_),
        data_(other.data_),
        length_(other.length_),
        val_byte_(other.val_byte_) {
    other.tag_ = 0xFF;
    other.format_ = 0xFF;
    other.data_ = 0;
    other.length_ = 0;
    other.val_byte_ = nullptr;
  }

  // Destructor
  ~IFEntry() { delete_union(); }

  // Tag accessors
  unsigned short tag() const { return tag_; }
  void tag(unsigned short tag) { tag_ = tag; }

  // Format accessors
  unsigned short format() const { return format_; }
  bool format(unsigned short format) {
    switch (format) {
      case 0x01:
      case 0x02:
      case 0x03:
      case 0x04:
      case 0x05:
      case 0x07:
      case 0x09:
      case 0x0a:
      case 0xff:
        break;
      default:
        return false;
    }
    delete_union();
    format_ = format;
    new_union();
    return true;
  }

  // Data and length accessors
  unsigned data() const { return data_; }
  void data(unsigned data) { data_ = data; }
  unsigned length() const { return length_; }
  void length(unsigned length) { length_ = length; }

  // Value accessors - caller must ensure correct format
  byte_vector &val_byte() { return *val_byte_; }
  ascii_vector &val_string() { return *val_string_; }
  short_vector &val_short() { return *val_short_; }
  long_vector &val_long() { return *val_long_; }
  rational_vector &val_rational() { return *val_rational_; }

 private:
  // Raw fields
  unsigned short tag_;
  unsigned short format_;
  unsigned data_;
  unsigned length_;

  // Union for parsed data
  union {
    byte_vector *val_byte_;
    ascii_vector *val_string_;
    short_vector *val_short_;
    long_vector *val_long_;
    rational_vector *val_rational_;
  };

  // Helper functions to manage union memory
  void delete_union() {
    switch (format_) {
      case 0x1:
        delete val_byte_;
        val_byte_ = nullptr;
        break;
      case 0x2:
        delete val_string_;
        val_string_ = nullptr;
        break;
      case 0x3:
        delete val_short_;
        val_short_ = nullptr;
        break;
      case 0x4:
        delete val_long_;
        val_long_ = nullptr;
        break;
      case 0x5:
        delete val_rational_;
        val_rational_ = nullptr;
        break;
      case 0xff:
        break;
      default:
        // Should not reach here
        break;
    }
  }

  void new_union() {
    switch (format_) {
      case 0x1:
        val_byte_ = new byte_vector();
        break;
      case 0x2:
        val_string_ = new ascii_vector();
        break;
      case 0x3:
        val_short_ = new short_vector();
        break;
      case 0x4:
        val_long_ = new long_vector();
        break;
      case 0x5:
        val_rational_ = new rational_vector();
        break;
      case 0xff:
        break;
      default:
        // Should not reach here
        break;
    }
  }
};

// Template function to parse values with specified alignment
template <typename T, bool alignIntel>
T parse(const unsigned char *buf);

// Specializations for uint8_t
template <>
uint8_t parse<uint8_t, false>(const unsigned char *buf) {
  return *buf;
}
template <>
uint8_t parse<uint8_t, true>(const unsigned char *buf) {
  return *buf;
}

// Specializations for uint16_t
template <>
uint16_t parse<uint16_t, false>(const unsigned char *buf) {
  return (static_cast<uint16_t>(buf[0]) << 8) | buf[1];
}
template <>
uint16_t parse<uint16_t, true>(const unsigned char *buf) {
  return (static_cast<uint16_t>(buf[1]) << 8) | buf[0];
}

// Specializations for uint32_t
template <>
uint32_t parse<uint32_t, false>(const unsigned char *buf) {
  return (static_cast<uint32_t>(buf[0]) << 24) |
         (static_cast<uint32_t>(buf[1]) << 16) |
         (static_cast<uint32_t>(buf[2]) << 8) | buf[3];
}
template <>
uint32_t parse<uint32_t, true>(const unsigned char *buf) {
  return (static_cast<uint32_t>(buf[3]) << 24) |
         (static_cast<uint32_t>(buf[2]) << 16) |
         (static_cast<uint32_t>(buf[1]) << 8) | buf[0];
}

// Specializations for Rational
template <>
Rational parse<Rational, true>(const unsigned char *buf) {
  Rational r;
  r.numerator = parse<uint32_t, true>(buf);
  r.denominator = parse<uint32_t, true>(buf + 4);
  return r;
}
template <>
Rational parse<Rational, false>(const unsigned char *buf) {
  Rational r;
  r.numerator = parse<uint32_t, false>(buf);
  r.denominator = parse<uint32_t, false>(buf + 4);
  return r;
}

/**
 * Extracts values from buffer into container.
 *
 * Returns:
 *  true  - entry.length() values were read successfully
 *  false - error occurred, container unchanged
 */
template <typename T, bool alignIntel, typename C>
bool extract_values(C &container, const unsigned char *buf, const unsigned base,
                    const unsigned len, const IFEntry &entry) {
  const unsigned char *data;
  uint32_t reversed_data;

  // If data fits in 4 bytes, it's stored directly in the IFEntry's data field
  if (sizeof(T) * entry.length() <= 4) {
    if (alignIntel) {
      reversed_data = entry.data();
    } else {
      reversed_data = entry.data();
      // Manual byte reversal for non-intel alignment
      unsigned char *rdata = reinterpret_cast<unsigned char *>(&reversed_data);
      unsigned char tmp;
      tmp = rdata[0];
      rdata[0] = rdata[3];
      rdata[3] = tmp;
      tmp = rdata[1];
      rdata[1] = rdata[2];
      rdata[2] = tmp;
    }
    data = reinterpret_cast<const unsigned char *>(&(reversed_data));
  } else {
    data = buf + base + entry.data();
    if (data + sizeof(T) * entry.length() > buf + len) {
      return false;
    }
  }

  container.resize(entry.length());
  for (size_t i = 0; i < entry.length(); ++i) {
    container[i] = parse<T, alignIntel>(data + sizeof(T) * i);
  }
  return true;
}

// Parse IF Entry header (raw version)
template <bool alignIntel>
void parseIFEntryHeader(const unsigned char *buf, unsigned short &tag,
                        unsigned short &format, unsigned &length,
                        unsigned &data) {
  tag = parse<uint16_t, alignIntel>(buf);
  format = parse<uint16_t, alignIntel>(buf + 2);
  length = parse<uint32_t, alignIntel>(buf + 4);
  data = parse<uint32_t, alignIntel>(buf + 8);
}

// Parse IF Entry header (into IFEntry object)
template <bool alignIntel>
void parseIFEntryHeader(const unsigned char *buf, IFEntry &result) {
  unsigned short tag;
  unsigned short format;
  unsigned length;
  unsigned data;
  parseIFEntryHeader<alignIntel>(buf, tag, format, length, data);
  result.tag(tag);
  result.format(format);
  result.length(length);
  result.data(data);
}

// Parse IF Entry temporarily (returns IFEntry)
template <bool alignIntel>
IFEntry parseIFEntry_temp(const unsigned char *buf, const unsigned offs,
                          const unsigned base, const unsigned len) {
  IFEntry result;

  // Check buffer bounds
  if (buf + offs + 12 > buf + len) {
    result.tag(0xFF);
    return result;
  }

  parseIFEntryHeader<alignIntel>(buf + offs, result);

  // Parse value based on format
  switch (result.format()) {
    case 1:
      if (!extract_values<uint8_t, alignIntel>(result.val_byte(), buf, base,
                                               len, result)) {
        result.tag(0xFF);
      }
      break;
    case 2:
      if (!extract_values<uint8_t, alignIntel>(result.val_string(), buf, base,
                                               len, result)) {
        result.tag(0xFF);
      }
      // Remove trailing null byte if present
      if (!result.val_string().empty() &&
          result.val_string()[result.val_string().length() - 1] == '\0') {
        result.val_string().resize(result.val_string().length() - 1);
      }
      break;
    case 3:
      if (!extract_values<uint16_t, alignIntel>(result.val_short(), buf, base,
                                                len, result)) {
        result.tag(0xFF);
      }
      break;
    case 4:
      if (!extract_values<uint32_t, alignIntel>(result.val_long(), buf, base,
                                                len, result)) {
        result.tag(0xFF);
      }
      break;
    case 5:
      if (!extract_values<Rational, alignIntel>(result.val_rational(), buf,
                                                base, len, result)) {
        result.tag(0xFF);
      }
      break;
    case 7:
    case 9:
    case 10:
      break;
    default:
      result.tag(0xFF);
  }
  return result;
}

// Helper: parse single value with alignment flag
template <typename T>
T parse_value(const unsigned char *buf, bool alignIntel) {
  if (alignIntel) {
    return parse<T, true>(buf);
  } else {
    return parse<T, false>(buf);
  }
}

// Wrapper for parsing IF Entry header with alignment flag
void parseIFEntryHeader(const unsigned char *buf, bool alignIntel,
                        unsigned short &tag, unsigned short &format,
                        unsigned &length, unsigned &data) {
  if (alignIntel) {
    parseIFEntryHeader<true>(buf, tag, format, length, data);
  } else {
    parseIFEntryHeader<false>(buf, tag, format, length, data);
  }
}

// Main IF Entry parser with alignment support
IFEntry parseIFEntry(const unsigned char *buf, const unsigned offs,
                     const bool alignIntel, const unsigned base,
                     const unsigned len) {
  if (alignIntel) {
    return parseIFEntry_temp<true>(buf, offs, base, len);
  } else {
    return parseIFEntry_temp<false>(buf, offs, base, len);
  }
}

}  // namespace

//
// Parses EXIF data from JPEG buffer
//
int easyexif::EXIFInfo::parseFrom(const unsigned char *buf, unsigned len) {
  // Sanity check: JPEG files start with 0xFFD8
  if (!buf || len < 4) return PARSE_EXIF_ERROR_NO_JPEG;
  if (buf[0] != 0xFF || buf[1] != 0xD8) return PARSE_EXIF_ERROR_NO_JPEG;

  // Handle padding at end of JPEG
  while (len > 2) {
    if (buf[len - 1] == 0xD9 && buf[len - 2] == 0xFF)
      break;
    len--;
  }
  if (len <= 2)
    return PARSE_EXIF_ERROR_NO_JPEG;

  clear();

  // Scan for EXIF marker (0xFFE1)
  unsigned offs = 0;
  for (offs = 0; offs < len - 1; offs++)
    if (buf[offs] == 0xFF && buf[offs + 1] == 0xE1) break;

  if (offs + 4 > len) return PARSE_EXIF_ERROR_NO_EXIF;
  offs += 2;

  // Section length (Motorola byte order)
  unsigned short section_length = parse_value<uint16_t>(buf + offs, false);
  if (offs + section_length > len || section_length < 16)
    return PARSE_EXIF_ERROR_CORRUPT;

  offs += 2;
  return parseFromEXIFSegment(buf + offs, len - offs);
}

int easyexif::EXIFInfo::parseFrom(const string &data) {
  return parseFrom(
      reinterpret_cast<const unsigned char *>(data.data()),
      static_cast<unsigned>(data.length()));
}

//
// Main EXIF segment parser
//
int easyexif::EXIFInfo::parseFromEXIFSegment(const unsigned char *buf,
                                             unsigned len) {
  bool alignIntel = true;
  unsigned offs = 0;

  if (!buf || len < 6) return PARSE_EXIF_ERROR_NO_EXIF;
  if (!std::equal(buf, buf + 6, "Exif\0\0")) return PARSE_EXIF_ERROR_NO_EXIF;
  offs += 6;

  // Parse TIFF header
  unsigned tiff_header_start = offs;
  if (offs + 8 > len) return PARSE_EXIF_ERROR_CORRUPT;

  if (buf[offs] == 'I' && buf[offs + 1] == 'I')
    alignIntel = true;
  else if (buf[offs] == 'M' && buf[offs + 1] == 'M')
    alignIntel = false;
  else
    return PARSE_EXIF_ERROR_UNKNOWN_BYTEALIGN;

  this->ByteAlign = alignIntel;
  offs += 2;

  if (0x2a != parse_value<uint16_t>(buf + offs, alignIntel))
    return PARSE_EXIF_ERROR_CORRUPT;
  offs += 2;

  unsigned first_ifd_offset = parse_value<uint32_t>(buf + offs, alignIntel);
  offs += first_ifd_offset - 4;
  if (offs >= len) return PARSE_EXIF_ERROR_CORRUPT;

  // Parse IFD0
  if (offs + 2 > len) return PARSE_EXIF_ERROR_CORRUPT;
  int num_entries = parse_value<uint16_t>(buf + offs, alignIntel);
  if (offs + 6 + 12 * num_entries > len) return PARSE_EXIF_ERROR_CORRUPT;
  offs += 2;

  unsigned exif_sub_ifd_offset = len;
  unsigned gps_sub_ifd_offset = len;

  while (--num_entries >= 0) {
    IFEntry result =
        parseIFEntry(buf, offs, alignIntel, tiff_header_start, len);
    offs += 12;

    switch (result.tag()) {
      case 0x102:  // Bits per sample
        if (result.format() == 3 && result.val_short().size())
          this->BitsPerSample = result.val_short().front();
        break;
      case 0x10E:  // Image description
        if (result.format() == 2) this->ImageDescription = result.val_string();
        break;
      case 0x10F:  // Digicam make
        if (result.format() == 2) this->Make = result.val_string();
        break;
      case 0x110:  // Digicam model
        if (result.format() == 2) this->Model = result.val_string();
        break;
      case 0x112:  // Orientation
        if (result.format() == 3 && result.val_short().size())
          this->Orientation = result.val_short().front();
        break;
      case 0x131:  // Software
        if (result.format() == 2) this->Software = result.val_string();
        break;
      case 0x132:  // Date/time
        if (result.format() == 2) this->DateTime = result.val_string();
        break;
      case 0x8298:  // Copyright
        [redacted]
        break;
      case 0x8825:  // GPS offset
        gps_sub_ifd_offset = tiff_header_start + result.data();
        break;
      case 0x8769:  // EXIF SubIFD offset
        exif_sub_ifd_offset = tiff_header_start + result.data();
        break;
    }
  }

  // Parse EXIF SubIFD
  if (exif_sub_ifd_offset + 4 <= len) {
    offs = exif_sub_ifd_offset;
    int num_sub_entries = parse_value<uint16_t>(buf + offs, alignIntel);
    if (offs + 6 + 12 * num_sub_entries > len) return PARSE_EXIF_ERROR_CORRUPT;
    offs += 2;

    while (--num_sub_entries >= 0) {
      IFEntry result =
          parseIFEntry(buf, offs, alignIntel, tiff_header_start, len);
      switch (result.tag()) {
        case 0x829a:  // Exposure time
          if (result.format() == 5 && result.val_rational().size())
            this->ExposureTime = result.val_rational().front();
          break;
        case 0x829d:  // F-number
          if (result.format() == 5 && result.val_rational().size())
            this->FNumber = result.val_rational().front();
          break;
        case 0x8822:  // Exposure program
          if (result.format() == 3 && result.val_short().size())
            this->ExposureProgram = result.val_short().front();
          break;
        case 0x8827:  // ISO speed
          if (result.format() == 3 && result.val_short().size())
            this->ISOSpeedRatings = result.val_short().front();
          break;
        case 0x9003:  // DateTimeOriginal
          if (result.format() == 2)
            this->DateTimeOriginal = result.val_string();
          break;
        case 0x9004:  // DateTimeDigitized
          if (result.format() == 2)
            this->DateTimeDigitized = result.val_string();
          break;
        case 0x9201:  // Shutter speed
          if (result.format() == 5 && result.val_rational().size())
            this->ShutterSpeedValue = result.val_rational().front();
          break;
        case 0x9204:  // Exposure bias
          if (result.format() == 5 && result.val_rational().size())
            this->ExposureBiasValue = result.val_rational().front();
          break;
        case 0x9206:  // Subject distance
          if (result.format() == 5 && result.val_rational().size())
            this->SubjectDistance = result.val_rational().front();
          break;
        case 0x9209:  // Flash
          if (result.format() == 3 && result.val_short().size()) {
            uint16_t data = result.val_short().front();
            this->Flash = data & 1;
            this->FlashReturnedLight = (data & 6) >> 1;
            this->FlashMode = (data & 24) >> 3;
          }
          break;
        case 0x920a:  // Focal length
          if (result.format() == 5 && result.val_rational().size())
            this->FocalLength = result.val_rational().front();
          break;
        case 0xa405:  // Focal length in 35mm
          if (result.format() == 3 && result.val_short().size())
            this->LensInfo.FocalLengthIn35mm = result.val_short().front();
          break;
        case 0x9207:  // Metering mode
          if (result.format() == 3 && result.val_short().size())
            this->MeteringMode = result.val_short().front();
          break;
        case 0x9291:  // SubSecTimeOriginal
          if (result.format() == 2)
            this->SubSecTimeOriginal = result.val_string();
          break;
        case 0xa001:  // Color space
          if (result.format() == 3 && result.val_short().size())
            this->ColorSpace = result.val_short().front();
          break;
        case 0xa002:  // Image width
          if (result.format() == 4 && result.val_long().size())
            this->ImageWidth = result.val_long().front();
          if (result.format() == 3 && result.val_short().size())
            this->ImageWidth = result.val_short().front();
          break;
        case 0xa003:  // Image height
          if (result.format() == 4 && result.val_long().size())
            this->ImageHeight = result.val_long().front();
          if (result.format() == 3 && result.val_short().size())
            this->ImageHeight = result.val_short().front();
          break;
        case 0xa20e:  // Focal plane X resolution
          if (result.format() == 5) {
            this->LensInfo.FocalPlaneXResolution = result.val_rational()[0];
          }
          break;
        case 0xa20f:  // Focal plane Y resolution
          if (result.format() == 5) {
            this->LensInfo.FocalPlaneYResolution = result.val_rational()[0];
          }
          break;
        case 0xa210:  // Focal plane resolution unit
          if (result.format() == 3 && result.val_short().size()) {
            this->LensInfo.FocalPlaneResolutionUnit = result.val_short().front();
          }
          break;
        case 0xa432:  // Lens info (min/max focal length, min/max aperture)
          if (result.format() == 5) {
            int sz = static_cast<unsigned>(result.val_rational().size());
            if (sz > 0)
              this->LensInfo.FocalLengthMin = result.val_rational()[0];
            if (sz > 1)
              this->LensInfo.FocalLengthMax = result.val_rational()[1];
            if (sz > 2)
              this->LensInfo.FStopMin = result.val_rational()[2];
            if (sz > 3)
              this->LensInfo.FStopMax = result.val_rational()[3];
          }
          break;
        case 0xa433:  // Lens make
          if (result.format() == 2) {
            this->LensInfo.Make = result.val_string();
          }
          break;
        case 0xa434:  // Lens model
          if (result.format() == 2) {
            this->LensInfo.Model = result.val_string();
          }
          break;
      }
      offs += 12;
    }
  }

  // Parse GPS SubIFD
  if (gps_sub_ifd_offset + 4 <= len) {
    offs = gps_sub_ifd_offset;
    int num_sub_entries = parse_value<uint16_t>(buf + offs, alignIntel);
    if (offs + 6 + 12 * num_sub_entries > len) return PARSE_EXIF_ERROR_CORRUPT;
    offs += 2;

    while (--num_sub_entries >= 0) {
      unsigned short tag, format;
      unsigned length, data;
      parseIFEntryHeader(buf + offs, alignIntel, tag, format, length, data);

      switch (tag) {
        case 1:  // GPS direction (N/S)
          this->GeoLocation.LatComponents.direction = *(buf + offs + 8);
          if (this->GeoLocation.LatComponents.direction == 0)
            this->GeoLocation.LatComponents.direction = '?';
          if ('S' == this->GeoLocation.LatComponents.direction)
            this->GeoLocation.Latitude = -this->GeoLocation.Latitude;
          break;
        case 2:  // Latitude
          if ((format == 5 || format == 10) && length == 3) {
            this->GeoLocation.LatComponents.degrees = parse_value<Rational>(
                buf + data + tiff_header_start, alignIntel);
            this->GeoLocation.LatComponents.minutes = parse_value<Rational>(
                buf + data + tiff_header_start + 8, alignIntel);
            this->GeoLocation.LatComponents.seconds = parse_value<Rational>(
                buf + data + tiff_header_start + 16, alignIntel);
            this->GeoLocation.Latitude =
                this->GeoLocation.LatComponents.degrees +
                this->GeoLocation.LatComponents.minutes / 60 +
                this->GeoLocation.LatComponents.seconds / 3600;
            if ('S' == this->GeoLocation.LatComponents.direction)
              this->GeoLocation.Latitude = -this->GeoLocation.Latitude;
          }
          break;
        case 3:  // GPS direction (E/W)
          this->GeoLocation.LonComponents.direction = *(buf + offs + 8);
          if (this->GeoLocation.LonComponents.direction == 0)
            this->GeoLocation.LonComponents.direction = '?';
          if ('W' == this->GeoLocation.LonComponents.direction)
            this->GeoLocation.Longitude = -this->GeoLocation.Longitude;
          break;
        case 4:  // Longitude
          if ((format == 5 || format == 10) && length == 3) {
            this->GeoLocation.LonComponents.degrees = parse_value<Rational>(
                buf + data + tiff_header_start, alignIntel);
            this->GeoLocation.LonComponents.minutes = parse_value<Rational>(
                buf + data + tiff_header_start + 8, alignIntel);
            this->GeoLocation.LonComponents.seconds = parse_value<Rational>(
                buf + data + tiff_header_start + 16, alignIntel);
            this->GeoLocation.Longitude =
                this->GeoLocation.LonComponents.degrees +
                this->GeoLocation.LonComponents.minutes / 60 +
                this->GeoLocation.LonComponents.seconds / 3600;
            if ('W' == this->GeoLocation.LonComponents.direction)
              this->GeoLocation.Longitude = -this->GeoLocation.Longitude;
          }
          break;
        case 5:  // Altitude reference
          this->GeoLocation.AltitudeRef = *(buf + offs + 8);
          if (1 == this->GeoLocation.AltitudeRef)
            this->GeoLocation.Altitude = -this->GeoLocation.Altitude;
          break;
        case 6:  // Altitude
          if ((format == 5 || format == 10)) {
            this->GeoLocation.Altitude = parse_value<Rational>(
                buf + data + tiff_header_start, alignIntel);
            if (1 == this->GeoLocation.AltitudeRef)
              this->GeoLocation.Altitude = -this->GeoLocation.Altitude;
          }
          break;
        case 11:  // DOP
          if ((format == 5 || format == 10)) {
            this->GeoLocation.DOP = parse_value<Rational>(
                buf + data + tiff_header_start, alignIntel);
          }
          break;
      }
      offs += 12;
    }
  }

  return PARSE_EXIF_SUCCESS;
}

void easyexif::EXIFInfo::clear() {
  // Reset strings
  ImageDescription = "";
  Make = "";
  Model = "";
  Software = "";
  DateTime = "";
  DateTimeOriginal = "";
  DateTimeDigitized = "";
  SubSecTimeOriginal = "";
  Copyright [redacted]

  // Reset numeric fields
  ByteAlign = 0;
  Orientation = 0;
  BitsPerSample = 0;
  ExposureTime = 0;
  FNumber = 0;
  ExposureProgram = 0;
  ISOSpeedRatings = 0;
  ShutterSpeedValue = 0;
  ExposureBiasValue = 0;
  SubjectDistance = 0;
  FocalLength = 0;
  FocalLengthIn35mm = 0;
  Flash = 0;
  FlashReturnedLight = 0;
  FlashMode = 0;
  MeteringMode = 0;
  ColorSpace = 0;
  ImageWidth = 0;
  ImageHeight = 0;

  // Reset geolocation
  GeoLocation.Latitude = 0;
  GeoLocation.Longitude = 0;
  GeoLocation.Altitude = 0;
  GeoLocation.AltitudeRef = 0;
  GeoLocation.DOP = 0;
  GeoLocation.LatComponents.degrees = 0;
  GeoLocation.LatComponents.minutes = 0;
  GeoLocation.LatComponents.seconds = 0;
  GeoLocation.LatComponents.direction = '?';
  GeoLocation.LonComponents.degrees = 0;
  GeoLocation.LonComponents.minutes = 0;
  GeoLocation.LonComponents.seconds = 0;
  GeoLocation.LonComponents.direction = '?';

  // Reset lens info
  LensInfo.FocalLengthMax = 0;
  LensInfo.FocalLengthMin = 0;
  LensInfo.FStopMax = 0;
  LensInfo.FStopMin = 0;
  LensInfo.FocalPlaneYResolution = 0;
  LensInfo.FocalPlaneXResolution = 0;
  LensInfo.FocalPlaneResolutionUnit = 0;
  LensInfo.Make = "";
  LensInfo.Model = "";
}

