LOGMODULE("ftpd");

// FTP daemon configuration
constexpr u16 ListenPort = 21;
constexpr u8 MaxConnections = 1;

// Constructor
CFTPDaemon::CFTPDaemon(const char* pUser, const char* pPassword)
    : CTask(TASK_STACK_SIZE, true),
      m_pListenSocket(nullptr),
      m_pUser(pUser),
      m_pPassword(pPassword) {
}

// Destructor
CFTPDaemon::~CFTPDaemon() {
    if (m_pListenSocket)
        delete m_pListenSocket;
}

// Initialize the FTP daemon
bool CFTPDaemon::Initialize() {
    CNetSubSystem* const pNet = CNetSubSystem::Get();

    // Create listening socket
    if ((m_pListenSocket = new CSocket(pNet, IPPROTO_TCP)) == nullptr)
        return false;

    // Bind to port
    if (m_pListenSocket->Bind(ListenPort) != 0) {
        LOGERR("Couldn't bind to port %d", ListenPort);
        return false;
    }

    // Start listening
    if (m_pListenSocket->Listen() != 0) {
        LOGERR("Failed to listen on control socket");
        return false;
    }

    // We started as a suspended task; run now that initialization is successful
    Start();
    return true;
}

// Main daemon loop
void CFTPDaemon::Run() {
    assert(m_pListenSocket != nullptr);
    LOGNOTE("Listener task spawned");

    while (true) {
        CIPAddress ClientIPAddress;
        u16 nClientPort;

        LOGDBG("Listener: waiting for connection");

        // Accept incoming connection
        CSocket* pConnection = m_pListenSocket->Accept(&ClientIPAddress, &nClientPort);
        if (pConnection == nullptr) {
            LOGERR("Unable to accept connection");
            continue;
        }

        // Log client info
        CString IPAddressString;
        ClientIPAddress.Format(&IPAddressString);
        LOGNOTE("Incoming connection from %s:%d", static_cast<const char*>(IPAddressString), nClientPort);

        // Check connection limit
        if (CFTPWorker::GetInstanceCount() >= MaxConnections) {
            pConnection->Send("421 Maximum number of connections reached.\r\n", 45, 0);
            delete pConnection;
            LOGWARN("Maximum number of connections reached");
            continue;
        }

        // Spawn new worker for the connection
        new CFTPWorker(pConnection, m_pUser, m_pPassword);
    }
}

#include <charPipeline/structures/dolphinString.h>

// Concatenates two strings into destination
u8 Strcat(char* str1, char* str2, char* dst)
{
    char* srcCursor = str1;
    char* dstCursor = dst;

    // Validate inputs
    if (!dst) {
        return 0;
    }
    if (!str1) {
        return 0;
    }
    if (!str2) {
        return 0;
    }

    // Copy first string
    while ((s8)*srcCursor != 0) {
        *dstCursor = *srcCursor;
        dstCursor++;
        srcCursor++;
    }

    // Copy second string
    srcCursor = str2;
    while ((s8)*srcCursor != 0) {
        *dstCursor = *srcCursor;
        dstCursor++;
        srcCursor++;
    }

    // Null-terminate
    *dstCursor = 0;
    return 1;
}

// Copies source string to destination
void Strcpy(char* dst, char* src)
{
    do {
        *dst = *src;
        dst++;
        src++;
    } while ((s8)*src != 0);
}

// Compares two strings lexicographically
s8 Strcmp(char* str1, char* str2)
{
    char* cursor1 = str1;
    char* cursor2 = str2;

    while (1) {
        if ((s8)*cursor1 < (s8)*cursor2) {
            return 1;
        }
        if ((s8)*cursor1 > (s8)*cursor2) {
            return -1;
        }
        cursor1++;
        cursor2++;
        if ((s8)*cursor1 == 0 || (s8)*cursor2 == 0) {
            return 0;
        }
    }
}

// Returns length of string
u32 Strlen(char* str)
{
    char* cursor = str;
    u32 counter = 0;

    if (!str) {
        return 0;
    }

    while ((s8)*cursor != 0) {
        cursor++;
        counter++;
    }

    return counter;
}

