// Check if key matches redirect table
static BOOL IsRegKey(HKEY hKey, int rkVal) {
    if (rkVal < enSoftwareKey || rkVal >= enCountKey)
        return FALSE;
    if (hKey == (HKEY)(REG_KEY_BASE + (rkVal)))
        return TRUE;
    return FALSE;
}

// Check if key is a fake registry key
static BOOL IsFakeRegKey(unsigned long ulKey) {
    if ((ulKey) >= (REG_KEY_BASE + enSoftwareKey) && (ulKey) < (REG_KEY_BASE + enCountKey))
        return TRUE;
    return FALSE;
}

// Get index of redirected key
static int GetRedirectKey(HKEY hKey) {
    for (int i = 0; i < enCountKey; i++)
        if (IsRegKey(hKey, i))
            return i;
    return enCountKey;
}

// Map subkey string to enum value
static BOOL RegLookup(const char *lpSubKey, unsigned long *ulKey) {
    BOOL ret = FALSE;
    if (_stricmp(lpSubKey, "Software") == 0) {
        *ulKey = enSoftwareKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Maxis") == 0) {
        *ulKey = enMaxisKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, gamePrimaryKey) == 0) {
        *ulKey = enSC2KKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Paths") == 0) {
        *ulKey = enPathsKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Windows") == 0) {
        *ulKey = enWindowsKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Version") == 0) {
        *ulKey = enVersionKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Options") == 0) {
        *ulKey = enOptionsKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Localize") == 0) {
        *ulKey = enLocalizeKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "Registration") == 0) {
        *ulKey = enRegistrationKey;
        ret = TRUE;
    }
    else if (_stricmp(lpSubKey, "SCURK") == 0) {
        *ulKey = enSCURKKey;
        ret = TRUE;
    }
    return ret;
}

// Map registry key to INI section name
static const char *SectionLookup(HKEY hKey) {
    switch (GetRedirectKey(hKey)) {
        case enWindowsKey:
            return "Windows";
        case enVersionKey:
            return "Version";
        case enOptionsKey:
            return "Options";
        case enLocalizeKey:
            return "Localize";
        case enSCURKKey:
            return "SCURK";
        default:
            break;
    }
    return NULL;
}

