// Helper function to concatenate two vectors
template <typename T>
inline std::vector<T> concatenate_vector(const std::vector<T> &lhs,
                                         const std::vector<T> &rhs) {
  std::vector<T> result;
  result.assign(lhs.begin(), lhs.end());
  result.insert(result.end(), rhs.begin(), rhs.end());
  return result;
}

