using namespace std;

// Normalizes a string by removing leading zeros
string normalize(string s) {
    if (s.empty()) return "0";
    size_t startpos = s.find_first_not_of('0');
    if (startpos == string::npos) return "0";
    return s.substr(startpos);
}

// Adds two large numbers represented as strings
string big_add(string x, string y) {
    if (x == "0") return y;
    if (y == "0") return x;
    string a = x;
    string b = y;
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    size_t len = max(a.size(), b.size());
    a.resize(len, '0');
    b.resize(len, '0');
    string res(len + 1, '0');
    int carry = 0;
    for (size_t i = 0; i < len; ++i) {
        int sum = (a[i] - '0') + (b[i] - '0') + carry;
        res[i] = (sum % 10) + '0';
        carry = sum / 10;
    }
    res[len] = carry + '0';
    reverse(res.begin(), res.end());
    size_t startpos = res.find_first_not_of('0');
    if (startpos == string::npos) return "0";
    return res.substr(startpos);
}

// Subtracts two large numbers represented as strings (assumes x >= y)
string big_subtract(string x, string y) {
    if (y == "0") return x;
    if (x == y) return "0";
    string a = x;
    string b = y;
    reverse(a.begin(), a.end());
    reverse(b.begin(), b.end());
    size_t len = a.size();
    b.resize(len, '0');
    string res(len, '0');
    int borrow = 0;
    for (size_t i = 0; i < len; ++i) {
        int diff = (a[i] - '0') - (b[i] - '0') - borrow;
        if (diff < 0) {
            diff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        res[i] = diff + '0';
    }
    reverse(res.begin(), res.end());
    size_t startpos = res.find_first_not_of('0');
    if (startpos == string::npos) return "0";
    return res.substr(startpos);
}

int main() {
    int n;
    string W_str;
    cin >> n >> W_str;
    W_str = normalize(W_str);

    vector<string> a(n);
    for (auto& s : a) {
        cin >> s;
        s = normalize(s);
    }

    vector<pair<string, int>> items(n);
    for (int i = 0; i < n; i++) {
        items[i] = {a[i], i};
    }

    // Custom comparator for comparing large numbers as strings
    auto big_cmp = [](const string& x, const string& y) -> int {
        if (x.size() > y.size()) return 1;
        if (x.size() < y.size()) return -1;
        if (x > y) return 1;
        if (x < y) return -1;
        return 0;
    };

    // Sort items in descending order based on their numeric value
    sort(items.begin(), items.end(), [&](const pair<string, int>& p1, const pair<string, int>& p2) {
        return big_cmp(p1.first, p2.first) > 0;
    });

    vector<int> choice(n, 0);
    string current = "0";

    // Greedy selection: add items while not exceeding capacity
    for (auto& p : items) {
        string temp = big_add(current, p.first);
        if (big_cmp(temp, W_str) <= 0) {
            current = temp;
            choice[p.second] = 1;
        }
    }

    // Calculate remaining capacity
    string R = big_subtract(W_str, current);

    // Try to improve solution by adding smallest unused item that doesn't exceed capacity
    if (big_cmp(R, "0") > 0) {
        string min_not = "";
        int best_i = -1;
        for (int i = 0; i < n; i++) {
            if (choice[i] == 0 && big_cmp(a[i], "0") > 0) {
                if (best_i == -1 || big_cmp(a[i], min_not) < 0) {
                    min_not = a[i];
                    best_i = i;
                }
            }
        }
        if (best_i != -1) {
            string temp = big_add(current, min_not);
            string error_new = big_subtract(temp, W_str);
            if (big_cmp(error_new, R) < 0) {
                choice[best_i] = 1;
            }
        }
    }

    // Output the selection result
    for (int i = 0; i < n; i++) {
        if (i > 0) cout << " ";
        cout << choice[i];
    }
    cout << endl;

    return 0;
}

#include <iostream>

#if TS_MODEL == TS_MODEL_FT6X36

    #include "FT6X36.h"

// Static instance initialization
FT6X36* FT6X36::_instance = nullptr;

// Constructor
FT6X36::FT6X36(TwoWire* wire, int8_t intPin)
{
    _instance = this;
    _wire = wire;
    _intPin = intPin;
}

// Destructor
FT6X36::~FT6X36()
{
    detachInterrupt(digitalPinToInterrupt(_intPin));
}

// Interrupt service routine (static)
void ISR_ATTR FT6X36::isr()
{
    if (_instance) _instance->onInterrupt();
}

// Initialize the touch controller
bool FT6X36::begin(uint8_t threshold)
{
    if (readRegister8(FT6X36_REG_PANEL_ID) != FT6X36_VENDID) return false;

    uint8_t id = readRegister8(FT6X36_REG_CHIPID);
    if (id != FT6206_CHIPID && id != FT6236_CHIPID && id != FT6336_CHIPID) return false;

    pinMode(_intPin, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt(_intPin), FT6X36::isr, FALLING);

    writeRegister8(FT6X36_REG_DEVICE_MODE, 0x00);
    writeRegister8(FT6X36_REG_THRESHHOLD, threshold);
    writeRegister8(FT6X36_REG_TOUCHRATE_ACTIVE, 0x0E);

    return true;
}

// Register custom interrupt handler
void FT6X36::registerIsrHandler(void (*fn)())
{
    _isrHandler = fn;
}

// Register touch event handler
void FT6X36::registerTouchHandler(void (*fn)(TPoint point, TEvent e))
{
    _touchHandler = fn;
}

// Get number of touches
uint8_t FT6X36::touched()
{
    uint8_t n = readRegister8(FT6X36_REG_NUM_TOUCHES);
    if (n > 2) { n = 0; }
    return n;
}

// Main loop for processing pending interrupts
void FT6X36::loop()
{
    if (_irqPending)
    {
        _irqPending = false;
        processTouch();
    }
}

// Process raw touch data
void FT6X36::processTouch()
{
    readData();

    uint8_t   n = 0;
    TRawEvent event = (TRawEvent)_touchEvent[n];
    TPoint    point{_touchX[n], _touchY[n]};

    if (event == TRawEvent::PressDown)
    {
        _points[0] = point;
        _pointIdx = 1;
        _dragMode = false;
        _touchStartTime = millis();
        fireEvent(point, TEvent::TouchStart);
    }
    else if (event == TRawEvent::Contact)
    {
        if (_pointIdx < 10)
        {
            _points[_pointIdx] = point;
            _pointIdx += 1;
        }

        if (!_dragMode && _points[0].aboutEqual(point) && millis() - _touchStartTime > 300)
        {
            _dragMode = true;
            fireEvent(point, TEvent::DragStart);
        }
        else if (_dragMode)
        {
            fireEvent(point, TEvent::DragMove);
        }

        fireEvent(point, TEvent::TouchMove);
    }
    else if (event == TRawEvent::LiftUp)
    {
        _points[9] = point;
        _touchEndTime = millis();
        fireEvent(point, TEvent::TouchEnd);

        if (_dragMode)
        {
            fireEvent(point, TEvent::DragEnd);
            _dragMode = false;
        }

        if (_points[0].aboutEqual(point) && _touchEndTime - _touchStartTime <= 300)
        {
            fireEvent(point, TEvent::Tap);
            _points[0] = {0, 0};
            _touchStartTime = 0;
        }
    }
    else
    {
        // Unknown event — ignore
    }
}

// Called from ISR: mark interrupt as pending
void FT6X36::onInterrupt()
{
    _irqPending = true;
    if (_isrHandler) { _isrHandler(); }
}

// Read raw data from registers
void FT6X36::readData(void)
{
    const uint8_t size = 16;
    uint8_t       data[size];

    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(0);
    _wire->endTransmission();

    _wire->requestFrom((uint8_t)FT6X36_ADDR, size);

    for (uint8_t i = 0; i < size; i++) data[i] = Wire.read();

#ifdef FT6X36_DEBUG
    Serial.println("REGISTERS:");
    for (int16_t i = 0; i < size; i++)
    {
        Serial.print("0x");
        Serial.print(i, HEX);
        Serial.print(" = 0x");
        Serial.println(data[i], HEX);
    }
    Serial.println();

    Serial.print("TOUCHES: ");
    Serial.println(data[FT6X36_REG_NUM_TOUCHES]);
    Serial.print("GESTURE: ");
    Serial.println(data[FT6X36_REG_GESTURE_ID]);
#endif

    _touches = data[FT6X36_REG_NUM_TOUCHES];

    const uint8_t addrShift = 6;
    for (uint8_t i = 0; i < 2; i++)
    {
        _touchX[i] = data[FT6X36_REG_P1_XH + i * addrShift] & 0x0F;
        _touchX[i] <<= 8;
        _touchX[i] |= data[FT6X36_REG_P1_XL + i * addrShift];

        _touchY[i] = data[FT6X36_REG_P1_YH + i * addrShift] & 0x0F;
        _touchY[i] <<= 8;
        _touchY[i] |= data[FT6X36_REG_P1_YL + i * addrShift];

        _touchEvent[i] = data[FT6X36_REG_P1_XH + i * addrShift] >> 6;
    }
}

// Write 8-bit register value
void FT6X36::writeRegister8(uint8_t reg, uint8_t value)
{
    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(reg);
    _wire->write(value);
    _wire->endTransmission();
}

// Read 8-bit register value
uint8_t FT6X36::readRegister8(uint8_t reg)
{
    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(reg);
    _wire->endTransmission();

    _wire->requestFrom((uint8_t)FT6X36_ADDR, (uint8_t)1);
    uint8_t value = _wire->read();

#ifdef I2C_DEBUG
    Serial.print("REG 0x");
    Serial.print(reg, HEX);
    Serial.print(": 0x");
    Serial.println(value, HEX);
#endif

    return value;
}

// Fire registered touch event
void FT6X36::fireEvent(TPoint point, TEvent e)
{
    if (_touchHandler) _touchHandler(point, e);
}

#ifdef FT6X36_DEBUG
// Debug helper: print all relevant registers
void FT6X36::debugInfo()
