TEST_F(ProgramTest, UniformMatrixTranspose) {
    char infoLog[1024] = "";
    GLuint vs = CreateShader(GL_VERTEX_SHADER);
    ShaderSource(vs, 1, &vsSrc, NULL);
    printf("Compiling vertex shader: %s\n", vsSrc);
