// Namespace for utility functions
namespace utils {
    // Computes greatest common divisor using Euclidean algorithm
    int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
}

// Structure representing a rational number
struct RationalNumber {
    int numerator;
    int denominator;
};

// Simplifies the rational number by dividing both parts by their GCD
void rationalizeRationalNumber(RationalNumber& rationalNumber) {
    int gcdValue = utils::gcd(rationalNumber.denominator, rationalNumber.numerator);
    rationalNumber.numerator /= gcdValue;
    rationalNumber.denominator /= gcdValue;
}

// Adds two rational numbers and returns the simplified result
RationalNumber addRationalNumbers(const RationalNumber& a, const RationalNumber& b) {
    int resultDenominator = a.denominator * b.denominator;
    int resultNumerator = a.numerator * b.denominator + a.denominator * b.numerator;
    RationalNumber result { resultNumerator, resultDenominator };
    rationalizeRationalNumber(result);
    return result;
}

// Subtracts second rational number from the first and returns the simplified result
RationalNumber subtractRationalNumbers(const RationalNumber& a, const RationalNumber& b) {
    int resultDenominator = a.denominator * b.denominator;
    int resultNumerator = a.numerator * b.denominator - a.denominator * b.numerator;
    RationalNumber result { resultNumerator, resultDenominator };
    rationalizeRationalNumber(result);
    return result;
}

// Multiplies two rational numbers and returns the simplified result
RationalNumber multiplyRationalNumbers(const RationalNumber& a, const RationalNumber& b) {
    RationalNumber result = { a.numerator * b.numerator, a.denominator * b.denominator };
    rationalizeRationalNumber(result);
    return result;
}

// Divides first rational number by the second and returns the simplified result
RationalNumber divideRationalNumbers(const RationalNumber& a, const RationalNumber& b) {
    RationalNumber reciprocalOfB { b.denominator, b.numerator };
    return multiplyRationalNumbers(a, reciprocalOfB);
}

// Checks if the rational number is valid (non-zero denominator)
bool isValidRationalNumber(const RationalNumber& rationalNumber) {
    return rationalNumber.denominator != 0;
}

// Checks if the rational number represents a whole number
bool isWholeNumber(const RationalNumber& rationalNumber) {
    return rationalNumber.numerator % rationalNumber.denominator == 0;
}

// Prints the rational number in a formatted way, handling negative signs appropriately
void printRationalNumber(const RationalNumber& rationalNumber) {
    bool negativeDenominator = rationalNumber.denominator < 0;
    bool negativeNumerator = rationalNumber.numerator < 0;
    bool isNegative = !(negativeDenominator && negativeNumerator) && (negativeDenominator || negativeNumerator);
    cout << (isNegative ? "-(" : "") << abs(rationalNumber.numerator) << "/" << abs(rationalNumber.denominator) << (isNegative ? ")" : "") << '\n';
}

// Main function demonstrating rational number operations
int main() {
    RationalNumber a{ 1, 2 };
    RationalNumber b = { 3, 4 };

    printRationalNumber(addRationalNumbers(a, b));      // 5/4
    printRationalNumber(subtractRationalNumbers(a, b)); // -(1/4)
    printRationalNumber(multiplyRationalNumbers(a, b)); // 3/8 
    printRationalNumber(divideRationalNumbers(a, b));   // 2/3
    printRationalNumber({-1, -2});                      // 1/2

    return 0;
}

#include "wndproc.hpp"

// Static instance initialization
memory::hooks::WndProc* memory::hooks::WndProc::_instance {};

// Constructor
memory::hooks::WndProc::WndProc(HWND hWnd) : Hook("WndProc", nullptr, nullptr, nullptr)
{
    _instance = this;
    _hWnd     = hWnd;
}

// Destructor
memory::hooks::WndProc::~WndProc()
{
    disable(false);
    if (_instance == this)
    {
        _instance = nullptr;
    }
}

// Enable window procedure hook
bool memory::hooks::WndProc::enable()
{
    _originalWndProc = reinterpret_cast<WNDPROC>(SetWindowLongPtr(
        _hWnd,
        GWLP_WNDPROC,
        reinterpret_cast<LONG_PTR>(wndProc)
    ));

    if (!_originalWndProc)
    {
        return false;
    }

    return true;
}

// Disable window procedure hook
bool memory::hooks::WndProc::disable(bool uninitialize)
{
    SetWindowLongPtr(_hWnd, GWLP_WNDPROC, reinterpret_cast<LONG_PTR>(_originalWndProc));
    return true;
}

// Add callback function
void memory::hooks::WndProc::addCallback(const std::function<uintptr_t(HWND, UINT, WPARAM, LPARAM)>& callback)
{
    _callbacks.push_back(callback);
}

// Internal window procedure handler
LRESULT memory::hooks::WndProc::internalWndProc(HWND hWnd, const UINT msg, const WPARAM wParam, const LPARAM lParam) const
{
    bool callOriginal = true;

    for (const auto& callback : _callbacks)
    {
        if (callback(hWnd, msg, wParam, lParam) == 0)
        {
            callOriginal = false;
        }
    }

    if (!callOriginal)
    {
        return 0;
    }

    return CallWindowProc(_originalWndProc, hWnd, msg, wParam, lParam);
}

// Static window procedure entry point
LRESULT memory::hooks::WndProc::wndProc(HWND hWnd, const UINT msg, const WPARAM wParam, const LPARAM lParam)
{
    if (!_instance)
    {
        return 0;
    }

    return _instance->internalWndProc(hWnd, msg, wParam, lParam);
}

#include "ROL_StrUtils.hpp"
