SInt& SInt::operator<<=(unsigned count)
{
    CJC_ASSERT(count <= width);
    if (count == width) {
        val = 0;
    } else {
        val <<= count;
    }
    return ClearUnusedBits();
}

SInt& SInt::operator<<=(const SInt& count)
{
    *this <<= static_cast<unsigned>(count.GetULimitedValue(width));
