#include <stdlib.h>

// Macro to calculate pointer to the i-th member in the table
#define table_ptr(i) (((char*)table_base) + (member_size * ((i)-1)))

// Macro to swap two memory blocks of size cnt
#define swap(dst, src, cnt)                                                                        \
  do {                                                                                             \
    char* p;                                                                                       \
    char* q;                                                                                       \
    size_t n = cnt;                                                                                \
                                                                                                   \
    unsigned long tmp;                                                                             \
                                                                                                   \
    for (p = (char*)src - 1, q = (char*)dst - 1, n++; --n;) {                                      \
      tmp = *++q;                                                                                  \
      *q = *++p;                                                                                   \
      *p = tmp;                                                                                    \
    }                                                                                              \
  } while (0)

// Implementation of heap sort algorithm
void qsort(void* table_base, size_t num_members, size_t member_size, _compare_function compare_members) 
{
  size_t l, r, j;
  char* lp;
  char* rp;
  char* ip;
  char* jp;
  char* kp;

  // Handle edge case: less than 2 elements
  if (num_members < 2)
    return;

  // Initialize heap indices
  r = num_members;
  l = (r / 2) + 1;
  lp = table_ptr(l);
  rp = table_ptr(r);

  // Main sorting loop
  for (;;) {
    if (l > 1) {
      // Move left pointer and decrement l
      l--;
      lp -= member_size;
    } else {
      // Swap root with last element and shrink heap
      swap(lp, rp, member_size);
      if (--r == 1)
        return;
      rp -= member_size;
    }

    // Heapify process
    j = l;
    jp = table_ptr(j);
    while (j * 2 <= r) {
      j *= 2;
      ip = jp;
      jp = table_ptr(j);

      // Find larger child if right child exists
      if (j < r) {
        kp = jp + member_size;
        if (compare_members(jp, kp) < 0) {
          j++;
          jp = kp;
        }
      }

      // Swap if parent is smaller than largest child
      if (compare_members(ip, jp) < 0)
        swap(ip, jp, member_size);
      else
        break;
    }
  }
}

