// Interpolates tangent for spline interpolation
void InterpTangent(
    const Vector3 &v1,
    const Vector3 &v2,
    const Vector3 &v3,
    const Vector3 &v4,
    float f,
    Vector3 &vout
) {
    float ftimes6;
    float scale3;
    float scale;

    ftimes6 = f * 6.0f;
    scale = f * f;

    Scale(v1, (scale * 6.0f) - ftimes6, vout);

    Vector3 vtmp;
    scale3 = scale * 3.0f;

    Scale(v2, 1.0f + (scale3 - (f * 4.0f)), vtmp);
    Add(vout, vtmp, vout);

    Scale(v3, (scale * -6.0f) + ftimes6, vtmp);
    Add(vout, vtmp, vout);

    Scale(v4, (scale3 - (f * 2.0f)), vtmp);
    Add(vout, vtmp, vout);
}

// Computes tangent for spline using neighboring keys
void SplineTangent(const Keys<Vector3, Vector3> &keys, int i, Vector3 &vout) {
    int size = keys.size();
    MILO_ASSERT(size > 1, 0x17);

    if (size == 2) {
        Subtract(keys[1].value, keys[0].value, vout);
    } else if (i <= 0) {
        Subtract(keys[1].value, keys[0].value, vout);
        Scale(vout, 1.5f, vout);

        Vector3 vtmp;
        Subtract(keys[2].value, keys[0].value, vtmp);
        Scale(vtmp, 0.25f, vtmp);
        Subtract(vout, vtmp, vout);
    } else if (i >= size - 1) {
        Subtract(keys[size - 1].value, keys[size - 2].value, vout);
        Scale(vout, 1.5f, vout);

        Vector3 vtmp;
        Subtract(keys[size - 1].value, keys[size - 3].value, vtmp);
        Scale(vtmp, 0.25f, vtmp);
        Subtract(vout, vtmp, vout);
    } else {
        Subtract(keys[i + 1].value, keys[i - 1].value, vout);
        Scale(vout, 0.5f, vout);
    }
}

// Interpolates vector with optional spline support
void InterpVector(
    const Keys<Vector3, Vector3> &keys,
    const Key<Vector3> *prev,
    const Key<Vector3> *next,
    float ref,
    bool spline,
    Vector3 &vref,
    Vector3 *vptr
) {
    if (keys.size() < 3) {
        spline = false;

        if (keys.size() < 2) {
            if (vptr)
                vptr->Set(0.0f, 1.0f, 0.0f);

            if (keys.size() != 0)
                vref = prev->value;
            else
                vref.Set(0, 0, 0);

            return;
        }
    }

    int idx = prev - keys.begin();

    if (spline) {
        float fsq = ref * ref;
        float fcubed = fsq * ref;
        float fsq3 = fsq * 3.0f;

        Scale(prev->value, (fcubed * 2.0f - fsq3) + 1.0f, vref);

        Vector3 v70;
        SplineTangent(keys, idx, v70);

        Vector3 v7c;
        Vector3 v88;

        Scale(v70, ref + fsq * -2.0f + fcubed, v88);
        Add(vref, v88, vref);

        Scale(next->value, fcubed * -2.0f + fsq3, v88);
        Add(vref, v88, vref);

        SplineTangent(keys, idx + 1, v7c);
        Scale(v7c, fcubed - fsq, v88);
        Add(vref, v88, vref);

        if (vptr) {
            InterpTangent(prev->value, v70, next->value, v7c, ref, *vptr);
        }
    } else {
        Interp(prev->value, next->value, ref, vref);

        if (vptr) {
            if (idx == keys.size() - 1) {
                idx--;
            }
            Subtract(keys[idx + 1].value, keys[idx].value, *vptr);
        }
    }
}

// Convenience overload for InterpVector
void InterpVector(
    const Keys<Vector3, Vector3> &keys,
    bool spline,
    float frame,
    Vector3 &vref,
    Vector3 *vptr
) {
    const Key<Vector3> *prev;
    const Key<Vector3> *next;
    float ref;

    keys.AtFrame(frame, prev, next, ref);
    InterpVector(keys, prev, next, ref, spline, vref, vptr);
}

// Spherical cubic interpolation for quaternions
void QuatSpline(
    const Keys<Hmx::Quat, Hmx::Quat> &keys,
    const Key<Hmx::Quat> *prev,
    const Key<Hmx::Quat> *next,
    float ref,
    Hmx::Quat &qout
) {
    MILO_ASSERT(keys.size(), 0x9B);

    if (prev == next) {
        qout = prev->value;
    } else {
        int idx = prev - &keys.front();

        Hmx::Quat prevQuat = prev->value;
        Hmx::Quat nextQuat = next->value;
        Hmx::Quat q88 = idx == 0 ? prevQuat : keys[idx - 1].value;
        Hmx::Quat q58 = idx + 1 == keys.size() - 1 ? nextQuat : keys[idx + 2].value;

        NormalizeTo(prevQuat, q88);
        NormalizeTo(prevQuat, nextQuat);
        NormalizeTo(prevQuat, q58);

        for (int i = 0; i < 4; i++) {
            // Match base computation order exactly
            float pq = prevQuat[i];
            float p2 = pq * 2.0f;
            float nq = nextQuat[i];
            float q8 = q88[i];
            float n3mq8 = nq * 3.0f - q8;
            float q5 = q58[i];
            float diff = nq - q8;
            float n4p2 = nq * 4.0f + p2;
            float coef3part = q5 - n3mq8;
            float coef1 = diff * 0.5f;
            float tmp = n4p2 - pq * 5.0f;
            float coef3 = coef3part - diff;
            float coef2 = tmp - q5;

            qout[i] = ((coef3 * ref + coef2) * ref + coef1) * ref + p2;
        }

        Normalize(qout, qout);
    }
}

