#include "Scope.h"

// Constructor: initializes scope by pushing a new level
Scope::Scope()
{
    pushLevel();
}

// Pushes a new scope level onto the stack
void Scope::pushLevel()
{
    scopeLevels.push(ScopeLevel());
}

// Pops the current scope level from the stack
void Scope::popLevel()
{
    scopeLevels.pop();
}

// Sets a wrapped value in the current scope; returns false if already exists
bool Scope::setWrappedValue(string identifier, shared_ptr<WrappedValue> wrappedValue)
{
    if (scopeLevels.top().wrappedValueMap[identifier] != nullptr)
        return false;

    scopeLevels.top().wrappedValueMap[identifier] = wrappedValue;
    return true;
}

// Retrieves a wrapped value by identifier, searching from top to bottom of scope stack
shared_ptr<WrappedValue> Scope::getWrappedValue(string identifier)
{
    stack<ScopeLevel> scopeLevels = this->scopeLevels;
    while (!scopeLevels.empty())
    {
        shared_ptr<WrappedValue> wrappedValue = scopeLevels.top().wrappedValueMap[identifier];
        if (wrappedValue != nullptr)
            return wrappedValue;

        scopeLevels.pop();
    }
    return nullptr;
}

// Sets a function in the current scope; returns false if already exists
bool Scope::setFunction(string name, llvm::Function *function)
{
    if (scopeLevels.top().funMap[name] != nullptr)
        return false;

    scopeLevels.top().funMap[name] = function;
    return true;
}

// Retrieves a function by name, searching from top to bottom of scope stack
llvm::Function* Scope::getFunction(string name)
{
    stack<ScopeLevel> scopeLevels = this->scopeLevels;
    while (!scopeLevels.empty())
    {
        llvm::Function *function = scopeLevels.top().funMap[name];
        if (function != nullptr)
            return function;

        scopeLevels.pop();
    }
    return nullptr;
}

// Sets an inline assembly in the current scope; returns false if already exists
bool Scope::setInlineAsm(string name, llvm::InlineAsm *inlineAsm)
{
    if (scopeLevels.top().rawFunMap[name] != nullptr)
        return false;

    scopeLevels.top().rawFunMap[name] = inlineAsm;
    return true;
}

// Retrieves an inline assembly by name, searching from top to bottom of scope stack
llvm::InlineAsm *Scope::getInlineAsm(string name)
{
    stack<ScopeLevel> scopeLevels = this->scopeLevels;
    while (!scopeLevels.empty())
    {
        llvm::InlineAsm *inlineAsm = scopeLevels.top().rawFunMap[name];
        if (inlineAsm != nullptr)
            return inlineAsm;

        scopeLevels.pop();
    }
    return nullptr;
}

// Sets a struct type and its member names in the current scope
bool Scope::setStruct(string structName, llvm::StructType *structType, vector<string> memberNames)
{
    scopeLevels.top().structTypeMap[structName] = structType;
    scopeLevels.top().structMembersMap[structName] = memberNames;
    return true;
}

// Retrieves a struct type by name, searching from top to bottom of scope stack
llvm::StructType *Scope::getStructType(string structName)
{
    stack<ScopeLevel> scopeLevels = this->scopeLevels;
    while (!scopeLevels.empty())
    {
        llvm::StructType *structType = scopeLevels.top().structTypeMap[structName];
        if (structType != nullptr)
            return structType;

        scopeLevels.pop();
    }
    return nullptr;
}

// Gets the index of a member within a struct, searching from top to bottom of scope stack
optional<int> Scope::getStructMemberIndex(string structName, string memberName)
{
    stack<ScopeLevel> scopeLevels = this->scopeLevels;
    while (!scopeLevels.empty())
    {
        if (scopeLevels.top().structMembersMap.contains(structName))
        {
            vector<string> memberNames = scopeLevels.top().structMembersMap[structName];
            for (int i=0; i<memberNames.size(); i++)
            {
                if (memberNames[i].compare(memberName) == 0)
                    return i;
            }
        }
        scopeLevels.pop();
    }
    return {};
}

#include "TuringTest.h"
#include "ByteBuffer.h"
#include "ByteBufferIterator.h"

using namespace turing::test;

class ByteBufferIteratorTest : public TuringTest {
protected:
    void initialize() override {
    }

    void terminate() override {
    }
};

template <fs::TrivialPrimitive T>
void appendBytes(fs::ByteBuffer& buf, std::vector<T>& data) {
    const size_t prevSize = buf.size();
    const size_t size = data.size() * sizeof(T);
    buf.resize(prevSize + size);
    std::memcpy(buf.data() + prevSize, data.data(), size);
}

template <fs::TrivialPrimitive T>
void appendBytes(fs::ByteBuffer& buf, T data) {
    const size_t prevSize = buf.size();
    const size_t size = sizeof(T);
    buf.resize(prevSize + size);
    std::memcpy(buf.data() + prevSize, &data, size);
}

template <fs::CharPrimitive T>
void appendBytes(fs::ByteBuffer& buf, std::basic_string_view<T> data) {
    const size_t prevSize = buf.size();
    const size_t size = data.size() * sizeof(T);
    buf.resize(prevSize + size);
    std::memcpy(buf.data() + prevSize, data.data(), size);
}

TEST_F(ByteBufferIteratorTest, General) {
    using namespace std::literals;

    fs::ByteBuffer buf;

    // Vector inputs
    std::vector<uint16_t> integers = {0, 1, 2, 3, 4};
    std::vector<float> floats = {3.14159f, 1.61803f};

    appendBytes(buf, integers);
    appendBytes(buf, floats);
    appendBytes(buf, 2.71828);
    appendBytes(buf, "Hello world"sv);

    // Reading
    fs::ByteBufferIterator it(buf);

    std::span<const uint16_t> v1 = it.get<uint16_t>(3);
    ASSERT_EQ(v1[0], 0);
    ASSERT_EQ(v1[1], 1);
    ASSERT_EQ(v1[2], 2);

    ASSERT_EQ(it.get<uint16_t>(), 3);
    ASSERT_EQ(it.get<uint16_t>(), 4);

    ASSERT_NEAR(it.get<float>(), 3.14159f, 0.00001f);
    ASSERT_NEAR(it.get<float>(), 1.61803f, 0.00001f);

    ASSERT_NEAR(it.get<double>(), 2.71828, 0.00001);

    ASSERT_TRUE(it.get<char>(11) == "Hello world"sv);
}

int main(int argc, char** argv) {
    return turing::test::turingTestMain(argc, argv, [] {
        testing::GTEST_FLAG(repeat) = 4;
    });
}

#include <gtest/gtest.h>
#include <ocs2_core/ComputationRequest.h>
#include <ocs2_core/PreComputation.h>

using Request = ocs2::Request;

// Test convenient interface for PreComputation
TEST(testPrecomputation, convenientInterface) {
  // Check that this compiles
  ocs2::PreComputation preComputation;
  preComputation.request(Request::Dynamics + Request::Approximation, 0.0, ocs2::vector_t(), ocs2::vector_t());
  preComputation.requestPreJump(Request::Dynamics + Request::Approximation, 0.0, ocs2::vector_t());
  preComputation.requestFinal(Request::Approximation, 0.0, ocs2::vector_t());
}

// Test contains functionality
TEST(testPrecomputation, containts) {
  constexpr auto request = Request::Dynamics + Request::Cost + Request::Constraint + Request::SoftConstraint + Request::Approximation;
  ASSERT_TRUE(request.contains(Request::Dynamics));
  ASSERT_TRUE(request.contains(Request::Cost));
  ASSERT_TRUE(request.contains(Request::Constraint));
  ASSERT_TRUE(request.contains(Request::SoftConstraint));
  ASSERT_TRUE(request.contains(Request::Approximation));

  constexpr ocs2::RequestSet request2 = Request::Dynamics;
  ASSERT_TRUE(request2.contains(Request::Dynamics));
  ASSERT_FALSE(request2.contains(Request::Cost));
  ASSERT_FALSE(request2.contains(Request::Constraint));
  ASSERT_FALSE(request2.contains(Request::SoftConstraint));
  ASSERT_FALSE(request2.contains(Request::Approximation));

  constexpr auto request3 = Request::Cost + Request::Constraint;
  ASSERT_FALSE(request3.contains(Request::Dynamics));
  ASSERT_TRUE(request3.contains(Request::Constraint));
  ASSERT_TRUE(request3.contains(Request::Cost));
  ASSERT_FALSE(request3.contains(Request::SoftConstraint));
  ASSERT_FALSE(request3.contains(Request::Approximation));
}

// Test containsAny and containsAll functionality
TEST(testPrecomputation, containtsAnyAll) {
  constexpr auto request1 = Request::Dynamics + Request::Cost;
  constexpr auto request2 = Request::Constraint + Request::Cost;
  ASSERT_TRUE(request1.containsAny(request2));
  ASSERT_FALSE(request1.containsAll(request2));

  constexpr auto request3 = Request::Constraint + Request::Cost + Request::Approximation;
  ASSERT_TRUE(request3.containsAll(request2));
}

