// Test case for iterators and insert
TEST_CASE_MAP("iterators_insert", int, int)
{
    auto v = std::vector<std::pair<int, int>>();
    v.reserve(1000);

    // Fill the vector with pairs
    for(int i=0; i<1000; ++i)
    {
        v.emplace_back(i, i);
    }

    // Construct map from vector iterators
    auto map = map_t(v.begin(), v.end());
    REQUIRE(map.size() == v.size());

    // Verify all elements are present
    for(auto const& kv : v)
    {
        REQUIRE(map.count(kv.first) == 1);
        auto it = map.find(kv.first);
        REQUIRE(it != map.end());
    }
}

