// Finds the game window by enumerating top-level windows
HWND WindowFinder::FindGameWindow() noexcept
{
    const DWORD currentProcessId = GetCurrentProcessId();
    const HWND consoleHwnd = GetConsoleWindow();
    EnumData data{ currentProcessId, consoleHwnd, nullptr };
    EnumWindows(EnumWindowsCallback, reinterpret_cast<LPARAM>(&data));
    return data.bestHandle;
}

// Callback function for EnumWindows to find the target window
BOOL CALLBACK WindowFinder::EnumWindowsCallback(const HWND hwnd, const LPARAM lParam) noexcept
{
    const auto data = reinterpret_cast<EnumData*>(lParam);

    // Skip console window and other console-related windows
    if (hwnd == data->consoleHwnd || IsConsoleWindow(hwnd)) 
        return TRUE;

    DWORD windowProcessId = 0;
    GetWindowThreadProcessId(hwnd, &windowProcessId);

    // Skip windows from different processes
    if (windowProcessId != data->processId) 
        return TRUE;

    // Check if it's a main window
    if (!IsMainWindow(hwnd, data->consoleHwnd)) 
        return TRUE;

    // Found the best match - store handle and stop enumeration
    data->bestHandle = hwnd;
    return FALSE;
}

// Determines if a window qualifies as the main application window
bool WindowFinder::IsMainWindow(const HWND hwnd, const HWND consoleHwnd) noexcept
{
    // Exclude console window
    if (hwnd == consoleHwnd) 
        return false;

    // Must be visible
    if (!IsWindowVisible(hwnd)) 
        return false;

    // Must not have a parent (top-level window)
    if (GetParent(hwnd) != nullptr) 
        return false;

    // Check minimum window size
    RECT rect;
    GetWindowRect(hwnd, &rect);
    constexpr int MIN_WINDOW_SIZE = 100;

    if ((rect.right - rect.left) < MIN_WINDOW_SIZE || 
        (rect.bottom - rect.top) < MIN_WINDOW_SIZE) 
        return false;

    return true;
}

// Checks if the window is a console window by class name
bool WindowFinder::IsConsoleWindow(const HWND hwnd) noexcept
{
    wchar_t className[256];
    if (GetClassNameW(hwnd, className, 256) == 0) 
        return false;

    return wcscmp(className, L"ConsoleWindowClass") == 0;
}

