void tglDrawSO(const TMeshImage &image, double minColor[4], double maxColor[4],
               const PlasticDeformerDataGroup *group, bool deformedDomain)
{
  struct locals {
    static double returnSO(const LinearColorFunction *cf, int m, int f) {
      return cf->m_group->m_datas[m].m_so[f];
    }
  };
  double min = 0.0, max = 0.0;
  if (group) min = group->m_soMin, max = group->m_soMax;
  LinearFaceColorFunction colorFunction(image, group, min, max, minColor,
                                        maxColor, locals::returnSO);
  if (group && deformedDomain)
    tglDrawFaces(image, group, colorFunction);
  else
    tglDrawFaces(image, colorFunction);
}
//-------------------------------------------------------------------------------
void tglDrawRigidity(const TMeshImage &image, double minColor[4],
                     double maxColor[4], const PlasticDeformerDataGroup *group,
                     bool deformedDomain)
{
  struct locals {
    static double returnRigidity(const LinearColorFunction *cf, int m, int v) {
      return cf->m_meshImg.meshes()[m]->vertex(v).P().rigidity;
    }
  };
  LinearVertexColorFunction colorFunction(image, group, 1.0, 1e4, minColor,
                                          maxColor, locals::returnRigidity);
  if (group && deformedDomain)
    tglDrawFaces(image, group, colorFunction);
  else
    tglDrawFaces(image, colorFunction);
}

//***********************************************************************************************
//    Texturized drawing  implementation
//***********************************************************************************************

void tglDraw(const TMeshImage &meshImage, const DrawableTextureData &texData,
             const TAffine &meshToTexAff,
             const PlasticDeformerDataGroup &group)
{
  typedef MeshTexturizer::TextureData::TileData TileData;
  // Prepare OpenGL
  glPushAttrib(GL_COLOR_BUFFER_BIT | GL_LINE_BIT |
               GL_HINT_BIT);  // Preserve original status bits
  glEnable(GL_BLEND);
  glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
  glEnable(GL_LINE_SMOOTH);
  glLineWidth(1.0f);
  glHint(GL_LINE_SMOOTH_HINT, GL_NICEST);
  // Prepare variables
  const std::vector<TTextureMeshP> &meshes = meshImage.meshes();
  const TTextureMesh *mesh;
  typedef std::vector<std::pair<int, int>> SortedFacesVector;
  const SortedFacesVector &sortedFaces = group.m_sortedFaces;
  const MeshTexturizer::TextureData *td = texData.m_textureData;
  int t, tCount = td->m_tileDatas.size();
  GLuint texId = -1;
  int m        = -1;
  const double *dstCoords;
  int v0, v1, v2;
  int e1ovi, e2ovi;  // Edge X's Other Vertex Index (see below)
  // Prepare each tile's affine
  std::vector<TAffine> tileAff(tCount);
  for (t = 0; t != tCount; ++t) {
    const TileData &tileData = td->m_tileDatas[t];
    const TRectD &tileRect   = tileData.m_tileGeometry;
    tileAff[t] = TScale(1.0 / (tileRect.x1 - tileRect.x0),
                        1.0 / (tileRect.y1 - tileRect.y0)) *
                 TTranslation(-tileRect.x0, -tileRect.y0) * meshToTexAff;
  }
  // Draw each face individually, according to the group's sorted faces list.
  // Change tile and mesh data only if they change - improves performance
  SortedFacesVector::const_iterator sft, sfEnd(sortedFaces.end());
  for (sft = sortedFaces.begin(); sft != sfEnd; ++sft) {
    int f = sft->first, m_ = sft->second;
    if (m != m_) {
      // Change mesh if different from current
      m = m_;
      mesh      = meshes[m].getPointer();
      dstCoords = group.m_datas[m].m_output.get();
    }
    // Draw each face
    const TTextureMesh::face_type &fc = mesh->face(f);
    const TTextureMesh::edge_type &ed0 = mesh->edge(fc.edge(0)),
                                  &ed1 = mesh->edge(fc.edge(1)),
                                  &ed2 = mesh->edge(fc.edge(2));
    {
      v0 = ed0.vertex(0);
      v1 = ed0.vertex(1);
      v2 = ed1.vertex((ed1.vertex(0) == v0) | (ed1.vertex(0) == v1));
      e1ovi = (ed1.vertex(0) == v1) |
              (ed1.vertex(1) == v1);  // ed1 and ed2 will refer to vertexes
      e2ovi = 1 - e1ovi;              // with index 2 and these.
    }
    const TPointD &p0 = mesh->vertex(v0).P(), &p1 = mesh->vertex(v1).P(),
                  &p2 = mesh->vertex(v2).P();
    for (t = 0; t != tCount; ++t) {
      // Draw face against tile
      const TileData &tileData = td->m_tileDatas[t];
      // Map each face vertex to tile coordinates
      TPointD s[3] = {tileAff[t] * p0, tileAff[t] * p1, tileAff[t] * p2};
      // Test the face bbox - tile intersection
      if (std::min({s[0].x, s[1].x, s[2].x}) > 1.0 ||
          std::min({s[0].y, s[1].y, s[2].y}) > 1.0 ||
          std::max({s[0].x, s[1].x, s[2].x}) < 0.0 ||
          std::max({s[0].y, s[1].y, s[2].y}) < 0.0)
        continue;
      // If the tile has changed, interrupt the glBegin/glEnd block and bind the
      // OpenGL texture corresponding to the new tile
      if (tileData.m_textureId != texId) {
        texId = tileData.m_textureId;
        glBindTexture(
            GL_TEXTURE_2D,
            tileData
                .m_textureId);  // This must be OUTSIDE a glBegin/glEnd block
      }
      const double *d[3] = {dstCoords + (v0 << 1), dstCoords + (v1 << 1),
                            dstCoords + (v2 << 1)};
      /*
Now, draw primitives. A note about pixel arithmetic, here.
Since line antialiasing in OpenGL just manipulates output fragments' alpha
components,
we must require that the input texture is NONPREMULTIPLIED.
Furthermore, this function does not rely on the assumption that the output alpha
component
is discarded (as it happens when drawing on screen). This means that just using
a simple
glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA) is not an option, since this
way THE INPUT
SRC ALPHA GETS MULTIPLIED BY ITSELF - see glBlendFunc's docs - and that shows.
The solution is to separate the rendering of RGB and M components - the formers
use
GL_SRC_ALPHA, while the latter uses GL_ONE. The result is a PREMULTIPLIED image.
*/
      // First, draw antialiased face edges on the mesh border.
      bool drawEd0 = (ed0.facesCount() < 2), drawEd1 = (ed1.facesCount() < 2),
           drawEd2 = (ed2.facesCount() < 2);
      glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_FALSE);
      glBegin(GL_LINES);
      {
        if (drawEd0) {
          glTexCoord2d(s[0].x, s[0].y), glVertex2d(*d[0], *(d[0] + 1));
          glTexCoord2d(s[1].x, s[1].y), glVertex2d(*d[1], *(d[1] + 1));
        }
        if (drawEd1) {
          glTexCoord2d(s[e1ovi].x, s[e1ovi].y),
              glVertex2d(*d[e1ovi], *(d[e1ovi] + 1));
          glTexCoord2d(s[2].x, s[2].y), glVertex2d(*d[2], *(d[2] + 1));
        }
        if (drawEd2) {
          glTexCoord2d(s[e2ovi].x, s[e2ovi].y),
              glVertex2d(*d[e2ovi], *(d[e2ovi] + 1));
          glTexCoord2d(s[2].x, s[2].y), glVertex2d(*d[2], *(d[2] + 1));
        }
      }
      glEnd();
      glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
      glBegin(GL_LINES);
      {
        if (drawEd0) {
          glTexCoord2d(s[0].x, s[0].y), glVertex2d(*d[0], *(d[0] + 1));
          glTexCoord2d(s[1].x, s[1].y), glVertex2d(*d[1], *(d[1] + 1));
        }
        if (drawEd1) {
          glTexCoord2d(s[e1ovi].x, s[e1ovi].y),
              glVertex2d(*d[e1ovi], *(d[e1ovi] + 1));
          glTexCoord2d(s[2].x, s[2].y), glVertex2d(*d[2], *(d[2] + 1));
        }
        if (drawEd2) {
          glTexCoord2d(s[e2ovi].x, s[e2ovi].y),
              glVertex2d(*d[e2ovi], *(d[e2ovi] + 1));
          glTexCoord2d(s[2].x, s[2].y), glVertex2d(*d[2], *(d[2] + 1));
        }
      }
      glEnd();
      // Finally, draw the face
      glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_FALSE);
      glBegin(GL_TRIANGLES);
      {
        glTexCoord2d(s[0].x, s[0].y), glVertex2d(*d[0], *(d[0] + 1));
        glTexCoord2d(s[1].x, s[1].y), glVertex2d(*d[1], *(d[1] + 1));
        glTexCoord2d(s[2].x, s[2].y), glVertex2d(*d[2], *(d[2] + 1));
      }
      glEnd();
      glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
      glBegin(GL_TRIANGLES);
      {
        glTexCoord2d(s[0].x, s[0].y), glVertex2d(*d[0], *(d[0] + 1));
        glTexCoord2d(s[1].x, s[1].y), glVertex2d(*d[1], *(d[1] + 1));
        glTexCoord2d(s[2].x, s[2].y), glVertex2d(*d[2], *(d[2] + 1));
      }
      glEnd();
    }
  }
  glBindTexture(GL_TEXTURE_2D, 0);  // Unbind texture
  glPopAttrib();
}

#include "beekeeper/internalaliases.hpp"
#include "beekeeper/util.hpp"
#include <algorithm>

// Retrieves filesystem info from a map by UUID
const fs_info *
bk_util::retrieve_filesystem_info_from_a_list(const fs_map &haystack, const std::string &needle)
{
    auto it = haystack.find(needle);
    if (it == haystack.end())
        return nullptr;

    return &it->second; // immutable, no copy
}

/* NOTE FOR THE DEVS: you must ensure that the next three function's
* return vectors NEVER EVER contain the same UUID across their return
* values.
*
* For example:
*
* Good:
* - added: xxxxx
* - added: yyyyy
* - changed: zzzzz
* - removed: wwwww
*
* DANGEROUS, DON'T ALLOW THIS TO HAPPEN
* - added: xxxxx
* - added: yyyyy
* - changed: xxxxx <- also in "added"
* - changed: yyyyy <- also in "added" and "removed"
* - removed: zzzzz
* - removed: yyyyy
* 
* The same UUID contained within multiple function returns will
* cause table refresh issues in the GUI and break functionality.
* The above "Dangerous" must NEVER happen.
*/

/**
* @brief Return a new fs_vec containing only the new filesystem
* entities.
*
* @return A fs_vec containing filesystem entities from fresh_list
* that don't exist in the base filesystem list.
*
* @param snapshot Your latest filesystem list snapshot, prior refresh.
* @param fresh_list Your new filesystem list snapshot you want to
* compare your last one against; whatever is contained here that
* isn't present in the base fs_vec will be added to this function's
* return.
*/
fs_map
bk_util::list_of_newly_added_filesystems (const std::vector<std::string> &snapshot, const fs_map &fresh_list) 
{
    fs_map newly_added;
    newly_added.reserve(fresh_list.size());

    for (const auto &[uuid, info] : fresh_list) { // don't copy just yet
        if (std::find(snapshot.begin(), snapshot.end(), uuid) == snapshot.end()) {
            newly_added.emplace(uuid, info); // copy if not present
        }
        // if it does exist, do nothing
    }

    return newly_added;
}

/**
* @brief Return a new fs_vec containing the filesystem entities
* that have been removed from the last snapshot.
*
* @return A fs_vec containing filesystem entities from fresh_list
* that don't exist in the newer filesystem list but do exist in
* the base list. Note that this must NOT include newly added
* filesystems.
*
* @param base Your latest filesystem list snapshot, prior refresh.
* @param fresh_list Your new filesystem list snapshot you want to
* compare your last one against; whatever is contained in the base
* list that isn't present in the new fs_vec will be added to this
* function's return.
*/
std::vector<std::string>
bk_util::list_of_just_removed_filesystems (const std::vector<std::string> &snapshot, const fs_map &fresh_list) 
{
    std::vector<std::string> just_removed;
    just_removed.reserve(fresh_list.size());

    for (const std::string &uuid : snapshot) {
        if (fresh_list.find(uuid) == fresh_list.end()) {
            just_removed.emplace_back(uuid);
            // same as above: if it wasn't removed, do nothing
        }
    }

    return just_removed;
}

/**
* @brief Return a new fs_vec which contains all filesystem entities
* that still exist in both snapshot and new list and that have at
* least one of its data values changed.
*
* @return A fs_vec containing all filesystem entities that exist in
* both the snapshot and the new list and have at least one of its data
* values changed, comparing everything but the UUIDs since that's the
* reference key and so those comparisons would always be true.
*/
fs_map
bk_util::list_of_filesystems_that_still_exist_and_were_changed (const fs_map &snapshot, const fs_map &fresh_list)
{
    fs_map just_changed;
    just_changed.reserve(fresh_list.size());

    for (const auto &[uuid, info] : fresh_list) {
        const auto prolly_existed_and_changed = snapshot.find(uuid);

        // if it DOES exist in both new and snapshot
        if (prolly_existed_and_changed != snapshot.end()) {
            // if it changed in something, add it
            if (
                info.label != prolly_existed_and_changed->second.label
            ||  info.status != prolly_existed_and_changed->second.status
            ||  info.devname != prolly_existed_and_changed->second.devname
            ) {
                just_changed.emplace(uuid, info);
            }
        }
    }

    return just_changed;
}

fs_diff
bk_util::difference_between_two_fs_maps (
    const fs_map &snapshot,
    const fs_map &fresh_list
)
{
    fs_diff differences;

    std::vector<std::string> snapshot_uuids;
    for (const auto &[uuid, info] : snapshot) {
        snapshot_uuids.emplace_back(uuid);
    }

    differences.newly_added = list_of_newly_added_filesystems(snapshot_uuids, fresh_list);
    differences.just_removed = list_of_just_removed_filesystems(snapshot_uuids, fresh_list);
    differences.just_changed = list_of_filesystems_that_still_exist_and_were_changed(snapshot, fresh_list);

    return differences;
}

