      [&](const DoingNothing& activity) { doNothing(runApi.getTime(), activity); },
      [&](const DoingSomething& activity) { doSomething(runApi.getTime(), activity); },
      [&](const Sleeping& activity) { doSleep(runApi.getTime(), activity); }
