class XCOFFInfoPrinter : public ObjDumper {
public:
  XCOFFInfoPrinter(const XCOFFObjectFile &File, ScopedPrinter &Printer)
      : ObjDumper(Printer), File(File) {}
  void printFileHeaders() override;
  void printSectionHeaders() override;
  void printRelocations() override;
  void printSymbols() override;
  void printDynamicSymbols() override;
  void printUnwindInfo() override;
  void printStackMap() const override;
  void printNeededLibraries() override;

private:
  const XCOFFObjectFile &File;
};
} // anonymous namespace

void XCOFFInfoPrinter::printFileHeaders() {
  DictScope DS(P, "FileHeader");
  P.printHex("Magic", File.getMagic());
  P.printNumber("NumberOfSections", File.getNumberOfSections());

  int32_t TimeStamp = File.getTimeStamp();
  if (TimeStamp > 0) {
    time_t TimestampValue = TimeStamp;
    char FormattedTime[21] = {};
    size_t BytesWritten =
        strftime(FormattedTime, 21, "%Y-%m-%dT%H:%M:%SZ", gmtime(&TimestampValue));
    if (BytesWritten)
      P.printHex("TimeStamp", FormattedTime, TimeStamp);
    else
      P.printHex("Timestamp", TimeStamp);
  } else {
    P.printHex("TimeStamp", TimeStamp == 0 ? "None" : "Reserved Value",
               TimeStamp);
  }

  P.printHex("SymbolTableOffset", File.getSymbolTableOffset());
  int32_t SymbolCount = File.getRawNumberOfSymbolTableEntries();
  if (SymbolCount >= 0)
    P.printNumber("SymbolTableEntries", SymbolCount);
  else
    P.printHex("SymbolTableEntries", "Reserved Value", SymbolCount);

  P.printHex("OptionalHeaderSize", File.getOptionalHeaderSize());
  P.printHex("Flags", File.getFlags());

  // TODO FIXME Add support for the auxiliary header (if any) once
  // XCOFFObjectFile has the necessary support.
}

