namespace llvm {
std::error_code createXCOFFInfoPrinter(const object::ObjectFile *Obj,
                                       ScopedPrinter &Printer,
                                       std::unique_ptr<ObjDumper> &Result) {
  const XCOFFObjectFile *XObj = dyn_cast<XCOFFObjectFile>(Obj);
