}

Swapchain::Swapchain(XrSwapchain xr_chain)
    : m_xr_chain{xr_chain}
{
    ERHE_PROFILE_FUNCTION
    Expects(xr_chain != XR_NULL_HANDLE);
    enumerate_textures();
}

Swapchain::~Swapchain()
{
    ERHE_PROFILE_FUNCTION
    if (m_xr_chain != XR_NULL_HANDLE)
    {
        check_gl_context_in_current_in_this_thread();
        check(xrDestroySwapchain(m_xr_chain));
    }
}

Swapchain::Swapchain(Swapchain&& other) noexcept
    : m_xr_chain{other.m_xr_chain}
    , m_gl_texes{std::move(other.m_gl_texes)}
{
    other.m_xr_chain = XR_NULL_HANDLE;
}

void Swapchain::operator=(Swapchain&& other) noexcept
{
    Expects(other.m_xr_chain != XR_NULL_HANDLE);
    if (m_xr_chain != XR_NULL_HANDLE)
    {
        check_gl_context_in_current_in_this_thread();
        check(xrDestroySwapchain(m_xr_chain));
    }
    m_xr_chain = other.m_xr_chain;
    m_gl_texes = std::move(other.m_gl_texes);
    other.m_xr_chain = XR_NULL_HANDLE;
}

auto Swapchain::acquire() -> std::optional<Swapchain_image>
{
    ERHE_PROFILE_FUNCTION
    if (m_xr_chain == XR_NULL_HANDLE)
    {
        return {};
    }

    const XrSwapchainImageAcquireInfo acquire_info
    {
        .type = XR_TYPE_SWAPCHAIN_IMAGE_ACQUIRE_INFO,
        .next = nullptr
    };

    uint32_t index = 0;
    check_gl_context_in_current_in_this_thread();

    if (
        !check(
            xrAcquireSwapchainImage(
                m_xr_chain,
                &acquire_info,
                &index
            )
        )
    )
    {
        return {};
    }

    assert(index < 16);
    return Swapchain_image(this, index);
}

auto Swapchain::release() -> bool
{
    ERHE_PROFILE_FUNCTION
    if (m_xr_chain == XR_NULL_HANDLE)
    {
        return true;
    }

    const XrSwapchainImageReleaseInfo release_info
    {
        .type = XR_TYPE_SWAPCHAIN_IMAGE_RELEASE_INFO,
        .next = nullptr,
    };

    check_gl_context_in_current_in_this_thread();
    return check(
        xrReleaseSwapchainImage(m_xr_chain, &release_info)
    );
}

auto Swapchain::wait() -> bool
{
    ERHE_PROFILE_FUNCTION
    if (m_xr_chain == XR_NULL_HANDLE)
    {
        return false;
    }

    const XrSwapchainImageWaitInfo wait_info
    {
        .type    = XR_TYPE_SWAPCHAIN_IMAGE_WAIT_INFO,
        .next    = nullptr,
        .timeout = XR_INFINITE_DURATION
    };

    check_gl_context_in_current_in_this_thread();
    return check(
        xrWaitSwapchainImage(m_xr_chain, &wait_info)
    );
}

auto Swapchain::get_gl_texture(const uint32_t index) const -> unsigned int
{
    ERHE_VERIFY(index < m_gl_texes.size());
    return m_gl_texes[index];
}

auto Swapchain::get_xr_swapchain() const -> XrSwapchain
{
    return m_xr_chain;
}

auto Swapchain::enumerate_textures() -> bool
{
    ERHE_PROFILE_FUNCTION
    if (m_xr_chain == XR_NULL_HANDLE)
    {
        return false;
    }

    uint32_t count{0};
    check_gl_context_in_current_in_this_thread();
    ERHE_XR_CHECK(xrEnumerateSwapchainImages(m_xr_chain, 0, &count, nullptr));

    m_gl_texes.resize(count);

    std::vector<XrSwapchainImageOpenGLKHR> tex_array(count);
    for (uint32_t i = 0; i < count; ++i)
    {
        tex_array[i].type  = XR_TYPE_SWAPCHAIN_IMAGE_OPENGL_KHR;
        tex_array[i].next  = nullptr;
        tex_array[i].image = 0;
    }

    check_gl_context_in_current_in_this_thread();
    ERHE_XR_CHECK(
        xrEnumerateSwapchainImages(
            m_xr_chain,
            count,
            &count,
            reinterpret_cast<XrSwapchainImageBaseHeader*>(tex_array.data())
        )
    );

    for (uint32_t i = 0; i < count; ++i)
    {
        m_gl_texes[i] = tex_array[i].image;
    }

    return true;
}

