CD3DX12AffinityCommandList::CD3DX12AffinityCommandList(CD3DX12AffinityDevice* pDevice, ID3D12CommandList** ppCommandLists, UINT NumLists)
    : CD3DX12AffinityDeviceChild(pDevice, reinterpret_cast<ID3D12DeviceChild**>(ppCommandLists), NumLists)
{
    for (UINT idx = 0; idx < D3DX12_MAX_ACTIVE_NODES; ++idx)
    {
        if (idx < NumLists)
        {
            mCommandLists[idx] = ppCommandLists[idx];
        }
        else
        {
            mCommandLists[idx] = nullptr;
        }
    }
#ifdef DEBUG_OBJECT_NAME
    mObjectTypeName = L"CommandList";
#endif
}

D3D12_COMMAND_LIST_TYPE STDMETHODCALLTYPE CD3DX12AffinityCommandList::GetType(UINT NodeIndex)
{
    return mCommandLists[NodeIndex]->GetType();
}

BOOL STDMETHODCALLTYPE CD3DX12AffinityCommandList::AssertResourceState(
    CD3DX12AffinityResource* pRes,
    UINT Subres,
    UINT State)
{
    UINT i = GetActiveNodeIndex();
    ID3D12CommandList* pCmdList = mCommandLists[i];
    ID3D12DebugCommandList* pDebugCmdList = nullptr;
    HRESULT const hr = pCmdList->QueryInterface(IID_PPV_ARGS(&pDebugCmdList));
    if (S_OK != hr)
    {
        return false;
    }
    if (false == pDebugCmdList->AssertResourceState(pRes->mResources[i], Subres, State))
    {
        return false;
    }
    return true;
}

HRESULT STDMETHODCALLTYPE CD3DX12AffinityCommandList::SetFeatureMask(
    D3D12_DEBUG_FEATURE FeatureMask)
{
    for (UINT node = 0; node < D3DX12_MAX_ACTIVE_NODES; ++node)
    {
        if (((1 << node) & mAffinityMask) != 0)
        {
            ID3D12CommandList* pCmdList = mCommandLists[node];
            ID3D12DebugCommandList* pDebugCmdList = nullptr;
            HRESULT hr = pCmdList->QueryInterface(IID_PPV_ARGS(&pDebugCmdList));
            if (S_OK != hr)
            {
                return hr;
            }
            hr = pDebugCmdList->SetFeatureMask(FeatureMask);
            if (S_OK != hr)
            {
                return hr;
            }
        }
    }
    return S_OK;
}

ID3D12CommandList* CD3DX12AffinityCommandList::GetChildObject(UINT AffinityIndex)
{
    return mCommandLists[AffinityIndex];
}

bool CD3DX12AffinityCommandList::IsReady()
{
    return mPendingBroadcast == 0;
}

void CD3DX12AffinityCommandList::RegisterPendingBroadcast()
{
    std::lock_guard<std::mutex> lock(mMutexPendingBroadcast);
    ++mPendingBroadcast;
}

void CD3DX12AffinityCommandList::UnRegisterPendingBroadcast()
{
    std::lock_guard<std::mutex> lock(mMutexPendingBroadcast);
    --mPendingBroadcast;
}

