#include <vector>
#include <map>

class Solution {
public:
  int countElements(std::vector<int>& nums) {
    int result = 0;
    std::map<int, int> frequencyMap;

    for (int value : nums) {
      frequencyMap[value]++;
    }

    for (int value : nums) {
      if (frequencyMap[value + 1] > 0) {
        result++;
      }
    }

    return result;
  }
};

