#endif

// Compare internal implementation with standard libc snprintf
template<typename T>
static void TestAgainstLibc(const char *format, T arg1, T arg2) {
  char buffer[1024];
  uptr length = internal_snprintf(buffer, sizeof(buffer), format, arg1, arg2);
  char libBuffer[1024];
  snprintf(libBuffer, sizeof(libBuffer), format, arg1, arg2);
  EXPECT_EQ(length, strlen(buffer));
  EXPECT_STREQ(libBuffer, buffer);
}

// Test boundary values for different types
TEST(Printf, MinMax) {
  TestAgainstLibc<int>("%d-%d", INT_MIN, INT_MAX);  // NOLINT
  TestAgainstLibc<unsigned>("%u-%u", 0, UINT_MAX);  // NOLINT
  TestAgainstLibc<unsigned>("%x-%x", 0, UINT_MAX);  // NOLINT
#if !defined(_WIN32)
  // %z* format doesn't seem to be supported by MSVS.
  TestAgainstLibc<long>("%zd-%zd", LONG_MIN, LONG_MAX);  // NOLINT
  TestAgainstLibc<unsigned long>("%zu-%zu", 0, ULONG_MAX);  // NOLINT
  TestAgainstLibc<unsigned long>("%zx-%zx", 0, ULONG_MAX);  // NOLINT
#endif
}

// Test padding behavior with different width specifiers
TEST(Printf, Padding) {
  TestAgainstLibc<int>("%3d - %3d", 1, 0);
  TestAgainstLibc<int>("%3d - %3d", -1, 123);
  TestAgainstLibc<int>("%3d - %3d", -1, -123);
  TestAgainstLibc<int>("%3d - %3d", 12, 1234);
  TestAgainstLibc<int>("%3d - %3d", -12, -1234);
  TestAgainstLibc<int>("%03d - %03d", 1, 0);
  TestAgainstLibc<int>("%03d - %03d", -1, 123);
  TestAgainstLibc<int>("%03d - %03d", -1, -123);
  TestAgainstLibc<int>("%03d - %03d", 12, 1234);
  TestAgainstLibc<int>("%03d - %03d", -12, -1234);
}

// Test precision and width formatting
TEST(Printf, Precision) {
  char buffer[1024];
  uptr length = internal_snprintf(buffer, sizeof(buffer), "%.*s", 3, "12345");
  EXPECT_EQ(3U, length);
  EXPECT_STREQ("123", buffer);
  length = internal_snprintf(buffer, sizeof(buffer), "%.*s", 6, "12345");
  EXPECT_EQ(5U, length);
  EXPECT_STREQ("12345", buffer);
  length = internal_snprintf(buffer, sizeof(buffer), "%-6s", "12345");
  EXPECT_EQ(6U, length);
  EXPECT_STREQ("12345 ", buffer);
  // Check that width does not overflow the smaller buffer, although
  // 10 chars is requested, it stops at the buffer size, 8.
  length = internal_snprintf(buffer, 8, "%-10s", "12345");
  EXPECT_EQ(10U, length);  // The required size reported.
  EXPECT_STREQ("12345  ", buffer);
}

