  const size_t total_entries_;
  const size_t payload_size_;
  const size_t chunk_size_;
  const cloud_provider_firestore::CloudProviderFactory::UserId user_id_;
  files::ScopedTempDir writer_storage_;
  files::ScopedTempDir reader_storage_;
  fuchsia::sys::ComponentControllerPtr writer_controller_;
  fuchsia::sys::ComponentControllerPtr reader_controller_;
  LedgerPtr writer_ledger_;
  LedgerPtr reader_ledger_;
  PageId active_page_id_;
  PagePtr writer_page_;
  PagePtr reader_page_;
  std::vector<std::vector<uint8_t>> identifier_list_;
  fit::function<void(SyncState, SyncState)> on_sync_state_changed_;
  FXL_DISALLOW_COPY_ASSIGN_AND_MOVE(FetchPerformanceTest);
};

FetchPerformanceTest::FetchPerformanceTest(async::Loop* loop,
                                           std::unique_ptr<sys::ComponentContext> component_context,
                                           size_t entry_count, size_t payload_size, size_t chunk_size,
                                           SyncParams sync_params)
    : event_loop_(loop),
      entropy_source_(0),
      data_producer_(&entropy_source_),
      page_data_producer_(&entropy_source_),
      system_context_(std::move(component_context)),
      cloud_factory_(system_context_.get(), &entropy_source_, std::move(sync_params.api_key),
                     std::move(sync_params.credentials)),
      sync_watcher_binding_(this),
      total_entries_(entry_count),
      payload_size_(payload_size),
      chunk_size_(chunk_size),
      user_id_(cloud_provider_firestore::CloudProviderFactory::UserId::New()),
      writer_storage_(kDataDirectory),
      reader_storage_(kDataDirectory) {
  FXL_DCHECK(event_loop_);
  FXL_DCHECK(total_entries_ > 0);
  FXL_DCHECK(payload_size_ > 0);
  FXL_DCHECK(chunk_size_ <= payload_size_);
  cloud_factory_.Initialize();
}

void FetchPerformanceTest::OnSyncStateChange(SyncState download, SyncState upload,
                                             SyncStateChangedCallback callback) {
  if (on_sync_state_changed_) {
    on_sync_state_changed_(download, upload);
  }
  callback();
}

void FetchPerformanceTest::Execute() {
  // Name of the storage directory currently identifies the user. Ensure the
  // most nested directory has the same name to make the ledgers sync.
  std::string writer_directory = writer_storage_.path() + kUserNamespace;
  bool success = files::CreateDirectory(writer_directory);
  FXL_DCHECK(success);

  cloud_provider::CloudProviderPtr cloud_provider_writer;
  cloud_factory_.MakeCloudProvider(user_id_, cloud_provider_writer.NewRequest());

  Status status = GetLedger(system_context_.get(), writer_controller_.NewRequest(),
                            std::move(cloud_provider_writer), user_id_.user_id(), "fetch",
                            DetachedPath(std::move(writer_directory)), ExitLoopCallback(), &writer_ledger_,
                            kDefaultGarbageCollectionPolicy);
  if (ExitOnError(ExitLoopCallback(), status, "Get writer ledger")) {
    return;
  }

  GetPageEnsureInitialized(
      &writer_ledger_, nullptr, DelayCallback::YES, ExitLoopCallback(),
      [this](Status status, PagePtr page, PageId id) {
        if (ExitOnError(ExitLoopCallback(), status, "Writer page initialization")) {
          return;
        }
        writer_page_ = std::move(page);
        active_page_id_ = id;
        SeedData();
      });
}

void FetchPerformanceTest::SeedData() {
  auto identifiers = data_producer_.GenerateIdentifiers(total_entries_, kIdentifierLength, total_entries_);
  for (size_t i = 0; i < total_entries_; i++) {
    identifier_list_.push_back(identifiers[i]);
  }
  page_data_producer_.Populate(
      &writer_page_, std::move(identifiers), payload_size_, total_entries_,
      PageDataGenerator::ReferenceStrategy::REFERENCE, Priority::LAZY, [this](Status status) {
        if (ExitOnError(ExitLoopCallback(), status, "PageGenerator::Populate")) {
          return;
        }
        AwaitWriterUpload();
      });
}

void FetchPerformanceTest::AwaitWriterUpload() {
  on_sync_state_changed_ = [this](SyncState download, SyncState upload) {
    if (upload == SyncState::IDLE) {
      on_sync_state_changed_ = nullptr;
      // Stop watching sync state for this page.
      sync_watcher_binding_.Unbind();
      InitializeReader();
      return;
    }
  };
  writer_page_->SetSyncStateWatcher(sync_watcher_binding_.NewBinding());
}

void FetchPerformanceTest::InitializeReader() {
  std::string reader_directory = reader_storage_.path() + kUserNamespace;
  bool success = files::CreateDirectory(reader_directory);
  FXL_DCHECK(success);

  cloud_provider::CloudProviderPtr cloud_provider_reader;
  cloud_factory_.MakeCloudProvider(user_id_, cloud_provider_reader.NewRequest());

  Status status = GetLedger(system_context_.get(), reader_controller_.NewRequest(),
                            std::move(cloud_provider_reader), user_id_.user_id(), "fetch",
                            DetachedPath(std::move(reader_directory)), ExitLoopCallback(), &reader_ledger_,
                            kDefaultGarbageCollectionPolicy);
  if (ExitOnError(ExitLoopCallback(), status, "InitializeReader")) {
    return;
  }

  reader_ledger_->GetPage(fidl::MakeOptional(active_page_id_), reader_page_.NewRequest());
  AwaitReaderDownload();
}

void FetchPerformanceTest::AwaitReaderDownload() {
  on_sync_state_changed_ = [this](SyncState download, SyncState upload) {
    if (download == SyncState::IDLE) {
      on_sync_state_changed_ = nullptr;
      PageSnapshotPtr snapshot;
      reader_page_->GetSnapshot(snapshot.NewRequest(), {}, nullptr);
      RetrieveEntries(std::move(snapshot), 0);
      return;
    }
  };
  reader_page_->SetSyncStateWatcher(sync_watcher_binding_.NewBinding());
}

void FetchPerformanceTest::RetrieveEntries(PageSnapshotPtr snapshot, size_t index) {
  if (index >= total_entries_) {
    Terminate();
    return;
  }

  if (chunk_size_ > 0) {
    TRACE_ASYNC_BEGIN("benchmark", "Fetch (cumulative)", index);
    RetrieveChunk(std::move(snapshot), index, 0);
    return;
  }

  PageSnapshot* snapshot_ptr = snapshot.get();
  TRACE_ASYNC_BEGIN("benchmark", "Fetch", index);
  snapshot_ptr->Fetch(std::move(identifier_list_[index]),
                      [this, snapshot = std::move(snapshot),
                       index](fuchsia::ledger::PageSnapshot_Fetch_Result result) mutable {
                        if (ExitOnError(ExitLoopCallback(), result, "PageSnapshot::Fetch")) {
                          return;
                        }
                        TRACE_ASYNC_END("benchmark", "Fetch", index);
                        RetrieveEntries(std::move(snapshot), index + 1);
                      });
}

void FetchPerformanceTest::RetrieveChunk(PageSnapshotPtr snapshot, size_t index, size_t chunk) {
  if (chunk * chunk_size_ >= payload_size_) {
    TRACE_ASYNC_END("benchmark", "Fetch (cumulative)", index);
    RetrieveEntries(std::move(snapshot), index + 1);
    return;
  }

  PageSnapshot* snapshot_ptr = snapshot.get();
  auto trace_event_id = TRACE_NONCE();
  TRACE_ASYNC_BEGIN("benchmark", "FetchPartial", trace_event_id);
  snapshot_ptr->FetchPartial(
      identifier_list_[index], chunk * chunk_size_, chunk_size_,
      [this, snapshot = std::move(snapshot), index, chunk,
       trace_event_id](fuchsia::ledger::PageSnapshot_FetchPartial_Result result) mutable {
        if (ExitOnError(ExitLoopCallback(), result, "PageSnapshot::FetchPartial")) {
          return;
        }
        TRACE_ASYNC_END("benchmark", "FetchPartial", trace_event_id);
        RetrieveChunk(std::move(snapshot), index, chunk + 1);
      });
}

void FetchPerformanceTest::Terminate() {
  KillLedgerProcess(&writer_controller_);
  KillLedgerProcess(&reader_controller_);
  event_loop_->Quit();
}

fit::closure FetchPerformanceTest::ExitLoopCallback() {
  return [this] { event_loop_->Quit(); };
}

int PerformMain(int argc, const char** argv) {
  fxl::CommandLine command_line = fxl::CommandLineFromArgcArgv(argc, argv);
  async::Loop loop(&kAsyncLoopConfigAttachToCurrentThread);
  auto component_context = sys::ComponentContext::Create();

  std::string entry_count_str;
  size_t entry_count;
  std::string payload_size_str;
  size_t payload_size;
  std::string chunk_size_str;
  size_t chunk_size;
  SyncParams sync_configuration;

  if (!command_line.GetOptionValue(kEntryCountOption.ToString(), &entry_count_str) ||
      !fxl::StringToNumberWithError(entry_count_str, &entry_count) || entry_count == 0 ||
      !command_line.GetOptionValue(kPayloadSizeOption.ToString(), &payload_size_str) ||
      !fxl::StringToNumberWithError(payload_size_str, &payload_size) || payload_size == 0 ||
      !command_line.GetOptionValue(kChunkSizeOption.ToString(), &chunk_size_str) ||
      !fxl::StringToNumberWithError(chunk_size_str, &chunk_size) ||
      !ParseSyncParamsFromCommandLine(command_line, component_context.get(), &sync_configuration)) {
    ShowHelp();
    return -1;
  }

  FetchPerformanceTest app(&loop, std::move(component_context), entry_count, payload_size, chunk_size,
                           std::move(sync_configuration));
  return RunWithTracing(&loop, [&app] { app.Execute(); });
}

