#include "mariopaint.h"
#include "amigamod.h"
#include "modloader.h"

void showHelp();
void waitForInput();

int main(int argc, const char* argv[]) {

    printf("modshroom v0.55\n");
    printf("all n00bs\n\n");

    char file_in[1024];     // buffer for input path
    char file_out[1024];    // buffer for output path
    int speed = 150;        // default playback speed
    char creator[512];
    creator[0] = '\0';

    if (argc < 2 || argc > 5) {
        showHelp();
        waitForInput();
        return 0;
    }

    strcpy(file_in, argv[1]);

    // output filename provided?
    if (argc > 2) {
        strcpy(file_out, argv[2]);
    } else {
        char suffix[] = ".sho";
        strcpy(file_out, argv[1]);
        strcat(file_out, suffix);
    }

    if (argc > 3) {
        speed = atoi(argv[3]);
        printf("Speed: %d\n", speed);
    } else {
        printf("Using the default speed of %d\n", speed);
    }

    if (argc > 4) {
        strcpy(creator, argv[4]);
        creator[31] = '\0';
    }

    TrackerSong track;
    if (loadAmigamod(track, file_in) == 0) {
        printf("Creator: %s\n", creator);
        printf("Amigamod %s loaded successfully.\n", file_in);
        printf("\nConverting...\n");

        Mariosong convertedSHO;
        prepareMariosong(convertedSHO);
        int status = convertToMarioSongData(track, convertedSHO);

        if (status == 0) {
            strcpy(convertedSHO.songname, track.name);
            convertedSHO.tempo = (char)speed;
            memcpy(convertedSHO.author, creator, 32);
            saveSHO(convertedSHO, file_out);

            printf("SHO saved successfully to %s\n", file_out);
        } else {
            printf("Conversion error!\n");
        }
    } else {
        printf("Error: Couldn't load amigamod %s!\n", file_in);
    }

    waitForInput();
    return 0;
}

void showHelp() {
    printf("Usage: modshroom.exe input.mod [output.sho] [tempo] [author]\n");
}

void waitForInput() {
    printf("\nPress enter to quit.\n");
    char dummy = getchar();
}

