void Engine::sendCommand(s32 cmdVal) {
    MsgHeader header;
    switch (cmdVal) {
    case ECT_TERMINATE:
    {
        header.finish(ECT_TERMINATE, ++header.gSharedSN, ECT_VERSION);
        break;
    }
    case ECT_HEARTBEAT:
    {
        header.finish(ECT_HEARTBEAT, ++header.gSharedSN, ECT_VERSION);
        break;
    }
    default:
        Logger::log(ELL_INFO, "Engine::sendCommand>>unknown command = %d", cmdVal);
        return;
    }

    for (usz idx = 0; idx < mWorkers.size(); ++idx) {
        if (sizeof(header) != mWorkers[idx].mSocket.sendAll(&header, sizeof(header))) { // blocking send
            Logger::log(ELL_INFO, "Engine::sendCommand>>failed to send cmd = %d to child pid=%d", cmdVal, mWorkers[idx].mPid);
        }
    }

    if (ECT_TERMINATE == cmdVal) {
        for (usz idx = 0; idx < mWorkers.size(); ++idx) {
            if (mWorkers[idx].mHandle) {
                System::waitProcess(mWorkers[idx].mHandle);
                mWorkers[idx].mHandle = nullptr;
                Logger::log(ELL_INFO, "Engine::sendCommand>>worker[%d] terminated, pid=%d",
                    idx, mWorkers[idx].mPid);
            }
        }
        //if (mPrimaryProcess.mHandle) {
        mPrimaryProcess.mSocket.sendAll(&header, sizeof(header));
    }
}


bool Engine::startup(const s8* configPath, bool isChild) {
    mIsMain = !isChild;
    AppStrConverterInit();
#if defined(DOS_WINDOWS)
    s8 buffer[260];
    AppGbkToUTF8(configPath, buffer, sizeof(buffer));
    configPath = buffer;
#endif

    MsgHeader::gSharedSN = 0;
    mExecutablePath = configPath;
    mExecutablePath.deleteFilename();
    mExecutablePath.replace('\\', '/');
    mExecutableName = configPath + mExecutablePath.getLen();

    if (!mSettings.load(mExecutablePath, APP_CONFIG_PATH)) {
        mSettings.save(mExecutablePath + APP_CONFIG_PATH + ".generated.json");
        return false;
    }

    Timer::getTimeZone();
    System::getCoreCount();
    System::getPageSize();
    System::getDiskSectorSize();

    System::createPath(mSettings.mLogDirectory);

    Logger::getInstance();

    mProcessID = System::getPID();
    Logger::addFileReceiver();

    bool success = 0 == System::loadNetLib();
    if (!success) {
        Logger::log(ELL_ERROR, "Engine::startup>>network library load failed");
        return false;
    }

    mThreadLocalStorage.init();

    if (mSettings.mMaxWorkerCount > 0) {
        if (App4Char2S32("GMEM") == App4Char2S32(mSettings.mMemoryName.c_str())) {
            if (mIsMain) {
                if (!mMappedFile.createMem(mSettings.mMemorySize, mSettings.mMemoryName.c_str(), false, true)) {
                    Logger::log(ELL_INFO, "Engine::startup>>memory mapping creation failed: %s", mSettings.mMemoryName.c_str());
                    return false;
                }
            } else {
                if (!mMappedFile.openMem(mSettings.mMemoryName.c_str(), false)) {
                    Logger::log(ELL_INFO, "Engine::startup>>child process memory mapping open failed: %s", mSettings.mMemoryName.c_str());
                    return false;
                }
            }
        } else {
            if (mIsMain) {
                if (!mMappedFile.createMapfile(mSettings.mMemorySize, mSettings.mMemoryName.c_str(), false, false, true)) {
                    Logger::log(ELL_INFO, "Engine::startup>>file mapping creation failed: %s", mSettings.mMemoryName.c_str());
                    return false;
                }
            } else {
                if (!mMappedFile.openMem(mSettings.mMemoryName.c_str(), false)) {
                    Logger::log(ELL_INFO, "Engine::startup>>child process file mapping open failed: %s", mSettings.mMemoryName.c_str());
                    return false;
                }
            }
        }

        MemSlabPool& slabPool = getMemSlabPool();
        if (mIsMain) {
            new (&slabPool)MemSlabPool(mSettings.mMemorySize);
        } else {
            slabPool.initSlabSize();
        }
    }

    if (mIsMain) {
        FileWriter writer;
        if (writer.openFile(mSettings.mPidFilePath, false)) {
            writer.writeParams("%d", mProcessID);
            writer.close();
        } else {
            return false;
        }
        Logger::log(ELL_INFO, "Engine::startup>>pid = %d, role = %c", mProcessID, mIsMain ? 'M' : 'W');
        success = spawnWorkers();
    }

    if (mIsMain) {
        Logger::addPrintReceiver();
        success = runMasterProcess();
    } else {
#if defined(DOS_WINDOWS)
        net::Socket stdinSocket = (net::netsocket)GetStdHandle(STD_INPUT_HANDLE);
        Logger::log(ELL_INFO, "Engine::startup>>pid = %d, stdinSocket = %llu", mProcessID, stdinSocket.getValue());
        if (!stdinSocket.isOpen()) {
            Logger::log(ELL_INFO, "Engine::startup>>pid = %d, role = %c", mProcessID, mIsMain ? 'M' : 'W');
            return false;
        }

        Logger::log(ELL_INFO, "Engine::startup>>pid = %d, role = %c", mProcessID, mIsMain ? 'M' : 'W');
        success = runWorkerProcess(stdinSocket);
#endif
    }

    mProcessID = System::getPID();
    return success;
}


bool Engine::shutdown() {
    Logger::flush();
    mThreadPool.stop();
    cleanup();
    mThreadLocalStorage.uninit();
    return 0 == System::unloadNetLib();
}

