bool Engine::tick() {
    return mEventLoop.run();
}

bool Engine::runMasterProcess() {
    String socketPath = Engine::getInstance().getSettings().mLogDirectory;
    socketPath += System::getPID();
    socketPath += ".unpath";

    mPrimaryProcess.mHandle = nullptr;
    net::SocketPair socketPair;
    if (socketPair.open(socketPath.c_str())) {
        mPrimaryProcess.mPid = System::getPID();
        mPrimaryProcess.mStatus = 0;
        mPrimaryProcess.mSocket = socketPair.getSocketA();
    } else {
        Logger::log(ELL_ERROR, "Engine::runMasterProcess>> failed to create socket pair");
        return false;
    }
    mThreadPool.start(mSettings.mMaxThreadCount);
    bool ok = mEventLoop.start(socketPair.getSocketB());
    if (ok) { initializeTasks(); }
    return ok;
}

bool Engine::runWorkerProcess(net::Socket& controlSocket) {
    mThreadPool.start(mSettings.mMaxThreadCount);
    bool ok = mEventLoop.start(controlSocket);
    if (ok) {
        initializeTasks();
    }
    return ok;
}

bool Engine::spawnWorkers() {
    bool result = true;
    String socketPath = Engine::getInstance().getSettings().mLogDirectory;
    socketPath += System::getPID();
    socketPath += ".unpath";

    Process workerNode;
    mWorkers.reallocate(mSettings.mMaxWorkerCount);
    net::SocketPair socketPair;
    for (s16 i = 0; i < mSettings.mMaxWorkerCount; ++i) {
        if (socketPair.open(socketPath.c_str())) {
            workerNode.mSocket = socketPair.getSocketA();
            workerNode.mPid = System::createProcess(socketPair.getSocketB().getValue(), workerNode.mHandle);
            workerNode.mStatus = 1;
#if defined(DOS_LINUX)
            if (0 == workerNode.mPid) {//child
                socketPair.getSocketA().close();
                runWorkerProcess(socketPair.getSocketB());
                mIsMain=false;
                return true;
            } else {
                socketPair.getSocketB().close();
                if(workerNode.mPid<0){ //error
                    socketPair.close();
                    continue;
                }
            }
#endif
            mWorkers.pushBack(workerNode);
            Logger::log(ELL_INFO, "Engine::spawnWorkers>>worker pid = %d, controlSocket = %llu", workerNode.mPid, workerNode.mSocket.getValue());
        } else {
            Logger::log(ELL_ERROR, "Engine::startup>>start Worker[%d] failed", (s32)i);
            result = false;
            break;
        }
    }
    return result;
}


void Engine::initializeTasks() {
    for (usz i = 0; i < mSettings.mProxyList.size(); ++i) {
        net::Acceptor* listener = new net::Acceptor(mEventLoop, net::TcpProxy::funcOnLink, &mSettings.mProxyList[i]);
        listener->setTimeout(mSettings.mProxyList[i].mTimeout);
        listener->setBackend(mSettings.mProxyList[i].mRemoteAddress);
        if (0 == listener->open(mSettings.mProxyList[i].mLocalAddress)) {
            Logger::log(ELL_INFO, "Engine::init>>started TcpProxy=[%s->%s]",
                mSettings.mProxyList[i].mLocalAddress.getStr(), mSettings.mProxyList[i].mRemoteAddress.getStr());
        } else {
            Logger::log(ELL_ERROR, "Engine::init>>failed TcpProxy=[%s->%s]",
                mSettings.mProxyList[i].mLocalAddress.getStr(), mSettings.mProxyList[i].mRemoteAddress.getStr());
            delete listener;
        }
    }


    for (usz i = 0; i < mSettings.mWebServers.size(); ++i) {
        switch (mSettings.mWebServers[i].mProtocolType) {
        case 0: //http
        case 1: //https
        {
            net::Acceptor* listener = new net::Acceptor(mEventLoop, net::HttpLayer::funcOnLink, &mSettings.mWebServers[i]);
            listener->getHandleTCP().setTimeGap(mSettings.mWebServers[i].mTimeout);
            listener->getHandleTCP().setTimeout(mSettings.mWebServers[i].mTimeout);
            if (0 == listener->open(mSettings.mWebServers[i].mBindAddress)) {
                Logger::log(ELL_INFO, "Engine::init>>started website=%s,path=%s",
                    mSettings.mWebServers[i].mBindAddress.getStr(), mSettings.mWebServers[i].mDocumentRoot.c_str());
            } else {
                Logger::log(ELL_ERROR, "Engine::init>>failed website=%s,path=%s",
                    mSettings.mWebServers[i].mBindAddress.getStr(), mSettings.mWebServers[i].mDocumentRoot.c_str());
                delete listener;
            }
            break;
        }
        default:
            Logger::log(ELL_ERROR, "Engine::init>>invalid WebServer index=%lld, type=%d", i, mSettings.mWebServers[i].mProtocolType);
            break;
        }
    }
}

