#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    int maxProfit(int k, std::vector<int>& stockPrices) {
        // Step 1: Extract all possible transaction profits
        std::vector<int> gains;
        std::vector<std::pair<int, int>> vpStack; // valley-peak storage

        int valley;
        int peak = -1;

        for (;;) {
            // Locate next valley
            for (valley = peak + 1; (valley + 1 < stockPrices.size()) && (stockPrices[valley] >= stockPrices[valley + 1]); ++valley);

            // Locate next peak
            for (peak = valley; (peak + 1 < stockPrices.size()) && (stockPrices[peak] <= stockPrices[peak + 1]); ++peak);

            if (valley == peak) {
                break; // Both reached end of array
            }

            // Process existing transactions that are dominated by the new one
            while (!vpStack.empty() && (stockPrices[valley] <= stockPrices[vpStack.back().first])) {
                gains.push_back(stockPrices[vpStack.back().second] - stockPrices[vpStack.back().first]);
                vpStack.pop_back();
            }

            // Merge overlapping profitable segments when beneficial
            while (!vpStack.empty() && (stockPrices[peak] >= stockPrices[vpStack.back().second])) {
                gains.push_back(stockPrices[vpStack.back().second] - stockPrices[valley]);
                valley = vpStack.back().first;
                vpStack.pop_back();
            }

            // Record current valley-peak pair
            vpStack.emplace_back(valley, peak);
        }

        // Add remaining transaction profits
        while (!vpStack.empty()) {
            gains.push_back(stockPrices[vpStack.back().second] - stockPrices[vpStack.back().first]);
            vpStack.pop_back();
        }

        // Step 2: Sum top k profits
        int result;
        if (gains.size() <= static_cast<size_t>(k)) {
            result = std::accumulate(gains.begin(), gains.end(), 0);
        } else {
            std::nth_element(gains.begin(), gains.end() - k, gains.end());
            result = std::accumulate(gains.end() - k, gains.end(), 0);
        }

        return result;
    }
};

