// Helper: convert narrow C-string to wide BSTR-compatible wstring
static std::wstring ConvertAnsiToWide(const char* source) {
	if (!source)
		return {};
	std::wstring result;
	const auto required_chars = MultiByteToWideChar(CP_ACP, 0, source, -1, nullptr, 0);
	if (required_chars > 0) {
		result.resize(required_chars - 1);
		if (!MultiByteToWideChar(CP_ACP, 0, source, -1, &result[0], static_cast<int>(result.size()))) {
			if (ERROR_INSUFFICIENT_BUFFER == GetLastError())
				return result;
		}
	}
	return result;
}

// Helper: convert BSTR to narrow std::string (handles embedded NULs)
static std::string ConvertWideToAnsi(BSTR source) {
	if (!source)
		return {};
	const auto src_len = SysStringLen(source);
	std::string result;
	const auto needed_bytes = WideCharToMultiByte(CP_ACP, 0, source, src_len + 1, nullptr, 0, 0, 0);
	if (needed_bytes > 0) {
		result.resize(needed_bytes, '\0');
		if (!WideCharToMultiByte(CP_ACP, 0, source, src_len + 1, &result[0], needed_bytes, 0, 0))
			result.clear();
	}
	return result;
}

// Retrieve OS name via WMI query on Win32_OperatingSystem.Name
static std::string get_windows_os_name() {
	if (FAILED(CoInitializeEx(nullptr, COINIT_APARTMENTTHREADED)))
		return {};

	iware::detail::quickscope_wrapper com_cleanup{CoUninitialize};

	if (FAILED(CoInitializeSecurity(nullptr, -1, nullptr, nullptr,
	                                RPC_C_AUTHN_LEVEL_DEFAULT, RPC_C_IMP_LEVEL_IMPERSONATE,
	                                nullptr, EOAC_NONE, nullptr)))
		return {};

	IWbemLocator* locator_raw = nullptr;
	if (FAILED(CoCreateInstance(CLSID_WbemLocator, nullptr, CLSCTX_INPROC_SERVER,
	                            IID_IWbemLocator, reinterpret_cast<void**>(&locator_raw))))
		return {};

	std::unique_ptr<IWbemLocator, iware::detail::release_deleter> locator(locator_raw);

	IWbemServices* services_raw = nullptr;
	if (FAILED(locator->ConnectServer(&ConvertAnsiToWide("ROOT\\CIMV2")[0],
	                                  nullptr, nullptr, 0, 0, 0, 0, &services_raw)))
		return {};

	std::unique_ptr<IWbemServices, iware::detail::release_deleter> services(services_raw);

	if (FAILED(CoSetProxyBlanket(services.get(), RPC_C_AUTHN_WINNT, RPC_C_AUTHZ_NONE,
	                             nullptr, RPC_C_AUTHN_LEVEL_CALL, RPC_C_IMP_LEVEL_IMPERSONATE,
	                             nullptr, EOAC_NONE)))
		return {};

	IEnumWbemClassObject* enum_raw = nullptr;
	if (FAILED(services->ExecQuery(&ConvertAnsiToWide("WQL")[0],
	                               &ConvertAnsiToWide("SELECT Name FROM Win32_OperatingSystem")[0],
	                               WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
	                               nullptr, &enum_raw)))
		return {};

	std::unique_ptr<IEnumWbemClassObject, iware::detail::release_deleter> enumerator(enum_raw);

	std::string os_name;
	while (enumerator) {
		IWbemClassObject* obj_raw = nullptr;
		ULONG fetched = 0;
		enumerator->Next(WBEM_INFINITE, 1, &obj_raw, &fetched);
		if (fetched != 1)
			break;

		std::unique_ptr<IWbemClassObject, iware::detail::release_deleter> object(obj_raw);

		VARIANT variant{};
		object->Get(L"Name", 0, &variant, 0, 0);
		iware::detail::quickscope_wrapper variant_guard{[&] { VariantClear(&variant); }};

		os_name = ConvertWideToAnsi(variant.bstrVal);
	}

	return os_name.substr(0, os_name.find('|'));
}

iware::system::OS_info_t iware::system::OS_info() {
	const auto kernel_data = iware::system::kernel_info();
	return {"Windows NT", get_windows_os_name(),
	        kernel_data.major, kernel_data.minor, kernel_data.patch, kernel_data.build_number};
}
