#include <vector>
#include <algorithm>

class Solution {
public:
    // Helper function to build tree from preorder and postorder traversals
    TreeNode* buildTreeRecursive(const std::vector<int>& preorder, int preIndex,
                                 const std::vector<int>& postorder, int left, int right) {
        if (left > right) return nullptr;

        TreeNode* node = new TreeNode(postorder[right]);

        // Find position of next preorder element in postorder array
        int splitPos = std::find(postorder.begin() + left, postorder.begin() + right, 
                                preorder[preIndex + 1]) - postorder.begin();
        splitPos = (splitPos < right) ? splitPos : (left - 1);

        // Recursively construct left and right subtrees
        node->left = buildTreeRecursive(preorder, preIndex + 1, postorder, left, splitPos);
        node->right = buildTreeRecursive(preorder, preIndex + splitPos - left + 2, 
                                        postorder, splitPos + 1, right - 1);
        return node;
    }

    TreeNode* constructFromPrePost(std::vector<int>& preorder, std::vector<int>& postorder) {
        int size = postorder.size();
        return buildTreeRecursive(preorder, 0, postorder, 0, size - 1);
    }
};

