// Adjust child mutation states to remain consistent with updated parent state,
// and record any required changes in the list of modified nodes.
void clean_up_child_mutations(MAT::Node *child_node,
                              std::vector<Altered_Node_t> &modified_nodes) {
    MAT::Mutations_Collection &mut_collection = child_node->mutations;
    State_Change_Collection state_updates;

    for (auto &mutation : mut_collection) {
        nuc_one_hot expected_state =
            mutation.get_par_one_hot() & mutation.get_all_major_allele();
        nuc_one_hot current_state = mutation.get_mut_one_hot();

        // Update mutation state if it now aligns with parent and previously inconsistent
        if (expected_state && current_state != expected_state) {
            child_node->changed = true;
            mutation.set_mut_one_hot(expected_state);
            state_updates.emplace_back(mutation, current_state);
        }
    }

    // Remove mutations that are redundant: major allele matches parent, no sensitive alleles remain
    mut_collection.mutations.erase(
        std::remove_if(mut_collection.mutations.begin(), mut_collection.mutations.end(),
                       [](const MAT::Mutation &mut) {
                           return (
                               mut.get_par_one_hot() == mut.get_all_major_allele() &&
                               !mut.get_boundary1_one_hot());
                       }),
        mut_collection.mutations.end());

    if (!state_updates.empty()) {
        modified_nodes.emplace_back(child_node);
        modified_nodes.back().changed_states = std::move(state_updates);
    }
}

#ifdef CHECK_STATE_REASSIGN
void validate_mutation_consistency(MAT::Node *original, MAT::Node *updated) {
    for (size_t idx = 0; idx < original->mutations.size(); ++idx) {
        if (!(original->mutations[idx] == updated->mutations[idx])) {
            fprintf(stderr, "Mismatch at index %zu\n", idx);
            assert(false);
        }
        assert(original->mutations[idx] == updated->mutations[idx]);

        if (original->children.size() == 2) {
            assert(original->mutations[idx].get_left_child_state() ==
                   updated->mutations[idx].get_left_child_state());
            assert(original->mutations[idx].get_right_child_state() ==
                   updated->mutations[idx].get_right_child_state());
        }
    }
}
#endif

