// Helper function during debugging: locate an altered node by identifier
const Altered_Node_t* locate_altered_node(const char* id_label, const std::vector<Altered_Node_t>& candidates) {
    for (const auto& entry : candidates) {
        if (entry.altered_node->identifier == id_label) {
            return &entry;
