}

#ifdef CHECK_STATE_REASSIGN
void compare_full_trees(MAT::Tree &original_tree, MAT::Tree &revised_tree) {
    std::vector<MAT::Node *> original_nodes = original_tree.breadth_first_expansion();
    std::vector<MAT::Node *> revised_nodes = revised_tree.breadth_first_expansion();

    for (int i = original_nodes.size() - 1; i >= 0; --i) {
        validate_mutation_consistency(original_nodes[i], revised_nodes[i]);
    }
    revised_tree.delete_nodes();
}
#endif

/**
 * @brief Execute all non-conflicting rearrangement moves
 * @param move_list collection of valid moves to apply
 * @param tree reference to the tree being modified
 * @param bfs_order list of nodes in breadth-first order
 * @param next_candidates concurrent vector of candidate nodes for next iteration
 */
void execute_moves(std::vector<Profitable_Moves_ptr_t> &move_list, MAT::Tree &tree,
                   std::vector<MAT::Node *> &bfs_order,
                   tbb::concurrent_vector<MAT::Node *> &next_candidates
#ifdef CHECK_STATE_REASSIGN
                   ,
                   const Original_State_t &initial_state
#endif
) {
    std::vector<MAT::Node *> branch_modified_nodes;     // nodes affected by structural change
    std::vector<Altered_Node_t> forward_pass_modifications; // nodes needing state propagation
    std::unordered_set<size_t> removed_node_addresses;   // delayed deletion set
    std::vector<MAT::Node *> nodes_requiring_cleanup;    // nodes whose parent may have changed due to condensation

#ifdef CHECK_STATE_REASSIGN
#ifndef SINGLE_THREAD_TEST
    FILE* debug_log = fopen("moves", "w");
#endif
#endif

    for (const auto &action : move_list) {
        // Skip moves involving already-deleted endpoints or self-referencing edges
        if (removed_node_addresses.count((size_t)action->src) ||
            removed_node_addresses.count((size_t)action->get_dst()) ||
            action->src->parent == action->get_dst()) {
            continue;
        }

#ifdef CHECK_STATE_REASSIGN
#ifdef SINGLE_THREAD_TEST
        fprintf(stderr, "%s\tto\t%s\n", action->src->identifier.c_str(), action->get_dst()->identifier.c_str());
#else
        fprintf(debug_log, "%s\tto\t%s\n", action->src->identifier.c_str(), action->get_dst()->identifier.c_str());
        fflush(debug_log);
#endif
#endif

        // Perform preliminary move preserving global state consistency
        move_node(action->src, action->get_dst(), branch_modified_nodes, tree,
                  removed_node_addresses, nodes_requiring_cleanup);
        delete action;
    }

    // Rebuild DFS traversal since Fitch/Sankoff requires bottom-up processing
    std::vector<MAT::Node*> postorder = tree.depth_first_expansion();

    // Remove deleted nodes from structural update list
    auto end_it = std::remove_if(branch_modified_nodes.begin(), branch_modified_nodes.end(),
                                 [&removed_node_addresses](MAT::Node *n) {
                                     return removed_node_addresses.count((size_t)n);
                                 });
    branch_modified_nodes.erase(end_it, branch_modified_nodes.end());

    // Also filter out deleted nodes from cleanup list
    nodes_requiring_cleanup.erase(
        std::remove_if(nodes_requiring_cleanup.begin(), nodes_requiring_cleanup.end(),
                       [&removed_node_addresses](MAT::Node *n) {
                           return removed_node_addresses.count((size_t)n);
                       }),
        nodes_requiring_cleanup.end());

#ifdef CHECK_STATE_REASSIGN
    MAT::Tree reconstructed_tree = reassign_state_full(tree);
    reconstructed_tree.save_detailed_mutations("After_reassign.pb");
#endif

    // Backward pass: propagate major allele updates
    if (!branch_modified_nodes.empty()) {
        reassign_backward_pass(branch_modified_nodes, forward_pass_modifications
#ifdef CHECK_STATE_REASSIGN
                               ,
                               reconstructed_tree
#endif
        );
    }

    // Clean up nodes whose parent state may have changed
    for (const auto node : nodes_requiring_cleanup) {
        clean_up_child_mutations(node, forward_pass_modifications);
    }

    // Forward pass: enforce child state consistency with new parent states
    if (!forward_pass_modifications.empty()) {
        forward_pass(forward_pass_modifications
#ifdef CHECK_STATE_REASSIGN
                     ,
                     reconstructed_tree
#endif
        );
    }

#ifdef CHECK_STATE_REASSIGN
    compare_full_trees(tree, reconstructed_tree);
#endif

    // Filter out deleted nodes from candidate list for next round
    tbb::concurrent_vector<MAT::Node*> remaining_candidates;
    remaining_candidates.reserve(next_candidates.size());
    for (const auto node : next_candidates) {
        if (!removed_node_addresses.count((size_t)node)) {
            remaining_candidates.push_back(node);
        }
    }
    next_candidates.swap(remaining_candidates);

    // Finalize deletion of removed nodes
    for (auto addr : removed_node_addresses) {
        MAT::Node* node_ptr = reinterpret_cast<MAT::Node*>(addr);
        tree.all_nodes.erase(node_ptr->identifier);
        delete node_ptr;
    }

#ifdef CHECK_STATE_REASSIGN
#ifndef SINGLE_THREAD_TEST
    fclose(debug_log);
#endif
#endif
}

