        "IsVisible",
        "Visibility",
        "If this value is 'false', this dashboard will be hidden, regardless of the "
        "state of the individual components"
    };

    constexpr openspace::properties::Property::PropertyInfo OffsetStartInfo = {
        "OffsetStart",
        "Offset Start",
        "A 2D vector controlling where the dashboard rendering begins."
        "Adding an offset in x and y-direction on screen"
    };
} // namespace

namespace openspace {

Dashboard::Dashboard()
    : properties::PropertyOwner({ "Dashboard" })
    , _isVisible(VisibilityInfo, true)
    , _offsetStart(
        properties::IVec2Property(OffsetStartInfo, glm::ivec2(15, -15))
    )
{
    addProperty(_isVisible);
    addProperty(_offsetStart);
}

void Dashboard::addDashboardItem(std::unique_ptr<DashboardItem> item) {
    const std::string& baseIdentifier = item->identifier();
    int counter = 1;

    while (true) {
        auto iterator = std::find_if(
            _components.begin(),
            _components.end(),
            [&item](const std::unique_ptr<DashboardItem>& i) {
                return (i->identifier() == item->identifier());
            }
        );

        if (iterator == _components.end()) {
            // Unique name found
            break;
        }
        else {
            item->setIdentifier(baseIdentifier + std::to_string(counter));
            item->setGuiName(baseIdentifier + " " + std::to_string(counter));
            ++counter;
        }
    }

    addPropertySubOwner(item.get());
    _components.push_back(std::move(item));
}

void Dashboard::removeDashboardItem(int index) {
    ghoul_assert(index < static_cast<int>(_components.size()), "Invalid index");
    removePropertySubOwner(_components[index].get());
    _components.erase(_components.begin() + index);
}

void Dashboard::removeDashboardItem(const std::string& identifier) {
    const auto it = std::find_if(
        _components.begin(),
        _components.end(),
        [&identifier](const std::unique_ptr<DashboardItem>& i) {
            return i->identifier() == identifier;
        }
    );

    if (it == _components.end()) {
        return;
    }

    removePropertySubOwner(it->get());
    _components.erase(it);
}

bool Dashboard::hasComponent(int index) const {
    return (index >= 0) && (index < static_cast<int>(_components.size()));
}

const DashboardItem& Dashboard::component(int index) const {
    ghoul_assert(index < static_cast<int>(_components.size()), "Invalid index");
    return *_components[index];
}

void Dashboard::clearAllComponents() {
    for (const std::unique_ptr<DashboardItem>& item : _components) {
        removePropertySubOwner(item.get());
    }
    _components.clear();
}

void Dashboard::render(glm::vec2& penPosition) {
    if (!_isVisible) {
        return;
    }

    for (const std::unique_ptr<DashboardItem>& item : _components) {
        if (item->isEnabled()) {
            item->render(penPosition);
        }
    }
}

glm::vec2 Dashboard::getOffsetStart() {
    return _offsetStart.value();
};

