using json = nlohmann::json;
using QuatDatum = glm::quat;

// Construct a quaternion from JSON array
QuatDatum quat_from_json(const json& source) {
    QuatDatum q(1.0f, 0.0f, 0.0f, 0.0f);
    if (source.is_array() && source.size() == 4) {
        q.w = source[0];
        q.x = source[1];
        q.y = source[2];
        q.z = source[3];
    }
    return q;
}

// Convert quaternion to JSON array
json quat_to_json(const QuatDatum& q) {
    json arr = json::array();
    arr.push_back(q.w);
    arr.push_back(q.x);
    arr.push_back(q.y);
    arr.push_back(q.z);
    return arr;
}

// Generate a random unit quaternion with fixed angle
QuatDatum generate_random_quat() {
    constexpr float ROTATION_ANGLE = 1.57f; // ~PI/2 radians
    glm::vec3 axis = RandomUtil::unitSphereSurface();
    return glm::angleAxis(ROTATION_ANGLE, axis);
}

// Check approximate equality of two quaternions (accounting for double-cover)
bool quats_approx_equal(const QuatDatum& first, const QuatDatum& second) {
    constexpr float DOT_TOLERANCE = 8.0e-7; // ~0.1 degree discrepancy
    float dot_val = std::abs(glm::dot(first, second));
    return std::abs(1.0f - dot_val) < DOT_TOLERANCE;
}

class SampleConfig : public ConfigUtil::ConfigInterface {
public:
    SampleConfig() { }
    ~SampleConfig() { }

    // Required override: serialize config to JSON
    nlohmann::json getJson() const override {
        std::unique_lock<decltype(_mutex)> guard(_mutex);
        json result;
        result["label"] = _label;
        result["value"] = _value;
        json items = json::array();
        for (size_t idx = 0; idx < _items.size(); ++idx) {
            items.push_back(quat_to_json(_items[idx]));
        }
        result["items"] = items;
        return result;
    }

    // Required override: deserialize config from JSON
    void updateJson(const nlohmann::json& source) override {
        std::unique_lock<decltype(_mutex)> guard(_mutex);
        bool modified = false;
        if (source.contains("label") && source["label"].is_string()) {
            _label = source["label"];
            modified = true;
        }
        if (source.contains("value") && source["value"].is_number_integer()) {
            _value = source["value"];
            modified = true;
        }
        if (source.contains("items") && source["items"].is_array()) {
            _items.clear();
            json arr = source["items"];
            _items.reserve(arr.size());
            for (json::iterator it = arr.begin(); it != arr.end(); ++it) {
                _items.push_back(quat_from_json(*it));
            }
            modified = true;
        }
        if (modified) {
            bumpVersion();
        }
    }

    void setLabel(const std::string& label) {
        std::unique_lock<decltype(_mutex)> guard(_mutex);
        if (label != _label) {
            _label = label;
            bumpVersion();
        }
    }

    void setValue(int32_t val) {
        std::unique_lock<decltype(_mutex)> guard(_mutex);
        if (val != _value) {
            _value = val;
            bumpVersion();
        }
    }

    void setItems(const std::vector<QuatDatum>& items) {
        std::unique_lock<decltype(_mutex)> guard(_mutex);
        bool changed = false;
        size_t count = items.size();
        if (count != _items.size()) {
            changed = true;
            _items.clear();
        }
        _items.reserve(count);
        size_t index = 0;
        while (index < count) {
            if (index < _items.size()) {
                if (_items[index] != items[index]) {
                    _items[index] = items[index];
                    changed = true;
                }
            } else {
                _items.push_back(items[index]);
            }
            ++index;
        }
        if (changed) {
            bumpVersion();
        }
    }

    bool operator==(const SampleConfig& rhs) {
        std::unique_lock<decltype(_mutex)> guard(_mutex);
        if (_label != rhs._label
            || _value != rhs._value
            || _items.size() != rhs._items.size())
        {
            return false;
        }
        for (size_t i = 0; i < _items.size(); ++i) {
            if (!quats_approx_equal(_items[i], rhs._items[i])) {
                return false;
            }
        }
        return true;
    }

private:
    std::string _label;
    int32_t _value { 0 };
    std::vector<QuatDatum> _items;
};

TEST(ConfigUtil_test, serialization_roundtrip) {
    // Prepare test data
    size_t item_count = 16;
    std::vector<QuatDatum> samples;
    samples.reserve(item_count);
    for (size_t k = 0; k < item_count; ++k) {
        samples.push_back(generate_random_quat());
    }

    // Initialize first config
    SampleConfig cfg1;
    cfg1.setLabel("alpha");
    cfg1.setValue(42);
    cfg1.setItems(samples);

    // Initialize second config as empty
    SampleConfig cfg2;
    EXPECT_FALSE(cfg1 == cfg2);
    EXPECT_FALSE(cfg2 == cfg1);

    // Copy via JSON object
    json json_obj = cfg1.getJson();
    cfg2.updateJson(json_obj);
    EXPECT_TRUE(cfg1 == cfg2);
    EXPECT_TRUE(cfg2 == cfg1);

    // Modify first config
    cfg1.setLabel("beta");
    EXPECT_FALSE(cfg1 == cfg2);

    // Copy via file
    std::string filepath = fmt::format("/tmp/test_ConfigUtil-{:0<8x}.json", RandomUtil::uint32());
    cfg1.setFilename(filepath);
    bool wrote_ok = cfg1.writeFile();
    EXPECT_TRUE(wrote_ok);

    SampleConfig cfg3;
    cfg3.setFilename(filepath);
    bool read_ok = cfg3.readFileIfChanged();
    EXPECT_TRUE(read_ok);
    EXPECT_TRUE(cfg1 == cfg3);

    bool removed = std::filesystem::remove(filepath);
    EXPECT_TRUE(removed);
}

