class Solution {
public:
    static void shiftZeros(std::vector<int>& values) noexcept;
};

void Solution::shiftZeros(std::vector<int>& values) noexcept
{
    std::stable_partition(values.begin(), values.end(),
                          [](const auto element) noexcept { return element != 0; });
}

