#include "RandomWordIterator.h"

void RandomWordIterator::initializeGenerator()
{
    if (cachedSize != dictionary.Size()) // size has been modified
    {
        distribution = std::unique_ptr<std::uniform_int_distribution<size_t>>(new std::uniform_int_distribution<size_t>(0, dictionary.Size() - 1));
        cachedSize = dictionary.Size();
    }
}

std::string RandomWordIterator::getNext()
{
    if (!hasRemaining())
    {
        return "";
    }
    initializeGenerator();
    std::string selectedWord;
    do
    {
        selectedWord = dictionary[(*distribution)(randomEngine)];
    }
    while (!filter(selectedWord));
    return selectedWord;
}

bool RandomWordIterator::hasRemaining()
{
    bool exists = false;
    for (size_t index = 0; index < dictionary.Size(); ++index)
    {
        if (filter(dictionary[index]))
        {
            exists = true;
            break;
        }
    }
    return exists;
}

