class Solution {
public:
    Solution(vector<int>& inputArray) : original(inputArray), current(inputArray), size(inputArray.size()) {}

    /** Restores the array to its initial state and returns it. */
    vector<int> reset() {
        return original;
    }

    /** Produces a randomly shuffled version of the array. */
    vector<int> shuffle() {
        for (int index = size - 1; index >= 1; --index) {
            uniform_int_distribution<int> dist(0, index);
            int randomIndex = dist(rng);
            swap(current[randomIndex], current[index]);
        }
        return current;
    }
private:
    vector<int> original;
    vector<int> current;
    int size;
    default_random_engine rng;
};
