    // Generate queries with constraint u < v
    for (int q_idx = 0; q_idx < query_count; q_idx++) {
        int first_node, second_node;
        do {
            first_node = generator.uniform(0, node_count - 1);
            second_node = generator.uniform(0, node_count - 1);
