STATISTIC(NumObjectsPromoted, "Number of heap allocations moved to stack storage");
using namespace swift;

namespace {
/// Transforms heap-allocated objects into stack-allocated ones.
///
/// This pass processes alloc_ref instructions for native Swift classes: when
/// successful, it marks the allocation with the [stack] attribute and inserts
/// a corresponding dealloc_ref [stack] at the end of the object's lifetime.
class StackPromotion : public SILFunctionTransform {
public:
  StackPromotion() = default;

private:
  void run() override;
  bool processBlock(SILBasicBlock *BB, EscapeAnalysis *EA, DeadEndBlocks &DEBlocks);
  bool attemptPromotion(AllocRefInst *ARI, EscapeAnalysis *EA, DeadEndBlocks &DEBlocks);
};

void StackPromotion::run() {
  SILFunction *func = getFunction();
  DEBUG(llvm::dbgs() << "** StackPromotion processing " << func->getName() << " **\n");

  auto *escapeAnalysis = PM->getAnalysis<EscapeAnalysis>();
  DeadEndBlocks deadEndBlocks(func);
  bool modified = false;

  for (SILBasicBlock &block : *func) {
    modified |= processBlock(&block, escapeAnalysis, deadEndBlocks);
  }

  if (!modified)
    return;

  StackNesting sn;
  if (sn.correctStackNesting(func) == StackNesting::Changes::CFG) {
    invalidateAnalysis(SILAnalysis::InvalidationKind::BranchesAndInstructions);
  } else {
    invalidateAnalysis(SILAnalysis::InvalidationKind::Instructions);
  }
}

bool StackPromotion::processBlock(SILBasicBlock *BB, EscapeAnalysis *EA,
                                  DeadEndBlocks &DEBlocks) {
  bool changed = false;

  for (auto iter = BB->begin(); iter != BB->end(); ) {
    SILInstruction *inst = &*iter++;

    if (auto *allocRef = dyn_cast<AllocRefInst>(inst)) {
      // Skip promotion in unreachable regions to avoid premature deallocation
      if (DEBlocks.isDeadEnd(BB))
        continue;

      changed |= attemptPromotion(allocRef, EA, DEBlocks);
    }
  }

  return changed;
}

bool StackPromotion::attemptPromotion(AllocRefInst *ARI, EscapeAnalysis *EA,
                                      DeadEndBlocks &DEBlocks) {
  // Skip Objective-C or already stack-allocatable allocations
  if (ARI->isObjC() || ARI->canAllocOnStack())
    return false;

  auto *connGraph = EA->getConnectionGraph(ARI->getFunction());
  auto *node = connGraph->getNodeOrNull(ARI, EA);
  if (!node)
    return false;

  // Core requirement: object must not escape the function
  if (node->escapes())
    return false;

  DEBUG(llvm::dbgs() << "Promoting " << *ARI);

  // Gather all use points: refcount operations and apply instructions
  llvm::SmallVector<ValueBase *, 8> baseUses;
  llvm::SmallVector<SILInstruction *, 8> uses;
  connGraph->getUsePoints(node, baseUses);

  for (ValueBase *use : baseUses) {
    if (auto *inst = dyn_cast<SILInstruction>(use)) {
      uses.push_back(inst);
    } else {
      // Handle phi arguments by inserting at block entry
      SILBasicBlock *useBlock = cast<SILPHIArgument>(use)->getParent();
      uses.push_back(&useBlock->front());
    }
  }

  ValueLifetimeAnalysis vla(ARI, uses);

  // Reject if use occurs before allocation (e.g., stored in pre-existing object)
  if (vla.isAliveAtBeginOfBlock(ARI->getFunction()->getEntryBlock())) {
    DEBUG(llvm::dbgs() << "  use precedes allocation -> skip promotion");
    return false;
  }

  // Determine end-of-lifetime positions
  ValueLifetimeAnalysis::Frontier frontier;
  if (!vla.computeFrontier(frontier, ValueLifetimeAnalysis::UsersMustPostDomDef,
                           &DEBlocks)) {
    DEBUG(llvm::dbgs() << "  uses don't post-dominate allocation -> skip promotion");
    return false;
  }

  NumObjectsPromoted++;

  // Mark allocation as stack-based
  ARI->setStackAllocatable();

  // Insert corresponding deallocation at each frontier point
  for (SILInstruction *frontierInst : frontier) {
    SILBuilder builder(frontierInst);
    builder.createDeallocRef(ARI->getLoc(), ARI, true);
  }

  return true;
}
} // end anonymous namespace

SILTransform *swift::createStackPromotion() {
  return new StackPromotion();
}

