MobileManipulatorInterface::MobileManipulatorInterface(const std::string& configPath, const std::string& libFolder,
                                                       const std::string& robotModelFile) {
  // verify configuration file existence
  boost::filesystem::path configFilePath(configPath);
  if (boost::filesystem::exists(configFilePath)) {
    std::cerr << "[MobileManipulatorInterface] Loading configuration file: " << configFilePath << std::endl;
  } else {
    throw std::invalid_argument("[MobileManipulatorInterface] Configuration file not found: " + configFilePath.string());
  }

  // verify robot model file existence
  boost::filesystem::path robotModelFilePath(robotModelFile);
  if (boost::filesystem::exists(robotModelFilePath)) {
    std::cerr << "[MobileManipulatorInterface] Loading Pinocchio model from: " << robotModelFilePath << std::endl;
  } else {
    throw std::invalid_argument("[MobileManipulatorInterface] Robot model file not found: " + robotModelFilePath.string());
  }

  // ensure library directory exists
  boost::filesystem::path libFolderPath(libFolder);
  boost::filesystem::create_directories(libFolderPath);
  std::cerr << "[MobileManipulatorInterface] Generated library path: " << libFolderPath << std::endl;

  // construct pinocchio interface
  pinocchioInterfacePtr_.reset(new PinocchioInterface(buildPinocchioInterface(robotModelFile)));
  std::cerr << *pinocchioInterfacePtr_;

  bool enablePreComputation = true;
  bool forceRecompilation = true;
  boost::property_tree::ptree paramsTree;
  boost::property_tree::read_info(configPath, paramsTree);

  std::cerr << "\n #### Model Configuration:";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadPtreeValue(paramsTree, enablePreComputation, "model_settings.enablePreComputation", true);
  loadData::loadPtreeValue(paramsTree, forceRecompilation, "model_settings.forceRecompilation", true);
  std::cerr << " #### =============================================================================\n";

  // Default initial state
  loadData::loadEigenMatrix(configPath, "initialState", initialState_);
  std::cerr << "Initial State:   " << initialState_.transpose() << std::endl;

  // DDP-MPC settings
  ddpSettings_ = ddp::loadSettings(configPath, "ddp");
  mpcSettings_ = mpc::loadSettings(configPath, "mpc");

  // Reference Manager
  referenceManagerPtr_.reset(new ReferenceManager);

  /*
   * Optimal control problem formulation
   */
  // Cost terms
  problem_.costPtr->add("inputEnergy", getQuadraticInputCost(configPath));

  // Constraints
  problem_.softConstraintPtr->add("jointSpeedLimit", getJointVelocityLimitConstraint(configPath));
  problem_.stateSoftConstraintPtr->add("selfCollisionAvoidance", getSelfCollisionConstraint(*pinocchioInterfacePtr_, configPath, robotModelFile,
                                                                                           enablePreComputation, libFolder, forceRecompilation));
  problem_.stateSoftConstraintPtr->add("targetEndEffector", getEndEffectorConstraint(*pinocchioInterfacePtr_, configPath, "endEffector",
                                                                                     enablePreComputation, libFolder, forceRecompilation));
  problem_.finalSoftConstraintPtr->add("finalEndEffectorPose", getEndEffectorConstraint(*pinocchioInterfacePtr_, configPath, "finalEndEffector",
                                                                                        enablePreComputation, libFolder, forceRecompilation));

  // Dynamics model
  problem_.dynamicsPtr.reset(new MobileManipulatorDynamics("mobile_manipulator_dynamics", libFolder, forceRecompilation, true));

  /*
   * Pre-computation setup
   */
  if (enablePreComputation) {
    problem_.preComputationPtr.reset(new MobileManipulatorPreComputation(*pinocchioInterfacePtr_));
  }

  // Rollout configuration
  const auto rolloutConfig = rollout::loadSettings(configPath, "rollout");
  rolloutPtr_.reset(new TimeTriggeredRollout(*problem_.dynamicsPtr, rolloutConfig));

  // Initialization strategy
  initializerPtr_.reset(new DefaultInitializer(INPUT_DIM));
}

PinocchioInterface MobileManipulatorInterface::buildPinocchioInterface(const std::string& robotModelFile) {
  // Add 3 DOF for base mobility (x, y, rotation)
  pinocchio::JointModelComposite baseJoint(3);
  baseJoint.addJoint(pinocchio::JointModelPX());
  baseJoint.addJoint(pinocchio::JointModelPY());
  baseJoint.addJoint(pinocchio::JointModelRZ());
  return getPinocchioInterfaceFromUrdfFile(robotModelFile, baseJoint);
}

std::unique_ptr<StateInputCost> MobileManipulatorInterface::getQuadraticInputCost(const std::string& configPath) {
  matrix_t controlWeightMat(INPUT_DIM, INPUT_DIM);
  std::cerr << "\n #### Control Cost Configuration: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadEigenMatrix(configPath, "controlCost.R", controlWeightMat);
  std::cerr << "controlCost.R:  \n" << controlWeightMat << '\n';
  std::cerr << " #### =============================================================================\n";
  return std::unique_ptr<StateInputCost>(new QuadraticInputCost(std::move(controlWeightMat)));
}

std::unique_ptr<StateCost> MobileManipulatorInterface::getEndEffectorConstraint(const PinocchioInterface& pinocchioInterface,
                                                                                const std::string& configPath, const std::string& targetPrefix,
                                                                                bool useFastComputation, const std::string& libDirectory,
                                                                                bool forceRecompile) {
  scalar_t positionWeight = 1.0;
  scalar_t orientationWeight = 1.0;
  const std::string endEffectorName = "WRIST_2";
  boost::property_tree::ptree paramsTree;
  boost::property_tree::read_info(configPath, paramsTree);

  std::cerr << "\n #### " << targetPrefix << " Configuration: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadPtreeValue(paramsTree, positionWeight, targetPrefix + ".positionWeight", true);
  loadData::loadPtreeValue(paramsTree, orientationWeight, targetPrefix + ".orientationWeight", true);
  std::cerr << " #### =============================================================================\n";

  if (referenceManagerPtr_ == nullptr) {
    throw std::runtime_error("[getEndEffectorConstraint] referenceManagerPtr_ must be initialized first!");
  }

  std::unique_ptr<StateConstraint> constraintPtr;
  if (useFastComputation) {
    MobileManipulatorPinocchioMapping<scalar_t> kinematicMapping;
    PinocchioEndEffectorKinematics eeKinematics(pinocchioInterface, kinematicMapping, {endEffectorName});
    constraintPtr.reset(new EndEffectorConstraint(eeKinematics, *referenceManagerPtr_));
  } else {
    MobileManipulatorPinocchioMapping<ad_scalar_t> adKinematicMapping;
    PinocchioEndEffectorKinematicsCppAd eeKinematics(pinocchioInterface, adKinematicMapping, {endEffectorName}, STATE_DIM, INPUT_DIM,
                                                     "end_effector_kinematics", libDirectory, forceRecompile, false);
    constraintPtr.reset(new EndEffectorConstraint(eeKinematics, *referenceManagerPtr_));
  }

  std::vector<std::unique_ptr<PenaltyBase>> penaltyArray(6);
  std::generate_n(penaltyArray.begin(), 3, [&]() { return std::unique_ptr<PenaltyBase>(new QuadraticPenalty(positionWeight)); });
  std::generate_n(penaltyArray.begin() + 3, 3, [&]() { return std::unique_ptr<PenaltyBase>(new QuadraticPenalty(orientationWeight)); });

  return std::unique_ptr<StateCost>(new StateSoftConstraint(std::move(constraintPtr), std::move(penaltyArray)));
}

std::unique_ptr<StateCost> MobileManipulatorInterface::getSelfCollisionConstraint(const PinocchioInterface& pinocchioInterface,
                                                                                  const std::string& configPath, const std::string& robotModelFile,
                                                                                  bool useFastComputation, const std::string& libDirectory,
                                                                                  bool forceRecompile) {
  std::vector<std::pair<size_t, size_t>> collisionObjectPairs;
  std::vector<std::pair<std::string, std::string>> collisionLinkPairs;
  scalar_t barrierParam = 1e-2;
  scalar_t smoothingParam = 1e-3;
  scalar_t minClearance = 0.0;

  boost::property_tree::ptree paramsTree;
  boost::property_tree::read_info(configPath, paramsTree);
  const std::string prefix = "selfCollision.";

  std::cerr << "\n #### SelfCollision Configuration: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadPtreeValue(paramsTree, barrierParam, prefix + "barrierParam", true);
  loadData::loadPtreeValue(paramsTree, smoothingParam, prefix + "smoothingParam", true);
  loadData::loadPtreeValue(paramsTree, minClearance, prefix + "minClearance", true);
  loadData::loadStdVectorOfPair(configPath, prefix + "collisionObjectPairs", collisionObjectPairs, true);
  loadData::loadStdVectorOfPair(configPath, prefix + "collisionLinkPairs", collisionLinkPairs, true);
  std::cerr << " #### =============================================================================\n";

  PinocchioGeometryInterface geometryInterface(pinocchioInterface, collisionLinkPairs, collisionObjectPairs);
  const size_t numCollisionPairs = geometryInterface.getNumCollisionPairs();
  std::cerr << "SelfCollision: Checking " << numCollisionPairs << " collision pairs\n";

  std::unique_ptr<StateConstraint> constraintPtr;
  if (useFastComputation) {
    constraintPtr = std::unique_ptr<StateConstraint>(new MobileManipulatorSelfCollisionConstraint(
        MobileManipulatorPinocchioMapping<scalar_t>(), std::move(geometryInterface), minClearance));
  } else {
    constraintPtr = std::unique_ptr<StateConstraint>(
        new SelfCollisionConstraintCppAd(pinocchioInterface, MobileManipulatorPinocchioMapping<scalar_t>(), std::move(geometryInterface),
                                         minClearance, "self_collision", libDirectory, forceRecompile, false));
  }

  std::unique_ptr<PenaltyBase> penaltyFunc(new RelaxedBarrierPenalty({barrierParam, smoothingParam}));
  return std::unique_ptr<StateCost>(new StateSoftConstraint(std::move(constraintPtr), std::move(penaltyFunc)));
}

std::unique_ptr<StateInputCost> MobileManipulatorInterface::getJointVelocityLimitConstraint(const std::string& configPath) {
  vector_t lowerBound(INPUT_DIM);
  vector_t upperBound(INPUT_DIM);
  scalar_t barrierParam = 1e-2;
  scalar_t smoothingParam = 1e-3;

  boost::property_tree::ptree paramsTree;
  boost::property_tree::read_info(configPath, paramsTree);
  const std::string prefix = "jointVelocityLimits.";

  std::cerr << "\n #### JointVelocityLimits Configuration: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadEigenMatrix(configPath, "jointVelocityLimits.lowerBound", lowerBound);
  std::cerr << " #### 'lowerBound':  " << lowerBound.transpose() << std::endl;
  loadData::loadEigenMatrix(configPath, "jointVelocityLimits.upperBound", upperBound);
  std::cerr << " #### 'upperBound':  " << upperBound.transpose() << std::endl;
  loadData::loadPtreeValue(paramsTree, barrierParam, prefix + "barrierParam", true);
  loadData::loadPtreeValue(paramsTree, smoothingParam, prefix + "smoothingParam", true);
  std::cerr << " #### =============================================================================\n";

  std::unique_ptr<StateInputConstraint> constraintPtr(new JointVelocityLimits);
  std::vector<std::unique_ptr<PenaltyBase>> penaltyArray(INPUT_DIM);
  for (int i = 0; i < INPUT_DIM; ++i) {
    std::unique_ptr<PenaltyBase> barrierFunction(new RelaxedBarrierPenalty({barrierParam, smoothingParam}));
    penaltyArray[i].reset(new DoubleSidedPenalty(lowerBound(i), upperBound(i), std::move(barrierFunction)));
  }
  return std::unique_ptr<StateInputCost>(new StateInputSoftConstraint(std::move(constraintPtr), std::move(penaltyArray)));
}

