                     const GLchar* message,
                     const void* userParam)
{
    if (severity != GL_DEBUG_SEVERITY_HIGH) return;
    fprintf(
        stderr,
        "GL CALLBACK: %s type = 0x%x, severity = 0x%x, message = %s\n",
        (type == GL_DEBUG_TYPE_ERROR ? "** GL ERROR **" : ""),
        type, severity, message
    );
}

