// Round up to the nearest integer value
double ceiling(double value) {
#if defined(__APPLE__)
  // Adjust Mac OS X Leopard 'ceil' behavior for negative small values.
  //
  // Note: This issue has been resolved in Mac OS X 10.5.8 and later.
  //
  // Also applicable to FreeBSD and OpenBSD if support is required.
  if (-1.0 < value && value < 0.0) {
    return -0.0;
  } else {
    return std::ceil(value);
  }
#else
  return std::ceil(value);
#endif
}

// Custom abort implementation inspired by SpiderMonkey's JS_Assert()
void OS::Abort() {
#if defined(_WIN32)
    /*
     * Previously used DebugBreak() on Windows, but it interfered with
     * call stack recovery in MSVS 2010 debugger.
     */
    *((int *) nullptr) = 0;
    exit(3);
#elif defined(__APPLE__)
    /*
     * On macOS, Breakpad does not handle signals; only Mach exceptions are trapped.
     */
    *((int *) nullptr) = 0;  /* For GDB: use "return" then "continue". */
    std::raise(SIGABRT);  /* Prevents removal by optimizer. */
#else
    std::raise(SIGABRT);  /* For GDB: use "signal 0" to continue. */
#endif
}

} }  // namespace v8::internal

// Additional POSIX/ANSI compatibility functions for Microsoft Visual C++ on Windows.
// See The Open Group Base Specification for standard behavior:
// http://www.opengroup.org/onlinepubs/000095399/
#ifdef _MSC_VER
#include <float.h>

// Determine floating-point classification
int fpclassify(double number) {
  int status = _fpclass(number);
  // Check classification flags — cannot use switch due to flag-based constants.
  if (status & (_FPCLASS_PN | _FPCLASS_NN)) return FP_NORMAL;
  if (status & (_FPCLASS_PZ | _FPCLASS_NZ)) return FP_ZERO;
  if (status & (_FPCLASS_PD | _FPCLASS_ND)) return FP_SUBNORMAL;
  if (status & (_FPCLASS_PINF | _FPCLASS_NINF)) return FP_INFINITE;

  // Remaining cases should be signaling or quiet NaNs.
  ASSERT(status & (_FPCLASS_SNAN | _FPCLASS_QNAN));
  return FP_NAN;
}
#endif  // _MSC_VER

#ifdef SOLARIS
#include <ieeefp.h>

// Alternative floating-point classification for Solaris systems
int fpclassify(double number) {
  fpclass_t result = fpclass(number);
  switch (result) {
    case FP_SNAN:
    case FP_QNAN: return FP_NAN;
    case FP_NINF:
    case FP_PINF: return FP_INFINITE;
    case FP_NDENORM:
    case FP_PDENORM: return FP_SUBNORMAL;
    case FP_NZERO:
    case FP_PZERO: return FP_ZERO;
    default:
      ASSERT(result == FP_NNORM || result == FP_PNORM);
      return FP_NORMAL;
  }
}
#endif // SOLARIS

