/////////////////////////////////////////////////////////////////////////////////////
POWorkerThread::POWorkerThread()
{
	m_taskType = -1;
	m_result = false;
	m_initialized = false;
	m_pImageData = nullptr;
}
/////////////////////////////////////////////////////////////////////////////////////
POWorkerThread::~POWorkerThread()
{
	Terminate();
}
/////////////////////////////////////////////////////////////////////////////////////
int POWorkerThread::StaticThreadEntry(void* param)
{
	POWorkerThread* instance = static_cast<POWorkerThread*>(param);
	return instance->Execute();
}
/////////////////////////////////////////////////////////////////////////////////////
bool POWorkerThread::ProcessTask()
{
	const PngDumpData& dataRef = *m_pImageData;
	PngDumpSettings settings;
	settings.zlibCompressionLevel = 9;
	if( m_taskType == 0 )
	{
		// Scenario A
		// - Disable filtering
		// - Use default ZLib strategy
		// - Standard memory usage
		settings.filtering = 0;
		settings.zlibStrategy = PngDumpSettings::zlibStrategyDefault;
		settings.zlibWindowBitsAndMem = 0;
		if( !PngDumper::Dump(m_outputFile, dataRef, settings) )
		{
			return false;
		}
	}
	else if( m_taskType == 1 )
	{
		// Applicable for images with low bit depth
		int bitsPerPixel = ImageFormat::SizeofPixelInBits(dataRef.pixelFormat);
		if( bitsPerPixel <= 8 )
		{
			// Scenario B
			// - No filtering applied
			// - Default ZLib strategy
			// - Optimized for low memory consumption (compression may improve unexpectedly)
			settings.filtering = 0;
			settings.zlibStrategy = PngDumpSettings::zlibStrategyDefault;
			settings.zlibWindowBitsAndMem = PngDumpSettings::zlibWindowBitsAndMemLow;
			if( !PngDumper::Dump(m_outputFile, dataRef, settings) )
			{
				return false;
			}
		}
	}
	else if( m_taskType == 2 )
	{
		// Scenario C
		// - Enable adaptive filtering
		// - Filter-optimized ZLib strategy
		// - Normal memory allocation
		settings.filtering = 1;
		settings.zlibStrategy = PngDumpSettings::zlibStrategyFilter;
		settings.zlibWindowBitsAndMem = 0;
		if( !PngDumper::Dump(m_outputFile, dataRef, settings) )
		{
			return false;
		}
	}
	else if( m_taskType == 3 )
	{
		// Scenario D
		// - Filtering enabled
		// - Default ZLib strategy
		// - Standard memory footprint
		settings.filtering = 1;
		settings.zlibStrategy = PngDumpSettings::zlibStrategyDefault;
		settings.zlibWindowBitsAndMem = 0;
		if( !PngDumper::Dump(m_outputFile, dataRef, settings) )
		{
			return false;
		}
	}
	else
	{
		return false;
	}
	return true;
}
/////////////////////////////////////////////////////////////////////////////////////
int POWorkerThread::Execute()
{
	for(;;)
	{
		if( m_semaphoreStart.Wait() != 0 )
		{
			break;
		}
		// Execute assigned task
		if( m_taskType < 0 )
		{
			// Shutdown signal received
			break;
		}
		m_result = ProcessTask();
		m_semaphoreReady.Increment();
	}
	return 0;
}
/////////////////////////////////////////////////////////////////////////////////////
// Initializes the worker thread and associated resources.
// Returns true on successful initialization
bool POWorkerThread::Initialize()
{
	const size_t initialBufferSize = 256 * 1024 - 64;
	m_outputFile.Open(initialBufferSize);
	if( !m_semaphoreStart.Create() )
	{
		return false;
	}
	if( !m_semaphoreReady.Create() )
	{
		return false;
	}
	if( !m_workerThread.Start(&StaticThreadEntry, this) )
	{
		return false;
	}
	m_initialized = true;
	return true;
}
/////////////////////////////////////////////////////////////////////////////////////
// Starts processing a new job. Initializes the worker if needed.
// [in] taskType   Type of operation to perform. Valid range: [0..3]
// [in] pImageData Pointer to input image data
// Returns true if job was successfully queued. Call Wait() to retrieve outcome.
bool POWorkerThread::Start(int taskType, const PngDumpData* pImageData)
{
	if( !m_initialized && !Initialize() )
	{
		return false;
	}
	if( !(0 <= taskType && taskType <= 3) )
	{
		return false;
	}
	m_pImageData = pImageData;
	m_taskType = taskType;
	m_result = false;
	m_outputFile.SetPosition(0);
	m_semaphoreStart.Increment();
	return true;
}
/////////////////////////////////////////////////////////////////////////////////////
// Blocks until the current job completes execution.
/////////////////////////////////////////////////////////////////////////////////////
void POWorkerThread::Wait()
{
	if( m_taskType < 0 )
	{
		return;
	}
	m_semaphoreReady.Wait();
	m_taskType = -1;
	m_pImageData = nullptr;
}
/////////////////////////////////////////////////////////////////////////////////////
// Requests graceful termination of the worker thread if it's idle.
/////////////////////////////////////////////////////////////////////////////////////
void POWorkerThread::Terminate()
{
	if( !m_initialized )
	{
		return;
	}
	m_pImageData = nullptr;
	m_taskType = -1; // Signal shutdown
	m_result = false;
	m_semaphoreStart.Increment();
	m_workerThread.Join();
	m_semaphoreStart.Close();
}
/////////////////////////////////////////////////////////////////////////////////////
// Retrieves the status of the last completed job.
// Returns true if the operation succeeded
bool POWorkerThread::IsSuccessful() const
{
	return m_result;
}
/////////////////////////////////////////////////////////////////////////////////////
// Accesses the output buffer containing the generated PNG file.
DynamicMemoryFile& POWorkerThread::GetOutput()
{
	return m_outputFile;
}

