#define PARENT BaseEinastoModel
    void MODEL_NAMESPACE::Einasto_rho0_to_BaseEinasto (const ModelParameters &input_params, ModelParameters &output_params)
    {
        double central_density = input_params["central_density"];
        double scale_radius = input_params["scale_radius"];
        double solar_distance = input_params["solar_distance"];
        double shape_parameter = input_params["shape_parameter"];
        double reference_density = central_density * exp((2.0 / shape_parameter) * (pow(solar_distance / scale_radius, shape_parameter) - 1.0));
        output_params.setValues(input_params, true);
        output_params.setValue("reference_density", reference_density);
    }
#undef PARENT
#undef MODEL

#define MODEL Einasto_rhos_form
#define PARENT BaseEinastoModel
    void MODEL_NAMESPACE::Einasto_rhos_to_BaseEinasto (const ModelParameters &input_params, ModelParameters &output_params)
    {
        double reference_density = input_params["reference_density"];
        double scale_radius = input_params["scale_radius"];
        double solar_distance = input_params["solar_distance"];
        double shape_parameter = input_params["shape_parameter"];
        double central_density = reference_density * exp((-2.0 / shape_parameter) * (pow(solar_distance / scale_radius, shape_parameter) - 1.0));
        output_params.setValues(input_params, true);
        output_params.setValue("central_density", central_density);
    }
#undef PARENT
#undef MODEL

