namespace chess
{
    pawn::pawn(color c, const position_type& pos)
        : chess_piece(c, pos)
        , m_has_moved(false)
    {
    }

    bool pawn::can_move(const position_type& new_pos,
                        const has_piece_callback& cb) const
    {
        color player_color = get_color();
        const position_type& current_position = get_position();
        bool is_valid = false;

        bool same_file = new_pos.first == current_position.first;
        bool forward_1_white = (new_pos.second == current_position.second + 1) && (player_color == 'w');
        bool forward_2_white = (new_pos.second == current_position.second + 2) && (player_color == 'w');
        bool forward_1_black = (new_pos.second + 1 == current_position.second) && (player_color == 'b');
        bool forward_2_black = (new_pos.second + 2 == current_position.second) && (player_color == 'b');

        bool move_forward_1 = same_file && (forward_1_white || forward_1_black);
        bool move_forward_2 = same_file && (forward_2_white || forward_2_black);

        bool diagonal_white = (new_pos.first == current_position.first + 1 || new_pos.first + 1 == current_position.first)
            && (new_pos.second == current_position.second + 1u);
        bool diagonal_black = (new_pos.first + 1 == current_position.first || new_pos.first == current_position.first + 1)
            && (new_pos.second == current_position.second + 1u);

        if (diagonal_white || diagonal_black)
        {
            is_valid = cb(new_pos, get_opposite_color());
        }
        else if (move_forward_1)
        {
            is_valid = !cb(new_pos, 'a');
        }
        else if (move_forward_2)
        {
            is_valid = !m_has_moved;
            if (player_color == 'w')
            {
                is_valid &= !cb(position_type(current_position.first, current_position.second + 1), 'a');
            }
            else
            {
                is_valid &= !cb(position_type(current_position.first, new_pos.second + 1), 'a');
            }
            is_valid &= !cb(new_pos, 'a');
        }
        return is_valid;
    }

    void pawn::print(std::ostream& out) const
    {
        out << "P" << get_color();
    }

    void pawn::notify_move()
    {
        m_has_moved = true;
    }
}

