Color::Color()
{
    red = 0;
    green = 0;
    blue = 0;
}

Color::Color(int32 r, int32 g, int32 b)
{
    red = r;
    green = g;
    blue = b;
}

Color::Color(int32 rgbValue)
{
    red = (rgbValue & 0xff0000) >> 16;
    green = (rgbValue & 0xff00) >> 8;
    blue = rgbValue & 0xff;
