namespace gui::settings {
    ActionSettingsPane::ActionSettingsPane(model::settings::ActionSettingsModel *config, QWidget *parent)
        : QWidget(parent), config(config) {
        currentMode = config->getMode();
        currentSound = config->getSound();
        currentColor = config->getColor();
        currentInterval = config->getInterval();
        currentCount = config->getCount();
        initializeComponents();
    }

    void ActionSettingsPane::initializeComponents() {
        auto *layout = new QGridLayout(this);

        // ----- mode -----
        {
            auto *modeCombo = new QComboBox;
            auto *fieldBox = new util::FieldSet<QComboBox>(0, new QLabel("Mode"), modeCombo);
            gui::util::widget::addItems<model::ActionMode>(modeCombo, model::actionModes(), [](model::ActionMode m) {
                return model::getName(m);
            });
            modeCombo->setCurrentText(model::getName(config->getMode()));
            util::addFieldSet(layout, *fieldBox);
            connect(modeCombo, SIGNAL(currentIndexChanged(int)), this, SLOT(setMode(int)));
        }

        // ----- sound -----
        {
            auto *soundCombo = new QComboBox;
            auto *fieldBox = new util::FieldSet<QComboBox>(1, new QLabel("Sound"), soundCombo);
            gui::util::widget::addItems<model::Sound>(soundCombo, model::sounds(), [](model::Sound s) {
                return model::getName(s);
            });
            soundCombo->setCurrentText(model::getName(config->getSound()));
            util::addFieldSet(layout, *fieldBox);
            connect(soundCombo, SIGNAL(currentIndexChanged(int)), this, SLOT(setSound(int)));
            connect(this, &ActionSettingsPane::modeChanged, [layout, fieldBox](const int mode) {
                const bool visible = mode == model::ActionMode::AUDIO || mode == model::ActionMode::AV;
                util::setVisible(layout, *fieldBox, visible);
            });
        }

        // ----- color -----
        {
            auto *colorBtn = new QPushButton;
            auto *fieldBox = new util::FieldSet<QPushButton>(2, new QLabel("Color"), colorBtn);
            setIconColor(colorBtn, currentColor);
            connect(colorBtn, &QPushButton::clicked, [this, colorBtn] {
                const QColor pickedColor = QColorDialog::getColor(currentColor, this);
                if (pickedColor.isValid()) {
                    setIconColor(colorBtn, pickedColor);
                    currentColor = pickedColor;
                }
            });
            connect(this, &ActionSettingsPane::modeChanged, [layout, fieldBox](const int mode) {
                const bool visible = mode == model::ActionMode::VISUAL || mode == model::ActionMode::AV;
                util::setVisible(layout, *fieldBox, visible);
            });
            util::addFieldSet(layout, *fieldBox);
        }

        // ----- interval -----
        {
            auto *intervalSpin = new QSpinBox;
            auto *fieldBox = new util::FieldSet<QSpinBox>(3, new QLabel("Interval"), intervalSpin);
            gui::util::widget::setModel(intervalSpin, 1, 1000, config->getInterval());
            util::addFieldSet(layout, *fieldBox);
            connect(intervalSpin, SIGNAL(valueChanged(int)), this, SLOT(setInterval(int)));
        }

        // ----- count -----
        {
            auto *countSpin = new QSpinBox;
            auto *fieldBox = new util::FieldSet<QSpinBox>(4, new QLabel("Count"), countSpin);
            gui::util::widget::setModel(countSpin, 1, 50, config->getCount());
            util::addFieldSet(layout, *fieldBox);
            connect(countSpin, SIGNAL(valueChanged(int)), this, SLOT(setCount(int)));
        }

        // ensure all fieldsets reflect current visibility state
        emit modeChanged(currentMode);
    }

    void ActionSettingsPane::applyChanges() {
        config->setMode(model::actionMode(static_cast<unsigned int>(currentMode)));
        config->setSound(model::sound(static_cast<unsigned int>(currentSound)));
        config->setInterval(static_cast<unsigned int>(currentInterval));
        config->setCount(static_cast<unsigned int>(currentCount));
        config->setColor(currentColor);
    }

    void ActionSettingsPane::setMode(int mode) {
        if (currentMode != mode) {
            emit modeChanged(mode);
            currentMode = mode;
        }
    }

    void ActionSettingsPane::setSound(int sound) { currentSound = sound; }
    void ActionSettingsPane::setInterval(int interval) { currentInterval = interval; }
    void ActionSettingsPane::setCount(int count) { currentCount = count; }

    void ActionSettingsPane::setIconColor(QPushButton *button, const QColor &color) {
        QPixmap iconPixmap(64, 64);
        iconPixmap.fill(color);
        QIcon buttonIcon(iconPixmap);
        button->setIcon(buttonIcon);
    }
}  // namespace gui::settings

#include "test_helper.h"
#include "compiler/lexical_grammar.h"
#include "compiler/prepare_grammar/expand_tokens.h"
#include "helpers/stream_methods.h"
START_TEST
using namespace rules;
using prepare_grammar::expand_token;
using prepare_grammar::ExpandTokenResult;
describe("token_expansion", []() {
  MetadataParams char_params;
  char_params.is_string = true;
  char_params.is_token = true;
  describe("literal string processing", [&]() {
    it("converts string literals into character set sequences", [&]() {
      AssertThat(
        expand_token(Rule::seq({
          String{"x"},
          String{"yz1"},
          String{"k"}
        })).rule,
        Equals(Rule::seq({
          CharacterSet{{ 'x' }},
          Rule::seq({
            CharacterSet{{ 'y' }},
            CharacterSet{{ 'z' }},
            CharacterSet{{ '1' }},
          }),
          CharacterSet{{ 'k' }},
        })));
    });
    it("supports Unicode characters encoded in UTF-8", [&]() {
      AssertThat(
        expand_token(String{"\xD0\x90 \xD0\x91"}).rule,
        Equals(Rule::seq({
          CharacterSet{{ 1040 }},
          CharacterSet{{ ' ' }},
          CharacterSet{{ 1041 }},
        }))
      );
    });
  });
  describe("regular expression handling", [&]() {
    it("transforms regex patterns into corresponding rule structures", [&]() {
      AssertThat(
        expand_token(Rule::seq({
          String{"m"},
          Pattern{"p*"},
          String{"q"},
        })).rule,
        Equals(Rule::seq({
          CharacterSet{{'m'}},
          Repeat{CharacterSet{{ 'p' }}},
          CharacterSet{{'q'}},
        }))
      );
    });
    it("processes regexes with non-ASCII Unicode ranges correctly", [&]() {
      AssertThat(
        expand_token(Pattern{"[^\xD0\x92-\xD0\x95]+"}).rule,
        Equals(Rule(Repeat{
          CharacterSet().include_all().exclude(1042, 1045)
        }))
      );
    });
    it("produces an error for malformed regular expressions", [&]() {
      AssertThat(
        expand_token(Rule::seq({
          Pattern{"{"},
          String{"abc"},
          Pattern{"|"},
        })).error,
        Equals(CompileError(
          TSCompileErrorTypeInvalidRegex,
          "invalid repetition operator"
        ))
      );
    });
  });
});
END_TEST

#include <LuaConsole/LuaSFMLConsoleView.hpp>
