namespace blua {

const unsigned kTextSize = 18u;
const char * const kFontPath = "DejaVuSansMono.ttf";

static sf::Color convertColor(unsigned hexColor)
{
    sf::Color result;
    result.r = (hexColor & 0xff000000) >> 24;
    result.g = (hexColor & 0xff0000) >> 16;
    result.b = (hexColor & 0xff00) >> 8;
    result.a = hexColor & 0xff;
    return result;
}

LuaSFMLConsoleView::LuaSFMLConsoleView(bool useDefaultFont) :
m_lastUpdate(0u),
m_font(nullptr),
m_ownsFont(false),
m_useDefaultFont(useDefaultFont),
m_isVisible(false)
{
    m_vertices.setPrimitiveType(sf::Quads);
    if(m_useDefaultFont)
    {
        sf::Font * defaultFont = new sf::Font;
        defaultFont->loadFromFile(kFontPath);
        m_font = defaultFont;
        m_ownsFont = true;
    }
}

LuaSFMLConsoleView::~LuaSFMLConsoleView()
{
    if(m_ownsFont)
        delete m_font;
}

void LuaSFMLConsoleView::render(sf::RenderTarget& target, sf::RenderStates states) const
{
    if(!m_font || !m_isVisible)
        return;

    sf::View currentView = target.getView();
    target.setView(sf::View(sf::FloatRect(sf::Vector2f(), sf::Vector2f(target.getSize()))));
    states.texture = &m_font->getTexture(kTextSize);
    target.draw(m_vertices, states);
    target.setView(currentView);
}

void LuaSFMLConsoleView::assignFont(const sf::Font * font)
{
    if(m_ownsFont)
        delete m_font;

    m_font = font;
    m_ownsFont = false;

    if(!m_font && m_useDefaultFont)
    {
        sf::Font * defaultFont = new sf::Font;
        defaultFont->loadFromFile(kFontPath);
        m_font = defaultFont;
        m_ownsFont = true;
    }
}

const sf::Font * LuaSFMLConsoleView::retrieveFont() const
{
    return m_font;
}

