void LuaSFMLConsoleView::updateGeometry(const LuaConsoleModel * model)
{
    if(!model)
        return;

    if(m_lastUpdate == model->getDirtyness())
        return;

    if(!m_font)
        return;

    m_lastUpdate = model->getDirtyness();
    m_isVisible = model->isVisible();

    if(!m_isVisible)
        return;

    const ScreenCell * buffer = model->getScreenBuffer();
    m_vertices.clear();

    // Reserve space for background rectangle
    for(int i = 0; i < 4; ++i)
        m_vertices.append(sf::Vertex());

    float horizontalSpacing = m_font->getGlyph(L' ', kTextSize, false).advance;
    float verticalSpacing = m_font->getLineSpacing(kTextSize);
    float cursorX = 0.f;
    float cursorY = kTextSize;
    sf::Uint32 previousCharacter = 0u;

    std::size_t totalCells = model->getConsoleWidth() * model->getConsoleHeight();

    for(std::size_t index = 0u; index < totalCells; ++index)
    {
        sf::Uint32 currentChar = buffer[index].Char;

        // Adjust reserved background vertices position
        if(index == 1u)
            for(std::size_t k = 0u; k < 4u; ++k)
                m_vertices[k].position = m_vertices[4].position;

        // Apply kerning
        cursorX += m_font->getKerning(previousCharacter, currentChar, kTextSize);
        previousCharacter = currentChar;

        // Draw cursor block at specific position
        if(model->getCurPos() + (model->getConsoleWidth() * (model->getConsoleHeight() - 2)) == index)
        {
            const sf::Uint32 BLOCK_CHAR = 0x2588u;
            const sf::Glyph glyph = m_font->getGlyph(BLOCK_CHAR, kTextSize, false);
            const sf::Color cursorColor = convertColor(model->getColor(ECC_CURSOR));
            const sf::Vector2f texCoords = sf::Vector2f(1.f, 1.f);

            m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + glyph.bounds.left, cursorY + glyph.bounds.top), cursorColor, texCoords));
            m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + glyph.bounds.left, cursorY + glyph.bounds.top + glyph.bounds.height), cursorColor, texCoords));
            m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + glyph.bounds.left + glyph.bounds.width, cursorY + glyph.bounds.top + glyph.bounds.height), cursorColor, texCoords));
            m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + glyph.bounds.left + glyph.bounds.width, cursorY + glyph.bounds.top), cursorColor, texCoords));
        }

        // Handle whitespace characters
        switch(currentChar)
        {
            case '\t': case '\n': case ' ':
                cursorX += horizontalSpacing;
                continue;
        }

        // Process visible character
        const sf::Glyph& glyph = m_font->getGlyph(currentChar, kTextSize, false);
        int left = glyph.bounds.left;
        int top = glyph.bounds.top;
        int right = glyph.bounds.left + glyph.bounds.width;
        int bottom = glyph.bounds.top + glyph.bounds.height;

        float u1 = glyph.textureRect.left;
        float v1 = glyph.textureRect.top;
        float u2 = glyph.textureRect.left + glyph.textureRect.width;
        float v2 = glyph.textureRect.top + glyph.textureRect.height;

        const sf::Color textColor = convertColor(buffer[index].Color);

        m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + left, cursorY + top), textColor, sf::Vector2f(u1, v1)));
        m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + right, cursorY + top), textColor, sf::Vector2f(u2, v1)));
        m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + right, cursorY + bottom), textColor, sf::Vector2f(u2, v2)));
        m_vertices.append(sf::Vertex(sf::Vector2f(cursorX + left, cursorY + bottom), textColor, sf::Vector2f(u1, v2)));

        cursorX += glyph.advance;

        if((index + 1) % model->getConsoleWidth() == 0)
        {
            cursorY += verticalSpacing;
            cursorX = 0.f;
            previousCharacter = '\n';
        }
    }

    // Set background rectangle bounds
    const sf::FloatRect bounds = m_vertices.getBounds();
    m_vertices[0].position = sf::Vector2f(bounds.left, bounds.top);
    m_vertices[1].position = sf::Vector2f(bounds.left, bounds.top + bounds.height);
    m_vertices[2].position = sf::Vector2f(bounds.left + bounds.width, bounds.top + bounds.height);
    m_vertices[3].position = sf::Vector2f(bounds.left + bounds.width, bounds.top);

    const sf::Color bgColor = convertColor(model->getColor(ECC_BACKGROUND));
    for(std::size_t k = 0u; k < 4u; ++k)
    {
        m_vertices[k].texCoords = sf::Vector2f(1.f, 1.f);
        m_vertices[k].color = bgColor;
    }
}

