namespace steering_wheel_shield {
    // Set CSX pin high
    inline void set_csx() { GPIOC_PSOR = CSX_MASK; }
    // Clear CSX pin low
    inline void clr_csx() { GPIOC_PCOR = CSX_MASK; }
    // Set DCX pin high
    inline void set_dcx() { GPIOC_PSOR = DCX_MASK; }
    // Clear DCX pin low
    inline void clr_dcx() { GPIOC_PCOR = DCX_MASK; }
    // Set WRX pin high
    inline void set_wrx() { GPIOC_PSOR = WRX_MASK; }
    // Clear WRX pin low
    inline void clr_wrx() { GPIOC_PCOR = WRX_MASK; }
    // Set RDX pin high
    inline void set_rdx() { GPIOC_PSOR = RDX_MASK; }
    // Clear RDX pin low
    inline void clr_rdx() { GPIOC_PCOR = RDX_MASK; }
    // Set RST pin high
    inline void set_rst() { GPIOE_PSOR = RST_MASK; }
    // Clear RST pin low
    inline void clr_rst() { GPIOE_PCOR = RST_MASK; }

    // Clear all data pins
    inline void clr_data() {
        GPIOB_PCOR = PORTB_DATA_MASK;
        GPIOC_PCOR = PORTC_DATA_MASK;
    }

    // Write command to display using provided data buffer
    void write_command(uint8_t* buffer, uint8_t count) {
        clr_csx();
        clr_dcx();

        GPIOC_PSOR = buffer[0] << 4;
        clr_wrx();
        NOPN(0, 0, 9);
        set_wrx();
        NOPN(0, 0, 3);
        GPIOC_PCOR = buffer[0] << 4;

        set_dcx();

        for (int idx = 1; idx < count; idx++) {
            GPIOC_PSOR = buffer[idx] << 4;
            clr_wrx();
            NOPN(0, 0, 9);
            set_wrx();
            NOPN(0, 0, 3);
            GPIOC_PCOR = buffer[idx] << 4;
        }

        set_csx();
    }

    // Define a rectangular window on the screen
    void set_window(uint16_t x_start, uint16_t x_end, uint16_t y_start, uint16_t y_end) {
        uint8_t cmd_buffer[5];

        // Set column address
        cmd_buffer[0] = HX8357_SET_COLUMN_ADDRESS;
        cmd_buffer[1] = (x_start >> 8) & 0xFF;
        cmd_buffer[2] = x_start & 0xFF;
        cmd_buffer[3] = (x_end >> 8) & 0xFF;
        cmd_buffer[4] = x_end & 0xFF;
        write_command(cmd_buffer, 5);

        // Set page address
        cmd_buffer[0] = HX8357_SET_PAGE_ADDRESS;
        cmd_buffer[1] = (y_start >> 8) & 0xFF;
        cmd_buffer[2] = y_start & 0xFF;
        cmd_buffer[3] = (y_end >> 8) & 0xFF;
        cmd_buffer[4] = y_end & 0xFF;
        write_command(cmd_buffer, 5);
    }

    // Fill entire screen with default color
    void fill_screen() {
        clr_csx();
        clr_dcx();

        GPIOC_PSOR = HX8357_WRITE_MEMORY_START << 4;
        clr_wrx();
        NOPN(0, 0, 9);
        set_wrx();
        NOPN(0, 0, 3);
        GPIOC_PCOR = HX8357_WRITE_MEMORY_START << 4;

        set_dcx();
        GPIOC_PSOR = 0x000003F0;

        for (int row = 0; row < 320; row++) {
            for (int col = 0; col < 480; col++) {
                clr_wrx();
                NOPN(0, 0, 9);
                set_wrx();
                NOPN(0, 0, 3);
            }
        }

        GPIOC_PCOR = 0x000003F0;
    }

    // Perform hardware and software reset of the display controller
    void reset() {
        set_csx();
        set_dcx();
        set_wrx();
        set_rdx();
        set_rst();
        clr_data();
        delay(100);

        clr_rst();
        delay(100);

        set_rst();
        delay(100);

        uint8_t init_buf[16];

        // Power setting
        init_buf[0] = HX8357_SET_POWER;
        init_buf[1] = 0x44;
        init_buf[2] = 0x41;
        init_buf[3] = 0x06;
        write_command(init_buf, 4);

        // VCOM setting
        init_buf[0] = HX8357_SET_VCOM;
        init_buf[1] = 0x40;
        init_buf[2] = 0x10;
        write_command(init_buf, 3);

        // Power normal mode
        init_buf[0] = HX8357_SET_POWER_NORMAL;
        init_buf[1] = 0x05;
        init_buf[2] = 0x12;
        write_command(init_buf, 3);

        // Panel driving settings
        init_buf[0] = HX8357_SET_PANEL_DRIVING;
        init_buf[1] = 0x14;
        init_buf[2] = 0x3B;
        init_buf[3] = 0x00;
        init_buf[4] = 0x02;
        init_buf[5] = 0x11;
        write_command(init_buf, 6);

        // Display frame control
        init_buf[0] = HX8357_SET_DISPLAY_FRAME;
        init_buf[1] = 0x0C;
        write_command(init_buf, 2);

        // Panel related settings
        init_buf[0] = HX8357_SET_PANEL_RELATED;
        init_buf[1] = 0x01;
        write_command(init_buf, 2);

        // Gamma settings
        init_buf[0]  = HX8357_SET_GAMMA;
        init_buf[1]  = 0x00;
        init_buf[2]  = 0x15;
        init_buf[3]  = 0x00;
        init_buf[4]  = 0x22;
        init_buf[5]  = 0x00;
        init_buf[6]  = 0x08;
        init_buf[7]  = 0x77;
        init_buf[8]  = 0x26;
        init_buf[9]  = 0x77;
        init_buf[10] = 0x22;
        init_buf[11] = 0x04;
        init_buf[12] = 0x00;
        write_command(init_buf, 13);

        // Address mode
        init_buf[0] = HX8357_SET_ADDRESS_MODE;
        init_buf[1] = 0xC0;
        write_command(init_buf, 2);

        // Pixel format
        init_buf[0] = HX8357_SET_PIXEL_FORMAT;
        init_buf[1] = 0x06;
        write_command(init_buf, 2);

        // Set full screen window
        set_window(0, 319, 0, 479);

        // Display mode
        init_buf[0] = HX8357_SET_DISPLAY_MODE;
        init_buf[1] = 0x00;
        write_command(init_buf, 2);

        // Exit sleep mode
        init_buf[0] = HX8357_EXIT_SLEEP_MODE;
        write_command(init_buf, 1);
        delay(120);

        // Turn display on
        init_buf[0] = HX8357_SET_DISPLAY_ON;
        write_command(init_buf, 1);
        delay(10);
    }

    // Initialize hardware and start display
    void begin() {
        // Configure port control registers for data pins
        PORTB_PCR0  = PCR_MUX(1);
        PORTB_PCR1  = PCR_MUX(1);
        PORTB_PCR2  = PCR_MUX(1);
        PORTB_PCR3  = PCR_MUX(1);
        PORTB_PCR10 = PCR_MUX(1);
        PORTB_PCR11 = PCR_MUX(1);
        PORTB_PCR16 = PCR_MUX(1);
        PORTB_PCR17 = PCR_MUX(1);
        PORTB_PCR18 = PCR_MUX(1);
        PORTB_PCR19 = PCR_MUX(1);
        PORTC_PCR0  = PCR_MUX(1);
        PORTC_PCR1  = PCR_MUX(1);
        PORTC_PCR2  = PCR_MUX(1);
        PORTC_PCR3  = PCR_MUX(1);
        PORTC_PCR4  = PCR_MUX(1);
        PORTC_PCR5  = PCR_MUX(1);
        PORTC_PCR6  = PCR_MUX(1);
        PORTC_PCR7  = PCR_MUX(1);
        PORTC_PCR8  = PCR_MUX(1);
        PORTC_PCR9  = PCR_MUX(1);
        PORTC_PCR10 = PCR_MUX(1);
        PORTC_PCR11 = PCR_MUX(1);
        PORTE_PCR26 = PCR_MUX(1);

        // Set direction registers for output
        GPIOB_PDDR |= 0x000F0C0F;
        GPIOC_PDDR |= 0x00000FFF;
        GPIOE_PDDR |= 0x04000000;

        // Perform full reset sequence
        reset();
    }
} // namespace steering_wheel_shield

