/*
Test Example: f(v)=x^2+(x+y-10)^2+(2*y-z)^2+2*z;
Approximate Hessian Matrix using SR1.
*/

double objectiveFunction(Vector3d vars)
{
    double x = vars(0);
    double y = vars(1);
    double z = vars(2);
    double result;

    result = x * x + (x + y - 10) * (x + y - 10) + (2 * y - z) * (2 * y - z) + 2 * z;

    return result;
}

Vector3d gradient(Vector3d vars)
{
    Vector3d grad;
    double x = vars(0);
    double y = vars(1);
    double z = vars(2);

    double dx = 2 * x + 2 * (x + y - 10);
    double dy = 2 * (x + y - 10) + 4 * (2 * y - z);
    double dz = 2 * (z - 2 * y) + 2;

    grad(0) = dx; 
    grad(1) = dy; 
    grad(2) = dz;

    return grad;
}

bool isPositiveDefinite(Matrix3d matrix)
{
    Vector3cd eigenvals = matrix.eigenvalues();

    bool positive = eigenvals(0).real() > 0 && 
                    eigenvals(1).real() > 0 && 
                    eigenvals(2).real() > 0;

    return positive;
}

int main()
{
    Vector3d currentPoint(100, 100, 100);
    double delta = 0.25;
    Matrix3d H; H.setIdentity();
    Matrix3d Identity; Identity.setIdentity();

    while (true)
    {
        Vector3d grad = gradient(currentPoint);
        if (grad.norm() < 1e-6) break;

        while (!isPositiveDefinite(H + delta * Identity))
        {
            delta *= 4;
        }

        Matrix3d K = H + delta * Identity;
        Vector3d step = -K.inverse() * grad;

        double newFuncVal = objectiveFunction(currentPoint + step);
        double quadModel = objectiveFunction(currentPoint) + 
                          grad.transpose() * step + 
                          0.5 * step.transpose() * H * step;
        double ratio = (objectiveFunction(currentPoint) - newFuncVal) / 
                      (objectiveFunction(currentPoint) - quadModel);

        if (ratio < 0.25) 
            delta *= 4.0;
        else if (ratio > 0.75) 
            delta /= 2.0;

        if (ratio > 0)
        {
            currentPoint = currentPoint + step;
            Vector3d s_vec = -step;
            Vector3d y_vec = grad - gradient(currentPoint);
            double denom = (s_vec - H * y_vec).transpose() * y_vec;
            H = H + (s_vec - H * y_vec) * (s_vec - H * y_vec).transpose() / denom;
        }
    }

    cout << currentPoint.transpose() << endl;
    cout << objectiveFunction(currentPoint) << endl;

    return 0;
}

