namespace OVR {

bool SaveJpegImage( const char * outputPath, const unsigned char * pixelData, int imgWidth, int imgHeight )
{
	tjhandle compressor = tjInitCompress();
	unsigned char * compressedBuf = NULL;
	unsigned long compressedSize = 0;

	const int compressResult = tjCompress2( compressor, (unsigned char*)pixelData,
		imgWidth, imgWidth * 4, imgHeight, TJPF_RGBX, &compressedBuf,
		&compressedSize, TJSAMP_444 /* TJSAMP_422 */, 90 /* quality */, 0 /* flags */ );

	if ( compressResult != 0 )
	{
		LOG_TJ( "tjCompress2 error: %s for %s", tjGetErrorStr(), outputPath );
		tjFree( compressedBuf );
		tjDestroy( compressor );
		return false;
	}

	FILE * outputFile = fopen( outputPath, "wb" );
	if ( outputFile != NULL )
	{
		fwrite( compressedBuf, 1, compressedSize, outputFile );
		fclose( outputFile );
	}
	else
	{
		LOG_TJ( "Failed to open output file: %s", outputPath );
		tjFree( compressedBuf );
		tjDestroy( compressor );
		return false;
	}

	tjFree( compressedBuf );
	tjDestroy( compressor );
	return true;
}

// Alternative image loader using TurboJPEG — faster than stbi_load_from_memory()
unsigned char * DecodeJpegFromBuffer( const unsigned char * jpegData, const int dataSize, int * outWidth, int * outHeight )
{
	tjhandle decompressor = tjInitDecompress();
	int jpegW, jpegH, subsamp, colorspace;

	const int headerParseResult = tjDecompressHeader3( decompressor,
		(unsigned char*)jpegData, dataSize, &jpegW, &jpegH,
		&subsamp, &colorspace );

	if ( headerParseResult != 0 )
	{
		LOG_TJ( "TurboJpeg header decode failed: %s", tjGetErrorStr() );
		tjDestroy( decompressor );
		return nullptr;
	}

	const int bufferSize = jpegW * jpegH * 4;
	unsigned char * decodedBuffer = (unsigned char*)malloc( bufferSize );
	if ( decodedBuffer != nullptr )
	{
		const int decodeResult = tjDecompress2( decompressor,
			(unsigned char*)jpegData, dataSize, decodedBuffer,
			jpegW, jpegW * 4, jpegH, TJPF_RGBX, 0 /* flags */ );

		if ( decodeResult != 0 )
		{
			LOG_TJ( "TurboJpeg decode error: %s", tjGetErrorStr() );
			free( decodedBuffer );
			tjDestroy( decompressor );
			return nullptr;
		}

		tjDestroy( decompressor );
		*outWidth = jpegW;
		*outHeight = jpegH;
	}

	return decodedBuffer;
}

unsigned char * LoadJpegFromFile( const char * filePath, int * width, int * height )
{
	const int fileDescriptor = open( filePath, O_RDONLY );
	if ( fileDescriptor <= 0 )
	{
		return nullptr;
	}

	struct stat fileStat = {};
	if ( fstat( fileDescriptor, &fileStat ) == -1 )
	{
		LOG_TJ( "fstat failed on %s", filePath );
		close( fileDescriptor );
		return nullptr;
	}

	const unsigned char * mappedData = (unsigned char*)mmap(
		NULL, (size_t)fileStat.st_size, PROT_READ, MAP_SHARED, fileDescriptor, 0 );

	if ( mappedData == MAP_FAILED )
	{
		LOG_TJ( "mmap failed for %s (%d bytes): %s", filePath, (int)fileStat.st_size,
			strerror( errno ) );
		close( fileDescriptor );
		return nullptr;
	}

	LOG_TJ( "Mapped %s (%d bytes) at %p", filePath, (int)fileStat.st_size, mappedData );

	unsigned char * result = DecodeJpegFromBuffer( mappedData, (int)fileStat.st_size, width, height );

	close( fileDescriptor );
	munmap( (void*)mappedData, (size_t)fileStat.st_size );

	return result;
}

