bool UOUUDataTableLibrary::AddRowToDataTable(UDataTable* DataTable, FName RowName, FTableRowBase RowStruct)
{
	// This function should never be called directly; the actual implementation resides in Generic_AddRowToDataTable
	check(false);
	return false;
}

bool UOUUDataTableLibrary::RemoveRowFromDataTable(UDataTable* DataTable, FName RowName)
{
	if (!IsValid(DataTable) || !RowName.IsNone())
	{
		if (!DataTable->GetRowNames().Contains(RowName))
		{
			return false;
		}
	}

	DataTable->RemoveRow(RowName);
	return true;
}

DEFINE_FUNCTION(UOUUDataTableLibrary::execAddRowToDataTable)
{
	P_GET_OBJECT(UDataTable, TargetTable);
	P_GET_PROPERTY(FNameProperty, EntryName);
	Stack.StepCompiledIn<FStructProperty>(nullptr);
	void* StructData = Stack.MostRecentPropertyAddress;
	P_FINISH;

	FStructProperty* StructProperty = CastField<FStructProperty>(Stack.MostRecentProperty);
	bool bResult = false;

	if (!TargetTable)
	{
		FBlueprintExceptionInfo ErrorInfo(
			EBlueprintExceptionType::AccessViolation,
			INVTEXT("Invalid DataTable reference. Ensure the input table is valid.")
		);
		FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ErrorInfo);
	}
	else if (StructProperty && StructData)
	{
		UScriptStruct* InputStruct = StructProperty->Struct;
		const UScriptStruct* ExpectedStruct = TargetTable->GetRowStruct();

		const bool bIsCompatible = (InputStruct == ExpectedStruct) ||
			(InputStruct->IsChildOf(ExpectedStruct) && FStructUtils::TheSameLayout(InputStruct, ExpectedStruct));

		if (bIsCompatible)
		{
			P_NATIVE_BEGIN;
			bResult = Generic_AddRowToDataTable(TargetTable, EntryName, StructProperty, StructData);
			P_NATIVE_END;
		}
		else
		{
			FBlueprintExceptionInfo ErrorInfo(
				EBlueprintExceptionType::AccessViolation,
				INVTEXT("Type mismatch: the provided row data does not match the DataTable's expected structure.")
			);
			FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ErrorInfo);
		}
	}
	else
	{
		FBlueprintExceptionInfo ErrorInfo(
			EBlueprintExceptionType::AccessViolation,
			INVTEXT("Unable to resolve required parameters for AddRowToDataTable.")
		);
		FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ErrorInfo);
	}

	*(bool*)RESULT_PARAM = bResult;
}

bool UOUUDataTableLibrary::Generic_AddRowToDataTable(UDataTable* DataTable, FName RowName, FStructProperty* StructProp, void* RowPtr)
{
	if (!IsValid(DataTable) || !RowPtr || !StructProp)
		return false;

	if (DataTable->GetRowMap().Contains(RowName))
		return false;

	const UScriptStruct* RowStructType = DataTable->GetRowStruct();
	if (!RowStructType)
		return false;

	const FTableRowBase* SourceRow = StaticCast<FTableRowBase*>(RowPtr);
	DataTable->AddRow(RowName, *SourceRow);
	return true;
}

#include "Tetrahedron.h"
#include <Ziran/CS/Util/Debug.h>
#include <Eigen/Dense>

namespace ZIRAN {

template <class T>
void barycentricCoordinates(
    const Vector<T, 3>& point,
    const Vector<T, 3>& vertexA,
    const Vector<T, 3>& vertexB,
    const Vector<T, 3>& vertexC,
    const Vector<T, 3>& vertexD,
    Vector<T, 4>& coords)
{
    Matrix<T, 3, 3> M;
    M.col(0) = vertexA - vertexD;
    M.col(1) = vertexB - vertexD;
    M.col(2) = vertexC - vertexD;

    Vector<T, 3> bary_coords_abc = M.fullPivLu().solve(point - vertexD);
    coords.template segment<3>(0) = bary_coords_abc;
    coords(3) = (T)1.0 - bary_coords_abc.sum();

    ZIRAN_ASSERT((coords.array() >= (T)0).all(), coords.transpose());
    ZIRAN_ASSERT((coords.array() <= (T)1).all(), coords.transpose());
    ZIRAN_ASSERT(std::abs(coords.array().sum() - (T)1) < 1e-7, coords.transpose());

    Vector<T, 3> reconstructed_point = Vector<T, 3>::Zero();
    reconstructed_point += coords(0) * vertexA;
    reconstructed_point += coords(1) * vertexB;
    reconstructed_point += coords(2) * vertexC;
    reconstructed_point += coords(3) * vertexD;

    ZIRAN_ASSERT((point - reconstructed_point).squaredNorm() < 1e-7);
}

template void barycentricCoordinates<double>(
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 4, 1, 0, 4, 1>&);

template void barycentricCoordinates<float>(
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<float, 4, 1, 0, 4, 1>&);

} // namespace ZIRAN

#include "catch2/catch.hpp"
#include "block.hpp"
#include "command.hpp"
