// Helper function to parse a string into a Block
gs2::Block decodeBlock(const std::string &input) {
    std::vector<uint8_t> byteStream{input.begin(), input.end()};
    return gs2::Block::parseBytes(byteStream);
}

// Verify parsed commands match expected byte sequences
void validateParsing(const std::string &input, const std::vector<std::string> &expectedList) {
    auto block = decodeBlock(input);
    auto &commands = block.getCommands();
    REQUIRE(expectedList.size() == commands.size());
    for (size_t idx = 0; idx < expectedList.size(); ++idx) {
        std::vector<uint8_t> targetBytes(expectedList[idx].begin(), expectedList[idx].end());
        CHECK(targetBytes == commands[idx].getBytes());
    }
}

// Ensure parsing fails with expected exception type
void expectParseFailure(const std::string &input) {
    std::vector<uint8_t> byteStream{input.begin(), input.end()};
    CHECK_THROWS_AS(gs2::Block::parseBytes(byteStream), gs2::GS2Exception);
}

TEST_CASE("Code parsing validation") {
    // Standard text parsing
    validateParsing("Hello there", {"H", "e", "l", "l", "o", " ", "t", "h", "e", "r", "e"});

    // Unsigned byte push
    validateParsing("\x01\xee\x01\xdd", {"\x01\xee", "\x01\xdd"});

    // Signed short push
    validateParsing("\x02\xee\x01\x02\x11\x22", {"\x02\xee\x01", "\x02\x11\x22"});

    // Signed long push
    validateParsing("\x03\x01\x02\x03\x04\xbb", {"\x03\x01\x02\x03\x04", "\xbb"});

    // Single-character string pushes
    validateParsing("\x07\x32\x07\x42", {"\x07\x32", "\x07\x42"});

    // Multi-character string pushes
    validateParsing("\x04hello there\x05\x04\x05", {"\x04hello there\x05", "\x04\x05"});
    validateParsing("\x04gamma\x9b\x04knife\x9c\x04rattlesnake\x9d",
                    {"\x04gamma\x9b", "\x04knife\x9c", "\x04rattlesnake\x9d"});
    validateParsing("\x04???\x9e\x04!!!\x9f", {"\x04???\x9e", "\x04!!!\x9f"});

    // Implicit start of strings
    validateParsing("who\x05", {"\x04who\x05"});
    validateParsing("what\x06k", {"\x04what\x06", "k"});
    validateParsing("where\x9b??", {"\x04where\x9b", "?", "?"});
    validateParsing("why\x9c!!!", {"\x04why\x9c", "!", "!", "!"});
    validateParsing("how\x9d", {"\x04how\x9d"});
    validateParsing("which\x9e", {"\x04which\x9e"});
    validateParsing("\x01\x02\x03\x9f", {"\x04\x01\x02\x03\x9f"});

    // Invalid inputs that should throw exceptions
    expectParseFailure("\x01");
    expectParseFailure("\x02?");
    expectParseFailure("\x03???");
    expectParseFailure("\x04 blah blah blah");
    expectParseFailure("\x07");
    expectParseFailure("\x09");
}

TEST_CASE("Mode-specific parsing behavior") {
    // Line mode handling
    auto commands = decodeBlock("\x30Hey\x05?").getCommands();
    REQUIRE(commands.size() == 4);
    REQUIRE(commands[0].isBytes());
    CHECK(commands[0].getBytes() == std::vector<uint8_t>{ 0x2a });
    REQUIRE(commands[2].isBytes());
    CHECK(commands[2].getBytes() == std::vector<uint8_t>{ 0x34 });
    REQUIRE(commands[3].isBytes());
    CHECK(commands[3].getBytes() == std::vector<uint8_t>{ 0x54 });
    REQUIRE(commands[1].isBlock());
    auto innerBlock = commands[1].getBlock().getCommands();
    REQUIRE(innerBlock.size() == 2);
    REQUIRE(innerBlock[0].isBytes());
    CHECK(innerBlock[0].getBytes() == std::vector<uint8_t>{ 0x04, 'H', 'e', 'y', 0x05 });
    REQUIRE(innerBlock[1].isBytes());
    CHECK(innerBlock[1].getBytes() == std::vector<uint8_t>{ '?' });
}

TEST_CASE("Block structure parsing") {
    // Simple block construction
    auto commands = decodeBlock("\x08hey\x09").getCommands();
    REQUIRE(commands.size() == 2);
    REQUIRE(commands[1].isBytes());
    REQUIRE(commands[1].getBytes() == std::vector<uint8_t>{ 0 });
    REQUIRE(commands[0].isBlock());
    auto innerCmds = commands[0].getBlock().getCommands();
    REQUIRE(innerCmds.size() == 3);
    REQUIRE(innerCmds[0].isBytes());
    CHECK(innerCmds[0].getBytes() == std::vector<uint8_t>{ 'h' });
    REQUIRE(innerCmds[1].isBytes());
    CHECK(innerCmds[1].getBytes() == std::vector<uint8_t>{ 'e' });
    REQUIRE(innerCmds[2].isBytes());
    CHECK(innerCmds[2].getBytes() == std::vector<uint8_t>{ 'y' });

    // Deeply nested blocks
    commands = decodeBlock("\x08\x08\x08\x08").getCommands();
    for (int depth = 0; depth < 4; depth++) {
        REQUIRE(commands.size() == 2);
        REQUIRE(commands[1].isBytes());
        CHECK(commands[1].getBytes() == std::vector<uint8_t>{ 0 });
        REQUIRE(commands[0].isBlock());
        if (depth == 3) {
            REQUIRE(commands[0].getBlock().getCommands().empty());
        } else {
            commands = commands[0].getBlock().getCommands();
        }
    }

    // Filter block parsing
    commands = decodeBlock("\xff?!").getCommands();
    REQUIRE(commands.size() == 2);
    REQUIRE(commands[1].isBytes());
    CHECK(commands[1].getBytes() == std::vector<uint8_t>{ 0x35 });
    REQUIRE(commands[0].isBlock());
    auto filterInner = commands[0].getBlock().getCommands();
    REQUIRE(filterInner.size() == 2);
    REQUIRE(filterInner[0].isBytes());
    CHECK(filterInner[0].getBytes() == std::vector<uint8_t>{ '?' });
    REQUIRE(filterInner[1].isBytes());
    CHECK(filterInner[1].getBytes() == std::vector<uint8_t>{ '!' });

    // Map block parsing
    commands = decodeBlock("\xfe?!").getCommands();
    REQUIRE(commands.size() == 2);
    REQUIRE(commands[1].isBytes());
    CHECK(commands[1].getBytes() == std::vector<uint8_t>{ 0x34 });
    REQUIRE(commands[0].isBlock());
    auto mapInner = commands[0].getBlock().getCommands();
    REQUIRE(mapInner.size() == 2);
    REQUIRE(mapInner[0].isBytes());
    CHECK(mapInner[0].getBytes() == std::vector<uint8_t>{ '?' });
    REQUIRE(mapInner[1].isBytes());
    CHECK(mapInner[1].getBytes() == std::vector<uint8_t>{ '!' });
}

