		: m_engine_context(engine_context)
		, m_clip_allocator(engine_context.getAllocator())
		, m_audio_device(nullptr)
	{
		setupAudioProperties(engine_context.getAllocator());
		AudioScene::registerLuaAPI(m_engine_context.getState());
		m_audio_device = AudioDevice::create(m_engine_context);
		m_clip_allocator.create(AUDIO_CLIP_RESOURCE, m_engine_context.getResourceManager());
	}


	~AudioSystemImplementation()
	{
		AudioDevice::destroy(*m_audio_device);
		m_clip_allocator.destroy();
	}


	Engine& getEngineContext() override { return m_engine_context; }
	AudioDevice& getAudioDevice() override { return *m_audio_device; }
	ClipManager& getClipManagerReference() override { return m_clip_allocator; }


