	void releaseScene(IScene* scene_reference) override { AudioScene::destroyInstance(static_cast<AudioScene*>(scene_reference)); }


	ClipManager m_clip_allocator;
	Engine& m_engine_context;
	AudioDevice* m_audio_device;
};


