#include <vector>
#include <algorithm>

// Generate all possible subsets (power set) of the input array
void generateSubsets(int position, std::vector<int> &inputArray, std::vector<std::vector<int> > &result, std::vector<int> &currentSubset)
{
    if (position == inputArray.size())
    {
        result.push_back(currentSubset);
        return;
    }

    // Exclude current element
    generateSubsets(position + 1, inputArray, result, currentSubset);

    // Include current element
    currentSubset.push_back(inputArray[position]);
    generateSubsets(position + 1, inputArray, result, currentSubset);
    currentSubset.pop_back(); // backtrack
}

std::vector<std::vector<int> > Solution::subsets(std::vector<int> &A) {
    std::sort(A.begin(), A.end());
    std::vector<std::vector<int> > result;
    std::vector<int> currentSubset;
    generateSubsets(0, A, result, currentSubset);
    std::sort(result.begin(), result.end());
    return result;
}

#include <cstdlib>
#include <cstring>
#include <iostream>
#include <boost/asio.hpp>
using boost::asio::local::datagram_protocol;
enum { buffer_size = 8192 };
const char *socket_prefix = "/tmp/rclogger.";
int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: rclogger <socket_path>\n";
      return 1;
    }
    boost::asio::io_service service;
    datagram_protocol::endpoint server_endpoint(argv[1]);
    datagram_protocol::socket socket_obj(service);
    socket_obj.connect(server_endpoint);
    std::string client_socket_name = socket_prefix + std::to_string(::getpid());
    ::unlink(client_socket_name.c_str());     // NOTE: is it correct behavior?
    datagram_protocol::endpoint local_endpoint(client_socket_name);
    socket_obj.bind(local_endpoint);
//    std::cout << "Enter message: ";
    std::string input_data = "";
    std::string temp_line;
    while (std::getline(std::cin, temp_line))
        input_data += temp_line + "\n";
    if (input_data.length() > buffer_size)
        std::cerr << "Error: message to send exceeds maximum size!" << std::endl;
    socket_obj.send_to(boost::asio::buffer(input_data), server_endpoint);
    char response[buffer_size];
    size_t bytes_received = socket_obj.receive_from(
        boost::asio::buffer(response, buffer_size), local_endpoint);
    std::cout << "Reply is: ";
    std::cout.write(response, bytes_received);
    std::cout << "\n";
    socket_obj.close();
    ::unlink(client_socket_name.c_str());
  }
  catch (std::exception& err)
  {
    std::cerr << "Exception: " << err.what() << "\n";
  }
  return 0;
}

