namespace NNodeCmp {

bool IsComparableType(const TNode::EType kind) {
    switch (kind) {
        case TNode::String:
        case TNode::Int64:
        case TNode::Uint64:
        case TNode::Double:
        case TNode::Bool:
        case TNode::Null:
        case TNode::Undefined:
            return true;
        default:
            return false;
    }
}

bool operator<(const TNode& left, const TNode& right) {
    if (!left.GetAttributes().Empty() || !right.GetAttributes().Empty()) {
        ythrow TNode::TTypeError() << "Unsupported attributes comparison";
    }
    if (!IsComparableType(left.GetType()) || !IsComparableType(right.GetType())) {
        ythrow TNode::TTypeError() << "Unsupported types for comparison: " << left.GetType() << " with " << right.GetType();
    }
    if (left.GetType() != right.GetType()) {
        return left.GetType() < right.GetType();
    }

    switch (left.GetType()) {
        case TNode::String:
            return left.AsString() < right.AsString();
        case TNode::Int64:
            return left.AsInt64() < right.AsInt64();
        case TNode::Uint64:
            return left.AsUint64() < right.AsUint64();
        case TNode::Double:
            return left.AsDouble() < right.AsDouble();
        case TNode::Bool:
            return left.AsBool() < right.AsBool();
        case TNode::Null:
        case TNode::Undefined:
            return false;
        default:
            Y_FAIL("Unexpected type: %d", left.GetType());
    }
}

bool operator>(const TNode& left, const TNode& right) {
    return right < left;
}

bool operator<=(const TNode& left, const TNode& right) {
    return !(left > right);
}

bool operator>=(const TNode& left, const TNode& right) {
    return !(left < right);
}

} // namespace NNodeCmp

