#include <vector>
#include <algorithm>

class Solution {
public:
    bool searchMatrix(std::vector<std::vector<int>>& grid, int goal) {
        int rows = grid.size();
        int cols = grid[0].size();
        return findInSubmatrix(grid, 0, 0, rows - 1, cols - 1, goal);
    }

private:
    bool findInSubmatrix(std::vector<std::vector<int>>& grid, int r1, int c1, int r2, int c2, int goal) {
        // Base case: invalid submatrix bounds
        if (r1 > r2 || c1 > c2)
            return false;

        int range = std::min(r2 - r1, c2 - c1);
        int left = 0;
        int right = range;

        // Binary search along the diagonal of current submatrix
        while (left <= right) {
            int middle = (left + right) / 2;
            int value = grid[r1 + middle][c1 + middle];

            if (value == goal)
                return true;
            else if (value < goal)
                left = middle + 1;
            else
                right = middle - 1;
        }

        // Recursively search the two remaining submatrices
        return findInSubmatrix(grid, r1, c1 + left, r1 + right, c2, goal) ||
               findInSubmatrix(grid, r1 + left, c1, r2, c1 + right, goal);
    }
};

