// Write a relocation value without padding and return the number of bytes
// written.
static unsigned writeCompactReloc(uint8_t *Buf, const WasmRelocation &Rel,
                                  uint32_t Value) {
  switch (Rel.Type) {
  case R_WEBASSEMBLY_TYPE_INDEX_LEB:
  case R_WEBASSEMBLY_FUNCTION_INDEX_LEB:
  case R_WEBASSEMBLY_GLOBAL_INDEX_LEB:
  case R_WEBASSEMBLY_EVENT_INDEX_LEB:
  case R_WEBASSEMBLY_MEMORY_ADDR_LEB:
    return encodeULEB128(Value, Buf);
  case R_WEBASSEMBLY_TABLE_INDEX_SLEB:
  case R_WEBASSEMBLY_MEMORY_ADDR_SLEB:
    return encodeSLEB128(static_cast<int32_t>(Value), Buf);
  default:
    llvm_unreachable("unexpected relocation type");
  }
}

static unsigned getRelocSizePadded(const WasmRelocation &Rel) {
  switch (Rel.Type) {
  case R_WEBASSEMBLY_TYPE_INDEX_LEB:
  case R_WEBASSEMBLY_FUNCTION_INDEX_LEB:
  case R_WEBASSEMBLY_GLOBAL_INDEX_LEB:
  case R_WEBASSEMBLY_EVENT_INDEX_LEB:
  case R_WEBASSEMBLY_MEMORY_ADDR_LEB:
  case R_WEBASSEMBLY_TABLE_INDEX_SLEB:
  case R_WEBASSEMBLY_MEMORY_ADDR_SLEB:
    return 5;
  default:
    llvm_unreachable("unexpected relocation type");
  }
}

static unsigned getRelocSize(const WasmRelocation &Rel, uint32_t Value) {
  uint8_t Buf[5];
  return writeCompactReloc(Buf, Rel, Value);
}

// Relocations of type LEB and SLEB in the code section are padded to 5 bytes
// so that a fast linker can blindly overwrite them without needing to worry
// about the number of bytes needed to encode the values.
// However, for optimal output the code section can be compressed to remove
// the padding then outputting non-relocatable files.
// In this case we need to perform a size calculation based on the value at each
// relocation.  At best we end up saving 4 bytes for each relocation entry.
//
// This function only computes the final output size.  It must be called
// before getSize() is used to calculate layout of the code section.
void InputFunction::calculateSize() {
  if (!File || !Config->CompressRelocations)
    return;

  LLVM_DEBUG(dbgs() << "calculateSize: " << getName() << "\n");

  const uint8_t *SecBegin = File->CodeSection->Content.data();
  const uint8_t *FuncBegin = SecBegin + getInputSectionOffset();
  uint32_t FuncSizeLength;
  decodeULEB128(FuncBegin, &FuncSizeLength);

  uint32_t Start = getInputSectionOffset();
  uint32_t End = Start + Function->Size;
  uint32_t LastRelocEnd = Start + FuncSizeLength;

  for (const WasmRelocation &Rel : Relocations) {
    LLVM_DEBUG(dbgs() << "  region: " << (Rel.Offset - LastRelocEnd) << "\n");
    CompressedFuncSize += Rel.Offset - LastRelocEnd;
    CompressedFuncSize += getRelocSize(Rel, File->calcNewValue(Rel));
    LastRelocEnd = Rel.Offset + getRelocSizePadded(Rel);
  }

  LLVM_DEBUG(dbgs() << "  final region: " << (End - LastRelocEnd) << "\n");
  CompressedFuncSize += End - LastRelocEnd;

  // Now we know how long the resulting function is we can add the encoding
  // of its length
  uint8_t Buf[5];
  CompressedSize = CompressedFuncSize + encodeULEB128(CompressedFuncSize, Buf);

  LLVM_DEBUG(dbgs() << "  calculateSize original: " << Function->Size << "\n");
  LLVM_DEBUG(dbgs() << "  calculateSize  new: " << CompressedSize << "\n");
}

// Override the default writeTo method so that we can (optionally) write the
// compressed version of the function.
void InputFunction::writeTo(uint8_t *Buffer) const {
  if (!File || !Config->CompressRelocations)
    return InputChunk::writeTo(Buffer);

  Buffer += OutputOffset;
  uint8_t *Original = Buffer;
  (void)Original;

  const uint8_t *SecBegin = File->CodeSection->Content.data();
  const uint8_t *FuncBegin = SecBegin + getInputSectionOffset();
  const uint8_t *FuncEnd = FuncBegin + Function->Size;

  uint32_t Count;
  decodeULEB128(FuncBegin, &Count);
  FuncBegin += Count;

  LLVM_DEBUG(dbgs() << "write func: " << getName() << "\n");

  Buffer += encodeULEB128(CompressedFuncSize, Buffer);
  const uint8_t *LastRelocEnd = FuncBegin;

  for (const WasmRelocation &Rel : Relocations) {
    unsigned ChunkSize = (SecBegin + Rel.Offset) - LastRelocEnd;
    LLVM_DEBUG(dbgs() << "  write chunk: " << ChunkSize << "\n");
    memcpy(Buffer, LastRelocEnd, ChunkSize);
    Buffer += ChunkSize;
    Buffer += writeCompactReloc(Buffer, Rel, File->calcNewValue(Rel));
    LastRelocEnd = SecBegin + Rel.Offset + getRelocSizePadded(Rel);
  }

  unsigned FinalChunkSize = FuncEnd - LastRelocEnd;
  LLVM_DEBUG(dbgs() << "  write final chunk: " << FinalChunkSize << "\n");
  memcpy(Buffer, LastRelocEnd, FinalChunkSize);

  LLVM_DEBUG(dbgs() << "  total: " << (Buffer + FinalChunkSize - Original) << "\n");
}

