// HTTP response parser
static size_t ParseIntegerFromText(const char * text_start, const char * text_end)
{
    size_t accumulated_value = 0;
    while(text_start < text_end && isdigit(text_start[0]))
    {
        accumulated_value = (accumulated_value * 10) + (text_start[0] - '0');
        text_start++;
    }
    return accumulated_value;
}
bool CASC_MIME_HTTP::IsResponseFullyReceived(const char * http_response, size_t response_size)
{
    const char * content_length_field;
    const char * content_start_field;
    // Prevent re-parsing of already processed responses
    if(response_valid == 0 && response_size > 8)
    {
        // Verify the start of the HTTP response
        if(!strncmp(http_response, "HTTP/1.1", 8))
        {
            // Locate the beginning of the body (double CRLF)
            if((content_start_field = strstr(http_response, "\r\n\r\n")) != NULL)
            {
                // Look for the Content-Length header
                if((content_length_field = strstr(http_response, "Content-Length: ")) != NULL)
                {
                    // Ensure Content-Length appears before the body
                    if(content_length_field < content_start_field)
                    {
                        // Populate response metadata cache
                        response_valid = 0x48545450;    // 'HTTP'
                        content_offset = (content_start_field + 4) - http_response;
                        content_length = ParseIntegerFromText(content_length_field + 16, content_start_field);
                        total_length = content_offset + content_length;
                    }
                }
            }
        }
    }
    // Determine completeness based on known expected length
    return ((response_valid != 0) && (total_length == response_size));
}
