// MIME blob handler
CASC_MIME_BLOB::CASC_MIME_BLOB(char * blob_ptr, char * blob_end)
{
    ptr = blob_ptr;
    end = blob_end;
}
CASC_MIME_BLOB::~CASC_MIME_BLOB()
{
    ptr = end = NULL;
}
char * CASC_MIME_BLOB::FetchNextLine()
{
    char * line_start = ptr;
    while(ptr < end)
    {
        // Each line must terminate with CR LF
        if(ptr[0] == 0x0D && ptr[1] == 0x0A)
        {
            // Check for line continuation (tab or space)
            if(ptr[2] == 0x09 || ptr[2] == 0x20)
            {
                ptr = ptr + 2;
                continue;
            }
            // Terminate current line and advance pointer
            ptr[0] = 0;
            ptr[1] = 0;
            ptr = ptr + 2;
            return line_start;
        }
        // Advance to next character
        ptr++;
    }
    // No complete line found
    return NULL;
}
