// MIME element implementation
CASC_MIME_ELEMENT::CASC_MIME_ELEMENT()
{
    memset(this, 0, sizeof(CASC_MIME_ELEMENT));
}
CASC_MIME_ELEMENT::~CASC_MIME_ELEMENT()
{
    // Clean up child and sibling elements
    if(folder.pChild != NULL)
        delete folder.pChild;
    folder.pChild = NULL;
    if(folder.pNext != NULL)
        delete folder.pNext;
    folder.pNext = NULL;
    // Release data buffer
    if(data.begin != NULL)
        CASC_FREE(data.begin);
    data.begin = NULL;
}
unsigned char * CASC_MIME_ELEMENT::TransferOwnership(size_t * out_data_length)
{
    unsigned char * transferred_data = data.begin;
    size_t transferred_length = data.length;
    // Reset internal state without freeing
    data.begin = NULL;
    data.length = 0;
    // Output length if requested
    if(out_data_length != NULL)
        out_data_length[0] = transferred_length;
    return transferred_data;
}
DWORD CASC_MIME_ELEMENT::Initialize(char * mime_buffer_start, char * mime_buffer_end, const char * boundary_marker)
{
    CASC_MIME_ENCODING TransferEncoding = MimeEncodingTextPlain;
    CASC_MIME_BLOB mime_parser(mime_buffer_start, mime_buffer_end);
    CASC_MIME_HTTP HttpInfo;
    size_t boundary_start_len;
    size_t boundary_end_len;
    char * current_line;
    char boundary_prefix[MAX_LENGTH_BOUNDARY + 2];
    char boundary_suffix[MAX_LENGTH_BOUNDARY + 4];
    DWORD error_code = ERROR_SUCCESS;
    bool has_mime_version = false;
    // Special case for HTTP: bypass parsing and extract raw data directly
    if(HttpInfo.IsResponseFullyReceived(mime_buffer_start, (mime_buffer_end - mime_buffer_start)))
    {
        if((data.begin = CASC_ALLOC<BYTE>(HttpInfo.content_length)) == NULL)
            return ERROR_NOT_ENOUGH_MEMORY;

        memcpy(data.begin, mime_buffer_start + HttpInfo.content_offset, HttpInfo.content_length);
        data.length = HttpInfo.content_length;
        return ERROR_SUCCESS;
    }
    // Clear boundary storage
    boundary[0] = 0;
    // Process headers line by line until body starts
    while((current_line = mime_parser.FetchNextLine()) != NULL)
    {
        // Empty line indicates end of headers
        if(current_line[0] == 0)
        {
            mime_parser.ptr = current_line + 2;
            break;
        }
        // Root nodes require MIME-Version header
        if(boundary_marker == NULL && has_mime_version == false)
        {
            if(!strcmp(current_line, "MIME-Version: 1.0"))
            {
                has_mime_version = true;
                continue;
            }
            if(!strcmp(current_line, "HTTP/1.1 200 OK"))
            {
                has_mime_version = true;
                continue;
            }
        }
        // Extract transfer encoding
        if(!strncmp(current_line, "Content-Transfer-Encoding: ", 27))
        {
            IdentifyEncoding(current_line + 27, TransferEncoding);
            continue;
        }
        // Extract boundary from Content-Type
        if(!strncmp(current_line, "Content-Type: ", 14))
        {
            IdentifyBoundary(current_line + 14);
            continue;
        }
    }
    // Proceed only if valid MIME structure detected
    if(boundary_marker != NULL || has_mime_version == true)
    {
        // Handle multipart content with boundaries
        if(boundary[0])
        {
            CASC_MIME_ELEMENT * previous_element = NULL;
            CASC_MIME_ELEMENT * current_element;
            CASC_MIME_BLOB sub_content(mime_parser.ptr, NULL);
            // Build boundary prefix (without trailing newline)
            boundary_start_len = CascStrPrintf(boundary_prefix, _countof(boundary_prefix), "--%s", boundary);
            error_code = ERROR_SUCCESS;
            // Validate start of boundary
            if(memcmp(sub_content.ptr, boundary_prefix, boundary_start_len))
                return ERROR_BAD_FORMAT;
            sub_content.ptr += boundary_start_len;
            // Build boundary suffix
            boundary_end_len = CascStrPrintf(boundary_suffix, _countof(boundary_suffix), "--%s--\r\n", boundary);
            sub_content.end = strstr(sub_content.ptr, boundary_suffix);
            if(sub_content.end == NULL)
                return ERROR_BAD_FORMAT;
            // Split into individual MIME parts
            while(sub_content.ptr < sub_content.end)
            {
                char * next_boundary;
                // Expect CRLF at start of part
                if(sub_content.ptr[0] != 0x0D || sub_content.ptr[1] != 0x0A)
                    return ERROR_BAD_FORMAT;
                sub_content.ptr += 2;
                // Find next boundary marker
                next_boundary = strstr(sub_content.ptr, boundary_prefix);
                if(next_boundary == NULL)
                    return ERROR_BAD_FORMAT;
                // Create and load child element
                current_element = AllocateAndLoadElement(sub_content.ptr, next_boundary - 2, boundary_prefix);
                if(current_element == NULL)
                {
                    error_code = GetCascError();
                    break;
                }
                // Link into element tree
                if(folder.pChild == NULL)
                    folder.pChild = current_element;
                if(previous_element != NULL)
                    previous_element->folder.pNext = current_element;
                previous_element = current_element;
                // Move past current boundary
                sub_content.ptr = next_boundary + boundary_start_len;
            }
        }
        else
        {
            CASC_MIME_BLOB content_area(mime_parser.ptr, NULL);
            unsigned char * decoded_data;
            size_t decoded_length = 0;
            size_t raw_size;
            // Determine end of content based on boundary presence
            if(boundary_marker != NULL)
            {
                content_area.end = strstr(content_area.ptr, boundary_marker);
                if(content_area.end == NULL)
                    return ERROR_BAD_FORMAT;
                if((content_area.ptr + 2) >= content_area.end)
                    return ERROR_BAD_FORMAT;
                content_area.end -= 2;
            }
            else
            {
                content_area.end = mime_buffer_end - 2;
                if(content_area.end[0] != 0x0D || content_area.end[1] != 0x0A)
                    return ERROR_BAD_FORMAT;
                if((content_area.ptr + 2) >= content_area.end)
                    return ERROR_BAD_FORMAT;
            }
            // Allocate buffer for decoded output
            raw_size = (content_area.end - content_area.ptr);
            decoded_data = CASC_ALLOC<unsigned char>(raw_size);
            if(decoded_data != NULL)
            {
                // Perform decoding based on specified encoding
                switch(TransferEncoding)
                {
                    case MimeEncodingTextPlain:
                        error_code = DecodeTextPlain(content_area.ptr, content_area.end, decoded_data, &decoded_length);
                        break;
                    case MimeEncodingQuotedPrintable:
                        error_code = DecodeQuotedPrintable(content_area.ptr, content_area.end, decoded_data, &decoded_length);
                        break;
                    case MimeEncodingBase64:
                        error_code = DecodeBase64(content_area.ptr, content_area.end, decoded_data, &decoded_length);
                        break;

                    default:;
                        // suppress unused warning
                }
                // Cleanup on failure
                if(error_code != ERROR_SUCCESS)
                {
                    CASC_FREE(decoded_data);
                    decoded_data = NULL;
                    decoded_length = 0;
                }
            }
            else
            {
                error_code = ERROR_NOT_ENOUGH_MEMORY;
            }
            // Assign final data buffer
            data.begin = decoded_data;
            data.length = decoded_length;
        }
    }
    else
    {
        error_code = ERROR_NOT_SUPPORTED;
    }
    return error_code;
}
#ifdef _DEBUG
#define MAX_DEPTH 0x10
void CASC_MIME_ELEMENT::Display(size_t depth, size_t index)
{
    char Indent[(MAX_DEPTH * 4) + 0x20 + 1] = {0};
    size_t indent_spaces;
    // Generate indentation
    indent_spaces = (depth < MAX_DEPTH) ? (depth * 4) : (MAX_DEPTH * 4);
    memset(Indent, ' ', indent_spaces);
    // Print node info
    indent_spaces = printf("%s* [%u]: ", Indent, (int)index);
    memset(Indent, ' ', indent_spaces);
    // Distinguish between folder and data nodes
    if(folder.pChild != NULL)
    {
        printf("Folder node (boundary: %s)\n", boundary);
        folder.pChild->Display(depth + 1, 0);
    }
    else
    {
        char visible_data[0x20] = {0};
        for(size_t i = 0; (i < data.length && i < _countof(visible_data) - 1); i++)
        {
            if(0x20 <= data.begin[i] && data.begin[i] <= 0x7F)
                visible_data[i] = data.begin[i];
            else
                visible_data[i] = '.';
        }
        printf("Data node (%u bytes): \"%s\"\n", (int)data.length, visible_data);
    }
    // Recursively display siblings
    if(folder.pNext != NULL)
    {
        folder.pNext->Display(depth, index + 1);
    }
}
#endif
CASC_MIME_ELEMENT * CASC_MIME_ELEMENT::AllocateAndLoadElement(char * a_mime_data, char * a_mime_data_end, const char * boundary_prefix)
{
    CASC_MIME_ELEMENT * new_element;
    DWORD error_code = ERROR_NOT_ENOUGH_MEMORY;
    // Allocate new element
    if((new_element = new CASC_MIME_ELEMENT()) != NULL)
    {
        // Initialize element
        error_code = new_element->Initialize(a_mime_data, a_mime_data_end, boundary_prefix);
        if(error_code == ERROR_SUCCESS)
            return new_element;
        // Free on failure
        delete new_element;
    }
    SetCascError(error_code);
    return NULL;
}
bool CASC_MIME_ELEMENT::IdentifyEncoding(const char * line, CASC_MIME_ENCODING & Encoding)
{
    if(!_stricmp(line, "base64"))
    {
        Encoding = MimeEncodingBase64;
        return true;
    }
    if(!_stricmp(line, "quoted-printable"))
    {
        Encoding = MimeEncodingQuotedPrintable;
        return true;
    }
    // Unknown encoding type
    return false;
}
bool CASC_MIME_ELEMENT::IdentifyBoundary(const char * line)
{
    const char * start;
    const char * finish;
    // Locate start of boundary value
    if((start = strstr(line, "boundary=\"")) != NULL)
    {
        start = start + 10;

        // Locate end quote
        if((finish = strchr(start, '\"')) != NULL)
        {
            CascStrCopy(boundary, _countof(boundary), start, finish - start);
            return true;
        }
    }
    return false;
}
DWORD CASC_MIME_ELEMENT::DecodeTextPlain(char * source_begin, char * source_end, unsigned char * dest_buffer, size_t * out_length)
{
    size_t copy_size = (size_t)(source_end - source_begin);
    // Validation checks
    assert(source_begin && source_end);
    assert(source_end > source_begin);
    // Direct memory copy
    memcpy(dest_buffer, source_begin, copy_size);
    // Report result size
    if(out_length != NULL)
        out_length[0] = copy_size;
    return ERROR_SUCCESS;
}
DWORD CASC_MIME_ELEMENT::DecodeQuotedPrintable(char * source_begin, char * source_end, unsigned char * dest_buffer, size_t * out_length)
{
    unsigned char * original_dest = dest_buffer;
    char * scan_ptr;
    DWORD error_code;
    // Input validation
    assert(source_begin && source_end);
    assert(source_end > source_begin);
    // Process encoded data
    for(scan_ptr = source_begin; scan_ptr < source_end; )
    {
        // Handle escape sequences
        if(scan_ptr[0] == '=')
        {
            // Soft line break
            if(scan_ptr[1] == 0x0D && scan_ptr[2] == 0x0A)
            {
                scan_ptr += 3;
                continue;
            }
            // Hexadecimal escape
            error_code = BinaryFromString(scan_ptr + 1, 2, dest_buffer);
            if(error_code != ERROR_SUCCESS)
                return error_code;
            scan_ptr += 3;
            dest_buffer++;
            continue;
        }
        else
        {
            *dest_buffer++ = (unsigned char)(*scan_ptr++);
        }
    }
    if(out_length != NULL)
        out_length[0] = (size_t)(dest_buffer - original_dest);
    return ERROR_SUCCESS;
}
DWORD CASC_MIME_ELEMENT::DecodeBase64(char * source_begin, char * source_end, unsigned char * dest_buffer, size_t * out_length)
{
    unsigned char * original_dest = dest_buffer;
    DWORD BitBuffer = 0;
    DWORD BitCount = 0;
    BYTE CurrentByte;
    // One-time initialization of decoding table
    if(Base64DecodingTable[0] == 0)
    {
        // Mark all entries as invalid initially
        memset(Base64DecodingTable, BASE64_INVALID_CHAR, sizeof(Base64DecodingTable));
        // Mark whitespace characters
        for(BYTE i = 1; i <= 0x20; i++)
            Base64DecodingTable[i] = BASE64_WHITESPACE_CHAR;
        // Populate valid character mappings
        for(BYTE i = 0; Base64EncodingTable[i] != 0; i++)
        {
            CurrentByte = Base64EncodingTable[i];
            Base64DecodingTable[CurrentByte] = i;
        }
    }
    // Perform base64 decoding
    while(source_begin < source_end && source_begin[0] != '=')
    {
        // Bounds check
        if(source_begin[0] >= sizeof(Base64DecodingTable))
            return ERROR_BAD_FORMAT;
        if((CurrentByte = Base64DecodingTable[*source_begin++]) == BASE64_INVALID_CHAR)
            return ERROR_BAD_FORMAT;
        if(CurrentByte == BASE64_WHITESPACE_CHAR)
            continue;
        // Accumulate bits
        BitBuffer = (BitBuffer << 6) | CurrentByte;
        BitCount += 6;
        // Output full bytes
        while(BitCount >= 8)
        {
            BitCount -= 8;
            CurrentByte = (BYTE)(BitBuffer >> BitCount);
            BitBuffer &= (1 << BitCount) - 1;
            *dest_buffer++ = CurrentByte;
        }
    }
    // Report decoded length
    if(out_length != NULL)
        out_length[0] = (dest_buffer - original_dest);
    return ERROR_SUCCESS;
}
