// Top-level MIME handler
CASC_MIME::CASC_MIME()
{}
CASC_MIME::~CASC_MIME()
{}
unsigned char * CASC_MIME::TransferOwnership(size_t * out_length)
{
    CASC_MIME_ELEMENT * current_node = &root;
    unsigned char * extracted_data;
    // Try root first
    if((extracted_data = root.TransferOwnership(out_length)) != NULL)
        return extracted_data;
    // Fall back to first child
    current_node = root.GetChild();
    if(current_node && (extracted_data = current_node->TransferOwnership(out_length)) != NULL)
        return extracted_data;
    // No data available
    if(out_length != NULL)
        out_length[0] = 0;
    return NULL;
}
DWORD CASC_MIME::Initialize(char * data, size_t size)
{
    // Reset root node
    memset(&root, 0, sizeof(CASC_MIME_ELEMENT));
    // Load root element from input
    return root.Initialize(data, data + size);
}
DWORD CASC_MIME::Initialize(LPCTSTR filename)
{
    char * file_data;
    DWORD file_size = 0;
    DWORD error_code = ERROR_SUCCESS;
    // Load file into memory
    file_data = (char *)LoadFileToMemory(filename, &file_size);
    if(file_data != NULL)
    {
        error_code = Initialize(file_data, file_size);
        CASC_FREE(file_data);
    }
    else
    {
        error_code = GetCascError();
    }
    return error_code;
}
