class sqlrconfigs {
private:
	sqlrconfig *config;
	dynamiclib *loader;
	char const *execDir;

public:
	sqlrconfigs(sqlrpaths *paths);
	~sqlrconfigs();

	void getEnabledIds(char const *urlList, linkedlist<char*> *idList);
	sqlrconfig *load(char const *urlList, char const *instanceId);

private:
	void loadConfig(char const *moduleName);
};

sqlrconfigs::sqlrconfigs(sqlrpaths *paths) {
	debugFunction();
	execDir = paths->getLibExecDir();
	config = nullptr;
	loader = nullptr;
}

sqlrconfigs::~sqlrconfigs() {
	debugFunction();
	delete config;
	delete loader;
}

void sqlrconfigs::getEnabledIds(char const *urlList, linkedlist<char*> *idList) {
	debugFunction();

	// Split comma-separated URLs into array
	char **urlArray = nullptr;
	uint64_t urlCount = 0;
	charstring::split(urlList, ",", true, &urlArray, &urlCount);

	for (uint64_t idx = 0; idx < urlCount; ++idx) {
		char const *currentUrl = urlArray[idx];

		// Extract protocol part (e.g., "file:" from "file:/path")
		char *protocol = nullptr;
		char const *colonPos = charstring::findFirst(currentUrl, ':');
		if (colonPos) {
			protocol = charstring::duplicate(currentUrl, colonPos - currentUrl);
		}

		// Attempt to load plugin matching the protocol
		if (protocol) {
			loadConfig(protocol);
			delete[] protocol;
		}

		// Fallback to default XML parser if previous attempt failed
		if (!config) {
			loadConfig("xml");
		}

		// Retrieve enabled IDs using loaded config
		if (config) {
			config->getEnabledIds(currentUrl, idList);
		}

		// Reset state for next iteration
		delete config;
		config = nullptr;
		delete loader;
		loader = nullptr;
	}

	// Deallocate URL array
	for (uint64_t i = 0; i < urlCount; ++i) {
		delete[] urlArray[i];
	}
	delete[] urlArray;
}

sqlrconfig *sqlrconfigs::load(char const *urlList, char const *instanceId) {
	debugFunction();

	// Validate inputs
	if (charstring::isNullOrEmpty(urlList) || charstring::isNullOrEmpty(instanceId)) {
		return nullptr;
	}

	debugPrintf("urls: %s\n", urlList);
	debugPrintf("id: %s\n", instanceId);

	// Parse input URLs
	char **urlArray = nullptr;
	uint64_t urlCount = 0;
	charstring::split(urlList, ",", true, &urlArray, &urlCount);

	for (uint64_t idx = 0; idx < urlCount; ++idx) {
		char const *currentUrl = urlArray[idx];
		debugPrintf("    url: %s\n", currentUrl);

		// Extract protocol
		char *protocol = nullptr;
		char const *colonPos = charstring::findFirst(currentUrl, ':');
		if (colonPos) {
			protocol = charstring::duplicate(currentUrl, colonPos - currentUrl);
		}

		// Try loading protocol-specific config module
		if (protocol) {
			loadConfig(protocol);
			delete[] protocol;
		}

		// Fall back to XML parser if needed
		if (!config) {
			loadConfig("xml");
		}

		// Attempt to load configuration for given ID
		if (config && config->load(currentUrl, instanceId)) {
			break; // Success — stop searching
		} else {
			delete config;
			config = nullptr;
		}
	}

	// Cleanup URL array
	for (uint64_t i = 0; i < urlCount; ++i) {
		delete[] urlArray[i];
	}
	delete[] urlArray;

	// Report failure if no config found
	if (!config) {
		stderror.printf("Couldn't find id %s.\n", instanceId);
	}

	return config;
}

void sqlrconfigs::loadConfig(char const *module) {
	debugFunction();
	debugPrintf("loading config: %s\n", module);

#ifdef SQLRELAY_ENABLE_SHARED
	stringbuffer moduleName;
	moduleName.append(execDir);
	moduleName.append(SQLR);
	moduleName.append("config_");
	moduleName.append(module)->append(".")->append(SQLRELAY_MODULESUFFIX);

	loader = new dynamiclib();
	if (!loader->open(moduleName.getString(), true, true)) {
		debugPrintf("failed to load config module: %s\n", module);
		char *err = loader->getError();
		debugPrintf("%s\n", err);
		delete[] err;
		delete loader;
		loader = nullptr;
		return;
	}

	stringbuffer funcName;
	funcName.append("new_sqlrconfig_")->append(module);
	sqlrconfig *(*factoryFunc)() =
		(sqlrconfig *(*)()) loader->getSymbol(funcName.getString());

	if (!factoryFunc) {
		debugPrintf("failed to create config: %s\n", module);
		char *err = loader->getError();
		debugPrintf("%s\n", err);
		delete[] err;
		loader->close();
		delete loader;
		loader = nullptr;
		return;
	}

	config = (*factoryFunc)();
#else
	#include "sqlrconfigassignments.cpp"
	{
		config = nullptr;
	}
#endif
}

#include <BladePCH.h>
#include <utility/StringTable.h>

namespace Blade
{
    /************************************************************************/
    /*                                                                      */
    /************************************************************************/
    /////////////////////////////////////////////////////////////////////////
    tchar* StringTable::loadStrings(IOBuffer& dataStream, StringInfoList& metadata, uint32& entryCount, uint32& totalBytes, IPool* allocator/* = Memory::getResourcePool() */)
    {
        if( allocator == NULL )
        {
            assert(false);
            return NULL;
        }

        entryCount = 0;
        totalBytes = 0;

        dataStream.read(&entryCount);
        dataStream.read(&totalBytes);

        if( entryCount == 0 || totalBytes == 0 )
            return NULL;

        metadata.create(entryCount);

        IOBuffer tempBuffer;
        for(uint32 index = 0; index < entryCount; ++index)
        {
            // Convert UTF-8 encoded string to wide string representation
            TString localString;
            dataStream.readTString(localString);
            tempBuffer.writeTStringRAW(localString);

            metadata[index].offset = (index == 0 ? 0 : metadata[index-1].offset + metadata[index-1].length + 1);
            metadata[index].length = (uint32)localString.size();
        }

        assert(dataStream.eof());
        totalBytes = (uint32)tempBuffer.tell();

        tchar* stringData = (tchar*)allocator->allocate( (size_t)totalBytes );
        std::memcpy(stringData, tempBuffer.getData(), (size_t)totalBytes );

        return stringData;
    }

    /////////////////////////////////////////////////////////////////////////
    tchar* StringTable::loadStrings(const HSTREAM& fileStream, StringInfoList& metadata, uint32& entryCount, uint32& totalBytes, IPool* allocator/* = Memory::getResourcePool()*/)
    {
        if( fileStream != NULL && allocator != NULL && (fileStream->getAccessMode() & IStream::AM_READ) )
        {
            entryCount = 0;
            totalBytes = 0;

            fileStream->readAtom(entryCount);
            fileStream->readAtom(totalBytes);

            if( entryCount == 0 || totalBytes == 0 )
                return NULL;

            IOBuffer intermediateBuffer;
            intermediateBuffer.reserve( (size_t)totalBytes + sizeof(uint32)*2 );

            intermediateBuffer.write(&entryCount);
            intermediateBuffer.write(&totalBytes);

            fileStream->readData(intermediateBuffer.getCurrentData(), totalBytes);
            intermediateBuffer.rewind();

            return StringTable::loadStrings(intermediateBuffer, metadata, entryCount, totalBytes, allocator);
        }
        return NULL;
    }

    /////////////////////////////////////////////////////////////////////////
    bool StringTable::saveStrings(IOBuffer& outputBuffer, const TString* sourceArray, uint32 count)
    {
        if( sourceArray == NULL && count != 0 )
        {
            assert(false);
            return false;
        }

        // Convert strings to UTF-8 format
        IOBuffer temporaryStorage;
        for(size_t position = 0; position < count; ++position)
            temporaryStorage.writeTString( sourceArray[position] );

        outputBuffer.write(&count);
        uint32 byteCount = (uint32)temporaryStorage.tell();
        outputBuffer.write(&byteCount);
        outputBuffer.writeData(temporaryStorage.getData(), byteCount);

        return true;
    }

    /////////////////////////////////////////////////////////////////////////
    bool StringTable::saveStrings(const HSTREAM& outputStream, const TString* sourceArray, uint32 count)
    {
        IOBuffer intermediateBuffer;
        if( outputStream != NULL && (outputStream->getAccessMode() & IStream::AM_WRITE) && 
            StringTable::saveStrings(intermediateBuffer, sourceArray, count) )
            return intermediateBuffer.saveToStream(outputStream);

        return false;
    }

    /************************************************************************/
    /*                                                                      */
    /************************************************************************/
    /////////////////////////////////////////////////////////////////////////
    bool StringTableCache::store(const TStringParam& configuration, StringTable& targetTable, IPool* allocator/* = Memory::getResourcePool()*/)
    {
        IOBuffer buffer;
        if( !StringTable::saveStrings(buffer, configuration) )
            return false;

        buffer.rewind();
        return StringTable::loadStrings(buffer, targetTable, allocator);
    }

}//namespace Blade

