// Color Curve Implementation
UNiagaraDataInterfaceColorCurve::UNiagaraDataInterfaceColorCurve(FObjectInitializer const& ObjectInitializer)
	: Super(ObjectInitializer)
{
	GenerateLookupTable();
}

void UNiagaraDataInterfaceColorCurve::PostInitProperties()
{
	Super::PostInitProperties();
	if (HasAnyFlags(RF_ClassDefaultObject))
	{
		FNiagaraTypeRegistry::Register(FNiagaraTypeDefinition(GetClass()), true, false, false);
	}
	GenerateLookupTable();
}

void UNiagaraDataInterfaceColorCurve::PostLoad()
{
	Super::PostLoad();
	GenerateLookupTable();
}

#if WITH_EDITOR
void UNiagaraDataInterfaceColorCurve::PostEditChangeProperty(struct FPropertyChangedEvent& PropertyChangedEvent)
{
	Super::PostEditChangeProperty(PropertyChangedEvent);
	if (PropertyChangedEvent.Property && PropertyChangedEvent.Property->GetFName() == GET_MEMBER_NAME_CHECKED(UNiagaraDataInterfaceColorCurve, SourceCurve))
	{
		UCurveLinearColor* ImportedCurve = Cast<UCurveLinearColor>(SourceCurve.TryLoad());
		if (ImportedCurve)
		{
			Modify();
			RedChannelCurve = ImportedCurve->FloatCurves[0];
			GreenChannelCurve = ImportedCurve->FloatCurves[1];
			BlueChannelCurve = ImportedCurve->FloatCurves[2];
			AlphaChannelCurve = ImportedCurve->FloatCurves[3];
		}
		GenerateLookupTable();
	}
}
#endif

void UNiagaraDataInterfaceColorCurve::GenerateLookupTable()
{
	ShaderLUT.Empty();
	for (uint32 Index = 0; Index < LookupTableSize; ++Index)
	{
		float T = static_cast<float>(Index) / static_cast<float>(LookupTableSize);
		FLinearColor Sample(
			RedChannelCurve.Eval(T),
			GreenChannelCurve.Eval(T),
			BlueChannelCurve.Eval(T),
			AlphaChannelCurve.Eval(T)
		);
		ShaderLUT.Add(Sample.R);
		ShaderLUT.Add(Sample.G);
		ShaderLUT.Add(Sample.B);
		ShaderLUT.Add(Sample.A);
	}
	GPUBufferNeedsUpdate = true;
}

bool UNiagaraDataInterfaceColorCurve::CopyTo(UNiagaraDataInterface* Target) const
{
	if (!Super::CopyTo(Target))
	{
		return false;
	}
	UNiagaraDataInterfaceColorCurve* TargetColorCurve = CastChecked<UNiagaraDataInterfaceColorCurve>(Target);
	TargetColorCurve->RedChannelCurve = RedChannelCurve;
	TargetColorCurve->GreenChannelCurve = GreenChannelCurve;
	TargetColorCurve->BlueChannelCurve = BlueChannelCurve;
	TargetColorCurve->AlphaChannelCurve = AlphaChannelCurve;
	TargetColorCurve->GenerateLookupTable();
	return true;
}

bool UNiagaraDataInterfaceColorCurve::Equals(const UNiagaraDataInterface* Other) const
{
	if (!Super::Equals(Other))
	{
		return false;
	}
	const UNiagaraDataInterfaceColorCurve* OtherColorCurve = CastChecked<const UNiagaraDataInterfaceColorCurve>(Other);
	return OtherColorCurve->RedChannelCurve == RedChannelCurve &&
		OtherColorCurve->GreenChannelCurve == GreenChannelCurve &&
		OtherColorCurve->BlueChannelCurve == BlueChannelCurve &&
		OtherColorCurve->AlphaChannelCurve == AlphaChannelCurve;
}

void UNiagaraDataInterfaceColorCurve::GetCurveData(TArray<FCurveData>& OutCurveList)
{
	OutCurveList.Add(FCurveData(&RedChannelCurve, TEXT("Red"), FLinearColor::Red));
	OutCurveList.Add(FCurveData(&GreenChannelCurve, TEXT("Green"), FLinearColor::Green));
	OutCurveList.Add(FCurveData(&BlueChannelCurve, TEXT("Blue"), FLinearColor::Blue));
	OutCurveList.Add(FCurveData(&AlphaChannelCurve, TEXT("Alpha"), FLinearColor::White));
}

void UNiagaraDataInterfaceColorCurve::GetFunctions(TArray<FNiagaraFunctionSignature>& OutFunctionList)
{
	FNiagaraFunctionSignature Signature;
	Signature.Name = TEXT("SampleColorCurve");
	Signature.bMemberFunction = true;
	Signature.bRequiresContext = false;
	Signature.Inputs.Add(FNiagaraVariable(FNiagaraTypeDefinition(GetClass()), TEXT("ColorCurve")));
	Signature.Inputs.Add(FNiagaraVariable(FNiagaraTypeDefinition::GetFloatDef(), TEXT("T")));
	Signature.Outputs.Add(FNiagaraVariable(FNiagaraTypeDefinition::GetColorDef(), TEXT("Result")));
	OutFunctionList.Add(Signature);
}

bool UNiagaraDataInterfaceColorCurve::GetFunctionHLSL(FString FunctionIdentifier, TArray<DIGPUBufferParamDescriptor> &BufferParams, FString &InterfaceID, FString &OutHLSLCode)
{
	FString BufferVariable = BufferParams[0].BufferParamName;
	OutHLSLCode += TEXT("void ") + FunctionIdentifier + TEXT("(in float In_T, out float4 Out_Result) \n{\n");
	OutHLSLCode += TEXT("\t Out_Result.x = ") + BufferVariable + TEXT("[(int)(In_T *") + FString::FromInt(LookupTableSize) + TEXT(")* 4 ];");
	OutHLSLCode += TEXT("\t Out_Result.y = ") + BufferVariable + TEXT("[1+ (int)(In_T *") + FString::FromInt(LookupTableSize) + TEXT(")* 4 ];");
	OutHLSLCode += TEXT("\t Out_Result.z = ") + BufferVariable + TEXT("[2+ (int)(In_T *") + FString::FromInt(LookupTableSize) + TEXT(")* 4 ];");
	OutHLSLCode += TEXT("\t Out_Result.w = ") + BufferVariable + TEXT("[3+ (int)(In_T *") + FString::FromInt(LookupTableSize) + TEXT(")* 4 ];");
	OutHLSLCode += TEXT("\n}\n");
	return true;
}

void UNiagaraDataInterfaceColorCurve::GetBufferDefinitionHLSL(FString DataInterfaceUID, TArray<DIGPUBufferParamDescriptor> &BufferDescriptors, FString &OutHLSLCode)
{
	FString BufferVariableName = "CurveLUT" + DataInterfaceUID;
	OutHLSLCode += TEXT("Buffer<float> ") + BufferVariableName + TEXT(";\n");
	BufferDescriptors.Add(DIGPUBufferParamDescriptor(BufferVariableName, 0));
}

void UNiagaraDataInterfaceColorCurve::SetupBuffers(TArray<DIGPUBufferParamDescriptor> &BufferDescriptors)
{
	for (DIGPUBufferParamDescriptor &Desc : BufferDescriptors)
	{
		FNiagaraDataInterfaceBufferData BufferInfo(*Desc.BufferParamName);
		GPUBuffers.Add(BufferInfo);
	}
}

TArray<FNiagaraDataInterfaceBufferData> &UNiagaraDataInterfaceColorCurve::GetBufferDataArray()
{
	check(IsInRenderingThread());
	if (GPUBufferNeedsUpdate)
	{
		check(GPUBuffers.Num() > 0);
		FNiagaraDataInterfaceBufferData &GPUData = GPUBuffers[0];
		GPUData.Buffer.Release();
		GPUData.Buffer.Initialize(sizeof(float), LookupTableSize * 4, EPixelFormat::PF_R32_FLOAT, BUF_Volatile);
		uint32 DataSize = ShaderLUT.Num() * sizeof(float);
		int32* BufferData = static_cast<int32*>(RHILockVertexBuffer(GPUData.Buffer.Buffer, 0, DataSize, EResourceLockMode::RLM_WriteOnly));
		FPlatformMemory::Memcpy(BufferData, ShaderLUT.GetData(), DataSize);
		RHIUnlockVertexBuffer(GPUData.Buffer.Buffer);
		GPUBufferNeedsUpdate = false;
	}
	return GPUBuffers;
}

DEFINE_NDI_FUNC_BINDER(UNiagaraDataInterfaceColorCurve, EvaluateCurve);
FVMExternalFunction UNiagaraDataInterfaceColorCurve::GetVMExternalFunction(const FVMExternalFunctionBindingInfo& BindingInfo, void* InstanceData)
{
	if (BindingInfo.Name == TEXT("SampleColorCurve") && BindingInfo.GetNumInputs() == 1 && BindingInfo.GetNumOutputs() == 4)
	{
		return TNDIParamBinder<0, float, NDI_FUNC_BINDER(UNiagaraDataInterfaceColorCurve, EvaluateCurve)>::Bind(this, BindingInfo, InstanceData);
	}
	else
	{
		UE_LOG(LogNiagara, Error, TEXT("Could not find data interface external function.\n\tExpected Name: SampleColorCurve  Actual Name: %s\n\tExpected Inputs: 1  Actual Inputs: %i\n\tExpected Outputs: 4  Actual Outputs: %i"),
			*BindingInfo.Name.ToString(), BindingInfo.GetNumInputs(), BindingInfo.GetNumOutputs());
		return FVMExternalFunction();
	}
}

template<typename TimeParamType>
void UNiagaraDataInterfaceColorCurve::EvaluateCurve(FVectorVMContext& Context)
{
	TimeParamType TimeParam(Context);
	FRegisterHandler<float> OutputR(Context);
	FRegisterHandler<float> OutputG(Context);
	FRegisterHandler<float> OutputB(Context);
	FRegisterHandler<float> OutputA(Context);
	for (int32 i = 0; i < Context.NumInstances; ++i)
	{
		float T = TimeParam.Get();
		FLinearColor Color(
			RedChannelCurve.Eval(T),
			GreenChannelCurve.Eval(T),
			BlueChannelCurve.Eval(T),
			AlphaChannelCurve.Eval(T)
		);
		*OutputR.GetDest() = Color.R;
		*OutputG.GetDest() = Color.G;
		*OutputB.GetDest() = Color.B;
		*OutputA.GetDest() = Color.A;
		TimeParam.Advance();
		OutputR.Advance();
		OutputG.Advance();
		OutputB.Advance();
		OutputA.Advance();
	}
}

