// TODO move from macro to function/assert for better readability?
#define verify_match(x) assert(prev_state->x == current_state->x);
#define verify_buffer(x) assert(memcmp(prev_state->x, current_state->x, sizeof(current_state->x)) == 0);

bool upgrade_from_FF_to_01(AuthenticatorState_0xFF* prev_state, AuthenticatorState_0x01* current_state){
    // Compute PIN hash and substitute raw PIN with its hash; include version in structure
    // remaining fields remain unchanged
    if (current_state->data_version != 0xFF)
        return false;

    static_assert(sizeof(AuthenticatorState_0xFF) <= sizeof(AuthenticatorState_0x01), 
                  "New state structure is smaller than current one, which is not supported");

    if (ctap_generate_rng(current_state->PIN_SALT, sizeof(current_state->PIN_SALT)) != 1) {
        printf2(TAG_ERR, "Error: RNG failed\n");
        return false;
    }

    if (prev_state->is_pin_set){
        crypto_sha256_init();
        crypto_sha256_update(prev_state->pin_code, prev_state->pin_code_length);
        uint8_t tempHash[32];
        crypto_sha256_final(tempHash);
        crypto_sha256_init();
        crypto_sha256_update(tempHash, 16);
        memset(tempHash, 0, sizeof(tempHash));
        crypto_sha256_update(current_state->PIN_SALT, sizeof(current_state->PIN_SALT));
        crypto_sha256_final(current_state->PIN_CODE_HASH);
    }

    assert(current_state->_reserved == prev_state->pin_code_length);
    current_state->_reserved = 0xFF;
    current_state->data_version = 1;

    verify_match(is_initialized);
    verify_match(is_pin_set);
    verify_match(remaining_tries);
    verify_match(rk_stored);
    verify_buffer(key_lens);
    verify_buffer(key_space);

    assert(current_state->data_version != 0xFF);
    return true;
}

void persist_upgraded_state(AuthenticatorState *current_state) {
    memmove(&STATE, current_state, sizeof(AuthenticatorState));
    authenticator_write_state(current_state);
}

void perform_upgrade_if_needed(AuthenticatorState* current_state){
    // Currently handles only state structures with the same size or larger
    // FIXME rework to raw buffers with fixed size to allow state structure size decrease
    if(!current_state->is_initialized)
        return;

    AuthenticatorState buffer_current;
    AuthenticatorState buffer_previous;

    authenticator_read_state(&buffer_previous);
    authenticator_read_state(&buffer_current);

    printf2(TAG_ERR, "Skipping migration process\n");

    if(current_state->data_version == 0xFF){
        printf2(TAG_ERR, "Executing migration\n");
        bool result = upgrade_from_FF_to_01((AuthenticatorState_0xFF *) &buffer_previous, &buffer_current);
        if (!result){
            printf2(TAG_ERR, "Migration from 0xFF to 1 failed\n");
            // FIXME discuss migration failure behavior
            goto cleanup_buffers;
        }

        dump_hex1(TAG_ERR, (uint8_t *)&buffer_current, sizeof(buffer_current));
        dump_hex1(TAG_ERR, (uint8_t *)&buffer_previous, sizeof(buffer_previous));
        persist_upgraded_state(&buffer_current);
    }

    assert(current_state->data_version == STATE_VERSION);

cleanup_buffers:
    memset(&buffer_current, 0, sizeof(AuthenticatorState));
    memset(&buffer_previous, 0, sizeof(AuthenticatorState));
}

