CorrelMatAna2D::CorrelMatAna2D(int Nimages)
{
     NumImages = Nimages;
     CorrelationMatrix.alloc(Nimages);
     MeanValues.alloc(Nimages);
     CorrelationMat.alloc(NumImages, NumImages);
     MeanValues.init();
}
/************************************************************/
void CorrelMatAna2D::print()
{
    for(int idx=0; idx < NumImages; idx++)
         cout  << "image " << idx+1 <<  ": mean = " << MeanValues(idx) << endl;
    CorrelationMatrix.print();
}
/************************************************************/
void CorrelMatAna2D::subtract_mean(Ifloat *ImageArray)
{
    int index,k;
    int Rows = ImageArray[0].nl();
    int Cols = ImageArray[0].nc();

    for(k=0; k < NumImages; k++)
    {
       MeanValues(k) = average(ImageArray[k]);   
       for (index=0; index < Rows*Cols; index++) ImageArray[k](index) -= MeanValues(k);
    }
}
/************************************************************/
void CorrelMatAna2D::add_mean(Ifloat *ImageArray)
{
    int index,k;
    int Rows = ImageArray[0].nl();
    int Cols = ImageArray[0].nc();
    for(k=0; k < NumImages; k++)
    {
        for (index=0; index < Rows*Cols; index++) ImageArray[k](index) += MeanValues(k);
    }
}
/************************************************************/
void CorrelMatAna2D::compute(Ifloat *ImageArray, float Threshold)
{
    int row,col;

    // compute the correlation matrix
    CorrelationMat.init();

    // diagonal elements are set to unity
    for(row=0; row < NumImages; row++) CorrelationMat(row,row) = 1.0f;

    for(row=0; row < NumImages; row++)
    for(col=row+1; col < NumImages; col++)
    { 
       if (Threshold > 0.0f)  
 	       CorrelationMat(row,col) = correlation(ImageArray[row], ImageArray[col], Threshold);
       else CorrelationMat(row,col) = correlation(ImageArray[row], ImageArray[col]);

       // matrix is symmetric
       CorrelationMat(col,row) =  CorrelationMat(row,col);
    }

       // eigenvalue decomposition
       CorrelationMatrix.compute_eigen(CorrelationMat);
}      
/************************************************************/
void CorrelMatAna2D::transform (Ifloat *InputImages, Ifloat *OutputImages)
{
   int i,j,k;
   fltarray TempVector(NumImages);
   fltarray TransformedVector(NumImages);     

   for (i=0; i < InputImages[0].nl(); i++)
   for (j=0; j < InputImages[0].nc(); j++)
   {
      for (k = 0; k < NumImages; k++) TempVector(k) = (InputImages[k])(i,j);
      CorrelationMatrix.transform(TempVector, TransformedVector);
      for (k = 0; k < NumImages; k++) (OutputImages[k])(i,j) = TransformedVector(k);
   } 
}
/************************************************************/
void CorrelMatAna2D::invtransform ( Ifloat *InputImages, Ifloat *OutputImages)
{
   int i,j,k;
   fltarray TempVector(NumImages);
   fltarray InverseTransformedVector(NumImages);

    for (i=0; i < InputImages[0].nl(); i++)
    for (j=0; j < InputImages[0].nc(); j++)
    {
       for (k = 0; k < NumImages; k++) TempVector(k) = InputImages[k](i,j);
       CorrelationMatrix.invtransform(TempVector, InverseTransformedVector);
       for (k = 0; k < NumImages; k++) OutputImages[k](i,j) = InverseTransformedVector(k);
    }   
}
/************************************************************/
void CorrelMatAna2D::invsubtransform (Ifloat *InputImages, Ifloat *OutputImages, 
                         int NumEigen, int *KillFlags)
{
    int i,j,k;
    fltarray TempVector(NumImages);
    fltarray InverseTransformedVector(NumImages);
    int M = NumEigen;

    if ((M < 1) || (M > NumImages)) M = NumImages;

    for (i=0; i < InputImages[0].nl(); i++)
    for (j=0; j < InputImages[0].nc(); j++)
    {
        for (k = 0; k < M; k++)
        {
          if ((KillFlags != NULL) && (KillFlags[k] == 1)) TempVector(k) = 0.0f;
          else TempVector(k) = InputImages[k](i,j);
        }
        CorrelationMatrix.invtransform(TempVector, InverseTransformedVector, M);
        for (k = 0; k < NumImages; k++) OutputImages[k](i,j) = InverseTransformedVector(k);
    }   
}
