	metadata[sourceIndex].Usage  = VK_IMAGE_USAGE_TRANSFER_SRC_BIT;
	metadata[sourceIndex].Stage  = VK_PIPELINE_STAGE_TRANSFER_BIT;
	metadata[sourceIndex].Access = VK_ACCESS_TRANSFER_READ_BIT;
	metadata[destIndex].Layout   = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
	metadata[destIndex].Usage    = VK_IMAGE_USAGE_TRANSFER_DST_BIT;
