inline bool Vulkan::CopyImagePass::PropagateSubresourceInfos(std::span<SubresourceMetadataPayload> metadata)
{
	uint32_t sourceIndex = (size_t)PassSubresourceId::SrcImage;
	uint32_t destIndex   = (size_t)PassSubresourceId::DstImage;
	bool changed         = false;

	if (metadata[sourceIndex].Format == VK_FORMAT_UNDEFINED && metadata[destIndex].Format != VK_FORMAT_UNDEFINED)
	{
		metadata[sourceIndex].Format = metadata[destIndex].Format;
		changed = true;
	}

	if (metadata[destIndex].Format == VK_FORMAT_UNDEFINED && metadata[sourceIndex].Format != VK_FORMAT_UNDEFINED)
	{
		metadata[destIndex].Format = metadata[sourceIndex].Format;
		changed = true;
	}

	return changed;
}

