#include "stacktrace.hpp"
#include "logging.hpp"

#ifdef WIN32
#include <windows.h>
#include <DbgHelp.h>

static bool s_initialized;

//---------------------------------------------------------------------------
void PrintStack() { 
    SpeedLog()->info("Stack Trace:\n" + GetStackTrace()); 
}

//---------------------------------------------------------------------------
std::vector<void*> GetStackFunctionPointers()
{
    auto currentProcess = GetCurrentProcess();
    if (!s_initialized)
    {
        s_initialized = true;
        bool initialization_ok = SymInitialize(currentProcess, nullptr, TRUE);
        if (!initialization_ok)
        {
            WARN_("Failed to initialize debug symbol handling.");
        }
        SymSetOptions(SYMOPT_LOAD_LINES);
    }

    static constexpr size_t MAX_CALLS = 32;
    std::vector<void*> call_addresses(MAX_CALLS, nullptr);
    const ULONG skip_frames = 0;
    ULONG trace_hash = 0;

    const USHORT actual_count =
        CaptureStackBackTrace(skip_frames, static_cast<DWORD>(call_addresses.size()),
                              call_addresses.data(), &trace_hash);

    call_addresses.resize(actual_count);
    return call_addresses;
}

//---------------------------------------------------------------------------
std::string GetStackTrace()
{
    auto currentProcess = GetCurrentProcess();
    std::vector<void*> call_addresses = GetStackFunctionPointers();
    std::string full_trace = "";
    uint32_t frame_number = 0;

    for (USHORT idx = 0; idx < call_addresses.size(); ++idx)
    {
        const uint32_t max_symbol_len = 1024;
        uint8_t symbol_buffer[sizeof(SYMBOL_INFO) + max_symbol_len + sizeof(ULONG) - 1];
        SYMBOL_INFO* symbol_info = reinterpret_cast<SYMBOL_INFO*>(symbol_buffer);
        symbol_info->SizeOfStruct = sizeof(SYMBOL_INFO);
        symbol_info->MaxNameLen = 1024;

        uint64_t displacement = 0;
        auto success = SymFromAddr(currentProcess, (DWORD64)call_addresses[idx],
                                   &displacement, symbol_info);

        const char* frame_description = "<Unknown>";
        bool is_main_frame = false;

        if (success)
        {
            frame_description = symbol_info->Name;

            // Skip internal functions
            if (strcmp(frame_description, "GetStackTrace") == 0 ||
                strcmp(frame_description, "PrintStack") == 0)
            {
                continue;
            }

            // Detect main function as entry point
            is_main_frame = (strcmp(frame_description, "main") == 0);

            IMAGEHLP_LINE64 line_info;
            line_info.SizeOfStruct = sizeof(IMAGEHLP_LINE64);
            DWORD line_displacement = 0;

            if (SymGetLineFromAddr(currentProcess, (DWORD64)call_addresses[idx],
                                   &line_displacement, &line_info))
            {
                std::string detailed_frame = std::string(frame_description) + " @ " +
                                             std::string(line_info.FileName) + ":" +
                                             std::to_string(line_info.LineNumber);
                frame_description = detailed_frame.c_str();
            }
        }

        std::string formatted_line = fmt::format("[{:03}] {} | {}\n", 
                                                  frame_number,
                                                  call_addresses[idx], 
                                                  frame_description);
        full_trace += formatted_line;
        frame_number++;

        if (is_main_frame)
        {
            break;
        }
    }

    return full_trace;
}
