static inline constexpr uint8_t encode_register(uint8_t bank, uint8_t address) {
    return ((bank & 0b11) << 5) | (address & 0b11111);
}

namespace register_map {
    // common registers across all banks
    constexpr uint8_t eth_int_enable = encode_register(0, 0x1B);
    constexpr uint8_t eth_int_flag = encode_register(0, 0x1C);
    constexpr uint8_t eth_status = encode_register(0, 0x1D);
    constexpr uint8_t eth_con2 = encode_register(0, 0x1E);
    constexpr uint8_t eth_con1 = encode_register(0, 0x1F);

    // bank 0 specific registers
    constexpr uint8_t read_ptr_low = encode_register(0, 0x00);
    constexpr uint8_t read_ptr_high = encode_register(0, 0x01);
    constexpr uint8_t write_ptr_low = encode_register(0, 0x02);
    constexpr uint8_t write_ptr_high = encode_register(0, 0x03);
    constexpr uint8_t tx_start_low = encode_register(0, 0x04);
    constexpr uint8_t tx_start_high = encode_register(0, 0x05);
    constexpr uint8_t tx_end_low = encode_register(0, 0x06);
    constexpr uint8_t tx_end_high = encode_register(0, 0x07);
    constexpr uint8_t rx_start_low = encode_register(0, 0x08);
    constexpr uint8_t rx_start_high = encode_register(0, 0x09);
    constexpr uint8_t rx_end_low = encode_register(0, 0x0A);
    constexpr uint8_t rx_end_high = encode_register(0, 0x0B);
    constexpr uint8_t rx_read_ptr_low = encode_register(0, 0x0C);
    constexpr uint8_t rx_read_ptr_high = encode_register(0, 0x0D);
    constexpr uint8_t rx_write_ptr_low = encode_register(0, 0x0E);
    constexpr uint8_t rx_write_ptr_high = encode_register(0, 0x0F);

    // bank 1 specific registers
    constexpr uint8_t packet_count = encode_register(1, 0x19);

    // bank 2 specific registers
    constexpr uint8_t mac_con1 = encode_register(2, 0x00);
    constexpr uint8_t mac_con3 = encode_register(2, 0x02);
    constexpr uint8_t mac_con4 = encode_register(2, 0x03);
    constexpr uint8_t mac_bb_ipg = encode_register(2, 0x04);
    constexpr uint8_t mac_pi_pgl = encode_register(2, 0x06);
    constexpr uint8_t micm_cmd = encode_register(2, 0x12);
    constexpr uint8_t miadr_addr = encode_register(2, 0x14);
    constexpr uint8_t miwr_data_l = encode_register(2, 0x16);
    constexpr uint8_t miwr_data_h = encode_register(2, 0x17);
    constexpr uint8_t mird_data_l = encode_register(2, 0x18);
