namespace lab {

AnalyserNode::AnalyserNode(float sampleRate, size_t fftSize) 
    : AudioBasicInspectorNode(sampleRate, 2), m_analyser(fftSize)
{
    //N.B.: inputs and outputs added by AudioBasicInspectorNode... no need to create here.
    setNodeType(NodeTypeAnalyser);
    initialize();
}

AnalyserNode::~AnalyserNode()
{
    uninitialize();
}

void AnalyserNode::process(ContextRenderLock& r, size_t frameCount)
{
    AudioBus* outputBus = output(0)->bus(r);

    if (!isInitialized() || !input(0)->isConnected())
    {
        outputBus->zero();
        return;
    }

    AudioBus* inputBus = input(0)->bus(r);

    // Pass the incoming audio data to the analyser for analysis.
    m_analyser.writeInput(r, inputBus, frameCount);

    // For in-place processing, our override of pullInputs() will simply forward 
    // the audio unchanged when channel counts match (i.e., inputBus == outputBus).
    // Otherwise, perform up-mixing to stereo.
    if (inputBus != outputBus)
    {
        outputBus->copyFrom(*inputBus);
    }
}

void AnalyserNode::reset(ContextRenderLock&)
{
    m_analyser.reset();
}

