// Main Perlin noise calculation function
double Perlin::perlin(double xCoord, double yCoord, double zCoord) {
    if (repeat > 0) {
        // If repetition is enabled, wrap coordinates to local repetitions
        xCoord = static_cast<int>(xCoord) % repeat;
        yCoord = static_cast<int>(yCoord) % repeat;
        zCoord = static_cast<int>(zCoord) % repeat;
    }

    // Determine the integer coordinates of the unit cube containing the point
    int xi = static_cast<int>(xCoord) & 255;
    int yi = static_cast<int>(yCoord) & 255;
    int zi = static_cast<int>(zCoord) & 255;

    // Compute fractional parts and fade them for smooth interpolation
    double xf = xCoord - static_cast<int>(xCoord);
    double yf = yCoord - static_cast<int>(yCoord);
    double zf = zCoord - static_cast<int>(zCoord);

    double u = fade(xf);
    double v = fade(yf);
    double w = fade(zf);

    // Retrieve hashed indices for the eight corners of the unit cube
    int aaa = p[p[p[xi] + yi] + zi];
    int aba = p[p[p[xi] + inc(yi)] + zi];
    int aab = p[p[p[xi] + yi] + inc(zi)];
    int abb = p[p[p[xi] + inc(yi)] + inc(zi)];
    int baa = p[p[p[inc(xi)] + yi] + zi];
    int bba = p[p[p[inc(xi)] + inc(yi)] + zi];
    int bab = p[p[p[inc(xi)] + yi] + inc(zi)];
    int bbb = p[p[p[inc(xi)] + inc(yi)] + inc(zi)];

    // Interpolate gradient contributions from each corner
    double x1 = lerp(grad(aaa, xf, yf, zf),
                     grad(baa, xf - 1, yf, zf),
                     u);
    double x2 = lerp(grad(aba, xf, yf - 1, zf),
                     grad(bba, xf - 1, yf - 1, zf),
                     u);
    double y1 = lerp(x1, x2, v);

    double x3 = lerp(grad(aab, xf, yf, zf - 1),
                     grad(bab, xf - 1, yf, zf - 1),
                     u);
    double x4 = lerp(grad(abb, xf, yf - 1, zf - 1),
                     grad(bbb, xf - 1, yf - 1, zf - 1),
                     u);
    double y2 = lerp(x3, x4, v);

    // Final interpolation and normalization to [0, 1]
    return (lerp(y1, y2, w) + 1) / 2;
}

// Increment with optional wrapping based on repeat distance
int Perlin::inc(int value) {
    value++;
    if (repeat > 0)
        value %= repeat;
    return value;
}

// Gradient function using hash-based vector selection
double Perlin::grad(int hashValue, double dx, double dy, double dz) {
    int h = hashValue & 15;

    // Select first component: x if h < 8, else y
    double firstComponent = (h < 8) ? dx : dy;

    // Select second component based on lower bits
    double secondComponent;
    if (h < 4)
        secondComponent = dy;
    else if (h == 12 || h == 14)
        secondComponent = dx;
    else
        secondComponent = dz;

    // Apply sign based on remaining bits and return sum
    return ((h & 1) == 0 ? firstComponent : -firstComponent) +
           ((h & 2) == 0 ? secondComponent : -secondComponent);
}

// Smoothstep-like fade function for interpolation smoothing
double Perlin::fade(double t) {
    return t * t * t * (t * (t * 6 - 15) + 10); // 6t^5 - 15t^4 + 10t^3
}

// Linear interpolation helper
double Perlin::lerp(double startValue, double endValue, double blendFactor) {
    return startValue + blendFactor * (endValue - startValue);
}

// Multi-octave Perlin noise generator
double Perlin::OctavePerlin(double x, double y, double z, int octaveCount, double persistenceFactor) {
    double result = 0.0;
    double currentFrequency = 1.0;
    double currentAmplitude = 1.0;
    double maxPossibleValue = 0.0;

    for (int i = 0; i < octaveCount; ++i) {
        result += perlin(x * currentFrequency, y * currentFrequency, z * currentFrequency) * currentAmplitude;
        maxPossibleValue += currentAmplitude;
        currentAmplitude *= persistenceFactor;
        currentFrequency *= 2.0;
    }

    return result / maxPossibleValue;
}

