// Memory manager for LLVM object loading
struct LLVMJIT::ModuleMemoryManager : llvm::RTDyldMemoryManager
{
	ModuleMemoryManager()
	: imageBase(nullptr)
	, finalized(false)
	, textSection({nullptr, 0, 0})
	, constSection({nullptr, 0, 0})
	, dataSection({nullptr, 0, 0})
	, ehFramesRegistered(false)
	{
	}

	virtual ~ModuleMemoryManager() override
	{
		releaseEHFrames();
		if(!KEEP_MODULE_ADDRESSES_RESERVED)
		{ Platform::freeVirtualPages(imageBase, totalImagePages); }
		else
		{
			Platform::decommitVirtualPages(imageBase, totalImagePages);
		}
	}

	void registerEHFrames(U8* addr, U64 loadAddr, uintptr_t numBytes) override
	{
		if(!ENABLE_WINDOWS_SEH)
		{
			Platform::registerEHFrames(imageBase, addr, numBytes);
			ehFramesRegistered = true;
			ehFrameStart = addr;
			ehFrameSize = numBytes;
		}
	}

	void registerFixedSEHFrames(U8* addr, Uptr numBytes)
	{
		Platform::registerEHFrames(imageBase, addr, numBytes);
		ehFramesRegistered = true;
		ehFrameStart = addr;
		ehFrameSize = numBytes;
	}

	void releaseEHFrames() override
	{
		if(ehFramesRegistered)
		{
			ehFramesRegistered = false;
			Platform::deregisterEHFrames(imageBase, ehFrameStart, ehFrameSize);
		}
	}

	virtual bool needsToReserveAllocationSpace() override { return true; }

	virtual void reserveAllocationSpace(uintptr_t numCodeBytes,
										U32 codeAlign,
										uintptr_t numConstBytes,
										U32 constAlign,
										uintptr_t numDataBytes,
										U32 dataAlign) override
	{
		if(ENABLE_WINDOWS_SEH)
		{
			numCodeBytes += 32;
		}

		textSection.numPages = shrAndRoundUp(numCodeBytes, Platform::getPageSizeLog2());
		constSection.numPages = shrAndRoundUp(numConstBytes, Platform::getPageSizeLog2());
		dataSection.numPages = shrAndRoundUp(numDataBytes, Platform::getPageSizeLog2());

		totalImagePages = textSection.numPages + constSection.numPages + dataSection.numPages;

		if(totalImagePages)
		{
			imageBase = Platform::allocateVirtualPages(totalImagePages);
			if(!imageBase || !Platform::commitVirtualPages(imageBase, totalImagePages))
			{ Errors::fatal("JIT memory allocation failed"); }

			textSection.baseAddress = imageBase;
			constSection.baseAddress = textSection.baseAddress + (textSection.numPages << Platform::getPageSizeLog2());
			dataSection.baseAddress = constSection.baseAddress + (constSection.numPages << Platform::getPageSizeLog2());
		}
	}

	virtual U8* allocateCodeSection(uintptr_t numBytes,
									U32 alignment,
									U32 sectionID,
									llvm::StringRef sectionName) override
	{
		return allocateBytes((Uptr)numBytes, alignment, textSection);
	}

	virtual U8* allocateDataSection(uintptr_t numBytes,
									U32 alignment,
									U32 sectionID,
									llvm::StringRef SectionName,
									bool isReadOnly) override
	{
		return allocateBytes(
			(Uptr)numBytes, alignment, isReadOnly ? constSection : dataSection);
	}

	virtual bool finalizeMemory(std::string* ErrMsg = nullptr) override
	{
		return true;
	}

	void reallyFinalizeMemory()
	{
		wavmAssert(!finalized);
		finalized = true;

		const Platform::MemoryAccess execAccess = Platform::MemoryAccess::execute;
		if(textSection.numPages)
		{
			errorUnless(Platform::setVirtualPageAccess(
				textSection.baseAddress, textSection.numPages, execAccess));
		}

		if(constSection.numPages)
		{
			errorUnless(Platform::setVirtualPageAccess(constSection.baseAddress,
													   constSection.numPages,
													   Platform::MemoryAccess::readOnly));
		}

		if(dataSection.numPages)
		{
			errorUnless(Platform::setVirtualPageAccess(dataSection.baseAddress,
													   dataSection.numPages,
													   Platform::MemoryAccess::readWrite));
		}

		invalidateInstructionCache();
	}

	virtual void invalidateInstructionCache()
	{
		llvm::sys::Memory::InvalidateInstructionCache(
			imageBase, totalImagePages << Platform::getPageSizeLog2());
	}

	U8* getImageBase() const { return imageBase; }
	Uptr getTotalImageBytes() const { return totalImagePages << Platform::getPageSizeLog2(); }

private:
	struct MemRegion
	{
		U8* baseAddress;
		Uptr numPages;
		Uptr committedBytes;
	};

	U8* imageBase;
	Uptr totalImagePages;
	bool finalized;
	MemRegion textSection;
	MemRegion constSection;
	MemRegion dataSection;
	bool ehFramesRegistered;
	const U8* ehFrameStart;
	Uptr ehFrameSize;

	U8* allocateBytes(Uptr size, Uptr align, MemRegion& region)
	{
		if(align == 0) { align = 1; }
		wavmAssert(region.baseAddress);
		wavmAssert(!(align & (align - 1)));
		wavmAssert(!finalized);

		U8* allocAddr = region.baseAddress + align(region.committedBytes, align);
		wavmAssert(!(reinterpret_cast<Uptr>(allocAddr) & (align - 1)));

		region.committedBytes = align(region.committedBytes, align) + align(size, align);

		if(region.committedBytes > (region.numPages << Platform::getPageSizeLog2()))
		{ Errors::fatal("section space exhausted"); }

		return allocAddr;
	}

	static Uptr align(Uptr val, Uptr alignment)
	{
		return (val + alignment - 1) & ~(alignment - 1);
	}

	static Uptr shrAndRoundUp(Uptr value, Uptr shift)
	{
		return (value + (Uptr(1) << shift) - 1) >> shift;
	}

	ModuleMemoryManager(const ModuleMemoryManager&) = delete;
	void operator=(const ModuleMemoryManager&) = delete;
};

static void printDisassembly(U8* bytes, Uptr count)
{
	LLVMDisasmContextRef ctx
		= LLVMCreateDisasm(llvm::sys::getProcessTriple().c_str(), nullptr, 0, nullptr, nullptr);
	U8* cursor = bytes;
	Uptr remaining = count;

	while(remaining)
	{
		char instrBuf[256];
		Uptr instrLen = LLVMDisasmInstruction(ctx,
											  cursor,
											  remaining,
											  reinterpret_cast<Uptr>(cursor),
											  instrBuf,
											  sizeof(instrBuf));
		if(instrLen == 0) { instrLen = 1; }
		wavmAssert(instrLen <= remaining);
		remaining -= instrLen;
		cursor += instrLen;

		Log::printf(Log::output,
					"\t\t0x%04" PRIxPTR " %s\n",
					(cursor - bytes - instrLen),
					instrBuf);
	}

	LLVMDisasmDispose(ctx);
}

Module::Module(const std::vector<U8>& objBytes,
			   const HashMap<std::string, Uptr>& symMap,
			   bool logTiming)
: memMgr(new ModuleMemoryManager())
#if LLVM_VERSION_MAJOR < 8
, objectData(objBytes)
#endif
{
	Timing::Timer loaderTimer;

#if LLVM_VERSION_MAJOR >= 8
	std::unique_ptr<llvm::object::ObjectFile> obj;
#endif

	obj = cantFail(llvm::object::ObjectFile::createObjectFile(llvm::MemoryBufferRef(
		llvm::StringRef((const char*)objBytes.data(), objBytes.size()), "jit_memory")));

	struct SymbolResolver : llvm::JITSymbolResolver
	{
		const HashMap<std::string, Uptr>& imports;
		SymbolResolver(const HashMap<std::string, Uptr>& map) : imports(map) {}

#if LLVM_VERSION_MAJOR >= 8
		virtual void lookup(const LookupSet& syms,
							llvm::JITSymbolResolver::OnResolvedFunction callback) override
		{
			LookupResult result;
			for(auto sym : syms) { result.emplace(sym, resolveSymbol(sym)); }
			callback(result);
		}

		virtual llvm::Expected<LookupSet> getResponsibilitySet(const LookupSet& syms) override
		{
			return LookupSet();
		}
#elif LLVM_VERSION_MAJOR == 7
		virtual llvm::Expected<LookupResult> lookup(const LookupSet& syms) override
		{
			LookupResult result;
			for(auto sym : syms) { result.emplace(sym, resolveSymbol(sym)); }
			return result;
		}

		virtual llvm::Expected<LookupFlagsResult> lookupFlags(const LookupSet& syms) override
		{
			LookupFlagsResult result;
			for(auto sym : syms)
			{ result.emplace(sym, resolveSymbol(sym).getFlags()); }
			return result;
		}
#else
		virtual llvm::JITSymbol findSymbolInLogicalDylib(const std::string& name) override
		{
			return resolveSymbol(name);
		}

		virtual llvm::JITSymbol findSymbol(const std::string& name) override
		{
			return resolveSymbol(name);
		}
#endif

	private:
		llvm::JITEvaluatedSymbol resolveSymbol(llvm::StringRef name)
		{
			const std::string demangled = demangleSymbol(name.str());
			const Uptr* found = imports.get(demangled);
			if(!found) { return resolveJITImport(demangled); }
			else
			{
				wavmAssert(*found);
				return llvm::JITEvaluatedSymbol(U64(*found), llvm::JITSymbolFlags::None);
			}
		}
	};

	SymbolResolver resolver(symMap);
	llvm::RuntimeDyld loader(*memMgr, resolver);

#ifndef _WIN32
	loader.setProcessAllSections(true);
#endif

	llvm::object::SectionRef pdataSec;
	U8* pdataBackup = nullptr;
	Uptr pdataSize = 0;

	llvm::object::SectionRef xdataSec;
	U8* xdataBackup = nullptr;

	if(ENABLE_WINDOWS_SEH)
	{
		for(auto section : obj->sections())
		{
			llvm::StringRef name;
			if(!section.getName(name))
			{
#if LLVM_VERSION_MAJOR >= 9
				llvm::Expected<llvm::StringRef> contentOrErr = section.getContents();
				if(contentOrErr)
				{
					const llvm::StringRef& content = contentOrErr.get();
#else
				llvm::StringRef content;
				if(!section.getContents(content))
				{
#endif
					const U8* loaded = (const U8*)content.data();
					if(name == ".pdata")
					{
						pdataBackup = new U8[section.getSize()];
						pdataSize = section.getSize();
						pdataSec = section;
						memcpy(pdataBackup, loaded, section.getSize());
					}
					else if(name == ".xdata")
					{
						xdataBackup = new U8[section.getSize()];
						xdataSec = section;
						memcpy(xdataBackup, loaded, section.getSize());
					}
				}
			}
		}
	}

	std::unique_ptr<llvm::RuntimeDyld::LoadedObjectInfo> loadedInfo = loader.loadObject(*obj);
	loader.finalizeWithMemoryManagerLocking();

	if(loader.hasError())
	{ Errors::fatalf("RuntimeDyld error: %s", loader.getErrorString().data()); }

	if(ENABLE_WINDOWS_SEH && pdataBackup)
	{
		const llvm::JITEvaluatedSymbol sehHandler = resolveJITImport("__CxxFrameHandler3");
		errorUnless(sehHandler);
		const U64 sehAddr = U64(sehHandler.getAddress());

		U8* tramp = memMgr->allocateCodeSection(16, 16, 0, "seh_tramp");
		tramp[0] = 0xff;
		tramp[1] = 0x25;
		memset(tramp + 2, 0, 4);
		memcpy(tramp + 6, &sehAddr, sizeof(U64));

		processSEPTables(memMgr->getImageBase(),
						 *loadedInfo,
						 pdataSec,
						 pdataBackup,
						 pdataSize,
						 xdataSec,
						 xdataBackup,
						 reinterpret_cast<Uptr>(tramp));

		memMgr->registerFixedSEHFrames(
			reinterpret_cast<U8*>(Uptr(loadedInfo->getSectionLoadAddress(pdataSec))),
			pdataSize);
	}

	if(pdataBackup)
	{
		delete[] pdataBackup;
		pdataBackup = nullptr;
	}

	if(xdataBackup)
	{
		delete[] xdataBackup;
		xdataBackup = nullptr;
	}

	memMgr->reallyFinalizeMemory();

	{
		Lock<Platform::Mutex> lock(gdbListenerMutex);
		if(!gdbListener)
		{ gdbListener = llvm::JITEventListener::createGDBRegistrationListener(); }

#if LLVM_VERSION_MAJOR >= 8
		gdbListener->notifyObjectLoaded(reinterpret_cast<Uptr>(this), *obj, *loadedInfo);
#else
		gdbListener->NotifyObjectEmitted(*obj, *loadedInfo);
#endif
	}

	auto dwarfCtx = llvm::DWARFContext::create(*obj, &*loadedInfo);

	for(std::pair<llvm::object::SymbolRef, U64> symPair :
		llvm::object::computeSymbolSizes(*obj))
	{
		llvm::object::SymbolRef symbol = symPair.first;

		if(!(symbol.getFlags() & llvm::object::SymbolRef::SF_Global)) { continue; }

		llvm::Expected<llvm::object::SymbolRef::Type> type = symbol.getType();
		if(!type || *type != llvm::object::SymbolRef::ST_Function) { continue; }

		llvm::Expected<llvm::StringRef> name = symbol.getName();
		if(!name) { continue; }

		llvm::Expected<U64> addr = symbol.getAddress();
		if(!addr) { continue; }

		Uptr loadAddr = Uptr(*addr);
		if(llvm::Expected<llvm::object::section_iterator> sec = symbol.getSection())
		{ loadAddr += (Uptr)loadedInfo->getSectionLoadAddress(*sec.get()); }

#if LLVM_VERSION_MAJOR >= 9
		llvm::Expected<llvm::object::section_iterator> sec = symbol.getSection();
		if(!sec) { continue; }
		llvm::DILineInfoTable lineTable = dwarfCtx->getLineInfoForAddressRange(
			llvm::object::SectionedAddress{loadAddr, sec.get()->getIndex()},
			symPair.second);
#else
		llvm::DILineInfoTable lineTable
			= dwarfCtx->getLineInfoForAddressRange(loadAddr, symPair.second);
#endif

		std::map<U32, U32> offsetMap;
		for(auto info : lineTable)
		{ offsetMap.emplace(U32(info.first - loadAddr), info.second.Line); }

		if(DUMP_DISASSEMBLY && logTiming)
		{
			Log::printf(Log::output, "Disassembly for %s\n", name.get().data());
			printDisassembly(reinterpret_cast<U8*>(loadAddr), Uptr(symPair.second));
		}

		wavmAssert(symPair.second <= UINTPTR_MAX);
		Runtime::Function* func
			= (Runtime::Function*)(loadAddr - offsetof(Runtime::Function, code));

		nameToFunctionMap.addOrFail(*name, func);
		addressToFunctionMap.emplace(Uptr(loadAddr + symPair.second), func);

		wavmAssert(func->mutableData);
		func->mutableData->jitModule = this;
		func->mutableData->function = func;
		func->mutableData->codeSize = Uptr(symPair.second);
		func->mutableData->offsetMap = std::move(offsetMap);
	}

	const Uptr endAddr = reinterpret_cast<Uptr>(memMgr->getImageBase() + memMgr->getTotalImageBytes());

	{
		Lock<Platform::Mutex> lock(addrToModuleMutex);
		addrToModuleMap.emplace(endAddr, this);
	}

	if(logTiming)
	{
		Timing::logRatePerSecond(
			"Module loaded", loaderTimer, (F64)objBytes.size() / 1024.0 / 1024.0, "MB");
	}
}

Module::~Module()
{
	{
		Lock<Platform::Mutex> lock(gdbListenerMutex);
#if LLVM_VERSION_MAJOR >= 8
		gdbListener->notifyFreeingObject(reinterpret_cast<Uptr>(this));
#else
		gdbListener->NotifyFreeingObject(*obj);
#endif
	}

	Lock<Platform::Mutex> lock(addrToModuleMutex);
	addrToModuleMap.erase(addrToModuleMap.find(reinterpret_cast<Uptr>(
		memMgr->getImageBase() + memMgr->getTotalImageBytes())));

	for(const auto& pair : addressToFunctionMap) { delete pair.second->mutableData; }

	delete memMgr;
}

std::shared_ptr<LLVMJIT::Module> LLVMJIT::loadModule(
	const std::vector<U8>& objBytes,
	HashMap<std::string, FunctionBinding>&& intrinsics,
	std::vector<IR::FunctionType>&& types,
	std::vector<FunctionBinding>&& funcImports,
	std::vector<TableBinding>&& tables,
	std::vector<MemoryBinding>&& memories,
	std::vector<GlobalBinding>&& globals,
	std::vector<ExceptionTypeBinding>&& exceptions,
	ModuleInstanceBinding modInst,
	Uptr tableBias,
	const std::vector<Runtime::FunctionMutableData*>& funcDatas)
{
	HashMap<std::string, Uptr> importedSyms;

	for(auto& pair : intrinsics)
	{
		wavmAssert(pair.value.callingConvention == IR::CallingConvention::intrinsic);
		importedSyms.addOrFail(pair.key, reinterpret_cast<Uptr>(pair.value.code));
	}

	for(Uptr idx = 0; idx < types.size(); ++idx)
	{
		importedSyms.addOrFail(getExternalName("typeId", idx),
							   types[idx].getEncoding().impl);
	}

	for(Uptr idx = 0; idx < funcImports.size(); ++idx)
	{
		importedSyms.addOrFail(getExternalName("funcImport", idx),
							   reinterpret_cast<Uptr>(funcImports[idx].code));
	}

	for(Uptr idx = 0; idx < tables.size(); ++idx)
	{
		importedSyms.addOrFail(getExternalName("tableOffset", idx),
							   offsetof(Runtime::CompartmentRuntimeData, tableBases)
								   + sizeof(void*) * tables[idx].id);
	}

	for(Uptr idx = 0; idx < memories.size(); ++idx)
	{
		importedSyms.addOrFail(getExternalName("memOffset", idx),
							   offsetof(Runtime::CompartmentRuntimeData, memoryBases)
								   + sizeof(void*) * memories[idx].id);
	}

	for(Uptr idx = 0; idx < globals.size(); ++idx)
	{
		const GlobalBinding& spec = globals[idx];
		Uptr val;
		if(spec.type.isMutable)
		{
			val = offsetof(Runtime::ContextRuntimeData, mutableGlobals)
				  + spec.mutableGlobalIndex * sizeof(IR::UntaggedValue);
		}
		else
		{
			val = reinterpret_cast<Uptr>(spec.immutableValuePointer);
		}
		importedSyms.addOrFail(getExternalName("global", idx), val);
	}

	for(Uptr idx = 0; idx < exceptions.size(); ++idx)
	{
		importedSyms.addOrFail(getExternalName("excTypeId", idx),
							   exceptions[idx].id + 1);
	}

	for(Uptr idx = 0; idx < funcDatas.size(); ++idx)
	{
		Runtime::FunctionMutableData* data = funcDatas[idx];
		importedSyms.addOrFail(getExternalName("funcData", idx),
							   reinterpret_cast<Uptr>(data));
	}

	wavmAssert(modInst.id != UINTPTR_MAX);
	importedSyms.addOrFail("modInstId", modInst.id + 1);
	importedSyms.addOrFail("tableBias", tableBias);

#if !ENABLE_WINDOWS_SEH
	std::type_info* excTypeInfo = nullptr;
	try
	{
		throw(Runtime::Exception*) nullptr;
	}
	catch(Runtime::Exception*)
	{
		excTypeInfo = __cxxabiv1::__cxa_current_exception_type();
	}
	importedSyms.addOrFail("runtimeExcTypeInfo", reinterpret_cast<Uptr>(excTypeInfo));
#endif

	return std::make_shared<Module>(objBytes, importedSyms, true);
}

Runtime::Function* LLVMJIT::getFunctionByAddress(Uptr addr)
{
	Module* jitMod;
	{
		Lock<Platform::Mutex> lock(addrToModuleMutex);
		auto it = addrToModuleMap.upper_bound(addr);
		if(it == addrToModuleMap.end()) { return nullptr; }
		jitMod = it->second;
	}

	auto fit = jitMod->addressToFunctionMap.upper_bound(addr);
	if(fit == jitMod->addressToFunctionMap.end()) { return nullptr; }

	Runtime::Function* func = fit->second;
	const Uptr codeStart = reinterpret_cast<Uptr>(func->code);
	return addr >= codeStart && addr < codeStart + func->mutableData->codeSize
			   ? func
			   : nullptr;
}

