/***
 *
 * Internal Device-side API functions
 *
 ***/
__device__ bool isFull(uint64_t read_idx, uint64_t write_idx,
                       uint64_t queue_size) {
    return ((queue_size - (write_idx - read_idx)) == 0);
}

__device__ void build_queue_element(ro_net_cmds type, void* dst, void * src,
                                    size_t size, int pe, int logPE_stride,
                                    int PE_size,  int PE_root,
                                    void* pWrk, long *pSync, MPI_Comm team_comm,
                                    struct ro_net_wg_handle *handle,
                                    bool blocking, ROC_SHMEM_OP op,
                                    ro_net_types datatype)
{
    int threadId = get_flat_block_id();
    uint64_t start = handle->profiler.startTimer();
    unsigned long long old_write_slot = handle->write_idx;
    unsigned long long write_slot;
    do {
        write_slot = old_write_slot;
        // If we think the queue might be full, poll on the in-memory read
        // index.  Otherwise, we are good to go!  In the common case we never
        // need to go to memory.
        while (isFull(handle->read_idx, write_slot, handle->queue_size))
        {
            __asm__ volatile ("global_load_dwordx2 %0 %1 off glc slc\n "
                              "s_waitcnt vmcnt(0)" :
                              "=v"(handle->read_idx) :
                              "v"(handle->host_read_idx));
        }
        // Double check that our write_idx is still available and update it.
        // If it isn't then we try again and validate that the new write
        // index is available for the taking.
        old_write_slot = atomicCAS((unsigned long long*) &handle->write_idx,
            write_slot, write_slot + 1);
    } while (write_slot != old_write_slot);
    handle->profiler.endTimer(start, WAITING_ON_SLOT);
    start = handle->profiler.startTimer();
    write_slot = write_slot % handle->queue_size;
    handle->queue[write_slot].type = type;
    handle->queue[write_slot].PE = pe;
    handle->queue[write_slot].size = size;
    handle->queue[write_slot].dst = dst;
    // Inline commands will pack the data value in the src field.
    if (type == RO_NET_P)
       memcpy(&handle->queue[write_slot].src, src, size);
    else
       handle->queue[write_slot].src = src;
    handle->queue[write_slot].threadId = threadId;
    /*
        * TODO: Might be more efficient to inline the stores.
    int1  val1 = make_int1((int)type);
    int2  val2 = make_int2(pe, size);
    long1 val3 = make_long1((long)src);
    long1 val4 = make_long1((long)dst);
    __store_dword(val1,
        (volatile int1*)&(handle->queue[write_slot].type));
    __store_dwordx2(val2,
        (volatile int2*)&(handle->queue[write_slot].PE));
    __store_long_dwordx2(val3,
        (volatile long1*)&(handle->queue[write_slot].src));
    __store_long_dwordx2(val4,
        (volatile long1*)&(handle->queue[write_slot].dst));
    */
    if(type == RO_NET_AMO_FOP)
        handle->queue[write_slot].op = op;
    if(type == RO_NET_AMO_FCAS)
        handle->queue[write_slot].pWrk = pWrk;
    if (type == RO_NET_TO_ALL) {
        handle->queue[write_slot].logPE_stride = logPE_stride;
        handle->queue[write_slot].PE_size = PE_size;
        handle->queue[write_slot].pWrk = pWrk;
        handle->queue[write_slot].pSync = pSync;
        handle->queue[write_slot].op = op;
        handle->queue[write_slot].datatype = datatype;
    }
    if (type == RO_NET_TEAM_TO_ALL) {
        handle->queue[write_slot].op = op;
        handle->queue[write_slot].datatype = datatype;
        handle->queue[write_slot].team_comm = team_comm;
    }
    if (type == RO_NET_BROADCAST) {
        handle->queue[write_slot].logPE_stride = logPE_stride;
        handle->queue[write_slot].PE_size = PE_size;
        handle->queue[write_slot].pSync = pSync;
        handle->queue[write_slot].PE_root = PE_root;
        handle->queue[write_slot].datatype = datatype;
    }
    if (type == RO_NET_TEAM_BROADCAST) {
        handle->queue[write_slot].PE_root = PE_root;
        handle->queue[write_slot].datatype = datatype;
        handle->queue[write_slot].team_comm = team_comm;
    }
    handle->profiler.endTimer(start, PACK_QUEUE);
    // Make sure queue element data is visible to CPU
    start = handle->profiler.startTimer();
    __threadfence();
    handle->profiler.endTimer(start, THREAD_FENCE_1);
    // Make data as ready and make visible to CPU
    start = handle->profiler.startTimer();
    handle->queue[write_slot].valid = 1;
    __threadfence();
    handle->profiler.endTimer(start, THREAD_FENCE_2);
    // Blocking requires the CPU to complete the operation.
    start = handle->profiler.startTimer();
    if (blocking) {
        int net_status = 0;
        do {
            // At will take at least 1-2us to satisfy any request, best case.
            // TODO: Vega supports 7 bits, Fiji only 4
            __asm__ volatile ("s_sleep 32\n"
                              "global_load_sbyte %0 %1 off glc slc\n "
                                "s_waitcnt vmcnt(0)" :
                                "=v"(net_status) :
                                "v"(&handle->status[threadId]));
        } while (net_status == 0);
        handle->status[threadId] = 0;
        __threadfence();
    }
    handle->profiler.endTimer(start, WAITING_ON_HOST);
}
}  // namespace rocshmem

#include "include/proxy-wasm/signature_util.h"
#include <fstream>
#include <iostream>
#include <sstream>
#include "test/utility.h"
#include "gtest/gtest.h"

namespace proxy_wasm {

// Test case for verifying a correctly signed Wasm module
TEST(TestSignatureUtil, GoodSignature) {
#ifndef PROXY_WASM_VERIFY_WITH_ED25519_PUBKEY
  FAIL() << "Built without a key for verifying signed Wasm modules.";
#endif
  const auto wasm_bytes = readTestWasmFile("abi_export.signed.with.key1.wasm");
  std::string result_message;
  EXPECT_TRUE(SignatureUtil::verifySignature(wasm_bytes, result_message));
  EXPECT_EQ(result_message, "Wasm signature OK (Ed25519)");
}

// Test case for verifying a Wasm module with an invalid signature
TEST(TestSignatureUtil, BadSignature) {
#ifndef PROXY_WASM_VERIFY_WITH_ED25519_PUBKEY
  FAIL() << "Built without a key for verifying signed Wasm modules.";
#endif
  const auto wasm_bytes = readTestWasmFile("abi_export.signed.with.key2.wasm");
  std::string result_message;
  EXPECT_FALSE(SignatureUtil::verifySignature(wasm_bytes, result_message));
  EXPECT_EQ(result_message, "Signature mismatch");
}

// Test case for verifying a Wasm module that lacks a signature section
TEST(TestSignatureUtil, NoSignature) {
#ifndef PROXY_WASM_VERIFY_WITH_ED25519_PUBKEY
  FAIL() << "Built without a key for verifying signed Wasm modules.";
#endif
  const auto wasm_bytes = readTestWasmFile("abi_export.wasm");
  std::string result_message;
  EXPECT_FALSE(SignatureUtil::verifySignature(wasm_bytes, result_message));
  EXPECT_EQ(result_message, "Custom Section \"signature_wasmsign\" not found");
}

} // namespace proxy_wasm

#include "BufferManager.hpp"
#include "PacketBuffer.hpp"
#include "ProfilingUtils.hpp"
#include <armnn/Exceptions.hpp>
#include <boost/test/unit_test.hpp>

using namespace armnn::profiling;

BOOST_AUTO_TEST_SUITE(BufferTests)

// Test basic packet buffer operations: write, commit, read, mark read
BOOST_AUTO_TEST_CASE(PacketBufferTest0)
{
    IPacketBufferPtr testBuffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(testBuffer->GetSize() == 0);

    // Write test values to the buffer at specific offsets
    WriteUint32(testBuffer, 0, 100);
    WriteUint32(testBuffer, 4, 200);
    WriteUint32(testBuffer, 8, 300);
    WriteUint32(testBuffer, 12, 400);

    // Commit 16 bytes of data
    testBuffer->Commit(16);
    BOOST_TEST(testBuffer->GetSize() == 16);

    // Read back and verify committed data
    auto readableData = testBuffer->GetReadableData();
    uint32_t val0 = ReadUint32(readableData, 0);
    uint32_t val1 = ReadUint32(readableData, 4);
    uint32_t val2 = ReadUint32(readableData, 8);
    uint32_t val3 = ReadUint32(readableData, 12);

    BOOST_TEST(val0 == 100);
    BOOST_TEST(val1 == 200);
    BOOST_TEST(val2 == 300);
    BOOST_TEST(val3 == 400);

    // Mark data as read and confirm buffer is empty
    testBuffer->MarkRead();
    BOOST_TEST(testBuffer->GetSize() == 0);
}

// Test using GetWritableData for writing instead of direct buffer access
BOOST_AUTO_TEST_CASE(PacketBufferTest1)
{
    IPacketBufferPtr testBuffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(testBuffer->GetSize() == 0);

    auto writableData = testBuffer->GetWritableData();
    WriteUint32(writableData, 0, 111);
    WriteUint32(writableData, 4, 222);
    WriteUint32(writableData, 8, 333);
    WriteUint32(writableData, 12, 444);

    testBuffer->Commit(16);
    BOOST_TEST(testBuffer->GetSize() == 16);

    auto readableData = testBuffer->GetReadableData();
    uint32_t r0 = ReadUint32(readableData, 0);
    uint32_t r1 = ReadUint32(readableData, 4);
    uint32_t r2 = ReadUint32(readableData, 8);
    uint32_t r3 = ReadUint32(readableData, 12);

    BOOST_TEST(r0 == 111);
    BOOST_TEST(r1 == 222);
    BOOST_TEST(r2 == 333);
    BOOST_TEST(r3 == 444);

    testBuffer->MarkRead();
    BOOST_TEST(testBuffer->GetSize() == 0);
}

// Test releasing a buffer before committing
BOOST_AUTO_TEST_CASE(PacketBufferReleaseTest) {
    IPacketBufferPtr testBuffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(testBuffer->GetSize() == 0);

    auto writableData = testBuffer->GetWritableData();
    WriteUint32(writableData, 0, 777);
    WriteUint32(writableData, 4, 888);
    WriteUint32(writableData, 8, 999);
    WriteUint32(writableData, 12, 111);

    testBuffer->Release();
    BOOST_TEST(testBuffer->GetSize() == 0);
}

// Test that committing more than buffer capacity throws an exception
BOOST_AUTO_TEST_CASE(PacketBufferCommitErrorTest)
{
    IPacketBufferPtr testBuffer = std::make_unique<PacketBuffer>(8);
    BOOST_CHECK_THROW(testBuffer->Commit(16);, armnn::RuntimeException);
}

// Test successful buffer reservation with exact size
BOOST_AUTO_TEST_CASE(BufferReserveTest)
{
    BufferManager manager(1, 512);
    unsigned int actualSize = 0;
    auto buffer = manager.Reserve(512, actualSize);

    BOOST_TEST(actualSize == 512);
    BOOST_TEST(buffer.get() != nullptr);
}

// Test rejection when requesting more than max buffer size
BOOST_AUTO_TEST_CASE(BufferReserveExceedingSpaceTest)
{
    BufferManager manager(1, 512);
    unsigned int actualSize = 0;
    auto buffer = manager.Reserve(1024, actualSize);

    BOOST_TEST(actualSize == 0);
    BOOST_TEST(buffer.get() == nullptr);
}

// Test exhaustion of available buffers
BOOST_AUTO_TEST_CASE(BufferExhaustionTest)
{
    BufferManager manager(1, 512);
    unsigned int actualSize = 0;
    auto buffer1 = manager.Reserve(512, actualSize);
    BOOST_TEST(actualSize == 512);
    BOOST_TEST(buffer1.get() != nullptr);

    auto buffer2 = manager.Reserve(512, actualSize);
    BOOST_TEST(actualSize == 0);
    BOOST_TEST(buffer2.get() == nullptr);
}

// Test multiple reservations with varying sizes
BOOST_AUTO_TEST_CASE(BufferReserveMultipleTest)
{
    BufferManager manager(3, 512);
    unsigned int size0 = 0;
    auto buf0 = manager.Reserve(512, size0);
    BOOST_TEST(size0 == 512);
    BOOST_TEST(buf0.get() != nullptr);

    unsigned int size1 = 0;
    auto buf1 = manager.Reserve(128, size1);
    BOOST_TEST(size1 == 128);
    BOOST_TEST(buf1.get() != nullptr);

    unsigned int size2 = 0;
    auto buf2 = manager.Reserve(512, size2);
    BOOST_TEST(size2 == 512);
    BOOST_TEST(buf2.get() != nullptr);

    unsigned int size3 = 0;
    auto buf3 = manager.Reserve(512, size3);
    BOOST_TEST(size3 == 0);
    BOOST_TEST(buf3.get() == nullptr);
}

// Test releasing a buffer makes it available again
BOOST_AUTO_TEST_CASE(BufferReleaseTest)
{
    BufferManager manager(2, 512);
    unsigned int size0 = 0;
    auto buf0 = manager.Reserve(512, size0);
    BOOST_TEST(size0 == 512);
    BOOST_TEST(buf0.get() != nullptr);

    unsigned int size1 = 0;
    auto buf1 = manager.Reserve(128, size1);
    BOOST_TEST(size1 == 128);
    BOOST_TEST(buf1.get() != nullptr);

    unsigned int size2 = 0;
    auto buf2 = manager.Reserve(512, size2);
    BOOST_TEST(size2 == 0);
    BOOST_TEST(buf2.get() == nullptr);

    manager.Release(buf0);
    auto buf3 = manager.Reserve(128, size2);
    BOOST_TEST(size2 == 128);
    BOOST_TEST(buf3.get() != nullptr);
}

// Test committing a buffer makes it readable but not reusable yet
BOOST_AUTO_TEST_CASE(BufferCommitTest)
{
    BufferManager manager(2, 512);
    unsigned int size0 = 0;
    auto buf0 = manager.Reserve(512, size0);
    BOOST_TEST(size0 == 512);
    BOOST_TEST(buf0.get() != nullptr);

    unsigned int size1 = 0;
    auto buf1 = manager.Reserve(128, size1);
    BOOST_TEST(size1 == 128);
    BOOST_TEST(buf1.get() != nullptr);

    unsigned int size2 = 0;
    auto buf2 = manager.Reserve(512, size2);
    BOOST_TEST(size2 == 0);
    BOOST_TEST(buf2.get() == nullptr);

    manager.Commit(buf0, 256);
    auto readableBuf = manager.GetReadableBuffer();
    BOOST_TEST(readableBuf.get() != nullptr);
    BOOST_TEST(readableBuf->GetSize() == 256);

    unsigned int size = 0;
    auto retryBuf = manager.Reserve(512, size);
    BOOST_TEST(size == 0);
    BOOST_TEST(retryBuf.get() == nullptr);
}

// Test full lifecycle: reserve, commit, read, release, reuse
BOOST_AUTO_TEST_CASE(BufferMarkReadTest)
{
    BufferManager manager(2, 512);
    unsigned int size0 = 0;
    auto buf0 = manager.Reserve(512, size0);
    BOOST_TEST(size0 == 512);
    BOOST_TEST(buf0.get() != nullptr);

    unsigned int size1 = 0;
    auto buf1 = manager.Reserve(128, size1);
    BOOST_TEST(size1 == 128);
    BOOST_TEST(buf1.get() != nullptr);

    unsigned int size2 = 0;
    auto buf2 = manager.Reserve(512, size2);
    BOOST_TEST(size2 == 0);
    BOOST_TEST(buf2.get() == nullptr);

    manager.Commit(buf0, 256);
    auto readableBuf = manager.GetReadableBuffer();
    BOOST_TEST(readableBuf.get() != nullptr);
    BOOST_TEST(readableBuf->GetSize() == 256);

    unsigned int size = 0;
    auto retryBuf = manager.Reserve(512, size);
    BOOST_TEST(size == 0);
    BOOST_TEST(retryBuf.get() == nullptr);

    manager.MarkRead(readableBuf);
    auto nextReadable = manager.GetReadableBuffer();
    BOOST_TEST(nextReadable.get() == nullptr);

    unsigned int size3 = 0;
    auto reusedBuf = manager.Reserve(56, size3);
    BOOST_TEST(size3 == 56);
    BOOST_TEST(reusedBuf.get() != nullptr);
}

BOOST_AUTO_TEST_SUITE_END()

#include "UEBoidManager.h"
#include "Components/BrushComponent.h"
#include "UEBoids.h"
#include "Runtime\Core\Public\Math\Box.h"
#include "Runtime\Engine\Classes\Kismet\KismetMathLibrary.h"
#include "Runtime/Engine/Classes/Components/InstancedStaticMeshComponent.h"

ABoidManager::ABoidManager(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	PrimaryActorTick.bCanEverTick = true;
	SetActorTickEnabled(true);
	instanceMesh = CreateDefaultSubobject<UInstancedStaticMeshComponent>(TEXT("instanceMesh"));
	instanceMesh->SetupAttachment(RootComponent);
	GetBrushComponent()->Mobility = EComponentMobility::Static;
	BrushColor = FColor(255, 255, 255, 255);
	bColored = true;
}

ABoidManager::~ABoidManager()
{
	boidList.Empty();
}

void ABoidManager::BeginPlay()
{
	Super::BeginPlay();
	instanceMesh->SetStaticMesh(meshReference);
	boidList.Reserve(parameters.numBoids);
	collisionBounds = GetComponentsBoundingBox(false);
	minAABB = collisionBounds.GetCenter() - collisionBounds.GetExtent();
	maxAABB = collisionBounds.GetCenter() + collisionBounds.GetExtent();

	for (int idx = 0; idx < parameters.numBoids; ++idx)
	{
		int listIndex = boidList.Emplace();
		BoidData& entry = boidList[listIndex];

		entry.position = (FMath::RandPointInBox(GetComponentsBoundingBox(true)) / GetTransform().GetScale3D());
		entry.velocity = FVector(FMath::VRand());
		FTransform transform;
		transform.SetLocation(entry.position);
		transform.SetScale3D(FVector(meshScaleValue));
		instanceMesh->AddInstance(transform);
	}
	parameters.Refresh();
}

void ABoidManager::Tick(float deltaTime)
{
	Super::Tick(deltaTime);
	int index = 0;
	for (BoidData& boid : boidList)
	{
		FVector centerPosition(0.f);
		FVector averageVelocity(0.f);
		FVector repulsion(0.f);
		int countCohesion = 0;
		int countAlignment = 0;
		int neighborIndex = 0;

		for (const BoidData& otherBoid : boidList)
		{
			if (index != neighborIndex)
			{
				float squaredDistance = FVector::DistSquared(boid.position, otherBoid.position);

				// Cohesion logic: accumulate positions within cohesion radius
				if (squaredDistance < parameters.cohesionRadiusSq)
				{
					centerPosition += otherBoid.position;
					countCohesion++;
				}

				// Avoidance logic: push away from nearby boids
				if (squaredDistance < parameters.avoidanceRadiusSq)
				{
					repulsion += boid.position - otherBoid.position;
				}

				// Alignment logic: accumulate velocities within alignment radius
				if (squaredDistance < parameters.alignmentRadiusSq)
				{
					averageVelocity += otherBoid.velocity;
				}
			}
			++neighborIndex;
		}

		// Compute mean positions and velocities
		if (countCohesion > 0)
			centerPosition /= static_cast<float>(countCohesion);

		FVector cohesionVector = (centerPosition - boid.position) * parameters.cohesionFactor;

		if (countAlignment > 0)
			averageVelocity /= static_cast<float>(countAlignment);

		FVector alignmentVector = averageVelocity * parameters.alignmentFactor;

		// Boundary avoidance logic
		FVector boundaryForce(0.f);
		if (boid.position.X < minAABB.X) {
			boundaryForce.X = parameters.boundaryRepulsion;
		} else if (boid.position.X > maxAABB.X) {
			boundaryForce.X = -parameters.boundaryRepulsion;
		}

		if (boid.position.Y < minAABB.Y) {
			boundaryForce.Y = parameters.boundaryRepulsion;
		} else if (boid.position.Y > maxAABB.Y) {
			boundaryForce.Y = -parameters.boundaryRepulsion;
		}

		if (boid.position.Z < minAABB.Z) {
			boundaryForce.Z = parameters.boundaryRepulsion;
		} else if (boid.position.Z > maxAABB.Z) {
			boundaryForce.Z = -parameters.boundaryRepulsion;
		}

		boundaryForce *= parameters.boundaryRepulsion;

		// Update velocity with combined forces and clamp to max speed
		FVector newVelocity = boid.velocity + (cohesionVector + repulsion + alignmentVector + boundaryForce);
		newVelocity = newVelocity.GetClampedToMaxSize(parameters.maxSpeed);
		boid.velocity = FMath::Lerp(boid.velocity, newVelocity, deltaTime * 10.f);

		// Update position
		boid.position += boid.velocity * deltaTime;

		// Update mesh instance transform
		FTransform currentTransform;
		instanceMesh->GetInstanceTransform(index, currentTransform);

		FQuat orientation = FRotationMatrix::MakeFromX(boid.velocity).ToQuat();
		currentTransform.SetRotation(orientation);
		currentTransform.SetLocation(boid.position);

		instanceMesh->UpdateInstanceTransform(index, currentTransform, false, index == boidList.Num() - 1, true);
		++index;
	}
}

#include "types.h"
#include <3ds.h>
#include "csvc.h"
#include "CTRPluginFrameworkImpl/Graphics.hpp"
#include "CTRPluginFrameworkImpl/System.hpp"
#include "CTRPluginFrameworkImpl/Preferences.hpp"
#include "CTRPluginFramework/System/System.hpp"
#include "CTRPluginFramework/Utils/Utils.hpp"
#include "CTRPluginFramework/Graphics/OSD.hpp"

namespace CTRPluginFramework
{
    using namespace CTRPluginFrameworkImpl::Services;

    #define REG(x)          *(vu32 *)(x)
    #define REG32(x)        *(vu32 *)((x) | (1u << 31))
    #define LCDREG(offset)  REG(this->_LCDSetup + offset)

    // Structure to hold framebuffers for both screens
    struct FramebufferLayout
    {
        u8  topScreenFB0[400 * 240 * 2];
        u8  topScreenFB1[400 * 240 * 2];
        u8  bottomScreenFB0[320 * 240 * 2];
        u8  bottomScreenFB1[320 * 240 * 2];
    } PACKED;

    // Static buffers for Screen objects
    static u8  _topScreenStorage[sizeof(ScreenImpl)] ALIGN(4);
    static u8  _botScreenStorage[sizeof(ScreenImpl)] ALIGN(4);

    ScreenImpl* ScreenImpl::Top = nullptr;
    ScreenImpl* ScreenImpl::Bottom = nullptr;

    // Determine bytes per pixel based on GPU format
    u32 GetBytesPerPixel(GSPGPU_FramebufferFormat fmt)
    {
        switch(fmt)
        {
            case GSP_RGBA8_OES:
                return 4;
            case GSP_BGR8_OES:
                return 3;
            case GSP_RGB565_OES:
            case GSP_RGB5_A1_OES:
            case GSP_RGBA4_OES:
                return 2;
        }
        return 3;
    }

    // Constructor for ScreenImpl
    ScreenImpl::ScreenImpl(const u32 lcdConfigAddr, const u32 fillColAddr, const bool isTop) :
        _LCDSetup(lcdConfigAddr),
        _FillColor(fillColAddr),
        _backlightOffset{isTop ? 0x40u : 0x840u},
        _currentBuffer(0),
        _width(isTop ? 400 : 320),
        _stride(0), _rowSize(0), _bytesPerPixel(0),
        _isTopScreen(isTop), _format()
    {
    }

    // Initialize screen objects and their framebuffers
    void    ScreenImpl::Initialize(void)
    {
        auto *fbArray = reinterpret_cast<FramebufferLayout *>(FwkSettings::Header->heapVA);

        Top = new (_topScreenStorage) ScreenImpl(0x10400400 | (1u << 31), (0x10202000 | (1u << 31)) + 0x204, true);
        Bottom = new (_botScreenStorage) ScreenImpl(0x10400500 | (1u << 31), (0x10202000 | (1u << 31)) + 0xA04);

        // Setup top screen framebuffers
        GSP::FrameBufferInfo* fb = &Top->_frameBufferInfo.fbInfo[0];
        fb->active_framebuf = 0;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(fbArray->topScreenFB0);
        fb->framebuf1_vaddr = fb->framebuf0_vaddr;
        fb->framebuf_widthbytesize = 240 * 2; // Force RGB565
        fb->format = 0x42; // GSP_RGB565_OES;
        fb->framebuf_dispselect = 0;

        fb = &Top->_frameBufferInfo.fbInfo[1];
        fb->active_framebuf = 1;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(fbArray->topScreenFB1);
        fb->framebuf1_vaddr = fb->framebuf0_vaddr;
        fb->framebuf_widthbytesize = 240 * 2; // Force RGB565
        fb->format = 0x42; // GSP_RGB565_OES;
        fb->framebuf_dispselect = 1;

        // Setup bottom screen framebuffers
        fb = &Bottom->_frameBufferInfo.fbInfo[0];
        fb->active_framebuf = 0;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(fbArray->bottomScreenFB0);
        fb->framebuf1_vaddr = nullptr;
        fb->framebuf_widthbytesize = 240 * 2; // Force RGB565
        fb->format = GSP_RGB565_OES;
        fb->framebuf_dispselect = 0;

        fb = &Bottom->_frameBufferInfo.fbInfo[1];
        fb->active_framebuf = 1;
        fb->framebuf0_vaddr = reinterpret_cast<u32 *>(fbArray->bottomScreenFB1);
        fb->framebuf1_vaddr = nullptr;
        fb->framebuf_widthbytesize = 240 * 2; // Force RGB565
        fb->format = GSP_RGB565_OES;
        fb->framebuf_dispselect = 1;
    }

    // Apply ctrpf-specific screen settings
    void    ScreenImpl::ApplyCtrpfScreens(void)
    {
        Top->_frameBufferInfo.header.screen = Top->_currentBuffer;
        Bottom->_frameBufferInfo.header.screen = Bottom->_currentBuffer;
        GSP::SetFrameBufferInfo(Top->_frameBufferInfo, 0, true);
        GSP::SetFrameBufferInfo(Bottom->_frameBufferInfo, 1, true);
    }

    // Apply fade effect across entire buffer
    void    ScreenImpl::Fade(const float alpha)
    {
        const u32 size = GetFrameBufferSize() / _bytesPerPixel;
        u8* bufPtr = GetLeftFrameBuffer();
        PrivColor::SetFormat(_format);

        for (int idx = size; idx > 0; --idx)
        {
            bufPtr = PrivColor::ToFramebuffer(bufPtr, PrivColor::FromFramebuffer(bufPtr).Fade(alpha));
        }
    }

    // Acquire screen with optional fade-in
    u32     ScreenImpl::Acquire(bool doFade)
    {
        if (ImportFromGsp())
            return -1;

        _frameBufferInfo.FillFrameBuffersFrom(_gameFrameBufferInfo);
        _format = GSP_RGB565_OES;
        _stride = 240 * 2;
        _bytesPerPixel = 2;
        _rowSize = 240;

        auto& fbInfo = _frameBufferInfo.fbInfo;
        _leftFrameBuffers[0] = reinterpret_cast<u32>(fbInfo[0].framebuf0_vaddr);
        _leftFrameBuffers[1] = reinterpret_cast<u32>(fbInfo[1].framebuf0_vaddr);
        _rightFrameBuffers[0] = reinterpret_cast<u32>(fbInfo[0].framebuf1_vaddr);
        _rightFrameBuffers[1] = reinterpret_cast<u32>(fbInfo[1].framebuf1_vaddr);

        _currentBuffer = _frameBufferInfo.header.screen = 1;

        if (doFade)
            Fade(0.3f);

        _currentBuffer = 0;
        Copy();

        _currentBuffer = 1;
        Flush();

        GSP::SetFrameBufferInfo(_frameBufferInfo, !_isTopScreen, true);
        _isGspAcquired = true;
        return 0;
    }

    // Import current game framebuffer info from GSP
    u32     ScreenImpl::ImportFromGsp(void)
    {
        if (_isGspAcquired)
            return 0;

        if (GSP::ImportFrameBufferInfo(_gameFrameBufferInfo, !_isTopScreen))
            return -1;

        const u32 activeIdx = _gameFrameBufferInfo.header.screen;
        if (!Process::CheckAddress(reinterpret_cast<u32>(_gameFrameBufferInfo.fbInfo[activeIdx].framebuf0_vaddr)))
            return -1;

        return 0;
    }

    // Release screen back to game control
    void    ScreenImpl::Release(void)
    {
        GSP::SetFrameBufferInfo(_gameFrameBufferInfo, !_isTopScreen, false);
        _isGspAcquired = false;
    }

    // Acquire custom framebuffers (e.g., plugin-rendered)
    void    ScreenImpl::Acquire(u32 leftAddr, u32 rightAddr, u32 pitch, u32 fmt, bool backup)
    {
        _currentBuffer = 1;
        _format = static_cast<GSPGPU_FramebufferFormat>(fmt & 7);
        _stride = pitch;
        _bytesPerPixel = GetBytesPerPixel(_format);
        _rowSize = _stride / _bytesPerPixel;

        _leftFrameBuffers[0] = leftAddr;
        _rightFrameBuffers[0] = rightAddr;

        _gameFrameBufferInfo.header.screen = 0;
        GSP::FrameBufferInfo& fb = _gameFrameBufferInfo.fbInfo[0];
        fb.active_framebuf = 0;
        fb.framebuf0_vaddr = reinterpret_cast<u32 *>(leftAddr);
        fb.framebuf1_vaddr = reinterpret_cast<u32 *>(rightAddr);
        fb.framebuf_widthbytesize = pitch;
        fb.format = fmt;
        fb.framebuf_dispselect = 0;
    }

    // Flush data cache for current buffer
    void    ScreenImpl::Flush(void)
    {
        u32 size = GetFrameBufferSize();
        svcFlushProcessDataCache(CUR_PROCESS_HANDLE, (u32)GetLeftFrameBuffer(), size);
    }

    // Invalidate data cache for current buffer
    void    ScreenImpl::Invalidate(void)
    {
        u32 size = GetFrameBufferSize();
        svcInvalidateProcessDataCache(CUR_PROCESS_HANDLE, (u32)GetLeftFrameBuffer(), size);
    }

    // Clear screen buffer
    void    ScreenImpl::Clear(bool applyFlag)
    {
        const u32 activeIdx = _gameFrameBufferInfo.header.screen;
        _frameBufferInfo.fbInfo[!_currentBuffer].FillFrameBufferFrom(_gameFrameBufferInfo.fbInfo[activeIdx]);
        Fade(0.3f);

        if (!applyFlag)
            return;

        s32 flags = GSP::__ldrex__(&GSP::BufferFlags);
        flags |= (_isTopScreen ? GSP::FB_TOP_NEED_CLEAR : GSP::FB_BOTTOM_NEED_CLEAR);
        GSP::__strex__(&GSP::BufferFlags, flags);
    }

    // Copy one buffer to another
    void    ScreenImpl::Copy(void)
    {
        u32 size = GetFrameBufferSize();
        u8* dst = GetLeftFrameBuffer();
        u8* src = GetLeftFrameBuffer(true);
        std::copy(src, src + size, dst);
    }

