    // Query screen type
    bool    ScreenImpl::IsTopScreen(void)
    {
        return _isTopScreen;
    }

    // Check if 3D is enabled on top screen
    bool    ScreenImpl::Is3DEnabled(void)
    {
        if (!_isTopScreen)
            return false;

        u32 left = _leftFrameBuffers[!_currentBuffer];
        u32 right = _rightFrameBuffers[!_currentBuffer];

        return right && right != left && *(float*)(0x1FF81080) > 0.f;
    }

    // Flash backlight
    void    ScreenImpl::Flash(Color &color)
    {
        u32 colorVal = (color.ToU32() & 0xFFFFFF) | 0x01000000;
        for (int i = 0; i < 0x64; i++)
        {
            REG(_FillColor) = colorVal;
            svcSleepThread(5000000); // 0.005s
        }
        REG(_FillColor) = 0;
    }

    // Clean up screens (New 3DS only)
    void    ScreenImpl::Clean(void)
    {
        if (!System::IsNew3DS())
            return;

        Top->Clear(true);
        Bottom->Clear(true);
    }

    // Switch between game/plugin framebuffers
    void    ScreenImpl::SwitchFrameBuffers(bool gameMode)
    {
        if (gameMode)
        {
            Top->Release();
            Bottom->Release();
            GSP::WaitBufferSwapped(3);
        }
        else
        {
            Top->_frameBufferInfo.header.screen = Top->_currentBuffer;
            Bottom->_frameBufferInfo.header.screen = Bottom->_currentBuffer;
            GSP::SetFrameBufferInfo(Top->_frameBufferInfo, 0, true);
            GSP::SetFrameBufferInfo(Bottom->_frameBufferInfo, 1, true);
            GSP::WaitBufferSwapped(3);
            Top->_isGspAcquired = true;
            Bottom->_isGspAcquired = true;
        }
    }

    // Apply fading and swap buffers
    void    ScreenImpl::ApplyFading(void)
    {
        Top->Fade(0.5f);
        Bottom->Fade(0.5f);
        Top->SwapBuffer();
        Bottom->SwapBuffer();
        GSP::WaitBufferSwapped(3);
        Top->Copy();
        Bottom->Copy();
    }

    // GPU register definitions
    #define GPU_PSC0_CNT                REG32(0x1040001C)
    #define GPU_PSC1_CNT                REG32(0x1040002C)
    #define GPU_TRANSFER_CNT            REG32(0x10400C18)
    #define GPU_CMDLIST_CNT             REG32(0x104018F0)

    // Acquire both screens from GSP
    u32     ScreenImpl::AcquireFromGsp(bool fade)
    {
        while ((GPU_PSC0_CNT | GPU_PSC1_CNT | GPU_TRANSFER_CNT | GPU_CMDLIST_CNT) & 1);
        u32 err = Top->Acquire(fade) | Bottom->Acquire(fade);
        return err;
    }

    // Validate GSP framebuffers
    u32     ScreenImpl::CheckGspFrameBuffersInfo()
    {
        return Top->ImportFromGsp() | Bottom->ImportFromGsp();
    }

    // Swap current buffer
    void    ScreenImpl::SwapBuffer(void)
    {
        svcFlushDataCacheRange(GetLeftFrameBuffer(), GetFrameBufferSize());
        GSP::SwapBuffer(!_isTopScreen);
        _currentBuffer = !_currentBuffer;
    }

    // Internal buffer toggle without GPU interaction
    void    ScreenImpl::SwapBufferInternal(void)
    {
        _currentBuffer = !_currentBuffer;
    }

    // Backlight getters/setters
    u32     ScreenImpl::GetBacklight(void)
    {
        return REG32(0x10202200 + _backlightOffset);
    }

    void    ScreenImpl::SetBacklight(u32 val)
    {
        REG32(0x10202200 + _backlightOffset) = val;
    }

    // Format and dimension accessors
    GSPGPU_FramebufferFormat   ScreenImpl::GetFormat(void) const
    {
        return _format;
    }

    u16     ScreenImpl::GetWidth(void) const
    {
        return _width;
    }

    u32     ScreenImpl::GetStride(void) const
    {
        return _stride;
    }

    u32     ScreenImpl::GetRowSize(void) const
    {
        return _rowSize;
    }

    u32     ScreenImpl::GetBytesPerPixel(void) const
    {
        return _bytesPerPixel;
    }

    u32     ScreenImpl::GetFrameBufferSize(void) const
    {
        return _stride * _width;
    }

    u32     ScreenImpl::GetCurrentBufferID(void) const
    {
        return _currentBuffer;
    }

    void    ScreenImpl::GetFrameBufferInfos(int &pitch, int &bpp, GSPGPU_FramebufferFormat &fmt) const
    {
        pitch = _stride;
        bpp = _bytesPerPixel;
        fmt = _format;
    }

    // Left framebuffer accessors
    u8      *ScreenImpl::GetLeftFrameBuffer(bool useCurrent)
    {
        return reinterpret_cast<u8*>(_leftFrameBuffers[useCurrent ? _currentBuffer : !_currentBuffer]);
    }

    u8      *ScreenImpl::GetLeftFrameBuffer(int x, int y)
    {
        x = std::max(x, 0);
        x = std::min(x, (_isTopScreen ? 400 : 320));
        y = std::max(y, 0);
        y = std::min(y, 240);

        y += _rowSize - 240;
        u32 offset = (_rowSize - 1 - y + x * _rowSize) * _bytesPerPixel;
        return reinterpret_cast<u8*>(_leftFrameBuffers[!_currentBuffer]) + offset;
    }

    // Right framebuffer accessors (top screen only)
    u8      *ScreenImpl::GetRightFrameBuffer(bool useCurrent)
    {
        if (!_isTopScreen)
            return nullptr;
        return reinterpret_cast<u8*>(_rightFrameBuffers[useCurrent ? _currentBuffer : !_currentBuffer]);
    }

    u8      *ScreenImpl::GetRightFrameBuffer(int x, int y)
    {
        if (!_isTopScreen)
            return nullptr;

        x = std::max(x, 0);
        x = std::min(x, (_isTopScreen ? 400 : 320));
        y = std::max(y, 0);
        y = std::min(y, 240);

        y += _rowSize - 240;
        u32 offset = (_rowSize - 1 - y + x * _rowSize) * _bytesPerPixel;
        return reinterpret_cast<u8*>(_rightFrameBuffers[!_currentBuffer]) + offset;
    }

    // Convert address to coordinates
    void    ScreenImpl::GetPosFromAddress(u32 addr, int &x, int &y)
    {
        addr -= _leftFrameBuffers[!_currentBuffer];
        x = addr / (_rowSize * _bytesPerPixel);
        y = _rowSize - 1 - ((addr / _bytesPerPixel) - (_rowSize * x));
        y -= _rowSize - 240;
    }
}

