    // TODO
}

TEST_F(InteractomeTestSuite, NodeListTypeVerification) {
    ASSERT_EQ(typeid(network.getNodes()), typeid(std::vector<int>));
    ASSERT_THAT(network.getNodes(), UnorderedElementsAreArray({1, 2, 3, 4, 5}));
}

TEST_F(InteractomeTestSuite, AddingNewNodeSucceeds) {
    network.addNode(9);
    ASSERT_THAT(network.getNodes(), Contains(9));
}

TEST_F(InteractomeTestSuite, NetworkReconstructionFromNewInteractionSet) {
    std::vector<std::pair<int, int>> newEdges = {
            std::make_pair(11, 12),
            std::make_pair(12, 13),
            std::make_pair(14, 15)
    };
    network = Interactome(newEdges);
    ASSERT_EQ(5u, network.getNodes().size());
    ASSERT_THAT(network.getNodes(), UnorderedElementsAreArray({11, 12, 13, 14, 15}));
}

