    std::vector<int> adjacentNodes = network.getInteractors(2);
    ASSERT_EQ(adjacentNodes.size(), 2u);
    ASSERT_THAT(adjacentNodes, UnorderedElementsAreArray({1, 3}));
    ASSERT_THAT(adjacentNodes, Not(AnyOf(Contains(4), Contains(5))));
}

