    ASSERT_EQ(network.getNodeName(2), "B2");
    ASSERT_EQ(network.getNodeName(5), "E2");
}

TEST_F(InteractomeTestSuite, SequentialNameUpdatesReplacePreviousOnes) {
    std::string firstBatch = "1 A1\n3 C1\n2 B1\n4 D1\n5 E1";
    std::istringstream buffer1(firstBatch);
    network.readNodeNames(buffer1);

    std::string secondBatch = "1 A2\n3 C2\n2 B2\n4 D2\n5 E2";
    std::istringstream buffer2(secondBatch);
