#include <bits/stdc++.h>
using namespace std;

using i64 = long long;
const int LIMIT = 100007; // slightly larger than original MAX
const i64 BIG_NUM = 10000000007LL; // slightly larger than original INF

i64 rows, cols;
i64 best_diff = BIG_NUM;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Input dimensions
    cin >> rows >> cols;

    // First approach: horizontal cut at row i, then vertical cuts near midpoint
    for (i64 cut1 = 1; cut1 < rows; ++cut1) {
        i64 center = (cut1 + rows) / 2;
        i64 area_top = cols * cut1;
        for (i64 cut2 = max(center - 2, cut1); cut2 <= min(center + 2, rows); ++cut2) {
            i64 area_mid = (cut2 - cut1) * cols;
            i64 area_bot = (rows - cut2) * cols;
            i64 diff = max({area_top, area_mid, area_bot}) - min({area_top, area_mid, area_bot});
            best_diff = min(best_diff, diff);
        }
    }

    // Second approach: horizontal cut at row i, then vertical split near middle column
    for (i64 cut1 = 1; cut1 < rows; ++cut1) {
        i64 center_col = cols / 2;
        i64 area_top = cols * cut1;
        for (i64 col_split = max(center_col - 2, 0LL); col_split <= min(center_col + 2, cols); ++col_split) {
            i64 area_left = (rows - cut1) * col_split;
            i64 area_right = (rows - cut1) * (cols - col_split);
            i64 diff = max({area_top, area_left, area_right}) - min({area_top, area_left, area_right});
            best_diff = min(best_diff, diff);
        }
    }

    // Third approach: vertical cut at column i, then horizontal cuts near midpoint
    for (i64 cut1 = 1; cut1 < cols; ++cut1) {
        i64 center = (cut1 + cols) / 2;
        i64 area_left = rows * cut1;
        for (i64 cut2 = max(center - 2, cut1); cut2 <= min(center + 2, cols); ++cut2) {
            i64 area_mid = rows * (cut2 - cut1);
            i64 area_right = rows * (cols - cut2);
            i64 diff = max({area_left, area_mid, area_right}) - min({area_left, area_mid, area_right});
            best_diff = min(best_diff, diff);
        }
    }

    // Fourth approach: vertical cut at column i, then horizontal split near middle row
    for (i64 cut1 = 1; cut1 < cols; ++cut1) {
        i64 center_row = rows / 2;
        i64 area_left = rows * cut1;
        for (i64 row_split = max(center_row - 2, 0LL); row_split <= min(center_row + 2, rows); ++row_split) {
            i64 area_top = row_split * (cols - cut1);
            i64 area_bot = (rows - row_split) * (cols - cut1);
            i64 diff = max({area_left, area_top, area_bot}) - min({area_left, area_top, area_bot});
            best_diff = min(best_diff, diff);
        }
    }

    cout << best_diff << '\n';
    return 0;
}

#include "BBE/BrotBoxEngine.h"
#include <iostream>

constexpr int SCREEN_WIDTH = 1280;
constexpr int SCREEN_HEIGHT = 720;

class GameExample : public bbe::Game
{
    bbe::Vector2 projectionDirection = bbe::Vector2{ 4, 1 }.normalize();
    bbe::RectangleRotated rectA;
    bbe::RectangleRotated rectB;

    static constexpr float rotationSpeed = 1.0f;

    virtual void onStart() override
    {
        rectA = bbe::RectangleRotated(100, 200, 100, 140, 0);
        rectB = bbe::RectangleRotated(400, 400, 40, 20, 0);
    }

    virtual void update(float deltaTime) override
    {
        float currentRotationA = rectA.getRotation() + deltaTime * rotationSpeed;
        rectA.setRotation(currentRotationA);

        float currentRotationB = rectB.getRotation() + deltaTime * 0.4f * rotationSpeed;
        rectB.setRotation(currentRotationB);

        rectB.setX(getMouseX());
        rectB.setY(getMouseY());

        if (isMouseDown(bbe::MouseButton::LEFT))
        {
            projectionDirection = getMouse().normalize();
        }
    }

    virtual void draw3D(bbe::PrimitiveBrush3D & brush) override
    {
    }

    virtual void draw2D(bbe::PrimitiveBrush2D & brush) override
    {
        brush.setColorRGB(1, 1, 1);
        brush.fillRect(rectA);

        auto corners = rectA.getVertices();
        brush.setColorRGB(1, 0, 0);
        brush.fillLineStrip(corners, true);

        const bbe::RectangleRotated::ProjectionResult result = rectA.project(projectionDirection);
        brush.setColorRGB(0, 1, 0);
        brush.fillLine(projectionDirection * result.start, projectionDirection * result.stop);

        auto projectedPoints = bbe::Math::project(corners, projectionDirection);
        assert(projectedPoints.getLength() == corners.getLength());

        for (size_t index = 0; index < projectedPoints.getLength(); ++index)
        {
            brush.fillLine(corners[index], projectedPoints[index]);
        }

        auto faceNormals = rectA.getNormals();
        brush.setColorRGB(0, 0, 1);
        for (size_t index = 0; index < faceNormals.getLength(); ++index)
        {
            brush.fillLine(corners[index], faceNormals[index] * 10 + corners[index]);
        }

        if (rectB.intersects(rectA))
        {
            brush.setColorRGB(0, 1, 1);
        }
        else
        {
            brush.setColorRGB(1, 1, 0);
        }

        brush.fillRect(rectB);
    }

    virtual void onEnd() override
    {
    }
};

int main()
{
    GameExample* gameInstance = new GameExample();
    gameInstance->start(SCREEN_WIDTH, SCREEN_HEIGHT, "Rotating Rectangles Demo");
    return 0;
}

