#include "indirect_inode.hpp"
namespace FSFS {
IndirectInode::IndirectInode(const inode_block& block) : inode(block) { reset(); }
int32_t IndirectInode::get_pointer(int32_t index) const { return indirect_data[index]; }
int32_t IndirectInode::get_last_indirect_pointer(int32_t block_index) const {
    auto iter = std::next(indirect_blocks.cbegin(), block_index);
    if (iter == indirect_blocks.cend()) {
        return fs_nullptr;
    }
    return *iter;
}
int32_t IndirectInode::store(Block& data_storage, BlockBitmap& free_map, PtrsLList& pending_ptrs) {
    if (inode.indirect_inode_ptr == fs_nullptr) {
        throw std::runtime_error("Base indirect pointer of inode is invalid.");
    }
    if (pending_ptrs.empty()) {
        return 0;
    }
    if (indirect_blocks.empty()) {
        indirect_blocks.push_front(inode.indirect_inode_ptr);
    }
    // Phase 1: Populate new pointers into local list
    //
    int32_t existing_indirect_count = std::max(data_storage.bytes_to_blocks(inode.file_len) - meta_direct_pointers, 0);
    int32_t new_count = std::distance(pending_ptrs.begin(), pending_ptrs.end());
    int32_t remaining_to_write = new_count;
    indirect_data.resize(indirect_data.size() + new_count);
    for (int32_t i = 0; !pending_ptrs.empty(); ++i) {
        indirect_data[existing_indirect_count + i] = pending_ptrs.front();
        pending_ptrs.pop_front();
    }
    // Phase 2: Write to existing indirect block
    //
    int32_t offset_in_current = existing_indirect_count % (data_storage.get_n_addresses_per_block() - 1);
    int32_t available_slots = (data_storage.get_n_addresses_per_block() - 1) - offset_in_current;
    int32_t to_write_now = std::min(available_slots, remaining_to_write);
    if (to_write_now > 0) {
        uint8_t* buffer = cast_to_data(&indirect_data[existing_indirect_count]);
        int32_t block_addr = data_storage.data_n_to_block_n(indirect_blocks.front());
        data_storage.write(block_addr, buffer, offset_in_current * sizeof(int32_t),
                           to_write_now * sizeof(int32_t));
        remaining_to_write -= to_write_now;
        existing_indirect_count += to_write_now;
    }
    // Phase 3: Allocate additional indirect blocks and write remaining pointers
    //
    while (remaining_to_write > 0) {
        // Create new block
        int32_t new_block_addr = free_map.next_free(0);
        if (new_block_addr == fs_nullptr) {
            reset();
            return new_count - remaining_to_write;
        }
        free_map.set_status(new_block_addr, 1);
        int32_t prev_block_addr = data_storage.data_n_to_block_n(indirect_blocks.front());
        indirect_blocks.push_front(new_block_addr);
        // Link to previous block
        data_storage.write(prev_block_addr, cast_to_data(&new_block_addr), -static_cast<int32_t>(sizeof(int32_t)), sizeof(int32_t));
        // Store pointers in new block
        uint8_t* ptr_buffer = cast_to_data(&indirect_data[existing_indirect_count]);
        to_write_now = std::min(data_storage.get_n_addresses_per_block() - 1, remaining_to_write);
        int32_t current_block_addr = data_storage.data_n_to_block_n(indirect_blocks.front());
        data_storage.write(current_block_addr, ptr_buffer, 0, to_write_now * sizeof(int32_t));
        remaining_to_write -= to_write_now;
        existing_indirect_count += to_write_now;
    }
    reset();
    return new_count - remaining_to_write;
}
void IndirectInode::reset() {
    indirect_data.clear();
    indirect_blocks.clear();
}
void IndirectInode::fetch(Block& data_storage) {
    // Phase 1: Validate presence of indirect blocks
    //
    int32_t needed_indirect_count = data_storage.bytes_to_blocks(inode.file_len) - meta_direct_pointers;
    if ((needed_indirect_count <= 0) || (inode.indirect_inode_ptr == fs_nullptr)) {
        return;
    }
    reset();
    indirect_data.resize(needed_indirect_count);
    int32_t current_block_ptr = inode.indirect_inode_ptr;
    indirect_blocks.push_front(current_block_ptr);
    // Phase 2: Load full indirect blocks
    //
    int32_t entries_per_block = data_storage.get_n_addresses_per_block() - 1;
    int32_t bytes_per_indirect_block = data_storage.get_block_size() - sizeof(int32_t);
    int32_t loaded_count = 0;
    int32_t total_blocks = needed_indirect_count / entries_per_block;
    for (int32_t block_num = 0; block_num < total_blocks; ++block_num) {
        uint8_t* buffer = cast_to_data(&indirect_data[loaded_count]);
        int32_t addr = data_storage.data_n_to_block_n(current_block_ptr);
        data_storage.read(addr, buffer, 0, bytes_per_indirect_block);
        data_storage.read(addr, cast_to_data(&current_block_ptr), bytes_per_indirect_block, sizeof(int32_t));
        indirect_blocks.push_front(current_block_ptr);
        loaded_count += entries_per_block;
    }
    // Phase 3: Load remaining pointers from last block
    //
    if (loaded_count < needed_indirect_count) {
        uint8_t* buffer = cast_to_data(&indirect_data[loaded_count]);
        int32_t remaining = needed_indirect_count - loaded_count;
        int32_t addr = data_storage.data_n_to_block_n(current_block_ptr);
        data_storage.read(addr, buffer, 0, remaining * sizeof(int32_t));
    }
}
}

#include "Animation_RuntimeGraph_RootMotionRecorder.h"
