#if KRG_DEVELOPMENT_TOOLS
namespace KRG::Animation
{
    RootMotionRecorder::RootMotionRecorder()
    {
        m_transformHistory.reserve( s_maxRecordedFrames );
    }

    void RootMotionRecorder::SetDebugMode( DebugMode newMode )
    {
        // Reset internal state if entering visualization mode
        if ( m_currentDebugMode < DebugMode::DrawRecordedRootMotion && newMode >= DebugMode::DrawRecordedRootMotion )
        {
            m_nextWriteIndex = 0;
            m_transformHistory.clear();
        }
        m_currentDebugMode = newMode;
    }

    void RootMotionRecorder::BeginCharacterUpdate( Transform const& worldTransform )
    {
        m_initialWorldTransform = worldTransform;
        m_actionList.clear();
    }

    void RootMotionRecorder::FinishCharacterUpdate( Transform const& worldTransform )
    {
        m_finalWorldTransform = worldTransform;

        //-------------------------------------------------------------------------
        if ( m_currentDebugMode >= DebugMode::DrawRecordedRootMotion )
        {
            KRG_ASSERT( m_nextWriteIndex < s_maxRecordedFrames );

            // Ensure space in history buffer before writing
            if ( m_nextWriteIndex == static_cast<int32>( m_transformHistory.size() ) )
            {
                m_transformHistory.emplace_back();
            }

            // Populate transform record based on action data
            if ( m_actionList.empty() )
            {
                m_transformHistory[m_nextWriteIndex].m_actual   = m_finalWorldTransform;
                m_transformHistory[m_nextWriteIndex].m_predicted = m_finalWorldTransform;
            }
            else
            {
                m_transformHistory[m_nextWriteIndex].m_actual   = m_finalWorldTransform;
                m_transformHistory[m_nextWriteIndex].m_predicted = m_actionList.back().m_rootMotionDelta * m_initialWorldTransform;
            }

            // Advance circular buffer index
            m_nextWriteIndex++;
            if ( m_nextWriteIndex >= s_maxRecordedFrames )
            {
                m_nextWriteIndex = 0;
            }
        }
    }

    void RootMotionRecorder::RenderDebug( Drawing::DrawContext& context )
    {
        if ( m_currentDebugMode == DebugMode::DrawRoot )
        {
            RenderRootBone( context, m_finalWorldTransform );
        }
        else if ( m_currentDebugMode == DebugMode::DrawRecordedRootMotion || m_currentDebugMode == DebugMode::DrawRecordedRootMotionAdvanced )
        {
            bool const showDetailedView = ( m_currentDebugMode == DebugMode::DrawRecordedRootMotionAdvanced );

            auto DrawSegment = [this, &context, showDetailedView]( int32 idxA, int32 idxB, int32 colorIdx )
            {
                static Vector const offsetUp( 0.0f, 0.0f, 0.25f );
                static Color const actualColors[2] = { Colors::Blue, Colors::Red };
                static Color const predictedColors[2] = { Colors::Cyan, Colors::Magenta };

                // Draw actual motion path
                context.DrawLine(
                    m_transformHistory[idxA].m_actual.GetTranslation(),
                    m_transformHistory[idxB].m_actual.GetTranslation(),
                    actualColors[colorIdx],
                    3.0f );

                context.DrawAxis( m_transformHistory[idxB].m_actual, 0.1f, 2.0f );

                if ( showDetailedView )
                {
                    // Draw predicted motion path (offset vertically)
                    context.DrawLine(
                        m_transformHistory[idxA].m_predicted.GetTranslation() + offsetUp,
                        m_transformHistory[idxB].m_predicted.GetTranslation() + offsetUp,
                        predictedColors[colorIdx],
                        3.0f );

                    Transform axisTfm = m_transformHistory[idxB].m_predicted;
                    axisTfm.AddTranslation( offsetUp );
                    context.DrawAxis( axisTfm, 0.1f, 2.0f );
                }
            };

            //-------------------------------------------------------------------------
            int32 const totalEntries = static_cast<int32>( m_transformHistory.size() );
            bool const isFull = ( totalEntries == s_maxRecordedFrames );

            if ( !isFull )
            {
                // Draw sequential entries up to current write position
                for ( int32 i = 1; i < m_nextWriteIndex; ++i )
                {
                    int32 const c = Math::IsEven( i ) ? 0 : 1;
                    DrawSegment( i - 1, i, c );
                }
            }
            else
            {
                // Circular buffer: draw from nextWriteIndex+1 to end
                for ( int32 i = m_nextWriteIndex + 1; i < totalEntries; ++i )
                {
                    int32 const c = Math::IsEven( i ) ? 0 : 1;
                    DrawSegment( i - 1, i, c );
                }

                // Then wrap around: from 1 to nextWriteIndex
                for ( int32 i = 1; i < m_nextWriteIndex; ++i )
                {
                    int32 const c = Math::IsEven( i ) ? 0 : 1;
                    DrawSegment( i - 1, i, c );
                }

                // Connect wrap-around loop
                if ( m_nextWriteIndex != 0 )
                {
                    DrawSegment( 0, s_maxRecordedFrames - 1, 0 );
                }
            }
        }
    }
}
