namespace Tomizawa_Edmonds_Karp {
struct graph {
  typedef int flow_type;
  typedef int cost_type;
  struct edge {
    int src, dst;
    flow_type capacity, flow;
    cost_type cost;
    size_t rev;
  };
  vector<edge> edges;
  void add_edge(int src, int dst, flow_type cap, cost_type cost) {
    adj[src].push_back({src, dst, cap, 0, cost, adj[dst].size()});
    adj[dst].push_back({dst, src, 0, 0, -cost, adj[src].size()-1});
  }
  int n;
  vector<vector<edge>> adj;
  graph(int n) : n(n), adj(n) { }
  pair<flow_type, cost_type> min_cost_max_flow(int s, int t) {
    flow_type flow = 0;
    cost_type cost = 0;
    for (int u = 0; u < n; ++u) // initialize
      for (auto &e: adj[u]) e.flow = 0;
    vector<cost_type> p(n, 0);
    auto rcost = [&](edge e) { return e.cost + p[e.src] - p[e.dst]; };
    for (int iter = 0; ; ++iter) {
      vector<int> prev(n, -1); prev[s] = 0;
      vector<cost_type> dist(n, INF); dist[s] = 0;
      if (iter == 0) { // use Bellman-Ford to remove negative cost edges
        vector<int> count(n); count[s] = 1;
        queue<int> que; 
        for (que.push(s); !que.empty(); ) {
          int u = que.front(); que.pop();
          count[u] = -count[u];
          for (auto &e: adj[u]) {
            if (e.capacity > e.flow && dist[e.dst] > dist[e.src] + rcost(e)) {
              dist[e.dst] = dist[e.src] + rcost(e);
              prev[e.dst] = e.rev;
              if (count[e.dst] <= 0) {
                count[e.dst] = -count[e.dst] + 1;
                que.push(e.dst);
              }
            }
          }
        }
      } else { // use Dijkstra 
        typedef pair<cost_type, int> node;
        priority_queue<node, vector<node>, greater<node>> que;
        que.push({0, s});
        while (!que.empty()) {
          node a = que.top(); que.pop();
          if (a.snd == t) break;
          if (dist[a.snd] > a.fst) continue;
          for (auto e: adj[a.snd]) {
            if (e.capacity > e.flow && dist[e.dst] > a.fst + rcost(e)) {
              dist[e.dst] = dist[e.src] + rcost(e);
              prev[e.dst] = e.rev;
              que.push({dist[e.dst], e.dst});
            }
          }
        }
      }
      if (prev[t] == -1) break;
      for (int u = 0; u < n; ++u) 
        if (dist[u] < dist[t]) p[u] += dist[u] - dist[t];
      function<flow_type(int,flow_type)> augment = [&](int u, flow_type cur) {
        if (u == s) return cur;
        edge &r = adj[u][prev[u]], &e = adj[r.dst][r.rev];
        flow_type f = augment(e.src, min(e.capacity - e.flow, cur));
        e.flow += f; r.flow -= f;
        return f;
      };
      flow_type f = augment(t, INF);
      flow += f;
      cost += f * (p[t] - p[s]);
    }
    return {flow, cost};
  }
};
}

// === tick a time ===
#include <ctime>
double tick() {
  static clock_t oldtick;
  clock_t newtick = clock();
  double diff = 1.0*(newtick - oldtick) / CLOCKS_PER_SEC;
  oldtick = newtick;
  return diff;
}
int main() {
  for (int seed_val = 0; seed_val < 10000; ++seed_val) {
    cout << "--------------------" << endl;
    cout << "seed = " << seed_val << endl;
    srand(seed_val);
    int node_count = 200;
    Tomizawa_Edmonds_Karp::graph g1(node_count);
    NegativeCycleCanceling::graph g2(node_count);
    /*
    g2.add_edge(0, 1, 1, 1);
    g2.add_edge(1, 2, 1, 1);
    g2.add_edge(2, 3, 1, 1);
    g2.add_edge(1, 3, 1, 4);
    */
    /*
    g2.add_edge(0, 1, 1, 1);
    g2.add_edge(1, 2, 1, 1);
    g2.add_edge(2, 3, 1, 1);
    g2.add_edge(1, 3, 1, 1);
    */
    for (int i = 0; i < node_count; ++i) {
      for (int j = 0; j < node_count; ++j) {
        if (i == j) continue;
        if (rand() % 2 == 0) {
          int a = 1 + rand() % 10; 
          int b = 1 + rand() % 10;
          g1.add_edge(i, j, a, b);
          g2.add_edge(i, j, a, b);
        } 
      }
    }
    int source = 0, target = node_count-1;
    tick();
    auto res1 = g1.min_cost_max_flow(source, target);
    cout << res1.fst << " " << res1.second << " " << tick() << endl;
    auto res2 = g2.min_cost_max_flow(source, target);
    cout << res2.fst << " " << res2.second << " " << tick() << endl;
    if (res1.snd != res2.snd) break;
  }
}

#include "GBlender.h"
#include "GEngineDevice.h"

GBlender::GBlender()
	: mBlendDesc(D3D11_BLEND_DESC()), mState(nullptr), mColor(GVector4D())
{
	EMPTY_STATEMENT;
}

GBlender::~GBlender()
{
	if (nullptr != mState)
	{
		mState->Release();
		mState = nullptr;
	}
}

bool GBlender::Create()
{
	mBlendDesc.AlphaToCoverageEnable = false;
	mBlendDesc.IndependentBlendEnable = false;
	mBlendDesc.RenderTarget[0].BlendEnable = true;
	mBlendDesc.RenderTarget[0].RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE::D3D11_COLOR_WRITE_ENABLE_ALL;
	mBlendDesc.RenderTarget[0].BlendOp = D3D11_BLEND_OP::D3D11_BLEND_OP_ADD;
	mBlendDesc.RenderTarget[0].BlendOpAlpha = D3D11_BLEND_OP::D3D11_BLEND_OP_ADD;

	mBlendDesc.RenderTarget[0].SrcBlend = D3D11_BLEND::D3D11_BLEND_SRC_ALPHA;
	mBlendDesc.RenderTarget[0].SrcBlendAlpha = D3D11_BLEND::D3D11_BLEND_ONE;
	mBlendDesc.RenderTarget[0].DestBlend = D3D11_BLEND::D3D11_BLEND_INV_SRC_ALPHA;
	mBlendDesc.RenderTarget[0].DestBlendAlpha = D3D11_BLEND::D3D11_BLEND_ZERO;

	return Create(mBlendDesc);
}

bool GBlender::Create(const D3D11_BLEND_DESC& desc)
{
	if (&mBlendDesc != &desc)
	{
		mBlendDesc = desc;
	}

	if (FAILED(GEngineDevice::MainDevice().GetIDevice().CreateBlendState(&mBlendDesc, &mState)))
	{
		CRASH_PROG;
		return false;
	}

	return true;
}

void GBlender::Update()
{
	GEngineDevice::MainDevice().GetIContext().OMSetBlendState(
		mState, mColor.Arr, 0xffffffff /* default value */
	);
}

