#include <memory.h>
#include "HAtomicOperator.h"

namespace app {

CMemoryHub::CMemoryHub() :
    mReferenceCount(1) {
    setMemoryPageSize(32);
}

CMemoryHub::~CMemoryHub() {
    APP_ASSERT(0 == mReferenceCount);
}

void CMemoryHub::grab() {
    APP_ASSERT(mReferenceCount > 0);
    AppAtomicIncrementFetch(&mReferenceCount);
}

void CMemoryHub::drop() {
    s32 result = AppAtomicDecrementFetch(&mReferenceCount);
    APP_ASSERT(result >= 0);
    if (0 == result) {
        delete this;
    }
}

void CMemoryHub::setMemoryPageSize(s32 factor) {
    mPool128.setPageSize(128 * factor);
    mPool512.setPageSize(512 * factor);
    mPool2048.setPageSize(2048 * factor);
    mPool8192.setPageSize(8192 * factor);
    mPool10K.setPageSize(10240 * factor);
}

s8* CMemoryHub::allocateAndZero(u64 sizeRequested, u64 alignment/* = sizeof(void*)*/) {
    s8* ptr = allocate(sizeRequested, alignment);
    memset(ptr, 0, sizeRequested);
    return ptr;
}

s8* CMemoryHub::allocate(u64 sizeRequested, u64 alignment/* = sizeof(void*)*/) {
#if defined(APP_DEBUG)
    grab();
#endif

    alignment = alignment < sizeof(SMemHead) ? sizeof(SMemHead) : alignment;
    sizeRequested += alignment;
    sizeRequested = APP_ALIGN_DATA(sizeRequested, alignment);

#ifdef APP_DISABLE_BYTE_POOL
    return malloc(sizeRequested);
#endif

    s8* output;

    if (sizeRequested <= 128) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.lock();
#endif
        output = (s8*) mPool128.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.unlock();
#endif
        return getUserPointer(output, alignment, EMT_128);
    }

    if (sizeRequested <= 512) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.lock();
#endif
        output = (s8*) mPool512.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.unlock();
#endif
        return getUserPointer(output, alignment, EMT_512);
    }

    if (sizeRequested <= 2048) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.lock();
#endif
        output = (s8*) mPool2048.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.unlock();
#endif
        return getUserPointer(output, alignment, EMT_2048);
    }

    if (sizeRequested <= 8192) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.lock();
#endif
        output = (s8*) mPool8192.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.unlock();
#endif
        return getUserPointer(output, alignment, EMT_8192);
    }

    if (sizeRequested <= 10240) {
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.lock();
#endif
        output = (s8*) mPool10K.allocate();
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.unlock();
#endif
        return getUserPointer(output, alignment, EMT_10K);
    }

    output = (s8*) ::malloc(sizeRequested + 1);
    return getUserPointer(output, alignment, EMT_DEFAULT);
}

void CMemoryHub::deallocate(void* ptr) {
    if (!ptr) {
        return;
    }

#if defined(APP_DEBUG)
    drop();
#endif

#ifdef APP_DISABLE_BYTE_POOL
    ::free(ptr);
#endif

    s8* actualPtr;
    switch(getRealPointer(ptr, actualPtr)) {
    case EMT_128:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.lock();
#endif
        mPool128.release((u8(*)[128]) actualPtr);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex128.unlock();
#endif
        break;

    case EMT_512:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.lock();
#endif
        mPool512.release((u8(*)[512]) actualPtr);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex512.unlock();
#endif
        break;

    case EMT_2048:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.lock();
#endif
        mPool2048.release((u8(*)[2048]) actualPtr);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex2048.unlock();
#endif
        break;

    case EMT_8192:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.lock();
#endif
        mPool8192.release((u8(*)[8192]) actualPtr);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex8192.unlock();
#endif
        break;

    case EMT_10K:
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.lock();
#endif
        mPool10K.release((u8(*)[10240]) actualPtr);
#ifdef APP_THREADSAFE_MEMORY_POOL
        mMutex10K.unlock();
#endif
        break;

    case EMT_DEFAULT:
        ::free(actualPtr);
        break;

    default:
        APP_ASSERT(0);
        break;
    }
}

void CMemoryHub::reset() {
#ifdef APP_THREADSAFE_MEMORY_POOL
    mPool128.clear();
    mPool512.clear();
    mPool2048.clear();
    mPool8192.clear();
    mPool10K.clear();
#endif //APP_THREADSAFE_MEMORY_POOL
}

