std::string GenerateRandomSpaceSeparatedWords(
    const size_t min_len,
    const size_t max_len,
    const std::string_view char_set,
    const size_t word_qty)
{
    std::string result;
    std::minstd_rand rng;

    for(size_t idx = 0; idx < word_qty; ++idx)
    {
        const size_t word_length = rng() % (max_len - min_len) + min_len;
        for(size_t pos = 0; pos < word_length; ++pos)
            result.push_back(char_set[rng() % char_set.size()]);
        result.push_back(' ');
    }
    return result;
}
} // namespace

const BenchmarkDataElement g_test_data[]
{
    // Basic character sequence benchmark
    {
        "[A-Z_a-z0-9]+",
        []{ return GenerateRandomSpaceSeparatedWords(1, 20, "ABCDEFGHIJKLMNOPQRSTUVWXYZ_abcdefghijklmnopqrstuvwxyz0123456789", 1024 * 1024); }
    },
    // Pattern requiring backtracking
    {
        "[0-9]*3",
        []{ return GenerateRandomSpaceSeparatedWords(1, 30, "0123456789", 1024 * 256); }
    },
    // Long fixed pattern
    {
        "1101011011101110100101011010101110101",
        []{ return GenerateRandomSpaceSeparatedWords(3, 40, "01", 1024 * 256); }
    },
    // Two sequences with overlapping characters
    {
        "[w-z]+y[w-z]+",
        []{ return GenerateRandomSpaceSeparatedWords(3, 50, "wwwwwwwwxxxxxxxxzzzzzzzzy", 1024 * 256); }
    },
    // Non-greedy variant of previous pattern
    {
        "[w-z]+?y[w-z]+",
        []{ return GenerateRandomSpaceSeparatedWords(3, 50, "wwwwwwwwxxxxxxxxzzzzzzzzy", 1024 * 256); }
    },
    // Fixed repetition pattern
    {
        "(?:abc){3}",
        []{ return GenerateRandomSpaceSeparatedWords(6, 20, "abc", 1024 * 1024); }
    },
    // Start-anchored pattern
    {
        "^[0-9]+",
        []{ return GenerateRandomSpaceSeparatedWords(6, 20, "0123456789", 1024 * 1024); }
    },
    // Advanced regex with lookbehind, lookahead, recursion and backreference
    {
        "(?<![a-f])(([a-f])((?1)|[a-f])?\\2)(?![a-f])",
        []{ return GenerateRandomSpaceSeparatedWords(1, 8, "abcdef", 1024 * 1024); }
    },
};

