// Constructor initializes callback handlers for various packet types
class python_module_packet_switch : public vs_packet_decoder {
public:
    python_module_packet_switch();
    PyObject* result;
};

python_module_packet_switch::python_module_packet_switch() {
    case_text([this](const char* text, size_t len) {
        result = Py_BuildValue("{ss,si,ss,si,si, ss#}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "TEXT",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "text", text, len
        );
    });

    case_analog([this](int w, int h, uint8_t* buf) {
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sy#}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "SCAMP5_AOUT",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "width", w,
            "height", h,
            "buffer", buf, size_t(w * h)
        );
    });

    case_digital([this](int w, int h, uint8_t* buf) {
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sy#}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "SCAMP5_DOUT",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "width", w,
            "height", h,
            "buffer", buf, size_t(w * h)
        );
    });

    case_boundingbox([this](const vs_array<uint8_t>& data) {
        PyObject* list = PyList_New(data.n_rows());
        for (int idx = 0; idx < data.n_rows(); ++idx) {
            PyObject* vec = Py_BuildValue("(ii)", data(idx, 0), data(idx, 1));
            PyList_SET_ITEM(list, idx, vec);
        }
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sO}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "BBOX",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "n_rows", (int)data.n_rows(),
            "n_cols", (int)data.n_cols(),
            "data", list
        );
    });

    case_points([this](const vs_array<uint8_t>& data) {
        PyObject* list = PyList_New(data.n_rows());
        for (int idx = 0; idx < data.n_rows(); ++idx) {
            PyObject* vec = Py_BuildValue("(ii)", data(idx, 0), data(idx, 1));
            PyList_SET_ITEM(list, idx, vec);
        }
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sO}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "EVENTS",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "n_rows", (int)data.n_rows(),
            "n_cols", (int)data.n_cols(),
            "data", list
        );
    });

    case_data_int8([this](const vs_array<int8_t>& data) {
        PyObject* outer_list = PyList_New(data.n_rows());
        for (int row = 0; row < data.n_rows(); ++row) {
            PyObject* inner_list = PyList_New(data.n_cols());
            for (int col = 0; col < data.n_cols(); ++col) {
                PyList_SET_ITEM(inner_list, col, PyLong_FromLong(data(row, col)));
            }
            PyList_SET_ITEM(outer_list, row, inner_list);
        }
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sO}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "INT8",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "n_rows", (int)data.n_rows(),
            "n_cols", (int)data.n_cols(),
            "data", outer_list
        );
    });

    case_data_int16([this](const vs_array<int16_t>& data) {
        PyObject* outer_list = PyList_New(data.n_rows());
        for (int row = 0; row < data.n_rows(); ++row) {
            PyObject* inner_list = PyList_New(data.n_cols());
            for (int col = 0; col < data.n_cols(); ++col) {
                PyList_SET_ITEM(inner_list, col, PyLong_FromLong(data(row, col)));
            }
            PyList_SET_ITEM(outer_list, row, inner_list);
        }
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sO}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "INT16",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "n_rows", (int)data.n_rows(),
            "n_cols", (int)data.n_cols(),
            "data", outer_list
        );
    });

    case_data_int32([this](const vs_array<int32_t>& data) {
        PyObject* outer_list = PyList_New(data.n_rows());
        for (int row = 0; row < data.n_rows(); ++row) {
            PyObject* inner_list = PyList_New(data.n_cols());
            for (int col = 0; col < data.n_cols(); ++col) {
                PyList_SET_ITEM(inner_list, col, PyLong_FromLong(data(row, col)));
            }
            PyList_SET_ITEM(outer_list, row, inner_list);
        }
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sO}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "INT32",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "n_rows", (int)data.n_rows(),
            "n_cols", (int)data.n_cols(),
            "data", outer_list
        );
    });

    case_data_float([this](const vs_array<float>& data) {
        PyObject* outer_list = PyList_New(data.n_rows());
        for (int row = 0; row < data.n_rows(); ++row) {
            PyObject* inner_list = PyList_New(data.n_cols());
            for (int col = 0; col < data.n_cols(); ++col) {
                PyList_SET_ITEM(inner_list, col, PyFloat_FromDouble(data(row, col)));
            }
            PyList_SET_ITEM(outer_list, row, inner_list);
        }
        result = Py_BuildValue("{ss,si,ss,si,si, si,si,sO}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "FLOAT",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "n_rows", (int)data.n_rows(),
            "n_cols", (int)data.n_cols(),
            "data", outer_list
        );
    });

    case_request_image([this](const char* path, int32_t bits) {
        result = Py_BuildValue("{ss,si,ss,si,si, ss,ss,si}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "REQUEST",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "filetype", "IMAGE",
            "filepath", path,
            "n_bits", int(bits)
        );
    });

    case_request_file([this](const char* path, int32_t chunk) {
        result = Py_BuildValue("{ss,si,ss,si,si, ss,ss,si}",
            "type", "data",
            "size", int(get_packet_header()->payload_size),
            "datatype", "REQUEST",
            "loopcounter", (int)get_loop_counter(),
            "channel", (int)get_data_channel(),
            "filetype", "FILE",
            "filepath", path,
            "chunksize", int(chunk)
        );
    });
}

PyObject* decode_packet(uint8_t* buffer, size_t size) {
    static python_module_packet_switch decoder;
    static uint32_t counter = 0;
    auto status = decoder.decode_packet(buffer, size, counter++);

    if (status == python_module_packet_switch::done) {
        return decoder.result;
    } else {
        auto header = reinterpret_cast<vs_packet_header_t*>(buffer);
        int payload_len = header->payload_size;
        auto payload_data = buffer + sizeof(vs_packet_header_t);
        return Py_BuildValue("{ss,si,sy#}",
            "type", "unknown",
            "size", payload_len,
            "payload", payload_data, payload_len
        );
    }
}

