NS_XGAME_BEGIN

// Internal state variables for the downloader system
static cocos2d::network::Downloader *_downloaderInstance = nullptr;
static std::function<void(const downloader::FileTask &)> _dispatchCallback = nullptr;
static std::vector<downloader::FileTask> _pendingTasks;
static std::unordered_map<std::string, int64_t> _expectedFileSizes;
static std::mutex _taskMutex;
static std::thread *_verificationThread = nullptr;
static std::condition_variable _taskCondition;
static bool _shutdownFlag = false;

// Cleanup and shutdown routine
void downloader::end()
{
    if (_downloaderInstance) {
        _shutdownFlag = true;
        _taskCondition.notify_one();
        _verificationThread->join();
        delete _verificationThread;
        delete _downloaderInstance;
        _verificationThread = nullptr;
        _downloaderInstance = nullptr;
        _shutdownFlag = false;
    }
}

// Initialize the downloader with configuration
void downloader::init()
{
    if (_downloaderInstance) {
        return;
    }

    // Launch background verification thread
    _verificationThread = new std::thread(&downloader::start);

    // Configure download hints: concurrent tasks, max retries, temp extension
    DownloaderHints hints = {6, 10, ".tmp"};
    _downloaderInstance = new Downloader(hints);

    // Set up error handler for failed downloads
    _downloaderInstance->onTaskError = [](const DownloadTask &task, int errorCode, int errorCodeInternal, const std::string &errorStr) {
        FileTask file;
        file.md5 = task.identifier;
        file.url = task.requestURL;
        file.path = task.storagePath;
        file.state = FileState::IOERROR;

        std::lock_guard<std::mutex> lock(_taskMutex);
        _pendingTasks.push_back(file);
        _taskCondition.notify_one();
    };

    // Handle successful file download completion
    _downloaderInstance->onFileTaskSuccess = [](const DownloadTask &task) {
        FileTask file;
        file.md5 = task.identifier;
        file.url = task.requestURL;
        file.path = task.storagePath;
        file.state = FileState::PENDING;

        int64_t size = _expectedFileSizes[task.requestURL];
        _expectedFileSizes.erase(task.requestURL);

        // Validate downloaded file size matches expectation
        if (FileUtils::getInstance()->getFileSize(file.path) != size || size == 0) {
            file.state = FileState::IOERROR;
        }

        std::lock_guard<std::mutex> lock(_taskMutex);
        _pendingTasks.push_back(file);
        _taskCondition.notify_one();
    };

    // Track expected file sizes during download progress
    _downloaderInstance->onTaskProgress = [](const DownloadTask& task, int64_t bytesReceived, int64_t totalBytesReceived, int64_t totalBytesExpected) {
        _expectedFileSizes[task.requestURL] = totalBytesExpected;
    };
}

// Set the callback function to dispatch completed tasks
void downloader::setDispatcher(const std::function<void(const FileTask &)> callback)
{
    _dispatchCallback = callback;
}

// Verify integrity of a downloaded file using MD5 checksum
static bool verifyFileIntegrity(const downloader::FileTask &task)
{
    unsigned char hashResult[MD5_STR_LEN];
    return md5f(hashResult, task.path.c_str()) &&
           strcaseequal((const char *)hashResult, task.md5.c_str());
}

// Submit a new download request
void downloader::load(const FileTask &task)
{
    auto storagePath = task.path;
    auto lastSeparatorPos = storagePath.find_last_of("/");

    // Ensure parent directory exists
    if (lastSeparatorPos != std::string::npos) {
        storagePath = storagePath.substr(0, lastSeparatorPos);
    }

    filesystem::createDirectory(storagePath);

    // Clean up any leftover temporary files
    if (filesystem::exist(task.path + ".tmp")) {
        filesystem::remove(task.path + ".tmp");
    }

    // Register expected file size placeholder
    _expectedFileSizes[task.url] = 0;
    _downloaderInstance->createDownloadFileTask(task.url, task.path, task.md5);
}

// Background thread responsible for processing completed downloads
void downloader::start()
{
    while (!_shutdownFlag) {
        _taskMutex.lock();

        if (_pendingTasks.size() > 0) {
            FileTask currentTask = _pendingTasks.back();
            _pendingTasks.pop_back();
            _taskMutex.unlock();

            // Process pending tasks by verifying checksums
            if (currentTask.state == FileState::PENDING) {
                if (!currentTask.md5.empty()) {
                    currentTask.state = verifyFileIntegrity(currentTask) ? FileState::LOADED : FileState::INVALID;
                } else {
                    currentTask.state = FileState::LOADED;
                }
            }

            // Remove corrupted or incomplete files
            if (currentTask.state != FileState::LOADED && filesystem::exist(currentTask.path)) {
                filesystem::remove(currentTask.path);
            }

            // Dispatch result back to main game thread
            cocos2d::Director::getInstance()->getScheduler()->performFunctionInCocosThread([currentTask]() {
                if (_dispatchCallback) {
                    _dispatchCallback(currentTask);
                }
            });

            continue;
        } else {
            _taskMutex.unlock();
        }

        // Wait for new tasks or shutdown signal
        std::unique_lock<std::mutex> lock(_taskMutex);
        _taskCondition.wait(lock);
    }
}

