#include "LexTokenStream.hpp"
#include "antlr/CommonToken.hpp"

extern "C" {
    extern char* yytext;
    extern int yylex();
    extern int yyrestart(std::FILE*);
}

// Global pointer to track the currently active lexer instance
static LexTokenStream* activeLexer = 0;

// Callback function invoked when a new line is encountered during lexing
extern "C"
void newLine()
{
    activeLexer->advanceLine();
}

// Constructor initializes the lexer with a file stream
LexTokenStream::LexTokenStream(std::FILE* fp)
{
    yyrestart(fp);
    reachedEOF = false;
    currentLine = 1;
}

// Increment the current line counter
void LexTokenStream::advanceLine()
{
    ++currentLine;
}

// Retrieve the next token from the input stream
ANTLR_USE_NAMESPACE(antlr)RefToken LexTokenStream::nextToken()
{
    ANTLR_USE_NAMESPACE(antlr)RefToken tokenPtr;

    if (!reachedEOF) {
        int tokenType;
        activeLexer = this;

        // Skip tokens marked as SKIP by the lexer
        while ((tokenType = yylex()) == -1)
            ;

        if (tokenType != 0) {
            // Create a token with the type and text from the lexer
            tokenPtr = ANTLR_USE_NAMESPACE(antlr)RefToken(
                new ANTLR_USE_NAMESPACE(antlr)CommonToken(tokenType, yytext)
            );
        } else {
            // Token type 0 indicates end-of-file
            reachedEOF = true;
        }
    }

    // If EOF has been reached, return an EOF token
    if (reachedEOF) {
        tokenPtr = ANTLR_USE_NAMESPACE(antlr)RefToken(
            new ANTLR_USE_NAMESPACE(antlr)CommonToken(1, "EOF")
        );
    }

    // Set the line number for the returned token
    tokenPtr->setLine(currentLine);
    return tokenPtr;
}

#include "user_console_ui.h"
#include "exceptions.h"

static const char BROWSER_COMMAND[] = "/usr/bin/firefox --new-window ";
static const char CLOSE_WINDOW_CMD[] = "wmctrl -ic \"$(wmctrl -l | grep 'Mozilla Firefox' | tail -1 | awk '{ print $1 }')\"";

UserConsoleUI::UserConsoleUI(std::shared_ptr<Repository<Trenchcoat>> repository,
                             std::shared_ptr<Repository<Trenchcoat>> cartRepository) 
    : service(repository, cartRepository) {}

void UserConsoleUI::seeCoats() {
    std::string sizeInput("INITIAL");
    for (;;) {
        if (sizeInput != "INITIAL")
            this->displayError("Invalid size. Please enter a valid one.\n");
        sizeInput = this->getString("Size: ");
        bool proceed = true;
        try {
            Validator<Trenchcoat>::validSize(sizeInput);
        } catch (const InvalidTrenchcoatSize&) {
            proceed = false;
        }
        if (!proceed && !sizeInput.empty())
            continue;
        break;
    }

    std::size_t position = 0;
    bool inputValid = true;
    for (;;) {
        auto availableCoats = this->service.getCoats(sizeInput);
        Trenchcoat currentCoat = availableCoats[position];

        if (availableCoats.empty()) {
            this->displayError("No coats available in this size. Apologies.");
            return;
        }

        if (inputValid)
            position = (position + 1) % availableCoats.size();
        inputValid = true;

        system((std::string(BROWSER_COMMAND) + " " + currentCoat.photoLink()).c_str());
        this->displayEntity<Trenchcoat>(currentCoat);

        auto userChoice = this->getString(
            "Purchase (" + std::string(1, BUY_KEY) + 
                "), Next (" + std::string(1, SKIP_KEY) + 
                ") or Back (" + std::string(1, MENU_KEY) + 
                "): "
        );

        system(CLOSE_WINDOW_CMD);

        if (userChoice.length() > 1)
            userChoice[0] = '\0';

        switch (userChoice[0]) {
            case BUY_KEY:
                this->service.buyCoat(currentCoat);
                this->displayMessage("Total amount: $" + 
                        std::to_string(this->service.getShoppingCartPrice()));
                break;
            case SKIP_KEY:
                break;
            case MENU_KEY:
                return;

            default:
                this->displayError("Invalid option. Try again.\n");
                inputValid = false;
        };
        this->displayMessage("");
    }
}

void UserConsoleUI::showCart() {
    this->displayEntityVector<Trenchcoat>(
        this->service.getShoppingCart()
    );
    this->displayMessage("Cart total: $" + 
        std::to_string(this->service.getShoppingCartPrice()));
}

void UserConsoleUI::seeCoatsFile() {
    system(service.getDisplayFileCommand().c_str());
}

void UserConsoleUI::exitProgram() {
    this->displayMessage("Terminating...");
}

void UserConsoleUI::displayMenu() {
    this->displayMessage(
        "\n+++++++++++++ USER MODE +++++++++++++\n" +
        std::string(1, LIST_KEY) + ". Display coats.\n" + 
        std::string(1, BASKET_KEY) + ". View shopping cart.\n" + 
        std::string(1, FILE_LIST_KEY) + ". Show coats (from file)\n" +
        std::string(1, EXIT_KEY) + ". Quit.\n"); 
}

void UserConsoleUI::run() {
    for (;;) {
        this->displayMenu();
        auto selection = this->getString("Your selection: ");
        if (selection.length() > 1)
            selection[0] = '\0';
        switch (selection[0]) {
            case LIST_KEY:
                this->seeCoats();
                break;
            case BASKET_KEY:
                this->showCart();
                break;
            case FILE_LIST_KEY:
                this->seeCoatsFile();
                break;
            case EXIT_KEY:
                this->exitProgram();
                return;

            default:
                this->displayError("Invalid selection. Please try again.\n");
                break;
        };
    }
}

