using Converter = void* (*)(void*);
using DynCastFunc = swig_type_info* (*)(void**);

struct swig_type_info {
  const char*           type_name;              
  Converter             type_converter;
  const char*           type_str;
  void*                 user_data;	
  DynCastFunc           dynamic_cast_func;
  swig_type_info*       next_entry;
  swig_type_info*       previous_entry;
};

#ifdef SWIG_NOINCLUDE
IMPORT_FUNC(swig_type_info*) RegisterType(swig_type_info*);
IMPORT_FUNC(swig_type_info*) CheckType(char*, swig_type_info*);
IMPORT_FUNC(void*)           CastPointer(swig_type_info*, void*);
IMPORT_FUNC(swig_type_info*) DynamicCast(swig_type_info*, void**);
IMPORT_FUNC(swig_type_info*) FindType(const char*);
IMPORT_FUNC(void)            SetUserData(swig_type_info*, void*);
#else

static swig_type_info* type_registry_head = nullptr;

RUNTIME_DECL(swig_type_info*)
RegisterType(swig_type_info* new_type) {
  swig_type_info* current = type_registry_head;
  swig_type_info* head_node = nullptr;
  swig_type_info* return_node = nullptr;
  swig_type_info* next_block = nullptr;

  // Check if already registered
  while (current) {
    if (std::strcmp(current->type_name, new_type->type_name) == 0) {
      if (current->user_data) new_type->user_data = current->user_data;
      head_node = current;
      next_block = current->next_entry;
      goto link_types;
    }
    current = current->previous_entry;
  }

  head_node = new_type;
  next_block = nullptr;

  // Insert into list
  new_type->previous_entry = type_registry_head;
  type_registry_head = new_type;

link_types:
  return_node = head_node;
  current = new_type + 1;

  // Link remaining types in block
  while (current->type_name) {
    head_node->next_entry = current;
    current->previous_entry = head_node;
    head_node = current;
    current++;
  }
  head_node->next_entry = next_block;
  return return_node;
}

RUNTIME_DECL(swig_type_info*) 
CheckType(char* name, swig_type_info* base_type) {
  if (!base_type) return nullptr;

  swig_type_info* search_ptr = base_type->next_entry;
  do {
    if (search_ptr && std::strcmp(search_ptr->type_name, name) == 0) {
      if (search_ptr == base_type->next_entry) return search_ptr;

      // Move found entry to top of list (after base)
      search_ptr->previous_entry->next_entry = search_ptr->next_entry;
      if (search_ptr->next_entry) {
        search_ptr->next_entry->previous_entry = search_ptr->previous_entry;
      }
      search_ptr->next_entry = base_type->next_entry;
      if (base_type->next_entry) base_type->next_entry->previous_entry = search_ptr;
      base_type->next_entry = search_ptr;
      return search_ptr;
    }
    search_ptr = search_ptr ? search_ptr->next_entry : nullptr;
  } while (search_ptr && search_ptr != base_type->next_entry);

  return nullptr;
}

RUNTIME_DECL(void*) 
CastPointer(swig_type_info* target_type, void* pointer) {
  if (!target_type || !target_type->type_converter) return pointer;
  return (target_type->type_converter)(pointer);
}

RUNTIME_DECL(swig_type_info*) 
DynamicCast(swig_type_info* initial_type, void** ptr_ref) {
  swig_type_info* last_valid_type = initial_type;
  if (!initial_type || !initial_type->dynamic_cast_func) return initial_type;

  while (initial_type && initial_type->dynamic_cast_func) {
    initial_type = (initial_type->dynamic_cast_func)(ptr_ref);
    if (initial_type) last_valid_type = initial_type;
  }
  return last_valid_type;
}

RUNTIME_DECL(swig_type_info*)
FindType(const char* name) {
  swig_type_info* current = type_registry_head;
  while (current) {
    if ((current->type_str && std::strcmp(name, current->type_str) == 0) ||
        (current->type_name && std::strcmp(name, current->type_name) == 0)) {
      return current;
    }
    current = current->previous_entry;
  }
  return nullptr;
}

RUNTIME_DECL(void)
SetUserData(swig_type_info* target, void* data) {
  if (target->user_data == data) return;
  target->user_data = data;

  swig_type_info* equivalent = target->next_entry;
  while (equivalent) {
    if (!equivalent->type_converter) {
      swig_type_info* scan = type_registry_head;
      while (scan) {
        if (std::strcmp(scan->type_name, equivalent->type_name) == 0) {
          SetUserData(scan, data);
        }
        scan = scan->previous_entry;
      }
    }
    equivalent = equivalent->next_entry;
  }
}
#endif

