typedef struct GlobalVariable {
  char* var_name;
  PyObject* (*getter_func)(void);
  int (*setter_func)(PyObject*);
  struct GlobalVariable* next_var;
} GlobalVariable;

typedef struct VariableLinkObject {
  PyObject_HEAD
  GlobalVariable* variable_list;
} VariableLinkObject;

static PyObject*
VariableLinkRepr(VariableLinkObject* obj) {
  obj = obj;
  return PyString_FromString("<Global Variables Container>");
}

static int
VariableLinkPrint(VariableLinkObject* obj, FILE* stream, int flags) {
  flags = flags;
  fprintf(stream, "Variables { ");
  for (GlobalVariable* v = obj->variable_list; v; v = v->next_var) {
    fprintf(stream, "%s", v->var_name);
    if (v->next_var) fprintf(stream, ", ");
  }
  fprintf(stream, " }\n");
  return 0;
}

static PyObject*
VariableLinkGetAttr(VariableLinkObject* obj, char* name) {
  GlobalVariable* current = obj->variable_list;
  while (current) {
    if (std::strcmp(current->var_name, name) == 0) {
      return (current->getter_func)();
    }
    current = current->next_var;
  }
  PyErr_SetString(PyExc_NameError, "Unknown global variable");
  return NULL;
}

static int
VariableLinkSetAttr(VariableLinkObject* obj, char* name, PyObject* value) {
  GlobalVariable* current = obj->variable_list;
  while (current) {
    if (std::strcmp(current->var_name, name) == 0) {
      return (current->setter_func)(value);
    }
    current = current->next_var;
  }
  PyErr_SetString(PyExc_NameError, "Unknown global variable");
  return 1;
}

