RUNTIME_DECL(char*)
PackBinaryData(char* buffer, void* data, int size) {
  static char hex_chars[17] = "0123456789abcdef";
  unsigned char* bytes = (unsigned char*)data;
  for (int i = 0; i < size; ++i, ++bytes) {
    unsigned char byte_val = *bytes;
    *(buffer++) = hex_chars[(byte_val & 0xF0) >> 4];
    *(buffer++) = hex_chars[byte_val & 0x0F];
  }
  return buffer;
}

RUNTIME_DECL(char*)
UnpackBinaryData(char* buffer, void* output, int size) {
  unsigned char* dest = (unsigned char*)output;
  for (int i = 0; i < size; ++i, ++dest) {
    int high_nibble = *(buffer++);
    unsigned char value = 0;
    if (high_nibble >= '0' && high_nibble <= '9')
      value = ((high_nibble - '0') << 4);
    else if (high_nibble >= 'a' && high_nibble <= 'f')
      value = ((high_nibble - ('a' - 10)) << 4);

    int low_nibble = *(buffer++);
    if (low_nibble >= '0' && low_nibble <= '9')
      value |= (low_nibble - '0');
    else if (low_nibble >= 'a' && low_nibble <= 'f')
      value |= (low_nibble - ('a' - 10));

    *dest = value;
  }
  return buffer;
}

RUNTIME_DECL(int)
ConvertPointer(PyObject* input, void** output, swig_type_info* type_info, int flags) {
  swig_type_info* matched_type;
  char* type_descriptor;
  static PyObject* this_attr = nullptr;
  int ref_counted = 0;
  PyObject* temp_obj = nullptr;

  if (!input) return 0;
  if (input == Py_None) {
    *output = nullptr;
    return 0;
  }

#ifdef SWIG_COBJECT_TYPES
  if (!PyCObject_Check(input)) {
    if (!this_attr) this_attr = PyString_FromString("this");
    temp_obj = input;
    input = PyObject_GetAttr(input, this_attr);
    ref_counted = 1;
    if (!input) goto type_error;
    if (!PyCObject_Check(input)) {
      Py_DECREF(input);
      goto type_error;
    }
  }
  *output = PyCObject_AsVoidPtr(input);
  type_descriptor = (char*)PyCObject_GetDesc(input);
  if (ref_counted) Py_DECREF(input);
  goto check_cobject;
#else
  if (!PyString_Check(input)) {
    if (!this_attr) this_attr = PyString_FromString("this");
    temp_obj = input;
    input = PyObject_GetAttr(input, this_attr);
    ref_counted = 1;
    if (!input) goto type_error;
    if (!PyString_Check(input)) {
      Py_DECREF(input);
      goto type_error;
    }
  }
  type_descriptor = PyString_AsString(input);
  if (*type_descriptor != '_') {
    *output = (void*)0;
    if (std::strcmp(type_descriptor, "NULL") == 0) {
      if (ref_counted) Py_DECREF(input);
      return 0;
    } else {
      if (ref_counted) Py_DECREF(input);
      goto type_error;
    }
  }
  type_descriptor++;
  type_descriptor = UnpackBinaryData(type_descriptor, output, sizeof(void*));
  if (ref_counted) Py_DECREF(input);
#endif

#ifdef SWIG_COBJECT_TYPES
check_cobject:
#endif
  if (type_info) {
    matched_type = CheckType(type_descriptor, type_info);
    if (!matched_type) goto type_error;
    *output = CastPointer(matched_type, *output);
  }

  if (temp_obj && (flags & FLAG_DISOWN_OBJECT)) {
    PyObject* zero = PyInt_FromLong(0);
    PyObject_SetAttrString(temp_obj, (char*)"thisown", zero);
    Py_DECREF(zero);
  }
  return 0;

type_error:
  if (flags & FLAG_THROW_EXCEPTION) {
    if (type_info) {
      char* msg = (char*)malloc(64 + std::strlen(type_info->type_name));
      std::sprintf(msg, "Type mismatch. Expected %s", type_info->type_name);
      PyErr_SetString(PyExc_TypeError, msg);
      free(msg);
    } else {
      PyErr_SetString(PyExc_TypeError, "Expected a pointer");
    }
  }
  return -1;
}

RUNTIME_DECL(int)
ConvertPackedData(PyObject* input, void* buffer, int size, swig_type_info* type_info, int flags) {
  swig_type_info* matched_type;
  char* descriptor;
  if ((!input) || (!PyString_Check(input))) goto type_error;
  descriptor = PyString_AsString(input);
  if (*descriptor != '_') goto type_error;
  descriptor++;
  descriptor = UnpackBinaryData(descriptor, buffer, size);
  if (type_info) {
    matched_type = CheckType(descriptor, type_info);
    if (!matched_type) goto type_error;
  }
  return 0;

type_error:
  if (flags) {
    if (type_info) {
      char* msg = (char*)malloc(64 + std::strlen(type_info->type_name));
      std::sprintf(msg, "Type mismatch. Expected %s", type_info->type_name);
      PyErr_SetString(PyExc_TypeError, msg);
      free(msg);
    } else {
      PyErr_SetString(PyExc_TypeError, "Expected a pointer");
    }
  }
  return -1;
}

RUNTIME_DECL(PyObject*)
NewPointerObject(void* ptr, swig_type_info* type, int ownership_flag) {
  PyObject* result;
  if (!ptr) {
    Py_INCREF(Py_None);
    return Py_None;
  }

#ifdef SWIG_COBJECT_TYPES
  result = PyCObject_FromVoidPtrAndDesc(ptr, (char*)type->type_name, NULL);
#else
  char buffer[1024];
  char* pos = buffer;
  *(pos++) = '_';
  pos = PackBinaryData(pos, &ptr, sizeof(void*));
  std::strcpy(pos, type->type_name);
  result = PyString_FromString(buffer);
#endif

  if (!result || result == Py_None) return result;

  if (type->user_data) {
    PyObject* instance;
    PyObject* args = Py_BuildValue((char*)"(O)", result);
    Py_DECREF(result);
    instance = PyObject_CallObject((PyObject*)type->user_data, args);
    Py_DECREF(args);
    if (instance) {
      if (ownership_flag) {
        PyObject* flag = PyInt_FromLong(1);
        PyObject_SetAttrString(instance, (char*)"thisown", flag);
        Py_DECREF(flag);
      }
      result = instance;
    }
  }
  return result;
}

RUNTIME_DECL(PyObject*)
NewPackedObject(void* data, int size, swig_type_info* type) {
  char buffer[1024];
  char* pos = buffer;
  if ((2*size + 1 + std::strlen(type->type_name)) > 1000) return nullptr;
  *(pos++) = '_';
  pos = PackBinaryData(pos, data, size);
  std::strcpy(pos, type->type_name);
  return PyString_FromString(buffer);
}

RUNTIME_DECL(void)
InstallConstants(PyObject* module_dict, ConstantEntry constants[]) {
  int index = 0;
  PyObject* constant_obj;
  while (constants[index].type_id) {
    switch(constants[index].type_id) {
    case SWIG_CONST_INT:
      constant_obj = PyInt_FromLong(constants[index].integer_val);
      break;
    case SWIG_CONST_FLOAT:
      constant_obj = PyFloat_FromDouble(constants[index].float_val);
      break;
    case SWIG_CONST_STRING:
      constant_obj = PyString_FromString((char*)constants[index].pointer_val);
      break;
    case SWIG_CONST_POINTER:
      constant_obj = NewPointerObj(constants[index].pointer_val, 
                                   *(constants[index].type_ref), 0);
      break;
    case SWIG_CONST_BINARY:
      constant_obj = NewPackedObj(constants[index].pointer_val, 
                                  constants[index].integer_val, 
                                  *(constants[index].type_ref));
      break;
    default:
      constant_obj = nullptr;
      break;
    }
    if (constant_obj) {
      PyDict_SetItemString(module_dict, constants[index].name, constant_obj);
      Py_DECREF(constant_obj);
    }
    index++;
  }
}
#endif

