void CCustomSplitter::RecalcLayout()
{
    ASSERT_VALID(this);
    ASSERT(m_nRows > 0 && m_nCols > 0); // must have at least one pane
    CRect rcClient;
    GetClientRect(rcClient);
    rcClient.InflateRect(-m_cxBorder, -m_cyBorder);
    CRect rcInner;
    GetInsideRect(rcInner);

    // Layout columns and rows with available space
    ArrangeRowOrColumn(m_pColInfo, m_nCols, rcInner.Width(), m_cxSplitterGap);
    ArrangeRowOrColumn(m_pRowInfo, m_nRows, rcInner.Height(), m_cySplitterGap);

    // Prepare window position changes
    AFX_SIZEPARENTPARAMS layoutData;
    layoutData.hDWP = ::BeginDeferWindowPos((m_nCols + 1) * (m_nRows + 1) + 1);

    // Determine scrollbar sizes
    int sbWidth = rcClient.right - rcInner.right;
    int sbHeight = rcClient.bottom - rcInner.bottom;

    // Reposition size box if both scrollbars exist
    if (m_bHasHScroll && m_bHasVScroll)
    {
        CWnd* pSizeBox = GetDlgItem(AFX_IDW_SIZE_BOX);
        ASSERT(pSizeBox != NULL);
        BOOL bIsSizingParent = (GetSizingParent() != NULL);
        if (pSizeBox->ModifyStyle(SBS_SIZEGRIP | SBS_SIZEBOX,
                bIsSizingParent ? SBS_SIZEGRIP : SBS_SIZEBOX))
            pSizeBox->Invalidate();
        pSizeBox->EnableWindow(bIsSizingParent);
        AdjustPanePosition(&layoutData, pSizeBox,
            rcInner.right, rcInner.bottom, sbWidth, sbHeight, TRUE);
    }

    // Reposition horizontal scrollbars
    if (m_bHasHScroll)
    {
        int splitterWidth = m_cxSplitter;
        int x = rcClient.left;
        int y = rcInner.bottom;
        for (int colIdx = 0; colIdx < m_nCols; ++colIdx)
        {
            CWnd* pHScroll = GetDlgItem(AFX_IDW_HSCROLL_FIRST + colIdx);
            ASSERT(pHScroll != NULL);
            int colWidth = m_pColInfo[colIdx].nCurSize;
            if (colIdx == 0 && m_nCols < m_nMaxCols)
            {
                x += splitterWidth;
                colWidth -= splitterWidth;
            }
            AdjustPanePosition(&layoutData, pHScroll, x, y, colWidth, sbHeight, TRUE);
            x += colWidth + m_cxSplitterGap;
        }
    }

    // Reposition vertical scrollbars
    if (m_bHasVScroll)
    {
        int splitterHeight = m_cySplitter;
        int x = rcInner.right;
        int y = rcClient.top;
        for (int rowIdx = 0; rowIdx < m_nRows; ++rowIdx)
        {
            CWnd* pVScroll = GetDlgItem(AFX_IDW_VSCROLL_FIRST + rowIdx);
            ASSERT(pVScroll != NULL);
            int rowHeight = m_pRowInfo[rowIdx].nCurSize;
            if (rowIdx == 0 && m_nRows < m_nMaxRows)
            {
                y += splitterHeight;
                rowHeight -= splitterHeight;
            }
            AdjustPanePosition(&layoutData, pVScroll, x, y, sbWidth, rowHeight, TRUE);
            y += rowHeight + m_cySplitterGap;
        }
    }

    // Reposition all panes
    {
        int leftX = rcClient.left;
        for (int colIdx = 0; colIdx < m_nCols; ++colIdx)
        {
            int paneWidth = m_pColInfo[colIdx].nCurSize;
            int topY = rcClient.top;
            for (int rowIdx = 0; rowIdx < m_nRows; ++rowIdx)
            {
                int paneHeight = m_pRowInfo[rowIdx].nCurSize;
                CWnd* pPane = GetPane(rowIdx, colIdx);
                AdjustPanePosition(&layoutData, pPane, leftX, topY, paneWidth, paneHeight, FALSE);
                topY += paneHeight + m_cySplitterGap;
            }
            leftX += paneWidth + m_cxSplitterGap;
        }
    }

    // Apply all window positions at once
    if (layoutData.hDWP == NULL || !::EndDeferWindowPos(layoutData.hDWP))
    {
        TRACE0("Warning: DeferWindowPos failed - low system resources.\n");
    }
}

