void CCustomSplitter::TrackRowSize(int y, int row)
{
    ASSERT_VALID(this);
    ASSERT(m_nRows > 1);
    CPoint pt(0, y);
    ClientToScreen(&pt);
    GetPane(row + 1, 0)->ScreenToClient(&pt);
    m_pRowInfo[row + 1].nIdealSize = m_pRowInfo[row + 1].nCurSize - pt.y;
}

void CCustomSplitter::TrackColumnSize(int x, int col)
{
    ASSERT_VALID(this);
    ASSERT(m_nCols > 1);
    CPoint pt(x, 0);
    ClientToScreen(&pt);
    GetPane(0, col + 1)->ScreenToClient(&pt);
    m_pColInfo[col + 1].nIdealSize = m_pColInfo[col + 1].nCurSize - pt.x;
}

/////////////////////////////////////////////////////////////////////////////
// Generic layout routine:
//  For X direction: pInfoBuffer = m_pColInfo, nCount = m_nMaxCols, nTotalSize = cx
//  For Y direction: pInfoBuffer = m_pRowInfo, nCount = m_nMaxRows, nTotalSize = cy
//
// Preference given from right to left (opposite of standard MFC).
static void ArrangeRowOrColumn(CSplitterWndEx::CRowColInfo* pInfoBuffer,
    int nCount, int nTotalSize, int nGapSize)
{
    ASSERT(pInfoBuffer != NULL);
    ASSERT(nCount > 0);
    ASSERT(nGapSize > 0);

    CSplitterWndEx::CRowColInfo* pInfo;
    int i;

    if (nTotalSize < 0)
        nTotalSize = 0;

    // Initialize ideal sizes
    for (i = 0, pInfo = &pInfoBuffer[nCount - 1]; i < nCount - 1; i++, pInfo--)
    {
        if (pInfo->nIdealSize < pInfo->nMinSize)
            pInfo->nIdealSize = 0;
        pInfo->nCurSize = pInfo->nIdealSize;
    }
    pInfo->nCurSize = INT_MAX; // Last item takes remaining space

    // Distribute space
    for (i = 0, pInfo = &pInfoBuffer[nCount - 1]; i < nCount; i++, pInfo--)
    {
        ASSERT(nTotalSize >= 0);
        if (nTotalSize == 0)
        {
            pInfo->nCurSize = 0;
            continue;
        }
        else if (nTotalSize < pInfo->nMinSize && i != 0)
        {
            pInfo->nCurSize = 0;
            (pInfo + 1)->nCurSize += nTotalSize + afxData.cxBorder2;
            nTotalSize = 0;
        }
        else
        {
            if (pInfo->nCurSize == 0)
            {
                if (i != 0)
                    pInfo->nCurSize = 0;
            }
            else if (nTotalSize < pInfo->nCurSize)
            {
                pInfo->nCurSize = nTotalSize;
                nTotalSize = 0;
            }
            else
            {
                nTotalSize -= pInfo->nCurSize;
            }
        }

        if (i != nCount - 1)
        {
            if (nTotalSize > nGapSize)
            {
                nTotalSize -= nGapSize;
                ASSERT(nTotalSize > 0);
            }
            else
            {
                pInfo->nCurSize += nTotalSize;
                if (pInfo->nCurSize > (nGapSize - afxData.cxBorder2))
                    pInfo->nCurSize -= (nGapSize - afxData.cyBorder2);
                nTotalSize = 0;
            }
        }
    }
    ASSERT(nTotalSize == 0);
}

/////////////////////////////////////////////////////////////////////////////
// Positions a child window inside the client area
static void AdjustPanePosition(AFX_SIZEPARENTPARAMS* pLayout,
    CWnd* pControl, int x, int y, int w, int h, BOOL bIsScrollBar)
{
    ASSERT(pControl != NULL);
    ASSERT(pControl->m_hWnd != NULL);

    if (bIsScrollBar)
    {
        BOOL needsBorder = (w <= AFX_CX_BORDER || h <= AFX_CY_BORDER);
        pControl->ModifyStyle(needsBorder ? 0 : WS_BORDER,
            needsBorder ? WS_BORDER : 0);
    }

    CRect rcNew(x, y, x + w, y + h);

    // Account for 3D borders
    if ((pControl->GetExStyle() & WS_EX_CLIENTEDGE) ||
          pControl->IsKindOf(RUNTIME_CLASS(CSplitterWndEx)))
        rcNew.InflateRect(afxData.cxBorder2, afxData.cyBorder2);

    // Skip if no change needed
    CRect rcOld;
    pControl->GetWindowRect(rcOld);
    pControl->GetParent()->ScreenToClient(&rcOld);
    if (rcNew != rcOld)
        AfxRepositionWindow(pLayout, pControl->m_hWnd, rcNew);
}

