static QScriptValue consoleLog(QScriptContext* context, QScriptEngine* engine){
    QString output = "";
    for (int index = 0; index < context->argumentCount(); index++) {
        if (index > 0) {
            output += " ";
        }
        output += context->argument(index).toString();
    }
    qCDebug(scriptengine) << "script:consoleLog()" << output;
    output = output.replace("\\", "\\\\")
                   .replace("\n", "\\n")
                   .replace("\r", "\\r")
                   .replace("'", "\\'");
    engine->evaluate("Script.log('" + output + "')");
    return QScriptValue();
}

