static bool isValidSyntax(const QScriptProgram& program) {
    const auto syntaxResult = QScriptEngine::checkSyntax(program.sourceCode());
    if (syntaxResult.state() != QScriptSyntaxCheckResult::Valid) {
        const auto errorMsg = syntaxResult.errorMessage();
        const auto lineNum = QString::number(syntaxResult.errorLineNumber());
        const auto colNum = QString::number(syntaxResult.errorColumnNumber());
        const auto fullMsg = QString("[SyntaxError] %1 in %2:%3(%4)").arg(errorMsg, program.fileName(), lineNum, colNum);
        qCWarning(scriptengine) << qPrintable(fullMsg);
        return false;
    }
    return true;
}

static bool hasException(QScriptEngine& engine, const QString& fileName) {
    if (engine.hasUncaughtException()) {
        const auto trace = engine.uncaughtExceptionBacktrace();
        const auto exceptionMsg = engine.uncaughtException().toString();
        const auto lineNum = QString::number(engine.uncaughtExceptionLineNumber());
        engine.clearExceptions();

        auto message = QString("[UncaughtException] %1 in %2:%3").arg(exceptionMsg, fileName, lineNum);
        if (!trace.empty()) {
            static const auto separator = "\n    ";
            message += QString("\n[Backtrace]%1%2").arg(separator, trace.join(separator));
        }
        qCWarning(scriptengine) << qPrintable(message);
        return true;
    }
    return false;
}

ScriptEngine::ScriptEngine(const QString& scriptContent, const QString& fileString, bool emitSignals) :
    _scriptContents(scriptContent),
    _isFinished(false),
    _isRunning(false),
    _isInitialized(false),
    _timerFunctionMap(),
    _wantSignals(emitSignals),
    _fileNameString(fileString),
    _isUserLoaded(false),
    _isReloading(false),
    _arrayBufferClass(new ArrayBufferClass(this))
{
    _allScriptsMutex.lock();
    _allKnownScriptEngines.insert(this);
    _allScriptsMutex.unlock();
}

ScriptEngine::~ScriptEngine() {
    if (!_stoppingAllScripts) {
        _allScriptsMutex.lock();
        _allKnownScriptEngines.remove(this);
        _allScriptsMutex.unlock();
    }
}

void ScriptEngine::runInWorkerThread() {
    QThread* workerThread = new QThread();
    QString threadName = QString("Script Worker:") + getFilename();
    workerThread->setObjectName(threadName);

    connect(workerThread, &QThread::started, this, &ScriptEngine::run);
    connect(this, &ScriptEngine::doneRunning, workerThread, &QThread::quit);
    connect(workerThread, &QThread::finished, workerThread, &QThread::deleteLater);
    connect(workerThread, &QThread::finished, this, &ScriptEngine::deleteLater);

    moveToThread(workerThread);
    workerThread->start();
}

QSet<ScriptEngine*> ScriptEngine::_allKnownScriptEngines;
QMutex ScriptEngine::_allScriptsMutex;
bool ScriptEngine::_stoppingAllScripts = false;
bool ScriptEngine::_doneRunningThisScript = false;

void ScriptEngine::stopAllScripts(QObject* application) {
    _allScriptsMutex.lock();
    _stoppingAllScripts = true;
    QMutableSetIterator<ScriptEngine*> iter(_allKnownScriptEngines);
    while (iter.hasNext()) {
        ScriptEngine* scriptEngine = iter.next();
        QString scriptName = scriptEngine->getFilename();

        if (scriptEngine->isRunning()) {
            if (scriptEngine->evaluatePending()) {
                while (scriptEngine->evaluatePending()) {
                    QEventLoop loop;
                    QObject::connect(scriptEngine, &ScriptEngine::evaluationFinished, &loop, &QEventLoop::quit);
                    loop.exec();
                }
            }

            scriptEngine->disconnect(application);
            scriptEngine->stop();
            scriptEngine->waitTillDoneRunning();
            iter.remove();
        }
    }
    _stoppingAllScripts = false;
    _allScriptsMutex.unlock();
}

void ScriptEngine::waitTillDoneRunning() {
    if (_isRunning) {
        _doneRunningThisScript = false;
        while (!_doneRunningThisScript) {
            QCoreApplication::processEvents();
        }
    }
}

QString ScriptEngine::getFilename() const {
    QStringList fileNameParts = _fileNameString.split("/");
    QString lastPart;
    if (!fileNameParts.isEmpty()) {
        lastPart = fileNameParts.last();
    }
    return lastPart;
}

void ScriptEngine::loadURL(const QUrl& scriptURL, bool reload) {
    if (_isRunning) {
        return;
    }
    _fileNameString = scriptURL.toString();
    _isReloading = reload;
    QUrl url(scriptURL);
    bool isPending;
    auto scriptCache = DependencyManager::get<ScriptCache>();
    scriptCache->getScript(url, this, isPending, reload);
}

void ScriptEngine::scriptContentsAvailable(const QUrl& url, const QString& scriptContents) {
    _scriptContents = scriptContents;
    if (_wantSignals) {
        emit scriptLoaded(_fileNameString);
    }
}

void ScriptEngine::errorInLoadingScript(const QUrl& url) {
    qCDebug(scriptengine) << "ERROR Loading file:" << url.toString() << "line:" << __LINE__;
    if (_wantSignals) {
        emit errorLoadingScript(_fileNameString);
    }
}

