enum class seat_state : char
{
    floor = '.',
    empty = 'L',
    occupied = '#'
};

using grid = std::vector<std::vector<seat_state>>;

auto operator<<(std::ostream& os, const grid& layout) -> std::ostream&
{
    for(size_t row_idx = 0; row_idx < layout.size(); ++row_idx)
    {
        for(size_t col_idx = 0; col_idx < layout[0].size(); ++col_idx)
        {
            os << static_cast<char>(layout[row_idx][col_idx]);
        }
        os << "\n";
    }
    return os;
}

auto count_occupied(const grid& layout) -> size_t
{
    size_t count{0};
    for(const auto& row : layout)
    {
        for(const auto& seat : row)
        {
            if(seat == seat_state::occupied)
            {
                ++count;
            }
        }
    }
    return count;
}

static std::array<std::pair<int64_t, int64_t>, 8> directions = {
    std::pair{-1, -1},   std::pair{0, -1},    std::pair{1, -1},
    std::pair{-1, 0},                         std::pair{1, 0},
    std::pair{-1, 1},    std::pair{0, 1},     std::pair{1, 1}
};

static auto evolve(const grid& current_layout) -> grid
{
    grid next_layout = current_layout;
    auto rows = current_layout.size();
    auto cols = current_layout[0].size();

    for(size_t x = 0; x < rows; ++x)
    {
        for(size_t y = 0; y < cols; ++y)
        {
            auto state = current_layout[x][y];
            if(state == seat_state::floor)
            {
                continue;
            }

            size_t adjacent_occupied{0};
            for(const auto& [dx, dy] : directions)
            {
                auto nx = static_cast<int64_t>(x) + dx;
                auto ny = static_cast<int64_t>(y) + dy;
                bool found{false};

                while(!found && nx >= 0 && nx < static_cast<int64_t>(rows) && 
                      ny >= 0 && ny < static_cast<int64_t>(cols))
                {
                    switch(current_layout[nx][ny])
                    {
                        case seat_state::floor:
                            nx += dx;
                            ny += dy;
                            break;
                        case seat_state::empty:
                            found = true;
                            break;
                        case seat_state::occupied:
                            found = true;
                            ++adjacent_occupied;
                            break;
                    }
                }
            }

            switch(state)
            {
                case seat_state::empty:
                    if(adjacent_occupied == 0)
                    {
                        next_layout[x][y] = seat_state::occupied;
                    }
                    break;
                case seat_state::occupied:
                    if(adjacent_occupied >= 5)
                    {
                        next_layout[x][y] = seat_state::empty;
                    }
                    break;
            }
        }
    }
    return next_layout;
}

int main(int argc, char* argv[])
{
    std::vector<std::string> arguments{argv, argv + argc};
    if(arguments.size() != 2)
    {
        std::cout << arguments[0] << " <input_file>" << std::endl;
        return 0;
    }

    auto file_content = file::read(arguments[1]);
    auto lines = chain::str::split(file_content, '\n');

    grid seating{};
    for(const auto& line : lines)
    {
        auto& row = seating.emplace_back();
        for(const auto& character : line)
        {
            switch(character)
            {
                case '.':
                    row.push_back(seat_state::floor);
                    break;
                case 'L':
                    row.push_back(seat_state::empty);
                    break;
                case '#':
                    row.push_back(seat_state::occupied);
                    break;
            }
        }
    }

    grid previous_layout{};
    do
    {
        std::cout << seating << "\n\n";
        previous_layout = seating;
        seating = evolve(seating);
    } while(previous_layout != seating);

    std::cout << "occupied seats = " << count_occupied(seating) << "\n";
    return 0;
}

