namespace diy
{
    struct Master::IExchangeInfoDUD: public IExchangeInfo
    {
        struct DataPacket
        {
            std::array<int,2>   payload;
            mpi::request        async_op;
        };
      using IExchangeInfo::IExchangeInfo;
      inline bool       finished() override;                             // determine if all processes have completed
      inline void       increment_work(int amount) override;             // increase global work counter
      inline void       manage() override;
      inline void       propagate_subtree_change(int delta);
      inline bool       handle_work_update();
      inline void       verify_no_abort();
      inline void       terminate(int attempt);
      inline void       handle_completion(int sender, int attempt);
      inline void       clear_child_acknowledgments();
      int               lowest_set_bit(int value) const         { return ((value ^ (value-1)) + 1) >> 1; }
      void              transmit(int dest, int  kind, int  val)
      {
          pending_.emplace_back();
          DataPacket& p = pending_.back();
          p.payload[0] = kind;
          p.payload[1] = val;
          p.async_op = comm.issend(dest, tags::iexchange, p.payload);
          log->trace("[{}] Dispatching to {}, kind = {}, val = {}", comm.rank(), dest, kind, val);
      }
      void              receive(int src, int& kind, int& val)
      {
          std::array<int,2> buffer;
          comm.recv(src, tags::iexchange, buffer);
          kind = buffer[0];
          val = buffer[1];
          log->trace("[{}] Acquired from {}, kind = {}, val = {}, data = {}", comm.rank(), src, kind, val);
      }
      inline bool       advance();
      int               ancestor() const                        { return comm.rank() & (comm.rank() - 1); }     // clear the final 1 bit
      inline void       notify_descendants(int marker, int val);
      bool              ongoing() const                         { return subtree_load_ > 0 || !pending_.empty(); }
      bool              outdated() const                        { return subtree_load_ != last_subtree_load_report_ || local_load_ != last_local_load_report_; }
      struct category   { enum {
                                    load_update = 0,
                                    complete,
                                    cancel
                                }; };
      std::unordered_map<int, bool>       completion_status;  // gid -> complete
      int                                 local_load_   = 0, last_local_load_report_   = 0;
      int                                 subtree_load_ = 0, last_subtree_load_report_ = 0;
      int                                 up_down_up_ = 0;
      std::list<DataPacket>               pending_;
      int                                 current_attempt_ = -1;
      int                                 descendant_acknowledgments = -1;
      // debugging
      bool                                initial_dud = true;
      using IExchangeInfo::prof;
    };
}

// determine if all processes have completed execution
bool
diy::Master::IExchangeInfoDUD::
finished()
{
    if (up_down_up_ == 3)
        while (!pending_.empty()) advance();     // ensure all messages are delivered before termination
                                                 // once decided complete, only outstanding messages should be completion signals to children
    return up_down_up_ == 3;
}

// add specified units to global work counter
void
diy::Master::IExchangeInfoDUD::
increment_work(int amount)
{
    int previous_local_load = local_load_;
    local_load_ += amount;
    assert(local_load_ >= 0);
    log->trace("[{}] Increasing workload: amount = {}, local_load = {}, previous_local_load = {}", comm.rank(), amount, local_load_, previous_local_load);
    if ((previous_local_load == 0) ^ (local_load_ == 0))     // transitioned through zero
    {
        int delta   = (local_load_ - last_local_load_report_);
        propagate_subtree_change(delta);
        last_local_load_report_ = local_load_;
    }
}

void
diy::Master::IExchangeInfoDUD::
propagate_subtree_change(int delta)
{
    int previous_subtree_load = subtree_load_;
    subtree_load_ += delta;
    log->debug("[{}] Adjusting subtree: delta = {}, subtree_load_ = {}", comm.rank(), delta, subtree_load_);
    assert(subtree_load_ >= 0);
    if ((previous_subtree_load == 0) ^ (subtree_load_ == 0))     // transitioned through zero
    {
        if (comm.rank() != 0)
        {
            int subtree_delta = (subtree_load_ - last_subtree_load_report_);
            log->debug("[{}] Transmitting subtree adjustment: delta = {}, subtree_delta = {}", comm.rank(), delta, subtree_delta);
            transmit(ancestor(), category::load_update, subtree_delta);
            last_subtree_load_report_ = subtree_load_;
            if (up_down_up_ == 1)
                terminate(current_attempt_);
            else if (up_down_up_ == 2)
                log->warn("[{}] Queueing workload update after completion, delta = {}", comm.rank(), subtree_delta);
                // This is acceptable generally: if this occurs, another process must cancel this attempt.
            else if (up_down_up_ == 3)
                log->critical("[{}] Queueing workload update after full completion, delta = {}", comm.rank(), subtree_delta);
        } else
        {
            assert(up_down_up_ < 2);
            up_down_up_ = 0;      // updating work on root cancels the up-down-up protocol
        }
    }
}

void
diy::Master::IExchangeInfoDUD::
manage()
{
    mpi::optional<mpi::status> ostatus = comm.iprobe(mpi::any_source, tags::iexchange);
    while(ostatus)
    {
        int k, v;
        receive(ostatus->source(), k, v);
        if (k == category::load_update)
        {
            // v = delta
            log->debug("[{}] subtree adjustment request from {}, delta = {}", comm.rank(), ostatus->source(), v);
            propagate_subtree_change(v);      // forwards tree unchanged
        } else if (k == category::cancel)
        {
            // v = attempt
            assert(v >= -1);
            terminate(v);
        } else if (k == category::complete)
        {
            handle_completion(ostatus->source(), v);
        }
        ostatus = comm.iprobe(mpi::any_source, tags::iexchange);
    }
    // start up-down-up protocol
    if (subtree_load_ == 0 && comm.rank() == 0 && up_down_up_ == 0)
    {
        // debugging
        if (initial_dud)
        {
            prof >> "iexchange-manage";        // consensus-time cannot nest in iexchange-manage
            prof << "consensus-time";
            prof << "iexchange-manage";
            initial_dud = false;
        }
        up_down_up_ = 1;
        clear_child_acknowledgments();
        if (descendant_acknowledgments)
        {
            notify_descendants(category::complete, ++current_attempt_);
            log->info("Started up-down-up, attempt = {}", current_attempt_);
        } else // no descendants
            up_down_up_ = 3;
    }
    while(advance());
}

void
diy::Master::IExchangeInfoDUD::
terminate(int attempt)
{
    if (up_down_up_ == 0) // already cancelled
        return;
    if (attempt != current_attempt_)
        return;
    log->warn("[{}] cancelling attempt {}", comm.rank(), attempt);
    assert(attempt >= 0);
    up_down_up_ = 0;
    if (comm.rank() != 0)
    {
        transmit(ancestor(), category::cancel, attempt);    // forward cancellation
        if (up_down_up_ >= 2)
            log->critical("[{}] sending cancellation after completion", comm.rank());
        current_attempt_ = -1;       // future cancellations for this attempt will be obsolete
    }
}

void
diy::Master::IExchangeInfoDUD::
handle_completion(int sender, int attempt)
{
    if (attempt < -1)
    {
        log->critical("[{}] completion with sender = {}, attempt = {}", comm.rank(), sender, attempt);
        assert(attempt >= -1);
    }
    while(advance());     // clear completed requests: necessary since requests may have been received;
                          // now receiving responses to them; they remain in our pending_
    if (sender == ancestor())
    {
        if (attempt == current_attempt_)       // confirmation of completion
        {
            assert(up_down_up_ == 2);
            log->info("[{}] received completion confirmation from parent, attempt = {}; ongoing = {}, subtree = {}, outdated = {}",
                      comm.rank(), attempt, ongoing(), subtree_load_, outdated());
            up_down_up_ = 3;
            assert(!ongoing() && !outdated());
        } else
        {
            current_attempt_ = attempt;
            up_down_up_ = 1;
            // verify no changes occurred
            if (ongoing() || outdated())
                terminate(attempt);
        }
        // forward message to descendants
        if (up_down_up_ > 0)
        {
            clear_child_acknowledgments();
            if (descendant_acknowledgments)
            {
                log->info("[{}] notifying descendants of completion, attempt = {}", comm.rank(), attempt);
                notify_descendants(category::complete, attempt);
            }
            else if (up_down_up_ < 2)     // no descendants, immediately signal parent back unless final completion
            {
                up_down_up_ = 2;
                log->info("[{}] signaling completion to parent (1), attempt = {}, ongoing = {}", comm.rank(), attempt, ongoing());
                transmit(ancestor(), category::complete, attempt);
            }
        }
    } else // signal from a descendant
    {
        if (attempt == current_attempt_)
        {
            int descendant_mask = lowest_set_bit(sender);
            descendant_acknowledgments &= ~descendant_mask;
            if (descendant_acknowledgments == 0)       // completed
            {
                if (comm.rank() != 0)
                {
                    if (ongoing() || outdated())        // heard from all descendants but something incomplete
                        terminate(attempt);
                    else
                    {
                        up_down_up_ = 2;
                        log->info("[{}] signaling completion to parent (2), attempt = {}, ongoing = {}", comm.rank(), attempt, ongoing());
                        transmit(ancestor(), category::complete, attempt);
                    }
                }
                else if (up_down_up_ == 1)
                {
                    log->info("[{}] received completion confirmation from descendants at root, attempt = {}", comm.rank(), attempt);
                    // start final down phase
                    up_down_up_ = 3;
                    notify_descendants(category::complete, attempt);
                }
            }
        } // else obsolete attempt confirmation, discard
    }
}

void
diy::Master::IExchangeInfoDUD::
clear_child_acknowledgments()
{
    descendant_acknowledgments = 0;
    int descendant_mask = 1;
    int descendant = descendant_mask | comm.rank();
    while (descendant != comm.rank() && descendant < comm.size())
    {
        descendant_acknowledgments |= descendant_mask;
        descendant_mask <<= 1;
        descendant = descendant_mask | comm.rank();
    }
}

void
diy::Master::IExchangeInfoDUD::
notify_descendants(int marker, int val)
{
    int descendant_mask = 1;
    int descendant = descendant_mask | comm.rank();
    while (descendant != comm.rank() && descendant < comm.size())
    {
        transmit(descendant, marker, val);
        descendant_mask <<= 1;
        descendant = descendant_mask | comm.rank();
    }
}

bool
diy::Master::IExchangeInfoDUD::
advance()
{
  bool accomplished = false;
  for (auto iter = pending_.begin(); iter != pending_.end();)
  {
    mpi::optional<mpi::status> ostatus = iter->async_op.test();
    if (ostatus)
    {
      accomplished = true;
      iter = pending_.erase(iter);
    }
    else
      ++iter;
  }
  return accomplished;
}

