void FPropertyTable::DeleteColumn(const TSharedRef<IPropertyTableColumn>& Column)
{
	TSet<TSharedRef<IPropertyTableCell>> NewSelection;
	for (const TSharedRef<IPropertyTableCell>& Cell : ActiveSelection)
	{
		if (Cell->GetOwningColumn() != Column)
		{
			NewSelection.Add(Cell);
		}
	}

	TableColumns.Remove(Column);
	TableStructureChanged.Broadcast();

	if (NewSelection.Num() != ActiveSelection.Num())
	{
		ApplySelection(NewSelection);
	}
}

void FPropertyTable::DeleteRow(const TSharedRef<IPropertyTableRow>& Row)
{
	if (!Row->HasChildren() && !Row->GetSource()->AsPropertyPath().IsValid())
	{
		const TWeakObjectPtr<UObject> Obj = Row->GetSource()->AsUObject();
		ObjectNodeMap.Remove(Obj);
		if (!Obj.IsValid())
		{
			CleanupInvalidNodes();
		}
	}

	TSet<TSharedRef<IPropertyTableCell>> NewSelection;
	for (const TSharedRef<IPropertyTableCell>& Cell : ActiveSelection)
	{
		if (Cell->GetOwningRow() != Row)
		{
			NewSelection.Add(Cell);
		}
	}

	TableRows.Remove(Row);
	TableStructureChanged.Broadcast();

	for (const TSharedRef<IPropertyTableColumn>& Col : TableColumns)
	{
		Col->DiscardCellsForRow(Row);
	}

	if (NewSelection.Num() != ActiveSelection.Num())
	{
		ApplySelection(NewSelection);
	}
}

void FPropertyTable::CleanupInvalidNodes()
{
	TArray<TSharedRef<FObjectPropertyNode>> ValidEntries;
	for (auto It = ObjectNodeMap.CreateIterator(); It; ++It)
	{
		const TWeakObjectPtr<UObject> Key = It.Key();
		if (!Key.IsValid())
		{
			ValidEntries.Add(It.Value());
		}
	}

	ObjectNodeMap.Empty();
	for (auto It = ValidEntries.CreateIterator(); It; ++It)
	{
		const TSharedRef<FObjectPropertyNode>& Node = *It;
		ObjectNodeMap.Add(Node->GetTargetObject(0), Node);
	}
}

