TArray<FPropertyInfo> FPropertyTable::GetAvailableExtensions(const TSharedRef<FPropertyPath>& Path) const
{
	TArray<FPropertyInfo> ExtensionsList;
	for (auto It = ObjectNodeMap.CreateConstIterator(); It; ++It)
	{
		TArray<FPropertyInfo> Candidates = FPropertyNode::GetPossibleExtensionsForPath(Path, It.Value());
		for (auto ExtIt = Candidates.CreateIterator(); ExtIt; ++ExtIt)
		{
			const FPropertyInfo& Info = *ExtIt;
			if (Info.ArrayIndex == INDEX_NONE &&
				(Info.Property->IsA(UStructProperty::StaticClass()) ||
					Info.Property->IsA(UArrayProperty::StaticClass())))
			{
				bool bDuplicateFound = false;
				for (auto ExistingIt = ExtensionsList.CreateConstIterator(); ExistingIt; ++ExistingIt)
				{
					if (*ExistingIt == Info)
					{
						bDuplicateFound = true;
						break;
					}
				}

				if (!bDuplicateFound)
				{
					ExtensionsList.Add(Info);
				}
			}
		}
	}
	return ExtensionsList;
}

