void FPropertyTable::SortByColumnIdentifier(EColumnSortPriority::Type Priority, const FName& ColumnName, EColumnSortMode::Type Mode)
{
	for (auto It = TableColumns.CreateIterator(); It; ++It)
	{
		const TSharedRef<IPropertyTableColumn> Col = *It;
		if (Col->GetIdentifier() == ColumnName)
		{
			SortByColumn(Col, Mode);
			break;
		}
	}
}

void FPropertyTable::SortByColumn(const TSharedRef<IPropertyTableColumn>& Column, EColumnSortMode::Type Mode)
{
	if (!Column->CanSort())
	{
		SortedColumn = nullptr;
		SortedMode = EColumnSortMode::None;
		return;
	}

	SortedColumn = Column;
	EColumnSortMode::Type PreviousMode = SortedMode;
	SortedMode = Mode;

	if (SortedMode == EColumnSortMode::None)
	{
		return;
	}

	Column->Sort(TableRows, SortedMode);

	if (SortedColumn.IsValid())
	{
		TableStructureChanged.Broadcast();
	}
}

void SetDataValue(const TSharedRef<IPropertyTableCell>& Cell, FString Value)
{
	if (Cell->IsLocked())
	{
		return;
	}

	TSharedPtr<FPropertyNode> Node = Cell->GetPropertyNode();
	if (Node.IsValid())
	{
		UProperty* Prop = Node->GetProperty();
		if (Prop->IsA(UNameProperty::StaticClass()))
		{
			Value = Value.TrimQuotes().Replace(TEXT("\n"), TEXT(""));
		}
	}

	FString OriginalValue = Cell->GetValueAsString();
	if (OriginalValue != Value)
	{
		Cell->SetValueFromString(Value);
	}
}

void FPropertyTable::PasteContent(const FString& Text, const TSharedRef<IPropertyTableCell>& TargetCell)
{
	if (!ActiveSelection.Contains(TargetCell))
	{
		return;
	}

	int32 CurrentRowIndex = 0;
	int32 CurrentColumnIndex = 0;
	TSharedPtr<IPropertyTableCell> StartCell = TargetCell;
	TSharedPtr<IPropertyTableCell> DestinationCell = TargetCell;

	TArray<FString> LineBuffer;
	Text.ParseIntoArray(LineBuffer, TEXT("\n"), true);

	TArray<FString> CellBuffer;
	LineBuffer[CurrentRowIndex++].ParseIntoArray(CellBuffer, TEXT("\t"), false);

	int32 MaxOperationsBeforeWarning = GetDefault<UEditorPerProjectUserSettings>()->PropertyMatrix_NumberOfPasteOperationsBeforeWarning;

	const bool bShowCancel = false;
	const bool bShowProgress = ActiveSelection.Num() > MaxOperationsBeforeWarning;
	GWarn->BeginSlowTask(LOCTEXT("UpdatingPropertiesSlowTaskLabel", "Updating properties..."), bShowProgress, bShowCancel);

	if (LineBuffer.Num() == 1 && CellBuffer.Num() == 1)
	{
		int32 CellCounter = 0;
		for (auto It = ActiveSelection.CreateIterator(); It; ++It)
		{
			SetDataValue(*It, CellBuffer[0]);

			if (bShowProgress)
			{
				GWarn->UpdateProgress(CellCounter, ActiveSelection.Num());
				++CellCounter;
			}
		}
	}
	else if (StartSelectionRange.IsValid() && EndSelectionRange.IsValid())
	{
		while (DestinationCell.IsValid() && ActiveSelection.Contains(DestinationCell.ToSharedRef()) && CurrentColumnIndex < CellBuffer.Num())
		{
			SetDataValue(DestinationCell.ToSharedRef(), CellBuffer[CurrentColumnIndex++]);

			DestinationCell = AdvanceToNextCellInRow(DestinationCell.ToSharedRef());

			if ((!DestinationCell.IsValid() || !ActiveSelection.Contains(DestinationCell.ToSharedRef()) || CurrentColumnIndex == CellBuffer.Num()) && CurrentRowIndex < LineBuffer.Num())
			{
				DestinationCell = AdvanceToNextCellInColumn(StartCell.ToSharedRef());
				if (DestinationCell.IsValid() && ActiveSelection.Contains(DestinationCell.ToSharedRef()))
				{
					CurrentColumnIndex = 0;
					StartCell = DestinationCell;
					LineBuffer[CurrentRowIndex++].ParseIntoArray(CellBuffer, TEXT("\t"), false);

					if (bShowProgress)
					{
						GWarn->UpdateProgress(CurrentRowIndex, LineBuffer.Num());
					}
				}
			}
		}
	}

	GWarn->EndSlowTask();
}

TSharedPtr<IPropertyTableColumn> FPropertyTable::FindNextValidColumn(int32 StartIndex, int32 Step) const
{
	TSharedPtr<IPropertyTableColumn> Column;
	for (int32 Index = StartIndex; Index >= 0 && Index < TableColumns.Num() && (!Column.IsValid() || !Column->CanSelectCells()); Index += Step)
	{
		Column = TableColumns[Index];
	}

	if (!Column.IsValid() || !Column->CanSelectCells())
	{
		return nullptr;
	}
	return Column;
}

TSharedPtr<IPropertyTableRow> FPropertyTable::FindNextValidRow(int32 StartIndex, int32 Step) const
{
	TSharedPtr<IPropertyTableRow> Row;
	for (int32 Index = StartIndex; Index >= 0 && Index < TableRows.Num() && (!Row.IsValid() || !Row->HasDataCells()); Index += Step)
	{
		Row = TableRows[Index];
	}

	if (!Row.IsValid() || !Row->HasDataCells())
	{
		return nullptr;
	}
	return Row;
}

