TSharedPtr<IPropertyTableCell> FPropertyTable::AdvanceToNextCellInRow(const TSharedRef<IPropertyTableCell>& Cell)
{
	const int32 FoundIndex = TableColumns.Find(Cell->GetOwningColumn());
	if (FoundIndex == INDEX_NONE)
	{
		return nullptr;
	}

	const int32 BeginIndex = FoundIndex + 1;
	const int32 Increment = 1;
	TSharedPtr<IPropertyTableColumn> NextCol = FindNextValidColumn(BeginIndex, Increment);
	if (!NextCol.IsValid())
	{
		return nullptr;
	}
	return NextCol->GetCell(Cell->GetOwningRow());
}

TSharedPtr<IPropertyTableCell> FPropertyTable::MoveToPreviousCellInRow(const TSharedRef<IPropertyTableCell>& Cell)
{
	const int32 FoundIndex = TableColumns.Find(Cell->GetOwningColumn());
	if (FoundIndex == INDEX_NONE)
	{
		return nullptr;
	}

	const int32 BeginIndex = FoundIndex - 1;
	const int32 Increment = -1;
	TSharedPtr<IPropertyTableColumn> PrevCol = FindNextValidColumn(BeginIndex, Increment);
	if (!PrevCol.IsValid())
	{
		return nullptr;
	}
	return PrevCol->GetCell(Cell->GetOwningRow());
}

TSharedPtr<IPropertyTableCell> FPropertyTable::AdvanceToNextCellInColumn(const TSharedRef<IPropertyTableCell>& Cell)
{
	const int32 FoundIndex = TableRows.Find(Cell->GetOwningRow());
	if (FoundIndex == INDEX_NONE)
	{
		return nullptr;
