	const int32 BeginIndex = FoundIndex + 1;
	const int32 Increment = 1;
	TSharedPtr<IPropertyTableRow> NextRow = FindNextValidRow(BeginIndex, Increment);
	if (!NextRow.IsValid())
	{
		return nullptr;
	}
	return Cell->GetOwningColumn()->GetCell(NextRow.ToSharedRef());
}

TSharedPtr<IPropertyTableCell> FPropertyTable::MoveToPreviousCellInColumn(const TSharedRef<IPropertyTableCell>& Cell)
