	TSharedPtr<IPropertyTableRow> PrevRow = FindNextValidRow(BeginIndex, Increment);
	if (!PrevRow.IsValid())
	{
		return nullptr;
	}
	return Cell->GetOwningColumn()->GetCell(PrevRow.ToSharedRef());
