void FPropertyTable::SetActiveCell(const TSharedPtr<IPropertyTableCell>& Cell)
{
	if (ActiveCell == Cell || !SupportsCellSelection())
	{
		return;
	}

	if (ActiveCell.IsValid())
	{
		ActiveCell->ExitEditMode();
	}

	if (Cell.IsValid())
	{
		ActiveRow = Cell->GetOwningRow();
		ActiveColumn = Cell->GetOwningColumn();
	}

	ActiveCell = Cell;

	bool bTriggerSelectionEvent = false;
	if (ActiveRow.IsValid() && (!ActiveRowSelection.Contains(ActiveRow.ToSharedRef()) || (ActiveCell.IsValid() && !ActiveSelection.Contains(ActiveCell.ToSharedRef()))))
	{
		ActiveRowSelection.Empty();
		ActiveRowSelection.Add(ActiveRow.ToSharedRef());
		bTriggerSelectionEvent = true;
	}

	if (ActiveCell.IsValid() && !ActiveSelection.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveSelection.Empty();
		ActiveSelection.Add(ActiveCell.ToSharedRef());
		StartSelectionRange = ActiveCell;
		EndSelectionRange = ActiveCell;
		bTriggerSelectionEvent = true;
	}

	if (bTriggerSelectionEvent)
	{
		SelectionChangedEvent.Broadcast();
	}
}

void FPropertyTable::SetActiveColumn(const TSharedPtr<IPropertyTableColumn>& Column)
{
	if (ActiveColumn == Column || !SupportsCellSelection())
	{
		return;
	}

	ActiveColumn = Column;

	if (ActiveCell.IsValid() && ActiveCell->GetOwningColumn() != Column)
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}
}

void FPropertyTable::SetActiveRow(const TSharedPtr<IPropertyTableRow>& Row)
{
	if (ActiveRow == Row || !SupportsRowSelection())
	{
		return;
	}

	ActiveRow = Row;

	if (!ActiveRow.IsValid() || (ActiveCell.IsValid() && ActiveCell->GetOwningRow() != ActiveRow))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}

	if (ActiveRow.IsValid() && !ActiveRowSelection.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRowSelection.Empty();
		ActiveRowSelection.Add(ActiveRow.ToSharedRef());
		SelectionChangedEvent.Broadcast();
	}
}

void FPropertyTable::ApplyRowSelection(const TSet<TSharedRef<IPropertyTableRow>>& Rows)
{
	ActiveColumnSelection.Empty();
	ActiveRowSelection.Empty();

	if (!SupportsRowSelection())
	{
		return;
	}

	ActiveRowSelection.Append(Rows);

	TSet<TSharedRef<IPropertyTableCell>> PreviousCells(ActiveSelection);
	bool bRemovedCells = false;

	for (auto It = PreviousCells.CreateConstIterator(); It; ++It)
	{
		const TSharedRef<IPropertyTableCell>& Cell = *It;
		if (!ActiveRowSelection.Contains(Cell->GetOwningRow()))
		{
			ActiveSelection.Remove(Cell);
			ActiveColumnSelection.Add(Cell->GetOwningColumn());
			bRemovedCells = true;
		}
	}

	if (bRemovedCells)
	{
		StartSelectionRange = nullptr;
		EndSelectionRange = nullptr;
	}

	if (ActiveRow.IsValid() && !ActiveRowSelection.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRow = nullptr;
	}

	if (ActiveColumn.IsValid() && !ActiveColumnSelection.Contains(ActiveColumn.ToSharedRef()))
	{
		ActiveColumn = nullptr;
	}

	if (ActiveCell.IsValid() && !ActiveSelection.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}

	SelectionChangedEvent.Broadcast();
}

void FPropertyTable::ApplyCellSelection(const TSet<TSharedRef<IPropertyTableCell>>& Cells)
{
	ActiveSelection.Empty();

	if (!SupportsCellSelection())
	{
		return;
	}

	ActiveSelection.Append(Cells);
	ActiveColumnSelection.Empty();
	ActiveRowSelection.Empty();

	TSharedPtr<IPropertyTableCell> LastCell;
	for (auto It = ActiveSelection.CreateConstIterator(); It; ++It)
	{
		LastCell = *It;
		ActiveRowSelection.Add(LastCell->GetOwningRow());
		ActiveColumnSelection.Add(LastCell->GetOwningColumn());
	}

	if (ActiveRow.IsValid() && !ActiveRowSelection.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRow = nullptr;
	}

	if (ActiveColumn.IsValid() && !ActiveColumnSelection.Contains(ActiveColumn.ToSharedRef()))
	{
		ActiveColumn = nullptr;
	}

	if (LastCell.IsValid() && ActiveSelection.Num() == 1)
	{
		StartSelectionRange = LastCell;
		EndSelectionRange = LastCell;
	}
	else
	{
		StartSelectionRange = nullptr;
		EndSelectionRange = nullptr;
	}

	if (ActiveCell.IsValid() && !ActiveSelection.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}

	SelectionChangedEvent.Broadcast();
}

void FPropertyTable::SelectRectangularRegion(const TSharedRef<IPropertyTableCell>& TopLeft, const TSharedRef<IPropertyTableCell>& BottomRight)
{
	ActiveColumnSelection.Empty();
	ActiveRowSelection.Empty();
	ActiveSelection.Empty();

	const int32 StartRow = TableRows.Find(TopLeft->GetOwningRow());
	const int32 EndRow = TableRows.Find(BottomRight->GetOwningRow());

	for (int32 RowIndex = StartRow; RowIndex < TableRows.Num() && RowIndex <= EndRow; ++RowIndex)
	{
		ActiveRowSelection.Add(TableRows[RowIndex]);
	}

	const int32 StartCol = TableColumns.Find(TopLeft->GetOwningColumn());
	const int32 EndCol = TableColumns.Find(BottomRight->GetOwningColumn());

	for (int32 ColIndex = StartCol; ColIndex < TableColumns.Num() && ColIndex <= EndCol; ++ColIndex)
	{
		ActiveColumnSelection.Add(TableColumns[ColIndex]);
		for (auto RowIt = ActiveRowSelection.CreateConstIterator(); RowIt; ++RowIt)
		{
			ActiveSelection.Add(TableColumns[ColIndex]->GetCell(*RowIt));
		}
	}

	if (ActiveRow.IsValid() && !ActiveRowSelection.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRow = nullptr;
	}

	if (ActiveColumn.IsValid() && !ActiveColumnSelection.Contains(ActiveColumn.ToSharedRef()))
	{
		ActiveColumn = nullptr;
	}

	StartSelectionRange = TopLeft;
	EndSelectionRange = BottomRight;

	if (ActiveCell.IsValid() && !ActiveSelection.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}

	SelectionChangedEvent.Broadcast();
}

