TSharedRef<FObjectPropertyNode> FPropertyTable::AcquireObjectNode(const TWeakObjectPtr<UObject>& Object)
{
	TSharedRef<FObjectPropertyNode>* NodePtr = ObjectNodeMap.Find(Object);
	if (NodePtr != nullptr)
	{
		return *NodePtr;
	}

	TSharedRef<FObjectPropertyNode> NewNode(new FObjectPropertyNode());
	NewNode->AddObject(Object.Get());

	FPropertyNodeInitParams Params;
	Params.bCreateCategoryNodes = false;
	NewNode->InitializeNode(Params);

	ObjectNodeMap.Add(Object, NewNode);
	return NewNode;
}

