void FPropertyTable::RebuildRows()
{
	if (LayoutDirection == EPropertyTableOrientation::AlignPropertiesInColumns)
	{
		TMultiMap<UObject*, TSharedRef<IPropertyTableRow>> RowMap;
		for (int32 RowIndex = 0; RowIndex < TableRows.Num(); ++RowIndex)
		{
			RowMap.Add(TableRows[RowIndex]->GetSource()->AsUObject().Get(), TableRows[RowIndex]);
		}

		TableRows.Empty();

		for (auto It = ObjectsList.CreateConstIterator(); It; ++It)
		{
			const TWeakObjectPtr<UObject>& Obj = *It;
			if (Obj.IsValid())
			{
				const TSharedRef<FObjectPropertyNode> RootNode = AcquireObjectNode(Obj);
				const TSharedPtr<FPropertyNode> PropertyNode = FPropertyNode::FindPropertyNodeByPath(BasePath, RootNode);

				if (PropertyNode.IsValid())
				{
					UProperty* Prop = PropertyNode->GetProperty();
					if (Prop != nullptr && Prop->IsA(UArrayProperty::StaticClass()))
					{
						for (int32 ChildIndex = 0; ChildIndex < PropertyNode->GetChildCount(); ++ChildIndex)
						{
							TSharedPtr<FPropertyNode> ChildNode = PropertyNode->GetChildNode(ChildIndex);
							FPropertyInfo Extension;
							Extension.Property = ChildNode->GetProperty();
							Extension.ArrayIndex = ChildNode->GetArrayIndex();
							TSharedRef<FPropertyPath> Path = FPropertyPath::CreateEmpty()->ExtendPath(Extension);

							TArray<TSharedRef<IPropertyTableRow>> Matches;
							bool bFound = false;
							RowMap.MultiFind(Obj.Get(), Matches);
							for (int32 MapIndex = 0; MapIndex < Matches.Num(); ++MapIndex)
							{
								if (FPropertyPath::AreEqual(Path, Matches[MapIndex]->GetPartialPath()))
								{
									bFound = true;
									TableRows.Add(Matches[MapIndex]);
									break;
								}
							}

							if (!bFound)
							{
								TableRows.Add(MakeShareable(new FPropertyTableRow(SharedThis(this), Obj, Path)));
							}
						}
					}
					else
					{
						TArray<TSharedRef<IPropertyTableRow>> Matches;
						bool bFound = false;
						RowMap.MultiFind(Obj.Get(), Matches);
						for (int32 MapIndex = 0; MapIndex < Matches.Num(); ++MapIndex)
						{
							if (Matches[MapIndex]->GetPartialPath()->GetPropertyCount() == 0)
							{
								bFound = true;
								TableRows.Add(Matches[MapIndex]);
								break;
							}
						}

						if (!bFound)
						{
							TableRows.Add(MakeShareable(new FPropertyTableRow(SharedThis(this), Obj)));
						}
					}
				}
			}
		}
	}

	const TSharedPtr<IPropertyTableColumn> SortCol = SortedColumn.Pin();
	if (SortCol.IsValid() && SortedMode != EColumnSortMode::None)
	{
		SortCol->Sort(TableRows, SortedMode);
	}

	TableStructureChanged.Broadcast();
}

void FPropertyTable::RebuildColumns()
{
	if (LayoutDirection == EPropertyTableOrientation::AlignPropertiesInColumns)
	{
		TMultiMap<UProperty*, TSharedRef<IPropertyTableColumn>> ColumnMap;
		for (int32 ColIndex = 0; ColIndex < TableColumns.Num(); ++ColIndex)
		{
			TSharedRef<IDataSource> Source = TableColumns[ColIndex]->GetSource();
			TSharedPtr<FPropertyPath> Path = Source->AsPropertyPath();
			if (Path.IsValid() && Path->GetPropertyCount() > 0)
			{
				ColumnMap.Add(Path->GetRootProperty().Property.Get(), TableColumns[ColIndex]);
			}
		}

		TableColumns.Empty();

		if (bDisplayRowHeader)
		{
			TSharedRef<IPropertyTableColumn> NewCol = MakeShareable(new FPropertyTableRowHeaderColumn(SharedThis(this)));
			TableColumns.Add(NewCol);
		}

		if (bShowObjectNames)
		{
			TSharedRef<IPropertyTableColumn> NewCol = MakeShareable(new FPropertyTableObjectNameColumn(SharedThis(this)));
			NewCol->SetFrozenState(true);
			TableColumns.Add(NewCol);
		}

		TArray<TWeakObjectPtr<UStruct>> UniqueTypes;
		TArray<int> TypeCounter;

		for (auto It = ObjectsList.CreateConstIterator(); It; ++It)
		{
			UObject* Obj = *It;
			if (!Obj)
			{
				continue;
			}

			const TSharedRef<FObjectPropertyNode> RootNode = AcquireObjectNode(Obj);
			TWeakObjectPtr<UStruct> Type;

			if (BasePath->GetPropertyCount() == 0)
			{
				Type = RootNode->GetObjectBaseClass();
			}
			else
			{
				const TSharedPtr<FPropertyNode> PropNode = FPropertyNode::FindPropertyNodeByPath(BasePath, RootNode);
				if (!PropNode.IsValid())
				{
					continue;
				}

				const TWeakObjectPtr<UProperty> Prop = PropNode->GetProperty();
				if (!Prop.IsValid() || !Prop->IsA(UStructProperty::StaticClass()))
				{
					continue;
				}

				UStructProperty* StructProp = Cast<UStructProperty>(Prop.Get());
