#include "util.h"
// [[Rcpp::export]]
NumericMatrix calculate_term_score(NumericMatrix topic_distributions) {
  // compute term score according to Blei and Lafferty (2009)
  int num_terms = topic_distributions.nrow();
  int num_topics = topic_distributions.ncol();
  NumericMatrix result_matrix(num_terms, num_topics);

  for (int t = 0; t < num_terms; t++) {
    double geometric_mean = 1.0;
    for (int j = 0; j < num_topics; j++) {
      geometric_mean *= topic_distributions(t, j);
    }
    for (int j = 0; j < num_topics; j++) {
      result_matrix(t, j) = topic_distributions(t, j) * 
        log(topic_distributions(t, j) / pow(geometric_mean, (1.0 / num_topics)));
    }
  }

  return result_matrix;
}
// [[Rcpp::export]]
NumericVector evaluate_coherence(List corpus_stats, NumericMatrix word_topic_matrix) {
  int num_topics = word_topic_matrix.ncol();
  int num_words = word_topic_matrix.nrow();
  NumericMatrix document_topic_counts = corpus_stats["document_topic_counts"];
  NumericVector coherence_values(num_topics);
  NumericVector document_ids = corpus_stats["document_ids"];
  for (int j = 0; j < num_topics; j++) {
    for (int w2 = 2; w2 < num_words; w2++) {
      for (int w1 = 0; w1 < w2-1; w1++) {
        double doc_count = 0.0;
        double co_doc_count = 0.0;
        for (int d = 0; d < document_ids.size(); d++) {
          doc_count += (double) (document_ids[d] == word_topic_matrix(w1, j));
          co_doc_count += (double) (document_ids[d] == word_topic_matrix(w2, j) &&
                                    document_ids[d] == word_topic_matrix(w1, j));
        }
        coherence_values[j] += log((co_doc_count + 1.0) / doc_count);
      }
    }
  }
  return coherence_values;
}

