/**
  Draws the widget's box() to fill the entire widget area.
  If the box is not rectangular, this also redraws the exposed parent area.
  Sets up drawing style and colors for subsequent text rendering.
*/
void Widget::render_box() const {
  this->render_box(Rectangle(w(), h()));
}

void Widget::render_box(const Rectangle& r) const {
  Box* frame = this->box();
  if (!frame->fills_rectangle()) render_background();
  drawstyle(style(), flags_ & ~OUTPUT);
  frame->draw(r);
}

/**
  Similar to render_box() but only draws the boundary using INVISIBLE flag.
  Works only for rectangular boxes. Useful for reducing flicker when
  widgets erase their contents during redraw.
*/
void Widget::render_frame() const {
  drawstyle(style(), (flags_ & ~OUTPUT) | INVISIBLE);
  box()->draw(Rectangle(w(), h()));
  setdrawflags(flags_);
}

/**
  Calls render_label() with the inner area of the box() and alignment from flags().
  Uses labelfont() and labelcolor(). If OUTPUT flag is set, uses textfont()/textcolor()
  instead (legacy behavior).
*/
void Widget::render_label() const {
  Flags state = this->flags();
  if (!image() && (!label() || !*label() ||
                   ((state & 15) && !(state & ALIGN_INSIDE)))) return;

  Rectangle r(w(), h()); 
  box()->inset(r);

  drawstyle(style(), this->flags() ^ OUTPUT);
  render_label(r, state);
}

/**
  Renders labels inside the widget using current font/color settings.
  \a bounds defines the bounding rectangle, \a state controls alignment.
  If no ALIGN flags or no ALIGN_INSIDE, image() fills the box instead.
  Otherwise, attempts to place both label() and image() nicely.
*/
void Widget::render_label(const Rectangle& inner, Flags state) const {
  const Symbol* icon = image();
  Rectangle area(inner);

  if (icon) {
    int imgW = area.w();
    int imgH = area.h();
    icon->measure(imgW, imgH);

    if (state & ALIGN_CLIP) push_clip(area);

    // Resize logic based on flags
    if (state & RESIZE_FIT) {
      if ((state & RESIZE_FILL) || imgW > area.w() || imgH > area.h()) {
        if (imgW * area.h() > imgH * area.w()) {
          imgH = imgH * area.w() / imgW;
          imgW = area.w();
        } else {
          imgW = imgW * area.h() / imgH;
          imgH = area.h();
        }
      }
    } else if (state & RESIZE_FILL) {
      imgW = area.w();
      imgH = area.h();
    }

    // Special centering when no alignment flags are set
    if (label_ && !(state & 0x3f) && !(label_[0] == '@' && label_[1] == ';')) {
      int margin = (area.h() - int(imgH + labelsize() + leading() + .5)) >> 1;
      if (margin < 0) {
        if (imgW < area.w()) {
          int txtW = area.w() - imgW;
          int txtH = area.h();
          measure(label_, txtW, txtH, state);
          int offset = (area.w() - imgW - txtW) >> 1;
          if (offset >= 0) {
            area.move_x(offset);
            state |= ALIGN_LEFT | ALIGN_INSIDE;
            goto LAYOUT_OK;
          }
        }
        margin = 0;
      }
      area.move_y(margin);
      state |= ALIGN_TOP | ALIGN_INSIDE;
    LAYOUT_OK:;
    }

    if (state & ALIGN_CENTER) {
      Rectangle iconRect(area, imgW, imgH, 0);
      icon->draw(iconRect);
    } else {
      Rectangle iconRect(area, imgW, imgH, state);
      icon->draw(iconRect);

      if (state & ALIGN_TOP) area.set_y(iconRect.b());
      else if (state & ALIGN_BOTTOM) area.set_b(iconRect.y());
      else if (state & ALIGN_LEFT) area.set_x(iconRect.r());
      else if (state & ALIGN_RIGHT) area.set_r(iconRect.x());
      else area.set_y(iconRect.b());
    }
  }

  // Render text if applicable
  if ((!(state & fltk::ALIGN_POSITIONMASK) || (state & fltk::ALIGN_INSIDE)) &&
      area.w() > 0 && label_ && *label_) {
    if (area.w() > 6 && state & ALIGN_LEFT) {
      if (area.w() > 9) { area.move_x(3); area.move_r(-3); }
      else area.set_x(area.r() - 6);
    }
    if (area.w() > 6 && state & ALIGN_RIGHT) {
      if (area.w() > 9) area.move_r(-6);
      else area.w(6);
    }
    if (!icon && (state & ALIGN_CLIP)) push_clip(area);
    labeltype()->render(label_, area, state);
  } else {
    if (!icon) return;
  }

  if (state & ALIGN_CLIP) pop_clip();
}

/**
  Groups call this to draw the widget's label outside its boundaries.
  Uses flags() to determine position. Does nothing if no external alignment.
*/
void Group::render_outside_label(Widget& w) const {
  Flags state = w.flags();
  if (state & INVISIBLE) return;
  if (!(state & 15) || (state & ALIGN_INSIDE)) return;
  if (!w.label() || !*w.label()) return;

  Rectangle rect(w);
  if (state & ALIGN_TOP) {
    if (state & ALIGN_BOTTOM) {
      if (state & ALIGN_LEFT) {
        state &= ~(ALIGN_TOP | ALIGN_LEFT);
      } else {
        state &= ~ALIGN_BOTTOM;
      }
      if (state & ALIGN_RIGHT) {
        rect.x(rect.r() + 3);
        rect.set_r(this->w());
        state = (state & ~ALIGN_RIGHT) | ALIGN_LEFT;
      } else {
        rect.x(0);
        rect.w(w.x() - 3);
        state = state | ALIGN_RIGHT;
      }
    } else {
      state ^= (ALIGN_BOTTOM | ALIGN_TOP);
      rect.y(0);
      rect.h(w.y());
    }
  } else if (state & ALIGN_BOTTOM) {
    state ^= (ALIGN_BOTTOM | ALIGN_TOP);
    rect.y(rect.b());
    rect.set_b(h());
  } else if (state & ALIGN_LEFT) {
    state ^= (ALIGN_LEFT | ALIGN_RIGHT);
    rect.x(0);
    rect.w(w.x() - 3);
  } else if (state & ALIGN_RIGHT) {
    state ^= (ALIGN_LEFT | ALIGN_RIGHT);
    rect.x(rect.r() + 3);
    rect.set_r(this->w());
  }

  state = (state & ~(HIGHLIGHT | PUSHED)) | OUTPUT;
  drawstyle(w.style(), state);
  w.labeltype()->render(w.label(), rect, state);
}

/**
  Updates \a w and \a h to reflect the space needed for the label.
  Uses labelfont() and considers wrapping at arbitrary width 300.
*/
void Widget::measure_label(int& width, int& height) const {
  setfont(labelfont(), labelsize());
  width = height = 300;
  measure(label(), width, height, flags());
}

