PIXELFORMATDESCRIPTOR CreateDefaultPixelFormatDescriptor()
{
    PIXELFORMATDESCRIPTOR descriptor = {0};
    descriptor.nSize                 = sizeof(descriptor);
    descriptor.nVersion              = 1;
    descriptor.dwFlags =
        PFD_DRAW_TO_WINDOW | PFD_GENERIC_ACCELERATED | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
    descriptor.iPixelType   = PFD_TYPE_RGBA;
    descriptor.cColorBits   = 24;
    descriptor.cAlphaBits   = 8;
    descriptor.cDepthBits   = 24;
    descriptor.cStencilBits = 8;
    descriptor.iLayerType   = PFD_MAIN_PLANE;
    return descriptor;
}

std::vector<int> CreateDefaultPixelFormatAttributes(bool preserveSwap)
{
    std::vector<int> attributes;
    attributes.push_back(WGL_DRAW_TO_WINDOW_ARB);
    attributes.push_back(TRUE);
    attributes.push_back(WGL_ACCELERATION_ARB);
    attributes.push_back(WGL_FULL_ACCELERATION_ARB);
    attributes.push_back(WGL_SUPPORT_OPENGL_ARB);
    attributes.push_back(TRUE);
    attributes.push_back(WGL_DOUBLE_BUFFER_ARB);
    attributes.push_back(TRUE);
    attributes.push_back(WGL_PIXEL_TYPE_ARB);
    attributes.push_back(WGL_TYPE_RGBA_ARB);
    attributes.push_back(WGL_COLOR_BITS_ARB);
    attributes.push_back(24);
    attributes.push_back(WGL_ALPHA_BITS_ARB);
    attributes.push_back(8);
    attributes.push_back(WGL_DEPTH_BITS_ARB);
    attributes.push_back(24);
    attributes.push_back(WGL_STENCIL_BITS_ARB);
    attributes.push_back(8);
    attributes.push_back(WGL_SWAP_METHOD_ARB);
    attributes.push_back(preserveSwap ? WGL_SWAP_COPY_ARB : WGL_SWAP_UNDEFINED_ARB);
    attributes.push_back(0);
    return attributes;
}

int GetWGLFormatAttribute(HDC deviceContext, int pixelFormat, int attributeName, const FunctionsWGL *wglFunctions)
{
    int value = 0;
    if (wglFunctions->getPixelFormatAttribivARB == nullptr ||
        !wglFunctions->getPixelFormatAttribivARB(deviceContext, pixelFormat, 0, 1, &attributeName, &value))
    {
        return 0;
    }
    return value;
}
