void FGameplayAbilityActorInfo::InitializeFromActor(AActor* NewOwner, AActor* NewAvatar, UAbilitySystemComponent* NewASC)
{
	check(NewOwner);
	check(NewASC);
	OwnerActor = NewOwner;
	AvatarActor = NewAvatar;
	AbilitySystemComponent = NewASC;
	AffectedAnimInstanceTag = NewASC->AffectedAnimInstanceTag; 

	APlayerController* PreviousPC = PlayerController.Get();
	// Search for a player controller or pawn in the owner chain.
	AActor* CurrentActor = NewOwner;
	while (CurrentActor)
	{
		if (APlayerController* FoundPC = Cast<APlayerController>(CurrentActor))
		{
			PlayerController = FoundPC;
			break;
		}
		if (APawn* PawnRef = Cast<APawn>(CurrentActor))
		{
			PlayerController = Cast<APlayerController>(PawnRef->GetController());
			break;
		}
		CurrentActor = CurrentActor->GetOwner();
	}
	// Notify ASC if PlayerController was found for first time
	if (PreviousPC == nullptr && PlayerController.IsValid())
	{
		NewASC->OnPlayerControllerSet();
	}
	if (AActor* const AvatarPtr = AvatarActor.Get())
	{
		// Retrieve Components that we care about
		SkeletalMeshComponent = AvatarPtr->FindComponentByClass<USkeletalMeshComponent>();
		MovementComponent = AvatarPtr->FindComponentByClass<UMovementComponent>();
	}
	else
	{
		SkeletalMeshComponent = nullptr;
		MovementComponent = nullptr;
	}
}

void FGameplayAbilityActorInfo::AssignAvatarActor(AActor* NewAvatar)
{
	InitializeFromActor(OwnerActor.Get(), NewAvatar, AbilitySystemComponent.Get());
}

void FGameplayAbilityActorInfo::ResetActorReferences()
{
	OwnerActor = nullptr;
	AvatarActor = nullptr;
	PlayerController = nullptr;
	SkeletalMeshComponent = nullptr;
	MovementComponent = nullptr;
}

bool FGameplayAbilityActorInfo::IsLocallyControlled() const
{
	if (const APlayerController* PC = PlayerController.Get())
	{
		return PC->IsLocalController();
	}
	else if (IsNetAuthority())
	{
		// Non-players are always locally controlled on the server
		return true;
	}
	return false;
}

bool FGameplayAbilityActorInfo::IsLocallyControlledPlayer() const
{
	if (const APlayerController* PC = PlayerController.Get())
	{
		return PC->IsLocalController();
	}
	return false;
}

bool FGameplayAbilityActorInfo::IsNetAuthority() const
{
	// Make sure this works on pending kill actors
	AActor* const OwnerPtr = OwnerActor.Get(/*bEvenIfPendingKill=*/ true);
	if (OwnerPtr)
	{
		return (OwnerPtr->GetLocalRole() == ROLE_Authority);
	}
	// This rarely happens during shutdown cases for reasons that aren't quite clear
	ABILITY_LOG(Warning, TEXT("IsNetAuthority called when OwnerActor was invalid. Returning false. AbilitySystemComponent: %s"), *GetNameSafe(AbilitySystemComponent.Get()));
	return false;
}

void FGameplayAbilityActivationInfo::SetToPredicting(FPredictionKey Key)
{
	ActivationMode = EGameplayAbilityActivationMode::Predicting;
	PredictionKeyWhenActivated = Key;
	// Abilities can be cancelled by server at any time. There is no reason to have to wait until confirmation.
	// prediction keys keep previous activations of abilities from ending future activations.
	bCanBeEndedByOtherInstance = true;
}

