SweptSurface::SweptSurface(int pVal, int qVal, std::vector<double> knotUVal, std::vector<double> knotVVal, std::vector<std::vector<Point3D>> controlNetVal)
{
    p = pVal;
    q = qVal;
    knotU = knotUVal;
    knotV = knotVVal;
    controlNet = controlNetVal;
}

void SweptSurface::getTranslationalSweep(int pVal, std::vector<double> knotUVal, int qVal, std::vector<double> knotVVal, std::vector<Point3D> UnetVal, std::vector<Point3D> VnetVal)
{
    p = pVal;
    q = qVal;
    knotU = knotUVal;
    knotV = knotVVal;

    // Compute dimensions: U: r = n + p + 1, V: s = m + q + 1
    int r = static_cast<int>(knotU.size()) - 1;
    int s = static_cast<int>(knotV.size()) - 1;
    int n = r - p - 1;
    int m = s - q - 1;

    int N = n + 1; // number of control points in U-direction
    int M = m + 1; // number of control points in V-direction

    controlNet.assign(N, std::vector<Point3D>(M));
    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < M; ++j) {
            controlNet[i][j] = UnetVal[i] + VnetVal[j];
        }
    }
}

void SweptSurface::outputSweptSur(int& pOut, int& qOut, std::vector<double>& knotUOut, std::vector<double>& knotVOut, std::vector<std::vector<Point3D>>& controlNetOut)
{
    pOut = p;
    qOut = q;
    knotUOut = knotU;
    knotVOut = knotV;
    controlNetOut = controlNet;
}

void SweptSurface::getSweepSurface1(BSplineCurve T, BSplineCurve C, vector3D Bv, Matrix33 Sv, int K)
{
    p = C.getDegree();
    knotU = C.getKnotVec();
    q = T.getDegree();

    int ktv = static_cast<int>(T.getKnotVec().size());
    int nsect = K + 1;

    if (ktv <= nsect + q) {
        int m = nsect + q - ktv + 1;
        insertKnots(T, m);
        knotV = T.getKnotVec();
    } else {
        knotV = T.getKnotVec();
        if (ktv > nsect + q + 1) {
            nsect = ktv - q - 1;
        }
    }

    std::vector<double> vSections(nsect, 0.0);
    vSections[0] = 0.0;
    vSections[nsect - 1] = 1.0;

    for (int k = 1; k < nsect - 1; ++k) {
        double sum = 0.0;
        for (int j = 1; j <= q; ++j) {
            sum += knotV[k + j];
        }
        vSections[k] = sum / static_cast<double>(q);
    }

    std::vector<std::vector<Point3D>> QTotalvFixed;
    for (int k = 0; k < nsect; ++k) {
        std::vector<Point3D> Q = C.getControlPts();
        for (size_t i = 0; i < Q.size(); ++i) {
            Q[i] = Sv * Q[i];
        }

        vector3D yv = T.getFirstDerivative(vSections[k]).normalize();
        vector3D xv = Bv.normalize();
        vector3D zv = xv.crossp(yv);

        Point3D pTv = T.getPointAt(vSections[k]);
        Matrix33 Av(xv, yv, zv);

        for (size_t i = 0; i < Q.size(); ++i) {
            Q[i] = Av * Q[i] + pTv;
        }

        QTotalvFixed.push_back(Q);
    }

    int rows = static_cast<int>(QTotalvFixed.size());
    int cols = static_cast<int>(QTotalvFixed[0].size());

    std::vector<std::vector<Point3D>> QTotaluFixed(cols, std::vector<Point3D>(rows));
    for (int j = 0; j < cols; ++j) {
        for (int i = 0; i < rows; ++i) {
            QTotaluFixed[j][i] = QTotalvFixed[i][j];
        }
    }

    int n = static_cast<int>(C.getControlPts().size());
    for (int i = 0; i < n; ++i) {
        // TODO: interpolate across Q[0]....Q[nsect-1]
    }

    controlNet = QTotaluFixed;
}

void SweptSurface::insertKnots(BSplineCurve& T, int insertTimes)
{
    for (int i = 0; i < insertTimes; ++i) {
        double insertu = getMiddlePointOfLongestVSpan(T.getKnotVec());
        T = curvePointKnontInsertion(T.getn(), T.getDegree(), T.getKnotVec(), T.getControlPts(), insertu, 0, 1);
    }
}

double SweptSurface::getMiddlePointOfLongestVSpan(std::vector<double> KnotVec)
{
    int indLongSpan = 0;
    double MaxSpan = 0.0;

    for (int i = 0; i < static_cast<int>(KnotVec.size()) - 1; ++i) {
        double currentSpan = KnotVec[i + 1] - KnotVec[i];
        if (currentSpan > MaxSpan) {
            indLongSpan = i;
            MaxSpan = currentSpan;
        }
    }

    return (KnotVec[indLongSpan + 1] + KnotVec[indLongSpan]) / 2.0;
}

