    buffer->current_count = 0;
    buffer->entries = (overlap_data*)calloc(buffer->capacity, sizeof(overlap_data));

    uint64_t index;
    for (index = 0; index < buffer->capacity; index++)
    { 
        initialize_cigar_structure(&(buffer->entries[index].cigar_record));
        initialize_boundary_segments_alloc(&(buffer->entries[index].boundary_records));
    }
}

void reset_overlap_buffer(overlap_data_buffer* buffer)
{
    buffer->current_count = 0;
    buffer->mapped_count = 0;
    uint64_t idx = 0;
    for (idx = 0; idx < buffer->capacity; idx++)
    {   
        buffer->entries[idx].window_list_length = 0;
        reset_cigar_structure(&(buffer->entries[idx].cigar_record));
