        if (buffer->entries[idx].window_list_capacity != 0)
        {
            free(buffer->entries[idx].window_list);
        }
        destroy_cigar_structure(&(buffer->entries[idx].cigar_record));
        destroy_boundary_segments_alloc(&(buffer->entries[idx].boundary_records));
    }
    free(buffer->entries);
}

int extract_gap_position(Cigar_Data* data, int position)
{
    return (data->storage[position]>>32);
}

int extract_gap_offset(Cigar_Data* data, int position)
{
    uint32_t temp = ((uint32_t)(data->storage[position]));
    int value;
    if(temp & ((uint32_t)1))
    {
        temp = temp >> 1;
        value = temp;
        value = value * -1;
    }
    else
    {
        temp = temp >> 1;
        value = temp;
    }

    return value;
}

int add_to_overlap_buffer(overlap_data_buffer* buffer, overlap_data* entry, 
                          Read_Info* read_info, int include_ends)
{

    if (buffer->current_count + 1 > buffer->capacity)
    {
        buffer->capacity = buffer->capacity * 2;
        buffer->entries = (overlap_data*)realloc(buffer->entries, sizeof(overlap_data)*buffer->capacity);
        memset(buffer->entries + (buffer->capacity/2), 0, sizeof(overlap_data)*(buffer->capacity/2));
    }

    if (buffer->current_count!=0 && buffer->entries[buffer->current_count - 1].query_read_id == entry->query_read_id)
    {    
        if((buffer->entries[buffer->current_count - 1].seed_count > entry->seed_count)
           ||
           ((buffer->entries[buffer->current_count - 1].seed_count == entry->seed_count) && 
           (buffer->entries[buffer->current_count - 1].overlap_size <= entry->overlap_size)))
        {
            return 0;
        }
        else
        {
            buffer->current_count--;
        }
    }

    if(entry->target_start <= entry->query_start)
    {
        entry->query_start = entry->query_start - entry->target_start;
        entry->target_start = 0;
    }
    else
    {
        entry->target_start = entry->target_start - entry->query_start;
        entry->query_start = 0;
    }

    long long target_right = Get_READ_LENGTH((*read_info), entry->target_id) - entry->target_end - 1;
    long long query_right = Get_READ_LENGTH((*read_info), entry->query_id) - entry->query_end - 1;

    if(target_right <= query_right)
    {
        entry->target_end = Get_READ_LENGTH((*read_info), entry->target_id) - 1;
        entry->query_end = entry->query_end + target_right;        
    }
    else
    {
        entry->target_end = entry->target_end + query_right;
        entry->query_end = Get_READ_LENGTH((*read_info), entry->query_id) - 1;
    }

    if (entry->target_strand == 1)
    {
        buffer->entries[buffer->current_count].target_id = entry->target_id;
        buffer->entries[buffer->current_count].target_end = Get_READ_LENGTH((*read_info), entry->target_id) - entry->target_start - 1;
        buffer->entries[buffer->current_count].target_start = Get_READ_LENGTH((*read_info), entry->target_id) - entry->target_end - 1;
        buffer->entries[buffer->current_count].target_strand = 0;
        buffer->entries[buffer->current_count].query_id = entry->query_id;
        buffer->entries[buffer->current_count].query_end = Get_READ_LENGTH((*read_info), entry->query_id) - entry->query_start - 1;
        buffer->entries[buffer->current_count].query_start = Get_READ_LENGTH((*read_info), entry->query_id) - entry->query_end - 1;
        buffer->entries[buffer->current_count].query_strand = 1;

        resize_cigar_structure(&(buffer->entries[buffer->current_count].cigar_record), (entry->cigar_record.length + 2));

        if(include_ends == 1)
        {
            append_cigar_segment(&(buffer->entries[buffer->current_count].cigar_record), buffer->entries[buffer->current_count].target_start, 0);
        }

        long long offset_diff;
        long long prev_offset_diff = 0xfffffffffffffff;
        long long i = 0;

        for (i = 0; i < (long long)entry->cigar_record.length; i++)
        {
            offset_diff = extract_gap_offset(&(entry->cigar_record), i);
            if(offset_diff != prev_offset_diff)
            {
                prev_offset_diff = offset_diff;
                append_cigar_segment(&(buffer->entries[buffer->current_count].cigar_record), 
                Get_READ_LENGTH((*read_info), entry->target_id) - extract_gap_position(&(entry->cigar_record), i) - 1, 
                prev_offset_diff);
            }
        }

        if(include_ends == 1 && extract_gap_position(&(buffer->entries[buffer->current_count].cigar_record), 
            buffer->entries[buffer->current_count].cigar_record.length - 1) != (long long)buffer->entries[buffer->current_count].target_end)
        {
            append_cigar_segment(&(buffer->entries[buffer->current_count].cigar_record), 
            buffer->entries[buffer->current_count].target_end, 
            extract_gap_offset(&(buffer->entries[buffer->current_count].cigar_record), 
            buffer->entries[buffer->current_count].cigar_record.length - 1));
        }
    }
    else
    {
        buffer->entries[buffer->current_count].target_id = entry->target_id;
        buffer->entries[buffer->current_count].target_end = entry->target_end;
        buffer->entries[buffer->current_count].target_start = entry->target_start;
        buffer->entries[buffer->current_count].target_strand = entry->target_strand;
        buffer->entries[buffer->current_count].query_id = entry->query_id;
        buffer->entries[buffer->current_count].query_end = entry->query_end;
        buffer->entries[buffer->current_count].query_start = entry->query_start;
        buffer->entries[buffer->current_count].query_strand = entry->query_strand;

        resize_cigar_structure(&(buffer->entries[buffer->current_count].cigar_record), (entry->cigar_record.length + 2));

        if(include_ends == 1)
        {
            append_cigar_segment(&(buffer->entries[buffer->current_count].cigar_record), buffer->entries[buffer->current_count].target_start, 0);
        }

        long long self_distance = entry->target_end - entry->target_start;
        long long query_distance = entry->query_end - entry->query_start;
        long long initial_offset_diff = query_distance - self_distance;

        long long prev_offset_diff = 0xfffffffffffffff;
        long long offset_diff;
        long long i = 0;

        for (i = entry->cigar_record.length - 1; i >= 0; i--)
        {
            offset_diff = extract_gap_offset(&(entry->cigar_record), i);
            if(offset_diff != prev_offset_diff)
            {
                prev_offset_diff = offset_diff;
                append_cigar_segment(&(buffer->entries[buffer->current_count].cigar_record), 
                extract_gap_position(&(entry->cigar_record), i), initial_offset_diff - prev_offset_diff);
            }
        }

        if(include_ends == 1 && extract_gap_position(&(buffer->entries[buffer->current_count].cigar_record), 
        buffer->entries[buffer->current_count].cigar_record.length - 1) != (long long)buffer->entries[buffer->current_count].target_end)
        {
            append_cigar_segment(&(buffer->entries[buffer->current_count].cigar_record), 
            buffer->entries[buffer->current_count].target_end, 
            extract_gap_offset(&(buffer->entries[buffer->current_count].cigar_record), 
            buffer->entries[buffer->current_count].cigar_record.length - 1));
        } 
    }

    buffer->entries[buffer->current_count].seed_count = entry->seed_count;
    buffer->entries[buffer->current_count].align_length = 0;
    buffer->entries[buffer->current_count].is_match = 0;
    buffer->entries[buffer->current_count].non_homopolymer_errors = 0;
    buffer->entries[buffer->current_count].strong = 0;
    buffer->current_count++;

    return 1;
}

