void debug_chain_data(k_mer_hit* hits, long long hit_count, Chain_Params* params)
{
    long long i, j, current_idx;
    long long seq_len, indel_count;
    long long pos_diff, self_pos_diff, gap_diff;

    for (i = 0; i < hit_count; ++i) 
    {
        seq_len = indel_count = 0;
        j = i;

        while (j >= 0)
        {
            current_idx = j;
            j = params->predecessor[j];

            if(j != -1)
            {
                self_pos_diff = hits[current_idx].self_offset - hits[j].self_offset;
                pos_diff = hits[current_idx].offset - hits[j].offset;
                gap_diff = pos_diff > self_pos_diff? pos_diff - self_pos_diff : self_pos_diff - pos_diff;
                indel_count += gap_diff; 
                seq_len += self_pos_diff;
            }
        }

        if(indel_count != params->indels[i])
        {
            fprintf(stderr, "indel count mismatch: %lld, expected: %ld\n", indel_count, (long)params->indels[i]);
        }

        if(seq_len != params->sequence_length[i])
        {
            fprintf(stderr, "sequence length mismatch: %lld, expected: %ld\n", seq_len, (long)params->sequence_length[i]);
        }
    }
}

long long compute_chain_length(long long x_start, long long x_finish, long long x_length, 
                               long long y_start, long long y_finish, long long y_length)
{
    if(x_start <= y_start)
    {
        y_start = y_start - x_start;
        x_start = 0;
    }
    else
    {
        x_start = x_start - y_start;
        y_start = 0;
    }

    long long x_remaining = x_length - x_finish - 1;
    long long y_remaining = y_length - y_finish - 1;

    if(x_remaining <= y_remaining)
    {
        x_finish = x_length - 1;
        y_finish = y_finish + x_remaining;        
    }
    else
    {
        x_finish = x_finish + y_remaining;
        y_finish = y_length - 1;
    }

    return x_finish - x_start + 1;
}

