int32_t check_chain(k_mer_hit *hits, int32_t n_hits, Chain_Params *params, int32_t min_score, double bandwidth_threshold)
{
    int32_t i, total_indel = 0, total_len = 0;
    double penalty_factor;

    if (n_hits == 0) return -1;

    for (i = 1; i < n_hits; ++i)
        if (hits[i-1].self_offset >= hits[i].self_offset)
            break;

    if (i < n_hits) return -1;

    penalty_factor = 1.0 / bandwidth_threshold;

    params->score[0] = hits[0].valid? min_score : min_score>>1;
    params->predecessor[0] = -1; 
    params->indels[0] = 0; 
    params->sequence_length[0] = 0; 
    params->occurrences[0] = 1;

    for (i = 1; i < n_hits; ++i) {
        int32_t score, gap;
        int32_t dx = (int32_t)hits[i].offset - (int32_t)hits[i-1].offset;
        int32_t dy = (int32_t)hits[i].self_offset - (int32_t)hits[i-1].self_offset;
        int32_t dd = dx > dy? dx - dy : dy - dx;
        double gap_ratio;

        total_indel += dd;
        total_len += dy;

        if (total_indel > total_len * bandwidth_threshold) break;

        gap = dx < dy? dx : dy;

        if (dd > MAX_GAP_SIZE && dd > gap * bandwidth_threshold) break;

        score = gap < min_score? gap : min_score;

        if (!hits[i].valid) score >>= 1;

        gap_ratio = (double)total_indel / total_len;
        score -= (int)(gap_ratio * score * penalty_factor);

        params->score[i] = params->score[i-1] + score;
        params->predecessor[i] = i - 1;
        params->indels[i] = total_indel;
        params->sequence_length[i] = total_len;
        params->occurrences[i] = i + 1;
    }

    if (i < n_hits) return -1;
    return n_hits;
}

void chain_optimization(k_mer_hit* hits, long long hit_count, Chain_Params* params, overlap_data* result, 
                        double bandwidth_threshold, int max_skip, int read_x_len, int read_y_len)
{
    long long i, j;
    long long self_pos, pos, best_j, best_i, best_score, score;
    long long pos_diff, self_pos_diff, gap_diff, min_diff;
    double bandwidth_penalty = 1 / bandwidth_threshold;
    long long minimum_score = asm_opt.k_mer_length;
    long long max_indels, max_seq_len;
    double gap_ratio;
    long long total_indels, total_seq_len;
    int32_t status;

    resize_Chain_Params(params, hit_count);

    status = check_chain(hits, hit_count, params, minimum_score, bandwidth_threshold);
    if (status > 0) {
        hit_count = status;
        goto skip_dp;
    }

    // fill the score and backtrack arrays
    for (i = 0; i < hit_count; ++i) params->temp[i] = -1;

    for (i = 0; i < hit_count; ++i) 
    {
        int n_skip = 0;
        int n_max_skip = 0;

        pos = hits[i].offset;
        self_pos = hits[i].self_offset;

        best_j = -1;
        best_score = hits[i].valid? minimum_score : minimum_score>>1;
        max_indels = 0;
        max_seq_len = 0;

        for (j = i - 1; j >= 0; --j) 
        {
            pos_diff = pos - hits[j].offset;
            self_pos_diff = self_pos - hits[j].self_offset;

            if(pos_diff == 0 || self_pos_diff <= 0)
            {
                continue;
            }

            gap_diff = pos_diff > self_pos_diff? pos_diff - self_pos_diff : self_pos_diff - pos_diff;

            total_indels = params->indels[j] + gap_diff;
            total_seq_len = params->sequence_length[j] + self_pos_diff;

            if(total_indels > bandwidth_threshold * total_seq_len)
            {
                continue;
            }

            min_diff = pos_diff < self_pos_diff? pos_diff:self_pos_diff;
            score = min_diff < minimum_score? min_diff : minimum_score;

            if (!hits[j].valid) score >>= 1;

            gap_ratio = (double)((double)(total_indels)/(double)(total_seq_len));
            score -= (long long)(gap_ratio * score * bandwidth_penalty);
            score += params->score[j];

            if (score > best_score) {
                best_score = score;
                best_j = j;
                max_indels = total_indels;
                max_seq_len = total_seq_len;
                n_max_skip = 0;

                if (n_skip > 0) --n_skip;
            } else {
                if (++n_max_skip > max_skip)
                    break;

                if (params->temp[j] == i) {
                    if (++n_skip > max_skip)
                        break;
                }
            }

            if (params->predecessor[j] >= 0) params->temp[params->predecessor[j]] = i;
        }

        params->score[i] = best_score;
        params->predecessor[i] = best_j;
        params->indels[i] = max_indels;
        params->sequence_length[i] = max_seq_len;
        params->occurrences[i] = 1;

        if(best_j != -1) params->occurrences[i] = params->occurrences[best_j] + 1;
    }

skip_dp:
    best_score = -1;
    best_i = -1;
    long long min_xLen = read_x_len * 2 + 2, tmp_xLen;

    for (i = 0; i < hit_count; ++i) 
    {
        if(params->score[i] > best_score)
        {
            best_score = params->score[i];
            best_i = i;
            min_xLen = compute_chain_length(hits[i].self_offset, hits[i].self_offset, read_x_len, 
                                     hits[i].offset, hits[i].offset, read_y_len);
        }
        else if(params->score[i] == best_score)
        {
            tmp_xLen = compute_chain_length(hits[i].self_offset, hits[i].self_offset, read_x_len, 
                                    hits[i].offset, hits[i].offset, read_y_len);

            if(tmp_xLen < min_xLen)
            {
                best_score = params->score[i];
                best_i = i;
                min_xLen = tmp_xLen;
            }
        }
    }

    reset_cigar_structure(&(result->cigar_record));

    i = best_i;
    result->target_end = hits[i].self_offset;
    result->query_end = hits[i].offset;
    result->seed_count = best_score;
    result->overlap_size = min_xLen;

    self_pos_diff = result->target_end - hits[i].self_offset;
    pos_diff = result->query_end - hits[i].offset;
    long long prev_gap_diff = pos_diff - self_pos_diff;

    append_cigar_segment(&(result->cigar_record), hits[i].self_offset, prev_gap_diff);

    long long chain_length = 0;

    if(result->target_strand == 1)
    {
        while (i >= 0)
        {
            self_pos_diff = result->target_end - hits[i].self_offset;
            pos_diff = result->query_end - hits[i].offset;
            gap_diff = pos_diff - self_pos_diff;

            if(gap_diff != prev_gap_diff)
            {
                prev_gap_diff = gap_diff;
                append_cigar_segment(&(result->cigar_record), hits[i].self_offset, prev_gap_diff);
            }

            chain_length++;
            result->target_start = hits[i].self_offset;
            result->query_start = hits[i].offset;
            i = params->predecessor[i];
        }
    }
    else
    {
        while (i >= 0)
        {
            self_pos_diff = result->target_end - hits[i].self_offset;
            pos_diff = result->query_end - hits[i].offset;
            gap_diff = pos_diff - self_pos_diff;

            if(gap_diff == prev_gap_diff)
            {
                result->cigar_record.length--;
                append_cigar_segment(&(result->cigar_record), hits[i].self_offset, prev_gap_diff);
            }
            else
            {
                prev_gap_diff = gap_diff;
                append_cigar_segment(&(result->cigar_record), hits[i].self_offset, prev_gap_diff);
            }

            chain_length++;
            result->target_start = hits[i].self_offset;
            result->query_start = hits[i].offset;
            i = params->predecessor[i];
        }
    }
}

void process_overlaps_by_chaining_back(Candidates_list* candidates, overlap_data_buffer* overlap_buffer, 
                                      uint64_t readID, uint64_t readLength, Read_Info* read_info, 
                                      double bandwidth_threshold, int include_ends)
{
    overlap_data temp_region;
    long long i = 0;
    uint64_t current_ID;
    uint64_t current_strand;

    if (candidates->length == 0)
    {
        return;
    }

    long long sub_region_start;
    long long sub_region_end;

    initialize_cigar_structure(&(temp_region.cigar_record));
    i = 0;

    while (i < candidates->length)
    {
        current_ID = candidates->list[i].readID;
        current_strand = candidates->list[i].strand;

        temp_region.target_id = readID;
        temp_region.target_strand = current_strand;
        temp_region.query_id = current_ID;
        temp_region.query_strand = 0;  

        sub_region_start = i;
        sub_region_end = i;
        i++;

        while (i < candidates->length 
        && 
        current_ID == candidates->list[i].readID
        &&
        current_strand == candidates->list[i].strand)
        {
            sub_region_end = i;
            i++;
        }

        if (temp_region.target_id == temp_region.query_id)
        {
            continue;
        }

        chain_DP(candidates->list + sub_region_start,
                sub_region_end - sub_region_start + 1, &(candidates->chain_params), &temp_region, bandwidth_threshold,
                25, Get_READ_LENGTH((*read_info), temp_region.target_id), Get_READ_LENGTH((*read_info), temp_region.query_id));

        if (temp_region.target_id != temp_region.query_id)
        {
            add_to_overlap_buffer(overlap_buffer, &temp_region, read_info, include_ends);
        }
    }

    destroy_cigar_structure(&(temp_region.cigar_record));
}

void process_overlaps_by_chaining(Candidates_list* candidates, overlap_data_buffer* overlap_buffer, kvec_t_u64_warp* chain_idx,
                                  uint64_t readID, uint64_t readLength, Read_Info* read_info, 
                                  double bandwidth_threshold, int include_ends, overlap_data* cigar_result)
{
    long long i = 0;
    uint64_t current_ID;
    uint64_t current_strand;

    if (candidates->length == 0)
    {
        return;
    }

    long long sub_region_start;
    long long sub_region_end;

    reset_cigar_structure(&((*cigar_result).cigar_record));
    i = 0;

    while (i < candidates->length)
    {
        chain_idx->a.n = 0;
        current_ID = candidates->list[i].readID;
        current_strand = candidates->list[i].strand;

        (*cigar_result).target_id = readID;
        (*cigar_result).target_strand = current_strand;
        (*cigar_result).query_id = current_ID;
        (*cigar_result).query_strand = 0;  

        sub_region_start = i;
        sub_region_end = i;
        i++;

        while (i < candidates->length 
        && 
        current_ID == candidates->list[i].readID
        &&
        current_strand == candidates->list[i].strand)
        {
            sub_region_end = i;
            i++;
        }

        if ((*cigar_result).target_id == (*cigar_result).query_id)
        {
            continue;
        }

        chain_DP(candidates->list + sub_region_start,
                sub_region_end - sub_region_start + 1, &(candidates->chain_params), cigar_result, bandwidth_threshold,
                25, Get_READ_LENGTH((*read_info), (*cigar_result).target_id), Get_READ_LENGTH((*read_info), (*cigar_result).query_id));

        if ((*cigar_result).target_id != (*cigar_result).query_id)
        {
            add_to_overlap_buffer(overlap_buffer, cigar_result, read_info, include_ends);
        }
    }
}

void append_window_entry(overlap_data* region, uint64_t x_start, uint64_t x_end, int y_start, int y_end, int error,
                        int extra_begin, int extra_end, int error_limit)
{
    long long length = region->target_end - region->target_start + 1;
    uint64_t num_windows = length / WINDOW_SIZE + 4;

    if (num_windows > region->window_list_capacity)
    {
        region->window_list_capacity = num_windows;
        region->window_list = (window_data*)realloc(region->window_list, region->window_list_capacity*sizeof(window_data));
    }

    region->window_list[region->window_list_length].x_start = x_start;
    region->window_list[region->window_list_length].x_end = x_end;
    region->window_list[region->window_list_length].y_start = y_start;
    region->window_list[region->window_list_length].y_end = y_end;
    region->window_list[region->window_list_length].error = error;
    region->window_list[region->window_list_length].cigar.length = -1;
    region->window_list[region->window_list_length].extra_begin = extra_begin;
    region->window_list[region->window_list_length].extra_end = extra_end;
    region->window_list[region->window_list_length].error_threshold = error_limit;
    region->window_list_length++;
}

void validate_single_list(Candidates_list* candidates, k_mer_pos* list, uint64_t list_length, uint64_t end_pos, uint64_t strand)
{
    uint64_t i;
    long long j = 0;

    for (i = 0; i < list_length; i++)
    {
        for (; j < candidates->length; j++)
        {
            if (
                list[i].offset == (uint64_t)candidates->list[j].offset
                &&
                list[i].readID == candidates->list[j].readID
                &&
                end_pos == (uint64_t)candidates->list[j].self_offset
                &&
                strand == candidates->list[j].strand
            )
            {
                break;
            }   
        }

        if (j == candidates->length)
        {
            fprintf(stderr, "VALIDATION ERROR\n");
        }
    }
}

void init_Chain_Params(Chain_Params* x)
{
    memset(x, 0, sizeof(Chain_Params));
}

void clear_Chain_Params(Chain_Params* x)
{
    x->length = 0;
}

void destroy_Chain_Params(Chain_Params* x)
{
    free(x->score);
    free(x->predecessor);
    free(x->indels);
    free(x->sequence_length);
    free(x->occurrences);
    free(x->temp);
}

void resize_Chain_Params(Chain_Params* x, long long size)
{
    if (size + 1 > x->capacity) {
        x->capacity = size + 1;
        kroundup64(x->capacity);
        REALLOC(x->score, x->capacity);
        REALLOC(x->predecessor, x->capacity);
        REALLOC(x->indels, x->capacity);
        REALLOC(x->sequence_length, x->capacity);
        REALLOC(x->occurrences, x->capacity);
        REALLOC(x->temp, x->capacity);
    }
}

void init_Candidates_list(Candidates_list* l)
{
    l->length = 0;
    l->capacity = 0;
    l->list = NULL;
    init_Chain_Params(&(l->chain_params));
}

void clear_Candidates_list(Candidates_list* l)
{
    l->length = 0;
    clear_Chain_Params(&(l->chain_params));
}

void destroy_Candidates_list(Candidates_list* l)
{
    free(l->list);
    destroy_Chain_Params(&(l->chain_params));
}

void initialize_cigar_structure(Cigar_Data* x)
{
    x->storage = NULL;
    x->length = 0;
    x->capacity = 0;
}

void destroy_cigar_structure(Cigar_Data* x)
{
    if(x->capacity > 0)
    {
        free(x->storage);
    }
}

void reset_cigar_structure(Cigar_Data* x)
{
    x->length = 0;
}

void append_cigar_segment(Cigar_Data* x, uint32_t gap_position, int32_t gap_shift)
{
    if(x->length + 1 > x->capacity)
    {
        x->capacity = (x->length + 1) * 2;
        x->storage = (uint64_t*)realloc(x->storage, sizeof(uint64_t) * x->capacity);
    }

    x->storage[x->length] = gap_position;
    x->storage[x->length] = x->storage[x->length] << 32;

    if(gap_shift < 0)
    {
        gap_shift = gap_shift * -1;
        gap_position = gap_shift;
        gap_position = gap_position << 1;
        gap_position = gap_position | ((uint32_t)1);
    }
    else
    {
        gap_position = gap_shift;
        gap_position = gap_position << 1;
    }

    x->storage[x->length] = x->storage[x->length] | ((uint32_t)gap_position);
    x->length++;
}

void resize_cigar_structure(Cigar_Data* x, uint64_t size)
{
    if (size > x->capacity) {
        x->capacity = size;
        REALLOC(x->storage, x->capacity);
    }

    x->length = 0;
}

void initialize_boundary_segments_alloc(window_data_alloc* x)
{
    x->buffer = NULL;
    x->length = 0;
    x->capacity = 0;
}

void reset_boundary_segments_alloc(window_data_alloc* x)
{
    x->length = 0;
}

void destroy_boundary_segments_alloc(window_data_alloc* x)
{
    if(x->capacity != 0)
    {
        free((x->buffer));
    }
}

void resize_boundary_segments_alloc(window_data_alloc* x, long long size)
{
    if(size > x->capacity)
    {
        x->capacity = size;
        x->buffer = (window_data*)realloc(x->buffer, sizeof(window_data) * x->capacity);
    }

    long long i;
    for (i = 0; i < x->capacity; i++)
    {
        x->buffer[i].error = -1; 
    }

    x->length = 0;
}

#include <torch/extension.h>

// C++ interface for deep ray tracing operations
#define VERIFY_CUDA(t) AT_ASSERTM(t.type().is_cuda(), #t " should be on GPU")
#define VERIFY_CONTIGUOUS(t) AT_ASSERTM(t.is_contiguous(), #t " must be contiguous")
#define VERIFY_TENSOR(t) VERIFY_CUDA(t); VERIFY_CONTIGUOUS(t)
#define VERIFY_SHAPE3D(t, b, h, w, c) AT_ASSERTM((t.size(0) == b) && (t.size(1) == h) && (t.size(2) == w) && (t.size(3) == c), #t " has incorrect spatial dimensions")
#define VERIFY_SHAPE2D(t, b, n, d) AT_ASSERTM((t.size(0) == b) && (t.size(1) == n) && (t.size(2) == d), #t " has incorrect point dimensions")

////////////////////////////////////////////////////////////
// CUDA kernel forward declarations
void dr_kernel_forward_batch(at::Tensor coords2d_bxfx6,
        at::Tensor directions_bxfx1, at::Tensor bbox_bxfx4,
        at::Tensor lengths_bxfx3, at::Tensor gt_labels_fx2, at::Tensor mus_n, 
        at::Tensor weights_3vf, at::Tensor indices_vf,
        at::Tensor visibility_cnt_bxhxwx1, at::Tensor start_idx_bxhxwx1,
        at::Tensor image_bxhxwx1,
        int use_visibility_count, float max_sino_value);

void dr_forward_batch(at::Tensor coords2d_bxfx6,
        at::Tensor directions_bxfx1, at::Tensor bbox_bxfx4,
        at::Tensor lengths_bxfx3, at::Tensor gt_labels_fx2, at::Tensor mus_n, 
        at::Tensor weights_3vf, at::Tensor indices_vf,
        at::Tensor visibility_cnt_bxhxwx1, at::Tensor start_idx_bxhxwx1,
        at::Tensor image_bxhxwx1, int use_visibility_count, float max_sino_value) {
    VERIFY_TENSOR(coords2d_bxfx6);
    VERIFY_TENSOR(directions_bxfx1);
    VERIFY_TENSOR(bbox_bxfx4);
    VERIFY_TENSOR(lengths_bxfx3);
    VERIFY_TENSOR(gt_labels_fx2);
    VERIFY_TENSOR(mus_n);
    // VERIFY_TENSOR(indices_vf);
    VERIFY_TENSOR(visibility_cnt_bxhxwx1);
    // VERIFY_TENSOR(weights_3vf);
    VERIFY_TENSOR(start_idx_bxhxwx1);
    VERIFY_TENSOR(image_bxhxwx1);

    int batch_size = coords2d_bxfx6.size(0);
    int num_points = coords2d_bxfx6.size(1);
    int img_height = image_bxhxwx1.size(1);
    int img_width = image_bxhxwx1.size(2);
    int depth_channels = image_bxhxwx1.size(3);

    VERIFY_SHAPE2D(coords2d_bxfx6, batch_size, num_points, 6);
    VERIFY_SHAPE2D(directions_bxfx1, batch_size, num_points, 1);
    VERIFY_SHAPE2D(bbox_bxfx4, batch_size, num_points, 4);
    VERIFY_SHAPE2D(lengths_bxfx3, batch_size, num_points, 3);
    VERIFY_SHAPE3D(visibility_cnt_bxhxwx1, batch_size, img_height, img_width, 1);
    VERIFY_SHAPE3D(image_bxhxwx1, batch_size, img_height, img_width, depth_channels);

    dr_kernel_forward_batch(coords2d_bxfx6, directions_bxfx1,
            bbox_bxfx4, lengths_bxfx3, 
            gt_labels_fx2, mus_n,
            weights_3vf, indices_vf,
            visibility_cnt_bxhxwx1, start_idx_bxhxwx1,
            image_bxhxwx1, use_visibility_count, max_sino_value);
    return;
}

//////////////////////////////////////////////////////////
void dr_kernel_backward_batch(at::Tensor grad_output_bxhxwxd,
        at::Tensor output_image_bxhxwxd, at::Tensor indices_vf,
        at::Tensor visibility_cnt_bxhxwx1, at::Tensor start_idx_bxhxwx1,
        at::Tensor weights_3vf, at::Tensor coords2d_bxfx6, at::Tensor lengths_bxfx3,
        at::Tensor gt_labels_fx2, at::Tensor mus_n, at::Tensor facing_flags_bxfx1,
        at::Tensor grad_coords2d_bxfx6, at::Tensor grad_lengths_bxfx3, at::Tensor grad_mus_n);

void dr_backward_batch(at::Tensor grad_output_bxhxwxd, at::Tensor output_image_bxhxwxd,
        at::Tensor indices_vf, at::Tensor visibility_cnt_bxhxwx1,
        at::Tensor start_idx_bxhxwx1,
        at::Tensor weights_3vf, at::Tensor coords2d_bxfx6, at::Tensor lengths_bxfx3,
        at::Tensor gt_labels_fx2, at::Tensor mus_n, at::Tensor facing_flags_bxfx1,
        at::Tensor grad_coords2d_bxfx6, at::Tensor grad_lengths_bxfx3, at::Tensor grad_mus_n) {
    VERIFY_TENSOR(grad_output_bxhxwxd);
    VERIFY_TENSOR(output_image_bxhxwxd);
    VERIFY_TENSOR(indices_vf);
    VERIFY_TENSOR(visibility_cnt_bxhxwx1);
    VERIFY_TENSOR(start_idx_bxhxwx1);
    VERIFY_TENSOR(weights_3vf);
    VERIFY_TENSOR(coords2d_bxfx6);
    VERIFY_TENSOR(lengths_bxfx3);
    VERIFY_TENSOR(gt_labels_fx2);
    VERIFY_TENSOR(mus_n);

    VERIFY_TENSOR(facing_flags_bxfx1);
    VERIFY_TENSOR(grad_coords2d_bxfx6);
    VERIFY_TENSOR(grad_lengths_bxfx3);
    VERIFY_TENSOR(grad_mus_n);

    int batch_size = grad_output_bxhxwxd.size(0);
    int img_height = grad_output_bxhxwxd.size(1);
    int img_width = grad_output_bxhxwxd.size(2);
    int depth_channels = grad_output_bxhxwxd.size(3);
    int num_points = coords2d_bxfx6.size(1);

    VERIFY_SHAPE3D(grad_output_bxhxwxd, batch_size, img_height, img_width, depth_channels);
    VERIFY_SHAPE3D(output_image_bxhxwxd, batch_size, img_height, img_width, depth_channels);
    VERIFY_SHAPE3D(visibility_cnt_bxhxwx1, batch_size, img_height, img_width, 1);
    VERIFY_SHAPE2D(coords2d_bxfx6, batch_size, num_points, 6);
    VERIFY_SHAPE2D(lengths_bxfx3, batch_size, num_points, 3);
    VERIFY_SHAPE2D(facing_flags_bxfx1, batch_size, num_points, 1);
    VERIFY_SHAPE2D(grad_coords2d_bxfx6, batch_size, num_points, 6);
    VERIFY_SHAPE2D(grad_lengths_bxfx3, batch_size, num_points, 3);

    dr_kernel_backward_batch(grad_output_bxhxwxd,
            output_image_bxhxwxd, indices_vf, visibility_cnt_bxhxwx1, start_idx_bxhxwx1,
            weights_3vf, coords2d_bxfx6, lengths_bxfx3,
            gt_labels_fx2, mus_n, facing_flags_bxfx1,
            grad_coords2d_bxfx6, grad_lengths_bxfx3,
            grad_mus_n);
    return;
}

