namespace scriptengine::jvm {
    using namespace tier0;
    using namespace tier1;
}

namespace scriptengine::jvm {
    void execute_script(mut_ref<VM> vm, MethodHandle methodHandle, Frame frame) {
        var &evaluator = vm.evaluator;
        let codeHandle = methodHandle.handle_;
        let constantPool = codeHandle.handle_->constantPool_;
        let currentMethod = codeHandle.handle_->methods_.get(methodHandle.index_);
        let className = constantPool.getClassName(codeHandle.handle_->thisClass_);
        let methodName = constantPool.getName(currentMethod.nameIndex_);
        var methodRef = Tuple(className, methodName);
        (void) methodRef;

        let bytecodeOpt = fetch_bytecode(vm, methodHandle);
        if (!bytecodeOpt.hasValue()) {
            // native method
            return;
        }

        let bytecode = bytecodeOpt.value();
        var &operandStack = frame.stack;
        var &localVariables = frame.locals;

        operandStack.stack_.ensure(Int(bytecode.maxStack_));
        let localCount = Int(bytecode.maxLocals_);
        localVariables.ensure(localCount);
        localVariables._size(localCount);

        var running = Boolean(true);
        var error_handler = [&]() {
            terminate_execution();
        };

        var programCounter = Int(0);
        var branch = [&](Int offset) { programCounter = programCounter + offset - 1; };

        for (; running; programCounter = programCounter + 1) {
            let opcode = bytecode.code_.get(programCounter).variant_;
            switch (opcode.index()) {
                case Instruction::Invalid: {
                    error_handler();
                }
                case Instruction::athrow: {
                    error_handler();
                    break;
                }
                case Instruction::monitorenter: {
                    var monitorObj = operandStack.pop().get<Stack::ValueKind::Reference>();
                    (void) monitorObj;
                    break;
                }
                case Instruction::monitorexit: {
                    var monitorObj = operandStack.pop().get<Stack::ValueKind::Reference>();
                    (void) monitorObj;
                    break;
                }
                case Instruction::nop: {
                    break;
                }
                case Instruction::_return: {
                    running = false;
                    break;
                }
                case Instruction::wide: {
                    error_handler();
                    break;
                }
                    // CLASS operations
                case Instruction::anewarray: {
                    let instr = opcode.get<Instruction::anewarray>();
                    var size = operandStack.pop().get<Stack::ValueKind::Int>();
                    let typeName = constantPool.getClassName(instr.index);
                    operandStack.push(evaluator._newarray(vm, typeName, size));
                    break;
                }
                case Instruction::arraylength: {
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(evaluator.arraysize(vm, arrayRef));
                    break;
                }
                case Instruction::checkcast: {
                    var objRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Reference>(objRef));
                    break;
                }
                case Instruction::getfield: {
                    let instr = opcode.get<Instruction::getfield>();
                    let fieldRef = constantPool.getAny(instr.index).variant_.get<Constant::Fieldref>();
                    let ownerClass = constantPool.getClassName(fieldRef.classIndex);
                    let nameAndType = constantPool.getAny(fieldRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let fieldName = constantPool.getName(nameAndType.nameIndex);
                    let fieldType = constantPool.getName(nameAndType.descriptorIndex);
                    (void) ownerClass;
                    (void) fieldType;
                    var receiver = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(evaluator.getinstance(vm, receiver, fieldName));
                    break;
                }
                case Instruction::getstatic: {
                    let instr = opcode.get<Instruction::getstatic>();
                    let fieldRef = constantPool.getAny(instr.index).variant_.get<Constant::Fieldref>();
                    let ownerClass = constantPool.getClassName(fieldRef.classIndex);
                    let nameAndType = constantPool.getAny(fieldRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let fieldName = constantPool.getName(nameAndType.nameIndex);
                    let fieldType = constantPool.getName(nameAndType.descriptorIndex);
