int main() {
  printf("Parsing color from '#ABC'\n");
  auto color = Color::fromHexString("#ABC");
  printf("  RGB: %d, %d, %d\n", color.red(), color.green(), color.blue());
  printf("  HSV: %f, %f, %f\n", color.h, color.s, color.v);
  printf("  HEX: %s\n", color.hex().c_str());

  printf("\nParsing color from 'skyblue'\n");
  color = Color::fromWebName("skyblue");
  printf("  RGB: %d, %d, %d\n", color.red(), color.green(), color.blue());
  printf("  HSV: %f, %f, %f\n", color.h, color.s, color.v);
  printf("  HEX: %s\n", color.hex().c_str());

  printf("\nBlending #ffffff with #000 (factor = 0.5)\n");
  auto light = Color::fromHexString("#ffffff");
  auto dark = Color::fromHexString("#000");
  light.blend(dark);
  printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
  printf("  HSV: %f, %f, %f\n", light.h, light.s, light.v);
  printf("  HEX: %s\n", light.hex().c_str());

  printf("\nBlending #ffffff with #000 (factor = 1)\n");
  light = Color::fromHexString("#ffffff");
  light.blend(dark, 1);
  printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
  printf("  HSV: %f, %f, %f\n", light.h, light.s, light.v);
  printf("  HEX: %s\n", light.hex().c_str());

  printf("\nRotating hue from red back to red\n");
  light = Color::fromHexString("#ff0000");
  printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
  printf("  HSV: %f, %f, %f\n", light.h, light.s, light.v);
  printf("  HEX: %s\n", light.hex().c_str());

  for (int step = 0; step < 5; ++step) {
    light.hue(light.hue() + 360.f / 5);
    printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
    printf("  HSV: %f, %f, %f\n", light.h, light.s, light.v);
    printf("  HEX: %s\n", light.hex().c_str());
  }
}

