#include "stdlib.hpp"
#include "stdlib.hpp"
#include "expressions/stdlib.hpp"
#include "types.hpp"
#include <cstdlib>
#include <cmath>

// Generate a random number from a uniform distribution over [a, b]
auto std_uniform_random = [](Env env) {
    Val lower_bound = env->apply("min");
    if (!val_is_number(lower_bound)) {
        throw_err("type", "random.uniform : R -> R -> R cannot accept argument " + lower_bound->toString());
        return (Val) nullptr;
    }
    Val upper_bound = env->apply("max");
    if (!val_is_number(upper_bound)) {
        throw_err("type", "random.uniform : R -> R -> R cannot accept argument " + upper_bound->toString());
        return (Val) nullptr;
    }

    float u = static_cast<float>(rand()) / RAND_MAX;
    float range = (isVal<IntVal>(upper_bound)
        ? static_cast<float>(((IntVal*) upper_bound)->get())
        : static_cast<float>(((RealVal*) upper_bound)->get()))
        - (isVal<IntVal>(lower_bound)
            ? static_cast<float>(((IntVal*) lower_bound)->get())
            : static_cast<float>(((RealVal*) lower_bound)->get()));

    u *= range;
    u += (isVal<IntVal>(lower_bound)
        ? static_cast<float>(((IntVal*) lower_bound)->get())
        : static_cast<float>(((RealVal*) lower_bound)->get()));

    return static_cast<Val>(new RealVal(u));
};

// Generate a random number from a normal distribution with mean 'a' and std dev 'b'
auto std_normal_random = [](Env env) {
    Val mean_val = env->apply("mean");
    if (!val_is_number(mean_val)) {
        throw_err("type", "random.normal : R -> R -> R cannot accept argument " + mean_val->toString());
        return (Val) nullptr;
    }
    Val stddev_val = env->apply("stddev");
    if (!val_is_number(stddev_val)) {
        throw_err("type", "random.normal : R -> R -> R cannot accept argument " + stddev_val->toString());
        return (Val) nullptr;
    }

    // Generate two independent uniform random numbers in (0,1)
    float u1 = static_cast<float>(rand()) / RAND_MAX;
    float u2 = static_cast<float>(rand()) / RAND_MAX;

    // Box-Muller transform to get standard normal variable
    float z = sqrt(-2.0f * log(u1)) * cos(2.0f * M_PI * u2);

    // Scale and shift to desired mean and standard deviation
    float stddev = sqrt(isVal<IntVal>(stddev_val)
        ? static_cast<float>(((IntVal*) stddev_val)->get())
        : static_cast<float>(((RealVal*) stddev_val)->get()));

    z *= stddev;
    z += (isVal<IntVal>(mean_val)
        ? static_cast<float>(((IntVal*) mean_val)->get())
        : static_cast<float>(((RealVal*) mean_val)->get()));

    return static_cast<Val>(new RealVal(z));
};

Type* type_stdlib_random() {
    return new DictType {
        { 
            // uniform : R -> R -> R
            "uniform",
            new LambdaType("min",
                new RealType,
                new LambdaType("max",
                    new RealType,
                    new RealType))
        }, { 
            // normal : R -> R -> R
            "normal",
            new LambdaType("mean",
                new RealType,
                new LambdaType("stddev",
                    new RealType,
                    new RealType))
        }
    };
}

Val load_stdlib_random() {
    return new DictVal {
        {
            "uniform",
            new LambdaVal(new std::string[3]{"min", "max", ""},
                new ImplementExp(std_uniform_random, nullptr))
        }, {
            "normal",
            new LambdaVal(new std::string[3]{"mean", "stddev", ""},
                new ImplementExp(std_normal_random, nullptr))
        }
    };
}

#include "memory.h"

// Copies count bytes from source to destination buffer
void* memcpy(void* destination, const void* source, size_t byteCount)
{
    const unsigned char* srcPtr = (const unsigned char*)source;
    unsigned char* dstPtr = (unsigned char*)destination;

    while (byteCount > 0) {
        *dstPtr++ = *srcPtr++;
        byteCount--;
    }

    return destination;
}

// Compares first n bytes of two memory regions
int memcmp(const void* region1, const void* region2, size_t length)
{
    unsigned char byte1, byte2;
    unsigned char* ptr1 = (unsigned char*)region1;
    unsigned char* ptr2 = (unsigned char*)region2;

    for (; length > 0; length--, ptr1++, ptr2++) {
        byte1 = *ptr1;
        byte2 = *ptr2;
        if (byte1 != byte2) {
            return (int)(byte1 - byte2);
        }
    }
    return 0;
}

// Fills count bytes of destination with value val
void* memset(void* destination, int value, size_t count)
{
    unsigned char* buffer = (unsigned char*)destination;
    unsigned char fillValue = (unsigned char)value;

    for (size_t i = 0; i < count; i++) {
        buffer[i] = fillValue;
    }

    return destination;
}

/*
The memmove() function copies n bytes from the source memory area 
to the destination memory area. These areas may overlap.
Returns pointer to the destination memory area.
*/
void* memmove(void* destArea, void* srcArea, size_t numBytes)
{
    size_t index;
    char* destChar = (char*)destArea;
    char* srcChar = (char*)srcArea;

    if (destChar == srcChar) {
        // No operation needed when areas are identical
    }
    else if (destChar < srcChar) {
        // Copy forward when destination starts before source
        for (index = 0; index < numBytes; index++) {
            destChar[index] = srcChar[index];
        }
    }
    else {
        // Copy backward when destination starts after source
        for (index = numBytes; index > 0; index--) {
            destChar[index - 1] = srcChar[index - 1];
        }
    }

    return destArea;
}

// Searches for first occurrence of character c in first n bytes of s
void* memchr(const void* buffer, int searchChar, size_t searchLength)
{
    if (searchLength > 0) {
        const unsigned char* pos = (const unsigned char*)buffer;
        unsigned char target = (unsigned char)searchChar;

        do {
            if (*pos == target) {
                return (void*)pos;
            }
            pos++;
        } while (--searchLength != 0);
    }

    return nullptr;
}

