TEST(NonceGeneration, generateUniqueNonces) {
  std::set<std::string> nonceSet;
  const int nonceCount = 100;
  for (int i=0; i < nonceCount; ++i) {
    nonceSet.insert(Nonce::nonce());
  }
  // Verify no duplicate nonces were generated
  ASSERT_EQ(nonceSet.size(), nonceCount);
  for (std::set<std::string>::iterator iter = nonceSet.begin();
                                       iter != nonceSet.end();
                                       ++iter) {
    ASSERT_TRUE(iter->length() > 0);
    ASSERT_TRUE(iter->length() <= 128);
  }
}

TEST(NonceGeneration, updateInputWithNonce) {
  JSON inputParams(JSON_OBJECT);
  inputParams["param1"] = "value1";
  inputParams["param2"] = "value2";
  JSON updatedInput = Nonce::updateNonce(inputParams);
  ASSERT_EQ(inputParams["param1"], updatedInput["param1"]);
  ASSERT_EQ(inputParams["param2"], updatedInput["param2"]);
  ASSERT_TRUE(updatedInput.has("nonce"));
  std::string nonceValue = updatedInput["nonce"].get<string>();
  ASSERT_TRUE(nonceValue.length() > 0);
  ASSERT_TRUE(nonceValue.length() <= 128);

  std::string newNonce = Nonce::nonce();
