  ASSERT_EQ(inputParams["param1"], updatedInput["param1"]);
  ASSERT_EQ(inputParams["param2"], updatedInput["param2"]);
  ASSERT_TRUE(updatedInput.has("nonce"));
  nonceValue = updatedInput["nonce"].get<string>();
  ASSERT_EQ(newNonce, nonceValue);
  ASSERT_TRUE(nonceValue.length() > 0);
  ASSERT_TRUE(nonceValue.length() <= 128);
}

/////////////////
// Idempotency //
/////////////////
// Verify that repeated API calls with same parameters produce identical responses
void verifyIdenticalResponses(JSON (*apiFunction)(const dx::JSON &, const bool), 
                              const JSON &params, const bool retryAllowed=false) {
  JSON response1 =  (*apiFunction)(params, retryAllowed);
  JSON response2 =  (*apiFunction)(params, retryAllowed);
  ASSERT_EQ(response1, response2);
}

void verifyIdenticalResponses(JSON (*apiFunction)(const string &, const dx::JSON &, const bool),
                              const string& objId, const JSON &params, const bool retryAllowed=false) {
  JSON response1 =  (*apiFunction)(objId, params, retryAllowed);
  JSON response2 =  (*apiFunction)(objId, params, retryAllowed);
  ASSERT_EQ(response1, response2);
}

static const std::string nonceConflictMessage =
  "InvalidInput: 'Nonce was reused for an earlier API request that had a different input', Server returned HTTP code '422'";

// Verify that reusing a nonce with different parameters fails appropriately
void expectNonceConflict(JSON (*apiFunction)(const dx::JSON &, const bool), 
                        const JSON &params, const bool retryAllowed=false){
  try {
    (*apiFunction)(params, retryAllowed);
    ASSERT_THROW((*apiFunction)(params, retryAllowed), DXAPIError);
  } catch(DXAPIError &err) {
    ASSERT_EQ(err.resp_code, 422);
    ASSERT_EQ(std::string(err.what()), nonceConflictMessage);
  }
}

void expectNonceConflict(JSON (*apiFunction)(const string &, const dx::JSON &, const bool),
                        const string& objId, const JSON &params, const bool retryAllowed=false) {
  try {
    (*apiFunction)(objId, params, retryAllowed);
    ASSERT_THROW((*apiFunction)(objId, params, retryAllowed), DXAPIError);
  } catch(DXAPIError &err) {
    ASSERT_EQ(err.resp_code, 422);
    ASSERT_EQ(std::string(err.what()), nonceConflictMessage);
  }
}

