// Constructor initializes context and color, then records command buffers
color_renderer::color_renderer(uint32_t width, uint32_t height, std::array<float, 4> new_color)
    : context_{width, height}
    , target_color_{new_color}
{
    generate_command_buffers();
}

// Initiates drawing by beginning and ending the draw process
void color_renderer::render()
{
    context_.start_rendering();
    context_.finish_rendering();
}

// Updates the target color and re-records command buffers accordingly
void color_renderer::set_color(std::array<float, 4> new_color)
{
    target_color_ = new_color;
    generate_command_buffers();
}

// Records or re-records the command buffers for each swapchain image
void color_renderer::generate_command_buffers()
{
    auto& swapchain_buffer     = context_.swapchain();
    auto& gpu_device           = context_.physical_device();
    auto& cmd_buffers            = context_.command_buffers();
    vk::ImageSubresourceRange region_of_interest =
        {vk::ImageAspectFlagBits::eColor, 0, 1, 0, 1};

    for (uint32_t index = 0; index < swapchain_buffer.images.size(); ++index) {
        vk::ImageMemoryBarrier transition_to_clear = {
            vk::AccessFlagBits::eMemoryRead,
            vk::AccessFlagBits::eTransferWrite,
            vk::ImageLayout::eUndefined,
            vk::ImageLayout::eTransferDstOptimal,
            gpu_device.queue_family_idx,
            gpu_device.queue_family_idx,
            swapchain_buffer.images[index],
            region_of_interest};

        vk::ImageMemoryBarrier transition_to_present = {
            vk::AccessFlagBits::eTransferWrite,
            vk::AccessFlagBits::eMemoryRead,
            vk::ImageLayout::eTransferDstOptimal,
            vk::ImageLayout::ePresentSrcKHR,
            gpu_device.queue_family_idx,
            gpu_device.queue_family_idx,
            swapchain_buffer.images[index],
            region_of_interest};

        cmd_buffers[index]->begin(vk::CommandBufferBeginInfo{});

        cmd_buffers[index]->pipelineBarrier(
            vk::PipelineStageFlagBits::eTransfer,
            vk::PipelineStageFlagBits::eTransfer,
            {},
            {},
            {},
            transition_to_clear);

        cmd_buffers[index]->clearColorImage(
            swapchain_buffer.images[index],
            vk::ImageLayout::eTransferDstOptimal,
            target_color_,
            region_of_interest);

        cmd_buffers[index]->pipelineBarrier(
            vk::PipelineStageFlagBits::eTransfer,
            vk::PipelineStageFlagBits::eBottomOfPipe,
            {},
            {},
            {},
            transition_to_present);

        cmd_buffers[index]->end();
    }
}

