struct WebStream::impl : public StreamSockSetter {
    impl(const char * port_str, HWND window_handle) : m_server(port_str), m_init_block(true), m_window(window_handle) {
        // start server thread
        m_worker_thread = std::thread(&WebStream::impl::ListenForConnections, this);
        // wait for video request or socket failure
        std::mutex mtx;
        std::unique_lock<std::mutex> lock(mtx);
        while (m_init_block)
            m_condition.wait(lock);
        // start streaming video
    }

    void ListenForConnections() {
        for (;;) {
            auto client_socket = m_server.WaitForClient();
            if (!client_socket)
                break;
            // create a thread to handle client connection
            client_socket->Start(m_window, this);
            m_active_clients.push_back(std::move(client_socket));
        }
        SignalInitializationComplete();
    }

    void SetStreamSocket(ClientSock & s) override {
        for (size_t idx = 0; idx < m_active_clients.size(); ++idx) {
            if (m_active_clients[idx].get() == &s) {
                m_streaming_client = std::move(m_active_clients[idx]);
                return;
            }
        }
    }

    void SignalInitializationComplete() override {
        m_init_block = false;
        m_condition.notify_all();
    }

    ~impl() override {
        // close open sockets (forces blocking calls to complete)
        m_server = ServerSock();
        m_worker_thread.join();
        m_streaming_client.reset();
        // wait for client threads to complete
        for (auto & client : m_active_clients) {
            if (client)
                client.reset();
        }
    }

    ServerSock              m_server;  ///< listens for new connections
    std::unique_ptr<ClientSock> m_streaming_client;  ///< video streaming socket
    std::atomic<bool>       m_init_block;
    std::condition_variable m_condition;
    std::thread             m_worker_thread;
    std::vector<std::unique_ptr<ClientSock>> m_active_clients; // heap allocated objects to ensure that they never change address
    HWND                    m_window = nullptr;
    unsigned __int64        m_current_position = 0;
    MP4FragmentEditor       m_data_editor;
};

