WallSquareWorld::WallSquareWorld(/* constructor parameters */)
{
    id = "WallSquareWorld";
    state.emplace_back(start_x);
    state.emplace_back(start_y);

    // Define observation and action space limits
    std::vector<double> min_vals  = {0.0, 0.0};
    std::vector<double> max_vals = {1.0, 1.0};
    observation_space.set_bounds(min_vals, max_vals);
    action_space.set_n(4);

    // Initialize random seed
    int random_seed = std::rand();
    set_seed(random_seed);

    // Rendering configuration
    refresh_interval_for_render2d = 500;
    clipping_area_for_render2d[0] = 0.0;
    clipping_area_for_render2d[1] = 1.0;
    clipping_area_for_render2d[2] = 0.0;
    clipping_area_for_render2d[3] = 1.0;
}

env::StepResult<std::vector<double>> WallSquareWorld::step(int selected_action)
{
    // Handle rendering state update
    if (rendering_enabled) append_state_for_rendering(state);

    bool episode_ended = false; 
    double current_reward = std::exp( -0.5*(std::pow(state[0]-goal_x, 2) + std::pow(state[1]-goal_y, 2))/(std::pow(reward_smoothness, 2)));
    current_reward += randgen.sample_gaussian(0, reward_noise_stdev);

    double x_noise = randgen.sample_gaussian(0, transition_noise_stdev);
    double y_noise = randgen.sample_gaussian(0, transition_noise_stdev);

    double old_x = state[0];
    double old_y = state[1];

    // Apply noise first
    state[0] = std::min(1.0, std::max(0.0, state[0] + x_noise));
    state[1] = std::min(1.0, std::max(0.0, state[1] + y_noise)); 

    // Apply action-based displacement
    if      (selected_action == 0) state[0] = std::max(0.0, state[0] - displacement);
    else if (selected_action == 1) state[0] = std::min(1.0, state[0] + displacement);
    else if (selected_action == 2) state[1] = std::max(0.0, state[1] - displacement);
    else if (selected_action == 3) state[1] = std::min(1.0, state[1] + displacement);

    // Wall collision detection using line interpolation
    double dx = state[0] - old_x;
    double dy = state[1] - old_y;
    double curr_x = old_x; 
    double curr_y = old_y;
    int steps = 10;
    double step_x = dx / steps;
    double step_y = dy / steps;

    for(int idx = 1; idx <= steps; idx++)
    {
        if( ! is_inside_wall( curr_x + step_x, curr_y + step_y) )
        {
            curr_x = curr_x + step_x;
            curr_y = curr_y + step_y;
        }
    }

    clip_to_domain(curr_x, curr_y);
    state[0] = curr_x;
    state[1] = curr_y;

    env::StepResult<std::vector<double>> outcome(state, current_reward, episode_ended);
    return outcome;
}

void WallSquareWorld::clip_to_domain(double &x_coord, double &y_coord)
{
    x_coord = std::max(0.0, x_coord);
    x_coord = std::min(1.0, x_coord);
    y_coord = std::max(0.0, y_coord);
    y_coord = std::min(1.0, y_coord);
}

bool WallSquareWorld::is_inside_wall(double x_val, double y_val)
{
    clip_to_domain(x_val, y_val);
    bool inside = false;
    inside = inside || ( x_val <= wall_1_x1 && x_val >= wall_1_x0 && y_val <= wall_1_y1 && y_val >= wall_1_y0);
    inside = inside || ( x_val <= wall_2_x1 && x_val >= wall_2_x0 && y_val <= wall_2_y1 && y_val >= wall_2_y0);
    return inside;
}

std::vector<double> WallSquareWorld::reset()
{
    std::vector<double> reset_state {start_x, start_y};
    state = reset_state;
    return reset_state; 
}

std::unique_ptr<ContinuousStateEnv> WallSquareWorld::clone() const
{
    return std::make_unique<WallSquareWorld>(*this);
}

utils::render::Scene2D WallSquareWorld::get_scene_for_render2d(std::vector<double> agent_state)
{
    utils::render::Scene2D scene;
    utils::render::Geometric2D agent_shape;
    agent_shape.type = "GL_QUADS";
    agent_shape.set_color(0.75, 0.0, 0.5);
    float dimension = 0.025;
    float px = agent_state[0];
    float py = agent_state[1];

    // Add vertices for the agent shape
    agent_shape.add_vertex(px-dimension/4.0, py-dimension);
    agent_shape.add_vertex(px+dimension/4.0, py-dimension);
    agent_shape.add_vertex(px+dimension/4.0, py+dimension);
    agent_shape.add_vertex(px-dimension/4.0, py+dimension);

    agent_shape.add_vertex(px-dimension, py-dimension/4.0);
    agent_shape.add_vertex(px+dimension, py-dimension/4.0);
    agent_shape.add_vertex(px+dimension, py+dimension/4.0);
    agent_shape.add_vertex(px-dimension, py+dimension/4.0);

    scene.add_shape(agent_shape);
    return scene;
}

utils::render::Scene2D WallSquareWorld::get_background_for_render2d()
{
    utils::render::Scene2D background;

    // Goal flag visualization
    utils::render::Geometric2D goal_flag;
    goal_flag.set_color(0.0, 0.5, 0.0);
    goal_flag.type     = "GL_TRIANGLES";
    goal_flag.add_vertex(goal_x, goal_y);
    goal_flag.add_vertex(goal_x+0.025f, goal_y+0.075f);
    goal_flag.add_vertex(goal_x-0.025f, goal_y+0.075f);
    background.add_shape(goal_flag);

    // First wall
    utils::render::Geometric2D obstacle_1;
    obstacle_1.type = "GL_QUADS";
    obstacle_1.set_color(0.0, 0.0, 0.0);
    obstacle_1.add_vertex(wall_1_x0, wall_1_y0);
    obstacle_1.add_vertex(wall_1_x0, wall_1_y1);
    obstacle_1.add_vertex(wall_1_x1, wall_1_y1);
    obstacle_1.add_vertex(wall_1_x1, wall_1_y0);    
    background.add_shape(obstacle_1);

    // Second wall
    utils::render::Geometric2D obstacle_2;
    obstacle_2.type = "GL_QUADS";
    obstacle_2.set_color(0.0, 0.0, 0.0);
    obstacle_2.add_vertex(wall_2_x0, wall_2_y0);
    obstacle_2.add_vertex(wall_2_x0, wall_2_y1);
    obstacle_2.add_vertex(wall_2_x1, wall_2_y1);
    obstacle_2.add_vertex(wall_2_x1, wall_2_y0);    
    background.add_shape(obstacle_2);

    return background;
}
