extern "C" void sc_value_validation(void *tensor, const char *label, size_t byte_count) {
    // currently assume dtype is float32
    float *buffer = reinterpret_cast<float *>(tensor);
    for (size_t i = 0; i < byte_count / sizeof(float); ++i) {
        float sample = static_cast<float>(buffer[i]);
        if (std::isnan(sample) || std::isinf(sample)) {
            SC_MODULE_WARN << "Malformed value (nan or inf) detected in tensor "
                           << label << " position=" << i;
        }
    }
}

#include <iostream>
#include <vector>
using namespace std;

class PermutationChecker {
 public:
  bool containsPermutation(string pattern, string text) {
    int patternLen = pattern.size(), textLen = text.size();
    if (patternLen > textLen) return false;

    int charCount[26]{};
    int unmatchedCount = patternLen;

    // Initialize counts for pattern characters
    for (char ch : pattern) charCount[ch - 'a']--;

    // Process first window
    int windowEnd = 0;
    for (; windowEnd < patternLen; ++windowEnd) {
      if (++charCount[text[windowEnd] - 'a'] <= 0) 
        --unmatchedCount;
      else 
        ++unmatchedCount;
    }

    if (unmatchedCount == 0) return true;

    // Slide the window through the rest of the text
    for (; windowEnd < textLen; ++windowEnd) {
      // Add new character to window
      if (++charCount[text[windowEnd] - 'a'] <= 0) 
        --unmatchedCount;
      else 
        ++unmatchedCount;

      // Remove old character from window
      if (--charCount[text[windowEnd - patternLen] - 'a'] >= 0) 
        --unmatchedCount;
      else 
        ++unmatchedCount;

      if (unmatchedCount == 0) return true;
    }

    return false;
  }
};

int main(int argc, char const *argv[]) {
  PermutationChecker checker;
  string input1, input2;
  while (cin >> input1 >> input2) {
    cout << checker.containsPermutation(input1, input2) << endl;
  }
  return 0;
}

