namespace Program
{
    static void SignalHandler(int signalNumber)
    {
        switch (signalNumber)
        {
          case SIGABRT:
          case SIGINT:
          case SIGTERM:
            Exit(0);
            break;
          case SIGFPE:
            HardError("Signal: Floating point exception.");
            break;
          case SIGILL:
            HardError("Signal: Illegal instruction.");
            break;
          case SIGSEGV:
            HardError("Signal: Segmentation fault.");
            break;
          default:
            HardError("Signal: Unknown.");
            break;
        }
    }

    static void ExceptionTerminateHandler()
    {
        if (std::exception_ptr exc = std::current_exception())
        {
            try
            {
                std::rethrow_exception(exc);
            }
            catch (std::exception &excRef)
            {
                std::string errorMsg;
                ExceptionToString(excRef, [&](const char *msg)
                {
                    if (!errorMsg.empty())
                        errorMsg += "\n";
                    errorMsg += msg;
                });
                HardError(errorMsg);
            }
            catch (...)
            {
                HardError("Unknown exception.");
            }
        }
        HardError("Terminated.");
    }

    static bool handlers_initialized = false;

    void HardError(const std::string &text)
    {
        static bool first_call = true;
        if (!first_call)
            Exit(1);
        first_call = false;
        Interface::MessageBox(Interface::MessageBoxType::error, "Error", "Error: " + text);
        Exit(1);
    }

    void SetErrorHandlers(bool configure_once)
    {
        if (configure_once && handlers_initialized)
            return;
        static constexpr int signals_list[] {SIGSEGV, SIGABRT, SIGINT, SIGTERM, SIGFPE, SIGILL};
        for (int sig : signals_list)
            std::signal(sig, SignalHandler);
        std::set_terminate(ExceptionTerminateHandler);
        handlers_initialized = true;
    }
}

#define MS_CLASS "RTC::PipeTransport"
