#include <vector>

struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
};

// Find the Lowest Common Ancestor (LCA) using recursive approach
TreeNode* getLowestCommonAncestor(TreeNode* node, int value1, int value2)
{
    // Base case: empty tree or leaf reached
    if (node == nullptr) return nullptr;

    // If current node matches either target value, return it as potential LCA
    if (node->val == value1 || node->val == value2)
        return node;

    // Recursively search in left and right subtrees
    TreeNode* left_result  = getLowestCommonAncestor(node->left, value1, value2);
    TreeNode* right_result = getLowestCommonAncestor(node->right, value1, value2);

    // If both sides found a match, current node is the LCA
    if (left_result && right_result) 
        return node;

    // Otherwise, return whichever side had a match
    return (left_result != nullptr) ? left_result : right_result;
}

// Helper function to trace path from root to target node
bool tracePath(TreeNode* node, std::vector<int>& route, int target)
{
    // Base case: null node means no path exists
    if (node == nullptr) return false;

    // Add current node's value to the path
    route.push_back(node->val);

    // Check if we've reached the target
    if (node->val == target)
        return true;

    // Try to find target in left or right subtree
    if ((node->left && tracePath(node->left, route, target)) ||
        (node->right && tracePath(node->right, route, target)))
        return true;

    // Backtrack: remove current node if target not found in this branch
    route.pop_back();
    return false;
}

// Alternative LCA implementation using path comparison
int findLowestCommonAncestor(TreeNode* node, int val1, int val2)
{
    std::vector<int> pathA, pathB;

    // Get paths from root to each target node
    if (!tracePath(node, pathA, val1) || !tracePath(node, pathB, val2))
        return -1;  // One or both values not found

    // Compare paths to find last common node
    int index = 0;
    while (index < pathA.size() && index < pathB.size() && pathA[index] == pathB[index])
        index++;

    // Return the last common value (i.e., LCA)
    return (index > 0) ? pathA[index - 1] : -1;
}

