#include "RemoteUdpOutput.h"

#ifdef _WIN32
#include <WinSock2.h>
#include <Windows.h>
#else
#include <arpa/inet.h>
#include <fcntl.h>
#include <unistd.h>
#endif

#include "ChannelStrip.h"
#include <string.h>
#include <string>

// Sample rate lookup table for VBAN protocol
static uint32_t SAMPLE_RATE_TABLE[] = {6000,   12000,  24000,  48000, 96000, 192000, 384000, 8000,   16000,  32000, 64000,
                                       128000, 256000, 512000, 11025, 22050, 44100,  88200,  176400, 352800, 705600};

// Protocol identifiers
#define VBAN_HEADER_SIGNATURE 0x4e414256  // "VBAN" in little-endian
#define AUDIO_PROTOCOL        0x00
#define SERIAL_PROTOCOL       0x20
#define TEXT_PROTOCOL         0x40
#define SERVICE_PROTOCOL      0x60

// Data type definitions
#define FORMAT_8BIT           0x00
#define FORMAT_16BIT          0x01
#define FORMAT_24BIT          0x02
#define FORMAT_32BIT          0x03
#define FORMAT_FLOAT32        0x04
#define FORMAT_FLOAT64        0x05
#define FORMAT_12BITS         0x06
#define FORMAT_10BITS         0x00

// Audio codec: PCM only supported
#define AUDIO_CODEC_PCM       0x00

RemoteUdpOutput::RemoteUdpOutput(OscContainer* oscParent, const char* name)
    : is_running(false), sampleRateMonitor(oscParent, name) {}

RemoteUdpOutput::~RemoteUdpOutput() {
    shutdown();
}

int RemoteUdpOutput::initialize(int stream_index, int sample_rate, const char* target_ip, int udp_port) {
    std::string stream_id = ChannelStrip::JACK_CLIENT_NAME_PREFIX + std::to_string(stream_index);
    uint32_t ip_address = inet_addr(target_ip);

    if(is_running)
        return 1;

    is_running = true;
    SPDLOG_INFO("Transmitting audio stream {} to {}:{}", stream_index, target_ip, udp_port);

    server_addr.sin_addr.s_addr = ip_address;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(udp_port);

    if((udp_socket = socket(AF_INET, SOCK_DGRAM, 0)) == -1) {
        SPDLOG_ERROR("Failed to create UDP socket: {} ({})", strerror(errno), errno);
        return 2;
    }

#ifndef _WIN32
    int flags;
    flags = fcntl(udp_socket, F_GETFL, 0);
    fcntl(udp_socket, F_SETFL, flags | O_NONBLOCK);
    int broadcast_flag = 1;
    setsockopt(udp_socket, SOL_SOCKET, SO_BROADCAST, &broadcast_flag, sizeof(broadcast_flag));
#else
    unsigned long nonblocking_flag = 1;
    ioctlsocket(udp_socket, FIONBIO, &nonblocking_flag);
#endif

    vban_packet.header.vban = VBAN_HEADER_SIGNATURE;  // Set VBAN signature
    configureSampleRate(sample_rate);
    vban_packet.header.format_nbc = 2 - 1;                // stereo: numChannels - 1
    vban_packet.header.format_bit = FORMAT_16BIT;         // 16-bit integer PCM
    strncpy(vban_packet.header.streamname, stream_id.c_str(), sizeof(vban_packet.header.streamname) - 1);
    vban_packet.header.nuFrame = 0;

    return 0;
}

void RemoteUdpOutput::shutdown() {
    if(is_running) {
        is_running = false;
        int socket_descriptor = this->udp_socket;
        this->udp_socket = -1;
#ifdef _WIN32
        closesocket(socket_descriptor);
#else
        close(socket_descriptor);
#endif
    }
}

bool RemoteUdpOutput::isActive() {
    return is_running;
}

void RemoteUdpOutput::onSlowTimer() {
    sampleRateMonitor.onTimeoutTimer();
}

void RemoteUdpOutput::configureSampleRate(uint32_t rate) {
    for(size_t idx = 0; idx < sizeof(SAMPLE_RATE_TABLE) / sizeof(SAMPLE_RATE_TABLE[0]); idx++) {
        if(SAMPLE_RATE_TABLE[idx] == rate) {
            vban_packet.header.format_SR = idx;
            break;
        }
    }
}

void RemoteUdpOutput::transmitAudio(float* channel_left, float* channel_right, size_t frame_count) {
    if(udp_socket <= 0)
        return;

    for(size_t frames_processed = 0; frames_processed < frame_count;) {
        size_t frames_to_send = frame_count - frames_processed;
        if(frames_to_send > 128)  // Reduced from 256 to 128
            frames_to_send = 128;

        vban_packet.header.format_nbs = frames_to_send - 1;

        for(size_t i = 0; i < frames_to_send; i++) {
            vban_packet.data[i * 2] = static_cast<int16_t>(channel_left[i + frames_processed] * 0x8000);     // 32768 as hex
            vban_packet.data[i * 2 + 1] = static_cast<int16_t>(channel_right[i + frames_processed] * 0x8000);
        }

        int bytes_sent = sendto(udp_socket,
                                reinterpret_cast<char*>(&vban_packet),
                                sizeof(vban_packet.header) + frames_to_send * 2 * sizeof(vban_packet.data[0]),
                                0,
                                reinterpret_cast<const struct sockaddr*>(&server_addr),
                                sizeof(server_addr));

        if(bytes_sent == -1 && errno == EWOULDBLOCK)
            bytes_sent = 0;

        if(bytes_sent == -1 && udp_socket > 0) {
            SPDLOG_ERROR("UDP transmission error, errno: {}", errno);
            break;
        }

        frames_processed += frames_to_send;
        vban_packet.header.nuFrame++;
    }

    sampleRateMonitor.notifySampleProcessed(frame_count);
}

void RemoteUdpOutput::transmitAudioWithoutVBAN(float* channel_left, float* channel_right, size_t frame_count) {
    if(udp_socket <= 0)
        return;

    for(size_t frames_processed = 0; frames_processed < frame_count;) {
        size_t frames_to_send = frame_count - frames_processed;
        if(frames_to_send > sizeof(vban_packet.data))
            frames_to_send = sizeof(vban_packet.data);

        for(size_t i = 0; i < frames_to_send; i++) {
            vban_packet.data[i * 2] = static_cast<int16_t>(channel_left[i + frames_processed] * 0x8000);
            vban_packet.data[i * 2 + 1] = static_cast<int16_t>(channel_right[i + frames_processed] * 0x8000);
        }

        int bytes_sent = sendto(udp_socket,
                                reinterpret_cast<char*>(vban_packet.data),
                                frames_to_send * 2 * sizeof(vban_packet.data[0]),
                                0,
                                reinterpret_cast<const struct sockaddr*>(&server_addr),
                                sizeof(server_addr));

        if(bytes_sent == -1 && errno == EWOULDBLOCK)
            bytes_sent = 0;

        if(bytes_sent == -1 && udp_socket > 0) {
            // Log suppressed: SPDLOG_INFO("Socket error during raw transmission, errno: {}", errno);
        }

        frames_processed += frames_to_send;
    }

    sampleRateMonitor.notifySampleProcessed(frame_count);
}

