// ------------------ ordt_addr_elem methods ------------------
ordt_addr_elem::ordt_addr_elem(uint64_t _start_addr, uint64_t _end_addr)
  : m_startaddress(_start_addr),
    m_endaddress(_end_addr) {
}

bool ordt_addr_elem::containsAddress(const uint64_t &addr) const {
  return ((addr >= m_startaddress) && (addr <= m_endaddress));
}

bool ordt_addr_elem::isBelowAddress(const uint64_t &addr) const {
  return (addr > m_endaddress);
}

bool ordt_addr_elem::isAboveAddress(const uint64_t &addr) const {
  return (addr < m_startaddress);
}

bool ordt_addr_elem::hasStartAddress(const uint64_t &addr) const {
  return (addr == m_startaddress);
}

void ordt_addr_elem::update_child_ptrs() {
}

// ------------------ ordt_regset methods ------------------
ordt_addr_elem* ordt_regset::findAddrElem(const uint64_t &addr) {
  int low = 0;
  int high = static_cast<int>(m_children.size()) - 1;
  int middle = 0;
  while (low <= high) {
     middle = (low + high) / 2;
     if (m_children[middle]->containsAddress(addr)) {
        return m_children[middle];
     }
     else if (m_children[middle]->isAboveAddress(addr))
        high = middle - 1;
     else
        low = middle + 1;
  }
  return nullptr;
}

ordt_regset::ordt_regset(uint64_t _start_addr, uint64_t _end_addr)
  : ordt_addr_elem(_start_addr, _end_addr) {
}

int ordt_regset::write(const uint64_t &addr, const ordt_data &wdata) {
     if (this->containsAddress(addr)) {
        childElem = this->findAddrElem(addr);
        if (childElem != nullptr) { return childElem->write(addr, wdata); }
     }
  #ifdef ORDT_PIO_VERBOSE
     std::cout << "--> write to invalid address " << addr << " in regset\n";
  #endif
     return 8;
}

int ordt_regset::read(const uint64_t &addr, ordt_data &rdata) {
     if (this->containsAddress(addr)) {
        childElem = this->findAddrElem(addr);
        if (childElem != nullptr) { return childElem->read(addr, rdata); }
     }
  #ifdef ORDT_PIO_VERBOSE
     std::cout << "--> read to invalid address " << addr << " in regset\n";
  #endif
     rdata.clear();
     return 8;
}

