void Representador::dibujar_rejilla(DLibV::Pantalla& pantalla, int paso, tcolor color, double x_origen, double y_origen, double factor_zoom, int ancho, int alto)
{
	DLibV::Representacion_primitiva_linea linea(0, 0, 0, 0, color.r, color.g, color.b);
	linea.establecer_alpha(color.a);

	double inicio_x = -(fmod(x_origen, paso)) / factor_zoom;
	double fin_x = inicio_x + ancho;

	while(inicio_x < fin_x)
	{
		linea.establecer_puntos(inicio_x, 0, inicio_x, alto);
		linea.volcar(pantalla);
		inicio_x += (paso / factor_zoom);
	}

	double inicio_y = (fmod(y_origen, paso)) / factor_zoom;
	double fin_y = inicio_y + alto;

	while(inicio_y < fin_y)
	{
		linea.establecer_puntos(0, inicio_y, ancho, inicio_y);
		linea.volcar(pantalla);
		inicio_y += (paso / factor_zoom);
	}
}

