void Representador::dibujar_hud(DLibV::Pantalla& pantalla, const DLibV::Fuente_TTF& fuente, const std::string& texto_tiempo, bool alerta_tiempo, int max_velocidad, int vel_actual, int vel_total)
{
	auto color = alerta_tiempo ? SDL_Color{255, 32, 32, 255} : SDL_Color{255, 255, 255, 255};
	DLibV::Representacion_TTF texto(fuente, color, texto_tiempo);
	texto.ir_a(16, 70);
	texto.volcar(pantalla);

	DLibV::Representacion_bitmap sprite(DLibV::Gestor_texturas::obtener(r_graficos::g_hud));
	sprite.establecer_modo_blend(DLibV::Representacion::BLEND_ALPHA);

	auto dibujar_barras = [&](int& contador, int limite, int x_recorte, int alpha) {
		sprite.establecer_recorte(x_recorte, 0, 31, 40);
		sprite.establecer_alpha(alpha);
		while(contador <= limite)
		{
			sprite.establecer_posicion((contador * 33) + 16, 16, 31, 40);
			sprite.volcar(pantalla);
			++contador;
		}
	};

	// Velocidad actual
	sprite.establecer_recorte(31, 0, 31, 40);
	sprite.establecer_alpha(255);
	int cont_vel = 0;

	dibujar_barras(cont_vel, vel_actual, 31, 255);

	if(velocidad_minima_aviso.tiempo && cont_vel <= velocidad_minima_aviso.velocidad)
	{
		int alfa = static_cast<int>((velocidad_minima_aviso.tiempo * 255) / 1.2f);
		int temp = cont_vel;
		dibujar_barras(temp, velocidad_minima_aviso.velocidad, 62, alfa < 128 ? 128 : alfa);
	}

	if(cont_vel <= max_velocidad) dibujar_barras(cont_vel, max_velocidad, 0, 128);
	if(cont_vel <= vel_total) dibujar_barras(cont_vel, vel_total, 93, 128);
}

void Representador::turno(float dt)
{
	if(velocidad_minima_aviso.tiempo > 0.0f)
	{
		velocidad_minima_aviso.tiempo -= dt;
		if(velocidad_minima_aviso.tiempo < 0.0f)
			velocidad_minima_aviso.tiempo = 0.0f;
	}
}

