{
	velocidad_minima_aviso = {vel, 1.2f};
}

#include "reduction_utils.hpp"
#include <CL/sycl.hpp>
#include <cassert>
using namespace cl::sycl;

template <typename T, bool B> class KernelName;

template <int Dims>
std::ostream &operator<<(std::ostream &OS, const range<Dims> &Rng) {
  OS << "{" << Rng[0];
  if constexpr (Dims > 1)
    OS << ", " << Rng[1];
  if constexpr (Dims > 2)
    OS << ", " << Rng[2];
  OS << "}";
  return OS;
}

template <typename Name, bool IsSYCL2020Mode, access::mode AccMode, typename ValueType,
          int AccDim = 1, class CombineOp, int Dims>
void runTest(queue &Q, ValueType IdentityVal, ValueType InitVal, CombineOp Op,
             range<Dims> Range) {
  std::string ModeStr = IsSYCL2020Mode ? "SYCL2020" : "ONEAPI  ";
  std::cout << "Executing test: " << ModeStr
            << " {T=" << typeid(ValueType).name()
            << ", Op=" << typeid(CombineOp).name() << ", Range=" << Range
            << std::endl;

  // Avoid testing extremely large datasets for now
  constexpr size_t MaxSize = 2LL * 1024 * 1024 * 1024;
  if (Range.size() > MaxSize)
    return;

  buffer<ValueType, Dims> InputBuf(Range);
  buffer<ValueType, 1> OutputBuf(1);

  ValueType ExpectedResult;
  initInputData(InputBuf, ExpectedResult, IdentityVal, Op, Range);

  if constexpr (AccMode == access::mode::read_write) {
    ExpectedResult = Op(ExpectedResult, InitVal);
  }

  // Initialize output buffer; this value will be overwritten during reduction
  (OutputBuf.template get_access<access::mode::write>())[0] = InitVal;

  if constexpr (IsSYCL2020Mode) {
    Q.submit([&](handler &CGH) {
      auto In = InputBuf.template get_access<access::mode::read>(CGH);
      property_list PropList = getPropertyList<AccMode>();
      auto Redu = sycl::reduction(OutputBuf, CGH, IdentityVal, Op, PropList);
      CGH.parallel_for<Name>(
          Range, Redu, [=](id<Dims> Idx, auto &Reducer) { Reducer.combine(In[Idx]); });
    });
  } else {
    Q.submit([&](handler &CGH) {
      auto In = InputBuf.template get_access<access::mode::read>(CGH);
      accessor<ValueType, AccDim, AccMode, access::target::global_buffer> Out(OutputBuf, CGH);
      auto Redu = ext::oneapi::reduction(Out, IdentityVal, Op);
      CGH.parallel_for<Name>(
          Range, Redu, [=](id<Dims> Idx, auto &Reducer) { Reducer.combine(In[Idx]); });
    });
  }

  // Validate result
  auto Out = OutputBuf.template get_access<access::mode::read>();
  ValueType ActualResult = *(Out.get_pointer());
  if (ActualResult != ExpectedResult) {
    printDeviceInfo(Q, true);
    std::cerr << "Mismatch: Range = " << Range << ", "
              << "Computed: " << ActualResult
              << ", Expected: " << ExpectedResult << "\n";
    assert(0 && "Incorrect reduction result.");
  }
}

template <typename Name, access::mode AccMode, typename ValueType, class CombineOp,
          int Dims>
void runBothModes(queue &Q, ValueType IdentityVal, ValueType InitVal, CombineOp Op,
                  range<Dims> Range) {
  runTest<KernelName<Name, false>, false, AccMode>(Q, IdentityVal, InitVal, Op, Range);
  runTest<KernelName<Name, true>, true, AccMode>(Q, IdentityVal, InitVal, Op, Range);
}

#include <iostream>

void ExtensionServiceBackend::LoadSingleExtension(const FilePath& extension_file_path) {
  CHECK(BrowserThread::CurrentlyOn(BrowserThread::FILE));

  FilePath abs_path = extension_file_path;
  file_util::AbsolutePath(&abs_path);

  int load_flags = Extension::ShouldAlwaysAllowFileAccess(Extension::LOAD) 
                   ? Extension::ALLOW_FILE_ACCESS 
                   : Extension::NO_FLAGS;

  if (Extension::ShouldDoStrictErrorChecking(Extension::LOAD)) {
    load_flags |= Extension::STRICT_ERROR_CHECKS;
  }

  std::string load_error;
  scoped_refptr<const Extension> loaded_ext(extension_file_util::LoadExtension(
      abs_path,
      Extension::LOAD,
      load_flags,
      &load_error));

  if (!loaded_ext) {
    if (!BrowserThread::PostTask(
            BrowserThread::UI, FROM_HERE,
            NewRunnableMethod(
                this,
                &ExtensionServiceBackend::ReportExtensionLoadError,
                abs_path, load_error))) {
      NOTREACHED() << load_error;
    }
    return;
  }

  // Mark as installed so it persists in preferences
  if (!BrowserThread::PostTask(
          BrowserThread::UI, FROM_HERE,
          NewRunnableMethod(
              this,
              &ExtensionServiceBackend::OnExtensionInstalled,
              loaded_ext))) {
    NOTREACHED();
  }
}

