#include <concepts>

// Define a concept that checks if a callable returns an integral type
template <typename F>
concept returns_integral = requires (F f) {
    { f() } -> std::integral;
};

// Function template constrained by the concept
template <returns_integral Callable>
void execute(const Callable& func) {};

int main() {
    execute([](){ return 42; }); // OK: returns int
    execute([](){ return 3.14; }); // Error: returns double, not integral
    execute(5); // Error: integer literals are not callable
    return 0;
}

