    std::string AssetModule::type_name_static_ = "AssetResources";

    AssetModule::AssetModule() : IModule(type_name_static_), event_handler_id_(0)
    {
    }

    AssetModule::~AssetModule()
    {
    }

    // virtual
    void AssetModule::Load()
    {
    }

    // virtual
    void AssetModule::Initialize()
    {
        resource_manager_ = AssetManagerPtr(new AssetManager(framework_));
        framework_->GetServiceManager()->RegisterService(Service::ST_Asset, resource_manager_);

        // Register XML-RPC provider first since it handles specific requests before HTTP providers
        xmlrpc_handler_ = Foundation::AssetProviderPtr(new XMLRPCAssetProvider(framework_));
        resource_manager_->RegisterAssetProvider(xmlrpc_handler_);

        // Add HTTP handler before UDP so it can process texture requests via UUID through GetTexture caps URL
        http_handler_ = Foundation::AssetProviderPtr(new QtHttpAssetProvider(framework_));
        resource_manager_->RegisterAssetProvider(http_handler_);

        // Add local asset handler with default directory for now
        // Note: this path differs from the "pre-warmed assetcache" concept
        local_handler_ = Foundation::AssetProviderPtr(new LocalAssetProvider(framework_, "./assets/data"));
        resource_manager_->RegisterAssetProvider(local_handler_);

        // Final fallback is UDP provider
        udp_handler_ = Foundation::AssetProviderPtr(new UDPAssetProvider(framework_));
        resource_manager_->RegisterAssetProvider(udp_handler_);

        framework_event_id_ = framework_->GetEventManager()->QueryEventCategory("Framework");
    }

    void AssetModule::PostInitialize()
    {
        RegisterConsoleCommand(Console::CreateCommand(
            "FetchAsset", "Request asset from server. Usage: FetchAsset(uuid,assettype)", 
            Console::Bind(this, &AssetModule::ConsoleFetchAsset)));
    }

    void AssetModule::SubscribeToNetworkEvents(boost::weak_ptr<ProtocolUtilities::ProtocolModuleInterface> currentProtocolModule)
    {
        protocolModule_ = currentProtocolModule;
        udp_handler_->SetCurrentProtocolModule(protocolModule_);
        network_event_id_ = framework_->GetEventManager()->QueryEventCategory("NetworkState");
        event_handler_id_ = framework_->GetEventManager()->QueryEventCategory("NetworkIn");
    }

    void AssetModule::UnsubscribeNetworkEvents()
    {
    }

    // virtual
    void AssetModule::Update(f64 frametime)
    {
        {
            PROFILE(AssetModule_Update);
            if (resource_manager_)
                resource_manager_->Update(frametime);
        }
        RESETPROFILER;
    }

    // virtual 
    void AssetModule::Uninitialize()
    {
        resource_manager_->UnregisterAssetProvider(udp_handler_);
        resource_manager_->UnregisterAssetProvider(xmlrpc_handler_);
        resource_manager_->UnregisterAssetProvider(local_handler_);
        resource_manager_->UnregisterAssetProvider(http_handler_);
        framework_->GetServiceManager()->UnregisterService(resource_manager_);
        resource_manager_.reset();
    }

    Console::CommandResult AssetModule::ConsoleFetchAsset(const StringVector &params)
    {
        if (params.size() != 2)
            return Console::ResultFailure("Usage: FetchAsset(uuid,assettype)");
        resource_manager_->RequestAsset(params[0], params[1]);
        return Console::ResultSuccess();
    }

    bool AssetModule::HandleEvent(
        event_category_id_t category_id,
        event_id_t event_id, 
        IEventData* data)
    {
        PROFILE(AssetModule_HandleEvent);
        if ((category_id == event_handler_id_))
        {
            if (udp_handler_)
                return checked_static_cast<UDPAssetProvider*>(udp_handler_.get())->HandleNetworkEvent(data);
        }
        else if (category_id == framework_event_id_ && event_id == Foundation::NETWORKING_REGISTERED)
        {
            ProtocolUtilities::NetworkingRegisteredEvent *event_data = dynamic_cast<ProtocolUtilities::NetworkingRegisteredEvent *>(data);
            if (event_data)
                SubscribeToNetworkEvents(event_data->currentProtocolModule);
            return false;
        }
        if (category_id == network_event_id_ && event_id == ProtocolUtilities::Events::EVENT_SERVER_DISCONNECTED)
        {
            if (udp_handler_)
                checked_static_cast<UDPAssetProvider*>(udp_handler_.get())->ClearAllTransfers();
            if (http_handler_)
                checked_static_cast<QtHttpAssetProvider*>(http_handler_.get())->ClearAllTransfers();
        }
        if (category_id == network_event_id_ && event_id == ProtocolUtilities::Events::EVENT_CAPS_FETCHED)
        {
            if (protocolModule_.lock().get() && http_handler_)
            {
                std::string get_texture_cap = protocolModule_.lock()->GetCapability("GetTexture");
                checked_static_cast<QtHttpAssetProvider*>(http_handler_.get())->SetGetTextureCap(get_texture_cap);
            }
        }
        return false;
    }
}

