void Framebuffer::validateFramebufferState() {
    GLenum status = glCheckFramebufferStatus( GL_FRAMEBUFFER );
    if ( status == GL_FRAMEBUFFER_COMPLETE ) return;

    std::string errorMsg{};
    switch ( status ) {
        case GL_FRAMEBUFFER_UNDEFINED:
            errorMsg = "Frame Buffer creation error code: GL_FRAMEBUFFER_UNDEFINED";
            break;
        case GL_FRAMEBUFFER_INCOMPLETE_ATTACHMENT:
            errorMsg = "Frame Buffer creation error code: GL_FRAMEBUFFER_INCOMPLETE_ATTACHMENT";
            break;
        case GL_FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT:
            errorMsg = "Frame Buffer creation error code: GL_FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT";
            break;
        case GL_FRAMEBUFFER_UNSUPPORTED:
            errorMsg = "Frame Buffer creation error code: GL_FRAMEBUFFER_UNSUPPORTED";
            break;
        case GL_FRAMEBUFFER_INCOMPLETE_MULTISAMPLE:
            errorMsg = "Frame Buffer creation error code: GL_FRAMEBUFFER_INCOMPLETE_MULTISAMPLE";
            break;
        default:
            errorMsg = "Frame Buffer creation error code: UNKNOWN (You should be very scared about this";
            break;
    }
    LOGRS( "Framebuffer " << mName << " dimensions: [" << mWidth << ":" << mHeight << "] pixel format : ["
                          << glEnumToString( pixelFormatToGlInternalFormat(mFormat) ) << "] "
