#include "numbers.dat"
#include <iostream>
#include <memory>

int main(int numArgs, char* args[]) {
    const int limit = 100005;

    // Allocate memory for prime checking array
    std::unique_ptr<bool[]> primeFlag_ptr(new bool[limit]);
    bool* primeFlag = primeFlag_ptr.get();

    // Initialize all numbers as potentially prime
    for (int idx = 0; idx < limit; ++idx) {
        primeFlag[idx] = true;
    }

    // Mark 0 and 1 as not prime
    primeFlag[0] = false;
    primeFlag[1] = false;

    // Sieve of Eratosthenes implementation
    for (int num = 2; num < limit; num++) {
        if (primeFlag[num]) {
            for (int multiple = num * 2; multiple < limit; multiple += num) {
                primeFlag[multiple] = false;
            }
        }
    }

    // Build prefix sum array for prime counts
    std::unique_ptr<int[]> prefixCount_ptr(new int[Size]);
    int* prefixCount = prefixCount_ptr.get();

    prefixCount[0] = primeFlag[Data[0]];
    for (int pos = 1; pos < Size; ++pos) {
        prefixCount[pos] = prefixCount[pos - 1] + primeFlag[Data[pos]];
    }

    // Validate command line arguments
    if (numArgs % 2 != 1 || numArgs == 1) {
        return -1;
    }

    // Process each pair of arguments
    for (int pairIdx = 1; pairIdx < numArgs; pairIdx += 2) {
        int lowerBound = atoi(args[pairIdx]);
        int upperBound = atoi(args[pairIdx + 1]);

        // Check if range is valid
        if (upperBound < lowerBound) {
            std::cout << 0 << std::endl;
            return 0;
        }

        // Find index of lower bound in Data array
        int leftIndex = 0;
        while (leftIndex < Size && Data[leftIndex] != lowerBound) {
            ++leftIndex;
        }
        if (leftIndex >= Size) {
            std::cout << 0 << std::endl;
            return 0;
        }

        // Find index of upper bound in Data array
        int rightIndex = Size - 1;
        while (rightIndex >= 0 && Data[rightIndex] != upperBound) {
            --rightIndex;
        }
        if (rightIndex < 0) {
            std::cout << 0 << std::endl;
            return 0;
        }

        // Calculate count of primes in range using prefix sums
        std::cout << prefixCount[rightIndex] - prefixCount[leftIndex] + primeFlag[Data[leftIndex]] << std::endl;
    }

    return 0;
}

