namespace rt {
namespace math {

Distribution::Distribution()
    : mPDF(nullptr)
    , mCDF(nullptr)
    , mSize(0)
{
}

Distribution::~Distribution()
{
    DefaultAllocator::Free(mCDF);
    DefaultAllocator::Free(mPDF);
    mCDF = nullptr;
    mPDF = nullptr;
}

bool Distribution::Initialize(const float* inputPdf, uint32 count)
{
    if (count == 0)
    {
        RT_LOG_ERROR("Empty distribution");
        return false;
    }
    if (!inputPdf)
    {
        RT_LOG_ERROR("Invalid distribution pdf");
        return false;
    }

    mPDF = (float*)DefaultAllocator::Allocate(sizeof(float) * (size_t)count, RT_CACHE_LINE_SIZE);
    if (!mPDF)
    {
        RT_LOG_ERROR("Failed to allocate memory for PDF");
        return false;
    }

    mCDF = (float*)DefaultAllocator::Allocate(sizeof(float) * ((size_t)count + 1), RT_CACHE_LINE_SIZE);
    if (!mCDF)
    {
        RT_LOG_ERROR("Failed to allocate memory for CDF");
        return false;
    }

    // compute cumulated distribution function
    float runningSum = 0.0f;
    mCDF[0] = 0.0f;
    for (uint32 idx = 0; idx < count; ++idx)
    {
        RT_ASSERT(IsValid(inputPdf[idx]), "Corrupted pdf");
        RT_ASSERT(inputPdf[idx] >= 0.0f, "Pdf must be non-negative");
        runningSum += inputPdf[idx];
        mCDF[idx + 1] = runningSum;
    }
    RT_ASSERT(runningSum > 0.0f, "Pdf must be non-zero");

    // normalize
    const float cdfScale = 1.0f / runningSum;
    const float pdfScale = cdfScale * static_cast<float>(count);
    for (uint32 idx = 0; idx < count; ++idx)
    {
        mCDF[idx] *= cdfScale;
        mPDF[idx] = inputPdf[idx] * pdfScale;
    }
    mCDF[count] *= cdfScale;

    // TODO Cumulative distribution function should be stored as unsigned integers, as it's only in 0-1 range
    mSize = count;
    return true;
}

uint32 Distribution::SampleDiscrete(const float randVal, float& outPdf) const
{
    uint32 left = 0u;
    uint32 right = mSize;

    // binary search
    while (left < right)
    {
        uint32 mid = (left + right) / 2u;
        if (randVal >= mCDF[mid])
        {
            left = mid + 1u;
        }
        else
        {
            right = mid;
        }
    }

    uint32 index = left - 1u;
    outPdf = mPDF[index];
    return index;
}

