int main() {
    ProbabilisticCounter<uint64_t> counter1, counter2;
    PCSA<uint64_t> pcSA(1000);
    wy::WyRand<uint64_t> rng;

    for (size_t idx = 0; idx < 100000; ++idx) {
        auto value = rng();
        counter1.addh(value);
        pcSA.addh(value);
    }

    PCSA<uint64_t> pcSA2(1000);
    for (size_t idx = 0; idx < 100000; ++idx) {
        auto value = rng();
        counter2.addh(value);
        pcSA2.addh(value);
    }

    std::fprintf(stderr, "100000: %g, pcsa: %g\n", counter1.report(), pcSA.report());
    std::fprintf(stderr, "100000: %g, pcsa: %g\n", counter2.report(), pcSA2.report());

    pcSA2 |= pcSA;
    counter2 |= counter1;

    std::fprintf(stderr, "200000 (union): %g, pcsa: %g\n", counter2.report(), pcSA2.report());
}

