// Helper function to compute projection matrices
inline void BuildProjectionMatrices(const double intr[9],
                                    const double rot[9],
                                    const double trans[3],
                                    const double row4[4],
                                    double proj[16],
                                    double inv_proj[16]) {
    // Construct 3x4 projection matrix
    Eigen::Matrix<double, 3, 4, Eigen::RowMajor> P_3x4;
    P_3x4.block<3, 3>(0, 0) = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(rot);
    P_3x4.col(3) = Eigen::Map<const Eigen::Matrix<double, 3, 1>>(trans);
    P_3x4 = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(intr) * P_3x4;

    // Extend to 4x4 matrix
    Eigen::Matrix<double, 4, 4, Eigen::RowMajor> fullP;
    fullP.block<3, 4>(0, 0) = P_3x4;
    fullP.row(3) = Eigen::Map<const Eigen::Matrix<double, 1, 4>>(row4);

    // Normalize for numerical stability
    const double scale_factor = 10.0 / fullP.cwiseAbs().maxCoeff();
    fullP *= scale_factor;

    memcpy(proj, fullP.data(), 16 * sizeof(double));

    // Compute inverse
    Eigen::Matrix<double, 4, 4, Eigen::RowMajor> inv_fullP = fullP.inverse();
    const double inv_scale = 10.0 / inv_fullP.cwiseAbs().maxCoeff();
    inv_fullP *= inv_scale;

    memcpy(inv_proj, inv_fullP.data(), 16 * sizeof(double));
}

// Helper function to compute camera center
inline void ComputeCameraCenter(const double rot[9], const double trans[3], double center[3]) {
    const Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> R(rot);
    const Eigen::Map<const Eigen::Matrix<double, 3, 1>> t(trans);
    const Eigen::Matrix<double, 3, 1> C = -R.transpose() * t;
    memcpy(center, C.data(), 3 * sizeof(double));
}

// Convert double array to float array
inline void DoubleToFloatArray(const double* src, float* dst, int size) {
    for (int idx = 0; idx < size; ++idx) {
        dst[idx] = static_cast<float>(src[idx]);
    }
}

