float Image::GetDepth(double x, double y, double z) const {
    Eigen::Matrix<double, 3, 4, Eigen::RowMajor> P_3x4;
    P_3x4.block<3, 3>(0, 0) = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(R_);
    P_3x4.col(3) = Eigen::Map<const Eigen::Matrix<double, 3, 1>>(T_);
    P_3x4 = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(K_) * P_3x4;

    Eigen::Matrix<double, 4, 4, Eigen::RowMajor> P_full;
    P_full.block<3, 4>(0, 0) = P_3x4;
    P_full.row(3) = Eigen::Map<const Eigen::Matrix<double, 1, 4>>(last_row_);

    const Eigen::Vector4d point(x, y, z, 1.0);
    const Eigen::Vector4d projected = P_full * point;

    const double depth_val = projected[3] / projected[2];
    return static_cast<float>(depth_val);
}

