void Image::Original(float K[9], float inv_K[9], float R[9], float T[3], float P[16], float inv_P[16], float C[3]) const {
    double P_d[16];
    double inv_P_d[16];
    BuildProjectionMatrices(K_, R_, T_, last_row_, P_d, inv_P_d);

    double C_d[3];
    ComputeCameraCenter(R_, T_, C_d);

    const Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> K_mat(K_);
    const Eigen::Matrix<double, 3, 3, Eigen::RowMajor> K_inv = K_mat.inverse();
    const double* K_inv_data = K_inv.data();

    DoubleToFloatArray(K_, K, 9);
    DoubleToFloatArray(K_inv_data, inv_K, 9);
    DoubleToFloatArray(R_, R, 9);
    DoubleToFloatArray(T_, T, 3);
    DoubleToFloatArray(P_d, P, 16);
    DoubleToFloatArray(inv_P_d, inv_P, 16);
    DoubleToFloatArray(C_d, C, 3);
}

