namespace ChipDnaClientLib {
#pragma region Static Methods
	static int FindFirstMatch(const std::string& textToScan, const std::vector<char>& targetChars, const int startPos) {
		if (textToScan.empty() || targetChars.empty())
			return -1;
		const int textSize = textToScan.length();
		if (startPos < 0 || startPos > textSize)
			return -1;
		for (int index = startPos; index < textSize; ++index) {
			const char currentChar = textToScan[index];
			for (char targetChar : targetChars) {
				if (currentChar == targetChar) {
					return index;
				}
			}
		}
		return -1;
	}

	static void FlushQueue(std::queue<std::string>& queueToClear) {
		while (!queueToClear.empty()) {
			queueToClear.pop();
		}
	}

	static void AppendBuffer(std::vector<char>& destination, char source[], const int count) {
		for (int i = 0; i < count; ++i) {
			destination.push_back(source[i]);
		}
	}

	static void CopyVectorToArray(const std::vector<char>& source, char destination[]) {
		for (size_t i = 0; i < source.size(); ++i) {
			destination[i] = source[i];
		}
	}

	static void NoOperation(std::string&) { }
#pragma endregion

#pragma region Public Methods
	void ClientBase::SetDisconnectionHandler(OnDisconnection handler) {
		disconnectionCallback = handler;
	}

	void ClientBase::UnregisterDisconnectionHandler() {
		if (disconnectionCallback) {
			disconnectionCallback = NoOperation;
		}
	}

	bool ClientBase::ConnectionActive() const {
		return !isShuttingDown;
	}

	ClientBase::ClientBase()
		: errorOccured(false), isShuttingDown(true), sslEnabled(false) {
		pthread_mutex_init(&writeList_mutex, nullptr);
		pthread_mutex_init(&readList_mutex, nullptr);
		pthread_cond_init(&writeList_cond, nullptr);
		pthread_cond_init(&readList_cond, nullptr);
	}
#pragma endregion

#pragma region Private Methods
	void ClientBase::InitializeThreads() {
		errorOccured = false;
		pthread_attr_t attributes;
		pthread_attr_init(&attributes);
		pthread_attr_setdetachstate(&attributes, PTHREAD_CREATE_DETACHED);
		pthread_create(&readerThread, &attributes, &ClientBase::read, static_cast<void*>(this));
		pthread_create(&writerThread, &attributes, &ClientBase::write, static_cast<void*>(this));
		pthread_create(&progressThread, &attributes, &ClientBase::process, static_cast<void*>(this));
		pthread_attr_destroy(&attributes);
	}

	bool ClientBase::Terminate(bool forceClose, bool alreadyClosed) {
		if (isShuttingDown) return true;
		isShuttingDown = true;
		closeSockets();
		clearDataStructures();
		if (!alreadyClosed && disconnectionCallback) {
			std::string message = "Connection Failure: Lost connection with the server";
			disconnectionCallback(message);
		}
		return true;
	}

	void ClientBase::EnqueueWriteRequest(ResponseContainer request) {
		pthread_mutex_lock(&writeList_mutex);
		writeList.push(std::move(request));
		pthread_cond_broadcast(&writeList_cond);
		pthread_mutex_unlock(&writeList_mutex);
	}

	bool ClientBase::closeSockets() {
		errorOccured = true;
		if (sslEnabled) {
			BIO_free_all(bio);
			SSL_CTX_free(ctx);
			sslEnabled = false;
		}
#if !_WIN32
		if (!sslEnabled) {
			shutdown(_socket, SHUT_RDWR);
		}
#endif
		if (!sslEnabled)
			close(_socket);
#ifdef _WIN32
		if (!sslEnabled) {
			if (wsaStarted)
				WSACleanup();
		}
#endif
		return true;
	}

	void* ClientBase::write(void* threadId) {
		int result = 1;
		char stx = '\x02';
		char etx = '\x03';
		auto clientInstance = static_cast<ClientBase*>(threadId);
		while (clientInstance->ConnectionActive()) {
			if (result <= 0) {
				break;
			}
			pthread_mutex_lock(&clientInstance->writeList_mutex);
			if (clientInstance->writeList.empty()) {
				pthread_cond_wait(&clientInstance->writeList_cond, &clientInstance->writeList_mutex);
			}
			std::vector<ResponseContainer> batch;
			while (!clientInstance->writeList.empty()) {
				batch.push_back(clientInstance->writeList.front());
				clientInstance->writeList.pop();
			}
			pthread_mutex_unlock(&clientInstance->writeList_mutex);

			if (!clientInstance->isShuttingDown && !clientInstance->errorOccured) {
				std::string xmlPayload = XmlRequest::CreateAllRequests(batch);
				if (xmlPayload.empty()) {
					continue;
				}
				result = clientInstance->write(&stx, sizeof(stx));
				if (result == -1) break;
				result = clientInstance->write(xmlPayload.c_str(), static_cast<int>(xmlPayload.size()));
				if (result == -1) break;
				result = clientInstance->write(&etx, sizeof(etx));
				if (result == -1) break;
			}
		}
		clientInstance->Terminate(false, false);
		pthread_exit(nullptr);
		return nullptr;
	}

	int ClientBase::write(const char* buffer, int size) {
		if (!sslEnabled) {
			return send(_socket, buffer, size, 0);
		}
		return BIO_write(bio, buffer, size);
	}

	void* ClientBase::read(void* threadId) {
		std::vector<char> delimiters;
		delimiters.push_back('\x02');
		delimiters.push_back('\x03');

		std::vector<char> startMarkers;
		startMarkers.push_back('\x02');

		std::vector<char> dataBuffer;
		std::stringstream accumulator;
		char incoming_buffer[8190];
		int bytesReceived = 0;

		auto clientInstance = static_cast<ClientBase*>(threadId);
		while (!clientInstance->isShuttingDown && !clientInstance->errorOccured) {
			bytesReceived = clientInstance->read(incoming_buffer, 4095);
			if (bytesReceived > 0) {
				AppendBuffer(dataBuffer, incoming_buffer, bytesReceived);
			}
			else {
				break;
			}

			accumulator << std::string(dataBuffer.begin(), dataBuffer.end());
			std::string rawInput = accumulator.str();
			accumulator.str("");

			int stxPosition = rawInput.find('\x02');
			int etxPosition = -1;

			while (stxPosition >= 0) {
				etxPosition = FindFirstMatch(rawInput, delimiters, stxPosition + 1);
				if (etxPosition == -1) {
					break;
				}
				if (rawInput[etxPosition] == '\x03') {
					pthread_mutex_lock(&clientInstance->readList_mutex);
					clientInstance->readList.push(rawInput.substr(stxPosition + 1, etxPosition - stxPosition - 1));
					pthread_cond_broadcast(&clientInstance->readList_cond);
					pthread_mutex_unlock(&clientInstance->readList_mutex);
				}
				stxPosition = FindFirstMatch(rawInput, startMarkers, etxPosition);
			}

			if (stxPosition == -1 && etxPosition == -1) {
				dataBuffer.clear();
			}
			else if (etxPosition >= 0) {
				std::string processedPart = rawInput.substr(0, etxPosition + 1);
				dataBuffer.erase(dataBuffer.begin(), dataBuffer.begin() + processedPart.size());
			}
			else if (stxPosition > 0) {
				std::string prefix = rawInput.substr(0, stxPosition);
				dataBuffer.erase(dataBuffer.begin(), dataBuffer.begin() + prefix.size());
			}
		}
		clientInstance->Terminate(false, false);
		pthread_exit(nullptr);
		return nullptr;
	}

	int ClientBase::read(char* buffer, int bufferSize) {
		if (!sslEnabled) {
			return recv(_socket, buffer, bufferSize, 0);
		}
		return BIO_read(bio, buffer, bufferSize);
	}

	void* ClientBase::process(void* threadId) {
		auto clientInstance = static_cast<ClientBase*>(threadId);
		std::vector<std::string> pendingMessages;
		while (clientInstance->ConnectionActive()) {
			for (const auto& message : pendingMessages) {
				clientInstance->processMessages(message);
			}
			pendingMessages.clear();

			pthread_mutex_lock(&clientInstance->readList_mutex);
			if (clientInstance->readList.empty()) {
				pthread_cond_wait(&clientInstance->readList_cond, &clientInstance->readList_mutex);
			}
			pthread_mutex_unlock(&clientInstance->readList_mutex);

			while (!clientInstance->readList.empty()) {
				pendingMessages.push_back(clientInstance->readList.front());
				clientInstance->readList.pop();
			}
		}
		clientInstance->Terminate(false, false);
		pthread_exit(nullptr);
		return nullptr;
	}

	void ClientBase::clearDataStructures() {
		pthread_mutex_lock(&readList_mutex);
		FlushQueue(readList);
		pthread_cond_broadcast(&readList_cond);
		pthread_mutex_unlock(&readList_mutex);

		pthread_mutex_lock(&writeList_mutex);
		FlushQueue(writeList);
		pthread_cond_broadcast(&writeList_cond);
		pthread_mutex_unlock(&writeList_mutex);
	}
#pragma endregion 
}

