#include <vector>
using namespace std;

// Compute product of array except self using two-pass approach
class Solution {
public:
    vector<int> computeProduct(vector<int>& inputArray) {
        vector<int> result;
        int length = inputArray.size(), runningProduct = 1;

        // First pass: store prefix products
        for(int index = 0; index < length; ++index) {
            result.push_back(runningProduct);
            runningProduct *= inputArray[index];
        }

        // Reset running product for suffix calculation
        runningProduct = 1;

        // Second pass: multiply with suffix products
        for(int position = length - 1; position >= 0; --position) {
            result[position] *= runningProduct;
            runningProduct *= inputArray[position];
        }

        return result;
    }
};

