// Windows Universal Application is a unique platform where Microsoft restricts access to many system APIs.
// Apps can only access information about the current display and window, not all connected displays.
// DisplayInformation provides full display metrics only at startup; later calls return only window size.
// Therefore, DeviceManagerImpl captures all display data once during initialization.
// On changes to display properties (currently only RawDpiX/Y are monitored), it updates raw DPI values
// while keeping the original display dimensions cached.
DeviceManagerImpl::DeviceManagerImpl(DeviceManager* manager, Private::MainDispatcher* dispatcher)
    : deviceManager(manager)
    , mainDispatcher(dispatcher)
{
    using ::Windows::UI::ViewManagement::ApplicationView;
    using ::Windows::Graphics::Display::DisplayInformation;

    ApplicationView ^ appView = ApplicationView::GetForCurrentView();
    DisplayInformation ^ dispInfo = DisplayInformation::GetForCurrentView();

    ::Windows::Foundation::Rect bounds = appView->VisibleBounds;
    float32 scaleFactor = static_cast<float32>(dispInfo->RawPixelsPerViewPixel);

    displayInfo.systemId = 0;
    displayInfo.name = "primary"; // Default name since DisplayInformation doesn't expose display names
    displayInfo.rawDpiX = dispInfo->RawDpiX;
    displayInfo.rawDpiY = dispInfo->RawDpiY;
    displayInfo.rect.x = bounds.X;
    displayInfo.rect.y = bounds.Y;
    displayInfo.rect.dx = bounds.Width * scaleFactor;
    displayInfo.rect.dy = bounds.Height * scaleFactor;

    deviceManager->displays.push_back(displayInfo);
}

void DeviceManagerImpl::UpdateDisplayConfig()
{
    using ::Windows::UI::ViewManagement::ApplicationView;
    using ::Windows::Graphics::Display::DisplayInformation;

    DisplayInformation ^ currentDispInfo = DisplayInformation::GetForCurrentView();

    if (displayInfo.rawDpiX != currentDispInfo->RawDpiX || 
        displayInfo.rawDpiY != currentDispInfo->RawDpiY)
    {
        displayInfo.rawDpiX = currentDispInfo->RawDpiX;
        displayInfo.rawDpiY = currentDispInfo->RawDpiY;

        DisplayInfo* updatedInfo = new DisplayInfo[1];
        *updatedInfo = displayInfo;

        mainDispatcher->PostEvent(MainDispatcherEvent::CreateDisplayConfigChangedEvent(updatedInfo, 1));
    }
}

