UAugmentaReceiver::UAugmentaReceiver()
{
}

UAugmentaReceiver::~UAugmentaReceiver()
{
	Disconnect();
	TrackedObjects.Reset();
	AdditionalObjectData.Reset();
}

void UAugmentaReceiver::Connect(FString HostAddress, int32 PortNumber)
{
	if (OscServerInstance) return;
	OscServerInstance = UOSCManager::CreateOscServer(HostAddress, PortNumber, false, true, "AugmentaOscListener");
	OscServerInstance->OnOscPacketReceived.AddDynamic(this, &UAugmentaReceiver::HandleIncomingMessage);
}

void UAugmentaReceiver::Disconnect()
{
	if (OscServerInstance && OscServerInstance->IsValidLowLevel())
	{
		OscServerInstance->Shutdown(); // Ensure server is stopped before destruction
		OscServerInstance->ConditionalBeginDestroy();
		OscServerInstance = nullptr;
	}
}

UAugmentaReceiver* UAugmentaReceiver::CreateNewReceiver(FString HostAddress, int32 PortNumber)
{
	UAugmentaReceiver* Instance = NewObject<UAugmentaReceiver>();
	Instance->Connect(HostAddress, PortNumber);
	return Instance;
}

bool UAugmentaReceiver::IsConnected() const
{
	return (OscServerInstance && OscServerInstance->IsValidLowLevel() && OscServerInstance->IsRunning());
}

