void UAugmentaReceiver::HandleIncomingMessage(const FOSCMessage& Message, const FString& SourceIP, int32 Port)
{
	const FOSCAddress Address = Message.GetAddress();
	const FString FirstSegment = Address.GetContainer(0);
	const FString SecondSegment = Address.GetContainer(1);
	const FString Action = Address.GetMethod();

	// Validate message type
	if (FirstSegment == ObjectContainerName)
	{
		if (SecondSegment.IsEmpty())
		{
			const bool IsEnter = Action == ObjectEnterAction;
			if (IsEnter || Action == ObjectUpdateAction)
			{
				ProcessPersonUpdate(Message, IsEnter);
			}
			else if (Action == ObjectExitAction)
			{
				ProcessPersonRemoval(Message);
			}
		}
		else if (Action == ObjectExtraAction)
		{
			const bool IsEnter = SecondSegment == ObjectEnterAction;
			if (IsEnter || SecondSegment == ObjectUpdateAction)
			{
				ProcessExtraUpdate(Message, IsEnter);
			}
			else if (SecondSegment == ObjectExitAction)
			{
				ProcessExtraRemoval(Message);
			}
		}
	}
	else if (Action == SceneAction)
	{
		ProcessSceneUpdate(Message);
	}
	else if (Action == VideoOutputAction)
	{
		ProcessVideoConfigUpdate(Message);
	}
}

void UAugmentaReceiver::ProcessSceneUpdate(const FOSCMessage& Message)
{
	UOSCManager::GetInt32(Message, 0, SceneData.CurrentTime);
	UOSCManager::GetInt32(Message, 1, SceneData.PersonCount);
	UOSCManager::GetFloat(Message, 2, SceneData.SceneDimensions.X);
	UOSCManager::GetFloat(Message, 3, SceneData.SceneDimensions.Y);
	OnSceneChanged.Broadcast(SceneData);
}

void UAugmentaReceiver::ProcessPersonUpdate(const FOSCMessage& Message, bool bIsEntering)
{
	int32 PersonId = -1;
	UOSCManager::GetInt32(Message, 1, PersonId);

	FAugmentaPerson Person = TrackedObjects.FindOrAdd(PersonId);

	Person.Pid = PersonId;
	UOSCManager::GetInt32(Message, 0, Person.FrameNumber);
	UOSCManager::GetInt32(Message, 2, Person.ObjectId);
	UOSCManager::GetFloat(Message, 3, Person.Age);
	UOSCManager::GetFloat(Message, 4, Person.Position.X);
	UOSCManager::GetFloat(Message, 5, Person.Position.Y);
	UOSCManager::GetFloat(Message, 6, Person.Movement.X);
	UOSCManager::GetFloat(Message, 7, Person.Movement.Y);
	UOSCManager::GetFloat(Message, 8, Person.OrientationAngle);
	UOSCManager::GetFloat(Message, 9, Person.BoundingBoxOrigin.X);
	UOSCManager::GetFloat(Message, 10, Person.BoundingBoxOrigin.Y);
	UOSCManager::GetFloat(Message, 11, Person.BoundingBoxSize.X);
	UOSCManager::GetFloat(Message, 12, Person.BoundingBoxSize.Y);
	UOSCManager::GetFloat(Message, 13, Person.BoundingBoxRotation);
	UOSCManager::GetFloat(Message, 14, Person.BodyHeight);

	TrackedObjects[PersonId] = Person;

	if (bIsEntering)
	{
		OnPersonEntered.Broadcast(Person);
	}
	else
	{
		OnPersonUpdated.Broadcast(Person);
	}
}

void UAugmentaReceiver::ProcessPersonRemoval(const FOSCMessage& Message)
{
	int32 PersonId = -1;
	UOSCManager::GetInt32(Message, 1, PersonId);

	FAugmentaPerson RemovedPerson;
	TrackedObjects.RemoveAndCopyValue(PersonId, RemovedPerson);
	OnPersonLeaving.Broadcast(RemovedPerson);
}

void UAugmentaReceiver::ProcessVideoConfigUpdate(const FOSCMessage& Message)
{
	UOSCManager::GetFloat(Message, 0, VideoStreamConfig.Offset.X);
	UOSCManager::GetFloat(Message, 1, VideoStreamConfig.Offset.Y);
	UOSCManager::GetFloat(Message, 2, VideoStreamConfig.Size.X);
	UOSCManager::GetFloat(Message, 3, VideoStreamConfig.Size.Y);
	UOSCManager::GetInt32(Message, 4, VideoStreamConfig.Resolution.X);
	UOSCManager::GetInt32(Message, 5, VideoStreamConfig.Resolution.Y);
	OnVideoConfigChanged.Broadcast(VideoStreamConfig);
}

void UAugmentaReceiver::ProcessExtraUpdate(const FOSCMessage& Message, bool bIsEntering)
{
	int32 ObjectId = -1;
	UOSCManager::GetInt32(Message, 1, ObjectId);

	FAugmentaObjectExtra Extra = AdditionalObjectData.FindOrAdd(ObjectId);

	Extra.Id = ObjectId;
	UOSCManager::GetInt32(Message, 0, Extra.FrameNumber);
	UOSCManager::GetInt32(Message, 2, Extra.ObjectId);
	UOSCManager::GetFloat(Message, 3, Extra.TopPoint.X);
	UOSCManager::GetFloat(Message, 4, Extra.TopPoint.Y);
	UOSCManager::GetFloat(Message, 5, Extra.DistanceToSensor);
	UOSCManager::GetFloat(Message, 6, Extra.Reflectance);

	AdditionalObjectData[ObjectId] = Extra;

	if (bIsEntering)
	{
		OnExtraDataAdded.Broadcast(Extra);
	}
	else
	{
		OnExtraDataModified.Broadcast(Extra);
	}
}

void UAugmentaReceiver::ProcessExtraRemoval(const FOSCMessage& Message)
{
	int32 ObjectId = -1;
	UOSCManager::GetInt32(Message, 1, ObjectId);

	FAugmentaObjectExtra RemovedExtra;
	AdditionalObjectData.RemoveAndCopyValue(ObjectId, RemovedExtra);
	OnExtraDataRemoved.Broadcast(RemovedExtra);
}

