//---------------------------------------------------------------------
// optimized copy for various sizes
//---------------------------------------------------------------------
static INLINE void memmove_sse2_block16(void *target, const void *origin) {
	__m128i reg0 = _mm_loadu_si128(((const __m128i*)origin) + 0);
	_mm_storeu_si128(((__m128i*)target) + 0, reg0);
}
static INLINE void memmove_sse2_block32(void *target, const void *origin) {
	__m128i reg0 = _mm_loadu_si128(((const __m128i*)origin) + 0);
	__m128i reg1 = _mm_loadu_si128(((const __m128i*)origin) + 1);
	_mm_storeu_si128(((__m128i*)target) + 0, reg0);
