#include <vector>
#include <climits>
#include <algorithm>

int hourglassSum(std::vector<std::vector<int>> grid) {

    int nRows = grid.size();
    int nCols = grid[0].size();

    if (nRows < 3 || nCols < 3) {
        return -1;
    }

    int best_sum = INT_MIN;
    for (int row = 0; row < nRows - 2; ++row) {
        for (int col = 0; col < nCols - 2; ++col) {

            int current_sum = (grid[row][col] + 
                               grid[row][col + 1] + 
                               grid[row][col + 2] + 
                               grid[row + 1][col + 1] + 
                               grid[row + 2][col] + 
                               grid[row + 2][col + 1] + 
                               grid[row + 2][col + 2]);

            best_sum = std::max(best_sum, current_sum);
        }
    }
    return best_sum;
}

