// Total number of validation steps in token test sequence
static int totalValidations = 10;

class SiteHandlerSoapToken : public SiteHandlerSoap
{
public:
    bool Handle(SOAPMessage* p_msg);
private:
    void ValidateSecurityContext(SOAPMessage* p_message);
};

bool
SiteHandlerSoapToken::Handle(SOAPMessage* p_msg)
{
    // Decrement global validation counter
    --totalValidations;
    ValidateSecurityContext(p_msg);
    return true;
}

void 
SiteHandlerSoapToken::ValidateSecurityContext(SOAPMessage* p_message)
{
    HANDLE   hFile         = NULL;
    HANDLE   clientToken   = p_message->GetAccessToken();
    DWORD    bufferSize    = 0;
    HANDLE   serverToken   = NULL;
    int      failureCount  = 0;
    CString  filePath      = WebConfig::GetExePath() + L"FileOwner.txt";
    CString  logBuffer;

    // Verify presence of access token
    if(clientToken == NULL)
    {
        qprintf("Token validation: No authenticated context present       : FAIL\n");
        xerror();
        ++failureCount;
        goto FINALIZE;
    }
    --totalValidations;

    // Acquire server-side thread or process token
    if(!OpenThreadToken(GetCurrentThread(), MAXIMUM_ALLOWED, TRUE, &serverToken))
    {
        if(!OpenProcessToken(GetCurrentProcess(), MAXIMUM_ALLOWED, &serverToken))
        {
            qprintf("OpenProcessToken failed                                 : FAIL\n");
            xprintf("Error code 0x%lx\n", GetLastError());
            ++failureCount;
            xerror();
            goto FINALIZE;
        }
    }
    --totalValidations;

    logBuffer += L"\nPRIMARY SERVER TOKEN\n";
    xprintf("Analyzing primary server token...\n");

    if(!DumpToken(logBuffer, serverToken))
    {
        qprintf("DumpTokenInformation for server token failed           : FAIL\n");
        CloseHandle(serverToken);
        xerror();
        ++failureCount;
        goto FINALIZE;
    }
    --totalValidations;
    CloseHandle(serverToken);
    logBuffer += L"\n\n";

    // Analyze incoming HTTP token
    xprintf("Processing HTTP client token...\n");
    logBuffer += L"CLIENT HTTP TOKEN\n";
    DumpToken(logBuffer, clientToken);

    // Query required buffer size for TokenOwner info
    GetTokenInformation(clientToken, TokenOwner, NULL, 0, &bufferSize);
    if(bufferSize == 0)
    {
        qprintf("Unable to retrieve token owner information              : FAIL\n");
        xerror();
        ++failureCount;
        goto FINALIZE;
    }
    --totalValidations;

    // Attempt impersonation of logged-on user
    if(ImpersonateLoggedOnUser(clientToken) == FALSE)
    {
        qprintf("Failed to impersonate logged-on user via token          : FAIL\n");
        xerror();
        ++failureCount;
        goto FINALIZE;
    }
    --totalValidations;

    // Try creating a file under impersonated context
    hFile = CreateFile(filePath,
                       GENERIC_READ | GENERIC_WRITE,
                       FILE_SHARE_READ | FILE_SHARE_WRITE,
                       nullptr,
                       CREATE_ALWAYS,
                       FILE_ATTRIBUTE_NORMAL,
                       nullptr);

    if(hFile == INVALID_HANDLE_VALUE)
    {
        // Common error codes: 1307 (INVALID_OWNER), 1368 (CANNOT_IMPERSONATE), 1346 (BAD_IMPERSONATION_LEVEL)
        xerror();
        int errCode = GetLastError();
        qprintf("Failed to create test file for token owner              : FAIL\n");
        xprintf("ERROR %d : %s\n", errCode, GetLastErrorAsString(errCode).GetString());
    }
    else
    {
        DWORD bytesWritten = 0;
        CString soapMsg = p_message->GetSoapMessage();
        soapMsg.Replace(L"\n", L"\r\n");

        if(WriteFile(hFile, soapMsg.GetString(), soapMsg.GetLength(), &bytesWritten, nullptr) == FALSE)
        {
            qprintf("Write operation failed on SOAP message                  : FAIL\n");
            xerror();
            ++failureCount;
        }
        else
        {
            --totalValidations;
            xprintf("SOAP payload saved to: %s\n", (LPCTSTR)filePath);
        }

        logBuffer.Replace(L"\n", L"\r\n");
        if(WriteFile(hFile, logBuffer.GetString(), logBuffer.GetLength(), &bytesWritten, nullptr) == FALSE)
        {
            qprintf("Write operation failed on token access log              : FAIL\n");
            xerror();
            ++failureCount;
        }
        else
        {
            --totalValidations;
            xprintf("Token access log saved to: %s\n", (LPCTSTR)filePath);
        }

        CloseHandle(hFile);
    }

FINALIZE:
    p_message->Reset();
    p_message->SetParameter(L"ValidationStatus", failureCount ? L"FAILED" : L"PASSED");

    qprintf("Token processing for incoming request                    : %s\n", failureCount ? L"FAILED" : L"PASSED");
}

int 
TestMarlinServer::TestToken()
{
    int result = 0;
    m_doDetails = false;

    CString endpointUrl(L"/MarlinTest/TestToken/");
    xprintf("TESTING TOKEN HANDLING CAPABILITIES OF HTTP SERVER\n");
    xprintf("===================================================\n");

    HTTPSite* site = m_httpServer->CreateSite(PrefixType::URLPRE_Strong, false, m_inPortNumber, endpointUrl);
    if(site)
    {
        qprintf("HTTPSite DACL token testing : PASS : %s\n", site->GetPrefixURL().GetString());
    }
    else
    {
        ++result;
        xerror();
        qprintf("ERROR: Unable to create HTTP site at: %s\n", (LPCTSTR)endpointUrl);
        return result;
    }

    site->SetHandler(HTTPCommand::http_post, new SiteHandlerSoapToken());
    site->AddContentType(L"", L"text/xml");
    site->AddContentType(L"xml", L"application/soap+xml");

    site->SetAuthenticationScheme(L"NTLM");
    site->SetAuthenticationNTLMCache(true);

    if(site->StartSite())
    {
        xprintf("Site successfully started: %s\n", endpointUrl.GetString());
    }
    else
    {
        ++result;
        xerror();
        qprintf("ERROR STARTING SITE: %s\n", (LPCTSTR)endpointUrl);
    }

    return result;
}

int
TestMarlinServer::AfterTestToken()
{
    qprintf("Authentication token capability verification               : %s\n", totalValidations > 0 ? L"INCOMPLETE" : L"COMPLETED");
    return totalValidations > 0;
}

