// Test that includes() correctly checks for candidate presence and absence
TEST(Candidates, includes)
{
    for (int val = 1; val <= 9; ++val)
    {
        EXPECT_TRUE(Candidates::includes(Candidates::fromValue(val), val));
        EXPECT_FALSE(Candidates::includes((~Candidates::fromValue(val)) & Candidates::ALL, val));
    }
}

// Test that isSolved() returns true only for single candidates
TEST(Candidates, isSolved)
{
    for (int val = 1; val <= 9; ++val)
    {
        EXPECT_TRUE(Candidates::isSolved(Candidates::fromValue(val)));
    }
    EXPECT_FALSE(Candidates::isSolved(Candidates::ALL));
}

// Test that isBivalue() correctly identifies bivalue candidates
TEST(Candidates, isBivalue)
{
    for (int first = 1; first <= 9; ++first)
    {
        for (int second = 1; second <= 9; ++second)
        {
            if (first == second)
                EXPECT_FALSE(Candidates::isBivalue(Candidates::fromValue(first)));
            else
                EXPECT_TRUE(Candidates::isBivalue(Candidates::fromValue(first) | Candidates::fromValue(second)));
        }
    }
    EXPECT_FALSE(Candidates::isBivalue(Candidates::ALL));
}

// Test that value() correctly extracts the integer value from a candidate set
TEST(Candidates, value_fromValue)
{
    EXPECT_EQ(Candidates::value(Candidates::NONE), 0);
    for (int val = 1; val <= 9; ++val)
    {
        EXPECT_EQ(Candidates::value(Candidates::fromValue(val)), val);
    }
}

// Test that values() returns the correct vector of integers for each candidate set
TEST(Candidates, values)
{
    EXPECT_EQ(Candidates::values(Candidates::NONE), std::vector<int>());
    for (Candidates::Type mask = 0; mask <= Candidates::ALL; ++mask)
    {
        std::vector<int> expected;
        for (int idx = 1; idx <= 9; ++idx)
        {
            if ((mask & (1 << idx)) != 0)
                expected.push_back(idx);
        }
        EXPECT_EQ(Candidates::values(mask), expected);
    }
}

// Test that count() correctly counts the number of set bits in a candidate set
TEST(Candidates, count)
{
    for (Candidates::Type candSet = 0; candSet <= Candidates::ALL; candSet += 2)
    {
        Candidates::Type temp = candSet;
        int numSet = 0;
        while (temp != 0)
        {
            temp >>= 1;
            if (temp & 1)
                ++numSet;
        }
        EXPECT_EQ(Candidates::count(candSet), numSet);
    }
}

