WavReaderTester::WavReaderTester() {
    inputDirectory = nullptr;
    audioSamples = nullptr;
    shortSamples = nullptr;
    readerInstance = new WavReader();
}

WavReaderTester::~WavReaderTester() {
    if (readerInstance) {
        delete readerInstance;
        readerInstance = nullptr;
    }
    if (audioSamples) {
        free(audioSamples);
        audioSamples = nullptr;
    }
    if (shortSamples) {
        free(shortSamples);
        shortSamples = nullptr;
    }
}

bool WavReaderTester::setup(const char *directoryPath) {
    //printf("Setting up WavReaderTester.\n\n");

    // Validate directory path
    if (!directoryPath) {
        fprintf(stderr, "Error: Input directory path is NULL.\n");
        return false;
    }

    char tempPath[MAX_PATH_LENGTH];
    sprintf(tempPath, "%s/WavReaderTesterTempFile.txt", directoryPath);
    FILE* fp = fopen(tempPath, "w");
    if (!fp) {
        fprintf(stderr, "Error: Unable to open temp file at path:\n%s.\n", tempPath);
        return false;
    }

    if (remove(tempPath) != 0) {
        fprintf(stderr, "Error: Unable to remove test file created to validate directory path.\n");
        fclose(fp);
        return false;
    }
    fclose(fp);

    this->inputDirectory = directoryPath;

    if (audioSamples) {
        free(audioSamples);
        audioSamples = nullptr;
    }

    if (shortSamples) {
        free(shortSamples);
        shortSamples = nullptr;
    }

    return true;
}

bool WavReaderTester::executeTests() {
    printf("Executing WavReaderTest.\n");

    // Reading files all at once
    printf("    Testing full-file read...\n");
    for (int idx = 0; idx < NUM_FILE_PARAM_SETS; idx++) {
        testFullRead(&inFileParamSets[idx]);
    }

    // Read files incrementally
    printf("    Testing incremental read...\n");
    for (int idx = 0; idx < NUM_FILE_PARAM_SETS; idx++) {
        testIncrementalRead(&inFileParamSets[idx]);
    }

    // Read files into int16 arrays
    printf("    Testing int16 array read...\n");
    for (int idx = 0; idx < NUM_FILE_PARAM_SETS; idx++) {
        if (!testToInt16Array(&inFileParamSets[idx])) {
            fprintf(stderr, "executeTests(): Error during int16 array test.\n");
            return false;
        }
    }

    printf("Completed WavReaderTest.\n\n");
    return true;
}

bool WavReaderTester::testFullRead(const InFileParamSetDef* params) {
    const char* filename = params->fileName;
    char fullPath[MAX_PATH_LENGTH];
    sprintf(fullPath,
            "%s/%s",
            inputDirectory,
            filename);

    if (!readerInstance->initialize(fullPath)) {
        fprintf(stderr, "testFullRead(): Failed to initialize reader.\n");
        return false;
    }

    if (!readerInstance->prepareToRead()) {
        fprintf(stderr, "testFullRead(): Failed to prepare reader.\n");
        return false;
    }

    // Allocate memory for sample data
    uint32_t requiredSize = readerInstance->getSampleDataSize();
    if (audioSamples) {
        free(audioSamples);
        audioSamples = nullptr;
    }
    audioSamples = (uint8_t*) malloc(requiredSize);

    if (!readerInstance->readData(audioSamples, requiredSize)) {
        fprintf(stderr, "testFullRead(): Failed to read data.\n");
        return false;
    }

    if (!readerInstance->finishReading()) {
        fprintf(stderr, "testFullRead(): Failed to finalize reading.\n");
        return false;
    }

    // Validate results
    if (!checkValidation(params, VALIDATION_SOURCE_SAMPLEDATA)) {
        fprintf(stderr, "testFullRead(): Validation failed.\n");
        return false;
    }

    return true;
}

bool WavReaderTester::testIncrementalRead(const InFileParamSetDef* params) {
    const char* filename = params->fileName;
    const uint32_t channels = params->numChannels;
    const uint32_t depth = params->byteDepth;

    char fullPath[MAX_PATH_LENGTH];
    sprintf(fullPath,
            "%s/%s",
            inputDirectory,
            filename);

    if (!readerInstance->initialize(fullPath)) {
        fprintf(stderr, "testIncrementalRead(): Initialization error.\n");
        return false;
    }

    if (!readerInstance->prepareToRead()) {
        fprintf(stderr, "testIncrementalRead(): Prepare-to-read error.\n");
        return false;
    }

    // Allocate buffer
    const uint32_t totalBytes = readerInstance->getNumSamples() * readerInstance->getNumChannels() * readerInstance->getByteDepth();
    if (audioSamples) {
        free(audioSamples);
        audioSamples = nullptr;
    }
    audioSamples = (uint8_t*) malloc(totalBytes);

    const uint32_t chunkSize = channels * depth * 1; // Block-aligned size
    uint8_t chunk[chunkSize];

    uint32_t offset = 0;
    while (offset < totalBytes) {
        const uint32_t remaining = totalBytes - offset;
        const uint32_t toRead = (remaining < chunkSize) ? remaining : chunkSize;

        if (!readerInstance->readData(chunk, toRead)) {
            fprintf(stderr, "testIncrementalRead(): Data read error.\n");
            return false;
        }

        for (int k = 0; k < (int)toRead; k++) {
            audioSamples[offset] = chunk[k];
            offset++;
        }
    }

    if (!readerInstance->finishReading()) {
        fprintf(stderr, "testIncrementalRead(): Finalization error.\n");
        return false;
    }

    if (!checkValidation(params, VALIDATION_SOURCE_SAMPLEDATA)) {
        fprintf(stderr, "testIncrementalRead(): Validation failed.\n");
        return false;
    }

    return true;
}

bool WavReaderTester::testToInt16Array(const InFileParamSetDef* params) {
    const char* filename = params->fileName;

    char fullPath[MAX_PATH_LENGTH];
    sprintf(fullPath,
            "%s/%s",
            inputDirectory,
            filename);

    if (!readerInstance->initialize(fullPath)) {
        fprintf(stderr, "testToInt16Array(): Reader initialization failed.\n");
        return false;
    }

    if (!readerInstance->prepareToRead()) {
        fprintf(stderr, "testToInt16Array(): Reader preparation failed.\n");
        return false;
    }

    // Allocate int16 buffer
    const size_t shortBufSize = readerInstance->getNumSamples() * readerInstance->getNumChannels() * 2; // 2 bytes per int16
    if (shortSamples) {
        free(shortSamples);
        shortSamples = nullptr;
    }
    shortSamples = (int16_t*) malloc(shortBufSize);

    if (!readerInstance->readDataToInt16s(shortSamples, readerInstance->getNumSamples())) {
        fprintf(stderr, "testToInt16Array(): Int16 read error.\n");
        return false;
    }

    if (!readerInstance->finishReading()) {
        fprintf(stderr, "testToInt16Array(): Finalization error.\n");
        return false;
    }

    if (!checkValidation(params, VALIDATION_SOURCE_INT16SAMPLES)) {
        fprintf(stderr, "testToInt16Array(): Validation failed.\n");
        return false;
    }

    return true;
}

bool WavReaderTester::checkValidation(const InFileParamSetDef* params, ValidationSource source) {
    const char* filename = params->fileName;

    // Metadata checks
    if (params->numChannels != readerInstance->getNumChannels()) {
        fprintf(stderr, "Error: numChannels mismatch for %s.\n", filename);
        return false;
    }

    if (params->byteDepth != readerInstance->getByteDepth()) {
        fprintf(stderr, "Error: byteDepth mismatch for %s.\n", filename);
        return false;
    }

    if (params->samplesAreInts != readerInstance->getSamplesAreInts()) {
        fprintf(stderr, "Error: samplesAreInts mismatch for %s.\n", filename);
        return false;
    }

    // Content validation: verify ~440Hz sine wave in both channels
    int16_t ch1 = 0;
    int16_t ch2 = 0;
    int16_t prevCh1 = 0;
    int16_t prevCh2 = 0;
    uint32_t zeroCrossCh1 = 0;
    uint32_t zeroCrossCh2 = 0;

    uint32_t totalSamples = readerInstance->getNumSamples();
    uint32_t numChannels = readerInstance->getNumChannels();
    uint32_t totalBytes = readerInstance->getNumSamples() * readerInstance->getNumChannels() * readerInstance->getByteDepth();

    for (uint32_t n = 0; n < totalSamples; n++) {
        prevCh1 = ch1;
        prevCh2 = ch2;

        if (source == VALIDATION_SOURCE_SAMPLEDATA) {
            readerInstance->readInt16SampleFromArray(audioSamples,
                                                     totalBytes,
                                                     n,
                                                     ch1,
                                                     ch2);
        } else { // VALIDATION_SOURCE_INT16SAMPLES
            ch1 = shortSamples[n * numChannels];
            ch2 = (numChannels == 1) ? 0 : shortSamples[n * numChannels + 1];
        }

        if (prevCh1 < 0 && ch1 >= 0) zeroCrossCh1++;
        if (prevCh2 < 0 && ch2 >= 0) zeroCrossCh2++;
    }

    double duration = (double)totalSamples / (double)SAMPLE_RATE;
    double freqCh1 = (double)zeroCrossCh1 / duration;
    double freqCh2 = (double)zeroCrossCh2 / duration;

    double tolerance = 80.0;
    if (freqCh1 < SINE_FREQUENCY - tolerance || freqCh1 > SINE_FREQUENCY + tolerance) {
        fprintf(stderr, "Error: channel1 frequency (%.0fHz) out of acceptable range [%.0f±%.0f]Hz for %s.\n",
                ceil(freqCh1),
                SINE_FREQUENCY,
                tolerance,
                filename);
        return false;
    }

    if (numChannels == 2) {
        if (freqCh2 < SINE_FREQUENCY - tolerance || freqCh2 > SINE_FREQUENCY + tolerance) {
            fprintf(stderr, "Error: channel2 frequency (%.0fHz) out of acceptable range [%.0f±%.0f]Hz for %s.\n",
                    ceil(freqCh2),
                    SINE_FREQUENCY,
                    tolerance,
                    filename);
            return false;
        }
    }

    return true;
}

