PSContext2D_t* PSContext2DAllocate() {
  PSContext2D_t* context = (PSContext2D_t*) malloc(sizeof(PSContext2D_t));
  memset(context, 0, sizeof(PSContext2D_t));
  context->format = PSInterfaceImageData()->GetNativeImageDataFormat();
  return context;
}

void PSContext2DFree(PSContext2D_t* context) {
  if (context->graphic_2d) {
    PSInterfaceCore()->ReleaseResource(context->graphic_2d);
    context->graphic_2d = 0;
  }
  if (context->image) {
    PSInterfaceCore()->ReleaseResource(context->image);
    context->image = 0;
  }
  free(context);
}

// Process the incoming event for 2D context updates, returning non-zero
// if the event was handled.
int PSContext2DHandleEvent(PSContext2D_t* context, PSEvent* event) {
  switch(event->type) {
    case PSE_INSTANCE_DIDCHANGEVIEW: {
      struct PP_Rect bounds;
      PSInterfaceView()->GetRect(event->as_resource, &bounds);
      PSInterfaceCore()->ReleaseResource(context->graphic_2d);
      context->bound = 0;
      context->width = bounds.size.width;
      context->height = bounds.size.height;

      // Create a new opaque 2D graphics context with updated dimensions
      context->graphic_2d =
          PSInterfaceGraphics2D()->Create(PSGetInstanceId(), &bounds.size,
                                          PP_TRUE);

      // Bind the newly created context to the instance
      if (context->graphic_2d) {
        context->bound =
            PSInterfaceInstance()->BindGraphics(PSGetInstanceId(),
                                                context->graphic_2d);
      }

      // Discard any existing image resource to ensure fresh allocation later
      if (context->image) {
        PSInterfaceCore()->ReleaseResource(context->image);
        context->image = 0;
      }
      return 1;
    }
    default: break;
  }
  return 0;
}

// Acquire an image buffer for drawing operations, allocating one if necessary.
// Returns 1 on success, 0 otherwise.
int PSContext2DGetBuffer(PSContext2D_t* context) {
  if (!context->bound) return 0;

  // Reuse existing image if available
  if (context->image) return 1;

  PP_Size dimensions;
  dimensions.width = context->width;
  dimensions.height = context->height;

  // Allocate a new image resource without zero-initializing the memory
  PP_Resource image =
      PSInterfaceImageData()->Create(PSGetInstanceId(), context->format, &dimensions,
                                     PP_FALSE);
  if (0 == image) {
    PSInstance::GetInstance()->Error("Unable to create 2D image.\n");
    return 0;
  }

  // Retrieve image descriptor and map memory
  struct PP_ImageDataDesc info;
  PSInterfaceImageData()->Describe(image, &info);
  context->image = image;
  context->data = static_cast<uint32_t*>(PSInterfaceImageData()->Map(image));
  context->stride = info.stride;
  return 1;
}

// Commit current drawing buffer to the display by swapping buffers.
// Returns 1 on success, 0 otherwise.
int PSContext2DSwapBuffer(PSContext2D_t* context) {
  if (context->bound && context->image) {
    PSInterfaceImageData()->Unmap(context->image);
    PSInterfaceGraphics2D()->ReplaceContents(context->graphic_2d, context->image);
    PSInterfaceGraphics2D()->Flush(context->graphic_2d, PP_BlockUntilComplete());
    PSInterfaceCore()->ReleaseResource(context->image);
    context->image = 0;
    context->stride = 0;
    context->data = NULL;
    return 1;
  }
  return 0;
}

