// Enumerates all 16 operation codes for the CPU simulator
enum InstructionType {
  ADDR,
  ADDI,
  MULR,
  MULI,
  BANR,
  BANI,
  BORR,
  BORI,
  SETR,
  SETI,
  GTIR,
  GTRI,
  GTRR,
  EQIR,
  EQRI,
  EQRR,
};

// Contains all available operations in a vector
std::vector<InstructionType> ALL_INSTRUCTIONS({
    ADDR,
    ADDI,
    MULR,
    MULI,
    BANR,
    BANI,
    BORR,
    BORI,
    SETR,
    SETI,
    GTIR,
    GTRI,
    GTRR,
    EQIR,
    EQRI,
    EQRR,
});

// Represents a single operation with before/after states
struct OperationRecord {
  std::array<int, 4> initial_state;
  int instruction_code;
  int operand_a;
  int operand_b;
  int result_register;
  std::vector<InstructionType> possible_instructions;
  std::array<int, 4> final_state;
  OperationRecord() {}
};

// Represents an executable instruction
struct ExecutableCommand {
  InstructionType command;
  int source_value;
  int second_operand;
  int destination_register;
};

// Executes an instruction on the given register state
void execute_command(ExecutableCommand cmd, std::array<int, 4>& registers) {
  int op_a = cmd.source_value;
  int op_b = cmd.second_operand;
  int dest = cmd.destination_register;

  switch (cmd.command) {
    case ADDR:
      std::cout << "ADDR " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] + registers[op_b];
      break;
    case ADDI:
      std::cout << "ADDI " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] + op_b;
      break;
    case MULR:
      std::cout << "MULR " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] * registers[op_b];
      break;
    case MULI:
      std::cout << "MULI " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] * op_b;
      break;
    case BANR:
      std::cout << "BANR " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] & registers[op_b];
      break;
    case BANI:
      std::cout << "BANI " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] & op_b;
      break;
    case BORR:
      std::cout << "BORR " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] | registers[op_b];
      break;
    case BORI:
      std::cout << "BORI " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a] | op_b;
      break;
    case SETR:
      std::cout << "SETR " << op_a << " " << op_b << " " << dest;
      registers[dest] = registers[op_a];
      break;
    case SETI:
      std::cout << "SETI " << op_a << " " << op_b << " " << dest;
      registers[dest] = op_a;
      break;
    case GTIR: {
      bool condition_met = (op_a > registers[op_b]);
      registers[dest] = condition_met ? 1 : 0;
      break;
    }
    case GTRI: {
      bool condition_met = (registers[op_a] > op_b);
      registers[dest] = condition_met ? 1 : 0;
      break;
    }
    case GTRR: {
      bool condition_met = (registers[op_a] > registers[op_b]);
      registers[dest] = condition_met ? 1 : 0;
      break;
    }
    case EQIR: {
      bool condition_met = (op_a == registers[op_b]);
      registers[dest] = condition_met ? 1 : 0;
      break;
    }
    case EQRI: {
      bool condition_met = (registers[op_a] == op_b);
      registers[dest] = condition_met ? 1 : 0;
      break;
    }
    case EQRR: {
      bool condition_met = (registers[op_a] == registers[op_b]);
      registers[dest] = condition_met ? 1 : 0;
      break;
    }
  }

  std::cout << "  [";
  for (auto reg : registers) {
    std::cout << reg << ", ";
  }
  std::cout << "]\n";
}

// Checks if an operation behaves as expected for a given instruction type
bool matches_behavior(OperationRecord* record, InstructionType instruction_type) {
  // Verify unchanged registers remain the same
  for (int i = 0; i < 4; i++) {
    if (i != record->result_register) {
      assert(record->initial_state[i] == record->final_state[i]);
    }
  }

  switch (instruction_type) {
    case ADDR:
      return (record->initial_state[record->operand_a] +
              record->initial_state[record->operand_b]) ==
             record->final_state[record->result_register];
    case ADDI:
      return (record->initial_state[record->operand_a] + record->operand_b) ==
             record->final_state[record->result_register];
    case MULR:
      return (record->initial_state[record->operand_a] *
              record->initial_state[record->operand_b]) ==
             record->final_state[record->result_register];
    case MULI:
      return (record->initial_state[record->operand_a] * record->operand_b) ==
             record->final_state[record->result_register];
    case BANR:
      return (record->initial_state[record->operand_a] &
              record->initial_state[record->operand_b]) ==
             record->final_state[record->result_register];
    case BANI:
      return (record->initial_state[record->operand_a] & record->operand_b) ==
             record->final_state[record->result_register];
    case BORR:
      return (record->initial_state[record->operand_a] |
              record->initial_state[record->operand_b]) ==
             record->final_state[record->result_register];
    case BORI:
      return (record->initial_state[record->operand_a] | record->operand_b) ==
             record->final_state[record->result_register];
    case SETR:
      return record->initial_state[record->operand_a] ==
             record->final_state[record->result_register];
    case SETI:
      return record->operand_a == record->final_state[record->result_register];
    case GTIR: {
      bool condition_met = (record->operand_a > record->initial_state[record->operand_b]);
      return condition_met ? (record->final_state[record->result_register] == 1)
                     : (record->final_state[record->result_register] == 0);
    }
    case GTRI: {
      bool condition_met = (record->initial_state[record->operand_a] > record->operand_b);
      return condition_met ? (record->final_state[record->result_register] == 1)
                     : (record->final_state[record->result_register] == 0);
    }
    case GTRR: {
      bool condition_met = (record->initial_state[record->operand_a] >
                      record->initial_state[record->operand_b]);
      return condition_met ? (record->final_state[record->result_register] == 1)
                     : (record->final_state[record->result_register] == 0);
    }
    case EQIR: {
      bool condition_met =
          (record->operand_a == record->initial_state[record->operand_b]);
      return condition_met ? (record->final_state[record->result_register] == 1)
                     : (record->final_state[record->result_register] == 0);
    }
    case EQRI: {
      bool condition_met =
          (record->initial_state[record->operand_a] == record->operand_b);
      return condition_met ? (record->final_state[record->result_register] == 1)
                     : (record->final_state[record->result_register] == 0);
    }
    case EQRR: {
      bool condition_met = (record->initial_state[record->operand_a] ==
                      record->initial_state[record->operand_b]);
      return condition_met ? (record->final_state[record->result_register] == 1)
                     : (record->final_state[record->result_register] == 0);
    }
  }
  return false;
}

// Determines possible instruction types for an operation
std::set<InstructionType> determine_possible_instructions(OperationRecord* record) {
  std::set<InstructionType> possibilities;
  for (auto type : ALL_INSTRUCTIONS) {
    if (matches_behavior(record, type)) {
      possibilities.insert(type);
    }
  }
  return possibilities;
}

// Reads operation sequences from file
std::vector<OperationRecord*> load_operations() {
  std::ifstream data_file("16.1.input");
  std::regex before_pattern("Before: \\[(\\d+), (\\d+), (\\d+), (\\d+)\\]");
  std::regex instruction_pattern("(\\d+) (\\d+) (\\d+) (\\d+)");
  std::regex after_pattern("After:  \\[(\\d+), (\\d+), (\\d+), (\\d+)\\]");
  std::vector<OperationRecord*> records;
  std::string line;

  if (data_file.is_open()) {
    while (getline(data_file, line)) {
      OperationRecord* record = new OperationRecord();
      std::smatch match_result;

      assert((std::regex_search(line, match_result, before_pattern)));
      for (int idx = 1; idx <= 4; idx++) {
        record->initial_state[idx - 1] = std::stoi(match_result[idx].str());
      }

      assert((getline(data_file, line)));
      assert((std::regex_search(line, match_result, instruction_pattern)));
      record->instruction_code = std::stoi(match_result[1].str());
      record->operand_a = std::stoi(match_result[2].str());
      record->operand_b = std::stoi(match_result[3].str());
      record->result_register = std::stoi(match_result[4].str());

      assert((getline(data_file, line)));
      assert((std::regex_search(line, match_result, after_pattern)));
      for (int idx = 1; idx <= 4; idx++) {
        record->final_state[idx - 1] = std::stoi(match_result[idx].str());
      }

      records.push_back(record);
      getline(data_file, line);
    }
  }
  return records;
}

// Part one: identifies instruction mappings and counts candidates
std::map<int, InstructionType> analyze_operations(std::vector<OperationRecord*>& records) {
  int high_candidate_count = 0;
  std::multimap<int, InstructionType> instruction_candidates;
  int index = 0;

  for (auto record : records) {
    auto possible = determine_possible_instructions(record);

    if (possible.size() >= 3) {
      high_candidate_count++;
    }

    if (instruction_candidates.count(record->instruction_code) > 0) {
      auto range_start = instruction_candidates.equal_range(record->instruction_code).first;
      auto range_end = instruction_candidates.equal_range(record->instruction_code).second;

      while (range_start != range_end) {
        if (possible.count(range_start->second) != 1) {
          range_start = instruction_candidates.erase(range_start);
        } else {
          range_start++;
        }
      }
    } else {
      for (auto type : possible) {
        instruction_candidates.insert(std::make_pair(record->instruction_code, type));
      }
    }
  }

  std::cout << "Operations with more than 3 candidate instructions: " << high_candidate_count
            << "\n";

  std::map<int, InstructionType> final_mapping;
  while (instruction_candidates.size() > 0) {
    for (int i = 0; i < 16; i++) {
      if (instruction_candidates.count(i) == 1) {
        auto range = instruction_candidates.equal_range(i);
        InstructionType type = range.first->second;
        final_mapping[i] = type;
        instruction_candidates.erase(i);

        auto iterator = instruction_candidates.begin();
        while (iterator != instruction_candidates.end()) {
          if (iterator->second == type) {
            iterator = instruction_candidates.erase(iterator);
          } else {
            iterator++;
          }
        }
      }
    }
  }

  assert(instruction_candidates.size() == 0);
  return final_mapping;
}

// Part two: executes program with resolved instruction mapping
void run_program(std::map<int, InstructionType> mapping) {
  std::ifstream program_file("16.2.input");
  std::string line;
  std::regex instruction_regex("(\\d+) (\\d+) (\\d+) (\\d+)");
  std::array<int, 4> cpu_registers({0, 0, 0, 0});

  if (program_file.is_open()) {
    while (getline(program_file, line)) {
      ExecutableCommand command;
      std::smatch match_result;

      assert((std::regex_search(line, match_result, instruction_regex)));
      command.command = mapping[std::stoi(match_result[1].str())];
      command.source_value = std::stoi(match_result[2].str());
      command.second_operand = std::stoi(match_result[3].str());
      command.destination_register = std::stoi(match_result[4].str());

      execute_command(command, cpu_registers);
    }
  }

  std::cout << "Final value in register 0: " << cpu_registers[0] << "\n";
}

int main() {
  auto operation_records = load_operations();
  auto instruction_map = analyze_operations(operation_records);
  run_program(instruction_map);
}

