double BatReader::readBatVoltage(void) {
    double measured = (double)(analogRead(BAT_PIN) * ANA_REF) / 1024.0;
    if (measured > BAT_MAX) 
        return BAT_MAX;
    else 
        return measured;
}

// Calculate and return the battery percentage based on voltage
double BatReader::readBatPercent(void) {
    double result = (SLOPE * readBatVoltage()) - OFFSET;
    if (result < 0.0) 
        return 0.0;
    else 
        return result;
}

