DTint ContextSwitcher::exchange_context(uContext *dest, const uContext *src)
{
    if(get_machine_context(dest) == 0)
        assign_machine_context(src);
    return 0;
}

void ContextSwitcher::initialize_context(uContext *ucp, void (*callback)(void*), void *parameter)
{
#if DT3_CPU == DT3_INTEL && DT3_POINTER_SIZE == DT3_32_BIT
    ::memset(&ucp->uc_mcontext, 0, sizeof(ucp->uc_mcontext));
    DTuint *stack_ptr = (DTuint*)ucp->uc_stack_sp + ucp->uc_stack_ss/sizeof(void*);
    stack_ptr -= 1;
    stack_ptr = (DTuint*)((DTuint)stack_ptr - (DTuint)stack_ptr%16);	/* 16-align for OS X */
    *stack_ptr = (DTuint64) parameter;
    ucp->uc_mcontext.gregs[1] = *stack_ptr;
    *--stack_ptr = 0;		// return address
    ucp->uc_mcontext.gregs[15] = (DTuint)callback;    // eip
    ucp->uc_mcontext.gregs[18] = (DTuint)stack_ptr;      // esp
#elif DT3_CPU == DT3_INTEL && DT3_POINTER_SIZE == DT3_64_BIT
    ::memset(&ucp->uc_mcontext, 0, sizeof(ucp->uc_mcontext));
    DTuint64 *stack_ptr = (DTuint64*)ucp->uc_stack_sp + ucp->uc_stack_ss/sizeof(void*);
    stack_ptr -= 1;
    stack_ptr = (DTuint64*)((DTuint64)stack_ptr - (DTuint64)stack_ptr%16);	/* 16-align for OS X */
    *stack_ptr = (DTuint64) parameter;
    ucp->uc_mcontext.gregs[1] = *stack_ptr;
    *--stack_ptr = 0;	// return address
    ucp->uc_mcontext.gregs[20] = (DTuint64)callback;
    ucp->uc_mcontext.gregs[23] = (DTuint64)stack_ptr;
#elif DT3_CPU == DT3_ARM
    DTuint *stack_ptr;
    stack_ptr = (DTuint*)ucp->uc_stack_sp + ucp->uc_stack_ss/sizeof(void*);
    ucp->uc_mcontext.gregs[0] = (DTuint) parameter;
    ucp->uc_mcontext.gregs[13] = (DTuint)stack_ptr;
    ucp->uc_mcontext.gregs[14] = (DTuint)callback;
#else
    //#error Not available on this architecture yet!!
    ASSERT(false)
#endif
}

DTint ContextSwitcher::get_context(uContext*ucp)
{
    return get_machine_context( &(ucp->uc_mcontext) );
}

void ContextSwitcher::set_machine_context(const uContext*ucp)
{
    assign_machine_context( &(ucp->uc_mcontext) );
}
