namespace mio {

// Page size configuration: default 4KB, will be updated at runtime
int kPageSizeShift = 12;
int kPageSize = (1 << kPageSizeShift); // 4 KB
int kLargeSize = kPageSize / 4;
int kDefaultNativeCodeSize = 4 * kPageSize;
uintptr_t kPageAlignmentMask = -1;
int kNumberOfCpuCores = 1;

// Fill a memory region with repeated copies of 'zag', handling both aligned and partial bytes
template<class T>
inline void *FillMemoryWithPattern(const T zag, void *buffer, size_t byteCount) {
    static_assert(sizeof(zag) > 1 && sizeof(zag) <= 8, "T must be int16, int32, or int64");
    static_assert(std::is_integral<T>::value, "T must be an integral type");
    DCHECK_GE(byteCount, 0);

    void* originalBuffer = buffer;
    size_t elementCount = byteCount / sizeof(T);

    // Fill full elements
    while (elementCount--) {
        auto* currentElement = static_cast<T*>(buffer);
        *currentElement = zag;
        buffer = static_cast<void*>(currentElement + 1);
    }

    // Handle remaining bytes (less than sizeof(T))
    const uint8_t* patternBytes = reinterpret_cast<const uint8_t*>(&zag);
    size_t remainingBytes = byteCount % sizeof(T);

    while (remainingBytes--) {
        auto* currentByte = static_cast<uint8_t*>(buffer);
        *currentByte = *patternBytes++;
        buffer = static_cast<void*>(currentByte + 1);
    }

    return originalBuffer;
}

// Type-specific wrappers for common fill sizes
void *Fill16BitPattern(const uint16_t pattern, void *buffer, size_t byteCount) {
    return FillMemoryWithPattern<uint16_t>(pattern, buffer, byteCount);
}

void *Fill32BitPattern(const uint32_t pattern, void *buffer, size_t byteCount) {
    return FillMemoryWithPattern<uint32_t>(pattern, buffer, byteCount);
}

void *Fill64BitPattern(const uint64_t pattern, void *buffer, size_t byteCount) {
    return FillMemoryWithPattern<uint64_t>(pattern, buffer, byteCount);
}

// Initialize environment-specific settings (page size, CPU cores, etc.)
void EnvironmentInitialize() {
    // Get system page size
    kPageSize = static_cast<int>(sysconf(_SC_PAGESIZE));
    PLOG_IF(FATAL, kPageSize <= 0) << "Failed to retrieve system page size!";

    // Compute base-2 logarithm of page size (shift count)
    int shift;
    for (shift = 0; (1 << shift) < kPageSize; shift++) {
        // Loop body intentionally empty
    }
    kPageSizeShift = shift;

    // Compute alignment mask for page-aligned addresses
    kPageAlignmentMask = ~(kPageSize - 1);

    DLOG(INFO) << "System page size: " << kPageSize << " bytes, shift: " << kPageSizeShift;

    // Get number of online CPU cores
    kNumberOfCpuCores = static_cast<int>(sysconf(_SC_NPROCESSORS_ONLN));
    DLOG(INFO) << "Number of online CPU cores: " << kNumberOfCpuCores;

    // Recompute derived constants based on actual page size
    kLargeSize = kPageSize / 4;
    kDefaultNativeCodeSize = 4 * kPageSize;
}

} // namespace mio

