template<>
class frg::hash<guid_t> {
public:
    unsigned int operator() (const guid_t &g) const {
        unsigned int h = g.d1;
        h += 31 * h + g.d2;
        h += 31 * h + g.d3;
        for(size_t i = 0; i < 8; i++) {
            h += 31 * h + g.d4[i];
        }
        return h;
    }
};

