        const char* label;
        filesystem_init_fn constructor;
    };

    using guid_to_fs_map_t = frg::hash_map<guid_t, file_system_entry, frg::hash<guid_t>, frg::stl_allocator>;

    static guid_to_fs_map_t registered_filesystems(frg::hash<guid_t>(), {
        frg::make_tuple(gpt::GUID_LINUX_FS_DATA, file_system_entry{"ext2", ext2_init})
    });

