    disk_device::disk_device()
        : device(device_type::storage)
    {
        flags = fs::FS_NODE_BLKDEVICE;
        _identifier = (char *)malloc(16); 
        strncpy(_identifier, "hd", 2);
        itoa(next_instance_number++, _identifier + 2, 10);
        _unique_name = _identifier;
    }

    disk_device::~disk_device() {
        free(_identifier);
    }

    int disk_device::initialize_partitions() {
        static char suffix = 'a';
        for(unsigned idx = 0; idx < _partitions.size(); idx++) {
            auto* part = _partitions[idx];
            auto entry = registered_filesystems.find(part->type());
            if(entry != registered_filesystems.end()) {
                fs::fs_volume* vol = entry->get<1>().constructor(_partitions[idx]);
                if(vol) {
                    if(vol->error()) {
                        delete vol;
                    } else {
                        fs::register_volume(vol, false);
                    }
                }
            }
        }
        return 0;
    }

    ssize_t disk_device::read(size_t offset, size_t length, uint8_t* buffer) {
        if(offset & _block_size) {
            return -EINVAL;
        }
        return read_disk_block(offset / _block_size, length, buffer) != 0 ? -EIO : length;
    }

