#include		"lapin_private.h"
#define			PATTERN		"%p data, %zu size, %s path -> %p"
t_bunny_picture		*bunny_read_picture_id(const void	*_data,
					       size_t		dataSize,
					       const char	*filePath)
{
  struct bunny_picture	*img;
  sf::Texture		tempTexture;
  sf::Sprite		tempSprite;
  uint64_t		hashValue;
  hashValue = bunny_hash(BH_FNV, filePath, strlen(filePath));
  if ((img = new (std::nothrow) struct bunny_picture) == NULL)
    goto AllocationFailure;
  if ((img->sprite = new (std::nothrow) sf::Sprite) == NULL)
    goto FreeImageStructure;
  if (RessourceManager.disable_manager ||
      filePath == NULL ||
      (img->texture = (sf::RenderTexture*)
       RessourceManager.TryGet(ResManager::SF_RENDERTEXTURE, hashValue)) == NULL)
    {
      // We use a temporary texture because RenderTexture cannot load files.
      if (tempTexture.loadFromMemory(_data, dataSize) == false)
	goto FreeTempSprite;
      tempSprite.setTexture(tempTexture);
      if ((img->texture = new (std::nothrow) sf::RenderTexture) == NULL)
	goto FreeTempSprite;
      if (img->texture->create(tempTexture.getSize().x, tempTexture.getSize().y) == false)
	goto FreeRenderTexture;
      img->texture->clear(sf::Color(0, 0, 0, 0));
      img->texture->draw(tempSprite);
      img->texture->display();
    }
  if (RessourceManager.disable_manager == false)
    RessourceManager.AddToPool(ResManager::SF_RENDERTEXTURE, filePath, hashValue, img, img->texture);
  img->res_id = hashValue;
  img->tex = &img->texture->getTexture();
  img->sprite->setTexture(*img->tex);
  img->type = GRAPHIC_RAM;
  img->width = img->tex->getSize().x;
  img->height = img->tex->getSize().y;
  img->rect.x = 0;
  img->rect.y = 0;
  img->rect.w = img->width;
  img->rect.h = img->height;
  img->position.x = 0;
  img->position.y = 0;
  img->origin.x = 0;
  img->origin.y = 0;
  img->scale.x = 1;
  img->scale.y = 1;
  img->rotation = 0;
  img->color_mask.full = WHITE;
  img->smooth = false;
  img->mosaic = false;
  scream_log_if(PATTERN, "ressource,graphics", _data, dataSize, filePath, img);
  return ((t_bunny_picture*)img);
 FreeRenderTexture:
  delete img->texture;
 FreeTempSprite:
  delete img->sprite;
 FreeImageStructure:
  delete img;
 AllocationFailure:
  scream_error_if(return (NULL), ENOMEM, PATTERN, "ressource,graphics", _data, dataSize, filePath, (void*)NULL);
  return (NULL);
}

