{
    map<unsigned int, PoolData_t*>::iterator it = m_PoolMap.begin();

    printf("\n\n");
    while (it != m_PoolMap.end())
    {
        PoolData_t *poolInfo = it->second;
        unsigned int poolSize = it->first;


        printf("Pool %u\n", poolSize);

        printf("  totalAllocationsFromThisPool       : %u\n", poolInfo->totalAllocationsFromThisPool);
        printf("  startAddress                       : 0x%x\n", poolInfo->startAddress);
        printf("  endAddress                         : 0x%x\n", poolInfo->endAddress);
        printf("  totalSize                          : %u bytes\n", poolInfo->totalSize);
        printf("  remainingSpace                     : %u bytes\n", poolInfo->remainingSpace);
        printf("  totalBlocks                        : %u\n", poolInfo->totalBlocks);
        printf("  freeBlocks                         : %u\n", poolInfo->freeBlocks);
        printf("  usedBlocks                         : %u\n", poolInfo->usedBlocks);
        printf("\n");

        it++;
    }
    printf("\n** Total Pools: %d **\n", m_PoolMap.size());
}

