class NumMatrix {
public:
    std::vector<std::vector<std::vector<int>>> sparseTable;
    int logN;

    NumMatrix(std::vector<std::vector<int>>& matrix) {
        int rows = matrix.size();
        int cols = matrix[0].size();
        logN = std::log2(cols);

        sparseTable.resize(rows, std::vector<std::vector<int>>(cols, std::vector<int>(logN + 1)));

        // Initialize base case (power of 0)
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                sparseTable[r][c][0] = matrix[r][c];
            }
        }

        // Build sparse table for each row
        for (int r = 0; r < rows; ++r) {
            for (int j = 1; j <= logN; ++j) {
                for (int start = 0; start + (1 << j) <= cols; ++start) {
                    sparseTable[r][start][j] = sparseTable[r][start][j - 1] + 
                                               sparseTable[r][start + (1 << (j - 1))][j - 1];
                }
            }
        }
    }

    int sumRegion(int row1, int col1, int row2, int col2) {
        int result = 0;
        int left = col1;

        for (int power = logN; power >= 0; --power) {
            if (left + (1 << power) - 1 <= col2) {
                for (int r = row1; r <= row2; ++r) {
                    result += sparseTable[r][left][power];
                }
                left += (1 << power);
            }
        }

        return result;
    }
};

