size_t ConvertToInt(const std::string& input) {
  size_t value = 0;
  std::istringstream stream(input);
  stream >> value;
  return value;
}

int main(int argument_count, char* arguments[]) {
  if (argument_count != 5) {
    std::cerr << "Usage: " << arguments[0]
              << " width height endian_mode big_endian_flag < input > output\n"
              << "    width, height: dimensions of each video frame in pixels\n"
              << "    big_endian_flag: byte order of raw input data (0 for little, 1 for big)\n"
              << "    endian_mode: number of bits to left-shift to align 12-bit data to MSBs:\n"
              << "                 xxxxxxxxxxxx0000 format\n"
              << std::endl;
    return 1;
  }

  size_t frame_width = ConvertToInt(arguments[1]);
  size_t frame_height = ConvertToInt(arguments[2]);
  size_t is_big_endian = ConvertToInt(arguments[3]);
  size_t bit_shift = ConvertToInt(arguments[4]);

  // Validate frame dimensions and shift parameter
  if (frame_width == 0 || frame_width > 65536 || frame_height == 0 || frame_height > 65536) {
    std::cerr << "invalid dimensions: " << frame_width << " x " << frame_height << std::endl;
    return 1;
  }

  if (bit_shift > 16) {
    std::cerr << "invalid shift amount: " << bit_shift << std::endl;
    return 1;
  }

  size_t frame_bytes = frame_width * frame_height * sizeof(uint16_t);
  std::vector<uint16_t> decoded_frame;
  std::vector<uint8_t> compressed_data;
  size_t frame_index = 0;

  fpvc::StreamingDecoder video_decoder;
  size_t chunk_size = (1 << 20);  // 1 MB chunks

  std::vector<uint8_t> io_buffer(chunk_size);
  std::vector<uint8_t> raw_frame_data(frame_bytes);

  while (std::cin) {
    size_t bytes_read = 0;
    size_t current_chunk_size = chunk_size;

    if (!std::cin.read(reinterpret_cast<char*>(io_buffer.data()), chunk_size)) {
      current_chunk_size = static_cast<size_t>(std::cin.gcount());
      if (current_chunk_size == 0) break;
    }

    video_decoder.Decode(
        io_buffer.data(), current_chunk_size,
        [bit_shift, is_big_endian, &frame_index, &raw_frame_data](bool success, const uint16_t* frame_data,
                                          size_t width, size_t height,
                                          void* context) {
          if (!success) {
            std::cerr << "frame decompression error" << std::endl;
            std::exit(1);
          }

          fpvc::UnextractFrame(frame_data, width, height, bit_shift, is_big_endian,
                               raw_frame_data.data());
          fwrite(raw_frame_data.data(), 1, raw_frame_data.size(), stdout);
          std::cerr << "frame processed: " << (frame_index++) << std::endl;
        },
        nullptr);
  }
}

