void fvec_madd_ref(
        std::size_t len,
        const float* src1,
        float scale,
        const float* src2,
        float* dst) {
    for (std::size_t idx = 0; idx < len; idx++)
        dst[idx] = src1[idx] + scale * src2[idx];
}

int fvec_madd_and_argmin_ref(
        std::size_t len,
        const float* src1,
        float scale,
        const float* src2,
        float* dst) {
    float minVal = 1e30f;
    int argMin = -1;
    for (std::size_t idx = 0; idx < len; idx++) {
        dst[idx] = src1[idx] + scale * src2[idx];
        if (dst[idx] < minVal) {
            minVal = dst[idx];
            argMin = static_cast<int>(idx);
        }
    }
    return argMin;
}
