// Compute product of integers in the inclusive range [from, to]
uint64_t rangeProduct(uint64_t start, uint64_t end) {
    uint64_t result = 1;
    for (; start <= end; ++start) {
        result *= start;
    }
    return result;
}

// Evaluate Jacobi polynomial P_n^(a,b)(x)
double JacobiP(unsigned degree, unsigned alpha, unsigned beta, double argument) {
    if (degree == 0) {
        return 1.0;
    }
    double P_prev_2;
    double P_prev_1 = 1.0;
    double P_current = 0.5 * alpha - 0.5 * beta +
                       (1.0 + 0.5 * (alpha + beta)) * argument;
    double alpha2_beta2 = static_cast<double>(alpha * alpha) -
                          static_cast<double>(beta * beta);
    for (unsigned m = 2; m <= degree; ++m) {
        P_prev_2 = P_prev_1;
        P_prev_1 = P_current;
        P_current = ((2.0 * m + alpha + beta - 1.0) *
                     (alpha2_beta2 + (2.0 * m + alpha + beta) *
                                   (2.0 * m + alpha + beta - 2.0) * argument) *
                         P_prev_1 -
                     2.0 * (m + alpha - 1.0) * (m + beta - 1.0) *
                         (2.0 * m + alpha + beta) * P_prev_2) /
                    (2.0 * m * (m + alpha + beta) *
                     (2.0 * m + alpha + beta - 2.0));
    }
    return P_current;
}

// Derivative of Jacobi polynomial with respect to x
double JacobiPDerivative(unsigned degree, unsigned alpha, unsigned beta,
                         double argument) {
    return (degree == 0) ? 0.0
                         : 0.5 * (degree + alpha + beta + 1.0) *
                               JacobiP(degree - 1, alpha + 1, beta + 1,
                                       argument);
}

// Precompute coefficients for singularity-free Jacobi recursion
std::array<double, 5> SingularityFreeJacobiPFactors(unsigned m_index,
                                                    unsigned alpha,
                                                    unsigned beta) {
    double c_0 = 2.0 * m_index + alpha + beta;
    double c_1 = c_0 - 1.0;
    double c_2 = static_cast<double>(alpha * alpha) -
                 static_cast<double>(beta * beta);
    double c_3 = c_0 * (c_0 - 2.0);
    double c_4 = 2.0 * (m_index + alpha - 1.0) * (m_index + beta - 1.0) * c_0;
    double c_5 = 2.0 * m_index * (m_index + alpha + beta) * (c_0 - 2.0);
    return {c_1, c_2, c_3, c_4, c_5};
}

// Perform one step of singularity-free Jacobi recursion
double SingularityFreeJacobiPRecursion(double x_val, double y_val,
                                       std::array<double, 5> const& coeffs,
                                       double P_prev_1, double P_prev_2) {
    return (coeffs[0] * (coeffs[1] * y_val + coeffs[2] * x_val) * P_prev_1 -
            coeffs[3] * y_val * y_val * P_prev_2) /
           coeffs[4];
}

// Evaluate singularity-free Jacobi polynomial using two arguments
double SingularityFreeJacobiP(unsigned degree, unsigned alpha, unsigned beta,
                              double x_val, double y_val) {
    if (degree == 0) {
        return 1.0;
    }
    double P_prev_2;
    double P_prev_1 = 1.0;
    double P_current =
        (0.5 * alpha - 0.5 * beta) * y_val +
        (1.0 + 0.5 * (alpha + beta)) * x_val;
    for (unsigned m = 2; m <= degree; ++m) {
        P_prev_2 = P_prev_1;
        P_prev_1 = P_current;
        auto coeffs = SingularityFreeJacobiPFactors(m, alpha, beta);
        P_current = SingularityFreeJacobiPRecursion(x_val, y_val, coeffs,
                                                    P_prev_1, P_prev_2);
    }
    return P_current;
}

// Compute value and partial derivatives of singularity-free Jacobi polynomial
std::array<double, 3>
SingularityFreeJacobiPAndDerivatives(unsigned degree, unsigned alpha,
                                     unsigned beta, double x_val, double y_val) {
    if (degree == 0) {
        return {1.0, 0.0, 0.0};
    }
    double P_prev_2, ddxP_prev_2, ddyP_prev_2;
    double P_prev_1 = 1.0, ddxP_prev_1 = 0.0, ddyP_prev_1 = 0.0;
    double P_current = SingularityFreeJacobiP(1, alpha, beta, x_val, y_val);
    double ddxP_current = 1.0 + 0.5 * (alpha + beta);
    double ddyP_current = 0.5 * (static_cast<double>(alpha) -
                                 static_cast<double>(beta));
    for (unsigned m = 2; m <= degree; ++m) {
        P_prev_2 = P_prev_1;
        P_prev_1 = P_current;
        ddxP_prev_2 = ddxP_prev_1;
        ddxP_prev_1 = ddxP_current;
        ddyP_prev_2 = ddyP_prev_1;
        ddyP_prev_1 = ddyP_current;

        auto coeffs = SingularityFreeJacobiPFactors(m, alpha, beta);
        P_current = SingularityFreeJacobiPRecursion(x_val, y_val, coeffs,
                                                    P_prev_1, P_prev_2);
        ddxP_current = (coeffs[0] * (coeffs[2] * P_prev_1 +
                                      (coeffs[1] * y_val + coeffs[2] * x_val) *
                                          ddxP_prev_1) -
                        coeffs[3] * y_val * y_val * ddxP_prev_2) /
                       coeffs[4];
        ddyP_current = (coeffs[0] * (coeffs[1] * P_prev_1 +
                                      (coeffs[1] * y_val + coeffs[2] * x_val) *
                                          ddyP_prev_1) -
                        coeffs[3] * (2.0 * y_val * P_prev_2 +
                                     y_val * y_val * ddyP_prev_2)) /
                       coeffs[4];
    }
    return {P_current, ddxP_current, ddyP_current};
}

// Triangular Dubiner polynomial evaluation
double TriDubinerP(std::array<unsigned, 2> const& indices,
                   std::array<double, 2> const& coords) {
    double r_num = 2.0 * coords[0] - 1.0 + coords[1];
    double s = 2.0 * coords[1] - 1.0;
    double theta = 1.0 - coords[1];
    double ti = SingularityFreeJacobiP(indices[0], 0, 0, r_num, theta);
    double tij = SingularityFreeJacobiP(indices[1], 2 * indices[0] + 1, 0, s,
                                        1.0);
    return ti * tij;
}

// Gradient of triangular Dubiner polynomial
std::array<double, 2> gradTriDubinerP(std::array<unsigned, 2> const& indices,
                                      std::array<double, 2> const& coords) {
    double r_num = 2.0 * coords[0] - 1.0 + coords[1];
    double s = 2.0 * coords[1] - 1.0;
    double theta = 1.0 - coords[1];
    auto ti = SingularityFreeJacobiPAndDerivatives(indices[0], 0, 0, r_num,
                                                   theta);
    auto tij = SingularityFreeJacobiPAndDerivatives(
        indices[1], 2 * indices[0] + 1, 0, s, 1.0);
    auto ddalpha = [&](double dr_num, double dtheta, double dt) {
        return (ti[1] * dr_num + ti[2] * dtheta) * tij[0] +
               ti[0] * tij[1] * dt;
    };
    return {ddalpha(2.0, 0.0, 0.0), ddalpha(1.0, -1.0, 2.0)};
}

// Tetrahedral Dubiner polynomial evaluation
double TetraDubinerP(std::array<unsigned, 3> const& indices,
                     std::array<double, 3> const& coords) {
    double r_num = 2.0 * coords[0] - 1.0 + coords[1] + coords[2];
    double s_num = 2.0 * coords[1] - 1.0 + coords[2];
    double t = 2.0 * coords[2] - 1.0;
    double sigmatheta = 1.0 - coords[1] - coords[2];
    double theta = 1.0 - coords[2];
    double ti = SingularityFreeJacobiP(indices[0], 0, 0, r_num, sigmatheta);
    double tij = SingularityFreeJacobiP(indices[1], 2 * indices[0] + 1, 0,
                                        s_num, theta);
    double tijk = SingularityFreeJacobiP(indices[2], 2 * indices[0] +
                                                     2 * indices[1] + 2, 0, t,
                                         1.0);
    return ti * tij * tijk;
}

// Gradient of tetrahedral Dubiner polynomial
std::array<double, 3> gradTetraDubinerP(std::array<unsigned, 3> const& indices,
                                        std::array<double, 3> const& coords) {
    double r_num = 2.0 * coords[0] - 1.0 + coords[1] + coords[2];
    double s_num = 2.0 * coords[1] - 1.0 + coords[2];
    double t = 2.0 * coords[2] - 1.0;
    double sigmatheta = 1.0 - coords[1] - coords[2];
    double theta = 1.0 - coords[2];
    auto ti = SingularityFreeJacobiPAndDerivatives(indices[0], 0, 0, r_num,
                                                   sigmatheta);
    auto tij = SingularityFreeJacobiPAndDerivatives(
        indices[1], 2 * indices[0] + 1, 0, s_num, theta);
    auto tijk = SingularityFreeJacobiPAndDerivatives(
        indices[2], 2 * indices[0] + 2 * indices[1] + 2, 0, t, 1.0);
    auto ddalpha = [&](double dr_num, double dsigmatheta, double ds_num,
                       double dtheta, double dt) {
        return (ti[1] * dr_num + ti[2] * dsigmatheta) * tij[0] * tijk[0] +
               ti[0] * (tij[1] * ds_num + tij[2] * dtheta) * tijk[0] +
               ti[0] * tij[0] * (tijk[1] * dt);
    };
    return {ddalpha(2.0, 0.0, 0.0, 0.0, 0.0),
            ddalpha(1.0, -1.0, 2.0, 0.0, 0.0),
            ddalpha(1.0, -1.0, 1.0, -1.0, 2.0)};
}
