#ifdef __arm__
// On ARM, this function is exported by the dynamic linker but never
// declared in any official header. It is used at runtime to
// locate the base address of the .ARM.exidx section for the
// shared library containing the instruction at |pc|, storing the count
// of 8-byte entries into |*pcount|.
extern "C" _Unwind_Ptr dl_unwind_find_exidx(_Unwind_Ptr, int*);
#else
// On other architectures, this function is exported by the dynamic linker
// but not declared in any standard header. At runtime, it iterates over all
// loaded libraries invoking |cb|. If the callback returns non-zero,
// iteration halts and that value is returned.
extern "C" int dl_iterate_phdr(int (*cb)(dl_phdr_info* info,
                                         size_t size,
                                         void* data),
                               void* data);
#endif

namespace crazy {
namespace {

// LLVM’s demangler is large; we don’t need it. By replacing it with a stub,
// we avoid pulling in substantial code from libc++, reducing the disk footprint
// of the crazy linker from over 290 KB to under 85 KB on ARM.
//
// See:
//   https://code.google.com/p/chromium/issues/detail?id=502299
//   https://llvm.org/svn/llvm-project/libcxxabi/trunk/src/cxa_demangle.cpp
extern "C" char* __cxa_demangle(const char* mangled_name,
                                char* buf,
                                size_t* n,
                                int* status) {
  static const int kHeapAllocFailed = -1;  // Matches LLVM's memory_alloc_failure.
  if (status)
    *status = kHeapAllocFailed;
  return nullptr;
}

#ifdef __arm__
extern "C" int __cxa_atexit(void (*)(void*), void*, void*);

// On ARM, __cxa_atexit is weakly defined in libc.so, but dlsym() cannot resolve it.
// To work around this, provide an equivalent implementation here.
// The ARM EABI specifies its behavior precisely.
int __aeabi_atexit(void* obj_ptr, void (*dtor)(void*), void* dso_handle) {
  return __cxa_atexit(dtor, obj_ptr, dso_handle);
}
#endif

// Store the system dlerror() string into thread-local storage.
void RecordSystemError() {
  ThreadData* tls_data = GetThreadData();
  tls_data->SetError(::dlerror());
}

char* DlerrorWrapper() {
  ThreadData* tls_data = GetThreadData();
  const char* err_msg = tls_data->GetError();
  tls_data->SwapErrorBuffers();
  // dlerror() returns 'char*', but clients must not modify the result.
  return const_cast<char*>(err_msg);
}

void* DlopenWrapper(const char* lib_path, int flags) {
  ScopedGlobalLock lock;
  // If |lib_path| is NULL, return handle to current executable — not handled by crazy linker.
  if (lib_path) {
    LibraryList* libs = Globals::GetLibraries();
    Error err;
    LibraryView* wrapper = libs->LoadLibrary(lib_path,
                                             flags,
                                             0U /* load_address */,
                                             0U /* file_offset */,
                                             Globals::GetSearchPaths(),
                                             false,
                                             &err);
    if (wrapper)
      return wrapper;
  }

  // Fallback to system dlopen()
  ::dlerror();
  void* sys_lib = ::dlopen(lib_path, flags);
  if (!sys_lib) {
    RecordSystemError();
    return nullptr;
  }

  LibraryView* wrap_lib = new LibraryView();
  wrap_lib->SetSystem(sys_lib, lib_path ? lib_path : "<executable>");
  Globals::GetLibraries()->AddLibrary(wrap_lib);
  return wrap_lib;
}

void* DlsymWrapper(void* handle, const char* sym_name) {
  LibraryView* wrap_lib = reinterpret_cast<LibraryView*>(handle);
  if (!sym_name) {
    SetLinkerError("dlsym: NULL symbol name");
    return nullptr;
  }
  if (!handle) {
    SetLinkerError("dlsym: NULL library handle");
    return nullptr;
  }

  // TODO(digit): Support RTLD_DEFAULT / RTLD_NEXT
  if (handle == RTLD_DEFAULT || handle == RTLD_NEXT) {
    SetLinkerError("dlsym: RTLD_DEFAULT/RTLD_NEXT not implemented!");
    return nullptr;
  }

  void* addr = nullptr;
  if (wrap_lib->IsSystem()) {
    addr = ::dlsym(wrap_lib->GetSystem(), sym_name);
    if (!addr) {
      RecordSystemError();
      LOG("dlsym:%s: symbol '%s' not found in system library\n%s",
          wrap_lib->GetName(),
          sym_name,
          GetThreadData()->GetError());
    }
    return addr;
  }

  if (wrap_lib->IsCrazy()) {
    ScopedGlobalLock lock;
    LibraryList* libs = Globals::GetLibraries();
    addr = libs->FindSymbolFrom(sym_name, wrap_lib);
    if (addr)
      return addr;

    SetLinkerError("dlsym: Symbol '%s' not found in library '%s'",
                   sym_name,
                   wrap_lib->GetName());
    return nullptr;
  }

  SetLinkerError("dlsym: Invalid handle %p for symbol '%s'",
                 handle,
                 sym_name);
  return nullptr;
}

int DladdrWrapper(void* ptr, Dl_info* out_info) {
  // Search in crazy libraries first.
  {
    ScopedGlobalLock lock;
    LibraryList* libs = Globals::GetLibraries();
    LibraryView* wrap = libs->FindLibraryForAddress(ptr);
    if (wrap && wrap->IsCrazy()) {
      size_t sym_size = 0;
      SharedLibrary* lib = wrap->GetCrazy();
      ::memset(out_info, 0, sizeof(*out_info));
      out_info->dli_fname = lib->base_name();
      out_info->dli_fbase = reinterpret_cast<void*>(lib->load_address());
      (void)lib->FindNearestSymbolForAddress(
          ptr, &out_info->dli_sname, &out_info->dli_saddr, &sym_size);
      return 0;
    }
  }

  // Fall back to system dladdr().
  ::dlerror();
  int res = ::dladdr(ptr, out_info);
  if (res != 0)
    RecordSystemError();
  return res;
}

int DlcloseWrapper(void* handle) {
  LibraryView* wrap_lib = reinterpret_cast<LibraryView*>(handle);
  if (!wrap_lib) {
    SetLinkerError("NULL library handle");
    return -1;
  }

  if (wrap_lib->IsSystem() || wrap_lib->IsCrazy()) {
    ScopedGlobalLock lock;
    LibraryList* libs = Globals::GetLibraries();
    libs->UnloadLibrary(wrap_lib);
    return 0;
  }

  SetLinkerError("Invalid library handle %p", handle);
  return -1;
}

#ifdef __arm__
_Unwind_Ptr Dl_unwind_find_exidx_wrapper(_Unwind_Ptr pc, int* pcount) {
  // First check crazy libraries.
  {
    ScopedGlobalLock lock;
    LibraryList* list = Globals::GetLibraries();
    _Unwind_Ptr result = list->FindArmExIdx(pc, pcount);
    if (result)
      return result;
  }

  // Then try system unwinder.
  return ::dl_unwind_find_exidx(pc, pcount);
}
#else  // !__arm__
int Dl_iterate_phdr_wrapper(int (*callback)(dl_phdr_info*, size_t, void*), void* arg) {
  // Iterate over crazy libraries first.
  {
    ScopedGlobalLock lock;
    LibraryList* list = Globals::GetLibraries();
    int val = list->IteratePhdr(callback, arg);
    if (val)
      return val;
  }

  // Continue with system libraries.
  return ::dl_iterate_phdr(callback, arg);
}
#endif  // !__arm__

}  // namespace

void* LinkerSymbolResolver(const char* sym_name) {
  // All wrapped symbols start with 'dl'; special-case __aeabi_atexit on ARM.
  if (sym_name[0] != 'd' || sym_name[1] != 'l') {
#ifdef __arm__
    if (sym_name[0] == '_' && !strcmp("__aeabi_atexit", sym_name))
      return reinterpret_cast<void*>(&__aeabi_atexit);
#endif
    return nullptr;
  }

  static const struct {
    const char* name;
    void* func_ptr;
  } kWrappedSymbols[] = {
        {"dlopen", reinterpret_cast<void*>(&DlopenWrapper)},
        {"dlclose", reinterpret_cast<void*>(&DlcloseWrapper)},
        {"dlerror", reinterpret_cast<void*>(&DlerrorWrapper)},
        {"dlsym", reinterpret_cast<void*>(&DlsymWrapper)},
        {"dladdr", reinterpret_cast<void*>(&DladdrWrapper)},
#ifdef __arm__
        {"dl_unwind_find_exidx",
         reinterpret_cast<void*>(&Dl_unwind_find_exidx_wrapper)},
#else
        {"dl_iterate_phdr", reinterpret_cast<void*>(&Dl_iterate_phdr_wrapper)},
#endif
    };

  static const size_t kNumSymbols = sizeof(kWrappedSymbols) / sizeof(kWrappedSymbols[0]);
  for (size_t idx = 0; idx < kNumSymbols; ++idx) {
    if (!strcmp(kWrappedSymbols[idx].name, sym_name))
      return kWrappedSymbols[idx].func_ptr;
  }
  return nullptr;
}

