#define HOOK_FUNC_NAME "__exception_handler"
#define OPT_PREFIX "__opt_"

using namespace llvm;
using std::vector;
using std::map;
using std::pair;

namespace {
/*
 * Add a `stackmap` instruction following each function call to capture its return address.
 *
 * The optimized variant of each function maintains an equivalent count of
 * `llvm.experimental.stackmap` instructions as the initial (programmer-defined) version.
 * Given the identifier of a `stackmap` instruction in the optimized function,
 * the corresponding identifier in the non-optimized version can be derived
 * by applying bitwise complement to the identifier.
 */
struct TracePointPass: public FunctionPass {
  static char id;
  // Associative container mapping each function name to the patchpoint identifiers of stackmap instructions
  // within that function. This facilitates runtime correlation between stackmap
  // instructions in optimized functions and their unoptimized counterparts.
  static map<StringRef, vector<uint64_t>> stackMaps;

  TracePointPass() : FunctionPass(id) {}

  virtual bool initialize(Module &module) {
    // Declare the exception handler function. Required because the
    // `__exception_handler` function isn't defined in the current module.
    LLVMContext &context = module.getContext();
    Type* int64 = Type::getInt64Ty(context);
    FunctionType* prototype = FunctionType::get(Type::getVoidTy(context),
                                                int64, false);
    Function *handler_func = Function::Create(
        prototype, Function::ExternalLinkage, "__exception_handler", &module);
    return true;
  }

  virtual bool executeOnFunction(Function &func) {
    Module *module = func.getParent();
    StringRef funcName = func.getName();
    outs() << "Executing TracePointPass on function: " << funcName << '\n';

    Type *ptr8_t = PointerType::getUnqual(
        IntegerType::getInt8Ty(module->getContext()));

    vector <Instruction *> callInstructions;

    // Handler callback for guard failures.
    Constant* exceptionHandler = ConstantExpr::getBitCast(
        module->getFunction(HOOK_FUNC_NAME), ptr8_t);

    for (auto &block : func) {
      for (BasicBlock::iterator iter = block.begin(); iter != block.end(); ++iter) {
        // XXX This is where the guard must trigger (a specific instruction in
        // the "deep_call" function).
        if (funcName.endswith("deep_call") && isa<ReturnInst>(iter)) {
          LLVMContext &ctx = block.getContext();
          IRBuilder<> builder(&block, iter->getIterator());
          uint64_t PPID = getNextPatchpointID(funcName);

          // First two parameters of stackmap/patchpoint intrinsic calls are:
          // unique call identifier and shadow byte count.
          auto params = vector<Value*> { builder.getInt64(PPID),
                                         builder.getInt32(17) // XXX shadow size
                                        };

          // Intrinsic to invoke: patchpoint for optimized functions; stackmap for unoptimized.
          Function *intrinsic = nullptr;
          if (!funcName.startswith(OPT_PREFIX)) {
            // Optimized function -> insert patchpoint call with callback
            params.insert(params.end(),
                        { exceptionHandler,          // callback function
                          builder.getInt32(1),       // callback argument count
                          builder.getInt64(PPID)     // callback parameter
                        });
            intrinsic = Intrinsic::getDeclaration(
                module, Intrinsic::experimental_patchpoint_void);
          } else {
            // Unoptimized function -> insert patchpoint without callback
            auto cb = builder.CreateIntToPtr(builder.getInt64(0),
                                             builder.getInt8PtrTy());
            params.insert(params.end(),
                        { cb,              // no callback
                          builder.getInt32(0)   // zero callback arguments
                        });
            intrinsic = Intrinsic::getDeclaration(
                module, Intrinsic::experimental_patchpoint_void);
          }
          auto callInst = builder.CreateCall(intrinsic, params);
        } 
        else if (isa<CallInst>(iter)) {
          CallInst &prevCallInst = cast<CallInst>(*iter);
          Function *targetFunc = prevCallInst.getCalledFunction();

          if (!prevCallInst.isInlineAsm() &&
              !targetFunc->hasAvailableExternallyLinkage() &&
              !targetFunc->isDeclaration()) {
            // Regular function call - guard might fail inside, so record return address
            uint64_t PPID = getNextPatchpointID(funcName);
            IRBuilder<> builder(iter->getNextNode());

            auto params = vector<Value*> { builder.getInt64(PPID),
                                         builder.getInt32(17)
                                       };

            if (funcName.startswith(OPT_PREFIX)) {
              // Current function is unoptimized - replace calls with patchpoints
              // Original called functions become callbacks for accurate return tracking
              if (!targetFunc->getName().startswith(OPT_PREFIX)) {
                targetFunc = module->getFunction(getTwinName(targetFunc->getName()));
              }

              // Callback for patchpoint call
              Constant* callback = ConstantExpr::getBitCast(targetFunc, ptr8_t);
              params.insert(params.end(),
                          { callback,          // callback function
                            builder.getInt32(prevCallInst.getNumArgOperands())
                          });

              for (unsigned i = 0; i < prevCallInst.getNumArgOperands(); ++i) {
                params.push_back(prevCallInst.getArgOperand(i));
              }

              // Select correct patchpoint intrinsic based on return type
              Function *intrinsic = nullptr;
              if (targetFunc->getReturnType()->isVoidTy()) {
                intrinsic = Intrinsic::getDeclaration(
                  module, Intrinsic::experimental_patchpoint_void);
              } else {
                intrinsic = Intrinsic::getDeclaration(
                  module, Intrinsic::experimental_patchpoint_i64);
              }

              // Transform this call into a patchpoint call
              auto newCall = CallInst::Create(intrinsic, params);

              // Update uses of original call with new patchpoint
              auto targetRetTy = targetFunc->getReturnType();
              if (targetRetTy->isVoidTy()) {
                if (!prevCallInst.use_empty()) {
                  prevCallInst.replaceAllUsesWith(newCall);
                }
              } else {
                auto retType = prevCallInst.getCalledFunction()->getReturnType();
                Value *retVal = nullptr;
                if (targetRetTy->isIntegerTy()) {
                  retVal = builder.CreateTruncOrBitCast(newCall, retType);
                } else {
                  auto floatPtrTy = PointerType::getUnqual(retType);
                  retVal = builder.CreateIntToPtr(newCall, floatPtrTy);
                  retVal = builder.CreateLoad(retVal, retType);
                }
                if (!prevCallInst.use_empty()) {
                  prevCallInst.replaceAllUsesWith(retVal);
                }
              }
              ReplaceInstWithInst(&prevCallInst, newCall);
              iter = newCall->getIterator();
              callInstructions.push_back(&*iter);
            } 
            else {
              // Non-unoptimized function - insert stackmap after call
              auto intrinsic = Intrinsic::getDeclaration(
                  module, Intrinsic::experimental_stackmap);
              builder.CreateCall(intrinsic, params);
              callInstructions.push_back(&*iter);
            }
          }
        }
      }
    }

    // Insert empty inline assembly blocks
    for (auto inst: callInstructions) {
      IRBuilder<> builder(inst);
      FunctionType *funType = FunctionType::get(builder.getVoidTy(), false);

      InlineAsm *asmBlock = InlineAsm::get(funType,
                                          "",      /* AsmString */
                                          ""       /* Constraints */,
                                          true     /* hasSideEffects */,
                                          false    /* isAlignStack */);
      builder.CreateCall(asmBlock, {});
    }
    return true;
  }

  /*
   * Get the 'counterpart' function name for the specified one.
   *
   * If input is optimized function name, returns unoptimized version (prefixed with '__unopt_').
   * If input is unoptimized function name, returns optimized version (strips '__unopt_' prefix).
   *
   * Example: "process" -> "__unopt_process" or "__unopt_process" -> "process"
   */
  static std::string getCounterpartName(StringRef name) {
    if (name.startswith(OPT_PREFIX)) {
      return name.drop_front(StringRef(OPT_PREFIX).size()).str();
    }
    return OPT_PREFIX + name.str();
  }

  /*
   * Generate next patchpoint identifier for given function.
   */
  static uint64_t getNextPatchpointID(StringRef funcName) {
    uint64_t nextID = 0;
    if (!stackMaps.empty()) {
        std::string counterpart = getCounterpartName(funcName);
        if (stackMaps.find(counterpart) == stackMaps.end()) {
          // Counterpart function has no IDs yet
          // Next ID equals last ID from current function plus one
          auto maxPos = std::max_element(stackMaps.begin(), stackMaps.end(),
              [] (const pair<StringRef, vector<uint64_t>> &a,
                    const pair<StringRef, vector<uint64_t>> &b) {
                return a.second.back() < b.second.back();
              });
          nextID = (*maxPos).second.back() + 1;
        } else {
          // Find corresponding stackmap ID in counterpart function
          // Apply bitwise NOT to get new ID for current function
          size_t idx = stackMaps[funcName].size();
          nextID = ~stackMaps[counterpart][idx];
        }
    }

    if (stackMaps.find(funcName) == stackMaps.end() &&
        stackMaps.find(getCounterpartName(funcName)) == stackMaps.end()) {
      // Ensures stackmap/patchpoint calls in same function have consecutive IDs
      // Increment when encountering new function
      ++nextID;
    }

    stackMaps[funcName].push_back(nextID);
    return nextID;
  }
};
} // end anonymous namespace

char TracePointPass::id = 0;
map<StringRef, vector<uint64_t>> TracePointPass::stackMaps;

// Auto-enable mechanism for pass registration
// http://adriansampson.net/blog/clangpass.html
static void setupPass(const PassManagerBuilder &,
                      legacy::PassManagerBase &manager) {
  manager.add(new TracePointPass());
}

static RegisterStandardPasses RegisterPass(
    PassManagerBuilder::EP_EarlyAsPossible, setupPass);

