InverseExponentialElasticConstant::InverseExponentialElasticConstant(double stiffness,
		double reference_distance, int exponent):ElasticConstantCalculator(stiffness){
	this->x0 = reference_distance;
	this->power = exponent;
}

InverseExponentialElasticConstant::~InverseExponentialElasticConstant() {
}

double InverseExponentialElasticConstant::calculateK(Point& point_i, Point& point_j){
	// initial values: k = 1, x0 = 3.8, power = 6, cutoff = 10
	double distance = point_j.distance(point_i);
	double k_initial = initial_constant;
	return k_initial / ( 1.0 + pow( distance / x0, power ) );
//	return (k_initial / ( 1.0 + pow( distance / x0, power ) ))/(distance*distance);
}

#include "sip_hash.h"
#include <cstring>  // memcpy
#include "vec.h"

namespace {
// Paper: https://www.131002.net/siphash/siphash.pdf
// SSE41 implementation: https://goo.gl/80GBSD
// The hash state is updated by injecting 8-byte packets;
// XORing together all state variables yields the final hash.
// 32 bytes. Parameters are hardwired to c=2, d=4 [rounds].
class SipHashState {
 public:
  explicit INLINE SipHashState(const uint64_t keys[2]) {
    const V2x64U key = LoadU(keys);
    const V2x64U init0 =
        key ^ V2x64U(0x646f72616e646f6dull, 0x736f6d6570736575ull);
    const V2x64U init1 =
        key ^ V2x64U(0x7465646279746573ull, 0x6c7967656e657261ull);
    v02 = UnpackLow(init0, init1);
    v13 = UnpackHigh(init0, init1);
  }
  INLINE void Process(const V2x64U& chunk) {
    v13 ^= V2x64U(_mm_slli_si128(chunk, 8));  // Only v3.
    Mix<2>();
    v02 ^= chunk;  // Only v0.
  }
  INLINE uint64_t ComputeResult() {
    // Mix in bits to avoid leaking the key if all packets were zero.
    v02 ^= V2x64U(0xFF, 0);
    Mix<4>();
    const V2x64U combined = v02 ^ v13;
    const V2x64U highPart(_mm_unpackhi_epi64(combined, combined));
    return _mm_cvtsi128_si64(combined ^ highPart);
  }
 private:
  // Independently rotates v1 and v3 by bits1 and bits3.
  template <uint64_t bits1, uint64_t bits3>
  static INLINE V2x64U ShiftLeft(const V2x64U& v13) {
    const V2x64U shiftL(bits1, bits3);
    const V2x64U shiftR(64 - bits1, 64 - bits3);
    const V2x64U left(_mm_sllv_epi64(v13, shiftL));
    const V2x64U right(_mm_srlv_epi64(v13, shiftR));
    return left | right;
  }
  // Swaps and rotates v0 and v2 by 32 bits.
  static INLINE V2x64U Shift32(const V2x64U& v02) {
    return V2x64U(_mm_shuffle_epi32(v02, _MM_SHUFFLE(0, 1, 3, 2)));
  }
  // ARX network: add, rotate, exclusive-or.
  template <uint64_t bits1, uint64_t bits3>
  INLINE void QuarterRound() {
    v02 += v13;
    v13 = ShiftLeft<bits1, bits3>(v13);
    v13 ^= v02;
  }
  template <size_t rounds>
  INLINE void Mix() {
    for (size_t i = 0; i < rounds; ++i) {
      QuarterRound<16, 13>();
      v02 = Shift32(v02);
      QuarterRound<21, 17>();
      v02 = Shift32(v02);
    }
  }
  V2x64U v02;
  V2x64U v13;
};

static INLINE V2x64U ReadPacket64(const uint8_t* data) {
  uint64_t value;
  memcpy(&value, data, sizeof(value));
  return V2x64U(_mm_cvtsi64_si128(value));
}

static INLINE V2x64U ReadFinalPacket64(const uint8_t* data,
                                       const uint64_t length,
                                       const size_t pos) {
  ALIGNED(uint8_t, 16) temp[8] = {0};
  memcpy(temp, data, length - pos);
  temp[7] = length;
  return ReadPacket64(temp);
}
}  // namespace

uint64_t SipHash(const uint64_t key[2], const uint8_t* data,
                 const uint64_t length) {
  SipHashState hasher(key);
  size_t index = 0;
  for (; index < (length & ~7); index += 8) {
    const V2x64U chunk = ReadPacket64(data + index);
    hasher.Process(chunk);
  }
  const V2x64U lastChunk = ReadFinalPacket64(data + index, length, index);
  hasher.Process(lastChunk);
  return hasher.ComputeResult();
}

uint64_t ReduceSipTreeHash(const uint64_t key[2], const uint64_t values[4]) {
  SipHashState hasher(key);
  for (int idx = 0; idx < 4; ++idx) {
    const V2x64U chunk(_mm_cvtsi64_si128(values[idx]));
    hasher.Process(chunk);
  }
  return hasher.ComputeResult();
}

#include "../helpers_event.h"
void do_item_description(std::ostream & s, const event_context & context, df::item *item)
{
    if (auto is_artifact = Items::getGeneralRef(item, general_ref_type::IS_ARTIFACT))
    {
        if (auto artifact = is_artifact->getArtifact())
        {
            event_link(s, context, artifact);
            return;
        }
    }
    std::string buffer;
    item->getItemDescriptionPrefix(&buffer, 0);
    s << buffer;
    buffer.clear();
    item->getItemDescription(&buffer, 0);
    if (auto remains = virtual_cast<df::item_body_component>(item))
    {
        if (auto hf = df::historical_figure::find(remains->hist_figure_id))
        {
            std::string label = Translation::capitalize(Translation::TranslateName(&hf->name, false), true);
            size_t offset = 0;
            size_t index;
            while ((index = buffer.find(label, offset)) != std::string::npos)
            {
                s << buffer.substr(offset, index - offset);
                link(s, hf);
                offset = index + label.length();
            }
            s << buffer.substr(offset);
            return;
        }
    }
    s << buffer;
}

