// Verify that an empty result has all expected fields initialized correctly
void validateEmptyResult(const InvocationLogParseResult &empty) {
  REQUIRE(empty.invocations.entries.empty());
  REQUIRE(empty.invocations.created_directories.empty());
  REQUIRE(empty.warning.empty());
  REQUIRE(!empty.needs_recompaction);
  REQUIRE(empty.parse_data.path_ids.empty());
  REQUIRE(empty.parse_data.fingerprint_ids.empty());
  REQUIRE(empty.parse_data.fingerprint_entry_count == 0);
  REQUIRE(empty.parse_data.path_entry_count == 0);
  REQUIRE(!empty.parse_data.buffer);
}

// Helper to record a command execution with various dependencies
void executeCommand(
    InvocationLog &log,
    const Hash &step_hash,
    std::vector<std::string> &&outputs,
    std::vector<std::string> &&inputs,
    std::vector<uint32_t> &&ignores,
    std::vector<Hash> &&extras) {
  log.ranCommand(
      step_hash,
      std::move(outputs),
      log.fingerprintFiles(outputs),
      std::move(inputs),
      log.fingerprintFiles(inputs),
      std::move(ignores),
      std::move(extras));
}

// Test round-trip behavior between in-memory and persistent logs
template <typename Func>
void testRoundTrip(const Func &func) {
  InMemoryFileSystem fileSystem;
  InMemoryInvocationLog memoryLog(fileSystem, [] { return 0; });

  auto persistentLog = openPersistentInvocationLog(
      fileSystem,
      [] { return 0; },
      "test_log",
      InvocationLogParseResult::ParseData());

  func(*persistentLog, fileSystem);
  func(memoryLog, fileSystem);

  auto parsedResult = parsePersistentInvocationLog(fileSystem, "test_log");
  auto memoryResult = memoryLog.invocations();

  REQUIRE(parsedResult.warning == "");
  REQUIRE(memoryResult == parsedResult.invocations);
}

// Test memory leak handling
template <typename Func>
void testMemoryLeak(const Func &func) {
  InMemoryFileSystem fileSystem;
  auto persistentLog = openPersistentInvocationLog(
      fileSystem,
