      "test_log",
      InvocationLogParseResult::ParseData());

  func(*persistentLog, fileSystem);
  persistentLog->leakMemory();
  // No specific checks here - just ensure no crash occurs
}

// Test multiple write cycles with recompaction
template <typename Func>
void testMultipleCycles(const Func &func, InMemoryFileSystem fileSystem) {
  InMemoryInvocationLog memoryLog(fileSystem, [] { return 0; });
  func(memoryLog, fileSystem);

  for (size_t i = 0; i < 5; i++) {
    auto parsedResult = parsePersistentInvocationLog(fileSystem, "test_log");
    REQUIRE(parsedResult.warning == "");

    auto persistentLog = openPersistentInvocationLog(
        fileSystem,
        [] { return 0; },
        "test_log",
        std::move(parsedResult.parse_data));

    func(*persistentLog, fileSystem);
  }

  auto finalResult = parsePersistentInvocationLog(fileSystem, "test_log");
  auto memoryResult = memoryLog.invocations();

  REQUIRE(finalResult.warning == "");
  REQUIRE(memoryResult == finalResult.invocations);
}

// Test that recompaction is eventually requested
template <typename Func>
void testRecompactionTrigger(const Func &func) {
  InMemoryFileSystem fileSystem;

  for (size_t attempt = 0;; attempt++) {
    auto persistentLog = openPersistentInvocationLog(
        fileSystem,
        [] { return 0; },
        "test_log",
        InvocationLogParseResult::ParseData());

    func(*persistentLog, fileSystem);

    const auto result = parsePersistentInvocationLog(fileSystem, "test_log");

    if (result.needs_recompaction) {
      REQUIRE(attempt > 10);  // Should not request immediately
      break;
    }

    if (attempt > 10000) {
      REQUIRE(false && "Should eventually request recompaction");
      break;
    }
  }
}

// Test recompaction functionality
template <typename Func>
void testRecompact(const Func &func, int iterations = 5) {
  InMemoryFileSystem fileSystem;
  InMemoryInvocationLog memoryLog(fileSystem, [] { return 0; });

  func(memoryLog, fileSystem);

  for (size_t i = 0; i < iterations; i++) {
    auto parsedResult = parsePersistentInvocationLog(fileSystem, "test_log");
    REQUIRE(parsedResult.warning == "");

    auto persistentLog = openPersistentInvocationLog(
        fileSystem,
        [] { return 0; },
        "test_log",
        std::move(parsedResult.parse_data));

    func(*persistentLog, fileSystem);
  }

  auto parseData = recompactPersistentInvocationLog(
      fileSystem,
      [] { return 0; },
      parsePersistentInvocationLog(fileSystem, "test_log").invocations,
      "test_log");

  auto finalResult = parsePersistentInvocationLog(fileSystem, "test_log");
  REQUIRE(!finalResult.needs_recompaction);

  auto memoryResult = memoryLog.invocations();
  REQUIRE(finalResult.warning == "");
  REQUIRE(memoryResult == finalResult.invocations);

  // Validate parse data consistency
  REQUIRE(parseData.buffer);
  REQUIRE(parseData.fingerprint_entry_count == finalResult.invocations.fingerprints.size());
  REQUIRE(parseData.path_entry_count == parseData.path_ids.size());

  for (const auto &fingerprint : memoryResult.fingerprints) {
    const std::string path(fingerprint.first);
    REQUIRE(parseData.path_ids.count(path));
    REQUIRE(parseData.fingerprint_ids.count(path));
  }

  // Check for duplicate IDs
  std::unordered_set<uint32_t> fingerprintIds;
  std::unordered_set<uint32_t> pathIds;

  auto checkIdUniqueness = [&](std::unordered_set<uint32_t> &set, size_t id) {
    bool unique = set.emplace(id).second;
    REQUIRE(unique);
  };

  for (const auto &fingerprint : memoryResult.fingerprints) {
    const std::string path(fingerprint.first);
    auto pathIt = parseData.path_ids.find(path);
    if (pathIt != parseData.path_ids.end()) {
      checkIdUniqueness(pathIds, pathIt->second);
    }
    parseData.path_ids.erase(path);

    auto fingerprintIt = parseData.fingerprint_ids.find(path);
    if (fingerprintIt != parseData.fingerprint_ids.end()) {
      checkIdUniqueness(fingerprintIds, fingerprintIt->second.record_id);
    }
    parseData.fingerprint_ids.erase(path);
  }

  REQUIRE(parseData.path_ids.empty());
  REQUIRE(parseData.fingerprint_ids.empty());

  for (const auto &dir : memoryResult.created_directories) {
    REQUIRE(parseData.path_ids.count(dir.second));
  }

  // Final validation of invocations
  REQUIRE(memoryResult.fingerprints == finalResult.invocations.fingerprints);
  REQUIRE(memoryResult.entries == finalResult.invocations.entries);
  REQUIRE(memoryResult.created_directories == finalResult.invocations.created_directories);
}

// Test warning on truncated input
template <typename Func>
void testTruncationWarning(const Func &func) {
  InMemoryFileSystem fileSystem;
  constexpr size_t signatureSize = 16;

  // Create initial file
  REQUIRE(fileSystem.open("test_log", "w").second == IoError::success());
  size_t warningCount = 0;

  for (size_t i = 1;; i++) {
    REQUIRE(fileSystem.unlink("test_log") == IoError::success());

    auto persistentLog = openPersistentInvocationLog(
        fileSystem,
        [] { return 0; },
        "test_log",
        InvocationLogParseResult::ParseData());

    func(*persistentLog, fileSystem);

    auto stat = fileSystem.stat("test_log");
    auto newSize = stat.metadata.size - i;

    if (newSize <= signatureSize) {
      break;
    }

    REQUIRE(fileSystem.truncate("test_log", newSize) == IoError::success());

    auto result = parsePersistentInvocationLog(fileSystem, "test_log");
    if (!result.warning.empty()) {
      warningCount++;
    }

    // Verify truncation was handled
    auto afterResult = parsePersistentInvocationLog(fileSystem, "test_log");
    REQUIRE(afterResult.warning.empty());
  }

  REQUIRE(warningCount > 0);
}

// Comprehensive test suite for writing entries
template <typename Func>
void runWriteTests(const Func &func) {
  testRoundTrip(func);
  testMemoryLeak(func);
  testRecompactionTrigger(func);
  testMultipleCycles(func, InMemoryFileSystem());
  testRecompact(func);
  testTruncationWarning(func);
}

// Helper to create a file with header
void createFileWithHeader(
    FileSystem &fs,
    const std::string &filename,
    uint32_t version) {
  auto stream = fs.open(filename, "w");
  REQUIRE(stream.second == IoError::success());

  const std::string signature = "invocations:";
  REQUIRE(stream.first->write(
      reinterpret_cast<const uint8_t*>(signature.data()),
      signature.size(), 1) == IoError::success());

  REQUIRE(stream.first->write(
      reinterpret_cast<const uint8_t*>(&version),
      sizeof(version), 1) == IoError::success());
}

