TEST_CASE("PersistentInvocationLog") {
  InMemoryFileSystem fileSystem;
  Hash hashZero;
  std::fill(hashZero.data.begin(), hashZero.data.end(), 0);
  Hash hashOne;
  std::fill(hashOne.data.begin(), hashOne.data.end(), 1);

  SECTION("Parsing") {
    SECTION("MissingFile") {
      parsePersistentInvocationLog(fileSystem, "nonexistent");
    }

    SECTION("EmptyFile") {
      REQUIRE(fileSystem.writeFile("empty", "") == IoError::success());
      auto result = parsePersistentInvocationLog(fileSystem, "empty");
      REQUIRE(result.warning == "invalid invocation log file signature (too short)");
      REQUIRE(fileSystem.stat("empty").result == ENOENT);
    }

    SECTION("InvalidHeader") {
      createFileWithHeader(fileSystem, "bad_header", 3);
      auto result = parsePersistentInvocationLog(fileSystem, "bad_header");
      REQUIRE(result.warning == "invalid invocation log file version or bad byte order");
      REQUIRE(fileSystem.stat("bad_header").result == ENOENT);
    }

    SECTION("HeaderOnly") {
      createFileWithHeader(fileSystem, "header_only", 1);
      validateEmptyResult(parsePersistentInvocationLog(fileSystem, "header_only"));
    }
  }

  SECTION("Writing") {
    SECTION("IgnoreInputDirectory") {
      REQUIRE(fileSystem.mkdir("dir") == IoError::success());
      auto persistentLog = openPersistentInvocationLog(
          fileSystem,
          [] { return 0; },
          "test_log",
          InvocationLogParseResult::ParseData());

      executeCommand(*persistentLog, hashZero, {}, {"dir"}, {}, {});

      auto result = parsePersistentInvocationLog(fileSystem, "test_log");
      REQUIRE(result.warning == "");
      REQUIRE(result.invocations.entries.size() == 1);
      REQUIRE(result.invocations.entries.begin()->first == hashZero);
      REQUIRE(result.invocations.entries.begin()->second.output_files.empty());
      REQUIRE(result.invocations.entries.begin()->second.input_files.empty());
    }

    SECTION("EmptyLog") {
      auto emptyFunc = [](InvocationLog &log, FileSystem &fs) {};
      testRoundTrip(emptyFunc);
      testMultipleCycles(emptyFunc, InMemoryFileSystem());
    }

    SECTION("CreatedDirectory") {
      runWriteTests([](InvocationLog &log, FileSystem &fs) {
        log.createdDirectory("dir");
      });
    }

    SECTION("CreatedThenDeletedDirectory") {
      runWriteTests([](InvocationLog &log, FileSystem &fs) {
        log.createdDirectory("dir");
        log.removedDirectory("dir");
      });
    }

    SECTION("FingerprintTest") {
      runWriteTests([hashZero](InvocationLog &log, FileSystem &fs) {
        REQUIRE(fs.writeFile("test_file", "hello!") == IoError::success());
        REQUIRE(log.fingerprint("test_file") == takeFingerprint(fs, 0, "test_file"));
        executeCommand(
            log,
            hashZero,
            {"test_file"},
            {},
            {},
            {});
      });
    }

    SECTION("NoFiles") {
      runWriteTests([&](InvocationLog &log, FileSystem &fs) {
        executeCommand(log, hashZero, {}, {}, {}, {});
      });
    }

    SECTION("SingleInputFile") {
      runWriteTests([&](InvocationLog &log, FileSystem &fs) {
        executeCommand(log, hashZero, {}, {"hi"}, {}, {});
      });
    }

    SECTION("VariablePathLengths") {
      runWriteTests([&](InvocationLog &log, FileSystem &fs) {
        Hash hash{};
        executeCommand(log, hash, {}, {""}, {}, {});
        hash.data[0]++;
        executeCommand(log, hash, {}, {"1"}, {}, {});
        hash.data[0]++;
        executeCommand(log, hash, {}, {"12"}, {}, {});
        hash.data[0]++;
        executeCommand(log, hash, {}, {"123"}, {}, {});
        hash.data[0]++;
        executeCommand(log, hash, {}, {"1234"}, {}, {});
        hash.data[0]++;
        executeCommand(log, hash, {}, {"12345"}, {}, {});
      });
    }

    SECTION("TwoInputFiles") {
      runWriteTests([&](InvocationLog &log, FileSystem &fs) {
        executeCommand(
            log,
            hashZero,
            {},
