// Basic runtime class implementations for testing event handling
struct MockSplashScreen : implements<MockSplashScreen, ISplashScreen>
{
    operator SplashScreen() const noexcept
    {
        SplashScreen result = nullptr;
        copy_from_abi(result, to_abi<ISplashScreen>(this));
        return result;
    }

    event<TypedEventHandler<SplashScreen, Windows::Foundation::IInspectable>> m_onDismissed;

    Rect ImageLocation()
    {
        m_onDismissed(*this, nullptr);
        return {};
    }

    event_token Dismissed(const TypedEventHandler<SplashScreen, Windows::Foundation::IInspectable> & handler)
    {
        return m_onDismissed.add(handler);
    }

    void Dismissed(event_token cookie)
    {
        m_onDismissed.remove(cookie);
    }
};

struct MockClipboardStatics : implements<MockClipboardStatics, IClipboardStatics>
{
    event<EventHandler<IInspectable>> m_onContentChanged;

    DataPackageView GetContent() const { return nullptr; }
    void Flush() const {}
    void Clear() const {}

    void SetContent(const DataPackage &)
    {
        m_onContentChanged(*this, nullptr);
    }

    event_token ContentChanged(const EventHandler<IInspectable> & handler)
    {
        return m_onContentChanged.add(handler);
    }

    void ContentChanged(event_token token)
    {
        m_onContentChanged.remove(token);
    }
};

struct MockClipboard
{
    static IClipboardStatics GetStatics()
    {
        static IClipboardStatics s_statics = make<MockClipboardStatics>();
        return s_statics;
    }

    static void SetContent(const DataPackage & content)
    {
        GetStatics().SetContent(content);
    }

    static event_token ContentChanged(const Windows::Foundation::EventHandler<Windows::Foundation::IInspectable> & changeHandler)
    {
        return GetStatics().ContentChanged(changeHandler);
    }

    using ContentChanged_revoker = impl::factory_event_revoker<IClipboardStatics, &impl::abi_t<Windows::ApplicationModel::DataTransfer::IClipboardStatics>::remove_ContentChanged>;

    static ContentChanged_revoker ContentChanged(auto_revoke_t, const Windows::Foundation::EventHandler<Windows::Foundation::IInspectable> & changeHandler)
    {
        auto factory = GetStatics();
        return{ factory, factory.ContentChanged(changeHandler) };
    }

    static void ContentChanged(event_token token)
    {
        GetStatics().ContentChanged(token);
    }
};

// Test that the projection provides correct auto_revoke functionality for instance events
TEST_CASE("testing instance event revokers")
{
    ISplashScreen splash = make<MockSplashScreen>();
    uint32_t triggerCount = 0;

    SplashScreen::Dismissed_revoker // revoker type alias exists
        r = splash.Dismissed(auto_revoke, // auto_revoke flag is mandatory
                             [&](auto && ...)
                             {
                                 ++triggerCount;
                             });

    splash.ImageLocation(); // fire event
    REQUIRE(triggerCount == 1); // handler executed once

    r.revoke();
    r.revoke(); // double revoke is safe
    splash.ImageLocation(); // fire again
    REQUIRE(triggerCount == 1); // no additional calls after revoke

    {
        SplashScreen::Dismissed_revoker // revoker type alias exists
            localScope = splash.Dismissed(auto_revoke, // auto_revoke flag required
                                          [&](auto && ...)
            {
                ++triggerCount;
            });

        splash.ImageLocation(); // fire event
        REQUIRE(triggerCount == 2); // handler called again

        // destructor handles automatic revocation
    }

    splash.ImageLocation(); // fire event
    REQUIRE(triggerCount == 2); // no further calls after scope exit
}

// Test that revokers work correctly with factory-based events
TEST_CASE("testing factory event revokers")
{
    uint32_t triggerCount = 0;

    Clipboard::ContentChanged_revoker // revoker type alias exists
        r = MockClipboard::ContentChanged(auto_revoke, // auto_revoke flag required
                                          [&](auto && ...)
                                          {
                                              ++triggerCount;
                                          });

    MockClipboard::SetContent(nullptr);
    REQUIRE(triggerCount == 1); // handler invoked

    r.revoke();
    r.revoke(); // redundant revoke is harmless
    MockClipboard::SetContent(nullptr);
    REQUIRE(triggerCount == 1); // no additional calls after revoke

    {
        Clipboard::ContentChanged_revoker // revoker type alias exists
            scopedRevoker = MockClipboard::ContentChanged(auto_revoke, // auto_revoke flag required
                                                          [&](auto && ...)
                                                          {
                                                              ++triggerCount;
                                                          });

        MockClipboard::SetContent(nullptr); // fire event
        REQUIRE(triggerCount == 2); // handler called again

        // destructor automatically revokes
    }

    MockClipboard::SetContent(nullptr); // fire event
    REQUIRE(triggerCount == 2); // no further calls after scope exit
}

