typedef int ScreenUnit;

ScreenUnit getBaseCharWidth()                { return 9; /*TODO: retrieve from system. Try: GetDialogBaseUnits*/ }
ScreenUnit getQuarterCharUnit()              { return getBaseCharWidth()/4; }
ScreenUnit getBorderThickness()              { return getQuarterCharUnit()*2; }
ScreenUnit getTextPixelLength(std::size_t p_len) { return getBaseCharWidth()*p_len; }
ScreenUnit calculateTotalWidth(std::size_t p_textLength)
{
    return 2 * getBorderThickness() + getTextPixelLength(p_textLength);
}

struct StringSizeChecker
{
    bool operator()(const std::string& p_first, const std::string& p_second)
    {
        return p_first.length() < p_second.length();
    }
};

