// Convert a long integer to a Pascal-style string (Str255)
void LongToPascalString(long value, Str255 outputString)
{
	int result = snprintf(outputString + 1, 254, "%ld", value);
	outputString[0] = (result < 0 || result > 255) ? 0 : static_cast<unsigned char>(result);
}

// Convert a long integer to a C-style string (null-terminated), return length
int LongToCString(long value, Str255 buffer)
{
	return snprintf(buffer, 256, "%ld", value);
}

// Retrieve a string from a STR# resource by index
void GetStringFromList(Str255 outString, short resourceID, short entryIndex)
{
	outString[0] = '\0';
	Handle stringListHandle = GetResource('STR#', resourceID);
	if (!stringListHandle)
		return;

	memstream substream(*stringListHandle, GetHandleSize(stringListHandle));
	Pomme::BigEndianIStream inputStream(substream);

	int16_t totalStrings = inputStream.Read<int16_t>();
	if (entryIndex > totalStrings) // indices are 1-based, so '>' is correct
	{
		ReleaseResource(stringListHandle);
		return;
	}

	// Skip preceding strings to reach the desired one
	uint8_t stringLength = 0;
	for (int j = 1; j < entryIndex; ++j) // entryIndex starts at 1
	{
		stringLength = inputStream.Read<uint8_t>();
		inputStream.Skip(stringLength);
	}

	stringLength = inputStream.Read<uint8_t>();
	inputStream.Read(outString, stringLength);
	outString[stringLength] = '\0';

	static_assert(sizeof(Str255) == 256);
	ReleaseResource(stringListHandle);
}

