#include <iostream>
#include <vector>
#include "ds_stack.h"

// Modified Stack implementation with renamed variables and minor stylistic changes
Stack::Stack() {
  data = std::vector<int>();
}

Stack::~Stack() {}

bool Stack::isEmpty() const {
  return data.empty();
}

int Stack::peek() const {
  if (!isEmpty()) {
    return data.back();
  } else {
    throw std::out_of_range("The stack is empty");
  }
}

void Stack::push(int value) {
  data.push_back(value);
}

int Stack::pop() {
  if (!isEmpty()) {
    int lastElement = data.back();
    data.pop_back();
    return lastElement;
  } else {
    throw std::out_of_range("The stack is empty");
  }
}

int Stack::size() const {
  return static_cast<int>(data.size());
}

void Stack::show() const {
  for (size_t index = 0; index < data.size(); ++index) {
    std::cout << data[index] << " ";
  }
}

int main() {
  Stack s;

  // Output: true.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;

  s.push(10);
  s.push(20);
  s.push(30);

  // Output: false; 10 20 30; 30; 3.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  std::cout << "Peek: " << s.peek() << std::endl;

  s.pop();
  s.pop();

  // Output: false; 10; 10; 1.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  std::cout << "Peek: " << s.peek() << std::endl;

  s.pop();

  // Output: true; ; 0.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;

  return 0;
}

