#include <vespa/vespalib/testkit/test_kit.h>
#include <vespa/searchlib/fef/indexproperties.h>
#include <vespa/searchlib/fef/properties.h>
#include <limits>
using namespace search::fef;
using namespace search::fef::indexproperties;

struct CloneVisitor : public IPropertiesVisitor
{
    Properties &target;
    CloneVisitor(Properties &p) : target(p) {}
    virtual void visitProperty(const Property::Value &key,
                               const Property &values) override
    {
        for (uint32_t idx = 0; idx < values.size(); ++idx) {
            target.add(key, values.getAt(idx));
        }
    }
};

Properties build_properties(std::initializer_list<std::pair<const char *, std::initializer_list<const char *> > > items) {
    Properties props;
    for (const auto &item: items) {
        vespalib::string key_name = item.first;
        for (vespalib::string val: item.second) {
            props.add(key_name, val);
        }
    }
    return props;
}

TEST("require that namespace visitation works with clone") {
    Properties source = build_properties({    {"foo",   {"outside"}},
                                             {"foo.a", {"a_value"}},
                                             {"foo.b", {"b_value"}},
                                             {"foo.",  {"outside"}}
                                         });
    Properties destination;
    CloneVisitor cloner(destination);
    source.visitNamespace("foo", cloner);
    EXPECT_EQUAL(2u, destination.numKeys());
    EXPECT_EQUAL(destination.lookup("a").get(), Property::Value("a_value"));
    EXPECT_EQUAL(destination.lookup("b").get(), Property::Value("b_value"));
}

TEST("test basic property operations") {
    { // empty lookup result
        Property prop;
        EXPECT_EQUAL(prop.found(), false);
        EXPECT_EQUAL(prop.get(), Property::Value(""));
        EXPECT_EQUAL(prop.get("fb"), Property::Value("fb"));
        EXPECT_EQUAL(prop.size(), 0u);
        EXPECT_EQUAL(prop.getAt(0), Property::Value(""));
    }

    { // add / count / remove
        Properties p = build_properties({    {"a", {"a1", "a2", "a3"}},
                                            {"b", {"b1", "b2"}},
                                            {"c", {"c1"}}
                                        });
        const Properties &pc = p;
        EXPECT_EQUAL(pc.numKeys(), 3u);
        EXPECT_EQUAL(pc.numValues(), 6u);
        EXPECT_EQUAL(pc.count("a"), 3u);
        EXPECT_EQUAL(pc.count("b"), 2u);
        EXPECT_EQUAL(pc.count("c"), 1u);
        EXPECT_EQUAL(pc.count("d"), 0u);

        p.remove("d");
        EXPECT_EQUAL(pc.numKeys(), 3u);
        EXPECT_EQUAL(pc.numValues(), 6u);
        EXPECT_EQUAL(pc.count("a"), 3u);
        EXPECT_EQUAL(pc.count("b"), 2u);
        EXPECT_EQUAL(pc.count("c"), 1u);
        EXPECT_EQUAL(pc.count("d"), 0u);

        p.remove("c");
        EXPECT_EQUAL(pc.numKeys(), 2u);
        EXPECT_EQUAL(pc.numValues(), 5u);
        EXPECT_EQUAL(pc.count("a"), 3u);
