#include "ShaderImporter.h"
#include "EngineCore/Renderer/Material/Shader.h"
#include "RenderAPI/Interface/Shader.h"

namespace cube
{
    Resource* ShaderImporter::LoadResource(SPtr<platform::File>& stream, const FrameJsonValue& metadata)
    {
        uint64_t fileSize = stream->GetFileSize();
        char* buffer = (char*)malloc(fileSize + 1);
        uint64_t bytesRead = 0;
        stream->Read(buffer, fileSize, bytesRead);
        buffer[fileSize] = '\0';

        ShaderCompileDesc compileInfo = ExtractCompileSettings(metadata);
        render::ShaderAttribute shaderInit;
        shaderInit.language = compileInfo.language;
        shaderInit.type = compileInfo.type;
        shaderInit.entryPoint = compileInfo.entryPoint.c_str();
        shaderInit.code = buffer;

        Shader* compiledShader = new Shader();
        compiledShader->_LoadShader(mDevice, shaderInit);
        free(buffer);

        return compiledShader;
    }

    ShaderCompileDesc ShaderImporter::ExtractCompileSettings(const FrameJsonValue& metadata)
    {
        using namespace render;
        ShaderCompileDesc settings;

        U8String lang = metadata["language"].GetString();
        U8String shaderType = metadata["type"].GetString();
        U8String entryName = metadata["entry_point"].GetString();

        if(lang == "glsl") {
            settings.language = ShaderLanguage::GLSL;
        } else if(lang == "hsls") {
            settings.language = ShaderLanguage::HLSL;
        } else if(lang == "spir-v") {
            settings.language = ShaderLanguage::SPIRV;
        }

        if(shaderType == "vertex") {
            settings.type = ShaderType::Vertex;
        } else if(shaderType == "fragment" || shaderType == "pixel") {
            settings.type = ShaderType::Pixel;
        } else if(shaderType == "compute") {
            settings.type = ShaderType::Compute;
        }

        settings.entryPoint = entryName;
        return settings;
    }
} // namespace cube

#include "caf/detail/set_thread_name.hpp"
#include "caf/config.hpp"
#ifndef CAF_WINDOWS
#  include <pthread.h>
#endif // CAF_WINDOWS
#if defined(CAF_LINUX)
#  include <sys/prctl.h>
#elif defined(CAF_BSD) && !defined(CAF_NET_BSD)
#  include <pthread_np.h>
#endif // defined(...)
#include <thread>
#include <type_traits>

namespace caf::detail {

void set_thread_name(const char* thread_label) {
  CAF_IGNORE_UNUSED(thread_label);
#ifdef CAF_WINDOWS
  // no-op on Windows
#else // CAF_WINDOWS
  static_assert(std::is_same<std::thread::native_handle_type, pthread_t>::value,
                "std::thread not based on pthread_t");
#  if defined(CAF_MACOS)
  pthread_setname_np(thread_label);
#  elif defined(CAF_LINUX)
  prctl(PR_SET_NAME, thread_label, 0, 0, 0);
#  elif defined(CAF_NET_BSD)
  pthread_setname_np(pthread_self(), thread_label, NULL);
#  elif defined(CAF_BSD)
  pthread_set_name_np(pthread_self(), thread_label);
#  endif // defined(...)
#endif   // CAF_WINDOWS
}

} // namespace caf::detail

