// Test trace-level message routing
TEST( LogrLevelsRouting, TraceMessages )  // NOLINT
{
    logr_test::logger_mock_t<> logger_instance( logr::log_message_level::trace );
    InSequence sequence;
    EXPECT_CALL( logger_instance, log_message_trace( An< std::string_view >() ) );
    EXPECT_CALL( logger_instance, log_message_trace( _, An< std::string_view >() ) );
    EXPECT_CALL( logger_instance, log_message_trace( An< std::string_view >() ) );
    EXPECT_CALL( logger_instance, log_message_trace( _, An< std::string_view >() ) );
    EXPECT_CALL( logger_instance, log_message_trace( An< std::string_view >() ) );
    EXPECT_CALL( logger_instance, log_message_trace( _, An< std::string_view >() ) );

    logger_instance.trace( "sample [raw message]" );
    logger_instance.trace( LOGR_SRC_LOCATION, "sample [raw message]" );
    logger_instance.trace( []() { return "sample [cb]"; } );
    logger_instance.trace( LOGR_SRC_LOCATION, []() { return "sample [cb]"; } );
    logger_instance.trace( []( auto & output_buffer ) {
        format_to( output_buffer, "{} [{}]", "sample", "cb with explicit out" );
    } );
    logger_instance.trace( LOGR_SRC_LOCATION, []( auto & output_buffer ) {
        format_to( output_buffer, "{} [{}]", "sample", "cb with explicit out" );
    } );
}

