#include "win32_file_io.h"
#include <stdlib.h>
#include <string.h>
#ifdef DEBUG
#include <assert.h>
#else
#define assert(x)
#endif
#define UNUSED_PARAM(x) x

// Four-character codes for WAV file components
u32 constexpr kWavFourCC_RIFF = 'FFIR';
u32 constexpr kChunkData = 'atad';
u32 constexpr kFormatChunk = ' tmf';
u32 constexpr kWavType = 'EVAW';
u32 constexpr kXWMAType = 'AMWX';

// Structure to hold parsing state and buffer information
struct wav_stream_state
{
    u8 *BufferBegin = nullptr;
    size_t CurrentOffset = 0;
    size_t BufferLength = 0;
    b32 HasError = false;
};

// Helper functions for safe data access
b32 IsEndReached(wav_stream_state *State, u32 BytesNeeded = 0)
{
    b32 EndOfStream = false;

    if (!State->BufferBegin || ((State->CurrentOffset + BytesNeeded) > State->BufferLength))
    {
        State->HasError = true;
        EndOfStream = true;
    }

    return EndOfStream;
}

b32 IsValidState(wav_stream_state *State)
{
    b32 Valid = false;

    if (!State->HasError && !IsEndReached(State))
    {
        Valid = true;
    }

    return Valid;
}

void MoveForward(wav_stream_state *State, u32 OffsetAmount)
{
    if (!IsEndReached(State, OffsetAmount))
    {
        State->CurrentOffset += OffsetAmount;
    }
}

u8 *GetCurrentPointer(wav_stream_state *State)
{
    u8 *Address = nullptr;

    if (IsValidState(State))
    {
        Address = State->BufferBegin + State->CurrentOffset;
    }

    return Address;
}

u32 Peek_u32(wav_stream_state *State)
{
    u32 Value = 0;

    if (IsValidState(State))
    {
        Value = *((u32 *)GetCurrentPointer(State));
    }

    return Value;
}

u32 Read_u32(wav_stream_state *State)
{
    u32 Value = 0;

    if (IsValidState(State))
    {
        Value = *((u32 *)GetCurrentPointer(State));
        MoveForward(State, 4);
    }

    return Value;
}

u16 Read_u16(wav_stream_state *State)
{
    u16 Value = 0;

    if (IsValidState(State))
    {
        Value = *((u16 *)GetCurrentPointer(State));
        MoveForward(State, 2);
    }

    return Value;
}

// Parse RIFF header chunk
b32 ParseRIFFHeader(wav_stream_state *State, wav *Output)
{
    b32 Success = false;

    if (IsValidState(State))
    {
        u32 Signature = Peek_u32(State);
        if (Signature == kWavFourCC_RIFF)
        {
            MoveForward(State, 4);

            u32 TotalSize = Read_u32(State);
            UNUSED_PARAM(TotalSize);
            // MSDN: fileSize excludes RIFF header but includes rest of file

            u32 WaveType = Read_u32(State);
            if (WaveType == kWavType) // Only uncompressed WAV supported currently
            {
                Output->FormatType = WavType_Wave;
                Success = true;
            }
#if 0
            else if (WaveType == kXWMAType)
            {
                Output->FormatType = WavType_XWMA;
                Success = true;
            }
#endif
        }
    }

    State->HasError = !Success;
    return Success;
}

// Parse format ('fmt ') chunk
b32 ParseFormatChunk(wav_stream_state *State, wav *Output)
{
    b32 Success = false;

    if (IsValidState(State))
    {
        u32 Signature = Peek_u32(State);
        if (Signature == kFormatChunk)
        {
            MoveForward(State, 4);

            u32 ChunkSize = Read_u32(State);
            UNUSED_PARAM(ChunkSize);

            wav_format *Fmt = &Output->Format;
            Fmt->CompressionCodec = Read_u16(State);
            Fmt->ChannelCount = Read_u16(State);
            Fmt->SampleRateHz = Read_u32(State);
            Fmt->BytesPerSecond = Read_u32(State);
            Fmt->FrameSize = Read_u16(State);
            Fmt->BitsPerSample = Read_u16(State);

            if (ChunkSize > 16) // Handle optional extended format info
            {
                Fmt->ExtraByteCount = Read_u16(State);
                MoveForward(State, Fmt->ExtraByteCount); // Skip unused extension bytes
            }

            if (Fmt->CompressionCodec != 1) // Only PCM supported now
            {
                assert(0);
            }

            if (Fmt->BitsPerSample % 8 != 0) // Must be byte-aligned
            {
                assert(0);
            }

            Success = true;
        }
    }

    State->HasError = !Success;
    return Success;
}

// Parse data chunk
b32 ParseDataChunk(wav_stream_state *State, wav *Output)
{
    b32 Success = false;

    if (IsValidState(State))
    {
        u32 Signature = Peek_u32(State);
        if (Signature == kChunkData)
        {
            MoveForward(State, 4);

            Output->DataSize = Read_u32(State);
            Output->AudioData = static_cast<u8 *>(malloc(Output->DataSize));
            assert(Output->AudioData);

            memcpy(Output->AudioData, GetCurrentPointer(State), Output->DataSize);

            Success = true;
        }
    }

    return Success;
}

// Main public function to parse entire WAV file
b32 LoadWAV(u8 *InputBuffer, size_t InputSize, wav *Result)
{
    b32 Success = false;

    if (Result && InputBuffer && InputSize > 0)
    {
        wav_stream_state State;
        State.BufferBegin = InputBuffer;
        State.CurrentOffset = 0;
        State.BufferLength = InputSize;

        Success = ParseRIFFHeader(&State, Result);
        assert(Success);

        Success = ParseFormatChunk(&State, Result);
        assert(Success);

        Success = ParseDataChunk(&State, Result);
        assert(Success);
    }

    return Success;
}

// Clean up allocated resources
void DestroyWAV(wav *File)
{
    if (File)
    {
        if (File->AudioData)
        {
            free(File->AudioData);
            memset(File, 0, sizeof(wav));
        }
    }
}

#include <gtest/gtest.h>
