class SingleStateTest : public StateMachine, public ::testing::Test
{
public:
	SingleStateTest()
		: guard1(false)
		, guard2(false)
		, guard3(false)
	{
		InitStateMachine();
	}

	std::string GetLog() const { return recordedEvents; }

	std::string GetCurrentStateName() const
	{
		return StateNames.at(GetCurrentState());
	}

protected:
	bool guard1;
	bool guard2;
	bool guard3;

private:
	void AppendToLog(const std::string& event)
	{
		if (!recordedEvents.empty()) { recordedEvents += ':'; }
		recordedEvents += event;
	}

	void OnInitialAction() override { AppendToLog("Initial"); }
	void OnActionA1() override { AppendToLog("A1"); }
	void OnActionA2() override { AppendToLog("A2"); }
	void OnActionA3() override { AppendToLog("A3"); }
	void OnActionA4() override { AppendToLog("A4"); }
	void OnActionA5() override { AppendToLog("A5"); }
	void OnActionA6() override { AppendToLog("A6"); }
	void OnEntry() override { AppendToLog("Entry"); }
	void OnExit() override { AppendToLog("Exit"); }

	bool CheckGuard1() const override { return guard1; }
	bool CheckGuard2() const override { return guard2; }

	std::string recordedEvents;
};

TEST_F(SingleStateTest, InitialState)
{
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, InitialActionAndEntryActionExecuted)
{
    EXPECT_EQ("Initial:Entry", GetLog());
}

TEST_F(SingleStateTest, ActionExecutedOnInternalEvent)
{
    TriggerEvent1();
    EXPECT_EQ("Initial:Entry:A1", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, ActionExecutedTwice)
{
    TriggerEvent1();
    TriggerEvent1();
    EXPECT_EQ("Initial:Entry:A1:A1", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, TransitionToSelf)
{
    TriggerEvent2();
    EXPECT_EQ("Initial:Entry:Exit:A2:Entry", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, TransitionToFinalState)
{
    TriggerEvent3();
    EXPECT_EQ("Initial:Entry:Exit:A3", GetLog());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", GetCurrentStateName());
}

TEST_F(SingleStateTest, NoActionsExecutedInFinalState)
{
    TriggerEvent3();
    EXPECT_EQ("Initial:Entry:Exit:A3", GetLog());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", GetCurrentStateName());

    TriggerEvent1();
    TriggerEvent2();
    TriggerEvent3();

    EXPECT_EQ("Initial:Entry:Exit:A3", GetLog());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", GetCurrentStateName());
}

TEST_F(SingleStateTest, ActionOrNoActionDependingOnGuard)
{
    guard1 = false;
    TriggerEvent4();
    EXPECT_EQ("Initial:Entry", GetLog());

    guard1 = true;
    TriggerEvent4();
    EXPECT_EQ("Initial:Entry:A4", GetLog());

    guard1 = false;
    TriggerEvent4();
    EXPECT_EQ("Initial:Entry:A4", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, ActionOrOtherActionDependingOnGuard)
{
    guard2 = true;
    TriggerEvent5();
    EXPECT_EQ("Initial:Entry:A5", GetLog());

    guard2 = false;
    TriggerEvent5();
    EXPECT_EQ("Initial:Entry:A5:A6", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

