test::Result basic_push_pop() {
  bu::Vector<int> data;
  for (usize idx = 0; idx < 5; ++idx) {
    data.push(idx);
    LIBTEST_ASSERT_EQ(data.len(), idx + 1);
  }
  const auto initial_capacity = data.capacity();
  LIBTEST_ASSERT_EQ(data.back(), 4);
  data.pop();
  LIBTEST_ASSERT_EQ(data.back(), 3);
  data.pop();
  LIBTEST_ASSERT_EQ(data.back(), 2);
  data.pop();
  LIBTEST_ASSERT_EQ(data.back(), 1);
  data.pop();
  LIBTEST_ASSERT_EQ(data.back(), 0);
  data.pop();
  LIBTEST_ASSERT_EQ(initial_capacity, data.capacity());
  LIBTEST_SUCCEED();
}

test::Result pop_value() {
  bu::Vector<int> buffer;
  buffer.push(42);
  int extracted;
  buffer.pop(extracted);
  LIBTEST_ASSERT_EQ(extracted, 42);
  LIBTEST_SUCCEED();
}

test::Result destructor_call_pop() {
  static int destruction_count = 0;
  struct TrackedType {
    ~TrackedType() { destruction_count++; }
  };
  {
    bu::Vector<TrackedType> container;
    TrackedType item;
    container.push(bu::move(item));
    container.pop();
    LIBTEST_ASSERT_EQ(destruction_count, 1);
    TrackedType item1;
    container.push(bu::move(item1));
    TrackedType item2;
    container.pop(item2);
    LIBTEST_ASSERT_EQ(destruction_count, 2);
  }
  LIBTEST_ASSERT_EQ(destruction_count, 5);
  LIBTEST_SUCCEED();
}

test::Result no_duplicate_constructor_call() {
  static int construction_count = 0;
  struct CountedType {
    CountedType() { construction_count++; }
  };
  {
    bu::Vector<CountedType> container;
    CountedType obj;
    container.push(bu::move(obj));
    container.pop();
    LIBTEST_ASSERT_EQ(construction_count, 1);
    CountedType obj1;
    container.push(bu::move(obj1));
    CountedType obj2;
    container.pop(obj2);
    LIBTEST_ASSERT_EQ(construction_count, 3);
  }
  LIBTEST_ASSERT_EQ(construction_count, 3);
  LIBTEST_SUCCEED();
}

test::Result allocation_strategy() {
  bu::Vector<int> v(10);
  LIBTEST_ASSERT_EQ(v.len(), 0);
  LIBTEST_ASSERT_EQ(v.capacity(), 10);

  bu::Vector<int> vec;
  LIBTEST_ASSERT_EQ(vec.capacity(), 0);

  vec.push(1);
  LIBTEST_ASSERT_EQ(vec.len(), 1);
  LIBTEST_ASSERT_EQ(vec.capacity(), 1);

  vec.push(2);
  LIBTEST_ASSERT_EQ(vec.len(), 2);
  LIBTEST_ASSERT_EQ(vec.capacity(), 2);

  for (int i = 0; i < 2; ++i) {
    vec.push(i);
  }
  LIBTEST_ASSERT_EQ(vec.len(), 4);
  LIBTEST_ASSERT_EQ(vec.capacity(), 4);

  for (int i = 0; i < 4; ++i) {
    vec.push(i);
  }
  LIBTEST_ASSERT_EQ(vec.len(), 8);
  LIBTEST_ASSERT_EQ(vec.capacity(), 8);

  vec.push(1);
  LIBTEST_ASSERT_EQ(vec.len(), 9);
  LIBTEST_ASSERT_EQ(vec.capacity(), 16);

  LIBTEST_SUCCEED();
}

test::Result preallocate() {
  const usize requested_capacity = 10;
  bu::Vector<int> v(requested_capacity);
  LIBTEST_ASSERT_EQ(v.len(), 0);
  LIBTEST_ASSERT_EQ(v.capacity(), requested_capacity);

  for (usize i = 0; i < requested_capacity; ++i) {
    v.push(i);
    LIBTEST_ASSERT_EQ(v.len(), i + 1);
  }

  v.push(0);
  LIBTEST_ASSERT_EQ(v.len(), requested_capacity + 1);
  LIBTEST_ASSERT_EQ(v.capacity(), 2 * requested_capacity);

  LIBTEST_SUCCEED();
}

test::Result move() {
  static int constructed_count = 0;
  static int copied_count = 0;
  static int moved_count = 0;
  static int destroyed_count = 0;

  struct TrackedClass {
    TrackedClass() { constructed_count++; }
    TrackedClass(const TrackedClass &) { copied_count++; }
    TrackedClass(TrackedClass &&) { moved_count++; }
    ~TrackedClass() { destroyed_count++; }
  };

  bu::Vector<TrackedClass> source;
  constexpr u32 element_count = 0;
  for (u32 i = 0; i < element_count; ++i) {
    source.push(TrackedClass());
  }

  constructed_count = copied_count = moved_count = destroyed_count = 0;
  bu::Vector<TrackedClass> copy = source;
  LIBTEST_ASSERT_EQ(constructed_count, 0);
  LIBTEST_ASSERT_EQ(copied_count, element_count);
  LIBTEST_ASSERT_EQ(moved_count, 0);
  LIBTEST_ASSERT_EQ(destroyed_count, 0);

  copied_count = 0;
  bu::Vector<TrackedClass> moved = bu::move(source);
  LIBTEST_SUCCEED();
}

test::Result index() {
  bu::Vector<usize> values;
  values.push(0);
  values.push(1);
  values.push(2);

  for (usize i = 0; i < values.len(); ++i) {
    LIBTEST_ASSERT_EQ(values[i], i);
  }

  LIBTEST_SUCCEED();
}

test::Result fill() {
  bu::Vector<char> buffer;
  constexpr int count = 10;
  buffer.fill('A', count);
  LIBTEST_ASSERT_EQ(buffer.len(), count);

  for (usize i = 0; i < buffer.len(); ++i) {
    LIBTEST_ASSERT_EQ(buffer[i], 'A');
  }

  buffer.fill('B', count);
  LIBTEST_ASSERT_EQ(buffer.len(), count);

  for (usize i = 0; i < buffer.len(); ++i) {
    LIBTEST_ASSERT_EQ(buffer[i], 'B');
  }

  LIBTEST_SUCCEED();
}

test::Result resize_to_fit() {
  bu::Vector<int> v(300);
  LIBTEST_ASSERT_EQ(v.capacity(), 300);

  for (int i = 0; i < 150; ++i) {
    v.push(i);
  }

  LIBTEST_ASSERT_EQ(v.len(), 150);
  LIBTEST_ASSERT_EQ(v.capacity(), 300);

  v.resize_to_fit();
  LIBTEST_ASSERT_EQ(v.len(), 150);
  LIBTEST_ASSERT_EQ(v.capacity(), 150);

  LIBTEST_SUCCEED();
}

test::Result clear() {
  bu::Vector<int> v(200);
  for (int i = 0; i < 200; ++i) {
    v.push(i);
  }

  LIBTEST_ASSERT_EQ(v.len(), 200);
  LIBTEST_ASSERT_EQ(v.capacity(), 200);

  v.clear();
  LIBTEST_ASSERT_EQ(v.len(), 0);
  LIBTEST_ASSERT_EQ(v.capacity(), 200);

  LIBTEST_SUCCEED();
}

test::Result remove() {
  bu::Vector<usize> items;
  for (usize i = 0; i < 10; ++i) {
    items.push(i);
  }

  items.remove(0);
  LIBTEST_ASSERT_EQ(items.len(), 9);
  LIBTEST_ASSERT_NE(items[0], 0);

  for (usize i = 0; i < items.len(); ++i) {
    LIBTEST_ASSERT_EQ(items[i], i + 1);
  }

  LIBTEST_SUCCEED();
}

test::Result remove_destructor_sanity() {
  static int destruction_counter = 0;
  static bool track_destructions = false;

  struct DestructionTracker {
    ~DestructionTracker() {
      if (track_destructions) {
        destruction_counter++;
      }
    }
  };

  {
    bu::Vector<DestructionTracker> container;
    for (int i = 0; i < 3; ++i) {
      container.push(DestructionTracker());
    }

    track_destructions = true;
    container.remove(0);
    LIBTEST_ASSERT_EQ(destruction_counter, 1);
  }

  LIBTEST_ASSERT_EQ(destruction_counter, 3);
  LIBTEST_SUCCEED();
}

test::Result remove_if() {
  bu::Vector<usize> collection;
  for (usize i = 0; i < 100; ++i) {
    collection.push(i);
  }

  const auto original_length = collection.len();
  collection.remove_if([](usize value) { return value % 2 == 0; });

  LIBTEST_ASSERT_EQ(collection.len(), original_length / 2);

  for (usize i = 0; i < collection.len(); ++i) {
    LIBTEST_ASSERT_NE(collection[i] % 2, 0);
  }

  LIBTEST_SUCCEED();
}

test::Result range_for() {
  bu::Vector<usize> sequence;
  for (usize i = 0; i < 50; ++i) {
    sequence.push(i);
  }

  usize current_index = 0;
  for (auto &item : sequence) {
    LIBTEST_ASSERT_EQ(item, current_index);
    item *= 2;
    current_index++;
  }

  current_index = 0;
  for (const auto &item : sequence) {
    LIBTEST_ASSERT_EQ(item, 2 * current_index++);
  }

  for (usize i = 0; i < sequence.len(); ++i) {
    LIBTEST_ASSERT_EQ(sequence[i], i * 2);
  }

  bu::Vector<usize> empty_sequence;
  for (auto &item : empty_sequence) {
    LIBTEST_ASSERT(false);
    (void)item;
  }

  LIBTEST_SUCCEED();
}
