#include "normalizeString.h"
#include <set>

// Process XLSX file asynchronously with configurable options
namespace xlsx
{
    void readXlsxAsync(const Napi::CallbackInfo& info)
    {
        Napi::Env env = info.Env();

        // Validate callback function presence and argument count
        if (info.Length() != 8) 
        {
            Napi::TypeError::New(env, "xlsx-util: invalid argument count - expected 8").ThrowAsJavaScriptException();
            return;
        }

        if (!info[7].IsFunction()) 
        {
            Napi::TypeError::New(env, "xlsx-util: invalid callback function [arg7]").ThrowAsJavaScriptException();
            return;
        }

        Napi::Function callback = info[7].As<Napi::Function>();

        // Validate filename parameter
        if (!info[0].IsString()) 
        {
            auto error = new AsyncError{callback, "xlsx-util: [arg0] must be a string [filepath]"};
            error->Queue();
            return;
        }

        const std::string filePath = info[0].As<Napi::String>().Utf8Value();

        // Parse headers flag
        bool readHeaders = false;
        if (!info[1].IsUndefined() && !info[1].IsNull() && info[1].IsBoolean()) 
        {
            readHeaders = info[1].ToBoolean();
        }

        // Build transformation map for column names
        std::map<std::string, std::string> renameMap;
        if (!info[2].IsUndefined() && !info[2].IsNull() && info[2].IsObject()) 
        {
            auto obj = info[2].As<Napi::Object>();
            auto keys = obj.GetPropertyNames();
            auto keyCount = keys.Length();

            for (decltype(keyCount) idx = 0; idx < keyCount; ++idx) 
            {
                auto keyNapi = keys.Get(idx).As<Napi::String>();
                const std::string key = keyNapi.Utf8Value();

                auto valueNapi = obj.Get(keyNapi);
                if (valueNapi.IsString()) 
                {
                    auto valNapi = valueNapi.As<Napi::String>();
                    const std::string value = valNapi.Utf8Value();

                    if (!key.empty() && !value.empty()) 
                    {
                        renameMap[normalizeString(key)] = value;
                    }
                }
            }
        }

        // Collect columns to delete
        std::set<std::string> deleteColumns;
        if (!info[3].IsUndefined() && !info[3].IsNull() && info[3].IsArray()) 
        {
            auto delArray = info[3].As<Napi::Array>();
            for (int i = 0; i < delArray.Length(); ++i) 
            {
                auto item = delArray.Get(i);
                if (item.IsString()) 
                {
                    deleteColumns.insert(item.As<Napi::String>().Utf8Value());
                }
            }
        }

        // Pascal case words configuration
        std::set<std::string> pascalWords;
        if (!info[5].IsUndefined() && !info[5].IsNull() && info[5].IsArray()) 
        {
            auto arr = info[5].As<Napi::Array>();
            for (int i = 0; i < arr.Length(); ++i) 
            {
                auto item = arr.Get(i);
                if (item.IsString()) 
                {
                    pascalWords.insert(item.As<Napi::String>().Utf8Value());
                }
            }
        }

        // String columns specification
        std::set<std::string> stringFields;
        if (!info[6].IsUndefined() && !info[6].IsNull() && info[6].IsArray()) 
        {
            auto strCols = info[6].As<Napi::Array>();
            for (int i = 0; i < strCols.Length(); ++i) 
            {
                auto item = strCols.Get(i);
                if (item.IsString()) 
                {
                    stringFields.insert(item.As<Napi::String>().Utf8Value());
                }
            }
        }

        // Pascal case conversion flag
        bool applyPascalCase = false;
        if (!info[4].IsUndefined() && !info[4].IsNull() && info[4].IsBoolean()) 
        {
            applyPascalCase = info[4].ToBoolean();
        }

        // Create and queue async reader
        AsyncReader* reader = new AsyncReader{
            filePath,
            readHeaders,
            renameMap,
            deleteColumns,
            applyPascalCase,
            pascalWords,
            stringFields,
            callback
        };

        reader->Queue();
    }
}

