void FUnrealcvServer::SetupWorldController()
{
	UWorld* ActiveWorld = GetActiveWorld();
	if (IsValid(ActiveWorld) && !WorldManager.IsValid())
	{
		UE_LOG(LogTemp, Display, TEXT("FUnrealcvServer::Tick Creating WorldController"));
		this->WorldManager = Cast<AUnrealcvWorldController>(ActiveWorld->SpawnActor(AUnrealcvWorldController::StaticClass()));

		if (this->WorldManager != nullptr)
		{
			this->WorldManager->InitializeWorld();
		}
		else
		{
			UE_LOG(LogUnrealCV, Error, TEXT("Failed to spawn WorldController"));
		}
	}
}

/** Only available during gameplay */
APawn* FUnrealcvServer::GetControlledPawn()
{
	UWorld* CurrentWorld = GetWorld();
	if (!IsValid(CurrentWorld))
	{
		return nullptr;
	}

	APlayerController* Controller = CurrentWorld->GetFirstPlayerController();
	if (!IsValid(Controller))
	{
		return nullptr;
	}

	PawnReference = Controller->GetPawn();
	return PawnReference;
}

