/** Select and return the most appropriate world for current context
 * GWorld returns EditorWorld in editor mode, which is usually not desired.
 */
UWorld* FUnrealcvServer::GetWorld()
{
	UWorld* TargetWorld = nullptr;
#if WITH_EDITOR
	UEditorEngine* EditorInstance = Cast<UEditorEngine>(GEngine);
	if (IsValid(EditorInstance))
	{
		if (EditorInstance->GetPIEWorldContext() != nullptr)
		{
			TargetWorld = EditorInstance->GetPIEWorldContext()->World();
		}
		else
		{
			TargetWorld = EditorInstance->GetEditorWorldContext().World();
		}
	}
#else
	UGameEngine* GameInstance = Cast<UGameEngine>(GEngine);
	if (IsValid(GameInstance))
	{
		TargetWorld = GameInstance->GetGameWorld();
	}
	else
	{
		UE_LOG(LogUnrealCV, Error, TEXT("GameEngine is invalid"));
	}
#endif

	if (IsValid(TargetWorld))
	{
		return TargetWorld;
	}
	else
	{
		UE_LOG(LogUnrealCV, Error, TEXT("UWorld pointer is invalid: %p."), TargetWorld);
		return nullptr;
	}
}

