void FUnrealcvServer::ExecuteCommand(FRequest& Request)
{
	SCOPE_CYCLE_COUNTER(STAT_ProcessRequest);
	FExecStatus Result = CommandRouter->Execute(Request.Message);
	UE_LOG(LogUnrealCV, Warning, TEXT("Response: %s"), *Result.GetMessage());

	FString Header = FString::Printf(TEXT("%d:"), Request.RequestId);
	TArray<uint8> ResponseData;
	FExecStatus::BinaryArrayFromString(Header, ResponseData);
	ResponseData += Result.GetData();
	TcpListener->SendData(ResponseData);
}

// Process all queued requests on each game thread tick
void FUnrealcvServer::HandlePendingRequests()
{
	while (!RequestQueue.IsEmpty()) 
	{
		FRequest CurrentRequest;
		bool Success = RequestQueue.Dequeue(CurrentRequest);
		int32 RequestIdentifier = CurrentRequest.RequestId;

		if (CurrentRequest.Message.StartsWith(TEXT("vbatch")))
		{
			BatchSize = FCString::Atoi(*CurrentRequest.Message.Replace(TEXT("vbatch"), TEXT("")));
			if (BatchSize < 1)
			{
				UE_LOG(LogUnrealCV, Warning, TEXT("Cannot process batch size smaller than 1"));
			}

			FString Header = FString::Printf(TEXT("%d:"), RequestIdentifier);
			TArray<uint8> ReplyData;
			FExecStatus::BinaryArrayFromString(Header, ReplyData);
			ReplyData += FExecStatus::OK().GetData();
			TcpListener->SendData(ReplyData); // Send fake OK for vbatch
			continue;
		}
		else
		{
			BatchSize = 1;
		}

		if (BatchSize > 0) 
		{
			WorkBatch.Add(CurrentRequest);
			BatchSize -= 1;
		}

		if (BatchSize == 0) 
		{
			for (FRequest Item : WorkBatch)
			{
				ExecuteCommand(Item);
			}
			WorkBatch.Empty();
		}
	}
}

/** Message handler for server */
void FUnrealcvServer::OnRawDataReceived(const FString& Endpoint, const FString& RawData)
{
	UE_LOG(LogUnrealCV, Warning, TEXT("Request: %s"), *RawData);

	FString Pattern = "(\\d{1,8}):(.*)";
	FRegexPattern Regex(Pattern);
	FRegexMatcher Matcher(Regex, RawData);

	if (Matcher.FindNext())
	{
		FString IdString = Matcher.GetCaptureGroup(1);
		FString Content = Matcher.GetCaptureGroup(2);
		uint32 RequestId = FCString::Atoi(*IdString);

		FRequest NewRequest(Endpoint, Content, RequestId);
		RequestQueue.Enqueue(NewRequest);
	}
	else
	{
		UE_LOG(LogUnrealCV, Warning, TEXT("error: Malformed raw message '%s'"), *RawData);
	}
}

/** Error handler for server */
void FUnrealcvServer::OnConnectionError(const FString& ErrorMessage)
{
	if (Config.TerminateOnFailure)
	{
		UE_LOG(LogUnrealCV, Error, TEXT("Unexpected error from server. Requesting exit. Error message: %s"), *ErrorMessage);
		FGenericPlatformMisc::RequestExit(false);
	}
}

