#include <iostream>

// Function declarations for sorting algorithms
void mergeSort(int [], int, int);
void quickSort(int [], int, int);

int main() {
    // First array to be sorted using merge sort
    int data[] = {5, 1, 6, 2, 7, 1, 8, 2, 9, 2};
    mergeSort(data, 0, 9);

    // Output the sorted array
    for (int element : data) {
        std::cout << element << " ";
    }
    std::cout << std::endl;

    // Second array to be sorted using quick sort
    int data2[] = {5, 1, 6, 2, 7, 1, 8, 2, 9, 2};
    quickSort(data2, 0, 9);

    // Output the second sorted array
    for (int element : data2) {
        std::cout << element << " ";
    }

    return 0;
}

// Helper function to swap two elements
void swap(int *a, int *b) {
    int tempValue = *a;
    *a = *b;
    *b = tempValue;
}

// Merge function for merge sort
void merge(int arr[], int leftStart, int midPoint, int rightEnd) {
    int leftIndex, rightIndex, mergeIndex;
    int leftSize = midPoint - leftStart + 1;
    int rightSize = rightEnd - midPoint;

    int leftArray[leftSize], rightArray[rightSize];

    // Copy data to temporary arrays
    for (leftIndex = 0; leftIndex < leftSize; leftIndex++)
        leftArray[leftIndex] = arr[leftStart + leftIndex];

    for (rightIndex = 0; rightIndex < rightSize; rightIndex++)
        rightArray[rightIndex] = arr[(midPoint + 1) + rightIndex];

    // Merge the temporary arrays back into arr[]
    leftIndex = 0;
    rightIndex = 0;
    mergeIndex = leftStart;

    while (leftIndex < leftSize && rightIndex < rightSize) {
        if (leftArray[leftIndex] <= rightArray[rightIndex]) {
            arr[mergeIndex] = leftArray[leftIndex];
            leftIndex++;
        } else {
            arr[mergeIndex] = rightArray[rightIndex];
            rightIndex++;
        }
        mergeIndex++;
    }

    // Copy remaining elements of leftArray[], if any
    while (leftIndex < leftSize) {
        arr[mergeIndex] = leftArray[leftIndex];
        leftIndex++;
        mergeIndex++;
    }

    // Copy remaining elements of rightArray[], if any
    while (rightIndex < rightSize) {
        arr[mergeIndex] = rightArray[rightIndex];
        rightIndex++;
        mergeIndex++;
    }
}

// Main merge sort function
void mergeSort(int arr[], int leftStart, int rightEnd) {
    if (leftStart < rightEnd) {
        int midPoint = leftStart + (rightEnd - leftStart) / 2;
        mergeSort(arr, leftStart, midPoint);
        mergeSort(arr, midPoint + 1, rightEnd);
        merge(arr, leftStart, midPoint, rightEnd);
    }
}

// Partition function for quick sort
int partition(int arr[], int leftStart, int rightEnd) {
    int pivotValue = arr[leftStart + (rightEnd - leftStart) / 2];
    int leftPointer = leftStart - 1;
    int rightPointer = rightEnd + 1;

    while (true) {
        // Move left pointer until we find an element >= pivot
        while (arr[++leftPointer] < pivotValue);

        // Move right pointer until we find an element <= pivot
        while (arr[--rightPointer] > pivotValue);

        // If pointers crossed, return right pointer
        if (leftPointer >= rightPointer)
            return rightPointer;

        // Swap elements at left and right pointers
        swap(&arr[leftPointer], &arr[rightPointer]);
    }
}

// Main quick sort function
void quickSort(int arr[], int leftStart, int rightEnd) {
    if (rightEnd <= leftStart) 
        return;

    int partitionIndex = partition(arr, leftStart, rightEnd);
    quickSort(arr, leftStart, partitionIndex);
    quickSort(arr, partitionIndex + 1, rightEnd);
}

