// Structure representing long-range diffusion data per thread
struct LongDiffusionData {
	int dchange;
	int* mindex;      // index into memb_list[m]
	int* pindex;      // parent index in this structure
	double** state;
	double* a;
	double* b;
	double* d;
	double* rhs;
	double* af;       // efficiency factor: rall/dx^2
	double* bf;       // 1/dx^2
	double* vol;      // volume from COMPARTMENT
	double* dc;       // diffusion constant * cross-sectional area
};

// Thread-specific data container for diffusion mechanisms
struct LongDiffusionThreadData {
	int nthread;
	LongDiffusionData** ldifus;
	Memb_list** ml;
};

static int diffus_func_count = 0;
static ldifusfunc_t* diffus_funcs = nullptr;
static ldifusfunc2_t stagger_step, ode_system, matrix_solver, overall_init;

void hoc_register_diffus(ldifusfunc_t func) {
	diffus_funcs = (ldifusfunc_t*)erealloc(diffus_funcs, (diffus_func_count + 1) * sizeof(ldifusfunc_t));
	diffus_funcs[diffus_func_count] = func;
	++diffus_func_count;
}

