// Tridiagonal tree solver
extern "C" void solve_tree_system(double* upper_diag, double* diag, double* lower_diag, double* rhs_vec, int* parent_idx, int size) {
    // Forward elimination (triangulation)
	for (int idx = size - 1; idx > 0; --idx) {
		int par = parent_idx[idx];
		if (par > -1) {
			double factor = upper_diag[idx] / diag[idx];
			diag[par] -= factor * lower_diag[idx];
			rhs_vec[par] -= factor * rhs_vec[idx];
		}
	}

    // Back substitution
	for (int idx = 0; idx < size; ++idx) {
		int par = parent_idx[idx];
		if (par > -1) {
			rhs_vec[idx] -= lower_diag[idx] * rhs_vec[par];
		}
		rhs_vec[idx] /= diag[idx];
	}
}

// Dispatch to appropriate diffusion solver based on method flag
void apply_diffusion_solver(int method, NrnThread* nt) {
	ldifusfunc2_t* solver_ptr = nullptr;
	if (diffus_funcs) {
		switch (method) {
		case 0: /* staggered time stepping */
			solver_ptr = &stagger_step;
			break;
		case 1: /* ODE system */
			solver_ptr = &ode_system;
			break;
		case 2: /* matrix solving */
			solver_ptr = &matrix_solver;
			break;
		case 3: /* setup only (thread 0) */
			solver_ptr = &overall_init;
			break;
		}
		assert(solver_ptr);

		for (int i = 0; i < diffus_func_count; ++i) {
			(*diffus_funcs[i])(solver_ptr, nt);
		}
	}
}	

