// Recompute geometric coefficients when diameter changes
static void update_diffusion_coefficients(LongDiffusionData* data, int mod, int sidx, Memb_list* ml, NrnThread* _nt) {
	int i, count, mi, mpi, j, idx, pidx, vnode_total;
	Node* node, *parent_node;
	double rall_factor, dx_parent, dx_child;

	if (data->dchange == diam_change_cnt) { return; }

	vnode_total = _nt->end;
	count = ml->nodecount;
	for (i = 0; i < count; ++i) {
		mi = data->mindex[i];
		if (sidx < 0) {
			data->state[i] = ml->pdata[mi][-sidx - 1].pval;
		} else {
			data->state[i] = ml->data[mi] + sidx;
		}
		node = ml->nodelist[mi];
		pidx = data->pindex[i];
		if (pidx > -1) {
			mpi = data->mindex[pidx];
			parent_node = ml->nodelist[mpi];
			if (node->sec_node_index_ == 0) {
				rall_factor = node->sec->prop->dparam[4].val;
			} else {
				rall_factor = 1.0;
			}
			dx_child = section_length(node->sec) / ((double)(node->sec->nnode - 1));
			dx_parent = section_length(parent_node->sec) / ((double)(parent_node->sec->nnode - 1));
			data->af[i] = 2.0 * rall_factor / dx_parent / (dx_child + dx_parent);
			data->bf[i] = 2.0 / dx_child / (dx_child + dx_parent);
		}
	}
	data->dchange = diam_change_cnt;
}

// Allocate and initialize diffusion data structures
static void allocate_diffusion_data(LongDiffusionData** ptr_to_ptr, int mod, int sidx, Memb_list* ml, NrnThread* _nt) {
	LongDiffusionData* data;
	int i, count, mi, mpi, j, idx, pidx, vnode_total;
	int* node_map, *reverse_map;
	Node* node, *parent_node;
	hoc_Item* qsec;

	vnode_total = _nt->end;
	*ptr_to_ptr = data = (LongDiffusionData*)emalloc(sizeof(LongDiffusionData));
	count = ml->nodecount;
	data->dchange = 0;
	data->mindex = (int*)ecalloc(count, sizeof(int));
	data->pindex = (int*)ecalloc(count, sizeof(int));
	data->state = (double**)ecalloc(count, sizeof(double*));
	data->a = (double*)ecalloc(count, sizeof(double));
	data->b = (double*)ecalloc(count, sizeof(double));
	data->d = (double*)ecalloc(count, sizeof(double));
	data->rhs = (double*)ecalloc(count, sizeof(double));
	data->af = (double*)ecalloc(count, sizeof(double));
	data->bf = (double*)ecalloc(count, sizeof(double));
	data->vol = (double*)ecalloc(count, sizeof(double));
	data->dc = (double*)ecalloc(count, sizeof(double));

	// Build mapping from global node index to local memb_list index
	node_map = (int*)ecalloc(vnode_total, sizeof(int));
	reverse_map = (int*)ecalloc(count, sizeof(int));
	for (i = 0; i < vnode_total; ++i) {
		node_map[i] = -1;
	}
	for (i = 0; i < count; ++i) {
		node_map[ml->nodelist[i]->v_node_index] = i;
	}

	// Order indices for efficient Gaussian elimination
	for (i = 0, j = 0; i < vnode_total; ++i) {
		if (node_map[i] > -1) {
			data->mindex[j] = node_map[i];
			reverse_map[node_map[i]] = j;
			parent_node = _nt->_v_parent[i];
			pidx = node_map[parent_node->v_node_index];
			if (pidx == -1) {
				parent_node = _nt->_v_parent[parent_node->v_node_index];
				if (parent_node) {
					pidx = node_map[parent_node->v_node_index];
					if (pidx < 0) {
						Section* psec = _nt->_v_node[i]->sec->parentsec;
						if (psec) {
							parent_node = psec->pnode[0];
							pidx = node_map[parent_node->v_node_index];
						}
					}
				} else {
					Section* psec = _nt->_v_node[i]->sec->parentsec;
					if (psec) {
						parent_node = psec->pnode[0];
						pidx = node_map[parent_node->v_node_index];
					}
				}
			}
			if (pidx > -1) {
				data->pindex[j] = reverse_map[pidx];
			} else {
				data->pindex[j] = -1;
			}
			++j;
		}
	}
	update_diffusion_coefficients(data, mod, sidx, ml, _nt);

#if 0
	for (i=0; i < count; ++i) {
printf("i=%d pin=%d mi=%d :%s node %d state[(%i)]=%g\n", i, data->pindex[i],
	data->mindex[i], secname(ml->nodelist[data->mindex[i]]->sec),
	ml->nodelist[data->mindex[i]]->sec_node_index_
	, sidx, data->state[i][0]);
	}
#endif
	free(node_map);
	free(reverse_map);
}

// Overall setup function — called once by thread 0 at end of v_setup_vectors
static void setup_diffusion_overall(int mod, ldifusfunc3_t difffunc, void** vdata, int argi, int sidx, int didx, NrnThread* _nt) {
	int i;
	LongDiffusionThreadData** ptr_to_ptr = (LongDiffusionThreadData**)vdata;
	LongDiffusionThreadData* tdata = *ptr_to_ptr;
	if (tdata) {
		free(tdata->ml);
		for (i = 0; i < tdata->nthread; ++i) {
			if (tdata->ldifus[i]) {
				free_diffusion_data(tdata->ldifus + i);
			}
		}
		free(tdata->ldifus);
		free(tdata);
		*ptr_to_ptr = nullptr;
	}

	// Allocate new top-level structure
	*ptr_to_ptr = (LongDiffusionThreadData*)emalloc(sizeof(LongDiffusionThreadData));
	tdata = *ptr_to_ptr;
	tdata->nthread = nrn_nthread;
	tdata->ldifus = (LongDiffusionData**)ecalloc(nrn_nthread, sizeof(LongDiffusionData*));
	tdata->ml = (Memb_list**)ecalloc(nrn_nthread, sizeof(Memb_list*));

	// Populate per-thread data
	for (i = 0; i < nrn_nthread; ++i) {
		NrnThreadMembList* tml;
		for (tml = nrn_threads[i].tml; tml; tml = tml->next) {
			if (tml->index == mod) {
				tdata->ml[i] = tml->ml;
				allocate_diffusion_data(tdata->ldifus + i, mod, sidx, tml->ml, nrn_threads + i);
				break;
			}
		}
	}
}

// Helper functions to extract thread-local data
static LongDiffusionData* get_diffusion_data(void** vdata, int tid) {
	LongDiffusionThreadData** ptr_to_ptr = (LongDiffusionThreadData**)vdata;
	return (*ptr_to_ptr)->ldifus[tid];
}

static Memb_list* get_memb_list(void** vdata, int tid) {
	LongDiffusionThreadData** ptr_to_ptr = (LongDiffusionThreadData**)vdata;
	return (*ptr_to_ptr)->ml[tid];
}

// Staggered time step integration
static void stagger_time_step(int mod, ldifusfunc3_t difffunc, void** vdata, int argi, int sidx, int didx, NrnThread* _nt) {
	LongDiffusionData* data;
	int i, count, di;
	double dc, vol, dfdi, dx;
	double** data_arr;
	Datum** pdata_arr;
	Datum* thread_arr;
	Memb_list* ml;
	di = didx + argi;
	data = get_diffusion_data(vdata, _nt->id);
	if (!data) return;
	ml = get_memb_list(vdata, _nt->id);
	count = ml->nodecount;
	data_arr = ml->data;
	pdata_arr = ml->pdata;
	thread_arr = ml->_thread;

	update_diffusion_coefficients(data, mod, sidx, ml, _nt);

	// Compute flux and volume coefficients
	for (i = 0; i < count; ++i) {
		int par = data->pindex[i];
		int mi = data->mindex[i];
		data->dc[i] = (*difffunc)(argi, data_arr[mi], pdata_arr[mi], data->vol + i, &dfdi, thread_arr, _nt);
		data->d[i] = 0.0;
#if 0
		if (dfdi) {
			data->d[i] += fabs(dfdi)/data->vol[i]/data->state[i][argi];
		}
#endif
		if (par > -1) {
			dc = (data->dc[i] + data->dc[par]) / 2.0;
			data->a[i] = -data->af[i] * dc / data->vol[par];
			data->b[i] = -data->bf[i] * dc / data->vol[i];
		}
	}

	// Assemble linear system
	for (i = 0; i < count; ++i) {
		int par = data->pindex[i];
		int mi = data->mindex[i];
		data->d[i] += 1.0 / nt_dt;
		data->rhs[i] = data->state[i][argi] / nt_dt;
		if (par > -1) {
			data->d[i] -= data->b[i];
			data->d[par] -= data->a[i];
		}
	}

	// Solve linear system
	solve_tree_system(data->a, data->d, data->b, data->rhs, data->pindex, count);

	// Update solution
	for (i = 0; i < count; ++i) {
		data->state[i][argi] = data->rhs[i];
	}
}

// ODE-based integration (explicit update)
static void ode_integration(int mod, ldifusfunc3_t difffunc, void** vdata, int argi, int sidx, int didx, NrnThread* _nt) {
	LongDiffusionData* data;
	int i, count, di;
	double dc, vol, dfdi;
	double** data_arr;
	Datum** pdata_arr;
	Datum* thread_arr;
	Memb_list* ml;
	di = didx + argi;
	data = get_diffusion_data(vdata, _nt->id);
	if (!data) return;
	ml = get_memb_list(vdata, _nt->id);
	count = ml->nodecount;
	data_arr = ml->data;
	pdata_arr = ml->pdata;
	thread_arr = ml->_thread;

	update_diffusion_coefficients(data, mod, sidx, ml, _nt);

	for (i = 0; i < count; ++i) {
		int par = data->pindex[i];
		int mi = data->mindex[i];
		data->dc[i] = (*difffunc)(argi, data_arr[mi], pdata_arr[mi], data->vol + i, &dfdi, thread_arr, _nt);
		if (par > -1) {
			dc = (data->dc[i] + data->dc[par]) / 2.0;
			data->a[i] = data->af[i] * dc / data->vol[par];
			data->b[i] = data->bf[i] * dc / data->vol[i];
		}
	}

	// Add diffusion terms to derivative
	for (i = 0; i < count; ++i) {
		double diff_term;
		int par = data->pindex[i];
		int mi = data->mindex[i];
		if (par > -1) {
			diff_term = (data->state[par][argi] - data->state[i][argi]);
			data_arr[mi][di] += diff_term * data->b[i];
			data_arr[data->mindex[par]][di] -= diff_term * data->a[i];
		}
	}
}

// Matrix solver for implicit methods (Jacobian solve)
static void matrix_solve_method(int mod, ldifusfunc3_t difffunc, void** vdata, int argi, int sidx, int didx, NrnThread* _nt) {
	LongDiffusionData* data;
	int i, count, di;
	double dc, vol, dfdi;
	double** data_arr;
	Datum** pdata_arr;
	Datum* thread_arr;
	Memb_list* ml;
	di = didx + argi;
	data = get_diffusion_data(vdata, _nt->id);
	if (!data) return;
	ml = get_memb_list(vdata, _nt->id);
	count = ml->nodecount;
	data_arr = ml->data;
	pdata_arr = ml->pdata;
	thread_arr = ml->_thread;

	for (i = 0; i < count; ++i) {
		int par = data->pindex[i];
		int mi = data->mindex[i];
		data->dc[i] = (*difffunc)(argi, data_arr[mi], pdata_arr[mi], data->vol + i, &dfdi, thread_arr, _nt);
		data->d[i] = 0.0;
		if (dfdi) {
			data->d[i] += fabs(dfdi) / data->vol[i] / data->state[i][argi];
#if 0
printf("i=%d state=%g vol=%g dfdc=%g\n", i, data->state[i][argi], data->vol[i], data->d[i]);
#endif
		}
		if (par > -1) {
			dc = (data->dc[i] + data->dc[par]) / 2.0;
			data->a[i] = -data->af[i] * dc / data->vol[par];
			data->b[i] = -data->bf[i] * dc / data->vol[i];
		}
	}

	// Assemble system
	for (i = 0; i < count; ++i) {
		int par = data->pindex[i];
		int mi = data->mindex[i];
		data->d[i] += 1.0 / nt_dt;
		data->rhs[i] = data_arr[mi][di] / nt_dt;
		if (par > -1) {
			data->d[i] -= data->b[i];
			data->d[par] -= data->a[i];
		}
	}

	// Triangularization
	for (i = count - 1; i > 0; --i) {
		int par = data->pindex[i];
		if (par > -1) {
			double factor = data->a[i] / data->d[i];
			data->d[par] -= factor * data->b[i];
			data->rhs[par] -= factor * data->rhs[i];
		}
	}

	// Back substitution
	for (i = 0; i < count; ++i) {
		int par = data->pindex[i];
		if (par > -1) {
			data->rhs[i] -= data->b[i] * data->rhs[par];
		}
		data->rhs[i] /= data->d[i];
	}

	// Update solution
	for (i = 0; i < count; ++i) {
		int mi = data->mindex[i];
		data_arr[mi][di] = data->rhs[i];
	}
}

