CompilerOptions *parseArgs(int argc, char **args) {
  CompilerOptions *options = new CompilerOptions;
  options->sourceFileBaseName = getFileName(args[1]);
  options->sourceFileDirectory = getFileParentPath(args[1]);
  options->inputFilePath = args[1];

  for (int index = 2; index < argc; ++index) {
    if (strcmp(args[index], COMPILER_NAME_FLAG) == 0 && index < argc - 1) {
      options->compilerExecutableName = args[index + 1];
      index += 2;
      continue;
    }
    if (strcmp(args[index], OPTIMIZATION_FLAG) == 0 && index < argc - 1) {
      options->optimizationDegree = args[index + 1];
      index += 2;
      continue;
    }
    if (strcmp(args[index], GENERATED_FILE_NAME_FLAG) == 0 && index < argc - 1) {
      options->outputFileName = args[index + 1];
      index += 2;
      continue;
    }
    if (strcmp(args[index], EXECUTABLE_NAME_FLAG) == 0 && index < argc - 1) {
      options->binaryFileName = args[index + 1];
      index += 2;
      continue;
    }
    if (strcmp(args[index], GENERATE_RUN_EXECUTABLE_FLAG) == 0) {
      options->shouldBuildExecutable = true;
      options->shouldExecuteAfterBuild = true;
      continue;
    }
    if (strcmp(args[index], GENERATE_EXECUTABLE_FLAG) == 0) {
      options->shouldBuildExecutable = true;
      continue;
    }
  }
  return options;
}

void handleCompilerFlags(char *flagArgument) {
  if (strcmp(flagArgument, COMPILER_HELP_FLAG) == 0) {
    std::cout << "Done is compiler to generate C" << std::endl;
    std::cout << "Usage:" << std::endl;
    std::cout << "    donec <source file> <options>" << std::endl;
    exit(EXIT_SUCCESS);
  }
  if (strcmp(flagArgument, COMPILER_VERSION_FLAG) == 0) {
    std::cout << "Done Compiler version is 1.0.0" << std::endl;
    exit(EXIT_SUCCESS);
  }
}

