// Convert a date string in 'YYYY-mm-dd HH:MM:SS' format to Unix timestamp
time_t convertDateStringToTime(std::string inputDate) {
    int year = std::stoi(inputDate.substr(0, 4));
    int month = std::stoi(inputDate.substr(5, 2));
    int day = std::stoi(inputDate.substr(8, 2));
    int hours = std::stoi(inputDate.substr(11, 2));
    int minutes = std::stoi(inputDate.substr(14, 2));
    int seconds = std::stoi(inputDate.substr(17, 2));

    struct tm timeStruct;
    timeStruct.tm_year = year - 1900;
    timeStruct.tm_mon = month - 1;
    timeStruct.tm_mday = day;
    timeStruct.tm_hour = hours;
    timeStruct.tm_min = minutes;
    timeStruct.tm_sec = seconds;
    timeStruct.tm_isdst = -1; // Let mktime determine DST

    time_t resultTimestamp = mktime(&timeStruct);
    return resultTimestamp;
}

