/*! \brief The method is used for collecting the current class attributeList.
    \param prefix         The prefix of the each attributeList parameter.
    \param attributeList  The attributeList storage.
*/
void GridSettings::getAttributeList(const std::string &prefix, T::AttributeList &attributeList) const {
  try {
    char name[300];
    sprintf(name, "%sGridSettings.NumI", prefix.c_str());
    attributeList.addAttribute(name, toString(mNumI));
    sprintf(name, "%sGridSettings.NumJ", prefix.c_str());
    attributeList.addAttribute(name, toString(mNumJ));
    sprintf(name, "%sGridSettings.AngleInitialProdDomain", prefix.c_str());
    attributeList.addAttribute(name, toString(mAngleInitialProdDomain));
    sprintf(name, "%sGridSettings.AngleSubdivisions", prefix.c_str());
    attributeList.addAttribute(name, toString(mAngleSubdivisions));
    sprintf(name, "%sGridSettings.FirstGridLat", prefix.c_str());
    attributeList.addAttribute(name, toString(mFirstGridLat));
    sprintf(name, "%sGridSettings.FirstGridLon", prefix.c_str());
    attributeList.addAttribute(name, toString(mFirstGridLon));
    sprintf(name, "%sGridSettings.", prefix.c_str());
    mResolution.getAttributeList(name, attributeList);
    sprintf(name, "%sGridSettings.LastGridLat", prefix.c_str());
    attributeList.addAttribute(name, toString(mLastGridLat));
    sprintf(name, "%sGridSettings.LastGridLon", prefix.c_str());
    attributeList.addAttribute(name, toString(mLastGridLon));
  } catch (...) {
    throw Fmi::Exception(BCP, "Operation failed", nullptr);
  }
}

/*! \brief The method is used for getting attribute values by their names.
    \param attributeName  The name of the attribute.
    \param attributeValue The value of the attribute (string).
*/
bool GridSettings::getAttributeValue(const char *attributeName, std::string &attributeValue) const {
  try {
    if (attributeName == nullptr)
      return false;
    if (strcasecmp(attributeName, "NumI") == 0) {
      attributeValue = toString(mNumI);
      return true;
    }
    if (strcasecmp(attributeName, "NumJ") == 0) {
      attributeValue = toString(mNumJ);
      return true;
    }
    if (strcasecmp(attributeName, "AngleInitialProdDomain") == 0) {
      attributeValue = toString(mAngleInitialProdDomain);
      return true;
    }
    if (strcasecmp(attributeName, "AngleSubdivisions") == 0) {
      attributeValue = toString(mAngleSubdivisions);
      return true;
    }
    if (strcasecmp(attributeName, "FirstGridLat") == 0) {
      attributeValue = toString(mFirstGridLat);
      return true;
    }
    if (strcasecmp(attributeName, "FirstGridLon") == 0) {
      attributeValue = toString(mFirstGridLon);
      return true;
    }
    if (mResolution.getAttributeValue(attributeName, attributeValue))
      return true;
    if (strcasecmp(attributeName, "LastGridLat") == 0) {
      attributeValue = toString(mLastGridLat);
      return true;
    }
    if (strcasecmp(attributeName, "LastGridLon") == 0) {
      attributeValue = toString(mLastGridLon);
      return true;
    }
    return false;
  } catch (...) {
    throw Fmi::Exception(BCP, "Operation failed", nullptr);
  }
}

/*! \brief The method is used for checking if the attribute value matches to the given value.
    \param attributeName  The name of the attribute.
    \param attributeValue The value of the attribute (string).
*/
bool GridSettings::hasAttributeValue(const char *attributeName, const char *attributeValue) const {
  try {
    if (attributeName == nullptr || attributeValue == nullptr)
      return false;
    if (strcasecmp(attributeName, "NumI") == 0 && strcasecmp(attributeValue, toString(mNumI).c_str()) == 0)
      return true;
    if (strcasecmp(attributeName, "NumJ") == 0 && strcasecmp(attributeValue, toString(mNumJ).c_str()) == 0)
      return true;
    if (strcasecmp(attributeName, "AngleInitialProdDomain") == 0 && strcasecmp(attributeValue, toString(mAngleInitialProdDomain).c_str()) == 0)
      return true;
    if (strcasecmp(attributeName, "AngleSubdivisions") == 0 && strcasecmp(attributeValue, toString(mAngleSubdivisions).c_str()) == 0)
      return true;
    if (strcasecmp(attributeName, "FirstGridLat") == 0 && strcasecmp(attributeValue, toString(mFirstGridLat).c_str()) == 0)
      return true;
    if (strcasecmp(attributeName, "FirstGridLon") == 0 && strcasecmp(attributeValue, toString(mFirstGridLon).c_str()) == 0)
      return true;
    if (mResolution.hasAttributeValue(attributeName, attributeValue))
      return true;
    if (strcasecmp(attributeName, "LastGridLat") == 0 && strcasecmp(attributeValue, toString(mLastGridLat).c_str()) == 0)
      return true;
    if (strcasecmp(attributeName, "LastGridLon") == 0 && strcasecmp(attributeValue, toString(mLastGridLon).c_str()) == 0)
      return true;
    return false;
  } catch (...) {
    throw Fmi::Exception(BCP, "Operation failed", nullptr);
  }
}

/*! \brief The method prints the content of the current object into the given stream.
    \param ostream      The output stream.
    \param level        The print level (used when printing multi-level structures).
    \param optionFlags  The printing options expressed in flag-bits.
*/
void GridSettings::print(std::ostream &stream, uint level, uint optionFlags) const {
  try {
    stream << space(level) << "GridSettings\n";
    stream << space(level) << "- NumI = " << toString(mNumI) << "\n";
    stream << space(level) << "- NumJ = " << toString(mNumJ) << "\n";
    stream << space(level) << "- AngleInitialProdDomain = " << toString(mAngleInitialProdDomain) << "\n";
    stream << space(level) << "- AngleSubdivisions = " << toString(mAngleSubdivisions) << "\n";
    stream << space(level) << "- FirstGridLat = " << toString(mFirstGridLat) << "\n";
    stream << space(level) << "- FirstGridLon = " << toString(mFirstGridLon) << "\n";
    mResolution.print(stream, level + 1, optionFlags);
    stream << space(level) << "- LastGridLat = " << toString(mLastGridLat) << "\n";
    stream << space(level) << "- LastGridLon = " << toString(mLastGridLon) << "\n";
  } catch (...) {
    throw Fmi::Exception(BCP, "Operation failed", nullptr);
  }
}

