void AudioNode::init()
{
    CK_ASSERT(!s_bufferPool);
#if CK_PLATFORM_ANDROID
    // align output sample rate with device's native rate to prevent audio artifacts
    // https://groups.google.com/d/topic/android-ndk/0Gtzpg49ZeE/discussion
    s_sampleRate = Audio::getNativeSampleRate();
#elif CK_PLATFORM_IOS || CK_PLATFORM_TVOS || CK_PLATFORM_OSX
    // synchronize with the active audio session's sample rate
    s_sampleRate = Audio::getSessionSampleRate();
#endif
    float updateIntervalMs = System::get()->getConfig().audioUpdateMs;
    int frameCount = (int) (s_sampleRate * updateIntervalMs * 0.001f);
    frameCount *= 2; // reserve capacity for up to 2x playback speed at 48kHz
    s_bufferPool = new BufferPool(k_maxChannels * frameCount);
}
void AudioNode::shutdown()
{
    CK_ASSERT(s_bufferPool);
    delete s_bufferPool;
    s_bufferPool = nullptr;
}
AudioNode::AudioNode() 
{
}
AudioNode::~AudioNode()
{
}
template <>
BufferHandle AudioNode::process<int32>(int frameCount, bool postProcess, bool& needsPostProcessing)
{
    return processFixed(frameCount, postProcess, needsPostProcessing);
}
template <>
BufferHandle AudioNode::process<float>(int frameCount, bool postProcess, bool& needsPostProcessing)
{
    return processFloat(frameCount, postProcess, needsPostProcessing);
}
