void AudioNode::printImpl(int depth, const char* label)
{
    for (int i = 0; i < depth; ++i)
    {
        CK_PRINT("  ");
    }
    CK_PRINT("%p %s\n", this, label);
}
#endif
BufferPool* AudioNode::s_bufferPool = NULL;
int AudioNode::s_sampleRate = k_maxSampleRate;
////////////////////////////////////////
void AudioNode::setVolumeRampTime(float durationMs)
{
    s_volumeRampDuration = durationMs;
}
float AudioNode::getVolumeRampTime()
{
    return s_volumeRampDuration;
}
float AudioNode::getVolumeRate()
{
    if (s_volumeRampDuration <= 0.0f || s_volumeRampDuration <= 1.0f / s_sampleRate)
    {
        return 10.0f; // immediate transition
    }
    else
    {
        return 1.0f / (s_volumeRampDuration * 0.001f * s_sampleRate);
    }
}
float AudioNode::s_volumeRampDuration = Ck_volumeRampTimeMsDefault;
