        };

        static constexpr char const* const token_symbols[] =
        {
            // precedence 1
            ",",
            // precedence 2
            "=",
            "+=",
            "-=",
            "*=",
            "/=",
            "%=",
            "&=",
            "^=",
            "|=",
            "<<=",
            ">>=",
            // precedence 3
            "||",
            // precedence 4
            "&&",
            // precedence 5
            "|",
            // precedence 6
            "^",
            // precedence 7
            "&",
            // precedence 8
            "==",
            "!=",
            // precedence 9
            "<",
            "<=",
            ">",
            ">=",
            // precedence 10
            "<<",
            ">>",
            // precedence 11
            "+",
            "-",
            // precedence 12
            "*",
            "/",
            "%",
            // precedence 13
            "+",
            "-",
            "++",
            "--",
            "~",
            "!",
            // precedence 14
            "++",
            "--",
            "\?\?\?",
        };
    }

    std::ostream& operator<<(std::ostream& out, nil)
    {
        if (util::is_repr(out))
        {
            out << "<nil>";
        }
        return out;
    }

    std::ostream& operator<<(std::ostream& out, optoken op)
    {
        out << detail::token_symbols[static_cast<int>(op)];
        return out;
    }

    std::ostream& operator<<(std::ostream& out, identifier const& id)
    {
        out << id.symbol_name;
        if (id.unique_id >= 0 && id.column_number != -1)
        {
            out << '$' << id.unique_id << '$' << id.column_number;
        }
        return out;
    }

    namespace detail
    {
        void to_string_visitor::operator()(bool value) const
        {
            out_ << std::boolalpha << value;
        }

        void to_string_visitor::operator()(std::string const& text) const
        {
            if (util::is_repr(out_))
            {
                out_ << "\"";
                for (char c : text)
                {
                    switch (c)
                    {
                    case '\b':  out_ << "\\\b"; break;
                    case '\n':  out_ << "\\n"; break;
                    case '\r':  out_ << "\\r"; break;
                    case '\t':  out_ << "\\t"; break;
                    case '\\':  out_ << "\\\\"; break;
                    case '\"':  out_ << "\\\""; break;
                    default:    out_ << c;
                    }
                }
                out_ << "\"";
            }
            else
            {
                for (char c : text)
                {
                    out_ << c;
                }
            }
        }
    }

    std::ostream& operator<<(std::ostream& out, primary_expr const& pe)
    {
        util::visit(to_string_visitor{out}, pe.get());
        return out;
    }

    std::ostream& operator<<(std::ostream& out, operand const& op)
    {
        util::visit(to_string_visitor{out}, op.get());
        return out;
    }

    std::ostream& operator<<(std::ostream& out, unary_expr const& ue)
    {
        out << ue.operator_token << ue.operand_value;
        return out;
    }

    std::ostream& operator<<(std::ostream& out, operation const& op)
    {
        out << " " << op.operator_token << " " << op.operand_value;
        return out;
    }

    std::ostream& operator<<(std::ostream& out, expression const& expr)
    {
        if (!expr.remaining_operations.empty())
        {
            out << "(";
        }
        out << expr.head_expression;
        if (!expr.remaining_operations.empty())
        {
            for (auto const& operation : expr.remaining_operations)
                out << operation;
            out << ")";
        }
        return out;
    }

    std::ostream& operator<<(std::ostream& out, function_call const& f)
    {
        out << f.function_identifier << "(";
        bool first_argument = true;
        for (auto const& arg : f.argument_list)
        {
            if (!first_argument)
            {
                out << ", ";
            }
            first_argument = false;
            out << arg;
        }
        out << ")";
        return out;
    }

    std::ostream& operator<<(
        std::ostream& out, std::vector<ast::expression> const& list)
    {
        out << "list(";
        bool first_item = true;
        for (auto const& item : list)
        {
            if (!first_item)
            {
                out << ", ";
            }
            first_item = false;
            out << item;
        }
        out << ")";
        return out;
    }

    std::string to_string(expression const& expr)
    {
        std::ostringstream stream;
        stream << expr;
        return stream.str();
    }
}}

