//
// CheckPageTableEntryValidity
//
// Verify whether the page table entry for the given virtual address is present.
//
_Use_decl_annotations_
BOOL
CheckPageTableEntryValidity(
    PVOID targetAddress,
    PBOOL pIsPresent
)
{
    PSAPI_WORKING_SET_EX_INFORMATION wsInfo = {};
    BOOL operationStatus = TRUE;

    // Clear output parameter.
    *pIsPresent = FALSE;

    //
    // Prepare the virtual address for working set extended information query.
    //
    wsInfo.VirtualAddress = targetAddress;
    operationStatus = QueryWorkingSetEx(
        GetCurrentProcess(),
        &wsInfo,
        sizeof(wsInfo));
    if (!operationStatus)
    {
        fprintf(stderr, "QueryWorkingSetEx error: %lu\n", GetLastError());
        goto cleanup;
    }

    // Update output based on validity of virtual attributes.
    if (wsInfo.VirtualAttributes.Valid)
    {
        *pIsPresent = TRUE;
    }

cleanup:
    return operationStatus;
}

