#include <vector>
#include <queue>

class Solution {
public:
    std::vector<int> findMinHeightTrees(int nodeCount, std::vector<std::vector<int>>& connectionList) {
        // Build adjacency list and degree count
        std::vector<std::vector<int>> adjList(nodeCount);
        std::vector<int> degree(nodeCount, 0);

        for (auto& edge : connectionList) {
            adjList[edge[0]].push_back(edge[1]);
            adjList[edge[1]].push_back(edge[0]);
            degree[edge[0]]++;
            degree[edge[1]]++;
        }

        int remainingNodes = nodeCount;

        // Trim leaves until we have 1 or 2 nodes left
        while (remainingNodes > 2) {
            std::queue<int> leafQueue;

            // Find all current leaves
            for (int node = 0; node < nodeCount; node++) {
                if (degree[node] == 1) {
                    leafQueue.push(node);
                    degree[node] = -1;  // Mark as processed
                    remainingNodes--;
                }
            }

            // Remove leaves and update degrees of their neighbors
            while (!leafQueue.empty()) {
                int currentLeaf = leafQueue.front();
                leafQueue.pop();

                for (int neighbor : adjList[currentLeaf]) {
                    if (degree[neighbor] > 0) {
                        degree[neighbor]--;
                    }
                }
            }
        }

        // Collect remaining nodes (potential roots)
        std::vector<int> minHeightRoots;
        for (int i = 0; i < nodeCount; i++) {
            if (degree[i] >= 0 && degree[i] <= 1) {
                minHeightRoots.push_back(i);
            }
        }

        return minHeightRoots;
    }
};

#include <string>
#include <cmath>

class Solution {
public:
    // Find the smallest good base for the given number n
    std::string smallestGoodBase(std::string numberStr) {
        // Convert input string to unsigned long long
        unsigned long long targetNum = (unsigned long long)stoll(numberStr);

        // Start with base 2 representation (all 1s)
        unsigned long long candidate = 1;

        // Check from highest possible length down to 2 digits
        for (int bitCount = 62; bitCount >= 1; bitCount--) {
            // If 2^bitCount is less than our target, check this length
            if ((candidate << bitCount) < targetNum) {
                unsigned long long result = findBase(targetNum, bitCount);
                if (result != 0) {
                    return std::to_string(result);
                }
            }
        }

        // If no smaller base found, return n-1 (always works as "11")
        return std::to_string(targetNum - 1);
    }

    // Binary search to find base for d+1 digit representation (all 1s)
    unsigned long long findBase(unsigned long long value, int digits) {
        double approxValue = (double)value;
        // Upper bound for base: approximately n^(1/d)
        unsigned long long highBound = (unsigned long long)(std::pow(approxValue, 1.0/digits) + 1);
        unsigned long long lowBound = 1;

        // Binary search for the correct base
        while (lowBound <= highBound) {
            unsigned long long base = lowBound + (highBound - lowBound) / 2;
            unsigned long long totalSum = 1;
            unsigned long long currentPower = 1;

            // Calculate sum: 1 + base + base^2 + ... + base^digits
            for (int position = 1; position <= digits; position++) {
                currentPower *= base;
                totalSum += currentPower;
            }

            if (totalSum == value) {
                return base;
            } else if (totalSum > value) {
                highBound = base - 1;
            } else {
                lowBound = base + 1;
            }
        }
        return 0;
    }
};

