using namespace snmalloc;

using CustomGlobals = FixedGlobals<PALNoAlloc<DefaultPal>>;
using FixedAlloc = LocalAllocator<CustomGlobals>;

int main()
{
#ifndef SNMALLOC_PASS_THROUGH // Depends on snmalloc specific features
  setup();

  // 28 is large enough to produce a nested allocator.
  // It is also large enough for the example to run in.
  // For 1MiB superslabs, SUPERSLAB_BITS + 4 is not big enough for the example.
  auto region_size = bits::one_at_bit(28);
  auto base_address = Pal::reserve(region_size);
  Pal::notify_using<NoZero>(base_address, region_size);
  auto end_address = pointer_offset(base_address, region_size);
  std::cout << "Allocated region " << base_address << " - "
            << pointer_offset(base_address, region_size) << std::endl;

  CustomGlobals::init(nullptr, base_address, region_size);
  FixedAlloc allocator;

  size_t allocation_size = 128;
  size_t total_bytes = 0;
  size_t iteration_count = 0;
  while (true)
  {
    auto result = allocator.alloc(allocation_size);
    total_bytes += allocation_size;
    iteration_count++;

    if (iteration_count == 1024)
    {
      iteration_count = 0;
      std::cout << ".";
    }
    // Run until we exhaust the fixed region.
    // This should return null.
    if (result == nullptr)
      break;

    if (base_address > result)
    {
      std::cout << "Allocated: " << result << std::endl;
      abort();
    }
    if (end_address < result)
    {
      std::cout << "Allocated: " << result << std::endl;
      abort();
    }
  }

  std::cout << "Total allocated: " << total_bytes << " out of " << region_size << std::endl;
  std::cout << "Overhead: 1/" << (double)region_size / (double)(region_size - total_bytes)
            << std::endl;

  allocator.teardown();
#endif
}

#include <stdio.h>
#include "StackBlurFilter.h"

void applyHorizontalBlur(uint32_t *imageData, int width, int height, int blurRadius, int originX, int originY, int stepX, int stepY);
void applyVerticalBlur(uint32_t *imageData, int width, int height, int blurRadius, int originX, int originY, int stepX, int stepY);

void processBlur(uint32_t *buffer, int radius, int threads, int threadId, int mode, int w, int h) {
    using namespace hokoblur;

    if (buffer == NULL) {
        return;
    }

    if (mode == HORIZONTAL) {
        int blockHeight = h / threads;
        int startY = threadId * blockHeight;
        if (threadId == threads - 1) {
            blockHeight = h - (threads - 1) * blockHeight;
        }
        applyHorizontalBlur(buffer, w, h, radius, 0, startY, w, blockHeight);
    } else if (mode == VERTICAL) {
        int blockWidth = w / threads;
        int startX = threadId * blockWidth;
        if (threadId == threads - 1) {
            blockWidth = w - (threads - 1) * (w / threads);
        }
        applyVerticalBlur(buffer, w, h, radius, startX, 0, blockWidth, h);
    }
}

void applyHorizontalBlur(uint32_t *imgData, int width, int height, int radius, int originX, int originY, int stepX, int stepY) {
    int widthMax = width - 1;
    int divisor = radius + radius + 1;
    int redSum, greenSum, blueSum, x, y, i, pixelValue, yPos;
    int *minValues;
    minValues = (int *) malloc(sizeof(int) * max(width, height));

    int divSquare = (divisor + 1) >> 1;
    divSquare *= divSquare;

    short *distanceWeights;
    distanceWeights = (short *) malloc(sizeof(short) * 256 * divSquare);

    for (i = 0; i < 256 * divSquare; i++) {
        distanceWeights[i] = (short) (i / divSquare);
    }

    int (*blurStack)[3];
    blurStack = (int (*)[3]) malloc(sizeof(int) * divisor * 3);

    int stackIndex;
    int stackBegin;
    int *currentPixel;
    int pixelWeight;
    int windowSize = radius + 1;
    int outRedSum, outGreenSum, outBlueSum;
    int inRedSum, inGreenSum, inBlueSum;
    int startIndex;

    int finishX = originX + stepX;
    int finishY = originY + stepY;

    for (y = originY; y < finishY; y++) {
        inRedSum = inGreenSum = inBlueSum = outRedSum = outGreenSum = outBlueSum = 
        redSum = greenSum = blueSum = 0;

        startIndex = y * width;

        for (i = -radius; i <= radius; i++) {
            pixelValue = imgData[startIndex + min(widthMax, max(originX, i + originX))];
            currentPixel = blurStack[i + radius];
            currentPixel[0] = (pixelValue & 0xff0000) >> 16;
            currentPixel[1] = (pixelValue & 0x00ff00) >> 8;
            currentPixel[2] = (pixelValue & 0x0000ff);

            pixelWeight = windowSize - abs(i);
            redSum += currentPixel[0] * pixelWeight;
            greenSum += currentPixel[1] * pixelWeight;
            blueSum += currentPixel[2] * pixelWeight;

            if (i > 0) {
                inRedSum += currentPixel[0];
                inGreenSum += currentPixel[1];
                inBlueSum += currentPixel[2];
            } else {
                outRedSum += currentPixel[0];
                outGreenSum += currentPixel[1];
                outBlueSum += currentPixel[2];
            }
        }

        stackIndex = radius;
        yPos = startIndex + originX;

        for (x = originX; x < finishX; x++) {
            imgData[yPos] = (0xff000000 & imgData[yPos]) | 
                           (distanceWeights[redSum] << 16) | 
                           (distanceWeights[greenSum] << 8) | 
                           distanceWeights[blueSum];

            redSum -= outRedSum;
            greenSum -= outGreenSum;
            blueSum -= outBlueSum;

            stackBegin = stackIndex - radius + divisor;
            currentPixel = blurStack[stackBegin % divisor];

            outRedSum -= currentPixel[0];
            outGreenSum -= currentPixel[1];
            outBlueSum -= currentPixel[2];

            minValues[x] = min(x + radius + 1, widthMax);

            pixelValue = imgData[startIndex + minValues[x]];
            currentPixel[0] = (pixelValue & 0xff0000) >> 16;
            currentPixel[1] = (pixelValue & 0x00ff00) >> 8;
            currentPixel[2] = (pixelValue & 0x0000ff);

            inRedSum += currentPixel[0];
            inGreenSum += currentPixel[1];
            inBlueSum += currentPixel[2];

            redSum += inRedSum;
            greenSum += inGreenSum;
            blueSum += inBlueSum;

            stackIndex = (stackIndex + 1) % divisor;
            currentPixel = blurStack[stackIndex % divisor];

            outRedSum += currentPixel[0];
            outGreenSum += currentPixel[1];
            outBlueSum += currentPixel[2];

            inRedSum -= currentPixel[0];
            inGreenSum -= currentPixel[1];
            inBlueSum -= currentPixel[2];

            yPos++;
        }
    }

    free(distanceWeights);
    free(blurStack);
}

void applyVerticalBlur(uint32_t *imgData, int width, int height, int radius, int originX, int originY, int stepX, int stepY) {
    int heightMax = height - 1;
    int heightWidth = heightMax * width;
    int divisor = radius + radius + 1;
    int redSum, greenSum, blueSum, x, y, i, pixelValue, yPos;
    int *minValues;
    minValues = (int *) malloc(sizeof(int) * max(width, height));

    int divSquare = (divisor + 1) >> 1;
    divSquare *= divSquare;

    short *distanceWeights;
    distanceWeights = (short *) malloc(sizeof(short) * 256 * divSquare);

    for (i = 0; i < 256 * divSquare; i++) {
        distanceWeights[i] = (short) (i / divSquare);
    }

    int (*blurStack)[3];
    blurStack = (int (*)[3]) malloc(sizeof(int) * divisor * 3);

    int stackIndex;
    int stackBegin;
    int *currentPixel;
    int pixelWeight;
    int windowSize = radius + 1;
    int outRedSum, outGreenSum, outBlueSum;
    int inRedSum, inGreenSum, inBlueSum;

    int finishX = originX + stepX;
    int finishY = originY + stepY;

    int baseOffset = originY * width;

    for (x = originX; x < finishX; x++) {
        inRedSum = inGreenSum = inBlueSum = outRedSum = outGreenSum = outBlueSum = 
        redSum = greenSum = blueSum = 0;

        for (i = -radius; i <= radius; i++) {
            pixelValue = imgData[min(heightWidth, max(baseOffset + i * width, baseOffset)) + x];
            currentPixel = blurStack[i + radius];
            currentPixel[0] = (pixelValue & 0xff0000) >> 16;
            currentPixel[1] = (pixelValue & 0x00ff00) >> 8;
            currentPixel[2] = (pixelValue & 0x0000ff);

            pixelWeight = windowSize - abs(i);
            redSum += currentPixel[0] * pixelWeight;
            greenSum += currentPixel[1] * pixelWeight;
            blueSum += currentPixel[2] * pixelWeight;

            if (i > 0) {
                inRedSum += currentPixel[0];
                inGreenSum += currentPixel[1];
                inBlueSum += currentPixel[2];
            } else {
                outRedSum += currentPixel[0];
                outGreenSum += currentPixel[1];
                outBlueSum += currentPixel[2];
            }
        }

        stackIndex = radius;
        yPos = baseOffset + x;

        for (y = originY; y < finishY; y++) {
            imgData[yPos] = (0xff000000 & imgData[yPos]) | 
                           (distanceWeights[redSum] << 16) | 
                           (distanceWeights[greenSum] << 8) | 
                           distanceWeights[blueSum];

            redSum -= outRedSum;
            greenSum -= outGreenSum;
            blueSum -= outBlueSum;

            stackBegin = stackIndex - radius + divisor;
            currentPixel = blurStack[stackBegin % divisor];

            outRedSum -= currentPixel[0];
            outGreenSum -= currentPixel[1];
            outBlueSum -= currentPixel[2];

            minValues[y] = min(y + radius + 1, heightMax);

            pixelValue = imgData[minValues[y] * width + x];
            currentPixel[0] = (pixelValue & 0xff0000) >> 16;
            currentPixel[1] = (pixelValue & 0x00ff00) >> 8;
            currentPixel[2] = (pixelValue & 0x0000ff);

            inRedSum += currentPixel[0];
            inGreenSum += currentPixel[1];
            inBlueSum += currentPixel[2];

            redSum += inRedSum;
            greenSum += inGreenSum;
            blueSum += inBlueSum;

            stackIndex = (stackIndex + 1) % divisor;
            currentPixel = blurStack[stackIndex % divisor];

            outRedSum += currentPixel[0];
            outGreenSum += currentPixel[1];
            outBlueSum += currentPixel[2];

            inRedSum -= currentPixel[0];
            inGreenSum -= currentPixel[1];
            inBlueSum -= currentPixel[2];

            yPos += width;
        }
    }

    free(distanceWeights);
    free(blurStack);
}

#include <vector>
#include <set>
#include <algorithm>
#include <climits>

class Solution {
public:
    int coinChange(std::vector<int>& denominations, int targetAmount) {

        int size = denominations.size();
        std::vector<int> minCoins(targetAmount + 1, INT_MAX);
        minCoins[targetAmount] = 0;
        std::set<int> remaining;
        remaining.insert(targetAmount);
        std::sort(denominations.begin(), denominations.end());

        for(int i = size - 1; i >= 0; --i) {
            for(std::set<int>::reverse_iterator iter = remaining.rbegin(); iter != remaining.rend(); ++iter) {
                int current = *iter;
                int nextVal = current - denominations[i];
                if(nextVal >= 0) {
                    minCoins[nextVal] = std::min(minCoins[nextVal], minCoins[current] + 1);
                    remaining.insert(nextVal);
                }
            }
        }
        return (minCoins[0] == INT_MAX) ? -1 : minCoins[0];
    }
};

