// Post notification messages to main window
void ClientHandler::SendNotification(NotificationType type)
{
  UINT msgId;
  switch(type)
  {
  case NOTIFY_CONSOLE_MESSAGE:
    msgId = ID_WARN_CONSOLEMESSAGE;
    break;
  case NOTIFY_DOWNLOAD_COMPLETE:
    msgId = ID_WARN_DOWNLOADCOMPLETE;
    break;
  case NOTIFY_DOWNLOAD_ERROR:
    msgId = ID_WARN_DOWNLOADERROR;
    break;
