#include <string>
#include <algorithm>

class Solution {
public:
    std::string sumBinary(std::string first, std::string second) {
        int overflow = 0;
        std::string result = "";
        int idx1 = first.length() - 1;
        int idx2 = second.length() - 1;

        while(idx1 >= 0 || idx2 >= 0 || overflow > 0){
            int digit1 = idx1 < 0 ? 0 : first[idx1] - '0';
            int digit2 = idx2 < 0 ? 0 : second[idx2] - '0';

            int total = digit1 + digit2 + overflow;
            result = char((total % 2) + '0') + result;
            overflow = total / 2;

            idx1--;
            idx2--;
        }
        return result;
    }
};

