namespace Mod::Util::Heap_KSM
{
	void ModifyKSM(bool enable)
	{
		static uint32_t PAGE_SIZE = getpagesize();

		std::unique_ptr<FILE, decltype(&fclose)> fileHandle(fopen("/proc/self/maps", "r"), &fclose);
		if (!fileHandle) {
			Msg("Failed to open '/proc/self/maps': %s\n", strerror(errno));
			return;
		}

		char lineBuffer[4096];
		while (fgets(lineBuffer, sizeof(lineBuffer), fileHandle.get()) != nullptr) {
			uint32_t beginAddr = 0x00000000;
			uint32_t endAddr   = 0x00000000;
			char permRead      = ' ';
			char permWrite     = ' ';
			char permExec      = ' ';
			char permShare     = ' ';
			uint64_t inodeNum  = 0;
			char path[4096]    = {0};

			int parsedFields = sscanf(lineBuffer, "%8" SCNx32 "-%8" SCNx32 " %c%c%c%c %*8x %*2x:%*2x %" SCNu64 " %4095s",
			                          &beginAddr, &endAddr, &permRead, &permWrite, &permExec, &permShare, &inodeNum, path);

			if (parsedFields == 8) {
				if (path[0] == '\0' || std::strcmp(path, "[heap]") != 0) {
					continue;
				}
			} else if (parsedFields != 7) {
				continue;
			}

			if (inodeNum != 0) {
				continue;
			}

			if ((beginAddr & (PAGE_SIZE - 1)) != 0 || (endAddr & (PAGE_SIZE - 1)) != 0) {
				continue;
			}

			if (beginAddr >= endAddr) {
				continue;
			}

			if (permShare != 'p') {
				continue;
			}

			void* regionStart = reinterpret_cast<void*>(beginAddr);
			size_t regionSize = static_cast<size_t>(endAddr - beginAddr);

			Msg("madvise(0x%08x, 0x%08x, MADV_%sMERGEABLE)\n", 
			    static_cast<uint32_t>(regionStart), 
			    static_cast<uint32_t>(regionSize), 
			    enable ? "" : "UN");

			if (madvise(regionStart, regionSize, enable ? MADV_MERGEABLE : MADV_UNMERGEABLE) < 0) {
				Msg("madvise failed: %s\n", strerror(errno));
			}
		}
	}

	CON_COMMAND(sig_util_heap_ksm_enable, "Utility: enable Kernel Samepage Merging for all private anonymous mappings")
	{
		ModifyKSM(true);
	}

	CON_COMMAND(sig_util_heap_ksm_disable, "Utility: disable Kernel Samepage Merging for all private anonymous mappings")
	{
		ModifyKSM(false);
	}
}

