// __________________________________________________________________________________________
// Name			: AEInitialize
// Input		: None
// Output		: OSErr: error status if initialization fails
// Description	: Registers handlers for standard AppleEvents (launch, open docs, print, quit)
//				  plus custom events for icon insertion and alias resolution
OSErr AEInitialize()
{
	OSErr result = noErr;
	AEEventHandlerUPP launchHandler;
	AEEventHandlerUPP openDocsHandler;
	AEEventHandlerUPP printDocsHandler;
	AEEventHandlerUPP terminateHandler;
	AEEventHandlerUPP insertIconHandler;
	OSLAccessorUPP	aliasAccessorHandler;

	launchHandler = NewAEEventHandlerProc(AELaunchApp);
	openDocsHandler = NewAEEventHandlerProc(AEOpenDocuments);
	printDocsHandler = NewAEEventHandlerProc(AEPrintDocuments);
	terminateHandler = NewAEEventHandlerProc(AETerminateApp);
	insertIconHandler = NewAEEventHandlerProc(AEInsertIconResource);
	aliasAccessorHandler = NewOSLAccessorProc(AliasObjectAccessor);

	result = AEInstallEventHandler(kCoreEventClass, kAEOpenApplication, launchHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler(kCoreEventClass, kAEOpenDocuments, openDocsHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler(kCoreEventClass, kAEPrintDocuments, printDocsHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler(kCoreEventClass, kAEQuitApplication, terminateHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEOpenApplication, launchHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEOpenDocuments, openDocsHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEPrintDocuments, printDocsHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEQuitApplication, terminateHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('c2ci', 'insr', insertIconHandler, 0L, false);
	if (result == noErr)
		result = AEObjectInit();
	if (result == noErr)
		result = AEInstallObjectAccessor('alis', typeNull, aliasAccessorHandler, 0, false);

	return result;
}
// __________________________________________________________________________________________
// Name			: VerifyRequiredParameters
// Input		: AppleEvent reference
// Output		: OSErr: noErr if all required parameters present, errAEParamMissed otherwise
// Description	: Checks whether any mandatory keywords were omitted in the AppleEvent
OSErr VerifyRequiredParameters(const AppleEvent *eventRef)
{
	DescType foundType;
	Size bufferSize;
	if ( AEGetAttributePtr(eventRef, keyMissedKeywordAttr, typeWildCard, &foundType, nullptr, 0, &bufferSize) == errAEDescNotFound )
		return noErr;
	else
		return errAEParamMissed;
}			  
pascal OSErr AELaunchApp(const AppleEvent *event, AppleEvent *response, long userData)
{
	event;
	response; 
	userData;
	return VerifyRequiredParameters(event);
}
pascal OSErr AEOpenDocuments(const AppleEvent *event, AppleEvent *response, long userData)
{
	OSErr		status;
	AEDescList	fileDescriptorList;
	long		index;
	long		itemCount;
	Size		actualSize;
	FSSpec		specifier;
	AEKeyword	keyword;
	DescType	type;
	event;
	userData;
	status = AEGetParamDesc(event, keyDirectObject, typeAEList, &fileDescriptorList);

	status = AECountItems(&fileDescriptorList, &itemCount);
	for (index = 1; index <= itemCount; index++)
	{
		status = AEGetNthPtr(&fileDescriptorList, index, typeFSS, &keyword, &type, (Ptr)&specifier, sizeof(FSSpec), &actualSize);
		if (status == noErr)
		{
			fileSpec = specifier;
			EditIcon(false);
			return VerifyRequiredParameters(event);
		}
	}
	return VerifyRequiredParameters(event);
}
pascal OSErr AEPrintDocuments(const AppleEvent *event, AppleEvent *response, long userData)
{
	event;
	response;
	userData;
	return errAEEventNotHandled;
}
pascal OSErr AETerminateApp(const AppleEvent *event, AppleEvent *response, long userData)
{
	response;
	userData;
	isDone = true;
	return VerifyRequiredParameters(event);
}
pascal OSErr AEInsertIconResource(const AppleEvent *event, AppleEvent *response, long userData)
{
	response;
	userData;
	long resourceID;
	Size	actualSize;
	DescType actualType;
	AEDescList	fileDescriptorList;
	Str255	resourceName;
	OSStatus status;
	long count;
	AEKeyword	keyword;
	FSSpec		specifier;
	DescType	type;
	int dummy;
	bool hasResourceID;


	//if (!CheckClipboard(false))
	//	return noScrapErr;


	status = AEGetParamDesc(event, 'iFil', typeAEList, &fileDescriptorList);

	status = AECountItems(&fileDescriptorList, &count);
	for (int i = 1; i <= count; i++)
	{
		status = AEGetNthPtr(&fileDescriptorList, i, typeFSS, &keyword, &type, (Ptr)&specifier, sizeof(FSSpec), &actualSize);
		if (status == noErr)
		{
			fileSpec = specifier;
		}
		else
		{
			AEDesc object, token;
			unsigned char ignored;
			status = AEGetParamDesc(event, 'iFil', typeObjectSpecifier, &object);

			status = AEResolve(&object, kAEIDoMinimum, &token);

			status = ResolveAlias(NULL, (AliasHandle)(token.dataHandle), &specifier, &ignored);

			AEDisposeDesc(&token);

			fileSpec = specifier;
		}
	}

	status = AEGetParamPtr(event, 'iID ', typeSInt32, &actualType, &resourceID, sizeof(long), &actualSize);
	if (status != noErr)
		hasResourceID = false;
	else
		hasResourceID = true;

	status = AEGetParamPtr(event, 'iNam', typeChar, &actualType, (Ptr)(&(resourceName[1])), 255, &actualSize);
	if (status == noErr)
		resourceName[0] = actualSize;
	else if ((**preferences).nameResources && hasResourceID)
		GetIconMenu(resourceID, &dummy, &dummy, resourceName);

	if (hasResourceID)
		clip2icns(resourceID, resourceName);
	else
	{
		AEInteractAllowed previousMode;
		AEGetInteractionAllowed(&previousMode);
		AESetInteractionAllowed(kAEInteractWithLocal);
		AEInteractWithUser(kAEDefaultTimeout, nullptr, nullptr);
		EditIcon(false);
		AESetInteractionAllowed(previousMode);
	}

	return VerifyRequiredParameters(event);
}
pascal OSErr AliasObjectAccessor(DescType	desiredClass,
								AEDesc*		containerToken,
								DescType	containerClass,
								DescType	keyForm,
								AEDesc*		keyData,
								AEDesc*		resultToken,
								long		refCon)
{
#pragma unused (desiredClass, containerToken, containerClass, keyForm, refCon)
	OSErr status;
	AEKeyword	keyword;

	status = AEGetNthDesc(keyData, 1, 'alis', &keyword, resultToken);

	return status;
}

#include "../../include/utility/math.hpp"

// Linear interpolation for 2D, 3D, and 4D vectors
xd::vec2 lerp(const xd::vec2& begin, const xd::vec2& finish, float t) noexcept {
    xd::vec2 output;
    output.x = lerp(begin.x, finish.x, t);
    output.y = lerp(begin.y, finish.y, t);
    return output;
}

xd::vec3 lerp(const xd::vec3& begin, const xd::vec3& finish, float t) noexcept {
    xd::vec3 output;
    output.x = lerp(begin.x, finish.x, t);
    output.y = lerp(begin.y, finish.y, t);
    output.z = lerp(begin.z, finish.z, t);
    return output;
}

xd::vec4 lerp(const xd::vec4& begin, const xd::vec4& finish, float t) noexcept {
    xd::vec4 output;
    output.x = lerp(begin.x, finish.x, t);
    output.y = lerp(begin.y, finish.y, t);
    output.z = lerp(begin.z, finish.z, t);
    output.w = lerp(begin.w, finish.w, t);
    return output;
}

#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    int size;
    cin >> size;
    vector<int> frequency(100001, 0);
    int maxValue = 0;

    for (int index = 0; index < size; index++) {
        int value;
        cin >> value;
        frequency[value]++;
        maxValue = max(maxValue, value);
    }

    vector<long long> dp(maxValue + 1, 0);
    dp[0] = 0;
    dp[1] = 1LL * frequency[1];

    for (int i = 2; i <= maxValue; i++) {
        dp[i] = max(dp[i-1], dp[i-2] + static_cast<long long>(i) * static_cast<long long>(frequency[i]));
    }

    cout << dp[maxValue] << endl;
    return 0;
}

