#define SERVICECTRL_INSTALL		"Install"
#define SERVICECTRL_UNINSTALL	"Uninstall"
#define SERVICECTRL_START		"Start"
#define SERVICECTRL_STOP		"Stop"
#define SERVICECTRL_STATUS		"Status"
