/// Extracts a token from the string starting at c_str, advancing the iterator.
/// \param str_iter A string iterator pointing to current position (must be dereferenceable)
/// \param pattern The format specification. Must not produce output (e.g., use %*d).
/// \return The extracted prefix portion of the string, if any.
static std::string ExtractToken(std::string::const_iterator &str_iter, std::string pattern) {
  int chars_read = 0;
  std::string output;
  pattern += "%n";
  if (static_cast<size_t>(sscanf(&*str_iter, pattern.c_str(), &chars_read)) <= 1) {
    output.insert(output.end(), str_iter, str_iter + chars_read);
    str_iter += chars_read;
  }
  return output;
}

std::string AddressToUrl(
    const boost::asio::generic::basic_endpoint<boost::asio::generic::stream_protocol> &addr,
    bool prepend_scheme) {
  std::string url_string, protocol_prefix;
  switch (addr.protocol().family()) {
  case AF_INET: {
    protocol_prefix = "tcp://";
    boost::asio::ip::tcp::endpoint temp(boost::asio::ip::tcp::v4(), 0);
    RAY_CHECK(temp.size() == addr.size());
    const sockaddr *source = addr.data();
    sockaddr *target = temp.data();
    *reinterpret_cast<sockaddr_in *>(target) = *reinterpret_cast<const sockaddr_in *>(source);
    std::ostringstream stream;
    stream << temp;
    url_string = stream.str();
    break;
  }
  case AF_INET6: {
    protocol_prefix = "tcp://";
    boost::asio::ip::tcp::endpoint temp6(boost::asio::ip::tcp::v6(), 0);
    RAY_CHECK(temp6.size() == addr.size());
    const sockaddr *src_addr = addr.data();
    sockaddr *dst_addr = temp6.data();
    *reinterpret_cast<sockaddr_in6 *>(dst_addr) = *reinterpret_cast<const sockaddr_in6 *>(src_addr);
    std::ostringstream stream;
    stream << temp6;
    url_string = stream.str();
    break;
  }
#ifdef BOOST_ASIO_HAS_LOCAL_SOCKETS
  case AF_UNIX:
    protocol_prefix = "unix://";
    url_string.append(reinterpret_cast<const struct sockaddr_un *>(addr.data())->sun_path,
                      addr.size() - offsetof(sockaddr_un, sun_path));
    break;
#endif
  default:
    RAY_LOG(FATAL) << "unsupported protocol family: " << addr.protocol().family();
    break;
  }
  if (prepend_scheme) {
    url_string.insert(0, protocol_prefix);
  }
  return url_string;
}

boost::asio::generic::basic_endpoint<boost::asio::generic::stream_protocol>
UrlToAddress(const std::string &url_input, int fallback_port) {
  // Syntax reference: https://en.wikipedia.org/wiki/URL#Syntax
  // Note that we're a bit more flexible, to allow parsing "127.0.0.1" as a URL.
  boost::asio::generic::stream_protocol::endpoint outcome;
  std::string address_part = url_input, scheme_part;
  if (address_part.find("unix://") == 0) {
    scheme_part = "unix://";
    address_part.erase(0, scheme_part.size());
  } else if (address_part.size() > 0 && ray::IsDirSep(address_part[0])) {
    scheme_part = "unix://";
  } else if (address_part.find("tcp://") == 0) {
    scheme_part = "tcp://";
    address_part.erase(0, scheme_part.size());
  } else {
    scheme_part = "tcp://";
  }
  if (scheme_part == "unix://") {
#ifdef BOOST_ASIO_HAS_LOCAL_SOCKETS
    size_t max_len = sizeof(sockaddr_un().sun_path) / sizeof(*sockaddr_un().sun_path) - 1;
    RAY_CHECK(address_part.size() <= max_len)
        << "AF_UNIX path length cannot exceed " << max_len << " bytes: " << address_part;
    outcome = boost::asio::local::stream_protocol::endpoint(address_part);
#else
    RAY_LOG(FATAL) << "UNIX-domain socket endpoints are not supported: " << url_input;
#endif
  } else if (scheme_part == "tcp://") {
    std::string::const_iterator iter = address_part.begin();
    std::string host_name = ExtractToken(iter, "[%*[^][/]]");
    host_name = host_name.empty() ? ExtractToken(iter, "%*[^/:]") : host_name.substr(1, host_name.size() - 2);
    std::string port_text = ExtractToken(iter, ":%*d");
    int port_num = port_text.empty() ? fallback_port : std::stoi(port_text.substr(1));
    outcome = boost::asio::ip::tcp::endpoint(boost::asio::ip::make_address(host_name), port_num);
  } else {
    RAY_LOG(FATAL) << "Unable to parse socket endpoint: " << url_input;
  }
  return outcome;
}

/// Rules:
/// 1. Adjacent tokens are concatenated, so "a"b'c' is just abc
/// 2. Outside quotes: backslashes make the next character literal; space & tab delimit
/// 3. Inside "...": backslashes escape a following " and \ and otherwise stay literal
/// 4. Inside '...': no escaping occurs
/// 5. [&|;<>`#()!] etc. are literal, but should be in '...' to avoid confusion.
/// Note: POSIX shells can perform additional processing (like piping) not reflected here.
/// Refer to the unit tests for examples.
/// To compare against the platform's behavior, try a command like the following:
/// $ python3 -c "import sys; [print(a) for a in sys.argv[1:]]" \x\\y "\x\\y" '\x\\y'
/// Python analog: shlex.split(s)
static std::vector<std::string> ParsePosixStyle(const std::string &input) {
  RAY_CHECK(input.find('\0') >= input.size()) << "Invalid null character in command line";
  const char space_char = ' ', tab_char = '\t', backslash_char = '\\', single_quote = '\'', double_quote = '\"';
  char context = space_char;
  bool backslash_next = false, argument_started = false;
  std::vector<std::string> tokens;
  std::string current_token;
  for (char character : input) {
    bool is_separator = false;
    if (backslash_next) {
      if (context == double_quote && (character == backslash_char || character == double_quote)) {
        current_token.pop_back();  // remove backslash because it precedes \ or " in double-quotes
      }
      current_token += character;
      backslash_next = false;
    } else if (context == double_quote || context == single_quote) {  // inside quotes
      if (character == context) {
        context = space_char;  // leaving quotes
      } else {
        current_token += character;
        backslash_next = context == double_quote && character == backslash_char;  // backslash in "..."
      }
    } else {  // outside quotes
      if (character == space_char || character == tab_char) {
        is_separator = true;
        if (argument_started) {  // we just finished an argument
          tokens.push_back(current_token);
        }
        current_token.clear();
      } else if (character == double_quote || character == single_quote) {
        context = character;  // entering quotes
      } else if (character == backslash_char) {
        backslash_next = true;
      } else {
        current_token += character;
      }
    }
    argument_started = !is_separator;
  }
  if (argument_started) {
    tokens.push_back(current_token);
  }
  return tokens;
}

/// Rules:
/// 1. Adjacent tokens are concatenated, so "a"b"c" is just abc
/// 2. Backslashes escape when eventually followed by " but stay literal otherwise
/// 3. Outside "...": space and tab are delimiters
/// 4. [&|:<>^#()] etc. are literal, but should be in "..." to avoid confusion.
/// Note: Windows tools have additional processing & quirks not reflected here.
/// Refer to the unit tests for examples.
/// To compare against the platform's behavior, try a command like the following:
/// > python3 -c "import sys; [print(a) for a in sys.argv[1:]]" \x\\y "\x\\y"
/// Python analog: None (would be shlex.split(s, posix=False), but it doesn't unquote)
static std::vector<std::string> ParseWindowsStyle(const std::string &input) {
  RAY_CHECK(input.find('\0') >= input.size()) << "Invalid null character in command line";
  // The if statement below may be incorrect. See:
  // https://github.com/ray-project/ray/pull/10131#discussion_r473871563
  if (input.empty()) {
    return {};
  }
  std::vector<std::string> tokens;
  std::string token, extended_input = input + '\0';
  std::string::const_iterator start_iter = extended_input.begin(), end_iter = extended_input.end() - 1;
  for (bool done = false, inside_quotes = false; !done;) {
    if (!inside_quotes && (start_iter >= end_iter || ExtractToken(start_iter, "%*[ \t]").size())) {
      tokens.push_back(token);
      token.clear();
    }
    done |= start_iter >= end_iter && !inside_quotes;
    token += ExtractToken(start_iter, inside_quotes ? "%*[^\\\"]" : "%*[^\\\" \t]");
    std::string potential_escape = ExtractToken(start_iter, "%*[\\]");
    bool is_escaping = potential_escape.size() % 2 != 0;
    if (*start_iter == '\"') {
      potential_escape.erase(potential_escape.size() / 2);
      potential_escape.append(is_escaping ? 1 : 0, *start_iter);
      inside_quotes ^= !is_escaping;
      ++start_iter;
    }
    token += potential_escape;
  }
  return tokens;
}

std::vector<std::string> SplitCommandLine(const std::string &input, CommandLineSyntax type) {
  if (type == CommandLineSyntax::System) {
#ifdef _WIN32
    type = CommandLineSyntax::Windows;
#else
    type = CommandLineSyntax::POSIX;
#endif
  }
  std::vector<std::string> tokens;
  switch (type) {
  case CommandLineSyntax::POSIX:
    tokens = ParsePosixStyle(input);
    break;
  case CommandLineSyntax::Windows:
    tokens = ParseWindowsStyle(input);
    break;
  default:
    RAY_LOG(FATAL) << "invalid command line syntax";
    break;
  }
  return tokens;
}

/// Python analog: shlex.join(args)
std::string JoinPosixArgs(const std::vector<std::string> &arguments) {
  std::string result;
  const std::string safe_chars("%*[-A-Za-z0-9%_=+]");
  const char single_quote = '\'';
  for (size_t index = 0; index != arguments.size(); ++index) {
    std::string arg = arguments[index], arg_with_null = arg + '\0';
    std::string::const_iterator iter = arg_with_null.begin();
    if (ExtractToken(iter, safe_chars) != arg) {
      // Prefer single-quotes. Double-quotes have unpredictable behavior, e.g. for "\!".
      std::string quoted;
      quoted += single_quote;
      for (char ch : arg) {
        if (ch == single_quote) {
          quoted += single_quote;
          quoted += '\\';
        }
        quoted += ch;
        if (ch == single_quote) {
          quoted += single_quote;
        }
      }
      quoted += single_quote;
      arg = quoted;
    }
    if (index > 0) {
      result += ' ';
    }
    result += arg;
  }
  return result;
}

// Python analog: subprocess.list2cmdline(args)
static std::string JoinWindowsArgs(const std::vector<std::string> &args) {
  std::string result;
  const std::string safe_chars("%*[-A-Za-z0-9%_=+]");
  const char double_quote = '\"';
  for (size_t idx = 0; idx != args.size(); ++idx) {
    std::string arg = args[idx], arg_with_null = arg + '\0';
    std::string::const_iterator iter = arg_with_null.begin();
    if (ExtractToken(iter, safe_chars) != arg) {
      // Escape only backslashes that precede double-quotes
      std::string quoted;
      quoted += double_quote;
      size_t backslash_count = 0;
      for (char ch : arg) {
        if (ch == double_quote) {
          quoted.append(backslash_count, '\\');
          quoted += '\\';
        }
        quoted += ch;
        backslash_count = ch == '\\' ? backslash_count + 1 : 0;
      }
      quoted.append(backslash_count, '\\');
      quoted += double_quote;
      arg = quoted;
    }
    if (idx > 0) {
      result += ' ';
    }
    result += arg;
  }
  return result;
}

std::string JoinCommandLine(const std::vector<std::string> &args,
                            CommandLineSyntax syntax) {
  if (syntax == CommandLineSyntax::System) {
#ifdef _WIN32
    syntax = CommandLineSyntax::Windows;
#else
    syntax = CommandLineSyntax::POSIX;
#endif
  }
  std::string result;
  switch (syntax) {
  case CommandLineSyntax::POSIX:
    result = JoinPosixArgs(args);
    break;
  case CommandLineSyntax::Windows:
    result = JoinWindowsArgs(args);
    break;
  default:
    RAY_LOG(FATAL) << "invalid command line syntax";
    break;
  }
  return result;
}

std::shared_ptr<std::unordered_map<std::string, std::string>> ParseQueryParameters(std::string full_url) {
  auto params = std::make_shared<std::unordered_map<std::string, std::string>>();
  std::string separator = "?";
  size_t position = 0;
  position = full_url.find(separator);
  if (position == std::string::npos) {
    return params;
  }
  const std::string base_url = full_url.substr(0, position);
  params->emplace("url", base_url);
  full_url.erase(0, position + separator.length());
  const std::string pair_separator = "&";
  auto extract_key_value = [](std::string kv_pair) {
    // Parse the query key value pair.
    const std::string delimiter = "=";
    size_t eq_pos = 0;
    eq_pos = kv_pair.find(delimiter);
    const std::string key = kv_pair.substr(0, eq_pos);
    return std::make_pair(key, kv_pair.substr(key.size() + 1));
  };
  while ((position = full_url.find(pair_separator)) != std::string::npos) {
    std::string segment = full_url.substr(0, position);
    auto kv_pair = extract_key_value(segment);
    params->emplace(kv_pair.first, kv_pair.second);
    full_url.erase(0, position + separator.length());
  }
  std::string last_segment = full_url.substr(0, position);
  auto final_kv_pair = extract_key_value(last_segment);
  params->emplace(final_kv_pair.first, final_kv_pair.second);
  return params;
}

namespace ray {
bool IsRayletDead(const std::string &pid_string) {
  auto needs_shutdown = false;
  if (!pid_string.empty()) {
    auto pid = static_cast<pid_t>(std::stoi(pid_string));
    if (!IsProcessAlive(pid)) {
      needs_shutdown = true;
    }
  } else if (!IsParentProcessAlive()) {
    needs_shutdown = true;
  }
  return needs_shutdown;
}

void ImmediateExit() {
  ray::RayLog::ShutDownRayLog();
  _Exit(1);
}
}  // namespace ray

