static FPhyaEngineContext* GPhyaContext = nullptr;

static void InitializePhyaSystem()
{
	if(GPhyaContext == nullptr)
	{
		paBlock::setnMaxFrames(AudioBlockSize);					
		paBlock::pool.allocate(NUM_OBJECTS + 5);				
		paContact::pool.allocate(100);
		paImpact::pool.allocate(100);
		paFunSurface::contactGenPool.allocate(20);			
		paFunSurface::impactGenPool.allocate(20);			
		paRes::activeResList.allocate(NUM_OBJECTS);			
		paSetnFramesPerSecond(AudioSampleRate);
		paInit();
		GPhyaContext = new FPhyaEngineContext;
	}
}

void UPhyaCollisionHandler::InitCollisionHandler()
{
	InitializePhyaSystem();

	ProceduralWave = NewObject<USoundWaveProcedural>(this);
	ProceduralWave->SampleRate = AudioSampleRate;
	ProceduralWave->NumChannels = 1;
	ProceduralWave->Duration = INDEFINITELY_LOOPING_DURATION;
	ProceduralWave->bLooping = false;
	ProceduralWave->OnSoundWaveProceduralUnderflow = FOnSoundWaveProceduralUnderflow::CreateUObject(this, &UPhyaCollisionHandler::ProceduralWaveUnderflow);

	AudioComp = NewObject<UAudioComponent>(this);
	AudioComp->SetSound(ProceduralWave);
	AudioComp->Play();

	Whitesurf = new paFunSurface;			
	Whitefun = new paWhiteFun;			
	Whitesurf->setFun(Whitefun);							
	Whitesurf->setContactGain(32000.0f);			

	Whitesurf->setCutoffFreqAtRoll(10.0f);				
	Whitesurf->setCutoffFreqRate(1000.0f);				
	Whitesurf->setCutoffFreq2AtRoll(10.0f);				
	Whitesurf->setCutoffFreq2Rate(1000.0f);

	Whitesurf->setContactDirectGain(0.0);				
	Whitesurf->setContactGain(70000.0);
	Whitesurf->setHardness(10000.0f);  

	ModalData = new paModalData;
	ModalData->read(ResonanceData);

	for(int32 Index=0; Index < NUM_OBJECTS; Index++) 
	{
		paModalRes* Res = new paModalRes;
		Res->setData(ModalData);
		Res->setQuietLevel(1.0f);		
		Res->setAuxAmpScale(.1f);
		Res->setAuxFreqScale(1.0f);
		Res->setAuxDampScale(1.0f);

		paBody* Body = new paBody;
		Body->setRes(Res);			
		Body->setSurface(Whitesurf);
		Bodies.Add(Body);
	}
}

void UPhyaCollisionHandler::ProceduralWaveUnderflow(USoundWaveProcedural* InProceduralWave, int32 SamplesRequired)
{
	check(ProceduralWave == InProceduralWave);

	const int32 QueuedSamples = ProceduralWave->GetAvailableAudioByteCount()/sizeof(uint16);
	const int32 SamplesNeeded = SamplesRequired - QueuedSamples;
	const int32 BlocksNeeded = FMath::CeilToInt(SamplesNeeded / AudioBlockSize);

	UE_LOG(LogTemp, Log, TEXT("Generating %d blocks for %s"), BlocksNeeded, *GetWorld()->GetPathName());

	TArray<int16> SampleBuffer;
	SampleBuffer.AddUninitialized(BlocksNeeded * AudioBlockSize);

	int32 CurrentSampleIndex = 0;
	for(int32 BlockIdx=0; BlockIdx < BlocksNeeded; BlockIdx++)
	{
		paBlock* AudioBlock = paTick();
		float* AudioData = AudioBlock->getStart();
		for(int32 SampleIdx=0; SampleIdx < AudioBlockSize; SampleIdx++)
		{
			SampleBuffer[CurrentSampleIndex] = static_cast<int16>(AudioData[SampleIdx]);
			CurrentSampleIndex++;
		}
	}

	ProceduralWave->QueueAudio((uint8*)SampleBuffer.GetData(), SampleBuffer.Num() * sizeof(int16));
}

void UPhyaCollisionHandler::TestImpact()
{
	UE_LOG(LogTemp, Log, TEXT("Creating Test Impact for %s"), *GetWorld()->GetPathName());

	paImpact* Impact = paImpact::newImpact();
	if(Impact != nullptr)
	{
		Impact->setBody1(Bodies[0]);

		paImpactDynamicData ImpactData;
		ImpactData.relTangentSpeedAtImpact = 0;
		ImpactData.impactImpulse = 1.0;
		Impact->setDynamicData(&ImpactData);
	}
}

void UPhyaCollisionHandler::HandlePhysicsCollisions_AssumesLocked(const TArray<FCollisionNotifyInfo>& PendingCollisionNotifies)
{
	if(GetWorld()->HasBegunPlay())
	{
		TMap< FPhyaBodyInstancePair, TSharedPtr<FPhyaPairInfo> > ExpiredPairs = PairHash;

		for(int32 InfoIndex=0; InfoIndex < PendingCollisionNotifies.Num(); InfoIndex++)
		{
			const FCollisionNotifyInfo& NotifyInfo = PendingCollisionNotifies[InfoIndex];
			FPhyaBodyInstancePair Pair(NotifyInfo.Info0.GetBodyInstance(), NotifyInfo.Info1.GetBodyInstance());

			TSharedPtr<FPhyaPairInfo> PairInfo = PairHash.FindRef(Pair);

			if(PairInfo.IsValid())
			{
				UE_LOG(LogTemp, Log, TEXT("EXISTING"));
				ExpiredPairs.Remove(Pair);
			}
			else
			{
				UE_LOG(LogTemp, Log, TEXT("NEW"));
				PairInfo = MakeShareable(new FPhyaPairInfo);
				PairHash.Add(Pair, PairInfo);

				paImpact* Impact = paImpact::newImpact();
				if(Impact != nullptr)
				{
					Impact->setBody1(Bodies[0]);

					paImpactDynamicData ImpactData;
					ImpactData.relTangentSpeedAtImpact = 0;
					ImpactData.impactImpulse = 1.0;
					Impact->setDynamicData(&ImpactData);
				}
			}
		}

		for(auto It = ExpiredPairs.CreateConstIterator(); It; ++It)
		{
			UE_LOG(LogTemp, Log, TEXT("EXPIRE"));
			FPhyaBodyInstancePair Pair = It.Key();
			PairHash.Remove(Pair);
		}
	}
}

