/// \TODO generalize to have pins and frequency be maintained by caller
void PWM::init(const uint32_t system_clock_hz) {
  enable_peripheral_clock(PeripheralID::Timer2);
  // Connect PB3 to timer 2
  // [DS] Table 17 (pg 77)
  GPIO::set_alternate_function(GPIO::Port::B, /*pin =*/3,
                               GPIO::AlternativeFuncion::AF1);  // TIM2_CH2
  TimerReg *timer = Timer2Base;
  // Set the frequency
  timer->reload_register = (system_clock_hz / pwm_freq_hz_) - 1;
  // Configure channel 2 in PWM output mode 1
  // with preload enabled.  The preload means that
  // the new PWM duty cycle gets written to a shadow
  // register and copied to the active register
  // at the start of the next cycle.
  timer->cc_mode[0] = 0x6800;
  timer->cc_enable = 0x10;
  // Start with 0% duty cycle
  timer->cc_value[1] = 0;
  // Load the shadow registers
  timer->event_register = 1;
  // Start the counter
  timer->control_reg1.bitfield.auto_reload_preload = 1;
  timer->control_reg1.bitfield.counter_enable = 1;
}
// Set the PWM period.
void PWM::adjust(const PwmPin pin, const float ratio) {
  auto [timer_ptr, channel] = [&]() -> std::pair<TimerReg *, int> {
    switch (pin) {
      case PwmPin::Blower:
        return {Timer2Base, 1};
    }
    // All cases covered above (and GCC checks this).
    __builtin_unreachable();
  }();
  timer_ptr->cc_value[channel] = static_cast<uint32_t>(static_cast<float>(timer_ptr->reload_register) * ratio);
}
#else
#include <cassert>
void PWM::init(const uint32_t system_clock_hz) {}
void PWM::configure_pin(PwmPin pin, GPIO::PinMode mode) { pwm_pin_modes_[pin] = mode; }
void PWM::adjust(PwmPin pin, float ratio) {
  if (pwm_pin_modes_[pin] != GPIO::PinMode::Output) {
    assert(false && "Can only write to an OUTPUT pin");
  }
  pwm_pin_values_[pin] = ratio;
}
