namespace Certain
{
    static const uint64_t kTransmissionDelayMs = 10;

    void clsCatchUpCtrl::AdjustThroughputLimit(uint32_t iNewSpeedKB)
    {
        if (m_iMaxCatchUpSpeedKB == iNewSpeedKB)
        {
            return;
        }
        if (iNewSpeedKB == 0)
        {
            return;
        }

        CertainLogImpt("Changing m_iMaxCatchUpSpeedKB from %u to %u",
                m_iMaxCatchUpSpeedKB, iNewSpeedKB);
        m_iMaxCatchUpSpeedKB = iNewSpeedKB;

        uint64_t iSpeedInBytes = m_iMaxCatchUpSpeedKB * uint64_t(1 << 10);
        m_iMaxByteSize = iSpeedInBytes / (1000.0 / kTransmissionDelayMs);
        assert(m_iMaxByteSize > 0);

        m_iNextSendTimeMS = 0;
        m_iRemainByteSize = 0;

        CertainLogInfo("Calculated iSpeedInBytes %lu with m_iMaxByteSize %lu",
                iSpeedInBytes, m_iMaxByteSize);
    }

    void clsCatchUpCtrl::AdjustConcurrencyLimit(uint32_t iNewLimit)
    {
        if (m_iMaxCatchUpCnt == iNewLimit)
        {
            return;
        }

        CertainLogImpt("Updating m_iMaxCatchUpCnt from %u to %u",
                m_iMaxCatchUpCnt, iNewLimit);
        m_iMaxCatchUpCnt = iNewLimit;
        m_iUseCount = 0;
        m_iNextCountTimeMS = GetCurrTimeMS() + 1000;
    }

    uint64_t clsCatchUpCtrl::ReserveCount()
    {
        if (m_iUseCount < m_iMaxCatchUpCnt)
        {
            ++m_iUseCount;
            return 0;
        }

        uint64_t iNowMs = GetCurrTimeMS();
        if (iNowMs < m_iNextCountTimeMS)
        {
            return m_iNextCountTimeMS - iNowMs;
        }

        // Minimum rate: at least one catch-up per second.
        m_iUseCount = 1;
        m_iNextCountTimeMS = iNowMs + 1000;
        return 0;
    }

    uint64_t clsCatchUpCtrl::ReserveByteSize(uint64_t iDataSize)
    {
        if (m_iRemainByteSize >= iDataSize)
        {
            m_iRemainByteSize -= iDataSize;
            return 0;
        }

        uint64_t iNowMs = GetCurrTimeMS();
        if (iNowMs < m_iNextSendTimeMS)
        {
            return m_iNextSendTimeMS - iNowMs;
        }

        if (iDataSize <= m_iMaxByteSize)
        {
            m_iRemainByteSize = m_iMaxByteSize - iDataSize;
            m_iNextSendTimeMS = iNowMs + kTransmissionDelayMs;
            return 0;
        }

        m_iNextSendTimeMS = iNowMs + (
                kTransmissionDelayMs * iDataSize) / m_iMaxByteSize;
        m_iRemainByteSize = 0;
        return 0;
    }

    uint64_t clsCatchUpWorker::EstimatePayloadSize(clsPaxosCmd *poCmd)
    {
        uint64_t iBaseSize = 42; // approximate header overhead
        const EntryRecord_t &tSrc = poCmd->GetSrcRecord();
        const EntryRecord_t &tDst = poCmd->GetDestRecord();

        if (tSrc.tValue.iValueID > 0 &&
                tSrc.tValue.iValueID != tDst.tValue.iValueID)
        {
            iBaseSize += tSrc.tValue.strValue.size();
        }

        return iBaseSize;
    }

    int clsCatchUpWorker::Initialize(clsConfigure *poConfig,
            clsCertainUserBase *poUser)
    {
        m_poConf = poConfig;
        m_iLocalServerID = poConfig->GetLocalServerID();
        m_iMaxCatchUpConcurr = poConfig->GetMaxCatchUpConcurr();
        m_iAcceptorNum = poConfig->GetAcceptorNum();
        m_iServerNum = poConfig->GetServerNum();
        m_iPrevPrintTimeMS = 0;

        for (uint32_t idx = 0; idx < m_iServerNum; ++idx)
        {
            m_iCatchUpCnt.emplace_back(0);
            m_iCatchUpSize.emplace_back(0);
        }

        uint32_t iSpeedKB = poConfig->GetMaxCatchUpSpeedKB();
        if (iSpeedKB == 0)
        {
            CertainLogFatal("Invalid iMaxCatchUpSpeedKB == 0");
            return -1;
        }

        m_poCatchUpCtrl = new clsCatchUpCtrl;
        m_poCatchUpCtrl->AdjustThroughputLimit(iSpeedKB);
        m_poCatchUpQueue = clsAsyncQueueMng::GetInstance()->GetCatchUpReqQueue(0);
        m_poIOWorkerRouter = clsIOWorkerRouter::GetInstance();
        m_poCertainUser = poUser;

        return 0;
    }

    void clsCatchUpWorker::Cleanup()
    {
        delete m_poCatchUpQueue;
        m_poCatchUpQueue = nullptr;
        delete m_poCatchUpCtrl;
        m_poCatchUpCtrl = nullptr;
    }

    int clsCatchUpWorker::EnqueueCatchUpCommand(clsPaxosCmd *poCmd)
    {
        AssertNotMore(poCmd->GetEntry(), poCmd->GetMaxChosenEntry());
        if (m_poCatchUpQueue->Size() >= m_iMaxCatchUpConcurr)
        {
            return -1;
        }

        int iStatus = m_poCatchUpQueue->PushByMultiThread(poCmd);
        if (iStatus != 0)
        {
            OSS::ReportCatchUpQueueErr();
            CertainLogError("Failed to push command: PushByMultiThread returned %d", iStatus);
            return -2;
        }

        return 0;
    }

    void clsCatchUpWorker::FlushStatistics()
    {
        uint64_t iNowMs = GetCurrTimeMS();
        if (iNowMs >= m_iPrevPrintTimeMS + 1000)
        {
            uint64_t iTotalOps = 0;
            uint64_t iTotalBytes = 0;
            bool bActiveServers = false;
            std::string strSummary;

            for (uint32_t idx = 0; idx < m_iServerNum; ++idx)
            {
                char tmp[128];
                snprintf(tmp, sizeof(tmp), " S%u(%lu, %lu)",
                        idx, m_iCatchUpCnt[idx], m_iCatchUpSize[idx]);
                strSummary.append(tmp);

                if (m_iCatchUpCnt[idx] > 0)
                {
                    bActiveServers = true;
                }

                iTotalOps += m_iCatchUpCnt[idx];
                iTotalBytes += m_iCatchUpSize[idx];

                m_iCatchUpCnt[idx] = 0;
                m_iCatchUpSize[idx] = 0;
            }

            if (bActiveServers)
            {
                CertainLogImpt("catchup_stat_for_srv %u Sid(%lu, %lu):%s",
                        m_iLocalServerID, iTotalOps, iTotalBytes, strSummary.c_str());
            }

            m_iPrevPrintTimeMS = iNowMs;
        }
    }

    void clsCatchUpWorker::AccumulateStats(uint64_t iEntityID,
            uint32_t iTargetAcceptorID, uint64_t iPayloadSize)
    {
        uint32_t iLocalAcceptorID = 0;
        AssertEqual(m_poCertainUser->GetLocalAcceptorID(
                    iEntityID, iLocalAcceptorID), 0);

        uint32_t iTargetServerID = m_iServerNum;

        if (iTargetAcceptorID < m_iAcceptorNum)
        {
            AssertNotEqual(iTargetAcceptorID, iLocalAcceptorID);
            AssertEqual(m_poCertainUser->GetServerID(
                        iEntityID, iTargetAcceptorID, iTargetServerID), 0);
            AssertLess(iTargetServerID, m_iServerNum);

            ++m_iCatchUpCnt[iTargetServerID];
            m_iCatchUpSize[iTargetServerID] += iPayloadSize;
        }
        else
        {
            for (uint32_t idx = 0; idx < m_iAcceptorNum; ++idx)
            {
                if (idx == iLocalAcceptorID)
                {
                    continue;
                }

                AssertEqual(m_poCertainUser->GetServerID(
                            iEntityID, idx, iTargetServerID), 0);
                AssertLess(iTargetServerID, m_iServerNum);

                ++m_iCatchUpCnt[iTargetServerID];
                m_iCatchUpSize[iTargetServerID] += iPayloadSize;
            }
        }

        FlushStatistics();
    }

    void clsCatchUpWorker::Execute()
    {
        int iStatus;
        SetThreadTitle("catchup_%u", m_iLocalServerID);
        CertainLogInfo("Starting catchup thread %u", m_iLocalServerID);

        clsSmartSleepCtrl oSlpCtrl(200, 1000);

        while (true)
        {
            if (CheckIfExiting(1000))
            {
                printf("Terminating catchup_%u\n", m_iLocalServerID);
                CertainLogInfo("catchup_%u exiting", m_iLocalServerID);
                break;
            }

            m_poCatchUpCtrl->AdjustThroughputLimit(m_poConf->GetMaxCatchUpSpeedKB());
            m_poCatchUpCtrl->AdjustConcurrencyLimit(m_poConf->GetMaxCatchUpCnt());

            clsPaxosCmd *poCmd = nullptr;
            iStatus = m_poCatchUpQueue->TakeByOneThread(&poCmd);

            if (iStatus != 0)
            {
                oSlpCtrl.Sleep();
                FlushStatistics();
                continue;
            }
            else
            {
                oSlpCtrl.Reset();
            }

            uint64_t iEntityID = poCmd->GetEntityID();
            uint32_t iTargetAcceptorID = poCmd->GetDestAcceptorID();
            uint64_t iPayloadSize = EstimatePayloadSize(poCmd);

            while (true)
            {
                uint64_t iDelayMs = m_poCatchUpCtrl->ReserveByteSize(iPayloadSize);
                if (iDelayMs == 0)
                {
                    break;
                }

                CertainLogImpt("Throttling due to byte limit: size=%lu wait=%lu ms",
                        iPayloadSize, iDelayMs);
                usleep(iDelayMs * 1000);
            }

            while (true)
            {
                uint64_t iDelayMs = m_poCatchUpCtrl->ReserveCount();
                if (iDelayMs == 0)
                {
                    break;
                }

                CertainLogImpt("Throttling due to count limit: wait=%lu ms", iDelayMs);
                usleep(iDelayMs * 1000);
            }

            iStatus = m_poIOWorkerRouter->Go(poCmd);
            if (iStatus != 0)
            {
                CertainLogError("Routing failed: Go returned %d cmd: %s",
                        iStatus, poCmd->GetTextCmd().c_str());
                delete poCmd;
                poCmd = nullptr;
            }
            else
            {
                AccumulateStats(iEntityID, iTargetAcceptorID, iPayloadSize);
            }
        }
    }
