#include "pch.h"
using namespace winrt;
using namespace Windows::Foundation;
using namespace Windows::Foundation::Collections;

TEST_CASE("single_threaded_observable_vector_renamed")
{
    {
        // Basic smoke test for strongly-typed observable vector - exhaustive tests already exist elsewhere.
        IObservableVector<int> vec = single_threaded_observable_vector<int>();
        bool eventTriggered{};
        vec.VectorChanged([&](auto && ...)
            {
                eventTriggered = vec.GetAt(0) == 456;
            });
        vec.Append(456);
        REQUIRE(eventTriggered);
    }
    {
        // Making sure we can still create IInspectable collections that aren't "special".
        IObservableVector<IInspectable> vec = single_threaded_observable_vector<IInspectable>();
        bool eventTriggered{};
        vec.VectorChanged([&](auto && ...)
            {
                eventTriggered = unbox_value<int>(vec.GetAt(0)) == 789;
            });
        vec.Append(box_value(789));
        REQUIRE(eventTriggered);
    }
    {
        // VectorChanged is raised on both interface types.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        bool triggered_i{};
        bool triggered_o{};
        vec_i.VectorChanged([&](IObservableVector<int> const& sender, IVectorChangedEventArgs const&)
            {
                triggered_i = sender.GetAt(0) == 456;
                REQUIRE(sender == vec_i);
            });
        vec_o.VectorChanged([&](IObservableVector<IInspectable> const& sender, IVectorChangedEventArgs const&)
            {
                triggered_o = unbox_value<int>(sender.GetAt(0)) == 456;
                REQUIRE(sender == vec_o);
            });
        vec_i.Append(456);
        REQUIRE(triggered_i);
        REQUIRE(triggered_o);
    }
    {
        // VectorChanged forwards underlying token.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        int count_i{};
        int count_o{};
        auto token_i = vec_i.VectorChanged([&](IObservableVector<int> const&, IVectorChangedEventArgs const&)
            {
                ++count_i;
            });
        auto token_o = vec_o.VectorChanged([&](IObservableVector<IInspectable> const&, IVectorChangedEventArgs const&)
            {
                ++count_o;
            });
        REQUIRE(count_i == 0);
        REQUIRE(count_o == 0);
        vec_i.Append(1);
        REQUIRE(count_i == 1);
        REQUIRE(count_o == 1);
        vec_i.VectorChanged(token_i);
        vec_i.Append(1);
        REQUIRE(count_i == 1);
        REQUIRE(count_o == 2);
        vec_o.VectorChanged(token_o);
        vec_i.Append(1);
        REQUIRE(count_i == 1);
        REQUIRE(count_o == 2);
    }
    {
        // Confirming the underlying container is shared and remains in sync.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        vec_i.Append(0);
        vec_o.Append(box_value(1));
        REQUIRE(vec_i.Size() == 2);
        REQUIRE(vec_o.Size() == 2);
        REQUIRE(vec_i.GetAt(0) == 0);
        REQUIRE(unbox_value<int>(vec_o.GetAt(0)) == 0);
        REQUIRE(vec_i.GetAt(1) == 1);
        REQUIRE(unbox_value<int>(vec_o.GetAt(1)) == 1);
    }
    {
        // Different iterator types over the same container.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 3,4 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        IIterator<int> iter_i = vec_i.First();
        IIterator<IInspectable> iter_o = vec_o.First();
        REQUIRE(iter_i.HasCurrent());
        REQUIRE(iter_o.HasCurrent());
        REQUIRE(iter_i.Current() == 3);
        REQUIRE(unbox_value<int>(iter_o.Current()) == 3);
        REQUIRE(iter_i.MoveNext());
        REQUIRE(iter_o.MoveNext());
        REQUIRE(iter_i.HasCurrent());
        REQUIRE(iter_o.HasCurrent());
        REQUIRE(iter_i.Current() == 4);
        REQUIRE(unbox_value<int>(iter_o.Current()) == 4);
        REQUIRE(!iter_i.MoveNext());
        REQUIRE(!iter_o.MoveNext());
        REQUIRE(!iter_i.HasCurrent());
        REQUIRE(!iter_o.HasCurrent());
        REQUIRE_THROWS_AS(iter_i.Current(), hresult_out_of_bounds);
        REQUIRE_THROWS_AS(iter_o.Current(), hresult_out_of_bounds);
    }
    {
        // GetMany always needs a bit of extra testing.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 5,6 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        IIterator<int> iter_i = vec_i.First();
        IIterator<IInspectable> iter_o = vec_o.First();
        std::array<int, 4> buffer_i{};
        REQUIRE(2 == iter_i.GetMany(buffer_i));
        REQUIRE(buffer_i[0] == 5);
        REQUIRE(buffer_i[1] == 6);
        REQUIRE(buffer_i[2] == 0);
        std::array<IInspectable, 4> buffer_o{};
        REQUIRE(2 == iter_o.GetMany(buffer_o));
        REQUIRE(unbox_value<int>(buffer_o[0]) == 5);
        REQUIRE(unbox_value<int>(buffer_o[1]) == 6);
        REQUIRE(buffer_o[2] == nullptr);
        REQUIRE(0 == iter_i.GetMany(buffer_i));
        REQUIRE(0 == iter_o.GetMany(buffer_o));
    }
    {
        // GetMany always needs a bit of extra testing (again).
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 7,8 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        IIterator<int> iter_i = vec_i.First();
        IIterator<IInspectable> iter_o = vec_o.First();
        std::array<int, 2> buffer_i{};
        REQUIRE(1 == iter_i.GetMany(buffer_i));
        REQUIRE(buffer_i[0] == 7);
        std::array<IInspectable, 2> buffer_o{};
        REQUIRE(1 == iter_o.GetMany(buffer_o));
        REQUIRE(unbox_value<int>(buffer_o[0]) == 7);
    }
    {
        // Iterator invalidation works across types.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 9,10 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        IIterator<int> iter_i = vec_i.First();
        IIterator<IInspectable> iter_o = vec_o.First();
        REQUIRE(iter_i.HasCurrent());
        REQUIRE(iter_o.HasCurrent());
        vec_i.Append(11);
        REQUIRE_THROWS_AS(iter_i.HasCurrent(), hresult_changed_state);
        REQUIRE_THROWS_AS(iter_o.HasCurrent(), hresult_changed_state);
    }
    {
        // IndexOf forwarding.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 12,13 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        uint32_t position{};
        REQUIRE((vec_i.IndexOf(13, position) && position == 1));
        position = 0;
        REQUIRE((vec_o.IndexOf(box_value(13), position) && position == 1));
    }
    {
        // GetView forwarding.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 14,15 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        REQUIRE(vec_i.GetView().GetAt(1) == 15);
        REQUIRE(unbox_value<int>(vec_o.GetView().GetAt(1)) == 15);
    }
    {
        // SetAt forwarding.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 16,17 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        REQUIRE(vec_i.GetAt(0) == 16);
        REQUIRE(vec_i.GetAt(1) == 17);
        vec_i.SetAt(0, 100);
        vec_o.SetAt(1, box_value(200));
        REQUIRE(vec_i.GetAt(0) == 100);
        REQUIRE(vec_i.GetAt(1) == 200);
    }
    {
        // InsertAt forwarding.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 20,23 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        REQUIRE(vec_i.Size() == 2);
        vec_i.InsertAt(1, 21);
        vec_o.InsertAt(2, box_value(22));
        REQUIRE(vec_i.Size() == 4);
        REQUIRE(vec_i.GetAt(0) == 20);
        REQUIRE(vec_i.GetAt(1) == 21);
        REQUIRE(vec_i.GetAt(2) == 22);
        REQUIRE(vec_i.GetAt(3) == 23);
    }
    {
        // Append forwarding.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        REQUIRE(vec_i.Size() == 0);
        vec_i.Append(10);
        vec_o.Append(box_value(20));
        REQUIRE(vec_i.Size() == 2);
        REQUIRE(vec_i.GetAt(0) == 10);
        REQUIRE(vec_i.GetAt(1) == 20);
    }
    {
        // GetMany boxing.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 1,2,3,4,5 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        {
            std::array<int, 3> buffer_i{};
            REQUIRE(0 == vec_i.GetMany(5, buffer_i));
        }
        {
            std::array<int, 3> buffer_i{};
            REQUIRE(3 == vec_i.GetMany(0, buffer_i));
            REQUIRE(buffer_i[0] == 1);
            REQUIRE(buffer_i[1] == 2);
            REQUIRE(buffer_i[2] == 3);
        }
        {
            std::array<int, 3> buffer_i{};
            REQUIRE(2 == vec_i.GetMany(3, buffer_i));
            REQUIRE(buffer_i[0] == 4);
            REQUIRE(buffer_i[1] == 5);
            REQUIRE(buffer_i[2] == 0);
        }
        {
            std::array<IInspectable, 3> buffer_o{};
            REQUIRE(0 == vec_o.GetMany(5, buffer_o));
        }
        {
            std::array<IInspectable, 3> buffer_o{};
            REQUIRE(3 == vec_o.GetMany(0, buffer_o));
            REQUIRE(unbox_value<int>(buffer_o[0]) == 1);
            REQUIRE(unbox_value<int>(buffer_o[1]) == 2);
            REQUIRE(unbox_value<int>(buffer_o[2]) == 3);
        }
        {
            std::array<IInspectable, 3> buffer_o{};
            REQUIRE(2 == vec_o.GetMany(3, buffer_o));
            REQUIRE(unbox_value<int>(buffer_o[0]) == 4);
            REQUIRE(unbox_value<int>(buffer_o[1]) == 5);
            REQUIRE(buffer_o[2] == nullptr);
        }
    }
    {
        // ReplaceAll boxing.
        IObservableVector<int> vec_i = single_threaded_observable_vector<int>({ 1,2,3,4,5 });
        IObservableVector<IInspectable> vec_o = vec_i.as<IObservableVector<IInspectable>>();
        {
            IIterator<int> iter_i = vec_i.First();
            IIterator<IInspectable> iter_o = vec_o.First();
            REQUIRE(iter_i.HasCurrent());
            REQUIRE(iter_o.HasCurrent());
            bool triggered_i{};
            bool triggered_o{};
            vec_i.VectorChanged([&](IObservableVector<int> const& sender, IVectorChangedEventArgs const&)
                {
                    triggered_i = sender.GetAt(0) == 999;
                    REQUIRE(sender == vec_i);
                });
            vec_o.VectorChanged([&](IObservableVector<IInspectable> const& sender, IVectorChangedEventArgs const&)
                {
                    triggered_o = unbox_value<int>(sender.GetAt(0)) == 999;
                    REQUIRE(sender == vec_o);
                });
            vec_i.ReplaceAll({ 999 });
            REQUIRE(triggered_i);
            REQUIRE(triggered_o);
            REQUIRE_THROWS_AS(iter_i.HasCurrent(), hresult_changed_state);
            REQUIRE_THROWS_AS(iter_o.HasCurrent(), hresult_changed_state);
            REQUIRE(vec_i.Size() == 1);
            REQUIRE(vec_i.GetAt(0) == 999);
        }
        {
            IIterator<int> iter_i = vec_i.First();
            IIterator<IInspectable> iter_o = vec_o.First();
            REQUIRE(iter_i.HasCurrent());
            REQUIRE(iter_o.HasCurrent());
            bool triggered_i{};
            bool triggered_o{};
            vec_i.VectorChanged([&](IObservableVector<int> const& sender, IVectorChangedEventArgs const&)
                {
                    triggered_i = sender.GetAt(0) == 999;
                    REQUIRE(sender == vec_i);
                });
            vec_o.VectorChanged([&](IObservableVector<IInspectable> const& sender, IVectorChangedEventArgs const&)
                {
                    triggered_o = unbox_value<int>(sender.GetAt(0)) == 999;
                    REQUIRE(sender == vec_o);
                });
            vec_o.ReplaceAll({ box_value(999) });
            REQUIRE(triggered_i);
            REQUIRE(triggered_o);
            REQUIRE_THROWS_AS(iter_i.HasCurrent(), hresult_changed_state);
            REQUIRE_THROWS_AS(iter_o.HasCurrent(), hresult_changed_state);
            REQUIRE(vec_i.Size() == 1);
            REQUIRE(vec_i.GetAt(0) == 999);
        }
    }
}

#include "MeshMergingSettingsCustomization.h"
#include "Engine/MeshMerging.h"
