#define LOCTEXT_NAMESPACE "FMeshMergingSettingCustomization"

FMeshMergingSettingsObjectCustomization::~FMeshMergingSettingsObjectCustomization()
{
}

void FMeshMergingSettingsObjectCustomization::CustomizeDetails(IDetailLayoutBuilder& Builder)
{
	TSharedRef<IPropertyHandle> SettingsProp = Builder.GetProperty(FName("UMeshMergingSettingsObject.Settings"));

	FName MeshSection("MeshSettings");
	IDetailCategoryBuilder& MeshSectionBuilder = Builder.EditCategory(MeshSection);
	TArray<TSharedRef<IPropertyHandle>> DefaultProps;
	MeshSectionBuilder.GetDefaultProperties(DefaultProps, true, true);
	MeshSectionBuilder.AddProperty(SettingsProp);

	FName CategoryKey("Category");
	for (TSharedRef<IPropertyHandle> Prop : DefaultProps)
	{
		const FString& CatName = Prop->GetMetaData(CategoryKey);
		IDetailCategoryBuilder& CatBuilder = Builder.EditCategory(*CatName);
		IDetailPropertyRow& Row = CatBuilder.AddProperty(Prop);

		if (Prop->GetProperty()->GetFName() == GET_MEMBER_NAME_CHECKED(FMeshMergingSettings, SpecificLOD))
		{
			static const FName VisibilityCondition = "EnumCondition";
			int32 ConditionValue = Prop->GetINTMetaData(VisibilityCondition);
			Row.Visibility(TAttribute<EVisibility>::Create(TAttribute<EVisibility>::FGetter::CreateSP(this, &FMeshMergingSettingsObjectCustomization::IsPropertyVisible, ConditionValue)));
		}
		else if (Prop->GetProperty()->GetFName() == GET_MEMBER_NAME_CHECKED(FMeshMergingSettings, LODSelectionType))
		{
			SelectedProperty = Prop;

			TSharedPtr<FPropertyRestriction> Restriction = MakeShareable(new FPropertyRestriction(LOCTEXT("Unsupported","This option is not supported in Merge Actor")));
			const UEnum* const LODTypeEnum = FindObject<UEnum>(ANY_PACKAGE, TEXT("EMeshLODSelectionType"));		
			Restriction->AddDisabledValue(LODTypeEnum->GetNameStringByValue((uint8)EMeshLODSelectionType::CalculateLOD));
			SelectedProperty->AddRestriction(Restriction.ToSharedRef());
		}
	}

	FName MaterialSection("MaterialSettings");
	IDetailCategoryBuilder& MaterialSectionBuilder = Builder.EditCategory(MaterialSection);
	DefaultProps.Empty();
	MaterialSectionBuilder.GetDefaultProperties(DefaultProps, true, true);

	for (TSharedRef<IPropertyHandle> Prop : DefaultProps)
	{
		const FString& CatName = Prop->GetMetaData(CategoryKey);
		IDetailCategoryBuilder& CatBuilder = Builder.EditCategory(*CatName);
		IDetailPropertyRow& Row = CatBuilder.AddProperty(Prop);

		// Disable material settings when exporting all LODs (material baking not supported)
		if (CatName.Compare("MaterialSettings") == 0)
		{
			Row.IsEnabled(TAttribute<bool>::Create(TAttribute<bool>::FGetter::CreateSP(this, &FMeshMergingSettingsObjectCustomization::IsMaterialEditingEnabled)));
		}
	}
}

TSharedRef<IDetailCustomization> FMeshMergingSettingsObjectCustomization::MakeInstance()
{
	return MakeShareable(new FMeshMergingSettingsObjectCustomization);
}

EVisibility FMeshMergingSettingsObjectCustomization::IsPropertyVisible(const int32 TargetValue) const
{
	uint8 CurrentValue = 0;
	SelectedProperty->GetValue(CurrentValue);
	return (CurrentValue == TargetValue) ? EVisibility::Visible : EVisibility::Collapsed;
}

bool FMeshMergingSettingsObjectCustomization::IsMaterialEditingEnabled() const
{
	uint8 CurrentValue = 0;
	SelectedProperty->GetValue(CurrentValue);
	return !(CurrentValue == (uint8)EMeshLODSelectionType::AllLODs);
}

