// =============================================
// Packet flags (modified layout and naming)
// =============================================
static constexpr uint16_t FLAG_TYPE_WIDTH = 1;
static constexpr uint16_t FLAG_TYPE_OFFSET = 15;
static constexpr uint16_t FLAG_TYPE_FIELD = ((1 << FLAG_TYPE_WIDTH) - 1) << FLAG_TYPE_OFFSET;

static constexpr uint16_t FLAG_OP_WIDTH = 4;
static constexpr uint16_t FLAG_OP_OFFSET = 11;
static constexpr uint16_t FLAG_OP_FIELD = ((1 << FLAG_OP_WIDTH) - 1) << FLAG_OP_OFFSET;

static constexpr uint16_t FLAG_AA_WIDTH = 1;
static constexpr uint16_t FLAG_AA_OFFSET = 10;
static constexpr uint16_t FLAG_AA_FIELD = ((1 << FLAG_AA_WIDTH) - 1) << FLAG_AA_OFFSET;

static constexpr uint16_t FLAG_TC_WIDTH = 1;
static constexpr uint16_t FLAG_TC_OFFSET = 9;
static constexpr uint16_t FLAG_TC_FIELD = ((1 << FLAG_TC_WIDTH) - 1) << FLAG_TC_OFFSET;

static constexpr uint16_t FLAG_RD_WIDTH = 1;
static constexpr uint16_t FLAG_RD_OFFSET = 8;
static constexpr uint16_t FLAG_RD_FIELD = ((1 << FLAG_RD_WIDTH) - 1) << FLAG_RD_OFFSET;

static constexpr uint16_t FLAG_RA_WIDTH = 1;
static constexpr uint16_t FLAG_RA_OFFSET = 7;
static constexpr uint16_t FLAG_RA_FIELD = ((1 << FLAG_RA_WIDTH) - 1) << FLAG_RA_OFFSET;

static constexpr uint16_t FLAG_Z_WIDTH = 3;
static constexpr uint16_t FLAG_Z_OFFSET = 4;
static constexpr uint16_t FLAG_Z_FIELD = ((1 << FLAG_Z_WIDTH) - 1) << FLAG_Z_OFFSET;

static constexpr uint16_t FLAG_RCODE_WIDTH = 4;
static constexpr uint16_t FLAG_RCODE_OFFSET = 0;
static constexpr uint16_t FLAG_RCODE_FIELD = ((1 << FLAG_RCODE_WIDTH) - 1) << FLAG_RCODE_OFFSET;

void PacketFlags::setType(PacketType kind) {
  value_ &= ~FLAG_TYPE_FIELD;
  value_ |= (uint16_t(kind) << FLAG_TYPE_OFFSET) & FLAG_TYPE_FIELD;
}

PacketType PacketFlags::getType() {
  return PacketType((value_ & FLAG_TYPE_FIELD) >> FLAG_TYPE_OFFSET);
}

void PacketFlags::setOpcode(Opcode op) {
  value_ &= ~FLAG_OP_FIELD;
  value_ |= (uint16_t(op) << FLAG_OP_OFFSET) & FLAG_OP_FIELD;
}

Opcode PacketFlags::getOpcode() {
  return Opcode((value_ & FLAG_OP_FIELD) >> FLAG_OP_OFFSET);
}

void PacketFlags::setAuthoritativeAnswer(bool isAuth) {
  value_ &= ~FLAG_AA_FIELD;
  value_ |= (uint16_t(isAuth) << FLAG_AA_OFFSET) & FLAG_AA_FIELD;
}

bool PacketFlags::isAuthoritativeAnswer() {
  return bool((value_ & FLAG_AA_FIELD) >> FLAG_AA_OFFSET);
}

void PacketFlags::setTruncation(bool isTruncated) {
  value_ &= ~FLAG_TC_FIELD;
  value_ |= (uint16_t(isTruncated) << FLAG_TC_OFFSET) & FLAG_TC_FIELD;
}

bool PacketFlags::isTruncated() {
  return bool((value_ & FLAG_TC_FIELD) >> FLAG_TC_OFFSET);
}

void PacketFlags::setRecursionDesired(bool wantRD) {
  value_ &= ~FLAG_RD_FIELD;
  value_ |= (uint16_t(wantRD) << FLAG_RD_OFFSET) & FLAG_RD_FIELD;
}

bool PacketFlags::wantsRecursion() {
  return bool((value_ & FLAG_RD_FIELD) >> FLAG_RD_OFFSET);
}

void PacketFlags::setRecursionAvailable(bool hasRA) {
  value_ &= ~FLAG_RA_FIELD;
  value_ |= (uint16_t(hasRA) << FLAG_RA_OFFSET) & FLAG_RA_FIELD;
}

bool PacketFlags::hasRecursionAvailable() {
  return bool((value_ & FLAG_RA_FIELD) >> FLAG_RA_OFFSET);
}

void PacketFlags::setReservedBits(ReservedFlagsTriple z) {
  value_ &= ~FLAG_Z_FIELD;
  value_ |= (uint16_t(z) << FLAG_Z_OFFSET) & FLAG_Z_FIELD;
}

ReservedFlagsTriple PacketFlags::getReservedBits() {
  return ReservedFlagsTriple((value_ & FLAG_Z_FIELD) >> FLAG_Z_OFFSET);
}

void PacketFlags::setResponseCode(ResponseCode rcode) {
  value_ &= ~FLAG_RCODE_FIELD;
  value_ |= (uint16_t(rcode) << FLAG_RCODE_OFFSET) & FLAG_RCODE_FIELD;
}

ResponseCode PacketFlags::getResponseCode() {
  return ResponseCode((value_ & FLAG_RCODE_FIELD) >> FLAG_RCODE_OFFSET);
}

// =============================================
// Record Data Serialization (toBytes)
// =============================================
std::vector<uint8_t> RecordData::toBytes() const {
  std::vector<uint8_t> bytes;
  toBytes(bytes);
  return bytes;
}

void RecordDataIPv4::toBytes(std::vector<uint8_t> &bytes) const {
  bytes.clear();
  bytes.emplace_back(uint8_t(addr_ >> 24));
  bytes.emplace_back(uint8_t(addr_ >> 16));
  bytes.emplace_back(uint8_t(addr_ >> 8));
  bytes.emplace_back(uint8_t(addr_));
}

void RecordDataGeneric::toBytes(std::vector<uint8_t> &bytes) const {
  bytes.clear();
  std::copy(data_.begin(), data_.end(), std::back_inserter(bytes));
}
