#include <benchmark/benchmark.h>

const double tolerance = 0.01;

static void computeOffset(NoSetup, TestProfile const &profile) {
  for (std::size_t idx = 1; idx <= profile.offsetCount; ++idx) {
    double dist = idx * profile.offsetDelta;
    cavc::parallelOffset(profile.pline, dist);
    cavc::parallelOffset(profile.pline, -dist);
  }
}

CAVC_CREATE_BENCHMARKS(computeOffset, NoSetup, computeOffset, benchmark::kMillisecond)
CAVC_CREATE_NO_ARCS_BENCHMARKS(computeOffset, NoSetup, computeOffset, tolerance, benchmark::kMillisecond)
BENCHMARK_MAIN();

#include "../common.h"
#include <rpi/vcprops.h>

// Initialize VC memory mapping
static void setupVCMemory()
{
    VCPROPS props;
    if (!vcPropsAlloc(&props, 512))
    {
        kputs("Failed to allocate VCProps buffer!\n");
        return;
    }

    vu32* tag = vcPropsAddTag(&props, VCTag_GetVCMem, 0, 2 * sizeof(u32));
    if (!vcPropsExecute(&props))
    {
        vcPropsFree(&props);
        kputs("Mailbox communication failed!\n");
        return;
    }

    u32 memBase = tag[0];
    u32 memSize = tag[1];
    vcPropsFree(&props);

    int firstIdx = L1_INDEX(phys2virt(memBase));
    int lastIdx = firstIdx + (memSize >> 20);
    u32 currentOffset = memBase - BIT(20);

    for (int idx = firstIdx; idx < lastIdx; idx++)
        MASTER_PAGETABLE[idx] = MMU_L1_SECT1MB | (currentOffset += BIT(20)) | MMU_L1_RWNA | MMU_L1_UNCACHED;

    kprintf("VC memory mapped at %p (%u bytes)\n", memBase, memSize);
}

void DevInitPlatform()
{
    setupVCMemory();
    LINK_MODULE(RPiFramebuffer);
}

