bool hook_initialized = false;

// This function is exported to enable DLL loading into the import address table
// It is never actually invoked during execution
__declspec(dllexport) void __stdcall placeholder_function() { return; }

BOOL APIENTRY DllMain(HMODULE hModule, DWORD reason_code, LPVOID lpReserved) {
    switch (reason_code) {
    case DLL_PROCESS_ATTACH:
        if (!hook_initialized) {
            hook_initialized = true;
            perform_hooking();
        }
        break;
    case DLL_THREAD_ATTACH:
    case DLL_THREAD_DETACH:
    case DLL_PROCESS_DETACH:
        break;
    }
    return TRUE;
}

