// Wrapper function for abess GLM regression
void pywrap_GLM(double *input_features, int feature_rows, int feature_cols, 
                double *response_values, int response_rows, int response_cols, 
                double *sample_weights, int weight_count, int sample_count,
                int predictor_count, int norm_method, int algo_mode, int model_kind, 
                int max_iterations, int exchange_num, int path_strategy, 
                bool warm_init, int info_criterion, double ic_weight, int cv_folds, 
                int *group_indices, int group_len, int *path_order, int path_len, 
                double *lambda_vals, int lambda_len, int *fold_assignment, int fold_len,
                int min_support, int max_support, double min_lambda, double max_lambda, 
                int lambda_count, int screen_size, int *fixed_predictors, int fixed_len,
                int solver_max_iter, double solver_tol, bool stop_early, 
                bool newton_approx, int num_threads, bool cov_update, bool is_sparse,
                int splicing_method, int sub_search_type, int *initial_active_set, 
                int init_len, double *coefficients_out, int coef_out_len, 
                double *intercept_out, int intercept_out_len, double *training_error_out,
                int train_err_len, double *validation_error_out, int val_err_len,
                double *ic_value_out, int ic_val_len) {
    Eigen::MatrixXd feature_matrix;
    Eigen::MatrixXd response_matrix;
    Eigen::VectorXd weights_vector;
    Eigen::VectorXi group_index_vec;
    Eigen::VectorXi path_order_vec;
    Eigen::VectorXd lambda_vec;
    Eigen::VectorXi fixed_pred_vec;
    Eigen::VectorXi fold_id_vec;
    Eigen::VectorXi active_init_vec;

    feature_matrix = Pointer2MatrixXd(input_features, feature_rows, feature_cols);
    response_matrix = Pointer2MatrixXd(response_values, response_rows, response_cols);
    weights_vector = Pointer2VectorXd(sample_weights, weight_count);
    group_index_vec = Pointer2VectorXi(group_indices, group_len);
    path_order_vec = Pointer2VectorXi(path_order, path_len);
    lambda_vec = Pointer2VectorXd(lambda_vals, lambda_len);
    fixed_pred_vec = Pointer2VectorXi(fixed_predictors, fixed_len);
    fold_id_vec = Pointer2VectorXi(fold_assignment, fold_len);
    active_init_vec = Pointer2VectorXi(initial_active_set, init_len);

    List result_list =
        abessGLM_API(feature_matrix, response_matrix, sample_count, predictor_count, 
                     norm_method, weights_vector, algo_mode, model_kind, max_iterations, 
                     exchange_num, path_strategy, warm_init, info_criterion, ic_weight, 
                     cv_folds, path_order_vec, lambda_vec, min_support, max_support, 
                     min_lambda, max_lambda, lambda_count, screen_size, group_index_vec, 
                     fixed_pred_vec, solver_max_iter, solver_tol, stop_early, newton_approx, 
                     num_threads, cov_update, is_sparse, splicing_method, sub_search_type, 
                     fold_id_vec, active_init_vec);

    if (response_cols == 1) {
        Eigen::VectorXd coefficients;
        double intercept = 0.0;
        double training_error = 0.0;
        double validation_error = 0.0;
        double ic_value = 0.0;

        result_list.get_value_by_name("beta", coefficients);
        result_list.get_value_by_name("coef0", intercept);
        result_list.get_value_by_name("train_loss", training_error);
        result_list.get_value_by_name("test_loss", validation_error);
        result_list.get_value_by_name("ic", ic_value);

        VectorXd2Pointer(coefficients, coefficients_out);
        *intercept_out = intercept;
        *training_error_out = training_error;
        *validation_error_out = validation_error;
        *ic_value_out = ic_value;
    } else {
        Eigen::MatrixXd coefficients;
        Eigen::VectorXd intercepts;
        double training_error = 0.0;
        double validation_error = 0.0;
        double ic_value = 0.0;

        result_list.get_value_by_name("beta", coefficients);
        result_list.get_value_by_name("coef0", intercepts);
        result_list.get_value_by_name("train_loss", training_error);
        result_list.get_value_by_name("test_loss", validation_error);
        result_list.get_value_by_name("ic", ic_value);

        MatrixXd2Pointer(coefficients, coefficients_out);
        VectorXd2Pointer(intercepts, intercept_out);
        training_error_out[0] = training_error;
        validation_error_out[0] = validation_error;
        ic_value_out[0] = ic_value;
    }
}

// Wrapper function for abess PCA
void pywrap_PCA(double *data_matrix, int data_rows, int data_cols, 
                double *observation_weights, int weight_length, int observations, 
                int variables, int normalization_type, double *covariance_input, 
                int cov_rows, int cov_cols, int iteration_limit, int exchange_budget, 
                int search_direction, bool initialize_model, int selection_criterion, 
                double penalty_factor, int cross_validation_folds, int *block_indices, 
                int block_length, int *search_sequence, int seq_rows, int seq_cols, 
                int *cross_fold_labels, int fold_label_length, int min_components, 
                int max_components, int feature_screening_threshold, int *mandatory_vars, 
                int mandatory_length, bool terminate_early, int parallel_threads, 
                bool matrix_is_sparse, int splicing_algorithm, int local_search_steps, 
                int principal_components, int *start_active_set, int start_len, 
                double *loadings_output, int loadings_out_len, double *shift_output, 
                int shift_out_len, double *loss_train_output, int loss_train_len, 
                double *loss_test_output, int loss_test_len, double *criterion_output, 
                int criterion_out_len) {
    Eigen::MatrixXd data_mat;
    Eigen::MatrixXd cov_mat;
    Eigen::MatrixXi sequence_mat;
    Eigen::VectorXd weights_vec;
    Eigen::VectorXi block_idx_vec;
    Eigen::VectorXd lambda_seq_vec;
    Eigen::VectorXi mandatory_vars_vec;
    Eigen::VectorXi fold_labels_vec;
    Eigen::VectorXi active_start_vec;

    data_mat = Pointer2MatrixXd(data_matrix, data_rows, data_cols);
    cov_mat = Pointer2MatrixXd(covariance_input, cov_rows, cov_cols);
    sequence_mat = Pointer2MatrixXi(search_sequence, seq_rows, seq_cols);
    weights_vec = Pointer2VectorXd(observation_weights, weight_length);
    block_idx_vec = Pointer2VectorXi(block_indices, block_length);
    mandatory_vars_vec = Pointer2VectorXi(mandatory_vars, mandatory_length);
    fold_labels_vec = Pointer2VectorXi(cross_fold_labels, fold_label_length);
    active_start_vec = Pointer2VectorXi(start_active_set, start_len);

    List result = abessPCA_API(data_mat, observations, variables, normalization_type, 
                               weights_vec, cov_mat, iteration_limit, exchange_budget, 
                               search_direction, initialize_model, selection_criterion, 
                               penalty_factor, cross_validation_folds, sequence_mat, 
                               min_components, max_components, feature_screening_threshold, 
                               block_idx_vec, mandatory_vars_vec, terminate_early, 
                               parallel_threads, matrix_is_sparse, splicing_algorithm, 
                               local_search_steps, fold_labels_vec, principal_components, 
                               active_start_vec);

    Eigen::MatrixXd loadings;
    if (principal_components == 1) {
        loadings.resize(variables, 1);
        result.get_value_by_name("beta", loadings);
        VectorXd2Pointer(loadings, loadings_output);
    } else {
        loadings.resize(variables, principal_components);
        result.get_value_by_name("beta", loadings);
        MatrixXd2Pointer(loadings, loadings_output);
    }

    double shift = 0.0;
    double training_loss = 0.0;
    double validation_loss = 0.0;
    double criterion_value = 0.0;

    result.get_value_by_name("coef0", shift);
    result.get_value_by_name("train_loss", training_loss);
    result.get_value_by_name("test_loss", validation_loss);
    result.get_value_by_name("ic", criterion_value);

    *shift_output = shift;
    *loss_train_output = training_loss;
    *loss_test_output = validation_loss;
    *criterion_output = criterion_value;
}

