#if defined(ASMJIT_TEST)

class TestNode : public ZoneListNode<TestNode> {};

UNIT(zone_list) {
  Zone memoryZone(4096);
  ZoneList<TestNode> nodeList;

  TestNode* node1 = memoryZone.newT<TestNode>();
  TestNode* node2 = memoryZone.newT<TestNode>();
  TestNode* node3 = memoryZone.newT<TestNode>();
  TestNode* node4 = memoryZone.newT<TestNode>();

  INFO("Append / Remove Operations");
  // []
  EXPECT(nodeList.empty() == true);

  // [N1]
  nodeList.append(node1);
  EXPECT(nodeList.empty() == false);
  EXPECT(nodeList.first() == node1);
  EXPECT(nodeList.last() == node1);
  EXPECT(node1->prev() == nullptr);
  EXPECT(node1->next() == nullptr);

  // [N1, N2]
  nodeList.append(node2);
  EXPECT(nodeList.first() == node1);
  EXPECT(nodeList.last() == node2);
  EXPECT(node1->prev() == nullptr);
  EXPECT(node1->next() == node2);
  EXPECT(node2->prev() == node1);
  EXPECT(node2->next() == nullptr);

  // [N1, N2, N3]
  nodeList.append(node3);
  EXPECT(nodeList.first() == node1);
  EXPECT(nodeList.last() == node3);
  EXPECT(node1->prev() == nullptr);
  EXPECT(node1->next() == node2);
  EXPECT(node2->prev() == node1);
  EXPECT(node2->next() == node3);
  EXPECT(node3->prev() == node2);
  EXPECT(node3->next() == nullptr);

  // [N2, N3]
  nodeList.unlink(node1);
  EXPECT(nodeList.first() == node2);
  EXPECT(nodeList.last() == node3);
  EXPECT(node1->prev() == nullptr);
  EXPECT(node1->next() == nullptr);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == node3);
  EXPECT(node3->prev() == node2);
  EXPECT(node3->next() == nullptr);

  // [N2]
  nodeList.unlink(node3);
  EXPECT(nodeList.first() == node2);
  EXPECT(nodeList.last() == node2);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == nullptr);
  EXPECT(node3->prev() == nullptr);
  EXPECT(node3->next() == nullptr);

  // []
  nodeList.unlink(node2);
  EXPECT(nodeList.empty() == true);
  EXPECT(nodeList.first() == nullptr);
  EXPECT(nodeList.last() == nullptr);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == nullptr);

  INFO("Prepend / Remove Operations");
  // [N1]
  nodeList.prepend(node1);
  EXPECT(nodeList.empty() == false);
  EXPECT(nodeList.first() == node1);
  EXPECT(nodeList.last() == node1);
  EXPECT(node1->prev() == nullptr);
  EXPECT(node1->next() == nullptr);

  // [N2, N1]
  nodeList.prepend(node2);
  EXPECT(nodeList.first() == node2);
  EXPECT(nodeList.last() == node1);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == node1);
  EXPECT(node1->prev() == node2);
  EXPECT(node1->next() == nullptr);

  INFO("InsertAfter / InsertBefore");
  // [N2, N1, N3]
  nodeList.insertAfter(node1, node3);
  EXPECT(nodeList.first() == node2);
  EXPECT(nodeList.last() == node3);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == node1);
  EXPECT(node1->prev() == node2);
  EXPECT(node1->next() == node3);
  EXPECT(node3->prev() == node1);
  EXPECT(node3->next() == nullptr);

  // [N2, N4, N1, N3]
  nodeList.insertBefore(node1, node4);
  EXPECT(nodeList.first() == node2);
  EXPECT(nodeList.last() == node3);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == node4);
  EXPECT(node4->prev() == node2);
  EXPECT(node4->next() == node1);
  EXPECT(node1->prev() == node4);
  EXPECT(node1->next() == node3);
  EXPECT(node3->prev() == node1);
  EXPECT(node3->next() == nullptr);

  INFO("PopFirst / PopLast");
  // [N4, N1, N3]
  EXPECT(nodeList.popFirst() == node2);
  EXPECT(node2->prev() == nullptr);
  EXPECT(node2->next() == nullptr);
  EXPECT(nodeList.first() == node4);
  EXPECT(nodeList.last() == node3);
  EXPECT(node4->prev() == nullptr);
  EXPECT(node4->next() == node1);
  EXPECT(node1->prev() == node4);
  EXPECT(node1->next() == node3);
  EXPECT(node3->prev() == node1);
  EXPECT(node3->next() == nullptr);

  // [N4, N1]
  EXPECT(nodeList.pop() == node3);
  EXPECT(node3->prev() == nullptr);
  EXPECT(node3->next() == nullptr);
  EXPECT(nodeList.first() == node4);
  EXPECT(nodeList.last() == node1);
  EXPECT(node4->prev() == nullptr);
  EXPECT(node4->next() == node1);
  EXPECT(node1->prev() == node4);
  EXPECT(node1->next() == nullptr);
}
