CRenderTarget::CRenderTarget()
{
    InitializeRenderTarget(0, 0, RTKIND_COLOR);
}

CRenderTarget::CRenderTarget(unsigned int width, unsigned int height, UCHAR type)
{
    InitializeRenderTarget(width, height, type);
}

CRenderTarget::~CRenderTarget()
{
    Cleanup();
}

void CRenderTarget::Cleanup()
{
    if (ReleaseReference())
    {
        LPDIRECT3DSURFACE9 currentTarget;
        RENDERER->GetDevice()->GetRenderTarget(0, &currentTarget);
        if (currentTarget == mSurfaceHandle)
        {
            RENDERER->SetRenderTarget(nullptr);
        }
        SAFE_RELEASE(mTextureResource);
        SAFE_RELEASE(mSurfaceResource);
        SAFE_RELEASE(mDepthStencilResource);
        delete this;
    }
}

void CRenderTarget::Activate()
{
    RENDERER->SetRenderTarget(this);
}

void CRenderTarget::InitializeRenderTarget(unsigned int width, unsigned int height, UCHAR kind)
{
    mKind = kind;
    mTextureResource = nullptr;
    mSurfaceResource = nullptr;
    mDepthStencilResource = nullptr;

    D3DSURFACE_DESC displayDesc = RENDERER->GetDisplayDesc();
    D3DFORMAT supportedFormats[] = {displayDesc.Format, D3DFMT_R32F, D3DFMT_A16B16G16R16F, D3DFMT_A32B32G32R32F};

    LRESULT result = RENDERER->GetDevice()->CreateTexture(
        width != 0u ? width : displayDesc.Width,
        height != 0u ? height : displayDesc.Height,
        1,
        D3DUSAGE_RENDERTARGET,
        supportedFormats[kind],
        D3DPOOL_DEFAULT,
        &mTextureResource,
        nullptr
    );

    if (FAILED(result))
    {
        MessageBoxA(nullptr, "Failed to create render target!", "Renderer error", MB_OK);
        ENGINE->Shutdown();
        return;
    }

    if (kind != RTKIND_DEPTH)
    {
        RENDERER->GetDevice()->CreateDepthStencilSurface(
            width, 
            height, 
            D3DFMT_D24S8, 
            D3DMULTISAMPLE_NONE, 
            0, 
            TRUE,
            &mDepthStencilResource, 
            nullptr
        );
    }

    mTextureResource->GetSurfaceLevel(0, &mSurfaceResource);
}

#include "../../template.hpp"

// Count set bits in binary representation of n using recursion
int countBitsRecursive(int value) {
    if (value == 0) return 0;
    return countBitsRecursive(value >> 1) + (value & 1);
}

// Generate array of bit counts from 0 to n using recursive helper
vi generateBitCountsRecursively(int limit) {
    vi result;
    for (int num = 0; num <= limit; ++num) {
        result.push_back(countBitsRecursive(num));
    }
    return result;
}

// Generate array of bit counts from 0 to n using dynamic programming
vi generateBitCountsDP(int limit) {
    vi dp(limit + 1, 0);
    vi result = {0};
    for (int i = 1; i <= limit; ++i) {
        dp[i] = dp[i >> 1] + (i & 1);
        result.push_back(dp[i]);
    }
    return result;
}

int main() { TimeMeasure _; __x();
    cout << generateBitCountsRecursively(0) << endl; // 0
    cout << generateBitCountsRecursively(2) << endl; // 0,1,1
    cout << generateBitCountsRecursively(5) << endl; // 0,1,1,2,1,2
    cout << endl;
    cout << generateBitCountsDP(0) << endl; // 0
    cout << generateBitCountsDP(2) << endl; // 0,1,1
    cout << generateBitCountsDP(5) << endl; // 0,1,1,2,1,2
}

