namespace baulk {
bool IsDebugMode = false;

void ShowHelp() {
  constexpr std::wstring_view helpText = LR"(baulk-update - Baulk self update utility
Usage: baulk-update [option]
  -h|--help        Display this help message and exit
  -v|--version     Print version information and exit
  -V|--verbose     Enable verbose output for detailed logging
  -F|--force       Activate force mode; e.g., force update of frozen packages
  -A|--user-agent  Specify User-Agent <name> in HTTP requests
  -k|--insecure    Permit insecure SSL connections (skip certificate verification)
  -S|--specified   Download and install a specific baulk version
  --https-proxy    Set proxy URL. Equivalent to 'HTTPS_PROXY' environment variable
Examples:
  baulk-update                  # Update to the latest stable release
  baulk-update -F               # Force update to the latest release
  baulk-update "-S4.0.0-beta.2" # Install a particular version
)";
  bela::terminal::WriteAuto(stderr, helpText);
}

void PrintVersionInfo() {
  bela::FPrintF(stdout, L"baulk-update %s\nRelease:    %s\nCommit:     %s\nBuild Time: %s\n", BAULK_VERSION,
                BAULK_REFNAME, BAULK_REVISION, BAULK_BUILD_TIME);
}

bool Executor::ParseArgv(int argc, wchar_t **argv) {
  bela::ParseArgv pa(argc, argv);
  pa.Add(L"help", bela::no_argument, 'h')
      .Add(L"version", bela::no_argument, 'v')
      .Add(L"verbose", bela::no_argument, 'V')
      .Add(L"force", bela::no_argument, L'F')
      .Add(L"insecure", bela::no_argument, L'k')
      .Add(L"profile", bela::required_argument, 'P')
      .Add(L"user-agent", bela::required_argument, 'A')
      .Add(L"specified", bela::required_argument, 'S')
      .Add(L"https-proxy", bela::required_argument, 1002);

  bela::error_code ec;
  auto parseResult = pa.Execute(
      [&](int optionVal, const wchar_t *originalArg, const wchar_t *) {
        using baulk::net::HttpClient;
        switch (optionVal) {
        case 'h':
          ShowHelp();
          exit(0);
        case 'v':
          PrintVersionInfo();
          exit(0);
        case 'V':
          IsDebugMode = true;
          HttpClient::DefaultClient().SetDebugMode(true);
          break;
        case 'F':
          forceMode = true;
          break;
        case 'k':
          HttpClient::DefaultClient().SetInsecureMode(true);
          break;
        case 'A':
          if (wcslen(originalArg) != 0) {
            HttpClient::DefaultClient().SetUserAgent(originalArg);
          }
          break;
        case 'S':
          specified = originalArg;
          if (!specified.empty()) {
            forceMode = true;
          }
          break;
        case 1002:
          HttpClient::DefaultClient().SetProxyURL(originalArg);
          break;
        default:
          return false;
        }
        return true;
      },
      ec);

  if (!parseResult) {
    bela::FPrintF(stderr, L"baulk-update ParseArgv error: %s\n", ec);
    return false;
  }
  return true;
}
} // namespace baulk

int wmain(int argc, wchar_t **argv) {
  bela::error_code ec;
  if (!baulk::vfs::InitializeFastPathFs(ec)) {
    bela::FPrintF(stderr, L"baulk-exec InitializeFastPathFs error %s\n", ec);
    return 1;
  }

  baulk::Executor executor;
  if (!executor.ParseArgv(argc, argv)) {
    return 1;
  }

  return executor.Execute() ? 0 : 1;
}

