        VkRenderPass generate_main_render_pass(ReaperRoot& /*root*/, VulkanBackend& ctx, const MainPassResources& res)
        {
            const GPUTextureProperties& depthProps = res.depthBuffer.properties;
            const GPUTextureProperties& hdrProps   = res.hdrBuffer.properties;

            const VkAttachmentDescription2 colorAttachment = {
                VK_STRUCTURE_TYPE_ATTACHMENT_DESCRIPTION_2, nullptr,
                VK_FLAGS_NONE,
                PixelFormatToVulkan(hdrProps.format),
                SampleCountToVulkan(hdrProps.sampleCount),
                VK_ATTACHMENT_LOAD_OP_CLEAR,
                VK_ATTACHMENT_STORE_OP_STORE,
                VK_ATTACHMENT_LOAD_OP_DONT_CARE,
                VK_ATTACHMENT_STORE_OP_DONT_CARE,
                VK_IMAGE_LAYOUT_UNDEFINED,
                VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL
            };

            const VkAttachmentDescription2 depthAttachment = {
                VK_STRUCTURE_TYPE_ATTACHMENT_DESCRIPTION_2, nullptr,
                VK_FLAGS_NONE,
                PixelFormatToVulkan(depthProps.format),
                SampleCountToVulkan(depthProps.sampleCount),
                VK_ATTACHMENT_LOAD_OP_CLEAR,
                VK_ATTACHMENT_STORE_OP_DONT_CARE,
                VK_ATTACHMENT_LOAD_OP_DONT_CARE,
                VK_ATTACHMENT_STORE_OP_DONT_CARE,
                VK_IMAGE_LAYOUT_UNDEFINED,
                VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL
            };

            std::array<VkAttachmentDescription2, 2> attachments = {colorAttachment, depthAttachment};

            VkAttachmentReference2 colorRef = {VK_STRUCTURE_TYPE_ATTACHMENT_REFERENCE_2, nullptr, 0,
                                               VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL, VK_IMAGE_ASPECT_COLOR_BIT};
            VkAttachmentReference2 depthRef = {VK_STRUCTURE_TYPE_ATTACHMENT_REFERENCE_2, nullptr, 1,
                                               VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL, VK_IMAGE_ASPECT_DEPTH_BIT};

            VkSubpassDescription2 subpass = {};
            subpass.sType = VK_STRUCTURE_TYPE_SUBPASS_DESCRIPTION_2;
            subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
            subpass.colorAttachmentCount = 1;
            subpass.pColorAttachments = &colorRef;
            subpass.pDepthStencilAttachment = &depthRef;

            const VkSubpassDependency2 depColor = {
                VK_STRUCTURE_TYPE_SUBPASS_DEPENDENCY_2, nullptr,
                VK_SUBPASS_EXTERNAL, 0,
                VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT, VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT,
                VK_ACCESS_SHADER_READ_BIT, VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT,
                VK_DEPENDENCY_BY_REGION_BIT, 0
            };

            const VkSubpassDependency2 depDepth = {
                VK_STRUCTURE_TYPE_SUBPASS_DEPENDENCY_2, nullptr,
                0, VK_SUBPASS_EXTERNAL,
                VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT, VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT,
                VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT, VK_ACCESS_SHADER_READ_BIT,
                VK_DEPENDENCY_BY_REGION_BIT, 0
            };

            std::array<VkSubpassDependency2, 2> deps = {depColor, depDepth};

            VkRenderPassCreateInfo2 passInfo = {};
            passInfo.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO_2;
            passInfo.pNext = nullptr;
            passInfo.attachmentCount = static_cast<uint32_t>(attachments.size());
            passInfo.pAttachments = attachments.data();
            passInfo.subpassCount = 1;
            passInfo.pSubpasses = &subpass;
            passInfo.dependencyCount = static_cast<uint32_t>(deps.size());
            passInfo.pDependencies = deps.data();
            passInfo.correlatedViewMaskCount = 0;
            passInfo.pCorrelatedViewMasks = nullptr;

            VkRenderPass renderPass = VK_NULL_HANDLE;
            Assert(vkCreateRenderPass2(ctx.device, &passInfo, nullptr, &renderPass) == VK_SUCCESS);
            return renderPass;
        }

        VkFramebuffer generate_main_framebuffer(VulkanBackend& ctx, MainPassResources& res)
        {
            std::array<VkFormat, 2> formats;
            std::array<VkFramebufferAttachmentImageInfo, 2> attachmentInfos = {
                get_attachment_info_from_image_properties(res.hdrBuffer.properties, &formats[0]),
                get_attachment_info_from_image_properties(res.depthBuffer.properties, &formats[1])
            };

            VkFramebufferAttachmentsCreateInfo attachInfo = {
                VK_STRUCTURE_TYPE_FRAMEBUFFER_ATTACHMENTS_CREATE_INFO, nullptr,
                static_cast<u32>(attachmentInfos.size()), attachmentInfos.data()
            };

            VkFramebufferCreateInfo fbInfo = {
                VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO,
                &attachInfo,
                VK_FRAMEBUFFER_CREATE_IMAGELESS_BIT,
                res.mainRenderPass,
                static_cast<u32>(attachmentInfos.size()),
                nullptr,
                attachmentInfos[0].width,
                attachmentInfos[0].height,
                1
            };

            VkFramebuffer framebuffer = VK_NULL_HANDLE;
            Assert(vkCreateFramebuffer(ctx.device, &fbInfo, nullptr, &framebuffer) == VK_SUCCESS);
            return framebuffer;
        }

        void allocate_main_pass_resources(ReaperRoot& root, VulkanBackend& ctx, MainPassResources& res)
        {
            res.hdrBuffer = create_image(root, ctx.device, "Main HDR Target", res.hdrBuffer.properties, ctx.vma_instance);
            res.hdrBufferView = create_default_image_view(root, ctx.device, res.hdrBuffer);
            res.depthBuffer = create_image(root, ctx.device, "Main Depth Target", res.depthBuffer.properties, ctx.vma_instance);
            res.depthBufferView = create_depth_image_view(root, ctx.device, res.depthBuffer);
            res.main_framebuffer = generate_main_framebuffer(ctx, res);
        }

        void release_main_pass_resources(VulkanBackend& ctx, MainPassResources& res)
        {
            vkDestroyFramebuffer(ctx.device, res.main_framebuffer, nullptr);
            vkDestroyImageView(ctx.device, res.hdrBufferView, nullptr);
            vmaDestroyImage(ctx.vma_instance, res.hdrBuffer.handle, res.hdrBuffer.allocation);
            vkDestroyImageView(ctx.device, res.depthBufferView, nullptr);
            vmaDestroyImage(ctx.vma_instance, res.depthBuffer.handle, res.depthBuffer.allocation);
            res.hdrBuffer = {};
            res.hdrBufferView = VK_NULL_HANDLE;
            res.depthBuffer = {};
            res.depthBufferView = VK_NULL_HANDLE;
        }

        void adjust_resource_dimensions(MainPassResources& res, glm::uvec2 size)
        {
            GPUTextureProperties hdrProps =
                DefaultGPUTextureProperties(size.x, size.y, PixelFormat::B10G11R11_UFLOAT_PACK32);
            hdrProps.usageFlags = GPUTextureUsage::ColorAttachment | GPUTextureUsage::Sampled;

            GPUTextureProperties depthProps = DefaultGPUTextureProperties(size.x, size.y, PixelFormat::D16_UNORM);
            depthProps.usageFlags = GPUTextureUsage::DepthStencilAttachment;

            res.hdrBuffer.properties = hdrProps;
            res.depthBuffer.properties = depthProps;
        }

        VkDescriptorSet allocate_main_pass_set(ReaperRoot& root, VulkanBackend& ctx, VkDescriptorSetLayout layout)
        {
            VkDescriptorSetAllocateInfo allocInfo = {VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO, nullptr,
                                                     ctx.global_descriptor_pool, 1, &layout};
            VkDescriptorSet set = VK_NULL_HANDLE;
            Assert(vkAllocateDescriptorSets(ctx.device, &allocInfo, &set) == VK_SUCCESS);
            log_debug(root, "vulkan: created descriptor set with handle: {}", static_cast<void*>(set));
            return set;
        }

        VkDescriptorSet allocate_material_set(ReaperRoot& root, VulkanBackend& ctx, VkDescriptorSetLayout layout)
        {
            VkDescriptorSetAllocateInfo allocInfo = {VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO, nullptr,
                                                     ctx.global_descriptor_pool, 1, &layout};
            VkDescriptorSet set = VK_NULL_HANDLE;
            Assert(vkAllocateDescriptorSets(ctx.device, &allocInfo, &set) == VK_SUCCESS);
            log_debug(root, "vulkan: created material descriptor set with handle: {}", static_cast<void*>(set));
            return set;
        }

        VkSampler generate_shadow_sampler(VulkanBackend& ctx)
        {
            VkSamplerCreateInfo info = {};
            info.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
            info.magFilter = VK_FILTER_LINEAR;
            info.minFilter = VK_FILTER_LINEAR;
            info.addressModeU = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_BORDER;
            info.addressModeV = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_BORDER;
            info.addressModeW = VK_SAMPLER_ADDRESS_MODE_CLAMP_TO_BORDER;
            info.anisotropyEnable = VK_FALSE;
            info.maxAnisotropy = 16;
            info.borderColor = UseReverseDepth ? VK_BORDER_COLOR_INT_OPAQUE_BLACK : VK_BORDER_COLOR_INT_OPAQUE_WHITE;
            info.unnormalizedCoordinates = VK_FALSE;
            info.compareEnable = VK_TRUE;
            info.compareOp = UseReverseDepth ? VK_COMPARE_OP_GREATER : VK_COMPARE_OP_LESS;
            info.mipmapMode = VK_SAMPLER_MIPMAP_MODE_NEAREST;
            info.mipLodBias = 0.f;
            info.minLod = 0.f;
            info.maxLod = FLT_MAX;

            VkSampler sampler;
            Assert(vkCreateSampler(ctx.device, &info, nullptr, &sampler) == VK_SUCCESS);
            return sampler;
        }

        VkSampler generate_diffuse_sampler(VulkanBackend& ctx)
        {
            VkSamplerCreateInfo info = {};
            info.sType = VK_STRUCTURE_TYPE_SAMPLER_CREATE_INFO;
            info.magFilter = VK_FILTER_LINEAR;
            info.minFilter = VK_FILTER_LINEAR;
            info.addressModeU = VK_SAMPLER_ADDRESS_MODE_REPEAT;
            info.addressModeV = VK_SAMPLER_ADDRESS_MODE_REPEAT;
            info.addressModeW = VK_SAMPLER_ADDRESS_MODE_REPEAT;
            info.anisotropyEnable = VK_TRUE;
            info.anisotropyEnable = VK_FALSE; // FIXME enable at higher level
            info.maxAnisotropy = 8;
            info.unnormalizedCoordinates = VK_FALSE;
            info.mipmapMode = VK_SAMPLER_MIPMAP_MODE_LINEAR;
            info.mipLodBias = 0.f;
            info.minLod = 0.f;
            info.maxLod = FLT_MAX;

            VkSampler sampler = VK_NULL_HANDLE;
            Assert(vkCreateSampler(ctx.device, &info, nullptr, &sampler) == VK_SUCCESS);
            return sampler;
        }
