    MainPassResources create_main_pass_resources(ReaperRoot& root, VulkanBackend& ctx, glm::uvec2 extent)
    {
        MainPassResources res = {};
        res.drawPassConstantBuffer = create_buffer(
            root, ctx.device, "Draw Pass Constant buffer",
            DefaultGPUBufferProperties(1, sizeof(DrawPassParams), GPUBufferUsage::UniformBuffer), ctx.vma_instance);
        res.drawInstanceConstantBuffer = create_buffer(
            root, ctx.device, "Draw Instance Constant buffer",
            DefaultGPUBufferProperties(MaxBatchInstanceCount, sizeof(DrawInstanceParams), GPUBufferUsage::StorageBuffer),
            ctx.vma_instance);

        adjust_resource_dimensions(res, extent);
        res.mainRenderPass = generate_main_render_pass(root, ctx, res);
        allocate_main_pass_resources(root, ctx, res);
        res.mainPipe = build_main_pipeline(root, ctx, res.mainRenderPass);
        res.descriptor_set = allocate_main_pass_set(root, ctx, res.mainPipe.descSetLayout);
        res.material_descriptor_set = allocate_material_set(root, ctx, res.mainPipe.descSetLayout2);
        res.shadowMapSampler = generate_shadow_sampler(ctx);
        res.diffuseMapSampler = generate_diffuse_sampler(ctx);
        return res;
    }

    void destroy_main_pass_resources(VulkanBackend& ctx, MainPassResources& res)
    {
        vkDestroySampler(ctx.device, res.diffuseMapSampler, nullptr);
        vkDestroySampler(ctx.device, res.shadowMapSampler, nullptr);
        vkDestroyPipeline(ctx.device, res.mainPipe.pipeline, nullptr);
        vkDestroyPipelineLayout(ctx.device, res.mainPipe.pipelineLayout, nullptr);
        vkDestroyDescriptorSetLayout(ctx.device, res.mainPipe.descSetLayout, nullptr);
        vkDestroyDescriptorSetLayout(ctx.device, res.mainPipe.descSetLayout2, nullptr);
        vkDestroyRenderPass(ctx.device, res.mainRenderPass, nullptr);
        release_main_pass_resources(ctx, res);
        vmaDestroyBuffer(ctx.vma_instance, res.drawPassConstantBuffer.buffer, res.drawPassConstantBuffer.allocation);
        vmaDestroyBuffer(ctx.vma_instance, res.drawInstanceConstantBuffer.buffer, res.drawInstanceConstantBuffer.allocation);
    }

    void resize_main_pass_resources(ReaperRoot& root, VulkanBackend& ctx, MainPassResources& res, glm::uvec2 extent)
    {
        release_main_pass_resources(ctx, res);
        adjust_resource_dimensions(res, extent);
        allocate_main_pass_resources(root, ctx, res);
    }

