    void record_main_pass_commands(CommandBuffer& cmdBuffer, VulkanBackend& ctx, const PreparedData& prepared,
                                   const MainPassResources& passRes, const CullResources& cullRes,
                                   const MeshCache& meshCache, VkExtent2D backbufferExtent)
    {
        REAPER_PROFILE_SCOPE_GPU(cmdBuffer.mlog, "Main Pass", MP_DARKGOLDENROD);
        const float                 depthClearValue = UseReverseDepth ? 0.f : 1.f;
        const glm::fvec4            clearColor = {0.1f, 0.1f, 0.1f, 0.0f};
        std::array<VkClearValue, 2> clearValues = {VkClearColor(clearColor), VkClearDepthStencil(depthClearValue, 0)};
        const VkRect2D              passRect = default_vk_rect(backbufferExtent);

        std::array<VkImageView, 2> framebufferViews = {passRes.hdrBufferView, passRes.depthBufferView};
        VkRenderPassAttachmentBeginInfo attachmentBegin = {
            VK_STRUCTURE_TYPE_RENDER_PASS_ATTACHMENT_BEGIN_INFO, nullptr,
            static_cast<u32>(framebufferViews.size()), framebufferViews.data()
        };

        VkRenderPassBeginInfo renderPassBegin = {
            VK_STRUCTURE_TYPE_RENDER_PASS_BEGIN_INFO,
            &attachmentBegin,
            passRes.mainRenderPass,
            passRes.main_framebuffer,
            passRect,
            static_cast<u32>(clearValues.size()),
            clearValues.data()
        };

        vkCmdBeginRenderPass(cmdBuffer.handle, &renderPassBegin, VK_SUBPASS_CONTENTS_INLINE);
        vkCmdBindPipeline(cmdBuffer.handle, VK_PIPELINE_BIND_POINT_GRAPHICS, passRes.mainPipe.pipeline);

        const VkViewport viewport = default_vk_viewport(passRect);
        vkCmdSetViewport(cmdBuffer.handle, 0, 1, &viewport);
        vkCmdSetScissor(cmdBuffer.handle, 0, 1, &passRect);

        std::vector<VkBuffer> vertexBuffers = {
            meshCache.vertexBufferPosition.buffer,
            meshCache.vertexBufferNormal.buffer,
            meshCache.vertexBufferUV.buffer,
        };
        std::vector<VkDeviceSize> vertexOffsets = {0, 0, 0};

        Assert(vertexBuffers.size() == vertexOffsets.size());

        vkCmdBindIndexBuffer(cmdBuffer.handle, cullRes.dynamicIndexBuffer.buffer, 0, get_vk_culling_index_type());
        vkCmdBindVertexBuffers(cmdBuffer.handle, 0, static_cast<u32>(vertexBuffers.size()), vertexBuffers.data(),
                               vertexOffsets.data());

        std::array<VkDescriptorSet, 2> descriptorSets = {
            passRes.descriptor_set,
            passRes.material_descriptor_set
        };
        vkCmdBindDescriptorSets(cmdBuffer.handle, VK_PIPELINE_BIND_POINT_GRAPHICS, passRes.mainPipe.pipelineLayout,
                                0, static_cast<u32>(descriptorSets.size()), descriptorSets.data(), 0, nullptr);

        const u32 pass_index = prepared.draw_culling_pass_index;
        const u32 draw_offset = pass_index * MaxIndirectDrawCount * sizeof(VkDrawIndexedIndirectCommand);
        const u32 max_draw_count = MaxIndirectDrawCount;

        if (ctx.options.use_compacted_draw)
        {
            const u32 count_offset = pass_index * 1 * sizeof(u32);
            vkCmdDrawIndexedIndirectCount(cmdBuffer.handle, cullRes.compactIndirectDrawBuffer.buffer,
                                          draw_offset, cullRes.compactIndirectDrawCountBuffer.buffer,
                                          count_offset, max_draw_count,
                                          cullRes.compactIndirectDrawBuffer.descriptor.elementSize);
        }
        else
        {
            const u32 count_offset = pass_index * IndirectDrawCountCount * sizeof(u32);
            vkCmdDrawIndexedIndirectCount(cmdBuffer.handle, cullRes.indirectDrawBuffer.buffer, draw_offset,
                                          cullRes.indirectDrawCountBuffer.buffer, count_offset,
                                          max_draw_count, cullRes.indirectDrawBuffer.descriptor.elementSize);
        }

        vkCmdEndRenderPass(cmdBuffer.handle);
    }
