GaitKeyboardPublisher::GaitKeyboardPublisher(ros::NodeHandle nodeHandle, const std::string& configFile, const std::string& robotPrefix,
                                             bool debugMode) {
  ROS_INFO_STREAM(robotPrefix + "_mpc_mode_schedule initialization in progress ...");
  loadData::loadStdVector(configFile, "gait_names", gaitNames_, debugMode);
  modeSchedulePub_ = nodeHandle.advertise<ocs2_msgs::mode_schedule>(robotPrefix + "_mpc_mode_schedule", 1, true);
  gaitRegistry_.clear();
  for (const auto& name : gaitNames_) {
    gaitRegistry_.emplace(name, loadModeSequenceTemplate(configFile, name, debugMode));
  }
  ROS_INFO_STREAM(robotPrefix + "_mpc_mode_schedule command handler initialized.");
}

void GaitKeyboardPublisher::getKeyboardCommand() {
  const std::string prompt = "Type desired gait; to view available options, enter \"list\"";
  std::cout << prompt << ": ";

  auto isShutdown = []() { return !ros::ok() || !ros::master::check(); };
  const auto inputTokens = stringToWords(getCommandLineString(isShutdown));
  if (inputTokens.empty()) {
    return;
  }
  if (inputTokens.size() != 1) {
    std::cout << "ERROR: Input must be exactly one token." << std::endl;
    return;
  }

  // Convert to lowercase
  auto selectedGait = inputTokens[0];
  std::transform(selectedGait.begin(), selectedGait.end(), selectedGait.begin(),
                 [](unsigned char c) { return std::tolower(c); });

  if (selectedGait == "list") {
    displayAvailableGaits(gaitNames_);
    return;
  }

  try {
    auto&& templateRef = gaitRegistry_.at(selectedGait);
    modeSchedulePub_.publish(createModeSequenceTemplateMsg(templateRef));
  } catch (const std::out_of_range&) {
    std::cout << "Gait \"" << selectedGait << "\" does not exist.\n";
    displayAvailableGaits(gaitNames_);
  }
}

void GaitKeyboardPublisher::displayAvailableGaits(const std::vector<std::string>& gaitList) const {
  std::cout << "Available gaits:\n";
  size_t index = 0;
  for (const auto& item : gaitList) {
    std::cout << "[" << index++ << "] " << item << "\n";
