Code ObtainLocalAddress(const std::string &dev_name, std::string *ip_address)
{/*{{{*/
    if (ip_address == nullptr) return kInvalidParam;
    struct in_addr ipv4_addr;
    Code status = ObtainLocalAddress(dev_name, &ipv4_addr);
    if (status != kOk) return status;
    char buffer[kMaxLenOfIp];
    inet_ntop(AF_INET, (void*)&ipv4_addr, buffer, sizeof(buffer));
    ip_address->assign(buffer);

    return kOk;
}/*}}}*/

Code ObtainLocalAddress(const std::string &dev_name, struct in_addr *ipv4_addr)
{/*{{{*/
    if (ipv4_addr == nullptr) return kInvalidParam;
    struct ifreq request;
    strncpy(request.ifr_name, dev_name.c_str(), IFNAMSIZ);
    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) return kSocketError;

    int result = ioctl(socket_fd, SIOCGIFADDR, (char*)&request);
    if (result < 0)
    {
        close(socket_fd);
        return kIOCtlError;
    }

    *ipv4_addr = ((struct sockaddr_in*)(&request.ifr_addr))->sin_addr;
    close(socket_fd);

    return kOk;
}/*}}}*/

Code RetrieveNetworkInterfaces(std::vector<std::string> *interface_list)
{/*{{{*/
    if (interface_list == nullptr) return kInvalidParam;
    struct ifaddrs *if_list = nullptr;
    int status = getifaddrs(&if_list);
    if (status == -1)
        return kGetIfsError;

    struct ifaddrs *current = if_list;
    while (current != nullptr)
    {
        if (current->ifa_addr->sa_family == AF_INET)
        {
            interface_list->push_back(current->ifa_name);
        }
        current = current->ifa_next;
    }
    freeifaddrs(if_list);
    return kOk;
}/*}}}*/

Code RetrieveNetworkInterfaces(std::map<std::string, struct in_addr> *interface_ipv4_map)
{/*{{{*/
    if (interface_ipv4_map == nullptr) return kInvalidParam;
    struct ifaddrs *if_list = nullptr;
    int status = getifaddrs(&if_list);
    if (status == -1)
        return kGetIfsError;

    struct ifaddrs *current = if_list;
    while (current != nullptr)
    {
        if (current->ifa_addr->sa_family == AF_INET)
        {
            interface_ipv4_map->insert(std::make_pair<std::string, struct in_addr>
                        (std::string(current->ifa_name),
                        (struct in_addr)(((struct sockaddr_in*)(current->ifa_addr))->sin_addr)));
        }
        current = current->ifa_next;
    }
    freeifaddrs(if_list);
    return kOk;
}/*}}}*/

Code RetrieveNetworkInterfaces(std::map<std::string, std::string> *interface_ip_map)
{/*{{{*/
    if (interface_ip_map == nullptr) return kInvalidParam;
    struct ifaddrs *if_list = nullptr;
    int status = getifaddrs(&if_list);
    if (status == -1)
        return kGetIfsError;

    char buffer[16];
    struct ifaddrs *current = if_list;
    while (current != nullptr)
    {
        if (current->ifa_addr->sa_family == AF_INET)
        {
            inet_ntop(AF_INET, &((struct sockaddr_in*)(current->ifa_addr))->sin_addr, 
                    buffer, sizeof(buffer));
            interface_ip_map->insert(std::make_pair<std::string, std::string>(current->ifa_name, buffer));
        }
        current = current->ifa_next;
    }
    freeifaddrs(if_list);
    return kOk;
}/*}}}*/

Code ObtainRemoteAddress(int socket_fd, std::string *remote_ip)
{/*{{{*/
    if (remote_ip == nullptr) return kInvalidParam;
    struct sockaddr_in addr_info;
    socklen_t addr_len = sizeof(addr_info);
    int status = getpeername(socket_fd, (struct sockaddr*)&addr_info, &addr_len);
    if (status == -1) return kSocketError;

    char buffer[kMaxLenOfIp];
    inet_ntop(AF_INET, (void*)&(addr_info.sin_addr), buffer, sizeof(buffer));
    remote_ip->assign(buffer);
    return kOk;
}/*}}}*/

Code ResolveHostnameToIp(const std::string &hostname, std::string *ip_address)
{/*{{{*/
    if (hostname.empty() || ip_address == nullptr) return kInvalidParam;
    ip_address->clear();

    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *result = nullptr;
    int status = getaddrinfo(hostname.c_str(), nullptr, &hints, &result);
    if (status != 0) return kGetHostByNameFailed;

    struct addrinfo *current = result;
    for (; current != nullptr; current = current->ai_next)
    {
        char buffer[20] = {0};
        const char *pos = inet_ntop(AF_INET, &((sockaddr_in*)(current->ai_addr))->sin_addr,
            buffer, sizeof(buffer));
        if (pos == nullptr) return kNetAddrConvertFailed;
        ip_address->append(buffer);
        break;
    }
    freeaddrinfo(result);
    result = nullptr;
    return kOk;
}/*}}}*/

Code ResolveHostnameToIp(const std::string &hostname, uint32_t *ip_address)
{/*{{{*/
    if (hostname.empty() || ip_address == nullptr) return kInvalidParam;

    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *result = nullptr;
    int status = getaddrinfo(hostname.c_str(), nullptr, &hints, &result);
    if (status != 0) return kGetHostByNameFailed;

    struct addrinfo *current = result;
    for (; current != nullptr; current = current->ai_next)
    {
        *ip_address = (((sockaddr_in*)(current->ai_addr))->sin_addr).s_addr;
        break;
    }
    freeaddrinfo(result);
    result = nullptr;
    return kOk;
}/*}}}*/

Code ResolveHostnameToIp(const std::string &hostname, std::deque<std::string> *ip_list)
{/*{{{*/
    if (hostname.empty() || ip_list == nullptr) return kInvalidParam;
    ip_list->clear();

    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *result = nullptr;
    int status = getaddrinfo(hostname.c_str(), nullptr, &hints, &result);
    if (status != 0) return kGetHostByNameFailed;

    struct addrinfo *current = result;
    for (; current != nullptr; current = current->ai_next)
    {
        char buffer[20] = {0};
        const char *pos = inet_ntop(AF_INET, &((sockaddr_in*)(current->ai_addr))->sin_addr,
            buffer, sizeof(buffer));
        if (pos == nullptr) return kNetAddrConvertFailed;
        ip_list->push_back(buffer);
    }
    freeaddrinfo(result);
    result = nullptr;
    return kOk;
}/*}}}*/

Code ResolveHostnameToIp(const std::string &hostname, std::deque<uint32_t> *ip_list)
{/*{{{*/
    if (hostname.empty() || ip_list == nullptr) return kInvalidParam;

    struct addrinfo hints;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *result = nullptr;
    int status = getaddrinfo(hostname.c_str(), nullptr, &hints, &result);
    if (status != 0) return kGetHostByNameFailed;

    struct addrinfo *current = result;
    for (; current != nullptr; current = current->ai_next)
    {
        ip_list->push_back((((sockaddr_in*)(current->ai_addr))->sin_addr).s_addr);
    }
    freeaddrinfo(result);
    result = nullptr;
    return kOk;
}/*}}}*/

Code ConvertStringToUintIp(const std::string &str_ip, uint32_t *uint_ip)
{/*{{{*/
    if (uint_ip == nullptr) return kInvalidParam;
    struct in_addr temp_addr;
    int result = inet_pton(AF_INET, str_ip.c_str(), &temp_addr);
    if (result == 1)
    {
        *uint_ip = (uint32_t)temp_addr.s_addr;
        return kOk;
    }
    return kInvalidIp;
}/*}}}*/

Code ConvertUintIpToString(uint32_t uint_ip, std::string *str_ip)
{/*{{{*/
    if (str_ip == nullptr) return kInvalidParam;
    struct in_addr temp_addr;
    temp_addr.s_addr = uint_ip;
    char buffer[kSmallBufLen] = {0};
    const char *p = inet_ntop(AF_INET, &temp_addr, buffer, sizeof(buffer));
    if (p == nullptr) return kInvalidIp;
    str_ip->assign(buffer);
    return kOk;
}/*}}}*/
}

