#include "Direct3D12.h"
#include "vertexbuffer.h"
#include <kinc/graphics5/vertexbuffer.h>
#include <kinc/backend/SystemMicrosoft.h>
#include <kinc/graphics4/graphics.h>

kinc_g5_vertex_buffer_t *_active_vertex_buffer = nullptr;

void kinc_g5_vertex_buffer_init(kinc_g5_vertex_buffer_t *vb, int vertexCount, kinc_g5_vertex_structure_t *layout, bool useGpuMemory, int instanceStepRate) {
    vb->impl.myVertexCount = vertexCount;
    vb->impl.lastStartIndex = -1;
    vb->impl.lastVertexCount = -1;

    static_assert(sizeof(D3D12VertexBufferView) == sizeof(D3D12_VERTEX_BUFFER_VIEW), "Mismatch in D3D12 vertex buffer view size");

    vb->impl.myStride = 0;
    for (int index = 0; index < layout->size; ++index) {
        switch (layout->elements[index].data) {
        case KINC_G4_VERTEX_DATA_FLOAT1:
            vb->impl.myStride += 1 * 4;
            break;
        case KINC_G4_VERTEX_DATA_FLOAT2:
            vb->impl.myStride += 2 * 4;
            break;
        case KINC_G4_VERTEX_DATA_FLOAT3:
            vb->impl.myStride += 3 * 4;
            break;
        case KINC_G4_VERTEX_DATA_FLOAT4:
            vb->impl.myStride += 4 * 4;
            break;
        case KINC_G4_VERTEX_DATA_COLOR:
            vb->impl.myStride += 1 * 4;
            break;
        case KINC_G4_VERTEX_DATA_SHORT2_NORM:
            vb->impl.myStride += 2 * 2;
            break;
        case KINC_G4_VERTEX_DATA_SHORT4_NORM:
            vb->impl.myStride += 4 * 2;
            break;
        }
    }

    int uploadSize = vb->impl.myStride * vb->impl.myVertexCount;
    CD3DX12_HEAP_PROPERTIES heapProps(D3D12_HEAP_TYPE_UPLOAD);
    CD3DX12_RESOURCE_DESC resourceDesc = CD3DX12_RESOURCE_DESC::Buffer(uploadSize);

    device->CreateCommittedResource(&heapProps, D3D12_HEAP_FLAG_NONE, &resourceDesc, D3D12_RESOURCE_STATE_GENERIC_READ, nullptr,
                                    IID_GRAPHICS_PPV_ARGS(&vb->impl.uploadBuffer));

    vb->impl.view.BufferLocation = vb->impl.uploadBuffer->GetGPUVirtualAddress();
    vb->impl.view.SizeInBytes = uploadSize;
    vb->impl.view.StrideInBytes = vb->impl.myStride;
}

void kinc_g5_vertex_buffer_destroy(kinc_g5_vertex_buffer_t *vb) {
    // vb->Release();
    // delete[] vertices;
}

float *kinc_g5_vertex_buffer_lock_all(kinc_g5_vertex_buffer_t *vb) {
    return kinc_g5_vertex_buffer_lock(vb, 0, kinc_g5_vertex_buffer_count(vb));
}

float *kinc_g5_vertex_buffer_lock(kinc_g5_vertex_buffer_t *vb, int startIndex, int count) {
    vb->impl.lastStartIndex = startIndex;
    vb->impl.lastVertexCount = count;

    void *mappedPtr;
    D3D12_RANGE range;
    range.Begin = startIndex * vb->impl.myStride;
    range.End = range.Begin + count * vb->impl.myStride;

    vb->impl.uploadBuffer->Map(0, &range, &mappedPtr);
    uint8_t *bytePtr = (uint8_t *)mappedPtr;
    bytePtr += startIndex * vb->impl.myStride;
    return (float *)bytePtr;
}

void kinc_g5_vertex_buffer_unlock_all(kinc_g5_vertex_buffer_t *vb) {
    D3D12_RANGE range;
    range.Begin = vb->impl.lastStartIndex * vb->impl.myStride;
    range.End = range.Begin + vb->impl.lastVertexCount * vb->impl.myStride;
    vb->impl.uploadBuffer->Unmap(0, &range);
}

void kinc_g5_vertex_buffer_unlock(kinc_g5_vertex_buffer_t *vb, int count) {
    D3D12_RANGE range;
    range.Begin = vb->impl.lastStartIndex * vb->impl.myStride;
    range.End = range.Begin + count * vb->impl.myStride;
    vb->impl.uploadBuffer->Unmap(0, &range);
}

int kinc_g5_internal_vertex_buffer_set(kinc_g5_vertex_buffer_t *vb, int offset) {
    _active_vertex_buffer = vb;
    return 0;
}

int kinc_g5_vertex_buffer_count(kinc_g5_vertex_buffer_t *vb) {
    return vb->impl.myVertexCount;
}

int kinc_g5_vertex_buffer_stride(kinc_g5_vertex_buffer_t *vb) {
    return vb->impl.myStride;
}

#include "ActorConstraint.hpp"
#include "Actor.hpp"

using namespace nima;

// Constructor initializes constraint with parent actor and component type
ActorConstraint::ActorConstraint(Actor* owner, ComponentType kind) :
    ActorComponent(owner, kind),
    m_IsActive(false),
    m_Weight(1.0f)
{
}

bool ActorConstraint::isActive() const
{
    return m_IsActive;
}

float ActorConstraint::weight() const
{
    return m_Weight;
}

void ActorConstraint::weight(float newValue)
{
    if(m_Weight == newValue)
    {
        return;
    }
    m_Weight = newValue;
    m_Owner->markTransformDirty();
}

void ActorConstraint::onTransformChanged(unsigned char flag)
{
    m_Owner->markTransformDirty();
}

void ActorConstraint::resolveIndices(ActorComponent** table)
{
    Base::resolveIndices(table);
    if(m_Owner != nullptr)
    {
        // Nodes are exported in hierarchical order, ensuring constraints are added sequentially during index resolution.
        m_Owner->addConstraint(this);
    }
}

void ActorConstraint::clone(ActorConstraint* source, Actor* targetActor)
{
    Base::clone(source, targetActor);
    m_IsActive = source->m_IsActive;
    m_Weight = source->m_Weight;
}

ActorConstraint* ActorConstraint::load(Actor* owner, BlockReader* stream, ActorConstraint* instance)
{
    Base::load(owner, stream, instance);
    instance->m_Weight = stream->readFloat();
    instance->m_IsActive = stream->readByte() == 1;
    return instance;
}

#include "\tc\CLib\addons\CLib\ModuleMacros.hpp"
// This file serves as the CLib equivalent of the standard CfgFunctions system, but with enhanced capabilities
// in terms of security and debuggability — for instance, complete stack traces are supported.
// Each "module" corresponds to a directory within this mod, and every FNC(someName) maps to
// a file named fn_someName.sqf located inside that module's folder.

class CfgCLibModules {
	// This is the identifier for this mod, used by the CLib framework (case-insensitive)
    class CLibRef {
		// Define the absolute path to the root directory containing all listed modules
		// This path is derived from the PBO prefix configured for the mod
		path = "rvn\clibref\addons\clibref";

		// List all external CLib-based dependencies required by this mod
		// Dependencies follow the format "ModName/ModuleName", referring to modules in other mods
		// These are appended to each module’s own dependency list
		// Unmet dependencies trigger an error logged in the RPT file
		// Matching is performed case-insensitively
		dependency[] = {};

		// Module names themselves are also case-insensitive
		MODULE(PFH) {
			// The dependency array lists components within the CLib framework this specific module relies on
			dependency[] = {"CLib/PerFrame", "Clib/Events"};

			// Declares a new function in this module, expected to reside in fn_clientInit.sqf
			// This is a special entry-point function (see below)
			FNC(clientInit);
		};

		MODULE(flagInteraction) {
			dependency[] = {"CLib/Interaction", "CLib/Events"};
			FNC(clientInit);
			FNC(captureFlag);
		};
    };	
};

///////////////////////////// ENTRY POINTS /////////////////////////////
// Entry points are functions invoked automatically at predefined stages of initialization.
// They act as starting points for code execution within the mod — similar to init.sqf in vanilla SQF,
// but more powerful and structured. CLib defines its own set of entry points, which execute as soon as
// the framework and required module dependencies are ready.

// Supported entry points:
// - FNC(clientInit): Invoked on all regular clients (excludes server and headless clients) [condition: hasInterface]
// - FNC(serverInit): Invoked only on the dedicated server (excludes clients and HCs) [condition: isServer]
// - FNC(hcInit): Invoked on each headless client (excludes server and regular clients) [condition: !isServer && !hasInterface]
// - FNC(init): Invoked universally across all machines (server, clients, HCs) [no condition]
// Note: The global init entry point executes before the specialized ones.

// For further information:
// - Entry point handling: https://github.com/TaktiCool/CLib/blob/master/addons/CLib/Core/Autoload/fn_callModules.sqf
// - Module loading & parsing logic: 
//   https://github.com/TaktiCool/CLib/blob/master/addons/CLib/Core/Compile/fn_readAllModules.sqf
//   and related files under: https://github.com/TaktiCool/CLib/blob/master/addons/CLib/Core/Compile/
//   combined with: https://github.com/TaktiCool/CLib/blob/master/addons/CLib/Core/Autoload

