      TargetEnv(BuildExeLibDir::fmt, env::get_project_build_dir() / "fmt"));

  FmtConfig fmt_configuration;
  registry.Build(arg_gcc_compiler.state, build_fmt_cb, fmt_library, fmt_configuration);

  ExecutableTarget_gcc application("hello_world", gcc_toolchain, "");
  registry.Build(arg_gcc_compiler.state, app_build_handler, application, fmt_library);
