// Returns reference to the smaller of two integers
inline int& minimum(int& val1, int& val2) {
    return val1 < val2 ? val1 : val2;
}

// Computes the value at position (i, j) in an n x n spiral matrix
int computeValue(int row, int col, int size) {
    int layer = minimum(minimum(row, size + 1 - row), minimum(col, size + 1 - col));

    if (row == layer)
        return col - row + 1 + 4 * (size - layer + 1) * (layer - 1);
    if (row == size + 1 - layer)
        return 3 * size - col - 5 * layer + 4 * (size - layer + 1) * (layer - 1) + 4;
    if (col == layer)
        return col - row + 4 * size - 8 * layer + 4 * (size - layer + 1) * (layer - 1) + 5;
    else
        return row + size - 3 * layer + 4 * (size - layer + 1) * (layer - 1) + 2;
}

int main() {
    int dimension;
    cin >> dimension;

    for (int row = 0; row < dimension; row++) {
        if (row)
            cout << endl;
        for (int col = 0; col < dimension; col++) {
            cout << setw(6) << computeValue(row + 1, col + 1, dimension);
        }
    }
    return 0;
}

