/*
//	Constructor/destructor. Not used. We stick to init() and close() here.
*/
bbLua::bbLua() { }
bbLua::~bbLua() { }

/*
//  Test function
*/
int bbLua::my_function(lua_State *L)
{
	int argCount = lua_gettop(L);
	std::cerr << "-- my_function() invoked with " << argCount
	<< " parameters:" << std::endl;
	for ( int idx=1; idx<=argCount; ++idx )
	{
		std::cerr << "-- parameter " << idx << ": "
		<< lua_tostring(L, idx) << std::endl;
	}
	lua_pushnumber(L, 456); // return value
	return 1; // number of returned values
}

/*
//  Error reporting function
*/
void bbLua::report_errors(lua_State *L, int result)
{
	if ( result!=0 )
	{
		std::cerr << "-- " << lua_tostring(L, -1) << std::endl;
		lua_pop(L, 1); // pop error message
	}
}

/*
//  bbLua::close - Terminates our lua environment
*/
void bbLua::close()
{
	lua_close(LuaContext);
}

/*
//	bbLua::init - Sets up our lua environment
*/
void bbLua::init()
{
	/* library setup */
	LuaContext = lua_open();
	luaopen_io(LuaContext); // exposes io.*
	luaopen_base(LuaContext);
	luaopen_table(LuaContext);
	luaopen_string(LuaContext);
	luaopen_math(LuaContext);
	luaopen_loadlib(LuaContext);
	// expose functions to Lua scripts
	lua_register(LuaContext, "Print", luaPrint);
	lua_register(LuaContext, "Reconfigure", luaReconfigure);
	lua_register(LuaContext, "SwitchDesktop", luaSwitchDesktop);
	lua_register(LuaContext, "SendBroam", luaSendBroam);
	lua_register(LuaContext, "GetBlackboxWindow", luaGetBlackboxWindow);
	lua_register(LuaContext, "GetProxyWindow", luaGetProxyWindow);
	lua_register(LuaContext, "FindWindow", luaFindWindow);
	lua_register(LuaContext, "SendMessage", luaSendMessage);
	lua_register(LuaContext, "RegisterEvent", luaRegisterEvent);
	lua_register(LuaContext, "UnregisterEvent", luaUnregisterEvent);
}

/*
//	loadFile - Loads a script into the lua context.
//
//	This function should be rewritten to support some kind of #include
//	directive.
*/
void bbLua::loadFile(const char* filename) {
	int status = luaL_loadfile(LuaContext, filename);
	std::cerr << "Executing script" << std::endl;
	if ( status==0 )
	{
		status = lua_pcall(LuaContext, 0, LUA_MULTRET, 0);
	}
	report_errors(LuaContext, status);
}

lua_State* bbLua::GetLuaContext()
{
	return(LuaContext);
}

int bbLua::CallLuaFunctionByName(char* funcName, int numArgs, ...)
{
	int i;
	char* param;
	va_list arguments;
	va_start(arguments, numArgs);
	lua_pushstring(LuaContext, funcName);
	for (i=0; i<numArgs; i++)
	{
		param = va_arg(arguments, char*);
		lua_pushstring(LuaContext, param);
	}
    lua_pcall(LuaContext, numArgs, LUA_MULTRET, 0);
	va_end(arguments);
	return(0);
}

