bool XG_UndoBuffer::CanUndo() const {
    if (!m_enabled)
        return false;
    return m_index > 0;
}

bool XG_UndoBuffer::CanRedo() const {
    if (!m_enabled)
        return false;
    return m_index < GetSize();
}

bool XG_UndoBuffer::Undo() {
    if (CanUndo()) {
        --m_index;
        at(m_index).Execute(false);
        return true;
    }
    return false;
}

bool XG_UndoBuffer::Redo() {
    if (CanRedo()) {
        at(m_index).Execute(true);
        ++m_index;
        return true;
    }
    return false;
}

void XG_UndoBuffer::Record(const XG_UndoInfo& ui) {
    if (!m_enabled)
        return;

    resize(m_index);

    emplace_back(ui);
    ++m_index;
}

static const int k_max_capacity = 30;

void XG_UndoBuffer::Record(UINT msg_id,
    std::shared_ptr<XG_UndoData> prior, std::shared_ptr<XG_UndoData> current)
{
    if (!m_enabled)
        return;

    resize(m_index);

    emplace_back(msg_id, prior, current);
    ++m_index;

    if (size() > k_max_capacity) {
        pop_front();
        --m_index;
    }
}

