static void* s_flv_writer;

// Callback function to send data through socket
static int rtmp_send_data(void* ctx, const void* hdr, size_t hdr_len, const void* payload, size_t payload_len)
{
    socket_t* sock = (socket_t*)ctx;
    socket_bufvec_t buffer_vec[2];
    socket_setbufvec(buffer_vec, 0, (void*)hdr, hdr_len);
    socket_setbufvec(buffer_vec, 1, (void*)payload, payload_len);
    return socket_send_v_all_by_time(*sock, buffer_vec, payload_len ? 2 : 1, 0, 2000);
}

// Handle incoming audio data
static int rtmp_on_audio_frame(void* /*user_data*/, const void* data, size_t size, uint32_t ts)
{
    return flv_writer_input(s_flv_writer, FLV_TYPE_AUDIO, data, size, ts);
}

// Handle incoming video data
static int rtmp_on_video_frame(void* /*user_data*/, const void* data, size_t size, uint32_t ts)
{
    return flv_writer_input(s_flv_writer, FLV_TYPE_VIDEO, data, size, ts);
}

// Handle incoming script metadata
static int rtmp_on_script_data(void* /*user_data*/, const void* data, size_t size, uint32_t ts)
{
    return flv_writer_input(s_flv_writer, FLV_TYPE_SCRIPT, data, size, ts);
}

// Play RTMP stream and save to local FLV file
// Usage: rtmp_play_test("live.example.com", "app", "stream_name", "output.flv")
void rtmp_play_test(const char* hostname, const char* app_name, const char* stream_id, const char* output_file)
{
    static char buffer[8 * 1024 * 1024];
    snprintf(buffer, sizeof(buffer), "rtmp://%s/%s", hostname, app_name); // tcUrl

    socket_init();
    socket_t conn_socket = socket_connect_host(hostname, 1935, 2000);
    socket_setnonblock(conn_socket, 0);

    struct rtmp_client_handler_t handler_ops;
    memset(&handler_ops, 0, sizeof(handler_ops));
    handler_ops.send = rtmp_send_data;
    handler_ops.onaudio = rtmp_on_audio_frame;
    handler_ops.onvideo = rtmp_on_video_frame;
    handler_ops.onscript = rtmp_on_script_data;

    rtmp_client_t* client = rtmp_client_create(app_name, stream_id, buffer, &conn_socket, &handler_ops);
    s_flv_writer = flv_writer_create(output_file);

    int status = rtmp_client_start(client, 1);

    while ((status = socket_recv(conn_socket, buffer, sizeof(buffer), 0)) > 0)
    {
        status = rtmp_client_input(client, buffer, status);
    }

    rtmp_client_stop(client);
    flv_writer_destroy(s_flv_writer);
    rtmp_client_destroy(client);
    socket_close(conn_socket);
    socket_cleanup();
}

