#include <bits/stdc++.h>
using namespace std;

struct element {
    int x, y, z, freq; 
    int result;

    bool operator< (const element& other) const { 
        return x == other.x ? (y == other.y ? z < other.z : y < other.y) : x < other.x; 
    }

    bool operator== (const element& other) const { 
        return x == other.x && y == other.y && z == other.z; 
    }
} input_arr[100005], temp_arr[100005];

int final_result[100005];

struct FenwickTree {
    int tree[200005];

    inline void reset() { 
        memset(tree, 0, sizeof(tree)); 
    }

    inline int lowbit(int num) { 
        return num & (-num); 
    }

    inline int prefixSum(int idx) { 
        int sum = 0; 
        for (; idx; idx -= lowbit(idx)) 
            sum += tree[idx]; 
        return sum; 
    }

    inline void update(int idx, int val=1) { 
        for (; idx <= 200000; idx += lowbit(idx)) 
            tree[idx] += val; 
    }

    inline int rangeQuery(int left, int right) { 
        return left <= right ? (prefixSum(right) - (left ? prefixSum(left - 1) : 0)) : 0; 
    }
} BIT;

void divideAndConquer(int left, int right, bool needSort = 1) {
    if (left >= right) return;

    int center = left + right >> 1;
    divideAndConquer(left, center);
    divideAndConquer(center + 1, right);

    int ptr = left;
    for (int j = center + 1; j <= right; ++j) {
        while (ptr <= center && temp_arr[ptr].y <= temp_arr[j].y) {
            BIT.update(temp_arr[ptr].z, temp_arr[ptr].freq);
            ++ptr;
        }
        temp_arr[j].result += BIT.prefixSum(temp_arr[j].z);
    }

    for (int j = left; j < ptr; ++j) {
        BIT.update(temp_arr[j].z, -temp_arr[j].freq);
    }

    if (needSort) {
        sort(temp_arr + left, temp_arr + right + 1, 
             [](const element& a, const element& b) { 
                 return a.y < b.y; 
             });
    }
}

int main() {
    int n, threshold;
    scanf("%d%d", &n, &threshold);

    for (int i = 1; i <= n; ++i) {
        scanf("%d%d%d", &input_arr[i].x, &input_arr[i].y, &input_arr[i].z);
        input_arr[i].freq = 1;
    }

    sort(input_arr + 1, input_arr + 1 + n);

    int uniqueCount = 1;
    temp_arr[1] = input_arr[1];

    for (int i = 2; i <= n; ++i) {
        if (input_arr[i] == input_arr[i-1]) {
            ++temp_arr[uniqueCount].freq;
        } else {
            temp_arr[++uniqueCount] = input_arr[i];
        }
    }

    divideAndConquer(1, uniqueCount, 0);

    for (int i = 1; i <= uniqueCount; ++i) {
        final_result[temp_arr[i].result + temp_arr[i].freq - 1] += temp_arr[i].freq;
    }

    for (int i = 0; i < n; ++i) {
        printf("%d\n", final_result[i]);
    }

    return 0;
}

#include <stdio.h>
