namespace libq {

// Compute a 64-bit hash value for the given state key, truncated to specified width
static inline unsigned int hash64(state_t key, int width) {
  unsigned int k32 = (key & 0xFFFFFFFF) ^ (key >> 32);
  k32 *= 0x9e370001UL;
  k32 = k32 >> (32 - width);
  return k32;
}

// Retrieve index of state 'a' in register, or -1 if not found
state_t get_state(state_t a, qureg *reg) {
  unsigned int idx = hash64(a, reg->hashw);
  while (reg->hash[idx]) {
    if (reg->state[reg->hash[idx] - 1] == a) {
      return reg->hash[idx] - 1;
    }
    idx++;
    if (idx == static_cast<unsigned int>((1 << reg->hashw))) {
      break;
    }
  }
  return -1;
}

// Insert a new entry into the hash table at position 'pos'
void libq_add_hash(state_t a, int pos, qureg *reg) {
  int wrap_flag = 0;
  unsigned int idx = hash64(a, reg->hashw);
  while (reg->hash[idx]) {
    idx++;
    if (idx == (1 << reg->hashw)) {
      if (!wrap_flag) {
        idx = 0;
        wrap_flag = 1;
      } else {
        // TODO(rhundt): Handle full hashtable.
      }
    }
  }
  reg->hash[idx] = pos + 1;
  if (reg->hash_caching && reg->hits < HASH_CACHE_SIZE) {
    reg->hash_hits[reg->hits] = idx;
    reg->hits += 1;
  }
}

// Rebuild the hash table from scratch
void libq_reconstruct_hash(qureg *reg) {
  reg->hash_computes += 1;
  if (reg->hash_caching && reg->hits < HASH_CACHE_SIZE) {
    for (int i = 0; i < reg->hits; ++i) {
      reg->hash[reg->hash_hits[i]] = 0;
      reg->hash_hits[i] = 0;
    }
    reg->hits = 0;
  } else {
    memset(reg->hash, 0, (1 << reg->hashw) * sizeof(int));
    memset(reg->hash_hits, 0, reg->hits * sizeof(int));
    reg->hits = 0;
    // TODO(rhundt): Apparently the compiler doesn't convert this loop.
    //               Investigate.
    // for (int i = 0; i < (1 << reg->hashw); ++i) {
    //   reg->hash[i] = 0;
    // }
  }
  for (int i = 0; i < reg->size; ++i) {
    libq_add_hash(reg->state[i], i, reg);
  }
}

// Apply a single-qubit gate to the quantum register
void libq_gate1(int target, cmplx m[4], qureg *reg) {
  int extra_states = 0;
  libq_reconstruct_hash(reg);

  /* Count how many new basis states will be needed */
  for (int i = 0; i < reg->size; ++i) {
    state_t flipped = reg->state[i] ^ (static_cast<state_t>(1) << target);
    if (get_state(flipped, reg) == static_cast<state_t>(-1))
      extra_states++;
  }

  /* Expand storage if necessary */
  if (extra_states) {
    reg->state = static_cast<state_t *>(
      realloc(reg->state, (reg->size + extra_states) * sizeof(state_t)));
    reg->amplitude = static_cast<cmplx *>(
      realloc(reg->amplitude, (reg->size + extra_states) * sizeof(cmplx)));
    memset(&reg->state[reg->size], 0, extra_states * sizeof(state_t));
    memset(&reg->amplitude[reg->size], 0, extra_states * sizeof(cmplx));
    if (reg->size + extra_states > reg->maxsize) {
      reg->maxsize = reg->size + extra_states;
    }
  }

  char *processed = static_cast<char *>(calloc(reg->size + extra_states, sizeof(char)));
  int next_slot = reg->size;
  float threshold = (1.0 / (static_cast<state_t>(1) << reg->width)) * 1e-6;

  /* Perform matrix multiplication for each basis state */
  for (int i = 0; i < reg->size; ++i) {
    if (!processed[i]) {
      int bit_set = reg->state[i] & (static_cast<state_t>(1) << target);
      int partner_idx =
          get_state(reg->state[i] ^ (static_cast<state_t>(1) << target), reg);
      cmplx partner_amp = partner_idx >= 0 ? reg->amplitude[partner_idx] : 0;
      cmplx current_amp = reg->amplitude[i];

      if (bit_set) {
        reg->amplitude[i] = m[2] * partner_amp + m[3] * current_amp;
      } else {
        reg->amplitude[i] = m[0] * current_amp + m[1] * partner_amp;
      }

      if (partner_idx >= 0) {
        if (bit_set) {
          reg->amplitude[partner_idx] = m[0] * partner_amp + m[1] * current_amp;
        } else {
          reg->amplitude[partner_idx] = m[2] * current_amp + m[3] * partner_amp;
        }
        processed[partner_idx] = 1;
      } else { /* Create new basis state */
        if ((abs(m[1]) == 0.0) && bit_set) break;
        if ((abs(m[2]) == 0.0) && !bit_set) break;
        reg->state[next_slot] =
            reg->state[i] ^ (static_cast<state_t>(1) << target);
        reg->amplitude[next_slot] = bit_set ? m[1] * current_amp : m[2] * current_amp;
        next_slot += 1;
      }
    }
  }

  reg->size += extra_states;
  free(processed);

  /* Trim negligible amplitude states */
  if (reg->hashw) {
    int removed_count = 0;
    for (int i = 0, j = 0; i < reg->size; ++i) {
      if (probability(reg->amplitude[i]) < threshold) {
        j++;
        removed_count++;
      } else if (j) {
        reg->state[i - j] = reg->state[i];
        reg->amplitude[i - j] = reg->amplitude[i];
      }
    }
    if (removed_count) {
      reg->size -= removed_count;
      // These seem redundant.
      // reg->amplitude = static_cast<cmplx *>(
      //   realloc(reg->amplitude, reg->size * sizeof(cmplx)));
      // reg->state = static_cast<state_t *>(
      //   realloc(reg->state, reg->size * sizeof(state_t)));
    }
  }

  if (reg->size > (1 << (reg->hashw - 1)))
    fprintf(stderr, "Warning: inefficient hash table (size %i vs hash %i)\n",
            reg->size, 1 << reg->hashw);
}

