Point3D generateRandomUnitVector() {
    std::normal_distribution<coord_t> dist;
    int attempts = 0;
    coord_t vx, vy, vz;
    do {
        vx = random(dist);
        vy = random(dist);
        vz = random(dist);
    } while (vx == 0 && vy == 0 && vz == 0 && attempts++ < 64);

