#include <array>
#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    array<int, 26> freq;

    while (true) {
        int roundNum;
        cin >> roundNum;
        if (roundNum < 0) {
            break;
        }

        cout << "Round " << roundNum << endl;

        string target, guesses;
        cin >> target >> guesses;

        freq.fill(0);
        for (char ch : target) {
            freq[ch - 'a']++;
        }

        int matched = 0;
        int wrong = 0;

        for (char ch : guesses) {
            int idx = ch - 'a';
            if (freq[idx] > 0) {
                matched += freq[idx];
                if (matched == target.size()) {
                    break;
                }
                freq[idx] = -1;
            } else if (freq[idx] == 0) {
                wrong++;
                if (wrong == 7) {
                    break;
                }
                freq[idx] = -1;
            }
        }

        if (matched == target.size()) {
            cout << "You win." << endl;
        } else if (wrong == 7) {
            cout << "You lose." << endl;
        } else {
            cout << "You chickened out." << endl;
        }
    }

    return 0;
}

