// Error handling macro: throws JavaScript TypeError with message s
#define EE(s) {TypeError::New(e, s).ThrowAsJavaScriptException(); return e.Null();}

using namespace Napi;

// Helper function to check if a Value is an integer (returns 1 if true)
static inline I ii(Value v){F d=v.As<Number>().DoubleValue(); return (I)d==d;}

// Get element i from array v
Value oi(Value v, I i){Array a=v.As<Array>(); return a[i];}

// Determine K type from JavaScript Value
I to(Value v){
    if(v.IsNumber()){
        P(ii(v), 'j'); 
        return 'f';
    }
    P(v.IsArray(), ' ') 
    return 0;
}

// Convert JavaScript Value to K object
K ko(Value v){
    S(to(v),
      C(0,0)
      C('j',kj(v.As<Number>().Int64Value()))
      C('f',kf(v.As<Number>().DoubleValue())),
      K x=k(' ',v.As<Array>().Length());
      N(xn, Xx=ko(oi(v,i));P(!Xx,0))x)
}

// Convert K object back to JavaScript Value
Value ok(Env e, K x){
    S(tx,
      C(KJ,Number::New(e, (F)xj))
      C(KF,Number::New(e, xf)),
      Array v=Array::New(e, xn);
      N(xn,v[i]=ok(e, Xx))v)
}

// Main callback function for k() method
Value _(const CallbackInfo& i){
    Env e=i.Env(); 
    // Require exactly 2 arguments: function name and args array
    if(i.Length()!=2) EE("format: k(function name, args array)"); 
    if(!i[0].IsString()||!i[1].IsObject()) EE("Wrong args"); 
    Value v;

    // Extract function name and convert arguments to K format
    S cf=i[0].ToString().Utf8Value().c_str(); 
    K x=ko(i[1]);

    // Execute the K function and handle errors
    R!x||ERR(x=k((K)cf,x))?TypeError::New(e, "ex").ThrowAsJavaScriptException(), e.Null():(v=ok(e, x),k(0,x),v);
}

// Module initialization function
Object Init(Env e, Object exp){
    exp.Set(String::New(e, "k"), Function::New(e, _)); 
    return exp;
}

