namespace keisan
{
std::ostream & operator<<(std::ostream & out, const EulerAngles & euler)
{
  return out << euler.roll << " " << euler.pitch << " " << euler.yaw;
}

EulerAngles::EulerAngles()
{
}

EulerAngles::EulerAngles(const Angle & r, const Angle & p, const Angle & y)
: roll(r), pitch(p), yaw(y)
{
}

EulerAngles::EulerAngles(const EulerAngles & src)
: roll(src.roll), pitch(src.pitch), yaw(src.yaw)
{
}

EulerAngles & EulerAngles::operator=(const EulerAngles & src)
{
  roll = src.roll;
  pitch = src.pitch;
  yaw = src.yaw;
  return *this;
}

bool EulerAngles::operator==(const EulerAngles & other) const
{
  return roll == other.roll && pitch == other.pitch && yaw == other.yaw;
}

bool EulerAngles::operator!=(const EulerAngles & other) const
{
  return roll != other.roll || pitch != other.pitch || yaw != other.yaw;
}

Quaternion EulerAngles::quaternion() const
{
  Quaternion q;
  double sr = sin(0.5 * roll);
  double cr = cos(0.5 * roll);
  double sp = sin(0.5 * pitch);
  double cp = cos(0.5 * pitch);
  double sy = sin(0.5 * yaw);
  double cy = cos(0.5 * yaw);

  q.x = sr * cp * cy - cr * sp * sy;
  q.y = cr * sp * cy + sr * cp * sy;
  q.z = cr * cp * sy - sr * sp * cy;
  q.w = cr * cp * cy + sr * sp * sy;

  return q;
}
}  // namespace keisan

