// JFSStat implementation
JFSStat::JFSStat(JFSStatKind statKind, llvm::StringRef identifier) : kind(statKind) {
    this->identifier.assign(identifier.begin(), identifier.end());
}

JFSStat::~JFSStat() {}

void JFSStat::dump() const {
    llvm::ScopedPrinter printer(llvm::errs());
    printYAML(printer);
}

llvm::StringRef JFSStat::getName() const { return identifier; }

// JFSTimerStat implementation
JFSTimerStat::JFSTimerStat(RecordTy recordData, llvm::StringRef label)
    : JFSStat(SINGLE_TIMER, label), record(recordData) {}

JFSTimerStat::~JFSTimerStat() {}

void JFSTimerStat::printYAML(llvm::ScopedPrinter& printer) const {
    printer.indent();
    auto& stream = printer.getOStream();
    stream << "\n";
    printer.startLine() << "name: " << getName() << "\n";
#define TIME_FORMAT "%.6f"
    printer.startLine() << "user_time: "
                        << llvm::format(TIME_FORMAT, record.getUserTime()) << "\n";
    printer.startLine() << "sys_time: "
                        << llvm::format(TIME_FORMAT, record.getSystemTime()) << "\n";
    printer.startLine() << "wall_time: "
                        << llvm::format(TIME_FORMAT, record.getWallTime()) << "\n";
    printer.startLine() << "mem_use: " << record.getMemUsed() << "\n";
#undef TIME_FORMAT
    printer.unindent();
}

// JFSAggregateTimerStat implementation
JFSAggregateTimerStat::JFSAggregateTimerStat(llvm::StringRef title)
    : JFSStat(AGGREGATE_TIMER, title) {}

JFSAggregateTimerStat::~JFSAggregateTimerStat() {}

void JFSAggregateTimerStat::append(std::unique_ptr<JFSTimerStat> timer) {
    timerList.push_back(std::move(timer));
}

void JFSAggregateTimerStat::clear() { timerList.clear(); }

void JFSAggregateTimerStat::printYAML(llvm::ScopedPrinter& printer) const {
    printer.indent();
    auto& stream = printer.getOStream();
    stream << "\n";
    printer.startLine() << "name: " << getName() << "\n";
    printer.startLine() << "stats:";

    if (timerList.size() == 0) {
        stream << " []\n";
        return;
    }

    stream << "\n";
    printer.indent();
    for (const auto& entry : timerList) {
        printer.startLine() << "-";
        entry->printYAML(printer);
    }
    printer.unindent();
    printer.unindent();
}

}
