#include "socket.hh"
#include "gason.h"
#include "sql_message.hh"

int receive_response(socket_t &sock, std::string &resp);
int fetch_http_headers(socket_t &sock, std::string &head);

/////////////////////////////////////////////////////////////////////////////////////////////////////
//usage
//-u http://127.0.0.1/get_places
//-u http://127.0.0.1/get_items
/////////////////////////////////////////////////////////////////////////////////////////////////////
void print_usage()
{
  std::cout << "usage: sqlite_client -u URI <-p PORT> <-h>" << std::endl;
  std::cout << "-u URI" << std::endl;
  std::cout << "-h: help, exit" << std::endl;
  std::cout << "-o PORT: port (default 3000)" << std::endl;
  exit(0);
}

///////////////////////////////////////////////////////////////////////////////////////
//main
///////////////////////////////////////////////////////////////////////////////////////
int main(int argc, char *argv[])
{
  std::string target_uri;
  unsigned short server_port = 3000;
  sql_action_t action = sql_action_t::none;
  std::string new_item;
  std::string new_place;

  for (int idx = 1; idx < argc && argv[idx][0] == '-'; idx++)
  {
    switch (argv[idx][1])
    {
    case 'h':
      print_usage();
      break;
    case 'o':
      server_port = static_cast<unsigned short>(atoi(argv[idx + 1]));
      idx++;
      break;
    case 'u':
      target_uri = argv[idx + 1];
      idx++;
      break;
    }
  }

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //client
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //parse URI 
  std::size_t scheme_end = target_uri.find("://", 0);
  if (scheme_end == std::string::npos)
  {
    print_usage();
  }
  scheme_end += 3;
  std::size_t path_start = target_uri.find("/", scheme_end + 1);
  std::string hostname = target_uri.substr(scheme_end, path_start - scheme_end);
  std::cout << "host: " << hostname << std::endl;

  //get API token
  std::string api_endpoint = target_uri.substr(path_start);

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //generate SQL from API
  //API:
  // /get_places
  // /get_items
  // /create_table_places
  // /create_table_items
  // /insert_place
  // /insert_item
  // /select_places
  // /select_items
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  if (api_endpoint.compare("/get_places") == 0)
  {
    action = sql_action_t::get_places;
  }
  else if (api_endpoint.compare("/get_items") == 0)
  {
    action = sql_action_t::get_items;
  }
  else if (api_endpoint.compare("/create_table_places") == 0)
  {
    action = sql_action_t::create_table_places;
  }
  else if (api_endpoint.compare("/create_table_items") == 0)
  {
    action = sql_action_t::create_table_items;
  }
  else if (api_endpoint.find("/insert_place/") != std::string::npos)
  {
    action = sql_action_t::insert_place;
    new_place = api_endpoint.substr(std::string("/insert_place/").size());
  }
  else if (api_endpoint.find("/insert_item/") != std::string::npos)
  {
    action = sql_action_t::insert_item;
    new_item = api_endpoint.substr(std::string("/insert_item/").size());
  }
  else if (api_endpoint.compare("/select_places") == 0)
  {
    action = sql_action_t::select_places;
  }
  else if (api_endpoint.compare("/select_items") == 0)
  {
    action = sql_action_t::select_items;
  }

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //make sql and JSON (an array of strings)
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  std::string json_payload = "[";
  sql_t sql_query;
  switch (action)
  {
  case sql_action_t::none:
    print_usage();
    return 0;
  case sql_action_t::create_table_places:
    json_payload += "\"";
    json_payload += sql_query.create_table_places();
    json_payload += "\"";
    break;
  case sql_action_t::create_table_items:
    json_payload += "\"";
    json_payload += sql_query.create_table_items();
    json_payload += "\"";
    break;
  case sql_action_t::insert_place:
    assert(new_place.length());
    json_payload += "\"";
    json_payload += sql_query.insert_place(new_place.c_str());
    json_payload += "\"";
    break;
  case sql_action_t::insert_item:
    assert(new_item.length());
    json_payload += "\"";
    json_payload += sql_query.insert_item(new_item.c_str(), "home");
    json_payload += "\"";
    break;
  case sql_action_t::select_places:
    json_payload += "\"";
    json_payload += sql_query.select_places(NULL);
    json_payload += "\"";
    break;
  case sql_action_t::select_items:
    json_payload += "\"";
    json_payload += sql_query.select_items(NULL);
    json_payload += "\"";
    break;
  case sql_action_t::all:
    json_payload += "\"";
    json_payload += sql_query.create_table_places();
    json_payload += "\"";
    json_payload += ",";
    json_payload += "\"";
    json_payload += sql_query.create_table_items();
    json_payload += "\"";
    json_payload += ",";
    json_payload += "\"";
    json_payload += sql_query.insert_place("home");
    json_payload += "\"";
    json_payload += ",";
    json_payload += "\"";
    json_payload += sql_query.insert_item("it1", "home");
    json_payload += "\"";
    json_payload += ",";
    json_payload += "\"";
    json_payload += sql_query.select_places("home");
    json_payload += "\"";
    json_payload += ",";
    json_payload += "\"";
    json_payload += sql_query.select_items("home");
    json_payload += "\"";
    break;
  }
  json_payload += "]";

  std::ofstream file_out("request.json");
  file_out << json_payload.c_str();
  file_out.close();

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //make HTTP request
  //construct request message using sql in body
  //separate between GET and POST methods
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  char request_buffer[1024];
  if (action == sql_action_t::get_items)
  {
    sprintf(request_buffer, "GET /get_items HTTP/1.1\r\n\r\n");
  }
  else if (action == sql_action_t::get_places)
  {
    sprintf(request_buffer, "GET /get_places HTTP/1.1\r\n\r\n");
  }
  else
  {
    sprintf(request_buffer, "POST / HTTP/1.1\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s",
      strlen(json_payload.c_str()), json_payload.c_str());
  }

#if _MSC_VER
  Sleep(500);
#endif

  tcp_client_t client(hostname.c_str(), server_port);
  std::cout << "client connecting to: " << hostname << ":" << server_port << " <" << client.m_socket_fd << "> " << std::endl;

  if (client.open() < 0)
  {
    std::string error_msg = "connect error to: ";
    error_msg += hostname;
    std::cout << error_msg << std::endl;
    return 1;
  }

  std::cout << "client: connected to: " << hostname << ":" << server_port << std::endl;

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //send
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  if (client.write_all(request_buffer, strlen(request_buffer)) < 0)
  {
  }
  std::cout << "client sent: \n" << request_buffer << std::endl;

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //read response if there is one
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  std::string server_response;
  if (receive_response(client, server_response) > 0)
  {
    std::cout << "client received:\n";
    std::cout << server_response << std::endl;
  }

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //close connection
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  client.close_socket();
  return 0;
}

/////////////////////////////////////////////////////////////////////////////////////////////////////
//receive_response
//return value
//0 nothing received
//1 something received
/////////////////////////////////////////////////////////////////////////////////////////////////////
int receive_response(socket_t &sock, std::string &resp)
{
  //get HTTP header
  std::string head;
  if (fetch_http_headers(sock, head) == 0)
  {
    return 0;
  }

  //get size
  unsigned int body_size = static_cast<unsigned int>(http_get_field("Content-Length: ", head));

  //read from socket with known size
  if (body_size)
  {
    char *buffer = new char[body_size];
    if (sock.read_all(buffer, body_size) < 0)
    {
      std::cout << "recv error: " << strerror(errno) << std::endl;
    }
    std::string json_string(buffer, body_size);
    resp = json_string;
    delete[] buffer;
    return 1;
  }
  return 1;
}

/////////////////////////////////////////////////////////////////////////////////////////////////////
//parse_http_headers
//return value
//0 nothing received
//1 something received
/////////////////////////////////////////////////////////////////////////////////////////////////////
int fetch_http_headers(socket_t &sock, std::string &head)
{
  int bytes_received; // size in bytes received or -1 on error 
  const int buffer_capacity = 4096;
  char temp_buffer[buffer_capacity];

  /////////////////////////////////////////////////////////////////////////////////////////////////////
  //MSG_PEEK
  //Peeks at an incoming message.The data is treated as unread and the next recv() or similar 
  //function shall still return this data.
  /////////////////////////////////////////////////////////////////////////////////////////////////////
  if ((bytes_received = recv(sock.m_socket_fd, temp_buffer, buffer_capacity, MSG_PEEK)) == -1)
  {
    std::cout << "recv error: " << strerror(errno) << std::endl;
    return -1;
  }

  if (bytes_received == 0)
  {
    return 0;
  }

  std::string raw_data(temp_buffer);
  size_t delimiter_pos = raw_data.find("\r\n\r\n");
  if (delimiter_pos == std::string::npos)
  {
    std::cout << "HTTP header bad format" << std::endl;
    return -1;
  }

  head = raw_data.substr(0, delimiter_pos + 4);
  int header_length = static_cast<int>(delimiter_pos + 4);

  //now get headers with the obtained size from socket
  if ((bytes_received = recv(sock.m_socket_fd, temp_buffer, header_length, 0)) == -1)
  {
    std::cout << "recv error: " << strerror(errno) << std::endl;
  }

  //sanity check
  std::string verified_buffer(temp_buffer);
  assert(verified_buffer == raw_data);

  size_t header_size = head.size();
  size_t total_message_size = raw_data.size();
  std::cout << "HTTP header size: " << header_size << std::endl;
  std::cout << head.c_str() << std::endl;
  return 1;
}

#include "runtime/date-parse-util.h"
#include "cctz/civil_time.h"
#include "runtime/datetime-iso-sql-format-parser.h"
#include "runtime/datetime-simple-date-format-parser.h"
#include "runtime/string-value.inline.h"
