		struct DescriptorLayout final {
			std::vector<VkDescriptorSetLayoutBinding> Bindings;
		};
		struct GraphicsPipelineCreate final {
			std::vector<VkVertexInputAttributeDescription> Attributes;
			std::vector<VkVertexInputBindingDescription> Bindings;
			const Program* ShaderProgram = nullptr;
			const PipelineLayout* Layout = nullptr;
			VkVertexInputAttributeDescription& AddAttribute(GLuint location) noexcept {
				Attributes.emplace_back().location = static_cast<uint32_t>(location);
				return Attributes.back();
			}
			VkVertexInputBindingDescription& AddBinding(GLuint index) noexcept {
				Bindings.emplace_back().binding = static_cast<uint32_t>(index);
				return Bindings.back();
			}
		};
	}
	PipelineLayout::PipelineLayout() noexcept {
		_LayoutHandle = reinterpret_cast<uintptr_t>(new DescriptorLayout) + 1;
	}
	PipelineLayout::~PipelineLayout() noexcept {
		if (_LayoutHandle & 1) {
			delete reinterpret_cast<DescriptorLayout*>(_LayoutHandle - 1);
		}
		else {
			vkDestroyPipelineLayout(D::context->GetDevice(), reinterpret_cast<VkPipelineLayout>(_LayoutHandle), nullptr);
			vkDestroyDescriptorSetLayout(D::context->GetDevice(), _SetLayout, nullptr);
		}
	}
	void PipelineLayout::Finalize() noexcept {
		if (_LayoutHandle & 1) {
			auto layoutData = reinterpret_cast<DescriptorLayout*>(_LayoutHandle - 1);
			VkDescriptorSetLayoutCreateInfo descriptorInfo = {};
			descriptorInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
			descriptorInfo.pNext = nullptr;
			descriptorInfo.bindingCount = layoutData->Bindings.size();
			descriptorInfo.pBindings = layoutData->Bindings.data();
			vkCreateDescriptorSetLayout(D::context->GetDevice(), &descriptorInfo, nullptr, &_SetLayout);
			delete reinterpret_cast<DescriptorLayout*>(_LayoutHandle - 1);
			VkPipelineLayoutCreateInfo pipelineLayoutInfo = {};
			pipelineLayoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
			pipelineLayoutInfo.pNext = nullptr;
			pipelineLayoutInfo.pushConstantRangeCount = 0;
			pipelineLayoutInfo.pPushConstantRanges = nullptr;
			pipelineLayoutInfo.setLayoutCount = 1;
			pipelineLayoutInfo.pSetLayouts = &_SetLayout;
			vkCreatePipelineLayout(D::context->GetDevice(), &pipelineLayoutInfo, nullptr,
				reinterpret_cast<VkPipelineLayout*>(&_LayoutHandle));
		}
	}
	void PipelineLayout::AddDescriptorBinding(GLuint binding, GLenum type) noexcept {
		static constexpr auto MapType = [](const GLenum type) noexcept->VkDescriptorType {
			switch (type) {
			case GL_UNIFORM_BUFFER: return VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
			default: return VK_DESCRIPTOR_TYPE_RANGE_SIZE;
			}
		};
		if (_LayoutHandle & 1) {
			auto layoutData = reinterpret_cast<DescriptorLayout*>(_LayoutHandle - 1);
			VkDescriptorSetLayoutBinding bindInfo;
			bindInfo.binding = binding;
			bindInfo.descriptorType = MapType(type);
			bindInfo.descriptorCount = 1;
			bindInfo.stageFlags = VK_SHADER_STAGE_ALL;
			bindInfo.pImmutableSamplers = nullptr;
			layoutData->Bindings.push_back(bindInfo);
		}
	}
