#include <algorithm>
#include <assert.h>
#include <numeric>

namespace tilegen
{
namespace alpha
{
void CalculatorLinear::updateAlphasAux(const Weights& weights)
{
    int remaining_alpha = 100;
    double sum_weights = std::accumulate(weights.begin(), weights.end(), 0.0);

    // Handle case where total weight is negligible
    if (sum_weights <= std::numeric_limits<double>::epsilon() * 100 * 4)
    {
        // Early exit when weights are effectively zero
        return;
    }

    // Initial allocation: assign proportional alpha values
    for (size_t idx = 0; idx < weights.size(); ++idx)
    {
        int alpha_value = static_cast<int>((100 * weights[idx]) / sum_weights);
        remaining_alpha -= alpha_value;
        getAlpha(idx) = static_cast<sf::Uint8>(alpha_value);
    }

    // Skip redistribution if perfectly allocated
    if (remaining_alpha == 0)
        return;

    // Determine how many corners have positive alpha values
    size_t active_corners = std::count_if(getAlphas().cbegin(), getAlphas().cend(),
                                         [](const sf::Uint8& val)
    {
        return val != 0;
    });

    assert(active_corners > 0);

    // Distribute leftover alpha points evenly among active corners
    auto division_result = div(remaining_alpha, active_corners);
    assert(division_result.quot >= 0);

    int corners_processed = 0;
    for(size_t position = 0; position < getAlphas().size(); ++position)
    {
        auto& current_alpha = getAlpha(position);
        if (current_alpha == 0)
            continue;

        current_alpha += division_result.quot;
        remaining_alpha -= division_result.quot;

        // Handle remainder distribution - some corners get one extra point
        if (corners_processed < division_result.rem)
        {
            current_alpha++;
            remaining_alpha--;
            corners_processed++;
        }
    }

    assert(remaining_alpha == 0);
}
