int main() {
    // Build the tree structure:
    //         0
    //     1       2
    //   3   4

    Albero::Albero* leftSubtree1 = Albero::costruisci(Nodo::costruisci(3));
    Albero::Albero* rightSubtree1 = Albero::costruisci(Nodo::costruisci(4));
    Albero::Albero* leftBranch = Albero::unisci(Albero::costruisci(Nodo::costruisci(1)), leftSubtree1, rightSubtree1);

    Albero::Albero* rightBranch = Albero::costruisci(Nodo::costruisci(2));
    Albero::Albero* fullTree = Albero::unisci(Albero::costruisci(Nodo::costruisci(0)), leftBranch, rightBranch);

    std::cout << Nodo::valore(Albero::radice(fullTree)) << std::endl;             // 0
    std::cout << Nodo::valore(Albero::radice(Albero::sx(fullTree))) << std::endl; // 1
    std::cout << Nodo::valore(Albero::radice(Albero::dx(fullTree))) << std::endl; // 2
    std::cout << Albero::to_str(fullTree) << std::endl; // 0 1 3 4 2

    return 0;
}

