#define computeIndex(rowSize, x, y) (((x) * (rowSize)) + (y))

// ===================== GPU_FIXED_POINT_KERNELS_BEGIN =========================
__global__ void processSuccessors(int *inputA, int *outputA,
                                  std::uint64_t vectorLength, int *successorList,
                                  std::uint64_t successorListSize,
                                  bool isSecondPass) {
  std::uint64_t col = hipThreadIdx_x + hipBlockIdx_x * hipBlockDim_x;
  std::uint64_t row = hipThreadIdx_y + hipBlockIdx_y * hipBlockDim_y;

  if (row >= successorListSize || col >= vectorLength)
    return;

  int srcIndex = computeIndex(successorListSize, 0, row);
  int dstIndex = computeIndex(successorListSize, 1, row);
  int sourceBVPos = computeIndex(vectorLength, successorList[srcIndex], col);
  int destBVPos = computeIndex(vectorLength, successorList[dstIndex], col);

  if (isSecondPass)
    outputA[destBVPos] |= inputA[sourceBVPos];
  else
    outputA[destBVPos] = inputA[sourceBVPos];
}

__global__ void executeTransferFunction(int *inputA, int *outputA, int *genA,
                                        int *killA, int vectorLength,
                                        std::uint64_t instructionCount) {
  std::uint64_t col = hipThreadIdx_x + hipBlockIdx_x * hipBlockDim_x;
  std::uint64_t row = hipThreadIdx_y + hipBlockIdx_y * hipBlockDim_y;

  if (row >= instructionCount || col >= vectorLength)
    return;

  std::uint64_t position = computeIndex(vectorLength, row, col);
  inputA[position] = genA[position] | (outputA[position] & ~(killA[position]));
}
// ====================== GPU_FIXED_POINT_KERNELS_END ==========================

// ========================= LIVENESS_ANALYSIS_HELPERS_BEGIN ====================
static bool isValidForAnalysis(const llvm::Value *value) {
  if (!value->hasName())
    return false;
  if (llvm::isa<llvm::Constant>(value))
    return false;
  if (llvm::isa<llvm::BasicBlock>(value))
    return false;
  return true;
}

static std::vector<Value *> collectGenSet(Instruction *inst) {
  std::vector<Value *> genValues;
  if (auto branch = dyn_cast<BranchInst>(inst)) {
    if (branch->isConditional())
      genValues.push_back(branch->getCondition());
    return genValues;
  }

  for (auto operand : inst->operand_values()) {
    if (isValidForAnalysis(operand)) {
      genValues.push_back(operand);
    }
  }
  return genValues;
}

static std::vector<Value *> collectKillSet(Instruction *inst) {
  std::vector<Value *> killValues;
  if (isa<BranchInst>(inst))
    return killValues;
  if (isa<StoreInst>(inst))
    return killValues;
  if (isa<ReturnInst>(inst))
    return killValues;

  if (Value *val = dyn_cast<Value>(inst)) {
    if (isValidForAnalysis(val))
      killValues.push_back(val);
  }
  return killValues;
}
// ========================== LIVENESS_ANALYSIS_HELPERS_END =====================

class LiveVariableAnalyzer {
private:
  std::map<Instruction *, BitVector> generationSet, killSet;
  std::map<Instruction *, BitVector> inSet, outSet;
  int *genArray, *killArray, *inArray, *outArray;
  BitVectorMapping mapping;
  std::uint64_t instructionCount, bitVectorSize;
  std::vector<Instruction *> instructionMap;
  std::map<Instruction *, int> instructionIndexMap;
  int *successorList1, *successorList2;
  std::uint64_t successorList1Size, successorList2Size;
  std::uint64_t iterationLimit;

public:
  LiveVariableAnalyzer(BitVectorMapping map) {
    this->mapping = map;
    instructionCount = 0;
    bitVectorSize = 0;
  }

  std::vector<llvm::Instruction *> getSuccessors(llvm::Instruction *inst) {
    std::vector<llvm::Instruction *> result;
    llvm::BasicBlock *parentBlock = inst->getParent();

    if (&parentBlock->back() == inst) {
      for (llvm::BasicBlock *successor : successors(parentBlock)) {
        result.push_back(&successor->front());
      }
    } else {
      result.push_back(inst->getNextNonDebugInstruction());
    }
    return result;
  }

  void setupSuccessorData(Function &func) {
    std::vector<std::pair<int, int>> list1, list2;

    for (inst_iterator I = inst_begin(func), E = inst_end(func); I != E; ++I) {
      auto successors = getSuccessors(&*I);
      int currentIdx = instructionIndexMap[&*I];

      assert(successors.size() <= 2 &&
             "More than two successors not supported");

      if (successors.empty())
        continue;

      list1.push_back(std::make_pair(currentIdx, instructionIndexMap[successors[0]]));
      if (successors.size() == 2)
        list2.push_back(std::make_pair(currentIdx, instructionIndexMap[successors[1]]));
    }

    successorList1Size = list1.size();
    successorList2Size = list2.size();

    hipMallocManaged(&successorList1, 2 * list1.size() * sizeof(int));
    for (int j = 0; j < list1.size(); j++) {
      int idx = computeIndex(list1.size(), 0, j);
      successorList1[idx] = list1[j].first;
      idx = computeIndex(list1.size(), 1, j);
      successorList1[idx] = list1[j].second;
    }

    hipMallocManaged(&successorList2, 2 * list2.size() * sizeof(int));
    for (int j = 0; j < list2.size(); j++) {
      int idx = computeIndex(list2.size(), 0, j);
      successorList2[idx] = list2[j].first;
      idx = computeIndex(list2.size(), 1, j);
      successorList2[idx] = list2[j].second;
    }
  }

  void initializeBitVectors(Function &func) {
    hipMallocManaged(&genArray, instructionCount * bitVectorSize * sizeof(int));
    hipMallocManaged(&killArray, instructionCount * bitVectorSize * sizeof(int));
    hipMallocManaged(&inArray, instructionCount * bitVectorSize * sizeof(int));
    hipMallocManaged(&outArray, instructionCount * bitVectorSize * sizeof(int));

    int currentIdx = 0;
    for (inst_iterator I = inst_begin(func), E = inst_end(func); I != E; ++I) {
      for (int i = 0; i < bitVectorSize; i++) {
        int effectivePos = computeIndex(bitVectorSize, currentIdx, i);
        genArray[effectivePos] = (generationSet[&*I].test(i)) ? 1 : 0;
        killArray[effectivePos] = (killSet[&*I].test(i)) ? 1 : 0;
        inArray[effectivePos] = (inSet[&*I].test(i)) ? 1 : 0;
        outArray[effectivePos] = (outSet[&*I].test(i)) ? 1 : 0;
      }
      currentIdx += 1;
    }
  }

  void displaySuccessors() {
    std::cout << "First successor list => \n";
    int pos;
    for (int i = 0; i < successorList1Size; i++) {
      pos = computeIndex(successorList1Size, 0, i);
      std::cout << successorList1[pos] << ' ';
    }
    std::cout << "\n";
    for (int i = 0; i < successorList1Size; i++) {
      pos = computeIndex(successorList1Size, 1, i);
      std::cout << successorList1[pos] << ' ';
    }
    std::cout << "\nSecond successor list => \n";
    for (int i = 0; i < successorList2Size; i++) {
      pos = computeIndex(successorList2Size, 0, i);
      std::cout << successorList2[pos] << ' ';
    }
    std::cout << "\n";
    for (int i = 0; i < successorList2Size; i++) {
      pos = computeIndex(successorList2Size, 1, i);
      std::cout << successorList2[pos] << ' ';
    }
    std::cout << "\n";
  }

  void displayResults() {
    std::cout << "In set values => \n";
    for (int i = 0; i < instructionCount; i++) {
      for (int j = 0; j < bitVectorSize; j++) {
        int pos = computeIndex(bitVectorSize, i, j);
        std::cout << inArray[pos] << ' ';
      }
      std::cout << "\n";
    }

    std::cout << "Out set values => \n";
    for (int i = 0; i < instructionCount; i++) {
      for (int j = 0; j < bitVectorSize; j++) {
        int pos = computeIndex(bitVectorSize, i, j);
        std::cout << outArray[pos] << ' ';
      }
      std::cout << "\n";
    }

    std::cout << "Gen set values => \n";
    for (int i = 0; i < instructionCount; i++) {
      for (int j = 0; j < bitVectorSize; j++) {
        int pos = computeIndex(bitVectorSize, i, j);
        std::cout << genArray[pos] << ' ';
      }
      std::cout << "\n";
    }

    std::cout << "Kill set values => \n";
    for (int i = 0; i < instructionCount; i++) {
      for (int j = 0; j < bitVectorSize; j++) {
        int pos = computeIndex(bitVectorSize, i, j);
        std::cout << killArray[pos] << ' ';
      }
      std::cout << "\n";
    }
  }

  void analyzeGlobalVariables(Module *module) {
    for (auto I = module->global_begin(), E = module->global_end(); I != E; ++I) {
      if (Value *val = dyn_cast<Value>(&*I))
        mapping.assignIndexToValue(val);
    }
  }

  void analyzeLocalVariables(Function &func) {
    for (inst_iterator I = inst_begin(func), E = inst_end(func); I != E; ++I) {
      if (Value *val = dyn_cast<Value>(&(*I))) {
        if (mapping.shouldMap(val) && !mapping.getBitVectorIndexForValue(val))
          mapping.assignIndexToValue(val);
      }
      for (auto operand : I->operand_values()) {
        if (mapping.shouldMap(operand) && !mapping.getBitVectorIndexForValue(operand))
          mapping.assignIndexToValue(operand);
      }
    }
  }

  void solveOnGPU() {
    for (std::uint64_t iter = 0; iter < iterationLimit; iter++) {
      dim3 threadBlock(32, 32);
      int blocksX = (bitVectorSize + threadBlock.x - 1) / threadBlock.x;
      int blocksY = (instructionCount + threadBlock.y - 1) / threadBlock.y;

      hipLaunchKernelGGL(executeTransferFunction, 
                        dim3(blocksX, blocksY), 
                        threadBlock, 0, 0,
                        inArray, outArray, genArray, killArray, 
                        bitVectorSize, instructionCount);

      blocksY = (successorList1Size + threadBlock.y - 1) / threadBlock.y;
      hipLaunchKernelGGL(processSuccessors, 
                        dim3(blocksX, blocksY), 
                        threadBlock, 0, 0,
                        inArray, outArray, bitVectorSize, 
                        successorList1, successorList1Size,
                        /*isSecondPass=*/false);

      blocksY = (successorList2Size + threadBlock.y - 1) / threadBlock.y;
      hipLaunchKernelGGL(processSuccessors, 
                        dim3(blocksX, blocksY), 
                        threadBlock, 0, 0,
                        inArray, outArray, bitVectorSize, 
                        successorList2, successorList2Size,
                        /*isSecondPass=*/true);
    }
    hipDeviceSynchronize();
  }

  void execute(Function &func) {
    analyzeGlobalVariables(func.getParent());
    analyzeLocalVariables(func);
    mapping.printMapping();
    std::cout << mapping.getAddressToIndexMap().size() << '\n';

    for (inst_iterator I = inst_begin(func), E = inst_end(func); I != E; ++I) {
      instructionMap.push_back(&*I);
      instructionIndexMap[&*I] = instructionCount;
      instructionCount += 1;

      generationSet[&*I] = (mapping.createBitVectorWithTrue(collectGenSet(&*I)));
      if (instructionCount == 1) {
        bitVectorSize = generationSet[&*I].size();
      }

      killSet[&*I] = (mapping.createBitVectorWithTrue(collectKillSet(&*I)));
      inSet[&*I] = (mapping.createBitVectorWithAllBitsZero());
      outSet[&*I] = (mapping.createBitVectorWithAllBitsZero());
    }

    initializeBitVectors(func);
    setupSuccessorData(func);

    iterationLimit = instructionCount * instructionCount;

    std::chrono::time_point<std::chrono::steady_clock> startTime, endTime;
    std::chrono::duration<float, std::ratio<1, 1>> timeSpan;

    startTime = std::chrono::steady_clock::now();
    solveOnGPU();
    endTime = std::chrono::steady_clock::now();

    timeSpan = endTime - startTime;
    std::cout << "Computation took " << std::setprecision(10) << timeSpan.count()
              << " seconds\n";
    std::cout.flush();

    std::cout << "Final data flow results:\n";
    displayResults();

    // Cleanup resources
    hipFree(genArray);
    hipFree(killArray);
    hipFree(inArray);
    hipFree(outArray);
    hipFree(successorList1);
    hipFree(successorList2);
    mapping.reset();
  }
};

int main(int argc, char *argv[]) {
  assert(argc == 2 && "Expected exactly one argument: the .ll file path");

  LLVMContext context;
  SMDiagnostic error;
  std::unique_ptr<Module> module(parseAssemblyFile(argv[1], error, context));

  bool verificationResult = verifyModule(*module);
  assert(!verificationResult && "Module verification failed!");

  for (auto funcIter = module->begin(); funcIter != module->end(); ++funcIter) {
    BitVectorMapping mapping;
    LiveVariableAnalyzer analyzer(mapping);
    analyzer.execute(*funcIter);
  }

  return 0;
}

#define BOOST_TEST_DYN_LINK
#define BOOST_TEST_MODULE ZipTestSuite
#include "zip.hpp"
#include <boost/test/unit_test.hpp>
#include <vector>
#include <tuple>

using namespace std;

BOOST_AUTO_TEST_SUITE(ZipIteratorTests)
BOOST_AUTO_TEST_CASE(ConstructorBasic) {
    vector<int> data = {10, 20, 30};
    zip_iterator<vector<int>::iterator> iter1(data.begin());
    zip_iterator<vector<int>::iterator> iter2(iter1);
    zip_iterator<vector<int>::iterator> iter3 = iter1;
    BOOST_CHECK(iter2 == iter3);
}

BOOST_AUTO_TEST_CASE(EqualityComparison) {
    vector<int> data = {10, 20, 30};
    zip_iterator<vector<int>::iterator> iter1(data.begin());
    zip_iterator<vector<int>::iterator> iter2(data.begin());
    BOOST_CHECK(iter1 == iter2);
    ++iter1;
    BOOST_CHECK(iter1 != iter2);
    ++iter2;
    BOOST_CHECK(iter1 == iter2);
}

BOOST_AUTO_TEST_CASE(RvalueDereference) {
    vector<int> data = {42};
    zip_iterator<vector<int>::iterator> iter(data.begin());
    int value = std::get<0>(*iter);
    BOOST_CHECK_EQUAL(value, 42);
}

BOOST_AUTO_TEST_CASE(LvalueDereference) {
    vector<int> data = {5, 15};
    zip_iterator<vector<int>::iterator> iter(data.begin());
    BOOST_CHECK(*iter == std::make_tuple(5));
    *iter = std::make_tuple(7);
    // data is now {7, 15}
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 7);
    BOOST_CHECK_EQUAL(data[0], 7);
    *iter++ = std::make_tuple(9);
    // data is now {9, 15}
    BOOST_CHECK_EQUAL(data[0], 9);
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 15);
}

BOOST_AUTO_TEST_CASE(IncrementOperations) {
    vector<int> data = {100, 200, 300, 400};
    zip_iterator<vector<int>::iterator> iter(data.begin());
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 100);
    ++iter;
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 200);
    iter++;
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 300);
    BOOST_CHECK_EQUAL(std::get<0>(*iter++), 300);
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 400);
}

BOOST_AUTO_TEST_CASE(IterationLoop) {
    vector<int> data = {5, 10, 15, 20, 25};
    zip_iterator<vector<int>::iterator> iter(data.begin());
    zip_iterator<vector<int>::iterator> end(data.end());
    size_t index = 0;
    for (; iter != end; ++iter, ++index) {
        if (index >= data.size()) {
            BOOST_FAIL("Iterator went past the end");
            break;
        }
        BOOST_CHECK_EQUAL(std::get<0>(*iter), data[index]);
    }
}

BOOST_AUTO_TEST_CASE(SwapBehavior) {
    vector<int> data = {8, 16};
    zip_iterator<vector<int>::iterator> iterA(data.begin());
    zip_iterator<vector<int>::iterator> iterB(++data.begin());
    BOOST_CHECK_EQUAL(std::get<0>(*iterA), 8);
    BOOST_CHECK_EQUAL(std::get<0>(*iterB), 16);
    std::swap(iterA, iterB);
    BOOST_CHECK_EQUAL(std::get<0>(*iterA), 16);
    BOOST_CHECK_EQUAL(std::get<0>(*iterB), 8);
    BOOST_CHECK_EQUAL(data[0], 8);
    BOOST_CHECK_EQUAL(data[1], 16);
}
BOOST_AUTO_TEST_SUITE_END()

BOOST_AUTO_TEST_SUITE(MultiZipIteratorTests)
BOOST_AUTO_TEST_CASE(ConstructorMulti) {
    vector<int> ints = {1, 2, 3};
    vector<char> chars = {'x', 'y', 'z'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter1(ints.begin(), chars.begin());
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter2(iter1);
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter3 = iter1;
    BOOST_CHECK(iter2 == iter3);
}

BOOST_AUTO_TEST_CASE(EqualityMulti) {
    vector<int> ints = {1, 2, 3};
    vector<char> chars = {'x', 'y', 'z'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter1(ints.begin(), chars.begin());
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter2(ints.begin(), chars.begin());
    BOOST_CHECK(iter1 == iter2);
    ++iter1;
    BOOST_CHECK(iter1 != iter2);
    ++iter2;
    BOOST_CHECK(iter1 == iter2);
}

BOOST_AUTO_TEST_CASE(RvalueDerefMulti) {
    vector<int> ints = {7};
    vector<char> chars = {'m'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter(ints.begin(), chars.begin());
    int iVal = std::get<0>(*iter);
    char cVal = std::get<1>(*iter);
    BOOST_CHECK_EQUAL(iVal, 7);
    BOOST_CHECK_EQUAL(cVal, 'm');
}

BOOST_AUTO_TEST_CASE(LvalueDerefMulti) {
    vector<int> ints = {4, 8};
    vector<char> chars = {'p', 'q'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter(ints.begin(), chars.begin());
    BOOST_CHECK(*iter == std::make_tuple(4, 'p'));
    *iter = std::make_tuple(6, 'r');
    // ints: {6, 8}, chars: {'r', 'q'}
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 6);
    BOOST_CHECK_EQUAL(std::get<1>(*iter), 'r');
    BOOST_CHECK_EQUAL(ints[0], 6);
    BOOST_CHECK_EQUAL(chars[0], 'r');
    *iter++ = std::make_tuple(10, 's');
    // ints: {10, 8}, chars: {'s', 'q'}
    BOOST_CHECK_EQUAL(ints[0], 10);
    BOOST_CHECK_EQUAL(chars[0], 's');
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 8);
    BOOST_CHECK_EQUAL(std::get<1>(*iter), 'q');
}

BOOST_AUTO_TEST_CASE(IncrementMulti) {
    vector<int> ints = {11, 22, 33, 44};
    vector<char> chars = {'e', 'f', 'g', 'h'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter(ints.begin(), chars.begin());
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 11);
    BOOST_CHECK_EQUAL(std::get<1>(*iter), 'e');
    ++iter;
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 22);
    BOOST_CHECK_EQUAL(std::get<1>(*iter), 'f');
    iter++;
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 33);
    BOOST_CHECK_EQUAL(std::get<1>(*iter), 'g');
    BOOST_CHECK(*iter++ == std::make_tuple(33, 'g'));
    BOOST_CHECK_EQUAL(std::get<0>(*iter), 44);
    BOOST_CHECK_EQUAL(std::get<1>(*iter), 'h');
}

BOOST_AUTO_TEST_CASE(IterationMulti) {
    vector<int> ints = {100, 200, 300, 400};
    vector<char> chars = {'A', 'B', 'C'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iter(ints.begin(), chars.begin());
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        end(ints.end(), chars.end());
    size_t idx = 0;
    size_t minSize = min(ints.size(), chars.size());
    for (; iter != end; ++iter, ++idx) {
        if (idx >= minSize) {
            BOOST_FAIL("Iterator overflow in multi-zip loop");
            break;
        }
        BOOST_CHECK_EQUAL(std::get<0>(*iter), ints[idx]);
        BOOST_CHECK_EQUAL(std::get<1>(*iter), chars[idx]);
    }
}

BOOST_AUTO_TEST_CASE(SwapMulti) {
    vector<int> ints = {50, 60};
    vector<char> chars = {'k', 'l'};
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iterA(ints.begin(), chars.begin());
    zip_iterator<vector<int>::iterator, vector<char>::iterator>
        iterB(++ints.begin(), ++chars.begin());
    BOOST_CHECK_EQUAL(std::get<0>(*iterA), 50);
    BOOST_CHECK_EQUAL(std::get<1>(*iterA), 'k');
    BOOST_CHECK_EQUAL(std::get<0>(*iterB), 60);
    BOOST_CHECK_EQUAL(std::get<1>(*iterB), 'l');
    std::swap(iterA, iterB);
    BOOST_CHECK_EQUAL(std::get<0>(*iterA), 60);
    BOOST_CHECK_EQUAL(std::get<1>(*iterA), 'l');
    BOOST_CHECK_EQUAL(std::get<0>(*iterB), 50);
    BOOST_CHECK_EQUAL(std::get<1>(*iterB), 'k');
    BOOST_CHECK_EQUAL(ints[0], 50);
    BOOST_CHECK_EQUAL(chars[0], 'k');
    BOOST_CHECK_EQUAL(ints[1], 60);
    BOOST_CHECK_EQUAL(chars[1], 'l');
}
BOOST_AUTO_TEST_SUITE_END()

