#include "circular_buffer.hpp"
#include <iostream>

int main() {
    std::cout << "Queue" << std::endl;
    CircularQueue<int, 3> queue;
    queue.pushBack(10);
    queue.pushBack(20);
    std::cout << "Full (2/3)? " << queue.full() << std::endl;
    queue.pushBack(30);
    std::cout << "Full (3/3)? " << queue.full() << std::endl;
    std::cout << "Front (should be 10) " << queue.front() << std::endl;
    queue.popFront();
    queue.popFront();
    std::cout << "Front (should be 30) " << queue.front() << std::endl;
    std::cout << "Empty (1/3)? " << queue.empty() << std::endl;
    queue.popFront();
    std::cout << "Full (0/3)? " << queue.full() << std::endl;
    std::cout << "Empty (0/3)? " << queue.empty() << std::endl;
    std::cout << std::endl;

    CircularQueue<double, 2> queue2;
    queue2.pushBack(1.1);
    queue2.pushBack(2.2);
    queue2.popFront();
    queue2.pushBack(3.3);
    std::cout << "Front (should be 2.2) " << queue2.front() << std::endl;
    std::cout << "Capacity (2/2) " << queue2.size() << std::endl;
    queue2.popFront();
    std::cout << "Capacity (1/2) " << queue2.size() << std::endl;
    queue2.popFront();
    std::cout << "Capacity (0/2) " << queue2.size() << std::endl;
    std::cout << std::endl;

    std::cout << "Buffer" << std::endl;
    struct Record {
        double data;
        int key;
    };
    CircularBuffer<Record, &Record::key, 3> storage;
    storage.insert({1.5, 100});
    storage.insert({2.5, 200});
    std::cout << "Count is (should be 2) " << storage.size() << std::endl;
    std::cout << "Is 100 present? (should be) " << storage.has(100) << std::endl;
    std::cout << "Is 999 present? (shouldn't be) " << storage.has(999) << std::endl;
    std::cout << "What is stored under 200? (2.5) " << storage.get(200).data << std::endl;
    std::cout << "Removing entry with key 100. (1.5) " << storage.extract(100).data << std::endl;
    std::cout << "Is 100 still there? (shouldn't be) " << storage.has(100) << std::endl;
    std::cout << "Count is (should be 1) " << storage.size() << std::endl;
    std::cout << "Removing entry with key 200. (2.5) " << storage.extract(200).data << std::endl;
    std::cout << "Count is (should be 0) " << storage.size() << std::endl;
    std::cout << "Can retrieve 200 now? (shouldn't) " << bool(storage.tryGet(200)) << std::endl;
}

#include <iostream>
using namespace std;

int main() {
    int * territory1 = new int[10000], * territory2 = new int[10000];
    int rows, cols, turns, limit;

    while (cin >> rows >> cols >> limit >> turns && !(rows == 0 && cols == 0 && limit == 0 && turns == 0)) {
        // Read initial territory values
        for (int r = 0; r < rows; r++)
            for (int c = 0; c < cols; c++)
                cin >> territory1[r * 100 + c];

        // Simulate the spread process for 'turns' iterations
        for (int t = 0; t < turns; t++) {
            int * current = (t & 1 ? territory2 : territory1);
            int * next = (t & 1 ? territory1 : territory2);

            for (int r = 0; r < rows; r++) {
                for (int c = 0; c < cols; c++) {
                    int value = (current[r * 100 + c] + limit - 1) % limit;
                    int spread = 0;

                    // Check all four adjacent cells
                    if (r > 0 && current[(r-1) * 100 + c] == value) spread = 1;
                    if (c > 0 && current[r * 100 + c-1] == value) spread = 1;
                    if (r < rows - 1 && current[(r+1) * 100 + c] == value) spread = 1;
                    if (c < cols - 1 && current[r * 100 + c+1] == value) spread = 1;

                    if (spread)
                        next[r * 100 + c] = value;
                    else
                        next[r * 100 + c] = current[r * 100 + c];
                }
            }
        }

        // Output the final state
        int * result = (turns & 1 ? territory2 : territory1);
        for (int r = 0; r < rows; r++) {
            bool firstEntry = false;
            for (int c = 0; c < cols; c++) {
                if (firstEntry) cout << " ";
                else firstEntry = true;
                cout << result[r * 100 + c];
            }
            cout << "\n";
        }
    }

    delete [] territory1;
    delete [] territory2;
    return 0;
}

#include "CameraMan.h"

CameraMan::CameraMan(Camera* cam)
	: mCamera(0)
	, mTarget(0)
{
	setCamera(cam);
	setTarget(mTarget ? mTarget : mCamera->getSceneManager()->getRootSceneNode());
	mCamera->setFixedYawAxis(true);
	setYawPitchDist(Degree(0), Degree(15), 150);
}

CameraMan::~CameraMan() {}

void CameraMan::setCamera(Camera* cam) {
	mCamera = cam;
}

Camera* CameraMan::getCamera() {
	return mCamera;
}

void CameraMan::setTarget(SceneNode* target) {
	if (target != mTarget) {
		mTarget = target;
		if(target) {
			setYawPitchDist(Degree(0), Degree(15), 150);
			mCamera->setAutoTracking(true, mTarget);
		} else {
			mCamera->setAutoTracking(false);
		}
	}
}

SceneNode* CameraMan::getTarget() {
	return mTarget;
}

void CameraMan::setYawPitchDist(Radian yaw, Radian pitch, Real dist) {
	mCamera->setPosition(mTarget->_getDerivedPosition());
	mCamera->setOrientation(mTarget->_getDerivedOrientation());
	mCamera->yaw(yaw);
	mCamera->pitch(-pitch);
	mCamera->moveRelative(Ogre::Vector3(0, 0, dist));
}

void CameraMan::injectMouseMove(const MouseEvent& evt) {
	Real distance = (mCamera->getPosition() - mTarget->_getDerivedPosition()).length();

	mCamera->setPosition(mTarget->_getDerivedPosition());

	mCamera->yaw(Degree(-evt.state.X.rel * 0.25f));
	mCamera->pitch(Degree(-evt.state.Y.rel * 0.25f));
	mTarget->yaw(Degree(-evt.state.X.rel * 0.25f));

	mCamera->moveRelative(Ogre::Vector3(0, 0, distance));

	if(evt.state.Z.rel != 0) {
		mCamera->moveRelative(Ogre::Vector3(0, 0, -evt.state.Z.rel * 0.0008f * distance));
	}
}

