namespace llvm {
namespace MachO {

// Map CPU type and subtype to architecture identifier
Architecture getArchitectureFromCpuType(uint32_t cpuType, uint32_t cpuSubType) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  if (cpuType == (Type) &&                                                     \
      (cpuSubType & ~MachO::CPU_SUBTYPE_MASK) == (Subtype))                    \
    return AK_##Arch;
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  return AK_unknown;
}

// Convert string name to architecture identifier
Architecture getArchitectureFromName(StringRef archName) {
  return StringSwitch<Architecture>(archName)
#define ARCHINFO(Arch, Type, Subtype, NumBits) .Case(#Arch, AK_##Arch)
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
      .Default(AK_unknown);
}

// Get string representation of architecture
StringRef getArchitectureName(Architecture arch) {
  switch (arch) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  case AK_##Arch:                                                              \
    return #Arch;
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  case AK_unknown:
    return "unknown";
  }
  // Fallback for compilers that require explicit handling
  return "unknown";
}

// Retrieve CPU type and subtype pair from architecture
std::pair<uint32_t, uint32_t> getCPUTypeFromArchitecture(Architecture arch) {
  switch (arch) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  case AK_##Arch:                                                              \
    return std::make_pair(Type, Subtype);
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  case AK_unknown:
    return std::make_pair(0, 0);
  }
  // Compiler safety fallback
  return std::make_pair(0, 0);
}

// Derive architecture from target triple
Architecture mapToArchitecture(const Triple &targetTriple) {
  return getArchitectureFromName(targetTriple.getArchName());
}

// Check if architecture is 64-bit
bool is64Bit(Architecture arch) {
  switch (arch) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  case AK_##Arch:                                                              \
    return NumBits == 64;
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  case AK_unknown:
    return false;
  }
  llvm_unreachable("Fully handled switch case above.");
}

// Output architecture name to stream
raw_ostream &operator<<(raw_ostream &OS, Architecture arch) {
  OS << getArchitectureName(arch);
  return OS;
}

} // end namespace MachO.
} // end namespace llvm.

