Parse_HTTP_Response::Parse_HTTP_Response (const char *response_data)
  : status_code_ (200),
    status_text_ (0),
    http_major_ (0),
    http_minor_ (9),
    full_version_ (0),
    raw_response_ (0),
    parse_error_ (0)
{
  if (response_data != 0)
    this->initialize (response_data);
}

Parse_HTTP_Response::~Parse_HTTP_Response (void)
{
  if (this->raw_response_)
    ACE_OS::free (this->raw_response_);
  this->raw_response_ = 0;
  this->status_text_ = 0;
  this->full_version_ = 0;
}

void
Parse_HTTP_Response::initialize (const char *response_data)
{
  this->raw_response_ = ACE_OS::strdup (response_data);
  if (this->raw_response_ == 0)
    {
      this->parse_error_ = MEMORY_ALLOCATION_FAILED;
      return;
    }

  int parsed_fields = ::sscanf (this->raw_response_, "HTTP/%d.%d %d %*s",
                                &(this->http_major_),
                                &(this->http_minor_),
                                &(this->status_code_));
  if (parsed_fields == 3)
    {
      char *cursor = this->raw_response_;
      while (*cursor == ' ' || *cursor == '\t')
        cursor++;
      this->full_version_ = cursor++;
      while (*cursor != ' ' && *cursor != '\t')
        cursor++;
      *cursor++ = '\0';
      while (*cursor == ' ' || *cursor == '\t')
        cursor++;
      this->status_text_ = cursor;
      while (*cursor && !ACE_OS::strchr (" \t\r\n", *cursor))
        cursor++;
      *cursor++ = '\0';
    }
  else
    this->parse_error_ = INVALID_RESPONSE_FORMAT;
}
