static int lua_error_handler(lua_State *L) {
    luai_writestringerror("FATAL: unhandled exception in Lua API (%s)\n",
        lua_tostring(L, -1));
    return 0;
}

LuaInterface::LuaInterface(const char *filename, int param_count, const char * const *params)
 : script_file(filename), arg_count(param_count), arg_values(params), _state(nullptr)
{
#ifdef DEBUG
	puts("LuaInterface: Loaded " LUA_RELEASE);
#else
	errlog << "LuaInterface: Loaded " << LUA_RELEASE << std::endl;
#endif
}

LuaInterface::~LuaInterface()
{
    Cleanup();
}

void LuaInterface::Cleanup()
{
	if(_state)
	{
		lua_close(_state);
		_state = nullptr;
	}
}

void LuaInterface::CollectGarbage()
{
    lua_gc(_state, LUA_GCCOLLECT, 0);
}

unsigned int LuaInterface::GetMemoryUsage()
{
    return lua_gc(_state, LUA_GCCOUNT, 0);
}

bool LuaInterface::Initialize()
{
	if(!_state)
	{
		_state = luaL_newstate();
		if(!_state)
			return false;
		lua_atpanic(_state, lua_error_handler);
		// Initialize built-in libraries
		luaL_openlibs(_state);
		// Register custom functions
		lua_register_enginefuncs(_state);
	}
	if(luaL_loadfile(_state, script_file) != LUA_OK)
		return false;
	// Push command-line arguments onto the stack
	for(int idx = 0; idx < arg_count; ++idx)
		lua_pushstring(_state, arg_values[idx]);
	return executeCall(arg_count);
}

static std::string buildStackTrace(lua_State *L, int depth = 1)
{
    lua_Debug info;
    std::ostringstream stream;
    if (lua_getstack(L, depth, &info) && lua_getinfo(L, "Sln", &info))
    {
        stream << info.short_src << ":" << info.currentline
            << " ([" << info.what << "] "  << info.namewhat << " " << (info.name ? info.name : "(?)") << ")";
    }
    else
    {
        stream << "unknown:0";
    }
    return stream.str();
}

static void logErrorWithStack(lua_State *L, const char *message = "<no error message>")
{
	lua_Debug temp;
	std::ostringstream output;
	output << "Script Error: " << message << std::endl;
	int frame = 0;
	while(true)
	{
		int success = lua_getstack(L, frame, &temp);
		if(!success)
			break;
		output << buildStackTrace(L, frame) << "\n";
		++frame;
	}
#ifdef DEBUG
	printf("%s\n", output.str().c_str());
#else
	errlog << output.str() << std::endl;
#endif
}

void LuaInterface::findFunction(const char *name)
{
    lua_getglobal(_state, name);
}

bool LuaInterface::executeCall(int numArgs, int numResults /* = 0 */)
{
    if(lua_pcall(_state, numArgs, numResults, 0) != LUA_OK)
    {
        logErrorWithStack(_state, getCStr(_state, -1));
        lua_pop(_state, 1);
        return false;
    }
    return true;
}

bool LuaInterface::run(const char *funcName)
{
    findFunction(funcName);
    return executeCall(0);
}

bool LuaInterface::run(const char *funcName, const char *arg1)
{
	findFunction(funcName);
	lua_pushstring(_state, arg1);
	return executeCall(1);
}

