namespace llvm {

// Constructor for DwarfFile
DwarfFile::DwarfFile(AsmPrinter *AP, DwarfDebug &DD, StringRef Pref,
                     BumpPtrAllocator &DA)
    : Asm(AP), DD(DD), StrPool(DA, *Asm, Pref) {}

// Destructor
DwarfFile::~DwarfFile() {}

// Assign a unique abbreviation identifier to the given DIEAbbrev.
void DwarfFile::assignAbbrevNumber(DIEAbbrev &Abbrev) {
  // Insert or retrieve existing node in the set.
  DIEAbbrev *Existing = AbbreviationsSet.GetOrInsertNode(&Abbrev);

  if (Existing == &Abbrev) {
    // New abbreviation: add to list and assign new number.
    Abbreviations.emplace_back(&Abbrev);
    Abbrev.setNumber(Abbreviations.size());
  } else {
    // Reuse existing abbreviation's number.
    Abbrev.setNumber(Existing->getNumber());
  }
}

// Add a compile unit to the list.
void DwarfFile::addUnit(std::unique_ptr<DwarfUnit> U) {
  CUs.push_back(std::move(U));
}

// Emit all units into their respective sections.
void DwarfFile::emitUnits(const MCSymbol *ASectionSym) {
  for (auto &CU : CUs) {
    DIE &RootDie = CU->getUnitDie();
    const MCSection *UnitSec = CU->getSection();

    Asm->OutStreamer.SwitchSection(UnitSec);
    CU->emitHeader(ASectionSym);
    DD.emitDIE(RootDie);
  }
}

// Compute sizes and offsets for all DIEs across all CUs.
void DwarfFile::computeSizeAndOffsets() {
  unsigned GlobalOffset = 0;

  for (auto &CU : CUs) {
    CU->setDebugInfoOffset(GlobalOffset);

    // Start offset after length field and header.
    unsigned LocalOffset = sizeof(int32_t) + CU->getHeaderSize();

    unsigned FinalOffset = computeSizeAndOffset(CU->getUnitDie(), LocalOffset);
    GlobalOffset += FinalOffset;
  }
}

// Recursively compute size and offset for a single DIE.
unsigned DwarfFile::computeSizeAndOffset(DIE &Die, unsigned Offset) {
  // Register abbreviation.
  assignAbbrevNumber(Die.getAbbrev());

  const DIEAbbrev &Abbr = Die.getAbbrev();
  Die.setOffset(Offset);

  // Account for abbreviation code size.
  Offset += getULEB128Size(Die.getAbbrevNumber());

  const auto &Attrs = Die.getValues();
  const auto &AbbrAttrs = Abbr.getData();

  // Process each attribute.
  for (size_t Idx = 0; Idx < Attrs.size(); ++Idx)
    Offset += Attrs[Idx]->SizeOf(Asm, AbbrAttrs[Idx].getForm());

  // Handle children recursively.
  const auto &Kids = Die.getChildren();
  if (!Kids.empty()) {
    assert(Abbr.hasChildren() && "Expected children flag");

    for (auto &Kid : Kids)
      Offset = computeSizeAndOffset(*Kid, Offset);

    // End-of-children marker.
    Offset += sizeof(int8_t);
  }

  Die.setSize(Offset - Die.getOffset());
  return Offset;
}

// Emit all abbreviations into the debug_abbrev section.
void DwarfFile::emitAbbrevs(const MCSection *Section) {
  if (!Abbreviations.empty()) {
    Asm->OutStreamer.SwitchSection(Section);

    for (const DIEAbbrev *Abbr : Abbreviations) {
      Asm->EmitULEB128(Abbr->getNumber(), "Abbrev Code");
      Abbr->Emit(Asm);
    }

    Asm->EmitULEB128(0, "End of Abbreviations");
  }
}

// Emit string pool entries.
void DwarfFile::emitStrings(const MCSection *StrSec,
                            const MCSection *OffSec) {
  StrPool.emit(*Asm, StrSec, OffSec);
}

// Insert a variable into the scope map, maintaining parameter order.
void DwarfFile::addScopeVariable(LexicalScope *LS, DbgVariable *Var) {
  auto &Vars = ScopeVariables[LS];
  DIVariable DV = Var->getVariable();

  if (unsigned ArgNum = DV.getArgNumber()) {
    // Insert parameters at front, sorted by arg number.
    auto It = Vars.begin();
    while (It != Vars.end()) {
      unsigned CurArg = (*It)->getVariable().getArgNumber();
      if (CurArg == 0 || CurArg > ArgNum)
        break;
      assert(CurArg != ArgNum && "Duplicate parameter detected");
      ++It;
    }
    Vars.insert(It, Var);
    return;
  }

  // Non-parameter locals go at end.
  Vars.push_back(Var);
}

