#include <utils/LogDefines.h>
#include <string>     // std::string, std::stoul, std::getline

using json = nlohmann::json;

int main(int argc, char *args[])
{
  using namespace httplib;
  Server app;

  // Validate command-line arguments
  if (argc < 3) {
    std::cerr << "Usage: " << args[0] << " <BIND_ADDRESS> <SERVER_PORT>" << std::endl;
    return 1;
  }

  char* bindAddr = args[1];
  uint32_t serverPort = std::stoul(args[2]);

  LOG_INF("Starting HTTP server on %s:%u", bindAddr, serverPort);

  // Simple health check endpoint
  app.Get("/hi", [](const httplib::Request &, httplib::Response &response) {
    response.set_content("Hello World!", "text/plain");
  });

  // Configuration endpoint
  app.Post("/configure", [](const Request& request, Response& response) {
    json incoming = json::parse(request.body);
    json reply;
    response.status = Controller::setup(incoming, reply);
    response.set_content("{\"status\": \"configured\"}", "application/json");
  });

  // Session creation endpoint
  app.Post("/createSession", [](const Request &request, Response &response) {
    json input = json::parse(request.body);
    json output;
    response.status = Controller::createSesssion(input, output);
    response.set_content("{\"session\": \"created\"}", "application/json");
  });

  // Start listening for incoming requests
  app.listen(bindAddr, serverPort);
}

#include "clang/Basic/SourceMgrAdapter.h"
#include "clang/Basic/Diagnostic.h"
using namespace clang;

void SourceMgrAdapter::handleDiag(const llvm::SMDiagnostic &diag,
                                  void *context) {
  static_cast<SourceMgrAdapter *>(context)->processDiagnostic(diag);
}

SourceMgrAdapter::SourceMgrAdapter(SourceManager &srcManager,
                                   DiagnosticsEngine &diagEngine,
                                   unsigned errorID,
                                   unsigned warningID,
                                   unsigned noteID,
                                   const FileEntry *initialFile)
  : SrcMgr(srcManager), Diag(diagEngine), ErrorDiagID(errorID),
    WarningDiagID(warningID), NoteDiagID(noteID),
    DefaultFile(initialFile) { }

SourceMgrAdapter::~SourceMgrAdapter() { }

SourceLocation SourceMgrAdapter::mapLocation(const llvm::SourceMgr &llvmSrcManager,
                                             llvm::SMLoc position) {
  // Handle invalid source locations
  if (!position.isValid())
    return SourceLocation();

  // Locate the buffer that contains this position
  unsigned bufferIdx = llvmSrcManager.FindBufferContainingLoc(position);
  if (!bufferIdx)
    return SourceLocation();

  // Retrieve the memory buffer
  auto buffer = llvmSrcManager.getMemoryBuffer(bufferIdx);

  // Check if we've already processed this buffer
  auto knownEntry = FileIDMapping.find(std::make_pair(&llvmSrcManager, bufferIdx));
  if (knownEntry == FileIDMapping.end()) {
    FileID fileID;

    if (DefaultFile) {
      // Assign to the default file
      fileID = SrcMgr.createFileID(DefaultFile, SourceLocation(),
                                   SrcMgr::C_User);
      // Ensure default file is only used once
      DefaultFile = nullptr;
    } else {
      // Duplicate the memory buffer content
      StringRef bufferName = buffer->getBufferIdentifier();
      auto bufferCopy
        = std::unique_ptr<llvm::MemoryBuffer>(
            llvm::MemoryBuffer::getMemBufferCopy(buffer->getBuffer(),
                                                 bufferName));
      // Register the new buffer with Clang's source manager
      fileID = SrcMgr.createFileID(std::move(bufferCopy));
    }

    // Record the mapping for future use
    knownEntry = FileIDMapping.insert(
                    std::make_pair(std::make_pair(&llvmSrcManager, bufferIdx),
                                   fileID)).first;
  }

  // Compute byte offset within the file
  unsigned offset = position.getPointer() - buffer->getBufferStart();
  return SrcMgr.getLocForStartOfFile(knownEntry->second)
           .getLocWithOffset(offset);
}

SourceRange SourceMgrAdapter::mapRange(const llvm::SourceMgr &llvmSrcManager,
                                       llvm::SMRange span) {
  if (!span.isValid())
    return SourceRange();

  SourceLocation begin = mapLocation(llvmSrcManager, span.Start);
  SourceLocation finish = mapLocation(llvmSrcManager, span.End);
  return SourceRange(begin, finish);
}

void SourceMgrAdapter::processDiagnostic(const llvm::SMDiagnostic &diag) {
  // Convert the diagnostic location
  SourceLocation loc;
  if (auto *llvmSrcManager = diag.getSourceMgr())
    loc = mapLocation(*llvmSrcManager, diag.getLoc());

  // Extract diagnostic message text
  StringRef msg = diag.getMessage();

  // Determine diagnostic severity level
  unsigned diagID;
  switch (diag.getKind()) {
  case llvm::SourceMgr::DK_Error:
    diagID = ErrorDiagID;
    break;
  case llvm::SourceMgr::DK_Warning:
    diagID = WarningDiagID;
    break;
  case llvm::SourceMgr::DK_Note:
    diagID = NoteDiagID;
    break;
  default:
    diagID = NoteDiagID;
    break;
  }

  // Emit the diagnostic through Clang's engine
  DiagnosticBuilder builder = Diag.Report(loc, diagID) << msg;

  if (auto *llvmSrcManager = diag.getSourceMgr()) {
    // Map source ranges relative to line start
    SourceLocation lineStart = loc.getLocWithOffset(-diag.getColumnNo());
    for (auto range : diag.getRanges()) {
      builder << SourceRange(lineStart.getLocWithOffset(range.first),
                             lineStart.getLocWithOffset(range.second));
    }

    // Apply fix-it hints
    for (const llvm::SMFixIt &fix : diag.getFixIts()) {
      CharSourceRange range(mapRange(*llvmSrcManager, fix.getRange()), false);
      builder << FixItHint::CreateReplacement(range, fix.getText());
    }
  }
}

#include <iostream>
