constexpr const char* sUsage = "<142N> <283Q> ... [options]\n";

struct PositionAminoAcid
{
    PositionAminoAcid(size_t position, char amino_acid) : pos(position), aa(amino_acid) {}
    size_t pos;
    char aa;
};

inline std::ostream& operator << (std::ostream& out, const PositionAminoAcid& paa)
{
    return out << paa.pos << paa.aa;
}

int main(int argc, char* const argv[])
{
    try {
        argc_argv parameters(argc, argv,
                             {
                                 {"--db-dir", ""},
                                 {"-v", false},
                                 {"--verbose", false},
                                 {"-h", false},
                                 {"--help", false},
                             });
        if (parameters["-h"] || parameters["--help"] || parameters.number_of_arguments() < 1) {
            throw std::runtime_error("Usage: "s + parameters.program() + sUsage + parameters.usage_options());
        }
        const bool verbose_mode = parameters["-v"] || parameters["--verbose"];
        seqdb::setup_dbs(parameters["--db-dir"].str(), verbose_mode ? seqdb::report::yes : seqdb::report::no);
        const auto& database = seqdb::get();
        std::vector<PositionAminoAcid> positions_and_aa;
        for (size_t index = 0; index < parameters.number_of_arguments(); ++index) {
            const std::string argument(parameters[index]);
            positions_and_aa.emplace_back(std::strtoul(argument.c_str(), nullptr, 10), std::toupper(argument[argument.size() - 1]));
        }
        // std::cout << positions_and_aa << '\n';
        for (const auto sequence_entry : database) {
            try {
                const auto aa_sequence = sequence_entry.seq().amino_acids(true);
                if (all_of(positions_and_aa.begin(), positions_and_aa.end(), [&aa_sequence](const auto& entry) -> bool { return aa_sequence[entry.pos - 1] == entry.aa; }))
                    std::cout << sequence_entry.make_name() << '\n';
            }
            catch (seqdb::SequenceNotAligned&) {
            }
        }
        return 0;
    }
    catch (std::exception& error) {
        std::cerr << "ERROR: " << error.what() << '\n';
        return 1;
    }
}
