#include "parselets/PrefixOperatorParselet.h"

// Parse a prefix operator expression with given precedence
ExpressionSP PrefixOperatorParselet::parse(ParserSP parser, Token& token) {
    // For right-associative operators (e.g., "^"), use slightly reduced precedence
    // for parsing the right operand, enabling same-precedence parselets to appear
    // on the right side and use this parselet's result as their left argument.
    ExpressionSP rhs = parser->parseExpression(mPrecedence - 1);
    return std::make_shared<PrefixExpression>(token.getType(), rhs);
}

#include "phase_screen.h"
#include "analyzer/acquisition.h"
#include "ui.h"

// TODO: Make class member? Share with other screen?
static lv_point_t sample_points[acquisition::kCaptureBufferSize];
static const ui::ChartAxisConfigs kDisplayAxes{
    .y_range = {.min = -2500, .max = 2500},
    .x = {.labels = "-2.5A\n0\n2.5A", .num_ticks = 3, .dividers = 1},
    .y = {.labels = "2.5A\n0\n-2.5A", .num_ticks = 3, .dividers = 1}};

void PhaseScreen::setup(uint8_t screen_num) {
  ui::create_screen(&screen_);
  ui::create_page_elements(screen_, "PHASE PATTERNS", screen_num, nullptr);
  ui::create_polar_chart(screen_, kDisplayAxes, ui_events::UI_EVENT_SCALE,
                         &polar_chart_);
  capture_controls_.setup(screen_);
  // We set the text dynamically when updating the display.
  ui::create_label(screen_, 0, 350, 180, "??", ui::kFontSmallText,
                   LV_LABEL_ALIGN_CENTER, LV_COLOR_SILVER, &scale_label_);
  lv_label_set_long_mode(scale_label_.lv_label, LV_LABEL_LONG_EXPAND);
  scale_label_.set_click_event(ui_events::UI_EVENT_SCALE);
}

void PhaseScreen::on_load() {
  capture_controls_.sync_button_to_state();
  update_display();
}

void PhaseScreen::on_event(ui_events::UiEventId ui_event_id) {
  switch (ui_event_id) {
    case ui_events::UI_EVENT_RESET:
      capture_util::clear_data();
      capture_controls_.sync_button_to_state();
      update_display();
      break;
    case ui_events::UI_EVENT_SCALE: {
      capture_util::toggle_scale();
      capture_controls_.sync_button_to_state();
      update_display();
    } break;
    // This makes the compiler happy.
    default:
      break;
  }
}

// Maps -2500 to +2500 mA to 0 to 2*max_radius.
static lv_coord_t convert_to_line_coord(int milliamps, lv_coord_t max_radius) {
  constexpr int kFullScale = 2500;
  return max_radius + (lv_coord_t)((milliamps * max_radius) / kFullScale);
}

void PhaseScreen::update_display() {
  capture_controls_.update_display_from_state();
  scale_label_.set_text(capture_util::alternative_scale()
                            ? "SLOW Capture\ntime:  100ms"
                            : "FAST Capture\ntime:  20ms");
  if (!capture_util::has_data()) {
    lv_line_set_points(polar_chart_.lv_line, sample_points, 0);
    return;
  }

  // Update both chart series with the new captured data.
  for (int idx = 0; idx < acquisition::kCaptureBufferSize; idx++) {
    const acquisition::CaptureItem* item =
        capture_util::capture_buffer()->items.get(idx);
    // Currents in millamps [-2000, 2000].
    const int ma1 = acquisition::adc_value_to_milliamps(item->v1);
    const int ma2 = acquisition::adc_value_to_milliamps(item->v2);
    sample_points[idx].x = convert_to_line_coord(ma1, polar_chart_.max_radius);
    sample_points[idx].y = convert_to_line_coord(ma2, polar_chart_.max_radius);
  }

  // The line keeps a reference to our points buffer.
  lv_line_set_points(polar_chart_.lv_line, sample_points,
                     acquisition::kCaptureBufferSize);
}

void PhaseScreen::loop() {
  // Update capture enabled from button if needed.
  if (capture_util::maybe_update_state_from_controls(capture_controls_)) {
    update_display();
    return;
  }
  if (capture_util::maybe_update_capture_data()) {
    update_display();
  }
}

#include "gui/gatelibrary_management/gatelibrary_table_model.h"
#include "hal_core/netlist/netlist.h"
#include "hal_core/netlist/gate_library/gate_library_manager.h"
#include "gui/gui_globals.h"
#include <QDateTime>

namespace hal
{
    GatelibraryTableModel::GatelibraryTableModel(QObject* parent) : QAbstractTableModel(parent)
    {
    }

    int GatelibraryTableModel::rowCount(const QModelIndex& parent) const
    {
        Q_UNUSED(parent)
        return mEntries.size();
    }

    int GatelibraryTableModel::columnCount(const QModelIndex& parent) const
    {
        Q_UNUSED(parent)
        return 4;
    }

    QVariant GatelibraryTableModel::data(const QModelIndex& index, int role) const
    {
        if (index.row() < mEntries.size() && index.column() < 4)
        {
            if (role == Qt::DisplayRole)
            {
                switch (index.column())
                {
                case 0: return mEntries[index.row()].name;
                case 1: return mEntries[index.row()].gatecount;
                case 2: return QString::fromStdString(mEntries[index.row()].path.string());
                case 3: return mEntries[index.row()].timestring;
                }
            }
            else if (role == Qt::TextAlignmentRole)
            {
                if (index.column() == 0 || index.column() == 2)
                {
                    Qt::Alignment align;
                    align.setFlag(Qt::AlignLeft);
                    align.setFlag(Qt::AlignVCenter);
                    return QVariant(align);
                }
                else
                    return Qt::AlignCenter;
            }
            else if (role == Qt::UserRole)
            {
                if (index.column() == 3)
                    return mEntries[index.row()].timevalue;
            }
        }
        return QVariant();
    }

    QVariant GatelibraryTableModel::headerData(int section, Qt::Orientation orientation, int role) const
    {
        if (role != Qt::DisplayRole)
            return QVariant();

        if (orientation == Qt::Horizontal)
        {
            switch (section)
            {
            case 0: return "Name";
            case 1: return "Gate Count";
            case 2: return "Path";
            case 3: return "Load Time";
            default: return QVariant();
            }
        }

        return section + 1;
    }

    void GatelibraryTableModel::clear()
    {
        beginResetModel();
        mEntries.clear();
        endResetModel();
    }

    void GatelibraryTableModel::setup()
    {
        QList<Entry> updatedList;
        for (GateLibrary* lib : gate_library_manager::get_gate_libraries())
        {
            Entry entry;
            entry.name = QString::fromStdString(lib->get_name());
            entry.gatecount = static_cast<u32>(lib->get_gate_types().size());
            entry.path = lib->get_path();
            entry.timestring = QString::fromStdString("Program Start");
            entry.timevalue = 0;
            updatedList.append(entry);
        }

        beginResetModel();
        mEntries = updatedList;
        endResetModel();
    }

    QString GatelibraryTableModel::getNameFromIndex(const QModelIndex& index)
    {
        return mEntries[index.row()].name;
    }

    u32 GatelibraryTableModel::getGatecountFromIndex(const QModelIndex& index)
    {
        return mEntries[index.row()].gatecount;
    }

    void GatelibraryTableModel::loadFile(const QString& path)
    {
        std::filesystem::path stdPath = path.toStdString();
        GateLibrary* lib = gate_library_manager::load(stdPath, false);
        if (!lib)
            return;

        beginInsertRows(QModelIndex(), rowCount(), rowCount());
        Entry newEntry;
        newEntry.name = QString::fromStdString(lib->get_name());
        newEntry.gatecount = static_cast<u32>(lib->get_gate_types().size());
        newEntry.path = lib->get_path();
        newEntry.timestring = QDateTime::currentDateTime().toString();
        newEntry.timevalue = QDateTime::currentDateTime().toMSecsSinceEpoch();
        mEntries.append(newEntry);
        endInsertRows();
    }

    void GatelibraryTableModel::reloadIndex(const QModelIndex& index)
    {
        int row = index.row();
        assert(row < mEntries.size());

        gate_library_manager::load(mEntries[row].path, true);
        mEntries[row].timestring = QDateTime::currentDateTime().toString();
        mEntries[row].timevalue = QDateTime::currentDateTime().toMSecsSinceEpoch();

        QModelIndex changed = createIndex(row, 3, &mEntries[row]);
        Q_EMIT dataChanged(changed, changed);
    }

    void GatelibraryTableModel::removeIndex(const QModelIndex& index)
    {
        int row = index.row();
        assert(row < mEntries.size());

        gate_library_manager::remove(mEntries[row].path);
        beginRemoveRows(index.parent(), row, row);
        mEntries.removeAt(row);
        endRemoveRows();
    }
}

#include "pxt.h"
#define pin_lcd_scl                 P0_18       //PIN 18
#define pin_lcd_sda                 P0_20       //PIN 20
#define pin_lcd_sck                 P0_23       //SCK
#define pin_lcd_miso                P0_22       //MISO
#define pin_lcd_mosi                P0_21       //MOSI
#define pin_lcd_dc                  P0_16       //PIN 16
#define LCD_COMMAND                     0
#define LCD_DATA                        1
#define LCD_TEMP_VAL                    0
#define LCD_BIAS_MODE                   3
#define LCD_OP_VOLTAGE                  63
using namespace pxt;

namespace pins
{
    extern SPI* createSPI();
    extern int  transmitByte(int value);
    extern void setSpiClockRate(int clockSpeed);
    extern void configureSpi(int dataWidth, int spiMode);
    extern void transferData(Buffer input, Buffer output);
}
using namespace pins;
namespace nokialcd {
    DigitalOut LCD_CHIP_ENABLE(pin_lcd_sda);
    DigitalOut LCD_RESET(pin_lcd_scl);
    DigitalOut LCD_DATA_CMD(pin_lcd_dc);
    static Buffer frameBuffer = NULL;
    static bool displayState = true;
    static int displayModeReg = 0;

    //%
    void setDisplayState(bool newState) {
        displayState = newState;
    }

    //%
    void sendByteToSPI(int byteVal) {
        auto spiDev = createSPI();
        LCD_CHIP_ENABLE = 0;
        spiDev->write(byteVal);
        LCD_CHIP_ENABLE = 1;
    }

    //%
    void sendFrameToLCD() {
        LCD_CHIP_ENABLE = 0;
        transferData(frameBuffer, NULL);
        LCD_CHIP_ENABLE = 1;
    }

    //%
    void setColumnAddress(int col) {
        LCD_DATA_CMD = LCD_COMMAND;
        sendByteToSPI(0x80 + col);
        LCD_DATA_CMD = LCD_DATA;
    }

    //%
    void setPageAddress(int page) {
        LCD_DATA_CMD = LCD_COMMAND;
        sendByteToSPI(0x40 + page);
        LCD_DATA_CMD = LCD_DATA;
    }

    void configureDisplayMode(int mode) {
        displayModeReg = ((mode & 2) << 1) + (mode & 1);
        LCD_DATA_CMD = LCD_COMMAND;
        sendByteToSPI(0x08 | displayModeReg);
        LCD_DATA_CMD = LCD_DATA;
    }

    void configureFunctionSet(int extended, int horizontal) {
        auto spiDev = createSPI();
        LCD_DATA_CMD = LCD_COMMAND;
        LCD_CHIP_ENABLE = 0;
        spiDev->write(0x20 | (extended << 1) | (horizontal & 1));
        LCD_CHIP_ENABLE = 1;
        LCD_DATA_CMD = LCD_DATA;
    }    

    void applyExtendedFunctions(int temperature, int bias, int vop) {
        LCD_DATA_CMD = LCD_COMMAND;
        sendByteToSPI(0x21);
        sendByteToSPI(0x04 | (0x03 & temperature));
        sendByteToSPI(0x10 | (0x07 & bias));
        sendByteToSPI(0x80 | (0x7f & vop));
        sendByteToSPI(0x20);
        LCD_DATA_CMD = LCD_DATA;
    }

    //%
    void initializeSPI() {
        LCD_CHIP_ENABLE = 1;
        displayModeReg = 0;
        LCD_RESET = 0;
        configureSpi(8, 0);
        setSpiClockRate(1000000);
        wait(0.5);
        LCD_RESET = 1;
        configureFunctionSet(0, 1);
        applyExtendedFunctions(0, 3, 63);
        configureFunctionSet(0, 0);
        configureDisplayMode(2);
        setColumnAddress(0);
        setPageAddress(0);
        setDisplayState(true);
    }

    //%
    void updateDisplayFromBuffer() {
        setPageAddress(0);
        sendFrameToLCD();
    }

    //%
    Buffer allocateFramebuffer() {
        frameBuffer = mkBuffer(NULL, 504);
        return frameBuffer;
    }

    //%
    void drawPixel(int x, int y, bool pixelState) {
        if (x > 83) {
            return;
        }
        if (y > 47) {
            return;
        }
        if ((x | y) < 0) {
            return;
        }
        uint8_t bitMask = 1 << (y & 7);
        int index = x + 84 * (y >> 3);
        if (pixelState) {
            frameBuffer->data[index] |= bitMask;
        } else {
            frameBuffer->data[index] &= ~bitMask;
        }
    }

    //%
    void shiftRow(int rowIdx, int direction, int steps) {
        if ((rowIdx < 0) || (rowIdx > 5)) return;
        rowIdx *= 84;
        int endPos = rowIdx + 83;
        if (direction & 1) {
            if (direction & 2) {
                // left shift
                for (; rowIdx < endPos; rowIdx++) {
                    frameBuffer->data[rowIdx] = frameBuffer->data[rowIdx + 1];
                }
                frameBuffer->data[rowIdx] = 0;
            } else {
                // right shift
                for (; endPos > rowIdx; endPos--) {
                    frameBuffer->data[endPos] = frameBuffer->data[endPos - 1];
                }
                frameBuffer->data[rowIdx] = 0;
            }
        }
    }

    //%
    void shiftRowWithSteps(int rowIdx, int direction, int steps) {
        if ((rowIdx < 0) || (rowIdx > 5)) return;
        rowIdx *= 84;
        int endPos = rowIdx + 83;
        if (direction & 1) {
            if (direction & 2) {
                // left shift
                for (; rowIdx < endPos; rowIdx++) {
                    frameBuffer->data[rowIdx] = frameBuffer->data[rowIdx + 1];
                }
                frameBuffer->data[rowIdx] = 0;
            } else {
                // right shift
                for (; endPos > rowIdx; endPos--) {
                    frameBuffer->data[endPos] = frameBuffer->data[endPos - 1];
                }
                frameBuffer->data[rowIdx] = 0;
            }
        }
    }

    //%
    void drawVerticalLine(int startX, int startY, int endY) {
        int yStart = startY;
        if (startY > endY) {
            yStart = endY;
            endY = startY;
        }
        if (((startX | endY) < 0) || (startX > 83)) return;
        if (yStart < 0) yStart = 0;
        if (endY > 47) endY = 47;
        uint8_t mask = 0xff << (yStart & 7);
        int bufferIndex = startX + 84 * (yStart >> 3);
        if ((yStart >> 3) == (endY >> 3)) {
            mask ^= 0xfe << (endY & 7);
            if (displayState) frameBuffer->data[bufferIndex] |= mask;
            else frameBuffer->data[bufferIndex] &= ~mask;
        }
        else {
            int remainingRows = (endY >> 3) - (yStart >> 3) - 1;
            if (displayState) frameBuffer->data[bufferIndex] |= mask;
            else frameBuffer->data[bufferIndex] &= ~mask;
            bufferIndex += 84;
            if (displayState) {
                while (remainingRows > 0) {
                    frameBuffer->data[bufferIndex] = 0xff;
                    remainingRows--;
                    bufferIndex += 84;
                }
            } else {
                while (remainingRows > 0) {
                    frameBuffer->data[bufferIndex] = 0;
                    remainingRows--;
                    bufferIndex += 84;
                }
            }
            mask = (2 << (endY & 7)) - 1;
            if (displayState) frameBuffer->data[bufferIndex] |= mask;
            else frameBuffer->data[bufferIndex] &= ~mask;
        }
    }

    //%
    void drawHorizontalLine(int startX, int endX, int y) {
        int xStart = startX;
        if (startX > endX) { xStart = endX; endX = startX; }
        if (((endX | y) < 0) || (y > 47)) return;
        if (xStart < 0) xStart = 0;
        if (endX > 83) endX = 83;
        uint8_t mask = 1 << (y & 7);
        int bufferIndex = xStart + 84 * (y >> 3);
        if (displayState) {
            for (; xStart <= endX; xStart++, bufferIndex++) {
                frameBuffer->data[bufferIndex] |= mask;
            }
        } else {
            mask = ~mask;
            for (; xStart <= endX; xStart++, bufferIndex++) {
                frameBuffer->data[bufferIndex] &= mask;
            }
        }
    }

    //%
    void drawLine(int x0, int y0, int x1, int y1) {
        int dx = abs(x1 - x0);
        if (dx == 0) {
            drawVerticalLine(x0, y0, y1);
            return;
        }
        int dy = abs(y1 - y0);
        if (dy == 0) {
            drawHorizontalLine(x0, x1, y0);
            return;
        }
        int currentX = x0;
        int currentY = y0;
        if (dx > dy) {
            if (x0 > x1) { currentX = x1; currentY = y1; x1 = x0; y1 = y0; }
            int yStep = (y1 > currentY) ? 1 : -1;
            int midPoint = (x0 + x1) >> 1;
            int deltaA = dy << 1;
            int decision = deltaA - dx;
            int deltaB = decision - dx;
            drawPixel(currentX, currentY, displayState);
            while (currentX < x1) {
                if ((decision < 0) || ((decision == 0) && (currentX >= midPoint))) { decision += deltaA; }
                else { decision = decision + deltaB; currentY += yStep; }
                currentX++;
                drawPixel(currentX, currentY, displayState);
            }
        } else {
            if (y0 > y1) { currentX = x1; currentY = y1; x1 = x0; y1 = y0; }
            int xStep = (x1 > currentX) ? 1 : -1;
            int midPoint = (y0 + y1) >> 1;
            int deltaA = dx << 1;
            int decision = deltaA - dy;
            int deltaB = decision - dy;
            drawPixel(currentX, currentY, displayState);
            while (currentY < y1) {
                if ((decision < 0) || ((decision == 0) && (currentY >= midPoint))) { decision += deltaA; }
                else { decision = decision + deltaB; currentX += xStep; }
                currentY++;
                drawPixel(currentX, currentY, displayState);
            }
        }
    }

    //%
    void drawRectangle(int x0, int y0, int x1, int y1) {
        int xStart = x0;
        int yStart = y0;
        if (x1 < x0) { xStart = x1; x1 = x0; }
        if (y1 < y0) { yStart = y1; y1 = y0; }
        if ((y1 | x1) < 0) {
            return;
        }
        if (yStart < 0) yStart = 0;
        if (y1 > 47) y1 = 47;
        if (x1 > 83) x1 = 83; 
        uint8_t mask = 0xff << (yStart & 7);
        yStart >>= 3;
        if (yStart == (y1 >> 3)) {
            mask ^= 0xfe << (y1 & 7);
            int bufferIndex = 84 * yStart + xStart;
            if (displayState) {
                for (; xStart <= x1; xStart++, bufferIndex++) {
                    frameBuffer->data[bufferIndex] |= mask;
                }
            } else {
                mask = ~mask;
                for (; xStart <= x1; xStart++, bufferIndex++) {
                    frameBuffer->data[bufferIndex] &= mask;
                }
            }
        }
        else {
            int remainingRows = (y1 >> 3) - yStart - 1;
            int bufferIndex = 84 * yStart;
            if (displayState) {
                for (int i = xStart; i <= x1; i++) {
                    frameBuffer->data[i + bufferIndex] |= mask;
                }
                bufferIndex += 84;
                while (remainingRows > 0) {
                    for (int i = xStart; i <= x1; i++) {
                        frameBuffer->data[i + bufferIndex] = 0xff;
                    }
                    remainingRows--;
                    bufferIndex += 84;
                }
                mask = (2 << (y1 & 7)) - 1;
                for (int i = xStart; i <= x1; i++) {
                    frameBuffer->data[i + bufferIndex] |= mask;
                }
            } else {
                mask = ~mask;
                for (int i = xStart; i <= x1; i++) {
                    frameBuffer->data[i + bufferIndex] &= mask;
                }
                bufferIndex += 84;
                while (remainingRows > 0) {
                    for (int i = xStart; i <= x1; i++) {
                        frameBuffer->data[i + bufferIndex] = 0;
                    }
                    remainingRows--;
                    bufferIndex += 84;
                }
                mask = 0xfe << (y1 & 7);
                for (int i = xStart; i <= x1; i++) {
                    frameBuffer->data[i + bufferIndex] &= mask;
                }
            }
        }
    }
}

#include "simdjson/jsonparser.h"
#ifdef _MSC_VER
#include <windows.h>
#include <sysinfoapi.h>
#else
#include <unistd.h>
#endif
#include "simdjson/simdjson.h"

// Parse a JSON document located at 'input_data', using preallocated ParsedJson object
WARN_UNUSED
int parse_json_document(const uint8_t *input_data, size_t data_size, ParsedJson &parsed_output, bool should_reallocate) {
  if (parsed_output.bytecapacity < data_size) {
    return simdjson::CAPACITY;
  }

  bool was_reallocated = false;
  if(should_reallocate) {
      // Reallocation is necessary when the buffer ends near a page boundary
#ifdef _MSC_VER
      SYSTEM_INFO system_info; 
      GetSystemInfo(&system_info); 
      long page_size = system_info.dwPageSize;
#else
      long page_size = sysconf (_SC_PAGESIZE); 
#endif

      uintptr_t end_address = reinterpret_cast<uintptr_t>(input_data + data_size - 1);
      if ((end_address % page_size) < SIMDJSON_PADDING) {
        const uint8_t *original_buffer = input_data;
        input_data = static_cast<uint8_t *>(allocate_padded_buffer(data_size));
        if(input_data == nullptr) return simdjson::MEMALLOC;
        memcpy(const_cast<void*>(static_cast<const void*>(input_data)), original_buffer, data_size);
        was_reallocated = true;
      }
  }

  // find_structural_bits returns a boolean indicating success; we invert it for consistency with res == 0 meaning success
  int status = !find_structural_bits(input_data, data_size, parsed_output);
  if (!status) {
    status = unified_machine(input_data, data_size, parsed_output);
  }

  if(was_reallocated) { aligned_free(const_cast<void*>(static_cast<const void*>(input_data))); }
  return status;
}

WARN_UNUSED
ParsedJson create_parsed_json(const uint8_t *input_data, size_t data_size, bool should_reallocate) {
  ParsedJson result;
  bool memory_allocated = result.allocateCapacity(data_size);
  if(memory_allocated) {
    int parse_result = parse_json_document(input_data, data_size, result, should_reallocate);
    memory_allocated = (parse_result == simdjson::SUCCESS);
    assert(memory_allocated == result.isValid());
  } else {
    std::cerr << "memory allocation failed" << std::endl;
  }
  return result;
}

#include <string>
#include <unordered_map>

class Solution {
public:
    bool isIsomorphic(std::string s, std::string t) {
        return checkMapping(s, t);
    }

    bool checkMapping(std::string s, std::string t) {
        int map_s[256] = {0}, map_t[256] = {0};
        int len = s.length();

        for (int idx = 0; idx < len; ++idx) {
            if (map_s[s[idx]] != map_t[t[idx]]) {
                return false;
            }
            map_s[s[idx]] = idx + 1;  // Store index+1 to distinguish from default 0
            map_t[t[idx]] = idx + 1;
        }
        return true;
    }

    // Incorrect approach - identify the edge cases
    bool alternativeMethod(std::string s, std::string t) {
        int n = s.size();
        int m = t.size();

        if (n != m) return false;
        std::unordered_map<char, char> charMap;

        for (int i = 0; i < n; ++i) {
            if (charMap.find(s[i]) == charMap.end() && 
                charMap.find(t[i]) == charMap.end()) {
                charMap[s[i]] = t[i];
            } else if (charMap[s[i]] != t[i]) {
                return false;
            }
        }

        return true;
    }
};

#include "sampling.h"
#include "geometry.h"
#include "shape.h"

namespace pbrt {
    Point2f ConcentricSampleDisk(const Point2f &sample) {
        // Map uniform random numbers to $[-1,1]^2$
        Point2f coordOffset = 2.f * sample - Vector2f(1, 1);
        // Handle degeneracy at the origin
        if (coordOffset.x == 0 && coordOffset.y == 0) return Point2f(0, 0);
        // Apply concentric mapping to point
        float angle, radius;
        if (std::abs(coordOffset.x) > std::abs(coordOffset.y)) {
            radius = coordOffset.x;
            angle = PiOver4 * (coordOffset.y / coordOffset.x);
        } else {
            radius = coordOffset.y;
            angle = PiOver2 - PiOver4 * (coordOffset.x / coordOffset.y);
        }
        return radius * Point2f(std::cos(angle), std::sin(angle));
    }
}

