    return (processes.size() == 0);
}

#include "../../head.h"
class Solution {
public:
    // Determine if the first player can win the game with n stones
    bool winnerSquareGame(int totalStones) {
        std::vector<bool> canWin(totalStones + 1, false);

        for (int stones = 1; stones <= totalStones; stones++) {
            int num = 1;
            int squareVal = 0;

            while ((squareVal = num * num) <= stones) {
                if (!canWin[stones - squareVal]) {
                    canWin[stones] = true;
                    break;
                }
                num++;
            }
        }

        return canWin[totalStones];
    }
};

