	SceneCamera::SceneCamera()
	{
		UpdateProjection();
	}

	void SceneCamera::SetOrthographic(float orthoSize, float clipNear, float clipFar)
	{
		m_ProjectionType = ProjectionType::Orthographic;
		m_OrthographicSize = orthoSize;
		m_OrthographicNearClip = clipNear;
		m_OrthographicFarClip = clipFar;
		UpdateProjection();
	}

	void SceneCamera::SetPerspective(float fovVertical, float clipNear, float clipFar)
	{
		m_ProjectionType = ProjectionType::Perspective;
		m_PerspectiveFieldOfView = fovVertical;
		m_PerspectiveNearClip = clipNear;
		m_PerspectiveFarClip = clipFar;
		UpdateProjection();
	}

	void SceneCamera::SetViewportSize(uint32_t width, uint32_t height)
	{
		m_AspectRatio = static_cast<float>(width) / static_cast<float>(height);
		UpdateProjection();
	}

	void SceneCamera::UpdateProjection()
	{
		if (m_ProjectionType == ProjectionType::Perspective)
		{
			m_ProjectionMatrix = glm::perspective(m_PerspectiveFieldOfView, m_AspectRatio, m_PerspectiveNearClip, m_PerspectiveFarClip);
		}
		else
		{
			float left   = -m_OrthographicSize * m_AspectRatio * 0.5f;
			float right  =  m_OrthographicSize * m_AspectRatio * 0.5f;
			float bottom = -m_OrthographicSize * 0.5f;
			float top    =  m_OrthographicSize * 0.5f;
			m_ProjectionMatrix = glm::ortho(left, right, bottom, top, m_OrthographicNearClip, m_OrthographicFarClip);
		}
	}
}

#include "StackAllocator.hpp"
#include "Core/Core.hpp"
#include "Utility/Size.hpp"

namespace QMBT
{
	StackAllocator::StackAllocator(const char* debugLabel, Size capacity)
		: m_Data(std::make_shared<AllocatorData>(debugLabel, capacity)), m_HeadPtr(malloc(m_Data->TotalSize))
	{
		QMBT_CORE_ASSERT(capacity < 1_GB && capacity > 0, "Capacity of allocator must be positive and less than 1 GB");
		MemoryManager::GetInstance().Register(m_Data);
		m_Offset = 0;
		LOG_MEMORY_INFO("Constructed {0} with capacity {1}", m_Data->DebugName, Utility::ToReadable(m_Data->TotalSize));
	}

	StackAllocator::~StackAllocator()
	{
		MemoryManager::GetInstance().UnRegister(m_Data);
		free(m_HeadPtr);
	}

	void* StackAllocator::Allocate(Size bytes, Size align)
	{
		const Size currentLocation = (Size)m_HeadPtr + m_Offset;
		Size pad = Utility::CalculatePaddingWithHeader(currentLocation, align, sizeof(AllocationHeader));

		if (m_Offset + pad + bytes > m_Data->TotalSize)
		{
			LOG_MEMORY_CRITICAL("{0}: Requested allocation ({1} bytes) exceeds available space ({2} remaining)!",
								m_Data->DebugName,
								bytes,
								Utility::ToReadable(m_Data->TotalSize - m_Offset));
			return nullptr;
		}

		m_Offset += pad;
		const Size targetAddress = currentLocation + pad;
		m_Offset += bytes;
		m_Data->UsedSize = m_Offset;

		LOG_MEMORY_INFO("{0}: Allocated {1} bytes (aligned to {2})", m_Data->DebugName, bytes, align);
		return reinterpret_cast<void*>(targetAddress);
	}

	void StackAllocator::Deallocate(const Size address)
	{
		const Size priorOffset = m_Offset;
		const Size headerLocation = address - sizeof(AllocationHeader);
		const AllocationHeader* header{reinterpret_cast<const AllocationHeader*>(headerLocation)};

		m_Offset = address - header->padding - (Size)m_HeadPtr;
		m_Data->UsedSize = m_Offset;

		LOG_MEMORY_INFO("{0}: Deallocated {1} bytes", m_Data->DebugName, Utility::ToReadable(priorOffset - m_Offset));
	}
} // namespace QMBT

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);

    int size;
    cin >> size;

    vector<int> data(size);
    for (auto &value : data) {
        cin >> value;
    }

    // Append first element to make array circular
    data.push_back(data[0]);

    int minDiff = numeric_limits<int>::max();
    int minIndex = -1;

    // Find adjacent pair with minimum absolute difference
    for (int idx = 0; idx < size; idx++) {
        int diff = abs(data[idx + 1] - data[idx]);
        if (diff < minDiff) {
            minDiff = diff;
            minIndex = idx;
        }
    }

    // Output 1-based indices
    if (minIndex == size - 1) {
        cout << minIndex + 1 << " " << 1 << endl;
    } else {
        cout << minIndex + 1 << " " << minIndex + 2 << endl;
    }

    return 0;
}

