#include <mpi.h>
#include <omp.h>
#ifdef HAS_PETSC
#include <petscksp.h>
#endif
#include "general_definitions.hpp"
#include "simulation/ompi/simulation_ompi_base.hpp"

int main(int argc, char* argv[]) {
    // Validate command-line arguments
    if (argc != 2) {
        std::cerr << "Usage\n"
                  << "    /path/to/dgswemv2-ompi input_file\n";
        return 1;
    } else {
        auto start_time = std::chrono::high_resolution_clock::now();

        int thread_support_level;
        MPI_Init_thread(&argc, &argv, MPI_THREAD_MULTIPLE, &thread_support_level);

        // Check if multi-threading is properly supported
        if (thread_support_level != MPI_THREAD_MULTIPLE) {
            if (omp_get_max_threads() > 1) {
                std::cerr << "dgswemv2 with ompi parallelization was submitted with more than \n"
                          << "1 thread per MPI rank and MPI_THREAD_MULTIPLE is not provided!\n"
                          << "Please either find an MPI implementation that supports MPI_THREAD_MULTIPLE,\n"
                          << " or resubmit the job with one thread per MPI rank and set the\n"
                          << " environment variable OMP_NUM_THREADS=1\n";
                MPI_Abort(MPI_COMM_WORLD, MPI_ERR_OTHER);
                return 1;
            }
        }

#ifdef HAS_PETSC
        PetscInitialize(&argc, &argv, (char*)nullptr, nullptr);
#endif

        // Process input file name
        std::string config_path = std::string(argv[1]);
        std::unique_ptr<OMPISimulationBase> model = OMPISimulationFactory::Create(config_path);
        model->Execute();

        // Synchronize all processes before timing
        MPI_Barrier(MPI_COMM_WORLD);

        auto end_time = std::chrono::high_resolution_clock::now();

        int process_rank;
        MPI_Comm_rank(MPI_COMM_WORLD, &process_rank);

        // Only rank 0 reports the execution time
        if (process_rank == 0) {
            std::cout << "Time Elapsed (in us): "
                      << std::chrono::duration_cast<std::chrono::microseconds>(end_time - start_time).count() << std::endl;
        }

        model->Cleanup();

#ifdef HAS_PETSC
        PetscFinalize();
#endif

        MPI_Finalize();
        return 0;
    }
}

