class CustomWorker : public gusc::Threads::Thread
{
};

void executeFunction()
{
    slog << "Executable function thread ID: " + tidToStr(std::this_thread::get_id());
}

class FunctionBinder
{
public:
    void invokeMethod()
    {
        slog << "Invoked method thread ID: " + tidToStr(std::this_thread::get_id());
    }
};

struct InvocableObject
{
    void operator()() const
    {
        slog << "Invocable object thread ID: " + tidToStr(std::this_thread::get_id());
    }
};

static const auto staticConstLambda = [](){
    slog << "Static const lambda thread ID: " + tidToStr(std::this_thread::get_id());
};

static auto staticLambda = [](){
    slog << "Static lambda thread ID: " + tidToStr(std::this_thread::get_id());
};

void runThreadValidation()
{
    slog << "Thread Validation";

    gusc::Threads::ThisThread worker;
    gusc::Threads::Thread tA;
    CustomWorker tB;

    slog << "Main thread ID: " + tidToStr(std::this_thread::get_id());

    // Test free function
    executeFunction();
    worker.send(&executeFunction);
    tA.send(&executeFunction);
    tB.send(&executeFunction);

    // Test member function via bind
    FunctionBinder instance;
    instance.invokeMethod();
    worker.send(std::bind(&FunctionBinder::invokeMethod, &instance));
    tA.send(std::bind(&FunctionBinder::invokeMethod, &instance));
    tB.send(std::bind(&FunctionBinder::invokeMethod, &instance));

    // Test callable struct (lvalue)
    const InvocableObject invObj;
    invObj();
    worker.send(invObj);
    tA.send(invObj);
    tB.send(invObj);

    // Test callable struct (temporary)
    worker.send(InvocableObject{});
    tA.send(InvocableObject{});
    tB.send(InvocableObject{});

    // Test local lambda
    auto localLambdaExpr = [](){
        slog << "Local lambda expression thread ID: " + tidToStr(std::this_thread::get_id());
    };
    localLambdaExpr();
    worker.send(localLambdaExpr);
    tA.send(localLambdaExpr);
    tB.send(localLambdaExpr);

    // Test global static lambda
    staticLambda();
    worker.send(staticLambda);
    tA.send(staticLambda);
    tB.send(staticLambda);

    // Test global static const lambda
    staticConstLambda();
    worker.send(staticConstLambda);
    tA.send(staticConstLambda);
    tB.send(staticConstLambda);

    // Test anonymous lambda expressions
    worker.send([](){
        slog << "Anonymous lambda expression thread ID: " + tidToStr(std::this_thread::get_id());
    });
    tA.send([](){
        slog << "Anonymous lambda expression thread ID: " + tidToStr(std::this_thread::get_id());
    });
    tB.send([](){
        slog << "Anonymous lambda expression thread ID: " + tidToStr(std::this_thread::get_id());
    });

    // Terminate main thread processing loop
    worker.stop();

    // Launch all threads and main event loop
    tA.start();
    tB.start();
    worker.start();
}

#include <gtest/gtest.h>
#include "ocs2_sqp/MultipleShootingSolver.h"
#include <ocs2_core/initialization/DefaultInitializer.h>
#include <ocs2_oc/test/circular_kinematics.h>

// Test case: solve using projected equality constraints
TEST(test_circular_kinematics, solve_projected_EqConstraints_v2) {
  // Define optimal control problem
  ocs2::OptimalControlProblem problem = ocs2::createCircularKinematicsProblem("/tmp/sqp_test_generated_v2");

  // State initializer
  ocs2::DefaultInitializer stateInit(2);

  // Configure solver settings
  ocs2::multiple_shooting::Settings config;
  config.dt = 0.02;                     // doubled time step
  config.sqpIteration = 30;             // more iterations
  config.projectStateInputEqualityConstraints = true;
  config.useFeedbackPolicy = true;
  config.printSolverStatistics = false; // disabled logging
  config.printSolverStatus = false;
  config.printLinesearch = false;
  config.nThreads = 2;                  // use multiple threads

  // Problem setup
  const ocs2::scalar_t startT = 0.5;    // shifted start time
  const ocs2::scalar_t endT = 1.5;      // shifted final time
  const ocs2::vector_t initialState = (ocs2::vector_t(2) << 0.8, 0.6).finished();  // radius still 1.0
  const ocs2::scalar_array_t timeGrid{0.0, 0.5};                                      // partitioning times adjusted

  // Initialize and run solver
  ocs2::MultipleShootingSolver solver(config, problem, stateInit);
  solver.run(startT, initialState, endT, timeGrid);

  // Retrieve and inspect solution
  const auto solution = solver.primalSolution(endT);
  for (size_t idx = 0; idx < solution.timeTrajectory_.size(); ++idx) {
    std::cout << "t=" << solution.timeTrajectory_[idx] 
              << ", x=" << solution.stateTrajectory_[idx].transpose()
              << ", u=" << solution.inputTrajectory_[idx].transpose() << std::endl;
  }

  // Validate initial condition
  EXPECT_TRUE(solution.stateTrajectory_.front().isApprox(initialState));
  EXPECT_DOUBLE_EQ(solution.timeTrajectory_.front(), startT);
  EXPECT_DOUBLE_EQ(solution.timeTrajectory_.back(), endT);

  // Verify constraint satisfaction
  const auto stats = solver.getPerformanceIndeces();
  EXPECT_LT(stats.stateEqConstraintISE, 1e-5);
  EXPECT_LT(stats.stateInputEqConstraintISE, 1e-5);

  // Validate feedback controller implementation
  for (size_t k = 0; k < solution.timeTrajectory_.size() - 1; ++k) {
    const auto t = solution.timeTrajectory_[k];
    const auto& x = solution.stateTrajectory_[k];
    const auto& u = solution.inputTrajectory_[k];
    EXPECT_TRUE(u.isApprox(solution.controllerPtr_->computeInput(t, x)));
  }
}

