	{
		FString MapPath, PackageName, TestLabel;
		ExtractMapParameters(InputParams, MapPath, PackageName, TestLabel);
		bool bCanProceed = false;
		IFunctionalTestingModule::Get().MarkPendingActivation();
		UWorld* ActiveWorld = RetrieveActiveWorld();
		if (ActiveWorld && ActiveWorld->GetMapName() == PackageName)
		{
			// Map is already loaded.
			bCanProceed = true;
		}
		else
		{
			bCanProceed = AutomationOpenMap(PackageName);
		}
		if (bCanProceed)
		{
			if (TestLabel.IsEmpty())
			{
				ADD_LATENT_AUTOMATION_COMMAND(FStartFTestsOnMap());
			}
			else
			{
				ADD_LATENT_AUTOMATION_COMMAND(FStartFTestOnMap(TestLabel));
			}
			return true;
		}
		/// FAutomationTestFramework::GetInstance().UnregisterAutomationTest
		//	ADD_LATENT_AUTOMATION_COMMAND(FWaitLatentCommand(1.f));
		//  ADD_LATENT_AUTOMATION_COMMAND(FExitGameCommand);
		UE_LOG(LogFunctionalTest, Error, TEXT("Failed to start the %s map (possibly due to BP compilation issues)"), *PackageName);
		return false;
	}
};

