#include "global.h"
#include "functions.h"

int preProcessing(int rows,
                  int cols,
                  int *threadsPerLaunch,
                  int *offsets,
                  int& initialMatrixElement)
{
    int totalLaunches = rows + cols - 1;
    int launchIndex;
    int prevColumnCount, currentOffsetPos, finalEndPosition;
    int threadsInCurrentLaunch;

    int alignedStride = COALESCED_OFFSET;
    int beginningPosition;
    int additionalOffset;

    additionalOffset = 0;
    beginningPosition = alignedStride;
    threadsInCurrentLaunch = 1;
    prevColumnCount = alignedStride - 1;

    for (launchIndex = 1; launchIndex < totalLaunches; launchIndex++)
    {
        if (launchIndex < rows)
        {
            if (launchIndex < cols)
            {
                threadsInCurrentLaunch++;
                threadsPerLaunch[launchIndex] = threadsInCurrentLaunch - 2;
            }
            else
            {
                threadsPerLaunch[launchIndex] = threadsInCurrentLaunch - 1;
            }
            finalEndPosition = beginningPosition;
        }
        else
        {
            threadsInCurrentLaunch--;
            threadsPerLaunch[launchIndex] = threadsInCurrentLaunch;
        }

        if (launchIndex > rows)
        {
            additionalOffset = 1;
        }

        if ((rows == cols) && (launchIndex == rows - 1))
        {
            currentOffsetPos = ((threadsInCurrentLaunch + alignedStride - 2) / alignedStride) * alignedStride;
        }
        else
        {
            currentOffsetPos = ((threadsInCurrentLaunch + alignedStride - 1) / alignedStride) * alignedStride;
        }

        beginningPosition += currentOffsetPos;

        if (launchIndex <= rows)
        {
            offsets[launchIndex] = prevColumnCount;
        }
        else
        {
            offsets[launchIndex] = prevColumnCount - additionalOffset;
        }

        prevColumnCount = currentOffsetPos;
    }

    initialMatrixElement = finalEndPosition + rows;
    return beginningPosition;
}

float maximumValue(float *values, int count)
{
    float maxValue = 0.0f;
    int index;

    for (index = 0; index < count; index++)
    {
        if (maxValue < values[index])
        {
            maxValue = values[index];
        }
    }

    return maxValue;
}

