int main() {
    atomic<int> value{ 10 }; // Initialization with curly braces ensures atomicity

    /*
     // Alternative initialization methods for atomic variables:
     // atomic<int> value( 10 ) -> valid
     // atomic<int> value{ 10 } -> valid
     // atomic<int> value = { 10 } -> valid
     // atomic<int> value = 0 -> invalid (no implicit conversion)
     // atomic<int> value; value = 0; -> valid (assignment after default construction)
     */

    cout << value << endl; // Outputs: 10

    int temp = value.load();
    cout << temp << endl; // Outputs: 10

    temp += 10;
    value.store(temp);
    cout << "After Store" << endl;
    cout << value << endl; // Outputs: 20
    cout << temp << endl;  // Outputs: 20

    temp = 100;
    int previous = value.exchange(temp);
    cout << "temp = 100 \nAfter Exchange. . ." << endl;
    cout << value << endl;   // Outputs: 100
    cout << temp << endl;    // Outputs: 100
    cout << previous << endl; // Outputs: 20

    bool result = value.compare_exchange_strong(temp, previous);
    /*
        if value == temp, then value = previous and return true
        else temp = value and return false
    */
    cout << "After compare_exchange_strong" << endl;
    cout << value << endl;   // Outputs: 20
    cout << temp << endl;    // Outputs: 100
    cout << previous << endl; // Outputs: 20
    cout << result << endl;  // Outputs: 1

    /*
        atomic<int> counter{ 0 };
        int current = counter;
        while(!counter.compare_exchange_strong(current, current + 1))
            ; // spin until successful
    */

    return 0;
}
