#include "Element.h"
#include "HyperSolveMiniApp.h"
#include "Ddata.h"

template<typename T, size_t NEq, size_t NC>
using CornerSol = std::array<std::array<T, NEq>, NC>;

template<typename T>
CornerSol<T, 5, 4> ComputeCellFlux(long num_cells) {
    std::array<double, 5> base_state = {1.8, 0.3, 0.15, 0.08, 0.79};
    CornerSol<T, 5, 4> state;

    for (int corner_idx = 0; corner_idx < 4; ++corner_idx)
        for (int eqn_idx = 0; eqn_idx < 5; ++eqn_idx)
            state[corner_idx][eqn_idx] = base_state[eqn_idx];

    std::array<HS::Point<double>, 4> vertex_coords;
    vertex_coords[0] = {0.0, 0.0, 0.0};
    vertex_coords[1] = {1.0, 0.0, 0.0};
    vertex_coords[2] = {0.0, 1.0, 0.0};
    vertex_coords[3] = {0.0, 0.0, 1.0};

    auto face_normals = HS::Element::Tet::calcDualNormals(vertex_coords);
    T unit_val = T(1.0);
    HS::Point<T> grad_u(unit_val, unit_val, unit_val);
    HS::Point<T> grad_v = grad_u;
    HS::Point<T> grad_w = grad_u;
    HS::Point<T> grad_t = grad_u;

    std::array<HS::Point<T>, 6> edge_grads_u, edge_grads_v, edge_grads_w, edge_grads_t;
    edge_grads_u.fill(grad_u);
    edge_grads_v.fill(grad_v);
    edge_grads_w.fill(grad_w);
    edge_grads_t.fill(grad_t);

    // Fixed values to avoid thermodynamics dependency
    T visc_coeff(0.015);
    T cond_coeff(0.12);
    HS::Point<T> visc_components;
    visc_components[0] = 1.1;
    visc_components[1] = 1.2;
    visc_components[2] = 1.3;

    CornerSol<T, 5, 4> result_flux;
    long counter = -1;
    int progress_pct = 0;

    for (long cell_num = 0; cell_num < num_cells; ++cell_num) {
        counter++;
        if (counter == (num_cells / 10)) {
            progress_pct += 10;
            printf("[%d%%] processing cell: %lu of %lu\n", progress_pct, cell_num, num_cells);
            counter = 0;
        }

        result_flux = HS::ElementBasedViscousFlux<4, 5>(
            HS::Element::Tet::edge_to_node,
            face_normals,
            edge_grads_u, edge_grads_v, edge_grads_w, edge_grads_t,
            cond_coeff,
            visc_coeff,
            visc_components
        );
    }

    printf("[%d%%] completed cell processing: %lu of %lu\n", 100, num_cells, num_cells);
    return result_flux;
}

int main(int argc, char *argv[]) {
    if (argc == 1) {
        printf("Usage: %s <number of cells to process>\n", argv[0]);
        return 1;
    }

    std::string input_arg = argv[1];
    long num_cells;

    try {
        std::size_t end_pos;
        num_cells = long(std::stod(input_arg, &end_pos));
        if (end_pos < input_arg.size()) {
            std::cerr << "Extra characters after numeric value: " << input_arg << '\n';
            return 1;
        }
    } catch (std::invalid_argument const &err) {
        std::cerr << "Invalid numeric input: " << input_arg << '\n';
        return 1;
    } catch (std::out_of_range const &err) {
        std::cerr << "Numeric value out of range: " << input_arg << '\n';
        return 1;
    }

    printf("Processing %lu cells.\n", num_cells);
    printf("Right-hand side computation:\n");
    auto rhs_result = ComputeCellFlux<double>(num_cells);

    printf("Left-hand side computation:\n");
    auto lhs_result = ComputeCellFlux<Linearize::Ddata<double, 5>>(num_cells);

    for (int corner = 0; corner < 4; ++corner) {
        for (int eqn = 0; eqn < 5; ++eqn) {
            double diff = std::fabs(rhs_result[corner][eqn] - lhs_result[corner][eqn].value);
            if (diff > 1.e-15) return 1;
        }
    }

    return 0;
}

#include "stack.h"
#include <stdlib.h>
#include <assert.h>

// Push a value onto the stack
void push_stack(Stack *S, address_type val) {
   assert(S->top < S->max_capacity);
   S->data[S->top] = val;
   (S->top)++;
}

// Pop and return the top element from the stack
address_type pop_stack(Stack *S) {
   (S->top)--;
   return(S->data[S->top]);
}

// Return the top element without removing it
address_type top_stack(Stack *S) {
   assert(S->top >= 1);
   return(S->data[S->top - 1]);
}

// Create a new stack with specified capacity
Stack* new_stack(int capacity) {
   Stack* S;
   S = (Stack*)malloc(sizeof(Stack));
   S->max_capacity = capacity;
   S->top = 0;
   S->data = (address_type*)calloc(capacity, sizeof(address_type));
   return S;
}

// Free all memory allocated for the stack
void free_stack(Stack *S) {
   free(S->data);
   free(S);
}

// Return current number of elements in the stack
int size_stack(Stack *S) {
   return S->top;
}

// Check if the stack is full
int full_stack(Stack *S) {
   return S->top >= S->max_capacity;
}

// Check if the stack is empty
int empty_stack(Stack *S) {
   return S->top == 0;
}

// Check if a specific value exists in the stack
int element_exist_stack(Stack *S, address_type value) {
   int index;
   for (index = 0; index < S->top; ++index) {
      if (value == S->data[index]) {
         return 1;
      }
   }
   return 0;
}

// Reset the stack to empty state
void reset_stack(Stack *S) {
   S->top = 0;
}

