namespace kaldi {
void UnitTestOnlineCmvn() {
  for (int32 iter = 0; iter < 1000; iter++) {
    int32 frame_count = 1 + (Rand() % 10 * 10);
    int32 feature_dim = 1 + Rand() % 10;
    SlidingWindowCmnOptions params;
    params.center = (Rand() % 2 == 0);
    params.normalize_variance = (Rand() % 2 == 0);
    params.cmn_window = 5 + Rand() % 50;
    params.min_window = 1 + Rand() % 100;
    if (params.min_window > params.cmn_window)
      params.min_window = params.cmn_window;

    Matrix<BaseFloat> input_data(frame_count, feature_dim),
        result1(frame_count, feature_dim),
        result2(frame_count, feature_dim);
    input_data.SetRandn();
    SlidingWindowCmn(params, input_data, &result1);

    for (int32 t = 0; t < frame_count; t++) {
      int32 start_idx, end_idx;
      if (params.center) {
        start_idx = t - (params.cmn_window / 2);
        end_idx = start_idx + params.cmn_window;
        int32 offset = 0;
        if (start_idx < 0)
          offset = -start_idx;
        else if (end_idx > frame_count)
          offset = frame_count - end_idx;
        end_idx += offset;
        start_idx += offset;
      } else {
        start_idx = t - params.cmn_window;
        end_idx = t + 1;
        if (end_idx < params.min_window)
            end_idx = params.min_window;
      }

      if (start_idx < 0) start_idx = 0;
      if (end_idx > frame_count) end_idx = frame_count;

      int32 window_len = end_idx - start_idx;
      for (int32 d = 0; d < feature_dim; d++) {
        double accum = 0.0, accum_sq = 0.0;
        for (int32 t2 = start_idx; t2 < end_idx; t2++) {
          accum += input_data(t2, d);
          accum_sq += input_data(t2, d) * input_data(t2, d);
        }
        double avg = accum / window_len, raw_var = accum_sq / window_len,
            var = raw_var - avg * avg;
        var = std::max(var, 1.0e-20);
        double value = input_data(t, d),
            normalized = value - avg;
        if (params.normalize_variance) {
          if (window_len == 1) normalized = 0.0;
          else normalized /= sqrt(var);
        }
        result2(t, d) = normalized;
      }
    }

    if (! result1.ApproxEqual(result2, 0.0001)) {
      KALDI_ERR << "CMVN results mismatch: " << result1 << " vs. " << result2;
    }
  }
}
}

int main() {
  using namespace kaldi;
  try {
    UnitTestOnlineCmvn();
    std::cout << "All tests passed successfully.\n";
    return 0;
  } catch (const std::exception &e) {
    std::cerr << "Error: " << e.what() << std::endl;
    return 1;
  }
}

