        static std::function<void(const char*, const signalr::value&)> build_invocation_handler(
            const logger& log,
            const std::function<void(const signalr::value&)>& assign_success,
            const std::function<void(const std::exception_ptr err)>& assign_failure);
    }

    std::shared_ptr<hub_connection_impl> hub_connection_impl::build(
        const std::string& endpoint,
        std::unique_ptr<hub_protocol>&& protocol,
        trace_level verbosity,
        const std::shared_ptr<log_writer>& writer,
        std::function<std::shared_ptr<http_client>(const signalr_client_config&)> http_factory,
        std::function<std::shared_ptr<websocket_client>(const signalr_client_config&)> ws_factory,
        const bool bypass_negotiation)
    {
        auto instance = std::shared_ptr<hub_connection_impl>(
            new hub_connection_impl(endpoint, std::move(protocol),
                verbosity, writer, http_factory, ws_factory, bypass_negotiation));
        instance->setup();
        return instance;
    }

    hub_connection_impl::hub_connection_impl(
        const std::string& endpoint,
        std::unique_ptr<hub_protocol>&& protocol,
        trace_level verbosity,
        const std::shared_ptr<log_writer>& writer,
        std::function<std::shared_ptr<http_client>(const signalr_client_config&)> http_factory,
        std::function<std::shared_ptr<websocket_client>(const signalr_client_config&)> ws_factory,
        const bool bypass_negotiation)
        : m_link(connection_impl::create(endpoint, verbosity, writer, http_factory, ws_factory, bypass_negotiation)),
          m_logger(writer, verbosity),
          m_registry("connection went out of scope before invocation result was received"),
          m_handshakeReceived(false),
          m_terminated([](std::exception_ptr) noexcept {}),
          m_protocol(std::move(protocol))
    {}

    void hub_connection_impl::setup()
    {
        std::weak_ptr<hub_connection_impl> weak_self = shared_from_this();

        m_link->set_on_message_received([weak_self](std::string&& payload)
        {
            auto self = weak_self.lock();
            if (self)
            {
                self->handle_incoming_message(std::move(payload));
            }
        });

        m_link->set_on_disconnected([weak_self](std::exception_ptr error)
        {
            auto self = weak_self.lock();
            if (self)
            {
                self->m_handshakePromise->set(std::make_exception_ptr(
                    signalr_exception("connection closed while handshake was in progress.")));

                try
                {
                    self->m_cancel_token_source->cancel();
                }
                catch (const std::exception& ex)
                {
                    if (self->m_logger.is_enabled(trace_level::warning))
                    {
                        self->m_logger.log(trace_level::warning,
                            std::string("disconnection event threw an exception during shutdown: ")
                                .append(ex.what()));
                    }
                }

                self->m_registry.clear("connection was stopped before invocation result was received");
                self->m_terminated(error);
            }
        });
    }

    void hub_connection_impl::subscribe(const std::string& name, const std::function<void(const std::vector<signalr::value>&)>& handler)
    {
        if (name.empty())
        {
            throw std::invalid_argument("event_name cannot be empty");
        }

        auto self_weak = std::weak_ptr<hub_connection_impl>(shared_from_this());
        auto self_locked = self_weak.lock();
        if (self_locked && self_locked->get_state() != connection_state::disconnected)
        {
            throw signalr_exception("cannot register handler when connection is not active");
        }

        if (m_handlers.find(name) != m_handlers.end())
        {
            throw signalr_exception(
                "handler already registered for this event: " + name);
        }

        m_handlers.insert({name, handler});
    }

    void hub_connection_impl::begin(std::function<void(std::exception_ptr)> completion) noexcept
    {
        if (m_link->get_state() != connection_state::disconnected)
        {
            completion(std::make_exception_ptr(signalr_exception(
                "connection must be in disconnected state to start")));
            return;
        }

        m_link->set_configuration(m_client_config);
        m_handshakePromise = std::make_shared<completion_event>();
        m_cancel_token_source = std::make_shared<cancellation_token_source>();
        m_handshakeReceived = false;

        std::weak_ptr<hub_connection_impl> self_weak = shared_from_this();

        m_link->start([self_weak, completion](std::exception_ptr start_error)
            {
                auto self = self_weak.lock();
                if (!self)
                {
                    completion(std::make_exception_ptr(signalr_exception("hub connection destroyed")));
                    return;
                }

                if (start_error)
                {
                    assert(self->get_state() == connection_state::disconnected);
                    completion(start_error);
                    return;
                }

                std::shared_ptr<std::mutex> lock = std::make_shared<std::mutex>();
                std::shared_ptr<bool> completed = std::make_shared<bool>(false);

                auto on_handshake_result = [self_weak, completed, lock, completion](
                    std::exception_ptr err, bool from_send)
                {
                    auto self = self_weak.lock();
                    if (!self)
                    {
                        completion(std::make_exception_ptr(signalr_exception("hub connection destroyed")));
                        return;
                    }

                    {
                        std::lock_guard<std::mutex> guard(*lock);
                        if (from_send || *completed != false)
                        {
                            return;
                        }
                        *completed = true;
                    }

                    try
                    {
                        if (err == nullptr)
                        {
                            self->m_handshakePromise->get();
                            completion(nullptr);
                        }
                    }
                    catch (...)
                    {
                        err = std::current_exception();
                    }

                    if (err != nullptr)
                    {
                        self->m_link->stop([completion, err](std::exception_ptr) { completion(err); }, err);
                    }
                };

                auto request = handshake::encode();
                auto promise = self->m_handshakePromise;
                auto timeout = self->m_client_config.get_handshake_timeout();

                self->m_cancel_token_source->register_callback([on_handshake_result, lock, completed]()
                    {
                        {
                            std::lock_guard<std::mutex> guard(*lock);
                            if (*completed != false)
                            {
                                return;
                            }
                        }
                        on_handshake_result(nullptr, false);
                    });

                timer(self->m_client_config.get_scheduler(),
                    [on_handshake_result, promise, timeout, lock](std::chrono::milliseconds elapsed)
                    {
                        {
                            std::lock_guard<std::mutex> guard(*lock);
                            if (promise->is_ready())
                            {
                                return true;
                            }
                            if (elapsed < timeout)
                            {
                                return false;
                            }
                        }
                        auto ex = std::make_exception_ptr(
                            signalr_exception("timed out waiting for server handshake response."));
                        promise->set(ex);
                        on_handshake_result(ex, false);
                        return true;
                    });

                self->m_link->send(request, self->m_protocol->format(),
                    [on_handshake_result, completed, lock](std::exception_ptr send_error)
                {
                    {
                        std::lock_guard<std::mutex> guard(*lock);
                        if (*completed != false)
                        {
                            return;
                        }
                        *completed = true;
                    }
                    on_handshake_result(send_error, true);
                });
            });
    }

    void hub_connection_impl::end(std::function<void(std::exception_ptr)> completion) noexcept
    {
        if (get_state() == connection_state::disconnected)
        {
            m_logger.log(trace_level::info, "Stop ignored because the connection is already inactive.");
            completion(nullptr);
            return;
        }

        {
            std::lock_guard<std::mutex> guard(m_completion_lock);
            m_callbacks.push_back(completion);
            if (m_callbacks.size() > 1)
            {
                m_logger.log(trace_level::info, "Stop already in progress; awaiting completion.");
                return;
            }
        }

        std::weak_ptr<hub_connection_impl> self_weak = shared_from_this();
        m_link->stop([self_weak](std::exception_ptr error)
            {
                auto self = self_weak.lock();
                if (!self)
                {
                    return;
                }

                assert(self->get_state() == connection_state::disconnected);
                std::vector<std::function<void(std::exception_ptr)>> handlers;
                {
                    std::lock_guard<std::mutex> guard(self->m_completion_lock);
                    handlers = self->m_callbacks;
                    self->m_callbacks.clear();
                }

                for (auto& cb : handlers)
                {
                    cb(error);
                }
            }, nullptr);
    }

    void hub_connection_impl::handle_incoming_message(std::string&& data)
    {
        try
        {
            if (!m_handshakeReceived)
            {
                signalr::value response;
                std::tie(data, response) = handshake::decode(data);
                auto& map = response.as_map();
                auto iter = map.find("error");
                if (iter != map.end())
                {
                    const auto& msg = iter->second.as_string();
                    if (m_logger.is_enabled(trace_level::error))
                    {
                        m_logger.log(trace_level::error, std::string("handshake failure: ").append(msg));
                    }
                    m_handshakePromise->set(std::make_exception_ptr(
                        signalr_exception(std::string("Error during handshake: ").append(msg))));
                    return;
                }
                else
                {
                    iter = map.find("type");
                    if (iter != map.end())
                    {
                        m_handshakePromise->set(std::make_exception_ptr(
                            signalr_exception("Unexpected message received during handshake phase.")));
                        return;
                    }
                    m_handshakeReceived = true;
                    m_handshakePromise->set();
                    if (data.empty())
                    {
                        return;
                    }
                }
            }

            auto messages = m_protocol->deserialize(data);
            for (const auto& item : messages)
            {
                switch (item->kind)
                {
                case message_type::invocation:
                {
                    auto invoc = static_cast<invocation_message*>(item.get());
                    auto handler = m_handlers.find(invoc->target);
                    if (handler != m_handlers.end())
                    {
                        handler->second(invoc->arguments);
                    }
                    else
                    {
                        m_logger.log(trace_level::info, "handler not found");
                    }
                    break;
                }
                case message_type::stream_invocation:
                    throw std::runtime_error("Unexpected 'StreamInvocation' message received by client.");
                case message_type::stream_item:
                    // Future implementation
                    break;
                case message_type::completion:
                {
                    auto comp = static_cast<completion_message*>(item.get());
                    process_completion(comp);
                    break;
                }
                case message_type::cancel_invocation:
                    throw std::runtime_error("Unexpected 'CancelInvocation' message received by client.");
                case message_type::ping:
                    // Future implementation
                    break;
                case message_type::close:
                    // Future implementation
                    break;
                }
            }
        }
        catch (const std::exception& e)
        {
            if (m_logger.is_enabled(trace_level::error))
            {
                m_logger.log(trace_level::error,
                    std::string("parsing error: ").append(e.what()).append(". payload: ").append(data));
            }
            m_link->stop([](std::exception_ptr) {}, std::current_exception());
        }
    }

    bool hub_connection_impl::process_completion(completion_message* record)
    {
        const char* error_msg = nullptr;
        if (!record->error.empty())
        {
            error_msg = record->error.c_str();
        }

        if (!m_registry.invoke(record->id, error_msg, record->payload, true))
        {
            if (m_logger.is_enabled(trace_level::info))
            {
                m_logger.log(trace_level::info,
                    std::string("no callback registered for id: ").append(record->id));
            }
        }
        return true;
    }

    void hub_connection_impl::invoke(const std::string& method, const std::vector<signalr::value>& args,
        std::function<void(const signalr::value&, std::exception_ptr)> callback) noexcept
    {
        const auto& id = m_registry.assign_id(
            build_invocation_handler(m_logger,
                [callback](const signalr::value& res) { callback(res, nullptr); },
                [callback](const std::exception_ptr err) { callback(signalr::value(), err); }));

        execute_method(method, args, id, nullptr,
            [callback](const std::exception_ptr err){ callback(signalr::value(), err); });
    }

    void hub_connection_impl::dispatch(const std::string& method, const std::vector<signalr::value>& args,
        std::function<void(std::exception_ptr)> callback) noexcept
    {
        execute_method(method, args, "",
            [callback]() { callback(nullptr); },
            [callback](const std::exception_ptr err){ callback(err); });
    }

    void hub_connection_impl::execute_method(const std::string& method,
        const std::vector<signalr::value>& args,
        const std::string& id,
        std::function<void()> on_sent,
        std::function<void(const std::exception_ptr)> on_error) noexcept
    {
        try
        {
            invocation_message msg(id, method, args);
            auto payload = m_protocol->serialize(&msg);

            std::weak_ptr<hub_connection_impl> self_weak = shared_from_this();
            m_link->send(payload, m_protocol->format(), [on_sent, on_error, self_weak, id](std::exception_ptr err)
                {
                    if (err)
                    {
                        auto self = self_weak.lock();
                        if (self)
                        {
                            self->m_registry.remove(id);
                        }
                        on_error(err);
                    }
                    else
                    {
                        if (id.empty())
                        {
                            on_sent();
                        }
                    }
                });
        }
        catch (const std::exception& e)
        {
            m_registry.remove(id);
            if (m_logger.is_enabled(trace_level::warning))
            {
                m_logger.log(trace_level::warning,
                    std::string("failed to dispatch invocation: ").append(e.what()));
            }
            on_error(std::current_exception());
        }
    }

    connection_state hub_connection_impl::get_state() const noexcept
    {
        return m_link->get_state();
    }

    std::string hub_connection_impl::get_identifier() const
    {
        return m_link->get_identifier();
    }

    void hub_connection_impl::configure(const signalr_client_config& settings)
    {
        m_client_config = settings;
        m_link->configure(settings);
    }

    void hub_connection_impl::set_termination_handler(const std::function<void(std::exception_ptr)>& handler)
    {
        m_terminated = handler;
    }

    namespace
    {
        static std::function<void(const char*, const signalr::value&)> build_invocation_handler(
            const logger& logger,
            const std::function<void(const signalr::value&)>& on_success,
            const std::function<void(const std::exception_ptr)>& on_failure)
        {
            return [logger, on_success, on_failure](const char* error, const signalr::value& value)
            {
                if (error != nullptr)
                {
                    on_failure(std::make_exception_ptr(hub_exception(error)));
                }
                else
                {
                    on_success(value);
                }
            };
        }
    }
}

#include "Logging.h"
#include "Assert.h"

namespace mms {

QTextStream* Logging::STDOUT = nullptr;

void Logging::init() {
    ASSERT_TR(STDOUT == nullptr);
    STDOUT = new QTextStream(stdout);
    qInstallMessageHandler(handler);
}

void Logging::handler(
        QtMsgType type,
        const QMessageLogContext& context,
        const QString& message) {
    ASSERT_FA(STDOUT == nullptr);

    static const QMap<QtMsgType, QString> levelMap {
        {QtDebugMsg,    "DEBUG"   },
        {QtInfoMsg,     "INFO"    },
        {QtWarningMsg,  "WARN"    },
        {QtCriticalMsg, "CRITICAL"},
        {QtFatalMsg,    "FATAL"   },
    };

    QString formattedOutput = QString("[%1][%2:%3] - %4").arg(
        levelMap.value(type),
        context.file,
        QString::number(context.line),
        message
    );

    *STDOUT << formattedOutput << endl;
}

