static logvisor::Module AudioLog("boo::WAVOut");

struct WAVOutputEngine : BaseAudioVoiceEngine {
    std::vector<float> m_audioBuffer;
    AudioChannelSet _getAvailableSet() { return AudioChannelSet::Stereo; }

    std::string getCurrentAudioOutput() const override { return "wavout"; }
    bool setCurrentAudioOutput(const char* label) override { return false; }

    std::vector<std::pair<std::string, std::string>> enumerateAudioOutputs() const override {
        return {{"wavout", "WAVOut"}};
    }

    std::vector<std::pair<std::string, std::string>> enumerateMIDIInputs() const override { return {}; }
    bool supportsVirtualMIDIIn() const override { return false; }

    ReceiveFunctor* m_midiCallback = nullptr;

    struct MIDIInputHandler : public IMIDIIn {
        MIDIInputHandler(WAVOutputEngine* owner, bool isVirtual, ReceiveFunctor&& callback)
            : IMIDIIn(owner, isVirtual, std::move(callback)) {}

        std::string description() const override { return "WAVOut MIDI"; }
    };

    std::unique_ptr<IMIDIIn> newVirtualMIDIIn(ReceiveFunctor&& callback) override {
        auto handler = std::make_unique<MIDIInputHandler>(nullptr, true, std::move(callback));
        m_midiCallback = &handler->m_receiver;
        return handler;
    }

    std::unique_ptr<IMIDIOut> newVirtualMIDIOut() override { return {}; }
    std::unique_ptr<IMIDIInOut> newVirtualMIDIInOut(ReceiveFunctor&& callback) override { return {}; }
    std::unique_ptr<IMIDIIn> newRealMIDIIn(const char* name, ReceiveFunctor&& callback) override { return {}; }
    std::unique_ptr<IMIDIOut> newRealMIDIOut(const char* name) override { return {}; }
    std::unique_ptr<IMIDIInOut> newRealMIDIInOut(const char* name, ReceiveFunctor&& callback) override { return {}; }

    bool useMIDILock() const override { return false; }

    FILE* m_fileHandle = nullptr;
    size_t m_totalBytes = 0;

    void setupWAVFormat(double sampleRate, int channelCount) {
        uint32_t speakerMask = 0;

        switch (channelCount) {
        default:
        case 2:
            channelCount = 2;
            m_mixInfo.m_channels = AudioChannelSet::Stereo;
            m_mixInfo.m_channelMap.m_channelCount = 2;
            m_mixInfo.m_channelMap.m_channels[0] = AudioChannel::FrontLeft;
            m_mixInfo.m_channelMap.m_channels[1] = AudioChannel::FrontRight;
            speakerMask = 0x00000001 | 0x00000002;
            break;

        case 4:
            channelCount = 4;
            m_mixInfo.m_channels = AudioChannelSet::Quad;
            m_mixInfo.m_channelMap.m_channelCount = 4;
            m_mixInfo.m_channelMap.m_channels[0] = AudioChannel::FrontLeft;
            m_mixInfo.m_channelMap.m_channels[1] = AudioChannel::FrontRight;
            m_mixInfo.m_channelMap.m_channels[2] = AudioChannel::RearLeft;
            m_mixInfo.m_channelMap.m_channels[3] = AudioChannel::RearRight;
            speakerMask = 0x00000001 | 0x00000002 | 0x00000010 | 0x00000020;
            break;

        case 6:
            channelCount = 6;
            m_mixInfo.m_channels = AudioChannelSet::Surround51;
            m_mixInfo.m_channelMap.m_channelCount = 6;
            m_mixInfo.m_channelMap.m_channels[0] = AudioChannel::FrontLeft;
            m_mixInfo.m_channelMap.m_channels[1] = AudioChannel::FrontRight;
            m_mixInfo.m_channelMap.m_channels[2] = AudioChannel::FrontCenter;
            m_mixInfo.m_channelMap.m_channels[3] = AudioChannel::LFE;
            m_mixInfo.m_channelMap.m_channels[4] = AudioChannel::RearLeft;
            m_mixInfo.m_channelMap.m_channels[5] = AudioChannel::RearRight;
            speakerMask = 0x00000001 | 0x00000002 | 0x00000004 | 0x00000008 | 0x00000010 | 0x00000020;
            break;

        case 8:
            channelCount = 8;
            m_mixInfo.m_channels = AudioChannelSet::Surround71;
            m_mixInfo.m_channelMap.m_channelCount = 8;
            m_mixInfo.m_channelMap.m_channels[0] = AudioChannel::FrontLeft;
            m_mixInfo.m_channelMap.m_channels[1] = AudioChannel::FrontRight;
            m_mixInfo.m_channelMap.m_channels[2] = AudioChannel::FrontCenter;
            m_mixInfo.m_channelMap.m_channels[3] = AudioChannel::LFE;
            m_mixInfo.m_channelMap.m_channels[4] = AudioChannel::RearLeft;
            m_mixInfo.m_channelMap.m_channels[5] = AudioChannel::RearRight;
            m_mixInfo.m_channelMap.m_channels[6] = AudioChannel::SideLeft;
            m_mixInfo.m_channelMap.m_channels[7] = AudioChannel::SideRight;
            speakerMask =
                0x00000001 | 0x00000002 | 0x00000004 | 0x00000008 | 0x00000010 | 0x00000020 | 0x00000200 | 0x00000400;
            break;
        }

        if (channelCount == 2) {
            fwrite("RIFF", 1, 4, m_fileHandle);
            uint32_t payloadSize = 0;
            uint32_t riffChunkSize = 36 + payloadSize;
            fwrite(&riffChunkSize, 1, 4, m_fileHandle);
            fwrite("WAVE", 1, 4, m_fileHandle);
            fwrite("fmt ", 1, 4, m_fileHandle);
            uint32_t subchunk1Size = 16;
            fwrite(&subchunk1Size, 1, 4, m_fileHandle);
            uint16_t formatTag = 3;
            fwrite(&formatTag, 1, 2, m_fileHandle);
            uint16_t numChannels = static_cast<uint16_t>(channelCount);
            fwrite(&numChannels, 1, 2, m_fileHandle);
            uint32_t samplingRate = static_cast<uint32_t>(sampleRate);
            fwrite(&samplingRate, 1, 4, m_fileHandle);
            uint16_t blockAlign = static_cast<uint16_t>(4 * channelCount);
            uint32_t avgBytesPerSec = samplingRate * blockAlign;
            fwrite(&avgBytesPerSec, 1, 4, m_fileHandle);
            fwrite(&blockAlign, 1, 2, m_fileHandle);
            uint16_t bitsPerSample = 32;
            fwrite(&bitsPerSample, 1, 2, m_fileHandle);
            fwrite("data", 1, 4, m_fileHandle);
            fwrite(&payloadSize, 1, 4, m_fileHandle);
        } else {
            fwrite("RIFF", 1, 4, m_fileHandle);
            uint32_t payloadSize = 0;
            uint32_t riffChunkSize = 60 + payloadSize;
            fwrite(&riffChunkSize, 1, 4, m_fileHandle);
            fwrite("WAVE", 1, 4, m_fileHandle);
            fwrite("fmt ", 1, 4, m_fileHandle);
            uint32_t extSubchunkSize = 40;
            fwrite(&extSubchunkSize, 1, 4, m_fileHandle);
            uint16_t formatTag = 0xFFFE;
            fwrite(&formatTag, 1, 2, m_fileHandle);
            uint16_t numChannels = static_cast<uint16_t>(channelCount);
            fwrite(&numChannels, 1, 2, m_fileHandle);
            uint32_t samplingRate = static_cast<uint32_t>(sampleRate);
            fwrite(&samplingRate, 1, 4, m_fileHandle);
            uint16_t blockAlign = static_cast<uint16_t>(4 * channelCount);
            uint32_t avgBytesPerSec = samplingRate * blockAlign;
            fwrite(&avgBytesPerSec, 1, 4, m_fileHandle);
            fwrite(&blockAlign, 1, 2, m_fileHandle);
            uint16_t bitsPerSample = 32;
            fwrite(&bitsPerSample, 1, 2, m_fileHandle);
            uint16_t extSize = 22;
            fwrite(&extSize, 1, 2, m_fileHandle);
            fwrite(&bitsPerSample, 1, 2, m_fileHandle);
            fwrite(&speakerMask, 1, 4, m_fileHandle);
            fwrite("\x03\x00\x00\x00\x00\x00\x10\x00\x80\x00\x00\xaa\x00\x38\x9b\x71", 1, 16, m_fileHandle);
            fwrite("data", 1, 4, m_fileHandle);
            fwrite(&payloadSize, 1, 4, m_fileHandle);
        }

        m_mixInfo.m_periodFrames = 512;
        m_mixInfo.m_sampleRate = sampleRate;
        m_mixInfo.m_bitsPerSample = 32;
        _buildAudioRenderClient();
    }

    WAVOutputEngine(const char* filePath, double sampleRate, int channelCount) {
        m_fileHandle = fopen(filePath, "wb");
        if (!m_fileHandle)
            return;
        setupWAVFormat(sampleRate, channelCount);
    }

#if _WIN32
    WAVOutputEngine(const wchar_t* filePath, double sampleRate, int channelCount) {
        m_fileHandle = _wfopen(filePath, L"wb");
        if (!m_fileHandle)
            return;
        setupWAVFormat(sampleRate, channelCount);
    }
#endif

    void finalizeWAV() {
        uint32_t actualDataSize = static_cast<uint32_t>(m_totalBytes);

        if (m_mixInfo.m_channelMap.m_channelCount == 2) {
            fseek(m_fileHandle, 4, SEEK_SET);
            uint32_t updatedChunkSize = 36 + actualDataSize;
            fwrite(&updatedChunkSize, 1, 4, m_fileHandle);
            fseek(m_fileHandle, 40, SEEK_SET);
            fwrite(&actualDataSize, 1, 4, m_fileHandle);
        } else {
            fseek(m_fileHandle, 4, SEEK_SET);
            uint32_t updatedChunkSize = 60 + actualDataSize;
            fwrite(&updatedChunkSize, 1, 4, m_fileHandle);
            fseek(m_fileHandle, 64, SEEK_SET);
            fwrite(&actualDataSize, 1, 4, m_fileHandle);
        }

        fclose(m_fileHandle);
    }

    ~WAVOutputEngine() override { finalizeWAV(); }

    void _buildAudioRenderClient() {
        m_5msFrames = static_cast<size_t>(m_mixInfo.m_sampleRate * 5 / 1000);
        m_audioBuffer.resize(m_mixInfo.m_channelMap.m_channelCount * m_5msFrames);
    }

    void _rebuildAudioRenderClient(double sampleRate, size_t periodFrames) {
        m_mixInfo.m_periodFrames = periodFrames;
        m_mixInfo.m_sampleRate = sampleRate;
        _buildAudioRenderClient();
        _resetSampleRate();
    }

    void pumpAndMixVoices() override {
        size_t frameSize = 4 * m_mixInfo.m_channelMap.m_channelCount;
        _pumpAndMixVoices(m_5msFrames, m_audioBuffer.data());
        fwrite(m_audioBuffer.data(), 1, m_5msFrames * frameSize, m_fileHandle);
        m_totalBytes += m_5msFrames * frameSize;
    }
};

