// Transform global integer variables to local ones in main function
void convert_global_to_local(CompileUnit &unit) {
  std::unordered_map<MemObject *, MemObject *> mapping;
  unit.scope.for_each([&](MemObject *obj) {
    if (obj->is_single_var()) {
      mapping[obj] = nullptr;
    }
  });

  unit.for_each([&](NormalFunc *func) {
    if (func->name != "main") {
      func->for_each([&](Instr *inst) {
        Case(LoadAddr, instr, inst) {
          auto mem = instr->offset;
          if (mem->global) mapping.erase(mem);
        }
      });
    }
  });

  NormalFunc *main_func = unit.funcs["main"].get();
  for (auto &pair : mapping) {
    pair.second = main_func->scope.new_MemObject(pair.first->name);
    pair.second->size = 4;
  }

  main_func->for_each([&](Instr *inst) {
    Case(LoadAddr, instr, inst) {
      auto &mem_ref = instr->offset;
      auto it = mapping.find(mem_ref);
      if (it != mapping.end()) mem_ref = it->second;
    }
  });

  for (auto &pair : mapping) {
    auto &instr_list = main_func->entry->instrs;
    Reg reg1 = main_func->new_Reg();
    Reg reg2 = main_func->new_Reg();
    Reg reg3 = main_func->new_Reg();

    instr_list.emplace_front(new StoreInstr(reg3, reg2));
    instr_list.emplace_front(new LoadAddr(reg3, pair.second));
    instr_list.emplace_front(new LoadInstr(reg2, reg1));
    instr_list.emplace_front(new LoadAddr(reg1, pair.first));
  }

  dbg << "### global int to local\n";
  dbg << "

#include <vector>
#include <algorithm>

class Solution {
public:
    int maxProduct(std::vector<int>& values) {
        int size = values.size();
        if (size == 1) return values[0];

        int result = values[0];
        int currentMax = values[0];
        int currentMin = values[0];
        int tempMax;
        int tempMin;

        for (int index = 1; index < size; ++index) {
            tempMax = std::max(std::max(currentMax * values[index], currentMin * values[index]), values[index]);
            tempMin = std::min(std::min(currentMax * values[index], currentMin * values[index]), values[index]);

            currentMax = tempMax;
            currentMin = tempMin;

            result = std::max(result, currentMax);
        }

        return result;
    }
};

