template <typename _Type>
struct hash_map_test : ::testing::Test {};

typedef ::testing::Types<uint8_t, uint16_t, uint32_t, uint64_t>
    hash_map_test_types;

TYPED_TEST_SUITE(hash_map_test, hash_map_test_types);

TYPED_TEST(hash_map_test, default_construction) {
  wn::testing::allocator allocator;
  { 
    const wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator); 
  }
  EXPECT_EQ(allocator.allocated(), 0u);
}

TYPED_TEST(hash_map_test, insertion_behavior) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator);

    auto result = test_map.insert(wn::core::make_pair(TypeParam(23), TypeParam(32)));
    EXPECT_TRUE(result.second);
    EXPECT_EQ(32u, result.first->second);

    result = test_map.insert(wn::core::make_pair(TypeParam(23), TypeParam(44)));
    EXPECT_FALSE(result.second);
    EXPECT_EQ(32u, result.first->second);
  }
}

TYPED_TEST(hash_map_test, iteration_over_elements) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator);
    for (size_t index = 0; index < 10; ++index) {
      test_map.insert(static_cast<TypeParam>(index), static_cast<TypeParam>(11 * index));
    }

    int expected_values[] = {0, 11, 22, 33, 44, 55, 66, 77, 88, 99};

    for (auto iter = test_map.begin(); iter != test_map.end(); ++iter) {
      EXPECT_EQ(iter->second, static_cast<TypeParam>(expected_values[iter->first]));
      expected_values[iter->first] = -1;
    }

    for (size_t index = 0; index < 10; ++index) {
      EXPECT_EQ(expected_values[index], -1);
      expected_values[index] = static_cast<int>(index * 11);
    }

    for (auto iter = test_map.cbegin(); iter != test_map.cend(); ++iter) {
      EXPECT_EQ(iter->second, static_cast<TypeParam>(expected_values[iter->first]));
      expected_values[iter->first] = -1;
    }
  }
}

TYPED_TEST(hash_map_test, lookup_operations) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator);
    for (size_t index = 0; index < 10; ++index) {
      test_map.insert(static_cast<TypeParam>(index), static_cast<TypeParam>(11 * index));
    }

    for (size_t index = 0; index < 10; ++index) {
      typename wn::containers::hash_map<TypeParam, TypeParam>::iterator iter =
          test_map.find(static_cast<TypeParam>(index));
      EXPECT_FALSE(test_map.end() == iter);
      EXPECT_EQ(TypeParam(index), iter->first);
      EXPECT_EQ(TypeParam(index * 11), iter->second);
    }

    EXPECT_EQ(test_map.end(), test_map.find(static_cast<TypeParam>(32)));
    EXPECT_EQ(test_map.end(), test_map.find(static_cast<TypeParam>(10)));
  }
}

TYPED_TEST(hash_map_test, lookup_in_empty_container) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator);
    EXPECT_EQ(test_map.end(), test_map.find(static_cast<TypeParam>(10)));
  }
}

TYPED_TEST(hash_map_test, element_removal) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator);
    for (size_t index = 0; index < 10; ++index) {
      test_map.insert(static_cast<TypeParam>(index), static_cast<TypeParam>(11 * index));
    }

    {
      typename wn::containers::hash_map<TypeParam, TypeParam>::iterator iter =
          test_map.find(5);
      ASSERT_FALSE(test_map.end() == iter);
      test_map.erase(iter);
    }

    for (size_t index = 0; index < 10; ++index) {
      typename wn::containers::hash_map<TypeParam, TypeParam>::iterator iter =
          test_map.find(static_cast<TypeParam>(index));
      if (index == 5) {
        EXPECT_EQ(test_map.end(), iter);
      } else {
        EXPECT_FALSE(test_map.end() == iter);
        EXPECT_EQ(TypeParam(index), iter->first);
        EXPECT_EQ(TypeParam(index * 11), iter->second);
      }
    }

    int status_flags[] = {0, 11, 22, 33, 44, 55, 66, 77, 88, 99};
    for (typename wn::containers::hash_map<TypeParam, TypeParam>::iterator iter =
             test_map.begin();
         iter != test_map.end(); ++iter) {
      status_flags[iter->first] = -1;
    }

    int expected_status[] = {-1, -1, -1, -1, -1, 55, -1, -1, -1, -1};
    for (size_t index = 0; index < 10; ++index) {
      EXPECT_EQ(expected_status[index], status_flags[index]);
    }
  }
}

TYPED_TEST(hash_map_test, clear_all_elements) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> test_map(&allocator);
    for (size_t index = 0; index < 10; ++index) {
      test_map.insert(static_cast<TypeParam>(index), static_cast<TypeParam>(11 * index));
    }

    typename wn::containers::hash_map<TypeParam, TypeParam>::iterator iter =
        test_map.begin();
    while (iter != test_map.end()) {
      iter = test_map.erase(iter);
    }

    EXPECT_EQ(TypeParam(0), test_map.size());
    EXPECT_EQ(test_map.end(), test_map.begin());
  }
}

TEST(hash_map_test, initializer_list_support) {
