TYPED_TEST(hash_map_test, move_semantics_test) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> source_map(&allocator,
        {{TypeParam(221), TypeParam(1)}, {TypeParam(201), TypeParam(2)},
