/// @req
/// @brief This test suite verifies the functionality which is specific to the UnixDomainSocket class
/// @pre server and client object are allocated and moved to the member objects of the fixture
/// @post StdErr is captured and outputted to StdCout
/// @note Most of the UnixDomainSocket functionality is tested in "IpcChannel_test"
class UnixDomainSocket_test : public Test
{
  public:
    void SetUp()
    {
        auto serverResult = UnixDomainSocket::create(
            testSocketName, IpcChannelSide::SERVER, UnixDomainSocket::MAX_MESSAGE_SIZE, MaxMsgNumber);
        ASSERT_THAT(serverResult.has_error(), Eq(false));
        server = std::move(serverResult.value());
        CaptureStderr();
        auto clientResult = UnixDomainSocket::create(
            testSocketName, IpcChannelSide::CLIENT, UnixDomainSocket::MAX_MESSAGE_SIZE, MaxMsgNumber);
        ASSERT_THAT(clientResult.has_error(), Eq(false));
        client = std::move(clientResult.value());
    }

    void TearDown()
    {
        std::string output = GetCapturedStderr();
        if (Test::HasFailure())
        {
            std::cout << output << std::endl;
        }
    }

    ~UnixDomainSocket_test() override
    {
    }

    bool createTestSocket(const UnixDomainSocket::UdsName_t& name)
    {
        static constexpr int32_t FAILURE_CODE = -1;
        struct sockaddr_un socketAddress;
        memset(&socketAddress, 0, sizeof(socketAddress));
        socketAddress.sun_family = AF_LOCAL;
        strncpy(socketAddress.sun_path, name.c_str(), name.size());

        bool socketCreationSuccess = true;

        iox::posix::posixCall(iox_socket)(AF_LOCAL, SOCK_DGRAM, 0)
            .failureReturnValue(FAILURE_CODE)
            .evaluate()
            .and_then([&](auto& r) {
                iox::posix::posixCall(iox_bind)(
                    r.value, reinterpret_cast<struct sockaddr*>(&socketAddress), sizeof(socketAddress))
                    .failureReturnValue(FAILURE_CODE)
                    .evaluate()
                    .or_else([&](auto&) {
                        std::cerr << "unable to bind socket\n";
                        socketCreationSuccess = false;
                    });
            })
            .or_else([&](auto&) {
                std::cerr << "unable to create socket\n";
                socketCreationSuccess = false;
            });

        return socketCreationSuccess;
    }

    void signalThreadReady()
    {
        shouldWaitForThread.store(false, std::memory_order_relaxed);
    }

    void waitForThread()
    {
        while (shouldWaitForThread.load(std::memory_order_relaxed))
        {
            std::this_thread::yield();
        }
    }

    const std::chronomilliseconds WAIT_IN_MS{10};
    std::atomic_bool shouldWaitForThread{true};

    static constexpr uint64_t MaxMsgNumber = 10U;
    UnixDomainSocket server;
    UnixDomainSocket client;
};

