// Recursive function to compute Fibonacci numbers
int fibonacci(int n)
{
    if(n == 1)
        return 0;
    if(n == 2)
        return 1;
    return fibonacci(n-1) + fibonacci(n-2);
}

// Recursive function to compute factorial
int factorial(int n)
{
    cout << n << endl;
    if (n <= 0)
        return 1;
    else 
        return n * factorial(n - 1);
}

int main(){
    int result = factorial(4);
    cout << result << endl;
    result = fibonacci(6);
    cout << result << endl;
   return 0; 
}
