			bool convertBmp32To1BitAlpha(Bmp *sourceBmp32, TPointer<Bmp> &destinationBmp1, int threshold) {
				if(sourceBmp32->getPixelWidth() == 32) {
					uint32_t width, height;

					width = sourceBmp32->getWidth();
					height = sourceBmp32->getHeight();

					destinationBmp1 = Bmp::newImage1Bit(width, height);

					uint32_t x, y;
					BmpRgbQuad color32;
					uint8_t value8;


					color32.rgbBlue = 0;
					color32.rgbGreen = 0;
					color32.rgbRed = 0;
					color32.rgbReserved = 0;
					destinationBmp1->setPaletteIndex(0, color32);
					color32.rgbBlue = 255;
					color32.rgbGreen = 255;
					color32.rgbRed = 255;
					color32.rgbReserved = 0;
					destinationBmp1->setPaletteIndex(1, color32);

					for(y = 0; y < height; y++) {
						for(x = 0; x < width; x++) {
							sourceBmp32->getPixel32(x, y, color32);
							value8 = color32.rgbReserved;
							if(value8 < threshold) {
								value8 = 1;
							} else {
								value8 = 0;
							}
							destinationBmp1->setPixel1(x, y, value8);
						};
					};

					return true;

				};
				return false;
			};

			bool convertBmp32To24And8Alpha(Bmp *sourceBmp32, TPointer<Bmp> &destinationBmp24, TPointer<Bmp> &destinationBmp8) {
				if(sourceBmp32->getPixelWidth() == 32) {
					uint32_t width, height;

					width = sourceBmp32->getWidth();
					height = sourceBmp32->getHeight();

					destinationBmp24 = Bmp::newImage24Bits(width, height);
					destinationBmp8 = Bmp::newImage8Bits(width, height);

					uint32_t x, y;
					BmpRgbQuad color32;
					BmpRgbTriple color24;
					uint8_t value8;


					for(y = 0; y < height; y++) {
						for(x = 0; x < width; x++) {
							sourceBmp32->getPixel32(x, y, color32);
							color24.rgbtBlue = color32.rgbBlue;
							color24.rgbtGreen = color32.rgbGreen;
							color24.rgbtRed = color32.rgbRed;
							destinationBmp24->setPixel24(x, y, color24);
						};
					};


					for(x = 0; x < 256; x++) {
						color32.rgbBlue = (uint8_t)x;
						color32.rgbGreen = (uint8_t)x;
						color32.rgbRed = (uint8_t)x;
						color32.rgbReserved = 0;
						destinationBmp8->setPaletteIndex((uint8_t)x, color32);
					};
					for(y = 0; y < height; y++) {
						for(x = 0; x < width; x++) {
							sourceBmp32->getPixel32(x, y, color32);
							value8 = color32.rgbReserved;
							destinationBmp8->setPixel8(x, y, value8);
						};
					};


					return true;

				};

				return false;
			};

			bool convertBmp32To8And1BitAlpha(Bmp *sourceBmp32, TPointer<Bmp> &destinationBmp8, TPointer<Bmp> &destinationBmp1, int threshold, bool &paletteOverflow) {
				paletteOverflow = false;

				if(sourceBmp32->getPixelWidth() == 32) {
					uint32_t width, height;

					width = sourceBmp32->getWidth();
					height = sourceBmp32->getHeight();

					destinationBmp8 = Bmp::newImage8Bits(width, height);

					uint32_t x, y;
					BmpRgbQuad color32;
					BmpRgbQuad tempColor32;

					uint8_t index8;
					int palettePosition, k;


					palettePosition = 0;
					for(y = 0; y < height; y++) {
						for(x = 0; x < width; x++) {
							sourceBmp32->getPixel32(x, y, color32);

							for(k = 0; k < palettePosition; ++k) {
								destinationBmp8->getPaletteIndex((uint8_t)k, tempColor32);
								if((tempColor32.rgbBlue == color32.rgbBlue)
									&& (tempColor32.rgbGreen == color32.rgbGreen)
									&& (tempColor32.rgbRed == color32.rgbRed)) {
									break;
								};
							};
							if(k < palettePosition) {
								index8 = (uint8_t)k;
							} else {
								if(palettePosition < 256) {
									index8 = (uint8_t)palettePosition;
									color32.rgbReserved = 0;
									destinationBmp8->setPaletteIndex(index8, color32);
									++palettePosition;
								} else {
									paletteOverflow = true;
								};
							};

							destinationBmp8->setPixel8(x, y, index8);
						};
					};


					if(convertBmp32To1BitAlpha(sourceBmp32, destinationBmp1, threshold)) {
						return true;
					};


				};

				return false;
			};


			bool convertBmp32To4And1BitAlpha(Bmp *sourceBmp32, TPointer<Bmp> &destinationBmp4, TPointer<Bmp> &destinationBmp1, int threshold, bool &paletteOverflow) {
				paletteOverflow = false;

				if(sourceBmp32->getPixelWidth() == 32) {
					uint32_t width, height;

					width = sourceBmp32->getWidth();
					height = sourceBmp32->getHeight();

					destinationBmp4 = Bmp::newImage4Bits(width, height);

					uint32_t x, y;
					BmpRgbQuad color32;
					BmpRgbQuad tempColor32;

					uint8_t index4;
					int palettePosition, k;


					palettePosition = 0;
					for(y = 0; y < height; y++) {
						for(x = 0; x < width; x++) {
							sourceBmp32->getPixel32(x, y, color32);

							for(k = 0; k < palettePosition; ++k) {
								destinationBmp4->getPaletteIndex((uint8_t)k, tempColor32);
								if((tempColor32.rgbBlue == color32.rgbBlue)
									&& (tempColor32.rgbGreen == color32.rgbGreen)
									&& (tempColor32.rgbRed == color32.rgbRed)) {
									break;
								};
							};

							if(k < palettePosition) {
								index4 = (uint8_t)k;
							} else {
								if(palettePosition < 16) {
									index4 = (uint8_t)palettePosition;
									color32.rgbReserved = 0;
									destinationBmp4->setPaletteIndex(index4, color32);
									++palettePosition;
								} else {
									paletteOverflow = true;
								};
							};

							destinationBmp4->setPixel4(x, y, index4);
						};
					};


					if(convertBmp32To1BitAlpha(sourceBmp32, destinationBmp1, threshold)) {
						return true;
					};



				};
				return false;
			};


			TPointer<Bmp> extractAlphaToBmp8(Image *sourceImage) {
				uint32_t width, height;

				width = sourceImage->width;
				height = sourceImage->height;
				uint8_t value8;

				TPointer<Bmp> destinationBmp8 = Bmp::newImage8Bits(width, height);
				uint32_t x, y, pixelValue;
				int paletteIndex;
				BmpRgbQuad paletteEntry;
				for(paletteIndex = 0; paletteIndex < 256; ++paletteIndex) {
					paletteEntry.rgbBlue = 0x00;
					paletteEntry.rgbGreen = 0x00;
					paletteEntry.rgbRed = 0x00;
					paletteEntry.rgbReserved = paletteIndex;
					destinationBmp8->setPaletteIndex(paletteIndex, paletteEntry);
				};

				for(y = 0; y < height; ++y) {
					for(x = 0; x < width; ++x) {
						value8 = XYO_PIXEL32_A(sourceImage->pixel[height - y - 1][x]);
						destinationBmp8->setPixel8(x, y, value8);
					};
				};
				return destinationBmp8;
			};


			TPointer<Bmp> extractAlphaToBmp1(Image *sourceImage, int threshold) {
				uint32_t width, height;

				width = sourceImage->width;
				height = sourceImage->height;
				BmpRgbQuad paletteEntry;

				TPointer<Bmp> destinationBmp1;

				destinationBmp1 = Bmp::newImage1Bit(width, height);
				paletteEntry.rgbBlue = 0x00;
				paletteEntry.rgbGreen = 0x00;
				paletteEntry.rgbRed = 0x00;
				paletteEntry.rgbReserved = 0x00;
				destinationBmp1->setPaletteIndex(0, paletteEntry);
				paletteEntry.rgbBlue = 0xFF;
				paletteEntry.rgbGreen = 0xFF;
				paletteEntry.rgbRed = 0xFF;
				paletteEntry.rgbReserved = 0x00;
				destinationBmp1->setPaletteIndex(1, paletteEntry);

				uint32_t x, y;
				uint8_t pixelValue;

				for(y = 0; y < height; ++y) {
					for(x = 0; x < width; ++x) {
						if(XYO_PIXEL32_A(sourceImage->pixel[height - y - 1][x]) < threshold) {
							pixelValue = 1;
						} else {
							pixelValue = 0;
						}
						destinationBmp1->setPixel1(x, y, pixelValue);
					};
				};

				return destinationBmp1;
			};


			TPointer<Bmp> convertToBmp24(Image *sourceImage) {
				uint32_t width, height;

				width = sourceImage->width;
				height = sourceImage->height;

				TPointer<Bmp> destinationBmp24 = Bmp::newImage24Bits(width, height);
				uint32_t x, y, pixelValue;
				BmpRgbTriple color;
				for(y = 0; y < height; ++y) {
					for(x = 0; x < width; ++x) {
						pixelValue = sourceImage->pixel[height - y - 1][x];
						color.rgbtRed = XYO_PIXEL32_R(pixelValue);
						color.rgbtGreen = XYO_PIXEL32_G(pixelValue);
						color.rgbtBlue = XYO_PIXEL32_B(pixelValue);
						destinationBmp24->setPixel24(x, y, color);
					};
				};
				return destinationBmp24;
			};

			TPointer<Bmp> convertToBmp32(Image *sourceImage) {
				uint32_t width, height;

				width = sourceImage->width;
				height = sourceImage->height;

				TPointer<Bmp> destinationBmp32 = Bmp::newImage32Bits(width, height);
				uint32_t x, y, pixelValue;
				BmpRgbQuad color;
				for(y = 0; y < height; ++y) {
					for(x = 0; x < width; ++x) {
						pixelValue = sourceImage->pixel[height - y - 1][x];
						color.rgbRed = XYO_PIXEL32_R(pixelValue);
						color.rgbGreen = XYO_PIXEL32_G(pixelValue);
						color.rgbBlue = XYO_PIXEL32_B(pixelValue);
						color.rgbReserved = XYO_PIXEL32_A(pixelValue);
						destinationBmp32->setPixel32(x, y, color);
					};
				};
				return destinationBmp32;
			};


		};
	};
