    void GapVisualizer::renderGap(visualization_msgs::MarkerArray & marker_array, potential_gap::Gap gap_data, std::string ns, std::string color) {
        if (!cfg_->gap_viz.debug_viz) return;

        int offset = 0;
        double jitter = cfg_->gap_viz.viz_jitter;
        if (jitter > 0 && gap_data.isAxial()) {
            offset = gap_data.isLeftType() ? -2 : 2;
        }

        int num_segments = (gap_data._right_idx - gap_data._left_idx) / cfg_->gap_viz.min_resoln + 1;
        float distance_increment = (gap_data._rdist - gap_data._ldist) / num_segments;
        int current_left_idx = gap_data._left_idx + offset;
        float current_left_dist = gap_data._ldist;

        visualization_msgs::Marker marker;
        marker.header.frame_id = gap_data._frame;
        marker.header.stamp = ros::Time();
        marker.ns = ns;
        marker.type = visualization_msgs::Marker::LINE_STRIP;
        marker.action = visualization_msgs::Marker::ADD;

        std::string local_ns = ns;
        if (gap_data.isAxial()) {
            local_ns += "_axial";
        } else {
            local_ns += "_radial";
        }

        auto color_it = colormap.find(local_ns);
        if (color_it == colormap.end()) {
            ROS_FATAL_STREAM("Visualization Color not found, return without drawing");
            return;
        }

        marker.colors = color_it->second;
        double line_width = cfg_->gap_viz.fig_gen ? 0.05 : 0.01;
        marker.scale.x = line_width;
        marker.scale.y = 0.1;
        marker.scale.z = 0.1;

        bool is_final_namespace = (ns == "fin");

        geometry_msgs::Point pt_start;
        geometry_msgs::Point pt_end;
        std::vector<geometry_msgs::Point> points;

        if (is_final_namespace) {
            marker.colors[0].a = 1.0;
            marker.colors[1].a = 1.0;
            pt_start.z = 0.1;
            pt_end.z = 0.1;
        }

        int marker_id = static_cast<int>(marker_array.markers.size());

        for (int i = 0; i < num_segments - 1; ++i) {
            points.clear();

            pt_start.x = (current_left_dist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - current_left_idx) / gap_data.half_scan * M_PI);
            pt_start.y = (current_left_dist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - current_left_idx) / gap_data.half_scan * M_PI);

            current_left_idx += cfg_->gap_viz.min_resoln;
            current_left_dist += distance_increment;

            pt_end.x = (current_left_dist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - current_left_idx) / gap_data.half_scan * M_PI);
            pt_end.y = (current_left_dist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - current_left_idx) / gap_data.half_scan * M_PI);

            points.push_back(pt_start);
            points.push_back(pt_end);

            marker.points = points;
            marker.id = marker_id++;
            marker.lifetime = ros::Duration(gap_data.life_time);
            marker_array.markers.push_back(marker);
        }

        // Final segment
        points.clear();
        pt_start.x = (current_left_dist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - current_left_idx) / gap_data.half_scan * M_PI);
        pt_start.y = (current_left_dist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - current_left_idx) / gap_data.half_scan * M_PI);
        pt_end.x = (gap_data._rdist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - gap_data._right_idx) / gap_data.half_scan * M_PI);
        pt_end.y = (gap_data._rdist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - gap_data._right_idx) / gap_data.half_scan * M_PI);

        points.push_back(pt_start);
        points.push_back(pt_end);
        marker.points = points;
        marker.id = marker_id++;
        marker.lifetime = ros::Duration(gap_data.life_time);
        marker_array.markers.push_back(marker);
    }

    void GapVisualizer::renderGaps(std::vector<potential_gap::Gap> gaps, std::string ns, std::string color) {
        if (!cfg_->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray marker_array;
        for (auto & gap : gaps) {
            renderGap(marker_array, gap, ns);
        }
        gaparc_publisher.publish(marker_array);
    }

    void GapVisualizer::renderManipulatedGap(visualization_msgs::MarkerArray & marker_array, potential_gap::Gap gap_data, bool & circle_flag) {
        if (!cfg_->gap_viz.debug_viz) return;
        if (!gap_data.mode.reduced && !gap_data.mode.convex && !gap_data.mode.agc) {
            return;
        }

        float jitter = static_cast<float>(cfg_->gap_viz.viz_jitter);
        int offset = 0;
        if (jitter > 0 && gap_data.isAxial()) {
            offset = gap_data.isLeftType() ? -2 : 2;
        }

        std::string ns;
        if (gap_data.mode.reduced) {
            ns = "final_radial";
            jitter += 0.1f;
        }

        if (gap_data.mode.convex) {
            ns = "final_extent";
        }

        if (gap_data.mode.agc) {
            ns = "final_agc";
        }

        int num_segments = (gap_data.convex.convex_ridx - gap_data.convex.convex_lidx) / cfg_->gap_viz.min_resoln + 1;
        float dist_step = (gap_data.convex.convex_rdist - gap_data.convex.convex_ldist) / num_segments;
        int idx = gap_data.convex.convex_lidx + offset;
        float dist = gap_data.convex.convex_ldist;

        visualization_msgs::Marker marker;
        marker.header.frame_id = gap_data._frame;
        marker.header.stamp = ros::Time();
        marker.ns = ns;
        marker.type = visualization_msgs::Marker::LINE_STRIP;
        marker.action = visualization_msgs::Marker::ADD;

        auto color_it = colormap.find(ns);
        if (color_it == colormap.end()) {
            ROS_FATAL_STREAM("[drawManipGaps] Visualization Color not found, return without drawing");
            return;
        }

        marker.colors = color_it->second;
        double thickness = cfg_->gap_viz.fig_gen ? 0.05 : 0.01;
        marker.scale.x = thickness;
        marker.scale.y = 0.1;
        marker.scale.z = 0.1;

        geometry_msgs::Point p1;
        geometry_msgs::Point p2;
        p1.z = 0.1;
        p2.z = 0.1;

        std::vector<geometry_msgs::Point> pts;
        int id = static_cast<int>(marker_array.markers.size());
        marker.lifetime = ros::Duration(0.25);

        for (int i = 0; i < num_segments - 1; ++i) {
            pts.clear();
            p1.x = (dist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - idx) / gap_data.half_scan * M_PI);
            p1.y = (dist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - idx) / gap_data.half_scan * M_PI);
            idx += cfg_->gap_viz.min_resoln;
            dist += dist_step;
            p2.x = (dist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - idx) / gap_data.half_scan * M_PI);
            p2.y = (dist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - idx) / gap_data.half_scan * M_PI);

            pts.push_back(p1);
            pts.push_back(p2);
            marker.points = pts;
            marker.id = id++;
            marker_array.markers.push_back(marker);
        }

        // Final segment
        pts.clear();
        p1.x = (dist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - idx) / gap_data.half_scan * M_PI);
        p1.y = (dist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - idx) / gap_data.half_scan * M_PI);
        p2.x = (gap_data.convex.convex_rdist + jitter) * cos(-(static_cast<float>(gap_data.half_scan) - gap_data.convex.convex_ridx) / gap_data.half_scan * M_PI);
        p2.y = (gap_data.convex.convex_rdist + jitter) * sin(-(static_cast<float>(gap_data.half_scan) - gap_data.convex.convex_ridx) / gap_data.half_scan * M_PI);

        pts.push_back(p1);
        pts.push_back(p2);
        marker.points = pts;
        marker.id = id++;
        marker.lifetime = ros::Duration(gap_data.life_time);
        marker_array.markers.push_back(marker);

        if (gap_data.mode.convex) {
            float radius = gap_data.getMinSafeDist();
            if (radius < 0) {
                ROS_WARN_STREAM("Gap min safe dist not recorded");
            }

            auto convex_color = colormap["final_extent"];
            marker.ns = "final_extent";

            if (!circle_flag) {
                for (int i = 0; i < 50; ++i) {
                    pts.clear();
                    p1.x = radius * cos(M_PI / 25.0f * static_cast<float>(i));
                    p1.y = radius * sin(M_PI / 25.0f * static_cast<float>(i));
                    p2.x = radius * cos(M_PI / 25.0f * static_cast<float>(i + 1));
                    p2.y = radius * sin(M_PI / 25.0f * static_cast<float>(i + 1));

                    pts.push_back(p1);
                    pts.push_back(p2);
                    marker.points = pts;
                    marker.colors = convex_color;
                    marker.id = id++;
                    marker.lifetime = ros::Duration();
                    marker_array.markers.push_back(marker);
                }
                circle_flag = true;
            }

            auto drawLine = [] (int index, float distance,
                                Eigen::Vector2f& pointB,
                                std::vector<geometry_msgs::Point>& lines,
                                geometry_msgs::Point& pt1,
                                geometry_msgs::Point& pt2,
                                visualization_msgs::Marker& marker_obj,
                                std::vector<std_msgs::ColorRGBA> & color_vec,
                                visualization_msgs::MarkerArray& marker_arr,
                                int half_scan_count,
                                int marker_id
                                ) -> void {
                                    lines.clear();
                                    pt1.x = pointB(0);
                                    pt1.y = pointB(1);
                                    pt1.z = 0.1;
                                    pt2.x = distance * cos(M_PI / half_scan_count * (index - half_scan_count));
                                    pt2.y = distance * sin(M_PI / half_scan_count * (index - half_scan_count));
                                    pt2.z = 0.1;
                                    lines.push_back(pt1);
                                    lines.push_back(pt2);
                                    marker_obj.points = lines;
                                    marker_obj.colors = color_vec;
                                    marker_obj.id = marker_id;
                                    marker_obj.lifetime = ros::Duration(0.2);
                                    marker_arr.markers.push_back(marker_obj);
                                };

            {
                marker.ns = "extent_line";
                drawLine(gap_data.convex.convex_lidx, gap_data.convex.convex_ldist, gap_data.qB,
                    pts, p1, p2, marker, convex_color, marker_array, gap_data.half_scan, id++);
                drawLine(gap_data.convex.convex_ridx, gap_data.convex.convex_rdist, gap_data.qB,
                    pts, p1, p2, marker, convex_color, marker_array, gap_data.half_scan, id++);
                Eigen::Vector2f origin_point(0, 0);
                marker.ns = "orig_line";
                drawLine(gap_data._left_idx, gap_data._ldist, origin_point,
                    pts, p1, p2, marker, colormap["final_agc"], marker_array, gap_data.half_scan, id++);
                drawLine(gap_data._right_idx, gap_data._rdist, origin_point,
                    pts, p1, p2, marker, colormap["final_agc"], marker_array, gap_data.half_scan, id++);
            }
        }
    }

    void GapVisualizer::renderManipulatedGaps(std::vector<potential_gap::Gap> vec) {
        if (!cfg_->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray marker_array;
        bool circle_flag = false;
        for (auto & gap : vec) {
            renderManipulatedGap(marker_array, gap, circle_flag);
        }
        gapside_publisher.publish(marker_array);
    }

    TrajectoryVisualizer::TrajectoryVisualizer(ros::NodeHandle& nh, const potential_gap::PotentialGapConfig& cfg)
    {
        cfg_ = &cfg;
        goal_selector_traj_vis = nh.advertise<geometry_msgs::PoseArray>("goal_select_traj", 1000);
        trajectory_score = nh.advertise<visualization_msgs::MarkerArray>("traj_score", 1000);
        all_traj_viz = nh.advertise<visualization_msgs::MarkerArray>("all_traj_vis", 1000);
    }

    void TrajectoryVisualizer::globalPlanRbtFrame(const std::vector<geometry_msgs::PoseStamped> & plan) {
        if (!cfg_->gap_viz.debug_viz) return;
        if (plan.size() < 1) {
            ROS_WARN_STREAM("Goal Selector Returned Trajectory Size " << plan.size() << " < 1");
        }
        geometry_msgs::PoseArray vis_arr;
        vis_arr.header = plan.at(0).header;
        for (auto & pose : plan) {
            vis_arr.poses.push_back(pose.pose);
        }
        goal_selector_traj_vis.publish(vis_arr);
    }

    void TrajectoryVisualizer::trajScore(geometry_msgs::PoseArray p_arr, std::vector<double> p_score) {
        if (!cfg_->gap_viz.debug_viz) return;
        ROS_FATAL_STREAM_COND(!p_score.size() == p_arr.poses.size(), "trajScore size mismatch, p_arr: "
            << p_arr.poses.size() << ", p_score: " << p_score.size());
        visualization_msgs::MarkerArray score_arr;
        visualization_msgs::Marker text_marker;
        text_marker.header.frame_id = p_arr.header.frame_id;
        text_marker.header.stamp = ros::Time::now();
        text_marker.ns = "trajScore";
        text_marker.type = visualization_msgs::Marker::TEXT_VIEW_FACING;
        text_marker.action = visualization_msgs::Marker::ADD;
        text_marker.pose.orientation.w = 1;
        text_marker.scale.x = 0.1;
        text_marker.scale.y = 0.1;
        text_marker.scale.z = 0.1;
        text_marker.color.a = 1;
        text_marker.color.r = 1;
        text_marker.color.g = 1;
        text_marker.color.b = 1;
        for (int i = 0; i < p_score.size(); i++) {
            text_marker.id = static_cast<int>(score_arr.markers.size());
            text_marker.pose.position.x = p_arr.poses.at(i).position.x;
            text_marker.pose.position.y = p_arr.poses.at(i).position.y;
            text_marker.pose.position.z = 0.5;
            text_marker.text = std::to_string(p_score.at(i));
            score_arr.markers.push_back(text_marker);
        }
        trajectory_score.publish(score_arr);
    }

    void TrajectoryVisualizer::pubAllScore(std::vector<geometry_msgs::PoseArray> prr, std::vector<std::vector<double>> cost) {
        if (!cfg_->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray score_arr;
        visualization_msgs::Marker text_marker;
        if (prr.size() == 0)
        {
            ROS_WARN_STREAM("traj count length 0");
            return;
        }
        text_marker.header.frame_id = prr.at(0).header.frame_id;
        text_marker.header.stamp = ros::Time::now();
        text_marker.ns = "trajScore";
        text_marker.type = visualization_msgs::Marker::TEXT_VIEW_FACING;
        text_marker.action = visualization_msgs::Marker::ADD;
        text_marker.pose.orientation.w = 1;
        text_marker.scale.x = 0.1;
        text_marker.scale.y = 0.1;
        text_marker.scale.z = 0.05;
        text_marker.color.a = 1;
        text_marker.color.r = 1;
        text_marker.color.g = 1;
        text_marker.color.b = 1;
        text_marker.lifetime = ros::Duration(0.25);
        ROS_FATAL_STREAM_COND(!prr.size() == cost.size(), "pubAllScore size mismatch, prr: "
            << prr.size() << ", cost: " << cost.size());
        for (int i = 0; i < prr.size(); i++) {
            ROS_FATAL_STREAM_COND(!prr.at(i).poses.size() == cost.at(i).size(), "pubAllScore size mismatch," << i << "th "
                << prr.at(i).poses.size() << ", cost: " << cost.at(i).size());

            for (int j = 0; j < prr.at(i).poses.size(); j++) {
                text_marker.id = static_cast<int>(score_arr.markers.size());
                text_marker.pose = prr.at(i).poses.at(j);
                std::stringstream stream;
                stream << std::fixed << std::setprecision(2) << cost.at(i).at(j);
                text_marker.text = stream.str();
                score_arr.markers.push_back(text_marker);
            }
        }
        trajectory_score.publish(score_arr);
    }

    void TrajectoryVisualizer::pubAllTraj(std::vector<geometry_msgs::PoseArray> prr) {
        if (!cfg_->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray traj_arr;
        visualization_msgs::Marker arrow_marker;
        if (prr.size() == 0)
        {
            ROS_WARN_STREAM("traj count length 0");
            return;
        }
        arrow_marker.header.frame_id = prr.at(0).header.frame_id;
        arrow_marker.header.stamp = ros::Time::now();
        arrow_marker.ns = "allTraj";
        arrow_marker.type = visualization_msgs::Marker::ARROW;
        arrow_marker.action = visualization_msgs::Marker::ADD;
        arrow_marker.scale.x = 0.1;
        arrow_marker.scale.y = cfg_->gap_viz.fig_gen ? 0.02 : 0.01;
        arrow_marker.scale.z = 0.1;
        arrow_marker.color.a = 1;
        arrow_marker.color.r = 0.5;
        arrow_marker.color.g = 0.5;
        arrow_marker.lifetime = ros::Duration(0.25);
        for (auto & arr : prr) {
            for (auto pose : arr.poses) {
                arrow_marker.id = static_cast<int>(traj_arr.markers.size());
                arrow_marker.pose = pose;
                traj_arr.markers.push_back(arrow_marker);
