#include "ArmCollisionDetector2018.h"
#include <PlatformInterface/Platform.h>
#include "Tools/Math/Polygon.h"
using namespace naoth;

ArmCollisionDetector2018::ArmCollisionDetector2018()
{
    // Initialize debug parameters
    getDebugParameterList().add(&params);

    double alpha, beta;
    const std::string& configDir = Platform::getInstance().theConfigDirectory;

    // Load left arm collision hull points
    std::ifstream inputFileLeft(configDir + params.point_configLeft);
    while (inputFileLeft >> alpha >> beta) {
        getCollisionPercept().referenceHullLeft.emplace_back(alpha, beta);
    }
    inputFileLeft.close();

    // Load right arm collision hull points
    std::ifstream inputFileRight(configDir + params.point_configRight);
    while (inputFileRight >> alpha >> beta) {
        getCollisionPercept().referenceHullRight.emplace_back(alpha, beta);
    }
    inputFileRight.close();

    // Compute convex hulls for both arms
    getCollisionPercept().referenceHullLeft = ConvexHull::convexHull(getCollisionPercept().referenceHullLeft);
    getCollisionPercept().referenceHullRight = ConvexHull::convexHull(getCollisionPercept().referenceHullRight);

    // Build polygon representations
    refpolyL.makeFromPointSet(getCollisionPercept().referenceHullLeft);
    refpolyR.makeFromPointSet(getCollisionPercept().referenceHullRight);
}

ArmCollisionDetector2018::~ArmCollisionDetector2018()
{
    getDebugParameterList().remove(&params);
}

void ArmCollisionDetector2018::execute()
{
    // Determine if robot is in appropriate state for collision detection
    const bool bodyConditionOK = getBodyState().fall_down_state != BodyState::upright;
    const bool armConditionOK =
        getMotionRequest().armMotionRequest.id == ArmMotionRequest::arms_synchronised_with_walk ||
        getMotionRequest().armMotionRequest.id == ArmMotionRequest::arms_down;
    const bool motionConditionOK = getMotionStatus().currentMotion == motion::walk || getMotionStatus().currentMotion == motion::stand;

    // Reset buffers when conditions are not met to avoid false positives during evasive actions
    if (!armConditionOK || !motionConditionOK || !bodyConditionOK)
    {
        jointDataBufferLeft.clear();
        jointDataBufferRight.clear();
        collisionBufferLeft.clear();
        collisionBufferRight.clear();
        collisionBufferLeftRoll.clear();
        collisionBufferRightRoll.clear();
        return;
    }

    // Collect motor joint data and compensate for timing offset (motor data leads sensor by 4 frames)
    jointDataBufferLeft.add(getMotorJointData().position[JointData::LShoulderPitch]);
    jointDataBufferRight.add(getMotorJointData().position[JointData::RShoulderPitch]);
    jointDataBufferLeftRoll.add(getMotorJointData().position[JointData::LShoulderRoll]);
    jointDataBufferRightRoll.add(getMotorJointData().position[JointData::RShoulderRoll]);

    // Adjust sensitivity based on arm position: arms_down mode uses stricter threshold
    if (getMotionRequest().armMotionRequest.id == ArmMotionRequest::arms_down)
    {
        // Process left arm shoulder pitch error
        if (jointDataBufferLeft.isFull()) {
            double diff = jointDataBufferLeft.first() - getSensorJointData().position[JointData::LShoulderPitch];
            collisionBufferLeft.add(std::fabs(diff));
        }

        // Process right arm shoulder pitch error
        if (jointDataBufferRight.isFull()) {
            double diff = jointDataBufferRight.first() - getSensorJointData().position[JointData::RShoulderPitch];
            collisionBufferRight.add(std::fabs(diff));
        }

        double threshold = params.maxErrorStand;

        // Detect left arm collision
        if (collisionBufferLeft.isFull() && collisionBufferLeft.getAverage() > threshold) {
            getCollisionPercept().timeCollisionArmLeft = getFrameInfo().getTime();
            jointDataBufferLeft.clear();
            collisionBufferLeft.clear();
        }

        // Detect right arm collision
        if (collisionBufferRight.isFull() && collisionBufferRight.getAverage() > threshold) {
            getCollisionPercept().timeCollisionArmRight = getFrameInfo().getTime();
            jointDataBufferRight.clear();
            collisionBufferRight.clear();
        }
        return;
    }
    else
    {
        // Clear pitch-specific buffers when not in arms_down mode
        collisionBufferLeft.clear();
        collisionBufferRight.clear();
    }

    // Handle shoulder roll collision detection
    if (jointDataBufferLeftRoll.isFull()) {
        double diff = jointDataBufferLeftRoll.first() - getSensorJointData().position[JointData::LShoulderRoll];
        collisionBufferLeftRoll.add(diff);
    }
    if (jointDataBufferRightRoll.isFull()) {
        double diff = jointDataBufferRightRoll.first() - getSensorJointData().position[JointData::RShoulderRoll];
        collisionBufferRightRoll.add(diff);
    }

    double rollThreshold = params.armRollError;

    // Check for left roll collision
    if (collisionBufferLeftRoll.isFull() && std::fabs(collisionBufferLeftRoll.getAverage()) > rollThreshold) {
        getCollisionPercept().timeCollisionArmLeft = getFrameInfo().getTime();
        jointDataBufferLeftRoll.clear();
        collisionBufferLeftRoll.clear();
    }

    // Check for right roll collision
    if (collisionBufferRightRoll.isFull() && std::fabs(collisionBufferRightRoll.getAverage()) > rollThreshold) {
        getCollisionPercept().timeCollisionArmRight = getFrameInfo().getTime();
        jointDataBufferRightRoll.clear();
        collisionBufferRightRoll.clear();
    }

    // Polygon-based collision detection method
    if (jointDataBufferLeft.isFull())
    {
        double motorAngle = jointDataBufferLeft.first();
        double sensorAngle = getSensorJointData().position[JointData::LShoulderPitch];
        double error = sensorAngle - motorAngle; // negative: collision from behind, positive: from front

        if (!refpolyL.isInside(Vector2d(motorAngle, error)))
        {
            // Collision detected
            if (error < 0)
            {
                getCollisionPercept().lastCollisionDirection = "Back";
            }
            else
            {
                getCollisionPercept().lastCollisionDirection = "Front";
            }
            getCollisionPercept().timeCollisionArmLeft = getFrameInfo().getTime();
            jointDataBufferLeft.clear();
        }
    }

    if (jointDataBufferRight.isFull())
    {
        double motorAngle = jointDataBufferRight.first();
        double sensorAngle = getSensorJointData().position[JointData::RShoulderPitch];
        double error = sensorAngle - motorAngle; // negative: collision from behind, positive: from front

        if (!refpolyR.isInside(Vector2d(motorAngle, error)))
        {
            // Collision detected
            if (error < 0)
            {
                getCollisionPercept().lastCollisionDirection = "Back";
            }
            else
            {
                getCollisionPercept().lastCollisionDirection = "Front";
            }
            getCollisionPercept().timeCollisionArmRight = getFrameInfo().getTime();
            jointDataBufferRight.clear();
        }
    }
}

