// Adjusts wheel speeds to move forward when no obstacles are nearby and reverse
// direction when sensors detect proximity to another robot
WheelVelocity Explore::CalcWheelVelocity(double sensor_left,
  double sensor_right) {
  return WheelVelocity(MAX_READING - sensor_right,
    MAX_READING - sensor_left);
}
// Combines light avoidance and food-seeking behaviors: the robot steers away
// from bright lights while moving toward food sources
WheelVelocity Explore::CalcWheelVelocityWFood(double left_light,
  double right_light, double left_nutrient,
  double right_nutrient) {
  return WheelVelocity(((MAX_READING - right_light) * 0.5) +
    (right_nutrient * 0.5), ((MAX_READING - left_light) * 0.5) +
    (left_nutrient * 0.5));
}
