#include "include/BER.h"

// Two methods to parse long-form integers: one using leading length byte, another via base-128 encoding
static size_t parse_ber_extended_integer(const uint8_t* buffer, long* result_value, int max_bytes) {
    int index = 1;
    long accumulated = 0;
    while (*buffer >= 128 && index < max_bytes && accumulated < INT_MAX) {
        accumulated += (*buffer & 0x7F);
        accumulated *= 128;
        ++buffer;
        ++index;
    }
    accumulated += *buffer; // final octet
    *result_value = accumulated;
    return index;
}

static size_t parse_ber_size_integer(const uint8_t* buffer, int* out_value, int) {
    if (*buffer <= 127) {
        *out_value = *buffer;
        return 1;
    } else {
        int byte_count = *buffer & 0x7F;
        int extended_length = 0;
        for (int j = 0; j < byte_count; ++j) {
            ++buffer;
            extended_length <<= 8;
            extended_length |= *buffer;
        }
        *out_value = extended_length;
        return byte_count + 1;
    }
}

int BER_CONTAINER::fromBuffer(const uint8_t *input, size_t limit) {
    if (limit < 2) return SNMP_BUFFER_ERROR_TLV_TOO_SMALL;

    const uint8_t* cursor = input;
    if (*cursor != _type) {
        SNMP_LOGE("Type mismatch during decode: expected %d, got %d\n", _type, *cursor);
        return SNMP_BUFFER_ERROR_TYPE_MISMATCH;
    }

    ++cursor; // skip type field
    cursor += parse_ber_size_integer(cursor, &_length, static_cast<int>(limit));

    if (static_cast<size_t>(_length) + 2 > limit) {
        return SNMP_BUFFER_ERROR_MAX_LEN_EXCEEDED;
    }

    return cursor - input;
}

int NetworkAddress::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* cursor = input + consumed;
    _value = IPAddress(cursor);
    return cursor - input;
}

int IntegerType::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* cursor = input + consumed;
    unsigned short remaining = _length;
    uint32_t temp = 0;

    while (remaining > 0) {
        temp <<= 8;
        temp |= *cursor++;
        --remaining;
    }

    switch (_length) {
        case 1:
            _value = static_cast<int8_t>(temp);
            break;
        case 2:
            _value = static_cast<int16_t>(temp);
            break;
        case 3:
            if (temp & 0x00800000) {
                temp |= 0xFF000000;
            }
            _value = static_cast<int32_t>(temp);
            break;
        default:
            _value = static_cast<int32_t>(temp);
    }

    return cursor - input;
}

int OctetType::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* cursor = input + consumed;
    if (_length > OCTET_TYPE_MAX_LENGTH) return SNMP_BUFFER_ERROR_OCTET_TOO_BIG;

    _value.assign(reinterpret_cast<const char*>(cursor), _length);
    return _length + consumed;
}

int OpaqueType::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* cursor = input + consumed;
    _value = static_cast<uint8_t*>(calloc(_length, sizeof(char)));
    memcpy(_value, cursor, _length);
    _dataLength = _length;
    return _length + consumed;
}

int OIDType::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* data = input + consumed;
    if (*data != 0x2b) return SNMP_BUFFER_ERROR_INVALID_OID;

    this->data.reserve(_length);
    this->data.assign(data, data + _length);
    this->valid = true;
    return _length + 2;
}

static inline void integer_to_string(char* buffer, long value, short depth = 0) {
    if (value > 9) {
        integer_to_string(buffer++, value / 10L, depth + 1);
    }
    *buffer++ = static_cast<char>(value % 10 + '0');
    if (!depth) *buffer = '\0';
}

const std::string& OIDType::string() {
    if (!_value.length()) {
        const uint8_t* data = this->data.data();
        this->_value = ".1.3";
        if (!this->valid) return this->_value;

        ++data;
        int remaining = this->data.size() - 1;
        char temp[16];

        while (remaining > 0) {
            memset(temp, 0, sizeof(temp));
            long component = 0;
            int len = parse_ber_extended_integer(data, &component, remaining);
            data += len;
            remaining -= len;

            temp[0] = '.';
            integer_to_string(temp + 1, component);
            this->_value.append(temp);
        }
    }
    return this->_value;
}

const std::vector<unsigned long> SortableOIDType::generateSortingMap() const {
    auto map = std::vector<unsigned long>();
    map.reserve(this->data.size());

    const uint8_t* cursor = this->data.data();
    ++cursor;
    int remaining = this->data.size() - 1;

    while (remaining > 0) {
        long component;
        size_t len = parse_ber_extended_integer(cursor, &component, remaining);
        cursor += len;
        remaining -= len;
        map.push_back(static_cast<unsigned long>(component));
    }

    return map;
}

int NullType::fromBuffer(const uint8_t *, size_t) {
    _length = 0;
    return 2;
}

int Counter64::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* cursor = input + consumed;
    int bytes_left = _length;
    _value = 0;

    while (bytes_left > 0) {
        _value <<= 8U;
        _value |= *cursor++;
        --bytes_left;
    }

    return _length + 2;
}

std::shared_ptr<BER_CONTAINER> ComplexType::createObjectForType(ASN_TYPE kind) {
    SNMP_LOGD("Instantiating object of type: %d\n", kind);
    switch (kind) {
        case INTEGER:
            return std::shared_ptr<BER_CONTAINER>(new IntegerType());
        case STRING:
            return std::shared_ptr<BER_CONTAINER>(new OctetType());
        case OID:
            return std::shared_ptr<BER_CONTAINER>(new OIDType());
        case NULLTYPE:
            return std::shared_ptr<BER_CONTAINER>(new NullType());
        case NOSUCHOBJECT:
            return std::shared_ptr<BER_CONTAINER>(new ImplicitNullType(NOSUCHOBJECT));
        case NOSUCHINSTANCE:
            return std::shared_ptr<BER_CONTAINER>(new ImplicitNullType(NOSUCHINSTANCE));
        case ENDOFMIBVIEW:
            return std::shared_ptr<BER_CONTAINER>(new ImplicitNullType(ENDOFMIBVIEW));
        case NETWORK_ADDRESS:
            return std::shared_ptr<BER_CONTAINER>(new NetworkAddress());
        case TIMESTAMP:
            return std::shared_ptr<BER_CONTAINER>(new TimestampType());
        case COUNTER32:
            return std::shared_ptr<BER_CONTAINER>(new Counter32());
        case GUAGE32:
            return std::shared_ptr<BER_CONTAINER>(new Guage());
        case COUNTER64:
            return std::shared_ptr<BER_CONTAINER>(new Counter64());
        case OPAQUE:
            return std::shared_ptr<BER_CONTAINER>(new OpaqueType());
        case STRUCTURE:
        case GetRequestPDU:
        case GetNextRequestPDU:
        case GetResponsePDU:
        case SetRequestPDU:
        case GetBulkRequestPDU:
        case InformRequestPDU:
        case Trapv2PDU:
            return std::shared_ptr<BER_CONTAINER>(new ComplexType(kind));
        default:
            return nullptr;
    }
}

int ComplexType::fromBuffer(const uint8_t *input, size_t limit) {
    int consumed = BER_CONTAINER::fromBuffer(input, limit);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* cursor = input + consumed;
    size_t processed = 1;

    while (processed < static_cast<size_t>(_length) && processed <= limit) {
        ASN_TYPE kind = static_cast<ASN_TYPE>(*cursor);
        auto child = ComplexType::createObjectForType(kind);
        if (!child) {
            SNMP_LOGD("Failed to instantiate type: %d\n", kind);
            return SNMP_BUFFER_ERROR_UNKNOWN_TYPE;
        }

        int used = child->fromBuffer(cursor, limit - processed);
        if (used < 0) {
            SNMP_LOGD("Deserialization failed for type: %d\n", kind);
            return SNMP_BUFFER_ERROR_PROBLEM_DESERIALISING;
        }

        addValueToList(child);
        cursor += used;
        processed += used;
    }

    return _length + 2;
}

