TEST(scorers_tests, duplicate_registration_attempt) {
  struct custom_scorer: public irs::sort {
    static ptr create(irs::string_ref) { return ptr(new custom_scorer()); }
    custom_scorer(): irs::sort(irs::type<custom_scorer>::get()) { }
    prepared::ptr prepare() const { return nullptr; }
  };
  static bool first_run = true;
  // This check supports repeated test executions (static maps persist across runs)
  if (first_run) {
    ASSERT_FALSE(irs::scorers::exists(irs::type<custom_scorer>::name(), irs::type<irs::text_format::vpack>::get()));
    ASSERT_FALSE(irs::scorers::exists(irs::type<custom_scorer>::name(), irs::type<irs::text_format::json>::get()));
    ASSERT_FALSE(irs::scorers::exists(irs::type<custom_scorer>::name(), irs::type<irs::text_format::text>::get()));
    ASSERT_EQ(nullptr, irs::scorers::get(irs::type<custom_scorer>::name(), irs::type<irs::text_format::vpack>::get(), irs::string_ref::NIL));
    ASSERT_EQ(nullptr, irs::scorers::get(irs::type<custom_scorer>::name(), irs::type<irs::text_format::json>::get(), irs::string_ref::NIL));
    ASSERT_EQ(nullptr, irs::scorers::get(irs::type<custom_scorer>::name(), irs::type<irs::text_format::text>::get(), irs::string_ref::NIL));

    irs::scorer_registrar first0(irs::type<custom_scorer>::get(), irs::type<irs::text_format::vpack>::get(), &custom_scorer::create);
    irs::scorer_registrar first1(irs::type<custom_scorer>::get(), irs::type<irs::text_format::json>::get(), &custom_scorer::create);
    irs::scorer_registrar first2(irs::type<custom_scorer>::get(), irs::type<irs::text_format::text>::get(), &custom_scorer::create);

    ASSERT_EQ(!first_run, !first0);
    ASSERT_EQ(!first_run, !first1);
    ASSERT_EQ(!first_run, !first2);
  }
  first_run = false; // Subsequent iterations should not allow re-registration of the same scorer

  irs::scorer_registrar retry0(irs::type<custom_scorer>::get(), irs::type<irs::text_format::vpack>::get(), &custom_scorer::create);
  irs::scorer_registrar retry1(irs::type<custom_scorer>::get(), irs::type<irs::text_format::json>::get(), &custom_scorer::create);
  irs::scorer_registrar retry2(irs::type<custom_scorer>::get(), irs::type<irs::text_format::text>::get(), &custom_scorer::create);

  ASSERT_TRUE(!retry0);
  ASSERT_TRUE(!retry1);
  ASSERT_TRUE(!retry2);

  ASSERT_TRUE(irs::scorers::exists(irs::type<custom_scorer>::name(), irs::type<irs::text_format::vpack>::get()));
  ASSERT_TRUE(irs::scorers::exists(irs::type<custom_scorer>::name(), irs::type<irs::text_format::json>::get()));
  ASSERT_TRUE(irs::scorers::exists(irs::type<custom_scorer>::name(), irs::type<irs::text_format::text>::get()));

  ASSERT_NE(nullptr, irs::scorers::get(irs::type<custom_scorer>::name(), irs::type<irs::text_format::vpack>::get(), irs::string_ref::NIL));
  ASSERT_NE(nullptr, irs::scorers::get(irs::type<custom_scorer>::name(), irs::type<irs::text_format::json>::get(), irs::string_ref::NIL));
  ASSERT_NE(nullptr, irs::scorers::get(irs::type<custom_scorer>::name(), irs::type<irs::text_format::text>::get(), irs::string_ref::NIL));
}

