//===----------------------------------------------------------------------===//
// Moore to Core Conversion Pass
//===----------------------------------------------------------------------===//

namespace {
struct MooreToCorePass : public ConvertMooreToCoreBase<MooreToCorePass> {
  void runOnOperation() override;
};
} // namespace

std::unique_ptr<OperationPass<ModuleOp>> circt::createConvertMooreToCorePass() {
  return std::make_unique<MooreToCorePass>();
}

namespace {

// Helper function to convert Moore types to core dialect types
static Type translateMooreType(Type type) {
  return TypeSwitch<Type, Type>(type)
      .Case<moore::IntType>([](auto t) {
        return IntegerType::get(t.getContext(), t.getBitWidth());
      })
      .Case<moore::RValueType>(
          [](auto t) { return translateMooreType(t.getNestedType()); })
      .Case<moore::LValueType>([](auto t) {
        return llhd::SigType::get(translateMooreType(t.getNestedType()));
      })
      .Default([](Type t) { return t; });
}

void MooreToCorePass::runOnOperation() {
  MLIRContext &ctx = getContext();
  ModuleOp mod = getOperation();

  // Set up conversion target: mark MIR ops as illegal, add legal dialects
  ConversionTarget target(ctx);
  target.addIllegalDialect<moore::MooreDialect>();
  target.addLegalDialect<hw::HWDialect>();
  target.addLegalDialect<llhd::LLHDDialect>();
  target.addLegalDialect<comb::CombDialect>();
  target.addLegalOp<ModuleOp>();

  // Configure type converter
  TypeConverter converter;
  converter.addConversion(translateMooreType);

  // Register rewrite patterns
  RewritePatternSet patterns(&ctx);
  patterns.add<ConstantOpConv, VariableDeclOpConv, AssignOpConv>(converter, &ctx);

  // Apply full conversion
  if (failed(applyFullConversion(mod, target, std::move(patterns))))
    signalPassFailure();
}

//===----------------------------------------------------------------------===//
// Operation conversion patterns
//===----------------------------------------------------------------------===//

struct ConstantOpConv : public OpConversionPattern<moore::ConstantOp> {
  using OpConversionPattern::OpConversionPattern;
  LogicalResult
  matchAndRewrite(moore::ConstantOp op, OpAdaptor adaptor,
                  ConversionPatternRewriter &rewriter) const override {
    rewriter.replaceOpWithNewOp<hw::ConstantOp>(op, op.valueAttr());
    return success();
  }
};

struct VariableDeclOpConv : public OpConversionPattern<moore::VariableDeclOp> {
  using OpConversionPattern::OpConversionPattern;
  LogicalResult
  matchAndRewrite(moore::VariableDeclOp op, OpAdaptor adaptor,
                  ConversionPatternRewriter &rewriter) const override {
    Type resultTy = typeConverter->convertType(op.result().getType());
    Value initVal =
        rewriter.create<hw::ConstantOp>(op->getLoc(), op.initAttr());
    rewriter.replaceOpWithNewOp<llhd::SigOp>(op, resultTy, op.name(),
                                             initVal);
    return success();
  }
};

struct AssignOpConv : public OpConversionPattern<moore::AssignOp> {
  using OpConversionPattern::OpConversionPattern;
  LogicalResult
  matchAndRewrite(moore::AssignOp op, OpAdaptor adaptor,
                  ConversionPatternRewriter &rewriter) const override {
    Value timeVal =
        rewriter.create<llhd::ConstantTimeOp>(op->getLoc(), 0, "s", 0, 1);
    Type dstTy = typeConverter->convertType(op.dest().getType());
    Type srcTy = typeConverter->convertType(op.src().getType());
    op.dest().setType(dstTy);
    op.src().setType(srcTy);
    rewriter.replaceOpWithNewOp<llhd::DrvOp>(op, op.dest(), op.src(), timeVal,
                                             Value());
    return success();
  }
};

