void FDlgParticipantData::AddPrimaryCondition(const FDlgCondition& Condition)
{
	const EDlgConditionType Type = Condition.ConditionType;
	const FName CallbackName = Condition.CallbackName;
	switch (Type)
	{
		case EDlgConditionType::EventCall:
			PrimaryConditions.Add(CallbackName);
			break;
		case EDlgConditionType::IntCall:
			IntVariables.Add(CallbackName);
			break;
		case EDlgConditionType::FloatCall:
			FloatVariables.Add(CallbackName);
			break;
		case EDlgConditionType::BoolCall:
			BoolVariables.Add(CallbackName);
			break;
		case EDlgConditionType::NameCall:
			NameVariables.Add(CallbackName);
			break;
		case EDlgConditionType::ClassIntVariable:
			ClassIntVariables.Add(CallbackName);
			break;
		case EDlgConditionType::ClassFloatVariable:
			ClassFloatVariables.Add(CallbackName);
			break;
		case EDlgConditionType::ClassBoolVariable:
			ClassBoolVariables.Add(CallbackName);
			break;
		case EDlgConditionType::ClassNameVariable:
			ClassNameVariables.Add(CallbackName);
			break;
		case EDlgConditionType::Custom:
			if (Condition.CustomCondition)
			{
				UserCustomConditions.Add(Condition.CustomCondition->GetClass());
			}
			break;
		default:
			break;
	}
}

void FDlgParticipantData::AddSecondaryCondition(const FDlgCondition& Condition)
{
	const FName OtherVarName = Condition.OtherVariableName;
	if (Condition.CompareType != EDlgCompare::ToConst)
	{
		const bool bIsClassVar = Condition.CompareType == EDlgCompare::ToClassVariable;
		switch (Condition.ConditionType)
		{
		case EDlgConditionType::IntCall:
		case EDlgConditionType::ClassIntVariable:
			(bIsClassVar ? ClassIntVariables : IntVariables).Add(OtherVarName);
			break;
		case EDlgConditionType::FloatCall:
		case EDlgConditionType::ClassFloatVariable:
			(bIsClassVar ? ClassFloatVariables : FloatVariables).Add(OtherVarName);
			break;
		case EDlgConditionType::BoolCall:
		case EDlgConditionType::ClassBoolVariable:
			(bIsClassVar ? ClassBoolVariables : BoolVariables).Add(OtherVarName);
			break;
		case EDlgConditionType::NameCall:
		case EDlgConditionType::ClassNameVariable:
			(bIsClassVar ? ClassNameVariables : NameVariables).Add(OtherVarName);
			break;
		default:
			break;
		}
	}
}

