using namespace dspbb;

// Load a stereo audio file and return left/right channels with original sample rate
StereoSound LoadStereoSound(const std::filesystem::path& path) {
    SndfileHandle audioFile(path.string().c_str());
    if (!audioFile) {
        throw std::runtime_error("Unable to open the specified audio file.");
    }

    const size_t frameCount = audioFile.frames();
    const size_t channelCount = audioFile.channels();
    const uint64_t sampleRate = audioFile.samplerate();

    if (channelCount != 2) {
        throw std::runtime_error("Only stereo audio files are supported.");
    }

    Signal<float> buffer(frameCount * channelCount);
    audioFile.read(buffer.Data(), buffer.Size());

    Signal<float> leftChannel = Decimate(buffer, 2);
    Signal<float> rightChannel = Decimate(AsView(buffer).SubSignal(1), 2);

    return { std::move(leftChannel), std::move(rightChannel), sampleRate };
}

