#include <bits/stdc++.h>
using namespace std;

// Structure to represent a point with coordinates
struct Point {
    long long x, y;
};

int numPoints;
vector<Point> points;

// Compute the total cost for placing points at horizontal offset 'baseX' and vertical position 'baseY'
long long computeCost(long long baseX, long long baseY) {
    long long total = 0;
    for (int idx = 0; idx < numPoints; ++idx) {
        total += abs(points[idx].x - (baseX + idx));
        total += abs(points[idx].y - baseY);
    }
    return total;
}

auto solveProblem() {
    cin >> numPoints;
    points.assign(numPoints, {});
    for (int i = 0; i < numPoints; ++i)
        cin >> points[i].x >> points[i].y;

    // Sort points lexicographically by x, then y
    sort(points.begin(), points.end(), [](Point a, Point b) {
        return a.x < b.x || (a.x == b.x && a.y < b.y);
    });

    // First ternary search over x-coordinate
    long long lowX = -1'010'000'000, highX = 1'010'000'000;
    while (lowX <= highX) {
        long long mid1X = static_cast<long long>(floor((2.0 * lowX + highX) / 3.0));
        long long mid2X = static_cast<long long>(ceil((lowX + 2.0 * highX) / 3.0));
        long long val1 = computeCost(mid1X, 0);
        long long val2 = computeCost(mid2X, 0);

        if (val1 < val2) {
            highX = mid2X - 1;
        } else {
            lowX = mid1X + 1;
        }
    }

    long long optimalX = (computeCost(lowX, 0) < computeCost(highX, 0)) ? lowX : highX;

    // Second ternary search over y-coordinate
    long long lowY = -1'010'000'000, highY = 1'010'000'000;
    while (lowY <= highY) {
        long long mid1Y = static_cast<long long>(floor((2.0 * lowY + highY) / 3.0));
        long long mid2Y = static_cast<long long>(ceil((lowY + 2.0 * highY) / 3.0));
        long long val1 = computeCost(optimalX, mid1Y);
        long long val2 = computeCost(optimalX, mid2Y);

        if (val1 < val2) {
            highY = mid2Y - 1;
        } else {
            lowY = mid1Y + 1;
        }
    }

    long long optimalY = (computeCost(optimalX, lowY) < computeCost(optimalX, highY)) ? lowY : highY;
    return computeCost(optimalX, optimalY);
}

int main() {
    unsigned testCaseCount;
    cin >> testCaseCount >> ws;
    for (unsigned t = 1; t <= testCaseCount; ++t) {
        auto result = solveProblem();
        cout << "Case #" << t << ": " << result << '\n';
    }
    return 0;
}

