static void TestFunc() {}

TEST(ExecutorAddrTest, PtrConversionWithFunctionType) {
  // Confirm function types (not just function pointers) work with toPtr
  auto FuncAddr = ExecutorAddr::fromPtr(TestFunc);
  void (*FuncPtr)() = FuncAddr.toPtr<void()>();
  EXPECT_EQ(FuncPtr, &TestFunc);
}

TEST(ExecutorAddrTest, AddrRanges) {
  ExecutorAddr Start0(0), Start1(1), Start2(2), Start3(3);
  ExecutorAddrRange Range0(Start0, Start1), Range1(Start1, Start2),
      Range2(Start2, Start3), Range3(Start0, Start2), Range4(Start1, Start3);
  // Layout:
  //     0123
  // R0: #     -- Before Range1
  // R1:  #    -- Middle range
  // R2:   #   -- After Range1
  // R3: ##    -- Overlaps start of R1
  // R4:  ##   -- Overlaps end of R1
  EXPECT_EQ(Range1, ExecutorAddrRange(Start1, Start2));
  EXPECT_EQ(Range1, ExecutorAddrRange(Start1, ExecutorAddrDiff(1)));
  EXPECT_NE(Range1, Range2);
  EXPECT_TRUE(Range1.contains(Start1));
  EXPECT_FALSE(Range1.contains(Start0));
  EXPECT_FALSE(Range1.contains(Start2));
  EXPECT_FALSE(Range1.overlaps(Range0));
  EXPECT_FALSE(Range1.overlaps(Range2));
  EXPECT_TRUE(Range1.overlaps(Range3));
  EXPECT_TRUE(Range1.overlaps(Range4));
}
