SPluginBrowser::~SPluginBrowser()
{
	FDirectoryWatcherModule& DirWatcher = FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
	for (auto& Pair : DirectoryWatchHandles)
	{
		DirWatcher.Get()->UnregisterDirectoryChangedCallback_Handle(Pair.Key, Pair.Value);
	}
	FPluginBrowserModule::Get().OnNewPluginCreated().RemoveAll(this);
}

void SPluginBrowser::Construct(const FArguments& Args)
{
	TArray<FString> PluginDirectories;
	PluginDirectories.Add(FPaths::EnginePluginsDir());
	if (FApp::HasProjectName())
	{
		PluginDirectories.Add(FPaths::ProjectPluginsDir());
		const FProjectDescriptor* ActiveProject = IProjectManager::Get().GetCurrentProject();
		if (ActiveProject != nullptr)
		{
			for (const FString& ExtraPath : ActiveProject->GetAdditionalPluginDirectories())
			{
				PluginDirectories.Add(ExtraPath);
			}
		}
	}

	FDirectoryWatcherModule& DirWatcherModule = FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
	for (const FString& DirName : PluginDirectories)
	{
		FDelegateHandle CallbackHandle;
		if (DirWatcherModule.Get()->RegisterDirectoryChangedCallback_Handle(DirName, IDirectoryWatcher::FDirectoryChanged::CreateRaw(this, &SPluginBrowser::OnPluginDirectoryModified), CallbackHandle, IDirectoryWatcher::WatchOptions::IncludeDirectoryChanges))
		{
			DirectoryWatchHandles.Add(DirName, CallbackHandle);
		}
	}

	FPluginBrowserModule::Get().OnNewPluginCreated().AddSP(this, &SPluginBrowser::OnNewPluginCreated);
	RegisterActiveTimer(0.f, FWidgetActiveTimerDelegate::CreateSP(this, &SPluginBrowser::RefreshBreadcrumbDisplay));

	struct InternalHelper
	{
		static void ConvertPluginToNames(const IPlugin* Plugin, OUT TArray<FString>& OutStrings)
		{
			OutStrings.Add(Plugin->GetDescriptor().FriendlyName);
		}
	};

	FilterByText = MakeShareable(new FPluginTextFilter(FPluginTextFilter::FItemToStringArray::CreateStatic(&InternalHelper::ConvertPluginToNames)));

	const float Spacing = 2.0f;

	CategoryTree = SNew(SPluginCategoryTree, SharedThis(this));

	TSharedRef<SVerticalBox> MainArea = SNew(SVerticalBox)
		+SVerticalBox::Slot()
		[
			SNew(SSplitter)
			+SSplitter::Slot()
			.Value(0.3f)
			[
				CategoryTree.ToSharedRef()
			]
			+SSplitter::Slot()
			[
				SNew(SVerticalBox)
				+SVerticalBox::Slot()
				.Padding(FMargin(0.0f, 0.0f, 0.0f, Spacing))
				.AutoHeight()
				[
					SNew(SHorizontalBox)
					+SHorizontalBox::Slot()
					.Padding(Spacing)
					[
						SAssignNew(Breadcrumbs, SBreadcrumbTrail<TSharedPtr<FPluginCategory>>)
						.DelimiterImage(FPluginStyle::Get()->GetBrush("Plugins.BreadcrumbArrow"))
						.ShowLeadingDelimiter(true)
						.OnCrumbClicked(this, &SPluginBrowser::OnBreadcrumbClicked)
					]
					+SHorizontalBox::Slot()
					.Padding(Spacing)
					[
						SAssignNew(SearchInput, SSearchBox)
						.OnTextChanged(this, &SPluginBrowser::OnSearchTextChanged)
					]
				]
				+SVerticalBox::Slot()
				[
					SAssignNew(PluginGrid, SPluginTileList, SharedThis(this))
				]
				+SVerticalBox::Slot()
				.AutoHeight()
				.Padding(FMargin(Spacing, Spacing, Spacing, 0.0f))
				[
					SNew(SBorder)
					.BorderBackgroundColor(FLinearColor::Yellow)
					.BorderImage(FEditorStyle::GetBrush("ToolPanel.GroupBorder"))
					.Padding(8.0f)
					.Visibility(this, &SPluginBrowser::ShouldShowRestartNotice)
					[
						SNew(SHorizontalBox)
						+SHorizontalBox::Slot()
						.AutoWidth()
						.VAlign(VAlign_Center)
						.Padding(FMargin(0.0f, 0.0f, 8.0f, 0.0f))
						[
							SNew(SImage)
							.Image(FPluginStyle::Get()->GetBrush("Plugins.Warning"))
						]
						+SHorizontalBox::Slot()
						.VAlign(VAlign_Center)
						[
							SNew(STextBlock)
							.Text(LOCTEXT("PluginSettingsRestartNotice", "Unreal Editor must be restarted for the plugin changes to take effect."))
						]
						+SHorizontalBox::Slot()
						.AutoWidth()
						.VAlign(VAlign_Center)
						.HAlign(HAlign_Right)
						[
							SNew(SButton)
							.Text(LOCTEXT("PluginSettingsRestartEditor", "Restart Now"))
							.OnClicked(this, &SPluginBrowser::OnRestartEditorClicked)
						]
					]
				]
			]
		];

	const FText CreatePluginTooltip = LOCTEXT("NewPluginEnabled", "Click here to open the Plugin Creator dialog.");
	MainArea->AddSlot()
		.AutoHeight()
		.Padding(5)
		.HAlign(HAlign_Right)
		[
			SNew(SButton)
			.ContentPadding(5)
			.IsEnabled(true)
			.ToolTip(SNew(SToolTip).Text(CreatePluginTooltip))
			.TextStyle(FEditorStyle::Get(), "LargeText")
			.ButtonStyle(FEditorStyle::Get(), "FlatButton.Success")
			.HAlign(HAlign_Center)
			.Text(LOCTEXT("NewPluginLabel", "New Plugin"))
			.OnClicked(this, &SPluginBrowser::OnCreateNewPluginClicked)
		];

	ChildSlot
	[
		MainArea
	];
}

