}

EActiveTimerReturnType SPluginBrowser::RefreshBreadcrumbDisplay(double InCurrentTime, float InDeltaTime)
{
	UpdateBreadcrumbUI();
	return EActiveTimerReturnType::Stop;
}

void SPluginBrowser::UpdateBreadcrumbUI()
{
	if (Breadcrumbs.IsValid())
	{
		TSharedPtr<FPluginCategory> SelectedNode = CategoryTree->GetSelectedCategory();
		TArray<TSharedPtr<FPluginCategory>> PathStack;

		if (SelectedNode.IsValid())
		{
			for (TSharedPtr<FPluginCategory> Current = SelectedNode; Current.IsValid(); Current = Current->ParentCategory.Pin())
			{
				PathStack.Insert(Current, 0);
			}
		}

		Breadcrumbs->ClearCrumbs();
		for (TSharedPtr<FPluginCategory>& Node : PathStack)
		{
			Breadcrumbs->PushCrumb(Node->DisplayName, Node);
		}
	}
}

void SPluginBrowser::OnBreadcrumbClicked(const TSharedPtr<FPluginCategory>& Category)
{
	if (CategoryTree.IsValid())
	{
		CategoryTree->SelectCategory(Category);
	}
}

FReply SPluginBrowser::OnCreateNewPluginClicked() const
{
	FGlobalTabmanager::Get()->InvokeTab(FPluginBrowserModule::PluginCreatorTabName);
	return FReply::Handled();
}

