#include "mex.h"
#define KDTREE_USE_SQUARED_DISTANCE
#include <kdtree++/kdtree.hpp>
#include <cstdlib>
#include <list>
#include <set>

struct Point2D {
    int index;
    double coordinates[2];

    bool operator==(const Point2D& other) const {
        return index == other.index && 
               coordinates[0] == other.coordinates[0] && 
               coordinates[1] == other.coordinates[1];
    }
};

inline double get_coord(Point2D p, size_t dim) { 
    return p.coordinates[dim]; 
}

typedef KDTree::KDTree<2, Point2D, std::pointer_to_binary_function<Point2D,size_t,double> > tree_type;

// Structure representing a 2D point with x and y components
typedef struct {
    double x_val;
    double y_val;
} point_2d;

struct Assignment {
    double distance_sq;
    int idx_A;
    int idx_B;
};

struct DistanceComparator {
    bool operator()(const Assignment& left, const Assignment& right) {
        return left.distance_sq > right.distance_sq;
    }
};

/* Computes squared Euclidean distance between two points */
inline static double compute_squared_distance(point_2d* ptA, point_2d* ptB) {
    double dx = ptA->x_val - ptB->x_val;
    double dy = ptA->y_val - ptB->y_val;
    return dx * dx + dy * dy;
}

void process_data(point_2d* inputA, point_2d* inputB, int count, int* result_indices)
{
    // Build k-d tree from set B
    tree_type tree_b(std::ptr_fun(get_coord));
    for (int i = 0; i < count; ++i) {
        Point2D pt = {i, inputB[i].x_val, inputB[i].y_val};
        tree_b.insert(pt);
    }
    tree_b.optimise(); // Rebalance the tree

    // Priority queue of assignments sorted by largest distance first
    std::multiset<Assignment, DistanceComparator> assignment_set;

    // Track which points in A are assigned to each point in B
    std::vector<std::list<int>> incoming_assignments(count);

    // Initial assignment: each point in A maps to nearest neighbor in B
    for (int i = 0; i < count; ++i) {
        Point2D query_pt = {-1, inputA[i].x_val, inputA[i].y_val};
        auto found = tree_b.find_nearest(query_pt);

        if (found.first != tree_b.end()) {
            Assignment assign = {found.second, i, found.first->index};
            assignment_set.insert(assign);
            incoming_assignments[assign.idx_B].push_back(assign.idx_A);
        } else {
            mexErrMsgIdAndTxt("pmRefinement:initMatch", "Failed to find initial match.");
            return;
        }
    }

    // Iteratively resolve conflicts until all points have unique matches
    while (!assignment_set.empty()) {
        // Take the assignment with maximum distance
        Assignment current = *assignment_set.begin();

        // Record final assignment
        result_indices[current.idx_A] = current.idx_B;

        // Remove this assignment from consideration
        assignment_set.erase(current);

        // Remove matched point from B from the tree
        Point2D removed_pt = {current.idx_B, inputB[current.idx_B].x_val, inputB[current.idx_B].y_val};
        tree_b.erase_exact(removed_pt);

        // Update other assignments that were pointing to the same B point
        if (incoming_assignments[current.idx_B].size() > 1) {
            for (auto it = incoming_assignments[current.idx_B].begin(); 
                 it != incoming_assignments[current.idx_B].end(); ++it) {
                int a_idx = *it;
                if (a_idx != current.idx_A) {
                    // Re-query for new nearest neighbor in updated tree
                    Point2D new_query = {-1, inputA[a_idx].x_val, inputA[a_idx].y_val};
                    auto new_match = tree_b.find_nearest(new_query);

                    int new_B_idx = new_match.first->index;
                    double new_dist_sq = new_match.second;

                    // Remove old assignment
                    double old_dist = compute_squared_distance(&inputA[a_idx], &inputB[current.idx_B]);
                    Assignment old_assign = {old_dist, a_idx, current.idx_B};
                    assignment_set.erase(old_assign);

                    // Insert updated assignment
                    Assignment updated_assign = {new_dist_sq, a_idx, new_B_idx};
                    assignment_set.insert(updated_assign);
                    incoming_assignments[new_B_idx].push_back(a_idx);
                }
            }
        }

        // Clear list since this B node is no longer available
        incoming_assignments[current.idx_B].clear();
    }
}

void mexFunction(int nlhs, mxArray *plhs[], int nrhs, const mxArray *prhs[]) {
    point_2d *pointsA, *pointsB;
    int rowsA, colsA, rowsB, colsB;
    int* output_ptr;

    // Check input/output arguments
    if (nrhs != 2) {
        mexErrMsgIdAndTxt("pmRefinement:nrhs", "Two inputs required.");
        return;
    }
    if (nlhs != 1) {
        mexErrMsgIdAndTxt("pmRefinement:nlhs", "One output required.");
        return;
    }

    // Get dimensions and data pointers for input matrices
    rowsA = static_cast<int>(mxGetM(prhs[0]));
    colsA = static_cast<int>(mxGetN(prhs[0]));
    pointsA = reinterpret_cast<point_2d*>(mxGetPr(prhs[0]));

    rowsB = static_cast<int>(mxGetM(prhs[1]));
    colsB = static_cast<int>(mxGetN(prhs[1]));
    pointsB = reinterpret_cast<point_2d*>(mxGetPr(prhs[1]));

    // Validate input consistency
    if (rowsA != rowsB || colsA != colsB) {
        mexErrMsgIdAndTxt("pmRefinement:prhs", "Input matrices must have same size.");
        return;
    }
    if (rowsA != 2) {
        mexErrMsgIdAndTxt("pmRefinement:prhs", "Points must be 2-dimensional.");
        return;
    }

    // Create output array
    plhs[0] = mxCreateNumericMatrix(1, colsA, mxINT32_CLASS, mxREAL);
    output_ptr = static_cast<int*>(mxGetData(plhs[0]));

    // Perform matching
    process_data(pointsA, pointsB, colsA, output_ptr);

    // Convert from C-style (0-based) to MATLAB-style (1-based) indexing
    for (int i = 0; i < colsA; ++i) {
        output_ptr[i] += 1;
    }
}

