#include "Test/Path.h"
#include "capture_data.pb.h"

using namespace std::string_view_literals;

const std::string_view kMainFunctionInstructions =
    "\x50\xbf\x04\x20\x40\x00\xe8\xe5\xfe\xff\xff\x31\xc0\x59\xc3\x90"sv;

constexpr const char* kOrganizationName = "The Orbit Authors";

TEST(AnnotatingSourceCodeDialog, SmokeTest) {
  QCoreApplication::setOrganizationName(kOrganizationName);
  QCoreApplication::setApplicationName("AnnotatingSourceCodeDialog.SmokeTest");

  const std::filesystem::path binary_path = orbit_test::GetTestdataDir() / "line_info_test_binary";

  {
    orbit_source_paths_mapping::MappingManager path_manager{};
    path_manager.SetMappings({});
    path_manager.AppendMapping(orbit_source_paths_mapping::Mapping{std::filesystem::path{"."} / "..",
                                                                   orbit_test::GetTestdataDir()});
  }

  ErrorMessageOr<std::unique_ptr<orbit_object_utils::ElfFile>> elf_file =
      orbit_object_utils::CreateElfFile(binary_path);
  ASSERT_TRUE(elf_file.has_value()) << elf_file.error().message();

  constexpr uint64_t kEntryAddress = 0x401140;
  ErrorMessageOr<orbit_grpc_protos::LineInfo> line_info =
      elf_file.value()->GetLocationOfFunction(kEntryAddress);
  ASSERT_TRUE(line_info.has_value()) << line_info.error().message();

  const std::filesystem::path cpp_source_path =
      orbit_test::GetTestdataDir() / "LineInfoTestBinary.cpp";
  ASSERT_TRUE(std::filesystem::exists(cpp_source_path));

  ErrorMessageOr<std::string> source_content_or_error =
      orbit_base::ReadFileToString(cpp_source_path);
  ASSERT_TRUE(source_content_or_error.has_value())
      << source_content_or_error.error().message();

  std::string source_content = std::move(source_content_or_error.value());

  orbit_client_protos::FunctionInfo func_info{};
  func_info.set_name("main");
  func_info.set_pretty_name("main");
  func_info.set_module_path("line_info_test_binary");
  func_info.set_address(0x401140);
  func_info.set_size(kMainFunctionInstructions.size());

  orbit_code_report::Disassembler disasm{};
  disasm.Disassemble(static_cast<const void*>(kMainFunctionInstructions.data()),
                     kMainFunctionInstructions.size(), 0x401140, true);
  std::string assembly_output = disasm.GetResult();

  orbit_code_report::DisassemblyReport report{std::move(disasm), kEntryAddress};

  orbit_qt::AnnotatingSourceCodeDialog dialog{};
  auto highlighter = std::make_unique<orbit_syntax_highlighter::X86Assembly>();
  dialog.SetMainContent(QString::fromStdString(assembly_output), std::move(highlighter));
  dialog.SetDisassemblyCodeReport(std::move(report));

  bool handler_executed = false;
  dialog.AddAnnotatingSourceCode(func_info, [&](const std::string&, const std::string&) {
    handler_executed = true;
    return orbit_base::Future<ErrorMessageOr<std::filesystem::path>>{binary_path};
  });

  bool source_loaded = false;
  QObject::connect(&dialog, &orbit_qt::AnnotatingSourceCodeDialog::SourceCodeLoaded, &dialog,
                   [&]() {
                     source_loaded = true;
                     dialog.close();
                   });

  QObject::connect(&dialog, &orbit_qt::AnnotatingSourceCodeDialog::SourceCodeAvailable, &dialog,
                   [&]() {
                     QPushButton* load_button = dialog.findChild<QPushButton*>("notification_action_button");
                     if (load_button == nullptr) return;
                     QTest::mouseClick(load_button, Qt::LeftButton);
                   });

  QTimer::singleShot(std::chrono::seconds{2}, &dialog, [&]() { dialog.close(); });

  dialog.exec();

  EXPECT_TRUE(handler_executed);
  EXPECT_TRUE(source_loaded);
}

