UKUIManagedButtonWidgetChildManager::UKUIManagedButtonWidgetChildManager( const class FObjectInitializer& oInit )
	: Super(oInit)
{
	m_bDisabled = EKUIBoolMatch::V_Any;
	m_bMouseOver = EKUIBoolMatch::V_Any;
	m_bPressed = EKUIBoolMatch::V_Any;
	vOffsetList.SetNum( 8 );

	for ( uint8 idx = 0; idx < 8; ++idx )
		vOffsetList[ idx ] = FVector2D::ZeroVector;
}

UKUIButtonWidget* UKUIManagedButtonWidgetChildManager::GetButton() const
{
	return Cast<UKUIButtonWidget>( cmWidget.Get() );
}

void UKUIManagedButtonWidgetChildManager::SetStates( TEnumAsByte<EKUIBoolMatch::Value> bDisabled, TEnumAsByte<EKUIBoolMatch::Value> bMouseOver, TEnumAsByte<EKUIBoolMatch::Value> bPressed )
{
	m_bDisabled = bDisabled;
	m_bMouseOver = bMouseOver;
	m_bPressed = bPressed;
}

void UKUIManagedButtonWidgetChildManager::SetOffset( FVector2D vOffset, TEnumAsByte<EKUIBoolMatch::Value> bDisabled, TEnumAsByte<EKUIBoolMatch::Value> bMouseOver, TEnumAsByte<EKUIBoolMatch::Value> bPressed )
{
	for ( uint8 i = 0; i < 8; ++i )
	{
		if ( ( i & 1 ) && bDisabled == EKUIBoolMatch::V_False )
			continue;
		if ( !( i & 1 ) && bDisabled == EKUIBoolMatch::V_True )
			continue;
		if ( ( i & 2 ) && bMouseOver == EKUIBoolMatch::V_False )
			continue;
		if ( !( i & 2 ) && bMouseOver == EKUIBoolMatch::V_True )
			continue;
		if ( ( i & 4 ) && bPressed == EKUIBoolMatch::V_False )
			continue;
		if ( !( i & 4 ) && bPressed == EKUIBoolMatch::V_True )
			continue;
		vOffsetList[ i ] = vOffset;
	}
}

void UKUIManagedButtonWidgetChildManager::Update()
{
	Super::Update();
	if ( GetButton() == nullptr )
	{
		KUIErrorDebugUO( "Null button" );
		return;
	}
	if ( !oChild.IsValid() )
	{
		KUIErrorDebugUO( "Null child" );
		return;
	}
	bool bShow = true;
	if ( m_bDisabled != EKUIBoolMatch::V_Any )
	{
		if ( GetButton()->IsDisabled() )
		{
			if ( m_bDisabled == EKUIBoolMatch::V_False )
				bShow = false;
		}
		else
		{
			if ( m_bDisabled == EKUIBoolMatch::V_True )
				bShow = false;
		}
	}
	if ( bShow && m_bMouseOver != EKUIBoolMatch::V_Any )
	{
		if ( GetButton()->IsMouseOver() )
		{
			if ( m_bMouseOver == EKUIBoolMatch::V_False )
				bShow = false;
		}
		else
		{
			if ( m_bMouseOver == EKUIBoolMatch::V_True )
				bShow = false;
		}
	}
	if ( bShow && m_bPressed != EKUIBoolMatch::V_Any )
	{
		if ( GetButton()->IsDown() )
		{
			if ( m_bPressed == EKUIBoolMatch::V_False )
				bShow = false;
		}
		else
		{
			if ( m_bPressed == EKUIBoolMatch::V_True )
				bShow = false;
		}
	}
	oChild->SetVisible( bShow );
	oChild->SetLocationStruct( vOffsetList[
		( GetButton()->IsDisabled()  ? 1 : 0 ) + 
		( GetButton()->IsMouseOver() ? 2 : 0 ) + 
		( GetButton()->IsDown()      ? 4 : 0 )
	] );
}

