// Backup current read functions and set defaults
void ILAPIENTRY cPreserveReadOps()
{
	// Save current function pointers
	GetcFunctionBackup = GetcProc;
	ReadFunctionBackup = ReadProc;
	SeekFunctionBackup = SeekRProc;
	TellFunctionBackup = TellRProc;
	iopenrBackup = iopenr;
	icloserBackup = icloser;

	// Reset to default read functions
	ilResetRead();
	return;
}

// Restore previously backed-up read functions
void ILAPIENTRY cRestoreReadOps()
{
	GetcProc = GetcFunctionBackup;
	ReadProc = ReadFunctionBackup;
	SeekRProc = SeekFunctionBackup;
	TellRProc = TellFunctionBackup;
	iopenr = iopenrBackup;
	icloser = icloserBackup;
	return;
}

// Backup current write functions and set defaults
void ILAPIENTRY cPreserveWriteOps()
{
	// Save current function pointers
	PutcFunctionBackup = PutcProc;
	SeekWFunctionBackup = SeekWProc;
	TellWFunctionBackup = TellWProc;
	WriteFunctionBackup = WriteProc;
	iopenwBackup = iopenw;
	iclosewBackup = iclosew;

	// Reset to default write functions
	ilResetWrite();
	return;
}

// Restore previously backed-up write functions
void ILAPIENTRY cRestoreWriteOps()
{
	PutcProc = PutcFunctionBackup;
	SeekWProc = SeekWFunctionBackup;
	TellWProc = TellWFunctionBackup;
	WriteProc = WriteFunctionBackup;
	iopenw = iopenwBackup;
	iclosew = iclosewBackup;
	return;
}

// Default file opening for reading
ILHANDLE ILAPIENTRY cDefaultOpenR(ILconst_string Filename)
{
#ifndef _UNICODE
	return (ILHANDLE)fopen((char*)Filename, "rb");
#else
	#ifdef _WIN32
		return (ILHANDLE)_wfopen(Filename, L"rb");
	#else
		return (ILHANDLE)fopen((char*)Filename, "rb");
	#endif
#endif//UNICODE
}

// Default file closing for reading
void ILAPIENTRY cDefaultCloseR(ILHANDLE Handle)
{
	fclose((FILE*)Handle);
	return;
}

// Default EOF check
ILboolean ILAPIENTRY cDefaultEof(ILHANDLE Handle)
{
	ILuint OriginalPosition, FileSize;

	OriginalPosition = itell();
	iseek(0, IL_SEEK_END);
	FileSize = itell();
	iseek(OriginalPosition, IL_SEEK_SET);

	if (itell() >= FileSize)
		return IL_TRUE;
	return IL_FALSE;
}

// Default character reading
ILint ILAPIENTRY cDefaultGetc(ILHANDLE Handle)
{
	ILint Value;
	if (!UseBuffering) {
		Value = fgetc((FILE*)Handle);
		if (Value == IL_EOF)
			ilSetError(IL_FILE_READ_ERROR);
	}
	else {
		Value = 0;
		if (iread(&Value, 1, 1) != 1)
			return IL_EOF;
	}
	return Value;
}

// Default block reading
ILint ILAPIENTRY cDefaultRead(void *Destination, ILuint ElementSize, ILuint ElementCount, ILHANDLE Handle)
{
	return (ILint)fread(Destination, ElementSize, ElementCount, (FILE*)Handle);
}

// Default reading seek
ILint ILAPIENTRY cDefaultRSeek(ILHANDLE Handle, ILint Offset, ILint Origin)
{
	return fseek((FILE*)Handle, Offset, Origin);
}

// Default writing seek
ILint ILAPIENTRY cDefaultWSeek(ILHANDLE Handle, ILint Offset, ILint Origin)
{
	return fseek((FILE*)Handle, Offset, Origin);
}

// Default reading tell
ILint ILAPIENTRY cDefaultRTell(ILHANDLE Handle)
{
	return ftell((FILE*)Handle);
}

// Default writing tell
ILint ILAPIENTRY cDefaultWTell(ILHANDLE Handle)
{
	return ftell((FILE*)Handle);
}

// Default file opening for writing
ILHANDLE ILAPIENTRY cDefaultOpenW(ILconst_string Filename)
{
#ifndef _UNICODE
	return (ILHANDLE)fopen((char*)Filename, "wb");
#else
	#ifdef _WIN32
		return (ILHANDLE)_wfopen(Filename, L"wb");
	#else
		return (ILHANDLE)fopen((char*)Filename, "wb");
	#endif
#endif//UNICODE
}

// Default file closing for writing
void ILAPIENTRY cDefaultCloseW(ILHANDLE Handle)
{
	fclose((FILE*)Handle);
	return;
}

// Default character writing
ILint ILAPIENTRY cDefaultPutc(ILubyte Character, ILHANDLE Handle)
{
	return fputc(Character, (FILE*)Handle);
}

// Default block writing
ILint ILAPIENTRY cDefaultWrite(const void *Source, ILuint ElementSize, ILuint ElementCount, ILHANDLE Handle)
{
	return (ILint)fwrite(Source, ElementSize, ElementCount, (FILE*)Handle);
}

// Reset read functions to defaults
void ILAPIENTRY ilResetRead()
{
	ilSetRead(cDefaultOpenR, cDefaultCloseR, cDefaultEof, cDefaultGetc, 
				cDefaultRead, cDefaultRSeek, cDefaultRTell);
	return;
}

// Reset write functions to defaults
void ILAPIENTRY ilResetWrite()
{
	ilSetWrite(cDefaultOpenW, cDefaultCloseW, cDefaultPutc,
				cDefaultWSeek, cDefaultWTell, cDefaultWrite);
	return;
}

// Set custom read functions
void ILAPIENTRY ilSetRead(fOpenRProc Open, fCloseRProc Close, fEofProc Eof, fGetcProc Getc, fReadProc Read, fSeekRProc Seek, fTellRProc Tell)
{
	iopenr    = Open;
	icloser   = Close;
	EofProc   = Eof;
	GetcProc  = Getc;
	ReadProc  = Read;
	SeekRProc = Seek;
	TellRProc = Tell;
	return;
}

// Set custom write functions
void ILAPIENTRY ilSetWrite(fOpenRProc Open, fCloseRProc Close, fPutcProc Putc, fSeekWProc Seek, fTellWProc Tell, fWriteProc Write)
{
	iopenw    = Open;
	iclosew   = Close;
	PutcProc  = Putc;
	WriteProc = Write;
	SeekWProc = Seek;
	TellWProc = Tell;
	return;
}

// Configure input source as file
void cSetInputFile(ILHANDLE File)
{
	ieof  = cEofFile;
	igetc = cGetcFile;
	iread = cReadFile;
	iseek = cSeekRFile;
	itell = cTellRFile;
	InputFileHandle = File;
	InputFileBaseOffset = itell();
}

// Configure input source as memory lump
void cSetInputLump(const void *Lump, ILuint Size)
{
	ieof  = cEofLump;
	igetc = cGetcLump;
	iread = cReadLump;
	iseek = cSeekRLump;
	itell = cTellRLump;
	InputLumpPointer = Lump;
	InputLumpPosition = 0;
	InputLumpTotalSize = Size;
}

// Configure output destination as file
void cSetOutputFile(ILHANDLE File)
{
	OutputLumpPointer = NULL;
	OutputLumpPosition = 0;
	OutputLumpTotalSize = 0;
	iputc  = cPutcFile;
	iseekw = cSeekWFile;
	itellw = cTellWFile;
	iwrite = cWriteFile;
	OutputFileHandle = File;
}

// Configure output destination as "fake" for size calculation
void cSetOutputFake(void)
{
	iputc  = cSizePutc;
	iseekw = cSizeSeek;
	itellw = cSizeTell;
	iwrite = cSizeWrite;
	return;
}

// Configure output destination as memory lump
void cSetOutputLump(void *Lump, ILuint Size)
{
	if (Lump == NULL)
		return;
	iputc  = cPutcLump;
	iseekw = cSeekWLump;
	itellw = cTellWLump;
	iwrite = cWriteLump;
	OutputLumpPointer = Lump;
	OutputLumpPosition = 0;
	OutputLumpTotalSize = Size;
}

// Get current position in output lump
ILuint ILAPIENTRY ilGetLumpPos()
{
	if (OutputLumpPointer)
		return OutputLumpPosition;
	return 0;
}

// Formatted output function
ILuint ILAPIENTRY ilprintf(const char *Format, ...)
{
	char	Buffer[2048];
	va_list	Args;
	ILuint	i;

	va_start(Args, Format);
	vsprintf(Buffer, Format, Args);
	va_end(Args);

	i = ilCharStrLen(Buffer);
	iwrite(Buffer, 1, i);
	return i;
}

// Pad with zeros
void ipad(ILuint NumZeros)
{
	ILuint i = 0;
	for (; i < NumZeros; i++)
		iputc(0);
	return;
}

// Implementation of file-based EOF check
ILboolean ILAPIENTRY cEofFile(void)
{
	return EofProc((FILE*)InputFileHandle);
}

// Implementation of lump-based EOF check
ILboolean ILAPIENTRY cEofLump(void)
{
	if (InputLumpTotalSize)
		return (InputLumpPosition >= InputLumpTotalSize);
	return IL_FALSE;
}

// Implementation of file-based character reading
ILint ILAPIENTRY cGetcFile(void)
{
	if (!UseBuffering) {
		return GetcProc(InputFileHandle);
	}
	if (BufferPosition >= BufferCapacity) {
		cPreCache(BufferCapacity);
	}
	BytesInBuffer++;
	return Buffer[BufferPosition++];
}

// Implementation of lump-based character reading
ILint ILAPIENTRY cGetcLump(void)
{
	if (InputLumpTotalSize > 0) {
		if (InputLumpPosition + 1 > InputLumpTotalSize) {
			InputLumpPosition--;
			ilSetError(IL_FILE_READ_ERROR);
			return IL_EOF;
		}
	}
	return *((ILubyte*)InputLumpPointer + InputLumpPosition++);
}

// Implementation of file-based block reading
ILuint ILAPIENTRY cReadFile(void *Destination, ILuint ElementSize, ILuint ElementCount)
{
	ILuint	TotalBytes = 0, CopiedBytes;
	ILuint	DestinationSize = ElementSize * ElementCount;
	ILuint	ElementsRead;

	if (!UseBuffering) {
		ElementsRead = ReadProc(Destination, ElementSize, ElementCount, InputFileHandle);
		if (ElementsRead != ElementCount)
			ilSetError(IL_FILE_READ_ERROR);
		return ElementsRead;
	}

	if (DestinationSize < BufferCapacity - BufferPosition) {
		memcpy(Destination, Buffer + BufferPosition, DestinationSize);
		BufferPosition += DestinationSize;
		BytesInBuffer += DestinationSize;
		if (ElementSize != 0)
			DestinationSize /= ElementSize;
		return DestinationSize;
	}
	else {
		while (TotalBytes < DestinationSize) {
			if (TotalBytes + BufferCapacity - BufferPosition > DestinationSize)
				CopiedBytes = DestinationSize - TotalBytes;
			else
				CopiedBytes = BufferCapacity - BufferPosition;
			memcpy((ILubyte*)Destination + TotalBytes, Buffer + BufferPosition, CopiedBytes);
			TotalBytes += CopiedBytes;
			BufferPosition += CopiedBytes;
			if (TotalBytes < DestinationSize) {
				cPreCache(BufferCapacity);
			}
		}
	}

	BytesInBuffer = BufferPosition;
	if (ElementSize != 0)
		TotalBytes /= ElementSize;
	if (TotalBytes != ElementCount)
		ilSetError(IL_FILE_READ_ERROR);
	return TotalBytes;
}

// Implementation of lump-based block reading
ILuint ILAPIENTRY cReadLump(void *Destination, const ILuint ElementSize, const ILuint ElementCount)
{
	ILuint i, ByteCount = IL_MIN(ElementSize*ElementCount, InputLumpTotalSize-InputLumpPosition);

	for (i = 0; i < ByteCount; i++) {
		*((ILubyte*)Destination + i) = *((ILubyte*)InputLumpPointer + InputLumpPosition + i);
		if (InputLumpTotalSize > 0) {
			if (InputLumpPosition + i > InputLumpTotalSize) {
				InputLumpPosition += i;
				if (i != ElementCount)
					ilSetError(IL_FILE_READ_ERROR);
				return i;
			}
		}
	}

	InputLumpPosition += i;
	if (ElementSize != 0)
		i /= ElementSize;
	if (i != ElementCount)
		ilSetError(IL_FILE_READ_ERROR);
	return i;
}

// Pre-cache data for buffered reading
ILboolean cPreCache(ILuint Size)
{
	if (iread == cReadLump) {
		return IL_TRUE;
	}

	if (Buffer) {
		ifree(Buffer);
	}

	if (Size == 0) {
		Size = 1;
	}

	Buffer = (ILubyte*)ialloc(Size);
	if (Buffer == NULL) {
		return IL_FALSE;
	}

	UseBuffering = IL_FALSE;
	BufferStartOffset = itell();
	BufferCapacity = iread(Buffer, 1, Size);
	if (BufferCapacity != Size)
		ilGetError();

	BufferCapacity = Size;
	BufferPosition = 0;
	UseBuffering = IL_TRUE;
	BytesInBuffer = 0;
	return IL_TRUE;
}

// Release buffer resources
void cUnCache()
{
	if (!UseBuffering)
		return;
	if (iread == cReadLump)
		return;

	BufferCapacity = 0;
	BufferPosition = 0;

	if (Buffer) {
		ifree(Buffer);
		Buffer = NULL;
	}

	UseBuffering = IL_FALSE;
	iseek(BufferStartOffset + BytesInBuffer, IL_SEEK_SET);
	return;
}

// Implementation of file-based reading seek
ILint ILAPIENTRY cSeekRFile(ILint Offset, ILuint Origin)
{
	if (Origin == IL_SEEK_SET)
		Offset += InputFileBaseOffset;
	return SeekRProc(InputFileHandle, Offset, Origin);
}

// Implementation of lump-based reading seek
ILint ILAPIENTRY cSeekRLump(ILint Offset, ILuint Origin)
{
	switch (Origin)
	{
		case IL_SEEK_SET:
			if (Offset > (ILint)InputLumpTotalSize)
				return 1;
			InputLumpPosition = Offset;
			break;
		case IL_SEEK_CUR:
			if (InputLumpPosition + Offset > InputLumpTotalSize)
				return 1;
			InputLumpPosition += Offset;
			break;
		case IL_SEEK_END:
			if (Offset > 0)
				return 1;
			if (abs(Offset) > (ILint)InputLumpTotalSize)
				return 1;
			InputLumpPosition = InputLumpTotalSize + Offset;
			break;
		default:
			return 1;
	}
	return 0;
}

// Implementation of file-based reading tell
ILuint ILAPIENTRY cTellRFile(void)
{
	return TellRProc(InputFileHandle);
}

// Implementation of lump-based reading tell
ILuint ILAPIENTRY cTellRLump(void)
{
	return InputLumpPosition;
}

// Get current input file handle
ILHANDLE ILAPIENTRY iGetFile(void)
{
	return InputFileHandle;
}

// Get current input lump pointer
const ILubyte* ILAPIENTRY iGetLump(void) {
	return (ILubyte*)InputLumpPointer;
}

// Implementation of file-based character writing
ILint ILAPIENTRY cPutcFile(ILubyte Character)
{
	return PutcProc(Character, OutputFileHandle);
}

// Implementation of lump-based character writing
ILint ILAPIENTRY cPutcLump(ILubyte Character)
{
	if (OutputLumpPosition >= OutputLumpTotalSize)
		return IL_EOF;
	*((ILubyte*)(OutputLumpPointer) + OutputLumpPosition++) = Character;
	return Character;
}

// Implementation of file-based block writing
ILint ILAPIENTRY cWriteFile(const void *Source, ILuint ElementSize, ILuint ElementCount)
{
	ILuint ElementsWritten;
	ElementsWritten = WriteProc(Source, ElementSize, ElementCount, OutputFileHandle);
	if (ElementsWritten != ElementCount) {
		ilSetError(IL_FILE_WRITE_ERROR);
		return 0;
	}
	return ElementsWritten;
}

// Implementation of lump-based block writing
ILint ILAPIENTRY cWriteLump(const void *Source, ILuint ElementSize, ILuint ElementCount)
{
	ILuint ByteCount = ElementSize * ElementCount;
	ILuint i = 0;

	for (; i < ByteCount; i++) {
		if (OutputLumpTotalSize > 0) {
			if (OutputLumpPosition + i >= OutputLumpTotalSize) {
				ilSetError(IL_FILE_WRITE_ERROR);
				OutputLumpPosition += i;
				return i;
			}
		}
		*((ILubyte*)OutputLumpPointer + OutputLumpPosition + i) = *((ILubyte*)Source + i);
	}

	OutputLumpPosition += ByteCount;
	return ByteCount;
}

// Implementation of file-based writing seek
ILint ILAPIENTRY cSeekWFile(ILint Offset, ILuint Origin)
{
	if (Origin == IL_SEEK_SET)
		Offset += OutputFileBaseOffset;
	return SeekWProc(OutputFileHandle, Offset, Origin);
}

// Implementation of lump-based writing seek
ILint ILAPIENTRY cSeekWLump(ILint Offset, ILuint Origin)
{
	switch (Origin)
	{
		case IL_SEEK_SET:
			if (Offset > (ILint)OutputLumpTotalSize)
				return 1;
			OutputLumpPosition = Offset;
			break;
		case IL_SEEK_CUR:
			if (OutputLumpPosition + Offset > OutputLumpTotalSize)
				return 1;
			OutputLumpPosition += Offset;
			break;
		case IL_SEEK_END:
			if (Offset > 0)
				return 1;
			if (abs(Offset) > (ILint)OutputLumpTotalSize)
				return 1;
			OutputLumpPosition = OutputLumpTotalSize + Offset;
			break;
		default:
			return 1;
	}
	return 0;
}

// Implementation of file-based writing tell
ILuint ILAPIENTRY cTellWFile(void)
{
	return TellWProc(OutputFileHandle);
}

// Implementation of lump-based writing tell
ILuint ILAPIENTRY cTellWLump(void)
{
	return OutputLumpPosition;
}

#include <bits/stdc++.h>
using namespace std;

// Generate pairs by dividing the range into two segments
void process() {
    int total_elements, partition_size;
    cin >> total_elements >> partition_size;

    int first_half = partition_size / 2;
    int second_half = partition_size - first_half;

    int start1 = 1, end1 = start1 + first_half * 2 - 1;
    int start2 = end1 + 1, end2 = start2 + second_half * 2 - 1;

    assert(end2 <= total_elements);

    // Output pairs for the first segment (moving inward)
    for (int i = 0; i < first_half; i++) {
        cout << start1 << ' ' << end1 << '\n';
        start1++;
        end1--;
    }

    // Output pairs for the second segment (moving inward)
    for (int j = 0; j < second_half; j++) {
        cout << start2 << ' ' << end2 << '\n';
        start2++;
        end2--;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    process();
    return 0;
}

