#include <math.h>

double AverageCalculator::autoResetError() const
{
    return m_autoResetThreshold;
}

void AverageCalculator::setAutoResetError(double threshold)
{
    m_autoResetThreshold = threshold;
}

bool AverageCalculator::enableAutoReset() const
{
    return m_isAutoResetEnabled;
}

void AverageCalculator::setEnableAutoReset(bool isEnabled)
{
    m_isAutoResetEnabled = isEnabled;
}

AverageCalculator::AverageCalculator() {}

double AverageCalculator::proceed(double newValue) {
    if(m_isAutoResetEnabled && newValue != e172::Math::null && (std::abs(averageValue - newValue) / newValue) > m_autoResetThreshold) {
        averageValue = newValue;
    }
    averageValue = ((averageValue * sampleCount + newValue) / (sampleCount + 1));
    sampleCount++;
    return averageValue;
}

