namespace doris {

class ColumnVectorTest : public testing::Test {
public:
    ColumnVectorTest() : _mem_pool(&_mem_tracker) {}
protected:
    void SetUp() override {}
    void TearDown() override {}
private:
    MemTracker _mem_tracker;
    MemPool _mem_pool;
};

template <FieldType field_type>
void test_scalar_column_vector_operations(std::shared_ptr<const TypeInfo> type_info, const uint8_t* source_data,
                                          size_t total_elements) {
    using ValueType = typename TypeTraits<field_type>::CppType;
    ValueType* source = (ValueType*)source_data;
    size_t VALUE_SIZE = sizeof(ValueType);
    size_t initial_capacity = total_elements / 2;

    std::unique_ptr<ColumnVectorBatch> column_batch;
    ASSERT_TRUE(ColumnVectorBatch::create(initial_capacity, true, type_info, nullptr, &column_batch).ok());

    memcpy(column_batch->mutable_cell_ptr(0), source, initial_capacity * VALUE_SIZE);
    column_batch->set_null_bits(0, initial_capacity, false);

    ASSERT_TRUE(column_batch->resize(total_elements).ok());

    size_t remaining_elements = total_elements - initial_capacity;
    memcpy(column_batch->mutable_cell_ptr(initial_capacity), source + initial_capacity, 
           remaining_elements * VALUE_SIZE);
    column_batch->set_null_bits(initial_capacity, remaining_elements, false);

    for (size_t position = 0; position < total_elements; ++position) {
        if (type_info->type() == OLAP_FIELD_TYPE_VARCHAR ||
            type_info->type() == OLAP_FIELD_TYPE_CHAR) {
            Slice* src_slice = (Slice*)source_data;
            ASSERT_EQ(src_slice[position].to_string(),
                      reinterpret_cast<const Slice*>(column_batch->cell_ptr(position))->to_string())
                    << "position:" << position;
        } else {
            ASSERT_EQ(source[position], *reinterpret_cast<const ValueType*>(column_batch->cell_ptr(position)));
        }
    }
}

template <FieldType element_type>
void test_array_column_vector_operations(std::shared_ptr<const TypeInfo> array_type_info, size_t num_arrays,
                                         CollectionValue* test_data) {
    DCHECK(num_arrays > 1);
    using ElementValueType = typename TypeTraits<element_type>::CppType;
    size_t ELEMENT_SIZE = sizeof(ElementValueType);

    TabletColumn array_column(OLAP_FIELD_AGGREGATION_NONE, OLAP_FIELD_TYPE_ARRAY);
    TabletColumn element_column(OLAP_FIELD_AGGREGATION_NONE, element_type, true, 0, 0);
    array_column.add_sub_column(element_column);

    Field* field = FieldFactory::create(array_column);
    size_t initial_array_count = num_arrays / 2;

    std::unique_ptr<ColumnVectorBatch> column_batch;
    ASSERT_TRUE(
            ColumnVectorBatch::create(initial_array_count, true, array_type_info, field, &column_batch).ok());

    auto* array_batch = reinterpret_cast<ArrayColumnVectorBatch*>(column_batch.get());
    ColumnVectorBatch* element_batch = array_batch->elements();
    ColumnVectorBatch* offset_batch = array_batch->offsets();

    // First write operation
    for (size_t i = 0; i < initial_array_count; ++i) {
        uint32_t len = test_data[i].length();
        memcpy(offset_batch->mutable_cell_ptr(1 + i), &len, sizeof(uint32_t));
    }
    array_batch->set_null_bits(0, initial_array_count, false);
    array_batch->get_offset_by_length(0, initial_array_count);

    size_t first_element_write_count = array_batch->item_offset(initial_array_count) - array_batch->item_offset(0);
    ASSERT_TRUE(element_batch->resize(first_element_write_count).ok());

    for (size_t i = 0; i < initial_array_count; ++i) {
        memcpy(element_batch->mutable_cell_ptr(array_batch->item_offset(i)), test_data[i].data(),
               test_data[i].length() * ELEMENT_SIZE);
    }
    element_batch->set_null_bits(0, first_element_write_count, false);
    array_batch->prepare_for_read(0, initial_array_count, false);

    // Second write operation
    ASSERT_TRUE(array_batch->resize(num_arrays).ok());

    for (int i = initial_array_count; i < num_arrays; ++i) {
        uint32_t len = test_data[i].length();
        memcpy(offset_batch->mutable_cell_ptr(i + 1), &len, sizeof(uint32_t));
    }
    array_batch->set_null_bits(initial_array_count, num_arrays - initial_array_count, false);
    array_batch->get_offset_by_length(initial_array_count, num_arrays - initial_array_count);

    size_t total_element_count = array_batch->item_offset(num_arrays);
    ASSERT_TRUE(element_batch->resize(total_element_count).ok());

    for (size_t i = initial_array_count; i < num_arrays; ++i) {
        memcpy(element_batch->mutable_cell_ptr(array_batch->item_offset(i)), test_data[i].data(),
               test_data[i].length() * ELEMENT_SIZE);
    }

    size_t second_element_write_count = total_element_count - first_element_write_count;
    element_batch->set_null_bits(first_element_write_count, second_element_write_count, false);
    array_batch->prepare_for_read(0, num_arrays, false);

    for (size_t idx = 0; idx < num_arrays; ++idx) {
        ASSERT_TRUE(array_type_info->equal(&test_data[idx], array_batch->cell_ptr(idx)))
                << "idx:" << idx;
    }
    delete field;
}

TEST_F(ColumnVectorTest, scalar_column_vector_basic_test) {
    {
        size_t count = 2048;
        auto* values = new uint8_t[count];
        for (int index = 0; index < count; ++index) {
            values[index] = static_cast<uint8_t>(index);
        }
        auto type_info = get_scalar_type_info(OLAP_FIELD_TYPE_TINYINT);
        test_scalar_column_vector_operations<OLAP_FIELD_TYPE_TINYINT>(type_info, values, count);
        delete[] values;
    }
    {
        size_t count = 2048;
        auto* char_values = new Slice[count];
        for (int index = 0; index < count; ++index) {
            set_column_value_by_type(OLAP_FIELD_TYPE_CHAR, index, (char*)&char_values[index], &_mem_pool, 16);
        }
        auto type_info = get_scalar_type_info(OLAP_FIELD_TYPE_CHAR);
        test_scalar_column_vector_operations<OLAP_FIELD_TYPE_CHAR>(type_info, (uint8_t*)char_values, count);
        delete[] char_values;
    }
}

TEST_F(ColumnVectorTest, array_column_vector_basic_test) {
    size_t num_arrays = 2048;
    size_t num_elements = num_arrays * 3;
    {
        auto* array_values = new CollectionValue[num_arrays];
        bool null_flags[3] = {false, false, false};
        auto* element_values = new uint8_t[num_elements];
        memset(null_flags, 0, sizeof(bool) * 3);

        for (int i = 0; i < num_elements; ++i) {
            element_values[i] = static_cast<uint8_t>(i);
            if (i % 3 == 0) {
                size_t array_pos = i / 3;
                array_values[array_pos].set_data(&element_values[i]);
                array_values[array_pos].set_null_signs(null_flags);
                array_values[array_pos].set_length(3);
            }
        }

        auto type_info = ArrayTypeInfoResolver::instance()->get_type_info(OLAP_FIELD_TYPE_TINYINT);
        test_array_column_vector_operations<OLAP_FIELD_TYPE_TINYINT>(type_info, num_arrays, array_values);

        // Test hash_code in CollectionValue
        type_info->hash_code(array_values, 0);

        delete[] array_values;
        delete[] element_values;
    }
}

} // namespace doris

int main(int argc, char** argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}

