#include <vector>
#include <string>

using namespace std;

class Solution {
public:
    // Find the longest common prefix among all strings in the input vector
    string longestCommonPrefix(vector<string>& words) {
        // Handle empty input case
        if (words.empty()) return "";

        // If only one string exists, it's the prefix itself
        if (words.size() == 1) return words[0];

        // Check for any empty string in the list
        for (const string& s : words) {
            if (s.empty()) return "";
        }

        // Start comparing from the first two strings
        int pos = -1;
        while (pos + 1 < words[0].size() && 
               pos + 1 < words[1].size() && 
               words[0][pos + 1] == words[1][pos + 1]) {
            pos++;
        }

        // No common prefix found
        if (pos < 0) return "";

        // Compare with remaining strings
        for (int j = 2; j < words.size(); ++j) {
            // Adjust position if current string is shorter
            if (words[j].size() - 1 < pos) {
                pos = words[j].size() - 1;
            }

            // Find common prefix with current string
            while (pos >= 0 && words[j][pos] != words[j-1][pos]) {
                pos--;
            }

            // No more common prefix
            if (pos < 0) return "";
        }

        return words[0].substr(0, pos + 1);
    }
};

