#include "include/printer.h"

namespace JSON {
    void Printer::serializeType(const Value &value, std::ostringstream &buffer) {
        switch (value.getType()) {
            case JSON_OBJECT:
                renderObject(value, buffer);
                break;
            case JSON_ARRAY:
                renderArray(value, buffer);
                break;
            case JSON_NUMBER:
                renderNumber(value, buffer);
                break;
            case JSON_BOOL:
                renderBoolean(value, buffer);
                break;
            case JSON_STRING:
                renderString(value, buffer);
                break;
            case EXT_BINARY:
                renderBinary(value, buffer);
                break;
            case JSON_NULL:
                buffer << "null";
                break;
        }
    }

    void Printer::renderObject(const Value &value, std::ostringstream &buffer) {
        bool isFirstEntry = true;
        buffer << "{";
        for (auto entry : value.as<Object>()) {
            if (!isFirstEntry) { buffer << ","; }
            buffer << "\"";
            buffer << entry.first;
            buffer << "\"";
            buffer << ":";
            serializeType(entry.second, buffer);
            isFirstEntry = false;
        }
        buffer << "}";
    }

    void Printer::renderArray(const Value &value, std::ostringstream &buffer) {
        bool isFirstElement = true;
        buffer << "[";
        for (auto element : value.as<Array>()) {
            if (!isFirstElement) { buffer << ","; }
            serializeType(element, buffer);
            isFirstElement = false;
        }
        buffer << "]";
    }

    void Printer::renderNumber(const Value &value, std::ostringstream &buffer) {
        buffer << value.as<double>();
    }

    void Printer::renderBoolean(const Value &value, std::ostringstream &buffer) {
        buffer << (value.as<bool>() ? "true" : "false");
    }

    void Printer::renderString(const Value &value, std::ostringstream &buffer) {
        buffer << "\"";
        buffer << value.as<std::string>();
        buffer << "\"";
    }

    void Printer::renderBinary(const Value &value, std::ostringstream &buffer) {
        buffer << "<<binary, size: ";
        buffer << value.as<std::string>().length();
        buffer << " bytes>>";
    }

    void Printer::output(const Value value, std::ostringstream &buffer) {
        serializeType(value, buffer);
    }

    std::string Printer::output(const Value value) {
        std::ostringstream buffer;
        serializeType(value, buffer);
        return buffer.str();
    }

    void PrettyPrinter::writeIndentation(std::ostringstream &buffer) {
        for (unsigned int level = 0; level < currentLevel; ++level) {
            buffer << " ";
        }
    }

    void PrettyPrinter::renderArray(const Value &data, std::ostringstream &buffer) {
        bool firstEntry = true;
        buffer << "[";
        for (auto entry : data.as<Array>()) {
            if (!firstEntry) { buffer << ", "; }
            serializeType(entry, buffer);
            firstEntry = false;
        }
        buffer << "]";
    }

    void PrettyPrinter::renderObject(const Value &data, std::ostringstream &buffer) {
        currentLevel += stepSize;
        buffer << "{\n";
        bool initialKey = true;
        for (auto keyVal : data.as<Object>()) {
            if (!initialKey) { buffer << ",\n"; }
            writeIndentation(buffer);
            buffer << "\"";
            buffer << keyVal.first;
            buffer << "\"";
            buffer << ": ";
            serializeType(keyVal.second, buffer);
            initialKey = false;
        }
        currentLevel -= stepSize;
        buffer << "\n";
        writeIndentation(buffer);
        buffer << "}";
    }
} // End namespace JSON

