// Convert image data format to corresponding OpenGL enum
GLenum gut::imageDataFormatToGLEnum(Image::DataFormat imgFormat)
{
    switch (imgFormat) {
        case Image::DataFormat::GRAY:
            return GL_RED;
        case Image::DataFormat::RGB:
            return GL_RGB;
        case Image::DataFormat::RGBA:
            return GL_RGBA;
    }
    // This should never execute unless new formats are introduced
    throw std::runtime_error("ERROR: imageDataFormatToGLEnum(): conversion from image data format to GL enum failed");
}

// Convert image data type to corresponding OpenGL enum
GLenum gut::imageDataTypeToGLEnum(Image::DataType imgType)
{
    switch (imgType) {
        case Image::DataType::U8:
            return GL_UNSIGNED_BYTE;
        case Image::DataType::U16:
            return GL_UNSIGNED_SHORT;
        case Image::DataType::F32:
            return GL_FLOAT;
    }
    // This should never execute unless new types are introduced
    throw std::runtime_error("ERROR: imageDataTypeToGLEnum(): conversion from image data type to GL enum failed");
}

// Convert OpenGL enum to image data format
Image::DataFormat gut::glEnumToImageDataFormat(GLenum glFormat)
{
    switch (glFormat) {
        case GL_RED:
        case GL_R8:
        case GL_R8I:
        case GL_R8UI:
        case GL_R16:
        case GL_R16I:
        case GL_R16UI:
        case GL_R16F:
        case GL_R32I:
        case GL_R32UI:
        case GL_R32F:
            return Image::DataFormat::GRAY;
        case GL_RGB:
        case GL_RGB8:
        case GL_RGB8I:
        case GL_RGB8UI:
        case GL_RGB16:
        case GL_RGB16I:
        case GL_RGB16UI:
        case GL_RGB16F:
        case GL_RGB32I:
        case GL_RGB32UI:
        case GL_RGB32F:
            return Image::DataFormat::RGB;
        case GL_RGBA:
        case GL_RGBA2:
        case GL_RGBA4:
        case GL_RGBA12:
        case GL_RGBA8:
        case GL_RGBA8I:
        case GL_RGBA8UI:
        case GL_RGBA8_SNORM:
        case GL_RGBA16:
        case GL_RGBA16I:
        case GL_RGBA16UI:
        case GL_RGBA16F:
        case GL_RGBA16_SNORM:
        case GL_RGBA32I:
        case GL_RGBA32UI:
        case GL_RGBA32F:
