		for (TObjectIterator<UScriptStruct> It; It; ++It)
		{
			UScriptStruct* CurrentStruct = *It;
			const bool bInheritsFromTableRowBase = CurrentStruct->IsChildOf(BaseTableRowStruct) && (CurrentStruct != BaseTableRowStruct);
			const bool bIsUserDefinedStruct = CurrentStruct->IsA<UUserDefinedStruct>();
			const bool bNotTransient = (CurrentStruct->GetOutermost() != GetTransientPackage());

			if ((bInheritsFromTableRowBase || bIsUserDefinedStruct) && bNotTransient)
			{
				ValidRowStructs.Add(CurrentStruct);
			}
		}
	}

	// Build UI layout
	this->ChildSlot
	[
		SNew(SBorder)
		.BorderImage(FEditorStyle::GetBrush(TEXT("Menu.Background")))
		.Padding(8)
		[
			SNew(SVerticalBox)

			// Import type selector label
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(STextBlock)
				.Text(LOCTEXT("ChooseAssetType", "Import As:"))
			]

			// Import type combo box
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SAssignNew(TypeComboBox, SComboBox<TSharedPtr<ECSVImportType>>)
				.OptionsSource(&AvailableImportTypes)
				.OnGenerateWidget(this, &SCSVImportOptions::CreateImportTypeWidget)
				[
					SNew(STextBlock)
					.Text(this, &SCSVImportOptions::GetCurrentImportTypeLabel)
				]
			]

			// Row struct selector label
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(STextBlock)
				.Text(LOCTEXT("ChooseRowType", "Choose DataTable Row Type:"))
				.Visibility(this, &SCSVImportOptions::ShouldShowRowStructOptions)
			]

			// Row struct combo box
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SAssignNew(RowStructComboBox, SComboBox<UScriptStruct*>)
				.OptionsSource(&ValidRowStructs)
				.OnGenerateWidget(this, &SCSVImportOptions::CreateRowStructWidget)
				.Visibility(this, &SCSVImportOptions::ShouldShowRowStructOptions)
				[
					SNew(STextBlock)
					.Text(this, &SCSVImportOptions::GetCurrentRowStructLabel)
				]
			]

			// Curve interpolation label
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(STextBlock)
				.Text(LOCTEXT("ChooseCurveType", "Choose Curve Interpolation Type:"))
				.Visibility(this, &SCSVImportOptions::ShouldShowCurveOptions)
			]

			// Curve interpolation combo box
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SAssignNew(CurveInterpComboBox, SComboBox<CurveInterpModePtr>)
				.OptionsSource(&AvailableInterpModes)
				.OnGenerateWidget(this, &SCSVImportOptions::CreateCurveInterpWidget)
				.Visibility(this, &SCSVImportOptions::ShouldShowCurveOptions)
				[
					SNew(STextBlock)
					.Text(this, &SCSVImportOptions::GetCurrentCurveInterpLabel)
				]
			]

			// OK / Cancel buttons
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(SHorizontalBox)
				+SHorizontalBox::Slot()
				.AutoWidth()
				[
					SNew(SButton)
					.Text(LOCTEXT("OK", "OK"))
					.OnClicked(this, &SCSVImportOptions::OnImport)
				]
				+SHorizontalBox::Slot()
				.AutoWidth()
				[
					SNew(SButton)
					.Text(LOCTEXT("Cancel", "Cancel"))
					.OnClicked(this, &SCSVImportOptions::OnCancel)
				]
			]
		]
	];

	// Initialize defaults
	TypeComboBox->SetSelectedItem(DataTableOption);

	// Pre-populate curve interpolation modes
	AvailableInterpModes.Add(MakeShareable(new ERichCurveInterpMode(ERichCurveInterpMode::RCIM_Constant)));
	AvailableInterpModes.Add(MakeShareable(new ERichCurveInterpMode(ERichCurveInterpMode::RCIM_Linear)));
	AvailableInterpModes.Add(MakeShareable(new ERichCurveInterpMode(ERichCurveInterpMode::RCIM_Cubic)));

	// Default selections are first items in respective lists
}

