FReply SCSVImportOptions::OnImport()
{
	ChosenStruct = RowStructComboBox->GetSelectedItem();
	SelectedImportType = *TypeComboBox->GetSelectedItem();

	if (CurveInterpComboBox->GetSelectedItem().IsValid())
	{
		SelectedCurveInterpMode = *CurveInterpComboBox->GetSelectedItem();
	}

	bShouldImport = true;

	if (WidgetWindow.IsValid())
	{
		WidgetWindow.Pin()->RequestDestroyWindow();
	}

	return FReply::Handled();
}

FReply SCSVImportOptions::OnCancel()
{
	bShouldImport = false;

	if (WidgetWindow.IsValid())
	{
		WidgetWindow.Pin()->RequestDestroyWindow();
	}

	return FReply::Handled();
}

