// Constants for Symphony protocol timing
const uint16_t kSymphonyBitMark = 400;
const uint16_t kSymphonyBitSpace = 1250;
const uint16_t kSymphonyOneMark = kSymphonyBitSpace;
const uint16_t kSymphonyOneSpace = kSymphonyBitMark;
const uint32_t kSymphonyEndGap = 4 * (kSymphonyBitMark + kSymphonyBitSpace);

#if SEND_SYMPHONY
/// Transmit a Symphony infrared message.
/// Status:  STABLE / Confirmed operational.
/// @param[in] payload The data word to be transmitted.
/// @param[in] bitCount Number of bits in the payload.
/// @param[in] repeatCount How many times to repeat the transmission.
void IRsend::sendSymphony(uint64_t payload, uint16_t bitCount, uint16_t repeatCount) {
  sendGeneric(0, 0,
              kSymphonyOneMark, kSymphonyOneSpace,
              kSymphonyBitMark, kSymphonyBitSpace,
              0, kSymphonyEndGap,
              payload, bitCount, 38000, true, repeatCount, kDutyDefault);
}
#endif  // SEND_SYMPHONY

#if DECODE_SYMPHONY
/// Decode an incoming Symphony infrared message.
/// Status: STABLE / Verified working.
/// @param[in,out] results Pointer to decode result structure.
/// @param[in] startIndex Starting position in raw buffer for decoding.
/// @param[in] expectedBits Expected number of data bits.
/// @param[in] requireStrict Whether to enforce strict bit-count validation.
/// @return True if decoding succeeded, false otherwise.
bool IRrecv::decodeSymphony(decode_results *results, uint16_t startIndex,
                            const uint16_t expectedBits, const bool requireStrict) {
  uint64_t decodedData = 0;

  // Check minimum buffer size requirement
  if (results->rawlen < 2 * expectedBits + startIndex - 1)
    return false;  // Insufficient samples for valid SYMPHONY frame.

  // Enforce bit count if strict mode is enabled
  if (requireStrict && expectedBits != kSymphonyBits) 
    return false;

  // Attempt generic matching with Symphony-specific parameters
  if (!matchGenericConstBitTime(results->rawbuf + startIndex, &decodedData,
                                results->rawlen - startIndex,
                                expectedBits,
                                0, 0,  // No header pulses
                                kSymphonyOneMark, kSymphonyBitMark,
                                0, kSymphonyEndGap, true,
                                _tolerance, 0))
    return false;

  // Store successful decode results
  results->value = decodedData;
  results->decode_type = decode_type_t::SYMPHONY;
  results->bits = expectedBits;
  results->address = 0;
  results->command = 0;
  return true;
}
#endif  // DECODE_SYMPHONY

