/**
 * Updates resource trends after changes in resources due to operations.
 */
void ResourceBreakdownPanel::updateResourceStatus()
{
	COMMON_METALS_TREND = evaluateTrend(mPreviousResources.commonMetals(), mPlayerResources->commonMetals());
	COMMON_MINERALS_TREND = evaluateTrend(mPreviousResources.commonMinerals(), mPlayerResources->commonMinerals());
	RARE_METALS_TREND = evaluateTrend(mPreviousResources.rareMetals(), mPlayerResources->rareMetals());
	RARE_MINERALS_TREND = evaluateTrend(mPreviousResources.rareMinerals(), mPlayerResources->rareMinerals());

	COMMON_MET_COLOR = TREND_TEXT_COLOR[COMMON_METALS_TREND];
	COMMON_MIN_COLOR = TREND_TEXT_COLOR[COMMON_MINERALS_TREND];
	RARE_MET_COLOR = TREND_TEXT_COLOR[RARE_METALS_TREND];
	RARE_MIN_COLOR = TREND_TEXT_COLOR[RARE_MINERALS_TREND];
}

