extern "C"
{
// Declarations from ${CMSIS-RTOS}/SRC/rt_Time.h.
extern std::uint32_t rtos_system_time;
// Declarations from ${CMSIS-RTOS}/SRC/RTX_Config.h.
extern std::uint32_t const rtos_timer_reload_value;
extern std::uint32_t get_current_tick_count(void);
extern std::uint32_t check_overflow_flag(void);
} // extern "C"

namespace std
{
// ----=====================================================================----
//     Internal utilities
// ----=====================================================================----
// Monitor the overflow occurrences of rtos_system_time. To achieve this,
// we store the upper four bits of rtos_system_time along with an overflow counter:
// +------------------+------------------+
// | rtos_system_time[31:28] | OverflowCount |
// |        (4 bit)         |    (28 bit)    |
// +------------------+------------------+
//
// This data structure is accessed concurrently by multiple threads.
static atomic<std::uint32_t> weos_chrono_overflow_counter{0};

// Retrieves the current value of the fastest available timer, while
// correctly handling overflows in rtos_system_time.
// For correctness, this function must be invoked frequently enough so that
// no overflow event is missed — specifically, at least once every 2^28 intervals
// of rtos_system_time.
static std::int64_t weos_chrono_read_high_precision_clock()
{
    // Phase 1: Acquire a consistent snapshot of (tick_count, time_value).
    // The loop below may be interrupted at any point; thus, we verify consistency.
    std::uint32_t tick_val, curr_time, tick_val2, curr_time2;
    do
    {
        atomic_thread_fence(memory_order_seq_cst);
        tick_val = get_current_tick_count();
        curr_time = check_overflow_flag() ? rtos_system_time + 1 : rtos_system_time;
        atomic_thread_fence(memory_order_seq_cst);
        tick_val2 = get_current_tick_count();
        curr_time2 = check_overflow_flag() ? rtos_system_time + 1 : rtos_system_time;
    } while (tick_val2 > tick_val || curr_time != curr_time2);

    // Phase 2: Update overflow tracking based on the most significant bits.
    std::uint32_t msb_bits = curr_time & 0xF0000000;
    std::uint32_t overflow_count;
    while (true)
    {
        std::uint32_t current_data = weos_chrono_overflow_counter.load();
        std::uint32_t stored_msb = current_data & 0xF0000000;
        overflow_count = current_data & 0x0FFFFFFF;

        if (msb_bits == stored_msb)
        {
            // Common case: MSBs unchanged — nothing to update.
            break;
        }
        else
        {
            // MSB changed — possibly due to wrap-around.
            if (msb_bits < stored_msb)
                ++overflow_count;

            std::uint32_t new_data = msb_bits | overflow_count;
            if (weos_chrono_overflow_counter.compare_exchange_weak(current_data, new_data))
                break;
        }
    }

    return (((std::uint64_t)overflow_count << 32) | curr_time) * (rtos_timer_reload_value + 1) + tick_val;
}

namespace chrono
{
// ----=====================================================================----
//     system_clock implementation
// ----=====================================================================----
system_clock::time_point system_clock::now()
{
    static_assert(WEOS_SYSTEM_CLOCK_FREQUENCY % WEOS_SYSTICK_FREQUENCY == 0,
                  "System clock frequency must be an integer multiple of SysTick frequency");

    static constexpr std::uint64_t ticks_per_interval
            = WEOS_SYSTEM_CLOCK_FREQUENCY / WEOS_SYSTICK_FREQUENCY;

    return time_point(duration(weos_chrono_read_high_precision_clock() / ticks_per_interval));
}

// ----=====================================================================----
//     high_resolution_clock implementation
// ----=====================================================================----
high_resolution_clock::time_point high_resolution_clock::now()
{
    return time_point(duration(weos_chrono_read_high_precision_clock()));
}
} // namespace chrono
} // namespace std

