#include <iostream>
#include <vector>
using namespace std;

class Solution {
private:
    int rows;
    int cols;
    int targetColor;
    int sourceColor;
    int directions[4][2] = {{-1,0},{1,0},{0,-1},{0,1}};

public:
    vector<vector<int>> floodFill(vector<vector<int>>& grid, int row, int col, int newColor) {
        rows = grid.size();
        if (rows == 0) {
            return grid;
        }

        cols = grid[0].size();
        if (cols == 0) {
            return grid;
        }

        if(!isValid(row, col)){
            return grid;
        }


        this->targetColor = newColor;
        this->sourceColor = grid[row][col];

        if (this->targetColor == this->sourceColor) {
            return grid;
        }

        fill(grid, row, col);
        return grid;
    }

     void fill(vector<vector<int>>&image, int x,int y){
         if (image[x][y] != sourceColor) {
             return;
         }

         image[x][y] = targetColor;

        for (int i = 0; i < 4; i++) {
            int newX = x + directions[i][0];
            int newY = y + directions[i][1];
            if (isValid(newX,newY) && image[newX][newY] == sourceColor) {
                fill(image, newX, newY);
            }
        }
    }

    bool isValid(int x ,int y){
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
};

