#pragma pack(push, 1)
struct SFileHeader_NVX2
{
    U32 fileSignature;
    U32 groupCount;
    U32 vertexCountTotal;
    U32 bytesPerVertex;
    U32 triangleCountTotal; // originally numIndices * 3
    U32 edgeCount;
    U32 activeVertexComponents;
};
struct SGroupInfo_NVX2
{
    U32 startVertex;
    U32 vertexCount;
    U32 startTriangle;
    U32 triangleCount;
    U32 startEdge;
    U32 edgeCountInGroup;
};
#pragma pack(pop)

enum EVertexComponentFlag_NVX2
{
    Position3 = (1 << 0),
    NormalVec = (1 << 1),
    TexCoord0 = (1 << 2),
    TexCoord1 = (1 << 3),
    TexCoord2 = (1 << 4),
    TexCoord3 = (1 << 5),
    VertexColor = (1 << 6),
    TangentVec = (1 << 7),
    BitangentVec = (1 << 8),
    SkinWeights = (1 << 9),
    SkinJointIdx = (1 << 10),
    Position4 = (1 << 11),
    ComponentCount = 12,
    AllComponentsMask = ((1 << ComponentCount) - 1)
};

static void BuildVertexLayout(U32 Flags, std::vector<Render::CVertexComponent>& Layout)
{
    Render::CVertexComponent Desc;
    Desc.Stream = 0;
    Desc.ByteOffset = Render::VertexComponentOffsetAuto;
    Desc.NameOverride = nullptr;
    Desc.IsInstanced = false;

    if (Flags & Position3)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_3;
        Desc.Semantic = Render::EVertexComponentSemantic::Position;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }
    else if (Flags & Position4)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_4;
        Desc.Semantic = Render::EVertexComponentSemantic::Position;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & NormalVec)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_3;
        Desc.Semantic = Render::EVertexComponentSemantic::Normal;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & TexCoord0)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_2;
        Desc.Semantic = Render::EVertexComponentSemantic::TexCoord;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & TexCoord1)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_2;
        Desc.Semantic = Render::EVertexComponentSemantic::TexCoord;
        Desc.SemanticIndex = 1;
        Layout.push_back(Desc);
    }

    if (Flags & TexCoord2)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_2;
        Desc.Semantic = Render::EVertexComponentSemantic::TexCoord;
        Desc.SemanticIndex = 2;
        Layout.push_back(Desc);
    }

    if (Flags & TexCoord3)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_2;
        Desc.Semantic = Render::EVertexComponentSemantic::TexCoord;
        Desc.SemanticIndex = 3;
        Layout.push_back(Desc);
    }

    if (Flags & VertexColor)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_4;
        Desc.Semantic = Render::EVertexComponentSemantic::Color;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & TangentVec)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_3;
        Desc.Semantic = Render::EVertexComponentSemantic::Tangent;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & BitangentVec)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_3;
        Desc.Semantic = Render::EVertexComponentSemantic::Bitangent;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & SkinWeights)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_4;
        Desc.Semantic = Render::EVertexComponentSemantic::BoneWeights;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }

    if (Flags & SkinJointIdx)
    {
        Desc.Format = Render::EVertexComponentFormat::Float32_4;
        Desc.Semantic = Render::EVertexComponentSemantic::BoneIndices;
        Desc.SemanticIndex = 0;
        Layout.push_back(Desc);
    }
}

//---------------------------------------------------------------------
const Core::CRTTI& CMeshLoaderNVX2::GetResultType() const
{
    return Render::CMeshData::RTTI;
}

//---------------------------------------------------------------------
Core::PObject CMeshLoaderNVX2::CreateResource(CStrID ResourceID)
{
    const char* pSubName;
    IO::PStream pStream = _ResMgr.CreateResourceStream(ResourceID.CStr(), pSubName, IO::SAP_SEQUENTIAL);
    if (!pStream || !pStream->IsOpened())
        return nullptr;

    IO::CBinaryReader Reader(*pStream);

    // NVX2 format always uses triangle list and 16-bit indices
    SFileHeader_NVX2 Header;
    if (!Reader.Read(Header) || Header.fileSignature != 'NVX2')
        return nullptr;

    Header.triangleCountTotal *= 3;

    Render::PMeshData pMesh = n_new(Render::CMeshData);
    pMesh->IndexType = Render::Index_16;
    pMesh->VertexCount = Header.vertexCountTotal;
    pMesh->IndexCount = Header.triangleCountTotal;

    CArray<Render::CPrimitiveGroup> PrimitiveGroups;
    PrimitiveGroups.Resize(Header.groupCount);

    for (U32 idx = 0; idx < Header.groupCount; ++idx)
    {
        SGroupInfo_NVX2 GroupDesc;
        Reader.Read(GroupDesc);

        Render::CPrimitiveGroup& Group = PrimitiveGroups.At(idx);
        Group.FirstVertex = GroupDesc.startVertex;
        Group.VertexCount = GroupDesc.vertexCount;
        Group.FirstIndex = GroupDesc.startTriangle * 3;
        Group.IndexCount = GroupDesc.triangleCount * 3;
        Group.Topology = Render::Prim_TriList;
    }

    BuildVertexLayout(Header.activeVertexComponents, pMesh->VertexFormat);

    // Load vertex buffer data
    UPTR vbSize = Header.vertexCountTotal * Header.bytesPerVertex * sizeof(float);
    pMesh->VBData.reset(n_new(Data::CBufferMallocAligned(vbSize, 16)));
    pStream->Read(pMesh->VBData->GetPtr(), vbSize);

    // Load index buffer data
    UPTR ibSize = Header.triangleCountTotal * sizeof(U16);
    pMesh->IBData.reset(n_new(Data::CBufferMallocAligned(ibSize, 16)));
    pStream->Read(pMesh->IBData->GetPtr(), ibSize);

    pMesh->InitGroups(&PrimitiveGroups.Front(), PrimitiveGroups.GetCount(), PrimitiveGroups.GetCount(), 1, false, true);
    return pMesh;
}
//---------------------------------------------------------------------
}

