#include <vector>
#include <algorithm>
#include <set>
#include <climits>
#include <numeric>

class Solution {
public:
    int maxEvents(std::vector<std::vector<int>>& events) {
        // Sort events by their end day (second element)
        std::sort(events.begin(), events.end(), [](const std::vector<int>& x, const std::vector<int>& y) {
            return x[1] < y[1];
        });

        int earliest_start = INT_MAX;
        int latest_end = INT_MIN;

        // Find the overall range of days
        for (const auto& event : events) {
            earliest_start = std::min(earliest_start, event[0]);
            latest_end = std::max(latest_end, event[1]);
        }

        // Create a set containing all possible days in the range
        std::vector<int> all_days(latest_end - earliest_start + 1);
        std::iota(all_days.begin(), all_days.end(), earliest_start);
        std::set<int> available_days(all_days.begin(), all_days.end());

        int count = 0;

        // Process each event
        for (auto& event : events) {
            int start_day = event[0];
            int end_day = event[1];

            // Find the first available day >= start_day
            auto it = available_days.lower_bound(start_day);

            // If no valid day exists or the day is after the event ends, skip
            if (it == available_days.end() || *it > end_day) {
                continue;
            }

            // Assign this day to the event
            available_days.erase(it);
            ++count;
        }

        return count;
    }
};

