namespace {
L<C>& add_semicolons(L<C>& input_script) {
    char prev_non_space = '\0';
    for (C& symbol : input_script) {
        const char ch = C::rep(symbol);
        if (ch == '\n' && prev_non_space != ';')
            symbol = C(';');
        if (!isspace(ch)) prev_non_space = ch;
    }
    return input_script;
}
} // unnamed

int main(int argc, char* argv[]) {
    L<S>           word_list{"in"_s};
    KV<S, KV<S,O>> environment;
    const S        module_id(0);
    environment.add(module_id, init_module(module_id));
    KV<S,O>        system_module(init_module("sys"_s));
    bool debug_mode = false;

    for (int index = 1; index < argc; ) {
        const char* const current_arg = argv[index++];
        if (current_arg[0] == '-') {
            if (current_arg[1] == 't') debug_mode = true;
        } else {
            L<L<C>> argument_list(argc - index);
            for (int pos = 0; index < argc; ++index, ++pos)
                argument_list[pos] = L<C>(argv[index], argv[index] + strlen(argv[index]));
            system_module.add("argv"_s, argument_list);
            environment.add("sys"_s , system_module);
            L<C> source_code = read_text(current_arg);
            add_semicolons(source_code);
            try {
                O evaluation_result(interp(environment, source_code, word_list, debug_mode));
                H(1) << evaluation_result << '\n' << flush;
            } catch (const Exception& error) {
                H(2) << error.what() << '\n';
            }
        }
    }

    if (isatty(0)) H(1) << "  " << flush;
    L<C> input_line = getline();
    for (; trim(input_line) != "\\\\"; input_line = getline()) {
        try {
            const L<C> processed_cmd = trim(input_line);
            if (processed_cmd.size()) {
                if (trim(processed_cmd)[0] != C('\\')) {
                    const O eval_output(interp(environment, processed_cmd, word_list, debug_mode));
                    if (eval_output->type != generic_null_type)
                        H(1) << eval_output << '\n' << flush;
                } else {
                    H(1) << "nyi: \\ commands";
                }
            }
        } catch (const Exception& error) {
            H(2) << '\'' << error.what() << '\n' << flush;
        }
        if (isatty(0)) H(1) << "  " << flush;
    }
}

