        .take_value();

enum ClockState { IDENTICAL, WITH_DELAY, RATE_CORRECTION };

class MixStageTest : public testing::ThreadingModelFixture {
  static constexpr uint32_t kBlockLengthFrames = 240;
 protected:
  void Initialize() {
    device_clock_ =
        AudioClock::CreateAsDeviceStatic(clock::CloneOfMonotonic(), AudioClock::kMonotonicDomain);
    mixer_stage_ = std::make_shared<MixStage>(kFormat, kBlockLengthFrames, timeline_func_,
                                              device_clock_);
  }
  zx::time future_time(zx::duration delta) { return zx::time(delta.to_nsecs()); }
  fbl::RefPtr<VersionedTimelineFunction> timeline_func_ =
      fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(TimelineRate(
          Fixed(kFormat.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  template <typename T, size_t N>
  std::array<T, N>& cast_to_array(void* ptr, size_t skip_elements = 0) {
    return reinterpret_cast<std::array<T, N>&>(static_cast<T*>(ptr)[skip_elements]);
  }

  AudioClock GenerateCustomClock() { return AudioClock::CreateAsCustom(clock::CloneOfMonotonic()); }

  AudioClock ConfigureFactoryWithClockOffset(zx::duration offset, testing::PacketFactory& factory);
  void RunTrimTest(ClockState state);
  void RunUniformMixTest(ClockState state);
  void RunSingleInputTest(ClockState state);
  void RunPositionAccuracyTest(ClockState state, int32_t ppm_adjust = 0);

  std::shared_ptr<MixStage> mixer_stage_;
  AudioClock device_clock_;
