AudioClock MixStageTest::ConfigureFactoryWithClockOffset(zx::duration offset,
                                                         testing::PacketFactory& factory) {
  auto custom_clock_result =
      clock::testing::CreateCustomClock({.start_val = zx::clock::get_monotonic() + offset});
  EXPECT_TRUE(custom_clock_result.is_ok());
  zx::clock custom_clock = custom_clock_result.take_value();
  EXPECT_TRUE(custom_clock.is_valid());

  auto offset_result = clock::testing::GetOffsetFromMonotonic(custom_clock);
  EXPECT_TRUE(offset_result.is_ok());
  auto actual_offset = offset_result.take_value();

  int64_t seek_frame = round(
      static_cast<double>(kFormat.frames_per_second() * actual_offset.get()) / ZX_SEC(1));
  factory.SeekToFrame(seek_frame);
  return AudioClock::CreateAsCustom(std::move(custom_clock));
}

void MixStageTest::RunTrimTest(ClockState state) {
  auto timeline_function = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormat.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  std::shared_ptr<PacketQueue> queue;
  testing::PacketFactory packet_factory(dispatcher(), kFormat, PAGE_SIZE);

  if (state == ClockState::IDENTICAL) {
    queue = std::make_shared<PacketQueue>(kFormat, timeline_function, GenerateCustomClock());
  } else if (state == ClockState::WITH_DELAY) {
    AudioClock custom_audio_clock =
        ConfigureFactoryWithClockOffset(zx::sec(-2), packet_factory);
    ASSERT_TRUE(custom_audio_clock.is_valid());
    queue = std::make_shared<PacketQueue>(kFormat, timeline_function, std::move(custom_audio_clock));
  } else {
    ASSERT_TRUE(state == ClockState::RATE_CORRECTION) << "Unknown clock state";
    ASSERT_TRUE(false) << "Multi-rate testing not yet implemented";
  }

  mixer_stage_->AddInput(queue);

  bool first_packet_released = false;
  bool second_packet_released = false;

  queue->PushPacket(packet_factory.CreatePacket(
      1.0, zx::msec(5), [&first_packet_released] { first_packet_released = true; }));
  queue->PushPacket(packet_factory.CreatePacket(
      0.5, zx::msec(5), [&second_packet_released] { second_packet_released = true; }));

  constexpr zx::duration kTolerance = zx::sec(1) / kFormat.frames_per_second();

  mixer_stage_->Trim(future_time(zx::msec(5) - kTolerance));
  RunLoopUntilIdle();
  EXPECT_FALSE(first_packet_released);

  mixer_stage_->Trim(future_time(zx::msec(5) + kTolerance));
  RunLoopUntilIdle();
  EXPECT_TRUE(first_packet_released);
  EXPECT_FALSE(second_packet_released);

  mixer_stage_->Trim(future_time(zx::msec(10) - kTolerance));
  RunLoopUntilIdle();
  EXPECT_FALSE(second_packet_released);

  mixer_stage_->Trim(future_time(zx::msec(10) + kTolerance));
  RunLoopUntilIdle();
  EXPECT_TRUE(second_packet_released);

  mixer_stage_->Trim(zx::time::infinite());
}

TEST_F(MixStageTest, Trim) { RunTrimTest(ClockState::IDENTICAL); }
TEST_F(MixStageTest, Trim_ClockOffset) { RunTrimTest(ClockState::WITH_DELAY); }

void MixStageTest::RunUniformMixTest(ClockState state) {
  auto timeline_function = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormat.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  testing::PacketFactory factory1(dispatcher(), kFormat, PAGE_SIZE);
  testing::PacketFactory factory2(dispatcher(), kFormat, PAGE_SIZE);

  auto queue1 =
      std::make_shared<PacketQueue>(kFormat, timeline_function, GenerateCustomClock());
  std::shared_ptr<PacketQueue> queue2;

  if (state == ClockState::IDENTICAL) {
    queue2 =
        std::make_shared<PacketQueue>(kFormat, timeline_function, GenerateCustomClock());
  } else if (state == ClockState::WITH_DELAY) {
    AudioClock custom_audio_clock;
    custom_audio_clock = ConfigureFactoryWithClockOffset(zx::sec(10), factory2);
    ASSERT_TRUE(custom_audio_clock.is_valid());
    queue2 = std::make_shared<PacketQueue>(kFormat, timeline_function, std::move(custom_audio_clock));
  } else {
    ASSERT_TRUE(state == ClockState::RATE_CORRECTION) << "Unknown clock state";
    ASSERT_TRUE(false) << "Multi-rate testing not yet implemented";
  }

  mixer_stage_->AddInput(queue1);
  mixer_stage_->AddInput(queue2);

  {
    queue1->PushPacket(factory1.CreatePacket(0.1, zx::msec(1)));
    queue1->PushPacket(factory1.CreatePacket(0.2, zx::msec(2)));
    queue1->PushPacket(factory1.CreatePacket(0.3, zx::msec(3)));
  }
  {
    queue2->PushPacket(factory2.CreatePacket(0.7, zx::msec(3)));
    queue2->PushPacket(factory2.CreatePacket(0.5, zx::msec(2)));
    queue2->PushPacket(factory2.CreatePacket(0.3, zx::msec(1)));
  }

  int64_t dest_start = 0;
  uint32_t dest_count = 96;

  {
    auto buf = mixer_stage_->ReadLock(future_time(zx::msec(2)), dest_start, dest_count);
    ASSERT_TRUE(buf);
    ASSERT_EQ(buf->length().Floor(), 96u);

    auto& arr1 = cast_to_array<float, 96>(buf->payload(), 0);
    EXPECT_THAT(arr1, Each(FloatEq(0.8f)));

    auto& arr2 = cast_to_array<float, 96>(buf->payload(), 96);
    EXPECT_THAT(arr2, Each(FloatEq(0.9f)));

    dest_start += dest_count;
  }

  {
    auto buf = mixer_stage_->ReadLock(future_time(zx::msec(4)), dest_start, dest_count);
    ASSERT_TRUE(buf);
    ASSERT_EQ(buf->length().Floor(), 96u);

    auto& arr1 = cast_to_array<float, 96>(buf->payload(), 0);
    EXPECT_THAT(arr1, Each(FloatEq(0.9f)));

    auto& arr2 = cast_to_array<float, 96>(buf->payload(), 96);
    EXPECT_THAT(arr2, Each(FloatEq(0.8f)));

    dest_start += dest_count;
  }

  {
    auto buf = mixer_stage_->ReadLock(future_time(zx::msec(6)), dest_start, dest_count);
    ASSERT_TRUE(buf);
    ASSERT_EQ(buf->length().Floor(), 96u);

    auto& arr1 = cast_to_array<float, 96>(buf->payload(), 0);
    EXPECT_THAT(arr1, Each(FloatEq(0.8f)));

    auto& arr2 = cast_to_array<float, 96>(buf->payload(), 96);
    EXPECT_THAT(arr2, Each(FloatEq(0.6f)));
  }

  mixer_stage_->Trim(zx::time::infinite());
}

TEST_F(MixStageTest, MixUniformFormats) { RunUniformMixTest(ClockState::IDENTICAL); }
TEST_F(MixStageTest, MixUniformFormats_ClockOffset) {
  RunUniformMixTest(ClockState::WITH_DELAY);
}

TEST_F(MixStageTest, MixFromRingBuffersSinc) {
  constexpr uint32_t kRingSizeFrames = 64;
  constexpr uint32_t kRingSizeSamples = kRingSizeFrames * kNumChannels;

  auto ring_buffer_endpoints = BaseRingBuffer::AllocateSoftwareBuffer(
      kFormat, timeline_func_, device_clock_, kRingSizeFrames);

  mixer_stage_->AddInput(ring_buffer_endpoints.reader, Mixer::Resampler::WindowedSinc);

  constexpr float kValue1 = 0.5f;
  constexpr float kValue2 = 0.7f;

  float* samples = reinterpret_cast<float*>(ring_buffer_endpoints.writer->virt());
  for (size_t i = 0; i < kRingSizeSamples / 2; ++i) {
    samples[i] = kValue1;
    samples[kRingSizeSamples / 2 + i] = kValue2;
  }

  constexpr uint32_t kRequestedFrames = kRingSizeFrames / 2;

  {
    auto buf = mixer_stage_->ReadLock(future_time(zx::msec(1)), 0, kRequestedFrames);
    ASSERT_TRUE(buf);
    ASSERT_EQ(buf->start().Floor(), 0u);
    ASSERT_EQ(buf->length().Floor(), kRequestedFrames);

    auto& arr = cast_to_array<float, kRequestedFrames * kNumChannels>(buf->payload(), 0);
    EXPECT_THAT(arr, Each(FloatEq(kValue1)));
  }

  {
    auto buf = mixer_stage_->ReadLock(future_time(zx::msec(2)), kRequestedFrames, kRequestedFrames);
    ASSERT_TRUE(buf);
    ASSERT_EQ(buf->start().Floor(), kRequestedFrames);
    ASSERT_EQ(buf->length().Floor(), kRequestedFrames);

    auto& arr = cast_to_array<float, kRequestedFrames * kNumChannels>(buf->payload(), 0);
    EXPECT_THAT(arr, Each(FloatEq(kValue2)));
  }
}

TEST_F(MixStageTest, MixNoInputs) {
  auto timeline_function = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormat.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  constexpr uint32_t kRequestedFrames = 48;
