void MixStageTest::RunPositionAccuracyTest(ClockState state, int32_t ppm_adjust) {
  clock::testing::ClockProperties props;
  if (state == ClockState::WITH_DELAY) {
    props = {.start_val = zx::clock::get_monotonic() - zx::sec(2)};
  } else if (state == ClockState::RATE_CORRECTION) {
    props = {.start_val = zx::time(0) + zx::sec(3), .rate_adjust_ppm = ppm_adjust};
  }

  auto custom_clock_result = clock::testing::CreateCustomClock(props);
  EXPECT_TRUE(custom_clock_result.is_ok()) << "CreateCustomClk err:" << custom_clock_result.error();
  zx::clock raw_clock = custom_clock_result.take_value();
  EXPECT_TRUE(raw_clock.is_valid());

  auto offset_result = clock::testing::GetOffsetFromMonotonic(raw_clock);
  EXPECT_TRUE(offset_result.is_ok()) << "GetOffsetFromMonotonic err:" << offset_result.error();
  auto clock_offset = offset_result.take_value();

  auto seek_frac_frame =
      Fixed::FromRaw(round(static_cast<double>(clock_offset.get()) * Fixed(1).raw_value() *
                           kFormat.frames_per_second() / ZX_SEC(1)));

  testing::PacketFactory factory(
      dispatcher(), kFormat,
      kFormat.frames_per_second() * kFormat.bytes_per_frame());
  factory.SeekToFrame(seek_frac_frame.Round());

  AudioClock audio_clock = AudioClock::CreateAsCustom(std::move(raw_clock));
  EXPECT_TRUE(audio_clock.is_valid());

  auto nsec_to_frac_src = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormat.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  std::shared_ptr<PacketQueue> queue =
      std::make_shared<PacketQueue>(kFormat, nsec_to_frac_src, std::move(audio_clock));

  auto& info = mixer_stage_->AddInput(queue)->source_info();

  Fixed upper_limit, lower_limit;

  if (ppm_adjust > 0) {
    upper_limit = Fixed::FromRaw(ppm_adjust * 8);
    lower_limit = Fixed::FromRaw(ppm_adjust * -16);
  } else {
    upper_limit = Fixed::FromRaw(ppm_adjust * -16);
    lower_limit = Fixed::FromRaw(ppm_adjust * 8);
  }

  if (ppm_adjust != 0) {
    upper_limit = std::max(upper_limit, Fixed::FromRaw(16));
    lower_limit = std::min(lower_limit, Fixed::FromRaw(-16));
  }

  constexpr Fixed kFinalUpperLimit = Fixed::FromRaw(8);
  constexpr Fixed kFinalLowerLimit = Fixed::FromRaw(-8);

  constexpr int kTotalIterations = 400;
  constexpr zx::duration kStepDuration = zx::msec(5);
  constexpr uint32_t frames_per_step = kBlockLengthFrames;

  Fixed max_error{0}, max_error_final{0};
  Fixed min_error{0}, min_error_final{0};
  int max_error_idx = 0, min_error_idx = 0;

  for (int idx = 0; idx < kTotalIterations; ++idx) {
    mixer_stage_->ReadLock(future_time(kStepDuration * idx), frames_per_step * idx, frames_per_step);
    EXPECT_EQ(info.next_dest_frame, frames_per_step * (idx + 1));

    if (info.frac_source_error > max_error) {
      max_error = info.frac_source_error;
      max_error_idx = idx;
    }
    if (info.frac_source_error < min_error) {
      min_error = info.frac_source_error;
      min_error_idx = idx;
    }

    if (idx >= kTotalIterations - 10) {
      max_error_final = std::max(info.frac_source_error, max_error_final);
      min_error_final = std::min(info.frac_source_error, min_error_final);
    }
  }

  EXPECT_LE(max_error, upper_limit)
      << "For rate_adjust_ppm " << ppm_adjust << ": error " << max_error.raw_value()
      << " <= limit " << upper_limit.raw_value() << " at mix_count " << max_error_idx
      << " (" << max_error_idx * kStepDuration.to_msecs() << " msec)";
  EXPECT_GE(min_error, lower_limit)
      << "For rate_adjust_ppm " << ppm_adjust << ": error " << min_error.raw_value()
      << " >= limit " << lower_limit.raw_value() << " at mix_count " << min_error_idx
      << " (" << min_error_idx * kStepDuration.to_msecs() << " msec)";

  if (ppm_adjust != 0) {
    EXPECT_LE(max_error_final, kFinalUpperLimit)
        << "for rate_adjust_ppm " << ppm_adjust << ": final error "
        << max_error_final.raw_value() << " <= limit " << kFinalUpperLimit.raw_value();
    EXPECT_GE(min_error_final, kFinalLowerLimit)
        << "For rate_adjust_ppm " << ppm_adjust << ": final error "
        << min_error_final.raw_value() << " >= limit " << kFinalLowerLimit.raw_value();
  }
}

