using namespace llvm;

MCSectionXCOFF::~MCSectionXCOFF() = default;

static StringRef getStorageClassString(XCOFF::StorageMappingClass SMC) {
  switch (SMC) {
  case XCOFF::XMC_DS:
    return "DS";
  case XCOFF::XMC_RW:
    return "RW";
  case XCOFF::XMC_PR:
    return "PR";
  default:
    report_fatal_error("Unknown storage-mapping class encountered.");
  }
}

void MCSectionXCOFF::PrintSwitchToSection(const MCAsmInfo &MAI, const Triple &T,
                                          raw_ostream &OS,
                                          const MCExpr *Subsection) const {
  if (isTextSection()) {
    if (getMappingClass() != XCOFF::XMC_PR)
      report_fatal_error("Unsupported storage-mapping class for .text csect");
    OS << "\t.csect " << getSectionName() << "["
       << getStorageClassString(getMappingClass())
       << "]" << '\n';
    return;
  }

  if (isDataSection()) {
    switch (getMappingClass()) {
    case XCOFF::XMC_RW:
    case XCOFF::XMC_DS:
      OS << "\t.csect " << getSectionName() << "["
         << getStorageClassString(getMappingClass()) << "]" << '\n';
      break;
    case XCOFF::XMC_TC0:
      OS << "\t.toc\n";
      break;
    default:
      report_fatal_error(
          "Unsupported storage-mapping class for .data csect.");
    }
    return;
  }

  if (isBSSLocalSection() || isCommonSection()) {
    assert((getMappingClass() == XCOFF::XMC_RW ||
            getMappingClass() == XCOFF::XMC_BS) &&
           "Unexpected storage-mapping class for common/bss csect.");
    assert(getCSectType() == XCOFF::XTY_CM &&
           "Incorrect csect type for .bss csect");
    // No directive needed when switching to section for commons.
    // '.comm' and '.lcomm' directives handle the required csect creation.
    return;
  }

  report_fatal_error("Printing for this SectionKind is not implemented.");
}

bool MCSectionXCOFF::UseCodeAlign() const { return isTextSection(); }
bool MCSectionXCOFF::isVirtualSection() const { return XCOFF::XTY_CM == Type; }

