// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* l, TreeNode* r) : val(x), left(l), right(r) {}
};

class Solution {
public:
    int findMaxDepth(TreeNode* node, int currentDepth) {
        if (node == nullptr) return currentDepth;
        currentDepth++;
        return max(findMaxDepth(node->left, currentDepth), 
                   findMaxDepth(node->right, currentDepth));
    }

    int findMaxDepth(TreeNode* root) {
        if (!root) return 0;
        return max(findMaxDepth(root->left), findMaxDepth(root->right)) + 1;
    }
};

int main() {
    TreeNode leafNode(2);
    TreeNode rootNode(1, &leafNode, nullptr);
    Solution solver;
    cout << "\n " << solver.findMaxDepth(&rootNode) << endl;
    return 0;
}

