    KeySequence::KeySequence(KeyVector keys) : 
        _keySequence(keys), _currentIndex(0)
    {            
    }

    bool  KeySequence::operator()(void)
    {
        if (Controller::IsKeyDown(_keySequence[_currentIndex]))
        {
            _currentIndex++;
            if (_currentIndex >= _keySequence.size())
            {
                _currentIndex = 0;
                return (true);
            }
            _timer.Reset();
        }

        if (_timer.IsElapsed(Seconds(1.0f)))
        {
            _currentIndex = 0;
            _timer.Reset();
        }

        return (false);
    }
}

