// Constants for revocation subpacket data
static const uint8_t revocation_code = OpenPGP::Subpacket::Tag2::Revoke::NO_REASON_SPECIFIED;
static const std::string revocation_reason = "";

// Helper function to populate Sub29 object with test data
static void POPULATE_TAG2_SUB29(OpenPGP::Subpacket::Tag2::Sub29 & sub29_obj) {
    sub29_obj.set_code(revocation_code);
    sub29_obj.set_reason(revocation_reason);
}

// Macro to verify Sub29 object contents match expected values
#define VERIFY_TAG2_SUB29(sub29_obj)            \
    EXPECT_EQ((sub29_obj).get_code(), revocation_code);        \
    EXPECT_EQ((sub29_obj).get_reason(), revocation_reason);    \
    EXPECT_EQ((sub29_obj).valid(true), OpenPGP::Status::SUCCESS);

// Test suite for Tag2 Subpacket 29 (Revocation Reason)
TEST(Tag2Sub29, ConstructorTests) {
    // Default constructor test
    OpenPGP::Subpacket::Tag2::Sub29 default_sub29;
    EXPECT_EQ(default_sub29.raw(), std::string(1, '\x00'));
    EXPECT_NO_THROW(POPULATE_TAG2_SUB29(default_sub29));

    // String constructor test
    {
        OpenPGP::Subpacket::Tag2::Sub29 from_string(default_sub29.raw());
        VERIFY_TAG2_SUB29(from_string);
    }

    // Copy constructor test
    {
        OpenPGP::Subpacket::Tag2::Sub29 copied_sub29(default_sub29);
        VERIFY_TAG2_SUB29(copied_sub29);
    }

    // Move constructor test
    {
        OpenPGP::Subpacket::Tag2::Sub29 moved_sub29(std::move(default_sub29));
        VERIFY_TAG2_SUB29(moved_sub29);
    }
}

TEST(Tag2Sub29, AssignmentOperatorTests) {
    OpenPGP::Subpacket::Tag2::Sub29 source_sub29;
    EXPECT_NO_THROW(POPULATE_TAG2_SUB29(source_sub29));

    // Copy assignment test
    {
        OpenPGP::Subpacket::Tag2::Sub29 assigned_sub29;
        assigned_sub29 = source_sub29;
        VERIFY_TAG2_SUB29(assigned_sub29);
    }

    // Move assignment test
    {
        OpenPGP::Subpacket::Tag2::Sub29 move_assigned_sub29;
        move_assigned_sub29 = std::move(source_sub29);
        VERIFY_TAG2_SUB29(move_assigned_sub29);
    }
}

TEST(Tag2Sub29, ReadWriteOperations) {
    const std::string expected_raw = std::string(1, revocation_code) + revocation_reason;
    OpenPGP::Subpacket::Tag2::Sub29 sub29_obj(expected_raw);
    VERIFY_TAG2_SUB29(sub29_obj);
    EXPECT_EQ(sub29_obj.raw(), expected_raw);
}

TEST(Tag2Sub29, ShowMethodTest) {
    OpenPGP::Subpacket::Tag2::Sub29 display_sub29;
    EXPECT_NO_THROW(POPULATE_TAG2_SUB29(display_sub29));
    EXPECT_NO_THROW(display_sub29.show());
}

TEST(Tag2Sub29, GetterSetterTest) {
    OpenPGP::Subpacket::Tag2::Sub29 test_sub29;
    POPULATE_TAG2_SUB29(test_sub29);
    VERIFY_TAG2_SUB29(test_sub29);
}

TEST(Tag2Sub29, CloneMethodTest) {
    OpenPGP::Subpacket::Tag2::Sub29 original_sub29;
    EXPECT_NO_THROW(POPULATE_TAG2_SUB29(original_sub29));

    OpenPGP::Subpacket::Sub::Ptr cloned_ptr = original_sub29.clone();
    EXPECT_NE(&original_sub29, cloned_ptr.get());

    VERIFY_TAG2_SUB29(*std::static_pointer_cast<OpenPGP::Subpacket::Tag2::Sub29>(cloned_ptr));
}

#include <cstring>

#define ROTR(val, bits) ((val >> bits) | (val << (32 - bits)))
#define Choice(var1, var2, var3) (var3 ^ (var1 & (var2 ^ var3)))
#define Majority(var1, var2, var3) ((var1 & var2) ^ (var3 & (var1 ^ var3)))
#define Sigma0(val) (ROTR(val, 2) ^ ROTR(val, 13) ^ ROTR(val, 22))
#define Sigma1(val) (ROTR(val, 6) ^ ROTR(val, 11) ^ ROTR(val, 25))
#define sigma0(val) (ROTR(val, 7) ^ ROTR(val, 18) ^ (val >> 3))
#define sigma1(val) (ROTR(val, 17) ^ ROTR(val, 19) ^ (val >> 10))
#define ROUND(v0,v1,v2,v3,v4,v5,v6,v7,k,data)		\
  v7 += Sigma1(v4) + Choice(v4, v5, v6) + k + data;	\
  v3 += v7;						\
  v7 += Sigma0(v0) + Majority(v0, v1, v2);

static void sha256HashBlock(const uint8_t *blockData, uint32_t *hashState) {
  uint32_t schedule[64];
  uint32_t v0, v1, v2, v3, v4, v5, v6, v7;
  int idx;

  /* Prepare the message schedule */
  for (idx = 0; idx < 16; ++idx) {
    schedule[idx] = (blockData[idx*4    ] << 24) 
                  | (blockData[idx*4 + 1] << 16) 
                  | (blockData[idx*4 + 2] << 8) 
                  |  blockData[idx*4 + 3];
  }

  for (; idx < 64; ++idx) {
    schedule[idx] = sigma1(schedule[idx-2]) + schedule[idx-7] + sigma0(schedule[idx-15]) + schedule[idx-16];
  }

  /* Initialize working variables */
  v0 = hashState[0];
  v1 = hashState[1];
  v2 = hashState[2];
  v3 = hashState[3];
  v4 = hashState[4];
  v5 = hashState[5];
  v6 = hashState[6];
  v7 = hashState[7];

  /* Compression loop */
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0x428a2f98, schedule[ 0]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0x71374491, schedule[ 1]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0xB5C0FBCF, schedule[ 2]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0xE9B5DBA5, schedule[ 3]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0x3956C25B, schedule[ 4]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0x59F111F1, schedule[ 5]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0x923F82A4, schedule[ 6]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0xAB1C5ED5, schedule[ 7]);
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0xD807AA98, schedule[ 8]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0x12835B01, schedule[ 9]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0x243185BE, schedule[10]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0x550C7DC3, schedule[11]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0x72BE5D74, schedule[12]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0x80DEB1FE, schedule[13]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0x9BDC06A7, schedule[14]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0xC19BF174, schedule[15]); 
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0xE49B69C1, schedule[16]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0xEFBE4786, schedule[17]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0x0FC19DC6, schedule[18]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0x240CA1CC, schedule[19]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0x2DE92C6F, schedule[20]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0x4A7484AA, schedule[21]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0x5CB0A9DC, schedule[22]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0x76F988DA, schedule[23]);
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0x983E5152, schedule[24]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0xA831C66D, schedule[25]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0xB00327C8, schedule[26]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0xBF597FC7, schedule[27]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0xC6E00BF3, schedule[28]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0xD5A79147, schedule[29]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0x06CA6351, schedule[30]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0x14292967, schedule[31]);
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0x27B70A85, schedule[32]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0x2E1B2138, schedule[33]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0x4D2C6DFC, schedule[34]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0x53380D13, schedule[35]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0x650A7354, schedule[36]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0x766A0ABB, schedule[37]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0x81C2C92E, schedule[38]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0x92722C85, schedule[39]);
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0xA2BFE8A1, schedule[40]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0xA81A664B, schedule[41]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0xC24B8B70, schedule[42]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0xC76C51A3, schedule[43]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0xD192E819, schedule[44]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0xD6990624, schedule[45]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0xF40E3585, schedule[46]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0x106AA070, schedule[47]);
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0x19A4C116, schedule[48]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0x1E376C08, schedule[49]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0x2748774C, schedule[50]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0x34B0BCB5, schedule[51]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0x391C0CB3, schedule[52]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0x4ED8AA4A, schedule[53]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0x5B9CCA4F, schedule[54]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0x682E6FF3, schedule[55]);
  ROUND(v0, v1, v2, v3, v4, v5, v6, v7, 0x748F82EE, schedule[56]);
  ROUND(v7, v0, v1, v2, v3, v4, v5, v6, 0x78A5636F, schedule[57]);
  ROUND(v6, v7, v0, v1, v2, v3, v4, v5, 0x84C87814, schedule[58]);
  ROUND(v5, v6, v7, v0, v1, v2, v3, v4, 0x8CC70208, schedule[59]);
  ROUND(v4, v5, v6, v7, v0, v1, v2, v3, 0x90BEFFFA, schedule[60]);
  ROUND(v3, v4, v5, v6, v7, v0, v1, v2, 0xA4506CEB, schedule[61]);
  ROUND(v2, v3, v4, v5, v6, v7, v0, v1, 0xBEF9A3F7, schedule[62]);
  ROUND(v1, v2, v3, v4, v5, v6, v7, v0, 0xC67178F2, schedule[63]);

  /* Update hash state */
  hashState[0] += v0;
  hashState[1] += v1;
  hashState[2] += v2;
  hashState[3] += v3;
  hashState[4] += v4;
  hashState[5] += v5;
  hashState[6] += v6;
  hashState[7] += v7;
}

void sha256(const uint8_t *message, const int messageLength, uint8_t *outputHash) {
  uint8_t buffer[64];
  uint32_t internalState[8];
  int blockLength, j;

  internalState[0] = 0x6a09e667;
  internalState[1] = 0xbb67ae85;
  internalState[2] = 0x3c6ef372;
  internalState[3] = 0xa54ff53a;
  internalState[4] = 0x510e527f;
  internalState[5] = 0x9b05688c;
  internalState[6] = 0x1f83d9ab;
  internalState[7] = 0x5be0cd19;

  for (j = 0; j + 64 <= messageLength; j += 64) {
    sha256HashBlock(message+j, internalState);
  }

  blockLength = messageLength - j;
  std::memcpy(buffer, message + j, blockLength);

  /* Pad the message */
  buffer[blockLength++] = 0x80;
  if (blockLength > 56) {
    while (blockLength < 64) {
      buffer[blockLength++] = 0;
    }
    sha256HashBlock(buffer, internalState);
    blockLength = 0;
  }

  while (blockLength < 56) {
    buffer[blockLength++] = 0;
  }

  buffer[56] = 0;
  buffer[57] = 0;
  buffer[58] = 0;
  buffer[59] = 0;
  buffer[60] = (uint8_t)(messageLength >> 21);
  buffer[61] = (uint8_t)(messageLength >> 13);
  buffer[62] = (uint8_t)(messageLength >> 5);
  buffer[63] = (uint8_t)(messageLength << 3);

  sha256HashBlock(buffer, internalState);

  /* Convert words to bytes in output */
  for (j = 0; j < 8; ++j) {
    outputHash[j*4]     = (uint8_t)(internalState[j] >> 24);
    outputHash[j*4 + 1] = (uint8_t)(internalState[j] >> 16);
    outputHash[j*4 + 2] = (uint8_t)(internalState[j] >> 8);
    outputHash[j*4 + 3] = (uint8_t)internalState[j];
  }
}

/** Fast sha256 for messageLength < 56 */
void sha256f(const uint8_t *message, const int messageLength, uint8_t *outputHash) {
  uint8_t buffer[64];
  uint32_t internalState[8];
  int blockLength, j;

  internalState[0] = 0x6a09e667;
  internalState[1] = 0xbb67ae85;
  internalState[2] = 0x3c6ef372;
  internalState[3] = 0xa54ff53a;
  internalState[4] = 0x510e527f;
  internalState[5] = 0x9b05688c;
  internalState[6] = 0x1f83d9ab;
  internalState[7] = 0x5be0cd19;

  blockLength = messageLength;
  std::memcpy(buffer, message, blockLength);

  /* Pad the message */
  buffer[blockLength++] = 0x80;
  while (blockLength < 56) {
    buffer[blockLength++] = 0;
  }

  buffer[56] = 0;
  buffer[57] = 0;
  buffer[58] = 0;
  buffer[59] = 0;
  buffer[60] = (uint8_t)(messageLength >> 21);
  buffer[61] = (uint8_t)(messageLength >> 13);
  buffer[62] = (uint8_t)(messageLength >> 5);
  buffer[63] = (uint8_t)(messageLength << 3);

  sha256HashBlock(buffer, internalState);

  /* Convert words to bytes in output */
  for (j = 0; j < 8; ++j) {
    outputHash[j*4    ] = (uint8_t)(internalState[j] >> 24);
    outputHash[j*4 + 1] = (uint8_t)(internalState[j] >> 16);
    outputHash[j*4 + 2] = (uint8_t)(internalState[j] >> 8);
    outputHash[j*4 + 3] = (uint8_t)internalState[j];
  }
}

#include "rive/animation/keyframe_double.hpp"
#include "rive/generated/core_registry.hpp"
using namespace rive;

// This entire class is intentionally misnamed to align with our editor codebase.
// While the editor operates with double-precision floats (float64) for numeric data,
// runtime operations only require single-precision (32-bit) floating-point numbers.
// Therefore, despite being named "double keyframe" for compatibility with editor conventions,
// values are internally stored and applied using 32-bit precision.
static void applyDoubleValue(Core* target, int propertyId, float blendFactor, float newValue)
{
	if (blendFactor == 1.0f)
	{
		CoreRegistry::setDouble(target, propertyId, newValue);
	}
	else
	{
		float inverseBlend = 1.0f - blendFactor;
		CoreRegistry::setDouble(
		    target,
		    propertyId,
		    CoreRegistry::getDouble(target, propertyId) * inverseBlend + newValue * blendFactor);
	}
}

void KeyFrameDouble::apply(Core* target, int propertyId, float blendFactor)
{
	applyDoubleValue(target, propertyId, blendFactor, value());
}

void KeyFrameDouble::applyInterpolation(Core* target,
                                        int propertyId,
                                        float currentTimestamp,
                                        const KeyFrame* subsequentFrame,
                                        float blendFactor)
{
	auto kfd = subsequentFrame->as<KeyFrameDouble>();
	const KeyFrameDouble& nextDoubleKey = *kfd;
	float t = (currentTimestamp - seconds()) / (nextDoubleKey.seconds() - seconds());

	if (CubicInterpolator* cubicCurve = interpolator())
	{
		t = cubicCurve->transform(t);
	}

	applyDoubleValue(
	    target, propertyId, blendFactor, 
	    value() + (nextDoubleKey.value() - value()) * t);
}

