    static std::string ApplySelectorFilter(
        const RenderCore::Techniques::TechniqueEntry& techniqueEntry,
        std::initializer_list<std::pair<const utf8*, const char*>> paramValues)
    {
        ParameterBox initialParams(paramValues);
        return BuildFlatStringTable(ShaderSourceParser::FilterSelectors(
            initialParams,
            techniqueEntry._selectorFiltering, ShaderSourceParser::SelectorFilteringRules{}));
    }

    TEST_CASE("TechniqueFileTests-TechniqueSelectorFiltering", "[rendercore_techniques]")
    {
        SECTION("testBlockA")
        {
            const char* techniqueDefinition = R"--(
                Shared=~
                    Selectors=~
                        CLASSIFY_NORMAL_MAP
                        SKIP_MATERIAL_DIFFUSE=~; relevance=<:(value!=0):>
                        SELECTOR_0=~; relevance=1
                Config=~
                    Inherit=~; Shared
                    Selectors=~
                        SELECTOR_0=1
            )--";

            InputStreamFormatter<utf8> parser{ MakeStringSection(techniqueDefinition) };
            RenderCore::Techniques::TechniqueSetFile techSet(parser, ::Assets::DirectorySearchRules{}, ::Assets::DependencyValidation{});
            (void)techSet;

            auto* configEntry = techSet.FindEntry(Hash64("Config"));
            REQUIRE(configEntry != nullptr);

            // Override SELECTOR_0 value; SKIP_MATERIAL_DIFFUSE excluded due to relevance check
            auto result0 = ApplySelectorFilter(
                *configEntry,
                {
                    std::make_pair("SELECTOR_0", "7"),
                    std::make_pair("SKIP_MATERIAL_DIFFUSE", "0")
                });
            REQUIRE(std::string{"SELECTOR_0=7"} == result0);

            // Default SELECTOR_0 used; SKIP_MATERIAL_DIFFUSE included; CLASSIFY_NORMAL_MAP overridden
            auto result1 = ApplySelectorFilter(
                *configEntry,
                {
                    std::make_pair("SKIP_MATERIAL_DIFFUSE", "9"),
                    std::make_pair("CLASSIFY_NORMAL_MAP", "12")
                });
            REQUIRE(std::string{"SELECTOR_0=1;CLASSIFY_NORMAL_MAP=12;SKIP_MATERIAL_DIFFUSE=9"} == result1);
        }

        SECTION("testBlockB")
        {
            const char* techSpec = R"--(
                Shared=~
                    Selectors=~
                        SELECTOR_0=~; relevance=<:(value!=0):>
                        SELECTOR_1=~; set=2; relevance=1
                        SELECTOR_2=~; relevance=<:(value!=5):>
                Config=~
                    Inherit=~; Shared
                    Selectors=~
                        SELECTOR_0=~; relevance=<:(value!=1):>
                        SELECTOR_1=3
                        SELECTOR_2=4
            )--";

            InputStreamFormatter<utf8> parser{ MakeStringSection(techSpec) };
            RenderCore::Techniques::TechniqueSetFile techSet(parser, ::Assets::DirectorySearchRules{}, ::Assets::DependencyValidation{});
            (void)techSet;

            auto* configEntry = techSet.FindEntry(Hash64("Config"));
            REQUIRE(configEntry != nullptr);

            // Config overrides inherited defaults; unknown selector ignored
            auto result0 = ApplySelectorFilter(
                *configEntry,
                {
                    std::make_pair("SELECTOR_0", "0"),
                    std::make_pair("UNKNOWN_SELECTOR", "6")
                });
            REQUIRE(std::string{"SELECTOR_2=4;SELECTOR_0=0;SELECTOR_1=3"} == result0);

            // When SELECTOR_2 is set to its non-relevant value (5), it's omitted entirely
            auto result1 = ApplySelectorFilter(
                *configEntry,
                {
                    std::make_pair("SELECTOR_2", "5")
                });
            REQUIRE(std::string{"SELECTOR_1=3"} == result1);
        }
    }
}

