#include <iostream>
#include <vector>
#include <iterator>

// Decodes a boolean sequence using XOR-based sliding window decoding
std::vector<bool> decode_sequence(const std::vector<bool>& input, int length, int window) {
  bool xor_accumulator = input[0];
  std::vector<bool> result(length, false);
  result[0] = input[0];

  for (int index = 1; index < length; ++index) {
    if (index >= window) {
      xor_accumulator ^= result[index - window];
    }
    result[index] = xor_accumulator ^ input[index];
    xor_accumulator ^= result[index];
  }

  return result;
}

int main() {
  int length, window;
  std::cin >> length >> window;

  int total_size = length + window - 1;
  std::vector<bool> input(total_size);

  char bit_char;
  for (size_t position = 0; position < input.size(); ++position) {
    std::cin >> bit_char;
    input[position] = bit_char - '0';
  }

  std::vector<bool> result = decode_sequence(input, length, window);
  std::ostream_iterator<bool> output_stream(std::cout);
  std::copy(result.begin(), result.end(), output_stream);

  return 0;
}

