// Generic array shuffling using reflection
void UImplotWrapperFunctionLibrary::GenericArray_Shuffle2(void* TargetArray, const FArrayProperty* ArrayProp)
{
    if (TargetArray)
    {
        FProperty* InnerProp = ArrayProp->Inner;
        const FBoolProperty* BoolProp = CastField<const FBoolProperty>(InnerProp);
        if (BoolProp)
        {
            ensure((BoolProp->ElementSize * BoolProp->ArrayDim) == sizeof(uint8));
            UE_LOG(LogTemp, Log, TEXT("BoolPropertyBoolPropertyBoolPropertyBoolPropertyBoolProperty"));
        }

        FScriptArrayHelper ArrayHelper(ArrayProp, TargetArray);
        int32 FinalIndex = ArrayHelper.Num() - 1;
        for (int32 pos = 0; pos <= FinalIndex; ++pos)
        {            
            int32 RandomPos = FMath::RandRange(pos, FinalIndex);
            if (pos != RandomPos)
            {
                ArrayHelper.SwapValues(pos, RandomPos);
            }
        }
    }
}

#include "libusb.h"
#include "device.h"
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <queue>
#include <utility>

#define USB_VID_LEA6T 0x1546
#define USB_PID_LEA6T 0x01A6
#define USB_IF_LEA6T       1
#define USB_EP_OUT         0x01
#define USB_EP_IN          0x82
#define USB_MAX_PACKET    1024

struct usb_serial {
    libusb_context *context;
    libusb_device_handle *dev_handle;
    struct libusb_transfer *transfer_out;
    struct libusb_transfer *transfer_in;
    uint8_t rx_buffer[USB_MAX_PACKET];
    int rx_count;
    std::queue< std::pair<uint8_t *, int> > pending_tx;
    int tx_ready;
};

static struct usb_serial serial;
static int connect_usb(void);
static void disconnect_usb(void);
static int get_fds_usb(struct pollfd **fds);
static int process_events_usb(void);
static int send_data(uint8_t *buf, int size);
static int receive_data(int count);
static void on_transfer_in(struct libusb_transfer *transfer);
static void on_transfer_out(struct libusb_transfer *transfer);

extern "C" int parse_ublox_message(uint8_t *data, int length);

struct device device_usb = {
    .open = connect_usb,
    .close = disconnect_usb,
    .get_pollfd = get_fds_usb,
    .handle_event = process_events_usb,
    .write = send_data
};

static int connect_usb(void)
{
    memset(&serial, 0, sizeof(serial));
    if (LIBUSB_SUCCESS != libusb_init(&(serial.context))) {
        return -1;
    }
    serial.dev_handle = libusb_open_device_with_vid_pid(serial.context, USB_VID_LEA6T, USB_PID_LEA6T);
    if (serial.dev_handle) {
        printf("LEA-6T Module connected successfully\n");
        if (LIBUSB_SUCCESS == libusb_set_auto_detach_kernel_driver(serial.dev_handle, 1)) {
            printf("kernel driver auto-detach enabled\n");
        }
        if (LIBUSB_SUCCESS == libusb_claim_interface(serial.dev_handle, USB_IF_LEA6T)) {
            printf("interface claimed successfully\n");
            serial.transfer_out = libusb_alloc_transfer(0);
            serial.transfer_in = libusb_alloc_transfer(0);
            if (!serial.transfer_out || !serial.transfer_in) {
                goto error;
            }
            serial.rx_count = 0;
            serial.tx_ready = 1;
            return receive_data(USB_MAX_PACKET);
        }
        else {
            printf("failed to claim interface\n");
            goto error;
        }
    }
    else {
        printf("LEA-6T Module not detected\n");
        goto error;
    }
    return 0;

error:
    disconnect_usb();
    return -1;
}

static void disconnect_usb(void)
{
    if (serial.transfer_out) {
        libusb_free_transfer(serial.transfer_out);
        serial.transfer_out = nullptr;
    }
    if (serial.transfer_in) {
        libusb_free_transfer(serial.transfer_in);
        serial.transfer_in = nullptr;
    }
    if (serial.dev_handle) {
        libusb_release_interface(serial.dev_handle, USB_IF_LEA6T);
        libusb_close(serial.dev_handle);
        serial.dev_handle = nullptr;
    }
    if (serial.context) {
        libusb_exit(serial.context);
        serial.context = nullptr;
    }
}

static int receive_data(int count)
{
    libusb_fill_bulk_transfer(serial.transfer_in, serial.dev_handle, USB_EP_IN,
        serial.rx_buffer + USB_MAX_PACKET - count, count, on_transfer_in, NULL, 0);
    return libusb_submit_transfer(serial.transfer_in);
}

static int send_data(uint8_t *buffer, int len)
{
    uint8_t *copy = (uint8_t *)malloc(len);
    if (copy) {
        memcpy(copy, buffer, len);
        if (serial.tx_ready) {
            libusb_fill_bulk_transfer(serial.transfer_out, serial.dev_handle, USB_EP_OUT,
                copy, len, on_transfer_out, NULL, 0);
            libusb_submit_transfer(serial.transfer_out);
            serial.tx_ready = 0;
        }
        else {
            serial.pending_tx.push(std::make_pair(copy, len));
        }
        return 0;
    }
    else {
        return -1;
    }
}

static int get_fds_usb(struct pollfd **fds)
{
    int result = -1;
    const struct libusb_pollfd **list = libusb_get_pollfds(serial.context);
    if (list) {
        int i = 0;
        int num_fds = 0;
        while (list[i] != nullptr) {
            num_fds++;
            i++;
        }
        if (num_fds > 0) {
            *fds = (struct pollfd *)calloc(num_fds, sizeof(**fds));
            for (i = 0; i < num_fds; i++) {
                (*fds)[i].fd = list[i]->fd;
                (*fds)[i].events = list[i]->events;
            }
            result = num_fds;
        }
        libusb_free_pollfds(list);
    }
    return result;
}

static int process_events_usb(void)
{
    struct timeval timeout = {0, 0};
    return libusb_handle_events_timeout(serial.context, &timeout);
}

static void on_transfer_in(struct libusb_transfer *transfer)
{
    if ((LIBUSB_TRANSFER_COMPLETED == transfer->status)
        || (LIBUSB_TRANSFER_OVERFLOW == transfer->status)) {
        int consumed = parse_ublox_message(serial.rx_buffer, serial.rx_count + transfer->actual_length);
        memmove(serial.rx_buffer, serial.rx_buffer + consumed, consumed);
        serial.rx_count += transfer->actual_length - consumed;
        if (USB_MAX_PACKET > serial.rx_count) {
            receive_data(USB_MAX_PACKET - serial.rx_count);
        }
        else {
            serial.rx_count = 0;
            receive_data(USB_MAX_PACKET);
        }
    }
    else {
        serial.rx_count = 0;
        receive_data(USB_MAX_PACKET);
    }
}

static void on_transfer_out(struct libusb_transfer *transfer)
{
    free(transfer->buffer);
    if (!serial.pending_tx.empty()) {
        std::pair<uint8_t *, int> item = serial.pending_tx.front();
        libusb_fill_bulk_transfer(serial.transfer_out, serial.dev_handle, USB_EP_OUT,
            item.first, item.second, on_transfer_out, NULL, 0);
        libusb_submit_transfer(serial.transfer_out);
        serial.pending_tx.pop();
    }
    else {
        serial.tx_ready = 1;
    }
    if (LIBUSB_TRANSFER_COMPLETED == transfer->status) {
        printf("bulk transmission completed: %d bytes\n", transfer->actual_length);
    }
}

