int DEBUG_LEVEL = 0;

TEST(ActiveMsgBody, twoStepsBlocking)
{
    const int my_rank = comm_rank();
    const int total_ranks = comm_size();
    const int MSG_COUNT = 64;
    Communicator comm(MPI_COMM_WORLD, DEBUG_LEVEL);
    vector<vector<int>> buffer(total_ranks, vector<int>(MSG_COUNT, 0));
    vector<bool> msg_received(total_ranks, false);
    vector<bool> msg_done(total_ranks, false);
    msg_received[my_rank] = true;
    msg_done[my_rank] = true;

    for(int idx = 0; idx < MSG_COUNT; idx++) 
        buffer[my_rank][idx] = my_rank * MSG_COUNT + idx;

    auto handler = comm.make_large_active_msg(
        [&](int& src, int& target){
            EXPECT_EQ(target, my_rank);
            EXPECT_FALSE(msg_received[src]);
            msg_received[src] = true;
        },
        [&](int& src, int& target){
            EXPECT_EQ(target, my_rank);
            char* mem = (char*)(buffer[src].data());
            return mem;
        },
        [&](int& src, int& target){
            EXPECT_EQ(src, my_rank);
            EXPECT_FALSE(msg_done[target]);
            msg_done[target] = true;
        });

    for(int sender = 0; sender < total_ranks; sender++) {
        if(my_rank == sender) {
            for(int receiver = 0; receiver < total_ranks; receiver++) {
                if(receiver != sender) {
                    int source = my_rank;
                    auto view_data = view<int>(buffer[my_rank].data(), buffer[my_rank].size());
                    handler->blocking_send_large(receiver, view_data, source, receiver);
                }
            }
        } else {
            comm.recv_process();
        }
    }

    for(int receiver = 0; receiver < total_ranks; receiver++) {
        if(receiver != my_rank) {
            EXPECT_TRUE(msg_received[receiver]);
            EXPECT_TRUE(msg_done[receiver]) << "Completion flag false at index " << receiver << " for rank " << my_rank;
            for(int idx = 0; idx < MSG_COUNT; idx++) {
                EXPECT_EQ(buffer[receiver][idx], receiver * MSG_COUNT + idx);
            }
        }
    }
    EXPECT_EQ(comm.get_n_msg_processed(), total_ranks - 1);
    EXPECT_EQ(comm.get_n_msg_queued(), total_ranks - 1);
    MPI_Barrier(MPI_COMM_WORLD);
}

TEST(ActiveMsgBody, twoStepsMixedNonBlocking)
{
    const int my_rank = comm_rank();
    const int total_ranks = comm_size();
    const int MSG_COUNT = 64;
    Communicator comm(MPI_COMM_WORLD, DEBUG_LEVEL);
    vector<vector<int>> buffer(total_ranks, vector<int>(MSG_COUNT, 0));
    vector<int> receive_count(total_ranks, 0);
    vector<int> completion_count(total_ranks, 0);
    const int expected_total = 3 * total_ranks;
    int processed = 0;

    for(int idx = 0; idx < MSG_COUNT; idx++) 
        buffer[my_rank][idx] = my_rank * MSG_COUNT + idx;

    auto handler0 = comm.make_active_msg(
        [&](int& src, int& dest){
            EXPECT_EQ(dest, my_rank);
            receive_count[src]++;
            processed++;
        });

    auto handler1 = comm.make_large_active_msg(
        [&](int& src, int& dest){
            EXPECT_EQ(dest, my_rank);
            receive_count[src]++;
            processed++;
        },
        [&](int& src, int& dest){
            EXPECT_EQ(dest, my_rank);
            char* mem = (char*)(buffer[src].data());
            return mem;
        },
        [&](int& src, int& dest) {
            EXPECT_EQ(src, my_rank);
            EXPECT_EQ(completion_count[dest], 0);
            completion_count[dest]++;
        });

    auto handler2 = comm.make_active_msg(
        [&](int& src, int& dest){
            EXPECT_EQ(dest, my_rank);
            receive_count[src]++;
            processed++;
        });

    for(int dest = 0; dest < total_ranks; dest++) {
        int source = my_rank;
        auto view_data = view<int>(buffer[source].data(), buffer[source].size());
        handler0->send(dest, source, dest);
        handler1->send_large(dest, view_data, source, dest);
        handler2->send(dest, source, dest);
    }

    while ( (!comm.is_done()) || (processed != expected_total) ) {
        comm.progress();
    }

    for(int r = 0; r < total_ranks; r++) {
        EXPECT_EQ(completion_count[r], 1);
        EXPECT_EQ(receive_count[r], 3);
        for(int idx = 0; idx < MSG_COUNT; idx++) {
            EXPECT_EQ(buffer[r][idx], r * MSG_COUNT + idx);
        }
    }
    EXPECT_EQ(comm.get_n_msg_processed(), 3 * total_ranks);
    EXPECT_EQ(comm.get_n_msg_queued(), 3 * total_ranks);
    MPI_Barrier(MPI_COMM_WORLD);
}

TEST(ActiveMsgBody, multipleBodiesBreakSize)
{
    vector<double> factors = {0.001, 0.1, 0.9, 1.1, 1.5, 4.0, 8.0}; 
    const size_t threshold = (1 << 22); 
    for(auto h_factor: factors) {
        for(auto b_factor: factors) {
            if(DEBUG_LEVEL) printf("Factor = %e, %e=======================\n", h_factor, b_factor);
            Communicator comm(MPI_COMM_WORLD, DEBUG_LEVEL, threshold);
            int finished = 0;
            int headers_rcvd = 0;
            int expected = 1;
            int completed = 0;
            size_t header_bytes = threshold * h_factor;
            size_t body_bytes = threshold * b_factor;
            char* header_mem = (char*)calloc(header_bytes, sizeof(char));
            char* send_mem = (char*)calloc(body_bytes, sizeof(char));
            char* recv_mem = (char*)calloc(body_bytes, sizeof(char));
            send_mem[0] = 'l';
            send_mem[body_bytes-1] = 'd';
            header_mem[0] = 'l';
            header_mem[header_bytes-1] = 'd';

            auto handler = comm.make_large_active_msg(
                [&](view<char>& header) {
                    EXPECT_EQ(finished, 0);
                    EXPECT_EQ(headers_rcvd, 1);
                    EXPECT_EQ(header.size(), header_bytes);
                    EXPECT_EQ(header.data()[0], 'l');
                    EXPECT_EQ(header.data()[header_bytes-1], 'd');
                    EXPECT_EQ(recv_mem[0],'l');
                    EXPECT_EQ(recv_mem[body_bytes-1],'d');
                    finished++;
                },
                [&](view<char>& header) {
                    EXPECT_EQ(header.size(), header_bytes);
                    EXPECT_EQ(header.data()[0], 'l');
                    EXPECT_EQ(header.data()[header_bytes-1], 'd');
                    EXPECT_EQ(finished, 0);
                    EXPECT_EQ(headers_rcvd, 0);
                    headers_rcvd++;
                    return recv_mem;
                },
                [&](view<char>&){
                    completed++;
                });

            auto body_view = view<char>(send_mem, body_bytes);
            auto header_view = view<char>(header_mem, header_bytes);
            int dest = (comm_rank() + 1) % (comm_size());
            handler->send_large(dest, body_view, header_view);

            while ( (!comm.is_done()) || (finished != expected) ) {
                comm.progress();
            }

            EXPECT_EQ(finished, expected);
            EXPECT_EQ(headers_rcvd, expected);
            EXPECT_EQ(completed, 1);
            MPI_Barrier(MPI_COMM_WORLD);
            free(send_mem);
            free(recv_mem);
            free(header_mem);
        }
    }
}

void test_message_sizes(vector<size_t> sizes, size_t threshold) {
    Communicator comm(MPI_COMM_WORLD, DEBUG_LEVEL, threshold);
    int N = sizes.size();
    vector<unsigned char*> send_buffers(N * N);
    vector<unsigned char*> recv_buffers(N * N);
    vector<unsigned char*> header_buffers(N * N);
    int headers_received = 0;
    int bodies_received = 0;
    const int expected_total = N * N;
    int completed = 0;

    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            int idx = i + j * N;
            size_t header_bytes = sizes[i];
            size_t body_bytes = sizes[j];
            header_buffers.at(idx) = (unsigned char*)malloc(header_bytes);
            *(header_buffers.at(idx)) = (unsigned char)(- idx);
            *(header_buffers.at(idx)+header_bytes-1) = (unsigned char)(- idx);
            send_buffers.at(idx) = (unsigned char*)malloc(body_bytes);
            *(send_buffers.at(idx)) = (unsigned char)idx;
            *(send_buffers.at(idx)+body_bytes-1) = (unsigned char)idx;
            recv_buffers.at(idx) = (unsigned char*)malloc(body_bytes);
            *(recv_buffers.at(idx)) = (unsigned char)0;
            *(recv_buffers.at(idx)+body_bytes-1) = (unsigned char)0;
        }
    }

    auto handler = comm.make_large_active_msg(
        [&](int& i, int& j, view<unsigned char>& header) {
            int idx = i + j * N;
            size_t header_bytes = sizes.at(i);
            EXPECT_EQ(header.size(), header_bytes);
            EXPECT_EQ(*(header.begin()), (unsigned char)(- idx));
            EXPECT_EQ(*(header.end()-1), (unsigned char)(- idx));
            size_t body_bytes = sizes.at(j);
            EXPECT_EQ(*(recv_buffers[idx]), (unsigned char)idx); 
            EXPECT_EQ(*(recv_buffers[idx] + body_bytes - 1), (unsigned char)idx);
            bodies_received++;
        },
        [&](int& i, int& j, view<unsigned char>& header) {
            int idx = i + j * N;
            size_t header_bytes = sizes.at(i);
            EXPECT_EQ(header.size(), header_bytes);
            EXPECT_EQ(*(header.begin()), (unsigned char)(- idx));
            EXPECT_EQ(*(header.end()-1), (unsigned char)(- idx));
            size_t body_bytes = sizes.at(j);
            EXPECT_EQ(*(recv_buffers[idx]), (unsigned char)0); 
            EXPECT_EQ(*(recv_buffers[idx] + body_bytes - 1), (unsigned char)0);
            unsigned char* ptr = recv_buffers.at(idx);
            headers_received++;
            return ptr;
        },
        [&](int&, int&, view<unsigned char>&) {
            completed++;
        });

    int dest = (comm_rank() + 1) % (comm_size());
    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            int idx = i + j * N;
            size_t header_bytes = sizes.at(i);
            size_t body_bytes = sizes.at(j);
            auto body   = view<unsigned char>(send_buffers.at(idx), body_bytes);
            auto header = view<unsigned char>(header_buffers.at(idx), header_bytes);
            handler->send_large(dest, body, i, j, header);
        }
    }

    while ( (!comm.is_done()) || (bodies_received != expected_total) ) {
        comm.progress();
    }

    EXPECT_EQ(bodies_received, expected_total);
    EXPECT_EQ(headers_received, expected_total);
    EXPECT_EQ(completed, N*N);

    for(int i = 0; i < N; i++) {
        for(int j = 0; j < N; j++) {
            int idx = i + j * N;
            size_t body_bytes = sizes.at(j);
            EXPECT_EQ(*(recv_buffers.at(idx)), (unsigned char)idx);
            EXPECT_EQ(*(recv_buffers.at(idx) + body_bytes - 1), (unsigned char)idx);
        }
    }
    MPI_Barrier(MPI_COMM_WORLD);

    for(auto v: send_buffers) free(v);
    for(auto v: recv_buffers) free(v);
    for(auto v: header_buffers) free(v);
}

TEST(BigToSmall, large)
{
    const size_t threshold = (1 << 21); 

    vector<size_t> sizes_0 = {32*threshold,    16*threshold,  8*threshold, 
                              4*threshold,     2*threshold,   threshold, 
                              threshold/2,     threshold/4,   threshold/8, 
                              threshold/16,    threshold/32,  threshold/64, 
                              threshold/128,   threshold/256, threshold/512};

    vector<size_t> sizes_1 = {128*threshold, 1*threshold, threshold/16, threshold/1024};

    vector<size_t> sizes_2 = {4*threshold, 4*threshold, 4*threshold, 4*threshold, 4*threshold,
                              2*threshold, 2*threshold, 2*threshold, 2*threshold, 2*threshold,
                              1*threshold, 1*threshold, 1*threshold, 1*threshold, 1*threshold,
                              threshold/2, threshold/2, threshold/2, threshold/2, threshold/2, 
                              threshold/4, threshold/4, threshold/4, threshold/4, threshold/4};

    vector<vector<size_t>> all_sizes = {sizes_0, sizes_1, sizes_2};
    test_message_sizes(sizes_0, threshold);
    test_message_sizes(sizes_1, threshold);
    test_message_sizes(sizes_2, threshold);
}

TEST(BigToSmall, small)
{
    const size_t threshold = (1 << 21); 

    vector<size_t> sizes_0 = {4*threshold,     2*threshold,   threshold, 
                              threshold/2,     threshold/4,   threshold/8, 
                              threshold/16,    threshold/32,  threshold/64, 
                              threshold/128,   threshold/256, threshold/512};

    vector<size_t> sizes_1 = {4*threshold, 1*threshold, threshold/16, threshold/1024};

    vector<size_t> sizes_2 = {4*threshold, 4*threshold,
                              2*threshold, 2*threshold,
                              1*threshold, 1*threshold,
                              threshold/2, threshold/2, 
                              threshold/4, threshold/4};

    test_message_sizes(sizes_0, threshold);
    test_message_sizes(sizes_1, threshold);
    test_message_sizes(sizes_2, threshold);
}

