void FConfigPropertyHelperDetails::CustomizeDetails(IDetailLayoutBuilder& LayoutBuilder)
{
	TSharedPtr<IPropertyHandle> EditPropHandle = LayoutBuilder.GetProperty("EditProperty");
	LayoutBuilder.HideProperty(EditPropHandle);

	UObject* PropValuePtr;
	EditPropHandle->GetValue(PropValuePtr);
	OriginalProperty = CastChecked<UProperty>(PropValuePtr);

	// Build a temporary UClass containing only the target property for use in the details view
	ConfigEditorPropertyViewClass = NewObject<UClass>(GetTransientPackage(), TEXT("TempConfigEditorUClass"), RF_Public|RF_Standalone);

	// Duplicate and attach the property to the new class
	ConfigEditorCopyOfEditProperty = DuplicateObject<UProperty>(OriginalProperty, ConfigEditorPropertyViewClass, *(PropValuePtr->GetName()));

	// Configure the class metadata
	ConfigEditorPropertyViewClass->ClassConfigName = OriginalProperty->GetOwnerClass()->ClassConfigName;
	ConfigEditorPropertyViewClass->SetSuperStruct(UObject::StaticClass());
	ConfigEditorPropertyViewClass->ClassFlags |= (CLASS_DefaultConfig | CLASS_Config);
	ConfigEditorPropertyViewClass->AddCppProperty(ConfigEditorCopyOfEditProperty);
	ConfigEditorPropertyViewClass->Bind();
	ConfigEditorPropertyViewClass->StaticLink(true);
	ConfigEditorPropertyViewClass->AddToRoot();

	// Initialize CDO and root it
	ConfigEditorPropertyViewCDO = ConfigEditorPropertyViewClass->GetDefaultObject(true);
	ConfigEditorPropertyViewCDO->AddToRoot();

	// Retrieve config file list
	ConfigFilesHandle = LayoutBuilder.GetProperty("ConfigFilePropertyObjects");
	LayoutBuilder.HideProperty(ConfigFilesHandle);

	// Add custom UI row for config hierarchy
	IDetailCategoryBuilder& HierarchyCategory = LayoutBuilder.EditCategory("ConfigHierarchy");
	HierarchyCategory.AddCustomRow(LOCTEXT("ConfigHierarchy", "ConfigHierarchy"))
	[
		ConstructPropertyTable(LayoutBuilder)
	];

	// Subscribe to property change notifications
	FCoreUObjectDelegates::OnObjectPropertyChanged.AddSP(this, &FConfigPropertyHelperDetails::OnPropertyValueChanged);
}

void FConfigPropertyHelperDetails::OnPropertyValueChanged(UObject* ModifiedObject, FPropertyChangedEvent& ChangeEvent)
{
	UClass* OwnerClass = ConfigEditorCopyOfEditProperty->GetOwnerClass();
	if (ModifiedObject && ModifiedObject->IsA(OwnerClass))
	{
		const FString* SourceFile = ConfigFileAndPropertySourcePairings.FindKey(ModifiedObject);
		if (SourceFile != nullptr)
		{
			const FString& IniFileName = *SourceFile;

			// Create isolated config cache
			FConfigCacheIni SandboxConfig(EConfigCacheType::Temporary);

			// Insert empty file to prevent loading original data
			FConfigFile& SandboxFile = SandboxConfig.Add(IniFileName, FConfigFile());

			// Export current default object state to sandbox
			OriginalProperty->GetOwnerClass()->GetDefaultObject()->SaveConfig(CPF_Config, *IniFileName, &SandboxConfig);

			// Validate single-file output
			ensureMsgf(SandboxConfig.Num() == 1, TEXT("UObject::UpdateDefaultConfig() unexpectedly modified multiple files!"));

			TArray<FString> SectionKeys;
			SandboxFile.GetKeys(SectionKeys);
			checkf(SectionKeys.Num() > 0, TEXT("No section found after saving config."));

			const FString& TargetSection = SectionKeys[0];
			const FString& TargetPropName = ConfigEditorCopyOfEditProperty->GetName();

			FString PropertyValueStr;
			ConfigEditorCopyOfEditProperty->ExportText_InContainer(nullptr, PropertyValueStr, ModifiedObject, ModifiedObject, ModifiedObject, 0);
			SandboxFile.SetString(*TargetSection, *TargetPropName, *PropertyValueStr);

			// Apply changes via global config
			GConfig->SetString(*TargetSection, *TargetPropName, *PropertyValueStr, IniFileName);
			SandboxFile.UpdateSinglePropertyInSection(*IniFileName, *TargetPropName, *TargetSection);

			// Reload global config and refresh CDO
			FString FinalConfigPath;
			GConfig->LoadGlobalIniFile(FinalConfigPath, *OriginalProperty->GetOwnerClass()->ClassConfigName.ToString(), nullptr, true);
			OriginalProperty->GetOwnerClass()->GetDefaultObject()->ReloadConfig();
		}
	}
}

void FConfigPropertyHelperDetails::AddEditablePropertyForConfig(IDetailLayoutBuilder& LayoutBuilder, const UPropertyConfigFileDisplayRow* RowData)
{
	AssociatedConfigFileAndObjectPairings.Add(RowData->ConfigFileName, (UObject*)RowData);

	IDetailCategoryBuilder& TempCategory = LayoutBuilder.EditCategory("TempCategory");

	UObject* InstanceObj = StaticDuplicateObject(ConfigEditorPropertyViewCDO, GetTransientPackage(), *(RowData->ConfigFileName + TEXT("_cdoDupe")));
	InstanceObj->AddToRoot();

	FString CurrentValue;
	static const FString SectionPath = OriginalProperty->GetOwnerClass()->GetPathName();
	static const FString PropertyName = ConfigEditorCopyOfEditProperty->GetName();

	if (GConfig->GetString(*SectionPath, *PropertyName, CurrentValue, RowData->ConfigFileName))
	{
		ConfigEditorCopyOfEditProperty->ImportText(*CurrentValue, ConfigEditorCopyOfEditProperty->ContainerPtrToValuePtr<uint8>(InstanceObj), 0, nullptr);
	}

	ConfigFileAndPropertySourcePairings.Add(RowData->ConfigFileName, (UObject*)InstanceObj);

	TArray<UObject*> DisplayList;
	DisplayList.Add(InstanceObj);

	if (IDetailPropertyRow* Row = TempCategory.AddExternalProperty(DisplayList, ConfigEditorCopyOfEditProperty->GetFName()))
	{
		TSharedPtr<SWidget> NameWidget, ValueWidget;
		Row->GetDefaultWidgets(NameWidget, ValueWidget);

		IConfigEditorModule& ConfigEditor = FModuleManager::Get().LoadModuleChecked<IConfigEditorModule>("ConfigEditor");
		ConfigEditor.AddExternalPropertyValueWidgetAndConfigPairing(RowData->ConfigFileName, ValueWidget);

		Row->Visibility(EVisibility::Hidden);
	}
}

TSharedRef<SWidget> FConfigPropertyHelperDetails::ConstructPropertyTable(IDetailLayoutBuilder& LayoutBuilder)
{
	FPropertyEditorModule& EditorMod = FModuleManager::LoadModuleChecked<FPropertyEditorModule>("PropertyEditor");
	PropertyTable = EditorMod.CreatePropertyTable();
	PropertyTable->SetSelectionMode(ESelectionMode::None);
	PropertyTable->SetSelectionUnit(EPropertyTableSelectionUnit::None);
	PropertyTable->SetIsUserAllowedToChangeRoot(false);
	PropertyTable->SetShowObjectName(false);

	RepopulatePropertyTable(LayoutBuilder);

	TArray<TSharedRef<class IPropertyTableCustomColumn>> CustomCols;
	TSharedRef<FConfigPropertyCustomColumn> MainCol = MakeShareable(new FConfigPropertyCustomColumn());
	MainCol->EditProperty = ConfigEditorCopyOfEditProperty;
	CustomCols.Add(MainCol);

	return EditorMod.CreatePropertyTableWidget(PropertyTable.ToSharedRef(), CustomCols);
}

void FConfigPropertyHelperDetails::RepopulatePropertyTable(IDetailLayoutBuilder& LayoutBuilder)
{
	AssociatedConfigFileAndObjectPairings.Empty();

	TSharedPtr<IPropertyHandleArray> FileArrayHandle = ConfigFilesHandle->AsArray();
	uint32 NumFiles = 0;
	FileArrayHandle->GetNumElements(NumFiles);

	for (uint32 Idx = 0; Idx < NumFiles; ++Idx)
	{
		FString ConfigName;
		TSharedRef<IPropertyHandle> ElementHandle = FileArrayHandle->GetElement(Idx);
		UObject* HelperObj = nullptr;
		ensure(ElementHandle->GetValue(HelperObj) == FPropertyAccess::Success);
		UPropertyConfigFileDisplayRow* Row = CastChecked<UPropertyConfigFileDisplayRow>(HelperObj);
		AddEditablePropertyForConfig(LayoutBuilder, Row);
	}

	TArray<UObject*> DisplayObjects;
	AssociatedConfigFileAndObjectPairings.GenerateValueArray(DisplayObjects);
	PropertyTable->SetObjects(DisplayObjects);

	for (UProperty* Prop = UPropertyConfigFileDisplayRow::StaticClass()->PropertyLink; Prop; Prop = Prop->PropertyLinkNext)
	{
		PropertyTable->AddColumn((TWeakObjectPtr<UProperty>)Prop);
	}

	TArray<TSharedRef<IPropertyTableColumn>> Columns = PropertyTable->GetColumns();
	for (TSharedRef<IPropertyTableColumn> Col : Columns)
	{
		Col->SetFrozen(true);
	}

	PropertyTable->RequestRefresh();
}

