using namespace routing;

struct WeightedEdge
{
  WeightedEdge(unsigned target, double weight) : targetVertex(target), weightValue(weight) {}
  unsigned GetTarget() const { return targetVertex; }
  double GetWeight() const { return weightValue; }
  unsigned targetVertex;
  double weightValue;
};

class BidirectionalGraph
{
public:
  using TVertexType = unsigned;
  using TEdgeType = WeightedEdge;

  void AddConnection(unsigned u, unsigned v, double w)
  {
    adjacencyList[u].push_back(WeightedEdge(v, w));
    adjacencyList[v].push_back(WeightedEdge(u, w));
  }

  void GetAdjacencyList(unsigned vertex, vector<WeightedEdge> & adj) const
  {
    adj.clear();
    auto const it = adjacencyList.find(vertex);
    if (it != adjacencyList.end())
      adj = it->second;
  }

  void GetIngoingEdgesList(unsigned vertex, vector<WeightedEdge> & adj) const
  {
    GetAdjacencyList(vertex, adj);
  }

  void GetOutgoingEdgesList(unsigned vertex, vector<WeightedEdge> & adj) const
  {
    GetAdjacencyList(vertex, adj);
  }

  double HeuristicCostEstimate(unsigned from, unsigned to) const { return 0.0; }

private:
  map<unsigned, vector<WeightedEdge>> adjacencyList;
};

void RunAStarTest(BidirectionalGraph const & graph, vector<unsigned> const & expectedPath, double const & expectedTotalWeight)
{
  using TAlgorithm = AStarAlgorithm<BidirectionalGraph>;
  TAlgorithm solver;
  RoutingResult<unsigned> result;

  TEST_EQUAL(TAlgorithm::Result::OK, solver.FindPath(graph, 0u, 4u, result), ());
  TEST_EQUAL(expectedPath, result.path, ());
  TEST_ALMOST_EQUAL_ULPS(expectedTotalWeight, result.distance, ());

  result.path.clear();
  TEST_EQUAL(TAlgorithm::Result::OK, solver.FindPathBidirectional(graph, 0u, 4u, result), ());
  TEST_EQUAL(expectedPath, result.path, ());
  TEST_ALMOST_EQUAL_ULPS(expectedTotalWeight, result.distance, ());
}

UNIT_TEST(AStarAlgorithm_Sample)
{
  BidirectionalGraph graph;
  // Adds edges in format: <source, target, weight>.
  graph.AddConnection(0, 1, 10.0);
  graph.AddConnection(1, 2, 5.0);
  graph.AddConnection(2, 3, 5.0);
  graph.AddConnection(2, 4, 10.0);
  graph.AddConnection(3, 4, 3.0);

  vector<unsigned> const expectedRoute = {0, 1, 2, 3, 4};
  RunAStarTest(graph, expectedRoute, 23.0);
}
