// Convert remote path separators from backslash to forward slash
String remotePath(TCchar* path) {
    String buffer = path;
    int    len = buffer.length();
    int    index;
    for (index = 0; index < len; index++) if (buffer[index] == _T('\\')) buffer[index] = _T('/');
    return buffer;
}

// Convert local path separators from forward slash to backslash  
String localPath(TCchar* path) {
    String buffer = path;
    int    len = buffer.length();
    int    index;
    for (index = 0; index < len; index++) if (buffer[index] == _T('/')) buffer[index] = _T('\\');
    return buffer;
}

// Extract filename from a given path
String parseName(TCchar* path) {
    String buffer = path;
    int    pos = buffer.findLastOf(_T('\\'));   if (pos < 0) return buffer;
    return buffer.substr(pos + 1);
}

// Ensure root path ends with a backslash
void fixRootPath(String& root) {if (root[root.length() - 1] != _T('\\')) root += _T('\\');}

