// Extracts the local bind pose for a specific joint from the skeleton.
ozz::math::Transform RetrieveJointLocalBindPose(const Skeleton& skeleton,
                                                int joint_index) {
  assert(joint_index >= 0 && joint_index < skeleton.num_joints() &&
         "Joint index out of valid range.");

  const ozz::math::SoaTransform& soa_data =
      skeleton.bind_pose()[joint_index / 4];

  // Convert SoA (Structure of Arrays) to AoS (Array of Structures).
  ozz::math::SimdFloat4 translation_components[4];
  ozz::math::Transpose3x4(&soa_data.translation.x, translation_components);

  ozz::math::SimdFloat4 rotation_components[4];
  ozz::math::Transpose4x4(&soa_data.rotation.x, rotation_components);

  ozz::math::SimdFloat4 scale_components[4];
  ozz::math::Transpose3x4(&soa_data.scale.x, scale_components);

  // Populate the Transform structure.
  math::Transform local_bind;
  const int component_index = joint_index % 4;

  ozz::math::Store3PtrU(translation_components[component_index], &local_bind.translation.x);
  ozz::math::StorePtrU(rotation_components[component_index], &local_bind.rotation.x);
  ozz::math::Store3PtrU(scale_components[component_index], &local_bind.scale.x);

  return local_bind;
}

// Macro to check whether a joint has a sibling at the next position.
#define _CHECK_SIBLING(_idx, _total_joints, _joint_props) \
  ((_idx + 1 < _total_joints) &&                          \
   (_joint_props[_idx].parent == _joint_props[_idx + 1].parent))

// Performs depth-first traversal over joint hierarchy using an explicit stack.
void TraverseJointsDF(const Skeleton& skeleton, int start_joint,
                      JointsIterator* iterator) {
  assert(iterator);
  const int total_joints = skeleton.num_joints();
  Range<const Skeleton::JointProperties> joint_properties =
      skeleton.joint_properties();

  // Reset iterator state.
  iterator->num_joints = 0;

  // Early exit if skeleton is empty or invalid start point.
  if (total_joints == 0) {
    return;
  }
  if ((start_joint < 0 || start_joint >= total_joints) && 
      start_joint != Skeleton::kNoParentIndex) {
    return;
  }

  // Stack frame representation for iterative DFS.
  struct StackFrame {
    uint16_t joint_id : 15;
    uint16_t has_sibling : 1;
  };

  StackFrame traversal_stack[Skeleton::kMaxJoints];
  int stack_depth = 0;

  // Setup initial context.
  StackFrame initial_frame;
  if (start_joint != Skeleton::kNoParentIndex) {
    initial_frame.joint_id = start_joint;
    initial_frame.has_sibling = false;  // No siblings allowed for specified root.
  } else {
    initial_frame.joint_id = 0;
    initial_frame.has_sibling = _CHECK_SIBLING(0, total_joints, joint_properties.begin);
  }

  traversal_stack[stack_depth++] = initial_frame;

  while (stack_depth != 0) {
    const StackFrame& current = traversal_stack[stack_depth - 1];

    // Add current joint to output list.
    iterator->joints[iterator->num_joints++] = current.joint_id;

    // If current joint is not a leaf, find and push its first child.
    if (!joint_properties.begin[current.joint_id].is_leaf) {
      uint16_t candidate_child = current.joint_id + 1;

      // Find the first child by matching parent index.
      for (; candidate_child < total_joints &&
             current.joint_id != joint_properties.begin[candidate_child].parent;
           ++candidate_child) {
        // Continue scanning...
      }

      if (candidate_child < total_joints) {
        StackFrame& child_frame = traversal_stack[stack_depth++];
        child_frame.joint_id = candidate_child;
        child_frame.has_sibling = _CHECK_SIBLING(candidate_child, total_joints, joint_properties.begin);
        continue;  // Process child next.
      }
    }

    // Backtrack while no siblings remain.
    for (; stack_depth != 0 && !traversal_stack[stack_depth - 1].has_sibling;
         --stack_depth) {
      // Pop frames until a node with unvisited siblings is found.
    }

    // Promote sibling if available.
    if (stack_depth != 0) {
      StackFrame& sibling_frame = traversal_stack[stack_depth - 1];
      assert(sibling_frame.has_sibling && sibling_frame.joint_id + 1 < total_joints);

      sibling_frame.joint_id++;  // Next sibling in BFS order.
      sibling_frame.has_sibling = _CHECK_SIBLING(sibling_frame.joint_id, total_joints, joint_properties.begin);
    }
  }
}

#undef _CHECK_SIBLING

