#include "Transforms/MultiTransformer.h"

void UMultiTransformer::Setup(UInteractiveGizmoManager* GizmoManagerIn, IToolContextTransactionProvider* TransactionProviderIn)
{
	GizmoManager = GizmoManagerIn;
	TransactionProvider = TransactionProviderIn;
	CurrentFrame = FFrame3d();
	CurrentScale = FVector3d::One();
	CurrentMode = EMultiTransformerMode::DefaultGizmo;

	// Initialize proxy object for transformation handling
	ProxyObject = NewObject<UTransformProxy>(this);
	ProxyObject->SetTransform(CurrentFrame.ToFTransform());
	UpdateGizmoVisibility(true);

	// Register callbacks for proxy transformation events
	ProxyObject->OnTransformChanged.AddUObject(this, &UMultiTransformer::OnProxyTransformUpdated);
	ProxyObject->OnBeginTransformEdit.AddUObject(this, &UMultiTransformer::OnStartProxyTransform);
	ProxyObject->OnEndTransformEdit.AddUObject(this, &UMultiTransformer::OnFinishProxyTransform);
}

void UMultiTransformer::Shutdown()
{
	GizmoManager->DestroyAllGizmosByOwner(this);
}

void UMultiTransformer::SetOverrideGizmoCoordinateSystem(EToolContextCoordinateSystem CoordSystem)
{
	if (GizmoCoordSystem != CoordSystem || !bForceGizmoCoordSystem)
	{
		bForceGizmoCoordSystem = true;
		GizmoCoordSystem = CoordSystem;
		if (MainGizmo != nullptr)
		{
			UpdateGizmoVisibility(false);
			UpdateGizmoVisibility(true);
		}
	}
}

void UMultiTransformer::SetEnabledGizmoSubElements(ETransformGizmoSubElements EnabledSubElements)
{
	if (ActiveSubElements != EnabledSubElements)
	{
		ActiveSubElements = EnabledSubElements;
		if (MainGizmo != nullptr)
		{
			UpdateGizmoVisibility(false);
			UpdateGizmoVisibility(true);
		}
	}
}

void UMultiTransformer::SetMode(EMultiTransformerMode NewMode)
{
	if (NewMode != CurrentMode)
	{
		if (NewMode == EMultiTransformerMode::DefaultGizmo)
		{
			UpdateGizmoVisibility(true);
		}
		else
		{
			UpdateGizmoVisibility(false);
		}
		CurrentMode = NewMode;
	}
}

void UMultiTransformer::SetGizmoVisibility(bool bVisible)
{
	if (bDesiredVisibility != bVisible)
	{
		bDesiredVisibility = bVisible;
		if (MainGizmo != nullptr)
		{
			MainGizmo->SetVisibility(bVisible);
		}
	}
}

void UMultiTransformer::SetSnapToWorldGridSourceFunc(TUniqueFunction<bool()> EnableSnapFunc)
{
	SnapToGridCheckFunc = MoveTemp(EnableSnapFunc);
}

void UMultiTransformer::Tick(float DeltaTime)
{
	if (MainGizmo != nullptr)
	{
		MainGizmo->bSnapToWorldGrid =
			(SnapToGridCheckFunc) ? SnapToGridCheckFunc() : false;
	}
}

void UMultiTransformer::InitializeGizmoPositionFromWorldFrame(const FFrame3d& Frame, bool bResetScale)
{
	CurrentFrame = Frame;
	if (bResetScale)
	{
		CurrentScale = FVector3d::One();
	}
	if (MainGizmo != nullptr)
	{
		MainGizmo->ReinitializeGizmoTransform(CurrentFrame.ToFTransform());
	}
}

void UMultiTransformer::UpdateGizmoPositionFromWorldFrame(const FFrame3d& Frame, bool bResetScale)
{
	CurrentFrame = Frame;
	if (bResetScale)
	{
		CurrentScale = FVector3d::One();
	}
	if (MainGizmo != nullptr)
	{
		MainGizmo->SetNewGizmoTransform(CurrentFrame.ToFTransform());
	}
}

void UMultiTransformer::ResetScale()
{
	CurrentScale = FVector3d::One();
	if (MainGizmo != nullptr)
	{
		MainGizmo->SetNewChildScale(FVector::OneVector);
	}
}

void UMultiTransformer::OnProxyTransformUpdated(UTransformProxy* Proxy, FTransform Transform)
{
	CurrentFrame = FFrame3d(Transform);
	CurrentScale = FVector3d(Transform.GetScale3D());
	OnTransformUpdated.Broadcast();
}

void UMultiTransformer::OnStartProxyTransform(UTransformProxy* Proxy)
{
	bIsEditing = true;
	OnTransformStarted.Broadcast();
}

void UMultiTransformer::OnFinishProxyTransform(UTransformProxy* Proxy)
{
	bIsEditing = false;
	OnTransformCompleted.Broadcast();
}

void UMultiTransformer::UpdateGizmoVisibility(bool bNewVisibility)
{
	if (!bNewVisibility)
	{
		GizmoManager->DestroyAllGizmosByOwner(this);
		MainGizmo = nullptr;
	}
	else
	{
		check(MainGizmo == nullptr);
		MainGizmo = GizmoManager->CreateCustomTransformGizmo(ActiveSubElements, this);
		if (bForceGizmoCoordSystem)
		{
			MainGizmo->bUseContextCoordinateSystem = false;
			MainGizmo->CurrentCoordinateSystem = GizmoCoordSystem;
		}
		MainGizmo->SetActiveTarget(ProxyObject, TransactionProvider);
		MainGizmo->ReinitializeGizmoTransform(CurrentFrame.ToFTransform());
		MainGizmo->SetVisibility(bDesiredVisibility);
	}
}

