    m_bPassthrough = false;
    m_iBitsPerSample = 0;
    m_sampleRate = 0;
    m_bPaused = true;
    m_currentPts = DVD_NOPTS_VALUE; // silence coverity uninitialized warning, is set elsewhere
    m_ptsTimestamp = 0.0;           // silence coverity uninitialized warning, is set elsewhere
    m_errorCorrection = 0.0;
    m_errorTimestamp = 0;
}

