void CAudioRenderer::Shutdown() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (m_pAudioStream)
        CAEFactory::FreeStream(m_pAudioStream);
    m_pAudioStream = nullptr;
    m_sampleRate = 0;
    m_iBitsPerSample = 0;
    m_bPassthrough = false;
    m_bPaused = true;
    m_currentPts = DVD_NOPTS_VALUE;
}

unsigned int CAudioRenderer::EnqueueFrames(const DVDAudioFrame &frame) {
    m_bAbortRequest = false;
    std::unique_lock<std::recursive_mutex> lock(m_criticalSection);
    if (!m_pAudioStream)
        return 0;

    CAESyncInfo info = m_pAudioStream->GetSyncInfo();
    if (info.state == CAESyncInfo::SYNC_INSYNC) {
        unsigned int newTime = info.errortime;
        if (newTime != m_errorTimestamp) {
            m_errorTimestamp = info.errortime;
            m_errorCorrection = info.error / 1000 * DVD_TIME_BASE;
            m_resampleFactor = info.rr;
        }
    } else {
        m_errorTimestamp = 0;
        m_errorCorrection = 0.0;
    }

    // Compute a deadline by which processing must complete
    double deadline;
    deadline = DVD_SEC_TO_TIME(m_pAudioStream->GetDelay()) + frame.duration;
    deadline += DVD_SEC_TO_TIME(1.0);
    deadline += m_pClock->GetAbsoluteClock();

    unsigned int totalFrames = frame.nb_frames;
    unsigned int remaining = frame.nb_frames;
    unsigned int position = 0;

    do {
        double pts =
            (position == 0) ? frame.pts / DVD_TIME_BASE * 1000 : 0.0;
        unsigned int processed =
            m_pAudioStream->AddData(frame.data, position, remaining, pts);
        position += processed;
        remaining -= processed;
        if (remaining <= 0)
            break;
        if (processed == 0 && deadline < m_pClock->GetAbsoluteClock()) {
            //    CLog::Log(LOGERROR, "CAudioRenderer::EnqueueFrames -
            //    timeout adding data to renderer");
            break;
        }
        lock.unlock();
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
        lock.lock();
    } while (!m_bAbortRequest);

    m_currentPts = frame.pts + frame.duration - GetLatency();
    m_ptsTimestamp = m_pClock->GetAbsoluteClock();
    return totalFrames - remaining;
}

void CAudioRenderer::FlushPendingData() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (m_pAudioStream)
        m_pAudioStream->Drain(true);
}

