void CAudioRenderer::Suspend() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (m_pAudioStream)
        m_pAudioStream->Pause();
    // CLog::Log(LOGDEBUG,"CAudioRenderer::Suspend - pausing audio stream");
    m_currentPts = DVD_NOPTS_VALUE;
}

void CAudioRenderer::Activate() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (m_pAudioStream)
        m_pAudioStream->Resume();
    // CLog::Log(LOGDEBUG,"CAudioRenderer::Activate - resume audio stream");
}

double CAudioRenderer::GetLatency() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    double latency = 0.3;
    if (m_pAudioStream)
        latency = m_pAudioStream->GetDelay();
    return latency * DVD_TIME_BASE;
}

void CAudioRenderer::ClearBuffer() {
    m_bAbortRequest = true;
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (m_pAudioStream) {
        m_pAudioStream->Flush();
        //   CLog::Log(LOGDEBUG,"CAudioRenderer::ClearBuffer - flush audio
        //   stream");
    }
    m_currentPts = DVD_NOPTS_VALUE;
    m_errorCorrection = 0.0;
    m_errorTimestamp = 0;
}

void CAudioRenderer::SignalAbort() { m_bAbortRequest = true; }

bool CAudioRenderer::MatchesConfiguration(const DVDAudioFrame &frame) {
    if (!m_pAudioStream)
        return false;
    if (frame.passthrough != m_bPassthrough)
        return false;
    if (m_sampleRate != frame.format.m_sampleRate ||
        m_iBitsPerSample != frame.bits_per_sample ||
        m_channelLayout != frame.format.m_channelLayout)
        return false;
    return true;
}

double CAudioRenderer::GetBufferedDuration() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (!m_pAudioStream)
        return 0.0;
    double delay = 0.0;
    if (m_pAudioStream)
        delay = m_pAudioStream->GetCacheTime();
    return delay;
}

double CAudioRenderer::GetTotalCapacity() {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (!m_pAudioStream)
        return 0.0;
    return m_pAudioStream->GetCacheTotal();
}

double CAudioRenderer::GetCurrentTimestamp() {
    if (m_currentPts == DVD_NOPTS_VALUE)
        return 0.0;
    double currentTime = m_pClock->GetAbsoluteClock();
    double elapsed = currentTime - m_ptsTimestamp;
    double buffered = GetBufferedDuration();
    double consumed = 0.0;
    if (elapsed < buffered)
        consumed = elapsed;
    else
        consumed = buffered;
    m_ptsTimestamp = currentTime;
    m_currentPts += consumed;
    return m_currentPts;
}

double CAudioRenderer::GetErrorValue() { return m_errorCorrection; }

void CAudioRenderer::ApplyErrorCorrection(double adjustment) {
    m_errorCorrection += adjustment;
}

double CAudioRenderer::GetResampleFactor() { return m_resampleFactor; }

void CAudioRenderer::ConfigureResampling(int setting) {
    std::lock_guard<std::recursive_mutex> lock(m_criticalSection);
    if (m_pAudioStream) {
        m_pAudioStream->SetResampleMode(setting);
    }
}

double CAudioRenderer::GetReferenceTime() {
    if (m_pClock)
        return (m_pClock->GetClock() + m_pClock->GetVsyncAdjust()) /
            DVD_TIME_BASE * 1000;
    else
        return 0.0;
}

double CAudioRenderer::GetPlaybackSpeed() {
    if (m_pClock)
        return m_pClock->GetClockSpeed();
    else
        return 1.0;
}

