#include "QrDecoder.h"
#include "quirc/quirc.h"
#include <qdebug.h>
#include "quirc/quirc_internal.h"

QrDecoder::QrDecoder()
    : m_decoder(quirc_new())
{
}

QrDecoder::~QrDecoder()
{
    quirc_destroy(m_decoder);
}

QVector<QString> QrDecoder::process(const QImage &inputImage)
{
    QVector<QString> output;
    if (m_decoder == nullptr)
    {
        return output;
    }
    if (quirc_resize(m_decoder, inputImage.width(), inputImage.height()) < 0)
    {
        return output;
    }
    uint8_t *buffer = quirc_begin(m_decoder, nullptr, nullptr);
    if (buffer == nullptr)
    {
        return output;
    }
    std::copy(inputImage.constBits(), inputImage.constBits() + inputImage.width()*inputImage.height(), buffer);
    quirc_end(m_decoder);
    const int detectedCount = quirc_count(m_decoder);
    if (detectedCount < 0)
    {
        return output;
    }
    for (int position = 0; position < detectedCount; ++position)
    {
        quirc_code symbol;
        quirc_extract(m_decoder, position, &symbol);
        quirc_data info;
        const quirc_decode_error_t status = quirc_decode(&symbol, &info);
        if (status == QUIRC_SUCCESS)
        {
            output.append(QLatin1String((const char *)info.payload));
        }
    }
    return output;
}

