WriteBufferAggregator::WriteBufferAggregator(size_t buf_capacity)
    : buffer_capacity_(buf_capacity)
{
}

void WriteBufferAggregator::Reset()
{
    buffer_ = nullptr;
    buffer_idx_ = 0;
    use_fixed_ = true;
    file_id_ = 0;
    start_off_ = 0;
    next_off_ = 0;
    current_used_ = 0;
    pages_.clear();
    release_ptrs_.clear();
    release_indices_.clear();
}

bool WriteBufferAggregator::HasBuffer() const
{
    return buffer_ != nullptr;
}

bool WriteBufferAggregator::HasData() const
{
    return buffer_ != nullptr && current_used_ > 0;
}

void WriteBufferAggregator::SetBuffer(char *buffer,
                                      uint16_t buffer_idx,
                                      FileId file_id,
                                      uint64_t start_off,
                                      bool use_fixed)
{
    buffer_ = buffer;
    buffer_idx_ = buffer_idx;
    use_fixed_ = use_fixed;
    file_id_ = file_id;
    start_off_ = start_off;
    next_off_ = start_off;
    current_used_ = 0;
    pages_.clear();
    release_ptrs_.clear();
    release_indices_.clear();
}

bool WriteBufferAggregator::CanAppend(FileId file_id,
                                      uint64_t offset,
                                      size_t size) const
{
    if (buffer_ == nullptr)
    {
        return false;
    }
    if (file_id != file_id_)
    {
        return false;
    }
    if (offset != next_off_)
    {
        LOG(INFO) << "WriteBufferAggregator::CanAppend non-contiguous offset="
                  << offset << " expected=" << next_off_
                  << " file_id=" << file_id_;
        return false;
    }
    if (current_used_ + size > buffer_capacity_)
    {
        return false;
    }
    return true;
}

char *WriteBufferAggregator::TryReserve(FileId file_id,
                                        uint64_t offset,
                                        size_t size)
{
    if (!CanAppend(file_id, offset, size))
    {
        return nullptr;
    }
    char *ptr = buffer_ + current_used_;
    current_used_ += size;
    next_off_ += size;
    return ptr;
}

void WriteBufferAggregator::AddPage(VarPage page,
                                    char *release_ptr,
                                    uint16_t release_index)
{
    pages_.push_back(std::move(page));
    release_ptrs_.push_back(release_ptr);
    release_indices_.push_back(release_index);
}

bool WriteBufferAggregator::ShouldFlush(size_t next_size) const
{
    if (buffer_ == nullptr)
    {
        return false;
    }
    return current_used_ + next_size > buffer_capacity_;
}

WriteBufferBatch WriteBufferAggregator::TakeBatch()
{
    WriteBufferBatch batch;
    batch.buffer = buffer_;
    batch.buffer_index = buffer_idx_;
    batch.use_fixed = use_fixed_;
    batch.file_id = file_id_;
    batch.start_offset = start_off_;
    batch.bytes = current_used_;
    batch.pages = std::move(pages_);
    batch.release_ptrs = std::move(release_ptrs_);
    batch.release_indices = std::move(release_indices_);
    buffer_ = nullptr;
    buffer_idx_ = 0;
    use_fixed_ = true;
    file_id_ = 0;
    start_off_ = 0;
    next_off_ = 0;
    current_used_ = 0;
    pages_.clear();
    release_ptrs_.clear();
    release_indices_.clear();
    return batch;
}
}  // namespace eloqstore

