namespace {
// Helper functions for case-insensitive string comparison
bool IsCharLower(char c) { return 'a' <= c && c <= 'z'; }
bool IsCharUpper(char c) { return 'A' <= c && c <= 'Z'; }
char ConvertToLower(char c) { return IsCharUpper(c) ? c + ('a' - 'A') : c; }

std::string ConvertStringToLower(const std::string& input) {
  std::string result(input);
  std::transform(result.begin(), result.end(), result.begin(), ConvertToLower);
  return result;
}

template <typename Predicate>
bool CheckAllCharacters(const std::string& text, Predicate pred) {
  for (std::size_t idx = 0; idx < text.length(); ++idx)
    if (!pred(text[idx]))
      return false;
  return true;
}

// Determines if a string follows flexible casing rules:
// . UPPERCASE
// . lowercase
// . Capitalized
bool MatchesFlexibleCase(const std::string& text) {
  if (text.empty())
    return true;

  if (CheckAllCharacters(text, IsCharLower))
    return true;

  bool startsWithCapital = IsCharUpper(text[0]);
  std::string remainingPart = text.substr(1);

  return startsWithCapital && 
         (CheckAllCharacters(remainingPart, IsCharLower) || 
          CheckAllCharacters(remainingPart, IsCharUpper));
}
}

namespace YAML {
bool convert<bool>::decode(const Node& node, bool& value) {
  if (!node.IsScalar())
    return false;

  // Supported boolean representations per YAML spec
  static const struct {
    std::string positiveForm, negativeForm;
  } booleanNames[] = {
      {"y", "n"}, {"yes", "no"}, {"true", "false"}, {"on", "off"},
  };

  if (!MatchesFlexibleCase(node.Scalar()))
    return false;

  for (unsigned i = 0; i < sizeof(booleanNames) / sizeof(booleanNames[0]); ++i) {
    if (booleanNames[i].positiveForm == ConvertStringToLower(node.Scalar())) {
      value = true;
      return true;
    }
    if (booleanNames[i].negativeForm == ConvertStringToLower(node.Scalar())) {
      value = false;
      return true;
    }
  }

  return false;
}
}

