void FocusController::initialize(FocusedClientStack *stack, ClientManager *manager,
                                 PaneLayout *layout, domain::Window *win) {
    m_stack = stack;
    m_layout = layout;
    m_manager = manager;
    m_manager->onClientAdded([this](KakouneClient *client) {
        m_stack->activate(client);
    });
    m_manager->onClientRemoved([this](KakouneClient *client) {
        m_stack->erase(client);
    });
    win->onMouseMove([this](float px, float py) {
        handleMouseMove(px, py);
    });
    win->onMouseButton([this](domain::MouseButtonEvent evt) {
        handleMouseButton(evt);
    });
}

void FocusController::handleMouseMove(float x, float y) {
    if (m_mouse_active) {
        return;
    }
    Pane *pane = m_layout->locatePaneAt(x, y);
    if (pane && pane->client != m_stack->active()) {
        m_stack->activate(pane->client);
    }
}

void FocusController::handleMouseButton(domain::MouseButtonEvent event) {
    if (event.action == domain::MouseButtonAction::DOWN) {
        m_mouse_active = true;
    } else if (event.action == domain::MouseButtonAction::UP) {
        m_mouse_active = false;
        handleMouseMove(event.x, event.y);
    }
}

#include <vector>
#include <unordered_set>

class Solution {
public:
    // Compute the count of distinct bitwise OR results from all subarrays
    int countDistinctSubarrayORs(std::vector<int> inputArray) {
        std::unordered_set<int> finalSet, currentSet, nextSet;

        for (int element : inputArray) {
            nextSet = {element};
            for (int prevValue : currentSet) {
                nextSet.insert(element | prevValue);
            }
            for (int value : currentSet = nextSet) {
                finalSet.insert(value);
            }
        }
        return finalSet.size();
    }
};

