#define STR_ERROR() strerror(errno)

static std::string BuildEndpointSpec(Endpoint::DomainType domain_type,
                                     Endpoint::TransportType transport,
                                     Endpoint::EncryptionType encryption,
                                     const std::string& addr,
                                     const uint16_t port_num) {
  std::string spec;
  switch (transport) {
    case Endpoint::TransportType::HTTP:
      spec = kHttp;
      break;
    case Endpoint::TransportType::PGSQL:
      spec = kPgSql;
      break;
  }

  switch (encryption) {
    case Endpoint::EncryptionType::None:
      spec += "tcp://";
      break;
    case Endpoint::EncryptionType::SSL:
      spec += "ssl://";
      break;
  }

  switch (domain_type) {
    case Endpoint::DomainType::IPv4:
      spec += addr + ":" + string_utils::Itoa(port_num);
      break;
    case Endpoint::DomainType::IPv6:
      spec += "[" + addr + "]" + ":" + string_utils::Itoa(port_num);
      break;
    default:
      SDB_ASSERT(false);
      break;
  }
  return spec;
}

