EndpointIp::EndpointIp(DomainType domain_type, EndpointType kind,
                       TransportType protocol, EncryptionType security,
                       int backlog_size, bool reuse_addr,
                       const std::string& address, const uint16_t port_num)
  : Endpoint(domain_type, kind, protocol, security,
             BuildEndpointSpec(domain_type, protocol, security, address, port_num),
             backlog_size),
    _host(address),
    _port(port_num),
    _reuse_address(reuse_addr) {
  SDB_ASSERT(domain_type == Endpoint::DomainType::IPv4 ||
             domain_type == Endpoint::DomainType::IPv6);
}

////////////////////////////////////////////////////////////////////////////////
/// destroys an IP socket endpoint
////////////////////////////////////////////////////////////////////////////////
EndpointIp::~EndpointIp() {
  if (_connected) {
    disconnect();
  }
}

////////////////////////////////////////////////////////////////////////////////
/// connects a socket
////////////////////////////////////////////////////////////////////////////////
SocketWrapper EndpointIp::connectSocket(const struct addrinfo* ai,
                                        double connect_timeout,
                                        double request_timeout) {
  const char* err_str;
  char err_msg[1080];

  // set address and port
  char host[NI_MAXHOST];
  char serv[NI_MAXSERV];
  if (::getnameinfo(ai->ai_addr, (socklen_t)ai->ai_addrlen, host,
                    sizeof(host), serv, sizeof(serv),
                    NI_NUMERICHOST | NI_NUMERICSERV) == 0) {
    SDB_TRACE("xxxxx", sdb::Logger::FIXME, "bind to address '", host,
              "', port ", _port);
  }

  SocketWrapper sock;
  sock = Sdbsocket(ai->ai_family, ai->ai_socktype, ai->ai_protocol);
  if (!Sdbisvalidsocket(sock)) {
    err_str = STR_ERROR();
    snprintf(err_msg, sizeof(err_msg), "socket() failed with %d - %s", errno,
             err_str);
    error_message = err_msg;
    return sock;
  }

  if (_type == EndpointType::Server) {
    // try to reuse address
    if (_reuse_address) {
      int opt_val = 1;
      if (Sdbsetsockopt(sock, SOL_SOCKET, SO_REUSEADDR,
                        reinterpret_cast<char*>(&opt_val), sizeof(opt_val)) == -1) {
        err_str = STR_ERROR();
        snprintf(err_msg, sizeof(err_msg), "setsockopt() failed with #%d - %s",
                 errno, err_str);
        error_message = err_msg;
        Sdbclosesocket(sock);
        Sdbinvalidatesocket(&sock);
        return sock;
      }
    }

    // server needs to bind to socket
    int res = Sdbbind(sock, ai->ai_addr, ai->ai_addrlen);
    if (res != 0) {
      err_str = STR_ERROR();
      snprintf(err_msg, sizeof(err_msg),
               "bind(address '%s', port %d) failed with #%d - %s", host,
               (int)_port, errno, err_str);
      error_message = err_msg;
      Sdbclosesocket(sock);
      Sdbinvalidatesocket(&sock);
      return sock;
    }

    // listen for new connection, executed for server endpoints only
    SDB_TRACE("xxxxx", sdb::Logger::FIXME, "using backlog size ",
              _listen_backlog);
    res = Sdblisten(sock, _listen_backlog);
    if (res != 0) {
      err_str = STR_ERROR();
      snprintf(err_msg, sizeof(err_msg), "listen() failed with #%d - %s", errno,
               err_str);
      error_message = err_msg;
      Sdbclosesocket(sock);
      Sdbinvalidatesocket(&sock);
      return sock;
    }
  } else if (_type == EndpointType::Client) {
    // connect to endpoint, executed for client endpoints only
    // set timeout
    setTimeout(sock, connect_timeout);
    int res = Sdbconnect(sock, (const struct sockaddr*)ai->ai_addr,
                         ai->ai_addrlen);
    if (res != 0) {
      err_str = STR_ERROR();
      snprintf(err_msg, sizeof(err_msg), "connect() failed with #%d - %s",
               errno, err_str);
      error_message = err_msg;
      Sdbclosesocket(sock);
      Sdbinvalidatesocket(&sock);
      return sock;
    }
  }

  if (!setSocketFlags(sock)) {  // set some common socket flags for
                                // client and server
    Sdbclosesocket(sock);
    Sdbinvalidatesocket(&sock);
    return sock;
  }

  if (_type == EndpointType::Client) {
    setTimeout(sock, request_timeout);
  }

  _connected = true;
  _socket = sock;
  return _socket;
}

////////////////////////////////////////////////////////////////////////////////
/// connect the endpoint
////////////////////////////////////////////////////////////////////////////////
SocketWrapper EndpointIp::connect(double connect_timeout,
                                  double request_timeout) {
  struct addrinfo* res_list = nullptr;
  struct addrinfo* ai;
  struct addrinfo hints;
  int status;
  SocketWrapper sock;
  Sdbinvalidatesocket(&sock);

  SDB_DEBUG("xxxxx", sdb::Logger::FIXME, "connecting to ip endpoint '",
            _specification, "'");
  SDB_ASSERT(!Sdbisvalidsocket(_socket));
  SDB_ASSERT(!_connected);

  memset(&hints, 0, sizeof(struct addrinfo));
  hints.ai_family = domain();  // Allow IPv4 or IPv6
  hints.ai_flags = AI_PASSIVE | AI_NUMERICSERV | AI_ALL;
  hints.ai_socktype = SOCK_STREAM;

  std::string port_str = string_utils::Itoa(_port);
  status = getaddrinfo(_host.c_str(), port_str.c_str(), &hints, &res_list);
  if (status != 0) {
    error_message = std::string("getaddrinfo for host '") + _host +
                    std::string("': ") + gai_strerror(status);
    if (res_list != nullptr) {
      freeaddrinfo(res_list);
    }
    return sock;
  }

  // Try all returned addresses until one works
  for (ai = res_list; ai != nullptr; ai = ai->ai_next) {
    // try to bind the address info pointer
    sock = connectSocket(ai, connect_timeout, request_timeout);
    if (Sdbisvalidsocket(sock)) {
      // OK
      break;
    }
  }

  freeaddrinfo(res_list);
  return sock;
}

////////////////////////////////////////////////////////////////////////////////
/// destroys an IPv4 socket endpoint
////////////////////////////////////////////////////////////////////////////////
void EndpointIp::disconnect() {
  if (_connected) {
    SDB_ASSERT(Sdbisvalidsocket(_socket));
    _connected = false;
    Sdbclosesocket(_socket);
    Sdbinvalidatesocket(&_socket);
  }
}

