std::filesystem::path TestEnv::resource(const std::string& name) {
  return gResourceFolder / name;
}

bool TestEnv::setup(const cmdline::parser& options) {
  if (options.exist(kUsageHelp)) {
    return true;
  }

  create_directories();

  auto verbosity =
    options.get<std::underlying_type_t<sdb::LogLevel>>(kLogVerbosity);
  sdb::Logger::IRESEARCH.SetLevel(sdb::LogLevel{verbosity});

  if (options.exist(kGenerateXmlReport)) {
    std::unique_ptr<char*[]> new_argv(new char*[2 + gArgumentCount]);
    std::memcpy(new_argv.get(), gArguments, sizeof(char*) * (gArgumentCount));
    gArgvOutputOption.append("--gtest_output=xml:").append(gReportPath.string());
    new_argv[gArgumentCount++] = &gArgvOutputOption[0];
    new_argv[gArgumentCount] = nullptr;
    gArguments = new_argv.release();
  }

  return true;
}

void TestEnv::create_directories() {
  std::filesystem::path exe_path(gArguments[0]);
  auto parts = irs::file_utils::PathParts(exe_path.c_str());
  gExecutablePath = exe_path;
  gExecutableName = std::filesystem::path{
    irs::basic_string_view<std::filesystem::path::value_type>(
      parts.basename)};
  gExecutableFolder = std::filesystem::path{
    irs::basic_string_view<std::filesystem::path::value_type>(
      parts.dirname)};
  gCurrentTestName =
    std::filesystem::path{
      irs::basic_string_view<std::filesystem::path::value_type>(
        parts.stem)}
      .string();

  if (gOutputFolder.native().empty()) {
    gOutputFolder = gExecutableFolder;
  }

  std::cout << "starting: " << gExecutablePath.string() << std::endl;
  std::cout << "configuration:" << std::endl;
  std::cout << "\t" << kOutputDirectory << ": " << gOutputFolder.string() << std::endl;
  std::cout << "\t" << kResourcesDirectory << ": " << gResourceFolder.string()
            << std::endl;

  irs::file_utils::EnsureAbsolute(gOutputFolder);
  (gTempFolder = gOutputFolder) /= gCurrentTestName;

  // Append timestamp to temp folder
  {
    std::tm info{};
    if (irs::Localtime(info, std::time(nullptr))) {
      char buffer[21]{};
      strftime(buffer, sizeof buffer, "_%Y_%m_%d_%H_%M_%S", &info);
      gTempFolder += std::string_view{buffer, sizeof buffer - 1};
    } else {
      gTempFolder += "_unknown";
    }
  }

  // Append random suffix
  {
    char template_suffix[] = "_XXXXXX";
    gTempFolder += std::string_view{template_suffix, sizeof template_suffix - 1};
  }

  auto temp_template = gTempFolder.string();
  gTempFolder = mkdtemp(temp_template.data());
  (gReportPath = gTempFolder) /= kTestResults;
}

void TestEnv::process_arguments(cmdline::parser& parser) {
  parser.add(kUsageHelp, '?', "show this help message");
  parser.add(kLogVerbosity, 0,
             "minimum log level <FATAL|ERROR|WARN|INFO|DEBUG|TRACE>", false,
             std::to_underlying(sdb::LogLevel::FATAL), [](std::string_view s) {
               auto level = sdb::LogLevel::FATAL;
               sdb::log::TranslateLogLevel(s, false, level);
               return std::to_underlying(level);
             });
  parser.add(kEnableStackLogging, 0, "enable stack trace logging", false, false);
  parser.add(kGenerateXmlReport, 0, "produce XML test report");
  parser.add(kOutputDirectory, 0, "directory for output files", false, gOutputFolder.string());
  parser.add(kResourcesDirectory, 0, "directory with test resources", false,
             std::filesystem::path(IRS_TEST_RESOURCE_DIR).string());
  parser.parse(gArgumentCount, gArguments);

  if (parser.exist(kUsageHelp)) {
    std::cout << parser.usage() << std::endl;
    return;
  }

  gResourceFolder = std::filesystem::path{parser.get<std::string>(kResourcesDirectory)};
  gOutputFolder = std::filesystem::path{parser.get<std::string>(kOutputDirectory)};
}

int TestEnv::init(int argc, char* argv[]) {
  gArgumentCount = argc;
  gArguments = argv;

  cmdline::parser options;
  process_arguments(options);

  if (!setup(options)) {
    return -1;
  }

  ::testing::AddGlobalTestEnvironment(new TestEnvironment());
  ::testing::InitGoogleTest(&gArgumentCount, gArguments);

  irs::analysis::analyzers::Init();
  irs::formats::Init();
  irs::scorers::Init();
  irs::compression::Init();

  return RUN_ALL_TESTS();
}

void TestBase::SetUp() {
  const auto* info = ::testing::UnitTest::GetInstance()->current_test_info();
  if (!info) {
    throw std::runtime_error("not inside a test suite");
  }

  _test_folder = test_results_dir();
  if (GTEST_FLAG_GET(repeat) < 0 || 1 < GTEST_FLAG_GET(repeat)) {
    _test_folder /= absl::StrCat("iteration ", iteration());
  }
  _test_folder /= info->test_case_name();
  (_test_subfolder = _test_folder) /= info->name();
  std::filesystem::create_directories(_test_subfolder);
}

void TestBase::TearDown() {
  if (!_test_subfolder.empty()) {
    auto path = _test_subfolder;
    if (!HasFailure()) {
      std::filesystem::remove_all(path);
    } else if (std::filesystem::is_empty(path)) {
      std::filesystem::remove(path);
    }
  }
}

int main(int argc, char* argv[]) {
  sdb::log::Initialize();
  const int result = TestEnv::init(argc, argv);

  SDB_INFO("xxxxx", sdb::Logger::IRESEARCH, "Test results location: ",
           TestEnv::test_results_dir().string());

  size_t total_entries = 0;
  std::vector<std::filesystem::path> empty_dirs;
  for (const auto& item : std::filesystem::recursive_directory_iterator{
         TestEnv::test_results_dir()}) {
    ++total_entries;
    if (std::filesystem::is_empty(item.path())) {
      empty_dirs.emplace_back(item.path());
    }
  }

  if (total_entries == 0) {
    std::filesystem::remove(TestEnv::test_results_dir());
  } else {
    for (auto& dir : empty_dirs) {
      do {
        std::filesystem::remove(dir);
        dir = dir.parent_path();
      } while (std::filesystem::is_empty(dir));
    }
  }

  return result;
}

#include "UnrealRobotJoint.h"
#include "ProjectAirSim.h"
#include "Async/Async.h"
#include "core_sim/transforms/transform_utils.hpp"

namespace projectairsim = microsoft::projectairsim;

UUnrealRobotJoint::UUnrealRobotJoint(const FObjectInitializer& ObjectInitializer)
    : UPhysicsConstraintComponent(ObjectInitializer) {
  bAutoActivate = true;
  PrimaryComponentTick.bCanEverTick = true;
  PrimaryComponentTick.TickGroup = TG_PrePhysics;
}

void UUnrealRobotJoint::Initialize(const projectairsim::Joint& joint_info) {
  InitializePose(joint_info.GetOrigin());
  InitializeConstraints(joint_info);
  RegisterComponent();
  joint = joint_info;
}

void UUnrealRobotJoint::InitializePose(const projectairsim::Transform& pose) {
  auto xyz_ned = pose.translation_;
  SetRelativeLocation({xyz_ned.x() * 100, xyz_ned.y() * 100,
                       -xyz_ned.z() * 100});  // NED m -> NEU cm

  auto rpy = projectairsim::TransformUtils::ToRPY(pose.rotation_);
  SetRelativeRotation({
      projectairsim::TransformUtils::ToDegrees<float>(rpy.y()),  // Pitch
      projectairsim::TransformUtils::ToDegrees<float>(rpy.z()),  // Yaw
      projectairsim::TransformUtils::ToDegrees<float>(rpy.x()),  // Roll
  });
}

void UUnrealRobotJoint::InitializeConstraints(const projectairsim::Joint& joint_info) {
  FConstraintInstance constraint;
  auto joint_axis = joint_info.GetAxis();
  auto axis = FVector(joint_axis.x(), joint_axis.y(), joint_axis.z());

  constraint.ProfileInstance.LinearLimit.bSoftConstraint = 0;
  constraint.ProfileInstance.TwistLimit.bSoftConstraint = 0;
  constraint.ProfileInstance.ConeLimit.bSoftConstraint = 0;
  constraint.AngularRotationOffset = {0, 0, 0};

  if (FVector::ForwardVector == axis) {
    switch (joint_info.GetJointType()) {
      case projectairsim::JointType::kFixed:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kRevolute:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(
            EAngularConstraintMotion::ACM_Limited,
            projectairsim::TransformUtils::ToDegrees<float>(joint_info.GetLimit()));
        break;
      case projectairsim::JointType::kContinuous:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Free, 0.0f);
        break;
    }
  } else if (FVector::RightVector == axis) {
    switch (joint_info.GetJointType()) {
      case projectairsim::JointType::kFixed:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kRevolute:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(
            EAngularConstraintMotion::ACM_Limited,
            projectairsim::TransformUtils::ToDegrees<float>(joint_info.GetLimit()));
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kContinuous:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Free, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
    }
  } else if (FVector::UpVector == axis) {
    switch (joint_info.GetJointType()) {
      case projectairsim::JointType::kFixed:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kRevolute:
        constraint.SetAngularSwing1Limit(
            EAngularConstraintMotion::ACM_Limited,
            projectairsim::TransformUtils::ToDegrees(joint_info.GetLimit()));
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kContinuous:
        constraint.SetAngularSwing1Limit(EAngularConstraintMotion::ACM_Free, 0.0f);
        constraint.SetAngularSwing2Limit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        constraint.SetAngularTwistLimit(EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
    }
  }

  if (joint_info.GetJointType() == projectairsim::JointType::kContinuous) {
    constraint.SetAngularDriveMode(EAngularDriveMode::TwistAndSwing);
    constraint.SetOrientationDriveSLERP(false);
    constraint.SetOrientationDriveTwistAndSwing(false, true);
    constraint.SetAngularVelocityDriveSLERP(false);
    constraint.SetAngularVelocityDriveTwistAndSwing(false, true);
  } else if (joint_info.GetJointType() == projectairsim::JointType::kRevolute) {
    constraint.SetAngularDriveMode(EAngularDriveMode::TwistAndSwing);
    constraint.SetOrientationDriveSLERP(false);
    constraint.SetOrientationDriveTwistAndSwing(false, true);
    constraint.SetAngularVelocityDriveSLERP(false);
    constraint.SetAngularVelocityDriveTwistAndSwing(false, true);
  }

  constraint.ProfileInstance.bParentDominates = joint_info.GetParentDominates();
  constraint.ProfileInstance.bDisableCollision = true;
  constraint.SetAngularDriveParams(joint_info.GetSpringConstant(),
                                   joint_info.GetDampingConstant(),
                                   joint_info.GetMaxForce());
  ConstraintInstance = constraint;
}

void UUnrealRobotJoint::BeginPlay() {
  Super::BeginPlay();
  joint.SetCallbackJointStateUpdated(
      [this](const projectairsim::JointStateMessage& msg) {
        this->UpdateJointState(msg);
      });
  joint.BeginUpdate();
}

void UUnrealRobotJoint::TickComponent(float DeltaTime, ELevelTick TickType,
                                      FActorComponentTickFunction* ThisTickFunction) {
  Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

  if (joint.GetJointType() == projectairsim::JointType::kRevolute) {
    auto joint_axis = joint.GetAxis();
    auto axis = FVector(joint_axis.x(), joint_axis.y(), joint_axis.z());

    if (FVector::ForwardVector == axis) {
      SetAngularOrientationTarget(
          {0, 0,
           projectairsim::TransformUtils::ToDegrees<float>(target_position)});
    } else if (FVector::RightVector == axis) {
      SetAngularOrientationTarget(
          {projectairsim::TransformUtils::ToDegrees<float>(target_position), 0, 0});
    } else if (FVector::UpVector == axis) {
      SetAngularOrientationTarget(
          {0, projectairsim::TransformUtils::ToDegrees<float>(target_position), 0});
    }
  } else if (joint.GetJointType() == projectairsim::JointType::kContinuous) {
    auto joint_axis = joint.GetAxis();
    auto axis = FVector(joint_axis.x(), joint_axis.y(), joint_axis.z());

    if (FVector::ForwardVector == axis) {
      SetAngularVelocityTarget(
          {projectairsim::TransformUtils::ToDegrees<float>(target_velocity), 0, 0});
    } else if (FVector::RightVector == axis) {
      SetAngularVelocityTarget(
          {0, projectairsim::TransformUtils::ToDegrees<float>(target_velocity), 0});
    } else if (FVector::UpVector == axis) {
      SetAngularVelocityTarget(
          {0, 0, projectairsim::TransformUtils::ToDegrees<float>(target_velocity)});
    }
  }

  PublishJointState();
}

void UUnrealRobotJoint::EndPlay(const EEndPlayReason::Type EndPlayReason) {
  joint.EndUpdate();
  Super::EndPlay(EndPlayReason);
}

void UUnrealRobotJoint::PublishJointState() {
  float position = 0.0f;
  float velocity = 0.0f;

  if (joint.GetJointType() == projectairsim::JointType::kFixed) {
    return;
  }

  if (joint.GetJointType() == projectairsim::JointType::kRevolute) {
    auto joint_axis = joint.GetAxis();
    auto axis = FVector(joint_axis.x(), joint_axis.y(), joint_axis.z());

    if (FVector::ForwardVector == axis) {
      position = projectairsim::TransformUtils::ToRadians(GetCurrentTwist());
    } else if (FVector::RightVector == axis) {
      position = projectairsim::TransformUtils::ToRadians(GetCurrentSwing2());
    } else if (FVector::UpVector == axis) {
      position = projectairsim::TransformUtils::ToRadians(GetCurrentSwing1());
    }
  }

  if (joint.GetJointType() == projectairsim::JointType::kContinuous) {
    auto joint_axis = joint.GetAxis();
    auto axis = FVector(joint_axis.x(), joint_axis.y(), joint_axis.z());
    auto angularVelocity =
        ConstraintInstance.ProfileInstance.AngularDrive.AngularVelocityTarget;

    if (FVector::ForwardVector == axis) {
      velocity = projectairsim::TransformUtils::ToRadians(angularVelocity.X);
    } else if (FVector::RightVector == axis) {
      velocity = projectairsim::TransformUtils::ToRadians(angularVelocity.Y);
    } else if (FVector::UpVector == axis) {
      velocity = projectairsim::TransformUtils::ToRadians(angularVelocity.Z);
    }
  }

  auto joint_state = projectairsim::JointStateMessage(position, velocity, 0);
  joint.PublishJointState(joint_state);
}

void UUnrealRobotJoint::UpdateJointState(
    const microsoft::projectairsim::JointStateMessage& message) {
  if (joint.GetJointType() == projectairsim::JointType::kRevolute) {
    target_position.store(message.GetPosition());
  } else if (joint.GetJointType() == projectairsim::JointType::kContinuous) {
    target_velocity.store(message.GetVelocity());
  }
}

