LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
	switch (message)
	{
	case WM_CLOSE:
		DestroyWindow(hwnd);
		break;
	case WM_DESTROY:
		PostQuitMessage(0);
		break;
	default:
		return DefWindowProc(hwnd, message, wParam, lParam);
	}
	return 0;
}

int WINAPI wWinMain(HINSTANCE hInstance, HINSTANCE /*hPrevInstance*/, LPWSTR /*lpCmdLine*/, int nShowCmd)
{
	int argumentCount;
	LPWSTR* argumentList = CommandLineToArgvW(GetCommandLineW(), &argumentCount);
	if (!argumentList) {
		MessageBox(nullptr,
			TEXT("Failed to parse command line arguments."),
			TEXT("Critical Error"),
			MB_ICONERROR | MB_OK);
		return EXIT_FAILURE;
	}

	auto cleanup_argument_memory = [&argumentList]() {
		if (argumentList) {
			LocalFree(argumentList);
			argumentList = nullptr;
		}
	};

	if (argumentCount < 2) {
		MessageBox(nullptr,
			TEXT("No model file path provided. Application will terminate."),
			TEXT("Missing Input"),
			MB_ICONERROR | MB_OK);
		cleanup_argument_memory();
		return EXIT_FAILURE;
	}

	std::wstring modelPathWide(argumentList[1]);
	char* narrowBuffer = new char[modelPathWide.size() + 1];
	memset(narrowBuffer, '\0', modelPathWide.size() + 1);
	utf8::utf16to8(modelPathWide.c_str(), modelPathWide.c_str() + modelPathWide.size(), narrowBuffer);
	g_ModelFilePath = narrowBuffer;
	delete[] narrowBuffer;

	cleanup_argument_memory();

	WNDCLASSEX windowClass;
	MSG messageLoop;
	windowClass.cbSize = sizeof(WNDCLASSEX);
	windowClass.style = CS_HREDRAW | CS_VREDRAW;
	windowClass.lpfnWndProc = MainWndProc;
	windowClass.cbClsExtra = 0;
	windowClass.cbWndExtra = 0;
	windowClass.hInstance = hInstance;
	windowClass.hIcon = LoadIcon(nullptr, IDI_APPLICATION);
	windowClass.hCursor = LoadCursor(nullptr, IDC_ARROW);
	windowClass.hbrBackground = reinterpret_cast<HBRUSH>(GetStockObject(WHITE_BRUSH));
	windowClass.lpszMenuName = nullptr;
	windowClass.lpszClassName = g_WindowClassName;
	windowClass.hIconSm = LoadIcon(nullptr, IDI_APPLICATION);

	if (!RegisterClassEx(&windowClass)) {
		MessageBox(nullptr, "Window Class Registration Failed", "Error",
			MB_ICONEXCLAMATION | MB_OK);
		return 0;
	}

	RECT windowRect = { 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT };
	AdjustWindowRect(&windowRect, WS_OVERLAPPEDWINDOW, FALSE);

	mainHwnd = CreateWindowEx(
		WS_EX_CLIENTEDGE,
		g_WindowClassName,
		"Advanced 3D Rendering Demo",
		WS_OVERLAPPEDWINDOW,
		CW_USEDEFAULT, CW_USEDEFAULT,
		windowRect.right - windowRect.left,
		windowRect.bottom - windowRect.top,
		nullptr, nullptr, hInstance, nullptr
	);

	if (!mainHwnd) {
		MessageBox(nullptr, "Window Creation Failed", "Error",
			MB_ICONEXCLAMATION | MB_OK);
		return 0;
	}

	ShowWindow(mainHwnd, nShowCmd);
	UpdateWindow(mainHwnd);

	clientWidth = windowRect.right - windowRect.left;
	clientHeight = windowRect.bottom - windowRect.top;

	try {
		InitializeDirect3D(hInstance, mainHwnd);

		while (true) {
			if (PeekMessage(&messageLoop, nullptr, 0, 0, PM_REMOVE)) {
				TranslateMessage(&messageLoop);
				DispatchMessage(&messageLoop);
				if (messageLoop.message == WM_QUIT)
					break;
			}
			RenderScene();
		}

		CleanupDirect3D();
		return static_cast<int>(messageLoop.wParam);
	} catch (const std::exception& ex) {
		MessageBox(mainHwnd, ex.what(), TEXT("Exception"), MB_ICONERROR | MB_OK);
		CleanupDirect3D();
		return EXIT_FAILURE;
	} catch (...) {
		MessageBox(mainHwnd, TEXT("Unknown exception occurred."), TEXT("Error"), MB_ICONERROR | MB_OK);
		CleanupDirect3D();
		return EXIT_FAILURE;
	}
}

void InitializeDirect3D(HINSTANCE /*hInstance*/, HWND hwnd)
{
	HRESULT status;
	UINT creationFlags = 0;

#ifdef _DEBUG
	creationFlags |= D3D11_CREATE_DEVICE_DEBUG;
#endif

	D3D_DRIVER_TYPE availableDrivers[] = {
		D3D_DRIVER_TYPE_HARDWARE,
		D3D_DRIVER_TYPE_WARP,
		D3D_DRIVER_TYPE_REFERENCE
	};
	UINT driverCount = ARRAYSIZE(availableDrivers);

	D3D_FEATURE_LEVEL requestedLevels[] = {
		D3D_FEATURE_LEVEL_11_1,
		D3D_FEATURE_LEVEL_11_0,
		D3D_FEATURE_LEVEL_10_1,
		D3D_FEATURE_LEVEL_10_0
	};
	UINT levelCount = ARRAYSIZE(requestedLevels);

	for (UINT i = 0; i < driverCount; ++i) {
		driverType = availableDrivers[i];
		status = D3D11CreateDevice(
			nullptr, driverType, nullptr, creationFlags,
			requestedLevels, levelCount, D3D11_SDK_VERSION,
			&device, &featureLevel, &context
		);

		if (status == E_INVALIDARG) {
			status = D3D11CreateDevice(
				nullptr, driverType, nullptr, creationFlags,
				&requestedLevels[1], levelCount - 1,
				D3D11_SDK_VERSION, &device, &featureLevel, &context
			);
		}

		if (SUCCEEDED(status))
			break;
	}

	if (FAILED(status))
		ReportError("Direct3D Device Initialization Failed");

#if _DEBUG
	status = device->QueryInterface(IID_PPV_ARGS(&debugInterface));
	if (FAILED(status))
		OutputDebugString(TEXT("Failed to retrieve DirectX Debug Interface.\n"));
#endif

	UINT msaaQualityLevel;
	device->CheckMultisampleQualityLevels(DXGI_FORMAT_R8G8B8A8_UNORM, 4, &msaaQualityLevel);

	IDXGIFactory1* dxgiFactory = nullptr;
	{
		IDXGIDevice* dxgiDevice = nullptr;
		status = device->QueryInterface(__uuidof(IDXGIDevice), reinterpret_cast<void**>(&dxgiDevice));
		if (SUCCEEDED(status)) {
			IDXGIAdapter* adapter = nullptr;
			status = dxgiDevice->GetAdapter(&adapter);
			if (SUCCEEDED(status)) {
				status = adapter->GetParent(__uuidof(IDXGIFactory1), reinterpret_cast<void**>(&dxgiFactory));
				adapter->Release();
			}
			dxgiDevice->Release();
		}
	}

	if (FAILED(status))
		ReportError("DXGI Factory Acquisition Failed");

	IDXGIFactory2* dxgiFactory2 = nullptr;
	status = dxgiFactory->QueryInterface(__uuidof(IDXGIFactory2), reinterpret_cast<void**>(&dxgiFactory2));
	if (dxgiFactory2) {
		status = device->QueryInterface(__uuidof(ID3D11Device1), reinterpret_cast<void**>(&device1));
		if (SUCCEEDED(status)) {
			(void)context->QueryInterface(__uuidof(ID3D11DeviceContext1), reinterpret_cast<void**>(&context1));
		}

		DXGI_SWAP_CHAIN_DESC1 swapDesc = {};
		swapDesc.Width = WINDOW_WIDTH;
		swapDesc.Height = WINDOW_HEIGHT;
		swapDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
		swapDesc.SampleDesc.Count = 4;
		swapDesc.SampleDesc.Quality = msaaQualityLevel - 1;
		swapDesc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
		swapDesc.BufferCount = 1;

		status = dxgiFactory2->CreateSwapChainForHwnd(device, hwnd, &swapDesc, nullptr, nullptr, &chain1);
		if (SUCCEEDED(status)) {
			status = chain1->QueryInterface(__uuidof(IDXGISwapChain), reinterpret_cast<void**>(&chain));
		}
		dxgiFactory2->Release();
	} else {
		DXGI_SWAP_CHAIN_DESC swapDesc = {};
		swapDesc.BufferCount = 1;
		swapDesc.BufferDesc.Width = WINDOW_WIDTH;
		swapDesc.BufferDesc.Height = WINDOW_HEIGHT;
		swapDesc.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
		swapDesc.BufferDesc.RefreshRate.Numerator = 60;
		swapDesc.BufferDesc.RefreshRate.Denominator = 1;
		swapDesc.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
		swapDesc.OutputWindow = hwnd;
		swapDesc.SampleDesc.Count = 1;
		swapDesc.SampleDesc.Quality = msaaQualityLevel - 1;
		swapDesc.Windowed = TRUE;

		status = dxgiFactory->CreateSwapChain(device, &swapDesc, &chain);
	}

	dxgiFactory->MakeWindowAssociation(mainHwnd, DXGI_MWA_NO_ALT_ENTER);
	dxgiFactory->Release();

	if (FAILED(status))
		ReportError("Swap Chain Creation Failed");

	ID3D11Texture2D* backBufferTexture = nullptr;
	chain->GetBuffer(0, __uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&backBufferTexture));
	device->CreateRenderTargetView(backBufferTexture, nullptr, &renderTarget);
	backBufferTexture->Release();

	D3D11_TEXTURE2D_DESC depthDesc = {};
	depthDesc.Width = WINDOW_WIDTH;
	depthDesc.Height = WINDOW_HEIGHT;
	depthDesc.MipLevels = 1;
	depthDesc.ArraySize = 1;
	depthDesc.Format = DXGI_FORMAT_D24_UNORM_S8_UINT;
	depthDesc.SampleDesc.Count = 4;
	depthDesc.SampleDesc.Quality = msaaQualityLevel - 1;
	depthDesc.Usage = D3D11_USAGE_DEFAULT;
	depthDesc.BindFlags = D3D11_BIND_DEPTH_STENCIL;
	depthDesc.CPUAccessFlags = 0;
	depthDesc.MiscFlags = 0;

	status = device->CreateTexture2D(&depthDesc, nullptr, &depthStencilBuffer);
	if (FAILED(status))
		ReportError("Depth Stencil Texture Creation Failed");

	D3D11_DEPTH_STENCIL_VIEW_DESC dsvDesc = {};
	dsvDesc.Format = depthDesc.Format;
	dsvDesc.ViewDimension = D3D11_DSV_DIMENSION_TEXTURE2D;
	dsvDesc.Texture2D.MipSlice = 0;

	status = device->CreateDepthStencilView(depthStencilBuffer, &dsvDesc, &depthStencilView);
	if (FAILED(status))
		ReportError("Depth Stencil View Creation Failed");

	context->OMSetRenderTargets(1, &renderTarget, depthStencilView);

	D3D11_RASTERIZER_DESC rasterDesc = {};
	rasterDesc.AntialiasedLineEnable = false;
	rasterDesc.CullMode = D3D11_CULL_BACK;
	rasterDesc.DepthBias = 0;
	rasterDesc.DepthBiasClamp = 0.0f;
	rasterDesc.DepthClipEnable = true;
	rasterDesc.FillMode = D3D11_FILL_SOLID;
	rasterDesc.FrontCounterClockwise = false;
	rasterDesc.MultisampleEnable = false;
	rasterDesc.ScissorEnable = false;
	rasterDesc.SlopeScaledDepthBias = 0.0f;

	status = device->CreateRasterizerState(&rasterDesc, &rasterizerState);
	if (SUCCEEDED(status))
		context->RSSetState(rasterizerState);

	D3D11_VIEWPORT viewport = {};
	viewport.TopLeftX = 0.0f;
	viewport.TopLeftY = 0.0f;
	viewport.MinDepth = 0.0f;
	viewport.MaxDepth = 1.0f;
	viewport.Width = static_cast<float>(clientWidth);
	viewport.Height = static_cast<float>(clientHeight);
	context->RSSetViewports(1, &viewport);

	SetupPipeline();
	SetupGraphicsResources();
}

void CleanupDirect3D()
{
	if (chain)
		chain->SetFullscreenState(FALSE, nullptr);

	if (sceneModel) {
		sceneModel->Shutdown();
		delete sceneModel;
		sceneModel = nullptr;
	}

	SafeRelease(textureSampler);
	SafeRelease(constantBuffer);
	SafeRelease(inputLayout);
	SafeRelease(vertexShader);
	SafeRelease(pixelShader);
	SafeRelease(rasterizerState);
	SafeRelease(depthStencilView);
	SafeRelease(depthStencilBuffer);
	SafeRelease(renderTarget);
	SafeRelease(chain);
	SafeRelease(chain1);
	SafeRelease(context1);
	SafeRelease(device1);
	SafeRelease(context);

#if _DEBUG
	if (debugInterface) {
		OutputDebugString(TEXT("Dumping DirectX 11 live objects...\n"));
		debugInterface->ReportLiveDeviceObjects(D3D11_RLDO_DETAIL);
		SafeRelease(debugInterface);
	} else {
		OutputDebugString(TEXT("Unable to dump live objects: no debug interface available.\n"));
	}
#endif

	SafeRelease(device);
}

void RenderScene()
{
	static float timeElapsed = 0.0f;
	static ULONGLONG startTime = 0;
	ULONGLONG currentTime = GetTickCount64();

	if (startTime == 0)
		startTime = currentTime;

	timeElapsed = (currentTime - startTime) / 1000.0f;

	float clearColors[4] = { 0.15f, 0.25f, 0.45f, 1.0f };
	context->ClearRenderTargetView(renderTarget, clearColors);
	context->ClearDepthStencilView(depthStencilView, D3D11_CLEAR_DEPTH | D3D11_CLEAR_STENCIL, 1.0f, 0);

	context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);

	worldTransform = XMMatrixRotationY(timeElapsed);

	TransformBuffer transformData;
	transformData.worldMatrix = XMMatrixTranspose(worldTransform);
	transformData.viewMatrix = XMMatrixTranspose(viewTransform);
	transformData.projMatrix = XMMatrixTranspose(projectionTransform);

	context->UpdateSubresource(constantBuffer, 0, nullptr, &transformData, 0, 0);

	context->VSSetShader(vertexShader, nullptr, 0);
	context->VSSetConstantBuffers(0, 1, &constantBuffer);
	context->PSSetShader(pixelShader, nullptr, 0);
	context->PSSetSamplers(0, 1, &textureSampler);

	sceneModel->Render(context);

	chain->Present(0, 0);
}

void SetupPipeline()
{
	ID3DBlob* vertexBlob = nullptr;
	ID3DBlob* pixelBlob = nullptr;

	if (FAILED(CompileShaderFromSource(SHADER_PATH VERTEX_SHADER_PATH, nullptr, "VSMain", "vs_4_0", &vertexBlob)))
		ReportError("Vertex Shader Compilation Failed");

	if (FAILED(CompileShaderFromSource(SHADER_PATH FRAGMENT_SHADER_PATH, nullptr, "PSMain", "ps_4_0", &pixelBlob)))
		ReportError("Pixel Shader Compilation Failed");

	device->CreateVertexShader(vertexBlob->GetBufferPointer(), vertexBlob->GetBufferSize(), nullptr, &vertexShader);
	device->CreatePixelShader(pixelBlob->GetBufferPointer(), pixelBlob->GetBufferSize(), nullptr, &pixelShader);

	D3D11_INPUT_ELEMENT_DESC layoutDesc[] = {
		{ "POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 0, D3D11_INPUT_PER_VERTEX_DATA, 0 },
		{ "TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT, 0, D3D11_APPEND_ALIGNED_ELEMENT, D3D11_INPUT_PER_VERTEX_DATA, 0 }
	};

	device->CreateInputLayout(layoutDesc, ARRAYSIZE(layoutDesc),
		vertexBlob->GetBufferPointer(), vertexBlob->GetBufferSize(), &inputLayout);
	context->IASetInputLayout(inputLayout);

	SafeRelease(vertexBlob);
	SafeRelease(pixelBlob);
}

void SetupGraphicsResources()
{
	HRESULT hr;

	projectionTransform = XMMatrixPerspectiveFovLH(XM_PIDIV4,
		static_cast<float>(clientWidth) / static_cast<float>(clientHeight), 0.01f, 1000.0f);

	D3D11_BUFFER_DESC cbDesc = {};
	cbDesc.Usage = D3D11_USAGE_DEFAULT;
	cbDesc.ByteWidth = sizeof(TransformBuffer);
	cbDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
	cbDesc.CPUAccessFlags = 0;

	hr = device->CreateBuffer(&cbDesc, nullptr, &constantBuffer);
	if (FAILED(hr))
		ReportError("Constant Buffer Creation Failed");

	D3D11_SAMPLER_DESC samplerDesc = {};
	samplerDesc.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
	samplerDesc.AddressU = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.AddressV = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.AddressW = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.ComparisonFunc = D3D11_COMPARISON_NEVER;
	samplerDesc.MinLOD = 0;
	samplerDesc.MaxLOD = D3D11_FLOAT32_MAX;

	hr = device->CreateSamplerState(&samplerDesc, &textureSampler);
	if (FAILED(hr))
		ReportError("Sampler State Creation Failed");

	XMVECTOR cameraPosition = XMVectorSet(0.0f, 10.0f, -150.0f, 0.0f);
	XMVECTOR lookAtPoint = XMVectorSet(0.0f, 5.0f, 0.0f, 0.0f);
	XMVECTOR upDirection = XMVectorSet(0.0f, 1.0f, 0.0f, 0.0f);

	viewTransform = XMMatrixLookAtLH(cameraPosition, lookAtPoint, upDirection);

	sceneModel = new ModelLoader();
	if (!sceneModel->Initialize(mainHwnd, device, context, g_ModelFilePath))
		ReportError("Model Loading Failed");
}

HRESULT CompileShaderFromSource(LPCWSTR filename, const D3D_SHADER_MACRO* defines, LPCSTR entryPoint, LPCSTR model, ID3DBlob** blob)
{
	UINT flags = D3DCOMPILE_ENABLE_STRICTNESS | D3DCOMPILE_PACK_MATRIX_COLUMN_MAJOR;

#ifdef _DEBUG
	flags |= D3DCOMPILE_DEBUG;
#endif

	ID3DBlob* errorBlob = nullptr;
	HRESULT result = D3DCompileFromFile(filename, defines, D3D_COMPILE_STANDARD_FILE_INCLUDE,
		entryPoint, model, flags, 0, blob, &errorBlob);

	if (FAILED(result)) {
		if (errorBlob != nullptr)
			OutputDebugStringA((LPCSTR)errorBlob->GetBufferPointer());
	}

	if (errorBlob != nullptr)
		errorBlob->Release();

	return result;
}

void ReportError(LPCSTR message)
{
	throw std::runtime_error(message);
}

