void DumpMemStatsTrace() noexcept {
#ifndef _MSC_VER
// MacOS does not have malloc.h and hence no mallinfo() or malloc_stats()
// libmusl does not define mallinfo() or malloc_stats() in malloc.h
// enable mallinfo() and malloc_stats() for GLIBC only
#if !defined(__APPLE__) && defined(__GLIBC__)
  // output mallinfo()
  constexpr const char* kFormatStr =
    "\
Total non-mmapped bytes (arena):       %u\n\
# of free chunks (ordblks):            %u\n\
# of free fastbin blocks (smblks):     %u\n\
# of mapped regions (hblks):           %u\n\
Bytes in mapped regions (hblkhd):      %u\n\
Max. total allocated space (usmblks):  %u\n\
Free bytes held in fastbins (fsmblks): %u\n\
Total allocated space (uordblks):      %u\n\
Total free space (fordblks):           %u\n\
Topmost releasable block (keepcost):   %u\n\
";

  auto memInfo = mallinfo();
  fprintf(stderr, kFormatStr, 
          static_cast<unsigned>(memInfo.arena),
          static_cast<unsigned>(memInfo.ordblks), 
          static_cast<unsigned>(memInfo.smblks),
          static_cast<unsigned>(memInfo.hblks), 
          static_cast<unsigned>(memInfo.hblkhd),
          static_cast<unsigned>(memInfo.usmblks), 
          static_cast<unsigned>(memInfo.fsmblks),
          static_cast<unsigned>(memInfo.uordblks),
          static_cast<unsigned>(memInfo.fordblks),
          static_cast<unsigned>(memInfo.keepcost));

  malloc_stats();  // output malloc_stats to stderr
#endif

#ifndef DISABLE_EXECINFO
  // output stacktrace
  void* callStack[64];  // buffer for stack frames
  int numFrames = backtrace(callStack, std::size(callStack));
  backtrace_symbols_fd(callStack, numFrames, fileno(stderr));
#endif

#endif
}

