// Dynamic library handle for dbghelp.dll
static dynutils::lib_obj* dbghelp_module{nullptr};

// Function pointer type for MiniDumpWriteDump
using WINBOOL = int;
using MiniDumpWriteDump_t = WINBOOL WINAPI(HANDLE hProcess, DWORD ProcessId, HANDLE hFile, MINIDUMP_TYPE DumpType,
                                           CONST PMINIDUMP_EXCEPTION_INFORMATION ExceptionParam,
                                           CONST PMINIDUMP_USER_STREAM_INFORMATION UserStreamParam,
                                           CONST PMINIDUMP_CALLBACK_INFORMATION CallbackParam);

static MiniDumpWriteDump_t* pMiniDumpWriteDump{nullptr};

// Buffers for user-defined dump data
static std::array<char, 2048 + 1> g_userNotes{};
static std::array<wchar_t, 512 + 1> g_dumpPathW{};

// Synchronization variables
static LONG g_dumpInProgress{0};
static HANDLE g_dumpCompleteEvent{nullptr};

// Ensure only one thread writes the dump
#define DUMP_IN_PROGRESS /* prevent multiple threads from writing simultaneously */                           \
    (InterlockedCompareExchange(&g_dumpInProgress, 1, 0) != 0 &&                                               \
     (g_dumpCompleteEvent == nullptr ||                                                                         \
      WaitForSingleObject(g_dumpCompleteEvent, INFINITE) == 0x00000000L /* WAIT_OBJECT_0 */))

// Internal function to write crash dump
static LONG write_crash_dump_internal(EXCEPTION_POINTERS* exceptionInfo) {
    // Generate unique filename using timestamp and process ID
    const DWORD pid = GetCurrentProcessId();
    SYSTEMTIME currentTime;
    GetLocalTime(&currentTime);
    swprintf_s(g_dumpPathW.data(), 512, L"dump_%hu%02hu%02hu_%02hu%02hu%02hu_pid%lu.dmp",
               currentTime.wYear, currentTime.wMonth, currentTime.wDay,
               currentTime.wHour, currentTime.wMinute, currentTime.wSecond, pid);

    // Create dump file
    HANDLE fileHandle = CreateFileW(g_dumpPathW.data(), GENERIC_WRITE, FILE_SHARE_READ,
                                    nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if(fileHandle != INVALID_HANDLE_VALUE) {
        MINIDUMP_EXCEPTION_INFORMATION exceptionParams{
            .ThreadId = GetCurrentThreadId(),
            .ExceptionPointers = exceptionInfo,
            .ClientPointers = FALSE
        };

        const auto dumpFlags =
            static_cast<MINIDUMP_TYPE>(MiniDumpWithDataSegs | MiniDumpWithHandleData | MiniDumpWithThreadInfo);

        MINIDUMP_USER_STREAM customStream;
        MINIDUMP_USER_STREAM_INFORMATION streamInfo;

        // Include optional user notes in dump
        if(g_userNotes[0] != '\0') {
            customStream.Type = 0x4D430000;  // "MC" in hex
            customStream.BufferSize = strlen(g_userNotes.data());
            customStream.Buffer = g_userNotes.data();
            streamInfo.UserStreamCount = 1;
            streamInfo.UserStreamArray = &customStream;
        } else {
            streamInfo.UserStreamCount = 0;
            streamInfo.UserStreamArray = nullptr;
        }

        const BOOL result = pMiniDumpWriteDump(GetCurrentProcess(), pid, fileHandle, dumpFlags,
                                               &exceptionParams, &streamInfo, nullptr);
        (void)result;
        CloseHandle(fileHandle);
    }

    fflush(stdout);
    fflush(stderr);

    // Signal completion to other threads
    if(g_dumpCompleteEvent != nullptr) {
        SetEvent(g_dumpCompleteEvent);
    }
    return EXCEPTION_EXECUTE_HANDLER;
}

// Unhandled exception filter callback
static LONG WINAPI unhandled_exception_filter(EXCEPTION_POINTERS* exceptionInfo) {
    if(DUMP_IN_PROGRESS) {
        return EXCEPTION_EXECUTE_HANDLER;
    }
    return write_crash_dump_internal(exceptionInfo);
}

// Global storage for captured context during signal-based crashes
static EXCEPTION_POINTERS g_exceptionPointers;
static EXCEPTION_RECORD g_exceptionRecord;
static CONTEXT g_context;

// Signal handler for SIGABRT and similar
static void abort_handler(int /*signal*/) {
    if(DUMP_IN_PROGRESS) {
        _exit(3);
    }

    // Capture current context
    memset(&g_context, 0, sizeof(CONTEXT));
    memset(&g_exceptionRecord, 0, sizeof(EXCEPTION_RECORD));
    RtlCaptureContext(&g_context);

    g_exceptionRecord.ExceptionCode = EXCEPTION_BREAKPOINT;
    g_exceptionRecord.ExceptionAddress = RET_ADDR();
    g_exceptionPointers.ContextRecord = &g_context;
    g_exceptionPointers.ExceptionRecord = &g_exceptionRecord;

    write_crash_dump_internal(&g_exceptionPointers);
    _exit(3);
}

// CRT terminate() handler
static void terminate_handler() { abort_handler(SIGABRT); }

// CRT pure virtual function call handler
static void purecall_handler() {
    if(DUMP_IN_PROGRESS) {
        _exit(3);
    }

    memset(&g_context, 0, sizeof(CONTEXT));
    memset(&g_exceptionRecord, 0, sizeof(EXCEPTION_RECORD));
    RtlCaptureContext(&g_context);

    g_exceptionRecord.ExceptionCode = STATUS_NONCONTINUABLE_EXCEPTION;
    g_exceptionRecord.ExceptionAddress = RET_ADDR();
    g_exceptionPointers.ContextRecord = &g_context;
    g_exceptionPointers.ExceptionRecord = &g_exceptionRecord;

    write_crash_dump_internal(&g_exceptionPointers);
    _exit(3);
}

// CRT invalid parameter handler
static void invalid_parameter_handler(const wchar_t* expr, const wchar_t* func, const wchar_t* srcFile,
                                      unsigned int lineNum, uintptr_t /*pReserved*/) {
    if(DUMP_IN_PROGRESS) {
        _exit(3);
    }

    memset(&g_context, 0, sizeof(CONTEXT));
    memset(&g_exceptionRecord, 0, sizeof(EXCEPTION_RECORD));
    RtlCaptureContext(&g_context);

    g_exceptionRecord.ExceptionCode = STATUS_INVALID_PARAMETER;
    g_exceptionRecord.ExceptionAddress = RET_ADDR();
    g_exceptionPointers.ContextRecord = &g_context;
    g_exceptionPointers.ExceptionRecord = &g_exceptionRecord;

    // Build detailed error message
    std::array<wchar_t, 32 + 1> lineBuffer{};
    UString errorMsg{US_("Invalid parameter detected:\n")};
    if(expr) {
        errorMsg += US_("  Expression: ");
        errorMsg += expr;
        errorMsg += u'\n';
    }
    if(func) {
        errorMsg += US_("  Function: ");
        errorMsg += func;
        errorMsg += u'\n';
    }
    if(srcFile) {
        swprintf_s(lineBuffer.data(), 32, L"%u", lineNum);
        errorMsg += US_("  File: ");
        errorMsg += srcFile;
        errorMsg += u':';
        errorMsg += lineBuffer.data();
        errorMsg += u'\n';
    }

    // Copy message into global buffer for inclusion in minidump
    memcpy(g_userNotes.data(), errorMsg.toUtf8(), std::min((int)g_userNotes.size() - 1, errorMsg.lengthUtf8()));

    write_crash_dump_internal(&g_exceptionPointers);
    _exit(3);
}

}  // namespace

void init() {
    // Load dbghelp.dll and resolve MiniDumpWriteDump
    {
        dbghelp_module = dynutils::load_lib_system("dbghelp.dll");
        if(dbghelp_module) {
            pMiniDumpWriteDump = dynutils::load_func<MiniDumpWriteDump_t>(dbghelp_module, "MiniDumpWriteDump");
        }

        if(!pMiniDumpWriteDump || !dbghelp_module) {
            debugLog("WARNING: crash dumps unavailable — failed to load MiniDumpWriteDump: {}",
                     dynutils::get_error());
            dynutils::unload_lib(dbghelp_module);
            return;
        }
    }

    // Setup synchronization event
    g_dumpCompleteEvent = CreateEventW(nullptr, TRUE, FALSE, nullptr);

    // Register unhandled exception filter
    SetUnhandledExceptionFilter(unhandled_exception_filter);

    // Prevent CRT from interfering with our exception handling
#ifndef MCENGINE_PLATFORM_WINDOWS_MSVCRT
#ifndef _DEBUG
    _set_abort_behavior(0, _WRITE_ABORT_MSG | _CALL_REPORTFAULT);
#else
    _set_abort_behavior(0, _CALL_REPORTFAULT);
#endif
#endif

    // Install CRT-specific handlers
    signal(SIGABRT, abort_handler);
    _set_purecall_handler(purecall_handler);
    _set_invalid_parameter_handler(invalid_parameter_handler);
    std::set_terminate(terminate_handler);

    // Reserve stack space and configure error mode
    {
        using SetThreadStackGuarantee_t = WINBOOL WINAPI(PULONG StackSizeInBytes);
        using SetErrorMode_t = UINT WINAPI(UINT uMode);

        SetThreadStackGuarantee_t* pstack_guarantee = nullptr;
        SetErrorMode_t* perror_mode = nullptr;

        const auto* kernel32_module = reinterpret_cast<dynutils::lib_obj*>(GetModuleHandleA("kernel32.dll"));
        if(kernel32_module) {
            pstack_guarantee =
                dynutils::load_func<SetThreadStackGuarantee_t>(kernel32_module, "SetThreadStackGuarantee");
            perror_mode = dynutils::load_func<SetErrorMode_t>(kernel32_module, "SetErrorMode");
        }

        if(pstack_guarantee) {
            ULONG stackReserve = 64UL * 1024;  // 64KB stack reserve
            pstack_guarantee(&stackReserve);
        }

        if(perror_mode) {
            SetErrorMode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
        }
    }
}
}  // namespace CrashHandler
#endif

