popup_message_v3::query_t popup_message_v3::setupMessageBox(fb2k::hwnd_t owner, const char* p_text, const char* p_caption, unsigned style) {
    query_t q = {};
    q.title = p_caption;
    q.msg = p_text;
    q.wndParent = owner;

    switch (style & 0xF) {
    default:
    case MB_OK:
        q.buttons = buttonOK;
        q.defButton = buttonOK;
        break;
    case MB_OKCANCEL:
        q.buttons = buttonOK | buttonCancel;
        q.defButton = (style & MB_DEFBUTTON2) ? buttonCancel : buttonOK;
        break;
    case MB_ABORTRETRYIGNORE:
        q.buttons = buttonAbort | buttonRetry | buttonIgnore;
        if (style & MB_DEFBUTTON3) q.defButton = buttonIgnore;
        else if (style & MB_DEFBUTTON2) q.defButton = buttonRetry;
        else q.defButton = buttonAbort;
        break;
    case MB_YESNOCANCEL:
        q.buttons = buttonYes | buttonNo | buttonCancel;
        if (style & MB_DEFBUTTON3) q.defButton = buttonCancel;
        else if (style & MB_DEFBUTTON2) q.defButton = buttonNo;
        else q.defButton = buttonYes;
        break;
    case MB_YESNO:
        q.buttons = buttonYes | buttonNo;
        q.defButton = (style & MB_DEFBUTTON2) ? buttonNo : buttonYes;
        break;
    case MB_RETRYCANCEL:
        q.buttons = buttonRetry | buttonCancel;
        q.defButton = (style & MB_DEFBUTTON2) ? buttonCancel : buttonRetry;
        break;
    }

    switch (style & 0xF0) {
    case MB_ICONHAND:
        q.icon = iconError;
        break;
    case MB_ICONQUESTION:
        q.icon = iconQuestion;
        break;
    case MB_ICONEXCLAMATION:
        q.icon = iconWarning;
        break;
    case MB_ICONASTERISK:
        q.icon = iconInformation;
        break;
    }

    return q;
}

int popup_message_v3::messageBoxReply(uint32_t result) {
    if (result & buttonOK) return IDOK;
    if (result & buttonCancel) return IDCANCEL;
    if (result & buttonYes) return IDYES;
    if (result & buttonNo) return IDNO;
    if (result & buttonRetry) return IDRETRY;
    if (result & buttonAbort) return IDABORT;
    if (result & buttonIgnore) return IDIGNORE;
    return -1;
}

void popup_message_v3::messageBoxAsync(fb2k::hwnd_t owner, const char* p_text, const char* p_caption, unsigned style, std::function<void (int)> callback) {
    PFC_ASSERT(core_api::is_main_thread());
    auto q = setupMessageBox(owner, p_text, p_caption, style);
    if (callback) {
        q.reply = fb2k::makeCompletionNotify([callback](unsigned code) {
            callback(messageBoxReply(code));
            });
    }
    this->show_query(q);
}

int popup_message_v3::messageBox(fb2k::hwnd_t owner, const char* p_text, const char* p_caption, unsigned style) {
    PFC_ASSERT(core_api::is_main_thread());
    auto q = setupMessageBox(owner, p_text, p_caption, style);
    uint32_t result = this->show_query_modal(q);
    return messageBoxReply(result);
