#include "geometry/angles.hpp"

namespace ang
{
double NormalizeAngle(double angle)
{
  double const cycle = 2.0 * math::pi;
  angle = fmod(angle, cycle);
  if (angle < 0.0)
    angle += cycle;
  if (AlmostEqualULPs(cycle, angle))
    return 0.0;
  return angle;
}

double ComputeAngularDifference(double theta1, double theta2)
{
  double const cycle = 2.0 * math::pi;
  theta1 = fmod(theta1, cycle);
  theta2 = fmod(theta2, cycle);
  double diff = theta2 - theta1;
  if (fabs(diff) > math::pi)
  {
    if (diff < 0.0)
      diff = cycle + diff;
    else
      diff = -cycle + diff;
  }
  return diff;
}

double InterpolateAngle(double first, double second)
{
  double mid = (first + second) / 2.0;
  if (fabs(first - second) > math::pi)
  {
    if (mid > 0.0)
      mid -= math::pi;
    else
      mid += math::pi;
  }
  return mid;
}
}  // namespace ang

