TEST(MiniTensor_ROL, Rosenbrock_Unconstrained)
{
  bool const
  show_results = ::testing::GTEST_FLAG(print_time);
  // suppress output
  ROL::nullstream
  dummy_stream;
  std::ostream &
  out_stream = (show_results == true) ? std::cout : dummy_stream;

  constexpr minitensor::Index
  DIMENSION{2};
  Scalar const
  alpha = 1.0;
  Scalar const
  beta = 100.0;

  minitensor::Rosenbrock<Scalar, DIMENSION>
  func(alpha, beta);

  // Define optimization algorithm.
  std::string const
  algorithm{"Line Search"};

  // Set solver parameters.
  Teuchos::ParameterList
  options;
  options.sublist("Step").sublist("Line Search").sublist("Descent Method").
    set("Type", "Newton-Krylov");
  options.sublist("Status Test").set("Gradient Tolerance", 1.0e-16);
  options.sublist("Status Test").set("Step Tolerance", 1.0e-16);
  options.sublist("Status Test").set("Iteration Limit", 128);

  // Initialize starting point
  minitensor::Vector<Scalar, DIMENSION>
  x(minitensor::Filler::RANDOM);

  ROL::MiniTensor_Minimizer<Scalar, DIMENSION>
  solver;
  solver.solve(algorithm, options, func, x);
  solver.printReport(out_stream);

  Scalar const
  tolerance{1.0e-10};
  minitensor::Vector<Scalar, DIMENSION>
  expected_solution(alpha, alpha * alpha);
  Scalar const
  deviation = minitensor::norm(expected_solution - x);
  ASSERT_LE(deviation, tolerance);
}

