template<typename S, minitensor::Index M = 2>
class HS24_Modified : public minitensor::Function_Base<HS24_Modified<S, M>, S, M>
{
public:
  HS24_Modified()
  {
  }
  static constexpr
  char const * const
  NAME{"HS24 Modified Function"};

  using Base = minitensor::Function_Base<HS24_Modified<S, M>, S, M>;

  // Explicit value.
  template<typename T, minitensor::Index N>
  T
  value(minitensor::Vector<T, N> const & x)
  {
    T const
    sqrt3 = std::sqrt(3.0);
    T const
    cubic_term = x(1) * x(1) * x(1);
    return sqrt3 * x(0) * cubic_term * (x(0) - 6.0) / 81.0;
  }

  // Default AD gradient.
  template<typename T, minitensor::Index N>
  minitensor::Vector<T, N>
  gradient(minitensor::Vector<T, N> const & x)
  {
    return Base::gradient(*this, x);
  }

  // Default AD hessian.
  template<typename T, minitensor::Index N>
  minitensor::Tensor<T, N>
  hessian(minitensor::Vector<T, N> const & x)
  {
    return Base::hessian(*this, x);
  }
};

template<typename S, minitensor::Index M = 2>
class HS4_Modified : public minitensor::Function_Base<HS4_Modified<S, M>, S, M>
{
public:
  HS4_Modified()
  {
  }
  static constexpr
  char const * const
  NAME{"HS4 Modified Function"};

  using Base = minitensor::Function_Base<HS4_Modified<S, M>, S, M>;

  // Explicit value.
  template<typename T, minitensor::Index N>
  T
  value(minitensor::Vector<T, N> const & x)
  {
    T const
    shift = x(0) + 1.0;
    return shift * shift * shift / 3.0 + x(1);
  }

  // Default AD gradient.
  template<typename T, minitensor::Index N>
  minitensor::Vector<T, N>
  gradient(minitensor::Vector<T, N> const & x)
  {
    return Base::gradient(*this, x);
  }

  // Default AD hessian.
  template<typename T, minitensor::Index N>
  minitensor::Tensor<T, N>
  hessian(minitensor::Vector<T, N> const & x)
  {
    return Base::hessian(*this, x);
  }
};

//
// HS24 feasible region
//
template<typename S, minitensor::Index NC = 3, minitensor::Index NV = 2>
class HS24_FeasibleRegion : public minitensor::Inequality_Constraint<HS24_FeasibleRegion<S, NC, NV>, S, NC, NV>
{
public:
  HS24_FeasibleRegion()
  {
  }
  static constexpr
  char const * const
  NAME{"HS24 Feasible Region"};

  using Base = minitensor::Inequality_Constraint<HS24_FeasibleRegion<S, NC, NV>, S, NC, NV>;

  // Explicit value.
  template<typename T, minitensor::Index N = 2>
  minitensor::Vector<T, NC>
  value(minitensor::Vector<T, N> const & x)
  {
    assert(x.get_dimension() == NV);
    T const
    c = std::sqrt(3.0);
    minitensor::Vector<T, NC>
    constraints(minitensor::Filler::ZEROS);
    constraints(0) = x(0) / c - x(1);
    constraints(1) = x(0) + c * x(1);
    constraints(2) = -x(0) - c * x(1) + 6.0;
    return constraints;
  }

  // Default AD gradient.
  template<typename T, minitensor::Index N = 2>
  minitensor::Matrix<T, NC, NV>
  gradient(minitensor::Vector<T, N> const & x)
  {
    return Base::gradient(*this, x);
  }
};
