#include "OpenColorIOEditorSettings.h"

// Retrieve viewport-specific OpenColorIO display settings by identifier
const FOpenColorIODisplayConfiguration* UOpenColorIOLevelViewportSettings::GetViewportSettings(FName ViewportId) const
{
	const FPerViewportDisplaySettingPair* Match = ViewportsSettings.FindByPredicate([ViewportId](const FPerViewportDisplaySettingPair& Item)
		{
			return Item.ViewportIdentifier == ViewportId;
		});
	if (Match)
	{
		return &Match->DisplayConfiguration;
	}
	return nullptr;
}

// Update or create viewport-specific OpenColorIO display settings
void UOpenColorIOLevelViewportSettings::SetViewportSettings(FName ViewportId, const FOpenColorIODisplayConfiguration& Settings)
{
	FPerViewportDisplaySettingPair* Match = ViewportsSettings.FindByPredicate([ViewportId](const FPerViewportDisplaySettingPair& Item)
		{
			return Item.ViewportIdentifier == ViewportId;
		});
	if (Match)
	{
		Match->DisplayConfiguration = Settings;
	}
	else
	{
		// Insert new entry if viewport not found
		FPerViewportDisplaySettingPair NewItem;
		NewItem.ViewportIdentifier = ViewportId;
		NewItem.DisplayConfiguration = Settings;
		ViewportsSettings.Emplace(MoveTemp(NewItem));
	}
}

#include <OTwo/Network/Packet.hpp>
#include <Genode/System/Exception.hpp>
#include <ced/compact_enc_det.h>
#include <algorithm>
#include <codecvt>
#include <locale>

void Packet::SetByteOrder(const Gx::Endian order)
{
    m_byteOrder = order;
}

Gx::Endian Packet::GetByteOrder() const
{
    return m_byteOrder;
}

void Packet::WriteBytes(const void* buffer, const std::size_t byteCount)
{
    if (buffer && byteCount > 0)
    {
        // reinterpret the input buffer as bytes
        const auto* start = reinterpret_cast<const std::byte*>(buffer);
        const auto* finish = start + byteCount;
        m_buffer.insert(m_buffer.end(), start, finish);
    }
}

std::size_t Packet::GetCurrentPosition() const
{
    return m_position;
}

void Packet::Reset()
{
    m_buffer.clear();
    m_position = 0;
    m_valid = true;
}

