Packet& Packet::operator>>(char* output)
{
    if (!output)
        throw Gx::ArgumentOutOfRangeException("Packet::operator>> Output pointer must not be null");
    while (m_valid)
    {
        std::uint8_t ch{};
        *this >> ch;
        *output++ = ch;
        if (ch == 0x00)
            break;
    }
    return *this;
}

Packet& Packet::operator>>(std::string& output)
{
    output.clear();
    while (m_valid)
    {
        std::uint8_t ch{};
        *this >> ch;
        if (ch == 0x00)
            break;
        output += static_cast<char>(ch);
    }
    return *this;
}

Packet& Packet::operator>>(wchar_t* output)
{
    while (m_valid)
    {
        std::uint32_t ch{};
        *this >> ch;
        *output++ = static_cast<wchar_t>(ch);
        if (ch == 0x00)
            break;
    }
    return *this;
}

Packet& Packet::operator>>(std::wstring& output)
{
    output.clear();
    while (m_valid)
    {
