            break;
        output += static_cast<wchar_t>(ch);
    }
    return *this;
}

Packet& Packet::operator>>(sf::String& output)
{
    output.clear();
    auto rawBytes = std::vector<char>{};
    while (m_valid)
    {
        std::uint8_t ch{};
        *this >> ch;
        if (ch == 0x00)
            break;
        rawBytes.push_back(ch);
    }
    bool confidenceHigh = false;
    int usedBytes = 0;
    const auto encodingType = CompactEncDet::DetectEncoding(
        rawBytes.data(),
        rawBytes.size(),
        nullptr,
        nullptr,
        nullptr,
        0,
        Language::UNKNOWN_LANGUAGE,
        CompactEncDet::TextCorpusType::QUERY_CORPUS,
        true,
        &usedBytes,
        &confidenceHigh
    );
    switch (encodingType)
    {
        case Encoding::ASCII_7BIT:
        case Encoding::UTF8:
        case Encoding::UTF8UTF8:
        {
            output = sf::String::fromUtf8(rawBytes.begin(), rawBytes.end());
            break;
        }
        case Encoding::UTF32LE:
        case Encoding::UTF32BE:
        case Encoding::GB18030:
        {
            // TODO: Handle Big Endian
            auto* ptr = reinterpret_cast<std::uint32_t*>(rawBytes.data());
            output = sf::String::fromUtf16(ptr, ptr + rawBytes.size() / sizeof(std::uint32_t));
            break;
        }
        default:
        {
            // TODO: Handle Big Endian
            auto* ptr = reinterpret_cast<std::uint16_t*>(rawBytes.data());
            output = sf::String::fromUtf16(ptr, ptr + rawBytes.size() / sizeof(std::uint16_t));
            break;
        }
    }
    return *this;
}

