Packet& Packet::operator<<(const std::string& str)
{
    if (!str.empty())
    {
        WriteBytes(str.c_str(), str.size());
        if (str.back() != 0x00)
            *this << static_cast<std::uint8_t>(0);
    }
    return *this;
}

Packet& Packet::operator<<(const wchar_t* wstr)
{
    *this << std::wstring(wstr ? wstr : L"");
    return *this;
}

Packet& Packet::operator<<(const std::wstring& wstr)
{
    if (!wstr.empty())
    {
        for (const wchar_t c : wstr)
            *this << static_cast<std::uint16_t>(c);
        if (static_cast<std::uint16_t>(wstr.back()) != 0x00)
            *this << static_cast<std::uint16_t>(0);
    }
    return *this;
}

Packet& Packet::operator<<(const sf::String& sstr)
{
    if (sstr.getSize() > 0)
    {
        for (const std::uint32_t codePoint : sstr)
        {
            if (codePoint <= std::numeric_limits<std::uint8_t>::max())
                *this << static_cast<std::uint8_t>(codePoint);
            else if (codePoint <= std::numeric_limits<std::uint16_t>::max())
                *this << static_cast<std::uint16_t>(codePoint);
            else
                *this << codePoint;
        }
        if (static_cast<std::uint32_t>(*(sstr.end() - 1)) != 0x00)
            *this << static_cast<std::uint8_t>(0);
    }
    return *this;
}

const void* Packet::PrepareForSending(std::size_t& outSize)
{
    outSize = GetBufferSize();
    return GetBufferPointer();
}

void Packet::ProcessIncomingData(const void* buffer, const std::size_t size)
{
    WriteBytes(buffer, size);
}

void Packet::Read(void* destination, const std::size_t count)
{
    if (m_position + count <= m_buffer.size())
    {
        std::memcpy(destination, &m_buffer[m_position], count);
        m_position += count;
    }
    else
    {
        m_valid = false;
    }
}

