namespace Core {
    namespace Network {
        TCPServer::TCPServer(int portNumber) {
            listening_socket = socket(AF_INET, SOCK_STREAM, 0);
            if (listening_socket == -1) {
                initialized = false;
                return;
            }

            address = {};
            address.sin_family = AF_INET;
            address.sin_addr.s_addr = INADDR_ANY;
            address.sin_port = htons(portNumber);
            if (bind(listening_socket, (sockaddr*)&address, sizeof(address)) < 0) {
                initialized = false;
                return;
            }
            initialized = true;
        }

        TCPServer::~TCPServer() {
            if (connection_fd > 0) close(connection_fd);
            if (listening_socket > 0) close(listening_socket);
            connection_fd = -1;
            listening_socket = -1;
        }

        std::string TCPServer::getHostName() {
            struct in_addr ip_address;
            ip_address.s_addr = gethostid();
            if (ip_address.s_addr == INADDR_NONE)
                return "";
            return std::string(inet_ntoa(ip_address));
        }

        bool TCPServer::waitConnection(WaitConnectionCallback callback) {
            interrupted = false;
            if (listen(listening_socket, 1) < 0)
                return false;

            fd_set read_fds;
            timeval interval;

            while (true) {
                if (callback != nullptr && !callback()) {
                    interrupted = true;
                    return false;
                }

                FD_ZERO(&read_fds);
                FD_SET(listening_socket, &read_fds);
                int timeoutMs = 100;
                interval.tv_sec = timeoutMs / 1000;
                interval.tv_usec = (timeoutMs % 1000) * 1000;

                int result = select(listening_socket + 1, &read_fds, nullptr, nullptr, &interval);
                if (result == -1)
                    return false;
                else if (result == 0)
                    continue;
                else {
                    connection_fd = accept(listening_socket, nullptr, nullptr);
                    if (connection_fd < 0)
                        return false;
                    break;
                }
            }
            return true;
        }

        bool TCPServer::send_all(void *dataBuffer, size_t bufferSize) {
            const char* dataPtr = reinterpret_cast<const char*>(dataBuffer);
            size_t totalBytesSent = 0;

            while (totalBytesSent < bufferSize) {
                ssize_t bytesSent = send(connection_fd, dataPtr + totalBytesSent, bufferSize - totalBytesSent, 0);
                if (bytesSent < 0) {
                    if (errno == EINTR)
                        continue;
                    return false;
                }
                if (bytesSent == 0)
                    return false;
                totalBytesSent += bytesSent;
            }
            return true;
        }

        bool TCPServer::recv(void *receiveBuffer, size_t receiveSize) {
            size_t totalBytesRead = 0;
            while (totalBytesRead < receiveSize) {
                size_t bytesRead = read(connection_fd, (char*)receiveBuffer + totalBytesRead, receiveSize - totalBytesRead);
                if (bytesRead <= 0)
                    return false;
                totalBytesRead += bytesRead;
            }
            return totalBytesRead == receiveSize;
        }
    }
}

#include "pybind11_qt/pybind11_qt_basic.h"
#include <type_traits>
#include <pybind11/stl/filesystem.h>
#include "pybind11_qt/details/pybind11_qt_utils.h"
// need to import containers to get QVariantList and QVariantMap
#include "pybind11_qt/pybind11_qt_containers.h"
namespace pybind11::detail {
    template <class CharT>
    QString qstring_from_stdstring(std::basic_string<CharT> const& inputStr)
    {
        if constexpr (std::is_same_v<CharT, char>) {
            return QString::fromStdString(inputStr);
        }
        else if constexpr (std::is_same_v<CharT, wchar_t>) {
            return QString::fromStdWString(inputStr);
        }
        else if constexpr (std::is_same_v<CharT, char16_t>) {
            return QString::fromStdU16String(inputStr);
        }
        else if constexpr (std::is_same_v<CharT, char32_t>) {
            return QString::fromStdU32String(inputStr);
        }
    }
    /**
     * Conversion part 1 (Python->C++): convert a PyObject into a QString
     * instance or return false upon failure. The second argument
     * indicates whether implicit conversions should be applied.
     */
    bool type_caster<QString>::load(handle source, bool /* convert */)
    {
        PyObject* objPtr = source.ptr();
        if (PyBytes_Check(objPtr)) {
            value = QString::fromUtf8(PyBytes_AsString(objPtr));
            return true;
        }
        else if (PyUnicode_Check(objPtr)) {
            switch (PyUnicode_KIND(objPtr)) {
            case PyUnicode_1BYTE_KIND:
                value = QString::fromUtf8(PyUnicode_AsUTF8(objPtr));
                break;
            case PyUnicode_2BYTE_KIND:
                value = QString::fromUtf16(
                    reinterpret_cast<char16_t*>(PyUnicode_2BYTE_DATA(objPtr)),
                    PyUnicode_GET_LENGTH(objPtr));
                break;
            case PyUnicode_4BYTE_KIND:
                value = QString::fromUcs4(
                    reinterpret_cast<char32_t*>(PyUnicode_4BYTE_DATA(objPtr)),
                    PyUnicode_GET_LENGTH(objPtr));
                break;
            default:
                return false;
            }
            return true;
        }
        else {
            return false;
        }
    }
    /**
     * Conversion part 2 (C++ -> Python): convert an QString instance into
     * a Python object. The second and third arguments are used to
     * indicate the return value policy and parent object (for
     * ``return_value_policy::reference_internal``) and are generally
     * ignored by implicit casters.
     */
    handle type_caster<QString>::cast(QString src, return_value_policy /* policy */,
                                      handle /* parent */)
    {
        return PyUnicode_DecodeUTF16(reinterpret_cast<const char*>(src.utf16()),
                                     2 * src.length(), nullptr, 0);
    }
    bool type_caster<QVariant>::load(handle src, bool)
    {
        // test for string first otherwise PyList_Check also works
        if (PyBytes_Check(src.ptr()) || PyUnicode_Check(src.ptr())) {
            value = src.cast<QString>();
            return true;
        }
        else if (PySequence_Check(src.ptr())) {
            // we could check if all the elements can be converted to QString
            // and store a QStringList in the QVariant but I am not sure that is
            // really useful.
            value = src.cast<QVariantList>();
            return true;
        }
        else if (PyMapping_Check(src.ptr())) {
            value = src.cast<QVariantMap>();
            return true;
        }
        else if (src.is(pybind11::none())) {
            value = QVariant();
            return true;
        }
        else if (PyDict_Check(src.ptr())) {
            value = src.cast<QVariantMap>();
            return true;
        }
        // PyBool will also return true for PyLong_Check but not the other way
        // around, so the order here is relevant.
        else if (PyBool_Check(src.ptr())) {
            value = src.cast<bool>();
            return true;
        }
        else if (PyLong_Check(src.ptr())) {
            // QVariant doesn't have long. It has int or long long. Given that
            // on m/s, long is 32 bits for 32- and 64- bit code...
            value = src.cast<int>();
            return true;
        }
        else {
            return false;
        }
    }
    handle type_caster<QVariant>::cast(QVariant var, return_value_policy policy,
                                       handle parent)
    {
        switch (var.typeId()) {
        case QMetaType::UnknownType:
            return Py_None;
        case QMetaType::Int:
            return PyLong_FromLong(var.toInt());
        case QMetaType::UInt:
            return PyLong_FromUnsignedLong(var.toUInt());
        case QMetaType::Bool:
            return PyBool_FromLong(var.toBool());
        case QMetaType::QString:
            return type_caster<QString>::cast(var.toString(), policy, parent);
        // We need to check for StringList here because these are not considered
        // List since List is QList<QVariant> will StringList is QList<QString>:
        case QMetaType::QStringList:
            return type_caster<QStringList>::cast(var.toStringList(), policy, parent);
        case QMetaType::QVariantList:
            return type_caster<QVariantList>::cast(var.toList(), policy, parent);
        case QMetaType::QVariantMap:
            return type_caster<QVariantMap>::cast(var.toMap(), policy, parent);
        default: {
            PyErr_Format(PyExc_TypeError, "type unsupported: %d", var.userType());
            throw pybind11::error_already_set();
        }
        }
    }
}  // namespace pybind11::detail

#include <iostream>
#include <list>
#include <string>

namespace Assimp {

// Helper function to locate a node element starting from the root list
bool X3DImporter::LocateNodeFromRoot(const std::string &nodeID, const X3DElemType nodeType, X3DNodeElementBase **outResult) {
    for (auto iter = mNodeList.begin(); iter != mNodeList.end(); ++iter) {
        if ((**iter).GetType() == nodeType && (**iter).GetID() == nodeID) {
            if (nullptr != outResult) {
                *outResult = *iter;
            }
            return true;
        }
    }
    return false;
}

// Recursive helper to search within a subtree rooted at 'startNode'
bool X3DImporter::LocateNodeInSubtree(X3DNodeElementBase *startNode, const std::string &nodeID,
                                      const X3DElemType nodeType, X3DNodeElementBase **outResult) {
    bool matchFound = false;

    // First check if the startNode itself matches
    if ((startNode->GetType() == nodeType) && (startNode->GetID() == nodeID)) {
        matchFound = true;
        if (nullptr != outResult) {
            *outResult = startNode;
        }
        goto end_search;
    }

    // Then recursively search in all children
    for (auto childIter = startNode->GetChildren().begin(); childIter != startNode->GetChildren().end(); ++childIter) {
        if (LocateNodeInSubtree(*childIter, nodeID, nodeType, outResult)) {
            matchFound = true;
            break;
        }
    }

end_search:
    return matchFound;
}

// Public entry point: searches either from root or static subtree depending on context
bool X3DImporter::FindNodeElement(const std::string &pID, const X3DElemType pType, X3DNodeElementBase **pElement) {
    X3DNodeElementBase *currentNode = mCurrentNode; // current traversal position
    bool searchingStatic = false; // indicates whether we're in a static group

    // Traverse upward to detect static context
    while (nullptr != currentNode) {
        if (X3DElemType::ENET_Group == currentNode->GetType()) {
            auto groupNode = static_cast<X3DNodeElementGroup *>(currentNode);
            if (groupNode->IsStatic()) {
                searchingStatic = true;
                break;
            }
        }
        currentNode = currentNode->GetParent();
    }

    // Dispatch to appropriate search strategy
    if (searchingStatic) {
        return LocateNodeInSubtree(currentNode, pID, pType, pElement);
    } else {
        return LocateNodeFromRoot(pID, pType, pElement);
    }
}

/*********************************************************************************************************************************************/
/**************************************************** Parsing Helpers: Node Tree Construction **********************************************/
/*********************************************************************************************************************************************/

void X3DImporter::BeginGroupNode(const bool isStatic) {
    X3DNodeElementGroup *newGroup = new X3DNodeElementGroup(mCurrentNode, isStatic);

    if (nullptr != mCurrentNode) {
        mCurrentNode->AddChild(newGroup);
    }

    mNodeList.push_back(newGroup);
    mCurrentNode = newGroup;
}

void X3DImporter::EnterNode(X3DNodeElementBase *nodePtr) {
    ai_assert(nullptr != nodePtr);
    mCurrentNode->AddChild(nodePtr);
    mCurrentNode = nodePtr;
}

void X3DImporter::ExitNode() {
    if (nullptr != mCurrentNode) {
        mCurrentNode = mCurrentNode->GetParent();
    }
}

