// MARK: File I/O --------------------------------------------------------------
Res<Rc<Fd>> openFile(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    isize fdRaw = ::open(path.buf(), O_RDONLY);
    if (fdRaw < 0)
        return Posix::fromLastErrno();
    auto file = makeRc<Posix::Fd>(fdRaw);
    if (try$(file->stat()).type == Type::DIR)
        return Error::isADirectory();
    return Ok(file);
}

Res<Rc<Fd>> createFile(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    auto fdRaw = ::open(path.buf(), O_WRONLY | O_CREAT | O_TRUNC, 0600);
    if (fdRaw < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(fdRaw));
}

Res<Rc<Fd>> openOrCreateFile(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    auto fdRaw = ::open(path.buf(), O_RDWR | O_CREAT, 0640);
    if (fdRaw < 0)
        return Posix::fromLastErrno();
    auto file = makeRc<Posix::Fd>(fdRaw);
    if (try$(file->stat()).type == Type::DIR)
        return Error::isADirectory();
    return Ok(file);
}

Res<Pair<Rc<Fd>>> createPipe() {
    int pipeFds[2];
    if (::pipe(pipeFds) < 0)
        return Posix::fromLastErrno();
    return Ok(Pair<Rc<Fd>>{
        makeRc<Posix::Fd>(pipeFds[0]),
        makeRc<Posix::Fd>(pipeFds[1]),
    });
}

Res<Rc<Fd>> createIn() {
    auto fd = makeRc<Posix::Fd>(STDIN_FILENO);
    fd->_leak = true; // Don't close stdin when we close the fd
    return Ok(fd);
}

Res<Rc<Fd>> createOut() {
    auto fd = makeRc<Posix::Fd>(STDOUT_FILENO);
    fd->_leak = true; // Don't close stdout when we close the fd
    return Ok(fd);
}

Res<Rc<Fd>> createErr() {
    auto fd = makeRc<Posix::Fd>(STDERR_FILENO);
    fd->_leak = true; // Don't close stderr when we close the fd
    return Ok(fd);
}

Res<Vec<DirEntry>> readDir(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    DIR* dir = ::opendir(path.buf());
    if (not dir)
        return Posix::fromLastErrno();
    Vec<DirEntry> entries;
    dirent* entry;
    errno = 0;
    while ((entry = ::readdir(dir))) {
        try$(Posix::consumeErrno());
        if (std::strcmp(entry->d_name, ".") == 0 or
            std::strcmp(entry->d_name, "..") == 0) {
            continue;
        }
        entries.pushBack(DirEntry{
            Str::fromNullterminated(entry->d_name),
            entry->d_type == DT_DIR ? Sys::Type::DIR : Sys::Type::FILE,
        });
    }
    if (::closedir(dir) < 0)
        return Posix::fromLastErrno();
    return Ok(entries);
}

Res<> createDir(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    if (::mkdir(path.buf(), 0750) < 0) {
        if (errno == EEXIST) {
            return Error::alreadyExists("directory already exists");
        }
        return Posix::fromLastErrno();
    }
    return Ok();
}

Res<Vec<Sys::DirEntry>> readDirOrCreate(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    DIR* dir = ::opendir(path.buf());
    ArmedDefer cleanup = [&]() {
        if (dir)
            ::closedir(dir);
    };

    if (dir) {
        Vec<DirEntry> entries;
        dirent* entry;
        errno = 0;
        while ((entry = ::readdir(dir))) {
            try$(Posix::consumeErrno());
            if (std::strcmp(entry->d_name, ".") == 0 or
                std::strcmp(entry->d_name, "..") == 0) {
                continue;
            }
            entries.pushBack(DirEntry{
                Str::fromNullterminated(entry->d_name),
                entry->d_type == DT_DIR ? Sys::Type::DIR : Sys::Type::FILE,
            });
        }
        return Ok(entries);
    } else {
        if (errno != ENOENT)
            return Posix::fromLastErrno();
        try$(createDir(url));
        return Ok(Vec<DirEntry>{});
    }
}

Res<Stat> stat(Ref::Url const& url) {
    String path = try$(Posix::resolve(url)).str();
    struct stat buffer;
    if (::stat(path.buf(), &buffer) < 0)
        return Posix::fromLastErrno();
    return Ok(Posix::fromStat(buffer));
}

// MARK: User interactions -----------------------------------------------------
Res<> launch(Intent intent) {
    if (intent.objects.len() != 1)
        return Error::invalidInput("expected exactly one object");
    auto [url, _] = intent.objects[0];
    String path = try$(Posix::resolve(url)).str();
    int pid = fork();
    if (pid < 0)
        return Posix::fromLastErrno();
    if (pid == 0) {
#ifdef __ck_sys_darwin__
        if (intent.action == Ref::Uti::PUBLIC_MODIFY) {
            execlp("open", "open", "-t", path.buf(), nullptr);
        } else {
            execlp("open", "open", path.buf(), nullptr);
        }
#else
        execlp("xdg-open", "xdg-open", path.buf(), nullptr);
#endif
        _exit(1);
    }
    auto status = 0;
    if (waitpid(pid, &status, 0) < 0)
        return Posix::fromLastErrno();
    if (WIFEXITED(status) and WEXITSTATUS(status) == 0)
        return Ok();
    return Posix::fromStatus(status);
}

Async::Task<> launchAsync(Intent intent) {
    co_return _Embed::launch(intent);
}

// MARK: Process ---------------------------------------------------------------
struct PosixPid : Sys::Pid {
    pid_t _pid;
    PosixPid(pid_t pid) : Pid(), _pid(pid) {}
    Res<> kill() override {
        if (::kill(_pid, SIGKILL) == -1)
            return Posix::fromLastErrno();
        return Ok();
    }
    Res<> wait() override {
        int status;
        if (::waitpid(_pid, &status, 0) == -1)
            return Posix::fromLastErrno();
        return Ok();
    }
};

Res<Rc<Pid>> spawn(Command const& cmd) {
    if (not cmd.exe or cmd.exe.len() == 0)
        return Error::invalidInput("no executable provided");

    auto buildArgv = [&](Vec<char*>& argv) {
        argv.pushBack(const_cast<char*>(cmd.exe.buf())); // argv[0]
        for (auto const& arg : cmd.args)
            argv.pushBack(const_cast<char*>(arg.buf()));
        argv.pushBack(nullptr);
    };

    auto buildEnvp = [&](Vec<String>& kvStore, Vec<char*>& envp) {
        kvStore.clear();
        envp.clear();
        for (auto const& [key, val] : cmd.env.iterItems()) {
            kvStore.pushBack(Io::format("{}={}", key, val));
        }
        for (auto& kv : kvStore)
            envp.pushBack(const_cast<char*>(kv.buf()));
        envp.pushBack(nullptr);
    };

    int inFd = -1;
    if (cmd.in)
        inFd = try$(Posix::ensurePosixFd(cmd.in.unwrap()))->_raw;
    int outFd = -1;
    if (cmd.out)
        outFd = try$(Posix::ensurePosixFd(cmd.out.unwrap()))->_raw;
    int errFd = -1;
    if (cmd.err)
        errFd = try$(Posix::ensurePosixFd(cmd.err.unwrap()))->_raw;

    pid_t pid = ::fork();
    if (pid < 0)
        return Posix::fromLastErrno();

    if (pid == 0) {
        // Child process
        if (cmd.in) {
            if (::dup2(inFd, STDIN_FILENO) < 0)
                _exit(127);
        }
        if (cmd.out) {
            if (::dup2(outFd, STDOUT_FILENO) < 0)
                _exit(127);
        }
        if (cmd.err) {
            if (::dup2(errFd, STDERR_FILENO) < 0)
                _exit(127);
        }

        Vec<char*> argv;
        buildArgv(argv);
        if (cmd.env.len()) {
            Vec<String> kvStore;
            Vec<char*> envp;
            buildEnvp(kvStore, envp);
            ::execve(cmd.exe.buf(), argv.buf(), envp.buf());
        } else {
            ::execvp(cmd.exe.buf(), argv.buf());
        }
        _exit(127); // exec failed
    }

    // Parent process
    return Ok(makeRc<PosixPid>(pid));
}

Res<Tuple<Rc<Pid>, Rc<Fd>>> spawnPty(Command const& cmd) {
    if (not cmd.exe or cmd.exe.len() == 0)
        return Error::invalidInput("no executable provided");

    auto buildArgv = [&](Vec<char*>& argv) {
        argv.pushBack(const_cast<char*>(cmd.exe.buf())); // argv[0]
        for (auto const& arg : cmd.args)
            argv.pushBack(const_cast<char*>(arg.buf()));
        argv.pushBack(nullptr);
    };

    auto buildEnvp = [&](Vec<String>& kvStore, Vec<char*>& envp) {
        kvStore.clear();
        envp.clear();
        for (auto const& [key, val] : cmd.env.iterItems()) {
            kvStore.pushBack(Io::format("{}={}", key, val));
        }
        for (auto& kv : kvStore)
            envp.pushBack(const_cast<char*>(kv.buf()));
        envp.pushBack(nullptr);
    };

    int pty = -1;
    pid_t pid = ::forkpty(&pty, nullptr, nullptr, nullptr);
    ArmedDefer deferClose = [&] {
        if (pty != -1)
            close(pty);
    };

    if (pid < 0)
        return Posix::fromLastErrno();

    if (pid == 0) {
        Vec<char*> argv;
        buildArgv(argv);
        if (cmd.env.len()) {
            Vec<String> kvStore;
            Vec<char*> envp;
            buildEnvp(kvStore, envp);
            ::execve(cmd.exe.buf(), argv.buf(), envp.buf());
        } else {
            ::execvp(cmd.exe.buf(), argv.buf());
        }
        _exit(127); // exec failed
    }

    deferClose.disarm();
    return Ok<Tuple<Rc<Pid>, Rc<Fd>>>(
        makeRc<PosixPid>(pid),
        makeRc<Posix::Fd>(pty)
    );
}

// MARK: Sockets ---------------------------------------------------------------
Res<Rc<Fd>> listenUdp(SocketAddr addr) {
    int fd = ::socket(AF_INET, SOCK_DGRAM, 0);
    if (fd < 0)
        return Posix::fromLastErrno();
    sockaddr_in addr_ = Posix::toSockAddr(addr);
    if (::bind(fd, (sockaddr*)&addr_, sizeof(addr_)) < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(fd));
}

Res<Rc<Fd>> connectTcp(SocketAddr addr) {
    int fd = ::socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0)
        return Posix::fromLastErrno();
    sockaddr_in addr_ = Posix::toSockAddr(addr);
    if (::connect(fd, (sockaddr*)&addr_, sizeof(addr_)) < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(fd));
}

Res<Rc<Fd>> listenTcp(SocketAddr addr) {
    int fd = ::socket(AF_INET, SOCK_STREAM, 0);
    if (fd < 0)
        return Posix::fromLastErrno();
    int opt = 1;
    if (::setsockopt(fd, SOL_SOCKET, SO_REUSEADDR, &opt, sizeof(opt)) < 0)
        return Posix::fromLastErrno();
    sockaddr_in addr_ = Posix::toSockAddr(addr);
    if (::bind(fd, (sockaddr*)&addr_, sizeof(addr_)) < 0)
        return Posix::fromLastErrno();
    if (::listen(fd, 256) < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(fd));
}

Res<Rc<Fd>> connectIpc(Ref::Url url) {
    int fd = ::socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd < 0)
        return Posix::fromLastErrno();
    sockaddr_un addr = {};
    addr.sun_family = AF_UNIX;
    String path = try$(Posix::resolve(url)).str();
    auto sunPath = MutSlice(addr.sun_path, sizeof(addr.sun_path) - 1);
    copy(sub(path), sunPath);
    if (::connect(fd, (sockaddr*)&addr, sizeof(addr)) < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(fd));
}

Res<Rc<Fd>> listenIpc(Ref::Url url) {
    int fd = ::socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd < 0)
        return Posix::fromLastErrno();
    sockaddr_un addr = {};
    addr.sun_family = AF_UNIX;
    String path = try$(Posix::resolve(url)).str();
    auto sunPath = MutSlice(addr.sun_path, sizeof(addr.sun_path) - 1);
    copy(sub(path), sunPath);
    if (::bind(fd, (sockaddr*)&addr, sizeof(addr)) < 0)
        return Posix::fromLastErrno();
    if (::listen(fd, 256) < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(fd));
}

// MARK: Time ------------------------------------------------------------------
Duration fromTimeSpec(timespec const& ts) {
    auto usecs = (u64)ts.tv_sec * 1000000 + (u64)ts.tv_nsec / 1000;
    return Duration::fromUSecs(usecs);
}

SystemTime now() {
    timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return SystemTime::epoch() + fromTimeSpec(ts);
}

Instant instant() {
    timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return Instant::epoch() + fromTimeSpec(ts);
}

Duration uptime() {
    timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return fromTimeSpec(ts);
}

// MARK: Memory Managment ------------------------------------------------------
isize _mmapPropsToProt(MmapProps const& options) {
    isize prot = 0;
    if (options.options & MmapOption::READ)
        prot |= PROT_READ;
    if (options.options & MmapOption::WRITE)
        prot |= PROT_WRITE;
    if (options.options & MmapOption::EXEC)
        prot |= PROT_EXEC;
    return prot;
}

Res<MmapResult> memMap(MmapProps const& options) {
    void* addr = ::mmap(reinterpret_cast<void*>(options.vaddr), options.size, _mmapPropsToProt(options), MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (addr == MAP_FAILED)
        return Posix::fromLastErrno();
    if (options.options & MmapOption::PREFETCH) {
        if (madvise(addr, options.size, MADV_WILLNEED) < 0)
            return Posix::fromLastErrno();
    }
    return Ok(MmapResult{0, (usize)addr, (usize)options.size});
}

Res<MmapResult> memMap(MmapProps const& options, Rc<Fd> maybeFd) {
    Rc<Posix::Fd> fd = try$(maybeFd.cast<Posix::Fd>());
    usize size = options.size;
    if (size == 0)
        size = try$(Io::size(*fd));
    void* addr = ::mmap(reinterpret_cast<void*>(options.vaddr), size, _mmapPropsToProt(options), MAP_SHARED, fd->_raw, options.offset);
    if (addr == MAP_FAILED)
        return Posix::fromLastErrno();
    return Ok(MmapResult{0, (usize)addr, (usize)size});
}

Res<> memUnmap(void const* buf, usize len) {
    if (::munmap((void*)buf, len) < 0)
        return Posix::fromLastErrno();
    return Ok();
}

Res<> memFlush(void* flush, usize len) {
    if (::msync(flush, len, MS_INVALIDATE) < 0)
        return Posix::fromLastErrno();
    return Ok();
}

usize pageSize() {
    return getpagesize();
}

