void verify_distinct_trees(multitree_node* tree_root, index expected_count) {
    multitree_iterator iter(tree_root);
    std::vector<std::vector<simple_bitvector>> partition_list;
    do {
        partition_list.push_back(tree_bipartitions(iter.tree()));
    } while (iter.next());

    // Ensure all trees are pairwise distinct
    std::sort(partition_list.begin(), partition_list.end());
    CHECK(std::adjacent_find(partition_list.begin(), partition_list.end()) == partition_list.end());

    // Confirm correct total count
    CHECK(partition_list.size() == expected_count);
}

TEST_CASE("multitree_iterator initialization basic", "[multitree]") {
    auto input_stream = std::istringstream{"7 4\n1 1 1 1 s1\n0 0 1 0 s2\n1 1 0 0 s3\n1 1 1 0 "
                                           "s4\n1 1 0 1 s5\n1 0 0 1 s7\n0 0 0 1 s13"};
    auto matrix_data = terraces::parse_bitmatrix(input_stream);
    auto phylogeny = terraces::parse_nwk("((((s2,s4),((s13,s1),s7)),s3),s5);", matrix_data.indices);
    auto supertree_info = terraces::create_supertree_data(phylogeny, matrix_data.matrix);

    tree_enumerator<variants::multitree_callback> eng{{}};
    auto enumeration_result = eng.run(supertree_info.num_leaves, supertree_info.constraints,
                                      supertree_info.root);
    verify_distinct_trees(enumeration_result, 9);
}

TEST_CASE("multitree_iterator initialization no constraints", "[multitree]") {
    name_map taxa_labels{"A", "B", "C", "D", "E", "F", "G", "H"};
    constraints fixed_constraints{{0, 1, 2}};
    index root_taxon = 0;

    tree_enumerator<variants::multitree_callback> generator{{}};
    auto generated_trees = generator.run(taxa_labels.size(), fixed_constraints, root_taxon);
    verify_distinct_trees(generated_trees, count_unrooted_trees<index>(7));
}

