        return group_data->profiles.size();
    }

    int columnCount(const QModelIndex &parent = QModelIndex()) const override {
        return 3;
    }

    QVariant headerData(int section, Qt::Orientation orientation, int role = Qt::DisplayRole) const override {
        if (role == Qt::DisplayRole) {
            if (orientation == Qt::Horizontal) {
                switch (section) {
                    case 0:
                        return QCoreApplication::translate(
                            "MainWindow", "Type");
                    case 1:
                        return QCoreApplication::translate(
                            "MainWindow", "Address");
                    case 2:
                        return QCoreApplication::translate(
                            "MainWindow", "Name");
                }
            } else if (orientation == Qt::Vertical) {
                return QString::number(group_data->profiles[section]);
            }
        }
        return QVariant();
    }

#define SKIP_ROLE_HANDLING 777777
    QVariant data(const QModelIndex &index, int role = Qt::DisplayRole) const override {
        if (role == SKIP_ROLE_HANDLING){
            return group_data->profiles.at(index.row());
        }
        if (role == Qt::DisplayRole) {
            int row = index.row();
            auto & profiles = group_data->profiles;
            if (profiles.size() <= row){
                return QVariant();
            }
            int col = index.column();
            if (col < 3 && col >= 0){
                int profile_id = profiles.at(row);
                auto & bean = 
                    Configs::profileManager->profiles.at(profile_id)->bean;
                switch(col){
                    case 0:
                        return bean->DisplayType();
                    case 1:
                        return bean->DisplayAddress();
                    case 2:
                        return bean->name;
                }
            }
        }
        return QVariant();
    }

    bool setData(const QModelIndex &index, const QVariant &value, int role = Qt::EditRole) override {
        return false;
    }

