TSharedPtr<SGraphPin> FControlRigGraphPanelPinFactory::CreatePin(UEdGraphPin* PinPtr) const
{
	if (PinPtr)
	{
		if (UControlRigGraphNode* NodeInstance = Cast<UControlRigGraphNode>(PinPtr->GetOwningNode()))
		{
			UControlRigGraph* GraphInstance = Cast<UControlRigGraph>(NodeInstance->GetGraph());
			if (URigVMPin* ModelPinRef = NodeInstance->GetModelPinFromPinPath(PinPtr->GetName()))
			{
				FName WidgetIdentifier = ModelPinRef->GetCustomWidgetName();
				if (WidgetIdentifier == TEXT("BoneName"))
				{
					return SNew(SControlRigGraphPinNameList, PinPtr)
						.ModelPin(ModelPinRef)
						.OnGetNameListContent_UObject(GraphInstance, &UControlRigGraph::GetBoneNameList);
				}
				else if (WidgetIdentifier == TEXT("ControlName"))
				{
					return SNew(SControlRigGraphPinNameList, PinPtr)
						.ModelPin(ModelPinRef)
						.OnGetNameListContent_UObject(GraphInstance, &UControlRigGraph::GetControlNameList);
				}
				else if (WidgetIdentifier == TEXT("SpaceName"))
				{
					return SNew(SControlRigGraphPinNameList, PinPtr)
						.ModelPin(ModelPinRef)
						.OnGetNameListContent_UObject(GraphInstance, &UControlRigGraph::GetSpaceNameList);
				}
				else if (WidgetIdentifier == TEXT("CurveName"))
				{
					return SNew(SControlRigGraphPinNameList, PinPtr)
						.ModelPin(ModelPinRef)
						.OnGetNameListContent_UObject(GraphInstance, &UControlRigGraph::GetCurveNameList);
				}
				else if (WidgetIdentifier == TEXT("ElementName"))
				{
					return SNew(SControlRigGraphPinNameList, PinPtr)
						.ModelPin(ModelPinRef)
						.OnGetNameListContent_UObject(GraphInstance, &UControlRigGraph::GetElementNameList);
				}
				else if (WidgetIdentifier == TEXT("DrawingName"))
				{
					return SNew(SControlRigGraphPinNameList, PinPtr)
						.ModelPin(ModelPinRef)
						.OnGetNameListContent_UObject(GraphInstance, &UControlRigGraph::GetDrawingNameList);
				}
				else if (WidgetIdentifier == TEXT("VariableName"))
				{
					return SNew(SControlRigGraphPinVariableName, PinPtr);
				}
				else if (WidgetIdentifier == TEXT("ParameterName"))
				{
					return SNew(SControlRigGraphPinParameterName, PinPtr);
				}
			}
			if (PinPtr->PinType.PinCategory == UEdGraphSchema_K2::PC_Struct)
			{
				if (Cast<UStruct>(PinPtr->PinType.PinSubCategoryObject)->IsChildOf(FRigVMExecuteContext::StaticStruct()))
				{
					return SNew(SGraphPinExec, PinPtr);
				}
				else if (PinPtr->PinType.PinSubCategoryObject == FRuntimeFloatCurve::StaticStruct())
				{
					return SNew(SControlRigGraphPinCurveFloat, PinPtr);
				}
			}
		}
	}
	TSharedPtr<SGraphPin> K2PinWidget = FNodeFactory::CreateK2PinWidget(PinPtr);
	if(K2PinWidget.IsValid())
	{
		return K2PinWidget;
	}
	return nullptr;
}

