template<typename V>
class OutcomeOrError {
 public:
  template<typename F>
  explicit OutcomeOrError(F f) {
    try {
      storage.template emplace<V>(f());
    } catch (const Exception& e) {
      storage.template emplace<Exception>(e);
    }
  }
  template<typename W>
  bool operator==(const OutcomeOrError<W>& other) const {
    using FirstType = std::decay_t<decltype(std::get<0>(storage))>;
    using SecondType = std::decay_t<decltype(std::get<0>(other.storage))>;
    static_assert(std::is_same_v<std::decay_t<V>, FirstType>);
    static_assert(std::is_same_v<std::decay_t<W>, SecondType>);
    constexpr bool kFirstIsSlice = std::is_same_v<Slice, FirstType>;
    constexpr bool kSecondIsSharedSlice = false;
    static_assert(kFirstIsSlice == kSecondIsSharedSlice);
    auto constexpr kComparingSliceWithSharedSlice =
      kFirstIsSlice && kSecondIsSharedSlice;
    static_assert(std::is_same_v<V, W> || kComparingSliceWithSharedSlice);
    if (storage.index() != other.storage.index()) {
      return false;
    }
    switch (storage.index()) {
      case 0: {
        const auto& left = std::get<0>(storage);
        const auto& right = std::get<0>(other.storage);
        if constexpr (kComparingSliceWithSharedSlice) {
          return left.start() == right.buffer().get();
        } else {
          return left == right;
        }
      }
      case 1: {
        const auto& left = std::get<1>(storage);
        const auto& right = std::get<1>(other.storage);
        return left.errorCode() == right.errorCode();
      }
      case std::variant_npos:
        throw std::exception();
    }
    throw std::exception();
  }
  friend std::ostream& operator<<(std::ostream& out,
                                  const OutcomeOrError& that) {
    const auto& storage = that.storage;
    switch (storage.index()) {
      case 0: {
        const auto& value = std::get<0>(storage);
        return out << ::testing::PrintToString(value);
      }
      case 1: {
        const auto& ex = std::get<1>(storage);
        return out << ex;
      }
      case std::variant_npos:
        throw std::exception();
    }
    throw std::exception();
  }
  std::variant<V, Exception> storage;
};

template<typename F>
OutcomeOrError(F) -> OutcomeOrError<std::invoke_result_t<F>>;

#define O(a) OutcomeOrError([&]() { return a; })

#define ASSERT_EQ_OUTCOME(left, right) \
  do {                                 \
    auto l = O(left);                  \
    auto r = O(right);                 \
    ASSERT_EQ(l, r);                   \
  } while (false)

