std::string normalize_whitespace(const std::string &input) {
  std::string output;
  bool previous_was_space = false;

  // First, remove leading whitespace
  auto first_non_space = std::find_if_not(input.begin(), input.end(), [](unsigned char ch) { return std::isspace(ch); });

  // If the string is entirely whitespace, return an empty string
  if (first_non_space == input.end()) {
    return "";
  }

  // Then, remove trailing whitespace by finding the last non-whitespace character
  auto last_non_space = std::find_if_not(input.rbegin(), input.rend(), [](unsigned char ch) { return std::isspace(ch); }).base();

  // Process the remaining characters
  for (auto it = first_non_space; it != last_non_space; ++it) {
    if (std::isspace(*it)) {
      if (!previous_was_space) {
        output += ' ';
        previous_was_space = true;
      }
    } else {
      output += *it;
      previous_was_space = false;
    }
  }
  return output;
}

bool equals_ignore_case(const std::string &first, const std::string &second) {
  // Check if the strings are of different lengths, if so, they can't match
  if (first.size() != second.size()) {
    return false;
  }

  // Convert both strings to lowercase and then compare
  std::string first_lower = first;
  std::string second_lower = second;

  std::transform(first_lower.begin(), first_lower.end(), first_lower.begin(), ::tolower);
  std::transform(second_lower.begin(), second_lower.end(), second_lower.begin(), ::tolower);

  // Now, perform a case-insensitive comparison
  return first_lower == second_lower;
}

std::vector<std::string> tokenize(const std::string &input, const std::string &separator) {
  std::string cleaned = normalize_whitespace(input);
  std::vector<std::string> parts;
  size_t begin = 0, finish = 0;

  while ((finish = cleaned.find(separator, begin)) != std::string::npos) {
    parts.push_back(cleaned.substr(begin, finish - begin));
    begin = finish + separator.length();
  }
  parts.push_back(cleaned.substr(begin));
  return parts;
}

bool convert_to_int(const std::string &text, int *value, bool silent) {
  try {
    *value = std::stoi(text);
    return true;
  } catch (const std::invalid_argument &e) {
    if (!silent) Zeal::Game::print_chat("Invalid Argument %s", e.what());
    return false;
  } catch (const std::out_of_range &e) {
    if (!silent) Zeal::Game::print_chat("Out of range: %s", e.what());
    return false;
  }
}

bool convert_to_float(const std::string &text, float *value, bool silent) {
