  }
}

std::string bytes_to_hex_string(const char *data, size_t count) {
  std::ostringstream stream;
  stream << std::hex << std::setfill('0');
  for (size_t i = 0; i < count; ++i) {
    stream << std::setw(2) << static_cast<unsigned int>(static_cast<unsigned char>(data[i])) << " ";
  }
  return stream.str();
}

// C++ could really use a std split() function.
std::vector<std::string> partition_string(const std::string &source, const std::string &delimiter) {
  std::vector<std::string> segments;
  size_t start = 0;
  size_t position = 0;

  while (position != std::string::npos && start < source.size()) {
    position = source.find(delimiter, start);
    size_t length = (position == std::string::npos) ? std::string::npos : position - start;
    segments.push_back(source.substr(start, length));
    start = position + delimiter.size();
  }
  return segments;
}

