vector<string> validate_seeds_range(int first_seed, int last_seed,
                                    int min_stars, int max_stars,
                                    const GalaxyCondition& gal_cond, int validation_level) {
    vector<string> valid_entries;
    for (int seed_val = first_seed; seed_val < last_seed; ++seed_val) {
        for (int star_count = min_stars; star_count < max_stars; ++star_count) {
            if (check_seed_level_1(seed_val, star_count, gal_cond, validation_level)) {
                valid_entries.push_back(to_string(seed_val) + "," + to_string(star_count));
            }
        }
    }
    return valid_entries;
}

vector<string> validate_specific_seeds(const vector<int>& seeds_list,
                                       const vector<int>& stars_list,
                                       const GalaxyCondition& gal_cond,
                                       int validation_level) {
    vector<string> confirmed_entries;
    for (size_t idx = 0; idx < seeds_list.size(); ++idx) {
        int s_id = seeds_list[idx];
        int s_cnt = stars_list[idx];
        if (check_seed_level_1(s_id, s_cnt, gal_cond, validation_level)) {
            confirmed_entries.push_back(to_string(s_id) + "," + to_string(s_cnt));
        }
    }
    return confirmed_entries;
}

static bool requires_veins(const GalaxyCondition& gal_cond) {
    if (gal_cond.need_veins) return true;
    for (const StarCondition& star : gal_cond.stars) {
        if (star.need_veins) return true;
        for (const PlanetCondition& planet : star.planets) {
            if (planet.need_veins) return true;
        }
    }
    for (const PlanetCondition& planet : gal_cond.planets) {
        if (planet.need_veins) return true;
    }
    return false;
}

static bool requires_planets(const GalaxyCondition& gal_cond) {
    for (const StarCondition& star : gal_cond.stars) {
        if (!star.planets.empty()) return true;
    }
    return !gal_cond.planets.empty();
}

int determine_validation_level(const GalaxyCondition& gal_cond, bool fast_mode) {
    if (requires_veins(gal_cond)) {
        return fast_mode ? 3 : 4;
    } else {
        return requires_planets(gal_cond) ? 2 : 1;
    }
}

vector<string> validate_seeds_batch(int start_seed, int end_seed,
                                    int start_star_num, int end_star_num,
                                    const py::dict& condition_dict, bool fast_mode) {
    GalaxyCondition galaxy_condition = galaxy_condition_to_struct(condition_dict);
    int level = determine_validation_level(galaxy_condition, fast_mode);
    return validate_seeds_range(start_seed, end_seed, start_star_num, end_star_num,
                                galaxy_condition, level);
}

vector<string> validate_seeds_precise(const vector<int>& seeds,
                                      const vector<int>& stars,
                                      const py::dict& condition_dict, bool fast_mode) {
    GalaxyCondition galaxy_condition = galaxy_condition_to_struct(condition_dict);
    int level = determine_validation_level(galaxy_condition, fast_mode);
    return validate_specific_seeds(seeds, stars, galaxy_condition, level);
}

