#define MAX_VAL(x, y) ((x) > (y) ? (x) : (y))
#define MIN_VAL(x, y) ((x) < (y) ? (x) : (y))

// Warp size constant for GPU execution
static constexpr int WARP_SZ = 32;

namespace vllm {
namespace moe {

// ====================== Softmax Implementation ===============================
// Custom softmax implementation supporting output transposition for expert-choice routing.
template <int BLOCK_SIZE, typename InputType>
class moeSoftmaxKernel {
 public:
  moeSoftmaxKernel(
      sycl::local_accessor<float, 1>& shared_mem,
      const InputType* input_data,
      const bool* row_mask,
      float* result_output,
      const int cols_per_row)
      : shared(shared_mem),
        data_in(input_data),
        active_rows(row_mask),
        data_out(result_output),
        num_cols(cols_per_row) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_SZ)]] (sycl::nd_item<1> item) const {
    void* smem_ptr = static_cast<void*>(
        shared.template get_multi_ptr<sycl::access::decorated::no>().get());
    float* scale_factor = reinterpret_cast<float*>(smem_ptr);
    float* max_val = scale_factor + 1;

    auto grp = item.get_group();
    auto local_id = item.get_local_id(0);
    auto group_id = item.get_group(0);

    const int row_offset = group_id * num_cols;
    float thread_max = -INFINITY;

    // Skip computation for finished rows
    if ((active_rows != nullptr) && active_rows[group_id]) {
      return;
    }

    // Find maximum value in the row
    for (int idx = local_id; idx < num_cols; idx += BLOCK_SIZE) {
      const int pos = row_offset + idx;
      thread_max = MAX_VAL(static_cast<float>(data_in[pos]), thread_max);
    }

    const float global_max = sycl::reduce_over_group(grp, thread_max, sycl::maximum<float>());
    if (local_id == 0) {
      *max_val = global_max;
    }
    item.barrier(sycl::access::fence_space::local_space);

    // Compute exponential sum
    thread_max = 0.0f;
    for (int idx = local_id; idx < num_cols; idx += BLOCK_SIZE) {
      const int pos = row_offset + idx;
      thread_max += sycl::exp(static_cast<float>(data_in[pos]) - *max_val);
    }

    const float sum_exp = sycl::reduce_over_group(grp, thread_max, sycl::plus<>());
    if (local_id == 0) {
      *scale_factor = 1.0f / sum_exp;
    }
    item.barrier(sycl::access::fence_space::local_space);

    // Finalize softmax output
    for (int idx = local_id; idx < num_cols; idx += BLOCK_SIZE) {
      const int pos = row_offset + idx;
      const float val = sycl::exp(static_cast<float>(data_in[pos]) - (*max_val)) * (*scale_factor);
      data_out[pos] = val;
    }
  }

 private:
  sycl::local_accessor<float, 1> shared;
  const InputType* data_in;
  const bool* active_rows;
  float* data_out;
  const int num_cols;
};

// ====================== Top-K Selection Kernel ===============================
template <int BLOCK_SIZE, typename IndexType>
class moeTopKSelector {
 public:
  moeTopKSelector(
      const float* after_softmax,
      const bool* row_mask,
      float* selected_vals,
      IndexType* expert_ids,
      int* row_mapping,
      const int total_experts,
      const int k_select,
      const int first_expert,
      const int last_expert,
      const bool do_renorm)
      : softmax_data(after_softmax),
        row_active(row_mask),
        out_vals(selected_vals),
        out_indices(expert_ids),
        src_rows(row_mapping),
        num_experts(total_experts),
        topk(k_select),
        start_idx(first_expert),
        end_idx(last_expert),
        need_renorm(do_renorm) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_SZ)]] (sycl::nd_item<1> item) const {
    int best_idx;
    float best_val;
    auto grp = item.get_group();
    auto tid = item.get_local_id(0);
    auto gid = item.get_group(0);
    const int total_rows = item.get_group_range(0);
    const int current_row = gid;
    const bool active_row = row_active ? !row_active[current_row] : true;
    const int read_base = current_row * num_experts;
    float accum_sum = 0.0f;

    for (int k_pos = 0; k_pos < topk; ++k_pos) {
      best_idx = 0;
      best_val = -1.0f;  // Inputs are probabilities so negative is safe initial

      for (int exp = tid; exp < num_experts; exp += BLOCK_SIZE) {
        const int pos = read_base + exp;
        int candidate_idx = exp;
        float candidate_val = softmax_data[pos];

        // Check against previously selected experts
        for (int prev = 0; prev < k_pos; ++prev) {
          if (out_indices[topk * current_row + prev] == exp) {
            candidate_idx = best_idx;
            candidate_val = best_val;
          }
        }

        if (candidate_val > best_val) {
          best_idx = candidate_idx;
          best_val = candidate_val;
        }
      }

      const float local_best = sycl::reduce_over_group(grp, best_val, sycl::maximum<float>());
      const int local_idx = sycl::reduce_over_group(
          grp, local_best == best_val ? best_idx : 0x7FFFFFFF, sycl::minimum<int>());

      accum_sum += local_best;

      if (tid == 0) {
        const int expert_id = local_idx;
        const bool within_node_range = expert_id >= start_idx && expert_id < end_idx;
        const bool should_process = active_row && within_node_range;
        const int out_pos = topk * current_row + k_pos;

        out_vals[out_pos] = local_best;
        out_indices[out_pos] = should_process ? (expert_id - start_idx) : num_experts;
        src_rows[out_pos] = k_pos * total_rows + current_row;
      }
      item.barrier(sycl::access::fence_space::local_space);
    }

    if (need_renorm) {
      auto range_x = item.get_local_range(0);
      for (int k_pos = tid; k_pos < topk; k_pos += range_x) {
        const int pos = topk * current_row + k_pos;
        out_vals[pos] /= accum_sum;
      }
    }
  }

 private:
  const float* softmax_data;
  const bool* row_active;
  float* out_vals;
  IndexType* out_indices;
  int* src_rows;
  const int num_experts;
  const int topk;
  const int start_idx;
  const int end_idx;
  const bool need_renorm;
};

// ====================== Optimized Top-K Gating Softmax =======================
/*
  Specialized kernel for small power-of-two expert counts or multiples of 64.
  Fuses softmax, max, and argmax into one pass.
  Limitations:
  1) Works best when number of experts is a power of two or multiple of 64.
  2) Efficient for small k values.
*/
template <
    int VEC_PER_THREAD,
    int NUM_EXPERTS,
    int WARPS_PER_BLOCK,
    int BYTES_PER_LOAD,
    int WARP_SZ_PARAM,
    typename InputType,
    typename IndexType>
class topkGatingSoftmaxKernel {
 public:
  topkGatingSoftmaxKernel(
      const InputType* input_data,
      const bool* row_mask,
      float* output_data,
      const int total_rows,
      IndexType* indices,
      int* row_map,
      const int k_select,
      const int start_expert,
      const int end_expert,
      const bool renormalize_flag)
      : data_in(input_data),
        row_active(row_mask),
        data_out(output_data),
        num_rows(total_rows),
        out_indices(indices),
        row_indices(row_map),
        k(k_select),
        start_idx(start_expert),
        end_idx(end_expert),
        need_renorm(renormalize_flag) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_SZ_PARAM)]] (sycl::nd_item<2> item) const {
    auto sub_grp = item.get_sub_group();
    auto local_x = item.get_local_id(1);
    auto local_y = item.get_local_id(0);
    auto group_x = item.get_group(1);

    // Compile-time constants setup
    static_assert(
        (BYTES_PER_LOAD & (BYTES_PER_LOAD - 1)) == 0,
        "BYTES_PER_LOAD must be power of 2");
    static_assert(BYTES_PER_LOAD <= 16, "BYTES_PER_LOAD must be <= 16");

    constexpr int ELTS_PER_LOAD = BYTES_PER_LOAD / sizeof(InputType);
    constexpr int TOTAL_ELTS = NUM_EXPERTS;
    constexpr int THREADS_PER_ROW = TOTAL_ELTS / VEC_PER_THREAD;
    constexpr int LOADS_PER_THREAD = VEC_PER_THREAD / ELTS_PER_LOAD;

    static_assert(
        VEC_PER_THREAD % ELTS_PER_LOAD == 0,
        "VEC_PER_THREAD must be multiple of ELTS_PER_LOAD");
    static_assert(
        WARP_SZ_PARAM % THREADS_PER_ROW == 0,
        "THREADS_PER_ROW must divide warp size");
    static_assert(
        (THREADS_PER_ROW & (THREADS_PER_ROW - 1)) == 0,
        "THREADS_PER_ROW must be power of 2");
    static_assert(THREADS_PER_ROW <= WARP_SZ_PARAM, "THREADS_PER_ROW <= WARP_SIZE");

    constexpr int ELTS_PER_WARP = WARP_SZ_PARAM * VEC_PER_THREAD;
    constexpr int ROWS_PER_WARP = ELTS_PER_WARP / TOTAL_ELTS;
    constexpr int ROWS_PER_BLOCK = WARPS_PER_BLOCK * ROWS_PER_WARP;

    static_assert(ELTS_PER_WARP % TOTAL_ELTS == 0, "Incompatible dimensions");

    // Runtime calculations
    const int block_start_row = group_x * ROWS_PER_BLOCK;
    const int warp_start_row = block_start_row + local_y * ROWS_PER_WARP;
    const int thread_row_offset = local_x / THREADS_PER_ROW;
    const int current_row = warp_start_row + thread_row_offset;

    if (current_row >= num_rows) return;

    const bool is_active = row_active ? !row_active[current_row] : true;

    const InputType* row_ptr = data_in + current_row * TOTAL_ELTS;
    const int group_offset = local_x % THREADS_PER_ROW;
    const int first_element = group_offset * ELTS_PER_LOAD;
    const InputType* load_ptr = row_ptr + first_element;

    // Load data
    InputType local_chunk[VEC_PER_THREAD];
#pragma unroll
    for (int i = 0; i < LOADS_PER_THREAD; ++i) {
#pragma unroll
      for (int j = 0; j < ELTS_PER_LOAD; ++j) {
        local_chunk[i * ELTS_PER_LOAD + j] =
            load_ptr[i * THREADS_PER_ROW * ELTS_PER_LOAD + j];
      }
    }

    // Convert to float
    float chunk_float[VEC_PER_THREAD];
#pragma unroll
    for (int i = 0; i < VEC_PER_THREAD; ++i) {
      chunk_float[i] = static_cast<float>(local_chunk[i]);
    }

    // Thread-local max reduction
    float local_max = chunk_float[0];
#pragma unroll
    for (int i = 1; i < VEC_PER_THREAD; ++i) {
      local_max = MAX_VAL(local_max, chunk_float[i]);
    }

    // Butterfly reduce across threads in warp
#pragma unroll
    for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
      float other_max = sycl::permute_group_by_xor(sub_grp, local_max, mask);
      local_max = MAX_VAL(local_max, other_max);
    }

    // Compute exp and sum
    float local_sum = 0.0f;
#pragma unroll
    for (int i = 0; i < VEC_PER_THREAD; ++i) {
      chunk_float[i] = sycl::exp(chunk_float[i] - local_max);
      local_sum += chunk_float[i];
    }

#pragma unroll
    for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
      local_sum += sycl::permute_group_by_xor(sub_grp, local_sum, mask);
    }

    const float inv_sum = 1.0f / local_sum;
#pragma unroll
    for (int i = 0; i < VEC_PER_THREAD; ++i) {
      chunk_float[i] *= inv_sum;
    }

    // Top-k selection
    int col_start = first_element;
    static constexpr int COLS_PER_GROUP = ELTS_PER_LOAD * THREADS_PER_ROW;
    float accum = 0.0f;

    for (int k_pos = 0; k_pos < k; ++k_pos) {
      float max_val = chunk_float[0];
      int expert_local = col_start;
      int max_idx = 0;

#pragma unroll
      for (int ldg = 0, col = col_start; ldg < LOADS_PER_THREAD;
           ++ldg, col += COLS_PER_GROUP) {
#pragma unroll
        for (int i = 0; i < ELTS_PER_LOAD; ++i) {
          float val = chunk_float[ldg * ELTS_PER_LOAD + i];
          if (val > max_val) {
            max_val = val;
            expert_local = col + i;
            max_idx = ldg * ELTS_PER_LOAD + i;
          }
        }
      }

      int winning_expert = expert_local;
#pragma unroll
      for (int mask = THREADS_PER_ROW / 2; mask > 0; mask /= 2) {
        float other_max = sycl::permute_group_by_xor(sub_grp, max_val, mask);
        int other_expert = sycl::permute_group_by_xor(sub_grp, winning_expert, mask);
        if (other_max > max_val ||
            (other_max == max_val && other_expert < winning_expert)) {
          max_val = other_max;
          winning_expert = other_expert;
        }
      }

      accum += max_val;

      if (group_offset == 0) {
        const bool in_range = winning_expert >= start_idx && winning_expert < end_idx;
        const bool process_row = is_active && in_range;
        const int out_pos = k * current_row + k_pos;

        data_out[out_pos] = max_val;
        out_indices[out_pos] = process_row ? (winning_expert - start_idx) : NUM_EXPERTS;
        row_indices[out_pos] = k_pos * num_rows + current_row;
      }

      if (winning_expert == expert_local) {
        chunk_float[max_idx] = -10000.0f;
      }
    }

    if (need_renorm) {
      for (int k_pos = group_offset; k_pos < k; k_pos += THREADS_PER_ROW) {
        const int pos = k * current_row + k_pos;
        data_out[pos] /= accum;
      }
    }
  }

 private:
  const InputType* data_in;
  const bool* row_active;
  float* data_out;
  const int num_rows;
  IndexType* out_indices;
  int* row_indices;
  const int k;
  const int start_idx;
  const int end_idx;
  const bool need_renorm;
};

namespace detail {
// Precompute compile-time constants for kernel configuration
template <
    int EXPERT_COUNT,
    int LOAD_BYTES,
    int WARP_SIZE,
    typename InputType>
struct TopkConfig {
  static constexpr int ELTS_PER_LOAD = LOAD_BYTES / sizeof(InputType);
  static_assert(
      EXPERT_COUNT % (ELTS_PER_LOAD * WARP_SIZE) == 0 ||
          EXPERT_COUNT / (ELTS_PER_LOAD * WARP_SIZE) == 0,
      "Invalid expert count alignment");

  static constexpr int VECS_PER_THREAD =
      MAX_VAL(1, EXPERT_COUNT / (ELTS_PER_LOAD * WARP_SIZE));
  static constexpr int VPT = VECS_PER_THREAD * ELTS_PER_LOAD;
  static constexpr int THREADS_PER_ROW = EXPERT_COUNT / VPT;
  static const int ROWS_PER_WARP = WARP_SIZE / THREADS_PER_ROW;
};
}  // namespace detail

template <
    int NUM_EXPERTS,
    int WARPS_PER_BLOCK,
    int WARP_SIZE,
    int MAX_LOAD_BYTES,
    typename InputType,
    typename IndexType>
void launch_topk_gating(
    const InputType* input,
    const bool* row_mask,
    float* output,
    IndexType* indices,
    int* row_map,
    const int total_rows,
    const int k,
    const int start_expert,
    const int end_expert,
    bool renormalize,
    sycl::queue& queue) {
  static constexpr int LOAD_SIZE = MIN_VAL(MAX_LOAD_BYTES, sizeof(InputType) * NUM_EXPERTS);
  using Config = detail::
      TopkConfig<NUM_EXPERTS, LOAD_SIZE, WARP_SIZE, InputType>;
  static constexpr int VPT = Config::VPT;
  static constexpr int ROWS_PER_WARP = Config::ROWS_PER_WARP;

  const int warps_needed = (total_rows + ROWS_PER_WARP - 1) / ROWS_PER_WARP;
  const int blocks_needed = (warps_needed + WARPS_PER_BLOCK - 1) / WARPS_PER_BLOCK;

  sycl::range<2> grid_dim(1, blocks_needed);
  sycl::range<2> block_dim(WARPS_PER_BLOCK, WARP_SIZE);

  queue.submit([&](sycl::handler& cgh) {
    cgh.parallel_for(
        sycl::nd_range<2>(grid_dim * block_dim, block_dim),
        topkGatingSoftmaxKernel<
            VPT,
            NUM_EXPERTS,
            WARPS_PER_BLOCK,
            LOAD_SIZE,
            WARP_SIZE,
            InputType,
            IndexType>(
            input,
            row_mask,
            output,
            total_rows,
            indices,
            row_map,
            k,
            start_expert,
            end_expert,
            renormalize));
  });
}

#define LAUNCH_KERNEL(EXPERTS, WARPS, MAX_BYTES)                               \
  static_assert(                                                               \
      WARP_SZ == 32, "Only 32-thread warps supported on XPU");                 \
  launch_topk_gating<                                                          \
      EXPERTS,                                                                 \
      WARPS,                                                                   \
      WARP_SZ,                                                                 \
      MAX_BYTES>(                                                              \
      gating_data,                                                             \
      nullptr,                                                                 \
      topk_weights,                                                            \
      topk_indices,                                                            \
      token_expert_map,                                                        \
      num_tokens,                                                              \
      top_k,                                                                   \
      0,                                                                       \
      total_experts,                                                           \
      normalize,                                                               \
      queue);

template <typename InputType, typename IndexType>
void topkGatingSoftmaxLauncher(
    const InputType* gating_data,
    float* topk_weights,
    IndexType* topk_indices,
    int* token_expert_map,
    float* workspace,
    const int num_tokens,
    const int total_experts,
    const int top_k,
    const bool normalize,
    sycl::queue& queue) {
  static constexpr int WARPS_PER_TB = 4;
  static constexpr int POWER_OF_2_BYTES = 16;
  static constexpr int MULTIPLE_64_BYTES = 2 * sizeof(InputType);

  switch (total_experts) {
    case 1:
      LAUNCH_KERNEL(1, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 2:
      LAUNCH_KERNEL(2, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 4:
      LAUNCH_KERNEL(4, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 8:
      LAUNCH_KERNEL(8, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 16:
      LAUNCH_KERNEL(16, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 32:
      LAUNCH_KERNEL(32, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 64:
      LAUNCH_KERNEL(64, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 128:
      LAUNCH_KERNEL(128, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 256:
      LAUNCH_KERNEL(256, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 512:
      LAUNCH_KERNEL(512, WARPS_PER_TB, POWER_OF_2_BYTES);
      break;
    case 192:
    case 320:
    case 384:
    case 448:
    case 576:
      LAUNCH_KERNEL(total_experts, WARPS_PER_TB, MULTIPLE_64_BYTES);
      break;
    default: {
      TORCH_CHECK(
          workspace != nullptr,
          "Workspace required for non-power-of-2 or large expert counts.");
      static constexpr int TPB = 256;
      sycl::range<1> grid(num_tokens);
      sycl::range<1> block(TPB);

      queue.submit([&](sycl::handler& cgh) {
        sycl::local_accessor<float, 1> slm(sycl::range<1>(2), cgh);
        cgh.parallel_for(
            sycl::nd_range<1>(grid * block, block),
            moeSoftmaxKernel<TPB, InputType>(
                slm, gating_data, nullptr, workspace, total_experts));
      });

      queue.submit([&](sycl::handler& cgh) {
        cgh.parallel_for(
            sycl::nd_range<1>(grid * block, block),
            moeTopKSelector<TPB, IndexType>(
                workspace,
                nullptr,
                topk_weights,
                topk_indices,
                token_expert_map,
                total_experts,
                top_k,
                0,
                total_experts,
                normalize));
      });
    }
  }
}
