bool captureScreenRegionBgr(const RECT& region, cv::Mat* resultBgr, std::string* errorMsg) {
	if (resultBgr == nullptr) {
		setError(errorMsg, "output matrix pointer is null");
		return false;
	}
	resultBgr->release();

	const int w = region.right - region.left;
	const int h = region.bottom - region.top;

	if (w <= 0 || h <= 0 || w > 10000 || h > 10000) {
		std::ostringstream oss;
		oss << "invalid region dimensions: left=" << region.left
			<< ", top=" << region.top
			<< ", right=" << region.right
			<< ", bottom=" << region.bottom;
		setError(errorMsg, oss.str());
		return false;
	}

	HDC desktopDc = GetDC(nullptr);
	if (desktopDc == nullptr) {
		setError(errorMsg, formatWin32Error("GetDC", GetLastError()));
		return false;
	}

	HDC compatibleDc = CreateCompatibleDC(desktopDc);
	if (compatibleDc == nullptr) {
		setError(errorMsg, formatWin32Error("CreateCompatibleDC", GetLastError()));
		ReleaseDC(nullptr, desktopDc);
		return false;
	}

	HBITMAP bitmapHandle = CreateCompatibleBitmap(desktopDc, w, h);
	if (bitmapHandle == nullptr) {
		setError(errorMsg, formatWin32Error("CreateCompatibleBitmap", GetLastError()));
		DeleteDC(compatibleDc);
		ReleaseDC(nullptr, desktopDc);
		return false;
	}

	HGDIOBJ previousObject = SelectObject(compatibleDc, bitmapHandle);
	if (previousObject == nullptr || previousObject == HGDI_ERROR) {
		setError(errorMsg, formatWin32Error("SelectObject", GetLastError()));
		DeleteObject(bitmapHandle);
		DeleteDC(compatibleDc);
		ReleaseDC(nullptr, desktopDc);
		return false;
	}

	if (BitBlt(
		compatibleDc,
		0,
		0,
		w,
		h,
		desktopDc,
		region.left,
		region.top,
		SRCCOPY | CAPTUREBLT) == 0) {
		setError(errorMsg, formatWin32Error("BitBlt", GetLastError()));
		SelectObject(compatibleDc, previousObject);
		DeleteObject(bitmapHandle);
		DeleteDC(compatibleDc);
		ReleaseDC(nullptr, desktopDc);
		return false;
	}

	BITMAPINFOHEADER infoHeader{};
	infoHeader.biSize = sizeof(BITMAPINFOHEADER);
	infoHeader.biWidth = w;
	infoHeader.biHeight = -h;  // top-down orientation
	infoHeader.biPlanes = 1;
	infoHeader.biBitCount = 32;
	infoHeader.biCompression = BI_RGB;

	cv::Mat bgraImage(h, w, CV_8UC4);

	int readResult = GetDIBits(
		compatibleDc,
		bitmapHandle,
		0,
		static_cast<UINT>(h),
		bgraImage.data,
		reinterpret_cast<BITMAPINFO*>(&infoHeader),
		DIB_RGB_COLORS);

	SelectObject(compatibleDc, previousObject);
	DeleteObject(bitmapHandle);
	DeleteDC(compatibleDc);
	ReleaseDC(nullptr, desktopDc);

	if (readResult == 0) {
		setError(errorMsg, formatWin32Error("GetDIBits", GetLastError()));
		return false;
	}

	cv::cvtColor(bgraImage, *resultBgr, cv::COLOR_BGRA2BGR);

	if (resultBgr->empty()) {
		setError(errorMsg, "capture resulted in empty image");
		return false;
	}

	return true;
}

