#include "meta_ham/MoveRatingHistory.h"
#include "meta/FixedSizeSaveable.h"
#include "meta/FixedSizeSaveableStream.h"

void MoveRatingHistory::SaveFixed(FixedSizeSaveableStream &stream) const {
    int count = unk8.size();
    static int maxSize = 0x4000;
    if (count > 0x4000) {
        MILO_NOTIFY(
            "The move awards history size is greater than the maximum supplied! size=%i max=%i",
            count,
            maxSize
        );
        count = 0x4000;
    }
    stream.Tell();
    stream << count;
    FOREACH (iter, unk8) {
        FixedSizeSaveable::SaveSymbolID(stream, iter->first.unk0);
        for (int idx = 0; idx < 4; idx++) {
            stream << iter->second.unk0[idx];
        }
    }
    if (count < 0x4000) {
        FixedSizeSaveable::PadStream(stream, (0x4000 - count) * 20);
    }
    const_cast<MoveRatingHistory *>(this)->unk20 = false;
}

void MoveRatingHistory::LoadFixed(FixedSizeSaveableStream &stream, int param2) {
    if (unk8.size() > 0) {
        MILO_NOTIFY("Move award history map is not empty on load!");
        unk8.clear();
    }
    int loadedCount;
    stream >> loadedCount;
    for (int i = 0; i < loadedCount; i++) {
        Key tempKey;
        FixedSizeSaveable::LoadSymbolFromID(stream, tempKey.unk0);
        for (int j = 0; j < 4; j++) {
            stream >> (int &)unk8[tempKey].unk0[j];
        }
    }
    if (loadedCount < 0x4000) {
        FixedSizeSaveable::DepadStream(stream, (0x4000 - loadedCount) * 20);
    }
}

void MoveRatingHistory::Clear() {
    unk8.clear();
    unk20 = false;
}

int MoveRatingHistory::GetRating(Symbol sym, int index) {
    Key key;
    key.unk0 = sym;
    if (HasRatingHistory(key)) {
        return unk8[key].unk0[index];
    } else {
        return -1;
    }
}

int MoveRatingHistory::SaveSize(int) { return 0x50004; }

void MoveRatingHistory::AddHistory(Symbol sym, int rating) {
    Key key;
    key.unk0 = sym;
    RatingHistory &history = unk8[key];
    MoveRating prev = history.unk0[0];
    history.unk0[1] = prev;
    history.unk0[2] = prev;
    history.unk0[3] = prev;
    history.unk0[0] = (MoveRating)rating;
    unk20 = true;
}

#include <SavePlayerDataProcessor.h>
#include <google/protobuf/util/json_util.h>
#include <PlayerDatabase.h>
#include <PlayerData.pb.h>

// Marker indicating end of config JSON section
static const std::string configEndMarker = "\"inputBindingsVersion\": 3";

SavePlayerDataProcessor::SavePlayerDataProcessor(SpectreRpcType rpcType) 
    : WebsocketPacketProcessor(rpcType) {
}

void SavePlayerDataProcessor::HandleRequest(SpectreWebsocketRequest& request, SpectreWebsocket& socket) {
    const char* rawData = reinterpret_cast<const char*>(request.GetRawBuffer()->cdata().data());
    std::string formattedRequest = "{\"playerId\": \"" + socket.GetPlayerId() + "\",\"data\":";

    size_t pos = 0;
    char currentChar;

    // Skip until we find the opening brace after the first quote
    for (; pos < request.GetRawBuffer()->size(); ++pos) {
        currentChar = rawData[pos];
        if (currentChar == '\"' && rawData[pos + 1] == '{') {
            ++pos; // skip leading quote before data object
            break;
        }
    }

    // Process characters inside the data object, handling escapes and detecting end marker
    for (; pos < request.GetRawBuffer()->size(); ++pos) {
        currentChar = rawData[pos];
        if (currentChar == '\\') {
            if (rawData[pos + 1] == '\"') {
                formattedRequest += '\"';
            }
            ++pos;
        }
        else if (currentChar == '}') {
            // Check if this closing brace ends with the expected config version marker
            if (formattedRequest.size() >= configEndMarker.size() &&
                formattedRequest.compare(formattedRequest.size() - configEndMarker.size(), 
                                         configEndMarker.size(), 
                                         configEndMarker.c_str()) == 0) {
                formattedRequest += currentChar;
                pos += 2;
                break;
            } else {
                formattedRequest += currentChar;
            }
        }
        else {
            formattedRequest += currentChar;
        }
    }

    // Append remaining bytes (likely trailing quote and padding)
    for (; pos < request.GetRawBuffer()->size() - 1; ++pos) {
        formattedRequest += rawData[pos];
    }

    PlayerData playerData;
    auto parseStatus = pbuf::util::JsonStringToMessage(formattedRequest, &playerData);
    if (!parseStatus.ok()) {
        spdlog::error("Failed to parse PlayerConfigData in SavePlayerDataProcessor: {}", parseStatus.message());
        throw;
    }

    // Handle case where only 'data' field is populated (common in client updates)
    if (playerData.attackeroutfitloadoutid().empty()) {
        // Preserve existing fields except 'data'
        std::unique_ptr<PlayerData> storedData = PlayerDatabase::Get().GetField<PlayerData>(FieldKey::PLAYER_DATA, socket.GetPlayerId());
        storedData->mutable_data()->CopyFrom(playerData.data());
        PlayerDatabase::Get().SetField(FieldKey::PLAYER_DATA, storedData.get(), socket.GetPlayerId());
    }
    else {
        spdlog::warn("Unexpected attacker outfit loadout ID set in SetPlayerData request from {}, may cause issues", socket.GetPlayerId());
        PlayerDatabase::Get().SetField(FieldKey::PLAYER_DATA, &playerData, socket.GetPlayerId());
    }

    // Send success response
    std::shared_ptr<json> response = request.GetBaseJsonResponse();
    (*response)["payload"]["success"] = true;
    socket.SendPacket(response);
}

