#include "yaml-cpp/yaml.h"
#include <iostream>

int main() {
    {
        // sample.yaml content simulation
        // - bar
        // - evens: [2, 4, 6, 8]
        //   squares: [1, 4, 9, 16]
        // - [a, b]
        YAML::Value document = YAML::Parse("sample.yaml");
        std::cout << document[0].as<std::string>();       // "bar"
        std::cout << str(document[0]);                    // "bar"
        std::cout << document[1]["evens"][2].as<int>();   // "6"
        std::cout << document[1]["squares"][3].as<int>(); // "16"
        document[2].push_back(7);
        document[3] = "Greetings";
        document[0].reset();
        document[0]["name"] = "data";
        std::cout << document;
    }

    {
        // value assignment semantics similar to Python
        YAML::Value data = "Welcome";     // "Welcome"
        data = YAML::Sequence();          // []
        data[0] = 10;                     // [10]
        data[2] = "three";                // [10, ~, three]
        YAML::Value alias = data;         // alias points to same object as data
        alias[0] = 20;                    // now data[0] is also 20
        alias.push_back(data);            // &1 [20, ~, three, *1]
        alias[3][1] = nullptr;            // &1 [20, ~, three, *1]
        alias.push_back(Copy(data));      // &1 [20, ~, three, *1, &2 [20, ~, three, *2]]
        alias[4][2] = "new";              // independent copy modified
    }

    {
        YAML::Value container;           // ~
        container[0] = 5;                // [5]
        container["id"] = 100;           // {0: 5, id: 100}
        container.push_back(200);        // error: cannot convert map to sequence
        container.erase("id");           // {0: 5}
        container = "Final";             // "Final"
    }

    {
        YAML::Value mapping;             // ~
        mapping[1] = 10;                 // {1: 10}
        YAML::Value list;                // ~
        list = YAML::Sequence();         // []
        list[1] = 20;                    // [~, 20]
    }

    {
        YAML::Value selfRef;             // ~
        selfRef[0] = selfRef;            // &1 [*1]
    }

    {
        YAML::Value parent;
        YAML::Value child = parent["field"]; // child not yet instantiated
        child = "active";                   // {field: active}
        YAML::Value peer = parent["other"];
        parent["third"] = peer;             // peer still null, but aliased
        peer = "value";                     // instantiates both 'other' and 'third'
    }

    {
        YAML::Value items = YAML::Sequence();
        items[0] = "first";               // ["first"]
        items[1] = items[0];              // [&1 first, *1]
        items[0] = items[1];              // no change (same reference)
        Is(items[0], items[1]);           // true
        items[1] = "second";              // [&1 second, *1]
        UnAlias(items[1]);                // ["second", "second"]
        Is(items[0], items[1]);           // false
    }

    {
        YAML::Value base;
        base.push_back("start");
        base.push_back("middle");
        base.push_back("end");
        YAML::Value last = base[2];
        base = "changed";                 // 'last' remains "end"
    }

    {
        YAML::Value root;                 // ~
        root[0] = root;                   // &1 [*1]
        root[0] = 42;                     // [42]
    }

    {
        YAML::Value root;
        YAML::Value keyNode;
        keyNode["title"] = "entry";
        root[keyNode] = keyNode;          // &1 {title: entry}: *1
    }

    {
        YAML::Value root;
        root[0] = "hello";
        root[1][0] = "goodbye";
        root[1][1] = root;                // &1 [hello, [goodbye, *1]]
        YAML::Value part = root[1];       // part references inner sequence
        root = "over";                    // part still holds [goodbye, over]
    }

    return 0;
}

