BookmarkListItem::BookmarkListItem() {}

BookmarkListItem::BookmarkListItem(World& w, const BookmarkCompleteUndoData& undoInfo) {
    nameData = w.netObjMan.make_obj<NameData>();
    nameData->name = undoInfo.name;
    if(undoInfo.folderList) {
        auto& srcFolderList = undoInfo.folderList.value();
        folderData = std::make_unique<BookmarkFolderData>();
        folderData->folderList = w.netObjMan.make_obj<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>();
        for(auto& srcItem : srcFolderList) {
            auto it = folderData->folderList->emplace_back_direct(folderData->folderList, w, srcItem);
            w.undo.register_new_netid_to_existing_undoid(srcItem.undoID, it->obj.get_net_id());
        }
    }
    else
        bookmarkData = std::make_unique<BookmarkData>(undoInfo.bookmarkData.value());
}

BookmarkListItem::BookmarkListItem(NetworkingObjects::NetObjManager& netObjMan, const std::string& label, bool isFolderType, const BookmarkData& initialBookmarkData) {
    if(isFolderType) {
        folderData = std::make_unique<BookmarkFolderData>();
        folderData->folderList = netObjMan.make_obj<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>();
    }
    else
        bookmarkData = std::make_unique<BookmarkData>(initialBookmarkData);
    nameData = netObjMan.make_obj<NameData>();
    nameData->name = label;
}

BookmarkCompleteUndoData BookmarkListItem::extract_complete_undo_info(WorldUndoManager& u) {
    BookmarkCompleteUndoData result;
    result.name = nameData->name;
    if(folderData) {
        result.folderList = std::vector<BookmarkCompleteUndoData>();
        auto& destFolderList = result.folderList.value();
        for(auto& b : *folderData->folderList) {
            destFolderList.emplace_back(b.obj->extract_complete_undo_info(u));
            destFolderList.back().undoID = u.get_undoid_from_netid(b.obj.get_net_id());
        }
    }
    else
        result.bookmarkData = *bookmarkData;
    return result;
}

void BookmarkListItem::remap_netobj_handles() {
    if(folderData)
        folderData->folderList.reassign_ids();
    nameData.reassign_ids();
}

void BookmarkListItem::adjust_scale(const WorldScalar& scaleFactor) {
    if(folderData) {
        for(auto& item : *folderData->folderList)
            item.obj->adjust_scale(scaleFactor);
    }
    else
