void BookmarkListItem::bind_class(World& w) {
    auto deserializeConstructor = [&w](const NetworkingObjects::NetObjTemporaryPtr<BookmarkListItem>& o, cereal::PortableBinaryInputArchive& a, const std::shared_ptr<NetServer::ClientData>& c) {
        bool isFolder;
        a(isFolder);
        if(isFolder) {
            o->folderData = std::make_unique<BookmarkFolderData>();
            o->folderData->folderList = o.get_obj_man()->read_create_message<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>(a, c);
        }
        else {
            o->bookmarkData = std::make_unique<BookmarkData>();
            a(*o->bookmarkData);
        }
        o->nameData = o.get_obj_man()->read_create_message<NameData>(a, c);
        canvas_scale_up_check(*o, w, c);
    };
    w.netObjMan.register_class<BookmarkListItem, BookmarkListItem, BookmarkListItem, BookmarkListItem>({
        .writeConstructorFuncClient = serialize_constructor,
        .readConstructorFuncClient = deserializeConstructor,
        .readUpdateFuncClient = nullptr,
        .writeConstructorFuncServer = serialize_constructor,
        .readConstructorFuncServer = deserializeConstructor,
        .readUpdateFuncServer = nullptr
    });
    NetworkingObjects::register_ordered_list_class<BookmarkListItem>(w.netObjMan);
    w.delayedUpdateObjectManager.register_class<NameData>(w.netObjMan);
}

void BookmarkListItem::serialize_constructor(const NetObjTemporaryPtr<BookmarkListItem>& o, cereal::PortableBinaryOutputArchive& a) {
    a(o->is_folder_type());
    if(o->is_folder_type())
        o->folderData->folderList.write_create_message(a);
    else
        a(*o->bookmarkData);
    o->nameData.write_create_message(a);
}

void BookmarkListItem::store_to_file(cereal::PortableBinaryOutputArchive& a) const {
    a(*nameData);
    a(static_cast<bool>(folderData));
    if(folderData) {
        a(folderData->folderList->size());
        for(auto& entry : *folderData->folderList)
            entry.obj->store_to_file(a);
    }
    else
        a(*bookmarkData);
}

void BookmarkListItem::restore_from_file(cereal::PortableBinaryInputArchive& a, VersionNumber version, BookmarkManager& bMan) {
    nameData = bMan.world.netObjMan.make_obj<NameData>();
    a(*nameData);
    bool isFolder;
    a(isFolder);
    if(isFolder) {
        folderData = std::make_unique<BookmarkFolderData>();
        folderData->folderList = bMan.world.netObjMan.make_obj<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>();
        uint32_t folderCount;
        a(folderCount);
        for(uint32_t idx = 0; idx < folderCount; idx++) {
            BookmarkListItem* newItem = new BookmarkListItem;
            newItem->restore_from_file(a, version, bMan);
            folderData->folderList->push_back_and_send_create(folderData->folderList, newItem);
        }
    }
    else {
        bookmarkData = std::make_unique<BookmarkData>();
        a(*bookmarkData);
    }
}

#include <torch/all.h>
#include "ATen/ATen.h"
#include <torch/library.h>
#include "registration.h"

typedef at::BFloat16 bf16;

// CUDA kernel declarations
void cuda_forward(int batch, int seq_len, int channels, float *w, float *u, float *k, float *v, float *y);
void cuda_forward_bf16(int batch, int seq_len, int channels, float *w, bf16 *u, bf16 *k, bf16 *v, bf16 *y);
void cuda_forward_with_state(int batch, int seq_len, int channels, float *w, float *u, float *k, float *v, float *y, float *state);
void cuda_forward_with_state_bf16(int batch, int seq_len, int channels, float *w, bf16 *u, bf16 *k, bf16 *v, bf16 *y, float *state);
void cuda_backward(int batch, int seq_len, int channels, float *w, float *u, float *k, float *v, float *y, float *gy, float *gw, float *gu, float *gk, float *gv);
void cuda_backward_bf16(int batch, int seq_len, int channels, float *w, bf16 *u, bf16 *k, bf16 *v, bf16 *y, bf16 *gy, bf16 *gw, bf16 *gu, bf16 *gk, bf16 *gv);

// FP32 forward implementation
void forward(torch::Tensor &weight, torch::Tensor &update, torch::Tensor &key, torch::Tensor &value, torch::Tensor &output) {
    const int batch = key.size(0);
    const int seq_len = key.size(1);
    const int channels = key.size(2);
    cuda_forward(batch, seq_len, channels,
                 weight.data_ptr<float>(),
                 update.data_ptr<float>(),
                 key.data_ptr<float>(),
                 value.data_ptr<float>(),
                 output.data_ptr<float>());
}

// BF16 forward implementation
void forward_bf16(torch::Tensor &weight, torch::Tensor &update, torch::Tensor &key, torch::Tensor &value, torch::Tensor &output) {
    const int batch = key.size(0);
    const int seq_len = key.size(1);
    const int channels = key.size(2);
    cuda_forward_bf16(batch, seq_len, channels,
                      weight.data_ptr<float>(),
                      update.data_ptr<bf16>(),
                      key.data_ptr<bf16>(),
                      value.data_ptr<bf16>(),
                      output.data_ptr<bf16>());
}

// FP32 forward with state implementation
void forward_with_state(torch::Tensor &weight, torch::Tensor &update, torch::Tensor &key, torch::Tensor &value, torch::Tensor &output, torch::Tensor &state) {
    const int batch = key.size(0);
    const int seq_len = key.size(1);
    const int channels = key.size(2);
    cuda_forward_with_state(batch, seq_len, channels,
                            weight.data_ptr<float>(),
                            update.data_ptr<float>(),
                            key.data_ptr<float>(),
                            value.data_ptr<float>(),
                            output.data_ptr<float>(),
                            state.data_ptr<float>());
}

// BF16 forward with state implementation
void forward_with_state_bf16(torch::Tensor &weight, torch::Tensor &update, torch::Tensor &key, torch::Tensor &value, torch::Tensor &output, torch::Tensor &state) {
    const int batch = key.size(0);
    const int seq_len = key.size(1);
    const int channels = key.size(2);
    cuda_forward_with_state_bf16(batch, seq_len, channels,
                                 weight.data_ptr<float>(),
                                 update.data_ptr<bf16>(),
                                 key.data_ptr<bf16>(),
                                 value.data_ptr<bf16>(),
                                 output.data_ptr<bf16>(),
                                 state.data_ptr<float>());
}

// FP32 backward implementation
void backward(torch::Tensor &weight, torch::Tensor &update, torch::Tensor &key, torch::Tensor &value, torch::Tensor &output,
              torch::Tensor &grad_output, torch::Tensor &grad_weight, torch::Tensor &grad_update,
              torch::Tensor &grad_key, torch::Tensor &grad_value) {
    const int batch = key.size(0);
    const int seq_len = key.size(1);
    const int channels = key.size(2);
    cuda_backward(batch, seq_len, channels,
                  weight.data_ptr<float>(),
                  update.data_ptr<float>(),
                  key.data_ptr<float>(),
                  value.data_ptr<float>(),
                  output.data_ptr<float>(),
                  grad_output.data_ptr<float>(),
                  grad_weight.data_ptr<float>(),
                  grad_update.data_ptr<float>(),
                  grad_key.data_ptr<float>(),
                  grad_value.data_ptr<float>());
}

// BF16 backward implementation
void backward_bf16(torch::Tensor &weight, torch::Tensor &update, torch::Tensor &key, torch::Tensor &value, torch::Tensor &output,
                   torch::Tensor &grad_output, torch::Tensor &grad_weight, torch::Tensor &grad_update,
                   torch::Tensor &grad_key, torch::Tensor &grad_value) {
    const int batch = key.size(0);
    const int seq_len = key.size(1);
    const int channels = key.size(2);
    cuda_backward_bf16(batch, seq_len, channels,
                       weight.data_ptr<float>(),
                       update.data_ptr<bf16>(),
                       key.data_ptr<bf16>(),
                       value.data_ptr<bf16>(),
                       output.data_ptr<bf16>(),
                       grad_output.data_ptr<bf16>(),
                       grad_weight.data_ptr<bf16>(),
                       grad_update.data_ptr<bf16>(),
                       grad_key.data_ptr<bf16>(),
                       grad_value.data_ptr<bf16>());
}

// Register operators with Torch
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, ops) {
    ops.def("forward", forward);
    ops.impl("forward", torch::kCUDA, &forward);

    ops.def("forward_bf16", forward_bf16);
    ops.impl("forward_bf16", torch::kCUDA, &forward_bf16);

    ops.def("forward_with_state", forward_with_state);
    ops.impl("forward_with_state", torch::kCUDA, &forward_with_state);

    ops.def("forward_with_state_bf16", forward_with_state_bf16);
    ops.impl("forward_with_state_bf16", torch::kCUDA, &forward_with_state_bf16);

    ops.def("backward", backward);
    ops.impl("backward", torch::kCUDA, &backward);

    ops.def("backward_bf16", backward_bf16);
    ops.impl("backward_bf16", torch::kCUDA, &backward_bf16);
}

REGISTER_EXTENSION(TORCH_EXTENSION_NAME)

#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MAX_SIZE = 2005;
const int64 MAX_QUERIES = 50000;
int grid_size;
int64 target_rank;
int64 value_cache[MAX_SIZE][MAX_SIZE];
bool is_cached[MAX_SIZE][MAX_SIZE];
bool visited[MAX_SIZE][MAX_SIZE];
int64 query_count = 0;

int64 fetch_value(int row, int col) {
    if (!is_cached[row][col]) {
        cout << "QUERY " << row << " " << col << endl;
        cout.flush();
        int64 val;
        if (!(cin >> val)) {
            exit(0);
        }
        value_cache[row][col] = val;
        is_cached[row][col] = true;
        ++query_count;
    }
    return value_cache[row][col];
}

void full_scan_solution() {
    vector<int64> all_values;
    all_values.reserve(grid_size * grid_size);
    for (int r = 1; r <= grid_size; ++r) {
        for (int c = 1; c <= grid_size; ++c) {
            all_values.push_back(fetch_value(r, c));
        }
    }
    nth_element(all_values.begin(), all_values.begin() + target_rank - 1, all_values.end());
    int64 result = all_values[target_rank - 1];
    cout << "DONE " << result << endl;
    cout.flush();
}

void small_k_bfs() {
    struct Cell {
        int64 val;
        int x, y;
    };
    struct MinHeapCompare {
        bool operator()(const Cell& a, const Cell& b) const {
            return a.val > b.val;
        }
    };

    memset(visited, 0, sizeof(visited));
    priority_queue<Cell, vector<Cell>, MinHeapCompare> heap;
    visited[1][1] = true;
    int64 first_val = fetch_value(1, 1);
    heap.push({first_val, 1, 1});

    int64 processed = 0;
    int64 answer = first_val;

    while (!heap.empty()) {
        Cell current = heap.top();
        heap.pop();
        ++processed;

        if (processed == target_rank) {
            answer = current.val;
            break;
        }

        int r = current.x;
        int c = current.y;

        if (r + 1 <= grid_size && !visited[r + 1][c]) {
            visited[r + 1][c] = true;
            int64 next_val = fetch_value(r + 1, c);
            heap.push({next_val, r + 1, c});
        }

        if (c + 1 <= grid_size && !visited[r][c + 1]) {
            visited[r][c + 1] = true;
            int64 next_val = fetch_value(r, c + 1);
            heap.push({next_val, r, c + 1});
        }
    }

    cout << "DONE " << answer << endl;
    cout.flush();
}

void large_k_bfs() {
    struct Cell {
        int64 val;
        int x, y;
    };
    struct MaxHeapCompare {
        bool operator()(const Cell& a, const Cell& b) const {
            return a.val < b.val;
        }
    };

    memset(visited, 0, sizeof(visited));
    priority_queue<Cell, vector<Cell>, MaxHeapCompare> heap;
    visited[grid_size][grid_size] = true;
    int64 last_val = fetch_value(grid_size, grid_size);
    heap.push({last_val, grid_size, grid_size});

    int64 total = 1LL * grid_size * grid_size;
    int64 rank_from_end = total - target_rank + 1;
    int64 processed = 0;
    int64 answer = last_val;

    while (!heap.empty()) {
        Cell current = heap.top();
        heap.pop();
        ++processed;

        if (processed == rank_from_end) {
            answer = current.val;
            break;
        }

        int r = current.x;
        int c = current.y;

        if (r - 1 >= 1 && !visited[r - 1][c]) {
            visited[r - 1][c] = true;
            int64 next_val = fetch_value(r - 1, c);
            heap.push({next_val, r - 1, c});
        }

        if (c - 1 >= 1 && !visited[r][c - 1]) {
            visited[r][c - 1] = true;
            int64 next_val = fetch_value(r, c - 1);
            heap.push({next_val, r, c - 1});
        }
    }

    cout << "DONE " << answer << endl;
    cout.flush();
}

int64 count_less_or_equal(int64 threshold) {
    int row = grid_size;
    int col = 1;
    int64 count = 0;

    while (row >= 1 && col <= grid_size) {
        int64 val = fetch_value(row, col);
        if (val <= threshold) {
            count += row;
            ++col;
        } else {
            --row;
        }
    }
    return count;
}

void binary_search_solution() {
    int64 min_val = fetch_value(1, 1);
    int64 max_val = fetch_value(grid_size, grid_size);

    int64 low = min_val;
    int64 high = max_val;
    int64 remaining_queries = MAX_QUERIES - query_count;

    int max_iterations = 0;
    if (2 * grid_size > 0) {
        max_iterations = static_cast<int>(remaining_queries / (2 * static_cast<int64>(grid_size)));
    }
    if (max_iterations > 60) max_iterations = 60;

    while (low < high && max_iterations > 0) {
        int64 mid = low + (high - low) / 2;
        int64 cnt = count_less_or_equal(mid);

        if (cnt >= target_rank) {
            high = mid;
        } else {
            low = mid + 1;
        }
        --max_iterations;
    }

    cout << "DONE " << low << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> grid_size >> target_rank)) {
        return 0;
    }

    int64 total_elements = 1LL * grid_size * grid_size;

    if (total_elements <= MAX_QUERIES) {
        full_scan_solution();
    } else {
        int64 forward_cost = target_rank;
        int64 backward_cost = total_elements - target_rank + 1;
        int64 cheaper_side = min(forward_cost, backward_cost);

        if (2 * cheaper_side <= MAX_QUERIES) {
            if (forward_cost <= backward_cost) {
                small_k_bfs();
            } else {
                large_k_bfs();
            }
        } else {
            binary_search_solution();
        }
    }

    return 0;
}

