    //////////////////////////////////////////////////
    class GazeboSimROS2ControlPluginPrivate
    {
    public:
        /// \brief Retrieve URDF XML from the ROS parameter server
        std::string fetchURDF() const;
        /// \brief Retrieve a collection of enabled, unique, single-axis joints from the model.
        /// If no joint names are specified in plugin configuration, all valid 1-axis joints are returned.
        /// \param[in] _modelEntity Entity representing the model
        /// \param[in] _ecm Gazebo Entity Component Manager
        /// \return Map of joint names to entities for all enabled joints
        std::map<std::string, sim::Entity> obtainEnabledJoints(
            const sim::Entity& _modelEntity,
            sim::EntityComponentManager& _ecm) const;

        /// \brief Store the entity ID for this sensor within Gazebo
        sim::Entity entity_id_;

        /// \brief ROS2 node handle
        std::shared_ptr<rclcpp::Node> ros_node_{nullptr};

        /// \brief Thread for running the executor
        std::thread executor_thread_;

        /// \brief Executor used to spin the controller
        rclcpp::executors::MultiThreadedExecutor::SharedPtr executor_spin_;

        /// \brief Control timing information
        rclcpp::Duration control_interval_ = rclcpp::Duration(1, 0);

        /// \brief Hardware interface loader
        std::shared_ptr<pluginlib::ClassLoader<
            gz_ros2_control::GazeboSimSystemInterface>>
        hardware_sim_loader_{nullptr};

        /// \brief Controller manager instance
        std::shared_ptr<controller_manager::ControllerManager>
        controller_instance_{nullptr};

        /// \brief Parameter name for robot description
        std::string robot_description_param_ = "robot_description";

        /// \brief Node name that holds the robot description
        std::string robot_description_node_name_ = "robot_state_publisher";

        /// \brief Timestamp of last update
        rclcpp::Time last_simulation_update_time_ =
            rclcpp::Time(static_cast<int64_t>(0), RCL_ROS_TIME);

        /// \brief Pointer to Entity Component Manager
        sim::EntityComponentManager* ecm_pointer{nullptr};

        /// \brief Update rate for controller
        int control_update_rate;
    };

    //////////////////////////////////////////////////
    std::map<std::string, sim::Entity>
    GazeboSimROS2ControlPluginPrivate::obtainEnabledJoints(
        const sim::Entity& _modelEntity,
        sim::EntityComponentManager& _ecm) const
    {
        std::map<std::string, sim::Entity> result_map;
        std::vector<std::string> active_joint_names;

        // Get all available joints
        auto joint_entities = _ecm.ChildrenByComponents(_modelEntity, sim::components::Joint());

        // Iterate over all joints and verify whether they can be enabled or not
        for (const auto& joint_entity : joint_entities)
        {
            const auto joint_name = _ecm.Component<sim::components::Name>(
                joint_entity)->Data();

            // Check if joint type is supported (exactly one actuated axis)
            const auto* joint_type_component = _ecm.Component<sim::components::JointType>(joint_entity);
            switch (joint_type_component->Data())
            {
            case sdf::JointType::PRISMATIC:
            case sdf::JointType::REVOLUTE:
            case sdf::JointType::CONTINUOUS:
            case sdf::JointType::GEARBOX:
                {
                    // Supported joint type - include it
                    break;
                }
            case sdf::JointType::FIXED:
                {
                    RCLCPP_INFO(
                        ros_node_->get_logger(),
                        "[gz_ros2_control] Fixed joint [%s] (Entity=%lu)] is skipped",
                        joint_name.c_str(), joint_entity);
                    continue;
                }
            case sdf::JointType::REVOLUTE2:
            case sdf::JointType::SCREW:
            case sdf::JointType::BALL:
            case sdf::JointType::UNIVERSAL:
                {
                    RCLCPP_WARN(
                        ros_node_->get_logger(),
                        "[gz_ros2_control] Joint [%s] (Entity=%lu)] is of unsupported type."
                        " Only joints with a single axis are supported.",
                        joint_name.c_str(), joint_entity);
                    continue;
                }
            default:
                {
                    RCLCPP_WARN(
                        ros_node_->get_logger(),
                        "[gz_ros2_control] Joint [%s] (Entity=%lu)] is of unknown type",
                        joint_name.c_str(), joint_entity);
                    continue;
                }
            }
            result_map[joint_name] = joint_entity;
        }
        return result_map;
    }

    //////////////////////////////////////////////////
    std::string GazeboSimROS2ControlPluginPrivate::fetchURDF() const
    {
        std::string urdf_data;
        using namespace std::chrono_literals;

        auto parameters_client = std::make_shared<rclcpp::AsyncParametersClient>(
            ros_node_, robot_description_node_name_);

        while (!parameters_client->wait_for_service(0.5s))
        {
            if (!rclcpp::ok())
            {
                RCLCPP_ERROR(
                    ros_node_->get_logger(), "Interrupted while waiting for %s service. Exiting.",
                    robot_description_node_name_.c_str());
                return "";
            }
            RCLCPP_ERROR(
                ros_node_->get_logger(), "%s service not available, waiting again...",
                robot_description_node_name_.c_str());
        }

        RCLCPP_INFO(
            ros_node_->get_logger(), "connected to service!! %s asking for %s",
            robot_description_node_name_.c_str(),
            this->robot_description_param_.c_str());

        // Wait for robot description on param server
        while (urdf_data.empty())
        {
            RCLCPP_DEBUG(
                ros_node_->get_logger(), "param_name %s",
                this->robot_description_param_.c_str());
            try
            {
                auto future_result = parameters_client->get_parameters({this->robot_description_param_});
                future_result.wait();
                const std::vector<rclcpp::Parameter>& values = future_result.get();
                urdf_data = values[0].as_string();
            }
            catch (const std::exception& e)
            {
                RCLCPP_ERROR(ros_node_->get_logger(), "%s", e.what());
            }

            if (!urdf_data.empty())
            {
                break;
            }

            RCLCPP_ERROR(
                ros_node_->get_logger(), "gz_ros2_control plugin is waiting for model"
                " URDF in parameter [%s] on the ROS param server.",
                this->robot_description_param_.c_str());

            std::this_thread::sleep_for(std::chrono::microseconds(100000));
        }

        RCLCPP_INFO(ros_node_->get_logger(), "Received URDF from param server");
        return urdf_data;
    }

    //////////////////////////////////////////////////
    GazeboSimROS2ControlPlugin::GazeboSimROS2ControlPlugin()
        : dataPtr(std::make_unique<GazeboSimROS2ControlPluginPrivate>())
    {
    }

    //////////////////////////////////////////////////
    GazeboSimROS2ControlPlugin::~GazeboSimROS2ControlPlugin()
    {
        // Stop controller manager thread
        if (!this->dataPtr->controller_instance_)
        {
            return;
        }

        this->dataPtr->executor_spin_->remove_node(this->dataPtr->controller_instance_);
        this->dataPtr->executor_spin_->cancel();
        this->dataPtr->executor_thread_.join();
    }

    //////////////////////////////////////////////////
    void GazeboSimROS2ControlPlugin::Configure(
        const sim::Entity& _entity,
        const std::shared_ptr<const sdf::Element>& _sdf,
        sim::EntityComponentManager& _ecm,
        sim::EventManager&)
    {
        rclcpp::Logger logger = rclcpp::get_logger("GazeboSimROS2ControlPlugin");

        // Ensure the controller is attached to a valid model
        const auto model = sim::Model(_entity);
        if (!model.Valid(_ecm))
        {
            RCLCPP_ERROR(
                logger,
                "[gz_ros2_control] Failed to initialize because [%s] (Entity=%lu)] is not a model."
                "Please make sure that gz_ros2_control is attached to a valid model.",
                model.Name(_ecm).c_str(), _entity);
            return;
        }

        // Get parameters from SDF
        auto paramFileName = _sdf->Get<std::string>("parameters");
        if (paramFileName.empty())
        {
            RCLCPP_ERROR(
                logger,
                "gz_ros2_control found an empty parameters file. Failed to initialize.");
            return;
        }

        // Get optional robot_param_node parameter
        auto robot_param_node = _sdf->Get<std::string>("robot_param_node");
        if (!robot_param_node.empty())
        {
            this->dataPtr->robot_description_node_name_ = robot_param_node;
        }

        RCLCPP_INFO(
            logger,
            "robot_param_node is %s", this->dataPtr->robot_description_node_name_.c_str());

        // Get optional robot_param parameter
        auto robot_description = _sdf->Get<std::string>("robot_param");
        if (!robot_description.empty())
        {
            this->dataPtr->robot_description_param_ = robot_description;
        }

        RCLCPP_INFO(
            logger,
            "robot_param is %s", this->dataPtr->robot_description_param_.c_str());

        // Build command line arguments
        std::vector<std::string> arguments = {"--ros-args"};
        auto sdfPtr = const_cast<sdf::Element*>(_sdf.get());
        sdf::ElementPtr argument_sdf = sdfPtr->GetElement("parameters");

        while (argument_sdf)
        {
            auto argument = argument_sdf->Get<std::string>();
            arguments.emplace_back(RCL_PARAM_FILE_FLAG);
            arguments.push_back(argument);
            argument_sdf = argument_sdf->GetNextElement("parameters");
        }

        // Get controller manager node name
        std::string controller_manager_node_name{"controller_manager"};
        if (sdfPtr->HasElement("controller_manager_name"))
        {
            controller_manager_node_name = sdfPtr->GetElement("controller_manager_name")->Get<std::string>();
        }

        // Handle namespace
        std::string ns = "/";
        if (sdfPtr->HasElement("ros"))
        {
            sdf::ElementPtr sdfRos = sdfPtr->GetElement("ros");
            // Set namespace if tag is present
            if (sdfRos->HasElement("namespace"))
            {
                ns = sdfRos->GetElement("namespace")->Get<std::string>();
                // Ensure namespace is absolute
                if (ns.empty() || ns[0] != '/')
                {
                    ns = '/' + ns;
                }
                if (ns.length() > 1)
                {
                    this->dataPtr->robot_description_node_name_ = ns + "/" + this->dataPtr->robot_description_node_name_;
                }
            }

            // Process remapping rules from SDF
            if (sdfRos->HasElement("remapping"))
            {
                sdf::ElementPtr argument_sdf = sdfRos->GetElement("remapping");
                arguments.emplace_back(RCL_ROS_ARGS_FLAG);
                while (argument_sdf)
                {
                    auto argument = argument_sdf->Get<std::string>();
                    arguments.emplace_back(RCL_REMAP_FLAG);
                    arguments.push_back(argument);
                    argument_sdf = argument_sdf->GetNextElement("remapping");
                }
            }
        }

        // Initialize ROS2 context if needed
        if (!rclcpp::ok())
        {
            RCLCPP_DEBUG_STREAM(logger, "Create default context");
            std::vector<const char*> argv;
            rclcpp::init(static_cast<int>(argv.size()), argv.data());
        }

        // Create node and executor
        std::string node_name = "gz_ros2_control";
        this->dataPtr->ros_node_ = rclcpp::Node::make_shared(node_name, ns);
        this->dataPtr->executor_spin_ = std::make_shared<rclcpp::executors::MultiThreadedExecutor>();
        this->dataPtr->executor_spin_->add_node(this->dataPtr->ros_node_);

        auto spin_function = [this]()
        {
            this->dataPtr->executor_spin_->spin();
        };
        this->dataPtr->executor_thread_ = std::thread(spin_function);

        RCLCPP_DEBUG_STREAM(logger, "Created node " << node_name);

        // Fetch URDF from parameter server
        const auto urdf_string = this->dataPtr->fetchURDF();
        if (urdf_string.empty())
        {
            RCLCPP_ERROR_STREAM(this->dataPtr->ros_node_->get_logger(), "An empty URDF was passed. Exiting.");
            return;
        }

        // Clean comments from URDF
        const std::regex comment_pattern(R"(<!--[\s\S]*?-->)");
        const auto rb_arg = std::string("robot_description:=") + std::regex_replace(
            urdf_string,
            comment_pattern, "");

        arguments.emplace_back(RCL_PARAM_FLAG);
        arguments.push_back(rb_arg);

        // Prepare arguments for rcl
        std::vector<const char*> argv;
        argv.reserve(arguments.size());
        for (const auto& arg : arguments)
        {
            argv.push_back(arg.data());
        }

        // Set arguments into rcl context
        rcl_arguments_t rcl_args = rcl_get_zero_initialized_arguments();
        rcl_ret_t rcl_ret = rcl_parse_arguments(
            static_cast<int>(argv.size()),
            argv.data(), rcl_get_default_allocator(), &rcl_args);

        auto rcl_context =
            this->dataPtr->ros_node_->get_node_base_interface()->get_context()->get_rcl_context();
        rcl_context->global_arguments = rcl_args;

        if (rcl_ret != RCL_RET_OK)
        {
            RCLCPP_ERROR_STREAM(
                this->dataPtr->ros_node_->get_logger(), "Argument parser error: " << rcl_get_error_string().str);
            rcl_reset_error();
            return;
        }

        if (rcl_arguments_get_param_files_count(&rcl_args) < 1)
        {
            RCLCPP_ERROR(this->dataPtr->ros_node_->get_logger(), "Failed to parse input yaml file(s)");
            return;
        }

        RCLCPP_DEBUG_STREAM(
            this->dataPtr->ros_node_->get_logger(), "[gz_ros2_control] Setting up controller for [" <<
            model.Name(_ecm) << "] (Entity=" << _entity << ")].");

        // Get list of enabled joints
        auto enabled_joints = this->dataPtr->obtainEnabledJoints(
            _entity,
            _ecm);

        if (enabled_joints.empty())
        {
            RCLCPP_DEBUG_STREAM(
                this->dataPtr->ros_node_->get_logger(),
                "[gz_ros2_control] There are no available Joints.");
            return;
        }

        // Parse URDF and setup resources
        std::vector<hardware_interface::HardwareInfo> control_hardware_info;
        try
        {
            control_hardware_info = hardware_interface::parse_control_resources_from_urdf(urdf_string);
        }
        catch (const std::runtime_error& ex)
        {
            RCLCPP_ERROR_STREAM(
                this->dataPtr->ros_node_->get_logger(),
                "Error parsing URDF in gz_ros2_control plugin, plugin not active : " << ex.what());
            return;
        }

        auto resource_manager_ = std::make_unique<hardware_interface::ResourceManager>();
        try
        {
            resource_manager_->load_urdf(urdf_string, false, false);
        }
        catch (...)
        {
            RCLCPP_ERROR(
                this->dataPtr->ros_node_->get_logger(), "Error initializing URDF to resource manager!");
        }

        // Load hardware interface plugins
        try
        {
            this->dataPtr->hardware_sim_loader_ = std::make_shared<pluginlib::ClassLoader<GazeboSimSystemInterface>>(
                "gz_ros2_control",
                "gz_ros2_control::GazeboSimSystemInterface");
        }
        catch (pluginlib::LibraryLoadException& ex)
        {
            RCLCPP_ERROR(
                this->dataPtr->ros_node_->get_logger(), "Failed to create robot simulation interface loader: %s ",
                ex.what());
            return;
        }

        // Initialize each component
        for (auto& component_info : control_hardware_info)
        {
            std::string hardware_type_str = component_info.hardware_class_type;
            std::unique_ptr<GazeboSimSystemInterface> gz_system;

            RCLCPP_DEBUG(
                this->dataPtr->ros_node_->get_logger(), "Loading hardware interface %s ...",
                hardware_type_str.c_str());

            try
            {
                gz_system = std::unique_ptr<GazeboSimSystemInterface>(
                    this->dataPtr->hardware_sim_loader_->createUnmanagedInstance(hardware_type_str));
            }
            catch (pluginlib::PluginlibException& ex)
            {
                RCLCPP_ERROR(
                    this->dataPtr->ros_node_->get_logger(),
                    "The plugin failed to load for some reason. Error: %s\n",
                    ex.what());
                continue;
            }

            if (!gz_system->initSim(
                this->dataPtr->ros_node_,
                enabled_joints,
                component_info,
                _ecm,
                this->dataPtr->control_update_rate))
            {
                RCLCPP_FATAL(
                    this->dataPtr->ros_node_->get_logger(), "Could not initialize robot simulation interface");
                return;
            }

            RCLCPP_DEBUG(
                this->dataPtr->ros_node_->get_logger(), "Initialized robot simulation interface %s!",
                hardware_type_str.c_str());

            resource_manager_->import_component(std::move(gz_system), component_info);

            rclcpp_lifecycle::State state(
                lifecycle_msgs::msg::State::PRIMARY_STATE_ACTIVE,
                hardware_interface::lifecycle_state_names::ACTIVE);
            resource_manager_->set_component_state(component_info.name, state);
        }

        // Create controller manager
        RCLCPP_INFO(this->dataPtr->ros_node_->get_logger(), "Loading controller_manager");

        rclcpp::NodeOptions options = controller_manager::get_cm_node_options();
        arguments.emplace_back("-r");
        arguments.push_back("__node:=" + controller_manager_node_name);
        arguments.emplace_back("-r");
        arguments.push_back("__ns:=" + ns);
        options.arguments(arguments);

        this->dataPtr->controller_instance_ = std::make_shared<controller_manager::ControllerManager>(
            std::move(resource_manager_),
            this->dataPtr->executor_spin_,
            controller_manager_node_name,
            this->dataPtr->ros_node_->get_namespace());

        this->dataPtr->executor_spin_->add_node(this->dataPtr->controller_instance_);

        if (!this->dataPtr->controller_instance_->has_parameter("update_rate"))
        {
            RCLCPP_ERROR_STREAM(
                this->dataPtr->ros_node_->get_logger(),
                "controller manager doesn't have an update_rate parameter");
            return;
        }

        this->dataPtr->control_update_rate =
            this->dataPtr->controller_instance_->get_parameter("update_rate").as_int();

        this->dataPtr->control_interval_ = rclcpp::Duration(
            std::chrono::duration_cast<std::chrono::nanoseconds>(
                std::chrono::duration<double>(1.0 / static_cast<double>(this->dataPtr->control_update_rate))));

        // Force use_sim_time parameter
        this->dataPtr->controller_instance_->set_parameter(
            rclcpp::Parameter("use_sim_time", rclcpp::ParameterValue(true)));

        this->dataPtr->entity_id_ = _entity;
    }

    //////////////////////////////////////////////////
    void GazeboSimROS2ControlPlugin::PreUpdate(
        const sim::UpdateInfo& _info,
        sim::EntityComponentManager& /*_ecm*/)
    {
        if (!this->dataPtr->controller_instance_)
        {
            return;
        }

        static bool warning_shown{false};
        if (!warning_shown)
        {
            rclcpp::Duration gazebo_period(_info.dt);

            // Check control period vs simulation period
            if (this->dataPtr->control_interval_ < _info.dt)
            {
                RCLCPP_ERROR_STREAM(
                    this->dataPtr->ros_node_->get_logger(),
                    "Desired controller update period (" << this->dataPtr->control_interval_.seconds() <<
                    " s) is faster than the gazebo simulation period (" <<
                    gazebo_period.seconds() << " s).");
            }
            else if (this->dataPtr->control_interval_ > gazebo_period)
            {
                RCLCPP_WARN_STREAM(
                    this->dataPtr->ros_node_->get_logger(),
                    "Desired controller update period (" << this->dataPtr->control_interval_.seconds() <<
                    " s) is slower than the gazebo simulation period (" <<
                    gazebo_period.seconds() << " s).");
            }
            warning_shown = true;
        }

        rclcpp::Time sim_time_ros(std::chrono::duration_cast<std::chrono::nanoseconds>(
                                      _info.simTime).count(), RCL_ROS_TIME);
        rclcpp::Duration sim_period = sim_time_ros - this->dataPtr->last_simulation_update_time_;

        // Always write commands to maintain joint stability at low frequencies
        this->dataPtr->controller_instance_->write(sim_time_ros, sim_period);
    }

    //////////////////////////////////////////////////
    void GazeboSimROS2ControlPlugin::PostUpdate(
        const sim::UpdateInfo& _info,
        const sim::EntityComponentManager& /*_ecm*/)
    {
        if (!this->dataPtr->controller_instance_)
        {
            return;
        }

        // Get simulation time and period
        rclcpp::Time sim_time_ros(std::chrono::duration_cast<std::chrono::nanoseconds>(
                                      _info.simTime).count(), RCL_ROS_TIME);
        rclcpp::Duration sim_period = sim_time_ros - this->dataPtr->last_simulation_update_time_;

        if (sim_period >= this->dataPtr->control_interval_)
        {
            this->dataPtr->last_simulation_update_time_ = sim_time_ros;

            this->dataPtr->controller_instance_->read(sim_time_ros, sim_period);
            this->dataPtr->controller_instance_->update(sim_time_ros, sim_period);
        }
    }
} // namespace gz_ros2_control

