#include "Folder.h"
#include "File.h"

namespace Gorgon::Resource {

// Constructor delegating to File::Self()
Folder::Folder(File &resourceFile) : Folder(resourceFile.Self()) { }

// Constructor accepting weak_ptr<File>
Folder::Folder(std::weak_ptr<File> resourceFile) : Folder() {
    this->file = resourceFile;
}

void Folder::Prepare() {
    Base::Prepare();
    if (shouldLoadNames) {
        for (auto &childNode : children) {
            if (!childNode.GetName().empty()) {
                namedlist.emplace(childNode.GetName(), &childNode);
            }
        }
    }
}

bool Folder::Load(bool shallow) {
    if (fullyloaded) return true;

    auto filePtr = this->file.lock();
    if (!filePtr) {
        return false;
    }

    auto &fileRef = *filePtr;
    if (!reader->TryOpen()) return false;

    reader->Seek(entrypoint - 4);
    auto chunkSize = reader->ReadChunkSize();

    bool success = load(reader, chunkSize, false, shallow, true);
    if (success) {
        // Populate mapping via BFS traversal
        std::vector<Containers::Collection<Base>::ConstIterator> queue;
        queue.emplace_back(this->begin());

        while (!queue.empty()) {
            if (!queue.back().IsValid()) {
                queue.pop_back();
                continue;
            }

            auto &currentObj = *queue.back();
            queue.back().Next();

            if (currentObj.Children.GetCount() > 0) {
                queue.emplace_back(currentObj.begin());
            }

            fileRef.mapping[currentObj.GetGuid()] = &currentObj;
        }

        Resolve(fileRef);

        if (fullyloaded) {
            this->reader->NoLongerNeeded();
            this->reader.reset();
        }
    }

    return success;
}

bool Folder::load(std::shared_ptr<Reader> reader, unsigned long totalsize, bool onlyfirst, bool shallow, bool doLoad) {
    entrypoint = reader->Tell();
    auto endPos = reader->Target(totalsize);

    if (!doLoad || onlyfirst) {
        reader->KeepOpen();
        this->reader = reader;
    }

    auto filePtr = this->file.lock();
    if (!filePtr) {
        throw LoadError(LoadError::NoFileObject, "There is no file object associated with this folder.");
    }

    while (!endPos) {
        auto gid = reader->ReadGID();
        auto size = reader->ReadChunkSize();

        if (gid == GID::Folder_Names) {
            reader->EatChunk(size);
        } else if (gid == GID::Folder_Props) {
            shouldLoadNames = reader->ReadBool();
            reader->EatChunk(size - 4);
        } else if (doLoad && gid == GID::Folder) {
            auto subfolder = new Folder(filePtr);
            if (!subfolder->load(reader, size, false, false, !shallow)) {
                delete subfolder;
                return false;
            }
            children.Add(subfolder);
            if (onlyfirst) {
                reader->Seek(endPos);
                break;
            }
        } else {
            auto resource = filePtr->LoadChunk(*this, gid, size, !doLoad);
            if (resource) {
                children.Add(resource);
                if (onlyfirst) {
                    reader->Seek(endPos);
                    break;
                }
            }
        }
    }

    if (!onlyfirst && doLoad) {
        fullyloaded = true;
    }

    return true;
}

void Folder::save(Writer &writer) const {
    auto startOffset = writer.WriteObjectStart(this);

    writer.WriteChunkHeader(GID::Folder_Props, 4);
    writer.WriteBool(shouldLoadNames);

    for (const auto &baseObj : children) {
        baseObj.Save(writer);
    }

    writer.WriteEnd(startOffset);
}

Folder *Folder::LoadResource(std::weak_ptr<File> file, std::shared_ptr<Reader> data, unsigned long size) {
    auto folder = new Folder(file);
    if (!folder->load(data, size, false, false, true)) {
        delete folder;
        return nullptr;
    }
    return folder;
}

} // namespace Gorgon::Resource

