#include "unicode/utypes.h"
#if !UCONFIG_NO_FORMATTING
#include <algorithm>
#include <cstring>

// ICU PATCH: Modified header paths for double-conversion library
#include "double-conversion-bignum.h"
#include "double-conversion-utils.h"

U_NAMESPACE_BEGIN
namespace double_conversion {

// Helper function to get raw bigit reference at specified index
Bignum::Chunk& Bignum::RawBigit(const int pos) {
  DOUBLE_CONVERSION_ASSERT(static_cast<unsigned>(pos) < kBigitCapacity);
  return bigits_buffer_[pos];
}

// Const version of RawBigit for read-only access
const Bignum::Chunk& Bignum::RawBigit(const int pos) const {
  DOUBLE_CONVERSION_ASSERT(static_cast<unsigned>(pos) < kBigitCapacity);
  return bigits_buffer_[pos];
}

// Calculate bit size of a given type
template<typename T>
static int GetBitSize(const T val) {
  (void) val;  // Suppress unused variable warning
  return 8 * sizeof(val);
}

// Assign a 16-bit unsigned value to this bignum
void Bignum::AssignUInt16(const uint16_t value) {
  DOUBLE_CONVERSION_ASSERT(kBigitSize >= GetBitSize(value));
  Zero();
  if (value > 0) {
    RawBigit(0) = value;
    used_bigits_ = 1;
  }
}

// Assign a 64-bit unsigned value to this bignum
void Bignum::AssignUInt64(uint64_t value) {
  Zero();
  for(int idx = 0; value > 0; ++idx) {
    RawBigit(idx) = value & kBigitMask;
    value >>= kBigitSize;
    ++used_bigits_;
  }
}

// Copy contents from another bignum
void Bignum::AssignBignum(const Bignum& source) {
  exponent_ = source.exponent_;
  for (int i = 0; i < source.used_bigits_; ++i) {
    RawBigit(i) = source.RawBigit(i);
  }
  used_bigits_ = source.used_bigits_;
}

// Parse decimal string representation into uint64_t
static uint64_t ParseUInt64(const Vector<const char> buffer,
                           const int start,
                           const int count) {
  uint64_t result = 0;
  for (int i = start; i < start + count; ++i) {
    const int digit = buffer[i] - '0';
    DOUBLE_CONVERSION_ASSERT(0 <= digit && digit <= 9);
    result = result * 10 + digit;
  }
  return result;
}

// Assign decimal string value to this bignum
void Bignum::AssignDecimalString(const Vector<const char> input) {
  // 2^64 = 18446744073709551616 > 10^19
  static const int kMaxUint64DecimalDigits = 19;
  Zero();
  int length = input.length();
  unsigned position = 0;
  // Assume each digit requires approximately 4 bits
  while (length >= kMaxUint64DecimalDigits) {
    const uint64_t digits = ParseUInt64(input, position, kMaxUint64DecimalDigits);
    position += kMaxUint64DecimalDigits;
    length -= kMaxUint64DecimalDigits;
    MultiplyByPowerOfTen(kMaxUint64DecimalDigits);
    AddUInt64(digits);
  }
  const uint64_t remaining_digits = ParseUInt64(input, position, length);
  MultiplyByPowerOfTen(length);
  AddUInt64(remaining_digits);
  Clamp();
}

// Convert hex character to numeric value
static uint64_t HexCharToValue(const int c) {
  if ('0' <= c && c <= '9') {
    return c - '0';
  }
  if ('a' <= c && c <= 'f') {
    return 10 + c - 'a';
  }
  DOUBLE_CONVERSION_ASSERT('A' <= c && c <= 'F');
  return 10 + c - 'A';
}

// Assign hexadecimal string value (mainly for testing)
void Bignum::AssignHexString(Vector<const char> hex_value) {
  Zero();
  // Estimate required capacity ignoring leading zeros
  EnsureCapacity(((hex_value.length() * 4) + kBigitSize - 1) / kBigitSize);
  DOUBLE_CONVERSION_ASSERT(sizeof(uint64_t) * 8 >= kBigitSize + 4);  // TODO: static_assert
  // Accumulate converted hex digits until we have enough for a bigit
  uint64_t temp = 0;
  int bit_count = 0;
  for (; !hex_value.is_empty(); hex_value.pop_back()) {
    temp |= (HexCharToValue(hex_value.last()) << bit_count);
    if ((bit_count += 4) >= kBigitSize) {
      RawBigit(used_bigits_++) = (temp & kBigitMask);
      bit_count -= kBigitSize;
      temp >>= kBigitSize;
    }
  }
  if (temp > 0) {
    DOUBLE_CONVERSION_ASSERT(temp <= kBigitMask);
    RawBigit(used_bigits_++) = static_cast<Bignum::Chunk>(temp & kBigitMask);
  }
  Clamp();
}

// Add a 64-bit unsigned integer to this bignum
void Bignum::AddUInt64(const uint64_t operand) {
  if (operand == 0) {
    return;
  }
  Bignum temp;
  temp.AssignUInt64(operand);
  AddBignum(temp);
}

// Add another bignum to this one
void Bignum::AddBignum(const Bignum& addend) {
  DOUBLE_CONVERSION_ASSERT(IsClamped());
  DOUBLE_CONVERSION_ASSERT(addend.IsClamped());

  // Align exponents by padding with zero bigits
  Align(addend);

  // Determine maximum needed capacity for result
  EnsureCapacity(1 + (std::max)(BigitLength(), addend.BigitLength()) - exponent_);

  Chunk carry = 0;
  int bigit_pos = addend.exponent_ - exponent_;
  DOUBLE_CONVERSION_ASSERT(bigit_pos >= 0);

  // Fill any gaps with zeros
  for (int i = used_bigits_; i < bigit_pos; ++i) {
    RawBigit(i) = 0;
  }

  // Add corresponding bigits
  for (int i = 0; i < addend.used_bigits_; ++i) {
    const Chunk current = (bigit_pos < used_bigits_) ? RawBigit(bigit_pos) : 0;
    const Chunk sum = current + addend.RawBigit(i) + carry;
    RawBigit(bigit_pos) = sum & kBigitMask;
    carry = sum >> kBigitSize;
    ++bigit_pos;
  }

  // Handle remaining carry
  while (carry != 0) {
    const Chunk current = (bigit_pos < used_bigits_) ? RawBigit(bigit_pos) : 0;
    const Chunk sum = current + carry;
    RawBigit(bigit_pos) = sum & kBigitMask;
    carry = sum >> kBigitSize;
    ++bigit_pos;
  }

  used_bigits_ = static_cast<int16_t>(std::max(bigit_pos, static_cast<int>(used_bigits_)));
  DOUBLE_CONVERSION_ASSERT(IsClamped());
}

// Subtract another bignum from this one
void Bignum::SubtractBignum(const Bignum& subtrahend) {
  DOUBLE_CONVERSION_ASSERT(IsClamped());
  DOUBLE_CONVERSION_ASSERT(subtrahend.IsClamped());
  DOUBLE_CONVERSION_ASSERT(LessEqual(subtrahend, *this));

  Align(subtrahend);
  const int offset = subtrahend.exponent_ - exponent_;
  Chunk borrow = 0;
  int i;

  // Perform subtraction digit by digit
  for (i = 0; i < subtrahend.used_bigits_; ++i) {
    DOUBLE_CONVERSION_ASSERT((borrow == 0) || (borrow == 1));
    const Chunk difference = RawBigit(i + offset) - subtrahend.RawBigit(i) - borrow;
    RawBigit(i + offset) = difference & kBigitMask;
    borrow = difference >> (kChunkSize - 1);
  }

  // Handle remaining borrow propagation
  while (borrow != 0) {
    const Chunk difference = RawBigit(i + offset) - borrow;
    RawBigit(i + offset) = difference & kBigitMask;
    borrow = difference >> (kChunkSize - 1);
    ++i;
  }
  Clamp();
}

// Left shift operation
void Bignum::ShiftLeft(const int shift_amount) {
  if (used_bigits_ == 0) {
    return;
  }
  exponent_ += static_cast<int16_t>(shift_amount / kBigitSize);
  const int local_shift = shift_amount % kBigitSize;
  EnsureCapacity(used_bigits_ + 1);
  BigitsShiftLeft(local_shift);
}

// Multiply by a 32-bit unsigned integer
void Bignum::MultiplyByUInt32(const uint32_t factor) {
  if (factor == 1) {
    return;
  }
  if (factor == 0) {
    Zero();
    return;
  }
  if (used_bigits_ == 0) {
    return;
  }

  // Product of bigit and factor fits in DoubleChunk plus carry
  DOUBLE_CONVERSION_ASSERT(kDoubleChunkSize >= kBigitSize + 32 + 1);
  DoubleChunk carry = 0;
  for (int i = 0; i < used_bigits_; ++i) {
    const DoubleChunk product = static_cast<DoubleChunk>(factor) * RawBigit(i) + carry;
    RawBigit(i) = static_cast<Chunk>(product & kBigitMask);
    carry = (product >> kBigitSize);
  }

  // Handle remaining carry
  while (carry != 0) {
    EnsureCapacity(used_bigits_ + 1);
    RawBigit(used_bigits_) = carry & kBigitMask;
    used_bigits_++;
    carry >>= kBigitSize;
  }
}

// Multiply by a 64-bit unsigned integer
void Bignum::MultiplyByUInt64(const uint64_t factor) {
  if (factor == 1) {
    return;
  }
  if (factor == 0) {
    Zero();
    return;
  }
  if (used_bigits_ == 0) {
    return;
  }

  DOUBLE_CONVERSION_ASSERT(kBigitSize < 32);
  uint64_t carry = 0;
  const uint64_t low_part = factor & 0xFFFFFFFF;
  const uint64_t high_part = factor >> 32;

  for (int i = 0; i < used_bigits_; ++i) {
    const uint64_t product_low = low_part * RawBigit(i);
    const uint64_t product_high = high_part * RawBigit(i);
    const uint64_t temp = (carry & kBigitMask) + product_low;
    RawBigit(i) = temp & kBigitMask;
    carry = (carry >> kBigitSize) + (temp >> kBigitSize) +
        (product_high << (32 - kBigitSize));
  }

  while (carry != 0) {
    EnsureCapacity(used_bigits_ + 1);
    RawBigit(used_bigits_) = carry & kBigitMask;
    used_bigits_++;
    carry >>= kBigitSize;
  }
}

// Multiply by 10^exponent
void Bignum::MultiplyByPowerOfTen(const exponent) {
  static const uint64_t kFive27 = DOUBLE_CONVERSION_UINT64_2PART_C(0x6765c793, fa10079d);
  static const uint16_t kFive1 = 5;
  static const uint16_t kFive2 = kFive1 * 5;
  static const uint16_t kFive3 = kFive2 * 5;
  static const uint16_t kFive4 = kFive3 * 5;
  static const uint16_t kFive5 = kFive4 * 5;
  static const uint16_t kFive6 = kFive5 * 5;
  static const uint32_t kFive7 = kFive6 * 5;
  static const uint32_t kFive8 = kFive7 * 5;
  static const uint32_t kFive9 = kFive8 * 5;
  static const uint32_t kFive10 = kFive9 * 5;
  static const uint32_t kFive11 = kFive10 * 5;
  static const uint32_t kFive12 = kFive11 * 5;
  static const uint32_t kFive13 = kFive12 * 5;
  static const uint32_t kFive1_to_12[] =
      { kFive1, kFive2, kFive3, kFive4, kFive5, kFive6,
        kFive7, kFive8, kFive9, kFive10, kFive11, kFive12 };
  DOUBLE_CONVERSION_ASSERT(exponent >= 0);
  if (exponent == 0) {
    return;
  }
  if (used_bigits_ == 0) {
    return;
  }

  int remaining_exponent = exponent;
  while (remaining_exponent >= 27) {
    MultiplyByUInt64(kFive27);
    remaining_exponent -= 27;
  }
  while (remaining_exponent >= 13) {
    MultiplyByUInt32(kFive13);
    remaining_exponent -= 13;
  }
  if (remaining_exponent > 0) {
    MultiplyByUInt32(kFive1_to_12[remaining_exponent - 1]);
  }
  ShiftLeft(exponent);
}

// Square this bignum in place
void Bignum::Square() {
  DOUBLE_CONVERSION_ASSERT(IsClamped());
  const int product_length = 2 * used_bigits_;
  EnsureCapacity(product_length);

  // Comba multiplication: compute each column separately
  // Example: r = a2a1a0 * b2b1b0.
  //    r =  1    * a0b0 +
  //        10    * (a1b0 + a0b1) +
  //        100   * (a2b0 + a1b1 + a0b2) +
  //        1000  * (a2b1 + a1b2) +
  //        10000 * a2b2

  // Check if accumulator can hold all products
  if ((1 << (2 * (kChunkSize - kBigitSize))) <= used_bigits_) {
    DOUBLE_CONVERSION_UNIMPLEMENTED();
  }

  DoubleChunk accumulator = 0;
  // Shift digits to avoid overwriting during computation
  const int copy_offset = used_bigits_;
  for (int i = 0; i < used_bigits_; ++i) {
    RawBigit(copy_offset + i) = RawBigit(i);
  }

  // First phase: process lower triangle
  for (int i = 0; i < used_bigits_; ++i) {
    int bigit_index1 = i;
    int bigit_index2 = 0;
    while (bigit_index1 >= 0) {
      const Chunk chunk1 = RawBigit(copy_offset + bigit_index1);
      const Chunk chunk2 = RawBigit(copy_offset + bigit_index2);
      accumulator += static_cast<DoubleChunk>(chunk1) * chunk2;
      bigit_index1--;
      bigit_index2++;
    }
    RawBigit(i) = static_cast<Chunk>(accumulator) & kBigitMask;
    accumulator >>= kBigitSize;
  }

  // Second phase: process upper triangle
  for (int i = used_bigits_; i < product_length; ++i) {
    int bigit_index1 = used_bigits_ - 1;
    int bigit_index2 = i - bigit_index1;
    while (bigit_index2 < used_bigits_) {
      const Chunk chunk1 = RawBigit(copy_offset + bigit_index1);
      const Chunk chunk2 = RawBigit(copy_offset + bigit_index2);
      accumulator += static_cast<DoubleChunk>(chunk1) * chunk2;
      bigit_index1--;
      bigit_index2++;
    }
    RawBigit(i) = static_cast<Chunk>(accumulator) & kBigitMask;
    accumulator >>= kBigitSize;
  }

  DOUBLE_CONVERSION_ASSERT(accumulator == 0);
  used_bigits_ = static_cast<int16_t>(product_length);
  exponent_ *= 2;
  Clamp();
}

// Compute base^power_exponent
void Bignum::AssignPowerUInt16(uint16_t base, const int power_exponent) {
  DOUBLE_CONVERSION_ASSERT(base != 0);
  DOUBLE_CONVERSION_ASSERT(power_exponent >= 0);
  if (power_exponent == 0) {
    AssignUInt16(1);
    return;
  }
  Zero();
  int shifts = 0;

  // Count trailing zeros in base
  while ((base & 1) == 0) {
    base >>= 1;
    shifts++;
  }

  // Calculate bit size of base
  int bit_size = 0;
  int temp_base = base;
  while (temp_base != 0) {
    temp_base >>= 1;
    bit_size++;
  }

  const int final_size = bit_size * power_exponent;
  EnsureCapacity(final_size / kBigitSize + 2);

  // Left-to-right binary exponentiation
  int mask = 1;
  while (power_exponent >= mask) mask <<= 1;
  mask >>= 2;

  uint64_t current_value = base;
  bool pending_multiplication = false;
  const uint64_t max_32bits = 0xFFFFFFFF;

  while (mask != 0 && current_value <= max_32bits) {
    current_value = current_value * current_value;
    if ((power_exponent & mask) != 0) {
      DOUBLE_CONVERSION_ASSERT(bit_size > 0);
      const uint64_t base_bits_mask =
        ~((static_cast<uint64_t>(1) << (64 - bit_size)) - 1);
      const bool high_bits_zero = (current_value & base_bits_mask) == 0;
      if (high_bits_zero) {
        current_value *= base;
      } else {
        pending_multiplication = true;
      }
    }
    mask >>= 1;
  }

  AssignUInt64(current_value);
  if (pending_multiplication) {
    MultiplyByUInt32(base);
  }

  // Continue with bignum operations for larger exponents
  while (mask != 0) {
    Square();
    if ((power_exponent & mask) != 0) {
      MultiplyByUInt32(base);
    }
    mask >>= 1;
  }

  // Apply saved shifts
  ShiftLeft(shifts * power_exponent);
}

// Divide and return quotient as 16-bit value
uint16_t Bignum::DivideModuloIntBignum(const Bignum& divisor) {
  DOUBLE_CONVERSION_ASSERT(IsClamped());
  DOUBLE_CONVERSION_ASSERT(divisor.IsClamped());
  DOUBLE_CONVERSION_ASSERT(divisor.used_bigits_ > 0);

  // If dividend has fewer digits than divisor, result is 0
  if (BigitLength() < divisor.BigitLength()) {
    return 0;
  }

  Align(divisor);
  uint16_t quotient = 0;

  // Remove multiples of divisor until same digit count
  while (BigitLength() > divisor.BigitLength()) {
    DOUBLE_CONVERSION_ASSERT(divisor.RawBigit(divisor.used_bigits_ - 1) >= ((1 << kBigitSize) / 16));
    DOUBLE_CONVERSION_ASSERT(RawBigit(used_bigits_ - 1) < 0x10000);

    // Estimate quotient from leading digits
    quotient += static_cast<uint16_t>(RawBigit(used_bigits_ - 1));
    SubtractTimes(divisor, RawBigit(used_bigits_ - 1));
  }

  DOUBLE_CONVERSION_ASSERT(BigitLength() == divisor.BigitLength());

  const Chunk dividend_digit = RawBigit(used_bigits_ - 1);
  const Chunk divisor_digit = divisor.RawBigit(divisor.used_bigits_ - 1);

  if (divisor.used_bigits_ == 1) {
    // Fast path for single-digit divisor
    int q = dividend_digit / divisor_digit;
    RawBigit(used_bigits_ - 1) = dividend_digit - divisor_digit * q;
    DOUBLE_CONVERSION_ASSERT(q < 0x10000);
    quotient += static_cast<uint16_t>(q);
    Clamp();
    return quotient;
  }

  const int initial_estimate = dividend_digit / (divisor_digit + 1);
  DOUBLE_CONVERSION_ASSERT(initial_estimate < 0x10000);
  quotient += static_cast<uint16_t>(initial_estimate);
  SubtractTimes(divisor, initial_estimate);

  if (divisor_digit * (initial_estimate + 1) > dividend_digit) {
    return quotient;
  }

  while (LessEqual(divisor, *this)) {
    SubtractBignum(divisor);
    quotient++;
  }
  return quotient;
}

// Calculate number of hex characters needed to represent a number
template<typename T>
static int HexDigitCount(T number) {
  DOUBLE_CONVERSION_ASSERT(number > 0);
  int count = 0;
  while (number != 0) {
    number >>= 4;
    count++;
  }
  return count;
}

// Convert numeric value to hex character
static char ValueToHexChar(const int value) {
  DOUBLE_CONVERSION_ASSERT(0 <= value && value <= 16);
  if (value < 10) {
    return static_cast<char>(value + '0');
  }
  return static_cast<char>(value - 10 + 'A');
}

// Convert bignum to hexadecimal string
bool Bignum::ToHexString(char* output, const int buffer_capacity) const {
  DOUBLE_CONVERSION_ASSERT(IsClamped());
  DOUBLE_CONVERSION_ASSERT(kBigitSize % 4 == 0);
  static const int kHexCharsPerBigit = kBigitSize / 4;

  if (used_bigits_ == 0) {
    if (buffer_capacity < 2) {
      return false;
    }
    output[0] = '0';
    output[1] = '\0';
    return true;
  }

  // Calculate required space including null terminator
  const int required_chars = (BigitLength() - 1) * kHexCharsPerBigit +
    HexDigitCount(RawBigit(used_bigits_ - 1)) + 1;
  if (required_chars > buffer_capacity) {
    return false;
  }

  int string_pos = required_chars - 1;
  output[string_pos--] = '\0';

  // Add exponent zeros
  for (int i = 0; i < exponent_; ++i) {
    for (int j = 0; j < kHexCharsPerBigit; ++j) {
      output[string_pos--] = '0';
    }
  }

  // Process each bigit except most significant
  for (int i = 0; i < used_bigits_ - 1; ++i) {
    Chunk current_bigit = RawBigit(i);
    for (int j = 0; j < kHexCharsPerBigit; ++j) {
      output[string_pos--] = ValueToHexChar(current_bigit & 0xF);
      current_bigit >>= 4;
    }
  }

  // Process most significant bigit
  Chunk msb = RawBigit(used_bigits_ - 1);
  while (msb != 0) {
    output[string_pos--] = ValueToHexChar(msb & 0xF);
    msb >>= 4;
  }
  return true;
}

// Safely access bigit at index, returning 0 if out of bounds
Bignum::Chunk Bignum::BigitOrZero(const int index) const {
  if (index >= BigitLength()) {
    return 0;
  }
  if (index < exponent_) {
    return 0;
  }
  return RawBigit(index - exponent_);
}

// Compare two bignums lexicographically
int Bignum::Compare(const Bignum& first, const Bignum& second) {
  DOUBLE_CONVERSION_ASSERT(first.IsClamped());
  DOUBLE_CONVERSION_ASSERT(second.IsClamped());

  const int len_a = first.BigitLength();
  const int len_b = second.BigitLength();

  if (len_a < len_b) {
    return -1;
  }
  if (len_a > len_b) {
    return +1;
  }

  for (int i = len_a - 1; i >= (std::min)(first.exponent_, second.exponent_); --i) {
    const Chunk digit_a = first.BigitOrZero(i);
    const Chunk digit_b = second.BigitOrZero(i);
    if (digit_a < digit_b) {
      return -1;
    }
    if (digit_a > digit_b) {
      return +1;
    }
  }
  return 0;
}

// Compare a+b with c
int Bignum::PlusCompare(const Bignum& augend, const Bignum& adder, const Bignum& sum) {
  DOUBLE_CONVERSION_ASSERT(augend.IsClamped());
  DOUBLE_CONVERSION_ASSERT(adder.IsClamped());
  DOUBLE_CONVERSION_ASSERT(sum.IsClamped());

  if (augend.BigitLength() < adder.BigitLength()) {
    return PlusCompare(adder, augend, sum);
  }

  if (augend.BigitLength() + 1 < sum.BigitLength()) {
    return -1;
  }
  if (augend.BigitLength() > sum.BigitLength()) {
    return +1;
  }

  if (augend.exponent_ >= adder.BigitLength() && augend.BigitLength() < sum.BigitLength()) {
    return -1;
  }

  Chunk borrow = 0;
  const int min_exp = (std::min)((std::min)(augend.exponent_, adder.exponent_), sum.exponent_);

  for (int i = sum.BigitLength() - 1; i >= min_exp; --i) {
    const Chunk digit_a = augend.BigitOrZero(i);
    const Chunk digit_b = adder.BigitOrZero(i);
    const Chunk digit_c = sum.BigitOrZero(i);
    const Chunk total = digit_a + digit_b;

    if (total > digit_c + borrow) {
      return +1;
    } else {
      borrow = digit_c + borrow - total;
      if (borrow > 1) {
        return -1;
      }
      borrow <<= kBigitSize;
    }
  }

  if (borrow == 0) {
    return 0;
  }
  return -1;
}

// Normalize bignum by removing leading zeros
void Bignum::Clamp() {
  while (used_bigits_ > 0 && RawBigit(used_bigits_ - 1) == 0) {
    used_bigits_--;
  }
  if (used_bigits_ == 0) {
    exponent_ = 0;
  }
}

// Align exponents of two bignums
void Bignum::Align(const Bignum& other) {
  if (exponent_ > other.exponent_) {
    const int extra_zeros = exponent_ - other.exponent_;
    EnsureCapacity(used_bigits_ + extra_zeros);
    for (int i = used_bigits_ - 1; i >= 0; --i) {
      RawBigit(i + extra_zeros) = RawBigit(i);
    }
    for (int i = 0; i < extra_zeros; ++i) {
      RawBigit(i) = 0;
    }
    used_bigits_ += static_cast<int16_t>(extra_zeros);
    exponent_ -= static_cast<int16_t>(extra_zeros);
    DOUBLE_CONVERSION_ASSERT(used_bigits_ >= 0);
    DOUBLE_CONVERSION_ASSERT(exponent_ >= 0);
  }
}

// Shift all bigits left by specified amount
void Bignum::BigitsShiftLeft(const int shift_amount) {
  DOUBLE_CONVERSION_ASSERT(shift_amount < kBigitSize);
  DOUBLE_CONVERSION_ASSERT(shift_amount >= 0);
  Chunk carry = 0;
  for (int i = 0; i < used_bigits_; ++i) {
    const Chunk new_carry = RawBigit(i) >> (kBigitSize - shift_amount);
    RawBigit(i) = ((RawBigit(i) << shift_amount) + carry) & kBigitMask;
    carry = new_carry;
  }
  if (carry != 0) {
    RawBigit(used_bigits_) = carry;
    used_bigits_++;
  }
}

// Subtract multiple copies of another bignum
void Bignum::SubtractTimes(const Bignum& subtrahend, const int multiplier) {
  DOUBLE_CONVERSION_ASSERT(exponent_ <= subtrahend.exponent_);
  if (multiplier < 3) {
    for (int i = 0; i < multiplier; ++i) {
      SubtractBignum(subtrahend);
    }
    return;
  }

  Chunk borrow = 0;
  const int exp_diff = subtrahend.exponent_ - exponent_;
  for (int i = 0; i < subtrahend.used_bigits_; ++i) {
    const DoubleChunk product = static_cast<DoubleChunk>(multiplier) * subtrahend.RawBigit(i);
    const DoubleChunk to_remove = borrow + product;
    const Chunk difference = RawBigit(i + exp_diff) - (to_remove & kBigitMask);
    RawBigit(i + exp_diff) = difference & kBigitMask;
    borrow = static_cast<Chunk>((difference >> (kChunkSize - 1)) +
                                (to_remove >> kBigitSize));
  }

  for (int i = subtrahend.used_bigits_ + exp_diff; i < used_bigits_; ++i) {
    if (borrow == 0) {
      return;
    }
    const Chunk difference = RawBigit(i) - borrow;
    RawBigit(i) = difference & kBigitMask;
    borrow = difference >> (kChunkSize - 1);
  }
  Clamp();
}

