#include "clipper2/clipper.h"
#include "clipper2/clipper.triangulation.h"

namespace Clipper2Lib
{
  enum class EdgeType { free, upward, downward }; // upward & downward are 'fixed' edges
  enum class IntersectionType { none, parallel, crossing };
  enum class PointPosition { outside, left_side, right_side };

  // Forward declarations
  class PointNode;
  class LinkEdge;
  class TriFace;

  typedef std::vector<PointNode*> NodeList;
  typedef std::vector<LinkEdge*> EdgeList;

  class PointNode {
  public:
    Point64   coord;
    EdgeList  connections;
    bool      is_inner = false;
    PointNode(const Point64& p) : coord(p) { connections.reserve(2); };
  };

  class LinkEdge {
  public:
    PointNode* start = nullptr;
    PointNode* end = nullptr;
    PointNode* bottom = nullptr;
    PointNode* top = nullptr;
    EdgeType   type = EdgeType::free;
    TriFace* faceA = nullptr;
    TriFace* faceB = nullptr;
    bool       in_use = false;
    LinkEdge* next_link = nullptr;
    LinkEdge* prev_link = nullptr;
  };

  class TriFace {
  public:
    LinkEdge* sides[3];
    TriFace(LinkEdge* s1, LinkEdge* s2, LinkEdge* s3)
    {
      sides[0] = s1;
      sides[1] = s2;
      sides[2] = s3;
    }
  };

  /////////////////////////////////////////////////////////////////////////////
  // Main triangulation class
  /////////////////////////////////////////////////////////////////////////////
  class DelaunayTriangulator {
  private:
    NodeList                  all_points;
    EdgeList                  all_links;
    std::vector<TriFace*>     all_faces;
    std::stack<LinkEdge*>     pending_edges;
    std::stack<LinkEdge*>     horizontal_stack;
    std::stack<PointNode*>    min_vertex_stack;
    bool                      enforce_delaunay = true;
    PointNode*                lowest_point = nullptr;
    LinkEdge*                 active_head = nullptr;

    void AddContour(const Path64& contour);
    bool AddMultipleContours(const Paths64& contours);
    void Cleanup();
    bool ProcessIntersections();
    void MergeCoincidentOrParallelPoints();
    void DivideEdge(LinkEdge* long_edge, LinkEdge* short_edge);
    bool EliminateIntersection(LinkEdge* e1, LinkEdge* e2);
    LinkEdge* MakeEdge(PointNode* p1, PointNode* p2, EdgeType t);
    TriFace* MakeTriangle(LinkEdge* e1, LinkEdge* e2, LinkEdge* e3);
    LinkEdge* CreateInnerMinimumFreeEdge(PointNode* above);
    LinkEdge* HorizontalConnection(PointNode* p1, PointNode* p2);
    void ProcessLeftTriangulation(LinkEdge* edge, PointNode* pivot, int64_t min_y);
    void ProcessRightTriangulation(LinkEdge* edge, PointNode* pivot, int64_t min_y);
    void InsertIntoActiveList(LinkEdge* edge);
    void RemoveFromActiveList(LinkEdge* edge);
    void EnsureValid(LinkEdge* edge);

  public:
    explicit DelaunayTriangulator(bool delaunay_check = true) : enforce_delaunay(delaunay_check) {};
    ~DelaunayTriangulator() { Cleanup(); };
    Paths64 Run(const Paths64& input_paths, TriangulateResult& result);
  };

  /////////////////////////////////////////////////////////////////////////////
  // Utility functions
  /////////////////////////////////////////////////////////////////////////////
  static bool PointSorter(const PointNode* first, const PointNode* second)
  {
    return (first->coord.y == second->coord.y) ? (first->coord.x < second->coord.x) : (first->coord.y > second->coord.y);
  }

  static bool EdgeSorter(const LinkEdge* first, const LinkEdge* second)
  {
    return (first->start->coord.x < second->start->coord.x);
  }

  static bool IsFreeEdge(const LinkEdge& e)
  {
    return e.type == EdgeType::free;
  }

  static bool IsAscendingEdge(const LinkEdge& e)
  {
    // ascending edge (boundary) of a fill area
    // meaning fills are on the **right** side of this edge
    // precondition - e is never a 'free' edge
    return e.type == EdgeType::upward;
  }

  static bool IsDescendingEdge(const LinkEdge& e)
  {
    // descending edge (boundary) of a fill area
    // still fills on the **right** side of this edge
    // precondition - e is never a 'free' edge
    return e.type == EdgeType::downward;
  }

  static bool IsHorizontalEdge(const LinkEdge& e)
  {
    return e.bottom->coord.y == e.top->coord.y;
  }

  static bool CounterClockwiseTurn(const Point64& pt1, const Point64& pt2, const Point64& pt3)
  {
    return CrossProductSign(pt1, pt2, pt3) < 0;
  }

  static bool ClockwiseTurn(const Point64& pt1, const Point64& pt2, const Point64& pt3)
  {
    return CrossProductSign(pt1, pt2, pt3) > 0;
  }

  static bool EdgeIsComplete(LinkEdge* edge)
  {
    if (!edge->faceA) return false;
    if (edge->faceB) return true;
    return edge->type != EdgeType::free;
  }

  static PointPosition EdgeContainsPoint(const LinkEdge* edge, const PointNode* point)
  {
    if (edge->start == point) return PointPosition::left_side;
    else if (edge->end == point) return PointPosition::right_side;
    else return PointPosition::outside;
  }

  static double CalculateAngle(const Point64& origin, const Point64& mid, const Point64& dest)
  {
    //https://stackoverflow.com/a/3487062/359538
    double omx = static_cast<double>(mid.x - origin.x);
    double omy = static_cast<double>(mid.y - origin.y);
    double mdx = static_cast<double>(dest.x - mid.x);
    double mdy = static_cast<double>(dest.y - mid.y);
    double dot_product = (omx * mdx + omy * mdy);
    double cross_product = (omx * mdy - omy * mdx);
    return std::atan2(cross_product, dot_product); //range between -Pi and Pi
  }

  static double GetMinimumVertexAngle(PointNode* vertex)
  {
    // todo - verify sign against left vs right turns
    // (currently assumes left turn => positive values)
    // precondition - this function is called before processing minimum vertex.
    //Assert(vertex->connections.size() == 2);
    int asc_idx, desc_idx;
    if (vertex->connections[0]->type == EdgeType::upward)
    {
      asc_idx = 0;
      desc_idx = 1;
    }
    else
    {
      desc_idx = 0;
      asc_idx = 1;
    }
    // winding direction - descending to ascending
    return CalculateAngle(vertex->connections[desc_idx]->top->coord, vertex->coord, vertex->connections[asc_idx]->top->coord);
  }

  static void RemoveLinkFromNode(PointNode* node, LinkEdge* link)
  {
    auto iter = std::find(node->connections.begin(), node->connections.end(), link);
    if (iter == node->connections.end()) throw "error!";
    node->connections.erase(iter);
  }

  static bool FindMinimumIndex(const Path64& path, size_t length, size_t& index)
  {
    if (length < 3) return false;
    size_t start_idx = index, n = (index + 1) % length;
    while (path[n].y <= path[index].y) 
    {
      index = n; n = (n + 1) % length;
      if (index == start_idx) return false; // fails if the path is completely horizontal
    }
    while (path[n].y >= path[index].y)
    {
      index = n; n = (n + 1) % length;
    }
    return true;
  }

  static size_t Previous(size_t& idx, size_t len)
  {
    if (idx == 0) return len - 1; else return idx - 1;
  }

  static size_t NextIndex(size_t& idx, size_t len)
  {
    return (idx + 1) % len;
  }

  static LinkEdge* FindConnectingEdge(const PointNode* node1, const PointNode* node2, bool prefer_upward)
  {
    LinkEdge* result = nullptr;
    for (auto link : node1->connections)
    {
      if (link->start == node2 || link->end == node2)
      {
        if (link->type == EdgeType::free ||
          ((link->type == EdgeType::upward) == prefer_upward)) return link;
        result = link;
      }
    }
    return result;
  }

  static Path64 TriangleToPath(TriFace tri)
  { 
    Path64 result;
    result.reserve(3);
    result.push_back(tri.sides[0]->start->coord);
    result.push_back(tri.sides[0]->end->coord);
    const LinkEdge& e = *tri.sides[1];
    if (e.start->coord == result[0] || e.start->coord == result[1]) 
      result.push_back(e.end->coord);
    else
      result.push_back(e.start->coord);
    return result;
  }

  static double InCircleTest(const Point64& pointA, const Point64& pointB, 
    const Point64& pointC, const Point64& pointD)
  {
    // Return the determinant value of 3 x 3 matrix ...
    // | ax-dx    ay-dy    Sqr(ax-dx)+Sqr(ay-dy) |
    // | bx-dx    by-dy    Sqr(bx-dx)+Sqr(by-dy) |
    // | cx-dx    cy-dy    Sqr(cx-dx)+Sqr(cy-dy) |
    // The *sign* of the return value is determined by
    // the orientation (CW vs CCW) of pointA, pointB & pointC.
    // precondition - pointA, pointB & pointC make a *non-empty* triangle
    double m00 = static_cast<double>(pointA.x - pointD.x);
    double m01 = static_cast<double>(pointA.y - pointD.y);
    double m02 = (Sqr(m00) + Sqr(m01));
    double m10 = static_cast<double>(pointB.x - pointD.x);
    double m11 = static_cast<double>(pointB.y - pointD.y);
    double m12 = (Sqr(m10) + Sqr(m11));
    double m20 = static_cast<double>(pointC.x - pointD.x);
    double m21 = static_cast<double>(pointC.y - pointD.y);
    double m22 = (Sqr(m20) + Sqr(m21));
    return m00 * (m11 * m22 - m21 * m12) -
      m10 * (m01 * m22 - m21 * m02) +
      m20 * (m01 * m12 - m11 * m02);
  }

  static double DistanceFromSegment(const Point64& point, const Point64& segment_start, const Point64& segment_end)
  {
    // precondition: segment_start != segment_end
    double dx = static_cast<double>(segment_end.x - segment_start.x);
    double dy = static_cast<double>(segment_end.y - segment_start.y);
    //Assert((dx < > 0) or (dy < > 0)); // ie segment_start != segment_end
    double px = static_cast<double>(point.x - segment_start.x);
    double py = static_cast<double>(point.y - segment_start.y);
    //q = (px * dx + py * dy) / (dx * dx + dy * dy);
    double q_num = px * dx + py * dy;
    if (q_num < 0)  // point is closest to segment_start
      return DistanceSqr(point, segment_start);
    else if (q_num > (Sqr(dx) + Sqr(dy))) // point is closest to segment_end
      return DistanceSqr(point, segment_end);
    else
       return Sqr(px * dy - dx * py) / (dx * dx + dy * dy);
  }

  static IntersectionType SegmentsIntersect(const Point64 seg1_start, const Point64 seg1_end, 
    const Point64 seg2_start, const Point64 seg2_end)
  {
    double dy1 = static_cast<double>(seg1_end.y - seg1_start.y);
    double dx1 = static_cast<double>(seg1_end.x - seg1_start.x);
    double dy2 = static_cast<double>(seg2_end.y - seg2_start.y);
    double dx2 = static_cast<double>(seg2_end.x - seg2_start.x);
    double cross_product = dy1 * dx2 - dy2 * dx1;
    if (cross_product == 0) return IntersectionType::parallel;
    double t_param = (static_cast<double>(seg1_start.x - seg2_start.x) * dy2 - 
      static_cast<double>(seg1_start.y - seg2_start.y) * dx2);
    //ignore segments that 'intersect' at an endpoint
    if (t_param == 0) return IntersectionType::none;
    if (t_param > 0)
    {
      if (cross_product < 0 || t_param >= cross_product) return IntersectionType::none;
    }
    else
    {
      if (cross_product > 0 || t_param <= cross_product) return IntersectionType::none;
    }
    // so far, the *segment* 'seg1' intersects the *line* through 'seg2',
    // but now make sure it also intersects the *segment* 'seg2'
    t_param = ((seg1_start.x - seg2_start.x) * dy1 - (seg1_start.y - seg2_start.y) * dx1);
    if (t_param == 0) return IntersectionType::none;
    if (t_param > 0)
    {
      if (cross_product > 0 && t_param < cross_product) return IntersectionType::crossing;
    }
    else
    { 
      if (cross_product < 0 && t_param > cross_product) return IntersectionType::crossing;
    }
    return IntersectionType::none;
  }

  /////////////////////////////////////////////////////////////////////////////
  // DelaunayTriangulator class definitions
  /////////////////////////////////////////////////////////////////////////////
  void DelaunayTriangulator::Cleanup()
  {
    for (auto pt : all_points) delete pt;
    all_points.resize(0);
    for (auto lnk : all_links) delete lnk;
    all_links.resize(0);
    for (auto fce : all_faces) delete fce;
    all_faces.resize(0);
    active_head = nullptr;
    lowest_point = nullptr;
   }

  void DelaunayTriangulator::EnsureValid(LinkEdge* edge)
  {
    // don't try to make empty triangles valid
    if (!edge->faceA || !edge->faceB) return;
    // vertA will be assigned the point in edge's faceA
    // that is NOT an end point of edge
    // Likewise, vertB will be assigned the point in edge's
    // faceB that is NOT an end point of edge
    // If edge is rotated, vertA & vertB will become its end points.
    PointNode* pointA = nullptr;
    PointNode* pointB = nullptr;
    // Excluding 'edge', edgesA will contain two edges (one from
    // faceA and one from faceB) that touch edge->start.
    // And edgesB will contain the two edges that touch edge->end.

    LinkEdge* adjacent_edgesA[3] = { nullptr, nullptr, nullptr };
    LinkEdge* adjacent_edgesB[3] = { nullptr, nullptr, nullptr };

    for (int i = 0; i < 3; ++i)
    {
      if (edge->faceA->sides[i] == edge) continue;
      switch (EdgeContainsPoint(edge->faceA->sides[i], edge->start))
      {
      case PointPosition::left_side:
        adjacent_edgesA[1] = edge->faceA->sides[i];
        pointA = edge->faceA->sides[i]->end;
        break;
      case PointPosition::right_side:
        adjacent_edgesA[1] = edge->faceA->sides[i];
        pointA = edge->faceA->sides[i]->start;
        break;
      default:
        adjacent_edgesB[1] = edge->faceA->sides[i];
      }
    }

    for (int i = 0; i < 3; ++i)
    {
      if (edge->faceB->sides[i] == edge) continue;
      switch (EdgeContainsPoint(edge->faceB->sides[i], edge->start))
      {
      case PointPosition::left_side:
        adjacent_edgesA[2] = edge->faceB->sides[i];
        pointB = edge->faceB->sides[i]->end;
        break;
      case PointPosition::right_side:
        adjacent_edgesA[2] = edge->faceB->sides[i];
        pointB = edge->faceB->sides[i]->start;
        break;
      default:
        adjacent_edgesB[2] = edge->faceB->sides[i];
      }
    }

    // InCircleTest requires edge.faceA to be a valid triangle
    // if IsEmptyTriangle(edge.faceA) then Exit; // slower
    if (CrossProductSign(pointA->coord, edge->start->coord, edge->end->coord) == 0) return;

    // ict_result - result sign depends on faceA's orientation
    double ict_result = InCircleTest(pointA->coord, edge->start->coord, edge->end->coord, pointB->coord);
    if (ict_result == 0 || // if on or outside circle then exit
      (ClockwiseTurn(pointA->coord, edge->start->coord, edge->end->coord) == (ict_result < 0))) return;

    // TRIANGLES HERE ARE **NOT** DELAUNAY COMPLIANT, SO MAKE THEM SO.
    // NOTE: ONCE WE BEGIN DELAUNAY COMPLIANCE, start & end WILL
    // NO LONGER REPRESENT LEFT AND RIGHT POINT ORIENTATION.
    // THIS IS MINOR PERFORMANCE EFFICIENCY IS SAFE AS LONG AS
    // THE Triangulate() METHOD IS CALLED ONCE ONLY ON A GIVEN
    // SET OF PATHS

    edge->start = pointA;
    edge->end = pointB;
    edge->faceA->sides[0] = edge;

    for (int i = 1; i < 3; ++i)
    {
      edge->faceA->sides[i] = adjacent_edgesA[i];
      if (!adjacent_edgesA[i]) throw "error"; // stops compiler warnings 
      if (IsFreeEdge(*adjacent_edgesA[i]))
        pending_edges.push(adjacent_edgesA[i]);

      // since each edge has its own faceA and faceB, we have to be careful
      // to update the correct one ...
      if (adjacent_edgesA[i]->faceA == edge->faceA || adjacent_edgesA[i]->faceB == edge->faceA) continue;
      if (adjacent_edgesA[i]->faceA == edge->faceB)
        adjacent_edgesA[i]->faceA = edge->faceA;
      else if (adjacent_edgesA[i]->faceB == edge->faceB)
        adjacent_edgesA[i]->faceB = edge->faceA;
      else throw "error";
    }

    edge->faceB->sides[0] = edge;

    for (int i = 1; i < 3; ++i)
    {
      edge->faceB->sides[i] = adjacent_edgesB[i];
      if (!adjacent_edgesB[i]) throw "error"; // stops compiler warnings 
      if (IsFreeEdge(*adjacent_edgesB[i]))
        pending_edges.push(adjacent_edgesB[i]);

      // since each edge has its own faceA and faceB, we have to be careful
      // to update the correct one ...
      if (adjacent_edgesB[i]->faceA == edge->faceB || adjacent_edgesB[i]->faceB == edge->faceB) continue;
      if (adjacent_edgesB[i]->faceA == edge->faceA)
        adjacent_edgesB[i]->faceA = edge->faceB;
      else if (adjacent_edgesB[i]->faceB == edge->faceA)
        adjacent_edgesB[i]->faceB = edge->faceB;
      else throw "error";
    }
  }

  LinkEdge* DelaunayTriangulator::MakeEdge(PointNode* p1, PointNode* p2, EdgeType t)
  {
    LinkEdge* result = all_links.emplace_back(new LinkEdge());
    if (p1->coord.y == p2->coord.y)
    {
      result->bottom = p1; result->top = p2;
    }
    else if (p1->coord.y < p2->coord.y)
    {
      result->bottom = p2; result->top = p1;
    }
    else
    {
      result->bottom = p1; result->top = p2;
    }
    if (p1->coord.x <= p2->coord.x)
    {
      result->start = p1; result->end = p2;
    }
    else
    {
      result->start = p2; result->end = p1;
    }
    result->type = t;
    p1->connections.push_back(result);
    p2->connections.push_back(result);
    if (t == EdgeType::free)
    {
      pending_edges.push(result);
      InsertIntoActiveList(result);
    }
    return result;
  }

  TriFace* DelaunayTriangulator::MakeTriangle(LinkEdge* e1, LinkEdge* e2, LinkEdge* e3)
  {
    TriFace* result = all_faces.emplace_back(new TriFace(e1, e2, e3));
    // nb: only expire free edges when both sides of these edges have triangles.
    for (int i = 0; i < 3; ++i)       
      if (result->sides[i]->faceA)
      {
        result->sides[i]->faceB = result;
        // this is the edge's second triangle hence no longer active
        RemoveFromActiveList(result->sides[i]);
      }
      else
      {
        result->sides[i]->faceA = result;
        // this is the edge's first triangle, so only remove
        // this edge from actives if it's a fixed edge.
        if (!IsFreeEdge(*result->sides[i])) 
          RemoveFromActiveList(result->sides[i]);
      }
    return result;
  }

  bool DelaunayTriangulator::EliminateIntersection(LinkEdge* e1, LinkEdge* e2)
  {
    // find which point is closest to the other segment
    // (ie not the point closest to the intersection point) ...
    PointNode* v = e1->start;
    LinkEdge* temp_edge = e2;
    double dist = DistanceFromSegment(e1->start->coord, e2->start->coord, e2->end->coord);
    double dist2 = DistanceFromSegment(e1->end->coord, e2->start->coord, e2->end->coord);
    if (dist2 < dist) { dist = dist2; v = e1->end; }
    dist2 = DistanceFromSegment(e2->start->coord, e1->start->coord, e1->end->coord);
    if (dist2 < dist) { dist = dist2; temp_edge = e1; v = e2->start; }
    dist2 = DistanceFromSegment(e2->end->coord, e1->start->coord, e1->end->coord);
    if (dist2 < dist) { dist = dist2; temp_edge = e1; v = e2->end; }
    if (dist > 1.000)
      return false; // Oops - this is not just a simple 'rounding' intersection

    // split 'temp_edge' into 2 edges at 'v'
    PointNode* v2 = temp_edge->top;
    RemoveLinkFromNode(v2, temp_edge);

    // replace v2 in temp_edge with v
    if (temp_edge->start == v2) temp_edge->start = v; 
    else temp_edge->end = v;
    temp_edge->top = v;
    v->connections.push_back(temp_edge);
    v->is_inner = false; // #47

    // left turning is angle positive
    if (temp_edge->bottom->is_inner && GetMinimumVertexAngle(temp_edge->bottom) <= 0)
      temp_edge->bottom->is_inner = false; // #44, 52

    // finally create a new edge between v and v2 ...
    MakeEdge(v, v2, temp_edge->type);
    return true;
  }

  bool DelaunayTriangulator::ProcessIntersections()
  {
    // precondition - edgeList must be sorted - ascending on edge.start.coord.x
    for (size_t i1 = 0; i1 < all_links.size(); ++i1)
    {
      LinkEdge* e1 = all_links[i1];
      // nb: we can safely ignore edges newly created inside this for loop
      for (size_t i2 = i1 + 1; i2 < all_links.size(); ++i2)
      {
        LinkEdge* e2 = all_links[i2];
        if (e2->start->coord.x >= e1->end->coord.x) 
          break; // all 'e' from now on are too far right

        // 'e2' is inside e1's horizontal region. If 'e2' is also inside
        // e1's vertical region, only then check for an intersection ...
        if (e2->top->coord.y < e1->bottom->coord.y && e2->bottom->coord.y > e1->top->coord.y &&
          (SegmentsIntersect(e2->start->coord, e2->end->coord,
            e1->start->coord, e1->end->coord) == IntersectionType::crossing))
        {
          if (!EliminateIntersection(e2, e1)) 
            return false; // oops!!
        }
        // nb: parallel edges are managed in MergeCoincidentOrParallelPoints below
      }
    }
    return true;
  }

  void DelaunayTriangulator::DivideEdge(LinkEdge* long_edge, LinkEdge* short_edge)
  {
    auto old_top = long_edge->top, new_top = short_edge->top;
    // remove long_edge from long_edge->top.connections
    RemoveLinkFromNode(old_top, long_edge);
    // shorten long_edge
    long_edge->top = new_top;
    if (long_edge->start == old_top) long_edge->start = new_top;
    else long_edge->end = new_top;
    // add shortened long_edge to new_top.connections
    new_top->connections.push_back(long_edge);
    // and create a new edge betweem new_top, old_top
    MakeEdge(new_top, old_top, long_edge->type);
  }

  void DelaunayTriangulator::MergeCoincidentOrParallelPoints()
  {
    // note: this procedure may add new edges and change the
    // number of edges connected with a given point, but it 
    // won't add or delete points (so it's safe to use iterators)
    auto pt_iter1 = all_points.begin();
    for (auto pt_iter2 = all_points.begin() + 1; pt_iter2 != all_points.end(); ++pt_iter2)
    {
      if ((*pt_iter1)->coord != (*pt_iter2)->coord)
      {
        pt_iter1 = pt_iter2;
        continue;
      }
      // merge pt1 & pt2
      PointNode* pt1 = *pt_iter1, * pt2 = *pt_iter2;
      if (!pt1->is_inner || !pt2->is_inner)
        pt1->is_inner = false;

      // in all of pt2's edges, replace links to pt2 with links to pt1
      for (auto lnk : pt2->connections)
      {
        if (lnk->bottom == pt2) lnk->bottom = pt1;
        else lnk->top = pt1;
        if (lnk->start == pt2) lnk->start = pt1;
        else lnk->end = pt1;
      }

      // move all of pt2's edges to pt1
      std::copy(pt2->connections.begin(), pt2->connections.end(), back_inserter(pt1->connections));
      pt2->connections.resize(0);

      // excluding horizontals, if pv.connections contains two edges
      // that are *parallel* and share the same bottom coords
      // but have different lengths, split the longer edge at
      // the top of the shorter edge ...
      for (auto it_link = pt1->connections.begin(); it_link != pt1->connections.end(); ++it_link)
      {
        if (IsHorizontalEdge(*(*it_link)) || (*it_link)->bottom != pt1) continue;
        for (auto it_link2 = it_link + 1; it_link2 != pt1->connections.end(); ++it_link2)
        {
          auto e1 = *it_link, e2 = *it_link2;
          if (e2->bottom != pt1 || e1->top->coord.y == e2->top->coord.y ||
            (CrossProductSign(e1->top->coord, pt1->coord, e2->top->coord) != 0)) continue;

          // we have parallel edges, both heading up from pt1.coord.
          // split the longer edge at the top of the shorter edge.
          if (e1->top->coord.y < e2->top->coord.y) DivideEdge(e1, e2);
          else DivideEdge(e2, e1);
          break; // because only two edges can be parallel
        }
      }
    }
  }

  LinkEdge* DelaunayTriangulator::CreateInnerMinimumFreeEdge(PointNode* above)
  {
    if (!active_head) return nullptr; // oops!!
    int64_t x_above = above->coord.x;
    int64_t y_above = above->coord.y;

    // find the closest 'active' edge with a point that's not above above
    LinkEdge* edge = active_head, *edge_below = nullptr;
    double best_dist = -1.0;

    while (edge) 
    { 
      if (edge->start->coord.x <= x_above && edge->end->coord.x >= x_above &&
        edge->bottom->coord.y >= y_above && edge->bottom != above && edge->top != above &&
        !CounterClockwiseTurn(edge->start->coord, above->coord, edge->end->coord))
      {
        double d = DistanceFromSegment(above->coord, edge->start->coord, edge->end->coord);
        if (!edge_below || d < best_dist) // compare edge with edge_below
        {
          edge_below = edge;
          best_dist = d;
        }
      }
      edge = edge->next_link;
    }

    if (!edge_below) return nullptr; // oops!!

    // get the best point from 'edge_below'
    PointNode* best_point = (edge_below->top->coord.y <= y_above) ? edge_below->bottom : edge_below->top;
    int64_t x_best = best_point->coord.x;
    int64_t y_best = best_point->coord.y;

    // make sure no edges intersect 'above' and 'best_point' ...
    // todo: active_list is currently *unsorted* but consider making it
    // a tree structure based on each edge's left and right bounds
    edge = active_head;

    if (x_best < x_above)
    {
      while (edge)
      {
        if (edge->end->coord.x > x_best && edge->start->coord.x < x_above &&
          edge->bottom->coord.y > y_above && edge->top->coord.y < y_best &&
          (SegmentsIntersect(edge->bottom->coord, edge->top->coord,
            best_point->coord, above->coord) == IntersectionType::crossing))
        {
          best_point = (edge->top->coord.y > y_above) ? edge->top : edge->bottom;
          x_best = best_point->coord.x;
          y_best = best_point->coord.y;
        }
        edge = edge->next_link;
      }
    }
    else
    {
      while (edge)
      {
        if (edge->end->coord.x < x_best && edge->start->coord.x > x_above &&
          edge->bottom->coord.y > y_above && edge->top->coord.y < y_best &&
          (SegmentsIntersect(edge->bottom->coord, edge->top->coord,
            best_point->coord, above->coord) == IntersectionType::crossing))
        {
          best_point = edge->top->coord.y > y_above ? edge->top : edge->bottom;
          x_best = best_point->coord.x;
          y_best = best_point->coord.y;
        }
        edge = edge->next_link;
      }
    }

    return MakeEdge(best_point, above, EdgeType::free);
  }

  LinkEdge* DelaunayTriangulator::HorizontalConnection(PointNode* p1, PointNode* p2)
  {
    int64_t y_coord = p1->coord.y, l, r;
    if (p1->coord.x > p2->coord.x)
    {
      l = p2->coord.x;
      r = p1->coord.x;
    } 
    else
    {
      l = p1->coord.x;
      r = p2->coord.x;
    }

    LinkEdge* result = active_head;
    while (result)
    {
      if (result->start->coord.y == y_coord && result->end->coord.y == y_coord &&
        result->start->coord.x >= l && result->end->coord.x <= r &&
        (result->start->coord.x != l || result->end->coord.x != r)) break;
      result = result->next_link;
    }
    return result;
  }

