#include "PinService.h"

// Configure the specified pin as input without pull-up or pull-down
void PinService::setInput(uint8_t pinNumber) {
    pinMode(pinNumber, INPUT);
    pullState[pinNumber] = NOPULL;
}

// Configure the specified pin as input with internal pull-up resistor enabled
void PinService::setInputPullup(uint8_t pinNumber) {
    pinMode(pinNumber, INPUT_PULLUP);
    pullState[pinNumber] = PULL_UP;
}

// Configure the specified pin as input with internal pull-down resistor enabled
void PinService::setInputPullDown(uint8_t pinNumber) {
    pinMode(pinNumber, INPUT_PULLDOWN);
    pullState[pinNumber] = PULL_DOWN;
}

// Configure the specified pin as output
void PinService::setOutput(uint8_t pinNumber) {
    pinMode(pinNumber, OUTPUT);
}

// Set the specified pin to HIGH logic level (ensures OUTPUT mode first)
void PinService::setHigh(uint8_t pinNumber) {
    setOutput(pinNumber);  // ensure OUTPUT mode
    digitalWrite(pinNumber, HIGH);
}

// Set the specified pin to LOW logic level (ensures OUTPUT mode first)
void PinService::setLow(uint8_t pinNumber) {
    setOutput(pinNumber);  // ensure OUTPUT mode
    digitalWrite(pinNumber, LOW);
}

// Read digital value from the specified pin
bool PinService::read(uint8_t pinNumber) {
    return gpio_get_level((gpio_num_t)pinNumber);
}

// Toggle pull-up configuration: if currently PULL_UP, switch to no pull; otherwise enable pull-up
void PinService::togglePullup(uint8_t pinNumber) {
    pullType currentState = pullState[pinNumber];
    if (currentState == PULL_UP) {
        setInput(pinNumber);
    } else {
        setInputPullup(pinNumber);
    }
}

// Toggle pull-down configuration: if currently PULL_DOWN, switch to no pull; otherwise enable pull-down
void PinService::togglePullDown(uint8_t pinNumber) {
    pullType currentState = pullState[pinNumber];
    if (currentState == PULL_DOWN) {
        setInput(pinNumber);
    } else {
        setInputPullDown(pinNumber);
    }
}

// Read analog value from the specified pin
int PinService::readAnalog(uint8_t pinNumber) {
    pinMode(pinNumber, INPUT); 
    return analogRead(pinNumber);
}

// Setup PWM on the specified pin with given frequency and duty cycle percentage
bool PinService::setupPwm(uint8_t pinNumber, uint32_t frequency, uint8_t dutyCyclePercent) {
    if (dutyCyclePercent > 100) dutyCyclePercent = 100;
    detachSignal(pinNumber); // stop existing PWM if active

    uint8_t resolutionBits;
    if (frequency > 300000) {
        resolutionBits = 6;
    } else if (frequency > 150000) {
        resolutionBits = 7;
    } else if (frequency > 60000) {
        resolutionBits = 8;
    } else if (frequency > 20000) {
        resolutionBits = 9;
    } else {
        resolutionBits = 10;
    }

    if (!ledcAttach(pinNumber, frequency, resolutionBits)) {
        return false;
    }

    uint32_t maxDuty = (1UL << resolutionBits) - 1;
    uint32_t actualDuty = (uint32_t(dutyCyclePercent) * maxDuty) / 100U;

    bool success = ledcWrite(pinNumber, actualDuty);
    if (success) {
        markActivePwmPin(pinNumber);
    }
    return success;
}

// Configure servo control using PWM on the specified pin with given angle (0-180 degrees)
bool PinService::setServoAngle(uint8_t pinNumber, uint8_t angleValue) {
  const int pwmFreq = 50; // Hz
  const int pwmResolution = 14;  // maximum stable resolution
  detachSignal(pinNumber); // stop existing signal if active

  // configure and attach LEDC channel
  ledcAttach(pinNumber, pwmFreq, pwmResolution);

  // calculate timing parameters
  const uint32_t periodMicros = 1000000UL / pwmFreq;    // 20000 microseconds
  const uint32_t maxDutyValue = (1UL << pwmResolution) - 1;

  // map angle to pulse width in microseconds (1000–2000 µs for 0–180°)
  uint32_t pulseWidthUs = map(angleValue, 0, 180, 1000, 2000);
  uint32_t dutyCycleValue = (pulseWidthUs * maxDutyValue) / periodMicros;

  bool result = ledcWrite(pinNumber, dutyCycleValue);
  if (result) {
      markActivePwmPin(pinNumber);
  }

  return result;
}

// Retrieve current pull configuration state for a given pin
PinService::pullType PinService::getPullType(uint8_t pinNumber){
    return(pullState[pinNumber]);
}

// Return list of pins that have pull-up or pull-down configured
std::vector<uint8_t> PinService::getConfiguredPullPins() {
    std::vector<uint8_t> pinList;
    pinList.reserve(pullState.size());
    for (const auto& item : pullState) {
        pinList.push_back(item.first);
    }
    return pinList;
}

// Detach PWM signal from the specified pin if it's currently active
void PinService::detachSignal(uint8_t pinNumber) {
    if (!isActivePwmPin(pinNumber)) return;
    ledcDetach(pinNumber);
    unmarkActivePwmPin(pinNumber);
}

// Check whether the specified pin is currently configured for PWM
bool PinService::isActivePwmPin(uint8_t pinNumber) const {
    return std::find(activePwmPins.begin(), activePwmPins.end(), pinNumber) != activePwmPins.end();
}

// Mark a pin as being used for PWM (add to list if not already present)
void PinService::markActivePwmPin(uint8_t pinNumber) {
    if (!isActivePwmPin(pinNumber)) activePwmPins.push_back(pinNumber);
}

// Remove a pin from the list of active PWM pins
void PinService::unmarkActivePwmPin(uint8_t pinNumber) {
    auto iter = std::remove(activePwmPins.begin(), activePwmPins.end(), pinNumber);
    if (iter != activePwmPins.end()) {
        activePwmPins.erase(iter, activePwmPins.end());
    }
}

