void StateManager::Impl::ConnectSims() {
  if (!is_distributed_ || !is_running_ || is_connected_) {
    return;
  }

  const json& sim_scenes = distributed_sim_settings_["sim-scenes"];
  const json& ports_simstate = distributed_sim_settings_["ports-simstate"];

  socket_matrix_.clear();
  socket_matrix_.resize(ports_simstate.size());

  // Open RESP sockets for incoming connections
  for (int source_idx = 0; source_idx < ports_simstate.size(); ++source_idx) {
    socket_matrix_[source_idx].resize(ports_simstate.size());
    if (source_idx == this_scene_index_) continue;

    int port = ports_simstate[source_idx][this_scene_index_];
    std::string endpoint = "tcp://*:";
    endpoint += std::to_string(port);

    nng_socket resp_socket = NNG_SOCKET_INITIALIZER;
    int result = nng_rep0_open(&resp_socket);
    logger_.LogVerbose(this_scene_id_,
                       "[StateManager] Instance %d listening for instance %d at %s...",
                       this_scene_index_, source_idx, endpoint.c_str());
    result = nng_listen(resp_socket, endpoint.c_str(), NULL, 0);
    logger_.LogVerbose(this_scene_id_,
                       "[StateManager] nng_listen() result: %d", result);
    socket_matrix_[source_idx][this_scene_index_] = resp_socket;
  }

  // Open REQ sockets for outgoing connections
  for (int dest_idx = 0; dest_idx < ports_simstate.size(); ++dest_idx) {
    if (dest_idx == this_scene_index_) continue;

    int port = ports_simstate[this_scene_index_][dest_idx];
    std::string endpoint = "tcp://";
    endpoint += sim_scenes[dest_idx]["ip"];
    endpoint += ":";
    endpoint += std::to_string(port);

    nng_socket req_socket = NNG_SOCKET_INITIALIZER;
    int result = nng_req0_open(&req_socket);
    logger_.LogVerbose(this_scene_id_,
                       "[StateManager] Instance %d dialing instance %d at %s...",
                       this_scene_index_, dest_idx, endpoint.c_str());

    do {
      if (!is_running_) return;
      result = nng_dial(req_socket, endpoint.c_str(), NULL, 0);
      logger_.LogVerbose(
          this_scene_id_,
          "[StateManager] nng_dial() result: %d. Retrying in 100ms...", result);
      if (result != 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
      }
    } while (result != 0);

    socket_matrix_[this_scene_index_][dest_idx] = req_socket;
  }

  is_connected_ = true;
}

void StateManager::Impl::DisconnectSims() {
  for (int src_idx = 0; src_idx < socket_matrix_.size(); ++src_idx) {
    for (int dst_idx = 0; dst_idx < socket_matrix_[src_idx].size(); ++dst_idx) {
      if (src_idx == dst_idx) continue;
      nng_socket sock = socket_matrix_[src_idx][dst_idx];
      int rv = nng_close(sock);
      if (rv != 0) {
        logger_.LogVerbose(this_scene_id_,
                           "[StateManager] nng_close() result: %d", rv);
      }
    }
  }
  is_connected_ = false;
}

void StateManager::Impl::Initialize(Scene* scene) {
  sim_scene_ = scene;
  this_scene_index_ = -1;
  this_scene_id_ = "";
  distributed_sim_settings_ = "{}"_json;
  socket_matrix_.clear();
  is_distributed_ = false;
  is_running_ = false;
  is_connected_ = false;
  is_clock_source_ = true;
}

bool StateManager::Impl::IsClockSource() const { return is_clock_source_; }
bool StateManager::Impl::IsConnected() const { return is_connected_; }
bool StateManager::Impl::IsDistributed() const { return is_distributed_; }

bool StateManager::Impl::IsLocalRobot(const std::string& robot_id) {
  int robot_instance_idx = -1;
  auto it = robot_instance_map_.find(robot_id);
  if (it != robot_instance_map_.end()) {
    robot_instance_idx = it->second;
  }
  return (robot_instance_idx == this_scene_index_);
}

bool StateManager::Impl::IsRunning() const { return is_running_; }

void StateManager::Impl::Load(const json& config_json) {
  if (sim_scene_ == nullptr) return;

  distributed_sim_settings_ =
      JsonUtils::GetJsonObject(config_json, Constant::Config::distributed_sim);

  if (JsonUtils::IsEmpty(distributed_sim_settings_)) return;

  const json& sim_scenes = distributed_sim_settings_["sim-scenes"];
  this_scene_id_ = sim_scene_->GetID();
  this_scene_index_ = -1;

  for (int i = 0; i < sim_scenes.size(); ++i) {
    if (this_scene_id_ == sim_scenes[i]["id"]) {
      this_scene_index_ = i;
      break;
    }
  }

  if (this_scene_index_ == -1) return;

  is_distributed_ = true;
  clock_source_instance_index_ = distributed_sim_settings_["simclock-source"];

  auto& actors = sim_scene_->GetActors();

  if (this_scene_index_ == clock_source_instance_index_) {
    is_clock_source_ = true;
    SimClock::Get()->SetExternallySteppedOnly(false);
  } else {
    is_clock_source_ = false;
    SimClock::Get()->SetExternallySteppedOnly(true);
  }

  robot_instance_map_.clear();
  for (auto& actor : actors) {
    if (actor.get().GetType() == ActorType::kRobot) {
      auto& robot = static_cast<Robot&>(actor.get());
      const std::string& robot_id = robot.GetID();
      int instance_idx = -1;
      for (int inst = 0; inst < sim_scenes.size(); ++inst) {
        const json& local_robots = sim_scenes[inst]["local-robots"];
        for (const auto& local_id : local_robots) {
          if (robot_id == local_id) {
            instance_idx = inst;
            break;
          }
        }
        if (instance_idx != -1) break;
      }
      robot_instance_map_.emplace(robot_id, instance_idx);
    }
  }

  for (auto& actor : actors) {
    if (actor.get().GetType() == ActorType::kRobot) {
      auto& robot = static_cast<Robot&>(actor.get());
      if (!IsLocalRobot(robot.GetID())) {
        robot.SetPhysicsType(PhysicsType::kNonPhysics);
        auto& sensors = robot.GetSensors();
        for (auto& sensor : sensors) {
          sensor.get().SetEnabled(false);
        }
      }
    }
  }
}

bool StateManager::Impl::ReceiveAck(nng_socket& socket) {
  bool* resp_data_buf = nullptr;
  size_t resp_data_len;
  int rv = NNG_EAGAIN;

  while (rv == NNG_EAGAIN && is_running_) {
    rv = nng_recv(socket, &resp_data_buf, &resp_data_len,
                  NNG_FLAG_ALLOC | NNG_FLAG_NONBLOCK);
  }

  bool success = false;
  if (rv != 0) {
    logger_.LogWarning(this_scene_id_,
                       "[StateManager::ReceiveAck] nng_recv() result: %d", rv);
  } else if (resp_data_len <= 0) {
    logger_.LogWarning(this_scene_id_,
                       "[StateManager::ReceiveAck] Empty response data.");
  } else {
    success = *resp_data_buf;
  }

  nng_free(resp_data_buf, resp_data_len);

  if (!success) {
    logger_.LogWarning(
        this_scene_id_,
        "[StateManager::ReceiveAck] Received unsuccessful response.");
  }

  return success;
}

void StateManager::Impl::ReceivePhysicsState(int src_idx) {
  nng_socket& socket = socket_matrix_[src_idx][this_scene_index_];
  char* msg_data_buf = nullptr;
  size_t msg_data_len;
  int rv = NNG_EAGAIN;

  while (rv == NNG_EAGAIN && is_running_) {
    rv = nng_recv(socket, &msg_data_buf, &msg_data_len,
                  NNG_FLAG_ALLOC | NNG_FLAG_NONBLOCK);
  }

  if (rv != 0) {
    logger_.LogVerbose(
        this_scene_id_,
        "[StateManager::ReceivePhysicsState] nng_recv() result: %d", rv);
    return;
  }

  std::string msg_data_str(msg_data_len, '\0');
  msg_data_str.assign(msg_data_buf, msg_data_len);
  nng_free(msg_data_buf, msg_data_len);

  PhysicsStateMessage physics_state_msg;
  physics_state_msg.Deserialize(msg_data_str);

  TimeNano timestamp = physics_state_msg.GetTimeStamp();
  const auto& physics_state = physics_state_msg.GetPhysicsState();
  const auto& actuated_rot_state = physics_state_msg.GetActuatedRotationsState();

  auto actors = sim_scene_->GetActors();
  for (auto& actor : actors) {
    if (actor.get().GetType() == ActorType::kRobot) {
      auto& robot = static_cast<Robot&>(actor.get());
      const std::string& robot_id = robot.GetID();

      auto phys_it = physics_state.find(robot_id);
      if (phys_it != physics_state.end()) {
        robot.UpdateKinematics(phys_it->second, timestamp);
      }

      auto rot_it = actuated_rot_state.find(robot_id);
      if (rot_it != actuated_rot_state.end()) {
        robot.SetActuatedRotations(rot_it->second, timestamp);
      }
    }
  }

  bool ack = true;
  rv = nng_send(socket, &ack, sizeof(ack), 0);
  if (rv != 0) {
    logger_.LogVerbose(
        this_scene_id_,
        "[StateManager::ReceivePhysicsState] nng_send() result: %d", rv);
  }
}

TimeNano StateManager::Impl::ReceiveSimTime() {
  nng_socket& socket = socket_matrix_[clock_source_instance_index_][this_scene_index_];
  TimeNano* req_data_buf = nullptr;
  size_t req_data_len;
  int rv = NNG_EAGAIN;

  while (rv == NNG_EAGAIN && is_running_) {
    rv = nng_recv(socket, &req_data_buf, &req_data_len,
                  NNG_FLAG_ALLOC | NNG_FLAG_NONBLOCK);
  }

  if (rv != 0) {
    logger_.LogVerbose(
        this_scene_id_,
        "[StateManager::ReceiveSimTime] nng_recv() result: %d", rv);
    return -1;
  }

  TimeNano new_time = *req_data_buf;
  nng_free(req_data_buf, req_data_len);

  bool ack = true;
  rv = nng_send(socket, &ack, sizeof(ack), 0);
  if (rv != 0) {
    logger_.LogVerbose(
        this_scene_id_,
        "[StateManager::ReceiveSimTime] nng_send() result: %d", rv);
  }

  return new_time;
}

void StateManager::Impl::SendPhysicsState(PhysicsStateMessage physics_state_msg) {
  std::string request_str = physics_state_msg.Serialize();

  for (int dest_idx = 0; dest_idx < socket_matrix_[this_scene_index_].size(); ++dest_idx) {
    if (dest_idx == this_scene_index_) continue;

    nng_socket& socket = socket_matrix_[this_scene_index_][dest_idx];
    int rv = nng_send(socket, request_str.data(), request_str.length(), 0);
    if (rv != 0) {
      logger_.LogVerbose(
          this_scene_id_,
          "[StateManager::SendPhysicsState] nng_send() result: %d", rv);
    }

    bool ack_resp = ReceiveAck(socket);
    if (!ack_resp) {
      logger_.LogVerbose(this_scene_id_,
                         "[StateManager::SendPhysicsState] Ack failed: %d",
                         ack_resp);
    }
  }
}

void StateManager::Impl::SendSimTime(TimeNano sim_time) {
  void* time_ptr = &sim_time;

  for (int dest_idx = 0; dest_idx < socket_matrix_[this_scene_index_].size(); ++dest_idx) {
    if (dest_idx == this_scene_index_) continue;

    nng_socket& socket = socket_matrix_[this_scene_index_][dest_idx];
    int rv = nng_send(socket, time_ptr, sizeof(sim_time), 0);
    if (rv != 0) {
      logger_.LogVerbose(
          this_scene_id_,
          "[StateManager::SendSimTime] nng_send() result: %d", rv);
      continue;
    }

    bool ack_resp = ReceiveAck(socket);
    if (!ack_resp) {
      logger_.LogVerbose(this_scene_id_,
                         "[StateManager::SendSimTime] Ack failed: %d",
                         ack_resp);
    }
  }
}

void StateManager::Impl::Start() { is_running_ = true; }

void StateManager::Impl::Stop() {
  is_running_ = false;
  DisconnectSims();
}

void StateManager::Impl::SynchronizePhysicsState(TimeNano time_stamp) {
  std::unordered_map<std::string, Kinematics> physics_to_send;
  std::unordered_map<std::string, ActuatedRotations> rots_to_send;

  bool physics_sent = false;
  std::set<int> instances_to_receive;

  auto& actors = sim_scene_->GetActors();

  for (int i = 0; i < actors.size(); ++i) {
    auto& actor = actors[i];
    if (actor.get().GetType() == ActorType::kRobot) {
      auto& robot = static_cast<Robot&>(actor.get());
      const std::string& robot_id = robot.GetID();

      if (IsLocalRobot(robot_id)) {
        const Kinematics& kin = robot.GetKinematics();
        physics_to_send.insert({robot_id, kin});

        ActuatedRotations current_rotations;
        const auto& actuators = robot.GetActuators();
        for (auto& actuator_ref : actuators) {
          const Actuator& actuator = actuator_ref.get();
          if (actuator.GetType() == ActuatorType::kRotor) {
            const auto& rotor_ref = static_cast<const Rotor&>(actuator);
            const auto& rotor_rots = rotor_ref.GetActuatedRotations();
            for (const auto& [link, ang_vel] : rotor_rots) {
              current_rotations.insert({link, ang_vel});
            }
          }
        }
        rots_to_send.insert({robot_id, current_rotations});
      } else {
        int robot_instance_idx = robot_instance_map_.at(robot_id);
        instances_to_receive.insert(robot_instance_idx);
      }
    }
  }

  PhysicsStateMessage message(time_stamp, physics_to_send, rots_to_send);

  for (int i = 0; i < actors.size(); ++i) {
    auto& actor = actors[i];
    if (actor.get().GetType() == ActorType::kRobot) {
      auto& robot = static_cast<Robot&>(actor.get());
      const std::string& robot_id = robot.GetID();
      int robot_instance_idx = robot_instance_map_.at(robot_id);

      if (IsLocalRobot(robot_id)) {
        if (physics_sent) continue;
        SendPhysicsState(message);
        physics_sent = true;
      } else {
        if (instances_to_receive.find(robot_instance_idx) == instances_to_receive.end()) {
          continue;
        }
        ReceivePhysicsState(robot_instance_idx);
        instances_to_receive.erase(robot_instance_idx);
      }
    }
  }
}

