// Structure to hold 3D UV coordinates
struct UVCoordinate
{
    double x_val;
    double y_val;
    double z_val;
};

// Structure to hold homogeneous UV coordinates (with weight)
struct UVCoordinate4D
{
    double x_val;
    double y_val;
    double z_val;
    double w_val;
};

namespace AliasToCoreTechUtils
{
    // Convert an Alias surface to a CoreTech NURBS representation
    template<typename SurfaceType>
    CT_OBJECT_ID GenerateCTNurbs(SurfaceType& SurfaceData, EAliasObjectReference RefType, AlMatrix4x4& TransformMatrix)
    {
        CT_UINT32 ControlPointDimension = 4;  // 4 for rational, 3 for non-rational
        CT_UINT32 ControlSizeU = SurfaceData.uNumberOfCVsInclMultiples();
        CT_UINT32 ControlSizeV = SurfaceData.vNumberOfCVsInclMultiples();
        CT_UINT32 DegreeU = SurfaceData.uDegree() + 1;   // U order
        CT_UINT32 DegreeV = SurfaceData.vDegree() + 1;   // V order
        CT_UINT32 KnotCountU = SurfaceData.realuNumberOfKnots() + 2;
        CT_UINT32 KnotCountV = SurfaceData.realvNumberOfKnots() + 2;

        TArray<CT_DOUBLE> KnotArrayU;
        TArray<CT_DOUBLE> KnotArrayV;
        TArray<CT_UINT32> MultArrayU;
        TArray<CT_UINT32> MultArrayV;

        KnotArrayU.SetNumUninitialized(KnotCountU);
        KnotArrayV.SetNumUninitialized(KnotCountV);

        SurfaceData.realuKnotVector(KnotArrayU.GetData() + 1);
        SurfaceData.realvKnotVector(KnotArrayV.GetData() + 1);

        MultArrayU.Init(1, KnotCountU);
        MultArrayV.Init(1, KnotCountV);

        // Extend knot vectors at ends
        KnotArrayU[0] = KnotArrayU[1];
        KnotArrayV[0] = KnotArrayV[1];
        KnotArrayU[KnotCountU - 1] = KnotArrayU[KnotCountU - 2];
        KnotArrayV[KnotCountV - 1] = KnotArrayV[KnotCountV - 2];

        // Prepare control points
        TArray<CT_DOUBLE> ControlPointsArray;
        int TotalCoords = ControlSizeU * ControlSizeV * 4;
        ControlPointsArray.SetNumUninitialized(TotalCoords);

        if (RefType == EAliasObjectReference::WorldReference)
        {
            SurfaceData.CVsWorldPositionInclMultiples(ControlPointsArray.GetData());
        }
        else if (RefType == EAliasObjectReference::ParentReference)
        {
            AlTM Matrix(TransformMatrix);
            SurfaceData.CVsAffectedPositionInclMultiples(Matrix, ControlPointsArray.GetData());
        }
        else  // LocalReference
        {
            SurfaceData.CVsUnaffectedPositionInclMultiples(ControlPointsArray.GetData());
        }

        CT_OBJECT_ID SurfaceID = 0;
        CT_IO_ERROR Status = CT_SNURBS_IO::Create(SurfaceID,
            DegreeU, DegreeV,
            KnotCountU, KnotCountV,
            ControlSizeU, ControlSizeV,
            4, ControlPointsArray.GetData(),
            KnotArrayU.GetData(), KnotArrayV.GetData(),
            MultArrayU.GetData(), MultArrayV.GetData()
        );

        return (Status == IO_OK) ? SurfaceID : 0;
    }
}

