// Create a 3D curve from an Alias curve
CT_OBJECT_ID FAliasCoretechWrapper::Add3DCurve(AlCurve& Curve)
{
    curveFormType Shape = Curve.form();
    CT_UINT32 Degree = Curve.degree() + 1;
    CT_UINT32 ControlSize = Curve.numberOfCVs();
    CT_UINT32 RealKnotCount = Curve.realNumberOfKnots() + 2;

    TArray<UVCoordinate4D> ControlPoints;
    ControlPoints.SetNumUninitialized(ControlSize);

    using HomogeneousPoint = double[4];
    Curve.CVsUnaffectedPositionInclMultiples((HomogeneousPoint*)ControlPoints.GetData());

    TArray<double> CoreTechControlPoints;
    CoreTechControlPoints.SetNumUninitialized(ControlSize * 4);

    int PositionIndex = 0;
    for (CT_UINT32 PointIndex = 0; PointIndex < ControlSize; ++PointIndex)
    {
        CoreTechControlPoints[PositionIndex++] = ControlPoints[PointIndex].x_val;
        CoreTechControlPoints[PositionIndex++] = ControlPoints[PointIndex].y_val;
        CoreTechControlPoints[PositionIndex++] = ControlPoints[PointIndex].z_val;
        CoreTechControlPoints[PositionIndex++] = ControlPoints[PointIndex].w_val;
    }

    TArray<CT_UINT32> KnotMult;
    KnotMult.Init(1, RealKnotCount);

    TArray<CT_DOUBLE> KnotValues;
    KnotValues.SetNumUninitialized(RealKnotCount);
    Curve.realKnotVector(KnotValues.GetData() + 1);
    KnotValues[0] = KnotValues[1];
    KnotValues[RealKnotCount - 1] = KnotValues[RealKnotCount - 2];

    CT_OBJECT_ID NurbsID;
    CT_IO_ERROR Error = CT_CNURBS_IO::Create(
        NurbsID,
        Degree,
        RealKnotCount,
        ControlSize,
        4,
        CoreTechControlPoints.GetData(),
        KnotValues.GetData(),
        KnotMult.GetData(),
        KnotValues[0],
        KnotValues[RealKnotCount - 1]
    );

    return Error ? NurbsID : 0;
}

// Create a trim curve from an Alias trim curve
CT_OBJECT_ID FAliasCoretechWrapper::AddTrimCurve(AlTrimCurve& TrimCurve)
{
    boolean bIsReversed = TrimCurve.isReversed();
    curveFormType Shape = TrimCurve.form();
    CT_UINT32 Degree = TrimCurve.degree() + 1;
    CT_UINT32 ControlSize = TrimCurve.numberOfCVs();
    CT_UINT32 RealKnotCount = TrimCurve.realNumberOfKnots() + 2;

    TArray<UVCoordinate> ControlPoints;
    TArray<double> Weights;
    ControlPoints.SetNumUninitialized(ControlSize);
    Weights.SetNumUninitialized(ControlSize);

    using UVPoint2 = double[3];
    TrimCurve.CVsUVPosition(Weights.GetData(), (UVPoint2*)ControlPoints.GetData());

    TArray<CT_UINT32> KnotMult;
    KnotMult.Init(1, RealKnotCount);

    TArray<CT_DOUBLE> KnotValues;
    KnotValues.SetNumUninitialized(RealKnotCount);
    TrimCurve.realKnotVector(KnotValues.GetData() + 1);
    KnotValues[0] = KnotValues[1];
    KnotValues[RealKnotCount - 1] = KnotValues[RealKnotCount - 2];

    CT_OBJECT_ID D3CurveId = 0;
    CT_OBJECT_ID CoedgeID;
    CT_IO_ERROR Result = CT_COEDGE_IO::Create(CoedgeID, bIsReversed ? CT_ORIENTATION::CT_REVERSE : CT_ORIENTATION::CT_FORWARD, D3CurveId);
    if (Result != IO_OK)
    {
        return 0;
    }

    Result = CT_COEDGE_IO::SetUVCurve(
        CoedgeID,
        Degree,
        RealKnotCount,
        ControlSize,
        3,
        (double*)ControlPoints.GetData(),
        KnotValues.GetData(),
        KnotMult.GetData(),
        KnotValues[0],
        KnotValues[RealKnotCount - 1]
    );

    if (Result != IO_OK)
    {
        return 0;
    }

    // Handle twin curve
    AlTrimCurve* TwinCurve = TrimCurve.getTwinCurve();
    if (TwinCurve)
    {
        CT_OBJECT_ID* TwinCoedgeID = AlEdge2CTEdge.Find(TwinCurve);
        if (TwinCoedgeID)
        {
            CT_COEDGE_IO::MatchCoedges(*TwinCoedgeID, CoedgeID);
        }
        AlEdge2CTEdge.Add(&TrimCurve, CoedgeID);
    }

    return CoedgeID;
}

// Create a trim boundary from an Alias trim boundary
CT_OBJECT_ID FAliasCoretechWrapper::AddTrimBoundary(AlTrimBoundary& TrimBoundary)
{
    AlTrimCurve* CurrentCurve = TrimBoundary.firstCurve();
    CT_LIST_IO CoedgesList;

    while (CurrentCurve)
    {
        CT_OBJECT_ID CoedgeID = AddTrimCurve(*CurrentCurve);
        if (CoedgeID)
        {
            CoedgesList.PushBack(CoedgeID);
        }
        CurrentCurve = CurrentCurve->nextCurve();
    }

    CT_OBJECT_ID LoopID;
    CT_IO_ERROR Result = CT_LOOP_IO::Create(LoopID, CoedgesList);
    return (Result == IO_OK) ? LoopID : 0;
}

// Create a trim region from an Alias trim region
CT_OBJECT_ID FAliasCoretechWrapper::AddTrimRegion(AlTrimRegion& TrimRegion, EAliasObjectReference RefType, AlMatrix4x4& TransformMatrix, bool OrientationFlag)
{
    CT_OBJECT_ID NurbsID = AliasToCoreTechUtils::GenerateCTNurbs(TrimRegion, RefType, TransformMatrix);
    if (NurbsID == 0)
    {
        return 0;
    }

    CT_LIST_IO BoundariesList;
    CT_OBJECT_ID FaceID;
    CT_ORIENTATION FaceOrient = OrientationFlag ? CT_ORIENTATION::CT_FORWARD : CT_ORIENTATION::CT_REVERSE;

    AlTrimBoundary* CurrentBoundary = TrimRegion.firstBoundary();
    while (CurrentBoundary)
    {
        CT_OBJECT_ID LoopID = AddTrimBoundary(*CurrentBoundary);
        if (LoopID)
        {
            BoundariesList.PushBack(LoopID);
        }
        CurrentBoundary = CurrentBoundary->nextBoundary();
    }

    CT_IO_ERROR Result = CT_FACE_IO::Create(FaceID, NurbsID, FaceOrient, BoundariesList);
    return (Result == IO_OK) ? FaceID : 0;
}

// Add a face from an Alias surface
void FAliasCoretechWrapper::AddFace(AlSurface& Surface, EAliasObjectReference RefType, AlMatrix4x4& TransformMatrix, bool OrientationFlag, CT_LIST_IO& OutFaceList)
{
    AlTrimRegion* TrimRegion = Surface.firstTrimRegion();
    if (TrimRegion)
    {
        while (TrimRegion)
        {
            CT_OBJECT_ID FaceID = AddTrimRegion(*TrimRegion, RefType, TransformMatrix, OrientationFlag);
            if (FaceID)
            {
                OutFaceList.PushBack(FaceID);
            }
            TrimRegion = TrimRegion->nextRegion();
        }
        return;
    }

    CT_OBJECT_ID NurbsID = AliasToCoreTechUtils::GenerateCTNurbs(Surface, RefType, TransformMatrix);
    CT_LIST_IO BoundariesList;
    CT_OBJECT_ID FaceID;
    CT_ORIENTATION FaceOrient = OrientationFlag ? CT_ORIENTATION::CT_FORWARD : CT_ORIENTATION::CT_REVERSE;
    CT_IO_ERROR Result = CT_FACE_IO::Create(FaceID, NurbsID, FaceOrient, BoundariesList);
    if (Result == IO_OK)
    {
        OutFaceList.PushBack(FaceID);
    }
}

// Add shell faces to the output list
void FAliasCoretechWrapper::AddShell(AlShell& Shell, EAliasObjectReference RefType, AlMatrix4x4& TransformMatrix, bool OrientationFlag, CT_LIST_IO& OutFaceList)
{
    AlTrimRegion* TrimRegion = Shell.firstTrimRegion();
    while (TrimRegion)
    {
        CT_OBJECT_ID FaceID = AddTrimRegion(*TrimRegion, RefType, TransformMatrix, OrientationFlag);
        if (FaceID)
        {
            OutFaceList.PushBack(FaceID);
        }
        TrimRegion = TrimRegion->nextRegion();
    }
}

// Add BREP geometry from DAG nodes
CT_IO_ERROR FAliasCoretechWrapper::AddBREP(TArray<AlDagNode*>& InDagNodeSet, EAliasObjectReference RefType)
{
    CT_IO_ERROR Status = IO_OK;
    if (!IsSessionValid())
    {
        return IO_ERROR;
    }

    CT_LIST_IO FaceList;
    AlEdge2CTEdge.Empty();

    for (auto Node : InDagNodeSet)
    {
        if (Node == nullptr)
        {
            continue;
        }

        boolean bAlOrientation;
        Node->getSurfaceOrientation(bAlOrientation);
        bool bOrientation = (bool)bAlOrientation;

        AlMatrix4x4 AlMatrix;
        if (RefType == EAliasObjectReference::ParentReference)
        {
            Node->localTransformationMatrix(AlMatrix);
        }

        AlObjectType Type = Node->type();
        switch (Type)
        {
        case(kShellNodeType):
        {
            const char* shaderName = nullptr;
            AlShellNode* ShellNode = Node->asShellNodePtr();
            if (ShellNode)
            {
                AlShell* Shell = ShellNode->shell();
                if (Shell)
                {
                    AddShell(*Shell, RefType, AlMatrix, bOrientation, FaceList);
                }
            }
            break;
        }
        case(kSurfaceNodeType):
        {
            const char* shaderName = nullptr;
            AlSurfaceNode* SurfaceNode = Node->asSurfaceNodePtr();
            if (SurfaceNode)
            {
                AlSurface* Surface = SurfaceNode->surface();
                if (Surface)
                {
                    AddFace(*Surface, RefType, AlMatrix, bOrientation, FaceList);
                }
            }
            break;
        }
        }

        if (FaceList.IsEmpty())
        {
            return IO_ERROR;
        }
    }

    CT_OBJECT_ID BodyID;
    Status = CT_BODY_IO::CreateFromFaces(BodyID, CT_BODY_PROP::CT_BODY_PROP_EXACT | CT_BODY_PROP::CT_BODY_PROP_CLOSE, FaceList);
    if (Status != IO_OK)
    {
        return Status;
    }

    CT_LIST_IO Bodies;
    Bodies.PushBack(BodyID);
    Status = CT_COMPONENT_IO::AddChildren(MainObjectId, Bodies);
    return Status;
}

