// distance between plane p and point v
#define DISTANCE_PLANE_POINT(p,v) \
  ( (p)[0]*(v)[0] + (p)[1]*(v)[1] + (p)[2]*(v)[2] + (p)[3] )

// dVector4, dVector3, dReal
// construct plane from normal and d
#define BUILD_PLANE(plane,normal,d) do{ \
  (plane)[0] = (normal)[0]; \
  (plane)[1] = (normal)[1]; \
  (plane)[2] = (normal)[2]; \
  (plane)[3] = (d); }while(0)

