// Test normal of mesh face as separating axis for intersection
static BOOL testFaceNormal( dReal fp0, dReal fR, dVector3 normalVec, int axisIndex ) 
{
  // calculate overlapping interval of box and triangle
  dReal overlapDepth = fR + fp0;

  // if we do not overlap
  if ( overlapDepth < 0 ) { 
    return FALSE;
  }

  // calculate normal's length
  dReal len = VECTOR_LENGTH(normalVec);

  // if long enough
  if ( len > 0.0f ) {
    dReal invLen = 1.0f / len;
    // normalize depth
    overlapDepth *= invLen;

    // get minimum depth
    if (overlapDepth < minimumDepth) {
      bestNormal[0] = -normalVec[0] * invLen;
      bestNormal[1] = -normalVec[1] * invLen;
      bestNormal[2] = -normalVec[2] * invLen;
      bestAxis = axisIndex;
      minimumDepth = overlapDepth;
    }
  }
  return TRUE;
}

// Test box axis as separating axis 
static BOOL testBoxAxis( dReal fp0, dReal fp1, dReal fp2, dReal fR, dReal fD, 
                         dVector3 normalVec, int axisIndex ) 
{
  dReal triMin, triMax;

  // find min of triangle interval 
  if ( fp0 < fp1 ) {
    if ( fp0 < fp2 ) {
      triMin = fp0;
    } else {
      triMin = fp2;
    }
  } else {
    if( fp1 < fp2 ) {
      triMin = fp1; 
    } else {
      triMin = fp2;
    }
  }

  // find max of triangle interval 
  if ( fp0 > fp1 ) {
    if ( fp0 > fp2 ) {
      triMax = fp0;
    } else {
      triMax = fp2;
    }
  } else {
    if( fp1 > fp2 ) {
      triMax = fp1; 
    } else {
      triMax = fp2;
    }
  }

  // calculate minimum and maximum depth
  dReal depthMin = fR - triMin;
  dReal depthMax = triMax + fR;

  // if we don't have overlapping interval
  if ( depthMin < 0 || depthMax < 0 ) {
    return FALSE;
  }

  dReal depth = 0;

  // if greater depth is on negative side 
  if ( depthMin > depthMax ) {
    // use smaller depth (one from positive side)
    depth = depthMax;
    // flip normal direction
    normalVec[0] = -normalVec[0];
    normalVec[1] = -normalVec[1];
    normalVec[2] = -normalVec[2];
    fD = -fD;
  } else {
    // use smaller depth (one from negative side)
    depth = depthMin;   
  }

  // if lower depth than best found so far 
  if (depth < minimumDepth) {
    // remember current axis as best axis
    bestNormal[0] = normalVec[0];
    bestNormal[1] = normalVec[1];
    bestNormal[2] = normalVec[2];
    bestAxis = axisIndex;
    minimumDepth = depth;
  }
  return TRUE;
}

// Test cross products of box axis and triangle edges as separating axis
static BOOL testEdgeAxis( dReal fp0, dReal fp1, dReal fR, dReal fD, 
                          dVector3 normalVec, int axisIndex ) 
{
  dReal triMin, triMax;

  // calculate min and max interval values  
  if ( fp0 < fp1 ) {
    triMin = fp0;
    triMax = fp1;
  } else {
    triMin = fp1;
    triMax = fp0;    
  }

  // check if we overlapp
  dReal depthMin = fR - triMin;
  dReal depthMax = triMax + fR;

  // if we don't overlapp
  if ( depthMin < 0 || depthMax < 0 ) {
    return FALSE;
  }

  dReal depth;

  // if greater depth is on negative side 
  if ( depthMin > depthMax ) {
    // use smaller depth (one from positive side)
    depth = depthMax;
    // flip normal direction
    normalVec[0] = -normalVec[0];
    normalVec[1] = -normalVec[1];
    normalVec[2] = -normalVec[2];
    fD = -fD;
  } else {
    // use smaller depth (one from negative side)
    depth = depthMin;   
  }

  // calculate normal's length
  dReal len = VECTOR_LENGTH(normalVec);

  // if long enough
  if ( len > 0.0f ) {
    // normalize depth
    dReal invLen = 1.0f / len;
    depth *= invLen;
    fD *= invLen;

    // if lower depth than best found so far (favor face over edges)
    if (depth * 1.5f < minimumDepth) {
      // remember current axis as best axis
      bestNormal[0] = normalVec[0] * invLen;
      bestNormal[1] = normalVec[1] * invLen;
      bestNormal[2] = normalVec[2] * invLen;
      bestAxis = axisIndex;
      minimumDepth = depth;
    }
  }
  return TRUE;
}

// clip polygon with plane and generate new polygon points
static void clipPolygonToPlane( dVector3 inputArray[], int inputCount, 
                      dVector3 outputArray[], int &outputCount, 
                      const dVector4 &plane )
{
  // start with no output points
  outputCount = 0;
  int prevIdx = inputCount - 1;

  // for each edge in input polygon
  for (int currIdx = 0; currIdx < inputCount; prevIdx = currIdx, currIdx++) {

    // calculate distance of edge points to plane
    dReal distPrev = DISTANCE_PLANE_POINT(plane, inputArray[prevIdx]);
    dReal distCurr = DISTANCE_PLANE_POINT(plane, inputArray[currIdx]);

    // if first point is in front of plane
    if (distPrev >= 0) {
      // emit point
      outputArray[outputCount][0] = inputArray[prevIdx][0];
      outputArray[outputCount][1] = inputArray[prevIdx][1];
      outputArray[outputCount][2] = inputArray[prevIdx][2];
      outputCount++;
    }

    // if points are on different sides
    if ((distPrev > 0 && distCurr < 0) || (distPrev < 0 && distCurr > 0)) {
      // find intersection point of edge and plane
      dVector3 intersectionPoint;
      intersectionPoint[0] = inputArray[prevIdx][0] - (inputArray[prevIdx][0] - inputArray[currIdx][0]) * distPrev / (distPrev - distCurr);
      intersectionPoint[1] = inputArray[prevIdx][1] - (inputArray[prevIdx][1] - inputArray[currIdx][1]) * distPrev / (distPrev - distCurr);
      intersectionPoint[2] = inputArray[prevIdx][2] - (inputArray[prevIdx][2] - inputArray[currIdx][2]) * distPrev / (distPrev - distCurr);

      // emit intersection point
      outputArray[outputCount][0] = intersectionPoint[0];
      outputArray[outputCount][1] = intersectionPoint[1];
      outputArray[outputCount][2] = intersectionPoint[2];
      outputCount++;
    }
  }
}

static BOOL testSeparatingAxes(const dVector3 &v0, const dVector3 &v1, const dVector3 &v2) {
  // reset best axis
  bestAxis = 0;
  exitAxis = -1;
  minimumDepth = MAX_VAL;

  // calculate edges
  SUBTRACT_VEC(v1, v0, edge0);
  SUBTRACT_VEC(v2, v0, edge1);
  SUBTRACT_VEC(edge1, edge0, edge2);

  // calculate poly normal
  dCROSS(faceNormal, =, edge0, edge1);

  // extract box axes as vectors
  dVector3 boxAxis0, boxAxis1, boxAxis2;
  EXTRACT_COL(boxRotation, 0, boxAxis0);
  EXTRACT_COL(boxRotation, 1, boxAxis1);
  EXTRACT_COL(boxRotation, 2, boxAxis2);

  // box halfsizes
  dReal hx = boxHalfExtents[0];
  dReal hy = boxHalfExtents[1];
  dReal hz = boxHalfExtents[2];

  // calculate relative position between box and triangle
  dVector3 diff;
  SUBTRACT_VEC(v0, boxPosition, diff);

  // calculate length of face normal
  dReal faceNormalLen = VECTOR_LENGTH(faceNormal);

  dVector3 tempVec;
  dReal fp0, fp1, fp2, fR, fD;

  // Test separating axes for intersection
  // ************************************************
  // Axis 1 - Triangle Normal 
  ASSIGN_VEC(tempVec, faceNormal);
  fp0  = dDOT(tempVec, diff);
  fp1  = fp0;
  fp2  = fp0;
  fR = hx * dFabs(dDOT(faceNormal, boxAxis0)) + 
       hy * dFabs(dDOT(faceNormal, boxAxis1)) + 
       hz * dFabs(dDOT(faceNormal, boxAxis2));

  if (!testFaceNormal(fp0, fR, tempVec, 1)) { 
    exitAxis = 1;
    return FALSE; 
  } 

  // ************************************************
  // Test Faces
  // ************************************************
  // Axis 2 - Box X-Axis
  ASSIGN_VEC(tempVec, boxAxis0);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 + dDOT(boxAxis0, edge0);
  fp2 = fp0 + dDOT(boxAxis0, edge1);
  fR  = hx;

  if (!testBoxAxis(fp0, fp1, fp2, fR, fD, tempVec, 2)) { 
    exitAxis = 2;
    return FALSE; 
  }

  // Axis 3 - Box Y-Axis
  ASSIGN_VEC(tempVec, boxAxis1);
  fD = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 + dDOT(boxAxis1, edge0);
  fp2 = fp0 + dDOT(boxAxis1, edge1);
  fR  = hy;

  if (!testBoxAxis(fp0, fp1, fp2, fR, fD, tempVec, 3)) { 
    exitAxis = 3;
    return FALSE; 
  }

  // Axis 4 - Box Z-Axis
  ASSIGN_VEC(tempVec, boxAxis2);
  fD = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 + dDOT(boxAxis2, edge0);
  fp2 = fp0 + dDOT(boxAxis2, edge1);
  fR  = hz;

  if (!testBoxAxis(fp0, fp1, fp2, fR, fD, tempVec, 4)) { 
    exitAxis = 4;
    return FALSE; 
  }

  // ************************************************
  // Test Edges
  // ************************************************
  // Axis 5 - Box X-Axis cross Edge0
  dCROSS(tempVec, =, boxAxis0, edge0);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0;
  fp2 = fp0 + dDOT(boxAxis0, faceNormal);
  fR  = hy * dFabs(dDOT(boxAxis2, edge0)) + hz * dFabs(dDOT(boxAxis1, edge0));

  if (!testEdgeAxis(fp1, fp2, fR, fD, tempVec, 5)) { 
    exitAxis = 5;
    return FALSE; 
  }

  // Axis 6 - Box X-Axis cross Edge1
  dCROSS(tempVec, =, boxAxis0, edge1);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 - dDOT(boxAxis0, faceNormal);
  fp2 = fp0;
  fR  = hy * dFabs(dDOT(boxAxis2, edge1)) + hz * dFabs(dDOT(boxAxis1, edge1));

  if (!testEdgeAxis(fp0, fp1, fR, fD, tempVec, 6)) { 
    exitAxis = 6;
    return FALSE; 
  }

  // Axis 7 - Box X-Axis cross Edge2
  dCROSS(tempVec, =, boxAxis0, edge2);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 - dDOT(boxAxis0, faceNormal);
  fp2 = fp0 - dDOT(boxAxis0, faceNormal);
  fR  = hy * dFabs(dDOT(boxAxis2, edge2)) + hz * dFabs(dDOT(boxAxis1, edge2));

  if (!testEdgeAxis(fp0, fp1, fR, fD, tempVec, 7)) { 
    exitAxis = 7;
    return FALSE; 
  }

  // Axis 8 - Box Y-Axis cross Edge0
  dCROSS(tempVec, =, boxAxis1, edge0);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0;
  fp2 = fp0 + dDOT(boxAxis1, faceNormal);
  fR  = hx * dFabs(dDOT(boxAxis2, edge0)) + hz * dFabs(dDOT(boxAxis0, edge0));

  if (!testEdgeAxis(fp0, fp2, fR, fD, tempVec, 8)) { 
    exitAxis = 8;
    return FALSE; 
  }

  // Axis 9 - Box Y-Axis cross Edge1
  dCROSS(tempVec, =, boxAxis1, edge1);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 - dDOT(boxAxis1, faceNormal);
  fp2 = fp0;
  fR  = hx * dFabs(dDOT(boxAxis2, edge1)) + hz * dFabs(dDOT(boxAxis0, edge1));

  if (!testEdgeAxis(fp0, fp1, fR, fD, tempVec, 9)) { 
    exitAxis = 9;
    return FALSE; 
  }

  // Axis 10 - Box Y-Axis cross Edge2
  dCROSS(tempVec, =, boxAxis1, edge2);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 - dDOT(boxAxis1, faceNormal);
  fp2 = fp0 - dDOT(boxAxis1, faceNormal);
  fR  = hx * dFabs(dDOT(boxAxis2, edge2)) + hz * dFabs(dDOT(boxAxis0, edge2));

  if (!testEdgeAxis(fp0, fp1, fR, fD, tempVec, 10)) { 
    exitAxis = 10;
    return FALSE; 
  }

  // Axis 11 - Box Z-Axis cross Edge0
  dCROSS(tempVec, =, boxAxis2, edge0);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0;
  fp2 = fp0 + dDOT(boxAxis2, faceNormal);
  fR  = hx * dFabs(dDOT(boxAxis1, edge0)) + hy * dFabs(dDOT(boxAxis0, edge0));

  if (!testEdgeAxis(fp0, fp2, fR, fD, tempVec, 11)) { 
    exitAxis = 11;
    return FALSE; 
  }

  // Axis 12 - Box Z-Axis cross Edge1
  dCROSS(tempVec, =, boxAxis2, edge1);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 - dDOT(boxAxis2, faceNormal);
  fp2 = fp0;
  fR  = hx * dFabs(dDOT(boxAxis1, edge1)) + hy * dFabs(dDOT(boxAxis0, edge1));

  if (!testEdgeAxis(fp0, fp1, fR, fD, tempVec, 12)) { 
    exitAxis = 12;
    return FALSE; 
  }

  // Axis 13 - Box Z-Axis cross Edge2
  dCROSS(tempVec, =, boxAxis2, edge2);
  fD  = dDOT(tempVec, faceNormal) / faceNormalLen;
  fp0 = dDOT(tempVec, diff);
  fp1 = fp0 - dDOT(boxAxis2, faceNormal);
  fp2 = fp0 - dDOT(boxAxis2, faceNormal);
  fR  = hx * dFabs(dDOT(boxAxis1, edge2)) + hy * dFabs(dDOT(boxAxis0, edge2));

  if (!testEdgeAxis(fp0, fp1, fR, fD, tempVec, 13)) { 
    exitAxis = 13;
    return FALSE; 
  }

  return TRUE; 
}

// find two closest points on two lines
static BOOL findClosestPointsOnLines(dVector3 pt1, dVector3 dir1, 
                                     dVector3 pt2, dVector3 dir2, 
                                     dReal &param1, dReal &param2) 
{
  // calculate denominator
  dVector3 vecDiff;
  SUBTRACT_VEC(pt2, pt1, vecDiff);

  dReal dotDirs = dDOT(dir1, dir2);
  dReal fq1     = dDOT(dir1, vecDiff);
  dReal fq2     = -dDOT(dir2, vecDiff);
  dReal denom   = 1.0f - dotDirs * dotDirs;

  // if denominator is positive
  if (denom > 0.0f) {
    // calculate points of closest approach
    denom = 1.0f / denom;
    param1 = (fq1 + dotDirs * fq2) * denom;
    param2 = (dotDirs * fq1 + fq2) * denom;
    return TRUE;
  } else {
    // lines are parallel
    param1 = 0.0f;
    param2 = 0.0f;
    return FALSE;
  }
}

// clip and generate contacts
static void processContacts(const dVector3 &v0, const dVector3 &v1, const dVector3 &v2) {
  // if we have edge/edge intersection
  if (bestAxis > 4) {
    dVector3 boxPt, triPt;
    ASSIGN_VEC(boxPt, boxPosition);

    // calculate point on box edge
    for (int i = 0; i < 3; i++) {
      dVector3 rotCol;
      EXTRACT_COL(boxRotation, i, rotCol);
      dReal sign = dDOT(bestNormal, rotCol) > 0 ? 1.0f : -1.0f;
      boxPt[0] += sign * boxHalfExtents[i] * rotCol[0];
      boxPt[1] += sign * boxHalfExtents[i] * rotCol[1];
      boxPt[2] += sign * boxHalfExtents[i] * rotCol[2];
    }

    int edgeIdx = (bestAxis - 5) % 3;

    // decide which edge is on triangle
    if (edgeIdx == 0) {
      ASSIGN_VEC(triPt, v0);
      ASSIGN_VEC(edge0, edge0);
    } else if (edgeIdx == 1) {
      ASSIGN_VEC(triPt, v2);
      ASSIGN_VEC(edge0, edge1);
    } else {
      ASSIGN_VEC(triPt, v1);
      ASSIGN_VEC(edge0, edge2);
    }

    // setup direction parameter for face edge
    dNormalize3(edge0);
    dReal param1, param2;

    // setup direction parameter for box edge
    dVector3 boxDir;
    int col = (bestAxis - 5) / 3;
    EXTRACT_COL(boxRotation, col, boxDir);

    // find two closest points on both edges
    findClosestPointsOnLines(boxPt, boxDir, triPt, edge0, param1, param2);

    boxPt[0] += boxDir[0] * param1;
    boxPt[1] += boxDir[1] * param1;
    boxPt[2] += boxDir[2] * param1;

    triPt[0] += edge0[0] * param2; 
    triPt[1] += edge0[1] * param2; 
    triPt[2] += edge0[2] * param2; 

    // calculate collision point
    dVector3 midPoint;
    ADD_VEC(boxPt, triPt, midPoint);
    midPoint[0] *= 0.5f;
    midPoint[1] *= 0.5f;
    midPoint[2] *= 0.5f;

    // generate contact point between two closest points
    dContactGeom* contact = SAFECONTACT(flags, contacts, contactCount, stride);
    contact->depth = minimumDepth;
    ASSIGN_VEC(contact->normal, bestNormal);
    ASSIGN_VEC(contact->pos, midPoint);
    contact->g1 = geom1;
    contact->g2 = geom2;
    contactCount++;
  } 
  // if triangle is the referent face then clip box to triangle face
  else if (bestAxis == 1) {
    dVector3 negBestNormal;
    negBestNormal[0] = -bestNormal[0];
    negBestNormal[1] = -bestNormal[1];
    negBestNormal[2] = -bestNormal[2];

    // transpose rotation matrix
    dMatrix3 transposedRot;
    transposedRot[0*4+0] = boxRotation[0*4+0];
    transposedRot[0*4+1] = boxRotation[1*4+0];
    transposedRot[0*4+2] = boxRotation[2*4+0];
    transposedRot[1*4+0] = boxRotation[0*4+1];
    transposedRot[1*4+1] = boxRotation[1*4+1];
    transposedRot[1*4+2] = boxRotation[2*4+1];
    transposedRot[2*4+0] = boxRotation[0*4+2];
    transposedRot[2*4+1] = boxRotation[1*4+2];
    transposedRot[2*4+2] = boxRotation[2*4+2];

    dVector3 localNormal;
    localNormal[0] = transposedRot[0*4+0]*negBestNormal[0] + transposedRot[0*4+1]*negBestNormal[1] + transposedRot[0*4+2]*negBestNormal[2];
    localNormal[1] = transposedRot[1*4+0]*negBestNormal[0] + transposedRot[1*4+1]*negBestNormal[1] + transposedRot[1*4+2]*negBestNormal[2];
    localNormal[2] = transposedRot[2*4+0]*negBestNormal[0] + transposedRot[2*4+1]*negBestNormal[1] + transposedRot[2*4+2]*negBestNormal[2];

    dVector3 absNormal;
    absNormal[0] = dFabs(localNormal[0]);
    absNormal[1] = dFabs(localNormal[1]);
    absNormal[2] = dFabs(localNormal[2]);

    // get closest face from box
    int idx0, idx1, idx2;
    if (absNormal[1] > absNormal[0]) {
      if (absNormal[1] > absNormal[2]) {
        idx1 = 0; idx0 = 1; idx2 = 2;
      } else {
        idx1 = 0; idx2 = 1; idx0 = 2;
      }
    } else {
      if (absNormal[0] > absNormal[2]) {
        idx0 = 0; idx1 = 1; idx2 = 2;
      } else {
        idx1 = 0; idx2 = 1; idx0 = 2;
      }
    }

    // Here find center of box face we are going to project
    dVector3 faceCenter;
    dVector3 colVec;
    EXTRACT_COL(boxRotation, idx0, colVec);

    if (localNormal[idx0] > 0) {
        faceCenter[0] = boxPosition[0] - v0[0] - boxHalfExtents[idx0] * colVec[0];
        faceCenter[1] = boxPosition[1] - v0[1] - boxHalfExtents[idx0] * colVec[1];
        faceCenter[2] = boxPosition[2] - v0[2] - boxHalfExtents[idx0] * colVec[2];
    } else {
      faceCenter[0] = boxPosition[0] - v0[0] + boxHalfExtents[idx0] * colVec[0];
      faceCenter[1] = boxPosition[1] - v0[1] + boxHalfExtents[idx0] * colVec[1];
      faceCenter[2] = boxPosition[2] - v0[2] + boxHalfExtents[idx0] * colVec[2];
    }  

    // Here find 4 corner points of box
    dVector3 boxCorners[4];
    dVector3 colVec2;
    EXTRACT_COL(boxRotation, idx1, colVec);
    EXTRACT_COL(boxRotation, idx2, colVec2);

    for (int x = 0; x < 3; x++) {
        boxCorners[0][x] = faceCenter[x] + (boxHalfExtents[idx1] * colVec[x]) - (boxHalfExtents[idx2] * colVec2[x]);
        boxCorners[1][x] = faceCenter[x] - (boxHalfExtents[idx1] * colVec[x]) - (boxHalfExtents[idx2] * colVec2[x]);
        boxCorners[2][x] = faceCenter[x] - (boxHalfExtents[idx1] * colVec[x]) + (boxHalfExtents[idx2] * colVec2[x]);
        boxCorners[3][x] = faceCenter[x] + (boxHalfExtents[idx1] * colVec[x]) + (boxHalfExtents[idx2] * colVec2[x]);
    }

    // clip Box face with 4 planes of triangle (1 face plane, 3 egde planes)
    dVector3 tempBuffer1[9];
    dVector3 tempBuffer2[9];
    dVector4 plane;
    int cnt1 = 0;
    int cnt2 = 0;

    // zeroify vectors - necessary?
    for (int i = 0; i < 9; i++) {
      tempBuffer1[i][0] = 0;
      tempBuffer1[i][1] = 0;
      tempBuffer1[i][2] = 0;
      tempBuffer2[i][0] = 0;
      tempBuffer2[i][1] = 0;
      tempBuffer2[i][2] = 0;
    }

    // Normal plane
    dVector3 tempVec;
    tempVec[0] = -faceNormal[0];
    tempVec[1] = -faceNormal[1];
    tempVec[2] = -faceNormal[2];
    dNormalize3(tempVec);
    BUILD_PLANE(plane, tempVec, 0);
    clipPolygonToPlane(boxCorners, 4, tempBuffer1, cnt1, plane);

    // Plane p0
    dVector3 tempVec2;
    SUBTRACT_VEC(v1, v0, tempVec2);
    dCROSS(tempVec, =, faceNormal, tempVec2);
    dNormalize3(tempVec);
    BUILD_PLANE(plane, tempVec, 0);
    clipPolygonToPlane(tempBuffer1, cnt1, tempBuffer2, cnt2, plane);

    // Plane p1
    SUBTRACT_VEC(v2, v1, tempVec2);
    dCROSS(tempVec, =, faceNormal, tempVec2);
    dNormalize3(tempVec);
    SUBTRACT_VEC(v0, v2, tempVec2);
    BUILD_PLANE(plane, tempVec, dDOT(tempVec2, tempVec));
    clipPolygonToPlane(tempBuffer2, cnt2, tempBuffer1, cnt1, plane);

    // Plane p2
    SUBTRACT_VEC(v0, v2, tempVec2);
    dCROSS(tempVec, =, faceNormal, tempVec2);
    dNormalize3(tempVec);
    BUILD_PLANE(plane, tempVec, 0);
    clipPolygonToPlane(tempBuffer1, cnt1, tempBuffer2, cnt2, plane);

    // END of clipping polygons

    // for each generated contact point
    for (int i = 0; i < cnt2; i++) {
      // calculate depth
      dReal tempDepth = dDOT(negBestNormal, tempBuffer2[i]);

      // clamp depth to zero
      if (tempDepth > 0) {
        tempDepth = 0;
      }

      dVector3 finalPoint;
      ADD_VEC(tempBuffer2[i], v0, finalPoint);

      if (contactCount < (flags & NUMC_MASK)) {
          dContactGeom* contact = SAFECONTACT(flags, contacts, contactCount, stride);
          contact->depth = -tempDepth;
          ASSIGN_VEC(contact->normal, bestNormal);
          ASSIGN_VEC(contact->pos, finalPoint);
          contact->g1 = geom1;
          contact->g2 = geom2;
          contactCount++;
      } else {
          break;
      }
    }
  }
}

