static void verify_parsing(const char *grammar_text, const std::vector<std::pair<std::string, uint32_t>> expected_map, const std::vector<llama_grammar_element> &expected_elements) {
    uint32_t counter = 0;
    llama_grammar_parser parsed_structure;
    parsed_structure.parse(grammar_text);

    std::map<uint32_t, std::string> symbol_labels;
    for (auto it = parsed_structure.symbol_ids.begin(); it != parsed_structure.symbol_ids.end(); ++it) {
        symbol_labels[it->second] = it->first;
    }

    auto dump_all = [&]() {
        fprintf(stderr, "    verify_parsing(R\"\"\"(%s)\"\"\", {\n", grammar_text);
        for (auto it = parsed_structure.symbol_ids.begin(); it != parsed_structure.symbol_ids.end(); ++it) {
            fprintf(stderr, "        {\"%s\", %u},\n", it->first.c_str(), it->second);
        }
        fprintf(stderr, "    }, {\n");
        for (size_t rule_idx = 0; rule_idx < parsed_structure.rules.size(); rule_idx++) {
            fprintf(stderr, "        // %s (index %zu)\n", symbol_labels[rule_idx].c_str(), rule_idx);
            auto & current_rule = parsed_structure.rules[rule_idx];
            for (uint32_t elem_idx = 0; elem_idx < current_rule.size(); elem_idx++) {
                fprintf(stderr, "        {%s, ", type_str(current_rule[elem_idx].type));
                if (current_rule[elem_idx].type == LLAMA_GRETYPE_CHAR || 
                    current_rule[elem_idx].type == LLAMA_GRETYPE_CHAR_ALT ||
                    current_rule[elem_idx].type == LLAMA_GRETYPE_CHAR_NOT || 
                    current_rule[elem_idx].type == LLAMA_GRETYPE_CHAR_RNG_UPPER) {
                    char c = static_cast<char>(current_rule[elem_idx].value);
                    if (c == '\n') {
                        fprintf(stderr, "'\\n'");
                    } else if (c == '\t') {
                        fprintf(stderr, "'\\t'");
                    } else if (c == '\r') {
                        fprintf(stderr, "'\\r'");
                    } else if (c == '\0') {
                        fprintf(stderr, "'\\0'");
                    } else {
                        fprintf(stderr, "'%c'", c);
                    }
                } else if (current_rule[elem_idx].type == LLAMA_GRETYPE_RULE_REF) {
                    fprintf(stderr, "/* %s */ %u", symbol_labels[current_rule[elem_idx].value].c_str(), current_rule[elem_idx].value);
                } else {
                    fprintf(stderr, "%u", current_rule[elem_idx].value);
                }
                fprintf(stderr, "},\n");
            }
        }
        fprintf(stderr, "    });\n");
    };

    if (getenv("TEST_GRAMMAR_PARSER_PRINT_ALL")) {
        dump_all();
        fprintf(stderr, "\n");
        return;
    }

    fprintf(stderr, "Testing grammar:%s\n", grammar_text);
    if (parsed_structure.symbol_ids.size() != expected_map.size()) {
        fprintf(stderr, "Code to update expectation (set TEST_GRAMMAR_PARSER_PRINT_ALL=1 to print all):\n");
        dump_all();
        assert(parsed_structure.symbol_ids.size() == expected_map.size());
    }

    for (auto it = parsed_structure.symbol_ids.begin(); it != parsed_structure.symbol_ids.end(); ++it)
    {
        std::string key_name = it->first;
        uint32_t value_id = it->second;
        std::pair<std::string, uint32_t> expected_entry = expected_map[counter];

        if (expected_entry.first != key_name || expected_entry.second != value_id)
        {
            fprintf(stderr, "index: %u\n", counter);
            fprintf(stderr, "expected_pair: %s, %u\n", expected_entry.first.c_str(), expected_entry.second);
            fprintf(stderr, "actual_pair: %s, %u\n", key_name.c_str(), value_id);
            fprintf(stderr, "expected_pair != actual_pair\n");
            fprintf(stderr, "Code to update expectation (set TEST_GRAMMAR_PARSER_PRINT_ALL=1 to print all):\n");
            dump_all();
        }
        assert(expected_entry.first == key_name && expected_entry.second == value_id);
        counter++;
    }

    counter = 0;
    for (auto rule : parsed_structure.rules)
    {
        for (uint32_t i = 0; i < rule.size(); i++)
        {
            llama_grammar_element current_element = rule[i];
            llama_grammar_element expected_element = expected_elements[counter];

            if (expected_element.type != current_element.type || expected_element.value != current_element.value)
            {
                fprintf(stderr, "index: %u\n", counter);
                fprintf(stderr, "expected_element: %s, %u\n", type_str(expected_element.type), expected_element.value);
                fprintf(stderr, "actual_element: %s, %u\n", type_str(current_element.type), current_element.value);
                fprintf(stderr, "expected_element != actual_element\n");
                fprintf(stderr, "all elements:\n");
                fprintf(stderr, "Code to update expectation (set TEST_GRAMMAR_PARSER_PRINT_ALL=1 to print all):\n");
                dump_all();
            }
            assert(expected_element.type == current_element.type && expected_element.value == current_element.value);
            counter++;
        }
    }
}

static void verify_failure(const char * grammar_text) {
    fprintf(stderr, "Testing expected failure:%s\n", grammar_text);
    llama_grammar_parser result;
    result.parse(grammar_text);
    assert(result.rules.empty() && "should have failed");
}

