void BiShengIRHIVMCompileMainConfig::collectHIVMCArgs() {
  std::vector<std::string> collectedArgs;
  auto &registeredOpts = cl::getRegisteredOptions();

  // Collect values from registered options using macro
  for (auto &[optName, optPtr] : registeredOpts) {
    std::string valueStr = "";
#define GEN_OPTION_COLLECTION
#include "bishengir/Tools/bishengir-hivm-compile/HIVMCompileOptions.cpp.inc"
    if (valueStr.empty())
      continue;
    collectedArgs.push_back(optName.str() + "=" + valueStr);
  }

  // Append any additional args from config
  for (const auto &argGroup : clOptionsConfig->getHIVMCArgs()) {
    if (argGroup.empty())
      continue;
    for (const auto &arg : llvm::split(argGroup, " "))
      collectedArgs.push_back(arg.str());
  }

  clOptionsConfig->setHIVMCArgs(collectedArgs);
}

