expr shl(expr const &x, expr const &y) {
  check_context(x, y);
  return to_expr(x.ctx(), Z3_mk_bvshl(x.ctx(), x, y));
}

expr lshr(expr const &x, expr const &y) {
  check_context(x, y);
  return to_expr(x.ctx(), Z3_mk_bvlshr(x.ctx(), x, y));
}

expr ashr(expr const &x, expr const &y) {
  check_context(x, y);
  return to_expr(x.ctx(), Z3_mk_bvashr(x.ctx(), x, y));
}

expr extract(unsigned int hi, unsigned int lo, expr const &val) {
  // extracts from hi downto lo (both including!)
  return to_expr(val.ctx(), Z3_mk_extract(val.ctx(), hi, lo, val));
}

expr concat(expr const &x, expr const &y) {
  return to_expr(x.ctx(), Z3_mk_concat(x.ctx(), x, y));
}

expr zext(unsigned int width, expr const &val) {
  // extends to size |val|+width
  return to_expr(val.ctx(), Z3_mk_zero_ext(val.ctx(), width, val));
}

expr sext(unsigned int width, expr const &val) {
  // extends to size |val|+width
  return to_expr(val.ctx(), Z3_mk_sign_ext(val.ctx(), width, val));
}

expr urem(expr const &x, expr const &y) {
  check_context(x, y);
  return to_expr(x.ctx(), Z3_mk_bvurem(x.ctx(), x, y));
}

expr srem(expr const &x, expr const &y) {
  check_context(x, y);
  return to_expr(x.ctx(), Z3_mk_bvsrem(x.ctx(), x, y));
}

