} // namespace z3_ext

uint64_t expr_to_uint(const z3::expr &e) {
  uint64_t value;
  bool ok = Z3_get_numeral_uint64(e.ctx(), e, &value);
  (void)ok;
  assert(ok && "unsupported conversion from numeral");
  return value;
}

int64_t expr_to_int(const z3::expr &e) {
  uint64_t raw;
  bool ok = Z3_get_numeral_uint64(e.ctx(), e, &raw);
  int64_t result = static_cast<int64_t>(raw);
  if (!ok)
    std::cerr << e << '\n';
  assert(ok && "unsupported conversion from numeral");
  unsigned int bitwidth = e.get_sort().bv_size();
  if (bitwidth < 64 && (result & (1LL << (bitwidth - 1)))) {
    // need to sign extend
    result = ~((1LL << bitwidth) - 1) | result;
  }
  return result;
}

bool expr_to_bool(const z3::expr &e) {
  assert(e.is_const());
  assert(e.is_bool());
  return z3::eq(e, e.ctx().bool_val(true));
}

bool model_defines(const z3::model &model, const z3::symbol &sym) {
  for (unsigned i = 0; i < model.num_consts(); ++i) {
    if (model.get_const_decl(i).name() == sym)
      return true;
  }
  return false;
}

bool is_unsat(z3::expr e) {
  z3::solver solver(e.ctx());
  solver.add(e);
  return solver.check() == z3::unsat;
}

std::vector<expr> expr_constants(const expr &e) {
  auto &ctx = e.ctx();
  auto compare_func = [](const expr &a, const expr &b) {
    Z3_symbol name_a = a.decl().name();
    Z3_symbol name_b = b.decl().name();
    return name_a < name_b;
  };
  std::set<expr, decltype(compare_func)> symbols(compare_func);
  std::function<void(const expr &)> traverse = [&traverse, &symbols,
                                                &ctx](const expr &expr) {
    assert(Z3_is_app(ctx, expr));
    auto app = Z3_to_app(ctx, expr);
    unsigned arg_count = Z3_get_app_num_args(ctx, app);
    auto fdecl = Z3_get_app_decl(ctx, app);
    if (arg_count == 0 && Z3_get_decl_kind(ctx, fdecl) == Z3_OP_UNINTERPRETED)
      symbols.insert(expr);
    for (unsigned i = 0; i < arg_count; ++i) {
      z3::expr arg(ctx, Z3_get_app_arg(ctx, app, i));
      traverse(arg);
    }
  };
  traverse(e);
  return std::vector<expr>(symbols.begin(), symbols.end());
}

z3::expr adjustBitwidth(z3::expr operand, unsigned int target_width) {
  assert(operand.is_bv() && "Only Bitvectors supported here!");
  unsigned int source_width = operand.get_sort().bv_size();
  if (target_width < source_width) // truncate
    return z3_ext::extract(target_width - 1, 0, operand);
  else if (target_width > source_width) // zero extend
    return z3_ext::zext(target_width - source_width, operand);
  else
    return operand;
}

z3::expr makeConstantInt(z3::context *ctx, const llvm::ConstantInt *value) {
  int bits = value->getType()->getIntegerBitWidth();
  assert(bits <= 64 && "TODO: support bigger ints");
  uint64_t val = llvm::dyn_cast<llvm::ConstantInt>(value)->getLimitedValue();
  z3::expr cexpr = ctx->bv_val(val, bits);
  return cexpr;
}

void makePairSort(z3::context &ctx, z3::sort &dest_sort,
                  z3::func_decl &dest_get_first, z3::func_decl &dest_get_second,
                  z3::func_decl &dest_constr, const char *src_get_first_name,
                  z3::sort src_get_first_sort, const char *src_get_second_name,
                  z3::sort src_get_second_sort, const char *src_constr_name) {
  Z3_symbol mk_tuple_name = Z3_mk_string_symbol(ctx, src_constr_name);
  Z3_symbol proj_names[2];
  Z3_sort proj_sorts[2];
  Z3_func_decl constr_decl;
  Z3_func_decl proj_decls[2];
  proj_names[0] = Z3_mk_string_symbol(ctx, src_get_first_name);
  proj_names[1] = Z3_mk_string_symbol(ctx, src_get_second_name);
  proj_sorts[0] = src_get_first_sort;
  proj_sorts[1] = src_get_second_sort;
  Z3_sort res = Z3_mk_tuple_sort(ctx, mk_tuple_name, 2, proj_names, proj_sorts,
                                 &constr_decl, proj_decls);
  dest_sort = z3::to_sort(ctx, res);
  dest_get_first = z3::to_func_decl(ctx, proj_decls[0]);
  dest_get_second = z3::to_func_decl(ctx, proj_decls[1]);
  dest_constr = z3::to_func_decl(ctx, constr_decl);
}

#ifndef _STLP_STRING_IO_C
#define _STLP_STRING_IO_C
#ifndef _STLP_STRING_IO_H
#  include <stl/_string_io.h>
#endif
#ifndef _STL_INTERNAL_CTYPE_H
#  include <stl/_ctype.h>
#endif
_STLP_BEGIN_NAMESPACE

template <class _CharT, class _Traits>
bool _STLP_CALL
__stlp_string_fill(basic_ostream<_CharT, _Traits>& __os,
                   basic_streambuf<_CharT, _Traits>* __buf,
                   streamsize __count) {
  _CharT __fill_char = __os.fill();
  for (streamsize __idx = 0; __idx < __count; ++__idx) {
    if (_Traits::eq_int_type(__buf->sputc(__fill_char), _Traits::eof()))
      return false;
  }
  return true;
}

template <class _CharT, class _Traits, class _Alloc>
basic_ostream<_CharT, _Traits>& _STLP_CALL
operator << (basic_ostream<_CharT, _Traits>& __os, 
             const basic_string<_CharT,_Traits,_Alloc>& __str) {
  typedef basic_ostream<_CharT, _Traits> __ostream_type;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  // Ensure size_type is unsigned via compile-time check
  typedef char __check_unsigned_size_type[__STATIC_CAST(size_type, -1) > 0];

  typename __ostream_type::sentry __sentry_obj(__os);
  bool __success = false;

  if (__sentry_obj) {
    __success = true;
    size_type __len = __str.size();
    const bool __left_justify = (__os.flags() & __ostream_type::left) != 0;
    const streamsize __field_width = __os.width(0);
    basic_streambuf<_CharT, _Traits>* __buffer = __os.rdbuf();

    const bool __requires_padding = (((sizeof(streamsize) > sizeof(size_t)) && (__STATIC_CAST(streamsize, __len) < __field_width)) ||
                                     ((sizeof(streamsize) <= sizeof(size_t)) && (__len < __STATIC_CAST(size_t, __field_width))));
    streamsize __pad_count = __requires_padding ? __field_width - __len : 0;

    if (!__left_justify)
      __success = __stlp_string_fill(__os, __buffer, __pad_count);    
    __success = __success && (__buffer->sputn(__str.data(), streamsize(__len)) == streamsize(__len));
    if (__left_justify)
      __success = __success && __stlp_string_fill(__os, __buffer, __pad_count);
  }

  if (!__success)
    __os.setstate(__ostream_type::failbit);
  return __os;
}

template <class _CharT, class _Traits, class _Alloc>
basic_istream<_CharT, _Traits>& _STLP_CALL 
operator >> (basic_istream<_CharT, _Traits>& __is,
             basic_string<_CharT,_Traits, _Alloc>& __str) {
  typedef basic_istream<_CharT, _Traits> __istream_type;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  // Compile-time assertion that size_type is unsigned
  typedef char __check_unsigned_size_type[__STATIC_CAST(size_type, -1) > 0];

  typename __istream_type::sentry __sentry_obj(__is);
  if (__sentry_obj) {
    basic_streambuf<_CharT, _Traits>* __buffer = __is.rdbuf();
    typedef ctype<_CharT> _C_type;
    const locale& __locale = __is.getloc();
    const _C_type& __ctype_facet = use_facet<_C_type>(__locale);

    __str.clear();
    streamsize __max_width = __is.width(0);
    size_type __limit;

    if (__max_width <= 0)
      __limit = __str.max_size();
    else if (sizeof(streamsize) > sizeof(size_type) && 
             (__max_width > __STATIC_CAST(streamsize, __str.max_size())))
      __limit = 0;
    else {
      __limit = __STATIC_CAST(size_type, __max_width);
      __str.reserve(__limit);
    }

    while (__limit-- > 0) {
      typename _Traits::int_type __char_code = __buffer->sbumpc();
      if (_Traits::eq_int_type(__char_code, _Traits::eof())) {
        __is.setstate(__istream_type::eofbit);
        break;
      }
      else {
        _CharT __current_char = _Traits::to_char_type(__char_code);
        if (__ctype_facet.is(_C_type::space, __current_char)) {
          if (_Traits::eq_int_type(__buffer->sputbackc(__current_char), _Traits::eof()))
            __is.setstate(__istream_type::failbit);
          break;
        }
        else
          __str.push_back(__current_char);
      }
    }

    if (__str.empty())
      __is.setstate(__istream_type::failbit);
  }
  else
    __is.setstate(__istream_type::failbit);
  return __is;
}

template <class _CharT, class _Traits, class _Alloc>    
basic_istream<_CharT, _Traits>& _STLP_CALL 
getline(basic_istream<_CharT, _Traits>& __is,
        basic_string<_CharT,_Traits,_Alloc>& __str,
        _CharT __delimiter) {
  typedef basic_istream<_CharT, _Traits> __istream_type;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  size_type __chars_read = 0;
  typename basic_istream<_CharT, _Traits>::sentry __sentry_obj(__is, true);

  if (__sentry_obj) {
    basic_streambuf<_CharT, _Traits>* __buffer = __is.rdbuf();
    __str.clear();

    while (__chars_read < __str.max_size()) {
      int __char_code = __buffer->sbumpc();
      if (_Traits::eq_int_type(__char_code, _Traits::eof())) {
        __is.setstate(__istream_type::eofbit);
        break;
      }
      else {
        ++__chars_read;
        _CharT __current_char = _Traits::to_char_type(__char_code);
        if (!_Traits::eq(__current_char, __delimiter)) 
          __str.push_back(__current_char);
        else
          break;              
      }
    }
  }

  if (__chars_read == 0 || __chars_read >= __str.max_size())
    __is.setstate(__istream_type::failbit);
  return __is;
}

_STLP_END_NAMESPACE
#endif
