#include <unistd.h>
#include "TestBed.hpp"
#include <rccl/rccl.h>

#define SEND_TO_CHILD(pid, data) \
  ASSERT_EQ(write(childList[pid]->parentWriteFd, &(data), sizeof(data)), sizeof(data))

#define RECV_FROM_CHILD(pid, val)                                                     \
  {                                                                                   \
    if (ev.verbose) INFO("Receiving from Child %d\n", pid);                           \
    ssize_t res = read(childList[pid]->parentReadFd, &(val), sizeof(val));            \
    if (ev.verbose) INFO("Received %ld bytes from Child %d\n", res, pid);             \
    if (res == -1)                                                                    \
    {                                                                                 \
      ERROR("Failed to read from child %d: %s\n", pid, strerror(errno));              \
      FAIL();                                                                         \
    }                                                                                 \
    else if (res == 0)                                                                \
    {                                                                                 \
      ERROR("Pipe closed unexpectedly in child %d\n", pid);                           \
      exit(1);                                                                        \
    }                                                                                 \
    else if (res < sizeof(int))                                                       \
    {                                                                                 \
      ERROR("Incomplete read from child %d (%ld / %lu)\n", pid, res, sizeof(val));    \
      exit(1);                                                                        \
    }                                                                                 \
  }

#define VERIFY_RESPONSE(pid)                                                          \
  {                                                                                   \
    int resp = 0;                                                                     \
    RECV_FROM_CHILD(pid, resp);                                                       \
    if (resp != TEST_SUCCESS)                                                         \
    {                                                                                 \
      ERROR("Child %d reported error\n", pid);                                        \
      ASSERT_EQ(resp, TEST_SUCCESS);                                                  \
      FAIL();                                                                         \
    }                                                                                 \
  }

namespace RcclUnitTesting
{
  TestBed::TestBed() :
    numDevicesDetected(0),
    activeChildrenCount(0),
    activeRanksCount(0)
  {
    this->numDevicesDetected = ev.maxGpus;
    if (ev.verbose) INFO("Found %d GPUs\n", this->numDevicesDetected);
  }

  void TestBed::SetupComms(std::vector<std::vector<int>> const& devicePerProc,
                           std::vector<int>              const& collsPerGroup,
                           std::vector<int>              const& streamsPerGroup,
                           int                           const  groupCalls,
                           bool                          const  blockingMode)
  {
    InteractiveWait("Initializing Comms");

    activeChildrenCount = devicePerProc.size();
    activeRanksCount = 0;
    this->groupCallCount = groupCalls;
    this->collsPerGroup = collsPerGroup;
    this->blockingMode = blockingMode;
    this->streamsPerGroup = streamsPerGroup;
    rankToChild.clear();
    rankToDevice.clear();

    if (ev.verbose) INFO("Configuring %d active processes\n", activeChildrenCount);

    for (int procIdx = 0; procIdx < activeChildrenCount; ++procIdx)
    {
      for (auto idx = 0; idx < devicePerProc[procIdx].size(); ++idx)
      {
        rankToChild.push_back(procIdx);
        rankToDevice.push_back(devicePerProc[procIdx][idx]);
        ++activeRanksCount;
      }
    }

    if (childList.size() > 0)
    {
      ERROR("DestroyComms must be called before re-initializing\n");
      return;
    }

    childList.resize(activeChildrenCount);
    for (int procIdx = 0; procIdx < activeChildrenCount; ++procIdx)
    {
      childList[procIdx] = new TestBedChild(procIdx, ev.verbose, ev.printValues, ev.useMultithreading);
      if (childList[procIdx]->InitPipes() != TEST_SUCCESS)
      {
        ERROR("Pipe creation failed\n");
        return;
      }

      pid_t childPid = fork();
      if (childPid == 0)
      {
        childList[procIdx]->StartExecutionLoop();
        return;
      }
      else
      {
        childList[procIdx]->pid = childPid;
        close(childList[procIdx]->childWriteFd);
        close(childList[procIdx]->childReadFd);
      }
    }

    if (ev.debugPause) {
      INFO("============================================================\n");
      INFO(" Pausing for debugger attach (e.g., sudo rocgdb -p <PID>)\n");
      INFO("============================================================\n");
      for (int pid = 0; pid < activeChildrenCount; ++pid) {
        INFO(" Process %02d: PID %d\n", pid, childList[pid]->pid);
      }
      INFO("============================================================\n");
      INFO("<Press Enter to continue>\n");
      scanf("%*c");
    }

    std::set<int> uniqueGpus;
    for (auto dev : rankToDevice)
      uniqueGpus.insert(dev);
    bool multiRankEnabled = uniqueGpus.size() < rankToDevice.size();

    // Request NCCL unique ID from first rank
    int getIdCmd = TestBedChild::CHILD_GET_UNIQUE_ID;
    SEND_TO_CHILD(0, getIdCmd);
    VERIFY_RESPONSE(0);

    ncclUniqueId id;
    RECV_FROM_CHILD(0, id);

    int const initCmd = TestBedChild::CHILD_INIT_COMMS;
    int rankBase = 0;
    for (int procIdx = 0; procIdx < activeChildrenCount; ++procIdx)
    {
      if (ev.verbose) INFO("Sending InitComms to process %d\n", procIdx);
      SEND_TO_CHILD(procIdx, initCmd);
      SEND_TO_CHILD(procIdx, id);
      SEND_TO_CHILD(procIdx, activeRanksCount);
      SEND_TO_CHILD(procIdx, rankBase);
      SEND_TO_CHILD(procIdx, groupCalls);
      SEND_TO_CHILD(procIdx, collsPerGroup);
      SEND_TO_CHILD(procIdx, blockingMode);
      SEND_TO_CHILD(procIdx, multiRankEnabled);
      SEND_TO_CHILD(procIdx, streamsPerGroup);

      int const gpuCount = devicePerProc[procIdx].size();
      SEND_TO_CHILD(procIdx, gpuCount);
      for (int g = 0; g < gpuCount; ++g)
        SEND_TO_CHILD(procIdx, devicePerProc[procIdx][g]);

      rankBase += gpuCount;
    }

    for (int procIdx = 0; procIdx < activeChildrenCount; ++procIdx)
    {
      VERIFY_RESPONSE(procIdx);
    }

    InteractiveWait("Completed Comms Setup");
  }

  void TestBed::SetupComms(std::vector<std::vector<int>> const& devicePerProc,
                           int const collsPerGroup, int const streamsPerGroup, int const groupCalls, bool const blockingMode)
  {
    SetupComms(devicePerProc, GetCollsPerGroup(collsPerGroup, groupCalls), GetStreamsPerGroup(streamsPerGroup, groupCalls), groupCalls, blockingMode);
  }

  void TestBed::SetupComms(int const numGpus, int const collsPerGroup, int const streamsPerGroup, int const groupCalls, bool const blockingMode)
  {
     const std::vector<int>& gpuOrder = ev.GetGpuPriorityOrder();
     SetupComms(GetDeviceIdsList(1, numGpus, gpuOrder), GetCollsPerGroup(collsPerGroup, groupCalls), GetStreamsPerGroup(streamsPerGroup, groupCalls), groupCalls, blockingMode);
  }

  void TestBed::SetCollectiveArgs(ncclFunc_t      const funcType,
                                  ncclDataType_t  const dataType,
                                  size_t          const inputSize,
                                  size_t          const outputSize,
                                  OptionalColArgs const &args,
                                  int             const collIdx,
                                  int             const groupIdx,
                                  int             const rank,
                                  int             const streamIdx)
  {
    InteractiveWait("Setting Collective Arguments");
    std::vector<int> ranksToApply;
    for (int r = 0; r < activeRanksCount; ++r)
      if (rank == -1 || rank == r) ranksToApply.push_back(r);

    if (streamIdx < 0 || streamIdx >= streamsPerGroup[groupIdx])
    {
      ERROR("Stream index %d out of bounds for group %d (max %d)\n", streamIdx, groupIdx, streamsPerGroup[groupIdx]);
      FAIL();
    }

    int const cmd = TestBedChild::CHILD_SET_COLL_ARGS;
    for (auto r : ranksToApply)
    {
      int const procId = rankToChild[r];
      SEND_TO_CHILD(procId, cmd);
      SEND_TO_CHILD(procId, r);
      SEND_TO_CHILD(procId, collIdx);
      SEND_TO_CHILD(procId, groupIdx);
      SEND_TO_CHILD(procId, funcType);
      SEND_TO_CHILD(procId, dataType);
      SEND_TO_CHILD(procId, inputSize);
      SEND_TO_CHILD(procId, outputSize);
      SEND_TO_CHILD(procId, streamIdx);
      SEND_TO_CHILD(procId, args);
      VERIFY_RESPONSE(procId);
    }

    InteractiveWait("Finished Setting Arguments");
  }

  void TestBed::AllocateMem(bool   const inPlace,
                            bool   const useManaged,
                            int    const groupIdx,
                            int    const collIdx,
                            int    const rank,
                            bool   const userRegistered)
  {
    InteractiveWait("Allocating Memory");
    std::vector<int> ranksToApply;
    for (int r = 0; r < activeRanksCount; ++r)
      if (rank == -1 || rank == r) ranksToApply.push_back(r);

    std::vector<int> groupsToApply;
    for (int g = 0; g < groupCallCount; ++g)
      if (groupIdx == -1 || groupIdx == g) groupsToApply.push_back(g);

    int const cmd = TestBedChild::CHILD_ALLOCATE_MEM;
    for (auto g : groupsToApply)
    {
      for (auto r : ranksToApply)
      {
        int const procId = rankToChild[r];
        SEND_TO_CHILD(procId, cmd);
        SEND_TO_CHILD(procId, r);
        SEND_TO_CHILD(procId, collIdx);
        SEND_TO_CHILD(procId, inPlace);
        SEND_TO_CHILD(procId, useManaged);
        SEND_TO_CHILD(procId, userRegistered);
        SEND_TO_CHILD(procId, g);
        VERIFY_RESPONSE(procId);
      }
    }

    InteractiveWait("Memory Allocation Complete");
  }

  void TestBed::PrepareData(int         const groupIdx,
                            int         const collIdx,
                            int         const rank,
                            CollFuncPtr const prepFunc)
  {
    InteractiveWait("Preparing Data");
    std::vector<int> ranksToApply;
    for (int r = 0; r < activeRanksCount; ++r)
      if (rank == -1 || rank == r) ranksToApply.push_back(r);

    std::vector<int> groupsToApply;
    for (int g = 0; g < groupCallCount; ++g)
      if (groupIdx == -1 || groupIdx == g) groupsToApply.push_back(g);

    int const cmd = TestBedChild::CHILD_PREPARE_DATA;
    for (auto g : groupsToApply)
    {
      for (auto r : ranksToApply)
      {
        int const procId = rankToChild[r];
        SEND_TO_CHILD(procId, cmd);
        SEND_TO_CHILD(procId, r);
        SEND_TO_CHILD(procId, g);
        SEND_TO_CHILD(procId, collIdx);
        SEND_TO_CHILD(procId, prepFunc);
        VERIFY_RESPONSE(procId);
      }
    }

    InteractiveWait("Data Preparation Complete");
  }

  void TestBed::ExecuteCollectives(std::vector<int> const &ranks, int const groupIdx,
                                   bool const useHipGraph)
  {
    InteractiveWait("Executing Collectives");
    int const cmd = TestBedChild::CHILD_EXECUTE_COLL;
    ++TestBed::NumTestsRun();

    std::vector<std::vector<int>> ranksPerProcess(activeChildrenCount);
    for (int r = 0; r < ranks.size(); ++r)
    {
      ranksPerProcess[rankToChild[ranks[r]]].push_back(r);
    }

    std::vector<int> groupsToApply;
    for (int g = 0; g < groupCallCount; ++g)
      if (groupIdx == -1 || groupIdx == g) groupsToApply.push_back(g);

    for (auto g : groupsToApply) {
      for (int procId = 0; procId < activeChildrenCount; ++procId)
      {
        if (ranks.empty() || !ranksPerProcess[procId].empty())
        {
          InteractiveWait("Executing for process " + std::to_string(procId));
          SEND_TO_CHILD(procId, cmd);
          SEND_TO_CHILD(procId, ev.timeoutUs);
          SEND_TO_CHILD(procId, g);
          SEND_TO_CHILD(procId, useHipGraph);
          int tempRanks = ranks.size();
          SEND_TO_CHILD(procId, tempRanks);
          for (int r = 0; r < ranks.size(); ++r)
            SEND_TO_CHILD(procId, ranks[r]);
        }
      }
    }

    for (int procId = 0; procId < activeChildrenCount; ++procId)
    {
      if (ranks.empty() || !ranksPerProcess[procId].empty()) VERIFY_RESPONSE(procId);
    }

    InteractiveWait("Collective Execution Complete");
  }

  void TestBed::ValidateResults(bool& success, int const groupIdx, int const collIdx, int const rank)
  {
    InteractiveWait("Validating Results");
    std::vector<int> ranksToApply;
    for (int r = 0; r < activeRanksCount; ++r)
      if (rank == -1 || rank == r) ranksToApply.push_back(r);

    std::vector<int> groupsToApply;
    for (int g = 0; g < groupCallCount; ++g)
      if (groupIdx == -1 || groupIdx == g) groupsToApply.push_back(g);

    int const cmd = TestBedChild::CHILD_VALIDATE_RESULTS;
    success = true;

    for (auto g : groupsToApply)
    {
      for (auto r : ranksToApply)
      {
        int const procId = rankToChild[r];
        SEND_TO_CHILD(procId, cmd);
        SEND_TO_CHILD(procId, r);
        SEND_TO_CHILD(procId, g);
        SEND_TO_CHILD(procId, collIdx);
        int response = 0;
        ASSERT_EQ(read(childList[procId]->parentReadFd, &response, sizeof(int)), sizeof(int));
        success &= (response == TEST_SUCCESS);
      }
    }

    ASSERT_EQ(success, true) << "Validation failed";
    InteractiveWait("Validation Complete");
  }

  void TestBed::LaunchGraphs(int const groupIdx)
  {
    InteractiveWait("Launching Graphs");
    std::vector<int> groupsToApply;
    for (int g = 0; g < groupCallCount; ++g)
      if (groupIdx == -1 || groupIdx == g) groupsToApply.push_back(g);

    int const cmd = TestBedChild::CHILD_LAUNCH_GRAPHS;
    for (auto g : groupsToApply)
    {
      for (int procId = 0; procId < activeChildrenCount; ++procId)
      {
        SEND_TO_CHILD(procId, cmd);
        SEND_TO_CHILD(procId, g);
        VERIFY_RESPONSE(procId);
      }
    }

    InteractiveWait("Graph Launch Complete");
  }

  void TestBed::DeallocateMem(int const groupIdx, int const collIdx, int const rank)
  {
    InteractiveWait("Deallocating Memory");
    std::vector<int> ranksToApply;
    for (int r = 0; r < activeRanksCount; ++r)
      if (rank == -1 || rank == r) ranksToApply.push_back(r);

    std::vector<int> groupsToApply;
    for (int g = 0; g < groupCallCount; ++g)
      if (groupIdx == -1 || groupIdx == g) groupsToApply.push_back(g);

    int const cmd = TestBedChild::CHILD_DEALLOCATE_MEM;
    for (auto g : groupsToApply)
    {
      for (auto r : ranksToApply)
