  void TestBed::DestroyComms()
  {
    InteractiveWait("Destroying Comms");
    int const cmd = TestBedChild::CHILD_DESTROY_COMMS;
    for (int procId = 0; procId < activeChildrenCount; ++procId)
    {
      SEND_TO_CHILD(procId, cmd);
      VERIFY_RESPONSE(procId);
    }
    Finalize();
    InteractiveWait("Comms Destroyed");
  }

  void TestBed::DestroyGraphs()
  {
    InteractiveWait("Destroying Graphs");
    int const cmd = TestBedChild::CHILD_DESTROY_GRAPHS;
    for (int g = 0; g < groupCallCount; ++g)
    {
      for (int procId = 0; procId < activeChildrenCount; ++procId)
      {
        SEND_TO_CHILD(procId, cmd);
        SEND_TO_CHILD(procId, g);
        VERIFY_RESPONSE(procId);
      }
    }
    InteractiveWait("Graphs Destroyed");
  }

  void TestBed::Finalize()
  {
    if (activeChildrenCount == 0)
      return;
    InteractiveWait("Finalizing");

    int const cmd = TestBedChild::CHILD_STOP;
    for (int procId = 0; procId < activeChildrenCount; ++procId)
    {
      SEND_TO_CHILD(procId, cmd);
      close(childList[procId]->parentWriteFd);
      close(childList[procId]->parentReadFd);
    }

    for (int procId = 0; procId < activeChildrenCount; ++procId)
    {
      int status = 0;
      waitpid(childList[procId]->pid, &status, 0);
      if (status != 0)
      {
        ERROR("Process %d exited with code %d\n", procId, status);
      }
      delete(childList[procId]);
    }
    childList.clear();

    activeChildrenCount = 0;
    activeRanksCount = 0;
    InteractiveWait("Finalization Complete");
  }

  TestBed::~TestBed()
  {
    Finalize();
  }

