//////////////////////////////////////////////////////////////////////////////
// Helper functions
//////////////////////////////////////////////////////////////////////////////
IGL_INLINE void igl::uniformly_sample_two_manifold(
  const Eigen::MatrixXd & point_coords,
  const Eigen::MatrixXi & triangle_indices,
  const int num_samples,
  const double expansion_factor,
  Eigen::MatrixXd & sampled_points)
{
  using namespace Eigen;
  using namespace std;

  // Compute Euclidean distance between two points on mesh using barycentric coordinates
  // Inputs:
  //   point_coords  #points by dim positions in weight space
  //   triangle_indices  #triangles by 3 vertex indices
  //   tri_idx_A  triangle index for first point
  //   bary_A  barycentric coords for first point
  //   tri_idx_B  triangle index for second point
  //   bary_B  barycentric coords for second point
  // Returns: Euclidean distance between points
  const auto & compute_barycentric_distance = [&point_coords, &triangle_indices] (
    const int tri_idx_A,
    const Eigen::Vector3d & bary_A,
    const int tri_idx_B,
    const Eigen::Vector3d & bary_B) -> double
  {
    Eigen::Vector3d point_A = 
      bary_A(0) * point_coords.row(triangle_indices(tri_idx_A, 0)) +
      bary_A(1) * point_coords.row(triangle_indices(tri_idx_A, 1)) +
      bary_A(2) * point_coords.row(triangle_indices(tri_idx_A, 2));

    Eigen::Vector3d point_B = 
      bary_B(0) * point_coords.row(triangle_indices(tri_idx_B, 0)) +
      bary_B(1) * point_coords.row(triangle_indices(tri_idx_B, 1)) +
      bary_B(2) * point_coords.row(triangle_indices(tri_idx_B, 2));

    return (point_A - point_B).norm();
  };

  // Handle tetrahedral meshes by extracting faces
  if(triangle_indices.cols() == 4)
  {
    verbose("uniform_sample.h: processing tetrahedral mesh\n");
    MatrixXi T0 = triangle_indices.col(0);
    MatrixXi T1 = triangle_indices.col(1);
    MatrixXi T2 = triangle_indices.col(2);
    MatrixXi T3 = triangle_indices.col(3);

    // Create face list from tetrahedra
    MatrixXi tri_faces =
      cat(1,
        cat(1,
          cat(2,T0, cat(2,T1,T2)),
          cat(2,T0, cat(2,T2,T3))),
        cat(1,
          cat(2,T0, cat(2,T3,T1)),
          cat(2,T1, cat(2,T3,T2)))
      );

    assert(tri_faces.rows() == 4 * triangle_indices.rows());
    assert(tri_faces.cols() == 3);
    uniformly_sample_two_manifold(point_coords, tri_faces, num_samples, expansion_factor, sampled_points);
    return;
  }

  double start_time = get_seconds();
  VectorXi sample_indices;

  // Initial sampling at vertices
  uniformly_sample_two_manifold_at_vertices(point_coords, num_samples, expansion_factor, sample_indices);
  verbose("Initial sampling time: %g\n", get_seconds() - start_time);

  slice(point_coords, sample_indices, colon<int>(0, point_cols(point_coords)-1), sampled_points);

  // Build vertex-to-triangle adjacency
  vector<vector<int> > vertex_to_faces, vertex_to_face_indices;
  vertex_triangle_adjacency(point_coords, triangle_indices, vertex_to_faces, vertex_to_face_indices);

  // Store face indices and barycentric coords for each sample
  vector<vector<int> > sample_triangles; 
  sample_triangles.resize(num_samples);

  vector<vector<Eigen::Vector3d> > sample_bary_coords; 
  sample_bary_coords.resize(num_samples);

  // Track current maxmin index for each sample
  vector<int> current_maxmin_index; 
  current_maxmin_index.resize(num_samples);

  // Distance matrices for each sample
  vector<MatrixXd> distance_matrices; 
  distance_matrices.resize(num_samples);

  // Identity matrix for corner computations
  MatrixXd identity_matrix(MatrixXd::Identity(point_cols(point_coords), point_cols(point_coords)));

  // Initialize seed locations as faces with barycentric coordinates
  for(int sample_idx = 0; sample_idx < num_samples; sample_idx++)
  {
    assert(vertex_to_faces[sample_indices(sample_idx)].size() > 0);
    sample_triangles[sample_idx].push_back(vertex_to_faces[sample_indices(sample_idx)][0]);

    Eigen::Vector3d bary(0, 0, 0);
    bary(vertex_to_face_indices[sample_indices(sample_idx)][0]) = 1;
    sample_bary_coords[sample_idx].push_back(bary);
    current_maxmin_index[sample_idx] = 0;
  }

  // Set initial radius and minimum threshold
  double current_radius = 1.0;
  double min_radius_threshold = 1e-5;
  int max_samples_per_face = 100;
  int max_attempts_per_face = 1000;
  int max_outer_iterations = 1000;

  // Iteratively refine sampling until radius is small enough
  while(current_radius > min_radius_threshold)
  {
    // Process each sample
    for(int sample_idx = 0; sample_idx < num_samples; sample_idx++)
    {
      int current_face = sample_triangles[sample_idx][current_maxmin_index[sample_idx]];
      Eigen::Vector3d current_bary(sample_bary_coords[sample_idx][current_maxmin_index[sample_idx]]);

      // Find vertex in face farthest from barycenter
      int vertex_in_face =
        (current_bary(0) > current_bary(1) ? (current_bary(0) > current_bary(2) ? 0 : 2)
                                           : (current_bary(1) > current_bary(2) ? 1 : 2));

      int closest_vertex = triangle_indices(current_face, vertex_in_face);
      vector<int> adjacent_faces = vertex_to_faces[closest_vertex];

      // Reset sample storage
      sample_bary_coords[sample_idx].clear();
      sample_triangles[sample_idx].clear();
      current_maxmin_index[sample_idx] = 0;

      sample_bary_coords[sample_idx].push_back(current_bary);
      sample_triangles[sample_idx].push_back(current_face);

      // Current position in weight space
      VectorXd current_position =
        current_bary(0) * point_coords.row(triangle_indices(current_face, 0)) +
        current_bary(1) * point_coords.row(triangle_indices(current_face, 1)) +
        current_bary(2) * point_coords.row(triangle_indices(current_face, 2));

#ifdef EXTREME_VERBOSE
      verbose("Sample %d:\n", sample_idx);
      verbose("Current face: %d\n", current_face);
      verbose("Vertex in face: %d\n", vertex_in_face);
      verbose("Closest vertex: %d\n", closest_vertex);
      verbose("Adjacent faces count: %d\n", adjacent_faces.size());
#endif

      // Sample around current position
      for(int f=0; f<(int)adjacent_faces.size(); f++)
      {
        int face_idx = adjacent_faces[f];
        int samples_in_face = 0;

        for(int attempt=0; attempt<max_attempts_per_face; attempt++)
        {
          // Generate random point in unit square
          double u_coord, v_coord;
          double rand_u = (double)rand() / RAND_MAX;
          double rand_v = (double)rand() / RAND_MAX;

          // Map to triangle
          if((rand_u + rand_v) > 1)
          {
            u_coord = 1 - rand_v;
            v_coord = 1 - rand_u;
          } else {
            u_coord = rand_u;
            v_coord = rand_v;
          }

          Eigen::Vector3d new_bary(u_coord, v_coord, 1 - u_coord - v_coord);
          double dist = compute_barycentric_distance(current_face, current_bary, face_idx, new_bary);

          // Add if within radius
          if(dist < current_radius)
          {
            sample_triangles[sample_idx].push_back(face_idx);
            sample_bary_coords[sample_idx].push_back(new_bary);
            samples_in_face++;
          }

          if(samples_in_face >= max_samples_per_face)
            break;

          if(attempt == (max_attempts_per_face - 1))
          {
#ifdef EXTREME_VERBOSE
            verbose("Max attempts reached for face %d\n", face_idx);
#endif
          }
        }
      }
    }

    // Precompute distances to other seeds and corners
    for(int sample_idx = 0; sample_idx < num_samples; sample_idx++)
    {
      distance_matrices[sample_idx].resize(sample_triangles[sample_idx].size(), num_samples + point_cols(point_coords));

      for(int s = 0; s < (int)sample_triangles[sample_idx].size(); s++)
      {
        int sample_face = sample_triangles[sample_idx][s];
        Eigen::Vector3d sample_bary = sample_bary_coords[sample_idx][s];

        // Distances to other seeds
        for(int j = 0; j < num_samples; j++)
        {
          double dist_val;
          if(sample_idx == j)
          {
            dist_val = 10.0;  // Large value for self
          } else {
            int other_face = sample_triangles[j][current_maxmin_index[j]];
            Eigen::Vector3d other_bary(sample_bary_coords[j][current_maxmin_index[j]]);
            dist_val = compute_barycentric_distance(sample_face, sample_bary, other_face, other_bary);
          }
          distance_matrices[sample_idx](s, j) = dist_val;
        }

        // Distances to corners
        for(int j = 0; j < point_cols(point_coords); j++)
        {
          Eigen::Vector3d point_in_space =
            sample_bary(0) * point_coords.row(triangle_indices(sample_face, 0)) +
            sample_bary(1) * point_coords.row(triangle_indices(sample_face, 1)) +
            sample_bary(2) * point_coords.row(triangle_indices(sample_face, 2));

          double dist_val = (point_in_space - identity_matrix.row(j)).norm() / expansion_factor;
          distance_matrices[sample_idx](s, num_samples + j) = dist_val;
        }
      }
    }

    // Optimize sample positions
    int iteration_count = 0;
    while(true)
    {
      bool any_moved = false;

      for(int sample_idx = 0; sample_idx < num_samples; sample_idx++)
      {
        VectorXd min_distances = distance_matrices[sample_idx].rowwise().minCoeff();
        assert(min_distances.size() == (int)sample_triangles[sample_idx].size());

        int old_index = current_maxmin_index[sample_idx];
        double best_distance = -2.0;

        for(int s = 0; s < (int)sample_triangles[sample_idx].size(); s++)
        {
          if(best_distance < min_distances(s))
          {
            best_distance = min_distances(s);
            current_maxmin_index[sample_idx] = s;
          }
        }

        any_moved |= (old_index != current_maxmin_index[sample_idx]);
      }

      if(!any_moved)
        break;

      iteration_count++;
      if(iteration_count >= max_outer_iterations)
      {
        verbose("Maximum iterations (%d) reached without convergence\n", max_outer_iterations);
        break;
      }
    }

    // Reduce radius
    current_radius *= 0.9;
  }

  // Finalize sampled points
  sampled_points.resize(num_samples, point_cols(point_coords));
  for(int i = 0; i < num_samples; i++)
  {
    int final_face = sample_triangles[i][current_maxmin_index[i]];
    Eigen::Vector3d final_bary(sample_bary_coords[i][current_maxmin_index[i]]);
    sampled_points.row(i) =
      final_bary(0) * point_coords.row(triangle_indices(final_face, 0)) +
      final_bary(1) * point_coords.row(triangle_indices(final_face, 1)) +
      final_bary(2) * point_coords.row(triangle_indices(final_face, 2));
  }

  verbose("Total sampling time: %g\n", get_seconds() - start_time);
}

IGL_INLINE void igl::uniformly_sample_two_manifold_at_vertices(
  const Eigen::MatrixXd & original_weights,
  const int k,
  const double push_factor,
  Eigen::VectorXi & selected_vertices)
{
  using namespace Eigen;
  using namespace std;

  const MatrixXd & weights = original_weights;

  // Partition weights to get initial seeds
  VectorXi partition_labels;
  Matrix<double,Dynamic,1>  dummy_vector;
  partition(weights, k + point_cols(weights), partition_labels, selected_vertices, dummy_vector);

  // Remove corner points (stored at beginning)
  selected_vertices = selected_vertices.segment(point_cols(weights), k).eval();

  MatrixXd selected_weights;
  slice(weights, selected_vertices, colon<int>(0, point_cols(weights)-1), selected_weights);

  int num_vertices = weights.rows();
  int num_dims = weights.cols();

  // Corner points in weight space
  MatrixXd corner_points = MatrixXd::Identity(num_dims, num_dims);

  // Combine original weights with corners
  MatrixXd combined_weights(num_vertices + num_dims, num_dims);
  combined_weights << weights, corner_points;

  // Prepare weights for seeds and corners
  MatrixXd seed_and_corner_weights(k + num_dims, num_dims);
  for(int i = 0; i < k; i++)
  {
    seed_and_corner_weights.row(i) = weights.row(selected_vertices(i));
  }
  for(int i = 0; i < num_dims; i++)
  {
    seed_and_corner_weights.row(i + k) = combined_weights.row(num_vertices + i);
  }

  // Compute all pairwise squared distances
  MatrixXd squared_distances;
  all_pairs_distances(combined_weights, seed_and_corner_weights, true, squared_distances);

  // Adjust corner distances by push factor
  squared_distances.block(0, k, squared_distances.rows(), num_dims) /= (push_factor * push_factor);

  int max_iterations = 30;
  int iter = 0;

  for(; iter < max_iterations; iter++)
  {
    bool changed = false;

    for(int i = 0; i < k; i++)
    {
      int old_index = selected_vertices(i);

      // Set large distance for current seed
      squared_distances.col(i).setZero();
      squared_distances.col(i).array() += 10.0;

      // Find farthest point from all other seeds
      MatrixXd min_distances = squared_distances.rowwise().minCoeff();
      MatrixXd::Index best_idx, dummy;
      min_distances.maxCoeff(&best_idx, &dummy);

      MatrixXd new_point = weights.row(best_idx);
      MatrixXd new_distances;
      all_pairs_distances(combined_weights, new_point, true, new_distances);
      squared_distances.col(i) = new_distances;

      selected_vertices(i) = best_idx;
      changed |= (best_idx != old_index);
    }

    if(!changed)
      break;
  }

  if(iter == max_iterations)
  {
    verbose("uniform_sample.h: Warning - maximum iterations reached\n");
  }
}

