#include "MovieSceneNiagaraParameterSectionTemplate.h"
#include "NiagaraComponent.h"
#include "NiagaraTypes.h"
#include "IMovieScenePlayer.h"

struct FActorStateRecord
{
	TWeakObjectPtr<UNiagaraComponent> ActorRef;
	TOptional<TArray<uint8>> SavedState;
};

struct FSectionRuntimeData : IPersistentEvaluationData
{
	TArray<FActorStateRecord> ComponentCache;
};

struct FPreviousParameterValueSnapshot : IMovieScenePreAnimatedToken
{
	FPreviousParameterValueSnapshot(FNiagaraVariable Var, TOptional<TArray<uint8>>&& PrevData)
		: Variable(Var)
		, PreviousData(PrevData)
	{
	}

	virtual void RestoreState(UObject& Target, IMovieScenePlayer& Player) override
	{
		UNiagaraComponent* NiagaraActor = Cast<UNiagaraComponent>(&Target);
		if (!PreviousData.IsSet())
		{
			NiagaraActor->GetOverrideParameters().RemoveParameter(Variable);
		}
		else
		{
			NiagaraActor->GetOverrideParameters().SetParameterData(PreviousData.GetValue().GetData(), Variable);
		}
	}

	FNiagaraVariable Variable;
	TOptional<TArray<uint8>> PreviousData;
};

struct FPreviousParameterValueCapture : IMovieScenePreAnimatedTokenProducer
{
	FPreviousParameterValueCapture(FNiagaraVariable Var)
		: Variable(Var)
	{
	}

	virtual IMovieScenePreAnimatedTokenPtr CacheExistingState(UObject& Object) const override
	{
		UNiagaraComponent* NiagaraActor = Cast<UNiagaraComponent>(&Object);
		const uint8* ExistingData = NiagaraActor->GetOverrideParameters().GetParameterData(Variable);
		TOptional<TArray<uint8>> StoredValue;

		if (ExistingData != nullptr)
		{
			TArray<uint8> TempBuffer;
			TempBuffer.AddUninitialized(Variable.GetSizeInBytes());
			FMemory::Memcpy(TempBuffer.GetData(), ExistingData, Variable.GetSizeInBytes());
			StoredValue.Emplace(MoveTemp(TempBuffer));
		}

		return FPreviousParameterValueSnapshot(Variable, MoveTemp(StoredValue));
	}

	FNiagaraVariable Variable;
};

struct FApplyParameterValueToken : IMovieSceneExecutionToken
{
	FApplyParameterValueToken(TWeakObjectPtr<UNiagaraComponent> InActor, FNiagaraVariable InVar, TArray<uint8>&& InBuffer)
		: ActorPtr(InActor)
		, Variable(InVar)
		, Buffer(std::move(InBuffer))
	{
	}

	virtual void Execute(const FMovieSceneContext& Context, const FMovieSceneEvaluationOperand& Operand, FPersistentEvaluationData& PersistentData, IMovieScenePlayer& Player) override
	{
		static FMovieSceneAnimTypeID TypeID = TMovieSceneAnimTypeID<FApplyParameterValueToken, 0>();
		UNiagaraComponent* NiagaraActor = ActorPtr.Get();
		if (NiagaraActor != nullptr)
		{
			Player.SavePreAnimatedState(*NiagaraActor, TypeID, FPreviousParameterValueCapture(Variable));
			NiagaraActor->GetOverrideParameters().AddParameter(Variable, false);
			NiagaraActor->GetOverrideParameters().SetParameterData(Buffer.GetData(), Variable);
		}
	}

	TWeakObjectPtr<UNiagaraComponent> ActorPtr;
	FNiagaraVariable Variable;
	TArray<uint8> Buffer;
};

FMovieSceneNiagaraParameterSectionTemplate::FMovieSceneNiagaraParameterSectionTemplate()
{
}

FMovieSceneNiagaraParameterSectionTemplate::FMovieSceneNiagaraParameterSectionTemplate(FNiagaraVariable InVar)
	: Parameter(InVar)
{}

void FMovieSceneNiagaraParameterSectionTemplate::Initialize(const FMovieSceneEvaluationOperand& Operand, const FMovieSceneContext& Context, FPersistentEvaluationData& PersistentData, IMovieScenePlayer& Player) const
{
	FSectionRuntimeData& RuntimeData = PersistentData.GetOrAddSectionData<FSectionRuntimeData>();
	RuntimeData.ComponentCache.Reset();

	for (TWeakObjectPtr<> ObjPtr : Player.FindBoundObjects(Operand))
	{
		UNiagaraComponent* NiagaraActor = Cast<UNiagaraComponent>(ObjPtr.Get());
		if (NiagaraActor != nullptr)
		{
			const uint8* ParamData = NiagaraActor->GetOverrideParameters().GetParameterData(Parameter);
			if (ParamData == nullptr)
			{
				ParamData = NiagaraActor->GetAsset()->GetExposedParameters().GetParameterData(Parameter);
			}

			TArray<uint8> CurrentState;
			if (ParamData != nullptr)
			{
				CurrentState.AddUninitialized(Parameter.GetSizeInBytes());
				FMemory::Memcpy(CurrentState.GetData(), ParamData, Parameter.GetSizeInBytes());
			}
			else
			{
				CurrentState.AddZeroed(Parameter.GetSizeInBytes());
			}

			FActorStateRecord Record;
			Record.ActorRef = NiagaraActor;
			Record.SavedState.Emplace(CurrentState);
			RuntimeData.ComponentCache.Add(Record);
		}
	}
}

void FMovieSceneNiagaraParameterSectionTemplate::Evaluate(const FMovieSceneEvaluationOperand& Operand, const FMovieSceneContext& Context, const FPersistentEvaluationData& PersistentData, FMovieSceneExecutionTokens& ExecutionTokens) const
{
	const FSectionRuntimeData* RuntimeData = PersistentData.FindSectionData<FSectionRuntimeData>();
	if (RuntimeData != nullptr)
	{
		for (const FActorStateRecord& Record : RuntimeData->ComponentCache)
		{
			if (Record.SavedState.IsSet())
			{
				TArray<uint8> InterpolatedData;
				GetParameterValue(Context.GetTime(), Record.SavedState.GetValue(), InterpolatedData);
				ExecutionTokens.Add(FApplyParameterValueToken(Record.ActorRef, Parameter, MoveTemp(InterpolatedData)));
			}
		}
	}
}

#include "origo/serialization/ISerializer.h"

namespace Origo {

static bool deserialize_vec3(ISerializer& serializer, Vec3& vector) {
    return serializer.try_read("x", vector.x) && 
           serializer.try_read("y", vector.y) && 
           serializer.try_read("z", vector.z);
}

static void serialize_vec3(ISerializer& serializer, const Vec3& vector) {
    serializer.write("x", vector.x);
    serializer.write("y", vector.y);
    serializer.write("z", vector.z);
}

bool ISerializer::try_read(std::string_view key, Vec3& value) {
    begin_object(key);
    bool success = deserialize_vec3(*this, value);
    end_object();
    return success;
}

bool ISerializer::try_read_array_object(Vec3& value) {
    if (!try_begin_array_object_read())
        return false;
    bool success = deserialize_vec3(*this, value);
    end_array_object();
    return success;
}

void ISerializer::write(std::string_view key, const Vec3& value) {
    begin_object(key);
    serialize_vec3(*this, value);
    end_object();
}

void ISerializer::write(const Vec3& value) {
    begin_array_object();
    serialize_vec3(*this, value);
    end_array_object();
}

void ISerializer::write(std::string_view key, const OptionalAssetHandle& opt_handle) {
    if (!opt_handle) {
        write(key, "0");
        return;
    }
    auto uuid = AssetManager::get_instance().get_uuid(*opt_handle);
    if (uuid.has_value())
        write(key, uuid->to_string());
    else
        write(key, "0");
}

void ISerializer::write(const OptionalAssetHandle& opt_handle) {
    if (!opt_handle) {
        write("0");
        return;
    }
    auto uuid = AssetManager::get_instance().get_uuid(*opt_handle);
    if (uuid.has_value())
        write(uuid->to_string());
    else
        write("0");
}

}

