    inline CompressedAABBVar create_compressed_bbox(const luisa::compute::Var<aabbData>& bbox,
        const luisa::compute::Float& flag1,
        const luisa::compute::Float& flag2)
    {
        CompressedAABBVar c;
        c[0][0] = bbox.cols[0].x;
        c[0][1] = bbox.cols[0].y;
        c[0][2] = bbox.cols[0].z;
        c[1][0] = bbox.cols[1].x;
        c[1][1] = bbox.cols[1].y;
        c[1][2] = bbox.cols[1].z;
        c[0][3] = flag1;
        c[1][3] = flag2;
        return c;
    }

    inline CompressedAABB create_compressed_bbox(const aabbData& bbox, const float flag1, const float flag2)
    {
        CompressedAABB c;
        c[0][0] = bbox.cols[0].x;
        c[0][1] = bbox.cols[0].y;
        c[0][2] = bbox.cols[0].z;
        c[1][0] = bbox.cols[1].x;
        c[1][1] = bbox.cols[1].y;
        c[1][2] = bbox.cols[1].z;
