                auto reduced_bbox = AABB::make_aabb(min_pos, max_pos);
                $if(vid % 256 == 0)
                {
                    const Uint blockIdx = 0;
                    sa_block_bbox->atomic(blockIdx).cols[0][0].fetch_min(reduced_bbox.cols[0][0]);
                    sa_block_bbox->atomic(blockIdx).cols[0][1].fetch_min(reduced_bbox.cols[0][1]);
                    sa_block_bbox->atomic(blockIdx).cols[0][2].fetch_min(reduced_bbox.cols[0][2]);
                    sa_block_bbox->atomic(blockIdx).cols[1][0].fetch_max(reduced_bbox.cols[1][0]);
                    sa_block_bbox->atomic(blockIdx).cols[1][1].fetch_max(reduced_bbox.cols[1][1]);
