EditChain::EditChain(QWidget *parent) : QWidget(parent), ui(new Ui::EditChain) {
    ui->setupUi(this);
}

EditChain::~EditChain() {
    delete ui;
}

void EditChain::onStart(std::shared_ptr<Configs::ProxyEntity> entry) {
    this->entry = entry;
    auto chainBean = this->entry->ChainBean();
    for (auto profileId : chainBean->sequence) {
        InsertProfileIfAvailable(profileId);
    }
}

bool EditChain::onEnd() {
    if (get_edit_text_name().isEmpty()) {
        MessageBoxWarning(app_name, tr("The name field must not be blank."));
        return false;
    }

    auto chainBean = this->entry->ChainBean();
    QList<int> idSequence;
    for (int index = 0; index < ui->listWidget->count(); ++index) {
        idSequence << ui->listWidget->item(index)->data(42).toInt();
    }
    chainBean->sequence = idSequence;
    return true;
}

void EditChain::on_select_profile_clicked() {
    // Hide the current dialog temporarily
    auto selector = new DialogGroupChooseProxy(this);
    selector->setWindowTitle(QCoreApplication::translate(
        "DialogGroupChooseProxy", "Add proxy"));
    QObject::connect(selector, &DialogGroupChooseProxy::set_proxy,
        this, [this](int id) {
            InsertProfileIfAvailable(id);
    });
    selector->show();
}

void EditChain::InsertProfileIfAvailable(int profileId) {
    auto entry = Configs::profileManager->GetProfile(profileId);
    if (entry != nullptr && entry->type != "chain" && entry->type != "extracore") {
        auto item = new QListWidgetItem();
        item->setData(42, profileId);
        auto widget = new ProxyItem(this, entry, item);
        ui->listWidget->addItem(item);
        ui->listWidget->setItemWidget(item, widget);

        // Update button handler
        connect(widget->get_change_button(), &QPushButton::clicked, widget, [=, this] {
            auto replacer = new DialogGroupChooseProxy(this);
            replacer->setWindowTitle(QCoreApplication::translate(
                "DialogGroupChooseProxy", "Replace %1 proxy").arg(widget->ent->bean->DisplayName()));
            QObject::connect(replacer, &DialogGroupChooseProxy::set_proxy,
                this, [widget, this](int newId) {
                    UpdateProxyItem(widget, newId);
            });
            replacer->show();
        });
    }
}

void EditChain::UpdateProxyItem(ProxyItem *widget, int profileId) {
    auto entry = Configs::profileManager->GetProfile(profileId);
    if (entry != nullptr && entry->type != "chain" && entry->type != "extracore") {
        widget->item->setData(42, profileId);
        widget->ent = entry;
        widget->refresh_data();
    }
}

