bool Locale::matchesOnly(const Locale& rhs, int mask) {
  if (rhs.flags() != mask) return false;
  if (mask & Component::LANG && m_lang != rhs.lang()) return false;
  if (mask & Component::COUNTRY && m_country != rhs.country()) return false;
  if (mask & Component::MODIFIER && m_modifier != rhs.modifier()) return false;
  return true;
}

int Locale::flags() const {
  int result = static_cast<int>(Component::LANG);
  if (m_country) result |= Component::COUNTRY;
  if (m_modifier) result |= Component::MODIFIER;
  return result;
}

Locale Locale::parse(std::string_view input) {
  enum class Section { Language, Territory, Charset, Variant } current = Section::Language;
  size_t pos = 0;
  std::string language;
  std::string territory;
  std::string charset;
  std::string variant;

  while (pos < input.size() && input[pos] != ']') {
    char ch = input[pos];
    switch (current) {
      case Section::Language: {
        if (std::isalpha(ch)) {
          language += ch;
        } else {
          if (ch == '_') {
            current = Section::Territory;
          } else if (ch == '.') {
            current = Section::Charset;
          } else if (ch == '@') {
            current = Section::Variant;
          }
        }
        break;
      }
      case Section::Territory: {
        if (std::isalpha(ch)) {
          territory += ch;
        } else {
          if (ch == '.') {
            current = Section::Charset;
          } else if (ch == '@') {
            current = Section::Variant;
          }
        }
        break;
      }
      case Section::Charset: {
        if (std::isalnum(ch)) {
          charset += ch;
        } else {
          if (ch == '@') {
            current = Section::Variant;
          }
        }
        break;
      }
      case Section::Variant: {
        if (std::isalpha(ch)) {
          variant += ch;
        }
        break;
      }
    }
    ++pos;
  }

  Locale result;
  result.setLang(language);
  if (!territory.empty()) result.setCountry(territory);
  if (!charset.empty()) result.setEncoding(charset);
  if (!variant.empty()) result.setModifier(variant);
  return result;
}

Locale::Locale() = default;

Locale::Locale(std::string_view data) { *this = Locale::parse(data); }

std::string Locale::toString() const {
  std::string output = lang();
  if (country()) {
    output += '_';
    output.append(*country());
  }
  if (encoding()) {
    output += '.';
    output.append(*encoding());
  }
  if (modifier()) {
    output += '@';
    output.append(*modifier());
  }
  return output;
}

std::ostream& operator<<(std::ostream& stream, const xdgpp::Locale& locale) {
  stream << locale.toString();
  return stream;
}

