#include "ztimer.h"

ZTimer::ZTimer() 
{
}

ZTimer::ZTimer(Duration time_ms) : m_duration(time_ms)
{
}

ZTimer::ZTimer(Duration time_ms, CallbackFunc handler)
            : m_duration(time_ms), m_handler(handler)
{
}

ZTimer::~ZTimer()
{
    Stop();
}

void ZTimer::Start()
{
    m_start = Clock::now();
    m_current = m_start;
    m_active = true;
    m_done = false;
}

void ZTimer::Stop()
{
    m_active = false;
}

void ZTimer::SetDuration(Duration time_ms)
{
    if (m_active)
        return;
    m_duration = time_ms;
}

void ZTimer::SetCallback(std::function<void()> handler)
{
    if (m_active)
        return;
    m_handler = handler;
}

void ZTimer::SetRepeating(bool enable)
{
    if (m_active)
        return;
    m_loop = enable;
}

void ZTimer::Update(Duration elapsed)
{
    if (!m_active)
        return;
    m_current += elapsed;
    if (m_current >= m_start + m_duration)
    {
        m_handler();
        if (!m_loop)
        {
            Stop();
            m_done = true;
        }
        else
            Start();
    }
}

