// Duplicate header inclusion removed for cleanliness (already present above)

std::wstring LoadCandidateHtml(const std::wstring &path)
{
    std::wifstream inputStream(path);
    if (!inputStream.is_open())
    {
        // TODO: Add logging here
        return L"";
    }
    // Configure locale for UTF-8 support
    inputStream.imbue(boost::locale::generator().generate("en_US.UTF-8"));
    std::wstringstream buffer;
    buffer << inputStream.rdbuf();
    return buffer.str();
}

int InitializeSciterCandidateHtml()
{
    std::wstring fullHtmlPath = fmt::format(                                             //
        L"{}\\{}\\resources\\ui\\sciter\\themes\\vertical_candidate_dark.html",          //
        string_to_wstring(CommonUtils::get_local_appdata_path()),                        //
        GlobalIme::ApplicationName                                                       //
    );
    std::wstring bodyHtmlPath = fmt::format(                                              //
        L"{}\\{}\\resources\\ui\\sciter\\themes\\body\\vertical_candidate_dark.html",     //
        string_to_wstring(CommonUtils::get_local_appdata_path()),                         //
        GlobalIme::ApplicationName                                                        //
    );

    bool isVerticalLayout = true;
    bool isNormalMode = true;

    if (!isVerticalLayout)
    {
        fullHtmlPath = L"/ui/sciter/themes/horizontal_candidate_dark.html";
        bodyHtmlPath = L"/ui/sciter/themes/body/horizontal_candidate_dark.html";

        if (isNormalMode)
        {
            fullHtmlPath = L"/ui/sciter/themes/horizontal_candidate_normal.html";
            bodyHtmlPath = L"/ui/sciter/themes/body/horizontal_candidate_normal.html";
        }
    }

    std::wstring mainTemplatePath = fullHtmlPath;
    std::wstring bodyTemplatePath = bodyHtmlPath;

    ::BodyContentString = LoadCandidateHtml(bodyTemplatePath);
    OutputDebugStringW(bodyTemplatePath.c_str());

    return 0;
}

void ExpandCandidateList(std::wstring &input)
{
    std::wstringstream stream(input);
    std::wstring segment;
    std::vector<std::wstring> items;
    int count = 0;
    int limit = 2;

    while (std::getline(stream, segment, L','))
    {
        items.push_back(segment);
        ++count;
    }

    int currentSize = static_cast<int>(items.size());
    while (static_cast<int>(items.size()) < 9)
    {
        items.emplace_back(L"");
    }

    std::wstring output = fmt::format( //
        ::BodyContentString,           //
        items[0],                      //
        items[1],                      //
        items[2],                      //
        items[3],                      //
        items[4],                      //
        items[5],                      //
        items[6],                      //
        items[7],                      //
        items[8]                       //
    );

    if (currentSize < 9)
    {
        std::wstring placeholder = fmt::format(L"<!--{}Anchor-->", currentSize);
        size_t anchorPos = output.find(placeholder);
        if (anchorPos != std::wstring::npos)
        {
            output = output.substr(0, anchorPos) + L"</div>";
        }
    }

    UpdateCandidateWindowContent(::main_window_handle, output.c_str());
}

SBOOL SC_CALLBACK ReplaceBodyContentCallback(HELEMENT element, LPVOID data)
{
    const wchar_t *replacementText = static_cast<const wchar_t *>(data);
    std::wstring wideStr(replacementText);
    std::string utf8Data = wstring_to_string(wideStr);

    SciterSetElementHtml(                  //
        element,                             //
        reinterpret_cast<const BYTE *>(utf8Data.c_str()), //
        static_cast<UINT>(utf8Data.length()),             //
        SIH_REPLACE_CONTENT                  // Preserves DOM/CSS integrity
    );

    return FALSE;
}

void UpdateCandidateWindowContent(HWND windowHandle, const wchar_t *newContent)
{
    HELEMENT rootElement = nullptr;
    if (SciterGetRootElement(windowHandle, &rootElement) != SCDOM_OK || !rootElement)
        return;

    // Reset UI state to prevent hover artifacts on first render
    SciterCallScriptingFunction(rootElement, L"ResetState", nullptr, 0, nullptr);

    SciterSelectElementsW(      //
        rootElement,            //
        WSTR("body"),           //
        ReplaceBodyContentCallback, //
        const_cast<LPVOID>(newContent) //
    );
}

int ComputeOptimalPosition( //
    HWND hwnd,               //
    int originX,             //
    int originY,             //
    int candidateWidth,      //
    int candidateHeight,     //
    int finalCoords[2]       //
)
{
    finalCoords[0] = originX;
    finalCoords[1] = originY + 3;

    MonitorCoordinates bounds = GetScreenBounds();

    if (finalCoords[0] < bounds.left)
        finalCoords[0] = bounds.left + 2;

    if (finalCoords[1] < bounds.top)
        finalCoords[1] = bounds.top + 2;

    if (finalCoords[0] + candidateWidth > bounds.right)
        finalCoords[0] = bounds.right - candidateWidth - 2;

    if (finalCoords[1] + ::cand_height_table[7] > bounds.bottom)
        finalCoords[1] = finalCoords[1] - candidateHeight - 30 - 2;

    return 0;
}

void SciterBridgeJs::resizeInitialWindow(sciter::value widthVal, sciter::value heightVal)
{
    int actualWidth = 0;
    if (widthVal.is_int())
        actualWidth = widthVal.get<int>();

    int actualHeight = 0;
    if (heightVal.is_int())
        actualHeight = heightVal.get<int>();

#ifdef FANY_DEBUG
    OutputDebugStringW(fmt::format(L"Candidate Window dimensions: {} x {}", actualWidth, actualHeight).c_str());
#endif

    ::CANDIDATE_WINDOW_WIDTH = actualWidth;
    ::DEFAULT_WINDOW_WIDTH = actualWidth;
    ::CANDIDATE_WINDOW_HEIGHT = actualHeight;
    ::cand_width_table[0] = actualWidth;
    ::cand_width_table[1] = actualWidth;

    UINT flags = SWP_NOZORDER | SWP_NOMOVE;
    SetWindowPos(                    //
        ::main_window_handle,        //
        nullptr,                     //
        0,                           //
        0,                           //
        actualWidth + ::BORDER_MARGIN,  //
        actualHeight + ::BORDER_MARGIN, //
        flags                        //
    );
}

void SciterBridgeJs::storeWindowSize(sciter::value indexVal, sciter::value widthVal, sciter::value heightVal)
{
    int currentIndex = 0;
    if (indexVal.is_int())
        currentIndex = indexVal.get<int>();

    int newWidth = 0;
    if (widthVal.is_int())
        newWidth = widthVal.get<int>();

    if (currentIndex < ::MAX_CANDIDATE_CHARS)
        ::cand_width_table[currentIndex] = newWidth;

    int newHeight = 0;
    if (heightVal.is_int())
        newHeight = heightVal.get<int>();

    if (currentIndex < ::MAX_CANDIDATE_CHARS)
        ::cand_height_table[currentIndex - 2] = newHeight;
}

#include "HexagonELFDynamic.h"
#include "HexagonLDBackend.h"
#include "eld/Target/ELFFileFormat.h"
#include "llvm/BinaryFormat/ELF.h"

using namespace eld;

HexagonELFDynamic::HexagonELFDynamic(GNULDBackend &pParent,
                                     LinkerConfig &pConfig)
    : ELFDynamic(pParent, pConfig) {}

HexagonELFDynamic::~HexagonELFDynamic() {}

void HexagonELFDynamic::reserveTargetEntries() {
  // Reserve entries for DT_HEXAGON_VER and DT_RELACOUNT
  reserveOne(eld::DT_HEXAGON_VER);
  reserveOne(llvm::ELF::DT_RELACOUNT);
}

void HexagonELFDynamic::applyTargetEntries() {
  applyOne(eld::DT_HEXAGON_VER, 0x4);

  uint32_t count = 0;
  for (auto &entry : m_Backend.getRelaDyn()->getRelocations()) {
    if ((*entry).type() == llvm::ELF::R_HEX_RELATIVE)
      count++;
  }
  applyOne(llvm::ELF::DT_RELACOUNT, count);
}

