#include <random>
#include <iostream>
#include <Eigen/Core>
#include <Eigen/Geometry>
#include <glk/path.hpp>
#include <glk/frame_buffer.hpp>
#include <glk/console_colors.hpp>
#include <glk/effects/screen_scape_attribute_estimation.hpp>

namespace glk {

ScreenSpaceAttributeEstimation::ScreenSpaceAttributeEstimation(const Eigen::Vector2i& dimensions, BufferType buffer_mode) {
  if (!texture_shader.init(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/texture.frag")) {
    return;
  }
  if (!position_shader.init(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/ssae_pos.frag")) {
    return;
  }
  if (!surface_normal_shader.init(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/ssae_normal.frag")) {
    return;
  }
  if (!ambient_occlusion_shader.init(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/ssae_ao.frag")) {
    return;
  }
  if (!bilateral_filter_shader.init(get_data_path() + "/shader/texture.vert", get_data_path() + "/shader/bilateral.frag")) {
    return;
  }
  configure_size(dimensions);
  smooth_normals = true;
  this->buffer_mode = buffer_mode;

  // Initialize random vectors for ambient occlusion
  std::mt19937 rng_engine;
  auto generate_random_unit_vector = [&] {
    double angle_u = std::uniform_real_distribution<>(0.0, 1.0)(rng_engine);
    double height_v = std::uniform_real_distribution<>(-1.0, 1.0)(rng_engine);
    double radius_w = std::uniform_real_distribution<>(0.0, 1.0)(rng_engine);
    double radial_distance = radius_w * 1.0;
    Eigen::Vector3f vector;
    vector.x() = radial_distance * std::sqrt(1 - height_v * height_v) * std::cos(2.0 * M_PI * angle_u);
    vector.y() = radial_distance * std::sqrt(1 - height_v * height_v) * std::sin(2.0 * M_PI * angle_u);
    vector.z() = radial_distance * height_v;
    return vector;
  };

  std::vector<Eigen::Vector3f> sample_directions(16);
  for (auto& dir : sample_directions) {
    dir = generate_random_unit_vector();
  }

  std::vector<Eigen::Vector3f> noise_pattern(128 * 128);
  for (auto& vec : noise_pattern) {
    vec = generate_random_unit_vector().normalized();
  }

  noise_texture.reset(new glk::Texture(Eigen::Vector2i(128, 128), GL_RGB32F, GL_RGB, GL_FLOAT, noise_pattern.data()));
  noise_texture->bind();
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_NEAREST);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_NEAREST);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_S, GL_REPEAT);
  glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_WRAP_T, GL_REPEAT);
  noise_texture->unbind();

  position_shader.use();
  position_shader.set_uniform("depth_sampler", 0);

  surface_normal_shader.use();
  surface_normal_shader.set_uniform("depth_sampler", 0);
  surface_normal_shader.set_uniform("position_sampler", 1);
  surface_normal_shader.set_uniform("normal_sampler", 2);

  ambient_occlusion_shader.use();
  ambient_occlusion_shader.set_uniform("depth_sampler", 0);
  ambient_occlusion_shader.set_uniform("position_sampler", 1);
  ambient_occlusion_shader.set_uniform("normal_sampler", 2);
  ambient_occlusion_shader.set_uniform("noise_sampler", 3);
  ambient_occlusion_shader.set_uniform("occlusion_radius", 0.05f);
  ambient_occlusion_shader.set_uniform("sample_vectors", sample_directions);

  bilateral_filter_shader.use();
  bilateral_filter_shader.set_uniform("color_sampler", 0);
  bilateral_filter_shader.set_uniform("position_sampler", 1);
  bilateral_filter_shader.set_uniform("kernel_half_size", 10);
  bilateral_filter_shader.set_uniform("spatial_sigma", 10.0f);
  bilateral_filter_shader.set_uniform("depth_sigma", 0.01f);
}

ScreenSpaceAttributeEstimation::~ScreenSpaceAttributeEstimation() {}

void ScreenSpaceAttributeEstimation::configure_size(const Eigen::Vector2i& dimensions) {
  position_framebuffer.reset(new glk::FrameBuffer(dimensions, 0, false));
  position_framebuffer->add_color_buffer(0, GL_RGBA32F, GL_RGB, GL_FLOAT);  // position

  position_blur_x.reset(new glk::FrameBuffer(dimensions, 0, false));
  position_blur_x->add_color_buffer(0, GL_RGBA32F, GL_RGB, GL_FLOAT);

  position_blur_y.reset(new glk::FrameBuffer(dimensions, 0, false));
  position_blur_y->add_color_buffer(0, GL_RGBA32F, GL_RGB, GL_FLOAT);

  normal_framebuffer.reset(new glk::FrameBuffer(dimensions, 0, false));
  normal_framebuffer->add_color_buffer(0, GL_RGB32F, GL_RGB, GL_FLOAT);

  occlusion_framebuffer.reset(new glk::FrameBuffer(dimensions, 0, false));
  occlusion_framebuffer->add_color_buffer(0, GL_R32F, GL_RGB, GL_FLOAT);
  occlusion_framebuffer->add_color_buffer(1, GL_RGB32F, GL_RGB, GL_FLOAT);

  bilateral_blur_x.reset(new glk::FrameBuffer(dimensions, 0, false));
  bilateral_blur_x->add_color_buffer(0, GL_RGBA32F, GL_RGB, GL_FLOAT);

  bilateral_blur_y.reset(new glk::FrameBuffer(dimensions, 0, false));
  bilateral_blur_y->add_color_buffer(0, GL_RGBA32F, GL_RGB, GL_FLOAT);
}

void ScreenSpaceAttributeEstimation::set_smooth_normal(bool enable_smoothing) {
  smooth_normals = enable_smoothing;
}

void ScreenSpaceAttributeEstimation::set_rendering_buffer(BufferType mode) {
  buffer_mode = mode;
}

const glk::Texture& ScreenSpaceAttributeEstimation::position() const {
  return position_framebuffer->color();
}

const glk::Texture& ScreenSpaceAttributeEstimation::normal() const {
  return normal_framebuffer->color();
}

const glk::Texture& ScreenSpaceAttributeEstimation::occlusion() const {
  return bilateral_blur_y->color(0);
}

void ScreenSpaceAttributeEstimation::draw(
  const TextureRenderer& renderer,
  const glk::Texture& depth_map,
  const glk::Texture& raw_depth,
  const TextureRendererInput::Ptr& input,
  glk::FrameBuffer* output_buffer) {
  using namespace glk::console;
  glDisable(GL_DEPTH_TEST);

  // Compute positions from depth
  auto view_matrix = input->get<Eigen::Matrix4f>("view_matrix");
  auto proj_matrix = input->get<Eigen::Matrix4f>("projection_matrix");
  if (!view_matrix || !proj_matrix) {
    std::cerr << bold_red << "error: view and projection matrices must be set" << reset << std::endl;
    return;
  }

  Eigen::Matrix4f pv_matrix = (*proj_matrix) * (*view_matrix);
  Eigen::Matrix4f inv_pv_matrix = pv_matrix.inverse();
  Eigen::Vector2f inv_resolution = 1.0f / position_framebuffer->size().array().cast<float>();

  position_shader.use();
  position_shader.set_uniform("inv_projection_view_matrix", inv_pv_matrix);
  raw_depth.bind();
  position_framebuffer->bind();
  renderer.draw_plain(position_shader);
  position_framebuffer->unbind();

  if (smooth_normals) {
    // Bilateral smoothing of position buffer
    bilateral_filter_shader.use();
    bilateral_filter_shader.set_uniform("inv_frame_size", inv_resolution);
    bilateral_filter_shader.set_uniform("filter_axis", Eigen::Vector2f(1.0f, 0.0f));
    bilateral_filter_shader.set_uniform("is_second_pass", false);

    position_blur_x->bind();
    position_framebuffer->color(0).bind(GL_TEXTURE0);
    position_framebuffer->color(0).bind(GL_TEXTURE1);
    renderer.draw_plain(bilateral_filter_shader);
    position_blur_x->unbind();

    bilateral_filter_shader.set_uniform("filter_axis", Eigen::Vector2f(0.0f, 1.0f));
    bilateral_filter_shader.set_uniform("is_second_pass", true);

    position_blur_y->bind();
    position_blur_x->color().bind(GL_TEXTURE0);
    position_framebuffer->color().bind(GL_TEXTURE1);
    renderer.draw_plain(bilateral_filter_shader);
    position_blur_y->unbind();
  }

  // Compute normals
  Eigen::Vector3f camera_position = view_matrix->inverse().block<3, 1>(0, 3);
  surface_normal_shader.use();
  surface_normal_shader.set_uniform("camera_position", camera_position);
  surface_normal_shader.set_uniform("inv_frame_size", inv_resolution);
  normal_framebuffer->bind();

  raw_depth.bind(GL_TEXTURE0);
  if (smooth_normals) {
    position_blur_y->color().bind(GL_TEXTURE1);
  } else {
    position_framebuffer->color().bind(GL_TEXTURE1);
  }

  glActiveTexture(GL_TEXTURE2);
  auto normal_input = input->get<GLuint>("normal_texture");
  if (normal_input) {
    glBindTexture(GL_TEXTURE_2D, *normal_input);
  } else {
    glBindTexture(GL_TEXTURE_2D, 0);
  }

  glActiveTexture(GL_TEXTURE0);
  renderer.draw_plain(surface_normal_shader);
  normal_framebuffer->unbind();

  // Ambient occlusion estimation
  Eigen::Vector2f noise_scale = raw_depth.size().cast<float>().array() / noise_texture->size().cast<float>().array();
  ambient_occlusion_shader.use();
  ambient_occlusion_shader.set_uniform("depth_sampler", 0);
  ambient_occlusion_shader.set_uniform("position_sampler", 1);
  ambient_occlusion_shader.set_uniform("normal_sampler", 2);
  ambient_occlusion_shader.set_uniform("noise_sampler", 3);
  ambient_occlusion_shader.set_uniform("projection_view_matrix", pv_matrix);
  ambient_occlusion_shader.set_uniform("noise_coordinate_scale", noise_scale);

  occlusion_framebuffer->bind();
  raw_depth.bind(GL_TEXTURE0);
  position_framebuffer->color().bind(GL_TEXTURE1);
  normal_framebuffer->color().bind(GL_TEXTURE2);
  noise_texture->bind(GL_TEXTURE3);
  renderer.draw_plain(ambient_occlusion_shader);
  occlusion_framebuffer->unbind();

  // Bilateral filtering of AO
  bilateral_filter_shader.use();
  bilateral_filter_shader.set_uniform("inv_frame_size", inv_resolution);
  bilateral_filter_shader.set_uniform("filter_axis", Eigen::Vector2f(1.0f, 0.0f));
  bilateral_filter_shader.set_uniform("is_second_pass", false);

  bilateral_blur_x->bind();
  occlusion_framebuffer->color(0).bind(GL_TEXTURE0);
  position_framebuffer->color(0).bind(GL_TEXTURE1);
  renderer.draw_plain(bilateral_filter_shader);
  bilateral_blur_x->unbind();

  bilateral_filter_shader.set_uniform("filter_axis", Eigen::Vector2f(0.0f, 1.0f));
  bilateral_filter_shader.set_uniform("is_second_pass", true);

  bilateral_blur_y->bind();
  bilateral_blur_x->color().bind(GL_TEXTURE0);
  position_framebuffer->color().bind(GL_TEXTURE1);
  renderer.draw_plain(bilateral_filter_shader);
  bilateral_blur_y->unbind();

  if (buffer_mode != BufferType::NONE) {
    if (output_buffer) {
      output_buffer->bind();
    }

    const glk::Texture* display_list[] = {
      &raw_depth,
      &position_framebuffer->color(),
      &position_blur_x->color(),
      &position_blur_y->color(),
      &normal_framebuffer->color(),
      &occlusion_framebuffer->color(),
      &bilateral_blur_x->color(),
      &bilateral_blur_y->color()
    };

    const auto selected_texture = display_list[static_cast<int>(buffer_mode) - 1];
    selected_texture->bind();
    texture_shader.use();
    renderer.draw_plain(texture_shader);

    if (output_buffer) {
      output_buffer->unbind();
    }
  }

  glEnable(GL_DEPTH_TEST);
}

}  // namespace glk

