#include "Intersection/IntersectionQueries3.h"
template<typename RealType>
bool UE::Geometry::TestIntersection(const THalfspace3<RealType>& Plane, const TSphere3<RealType>& Ball)
{
	RealType DistanceFromPlane = Plane.Normal.Dot(Ball.Center) - Plane.Constant;
	return (DistanceFromPlane + Ball.Radius >= 0);
}
template<typename RealType>
bool UE::Geometry::TestIntersection(const THalfspace3<RealType>& Plane, const TCapsule3<RealType>& Capsule)
{
	RealType DistStart = Plane.Normal.Dot(Capsule.Segment.StartPoint()) - Plane.Constant;
	RealType DistEnd   = Plane.Normal.Dot(Capsule.Segment.EndPoint())   - Plane.Constant;
	return (TMathUtil<RealType>::Max(DistStart, DistEnd) + Capsule.Radius >= 0);
}
template<typename RealType>
bool UE::Geometry::TestIntersection(const THalfspace3<RealType>& Plane, const TOrientedBox3<RealType>& Box)
{
	RealType CenterDist = Plane.Normal.Dot(Box.Frame.Origin) - Plane.Constant;
	FVector3<RealType> AxisX, AxisY, AxisZ;
	Box.Frame.GetAxes(AxisX, AxisY, AxisZ);
	RealType ExtentRadius =
		TMathUtil<RealType>::Abs(Box.Extents.X * Plane.Normal.Dot(AxisX)) +
		TMathUtil<RealType>::Abs(Box.Extents.Y * Plane.Normal.Dot(AxisY)) +
		TMathUtil<RealType>::Abs(Box.Extents.Z * Plane.Normal.Dot(AxisZ));
	return (CenterDist + ExtentRadius >= 0);
}
