STHalfEdge::STHalfEdge(SkeletalTrapezoidationEdge info) : HalfEdge(info) {}

bool STHalfEdge::canGoUp(bool strict) const
{
    if (to->data.dist_to_boundary > from->data.dist_to_boundary)
        return true;

    if (to->data.dist_to_boundary < from->data.dist_to_boundary || strict)
        return false;

    // Edge connects vertices at equal distance; traverse upward recursively
    for (edge_t *candidate = next; candidate != twin; candidate = candidate->twin->next)
    {
        if (candidate->canGoUp())
            return true;

        assert(candidate->twin);
        if (!candidate->twin)
            return false;

        assert(candidate->twin->next);
        if (!candidate->twin->next)
            return true; // Vertex lies on boundary — unexpected
    }
    return false;
}

bool STHalfEdge::isUpward() const
{
    if (to->data.dist_to_boundary > from->data.dist_to_boundary)
        return true;

    if (to->data.dist_to_boundary < from->data.dist_to_boundary)
        return false;

    // Equidistant edge case: compare upward distances
    std::optional<coord_t> fwd_dist = this->distToGoUp();
    std::optional<coord_t> bwd_dist = twin->distToGoUp();

    if (fwd_dist && bwd_dist)
        return *fwd_dist < *bwd_dist;

    if (fwd_dist)
        return true;

    if (bwd_dist)
        return false;

    return to->p < from->p; // Tie-breaker using arbitrary coordinate ordering
}

std::optional<coord_t> STHalfEdge::distToGoUp() const
{
    if (to->data.dist_to_boundary > from->data.dist_to_boundary)
        return 0;

    if (to->data.dist_to_boundary < from->data.dist_to_boundary)
        return std::nullopt;

    // Recursively compute minimal upward path length
    std::optional<coord_t> min_dist;
    for (edge_t *candidate = next; candidate != twin; candidate = candidate->twin->next)
    {
        std::optional<coord_t> sub_dist = candidate->distToGoUp();
        if (sub_dist)
        {
            if (min_dist)
                min_dist = std::min(*min_dist, *sub_dist);
            else
                min_dist = sub_dist;
        }

        assert(candidate->twin);
        if (!candidate->twin)
            return std::nullopt;

        assert(candidate->twin->next);
        if (!candidate->twin->next)
            return 0; // Boundary vertex — should not happen
    }

    if (min_dist)
        *min_dist += (to->p - from->p).cast<int64_t>().norm();

    return min_dist;
}

STHalfEdge *STHalfEdge::getNextUnconnected()
{
    edge_t *cursor = static_cast<STHalfEdge *>(this);
    while (cursor->next)
    {
        cursor = cursor->next;
        if (cursor == this)
            return nullptr;
    }
    return cursor->twin;
}

STHalfEdgeNode::STHalfEdgeNode(SkeletalTrapezoidationJoint info, Point pos) : HalfEdgeNode(info, pos) {}

bool STHalfEdgeNode::isMultiIntersection()
{
    int odd_count = 0;
    edge_t *cursor = this->incident_edge;
    do
    {
        if (!cursor)
            return false;

        if (cursor->data.isCentral())
            ++odd_count;
    } while ((cursor = cursor->twin->next) != this->incident_edge);

    return odd_count > 2;
}

bool STHalfEdgeNode::isCentral() const
{
    edge_t *cursor = incident_edge;
    do
    {
        if (cursor->data.isCentral())
            return true;

        assert(cursor->twin);
        if (!cursor->twin)
            return false;
    } while ((cursor = cursor->twin->next) != incident_edge);

    return false;
}

bool STHalfEdgeNode::isLocalMaximum(bool strict) const
{
    if (data.dist_to_boundary == 0)
        return false;

    edge_t *cursor = incident_edge;
    do
    {
        if (cursor->canGoUp(strict))
            return false;

        assert(cursor->twin);
        if (!cursor->twin)
            return false;

        if (!cursor->twin->next)
            return false; // Boundary node
    } while ((cursor = cursor->twin->next) != incident_edge);

    return true;
}

void SkeletalTrapezoidationGraph::collapseSmallEdges(coord_t threshold)
{
    ankerl::unordered_dense::map<edge_t *, Edges::iterator> edge_map;
    ankerl::unordered_dense::map<node_t *, Nodes::iterator> node_map;

    for (auto it = edges.begin(); it != edges.end(); ++it)
        edge_map.emplace(&*it, it);

    for (auto it = nodes.begin(); it != nodes.end(); ++it)
        node_map.emplace(&*it, it);

    auto removeEdgeSafely =
        [this, &edge_map](edge_t *target, Edges::iterator &current_it, bool &updated_flag)
    {
        if (current_it != edges.end() && target == &*current_it)
            current_it = edges.erase(current_it);
        else
            edges.erase(edge_map[target]);

        updated_flag = true;
    };

    auto shortEnough = [threshold](node_t *a, node_t *b)
    {
        return shorter_then(a->p - b->p, threshold);
    };

    for (auto edge_it = edges.begin(); edge_it != edges.end();)
    {
        if (edge_it->prev)
        {
            ++edge_it;
            continue;
        }

        edge_t *cell_start = &*edge_it;
        edge_t *cell_end = cell_start;
        while (cell_end->next)
            cell_end = cell_end->next;

        edge_t *cell_mid = (cell_start->next == cell_end) ? nullptr : cell_start->next;
        bool modified = false;

        if (cell_mid && shortEnough(cell_mid->from, cell_mid->to))
        {
            assert(cell_mid->twin);
            if (!cell_mid->twin)
            {
                BOOST_LOG_TRIVIAL(warning) << "Quad edge missing twin.";
                ++edge_it;
                continue;
            }

            int iter_limit = 0;
            for (edge_t *adjacent = cell_end; adjacent && adjacent != cell_mid->twin;
                 adjacent = adjacent->twin->next)
            {
                adjacent->from = cell_mid->from;
                adjacent->twin->to = cell_mid->from;

                if (iter_limit++ > 50)
                    std::cerr << adjacent->from->p << " -> " << adjacent->to->p << '\n';

                if (iter_limit > 1000)
                    break;
            }

            if (cell_mid->from->incident_edge == cell_mid)
            {
                cell_mid->from->incident_edge = cell_mid->twin->next ?: cell_mid->prev->twin;
            }

            nodes.erase(node_map[cell_mid->to]);
            cell_mid->prev->next = cell_mid->next;
            cell_mid->next->prev = cell_mid->prev;
            cell_mid->twin->next->prev = cell_mid->twin->prev;
            cell_mid->twin->prev->next = cell_mid->twin->next;

            removeEdgeSafely(cell_mid->twin, edge_it, modified);
            removeEdgeSafely(cell_mid, edge_it, modified);
        }

        if (shortEnough(cell_start->from, cell_end->to) &&
            shortEnough(cell_start->to, cell_end->from))
        {
            cell_start->twin->to = cell_end->to;
            cell_end->to->incident_edge = cell_end->twin;

            if (cell_end->from->incident_edge == cell_end)
            {
                cell_end->from->incident_edge = cell_end->twin->next ?: cell_end->prev->twin;
            }

            nodes.erase(node_map[cell_start->from]);
            cell_start->twin->twin = cell_end->twin;
            cell_end->twin->twin = cell_start->twin;

            removeEdgeSafely(cell_start, edge_it, modified);
            removeEdgeSafely(cell_end, edge_it, modified);
        }

        if (!modified)
            ++edge_it;
    }
}

void SkeletalTrapezoidationGraph::makeRib(edge_t *&prev_edge, const Point &src_a,
                                          const Point &src_b)
{
    Point proj;
    Line(src_a, src_b).distance_to_infinite_squared(prev_edge->to->p, &proj);
    coord_t dist = (prev_edge->to->p - proj).cast<int64_t>().norm();
    prev_edge->to->data.dist_to_boundary = dist;
    assert(dist >= 0);

    nodes.emplace_front(SkeletalTrapezoidationJoint(), proj);
    node_t *new_node = &nodes.front();
    new_node->data.dist_to_boundary = 0;

    edges.emplace_front(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::EdgeType::EXTRA_VD));
    edge_t *up_edge = &edges.front();

    edges.emplace_front(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::EdgeType::EXTRA_VD));
    edge_t *down_edge = &edges.front();

    prev_edge->next = up_edge;
    up_edge->prev = prev_edge;
    up_edge->from = prev_edge->to;
    up_edge->to = new_node;
    up_edge->twin = down_edge;
    down_edge->twin = up_edge;
    down_edge->from = new_node;
    down_edge->to = prev_edge->to;
    new_node->incident_edge = down_edge;
    prev_edge = down_edge;
}

std::pair<SkeletalTrapezoidationGraph::edge_t *, SkeletalTrapezoidationGraph::edge_t *>
SkeletalTrapezoidationGraph::insertRib(edge_t &input_edge, node_t *mid_node)
{
    edge_t *prev_part = input_edge.prev;
    edge_t *next_part = input_edge.next;
    node_t *left_node = input_edge.from;
    node_t *right_node = input_edge.to;
    Point mid_point = mid_node->p;

    const Line source_line = getSource(input_edge);
    Point px;
    source_line.distance_to_squared(mid_point, &px);
    coord_t dist = (mid_point - px).cast<int64_t>().norm();
    assert(dist > 0);

    mid_node->data.dist_to_boundary = dist;
    mid_node->data.transition_ratio = 0;

    nodes.emplace_back(SkeletalTrapezoidationJoint(), px);
    node_t *source_vertex = &nodes.back();
    source_vertex->data.dist_to_boundary = 0;

    edge_t *first = &input_edge;
    edges.emplace_back(SkeletalTrapezoidationEdge());
    edge_t *second = &edges.back();

    edges.emplace_back(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::EdgeType::TRANSITION_END));
    edge_t *out_edge = &edges.back();

    edges.emplace_back(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::EdgeType::TRANSITION_END));
    edge_t *in_edge = &edges.back();

    if (prev_part)
        prev_part->next = first;

    first->next = out_edge;
    out_edge->next = nullptr;
    in_edge->next = second;
    second->next = next_part;

    if (next_part)
        next_part->prev = second;

    second->prev = in_edge;
    in_edge->prev = nullptr;
    out_edge->prev = first;
    first->prev = prev_part;

    first->to = mid_node;
    out_edge->to = source_vertex;
    in_edge->to = mid_node;
    second->to = right_node;

    first->from = left_node;
    out_edge->from = mid_node;
    in_edge->from = source_vertex;
    second->from = mid_node;

    left_node->incident_edge = first;
    mid_node->incident_edge = out_edge;
    source_vertex->incident_edge = in_edge;
    if (next_part)
        right_node->incident_edge = next_part;

    first->data.setIsCentral(true);
    out_edge->data.setIsCentral(false);
    in_edge->data.setIsCentral(false);
    second->data.setIsCentral(true);

    out_edge->twin = in_edge;
    in_edge->twin = out_edge;
    first->twin = nullptr;
    second->twin = nullptr;

    assert(second->prev->from->data.dist_to_boundary == 0);
    return std::make_pair(first, second);
}

SkeletalTrapezoidationGraph::edge_t *SkeletalTrapezoidationGraph::insertNode(edge_t *input_edge, Point mid, coord_t bead_cnt)
{
    edge_t *last_replaced = input_edge;
    nodes.emplace_back(SkeletalTrapezoidationJoint(), mid);
    node_t *mid_node = &nodes.back();

    edge_t *twin_edge = last_replaced->twin;
    last_replaced->twin = nullptr;
    twin_edge->twin = nullptr;

    std::pair<edge_t *, edge_t *> left_pair = insertRib(*last_replaced, mid_node);
    std::pair<edge_t *, edge_t *> right_pair = insertRib(*twin_edge, mid_node);

    edge_t *first_left = left_pair.first;
    last_replaced = left_pair.second;
    edge_t *first_right = right_pair.first;
    edge_t *last_right = right_pair.second;

    first_left->twin = last_right;
    last_right->twin = first_left;
    last_replaced->twin = first_right;
    first_right->twin = last_replaced;

    mid_node->data.bead_count = bead_cnt;
    return last_replaced;
}

Line SkeletalTrapezoidationGraph::getSource(const edge_t &edge) const
{
    const edge_t *start = &edge;
    while (start->prev)
        start = start->prev;

    const edge_t *end = &edge;
    while (end->next)
        end = end->next;

    return Line(start->from->p, end->to->p);
}

