namespace py = pybind11;
using namespace small_gicp;

void register_pointcloud_module(py::module& module) {
  // PointCloud binding
  py::class_<PointCloud, std::shared_ptr<PointCloud>>(module, "PointCloud")  //
    .def(
      py::init([](const Eigen::MatrixXd& coords) {
        if (coords.cols() != 3 && coords.cols() != 4) {
          std::cerr << "coordinates must be Nx3 or Nx4" << std::endl;
          return std::make_shared<PointCloud>();
        }
        auto cloud = std::make_shared<PointCloud>();
        cloud->resize(coords.rows());
        if (coords.cols() == 3) {
          for (size_t idx = 0; idx < coords.rows(); idx++) {
            cloud->point(idx) << coords.row(idx).transpose(), 1.0;
          }
        } else {
          for (size_t idx = 0; idx < coords.rows(); idx++) {
            cloud->point(idx) << coords.row(idx).transpose();
          }
        }
        return cloud;
      }),
      py::arg("coordinates"),
      R"""(
      PointCloud(coordinates: numpy.ndarray)
      Initialize a PointCloud from a coordinate array.
      Parameters
      ----------
      coordinates : numpy.ndarray, shape (n, 3) or (n, 4)
          Input point coordinates.
      )""")
    .def("__repr__", [](const PointCloud& cloud) { 
      return "small_gicp.PointCloud (" + std::to_string(cloud.size()) + " points)"; 
    })
    .def("__len__", [](const PointCloud& cloud) { return cloud.size(); })
    .def(
      "is_empty",
      &PointCloud::empty,
      R"pbdoc(
        Determine whether the point cloud contains no points.
        Returns
        -------
        is_empty : bool
            True if the point cloud has zero points.
        )pbdoc")
    .def(
      "num_points",
      &PointCloud::size,
      R"pbdoc(
        Retrieve the count of points in the cloud.
        Returns
        -------
        num_points : int
            Number of stored points.
        )pbdoc")
    .def(
      "get_points",
      [](const PointCloud& cloud) -> Eigen::MatrixXd { 
        return Eigen::Map<const Eigen::Matrix<double, -1, -1, Eigen::RowMajor>>(cloud.points[0].data(), cloud.size(), 4); 
      },
      R"pbdoc(
        Export points as an Nx4 matrix.
        Returns
        -------
        points : numpy.ndarray
            All points in homogeneous coordinates.
        )pbdoc")
    .def(
      "get_normals",
      [](const PointCloud& cloud) -> Eigen::MatrixXd { 
        return Eigen::Map<const Eigen::Matrix<double, -1, -1, Eigen::RowMajor>>(cloud.normals[0].data(), cloud.size(), 4); 
      },
      R"pbdoc(
        Export surface normals as an Nx4 matrix.
        Returns
        -------
        normals : numpy.ndarray
            All normals in homogeneous coordinates.
        )pbdoc")
    .def(
      "get_covariances",
      [](const PointCloud& cloud) { return cloud.covs; },
      R"pbdoc(
        Access covariance matrices associated with each point.
        Returns
        -------
        covariances : list of numpy.ndarray
            List of 4x4 covariance matrices.
        )pbdoc")
    .def(
      "get_point",
      [](const PointCloud& cloud, size_t index) -> Eigen::Vector4d { 
        return cloud.point(index); 
      },
      py::arg("index"),
      R"pbdoc(
        Fetch a specific point by index.
        Parameters
        ----------
        index : int
            Zero-based index of the desired point.
        Returns
        -------
        point : numpy.ndarray, shape (4,)
            Requested point in homogeneous coordinates.
        )pbdoc")
    .def(
      "get_normal",
      [](const PointCloud& cloud, size_t index) -> Eigen::Vector4d { 
        return cloud.normal(index); 
      },
      py::arg("index"),
      R"pbdoc(
        Fetch a specific normal by index.
        Parameters
        ----------
        index : int
            Zero-based index of the desired normal.
        Returns
        -------
        normal : numpy.ndarray, shape (4,)
            Requested normal in homogeneous coordinates.
        )pbdoc")
    .def(
      "get_covariance",
      [](const PointCloud& cloud, size_t index) -> Eigen::Matrix4d { 
        return cloud.cov(index); 
      },
      py::arg("index"),
      R"pbdoc(
        Fetch a specific covariance matrix by index.
        Parameters
        ----------
        index : int
            Zero-based index of the desired covariance matrix.
        Returns
        -------
        covariance : numpy.ndarray, shape (4, 4)
            Requested 4x4 covariance matrix.
        )pbdoc");
}

#include <QApplication>
#include <uibase/linklabel.h>

QColor LinkLabel::m_linkColor;

// Constructor for LinkLabel
LinkLabel::LinkLabel(QWidget* parent) : QLabel(parent) {}

// Getter for the link color
QColor LinkLabel::linkColor() const
{
  return m_linkColor;
}

// Setter for the link color with global palette update
void LinkLabel::setLinkColor(const QColor& newColor)
{
  if (m_linkColor != newColor) {
    m_linkColor = newColor;
    // Update the application-wide palette since Qt doesn't support per-widget link colors
    if (qApp) {
      auto currentPalette = qApp->palette();
      currentPalette.setColor(QPalette::Link, newColor);
      currentPalette.setColor(QPalette::LinkVisited, newColor);
      qApp->setPalette(currentPalette);
    }
  }
}

#include "shaderprogram.hpp"
#include "glm/gtc/type_ptr.hpp"
#include "opengl.hpp"
#include <stdexcept>

const char *vertexShaderSource = R"(
#version 330 core
layout (location = 0) in vec2 pos;
layout (location = 1) in vec2 uv;
out vec2 UVCoords;
uniform mat4 projMatrix;
void main()
{
    gl_Position = projMatrix * vec4(pos, 0.0, 1.0);
    UVCoords = uv;
}
)";

const char *fragmentShaderSource = R"(
#version 330 core
in vec2 UVCoords;
out vec4 fragColor;
uniform sampler2D textureSampler;
uniform vec4 textCol;
uniform vec4 rectCol;
uniform int drawMode;
uniform vec4 boxBounds;
uniform float blurRadius; // Shadow blur radius in pixels
uniform vec4 radii; // top-left, top-right, bottom-right, bottom-left

float boxSDF(vec2 p, vec2 b) {
    vec2 d = abs(p) - b;
    return length(max(d, 0.0)) + min(max(d.x, d.y), 0.0);
}

float roundedBoxSDF(vec2 p, vec2 b, float r) {
    vec2 q = abs(p) - b + r;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - r;
}

float roundedBoxSDFPerCorner(vec2 p, vec2 b, vec4 r) {
    float radius;
    if (p.x < 0.0 && p.y < 0.0) {
        radius = r.x; // top-left
    } else if (p.x >= 0.0 && p.y < 0.0) {
        radius = r.y; // top-right
    } else if (p.x >= 0.0 && p.y >= 0.0) {
        radius = r.z; // bottom-right
    } else {
        radius = r.w; // bottom-left
    }
    vec2 q = abs(p) - b + radius;
    return min(max(q.x, q.y), 0.0) + length(max(q, 0.0)) - radius;
}

void main()
{
   if (drawMode == 0) { // Text
       vec4 sampled = vec4(1.0, 1.0, 1.0, texture(textureSampler, UVCoords).r);
       fragColor = textCol * sampled;
   } else if (drawMode == 1) { // ColoredText
       fragColor = texture(textureSampler, UVCoords);
   } else if (drawMode == 2) { // Rectangle
       fragColor = rectCol;
   } else if (drawMode == 3) { // Shadow
      vec2 center = boxBounds.xy + boxBounds.zw * 0.5;
      vec2 size = boxBounds.zw;
      vec2 pixelPos = gl_FragCoord.xy;
      vec2 localPos = pixelPos - center;
      float dist = boxSDF(localPos, size * 0.5);
      float shadowAlpha = 1.0 - smoothstep(0.0, blurRadius, dist);
      fragColor = vec4(vec3(0.0), 0.25 * shadowAlpha);
   } else if (drawMode == 4) { // RoundedRectangle
      vec2 center = boxBounds.xy + boxBounds.zw * 0.5;
      vec2 size = boxBounds.zw;
      vec2 pixelPos = gl_FragCoord.xy;
      vec2 localPos = pixelPos - center;
      float dist = roundedBoxSDFPerCorner(localPos, size * 0.5, radii);
      float alpha = 1.0 - smoothstep(-1.0, 1.0, dist);
      fragColor = vec4(rectCol.rgb, rectCol.a * alpha);
   } else if (drawMode == 5) { // RoundedShadow
      vec2 center = boxBounds.xy + boxBounds.zw * 0.5;
      vec2 size = boxBounds.zw;
      vec2 pixelPos = gl_FragCoord.xy;
      vec2 localPos = pixelPos - center;
      float dist = roundedBoxSDFPerCorner(localPos, size * 0.5, radii);
      float shadowAlpha = 1.0 - smoothstep(0.0, blurRadius, dist);
      fragColor = vec4(vec3(0.0), 0.25 * shadowAlpha);
   }
}";

opengl::ShaderProgram::ShaderProgram() {
}

void opengl::ShaderProgram::compile() {
    unsigned int vs = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vs, 1, &vertexShaderSource, NULL);
    glCompileShader(vs);
    int success;
    char infoLog[512];
    glGetShaderiv(vs, GL_COMPILE_STATUS, &success);
    if (!success) {
        glGetShaderInfoLog(vs, 512, NULL, infoLog);
        throw std::runtime_error("Vertex shader compilation failed: " + std::string(infoLog));
    }

    unsigned int fs = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fs, 1, &fragmentShaderSource, NULL);
    glCompileShader(fs);
    glGetShaderiv(fs, GL_COMPILE_STATUS, &success);
    if (!success) {
        glGetShaderInfoLog(fs, 512, NULL, infoLog);
        throw std::runtime_error("Fragment shader compilation failed: " + std::string(infoLog));
    }

    m_shader_program = glCreateProgram();
    glAttachShader(m_shader_program, vs);
    glAttachShader(m_shader_program, fs);
    glLinkProgram(m_shader_program);

    glGetProgramiv(m_shader_program, GL_LINK_STATUS, &success);
    if (!success) {
        glGetProgramInfoLog(m_shader_program, 512, NULL, infoLog);
        throw std::runtime_error("Shader program linking failed: " + std::string(infoLog));
    }

    glDeleteShader(vs);
    glDeleteShader(fs);

    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
}

void opengl::ShaderProgram::use() {
    glUseProgram(m_shader_program);
}

void opengl::ShaderProgram::setRenderType(opengl::RenderType type) {
    setInt("drawMode", (int)type);
    if (type == RenderType::ColoredText) {
        glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
    } else {
        glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    }
}

void opengl::ShaderProgram::setFloat(const std::string &name, float value) {
    glUniform1f(glGetUniformLocation(m_shader_program, name.c_str()), value);
}

void opengl::ShaderProgram::setInt(const std::string& name, int value) {
    glUniform1i(glGetUniformLocation(m_shader_program, name.c_str()), value);
}

void opengl::ShaderProgram::setVector4f(const std::string& name, float x, float y, float z, float w) {
    glUniform4f(glGetUniformLocation(m_shader_program, name.c_str()), x, y, z, w);
}

void opengl::ShaderProgram::setMatrix4(const std::string& name, const glm::mat4& mat) {
    glUniformMatrix4fv(glGetUniformLocation(m_shader_program, "projMatrix"), 1, GL_FALSE, glm::value_ptr(mat));
}

#include "client_singleton.h"
#include "SocketCommand.h"

// Read a block of memory from a remote process
bool FetchProcessMemoryBytes(uint64_t offset, uint32_t length,
                             std::vector<unsigned char> &buffer, PortType channel) {
    return SocketCommand::execute(channel, [&](WindowsSocketClient* client, int descriptor) -> bool {
#pragma pack(1)
        struct { unsigned char opcode; CeReadProcessMemoryInput params; } request;
#pragma pack()
        request.opcode = CMD_READPROCESSMEMORY;
        request.params.descriptor = descriptor;
        request.params.offset = offset;
        request.params.length = length;
        request.params.compression = 0;
        if (!client->Transmit(&request, sizeof(request)))
            return false;
        CeReadProcessMemoryOutput responseHeader{};
        if (!client->Receive(&responseHeader, sizeof(responseHeader)))
            return false;
        buffer.resize(length);
        client->Receive(buffer.data(), buffer.size());
        if (responseHeader.bytesRead <= 0) {
            buffer.clear();
            return false;
        }
        return true;
    });
}

// Write a block of memory to a remote process
bool StoreProcessMemoryBytes(uint64_t offset, uint32_t length,
                             std::vector<unsigned char> &source, PortType channel) {
    return SocketCommand::execute(channel, [&](WindowsSocketClient* client, int descriptor) -> bool {
#pragma pack(1)
        struct { unsigned char opcode; CeWriteProcessMemoryInput params; } request;
#pragma pack()
        request.opcode = CMD_WRITEPROCESSMEMORY;
        request.params.descriptor = descriptor;
        request.params.offset = offset;
        request.params.length = length;
        if (!client->Transmit(&request, sizeof(request)))
            return false;
        client->Transmit(source.data(), source.size());
        CeWriteProcessMemoryOutput result;
        if (!client->Receive(&result, sizeof(result)))
            return false;
        return result.bytesWritten == length;
    });
}

// Read memory into a raw buffer with explicit read count
bool FetchProcessMemoryRaw(uint64_t offset, uint32_t length, void *destination,
                           int32_t &actualRead, PortType channel) {
    return SocketCommand::execute(channel, [&](WindowsSocketClient* client, int descriptor) -> bool {
#pragma pack(1)
        struct { unsigned char opcode; CeReadProcessMemoryInput params; } request;
#pragma pack()
        request.opcode = CMD_READPROCESSMEMORY;
        request.params.descriptor = descriptor;
        request.params.offset = offset;
        request.params.length = length;
        request.params.compression = 0;
        if (!client->Transmit(&request, sizeof(request)))
            return false;
        client->Receive(&actualRead, sizeof(actualRead));
        client->Receive(destination, length);
        if (actualRead <= 0)
            return false;
        return true;
    });
}

// Read multiple memory blocks in batch
bool FetchBatchMemory(uint64_t baseOffset, uint32_t blockSize,
                      std::vector<std::pair<uint64_t, std::vector<uint8_t>>> &results,
                      PortType channel) {
    return SocketCommand::execute(channel, [&](WindowsSocketClient* client, int descriptor) -> bool {
#pragma pack(1)
        struct { unsigned char opcode; int descriptor; uint64_t baseOffset; uint32_t blockSize; } request;
#pragma pack()
        request.opcode = CMD_READBRATCHMEMORY;
        request.descriptor = descriptor;
        request.baseOffset = baseOffset;
        request.blockSize = blockSize;
        if (!client->Transmit(&request, sizeof(request)))
            return false;
        int count = 0;
        if (!client->Receive(&count, sizeof(count)))
            return false;
        if (count <= 0) {
            results.clear();
            return true;
        }
        results.resize(count);
        for (int index = 0; index < count; index++) {
            uint64_t currentAddr = 0;
            std::vector<unsigned char> chunk(4096);
            if (!client->Receive(&currentAddr, sizeof(currentAddr)))
                return false;
            if (!client->Receive(chunk.data(), 4096))
                return false;
            results[index] = {currentAddr, chunk};
        }
        return true;
    });
}

// Read specific addresses in batch using provided address-size pairs
bool FetchBatchAddresses(std::vector<std::pair<uint64_t, int32_t>> &addresses,
                         std::vector<std::pair<uint64_t, std::vector<uint8_t>>> &results,
                         PortType channel) {
    return SocketCommand::execute(channel, [&](WindowsSocketClient* client, int descriptor) -> bool {
        unsigned char command = CMD_READBRATCHADDR;
        if (!SocketCommand::sendCommandWithHandle(client, command, descriptor))
            return false;
        int count = addresses.size();
        if (!client->Transmit(&count, sizeof(count)))
            return false;
        std::vector<CeReadBratchAddr> requests(count);
        for (int index = 0; index < count; index++) {
            requests[index].address = addresses[index].first;
            requests[index].size = addresses[index].second;
        }
        if (!client->Transmit(requests.data(), count * sizeof(CeReadBratchAddr)))
            return false;
        results.clear();
        results.resize(count);
        int status = 0;
        if (!client->Receive(&status, sizeof(status)))
            return false;
        for (int index = 0; index < count; index++) {
            uint64_t currentAddr = 0;
            int32_t requestedSize = requests[index].size;
            std::vector<unsigned char> data(requestedSize);
            if (!client->Receive(&currentAddr, sizeof(currentAddr)))
                return false;
            if (!client->Receive(data.data(), requestedSize))
                return false;
            results[index] = {currentAddr, data};
        }
        return true;
    });
}

#include "quadrants/rhi/amdgpu/amdgpu_device.h"
#include "quadrants/rhi/llvm/device_memory_pool.h"
#include "quadrants/jit/jit_module.h"

namespace quadrants {
namespace lang {
namespace amdgpu {

AmdgpuDevice::AmdgpuDevice() {
  // Initialize the device memory pool
  DeviceMemoryPool::get_instance(Arch::amdgpu, false /*merge_upon_release*/);
}

AmdgpuDevice::AllocInfo AmdgpuDevice::get_alloc_info(
    const DeviceAllocation handle) {
  validate_device_alloc(handle);
  return allocations_[handle.alloc_id];
}

RhiResult AmdgpuDevice::allocate_memory(const AllocParams &params,
                                        DeviceAllocation *out_devalloc) {
  AllocInfo info;
  auto &mem_pool = DeviceMemoryPool::get_instance(Arch::amdgpu,
                                                  false /*merge_upon_release*/);
  bool managed = params.host_read || params.host_write;
  void *ptr =
      mem_pool.allocate(params.size, DeviceMemoryPool::page_size, managed);
  if (ptr == nullptr) {
    return RhiResult::out_of_memory;
  }
  info.ptr = ptr;
  info.size = params.size;
  info.is_imported = false;
  info.use_cached = false;
  info.use_preallocated = false;
  if (info.ptr == nullptr) {
    return RhiResult::out_of_memory;
  }
  AMDGPUDriver::get_instance().memset((void *)info.ptr, 0, info.size);
  *out_devalloc = DeviceAllocation{};
  out_devalloc->alloc_id = allocations_.size();
  out_devalloc->device = this;
  allocations_.push_back(info);
  return RhiResult::success;
}

DeviceAllocation AmdgpuDevice::allocate_memory_runtime(
    const LlvmRuntimeAllocParams &params) {
  AllocInfo info;
  info.size = quadrants::iroundup(params.size, quadrants_page_size);
  if (params.host_read || params.host_write) {
    QD_NOT_IMPLEMENTED
  } else {
    info.ptr = DeviceMemoryPool::get_instance(Arch::amdgpu,
                                              false /*merge_upon_release*/)
                   .allocate_with_cache(this, params);
    QD_ASSERT(info.ptr != nullptr);
    AMDGPUDriver::get_instance().memset((void *)info.ptr, 0, info.size);
  }
  info.is_imported = false;
  info.use_cached = true;
  info.use_preallocated = true;
  DeviceAllocation alloc;
  alloc.alloc_id = allocations_.size();
  alloc.device = this;
  allocations_.push_back(info);
  return alloc;
}

uint64_t *AmdgpuDevice::allocate_llvm_runtime_memory_jit(
    const LlvmRuntimeAllocParams &params) {
  params.runtime_jit->call<void *, std::size_t, std::size_t>(
      "runtime_memory_allocate_aligned", params.runtime, params.size,
      quadrants_page_size, params.result_buffer);
  AMDGPUDriver::get_instance().stream_synchronize(nullptr);
  uint64 *result{nullptr};
  AMDGPUDriver::get_instance().memcpy_device_to_host(&result, params.result_buffer,
                                                     sizeof(uint64));
  return result;
}

void AmdgpuDevice::dealloc_memory(DeviceAllocation handle) {
  // After reset, all allocations are invalid
  if (allocations_.empty()) {
    return;
  }
  validate_device_alloc(handle);
  AllocInfo &info = allocations_[handle.alloc_id];
  if (info.ptr == nullptr) {
    QD_ERROR("the DeviceAllocation is already deallocated");
  }
  QD_ASSERT(!info.is_imported);
  if (info.use_cached) {
    DeviceMemoryPool::get_instance(Arch::amdgpu, false /*merge_upon_release*/)
        .release(info.size, (uint64_t *)info.ptr, false);
  } else if (!info.use_preallocated) {
    DeviceMemoryPool::get_instance(Arch::amdgpu, false /*merge_upon_release*/)
        .release(info.size, info.ptr);
  }
  info.ptr = nullptr;
}

RhiResult AmdgpuDevice::map(DeviceAllocation alloc, void **mapped_ptr) {
  AllocInfo &info = allocations_[alloc.alloc_id];
  size_t size = info.size;
  info.mapped = new char[size];
  // FIXME: there should be a better way to do this...
  AMDGPUDriver::get_instance().memcpy_device_to_host(info.mapped, info.ptr,
                                                     size);
  *mapped_ptr = info.mapped;
  return RhiResult::success;
}

void AmdgpuDevice::unmap(DeviceAllocation alloc) {
  AllocInfo &info = allocations_[alloc.alloc_id];
  AMDGPUDriver::get_instance().memcpy_host_to_device(info.ptr, info.mapped,
                                                     info.size);
  delete[] static_cast<char *>(info.mapped);
  return;
}

void AmdgpuDevice::memcpy_internal(DevicePtr dst,
                                   DevicePtr src,
                                   uint64_t size) {
  void *dst_ptr =
      static_cast<char *>(allocations_[dst.alloc_id].ptr) + dst.offset;
  void *src_ptr =
      static_cast<char *>(allocations_[src.alloc_id].ptr) + src.offset;
  AMDGPUDriver::get_instance().memcpy_device_to_device(dst_ptr, src_ptr, size);
}

DeviceAllocation AmdgpuDevice::import_memory(void *ptr, size_t size) {
  AllocInfo info;
  info.ptr = ptr;
  info.size = size;
  info.is_imported = true;
  DeviceAllocation alloc;
  alloc.alloc_id = allocations_.size();
  alloc.device = this;
  allocations_.push_back(info);
  return alloc;
}

