// Mutex lock manager for FFmpeg thread safety
static int ffmpeg_boost_mutex_lock_manager(void **mutex, enum AVLockOp op)
{
  if (NULL == mutex)
    return -1;
  switch (op)
  {
    case AV_LOCK_CREATE:
    {
      *mutex = NULL;
      boost::mutex *m = new boost::mutex();
      *mutex = static_cast<void *>(m);
      break;
    }
    case AV_LOCK_OBTAIN:
    {
      boost::mutex *m = static_cast<boost::mutex *>(*mutex);
      m->lock();
      break;
    }
    case AV_LOCK_RELEASE:
    {
      boost::mutex *m = static_cast<boost::mutex *>(*mutex);
      m->unlock();
      break;
    }
    case AV_LOCK_DESTROY:
    {
      boost::mutex *m = static_cast<boost::mutex *>(*mutex);
      m->lock();
      m->unlock();
      delete m;
      break;
    }
    default:
      break;
  }
  return 0;
}

// Constructor with parameterized defaults
LibavStreamer::LibavStreamer(const async_web_server_cpp::HttpRequest &request,
                             async_web_server_cpp::HttpConnectionPtr connection, ros::NodeHandle& nh,
                             const std::string &format_name, const std::string &codec_name,
                             const std::string &content_type) :
    ImageTransportImageStreamer(request, connection, nh), output_format_(0), fmt_ctx_(0), encoder_(0), enc_ctx_(0), video_stream_(
        0), frame_(0), sws_ctx_(0), first_image_received_(false), first_image_time_(), format_name_(
        format_name), codec_name_(codec_name), content_type_(content_type), opt_(0), io_buffer_(0)
{
  // Set encoding parameters from request query or use defaults
  bitrate_ = request.get_query_param_value_or_default<int>("bitrate", 200000);
  qmin_ = request.get_query_param_value_or_default<int>("qmin", 8);
  qmax_ = request.get_query_param_value_or_default<int>("qmax", 40);
  gop_ = request.get_query_param_value_or_default<int>("gop", 30);

#if ( LIBAVCODEC_VERSION_INT  < AV_VERSION_INT(58,9,100) )
  av_lockmgr_register(&ffmpeg_boost_mutex_lock_manager);
  av_register_all();
#endif
}

// Destructor with proper cleanup
LibavStreamer::~LibavStreamer()
{
  if (enc_ctx_)
  {
    #if ( LIBAVCODEC_VERSION_INT  < AV_VERSION_INT(58,9,100) )
    avcodec_close(enc_ctx_);
    #else
    avcodec_free_context(&enc_ctx_);
    #endif
  }
  if (frame_)
  {
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
    av_free(frame_);
    frame_ = NULL;
#else
    av_frame_free(&frame_);
#endif
  }
  if (io_buffer_)
    delete[] io_buffer_;
  if (fmt_ctx_) {
    if (fmt_ctx_->pb)
      av_free(fmt_ctx_->pb);
    avformat_free_context(fmt_ctx_);
  }
  if (sws_ctx_)
    sws_freeContext(sws_ctx_);
}

