}

// Initialize encoder components
void LibavStreamer::initialize(const cv::Mat &img)
{
  // Allocate format context
  fmt_ctx_ = avformat_alloc_context();
  if (!fmt_ctx_)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Error allocating FFmpeg format context");
  }

  // Determine output format
  output_format_ = av_guess_format(format_name_.c_str(), NULL, NULL);
  if (!output_format_)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Error looking up output format");
  }
  fmt_ctx_->oformat = output_format_;

  // Setup custom IO context
  size_t io_buffer_size = 4 * 1024;    // Increased buffer size for better performance
  io_buffer_ = new unsigned char[io_buffer_size];
  AVIOContext* io_ctx = avio_alloc_context(io_buffer_, io_buffer_size, AVIO_FLAG_WRITE, &connection_, NULL, dispatch_output_packet, NULL);
  if (!io_ctx)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Error setting up IO context");
  }
  io_ctx->seekable = 0;                       // no seeking, it's a stream
  fmt_ctx_->pb = io_ctx;
  fmt_ctx_->max_interleave_delta = 0;
  output_format_->flags |= AVFMT_FLAG_CUSTOM_IO;
  output_format_->flags |= AVFMT_NOFILE;

  // Load encoder
  if (codec_name_.empty()) // use default encoder if none specified
    encoder_ = avcodec_find_encoder(output_format_->video_codec);
  else
    encoder_ = avcodec_find_encoder_by_name(codec_name_.c_str());
  if (!encoder_)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Error looking up encoder");
  }

  video_stream_ = avformat_new_stream(fmt_ctx_, encoder_);
  if (!video_stream_)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Error creating video stream");
  }

  #if ( LIBAVCODEC_VERSION_INT  < AV_VERSION_INT(58,9,100) )
  enc_ctx_ = video_stream_->codec;
  #else
  enc_ctx_ = avcodec_alloc_context3(encoder_);
  #endif

  // Configure encoder context
  avcodec_get_context_defaults3(enc_ctx_, encoder_);
  enc_ctx_->codec_id = encoder_->id;
  enc_ctx_->bit_rate = bitrate_;
  enc_ctx_->width = output_width_;
  enc_ctx_->height = output_height_;
  enc_ctx_->delay = 0;
  video_stream_->time_base.num = 1;
  video_stream_->time_base.den = 1000;
  enc_ctx_->time_base.num = 1;
  enc_ctx_->time_base.den = 1;
  enc_ctx_->gop_size = gop_;
  enc_ctx_->pix_fmt = AV_PIX_FMT_YUV420P;
  enc_ctx_->max_b_frames = 0;

  // Quality settings
  enc_ctx_->qmin = qmin_;
  enc_ctx_->qmax = qmax_;

  #if ( LIBAVCODEC_VERSION_INT  >= AV_VERSION_INT(58,9,100) )
  avcodec_parameters_from_context(video_stream_->codecpar, enc_ctx_);
  #endif

  setupEncoder();
  enc_ctx_->flags |= AV_CODEC_FLAG_LOW_DELAY;
  enc_ctx_->max_b_frames = 0;

  // Open encoder
  if (avcodec_open2(enc_ctx_, encoder_, NULL) < 0)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Could not open video encoder");
  }

  // Allocate frame buffers
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
  frame_ = avcodec_alloc_frame();
#else
  frame_ = av_frame_alloc();
#endif
  av_image_alloc(frame_->data, frame_->linesize, output_width_, output_height_,
          enc_ctx_->pix_fmt, 1);
  frame_->width = output_width_;
  frame_->height = output_height_;
  frame_->format = enc_ctx_->pix_fmt;
  output_format_->flags |= AVFMT_NOFILE;

  // Generate header metadata
  av_dict_set(&fmt_ctx_->metadata, "author", "ROS web_video_server", 0);
  av_dict_set(&fmt_ctx_->metadata, "title", topic_.c_str(), 0);

  // Send response headers
  async_web_server_cpp::HttpReply::builder(async_web_server_cpp::HttpReply::ok).header("Connection", "close").header(
      "Server", "web_video_server").header("Cache-Control",
                                           "no-cache, no-store, must-revalidate, pre-check=0, post-check=0, max-age=0").header(
      "Pragma", "no-cache").header("Expires", "0").header("Max-Age", "0").header("Trailer", "Expires").header(
      "Content-type", content_type_).header("Access-Control-Allow-Origin", "*").write(connection_);

  // Write stream header
  if (avformat_write_header(fmt_ctx_, &opt_) < 0)
  {
    async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request__,
                                                                                                         connection_,
                                                                                                         NULL, NULL);
    throw std::runtime_error("Error opening dynamic buffer");
  }
}

