#include "shared.h"
#include "x86_pointer_emulation.h"

// Maximum number of pointer entries supported in the register pool
static constexpr uint32_t kMaxPointerEntries = 65536;

// Storage for tracked pointers
static std::array<void*, kMaxPointerEntries> sPointerStorage;

// Free list for reusing pointer IDs
static std::queue<uint32_t> sFreeIDList;

// Next available ID to assign (starts at 1 since 0 is reserved)
static uint32_t sNextAvailableID = 1;

// Check if a pointer ID is invalid (uninitialized or sentinel value)
inline bool IsInvalidPointerID(uint32_t id) {
    return id == OTDUPointer::kInvalidID || id == 0xcdcdcdcd ||
           id == 0xdddddddd || id == 0x0;
}

// Acquire a new pointer entry ID from free list or allocate new one
static uint32_t GetNewPointerEntry() {
    uint32_t entryID = OTDUPointer::kInvalidID;

    if (!sFreeIDList.empty()) {
        entryID = sFreeIDList.front();
        sFreeIDList.pop();
    } else {
        entryID = sNextAvailableID++;
    }

    return entryID;
}

// Initialize the pointer storage array with a null entry at index 0
static bool SetupPointerStorage() {
    sPointerStorage[0] = nullptr;
    return true;
}

// Constructor: initialize storage and acquire an ID for this pointer
OTDUPointer::OTDUPointer() {
    SetupPointerStorage(); // TODO: Consider moving initialization to module startup

    OTDU_ASSERT_FATAL(sNextAvailableID < kMaxPointerEntries);

    if (!sFreeIDList.empty()) {
        ID = sFreeIDList.front();
        sFreeIDList.pop();
    } else {
        ID = sNextAvailableID++;
    }
}

// Destructor: return ID to free list for reuse
OTDUPointer::~OTDUPointer() {
    if (!IsInvalidPointerID(ID)) {
        sFreeIDList.push(ID);
    }
}

// Assignment operator: associate raw pointer with this object's ID
OTDUPointer& OTDUPointer::operator=(const void* pPointer) {
    OTDU_ASSERT(ID != OTDUPointer::kInvalidID);

    if (IsInvalidPointerID(ID)) {
        ID = GetNewPointerEntry();
    }

    sPointerStorage[ID] = const_cast<void*>(pPointer);
    return *this;
}

// Retrieve the stored pointer associated with this object's ID
void* OTDUPointer::retrievePointerFromCache() const {
    return !IsInvalidPointerID(ID) ? sPointerStorage[ID] : nullptr;
}

