class TreeKEMTestVariant
{
protected:
  const CipherSuite cipher{ CipherSuite::ID::P256_AES128GCM_SHA256_P256 };

  std::tuple<HPKEPrivateKey, SignaturePrivateKey, LeafNode> generate_leaf()
  {
    auto key_priv = HPKEPrivateKey::generate(cipher);
    auto sign_priv = SignaturePrivateKey::generate(cipher);
    auto credential = Credential::basic({ 0xA, 0xB, 0xC });
    auto node = LeafNode(cipher,
                         key_priv.public_key,
                         sign_priv.public_key,
                         credential,
                         Capabilities::create_default(),
                         Lifetime::create_default(),
                         {},
                         sign_priv);
    return std::make_tuple(key_priv, sign_priv, node);
  }
};

TEST_CASE_METHOD(TreeKEMTestVariant, "ParentNode Equivalence")
{
  auto initX = HPKEPrivateKey::generate(cipher);
  auto initY = HPKEPrivateKey::generate(cipher);
  auto nodeX =
    ParentNode{ initX.public_key, { 5, 6 }, { LeafIndex(3), LeafIndex(4) } };
  auto nodeY =
    ParentNode{ initY.public_key, { 9, 10 }, { LeafIndex(7), LeafIndex(8) } };

  REQUIRE(nodeX == nodeX);
  REQUIRE(nodeY == nodeY);
  REQUIRE(nodeX != nodeY);
}

TEST_CASE_METHOD(TreeKEMTestVariant, "Node Public Key Extraction")
{
  auto parent_key = HPKEPrivateKey::generate(cipher);
  auto parent_node = Node{ ParentNode{ parent_key.public_key, {}, {} } };
  REQUIRE(parent_node.public_key() == parent_key.public_key);

  auto [leaf_key_, sig_key, leaf] = generate_leaf();
  auto leaf_key = leaf_key_;
  silence_unused(sig_key);

  auto leaf_wrapper = Node{ leaf };
  REQUIRE(leaf_wrapper.public_key() == leaf_key.public_key);
}

TEST_CASE_METHOD(TreeKEMTestVariant, "TreeKEM Private Key Operations")
{
  const auto tree_size = LeafCount{ 7 };
  const auto updater_idx = LeafIndex{ 2 };
  const auto entrant_idx = LeafIndex{ 4 };
  const auto entropy = random_bytes(32);
  const auto priv_init = HPKEPrivateKey::derive(cipher, entropy);
  const auto priv_secondary = HPKEPrivateKey::generate(cipher);
  const auto hash_len = cipher.digest().hash_size;

  // Build a sparse tree with N leaves
  auto pub_tree = TreeKEMPublicKey(cipher);
  for (uint32_t idx = 0; idx < tree_size.val; ++idx) {
    auto [_leaf_key, _sig_key, leaf] = generate_leaf();
    pub_tree.add_leaf(leaf);
  }

  // create() populates path secrets along the direct path
  auto priv_created = TreeKEMPrivateKey::create(pub_tree, updater_idx, entropy);
  REQUIRE(priv_created.path_secrets.count(NodeIndex(3)) > 0);
  REQUIRE(priv_created.path_secrets.count(NodeIndex(1)) > 0);
  REQUIRE(priv_created.path_secrets.count(NodeIndex(7)) > 0);
  REQUIRE(priv_created.path_secrets.count(NodeIndex(15)) > 0);
  REQUIRE(priv_created.update_secret.size() == hash_len);

  // Manually populate internal nodes above the new member
  pub_tree.node_at(NodeIndex{ 1 }) = OptionalNode{ Node{ ParentNode{} } };
  pub_tree.node_at(NodeIndex{ 7 }) = OptionalNode{ Node{ ParentNode{} } };
  pub_tree.node_at(NodeIndex{ 15 }) = OptionalNode{ Node{ ParentNode{} } };

  // joiner() initializes leaf + ancestors but not middle path
  auto priv_entrant = TreeKEMPrivateKey::joiner(
    pub_tree, entrant_idx, priv_init, entrant_idx.ancestor(updater_idx), entropy);
  REQUIRE(priv_entrant.private_key(NodeIndex(8)));
  REQUIRE(priv_entrant.path_secrets.count(NodeIndex(7)) > 0);
  REQUIRE(priv_entrant.path_secrets.count(NodeIndex(15)) > 0);
  REQUIRE(priv_entrant.path_secrets.count(NodeIndex(3)) == 0);
  REQUIRE(priv_entrant.update_secret.size() == hash_len);

  auto prior_update_secret = priv_entrant.update_secret;

  // set_leaf_priv() updates leaf secret without affecting update_secret
  priv_entrant.set_leaf_priv(priv_secondary);
  REQUIRE(priv_entrant.private_key(NodeIndex(entrant_idx)) == priv_secondary);
  REQUIRE(priv_entrant.update_secret.size() == hash_len);
  REQUIRE(priv_entrant.update_secret == prior_update_secret);

  // shared_path_secret() locates nearest common ancestor
  auto [common_node_, secret_, success_] = priv_entrant.shared_path_secret(LeafIndex(0));
  auto common_node = common_node_;
  auto secret = secret_;
  auto success = success_;
  REQUIRE(success);
  REQUIRE(common_node == NodeIndex(7));
  REQUIRE(secret == priv_entrant.path_secrets[common_node]);

  // private_key() caches or returns nullopt appropriately
  auto cached_key = priv_entrant.private_key(NodeIndex(7));
  REQUIRE(cached_key.has_value());
  REQUIRE(priv_entrant.private_key_cache.count(NodeIndex(7)) > 0);

  auto absent_key = priv_entrant.private_key(NodeIndex(1));
  REQUIRE_FALSE(absent_key.has_value());
}

//        _
//    _       _
//  X   _   _   _
// X X _ X X _ _ _
// 0123456789abcde
TEST_CASE_METHOD(TreeKEMTestVariant, "TreeKEM Public Key Construction")
{
  const auto leaf_count = LeafCount{ 6 };
  const auto removed_leaf = LeafIndex{ 3 };
  const auto root_resolution =
    std::vector<NodeIndex>{ NodeIndex{ 1 }, NodeIndex{ 10 }, NodeIndex{ 12 } };

  auto pub_tree = TreeKEMPublicKey{ cipher };
  for (uint32_t i = 0; i < leaf_count.val; ++i) {
    auto [_init_priv, _sig_priv, leaf_before_] = generate_leaf();
    auto leaf_before = leaf_before_;
    silence_unused(_init_priv);
    silence_unused(_sig_priv);

    auto index = LeafIndex(i);
    auto add_result = pub_tree.add_leaf(leaf_before);
    REQUIRE(add_result == index);

    auto found = pub_tree.find(leaf_before);
    REQUIRE(found);
    REQUIRE(*found == index);

    auto stored_leaf = pub_tree.leaf_node(index);
    REQUIRE(stored_leaf);
    REQUIRE(*stored_leaf == leaf_before);

    // Simulate direct path population
    const auto [_init_priv_next, sig_priv_next, leaf_after_] = generate_leaf();
    const auto leaf_after = leaf_after_;
    auto update_path = UpdatePath{ leaf_after, {} };
    auto dp = pub_tree.filtered_direct_path(NodeIndex(index));

    while (update_path.nodes.size() < dp.size()) {
      auto node_pub = HPKEPrivateKey::generate(cipher).public_key;
      update_path.nodes.emplace_back(node_pub, std::vector<uint8_t>{});
    }

    update_path.leaf_node.sign(cipher, sig_priv_next, std::nullopt);
    pub_tree.merge(index, update_path);

    const auto& updated_leaf = update_path.leaf_node;
    found = pub_tree.find(updated_leaf);
    REQUIRE(found);
    REQUIRE(*found == index);

    for (const auto& [node_idx, _res] : dp) {
      auto idx = node_idx;
      REQUIRE(pub_tree.node_at(idx).node.has_value());
    }

    stored_leaf = pub_tree.leaf_node(index);
    REQUIRE(stored_leaf);
    REQUIRE(*stored_leaf == updated_leaf);
  }

  pub_tree.blank_path(removed_leaf);
  REQUIRE_FALSE(pub_tree.leaf_node(removed_leaf));
  REQUIRE(root_resolution == pub_tree.resolve(NodeIndex::root(leaf_count)));
}

TEST_CASE_METHOD(TreeKEMTestVariant, "TreeKEM Encapsulation/Decapsulation")
{
  const auto group_size = LeafCount{ 8 };
  auto priv_list = std::vector<TreeKEMPrivateKey>{};
  auto pub_list = std::vector<TreeKEMPublicKey>{};
  auto sig_keys = std::vector<SignaturePrivateKey>{};

  auto [init_priv_0, sig_priv_0, leaf0] = generate_leaf();
  sig_keys.push_back(sig_priv_0);
  auto pub_initial = TreeKEMPublicKey{ cipher };
  auto index_0 = pub_initial.add_leaf(leaf0);
  pub_list.push_back(pub_initial);
  REQUIRE(index_0 == LeafIndex{ 0 });

  auto priv_initial = TreeKEMPrivateKey::solo(cipher, index_0, init_priv_0);
  priv_list.push_back(priv_initial);
  REQUIRE(priv_initial.consistent(pub_initial));

  auto group_id = from_ascii("cluster");

  for (uint32_t step = 0; step < group_size.val - 2; ++step) {
    auto adder = LeafIndex{ step };
    auto joiner = LeafIndex{ step + 1 };
    auto ctx = bytes{ static_cast<uint8_t>(step) };

    auto [init_priv_new, sig_priv_new, leaf_new] = generate_leaf();
    sig_keys.push_back(sig_priv_new);

    auto new_index = pub_list[step].add_leaf(leaf_new);
    REQUIRE(new_index == joiner);

    auto leaf_secret = random_bytes(32);
    pub_list[step].set_hash_all();

    priv_list[step] = pub_list[step].update(
      adder, leaf_secret, group_id, sig_keys[step], {});

    auto path = pub_list[step].encap(priv_list[step], ctx, {});
    REQUIRE(pub_list[step].parent_hash_valid(adder, path));

    auto [common_, secret_, ok_] = priv_list[step].shared_path_secret(joiner);
    auto ok = ok_;
    REQUIRE(ok);
    REQUIRE(priv_list[step].consistent(pub_list[step]));

    auto entrant_priv = TreeKEMPrivateKey::joiner(
      pub_list[step], joiner, init_priv_new, common_, secret_);
    priv_list.push_back(entrant_priv);
    pub_list.push_back(pub_list[step]);

    REQUIRE(priv_list[step + 1].consistent(priv_list[step]));
    REQUIRE(priv_list[step + 1].consistent(pub_list[step + 1]));

    for (uint32_t k = 0; k < step; ++k) {
      pub_list[k].add_leaf(leaf_new);
      pub_list[k].set_hash_all();
      priv_list[k].decap(adder, pub_list[k], ctx, path, {});
      pub_list[k].merge(adder, path);
      REQUIRE(priv_list[k].consistent(priv_list[step]));
      REQUIRE(priv_list[k].consistent(pub_list[k]));
    }
  }

  // Verify tree slices
  auto original_tree = pub_list[0];
  original_tree.set_hash_all();
  const auto expected_root_hash = original_tree.root_hash();

  auto slices = std::vector<TreeSlice>{};
  for (uint32_t pos = 0; pos < original_tree.size.val; ++pos) {
    auto slice = original_tree.extract_slice(LeafIndex{ pos });
    REQUIRE(slice.tree_hash(cipher) == expected_root_hash);
    slices.push_back(slice);
  }

  auto assembled = TreeKEMPublicKey(cipher, slices[0]);
  for (uint32_t pos = 1; pos < slices.size(); ++pos) {
    assembled.implant_slice(slices[pos]);
  }
  assembled.set_hash_all();
  REQUIRE(assembled.root_hash() == expected_root_hash);
  REQUIRE(assembled.parent_hash_valid());
}

TEST_CASE("TreeKEM Interoperability", "[.][all]")
{
  for (auto suite : all_supported_suites) {
    for (auto layout : treekem_test_tree_structures) {
      auto test_vector = TreeKEMTestVector{ suite, layout };
      REQUIRE(test_vector.verify() == std::nullopt);
    }
  }
}

