namespace {
// Singleton pattern for managing stencil controls
class StencilControlManager {
  QThreadStorage<TStencilControl *> m_storage;
  StencilControlManager() {}
public:
  static StencilControlManager *getInstance() {
    static StencilControlManager instance;
    return &instance;
  }
  TStencilControl *getActiveStencilControl() {
    if (!m_storage.hasLocalData()) {
      m_storage.setLocalData(new TStencilControl);
    }
    return m_storage.localData();
  }
  ~StencilControlManager() {}
};
}  // Anonymous namespace
//-----------------------------------------------------------------------------------------
class TStencilControl::Implementation {
public:
  int m_stencilPlaneCount;
  int m_depthCounter;
  int m_activePlane;  // Index of the currently active stencil bit plane.
                      // -1 indicates no active writing plane.
  int m_virtualMode;
  // Virtual state tracking for masks exceeding hardware limits:
  // 0 = closed & disabled, 1 = closed & enabled, 2 = open

#ifdef _DEBUG
  std::stack<bool> m_fullStateStack;
  // Tracks actual mask states (true=opened, false=closed+enabled)
#endif

  unsigned char m_writeMask;     // Bitmask: i-th bit set => i-th mask is writable
  unsigned char m_screenWriteMask; // Bitmask: i-th bit set => i-th mask writes to screen
  unsigned char m_enableMask;    // Bitmask: i-th bit set => i-th mask is enabled
  unsigned char m_insideMask;    // Bitmask: i-th bit set => i-th mask defines inside region
  unsigned char m_singleDrawMask;

  Implementation();
  void updateGLState();
  void pushPlane();
  void popPlane();
  void startPlane(DrawMode mode);
  void finishPlane();
  void activatePlane(MaskType type);
  void deactivatePlane();
};
//-----------------------------------------------------------------------------------------
TStencilControl::Implementation::Implementation()
    : m_stencilPlaneCount(0)
    , m_depthCounter(1)
    , m_activePlane(-1)
    , m_enableMask(0)
    , m_writeMask(0)
    , m_insideMask(0)
    , m_screenWriteMask(0)
    , m_singleDrawMask(0)
    , m_virtualMode(0) {
  glGetIntegerv(GL_STENCIL_BITS, (GLint *)&m_stencilPlaneCount);
  glStencilMask(0xFFFFFFFF);
  glClear(GL_STENCIL_BUFFER_BIT);
}
//---------------------------------------------------------
TStencilControl *TStencilControl::instance() {
  StencilControlManager *manager = StencilControlManager::getInstance();
  return manager->getActiveStencilControl();
}
//---------------------------------------------------------
TStencilControl::TStencilControl() : m_impl(new Implementation) {}
//---------------------------------------------------------
TStencilControl::~TStencilControl() {}
//---------------------------------------------------------
void TStencilControl::Implementation::updateGLState() {
  if (m_activePlane >= 0) {  // Writing to stencil buffer
    unsigned char currentBit = 1 << m_activePlane;
    bool singlePass = (currentBit & m_singleDrawMask) != 0;

    if (currentBit & m_screenWriteMask) {
      unsigned char prevMask;
      int prevPlane = m_activePlane - 1;
      for (; prevPlane >= 0; prevPlane--) {
        prevMask = 1 << prevPlane;
        if ((prevMask & m_writeMask) == prevMask) break;
      }

      if (prevPlane < 0) {
        if (singlePass)
          m_enableMask |= currentBit;
        else
          m_enableMask &= ~currentBit;
      } else {
        tglMultColorMask(0, 0, 0, 0);
        singlePass = false;
        currentBit |= prevMask;
      }
    } else {
      tglMultColorMask(0, 0, 0, 0);
    }

    glStencilMask(currentBit);

    if (singlePass) {
      glStencilFunc(GL_EQUAL, m_insideMask, m_enableMask);
      glStencilOp(GL_KEEP, GL_INVERT, GL_INVERT);
    } else {
      glStencilFunc(GL_EQUAL, currentBit | m_insideMask, m_enableMask);
      glStencilOp(GL_KEEP, GL_REPLACE, GL_REPLACE);
    }
  } else {  // Writing to color buffer
    glStencilMask(0xFFFFFFFF);
    glStencilFunc(GL_EQUAL, m_insideMask, m_enableMask);
    glStencilOp(GL_KEEP, GL_KEEP, GL_KEEP);
  }

  if (!m_enableMask && m_activePlane < 0)
    glDisable(GL_STENCIL_TEST);
  else
    glEnable(GL_STENCIL_TEST);
}
//---------------------------------------------------------
void TStencilControl::Implementation::pushPlane() { ++m_depthCounter; }
//---------------------------------------------------------
void TStencilControl::Implementation::startPlane(DrawMode mode) {
  m_activePlane = m_depthCounter - 1;
  unsigned char currentBit = 1 << m_activePlane;
  m_writeMask |= currentBit;

  if (mode == DRAW_ALSO_ON_SCREEN) {
    m_screenWriteMask |= currentBit;
  } else if (mode == DRAW_ON_SCREEN_ONLY_ONCE) {
    m_screenWriteMask |= currentBit;
    m_singleDrawMask |= currentBit;
  } else {
    m_screenWriteMask &= ~currentBit;
    m_singleDrawMask &= ~currentBit;
  }

  glEnable(GL_STENCIL_TEST);
  glStencilMask(currentBit);
  glClear(GL_STENCIL_BUFFER_BIT);
  updateGLState();
}
//---------------------------------------------------------
void TStencilControl::Implementation::finishPlane() {
  assert(m_depthCounter - 1 == m_activePlane);
  unsigned char currentBit = 1 << (m_depthCounter - 1);
  m_writeMask &= ~currentBit;
  m_enableMask &= ~currentBit;
  m_screenWriteMask &= ~currentBit;
  m_singleDrawMask &= ~currentBit;

  --m_activePlane;
  for (; m_activePlane >= 0; --m_activePlane) {
    unsigned char testBit = 1 << m_activePlane;
    if ((testBit & m_writeMask) == testBit) break;
  }
  updateGLState();
}
//---------------------------------------------------------
void TStencilControl::Implementation::activatePlane(MaskType type) {
  unsigned char currentBit = 1 << (m_depthCounter - 1);
  if ((m_enableMask & currentBit) == 0) glPushAttrib(GL_ALL_ATTRIB_BITS);
  m_enableMask |= currentBit;

  assert(type == SHOW_INSIDE || type == SHOW_OUTSIDE);
  if (type == SHOW_INSIDE)
    m_insideMask |= currentBit;
  else
    m_insideMask &= ~currentBit;

  updateGLState();
}
//---------------------------------------------------------
void TStencilControl::Implementation::deactivatePlane() {
  unsigned char currentBit = 1 << (m_depthCounter - 1);
  m_enableMask &= ~currentBit;
  m_insideMask &= ~currentBit;
  updateGLState();
  glPopAttrib();
}
//---------------------------------------------------------
void TStencilControl::Implementation::popPlane() {
  --m_depthCounter;
  assert(m_depthCounter > 0);
}
//---------------------------------------------------------
void TStencilControl::beginMask(DrawMode mode) {
  glPushAttrib(GL_ALL_ATTRIB_BITS);
  if (m_impl->m_virtualMode) {
#ifdef _DEBUG
    m_impl->m_fullStateStack.push(m_impl->m_virtualMode == 2);
#endif
    m_impl->pushPlane();
  }
  m_impl->m_virtualMode = 2;
  if (m_impl->m_depthCounter <= m_impl->m_stencilPlaneCount)
    m_impl->startPlane(mode);
}
//---------------------------------------------------------
void TStencilControl::endMask() {
  if (!m_impl->m_virtualMode) {
    m_impl->popPlane();
#ifdef _DEBUG
    assert(m_impl->m_fullStateStack.top());
    m_impl->m_fullStateStack.pop();
#endif
  }
  assert(m_impl->m_virtualMode != 1);
  m_impl->m_virtualMode = 0;
  if (m_impl->m_depthCounter <= m_impl->m_stencilPlaneCount)
    m_impl->finishPlane();
  glPopAttrib();
}
//---------------------------------------------------------
void TStencilControl::enableMask(MaskType type) {
  assert(m_impl->m_virtualMode != 2);
  m_impl->m_virtualMode = 1;
  if (m_impl->m_depthCounter <= m_impl->m_stencilPlaneCount)
    m_impl->activatePlane(type);
}
//---------------------------------------------------------
void TStencilControl::disableMask() {
  assert(m_impl->m_virtualMode != 2);
  if (!m_impl->m_virtualMode) {
    m_impl->popPlane();
#ifdef _DEBUG
    assert(!m_impl->m_fullStateStack.top());
    m_impl->m_fullStateStack.pop();
#endif
  }
  m_impl->m_virtualMode = 0;
  if (m_impl->m_depthCounter <= m_impl->m_stencilPlaneCount)
    m_impl->deactivatePlane();
}
