#include "clipper2/clipper.h"
#include "clipper2/clipper.rectclip.h"

namespace Clipper2Lib {
  //------------------------------------------------------------------------------
  // Utility functions
  //------------------------------------------------------------------------------
  inline bool PathContainsPath(const Path64& outer, const Path64& inner)
  {
    int containmentCounter = 0;
    // assumption: minimal overlap between paths
    for (const Point64& point : inner)
    {
      PointInPolygonResult testResult = PointInPolygon(point, outer);
      switch (testResult)
      {
      case PointInPolygonResult::IsOutside: ++containmentCounter; break;
      case PointInPolygonResult::IsInside: --containmentCounter; break;
      default: continue;
      }
      if (std::abs(containmentCounter) > 1) break;
    }
    return containmentCounter <= 0;
  }

  inline bool DetermineLocation(const Rect64& rectangle,
    const Point64& point, Location& location)
  {
    if (point.x == rectangle.left && point.y >= rectangle.top && point.y <= rectangle.bottom)
    {
      location = Location::Left;
      return false;
    }
    else if (point.x == rectangle.right && point.y >= rectangle.top && point.y <= rectangle.bottom)
    {
      location = Location::Right;
      return false;
    }
    else if (point.y == rectangle.top && point.x >= rectangle.left && point.x <= rectangle.right)
    {
      location = Location::Top;
      return false;
    }
    else if (point.y == rectangle.bottom && point.x >= rectangle.left && point.x <= rectangle.right)
    {
      location = Location::Bottom;
      return false;
    }
    else if (point.x < rectangle.left) location = Location::Left;
    else if (point.x > rectangle.right) location = Location::Right;
    else if (point.y < rectangle.top) location = Location::Top;
    else if (point.y > rectangle.bottom) location = Location::Bottom;
    else location = Location::Inside;
    return true;
  }

  inline bool ArePointsHorizontal(const Point64& ptA, const Point64& ptB)
  {
    return ptA.y == ptB.y;
  }

  bool IntersectSegments(const Point64& a1,
    const Point64& a2, const Point64& b1, const Point64& b2, Point64& intersectionPoint)
  {
    int signA1 = CrossProductSign(a1, b1, b2);
    int signA2 = CrossProductSign(a2, b1, b2);

    if (signA1 == 0)
    {
      intersectionPoint = a1;
      if (signA2 == 0) return false; // segments are collinear
      else if (a1 == b1 || a1 == b2) return true;
      else if (ArePointsHorizontal(b1, b2)) return ((a1.x > b1.x) == (a1.x < b2.x));
      else return ((a1.y > b1.y) == (a1.y < b2.y));
    }
    else if (signA2 == 0)
    {
      intersectionPoint = a2;
      if (a2 == b1 || a2 == b2) return true;
      else if (ArePointsHorizontal(b1, b2)) return ((a2.x > b1.x) == (a2.x < b2.x));
      else return ((a2.y > b1.y) == (a2.y < b2.y));
    }

    if ((signA1 > 0) == (signA2 > 0)) return false;

    int signB1 = CrossProductSign(b1, a1, a2);
    int signB2 = CrossProductSign(b2, a1, a2);

    if (signB1 == 0)
    {
      intersectionPoint = b1;
      if (b1 == a1 || b1 == a2) return true;
      else if (ArePointsHorizontal(a1, a2)) return ((b1.x > a1.x) == (b1.x < a2.x));
      else return ((b1.y > a1.y) == (b1.y < a2.y));
    }
    else if (signB2 == 0)
    {
      intersectionPoint = b2;
      if (b2 == a1 || b2 == a2) return true;
      else if (ArePointsHorizontal(a1, a2)) return ((b2.x > a1.x) == (b2.x < a2.x));
      else return ((b2.y > a1.y) == (b2.y < a2.y));
    }

    if ((signB1 > 0) == (signB2 > 0)) return false;
    // segments must intersect to get here
    return GetLineIntersectPt(a1, a2, b1, b2, intersectionPoint);
  }

  inline bool GetRectIntersection(const Path64& rectPath,
    const Point64& start, const Point64& end, Location& loc, Point64& ip)
  {
    // finds the intersection closest to 'start'
    // when Result = false, loc remains unchanged
    switch (loc)
    {
    case Location::Left:
      if (IntersectSegments(start, end, rectPath[0], rectPath[3], ip)) return true;
      else if ((start.y < rectPath[0].y) && IntersectSegments(start, end, rectPath[0], rectPath[1], ip))
      {
        loc = Location::Top;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[2], rectPath[3], ip))
      {
        loc = Location::Bottom;
        return true;
      }
      else return false;

    case Location::Top:
      if (IntersectSegments(start, end, rectPath[0], rectPath[1], ip)) return true;
      else if ((start.x < rectPath[0].x) && IntersectSegments(start, end, rectPath[0], rectPath[3], ip))
      {
        loc = Location::Left;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[1], rectPath[2], ip))
      {
        loc = Location::Right;
        return true;
      }
      else return false;

    case Location::Right:
      if (IntersectSegments(start, end, rectPath[1], rectPath[2], ip)) return true;
      else if ((start.y < rectPath[1].y) && IntersectSegments(start, end, rectPath[0], rectPath[1], ip))
      {
        loc = Location::Top;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[2], rectPath[3], ip))
      {
        loc = Location::Bottom;
        return true;
      }
      else return false;

    case Location::Bottom:
      if (IntersectSegments(start, end, rectPath[2], rectPath[3], ip)) return true;
      else if ((start.x < rectPath[3].x) && IntersectSegments(start, end, rectPath[0], rectPath[3], ip))
      {
        loc = Location::Left;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[1], rectPath[2], ip))
      {
        loc = Location::Right;
        return true;
      }
      else return false;

    default: // loc == Inside
      if (IntersectSegments(start, end, rectPath[0], rectPath[3], ip))
      {
        loc = Location::Left;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[0], rectPath[1], ip))
      {
        loc = Location::Top;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[1], rectPath[2], ip))
      {
        loc = Location::Right;
        return true;
      }
      else if (IntersectSegments(start, end, rectPath[2], rectPath[3], ip))
      {
        loc = Location::Bottom;
        return true;
      }
      else return false;
    }
  }

  inline Location NextEdgeLocation(Location currentLoc, bool clockwise)
  {
    int offset = (clockwise) ? 1 : 3;
    return static_cast<Location>((static_cast<int>(currentLoc) + offset) % 4);
  }

  inline bool IsClockwiseTurn(Location prev, Location curr)
  {
    return (static_cast<int>(prev) + 1) % 4 == static_cast<int>(curr);
  }

  inline bool AreOppositeEdges(Location edge1, Location edge2)
  {
    return abs(static_cast<int>(edge1) - static_cast<int>(edge2)) == 2;
  }

  inline bool IsClockwiseDirection(Location prev, Location curr,
    const Point64& prev_pt, const Point64& curr_pt, const Point64& rect_center)
  {
    if (AreOppositeEdges(prev, curr))
      return CrossProductSign(prev_pt, rect_center, curr_pt) < 0;
    else
      return IsClockwiseTurn(prev, curr);
  }

  inline OutPt2* RemoveNode(OutPt2* node)
  {
    if (node->next == node) return nullptr;
    node->prev->next = node->next;
    node->next->prev = node->prev;
    return node->next;
  }

  inline OutPt2* RemoveBackNode(OutPt2* node)
  {
    if (node->next == node) return nullptr;
    node->prev->next = node->next;
    node->next->prev = node->prev;
    return node->prev;
  }

  inline uint32_t IdentifyEdgesForPoint(const Point64& pt, const Rect64& rec)
  {
    uint32_t result = 0;
    if (pt.x == rec.left) result = 1;
    else if (pt.x == rec.right) result = 4;
    if (pt.y == rec.top) result += 2;
    else if (pt.y == rec.bottom) result += 8;
    return result;
  }

  inline bool IsMovingClockwise(const Point64& pt1, const Point64& pt2, int edgeIndex)
  {
    switch (edgeIndex)
    {
    case 0: return pt2.y < pt1.y;
    case 1: return pt2.x > pt1.x;
    case 2: return pt2.y > pt1.y;
    default: return pt2.x < pt1.x;
    }
  }

  inline bool HorizontalOverlap(const Point64& left1, const Point64& right1,
    const Point64& left2, const Point64& right2)
  {
    return (left1.x < right2.x) && (right1.x > left2.x);
  }

  inline bool VerticalOverlap(const Point64& top1, const Point64& bottom1,
    const Point64& top2, const Point64& bottom2)
  {
    return (top1.y < bottom2.y) && (bottom1.y > top2.y);
  }

  inline void AttachToEdge(OutPt2List& edgeList, OutPt2* node)
  {
    if (node->edge) return;
    node->edge = &edgeList;
    edgeList.emplace_back(node);
  }

  inline void DetachFromEdge(OutPt2* node)
  {
    if (!node->edge) return;
    for (size_t k = 0; k < node->edge->size(); ++k)
    {
      OutPt2* otherNode = (*node->edge)[k];
      if (otherNode == node)
      {
        (*node->edge)[k] = nullptr;
        break;
      }
    }
    node->edge = nullptr;
  }

  inline void UpdateOwnerIndex(OutPt2* node, size_t newIndex)
  {
    node->owner_idx = newIndex;
    OutPt2* nextNode = node->next;
    while (nextNode != node)
    {
      nextNode->owner_idx = newIndex;
      nextNode = nextNode->next;
    }
  }

  //----------------------------------------------------------------------------
  // RectClip64 implementation
  //----------------------------------------------------------------------------
  OutPt2* RectClip64::Add(Point64 pt, bool isNewLoop)
  {
    size_t currentIndex = results_.size();
    OutPt2* newPoint;
    if (currentIndex == 0 || isNewLoop)
    {
      newPoint = &op_container_.emplace_back(OutPt2());
      newPoint->pt = pt;
      newPoint->next = newPoint;
      newPoint->prev = newPoint;
      results_.emplace_back(newPoint);
    }
    else
    {
      --currentIndex;
      OutPt2* previousPoint = results_[currentIndex];
      if (previousPoint->pt == pt)  return previousPoint;
      newPoint = &op_container_.emplace_back(OutPt2());
      newPoint->owner_idx = currentIndex;
      newPoint->pt = pt;
      newPoint->next = previousPoint->next;
      previousPoint->next->prev = newPoint;
      previousPoint->next = newPoint;
      newPoint->prev = previousPoint;
      results_[currentIndex] = newPoint;
    }
    return newPoint;
  }

  void RectClip64::AddCorner(Location prev, Location curr)
  {
    if (IsClockwiseTurn(prev, curr))
      Add(rect_as_path_[static_cast<size_t>(prev)]);
    else
      Add(rect_as_path_[static_cast<size_t>(curr)]);
  }

  void RectClip64::AddCorner(Location& loc, bool isClockwise)
  {
    if (isClockwise)
    {
      Add(rect_as_path_[static_cast<size_t>(loc)]);
      loc = NextEdgeLocation(loc, true);
    }
    else
    {
      loc = NextEdgeLocation(loc, false);
      Add(rect_as_path_[static_cast<size_t>(loc)]);
    }
  }

  void RectClip64::AdvanceToNextPoint(const Path64& path,
    Location& loc, size_t& index, size_t maxIndex)
  {
    switch (loc)
    {
    case Location::Left:
      while (index <= maxIndex && path[index].x <= rect_.left) ++index;
      if (index > maxIndex) break;
      else if (path[index].x >= rect_.right) loc = Location::Right;
      else if (path[index].y <= rect_.top) loc = Location::Top;
      else if (path[index].y >= rect_.bottom) loc = Location::Bottom;
      else loc = Location::Inside;
      break;

    case Location::Top:
      while (index <= maxIndex && path[index].y <= rect_.top) ++index;
      if (index > maxIndex) break;
      else if (path[index].y >= rect_.bottom) loc = Location::Bottom;
      else if (path[index].x <= rect_.left) loc = Location::Left;
      else if (path[index].x >= rect_.right) loc = Location::Right;
      else loc = Location::Inside;
      break;

    case Location::Right:
      while (index <= maxIndex && path[index].x >= rect_.right) ++index;
      if (index > maxIndex) break;
      else if (path[index].x <= rect_.left) loc = Location::Left;
      else if (path[index].y <= rect_.top) loc = Location::Top;
      else if (path[index].y >= rect_.bottom) loc = Location::Bottom;
      else loc = Location::Inside;
      break;

    case Location::Bottom:
      while (index <= maxIndex && path[index].y >= rect_.bottom) ++index;
      if (index > maxIndex) break;
      else if (path[index].y <= rect_.top) loc = Location::Top;
      else if (path[index].x <= rect_.left) loc = Location::Left;
      else if (path[index].x >= rect_.right) loc = Location::Right;
      else loc = Location::Inside;
      break;

    case Location::Inside:
      while (index <= maxIndex)
      {
        if (path[index].x < rect_.left) loc = Location::Left;
        else if (path[index].x > rect_.right) loc = Location::Right;
        else if (path[index].y > rect_.bottom) loc = Location::Bottom;
        else if (path[index].y < rect_.top) loc = Location::Top;
        else { Add(path[index]); ++index; continue; }
        break;
      }
      break;
    } //switch
  }

  bool StartLocationsAreClockwise(const std::vector<Location>& startlocs)
  {
    int result = 0;
    for (size_t i = 1; i < startlocs.size(); ++i)
    {
      int diff = static_cast<int>(startlocs[i]) - static_cast<int>(startlocs[i - 1]);
      switch (diff)
      {
        case -1: result -= 1; break;
        case 1: result += 1; break;
        case -3: result += 1; break;
        case 3: result -= 1; break;
      }
    }
    return result > 0;
  }

  void RectClip64::ProcessPath(const Path64& path)
  {
    if (path.size() < 1)
      return;
    size_t lastIndex = path.size() - 1;
    Location previousLoc = Location::Inside, currentLoc;
    Location crossingLoc = Location::Inside;
    Location firstCrossingLoc = Location::Inside;

    if (!DetermineLocation(rect_, path[lastIndex], currentLoc))
    {
      size_t idx = lastIndex;
      while (idx > 0 && !DetermineLocation(rect_, path[idx - 1], previousLoc))
        --idx;
      if (idx == 0)
      {
        // all of path must be inside rectangle
        for (const auto& pt : path) Add(pt);
        return;
      }
      if (previousLoc == Location::Inside) currentLoc = Location::Inside;
    }

    Location initialLoc = currentLoc;
    size_t i = 0;

    while (i <= lastIndex)
    {
      previousLoc = currentLoc;
      Location prevCrossing = crossingLoc;
      AdvanceToNextPoint(path, currentLoc, i, lastIndex);
      if (i > lastIndex) break;

      Point64 intersectionPt, secondIntersectionPt;
      Point64 previousPoint = (i) ?
        path[static_cast<size_t>(i - 1)] :
        path[lastIndex];
      crossingLoc = currentLoc;

      if (!GetRectIntersection(rect_as_path_,
        path[i], previousPoint, crossingLoc, intersectionPt))
      {
        // remaining outside
        if (prevCrossing == Location::Inside)
        {
          bool isClockwise = IsClockwiseDirection(previousLoc, currentLoc, previousPoint, path[i], rect_mp_);
          do {
            start_locs_.emplace_back(previousLoc);
            previousLoc = NextEdgeLocation(previousLoc, isClockwise);
          } while (previousLoc != currentLoc);
          crossingLoc = prevCrossing;
        }
        else if (previousLoc != Location::Inside && previousLoc != currentLoc)
        {
          bool isClockwise = IsClockwiseDirection(previousLoc, currentLoc, previousPoint, path[i], rect_mp_);
          do {
            AddCorner(previousLoc, isClockwise);
          } while (previousLoc != currentLoc);
        }
        ++i;
        continue;
      }

      // we must be crossing the rect boundary to get here
      if (currentLoc == Location::Inside) // path entering rect
      {
        if (firstCrossingLoc == Location::Inside)
        {
          firstCrossingLoc = crossingLoc;
          start_locs_.emplace_back(previousLoc);
        }
        else if (previousLoc != crossingLoc)
        {
          bool isClockwise = IsClockwiseDirection(previousLoc, crossingLoc, previousPoint, path[i], rect_mp_);
          do {
            AddCorner(previousLoc, isClockwise);
          } while (previousLoc != crossingLoc);
        }
      }
      else if (previousLoc != Location::Inside)
      {
        // passing through rect. 'intersectionPt' is second intersect pt
        currentLoc = previousLoc;
        GetRectIntersection(rect_as_path_, previousPoint, path[i], currentLoc, secondIntersectionPt);

        if (prevCrossing != Location::Inside && prevCrossing != currentLoc)
          AddCorner(prevCrossing, currentLoc);

        if (firstCrossingLoc == Location::Inside)
        {
          firstCrossingLoc = currentLoc;
          start_locs_.emplace_back(previousLoc);
        }
        currentLoc = crossingLoc;
        Add(secondIntersectionPt);

        if (intersectionPt == secondIntersectionPt)
        {
          GetLocation(rect_, path[i], currentLoc);
          AddCorner(crossingLoc, currentLoc);
          crossingLoc = currentLoc;
          continue;
        }
      }
      else // path exiting rect
      {
        currentLoc = crossingLoc;
        if (firstCrossingLoc == Location::Inside)
          firstCrossingLoc = crossingLoc;
      }
      Add(intersectionPt);
    } //while i <= lastIndex

    if (firstCrossingLoc == Location::Inside)
    {
      if (initialLoc != Location::Inside)
      {
        if (path_bounds_.Contains(rect_) &&
          PathContainsPath(path, rect_as_path_))
        {
          bool isClockwisePath = StartLocationsAreClockwise(start_locs_);
          for (size_t j = 0; j < 4; ++j)
          {
            size_t k = isClockwisePath ? j : 3 - j;
            Add(rect_as_path_[k]);
            AttachToEdge(edges_[k * 2], results_[0]);
          }
        }
      }
    }
    else if (currentLoc != Location::Inside &&
      (currentLoc != firstCrossingLoc || start_locs_.size() > 2))
    {
      if (start_locs_.size() > 0)
      {
        previousLoc = currentLoc;
        for (auto locVal : start_locs_)
        {
          if (previousLoc == locVal) continue;
          AddCorner(previousLoc, IsClockwiseTurn(previousLoc, locVal));
          previousLoc = locVal;
        }
        currentLoc = previousLoc;
      }
      if (currentLoc != firstCrossingLoc)
        AddCorner(currentLoc, IsClockwiseTurn(currentLoc, firstCrossingLoc));
    }
  }

  void RectClip64::ValidateEdges()
  {
    for (size_t i = 0; i < results_.size(); ++i)
    {
      OutPt2* op = results_[i];
      if (!op) continue;
      OutPt2* op2 = op;
      do
      {
        if (IsCollinear(op2->prev->pt, op2->pt, op2->next->pt))
        {
          if (op2 == op)
          {
            op2 = RemoveBackNode(op2);
            if (!op2) break;
            op = op2->prev;
          }
          else
          {
            op2 = RemoveBackNode(op2);
            if (!op2) break;
          }
        }
        else
          op2 = op2->next;
      } while (op2 != op);

      if (!op2)
      {
        results_[i] = nullptr;
        continue;
      }
      results_[i] = op;

      uint32_t edgeSet1 = IdentifyEdgesForPt(op->prev->pt, rect_);
      op2 = op;
      do
      {
        uint32_t edgeSet2 = IdentifyEdgesForPt(op2->pt, rect_);
        if (edgeSet2 && !op2->edge)
        {
          uint32_t combinedSet = (edgeSet1 & edgeSet2);
          for (int j = 0; j < 4; ++j)
          {
            if (combinedSet & (1 << j))
            {
              if (IsMovingClockwise(op2->prev->pt, op2->pt, j))
                AttachToEdge(edges_[j * 2], op2);
              else
                AttachToEdge(edges_[j * 2 + 1], op2);
            }
          }
        }
        edgeSet1 = edgeSet2;
        op2 = op2->next;
      } while (op2 != op);
    }
  }

  void RectClip64::OptimizeEdges(size_t idx, OutPt2List& cw, OutPt2List& ccw)
  {
    if (ccw.empty()) return;
    bool isHorizontal = ((idx == 1) || (idx == 3));
    bool cwMovesForward = ((idx == 1) || (idx == 2));
    size_t i = 0, j = 0;
    OutPt2* p1, * p2, * p1a, * p2a, * op, * op2;

    while (i < cw.size())
    {
      p1 = cw[i];
      if (!p1 || p1->next == p1->prev)
      {
        cw[i++] = nullptr;
        j = 0;
        continue;
      }
      size_t jLimit = ccw.size();
      while (j < jLimit &&
        (!ccw[j] || ccw[j]->next == ccw[j]->prev)) ++j;
      if (j == jLimit)
      {
        ++i;
        j = 0;
        continue;
      }

      if (cwMovesForward)
      {
        p1 = cw[i]->prev;
        p1a = cw[i];
        p2 = ccw[j];
        p2a = ccw[j]->prev;
      }
      else
      {
        p1 = cw[i];
        p1a = cw[i]->prev;
        p2 = ccw[j]->prev;
        p2a = ccw[j];
      }

      if ((isHorizontal && !HorizontalOverlap(p1->pt, p1a->pt, p2->pt, p2a->pt)) ||
        (!isHorizontal && !VerticalOverlap(p1->pt, p1a->pt, p2->pt, p2a->pt)))
      {
        ++j;
        continue;
      }

      bool isRejoining = cw[i]->owner_idx != ccw[j]->owner_idx;
      if (isRejoining)
      {
        results_[p2->owner_idx] = nullptr;
        UpdateOwnerIndex(p2, p1->owner_idx);
      }

      if (cwMovesForward)
      {
        p1->next = p2;
        p2->prev = p1;
        p1a->prev = p2a;
        p2a->next = p1a;
      }
      else
      {
        p1->prev = p2;
        p2->next = p1;
        p1a->next = p2a;
        p2a->prev = p1a;
      }

      if (!isRejoining)
      {
        size_t newIdx = results_.size();
        results_.emplace_back(p1a);
        UpdateOwnerIndex(p1a, newIdx);
      }

      if (cwMovesForward)
      {
        op = p2;
        op2 = p1a;
      }
      else
      {
        op = p1;
        op2 = p2a;
      }

      results_[op->owner_idx] = op;
      results_[op2->owner_idx] = op2;

      bool opIsForward, op2IsForward;
      if (isHorizontal)
      {
        opIsForward = op->pt.x > op->prev->pt.x;
        op2IsForward = op2->pt.x > op2->prev->pt.x;
      }
      else
      {
        opIsForward = op->pt.y > op->prev->pt.y;
        op2IsForward = op2->pt.y > op2->prev->pt.y;
      }

      if ((op->next == op->prev) || (op->pt == op->prev->pt))
      {
        if (op2IsForward == cwMovesForward)
        {
          cw[i] = op2;
          ccw[j++] = nullptr;
        }
        else
        {
          ccw[j] = op2;
          cw[i++] = nullptr;
        }
      }
      else if ((op2->next == op2->prev) || (op2->pt == op2->prev->pt))
      {
        if (opIsForward == cwMovesForward)
        {
          cw[i] = op;
          ccw[j++] = nullptr;
        }
        else
        {
          ccw[j] = op;
          cw[i++] = nullptr;
        }
      }
      else if (opIsForward == op2IsForward)
      {
        if (opIsForward == cwMovesForward)
        {
          cw[i] = op;
          DetachFromEdge(op2);
          AttachToEdge(cw, op2);
          ccw[j++] = nullptr;
        }
        else
        {
          cw[i++] = nullptr;
          ccw[j] = op2;
          DetachFromEdge(op);
          AttachToEdge(ccw, op);
          j = 0;
        }
      }
      else
      {
        if (opIsForward == cwMovesForward)
          cw[i] = op;
        else
          ccw[j] = op;
        if (op2IsForward == cwMovesForward)
          cw[i] = op2;
        else
          ccw[j] = op2;
      }
    }
  }

  Path64 RectClip64::ExtractPath(OutPt2*& op)
  {
    if (!op || op->next == op->prev) return Path64();
    OutPt2* op2 = op->next;
    while (op2 && op2 != op)
    {
      if (IsCollinear(op2->prev->pt, op2->pt, op2->next->pt))
      {
        op = op2->prev;
        op2 = RemoveBackNode(op2);
      }
      else
        op2 = op2->next;
    }
    op = op2;
    if (!op2) return Path64();

    Path64 result;
    result.emplace_back(op->pt);
    op2 = op->next;
    while (op2 != op)
    {
      result.emplace_back(op2->pt);
      op2 = op2->next;
    }
    return result;
  }

  Paths64 RectClip64::Run(const Paths64& inputPaths)
  {
    Paths64 output;
    if (rect_.IsEmpty()) return output;

    for (const Path64& path : inputPaths)
    {
      if (path.size() < 3) continue;
      path_bounds_ = GetBounds(path);
      if (!rect_.Intersects(path_bounds_))
        continue;
      else if (rect_.Contains(path_bounds_))
      {
        output.emplace_back(path);
        continue;
      }
      ProcessPath(path);
      ValidateEdges();
      for (size_t i = 0; i < 4; ++i)
        OptimizeEdges(i, edges_[i * 2], edges_[i * 2 + 1]);
      for (OutPt2*& op : results_)
      {
        Path64 temp = ExtractPath(op);
        if (!temp.empty())
          output.emplace_back(std::move(temp));
      }
      // clean up after each loop
      op_container_ = std::deque<OutPt2>();
      results_.clear();
      for (OutPt2List &edge : edges_) edge.clear();
      start_locs_.clear();
    }
    return output;
  }

  //------------------------------------------------------------------------------
  // RectClipLines64 implementation
  //------------------------------------------------------------------------------
  Paths64 RectClipLines64::Run(const Paths64& inputPaths)
  {
    Paths64 output;
    if (rect_.IsEmpty()) return output;

    for (const auto& path : inputPaths)
    {
      Rect64 pathBounds = GetBounds(path);
      if (!rect_.Intersects(pathBounds)) continue;
      ProcessPathInternal(path);
      for (OutPt2*& op : results_)
      {
        Path64 temp = ExtractPath(op);
        if (!temp.empty())
          output.emplace_back(std::move(temp));
      }
      results_.clear();
      op_container_ = std::deque<OutPt2>();
      start_locs_.clear();
    }
    return output;
  }

  void RectClipLines64::ProcessPathInternal(const Path64& path)
  {
    if (rect_.IsEmpty() || path.size() < 2) return;
    results_.clear();
    op_container_ = std::deque<OutPt2>();
    start_locs_.clear();

    size_t i = 1, lastIndex = path.size() - 1;
    Location previousLoc = Location::Inside, currentLoc;
    Location crossingLoc;

    if (!DetermineLocation(rect_, path[0], currentLoc))
    {
      while (i <= lastIndex && !DetermineLocation(rect_, path[i], previousLoc)) ++i;
      if (i > lastIndex)
      {
        for (const auto& pt : path) Add(pt);
        return;
      }
      if (previousLoc == Location::Inside) currentLoc = Location::Inside;
      i = 1;
    }

    if (currentLoc == Location::Inside) Add(path[0]);

    while (i <= lastIndex)
    {
      previousLoc = currentLoc;
      AdvanceToNextPoint(path, currentLoc, i, lastIndex);
      if (i > lastIndex) break;

      Point64 intersectionPt, secondIntersectionPt;
      Point64 previousPoint = path[static_cast<size_t>(i - 1)];
      crossingLoc = currentLoc;

      if (!GetRectIntersection(rect_as_path_,
        path[i], previousPoint, crossingLoc, intersectionPt))
      {
        ++i;
        continue;
      }

      if (currentLoc == Location::Inside)
      {
        Add(intersectionPt, true);
      }
      else if (previousLoc != Location::Inside)
      {
        crossingLoc = previousLoc;
        GetRectIntersection(rect_as_path_,
          previousPoint, path[i], crossingLoc, secondIntersectionPt);
        Add(secondIntersectionPt, true);
        Add(intersectionPt);
      }
      else
      {
        Add(intersectionPt);
      }
    }
  }

  Path64 RectClipLines64::ExtractPath(OutPt2*& op)
  {
    Path64 result;
    if (!op || op == op->next) return result;
    op = op->next;
    result.emplace_back(op->pt);
    OutPt2 *op2 = op->next;
    while (op2 != op)
    {
      result.emplace_back(op2->pt);
      op2 = op2->next;
    }
    return result;
  }
} // namespace

