void ImGui::UnionPalette(ImGuiTogglePalette* dest, const ImGuiTogglePalette* source, const ImVec4 colors[], bool state)
{
	dest->Knob = colors[ImGuiCol_Text];
	dest->KnobHover = colors[ImGuiCol_Text];
	dest->Frame = colors[!state ? ImGuiCol_FrameBg : ImGuiCol_Button];
	dest->FrameHover = colors[!state ? ImGuiCol_FrameBgHovered : ImGuiCol_ButtonHovered];
	dest->FrameBorder = colors[ImGuiCol_Border];
	dest->FrameShadow = colors[ImGuiCol_BorderShadow];
	dest->KnobBorder = colors[ImGuiCol_Border];
	dest->KnobShadow = colors[ImGuiCol_BorderShadow];
	dest->A11yGlyph = colors[!state ? ImGuiCol_FrameBg : ImGuiCol_Text];

	// If no custom palette is provided, use the default theme-based one.
	if (source == nullptr)
	{
		return;
	}

	// Otherwise, copy only non-zero color values from the candidate palette
#define POPULATE_IF_NONZERO(field)              \
	do                                          \
	{                                           \
		if (IsNonZero(source->field))           \
		{                                       \
			dest->field = source->field;        \
		}                                       \
	} while (0)

	POPULATE_IF_NONZERO(Knob);
	POPULATE_IF_NONZERO(KnobHover);
	POPULATE_IF_NONZERO(Frame);
	POPULATE_IF_NONZERO(FrameHover);
	POPULATE_IF_NONZERO(FrameBorder);
	POPULATE_IF_NONZERO(FrameShadow);
	POPULATE_IF_NONZERO(KnobBorder);
	POPULATE_IF_NONZERO(KnobShadow);
	POPULATE_IF_NONZERO(A11yGlyph);

#undef POPULATE_IF_NONZERO
}

void ImGui::BlendPalettes(ImGuiTogglePalette* output, const ImGuiTogglePalette& first, const ImGuiTogglePalette& second, float factor)
{
	// Early exit if blending is at either extreme
	if (ImApproximately(factor, 0.0f))
	{
		*output = first;
		return;
	}
	else if (ImApproximately(factor, 1.0f))
	{
		*output = second;
		return;
	}

#define LERP_FIELD(member)                                     \
	do                                                         \
	{                                                          \
		output->member = ImLerp(first.member, second.member, factor); \
	} while (0)

	LERP_FIELD(Knob);
	LERP_FIELD(KnobHover);
	LERP_FIELD(Frame);
	LERP_FIELD(FrameHover);
	LERP_FIELD(FrameBorder);
	LERP_FIELD(FrameShadow);
	LERP_FIELD(KnobBorder);
	LERP_FIELD(KnobShadow);
	LERP_FIELD(A11yGlyph);

#undef LERP_FIELD
}

