namespace quadrotor_msgs
{
bool decodeOutputData(const std::vector<uint8_t> &buffer,
                      quadrotor_msgs::OutputData &result)
{
  struct OUTPUT_DATA raw_data;
  if(buffer.size() != sizeof(raw_data))
    return false;
  memcpy(&raw_data, &buffer[0], sizeof(raw_data));
  result.loop_rate = raw_data.loop_rate;
  result.voltage = raw_data.voltage/1e3;
  const double roll_angle = raw_data.roll/1e2 * M_PI/180;
  const double pitch_angle = raw_data.pitch/1e2 * M_PI/180;
  const double yaw_angle = raw_data.yaw/1e2 * M_PI/180;
  // Asctec (2012 firmware) uses  Z-Y-X convention
  Eigen::Quaterniond q = Eigen::AngleAxisd(yaw_angle, Eigen::Vector3d::UnitZ()) *
      Eigen::AngleAxisd(pitch_angle, Eigen::Vector3d::UnitY()) *
      Eigen::AngleAxisd(roll_angle, Eigen::Vector3d::UnitX());
  result.orientation.w = q.w();
  result.orientation.x = q.x();
  result.orientation.y = q.y();
  result.orientation.z = q.z();
  result.angular_velocity.x = raw_data.ang_vel[0]*0.0154*M_PI/180;
  result.angular_velocity.y = raw_data.ang_vel[1]*0.0154*M_PI/180;
  result.angular_velocity.z = raw_data.ang_vel[2]*0.0154*M_PI/180;
  result.linear_acceleration.x = raw_data.acc[0]/1e3 * 9.81;
  result.linear_acceleration.y = raw_data.acc[1]/1e3 * 9.81;
  result.linear_acceleration.z = raw_data.acc[2]/1e3 * 9.81;
  result.pressure_dheight = raw_data.dheight/1e3;
  result.pressure_height = raw_data.height/1e3;
  result.magnetic_field.x = raw_data.mag[0]/2500.0;
  result.magnetic_field.y = raw_data.mag[1]/2500.0;
  result.magnetic_field.z = raw_data.mag[2]/2500.0;
  for(int idx = 0; idx < 8; idx++)
  {
    result.radio_channel[idx] = raw_data.radio[idx];
  }
  //for(int i = 0; i < 4; i++)
  //  result.motor_rpm[i] = raw_data.rpm[i];
  result.seq = raw_data.seq;
  return true;
}

bool decodeStatusData(const std::vector<uint8_t> &buffer,
                      quadrotor_msgs::StatusData &status)
{
  struct STATUS_DATA raw_status;
  if(buffer.size() != sizeof(raw_status))
    return false;
  memcpy(&raw_status, &buffer[0], sizeof(raw_status));
  status.loop_rate = raw_status.loop_rate;
  status.voltage = raw_status.voltage/1e3;
  status.seq = raw_status.seq;
  return true;
}

bool decodePPROutputData(const std::vector<uint8_t> &buffer,
                         quadrotor_msgs::PPROutputData &output)
{
  struct PPR_OUTPUT_DATA raw_output;
  if(buffer.size() != sizeof(raw_output))
    return false;
  memcpy(&raw_output, &buffer[0], sizeof(raw_output));
  output.quad_time = raw_output.time;
  output.des_thrust = raw_output.des_thrust*1e-4;
  output.des_roll = raw_output.des_roll*1e-4;
  output.des_pitch = raw_output.des_pitch*1e-4;
  output.des_yaw = raw_output.des_yaw*1e-4;
  output.est_roll = raw_output.est_roll*1e-4;
  output.est_pitch = raw_output.est_pitch*1e-4;
  output.est_yaw = raw_output.est_yaw*1e-4;
  output.est_angvel_x = raw_output.est_angvel_x*1e-3;
  output.est_angvel_y = raw_output.est_angvel_y*1e-3;
  output.est_angvel_z = raw_output.est_angvel_z*1e-3;
  output.est_acc_x = raw_output.est_acc_x*1e-4;
  output.est_acc_y = raw_output.est_acc_y*1e-4;
  output.est_acc_z = raw_output.est_acc_z*1e-4;
  output.pwm[0] = raw_output.pwm1;
  output.pwm[1] = raw_output.pwm2;
  output.pwm[2] = raw_output.pwm3;
  output.pwm[3] = raw_output.pwm4;
  return true;
}
