// Constructor initializes the entity with a world reference
Entity::Entity(World* world) : m_world(world) {}

// Move entity to a new position and set rotation
void Entity::MoveTo(mc::Vector3f pos, float yaw, float pitch) {
    pos.y += verticalOffset;
    currentPos = pos;
    prevPos = pos;
    movementDelta = pos;
    yawAngle = yaw;
    pitchAngle = pitch;
    UpdatePosition(pos);
}

// Adjust position relative to current facing direction
void Entity::MoveRelative(float x, float z, float speed) {
    float magnitude = x * x + z * z;
    if (magnitude >= 0.01f) {
        magnitude = speed / std::sqrt(magnitude);
        x *= magnitude;
        z *= magnitude;
        // Normalize yaw angle to [0, 360) degrees
        float yawRad = (this->yawAngle * M_PI / 180.0f);
        float sinYaw = std::sin(yawRad);
        float cosYaw = std::cos(yawRad);
        movementDelta.x += x * cosYaw - z * sinYaw;
        movementDelta.z += z * cosYaw + x * sinYaw;
    }
}

// Set entity's rotation angles
void Entity::SetRot(float yaw, float pitch) {
    yawAngle = yaw;
    pitchAngle = pitch;
}

// Set entity's position and update bounding box
void Entity::SetPos(mc::Vector3f pos) {
    currentPos = pos;
    float halfWidth = width / 2;
    float bottomY = pos.y - verticalOffset + slideOffset;
    boundingBox = AABB(pos.x - halfWidth, bottomY, pos.z - halfWidth,
                       pos.x + halfWidth, bottomY + height, pos.z + halfHeight);
}

// Placeholder for resetting position
void Entity::ResetPos() {}

// Configure entity's bounding box dimensions
void Entity::SetSize(float width, float height) {
    this->width = width;
    this->height = height;
}

// Rotate entity by given deltas
void Entity::Turn(float yawChange, float pitchChange) {
    yawAngle += yawChange * 0.15f;
    pitchAngle = std::clamp(pitchAngle - pitchChange * 0.15f, -90.0f, 90.0f);
    yawAngle = std::remainder(yawAngle, 360.0f);
    if (yawAngle < 0.0f)
        yawAngle += 360.0f;
}

// Handle fall damage logic based on vertical movement and ground contact
void Entity::CheckFallDamage(float deltaY, bool landed) {
    if (landed) {
        if (fallDistance > 0.0f) {
            ApplyFallDamage(fallDistance);
            fallDistance = 0.0f;
        }
    } else if (deltaY < 0.0f) {
        fallDistance -= deltaY;
    }
}

// Apply calculated fall damage (currently empty implementation)
void Entity::CauseFallDamage(float distance) {}

// Update previous position tracking each tick
void Entity::Tick() { movementDelta = currentPos; }

