{
	if (force_lowercase)
		displayed_text = ToLower(newtext);
	else if (force_uppercase)
		displayed_text = ToUpper(newtext);
	else
		displayed_text = newtext;
	clip_start_offset = 0;
	UpdateTextClipping();
	SetCursorPos((int)displayed_text.size());
	SetTextSelection(0, 0);
	Update();
}

