void LineEdit::SetSelection(int pos, int length)
{
	selection_start = pos;
	selection_extent = length;
	Update();
}

// Clear current selection
void LineEdit::ClearSelection()
{
	SetSelection(0, 0);
	Update();
}

// Delete currently selected text
void LineEdit::DeleteSelectedText()
{
	if (GetSelectionLength() == 0)
		return;
	int sel_start = selection_start;
	int sel_end = selection_start + selection_extent;
	if (sel_start > sel_end)
		std::swap(sel_start, sel_end);
	displayed_text = displayed_text.substr(0, sel_start) + displayed_text.substr(sel_end, displayed_text.size());
	cursor_position = sel_start;
	SetTextSelection(0, 0);
	int old_pos = GetCursorPos();
	SetCursorPos(0);
	SetCursorPos(old_pos);
}

