// Handle mouse movement events
void LineEdit::OnMouseMove(const Point& pos)
{
	if (mouse_selecting)
	{
		if (pos.x < 0.0 || pos.x >= GetWidth())
		{
			if (pos.x < 0.0)
				mouse_moves_left = true;
			else
				mouse_moves_left = false;
			if (!read_only)
				scrolling_timer->Start(50, true);
		}
		else
		{
			scrolling_timer->Stop();
			cursor_position = GetCharacterIndex(pos.x);
			SetSelectionLength(cursor_position - selection_start);
			Update();
		}
	}
}

// Handle mouse button press events
bool LineEdit::OnMouseDown(const Point& pos, InputKey key)
{
	if (key == InputKey::LeftMouse)
	{
		if (HasFocus())
		{
			SetPointerCapture();
			mouse_selecting = true;
			cursor_position = GetCharacterIndex(pos.x);
			SetTextSelection(cursor_position, 0);
		}
		else
		{
			SetFocus();
		}
		Update();
	}
	return true;
}

// Handle mouse double-click events
bool LineEdit::OnMouseDoubleclick(const Point& pos, InputKey key)
{
	return true;
}

// Handle mouse button release events
bool LineEdit::OnMouseUp(const Point& pos, InputKey key)
{
	if (mouse_selecting && key == InputKey::LeftMouse)
	{
		scrolling_timer->Stop();
		ReleasePointerCapture();
		mouse_selecting = false;
		int sel_end = GetCharacterIndex(pos.x);
		SetSelectionLength(sel_end - selection_start);
		cursor_position = sel_end;
		Update();
	}
	return true;
}

// Handle character input
void LineEdit::OnKeyChar(std::string chars)
{
	if (FuncFilterKeyChar)
	{
		chars = FuncFilterKeyChar(chars);
		if (chars.empty())
			return;
	}
	if (!chars.empty() && !(chars[0] >= 0 && chars[0] < 32))
	{
		if (FuncBeforeEditChanged)
			FuncBeforeEditChanged();
		DeleteSelectedText();
		if (input_mask_pattern.empty())
		{
			if (numeric_input_mode)
			{
				// '-' can only be added once, and only as the first character.
				if (chars == "-" && cursor_position == 0 && displayed_text.find("-") == std::string::npos)
				{
					if (InsertText(cursor_position, chars))
						cursor_position += (int)chars.size();
				}
				else if (numeric_decimals_allowed && chars == decimal_separator && cursor_position > 0) // add decimal char 
				{
					if (displayed_text.find(decimal_separator) == std::string::npos) // allow only one decimal char.
					{
						if (InsertText(cursor_position, chars))
							cursor_position += (int)chars.size();
					}
				}
				else if (numeric_mode_characters.find(chars) != std::string::npos) // 0-9
				{
					if (InsertText(cursor_position, chars))
						cursor_position += (int)chars.size();
				}
			}
			else
			{
				// not in any special mode, just insert the string.
				if (InsertText(cursor_position, chars))
					cursor_position += (int)chars.size();
			}
		}
		else
		{
			if (InputMaskAcceptsInput(cursor_position, chars))
			{
				if (InsertText(cursor_position, chars))
					cursor_position += (int)chars.size();
			}
		}
		UpdateTextClipping();
		if (FuncAfterEditChanged)
			FuncAfterEditChanged();
	}
}

// Handle keyboard key presses
void LineEdit::OnKeyDown(InputKey key)
{
	if (FuncIgnoreKeyDown && FuncIgnoreKeyDown(key))
		return;
	if (key == InputKey::Enter)
	{
		if (FuncEnterPressed)
			FuncEnterPressed();
		return;
	}
	if (!read_only)	// Do not flash cursor when readonly
	{
		cursor_blink_visible = true;
		input_timer->Start(500); // don't blink cursor when moving or typing.
	}
	if (key == InputKey::Enter || key == InputKey::Escape || key == InputKey::Tab)
	{
		// Do not consume these.
		return;
	}
	else if (key == InputKey::A && GetKeyState(InputKey::Ctrl))
	{
		// select all
		SetTextSelection(0, (int)displayed_text.size());
		cursor_position = selection_extent;
		UpdateTextClipping();
		Update();
	}
	else if (key == InputKey::C && GetKeyState(InputKey::Ctrl))
	{
		if (!password_display)	// Do not allow copying the password to clipboard
		{
			std::string str = GetSelection();
			SetClipboardText(str);
		}
	}
	else if (read_only)
	{
		// Do not consume messages on read only component (only allow CTRL-A and CTRL-C)
		return;
	}
	else if (key == InputKey::Left)
	{
		Move(-1, GetKeyState(InputKey::Ctrl), GetKeyState(InputKey::Shift));
	}
	else if (key == InputKey::Right)
	{
		Move(1, GetKeyState(InputKey::Ctrl), GetKeyState(InputKey::Shift));
	}
	else if (key == InputKey::Backspace)
	{
		Backspace();
		UpdateTextClipping();
	}
	else if (key == InputKey::Delete)
	{
		Del();
		UpdateTextClipping();
	}
	else if (key == InputKey::Home)
	{
		SetSelectionStart(cursor_position);
		cursor_position = 0;
		if (GetKeyState(InputKey::Shift))
			SetSelectionLength(-selection_start);
		else
			SetTextSelection(0, 0);
		UpdateTextClipping();
		Update();
	}
	else if (key == InputKey::End)
	{
		SetSelectionStart(cursor_position);
		cursor_position = (int)displayed_text.size();
		if (GetKeyState(InputKey::Shift))
			SetSelectionLength((int)displayed_text.size() - selection_start);
		else
			SetTextSelection(0, 0);
		UpdateTextClipping();
		Update();
	}
	else if (key == InputKey::X && GetKeyState(InputKey::Ctrl))
	{
		std::string str = GetSelection();
		DeleteSelectedText();
		SetClipboardText(str);
		UpdateTextClipping();
	}
	else if (key == InputKey::V && GetKeyState(InputKey::Ctrl))
	{
		std::string str = GetClipboardText();
		std::string::const_iterator end_str = std::remove(str.begin(), str.end(), '\n');
		str.resize(end_str - str.begin());
		end_str = std::remove(str.begin(), str.end(), '\r');
		str.resize(end_str - str.begin());
		DeleteSelectedText();
		if (input_mask_pattern.empty())
		{
			if (numeric_input_mode)
			{
				std::string present_text = GetText();
				bool present_minus = present_text.find('-') != std::string::npos;
				bool str_minus = str.find('-') != std::string::npos;
				if (!present_minus || !str_minus)
				{
					if ((!present_minus && !str_minus) || //if no minus found
						(str_minus && cursor_position == 0 && str[0] == '-') || //if there's minus in text to paste
						(present_minus && cursor_position > 0)) //if there's minus in the beginning of control's text
					{
						if (numeric_decimals_allowed)
						{
							std::string::size_type decimal_point_pos;
							if ((decimal_point_pos = str.find_first_not_of(numeric_mode_characters, str[0] == '-' ? 1 : 0)) == std::string::npos) //no decimal char inside string to paste
							{ //we don't look at the position of decimal char inside of text in the textbox, if it's present
								if (InsertText(cursor_position, str))
									SetCursorPos(cursor_position + (int)str.length());
							}
							else
							{
								if (present_text.find(decimal_separator) == std::string::npos &&
									str[decimal_point_pos] == decimal_separator[0] &&
									str.find_first_not_of(numeric_mode_characters, decimal_point_pos + 1) == std::string::npos) //allow only one decimal char in the string to paste
								{
									if (InsertText(cursor_position, str))
										SetCursorPos(cursor_position + (int)str.length());
								}
							}
						}
						else
						{
							if (str.find_first_not_of(numeric_mode_characters, str[0] == '-' ? 1 : 0) == std::string::npos)
							{
								if (InsertText(cursor_position, str))
									SetCursorPos(cursor_position + (int)str.length());
							}
						}
					}
				}
			}
			else
			{
				if (InsertText(cursor_position, str))
					SetCursorPos(cursor_position + (int)str.length());
			}
		}
		else
		{
			if (InputMaskAcceptsInput(cursor_position, str))
			{
				if (InsertText(cursor_position, str))
					SetCursorPos(cursor_position + (int)str.length());
			}
		}
		UpdateTextClipping();
	}
	else if (GetKeyState(InputKey::Ctrl) && key == InputKey::Z)
	{
		if (!read_only)
		{
			std::string tmp = undo_info.undo_text;
			undo_info.undo_text = GetText();
			SetText(tmp);
		}
	}
	else if (key == InputKey::Shift)
	{
		if (selection_start == -1)
			SetTextSelection(cursor_position, 0);
	}
	if (FuncAfterEditChanged)
		FuncAfterEditChanged();
}

// Handle keyboard key releases
void LineEdit::OnKeyUp(InputKey key)
{
}

// Handle focus gained event
void LineEdit::OnSetFocus()
{
	if (!read_only)
		input_timer->Start(500);
	if (select_all_on_focus)
		SelectAll();
	cursor_position = (int)displayed_text.length();
	Update();
	if (FuncFocusGained)
		FuncFocusGained();
}

// Handle focus lost event
void LineEdit::OnLostFocus()
{
	input_timer->Stop();
	SetTextSelection(0, 0);
	Update();
	if (FuncFocusLost)
		FuncFocusLost();
}

// Move cursor by specified steps
void LineEdit::Move(int steps, bool ctrl, bool shift)
{
	if (shift && selection_extent == 0)
		SetSelectionStart(cursor_position);
	// Jump over words if control is pressed.
	if (ctrl)
	{
		if (steps < 0)
			steps = FindPreviousBreakCharacter(cursor_position - 1) - cursor_position;
		else
			steps = FindNextBreakCharacter(cursor_position + 1) - cursor_position;
		cursor_position += steps;
		if (cursor_position < 0)
			cursor_position = 0;
		if (cursor_position > (int)displayed_text.size())
			cursor_position = (int)displayed_text.size();
	}
	else
	{
		UTF8Reader utf8_reader(displayed_text.data(), displayed_text.length());
		utf8_reader.set_position(cursor_position);
		if (steps > 0)
		{
			for (int i = 0; i < steps; i++)
				utf8_reader.next();
		}
		else if (steps < 0)
		{
			for (int i = 0; i < -steps; i++)
				utf8_reader.prev();
		}
		cursor_position = (int)utf8_reader.position();
	}
	// Clear the selection if a cursor key is pressed but shift isn't down. 
	if (shift)
		SetSelectionLength(cursor_position - selection_start);
	else
		SetTextSelection(-1, 0);
	UpdateTextClipping();
	Update();
	undo_info.first_text_insert = true;
}

// Insert text at specified position
bool LineEdit::InsertText(int pos, const std::string& str)
{
	undo_info.first_erase = false;
	if (undo_info.first_text_insert)
	{
		undo_info.undo_text = GetText();
		undo_info.first_text_insert = false;
	}
	// checking if insert exceeds max length
	if (UTF8Reader::utf8_length(displayed_text) + UTF8Reader::utf8_length(str) > (size_t)max_text_length)
	{
		return false;
	}
	if (force_lowercase)
		displayed_text.insert(pos, ToLower(str));
	else if (force_uppercase)
		displayed_text.insert(pos, ToUpper(str));
	else
		displayed_text.insert(pos, str);
	UpdateTextClipping();
	Update();
	return true;
}

// Handle backspace key
void LineEdit::Backspace()
{
	if (undo_info.first_erase)
	{
		undo_info.first_erase = false;
		undo_info.undo_text = GetText();
	}
	if (GetSelectionLength() != 0)
	{
		DeleteSelectedText();
		Update();
	}
	else
	{
		if (cursor_position > 0)
		{
			UTF8Reader utf8_reader(displayed_text.data(), displayed_text.length());
			utf8_reader.set_position(cursor_position);
			utf8_reader.prev();
			size_t length = utf8_reader.char_length();
			displayed_text.erase(cursor_position - length, length);
			cursor_position -= (int)length;
			Update();
		}
	}
	int old_pos = GetCursorPos();
	SetCursorPos(0);
	SetCursorPos(old_pos);
}

// Handle delete key
void LineEdit::Del()
{
	if (undo_info.first_erase)
	{
		undo_info.first_erase = false;
		undo_info.undo_text = GetText();
	}
	if (GetSelectionLength() != 0)
	{
		DeleteSelectedText();
		Update();
	}
	else
	{
		if (cursor_position < (int)displayed_text.size())
		{
			UTF8Reader utf8_reader(displayed_text.data(), displayed_text.length());
			utf8_reader.set_position(cursor_position);
			size_t length = utf8_reader.char_length();
			displayed_text.erase(cursor_position, length);
			Update();
		}
	}
}

// Find character index at mouse position
int LineEdit::GetCharacterIndex(double mouse_x)
{
	if (displayed_text.size() <= 1)
	{
		return (int)displayed_text.size();
	}
	Canvas* canvas = GetCanvas();
	if (!canvas)
		return 0;
	UTF8Reader utf8_reader(displayed_text.data(), displayed_text.length());
	int seek_start = clip_start_offset;
	int seek_end = (int)displayed_text.size();
	int seek_center = (seek_start + seek_end) / 2;
	//fast search
	while (true)
	{
		utf8_reader.set_position(seek_center);
		utf8_reader.move_to_leadbyte();
		seek_center = (int)utf8_reader.position();
		Size text_size = GetVisualTextSize(canvas, clip_start_offset, seek_center - clip_start_offset);
		if (text_size.width > mouse_x)
			seek_end = seek_center;
		else
			seek_start = seek_center;
		if (seek_end - seek_start < 7)
			break; //go to accurate search
		seek_center = (seek_start + seek_end) / 2;
	}
	utf8_reader.set_position(seek_start);
	utf8_reader.move_to_leadbyte();
	//accurate search
	while (true)
	{
		seek_center = (int)utf8_reader.position();
		Size text_size = GetVisualTextSize(canvas, clip_start_offset, seek_center - clip_start_offset);
		if (text_size.width > mouse_x || utf8_reader.is_end())
			break;
		utf8_reader.next();
	}
	return seek_center;
}

// Update text clipping based on visible area
void LineEdit::UpdateTextClipping()
{
	Canvas* canvas = GetCanvas();
	if (!canvas)
		return;
	// Size text_size = GetVisualTextSize(canvas, clip_start_offset, (int)displayed_text.size() - clip_start_offset);
	if (cursor_position < clip_start_offset)
		clip_start_offset = cursor_position;
	Rect cursor_rect = GetCursorRect();
	UTF8Reader utf8_reader(displayed_text.data(), displayed_text.length());
	double width = GetWidth();
	while (cursor_rect.x + cursor_rect.width > width)
	{
		utf8_reader.set_position(clip_start_offset);
		utf8_reader.next();
		clip_start_offset = (int)utf8_reader.position();
		if (clip_start_offset == (int)displayed_text.size())
			break;
		cursor_rect = GetCursorRect();
	}
	// Get number of chars of current text fitting in the lineedit.
	int search_upper = (int)displayed_text.size();
	int search_lower = clip_start_offset;
	while (true)
	{
		int midpoint = (search_lower + search_upper) / 2;
		utf8_reader.set_position(midpoint);
		utf8_reader.move_to_leadbyte();
		if (midpoint != (int)utf8_reader.position())
			utf8_reader.next();
		midpoint = (int)utf8_reader.position();
		if (midpoint == search_lower || midpoint == search_upper)
			break;
		Size midpoint_size = GetVisualTextSize(canvas, clip_start_offset, midpoint - clip_start_offset);
		if (width < midpoint_size.width)
			search_upper = midpoint;
		else
			search_lower = midpoint;
	}
	clip_end_offset = search_upper;
	if (cursor_rect.x < 0.0)
	{
		clip_start_offset = cursor_position;
	}
}

// Get rectangle for cursor position
Rect LineEdit::GetCursorRect()
{
	Canvas* canvas = GetCanvas();
	if (!canvas)
		return Rect::xywh(0.0, 0.0, 0.0, 0.0);
	int substr_end = cursor_position - clip_start_offset;
	if (substr_end < 0)
		substr_end = 0;
	std::string clipped_text = displayed_text.substr(clip_start_offset, substr_end);
	if (password_display)
	{
		// If we are in password mode, we gonna return the right characters
		clipped_text = CreatePassword(UTF8Reader::utf8_length(clipped_text));
	}
	Size text_size_before_cursor = canvas->measureText(clipped_text).size();
	Rect cursor_rect;
	cursor_rect.x = text_size_before_cursor.width;
	cursor_rect.width = 1.0f;
	cursor_rect.y = vertical_text_align.top;
	cursor_rect.height = vertical_text_align.bottom - vertical_text_align.top;
	return cursor_rect;
}

// Get rectangle for selection
Rect LineEdit::GetSelectionRect()
{
	Canvas* canvas = GetCanvas();
	if (!canvas)
		return Rect::xywh(0.0, 0.0, 0.0, 0.0);
	// text before selection:
	std::string txt_before = GetVisibleTextBeforeSelection();
	Size text_size_before_selection = canvas->measureText(txt_before).size();
	// selection text:
	std::string txt_selected = GetVisibleSelectedText();
	Size text_size_selection = canvas->measureText(txt_selected).size();
	Rect selection_rect;
	selection_rect.x = text_size_before_selection.width;
	selection_rect.width = text_size_selection.width;
	selection_rect.y = vertical_text_align.top;
	selection_rect.height = vertical_text_align.bottom - vertical_text_align.top;
	return selection_rect;
}

// Find next break character position
int LineEdit::FindNextBreakCharacter(int search_start)
{
	if (search_start >= int(displayed_text.size()) - 1)
		return (int)displayed_text.size();
	size_t pos = displayed_text.find_first_of(break_characters, search_start);
	if (pos == std::string::npos)
		return (int)displayed_text.size();
	return (int)pos;
}

// Find previous break character position
int LineEdit::FindPreviousBreakCharacter(int search_start)
{
	if (search_start <= 0)
		return 0;
	size_t pos = displayed_text.find_last_of(break_characters, search_start);
	if (pos == std::string::npos)
		return 0;
	return (int)pos;
}

// Handle timer expiration for cursor blinking
void LineEdit::OnTimerExpired()
{
	if (!IsVisible())
	{
		input_timer->Stop();
		return;
	}
	if (cursor_blink_visible)
		input_timer->Start(500);
	else
		input_timer->Start(500);
	cursor_blink_visible = !cursor_blink_visible;
	Update();
}

// Handle geometry changes
void LineEdit::OnGeometryChanged()
{
	Canvas* canvas = GetCanvas();
	if (!canvas)
		return;
	vertical_text_align = canvas->verticalTextAlign();
	clip_start_offset = 0;
	cursor_position = 0;
	UpdateTextClipping();
}

// Get visible text before selection
std::string LineEdit::GetVisibleTextBeforeSelection()
{
	std::string ret;
	int sel_start = std::min(selection_start, selection_start + selection_extent);
	int start = std::min(sel_start, clip_start_offset);
	if (start < clip_start_offset)
		return ret;
	int end = std::min(sel_start, clip_end_offset);
	ret = displayed_text.substr(start, end - start);
	// If we are in password mode, we gonna return the right characters
	if (password_display)
		ret = CreatePassword(UTF8Reader::utf8_length(ret));
	return ret;
}

// Get visible selected text
std::string LineEdit::GetVisibleSelectedText()
{
	std::string ret;
	if (selection_extent == 0)
		return ret;
	int sel_start = std::min(selection_start, selection_start + selection_extent);
	int sel_end = std::max(selection_start, selection_start + selection_extent);
	int end = std::min(clip_end_offset, sel_end);
	int start = std::max(clip_start_offset, sel_start);
	if (start > end)
		return ret;
	if (start == end)
		return ret;
	ret = displayed_text.substr(start, end - start);
	// If we are in password mode, we gonna return the right characters
	if (password_display)
		ret = CreatePassword(UTF8Reader::utf8_length(ret));
	return ret;
}

// Set selection start position
void LineEdit::SetSelectionStart(int start)
{
	if (FuncSelectionChanged && selection_extent && selection_start != start)
		FuncSelectionChanged();
	selection_start = start;
}

// Set selection length
void LineEdit::SetSelectionLength(int length)
{
	if (FuncSelectionChanged && selection_extent != length)
		FuncSelectionChanged();
	selection_extent = length;
}

// Set complete selection
void LineEdit::SetTextSelection(int start, int length)
{
	if (FuncSelectionChanged && (selection_extent != length || (selection_extent && selection_start != start)))
		FuncSelectionChanged();
	selection_start = start;
	selection_extent = length;
}

// Get visible text after selection
std::string LineEdit::GetVisibleTextAfterSelection()
{
	// returns the whole visible string if there is no selection.
	std::string ret;
	int sel_end = std::max(selection_start, selection_start + selection_extent);
	int start = std::max(clip_start_offset, sel_end);
	int end = clip_end_offset;
	if (start > end)
		return ret;
	if (clip_end_offset == sel_end)
		return ret;
	if (sel_end <= 0)
		return ret;
	else
	{
		ret = displayed_text.substr(start, end - start);
		// If we are in password mode, we gonna return the right characters
		if (password_display)
			ret = CreatePassword(UTF8Reader::utf8_length(ret));
		return ret;
	}
}

// Paint the widget
void LineEdit::OnPaint(Canvas* canvas)
{
	std::string txt_before = GetVisibleTextBeforeSelection();
	std::string txt_selected = GetVisibleSelectedText();
	std::string txt_after = GetVisibleTextAfterSelection();
	if (txt_before.empty() && txt_selected.empty() && txt_after.empty())
	{
		txt_after = displayed_text.substr(clip_start_offset, clip_end_offset - clip_start_offset);
		// If we are in password mode, we gonna return the right characters
		if (password_display)
			txt_after = CreatePassword(UTF8Reader::utf8_length(txt_after));
	}
	Size size_before = canvas->measureText(txt_before).size();
	Size size_selected = canvas->measureText(txt_selected).size();
	if (!txt_selected.empty())
	{
		// Draw selection box.
		Rect selection_rect = GetSelectionRect();
		canvas->fillRect(selection_rect, HasFocus() ? GetStyleColor("selection-color") : GetStyleColor("no-focus-selection-color"));
	}
	// Draw text before selection
	if (!txt_before.empty())
	{
		canvas->drawText(Point(0.0, canvas->verticalTextAlign().baseline), GetStyleColor("color"), txt_before);
	}
	if (!txt_selected.empty())
	{
		canvas->drawText(Point(size_before.width, canvas->verticalTextAlign().baseline), GetStyleColor("selection-text"), txt_selected);
	}
	if (!txt_after.empty())
	{
		canvas->drawText(Point(size_before.width + size_selected.width, canvas->verticalTextAlign().baseline), GetStyleColor("color"), txt_after);
	}
	// draw cursor
	if (HasFocus())
	{
		if (cursor_blink_visible)
		{
			Rect cursor_rect = GetCursorRect();
			canvas->fillRect(cursor_rect, GetStyleColor("color"));
		}
	}
}

// Handle scrolling timer expiration
void LineEdit::OnScrollTimerExpired()
{
	if (mouse_moves_left)
		Move(-1, false, false);
	else
		Move(1, false, false);
}

// Handle enable state changes
void LineEdit::OnEnableChanged()
{
	bool enabled = IsEnabled();
	if (!enabled)
	{
		cursor_blink_visible = false;
		input_timer->Stop();
	}
	Update();
}

