#include "platform/http_thread_qt.hpp"
#include "platform/http_thread_callback.hpp"
#include "platform/platform.hpp"
#include "base/logging.hpp"
#include <QNetworkAccessManager>
#include <QNetworkRequest>
#include <QSslError>
#include <QUrl>

HttpThread::HttpThread(std::string const & targetUrl, downloader::IHttpThreadCallback & handler,
                       int64_t startOffset, int64_t finishOffset, int64_t expectedSize,
                       std::string const & payloadBody)
  : m_callback(handler)
  , m_begRange(startOffset)
  , m_endRange(finishOffset)
  , m_downloadedBytes(0)
  , m_expectedSize(expectedSize)
{
  QUrl const urlObj(targetUrl.c_str());
  QNetworkRequest req(urlObj);

  // Apply Range header only when not fetching entire file from beginning
  if (!(startOffset == 0 && finishOffset < 0))
  {
    if (finishOffset > 0)
    {
      LOG(LDEBUG, (targetUrl, "fetching range [", startOffset, ",", finishOffset, "]"));
      QString const rangeHeader = QString("bytes=") + QString::number(startOffset) + '-' + QString::number(finishOffset);
      req.setRawHeader("Range", rangeHeader.toUtf8());
    }
    else
    {
      LOG(LDEBUG, (targetUrl, "resuming download at offset", startOffset));
      QString const resumeRange = QString("bytes=") + QString::number(startOffset) + '-';
      req.setRawHeader("Range", resumeRange.toUtf8());
    }
  }

  /// Reuse single manager instance across application
  static QNetworkAccessManager netMgr;
  if (payloadBody.empty())
    m_reply = netMgr.get(req);
  else
  {
    req.setRawHeader("Content-Type", "application/json");
    req.setRawHeader("Content-Length", QString::number(payloadBody.size()).toLocal8Bit());
    m_reply = netMgr.post(req, payloadBody.c_str());
  }

  connect(m_reply, SIGNAL(metaDataChanged()), this, SLOT(OnHeadersReceived()));
  connect(m_reply, SIGNAL(readyRead()), this, SLOT(OnChunkDownloaded()));
  connect(m_reply, SIGNAL(finished()), this, SLOT(OnDownloadFinished()));

  LOG(LDEBUG, ("Establishing connection to", targetUrl, "[", startOffset, ",", finishOffset, "]", "size=", expectedSize));
}

HttpThread::~HttpThread()
{
  LOG(LDEBUG, ("Releasing HttpThread resources"));
  disconnect(m_reply, SIGNAL(metaDataChanged()), this, SLOT(OnHeadersReceived()));
  disconnect(m_reply, SIGNAL(readyRead()), this, SLOT(OnChunkDownloaded()));
  disconnect(m_reply, SIGNAL(finished()), this, SLOT(OnDownloadFinished()));
  m_reply->deleteLater();
}

void HttpThread::OnHeadersReceived()
{
  // Skip callback notification here; OnDownloadFinished() will always be invoked later
  // Note: invoking reply methods after abort() may cause crashes
  if (m_reply->error())
    return;

  int const statusCode = m_reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();

  bool const isPartial = !(m_begRange == 0 && m_endRange < 0);
  if ((isPartial && statusCode != 206) || (!isPartial && statusCode != 200))
  {
    LOG(LWARNING,
        ("HTTP request to", m_reply->url().toEncoded().constData(), "terminated with status", statusCode));
    m_reply->abort();
  }
  else if (m_expectedSize > 0)
  {
    // First attempt to validate size using Content-Range header
    if (m_reply->hasRawHeader("Content-Range"))
    {
      QList<QByteArray> const parts = m_reply->rawHeader("Content-Range").split('/');
      int const count = parts.size();
      if (count && parts.at(count - 1).toLongLong() != m_expectedSize)
      {
        LOG(LWARNING, ("HTTP request to", m_reply->url().toEncoded().constData(),
                       "aborted due to mismatched Content-Range:", parts.at(count - 1).toLongLong()));
        m_reply->abort();
      }
    }
    // Fallback to Content-Length header
    else if (m_reply->hasRawHeader("Content-Length"))
    {
      QByteArray const lenHeader = m_reply->rawHeader("Content-Length");
      int64_t const actualSize = lenHeader.toLongLong();
      if (actualSize != m_expectedSize)
      {
        LOG(LWARNING, ("HTTP request to", m_reply->url().toEncoded().constData(),
                       "aborted due to invalid Content-Length:", m_reply->rawHeader("Content-Length").toLongLong()));
        m_reply->abort();
      }
    }
    else
    {
      LOG(LWARNING, ("HTTP request to", m_reply->url().toEncoded().constData(),
                     "aborted — no valid file size provided by server"));
      m_reply->abort();
    }
  }
}

void HttpThread::OnChunkDownloaded()
{
  QByteArray const buffer = m_reply->readAll();
  int const bytesRead = buffer.size();
  m_downloadedBytes += bytesRead;
  m_callback.OnWrite(m_begRange + m_downloadedBytes - bytesRead, buffer.constData(), bytesRead);
}

void HttpThread::OnDownloadFinished()
{
  if (m_reply->error() != QNetworkReply::NetworkError::NoError)
  {
    int const httpStatus = m_reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
    LOG(LWARNING, ("Download completed with status:", httpStatus, "error:", m_reply->errorString().toStdString()));
    m_callback.OnFinish(httpStatus, m_begRange, m_endRange);
  }
  else
  {
    m_callback.OnFinish(200, m_begRange, m_endRange);
  }
}

