#include "lz4.h"
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

enum {
    BUFFER_SIZE = 1024 * 8,
//  BUFFER_SIZE = 1024 * 64,
};

size_t write_integer(FILE* stream, int value) {
    return fwrite(&value, sizeof(value), 1, stream);
}

size_t write_binary(FILE* stream, const void* data, size_t size) {
    return fwrite(data, 1, size, stream);
}

size_t read_integer(FILE* stream, int* value) {
    return fread(value, sizeof(*value), 1, stream);
}

size_t read_binary(FILE* stream, void* buffer, size_t size) {
    return fread(buffer, 1, size, stream);
}

void perform_compression(FILE* output, FILE* input)
{
    LZ4_stream_t compressionContext;
    LZ4_stream_t* contextPtr = &compressionContext;
    char inputBuffer[2][BUFFER_SIZE];
    int bufferSelector = 0;

    LZ4_resetStream(contextPtr);
    for(;;) {
        char* const currentInput = inputBuffer[bufferSelector];
        const int bytesRead = (int) read_binary(input, currentInput, BUFFER_SIZE);
        if(0 == bytesRead) {
            break;
        }
        {
            char compressedBuffer[LZ4_COMPRESSBOUND(BUFFER_SIZE)];
            const int compressedSize = LZ4_compress_fast_continue(
                contextPtr, currentInput, compressedBuffer, bytesRead, sizeof(compressedBuffer), 1);
            if(compressedSize <= 0) {
                break;
            }
            write_integer(output, compressedSize);
            write_binary(output, compressedBuffer, (size_t) compressedSize);
        }
        bufferSelector = (bufferSelector + 1) % 2;
    }
    write_integer(output, 0);
}

void perform_decompression(FILE* output, FILE* input)
{
    LZ4_streamDecode_t decompressionContext;
    LZ4_streamDecode_t* contextPtr = &decompressionContext;
    char outputBuffer[2][BUFFER_SIZE];
    int bufferSelector = 0;

    LZ4_setStreamDecode(contextPtr, NULL, 0);
    for(;;) {
        char compressedBuffer[LZ4_COMPRESSBOUND(BUFFER_SIZE)];
        int  compressedSize = 0;
        {
            const size_t readStatus0 = read_integer(input, &compressedSize);
            if(readStatus0 != 1 || compressedSize <= 0) {
                break;
            }
            const size_t readStatus1 = read_binary(input, compressedBuffer, (size_t) compressedSize);
            if(readStatus1 != (size_t) compressedSize) {
                break;
            }
        }
        {
            char* const currentOutput = outputBuffer[bufferSelector];
            const int decompressedSize = LZ4_decompress_safe_continue(
                contextPtr, compressedBuffer, currentOutput, compressedSize, BUFFER_SIZE);
            if(decompressedSize <= 0) {
                break;
            }
            write_binary(output, currentOutput, (size_t) decompressedSize);
        }
        bufferSelector = (bufferSelector + 1) % 2;
    }
}

int compare_files(FILE* fileA, FILE* fileB)
{
    int result = 0;
    while(0 == result) {
        char bufferA[65536];
        char bufferB[65536];
        const size_t countA = read_binary(fileA, bufferA, sizeof(bufferA));
        const size_t countB = read_binary(fileB, bufferB, sizeof(bufferB));
        result = (int) countA - (int) countB;
        if(0 == countA || 0 == countB) {
            break;
        }
        if(0 == result) {
            result = memcmp(bufferA, bufferB, countA);
        }
    }
    return result;
}

int main(int argc, char* argv[])
{
    char inputFile[256] = { 0 };
    char lz4File[256] = { 0 };
    char outputFile[256] = { 0 };

    if(argc < 2) {
        printf("Please specify input filename\n");
        return 0;
    }

    snprintf(inputFile, 256, "%s", argv[1]);
    snprintf(lz4File, 256, "%s.lz4s-%d", argv[1], BUFFER_SIZE);
    snprintf(outputFile, 256, "%s.lz4s-%d.dec", argv[1], BUFFER_SIZE);

    printf("input = [%s]\n", inputFile);
    printf("lz4   = [%s]\n", lz4File);
    printf("output= [%s]\n", outputFile);

    // compress
    {
        FILE* inputFp = fopen(inputFile, "rb");
        FILE* outputFp = fopen(lz4File, "wb");
        printf("compress : %s -> %s\n", inputFile, lz4File);
        perform_compression(outputFp, inputFp);
        printf("compress : done\n");
        fclose(outputFp);
        fclose(inputFp);
    }

    // decompress
    {
        FILE* inputFp = fopen(lz4File, "rb");
        FILE* outputFp = fopen(outputFile, "wb");
        printf("decompress : %s -> %s\n", lz4File, outputFile);
        perform_decompression(outputFp, inputFp);
        printf("decompress : done\n");
        fclose(outputFp);
        fclose(inputFp);
    }

    // verify
    {
        FILE* originalFp = fopen(inputFile, "rb");
        FILE* decodedFp = fopen(outputFile, "rb");
        printf("verify : %s <-> %s\n", inputFile, outputFile);
        const int diff = compare_files(originalFp, decodedFp);
        if(0 == diff) {
            printf("verify : OK\n");
        } else {
            printf("verify : NG\n");
        }
        fclose(decodedFp);
        fclose(originalFp);
    }

    return 0;
}

