WrappedValue::WrappedValue() { }

std::shared_ptr<WrappedValue> WrappedValue::createInstance(std::shared_ptr<llvm::Module> mod, std::shared_ptr<llvm::IRBuilder<>> builder, llvm::Value *val, std::shared_ptr<ValueType> typeInfo) {
    std::shared_ptr<WrappedValue> instance = std::make_shared<WrappedValue>();
    instance->typeInfo = typeInfo;

    if (llvm::LoadInst *load = llvm::dyn_cast<llvm::LoadInst>(val)) {
        instance->getValueLambda = [load]() { return load; };
        instance->getPointerLambda = [load]() { return load->getPointerOperand(); };
        instance->llvmType = load->getType();
    } 
    else if (llvm::AllocaInst *alloca = llvm::dyn_cast<llvm::AllocaInst>(val)) {
        instance->getValueLambda = [builder, alloca]() {
            return builder->CreateLoad(alloca->getAllocatedType(), alloca);
        };
        instance->getPointerLambda = [alloca]() { return alloca; };
        instance->llvmType = alloca->getAllocatedType();
    } 
    else if (llvm::CallInst *call = llvm::dyn_cast<llvm::CallInst>(val)) {
        llvm::FunctionType *funcType = call->getFunctionType();
        llvm::Type *returnType = funcType->getReturnType();

        if (returnType->isVoidTy()) {
            instance->getValueLambda = [returnType]() { return llvm::UndefValue::get(returnType); };
            instance->getPointerLambda = [returnType]() { return llvm::UndefValue::get(returnType); };
        } 
        else {
            instance->getValueLambda = [call]() { return call; };
            instance->getPointerLambda = [builder, returnType, call]() {
                llvm::AllocaInst *alloc = builder->CreateAlloca(returnType, nullptr);
                builder->CreateStore(call, alloc);
                return alloc;
            };
        }
        instance->llvmType = returnType;
    } 
    else if (llvm::Argument *arg = llvm::dyn_cast<llvm::Argument>(val)) {
        llvm::Type *argType = val->getType();
        instance->getValueLambda = [arg]() { return arg; };
        instance->getPointerLambda = [builder, argType, arg]() {
            llvm::AllocaInst *alloc = builder->CreateAlloca(argType, nullptr);
            builder->CreateStore(arg, alloc);
            return alloc;
        };
        instance->llvmType = argType;
    } 
    else if (llvm::GlobalVariable *global = llvm::dyn_cast<llvm::GlobalVariable>(val)) {
        instance->getValueLambda = [global]() { return global; };
        instance->getPointerLambda = [global]() { return global; };
        instance->llvmType = global->getValueType();
    } 
    else if (llvm::Constant *constant = llvm::dyn_cast<llvm::Constant>(val)) {
        if (val->getType()->isVoidTy()) {
            return WrappedValue::createNone(constant->getType(), typeInfo);
        }
        instance->getValueLambda = [constant]() { return constant; };
        instance->getPointerLambda = [mod, constant]() {
            return new llvm::GlobalVariable(
                *mod,
                constant->getType(),
                true,
                llvm::GlobalValue::LinkageTypes::PrivateLinkage,
                constant
            );
        };
        instance->llvmType = val->getType();
    } 
    else {
        instance->getValueLambda = [val]() { return val; };
        instance->getPointerLambda = [builder, val]() {
            llvm::AllocaInst *alloc = builder->CreateAlloca(val->getType());
            builder->CreateStore(val, alloc);
            return alloc;
        };
        instance->llvmType = val->getType();
    }

    return instance;
}

std::shared_ptr<WrappedValue> WrappedValue::createUnsignedInt(llvm::Type *type, uint64_t num, std::shared_ptr<ValueType> typeInfo) {
    std::shared_ptr<WrappedValue> instance = std::make_shared<WrappedValue>();
    instance->getValueLambda = [type, num]() { return llvm::ConstantInt::get(type, num, false); };
    instance->getPointerLambda = [type, num]() { return llvm::ConstantInt::get(type, num, false); };
    instance->llvmType = type;
    instance->typeInfo = typeInfo;
    return instance;
}

std::shared_ptr<WrappedValue> WrappedValue::createNone(llvm::Type *type, std::shared_ptr<ValueType> typeInfo) {
    std::shared_ptr<WrappedValue> instance = std::make_shared<WrappedValue>();
    instance->getValueLambda = [type]() { return llvm::UndefValue::get(type); };
    instance->getPointerLambda = [type]() { return llvm::UndefValue::get(type); };
    instance->llvmType = type;
    instance->typeInfo = typeInfo;
    return instance;
}

llvm::Value *WrappedValue::retrieveValue() {
    if (cachedValue == nullptr)
        cachedValue = getValueLambda();
    return cachedValue;
}

llvm::Value *WrappedValue::retrievePointer() {
    if (cachedPointer == nullptr)
        cachedPointer = getPointerLambda();
    return cachedPointer;
}

llvm::Constant *WrappedValue::asConstant() {
    return llvm::dyn_cast<llvm::Constant>(retrieveValue());
}

llvm::GlobalVariable *WrappedValue::asGlobal() {
    return llvm::dyn_cast<llvm::GlobalVariable>(retrieveValue());
}

llvm::Type *WrappedValue::getType() {
    return llvmType;
}

llvm::ArrayType *WrappedValue::getAsArray() {
    return llvm::dyn_cast<llvm::ArrayType>(llvmType);
}

llvm::StructType *WrappedValue::getAsStruct() {
    return llvm::dyn_cast<llvm::StructType>(llvmType);
}

std::shared_ptr<ValueType> WrappedValue::getTypeInfo() {
    return typeInfo;
}

bool WrappedValue::isDataContainer() {
    return typeInfo->isData();
}

bool WrappedValue::isPointerType() {
    return typeInfo->isPointer();
}

bool WrappedValue::isBlobStructure() {
    return typeInfo->isBlob();
}

