GlyphLines GlyphLinesBuilder::build(const Lines& text_lines, Font* current_font, FontManager* font_mgr)
{
    std::vector<GlyphLine> result_lines;
    result_lines.reserve(text_lines.size());

    for (size_t idx = 0; idx < text_lines.size(); ++idx) {
        result_lines.emplace_back(build(text_lines.getLines()[idx], current_font, font_mgr));
    }

    float height_per_line = current_font->getLineHeight();
    return GlyphLines(result_lines, height_per_line);
}

GlyphLine GlyphLinesBuilder::build(const Line& line_text, Font* current_font, FontManager* font_mgr)
{
    std::vector<GlyphAtom> atoms_output;
    atoms_output.reserve(line_text.size());

    auto source_atoms = line_text.getAtoms();
    for (size_t pos = 0; pos < line_text.size(); ++pos) {
        atoms_output.push_back(build(source_atoms[pos], current_font, font_mgr));
    }

    return GlyphLine(atoms_output);
}

GlyphAtom GlyphLinesBuilder::build(const Atom& atom_data, Font* current_font, FontManager* font_mgr)
{
    auto content_str = atom_data.getContents();
    bool needs_bold = atom_data.getFace().hasAttribute(Attribute::Bold);
    bool needs_italic = atom_data.getFace().hasAttribute(Attribute::Italic);

    Font* effective_font = current_font;

    if (needs_bold || needs_italic) {
        FontStyle requested_style;
        if (needs_bold && needs_italic) {
            requested_style = FontStyle::BoldItalic;
        } else if (needs_bold) {
            requested_style = FontStyle::Bold;
        } else {
            requested_style = FontStyle::Italic;
        }

        Font* styled_font = font_mgr->getFontStyleVariant(current_font, requested_style);
        if (styled_font != nullptr) {
            effective_font = styled_font;
        }
    }

    auto glyph_runs = buildGlyphRuns(content_str, effective_font, font_mgr);
    return GlyphAtom(glyph_runs, atom_data.getFace());
}

std::vector<GlyphRun> GlyphLinesBuilder::buildGlyphRuns(const UTF8String& input_text, Font* base_font, FontManager* font_mgr)
{
    std::vector<GlyphRun> output_runs;

    if (input_text.empty()) {
        return output_runs;
    }

    std::vector<GlyphMetrics> batch_glyphs;
    Font* active_font = nullptr;

    Codepoint cp;
    for (size_t i = 0; i < input_text.size(); ++i) {
        char ch = input_text.at(i);
        if (ch == '\n') {
            cp = ' ';
        } else if (isControlCharacter(ch)) {
            continue;
        } else {
            cp = ch;
        }

        auto glyph_info = font_mgr->getGlyphWithFont(cp, base_font);
        if (active_font == nullptr || active_font == glyph_info.font) {
            active_font = glyph_info.font;
            batch_glyphs.push_back(glyph_info.glyph);
        } else {
            output_runs.emplace_back(batch_glyphs, active_font);
            batch_glyphs.clear();
            active_font = glyph_info.font;
            batch_glyphs.push_back(glyph_info.glyph);
        }
    }

    if (!batch_glyphs.empty()) {
        output_runs.emplace_back(batch_glyphs, active_font);
    }

    return output_runs;
}

std::vector<GlyphRun> GlyphLinesBuilder::buildGlyphRuns(const UTF8String& input_text, Font* base_font)
{
    std::vector<GlyphMetrics> glyphs_list;
    glyphs_list.reserve(input_text.size());

    for (size_t i = 0; i < input_text.size(); ++i) {
        base_font->loadGlyph(input_text.at(i));
        const GlyphMetrics& glyph_metrics = base_font->getGlyphMetrics(input_text.at(i));
        glyphs_list.push_back(glyph_metrics);
    }

    std::vector<GlyphRun> runs_result;
    if (!glyphs_list.empty()) {
        runs_result.emplace_back(glyphs_list, base_font);
    }

    return runs_result;
}

GlyphLines GlyphLinesBuilder::build(const Lines& text_lines, Font* current_font)
{
    std::vector<GlyphLine> lines_result;
    lines_result.reserve(text_lines.size());

    for (size_t idx = 0; idx < text_lines.size(); ++idx) {
        lines_result.emplace_back(build(text_lines.getLines()[idx], current_font));
    }

    float line_spacing = current_font->getLineHeight();
    return GlyphLines(lines_result, line_spacing);
}

GlyphLine GlyphLinesBuilder::build(const Line& line_text, Font* current_font)
{
    std::vector<GlyphAtom> atoms_result;
    atoms_result.reserve(line_text.size());

    auto local_atoms = line_text.getAtoms();
    for (size_t pos = 0; pos < line_text.size(); ++pos) {
        atoms_result.push_back(build(local_atoms[pos], current_font));
    }

    return GlyphLine(atoms_result);
}

GlyphAtom GlyphLinesBuilder::build(const Atom& atom_data, Font* current_font)
{
    auto content_str = atom_data.getContents();
    auto glyph_runs = buildGlyphRuns(content_str, current_font);
    return GlyphAtom(glyph_runs, atom_data.getFace());
}

