unsigned packet_decoder_mp3_common::parseDecoderSetup(const GUID & owner_id, t_size param1, const void * param2, t_size param2size)
{
    if (owner_id == owner_MP3) return 3;
    else if (owner_id == owner_MP2) return 2;
    else if (owner_id == owner_MP1) return 1;
    else if (owner_id == owner_MP4)
    {
        switch(param1)
        {
            case 0x6B:
                return 3;
                break;
            case 0x69:
                return 3;
                break;
            default:
                return 0;
        }
    }
    else if (owner_id == owner_matroska)
    {
        if (param2size == sizeof(matroska_setup))
        {
            const matroska_setup * setup_data = (const matroska_setup*) param2;
            if (!strcmp(setup_data->codec_id, "A_MPEG/L3")) return 3;
            else if (!strcmp(setup_data->codec_id, "A_MPEG/L2")) return 2;
            else if (!strcmp(setup_data->codec_id, "A_MPEG/L1")) return 1;
            else return 0;
        }
        else return 0;
    }
    else return 0;
}

unsigned packet_decoder_mp3_common::layer_from_frame(const void * buffer, size_t length) {
    using namespace mp3_utils;
    TMPEGFrameInfo frame_info;
    if (!ParseMPEGFrameHeader(frame_info, buffer, length)) throw exception_io_data();
    return frame_info.m_layer;
}

