  0x5d681b02UL, 0x2a6f2b94UL, 0xb40bbe37UL, 0xc30c8ea1UL, 0x5a05df1bUL,
  0x2d02ef8dUL
};

// Returns pointer to the CRC32 lookup table
LZO_PUBLIC(const unsigned long*)
get_crc_lookup_table(void)
{
    return crc_table_data;
}

#if 1
// Process single byte using lookup table
#define COMPUTE_CRC_STEP(data,idx) \
    checksum = crc_table_data[((int)checksum ^ data[idx]) & 0xff] ^ (checksum >> 8)
#else
#define COMPUTE_CRC_STEP(data,idx) \
    checksum = crc_table_data[(unsigned char)((unsigned char)checksum ^ data[idx])] ^ (checksum >> 8)
#endif

// Process multiple bytes in batches
#define COMPUTE_2_BYTES(data,idx)  COMPUTE_CRC_STEP(data,idx); COMPUTE_CRC_STEP(data,idx+1);
#define COMPUTE_4_BYTES(data,idx)  COMPUTE_2_BYTES(data,idx); COMPUTE_2_BYTES(data,idx+2);
#define COMPUTE_8_BYTES(data,idx)  COMPUTE_4_BYTES(data,idx); COMPUTE_4_BYTES(data,idx+4);
#define COMPUTE_16_BYTES(data,idx) COMPUTE_8_BYTES(data,idx); COMPUTE_8_BYTES(data,idx+8);

// Main CRC32 computation function
LZO_PUBLIC(unsigned long)
compute_crc32(unsigned long initial, const unsigned char* data, unsigned long length)
{
    unsigned long checksum;
#undef table
#if 1
#  define table crc_table_data
#else
   const unsigned long * table = crc_table_data;
#endif
    if (data == NULL)
        return 0;

    // Initialize checksum with initial value XORed with mask
    checksum = (initial & 0xffffffffUL) ^ 0xffffffffUL;

    // Process data in 16-byte blocks when possible
    if (length >= 16) do
    {
        COMPUTE_16_BYTES(data,0);
        data += 16;
        length -= 16;
    } while (length >= 16);

    // Handle remaining bytes one at a time
    if (length != 0) do
    {
        COMPUTE_CRC_STEP(data,0);
        data += 1;
        length -= 1;
    } while (length > 0);

    // Finalize by XORing with mask again
    return checksum ^ 0xffffffffUL;
#undef table
}
#undef COMPUTE_CRC_STEP
#undef COMPUTE_2_BYTES
#undef COMPUTE_4_BYTES
#undef COMPUTE_8_BYTES
#undef COMPUTE_16_BYTES

#include <gtest/gtest.h>
#include "SmallVector.h"

class SmallVectorTestSuite : public ::testing::Test {
};

TEST_F(SmallVectorTestSuite, AddAndClearElements) {
    SmallVector<int, 3> container;
    container.push_back(10);
    container.push_back(20);
    container.push_back(30);
    container.push_back(40);
    container.push_back(50);
    EXPECT_EQ(container.size(), 5U);
    EXPECT_EQ(container[0], 10);
    EXPECT_EQ(container[1], 20);
    EXPECT_EQ(container[2], 30);
    EXPECT_EQ(container[3], 40);
    EXPECT_EQ(container[4], 50);
    container.clear();
    EXPECT_EQ(container.size(), 0U);
}

TEST_F(SmallVectorTestSuite, LimitedCapacityBehavior) {
    SmallVector<int, 4> container;
    container.push_back(100);
    container.push_back(200);
    EXPECT_EQ(container.size(), 2U);
    EXPECT_EQ(container[0], 100);
    EXPECT_EQ(container[1], 200);
}

TEST_F(SmallVectorTestSuite, EmptyStateVerification) {
    SmallVector<int, 4> container;
    EXPECT_TRUE(container.empty());
    container.push_back(42);
    EXPECT_FALSE(container.empty());
    container.clear();
    EXPECT_TRUE(container.empty());
}

TEST_F(SmallVectorTestSuite, DynamicGrowthHandling) {
    SmallVector<int, 4> container;
    container.push_back(1);
    container.push_back(2);
    EXPECT_EQ(container.size(), 2U);
    EXPECT_EQ(container[0], 1);
    EXPECT_EQ(container[1], 2);

    container.push_back(3);
    container.push_back(4);
    container.push_back(5);
    EXPECT_EQ(container.size(), 5U);
    EXPECT_EQ(container[0], 1);
    EXPECT_EQ(container[1], 2);
    EXPECT_EQ(container[2], 3);
    EXPECT_EQ(container[3], 4);
    EXPECT_EQ(container[4], 5);

    container.clear();
    EXPECT_EQ(container.size(), 0U);

    container.push_back(6);
    container.push_back(7);
    container.push_back(8);
    EXPECT_EQ(container.size(), 3U);
    EXPECT_EQ(container[0], 6);
    EXPECT_EQ(container[1], 7);
    EXPECT_EQ(container[2], 8);

    container.push_back(9);
    container.push_back(10);
    container.push_back(11);
    EXPECT_EQ(container.size(), 6U);
    EXPECT_EQ(container[0], 6);
    EXPECT_EQ(container[1], 7);
    EXPECT_EQ(container[2], 8);
    EXPECT_EQ(container[3], 9);
    EXPECT_EQ(container[4], 10);
    EXPECT_EQ(container[5], 11);

    container.clear();
    EXPECT_EQ(container.size(), 0U);
}

TEST_F(SmallVectorTestSuite, IterationSupport) {
    constexpr size_t CAPACITY = 4;
    std::vector<int> referenceVec;
    SmallVector<int, CAPACITY> testVec;

    // Fill with small data set
    for (size_t idx = 0; idx < CAPACITY; ++idx) {
        testVec.push_back(static_cast<int>(idx));
        referenceVec.push_back(static_cast<int>(idx));
    }

    EXPECT_EQ(testVec.size(), referenceVec.size());
    EXPECT_EQ(testVec, referenceVec);

    size_t index = 0;
    for (auto iter = testVec.begin(); iter != testVec.end(); ++iter, ++index) {
        EXPECT_EQ(*iter, referenceVec[index]);
    }

    index = 0;
    for (int value : testVec) {
        EXPECT_EQ(value, referenceVec[index]);
        ++index;
    }
}

TEST_F(SmallVectorTestSuite, MapOperation) {
    constexpr size_t TOTAL_ITEMS = 100000;
    SmallVector<int, 100> testVec;

    for (size_t i = 0; i < TOTAL_ITEMS; ++i) {
        testVec.push_back(static_cast<int>(i));
    }

    std::vector<int> targetVec;
    testVec.map([&targetVec](int element) {
        targetVec.push_back(element);
    });

    EXPECT_EQ(testVec, targetVec);
}

#include "Rect2i.h"
#include <algorithm>
#include <windows.h>

// Constructor to initialize rectangle with position and dimensions
Rect2i::Rect2i(int x, int y, int w, int h) {
    xPos   = x;
    yPos   = y;
    width  = w;
    height = h;
}

// Compute intersection with another rectangle and modify current rectangle
Rect2i* Rect2i::intersect(const Rect2i* otherRect) {
    int left1   = xPos;
    int top1    = yPos;
    int right1  = xPos + width;
    int bottom1 = yPos + height;

    int left2   = otherRect->getX();
    int top2    = otherRect->getY();
    int right2  = left2 + otherRect->getWidth();
    int bottom2 = top2 + otherRect->getHeight();

    // Calculate intersection boundaries
    xPos   = std::max(left1, left2);
    yPos   = std::max(top1, top2);
    width  = std::max(0, std::min(right1, right2) - xPos);
    height = std::max(0, std::min(bottom1, bottom2) - yPos);

    return this;
}

// Getters
int Rect2i::getX() const { return xPos; }
int Rect2i::getY() const { return yPos; }
int Rect2i::getWidth() const { return width; }
int Rect2i::getHeight() const { return height; }

// Setters
void Rect2i::setX(int x) { xPos = x; }
void Rect2i::setY(int y) { yPos = y; }
void Rect2i::setWidth(int w) { width = w; }
void Rect2i::setHeight(int h) { height = h; }

// Set both position coordinates at once
void Rect2i::setPosition(int x, int y) {
    xPos = x;
    yPos = y;
}

