    int control_flag, var_a, var_b, var_c, var_d, var_e, var_f, var_g, var_h, var_i, var_j, var_k, var_l;
    unsigned int var_m, var_n, var_o, var_p, var_q, var_r, var_s, var_t, var_u, var_v;
