// ---------------------- String to Nested Types Helpers ------------------------------ //
static void skipWhitespaceChars(const char*& input, const char* end) {
    while (input < end) {
        if (*input & 0x80) {
            // We only skip ASCII white spaces there.
            break;
        } else {
            DASSERT(*input >= -1);
            if (!isspace(*input)) {
                break;
            }
        }
        input++;
    }
}

static void trimRightWhitespaceChars(const char* input, const char*& end) {
    while (input < end && isspace(*(end - 1))) {
        end--;
    }
}

static void removeQuotes(const char*& keyStart, const char*& keyEnd) {
    // Skip quotations on struct keys.
    if ((keyStart[0] == '\'' && (keyEnd - 1)[0] == '\'') ||
        (keyStart[0] == '\"' && (keyEnd - 1)[0] == '\"')) {
        keyStart++;
        keyEnd--;
    }
}

static bool findClosingQuote(const char*& input, const char* end) {
    auto ch = *input;
    input++; // skip the first " '
    // TODO: escape char
    while (input != end) {
        if (*input == ch) {
            return true;
        }
        input++;
    }
    return false;
}

static bool findMatchingBracket(const char*& input, const char* end, uint64_t& depth, char target,
    const CSVOption* option) {
    input++;
    while (input != end) {
        if (*input == '\'') {
            if (!findClosingQuote(input, end)) {
                return false;
            }
        } else if (*input == '{') { // must have closing brackets {, ] if they are not quoted
            if (!findMatchingBracket(input, end, depth, '}', option)) {
                return false;
            }
        } else if (*input == CopyConstants::DEFAULT_CSV_LIST_BEGIN_CHAR) {
            if (!findMatchingBracket(input, end, depth, CopyConstants::DEFAULT_CSV_LIST_END_CHAR, option)) {
                return false;
            }
            depth++; // nested one more level
        } else if (*input == target) {
            if (target == CopyConstants::DEFAULT_CSV_LIST_END_CHAR) {
                depth--;
            }
            return true;
        }
        input++;
    }
    return false; // no corresponding closing bracket
}

static bool checkNullValue(std::string_view& str) {
    auto start = str.data();
    auto end = start + str.length();
    skipWhitespaceChars(start, end);
    if (start == end) {
        return true;
    }
    if (end - start >= 4 && (*start == 'N' || *start == 'n') &&
        (*(start + 1) == 'U' || *(start + 1) == 'u') &&
        (*(start + 2) == 'L' || *(start + 2) == 'l') &&
        (*(start + 3) == 'L' || *(start + 3) == 'l')) {
        start += 4;
        skipWhitespaceChars(start, end);
        if (start == end) {
            return true;
        }
    }
    return false;
}

// ---------------------- String to List Processing ------------------------------ //
struct ElementCounterOperation {
    uint64_t elementCount = 0;
    static inline bool processKey(const char* /*start*/, const char* /*end*/,
        const CSVOption* /*config*/) {
        return true;
    }
    inline void processValue(const char* /*start*/, const char* /*end*/,
        const CSVOption* /*config*/) {
        elementCount++;
    }
};

struct ListSplitterOperation {
    ListSplitterOperation(uint64_t& currentIndex, ValueVector* outputVector)
        : currentIndex(currentIndex), outputVector(outputVector) {}
    uint64_t& currentIndex;
    ValueVector* outputVector;

    void processValue(const char* start, const char* end, const CSVOption* config) {
        skipWhitespaceChars(start, end);
        trimRightWhitespaceChars(start, end);
        CastString::copyStringToVector(outputVector, currentIndex,
            std::string_view{start, (uint32_t)(end - start)}, config);
        currentIndex++;
    }
};

template<typename T>
static bool parseCStringList(const char* source, uint64_t length, T& state, const CSVOption* config) {
    auto end = source + length;
    uint64_t depth = 1;
    bool foundValue = false;
    // locate [
    skipWhitespaceChars(source, end);
    if (source == end || *source != CopyConstants::DEFAULT_CSV_LIST_BEGIN_CHAR) {
        return false;
    }
    skipWhitespaceChars(++source, end);
    bool justFinishedEntry = true; // true at start
    auto startPtr = source;
    while (source < end) {
        auto ch = *source;
        if (ch == CopyConstants::DEFAULT_CSV_LIST_BEGIN_CHAR) {
            if (!findMatchingBracket(source, end, ++depth, CopyConstants::DEFAULT_CSV_LIST_END_CHAR, config)) {
                return false;
            }
        } else if ((ch == '\'' || ch == '"') && justFinishedEntry) {
            const char* prevSource = source;
            if (!findClosingQuote(source, end)) {
                source = prevSource;
            }
        } else if (ch == '{') {
            uint64_t struct_depth = 0;
            findMatchingBracket(source, end, struct_depth, '}', config);
        } else if (ch == ',' || ch == CopyConstants::DEFAULT_CSV_LIST_END_CHAR) { // split
            if (ch != CopyConstants::DEFAULT_CSV_LIST_END_CHAR || startPtr < source || foundValue) {
                state.processValue(startPtr, source, config);
                foundValue = true;
            }
            if (ch == CopyConstants::DEFAULT_CSV_LIST_END_CHAR) { // last ]
                depth--;
                break;
            }
            skipWhitespaceChars(++source, end);
            startPtr = source;
            justFinishedEntry = true;
            continue;
        }
        justFinishedEntry = false;
        source++;
    }
    skipWhitespaceChars(++source, end);
    return (source == end && depth == 0);
}

template<typename T>
static bool parseUnbracedList(std::string_view input, T& state, const CSVOption* config) {
    input = StringUtils::ltrim(StringUtils::rtrim(input));
    auto split = StringUtils::smartSplit(input, ';');
    if (split.size() == 1 && input.front() == '[' && input.back() == ']') {
        split = StringUtils::smartSplit(input.substr(1, input.size() - 2), ';');
    }
    for (auto& item : split) {
        state.processValue(item.data(), item.data() + item.length(), config);
    }
    return true;
}

template<typename T>
static inline void beginListConversion(const char* source, uint64_t length, T splitter, const CSVOption* config,
    ValueVector* vector) {
    auto validList = config->allowUnbracedList ?
                         parseUnbracedList(std::string_view(source, length), splitter, config) :
                         parseCStringList(source, length, splitter, config);
    if (!validList) {
        throw ConversionException("Conversion error. " + std::string{source, (size_t)length} +
                                  " is not in " + vector->dataType.toString() + " range.");
    }
}

// ---------------------- String to Array Processing ------------------------------ //
static void validateArrayElementCount(uint64_t elementsRead, const LogicalType& type) {
    auto expectedElements = ArrayType::getNumElements(type);
    if (elementsRead != expectedElements) {
        throw ConversionException(std::format(
            "Each array should have fixed number of elements. Expected: {}, Actual: {}.",
            expectedElements, elementsRead));
    }
}

// ---------------------- String to List/Array Conversion ------------------------------ //
template<>
void StringConverterHelper::convert(const char* source, uint64_t length, list_entry_t& /*result*/,
    ValueVector* vector, uint64_t position, const CSVOption* config) {
    auto logicalTypeID = vector->dataType.getLogicalTypeID();
    // calculate the number of elements in array
    ElementCounterOperation state;
    if (config->allowUnbracedList) {
        parseUnbracedList(std::string_view(source, length), state, config);
    } else {
        parseCStringList(source, length, state, config);
    }
    if (logicalTypeID == LogicalTypeID::ARRAY) {
        validateArrayElementCount(state.elementCount, vector->dataType);
    }
    auto list_entry = ListVector::addList(vector, state.elementCount);
    vector->setValue<list_entry_t>(position, list_entry);
    auto listDataVector = ListVector::getDataVector(vector);
    ListSplitterOperation splitter{list_entry.offset, listDataVector};
    beginListConversion(source, length, splitter, config, vector);
}

template<>
void CastString::operation(const string_t& input, list_entry_t& result, ValueVector* resultVector,
    uint64_t position, const CSVOption* config) {
    StringConverterHelper::convert(reinterpret_cast<const char*>(input.getData()), input.len, result,
        resultVector, position, config);
}

// ---------------------- String to Map Conversion ------------------------------ //
struct MapSplitterOperation {
    MapSplitterOperation(uint64_t& currentIndex, ValueVector* outputVector)
        : currentIndex{currentIndex}, outputVector{outputVector} {}
    uint64_t& currentIndex;
    ValueVector* outputVector;
    ValueSet uniqueKeys;
    // NOLINTNEXTLINE(readability-make-member-function-const): Semantically non-const.
    bool processKey(const char* start, const char* end, const CSVOption* config);
    void processValue(const char* start, const char* end, const CSVOption* config);
};

bool MapSplitterOperation::processKey(const char* start, const char* end,
    const CSVOption* config) {
    trimRightWhitespaceChars(start, end);
    auto fieldVector = StructVector::getFieldVector(outputVector, 0).get();
    CastString::copyStringToVector(fieldVector, currentIndex,
        std::string_view{start, (uint32_t)(end - start)}, config);
    if (fieldVector->isNull(currentIndex)) {
        throw common::ConversionException{"Map does not allow null as key."};
    }
    auto val = common::Value::createDefaultValue(fieldVector->dataType);
    val.copyFromColLayout(fieldVector->getData() + fieldVector->getNumBytesPerValue() * currentIndex,
        fieldVector);
    auto uniqueKey = uniqueKeys.insert(val).second;
    if (!uniqueKey) {
        throw common::ConversionException{"Map does not allow duplicate keys."};
    }
    return true;
}

void MapSplitterOperation::processValue(const char* start, const char* end,
    const CSVOption* config) {
    trimRightWhitespaceChars(start, end);
    CastString::copyStringToVector(StructVector::getFieldVector(outputVector, 1).get(), currentIndex++,
        std::string_view{start, (uint32_t)(end - start)}, config);
}

template<typename T>
static bool extractKeyOrValue(const char*& source, const char* end, T& state, bool isKey,
    bool& closeBracket, const CSVOption* config) {
    auto start = source;
    uint64_t depth = 0;
    while (source < end) {
        if (*source == '"' || *source == '\'') {
            if (!findClosingQuote(source, end)) {
                return false;
            }
        } else if (*source == '{') {
            if (!findMatchingBracket(source, end, depth, '}', config)) {
                return false;
            }
        } else if (*source == CopyConstants::DEFAULT_CSV_LIST_BEGIN_CHAR) {
            if (!findMatchingBracket(source, end, depth, CopyConstants::DEFAULT_CSV_LIST_END_CHAR, config)) {
                return false;
            }
        } else if (isKey && *source == '=') {
            return state.processKey(start, source, config);
        } else if (!isKey && (*source == ',' || *source == '}')) {
            state.processValue(start, source, config);
            if (*source == '}') {
                closeBracket = true;
            }
            return true;
        }
        source++;
    }
    return false;
}

// Split map of format: {a=12,b=13}
template<typename T>
static bool parseCStringMap(const char* source, uint64_t length, T& state, const CSVOption* config) {
    auto end = source + length;
    bool closeBracket = false;
    skipWhitespaceChars(source, end);
    if (source == end || *source != '{') { // start with {
        return false;
    }
    skipWhitespaceChars(++source, end);
    if (source == end) {
        return false;
    }
    if (*source == '}') {
        skipWhitespaceChars(++source, end); // empty
        return source == end;
    }
    while (source < end) {
        if (!extractKeyOrValue(source, end, state, true, closeBracket, config)) {
            return false;
        }
        skipWhitespaceChars(++source, end);
        if (!extractKeyOrValue(source, end, state, false, closeBracket, config)) {
            return false;
        }
        skipWhitespaceChars(++source, end);
        if (closeBracket) {
            return (source == end);
        }
    }
    return false;
}

template<>
void StringConverterHelper::convert(const char* source, uint64_t length, map_entry_t& /*result*/,
    ValueVector* vector, uint64_t position, const CSVOption* config) {
    // count the number of maps in map
    ElementCounterOperation state;
    parseCStringMap(source, length, state, config);
    auto list_entry = ListVector::addList(vector, state.elementCount);
    vector->setValue<list_entry_t>(position, list_entry);
    auto structVector = ListVector::getDataVector(vector);
    MapSplitterOperation splitter{list_entry.offset, structVector};
    if (!parseCStringMap(source, length, splitter, config)) {
        throw ConversionException("Conversion error. " + std::string{source, (size_t)length} +
                                  " is not in " + vector->dataType.toString() + " range.");
    }
}

template<>
void CastString::operation(const string_t& input, map_entry_t& result, ValueVector* resultVector,
    uint64_t position, const CSVOption* config) {
    StringConverterHelper::convert(reinterpret_cast<const char*>(input.getData()), input.len, result,
        resultVector, position, config);
}

// ---------------------- String to Struct Conversion ------------------------------ //
static bool extractStructFieldName(const char*& source, const char* end) {
    while (source < end) {
        if (*source == ':') {
            return true;
        }
        source++;
    }
    return false;
}

static bool extractStructFieldValue(const char*& source, const char* end, const CSVOption* config,
    bool& closeBrack) {
    uint64_t depth = 0;
    while (source < end) {
        if (*source == '"' || *source == '\'') {
            if (!findClosingQuote(source, end)) {
                return false;
            }
        } else if (*source == '{') {
            if (!findMatchingBracket(source, end, depth, '}', config)) {
                return false;
            }
        } else if (*source == CopyConstants::DEFAULT_CSV_LIST_BEGIN_CHAR) {
            if (!findMatchingBracket(source, end, ++depth, CopyConstants::DEFAULT_CSV_LIST_END_CHAR, config)) {
                return false;
            }
        } else if (*source == ',' || *source == '}') {
            if (*source == '}') {
                closeBrack = true;
            }
            return (depth == 0);
        }
        source++;
    }
    return false;
}

static bool tryConvertStringToStruct(const char* source, uint64_t length, ValueVector* vector,
    uint64_t position, const CSVOption* config) {
    // default values to NULL
    auto fieldVectors = StructVector::getFieldVectors(vector);
    for (auto& fieldVector : fieldVectors) {
        fieldVector->setNull(position, true);
    }
    // check if start with {
    auto end = source + length;
    const auto& type = vector->dataType;
    skipWhitespaceChars(source, end);
    if (source == end || *source != '{') {
        return false;
    }
    skipWhitespaceChars(++source, end);
    if (source == end) { // no closing bracket
        return false;
    }
    if (*source == '}') {
        skipWhitespaceChars(++source, end);
        return source == end;
    }
    bool closeBracket = false;
    while (source < end) {
        auto keyStart = source;
        if (!extractStructFieldName(source, end)) { // find key
            return false;
        }
        auto keyEnd = source;
        trimRightWhitespaceChars(keyStart, keyEnd);
        removeQuotes(keyStart, keyEnd);
        auto fieldIdx = StructType::getFieldIdx(type, std::string{keyStart, keyEnd});
        if (fieldIdx == INVALID_STRUCT_FIELD_IDX) {
            throw ParserException{"Invalid struct field name: " + std::string{keyStart, keyEnd}};
        }
        skipWhitespaceChars(++source, end);
        auto valStart = source;
        if (!extractStructFieldValue(source, end, config, closeBracket)) { // find value
            return false;
        }
        auto valEnd = source;
        trimRightWhitespaceChars(valStart, valEnd);
        removeQuotes(valStart, valEnd);
        skipWhitespaceChars(++source, end);
        auto fieldVector = StructVector::getFieldVector(vector, fieldIdx).get();
        fieldVector->setNull(position, false);
        CastString::copyStringToVector(fieldVector, position,
            std::string_view{valStart, (uint32_t)(valEnd - valStart)}, config);
        if (closeBracket) {
            return (source == end);
        }
    }
    return false;
}

template<>
void StringConverterHelper::convert(const char* source, uint64_t length, struct_entry_t& /*result*/,
    ValueVector* vector, uint64_t position, const CSVOption* config) {
    if (!tryConvertStringToStruct(source, length, vector, position, config)) {
        throw ConversionException("Conversion error. " + std::string{source, (size_t)length} +
                                  " is not in " + vector->dataType.toString() + " range.");
    }
}

template<>
void CastString::operation(const string_t& input, struct_entry_t& result, ValueVector* resultVector,
    uint64_t position, const CSVOption* config) {
    StringConverterHelper::convert(reinterpret_cast<const char*>(input.getData()), input.len, result,
        resultVector, position, config);
}

// ---------------------- String to Union Conversion ------------------------------ //
template<typename T>
static inline void assignValueIfValid(ValueVector* vector, uint64_t position, T result, bool success) {
    if (success) {
        vector->setValue(position, result);
    }
}

static bool tryConvertUnionField(ValueVector* vector, uint64_t position, const char* source,
    uint64_t length) {
    auto& targetType = vector->dataType;
    bool success = false;
    switch (targetType.getLogicalTypeID()) {
    case LogicalTypeID::BOOL: {
        bool result = false;
        success = function::tryCastToBool(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::INT128: {
        int128_t result = 0;
        success = function::trySimpleIntegerCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::UINT128: {
        uint128_t result = 0;
        success = function::trySimpleIntegerCast<uint128_t, false>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::INT64: {
        int64_t result = 0;
        success = function::trySimpleIntegerCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::INT32: {
        int32_t result = 0;
        success = function::trySimpleIntegerCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::INT16: {
        int16_t result = 0;
        success = function::trySimpleIntegerCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::INT8: {
        int8_t result = 0;
        success = function::trySimpleIntegerCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::UINT64: {
        uint64_t result = 0;
        success = function::trySimpleIntegerCast<uint64_t, false>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::UINT32: {
        uint32_t result = 0;
        success = function::trySimpleIntegerCast<uint32_t, false>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::UINT16: {
        uint16_t result = 0;
        success = function::trySimpleIntegerCast<uint16_t, false>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::UINT8: {
        uint8_t result = 0;
        success = function::trySimpleIntegerCast<uint8_t, false>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::DOUBLE: {
        double result = 0;
        success = function::tryDoubleCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::FLOAT: {
        float result = 0;
        success = function::tryDoubleCast(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::DECIMAL: {
        switch (targetType.getPhysicalType()) {
        case PhysicalTypeID::INT16: {
            int16_t result = 0;
            tryDecimalCast(source, length, result, DecimalType::getPrecision(targetType),
                DecimalType::getScale(targetType));
            assignValueIfValid(vector, position, result, success);
        } break;
        case PhysicalTypeID::INT32: {
            int32_t result = 0;
            tryDecimalCast(source, length, result, DecimalType::getPrecision(targetType),
                DecimalType::getScale(targetType));
            assignValueIfValid(vector, position, result, success);
        } break;
        case PhysicalTypeID::INT64: {
            int64_t result = 0;
            tryDecimalCast(source, length, result, DecimalType::getPrecision(targetType),
                DecimalType::getScale(targetType));
            assignValueIfValid(vector, position, result, success);
        } break;
        case PhysicalTypeID::INT128: {
            int128_t result = 0;
            tryDecimalCast(source, length, result, DecimalType::getPrecision(targetType),
                DecimalType::getScale(targetType));
            assignValueIfValid(vector, position, result, success);
        } break;
        default:
            UNREACHABLE_CODE;
        }
    } break;
    case LogicalTypeID::DATE: {
        date_t result;
        uint64_t pos = 0;
        success = Date::tryConvertDate(source, length, pos, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::TIMESTAMP_NS: {
        timestamp_ns_t result;
        success = TryCastStringToTimestamp::tryCast<timestamp_ns_t>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::TIMESTAMP_MS: {
        timestamp_ms_t result;
        success = TryCastStringToTimestamp::tryCast<timestamp_ms_t>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::TIMESTAMP_SEC: {
        timestamp_sec_t result;
        success = TryCastStringToTimestamp::tryCast<timestamp_sec_t>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::TIMESTAMP_TZ: {
        timestamp_tz_t result;
        success = TryCastStringToTimestamp::tryCast<timestamp_tz_t>(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::TIMESTAMP: {
        timestamp_t result;
        success = Timestamp::tryConvertTimestamp(source, length, result);
        assignValueIfValid(vector, position, result, success);
    } break;
    case LogicalTypeID::STRING: {
        if (!utf8proc::Utf8Proc::isValid(source, length)) {
            throw ConversionException{"Invalid UTF8-encoded string."};
        }
        StringVector::addString(vector, position, source, length);
        return true;
    }
    default: {
        return false;
    }
    }
    return success;
}

template<>
void StringConverterHelper::convert(const char* source, uint64_t length, union_entry_t& /*result*/,
    ValueVector* vector, uint64_t position, const CSVOption* /*settings*/) {
    auto& type = vector->dataType;
    union_field_idx_t selectedFieldIdx = INVALID_STRUCT_FIELD_IDX;
    auto i = 0u;
    for (; i < UnionType::getNumFields(type); i++) {
        auto internalFieldIdx = UnionType::getInternalFieldIdx(i);
        auto fieldVector = StructVector::getFieldVector(vector, internalFieldIdx).get();
        if (tryConvertUnionField(fieldVector, position, source, length)) {
            fieldVector->setNull(position, false /* isNull */);
            selectedFieldIdx = i;
            i++;
            break;
        } else {
            fieldVector->setNull(position, true /* isNull */);
        }
    }
    for (; i < UnionType::getNumFields(type); i++) {
        auto fieldVector = UnionVector::getValVector(vector, i);
        fieldVector->setNull(position, true /* isNull */);
    }
    if (selectedFieldIdx == INVALID_STRUCT_FIELD_IDX) {
        throw ConversionException{std::format("Could not convert to union type {}: {}.",
            type.toString(), std::string{source, (size_t)length})};
    }
    StructVector::getFieldVector(vector, UnionType::TAG_FIELD_IDX)
        ->setValue(position, selectedFieldIdx);
    StructVector::getFieldVector(vector, UnionType::TAG_FIELD_IDX)
        ->setNull(position, false /* isNull */);
}

template<>
