// Interactive button component
bool Gui::CreateButton(float widthFactor, const char* label, ...) {
    va_list args;
    va_start(args, label);

    // int textWidth = SpriteBatch_CalcTextWidthVargs(label, args);
    int x = windowLeft + relX;
    int y = windowTop + relY - BUTTON_TEXT_PADDING;

    int btnWidth = (widthFactor <= 0.f) ? /*textWidth + SliceSize*/ 100 : scaleToAbsolute(widthFactor);
    bool isPressed = IsPointerInside(x, y, btnWidth, BUTTON_HEIGHT);

    int middlePart = btnWidth - SliceSize * 2;

    RenderData->DrawTex(ReCraftCore::GetInstance()->GetAssetManager()->Get<Amy::Texture>("GuiTexture_Widgets"));
    int baseY = 66 + (isPressed * BUTTON_HEIGHT);

    DrawTexturedModalRect(x, y, 0, baseY, SliceSize, BUTTON_HEIGHT);
    DrawTexturedModalRect(x + SliceSize, y, SliceSize, baseY, middlePart, BUTTON_HEIGHT);
    DrawTexturedModalRect(x + SliceSize + middlePart, y, 192, baseY, SliceSize, BUTTON_HEIGHT);

    Amy::Color fontColor = isPressed ? Amy::Color(255, 255, 160, 255) : Amy::Color(224, 224, 224, 255);
    DrawCenteredString(label, x + (btnWidth * 0.5f), y + (BUTTON_HEIGHT * 0.5f), fontColor);

    va_end(args);

    relX += btnWidth + offsetX;
    currentRow.maxElementHeight = std::max(currentRow.maxElementHeight, BUTTON_HEIGHT);

    return Input::isKeyUp(KEY_TOUCH) && WasPointerInside(x, y, btnWidth, BUTTON_HEIGHT);
}

