bool Gui::IsPointerInside(int x, int y, int w, int h) {
    int touchX = Input::getTouch().px / 2; // m_guiScale;
    int touchY = Input::getTouch().py / 2; // m_guiScale;
    return touchX != 0 && touchY != 0 && 
           touchX >= x && touchX < x + w && 
           touchY >= y && touchY < y + h;
}

bool Gui::WasPointerInside(int x, int y, int w, int h) {
    int prevX = Input::getTouchPrev().px / 2; // m_guiScale;
    int prevY = Input::getTouchPrev().py / 2; // m_guiScale;
    return prevX != 0 && prevY != 0 && 
           prevX >= x && prevX < x + w && 
           prevY >= y && prevY < y + h;
}

bool Gui::JustEnteredPointer(int x, int y, int w, int h) {
    int prevX = Input::getTouchPrev().px / 2; // m_guiScale;
    int prevY = Input::getTouchPrev().py / 2; // m_guiScale;
    return (prevX == 0 && prevY == 0) && IsPointerInside(x, y, w, h);
}

void Gui::GetPointerDelta(int* dx, int* dy) {
    if ((Input::getTouch().px == 0 && Input::getTouch().py == 0) ||
        (Input::getTouchPrev().px == 0 && Input::getTouchPrev().py == 0)) {
        *dx = 0;
        *dy = 0;
        return;
    }

    *dx = Input::getTouch().px / 2 - Input::getTouchPrev().px / 2;
    *dy = Input::getTouch().py / 2 - Input::getTouchPrev().py / 2;
}

