Amy::Color applyFontShadow(const Amy::Color& original) {
    uint32_t rgba = (original.r << 24) | (original.g << 16) | (original.b << 8) | original.a;
    uint32_t shifted = (rgba & 16579836) >> 2 | rgba & -16777216;
    return Amy::Color(shifted);
}

void Gui::DrawTextWithShadow(const std::string& content, int x, int y, const Amy::Color& color) const {
    DrawText(content, x + 1, y + 1, applyFontShadow(color));
    DrawText(content, x, y, color);
}

void Gui::DrawCenteredText(const std::string& content, int x, int y, const Amy::Color& color, bool shadow) const {
    if (shadow) {
        renderList->DrawTextEx(Amy::ivec2((x + 1) * 2, (y + 1) * 2), 
                               content, applyFontShadow(color), AmyTextFlags_AlignMid);
    }
    renderList->DrawTextEx(Amy::fvec2(x * 2, y * 2), content, color, AmyTextFlags_AlignMid);
}

