Amy::fvec3 transformPoint(const Amy::mat4& matrix, const Amy::fvec3& point) {
    Amy::fvec3 result;
    result.x = Amy::fvec3(matrix(0, 0), matrix(0, 1), matrix(0, 2)).Dot(point);
    result.y = Amy::fvec3(matrix(1, 0), matrix(1, 1), matrix(1, 2)).Dot(point);
    result.z = Amy::fvec3(matrix(2, 0), matrix(2, 1), matrix(2, 2)).Dot(point);
    return result;
}

void Gui::RenderBlockIcon(BlockID blockId, uint8_t meta, Amy::fvec2 position) {
    int tileCount = TextureMap::UvPrecision / BlockRegistry::GetTextureMapEx()->GetMapTiles();
    static WorldVertex vertices[6 * 6];

    memcpy(vertices, cube_sides_lut, sizeof(WorldVertex) * 36);

    if (!blockTexture) {
        blockTexture = Amy::Texture::New();
        blockTexture->Load((C3D_Tex*)BlockRegistry::GetTextureMap(), 
                          BlockRegistry::GetTextureMapEx()->GetMapSize(),
                          Amy::fvec4(0, 1, 1, 0));
    }

    auto command = renderList->NewCommand();
    command->Tex = blockTexture;

    for (int face = 0; face < 6; face++) {
        if (face != Direction::Top && face != Direction::South && face != Direction::West)
            continue;

        int16_t uvCoords[2];
        uint8_t rgb[3];

        BlockRegistry::GetBlock(blockId)->getTexture((Direction)face, uvCoords);
        BlockRegistry::GetBlock(blockId)->getColor(meta, (Direction)face, rgb);

        for (int v = 0; v < 5; v++) {
            int idx = face * 6 + v;
            Amy::fvec3 p = Amy::fvec3(vertices[idx].xyz[0] - 0.5f, 
                                     vertices[idx].xyz[1] - 0.5f, 
                                     vertices[idx].xyz[2] - 0.5f);

            auto transformed = transformPoint(iconTransform, p);
            int scale = 16;
            vertices[idx].xyz[0] = FastFloor(transformed.x * scale) + (position.x + scale + 2);
            vertices[idx].xyz[1] = -FastFloor(transformed.y * scale) + (position.y + scale + 2);
        }

        Amy::fvec2 bl = Amy::fvec2(vertices[face * 6 + 0].xyz[0], vertices[face * 6 + 0].xyz[1]);
        Amy::fvec2 br = Amy::fvec2(vertices[face * 6 + 1].xyz[0], vertices[face * 6 + 1].xyz[1]);
        Amy::fvec2 tr = Amy::fvec2(vertices[face * 6 + 2].xyz[0], vertices[face * 6 + 2].xyz[1]);
        Amy::fvec2 tl = Amy::fvec2(vertices[face * 6 + 4].xyz[0], vertices[face * 6 + 4].xyz[1]);

        u32 finalColor = Amy::Color(rgb[0], rgb[1], rgb[2], 255);
        if (face == Direction::South) {
            finalColor = Amy::Color(rgb[0] * 0.8f, rgb[1] * 0.8f, rgb[2] * 0.8f, 255);
        } else if (face == Direction::West) {
            finalColor = Amy::Color(rgb[0] * 0.9f, rgb[1] * 0.9f, rgb[2] * 0.9f, 255);
        }

        Amy::Rect uvRect = Amy::fvec4((float)uvCoords[0] / (float)TextureMap::UvPrecision,
                                     (float)(uvCoords[1] + tileCount) / (float)TextureMap::UvPrecision,
                                     (float)(uvCoords[0] + tileCount) / (float)TextureMap::UvPrecision,
                                     (float)uvCoords[1] / (float)TextureMap::UvPrecision);

        command->PreAllocate(4, 6);
        command->Add(0).Add(1).Add(2);
        command->Add(0).Add(2).Add(3);

        command->Add(Amy::Iron::Vertex(br, uvRect.BotRight(), finalColor));
        command->Add(Amy::Iron::Vertex(tr, uvRect.TopRight(), finalColor));
        command->Add(Amy::Iron::Vertex(tl, uvRect.TopLeft(), finalColor));
        command->Add(Amy::Iron::Vertex(bl, uvRect.BotLeft(), finalColor));
    }
}

