/*! \file terodilate.cpp
This file contains an implementation of a greyscale (ie per-channel)
erode/dilate
morphological operator, following the van Herk/Gil-Werman O(row*cols) algorithm.
An extension with circular structuring element is attempted - unfortunately I
could
not retrieve a copy of Miyataka's paper about that, which seemingly claimed
O(rows * cols) too. The implemented algorithm is a sub-optimal
O(rows*cols*radius).
*/
//********************************************************
//    Helper  functions
//********************************************************
namespace {
template <typename Pix>
void copyMatte(const TRasterPT<Pix> &source,
               const TRasterPT<typename Pix::Channel> &alpha) {
  typedef typename Pix::Channel Chan;
  int row, width = source->getLx(), height = source->getLy();
  for (row = 0; row != height; ++row) {
    Pix *s, *sStart = source->pixels(row), *sFinish = sStart + width;
    Chan *a, *aStart = alpha->pixels(row);
    for (s = sStart, a = aStart; s != sFinish; ++s, ++a) *a = s->m;
  }
}
//--------------------------------------------------------------
template <typename Pix>
void copyChannels_erode(const TRasterPT<Pix> &source,
                        const TRasterPT<typename Pix::Channel> &alpha,
                        const TRasterPT<Pix> &destination) {
  typedef typename Pix::Channel Chan;
  // Just assemble source and alpha, remembering to depremultiply source pixels before
  // applying the new alpha
  double factor;
  int row, width = source->getLx(), height = source->getLy();
  for (row = 0; row != height; ++row) {
    const Pix *s, *sStart = source->pixels(row), *sFinish = sStart + width;
    Pix *d, *dStart = destination->pixels(row);
    Chan *a, *aStart = alpha->pixels(row);
    for (s = sStart, d = dStart, a = aStart; s != sFinish; ++s, ++d, ++a) {
      factor  = double(*a) / double(s->m);
      d->r = factor * s->r, d->g = factor * s->g, d->b = factor * s->b, d->m = *a;
    }
  }
}
//--------------------------------------------------------------
template <typename Pix>
void copyChannels_dilate(const TRasterPT<Pix> &source,
                         const TRasterPT<typename Pix::Channel> &alpha,
                         const TRasterPT<Pix> &destination) {
  typedef typename Pix::Channel Chan;
  // Trickier - since source is presumably premultiplied, increasing its pixels'
  // alpha by direct
  // substitution would expose the excessive RGB discretization of pixels with a
  // low alpha value.
  // So, let's just put the pixels on a black background. It should do fine.
  double maxVal = Pix::maxChannelValue;
  int row, width = source->getLx(), height = source->getLy();
  for (row = 0; row != height; ++row) {
    const Pix *s, *sStart = source->pixels(row), *sFinish = sStart + width;
    Pix *d, *dStart = destination->pixels(row);
    const Chan *a, *aStart = alpha->pixels(row);
    for (s = sStart, d = dStart, a = aStart; s != sFinish; ++s, ++d, ++a) {
      *d   = *s;
      d->m = s->m + (1.0 - s->m / maxVal) * *a;
    }
  }
}
}  // namespace
//********************************************************
//    EroDilate  algorithms
//********************************************************
namespace {
template <typename Chan>
struct MaxFunc {
  inline Chan operator()(const Chan &first, const Chan &second) {
    return std::max(first, second);
  }
};
template <typename Chan>
struct MinFunc {
  inline Chan operator()(const Chan &first, const Chan &second) {
    return std::min(first, second);
  }
};
//--------------------------------------------------------------
// NOTE: source and destination must be NOT OVERLAPPING (eg source != destination)
template <typename Chan, typename Func>
void erodilate_row(int length, const Chan *source, int sStride, Chan *destination, int dStride,
                   int radius, double radiusRemainder, Func func) {
  assert(radius >= 0);
  // Segment the row of specified length into wCount windows of max wSize
  // elements
  int window, wSize = 2 * radius + 1, wCount = length / wSize + 1;
  int swStride = wSize * sStride, srOffset = radius * sStride;
  int dwStride = wSize * dStride, drOffset = radius * dStride;
  const Chan *s, *sEnd = source + length * sStride;
  Chan *d, *dEnd       = destination + length * dStride;
  double one_radiusRemainder = (1.0 - radiusRemainder);
  for (window = 0; window != wCount; ++window) {
    Chan *dwStart = destination + window * dwStride, *dwFinish = std::min(dwStart + dwStride, dEnd);
    // Compute prefixes
    const Chan *swStart = source + std::max(window * swStride - srOffset - sStride, 0),
               *swFinish =
                   source + std::min(window * swStride + srOffset + sStride, length * sStride);
    s = swFinish - sStride, d = destination + ((s - source) / sStride) * dStride +
                           drOffset;  // d already decremented by dStride
    Chan val = *s, oldValue;
    for (s -= sStride; (d >= dEnd) && (s >= swStart);
         s -= sStride, d -= dStride)  // s decremented here
    {
      assert(s >= source);
      assert(s < sEnd);
      assert((s - source) % sStride == 0);
      assert(d >= destination);
      assert((d - destination) % dStride == 0);
      val = func(oldValue = val, *s);
    }
    for (; s >= swStart; s -= sStride, d -= dStride) {
      assert(s >= source);
      assert(s < sEnd);
      assert((s - source) % sStride == 0);
      assert(d >= destination);
      assert(d < dEnd);
      assert((d - destination) % dStride == 0);
      val = func(oldValue = val, *s);
      *d = (oldValue == val) ? val : one_radiusRemainder * oldValue + radiusRemainder * val;
    }
    for (d = std::min(d, dEnd - dStride); d >= dwStart; d -= dStride) {
      assert(d >= destination);
      assert(d < dEnd);
      assert((d - destination) % dStride == 0);
      val = func(oldValue = val, 0);
      *d = (oldValue == val) ? val : one_radiusRemainder * oldValue + radiusRemainder * val;
    }
    // Compute suffixes
    swStart = source + window * swStride + srOffset,
    swFinish   = std::min(swStart + swStride + sStride, sEnd);
    if (swStart >= swFinish) continue;
    s = swStart, d = dwStart;
    val = *s;
    for (s += sStride; (s < swFinish); s += sStride, d += dStride) {
      assert(s >= source);
      assert(s < sEnd);
      assert((s - source) % sStride == 0);
      assert(d >= destination);
      assert(d < dEnd);
      assert((d - destination) % dStride == 0);
      val = func(oldValue = val, *s);
      *d = func(*d, (oldValue == val) ? val : one_radiusRemainder * oldValue + radiusRemainder * val);
    }
    for (; d < dwFinish; d += dStride) {
      assert(d >= destination);
      assert(d < dEnd);
      assert((d - destination) % dStride == 0);
      val = func(oldValue = val, 0);
      *d = func(*d, (oldValue == val) ? val : one_radiusRemainder * oldValue + radiusRemainder * val);
    }
  }
}
//--------------------------------------------------------------
template <typename Pix, typename Chan>
void erodilate_chan(const TRasterPT<Pix> &source, const TRasterPT<Chan> &destination,
                    double radius, bool dilate) {
  assert(radius > 0.0);
  int radiusInt    = tfloor(radius);
  double radiusRemainder = radius - radiusInt;
  // Using a temporary raster to keep intermediate results. This allows us to
  // perform a cache-friendly iteration in the separable/square kernel case
  int col, row, width = source->getLx(), height = source->getLy();
  // Perform rows erodilation
  TRasterPT<Chan> temp(height, width);  // Notice transposition plz
  {
    if (dilate)
      for (row = 0; row != height; ++row)
        ::erodilate_row(width, &source->pixels(row)->m, 4, temp->pixels(0) + row, height,
                        radiusInt, radiusRemainder, MaxFunc<Chan>());
    else
      for (row = 0; row != height; ++row)
        ::erodilate_row(width, &source->pixels(row)->m, 4, temp->pixels(0) + row, height,
                        radiusInt, radiusRemainder, MinFunc<Chan>());
  }
  // Perform columns erodilation
  {
    if (dilate)
      for (col = 0; col != width; ++col)
        ::erodilate_row(height, temp->pixels(col), 1, destination->pixels(0) + col,
                        destination->getWrap(), radiusInt, radiusRemainder, MaxFunc<Chan>());
    else
      for (col = 0; col != width; ++col)
        ::erodilate_row(height, temp->pixels(col), 1, destination->pixels(0) + col,
                        destination->getWrap(), radiusInt, radiusRemainder, MinFunc<Chan>());
  }
}
//--------------------------------------------------------------
template <typename Pix>
void rect_erodilate(const TRasterPT<Pix> &source, const TRasterPT<Pix> &destination,
                    double radius) {
  typedef typename Pix::Channel Chan;
  if (radius == 0.0) {
    // No-op case
    TRop::copy(destination, source);
    return;
  }
  bool dilate = (radius >= 0.0);
  // Perform columns erodilation
  TRasterPT<Chan> temp(source->getLx(), source->getLy());
  ::erodilate_chan(source, temp, fabs(radius), dilate);
  // Remember that we have just calculated the alpha values. We still have to
  // apply them to the old RGB
  // values, which requires depremultiplying from source alpha and
  // premultiplying with the new one.
  if (dilate)
    ::copyChannels_dilate(source, temp, destination);
  else
    ::copyChannels_erode(source, temp, destination);
}
