//********************************************************
//    EroDilate  round algorithm
//********************************************************
namespace {
template <typename Chan, typename Func>
void erodilate_quarters(int width, int height, Chan *source, int sStrideX, int sStrideY,
                        Chan *destination, int dStrideX, int dStrideY, double radius,
                        double offset, Func func) {
  double sqRadius     = sq(radius);
  double squareHeight = radius * M_SQRT1_2;
  int squareHeightI   = tfloor(squareHeight);
  // For every arc point
  int arcY;
  for (arcY = -squareHeightI; arcY <= squareHeightI; ++arcY) {
    // Calculate x and weights
    double sqArcY = sq(arcY);
    assert(sqRadius >= sqArcY);
    double x = offset + sqrt(sqRadius - sqArcY) - squareHeight;
    int arcX = tfloor(x);
    double weight = x - arcX, one_weight = 1.0 - weight;
    // Build destination area influenced by the arc point. Func with 0 outside that.
    TRect bounds(0, 0, width, height);
    TRect dRect(bounds * (bounds + TPoint(-arcX, -arcY)));
    TRect sRect(bounds * (bounds + TPoint(arcX, arcY)));
    int sy, dy;
    // Func with 0 before dRect.y0
    for (dy = 0; dy < dRect.y0; ++dy) {
      Chan *d, *dStart = destination + dy * dStrideY, *dFinish = dStart + width * dStrideX;
      for (d = dStart; d != dFinish; d += dStrideX) {
        // assert(d >= destination); assert(d < dFinish); assert((d-destination) % dStrideX == 0);
        *d = func(*d, 0);
      }
    }
    // Func with 0 after dRect.y1
    for (dy = dRect.y1; dy < height; ++dy) {
      Chan *d, *dStart = destination + dy * dStrideY, *dFinish = dStart + width * dStrideX;
      for (d = dStart; d != dFinish; d += dStrideX) {
        // assert(d >= destination); assert(d < dFinish); assert((d-destination) % dStrideX == 0);
        *d = func(*d, 0);
      }
    }
    // For every destination pixel in the area, Func with the corresponding pixel in source
    for (dy = dRect.y0, sy = sRect.y0; dy != dRect.y1; ++dy, ++sy) {
      Chan *d, *dLine = destination + dy * dStrideY, *dStart = dLine + dRect.x0 * dStrideX;
      Chan *s, *sLine = source + sy * sStrideY, *sStart = sLine + sRect.x0 * sStrideX,
               *sFinish = sLine + sRect.x1 * sStrideX;
      Chan *sLast = sFinish - sStrideX;  // sLast would lerp with sFinish
      for (d = dStart, s = sStart; s != sLast;
           d += dStrideX, s += sStrideX)  // hence we stop before it
      {
        // assert(s >= source); assert(s < sFinish); assert((s-source) % sStrideX == 0);
        // assert(d >= destination); assert(d < dFinish); assert((d-destination) % dStrideX == 0);
        *d = func(*d, *s * one_weight + *(s + sStrideX) * weight);
      }
      // assert(s >= source); assert(s < sFinish); assert((s-source) % sStrideX == 0);
      // assert(d >= destination); assert(d < dFinish); assert((d-destination) % dStrideX == 0);
      *d = func(*d, *s * one_weight);  // lerp sLast with 0
    }
  }
}
//--------------------------------------------------------------
template <typename Pix>
void circular_erodilate(const TRasterPT<Pix> &source, const TRasterPT<Pix> &destination,
                        double radius) {
  typedef typename Pix::Channel Chan;
  if (radius == 0.0) {
    // No-op case
    TRop::copy(destination, source);
    return;
  }
  // Ok, the idea is: consider the maximal embedded square in our circular
  // structuring element.
  // Erodilating by it consists in the consecutive erodilation by rows and
  // columns with the same
  // 'square' radius. Now, it's easy to see that the square could be 'bent' so
  // that one of its
  // edges matches that of a 1/4 of the circle's edge, while remaining inside
  // the circle.
  // Erodilating by the bent square can be achieved by erodilating first by rows
  // or column for
  // the square edge radius, followed by perpendicular erodilationg with a
  // fourth of our
  // circumference. Sum the 4 erodilations needed to complete the circumference
  // - and it's done.
  // NOTE: Unfortunately, the above decomposition has lots of intersections
  // among the pieces - yet
  // it's simple enough and removes an O(radius) from the naive algorithm. Could
  // be done better?
  // First, build the various erodilation data
  bool dilate = (radius >= 0.0);
  radius      = fabs(radius);
  double inner_square_diameter = radius * M_SQRT2;
  double offset =
      0.25 *
      inner_square_diameter;  // Offset of the bent square SE needed to avoid
                              // touching the circumference on the other side
  double row_filter_radius = 0.5 * (inner_square_diameter - offset);
  double cseOffset = 0.5 * offset;  // circumference structuring element offset
  int width = source->getLx(), height = source->getLy();
  TRasterPT<Chan> temp1(width, height), temp2(width, height);
  int radiusInt    = tfloor(row_filter_radius);
  double radiusRemainder = row_filter_radius - radiusInt;
  if (dilate) {
    temp2->fill(0);  // Initialize with a Func-neutral value
    if (row_filter_radius > 0.0)
      for (int row = 0; row != height; ++row)
        ::erodilate_row(width, &source->pixels(row)->m, 4, temp1->pixels(row), 1, radiusInt,
                        radiusRemainder, MaxFunc<Chan>());
    else
      ::copyMatte(source, temp1);
    ::erodilate_quarters(width, height, temp1->pixels(0), 1, width, temp2->pixels(0), 1,
                         width, radius, cseOffset, MaxFunc<Chan>());
    ::erodilate_quarters(width, height, temp1->pixels(0) + width - 1, -1, width,
                         temp2->pixels(0) + width - 1, -1, width, radius, cseOffset,
                         MaxFunc<Chan>());
    if (row_filter_radius > 0.0)
      for (int col = 0; col != width; ++col)
        ::erodilate_row(height, &source->pixels(0)[col].m, 4 * source->getWrap(),
                        temp1->pixels(0) + col, width, radiusInt, radiusRemainder, MaxFunc<Chan>());
    else
      ::copyMatte(source, temp1);
    ::erodilate_quarters(height, width, temp1->pixels(0), width, 1, temp2->pixels(0), width,
                         1, radius, cseOffset, MaxFunc<Chan>());
    ::erodilate_quarters(height, width, temp1->pixels(0) + width * height - 1, -width, -1,
                         temp2->pixels(0) + width * height - 1, -width, -1, radius,
                         cseOffset, MaxFunc<Chan>());
  } else {
    temp2->fill((std::numeric_limits<Chan>::max)());  // Initialize with a
                                                      // Func-neutral value
    if (row_filter_radius > 0.0)
      for (int row = 0; row != height; ++row)
        ::erodilate_row(width, &source->pixels(row)->m, 4, temp1->pixels(row), 1, radiusInt,
                        radiusRemainder, MinFunc<Chan>());
    else
      ::copyMatte(source, temp1);
    ::erodilate_quarters(width, height, temp1->pixels(0), 1, width, temp2->pixels(0), 1,
                         width, radius, cseOffset, MinFunc<Chan>());
    ::erodilate_quarters(width, height, temp1->pixels(0) + width - 1, -1, width,
                         temp2->pixels(0) + width - 1, -1, width, radius, cseOffset,
                         MinFunc<Chan>());
    if (row_filter_radius > 0.0)
      for (int col = 0; col != width; ++col)
        ::erodilate_row(height, &source->pixels(0)[col].m, 4 * source->getWrap(),
                        temp1->pixels(0) + col, width, radiusInt, radiusRemainder, MinFunc<Chan>());
    else
      ::copyMatte(source, temp1);
    ::erodilate_quarters(height, width, temp1->pixels(0), width, 1, temp2->pixels(0), width,
                         1, radius, cseOffset, MinFunc<Chan>());
    ::erodilate_quarters(height, width, temp1->pixels(0) + width * height - 1, -width, -1,
                         temp2->pixels(0) + width * height - 1, -width, -1, radius,
                         cseOffset, MinFunc<Chan>());
  }
  // Remember that we have just calculated the alpha values. We still have to
  // apply them to the old RGB
  // values, which requires depremultiplying from source alpha and
  // premultiplying with the new one.
  if (dilate)
    ::copyChannels_dilate(source, temp2, destination);
  else
    ::copyChannels_erode(source, temp2, destination);
}
}  // namespace
//********************************************************
//    EroDilate  main functions
//********************************************************
void TRop::erodilate(const TRasterP &source, const TRasterP &destination, double radius,
                     ErodilateMaskType type) {
  assert(source->getSize() == destination->getSize());
  source->lock(), destination->lock();
  if ((TRaster32P)source && (TRaster32P)destination) switch (type) {
    case ED_rectangular:
      ::rect_erodilate<TPixel32>(source, destination, radius);
      break;
    case ED_circular:
      ::circular_erodilate<TPixel32>(source, destination, radius);
      break;
    default:
      assert(!"Unknown mask type");
      break;
    }
  else if ((TRaster64P)source && (TRaster64P)destination)
    switch (type) {
    case ED_rectangular:
      ::rect_erodilate<TPixel64>(source, destination, radius);
      break;
    case ED_circular:
      ::circular_erodilate<TPixel64>(source, destination, radius);
      break;
    default:
      assert(!"Unknown mask type");
      break;
    }
  else
    assert(!"Unsupported raster type!");
  source->unlock(), destination->unlock();
}

