///
/// Extensions
///
const Extension::Type RequiredCapabilitiesExtension::type =
  ExtensionType::required_capabilities;
const Extension::Type ApplicationIDExtension::type =
  ExtensionType::application_id;

// Default list of supported extension types
const std::array<uint16_t, 5> standard_extensions = {
  ExtensionType::application_id,        ExtensionType::ratchet_tree,
  ExtensionType::required_capabilities, ExtensionType::external_pub,
  ExtensionType::external_senders,
};

// Default list of supported proposal types
const std::array<uint16_t, 8> standard_proposals = {
  ProposalType::add,
  ProposalType::update,
  ProposalType::remove,
  ProposalType::psk,
  ProposalType::reinit,
  ProposalType::external_init,
  ProposalType::group_context_extensions,
};

// Supported protocol versions (currently only MLS 1.0)
const std::array<ProtocolVersion, 1> supported_versions_list = {
  ProtocolVersion::mls10
};

// Supported cipher suites
const std::array<CipherSuite::ID, 6> supported_ciphersuites_list = {
  CipherSuite::ID::X25519_AES128GCM_SHA256_Ed25519,
  CipherSuite::ID::P256_AES128GCM_SHA256_P256,
  CipherSuite::ID::X25519_CHACHA20POLY1305_SHA256_Ed25519,
  CipherSuite::ID::X448_AES256GCM_SHA512_Ed448,
  CipherSuite::ID::P521_AES256GCM_SHA512_P521,
  CipherSuite::ID::X448_CHACHA20POLY1305_SHA512_Ed448,
};

// Supported credential types
const std::array<CredentialType, 4> supported_credentials_list = {
  CredentialType::basic,
  CredentialType::x509,
  CredentialType::userinfo_vc_draft_00,
  CredentialType::multi_draft_00
};

Capabilities
Capabilities::create_default()
{
  return {
    { supported_versions_list.begin(), supported_versions_list.end() },
    { supported_ciphersuites_list.begin(), supported_ciphersuites_list.end() },
    { /* No non-default extensions */ },
    { /* No non-default proposals */ },
    { supported_credentials_list.begin(), supported_credentials_list.end() },
  };
}

bool
Capabilities::extensions_supported(
  const std::vector<Extension::Type>& needed) const
{
  return stdx::all_of(needed, [&](Extension::Type type) {
    if (stdx::contains(standard_extensions, type)) {
      return true;
    }
    return stdx::contains(extensions, type);
  });
}

bool
Capabilities::proposals_supported(
  const std::vector<Proposal::Type>& needed) const
{
  return stdx::all_of(needed, [&](Proposal::Type type) {
    if (stdx::contains(standard_proposals, type)) {
      return true;
    }
    return stdx::contains(proposals, type);
  });
}

bool
Capabilities::credential_supported(const Credential& cred_obj) const
{
  return stdx::contains(supported_credentials_list, cred_obj.type());
}

Lifetime
Lifetime::create_default()
{
  return Lifetime{ 0x0000000000000000ULL, 0xffffffffffffffffULL };
}

void
ExtensionList::add(uint16_t ext_type, bytes ext_data)
{
  auto existing = stdx::find_if(
    extensions, [&](const Extension& ext) -> bool { return ext.type == ext_type; });
  if (existing != extensions.end()) {
    existing->data = std::move(ext_data);
    return;
  }
  extensions.push_back({ ext_type, std::move(ext_data) });
}

bool
ExtensionList::has(uint16_t ext_type) const
{
  return stdx::any_of(extensions,
                      [&](const Extension& ext) { return ext.type == ext_type; });
}

///
/// LeafNode
///
LeafNode::LeafNode(CipherSuite suite,
                   HPKEPublicKey enc_key_in,
                   SignaturePublicKey sig_key_in,
                   Credential cred_in,
                   Capabilities caps_in,
                   Lifetime life_in,
                   ExtensionList ext_list_in,
                   const SignaturePrivateKey& priv_sig)
  : encryption_key(std::move(enc_key_in))
  , signature_key(std::move(sig_key_in))
  , credential(std::move(cred_in))
  , capabilities(std::move(caps_in))
  , content(life_in)
  , extensions(std::move(ext_list_in))
{
  grease(extensions);
  grease(capabilities, extensions);
  sign(suite, priv_sig, std::nullopt);
}

void
LeafNode::set_capabilities(Capabilities caps_in)
{
  capabilities = std::move(caps_in);
  grease(capabilities, extensions);
}

LeafNode
LeafNode::for_update(CipherSuite suite,
                     const bytes& gid,
                     LeafIndex idx,
                     HPKEPublicKey enc_key_in,
                     const LeafNodeOptions& opts,
                     const SignaturePrivateKey& priv_sig) const
{
  auto copy = clone_with_options(std::move(enc_key_in), opts);
  copy.content = Empty{};
  copy.sign(suite, priv_sig, { { gid, idx } });
  return copy;
}

LeafNode
LeafNode::for_commit(CipherSuite suite,
                     const bytes& gid,
                     LeafIndex idx,
                     HPKEPublicKey enc_key_in,
                     const bytes& phash,
                     const LeafNodeOptions& opts,
                     const SignaturePrivateKey& priv_sig) const
{
  auto copy = clone_with_options(std::move(enc_key_in), opts);
  copy.content = ParentHash{ phash };
  copy.sign(suite, priv_sig, { { gid, idx } });
  return copy;
}

LeafNodeSource
LeafNode::source() const
{
  return tls::variant<LeafNodeSource>::type(content);
}

void
LeafNode::sign(CipherSuite suite,
               const SignaturePrivateKey& priv_sig,
               const std::optional<MemberBinding>& binding)
{
  const auto tbs = to_be_signed(binding);
  if (priv_sig.public_key != signature_key) {
    throw InvalidParameterError("Signature key mismatch");
  }
  if (!credential.valid_for(signature_key)) {
    throw InvalidParameterError("Credential not valid for signature key");
  }
  signature = priv_sig.sign(suite, sign_label::leaf_node, tbs);
}

bool
LeafNode::verify(CipherSuite suite,
                 const std::optional<MemberBinding>& binding) const
{
  const auto tbs = to_be_signed(binding);
  if (CredentialType::x509 == credential.type()) {
    const auto& cred = credential.get<X509Credential>();
    if (cred.signature_scheme() !=
        tls_signature_scheme(suite.sig().id)) {
      throw std::runtime_error("Signature algorithm invalid");
    }
  }
  return signature_key.verify(
    suite, sign_label::leaf_node, tbs, signature);
}

bool
LeafNode::verify_expiry(uint64_t current_time) const
{
  const auto check_validity = overloaded{
    [current_time](const Lifetime& lt) {
      return lt.not_before <= current_time && current_time <= lt.not_after;
    },
    [](const auto& /* other */) { return false; },
  };
  return var::visit(check_validity, content);
}

bool
LeafNode::verify_extension_support(const ExtensionList& ext_list) const
{
  // Verify that extensions in the list are supported
  auto ext_types = stdx::transform<Extension::Type>(
    ext_list.extensions, [](const auto& ext) { return ext.type; });
  if (!capabilities.extensions_supported(ext_types)) {
    return false;
  }

  // If there's a RequiredCapabilities extension, verify support
  const auto maybe_req_capas = ext_list.find<RequiredCapabilitiesExtension>();
  if (!maybe_req_capas) {
    return true;
  }

  const auto& req_capas = opt::get(maybe_req_capas);
  return capabilities.extensions_supported(req_capas.extensions) &&
         capabilities.proposals_supported(req_capas.proposals);
}

LeafNode
LeafNode::clone_with_options(HPKEPublicKey enc_key_in,
                             const LeafNodeOptions& opts) const
{
  auto copy = *this;
  copy.encryption_key = std::move(enc_key_in);
  if (opts.credential) {
    copy.credential = opt::get(opts.credential);
  }
  if (opts.capabilities) {
    copy.capabilities = opt::get(opts.capabilities);
  }
  if (opts.extensions) {
    copy.extensions = opt::get(opts.extensions);
  }
  return copy;
}

