const char *BinStream::Name() const { return "<unnamed>"; }

BinStream::BinStream(bool little) : mLittleEndian(little), mCrypto(nullptr), mRevStack(nullptr) {}

void SwapBytes(const void *src, void *dst, int sz) {
    switch (sz) {
    case 2: {
        unsigned short *s1 = (unsigned short *)src;
        unsigned short *s2 = (unsigned short *)dst;
        *s2 = EndianSwap(*s1);
        break;
    }
    case 4: {
        unsigned int *i1 = (unsigned int *)src;
        unsigned int *i2 = (unsigned int *)dst;
        *i2 = EndianSwap(*i1);
        break;
    }
    case 8: {
        unsigned long long *l1 = (unsigned long long *)src;
        unsigned long long *l2 = (unsigned long long *)dst;
        *l2 = EndianSwap(*l1);
        break;
    }
    default:
        MILO_ASSERT(0, 0xAC);
        break;
    }
}

void BinStream::DisableEncryption() {
    MILO_ASSERT(mCrypto, 0xDC);
    RELEASE(mCrypto);
}

void BinStream::Write(const void *raw_data, int num_bytes) {
    if (Fail()) {
        MILO_PRINT_ONCE("Stream error: Can't write to %s\n", Name());
    } else {
        const unsigned char *data = (u8 *)raw_data;
        if (!mCrypto) {
            WriteImpl(raw_data, num_bytes);
        } else {
            char buffer[512];
            int remaining = num_bytes;
            while (remaining > 0) {
                int chunk = Min(512, remaining);
                for (int idx = 0; idx < chunk; ++idx) {
                    u8 mask = mCrypto->Int();
                    buffer[idx] = data[idx] ^ mask;
                }
                WriteImpl(buffer, chunk);
                remaining -= chunk;
                data += chunk;
            }
        }
    }
}

void BinStream::Seek(int offset, SeekType mode) {
    MILO_ASSERT(!Fail(), 0x11F);
    MILO_ASSERT(!mCrypto, 0x122);
    SeekImpl(offset, mode);
}

void BinStream::WriteEndian(const void *input, int size) {
    if (mLittleEndian) {
        u64 temp[2]; // 128-bit temporary storage
        SwapBytes(input, temp, size);
        Write(temp, size);
    } else {
        Write(input, size);
    }
}

bool BinStream::AddSharedInlined(const class FilePath &) {
    MILO_FAIL("BinStream::AddSharedInlined is a PC dev tool only !!");
    return false;
}

BinStream &BinStream::operator<<(const char *text) {
    MILO_ASSERT(text, 0x60);
    int len = strlen(text);
    *this << len;
    Write(text, len);
    return *this;
}

BinStream &BinStream::operator<<(const Symbol &symbol) {
    const char *str = symbol.Str();
    unsigned int length = strlen(str);
    MILO_ASSERT(length < BUFFER_CAPACITY, 0x6C);
    *this << length;
    Write(str, length);
    return *this;
}

BinStream &BinStream::operator<<(const class String &text) {
    int len = text.length();
    *this << len;
    Write(text.c_str(), len);
    return *this;
}

void BinStream::EnableWriteEncryption() {
    MILO_ASSERT(!mCrypto, 0xC8);
    int seed = RandomInt();
    *this << seed;
    mCrypto = new Rand2(seed);
}

int BinStream::PopRev(Hmx::Object *obj) {
    MILO_ASSERT(mRevStack, 0x34);
    ObjVersion *top = &mRevStack->back();
    while (top->obj == nullptr) {
        MILO_NOTIFY("hey object got deleted!");
        mRevStack->pop_back();
        top = &mRevStack->back();
    }
    int revs = top->revs;
    if (obj != top->obj) {
        MILO_LOG("rev stack $this mismatch (%08x != %08x\n", obj, top->obj);
        MILO_LOG("curr obj: %s %s\n", obj->ClassName(), PathName(obj));
        MILO_LOG("stack obj: %s %s\n", top->obj->ClassName(), PathName(top->obj));
        MILO_FAIL(
            "rev stack (%08x %s %s != %08x %s %s)\n",
            obj,
            obj->ClassName(),
            PathName(obj),
            top->obj,
            top->obj->ClassName(),
            PathName(top->obj)
        );
    }
    mRevStack->pop_back();
    return revs;
}

void BinStream::Read(void *buffer, int count) {
    if (Fail()) {
        MILO_NOTIFY_ONCE("Stream error: Can't read from %s", Name());
        memset(buffer, 0, count);
    } else {
        AutoGlitchReport report(50.0f, __FUNCTION__);
        ReadImpl(buffer, count);
        if (mCrypto) {
            unsigned char *ptr = (unsigned char *)buffer;
            unsigned char *end = ptr + count;
            for (; ptr < end; ++ptr) {
                unsigned char keyByte = mCrypto->Int();
                *ptr ^= keyByte;
            }
        }
    }
}

int BinStream::ReadAsync(void *dest, int bytes) {
    Read(dest, bytes);
    return Fail() ? 0 : bytes;
}

void BinStream::ReadEndian(void *out, int size) {
    Read(out, size);
    if (mLittleEndian) {
        SwapBytes(out, out, size);
    }
}

void BinStream::ReadString(char *buf, int capacity) {
    unsigned int len;
    *this >> len;
    if (len >= capacity)
        MILO_FAIL("String chars %d > %d", len + 1, capacity);
    Read(buf, len);
    buf[len] = '\0';
}

BinStream &BinStream::operator>>(Symbol &symbol) {
    char temp[BUFFER_CAPACITY];
    ReadString(temp, BUFFER_CAPACITY);
    symbol = temp;
    return *this;
}

BinStream &BinStream::operator>>(String &text) {
    int size;
    *this >> size;
    text.resize(size);
    Read((void *)text.c_str(), size);
    return *this;
}

void BinStream::EnableReadEncryption() {
    MILO_ASSERT(!mCrypto, 0xC0);
    int seed;
    *this >> seed;
    mCrypto = new Rand2(seed);
}

BinStream::~BinStream() {
    delete mCrypto;
    delete mRevStack;
}

void BinStream::PushRev(int revs, Hmx::Object *obj) {
    if (!mRevStack) {
        mRevStack = new std::vector<ObjVersion>();
    }
    mRevStack->push_back(ObjVersion(revs, obj));
}

#include "MeshGL.h"
