void TTWAIN_LogLastError(void) {
  char TempBuffer[1024];
  TTwainData.LastResultCode = TTWAIN_GetResultCode();

  if ((TTwainData.LastResultCode == TWRC_FAILURE) ||
      (TTwainData.LastResultCode == TWRC_CHECKSTATUS))
    TTwainData.LastConditionCode = TTWAIN_GetConditionCode();
  else
    TTwainData.LastConditionCode = -1;

  if (TTwainData.LastResultCode < (sizeof(ResultCodeText) / sizeof(ResultCodeText[0]))) {
    snprintf(ErrorBuffer, sizeof(ErrorBuffer), "Result: %s(%d)",
             ResultCodeText[TTwainData.LastResultCode], (int)TTwainData.LastResultCode);
  } else {
    snprintf(ErrorBuffer, sizeof(ErrorBuffer), "Result: %s(%d)", "unknown",
             (int)TTwainData.LastResultCode);
  }

  if (TTwainData.LastConditionCode < (sizeof(ConditionCodeText) / sizeof(ConditionCodeText[0]))) {
    snprintf(TempBuffer, sizeof(TempBuffer), " Condition: %s(%d)", 
             ConditionCodeText[TTwainData.LastConditionCode],
             (int)TTwainData.LastConditionCode);
    strcat(ErrorBuffer, TempBuffer);
  } else {
    snprintf(TempBuffer, sizeof(TempBuffer), " Condition: %s(%d)", "unknown",
             (int)TTwainData.LastConditionCode);
    strcat(ErrorBuffer, TempBuffer);
  }

  if (TTwainData.LastResultCode == TWRC_FAILURE &&
      TTwainData.LastConditionCode == TWCC_OPERATIONERROR) {
#ifdef _WIN32
    OutputDebugString(ErrorBuffer);
#else
#ifdef TOONZDEBUG
    printf("%s\n", ErrorBuffer);
#endif
#endif
  }
}
/*---------------------------------------------------------------------------*/
char *TTWAIN_GetErrorDetails(TUINT32 *out_rc, TUINT32 *out_cc) {
  assert(out_rc && out_cc);
  *out_rc = TTwainData.LastResultCode;
  *out_cc = TTwainData.LastConditionCode;
  return ErrorBuffer;
}
