using namespace db;

void CommitHistoryRebaser::rebase(const MetadataRebaser& metadataRebaser,
                                  DataPartRebaser& dataPartRebaser,
                                  const CommitHistory& originalHistory) {
    // Clear the journal: WriteSets may change on reflush after rebase
    _history.journal().clear();

    // Dataparts
    auto updatedDataparts = originalHistory._allDataparts;
    const size_t newCommitPartsCount = _history._commitDataparts.size();
    updatedDataparts.resize(updatedDataparts.size() + newCommitPartsCount);

    std::copy(_history._commitDataparts.begin(),
              _history._commitDataparts.end(),
              updatedDataparts.begin() + originalHistory._allDataparts.size());

    _history._allDataparts = std::move(updatedDataparts);

    _history._commitDataparts = {
        _history._allDataparts.data() + _history._allDataparts.size() - newCommitPartsCount,
        newCommitPartsCount,
    };

    const auto& priorDataParts = originalHistory._allDataparts;
    if (priorDataParts.empty()) {
        return;
    }

    const auto* lastPart = priorDataParts.back().get();
    for (auto& part : _history._commitDataparts) {
        dataPartRebaser.rebase(metadataRebaser, *lastPart, *part);
        lastPart = part.get();
    }
}

void CommitHistoryRebaser::removeCreatedDataParts() {
    // Total number of dataparts in the view of this commit
    const size_t totalDPs = _history._allDataparts.size();
    // Total number of dataparts which were created as part of this commit, as a result
    // of Change::commit (1 commit = 1 datapart).
    const size_t newlyCommittedDPs = _history._commitDataparts.size();

    // Just delete the most recent newlyCommittedDPs number of DPs
    resizeDataParts(totalDPs - newlyCommittedDPs);

    // Reset this commit to have no locally created DPs
    resetCommitDataParts();
}

void CommitHistoryRebaser::resizeDataParts(size_t targetSize) {
    _history._allDataparts.resize(targetSize);
}

void CommitHistoryRebaser::resetCommitDataParts() {
    // Set _commitDataparts to be an empty span, but from the same address
    _history._commitDataparts = {_history._commitDataparts.data(), 0};
}

