        }

        TVectorChild children[] = {xrange(0, 9),
                                   xrange(0, 9, 1)};
        for (const auto& arr : children) {
            UNIT_ASSERT(arr == baseData);
        }
    }

    template <class XRangeContainer>
    void TestEmptyRanges(const XRangeContainer& container) {
        for (const auto& emptyRange : container) {
            UNIT_ASSERT_VALUES_EQUAL(emptyRange.size(), 0);
            for (auto item : emptyRange) {
                Y_UNUSED(item);
