#include <pangolin/plot/loaders/csv_table_loader.h>
#include <fstream>
#include <memory>

namespace pangolin {

CsvTableLoader::CsvTableLoader(const std::vector<std::string>& file_paths, char delimiter, char comment_char)
    : delim(delimiter), comment(comment_char)
{
    for(const auto& path : file_paths) {
        if(path == "-") {
            streams.push_back(&std::cin);
        } else {
            std::ifstream* pFile = new std::ifstream(path);
            owned_streams.emplace_back(pFile);
            streams.push_back(pFile);
            PANGO_ASSERT(pFile->is_open());
        }
    }
}

bool CsvTableLoader::SkipLines(const std::vector<size_t>& skip_counts)
{
    if(!skip_counts.empty()) {
        PANGO_ASSERT(skip_counts.size() == streams.size());
        std::vector<std::string> dummy_row;
        for(size_t i = 0; i < streams.size(); ++i) {
            for(size_t r = 0; r < skip_counts[i]; ++r) {
                if(!AppendColumns(dummy_row, *streams[i], delim, '\0')) {
                    return false;
                }
            }
        }
    }
    return true;
}

bool CsvTableLoader::ReadRow(std::vector<std::string>& row)
{
    row.clear();
    for(auto& stream : streams) {
        if(!AppendColumns(row, *stream, delim, comment)) {
            return false;
        }
    }
    return true;
}

bool CsvTableLoader::AppendColumns(std::vector<std::string>& cols, std::istream& input_stream, char delimiter, char comment_marker)
{
    // Read line from stream, skipping comment lines
    std::string line;
    do {
        std::getline(input_stream, line);
    } while(!line.empty() && line[0] == comment_marker);

    // Return false if no more data available
    if(!input_stream.good()) return false;

    std::stringstream line_stream(line);
    std::string field;

    // Extract fields separated by delimiter
    while(std::getline(line_stream, field, delimiter)) {
        cols.push_back(field);
    }

    // Handle trailing empty field (e.g., "a,b,")
    if (!line_stream && field.empty()) {
        cols.push_back("");
    }

    return true;
}

