// Test CodeMemPool allocation behavior and boundary conditions
TEST(Mempool, CodeMemPool) {
  CodeMemPool Pool;
  auto *InitialStart = Pool.getMemStart();

  EXPECT_EQ(Pool.getMemStart(), InitialStart);
  EXPECT_EQ(Pool.getMemEnd(), InitialStart);
  EXPECT_EQ(Pool.getMemPageEnd(), InitialStart);

  void *FirstAlloc = Pool.allocate(10);
  EXPECT_EQ(Pool.getMemStart(), InitialStart);
  EXPECT_EQ(Pool.getMemEnd(), InitialStart + 10);
  EXPECT_EQ(FirstAlloc, InitialStart);
  EXPECT_EQ(Pool.getMemPageEnd(), InitialStart + 4096);

  void *SecondAlloc = Pool.allocate(10);
  EXPECT_EQ(Pool.getMemStart(), InitialStart);
  EXPECT_EQ(Pool.getMemEnd(), InitialStart + 26);
  EXPECT_EQ(SecondAlloc, InitialStart + 16);
  EXPECT_EQ(Pool.getMemPageEnd(), InitialStart + 4096);

  void *ThirdAlloc = Pool.allocate(4096);
  EXPECT_EQ(Pool.getMemStart(), InitialStart);
  EXPECT_EQ(Pool.getMemEnd(), InitialStart + 32 + 4096);
  EXPECT_EQ(ThirdAlloc, InitialStart + 32);
  EXPECT_EQ(Pool.getMemPageEnd(), InitialStart + 4096 * 2);

  EXPECT_DEATH(Pool.allocate(CodeMemPool::MaxCodeSize), "");
}

