#include "simulation.h"
#include <algorithm>
#include <thread>
#include <limits>

namespace unravel
{
using namespace std::chrono_literals;

simulation::simulation()
{
    if (max_inactive_fps_ == 0)
    {
        max_inactive_fps_ = std::max(max_inactive_fps_, max_fps_);
    }
}

void simulation::run_one_frame(bool is_active)
{
    // Determine effective FPS limit based on activity state
    auto current_max_fps = max_fps_;
    if (!is_active && current_max_fps > 0)
    {
        current_max_fps = std::min(max_inactive_fps_, current_max_fps);
    }

    // Calculate elapsed time since last frame
    duration_t time_passed = clock_t::now() - last_frame_timepoint_;

    // Apply frame rate limiting if enabled
    if (current_max_fps > 0)
    {
        duration_t desired_interval = 1000ms / current_max_fps;
        for (;;)
        {
            time_passed = clock_t::now() - last_frame_timepoint_;
            if (time_passed >= desired_interval)
            {
                break;
            }
            if (time_passed < duration_t(0))
            {
                break;
            }

            duration_t wait_duration = desired_interval - time_passed;
            auto wait_ms = std::chrono::duration_cast<std::chrono::milliseconds>(wait_duration);

            if (wait_duration > std::chrono::microseconds(1000))
            {
                if (wait_ms.count() > 0)
                {
                    wait_duration /= wait_ms.count();
                }
                std::this_thread::sleep_for(wait_duration);
            }
        }
    }

    // Ensure elapsed time is non-negative
    if (time_passed < duration_t(0))
    {
        time_passed = duration_t(0);
    }

    // Update timestamp for next frame
    last_frame_timepoint_ = clock_t::now();

    // Clamp elapsed time if minimum FPS is set
    if (min_fps_ > 0)
    {
        duration_t min_allowed_interval = 1000ms / min_fps_;
        if (time_passed > min_allowed_interval)
        {
            time_passed = min_allowed_interval;
        }
    }

    // Apply temporal smoothing to timestep
    if (smoothing_step_ > 0)
    {
        current_timestep_ = duration_t::zero();
        smoothed_timesteps_.push_back(time_passed);

        if (smoothed_timesteps_.size() > smoothing_step_)
        {
            auto start_iter = smoothed_timesteps_.begin();
            smoothed_timesteps_.erase(start_iter, start_iter + int(smoothed_timesteps_.size() - smoothing_step_));

            for (const auto& interval : smoothed_timesteps_)
            {
                current_timestep_ += interval;
            }
            current_timestep_ /= static_cast<duration_t::rep>(smoothed_timesteps_.size());
        }
        else
        {
            current_timestep_ = smoothed_timesteps_.back();
        }
    }
    else
    {
        current_timestep_ = time_passed;
    }

    ++frame_count_;
}

auto simulation::get_frame() const -> uint64_t
{
    return frame_count_;
}

void simulation::set_min_fps(uint32_t fps)
{
    min_fps_ = std::max<uint32_t>(fps, 0u);
}

void simulation::set_max_fps(uint32_t fps)
{
    max_fps_ = std::max<uint32_t>(fps, 0u);
}

void simulation::set_max_inactive_fps(uint32_t fps)
{
    max_inactive_fps_ = std::max<uint32_t>(fps, 0u);
}

void simulation::set_time_smoothing_step(uint32_t step)
{
    smoothing_step_ = step;
}

auto simulation::get_time_since_launch() const -> duration_t
{
    return clock_t::now() - launch_timepoint_;
}

auto simulation::get_fps() const -> float
{
    auto dt = std::chrono::duration_cast<std::chrono::duration<float, std::milli>>(get_delta_time()).count();
    return (std::abs(dt) < std::numeric_limits<float>::epsilon()) ? 0.0f : 1000.0f / dt;
}

auto simulation::get_delta_time() const -> delta_t
{
    auto dt = std::chrono::duration_cast<delta_t>(current_timestep_) * time_scale_factor_;
    return dt;
}

void simulation::set_time_scale(float scale)
{
    time_scale_factor_ = scale;
}

auto simulation::get_time_scale() const -> float
{
    return time_scale_factor_;
}
