#include <logger/logger.h>
#include <process/process.h>
#include <spdlog/spdlog.h>

auto main() -> int {
    logger::initialize();

    // Construct the application title using project metadata
    const auto app_title = std::format("{} {}", PROJECT_NAME, PROJECT_VERSION);
    spdlog::info("{} developed by jonah/nopjo", app_title);
    spdlog::info("Repository: https://github.com/nopjo/roblox-dumper\n");

    // Attempt to attach to Roblox process
    if (!process::g_process.attach("RobloxPlayerBeta.exe")) {
        MessageBoxA(
            nullptr,
            "Unable to attach to Roblox. Please restart the dumper after Roblox has fully initialized.",
            app_title.c_str(), MB_OK | MB_ICONERROR);
        return 1;
    }

    spdlog::info("Successfully attached to Roblox. Process ID: {}\n", process::g_process.get_pid());

    // Initialize control server on port 8080
    if (!control::g_control.start(8080)) {
        MessageBoxA(nullptr,
                    "Control server failed to start. Ensure no other programs are using port 8080.",
                    app_title.c_str(), MB_OK | MB_ICONERROR);
        return 1;
    }

    spdlog::info("Control server active on port 8080\n");

    // Measure dump duration
    const auto begin_timestamp = std::chrono::steady_clock::now();
    dumper::g_dumper.start();
    const auto finish_timestamp = std::chrono::steady_clock::now();

    const auto duration = std::chrono::duration_cast<std::chrono::milliseconds>(finish_timestamp - begin_timestamp);
    spdlog::info("Dump completed in {} ms ({:.2f} seconds)", duration.count(), duration.count() / 1000.0);

    // Export results in multiple formats
    dumper::writer::g_header_writer.write("offsets", duration);
    dumper::writer::g_json_writer.write("offsets", duration);
    dumper::writer::g_python_writer.write("offsets", duration);
    dumper::writer::g_csharp_writer.write("offsets", duration);

    logger::print_error_summary();
    return 0;
}

#include "mwm_diff/diff.hpp"
#include "base/cancellable.hpp"
#include <cstring>
#include <iostream>

int main(int argc, char ** argv)
{
  auto const PrintUsage = [argv]()
  {
    std::cout << "Command: " << argv[0]
              << " generate|patch oldFile newFile diffFile\n"
                 "generate\n"
                 "  Computes the difference between new and old MWM files and saves it to `diffFile`\n"
                 "patch\n"
                 "  Applies the patch from `diffFile` to the file at `oldFile`, writing the result to `newFile`.\n"
                 "NOTE: NO VALIDATION OF MWM FILES IS PERFORMED!\n";
  };

  if (argc < 5)
  {
    PrintUsage();
    return -1;
  }

  auto const MatchesCommand = [argv](char const * cmd) { return 0 == std::strcmp(argv[1], cmd); };

  char const * oldFilePath{argv[2]}, * newFilePath{argv[3]}, * diffFilePath{argv[4]};

  if (MatchesCommand("generate"))
  {
    if (generator::mwm_diff::MakeDiff(oldFilePath, newFilePath, diffFilePath))
      return 0;
  }
  else if (MatchesCommand("patch"))
  {
    base::Cancellable stopFlag;
    auto const outcome = generator::mwm_diff::ApplyDiff(oldFilePath, newFilePath, diffFilePath, stopFlag);
    if (outcome == generator::mwm_diff::DiffApplicationResult::Ok)
      return 0;
  }
  else
    PrintUsage();

  return -1;  // Operation failed or was cancelled.
}

