#include "events.h"

namespace LVMon {

CEvents::CEvents(void) : conditionVariable_(), mutex_(), eventSet_() {}

CEvents::~CEvents() {}

bool CEvents::GetEventSet(CEvents::Event *pEventOut) {
  bool bAcquired = false;
  std::unique_lock<std::mutex> lock(mutex_);
  if (!eventSet_.empty()) {
    auto iter = eventSet_.begin();
    *pEventOut = *iter;
    eventSet_.erase(iter);
    lock.unlock();
    bAcquired = true;
  }
  return bAcquired;
}

void CEvents::Set(Event evt) {
  std::unique_lock<std::mutex> lock(mutex_);
  eventSet_.insert(evt);
  conditionVariable_.notify_one();
}

void CEvents::Reset(Event evt) {
  std::unique_lock<std::mutex> lock(mutex_);
  eventSet_.erase(evt);
}

CEvents::WaitResult CEvents::Wait(Event evt) {
  WaitResult result = kWaitResultFail;
  std::unique_lock<std::mutex> lock(mutex_);
  conditionVariable_.wait(lock, [&]() {
    auto iter = eventSet_.find(evt);
    if (iter == eventSet_.end())
      return false;
    else {
      eventSet_.erase(evt);
      result = kWaitResultEvent0;
      return true;
    }
  });
  return result;
}

CEvents::WaitResult CEvents::WaitForMultiple(size_t count, Event *events) {
  WaitResult result = kWaitResultFail;
  std::unique_lock<std::mutex> lock(mutex_);
  conditionVariable_.wait(lock, [&]() {
    for (Event *pEvent = events, *pEnd = events + count; pEvent < pEnd; ++pEvent) {
      auto iter = eventSet_.find(*pEvent);
      if (iter != eventSet_.end()) {
        eventSet_.erase(iter);
        result = kWaitResultEvent0 + (pEvent - events);
        return true;
      }
    }
    return false;
  });
  return result;
}

}  // namespace LVMon

#include <iostream>

class Solution {
public:
    bool isPalindrome(int number) {
        if (number < 0) return false;
        if (number == 0) return true;

        // Handle positive integers only
        // Example: number = 12345
        // reversedNum will become 54321 after processing

        int digit;
        long long reversedNum = 0;
        int temp = number;

        while (temp > 0) {  // Process each digit from right to left
            digit = temp % 10;         // Extract rightmost digit
            temp = temp / 10;          // Remove rightmost digit from temp
            reversedNum = reversedNum * 10 + digit;  // Append digit to reversed number
        }

        // Compare original number with its reverse
        if ((long long)number == reversedNum) 
            return true;
        else 
            return false;
    }
};

#include "Face3D.hpp"

using std::inner_product;
using namespace MadVoro;

MadVoro::Face3D::Face3D(point_vec_v const& points, std::size_t neighborA, std::size_t neighborB)
  : vertices(points), neighbors(neighborA, neighborB) {}

Face3D& MadVoro::Face3D::operator=(const Face3D& rhs)
{
  vertices = rhs.vertices;
  neighbors = rhs.neighbors;
  return *this;
}

MadVoro::Face3D::Face3D(void): vertices(), neighbors() {}

MadVoro::Face3D::~Face3D(void)
{}

MadVoro::Face3D::Face3D(Face3D const& source):
  vertices(source.vertices),
  neighbors(source.neighbors) {}

double MadVoro::Face3D::GetArea(void) const
{
  const Point3D& reference = vertices[0];
  return inner_product(vertices.begin()+1,
		       vertices.end()-1,
		       vertices.begin()+2,
		       0.0,
		       [](const double a, const double b)
		       {return a + b;},
		       [&reference](const Point3D& p1, const Point3D& p2)
		       {return 0.5 * fastabs(CrossProduct(p1 - reference, p2 - reference));});
}

Point3D compute_centroid(const Face3D& face)
{
  const Point3D& origin = face.vertices[0];
  return inner_product(face.vertices.begin()+1,
		       face.vertices.end()-1,
		       face.vertices.begin()+2,
		       Point3D(0.0, 0.0, 0.0),
		       [](const Point3D& acc, const Point3D& curr)
		       {return acc + curr;},
		       [&origin](const Point3D& pt1, const Point3D& pt2)
		       {
			 const double tri_area = 0.5 * fastabs
			   (CrossProduct(pt1 - origin, pt2 - origin));
			 return tri_area * (pt1 + pt2 + origin) / 3.0;
		       });
}

