//------------------------------------------------
//
// suite
//
//------------------------------------------------
any_suite::
~any_suite() = default;
//------------------------------------------------
suites&
suites::
instance() noexcept
{
    class suites_container : public suites
    {
        std::vector<any_suite const*> container_;
    public:
        virtual ~suites_container() = default;
        void
        insert(any_suite const& t) override
        {
            container_.push_back(&t);
        }
        iterator
        begin() const noexcept override
        {
            if (!container_.empty())
                return &container_[0];
            return nullptr;
        }
        iterator
        end() const noexcept override
        {
            if (!container_.empty())
                return &container_[0] + container_.size();
            return nullptr;
        }
        void
        sort() override
        {
            std::sort(
                container_.begin(),
                container_.end(),
                []( any_suite const* pA,
                    any_suite const* pB )
                {
                    auto nameA = pA->name();
                    auto lenA = std::strlen(nameA);
                    auto nameB = pB->name();
                    auto lenB = std::strlen(nameB);
                    return std::lexicographical_compare(
                        nameA, nameA + lenA, nameB, nameB + lenB );
                });
        }
    };
    static suites_container instance_impl;
    return instance_impl;
}
