using clock_type =
    std::chrono::steady_clock;
struct timing_info
{
    clock_type::duration d;
};
std::ostream&
operator<<(
    std::ostream& os,
    timing_info const& t)
{
    using namespace std::chrono;
    auto const ms = duration_cast<
        milliseconds>(t.d);
    if (ms < seconds{1})
    {
        os << ms.count() << "ms";
    }
    else
    {
        std::streamsize width{
            os.width()};
        std::streamsize precision{
            os.precision()};
        os << std::fixed <<
            std::setprecision(1) <<
            (ms.count() / 1000.0) << "s";
        os.precision(precision);
        os.width(width);
    }
    return os;
}
