namespace test_suite {
namespace detail {
class simple_runner : public any_runner
{
    struct summary_data
    {
        char const* label;
        clock_type::time_point start_time;
        clock_type::duration duration;
        std::atomic<std::size_t> failures;
        std::atomic<std::size_t> total_tests;
        summary_data(summary_data const& other) noexcept
            : label(other.label)
            , start_time(other.start_time)
            , duration(other.duration)
            , failures(other.failures.load())
            , total_tests(other.total_tests.load())
        {
        }
        explicit
        summary_data(char const* name_) noexcept
            : label(name_)
            , start_time(clock_type::now())
            , failures(0)
            , total_tests(0)
        {
        }
    };
    summary_data overall_;
    std::ostream& output_stream_;
    std::vector<summary_data> suite_summaries_;
    bool print_timing_on_exit_ = true;

    void
    log_duration()
    {
        output_stream_ <<
            timing_info{clock_type::now() -
                     overall_.start_time } << ", " <<
            suite_summaries_.size() << " suites, " <<
            overall_.failures.load() << " failures, " <<
            overall_.total_tests.load() << " total." <<
            std::endl;
    }

public:
    explicit
    simple_runner(
        std::ostream& os)
        : overall_("(all)")
        , output_stream_(os)
    {
        std::unitbuf(output_stream_);
        suite_summaries_.reserve(256);
    }

    virtual ~simple_runner()
    {
        if (!print_timing_on_exit_)
            return;
        log_duration();
    }

    // true if no failures occurred
    bool
    success() const noexcept
    {
        return overall_.failures.load() == 0;
    }

    void
    run(any_suite const& test) override
    {
        suite_summaries_.emplace_back(test.name());
        output_stream_ << test.name() << "\n";
        test.run();
        suite_summaries_.back().duration =
            clock_type::now() -
            suite_summaries_.back().start_time;
    }

    void
    note(char const* msg) override
    {
        output_stream_ << msg << "\n";
    }

    std::ostream&
    log() noexcept override
    {
        return output_stream_;
    }

    char const*
    extract_filename(
        char const* full_path)
    {
        auto const base = full_path;
        auto pos = base + std::strlen(full_path);
        while(pos-- != base)
        {
        #ifdef _MSC_VER
            if(*pos == '\\')
        #else
            if(*pos == '/')
        #endif
                break;
        }
        return pos + 1;
    }

    bool test(bool, char const*, char const*, char const*, int) override;

    bool
    set_print_timing_on_exit(bool flag)
    {
        bool const old_value = print_timing_on_exit_;
        print_timing_on_exit_ = flag;
        return old_value;
    }
};
//------------------------------------------------
bool
simple_runner::
test(
    bool condition,
    char const* expression,
    char const* function_name,
    char const* file_path,
    int line_number)
{
    auto const test_id = ++overall_.total_tests;
    ++suite_summaries_.back().total_tests;
    if (condition)
        return true;

    ++overall_.failures;
    ++suite_summaries_.back().failures;

    (void)function_name;
    output_stream_ <<
        "#" << test_id << " " <<
        extract_filename(file_path) << "(" << line_number << ") "
        "failed: " << expression <<
        //" in " << function_name <<
        "\n";
    output_stream_.flush();
    return false;
}
} // detail

namespace {
    int global_argc = 0;
    char const* const* global_argv = nullptr;
}

void
set_command_line(
    int argc,
    char const* const* argv)
{
    global_argc = argc;
    global_argv = argv;
}

int
argc()
{
    if (global_argc == 0 || global_argv == nullptr)
        throw std::runtime_error("Command-line arguments not initialized. Call set_command_line() first.");
    return global_argc;
}

char const* const*
argv()
{
    if (global_argc == 0 || global_argv == nullptr)
        throw std::runtime_error("Command-line arguments not initialized. Call set_command_line() first.");
    return global_argv;
}

char const*
get_command_line_option(
    char const* short_flag,
    char const* long_flag)
{
    if (global_argc == 0 || global_argv == nullptr)
        throw std::runtime_error("Command-line arguments not initialized. Call set_command_line() first.");

    std::size_t const short_len = short_flag ? std::strlen(short_flag) : 0;
    std::size_t const long_len = long_flag ? std::strlen(long_flag) : 0;

    for (int i = 1; i < global_argc; ++i)
    {
        const char* current_arg = global_argv[i];
        std::size_t arg_length = std::strlen(current_arg);

        if (arg_length < 2 ||
            current_arg[0] != '-')
        {
            continue;
        }

        // Check for long option: --flag or --flag=value
        if (long_flag && std::strncmp(current_arg, "--", 2) == 0)
        {
            const char* rest = current_arg + 2;
            if (std::strncmp(rest, long_flag, long_len) == 0)
            {
                if (rest[long_len] == '=')
                    return rest + long_len + 1;
                if (rest[long_len] == '\0' && i + 1 < global_argc)
                    return global_argv[i + 1];
            }
            rest -= 2; // restore pointer
        }

        // Check for short option: -f or -f value
        if (short_flag && std::strncmp(current_arg, "-", 1) == 0 && std::strncmp(current_arg, "--", 2) != 0)
        {
            const char* rest = current_arg + 1;
            if (std::strncmp(rest, short_flag, short_len) == 0)
            {
                if (rest[short_len] == '=')
                    return rest + short_len + 1;
                if (rest[short_len] == '\0' && i + 1 < global_argc)
                    return global_argv[i + 1];
            }
        }
    }

    return nullptr;
}

/** Return a command-line flag
    This function returns true if the specified flag exists,
    otherwise it returns false.
    A command-line flag can be set with the `--name` format
    or the `-n` format.
    @param short_name The short form of the flag to search for.
    @param long_name The long form of the flag to search for.
    @return true if the flag is present, false otherwise.
 */
bool
get_command_line_flag(
    char const* short_flag,
    char const* long_flag)
{
    if (global_argc == 0 || global_argv == nullptr)
        throw std::runtime_error("Command-line arguments not initialized. Call set_command_line() first.");

    std::size_t const short_len = short_flag ? std::strlen(short_flag) : 0;
    std::size_t const long_len = long_flag ? std::strlen(long_flag) : 0;

    for (int i = 1; i < global_argc; ++i)
    {
        char const* current_arg = global_argv[i];
        std::size_t arg_length = std::strlen(current_arg);

        if (arg_length < 2 ||
            current_arg[0] != '-')
        {
            continue;
        }

        // Check for the long flag: --name
        if (long_flag && std::strncmp(current_arg, "--", 2) == 0) {
            const char* rest = current_arg + 2;
            if (std::strncmp(rest, long_flag, long_len) == 0
                && (rest[long_len] == '\0' || rest[long_len] == ' '))
            {
                return true;
            }
            rest -= 2; // restore pointer
        }

        // Check for the short flag: -n
        if (short_flag && std::strncmp(current_arg, "-", 1) == 0
            && std::strncmp(current_arg, "--", 2) != 0)
        {
            const char* rest = current_arg + 1;
            if (std::strncmp(rest, short_flag, short_len) == 0
                && (rest[short_len] == '\0' || rest[short_len] == ' '))
            {
                return true;
            }
        }
    }

    return false;
}

int
run(std::ostream& out)
{
    int argc = ::test_suite::argc();
    char const* const* argv = ::test_suite::argv();

    detail::simple_runner runner(out);
    suites::instance().sort();

    // If one of the arguments is -h or --help, show usage regardless
    // of other arguments
    if (get_command_line_flag("h", "help"))
    {
        // executable name
        char const* exe_name = argv[0];
        char const* last_slash = std::strrchr(exe_name, '/');
        if (!last_slash)
            last_slash = std::strrchr(exe_name, '\\');
        if (last_slash)
            exe_name = last_slash + 1;

        out <<
            "Run all test suites or only those matching the provided names.\n"
            "Usage:\n"
            "  " << exe_name << " <suite-specs> ... [ options ]\n"
                           "where\n"
                           "  - <suite-specs> are the names of test suite patterns to run\n"
                           "  - options are command-line flags or options\n"
                           "Available options and flags:\n"
                           "  -h, --help          Show this help message\n"
                           "  -l, --list-tests    List all available test suites\n"
            << std::endl;

        return EXIT_SUCCESS;
    }

    // If one of the arguments is --list-tests, list all available test suites
    // regardless of other arguments
    if (get_command_line_flag("l", "list-tests"))
    {
        for (any_suite const* entry : suites::instance())
        {
            out << entry->name() << "\n";
        }
        runner.set_print_timing_on_exit(false);
        return EXIT_SUCCESS;
    }

    // Identify range of suite patterns
    char const* const* pattern_start = argv + 1;
    char const* const* pattern_end = pattern_start;

    for (; pattern_end < argv + argc; ++pattern_end)
    {
        if (pattern_end[0][0] == '-' && pattern_end[0][1] != '\0')
           break; // stop at the first option
    }

    // Run the specified test suites
    bool const run_all = pattern_start == pattern_end;

    auto should_run =
        [pattern_start, pattern_end, run_all](
            char const* suite_name) {
        if (run_all)
        {
            return true;
        }

        std::size_t const suite_name_len = std::strlen(suite_name);

        for (char const* const* pattern_it = pattern_start;
             pattern_it != pattern_end;
             ++pattern_it)
        {
            char const* pattern = *pattern_it;
            std::size_t const pattern_len = std::strlen(pattern);

            if (pattern_len > suite_name_len)
            {
                continue;
            }

            // 1. An exact match (such as "boost.url.grammar.parse")
            if (std::strcmp(pattern, suite_name) == 0)
            {
                return true;
            }

            // 2. Path match (such as "boost.url.grammar")
            if (pattern_len < suite_name_len &&
                suite_name[pattern_len] == '.' &&
                std::strncmp(suite_name, pattern, pattern_len) == 0)
            {
                return true;
            }
        }

        return false;
    };

    for (any_suite const* suite : suites::instance())
    {
        if (should_run(suite->name()))
        {
            runner.run(*suite);
        }
    }

    return runner.success() ?
       EXIT_SUCCESS : EXIT_FAILURE;
}

int
run()
{
    ::test_suite::debug_stream out(std::cerr);
    return run(out);
}

int
run(std::ostream& out,
    int argc,
    char const* const* argv)
{
    ::test_suite::set_command_line(argc, argv);
    return run(out);
}

int
run(int argc, char const* const* argv)
{
    ::test_suite::set_command_line(argc, argv);
    return run();
}

} // test_suite

