pdb_remote_session_t::client_read_request_t::client_read_request_t()
  : kind(NONE),
    off_ea(BADADDR),
    buffer(nullptr),
    size(0),
    success(false)
{
    read_req = qsem_create(nullptr, 0);
    read_resp = qsem_create(nullptr, 0);
}
//--------------------------------------------------------------------------
pdb_remote_session_t::client_read_request_t::~client_read_request_t()
{
    qsem_free(read_req);
    qsem_free(read_resp);
    read_req = nullptr;
    read_resp = nullptr;
    buffer = nullptr;
}
//----------------------------------------------------------- pdb thread ---
bool pdb_remote_session_t::client_read_request_t::request_read(
        pdb_rr_kind_t _kind,
        uint64  _off_ea,
        uint32  _count,
        void   *_buffer,
        uint32 *_nread)
{
    off_ea = _off_ea;
    size   = _count;
    buffer = _buffer;
    kind   = _kind;
    qsem_post(read_req);
    qsem_wait(read_resp, INFINITE);
    if ( _nread != nullptr )
        *_nread = size;
    return success;
}
