struct symbol_packer_t : public pdb_access_t::children_visitor_t
{
    pdb_remote_session_t *pdb_rsess;
    int count;
    symbol_packer_t(pdb_remote_session_t *_pdb_rsess)
      : pdb_rsess(_pdb_rsess), count(0) {}
    HRESULT visit_child(pdb_sym_t &_sym)
    {
        QASSERT(1551, _sym.whoami() == DIA_PDB_SYM);
        dia_pdb_sym_t &diasym = (dia_pdb_sym_t &)_sym;
        if ( pdb_rsess->pack_symbol(diasym.data) == 0 )
            ++count;
        return S_OK;
    }
};
//----------------------------------------------------------- pdb thread ---
bool pdb_remote_session_t::perform()
{
    QASSERT(628, session_ref.opened() || fetch_type == FT_OPEN);
    QASSERT(629, fetch_id != (uint32) -1 || fetch_type == FT_OPEN);
    storage.qclear();
    uint32 syms_count = 0;
    bool stores_syms = fetch_type == FT_CHILDREN
                    || fetch_type == FT_SYMBOL
                    || fetch_type == FT_SYMBOLS_AT_VA
                    || fetch_type == FT_FILE_COMPILANDS;
    if ( stores_syms )
        storage.append(&syms_count, sizeof(syms_count));
    try
    {
        local_pdb_access_t *acc = fetch_type != FT_OPEN
                                ? session_ref.session->pdb_access : nullptr;
        HRESULT hr = E_FAIL;
        switch ( fetch_type )
        {
            case FT_OPEN:
                {
                    if ( !session_ref.opened() )
                    {
                        args.user_data = this;
                        hr = session_ref.open_session(args);
                        if ( SUCCEEDED(hr) )
                        {
                            const char *fname = session_ref.session->get_used_fname();
                            msg("PDB: successfully opened %s (%d)\n", fname, session_id);
                        }
                        else
                        {
                            pdberr_suggest_vs_runtime(hr);
                        }
                    }
                    else
                    {
                        hr = S_OK;
                    }
                }
                break;
            case FT_SYMBOL:
                {
                    pdb_sym_t *sym = acc->create_sym(fetch_id);
                    pdb_sym_janitor_t janitor_sym(sym);
                    QASSERT(1552, sym->whoami() == DIA_PDB_SYM);
                    dia_pdb_sym_t *diasym = (dia_pdb_sym_t *)sym;
                    if ( pack_symbol(diasym->data) == 0 )
                    {
                        ++syms_count;
                        hr = S_OK;
                    }
                }
                break;
            case FT_CHILDREN:
                {
                    pdb_sym_t *sym = acc->create_sym(fetch_id);
                    pdb_sym_janitor_t janitor_sym(sym);
                    symbol_packer_t packer(this);
                    hr = session_ref.session->pdb_access->iterate_children(
                        *sym,
                        fetch_symbol_type,
                        packer);
                    if ( SUCCEEDED(hr) )
                        syms_count = packer.count;
                }
                break;
            case FT_LINES_BY_VA:
            case FT_LINES_BY_COORDS:
                {
                    pdb_lnnums_t lnnums;
                    hr = fetch_type == FT_LINES_BY_VA
                      ? acc->sip_retrieve_lines_by_va(&lnnums, fetch_va, fetch_length)
                      : acc->sip_retrieve_lines_by_coords(
                              &lnnums, fetch_file_id, fetch_lnnum, fetch_colnum);
                    if ( SUCCEEDED(hr) )
                    {
                        const uint32 sz = uint32(lnnums.size());
                        storage.pack_dd(sz);
                        for ( uint32 i = 0; i < sz; ++i )
                        {
                            const pdb_lnnum_t &ln = lnnums[i];
                            storage.pack_ea64(ln.va);
                            storage.pack_dd(ln.length);
                            storage.pack_dd(ln.columnNumber);
                            storage.pack_dd(ln.columnNumberEnd);
                            storage.pack_dd(ln.lineNumber);
                            storage.pack_dd(ln.lineNumberEnd);
                            storage.pack_dd(ln.file_id);
                            storage.pack_db(ln.statement);
                        }
                    }
                }
                break;
            case FT_SYMBOLS_AT_VA:
            case FT_FILE_COMPILANDS:
                {
                    symbol_packer_t packer(this);
                    hr = fetch_type == FT_SYMBOLS_AT_VA
                      ? acc->sip_iterate_symbols_at_ea(
                              fetch_va, fetch_length, fetch_symbol_type, packer)
                      : acc->sip_iterate_file_compilands(fetch_file_id, packer);
                    if ( SUCCEEDED(hr) )
                        syms_count = packer.count;
                }
                break;
            case FT_FILE_PATH:
                {
                    qstring res;
                    hr = acc->sip_retrieve_file_path(&res, nullptr, fetch_file_id);
                    if ( SUCCEEDED(hr) )
                        storage.pack_str(res.c_str());
                }
                break;
            case FT_SYMBOL_FILES:
            case FT_FIND_FILES:
                {
                    qvector<DWORD> res;
                    if ( fetch_type == FT_SYMBOL_FILES )
                    {
                        pdb_sym_t *_sym = acc->create_sym(fetch_id);
                        pdb_sym_janitor_t janitor_sym(_sym);
                        hr = acc->sip_retrieve_symbol_files(&res, *_sym);
                    }
                    else
                    {
                        hr = acc->sip_find_files(&res, fetch_str.c_str());
                    }
                    if ( SUCCEEDED(hr) )
                    {
                        const uint32 sz = uint32(res.size());
                        storage.pack_dd(sz);
                        for ( uint32 i = 0; i < sz; ++i )
                            storage.pack_dd(res[i]);
                    }
                }
                break;
            default:
                INTERR(630);
        }
        if ( stores_syms )
            memcpy(storage.begin(), &syms_count, sizeof(syms_count));
        return hr == S_OK;
    }
    catch ( const pdb_exception_t &e )
    {
        msg("Failed fetching data: %s\n", e.what.c_str());
        return false;
    }
}
//----------------------------------------------------------------------------
void pdb_remote_session_t::stop()
{
    if ( is_opening )
    {
        while ( !is_done() )
        {
            if ( client_read_request.pending() )
            {
                client_read_request.success = false;
                client_read_request.read_complete();
            }
            qsleep(100);
        }
    }
}
//-------------------------------------------------------------------------
bool pdb_thread_t::is_running() const
{
    qmutex_locker_t lock(opener_mutex);
    bool running = worker_handle != nullptr;
    return running;
}
//----------------------------------------------------------------------------
void pdb_thread_t::terminate()
{
    qmutex_locker_t lock(opener_mutex);
    if ( worker_handle != nullptr )
    {
        msg("PDB: forcibly killing thread...\n");
        qthread_kill(worker_handle);
        qthread_free(worker_handle);
        worker_handle = nullptr;
    }
}
//----------------------------------------------------------------------------
static int idaapi main_pdb_func(void *)
{
    while ( true )
    {
        qsem_post(pdb_thread.request_ready);
        qsem_wait(pdb_thread.response_ready, INFINITE);
        pdb_remote_session_t *pdb_rsess = pdb_thread.pdb_rsess;
        pdb_rsess->fetch_ok = pdb_rsess->perform();
        qsem_post(pdb_rsess->fetch_complete);
    }
    return 0;
}
//----------------------------------------------------------------------------
void pdb_thread_t::start_if_needed()
{
    qmutex_locker_t lock(opener_mutex);
    if ( worker_handle == nullptr )
        worker_handle = qthread_create(main_pdb_func, nullptr);
}

#include <ocs2_ballbot/dynamics/BallbotSystemDynamics.h>
// robcogen
#include <iit/rbd/rbd.h>
#include <iit/rbd/traits/TraitSelector.h>
#include "ocs2_ballbot/generated/forward_dynamics.h"
#include "ocs2_ballbot/generated/inertia_properties.h"
#include "ocs2_ballbot/generated/inverse_dynamics.h"
#include "ocs2_ballbot/generated/jsim.h"
#include "ocs2_ballbot/generated/transforms.h"

namespace ocs2 {
namespace ballbot {

ad_vector_t BallbotSystemDynamics::systemFlowMap(ad_scalar_t time, const ad_vector_t& state, const ad_vector_t& input,
                                                 const ad_vector_t& parameters) const {
  // Compute the actuation matrix S^T appearing in: M(q)·v̇ + h = S^T·τ
  Eigen::Matrix<ad_scalar_t, 5, 3> actuationMatrix = Eigen::Matrix<ad_scalar_t, 5, 3>::Zero();

  const ad_scalar_t cosYaw = cos(state(2));
  const ad_scalar_t cosPitch = cos(state(3));
  const ad_scalar_t cosRoll = cos(state(4));
  const ad_scalar_t sinYaw = sin(state(2));
  const ad_scalar_t sinPitch = sin(state(3));
  const ad_scalar_t sinRoll = sin(state(4));

  const ad_scalar_t sqrt2 = ad_scalar_t(sqrt(2.0));
  const ad_scalar_t sqrt3 = ad_scalar_t(sqrt(3.0));
  const ad_scalar_t k1 = (sqrt2 * ballRadius_) / (4.0 * wheelRadius_);
  const ad_scalar_t k3 = (sqrt2 * cosPitch * sinYaw);
  const ad_scalar_t k4 = cosRoll * sinYaw - cosYaw * sinPitch * sinRoll;
  const ad_scalar_t k5 = sinRoll * sinYaw + cosRoll * cosYaw * sinPitch;
  const ad_scalar_t k6 = sqrt2 * cosPitch * cosYaw;

  actuationMatrix(0, 0) =
      -(sqrt2 * (cosYaw * sinRoll - cosRoll * sinPitch * sinYaw)) / (2 * wheelRadius_) - (sqrt2 * cosPitch * sinYaw) / (2 * wheelRadius_);
  actuationMatrix(0, 1) = (sqrt2 * cosPitch * sinYaw) / (4 * wheelRadius_) -
                          (sqrt2 * (cosYaw * sinRoll - cosRoll * sinPitch * sinYaw)) / (2 * wheelRadius_) -
                          (sqrt2 * sqrt3 * (cosRoll * cosYaw + sinPitch * sinRoll * sinYaw)) / (4 * wheelRadius_);
  actuationMatrix(0, 2) = (sqrt2 * cosPitch * sinYaw) / (4 * wheelRadius_) -
                          (sqrt2 * (cosYaw * sinRoll - cosRoll * sinPitch * sinYaw)) / (2 * wheelRadius_) +
                          (sqrt2 * sqrt3 * (cosRoll * cosYaw + sinPitch * sinRoll * sinYaw)) / (4 * wheelRadius_);

  actuationMatrix(1, 0) = (k6) / (2.0 * wheelRadius_) - (sqrt2 * (k5)) / (2.0 * wheelRadius_);
  actuationMatrix(1, 1) =
      -(sqrt2 * (k5)) / (2.0 * wheelRadius_) - (k6) / (4.0 * wheelRadius_) - (sqrt2 * sqrt3 * (k4)) / (4.0 * wheelRadius_);
  actuationMatrix(1, 2) =
      (sqrt2 * sqrt3 * (k4)) / (4.0 * wheelRadius_) - (k6) / (4.0 * wheelRadius_) - (sqrt2 * (k5)) / (2.0 * wheelRadius_);

  actuationMatrix(2, 0) = -(sqrt2 * ballRadius_ * (sinPitch + cosPitch * cosRoll)) / (2 * wheelRadius_);
  actuationMatrix(2, 1) = (sqrt2 * ballRadius_ * (sinPitch - 2 * cosPitch * cosRoll + sqrt3 * cosPitch * sinRoll)) / (4 * wheelRadius_);
  actuationMatrix(2, 2) = -(sqrt2 * ballRadius_ * (2 * cosPitch * cosRoll - sinPitch + sqrt3 * cosPitch * sinRoll)) / (4 * wheelRadius_);

  actuationMatrix(3, 0) = 2.0 * k1 * sinRoll;
  actuationMatrix(3, 1) = k1 * (2.0 * sinRoll + sqrt3 * cosRoll);
  actuationMatrix(3, 2) = k1 * (2.0 * sinRoll - sqrt3 * cosRoll);

  actuationMatrix(4, 0) = 2.0 * k1;
  actuationMatrix(4, 1) = -k1;
  actuationMatrix(4, 2) = -k1;

  // Compute joint accelerations using autogen code
  iit::Ballbot::tpl::JointState<ad_scalar_t> qdd;
  iit::Ballbot::tpl::JointState<ad_scalar_t> tau_eff = actuationMatrix * input;

  using trait_t = typename iit::rbd::tpl::TraitSelector<ad_scalar_t>::Trait;
  iit::Ballbot::dyn::tpl::InertiaProperties<trait_t> inertias;
  iit::Ballbot::tpl::MotionTransforms<trait_t> transforms;
  iit::Ballbot::dyn::tpl::ForwardDynamics<trait_t> forward_dyn(inertias, transforms);
  forward_dyn.fd(qdd, state.head<5>(), state.tail<5>(), tau_eff);

  // Construct state derivative: [velocity; acceleration]
  ad_vector_t stateDerivative(10);
  stateDerivative << state.tail<5>(), qdd;
  return stateDerivative;
}

}  // namespace ballbot
}  // namespace ocs2

