StopMotionSerial::StopMotionSerial() { 
    m_serialPort = new QSerialPort(this); 
}

StopMotionSerial::~StopMotionSerial() {}

//-----------------------------------------------------------------
QStringList StopMotionSerial::getAvailableSerialPorts() {
    QList<QSerialPortInfo> portList = QSerialPortInfo::availablePorts();
    QStringList availablePorts;
    availablePorts.push_back(tr("No Device"));

    int count = portList.size();
    for (int index = 0; index < count; ++index) {
        std::string description = portList.at(index).description().toStdString();
        std::string portName    = portList.at(index).portName().toStdString();
        std::string manufacturer = portList.at(index).manufacturer().toStdString();

        availablePorts.push_back(portList.at(index).portName());

        if (portList.at(index).hasProductIdentifier()) {
            std::string productIdStr =
                QString::number(portList.at(index).productIdentifier()).toStdString();
        }

        if (portList.at(index).hasVendorIdentifier()) {
            std::string vendorIdStr =
                QString::number(portList.at(index).vendorIdentifier()).toStdString();
        }
    }

    return availablePorts;
}

//-----------------------------------------------------------------
bool StopMotionSerial::setSerialPort(QString selectedPort) {
    if (m_serialPort->isOpen()) {
        m_serialPort->close();
    }

    QList<QSerialPortInfo> portList = QSerialPortInfo::availablePorts();
    bool connectionSuccess = false;
    int portCount = portList.size();

    for (int i = 0; i < portCount; ++i) {
        if (selectedPort == portList.at(i).portName()) {
            m_serialPort->setPort(portList.at(i));
            break;
        }
    }

    bool isOpened = m_serialPort->open(QIODevice::ReadWrite);
    if (isOpened) {
        connectionSuccess = m_serialPort->setBaudRate(QSerialPort::Baud9600) &
                            m_serialPort->setParity(QSerialPort::NoParity) &
                            m_serialPort->setDataBits(QSerialPort::Data8) &
                            m_serialPort->setStopBits(QSerialPort::OneStop) &
                            m_serialPort->setFlowControl(QSerialPort::NoFlowControl);

        std::string frameNumberStr =
            std::to_string(StopMotion::instance()->getXSheetFrameNumber());
        const char* frameNumberCStr = frameNumberStr.c_str();

        m_serialPort->write(frameNumberCStr);
        m_serialPort->waitForBytesWritten(10);

        QByteArray receivedData = m_serialPort->readLine();
        while (m_serialPort->waitForReadyRead(30)) {
            receivedData += m_serialPort->readLine();
        }

        QByteArray response = receivedData;
        QString responseString(response);
        std::string responseText = response.toStdString();
    }

    return connectionSuccess;
}

//-----------------------------------------------------------------
void StopMotionSerial::sendSerialData() {
    if (m_serialPort->isOpen()) {
        std::string frameNumberStr =
            std::to_string(StopMotion::instance()->getXSheetFrameNumber());
        const char* frameNumberCStr = frameNumberStr.c_str();

        m_serialPort->write(frameNumberCStr);
        m_serialPort->waitForBytesWritten(10);

        QByteArray receivedData = m_serialPort->readLine();
