#define UPDATENOTIFIER_DEBUG DEBUG_FLAGS_NONE
#ifdef DEBUGALL
#undef UPDATENOTIFIER_DEBUG
#define UPDATENOTIFIER_DEBUG DEBUG_FLAGS_EVERYTHING
#endif

UINT updatenotifier_debug = UPDATENOTIFIER_DEBUG;

// GitHub API endpoint for fetching latest release info
const char* szGitHubRepoReleases = "https://api.github.com/repos/sc2kfix/sc2kfix/releases?per_page=1";
const char* szGitHubAPIType[] = { "Accept: application/vnd.github+json", NULL };

char szLatestRelease[24] = { 0 };
BOOL bUpdateAvailable = FALSE;

DWORD WINAPI UpdaterThread(LPVOID lpParameter) {
    // Delay to allow main initialization to complete before checking updates
    Sleep(250);
    bUpdateAvailable = UpdaterCheckForUpdates();
    return EXIT_SUCCESS;
}

#define FETCHBUF_SIZE 4096
#define BUF_SIZE (FETCHBUF_SIZE * 4)

BOOL UpdaterCheckForUpdates(void) {
    DWORD dwContext;

    // Initialize WinINet session
    HINTERNET hInet = InternetOpen("sc2kfix Update Notifier", INTERNET_OPEN_TYPE_DIRECT, NULL, NULL, NULL);
    if (!hInet) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Failed to initialize Internet session.\n");
        return FALSE;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  InternetOpen() successful\n");

    // Set connection timeout to 3 seconds
    DWORD dwTimeoutMilliseconds = 3000;
    InternetSetOption(hInet, INTERNET_OPTION_CONNECT_TIMEOUT, &dwTimeoutMilliseconds, sizeof(DWORD));

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Timeout set to %u ms\n", dwTimeoutMilliseconds);

#pragma warning(push)
#pragma warning(disable:6385)
    // Open URL with secure flag and custom header
    HINTERNET hHttpRequest = InternetOpenUrl(hInet, szGitHubRepoReleases, "X-GitHub-Api-Version: 2022-11-28\r\n", -1L, INTERNET_FLAG_SECURE, (DWORD_PTR)&dwContext);
#pragma warning(pop)

    if (!hHttpRequest) {
        if (GetLastError() == 12002)
            ConsoleLog(LOG_WARNING, "UPD:  Connection timed out after 3000 ms.\n");
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  InternetOpenUrl failed, error code: 0x%08X\n", GetLastError());
        return FALSE;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  InternetOpenUrl() successful\n");

    DWORD dwBytesGrabbed = 0;
    DWORD dwBytesReceived = 0;
    char szTempBuf[FETCHBUF_SIZE + 1];
    char* szBuffer = (char*)malloc(BUF_SIZE + 1);

    if (!szBuffer) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Memory allocation failed for buffer.\n");
        return FALSE;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Buffer allocated (%u bytes)\n", BUF_SIZE);

    // Read response in chunks
    while (InternetReadFile(hHttpRequest, szTempBuf, sizeof(szTempBuf) - 1, &dwBytesGrabbed)) {
        if (dwBytesGrabbed == 0 || (dwBytesReceived + dwBytesGrabbed) >= BUF_SIZE)
            break;

        dwBytesReceived += dwBytesGrabbed;
        strcat_s(szBuffer, BUF_SIZE, szTempBuf);
        ZeroMemory(szTempBuf, sizeof(szTempBuf));
    }

    szBuffer[BUF_SIZE] = '\0';  // Ensure null termination

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  InternetReadFile() completed, total bytes: %u\n", dwBytesReceived);

    // Clean up handles
    InternetCloseHandle(hHttpRequest);
    InternetCloseHandle(hInet);

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Handles closed\n");

    // Parse JSON response for tag_name
    char* szTagString = strstr(szBuffer, "\"tag_name\"");
    if (!szTagString) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Could not find 'tag_name' in response.\n");
        free(szBuffer);
        return FALSE;
    }

    char* szQuoteComma = strstr(szTagString, "\",");
    char szThrowaway[64] = { 0 };
    strncpy_s(szThrowaway, 64, szTagString, szQuoteComma - szTagString);

    int n = sscanf_s(szThrowaway, "\"tag_name\":\"%s\"", szLatestRelease, 23);
    if (!*szLatestRelease) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Failed to parse version string (parsed %d fields).\n", n);
        free(szBuffer);
        return FALSE;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Latest release detected: %s\n", szLatestRelease);

    // Compare current vs latest version
    if (strcmp(szSC2KFixReleaseTag, szLatestRelease)) {
        ConsoleLog(LOG_INFO, "UPD:  New update available: %s (current: %s)\n", szLatestRelease, szSC2KFixReleaseTag);
        if (dwDetectedVersion == VERSION_SC2K_1996)
            PostMessage(hwndMainDialog_SC2K1996, WM_SC2KFIX_UPDATE, 0, 1);
        free(szBuffer);
        return TRUE;
    }

    free(szBuffer);
    return FALSE;
}

