void DQRNetworkManager::LogComment(Platform::String^ message) {
#ifndef _CONTENT_PACKAGE
    static int64_t startTime = 0;
    wchar_t buffer[64];
    int64_t currentTime = System::currentTimeMillis();

    if (startTime != 0) {
        _i64tow_s(currentTime - startTime, buffer, 64, 10);
        OutputDebugString(buffer);
        OutputDebugString(L" ms: ");
    } else {
        startTime = currentTime;
    }

    OutputDebugString(message->Data());
    OutputDebugString(L"\n");
#endif
}

void DQRNetworkManager::LogCommentFormat(LPCWSTR format, ...) {
    WCHAR outputBuffer[2048];
    va_list arguments;
    va_start(arguments, format);
    _vsnwprintf_s(outputBuffer, 2048, _TRUNCATE, format, arguments);
    outputBuffer[2047] = L'\0';
    va_end(arguments);
    LogComment(ref new Platform::String(outputBuffer));
}

void DQRNetworkManager::LogCommentWithError(Platform::String^ text, HRESULT errorCode) {
    Platform::String^ combinedMessage = text + GetErrorString(errorCode);
    LogComment(combinedMessage);
}

Platform::String^ DQRNetworkManager::GetErrorString(HRESULT hr) {
    Platform::String^ formatted = FormatString(L" %s [0x%0.8x]", ConvertHResultToErrorName(hr)->Data(), hr);
    return formatted;
}

Platform::String^ DQRNetworkManager::FormatString(LPCWSTR format, ...) {
    WCHAR tempBuffer[2048];
    va_list args;
    va_start(args, format);
    _vsnwprintf_s(tempBuffer, 2048, _TRUNCATE, format, args);
    tempBuffer[2047] = L'\0';
    va_end(args);
    Platform::String^ result = ref new Platform::String(tempBuffer);
    return result;
}

