#include "HKDF.h"
#include <HKDF.h>
#include <SHA256.h>
using namespace RNS;

// Derive a key of specified length using HKDF with SHA-256
Bytes RNS::Cryptography::hkdf(size_t output_length, const Bytes& input_material, const Bytes& optional_salt /*= {Bytes::NONE}*/, const Bytes& info_context /*= {Bytes::NONE}*/) {
    if (output_length <= 0) {
        throw std::invalid_argument("Invalid requested key length");
    }
    if (!input_material) {
        throw std::invalid_argument("Cannot derive key from empty source material");
    }

    HKDF<SHA256> hkdf_instance;

    if (optional_salt) {
        hkdf_instance.setKey(input_material.data(), input_material.size(), optional_salt.data(), optional_salt.size());
    } else {
        hkdf_instance.setKey(input_material.data(), input_material.size());
    }

    Bytes result_key;
    hkdf_instance.extract(result_key.writable(output_length), output_length);
    return result_key;
}

