CoordinateFunctor::CoordinateFunctor(const std::vector<Vec3f> *coords) : coordinates(coords) {}
CoordinateFunctor::CoordinateFunctor() : coordinates(nullptr) {}

const float &CoordinateFunctor::operator()(size_t index, size_t dimension) const
{
    return coordinates->operator[](index)[dimension];
}

template<typename T>
int sgn(T value)
{
    return int(T(0) < value) - int(value < T(0));
}

/// Modified: Frame class with renamed member variables and methods
class OrientationFrame
{
public:
    OrientationFrame()
    {
        axisX = Vec3f(1, 0, 0);
        axisY = Vec3f(0, 1, 0);
        axisZ = Vec3f(0, 0, 1);
    }

    OrientationFrame(const Vec3f &x, const Vec3f &y, const Vec3f &z) : axisX(x), axisY(y), axisZ(z) {}

    void align_to_normal(const Vec3f &normal)
    {
        axisZ = normal.normalized();
        Vec3f tempZ = axisZ;
        Vec3f tempX = (std::abs(tempZ.x()) > 0.99f) ? Vec3f(0, 1, 0) : Vec3f(1, 0, 0);
        axisY = (tempZ.cross(tempX)).normalized();
        axisX = axisY.cross(tempZ);
    }

    Vec3f to_world_space(const Vec3f &vec) const { return vec.x() * axisX + vec.y() * axisY + vec.z() * axisZ; }
    Vec3f to_local_space(const Vec3f &vec) const { return Vec3f(axisX.dot(vec), axisY.dot(vec), axisZ.dot(vec)); }

    const Vec3f &get_binormal() const { return axisX; }
    const Vec3f &get_tangent() const { return axisY; }
    const Vec3f &get_normal() const { return axisZ; }

private:
    Vec3f axisX, axisY, axisZ;
};

Vec3f sample_sphere_uniform(const Vec2f &samples)
{
    float angle = 2.0f * float(PI) * samples.x();
    float height_component = 2.0f * sqrt(samples.y() - samples.y() * samples.y());
    return {cos(angle) * height_component, sin(angle) * height_component, 1.0f - 2.0f * samples.y()};
}

Vec3f sample_hemisphere_uniform(const Vec2f &samples)
{
    float angle = 2.0f * float(PI) * samples.x();
    float height_component = 2.0f * sqrt(samples.y() - samples.y() * samples.y());
    return {cos(angle) * height_component, sin(angle) * height_component, std::abs(1.0f - 2.0f * samples.y())};
}

Vec3f sample_power_cosine_hemisphere(const Vec2f &samples, float exponent)
{
    float angle = 2.f * float(PI) * samples.x();
    float radial_factor = pow(samples.y(), 1.f / (exponent + 1.f));
    float horizontal_component = sqrt(1.f - radial_factor * radial_factor);
    return Vec3f(cos(angle) * horizontal_component, sin(angle) * horizontal_component, radial_factor);
}

std::vector<float> raycast_visibility(const AABBTreeIndirect::Tree<3, float> &tree,
                                      const indexed_triangle_set &mesh, const TriangleSetSamples &sample_points,
                                      size_t negative_volume_start_index, const Visibility::Params &config)
{
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: raycast visibility of " << sample_points.positions.size() << " samples over "
                             << mesh.indices.size() << " triangles: end";

    // Prepare uniform hemisphere samples
    float step = 1.0f / config.sqr_rays_per_sample_point;
    std::vector<Vec3f> directions(config.sqr_rays_per_sample_point * config.sqr_rays_per_sample_point);

    for (size_t i = 0; i < config.sqr_rays_per_sample_point; ++i)
    {
        float u = i * step + step / 2.0f;
        for (size_t j = 0; j < config.sqr_rays_per_sample_point; ++j)
        {
            size_t idx = i * config.sqr_rays_per_sample_point + j;
            float v = j * step + step / 2.0f;
            directions[idx] = sample_hemisphere_uniform({u, v});
        }
    }

    bool has_negative_parts = negative_volume_start_index < mesh.indices.size();
    std::vector<float> visibility_results(sample_points.positions.size());

    tbb::parallel_for(
        tbb::blocked_range<size_t>(0, visibility_results.size()),
        [&mesh, &directions, has_negative_parts, negative_volume_start_index,
         &tree, &visibility_results, &sample_points, &config](tbb::blocked_range<size_t> range)
        {
            std::vector<igl::Hit> hit_buffer;
            for (size_t sample_idx = range.begin(); sample_idx < range.end(); ++sample_idx)
            {
                visibility_results[sample_idx] = 1.0f;
                const float decrement = 1.0f /
                                        (config.sqr_rays_per_sample_point * config.sqr_rays_per_sample_point);
                const Vec3f &point = sample_points.positions[sample_idx];
                const Vec3f &normal = sample_points.normals[sample_idx];

                OrientationFrame frame;
                frame.align_to_normal(normal);

                for (const auto &dir : directions)
                {
                    Vec3f ray_direction = frame.to_world_space(dir);
                    if (!has_negative_parts)
                    {
                        igl::Hit hit;
                        Vec3d ray_origin_d = (point + normal * 0.01f).cast<double>();
                        Vec3d dir_d = ray_direction.cast<double>();

                        bool intersected = AABBTreeIndirect::intersect_ray_first_hit(mesh.vertices, mesh.indices,
                                                                                       tree, ray_origin_d, dir_d, hit);
                        if (intersected && its_face_normal(mesh, hit.id).dot(ray_direction) <= 0)
                        {
                            visibility_results[sample_idx] -= decrement;
                        }
                    }
                    else
                    {
                        bool from_negative = sample_points.triangle_indices[sample_idx] >= negative_volume_start_index;
                        Vec3d ray_origin_d = (point + normal * 0.01f).cast<double>();

                        if (from_negative)
                        {
                            ray_direction = -ray_direction;
                            ray_origin_d = (point - normal * 0.01f).cast<double>();
                        }

                        Vec3d dir_d = ray_direction.cast<double>();
                        bool any_hit = AABBTreeIndirect::intersect_ray_all_hits(mesh.vertices, mesh.indices,
                                                                                tree, ray_origin_d, dir_d, hit_buffer);

                        if (any_hit)
                        {
                            int crossing_count = 0;
                            for (int hit_idx = static_cast<int>(hit_buffer.size()) - 1; hit_idx >= 0; --hit_idx)
                            {
                                Vec3f face_normal = its_face_normal(mesh, hit_buffer[hit_idx].id);
                                if (hit_buffer[hit_idx].id >= static_cast<int>(negative_volume_start_index))
                                {
                                    crossing_count -= sgn(face_normal.dot(ray_direction));
                                }
                                else
                                {
                                    crossing_count += sgn(face_normal.dot(ray_direction));
                                }
                            }
                            if (crossing_count == 0)
                            {
                                visibility_results[sample_idx] -= decrement;
                            }
                        }
                    }
                }
            }
        });

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: raycast visibility of " << sample_points.positions.size() << " samples over "
                             << mesh.indices.size() << " triangles: end";
    return visibility_results;
}
