Visibility::Visibility(const Transform3d &object_transform, const ModelVolumePtrs &volumes, const Params &settings,
                       const std::function<void(void)> &cancel_callback)
{
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: gather occlusion meshes: start";

    indexed_triangle_set positive_mesh;
    indexed_triangle_set negative_mesh;

    for (const ModelVolume *vol : volumes)
    {
        if (vol->type() == ModelVolumeType::MODEL_PART ||
            vol->type() == ModelVolumeType::NEGATIVE_VOLUME)
        {
            auto transform = vol->get_matrix();
            indexed_triangle_set vol_its = vol->mesh().its;
            its_transform(vol_its, transform);

            if (vol->type() == ModelVolumeType::MODEL_PART)
            {
                its_merge(positive_mesh, vol_its);
            }
            else
            {
                its_merge(negative_mesh, vol_its);
            }
        }
    }

    cancel_callback();
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: gather occlusion meshes: end";

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: decimate: start";
    its_short_edge_collpase(positive_mesh, settings.fast_decimation_triangle_count_target);
    its_short_edge_collpase(negative_mesh, settings.fast_decimation_triangle_count_target);

    size_t neg_start_idx = positive_mesh.indices.size();
    its_merge(positive_mesh, negative_mesh);
    its_transform(positive_mesh, object_transform);

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: decimate: end";

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: Compute visibility sample points: start";
    this->mesh_samples = sample_its_uniform_parallel(settings.raycasting_visibility_samples_count, positive_mesh);
    this->mesh_samples_coordinate_functor = Impl::CoordinateFunctor(&this->mesh_samples.positions);
    this->mesh_samples_tree = KDTreeIndirect<3, float, Impl::CoordinateFunctor>(
        this->mesh_samples_coordinate_functor, this->mesh_samples.positions.size());

    // Compute search radius using exponential distribution approximation
    float prob = 0.9f;
    float target_samples = 4;
    float density = settings.raycasting_visibility_samples_count / this->mesh_samples.total_area;
    float area = target_samples / (-logf(prob) * density);
    float radius = sqrt(area / PI);
    this->mesh_samples_radius = radius;

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: Compute visiblity sample points: end";
    cancel_callback();
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: Mesh sample raidus: " << this->mesh_samples_radius;

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: build AABB tree: start";
    auto aabb_tree = AABBTreeIndirect::build_aabb_tree_over_indexed_triangle_set(positive_mesh.vertices,
                                                                                  positive_mesh.indices);
    cancel_callback();
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: build AABB tree: end";

    this->mesh_samples_visibility = Impl::raycast_visibility(aabb_tree, positive_mesh, this->mesh_samples,
                                                             neg_start_idx, settings);
    cancel_callback();
}

float Visibility::calculate_point_visibility(const Vec3f &query_point) const
{
    std::vector<size_t> nearby_indices = find_nearby_points(mesh_samples_tree, query_point, mesh_samples_radius);
    if (nearby_indices.empty())
    {
        return 1.0f;
    }

    auto distance_to_plane = [](const Vec3f &pt, const Vec3f &origin, const Vec3f &norm)
    {
        Vec3f vector = pt - origin;
        return std::abs(vector.dot(norm));
    };

    float weighted_sum = 0.0f;
    float weight_total = 0.0f;

    for (size_t i = 0; i < nearby_indices.size(); ++i)
    {
        size_t idx = nearby_indices[i];
        Vec3f sample_pos = this->mesh_samples.positions[idx];
        Vec3f sample_norm = this->mesh_samples.normals[idx];

        float dist = distance_to_plane(query_point, sample_pos, sample_norm);
        float w1 = mesh_samples_radius - dist;
        float w2 = mesh_samples_radius - (query_point - sample_pos).norm();
        float weight = w1 + w2;

        weighted_sum += weight * mesh_samples_visibility[idx];
        weight_total += weight;
    }

    return weighted_sum / weight_total;
}

