// Optimized template functions for string substitution (designed for performance and compactness)
template <class TStringType, class TTo, bool Main>
static Y_FORCE_INLINE void ShiftBlock(typename TStringType::value_type* buffer, size_t& readIdx, size_t& writeIdx, const size_t offset, const TTo replacement, const size_t replLen) {
    const size_t prefixLength = offset - readIdx;
    if (writeIdx < readIdx) {
        for (size_t k = 0; k < prefixLength; ++k) {
            buffer[writeIdx++] = buffer[readIdx++];
        }
    } else {
        writeIdx += prefixLength;
        readIdx += prefixLength;
    }
    if (Main) {
        for (size_t k = 0; k < replLen; ++k) {
            buffer[writeIdx++] = replacement[k];
        }
    }
}

template <typename T1, typename T2>
static bool Overlaps(const T1& first, const T2& second) noexcept {
    if (second.data() < first.data()) {
        return Overlaps(second, first);
    }
    return !first.empty() && !second.empty() &&
           ((first.data() <= second.data() && second.data() < first.data() + first.length()) ||
            (first.data() < second.data() + second.length() && second.data() + second.length() <= first.data() + first.length()));
}

/**
 * Performs global substring replacement in a string.
 * Implements two strategies: one for growing strings (append to new buffer),
 * another for shrinking or same-size replacements (in-place modification).
 * See IGNIETFERRO-394
 **/
template <class TStringType, typename TStringViewType = TBasicStringBuf<typename TStringType::value_type>>
static inline size_t ReplaceAllImpl(TStringType& str, const TStringViewType pattern, const TStringViewType replacement, size_t startPos = 0) {
    if (pattern.empty()) {
        return 0;
    }
    Y_ASSERT(!Overlaps(str, pattern));
    Y_ASSERT(!Overlaps(str, replacement));

    const size_t patternLen = pattern.size();
    const size_t replaceLen = replacement.size();
    size_t count = 0;
    size_t scanPos = startPos;
    size_t srcIndex = 0;

    if (replaceLen > patternLen) {
        // String will expand: build result in a new buffer
        TStringType output;
        for (; (scanPos = TStringViewType(str).find(pattern, scanPos)) != TStringType::npos; scanPos += patternLen) {
            if (!count) {
                // First match found — preallocate extra space
                output.reserve(str.size() + str.size() / 3);
            }
            output.append(str.begin() + srcIndex, str.begin() + scanPos);
            output.append(replacement.data(), replacement.size());
            srcIndex = scanPos + patternLen;
            ++count;
        }
        if (count) {
            // Append remaining suffix
            output.append(str.begin() + srcIndex, str.end());
            str = std::move(output);
        }
        return count;
    }

    // In-place substitution: no expansion needed
    size_t destIndex = 0;
    typename TStringType::value_type* dataPtr = &*str.begin();
    for (; (scanPos = TStringViewType(str).find(pattern, scanPos)) != TStringType::npos; scanPos += patternLen) {
        Y_ASSERT(destIndex <= srcIndex);
        ShiftBlock<TStringType, TStringViewType, true>(dataPtr, srcIndex, destIndex, scanPos, replacement, replaceLen);
        srcIndex = scanPos + patternLen;
        ++count;
    }
    if (count) {
        // Copy trailing characters
        ShiftBlock<TStringType, TStringViewType, false>(dataPtr, srcIndex, destIndex, str.size(), replacement, replaceLen);
        str.resize(destIndex);
    }
    return count;
}

/// Replaces all occurrences of character 'from' with 'to' starting at position 'fromPos'.
template <class TStringType>
inline size_t ReplaceCharAllImpl(TStringType& str, typename TStringType::value_type fromChar, typename TStringType::value_type toChar, size_t startPos = 0) {
    if (startPos >= str.size()) {
        return 0;
    }
    size_t modifiedCount = 0;
    startPos = str.find(fromChar, startPos);

    if (startPos != TStringType::npos) {
        auto* cursor = &*str.begin() + startPos;
        *cursor = toChar;
        ++modifiedCount;

        const auto* const endPtr = &*str.end();
        // Process aligned chunks first for better performance
        for (const auto* const unrollEnd = endPtr - (endPtr - cursor) % 4; cursor < unrollEnd;) {
            if (*cursor == fromChar) {
                *cursor = toChar;
                ++modifiedCount;
            }
            ++cursor;
            if (*cursor == fromChar) {
                *cursor = toChar;
                ++modifiedCount;
            }
            ++cursor;
            if (*cursor == fromChar) {
                *cursor = toChar;
                ++modifiedCount;
            }
            ++cursor;
            if (*cursor == fromChar) {
                *cursor = toChar;
                ++modifiedCount;
            }
            ++cursor;
        }
        // Handle remaining characters
        for (; cursor < endPtr; ++cursor) {
            if (*cursor == fromChar) {
                *cursor = toChar;
                ++modifiedCount;
            }
        }
    }
    return modifiedCount;
}

/* Standard guarantees that `char16_t` is distinct but has same size, signedness, and alignment as
 * `std::uint_least16_t`. We verify compatibility between `wchar16` and `char16_t`, and similarly for `wchar32`.
 */
static_assert(sizeof(wchar16) == sizeof(char16_t), "");
static_assert(sizeof(wchar32) == sizeof(char32_t), "");
static_assert(std::is_unsigned<wchar16>::value == std::is_unsigned<char16_t>::value, "");
static_assert(std::is_unsigned<wchar32>::value == std::is_unsigned<char32_t>::value, "");

size_t ReplaceAll(TCowString& text, const TStringBuf what, const TStringBuf with, size_t from) {
    return ReplaceAllImpl(text, what, with, from);
}

size_t ReplaceAll(TUtf16CowString& text, const TWtringBuf what, const TWtringBuf with, size_t from) {
    return ReplaceAllImpl(text, what, with, from);
}

size_t ReplaceAll(TUtf32CowString& text, const TUtf32StringBuf what, const TUtf32StringBuf with, size_t from) {
    return ReplaceAllImpl(text, what, with, from);
}

size_t ReplaceAll(TCowString& text, char what, char with, size_t from) {
    return ReplaceCharAllImpl(text, what, with, from);
}

size_t ReplaceAll(TUtf16CowString& text, wchar16 what, wchar16 with, size_t from) {
    return ReplaceCharAllImpl(text, static_cast<char16_t>(what), static_cast<char16_t>(with), from);
}

size_t ReplaceAll(TUtf32CowString& text, wchar32 what, wchar32 with, size_t from) {
    return ReplaceCharAllImpl(text, static_cast<char32_t>(what), static_cast<char32_t>(with), from);
}

