bool
scope_filter::operator()(std::string_view _input) const
{
    if(mode == FILTER_INCLUDE)
        return (pattern.empty())
                   ? true
                   : std::regex_search(_input.data(), std::regex{ pattern });
    else if(mode == FILTER_EXCLUDE)
        return (pattern.empty())
                   ? false
                   : !std::regex_search(_input.data(), std::regex{ pattern });
    throw exception<std::runtime_error>{ "invalid scope filter mode" };
}
