bool SettingsRequestHandler::TryHandleStaticRequest(
    const HttpRequest& request,
    const std::string& pathOnly,
    HttpResponse& response) {

    if (request.method != "GET") {
        return false;
    }

    if (pathOnly == "/favicon.ico") {
        response.statusCode = 204;
        response.contentType = "text/plain; charset=utf-8";
        response.body.clear();
        return true;
    }

    std::string webPath = request.path;
    if (IsHtmlPath(pathOnly, route_)) {
        webPath = "/index.html";
    }

    WebUiAsset asset;
    if (!TryLoadWebUiAsset(webUiBaseDirs_, webPath, &asset)) {
        return false;
    }

    response.statusCode = 200;
    response.contentType = asset.contentType;
    response.body.assign(reinterpret_cast<const char*>(asset.bytes.data()), asset.bytes.size());
    return true;
}

