    status = attributeAffects(mCycleTypeAttr, mOutLocatorPosScaleArrayAttr);
    status = attributeAffects(mCycleTypeAttr, mOutPointArrayAttr);

    MGlobal::executeCommand( UICodeMELScriptStr );
    return status;
