// Check if the given vertex factory type is supported for lightmap ray tracing
bool IsVertexFactorySupported(const FVertexFactoryType* FactoryType)
{
	static FName LocalVFName = FName(TEXT("FLocalVertexFactory"), FNAME_Find);
	static FName InstancedVFName = FName(TEXT("FInstancedStaticMeshVertexFactory"), FNAME_Find);
	static FName LandscapeVFName = FName(TEXT("FLandscapeVertexFactory"), FNAME_Find);
	static FName FixedGridVFName = FName(TEXT("FLandscapeFixedGridVertexFactory"), FNAME_Find);
	static FName XYOffsetVFName = FName(TEXT("FLandscapeXYOffsetVertexFactory"), FNAME_Find);

	return FactoryType == FindVertexFactoryType(LocalVFName)
		|| FactoryType == FindVertexFactoryType(InstancedVFName)
		|| FactoryType == FindVertexFactoryType(LandscapeVFName)
		|| FactoryType == FindVertexFactoryType(FixedGridVFName)
		|| FactoryType == FindVertexFactoryType(XYOffsetVFName);
}

