// Template closest-hit shader with optional any-hit support
template<bool EnableAnyHit>
class TLightmapMaterialCHS : public FLightmapMaterialCHS
{
	DECLARE_SHADER_TYPE(TLightmapMaterialCHS, MeshMaterial);
public:
	TLightmapMaterialCHS(const FMeshMaterialShaderType::CompiledShaderInitializerType& InitData)
		: FLightmapMaterialCHS(InitData)
	{}
	TLightmapMaterialCHS() {}

	static bool ShouldCompilePermutation(const FMeshMaterialShaderPermutationParameters& Params)
	{
		return IsVertexFactorySupported(Params.VertexFactoryType)
			&& ((Params.MaterialParameters.bIsMasked || Params.MaterialParameters.BlendMode == BLEND_Translucent) == EnableAnyHit)
			&& FNoLightMapPolicy::ShouldCompilePermutation(Params)
			&& ShouldCompileRayTracingShadersForProject(Params.Platform);
	}

	static void ModifyCompilationEnvironment(const FMaterialShaderPermutationParameters& Params, FShaderCompilerEnvironment& Env)
	{
		Env.SetDefine(TEXT("USE_MATERIAL_CLOSEST_HIT_SHADER"), 1);
		Env.SetDefine(TEXT("USE_MATERIAL_ANY_HIT_SHADER"), 1);
		Env.SetDefine(TEXT("USE_RAYTRACED_TEXTURE_RAYCONE_LOD"), 0);
		Env.SetDefine(TEXT("SCENE_TEXTURES_DISABLED"), 1);
		Env.SetDefine(TEXT("SIMPLIFIED_MATERIAL_SHADER"), 1);
		FNoLightMapPolicy::ModifyCompilationEnvironment(Params, Env);
		FMeshMaterialShader::ModifyCompilationEnvironment(Params, Env);
	}

	static bool ValidateCompiledResult(EShaderPlatform Platform, const FShaderParameterMap& ParamMap, TArray<FString>& OutErrors)
	{
		if (ParamMap.ContainsParameterAllocation(FSceneTextureUniformParameters::StaticStructMetadata.GetShaderVariableName()))
		{
			OutErrors.Add(TEXT("Ray tracing closest hit shaders cannot read from the SceneTexturesStruct."));
			return false;
		}

		for (const auto& It : ParamMap.GetParameterMap())
		{
			const FParameterAllocation& Alloc = It.Value;
			if (Alloc.Type != EShaderParameterType::UniformBuffer
				&& Alloc.Type != EShaderParameterType::LooseData)
			{
				OutErrors.Add(FString::Printf(TEXT("Invalid ray tracing shader parameter '%s'. Only uniform buffers and loose data parameters are supported."), *(It.Key)));
				return false;
			}
		}
		return true;
	}
};

