// Helper function to select appropriate hit shader based on material properties
static TShaderRef<FLightmapMaterialCHS> AcquireLightmapHitShader(const FMaterial& RESTRICT MaterialRes, const FVertexFactory* Factory)
{
	if (MaterialRes.IsMasked() || MaterialRes.GetBlendMode() == BLEND_Translucent)
	{
		return MaterialRes.GetShader<TLightmapMaterialCHS<true>>(Factory->GetType());
	}
	else
	{
		return MaterialRes.GetShader<TLightmapMaterialCHS<false>>(Factory->GetType());
	}
}

// Process mesh batch for lightmap ray tracing
void FLightmapRayTracingMeshProcessor::Process(
	const FMeshBatch& RESTRICT MeshBatch,
	uint64 ElementMask,
	const FPrimitiveSceneProxy* RESTRICT PrimitiveProxy,
	const FMaterialRenderProxy& RESTRICT MaterialProxy,
	const FMaterial& RESTRICT MaterialRes,
	FMaterialShadingModelField ShadingModels,
	const FUniformLightMapPolicy& RESTRICT LightMapPolicy,
	const typename FUniformLightMapPolicy::ElementDataType& RESTRICT LightMapElementData)
{
	const FVertexFactory* Factory = MeshBatch.VertexFactory;

	TMeshProcessorShaders<
		FMeshMaterialShader,
		FMeshMaterialShader,
		FMeshMaterialShader,
		FMeshMaterialShader,
		FMeshMaterialShader,
		FLightmapMaterialCHS> RayTracingShaders;

	RayTracingShaders.RayHitGroupShader = AcquireLightmapHitShader(MaterialRes, Factory);

	PassDrawRenderState.SetBlendState(TStaticBlendState<CW_RGBA, BO_Add, BF_One, BF_One, BO_Add, BF_Zero, BF_One>::GetRHI());
	PassDrawRenderState.SetDepthStencilState(TStaticDepthStencilState<false, CF_DepthNearOrEqual>::GetRHI());

	TBasePassShaderElementData<FUniformLightMapPolicy> ShaderData(LightMapElementData);
	ShaderData.InitializeMeshMaterialData(ViewIfDynamicMeshCommand, PrimitiveProxy, MeshBatch, -1, true);

	BuildRayTracingMeshCommands(
		MeshBatch,
		ElementMask,
		PrimitiveProxy,
		MaterialProxy,
		MaterialRes,
		PassDrawRenderState,
		RayTracingShaders,
		ShaderData);
}
