#define max(a, b) (((a) > (b)) ? (a) : (b))
PeakFinder::PeakFinder()
{
    minPosition = maxPosition = 0;
}
// Locates the 'baseline' of a peak bump by starting from 'peakIndex' and moving
// in the direction specified by 'step' until the next 'bump' after the minimum value 
// starts rising again
int PeakFinder::findGround(const float *signal, int peakIndex, int step) const
{
    float referenceValue;
    int lowIndex;
    int currentIndex;
    int climbCounter;
    float change;
    climbCounter = 0;
    referenceValue = signal[peakIndex];
    lowIndex = peakIndex;
    currentIndex = peakIndex;
    while ((currentIndex > minPosition) && (currentIndex < maxPosition))
    {
        int previousIndex;
        previousIndex = currentIndex;
        currentIndex += step;
        // compute derivative
        change = signal[currentIndex] - signal[previousIndex];
        if (change <= 0)
        {
            // descending, acceptable
            if (climbCounter)
            {
                climbCounter --;  // decrement climb counter
            }
            // check for new minimum
            if (signal[currentIndex] < referenceValue)
            {
                // new minimum located
                lowIndex = currentIndex;
                referenceValue = signal[currentIndex];
            }
        }
        else
        {
            // ascending, increment climb counter
            climbCounter ++;
            if (climbCounter > 5) break;    // prolonged ascent indicates next upward slope => exit
        }
    }
    return lowIndex;
}
// Determines the index where the signal crosses the specified threshold, starting from 'peakIndex' and
// moving in the direction indicated by 'step'
int PeakFinder::findCrossingLevel(const float *signal, float threshold, int peakIndex, int step) const
{
    float peakMagnitude;
    int currentIndex;
    peakMagnitude = signal[peakIndex];
    assert(peakMagnitude >= threshold);
    currentIndex = peakIndex;
    while ((currentIndex >= minPosition) && (currentIndex < maxPosition))
    {
        if (signal[currentIndex + step] < threshold) return currentIndex;   // threshold crossing detected
        currentIndex += step;
    }
    return -1;  // no crossing found
}
// Computes the center of mass position of 'signal' array elements between 'startIdx' and 'endIdx'
double PeakFinder::calcMassCenter(const float *signal, int startIdx, int endIdx) const
{
    int idx;
    float totalWeight;
    float weightedSum;
    totalWeight = 0;
    weightedSum = 0;
    for (idx = startIdx; idx <= endIdx; idx ++)
    {
        weightedSum += (float)idx * signal[idx];
        totalWeight += signal[idx];
    }
    if (totalWeight < 1e-6) return 0;
    return weightedSum / totalWeight;
}
/// Determine precise center of peak near given position by analyzing local mass distribution
double PeakFinder::getPeakCenter(const float *signal, int peakIndex) const
{
    float peakMagnitude;            // peak amplitude
    int crossIdx1, crossIdx2;       // indices where the peak 'bump' intersects the cutting level
    float cutThreshold;             // threshold value
    float baselineMagnitude;        // baseline amplitude of the peak
    int gp1, gp2;                   // bottom positions of the peak 'bump'
    // locate baseline positions.
    gp1 = findGround(signal, peakIndex, -1);
    gp2 = findGround(signal, peakIndex, 1);
    baselineMagnitude = max(signal[gp1], signal[gp2]);
    peakMagnitude = signal[peakIndex];
    if (baselineMagnitude < 1e-6) return 0;                // baseline too weak => detection failed
    if ((peakMagnitude / baselineMagnitude) < 1.3) return 0;   // peak less than 30% above baseline => insufficient peak
    // compute 70%-level of the peak
    cutThreshold = 0.70f * peakMagnitude + 0.30f * baselineMagnitude;
    // locate mid-level crossings
    crossIdx1 = findCrossingLevel(signal, cutThreshold, peakIndex, -1);
    crossIdx2 = findCrossingLevel(signal, cutThreshold, peakIndex, 1);
    if ((crossIdx1 < 0) || (crossIdx2 < 0)) return 0;   // no crossing => not a valid peak
    // compute mass center around the peak region
    return calcMassCenter(signal, crossIdx1, crossIdx2);
}
double PeakFinder::detectPeak(const float *signal, int aminPos, int amaxPos) 
{
    int i;
    int peakIndex;              // index of maximum amplitude
    double highPeak, currentPeak;
    this->minPosition = aminPos;
    this->maxPosition = amaxPos;
    // find global maximum
    peakIndex = minPosition;
    currentPeak = signal[minPosition];
    for (i = minPosition + 1; i < maxPosition; i ++)
    {
        if (signal[i] > currentPeak) 
        {
            currentPeak = signal[i];
            peakIndex = i;
        }
    }

    // Compute refined location using center-of-mass method for strongest peak
    highPeak = getPeakCenter(signal, peakIndex);
    currentPeak = highPeak;
    // Verify whether the strongest peak might be a harmonic of the true fundamental beat peak 
    // - occasionally the highest peak could be the Nth harmonic of the actual base peak yet 
    // only marginally larger than the true fundamental
    for (i = 2; i < 10; i ++)
    {
        double candidatePeak, tempVal;
        int i1,i2;
        peakIndex = (int)(highPeak / (double)i + 0.5f);
        if (peakIndex < minPosition) break;
        // compute center-of-mass of potential fundamental peak
        candidatePeak = getPeakCenter(signal, peakIndex);
        // compare with currently highest detected peak
        i1 = (int)(highPeak + 0.5);
        i2 = (int)(candidatePeak + 0.5);
        tempVal = 2 * (signal[i2] - signal[i1]) / (signal[i2] + signal[i1]);
        if (fabs(tempVal) < 0.1)
        {
            // The highest peak is a harmonic of nearly equal magnitude fundamental peak,
            // thus prefer the fundamental peak instead
            currentPeak = candidatePeak;
        }
    }
    return currentPeak;
}

