//! @cond Doxygen_Suppress
static TransformationNNPtr _createMolodensky(
    const util::PropertyMap &properties, const crs::CRSNNPtr &sourceCRSIn,
    const crs

#include <stdlib.h>
#include <stdint.h>
#include "lock.h"
#include "fork_impl.h"

/*
 * This implementation uses a modified lagged Fibonacci generator,
 * similar to the original BSD random function, but with improved seeding.
 */
static uint32_t seed_table[] = {
    0x00000000,0x5851f42d,0xc0b18ccf,0xcbb5f646,
    0xc7033129,0x30705b04,0x20fd5db4,0x9a8b7f78,
    0x502959d8,0xab894868,0x6c0356a7,0x88cdb7ff,
    0xb477d43f,0x70a3a52b,0xa8e4baf1,0xfd8341fc,
    0x8ae16fd9,0x742d2f7a,0x0d1f0796,0x76035e09,
    0x40f7702c,0x6fa72ca5,0xaaa84157,0x58a0df74,
    0xc74a0364,0xae533cc4,0x04185faf,0x6de3b115,
    0x0cab8628,0xf043bfa4,0x398150e9,0x37521657};

static int state_size = 31;
static int index_i = 3;
static int index_j = 0;
static uint32_t *state_ptr = seed_table + 1;
static volatile int mutex[1];
volatile int *const __random_mutex_ptr = mutex;

// Linear congruential generator for 32-bit values
static uint32_t lcg32(uint32_t val) {
    return (1103515245 * val + 12345) & 0x7fffffff;
}

// Linear congruential generator for 64-bit values
static uint64_t lcg64(uint64_t val) {
    return 6364136223846793005ull * val + 1;
}

// Save current generator state
static void *save_state() {
    state_ptr[-1] = (state_size << 16) | (index_i << 8) | index_j;
    return state_ptr - 1;
}

// Restore generator state from saved buffer
static void restore_state(uint32_t *buffer) {
    state_ptr = buffer + 1;
    state_size = buffer[0] >> 16;
    index_i = (buffer[0] >> 8) & 0xff;
    index_j = buffer[0] & 0xff;
}

// Internal random seed initialization
static void __srandom_internal(unsigned seed_value) {
    int k;
    uint64_t s = seed_value;

    if (state_size == 0) {
        state_ptr[0] = s;
        return;
    }

    index_i = (state_size == 31 || state_size == 7) ? 3 : 1;
    index_j = 0;

    for (k = 0; k < state_size; k++) {
        s = lcg64(s);
        state_ptr[k] = s >> 32;
    }

    // Ensure at least one odd number in state
    state_ptr[0] |= 1;
}

// Public function to set random seed
void srandom(unsigned seed_value) {
    LOCK(mutex);
    __srandom_internal(seed_value);
    UNLOCK(mutex);
}

// Set up new random state buffer
char *initstate(unsigned seed_value, char *buffer, size_t buf_size) {
    void *previous_state;

    if (buf_size < 8)
        return 0;

    LOCK(mutex);
    previous_state = save_state();

    if (buf_size < 32)
        state_size = 0;
    else if (buf_size < 64)
        state_size = 7;
    else if (buf_size < 128)
        state_size = 15;
    else if (buf_size < 256)
        state_size = 31;
    else
        state_size = 63;

    state_ptr = (uint32_t*)buffer + 1;
    __srandom_internal(seed_value);
    save_state();
    UNLOCK(mutex);

    return (char*)previous_state;
}

// Switch to new random state buffer
char *setstate(char *buffer) {
    void *previous_state;

    LOCK(mutex);
    previous_state = save_state();
    restore_state((uint32_t*)buffer);
    UNLOCK(mutex);

    return (char*)previous_state;
}

// Generate next random number
long random(void) {
    long result;

    LOCK(mutex);

    if (state_size == 0) {
        result = state_ptr[0] = lcg32(state_ptr[0]);
        goto cleanup;
    }

    state_ptr[index_i] += state_ptr[index_j];
    result = state_ptr[index_i] >> 1;

    if (++index_i == state_size)
        index_i = 0;
    if (++index_j == state_size)
        index_j = 0;

cleanup:
    UNLOCK(mutex);
    return result;
}

