extern BOOL PrepareDialogSpriteGraphic_SC2K1996(CGraphics *pGraphic, HWND hWnd, sprite_header_t *pSprHead, __int16 nSpriteID, CMFC3XRect *pDlgRect);
extern HWND hWndExt;

BOOL CALLBACK SpriteBrowserDialogProc(HWND hwndDlg, UINT message, WPARAM wParam, LPARAM lParam) {
	HWND hComboCtrl;
	CMFC3XRect rectBtn, rectDlg, rectPaint;
	__int16 nCurrentSpriteID;
	char szEntryBuffer[80 + 1];
	int nIdx;
	sprite_header_t *pHeader;
	PAINTSTRUCT ps;
	std::string strDisplay;
	int posX, posY;
	static __int16 nFirstSpriteID = -1;
	static CGraphics *pImgSmall = NULL;
	static CGraphics *pImgMedium = NULL;
	static CGraphics *pImgLarge = NULL;
	static BOOL bLoadFailSmall = FALSE;
	static BOOL bLoadFailMedium = FALSE;
	static BOOL bLoadFailLarge = FALSE;

	switch (message) {
		case WM_INITDIALOG:
			hComboCtrl = GetDlgItem(hwndDlg, IDC_SPRITEBROWSER_COMBOCTRL);
			GetWindowRect(hComboCtrl, &rectBtn);
			pImgSmall = new CGraphics();
			pImgMedium = new CGraphics();
			pImgLarge = new CGraphics();
			ComboBox_AddString(hComboCtrl, "(Select Sprite ID)");
			for (unsigned idx = 1; idx < SPRITE_ENTRY_COUNT; idx++) {
				ZeroMemory(szEntryBuffer, sizeof(szEntryBuffer));
				sprintf_s(szEntryBuffer, sizeof(szEntryBuffer) - 1, "%d - %s", idx, szSpriteNames[idx]);
				ComboBox_AddString(hComboCtrl, szEntryBuffer);
			}
			ComboBox_SetCurSel(hComboCtrl, 0);
			SetWindowPos(hComboCtrl, HWND_TOP, 0, 0, rectBtn.right - rectBtn.left, 200, SWP_NOZORDER | SWP_NOMOVE);
			CenterDialogBox(hwndDlg);
			return TRUE;

		case WM_PAINT:
			BeginPaint(hwndDlg, &ps);
			GetClientRect(hwndDlg, &rectDlg);
			rectPaint.left = 10;
			rectPaint.top = 160;
			rectPaint.bottom = 180;
			rectPaint.right = 180;
			SelectFont(ps.hdc, hFontMSSansSerifRegular8);
			SetTextAlign(ps.hdc, 8);
			SetBkColor(ps.hdc, colBtnFace);
			SetTextColor(ps.hdc, RGB(0, 0, 0));

			if (nFirstSpriteID > 0) {
				nCurrentSpriteID = nFirstSpriteID + SPRITE_SMALL_START;
				strDisplay = "Small Sprite: ";
				strDisplay += szInternalSpriteName[nCurrentSpriteID];
				strDisplay += " / ";
				strDisplay += std::to_string(nCurrentSpriteID);
				strDisplay += " (";
				strDisplay += HexPls(nCurrentSpriteID, 4);
				strDisplay += ")";
				if (bLoadFailSmall)
					strDisplay += " - Not found.";
				FillRect(ps.hdc, &rectPaint, (HBRUSH)MainBrushFace->m_hObject);
				ExtTextOutA(ps.hdc, rectPaint.left, rectPaint.top, ETO_OPAQUE, &rectPaint, strDisplay.c_str(), strDisplay.length(), 0);
				pHeader = &pArrSpriteHeaders[nCurrentSpriteID];
				if (pHeader) {
					posX = rectDlg.right - 40;
					posY = (rectDlg.bottom - pHeader->wHeight) - 20;
					if (pImgSmall && !bLoadFailSmall) {
						Game_Graphics_SetColorTableFromApplicationPalette(pImgSmall);
						Game_Graphics_Paint(pImgSmall, ps.hdc, posX, posY);
					}
				}

				nCurrentSpriteID = nFirstSpriteID + SPRITE_MEDIUM_START;
				strDisplay = "Medium Sprite: ";
				strDisplay += szInternalSpriteName[nCurrentSpriteID];
				strDisplay += " / ";
				strDisplay += std::to_string(nCurrentSpriteID);
				strDisplay += " (";
				strDisplay += HexPls(nCurrentSpriteID, 4);
				strDisplay += ")";
				if (bLoadFailMedium)
					strDisplay += " - Not found.";
				SetRect(&rectPaint, rectPaint.left, rectPaint.top + 40, rectPaint.right, rectPaint.bottom + 40);
				FillRect(ps.hdc, &rectPaint, (HBRUSH)MainBrushFace->m_hObject);
				ExtTextOutA(ps.hdc, rectPaint.left, rectPaint.top, ETO_OPAQUE, &rectPaint, strDisplay.c_str(), strDisplay.length(), 0);
				pHeader = &pArrSpriteHeaders[nCurrentSpriteID];
				if (pHeader) {
					posX -= (40 * 2);
					posY = (rectDlg.bottom - pHeader->wHeight) - 20;
					if (pImgMedium && !bLoadFailMedium) {
						Game_Graphics_SetColorTableFromApplicationPalette(pImgMedium);
						Game_Graphics_Paint(pImgMedium, ps.hdc, posX, posY);
					}
				}

				nCurrentSpriteID = nFirstSpriteID + SPRITE_LARGE_START;
				strDisplay = "Large Sprite: ";
				strDisplay += szInternalSpriteName[nCurrentSpriteID];
				strDisplay += " / ";
				strDisplay += std::to_string(nCurrentSpriteID);
				strDisplay += " (";
				strDisplay += HexPls(nCurrentSpriteID, 4);
				strDisplay += ")";
				if (bLoadFailLarge)
					strDisplay += " - Not found.";
				SetRect(&rectPaint, rectPaint.left, rectPaint.top + 40, rectPaint.right, rectPaint.bottom + 40);
				FillRect(ps.hdc, &rectPaint, (HBRUSH)MainBrushFace->m_hObject);
				ExtTextOutA(ps.hdc, rectPaint.left, rectPaint.top, ETO_OPAQUE, &rectPaint, strDisplay.c_str(), strDisplay.length(), 0);
				pHeader = &pArrSpriteHeaders[nCurrentSpriteID];
				if (pHeader) {
					posX -= (40 * 4);
					posY = (rectDlg.bottom - pHeader->wHeight) - 20;
					if (pImgLarge && !bLoadFailLarge) {
						Game_Graphics_SetColorTableFromApplicationPalette(pImgLarge);
						Game_Graphics_Paint(pImgLarge, ps.hdc, posX, posY);
					}
				}
			}
			EndPaint(hwndDlg, &ps);
			return FALSE;

		case WM_COMMAND:
			switch (GET_WM_COMMAND_ID(wParam, lParam)) {
				case IDC_SPRITEBROWSER_COMBOCTRL:
					if (GET_WM_COMMAND_CMD(wParam, lParam) == CBN_KILLFOCUS ||
						GET_WM_COMMAND_CMD(wParam, lParam) == CBN_CLOSEUP ||
						GET_WM_COMMAND_CMD(wParam, lParam) == CBN_SELENDOK ||
						GET_WM_COMMAND_CMD(wParam, lParam) == CBN_SELENDCANCEL) {
						UpdateWindow(hwndDlg);
						if (!hWndExt)
							hWndExt = hwndDlg;
						return TRUE;
					}
					else if (GET_WM_COMMAND_CMD(wParam, lParam) == CBN_DROPDOWN) {
						hWndExt = 0;
					}
					return FALSE;

				case IDC_SPRITEBROWSER_SELBUT:
					if (GET_WM_COMMAND_CMD(wParam, lParam) == BN_CLICKED) {
						if (!hWndExt)
							hWndExt = hwndDlg;
						hComboCtrl = GetDlgItem(hwndDlg, IDC_SPRITEBROWSER_COMBOCTRL);
						ZeroMemory(szEntryBuffer, sizeof(szEntryBuffer));
						if (pImgSmall)
							pImgSmall->DeleteStored_SC2K1996();
						if (pImgMedium)
							pImgMedium->DeleteStored_SC2K1996();
						if (pImgLarge)
							pImgLarge->DeleteStored_SC2K1996();
						nFirstSpriteID = -1;
						nIdx = ComboBox_GetCurSel(hComboCtrl);
						if (nIdx > 0) {
							GetWindowRect(hwndDlg, &rectDlg);
							ScreenToClient(hwndDlg, (LPPOINT)&rectDlg);
							ScreenToClient(hwndDlg, (LPPOINT)&rectDlg.right);
							GetWindowText(hComboCtrl, szEntryBuffer, 5);
							nFirstSpriteID = atoi(szEntryBuffer);
							if (nFirstSpriteID > 0) {
								nCurrentSpriteID = nFirstSpriteID + SPRITE_SMALL_START;
								bLoadFailSmall = PrepareDialogSpriteGraphic_SC2K1996(pImgSmall, hwndDlg, &pArrSpriteHeaders[nCurrentSpriteID], nCurrentSpriteID, &rectDlg);
								nCurrentSpriteID = nFirstSpriteID + SPRITE_MEDIUM_START;
								bLoadFailMedium = PrepareDialogSpriteGraphic_SC2K1996(pImgMedium, hwndDlg, &pArrSpriteHeaders[nCurrentSpriteID], nCurrentSpriteID, &rectDlg);
								nCurrentSpriteID = nFirstSpriteID + SPRITE_LARGE_START;
								bLoadFailLarge = PrepareDialogSpriteGraphic_SC2K1996(pImgLarge, hwndDlg, &pArrSpriteHeaders[nCurrentSpriteID], nCurrentSpriteID, &rectDlg);
							}
						}
						InvalidateRect(hwndDlg, 0, TRUE);
						UpdateWindow(hwndDlg);
						return TRUE;
					}
					break;

				case IDOK:
					EndDialog(hwndDlg, 1);
					return TRUE;

				case IDCANCEL:
					EndDialog(hwndDlg, 0);
					return TRUE;
			}
			break;

		case WM_DESTROY:
			hWndExt = 0;
			if (pImgSmall) {
				pImgSmall->DeleteStored_SC2K1996();
				delete pImgSmall;
				pImgSmall = NULL;
			}
			if (pImgMedium) {
				pImgMedium->DeleteStored_SC2K1996();
				delete pImgMedium;
				pImgMedium = NULL;
			}
			if (pImgLarge) {
				pImgLarge->DeleteStored_SC2K1996();
				delete pImgLarge;
				pImgLarge = NULL;
			}
			nFirstSpriteID = -1;
			break;
	}
	return FALSE;
}

