WebSvcMgrCurl gWebSvcInstance;
WebSvcMgr &TheWebSvcMgr = gWebSvcInstance;

WebSvcMgrCurl::~WebSvcMgrCurl() {
    if (mMultiHandle) {
        MILO_ASSERT(CURLM_OK == curl_multi_cleanup(mMultiHandle), 0x28);
        mMultiHandle = nullptr;
    }
}

void WebSvcMgrCurl::Initialize() {
    WebSvcMgr::Initialize();
    InitializeCurl();
}

void WebSvcMgrCurl::Update() {
    WebSvcMgr::Update();
    MILO_ASSERT(mMultiHandle, 0xFE);
    int active_handles;
    if (curl_multi_perform(mMultiHandle, &active_handles) == CURLM_OK) {
        static int sLastActiveHandles;
        if (sLastActiveHandles != active_handles) {
            sLastActiveHandles = active_handles;
        }
        int pending_messages = 0;
        int max_iterations = 100;
        CURLMsg *message;
        while (message = curl_multi_info_read(mMultiHandle, &pending_messages), message) {
            if (message->msg == CURLMSG_DONE) {
                CURL *easy_handle = message->easy_handle;
                bool success_flag = false;
                unsigned int status_code = 0;
                MILO_ASSERT(easy_handle, 0x11D);
                if (message->data.result == 0
                    && curl_easy_getinfo(easy_handle, (CURLINFO)0x200002, &status_code) == 0
                    && status_code == 200) {
                    success_flag = true;
                }
                ProcessAndComplete(easy_handle, success_flag, status_code);
            }
            max_iterations--;
            if (max_iterations == 0)
                return;
        }
    }
}

bool WebSvcMgrCurl::ExecuteRequest(
    ReqType type,
    unsigned int ip_address,
    unsigned short port_number,
    const char *endpoint_url,
    const char *extra_headers,
    unsigned int timeout_ms,
    const char *payload,
    unsigned int payload_size
) {
    MILO_ASSERT(ip_address, 0x51);
    MILO_ASSERT(port_number, 0x52);
    WebSvcRequest request(endpoint_url, extra_headers, nullptr);
    SetupRequest(&request, type, ip_address, port_number, payload, payload_size);
    request.Start();
    request.SetTimeout(timeout_ms);
    request.Perform();
    return request.IsSuccessful();
}

bool WebSvcMgrCurl::SetupRequest(
    WebSvcRequest *req,
    ReqType req_type,
    unsigned int ip_addr,
    unsigned short port,
    const char *body_data,
    unsigned int body_length
) {
    MILO_ASSERT(ip_addr, 0x91);
    MILO_ASSERT(port, 0x92);
    MILO_ASSERT(req, 0x93);
    return SetupRequest(req, req_type, nullptr, ip_addr, port, body_data, body_length);
}

bool WebSvcMgrCurl::SetupRequest(
    WebSvcRequest *req,
    ReqType req_type,
    const char *hostname,
    unsigned short port,
    const char *body_data,
    unsigned int body_length
) {
    MILO_ASSERT(strlen(hostname), 0xA0);
    MILO_ASSERT(port, 0xA1);
    MILO_ASSERT(req, 0xA2);
    return SetupRequest(req, req_type, hostname, 0, port, body_data, body_length);
}

void WebSvcMgrCurl::Enqueue(WebSvcRequest *req) {
    WebSvcMgr::Enqueue(req);
    MILO_ASSERT(req->GetRequest(), 0x40);
    CURL *curl_req = req->GetRequest();
    MILO_ASSERT(CURLM_OK == curl_multi_add_handle(mMultiHandle, curl_req), 0x42);
}

void WebSvcMgrCurl::InitializeCurl() {
    mMultiHandle = curl_multi_init();
    MILO_ASSERT(mMultiHandle, 0x31);
}

bool WebSvcMgrCurl::SetupRequest(
    WebSvcRequest *req,
    ReqType req_type,
    const char *hostname,
    unsigned int ip_addr,
    unsigned short port,
    const char *body_data,
    unsigned int body_length
) {
    MILO_ASSERT(port, 0x6D);
    HttpReqCurl *curl_req;
    if (ip_addr != 0) {
        curl_req = new HttpReqCurl(req_type, ip_addr, port, req->GetBaseURL());
    } else {
        curl_req = new HttpReqCurl(req_type, hostname, port, req->GetBaseURL());
    }
    MILO_ASSERT(curl_req, 0x79);
    if (body_length != 0) {
        MILO_ASSERT(body_data != NULL && req_type == kHttpReqType_POST, 0x7E);
        curl_req->SetBody(body_data);
        curl_req->SetBodyLength(body_length);
    }
    curl_req->SetCookies(req->GetCookies());
    req->SetHttpReq(curl_req);
    return true;
}

