TArray<FSequencerTrackInstanceInput> USequencerTrackInstanceBP::GetInputs() const
{
	using namespace UE::MovieScene;
	TArray<FSequencerTrackInstanceInput> OutputArray;
	TArrayView<const FMovieSceneTrackInstanceInput> SourceInputs = Super::GetInputs();
	OutputArray.Reserve(SourceInputs.Num());

	for (const FMovieSceneTrackInstanceInput& CurrentInput : SourceInputs)
	{
		FSequencerTrackInstanceInput LocalInput;
		LocalInput.Section = CastChecked<USequencerSectionBP>(CurrentInput.Section);

		const FInstanceRegistry* Registry = GetLinker()->GetInstanceRegistry();
		if (ensure(Registry->IsHandleValid(CurrentInput.InstanceHandle)))
		{
			LocalInput.Context = Registry->GetInstance(CurrentInput.InstanceHandle).GetContext();
		}

		OutputArray.Add(LocalInput);
	}

	return OutputArray;
}

int32 USequencerTrackInstanceBP::GetNumInputs() const
{
	return GetInputs().Num();
}

FSequencerTrackInstanceInput USequencerTrackInstanceBP::GetInput(int32 Index) const
{
	using namespace UE::MovieScene;
	TArrayView<const FMovieSceneTrackInstanceInput> InputsView = Super::GetInputs();

	if (!InputsView.IsValidIndex(Index))
	{
		FFrame::KismetExecutionMessage(*FString::Printf(TEXT("Attempting to access input %d from an array of size %d."), Index, InputsView.Num()), ELogVerbosity::Error);
		return FSequencerTrackInstanceInput();
	}

	FMovieSceneTrackInstanceInput RawInput = InputsView[Index];
	FSequencerTrackInstanceInput Output;
	Output.Section = CastChecked<USequencerSectionBP>(RawInput.Section);

	const FInstanceRegistry* Registry = GetLinker()->GetInstanceRegistry();
	if (ensure(Registry->IsHandleValid(RawInput.InstanceHandle)))
	{
		Output.Context = Registry->GetInstance(RawInput.InstanceHandle).GetContext();
	}

	return Output;
}

void USequencerTrackInstanceBP::OnInputAdded(const FMovieSceneTrackInstanceInput& InInput)
{
	using namespace UE::MovieScene;
