popup_message_v3::query_t popup_message_v3::setupMessageBox(fb2k::hwnd_t owner, const char* content, const char* caption, unsigned styleFlags) {
    query_t q = {};
    q.title = caption;
    q.msg = content;
    q.wndParent = owner;

    switch (styleFlags & 0xF) {
    default:
    case MB_OK:
        q.buttons = buttonOK;
        q.defButton = buttonOK;
        break;
    case MB_OKCANCEL:
        q.buttons = buttonOK | buttonCancel;
        q.defButton = (styleFlags & MB_DEFBUTTON2) ? buttonCancel : buttonOK;
        break;
    case MB_ABORTRETRYIGNORE:
        q.buttons = buttonAbort | buttonRetry | buttonIgnore;
        if (styleFlags & MB_DEFBUTTON3) q.defButton = buttonIgnore;
        else if (styleFlags & MB_DEFBUTTON2) q.defButton = buttonRetry;
        else q.defButton = buttonAbort;
        break;
    case MB_YESNOCANCEL:
        q.buttons = buttonYes | buttonNo | buttonCancel;
        if (styleFlags & MB_DEFBUTTON3) q.defButton = buttonCancel;
        else if (styleFlags & MB_DEFBUTTON2) q.defButton = buttonNo;
        else q.defButton = buttonYes;
        break;
    case MB_YESNO:
        q.buttons = buttonYes | buttonNo;
        q.defButton = (styleFlags & MB_DEFBUTTON2) ? buttonNo : buttonYes;
        break;
    case MB_RETRYCANCEL:
        q.buttons = buttonRetry | buttonCancel;
        q.defButton = (styleFlags & MB_DEFBUTTON2) ? buttonCancel : buttonRetry;
        break;
    }

    switch (styleFlags & 0xF0) {
    case MB_ICONHAND:
        q.icon = iconError;
        break;
    case MB_ICONQUESTION:
        q.icon = iconQuestion;
        break;
    case MB_ICONEXCLAMATION:
        q.icon = iconWarning;
        break;
    case MB_ICONASTERISK:
        q.icon = iconInformation;
        break;
    }

    return q;
}

int popup_message_v3::messageBoxReply(uint32_t result) {
    if (result & buttonOK) return IDOK;
    if (result & buttonCancel) return IDCANCEL;
    if (result & buttonYes) return IDYES;
    if (result & buttonNo) return IDNO;
    if (result & buttonRetry) return IDRETRY;
    if (result & buttonAbort) return IDABORT;
    if (result & buttonIgnore) return IDIGNORE;

    return -1;
}

void popup_message_v3::messageBoxAsync(fb2k::hwnd_t owner, const char* content, const char* caption, unsigned styleFlags, std::function<void (int)> onResult) {
    PFC_ASSERT(core_api::is_main_thread());
    auto q = setupMessageBox(owner, content, caption, styleFlags);
    if (onResult) {
        q.reply = fb2k::makeCompletionNotify([onResult](unsigned code) {
            onResult(messageBoxReply(code));
            });
    }
    this->show_query(q);
}

int popup_message_v3::messageBox(fb2k::hwnd_t owner, const char* content, const char* caption, unsigned styleFlags) {
    PFC_ASSERT(core_api::is_main_thread());
    auto q = setupMessageBox(owner, content, caption, styleFlags);
    uint32_t result = this->show_query_modal(q);
    return messageBoxReply(result);
}

#if MODE_METABALLS
#include "modes/MetaballsMode.h"
#include "extensions/MicrophoneExtension.h"
#include "services/DisplayService.h" // NOLINT(misc-include-cleaner)

void MetaballsMode::configure()
{
    for (uint16_t index = 0; index < contributions.size(); ++index)
    {
        contributions[index] = ((UINT8_MAX - index) * (UINT8_MAX - index) * (1U << 6U)) >> 16U;
    }
    for (Ball &particle : balls)
    {
        particle.x = static_cast<float>(random(GRID_COLUMNS));
        particle.y = static_cast<float>(random(GRID_ROWS));
        particle.xVelocity = speed * static_cast<float>(random(1, multiplier) * ((random(2) * 2) - 1));
        particle.yVelocity = speed * static_cast<float>(random(1, multiplier) * ((random(2) * 2) - 1));
    }
}

void MetaballsMode::handle()
{
#if EXTENSION_MICROPHONE
    if (Microphone->isTriggered())
#endif // EXTENSION_MICROPHONE
    {
#if PITCH_HORIZONTAL != PITCH_VERTICAL
        const bool rotated = (static_cast<uint8_t>(Display.getOrientation()) % 2) != 0;
        const float xScale = static_cast<float>(2 * (rotated ? PITCH_VERTICAL : PITCH_HORIZONTAL)) /
                             static_cast<float>(PITCH_VERTICAL + PITCH_HORIZONTAL);
        const float yScale = static_cast<float>(2 * (rotated ? PITCH_HORIZONTAL : PITCH_VERTICAL)) /
                             static_cast<float>(PITCH_VERTICAL + PITCH_HORIZONTAL);
#endif // PITCH_HORIZONTAL == PITCH_VERTICAL

        for (const Ball &particle : balls)
        {
            const uint8_t minX = max<int8_t>(particle.x - radius - max<float>(particle.xVelocity, 0), 0);
            const uint8_t minY = max<int8_t>(particle.y - radius - max<float>(particle.yVelocity, 0), 0);
            const uint8_t maxX = min<int8_t>(ceilf(particle.x + radius - min<float>(particle.xVelocity, 0)), GRID_COLUMNS - 1);
            const uint8_t maxY = min<int8_t>(ceilf(particle.y + radius - min<float>(particle.yVelocity, 0)), GRID_ROWS - 1);

            for (uint8_t col = minX; col <= maxX; ++col)
            {
                for (uint8_t row = minY; row <= maxY; ++row)
                {
                    uint8_t intensity = 0;
                    for (const Ball &particle : balls)
                    {
#if PITCH_HORIZONTAL == PITCH_VERTICAL
                        const float xDiff = (particle.x - static_cast<float>(col));
                        const float yDiff = (particle.y - static_cast<float>(row));
#else
                        const float xDiff = (particle.x - static_cast<float>(col)) * xScale;
                        const float yDiff = (particle.y - static_cast<float>(row)) * yScale;
#endif // PITCH_HORIZONTAL == PITCH_VERTICAL
                        const float distSq = (xDiff * xDiff) + (yDiff * yDiff);
                        if (distSq < radiusSq)
                        {
                            intensity = min<uint8_t>(
                                intensity + contributions[static_cast<uint8_t>(distSq * UINT8_MAX / radiusSq)],
                                UINT8_MAX);
                            if (intensity >= UINT8_MAX)
                            {
                                break;
                            }
                        }
                    }
                    Display.setPixel(col, row, intensity);
                }
            }
        }

        for (Ball &particle : balls)
        {
            particle.x += particle.xVelocity;
            particle.y += particle.yVelocity;

            if (particle.x < 0)
            {
                particle.x = 0;
                particle.xVelocity = speed * static_cast<float>(random(1, multiplier));
            }
            else if (particle.x > GRID_COLUMNS - 1)
            {
                particle.x = GRID_COLUMNS - 1;
                particle.xVelocity = -speed * static_cast<float>(random(1, multiplier));
            }

            if (particle.y < 0)
            {
                particle.y = 0;
                particle.yVelocity = speed * static_cast<float>(random(1, multiplier));
            }
            else if (particle.y > GRID_ROWS - 1)
            {
                particle.y = GRID_ROWS - 1;
                particle.yVelocity = -speed * static_cast<float>(random(1, multiplier));
            }
        }
    }
}
