// Helper functions for matrix operations
int scalarVecMult(double factor, double vec[], int size);
int copyVector(double src[], double dest[], int size);

/**
 * Performs matrix multiplication: C = A * B
 * Matrices stored in row-major order.
 */
void multiplyMatrices(double matrixA[], double matrixB[], int dimension, double resultMatrix[]);

int invertMatrix(double inputMatrix[], int rows, int cols, double workspace[]);
int computeEigenvaluesEigenvectors(int option, double matrix[], int size, 
                                   double realParts[], double imagParts[],
                                   double vecReal[], double vecImag[], double temp[]);
void balanceMatrix(double mat[], int dim, int* lowerBound, int* upperBound, double scaling[]);
void restoreEigenvectors(int dim, double vr[], double vi[], int lowIdx, int highIdx, double scale[]);
int hessenbergReduction(int mode, double mat[], int dim, int lowIdx, int highIdx, 
                        double vr[], double vi[], int workArray[]);
typedef struct { double real; double imag; } ComplexNumber;

#define complexMagnitude(a) (fabs((a).real) + fabs((a).imag))

ComplexNumber createComplex(double re, double im);
ComplexNumber addComplex(ComplexNumber a, ComplexNumber b);
ComplexNumber subtractComplex(ComplexNumber a, ComplexNumber b);
ComplexNumber multiplyComplex(ComplexNumber a, ComplexNumber b);
ComplexNumber divideComplex(ComplexNumber numerator, ComplexNumber denominator);
ComplexNumber scaleComplex(ComplexNumber val, double scalar);
int copyComplexVector(ComplexNumber src[], ComplexNumber dest[], int length);
int multiplyComplexMatrices(ComplexNumber a[], ComplexNumber b[], ComplexNumber c[], 
                            int rowsA, int colsAB, int colsB);
int printComplexMatrix(FILE* out, ComplexNumber mat[], int rows, int cols);
int invertComplexMatrix(ComplexNumber mat[], int rows, int cols, double auxSpace[]);

// Implementation of helper functions
int scalarVecMult(double factor, double vec[], int size) {
    for (int idx = 0; idx < size; idx++) {
        vec[idx] *= factor;
    }
    return 0;
}

int copyVector(double src[], double dest[], int size) {
    for (int idx = 0; idx < size; idx++) {
        dest[idx] = src[idx];
    }
    return 0;
}

void multiplyMatrices(double matrixA[], double matrixB[], int dimension, double resultMatrix[]) {
    // Initialize result matrix to zero
    for (int i = 0; i < dimension * dimension; i++) {
        resultMatrix[i] = 0.0;
    }

    // Perform standard matrix multiplication
    for (int row = 0; row < dimension; row++) {
        for (int col = 0; col < dimension; col++) {
            for (int k = 0; k < dimension; k++) {
                resultMatrix[row * dimension + col] += 
                    matrixA[row * dimension + k] * matrixB[k * dimension + col];
            }
        }
    }
}

int invertMatrix(double inputMatrix[], int rows, int cols, double workspace[]) {
    // Assume cols >= rows
    int i, j, k;
    int* rowPermutation = (int*)workspace;
    const double epsilon = 1.0e-20;
    double tempVal, tempVal2, maxVal;
    double determinant = 1.0;

    for (i = 0; i < rows; i++) {
        maxVal = 0.0;
        for (j = i; j < rows; j++) {
            if (maxVal < fabs(inputMatrix[j * cols + i])) {
                maxVal = fabs(inputMatrix[j * cols + i]);
                rowPermutation[i] = j;
            }
        }

        determinant *= maxVal;
        if (maxVal < epsilon) {
            printf("\nMatrix becomes singular at step %3d!\n", i + 1);
            return -1;
        }

        if (rowPermutation[i] != i) {
            for (j = 0; j < cols; j++) {
                tempVal = inputMatrix[i * cols + j];
                inputMatrix[i * cols + j] = inputMatrix[rowPermutation[i] * cols + j];
                inputMatrix[rowPermutation[i] * cols + j] = tempVal;
            }
        }

        tempVal = 1.0 / inputMatrix[i * cols + i];
        for (j = 0; j < rows; j++) {
            if (j == i) continue;
            tempVal2 = tempVal * inputMatrix[j * cols + i];
            for (k = 0; k < rows; k++) {
                inputMatrix[j * cols + k] -= tempVal2 * inputMatrix[i * cols + k];
            }
            inputMatrix[j * cols + i] = -tempVal2;
        }

        for (j = 0; j < cols; j++) {
            inputMatrix[i * cols + j] *= tempVal;
        }
        inputMatrix[i * cols + i] = tempVal;
    }

    for (i = rows - 1; i >= 0; i--) {
        if (rowPermutation[i] == i) continue;
        for (j = 0; j < rows; j++) {
            tempVal = inputMatrix[j * cols + i];
            inputMatrix[j * cols + i] = inputMatrix[j * cols + rowPermutation[i]];
            inputMatrix[j * cols + rowPermutation[i]] = tempVal;
        }
    }

    return 0;
}

// Main eigenvalue/eigenvector routine
int computeEigenvaluesEigenvectors(int option, double matrix[], int size, 
                                   double realParts[], double imagParts[],
                                   double vecReal[], double vecImag[], double temp[]) {
    int lowerBound, upperBound, idx, state = 0;
    const double base = 2;
    const int precisionDigits = 53;
    double tiny = sqrt(pow(base, 1 - precisionDigits));

    balanceMatrix(matrix, size, &lowerBound, &upperBound, temp);
    hessenbergReduction(option, matrix, size, lowerBound, upperBound, vecReal, vecImag, (int*)(temp + size));

    if (-1 == hessenbergEigenvalues(option, matrix, size, lowerBound, upperBound, realParts, imagParts, vecReal, vecImag)) {
        return -1;
    }

    if (option) {
        restoreEigenvectors(size, vecReal, vecImag, lowerBound, upperBound, temp);
    }

    // Sort eigenvalues (descending order by real part)
    for (idx = 0; idx < size; idx++) {
        int maxIndex = idx;
        double maxReal = realParts[idx];
        for (int j = idx + 1; j < size; j++) {
            if (realParts[j] > maxReal) {
                maxReal = realParts[j];
                maxIndex = j;
            }
        }

        if (maxIndex != idx) {
            std::swap(realParts[idx], realParts[maxIndex]);
            std::swap(imagParts[idx], imagParts[maxIndex]);
            for (int k = 0; k < size; k++) {
                std::swap(vecReal[k * size + idx], vecReal[k * size + maxIndex]);
                std::swap(vecImag[k * size + idx], vecImag[k * size + maxIndex]);
            }
        }

        if (fabs(imagParts[idx]) > tiny) {
            state = 1;
        }
    }

    return state;
}

// Complex number operations
ComplexNumber createComplex(double re, double im) {
    ComplexNumber result;
    result.real = re;
    result.imag = im;
    return result;
}

ComplexNumber addComplex(ComplexNumber a, ComplexNumber b) {
    ComplexNumber res;
    res.real = a.real + b.real;
    res.imag = a.imag + b.imag;
    return res;
}

ComplexNumber subtractComplex(ComplexNumber a, ComplexNumber b) {
    ComplexNumber res;
    res.real = a.real - b.real;
    res.imag = a.imag - b.imag;
    return res;
}

ComplexNumber multiplyComplex(ComplexNumber a, ComplexNumber b) {
    ComplexNumber res;
    res.real = a.real * b.real - a.imag * b.imag;
    res.imag = a.real * b.imag + a.imag * b.real;
    return res;
}

ComplexNumber divideComplex(ComplexNumber num, ComplexNumber denom) {
    double ratio, denominator;
    ComplexNumber res;

    if (fabs(denom.real) <= fabs(denom.imag)) {
        ratio = denom.real / denom.imag;
        denominator = denom.imag * (1.0 + ratio * ratio);
        res.real = (num.real * ratio + num.imag) / denominator;
        res.imag = (num.imag * ratio - num.real) / denominator;
    } else {
        ratio = denom.imag / denom.real;
        denominator = denom.real * (1.0 + ratio * ratio);
        res.real = (num.real + num.imag * ratio) / denominator;
        res.imag = (num.imag - num.real * ratio) / denominator;
    }
    return res;
}

ComplexNumber scaleComplex(ComplexNumber val, double scalar) {
    ComplexNumber res;
    res.real = scalar * val.real;
    res.imag = scalar * val.imag;
    return res;
}

int copyComplexVector(ComplexNumber src[], ComplexNumber dest[], int length) {
    for (int i = 0; i < length; i++) {
        dest[i] = src[i];
    }
    return 0;
}

int multiplyComplexMatrices(ComplexNumber a[], ComplexNumber b[], ComplexNumber c[], 
                            int rowsA, int colsAB, int colsB) {
    for (int i = 0; i < rowsA; i++) {
        for (int j = 0; j < colsB; j++) {
            ComplexNumber sum = createComplex(0.0, 0.0);
            for (int k = 0; k < colsAB; k++) {
                sum = addComplex(sum, multiplyComplex(a[i * colsAB + k], b[k * colsB + j]));
            }
            c[i * colsB + j] = sum;
        }
    }
    return 0;
}

int printComplexMatrix(FILE* out, ComplexNumber mat[], int rows, int cols) {
    for (int i = 0; i < rows; i++) {
        fputc('\n', out);
        for (int j = 0; j < cols; j++) {
            fprintf(out, "%7.3f%7.3f  ", mat[i * cols + j].real, mat[i * cols + j].imag);
        }
    }
    return 0;
}

int invertComplexMatrix(ComplexNumber mat[], int rows, int cols, double auxSpace[]) {
    int i, j, k;
    int* rowPermutation = (int*)auxSpace;
    double maxSize;
    const double threshold = 1e-20;
    ComplexNumber tempVal, tempVal2;

    for (i = 0; i < rows; i++) {
        maxSize = 0.0;
        for (j = i; j < rows; j++) {
            if (maxSize < complexMagnitude(mat[j * cols + i])) {
                maxSize = complexMagnitude(mat[j * cols + i]);
                rowPermutation[i] = j;
            }
        }

        if (maxSize < threshold) {
            printf("\nDeterminant approaches zero at index %8d!\n", i + 1);
            return -1;
        }

        if (rowPermutation[i] != i) {
            for (j = 0; j < cols; j++) {
                tempVal = mat[i * cols + j];
                mat[i * cols + j] = mat[rowPermutation[i] * cols + j];
                mat[rowPermutation[i] * cols + j] = tempVal;
            }
        }

        ComplexNumber one = createComplex(1.0, 0.0);
        tempVal = divideComplex(one, mat[i * cols + i]);

        for (j = 0; j < rows; j++) {
            if (j == i) continue;
            tempVal2 = multiplyComplex(tempVal, mat[j * cols + i]);
            for (k = 0; k < cols; k++) {
                mat[j * cols + k] = subtractComplex(mat[j * cols + k], multiplyComplex(tempVal2, mat[i * cols + k]));
            }
            mat[j * cols + i] = scaleComplex(tempVal2, -1.0);
        }

        for (j = 0; j < cols; j++) {
            mat[i * cols + j] = multiplyComplex(mat[i * cols + j], tempVal);
        }
        mat[i * cols + i] = tempVal;
    }

    for (i = rows - 1; i >= 0; i--) {
        if (rowPermutation[i] == i) continue;
        for (j = 0; j < rows; j++) {
            tempVal = mat[j * cols + i];
            mat[j * cols + i] = mat[j * cols + rowPermutation[i]];
            mat[j * cols + rowPermutation[i]] = tempVal;
        }
    }

    return 0;
}

// Balance matrix for numerical stability
void balanceMatrix(double mat[], int dim, int* lowerBound, int* upperBound, double scaling[]) {
    double c, f, g, r, s;
    int i, j, k, l, finished;

    // Push rows with isolated eigenvalues down
    for (k = dim - 1; k >= 0; k--) {
        for (j = k; j >= 0; j--) {
            for (i = 0; i <= k; i++) {
                if (i != j && fabs(mat[i * dim + j]) != 0) break;
            }
            if (i > k) {
                scaling[k] = j;
                if (j != k) {
                    for (i = 0; i <= k; i++) {
                        c = mat[i * dim + j];
                        mat[i * dim + j] = mat[i * dim + k];
                        mat[i * dim + k] = c;
                    }
                    for (i = 0; i < dim; i++) {
                        c = mat[j * dim + i];
                        mat[j * dim + i] = mat[k * dim + i];
                        mat[k * dim + i] = c;
                    }
                }
                break;
            }
        }
        if (j < 0) break;
    }

    // Push columns with isolated eigenvalues left
    for (l = 0; l <= k; l++) {
        for (j = l; j <= k; j++) {
            for (i = l; i <= k; i++) {
                if (i != j && fabs(mat[i * dim + j]) != 0) break;
            }
            if (i > k) {
                scaling[l] = j;
                if (j != l) {
                    for (i = 0; i <= k; i++) {
                        c = mat[i * dim + j];
                        mat[i * dim + j] = mat[i * dim + l];
                        mat[i * dim + l] = c;
                    }
                    for (i = l; i < dim; i++) {
                        c = mat[j * dim + i];
                        mat[j * dim + i] = mat[l * dim + i];
                        mat[l * dim + i] = c;
                    }
                }
                break;
            }
        }
        if (j > k) break;
    }

    *upperBound = k;
    *lowerBound = l;

    // Balance submatrix
    for (i = l; i <= k; i++) {
        scaling[i] = 1.0;
    }

    do {
        finished = 1;
        for (i = l; i <= k; i++) {
            for (c = 0, r = 0, j = l; j <= k; j++) {
                if (j != i) {
                    c += fabs(mat[j * dim + i]);
                    r += fabs(mat[i * dim + j]);
                }
            }
            if (c != 0 && r != 0) {
                g = r / 2.0;
                f = 1.0;
                s = c + r;
                while (c < g) {
                    f *= 2.0;
                    c *= 4.0;
                }
                g = r * 2.0;
                while (c >= g) {
                    f /= 2.0;
                    c /= 4.0;
                }
                if ((c + r) / f < 0.95 * s) {
                    finished = 0;
                    g = 1.0 / f;
                    scaling[i] *= f;
                    for (j = l; j < dim; j++) {
                        mat[i * dim + j] *= g;
                    }
                    for (j = 0; j <= k; j++) {
                        mat[j * dim + i] *= f;
                    }
                }
            }
        }
    } while (!finished);
}

// Restore eigenvectors after balancing
void restoreEigenvectors(int dim, double vr[], double vi[], int lowIdx, int highIdx, double scale[]) {
    int i, j, k;
    double temp;

    for (i = lowIdx; i <= highIdx; i++) {
        for (j = 0; j < dim; j++) {
            vr[i * dim + j] *= scale[i];
            vi[i * dim + j] *= scale[i];
        }
    }

    for (i = lowIdx - 1; i >= 0; i--) {
        if ((k = (int)scale[i]) != i) {
            for (j = 0; j < dim; j++) {
                temp = vr[i * dim + j];
                vr[i * dim + j] = vr[k * dim + j];
                vr[k * dim + j] = temp;
                temp = vi[i * dim + j];
                vi[i * dim + j] = vi[k * dim + j];
                vi[k * dim + j] = temp;
            }
        }
    }

    for (i = highIdx + 1; i < dim; i++) {
        if ((k = (int)scale[i]) != i) {
            for (j = 0; j < dim; j++) {
                temp = vr[i * dim + j];
                vr[i * dim + j] = vr[k * dim + j];
                vr[k * dim + j] = temp;
                temp = vi[i * dim + j];
                vi[i * dim + j] = vi[k * dim + j];
                vi[k * dim + j] = temp;
            }
        }
    }
}

// Reduce to Hessenberg form
void hessenbergReduction(int mode, double mat[], int dim, int lowIdx, int highIdx, 
                         double vr[], double vi[], int workArray[]) {
    int i, j, m;
    double x, y;

    for (m = lowIdx + 1; m < highIdx; m++) {
        for (x = 0, i = m, j = m; j <= highIdx; j++) {
            if (fabs(mat[j * dim + (m - 1)]) > fabs(x)) {
                x = mat[j * dim + (m - 1)];
                i = j;
            }
        }

        if ((workArray[m] = i) != m) {
            for (j = m - 1; j < dim; j++) {
                y = mat[i * dim + j];
                mat[i * dim + j] = mat[m * dim + j];
                mat[m * dim + j] = y;
            }
            for (j = 0; j <= highIdx; j++) {
                y = mat[j * dim + i];
                mat[j * dim + i] = mat[j * dim + m];
                mat[j * dim + m] = y;
            }
        }

        if (x != 0) {
            for (i = m + 1; i <= highIdx; i++) {
                if ((y = mat[i * dim + (m - 1)]) != 0) {
                    y = mat[i * dim + (m - 1)] = y / x;
                    for (j = m; j < dim; j++) {
                        mat[i * dim + j] -= y * mat[m * dim + j];
                    }
                    for (j = 0; j <= highIdx; j++) {
                        mat[j * dim + m] += y * mat[j * dim + i];
                    }
                }
            }
        }
    }

    if (mode) {
        for (i = 0; i < dim; i++) {
            for (j = 0; j < dim; j++) {
                vr[i * dim + j] = 0.0;
                vi[i * dim + j] = 0.0;
            }
            vr[i * dim + i] = 1.0;
        }

        for (m = highIdx - 1; m > lowIdx; m--) {
            for (i = m + 1; i <= highIdx; i++) {
                vr[i * dim + m] = mat[i * dim + (m - 1)];
            }
            if ((i = workArray[m]) != m) {
                for (j = m; j <= highIdx; j++) {
                    vr[m * dim + j] = vr[i * dim + j];
                    vr[i * dim + j] = 0.0;
                }
                vr[i * dim + m] = 1.0;
            }
        }
    }
}

