// Count how many lines a string spans, returns 0 on error
static size_t count_utf8_lines(std::string_view input) 
{
	size_t line_count = 1;

	const char* ptr = input.data();
	const char* end = ptr + input.size();
	while (ptr < end) {
		uint32_t code_point;
		int decode_error;
		ptr = utf8_decode(ptr, &code_point, &decode_error);
		if (decode_error) return 0;
		if (code_point == '\n') ++line_count;
	}

	return line_count;
}


void ws_source::refresh_line(const char* buffer, int caret_position)
{
	if (m_caret_pos == caret_position) return;
	m_caret_pos = caret_position;
	m_current_line = count_utf8_lines({ buffer, (size_t)caret_position });
}


void ws_source::on_load()
{
	m_should_reset = true;
}



static void extract_source(const oper_block& block, std::string& output)
{
	output.clear();

	std::ostringstream stream;
	ims_precision precision(stream);
	precision.template max<DefNumTypes::Real>();

	ims_write_block(stream, &block);

	output = stream.str();
}

