void ws_source::apply(bool is_js)
{
	if (!is_js) {
		const oper_block* current = get_cur_block();
		if (current != m_visible.b || (current && current->m_flags.from_js)) {
			show_generic_error_msg();
			return;
		}
	}

	m_editor = m_visible;
	m_editor.js_mode = is_js;
	try_open_file([this]() {
		open_file("", "", true, false, &m_editor);
	}, false);
}


void ws_source::append()
{
	m_editor.b = nullptr;
	m_editor.src = m_visible.src;
	m_editor.js_mode = false;
	try_open_file([this]() {
		open_file("", "", true, false, &m_editor);
	}, false);
}


void ws_source::show(int& identifier, bool is_js)
{
	const oper_block* current_block = nullptr;

	let& js_source = ims_info_get().m_js_src;

	m_should_reset = m_should_reset || m_visible.js_mode != is_js;

	if (!is_js) {
		current_block = get_cur_block();

		if (m_should_reset || current_block != m_visible.b) {
			m_visible.b = current_block;
			if (current_block) extract_source(*current_block, m_visible.src);
			else m_visible.src.clear();
		}
	}
	else {
		if (m_should_reset) {
			m_visible.src = js_source;
			m_visible.b = nullptr;
		}
	}

	m_should_reset = false;
	m_visible.js_mode = is_js;

	/////////////////////////////////////////////////////////////////

	if (!is_js) {
		SAME_LINE();
		if (ims_button("+Block", "Save changes as a new block", &identifier)) {
			append();
		}
	}

	enum
	{
		CMD_Cut,
		CMD_Copy,
		CMD_Paste,
		CMD_Undo,
		CMD_Redo,
		CMD_SelectAll,
	};

	static int s_active_command = CMD_Copy;

	{
		SAME_LINE();
		ImGui::PushID(identifier++);
		ImGui::PushItemWidth(70 * get_ui_scale());
		static constexpr auto commands = { "Cut","Copy", "Paste", "Undo", "Redo", "Select All" };
		ImGui::Combo("", &s_active_command, commands.begin(), (int)commands.size(), (int)commands.size());
		ImGui::PopItemWidth();
		ImGui::PopID();
	}

	bool button_pressed = false;

	{
		SAME_LINE();
		button_pressed = ims_button("Ok", "", &identifier);
	}

	{
		SAME_LINE();
		ImGui::Text(":%zu", m_current_line);
		set_tooltip("Cursor line");
	}

	int editor_action = 0;


	if (button_pressed) {
		switch (s_active_command) {
		case CMD_Cut:
			editor_action = 1;
			s_active_command = CMD_Paste;
			break;
		case CMD_Copy:
			editor_action = 2;
			s_active_command = CMD_Paste;
			break;
		case CMD_Paste:
			editor_action = 3;
			s_active_command = CMD_Copy;
			break;
		case CMD_Undo:
			editor_action = 4;
			break;
		case CMD_Redo:
			editor_action = 5;
			break;
		case CMD_SelectAll:
			//simulate_ctrl_a();
			editor_action = 6;
			s_active_command = CMD_Copy;

		}
	}

	ImGui::g_edit_hook = editor_action;
	IMS_SCOPE([] {ImGui::g_edit_hook = 0; });

	//stretch InputTextMultiline to cover the entire window
	auto window_size = ImGui::GetWindowSize();

	const auto cursor_pos = ImGui::GetCursorPos();

	window_size.x -= cursor_pos.x + cursor_pos.x;
	window_size.y -= cursor_pos.y + cursor_pos.x;

	ImGuiInputTextFlags text_flags = ImGuiInputTextFlags_AllowTabInput;

 	text_flags |= ImGuiInputTextFlags_CallbackAlways;
 	auto callback_func = [](ImGuiInputTextCallbackData* data)
 	{
		((ws_source*)(data->UserData))->refresh_line(data->Buf, data->CursorPos);
		return 0;
 	};


	//fixes a bug where the cursor was incorrectly positioned when using a mouse
	ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(0, 0));
	ImGui::PushStyleColor(ImGuiCol_Border, ImGui::GetStyle().Colors[ImGuiCol_ChildBg]);
	ImGui::PushStyleColor(ImGuiCol_FrameBg, ImGui::GetStyle().Colors[ImGuiCol_ChildBg]);
	if (button_pressed) {
		ImGui::SetItemDefaultFocus();
		ImGui::SetKeyboardFocusHere();
	}

	//static char buf[123] = { 0 };ImGui::InputText("1", buf, IM_ARRAYSIZE(buf));
	ImGui::InputTextMultiline("###source", &m_visible.src, window_size, text_flags, callback_func, this);



	ImGui::PopStyleColor(2);
	ImGui::PopStyleVar(1);

}

