void Snapshot::reset()
{
    this->identifier.clear();
    this->timestamp = 0;
    this->slic3r_version_snapshot = Semver::invalid();
    this->note.clear();
    this->cause = SNAPSHOT_UNKNOWN;
    this->print_profile.clear();
    this->sla_print_profile.clear();
    this->filaments_list.clear();
    this->sla_material_profile.clear();
    this->printer_profile.clear();
    this->physical_printer_profile.clear();
}

void Snapshot::read_ini(const std::string &filepath)
{
    this->reset();

    auto error_handler = [&filepath](const std::string &message)
    {
        throw file_parser_error(std::string("Failed to load snapshot file. Cause: ") + message, filepath);
    };

    // Load the snapshot configuration file
    boost::property_tree::ptree config_tree;
    try
    {
        boost::nowide::ifstream input_stream(filepath);
        boost::property_tree::read_ini(input_stream, config_tree);
    }
    catch (const std::ifstream::failure &error)
    {
        throw file_parser_error(std::string("The snapshot file cannot be accessed. Reason: ") + error.what(), filepath);
    }
    catch (const std::runtime_error &error)
    {
        error_handler(error.what());
    }

    // Process snapshot.ini sections
    std::string vendor_section_prefix = "Vendor:";
    std::string filament_key = "filament";
    std::string model_key_prefix = "model_";

    for (auto &section : config_tree)
    {
        if (section.first == "snapshot")
        {
            // Parse common snapshot data
            for (auto &entry : section.second)
            {
                if (entry.first == "id")
                    this->identifier = entry.second.data();
                else if (entry.first == "timestamp")
                {
                    this->timestamp = Slic3r::Utils::parse_iso_utc_timestamp(entry.second.data());
                    if (this->timestamp == (time_t) -1)
                        error_handler("invalid timestamp");
                }
                else if (entry.first == "slic3r_version_snapshot")
                {
                    auto version = Semver::parse(entry.second.data());
                    if (!version)
                        error_handler("invalid slic3r_version_snapshot semver");
                    this->slic3r_version_snapshot = *version;
                }
                else if (entry.first == "note")
                {
                    this->note = entry.second.data();
                }
                else if (entry.first == "cause")
                {
                    std::string cause_value = entry.second.data();
                    if (cause_value == "upgrade")
                        this->cause = SNAPSHOT_UPGRADE;
                    else if (cause_value == "downgrade")
                        this->cause = SNAPSHOT_DOWNGRADE;
                    else if (cause_value == "before_rollback")
                        this->cause = SNAPSHOT_BEFORE_ROLLBACK;
                    else if (cause_value == "user")
                        this->cause = SNAPSHOT_USER;
                    else
                        this->cause = SNAPSHOT_UNKNOWN;
                }
            }
        }
        else if (section.first == "presets")
        {
            // Load active preset names
            for (auto &entry : section.second)
            {
                if (entry.first == "print")
                {
                    this->print_profile = entry.second.data();
                }
                else if (entry.first == "sla_print")
                {
                    this->sla_print_profile = entry.second.data();
                }
                else if (boost::starts_with(entry.first, "filament"))
                {
                    int index = 0;
                    if (entry.first == "filament" || sscanf(entry.first.c_str(), "filament_%d", &index) == 1)
                    {
                        if (int(this->filaments_list.size()) <= index)
                            this->filaments_list.resize(index + 1, std::string());
                        this->filaments_list[index] = entry.second.data();
                    }
                }
                else if (entry.first == "sla_material")
                {
                    this->sla_material_profile = entry.second.data();
                }
                else if (entry.first == "printer")
                {
                    this->printer_profile = entry.second.data();
                }
                else if (entry.first == "physical_printer")
                {
                    this->physical_printer_profile = entry.second.data();
                }
            }
        }
        else if (boost::starts_with(section.first, vendor_section_prefix) &&
                 section.first.size() > vendor_section_prefix.size())
        {
            // Vendor specific configuration section
            VendorConfig vc;
            vc.name = section.first.substr(vendor_section_prefix.size());
            for (auto &entry : section.second)
            {
                if (entry.first == "version" || entry.first == "min_slic3r_version" || entry.first == "max_slic3r_version")
                {
                    auto version = Semver::parse(entry.second.data());
                    if (!version)
                        error_handler("invalid " + entry.first + " format for " + section.first);
                    if (entry.first == "version")
                        vc.version.config_version = *version;
                    else if (entry.first == "min_slic3r_version")
                        vc.version.min_slic3r_version = *version;
                    else
                        vc.version.max_slic3r_version = *version;
                }
                else if (boost::starts_with(entry.first, model_key_prefix) && entry.first.size() > model_key_prefix.size())
                {
                    // Parse installed printer variants for the model
                    auto &variant_set = vc.models_variants_installed[entry.first.substr(model_key_prefix.size())];
                    std::vector<std::string> variants;
                    if (unescape_strings_cstyle(entry.second.data(), variants))
                        for (auto &variant : variants)
                            variant_set.insert(std::move(variant));
                }
            }
            this->vendor_configs.emplace_back(std::move(vc));
        }
    }

    // Sort vendors alphabetically
    std::sort(this->vendor_configs.begin(), this->vendor_configs.end(),
              [](const VendorConfig &cfg1, const VendorConfig &cfg2) { return cfg1.name < cfg2.name; });
}

static std::string reason_to_string(const Snapshot::Reason cause)
{
    switch (cause)
    {
    case Snapshot::SNAPSHOT_UPGRADE:
        return "upgrade";
    case Snapshot::SNAPSHOT_DOWNGRADE:
        return "downgrade";
    case Snapshot::SNAPSHOT_BEFORE_ROLLBACK:
        return "before_rollback";
    case Snapshot::SNAPSHOT_USER:
        return "user";
    case Snapshot::SNAPSHOT_UNKNOWN:
    default:
        return "unknown";
    }
}

void Snapshot::write_ini(const std::string &filepath)
{
    boost::nowide::ofstream output_file;
    output_file.open(filepath, std::ios::out | std::ios::trunc);
    output_file << "# " << Slic3r::header_slic3r_generated() << std::endl;

    // Write common snapshot data
    output_file << std::endl << "[snapshot]" << std::endl;
    output_file << "id = " << this->identifier << std::endl;
    output_file << "timestamp = " << Slic3r::Utils::iso_utc_timestamp(this->timestamp) << std::endl;
    output_file << "slic3r_version_snapshot = " << this->slic3r_version_snapshot.to_string() << std::endl;
    output_file << "note = " << this->note << std::endl;
    output_file << "cause = " << reason_to_string(this->cause) << std::endl;

    // Write active presets
    output_file << std::endl << "[presets]" << std::endl;
    output_file << "print = " << this->print_profile << std::endl;
    output_file << "sla_print = " << this->sla_print_profile << std::endl;
    output_file << "filament = " << this->filaments_list.front() << std::endl;
    for (size_t i = 1; i < this->filaments_list.size(); ++i)
        output_file << "filament_" << std::to_string(i) << " = " << this->filaments_list[i] << std::endl;
    output_file << "sla_material = " << this->sla_material_profile << std::endl;
    output_file << "printer = " << this->printer_profile << std::endl;
    output_file << "physical_printer = " << this->physical_printer_profile << std::endl;

    // Write vendor configurations
    for (const VendorConfig &vc : this->vendor_configs)
    {
        output_file << std::endl << "[Vendor:" << vc.name << "]" << std::endl;
        output_file << "version = " << vc.version.config_version.to_string() << std::endl;
        output_file << "min_slic3r_version = " << vc.version.min_slic3r_version.to_string() << std::endl;
        output_file << "max_slic3r_version = " << vc.version.max_slic3r_version.to_string() << std::endl;

        // Write installed printer models and variants
        for (const auto &model : vc.models_variants_installed)
        {
            if (model.second.size() == 0)
                continue;
            const std::vector<std::string> variants(model.second.begin(), model.second.end());
            const auto escaped = escape_strings_cstyle(variants);
            output_file << "model_" << model.first << " = " << escaped << std::endl;
        }
    }
    output_file.close();
}

void Snapshot::apply_selections(AppConfig &config) const
{
    assert(filaments_list.size() >= 1);
    config.clear_section("presets");
    config.set("presets", "print", print_profile);
    config.set("presets", "sla_print", sla_print_profile);
    config.set("presets", "filament", filaments_list.front());
    for (unsigned i = 1; i < filaments_list.size(); ++i)
    {
        char name_buffer[64];
        sprintf(name_buffer, "filament_%u", i);
        config.set("presets", name_buffer, filaments_list[i]);
    }
    config.set("presets", "sla_material", sla_material_profile);
    config.set("presets", "printer", printer_profile);
    config.set("presets", "physical_printer", physical_printer_profile);
}

void Snapshot::apply_vendor_configs(AppConfig &config) const
{
    std::map<std::string, std::map<std::string, std::set<std::string>>> vendors_map;
    for (const VendorConfig &vc : vendor_configs)
        vendors_map[vc.name] = vc.models_variants_installed;
    config.set_vendors(std::move(vendors_map));
}

static constexpr auto config_subdirectories = {"print",   "sla_print",        "filament", "sla_material",
                                               "printer", "physical_printer", "vendor"};

// Compare current configuration state with snapshot
bool Snapshot::equal_to_current(const AppConfig &app_config) const
{
    // Check vendor configurations match
    {
        std::set<std::string> matched_vendors;
        for (const VendorConfig &vc : this->vendor_configs)
        {
            auto it = app_config.vendors().find(vc.name);
            if (it == app_config.vendors().end() ||
                it->second != vc.models_variants_installed)
                return false;
            matched_vendors.insert(vc.name);
        }
        for (const auto &v : app_config.vendors())
            if (matched_vendors.find(v.first) == matched_vendors.end() && !v.second.empty())
                return false;
    }

    // Check INI files match
    boost::filesystem::path data_directory = boost::filesystem::path(Slic3r::data_dir());
    boost::filesystem::path snapshot_path = boost::filesystem::path(Slic3r::data_dir()) / SNAPSHOT_DIR_NAME /
                                           this->identifier;

    for (const char *subdir : config_subdirectories)
    {
        boost::filesystem::path path1 = data_directory / subdir;
        boost::filesystem::path path2 = snapshot_path / subdir;
        std::vector<std::string> files1, files2;

        if (boost::filesystem::is_directory(path1))
            for (auto &dir_entry : boost::filesystem::directory_iterator(path1))
                if (Slic3r::is_ini_file(dir_entry))
                    files1.emplace_back(dir_entry.path().filename().string());

        if (boost::filesystem::is_directory(path2))
            for (auto &dir_entry : boost::filesystem::directory_iterator(path2))
                if (Slic3r::is_ini_file(dir_entry))
                    files2.emplace_back(dir_entry.path().filename().string());

        std::sort(files1.begin(), files1.end());
        std::sort(files2.begin(), files2.end());

        if (files1 != files2)
            return false;

        for (const std::string &filename : files1)
        {
            FILE *file1 = boost::nowide::fopen((path1 / filename).string().c_str(), "rb");
            FILE *file2 = boost::nowide::fopen((path2 / filename).string().c_str(), "rb");
            bool identical = true;

            if (file1 && file2)
            {
                char buffer1[4096];
                char buffer2[4096];
                do
                {
                    size_t bytes_read1 = fread(buffer1, 1, 4096, file1);
                    size_t bytes_read2 = fread(buffer2, 1, 4096, file2);
                    if (bytes_read1 != bytes_read2 || memcmp(buffer1, buffer2, bytes_read1))
                    {
                        identical = false;
                        break;
                    }
                } while (!feof(file1) || !feof(file2));
            }
            else
                identical = false;

            if (file1) fclose(file1);
            if (file2) fclose(file2);

            if (!identical)
                return false;
        }
    }
    return true;
}

size_t SnapshotDB::load_database()
{
    boost::filesystem::path snapshots_directory = SnapshotDB::create_db_dir();
    m_snapshots.clear();

    // Scan snapshot directories
    std::string errors_accumulated;
    for (auto &dir_entry : boost::filesystem::directory_iterator(snapshots_directory))
        if (boost::filesystem::is_directory(dir_entry.status()))
        {
            // Try loading snapshot.ini
            boost::filesystem::path ini_path = dir_entry.path() / SNAPSHOT_CONFIG_FILE;
            Snapshot snapshot;
            try
            {
                snapshot.read_ini(ini_path.string());
            }
            catch (const std::runtime_error &error)
            {
                errors_accumulated += error.what();
                errors_accumulated += "\n";
                continue;
            }

            // Verify directory name matches snapshot ID
            if (dir_entry.path().filename().string() != snapshot.identifier)
            {
                errors_accumulated += std::string("Snapshot ID ") + snapshot.identifier +
                                      " does not match directory " + dir_entry.path().filename().string() +
                                      "\n";
                continue;
            }

            m_snapshots.emplace_back(std::move(snapshot));
        }

    // Sort by timestamp
    std::sort(m_snapshots.begin(), m_snapshots.end(),
              [](const Snapshot &s1, const Snapshot &s2) { return s1.timestamp < s2.timestamp; });

    if (!errors_accumulated.empty())
        throw Slic3r::RuntimeError(errors_accumulated);

    return m_snapshots.size();
}

void SnapshotDB::update_versions(std::vector<Index> &index_data)
{
    for (Snapshot &snapshot : m_snapshots)
    {
        for (Snapshot::VendorConfig &vendor_config : snapshot.vendor_configs)
        {
            auto it = std::find_if(index_data.begin(), index_data.end(),
                                   [&vendor_config](const Index &idx) { return idx.vendor() == vendor_config.name; });
            if (it != index_data.end())
            {
                Index::const_iterator it_version = it->find(vendor_config.version.config_version);
                if (it_version != it->end())
                {
                    vendor_config.version.min_slic3r_version = it_version->min_slic3r_version;
                    vendor_config.version.max_slic3r_version = it_version->max_slic3r_version;
                }
            }
        }
    }
}

static void copy_directory_contents(const boost::filesystem::path &source,
                                    const boost::filesystem::path &destination)
{
    if (!boost::filesystem::is_directory(destination) && !boost::filesystem::create_directory(destination))
        throw Slic3r::RuntimeError(std::string("Unable to create directory at ") + destination.string());

    for (auto &dir_entry : boost::filesystem::directory_iterator(source))
        if (Slic3r::is_ini_file(dir_entry))
            if (std::string error_message;
                copy_file(dir_entry.path().string(), (destination / dir_entry.path().filename()).string(), error_message,
                          false) != SUCCESS)
                throw Slic3r::RuntimeError(format("Failed copying \"%1%\" to \"%2%\": %3%", source.string(),
                                                  destination.string(), error_message));
}

static void remove_ini_files(const boost::filesystem::path &path)
{
    if (!boost::filesystem::is_directory(path))
        return;
    for (auto &dir_entry : boost::filesystem::directory_iterator(path))
        if (boost::filesystem::is_regular_file(dir_entry.status()) &&
            boost::algorithm::iends_with(dir_entry.path().filename().string(), ".ini"))
            boost::filesystem::remove(dir_entry.path());
}

const Snapshot &SnapshotDB::capture_snapshot(const AppConfig &app_config, Snapshot::Reason cause,
                                             const std::string &note)
{
    boost::filesystem::path data_directory = boost::filesystem::path(Slic3r::data_dir());
    boost::filesystem::path db_directory = SnapshotDB::create_db_dir();

    // Prepare snapshot structure
    Snapshot snapshot;
    snapshot.timestamp = Slic3r::Utils::get_current_time_utc();
    snapshot.identifier = Slic3r::Utils::iso_utc_timestamp(snapshot.timestamp);
    snapshot.slic3r_version_snapshot = Slic3r::SEMVER;
    snapshot.note = note;
    snapshot.cause = cause;

    // Capture active presets
    snapshot.print_profile = app_config.get("presets", "print");
    snapshot.sla_print_profile = app_config.get("presets", "sla_print");
    snapshot.filaments_list.emplace_back(app_config.get("presets", "filament"));
    snapshot.sla_material_profile = app_config.get("presets", "sla_material");
    snapshot.printer_profile = app_config.get("presets", "printer");
    snapshot.physical_printer_profile = app_config.get("presets", "physical_printer");

    for (unsigned i = 1; i < 1000; ++i)
    {
        char name_buffer[64];
        sprintf(name_buffer, "filament_%u", i);
        if (!app_config.has("presets", name_buffer))
            break;
        snapshot.filaments_list.emplace_back(app_config.get("presets", name_buffer));
    }

    // Capture vendor configurations
    for (const auto &vendor : app_config.vendors())
    {
        Snapshot::VendorConfig cfg;
        cfg.name = vendor.first;
        cfg.models_variants_installed = vendor.second;

        for (auto it = cfg.models_variants_installed.begin(); it != cfg.models_variants_installed.end();)
            if (it->second.empty())
                cfg.models_variants_installed.erase(it++);
            else
                ++it;

        // Read active config bundle
        PresetBundle bundle;
        bundle.load_configbundle((data_directory / "vendor" / (cfg.name + ".ini")).string(),
                                 PresetBundle::LoadConfigBundleAttribute::LoadVendorOnly,
                                 ForwardCompatibilitySubstitutionRule::EnableSilent);
        for (const auto &vp : bundle.vendors)
            if (vp.second.id == cfg.name)
                cfg.version.config_version = vp.second.config_version;

        // Get min/max versions from index
        try
        {
            Index index;
            index.load(data_directory / "vendor" / (cfg.name + ".idx"));
            auto it = index.find(cfg.version.config_version);
            if (it != index.end())
            {
                cfg.version.min_slic3r_version = it->min_slic3r_version;
                cfg.version.max_slic3r_version = it->max_slic3r_version;
            }
        }
        catch (const std::runtime_error & /* error */)
        {
        }

        snapshot.vendor_configs.emplace_back(std::move(cfg));
    }

    boost::filesystem::path snapshot_directory = db_directory / snapshot.identifier;
    try
    {
        boost::filesystem::create_directory(snapshot_directory);

        // Backup presets
        for (const char *subdir : config_subdirectories)
            copy_directory_contents(data_directory / subdir, snapshot_directory / subdir);

        snapshot.write_ini((snapshot_directory / "snapshot.ini").string());

        assert(m_snapshots.empty() || m_snapshots.back().timestamp <= snapshot.timestamp);
        m_snapshots.emplace_back(std::move(snapshot));
    }
    catch (...)
    {
        if (boost::filesystem::is_directory(snapshot_directory))
        {
            try
            {
                boost::filesystem::remove_all(snapshot_directory);
            }
            catch (...)
            {
                BOOST_LOG_TRIVIAL(error) << "Failed creating snapshot and failed removing directory "
                                         << snapshot_directory;
            }
        }
        throw;
    }

    return m_snapshots.back();
}

const Snapshot &SnapshotDB::restore_snapshot(const std::string &id, AppConfig &app_config)
{
    for (const Snapshot &snapshot : m_snapshots)
        if (snapshot.identifier == id)
        {
            this->restore_snapshot(snapshot, app_config);
            return snapshot;
        }
    throw Slic3r::RuntimeError(std::string("Snapshot with id " + id + " was not found."));
}

void SnapshotDB::restore_snapshot(const Snapshot &snapshot, AppConfig &app_config)
{
    boost::filesystem::path data_directory = boost::filesystem::path(Slic3r::data_dir());
    boost::filesystem::path db_directory = SnapshotDB::create_db_dir();
    boost::filesystem::path snapshot_directory = db_directory / snapshot.identifier;

    // Restore INI files
    for (const char *subdir : config_subdirectories)
    {
        boost::filesystem::path src = snapshot_directory / subdir;
        boost::filesystem::path dst = data_directory / subdir;
        remove_ini_files(dst);
        if (boost::filesystem::is_directory(src))
            copy_directory_contents(src, dst);
    }

    // Update AppConfig
    snapshot.apply_selections(app_config);
    snapshot.apply_vendor_configs(app_config);
}

bool SnapshotDB::is_current_snapshot(AppConfig &app_config) const
{
    std::string on_snapshot = app_config.get("on_snapshot");
    if (on_snapshot.empty())
        return false;

    auto it_snapshot = this->snapshot(on_snapshot);
    if (it_snapshot != this->end() && it_snapshot->equal_to_current(app_config))
        return true;

    app_config.set("on_snapshot", "");
    return false;
}

SnapshotDB::const_iterator SnapshotDB::find_snapshot_with_vendor(const std::string &vendor_name,
                                                                 const Semver &config_version)
{
    auto it_found = m_snapshots.end();
    Snapshot::VendorConfig search_key;
    search_key.name = vendor_name;

    for (auto it = m_snapshots.begin(); it != m_snapshots.end(); ++it)
    {
        const Snapshot &snapshot = *it;
        auto it_vendor = std::lower_bound(snapshot.vendor_configs.begin(), snapshot.vendor_configs.end(), search_key,
                                          [](const Snapshot::VendorConfig &cfg1,
                                             const Snapshot::VendorConfig &cfg2)
                                          { return cfg1.name < cfg2.name; });
        if (it_vendor != snapshot.vendor_configs.end() && it_vendor->name == vendor_name &&
            config_version == it_vendor->version.config_version)
        {
            it_found = it;
        }
    }
    return it_found;
}

SnapshotDB::const_iterator SnapshotDB::snapshot(const std::string &id) const
{
    for (const_iterator it = m_snapshots.begin(); it != m_snapshots.end(); ++it)
        if (it->identifier == id)
            return it;
    return m_snapshots.end();
}

boost::filesystem::path SnapshotDB::create_db_dir()
{
    boost::filesystem::path data_directory = boost::filesystem::path(Slic3r::data_dir());
    boost::filesystem::path snapshots_directory = data_directory / SNAPSHOT_DIR_NAME;

    for (const boost::filesystem::path &path : {data_directory, snapshots_directory})
    {
        boost::filesystem::path subdir = path;
        subdir.make_preferred();
        if (!boost::filesystem::is_directory(subdir) && !boost::filesystem::create_directory(subdir))
            throw Slic3r::RuntimeError(std::string("Slic3r was unable to create directory at ") + subdir.string());
    }
    return snapshots_directory;
}

SnapshotDB &SnapshotDB::singleton()
{
    static SnapshotDB instance;
    static bool loaded = false;

    if (!loaded)
    {
        try
        {
            loaded = true;
            instance.load_database();
            std::vector<Index> index_data = Index::load_db();
            instance.update_versions(index_data);
        }
        catch (std::exception & /* ex */)
        {
        }
    }
    return instance;
}

const Snapshot *capture_config_snapshot_error_report(const AppConfig &app_config, Snapshot::Reason cause,
                                                     const std::string &note)
{
    try
    {
        return &SnapshotDB::singleton().capture_snapshot(app_config, cause, note);
    }
    catch (std::exception &err)
    {
        show_error(static_cast<wxWindow *>(wxGetApp().mainframe),
                   _L("Configuration snapshot creation failed.") + "\n\n" + from_u8(err.what()));
        return nullptr;
    }
}

bool capture_config_snapshot_ignore_error(const AppConfig &app_config, Snapshot::Reason cause,
                                          const std::string &note, const std::string &message,
                                          Snapshot const **psnapshot)
{
    try
    {
        const Snapshot *snapshot = &SnapshotDB::singleton().capture_snapshot(app_config, cause, note);
        if (psnapshot)
            *psnapshot = snapshot;
        return true;
    }
    catch (std::exception &err)
    {
        RichMessageDialog dlg(static_cast<wxWindow *>(wxGetApp().mainframe),
                              _L("preFlight encountered an error while creating configuration snapshot.") + "\n\n" +
                                  from_u8(err.what()) + "\n\n" + from_u8(message),
                              _L("preFlight error"), wxYES_NO);
        dlg.SetYesNoLabels(_L("Continue"), _L("Abort"));
        return dlg.ShowModal() == wxID_YES;
    }
}
