ESP::SubRecord::SubRecord() : m_RecordType(TYPE_UNKNOWN), m_Storage() {}

bool ESP::SubRecord::loadFrom(std::istream& input, uint32_t sizeOverride)
{
  static std::unordered_map<std::string, EType> s_TypeLookup{{"HEDR", TYPE_HEDR},
                                                             {"CNAM", TYPE_CNAM},
                                                             {"MAST", TYPE_MAST},
                                                             {"ONAM", TYPE_ONAM},
                                                             {"SNAM", TYPE_SNAM}};
  char typeBuffer[5];
  if (!input.read(typeBuffer, 4)) {
    if (input.gcount() == 0) {
      return false;
    } else {
      throw ESP::InvalidRecordException("sub-record incomplete (unknown type)");
    }
  }
  if (input.gcount() != 4) {
    throw ESP::InvalidRecordException(
        std::string("sub-record type incomplete (invalid type ") + typeBuffer + ")");
  }
  typeBuffer[4] = '\0';  // not sure if this is required, shouldn't be
  auto iter     = s_TypeLookup.find(std::string(typeBuffer));
  if (iter != s_TypeLookup.end()) {
    m_RecordType = iter->second;
  } else if (strncmp(typeBuffer, "XXXX", 4) == 0) {
    if (readType<uint16_t>(input) != 4) {
      throw ESP::InvalidRecordException(
          "XXXX record is supposed to be 4 bytes in size");
    }
    return loadFrom(input, readType<uint32_t>(input));
  } else {
    m_RecordType = TYPE_UNKNOWN;
  }
  uint32_t dataSize = readType<uint16_t>(input);
  if (sizeOverride != 0UL) {
    dataSize = sizeOverride;
  }
  m_Storage.resize(dataSize);
  if (dataSize > 0) {
    input.read(reinterpret_cast<char*>(m_Storage.data()), dataSize);
  }
  if (!input) {
    throw ESP::InvalidRecordException(std::string("sub-record incomplete: ") +
                                      typeBuffer);
  }
  return true;
}

