::mlspp::bytes_ns::bytes EncodeUint64AsBigEndian(uint64_t input) noexcept
{
    ::mlspp::bytes_ns::bytes encodedBuffer;
    encodedBuffer.reserve(sizeof(input));
    for (int byteIndex = static_cast<int>(sizeof(input)) - 1; byteIndex >= 0; --byteIndex) {
        const uint8_t byteValue = static_cast<uint8_t>(input >> (byteIndex * 8));
        encodedBuffer.push_back(byteValue);
    }
    return encodedBuffer;
}

::mlspp::CipherSuite SelectCiphersuiteFor(
  [[maybe_unused]] ProtocolVersion selectedVersion) noexcept
{
    return ::mlspp::CipherSuite{::mlspp::CipherSuite::ID::P256_AES128GCM_SHA256_P256};
}

ExternalSender::ExternalSender(discord::dave::ProtocolVersion protocolVersion, uint64_t groupId)
{
    ciphersuite_ = SelectCiphersuiteFor(protocolVersion);
    groupId_ = std::move(EncodeUint64AsBigEndian(groupId).as_vec());

    signaturePrivateKey_ = std::make_shared<::mlspp::SignaturePrivateKey>(
      ::mlspp::SignaturePrivateKey::generate(ciphersuite_));

    externalSender_.signature_key = signaturePrivateKey_->public_key;
    externalSender_.credential = ::mlspp::Credential::basic({0x00, 0x01, 0x01, 0x00});
}

std::vector<uint8_t> ExternalSender::GetMarshalledExternalSender()
{
    return ::mlspp::tls::marshal(externalSender_);
}

std::vector<uint8_t> ExternalSender::ProposeAdd(uint32_t epoch,
                                                std::vector<uint8_t> const& keyPackage)
{
    const auto keyPackageBytes = ::mlspp::bytes_ns::bytes(keyPackage);
    const auto keyPackageObj = ::mlspp::tls::get<::mlspp::KeyPackage>(keyPackageBytes);
    ::mlspp::Add addProposal{keyPackageObj};
    ::mlspp::Proposal proposal{addProposal};

    auto message = ::mlspp::external_proposal(
      ciphersuite_, groupId_, epoch, proposal, signerIndex_, *signaturePrivateKey_);

    bool isRevocation = false;
    ::mlspp::tls::ostream stream;
    stream << isRevocation;
    stream << std::vector<::mlspp::MLSMessage>{message};
    return stream.bytes();
}

std::pair<std::vector<uint8_t>, std::vector<uint8_t>> ExternalSender::SplitCommitWelcome(
  std::vector<uint8_t> const& serializedCommitWelcome)
{
    auto buffer = ::mlspp::bytes_ns::bytes(serializedCommitWelcome);
    ::mlspp::tls::istream reader(buffer);

    ::mlspp::MLSMessage commitMsg;
    ::mlspp::Welcome welcomeMsg;
    reader >> commitMsg;
    reader >> welcomeMsg;

    ::mlspp::tls::ostream commitStream;
    commitStream << commitMsg;
    auto commitBytes = commitStream.bytes();

    ::mlspp::tls::ostream welcomeStream;
    welcomeStream << welcomeMsg;
    auto welcomeBytes = welcomeStream.bytes();

    return std::make_pair(commitBytes, welcomeBytes);
}

