using namespace sdb;

template<typename T>
static void ValidateConversion(bool expected_validity, const std::string& input_string) {
  bool is_valid;
  T converted_value = sdb::number_utils::Atoi<T>(input_string.c_str(),
                                                  input_string.c_str() + input_string.size(), is_valid);
  ASSERT_EQ(expected_validity, is_valid);
  if (expected_validity) {
    ASSERT_EQ(input_string, std::to_string(converted_value));
    T converted_value_alt = sdb::number_utils::AtoiUnchecked<T>(
      input_string.c_str(), input_string.c_str() + input_string.size());
    ASSERT_EQ(input_string, std::to_string(converted_value_alt));
  }
}

template<typename T>
static void ValidateConversion(T expected_value, const std::string& input_string) {
  bool is_valid;
  T converted_value = sdb::number_utils::Atoi<T>(input_string.c_str(),
                                                  input_string.c_str() + input_string.size(), is_valid);
  ASSERT_TRUE(is_valid);
  ASSERT_EQ(expected_value, converted_value);
  T converted_value_alt = sdb::number_utils::AtoiUnchecked<T>(input_string.c_str(),
                                                              input_string.c_str() + input_string.size());
  ASSERT_EQ(expected_value, converted_value_alt);
}

TEST(NumberUtilsTest, testStrangeNumbers) {
  ValidateConversion<int64_t>(int64_t(0), "00");
  ValidateConversion<int64_t>(int64_t(0), "00000000000000000000000000000");
  ValidateConversion<int64_t>(int64_t(1), "01");
  ValidateConversion<int64_t>(int64_t(0), "-0");
  ValidateConversion<int64_t>(int64_t(-1), "-01");
  ValidateConversion<int64_t>(int64_t(-10), "-010");
  ValidateConversion<int64_t>(int64_t(0), "-00000");
  ValidateConversion<int64_t>(int64_t(-2), "-000002");
  ValidateConversion<int64_t>(int64_t(0), "+0");
  ValidateConversion<int64_t>(int64_t(0), "+00");
  ValidateConversion<int64_t>(int64_t(10), "+010");
  ValidateConversion<int64_t>(int64_t(0), "+00000000");
  ValidateConversion<int64_t>(int64_t(2), "+000000002");
  ValidateConversion<int64_t>(int64_t(0), "+0000000000000000000000000000000000000000");
  ValidateConversion<int64_t>(int64_t(22), "+000000000000000000000000000000000000000022");
}

TEST(NumberUtilsTest, testPredefinedConstants) {
  ValidateConversion<int16_t>(static_cast<int16_t>(INT16_MIN), std::to_string(INT16_MIN));
  ValidateConversion<int16_t>(INT16_MAX, std::to_string(INT16_MAX));
  ValidateConversion<int32_t>(INT32_MIN, std::to_string(INT32_MIN));
  ValidateConversion<int32_t>(INT32_MAX, std::to_string(INT32_MAX));
  ValidateConversion<int64_t>(INT64_MIN, std::to_string(INT64_MIN));
  ValidateConversion<int64_t>(INT64_MAX, std::to_string(INT64_MAX));
  ValidateConversion<uint8_t>(UINT8_MAX, std::to_string(UINT8_MAX));
  ValidateConversion<uint16_t>(UINT16_MAX, std::to_string(UINT16_MAX));
