void FDisplayClusterDeviceTopBottomBase::AdjustViewRect(enum EStereoscopicPass StereoPassType, int32& X, int32& Y, uint32& SizeX, uint32& SizeY) const
{
	const int ViewIndexLocal = DecodeViewportIndex(StereoPassType);
	const EStereoscopicPass PassType = DecodeStereoscopicPass(StereoPassType);
	const uint32 ViewId = DecodeViewIndex(StereoPassType);

	// Retrieve current viewport information
	FDisplayClusterRenderViewport& ActiveViewport = RenderViewports[ViewIndexLocal];

	// Set up the viewport rectangle for engine consumption
	const FIntRect& RectData = ActiveViewport.GetRect();

	if (PassType == EStereoscopicPass::eSSP_LEFT_EYE)
	{
		Y = RectData.Min.Y / 2;
	}
	else if (PassType == EStereoscopicPass::eSSP_RIGHT_EYE)
	{
		Y = SizeY / 2 + RectData.Min.Y / 2;
	}

	X = RectData.Min.X;
	SizeX = RectData.Width();
	SizeY = RectData.Height() / 2;

	// Update rendering context
	FDisplayClusterRenderViewContext& ContextRef = ActiveViewport.GetContext(ViewId);
	ContextRef.RenderTargetRect = FIntRect(X, Y, X + SizeX, Y + SizeY);

	const FIntRect& UpdatedRect = ContextRef.RenderTargetRect;
	UE_LOG(LogDisplayClusterRender, Verbose, TEXT("Adjusted view rect: ViewportIdx=%d, ViewIndex=%d, [%d,%d - %d,%d]"), 
		ViewIndexLocal, ViewId, UpdatedRect.Min.X, UpdatedRect.Min.Y, UpdatedRect.Max.X, UpdatedRect.Max.Y);
}

