TEST_CASE("hex_conversion_basic", "[hex_conversion]") {
    std::ostringstream buffer;
    auto stream_sink = std::make_shared<spdlog::sinks::ostream_sink_mt>(buffer);
    spdlog::logger test_logger("stream_logger", stream_sink);
    std::vector<unsigned char> data{9, 0xa, 0xb, 0xc, 0xff, 0xff};
    test_logger.info("{}", spdlog::to_hex(data));
    std::string result = buffer.str();
    REQUIRE(ends_with(result,
                      "0000: 09 0a 0b 0c ff ff" + std::string(spdlog::details::os::default_eol)));
}

TEST_CASE("hex_conversion_uppercase", "[hex_conversion]") {
    std::ostringstream buffer;
    auto stream_sink = std::make_shared<spdlog::sinks::ostream_sink_mt>(buffer);
    spdlog::logger test_logger("stream_logger", stream_sink);
    std::vector<unsigned char> data{9, 0xa, 0xb, 0xc, 0xff, 0xff};
    test_logger.info("{:X}", spdlog::to_hex(data));
    std::string result = buffer.str();
    REQUIRE(ends_with(result,
