TEST_CASE("hex_conversion_with_ascii", "[hex_conversion]") {
    std::ostringstream buffer;
    auto stream_sink = std::make_shared<spdlog::sinks::ostream_sink_mt>(buffer);
    spdlog::logger test_logger("stream_logger", stream_sink);
    std::vector<unsigned char> data{9, 0xa, 0xb, 0x41, 0xc, 0x4b, 0xff, 0xff};
    test_logger.info("{:Xsa}", spdlog::to_hex(data, 8));
    REQUIRE(ends_with(buffer.str(), "0000: 090A0B410C4BFFFF  ...A.K.." +
                                     std::string(spdlog::details::os::default_eol)));
}

TEST_CASE("hex_conversion_custom_line_length", "[hex_conversion]") {
    std::ostringstream buffer;
    auto stream_sink = std::make_shared<spdlog::sinks::ostream_sink_mt>(buffer);
    spdlog::logger test_logger("stream_logger", stream_sink);
    std::vector<unsigned char> data{9, 0xa, 0xb, 0x41, 0xc, 0x4b, 0xff, 0xff};

    test_logger.info("{:Xsa}", spdlog::to_hex(data, 10));
    REQUIRE(ends_with(buffer.str(), "0000: 090A0B410C4BFFFF  ...A.K.." +
                                     std::string(spdlog::details::os::default_eol)));

    test_logger.info("{:Xs}", spdlog::to_hex(data, 10));
    REQUIRE(ends_with(buffer.str(),
                      "0000: 090A0B410C4BFFFF" + std::string(spdlog::details::os::default_eol)));

    test_logger.info("{:Xsa}", spdlog::to_hex(data, 6));
    REQUIRE(ends_with(
        buffer.str(), "0000: 090A0B410C4B  ...A.K" + std::string(spdlog::details::os::default_eol) +
                       "0006: FFFF          .." + std::string(spdlog::details::os::default_eol)));

    test_logger.info("{:Xs}", spdlog::to_hex(data, 6));
    REQUIRE(ends_with(buffer.str(), "0000: 090A0B410C4B" +
                                     std::string(spdlog::details::os::default_eol) + "0006: FFFF" +
                                     std::string(spdlog::details::os::default_eol)));
}

TEST_CASE("hex_conversion_no_ascii_output", "[hex_conversion]") {
    std::ostringstream buffer;
    auto stream_sink = std::make_shared<spdlog::sinks::ostream_sink_mt>(buffer);
    spdlog::logger test_logger("stream_logger", stream_sink);
    std::vector<unsigned char> data{9, 0xa, 0xb, 0x41, 0xc, 0x4b, 0xff, 0xff};

    test_logger.info("{:Xs}", spdlog::to_hex(data, 8));
    REQUIRE(ends_with(buffer.str(),
                      "0000: 090A0B410C4BFFFF" + std::string(spdlog::details::os::default_eol)));

    test_logger.info("{:Xsna}", spdlog::to_hex(data, 8));
    REQUIRE(
        ends_with(buffer.str(), "090A0B410C4BFFFF" + std::string(spdlog::details::os::default_eol)));
}

