    JPH::Ref<JPH::SoftBodySharedSettings> generate_cloth(
        JPH::uint grid_size_x,
        JPH::uint grid_size_z,
        float spacing,
        const std::function<float(JPH::uint, JPH::uint)>& get_inv_mass,
        const std::function<JPH::Vec3(JPH::uint, JPH::uint)>& perturb_vertex,
        JPH::SoftBodySharedSettings::EBendType bend_type,
        const JPH::SoftBodySharedSettings::VertexAttributes& vertex_attrs
    ) {
        const float offset_x = -0.5f * spacing * (grid_size_x - 1);
        const float offset_z = -0.5f * spacing * (grid_size_z - 1);

        JPH::SoftBodySharedSettings* settings = new JPH::SoftBodySharedSettings;

        for (JPH::uint z = 0; z < grid_size_z; ++z)
            for (JPH::uint x = 0; x < grid_size_x; ++x) {
                JPH::SoftBodySharedSettings::Vertex vertex;
                JPH::Vec3 position = perturb_vertex(x, z) +
                                     JPH::Vec3(
                                         offset_x + x * spacing,
                                         0.0f,
                                         offset_z + z * spacing
                                     );
                position.StoreFloat3(&vertex.mPosition);
                vertex.mInvMass = get_inv_mass(x, z);
                settings->mVertices.push_back(vertex);
            }

        auto get_vertex_index = [grid_size_x](
                                    JPH::uint x, JPH::uint y
                                ) -> JPH::uint { return x + y * grid_size_x; };

        for (JPH::uint z = 0; z < grid_size_z - 1; ++z)
            for (JPH::uint x = 0; x < grid_size_x - 1; ++x) {
                JPH::SoftBodySharedSettings::Face face;
                face.mVertex[0] = get_vertex_index(x, z);
                face.mVertex[1] = get_vertex_index(x, z + 1);
                face.mVertex[2] = get_vertex_index(x + 1, z + 1);
                settings->AddFace(face);
                face.mVertex[1] = get_vertex_index(x + 1, z + 1);
                face.mVertex[2] = get_vertex_index(x + 1, z);
                settings->AddFace(face);
            }

        settings->CreateConstraints(&vertex_attrs, 1, bend_type);
        settings->Optimize();
        return settings;
    }

    JPH::Ref<JPH::SoftBodySharedSettings> create_cloth_with_fixed_corners(
        JPH::uint grid_size_x, JPH::uint grid_size_z, float spacing
    ) {
        auto inv_mass_func = [grid_size_x,
                              grid_size_z](JPH::uint x, JPH::uint z) {
            return (x == 0 && z == 0) ||
                           (x == grid_size_x - 1 && z == 0) ||
                           (x == 0 && z == grid_size_z - 1) ||
                           (x == grid_size_x - 1 && z == grid_size_z - 1)
                       ? 0.0f
                       : 1.0f;
        };
        return ::generate_cloth(
            grid_size_x,
            grid_size_z,
            spacing,
            inv_mass_func,
            [](JPH::uint, JPH::uint) { return JPH::Vec3::sZero(); },
            JPH::SoftBodySharedSettings::EBendType::None,
            { 1.0e-5f, 1.0e-5f, 1.0e-5f }
        );
    }

    JPH::Ref<JPH::SoftBodySharedSettings> create_cloth_cylinder_shape(
        const JPH::SoftBodySharedSettings::EBendType bend_type,
        const JPH::SoftBodySharedSettings::VertexAttributes& vertex_attributes,
        const double radius,
        const double height,
        const int num_segments_x,
        const int num_segments_y
    ) {
        MIRINAE_ASSERT(num_segments_x >= 3);
        MIRINAE_ASSERT(num_segments_y >= 2);
        const auto half_h = height * 0.5;
        auto settings_ptr = std::make_unique<JPH::SoftBodySharedSettings>();
        for (int y = 0; y < num_segments_y; ++y) {
            const auto y_pos = height * y / (num_segments_y - 1) - half_h;
            for (int x = 0; x < num_segments_x; ++x) {
                JPH::SoftBodySharedSettings::Vertex vertex;
                const auto theta = SUNG_TAU * x / num_segments_x;
                const JPH::Vec3 pos(
                    radius * std::cos(theta), y_pos, radius * std::sin(theta)
                );
                if (y >= num_segments_y - 1)
                    vertex.mInvMass = 0;
                else
                    vertex.mInvMass = 1;
                pos.StoreFloat3(&vertex.mPosition);
                settings_ptr->mVertices.push_back(vertex);
            }
        }

        auto get_idx = [num_segments_x,
                        num_segments_y](JPH::uint x, JPH::uint y) -> JPH::uint {
            x = x % num_segments_x;
            y = y % num_segments_y;
            return x + y * num_segments_x;
        };

        for (int y = 0; y < num_segments_y - 1; ++y) {
            for (int x = 0; x < num_segments_x; ++x) {
                JPH::SoftBodySharedSettings::Face face;
                face.mVertex[0] = get_idx(x, y);
                face.mVertex[1] = get_idx(x, y + 1);
                face.mVertex[2] = get_idx(x + 1, y + 1);
                settings_ptr->AddFace(face);
                face.mVertex[1] = get_idx(x + 1, y + 1);
                face.mVertex[2] = get_idx(x + 1, y);
                settings_ptr->AddFace(face);
            }
        }

        settings_ptr->CreateConstraints(&vertex_attributes, 1, bend_type);
        settings_ptr->Optimize();
        return settings_ptr.release();
    }
