    class DebugRendererImpl : public JPH::DebugRenderer {
    private:
        class BatchData : public JPH::RefTargetVirtual {
        public:
            void AddRef() override { ++ref_count_; }
            void Release() override { --ref_count_; }
            void add_vertex(const mirinae::DebugMesh::Vertex& v) {
                mesh_.idx_.push_back(mesh_.vtx_.size());
                mesh_.vtx_.push_back(v);
            }
            mirinae::DebugMesh mesh_;
            std::atomic_size_t ref_count_;
        };

    public:
        DebugRendererImpl() {
            this->Initialize();
            return;
        }

        void DrawLine(
            const JPH::RVec3Arg from,
            const JPH::RVec3Arg to,
            const JPH::ColorArg color
        ) override {}

        void DrawTriangle(
            const JPH::RVec3Arg v1,
            const JPH::RVec3Arg v2,
            const JPH::RVec3Arg v3,
            const JPH::ColorArg color,
            const ECastShadow shadow
        ) override {
            if (!debug_renderer_)
                return;
            debug_renderer_->tri(
                ::convert_vector(v1),
                ::convert_vector(v2),
                ::convert_vector(v3),
                ::convert_vector(color.ToVec4())
            );
        }

        void DrawGeometry(
            const JPH::RMat44Arg model_matrix,
            const JPH::AABox& world_bounds,
            const float lod_scale_sq,
            const JPH::ColorArg model_color,
            const GeometryRef& geometry,
            const ECullMode cull_mode,
            const ECastShadow cast_shadow,
            const EDrawMode draw_mode
        ) override {
            if (!debug_renderer_)
                return;
            auto ptr = geometry->mLODs[0].mTriangleBatch.GetPtr();
            auto batch = static_cast<const BatchData*>(ptr);
            if (!batch)
                return;
            debug_renderer_->mesh(batch->mesh_, ::convert_matrix(model_matrix));
        }

        Batch CreateTriangleBatch(
            const Triangle* triangles, const int triangle_count
        ) override {
            auto batch = std::make_unique<BatchData>();
            for (int i = 0; i < triangle_count; ++i) {
                auto& src_tri = triangles[i];
                for (int j = 0; j < 3; ++j) {
                    mirinae::DebugMesh::Vertex dst_vtx;
                    auto& src_vtx = src_tri.mV[j];
                    dst_vtx.pos_ = ::convert_vector(src_vtx.mPosition);
                    dst_vtx.color_ = ::convert_vector(src_vtx.mColor.ToVec4());
                    batch->add_vertex(dst_vtx);
                }
            }
            return batch.release();
        }

        Batch CreateTriangleBatch(
            const Vertex* vertices,
            const int vertex_count,
            const JPH::uint32* indices,
            const int index_count
        ) override {
            auto batch = std::make_unique<BatchData>();
            batch->mesh_.vtx_.reserve(vertex_count);
            for (int i = 0; i < vertex_count; ++i) {
                auto& v = batch->mesh_.vtx_.emplace_back();
                v.pos_ = ::convert_vector(vertices[i].mPosition);
                v.color_ = ::convert_vector(vertices[i].mColor.ToVec4());
            }
            batch->mesh_.idx_.assign(indices, indices + index_count);
            return batch.release();
        }

        void DrawText3D(
            const JPH::RVec3Arg position,
            const JPH::string_view& text,
            const JPH::ColorArg color,
            const float height
        ) override {}

        mirinae::IDebugRen* debug_renderer_ = nullptr;
    };
#endif

