    class MeshBuilderHelper {
    public:
        void add_triangle(
            const glm::vec3& v0, const glm::vec3& v1, const glm::vec3& v2
        ) {
            indices_.push_back(
                JPH::IndexedTriangle(
                    this->add_vertex(v0), this->add_vertex(v1), this->add_vertex(v2), 0
                )
            );
        }

        auto& get_vertices() const { return vertices_; }
        auto& get_indices() const { return indices_; }

    private:
        JPH::uint32 add_vertex(const JPH::Float3& v) {
            const auto idx = vertices_.size();
            vertices_.push_back(v);
            return static_cast<JPH::uint32>(idx);
        }

        JPH::uint32 add_vertex(const glm::vec3& v) {
            return this->add_vertex(JPH::Float3(v.x, v.y, v.z));
        }

        JPH::uint32 add_vertex(const JPH::RVec3& v) {
            return this->add_vertex(JPH::Float3(v.GetX(), v.GetY(), v.GetZ()));
        }

        JPH::VertexList vertices_;
        JPH::IndexedTriangleList indices_;
    };

    class ModelDataAdapter : public mirinae::IModelAccessor {
    public:
        bool position(const glm::vec3& p) override {
            vtx_buffer_[vtx_counter_] = p * scale_factor_;
            ++vtx_counter_;
            if (vtx_counter_ >= vtx_buffer_.size()) {
                mesh_builder_.add_triangle(vtx_buffer_[0], vtx_buffer_[1], vtx_buffer_[2]);
                vtx_counter_ = 0;
            }
            return true;
        }

        void set_scaling(const glm::vec3& scale) { scale_factor_ = scale; }
        auto& get_vertices() const { return mesh_builder_.get_vertices(); }
        auto& get_indices() const { return mesh_builder_.get_indices(); }

    private:
        MeshBuilderHelper mesh_builder_;
        std::array<glm::vec3, 3> vtx_buffer_;
        glm::vec3 scale_factor_{ 1, 1, 1 };
        size_t vtx_counter_ = 0;
    };

