    class MeshBodyComponent {
    public:
        bool try_initialize(
            const mirinae::cpnt::MdlActorStatic* model,
            const mirinae::cpnt::Transform* transform,
            JPH::BodyInterface& interface
        ) {
            namespace cpnt = mirinae::cpnt;
            if (!model) {
                return false;
            }
            if (!model->model_) {
                return false;
            }
            if (!model->model_->is_ready()) {
                return false;
            }

            JPH::Vec3 position(0, 0, 0);
            JPH::Quat rotation = JPH::Quat::sIdentity();
            if (transform) {
                position = ::convert_vector(transform->pos_);
                rotation = ::convert_quaternion(transform->rot_);
                model_adapter_.set_scaling(transform->scale_);
            }

            model->model_->access_positions(model_adapter_);
            JPH::MeshShapeSettings mesh_shape(
                model_adapter_.get_vertices(), model_adapter_.get_indices()
            );
            mesh_shape.mActiveEdgeCosThresholdAngle = 0.999f;
            auto result = mesh_shape.Create();
            if (result.HasError()) {
                SPDLOG_ERROR("Failed to create mesh shape: {}", result.GetError());
                return false;
            }

            shape_ = result.Get();
            JPH::BodyCreationSettings body_settings(
                shape_, position, rotation, JPH::EMotionType::Static, ::PhysicsLayers::STATIC_OBJECT
            );
            id_ = interface.CreateAndAddBody(
                body_settings, JPH::EActivation::DontActivate
            );
            ready_ = true;
            return true;
        }

        JPH::BodyID id_;
        JPH::Ref<JPH::Shape> shape_;
        ::ModelDataAdapter model_adapter_;
        bool ready_ = false;
    };

    class HeightFieldBodyComponent {
    public:
        bool try_initialize(
            const mirinae::cpnt::Terrain* terrain,
            const mirinae::cpnt::Transform* transform,
            JPH::BodyInterface& interface
        ) {
            namespace cpnt = mirinae::cpnt;
            if (!terrain) {
                return false;
            }
            if (!terrain->ren_unit_) {
                return false;
            }

            const auto height_map = terrain->ren_unit_->height_map();
            if (!height_map) {
                return false;
            }

            const auto img2d = height_map->as<dal::TDataImage2D<uint8_t>>();
            if (!img2d) {
                return false;
            }

            if (4 != img2d->channels()) {
                return false;
            }

            if (img2d->width() != img2d->height()) {
                return false;
            }

            height_data_length_ = img2d->width();
            const auto texel_count = img2d->width() * img2d->height();
            height_data_.resize(texel_count);
            for (uint32_t i = 0; i < texel_count; ++i) {
                const auto* texel = img2d->texel_ptr(
                    i % img2d->width(), i / img2d->width()
                );
                height_data_[i] = static_cast<float>(texel[0]) / 255.0f;
            }

            JPH::HeightFieldShapeSettings shape_settings(
                height_data_.data(),
                JPH::Vec3(
                    terrain->terrain_width_ * -0.5, 0, terrain->terrain_height_ * -0.5
                ),
                JPH::Vec3(
                    terrain->terrain_width_ / float(height_data_length_ - 1),
                    terrain->height_scale_,
                    terrain->terrain_height_ / float(height_data_length_ - 1)
                ),
                height_data_length_
            );

            auto result = shape_settings.Create();
            if (result.HasError()) {
                SPDLOG_ERROR(
                    "Failed to create height field shape: {}", result.GetError()
                );
                return false;
            }

            shape_ = result.Get();
            JPH::BodyCreationSettings body_settings(
                shape_,
                JPH::RVec3(),
                JPH::Quat::sIdentity(),
                JPH::EMotionType::Static,
                PhysicsLayers::STATIC_OBJECT
            );

            if (transform) {
                body_settings.mPosition = ::convert_vector(transform->pos_);
                body_settings.mRotation = ::convert_quaternion(transform->rot_);
            }

            id_ = interface.CreateAndAddBody(
                body_settings, JPH::EActivation::DontActivate
            );
            ready_ = true;
            return true;
        }

        JPH::BodyID id_;
        JPH::Ref<JPH::Shape> shape_;
        std::vector<float> height_data_;
        uint32_t height_data_length_ = 0;
        bool ready_ = false;
    };
}}  // namespace ::cpnt

