    class TaskPreSync_Mesh : public mirinae::DependingTask {
    public:
        void init(
            ::SimulationState& state,
            entt::registry& registry,
            JPH::BodyInterface& interface
        ) {
            sim_state_ = &state;
            reg_ = &registry;
            body_interface_ = &interface;
        }

        void prepare() {
            this->set_size(reg_->view<::cpnt::MeshBodyComponent>().size());
        }

        void ExecuteRange(enki::TaskSetPartition range, uint32_t tid) override {
            namespace cpnt = mirinae::cpnt;
            someone_is_preparing_ = false;
            someone_finished_preparing_ = false;

            if (!reg_ || !body_interface_)
                return;

            auto view = reg_->view<::cpnt::MeshBodyComponent>();
            auto begin = view.begin() + range.start;
            auto end = view.begin() + range.end;

            for (auto it = begin; it != end; ++it) {
                entt::entity entity = *it;
                auto& body = view.get<::cpnt::MeshBodyComponent>(entity);
                if (body.ready_)
                    continue;

                auto tform = reg_->try_get<cpnt::Transform>(entity);
                auto modl = reg_->try_get<cpnt::MdlActorStatic>(entity);

                if (body.try_initialize(modl, tform, *body_interface_))
                    someone_finished_preparing_ = true;
                else
                    someone_is_preparing_ = true;
            }

            if (someone_is_preparing_)
                sim_state_->no_simulation_.store(true);
            if (someone_finished_preparing_)
                sim_state_->need_optimization_.store(true);
        }

    private:
        ::SimulationState* sim_state_ = nullptr;
        entt::registry* reg_ = nullptr;
        JPH::BodyInterface* body_interface_ = nullptr;
        bool someone_is_preparing_ = false;
        bool someone_finished_preparing_ = false;
    };

