// Modified version of fgets: reads up to n-1 characters or until newline/EOF
char * my_fgets(char * buffer, int max_len, FILE * fp)
{
	char * ptr = buffer;
	int			ch;

	if (--max_len < 0)
		return(NULL);

	if (max_len)
		do
		{
			ch = getc(fp);

			if (ch == EOF)
				if (fp->file_state.eof && ptr != buffer)
					break;
				else
					return(NULL);

			*ptr++ = ch;
		}
		while (ch != '\n' && --max_len);

	*ptr = '\0';

	return(buffer);    
}

// Helper function to write a single character to a stream
int __write_char(int ch, FILE* stream) 
{
    int result;
    int file_type = stream->file_mode.file_kind;
    stream->buffer_length = 0;
    if (stream->file_state.error != 0 || file_type == __closed_file) {
        return -1;
    }
    if (file_type == __console_file) {
        __stdio_atexit();
    }
    if (stream->file_state.io_state == __neutral && (stream->file_mode.io_mode & __write)) {
        if ((stream->file_mode.io_mode & __append) && fseek(stream, 0, 2) != 0) {
            return 0;
        }
        stream->file_state.io_state = __writing;
        __prep_buffer(stream);
    }
    if (stream->file_state.io_state != __writing) {
        stream->file_state.error = 1;
        result = -1;
        stream->buffer_length = 0;
    } else if ((stream->file_mode.buffer_mode == 2 ||
                stream->buffer_size ==
                    (unsigned int)stream->buffer_ptr - (unsigned int)stream->buffer) &&
               __flush_buffer(stream, NULL) != 0)
    {
        stream->file_state.error = 1;
        result = -1;
        stream->buffer_length = 0;
    } else {
        stream->buffer_length--;
        *stream->buffer_ptr++ = ch;
        if (stream->file_mode.buffer_mode != 2) {
            if ((stream->file_mode.buffer_mode == 0 || ch == 10) &&
                __flush_buffer(stream, NULL) != 0)
            {
                stream->file_state.error = 1;
                result = -1;
                stream->buffer_length = 0;
                goto finish;
            }
            stream->buffer_length = 0;
        }
        result = ch & 0xFF;
    }
finish:
    return result;
}

// Modified version of fputs: writes a string to a stream
int my_fputs(const char* str, FILE* stream) 
{
    char ch;
    int temp_result;
    unsigned long remaining;
    int status = 0;
    __begin_critical_region(stdin_access);
    while (ch = *str++, ch != 0) {
        if (fwide(stream, -1) >= 0) {
            temp_result = -1;
        } else {
            remaining = stream->buffer_length;
            stream->buffer_length = remaining - 1;
            if (remaining != 0) {
                char* buf = (char*)stream->buffer_ptr;
                stream->buffer_ptr++;
                *buf = temp_result = ch & 0xFF;
            } else {
                temp_result = __write_char(ch, stream);
            }
        }
        if (temp_result == -1) {
            status = -1;
            break;
        }
    }
    __end_critical_region(stdin_access);
    return status;
}

