	HotkeySystem::HotkeySystem() :
	    IStateSerializer("hotkeys")
	{
	}

	void HotkeySystem::RegisterCommands()
	{
		auto& cmd_list = Commands::GetCommands();
		for (auto& [hash, cmd] : cmd_list)
		{
			CommandLink binding;
			m_CommandHotkeys.insert(std::make_pair(hash, binding));
		}
		m_CommandHotkeys.at("chathelper"_J).m_Chain.clear(); // ensure chat is always bound
		m_CommandHotkeys.at("chathelper"_J).m_Chain.push_back(0x54);
	}

	bool HotkeySystem::ListenAndApply(int& key_code, std::vector<int> excluded_keys)
	{
		static auto is_key_excluded = [excluded_keys](int key) -> bool {
			for (auto k : excluded_keys)
				if (k == key)
					return true;
			return false;
		};

		// VK_OEM_CLEAR is about the limit in terms of virtual key codes
		for (int scan = 0; scan < VK_OEM_CLEAR; scan++)
		{
			if ((GetKeyState(scan) & 0x8000) && scan != 1 && !is_key_excluded(scan))
			{
				key_code = scan;
				return true;
			}
		}
		return false;
	}

	// Will return the keycode if there are no labels
	std::string HotkeySystem::GetHotkeyLabel(int modifier_key)
	{
		char buffer[32];
		GetKeyNameTextA(MapVirtualKey(modifier_key, MAPVK_VK_TO_VSC) << 16, buffer, 32);
		if (std::string(buffer).empty())
			strcpy(buffer, std::to_string(modifier_key).data());
		return buffer;
	}

	// Meant to be called in a loop
	void HotkeySystem::CreateHotkey(std::vector<int>& sequence)
	{
		static auto is_key_unique = [this](int key, std::vector<int> list) -> bool {
			for (auto& existing_key : list)
				if (existing_key == key)
					return false;
			return true;
		};

		int detected_key = 0;
		if (ListenAndApply(detected_key, sequence))
		{
			MarkStateDirty();
			if (is_key_unique(detected_key, sequence))
			{
				sequence.push_back(detected_key);
			}
		}
	}

	void HotkeySystem::RunScriptImpl()
	{
		while (g_Running)
		{
			if (GetForegroundWindow() == *Pointers.Hwnd && 
			    !HUD::IS_PAUSE_MENU_ACTIVE() && 
			    !HUD::IS_SOCIAL_CLUB_ACTIVE() && 
			    !m_BeingModified && 
			    !GUI::IsUsingKeyboard())
			{
				for (auto& [hash, link] : m_CommandHotkeys)
				{
					if (link.m_Chain.empty())
						continue;

					bool all_keys_pressed = true;
					for (auto mod : link.m_Chain)
					{
						if (!(GetAsyncKeyState(mod) & 0x8000))
						{
							all_keys_pressed = false;
							break;
						}
					}

					if (all_keys_pressed && 
					    std::chrono::system_clock::now() - m_LastHotkeyTriggerTime > 100ms)
					{
						auto cmd = Commands::GetCommand(hash);
						if (cmd)
						{
							// TODO: this is the only way I can prevent chat from blocking the main loop while keeping everything else fast
							if (hash != "chathelper"_J)
								cmd->Call();
							else
							{
								FiberPool::Push([cmd] {
									cmd->Call();
								});
							}
						}
						m_LastHotkeyTriggerTime = std::chrono::system_clock::now();
					}
				}
			}
			ScriptMgr::Yield();
		}
	}

	void HotkeySystem::RunScript()
	{
		g_HotkeySystem.RunScriptImpl();
	}

	void HotkeySystem::SaveStateImpl(nlohmann::json& json_state)
	{
		for (const auto& hotkey : m_CommandHotkeys)
		{
			std::string key_str = std::to_string(hotkey.first);
			if (!hotkey.second.m_Chain.empty())
			{
				json_state[key_str] = hotkey.second.m_Chain;
			}
			else if (json_state.contains(key_str))
			{
				json_state.erase(key_str);
			}
		}
	}

	void HotkeySystem::LoadStateImpl(nlohmann::json& json_state)
	{
		for (auto& [key_str, value] : json_state.items())
		{
			if (m_CommandHotkeys.contains(static_cast<uint32_t>(std::stoul(key_str.data()))))
				m_CommandHotkeys[static_cast<uint32_t>(std::stoul(key_str.data()))].m_Chain = value.get<std::vector<int>>();
		}
	}

	void HotkeySystem::SetBeingModifed(bool state)
	{
		g_HotkeySystem.m_BeingModified = state;
	}
}

#include "decoders/processor/operators/cpu/debayer_ahd.hpp"

#include <opencv2/calib3d.hpp>
#include <opencv2/core.hpp>
#include <opencv2/core/mat.hpp>
#include <opencv2/core/types.hpp>
#include <opencv2/highgui.hpp>
#include <opencv2/imgproc.hpp>
#include <opencv2/opencv.hpp>

namespace puerhlab {
namespace CPU {

void BayerRGGB2RGB_AHD(cv::Mat& input_bayer) {
  // Color mapping: R=0, Gr=1, B=2, Gb=3 for RGGB pattern
  static int color_map[4] = {0, 1, 3, 2};
  const int height = input_bayer.rows;
  const int width  = input_bayer.cols;

  cv::Mat1f mask_red(height, width, 0.0f);
  cv::Mat1f mask_green_r(height, width, 0.0f);
  cv::Mat1f mask_green_b(height, width, 0.0f);
  cv::Mat1f mask_blue(height, width, 0.0f);

  // Construct masks based on pixel positions
  input_bayer.forEach<float>([&](float&, const int* position) {
    int row         = position[0];
    int col         = position[1];
    int channel_id  = color_map[((row % 2) * 2 + (col % 2)) % 4]; // RGGB layout

    switch (channel_id) {
      case 0:
        mask_red(row, col) = 1.0f;
        break;
      case 1:
        mask_green_r(row, col) = 1.0f;
        break;
      case 2:
        mask_blue(row, col) = 1.0f;
        break;
      case 3:
        mask_green_b(row, col) = 1.0f;
        break;
      default:
        break;
    }
  });

  cv::Mat1f raw_data = input_bayer.clone();

  cv::Mat1f green_final = input_bayer.clone();
#pragma omp parallel for schedule(dynamic)
  for (int y = 2; y < height - 2; ++y) {
    for (int x = 2; x < width - 2; ++x) {
      if (mask_red(y, x) > 0.5f || mask_blue(y, x) > 0.5f) {
        float center_val = raw_data(y, x);
        float h_mean     = 0.5f * (raw_data(y, x - 1) + raw_data(y, x + 1));
        float h_correction = 0.25f * (2.0f * center_val - raw_data(y, x - 2) - raw_data(y, x + 2));

        float v_mean     = 0.5f * (raw_data(y - 1, x) + raw_data(y + 1, x));
        float v_correction = 0.25f * (2.0f * center_val - raw_data(y - 2, x) - raw_data(y + 2, x));

        float diff_h = std::abs(raw_data(y, x - 1) - raw_data(y, x + 1));
        float diff_v = std::abs(raw_data(y - 1, x) - raw_data(y + 1, x));
        green_final(y, x) = (diff_h < diff_v) ? (h_mean + h_correction) : (v_mean + v_correction);
      }
    }
  }

  // Initialize red and blue channels at their native locations
  cv::Mat1f red_final   = input_bayer.mul(mask_red);
  cv::Mat1f blue_final  = input_bayer.mul(mask_blue);

// Interpolate missing red and blue values using directional interpolation
#pragma omp parallel for schedule(dynamic)
  for (int row = 1; row < height - 1; ++row) {
    for (int col = 1; col < width - 1; ++col) {
      // --- Red channel interpolation ---
      if (mask_red(row, col) < 0.5f) {
        float predicted_red = 0.0f;
        if (mask_green_r(row, col) > 0.5f) {
          // On green-red row: use horizontal neighbors
          float left_diff  = red_final(row, col - 1) - green_final(row, col - 1);
          float right_diff = red_final(row, col + 1) - green_final(row, col + 1);
          predicted_red    = green_final(row, col) + 0.5f * (left_diff + right_diff);
        } else if (mask_green_b(row, col) > 0.5f) {
          // On green-blue row: use vertical neighbors
          float up_diff   = red_final(row - 1, col) - green_final(row - 1, col);
          float down_diff = red_final(row + 1, col) - green_final(row + 1, col);
          predicted_red   = green_final(row, col) + 0.5f * (up_diff + down_diff);
        } else if (mask_blue(row, col) > 0.5f) {
          // At blue pixel: use diagonal neighbors
          float d1 = red_final(row - 1, col - 1) - green_final(row - 1, col - 1);
          float d2 = red_final(row - 1, col + 1) - green_final(row - 1, col + 1);
          float d3 = red_final(row + 1, col - 1) - green_final(row + 1, col - 1);
          float d4 = red_final(row + 1, col + 1) - green_final(row + 1, col + 1);
          predicted_red = green_final(row, col) + 0.25f * (d1 + d2 + d3 + d4);
        } else {
          // fallback: average all four directions
          float left_diff  = red_final(row, col - 1) - green_final(row, col - 1);
          float right_diff = red_final(row, col + 1) - green_final(row, col + 1);
          float up_diff    = red_final(row - 1, col) - green_final(row - 1, col);
          float down_diff  = red_final(row + 1, col) - green_final(row + 1, col);
          predicted_red    = green_final(row, col) + 0.25f * (left_diff + right_diff + up_diff + down_diff);
        }
        red_final(row, col) = predicted_red;
      }

      // --- Blue channel interpolation ---
      if (mask_blue(row, col) < 0.5f) {
        float predicted_blue = 0.0f;
        if (mask_green_b(row, col) > 0.5f) {
          // On green-blue row: use horizontal neighbors
          float left_diff  = blue_final(row, col - 1) - green_final(row, col - 1);
          float right_diff = blue_final(row, col + 1) - green_final(row, col + 1);
          predicted_blue   = green_final(row, col) + 0.5f * (left_diff + right_diff);
        } else if (mask_green_r(row, col) > 0.5f) {
          // On green-red row: use vertical neighbors
          float up_diff   = blue_final(row - 1, col) - green_final(row - 1, col);
          float down_diff = blue_final(row + 1, col) - green_final(row + 1, col);
          predicted_blue  = green_final(row, col) + 0.5f * (up_diff + down_diff);
        } else if (mask_red(row, col) > 0.5f) {
          // At red pixel: use diagonal neighbors
          float d1 = blue_final(row - 1, col - 1) - green_final(row - 1, col - 1);
          float d2 = blue_final(row - 1, col + 1) - green_final(row - 1, col + 1);
          float d3 = blue_final(row + 1, col - 1) - green_final(row + 1, col - 1);
          float d4 = blue_final(row + 1, col + 1) - green_final(row + 1, col + 1);
          predicted_blue = green_final(row, col) + 0.25f * (d1 + d2 + d3 + d4);
        } else {
          // fallback: average all four directions
          float left_diff  = blue_final(row, col - 1) - green_final(row, col - 1);
          float right_diff = blue_final(row, col + 1) - green_final(row, col + 1);
          float up_diff    = blue_final(row - 1, col) - green_final(row - 1, col);
          float down_diff  = blue_final(row + 1, col) - green_final(row + 1, col);
          predicted_blue   = green_final(row, col) + 0.25f * (left_diff + right_diff + up_diff + down_diff);
        }
        blue_final(row, col) = predicted_blue;
      }
    }
  }

  // Combine interpolated channels into final RGB image
  std::vector<cv::Mat> rgb_channels = {red_final, green_final, blue_final};
  cv::merge(rgb_channels, input_bayer);
}

