// Helper to extract millennium from time structure
template<typename T>
struct TimeMillenniumExtractor : public InitSessionTimezone<T>,
                                  public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE int64_t computeMillennium(const std::tm& datetime) {
    int64_t year_val = 1900 + datetime.tm_year;
    if (year_val > 0) {
      return (year_val + 999) / 1000;
    } else {
      return year_val / 1000;
    }
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& output,
                                const arg_type<Timestamp>& timestamp_val) {
    output = computeMillennium(getDateTime(timestamp_val, this->timeZone_));
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& output, const arg_type<Date>& date_val) {
    output = computeMillennium(getDateTime(date_val));
  }

  FOLLY_ALWAYS_INLINE void call(
    int64_t& output, const arg_type<TimestampWithTimezone>& timestamptz_val) {
    auto timestamp_val = this->toTimestamp(timestamptz_val);
    output = computeMillennium(getDateTime(timestamp_val, nullptr));
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& output,
                                const arg_type<Interval>& interval_data) {
    auto unpacked = UnpackInterval(interval_data);
    output = unpacked.month / 12000;
  }
};

// Helper to extract century from time structure
template<typename T>
struct TimeCenturyExtractor : public InitSessionTimezone<T>,
                               public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE int64_t computeCentury(const std::tm& datetime) {
    int64_t year_val = 1900 + datetime.tm_year;
    if (year_val > 0) {
      return (year_val + 99) / 100;
    } else {
      return year_val / 100;
    }
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& output,
                                const arg_type<Timestamp>& timestamp_val) {
    output = computeCentury(getDateTime(timestamp_val, this->timeZone_));
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& output, const arg_type<Date>& date_val) {
    output = computeCentury(getDateTime(date_val));
  }

  FOLLY_ALWAYS_INLINE void call(
    int64_t& output, const arg_type<TimestampWithTimezone>& timestamptz_val) {
    auto timestamp_val = this->toTimestamp(timestamptz_val);
    output = computeCentury(getDateTime(timestamp_val, nullptr));
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& output,
                                const arg_type<Interval>& interval_data) {
    auto unpacked = UnpackInterval(interval_data);
    output = unpacked.month / 1200;
  }
};

// Helper to extract decade from time structure
template<typename T>
struct TimeDecadeExtractor : public InitSessionTimezone<T>,
