// Helper to extract seconds with fractional part
template<typename T>
struct SecondWithFractionExtractor : public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE void call(double& output,
                                const arg_type<Timestamp>& timestamp_val) {
    auto datetime = getDateTime(timestamp_val, nullptr);
    double secs = datetime.tm_sec;
    double micros = timestamp_val.getNanos() / 1000.0;
    micros = std::fmod(micros, 1000000.0);
    output = secs + (micros / 1000000.0);
  }

  FOLLY_ALWAYS_INLINE void call(double& output, const arg_type<Date>& date_val) {
    auto datetime = getDateTime(date_val);
    output = datetime.tm_sec;
  }

  FOLLY_ALWAYS_INLINE void call(
    double& output, const arg_type<TimestampWithTimezone>& timestamptz_val) {
    auto timestamp_val = this->toTimestamp(timestamptz_val);
    auto datetime = getDateTime(timestamp_val, nullptr);
    double secs = datetime.tm_sec;
    double micros = timestamp_val.getNanos() / 1000.0;
    micros = std::fmod(micros, 1000000.0);
    output = secs + (micros / 1000000.0);
  }

  FOLLY_ALWAYS_INLINE void call(double& output,
                                const arg_type<Interval>& interval_data) {
    auto unpacked = UnpackInterval(interval_data);
    double total_secs = unpacked.time / 1000000.0;
    output = std::fmod(total_secs, 60.0);
  }
};

// Helper to extract milliseconds
template<typename T>
struct MillisecondExtractor : public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE void call(double& output,
                                const arg_type<Timestamp>& timestamp_val) {
    auto datetime = getDateTime(timestamp_val, nullptr);
    double secs = datetime.tm_sec;
    double micros = timestamp_val.getNanos() / 1000.0;
    micros = std::fmod(micros, 1000000.0);
    output = secs * 1000.0 + (micros / 1000.0);
  }

  FOLLY_ALWAYS_INLINE void call(
    double& output, const arg_type<TimestampWithTimezone>& timestamptz_val) {
    auto timestamp_val = this->toTimestamp(timestamptz_val);
    auto datetime = getDateTime(timestamp_val, nullptr);
    double secs = datetime.tm_sec;
    double micros = timestamp_val.getNanos() / 1000.0;
    micros = std::fmod(micros, 1000000.0);
    output = secs * 1000.0 + (micros / 1000.0);
  }

  FOLLY_ALWAYS_INLINE void call(double& output,
                                const arg_type<Interval>& interval_data) {
    auto unpacked = UnpackInterval(interval_data);
    double total_millis = unpacked.time / 1000.0;
    output = std::fmod(total_millis, 60000.0);
  }
};

// Helper to extract microseconds
template<typename T>
struct MicrosecondExtractor : public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE void call(double& output,
                                const arg_type<Timestamp>& timestamp_val) {
    auto datetime = getDateTime(timestamp_val, nullptr);
    double secs = datetime.tm_sec;
    double micros = timestamp_val.getNanos() / 1000.0;
    micros = std::fmod(micros, 1000000.0);
    output = secs * 1000000.0 + micros;
  }

  FOLLY_ALWAYS_INLINE void call(
    double& output, const arg_type<TimestampWithTimezone>& timestamptz_val) {
    auto timestamp_val = this->toTimestamp(timestamptz_val);
    auto datetime = getDateTime(timestamp_val, nullptr);
    double secs = datetime.tm_sec;
    double micros = timestamp_val.getNanos() / 1000.0;
    micros = std::fmod(micros, 1000000.0);
    output = secs * 1000000.0 + micros;
  }

  FOLLY_ALWAYS_INLINE void call(double& output,
                                const arg_type<Interval>& interval_data) {
    auto unpacked = UnpackInterval(interval_data);
    output = std::fmod(static_cast<double>(unpacked.time), 60000000.0);
  }
};

