#include <OTwo/Archives/OjmArchive.hpp>
#include <Genode/IO/FileSystem/FileSystem.hpp>
#include <string>

bool OjmArchive::LoadFromFile(const std::string& filePath)
{
    auto fileSystem = Gx::FileSystem::Open(filePath);
    char buffer[3];
    if (fileSystem->read(&buffer[0], 3) != 3)
        return false;
    delete fileSystem.release(); // Ensure file handle is closed
    const auto header = std::string(buffer, 3);
    if (header == "M30")
    {
        m_archiveType = ArchiveType::M30;
        return M30Archive::LoadFromFile(filePath);
    }
    else if (header == "OMC" || header == "OJM")
    {
        m_archiveType = ArchiveType::OMC;
        return OmcArchive::LoadFromFile(filePath);
    }
    return false;
}

Gx::ResourcePtr<sf::InputStream> OjmArchive::Open(unsigned int entryIndex) const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::Open(entryIndex);
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::Open(entryIndex);
    return nullptr;
}

Gx::ResourcePtr<sf::InputStream> OjmArchive::Open(const std::string& entryName) const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::Open(entryName);
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::Open(entryName);
    return nullptr;
}

bool OjmArchive::Contains(const std::string& resourceName) const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::Contains(resourceName);
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::Contains(resourceName);
    return false;
}

std::vector<std::unique_ptr<Gx::FileInfo>> OjmArchive::GetFileEntries() const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::GetFileEntries();
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::GetFileEntries();
    return {};
}

std::unique_ptr<Gx::FileInfo> OjmArchive::GetFileInfo(const std::string& resourceName) const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::GetFileInfo(resourceName);
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::GetFileInfo(resourceName);
    return {};
}

std::optional<std::size_t> OjmArchive::ReadFile(const std::string& resourceName, void* outputBuffer, std::size_t bufferSize) const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::ReadFile(resourceName, outputBuffer, bufferSize);
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::ReadFile(resourceName, outputBuffer, bufferSize);
    return std::nullopt;
}

std::optional<std::size_t> OjmArchive::GetFileSize(const std::string& resourceName) const
{
    if (m_archiveType == ArchiveType::M30)
        return M30Archive::GetFileSize(resourceName);
    else if (m_archiveType == ArchiveType::OMC)
        return OmcArchive::GetFileSize(resourceName);
    return -1;
}

#include "StdAfx.h"
#ifdef FOOBAR2000_DESKTOP_WINDOWS
#include "window_placement_helper.h"
#include <SDK/config_object.h>

static bool g_window_position_tracking_active()
{
	return standard_config_objects::query_remember_window_positions();
}

static BOOL CALLBACK __MonitorEnumProcHelper(
  HMONITOR hMonitor,  
  HDC hdcMonitor,     
  LPRECT lprcMonitor, 
  LPARAM dwData       
  ) {
	RECT * boundary = (RECT*)dwData;
	RECT combined;
	if (UnionRect(&combined, boundary, lprcMonitor)) {
		*boundary = combined;
	}
	return TRUE;
}

static bool is_valid_window_area(const RECT * area) {
	RECT full_clip = {};
	if (EnumDisplayMonitors(NULL, NULL, __MonitorEnumProcHelper, (LPARAM)&full_clip)) {
		const LONG safety_margin = 4;
		const LONG screen_width = full_clip.right - full_clip.left;
		const LONG screen_height = full_clip.bottom - full_clip.top;

		const LONG window_width = area->right - area->left;
		const LONG window_height = area->bottom - area->top;
		if (window_width > screen_width * safety_margin || window_height > screen_height * safety_margin) return false;
	}

	return MonitorFromRect(area, MONITOR_DEFAULTTONULL) != NULL;
}

bool cfg_window_placement::read_from_window(HWND hwnd)
{
	WINDOWPLACEMENT wp = {};
	if (g_window_position_tracking_active()) {
		wp.length = sizeof(wp);
		if (!GetWindowPlacement(hwnd, &wp)) {
			PFC_ASSERT(!"GetWindowPlacement failed!");
			memset(&wp, 0, sizeof(wp));
		} else {
			if (!IsWindowVisible(hwnd)) wp.showCmd = SW_HIDE;
		}
	}
	try { set(wp); } catch(...) {} 
	return wp.length == sizeof(wp);
}

bool apply_window_state(HWND hwnd, WINDOWPLACEMENT const& state, bool permit_invisible) {
	bool success = false;
	if (state.length == sizeof(state) && is_valid_window_area(&state.rcNormalPosition))
	{
		if (permit_invisible || state.showCmd != SW_HIDE) {
			if (state.showCmd == SW_HIDE && (state.flags & WPF_RESTORETOMAXIMIZED)) {
				auto temp = state;
				temp.showCmd = SW_SHOWMINIMIZED;
				if (SetWindowPlacement(hwnd, &temp)) {
					ShowWindow(hwnd, SW_HIDE);
					success = true;
				}
			} else {
				if (SetWindowPlacement(hwnd, &state)) {
					success = true;
				}
			}
		}
	}
	return success;
}

bool cfg_window_placement::apply_to_window(HWND hwnd, bool permit_invisible) {
	bool success = false;
	if (g_window_position_tracking_active())
	{
		auto state = get();
		success = apply_window_state(hwnd, state, permit_invisible);
	}
	return success;
}

void cfg_window_placement::on_window_created_passive(HWND hwnd) {
}

bool cfg_window_placement::on_window_created(HWND hwnd, bool permit_invisible) {
	return apply_to_window(hwnd, permit_invisible);
}

void cfg_window_placement::on_window_destroyed(HWND hwnd)
{
	read_from_window(hwnd);
}

static BOOL adjust_window_dimensions(HWND target, unsigned width, unsigned height)
{
	if (width != ~0u && height != ~0u)
		return SetWindowPos(target, 0, 0, 0, width, height, SWP_NOACTIVATE | SWP_NOMOVE | SWP_NOZORDER);
	else
		return FALSE;
}

bool cfg_window_size::apply_to_window(HWND hwnd) {
	bool success = false;
	if (g_window_position_tracking_active())
	{
		auto dims = get();
		if (dims.cx > 0 && dims.cy > 0) {
			if (adjust_window_dimensions(hwnd, dims.cx, dims.cy)) success = true;
		}
	}
	return success;
}

bool cfg_window_size::on_window_created(HWND hwnd)
{
	return apply_to_window(hwnd);
}

void cfg_window_size::on_window_destroyed(HWND hwnd)
{
	read_from_window(hwnd);
}

bool cfg_window_size::read_from_window(HWND hwnd)
{
	SIZE dimensions = {};
	if (g_window_position_tracking_active())
	{
		RECT bounds;
		if (GetWindowRect(hwnd, &bounds))
		{
			dimensions.cx = bounds.right - bounds.left;
			dimensions.cy = bounds.bottom - bounds.top;
		}
	}
	set(dimensions);
	return dimensions.cx > 0 && dimensions.cy > 0;
}
