#include "compiler/frontend/lexer.h"
#include "compiler/common/common_defs.h"
#include <string>
using namespace COMPILER;

// Mapping from keywords and special tokens to their corresponding token kinds
static std::unordered_map<std::string, Token::Kind> symbolMap = {
#define OPCODE(STR) {#STR, Token::TK_OP_##STR},
#include "compiler/mir/opcodes.def"
#undef OPCODE

#define PRIM_TYPE(TEXT, KIND, SIZE) {#TEXT, Token::TK_PT_##TEXT},
#include "compiler/mir/prim_types.def"
#undef PRIM_TYPE

#define KEYWORD(STR) {#STR, Token::TK_KW_##STR},
#include "compiler/mir/keywords.def"
#undef KEYWORD

#define CONDCODE(TEXT, PREDICATE, VALUE) {#TEXT, Token::TK_CC_##TEXT},
#include "compiler/mir/cond_codes.def"
#undef CONDCODE
};

class Lexer::Impl {
public:
  // Constructor initializes the lexer with input range
  Impl(const char *begin, const char *finish)
      : _begin(begin), _pos(begin), _finish(finish) {}

  // Fetches the next token from the input stream
  Token getNextToken() {
    ZEN_ASSERT(_pos <= _finish);
    skipSpacesAndComments();
    _begin = _pos;

    if (isAtEnd())
      return createToken(Token::_EOF);

    char currentChar = readNextChar();

    if (isLetter(currentChar))
      return handleIdentifier();

    if (isNumeric(currentChar) || (currentChar == '-' && isNumeric(peekNext())))
      return parseNumber();

    switch (currentChar) {
    case '(':
      return createToken(Token::LPAR);
    case ')':
      return createToken(Token::RPAR);
    case '[':
      return createToken(Token::LBRACKET);
    case ']':
      return createToken(Token::RBRACKET);
    case '{':
      return createToken(Token::LBRACE);
    case '}':
      return createToken(Token::RBRACE);
    case '%':
      return createToken(Token::PERCENT);
    case '$':
      return createToken(Token::DOLLAR);
    case '@':
      return createToken(Token::AT);
    case '-':
      return createToken(matchNext('>') ? Token::ARROW : Token::MINUS);
    case '=':
      return createToken(Token::EQUAL);
    case ':':
      return createToken(Token::COLON);
    case ',':
      return createToken(Token::COMMA);
    case '.':
      return createToken(Token::DOT);
    case '*':
      return createToken(Token::STAR);
    case '\0':
      return createToken(Token::_EOF);
    default:
      throw getError(ErrorCode::UnsupportedToken);
    }
  }

private:
  class LexicalError {};

  // Check if next character matches expected one and advance if so
  bool matchNext(char expected) {
    ZEN_ASSERT(!isAtEnd());
    if (*_pos != expected)
      return false;
    _pos++;
    return true;
  }

  // Look at current character without advancing
  char peekNext() const { return *_pos; }

  // Read current character and advance position
  char readNextChar() {
    ZEN_ASSERT(_pos < _finish);
    return *_pos++;
  }

  // Determine if a character is alphabetic
  bool isLetter(char c) const {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
  }

  // Determine if a character is numeric digit
  bool isNumeric(char c) const { return c >= '0' && c <= '9'; }

  // Handle identifier or keyword recognition
  Token handleIdentifier() {
    while (true) {
      char c = peekNext();
      if (isLetter(c))
        readNextChar();
      else if (isNumeric(c))
        readNextChar();
      else if (c == '_')
        readNextChar();
      else
        break;
    }

    std::string name(_begin, _pos - _begin);
    auto iter = symbolMap.find(name);
    if (iter != symbolMap.end()) {
      return createToken(iter->second);
    }
    return createToken(Token::IDENTIFIER);
  }

  // Parse numeric literals (integers and floats)
  Token parseNumber() {
    while (isNumeric(peekNext()))
      readNextChar();

    if (peekNext() == '.') {
      readNextChar();
      while (isNumeric(peekNext()))
        readNextChar();
    }

    return createToken(Token::NUMBER);
  }

  // Check if we've reached end of input
  bool isAtEnd() const { return _pos == _finish; }

  // Create a token with given kind and source span
  Token createToken(Token::Kind type) const {
    return {type, _begin, static_cast<size_t>(_pos - _begin)};
  }

  // Skip whitespace and single-line comments
  void skipSpacesAndComments() {
    while (true) {
      char c = peekNext();
      switch (c) {
      case ' ':
      case '\r':
      case '\t':
      case '\n':
        readNextChar();
        break;
      case ';': // comment starts with semicolon
        while (peekNext() != '\n' && !isAtEnd())
          readNextChar();
        break;
      default:
        return;
      }
    }
  }

private:
  const char *_begin;   // Start of current token
  const char *_pos;     // Current parsing position
  const char *_finish;  // End of input
};

// Public interface implementation
Lexer::Lexer(const char *start, const char *end)
    : _impl(new Impl(start, end)) {}

Lexer::~Lexer() = default;

Token Lexer::nextToken() { 
  return _impl->getNextToken(); 
}

