// Aliases for time durations
using HoursType = std::chrono::hours;
using MinutesType = std::chrono::minutes;

// Java class references and method/field IDs
jclass g_classHoursMinutes;
jmethodID g_ctorHoursMinutes;
jfieldID g_fieldHours;
jfieldID g_fieldMinutes;

jclass g_classTimespan;
jmethodID g_ctorTimespan;
jfieldID g_fieldStart;
jfieldID g_fieldEnd;

jclass g_classTimetable;
jmethodID g_ctorTimetable;
jfieldID g_fieldWorkingSpan;
jfieldID g_fieldClosedSpans;
jfieldID g_fieldIsFullDay;
jfieldID g_fieldWeekdays;

// Helper: Convert native hours/minutes to Java HoursMinutes object
jobject CreateJavaHoursMinutes(JNIEnv * env, jlong h, jlong m)
{
  static jclass const dateUtilsClass = jni::GetGlobalClassRef(env, "app/organicmaps/sdk/util/DateUtils");
  static jmethodID const is24HourFormatMethod =
      jni::GetStaticMethodID(env, dateUtilsClass, "is24HourFormat", "(Landroid/content/Context;)Z");
  jobject context = android::Platform::Instance().GetContext();
  jboolean const use24Hour = env->CallStaticBooleanMethod(dateUtilsClass, is24HourFormatMethod, context);
  jobject const hmObj = env->NewObject(g_classHoursMinutes, g_ctorHoursMinutes, h, m, use24Hour);
  ASSERT(hmObj, (jni::DescribeException()));
  return hmObj;
}

// Overload: Create Timespan from Java objects
jobject CreateJavaTimespan(JNIEnv * env, jobject startTime, jobject endTime)
{
  jobject const span = env->NewObject(g_classTimespan, g_ctorTimespan, startTime, endTime);
  ASSERT(span, (jni::DescribeException()));
  return span;
}

// Overload: Create Timespan from native Timespan
jobject CreateJavaTimespan(JNIEnv * env, osmoh::Timespan const & span)
{
  auto const start = span.GetStart();
  auto const end = span.GetEnd();
  return CreateJavaTimespan(env,
                            CreateJavaHoursMinutes(env, start.GetHoursCount(), start.GetMinutesCount()),
                            CreateJavaHoursMinutes(env, end.GetHoursCount(), end.GetMinutesCount()));
}

// Overload: Create Timetable from Java components
jobject CreateJavaTimetable(JNIEnv * env, jobject workSpan, jobjectArray closedSpans, bool fullDay, jintArray days)
{
  jobject const ttObj = env->NewObject(g_classTimetable, g_ctorTimetable, workSpan, closedSpans, fullDay, days);
  ASSERT(ttObj, (jni::DescribeException()));
  return ttObj;
}

// Overload: Create Timetable from native TimeTable
jobject CreateJavaTimetable(JNIEnv * env, TimeTable const & tt)
{
  auto const excludeSpans = tt.GetExcludeTime();
  std::set<Weekday> weekdaysSet = tt.GetOpeningDays();
  std::vector<int> weekdaysVec;
  weekdaysVec.reserve(weekdaysSet.size());
  std::transform(weekdaysSet.begin(), weekdaysSet.end(), std::back_inserter(weekdaysVec),
                 [](Weekday wd) { return static_cast<int>(wd); });

  jintArray jWeekdays = env->NewIntArray(static_cast<jsize>(weekdaysVec.size()));
  env->SetIntArrayRegion(jWeekdays, 0, static_cast<jsize>(weekdaysVec.size()), weekdaysVec.data());

  jobjectArray jClosed = jni::ToJavaArray(
      env, g_classTimespan, excludeSpans,
      [env](JNIEnv * e, osmoh::Timespan const & ts) { return CreateJavaTimespan(e, ts); });

  return CreateJavaTimetable(env,
                             CreateJavaTimespan(env, tt.GetOpeningTime()),
                             jClosed,
                             tt.IsTwentyFourHours(),
                             jWeekdays);
}

// Convert TimeTableSet to Java array
jobjectArray CreateJavaTimetables(JNIEnv * env, TimeTableSet & tts)
{
  size_t const count = tts.Size();
  jobjectArray result = env->NewObjectArray(static_cast<jsize>(count), g_classTimetable, nullptr);
  for (size_t idx = 0; idx < count; ++idx)
  {
    jni::TScopedLocalRef jTable(env, CreateJavaTimetable(env, tts.Get(idx)));
    env->SetObjectArrayElement(result, static_cast<jsize>(idx), jTable.get());
  }
  return result;
}

// Convert Java HoursMinutes to native HourMinutes
HourMinutes ConvertFromJavaHoursMinutes(JNIEnv * env, jobject jHM)
{
  jlong const hrs = env->GetLongField(jHM, g_fieldHours);
  jlong const mins = env->GetLongField(jHM, g_fieldMinutes);
  return HourMinutes(HoursType(hrs) + MinutesType(mins));
}

// Convert Java Timespan to native Timespan
Timespan ConvertFromJavaTimespan(JNIEnv * env, jobject jSpan)
{
  Timespan span;
  span.SetStart(ConvertFromJavaHoursMinutes(env, env->GetObjectField(jSpan, g_fieldStart)));
  span.SetEnd(ConvertFromJavaHoursMinutes(env, env->GetObjectField(jSpan, g_fieldEnd)));
  return span;
}

// Convert Java Timetable to native TimeTable
TimeTable ConvertFromJavaTimetable(JNIEnv * env, jobject jTT)
{
  TimeTable tt = TimeTable::GetPredefinedTimeTable();

  // Process weekdays
  jintArray jDays = static_cast<jintArray>(env->GetObjectField(jTT, g_fieldWeekdays));
  int * daysArr = env->GetIntArrayElements(jDays, nullptr);
  jint len = env->GetArrayLength(jDays);

  std::set<Weekday> weekdays;
  for (int i = 0; i < len; ++i)
    weekdays.insert(ToWeekday(daysArr[i]));

  tt.SetOpeningDays(weekdays);
  env->ReleaseIntArrayElements(jDays, daysArr, JNI_FALSE);

  // Set full-day flag
  tt.SetTwentyFourHours(env->GetBooleanField(jTT, g_fieldIsFullDay));

  // Set working time
  tt.SetOpeningTime(ConvertFromJavaTimespan(env, env->GetObjectField(jTT, g_fieldWorkingSpan)));

  // Process closed spans
  jobjectArray jClosed = static_cast<jobjectArray>(env->GetObjectField(jTT, g_fieldClosedSpans));
  len = env->GetArrayLength(jClosed);
  for (int i = 0; i < len; ++i)
  {
    jni::TScopedLocalRef jSpan(env, env->GetObjectArrayElement(jClosed, i));
    if (jSpan.get())
      tt.AddExcludeTime(ConvertFromJavaTimespan(env, jSpan.get()));
  }

  return tt;
}

// Convert Java Timetable array to TimeTableSet
TimeTableSet ConvertFromJavaTimetables(JNIEnv * env, jobjectArray jTts)
{
  TimeTableSet tts;
  int const arrSize = env->GetArrayLength(jTts);

  if (arrSize > 0)
  {
    tts.Replace(ConvertFromJavaTimetable(env, env->GetObjectArrayElement(jTts, 0)), 0);
    for (int i = 1; i < arrSize; ++i)
    {
      jni::TScopedLocalRef timetable(env, env->GetObjectArrayElement(jTts, i));
      tts.Append(ConvertFromJavaTimetable(env, timetable.get()));
    }
  }

  return tts;
}
