{
  TimeTableSet tts;
  std::string const source = jni::ToNativeString(env, jSource);
  if (!source.empty() && MakeTimeTableSet(OpeningHours(source), tts))
    return CreateJavaTimetables(env, tts);
  return nullptr;
}

