                                                                                                jclass clazz,
                                                                                                jobjectArray jTts)
{
  TimeTableSet tts = ConvertFromJavaTimetables(env, jTts);
  std::stringstream sstr;
  sstr << MakeOpeningHours(tts).GetRule();
  return jni::ToJavaString(env, sstr.str());
}

