  curs_set(0);
  noecho();
  bkgd(COLOR_BLACK);
  start_color();
  init_pair(GREEN_BLACK, COLOR_GREEN, COLOR_BLACK);
  init_pair(YELLOW_BLACK, COLOR_YELLOW, COLOR_BLACK);
  init_pair(RED_BLACK, COLOR_RED, COLOR_BLACK);
  init_pair(WHITE_BLACK, COLOR_WHITE, COLOR_BLACK);
  init_pair(BLACK_WHITE, COLOR_BLACK, COLOR_WHITE);
  refresh();
  clear();
  running_ = true;
}

int Screen::Columns(void) const { return COLS; }
int Screen::Rows(void) const { return LINES; }

void Screen::ApplyColor(ColorPair color) const {
  if (color == INVALID) {
    return;
  }
  if (IsReady()) {
    active_color_pair_ = color;
    attron(COLOR_PAIR(color));
  }
}

void Screen::Print(int x, int y, const char* text) const {
  if (IsReady()) {
    mvaddstr(y, x, text);
  }
}

void Screen::Print(const char* text) const {
  if (IsReady()) {
    addstr(text);
  }
}

void Screen::RemoveColor(void) const {
  if (IsReady()) {
    attroff(COLOR_PAIR(active_color_pair_));
    active_color_pair_ = INVALID;
  }
}

void Screen::Print(int x, int y, ColorPair color, const char* text) const {
  if (IsReady()) {
    attron(COLOR_PAIR(color));
    mvaddstr(y, x, text);
    attroff(COLOR_PAIR(color));
  }
}

void Screen::MoveRelative(int dx, int dy) const {
  if (IsReady()) {
    int x, y;
    getyx(stdscr, y, x);
    move(y + dy, x + dx);
  }
}

void Screen::HighlightRow(int row_index) {
  if (IsReady() && row_index < Rows()) {
    ApplyColor(WHITE_BLACK);
    for (int col = 0; col < Columns(); ++col) {
      chtype ch = mvinch(row_index + highlight_offset_, col);
      ch &= A_CHARTEXT;
      if (ch == ' ') {
        mvaddch(row_index + highlight_offset_, col, ch);
      }
    }
    RemoveColor();
    ApplyColor(BLACK_WHITE);
    for (int col = 0; col < Columns(); ++col) {
      chtype ch = mvinch(row_index, col);
      mvaddch(row_index, col, ch & A_CHARTEXT);
    }
    RemoveColor();
  }
}

int Screen::ProcessInput(int key) {
  switch (current_mode_) {
    case Mode::ShowHelp:
      if (KEY_BACKSPACE == key) {
        current_mode_ = Mode::RenderData;
        clear();
        key = 27;
      }
      break;
    case Mode::RenderData:
      if ('h' == key || 'H' == key) {
        current_mode_ = Mode::ShowHelp;
        clear();
      }
      break;
    default: {
    }
  }
  return key;
}

void Screen::MainLoop() {
  if (stdscr == nullptr || active_renderable_ == nullptr) {
    return;
  }
  highlight_offset_ = 0;
  void (Screen::*displayRoutines[])(int) = {&Screen::DisplayRenderableData, &Screen::DisplayHelpCommands};
  do {
    int key = getch();
    if (key == 'q' || key == 'Q' || key == 27) {
      running_ = false;
      break;
    }
    key = ProcessInput(key);
    (this->*displayRoutines[static_cast<int>(current_mode_)])(key);

    double fps = active_renderable_->frame_ratio();
    if (fps < MinimumHalfFrameRate) {
      fps = MinimumHalfFrameRate;
    }
    int delay_ms = static_cast<int>(1000.0 / fps);
    delay_ms >>= 1;
    std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms));
  } while (running_);
}

void Screen::AdjustSize(void) {
  if (IsReady()) {
    clear();
    refresh();
  }
}

void Screen::DisplayRenderableData(int key) {
  erase();
  int total_lines = active_renderable_->Render(this, key);
  const int visible_rows = std::min(Rows(), total_lines);
  int* current_row = active_renderable_->row_index();
  HighlightRow(*current_row);
  move(*current_row, 0);
  refresh();

  switch (key) {
    case 's':
    case 'S':
    case KEY_DOWN:
      ++(*current_row);
      highlight_offset_ = -1;
      if (*current_row >= visible_rows) {
        *current_row = visible_rows - 1;
      }
      break;
    case 'w':
    case 'W':
    case KEY_UP:
      --(*current_row);
      if (*current_row < 1) {
        *current_row = 1;
      }
      highlight_offset_ = 1;
      if (*current_row < 0) {
        *current_row = 0;
      }
      break;
    case 'a':
    case 'A':
    case KEY_BACKSPACE:
    case KEY_LEFT: {
      RenderableMessage* parent = active_renderable_->parent();
      if (parent) {
        active_renderable_ = parent;
        current_row = parent->row_index();
        clear();
      }
      break;
    }
    case '\n':
    case '\r':
    case 'd':
    case 'D':
    case KEY_RIGHT: {
      RenderableMessage* child = active_renderable_->Child(*current_row);
      if (child) {
        child->reset_line_page();
        active_renderable_ = child;
        current_row = child->row_index();
        clear();
      }
      break;
    }
  }
}

void Screen::DisplayHelpCommands(int) {
  unsigned row = 0;
  ApplyColor(Screen::WHITE_BLACK);
  Print((Columns() - 19) / 2, row++, "Interactive Command");
  const char* ptr = HelpCommandString;
  while (*ptr != '\0') {
    const char* newline = std::strchr(ptr, '\n');
    std::string segment(ptr, newline);
    Print(0, row++, segment.c_str());
    ptr = newline + 1;
  }
  RemoveColor();
}

#include <ansi_fp.h>
#include <ctype.h>
#include <float.h>
#include <math.h>

// Count trailing zero bits in an unsigned long value using binary search
inline int __count_trailing_zerol(unsigned long val)
{
    int count = 0;
    int remaining_bits = sizeof(unsigned long) * 8;
    int step_size = remaining_bits / 2;
    int chunk_size = step_size;
    unsigned long check_mask = (~0UL) >> (remaining_bits - step_size);

    while (remaining_bits > 0)
    {
        if (!(val & check_mask))
        {
            count += chunk_size;
            val >>= chunk_size;
            remaining_bits -= chunk_size;
        }
        else if (check_mask == 1)
            break;

        if (step_size > 1)
            step_size /= 2;

        if (check_mask > 1)
        {
            check_mask >>= step_size;
            chunk_size -= step_size;
        }
    }
    return count;
}

// Count trailing zeros in the mantissa of a double-precision floating-point number
inline int __count_trailing_zero(double value)
{
    unsigned long* parts = (unsigned long*)&value;
    if (parts[1] != 0)
        return __count_trailing_zerol(parts[1]);
    return (int)(sizeof(unsigned long) * 8 + __count_trailing_zerol(parts[0] | 0x00100000));
}

// Determine rounding direction for decimal representation
inline int __must_round(const decimal* dec, int position)
{
    unsigned char const* digit_ptr = dec->sig.text + position;
    if (*digit_ptr > 5)
        return 1;
    if (*digit_ptr < 5)
        return -1;

    // Check subsequent digits for non-zero values
    {
        unsigned char const* end_ptr = dec->sig.text + dec->sig.length;
        for (++digit_ptr; digit_ptr < end_ptr; ++digit_ptr)
            if (*digit_ptr != 0)
                return 1;
    }

    // Round to even check
    if (dec->sig.text[position - 1] & 1)
        return 1;
    return -1;
}

// Increment decimal significand at specified position (round up)
inline void __dorounddecup(decimal* dec, int digits)
{
    unsigned char* buffer = dec->sig.text;
    unsigned char* pos = buffer + digits - 1;

    while (true)
    {
        if (*pos < 9)
        {
            (*pos)++;
            break;
        }
        if (pos == buffer)
        {
            *pos = 1;
            dec->exp++;
            break;
        }
        *pos-- = 0;
    }
}

// Apply rounding to decimal number with specified precision
inline void __rounddec(decimal* dec, int digits)
{
    if (digits <= 0 || digits >= dec->sig.length)
        return;

    int round_decision = __must_round(dec, digits);
    dec->sig.length = (unsigned char)digits;

    if (round_decision < 0)
        return;

    __dorounddecup(dec, digits);
}

// Convert unsigned long long integer to decimal representation
inline void __ull2dec(decimal* result, unsigned long long integer)
{
    result->sign = 0;
    if (integer == 0)
    {
        result->exp = 0;
        result->sig.length = 1;
        result->sig.text[0] = 0;
        return;
    }

    if (integer < 0)
    {
        integer = -integer;
        result->sign = 1;
    }

    result->sig.length = 0;
    for (; integer != 0; integer /= 10)
        result->sig.text[result->sig.length++] = (unsigned char)(integer % 10);

    // Reverse digit order
    {
        unsigned char* start = result->sig.text;
        unsigned char* end = result->sig.text + result->sig.length;
        for (; start < --end; ++start)
        {
            unsigned char temp = *start;
            *start = *end;
            *end = temp;
        }
    }

    result->exp = (short)(result->sig.length - 1);
}

// Multiply two decimal numbers
static void __timesdec(decimal* result, const decimal* left, const decimal* right)
{
    unsigned long carry = 0;
    unsigned char product[2 * SIGDIGLEN];
    int index = left->sig.length + right->sig.length - 1;
    unsigned char* prod_pos = product + index + 1;
    unsigned char* prod_end = prod_pos;
    result->sign = 0;

    for (; index > 0; --index)
    {
        int k = right->sig.length - 1;
        int j = index - k - 1;
        int limit;
        int temp;
        unsigned char const *left_ptr, *right_ptr;

        if (j < 0)
        {
            j = 0;
            k = index - 1;
        }

        left_ptr = left->sig.text + j;
        right_ptr = right->sig.text + k;
        limit = k + 1;
        temp = left->sig.length - j;
        if (limit > temp)
            limit = temp;

        for (; limit > 0; --limit, ++left_ptr, --right_ptr)
            carry += (unsigned long)(*left_ptr) * *right_ptr;

        *--prod_pos = (unsigned char)(carry % 10);
        carry /= 10;
    }

    result->exp = (short)(left->exp + right->exp);
    if (carry > 0)
    {
        *--prod_pos = (unsigned char)carry;
        result->exp++;
    }

    for (index = 0; index < SIGDIGLEN && prod_pos < prod_end; ++index, ++prod_pos)
        result->sig.text[index] = *prod_pos;

    result->sig.length = (unsigned char)index;

    if (prod_pos < prod_end && *prod_pos >= 5)
    {
        if (*prod_pos == 5)
        {
            unsigned char* next_digit = prod_pos + 1;
            for (; next_digit < prod_end; ++next_digit)
                if (*next_digit != 0)
                    goto perform_rounding;

            if ((*(prod_pos - 1) & 1) == 0)
                return;
        }

    perform_rounding:
        __dorounddecup(result, result->sig.length);
    }
}

// Convert string to decimal with exponent adjustment
inline void __str2dec(decimal* dec, const char* digits_str, short exp_val)
{
    int i;
    dec->exp = exp_val;
    dec->sign = 0;

    for (i = 0; i < SIGDIGLEN && *digits_str != 0;)
        dec->sig.text[i++] = (unsigned char)(*digits_str++ - '0');

    dec->sig.length = (unsigned char)i;

    if (*digits_str != 0)
    {
        if (*digits_str < 5)
            return;

        {
            const char* next_char = digits_str + 1;
            for (; *next_char != 0; ++next_char)
                if (*next_char != '0')
                    goto rounding_needed;

            if ((dec->sig.text[i - 1] & 1) == 0)
                return;
        }

    rounding_needed:
        __dorounddecup(dec, dec->sig.length);
    }
}

// Compute power of two as decimal number
static void __two_exp(decimal* result, long exponent)
{
    switch (exponent)
    {
    case -64:
        __str2dec(result, "542101086242752217003726400434970855712890625", -20);
        return;
    case -53:
        __str2dec(result, "11102230246251565404236316680908203125", -16);
        return;
    case -32:
        __str2dec(result, "23283064365386962890625", -10);
        return;
    case -16:
        __str2dec(result, "152587890625", -5);
        return;
    case -8:
        __str2dec(result, "390625", -3);
        return;
    case -7:
        __str2dec(result, "78125", -3);
        return;
    case -6:
        __str2dec(result, "15625", -2);
        return;
    case -5:
        __str2dec(result, "3125", -2);
        return;
    case -4:
        __str2dec(result, "625", -2);
        return;
    case -3:
        __str2dec(result, "125", -1);
        return;
    case -2:
        __str2dec(result, "25", -1);
        return;
    case -1:
        __str2dec(result, "5", -1);
        return;
    case 0:
        __str2dec(result, "1", 0);
        return;
    case 1:
        __str2dec(result, "2", 0);
        return;
    case 2:
        __str2dec(result, "4", 0);
        return;
    case 3:
        __str2dec(result, "8", 0);
        return;
    case 4:
        __str2dec(result, "16", 1);
        return;
    case 5:
        __str2dec(result, "32", 1);
        return;
    case 6:
        __str2dec(result, "64", 1);
        return;
    case 7:
        __str2dec(result, "128", 2);
        return;
    case 8:
        __str2dec(result, "256", 2);
        return;
    }

    {
        decimal half_pow;
        __two_exp(&half_pow, (short)(exponent / 2));
        __timesdec(result, &half_pow, &half_pow);
    }

    if (exponent & 1)
    {
        decimal temp_result = *result;
        if (exponent > 0)
        {
            decimal base_two;
            __str2dec(&base_two, "2", 0);
            __timesdec(result, &temp_result, &base_two);
        }
        else
        {
            decimal half_value;
            __str2dec(&half_value, "5", -1);
            __timesdec(result, &temp_result, &half_value);
        }
    }
}

// Compare two decimal numbers for equality
static int __equals_dec(const decimal* first, const decimal* second)
{
    if (first->sig.text[0] == 0)
    {
        if (second->sig.text[0] == 0)
            return 1;
        return 0;
    }
    if (second->sig.text[0] == 0)
    {
        if (first->sig.text[0] == 0)
            return 1;
        return 0;
    }

    if (first->exp == second->exp)
    {
        int i;
        int min_len = first->sig.length;
        if (min_len > second->sig.length)
            min_len = second->sig.length;

        for (i = 0; i < min_len; ++i)
            if (first->sig.text[i] != second->sig.text[i])
                return 0;

        if (min_len == first->sig.length)
        {
            for (; i < second->sig.length; ++i)
                if (second->sig.text[i] != 0)
                    return 0;
        }
        else
        {
            for (; i < first->sig.length; ++i)
                if (first->sig.text[i] != 0)
                    return 0;
        }
        return 1;
    }
    return 0;
}

// Compare two decimal numbers for less-than relationship
inline int __less_dec(const decimal* first, const decimal* second)
{
    if (first->sig.text[0] == 0)
    {
        if (second->sig.text[0] != 0)
            return 1;
        return 0;
    }
    if (second->sig.text[0] == 0)
        return 0;

    if (first->exp == second->exp)
    {
        int i;
        int min_len = first->sig.length;
        if (min_len > second->sig.length)
            min_len = second->sig.length;

        for (i = 0; i < min_len; ++i)
        {
            if (first->sig.text[i] < second->sig.text[i])
                return 1;
            if (second->sig.text[i] < first->sig.text[i])
                return 0;
        }

        if (min_len == first->sig.length)
        {
            for (; i < second->sig.length; ++i)
                if (second->sig.text[i] != 0)
                    return 1;
        }
        return 0;
    }
    return first->exp < second->exp;
}

// Subtract two decimal numbers: z = x - y
static void __minus_dec(decimal* result, const decimal* minuend, const decimal* subtrahend)
{
    int res_length, diff_exp;
    unsigned char *buf_start, *cur_pos, *buf_end;
    unsigned char const *sub_start, *sub_cur, *sub_end;

    *result = *minuend;

    if (subtrahend->sig.text[0] == 0)
        return;

    res_length = result->sig.length;
    if (res_length < subtrahend->sig.length)
        res_length = subtrahend->sig.length;

    diff_exp = result->exp - subtrahend->exp;
    res_length += diff_exp;

    if (res_length > SIGDIGLEN)
        res_length = SIGDIGLEN;

    while (result->sig.length < res_length)
        result->sig.text[result->sig.length++] = 0;

    buf_start = result->sig.text;
    cur_pos = buf_start + res_length;

    if (subtrahend->sig.length + diff_exp < res_length)
        cur_pos = buf_start + (subtrahend->sig.length + diff_exp);

    sub_start = subtrahend->sig.text;
    sub_cur = sub_start + (cur_pos - buf_start - diff_exp);
    sub_end = sub_cur;

    while (cur_pos > buf_start && sub_cur > sub_start)
    {
        --cur_pos;
        --sub_cur;

        if (*cur_pos < *sub_cur)
        {
            unsigned char* borrow_pos = cur_pos - 1;
            while (*borrow_pos == 0)
                --borrow_pos;
            while (borrow_pos != cur_pos)
            {
                --*borrow_pos;
                *++borrow_pos += 10;
            }
        }
        *cur_pos -= *sub_cur;
    }

    if (sub_end - sub_start < subtrahend->sig.length)
    {
        int round_down = 0;
        if (*sub_end < 5)
            round_down = 1;
        else if (*sub_end == 5)
        {
            unsigned char const* sig_end = subtrahend->sig.text + subtrahend->sig.length;
            for (sub_cur = sub_end + 1; sub_cur < sig_end; ++sub_cur)
                if (*sub_cur != 0)
                    goto done_subtraction;

            cur_pos = buf_start + (sub_end - sub_start) + diff_exp - 1;
            if (*cur_pos & 1)
                round_down = 1;
        }

        if (round_down)
        {
            if (*cur_pos < 1)
            {
                unsigned char* borrow_pos = cur_pos - 1;
                while (*borrow_pos == 0)
                    --borrow_pos;
                while (borrow_pos != cur_pos)
                {
                    --*borrow_pos;
                    *++borrow_pos += 10;
                }
            }
            *cur_pos -= 1;
        }
    }

done_subtraction:
    for (cur_pos = buf_start; *cur_pos == 0; ++cur_pos)
    {
    }

    if (cur_pos > buf_start)
    {
        unsigned char shift_amount = (unsigned char)(cur_pos - buf_start);
        result->exp -= shift_amount;
        buf_end = buf_start + result->sig.length;
        for (; cur_pos < buf_end; ++cur_pos, ++buf_start)
            *buf_start = *cur_pos;
        result->sig.length -= shift_amount;
    }

    buf_start = result->sig.text;
    for (cur_pos = buf_start + result->sig.length; cur_pos > buf_start;)
    {
        --cur_pos;
        if (*cur_pos != 0)
            break;
    }
    result->sig.length = (unsigned char)(cur_pos - buf_start + 1);
}

// Internal conversion from double to decimal
static void __num2dec_internal(decimal* dec, double value)
{
    char sign_flag = signbit(value) != 0;

    if (value == 0.0)
    {
        dec->sign = sign_flag;
        dec->exp = 0;
        dec->sig.length = 1;
        dec->sig.text[0] = 0;
        return;
    }

    if (!isfinite(value))
    {
        dec->sign = sign_flag;
        dec->exp = 0;
        dec->sig.length = 1;
        dec->sig.text[0] = (unsigned char)(isnan(value) ? 'N' : 'I');
        return;
    }

    if (sign_flag)
        value = -value;

    {
        int exp_val;
        double fraction = frexp(value, &exp_val);
        short significant_bits = (short)(DBL_MANT_DIG - __count_trailing_zero(fraction));
        double integer_part;
        decimal int_dec, pow2_dec;

        __two_exp(&pow2_dec, (short)(exp_val - significant_bits));
        fraction = modf(ldexp(fraction, significant_bits), &integer_part);
        __ull2dec(&int_dec, (unsigned long long)integer_part);
        __timesdec(dec, &int_dec, &pow2_dec);
        dec->sign = sign_flag;
    }
}

// Convert double to decimal with specified precision
void __num2dec(const decform* format, double value, decimal* dec)
{
    short precision = format->digits;
    int i;

    __num2dec_internal(dec, value);

    if (dec->sig.text[0] > 9)
        return;

    if (precision > SIGDIGLEN)
        precision = SIGDIGLEN;

    __rounddec(dec, precision);

    while (dec->sig.length < precision)
        dec->sig.text[dec->sig.length++] = 0;

    dec->exp -= dec->sig.length - 1;

    for (i = 0; i < dec->sig.length; ++i)
        dec->sig.text[i] += '0';
}

// Convert decimal to double
double __dec2num(const decimal* dec)
{
    if (dec->sig.length <= 0)
        return copysign(0.0, dec->sign == 0 ? 1.0 : -1.0);

    switch (dec->sig.text[0])
    {
    case '0':
        return copysign(0.0, dec->sign == 0 ? 1.0 : -1.0);
    case 'I':
        return copysign((double)INFINITY, dec->sign == 0 ? 1.0 : -1.0);
    case 'N':
    {
        double result;
        unsigned long long* ll_ptr = (unsigned long long*)&result;
        *ll_ptr = 0x7FF0000000000000;
        if (dec->sign)
            *ll_ptr |= 0x8000000000000000;
        if (dec->sig.length == 1)
            *ll_ptr |= 0x0008000000000000;
        else
        {
            unsigned char* p = (unsigned char*)&result + 1;
            int placed_non_zero = 0;
            int low_nibble = 1;
            int i;
            int e = dec->sig.length;
            if (e > 14)
                e = 14;

            for (i = 1; i < e; ++i)
            {
                unsigned char c = dec->sig.text[i];
                if (isdigit(c))
                    c -= '0';
                else
                    c = (unsigned char)(tolower(c) - 'a' + 10);

                if (c != 0)
                    placed_non_zero = 1;

                if (low_nibble)
                    *p++ |= c;
                else
                    *p = (unsigned char)(c << 4);

                low_nibble = !low_nibble;
            }

            if (!placed_non_zero)
                *ll_ptr |= 0x0008000000000000;
        }
        return result;
    }
    }

    {
        static double powers_of_ten[8] = { 1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8 };
        decimal temp_dec = *dec;
        unsigned char* digit_ptr = temp_dec.sig.text;
        unsigned char* end_ptr = digit_ptr + temp_dec.sig.length;
        double approximation;
        int exponent;

        for (; digit_ptr < end_ptr; ++digit_ptr)
            *digit_ptr -= '0';

        temp_dec.exp += temp_dec.sig.length - 1;
        exponent = temp_dec.exp;
        digit_ptr = temp_dec.sig.text;
        approximation = *digit_ptr++;

        while (digit_ptr < end_ptr)
        {
            unsigned long ival = 0;
            int j;
            double temp1, temp2;
            int ndig = (end_ptr - digit_ptr) % 8;
            if (ndig == 0)
                ndig = 8;

            for (j = 0; j < ndig; ++j, ++digit_ptr)
                ival = ival * 10 + *digit_ptr;

            temp1 = approximation * powers_of_ten[ndig - 1];
            temp2 = temp1 + ival;

            if (ival != 0 && temp1 == temp2)
                break;

            approximation = temp2;
            exponent -= ndig;
        }

        if (exponent < 0)
            approximation /= pow(5.0, -exponent);
        else
            approximation *= pow(5.0, exponent);

        approximation = ldexp(approximation, exponent);

        if (isinf(approximation))
        {
            decimal max_limit;
            __str2dec(&max_limit, "179769313486231580793729011405303420", 308);
            if (__less_dec(&max_limit, &temp_dec))
                goto final_result;

            approximation = DBL_MAX;
        }

        {
            decimal feedback1;
            __num2dec_internal(&feedback1, approximation);

            if (__equals_dec(&feedback1, &temp_dec))
                goto final_result;

            if (__less_dec(&feedback1, &temp_dec))
            {
                decimal feedback2, difflow, diffhigh;
                double next_val = nextafter(approximation, (double)INFINITY);

                if (isinf(next_val))
                {
                    approximation = next_val;
                    goto final_result;
                }

                __num2dec_internal(&feedback2, next_val);

                while (__less_dec(&feedback2, &temp_dec))
                {
                    feedback1 = feedback2;
                    approximation = next_val;
                    next_val = nextafter(next_val, (double)INFINITY);

                    if (isinf(next_val))
                    {
                        approximation = next_val;
                        goto final_result;
                    }

                    __num2dec_internal(&feedback2, next_val);
                }

                __minus_dec(&difflow, &temp_dec, &feedback1);
                __minus_dec(&diffhigh, &feedback2, &temp_dec);

                if (__equals_dec(&difflow, &diffhigh))
                {
                    if (*(unsigned long long*)&approximation & 1)
                        approximation = next_val;
                }
                else if (!__less_dec(&difflow, &diffhigh))
                    approximation = next_val;
            }
            else
            {
                decimal feedback2, difflow, diffhigh;
                double next_val = nextafter(approximation, (double)(-INFINITY));

                __num2dec_internal(&feedback2, next_val);

                while (__less_dec(&temp_dec, &feedback2))
                {
                    feedback1 = feedback2;
                    approximation = next_val;
                    next_val = nextafter(next_val, (double)(-INFINITY));

                    __num2dec_internal(&feedback2, next_val);
                }

                __minus_dec(&difflow, &temp_dec, &feedback2);
                __minus_dec(&diffhigh, &feedback1, &temp_dec);

                if (__equals_dec(&difflow, &diffhigh))
                {
                    if (*(unsigned long long*)&approximation & 1)
                        approximation = next_val;
                }
                else if (__less_dec(&difflow, &diffhigh))
                    approximation = next_val;
            }
        }
    }

final_result:
    if (temp_dec.sign)
        approximation = -approximation;

    return approximation;
}

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"
#include <toml11/spec.hpp>

TEST_CASE("Verifying semantic_version constructor functionality")
{
    constexpr auto version_234 = toml::semantic_version(2, 3, 4);
    CHECK(version_234.major == 2);
    CHECK(version_234.minor == 3);
    CHECK(version_234.patch == 4);
}

TEST_CASE("Assessing comparison operators for semantic_version")
{
    constexpr auto ver_a = toml::semantic_version(2, 0, 0);
    constexpr auto ver_b = toml::semantic_version(2, 0, 1);
    constexpr auto ver_c = toml::semantic_version(2, 1, 0);
    constexpr auto ver_d = toml::semantic_version(2, 1, 2);
    constexpr auto ver_e = toml::semantic_version(2, 2, 1);

    // Reflexive checks for ver_a
    CHECK(ver_a == ver_a);
    CHECK(ver_a >= ver_a);
    CHECK(ver_a <= ver_a);
    CHECK_FALSE(ver_a != ver_a);
    CHECK_FALSE(ver_a >  ver_a);
    CHECK_FALSE(ver_a <  ver_a);

    // Comparing ver_a and ver_b
    CHECK(ver_a != ver_b);
    CHECK(ver_a <= ver_b);
    CHECK(ver_a <  ver_b);
    CHECK_FALSE(ver_a == ver_b);
    CHECK_FALSE(ver_a >= ver_b);
    CHECK_FALSE(ver_a >  ver_b);

    // Comparing ver_b and ver_c
    CHECK(ver_b != ver_c);
    CHECK(ver_b <  ver_c);
    CHECK(ver_b <= ver_c);
    CHECK_FALSE(ver_b == ver_c);
    CHECK_FALSE(ver_b >  ver_c);
    CHECK_FALSE(ver_b >= ver_c);

    // Comparing ver_c and ver_b
    CHECK(ver_c != ver_b);
    CHECK(ver_c >  ver_b);
    CHECK(ver_c >= ver_b);
    CHECK_FALSE(ver_c == ver_b);
    CHECK_FALSE(ver_c <  ver_b);
    CHECK_FALSE(ver_c <= ver_b);

    // Comparing ver_d and ver_e
    CHECK(ver_d != ver_e);
    CHECK(ver_d <  ver_e);
    CHECK(ver_d <= ver_e);
    CHECK(ver_e != ver_d);
    CHECK(ver_e >  ver_d);
    CHECK(ver_e >= ver_d);
}

