class ZWidgetWaylandVulkanLoader
{
public:
	ZWidgetWaylandVulkanLoader()
	{
#if defined(__APPLE__)
		module = dlopen("libvulkan.dylib", RTLD_NOW | RTLD_LOCAL);
		if (!module)
			module = dlopen("libvulkan.1.dylib", RTLD_NOW | RTLD_LOCAL);
		if (!module)
			module = dlopen("libMoltenVK.dylib", RTLD_NOW | RTLD_LOCAL);
#else
		module = dlopen("libvulkan.so.1", RTLD_NOW | RTLD_LOCAL);
		if (!module)
			module = dlopen("libvulkan.so", RTLD_NOW | RTLD_LOCAL);
#endif
		if (!module)
			throw std::runtime_error("Could not load vulkan");
		vkGetInstanceProcAddr = (PFN_vkGetInstanceProcAddr)dlsym(module, "vkGetInstanceProcAddr");
		if (!vkGetInstanceProcAddr)
		{
			dlclose(module);
			throw std::runtime_error("vkGetInstanceProcAddr not found");
		}
	}

	~ZWidgetWaylandVulkanLoader()
	{
		dlclose(module);
	}

	PFN_vkGetInstanceProcAddr vkGetInstanceProcAddr = nullptr;
	void* module = nullptr;
};

VkSurfaceKHR WaylandDisplayWindow::CreateVulkanSurface(VkInstance instance)
{
	static ZWidgetWaylandVulkanLoader loader;
	auto vkCreateWaylandSurfaceKHR = (PFN_vkCreateWaylandSurfaceKHR)loader.vkGetInstanceProcAddr(instance, "vkCreateWaylandSurfaceKHR");
	if (!vkCreateWaylandSurfaceKHR)
		throw std::runtime_error("Could not create vulkan surface");

	VkWaylandSurfaceCreateInfoKHR createInfo = { VK_STRUCTURE_TYPE_WAYLAND_SURFACE_CREATE_INFO_KHR };
	createInfo.display = m_NativeHandle.display;
	createInfo.surface = m_NativeHandle.surface;

	VkSurfaceKHR surface = {};
	VkResult result = vkCreateWaylandSurfaceKHR(instance, &createInfo, nullptr, &surface);
	if (result != VK_SUCCESS)
		throw std::runtime_error("Could not create vulkan surface");

	return surface;
}

std::vector<std::string> WaylandDisplayWindow::GetVulkanInstanceExtensions()
{
	return { "VK_KHR_surface", "VK_KHR_wayland_surface" };
}

#include <Python.h>

typedef struct {
    PyObject_HEAD
    Py_ssize_t      pos;
    PyObject* container;
} reviterobject;

static PyObject *
reviter_create(PyTypeObject *type, PyObject *args, PyObject *kwds)
{
    Py_ssize_t count;
    PyObject *seq_obj, *reverse_method;
    static PyObject *cache_attr = NULL;
    reviterobject *ro;

    if (type == &PyRevIter_Type && !_PyArg_NoKeywords("reviter()", kwds))
        return NULL;

    if (!PyArg_UnpackTuple(args, "reviter", 1, 1, &seq_obj))
        return NULL;

    if (PyInstance_Check(seq_obj)) {
        reverse_method = PyObject_GetAttrString(seq_obj, "__rev__");
        if (reverse_method == NULL) {
            if (PyErr_ExceptionMatches(PyExc_AttributeError))
                PyErr_Clear();
            else
                return NULL;
        }
    }
    else {
        reverse_method = _PyObject_LookupSpecial(seq_obj, "__rev__",
                                                &cache_attr);
        if (reverse_method == NULL && PyErr_Occurred())
            return NULL;
    }

    if (reverse_method != NULL) {
        PyObject *result = PyObject_CallFunctionObjArgs(reverse_method, NULL);
        Py_DECREF(reverse_method);
        return result;
    }

    if (!PySequence_Check(seq_obj)) {
        PyErr_SetString(PyExc_TypeError,
                        "reviter() argument must be a sequence");
        return NULL;
    }

    count = PySequence_Size(seq_obj);
    if (count == -1)
        return NULL;

    ro = (reviterobject *)type->tp_alloc(type, 0);
    if (ro == NULL)
        return NULL;

    ro->pos = count - 1;
    Py_INCREF(seq_obj);
    ro->container = seq_obj;

    return (PyObject *)ro;
}

static void
reviter_destroy(reviterobject *ro)
{
    PyObject_GC_UnTrack(ro);
    Py_XDECREF(ro->container);
    Py_TYPE(ro)->tp_free(ro);
}

static int
reviter_traverse(reviterobject *ro, visitproc visit, void *arg)
{
    Py_VISIT(ro->container);
    return 0;
}

static PyObject *
reviter_next(reviterobject *ro)
{
    PyObject *element;
    Py_ssize_t current_pos = ro->pos;

    if (current_pos >= 0) {
        element = PySequence_GetItem(ro->container, current_pos);
        if (element != NULL) {
            ro->pos--;
            return element;
        }
        if (PyErr_ExceptionMatches(PyExc_IndexError) ||
            PyErr_ExceptionMatches(PyExc_StopIteration))
            PyErr_Clear();
    }

    ro->pos = -1;
    Py_CLEAR(ro->container);
    return NULL;
}

PyDoc_STRVAR(reviter_doc,
"reviter(sequence) -> reverse iterator over values of the sequence\n"
"\n"
"Return a reverse iterator");

static PyObject *
reviter_length(reviterobject *ro)
{
    Py_ssize_t remaining, total_size;

    if (ro->container == NULL)
        return PyInt_FromLong(0);

    total_size = PySequence_Size(ro->container);
    if (total_size == -1)
        return NULL;

    remaining = ro->pos + 1;
    return PyInt_FromSsize_t((total_size < remaining) ? 0 : remaining);
}

PyDoc_STRVAR(hint_doc, "Private method returning an estimated length of the iterator.");

static PyMethodDef reviter_methods[] = {
    {"__length_hint__", (PyCFunction)reviter_length, METH_NOARGS, hint_doc},
    {NULL,              NULL}           /* sentinel */
