namespace {
  QReadWriteLock s_lock;
  QMutex s_fxMutex;

  template <typename T>
  TRasterGR8P createRasterAndAcquire(T** dataPtr, TDimensionI size) {
    TRasterGR8P raster(size.lx * sizeof(T), size.ly);
    raster->acquire();
    *dataPtr = static_cast<T*>(raster->getRawData());
    return raster;
  }

  void releaseAllAllocatedRasters(QList<TRasterGR8P>& rasterContainer) {
    for (int idx = 0; idx < rasterContainer.size(); ++idx)
      rasterContainer.at(idx)->release();
  }

  void cleanupAllResources(QList<TRasterGR8P>& rasterContainer,
                           QList<kiss_fftnd_cfg>& planContainer) {
    releaseAllAllocatedRasters(rasterContainer);
    for (int pIdx = 0; pIdx < planContainer.size(); ++pIdx)
      kiss_fft_free(planContainer.at(pIdx));
  }
} // namespace

//============================================================
//------------------------------------------------------------
// Normalize brightness of the depth reference image to unsigned char
// and store into destination memory buffer
//------------------------------------------------------------
template <typename RASTER, typename PIXEL>
void Iwa_BokehRefFx::storeDepthRaster(const RASTER sourceRaster,
                                      unsigned char* destBuffer,
                                      TDimensionI dimensions) {
  unsigned char* depthIter = destBuffer;
  for (int row = 0; row < dimensions.ly; ++row) {
    PIXEL* pixelRow = sourceRaster->pixels(row);
    for (int col = 0; col < dimensions.lx; ++col, ++pixelRow, ++depthIter) {
      double intensity = ((double)pixelRow->r * 0.3 +
                          (double)pixelRow->g * 0.59 +
                          (double)pixelRow->b * 0.11) /
                         (double)PIXEL::maxChannelValue;
      *depthIter = static_cast<unsigned char>(intensity * (double)UCHAR_MAX + 0.5);
    }
  }
}

template <typename RASTER, typename PIXEL>
void Iwa_BokehRefFx::storeDepthRasterGray(const RASTER sourceRaster,
                                          unsigned char* destBuffer,
                                          TDimensionI dimensions) {
  unsigned char* depthIter = destBuffer;
  for (int row = 0; row < dimensions.ly; ++row) {
    PIXEL* pixelRow = sourceRaster->pixels(row);
    for (int col = 0; col < dimensions.lx; ++col, ++pixelRow, ++depthIter) {
      double intensity = (double)pixelRow->value / (double)PIXEL::maxChannelValue;
      *depthIter = static_cast<unsigned char>(intensity * (double)UCHAR_MAX + 0.5);
    }
  }
}

//--------------------------------------------
Iwa_BokehRefFx::Iwa_BokehRefFx()
    : m_distancePrecision(10), m_fillGap(true), m_doMedian(true) {
  addInputPort("Source", m_source);
  addInputPort("Depth", m_depth);
  bindParam(this, "on_focus_distance", m_onFocusDistance, false);
  bindParam(this, "bokeh_amount", m_bokehAmount, false);
  bindParam(this, "hardness", m_hardness, false);
  bindParam(this, "gamma", m_gamma, false);
  bindParam(this, "gammaAdjust", m_gammaAdjust, false);
  bindParam(this, "distance_precision", m_distancePrecision, false);
  bindParam(this, "fill_gap", m_fillGap, false);
  bindParam(this, "fill_gap_with_median_filter", m_doMedian, false);
  bindParam(this, "linearizeMode", m_linearizeMode, false);

  m_distancePrecision->setValueRange(3, 128);
  enableComputeInFloat(true);

  setFxVersion(3); // Default to version 3
}

//--------------------------------------------
void Iwa_BokehRefFx::onFxVersionSet() {
  bool useGammaParam = getFxVersion() == 2;
  if (getFxVersion() == 1) {
    m_linearizeMode->setValue(Hardness);
    setFxVersion(3);
  } else if (getFxVersion() == 2) {
    if (m_linearizeMode->getValue() == Hardness ||
        (m_gamma->getKeyframeCount() == 0 &&
         areAlmostEqual(m_gamma->getDefaultValue(), 2.2))) {
      useGammaParam = false;
      setFxVersion(3);
    }
  }

  getParams()->getParamVar("gamma")->setIsHidden(!useGammaParam);
  getParams()->getParamVar("gammaAdjust")->setIsHidden(useGammaParam);
}

//--------------------------------------------
void Iwa_BokehRefFx::doCompute(TTile& outputTile, double frameNumber,
                               const TRenderSettings& renderSettings) {
  if (!m_iris.isConnected() || !m_source.isConnected() ||
      !m_depth.isConnected()) {
    outputTile.getRaster()->clear();
    return;
  }

  QList<TRasterGR8P> managedRasters;

  double bokehPixelScale = BokehUtils::getBokehPixelAmount(
      m_bokehAmount->getValue(frameNumber), renderSettings.m_affine);

  double focusDistance = m_onFocusDistance->getValue(frameNumber);
  double maxBlurRadius = bokehPixelScale *
                         std::max((1.0 - focusDistance), focusDistance);
  int padding =
      (maxBlurRadius > 1.0f) ? static_cast<int>(std::ceil((maxBlurRadius - 1.0) / 2.0)) : 0;

  TRectD outputRegion(outputTile.m_pos, TDimensionD(outputTile.getRaster()->getLx(),
                                                    outputTile.getRaster()->getLy()));
  outputRegion = outputRegion.enlarge(static_cast<double>(padding));

  TDimensionI finalSize(static_cast<int>(outputRegion.getLx() + 0.5),
                        static_cast<int>(outputRegion.getLy() + 0.5));

  if (finalSize.lx < 10000 && finalSize.ly < 10000) {
    int newX = kiss_fft_next_fast_size(finalSize.lx);
    int newY = kiss_fft_next_fast_size(finalSize.ly);

    while ((newX - finalSize.lx) % 2 != 0)
      newX = kiss_fft_next_fast_size(newX + 1);
    while ((newY - finalSize.ly) % 2 != 0)
      newY = kiss_fft_next_fast_size(newY + 1);

    outputRegion = outputRegion.enlarge(static_cast<double>(newX - finalSize.lx) / 2.0,
                                        static_cast<double>(newY - finalSize.ly) / 2.0);
    finalSize.lx = newX;
    finalSize.ly = newY;
  }

  // Allocate and compute source tile
  LayerValue layerData;
  layerData.sourceTile = new TTile();
  m_source->allocateAndCompute(*layerData.sourceTile, outputRegion.getP00(), finalSize,
                               outputTile.getRaster(), frameNumber, renderSettings);

  // Iris tile computation
  TRectD irisBounds;
  m_iris->getBBox(frameNumber, irisBounds, renderSettings);

  TTile irisTile;
  m_iris->allocateAndCompute(
      irisTile, irisBounds.getP00(),
      TDimension(static_cast<int>(irisBounds.getLx() + 0.5),
                 static_cast<int>(irisBounds.getLy() + 0.5)),
      outputTile.getRaster(), frameNumber, renderSettings);

  if (renderSettings.m_isCanceled && *renderSettings.m_isCanceled) {
    releaseAllAllocatedRasters(managedRasters);
    outputTile.getRaster()->clear();
    return;
  }

  double effectiveGamma;
  if (m_linearizeMode->getValue() == Hardness)
    effectiveGamma = m_hardness->getValue(frameNumber);
  else {
    if (getFxVersion() == 2)
      effectiveGamma = m_gamma->getValue(frameNumber);
    else
      effectiveGamma = std::max(
          1., renderSettings.m_colorSpaceGamma + m_gammaAdjust->getValue(frameNumber));
    if (outputTile.getRaster()->isLinear())
      effectiveGamma /= renderSettings.m_colorSpaceGamma;
  }

  std::vector<TRasterGR8P> controlRasters;
  QMap<int, unsigned char*> controlBuffers;

  unsigned char* depthBuffer;
  managedRasters.append(createRasterAndAcquire<unsigned char>(&depthBuffer, finalSize));

  {
    TTile depthTile;
    m_depth->allocateAndCompute(depthTile, outputRegion.getP00(), finalSize,
                                outputTile.getRaster(), frameNumber, renderSettings);

    if (renderSettings.m_isCanceled && *renderSettings.m_isCanceled) {
      releaseAllAllocatedRasters(managedRasters);
      outputTile.getRaster()->clear();
      return;
    }

    TRasterGR8P ras8   = dynamic_cast<TRasterGR8P>(depthTile.getRaster());
    TRasterGR16P ras16 = dynamic_cast<TRasterGR16P>(depthTile.getRaster());
    TRaster32P ras32   = dynamic_cast<TRaster32P>(depthTile.getRaster());
    TRaster64P ras64   = dynamic_cast<TRaster64P>(depthTile.getRaster());
    TRasterFP rasF     = dynamic_cast<TRasterFP>(depthTile.getRaster());

    s_lock.lockForRead();
    if (ras8)
      storeDepthRasterGray<TRasterGR8P, TPixelGR8>(ras8, depthBuffer, finalSize);
    else if (ras16)
      storeDepthRasterGray<TRasterGR16P, TPixelGR16>(ras16, depthBuffer, finalSize);
    else if (ras32)
      BokehUtils::storeDepthRaster<TRaster32P, TPixel32>(ras32, depthBuffer, finalSize);
    else if (ras64)
      BokehUtils::storeDepthRaster<TRaster64P, TPixel64>(ras64, depthBuffer, finalSize);
    else if (rasF)
      BokehUtils::storeDepthRaster<TRasterFP, TPixelF>(rasF, depthBuffer, finalSize);
    s_lock.unlock();
  }

  controlBuffers[1] = depthBuffer;

  layerData.premultiply       = false;
  layerData.layerGamma        = effectiveGamma;
  layerData.depth_ref         = 1;
  layerData.distance          = 0.5;
  layerData.bokehAdjustment   = 1.0;
  layerData.depthRange        = 1.0;
  layerData.distancePrecision = m_distancePrecision->getValue();
  layerData.fillGap           = m_fillGap->getValue();
  layerData.doMedian          = m_doMedian->getValue();

  QList<LayerValue> layers;
  layers.append(layerData);

  Iwa_BokehCommonFx::doFx(outputTile, frameNumber, renderSettings, bokehPixelScale, padding,
                          finalSize, irisBounds, irisTile, layers, controlBuffers);

  releaseAllAllocatedRasters(managedRasters);
  delete layerData.sourceTile;
}

