using namespace std;

class DualDequeQueue {
public:
    deque<int> frontPart, backPart;

    DualDequeQueue() {}

    // Maintain balance between the two deques
    void adjust() {
        // Ensure frontPart has at most one more element than backPart
        while (frontPart.size() > backPart.size() + 1) {
            backPart.push_front(frontPart.back());
            frontPart.pop_back();
        }
        while (frontPart.size() < backPart.size()) {
            frontPart.push_back(backPart.front());
            backPart.pop_front();
        }
    }

    void addFront(int value) {
        frontPart.push_front(value);
        adjust();
    }

    void addMiddle(int value) {
        if (frontPart.size() > backPart.size()) {
            backPart.push_front(frontPart.back());
            frontPart.pop_back();
        }
        frontPart.push_back(value);
        adjust();
    }

    void addBack(int value) {
        backPart.push_back(value);
        adjust();
    }

    int removeFront() {
        if (frontPart.empty() && backPart.empty()) return -1;
        int value;
        if (!frontPart.empty()) {
            value = frontPart.front();
            frontPart.pop_front();
        } else {
            value = backPart.front();
            backPart.pop_front();
        }
        adjust();
        return value;
    }

    int removeMiddle() {
        if (frontPart.empty() && backPart.empty()) return -1;
        int value;
        if (frontPart.size() == backPart.size()) {
            value = frontPart.back();
            frontPart.pop_back();
        } else {
            value = frontPart.back();
            frontPart.pop_back();
        }
        adjust();
        return value;
    }

    int removeBack() {
        if (frontPart.empty() && backPart.empty()) return -1;
        int value;
        if (!backPart.empty()) {
            value = backPart.back();
            backPart.pop_back();
        } else {
            value = frontPart.back();
            frontPart.pop_back();
        }
        adjust();
        return value;
    }
};
