 * Your DualDequeQueue object will be instantiated and called as such:
 * DualDequeQueue* obj = new DualDequeQueue();
 * obj->addFront(value);
 * obj->addMiddle(value);
 * obj->addBack(value);
 * int param_4 = obj->removeFront();
 * int param_5 = obj->removeMiddle();
 * int param_6 = obj->removeBack();
 */

