#include "MsDbMgr.h"
#include <stdio.h>
#include <string>

std::unique_ptr<MsDbMgr> MsDbMgr::m_instance;
std::mutex MsDbMgr::m_mutex;

MsDbMgr::MsDbMgr() : m_dbHandle(nullptr) {}

MsDbMgr::~MsDbMgr() {
    if (m_dbHandle) {
        sqlite3_close(m_dbHandle);
    }
}

int MsDbMgr::Initialize() {
    int result = sqlite3_open("conf/media_server.db", &m_dbHandle);
    if (result) {
        printf("Unable to open database: %s\n", sqlite3_errmsg(m_dbHandle));
        return -1;
    }

    char *errorMsg = nullptr;
    std::string query;

    // Create file metadata table
    query = "create table if not exists t_file (\
        file_id    INTEGER PRIMARY KEY,\
        name       TEXT NOT NULL,\
        size       INTEGER NOT NULL,\
        codec      TEXT NOT NULL,\
        res        TEXT NOT NULL,\
        duration   REAL DEFAULT 0,\
        frame_rate REAL DEFAULT 0\
        )";
    result = sqlite3_exec(m_dbHandle, query.c_str(), nullptr, 0, &errorMsg);
    if (result != SQLITE_OK) {
        printf("Database error: %s\n", errorMsg);
        sqlite3_free(errorMsg);
        return 1;
    }

    // Create device information table
    query = "create table if not exists device (\
        id INTEGER PRIMARY KEY ,\
        device_id TEXT NOT NULL UNIQUE,\
        parent_id TEXT NOT NULL,\
        domain_id TEXT NOT NULL,\
        name TEXT NOT NULL,\
        status TEXT NOT NULL,\
        manufacturer TEXT NOT NULL,\
        model TEXT NOT NULL,\
        owner TEXT NOT NULL,\
        civil_code TEXT NOT NULL,\
        address TEXT NOT NULL,\
        ip_addr TEXT NOT NULL,\
        user TEXT NOT NULL,\
        pass TEXT NOT NULL,\
        longitude  TEXT NOT NULL,\
        latitude  TEXT NOT NULL,\
        url TEXT NOT NULL,\
        ptz_type INTEGER NOT NULL,\
        type INTEGER NOT NULL,\
        protocol INTEGER NOT NULL,\
        port INTEGER NOT NULL,\
        bind_ip  TEXT NOT NULL,\
        remark  TEXT NOT NULL,\
        codec TEXT DEFAULT 'unknown',\
        resolution TEXT DEFAULT 'unknown',\
        onvif_profile  TEXT DEFAULT '',\
        onvif_ptz_url  TEXT DEFAULT '' \
        )";
    result = sqlite3_exec(m_dbHandle, query.c_str(), nullptr, 0, &errorMsg);
    if (result != SQLITE_OK) {
        printf("Database error: %s\n", errorMsg);
        sqlite3_free(errorMsg);
        return 1;
    }

    // Create group-device mapping table
    query = "create table if not exists group_dev  (\
        group_id  TEXT NOT NULL,\
        device_id  TEXT NOT NULL,\
        name  TEXT NOT NULL,\
        type  INTEGER NOT NULL,\
        PRIMARY KEY( group_id ,  device_id ) \
        ) ";
    result = sqlite3_exec(m_dbHandle, query.c_str(), nullptr, 0, &errorMsg);
    if (result != SQLITE_OK) {
        printf("Database error: %s\n", errorMsg);
        sqlite3_free(errorMsg);
        return 1;
    }

    return 0;
}

sqlite3* MsDbMgr::GetDatabaseHandle() {
    m_dbMutex.lock();
    return m_dbHandle;
}

void MsDbMgr::ReleaseDatabaseHandle() { 
    m_dbMutex.unlock(); 
}

MsDbMgr* MsDbMgr::GetInstance() {
    if (MsDbMgr::m_instance) {
        return MsDbMgr::m_instance.get();
    } else {
        std::lock_guard<std::mutex> lock(MsDbMgr::m_mutex);
        if (MsDbMgr::m_instance) {
            return MsDbMgr::m_instance.get();
        } else {
            MsDbMgr::m_instance = std::make_unique<MsDbMgr>();
            return MsDbMgr::m_instance.get();
        }
    }
}

