    auto sym_32 = symbolic::symbol("_32");
    auto assumption_32 = symbolic::Assumption::create(sym_32, type_i64);
    assumption_32.lower_bound_deprecated(symbolic::zero());
    assumption_32.upper_bound_deprecated(symbolic::sub(sym_3, symbolic::one()));
    assumption_32.map(symbolic::add(sym_32, symbolic::one()));

    // Collect all assumptions
    symbolic::Assumptions assumptions_set1;
    assumptions_set1.insert({sym_13, assumption_13});
    assumptions_set1.insert({sym_24, assumption_24});
    assumptions_set1.insert({sym_28, assumption_28});
    assumptions_set1.insert({sym_32, assumption_32});
    assumptions_set1.insert({sym_19, assumption_19});
    assumptions_set1.insert({sym_1, assumption_1});
    assumptions_set1.insert({sym_2, assumption_2});
    assumptions_set1.insert({sym_3, assumption_3});

    auto assumptions_set2 = assumptions_set1;

    // Expression 1: 1 + _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto stride_var1 = symbolic::add(symbolic::integer(2), sym_1);
    auto stride_var2 = symbolic::add(symbolic::integer(2), sym_2);
    auto stride_var3 = symbolic::add(symbolic::integer(2), sym_3);

    auto offset_sym32 = symbolic::add(symbolic::one(), sym_32);
    auto offset_sym28 = symbolic::add(symbolic::one(), sym_28);
    auto offset_sym24 = symbolic::add(symbolic::one(), sym_24);

    auto expression1 = symbolic::add(offset_sym32, symbolic::mul(stride_var3, offset_sym28));
    expression1 = symbolic::add(expression1, symbolic::mul(symbolic::mul(stride_var3, stride_var2), offset_sym24));
    expression1 = symbolic::add(expression1, symbolic::mul(symbolic::mul(symbolic::mul(stride_var3, stride_var2), stride_var1), sym_13));

    // Expression 2: 1 + _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*_24 + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expression2 = symbolic::add(offset_sym32, symbolic::mul(stride_var3, offset_sym28));
    expression2 = symbolic::add(expression2, symbolic::mul(symbolic::mul(stride_var3, stride_var2), sym_24));
    expression2 = symbolic::add(expression2, symbolic::mul(symbolic::mul(symbolic::mul(stride_var3, stride_var2), stride_var1), sym_13));

    EXPECT_FALSE(symbolic::maps::intersects({expression1}, {expression2}, sym_13, assumptions_set1, assumptions_set2));
    EXPECT_TRUE(symbolic::maps::intersects({expression1}, {expression2}, sym_24, assumptions_set1, assumptions_set2));

    // Expression 3: 1 + _32 + (2 + _3)*_28 + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expression3 = symbolic::add(offset_sym32, symbolic::mul(stride_var3, sym_28));
    expression3 = symbolic::add(expression3, symbolic::mul(symbolic::mul(stride_var3, stride_var2), offset_sym24));
    expression3 = symbolic::add(expression3, symbolic::mul(symbolic::mul(symbolic::mul(stride_var3, stride_var2), stride_var1), sym_13));

    EXPECT_FALSE(symbolic::maps::intersects({expression1}, {expression3}, sym_13, assumptions_set1, assumptions_set2));
    EXPECT_TRUE(symbolic::maps::intersects({expression1}, {expression3}, sym_28, assumptions_set1, assumptions_set2));

    // Expression 4: _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto expression4 = symbolic::add(sym_32, symbolic::mul(stride_var3, offset_sym28));
    expression4 = symbolic::add(expression4, symbolic::mul(symbolic::mul(stride_var3, stride_var2), offset_sym24));
    expression4 = symbolic::add(expression4, symbolic::mul(symbolic::mul(symbolic::mul(stride_var3, stride_var2), stride_var1), sym_13));

    EXPECT_FALSE(symbolic::maps::intersects({expression1}, {expression4}, sym_13, assumptions_set1, assumptions_set2));
    EXPECT_TRUE(symbolic::maps::intersects({expression1}, {expression4}, sym_32, assumptions_set1, assumptions_set2));
}

#include "test.h"
template <typename T>
Array<uint64_t, 2> computeHash(const T &element) noexcept {
    auto buffer = memory::viewCast(element);
    Array<uint64_t, 2> result;
    MurmurHash3_x64_128(buffer, _nc<int>(buffer.size()), 0, result.data());
    return result;
}
uint64_t indexHash(uint8_t k, uint64_t firstHash, uint64_t secondHash,
                   uint64_t tableSize) noexcept {
    return (firstHash + k * secondHash) % tableSize;
}
struct ProbabilisticSet {
    ProbabilisticSet(uint64_t capacity, uint8_t hashCount) noexcept
        : m_storage(capacity), m_hashCount(hashCount) {}
    template <typename T>
    void insert(const T &value) noexcept {
        auto buffer = memory::viewCast(value);
        auto hashes = computeHash(buffer);
        for (uint8_t k = 0; k < m_hashCount; k++) {
            m_storage[indexHash(k, hashes[0], hashes[1], m_storage.size())] =
                true;
        }
    }
    template <typename T>
    bool mightContain(const T &value) const noexcept {
        auto buffer = memory::viewCast(value);
        auto hashes = computeHash(buffer);
        for (uint8_t k = 0; k < m_hashCount; k++) {
            if (!m_storage[indexHash(k, hashes[0], hashes[1],
                                    m_storage.size())]) {
                return false;
            }
        }
        return true;
    }
private:
    uint8_t m_hashCount;
    std::vector<bool> m_storage;
};
TEST_CASE("util::ProbabilisticSet") {
    ProbabilisticSet set(1'000, 13);
    // Insert every even number
    auto inserted = 0;
    for (auto idx = 0; idx < 1'000; idx++) {
        if (!(idx % 2)) {
            set.insert(idx);
            inserted++;
        }
    }
    // Verify now that all the evens possibly exist and all the odds definitely
    // don't exist
    auto maybeFound = 0, definitelyNotFound = 0, mismatches = 0;
    for (auto idx = 0; idx < 1'000; idx++) {
        auto containsCheck = false;
        if (!(idx % 2))
            containsCheck = set.mightContain(idx);
        else
            containsCheck = set.mightContain(idx);
        if (containsCheck)
            maybeFound++;
        else {
            definitelyNotFound++;
            if (!(idx % 2)) {
                LOG(Test, "Set incorrectly says {} is not possible...", idx);
                mismatches++;
            }
        }
    }
    LOG(Test, "Maybe found: {,c} Definitely not found: {,c} Inserted: {,c} Mismatches: {,c}",
        maybeFound, definitelyNotFound, inserted, mismatches);
}

