    bool IsDelimiter(const std::uint32_t ch)
    {
        if (ch == U' ' || ch == U'\t')
            return true;
        static constexpr std::u32string_view delimiters = U".,;:!?()[]{}/\\-_@#%&*";
        return delimiters.find(static_cast<char32_t>(ch)) != std::u32string_view::npos;
    }

    size_t LocateWordBegin(const sf::String& text, const size_t position)
    {
        size_t left = position;
        while (left > 0)
        {
            const auto character = text[left - 1];
            if (IsDelimiter(character))
                left--;
            else
                break;
        }
        while (left > 0)
        {
            const auto character = text[left - 1];
            if (!IsDelimiter(character))
                left--;
            else
                break;
        }
        return left;
    }

    size_t LocateWordEnd(const sf::String& text, const size_t position)
    {
        size_t right = position;
        const size_t length = text.getSize();
        while (right < length)
        {
            const auto character = text[right];
            if (IsDelimiter(character))
                right++;
            else
                break;
        }
        while (right < length)
        {
            const auto character = text[right];
            if (!IsDelimiter(character))
                right++;
            else
                break;
        }
        return right;
    }
}

