    bool InputField::IsNextCharacterFit()
    {
        const auto currentText = m_textLabel.GetText();
        auto position = m_cursor.Index;
        if (m_cursor.SelectionLength != 0)
            position = static_cast<int>(Remove(position - 1, m_cursor.SelectionLength));

        auto newText = m_textLabel.GetText();
        newText.insert(position, " ");
        m_textLabel.SetText(newText);

        const bool fits = m_textLabel.GetLocalBounds().size.x <= m_area.size.x;

        m_textLabel.SetText(currentText);
        return fits;
    }

    void InputField::Select(const std::size_t index, const int selectionLength)
    {
        m_cursor.Index = static_cast<int>(index);
        m_cursor.SelectionLength = selectionLength;
        SetFocus(true);
        Invalidate();
    }

    void InputField::SelectAll()
