    sf::String InputField::GetSelectedText() const
    {
        auto position = m_cursor.Index - 1;
        const auto length = m_cursor.SelectionLength;
        if (length < 0)
            position += length + 1;
        else if (length > 0)
            position++;
        else
            return {};

        return m_textLabel.GetText().substring(position, std::abs(length));
    }

    size_t InputField::Insert(size_t position, const std::uint32_t unicode, const int selectionLength)
    {
        if (unicode <= 31 || // backspace, tab, enter, etc
            unicode == 127)  // ctrl+backspace
        {
            return position;
        }

        // Max length validation
        if (m_limitLength > 0 && selectionLength == 0 && m_textLabel.GetText().getSize() >= m_limitLength)
            return position;

        // Max visual bounds validation
        if (IsNextCharacterFit())
        {
            if (m_cursor.SelectionLength != 0)
                position = Remove(position - 1, selectionLength);

            auto text = m_textLabel.GetText();
            text.insert(position, sf::String(static_cast<char32_t>(unicode)));
            m_textLabel.SetText(text);
            return ++position;
        }
        return position;
    }

    std::size_t InputField::Remove(std::size_t position, const int length)
    {
        if (length < 0)
            position += length + 1;
        else if (length > 0)
            position++;
        else
            return position;

        auto text = m_textLabel.GetText();
        text.erase(position, std::abs(length));
        m_textLabel.SetText(text);
        return position;
    }

