    void InputField::OnKeyPressed(const sf::Event::KeyPressed& ev)
    {
        if (!IsEnabled() || !IsFocused())
            return;

        bool control = ev.control;
#ifdef __APPLE__
        control = ev.system;
#endif

        if (ev.code == sf::Keyboard::Key::Backspace || (ev.code == sf::Keyboard::Key::Delete && m_cursor.SelectionLength != 0))
        {
            if (m_cursor.Index == 0 && m_cursor.SelectionLength == 0)
                return;

            int eraseLength = m_cursor.SelectionLength == 0 ? -1 :  m_cursor.SelectionLength;

            if (m_cursor.SelectionLength == 0 && control)
            {
                if (!ev.shift)
                {
                    const size_t left = LocateWordBegin(m_textLabel.GetText(), static_cast<size_t>(m_cursor.Index));
                    eraseLength = -static_cast<int>(static_cast<size_t>(m_cursor.Index) - left);
                }
                else
                {
                    eraseLength = -static_cast<int>(static_cast<size_t>(m_cursor.Index));
                }
            }

            m_cursor.Index = static_cast<int>(Remove(m_cursor.Index - 1, eraseLength));
            m_cursor.SelectionLength = 0;
        }
        else if (ev.code == sf::Keyboard::Key::Delete)
        {
            if (m_cursor.Index >= m_textLabel.GetText().getSize())
                return;

            if (control && ev.shift)
            {
                const size_t from = static_cast<size_t>(m_cursor.Index);
                const size_t end  = m_textLabel.GetText().getSize();
                const int delta   = static_cast<int>(end - from);
                if (delta <= 0)
                    return;

                m_cursor.Index = static_cast<int>(Remove(m_cursor.Index - 1, delta));
                m_cursor.SelectionLength = 0;
            }
            else if (control)
            {
                const size_t from = static_cast<size_t>(m_cursor.Index);
                const size_t right = LocateWordEnd(m_textLabel.GetText(), from);
                const int delta = static_cast<int>(right - from);
                if (delta <= 0)
                    return;

                m_cursor.Index = static_cast<int>(Remove(m_cursor.Index - 1, delta));
                m_cursor.SelectionLength = 0;
            }
            else
            {
                auto text = m_textLabel.GetText();
                text.erase(m_cursor.Index);
                m_textLabel.SetText(text);
                m_cursor.SelectionLength = 0;
            }
        }
        else if (ev.code == sf::Keyboard::Key::Enter)
        {
            // Trim front and back string from whitespaces
            const sf::String text = StringHelper::Trim(m_textLabel.GetText());
            if (!text.isEmpty() && m_onTextSubmitted)
                m_onTextSubmitted(*this, text);

            m_textLabel.SetText("");
            m_cursor.SelectionLength = 0;
        }
        else if (control || ev.shift)
        {
            if (ev.shift)
            {
                if (control && ev.code == sf::Keyboard::Key::Left)
                {
                    if (m_cursor.Index <= 0)
                        return;

                    const size_t from = static_cast<size_t>(m_cursor.Index);
                    const size_t left = LocateWordBegin(m_textLabel.GetText(), from);
                    const int delta = static_cast<int>(from - left);
                    if (delta <= 0)
                        return;

                    m_cursor.Index -= delta;
                    m_cursor.SelectionLength += delta;
                }
                else if (control && ev.code == sf::Keyboard::Key::Right)
                {
                    if (m_cursor.Index >= m_textLabel.GetText().getSize())
                        return;

                    const size_t from = static_cast<size_t>(m_cursor.Index);
                    const size_t right = LocateWordEnd(m_textLabel.GetText(), from);
                    const int delta = static_cast<int>(right - from);
                    if (delta <= 0)
                        return;

                    m_cursor.Index += delta;
                    m_cursor.SelectionLength -= delta;
                }
                else if (ev.code == sf::Keyboard::Key::Left)
                {
                    if (m_cursor.Index <= 0)
                        return;

                    m_cursor.Index--;
                    m_cursor.SelectionLength++;
                }
                else if (ev.code == sf::Keyboard::Key::Right)
                {
                    if (m_cursor.Index >= m_textLabel.GetText().getSize())
                        return;

                    m_cursor.Index++;
                    m_cursor.SelectionLength--;
                }
            }

            if (control)
            {
                if (ev.code == sf::Keyboard::Key::C || ev.code == sf::Keyboard::Key::X)
                {
                    sf::Clipboard::setString(GetSelectedText());
                    if (ev.code == sf::Keyboard::Key::X)
                    {
                        m_cursor.Index = static_cast<int>(Remove(m_cursor.Index - 1, m_cursor.SelectionLength));
                        m_cursor.SelectionLength = 0;
                    }
                }
                else if (ev.code == sf::Keyboard::Key::V)
                {
                    std::string input = sf::Clipboard::getString();
                    auto text = sf::String::fromUtf32(input.begin(), input.end());
                    for (size_t index = 0; index < text.getSize(); index++)
                        m_cursor.Index = static_cast<int>(Insert(m_cursor.Index, text[index]));
                }
                else if (ev.code == sf::Keyboard::Key::A)
                {
                    SelectAll();
                }
                else if (!ev.shift && ev.code == sf::Keyboard::Key::Left)
                {
                    const size_t left = LocateWordBegin(m_textLabel.GetText(), static_cast<size_t>(m_cursor.Index));
                    m_cursor.Index = static_cast<int>(left);
                    m_cursor.SelectionLength = 0;
                }
                else if (!ev.shift && ev.code == sf::Keyboard::Key::Right)
                {
                    const size_t right = LocateWordEnd(m_textLabel.GetText(), static_cast<size_t>(m_cursor.Index));
                    m_cursor.Index = static_cast<int>(right);
                    m_cursor.SelectionLength = 0;
                }
            }
        }
        else if (ev.code == sf::Keyboard::Key::Left)
        {
            m_cursor.Index--;
            m_cursor.SelectionLength = 0;
            m_textLabel.SetColor(m_textLabel.GetColor());
        }
        else if (ev.code == sf::Keyboard::Key::Right)
        {
            m_cursor.Index++;
            m_cursor.SelectionLength = 0;
            m_textLabel.SetColor(m_textLabel.GetColor());
        }
        else
            return;

        Invalidate();
    }

    void InputField::OnTextEntered(const sf::Event::TextEntered& ev)
    {
        if (!IsEnabled() || !IsFocused())
            return;

        // backspace, tab, enter, etc
        if (ev.unicode <= 31)
            return;

#ifdef __APPLE__
        // Delete key
        if (ev.unicode == 127)
            return;
#endif

        // Only accept numbers
        if (m_numberOnly && (ev.unicode < 48 || ev.unicode > 57))
            return;

        m_cursor.Index = static_cast<int>(Insert(m_cursor.Index, ev.unicode, m_cursor.SelectionLength));
        m_cursor.SelectionLength = 0;
        Invalidate();
    }

    void InputField::Invalidate()
    {
        m_cursor.Invalidate();
        m_cursor.Reset(true);

        size_t start = m_cursor.Index;
        if (m_cursor.SelectionLength < 0)
            start += m_cursor.SelectionLength;

        m_textLabel.SetColor(m_textLabel.GetColor());

        if (m_cursor.SelectionLength != 0)
        {
            for (size_t index = 0; index < m_textLabel.GetText().getSize(); index++)
            {
                if (index >= start && index < start + std::abs(m_cursor.SelectionLength))
                    m_textLabel.SetColor(m_selectionColor, index);
            }
        }
    }
}

namespace Gx
{
    InputField::Caret::Caret(InputField& instance) :
        Instance(instance),
        Index(),
        SelectionLength(),
        m_cursor(),
        m_highlight(),
        m_visible(true),
        m_elapsed()
    {
        SetHighlightColor(sf::Color::Transparent);
        Invalidate();
    }

    void InputField::Caret::Reset(const bool visible)
    {
        m_elapsed = 0;
        m_visible = visible;
    }

    const Rectangle& InputField::Caret::GetHighlight() const
    {
        return m_highlight;
    }

    void InputField::Caret::SetHighlightColor(const sf::Color color)
    {
        m_highlight.SetColor(color);
    }

    RenderStates InputField::Caret::Render(RenderSurface& surface, RenderStates states) const
    {
        if (!m_visible)
            return states;

        surface.Render(m_cursor, states);
        return states;
    }

    void InputField::Caret::Update(const double delta)
    {
        m_elapsed += delta;
        if (m_elapsed >= BLINK_THRESHOLD)
        {
            m_elapsed = 0;
            m_visible = !m_visible;
        }
    }

    void InputField::Caret::Invalidate()
    {
        if (Index < 0)
            Index = 0;

        if (Index > Instance.GetText().getSize())
            Index = static_cast<int>(Instance.GetText().getSize());

        if (Instance.GetFont())
        {
            const auto glyph = Instance.GetFont()->GetGlyph('|', 0, Instance.GetFontSize(), false);
            m_cursor.SetSize(sf::Vector2f(glyph.bounds.size.x * 0.65f, static_cast<float>(Instance.GetFontSize())));
        }

        m_cursor.SetPosition(Instance.FindCharacterPosition(Index) + sf::Vector2f(0.f, 1.5f));
        m_cursor.SetColor(Instance.GetTextColor());

        if (SelectionLength != 0)
        {
            size_t index = Index - 1;
            const int length   = SelectionLength;
            if (length < 0)
                index += length + 1;
            else if (length > 0)
                index++;

            const auto charPos = Instance.FindCharacterPosition(index);
            const auto endPos  = Instance.FindCharacterPosition(index + std::abs(length));

            m_highlight.SetPosition(sf::Vector2f(charPos.x, m_cursor.GetPosition().y));
            m_highlight.SetSize(sf::Vector2f(std::abs(charPos.x - endPos.x), static_cast<float>(Instance.GetFontSize())));
        }
        else
            m_highlight.SetSize(sf::Vector2f());
    }
}

#include "fonticon.h"
#include "resources.h"
#include <QIconEngine>
#include <QPainter>
#include <QPixmapCache>
using namespace OCC::Resources;

namespace {
class IconRenderer : public QIconEngine
{
public:
    IconRenderer(FontIcon::FontFamily family, QChar symbol, FontIcon::Size dim, const QColor &ink)
        : _fontFamily(family)
        , _glyphSymbol(symbol)
        , _dimension(dim)
        , _inkColor(ink.isValid() ? ink : OCC::Resources::tint())
    {
    }

    void paint(QPainter *drawer, const QRect &area, QIcon::Mode, QIcon::State) override
    {
        drawer->save();
        drawer->setRenderHint(QPainter::Antialiasing);
        auto currentPen = drawer->pen();
        currentPen.setColor(_inkColor);
        drawer->setPen(currentPen);
        auto currentFont = drawer->font();

        switch (_fontFamily) {
        case FontIcon::FontFamily::FontAwesome:
            currentFont.setFamily(QStringLiteral("Font Awesome 6 Free"));
            break;
        case FontIcon::FontFamily::RemixIcon:
            currentFont.setFamily(QStringLiteral("remixicon"));
            break;
        }

        switch (_dimension) {
        case FontIcon::Size::Normal:
            currentFont.setPixelSize(area.height());
            break;
        case FontIcon::Size::Half:
            currentFont.setPixelSize(static_cast<int>(area.height() / 2.0));
            break;
        }

        const auto alignment = Qt::AlignHCenter | Qt::AlignVCenter;
        QFontMetricsF fontMetrics(currentFont);
        QRectF glyphBounds = fontMetrics.boundingRect(area, alignment, _glyphSymbol);

        if (glyphBounds.width() > area.width()) {
            int adjustedSize = static_cast<int>(
                currentFont.pixelSize() * qMin(area.width() * 0.95 / glyphBounds.width(),
                                               fontMetrics.height() * 0.95 / glyphBounds.height()));
            currentFont.setPixelSize(adjustedSize);
        }

        drawer->setFont(currentFont);
        drawer->drawText(area, alignment, _glyphSymbol);
        drawer->restore();
    }

    QPixmap toPixmap(const QSize &requestedSize, QIcon::Mode mode, QIcon::State state) override
    {
        QPixmap result;
        const QString cacheKey = generateCacheKey(requestedSize, mode, state);
        if (QPixmapCache::find(cacheKey, &result)) {
            return result;
        }

        result = QPixmap(requestedSize);
        result.fill(Qt::transparent);
        QPainter painter(&result);
        paint(&painter, {{0, 0}, requestedSize}, mode, state);
        painter.end();

        QPixmapCache::insert(cacheKey, result);
        return result;
    }

    QIconEngine *clone() const override { 
        return new IconRenderer(this->_fontFamily, this->_glyphSymbol, this->_dimension, this->_inkColor); 
    }

    QString generateCacheKey(const QSize &requestedSize, QIcon::Mode mode, QIcon::State state)
    {
        return QStringLiteral("FontIcon:%1").arg(
            QString::number(qHashMulti(0, _fontFamily, _glyphSymbol, _dimension, _inkColor.rgb(), requestedSize, mode, state), 16));
    }

private:
    const FontIcon::FontFamily _fontFamily;
    const QChar _glyphSymbol;
    const FontIcon::Size _dimension;
    const QColor _inkColor;
};
}

// --- Public FontIcon implementation ---

FontIcon::FontIcon() { }

FontIcon::FontIcon(QChar symbol, Size dim, const QColor &ink)
    : QIcon(new IconRenderer(FontFamily::FontAwesome, symbol, dim, ink))
{
}

FontIcon::FontIcon(DefaultGlyphes symbol, Size dim, const QColor &ink)
    : FontIcon(static_cast<std::underlying_type_t<DefaultGlyphes>>(symbol), dim, ink)
{
}

FontIcon::FontIcon(FontFamily family, QChar symbol, Size dim, const QColor &ink)
    : QIcon(new IconRenderer(family, symbol, dim, ink))
{
}

