using namespace wowee;

static void printUsage() {
    std::cerr
        << "Usage:\n"
        << "  auth_probe <host> <port> <account> <major> <minor> <patch> <build> <proto> <locale> [platform] [os]\n"
        << "Example:\n"
        << "  auth_probe logon.turtle-server-eu.kz 3724 test 1 12 1 5875 8 enGB x86 Win\n";
}

int main(int argc, char** argv) {
    if (argc < 10) {
        printUsage();
        return 2;
    }

    const std::string serverHost = argv[1];
    const int serverPort = std::atoi(argv[2]);
    const std::string accountName = argv[3];
    const int versionMajor = std::atoi(argv[4]);
    const int versionMinor = std::atoi(argv[5]);
    const int versionPatch = std::atoi(argv[6]);
    const int buildNumber = std::atoi(argv[7]);
    const int protocolVersion = std::atoi(argv[8]);
    const std::string localeCode = argv[9];
    const std::string platformType = (argc >= 11) ? argv[10] : "x86";
    const std::string osName = (argc >= 12) ? argv[11] : "Win";

    auth::ClientInfo clientInfo;
    clientInfo.majorVersion = static_cast<uint8_t>(versionMajor);
    clientInfo.minorVersion = static_cast<uint8_t>(versionMinor);
    clientInfo.patchVersion = static_cast<uint8_t>(versionPatch);
    clientInfo.build = static_cast<uint16_t>(buildNumber);
    clientInfo.protocolVersion = static_cast<uint8_t>(protocolVersion);
    clientInfo.locale = localeCode;
    clientInfo.platform = platformType;
    clientInfo.os = osName;

    std::atomic<bool> operationCompleted{false};
    std::atomic<int> resultStatus{0xFF};
    std::atomic<bool> responseReceived{false};

    network::TCPSocket socket;
    socket.setPacketCallback([&](const network::Packet& packet) {
        network::Packet pkt = packet;
        if (pkt.getSize() < 3) {
            return;
        }

        uint8_t opcode = pkt.readUInt8();
        if (opcode != static_cast<uint8_t>(auth::AuthOpcode::LOGON_CHALLENGE)) {
            return;
        }

        auth::LogonChallengeResponse response{};
        if (!auth::LogonChallengeResponseParser::parse(pkt, response)) {
            std::cerr << "Parsing the response failed\n";
            resultStatus = 0xFE;
        } else {
            resultStatus = static_cast<int>(response.result);
            if (response.isSuccess()) {
                std::cerr << "SUCCESS secFlags=0x" << std::hex << (int)response.securityFlags << std::dec << "\n";
            } else {
                std::cerr << "FAIL code=0x" << std::hex << (int)response.result << std::dec
                          << " (" << auth::getAuthResultString(response.result) << ")\n";
            }
        }

        responseReceived = true;
        operationCompleted = true;
    });

    if (!socket.connect(serverHost, static_cast<uint16_t>(serverPort))) {
        std::cerr << "Connection to server failed\n";
        return 3;
    }

    auto challengePacket = auth::LogonChallengePacket::build(accountName, clientInfo);
    socket.send(challengePacket);

    auto startTime = std::chrono::steady_clock::now();
    while (!operationCompleted) {
        socket.update();
        std::this_thread::sleep_for(std::chrono::milliseconds(10));

        auto currentTime = std::chrono::steady_clock::now();
        if (std::chrono::duration_cast<std::chrono::milliseconds>(currentTime - startTime).count() > 4000) {
            break;
        }
    }

    socket.disconnect();

    if (!responseReceived) {
        std::cerr << "Timeout waiting for server response\n";
        return 4;
    }

    return resultStatus.load();
}

