using namespace std;

// Retrieve a required parameter value by key from command-line arguments
template <typename T>
T extractArgument(const vector<string>& args, const string& paramName)
{
  auto pos = find(args.begin(), args.end(), "--" + paramName);
  if (pos != args.end() && (pos + 1) != args.end()) {
    return boost::lexical_cast<T>(*(pos + 1));
  } else {
    throw runtime_error("missing required argument: " + paramName);
  }
}

// Specialization for boolean flags (present = true, absent = false)
template <>
bool extractArgument<bool>(const vector<string>& args, const string& paramName)
{
  return find(args.begin(), args.end(), "--" + paramName) != args.end();
}

// Retrieve an optional parameter with a default fallback value
template <typename T>
T extractOptionalArgument(const vector<string>& args, const string& paramName, T defaultValue)
{
  try {
    return extractArgument<T>(args, paramName);
  } catch (const runtime_error&) {
    return defaultValue;
  }
}

// Determine log level from command-line arguments
loot::LogLevel determineLogLevel(const vector<string>& args)
{
  const string logLevelStr = extractOptionalArgument<string>(args, "logLevel", "");
  const auto cliLogLevel = lootcli::logLevelFromString(logLevelStr);
  return lootcli::toLootLogLevel(cliLogLevel);
}

