  setlocale(LC_ALL, "en.UTF-8");

  vector<string> convertedArgs;
  int argCount;
  LPWSTR* wideArgs = CommandLineToArgvW(GetCommandLineW(), &argCount);

  if (wideArgs) {
    for (int idx = 0; idx < argCount; ++idx) {
      size_t charCount;
      size_t bufferSize = (wcslen(wideArgs[idx]) * sizeof(wchar_t)) + 1;
      vector<char> narrowArg(bufferSize);
      wcstombs_s(&charCount, &narrowArg[0], bufferSize, wideArgs[idx], bufferSize - 1);
      convertedArgs.push_back(&narrowArg[0]);
    }
    LocalFree(wideArgs);
  }
#else
int main(int argc, char* argv[])
{
  setlocale(LC_ALL, "en_US.UTF-8");

  vector<string> convertedArgs;
  for (int i = 0; i < argc; ++i) {
    convertedArgs.push_back(argv[i]);
  }
#endif

  // Main processing logic
  try {
    lootcli::LOOTWorker processor;

    processor.setUpdateMasterlist(!extractArgument<bool>(convertedArgs, "skipUpdateMasterlist"));
    processor.setGame(extractArgument<string>(convertedArgs, "game"));
    processor.setGamePath(extractArgument<string>(convertedArgs, "gamePath"));
    processor.setPluginListPath(extractArgument<string>(convertedArgs, "pluginListPath"));
    processor.setOutput(extractArgument<string>(convertedArgs, "out"));
    processor.setLogLevel(determineLogLevel(convertedArgs));

    const string languageCode = extractOptionalArgument<string>(convertedArgs, "language", "");
    if (!languageCode.empty()) {
      processor.setLanguageCode(languageCode);
    }

    return processor.run();
  } catch (const exception& error) {
    cerr << "Error: " << error.what();
    return 1;
