std::optional<std::string> MemoryBuffer::push(std::vector<uint8_t> data) {
    if (!data.empty()) {
        m_total_size += data.size();
        m_chunks.push(std::move(data));
    }
    return std::nullopt;
}

BufferPeekResult MemoryBuffer::peek() {
    U8View chunk_view;
    if (!m_chunks.empty()) {
        const std::vector<uint8_t>& head = m_chunks.front();
        chunk_view = {head.data(), head.size()};
    }
    return {std::nullopt, chunk_view};
}

void MemoryBuffer::drain(size_t bytes_to_remove) {
    assert(bytes_to_remove <= m_total_size);
    m_total_size -= bytes_to_remove;

    while (bytes_to_remove > 0) {
        assert(!m_chunks.empty());
        std::vector<uint8_t>& current_chunk = m_chunks.front();
        size_t remove_amount = std::min(current_chunk.size(), bytes_to_remove);

        current_chunk.erase(current_chunk.begin(), current_chunk.begin() + remove_amount);
        bytes_to_remove -= remove_amount;

        if (current_chunk.empty()) {
            m_chunks.pop();
        }
    }
}

