float camera_angle[3], camera_position[3] = { 60,22,77 };
float zoom_level = 1.0;
float view_rotation = 0.0;
void transform_to_world(float world_coords[3], float cam_x, float cam_y, float cam_z)
{
   float local_vec[3] = { cam_x, cam_y, cam_z };
   float temp[3];
   float sine_val, cosine_val;
   sine_val = (float) sin(camera_angle[0]*3.141592/180);
   cosine_val = (float) cos(camera_angle[0]*3.141592/180);
   temp[0] = local_vec[0];
   temp[1] = cosine_val*local_vec[1] - sine_val*local_vec[2];
   temp[2] = sine_val*local_vec[1] + cosine_val*local_vec[2];
   sine_val = (float) sin(camera_angle[2]*3.141592/180);
   cosine_val = (float) cos(camera_angle[2]*3.141592/180);
   world_coords[0] = cosine_val*temp[0] - sine_val*temp[1];
   world_coords[1] = sine_val*temp[0] + cosine_val*temp[1];
   world_coords[2] = temp[2];
}
// camera worldspace velocity
float camera_velocity[3];
int input_state;
#define MAX_SPEED  150.0f      // blocks per second
#define ACCELERATION      6.0f
#define DECELERATION      3.0f
#define STATIC_FRICTION   DECELERATION
#define EFFECTIVE_ACCEL   (ACCELERATION+DECELERATION)
// dynamic friction:
//
//    if going at MAX_SPEED, ACCELERATION and friction must cancel
//    EFFECTIVE_ACCEL = DECELERATION + DYNAMIC_FRIC*MAX_SPEED
#define DYNAMIC_FRICTION  (ACCELERATION/(float)MAX_SPEED)
float horizontal_view_speed = 0;
float vertical_view_speed = 0;
float target_horizontal_view;
float target_vertical_view;
float target_horizontal_view;
float target_vertical_view;
void update_simulation_raw(float delta_time)
{
   int index;
   float thrust_vector[3] = { 0,0,0 };
   float world_thrust[3];
   // choose direction to apply thrust
   thrust_vector[0] = (input_state &  3)== 1 ? EFFECTIVE_ACCEL : (input_state &  3)== 2 ? -EFFECTIVE_ACCEL : 0;
   thrust_vector[1] = (input_state & 12)== 4 ? EFFECTIVE_ACCEL : (input_state & 12)== 8 ? -EFFECTIVE_ACCEL : 0;
   thrust_vector[2] = (input_state & 48)==16 ? EFFECTIVE_ACCEL : (input_state & 48)==32 ? -EFFECTIVE_ACCEL : 0;
   // @TODO clamp thrust_vector[0] & thrust_vector[1] vector length to EFFECTIVE_ACCEL
   transform_to_world(world_thrust, thrust_vector[0], thrust_vector[1], 0);
   world_thrust[2] += thrust_vector[2];
   for (index=0; index < 3; ++index) {
      float acceleration = world_thrust[index];
      camera_velocity[index] += acceleration*delta_time;
   }
   if (camera_velocity[0] || camera_velocity[1] || camera_velocity[2])
   {
      float speed = (float) sqrt(camera_velocity[0]*camera_velocity[0] + camera_velocity[1]*camera_velocity[1] + camera_velocity[2]*camera_velocity[2]);
      float new_speed = speed;
      float friction = STATIC_FRICTION + DYNAMIC_FRICTION*speed;
      new_speed = speed - friction*delta_time;
      if (new_speed < 0)
         new_speed = 0;
      camera_velocity[0] *= new_speed/speed;
      camera_velocity[1] *= new_speed/speed;
      camera_velocity[2] *= new_speed/speed;
   }
   camera_position[0] += camera_velocity[0] * delta_time;
   camera_position[1] += camera_velocity[1] * delta_time;
   camera_position[2] += camera_velocity[2] * delta_time;
   horizontal_view_speed *= (float) pow(0.75, delta_time);
   vertical_view_speed *= (float) pow(0.75, delta_time);
   horizontal_view_speed += (target_horizontal_view - horizontal_view_speed)*delta_time*60;
   vertical_view_speed += (target_vertical_view - vertical_view_speed)*delta_time*60;
   target_horizontal_view -= horizontal_view_speed * delta_time;
   target_vertical_view -= vertical_view_speed * delta_time;
   camera_angle[0] += horizontal_view_speed * delta_time;
   camera_angle[2] += vertical_view_speed * delta_time;
   camera_angle[0] = stb_clamp(camera_angle[0], -90, 90);
   camera_angle[2] = (float) fmod(camera_angle[2], 360);
}
void update_simulation(float delta_time)
{
   while (delta_time > 1.0f/60) {
      update_simulation_raw(1.0f/60);
      delta_time -= 1.0f/60;
   }
   update_simulation_raw(delta_time);
}
void handle_mouse_movement(float dx, float dy)
{
   // hard-coded mouse sensitivity, not resolution independent?
   target_vertical_view -= dx*300;
   target_horizontal_view -= dy*700;
}
