void render_scene(void)
{
   glEnable(GL_CULL_FACE);
   glDisable(GL_TEXTURE_2D);
   glDisable(GL_LIGHTING);
   glEnable(GL_DEPTH_TEST);
   #ifdef REVERSE_DEPTH
   glDepthFunc(GL_GREATER);
   glClearDepth(0);
   #else
   glDepthFunc(GL_LESS);
   glClearDepth(1);
   #endif
   glDepthMask(GL_TRUE);
   glDisable(GL_SCISSOR_TEST);
   glClearColor(0.6f,0.7f,0.9f,0.0f);
   glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);
   glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
   glColor3f(1,1,1);
   glFrontFace(GL_CW);
   glEnable(GL_TEXTURE_2D);
   glDisable(GL_BLEND);
   glMatrixMode(GL_PROJECTION);
   glLoadIdentity();
   #ifdef REVERSE_DEPTH
   stbgl_Perspective(zoom_level, 90, 70, 3000, 1.0/16);
   #else
   stbgl_Perspective(zoom_level, 90, 70, 1.0/16, 3000);
   #endif
   // now compute where the camera should be
   glMatrixMode(GL_MODELVIEW);
   glLoadIdentity();
   stbgl_initCamera_zup_facing_y();
   glRotatef(-camera_angle[0],1,0,0);
   glRotatef(-camera_angle[2],0,0,1);
   glTranslatef(-camera_position[0], -camera_position[1], -camera_position[2]);
   start_frame = SDL_GetPerformanceCounter();
   render_caves(camera_position);
   end_frame = SDL_GetPerformanceCounter();
   frame_render_duration = (end_frame - start_frame) / (float) SDL_GetPerformanceFrequency();
   glMatrixMode(GL_PROJECTION);
   glLoadIdentity();
   gluOrtho2D(0,window_width/2,window_height/2,0);
   glMatrixMode(GL_MODELVIEW);
   glLoadIdentity();
   glDisable(GL_TEXTURE_2D);
   glDisable(GL_BLEND);
   glDisable(GL_CULL_FACE);
   show_statistics();
}
