static int initialized=0;
static float last_delta_time;
int window_width,window_height;
float accumulated_time = 0;
#define TICKRATE 60
float texture_alpha = 1.0;
int raw_level_time;
float global_timer;
int global_hack;
int game_loop(float delta_time, int real_time, int in_client)
{
   if (!initialized) return 0;
   if (!real_time)
      return 0;
   // don't allow more than 6 frames to update at a time
   if (delta_time > 0.075) delta_time = 0.075;
   global_timer += delta_time;
   accumulated_time += delta_time;
   while (accumulated_time > 1.0/TICKRATE) {
      if (global_hack) {
         texture_alpha += global_hack / 60.0f;
         if (texture_alpha < 0) texture_alpha = 0;
         if (texture_alpha > 1) texture_alpha = 1;
      }
      //update_input();
      // if the player is dead, stop the sim
      accumulated_time -= 1.0/TICKRATE;
   }
   update_simulation(delta_time);
   render_loop();
   return 0;
}
