   switch (e->type) {
      case SDL_MOUSEMOTION:
         handle_sdl_mouse(e);
         break;
      case SDL_MOUSEBUTTONDOWN:
      case SDL_MOUSEBUTTONUP:
         break;
      case SDL_QUIT:
         quit_program = 1;
         break;
      case SDL_WINDOWEVENT:
         switch (e->window.event) {
            case SDL_WINDOWEVENT_SIZE_CHANGED:
               window_width = e->window.data1;
               window_height = e->window.data2;
               game_loop(0,1,0);
               break;
         }
         break;
      case SDL_KEYDOWN: {
         int k = e->key.keysym.sym;
         int s = e->key.keysym.scancode;
         SDL_Keymod mod;
         mod = SDL_GetModState();
         if (k == SDLK_ESCAPE)
            quit_program = 1;
         if (s == SDL_SCANCODE_D)   set_control(0);
         if (s == SDL_SCANCODE_A)   set_control(1);
         if (s == SDL_SCANCODE_W)   set_control(2);
         if (s == SDL_SCANCODE_S)   set_control(3);
         if (k == SDLK_SPACE)       set_control(4); 
         if (s == SDL_SCANCODE_LCTRL)   set_control(5);
         if (s == SDL_SCANCODE_S)   set_control(6);
         if (s == SDL_SCANCODE_D)   set_control(7);
         if (k == '1') global_hack = !global_hack;
         if (k == '2') global_hack = -1;
         #if 0
