static SDL_GLContext *gl_context;
static float calculate_delta_time(float minimum_interval)
{
   float time_passed;
   double current_time;
   static double previous_time = -1;

   if (previous_time == -1)
      previous_time = SDL_GetTicks() / 1000.0 - minimum_interval;
   for(;;) {
      current_time = SDL_GetTicks() / 1000.0;
      time_passed = (float) (current_time - previous_time);
      if (time_passed >= minimum_interval) {
         previous_time = current_time;         
         return time_passed;
      }
      // @TODO: compute correct delay
      SDL_Delay(1);
   }
}
