                                   window_width, window_height,
                                   SDL_WINDOW_OPENGL | SDL_WINDOW_RESIZABLE
                             );
   if (!main_window) report_error("Couldn't create window");
   gl_context = SDL_GL_CreateContext(main_window);
   if (!gl_context) report_error("Couldn't create context");
   SDL_GL_MakeCurrent(main_window, gl_context); // is this true by default?
