      activate_synchronous_debug();
   }
   #endif
   SDL_GL_SetSwapInterval(1);
   render_init();
   mesh_init();
   world_init();
   initialized = 1;
   while (!quit_program) {
      SDL_Event event;
      while (SDL_PollEvent(&event))
         handle_event(&event);
      game_loop(calculate_delta_time(0.0166f/8), 1, 1);
   }
   return 0;
}

