enum class GpuBackend {
    Cpu,
    Cuda,
    Vulkan
};

std::string getProgramPath() {
    char buffer[PATH_MAX];
    ssize_t len = readlink("/proc/self/exe", buffer, PATH_MAX);
    std::string exePath(buffer, (len > 0) ? len : 0);
    size_t slashPos = exePath.find_last_of("/\\");
    return exePath.substr(0, slashPos);
}

bool pathExists(const std::string& filePath) {
    struct stat info;
    return (stat(filePath.c_str(), &info) == 0);
}

void prependToLdLibraryPath(const std::string& dir) {
    const char* currentPath = getenv("LD_LIBRARY_PATH");
    std::string newPath = dir;
    if (currentPath) {
        newPath = dir + ":" + std::string(currentPath);
    }
    setenv("LD_LIBRARY_PATH", newPath.c_str(), 1);
}

bool checkCudaAvailability() {
    return system("ldconfig -p | grep -q libcudart") == 0;
}

bool checkVulkanSupport() {
    void* libHandle = dlopen("libvulkan.so.1", RTLD_NOW | RTLD_LOCAL);
    if (!libHandle) {
        libHandle = dlopen("libvulkan.so", RTLD_NOW | RTLD_LOCAL);
    }
    if (!libHandle) {
        return false;
    }
    dlclose(libHandle);
    return true;
}

extern char **environ;

std::vector<std::string> gatherEnvironmentVariables()
{
    std::vector<std::string> envList;
    for (char **env = environ; *env != nullptr; ++env) {
        envList.emplace_back(*env);
    }
    return envList;
}

void verifyExecutable(const std::string& programPath)
{
    if (access(programPath.c_str(), X_OK) != 0) {
        std::fprintf(stderr, "Binary is not executable: %s\n", programPath.c_str());
        perror("access");
        exit(EXIT_FAILURE);
    }
}

void updateOrSetEnv(std::vector<std::string>& envList,
                    const std::string& keyPrefix,
                    const std::string& value)
{
    for (auto& envEntry : envList) {
        if (envEntry.rfind(keyPrefix, 0) == 0) {
            envEntry = keyPrefix + value;
            return;
        }
    }
    envList.push_back(keyPrefix + value);
}

std::vector<char*> prepareEnvPointerList(std::vector<std::string>& envList)
{
    std::vector<char*> envPtrs;
    envPtrs.reserve(envList.size() + 1);
    for (auto &entry : envList) {
        envPtrs.push_back(entry.data());
    }
    envPtrs.push_back(nullptr);
    return envPtrs;
}

std::vector<char*> prepareArgPointerList(const std::string& programPath, int argc, char** argv)
{
    std::vector<std::string> argVec;
    argVec.push_back(programPath);
    for (int idx = 1; idx < argc; ++idx) {
        if (argv[idx]) {
            argVec.emplace_back(argv[idx]);
        }
    }
    std::vector<char*> argPtrs;
    argPtrs.reserve(argVec.size() + 1);
    for (const auto& arg : argVec) {
        argPtrs.push_back(const_cast<char*>(arg.data()));
    }
    argPtrs.push_back(nullptr);
    return argPtrs;
}

void executeWithEnvironment(const std::string& programPath,
                            std::vector<char*>& argPtrs,
                            std::vector<char*>& envPtrs)
{
    execve(programPath.c_str(), argPtrs.data(), envPtrs.data());
    std::fprintf(stderr, "execve failed\n");
    perror("execve failed");
    exit(EXIT_FAILURE);
}

void launchApplication(const std::string& exeDir,
                       const std::string& libPath,
                       int argc,
                       char** argv,
                       bool cudaDisabled,
                       const std::string& backendLabel,
                       const std::string& ggmlPath,
                       const std::string& deviceName) {
    const std::string appPath = exeDir + "/bin/aifilesorter";
    verifyExecutable(appPath);
    std::vector<std::string> envVars = gatherEnvironmentVariables();
    updateOrSetEnv(envVars, "LD_LIBRARY_PATH=", libPath);
    updateOrSetEnv(envVars, "GGML_DISABLE_CUDA=", cudaDisabled ? "1" : "0");
    updateOrSetEnv(envVars, "AI_FILE_SORTER_GPU_BACKEND=", backendLabel);
    updateOrSetEnv(envVars, "AI_FILE_SORTER_GGML_DIR=", ggmlPath);
    updateOrSetEnv(envVars, "LLAMA_ARG_DEVICE=", deviceName);
    std::vector<char*> envp = prepareEnvPointerList(envVars);
    std::vector<char*> argvp = prepareArgPointerList(appPath, argc, argv);
    executeWithEnvironment(appPath, argvp, envp);
}

struct BackendOverrideSettings {
    std::optional<bool> cuda;
    std::optional<bool> vulkan;
};

BackendOverrideSettings analyzeCommandLineOptions(int argc, char* argv[])
{
    BackendOverrideSettings flags;
    for (int i = 1; i < argc; ++i) {
        const std::string argument = argv[i] ? argv[i] : "";
        if (argument.rfind("--cuda=", 0) == 0) {
            flags.cuda = (argument.substr(7) == "on");
        } else if (argument.rfind("--vulkan=", 0) == 0) {
            flags.vulkan = (argument.substr(9) == "on");
        }
    }
    return flags;
}

bool validateBackendFlags(const BackendOverrideSettings& flags)
{
    if (flags.cuda.has_value() && flags.vulkan.has_value() &&
        flags.cuda.value() && flags.vulkan.value()) {
        std::cerr << "Cannot enable both CUDA and Vulkan at the same time." << std::endl;
        return false;
    }
    return true;
}

struct BackendConfiguration {
    bool cudaSupported{false};
    bool vulkanSupported{false};
    GpuBackend selectedBackend{GpuBackend::Cpu};
    std::string ggmlDirectory;
    std::string backendIdentifier{"cpu"};
    std::string deviceSelection;
};

BackendConfiguration determineBackend(const BackendOverrideSettings& overrides,
                                      const std::string& baseLibPath)
{
    BackendConfiguration config;
    config.cudaSupported = checkCudaAvailability();
    config.vulkanSupported = checkVulkanSupport();

    bool preferCuda = config.cudaSupported;
    bool preferVulkan = !preferCuda && config.vulkanSupported;

    if (overrides.cuda.has_value()) {
        preferCuda = overrides.cuda.value();
        if (preferCuda && !config.cudaSupported) {
            std::cerr << "Warning: CUDA forced but not available; falling back." << std::endl;
            preferCuda = false;
        }
    }

    if (overrides.vulkan.has_value()) {
        preferVulkan = overrides.vulkan.value();
        if (preferVulkan && !config.vulkanSupported) {
            std::cerr << "Warning: Vulkan forced but not available; falling back." << std::endl;
            preferVulkan = false;
        }
    }

    if (preferCuda && preferVulkan) {
        preferVulkan = false; // CUDA takes precedence
    }

    if (preferCuda) {
        config.selectedBackend = GpuBackend::Cuda;
        config.ggmlDirectory = baseLibPath + "/ggml/wcuda";
        config.backendIdentifier = "cuda";
        config.deviceSelection = "cuda";
        std::cout << "Using CUDA backend." << std::endl;
    } else if (preferVulkan) {
        config.selectedBackend = GpuBackend::Vulkan;
        config.ggmlDirectory = baseLibPath + "/ggml/wvulkan";
        config.backendIdentifier = "vulkan";
        config.deviceSelection = "vulkan";
        std::cout << "Using Vulkan backend." << std::endl;
    } else {
        config.selectedBackend = GpuBackend::Cpu;
        config.ggmlDirectory = baseLibPath + "/ggml/wocuda";
        config.backendIdentifier = "cpu";
        config.deviceSelection.clear();
        std::cout << "Using CPU backend." << std::endl;
    }
    return config;
}

int main(int argc, char* argv[]) {
    const std::string programDir = getProgramPath();
    const std::string libraryBasePath = programDir + "/lib";
    BackendOverrideSettings flags = analyzeCommandLineOptions(argc, argv);

    if (!validateBackendFlags(flags)) {
        return EXIT_FAILURE;
    }

    BackendConfiguration backendConfig = determineBackend(flags, libraryBasePath);
    const std::string combinedLdPath = backendConfig.ggmlDirectory + ":" + libraryBasePath;
    const bool disableCudaWhenNotSelected = (backendConfig.selectedBackend != GpuBackend::Cuda);

    launchApplication(programDir,
                      combinedLdPath,
                      argc,
                      argv,
                      disableCudaWhenNotSelected,
                      QString::fromStdString(backendConfig.backendIdentifier),
                      QString::fromStdString(backendConfig.ggmlDirectory),
                      QString::fromStdString(backendConfig.deviceSelection));

    return EXIT_SUCCESS;
}

