bool NgMat::AllowFog() const {
    return !(mBlend == kBlendDest ||
             mBlend == kBlendAdd ||
             mBlend == kBlendSubtract ||
             mBlend == kBlendSrcAlphaAdd);
}

bool NgMat::AllowHDR() const {
    bool noAlphaBlending = (mBlend != kBlendSrcAlpha &&
                            mBlend != kBlendSrcAlphaAdd &&
                            mBlend != kPreMultAlpha);
    return noAlphaBlending && !mAlphaCut && !mAlphaWrite;
}

void NgMat::SetupShader(bool enableAmbient, bool updateConstants) {
    if (updateConstants) {
        SetupAmbient();
    }

    if (this != sCurrent || mDirty) {
        if (mDirty & 2) {
            RefreshState();
        }
        SetBasicState();

        if (updateConstants) {
            SetRegularShaderConst(enableAmbient);
        }

        mDirty = 0;
        sCurrent = this;
    }
}

void NgMat::SetBasicState() {
    RndRenderState::CullMode cullMode;

    switch (mCull) {
    case kCullNone:
        cullMode = RndRenderState::CullMode(0);
        break;
    case kCullRegular:
        cullMode = RndRenderState::CullMode(2);
        break;
    case kCullBackwards:
        cullMode = RndRenderState::CullMode(6);
        break;
    default:
        cullMode = RndRenderState::CullMode(2);
        break;
    }

    TheRenderState.SetCullMode(cullMode);
    TheRenderState.SetBlendEnable(mBlendEnable);
    TheRenderState.SetBlendOp(mBlendOp);
    TheRenderState.SetBlend(unk23c, unk240, unk23c, unk240);
    TheRenderState.SetAlphaTestEnable(mAlphaCut);

    if (mAlphaCut) {
        TheRenderState.SetAlphaFunc(RndRenderState::TestFunc(5), mAlphaThreshold);
    }

    TheRenderState.SetDepthTestEnable(mDepthTestEnable);
    TheRenderState.SetDepthWriteEnable(mDepthWriteEnable);
    TheRenderState.SetDepthFunc(mDepthFunc);

    if (mStencilMode == kStencilIgnore) {
        TheRenderState.SetStencilTestEnable(false);
    } else {
        TheRenderState.SetStencilTestEnable(true);
        TheRenderState.SetStencilFunc(mStencilFunc, 0);
        TheRenderState.SetStencilOp(
            RndRenderState::StencilOp(0),
            RndRenderState::StencilOp(0),
            unk250
        );
    }

    RndRenderState::ClampMode currentClampMode = sTextureWrapModes[mTexWrap];

    if (mDiffuseTex) {
        TheRenderState.SetTextureClamp(0, currentClampMode);
    }
    if (mDiffuseTex2) {
        TheRenderState.SetTextureClamp(6, currentClampMode);
    }
    if (mNormalMap) {
        TheRenderState.SetTextureClamp(1, currentClampMode);
    }
    if (mSpecularMap) {
        TheRenderState.SetTextureClamp(2, currentClampMode);
    }
    if (mEmissiveMap) {
        TheRenderState.SetTextureClamp(3, currentClampMode);
    }

    if (currentClampMode == RndRenderState::ClampMode(6)) {
        bool useWhiteBorder = (mTexWrap == kTexBorderWhite);
        TheRenderState.SetBorderColor(0, useWhiteBorder);
        TheRenderState.SetBorderColor(6, useWhiteBorder);
        TheRenderState.SetBorderColor(1, useWhiteBorder);
        TheRenderState.SetBorderColor(2, useWhiteBorder);
        TheRenderState.SetBorderColor(3, useWhiteBorder);
    }
}

