    if (mUseEnviron) {
        const Vector4& ambientColor =
            reinterpret_cast<const Vector4&>(RndEnviron::Current()->AmbientColor());
        TheShaderMgr.SetVConstant(VShaderConstant(1), ambientColor);
        TheShaderMgr.SetPConstant(PShaderConstant(1), ambientColor);
    } else {
        Vector4 white(1.0f, 1.0f, 1.0f, 1.0f);
        TheShaderMgr.SetVConstant(VShaderConstant(1), white);
        TheShaderMgr.SetPConstant(PShaderConstant(1), white);
    }
}

#include "WebAssemblyTypeUtilities.h"
