using namespace llvm;

MVT WebAssembly::parseMVT(StringRef TypeName) {
  return StringSwitch<MVT>(TypeName)
      .Case("i32", MVT::i32)
      .Case("i64", MVT::i64)
      .Case("f32", MVT::f32)
      .Case("f64", MVT::f64)
      .Case("v16i8", MVT::v16i8)
      .Case("v8i16", MVT::v8i16)
      .Case("v4i32", MVT::v4i32)
      .Case("v2i64", MVT::v2i64)
      .Case("funcref", MVT::funcref)
      .Case("externref", MVT::externref)
      .Default(MVT::INVALID_SIMPLE_VALUE_TYPE);
}

wasm::ValType WebAssembly::toValType(MVT ValueType) {
  switch (ValueType.SimpleTy) {
  case MVT::i32:
    return wasm::ValType::I32;
  case MVT::i64:
    return wasm::ValType::I64;
  case MVT::f32:
    return wasm::ValType::F32;
  case MVT::f64:
    return wasm::ValType::F64;
  case MVT::v16i8:
  case MVT::v8i16:
  case MVT::v4i32:
  case MVT::v2i64:
  case MVT::v4f32:
  case MVT::v2f64:
    return wasm::ValType::V128;
  case MVT::funcref:
    return wasm::ValType::FUNCREF;
  case MVT::externref:
    return wasm::ValType::EXTERNREF;
  default:
    llvm_unreachable("unexpected type encountered");
  }
}

void WebAssembly::wasmSymbolSetType(MCSymbolWasm *Symbol, const Type *GlobalType,
                                    const ArrayRef<MVT> &ElementTypes) {
  assert(!Symbol->getType());

  // Tables are represented as Arrays in LLVM IR, thus they appear here as
  // aggregate Array types with an element type that is a reference type.
  wasm::ValType ValueTy;
  bool IsTable = false;

  if (WebAssembly::isWebAssemblyTableType(GlobalType)) {
    IsTable = true;
    const Type *ElementType = GlobalType->getArrayElementType();

    if (WebAssembly::isWebAssemblyExternrefType(ElementType))
      ValueTy = wasm::ValType::EXTERNREF;
    else if (WebAssembly::isWebAssemblyFuncrefType(ElementType))
      ValueTy = wasm::ValType::FUNCREF;
    else
      report_fatal_error("unsupported reference type");
  } else if (ElementTypes.size() == 1) {
    ValueTy = WebAssembly::toValType(ElementTypes[0]);
  } else {
    report_fatal_error("Aggregate globals not yet supported");
  }

  if (IsTable) {
    Symbol->setType(wasm::WASM_SYMBOL_TYPE_TABLE);
    Symbol->setTableType(ValueTy);
  } else {
    Symbol->setType(wasm::WASM_SYMBOL_TYPE_GLOBAL);
    Symbol->setGlobalType(wasm::WasmGlobalType{uint8_t(ValueTy), /*Mutable=*/true});
  }
}

#include "MavLinkLog.hpp"
