uint64_t MavLinkFileLog::getTimeStamp() {
  return std::chrono::duration_cast<std::chrono::microseconds>(
             std::chrono::high_resolution_clock::now().time_since_epoch())
      .count();
}

MavLinkFileLog::MavLinkFileLog() {
  file_ptr_ = nullptr;
  is_reading_ = false;
  is_writing_ = false;
  use_json_ = false;
}

MavLinkFileLog::~MavLinkFileLog() { close(); }

bool MavLinkFileLog::isOpen() { return is_reading_ || is_writing_; }

void MavLinkFileLog::openForReading(const std::string& filename) {
  close();
  log_file_name_ = filename;
  file_ptr_ = fopen(filename.c_str(), "rb");
  if (file_ptr_ == nullptr) {
    throw std::runtime_error(Utils::stringf(
        "Could not open the file %s, error=%d", filename.c_str(), errno));
  }
  fseek(file_ptr_, 0, SEEK_SET);
  is_reading_ = true;
  is_writing_ = false;
}

void MavLinkFileLog::openForWriting(const std::string& filename, bool json) {
  close();
  use_json_ = json;
  log_file_name_ = filename;
  file_ptr_ = fopen(filename.c_str(), "wb");
  if (file_ptr_ == nullptr) {
    throw std::runtime_error(Utils::stringf(
        "Could not open the file %s, error=%d", filename.c_str(), errno));
  }
  if (json) {
    fprintf(file_ptr_, "{ \"rows\": [\n");
  }
  is_reading_ = false;
  is_writing_ = true;
}

void MavLinkFileLog::close() {
  FILE* saved_ptr = file_ptr_;
  if (use_json_ && file_ptr_ != nullptr) {
    fprintf(file_ptr_,
            "    {}\n");  // so that trailing comma on last row isn't a problem.
    fprintf(file_ptr_, "]}\n");
  }
  file_ptr_ = nullptr;
  if (saved_ptr != nullptr) {
    fclose(saved_ptr);
  }
  is_reading_ = false;
  is_writing_ = false;
}

uint64_t FlipEndianness(uint64_t value) {
  uint64_t result = 0;
  uint64_t temp = value;
  const int size = sizeof(uint64_t);
  for (int i = 0; i < size; i++) {
    uint64_t low_byte = (temp & 0xff);
    result = (result << 8) + low_byte;
    temp >>= 8;
  }
  return result;
}

void MavLinkFileLog::write(const mavlinkcom::MavLinkMessage& msg,
                           uint64_t timestamp) {
  if (file_ptr_ != nullptr) {
    if (is_reading_) {
      throw std::runtime_error("Log file was opened for reading");
    }
    if (use_json_) {
      MavLinkMessageBase* typed_msg = MavLinkMessageBase::lookup(msg);
      if (typed_msg != nullptr) {
        typed_msg->timestamp = timestamp;
        std::string line = typed_msg->toJSon();
        fprintf(file_ptr_, "    %s\n", line.c_str());
        delete typed_msg;
      }
    } else {
      if (timestamp == 0) {
        timestamp = getTimeStamp();
      }
      // for compatibility with QGroundControl we have to save the time field in
      // big endian.
      // todo: mavlink2 support?
      timestamp = FlipEndianness(timestamp);
      fwrite(&timestamp, sizeof(uint64_t), 1, file_ptr_);
      fwrite(&msg.magic, 1, 1, file_ptr_);
      fwrite(&msg.len, 1, 1, file_ptr_);
      fwrite(&msg.seq, 1, 1, file_ptr_);
      fwrite(&msg.sysid, 1, 1, file_ptr_);
      fwrite(&msg.compid, 1, 1, file_ptr_);
      uint8_t msgid = msg.msgid & 0xff;  // truncate to mavlink1 msgid
      fwrite(&msgid, 1, 1, file_ptr_);
      fwrite(&msg.payload64, 1, msg.len, file_ptr_);
      fwrite(&msg.checksum, sizeof(uint16_t), 1, file_ptr_);
    }
  }
}

bool MavLinkFileLog::read(mavlinkcom::MavLinkMessage& msg,
                          uint64_t& timestamp) {
  if (file_ptr_ != nullptr) {
    if (is_writing_) {
      throw std::runtime_error("Log file was opened for writing");
    }
    uint64_t time;
    size_t s = fread(&time, 1, sizeof(uint64_t), file_ptr_);
    if (s < sizeof(uint64_t)) {
      int hr = errno;
      (void)hr; // suppress unused variable warning
      return false;
    }
    timestamp = FlipEndianness(time);
    s = fread(&msg.magic, 1, 1, file_ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.len, 1, 1, file_ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.seq, 1, 1, file_ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.sysid, 1, 1, file_ptr_);
    if (s == 0) {
      return false;
    }
    s = fread(&msg.compid, 1, 1, file_ptr_);
    if (s == 0) {
      return false;
    }
    uint8_t msgid = 0;
    s = fread(&msgid, 1, 1, file_ptr_);
    msg.msgid = msgid;
    if (s < 1) {
      return false;
    }
    s = fread(&msg.payload64, 1, msg.len, file_ptr_);
    if (s < msg.len) {
      return false;
    }
    s = fread(&msg.checksum, 1, sizeof(uint16_t), file_ptr_);
    if (s < sizeof(uint16_t)) {
      return false;
    }
    return true;
  }
  return false;
}

