int CALLBACK WinMain(_In_ HINSTANCE hInst, _In_ HINSTANCE hPrevInst, _In_ LPSTR cmdLine, _In_ int showCmd)
{
    SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);
    // #ifdef FANY_DEBUG
    // Initialize for logging
    InitSpdLogSystem();
    // #endif
    // Load configuration
    SetupImeConfiguration();
    ::InitializeIpcLayer();
    ::CreateNamedPipeInfrastructure();
    g_dictionaryLookup = std::make_unique<DictionaryUlPb>();
    RegisterCandidateWindowEventMessage();

    WNDCLASSEX windowClass;
    RegisterIMEWindowClass(windowClass, hInst);

    //
    // IPC Pipes
    //
    /* Named Pipe for communication between TSF and server */
    std::thread serverPipeThread(FanyNamedPipe::ServiceWorker);
    std::thread mainPipeThread(FanyNamedPipe::MainPipeMonitor);
    /* Named Pipe for TSF data transmission */
    std::thread tsfPipeThread(FanyNamedPipe::TsfDataPipeMonitor);
    ::mainListenerHandle = mainPipeThread.native_handle();
    ::tsfPipeListenerHandle = tsfPipeThread.native_handle();

    /* Worker Thread Pipe for TSF communication */
    std::thread workerPipeThread(FanyNamedPipe::WorkerDataPipeMonitor);
    ::workerPipeListenerHandle = workerPipeThread.native_handle();

    /* Auxiliary pipe for reconnection handling */
    std::thread auxPipeThread(FanyNamedPipe::AuxiliaryPipeMonitor);

    int result = CreateCandidateWindowInstance(hInst);
    g_pipeActiveFlag = false;
    g_queueCondition.notify_one();

    serverPipeThread.join();
    mainPipeThread.join();
    tsfPipeThread.join();
    workerPipeThread.join();
    auxPipeThread.join();

    return result;
}

