}

void flashLed(int index, long color) {
    for (int k = 0; k < 5; k++) {
        updateLed(index, color);
        delay(200);
        updateLed(index, COLOR_BLACK);
        delay(200);
    }
    updateLed(index, color);
}

void turnOffAllLeds() {
    for (int i = 0; i < LED_COUNT; i++) {
        strip.setPixelColor(i, COLOR_BLACK);
    }
    strip.show();
}

void bootSequenceLeds() {
    for (int i = 0; i < FILAMENT_COUNT; i++) {
        updateLed(i, COLOR_CYAN);
        delay(100);
    }
}

void finishBootLeds() {
    for (int i = FILAMENT_COUNT - 1; i >= 0; i--) {
        updateLed(i, COLOR_BLACK);
        delay(100);
    }
}

void blinkBootLeds() {
    unsigned long now = millis();
    if (now - lastBootBlinkTime >= 500) {
        lastBootBlinkTime = now;
        bootBlinkPhase = !bootBlinkPhase;
        for (int i = 0; i < FILAMENT_COUNT; i++) {
            updateLed(i, COLOR_BLACK);
            if (bootBlinkPhase) {
                updateLed(i, COLOR_AMBER);
            } else {
                updateLed(i, COLOR_BLACK);
            }
        }
    }
}

void blinkErrorLeds() {
    while (true) {
        for (int i = 0; i < FILAMENT_COUNT; i++) {
            updateLed(i, COLOR_RED);
        }
        delay(500);
        for (int i = 0; i < FILAMENT_COUNT; i++) {
            updateLed(i, COLOR_BLACK);
        }
        delay(500);
    }
}

void backupLedColors() {
    for (int i = 0; i < LED_COUNT; i++) {
        ledBuffer[i] = strip.getPixelColor(i);
    }
}

void restoreLedColors() {
    for (int i = 0; i < LED_COUNT; i++) {
        strip.setPixelColor(i, ledBuffer[i]);
    }
    strip.show();
}

void randomColorLed(int index) {
    long color;
    int currentPaletteIndex;
    do {
        currentPaletteIndex = random(0, 7);
    } while (currentPaletteIndex == lastPaletteIndex);
    lastPaletteIndex = currentPaletteIndex;

    switch (currentPaletteIndex) {
        case 0: color = COLOR_RED; break;
        case 1: color = COLOR_LIME; break;
        case 2: color = COLOR_BLUE; break;
        case 3: color = COLOR_YELLOW; break;
        case 4: color = COLOR_WHITE; break;
        case 5: color = COLOR_CYAN; break;
        case 6: color = COLOR_MAGENTA; break;
        case 7: color = COLOR_AMBER; break;
    }
    updateLed(index, color);
}

void playShortBeep() {
    int beepDuration = 50;
    tone(PIN_BEEPER, NOTE_C6, beepDuration);
    delay(beepDuration * 1.3);
    noTone(PIN_BEEPER);
}

void playMelody(const int* tune, const int* lengths, int count, bool useLeds) {
    if (useLeds) {
        backupLedColors();
        turnOffAllLeds();
    }

    for (int noteIndex = 0; noteIndex < count; noteIndex++) {
        int duration = lengths[noteIndex];
        int pitch = tune[noteIndex];
        int activeLed;

        do {
            activeLed = random(0, FILAMENT_COUNT - 1);
        } while (activeLed == lastActiveLED);

        lastActiveLED = activeLed;

        if (pitch == 0) {
            noTone(PIN_BEEPER);
        } else {
            tone(PIN_BEEPER, pitch, duration);
            if (useLeds) {
                randomColorLed(activeLed);
            }
        }
        delay(duration * 1.3);
        if (useLeds) {
            updateLed(activeLed, COLOR_BLACK);
        }
    }

    noTone(PIN_BEEPER);
    if (useLeds) {
        restoreLedColors();
    }
}

void playBootSound(bool useLeds) {
    int noteCount = sizeof(BOOT_SEQUENCE) / sizeof(BOOT_SEQUENCE[0]);
    playMelody(BOOT_SEQUENCE, BOOT_NOTE_LENGTHS, noteCount, useLeds);
}

void playAlertSound(bool useLeds) {
    int noteCount = sizeof(ALERT_TONE) / sizeof(ALERT_TONE[0]);
    playMelody(ALERT_TONE, ALERT_TONE_LENGTHS, noteCount, useLeds);
}

void playInsertedSound(bool useLeds) {
    int noteCount = sizeof(INSERT_SOUND) / sizeof(INSERT_SOUND[0]);
    playMelody(INSERT_SOUND, INSERT_SOUND_LENGTHS, noteCount, useLeds);
}

void playRemovedSound(bool useLeds) {
    int noteCount = sizeof(REMOVE_SOUND) / sizeof(REMOVE_SOUND[0]);
    playMelody(REMOVE_SOUND, REMOVE_SOUND_LENGTHS, noteCount, useLeds);
}

void playMarioVictory(bool useLeds) {
    int noteCount = sizeof(MARIO_VICTORY_TUNE) / sizeof(MARIO_VICTORY_TUNE[0]);
    playMelody(MARIO_VICTORY_TUNE, MARIO_VICTORY_BEATS, noteCount, useLeds);
}

bool playMidiCommand(int position) {
    switch (position) {
        case 0:
            playBootSound(true);
            return true;
        case 1:
            playAlertSound(true);
            return true;
        case 2:
            playInsertedSound(true);
            return true;
        case 3:
            playRemovedSound(true);
            return true;
        case 4:
            playMarioVictory(true);
            return true;
        default:
            logError(F("Unknown MIDI "), String(position));
    }
    return false;
}

