long convertMMToDegrees(long mm) {
    return mm * 360 / mmPerRevolution;
}

long convertDegreesToSteps(long degrees) {
    return degrees * MMU_MICROSTEP_DIVISOR * MMU_MOTOR_FULL_STEPS / 360UL;
}

long convertMMToSteps(long mm) {
    long deg = convertMMToDegrees(mm);
    return convertDegreesToSteps(deg);
}

long convertStepsToMM(unsigned long steps) {
    long deg = steps * 360UL / (MMU_MICROSTEP_DIVISOR * MMU_MOTOR_FULL_STEPS);
    return deg * mmPerRevolution / 360;
}

