bool selectFilament(int index) {
    selectedFilament = index;
    for (int i = 0; i < FILAMENT_COUNT; i++) {
        bool present = filamentPresent[i];
        if (present == LOW) {
            updateLed(i, COLOR_CYAN);
        } else {
            updateLed(i, COLOR_BLACK);
        }
    }
    updateLed(selectedFilament, COLOR_WHITE);

    bool state = filamentPresent[selectedFilament];
    int pos = mmuPositions[selectedFilament];
    setMMUPosition(pos);

    if (state == LOW) {
        clearMissingFilament();
        if (hubStateStuck) {
            updateLed(selectedFilament, COLOR_AMBER);
        } else if (hubStateStuck == HIGH) {
            updateLed(selectedFilament, COLOR_DARK_LIME);
        } else {
            updateLed(selectedFilament, COLOR_LIME);
        }
    } else {
        updateLed(selectedFilament, COLOR_RED);
        playAlertSound(false);
        flashLed(selectedFilament, COLOR_RED);
        return false;
    }
    return true;
}

void releaseFilament() {
    backupLedColors();
    if (currentMMUPosition > 90) {
        updateLed(7, COLOR_WHITE);
        setMMUPosition(mmuPositions[7]);
    } else {
        updateLed(0, COLOR_WHITE);
        setMMUPosition(mmuPositions[0]);
    }
    restoreLedColors();
}

bool finalizeSwap() {
    if (hubStateStuck || filamentPresent[selectedFilament] == HIGH) {
        triggerMissingFilament();
        playAlertSound(false);
        return false;
    }
    return true;
}

unsigned long rotateMMU(long degrees, int rpm, bool accelEnabled, bool decelEnabled, bool resetOnSensor) {
    if (degrees == 0) {
        return 0;
    }

    digitalWrite(MMU_GPIO_EN, LOW);

    if (degrees < 0) {
        digitalWrite(MMU_GPIO_DIR, !MMU_ROTATION_DIR);
        degrees *= -1;
    } else {
        digitalWrite(MMU_GPIO_DIR, MMU_ROTATION_DIR);
    }

    if (rpm == 0) {
        rpm = MMU_DEFAULT_SPEED_RPM;
    } else if (rpm < MMU_MIN_SPEED_RPM) {
        rpm = MMU_MIN_SPEED_RPM;
    }

    unsigned long totalSteps = 0;
    unsigned long steps = convertDegreesToSteps(degrees);
    unsigned long decelStart = steps - (steps / 100UL);
    unsigned long pulsePeriod = 60000000UL / ((unsigned long)rpm * MMU_MICROSTEP_DIVISOR * MMU_MOTOR_FULL_STEPS);
    unsigned int targetDelay = pulsePeriod / 2UL;
    unsigned int currentDelay = MMU_SLOW_PULSE_US;
    unsigned long skipCounter = 0;
    bool accelerated = false;
    bool lastHubState = hubStateStuck;

    if (!accelEnabled) {
        currentDelay = targetDelay;
    }

    for (unsigned long stepIndex = 0; stepIndex < steps; stepIndex++) {
        if (skipCounter > MMU_ACCEL_DECEL_SKIP_COUNT) {
            if (decelEnabled && currentDelay != MMU_SLOW_PULSE_US && stepIndex > decelStart) {
                skipCounter = 0;
                currentDelay += 1;
                if (currentDelay > MMU_SLOW_PULSE_US) {
                    currentDelay = MMU_SLOW_PULSE_US;
                }
            } else if (accelEnabled && !accelerated && currentDelay != targetDelay) {
                skipCounter = 0;
                currentDelay -= 1;
                if (currentDelay < targetDelay) {
                    currentDelay = targetDelay;
                    accelerated = true;
                }
            }
        }
        skipCounter++;
        totalSteps++;

        if (hubStateStuck != lastHubState && resetOnSensor) {
            logInfo(F("Resetting on filament sensor"), "");
            stepIndex = 0;
            skipCounter = 0;
            currentDelay = targetDelay;
            lastHubState = hubStateStuck;
        }

        digitalWrite(MMU_GPIO_STEP, HIGH);
        delayMicroseconds(currentDelay);
        digitalWrite(MMU_GPIO_STEP, LOW);
        delayMicroseconds(currentDelay);
    }

    digitalWrite(MMU_GPIO_EN, HIGH);
    return totalSteps;
}

void rotateToSensor(int targetState, long mm, long stuckLimitMM, int direction, int rpm) {
    if (mm == 0) {
        return;
    }

    if (hubStateStuck == targetState) {
        hubStateStuck = true;
        updateLed(selectedFilament, COLOR_AMBER);
        logWarning("Hub sensor stucked", (""));
    }

    digitalWrite(MMU_GPIO_EN, LOW);
    digitalWrite(MMU_GPIO_DIR, direction);

    if (rpm == 0) {
        rpm = MMU_DEFAULT_SPEED_RPM;
    } else if (rpm < MMU_MIN_SPEED_RPM) {
        rpm = MMU_MIN_SPEED_RPM;
    }

    unsigned long stepsToStuck = convertMMToSteps(stuckLimitMM);
    if (direction != MMU_ROTATION_DIR) {
        mm *= -1;
    }

    unsigned long pulsePeriod = 60000000UL / ((unsigned long)rpm * MMU_MICROSTEP_DIVISOR * MMU_MOTOR_FULL_STEPS);
    unsigned int targetDelay = pulsePeriod / 2UL;
    unsigned int currentDelay = MMU_SLOW_PULSE_US;
    unsigned long skipCounter = 0;
    unsigned long checkInterval = 0;
    unsigned long stepsTaken = 0;

    while (hubStateStuck != targetState || hubStateStuck) {
        if (skipCounter > MMU_ACCEL_DECEL_SKIP_COUNT && currentDelay != targetDelay) {
            skipCounter = 0;
            currentDelay -= 1;
            if (currentDelay < targetDelay) {
                currentDelay = targetDelay;
            }
        }

        if (direction != MMU_ROTATION_DIR && stepsTaken > stepsToStuck) {
            hubStateStuck = true;
            updateLed(selectedFilament, COLOR_AMBER);
            logWarning("Hub sensor stucked on retract", (""));
            break;
        } else if (direction == MMU_ROTATION_DIR && stepsTaken > stepsToStuck && !extrudingAutomatically) {
            hubStateStuck = true;
            updateLed(selectedFilament, COLOR_AMBER);
            logWarning("Hub sensor stucked on extrude", (""));
            break;
        }

        digitalWrite(MMU_GPIO_STEP, HIGH);
        delayMicroseconds(currentDelay);
        digitalWrite(MMU_GPIO_STEP, LOW);
        delayMicroseconds(currentDelay);

        checkInterval++;
        skipCounter++;
        stepsTaken++;
    }

    if (hubStateStuck) {
        updateLed(selectedFilament, COLOR_AMBER);
    } else if (hubStateStuck == HIGH) {
        updateLed(selectedFilament, COLOR_DARK_LIME);
    } else {
        updateLed(selectedFilament, COLOR_LIME);
    }

    long degrees = convertMMToDegrees(mm);
    bool resetOnRetract = direction != MMU_ROTATION_DIR;
    unsigned long extraSteps = rotateMMU(degrees, rpm, false, true, resetOnRetract);
    stepsTaken = stepsTaken + extraSteps;
    long stepsInMM = convertStepsToMM(stepsTaken);

    if (direction == MMU_ROTATION_DIR) {
        logInfo(F("Extruded milimeters: "), String(stepsInMM));
    } else if (direction != MMU_ROTATION_DIR) {
        logInfo(F("Retracted milimeters: "), String(stepsInMM));
    }

    digitalWrite(MMU_GPIO_EN, HIGH);
}

void extrudeFilament(long mm, int rpm) {
    long totalStuck = stuckThresholdMM + retractLengthMM;
    rotateToSensor(LOW, mm, totalStuck, MMU_ROTATION_DIR, rpm);
}

void retractFilament(long mm, int rpm) {
    long totalStuck = stuckThresholdMM + extrudeLengthMM;
    rotateToSensor(HIGH, mm, totalStuck, !MMU_ROTATION_DIR, rpm);
}

void readHubStatus() {
    if (hubStateStuck != lastHubState) {
        logInfo(F("Hub state changed to "), String(hubStateStuck));
        lastHubState = hubStateStuck;
        if (selectedFilament > -1 && filamentPresent[selectedFilament] == LOW && !hubStateStuck) {
            if (hubStateStuck == HIGH) {
                updateLed(selectedFilament, COLOR_DARK_LIME);
            } else {
                updateLed(selectedFilament, COLOR_LIME);
                clearMissingFilament();
            }
        }
    }
}

void readAllSensors(bool soundEnabled) {
    for (int i = 0; i < FILAMENT_COUNT; i++) {
        int pin = SENSOR_PINS[i];
        bool state = ioExpander.digitalRead(pin);
        if (state != filamentPresent[i]) {
            filamentPresent[i] = state;
            if (state == LOW) {
                logInfo("Filament T" + String(i) + " inserted", "");
                if (i == selectedFilament) {
                    clearMissingFilament();
                    if (hubStateStuck) {
                        updateLed(selectedFilament, COLOR_AMBER);
                    } else {
                        updateLed(selectedFilament, COLOR_LIME);
                    }
                } else {
                    updateLed(i, COLOR_CYAN);
                }
                if (soundEnabled) {
                    playInsertedSound(false);
                }
            } else {
                logInfo("Filament T" + String(i) + " removed", "");
                if (i == selectedFilament) {
                    triggerMissingFilament();
                    updateLed(i, COLOR_RED);
                    if (soundEnabled) {
                        playAlertSound(false);
                    }
                    flashLed(i, COLOR_RED);
                } else {
                    updateLed(i, COLOR_BLACK);
                    if (soundEnabled) {
                        playRemovedSound(false);
                    }
                }
            }
        }
    }
}

void readButtonPress() {
    bool currentState = ioExpander.digitalRead(BUTTON_PIN);
    bool previousState = !currentState;

    if (currentState == LOW) {
        unsigned long pressStartTime = millis();
        unsigned long pressDuration = 0;
        int pressCount = 0;

        while (currentState == LOW || (millis() - pressStartTime) < DEBOUNCE_WINDOW_MS) {
            currentState = ioExpander.digitalRead(BUTTON_PIN);
            if (currentState != previousState) {
                previousState = currentState;
                if (currentState == LOW) {
                    pressCount++;
                    pressStartTime = millis();
                } else {
                    pressDuration = millis() - pressStartTime;
                }
            }
        }

        playShortBeep();

        if (pressDuration > DEBOUNCE_WINDOW_MS) {
            logInfo(F("Pressed long"), "");
            if (selectedFilament > -1 && filamentPresent[selectedFilament] == LOW && hubStateStuck == HIGH) {
                extrudingAutomatically = true;
                int mmuPos = mmuPositions[selectedFilament];
                updateLed(selectedFilament, COLOR_WHITE);
                setMMUPosition(mmuPos);
                extrudeFilament(extrudeLengthMM, MMU_DEFAULT_SPEED_RPM);
                releaseFilament();
                extrudingAutomatically = false;
            }
        } else if (pressCount == 1) {
            logInfo(F("Pressed short"), "");
            releaseFilament();
        } else if (pressCount == 2) {
            logInfo(F("Pressed double"), "");
            setSlicerPosition(slicerClosedAngle);
            setSlicerPosition(slicerOpenAngle);
        } else {
            logWarning(F("Unknown press count "), String(pressCount));
            playAlertSound(false);
        }
    }
}

void processSerialCommand() {
    String input = Serial.readStringUntil('\n');
    input.toUpperCase();
    input.trim();

    if (input == F("START")) {
        logInfo(F("Starting up..."), "");
        turnOffAllLeds();
        bootSequenceLeds();
        playBootSound(true);
        finishBootLeds();
        updateHubState();
        readAllSensors(false);
        initializationComplete = true;
        logInfo(F("Started"), "");
        sendAck();
    } else if (input.startsWith(F("SYNC"))) {
        logInfo(F("Syncing config..."), "");
        int newPositions[FILAMENT_COUNT];
        const char* inputStr = input.c_str();
        const char* posStr = strstr(inputStr, "FILAMENT_POSITIONS");
        if (posStr) {
            sscanf(posStr, "FILAMENT_POSITIONS (%d, %d, %d, %d, %d, %d, %d, %d)",
                   &newPositions[0], &newPositions[1], &newPositions[2], &newPositions[3],
                   &newPositions[4], &newPositions[5], &newPositions[6], &newPositions[7]);
            for (int i = 0; i < FILAMENT_COUNT; i++) {
                mmuPositions[i] = newPositions[i];
            }
        }
        const char* extStr = strstr(inputStr, "EXTRUDE_MM");
        if (extStr) {
            sscanf(extStr, "EXTRUDE_MM %ld", &extrudeLengthMM);
        }
        const char* rtrStr = strstr(inputStr, "RETRACT_MM");
        if (rtrStr) {
            sscanf(rtrStr, "RETRACT_MM %ld", &retractLengthMM);
        }
        const char* mmPerRotStr = strstr(inputStr, "MM_PER_ROTATION");
        if (mmPerRotStr) {
            sscanf(mmPerRotStr, "MM_PER_ROTATION %lf", &mmPerRevolution);
        }
        const char* mmToStkStr = strstr(inputStr, "MM_TO_STUCK");
        if (mmToStkStr) {
            sscanf(mmToStkStr, "MM_TO_STUCK %ld", &stuckThresholdMM);
        }
        const char* cutterOpenStr = strstr(inputStr, "CUTTER_OPENED");
        if (cutterOpenStr) {
            sscanf(cutterOpenStr, "CUTTER_OPENED %d", &slicerOpenAngle);
        }
        const char* cutterCloseStr = strstr(inputStr, "CUTTER_CLOSED");
        if (cutterCloseStr) {
            sscanf(cutterCloseStr, "CUTTER_CLOSED %d", &slicerClosedAngle);
        }

        logInfo(F("New positions: "), "");
        for (int i = 0; i < FILAMENT_COUNT; i++) {
            logInfo(String(i + 1) + " => " + String(mmuPositions[i]), "");
        }
        logInfo(F("New extrude mm: "), String(extrudeLengthMM));
        logInfo(F("New retract mm: "), String(retractLengthMM));
        logInfo(F("New mm per rotation: "), String(mmPerRevolution));
        logInfo(F("New mm to stuck: "), String(stuckThresholdMM));
        logInfo(F("New cutter opened pos: "), String(slicerOpenAngle));
        logInfo(F("New cutter closed pos: "), String(slicerClosedAngle));
        logInfo(F("Config synced"), "");
        sendAck();
    } else if (input.startsWith(F("FILAMENT_RELEASE"))) {
        logInfo(F("Releasing filament"), "");
        sendAck();
        releaseFilament();
        logInfo(F("Filament released"), "");
    } else if (input.startsWith(F("FILAMENT"))) {
        int index = input.substring(input.indexOf(' ') + 1).toInt();
        logInfo(F("Setting filament T"), String(index));
        bool success = selectFilament(index);
        if (success) {
            logInfo(F("Filament set"), "");
            sendAck();
        } else {
            logError(F("Failed to set filament T"), String(index));
            sendFail();
        }
    } else if (input.startsWith(F("EXTRUDE"))) {
        long mm = 0;
        int rpm = 0;
        sscanf(input.c_str(), "EXTRUDE %ld %d", &mm, &rpm);
        logInfo(F("Extruding..."), "");
        extrudeFilament(mm, rpm);
        logInfo(F("Extruded"), "");
        sendAck();
    } else if (input.startsWith(F("RETRACT"))) {
        long mm = 0;
        int rpm = 0;
        sscanf(input.c_str(), "RETRACT %ld %d", &mm, &rpm);
        logInfo(F("Retracting..."), "");
        sendAck();
        delay(350);
        retractFilament(mm, rpm);
        logInfo(F("Retracted"), "");
    } else if (input.startsWith(F("SWAP_FINISH"))) {
        logInfo(F("Swap finishing..."), "");
        bool done = finalizeSwap();
        if (done) {
            logInfo(F("Swap finished"), "");
            sendAck();
        } else {
            logInfo(F("Swap not finished"), "");
            sendFail();
        }
    } else if (input.startsWith(F("CUTTER_POSITION"))) {
        int angle = input.substring(input.indexOf(' ') + 1).toInt();
        logInfo(F("Setting cutter position to "), String(angle));
        setSlicerPosition(angle);
        logInfo(F("Cutter position set to "), String(angle));
        sendAck();
    } else if (input.startsWith(F("MMU_POSITION"))) {
        int angle = input.substring(input.indexOf(' ') + 1).toInt();
        logInfo(F("Setting MMU position to "), String(angle));
        setMMUPosition(angle);
        logInfo(F("MMU position set to "), String(angle));
        sendAck();
    } else if (input.startsWith(F("MMU_ROTATE"))) {
        long deg = 0;
        int rpm = 0;
        sscanf(input.c_str(), "MMU_ROTATE %ld %d", &deg, &rpm);
        logInfo(F("Rotating MMU "), String(deg));
        logInfo(F("RPM "), String(rpm));
        rotateMMU(deg, rpm, true, true, false);
        logInfo(F("MMU rotated "), String(deg));
        sendAck();
    } else if (input.startsWith(F("MIDI"))) {
        int pos = input.substring(input.indexOf(' ') + 1).toInt();
        logInfo(F("Playing MIDI "), String(pos));
        bool played = playMidiCommand(pos);
        if (played) {
            logInfo(F("MIDI played"), "");
            sendAck();
        } else {
            logError(F("Failed to play MIDI "), String(pos));
            sendFail();
        }
    } else if (input.startsWith(F("TEST_LEDS"))) {
        logInfo(F("Testing LEDs..."), "");
        testAllLeds();
        logInfo(F("LEDs tested"), "");
        sendAck();
    } else if (input.startsWith(F("TEST_LED"))) {
        int index = input.substring(input.indexOf(' ') + 1).toInt();
        logInfo(F("Testing LED "), String(index));
        safeTestSingleLed(index - 1);
        logInfo(F("LED tested"), "");
        sendAck();
    } else {
        logError(F("Unknown command "), input);
        sendFail();
    }
}

void setup() {
    Serial.begin(SERIAL_SPEED);
    logInfo(F("Starting..."), "");
    randomSeed(analogRead(0));
    strip.begin();
    pinMode(HUB_SENSOR_PIN, INPUT_PULLUP);
    hubStateStuck = digitalRead(HUB_SENSOR_PIN);
    lastHubState = hubStateStuck;
    attachInterrupt(digitalPinToInterrupt(HUB_SENSOR_PIN), updateHubState, CHANGE);

    pinMode(MMU_GPIO_DIR, OUTPUT);
    pinMode(MMU_GPIO_STEP, OUTPUT);
    pinMode(MMU_GPIO_EN, OUTPUT);
    digitalWrite(MMU_GPIO_EN, HIGH);

    setSlicerPosition(0);
    setMMUPosition(0);

    if (!ioExpander.begin_I2C()) {
        logError(F("Failed to initialize MCP23017"), "");
        blinkErrorLeds();
    }

    ioExpander.pinMode(EXTRUDER_SENSOR_PIN, OUTPUT);
    ioExpander.pinMode(BUTTON_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T0_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T1_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T2_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T3_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T4_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T5_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T6_PIN, INPUT_PULLUP);
    ioExpander.pinMode(SENSOR_T7_PIN, INPUT_PULLUP);

    mmuArm.detach();
    slicerArm.detach();
    Serial.println("READY");
}

void loop() {
    if (Serial.available() > 0) {
        processSerialCommand();
    }

    if (initializationComplete) {
        readAllSensors(true);
        readHubStatus();
        readButtonPress();
        unsigned long currentTime = millis();
        if (currentTime - lastHeartbeatTime > HEARTBEAT_INTERVAL_MS) {
            sendAlive();
            lastHeartbeatTime = currentTime;
        }
    } else {
        blinkBootLeds();
    }
}

