void MavLinkFtpClientImpl::runStateMachine() {
  pending_operation_ = true;
  attempt_count_ = 0;
  cumulative_delay_ = milliseconds::zero();
  message_counter_ = 0;
  progress_->cancel = false;
  progress_->error_code = 0;
  progress_->bytes_processed = 0;
  progress_->total_bytes = 0;
  progress_->complete = false;
  progress_->max_latency = 0;
  progress_->message_count = 0;

  int previous_count = 0;
  subscribe();
  executeNextStep();

  const int polling_interval = 30;  // milliseconds between status checks
  double throughput = 0;
  double accumulated_time = 0;

  while (pending_operation_) {
    std::this_thread::sleep_for(std::chrono::milliseconds(polling_interval));
    accumulated_time += polling_interval;
    int current_count = 0;

    {
      std::lock_guard<std::mutex> lock(operation_mutex_);
      current_count = message_counter_;
      if (message_counter_ > 0) {
        throughput = static_cast<double>(cumulative_delay_.count()) /
                     static_cast<double>(message_counter_);
        if (progress_ != nullptr) {
          progress_->average_rate = throughput;
        }
      }
    }

    if (current_count == previous_count) {
      if (accumulated_time > (MAXIMUM_RESPONSE_DELAY * RETRY_MULTIPLIER)) {
        Utils::log("FTP operation timeout: no response received, initiating retry\n",
                   Utils::kLogLevelWarn);
        initiateRetry();
        accumulated_time = 0;
      }
    } else {
      accumulated_time = 0;
    }
    previous_count = current_count;
  }
  pending_operation_ = false;
}

void MavLinkFtpClientImpl::executeNextStep() {
  switch (current_command_) {
    case FtpCommandList:
      listDirectory();
      break;
    case FtpCommandGet:
      readFile();
      break;
    case FtpCommandPut:
      writeFile();
      break;
    case FtpCommandRemove:
      deleteFile();
      break;
    case FtpCommandMkdir:
      createDirectory();
      break;
    case FtpCommandRmdir:
      removeDirectory();
      break;
    default:
      break;
  }
}

void MavLinkFtpClientImpl::deleteFile() {
  MavLinkFileTransferProtocol ftp_msg;
  FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp_msg.payload[0]);
  ftp_msg.target_component = getTargetComponentId();
  ftp_msg.target_system = getTargetSystemId();
  payload->command_code = kCmdDeleteFile;
  assignFilenameToPayload(payload, target_path_.c_str());
  sendMessage(ftp_msg);
  recordTransmission();
}

