bool MavLinkFtpClientImpl::openLocalSource() {
  source_file_ = fopen(local_target_.c_str(), "rb");
  if (source_file_ == nullptr) {
    if (progress_ != nullptr) {
      progress_->error_code = errno;
      progress_->message =
          Utils::stringf("Failed to open '%s' for reading, error=%d",
                         local_target_.c_str(), progress_->error_code);
    }
    return false;
  }
  fseek(source_file_, 0, SEEK_END);
  long file_pos = ftell(source_file_);
  fseek(source_file_, 0, SEEK_SET);
  expected_size_ = static_cast<uint64_t>(file_pos);
  if (progress_ != nullptr) {
    progress_->total_bytes = expected_size_;
  }
  return true;
}

bool MavLinkFtpClientImpl::prepareLocalDestination() {
  if (destination_file_ == nullptr) {
    auto full_path = FileSystem::getFullPath(local_target_);
    if (FileSystem::isDirectory(full_path)) {
      auto base_name = FileSystem::getFileName(normalize(target_path_));
      local_target_ = FileSystem::combine(full_path, base_name);
    } else {
      FileSystem::removeLeaf(full_path);
      if (!FileSystem::isDirectory(full_path)) {
        if (progress_ != nullptr) {
          progress_->error_code = errno;
          progress_->message = Utils::stringf(
              "Cannot create file: '%s' is not a valid directory", full_path.c_str());
        }
        return false;
      }
    }
    destination_file_ = fopen(local_target_.c_str(), "wb");
    if (destination_file_ == nullptr) {
      if (progress_ != nullptr) {
        progress_->error_code = errno;
        progress_->message =
            Utils::stringf("Failed to open '%s' for writing, error=%d",
                           local_target_.c_str(), errno);
      }
      return false;
    }
    expected_size_ = 0;
  }
  return true;
}

void MavLinkFtpClientImpl::readFile() {
  if (!remote_session_active_) {
    MavLinkFileTransferProtocol ftp_msg;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp_msg.payload[0]);
    ftp_msg.target_component = getTargetComponentId();
    ftp_msg.target_system = getTargetSystemId();
    payload->command_code = kCmdOpenFileRead;
    assignFilenameToPayload(payload, target_path_.c_str());
    sendMessage(ftp_msg);
    recordTransmission();
  } else {
    if (prepareLocalDestination()) {
      FtpPayload* payload =
          reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
      payload->command_code = kCmdReadDataBlock;
      payload->file_offset = total_bytes_read_;
      last_message_.target_component = getTargetComponentId();
      last_message_.target_system = getTargetSystemId();
      sendMessage(last_message_);
      recordTransmission();
      if (progress_ != nullptr) {
        progress_->bytes_processed = total_bytes_read_;
      }
    } else {
      pending_operation_ = false;
    }
  }
}

void MavLinkFtpClientImpl::writeFile() {
  if (!remote_session_active_) {
    MavLinkFileTransferProtocol ftp_msg;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp_msg.payload[0]);
    ftp_msg.target_component = getTargetComponentId();
    ftp_msg.target_system = getTargetSystemId();
    payload->command_code = kCmdOpenFileWrite;
    strcpy(reinterpret_cast<char*>(&payload->payload_data), target_path_.c_str());
    payload->data_length = static_cast<uint8_t>(target_path_.size());
    sendMessage(ftp_msg);
    recordTransmission();
  } else {
    MavLinkFileTransferProtocol& ftp_msg = last_message_;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp_msg.payload[0]);
    payload->command_code = kCmdWriteDataBlock;
    payload->sequence_num = sequence_counter_;
    fseek(source_file_, bytes_transferred_, SEEK_SET);
    uint8_t* buffer = &payload->payload_data;
    size_t chunk_size = fread(buffer, 1, 251 - 12, source_file_);
    if (progress_ != nullptr) {
      progress_->bytes_processed = bytes_transferred_;
    }
    if (chunk_size == 0) {
      transfer_success_ = true;
      resetSession();
      int err = ferror(source_file_);
      if (err != 0) {
        if (progress_ != nullptr) {
          progress_->error_code = err;
          progress_->message =
              Utils::stringf("Error reading local file, errno=%d", err);
        }
      }
      fclose(source_file_);
      source_file_ = nullptr;
      pending_operation_ = false;
    } else {
      payload->file_offset = bytes_transferred_;
      payload->data_length = static_cast<uint8_t>(chunk_size);
      ftp_msg.target_component = getTargetComponentId();
      ftp_msg.target_system = getTargetSystemId();
      sendMessage(ftp_msg);
      recordTransmission();
    }
  }
}

void MavLinkFtpClientImpl::cancel() {
  resetSession();
}

void MavLinkFtpClientImpl::close() {
  if (source_file_ != nullptr) {
    resetSession();
    fclose(source_file_);
    source_file_ = nullptr;
  }
  if (destination_file_ != nullptr) {
    resetSession();
    fclose(destination_file_);
    destination_file_ = nullptr;
  }
  if (subscription_ != 0) {
    getConnection()->unsubscribe(subscription_);
    subscription_ = 0;
  }
}

void MavLinkFtpClientImpl::resetSession() {
  MavLinkFileTransferProtocol ftp_msg;
  ftp_msg.target_component = getTargetComponentId();
  ftp_msg.target_system = getTargetSystemId();
  FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp_msg.payload[0]);
  payload->command_code = kCmdClearAllSessions;
  sendMessage(ftp_msg);
  recordTransmission();
}

void MavLinkFtpClientImpl::processListResponse() {
  FtpPayload* payload =
      reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
  if (payload->file_offset != entry_index_) {
    Utils::log(
        Utils::stringf("List response mismatch: expected index %d, got offset %d\n",
                       entry_index_, payload->file_offset),
        Utils::kLogLevelError);
    initiateRetry();
    return;
  }
  if (payload->file_offset == 0 && payload->data_length == 0) {
    resetSession();
    transfer_success_ = true;
    pending_operation_ = false;
    return;
  }
  uint8_t* data = &payload->payload_data;
  for (int pos = 0; pos < payload->data_length;) {
    uint8_t entry_type = data[pos];
    pos++;
    attempt_count_ = 0;
    entry_index_++;
    int name_len = 0;
    std::string name = reinterpret_cast<char*>(&data[pos]);
    if (entry_type == kEntryTypeSkip) {
      // Skip this entry silently
    } else if (entry_type == kEntryTypeFile) {
      size_t tab_pos = name.find_last_of('\t');
      MavLinkFileInfo info;
      info.is_directory = false;
      name_len = static_cast<int>(name.size());
      if (tab_pos > 0) {
        std::string size_str(name.begin() + tab_pos + 1, name.end());
        info.size = Utils::to_integer(size_str);
        name.erase(tab_pos);
      }
      info.name = name;
      if (entries_ != nullptr) {
        entries_->push_back(info);
      }
    } else if (entry_type == kEntryTypeDir) {
      MavLinkFileInfo info;
      info.is_directory = true;
      info.name = name;
      name_len = static_cast<int>(name.size());
      if (entries_ != nullptr) {
        entries_->push_back(info);
      }
    }
    pos += name_len + 1;
  }
  if (progress_ != nullptr) {
    progress_->bytes_processed = entry_index_;
  }
  executeNextStep();
}

void MavLinkFtpClientImpl::processReadResponse() {
  FtpPayload* payload =
      reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
  if (payload->request_opcode == kCmdOpenFileRead) {
    remote_session_active_ = true;
    total_bytes_read_ = 0;
    attempt_count_ = 0;
    sequence_counter_ = payload->sequence_num;
    uint32_t* size_field = reinterpret_cast<uint32_t*>(&payload->payload_data);
    expected_size_ = static_cast<uint64_t>(*size_field);
    if (progress_ != nullptr) {
      progress_->total_bytes = expected_size_;
    }
    executeNextStep();
  } else if (payload->request_opcode == kCmdReadDataBlock) {
    int packet_seq = static_cast<int>(payload->sequence_num);
    if (packet_seq != sequence_counter_ + 1) {
      Utils::log(
          Utils::stringf("Out-of-sequence packet %d, expected %d\n",
                         packet_seq, sequence_counter_ + 1),
          Utils::kLogLevelError);
      return;
    } else if (destination_file_ != nullptr) {
      sequence_counter_ = payload->sequence_num;
      fwrite(&payload->payload_data, payload->data_length, 1, destination_file_);
      total_bytes_read_ += payload->data_length;
      attempt_count_ = 0;
      executeNextStep();
    }
  }
}

void MavLinkFtpClientImpl::processWriteResponse() {
  FtpPayload* payload =
      reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
  if (payload->request_opcode == kCmdOpenFileWrite) {
    remote_session_active_ = true;
    bytes_transferred_ = 0;
    attempt_count_ = 0;
    sequence_counter_ = payload->sequence_num;
    executeNextStep();
  } else if (payload->request_opcode == kCmdWriteDataBlock) {
    int packet_seq = static_cast<int>(payload->sequence_num);
    if (packet_seq != sequence_counter_ + 1) {
      Utils::log(
          Utils::stringf("Write packet %d out of sequence, expected %d\n",
                         packet_seq, sequence_counter_ + 1),
          Utils::kLogLevelError);
      return;
    }
    uint32_t* written_field = reinterpret_cast<uint32_t*>(&payload->payload_data);
    bytes_transferred_ += static_cast<int>(*written_field);
    attempt_count_ = 0;
    sequence_counter_++;
    executeNextStep();
  }
}

void MavLinkFtpClientImpl::processDeleteResponse() {
  transfer_success_ = true;
  pending_operation_ = false;
}

void MavLinkFtpClientImpl::processRmdirResponse() {
  transfer_success_ = true;
  pending_operation_ = false;
}

void MavLinkFtpClientImpl::processMkdirResponse() {
  transfer_success_ = true;
  pending_operation_ = false;
}

void MavLinkFtpClientImpl::processResponse(const MavLinkMessage& msg) {
  if (msg.msgid ==
      static_cast<int>(
          MavLinkMessageIds::MAVLINK_MSG_ID_FILE_TRANSFER_PROTOCOL)) {
    last_message_.decode(msg);
    recordReception();
    FtpPayload* payload =
        reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
    if (payload->command_code == kRspFailure) {
      if (source_file_ != nullptr) {
        fclose(source_file_);
        source_file_ = nullptr;
      }
      if (destination_file_ != nullptr) {
        fclose(destination_file_);
        destination_file_ = nullptr;
      }
      int error_code = static_cast<int>(payload->payload_data);
      if (error_code == kFailEndOfFile) {
        transfer_success_ = true;
        error_code = 0;
      } else {
        transfer_success_ = false;
        if (progress_ != nullptr) {
          if (error_code == kFailSystemError) {
            const uint8_t* details = &(payload->payload_data);
            error_code = static_cast<int>(details[1]);
            progress_->error_code = error_code;
            progress_->message = Utils::stringf("FTP system error %d", error_code);
          } else {
            progress_->error_code = error_code;
            progress_->message = Utils::stringf("FTP error %d", error_code);
          }
        }
      }
      last_error_code_ = error_code;
      pending_operation_ = false;
      resetSession();
    } else if (payload->command_code == kRspSuccess) {
      if (progress_ != nullptr) {
        progress_->message_count++;
      }
      switch (payload->request_opcode) {
        case kCmdListDir:
          processListResponse();
          break;
        case kCmdOpenFileRead:
        case kCmdReadDataBlock:
          processReadResponse();
          break;
        case kCmdOpenFileWrite:
        case kCmdWriteDataBlock:
          processWriteResponse();
          break;
        case kCmdClearAllSessions:
          break;
        case kCmdDeleteFile:
          processDeleteResponse();
          break;
        case kCmdDeleteDirectory:
          processRmdirResponse();
          break;
        case kCmdMakeDirectory:
          processMkdirResponse();
          break;
        default:
          Utils::log(Utils::stringf("Unexpected ACK with req_opcode=%d\n",
                                    static_cast<int>(payload->request_opcode)),
                     Utils::kLogLevelWarn);
          break;
      }
    }
  }
}

void MavLinkFtpClientImpl::initiateRetry() {
  attempt_count_++;
  if (attempt_count_ < 10) {
    Utils::log(Utils::stringf("Retry attempt %d\n", attempt_count_), Utils::kLogLevelWarn);
    executeNextStep();
  } else {
    last_error_code_ = kFailMaxRetriesReached;
    transfer_success_ = false;
    pending_operation_ = false;
    resetSession();
  }
}

void MavLinkFtpClientImpl::recordTransmission() {
  std::lock_guard<std::mutex> lock(operation_mutex_);
  transmission_start_ = std::chrono::duration_cast<milliseconds>(
      std::chrono::system_clock::now().time_since_epoch());
}

void MavLinkFtpClientImpl::recordReception() {
  std::lock_guard<std::mutex> lock(operation_mutex_);
  message_counter_++;
  milliseconds receive_time = std::chrono::duration_cast<milliseconds>(
      std::chrono::system_clock::now().time_since_epoch());
  milliseconds latency = receive_time - transmission_start_;
  cumulative_delay_ += latency;
  if (progress_ != nullptr && latency.count() > progress_->max_latency) {
    progress_->max_latency = static_cast<double>(latency.count());
  }
}

std::string MavLinkFtpClientImpl::replaceCharacter(std::string input,
                                                   char search_char,
                                                   char replace_char) {
  size_t position = input.find_first_of(search_char, 0);
  while (position != std::string::npos) {
    input.replace(position, 1, 1, replace_char);
    position = input.find_first_of(search_char, 0);
  }
  return input;
}

std::string MavLinkFtpClientImpl::normalize(std::string path) {
  if (FileSystem::kPathSeparator == '\\') {
    return replaceCharacter(path, '/',
                            '\\');  // Normalize user input to match FileSystem behavior
  }
  return path;
}

std::string MavLinkFtpClientImpl::toPX4Path(std::string path) {
  if (FileSystem::kPathSeparator == '\\') {
    return replaceCharacter(path, '\\', '/');  // PX4 uses forward slashes
  }
  return path;
}

#include <gtest/gtest.h>
#include "kindr/common/gtest_eigen.hpp"
#include "kindr/phys_quant/PhysicalType.hpp"
#include "kindr/phys_quant/PhysicalQuantities.hpp"
#include "kindr/vectors/Vector.hpp"

struct DimensionalAnalysisTest : public ::testing::Test {
  using Acceleration = kindr::Acceleration3D;
  using Force = kindr::Force3D;
  using Mass = kindr::MassD;

  Acceleration accel;
  Force f;
  Mass m;

  DimensionalAnalysisTest() : accel(1., 2., 3.), f(5., 10., 15.), m(5.) {}
};

TEST_F(DimensionalAnalysisTest, scalarMultiplication) {
  EXPECT_EQ(accel * m, f);
  EXPECT_EQ(m * accel, f);
}

TEST_F(DimensionalAnalysisTest, scalarDivision) {
  EXPECT_EQ(f / m, accel);
}

TEST_F(DimensionalAnalysisTest, scalarOperations) {
  kindr::Acceleration<double, 1> scalarAccel(2.);
  kindr::Force<double, 1> scalarForce(10.);
  EXPECT_EQ(scalarAccel * m, scalarForce);
  EXPECT_EQ(m * scalarAccel, scalarForce);
}

TEST_F(DimensionalAnalysisTest, divisionOfScalars) {
  kindr::Acceleration<double, 1> scalarAccel(2.);
  kindr::Force<double, 1> scalarForce(10.);
  EXPECT_EQ(scalarForce / m, scalarAccel);
  EXPECT_EQ(scalarForce / scalarAccel, m);
}

TEST_F(DimensionalAnalysisTest, compoundAssignment) {
  const kindr::VectorTypeless<double, 1> unitless(5.);
  accel *= unitless;
  EXPECT_EQ(accel, kindr::Acceleration3D(5., 10., 15.));
  f /= unitless;
  EXPECT_EQ(f, kindr::Force3D(1., 2., 3.));
}

