WebsocketConnection::WebsocketConnection(HttpConnectionPtr conn)
    : connection_(conn)
{
}

void WebsocketConnection::set_message_handler(MessageHandler& handler)
{
    message_handler_ = handler;
}

bool WebsocketConnection::sendTextMessage(const std::string& payload)
{
    async_web_server_cpp::WebsocketMessage msg;
    msg.type = async_web_server_cpp::WebsocketMessage::type_text;
    msg.content = payload;
    return transmitMessage(msg);
}

bool WebsocketConnection::sendPingMessage(const std::string& payload)
{
    async_web_server_cpp::WebsocketMessage msg;
    msg.type = async_web_server_cpp::WebsocketMessage::type_ping;
    msg.content = payload;
    return transmitMessage(msg);
}

bool WebsocketConnection::sendMessage(const WebsocketMessage& msg)
{
    WebsocketFrame frame;
    if (frame.fromMessage(msg))
    {
        return sendFrame(frame);
    }
    return false;
}

bool WebsocketConnection::sendFrame(WebsocketFrame& frame)
{
    std::vector<unsigned char> buffer;
    if (frame.serialize(buffer))
    {
        connection_->write_and_clear(buffer);
        return true;
    }
    return false;
}

void WebsocketConnection::static_handle_read(
    WebsocketConnectionWeakPtr weak_ptr, const char* start, const char* finish)
{
    WebsocketConnectionPtr self = weak_ptr.lock();
    if (self)
        self->processIncomingData(start, finish);
}

void WebsocketConnection::handle_read(const char* begin, const char* end)
{
    boost::tribool frame_status;
    const char* next_position = begin;

    while (next_position < end)
    {
        boost::tie(frame_status, next_position) =
            frame_parser_.parse(current_frame_, next_position, end);

        if (frame_status)
        {
            frame_parser_.reset();
            boost::tribool message_status =
                frame_buffer_.consume(current_message_, current_frame_);

            if (message_status)
            {
                if (message_handler_)
                    message_handler_(current_message_);
            }
        }
        else if (!boost::logic::indeterminate(frame_status))
        {
            frame_parser_.reset();
            current_message_.type = WebsocketMessage::type_unknown;
        }
    }

    WebsocketConnectionWeakPtr this_weak(shared_from_this());
    connection_->async_read(boost::bind(
        &WebsocketConnection::static_handle_read, this_weak, boost::placeholders::_1, boost::placeholders::_2));
}
