class TestXmlParsing : public QObject {
    Q_OBJECT

private slots:
    void parseMinimalXmlStructure();
};

void TestXmlParsing::parseMinimalXmlStructure() {
    // Generate a compact XML snippet in a temporary file for parsing validation
    QTemporaryFile tempFile;
    tempFile.setAutoRemove(true);
    QVERIFY(tempFile.open());

    tempFile.write(R"(<?xml version="1.0" encoding="UTF-8"?>
<ReClass>
    <!--ReClassEx-->
    <Class Name="SampleStruct" Type="28" Comment="" Offset="0" strOffset="0" Code="">
        <Node Name="vptr" Type="9" Size="8" bHidden="false" Comment=""/>
        <Node Name="score" Type="13" Size="4" bHidden="false" Comment=""/>
        <Node Name="label" Type="18" Size="32" bHidden="false" Comment=""/>
        <Node Name="coords" Type="23" Size="12" bHidden="false" Comment=""/>
        <Node Name="nextPtr" Type="8" Size="8" bHidden="false" Comment="" Pointer="SampleStruct"/>
    </Class>
</ReClass>
)");

    tempFile.flush();

    QString errorMsg;
    NodeTree result = importReclassXml(tempFile.fileName(), &errorMsg);

    QVERIFY2(!result.nodes.isEmpty(), qPrintable(errorMsg));

    // Expected: 1 top-level struct + 5 member nodes = 6 total
    QCOMPARE(result.nodes.size(), 6);

    // Verify root struct node
    QCOMPARE(result.nodes[0].kind, NodeKind::Struct);
    QCOMPARE(result.nodes[0].name, QStringLiteral("SampleStruct"));

    // vptr = Int64
    QCOMPARE(result.nodes[1].kind, NodeKind::Int64);
    QCOMPARE(result.nodes[1].name, QStringLiteral("vptr"));
    QCOMPARE(result.nodes[1].offset, 0);

    // score = Float
    QCOMPARE(result.nodes[2].kind, NodeKind::Float);
    QCOMPARE(result.nodes[2].name, QStringLiteral("score"));
    QCOMPARE(result.nodes[2].offset, 8);

    // label = UTF8 with length 32
    QCOMPARE(result.nodes[3].kind, NodeKind::UTF8);
    QCOMPARE(result.nodes[3].strLen, 32);
    QCOMPARE(result.nodes[3].offset, 12);

    // coords = Vec3
    QCOMPARE(result.nodes[4].kind, NodeKind::Vec3);
    QCOMPARE(result.nodes[4].offset, 44);

    // nextPtr = Pointer64 referencing SampleStruct
    QCOMPARE(result.nodes[5].kind, NodeKind::Pointer64);
    QCOMPARE(result.nodes[5].name, QStringLiteral("nextPtr"));
    QVERIFY(result.nodes[5].refId != 0);
    QCOMPARE(result.nodes[5].refId, result.nodes[0].id); // Should point back to SampleStruct
}

QTEST_MAIN(TestXmlParsing)
