using namespace std;

vector<long long> arr, blockSum, lazyVal;
struct SqrtDecomposition {
  const int blockSize, numBlocks;
  vector<int> leftBound, rightBound;
  vector<bool> needsRebuild;
  vector<vector<pair<int,int>>> uniqueValues;

  explicit SqrtDecomposition(const int size)
      : blockSize((int)max(1.0, floor(sqrt((double)size)))),
        numBlocks((size + blockSize - 1) / blockSize) {
    leftBound.resize(numBlocks);
    rightBound.resize(numBlocks);
    needsRebuild.assign(numBlocks, false);
    uniqueValues.resize(numBlocks);

    for (int i = 0; i < numBlocks; ++i) {
      leftBound[i] = blockSize * i;
      rightBound[i] = (i + 1 == numBlocks ? size : blockSize * (i + 1));
      uniqueValues[i].reserve((rightBound[i] - leftBound[i]) * 2);
    }
  }

  void rebuildBlock(int blockIdx) {
    vector<pair<int,int>> temp;
    temp.reserve(rightBound[blockIdx] - leftBound[blockIdx]);

    for (int i = leftBound[blockIdx]; i < rightBound[blockIdx]; ++i) {
      temp.emplace_back((int)arr[i], i);
    }

    sort(temp.begin(), temp.end(), [](const pair<int,int>& x, const pair<int,int>& y){
      if (x.first != y.first) return x.first < y.first;
      return x.second < y.second;
    });

    auto &uniqueList = uniqueValues[blockIdx];
    uniqueList.clear();
    uniqueList.reserve(temp.size());

    int lastKey = INT_MIN;
    for (auto &item : temp) {
      if (item.first != lastKey) {
        lastKey = item.first;
        uniqueList.emplace_back(item.first, item.second);
      }
    }
  }

  void buildAllMaps() {
    for (int b = 0; b < numBlocks; ++b) {
      rebuildBlock(b);
    }
  }

  inline int getActualValue(int index) const {
    int blockIndex = index / blockSize;
    return (int)(arr[index] + lazyVal[blockIndex]);
  }

  int findFirstEqual(int limitIndex, int targetValue) const {
    int currentBlock = limitIndex / blockSize;

    for (int b = 0; b < currentBlock; ++b) {
      int adjustedTarget = targetValue - (int)lazyVal[b];
      const auto& vec = uniqueValues[b];
      auto it = lower_bound(vec.begin(), vec.end(), adjustedTarget,
        [](const pair<int,int>& p, int val){ return p.first < val; });

      if (it != vec.end() && it->first == adjustedTarget) {
        return it->second;
      }
    }

    int adjustedTarget = (int)lazyVal[currentBlock];
    for (int i = leftBound[currentBlock]; i <= limitIndex; ++i) {
      if ((int)(arr[i] + adjustedTarget) == targetValue) {
        return i;
      }
    }
    return -1;
  }

  void rangeAddAndRebuild(int left, int right, int value) {
    if (right <= left) return;

    const int leftBlock = left / blockSize, rightBlock = (right - 1) / blockSize;
    updateRange(left, right, value);

    if (leftBlock == rightBlock) {
      rebuildBlock(leftBlock);
    } else {
      if (left != leftBound[leftBlock]) rebuildBlock(leftBlock);
      if (right != rightBound[rightBlock]) rebuildBlock(rightBlock);
    }
  }

  template <typename T>
  void updateSingleElement(const int idx, const T value) {
    arr[idx] += value;
    blockSum[idx / blockSize] += value;
  }

  template <typename T>
  void updateEntireBlock(const int blockIdx, const T value) {
    lazyVal[blockIdx] += value;
    needsRebuild[blockIdx] = true;
  }

  template <typename T>
  void updateRange(const int l, const int r, const T value) {
    if (r <= l) return;

    const int leftBlock = l / blockSize, rightBlock = (r - 1) / blockSize;

    if (leftBlock < rightBlock) {
      if (l == leftBound[leftBlock]) {
        updateEntireBlock(leftBlock, value);
      } else {
        for (int i = l; i < rightBound[leftBlock]; ++i) {
          updateSingleElement(i, value);
        }
      }

      for (int i = leftBlock + 1; i < rightBlock; ++i) {
        updateEntireBlock(i, value);
      }

      if (r == rightBound[rightBlock]) {
        updateEntireBlock(rightBlock, value);
      } else {
        for (int i = leftBound[rightBlock]; i < r; ++i) {
          updateSingleElement(i, value);
        }
      }
    } else {
      for (int i = l; i < r; ++i) {
        updateSingleElement(i, value);
      }
    }
  }

  template <typename T>
  void querySingleElement(const int idx, T* accumulator) {
    const int blockIndex = idx / blockSize;

    if (needsRebuild[blockIndex]) {
      for (int i = leftBound[blockIndex]; i < rightBound[blockIndex]; ++i) {
        updateSingleElement(i, lazyVal[blockIndex]);
      }
      lazyVal[blockIndex] = 0;
      needsRebuild[blockIndex] = false;
      const_cast<SqrtDecomposition*>(this)->rebuildBlock(blockIndex);
    }

    *accumulator += arr[idx];
  }

  template <typename T>
  void queryEntireBlock(const int blockIndex, T* accumulator) {
    *accumulator += blockSum[blockIndex] + lazyVal[blockIndex] * (rightBound[blockIndex] - leftBound[blockIndex]);
  }

  template <typename T>
  T queryRange(const int l, const int r, const T identity) {
    const int leftBlock = l / blockSize, rightBlock = (r - 1) / blockSize;
    T result = identity;

    if (leftBlock < rightBlock) {
      if (l == leftBound[leftBlock]) {
        queryEntireBlock(leftBlock, &result);
      } else {
        for (int i = l; i < rightBound[leftBlock]; ++i) {
          querySingleElement(i, &result);
        }
      }

      for (int i = leftBlock + 1; i < rightBlock; ++i) {
        queryEntireBlock(i, &result);
      }

      if (r == rightBound[rightBlock]) {
        queryEntireBlock(rightBlock, &result);
      } else {
        for (int i = leftBound[rightBlock]; i < r; ++i) {
          querySingleElement(i, &result);
        }
      }
    } else {
      for (int i = l; i < r; ++i) {
        querySingleElement(i, &result);
      }
    }

    return result;
  }
};

class Solution {
public:
    int longestBalancedSubarray(vector<int>& inputArray) 
    {
        int n = inputArray.size();
        int N = n + 1;

        SqrtDecomposition sd(N);
        arr.assign(N, 0);
        blockSum.assign(sd.numBlocks, 0);
        lazyVal.assign(sd.numBlocks, 0);

        sd.buildAllMaps();

        int MAX_VALUE = 100000;
        vector<int> lastOccurrence(MAX_VALUE + 1, -1);
        int maxLength = 0;

        for (int right = 0; right < n; ++right) {
            int value = inputArray[right];
            int previous = lastOccurrence[value];
            int delta = (value & 1) ? +1 : -1;

            sd.rangeAddAndRebuild(previous + 1, right + 1, delta);
            lastOccurrence[value] = right;

            int currentSum = sd.getActualValue(right + 1);
            int leftIndex = sd.findFirstEqual(right, currentSum);

            if (leftIndex != -1) {
                maxLength = max(maxLength, right - leftIndex + 1);
            }
        }

        return maxLength;
    }
};

#define INVALID_BASE64_BYTE 64
#include "llvm/Support/Base64.h"

static char decodeBase64Byte(uint8_t Ch) {
  constexpr char Invalid = INVALID_BASE64_BYTE;
  static const char DecodingTable[] = {
      Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, // ........
      Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, // ........
      Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, // ........
      Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, // ........
      Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, Invalid, // ........
      Invalid, Invalid, Invalid, 62,  Invalid, Invalid, Invalid, 63,  // ...+.../
      52,  53,  54,  55,  56,  57,  58,  59,  // 01234567
      60,  61,  Invalid, Invalid, Invalid, 0,   Invalid, Invalid, // 89...=..
      Invalid, 0,   1,   2,   3,   4,   5,   6,   // .ABCDEFG
      7,   8,   9,   10,  11,  12,  13,  14,  // HIJKLMNO
      15,  16,  17,  18,  19,  20,  21,  22,  // PQRSTUVW
      23,  24,  25,  Invalid, Invalid, Invalid, Invalid, Invalid, // XYZ.....
      Invalid, 26,  27,  28,  29,  30,  31,  32,  // .abcdefg
      33,  34,  35,  36,  37,  38,  39,  40,  // hijklmno
      41,  42,  43,  44,  45,  46,  47,  48,  // pqrstuvw
      49,  50,  51                            // xyz.....
  };
  if (Ch >= sizeof(DecodingTable))
    return Invalid;
  return DecodingTable[Ch];
}

llvm::Error llvm::decodeBase64(llvm::StringRef Input,
                               std::vector<char> &Result) {
  constexpr char Base64InvalidByte = INVALID_BASE64_BYTE;
  Result.clear();
  const uint64_t Length = Input.size();
  if (Length == 0)
    return Error::success();
  if ((Length % 4) != 0)
    return createStringError(std::errc::illegal_byte_sequence,
                             "Base64 encoded strings must be a multiple of 4 "
                             "bytes in length");
  const uint64_t FirstValidEqualPosition = Length - 2;
  char Hex64Bytes[4];
  for (uint64_t Position = 0; Position < Length; Position += 4) {
    for (uint64_t Offset = 0; Offset < 4; ++Offset) {
      const uint64_t Index = Position + Offset;
      const char Byte = Input[Index];
      const char DecodedValue = decodeBase64Byte(Byte);
      bool IsInvalid = DecodedValue == Base64InvalidByte;
      if (!IsInvalid && Byte == '=') {
        if (Index < FirstValidEqualPosition) {
          IsInvalid = true;
        } else if (Index == FirstValidEqualPosition && Input[Index + 1] != '=') {
          IsInvalid = true;
        }
      }
      if (IsInvalid)
        return createStringError(
            std::errc::illegal_byte_sequence,
            "Invalid Base64 character %#2.2x at index %" PRIu64, Byte, Index);
      Hex64Bytes[Offset] = DecodedValue;
    }
    Result.push_back((Hex64Bytes[0] << 2) + ((Hex64Bytes[1] >> 4) & 0x03));
    Result.push_back((Hex64Bytes[1] << 4) + ((Hex64Bytes[2] >> 2) & 0x0f));
    Result.push_back((Hex64Bytes[2] << 6) + (Hex64Bytes[3] & 0x3f));
  }
  if (Input.back() == '=') {
    Result.pop_back();
    if (Input[Length - 2] == '=')
      Result.pop_back();
  }
  return Error::success();
}

