// Modified version of AsyncResultProviderMessageConverter with renamed variables and restructured logic
AsyncResultProviderMessageConverter::AsyncResultProviderMessageConverter(
    const TAsyncResult<Message>& ar_msg)
    : TRefCounted(),
      piasyncresultprovider_(reinterpret_cast<TAsyncResultProvider<Message>*>(
          AsyncResultManager::GetPSelfDelete(ar_msg))) {
  // Retain reference to the wrapped async result provider
  piasyncresultprovider_->AddRef();
}

AsyncResultProviderMessageConverter::AsyncResultProviderMessageConverter(
    TAsyncResult<Message>&& ar_msg)
    : TRefCounted(),
      piasyncresultprovider_(reinterpret_cast<TAsyncResultProvider<Message>*>(
          AsyncResultManager::GetPSelfDelete(ar_msg))) {
  // Transfer ownership of the wrapped async result provider
  AsyncResultManager::GetPSelfDelete(ar_msg) = nullptr;
}

AsyncResultProviderMessageConverter::~AsyncResultProviderMessageConverter() {
  if (piasyncresultprovider_ != nullptr) piasyncresultprovider_->Release();
}

void AsyncResultProviderMessageConverter::Cancel(void) {
  if (piasyncresultprovider_ != nullptr) piasyncresultprovider_->Cancel();
}

bool AsyncResultProviderMessageConverter::FIsDone(void) const {
  if (piasyncresultprovider_ == nullptr) return (false);
  return (piasyncresultprovider_->FIsDone());
}

Status AsyncResultProviderMessageConverter::Wait(void) {
  Status status_result;
  if (piasyncresultprovider_ == nullptr) return (Status::Failed);

  status_result = piasyncresultprovider_->Wait();

  if (status_result == Status::OK) {
    auto& message_data = piasyncresultprovider_->GetResult();
    ResponseMessage rm_response;
    rm_response.Deserialize(message_data);

    if (rm_response.GetErrorCode() != 0) {
      auto json_output = rm_response.GetResult();
      json json_payload = json_output["message"];

      if (json_payload.is_string())
        client::log.InfoF("Error from server: %s",
                          static_cast<std::string>(json_payload).c_str());

      status_result = Status::RejectedByServer;
    }
    return (status_result);
  }

  return (status_result);
}

void TAsyncResultProvider<Message>::InvokeCallback(const Message& msg_data) {
  if (fn_response_callback != nullptr) {
    ResponseMessage rm_response;
    // Deserialize server message
    try {
      rm_response.Deserialize(msg_data);
    } catch (std::exception e) {
      log.ErrorF(
          "Caught exception deserializing server's reply message to "
          "ResponseMessage: %s",
          e.what());
    }
    // Invoke async response callback
    try {
      fn_response_callback(rm_response.GetErrorCode(), 
                           rm_response.GetResult().dump());
    } catch (std::exception e) {
      log.ErrorF(
          "Caught exception invoking asynchronous response message callback: "
          "%s",
          e.what());
    }
  }
}

