bool extractVidPid(std::wstring devId, int* vendorId, int* productId) {
  const wchar_t* start = devId.c_str();
  const wchar_t* limit = start + devId.size();

  // Extract the VID value
  const wchar_t* vidPos = wcsstr(start, L"VID_");
  if (vidPos == nullptr) {
    return false;
  }

  wchar_t* nextChar = nullptr;
  long tempValue = wcstol(vidPos + 4, &nextChar, 16);
  *vendorId = static_cast<int>(tempValue);

  // Now extract the PID value
  const wchar_t* pidPos = wcsstr(nextChar, L"PID_");
  if (pidPos == nullptr) {
    return false;
  }

  nextChar = nullptr;
  tempValue = wcstol(pidPos + 4, &nextChar, 16);
  *productId = static_cast<int>(tempValue);

  return true;
}

void extractDisplayName(std::wstring displayNameText, SerialPortInfo* portInfo) {
  portInfo->displayName = displayNameText;
  const wchar_t* textPtr = displayNameText.c_str();

  // Look for opening parenthesis to locate port name
  const wchar_t* openParen = wcsrchr(textPtr, L'(');
  if (openParen == nullptr) {
    return;
  }

  openParen++;  // Move past '('
  const wchar_t* closeParen = wcschr(openParen, L')');
  if (closeParen != nullptr) {
    portInfo->portName = std::wstring(openParen, closeParen - openParen);
  }
}

std::vector<SerialPortInfo> EnumeratePorts() {
  std::vector<SerialPortInfo> portList;
  ULONG bufferSize;

  CONFIGRET result = CM_Get_Device_Interface_List_SizeW(
      &bufferSize, 
      const_cast<GUID*>(&GUID_DEVINTERFACE_COMPORT),
      nullptr, 
      CM_GET_DEVICE_INTERFACE_LIST_PRESENT);

  if ((result != CR_SUCCESS) || (bufferSize == 0)) {
    return portList;
  }

  std::vector<WCHAR> buffer(bufferSize);
  result = CM_Get_Device_Interface_ListW(
      const_cast<GUID*>(&GUID_DEVINTERFACE_COMPORT),
      nullptr, 
      buffer.data(), 
      static_cast<ULONG>(buffer.size()),
      CM_GET_DEVICE_INTERFACE_LIST_PRESENT);

  if ((result != CR_SUCCESS) || (bufferSize == 0)) {
    return portList;
  }

  if (!buffer[0]) {
    return portList;
  }

  buffer.back() = UNICODE_NULL;

  ULONG counter = 0;
  for (PCWSTR interfacePath = buffer.data(); *interfacePath;
       interfacePath += wcslen(interfacePath) + 1) {

    const DEVPROPKEY propertyKey = {
        PKEY_DeviceInterface_Serial_PortName.fmtid,
        PKEY_DeviceInterface_Serial_PortName.pid
    };

    DEVPROPTYPE type;
    WCHAR comPortName[512];
    ULONG requiredSize = sizeof(comPortName);

    result = CM_Get_Device_Interface_PropertyW(
        interfacePath, 
        &propertyKey, 
        &type,
        reinterpret_cast<BYTE*>(comPortName), 
        &requiredSize,
        0);

    SerialPortInfo entry;
    entry.pid = 0;
    entry.vid = 0;
    entry.portName = interfacePath;

    int foundVid = 0, foundPid = 0;
    if (extractVidPid(entry.portName, &foundVid, &foundPid)) {
      entry.pid = foundPid;
      entry.vid = foundVid;
    }

    printf("Detected: %S\n", interfacePath);

    if ((result == CR_SUCCESS) && (type == DEVPROP_TYPE_STRING)) {
      entry.displayName = comPortName;
    }

    portList.push_back(entry);
    ++counter;
  }

  return portList;
}

std::vector<SerialPortInfo> MavLinkConnection::findSerialPorts(int vendorId,
                                                               int productId) {
  std::vector<SerialPortInfo> filteredList;
  std::vector<SerialPortInfo> allPorts = EnumeratePorts();

  for (auto iter = allPorts.begin(), last = allPorts.end(); iter != last; ++iter) {
    SerialPortInfo& current = *iter;
    if ((vendorId == 0 && productId == 0) || 
        (current.vid == vendorId && current.pid == productId)) {
      filteredList.push_back(current);
    }
  }

  return filteredList;
}

