FontModule::Symbol LargeFont::getChar(uint32_t codePoint) const
{
    if (codePoint >= 0x20 && codePoint <= 0x7F && codePoint < ascii.size() + 0x20)
    {
        return ascii[codePoint - 0x20];
    }
    else if (codePoint >= 0x80 && codePoint <= 0x10FFFF)
    {
        for (const SymbolExtended &extGlyph : unicode)
        {
            if (extGlyph.hex == codePoint)
            {
                return extGlyph.symbol;
            }
        }
    }
    return {};
}

#include <iostream>
#include <vector>
#include <unordered_set>
#include <stdexcept>

// Entry point for learning process (modified version)
int main() {
  try {
    bool use_horn_preprocessing = true; // renamed from do_horndini_prephase

    if (use_horn_preprocessing) {
      //
      // Duplicate data points and prepare pointers
      //
      std::vector<datapoint<bool>> sample_copy;
      sample_copy.reserve(sample.size());
      for (size_t idx = 0; idx < sample.size(); ++idx) {
        sample_copy.push_back(sample[idx]);
      }

      std::vector<datapoint<bool>*> ptr_list;
      ptr_list.reserve(sample_copy.size());
      for (size_t idx = 0; idx < sample_copy.size(); ++idx) {
        ptr_list.push_back(&sample_copy[idx]);
      }

      //
      // Build Horn constraints from indexes
      //
      auto horn_rules =
          io_handler::convert_to_horn_constraints(index_map, sample_copy);

      //
      // Execute Horndini pre-phase
      //
      try {
        auto horn_tree = horndini_initial_step(config, sample_copy,
                                               index_map, interval_bounds);
        //
        // Validate consistency and output if successful
        //
        bool is_valid = validator<job_scheduler>::check_consistency(
            horn_tree, ptr_list, horn_rules);
        if (is_valid) {
          io_handler::save_json_output(output_prefix + ".json", horn_tree,
                                       config);
          if (limit_handler.has_limit()) {
            limit_handler.save_limit_file(output_prefix + ".limit", limit_handler);
          }
          return EXIT_SUCCESS;
        }
      }
      catch (const no_conjunction_found_exception &err) {
        // Continue to next phase: decision tree learning
      }
    }

    /***********************************************************************************
     *
     * Proceed to decision tree construction
     *
     ***********************************************************************************/
    //
    // Load iteration count and bounds from files when applicable
    //
    if (limit_handler.has_limit()) {
      auto iter_num = io_handler::load_status_file(output_prefix + ".status");
      if (iter_num > 1) {
        limit_handler.set_limit(io_handler::load_status_file(output_prefix + ".limit"));
      }
    }

    //
    // Iterate over increasing bounds until convergence or failure
    //
    bool finished = false;
    while (!finished) {
      finished = !limit_handler.has_limit();

      try {
        //
        // Prepare working copies of data points and their references
        //
        std::vector<datapoint<bool>> temp_samples;
        temp_samples.reserve(sample.size());
        for (size_t i = 0; i < sample.size(); ++i) {
          temp_samples.push_back(sample[i]);
        }

        std::vector<datapoint<bool>*> ref_list;
        ref_list.reserve(temp_samples.size());
        for (size_t i = 0; i < temp_samples.size(); ++i) {
          ref_list.push_back(&temp_samples[i]);
        }

        //
        // Construct base Horn rules
        //
        auto horn_rules = io_handler::convert_to_horn_constraints(index_map, temp_samples);

        //
        // Add indistinguishability constraints if bounds are active
        //
        if (limit_handler.has_limit()) {
          std::vector<horn_constraint<bool>> equivalence_constraints;
          equivalence_constraints = io_handler::extract_equivalence_constraints(
              temp_samples, limit_handler.get_limit());
          horn_rules.insert(horn_rules.end(),
                            std::make_move_iterator(equivalence_constraints.begin()),
                            std::make_move_iterator(equivalence_constraints.end()));
        }

        //
        // Initialize Horn solver and classify initial points
        //
        horn_solver<bool> engine;
        std::unordered_set<datapoint<bool>*> pos_refs;
        std::unordered_set<datapoint<bool>*> neg_refs;

        bool success = engine.solve(ref_list, horn_rules, pos_refs, neg_refs);
        if (success) {
          for (auto dp : pos_refs) {
            dp->_is_classified = true;
            dp->_classification = true;
          }
          for (auto dp : neg_refs) {
            dp->_is_classified = true;
            dp->_classification = false;
          }
        } else {
          throw data_error("Inconsistent Horn clauses — no valid decision tree possible");
        }

        //
        // Configure learner heuristics
        //
        auto node_policy = NodeSelectionStrategy::BREADTH_FIRST;
        auto entropy_mode = EntropyCalculation::PENALIZED;
        auto conj_mode = ConjunctionHandling::NEUTRAL;
        job_scheduler scheduler(
            limit_handler.has_limit()
                ? complex_job_manager(ref_list, horn_rules, engine,
                                      limit_handler.get_limit(), node_policy,
                                      entropy_mode, conj_mode)
                : complex_job_manager(ref_list, horn_rules, engine,
                                      node_policy, entropy_mode, conj_mode));

        learner<complex_job_manager> trainer(scheduler);
        auto final_tree =
            trainer.train(config, ref_list, horn_rules);

        //
        // Verify correctness via assertion
        //
        assert(trainer.is_consistent(final_tree, ref_list, horn_rules));

        //
        // Save results
        //
        io_handler::save_json_output(output_prefix + ".json", final_tree, config);
        if (limit_handler.has_limit()) {
          limit_handler.save_limit_file(output_prefix + ".limit", limit_handler);
        }
        finished = true;

      } catch (const data_error &e) {
        if (limit_handler.has_limit()) {
          limit_handler.enlarge_limit();
        } else {
          throw;
        }
      } catch (const partition_impossible_error &e) {
        if (limit_handler.has_limit()) {
          limit_handler.enlarge_limit();
        } else {
          throw;
        }
      }
    }

    return EXIT_SUCCESS;
  }
  catch (const std::exception &e) {
    std::cerr << e.what() << std::endl;
    return EXIT_FAILURE;
  } catch (...) {
    std::cerr << "Learning process terminated unexpectedly" << std::endl;
    return EXIT_FAILURE;
  }
}

