void CVersion::_PopulateOSInfo()
{
    HMODULE hModule = GetModuleHandleW(L"ntdll.dll");
    GetOsVersion_t getOsVersionFunc = (GetOsVersion_t)GetProcAddress(hModule, "RtlGetVersion");
    if (getOsVersionFunc)
    {
        getOsVersionFunc(&m_versionInfo);
    }
