{
    ZeroMemory(&m_versionInfo, sizeof(RTL_OSVERSIONINFOEXW));
    m_versionInfo.dwOSVersionInfoSize = sizeof(RTL_OSVERSIONINFOEXW);
}

ULONG CVersion::BuildNumber()
{
    if (!m_versionInfo.dwBuildNumber)
        _PopulateOSInfo();
    return m_versionInfo.dwBuildNumber;
}

