{
    if (!m_versionInfo.dwMajorVersion)
        _PopulateOSInfo();
    return m_versionInfo.dwMajorVersion;
}

ULONG CVersion::MinorVersion()
{
    if (!m_versionInfo.dwMinorVersion)
        _PopulateOSInfo();
    return m_versionInfo.dwMinorVersion;
}

