namespace Slic3r
{
    // Global handles and function pointers for WinRT runtime
    HMODULE s_hRuntimeObjectLibrary = nullptr;
    FunctionRoInitialize s_RoInitialize = nullptr;
    FunctionRoUninitialize s_RoUninitialize = nullptr;
    FunctionRoActivateInstance s_RoActivateInstance = nullptr;
    FunctionRoGetActivationFactory s_RoGetActivationFactory = nullptr;
    FunctionWindowsCreateString s_WindowsCreateString = nullptr;
    FunctionWindowsDelteString s_WindowsDeleteString = nullptr;

    bool winrt_load_runtime_object_library()
    {
        if (s_hRuntimeObjectLibrary == nullptr)
            s_hRuntimeObjectLibrary = LoadLibrary(L"ComBase.dll");

        if (s_hRuntimeObjectLibrary != nullptr)
        {
            s_RoInitialize = (FunctionRoInitialize)GetProcAddress(s_hRuntimeObjectLibrary, "RoInitialize");
            s_RoUninitialize = (FunctionRoUninitialize)GetProcAddress(s_hRuntimeObjectLibrary, "RoUninitialize");
            s_RoActivateInstance = (FunctionRoActivateInstance)GetProcAddress(s_hRuntimeObjectLibrary, "RoActivateInstance");
            s_RoGetActivationFactory = (FunctionRoGetActivationFactory)GetProcAddress(s_hRuntimeObjectLibrary, "RoGetActivationFactory");
            s_WindowsCreateString = (FunctionWindowsCreateString)GetProcAddress(s_hRuntimeObjectLibrary, "WindowsCreateString");
            s_WindowsDeleteString = (FunctionWindowsDelteString)GetProcAddress(s_hRuntimeObjectLibrary, "WindowsDeleteString");
        }

        return s_RoInitialize && s_RoUninitialize && s_RoActivateInstance && 
               s_WindowsCreateString && s_WindowsDeleteString;
    }

    static HRESULT winrt_activate_instance(const std::wstring &className, IInspectable **pinst)
    {
        HSTRING hClassName;
        HRESULT hr = (*s_WindowsCreateString)(className.c_str(), className.size(), &hClassName);
        if (S_OK != hr)
            return hr;

        hr = (*s_RoActivateInstance)(hClassName, pinst);
        (*s_WindowsDeleteString)(hClassName);
        return hr;
    }

    template<typename TYPE>
    static HRESULT winrt_activate_instance(const std::wstring &className, TYPE **pinst)
    {
        IInspectable *inspectable = nullptr;
        HRESULT hr = winrt_activate_instance(className, &inspectable);
        if (S_OK != hr)
            return hr;

        hr = inspectable->QueryInterface(__uuidof(TYPE), (void **)pinst);
        inspectable->Release();
        return hr;
    }

    static HRESULT winrt_get_activation_factory(const std::wstring &className, REFIID iid, void **pinst)
    {
        HSTRING hClassName;
        HRESULT hr = (*s_WindowsCreateString)(className.c_str(), className.size(), &hClassName);
        if (S_OK != hr)
            return hr;

        hr = (*s_RoGetActivationFactory)(hClassName, iid, pinst);
        (*s_WindowsDeleteString)(hClassName);
        return hr;
    }

    template<typename TYPE>
    static HRESULT winrt_get_activation_factory(const std::wstring &className, TYPE **pinst)
    {
        return winrt_get_activation_factory(className, __uuidof(TYPE), reinterpret_cast<void **>(pinst));
    }

    // To be called often to test whether to cancel the operation.
    typedef std::function<void()> ThrowOnCancelFn;

    template<typename T>
    static AsyncStatus winrt_async_await(const Microsoft::WRL::ComPtr<T> &asyncAction, ThrowOnCancelFn throw_on_cancel,
                                         int blocking_tick_ms = 100)
    {
        Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncInfo> asyncInfo;
        asyncAction.As(&asyncInfo);
        AsyncStatus status;

        for (;;)
        {
            asyncInfo->get_Status(&status);
            if (status != AsyncStatus::Started)
                return status;

            throw_on_cancel();
            ::Sleep(blocking_tick_ms);
        }
    }

    static HRESULT winrt_open_file_stream(const std::wstring &path, ABI::Windows::Storage::FileAccessMode mode,
                                          ABI::Windows::Storage::Streams::IRandomAccessStream **fileStream,
                                          ThrowOnCancelFn throw_on_cancel)
    {
        // Get the file factory
        Microsoft::WRL::ComPtr<ABI::Windows::Storage::IStorageFileStatics> fileFactory;
        HRESULT hr = winrt_get_activation_factory(L"Windows.Storage.StorageFile", fileFactory.GetAddressOf());
        if (FAILED(hr))
            return hr;

        // Open the file asynchronously
        HSTRING hstr_path;
        hr = (*s_WindowsCreateString)(path.c_str(), path.size(), &hstr_path);
        if (FAILED(hr))
            return hr;

        Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Storage::StorageFile *>>
            fileOpenAsync;
        hr = fileFactory->GetFileFromPathAsync(hstr_path, fileOpenAsync.GetAddressOf());
        if (FAILED(hr))
            return hr;

        (*s_WindowsDeleteString)(hstr_path);

        // Wait until the file gets open, get the actual file
        AsyncStatus status = winrt_async_await(fileOpenAsync, throw_on_cancel);
        Microsoft::WRL::ComPtr<ABI::Windows::Storage::IStorageFile> storageFile;
        if (status == AsyncStatus::Completed)
        {
            hr = fileOpenAsync->GetResults(storageFile.GetAddressOf());
        }
        else
        {
            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncInfo> asyncInfo;
            hr = fileOpenAsync.As(&asyncInfo);
            if (FAILED(hr))
                return hr;
            HRESULT err;
            hr = asyncInfo->get_ErrorCode(&err);
            return FAILED(hr) ? hr : err;
        }

        Microsoft::WRL::ComPtr<
            ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Storage::Streams::IRandomAccessStream *>>
            fileStreamAsync;
        hr = storageFile->OpenAsync(mode, fileStreamAsync.GetAddressOf());
        if (FAILED(hr))
            return hr;

        status = winrt_async_await(fileStreamAsync, throw_on_cancel);
        if (status == AsyncStatus::Completed)
        {
            hr = fileStreamAsync->GetResults(fileStream);
        }
        else
        {
            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncInfo> asyncInfo;
            hr = fileStreamAsync.As(&asyncInfo);
            if (FAILED(hr))
                return hr;
            HRESULT err;
            hr = asyncInfo->get_ErrorCode(&err);
            if (!FAILED(hr))
                hr = err;
        }
        return hr;
    }

    bool is_windows10()
    {
        HKEY hKey;
        LONG lRes = RegOpenKeyExW(HKEY_LOCAL_MACHINE, L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion", 0, KEY_READ,
                                  &hKey);
        if (lRes == ERROR_SUCCESS)
        {
            WCHAR szBuffer[512];
            DWORD dwBufferSize = sizeof(szBuffer);
            lRes = RegQueryValueExW(hKey, L"ProductName", 0, nullptr, (LPBYTE)szBuffer, &dwBufferSize);
            if (lRes == ERROR_SUCCESS)
                return wcsncmp(szBuffer, L"Windows 10", 10) == 0;
            RegCloseKey(hKey);
        }
        return false;
    }

    // Progress function, to be called regularly to update the progress.
    typedef std::function<void(const char * /* message */, unsigned /* progress */)> ProgressFn;

    void fix_model_by_win10_sdk(const std::string &path_src, const std::string &path_dst, ProgressFn on_progress,
                                ThrowOnCancelFn throw_on_cancel)
    {
        if (!is_windows10())
            throw Slic3r::RuntimeError("fix_model_by_win10_sdk called on non Windows 10 system");

        if (!winrt_load_runtime_object_library())
            throw Slic3r::RuntimeError("Failed to initialize the WinRT library.");

        HRESULT hr = (*s_RoInitialize)(RO_INIT_MULTITHREADED);
        {
            on_progress(L("Exporting source model"), 20);
            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IRandomAccessStream> fileStream;
            hr = winrt_open_file_stream(boost::nowide::widen(path_src),
                                        ABI::Windows::Storage::FileAccessMode::FileAccessMode_Read,
                                        fileStream.GetAddressOf(), throw_on_cancel);

            Microsoft::WRL::ComPtr<ABI::Windows::Graphics::Printing3D::IPrinting3D3MFPackage> printing3d3mfpackage;
            hr = winrt_activate_instance(L"Windows.Graphics.Printing3D.Printing3D3MFPackage",
                                         printing3d3mfpackage.GetAddressOf());

            Microsoft::WRL::ComPtr<
                ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Graphics::Printing3D::Printing3DModel *>>
                modelAsync;
            hr = printing3d3mfpackage->LoadModelFromPackageAsync(fileStream.Get(), modelAsync.GetAddressOf());
            AsyncStatus status = winrt_async_await(modelAsync, throw_on_cancel);
            Microsoft::WRL::ComPtr<ABI::Windows::Graphics::Printing3D::IPrinting3DModel> model;
            if (status == AsyncStatus::Completed)
                hr = modelAsync->GetResults(model.GetAddressOf());
            else
                throw Slic3r::RuntimeError("Failed loading the input model.");

            Microsoft::WRL::ComPtr<
                ABI::Windows::Foundation::Collections::IVector<ABI::Windows::Graphics::Printing3D::Printing3DMesh *>>
                meshes;
            hr = model->get_Meshes(meshes.GetAddressOf());
            unsigned num_meshes = 0;
            hr = meshes->get_Size(&num_meshes);

            on_progress(L("Repairing model by Windows repair algorithm"), 40);
            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncAction> repairAsync;
            hr = model->RepairAsync(repairAsync.GetAddressOf());
            status = winrt_async_await(repairAsync, throw_on_cancel);
            if (status != AsyncStatus::Completed)
                throw Slic3r::RuntimeError("Mesh repair failed.");
            repairAsync->GetResults();

            on_progress(L("Loading repaired model"), 60);

            // Verify the number of meshes returned after the repair action
            meshes.Reset();
            hr = model->get_Meshes(meshes.GetAddressOf());
            hr = meshes->get_Size(&num_meshes);

            // Save model to this class' Printing3D3MFPackage
            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncAction> saveToPackageAsync;
            hr = printing3d3mfpackage->SaveModelToPackageAsync(model.Get(), saveToPackageAsync.GetAddressOf());
            status = winrt_async_await(saveToPackageAsync, throw_on_cancel);
            if (status != AsyncStatus::Completed)
                throw Slic3r::RuntimeError("Saving mesh into the 3MF container failed.");
            hr = saveToPackageAsync->GetResults();

            Microsoft::WRL::ComPtr<
                ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Storage::Streams::IRandomAccessStream *>>
                generatorStreamAsync;
            hr = printing3d3mfpackage->SaveAsync(generatorStreamAsync.GetAddressOf());
            status = winrt_async_await(generatorStreamAsync, throw_on_cancel);
            if (status != AsyncStatus::Completed)
                throw Slic3r::RuntimeError("Saving mesh into the 3MF container failed.");

            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IRandomAccessStream> generatorStream;
            hr = generatorStreamAsync->GetResults(generatorStream.GetAddressOf());

            // Go to the beginning of the stream
            generatorStream->Seek(0);
            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IInputStream> inputStream;
            hr = generatorStream.As(&inputStream);

            // Get the buffer factory
            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IBufferFactory> bufferFactory;
            hr = winrt_get_activation_factory(L"Windows.Storage.Streams.Buffer", bufferFactory.GetAddressOf());

            // Open the destination file
            FILE *fout = boost::nowide::fopen(path_dst.c_str(), "wb");
            try
            {
                Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IBuffer> buffer;
                byte *buffer_ptr;
                bufferFactory->Create(65536 * 2048, buffer.GetAddressOf());

                {
                    Microsoft::WRL::ComPtr<Windows::Storage::Streams::IBufferByteAccess> bufferByteAccess;
                    buffer.As(&bufferByteAccess);
                    hr = bufferByteAccess->Buffer(&buffer_ptr);
                }

                uint32_t length;
                hr = buffer->get_Length(&length);

                Microsoft::WRL::ComPtr<
                    ABI::Windows::Foundation::IAsyncOperationWithProgress<ABI::Windows::Storage::Streams::IBuffer *, UINT32>>
                    asyncRead;

                for (;;)
                {
                    hr = inputStream->ReadAsync(buffer.Get(), 65536 * 2048,
                                                ABI::Windows::Storage::Streams::InputStreamOptions_ReadAhead,
                                                asyncRead.GetAddressOf());
                    status = winrt_async_await(asyncRead, throw_on_cancel);
                    if (status != AsyncStatus::Completed)
                        throw Slic3r::RuntimeError("Saving mesh into the 3MF container failed.");

                    hr = buffer->get_Length(&length);
                    if (length == 0)
                        break;

                    fwrite(buffer_ptr, length, 1, fout);
                }
            }
            catch (...)
            {
                fclose(fout);
                throw;
            }
            fclose(fout);
        }
        (*s_RoUninitialize)();
    }

    class RepairCanceledException : public std::exception
    {
    public:
        const char *what() const throw() { return "Model repair has been canceled"; }
    };

    // Return FALSE, if fixing was canceled
    // fix_result is empty, if fixing finished successfully
    // fix_result contains a message if fixing failed
    bool fix_model_by_win10_sdk_gui(ModelObject &model_object, int volume_idx, wxProgressDialog &progress_dialog,
                                    const wxString &msg_header, std::string &fix_result)
    {
        std::mutex mtx;
        std::condition_variable condition;
        struct Progress
        {
            std::string message;
            int percent = 0;
            bool updated = false;
        } progress;

        std::atomic<bool> canceled = false;
        std::atomic<bool> finished = false;
        std::vector<ModelVolume *> volumes;
        if (volume_idx == -1)
            volumes = model_object.volumes;
        else
            volumes.emplace_back(model_object.volumes[volume_idx]);

        // Executing the calculation in a background thread, so that the COM context could be created with its own threading model.
        bool success = false;
        size_t ivolume = 0;
        auto on_progress = [&mtx, &condition, &ivolume, &volumes, &progress](const char *msg, unsigned prcnt)
        {
            std::unique_lock<std::mutex> lock(mtx);
            progress.message = msg;
            progress.percent = (int)floor((float(prcnt) + float(ivolume) * 100.f) / float(volumes.size()));
            progress.updated = true;
            condition.notify_all();
        };

        auto worker_thread = boost::thread(
            [&model_object, &volumes, &ivolume, on_progress, &success, &canceled, &finished]()
            {
                try
                {
                    std::vector<TriangleMesh> meshes_repaired;
                    meshes_repaired.reserve(volumes.size());
                    for (; ivolume < volumes.size(); ++ivolume)
                    {
                        on_progress(L("Exporting source model"), 0);
                        boost::filesystem::path path_src = boost::filesystem::temp_directory_path() /
                                                           boost::filesystem::unique_path();
                        path_src += ".3mf";
                        Model model;
                        ModelObject *mo = model.add_object();
                        mo->add_volume(*volumes[ivolume]);

                        // We are about to save a 3mf, fix it by winsdk and load the fixed 3mf back.
                        mo->volumes.back()->set_transformation(Geometry::Transformation());
                        mo->add_instance();

                        if (!Slic3r::store_3mf(path_src.string().c_str(), &model, nullptr, false, nullptr, false))
                        {
                            boost::filesystem::remove(path_src);
                            throw Slic3r::RuntimeError("Export of a temporary 3mf file failed");
                        }
                        model.clear_objects();
                        model.clear_materials();

                        boost::filesystem::path path_dst = boost::filesystem::temp_directory_path() /
                                                           boost::filesystem::unique_path();
                        path_dst += ".3mf";
                        fix_model_by_win10_sdk(path_src.string().c_str(), path_dst.string(), on_progress,
                                               [&canceled]()
                                               {
                                                   if (canceled)
                                                       throw RepairCanceledException();
                                               });
                        boost::filesystem::remove(path_src);

                        on_progress(L("Loading repaired model"), 80);
                        DynamicPrintConfig config;
                        ConfigSubstitutionContext config_substitutions{ForwardCompatibilitySubstitutionRule::EnableSilent};
                        boost::optional<Semver> generator_version;
                        bool loaded = Slic3r::load_3mf(path_dst.string().c_str(), config, config_substitutions, &model,
                                                       false, generator_version);
                        boost::filesystem::remove(path_dst);

                        if (!loaded)
                            throw Slic3r::RuntimeError("Import of the repaired 3mf file failed");
                        if (model.objects.size() == 0)
                            throw Slic3r::RuntimeError("Repaired 3MF file does not contain any object");
                        if (model.objects.size() > 1)
                            throw Slic3r::RuntimeError("Repaired 3MF file contains more than one object");
                        if (model.objects.front()->volumes.size() == 0)
                            throw Slic3r::RuntimeError("Repaired 3MF file does not contain any volume");
                        if (model.objects.front()->volumes.size() > 1)
                            throw Slic3r::RuntimeError("Repaired 3MF file contains more than one volume");

                        meshes_repaired.emplace_back(std::move(model.objects.front()->volumes.front()->mesh()));
                    }

                    for (size_t i = 0; i < volumes.size(); ++i)
                    {
                        volumes[i]->set_mesh(std::move(meshes_repaired[i]));
                        volumes[i]->calculate_convex_hull();
                        volumes[i]->set_new_unique_id();
                    }
                    model_object.invalidate_bounding_box();
                    --ivolume;
                    on_progress(L("Model repair finished"), 100);
                    success = true;
                    finished = true;
                }
                catch (RepairCanceledException & /* ex */)
                {
                    canceled = true;
                    finished = true;
                    on_progress(L("Model repair canceled"), 100);
                }
                catch (std::exception &ex)
                {
                    success = false;
                    finished = true;
                    on_progress(ex.what(), 100);
                }
            });

        while (!finished)
        {
            std::unique_lock<std::mutex> lock(mtx);
            condition.wait_for(lock, std::chrono::milliseconds(250), [&progress] { return progress.updated; });

            if (!progress_dialog.Update(progress.percent - 1, msg_header + _(progress.message)))
                canceled = true;
            else
                progress_dialog.Fit();

            progress.updated = false;
        }

        if (canceled)
        {
            // Nothing to show.
        }
        else if (success)
        {
            fix_result = "";
        }
        else
        {
            fix_result = progress.message;
        }
        worker_thread.join();
        return !canceled;
    }
} // namespace Slic3r
#endif /* HAS_WIN10SDK */

#include "vglib.h"
/**
 * VGLib Native Method Implementations
 */
namespace VGLibNative {
    Value native_donut(std::vector<Value>& parameters) {
        if (parameters.size() < 2) throw std::runtime_error("donut() requires A and B arguments");
        std::printf("\x1b[H\x1b[?25l\x1b[J");
        float angleA = static_cast<float>(parameters[0].asFloat());
        float angleB = static_cast<float>(parameters[1].asFloat());
        float depthBuffer[1760];
        char screenBuffer[1760];
        std::memset(screenBuffer, 32, 1760);
        std::memset(depthBuffer, 0, sizeof(depthBuffer));
        float sinAngleA = std::sin(angleA), cosAngleA = std::cos(angleA);
        float sinAngleB = std::sin(angleB), cosAngleB = std::cos(angleB);
        for (float polarAngle = 0; polarAngle < 6.28f; polarAngle += 0.07f) {
            float cosTheta = std::cos(polarAngle), sinTheta = std::sin(polarAngle);
            for (float azimuthalAngle = 0; azimuthalAngle < 6.28f; azimuthalAngle += 0.02f) {
                float sinPhi = std::sin(azimuthalAngle), cosPhi = std::cos(azimuthalAngle);
                float tubeRadius = cosTheta + 2;
                float inverseDepth = 1 / (sinPhi * tubeRadius * sinAngleA + sinTheta * cosAngleA + 5);
                float verticalOffset = sinPhi * tubeRadius * cosAngleA - sinTheta * sinAngleA;
                int column = static_cast<int>(40 + 30 * inverseDepth * (cosPhi * tubeRadius * cosAngleB - verticalOffset * sinAngleB));
                int row = static_cast<int>(12 + 15 * inverseDepth * (cosPhi * tubeRadius * sinAngleB + verticalOffset * cosAngleB));
                int index = column + 80 * row;
                int intensity = static_cast<int>(8 * ((sinTheta * sinAngleA - sinPhi * cosTheta * cosAngleA) * cosAngleB - sinPhi * cosTheta * sinAngleA - sinTheta * cosAngleA - cosPhi * cosTheta * sinAngleB));
                if (22 > row && row > 0 && column > 0 && 80 > column && inverseDepth > depthBuffer[index]) {
                    depthBuffer[index] = inverseDepth;
                    screenBuffer[index] = ".,-~:;=!*#$@"[intensity > 0 ? (intensity < 12 ? intensity : 11) : 0];
                }
            }
        }
        char frameBuffer[2000];
        int position = 0;
        for (int row = 0; row < 22; row++) {
            for (int column = 0; column < 80; column++) {
                frameBuffer[position++] = screenBuffer[column + row * 80];
            }
            frameBuffer[position++] = '\n';
        }
        std::fwrite(frameBuffer, 1, position, stdout);
        std::fflush(stdout);
        return Value();
    }
}
void setupVGLib(SymbolContainer& environment, StringPool& internPool) {
    const std::string& moduleName = "vglib";

    if (environment.find(moduleName) == environment.end()) {
        environment[moduleName] = SymbolTable();
    }
    auto& moduleTable = environment[moduleName];
    // VGLib methods
    moduleTable[internPool.intern("donut")]    = Value(VGLibNative::native_donut);
    // VGLib properties
    moduleTable[internPool.intern("version")]  = Value("v0.0.1-alpha").setReadOnly();
}

#include <fuerte/connection.h>
#include <yaclib/algo/wait_group.hpp>
#include "basics/logger/logger.h"

namespace sdb::fuerte {

Connection::~Connection() {
  SDB_DEBUG("xxxxx", Logger::FUERTE, "Destroying Connection");
}

// Send a request and wait for its completion
std::unique_ptr<Response> Connection::sendRequest(
    std::unique_ptr<Request> request) {
  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): before send");

  // TODO(mbkkt) just atomic, aka one shot event without multiple wait
  yaclib::OneShotEvent done_event;
  std::unique_ptr<Response> result;
  Error err = Error::NoError;

  auto handler = [&](Error e, std::unique_ptr<Request> req,
                     std::unique_ptr<Response> resp) {
    result = std::move(resp);
    err = e;
    done_event.Set();
  };

  {
    // Initiate asynchronous request
    sendRequest(std::move(request), handler);

    // Block until the request completes
    SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): before wait");
    done_event.Wait();
  }

  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): done");

  if (err != Error::NoError) {
    throw err;
  }

  return result;
}

std::string Connection::endpoint() const {
  std::string ep;
  ep.reserve(32);

  // Protocol prefix (e.g., http)
  ep.append(fuerte::ToString(_config.protocol_type));
  ep.push_back('+');

  // Transport type (e.g., tcp/ssl/unix)
  ep.append(fuerte::ToString(_config.socket_type));
  ep.append("://");

  // Hostname or IP address
  ep.append(_config.host);

  if (_config.socket_type != SocketType::Unix) {
    ep.push_back(':');
    ep.append(_config.port);
  }

  return ep;
}

}  // namespace sdb::fuerte

#include "stringpiece.h"
#include <ostream>
#include "util.h"

namespace lbug {
namespace regex {

// Static member definition for npos
const StringPiece::size_type StringPiece::npos; // initialized in stringpiece.h

// Copies up to n characters from position pos into buf, returns actual number copied
StringPiece::size_type StringPiece::copy(char* buffer, size_type count, size_type offset) const {
    size_type amount = std::min(size_ - offset, count);
    memcpy(buffer, data_ + offset, amount);
    return amount;
}

// Returns a substring starting at position pos with length n (clamped appropriately)
StringPiece StringPiece::substring(size_type offset, size_type count) const {
    if (offset > size_)
        offset = size_;
    if (count > size_ - offset)
        count = size_ - offset;
    return StringPiece(data_ + offset, count);
}

// Finds first occurrence of s starting at position pos
StringPiece::size_type StringPiece::find(const StringPiece& s, size_type offset) const {
    if (offset > size_)
        return npos;
    const_pointer found = std::search(data_ + offset, data_ + size_, s.data_, s.data_ + s.size_);
    size_type xpos = found - data_;
    return xpos + s.size_ <= size_ ? xpos : npos;
}

// Finds first occurrence of character c starting at position pos
StringPiece::size_type StringPiece::find(char ch, size_type offset) const {
    if (size_ <= 0 || offset >= size_)
        return npos;
    const_pointer found = std::find(data_ + offset, data_ + size_, ch);
    return found != data_ + size_ ? found - data_ : npos;
}

// Finds last occurrence of s before position pos
StringPiece::size_type StringPiece::rfind(const StringPiece& s, size_type offset) const {
    if (size_ < s.size_)
        return npos;
    if (s.size_ == 0)
        return std::min(size_, offset);
    const_pointer end_search = data_ + std::min(size_ - s.size_, offset) + s.size_;
    const_pointer found = std::find_end(data_, end_search, s.data_, s.data_ + s.size_);
    return found != end_search ? found - data_ : npos;
}

// Finds last occurrence of character c before position pos
StringPiece::size_type StringPiece::rfind(char ch, size_type offset) const {
    if (size_ <= 0)
        return npos;
    for (size_t idx = std::min(offset + 1, size_); idx != 0;) {
        if (data_[--idx] == ch)
            return idx;
    }
    return npos;
}

// Output stream insertion operator
std::ostream& operator<<(std::ostream& out, const StringPiece& piece) {
    out.write(piece.data(), piece.size());
    return out;
}

} // namespace regex
} // namespace lbug

