// Global flags for device enablement, initialized from settings
bool hmd_enabled = GetBoolFromSettingsByKey("enable hmd");
bool left_controller_enabled = GetBoolFromSettingsByKey("enable cl");
bool right_controller_enabled = GetBoolFromSettingsByKey("enable cr");

// Initialize the server driver with configured devices
EVRInitError CServerDriver_Sample::Init(vr::IVRDriverContext* pDriverContext)
{
    VR_INIT_SERVER_DRIVER_CONTEXT(pDriverContext);

    // Re-read settings to ensure latest values are used
    hmd_enabled = GetBoolFromSettingsByKey("enable hmd");
    left_controller_enabled = GetBoolFromSettingsByKey("enable cl");
    right_controller_enabled = GetBoolFromSettingsByKey("enable cr");

    // Add HMD if enabled
    if (hmd_enabled) {
        m_pNullHmdLatest = new CSampleDeviceDriver();
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            m_pNullHmdLatest->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_HMD,
            m_pNullHmdLatest
        );
    }

    // Add left controller if enabled
    if (left_controller_enabled) {
        m_pController = new CSampleControllerDriver();
        m_pController->SetControllerIndex(false);
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            m_pController->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_Controller,
            m_pController
        );
    }

    // Add right controller if enabled
    if (right_controller_enabled) {
        m_pController2 = new CSampleControllerDriver();
        m_pController2->SetControllerIndex(true);
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            m_pController2->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_Controller,
            m_pController2
        );
    }

    // Add generic trackers based on configured count
    int num_trackers = GetIntFromSettingsByKey("trackers num");
    for (int index = 0; index < num_trackers; ++index) {
        CSampleTracker* tracker = new CSampleTracker();
        tracker->SetTrackerIndex(index);
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            tracker->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_GenericTracker,
            tracker
        );
        m_vecTrackers.push_back(tracker);
    }

    return VRInitError_None;
}

// Clean up allocated resources
void CServerDriver_Sample::Cleanup()
{
    if (hmd_enabled) {
        delete m_pNullHmdLatest;
        m_pNullHmdLatest = nullptr;
    }
    if (left_controller_enabled) {
        delete m_pController;
        m_pController = nullptr;
    }
    if (right_controller_enabled) {
        delete m_pController2;
        m_pController2 = nullptr;
    }

    // Delete all trackers and clear the vector
    for (auto tracker : m_vecTrackers) {
        delete tracker;
    }
    m_vecTrackers.clear();
}

// Run a single frame of simulation/update logic
void CServerDriver_Sample::RunFrame()
{
    if (m_pNullHmdLatest && hmd_enabled) {
        m_pNullHmdLatest->RunFrame();
    }
    if (m_pController && left_controller_enabled) {
        m_pController->RunFrame();
    }
    if (m_pController2 && right_controller_enabled) {
        m_pController2->RunFrame();
    }

    // Update all active trackers
    for (auto tracker : m_vecTrackers) {
        tracker->RunFrame();
    }
}

#include "AsyncMqttClient.hpp"

// Modified constructor with renamed variables and reordering of some initializations
AsyncMqttClient::AsyncMqttClient()
: _client()
, _head(nullptr)
, _tail(nullptr)
, _sent(0)
, _state(DISCONNECTED)
, _disconnectReason(AsyncMqttClientDisconnectReason::TCP_DISCONNECTED)
, _lastServerActivity(0)
, _lastClientActivity(0)
, _lastPingRequestTime(0)
, _generatedClientId{0}
, _ip()
, _host(nullptr)
, _useIp(false)
#if ASYNC_TCP_SSL_ENABLED
, _secure(false)
#endif
, _port(0)
, _keepAlive(15)
, _cleanSession(true)
, _clientId(nullptr)
, _username(nullptr)
, _password(nullptr)
, _willTopic(nullptr)
, _willPayload(nullptr)
, _willPayloadLength(0)
, _willQos(0)
, _willRetain(false)
#if ASYNC_TCP_SSL_ENABLED
, _secureServerFingerprints()
#endif
, _onConnectUserCallbacks()
, _onDisconnectUserCallbacks()
, _onSubscribeUserCallbacks()
, _onUnsubscribeUserCallbacks()
, _onMessageUserCallbacks()
, _onPublishUserCallbacks()
, _parsingInformation { .bufferState = AsyncMqttClientInternals::BufferState::NONE, .maxTopicLength = 128, .topicBuffer = NULL, .packetType = 0, .packetFlags = 0, .remainingLength = 0 }
, _currentParsedPacket(nullptr)
, _remainingLengthBufferPosition(0)
, _remainingLengthBuffer{0}
, _pendingPubRels() {
  // Register callbacks for client events
  _client.onConnect([](void* obj, AsyncClient* c) { (static_cast<AsyncMqttClient*>(obj))->_onConnect(); }, this);
  _client.onDisconnect([](void* obj, AsyncClient* c) { (static_cast<AsyncMqttClient*>(obj))->_onDisconnect(); }, this);
  _client.onAck([](void* obj, AsyncClient* c, size_t len, uint32_t time) { (static_cast<AsyncMqttClient*>(obj))->_onAck(len); }, this);
  _client.onData([](void* obj, AsyncClient* c, void* data, size_t len) { (static_cast<AsyncMqttClient*>(obj))->_onData(static_cast<char*>(data), len); }, this);
  _client.onPoll([](void* obj, AsyncClient* c) { (static_cast<AsyncMqttClient*>(obj))->_onPoll(); }, this);

  // Enable immediate sending of small packets
  _client.setNoDelay(true);

#ifdef ESP32
  // Generate unique client ID for ESP32
  sprintf(_generatedClientId, "esp32-%06llx", ESP.getEfuseMac());
  _xSemaphore = xSemaphoreCreateMutex();
#elif defined(ESP8266)
  // Generate unique client ID for ESP8266
  sprintf(_generatedClientId, "esp8266-%06x", ESP.getChipId());
#endif

  // Set default max topic length and assign generated client ID
  setMaxTopicLength(128);
  _clientId = _generatedClientId;
}

// Destructor - cleaned up resources
AsyncMqttClient::~AsyncMqttClient() {
  delete _currentParsedPacket;
  delete[] _parsingInformation.topicBuffer;
  _clear();
  _pendingPubRels.clear();
  _pendingPubRels.shrink_to_fit();
  _clearQueue(false);

#ifdef ESP32
  vSemaphoreDelete(_xSemaphore);
#endif
}

