namespace Assimp {

aiVector3D X3DGeoHelper::make_point2D(float theta, float dist) {
    return aiVector3D(dist * std::cos(theta), dist * std::sin(theta), 0.0f);
}

void X3DGeoHelper::make_arc2D(float startAngle, float endAngle, float radius, size_t segments, std::list<aiVector3D> &vertexList) {
    // Validate input parameters
    if ((startAngle < -AI_MATH_TWO_PI_F) || (startAngle > AI_MATH_TWO_PI_F)) {
        throw DeadlyImportError("Arc2D.startAngle out of bounds");
    }
    if ((endAngle < -AI_MATH_TWO_PI_F) || (endAngle > AI_MATH_TWO_PI_F)) {
        throw DeadlyImportError("Arc2D.endAngle out of bounds");
    }
    if (radius <= 0.0f) {
        throw DeadlyImportError("Arc2D.radius must be positive");
    }

    // Compute total angle span
    float totalAngle = std::fabs(endAngle - startAngle);
    if ((totalAngle > AI_MATH_TWO_PI_F) || (totalAngle == 0.0f)) {
        totalAngle = AI_MATH_TWO_PI_F;
    }

    // Determine angular step size
    float deltaAngle = totalAngle / static_cast<float>(segments);

    // Generate points along the arc
    for (size_t idx = 0; idx <= segments; ++idx) {
        float currentAngle = startAngle + idx * deltaAngle;
        vertexList.emplace_back(make_point2D(currentAngle, radius));
    }

    // For full circles, duplicate the first point at the end
    if (totalAngle == AI_MATH_TWO_PI_F) {
        vertexList.push_back(*vertexList.begin());
    }
}

void X3DGeoHelper::extend_point_to_line(const std::list<aiVector3D> &inputPoints, std::list<aiVector3D> &outputLine) {
    auto iterCurrent = inputPoints.begin();
    auto iterEnd = inputPoints.end();
    --iterEnd;

    if (inputPoints.size() < 2) {
        throw DeadlyImportError("Extend_PointToLine: requires at least two points.");
    }

    outputLine.push_back(*iterCurrent++);
    while (iterCurrent != iterEnd) {
        outputLine.push_back(*iterCurrent); // End of previous segment
        outputLine.push_back(*iterCurrent); // Start of next segment
        ++iterCurrent;
    }
    outputLine.push_back(*iterCurrent); // Final point
}

void X3DGeoHelper::polylineIdx_to_lineIdx(const std::list<int32_t> &polylineIndices, std::list<int32_t> &lineIndices) {
    auto iterPoly = polylineIndices.begin();
    while (iterPoly != polylineIndices.end()) {
        lineIndices.push_back(*iterPoly++);

        while ((*iterPoly != -1) && (iterPoly != polylineIndices.end())) {
            auto iterNext = iterPoly;
            ++iterNext;

            lineIndices.push_back(*iterPoly);     // Shared vertex
            lineIndices.push_back(-1);            // Separator
            if ((*iterNext == -1) || (iterNext == polylineIndices.end())) break;

            lineIndices.push_back(*iterPoly);     // Shared vertex again
            iterPoly = iterNext;
        }
    }
}

