    do {                                                            \
        if (pCCW) {                                                 \
            pOut.push_back(pIn[pP1]);                               \
            pOut.push_back(pIn[pP2]);                               \
            pOut.push_back(pIn[pP3]);                               \
            pOut.push_back(pIn[pP4]);                               \
        } else {                                                    \
            pOut.push_back(pIn[pP4]);                               \
            pOut.push_back(pIn[pP3]);                               \
            pOut.push_back(pIn[pP2]);                               \
            pOut.push_back(pIn[pP1]);                               \
        }                                                           \
    } while (false)

#define MESH_RectParallelepiped_CREATE_VERT \
    aiVector3D vert_set[8];                 \
    float x_min, x_max, y_min, y_max, z_min, z_max, halfDim; \
                                            \
    halfDim = pSize.x / 2.0f; x_min = -halfDim; x_max = halfDim; \
    halfDim = pSize.y / 2.0f; y_min = -halfDim; y_max = halfDim; \
    halfDim = pSize.z / 2.0f; z_min = -halfDim; z_max = halfDim; \
    vert_set[0].Set(x_max, y_min, z_max);   \
    vert_set[1].Set(x_max, y_max, z_max);   \
    vert_set[2].Set(x_max, y_max, z_min);   \
    vert_set[3].Set(x_max, y_min, z_min);   \
    vert_set[4].Set(x_min, y_min, z_max);   \
    vert_set[5].Set(x_min, y_max, z_max);   \
    vert_set[6].Set(x_min, y_max, z_min);   \
    vert_set[7].Set(x_min, y_min, z_min)

void X3DGeoHelper::rect_parallel_epiped(const aiVector3D &pSize, std::list<aiVector3D> &pVertices) {
    MESH_RectParallelepiped_CREATE_VERT;

    MACRO_FACE_ADD_QUAD_FA(true, pVertices, vert_set, 3, 2, 1, 0); // front face
    MACRO_FACE_ADD_QUAD_FA(true, pVertices, vert_set, 6, 7, 4, 5); // back face
    MACRO_FACE_ADD_QUAD_FA(true, pVertices, vert_set, 7, 3, 0, 4); // left face
    MACRO_FACE_ADD_QUAD_FA(true, pVertices, vert_set, 2, 6, 5, 1); // right face
    MACRO_FACE_ADD_QUAD_FA(true, pVertices, vert_set, 0, 1, 5, 4); // top face
    MACRO_FACE_ADD_QUAD_FA(true, pVertices, vert_set, 7, 6, 2, 3); // bottom face
}

