static constexpr int32_t InvalidIndexValue = -1;

void X3DGeoHelper::coordIdx_str2faces_arr(const std::vector<int32_t> &rawCoordIndices, std::vector<aiFace> &outFaces, unsigned int &primitiveTypes) {
    std::vector<int32_t> processedData(rawCoordIndices);
    std::vector<unsigned int> tempIndices;
    unsigned int currentPrimitiveType = 0;

    if (!processedData.empty() && processedData.back() != InvalidIndexValue) {
        processedData.push_back(InvalidIndexValue);
    }

    outFaces.reserve(processedData.size() / 3);
    tempIndices.reserve(4);

    for (auto it = processedData.begin(); it != processedData.end(); ++it) {
        if (*it == InvalidIndexValue) {
            aiFace currentFace;
            size_t indexCount = tempIndices.size();

            switch (indexCount) {
                case 0:
                    goto cleanup_and_error;
                case 1:
                    currentPrimitiveType |= aiPrimitiveType_POINT;
                    break;
                case 2:
                    currentPrimitiveType |= aiPrimitiveType_LINE;
                    break;
                case 3:
                    currentPrimitiveType |= aiPrimitiveType_TRIANGLE;
                    break;
                default:
                    currentPrimitiveType |= aiPrimitiveType_POLYGON;
                    break;
            }

            currentFace.mNumIndices = static_cast<unsigned int>(indexCount);
            currentFace.mIndices = new unsigned int[indexCount];
            std::memcpy(currentFace.mIndices, tempIndices.data(), indexCount * sizeof(unsigned int));
            outFaces.push_back(currentFace);
            tempIndices.clear();
        } else {
            tempIndices.push_back(static_cast<unsigned int>(*it));
        }
    }

    primitiveTypes = currentPrimitiveType;
    return;

cleanup_and_error:
    for (auto &face : outFaces) {
        delete[] face.mIndices;
    }
    outFaces.clear();
}

void X3DGeoHelper::coordIdx_str2lines_arr(const std::vector<int32_t> &rawCoordIndices, std::vector<aiFace> &outFaces) {
    std::vector<int32_t> processedData(rawCoordIndices);
    if (!processedData.empty() && processedData.back() != InvalidIndexValue) {
        processedData.push_back(InvalidIndexValue);
    }

    outFaces.reserve(processedData.size() / 2);

    auto startIt = processedData.cbegin();
    for (auto endIt = processedData.cbegin(); endIt != processedData.cend(); ++endIt) {
        if (*endIt != -1) continue;

        std::size_t segmentLength = std::distance(startIt, endIt);
        if (segmentLength <= 1) goto cleanup_and_error;

        int32_t prevIndex = *startIt++;
        while (startIt != endIt) {
            int32_t currIndex = *startIt++;

            aiFace lineFace;
            lineFace.mNumIndices = 2;
            lineFace.mIndices = new unsigned int[2];
            lineFace.mIndices[0] = static_cast<unsigned int>(prevIndex);
            lineFace.mIndices[1] = static_cast<unsigned int>(currIndex);
            outFaces.push_back(lineFace);

            prevIndex = currIndex;
        }
        ++startIt;
    }
    return;

cleanup_and_error:
    for (auto &face : outFaces) {
        delete[] face.mIndices;
    }
    outFaces.clear();
}

void X3DGeoHelper::add_color(aiMesh &mesh, const std::list<aiColor3D> &colorsRGB, const bool perVertex) {
    std::list<aiColor4D> colorsRGBA;
    for (const auto &color : colorsRGB) {
        colorsRGBA.emplace_back(color.r, color.g, color.b, static_cast<ai_real>(1.0));
    }
    add_color(mesh, colorsRGBA, perVertex);
}

void X3DGeoHelper::add_color(aiMesh &mesh, const std::list<aiColor4D> &colorsRGBA, const bool perVertex) {
    auto colorIter = colorsRGBA.begin();

    if (perVertex) {
        if (colorsRGBA.size() < mesh.mNumVertices) {
            throw DeadlyImportError("Color count (" + ai_to_string(colorsRGBA.size()) +
                                    ") insufficient for vertex count (" + ai_to_string(mesh.mNumVertices) + ")");
        }

        mesh.mColors[0] = new aiColor4D[mesh.mNumVertices];
        for (size_t i = 0; i < mesh.mNumVertices; ++i) {
            mesh.mColors[0][i] = *colorIter++;
        }
    } else {
        if (colorsRGBA.size() < mesh.mNumFaces) {
            throw DeadlyImportError("Color count (" + ai_to_string(colorsRGBA.size()) +
                                    ") insufficient for face count (" + ai_to_string(mesh.mNumFaces) + ")");
        }

        mesh.mColors[0] = new aiColor4D[mesh.mNumVertices];
        for (size_t f = 0; f < mesh.mNumFaces; ++f) {
            const auto &face = mesh.mFaces[f];
            for (size_t v = 0; v < face.mNumIndices; ++v) {
                mesh.mColors[0][face.mIndices[v]] = *colorIter;
            }
            ++colorIter;
        }
    }
}

void X3DGeoHelper::add_color(aiMesh &mesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &colorIdx, const std::list<aiColor3D> &colorsRGB, const bool perVertex) {
    std::list<aiColor4D> colorsRGBA;
    for (const auto &color : colorsRGB) {
        colorsRGBA.emplace_back(color.r, color.g, color.b, static_cast<ai_real>(1.0));
    }
    add_color(mesh, coordIdx, colorIdx, colorsRGBA, perVertex);
}

void X3DGeoHelper::add_color(aiMesh &mesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &colorIdx, const std::list<aiColor4D> &colorsRGBA, bool perVertex) {
    std::vector<aiColor4D> targetColors;
    std::vector<aiColor4D> colorBuffer;
    colorBuffer.reserve(colorsRGBA.size());

    for (const auto &color : colorsRGBA) {
        colorBuffer.push_back(color);
    }

    if (perVertex) {
        if (!colorIdx.empty()) {
            if (colorIdx.size() < coordIdx.size()) {
                throw DeadlyImportError("Color indices count insufficient for coordinate indices.");
            }

            targetColors.resize(mesh.mNumVertices);
            for (size_t i = 0; i < colorIdx.size(); ++i) {
                if (colorIdx[i] == -1) continue;

                if (static_cast<size_t>(coordIdx[i]) >= mesh.mNumVertices ||
                    static_cast<size_t>(colorIdx[i]) >= colorBuffer.size()) {
                    throw DeadlyImportError("Color or coordinate index out of range.");
                }
                targetColors[coordIdx[i]] = colorBuffer[colorIdx[i]];
            }
        } else {
            if (colorsRGBA.size() < mesh.mNumVertices) {
                throw DeadlyImportError("Not enough colors for all vertices.");
            }

            targetColors.resize(mesh.mNumVertices);
            for (size_t i = 0; i < mesh.mNumVertices; ++i) {
                targetColors[i] = colorBuffer[i];
            }
        }
    } else {
        if (!colorIdx.empty()) {
            if (colorIdx.size() < mesh.mNumFaces) {
                throw DeadlyImportError("Color indices count insufficient for faces.");
            }

            targetColors.resize(mesh.mNumFaces);
            for (size_t f = 0; f < mesh.mNumFaces; ++f) {
                if (static_cast<size_t>(colorIdx[f]) >= colorBuffer.size()) {
                    throw DeadlyImportError("Color index out of range.");
                }
                targetColors[f] = colorBuffer[colorIdx[f]];
            }
        } else {
            if (colorsRGBA.size() < mesh.mNumFaces) {
                throw DeadlyImportError("Not enough colors for all faces.");
            }

            targetColors.resize(mesh.mNumFaces);
            for (size_t f = 0; f < mesh.mNumFaces; ++f) {
                targetColors[f] = colorBuffer[f];
            }
        }
    }

    std::list<aiColor4D> finalColors;
    for (const auto &c : targetColors) {
        finalColors.push_back(c);
    }
    add_color(mesh, finalColors, perVertex);
}

void X3DGeoHelper::add_normal(aiMesh &mesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &normalIdx, const std::list<aiVector3D> &normals, const bool perVertex) {
    std::vector<aiVector3D> normalBuffer;
    normalBuffer.reserve(normals.size());
    for (const auto &n : normals) {
        normalBuffer.push_back(n);
    }

    if (perVertex) {
        if (!normalIdx.empty()) {
            if (normalIdx.size() != coordIdx.size()) {
                throw DeadlyImportError("Normal and coordinate index counts must match.");
            }

            std::vector<size_t> mappedIndices;
            mappedIndices.reserve(normalIdx.size());
            for (int32_t idx : normalIdx) {
                if (idx != -1) mappedIndices.push_back(static_cast<size_t>(idx));
            }

            mesh.mNormals = new aiVector3D[mesh.mNumVertices];
            for (size_t i = 0; i < mesh.mNumVertices && i < mappedIndices.size(); ++i) {
                if (mappedIndices[i] >= normalBuffer.size()) {
                    throw DeadlyImportError("Normal index out of range.");
                }
                mesh.mNormals[i] = normalBuffer[mappedIndices[i]];
            }
        } else {
            if (normals.size() != mesh.mNumVertices) {
                throw DeadlyImportError("Normal and vertex counts must match.");
            }

            mesh.mNormals = new aiVector3D[mesh.mNumVertices];
            auto normIter = normals.begin();
            for (size_t i = 0; i < mesh.mNumVertices; ++i) {
                mesh.mNormals[i] = *normIter++;
            }
        }
    } else {
        std::vector<size_t> faceNormalIndices;
        if (!normalIdx.empty()) {
            if (normalIdx.size() != mesh.mNumFaces) {
                throw DeadlyImportError("Normal face count must match mesh face count.");
            }
            faceNormalIndices.reserve(normalIdx.size());
            for (int32_t idx : normalIdx) {
                faceNormalIndices.push_back(static_cast<size_t>(idx));
            }
        } else {
            faceNormalIndices.reserve(mesh.mNumFaces);
            for (size_t i = 0; i < mesh.mNumFaces; ++i) {
                faceNormalIndices.push_back(i);
            }
        }

        mesh.mNormals = new aiVector3D[mesh.mNumVertices];
        for (size_t f = 0; f < mesh.mNumFaces; ++f) {
            aiVector3D faceNormal = normalBuffer[faceNormalIndices[f]];
            const auto &face = mesh.mFaces[f];
            for (size_t v = 0; v < face.mNumIndices; ++v) {
                mesh.mNormals[face.mIndices[v]] = faceNormal;
            }
        }
    }
}

void X3DGeoHelper::add_normal(aiMesh &mesh, const std::list<aiVector3D> &normals, const bool perVertex) {
    auto normIter = normals.begin();

    if (perVertex) {
        if (normals.size() != mesh.mNumVertices) {
            throw DeadlyImportError("Normal and vertex counts must match.");
        }

        mesh.mNormals = new aiVector3D[mesh.mNumVertices];
        for (size_t i = 0; i < mesh.mNumVertices; ++i) {
            mesh.mNormals[i] = *normIter++;
        }
    } else {
        if (normals.size() != mesh.mNumFaces) {
            throw DeadlyImportError("Normal and face counts must match.");
        }

        mesh.mNormals = new aiVector3D[mesh.mNumVertices];
        for (size_t f = 0; f < mesh.mNumFaces; ++f) {
            const auto &face = mesh.mFaces[f];
            for (size_t v = 0; v < face.mNumIndices; ++v) {
                mesh.mNormals[face.mIndices[v]] = *normIter;
            }
            ++normIter;
        }
    }
}

void X3DGeoHelper::add_tex_coord(aiMesh &mesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &texCoordIdx, const std::list<aiVector2D> &texCoords) {
    std::vector<aiVector3D> texCoordBuffer;
    texCoordBuffer.reserve(texCoords.size());
    for (const auto &tc : texCoords) {
        texCoordBuffer.emplace_back(tc.x, tc.y, static_cast<ai_real>(0));
    }

    std::vector<aiFace> faceList;
    unsigned int primType;

    if (!texCoordIdx.empty()) {
        coordIdx_str2faces_arr(texCoordIdx, faceList, primType);
        if (faceList.empty()) {
            throw DeadlyImportError("Failed to parse texture coordinate faces.");
        }
        if (faceList.size() != mesh.mNumFaces) {
            throw DeadlyImportError("Texture coordinate face count mismatch.");
        }
    } else {
        coordIdx_str2faces_arr(coordIdx, faceList, primType);
    }

    mesh.mTextureCoords[0] = new aiVector3D[mesh.mNumVertices];
    mesh.mNumUVComponents[0] = 2;

    for (size_t f = 0; f < faceList.size(); ++f) {
        const auto &face = mesh.mFaces[f];
        const auto &texFace = faceList[f];
        if (face.mNumIndices != texFace.mNumIndices) {
            throw DeadlyImportError("Mismatch in face vertex counts.");
        }
        for (size_t v = 0; v < face.mNumIndices; ++v) {
            size_t vertexIndex = face.mIndices[v];
            size_t texIndex = texFace.mIndices[v];
            mesh.mTextureCoords[0][vertexIndex] = texCoordBuffer[texIndex];
        }
    }
}

void X3DGeoHelper::add_tex_coord(aiMesh &mesh, const std::list<aiVector2D> &texCoords) {
    if (texCoords.size() != mesh.mNumVertices) {
        throw DeadlyImportError("Texture coordinate and vertex counts must match.");
    }

    std::vector<aiVector3D> texCoordBuffer;
    texCoordBuffer.reserve(texCoords.size());
    for (const auto &tc : texCoords) {
        texCoordBuffer.emplace_back(tc.x, tc.y, static_cast<ai_real>(0));
    }

    mesh.mTextureCoords[0] = new aiVector3D[mesh.mNumVertices];
    mesh.mNumUVComponents[0] = 2;

    for (size_t i = 0; i < mesh.mNumVertices; ++i) {
        mesh.mTextureCoords[0][i] = texCoordBuffer[i];
    }
}

aiMesh *X3DGeoHelper::make_mesh(const std::vector<int32_t> &coordIdx, const std::list<aiVector3D> &vertices) {
    std::vector<aiFace> faces;
    unsigned int primitiveType = 0;

    coordIdx_str2faces_arr(coordIdx, faces, primitiveType);
    if (faces.empty()) {
        throw DeadlyImportError("Cannot construct mesh without faces.");
    }

    aiMesh *result = new aiMesh();
    result->mFaces = new aiFace[faces.size()];
    result->mNumFaces = static_cast<unsigned int>(faces.size());
    for (size_t i = 0; i < faces.size(); ++i) {
        result->mFaces[i] = faces[i];
    }

    result->mVertices = new aiVector3D[vertices.size()];
    result->mNumVertices = static_cast<unsigned int>(vertices.size());
    auto vertIter = vertices.begin();
    for (size_t i = 0; i < vertices.size(); ++i) {
        result->mVertices[i] = *vertIter++;
    }

    result->mPrimitiveTypes = primitiveType;
    return result;
}

aiMesh *X3DGeoHelper::make_line_mesh(const std::vector<int32_t> &coordIdx, const std::list<aiVector3D> &vertices) {
    std::vector<aiFace> faces;
    coordIdx_str2lines_arr(coordIdx, faces);
    if (faces.empty()) {
        throw DeadlyImportError("Cannot construct line mesh without faces.");
    }

    aiMesh *result = new aiMesh();
    result->mFaces = new aiFace[faces.size()];
    result->mNumFaces = static_cast<unsigned int>(faces.size());
    for (size_t i = 0; i < faces.size(); ++i) {
        result->mFaces[i] = faces[i];
    }

    result->mVertices = new aiVector3D[vertices.size()];
    result->mNumVertices = static_cast<unsigned int>(vertices.size());
    auto vertIter = vertices.begin();
    for (size_t i = 0; i < vertices.size(); ++i) {
        result->mVertices[i] = *vertIter++;
    }

    result->mPrimitiveTypes = aiPrimitiveType_LINE;
    return result;
}

