Engine::Engine() : _contextMap() {}
Engine::~Engine() = default;

void Engine::SetTaskContextData(TfToken const& key, VtValue const& value)
{
    // Attempt to insert the new entry; if it already exists, update the value.
    std::pair<HdTaskContext::iterator, bool> insertionResult = _contextMap.emplace(key, value);
    if (!insertionResult.second)
    {
        // Entry already existed, so update its value
        insertionResult.first->second = value;
    }
}

bool Engine::GetTaskContextData(TfToken const& key, VtValue* outValue) const
{
    if (!TF_VERIFY(outValue, "outValue is nullptr"))
    {
        return false;
    }

    auto const& foundIt = _contextMap.find(key);
    if (foundIt != _contextMap.end())
    {
        *outValue = foundIt->second;
        return true;
    }
    return false;
}

void Engine::RemoveTaskContextData(TfToken const& key)
{
    _contextMap.erase(key);
}

void Engine::ClearTaskContextData()
{
    _contextMap.clear();
}

void Engine::Execute(HdRenderIndex* index, HdTaskSharedPtrVector* taskList)
{
    TRACE_FUNCTION();

    if ((index == nullptr) || (taskList == nullptr))
    {
        TF_CODING_ERROR("Passed nullptr to Engine::Execute()");
        return;
    }

    // Provide render drivers to tasks via context
    _contextMap[HdTokens->drivers] = VtValue(index->GetDrivers());

    // --------------------------------------------------------------------- //
    // DATA DISCOVERY PHASE
    // --------------------------------------------------------------------- //
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Data Discovery Phase](RenderIndex::SyncAll)         \n"
             "--------------------------------------------------------------\n");
    {
        TRACE_FUNCTION_SCOPE("Data Discovery");
        index->SyncAll(taskList, &_contextMap);
    }

    // --------------------------------------------------------------------- //
    // PREPARE PHASE
    // --------------------------------------------------------------------- //
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Prepare Phase](Task::Prepare)                       \n"
             "--------------------------------------------------------------\n");
    {
        TRACE_FUNCTION_SCOPE("Task Prepare");
        for (auto const& task : *taskList)
        {
            task->Prepare(&_contextMap, index);
        }
    }

    // --------------------------------------------------------------------- //
    // DATA COMMIT PHASE
    // --------------------------------------------------------------------- //
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Data Commit Phase](RenderDelegate::CommitResources) \n"
             "--------------------------------------------------------------\n");
    {
        TRACE_FUNCTION_SCOPE("Data Commit");
        HdRenderDelegate* delegate = index->GetRenderDelegate();
        delegate->CommitResources(&index->GetChangeTracker());
    }

    // --------------------------------------------------------------------- //
    // EXECUTE PHASE
    // --------------------------------------------------------------------- //
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
    .Msg("\n"
         "==============================================================\n"
         "  Engine [Execute Phase](Task::Execute)                       \n"
         "--------------------------------------------------------------\n");
    {
        TRACE_FUNCTION_SCOPE("Task Execution");
        for (auto const& task : *taskList)
        {
            task->Execute(&_contextMap);
        }
    }
}

void Engine::Execute(HdRenderIndex* const index, SdfPathVector const& taskPaths)
{
    HdTaskSharedPtrVector tasks;
    tasks.reserve(taskPaths.size());

    for (SdfPath const& path : taskPaths)
    {
        if (path.IsEmpty())
        {
            TF_CODING_ERROR("Empty task path given to Engine::Execute()");
            continue;
        }

        HdTaskSharedPtr task = index->GetTask(path);
        if (!task)
        {
            TF_CODING_ERROR(
                "No task at %s in render index in Engine::Execute()", path.GetText());
            continue;
        }

        tasks.push_back(std::move(task));
    }

    Execute(index, &tasks);
}

bool Engine::AreTasksConverged(HdRenderIndex* const index, SdfPathVector const& taskPaths)
{
    for (SdfPath const& path : taskPaths)
    {
        if (path.IsEmpty())
        {
            TF_CODING_ERROR("Empty task path given to Engine::AreTasksConverged()");
            continue;
        }

        HdTaskSharedPtr const task = index->GetTask(path);
        if (!task)
        {
            TF_CODING_ERROR(
                "No task at %s in render index in Engine::AreTasksConverged()", path.GetText());
            continue;
        }

        if (!task->IsConverged())
        {
            return false;
        }
    }
    return true;
}
