using namespace sdb;
using namespace sdb::rest;

Acceptor::Acceptor(rest::GeneralServer& server, rest::IoContext& context,
                   Endpoint* endpoint)
  : _server(server),
    _ctx(context),
    _endpoint(endpoint),
    _open(false),
    _error_count(0) {}

std::unique_ptr<Acceptor> Acceptor::factory(rest::GeneralServer& server,
                                            rest::IoContext& context,
                                            Endpoint* endpoint) {
#ifdef SERENEDB_HAVE_DOMAIN_SOCKETS
  if (endpoint->domainType() == Endpoint::DomainType::UNIX) {
    return std::make_unique<AcceptorUnixDomain>(server, context, endpoint);
  }
#endif
  if (endpoint->encryption() == Endpoint::EncryptionType::SSL) {
    return std::make_unique<AcceptorTcp<rest::SocketType::Ssl>>(server, context,
                                                                endpoint);
  } else {
    SDB_ASSERT(endpoint->encryption() == Endpoint::EncryptionType::None);
    return std::make_unique<AcceptorTcp<rest::SocketType::Tcp>>(server, context,
                                                                endpoint);
  }
}

void Acceptor::handleError(const asio_ns::error_code& ec) {
  // During shutdown, the _open flag is cleared first, followed by
  // cancellation and closing of the acceptor. In such a scenario,
  // we should not initiate another async_accept call.
  // Otherwise, error recovery should proceed.
  if (!_open && ec == asio_ns::error::operation_aborted) {
    // This specific condition is expected and does not warrant logging
    SDB_DEBUG("yyyyy", sdb::Logger::COMMUNICATION,
              "accept operation aborted: ", ec.message());
    return;
  }

  if (++_error_count <= kMaxAcceptErrors) {
    SDB_WARN("yyyyy", sdb::Logger::COMMUNICATION,
             "accept error occurred: ", ec.message());
    if (_error_count == kMaxAcceptErrors) {
      SDB_WARN("yyyyy", sdb::Logger::COMMUNICATION,
               "maximum accept error threshold reached, ceasing further reports");
    }
  }

  asyncAccept();  // attempt reconnection
  return;
}

