using namespace llvm;

namespace llvm {
bool DebugFlag = false;
static ManagedStatic<std::vector<std::string>> DebugTypeList;

bool isCurrentDebugType(const char *Type) {
  if (DebugTypeList->empty())
    return true;
  for (const auto &type : *DebugTypeList) {
    if (type == Type)
      return true;
  }
  return false;
}

void setCurrentDebugTypes(const char **Types, unsigned Count);
void setCurrentDebugType(const char *Type) {
  setCurrentDebugTypes(&Type, 1U);
}
void setCurrentDebugTypes(const char **Types, unsigned Count) {
  DebugTypeList->clear();
  for (unsigned i = 0; i < Count; ++i)
    DebugTypeList->push_back(Types[i]);
}
