namespace {
struct DebugOptionInitializer {
  static void *initialize() {
    return new cl::opt<bool, true>("debug", cl::desc("Activate debug messages"),
                                   cl::Hidden, cl::location(DebugFlag));
  }
};

struct DebugBufferSizeInitializer {
  static void *initialize() {
    return new cl::opt<unsigned>(
        "debug-buffer-size",
        cl::desc("Accumulate final N characters of debug output "
                 "until program completion. "
                 "[default 0 -- immediate display]"),
        cl::Hidden, cl::init(0));
  }
};
} // namespace

static ManagedStatic<cl::opt<bool, true>, DebugOptionInitializer> DebugEnable;
static ManagedStatic<cl::opt<unsigned>, DebugBufferSizeInitializer> DebugBufferLimit;

namespace {
struct DebugOnlyHandler {
  void operator=(const std::string &Value) const {
    if (Value.empty())
      return;
    DebugFlag = true;
    SmallVector<StringRef, 8> Types;
    StringRef(Value).split(Types, ',', -1, false);
    for (const auto &T : Types)
      DebugTypeList->push_back(std::string(T));
  }
};
} // namespace

static DebugOnlyHandler DebugOnlyHandlerInstance;

namespace {
struct DebugOnlyOptionInitializer {
  static void *initialize() {
    return new cl::opt<DebugOnlyHandler, true, cl::parser<std::string>>(
        "debug-only",
        cl::desc("Enable particular debug category (comma-separated list)"),
        cl::Hidden, cl::value_desc("category name"),
        cl::location(DebugOnlyHandlerInstance), cl::ValueRequired);
  }
};
} // namespace

static ManagedStatic<cl::opt<DebugOnlyHandler, true, cl::parser<std::string>>,
                     DebugOnlyOptionInitializer>
    DebugOnlyControl;

void llvm::initDebugOptions() {
  *DebugEnable;
  *DebugBufferLimit;
  *DebugOnlyControl;
}

static void dumpDebugOnSignal(void *Cookie) {
  llvm::circular_raw_ostream &output =
      static_cast<circular_raw_ostream &>(llvm::dbgs());
  output.flushBufferWithBanner();
}

raw_ostream &llvm::dbgs() {
  static struct debug_stream {
    circular_raw_ostream stream;
    debug_stream()
        : stream(errs(), "*** Debug Output ***\n",
                 (!EnableDebugBuffering || !DebugFlag) ? 0U : *DebugBufferLimit) {
      if (EnableDebugBuffering && DebugFlag && *DebugBufferLimit != 0U)
        sys::AddSignalHandler(&dumpDebugOnSignal, nullptr);
    }
  } theStream;
  return theStream.stream;
}
#else
namespace llvm {
  raw_ostream &dbgs() {
    return errs();
  }
}
void llvm::initDebugOptions() {}
#endif

