   it would redefine the "struct termios" already defined
   by the <termios.h> already included by Boost.ASIO. */
#define K_NCCS 19
struct termios2
{
    tcflag_t c_iflag;
    tcflag_t c_oflag;
    tcflag_t c_cflag;
    tcflag_t c_lflag;
    cc_t c_line;
    cc_t c_cc[K_NCCS];
    speed_t c_ispeed;
    speed_t c_ospeed;
};
#define BOTHER CBAUDEX
#endif
//#define DEBUG_SERIAL
#ifdef DEBUG_SERIAL
#include <cstdlib>
#include <fstream>
std::fstream debug_stream;
#endif
#define MAX_HISTORY 20
namespace Slic3r
{
GCodeSender::GCodeSender()
    : service(), port(service), ready_to_transmit(false), transmitted_count(0), is_open(false), has_error(false), is_connected_flag(false), buffer_paused(false)
{
#ifdef DEBUG_SERIAL
    std::srand(static_cast<unsigned>(std::time(nullptr)));
#endif
}
GCodeSender::~GCodeSender()
{
    this->disconnect();
}
bool GCodeSender::connect(std::string device_path, unsigned int baud_rate)
{
    this->disconnect();
    this->set_error_state(false);
    try
    {
        this->port.open(device_path);
        this->port.set_option(boost::asio::serial_port_base::parity(boost::asio::serial_port_base::parity::odd));
        this->port.set_option(
            boost::asio::serial_port_base::character_size(boost::asio::serial_port_base::character_size(8)));
        this->port.set_option(
            boost::asio::serial_port_base::flow_control(boost::asio::serial_port_base::flow_control::none));
        this->port.set_option(
            boost::asio::serial_port_base::stop_bits(boost::asio::serial_port_base::stop_bits::one));
        this->configure_baud(baud_rate);
        this->port.close();
        this->port.open(device_path);
        this->port.set_option(boost::asio::serial_port_base::parity(boost::asio::serial_port_base::parity::none));
        // reapply baud rate as set_option may have reset it
        this->configure_baud(baud_rate);
        this->is_open = true;
        this->reset_device();
    }
    catch (boost::system::system_error &)
    {
        this->set_error_state(true);
        return false;
    }
    // After reset, firmware expects line numbers to restart at 1
    this->transmitted_count = 0;
    this->recent_lines.clear();
    /* Initialize debugger */
#ifdef DEBUG_SERIAL
    debug_stream.open("serial_log.txt", std::fstream::out | std::fstream::trunc);
#endif
    // Schedule initial read operation before starting background thread
    boost::asio::post(this->service, boost::bind(&GCodeSender::perform_read, this));
    // start reading in the background thread
    boost::thread worker_thread(boost::bind(&boost::asio::io_context::run, &this->service));
    this->worker.swap(worker_thread);
    // Send M105 to verify connection (firmware might remain silent otherwise)
    // FIXME: This may be sent too early, causing line number sync issues.
    // this->send("M105", true);
    return true;
}
void GCodeSender::configure_baud(unsigned int rate)
{
    try
    {
        // This does not support speeds > 115200
        this->port.set_option(boost::asio::serial_port_base::baud_rate(rate));
    }
    catch (boost::system::system_error &)
    {
        boost::asio::serial_port::native_handle_type handle = this->port.native_handle();
#if __APPLE__
        termios ios;
        ::tcgetattr(handle, &ios);
        ::cfsetspeed(&ios, rate);
        speed_t newSpeed = rate;
        ioctl(handle, IOSSIOSPEED, &newSpeed);
        ::tcsetattr(handle, TCSANOW, &ios);
#elif __linux__
        termios2 ios;
        if (ioctl(handle, TCGETS2, &ios))
            printf("Error in TCGETS2: %s\n", strerror(errno));
        ios.c_ispeed = ios.c_ospeed = rate;
        ios.c_cflag &= ~CBAUD;
        ios.c_cflag |= BOTHER | CLOCAL | CREAD;
        ios.c_cc[VMIN] = 1; // Minimum of characters to read, prevents eof errors when 0 bytes are read
        ios.c_cc[VTIME] = 1;
        if (ioctl(handle, TCSETS2, &ios))
            printf("Error in TCSETS2: %s\n", strerror(errno));
#elif __OpenBSD__
        struct termios ios;
        ::tcgetattr(handle, &ios);
        ::cfsetspeed(&ios, rate);
        if (::tcsetattr(handle, TCSAFLUSH, &ios) != 0)
            printf("Failed to set baud rate: %s\n", strerror(errno));
#else
        //throw Slic3r::InvalidArgument("OS does not currently support custom bauds");
#endif
    }
}
void GCodeSender::disconnect()
{
    if (!this->is_open)
        return;
    this->is_open = false;
    this->is_connected_flag = false;
    this->service.post(boost::bind(&GCodeSender::close_port, this));
    this->worker.join();
    this->service.reset();
    /*
    if (this->error_status()) {
        throw(boost::system::system_error(boost::system::error_code(),
            "Error while closing the device"));
    }
    */
#ifdef DEBUG_SERIAL
    debug_stream << "DISCONNECTED" << std::endl << std::flush;
    debug_stream.close();
#endif
}
bool GCodeSender::is_connected() const
{
    return this->is_connected_flag;
}
bool GCodeSender::wait_connected(unsigned int timeout_seconds) const
{
    using namespace boost::posix_time;
    ptime deadline = second_clock::local_time() + seconds(timeout_seconds);
    while (!this->is_connected_flag)
    {
        if (second_clock::local_time() > deadline)
            return false;
        boost::this_thread::sleep(boost::posix_time::milliseconds(100));
    }
    return true;
}
size_t GCodeSender::queue_length() const
{
    boost::lock_guard<boost::mutex> lock(this->queue_mutex);
    return this->pending_commands.size();
}
void GCodeSender::pause_command_queue()
{
    boost::lock_guard<boost::mutex> lock(this->queue_mutex);
    this->buffer_paused = true;
}
void GCodeSender::resume_command_queue()
{
    {
        boost::lock_guard<boost::mutex> lock(this->queue_mutex);
        this->buffer_paused = false;
    }
    this->transmit();
}
void GCodeSender::clear_queue(bool high_priority)
{
    boost::lock_guard<boost::mutex> lock(this->queue_mutex);
    if (high_priority)
    {
        // clear priority queue
        std::list<std::string> empty_list;
        std::swap(this->urgent_queue, empty_list);
    }
    else
    {
        // clear regular queue
        std::queue<std::string> empty_queue;
        std::swap(this->pending_commands, empty_queue);
        this->buffer_paused = false;
    }
}
// purge log and return its contents
std::vector<std::string> GCodeSender::flush_log()
{
    boost::lock_guard<boost::mutex> lock(this->log_mutex);
    std::vector<std::string> result;
    result.reserve(this->received_lines.size());
    while (!this->received_lines.empty())
    {
        result.push_back(this->received_lines.front());
        this->received_lines.pop();
    }
    return result;
}
std::string GCodeSender::get_extruder_temp() const
{
    boost::lock_guard<boost::mutex> lock(this->log_mutex);
    return this->extruder_temp_str;
}
std::string GCodeSender::get_bed_temp() const
{
    boost::lock_guard<boost::mutex> lock(this->log_mutex);
    return this->bed_temp_str;
}
void GCodeSender::close_port()
{
    this->set_error_state(false);
    boost::system::error_code ec;
    this->port.cancel(ec);
    if (ec)
        this->set_error_state(true);
    this->port.close(ec);
    if (ec)
        this->set_error_state(true);
}
void GCodeSender::set_error_state(bool state)
{
    boost::lock_guard<boost::mutex> lock(this->error_mutex);
    this->has_error = state;
}
bool GCodeSender::error_state() const
{
    boost::lock_guard<boost::mutex> lock(this->error_mutex);
    return this->has_error;
}
void GCodeSender::perform_read()
{
    // read one line
    boost::asio::async_read_until(this->port, this->read_buffer, '\n',
                                  boost::bind(&GCodeSender::handle_read, this, boost::asio::placeholders::error,
                                              boost::asio::placeholders::bytes_transferred));
}
void GCodeSender::handle_read(const boost::system::error_code &err, size_t bytes_transferred)
{
    this->set_error_state(false);
    if (err)
    {
#ifdef __APPLE__
        if (err.value() == 45)
        {
            // OS X bug: http://osdir.com/ml/lib.boost.asio.user/2008-08/msg00004.html
            this->perform_read();
            return;
        }
#endif
        // printf("ERROR: [%d] %s\n", err.value(), err.message().c_str());
        // error can be true even because the serial port was closed.
        // In this case it is not a real error, so ignore.
        if (this->is_open)
        {
            this->close_port();
            this->set_error_state(true);
        }
        return;
    }
    std::istream is(&this->read_buffer);
    std::string line;
    std::getline(is, line);
    if (!line.empty())
    {
#ifdef DEBUG_SERIAL
        debug_stream << "<< " << line << std::endl << std::flush;
#endif
        // note that line might contain \r at its end
        // parse incoming line
        if (!this->is_connected_flag && (boost::starts_with(line, "start") || boost::starts_with(line, "Grbl ") ||
                                         boost::starts_with(line, "ok") || boost::contains(line, "T:")))
        {
            this->is_connected_flag = true;
            {
                boost::lock_guard<boost::mutex> lock(this->queue_mutex);
                this->ready_to_transmit = true;
            }
            this->transmit();
        }
        else if (boost::starts_with(line, "ok"))
        {
            {
                boost::lock_guard<boost::mutex> lock(this->queue_mutex);
                this->ready_to_transmit = true;
            }
            this->transmit();
        }
        else if (boost::istarts_with(line, "resend") // Marlin uses "Resend: "
                 || boost::istarts_with(line, "rs"))
        {
            // extract the first number from line
            boost::algorithm::trim_left_if(line, !boost::algorithm::is_digit());
            size_t requested_seq = boost::lexical_cast<size_t>(line.substr(0, line.find_first_not_of("0123456789")));
#ifdef DEBUG_SERIAL
            debug_stream << "!! line num out of sync: requested_seq = " << requested_seq << ", transmitted_count = " << transmitted_count
                         << ", recent_lines.size = " << recent_lines.size() << std::endl;
#endif
            if (requested_seq > this->transmitted_count - this->recent_lines.size() && requested_seq <= this->transmitted_count)
            {
                {
                    boost::lock_guard<boost::mutex> lock(this->queue_mutex);
                    const auto count_to_resend = this->transmitted_count - requested_seq + 1;
#ifdef DEBUG_SERIAL
                    debug_stream << "!! resending " << count_to_resend << " lines" << std::endl;
#endif
                    // move the unsent lines to urgent_queue
                    this->urgent_queue.insert(this->urgent_queue.begin(), // insert at the beginning
                                          this->recent_lines.begin() + this->recent_lines.size() - count_to_resend,
                                          this->recent_lines.end());
                    // we can empty recent_lines because it's not useful anymore
                    this->recent_lines.clear();
                    // start resending with the requested line number
                    this->transmitted_count = requested_seq - 1;
                    this->ready_to_transmit = true;
                }
                this->transmit();
            }
            else
            {
                printf("Cannot resend %zu (oldest we have is %zu)\n", requested_seq, this->transmitted_count - this->recent_lines.size());
            }
        }
        else if (boost::starts_with(line, "wait"))
        {
            // ignore
        }
        else
        {
            // push any other line into the log
            boost::lock_guard<boost::mutex> lock(this->log_mutex);
            this->received_lines.push(line);
        }
        // parse temperature info
        {
            size_t pos = line.find("T:");
            if (pos != std::string::npos && line.size() > pos + 2)
            {
                // we got temperature info
                boost::lock_guard<boost::mutex> lock(this->log_mutex);
                this->extruder_temp_str = line.substr(pos + 2, line.find_first_not_of("0123456789.", pos + 2) - (pos + 2));
                pos = line.find("B:");
                if (pos != std::string::npos && line.size() > pos + 2)
                {
                    // we got bed temperature info
                    this->bed_temp_str = line.substr(pos + 2, line.find_first_not_of("0123456789.", pos + 2) - (pos + 2));
                }
            }
        }
    }
    this->perform_read();
}
void GCodeSender::send(const std::vector<std::string> &commands, bool priority)
{
    // append commands to queue
    {
        boost::lock_guard<boost::mutex> lock(this->queue_mutex);
        for (std::vector<std::string>::const_iterator cmd = commands.begin(); cmd != commands.end(); ++cmd)
        {
            if (priority)
            {
                this->urgent_queue.push_back(*cmd);
            }
            else
            {
                this->pending_commands.push(*cmd);
            }
        }
    }
    this->transmit();
}
void GCodeSender::send(const std::string &command, bool priority)
{
    // append command to queue
    {
        boost::lock_guard<boost::mutex> lock(this->queue_mutex);
        if (priority)
        {
            this->urgent_queue.push_back(command);
        }
        else
        {
            this->pending_commands.push(command);
        }
    }
    this->transmit();
}
void GCodeSender::transmit()
{
    this->service.post(boost::bind(&GCodeSender::do_transmit, this));
}
void GCodeSender::do_transmit()
{
    boost::lock_guard<boost::mutex> lock(this->queue_mutex);
    // printer is not connected or we're still waiting for the previous ack
    if (!this->ready_to_transmit)
        return;
    std::string line;
    while (!this->urgent_queue.empty() || (!this->pending_commands.empty() && !this->buffer_paused))
    {
        if (!this->urgent_queue.empty())
        {
            line = this->urgent_queue.front();
            this->urgent_queue.pop_front();
        }
        else
        {
            line = this->pending_commands.front();
            this->pending_commands.pop();
        }
        // strip comments
        size_t comment_pos = line.find_first_of(';');
        if (comment_pos != std::string::npos)
            line.erase(comment_pos, std::string::npos);
        boost::algorithm::trim(line);
        // if line is not empty, send it
        if (!line.empty())
            break;
        // if line is empty, process next item in queue
    }
    if (line.empty())
        return;
    // compute full line
    ++this->transmitted_count;
#ifndef DEBUG_SERIAL
    const auto seq_num = this->transmitted_count;
#else
    // In DEBUG_SERIAL mode, test line re-synchronization by sending bad line number 1/4 of the time
    const auto seq_num = std::rand() < RAND_MAX / 4 ? 0 : this->transmitted_count;
#endif
    std::string full_line = "N" + boost::lexical_cast<std::string>(seq_num) + " " + line;
    // calculate checksum
    int checksum = 0;
    for (std::string::const_iterator it = full_line.begin(); it != full_line.end(); ++it)
        checksum = checksum ^ *it;
    // write line to device
    full_line += "*";
    full_line += boost::lexical_cast<std::string>(checksum);
    full_line += "\n";
#ifdef DEBUG_SERIAL
    debug_stream << ">> " << full_line << std::flush;
#endif
    this->recent_lines.push_back(line);
    this->ready_to_transmit = false;
    while (this->recent_lines.size() > MAX_HISTORY)
    {
        this->recent_lines.pop_front();
    }
    // we can't supply boost::asio::buffer(full_line) to async_write() because full_line is on the
    // stack and the buffer would lose its underlying storage causing memory corruption
    std::ostream os(&this->write_buffer);
    os << full_line;
    boost::asio::async_write(this->port, this->write_buffer,
                             boost::bind(&GCodeSender::handle_write, this, boost::asio::placeholders::error,
                                         boost::asio::placeholders::bytes_transferred));
}
void GCodeSender::handle_write(const boost::system::error_code &err, size_t bytes_transferred)
{
    this->set_error_state(false);
    if (err)
    {
        if (this->is_open)
        {
            this->close_port();
            this->set_error_state(true);
        }
        return;
    }
    this->do_transmit();
}
void GCodeSender::set_DTR(bool active)
{
#if defined(_WIN32) && !defined(__SYMBIAN32__)
    boost::asio::serial_port_service::native_handle_type handle = this->port.native_handle();
    if (active)
        EscapeCommFunction(handle, SETDTR);
    else
        EscapeCommFunction(handle, CLRDTR);
#else
    int fd = this->port.native_handle();
    int status;
    ioctl(fd, TIOCMGET, &status);
    if (active)
        status |= TIOCM_DTR;
    else
        status &= ~TIOCM_DTR;
    ioctl(fd, TIOCMSET, &status);
#endif
}
void GCodeSender::reset_device()
{
    set_DTR(false);
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    set_DTR(true);
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    set_DTR(false);
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
}
} // namespace Slic3r

#include "zonelabeltexturebuilder.h"
#include <QPainter>
#include <QPainterPath>
#include <QFont>
#include <QFontMetricsF>
#include "../../core/constants.h"

namespace PlasmaZones {
namespace {
    constexpr int kGridUnit = 8; // Match Kirigami.Units.gridUnit

    QColor borderColFor(const QColor& textCol, const QColor& bgCol)
    {
        const qreal lum = textCol.redF() * 0.299 + textCol.greenF() * 0.587 + textCol.blueF() * 0.114;
        if (lum > 0.5) {
            return QColor::fromRgbF(bgCol.redF() * 0.2, bgCol.greenF() * 0.2,
                                    bgCol.blueF() * 0.2, 0.8);
        }
        return QColor::fromRgbF(1.0 - bgCol.redF() * 0.2, 1.0 - bgCol.greenF() * 0.2,
                                1.0 - bgCol.blueF() * 0.2, 0.8);
    }
} // namespace

QImage ZoneLabelTextureBuilder::build(const QVariantList& zones,
                                      const QSize& dim,
                                      const QColor& textColor,
                                      bool displayNumbers,
                                      const QColor& bgColor,
                                      const QString& fontFamily,
                                      qreal scale,
                                      int weight,
                                      bool italic,
                                      bool underline,
                                      bool strikeout)
{
    if (!displayNumbers || zones.isEmpty() || dim.width() <= 0 || dim.height() <= 0) {
        return QImage();
    }

    QImage canvas(dim, QImage::Format_ARGB32_Premultiplied);
    canvas.fill(Qt::transparent);

    QPainter painter(&canvas);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setRenderHint(QPainter::TextAntialiasing);
    painter.setRenderHint(QPainter::SmoothPixmapTransform);

    const QColor border = borderColFor(textColor, bgColor);
    const QColor fill = textColor;

    for (const QVariant& zoneVar : zones) {
        const QVariantMap zone = zoneVar.toMap();

        const qreal xPos = zone.value(QLatin1String(JsonKeys::X), 0).toDouble();
        const qreal yPos = zone.value(QLatin1String(JsonKeys::Y), 0).toDouble();
        const qreal width = zone.value(QLatin1String(JsonKeys::Width), 0).toDouble();
        const qreal height = zone.value(QLatin1String(JsonKeys::Height), 0).toDouble();
        const int number = zone.value(QLatin1String(JsonKeys::ZoneNumber), 0).toInt();

        if (width <= 0 || height <= 0) {
            continue;
        }

        const QString label = QString::number(number);
        const qreal fontSize = qMax(static_cast<qreal>(kGridUnit), qMin(width, height) * 0.25) * scale;

        QFont font;
        if (!fontFamily.isEmpty()) {
            font.setFamily(fontFamily);
        }
        font.setPixelSize(static_cast<int>(fontSize));
        font.setWeight(static_cast<QFont::Weight>(qBound(100, weight, 900)));
        font.setItalic(italic);

        const QRectF rect(xPos, yPos, width, height);
        const QPointF center = rect.center();

        QPainterPath path;
        path.addText(0, 0, font, label);

        const QRectF textBounds = path.boundingRect();
        const qreal offsetX = center.x() - textBounds.center().x();
        const qreal offsetY = center.y() - textBounds.center().y();
        path.translate(offsetX, offsetY);

        const QPen borderPen(border, 2.0, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
        painter.setPen(borderPen);
        painter.setBrush(Qt::NoBrush);
        painter.drawPath(path);

        painter.setPen(Qt::NoPen);
        painter.setBrush(fill);
        painter.drawPath(path);

        if (underline || strikeout) {
            const QFontMetricsF metrics(font);
            const qreal thickness = qMax(1.0, metrics.lineWidth());
            const qreal baselineY = offsetY;
            const qreal startX = textBounds.left() + offsetX;
            const qreal length = textBounds.width();

            auto drawLine = [&](qreal offset) {
                const QRectF lineRect(startX, baselineY + offset - thickness / 2.0,
                                      length, thickness);
                QPainterPath linePath;
                linePath.addRect(lineRect);
                painter.setPen(borderPen);
                painter.setBrush(Qt::NoBrush);
                painter.drawPath(linePath);
                painter.setPen(Qt::NoPen);
                painter.setBrush(fill);
                painter.drawPath(linePath);
            };

            if (underline) {
                drawLine(metrics.underlinePos());
            }
            if (strikeout) {
                drawLine(-metrics.strikeOutPos());
            }
        }
    }

    painter.end();
    return canvas;
}
} // namespace PlasmaZones

#include "quadrants/util/testing.h"
#include "quadrants/util/bit.h"

namespace quadrants {
namespace bit {

Bitset::Bitset() {
}

Bitset::Bitset(int n) {
  // Adjust n to be multiple of bits per word
  if (n % BITS_PER_WORD != 0) {
    n += BITS_PER_WORD - n % BITS_PER_WORD;
  }
  data_ = std::vector<word_t>(n / BITS_PER_WORD, 0);
}

std::size_t Bitset::size() const {
  return data_.size() * BITS_PER_WORD;
}

void Bitset::reset() {
  for (auto &word : data_) {
    word = 0;
  }
}

void Bitset::flip(int position) {
  data_[position / BITS_PER_WORD] ^= ((word_t)1) << (position % BITS_PER_WORD);
}

bool Bitset::any() const {
  for (const auto &val : data_) {
    if (val)
      return true;
  }
  return false;
}

bool Bitset::none() const {
  return !any();
}

Bitset::reference Bitset::operator[](int position) {
  return reference(data_, position);
}

Bitset &Bitset::operator&=(const Bitset &other) {
  const int count = data_.size();
  QD_ASSERT(count == other.data_.size());
  for (int idx = 0; idx < count; idx++) {
    data_[idx] &= other.data_[idx];
  }
  return *this;
}

Bitset Bitset::operator&(const Bitset &other) const {
  Bitset result = *this;
  result &= other;
  return result;
}

Bitset &Bitset::operator|=(const Bitset &other) {
  const int count = data_.size();
  QD_ASSERT(count == other.data_.size());
  for (int idx = 0; idx < count; idx++) {
    data_[idx] |= other.data_[idx];
  }
  return *this;
}

Bitset Bitset::operator|(const Bitset &other) const {
  Bitset result = *this;
  result |= other;
  return result;
}

Bitset &Bitset::operator^=(const Bitset &other) {
  const int count = data_.size();
  QD_ASSERT(count == other.data_.size());
  for (int idx = 0; idx < count; idx++) {
    data_[idx] ^= other.data_[idx];
  }
  return *this;
}

Bitset Bitset::operator~() const {
  Bitset result(size());
  const int count = data_.size();
  for (int idx = 0; idx < count; idx++) {
    result.data_[idx] = ~data_[idx];
  }
  return result;
}

int Bitset::find_first_one() const {
  return lower_bound(0);
}

int Bitset::lower_bound(int x) const {
  const int count = data_.size();
  if (x >= count * BITS_PER_WORD) {
    return -1;
  }
  if (x < 0) {
    x = 0;
  }
  int idx = x / BITS_PER_WORD;
  if (x % BITS_PER_WORD != 0) {
    if (auto test = data_[idx] & (WORD_MASK ^ ((1ULL << (x % BITS_PER_WORD)) - 1))) {
      return idx * BITS_PER_WORD + log2int(lowbit(test));
    }
    idx++;
  }
  for (; idx < count; idx++) {
    if (data_[idx]) {
      return idx * BITS_PER_WORD + log2int(lowbit(data_[idx]));
    }
  }
  return -1;
}

std::vector<int> Bitset::or_eq_get_update_list(const Bitset &other) {
  const int count = data_.size();
  QD_ASSERT(count == other.data_.size());
  std::vector<int> updates;
  for (int idx = 0; idx < count; idx++) {
    auto change = other.data_[idx] & ~data_[idx];
    if (change) {
      data_[idx] |= change;
      for (int j = 0; j < BITS_PER_WORD; j++) {
        if ((change >> j) & 1) {
          updates.push_back((idx * BITS_PER_WORD) | j);
        }
      }
    }
  }
  return updates;
}

Bitset::reference::reference(std::vector<word_t> &vec, int pos)
    : pos_(&vec[pos / BITS_PER_WORD]), digit_(((word_t)1) << (pos % BITS_PER_WORD)) {
}

Bitset::reference::operator bool() const {
  return *pos_ & digit_;
}

bool Bitset::reference::operator~() const {
  return ~*pos_ & digit_;
}

Bitset::reference &Bitset::reference::operator=(bool value) {
  if (value)
    *pos_ |= digit_;
  else
    *pos_ &= WORD_MASK ^ digit_;
  return *this;
}

Bitset::reference &Bitset::reference::operator=(
    const Bitset::reference &other) {
  *this = bool(other);
  return *this;
}

Bitset::reference &Bitset::reference::flip() {
  *pos_ ^= digit_;
  return *this;
}

std::ostream &operator<<(std::ostream &os, const Bitset &b) {
  for (auto &val : b.data_)
    for (int j = 0; j < Bitset::BITS_PER_WORD; j++)
      os << ((val >> j) & 1 ? '1' : '0');
  return os;
}

