// Helper function to count rows in the database using DuckDB
auto CountDatabaseRows(const std::filesystem::path& dbFile, const std::string& query) -> int64_t {
  duckdb_database   databaseHandle = nullptr;
  duckdb_connection connectionHandle = nullptr;

  if (duckdb_open(dbFile.string().c_str(), &databaseHandle) != DuckDBSuccess) {
    return -1;
  }

  if (duckdb_connect(databaseHandle, &connectionHandle) != DuckDBSuccess) {
    duckdb_close(&databaseHandle);
    return -1;
  }

  int64_t       rowCount = -1;
  duckdb_result queryResult;

  if (duckdb_query(connectionHandle, query.c_str(), &queryResult) == DuckDBSuccess) {
    rowCount = duckdb_row_count(&queryResult) > 0 
               ? duckdb_value_int64(&queryResult, 0, 0) 
               : 0;
  }

  duckdb_destroy_result(&queryResult);
  duckdb_disconnect(&connectionHandle);
  duckdb_close(&databaseHandle);

  return rowCount;
}

// Wait for import process to finish with timeout and polling
void AwaitImportCompletion(AlbumBackend& backend, int maxWaitMs = 30000) {
  QSignalSpy spy(&backend, &AlbumBackend::ImportStateChanged);
  const int  pollingInterval = 200;
  int        timeElapsed = 0;

  while (backend.ImportRunning() && timeElapsed < maxWaitMs) {
    spy.wait(pollingInterval);
    timeElapsed += pollingInterval;
  }

  ProcessEvents(600);
}

// Create a new project and load it into the backend
auto InitializeNewProject(AlbumBackend& backend, const std::filesystem::path& dbPath,
                          const std::filesystem::path& metaPath) -> bool {
  {
    ProjectService projectService(dbPath, metaPath, ProjectOpenMode::kCreateNew);
    projectService.SaveProject(metaPath);
  }

  QSignalSpy projectChangeSpy(&backend, &AlbumBackend::ProjectChanged);

  if (!backend.LoadProject(PathToQString(metaPath))) {
    return false;
  }

  WaitForSignal(projectChangeSpy, 15000);
  ProcessEvents(500);

  return backend.ServiceReady();
}

TEST_F(DeleteTests, DeleteImages_RemovesImageAndRelatedRows) {
  sl_element_id_t removedElementId = 0;
  image_id_t      removedImageId   = 0;
  QVariantMap     deleteResult;
  int             visibleCountAfterDeletion = -1;

  {
    AlbumBackend backend;

    ASSERT_TRUE(InitializeNewProject(backend, db_path_, meta_path_));

    auto testImages = CollectRawTestImages("airplane", 1);
    if (testImages.empty()) {
      GTEST_SKIP() << "No RAW images available in raw/airplane/";
    }

    backend.StartImport(PathsToQStringList(testImages));
    AwaitImportCompletion(backend);

    ASSERT_FALSE(backend.Thumbnails().isEmpty());

    const QVariantMap firstThumbnail = backend.Thumbnails().front().toMap();
    removedElementId = static_cast<sl_element_id_t>(firstThumbnail.value("elementId").toUInt());
    removedImageId   = static_cast<image_id_t>(firstThumbnail.value("imageId").toUInt());

    ASSERT_NE(removedElementId, 0u);
    ASSERT_NE(removedImageId, 0u);

    // Open editor to ensure pipeline/history entries are created
    backend.OpenEditor(static_cast<uint>(removedElementId), static_cast<uint>(removedImageId));
    ProcessEvents(400);

    QVariantList deletionTargets;
    deletionTargets.push_back(QVariantMap{{"elementId", static_cast<uint>(removedElementId)},
                                          {"imageId", static_cast<uint>(removedImageId)}});

    deleteResult = backend.DeleteImages(deletionTargets);
    ProcessEvents(500);

    visibleCountAfterDeletion = backend.ShownCount();
  }

  EXPECT_TRUE(deleteResult.value("success").toBool());
  EXPECT_EQ(deleteResult.value("deletedCount").toInt(), 1);
  EXPECT_EQ(deleteResult.value("failedCount").toInt(), 0);
  EXPECT_EQ(visibleCountAfterDeletion, 0);

  // Verify DB cleanup
  EXPECT_EQ(CountDatabaseRows(db_path_, std::format("SELECT COUNT(*) FROM Image WHERE id={}", removedImageId)), 0);
  EXPECT_EQ(CountDatabaseRows(db_path_, std::format("SELECT COUNT(*) FROM FileImage WHERE file_id={}", removedElementId)), 0);
  EXPECT_EQ(CountDatabaseRows(db_path_, std::format("SELECT COUNT(*) FROM EditHistory WHERE file_id={}", removedElementId)), 0);
  EXPECT_EQ(CountDatabaseRows(db_path_, std::format("SELECT COUNT(*) FROM PipelineParam WHERE file_id={}", removedElementId)), 0);
}

