class HttpWorker
{
private:
  jobject m_instance;
  jclass m_classRef;
public:
  HttpWorker(std::string const & url, downloader::IHttpThreadCallback & callback, int64_t startOffset, int64_t endOffset,
             int64_t totalSize, std::string const & postData)
  {
    JNIEnv * env = jni::GetEnv();
    static jclass const cls = jni::GetGlobalClassRef(env, "app/organicmaps/sdk/downloader/ChunkTask");
    m_classRef = cls;
    // public ChunkTask(long httpCallbackID, String url, long beg, long end,
    //                  long expectedFileSize, byte[] postBody, String userAgent)
    static jmethodID const constructorId = jni::GetConstructorID(env, cls, "(JLjava/lang/String;JJJ[B)V");
    static jmethodID const executeMethodId = env->GetMethodID(cls, "start", "()V");
    jni::TScopedLocalByteArrayRef postDataArray(env, nullptr);
    jsize const postDataLength = static_cast<jsize>(postData.size());
    if (postDataLength)
    {
      postDataArray.reset(env->NewByteArray(postDataLength));
      env->SetByteArrayRegion(postDataArray.get(), 0, postDataLength, reinterpret_cast<jbyte const *>(postData.c_str()));
    }
    jni::TScopedLocalRef jUrl(env, jni::ToJavaString(env, url.c_str()));
    jni::TScopedLocalRef localInstance(
        env, env->NewObject(cls, constructorId, reinterpret_cast<jlong>(&callback), jUrl.get(), static_cast<jlong>(startOffset),
                            static_cast<jlong>(endOffset), static_cast<jlong>(totalSize), postDataArray.get()));
    m_instance = env->NewGlobalRef(localInstance.get());
    ASSERT(m_instance, ());
    env->CallVoidMethod(m_instance, executeMethodId);
  }
  ~HttpWorker()
  {
    JNIEnv * env = jni::GetEnv();
    static jmethodID const abortMethodId = env->GetMethodID(m_classRef, "cancel", "(Z)Z");
    env->CallBooleanMethod(m_instance, abortMethodId, false);
    env->DeleteGlobalRef(m_instance);
  }
};

namespace downloader
{
HttpWorker * CreateNativeHttpWorker(std::string const & url, downloader::IHttpThreadCallback & callback, int64_t start,
                                    int64_t end, int64_t size, std::string const & postData)
{
  return new HttpWorker(url, callback, start, end, size, postData);
}

void DeleteNativeHttpWorker(HttpWorker * worker)
{
  delete worker;
}
}  // namespace downloader

extern "C"
{
JNIEXPORT jboolean JNICALL Java_app_organicmaps_sdk_downloader_ChunkTask_nativeOnWrite(JNIEnv * env, jclass clazz,
                                                                                       jlong callbackPtr, jlong offset,
                                                                                       jbyteArray buffer, jlong length)
{
  downloader::IHttpThreadCallback * cb = reinterpret_cast<downloader::IHttpThreadCallback *>(callbackPtr);
  jbyte * data = env->GetByteArrayElements(buffer, 0);
  ASSERT(data, ());
  bool success = false;
  try
  {
    success = cb->OnWrite(offset, data, static_cast<jsize>(length));
  }
  catch (std::exception const & e)
  {
    LOG(LERROR, ("Error writing chunk:", e.what()));
  }
  env->ReleaseByteArrayElements(buffer, data, 0);
  return success;
}

JNIEXPORT void JNICALL Java_app_organicmaps_sdk_downloader_ChunkTask_nativeOnFinish(JNIEnv * env, jclass clazz,
                                                                                    jlong callbackPtr,
                                                                                    jlong statusCode, jlong startPos,
                                                                                    jlong endPos)
{
  downloader::IHttpThreadCallback * cb = reinterpret_cast<downloader::IHttpThreadCallback *>(callbackPtr);
  cb->OnFinish(static_cast<long>(statusCode), startPos, endPos);
}
}  // extern "C"

