MultiSfxTester::MultiSfxTester(QWidget* parent) :
    QDialog(parent),
    ui(new Ui::MultiSfxTester)
{
    Q_ASSERT(!s_instance); // Only one instance allowed!
    ui->setupUi(this);
    s_instance = this;
    Mix_ChannelFinished(&sfxFinished);
    QObject::connect(&m_playTimer,
                     &QTimer::timeout,
                     this,
                     &MultiSfxTester::triggerRandomPlay);
#ifndef HAS_QRANDOM_GENERATOR
    qsrand((uint)std::time(nullptr));
#endif
}

MultiSfxTester::~MultiSfxTester()
{
    Mix_ChannelFinished(nullptr);
    delete ui;
    s_instance = nullptr;
}

MultiSfxItem *MultiSfxTester::addSfx(QString filePath)
{
    auto* item = new MultiSfxItem(filePath, this);
    m_items.append(item);
    QObject::connect(item,
                     &MultiSfxItem::wannaClose,
                     this,
                     &MultiSfxTester::handleItemClose);
    auto* layout = qobject_cast<QVBoxLayout*>(ui->sfxList->widget()->layout());
    layout->insertWidget(layout->count() - 1, item);
    return item;
}

void MultiSfxTester::refreshAllItems()
{
    for(auto& item : m_items)
        item->reOpenSfx();
}

void MultiSfxTester::changeEvent(QEvent* e)
{
    QDialog::changeEvent(e);
    switch(e->type())
    {
    case QEvent::LanguageChange:
        ui->retranslateUi(this);
        break;
    default:
        break;
    }
}

void MultiSfxTester::closeEvent(QCloseEvent*)
{
    clearAllItems();
    ui->randomPlaying->setChecked(false);
    on_randomPlaying_clicked(false);
}

void MultiSfxTester::dropEvent(QDropEvent* e)
{
    this->raise();
    this->setFocus(Qt::ActiveWindowFocusReason);
    for(const QUrl& url : e->mimeData()->urls())
    {
        const QString& fileName = url.toLocalFile();
        addSfx(fileName);
    }
}

void MultiSfxTester::dragEnterEvent(QDragEnterEvent* e)
{
    if(e->mimeData()->hasUrls())
        e->acceptProposedAction();
}

void MultiSfxTester::notifyChannelFinished(int channelNumber)
{
    for(auto& item : m_items)
        item->sfxStoppedHook(channelNumber);
}

void MultiSfxTester::on_openSfx_clicked()
{
    QString file = QFileDialog::getOpenFileName(this,
                                                tr("Open SFX file"),
                                                (m_lastPath.isEmpty() ?
                                                QApplication::applicationDirPath() :
                                                m_lastPath),
                                                "All (*.*)", nullptr,
                                                c_fileDialogOptions);
    if(file.isEmpty())
        return;
    m_lastPath = file;
    addSfx(file);
}

void MultiSfxTester::on_randomPlaying_clicked(bool checked)
{
    if(checked)
    {
        m_playTimer.start(200);
        ui->randomPlaying->setText(tr("Stop random"));
    }
    else
    {
        m_playTimer.stop();
        ui->randomPlaying->setText(tr("Play random"));
    }
}

void MultiSfxTester::triggerRandomPlay()
{
    m_playTimer.setInterval(100 + (XX_QRAND() % ui->maxRandomDelay->value()));
    if(m_items.isEmpty())
        return;
    int count = m_items.size();
    int index = XX_QRAND() % count;
    m_items[index]->on_play_clicked();
}

void MultiSfxTester::handleItemClose(MultiSfxItem* item)
{
    auto* layout = qobject_cast<QVBoxLayout*>(ui->sfxList->widget()->layout());
    layout->removeWidget(item);
    m_items.removeAll(item);
    item->on_stop_clicked();
    item->deleteLater();
}

void MultiSfxTester::on_saveList_clicked()
{
    int ret = QMessageBox::question(this,
                                    tr("Save list?"),
                                    tr("You are trying to save the SFX list for future use. "
                                       "If you saved the SFX list previously, it will be overriden. Do you want to save the SFX list?"),
                                    QMessageBox::Yes|QMessageBox::No);
    if(ret != QMessageBox::Yes)
        return;
    QSettings setup;
    setup.beginGroup("sfx-test-list");
    setup.beginWriteArray("sfx", m_items.size());
    int idx = 0;
    for(auto* item : m_items)
    {
        setup.setArrayIndex(idx++);
        setup.setValue("path", item->path());
        setup.setValue("channel", item->channel());
        setup.setValue("fade-delay", item->fadeDelay());
        setup.setValue("init-volume", item->initVolume());
    }
    setup.endArray();
    setup.endGroup();
    setup.sync();
    QMessageBox::information(this,
                             tr("SFX list has been saved"),
                             tr("The SFX list has been saved (%1 entries)").arg(m_items.size()),
                             QMessageBox::Ok);
}

void MultiSfxTester::on_loadList_clicked()
{
    clearAllItems();
    QSettings setup;
    setup.beginGroup("sfx-test-list");
    int size = setup.beginReadArray("sfx");
    for(int i = 0; i < size; ++i)
    {
        setup.setArrayIndex(i);
        auto path = setup.value("path").toString();
        auto ch = setup.value("channel", -1).toInt();
        auto fade = setup.value("fade-delay", 1000).toInt();
        auto ivol = setup.value("init-volume", 128).toInt();
        if(path.isEmpty())
            continue;
        auto *item = addSfx(path);
        if(item)
        {
            item->setChannel(ch);
            item->setFadeDelay(fade);
            item->setInitVolume(ivol);
        }
    }
    setup.endArray();
    setup.endGroup();
}

void MultiSfxTester::clearAllItems()
{
    for(auto* item : m_items)
    {
        auto* layout = qobject_cast<QVBoxLayout*>(ui->sfxList->widget()->layout());
        layout->removeWidget(item);
        item->on_stop_clicked();
        item->deleteLater();
    }
    m_items.clear();
}

void MultiSfxTester::sfxFinished(int numChannel)
{
    if(s_instance)
        QMetaObject::invokeMethod(s_instance,
                                  "notifyChannelFinished",
                                  Qt::QueuedConnection,
                                  Q_ARG(int, numChannel));
}

