using namespace small_gicp;

class RegistrationHelperTest : public testing::Test, public testing::WithParamInterface<const char*> {
public:
  void SetUp() override {
    // Load point clouds
    reference_cloud = std::make_shared<PointCloud>(read_ply("data/target.ply"));
    moving_cloud = std::make_shared<PointCloud>(read_ply("data/source.ply"));

    std::ifstream transform_file("data/T_target_source.txt");
    if (!transform_file) {
      std::cerr << "error: failed to open T_target_source.txt" << std::endl;
    }

    for (int row = 0; row < 4; ++row) {
      for (int col = 0; col < 4; ++col) {
        transform_file >> ground_truth_transform(row, col);
      }
    }
  }

  bool verify_transformation(const Eigen::Isometry3d& T1, const Eigen::Isometry3d& T2) {
    const Eigen::Isometry3d relative = T1.inverse() * T2;
    const double rotation_error = Eigen::AngleAxisd(relative.linear()).angle();
    const double translation_error = relative.translation().norm();

    const double rotation_threshold = 2.5 * M_PI / 180.0;
    const double translation_threshold = 0.2;

    EXPECT_NEAR(rotation_error, 0.0, rotation_threshold);
    EXPECT_NEAR(translation_error, 0.0, translation_threshold);

    return rotation_error < rotation_threshold && translation_error < translation_threshold;
  }

protected:
  PointCloud::Ptr reference_cloud;     ///< Reference (target) point cloud
  PointCloud::Ptr moving_cloud;        ///< Moving (source) point cloud  
  Eigen::Isometry3d ground_truth_transform;  ///< Known transformation between clouds
};

// Basic file loading verification
TEST_F(RegistrationHelperTest, FileLoadingVerification) {
  EXPECT_FALSE(reference_cloud->empty());
  EXPECT_FALSE(moving_cloud->empty());
}

// Test preprocessing with empty input
TEST_F(RegistrationHelperTest, EmptyPreprocessing) {
  auto empty_cloud = std::make_shared<PointCloud>();
  auto [processed_cloud, kdtree] = preprocess_points(*empty_cloud, 0.1, 10, 1);

  EXPECT_TRUE(processed_cloud);
  EXPECT_TRUE(kdtree);
  EXPECT_EQ(processed_cloud->size(), 0);
}

// Test preprocessing with actual data under different thread counts
TEST_F(RegistrationHelperTest, PreprocessingValidation) {
  const std::vector<int> thread_counts = {1, 2};

  for (int threads : thread_counts) {
    auto [processed, tree] = preprocess_points(*reference_cloud, 0.1, 10, threads);

    EXPECT_TRUE(processed) << "Thread count: " << threads;
    EXPECT_TRUE(tree) << "Thread count: " << threads;
    EXPECT_GT(processed->size(), 1000) << "Thread count: " << threads;
    EXPECT_LT(processed->size(), reference_cloud->size()) << "Thread count: " << threads;

    // Alternative overload test
