  } else if (method == "PLANE_ICP") {
    config.type = RegistrationSetting::PLANE_ICP;
  } else if (method == "GICP") {
    config.type = RegistrationSetting::GICP;
  } else if (method == "VGICP") {
    config.type = RegistrationSetting::VGICP;
  } else {
    std::cerr << "error: unknown registration method " << method << std::endl;
  }

  RegistrationResult result;

  // Preprocess both clouds
  auto [ref_processed, ref_tree] = preprocess_points(*reference_cloud, 0.1, 10, 1);
  auto [mov_processed, mov_tree] = preprocess_points(*moving_cloud, 0.1, 10, 1);

  // Forward alignment
  if (method != "VGICP") {
    result = align(*ref_processed, *mov_processed, *ref_tree, Eigen::Isometry3d::Identity(), config);
