#include "humanoid_controllers/humanoidController.h"
#include <thread>
using TimeDuration = std::chrono::duration<double>;
using HighResClock = std::chrono::high_resolution_clock;
bool is_paused = false;

void pauseHandler(const std_msgs::Bool::ConstPtr &msg)
{
    is_paused = msg->data;
    std::cerr << "Pause state updated: " << is_paused << std::endl;
}

int main(int argc, char **argv)
{
    ros::Duration elapsed_time_;
    ros::init(argc, argv, "humanoid_controller_node");
    ros::NodeHandle node_handle;
    humanoid_controller::HybridJointInterface *robot_interface;

    // Subscribe to pause flag topic
    ros::Subscriber pause_subscriber = node_handle.subscribe<std_msgs::Bool>("pauseFlag", 1, pauseHandler);

    humanoid_controller::humanoidCheaterController controller_instance;
    if (!controller_instance.init(robot_interface, node_handle))
    {
        ROS_ERROR("Failed to initialize the humanoid controller!");
        return -1;
    }

    auto initial_time = HighResClock::now();
    auto ros_start_time = ros::Time::now();
    controller_instance.starting(ros_start_time);
    auto previous_time = initial_time;

    // Launch background spinner thread
    std::thread spinner([]()
                        { ros::spin(); });
    spinner.detach();

    double loop_rate = 500.0; // Default 500 Hz
    node_handle.getParam("/wbc_frequency", loop_rate);
    std::cout << "WBC control frequency: " << loop_rate << std::endl;

    ros::Rate control_loop(loop_rate);
    struct timespec target_time;
    clock_gettime(CLOCK_MONOTONIC, &target_time);

    while (ros::ok())
    {
        if (!is_paused)
        {
            const auto current_time = HighResClock::now();

            // Calculate elapsed time since last iteration
            TimeDuration duration_span = std::chrono::duration_cast<TimeDuration>(current_time - previous_time);
            elapsed_time_ = ros::Duration(duration_span.count());
            previous_time = current_time;

            // Execute control update
            controller_instance.update(ros::Time::now(), elapsed_time_);

            // Maintain timing using absolute sleep
            const auto pre_sleep = HighResClock::now();
            target_time.tv_sec += (target_time.tv_nsec + static_cast<long>(1.0 / loop_rate * 1e9)) / 1e9;
            target_time.tv_nsec = (int)(target_time.tv_nsec + static_cast<long>(1.0 / loop_rate * 1e9)) % (int)1e9;
            clock_nanosleep(CLOCK_MONOTONIC, TIMER_ABSTIME, &target_time, NULL);

            // Monitor for timing violations
            const auto actual_cycle = std::chrono::duration_cast<std::chrono::milliseconds>(HighResClock::now() - current_time).count();
            if (actual_cycle > 1000)
            {
                ROS_INFO_STREAM("Cycle time exceeded 1 second: " << actual_cycle << "ms");
                const auto actual_sleep = std::chrono::duration_cast<std::chrono::milliseconds>(HighResClock::now() - pre_sleep).count();
                ROS_INFO_STREAM("Actual sleep duration: " << actual_sleep << "ms");
                const auto computation_time = std::chrono::duration_cast<std::chrono::milliseconds>(pre_sleep - current_time).count();
                ROS_INFO_STREAM("Computation time: " << computation_time << "ms");
            }
        }
    }

    return 0;
}

