bool IsUsingStormRenderer(HdRenderIndex const* renderIdx)
{
    return dynamic_cast<HdStRenderDelegate*>(renderIdx->GetRenderDelegate()) != nullptr;
}

TfToken DetermineRenderingBackend(HdRenderIndex const* renderIdx)
{
    HdDriverVector const& driverList = renderIdx->GetDrivers();
    for (HdDriver* drv : driverList)
    {
        if ((drv->name == HgiTokens->renderDriver) && drv->driver.IsHolding<Hgi*>())
        {
            return drv->driver.UncheckedGet<Hgi*>()->GetAPIName();
        }
    }
    return HgiTokens->OpenGL;
}

void ConfigureBlendStateForMaterialTag(TfToken const& materialTag, HdxRenderTaskParams& params)
{
    if (materialTag == HdStMaterialTagTokens->additive)
    {
        // Additive blending: no depth sorting required
        params.blendEnable = true;

        // Color blending: assume pre-multiplied alpha from shader output.
        params.blendColorOp        = HdBlendOpAdd;
        params.blendColorSrcFactor = HdBlendFactorOne;
        params.blendColorDstFactor = HdBlendFactorOne;

        // Alpha blending: keep framebuffer alpha unchanged (alpha = 0 expected).
        params.blendAlphaOp        = HdBlendOpAdd;
        params.blendAlphaSrcFactor = HdBlendFactorZero;
        params.blendAlphaDstFactor = HdBlendFactorOne;

        // Disable depth writes for additive pass
        params.depthMaskEnable = false;

        // Disable MSAA-based alpha-to-coverage for additive blending
        params.enableAlphaToCoverage = false;
    }
#if defined(DRAW_ORDER)
    else if (materialTag == HdStMaterialTagTokens->draworder)
    {
        // Standard alpha blending: result = src * srcAlpha + dst * (1 - srcAlpha)
        params.blendEnable         = true;
        params.blendColorOp        = HdBlendOpAdd;
        params.blendColorSrcFactor = HdBlendFactorSrcAlpha;
        params.blendColorDstFactor = HdBlendFactorOneMinusSrcAlpha;
        params.blendAlphaOp        = HdBlendOpAdd;
        params.blendAlphaSrcFactor = HdBlendFactorOne;
        params.blendAlphaDstFactor = HdBlendFactorZero;

        // Depth mask disabled for draw order pass
        params.depthMaskEnable = false;
        params.enableAlphaToCoverage = false;
    }
#endif
    else if (materialTag == HdStMaterialTagTokens->defaultMaterialTag ||
             materialTag == HdStMaterialTagTokens->masked)
    {
        // Default and masked tags share blend state; distinction is in shader behavior.
        params.blendEnable           = false;
        params.depthMaskEnable       = true;
        params.enableAlphaToCoverage = true;
    }
}

SdfPath ConstructRenderTaskPath(SdfPath const& controllerId, TfToken const& tag)
{
    TfToken leafName = ExtractRenderTaskLeafName(tag);
    return controllerId.AppendChild(leafName);
}

TfToken ExtractRenderTaskLeafName(TfToken const& tag)
{
    std::string nameBuffer = TfStringPrintf("renderTask_%s", tag.GetText());
    std::replace(nameBuffer.begin(), nameBuffer.end(), ':', '_');
    return TfToken(nameBuffer);
}

SdfPath CreateAovIdentifier(SdfPath const& parentPath, TfToken const& aovName)
{
    std::string sanitized = "aov_" + TfMakeValidIdentifier(aovName.GetString());
    return parentPath.AppendChild(TfToken(sanitized));
}

HdRprimCollection BuildDefaultCollection(
    HVT_NS::BasicLayerParams const* layerConfig, TfToken const& materialTag)
{
    HdRprimCollection collection = layerConfig->collection;
    collection.SetMaterialTag(materialTag);
    return collection;
}

bool ShouldClearRenderTargets(TaskManager const& taskMgr,
    TfToken const& taskLabel,
    RenderBufferSettingsProvider const& bufferSettings)
{
    bool firstTask = (RetrieveFirstRenderTask(taskMgr) == taskLabel);

    if (firstTask && bufferSettings.IsProgressiveRenderingEnabled())
    {
        firstTask = bufferSettings.GetAovParamCache().hasNoAovInputs;
    }

    return firstTask;
}

bool SupportsMultisampleAntiAliasing(TfToken const& materialTag)
{
    // OIT and volume rendering use per-pixel buffers only — MSAA not compatible.
    return (materialTag != HdStMaterialTagTokens->translucent &&
            materialTag != HdStMaterialTagTokens->volume);
}

TfToken RetrieveFirstRenderTask(const TaskManager& taskMgr)
{
    SdfPathVector taskPaths;
    taskMgr.GetTaskPaths(TaskFlagsBits::kRenderTaskBit, true, taskPaths);
    if (!taskPaths.empty())
    {
        return taskPaths[0].GetNameToken();
    }
    return TfToken(); // empty token
}

HdRenderPassAovBindingVector PrepareAovBindings(TaskManager const& taskMgr,
    TfToken const& taskLabel,
    RenderBufferSettingsProvider const& bufferSettings)
{
    hvt::AovParams const& aovData = bufferSettings.GetAovParamCache();
    bool const shouldClear = ShouldClearRenderTargets(taskMgr, taskLabel, bufferSettings);

    HdRenderPassAovBindingVector bindings =
        shouldClear ? aovData.aovBindingsClear : aovData.aovBindingsNoClear;

    // Adjust clear values per AOV buffer ID as needed.
    for (size_t idx = 0; idx < bindings.size(); ++idx)
    {
        auto found = aovData.outputClearValues.find(bindings[idx].renderBufferId);
        if (found != aovData.outputClearValues.end())
        {
            bindings[idx].clearValue = shouldClear ? found->second : VtValue();
        }
    }

    return bindings;
}

