//****************************************************************************
// Auto disabling functionality
void dInternalHandleAutoDisabling(dxWorld *world, dReal timestep)
{
    dxBody *currentBody;
    for (currentBody = world->firstbody; currentBody; currentBody = (dxBody*)currentBody->next) {
        // Skip unless body is enabled and has auto-disable flag set
        if ((currentBody->flags & (dxBodyAutoDisable | dxBodyDisabled)) != dxBodyAutoDisable) continue;

        // Check if the body is idle
        int isIdle = 1; // Assume idle initially
        dReal linearSpeedSq = dDOT(currentBody->lvel, currentBody->lvel);
        if (linearSpeedSq > currentBody->adis.linear_threshold) {
            isIdle = 0; // Moving too fast to be idle
        }
        else {
            dReal angularSpeedSq = dDOT(currentBody->avel, currentBody->avel);
            if (angularSpeedSq > currentBody->adis.angular_threshold) {
                isIdle = 0; // Rotating too fast to be idle
            }
        }

        // Update idle counters based on state
        if (isIdle) {
            currentBody->adis_stepsleft--;
            currentBody->adis_timeleft -= timestep;
        }
        else {
            currentBody->adis_stepsleft = currentBody->adis.idle_steps;
            currentBody->adis_timeleft = currentBody->adis.idle_time;
        }

        // Disable body if idle duration exceeds thresholds
        if (currentBody->adis_stepsleft < 0 && currentBody->adis_timeleft < 0) {
            currentBody->flags |= dxBodyDisabled;
        }
    }
}

//****************************************************************************
// Sine cardinal function: sin(x)/x with special handling near zero
static inline dReal sinc(dReal angle)
{
    // Use Taylor series for small angles to avoid singularity at 0
    if (dFabs(angle) < 1.0e-4) {
        return REAL(1.0) - angle * angle * REAL(0.166666666666666666667);
    }
    else {
        return dSin(angle) / angle;
    }
}

//****************************************************************************
// Apply body movement over a time step
void dxStepBody(dxBody *body, dReal h)
{
    int index;

    // Update position using linear velocity
    for (index = 0; index < 3; index++) {
        body->pos[index] += h * body->lvel[index];
    }

    if (body->flags & dxBodyFlagFiniteRotation) {
        dVector3 rotationalVector; // Infinitesimal rotation vector
        dQuaternion quaternion;    // Quaternion for finite rotation

        if (body->flags & dxBodyFlagFiniteRotationAxis) {
            // Decompose angular velocity into components parallel and perpendicular to rotation axis
            dVector3 finiteRotationVector;
            dReal projection = dDOT(body->finite_rot_axis, body->avel);
            finiteRotationVector[0] = body->finite_rot_axis[0] * projection;
            finiteRotationVector[1] = body->finite_rot_axis[1] * projection;
            finiteRotationVector[2] = body->finite_rot_axis[2] * projection;

            rotationalVector[0] = body->avel[0] - finiteRotationVector[0];
            rotationalVector[1] = body->avel[1] - finiteRotationVector[1];
            rotationalVector[2] = body->avel[2] - finiteRotationVector[2];

            // Create finite rotation quaternion
            h *= REAL(0.5);
            dReal halfAngle = projection * h;
            quaternion[0] = dCos(halfAngle);
            dReal scale = sinc(halfAngle) * h;
            quaternion[1] = finiteRotationVector[0] * scale;
            quaternion[2] = finiteRotationVector[1] * scale;
            quaternion[3] = finiteRotationVector[2] * scale;
        }
        else {
            // Full finite rotation without fixed axis
            dReal angularMagnitude = dSqrt(body->avel[0]*body->avel[0] + 
                                           body->avel[1]*body->avel[1] + 
                                           body->avel[2]*body->avel[2]);
            h *= REAL(0.5);
            dReal halfAngle = angularMagnitude * h;
            quaternion[0] = dCos(halfAngle);
            dReal scale = sinc(halfAngle) * h;
            quaternion[1] = body->avel[0] * scale;
            quaternion[2] = body->avel[1] * scale;
            quaternion[3] = body->avel[2] * scale;
        }

        // Apply finite rotation
        dQuaternion newQuaternion;
        dQMultiply0(newQuaternion, quaternion, body->q);
        for (index = 0; index < 4; index++) {
            body->q[index] = newQuaternion[index];
        }

        // Apply infinitesimal rotation if needed
        if (body->flags & dxBodyFlagFiniteRotationAxis) {
            dReal dq[4];
            dWtoDQ(rotationalVector, body->q, dq);
            for (index = 0; index < 4; index++) {
                body->q[index] += h * dq[index];
            }
        }
    }
    else {
        // Standard approach: use infinitesimal rotation
        dReal dq[4];
        dWtoDQ(body->avel, body->q, dq);
        for (index = 0; index < 4; index++) {
            body->q[index] += h * dq[index];
        }
    }

    // Normalize quaternion and update orientation matrix
    dNormalize4(body->q);
    dQtoR(body->q, body->R);

    // Notify attached geometric objects of movement
    for (dxGeom *geom = body->geom; geom; geom = dGeomGetBodyNext(geom)) {
        dGeomMoved(geom);
    }
}

//****************************************************************************
// Island processing for simulation optimization
void dxProcessIslands(dxWorld *world, dReal timestep, dstepper_fn_t stepper)
{
    dxBody *body, *currentBody, **bodyArray;
    dxJoint *joint, **jointArray;

    // Exit early if no bodies exist
    if (world->nb <= 0) return;

    // Process auto-disabling before island formation
    dInternalHandleAutoDisabling(world, timestep);

    // Allocate memory for island body and joint arrays
    bodyArray = (dxBody**) ALLOCA(world->nb * sizeof(dxBody*));
    jointArray = (dxJoint**) ALLOCA(world->nj * sizeof(dxJoint*));

    int bodyCount = 0;   // Number of bodies in current island
    int jointCount = 0;  // Number of joints in current island

    // Reset tags for all bodies and joints
    for (body = world->firstbody; body; body = (dxBody*)body->next) {
        body->tag = 0;
    }
    for (joint = world->firstjoint; joint; joint = (dxJoint*)joint->next) {
        joint->tag = 0;
    }

    // Determine maximum stack size needed for traversal
    int maxStackSize = (world->nj < world->nb) ? world->nj : world->nb;
    dxBody **stack = (dxBody**) ALLOCA(maxStackSize * sizeof(dxBody*));

    // Process each unvisited enabled body as potential island seed
    for (currentBody = world->firstbody; currentBody; currentBody = (dxBody*)currentBody->next) {
        if (currentBody->tag || (currentBody->flags & dxBodyDisabled)) continue;

        currentBody->tag = 1;
        int stackSize = 0;
        body = currentBody;
        bodyArray[0] = currentBody;
        bodyCount = 1;
        jointCount = 0;

        goto startTraversal;

        while (stackSize > 0) {
            body = stack[--stackSize];
            bodyArray[bodyCount++] = body;

            startTraversal:
            // Traverse connected joints and bodies
            for (dxJointNode *node = body->firstjoint; node; node = node->next) {
                if (!node->joint->tag) {
                    node->joint->tag = 1;
                    jointArray[jointCount++] = node->joint;

                    if (node->body && !node->body->tag) {
                        node->body->tag = 1;
                        stack[stackSize++] = node->body;
                    }
                }
            }

            dIASSERT(stackSize <= world->nb);
            dIASSERT(stackSize <= world->nj);
        }

        // Execute simulation stepper for this island
        stepper(world, bodyArray, bodyCount, jointArray, jointCount, timestep);

        // Ensure all processed bodies/joints remain tagged and enabled
        for (int i = 0; i < bodyCount; i++) {
            bodyArray[i]->tag = 1;
            bodyArray[i]->flags &= ~dxBodyDisabled;
        }
        for (int i = 0; i < jointCount; i++) {
            jointArray[i]->tag = 1;
        }
    }

    // Debug validation of tagging consistency
#ifndef dNODEBUG
    for (body = world->firstbody; body; body = (dxBody*)body->next) {
        if (body->flags & dxBodyDisabled) {
            if (body->tag) dDebug(0, "disabled body tagged");
        }
        else {
            if (!body->tag) dDebug(0, "enabled body not tagged");
        }
    }

    for (joint = world->firstjoint; joint; joint = (dxJoint*)joint->next) {
        bool connectedToActiveBody = false;
        if (joint->node[0].body && (joint->node[0].body->flags & dxBodyDisabled) == 0) {
            connectedToActiveBody = true;
        }
        if (joint->node[1].body && (joint->node[1].body->flags & dxBodyDisabled) == 0) {
            connectedToActiveBody = true;
        }

        if (connectedToActiveBody) {
