    MidiDevice::MidiDevice()
    {
        handle = nullptr;
        deviceIdentifier = 0;
    }

    MidiDevice::~MidiDevice()
    {
        Shutdown();
    }

    BOOL MidiDevice::ActivateDevice(UINT id)
    {
        if (handle != NULL)
        {
            if (deviceIdentifier != id)
            {
                Shutdown();
            }
            else
            {
                return FALSE;
            }
        }
        deviceIdentifier = id;
        return midiOutOpen(&handle, id, (DWORD_PTR)g_Supervisor.m_HwndGameWindow, NULL, CALLBACK_WINDOW) !=
               MMSYSERR_NOERROR;
    }

    ZunResult MidiDevice::Shutdown()
    {
        if (handle == NULL)
        {
            return ZUN_ERROR;
        }
        midiOutReset(handle);
        midiOutClose(handle);
        handle = NULL;
        return ZUN_SUCCESS;
    }

    BOOL MidiDevice::TransmitLongMessage(LPMIDIHDR header)
    {
        if (handle == NULL)
        {
            return FALSE;
        }
        else
        {
            if (midiOutPrepareHeader(handle, header, sizeof(*header)) != MMSYSERR_NOERROR)
            {
                return TRUE;
            }
            return midiOutLongMsg(handle, header, sizeof(*header)) != MMSYSERR_NOERROR;
        }
    }

    union ShortPacket {
        struct
        {
            u8 statusByte;
            i8 data1;
            i8 data2;
            i8 padding;
        } fields;
        DWORD value;
    };

    BOOL MidiDevice::TransmitShortMessage(u8 status, u8 byte1, u8 byte2)
    {
        ShortPacket packet;
        if (handle == NULL)
        {
            return FALSE;
        }
        else
        {
            packet.fields.statusByte = status;
            packet.fields.data1 = byte1;
            packet.fields.data2 = byte2;
            return midiOutShortMsg(handle, packet.value) != MMSYSERR_NOERROR;
        }
    }

    MidiTimer::MidiTimer()
    {
        timeGetDevCaps(&capabilities, sizeof(TIMECAPS));
        timerIdentifier = 0;
    }

    MidiTimer::~MidiTimer()
    {
        CancelTimerInternal();
        timeEndPeriod(capabilities.wPeriodMin);
    }

    UINT MidiTimer::StartTimerInternal(u32 delay, LPTIMECALLBACK callback, DWORD_PTR userData)
    {
        CancelTimerInternal();
        timeBeginPeriod(capabilities.wPeriodMin);
        if (callback != NULL)
        {
            timerIdentifier = timeSetEvent(delay, capabilities.wPeriodMin, callback, userData, TIME_PERIODIC);
        }
        else
        {
            timerIdentifier = timeSetEvent(delay, capabilities.wPeriodMin, (LPTIMECALLBACK)MidiTimer::DefaultTimerCallback,
                                           (DWORD_PTR)this, TIME_PERIODIC);
        }
        return timerIdentifier;
    }

    BOOL MidiTimer::CancelTimerInternal()
    {
        if (timerIdentifier != 0)
        {
            timeKillEvent(timerIdentifier);
        }
        timeEndPeriod(capabilities.wPeriodMin);
        timerIdentifier = 0;
        return TRUE;
    }

    void CALLBACK MidiTimer::DefaultTimerCallback(u32 id, u32 msg, DWORD_PTR user, DWORD_PTR dw1, DWORD_PTR dw2)
    {
        MidiTimer *timer = (MidiTimer *)user;
        timer->OnTimerElapsed();
    }

    u16 MidiOutput::Ntohs(u16 value)
    {
        u8 buffer[2];
        buffer[0] = ((u8 *)&value)[1];
        buffer[1] = ((u8 *)&value)[0];
        return *(const u16 *)(buffer);
    }

    u32 MidiOutput::SkipVariableLength(LPBYTE *cursor)
    {
        u32 result = 0;
        u8 currentByte;
        do
        {
            currentByte = **cursor;
            *cursor += 1;
            result = result * 0x80 + (currentByte & 0x7f);
        } while ((currentByte & 0x80) != 0);
        return result;
    }

    MidiOutput::MidiOutput()
    {
        tracks = NULL;
        divisions = 0;
        tempo = 0;
        trackCount = 0;
        field_2c4 = 0;
        fadeOutMultiplier = 0.0f;
        lastVolumeSetDuringFade = 0;
        field_2d0 = 0;
        field_2d4 = 0;
        field_2d8 = 0;
        field_2dc = 0;
        fadeOutActive = FALSE;
        for (int i = 0; i < ARRAY_SIZE_SIGNED(fileDataArray); i++)
        {
            fileDataArray[i] = NULL;
        }
        for (int i = 0; i < ARRAY_SIZE_SIGNED(headerArray); i++)
        {
            headerArray[i] = NULL;
        }
        activeFileIndex = -1;
        headerCursor = 0;
    }

    MidiOutput::~MidiOutput()
    {
        StopPlayback();
        ClearTracks();
        for (i32 i = 0; i < 32; i++)
        {
            FreeFileData(i);
        }
    }

    ZunResult MidiOutput::LoadFileData(int slot, LPCSTR path)
    {
        if (activeFileIndex == slot)
        {
            StopPlayback();
        }
        FreeFileData(slot);
        fileDataArray[slot] = FileSystem::OpenFile((LPSTR)path, NULL, false);
        if (fileDataArray[slot] == NULL)
        {
            g_GameErrorContext.Log(TH_ERR_MIDI_FAILED_TO_READ_FILE, path);
            return ZUN_ERROR;
        }
        return ZUN_SUCCESS;
    }

    void MidiOutput::FreeFileData(int slot)
    {
        g_ZunMemory.Free(fileDataArray[slot]);
        fileDataArray[slot] = NULL;
    }

    void MidiOutput::ClearTracks()
    {
        for (i32 idx = 0; idx < trackCount; idx++)
        {
            g_ZunMemory.Free(tracks[idx].data);
        }
        g_ZunMemory.Free(tracks);
        tracks = NULL;
        trackCount = 0;
    }

#pragma var_order(trackIdx, cursor, trackCursor, fileData, headerSize, rawHeader, trackSize, endOfHeader)
    ZunResult MidiOutput::AnalyzeFile(int index)
    {
        u8 rawHeader[8];
        u32 trackSize;
        LPBYTE cursor, trackCursor, endOfHeader;
        i32 trackIdx;
        LPBYTE fileData;
        u32 headerSize;

        ClearTracks();
        cursor = fileDataArray[index];
        fileData = cursor;

        if (cursor == NULL)
        {
            utils::DebugPrint(TH_ERR_MIDI_NOT_LOADED);
            return ZUN_ERROR;
        }

        // Read MIDI header chunk
        memcpy(&rawHeader, cursor, 8);
        cursor += sizeof(rawHeader);
        headerSize = MidiOutput::Ntohl(*(u32 *)(&rawHeader[4]));
        endOfHeader = cursor;
        cursor += headerSize;

        // Parse format type
        format = MidiOutput::Ntohs(*(u16 *)endOfHeader);
        divisions = MidiOutput::Ntohs(*(u16 *)(endOfHeader + 4));
        trackCount = MidiOutput::Ntohs(*(u16 *)(endOfHeader + 2));

        tracks = (MidiTrack *)g_ZunMemory.Alloc(sizeof(MidiTrack) * trackCount, "midi");
        memset(tracks, 0, sizeof(MidiTrack) * trackCount);

        for (trackIdx = 0; trackIdx < trackCount; trackIdx++)
        {
            trackCursor = cursor;
            cursor += 8;
            trackSize = MidiOutput::Ntohl(*(u32 *)&trackCursor[4]);
            tracks[trackIdx].size = trackSize;
            tracks[trackIdx].data = (LPBYTE)g_ZunMemory.Alloc(trackSize, "midi");
            tracks[trackIdx].playing = TRUE;
            memcpy(tracks[trackIdx].data, cursor, trackSize);
            cursor += trackSize;
        }

        tempo = 1000000;
        activeFileIndex = index;
        utils::DebugPrint(" midi open %d\n", index);
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::Initialize(LPCSTR path)
    {
        if (LoadFileData(0x1f, path) != ZUN_SUCCESS)
        {
            return ZUN_ERROR;
        }
        AnalyzeFile(0x1f);
        FreeFileData(0x1f);
        return ZUN_SUCCESS;
    }

    void MidiOutput::PrepareTracks()
    {
        i32 idx;
        MidiTrack *track = tracks;
        fadeOutMultiplier = 1.0f;
        field_2dc = 0;
        fadeOutActive = FALSE;
        volume = 0;
        field_130 = 0;

        for (idx = 0; idx < trackCount; idx++, track++)
        {
            track->cursor = track->data;
            track->startCursor = track->cursor;
            track->playing = TRUE;
            track->remainingTicks = MidiOutput::SkipVariableLength(&track->cursor);
        }
    }

    ZunResult MidiOutput::Start()
    {
        if (tracks == NULL)
        {
            return ZUN_ERROR;
        }
        PrepareTracks();
        midiDevice.ActivateDevice(MIDI_MAPPER);
        StartTimerInternal(1, NULL, NULL);
        utils::DebugPrint(" midi play\n");
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::StopPlayback()
    {
        if (tracks == NULL)
        {
            return ZUN_ERROR;
        }
        for (i32 i = 0; i < ARRAY_SIZE_SIGNED(headerArray); i++)
        {
            if (headerArray[i] != NULL)
            {
                CleanupHeader(headerArray[i]);
            }
        }
        CancelTimerInternal();
        midiDevice.Shutdown();
        activeFileIndex = -1;
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::CleanupHeader(LPMIDIHDR hdr)
    {
        if (hdr == NULL)
        {
            utils::DebugPrint("error :\r\n");
        }
        if (midiDevice.handle == NULL)
        {
            utils::DebugPrint("error :\r\n");
        }
        for (i32 i = 0; i < ARRAY_SIZE_SIGNED(headerArray); i++)
        {
            if (headerArray[i] == hdr)
            {
                headerArray[i] = NULL;
                goto success;
            }
        }
        return ZUN_ERROR;
    success:
        MMRESULT res = midiOutUnprepareHeader(midiDevice.handle, hdr, sizeof(*hdr));
        if (res != MMSYSERR_NOERROR)
        {
            utils::DebugPrint("error :\r\n");
        }
        g_ZunMemory.Free(hdr->lpData);
        g_ZunMemory.Free(hdr);
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::ConfigureFadeOut(u32 durationMs)
    {
        fadeOutMultiplier = 0.0f;
        fadeOutDuration = durationMs;
        fadeOutCounter = 0;
        field_2dc = 0;
        fadeOutActive = TRUE;
        return ZUN_SUCCESS;
    }

#pragma var_order(trackIdx, accumulator, anyTrackActive)
    void MidiOutput::OnTimerElapsed()
    {
        BOOL anyTrackActive = FALSE;
        ULONGLONG accumulator = field_130 + (volume * divisions * 1000) / tempo;

        if (fadeOutActive != FALSE)
        {
            if (fadeOutCounter < fadeOutDuration)
            {
                fadeOutMultiplier = 1.0f - (f32)fadeOutCounter / (f32)fadeOutDuration;
                if ((u32)(fadeOutMultiplier * 128.0f) != lastVolumeSetDuringFade)
                {
                    AdjustVolumeDuringFade(0);
                }
                lastVolumeSetDuringFade = (u8)(fadeOutMultiplier * 128.0f);
                fadeOutCounter++;
            }
            else
            {
                fadeOutMultiplier = 0.0f;
                return;
            }
        }

        i32 trackIdx;
        for (trackIdx = 0; trackIdx < trackCount; trackIdx++)
        {
            if (tracks[trackIdx].playing)
            {
                anyTrackActive = TRUE;
                while (tracks[trackIdx].playing)
                {
                    if (tracks[trackIdx].remainingTicks <= accumulator)
                    {
                        HandleEvent(&tracks[trackIdx]);
                        accumulator = field_130 + (volume * divisions * 1000 / tempo);
                        continue;
                    }
                    break;
                }
            }
        }
        volume++;
        if (!anyTrackActive)
        {
            PrepareTracks();
        }
    }

#pragma var_order(nextLen, idx, arg2, tempVar, opcodeLow, opcodeHigh, opcode, arg1, curLen, midiHdr, metaType,       \
                  localFlags, localPtr1, localPtr2)
    void MidiOutput::HandleEvent(MidiTrack *track)
    {
        i32 tempVar;
        i32 curLen, nextLen;
        MidiTrack *localPtr1;
        MidiTrack *localPtr2;
        u8 arg1, arg2;
        u8 opcode, opcodeHigh, opcodeLow;
        u8 metaType;
        LPMIDIHDR midiHdr;
        i32 idx;
        i32 localFlags;

        opcode = *track->cursor;
        if (opcode < MIDI_OPCODE_NOTE_OFF)
        {
            opcode = track->lastOpcode;
        }
        else
        {
            track->cursor += 1;
        }

        opcodeHigh = opcode & 0xf0;
        opcodeLow = opcode & 0x0f;

        switch (opcodeHigh)
        {
        case MIDI_OPCODE_SYSTEM_EXCLUSIVE:
            if (opcode == MIDI_OPCODE_SYSTEM_EXCLUSIVE)
            {
                if (headerArray[headerCursor] != NULL)
                {
                    CleanupHeader(headerArray[headerCursor]);
                }
                midiHdr = headerArray[headerCursor] = (LPMIDIHDR)g_ZunMemory.Alloc(sizeof(MIDIHDR), "midiHDR");
                curLen = MidiOutput::SkipVariableLength(&track->cursor);
                memset(midiHdr, 0, sizeof(MIDIHDR));
                midiHdr->lpData = (LPSTR)g_ZunMemory.Alloc(curLen + 1, "midiHDR->lpData");
                midiHdr->lpData[0] = MIDI_OPCODE_SYSTEM_EXCLUSIVE;
                midiHdr->dwFlags = 0;
                midiHdr->dwBufferLength = curLen + 1;
                for (idx = 0; idx < curLen; idx++)
                {
                    midiHdr->lpData[idx + 1] = *track->cursor;
                    track->cursor++;
                }
                if (midiDevice.TransmitLongMessage(midiHdr))
                {
                    g_ZunMemory.Free(midiHdr->lpData);
                    g_ZunMemory.Free(midiHdr);
                    headerArray[headerCursor] = NULL;
                }
                headerCursor += 1;
                headerCursor %= 32;
            }
            else if (opcode == MIDI_OPCODE_SYSTEM_RESET)
            {
                metaType = *track->cursor;
                track->cursor += 1;
                curLen = MidiOutput::SkipVariableLength(&track->cursor);
                if (metaType == 0x2f)
                {
                    track->playing = 0;
                    return;
                }
                if (metaType == 0x51)
                {
                    field_130 += (volume * divisions * 1000 / tempo);
                    volume = 0;
                    tempo = 0;
                    for (idx = 0; idx < curLen; idx += 1)
                    {
                        tempo = tempo * 0x100 + *track->cursor;
                        track->cursor += 1;
                    }
                    localFlags = 60000000 / tempo;
                    break;
                }
                track->cursor = track->cursor + curLen;
            }
            break;
        case MIDI_OPCODE_NOTE_OFF:
        case MIDI_OPCODE_NOTE_ON:
        case MIDI_OPCODE_POLYPHONIC_AFTERTOUCH:
        case MIDI_OPCODE_MODE_CHANGE:
        case MIDI_OPCODE_PITCH_BEND_CHANGE:
            arg1 = *track->cursor;
            track->cursor += 1;
            arg2 = *track->cursor;
            track->cursor += 1;
            break;
        case MIDI_OPCODE_PROGRAM_CHANGE:
        case MIDI_OPCODE_CHANNEL_AFTERTOUCH:
            arg1 = *track->cursor;
            track->cursor += 1;
            arg2 = 0;
            break;
        }

        switch (opcodeHigh)
        {
        case MIDI_OPCODE_NOTE_ON:
            if (arg2 != 0)
            {
                arg1 += field_2c4;
                channels[opcodeLow].pressedKeys[arg1 >> 3] |= (u8)(1 << (arg1 & 7));
                break;
            }
        case MIDI_OPCODE_NOTE_OFF:
            arg1 += field_2c4;
            channels[opcodeLow].pressedKeys[arg1 >> 3] &= (u8)(~(1 << (arg1 & 7)));
            break;
        case MIDI_OPCODE_PROGRAM_CHANGE:
            channels[opcodeLow].instrument = arg1;
            break;
        case MIDI_OPCODE_MODE_CHANGE:
            switch (arg1)
            {
            case 0:
                channels[opcodeLow].bank = arg2;
                break;
            case 7:
                channels[opcodeLow].volume = arg2;
                tempVar = (f32)arg2 * fadeOutMultiplier;
                if (tempVar < 0)
                {
                    tempVar = 0;
                }
                else if (0x7f < tempVar)
                {
                    tempVar = 0x7f;
                }
                arg2 = channels[opcodeLow].adjustedVolume = tempVar;
                break;
            case 91:
                channels[opcodeLow].effectOne = arg2;
                break;
            case 93:
                channels[opcodeLow].effectThree = arg2;
                break;
            case 10:
                channels[opcodeLow].pan = arg2;
                break;
            case 2:
                for (localPtr1 = &tracks[0], idx = 0; idx < trackCount; idx++, localPtr1++)
                {
                    localPtr1->startCursor = localPtr1->cursor;
                    localPtr1->savedRemaining = localPtr1->remainingTicks;
                }
                savedTempo = tempo;
                savedVolume = volume;
                savedField130 = field_130;
                break;
            case 4:
                for (localPtr2 = &tracks[0], idx = 0; idx < trackCount; idx++, localPtr2++)
                {
                    localPtr2->cursor = (byte *)localPtr2->startCursor;
                    localPtr2->remainingTicks = localPtr2->savedRemaining;
                }
                tempo = savedTempo;
                volume = savedVolume;
                field_130 = savedField130;
            }
            break;
        }

        if (opcode < MIDI_OPCODE_SYSTEM_EXCLUSIVE)
        {
            midiDevice.TransmitShortMsg(opcode, arg1, arg2);
        }
        track->lastOpcode = opcode;
        nextLen = MidiOutput::SkipVariableLength(&track->cursor);
        track->remainingTicks += nextLen;
    }

#pragma var_order(arg1, idx, volByte, status, clampedVol)
    void MidiOutput::AdjustVolumeDuringFade(i32 offset)
    {
        i32 clampedVol;
        u32 volByte;
        i32 idx;
        i32 arg1;
        u32 status;
        if (field_2d4 != 0)
        {
            return;
        }
        arg1 = 7;
        for (idx = 0; idx < ARRAY_SIZE_SIGNED(channels); idx += 1)
        {
            status = (u8)(idx + 0xb0);
            clampedVol = (i32)(channels[idx].volume * fadeOutMultiplier) + offset;
            if (clampedVol < 0)
            {
                clampedVol = 0;
            }
            else if (clampedVol > 127)
            {
                clampedVol = 127;
            }
            volByte = (u8)clampedVol;
            midiDevice.TransmitShortMsg(status, arg1, volByte);
        }
        return;
    }

    void MidiTimer::Activate()
    {
        StartTimerInternal(16, NULL, NULL);
    }

    void MidiTimer::Deactivate()
    {
        CancelTimerInternal();
    }
