namespace sdb {

template<typename Func>
void ShardBase::SchedulerWrapper::queue(Func&& func) {
  SchedulerFeature::gScheduler->queue(RequestLane::ClusterInternal,
                                      std::forward<Func>(func));
}

template<typename Func>
ShardBase::SchedulerWrapper::WorkHandle
ShardBase::SchedulerWrapper::queueDelayed(Func&& func,
                                          std::chrono::milliseconds delay) {
  return SchedulerFeature::gScheduler->queueDelayed(
    "shard-base-lock-timeout", RequestLane::ClusterInternal, delay,
    std::forward<Func>(func));
}

yaclib::Future<ErrorCode> ShardBase::LockImpl(double timeout,
                                              AccessMode::Type access_type) {
  // user read operations don't require any lock in RocksDB, so we won't get
  // here. user write operations will acquire the R/W lock in read mode, and
  // user exclusive operations will acquire the R/W lock in write mode.
  SDB_ASSERT(access_type == AccessMode::Type::Read || 
             access_type == AccessMode::Type::Write);

  if (timeout <= 0) {
    timeout = kDefaultLockTimeout;
  }

  auto timeout_duration = std::chrono::duration_cast<std::chrono::milliseconds>(
    std::chrono::duration<double>(timeout));

  bool acquired = false;

  if (access_type == AccessMode::Type::Write) {
    auto future = _exclusive_lock.asyncTryLockExclusiveFor(timeout_duration);
    co_await yaclib::Await(future);
    acquired = !!std::as_const(future).Touch();
    if (acquired) {
      std::move(future).Touch().Ok().release();
    }
  } else {
    auto future = _exclusive_lock.asyncTryLockSharedFor(timeout_duration);
    co_await yaclib::Await(future);
    acquired = !!std::as_const(future).Touch();
    if (acquired) {
      std::move(future).Touch().Ok().release();
    }
  }

  if (acquired) {
    co_return ERROR_OK;
  }
  co_return ERROR_LOCK_TIMEOUT;
}

yaclib::Future<ErrorCode> ShardBase::LockWrite(double timeout) {
  return LockImpl(timeout, AccessMode::Type::Write);
}

void ShardBase::UnlockWrite() noexcept { 
  _exclusive_lock.unlock(); 
}

yaclib::Future<ErrorCode> ShardBase::LockRead(double timeout) {
  return LockImpl(timeout, AccessMode::Type::Read);
}

void ShardBase::UnlockRead() { 
  _exclusive_lock.unlock(); 
}

