class MemoryImage {
public:
    int mWidth, mHeight;
    PixelFormat mPixelFormat;
    bool mHasAlpha, mHasTrans;
    unsigned int mRenderFlags;
    void* mColorIndices;
    int mBitsChangedCount;

    MemoryImage() : mWidth(0), mHeight(0), mPixelFormat(PixelFormat_Unknown),
                    mHasAlpha(false), mHasTrans(false), mRenderFlags(0),
                    mColorIndices(nullptr), mBitsChangedCount(0) {}
    void DeleteSWBuffers() {}
    void CommitBits() {}
    int GetWidth() const { return mWidth; }
    int GetHeight() const { return mHeight; }
};

class TextureDataPiece {
public:
    int mWidth, mHeight;
    void* mTexture;
    TextureDataPiece() : mWidth(0), mHeight(0), mTexture(nullptr) {}
};

class TextureData {
private:
    int mWidth, mHeight;
    PixelFormat mPixelFormat;
    unsigned int mImageFlags;
    int mTexPieceWidth, mTexPieceHeight;
    int mTexVecWidth, mTexVecHeight;
    int mBitsChangedCount;
    std::vector<TextureDataPiece> mTextures;
    int mTexMemSize;

public:
    float mMaxTotalU, mMaxTotalV;

    TextureData() : mWidth(0), mHeight(0), mPixelFormat(PixelFormat_Unknown),
                    mImageFlags(0), mTexPieceWidth(64), mTexPieceHeight(64),
                    mTexVecWidth(0), mTexVecHeight(0), mBitsChangedCount(0),
                    mTexMemSize(0), mMaxTotalU(1.0f), mMaxTotalV(1.0f) {}

    void ReleaseTextures() {
        mTextures.clear();
        mTexMemSize = 0;
    }

    void CreateTextureDimensions(MemoryImage* img) {
        int w = img->GetWidth();
        int h = img->GetHeight();
        mTexVecWidth = (w + mTexPieceWidth - 1) / mTexPieceWidth;
        mTexVecHeight = (h + mTexPieceHeight - 1) / mTexPieceHeight;
        mTextures.resize(mTexVecWidth * mTexVecHeight);
        for (int i = 0; i < mTexVecWidth * mTexVecHeight; ++i) {
            mTextures[i].mWidth = mTexPieceWidth;
            mTextures[i].mHeight = mTexPieceHeight;
        }
        // Adjust last row/col sizes
        if (mTexVecWidth > 0) {
            int lastW = w - (mTexVecWidth - 1) * mTexPieceWidth;
            for (int j = 0; j < mTexVecHeight; ++j) {
                mTextures[j * mTexVecWidth + mTexVecWidth - 1].mWidth = lastW;
            }
        }
        if (mTexVecHeight > 0) {
            int lastH = h - (mTexVecHeight - 1) * mTexPieceHeight;
            for (int i = 0; i < mTexVecWidth; ++i) {
                mTextures[(mTexVecHeight - 1) * mTexVecWidth + i].mHeight = lastH;
            }
        }
    }

    void CopyImageToTexture(void* tex, MemoryImage* img, int x, int y, int tw, int th, PixelFormat fmt, bool create) {
        // Simulate copying image data to texture
    }

    void CheckCreateTextures(MemoryImage* theImage) {
        if (mPixelFormat == PixelFormat_Unknown || 
            theImage->mWidth != mWidth || 
            theImage->mHeight != mHeight || 
            theImage->mBitsChangedCount != mBitsChangedCount || 
            (theImage->mRenderFlags & 0xFF) != mImageFlags) {
            CreateTextures(theImage);
        }
    }

    void CreateTextures(MemoryImage* theImage) {
        theImage->DeleteSWBuffers(); // don't need these buffers for 3d drawing
        // Choose appropriate pixel format
        PixelFormat aFormat = PixelFormat_A8R8G8B8;
        //theImage->mRenderFlags = RenderImageFlag_UseA4R4G4B4;
        theImage->CommitBits();
        if (!theImage->mHasAlpha && !theImage->mHasTrans && (0xFFFFFFFF & PixelFormat_R5G6B5)) {
            if (!(theImage->mRenderFlags & 0x100))
                aFormat = PixelFormat_R5G6B5;
        }
        if (theImage->mColorIndices != nullptr && (0xFFFFFFFF & PixelFormat_Palette8)) {
        }
        if ((theImage->mRenderFlags & 0x200) && aFormat == PixelFormat_A8R8G8B8 && (0xFFFFFFFF & PixelFormat_A4R4G4B4))
            aFormat = PixelFormat_A4R4G4B4;
        if (aFormat == PixelFormat_A8R8G8B8 && !(0xFFFFFFFF & PixelFormat_A8R8G8B8))
            aFormat = PixelFormat_A4R4G4B4;
        // Release texture if image size has changed
        bool createTextures = false;
        if (mWidth != theImage->mWidth || mHeight != theImage->mHeight || aFormat != mPixelFormat || (theImage->mRenderFlags & 0xFF) != mImageFlags) {
            ReleaseTextures();
            mPixelFormat = aFormat;
            mImageFlags = theImage->mRenderFlags & 0xFF;
            CreateTextureDimensions(theImage);
            createTextures = true;
        }
        int i, x, y;
        int aHeight = theImage->GetHeight();
        int aWidth = theImage->GetWidth();
        int aFormatSize = 4;
        GPU_TEXCOLOR aFormatType = GPU_RGBA8;
        if (aFormat == PixelFormat_R5G6B5) {
            aFormatSize = 2;
            aFormatType = GPU_RGB565;
        } else if (aFormat == PixelFormat_A4R4G4B4) {
            aFormatSize = 2;
            aFormatType = GPU_RGBA4;
        }
        i = 0;
        for (y = 0; y < aHeight; y += mTexPieceHeight) {
            for (x = 0; x < aWidth; x += mTexPieceWidth, i++) {
                TextureDataPiece& aPiece = mTextures[i];
                if (createTextures) {
                    // Simulate C3D_TexInit(&aPiece.mTexture, aPiece.mWidth, aPiece.mHeight, aFormatType);
                    mTexMemSize += aPiece.mWidth * aPiece.mHeight * aFormatSize;
                }
                CopyImageToTexture(&aPiece.mTexture, theImage, x, y, aPiece.mWidth, aPiece.mHeight, aFormat, createTextures);
            }
        }
        mWidth = theImage->mWidth;
        mHeight = theImage->mHeight;
        mBitsChangedCount = theImage->mBitsChangedCount;
        mPixelFormat = aFormat;
    }

    void* GetTexture(int x, int y, int& width, int& height, float& u1, float& v1, float& u2, float& v2) {
        int tx = x / mTexPieceWidth;
        int ty = y / mTexPieceHeight;
        TextureDataPiece& aPiece = mTextures[ty * mTexVecWidth + tx];
        int left = x % mTexPieceWidth;
        int top = y % mTexPieceHeight;
        int right = left + width;
        int bottom = top + height;
        if (right > aPiece.mWidth) right = aPiece.mWidth;
        if (bottom > aPiece.mHeight) bottom = aPiece.mHeight;
        width = right - left;
        height = bottom - top;
        u1 = static_cast<float>(left) / aPiece.mWidth;
        v1 = static_cast<float>(top) / aPiece.mHeight;
        u2 = static_cast<float>(right) / aPiece.mWidth;
        v2 = static_cast<float>(bottom) / aPiece.mHeight;
        return &aPiece.mTexture;
    }

    void* GetTextureF(float x, float y, float& width, float& height, float& u1, float& v1, float& u2, float& v2) {
        int tx = static_cast<int>(x / mTexPieceWidth);
        int ty = static_cast<int>(y / mTexPieceHeight);
        TextureDataPiece& aPiece = mTextures[ty * mTexVecWidth + tx];
        float left = x - tx * mTexPieceWidth;
        float top = y - ty * mTexPieceHeight;
        float right = left + width;
        float bottom = top + height;
        if (right > aPiece.mWidth) right = aPiece.mWidth;
        if (bottom > aPiece.mHeight) bottom = aPiece.mHeight;
        width = right - left;
        height = bottom - top;
        u1 = left / aPiece.mWidth;
        v1 = top / aPiece.mHeight;
        u2 = right / aPiece.mWidth;
        v2 = bottom / aPiece.mHeight;
        return &aPiece.mTexture;
    }

    void Blt(float theX, float theY, const Rect& theSrcRect, const Color& theColor) {
        int srcLeft = theSrcRect.mX;
        int srcTop = theSrcRect.mY;
        int srcRight = srcLeft + theSrcRect.mWidth;
        int srcBottom = srcTop + theSrcRect.mHeight;
        int srcX, srcY;
        float dstX, dstY;
        int aWidth, aHeight;
        float u1, v1, u2, v2;
        srcY = srcTop;
        dstY = theY;
        uint32_t aColor = (theColor.mRed << 0) | (theColor.mGreen << 8) | (theColor.mBlue << 16) | (theColor.mAlpha << 24);
        if ((srcLeft >= srcRight) || (srcTop >= srcBottom))
            return;
        while (srcY < srcBottom) {
            srcX = srcLeft;
            dstX = theX;
            while (srcX < srcRight) {
                aWidth = srcRight - srcX;
                aHeight = srcBottom - srcY;
                void* aTexture = GetTexture(srcX, srcY, aWidth, aHeight, u1, v1, u2, v2);
                float x = dstX - 0.5f;
                float y = dstY - 0.5f;
                GLVertex aVertex[4] = {
                    { {x}, {y}, {0}, {aColor}, {u1}, {v1} },
                    { {x}, {y + aHeight}, {0}, {aColor}, {u1}, {v2} },
                    { {x + aWidth}, {y}, {0}, {aColor}, {u2}, {v1} },
                    { {x + aWidth}, {y + aHeight}, {0}, {aColor}, {u2}, {v2} }
                };
                SetTexture(aTexture);
                GfxBegin(0x0005); // GPU_TRIANGLE_STRIP
                GfxAddVertices(aVertex, 4);
                GfxEnd();
                srcX += aWidth;
                dstX += aWidth;
            }
            srcY += aHeight;
            dstY += aHeight;
        }
    }
};

// Main function demonstrating usage
int main() {
    TextureData texData;
    MemoryImage img;
    img.mWidth = 256;
    img.mHeight = 256;
    texData.CheckCreateTextures(&img);

    Rect srcRect(0, 0, 64, 64);
    Color col(255, 255, 255, 255);
    texData.Blt(10.0f, 20.0f, srcRect, col);

    std::cout << "Texture processing completed." << std::endl;
    return 0;
}

