void Engine::execute()
{
    update_bindings();
    SDL_Event evt;
    bool exitLoop = false;
    int keyCount;
    const bool *keyboardState = SDL_GetKeyboardState(&keyCount);

    float deltaTime;
    uint64_t nowTime, prevTime{SDL_GetPerformanceCounter()};
    const double frequency = static_cast<double>(SDL_GetPerformanceFrequency());

    while (!exitLoop) {
        nowTime = SDL_GetPerformanceCounter();
        deltaTime = static_cast<float>(nowTime - prevTime) / frequency;
        prevTime = nowTime;

        while (SDL_PollEvent(&evt)) {
            switch (evt.type) {
            case SDL_EVENT_QUIT:
                exitLoop = true;
                break;
            case SDL_EVENT_WINDOW_PIXEL_SIZE_CHANGED:
                needsResize = true;
                break;
            case SDL_EVENT_KEY_DOWN:
                context->camera->handle_input(keyboardState, deltaTime);
                break;
            }
            ImGui_ImplSDL3_ProcessEvent(&evt);
        }

        if (needsResize)
            handle_resize();

        update_ui();
        render();
    }
}

void Engine::update_ui()
{
    static SpecializationConstantsClosestHit shaderCH{};
    static SpecializationConstantsMiss shaderMiss{};
    static bool useRandom{static_cast<bool>(shaderCH.random)},
        usePresample{static_cast<bool>(shaderCH.presampled)},
        useEnvironmentMap{static_cast<bool>(shaderMiss.envMap)}, directionalLightEnabled{false};
    static int maxRecursion = shaderCH.recursionDepth, maxBounces = shaderCH.numBounces;
    static float modelScale{1.f}, rotX{0.f}, rotY{0.f}, rotZ{0.f};
    static std::filesystem::path hdrFilePath{std::string(PROJECT_DIR)
                                             + std::string("/assets/rogland_clear_night_4k.hdr")};

    ImGui_ImplVulkan_NewFrame();
    ImGui_ImplSDL3_NewFrame();
    ImGui::NewFrame();

    const float frameTimeMs = ImGui::GetIO().DeltaTime * 1000.f;
    const float framesPerSecond = 1000.0f / frameTimeMs;

    ImGuiViewport *mainViewport = ImGui::GetMainViewport();
    ImVec2 workAreaOrigin = mainViewport->WorkPos;
    ImVec2 workAreaSize = mainViewport->WorkSize;
    ImVec2 windowPosition = ImVec2(workAreaOrigin.x + workAreaSize.x - 10, workAreaOrigin.y + 10);

    ImGui::SetNextWindowPos(windowPosition, ImGuiCond_Always, ImVec2(1.0f, 0.0f));
    ImGui::SetNextWindowBgAlpha(0.35f);

    static constexpr ImGuiWindowFlags uiFlags = ImGuiWindowFlags_NoDecoration
                                                | ImGuiWindowFlags_AlwaysAutoResize
                                                | ImGuiWindowFlags_NoSavedSettings
                                                | ImGuiWindowFlags_NoFocusOnAppearing
                                                | ImGuiWindowFlags_NoNav;

    ImGui::Begin("Performance Metrics", nullptr, uiFlags);
    ImGui::Text("%.1f FPS", framesPerSecond);
    ImGui::Text("%.2f ms", frameTimeMs);
    ImGui::End();

    ImGui::Begin("Rendering Controls");
    ImGui::ColorEdit3("Background Color", reinterpret_cast<float*>(&rayPush.clearColor));
    ImGui::Separator();

    ImGui::Checkbox("Environment Map", &useEnvironmentMap);
    ImGui::SameLine();
    if (ImGui::Button("Select File")) {
        const std::filesystem::path selectedPath = utils::load_file_from_window({{"HDRI", "hdr"}});
        context->device.waitIdle();
        utils::destroy_image(context->device, context->allocator, context->backgroundImage);
        context->load_background(selectedPath);
        descriptorManager->cleanup();
        for (const auto &frame : context->frames) {
            descriptorManager->add_combined_image(frame.descriptorSetRt, 5, {context->backgroundImage});
        }
        descriptorManager->apply();
        hdrFilePath = selectedPath;
    }

    if (useEnvironmentMap) {
        ImGui::SameLine();
        ImGui::Text("%s", hdrFilePath.c_str());
    }

    ImGui::Checkbox("Random Sampling", &useRandom);
    ImGui::Checkbox("Pre-sampled", &usePresample);
    ImGui::InputInt("Max Recursion Depth", &maxRecursion, 1, 1);
    maxRecursion = std::max(maxRecursion, 1);
    ImGui::InputInt("Light Bounces", &maxBounces, 2, 4);
    maxBounces = std::max(maxBounces, 2);

    if (ImGui::Button("Apply Settings")) {
        shaderCH.recursionDepth = static_cast<uint32_t>(maxRecursion);
        shaderCH.numBounces = static_cast<uint32_t>(maxBounces);
        shaderCH.random = static_cast<vk::Bool32>(useRandom);
        shaderCH.presampled = static_cast<vk::Bool32>(usePresample);
        shaderMiss.envMap = static_cast<vk::Bool32>(useEnvironmentMap);
        context->rebuild_rt_pipeline(shaderCH, shaderMiss);
    }

    ImGui::Separator();

    const float oldScale{modelScale};
    if (ImGui::InputFloat("Model Scale", &modelScale, 0.1f, 0.5f, "%.2f")) {
        modelScale = std::max(modelScale, 0.01f);
        const float scaleChange = modelScale / oldScale;
        const glm::mat4 scalingMatrix = glm::scale(glm::mat4{1.f}, glm::vec3(scaleChange));
        context->asBuilder->update_TLAS(context->tlas, scalingMatrix);
        rayPush.globalScale = modelScale;
    }

    const float oldRotX{rotX};
    if (ImGui::SliderAngle("Rotate X Axis", &rotX, -180.f, 180.f)) {
        const float angleDiff = rotX - oldRotX;
        const glm::mat4 rotationMatrix = glm::rotate(angleDiff, glm::vec3(1.f, 0.f, 0.f));
        context->asBuilder->update_TLAS(context->tlas, rotationMatrix);
    }

    const float oldRotY{rotY};
    if (ImGui::SliderAngle("Rotate Y Axis", &rotY, -180.f, 180.f)) {
        const float angleDiff = rotY - oldRotY;
        const glm::mat4 rotationMatrix = glm::rotate(angleDiff, glm::vec3(0.f, -1.f, 0.f));
        context->asBuilder->update_TLAS(context->tlas, rotationMatrix);
    }

    const float oldRotZ{rotZ};
    if (ImGui::SliderAngle("Rotate Z Axis", &rotZ, -180.f, 180.f)) {
        const float angleDiff = rotZ - oldRotZ;
        const glm::mat4 rotationMatrix = glm::rotate(angleDiff, glm::vec3(0.f, 0.f, 1.f));
        context->asBuilder->update_TLAS(context->tlas, rotationMatrix);
    }

    lightHandler->process();
    assert(lightHandler->lightBuffers.size() == lightHandler->lights.size());

    bool needUpdate = false;
    for (auto &f : context->frames) {
        needUpdate = needUpdate || (f.lightCount != lightHandler->lights.size());
        f.lightCount = lightHandler->lights.size();
    }

    if (needUpdate && lightHandler->lightBuffers.size() > 0) {
        descriptorManager->cleanup();
        for (const auto &f : context->frames) {
            descriptorManager->add_uniform(f.descriptorSetUAB, 3, lightHandler->lightBuffers);
        }
        descriptorManager->apply();
    }

    rayPush.lightCount = static_cast<uint32_t>(lightHandler->lights.size());
    ImGui::End();

    ImGui::Render();
}

void Engine::update_bindings()
{
    descriptorManager->cleanup();

    const bool hasTextures = context->scene->samplers.size() > 0 && context->scene->images.size() > 0;
    for (const auto &frame : context->frames) {
        const vk::DescriptorSet uniformSet = frame.descriptorSetUAB;
        const vk::DescriptorSet rtSet = frame.descriptorSetRt;

        descriptorManager->add_uniform(uniformSet, 0, context->scene->surfaceUniformBuffers);
        if (hasTextures) {
            descriptorManager->add_sampler(uniformSet, 1, context->scene->samplers);
            descriptorManager->add_sampled_image(uniformSet, 2, context->scene->images);
        }
        if (lightHandler->lightBuffers.size() > 0)
            descriptorManager->add_uniform(uniformSet, 3, lightHandler->lightBuffers);

        descriptorManager->add_as(rtSet, 0, context->tlas.as.AS);
        descriptorManager->add_storage_image(rtSet, 1, {frame.imageDraw});
        descriptorManager->add_uniform(rtSet, 2, {context->camera->cameraBuffer});
        descriptorManager->add_combined_image(rtSet, 3, {context->presampler->hemisphereImage});
        descriptorManager->add_combined_image(rtSet, 4, {context->presampler->ggxImage});
        descriptorManager->add_combined_image(rtSet, 5, {context->backgroundImage});
        descriptorManager->add_storage(rtSet, 6, {context->scene->instancesBuffer});
    }
    descriptorManager->apply();
}

void Engine::render()
{
    vk::Semaphore acquireSync = get_current_frame().renderSemaphore;
    vk::Fence frameFence = get_current_frame().renderFence;
    ImageData outputImage = get_current_frame().imageDraw;

    vk::Result fenceResult = context->device.waitForFences(frameFence, vk::True, FENCE_TIMEOUT);
    if (fenceResult != vk::Result::eSuccess) {
        std::println("Dropping frame due to GPU lag");
        return;
    }

    vk::AcquireNextImageInfoKHR imageRequest{};
    imageRequest.setSwapchain(context->swapchain);
    imageRequest.setSemaphore(acquireSync);
    imageRequest.setFence(nullptr);
    imageRequest.setTimeout(FENCE_TIMEOUT);
    imageRequest.setDeviceMask(1);

    vk::Result imageResult = context->device.acquireNextImage2KHR(&imageRequest, &swapchainImageIndex);
    VK_CHECK_RES(imageResult);

    if (imageResult == vk::Result::eErrorOutOfDateKHR) {
        needsResize = true;
        return;
    }

    context->device.resetFences(frameFence);
    vk::Semaphore submitSync = acquireSync;

    vk::MemoryBarrier2 memBarrier{};
    vk::DependencyInfo dependencyInfo{};
    dependencyInfo.setMemoryBarriers(memBarrier);

    vk::CommandBuffer cmdBuffer = get_current_frame().mainCommandBuffer;
    cmdBuffer.reset();

    vk::CommandBufferBeginInfo beginInfo{};
    beginInfo.setFlags(vk::CommandBufferUsageFlagBits::eOneTimeSubmit);
    cmdBuffer.begin(beginInfo);

    utils::transition_image(cmdBuffer,
                            context->swapchainImages[swapchainImageIndex],
                            vk::ImageLayout::eUndefined,
                            vk::ImageLayout::eGeneral,
                            vk::PipelineStageFlagBits2::eTopOfPipe,
                            vk::PipelineStageFlagBits2::eRayTracingShaderKHR);

    trace_rays(cmdBuffer);

    memBarrier.setSrcStageMask(vk::PipelineStageFlagBits2::eRayTracingShaderKHR);
    memBarrier.setDstStageMask(vk::PipelineStageFlagBits2::eBlit);
    memBarrier.setSrcAccessMask(vk::AccessFlagBits2::eMemoryWrite);
    memBarrier.setDstAccessMask(vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite);
    cmdBuffer.pipelineBarrier2(dependencyInfo);

    utils::copy_image(cmdBuffer,
                      outputImage.image,
                      context->swapchainImages[swapchainImageIndex].image,
                      vk::Extent2D{outputImage.extent.width, outputImage.extent.height},
                      context->swapchainExtent);

    memBarrier.setSrcStageMask(vk::PipelineStageFlagBits2::eBlit);
    memBarrier.setDstStageMask(vk::PipelineStageFlagBits2::eAllGraphics);
    memBarrier.setSrcAccessMask(vk::AccessFlagBits2::eMemoryWrite);
    memBarrier.setDstAccessMask(vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite);
    cmdBuffer.pipelineBarrier2(dependencyInfo);

    overlay_ui(cmdBuffer, context->swapchainImages[swapchainImageIndex].imageView);

    utils::transition_image(cmdBuffer,
                            context->swapchainImages[swapchainImageIndex],
                            vk::ImageLayout::eGeneral,
                            vk::ImageLayout::ePresentSrcKHR,
                            vk::PipelineStageFlagBits2::eAllGraphics,
                            vk::PipelineStageFlagBits2::eBottomOfPipe);

    cmdBuffer.end();

    vk::CommandBufferSubmitInfo cmdSubmitInfo{};
    cmdSubmitInfo.setDeviceMask(1);
    cmdSubmitInfo.setCommandBuffer(cmdBuffer);

    vk::SemaphoreSubmitInfo waitSemaphoreInfo{};
    waitSemaphoreInfo.setSemaphore(acquireSync);
    waitSemaphoreInfo.setStageMask(vk::PipelineStageFlagBits2::eAllGraphics
                                   | vk::PipelineStageFlagBits2::eRayTracingShaderKHR);
    waitSemaphoreInfo.setDeviceIndex(0);
    waitSemaphoreInfo.setValue(1);

    vk::SemaphoreSubmitInfo signalSemaphoreInfo{};
    signalSemaphoreInfo.setSemaphore(submitSync);
    signalSemaphoreInfo.setStageMask(vk::PipelineStageFlagBits2::eAllGraphics
                                     | vk::PipelineStageFlagBits2::eRayTracingShaderKHR);
    signalSemaphoreInfo.setDeviceIndex(0);
    signalSemaphoreInfo.setValue(1);

    vk::SubmitInfo2 submissionInfo{};
    submissionInfo.setCommandBufferInfos(cmdSubmitInfo);
    submissionInfo.setWaitSemaphoreInfos(waitSemaphoreInfo);
    submissionInfo.setSignalSemaphoreInfos(signalSemaphoreInfo);

    context->graphicsQueue.submit2(submissionInfo, nullptr);

    vk::SwapchainPresentFenceInfoKHR presentFenceInfo{};
    presentFenceInfo.setFences(frameFence);
    presentFenceInfo.setSwapchainCount(1);

    vk::PresentInfoKHR presentInfo{};
    presentInfo.setSwapchains(context->swapchain);
    presentInfo.setWaitSemaphores(submitSync);
    presentInfo.setImageIndices(swapchainImageIndex);
    presentInfo.setPNext(&presentFenceInfo);

    vk::Result presentResult = context->graphicsQueue.presentKHR(presentInfo);
    VK_CHECK_RES(presentResult);

    if (presentResult == vk::Result::eErrorOutOfDateKHR)
        needsResize = true;

    frameNumber = (frameNumber + 1) % context->frameOverlap;
}

void Engine::trace_rays(const vk::CommandBuffer &cmd)
{
    cmd.bindPipeline(vk::PipelineBindPoint::eRayTracingKHR, context->simpleRtPipeline.pipeline);

    vk::DescriptorSet uniformSet = get_current_frame().descriptorSetUAB;
    vk::DescriptorSet rtSet = get_current_frame().descriptorSetRt;
    vk::ImageView targetView = get_current_frame().imageDraw.imageView;
    vk::AccelerationStructureKHR tlas = context->tlas.as.AS;

    std::vector<vk::DescriptorSet> sets = {rtSet, uniformSet};

    vk::BindDescriptorSetsInfo bindInfo{};
    bindInfo.setDescriptorSets(sets);
    bindInfo.setStageFlags(vk::ShaderStageFlagBits::eRaygenKHR
                           | vk::ShaderStageFlagBits::eClosestHitKHR
                           | vk::ShaderStageFlagBits::eMissKHR);
    bindInfo.setLayout(context->simpleRtPipeline.pipelineLayout);
    bindInfo.setFirstSet(0);
    cmd.bindDescriptorSets2(bindInfo);

    vk::PushConstantsInfo pushInfo{};
    pushInfo.setLayout(context->simpleRtPipeline.pipelineLayout);
    pushInfo.setStageFlags(vk::ShaderStageFlagBits::eRaygenKHR
                           | vk::ShaderStageFlagBits::eClosestHitKHR
                           | vk::ShaderStageFlagBits::eMissKHR);
    pushInfo.setSize(sizeof(RayPush));
    pushInfo.setValues<RayPush>(rayPush);
    pushInfo.setOffset(0);
    cmd.pushConstants2(pushInfo);

    context->camera->update();
    cmd.traceRaysKHR(context->sbtHelper->rgenRegion,
                     context->sbtHelper->missRegion,
                     context->sbtHelper->hitRegion,
                     vk::StridedDeviceAddressRegionKHR{},
                     context->swapchainExtent.width,
                     context->swapchainExtent.height,
                     1);
}

void Engine::overlay_ui(const vk::CommandBuffer &cmd, const vk::ImageView &targetView)
{
    vk::RenderingAttachmentInfo colorAttachment{};
    colorAttachment.setImageView(targetView);
    colorAttachment.setImageLayout(vk::ImageLayout::eGeneral);
    colorAttachment.setLoadOp(vk::AttachmentLoadOp::eLoad);
    colorAttachment.setStoreOp(vk::AttachmentStoreOp::eStore);

    vk::RenderingInfo renderPassInfo{};
    renderPassInfo.setColorAttachments(colorAttachment);
    renderPassInfo.setLayerCount(1);
    renderPassInfo.setRenderArea(vk::Rect2D{vk::Offset2D{0, 0}, context->swapchainExtent});

    cmd.beginRendering(renderPassInfo);
    ImGui_ImplVulkan_RenderDrawData(ImGui::GetDrawData(), cmd);
    cmd.endRendering();
}

void Engine::handle_resize()
{
    context->device.waitIdle();
    context->recreate_swapchain();
    context->recreate_draw_data();
    descriptorManager->cleanup();
    for (const auto &f : context->frames)
        descriptorManager->add_storage_image(f.descriptorSetRt, 1, {f.imageDraw});
    descriptorManager->apply();
    context->recreate_camera();
    needsResize = false;
}

