	ListCommandItem::ListCommandItem(joaat_t identifier, std::optional<std::string> custom_label) :
	    m_Command(Commands::GetCommand<ListCommand>(identifier)),
	    m_LabelOverride(custom_label)
	{
	}

	void ListCommandItem::Draw()
	{
		if (!m_Command)
		{
			ImGui::Text("Unknown list!");
			return;
		}

		int current_value = m_Command->GetState();
		auto& items_list = m_Command->GetList();

		const char* widest_item = "";
		std::size_t max_width_chars = 0;

		if (!m_SelectedItem.has_value() || !m_ItemWidth.has_value())
		{
			for (const auto& entry : items_list)
			{
				if (entry.first == current_value)
				{
					m_SelectedItem = entry.second;
				}

				int text_len = strlen(entry.second);
				if (text_len > max_width_chars)
				{
					widest_item = entry.second;
					max_width_chars = text_len;
				}
			}

			if (!m_SelectedItem.has_value())
				m_SelectedItem = "";

			auto dimensions = ImGui::CalcTextSize(widest_item);
			m_ItemWidth = dimensions.x + 40.0f;
		}

		ImGui::SetNextItemWidth(m_ItemWidth.value());

		if (ImGui::BeginCombo(
		        m_LabelOverride.has_value() ? m_LabelOverride.value().c_str() : m_Command->GetLabel().c_str(),
		        m_SelectedItem.has_value() ? m_SelectedItem.value().c_str() : ""))
		{
			for (auto& option : items_list)
			{
				bool is_selected = option.first == current_value;
				if (ImGui::Selectable(option.second, is_selected))
				{
					current_value = option.first;
					m_Command->SetState(option.first);
				}

				if (is_selected)
				{
					m_SelectedItem = option.second; // ensure consistency
					ImGui::SetItemDefaultFocus();
				}
			}
			ImGui::EndCombo();
		}
	}
}

#include "script-output-tokenizer.hpp"
#include <utility>
#include "ui/omni-painter/omni-painter.hpp"

ScriptOutputTokenizer::ScriptOutputTokenizer(QStringView input) : m_input(input) {}

std::optional<ScriptOutputTokenizer::Token> ScriptOutputTokenizer::next() {
  static const auto schemes = {QStringLiteral("http://"), QStringLiteral("https://")};
  if (std::cmp_greater_equal(m_position, m_input.size())) return {};

  Token result;
  std::vector<uint8_t> ansiCodes;

  while (std::cmp_less(m_position, m_input.size())) {
    QChar const currentChar = m_input.at(m_position);
    QStringView remaining = m_input.sliced(m_position);

    switch (m_mode) {
    case Mode::Default: {
      if (currentChar == '\033') {
        if (result.style) return result;
        m_mode = Mode::Escape;
      } else {
        bool const potentialLink =
            std::ranges::any_of(schemes, [&](const auto &prefix) { return remaining.startsWith(prefix); });
        if (potentialLink) {
          m_mode = Mode::Link;
          return result;
        }
        result.content.append(currentChar);
      }
      break;
    }
    case Mode::Link: {
      if (isUrlCharacter(currentChar)) {
        result.content.append(currentChar);
      } else {
        m_mode = Mode::Default;
        result.link = true;
        return result;
      }
      break;
    }
    case Mode::Escape: {
      if (currentChar == '[') {
        if (!result.content.isEmpty()) { return result; }
        ansiCodes.clear();
        ansiCodes.emplace_back(0);
        m_mode = Mode::Ansi;
      }
      break;
    }
    case Mode::Ansi: {
      if (currentChar.isNumber()) {
        int digit = currentChar.toLatin1() - '0';
        ansiCodes.back() = ansiCodes.back() * 10 + digit;
      } else if (currentChar == ';') {
        ansiCodes.emplace_back(0);
      } else if (currentChar == 'm') {
        result.style = interpretAnsi(ansiCodes);
        m_mode = Mode::Default;
      }
      break;
    }
    }
    ++m_position;
  }
  return result;
}

size_t ScriptOutputTokenizer::getPosition() const { return m_position; }

void ScriptOutputTokenizer::setPosition(size_t pos) { m_position = pos; }

ScriptOutputTokenizer::Style ScriptOutputTokenizer::interpretAnsi(const std::vector<std::uint8_t> &codes) {
  Style style;
  for (const auto code : codes) {
    if (code >= 30 && code <= 37) {
      style.foreground = resolveForeground(code);
    } else if (code >= 40 && code <= 47) {
      style.background = resolveForeground(code - 10);
    } else if (code == 0) {
      style.clear = true;
    } else if (code == 1) {
      // emphasize next foreground color — currently ignored
    } else if (code >= 90 && code <= 97) {
      style.foreground = resolveForeground(code - 60);
    }
  }
  return style;
}

QColor ScriptOutputTokenizer::resolveBackground(int index) {
  return OmniPainter::resolveColor(getBaseColor(index));
}

bool ScriptOutputTokenizer::isUrlCharacter(QChar c) {
  return c.isPrint() && !c.isSpace() && c != '"' && c != '\'' && c != ')' && c != '(';
}

QColor ScriptOutputTokenizer::resolveForeground(std::uint8_t code) {
  return OmniPainter::resolveColor(getBaseColor(code));
}

ColorLike ScriptOutputTokenizer::getBaseColor(std::uint8_t index) {
  switch (index) {
  case 0:
    return QColor(Qt::transparent);
  case 30:
    return QColor(Qt::black);
  case 31:
    return SemanticColor::Red;
  case 32:
    return SemanticColor::Green;
  case 33:
    return SemanticColor::Yellow;
  case 34:
    return SemanticColor::Blue;
  case 35:
    return SemanticColor::Magenta;
  case 36:
    return SemanticColor::Cyan;
  case 97:
    return QColor(Qt::white);
  default:
    return SemanticColor::TextPrimary;
  }
}

