    if (presentSettings.framebufferHandle.IsHolding<HgiPresentInteropHandle>())
    {
        return presentSettings.framebufferHandle.UncheckedGet<HgiPresentInteropHandle>();
    }

#if defined(PXR_GL_SUPPORT_ENABLED)
    uint32_t fbHandle = 0;
    if (presentSettings.framebufferHandle.IsHolding<uint32_t>())
    {
        fbHandle = presentSettings.framebufferHandle.UncheckedGet<uint32_t>();
    }
    return HgiPresentGLInteropHandle { fbHandle };
#else
    TF_WARN("OpenGL interop not available");
    return HgiPresentNullInteropHandle {};
#endif
}

HgiPresentWindowParams _GetWindowDestination(
    RenderBufferSettingsProvider const& bufferSettings, BasicLayerParams const& layerConfig)
{
    PresentationParams const& presentParams = bufferSettings.GetPresentationParams();
    HgiPresentWindowParams windowParams {};
    windowParams.wantVsync = presentParams.windowVsync;

    if (presentParams.windowHandle.IsHolding<HgiPresentWindowHandle>())
    {
        windowParams.window = presentParams.windowHandle.UncheckedGet<HgiPresentWindowHandle>();
    }
    else
    {
        TF_CODING_ERROR("Invalid window handle in PresentationParams::windowHandle VtValue.");
    }

    std::string colorSpace = layerConfig.colorspace;
    if (colorSpace.empty() || colorSpace == HdxColorCorrectionTokens->disabled)
    {
        windowParams.srcColorSpace     = GfColorSpaceNames->LinearRec709;
        windowParams.surfaceColorSpace = GfColorSpaceNames->SRGBRec709;
    }
    else if (colorSpace == HdxColorCorrectionTokens->sRGB)
    {
        windowParams.srcColorSpace     = GfColorSpaceNames->SRGBRec709;
        windowParams.surfaceColorSpace = GfColorSpaceNames->SRGBRec709;
    }
    else if (colorSpace == HdxColorCorrectionTokens->openColorIO)
    {
        windowParams.srcColorSpace     = GfColorSpaceNames->Raw;
        windowParams.surfaceColorSpace = GfColorSpaceNames->Raw;
    }
    else
    {
        TF_CODING_ERROR("Unknown color correction mode token");
    }

    return windowParams;
}

HgiPresentInteropParams _GetInteropDestination(
    RenderBufferSettingsProvider const& bufferSettings, BasicLayerParams const& layerConfig)
{
    PresentationParams const& presentParams = bufferSettings.GetPresentationParams();
    GfVec2i renderSize = bufferSettings.GetRenderBufferSize();

    HgiPresentInteropParams dstParams;
    if (presentParams.compositionParams.IsHolding<HgiPresentCompositionParams>())
    {
        dstParams.composition =
            presentParams.compositionParams.UncheckedGet<HgiPresentCompositionParams>();
    }
    else
    {
        dstParams.composition.colorSrcBlendFactor = HgiBlendFactorOne;
        dstParams.composition.colorDstBlendFactor = HgiBlendFactorOneMinusSrcAlpha;
        dstParams.composition.colorBlendOp        = HgiBlendOpAdd;
        dstParams.composition.alphaSrcBlendFactor = HgiBlendFactorOne;
        dstParams.composition.alphaDstBlendFactor = HgiBlendFactorOneMinusSrcAlpha;
        dstParams.composition.alphaBlendOp        = HgiBlendOpAdd;
        dstParams.composition.depthFunc = _GetDepthComparisonMode(layerConfig);
    }

    dstParams.composition.dstRegion = GfRect2i({ 0, 0 }, renderSize[0], renderSize[1]);
    dstParams.destination = _GetInteropTarget(presentParams);
    return dstParams;
}
