    #define SSPI_CLK_CLR()          digitalWrite(_clk, LOW)
#endif
#define SSPI_TRANS_START()
#define SSPI_TRANS_END()
#define SSPI_TX(val)               _spiSend(val)
#define SSPI_TX16(s)             SSPI_TX((s) >> 8); SSPI_TX(s)
#define SSPI_TX32(l)             SSPI_TX((l) >> 24); SSPI_TX((l) >> 16); SSPI_TX((l) >> 8); SSPI_TX(l)
#define SSPI_TX_BLOCKS(c,l)      for(uint32_t i=0; i<(l); i+=2){ SSPI_TX(((uint8_t*)(c))[i+1]); SSPI_TX(((uint8_t*)(c))[i]); }
