    #define HSPI_TRANS_END()   SPI_OBJ.endTransaction()
#else
    #define HSPI_TRANS_START() HSPI_CONFIG_CLOCK(); SPI_OBJ.setBitOrder(MSBFIRST); SPI_OBJ.setDataMode(SPI_MODE0)
