    #define HSPI_TX16(s)          SPI_OBJ.write16(s)
    #define HSPI_TX32(l)          SPI_OBJ.write32(l)
    #ifdef SPI_SUPPORT_BLOCK_WRITE
        #define MAX_PIXELS_PER_XFER  32
        #define HSPI_TX_BLOCKS(c,l)   SPI_OBJ.writePixels(c,l)
    #else
        #define HSPI_TX_BLOCKS(c,l)   for(uint32_t i=0; i<((l)/2); i++){ HSPI_TX16(((uint16_t*)(c))[i]); }
    #endif
#elif defined ( __STM32F1__ )
    #define HSPI_TX(b)            SPI_OBJ.write(b)
    #define HSPI_TX16(s)          SPI_OBJ.write16(s)
#else
    // Standard Byte-by-Byte SPI
    #if defined(__AVR_ATmega4809__)
    static inline uint8_t _avr_spi_recv(void) __attribute__((always_inline));
    static inline uint8_t _avr_spi_recv(void) {
        uint8_t r = 0;
        SPI0_DATA = r;
        while(!(SPI0_INTFLAGS & _BV(SPI_IF_bp)));
        r = SPI0_DATA;
        return r;
    }
        #define HSPI_TX(b)        {SPI0_DATA = (b); while(!(SPI0_INTFLAGS & _BV(SPI_IF_bp)));}
        // #define HSPI_RX()          _avr_spi_recv()
    #elif defined (__AVR__) || defined(TEENSYDUINO)
        static inline uint8_t _avr_spi_recv(void) __attribute__((always_inline));
        static inline uint8_t _avr_spi_recv(void) {
            uint8_t r = 0;
            SPDR = r;
            while(!(SPSR & _BV(SPIF)));
            r = SPDR;
            return r;
        }
        #define HSPI_TX(b)        {SPDR = (b); while(!(SPSR & _BV(SPIF)));}
