extern "C" void PaletteAnimationHook(winscurkMDIClient *clientPtr) {
    TBC45XPalette *palette;
    TBC45XClientDC clientDC;
    TBC45XMDIChild *activeChild;
    HWND targetOne, targetTwo, targetThree;
    unsigned redrawFlags;
    BOOL needsRedraw, skipChildren;

    needsRedraw = FALSE;

    if (!IsIconic(clientPtr->pWnd->HWindow)) {
        palette = GameMain_winscurkApp_GetPalette_SCURK1996(gScurkApplication_SCURK1996);
        GameMain_BCClientDC_Construct_SCURK1996(&clientDC, clientPtr->pWnd->HWindow);
        GameMain_BCDC_SelectObjectPalette_SCURK1996(&clientDC, palette, 0);

        if (colorFastCounter_SCURK1996 == 5) {
            GameMain_winscurkMDIClient_RotateColors_SCURK1996(clientPtr, 1);
            AnimatePalette((HPALETTE)palette->Handle, 0xAB, 0x31, clientPtr->mFastColors);
            colorFastCounter_SCURK1996 = 0;
            needsRedraw = TRUE;
        }

        if (colorSlowCounter_SCURK1996 == 30) {
            GameMain_winscurkMDIClient_RotateColors_SCURK1996(clientPtr, 0);
            AnimatePalette((HPALETTE)palette->Handle, 0xE0, 0x10, clientPtr->mSlowColors);
            colorSlowCounter_SCURK1996 = 0;
            needsRedraw = TRUE;
        }

        ++colorFastCounter_SCURK1996;
        ++colorSlowCounter_SCURK1996;
        GameMain_BCWindowDC_Destruct_SCURK1996(&clientDC, 0);

        if (needsRedraw) {
            activeChild = GameMain_BCMDIClient_GetActiveMDIChild_SCURK1996(clientPtr);
            if (activeChild) {
                skipChildren = FALSE;
                targetOne = 0;
                targetTwo = 0;
                targetThree = 0;

                if (activeChild == (TBC45XMDIChild *)clientPtr->mPlaceWindow) {
                    targetOne = clientPtr->mPlaceWindow->__wndHead.pWnd->HWindow;
                    if (clientPtr->mPlaceWindow->pPlaceTileListDlg && clientPtr->mPlaceWindow->pPlaceTileListDlg->pListBox)
                        targetTwo = clientPtr->mPlaceWindow->pPlaceTileListDlg->pListBox->HWindow;
                }
                else if (activeChild == (TBC45XMDIChild *)clientPtr->mMoverWindow) {
                    if (clientPtr->mMoverWindow->pTileSourceWindow)
                        targetOne = clientPtr->mMoverWindow->pTileSourceWindow->HWindow;
                    if (clientPtr->mMoverWindow->pTileWorkingWindow)
                        targetTwo = clientPtr->mMoverWindow->pTileWorkingWindow->HWindow;
                }
                else if (activeChild == (TBC45XMDIChild *)clientPtr->mEditWindow) {
                    skipChildren = TRUE;
                    targetOne = clientPtr->mEditWindow->__wndHead.pWnd->HWindow;
                    if (clientPtr->mEditWindow->pPaintWindow)
                        targetTwo = clientPtr->mEditWindow->pPaintWindow->HWindow;
                    if (clientPtr->mEditWindow->pPaletteWindow)
                        targetThree = clientPtr->mEditWindow->pPaletteWindow->HWindow;
                }

                redrawFlags = RDW_INVALIDATE;
                if (!skipChildren)
                    redrawFlags |= RDW_ALLCHILDREN;

                if (targetOne)
                    RedrawWindow(targetOne, 0, 0, redrawFlags);
                if (targetTwo)
                    RedrawWindow(targetTwo, 0, 0, RDW_ALLCHILDREN | RDW_INVALIDATE);
                if (targetThree)
                    RedrawWindow(targetThree, 0, 0, RDW_ALLCHILDREN | RDW_INVALIDATE);
            }
        }
    }
}

extern "C" void DebugOutputHook(char const *format, ...) {
    va_list arguments;
    int stringLength;
    char* buffer;

    if ((debug_mode & DEBUG_LEVEL_INTERNAL) == 0)
        return;

    va_start(arguments, format);
    stringLength = _vscprintf(format, arguments) + 1;
    buffer = (char*)malloc(stringLength);

    if (buffer) {
        vsprintf_s(buffer, stringLength, format, arguments);
        ConsoleLog(LOG_DEBUG, "0x%06X -> gDebugOut(): %s", _ReturnAddress(), buffer);
        free(buffer);
    }
    va_end(arguments);
}

extern "C" void SetupPlaceDialog(TPlaceTileListDlg *dialogPtr) {
    char tileString[81];
    int itemIndex, maxItems;
    int indexValue;
    int scrollWidth, dialogRight, dialogBottom, listWidth, listHeight;
    TBC45XRect dialogRect;

    if ((debug_mode & DEBUG_LEVEL_PICKPLACE) != 0)
        ConsoleLog(LOG_DEBUG, "0x%06X -> PlaceTileListDlg_SetupWindow(0x%06X)\n", _ReturnAddress(), dialogPtr);

    strcpy_s(tileString, sizeof(tileString) - 1, "Tile");
    GameMain_BCDialog_SetupWindow_SCURK1996(dialogPtr);

    scrollWidth = GetSystemMetrics(SM_CXHSCROLL);

    // Resize the dialog window
    GetClientRect(dialogPtr->pWnd->HWindow, &dialogRect);
    dialogRight = dialogPtr->nMaxHitArea + scrollWidth - dialogRect.right;
    dialogBottom = dialogPtr->nLBButtonWidth - dialogRect.bottom;
    GetWindowRect(dialogPtr->pWnd->HWindow, &dialogRect);

    dialogRect.right += dialogRight + 8;
    dialogRect.bottom += dialogBottom + 8;

    SetWindowPos(dialogPtr->pWnd->HWindow, HWND_TOP, 
                 dialogRect.left, dialogRect.top, 
                 dialogRect.right - dialogRect.left, 
                 dialogRect.bottom - dialogRect.top, 
                 SWP_NOZORDER | SWP_NOMOVE);

    // Resize the listbox control
    listWidth = (dialogRect.right - dialogRect.left) - 8;
    listHeight = (dialogRect.bottom - dialogRect.top) - 8;

    GetClientRect(dialogPtr->pWnd->HWindow, &dialogRect);
    SetWindowPos(dialogPtr->pListBox->HWindow, HWND_TOP, 
                 dialogRect.left + 3, dialogRect.top + 3, 
                 listWidth - 4, listHeight + 2, 
                 SWP_NOZORDER);

    GameMain_BCWindow_HandleMessage_SCURK1996(dialogPtr->pListBox, LB_SETCOLUMNWIDTH, dialogPtr->nMaxHitArea, 0);

    maxItems = wTileObjects_SCURK1996[3 * dialogPtr->mNumTiles] + wTileObjects_SCURK1996[3 * dialogPtr->mNumTiles + 1] - 1;

    if ((debug_mode & DEBUG_LEVEL_PICKPLACE) != 0)
        ConsoleLog(LOG_DEBUG, "dialogPtr->mNumTiles(%d), maxItems(%d), dialogPtr->nTileRow(%d)\n", 
                   dialogPtr->mNumTiles, maxItems, dialogPtr->nTileRow);

    for (itemIndex = wTileObjects_SCURK1996[3 * dialogPtr->mNumTiles]; maxItems > itemIndex; itemIndex += dialogPtr->nTileRow) {
        sprintf_s(tileString, sizeof(tileString) - 1, "Tile%04d%04d", itemIndex, itemIndex + dialogPtr->nTileRow - 1);
        indexValue = GameMain_BCListBox_AddString_SCURK1996(dialogPtr->pListBox, tileString);

        if ((debug_mode & DEBUG_LEVEL_PICKPLACE) != 0)
            ConsoleLog(LOG_DEBUG, "itemIndex(%d), tileString[%s], indexValue(%d)\n", 
                       itemIndex, tileString, indexValue);

        GameMain_BCListBox_SetItemData_SCURK1996(dialogPtr->pListBox, indexValue, itemIndex);
    }
}

extern "C" void HandleDoubleClick(TPlaceTileListDlg *dialogPtr) {
    int currentRow;
