extern "C" void __declspec(naked) AdjustMoverWindowStyle(void) {
    TBC45XWindow *windowPtr;
    __asm {
        mov eax, [ebx + 0x4]
        mov [windowPtr], eax
    }

    if ((debug_mode & DEBUG_LEVEL_COPYPLACE) != 0)
        ConsoleLog(LOG_DEBUG, "0x%06X -> DisableMaximizeBox()\n", _ReturnAddress());

    if (GetSystemMetrics(SM_CXSCREEN) > 700)
        windowPtr->Attr.Style &= ~WS_MAXIMIZEBOX;
    else
        windowPtr->Attr.Style |= WS_MAXIMIZE;

    __asm {
        mov eax, windowPtr
        mov [ebx + 0x4], eax
    }
    GAMEJMP(0x44E55A);
}

extern "C" void HandleMinMaxInfo(winscurkMoverWindow *moverPtr, MINMAXINFO *infoPtr) {
    LONG screenCX, width, height;

    GameMain_BCWindow_DefaultProcessing_SCURK1996(moverPtr->__wndHead.pWnd);
