    else {
        width = 640;
        height = 480;
    }

    infoPtr->ptMinTrackSize.x = width;
    infoPtr->ptMinTrackSize.y = height;
    infoPtr->ptMaxPosition.x = 0;
    infoPtr->ptMaxPosition.y = 0;
    infoPtr->ptMaxSize.x = width;
    infoPtr->ptMaxSize.y = height;
    infoPtr->ptMaxTrackSize.x = width;
    infoPtr->ptMaxTrackSize.y = height;
}

static char *ProcessCommandLineArguments(char *mainPath, char *cmdParams, BOOL *isValidFile) {
    int argumentCount;
    std::string commandLine;
    static char fileArgument[MAX_PATH + 1];

    memset(fileArgument, 0, sizeof(fileArgument));
    commandLine = "\"";
    commandLine += mainPath;
    commandLine += "\" ";
    commandLine += cmdParams;

    std::wstring wideString(commandLine.begin(), commandLine.end());
    LPWSTR *argvList;

    argvList = CommandLineToArgvW(wideString.c_str(), &argumentCount);

    if (argvList) {
        WideCharToMultiByte(CP_UTF8, 0, argvList[argumentCount - 1], -1, fileArgument, MAX_PATH, NULL, NULL);
        _strlwr_s(fileArgument, sizeof(fileArgument) - 1);
        free(argvList);
    }

    *isValidFile = FALSE;

    if (argumentCount > 1) {
        if (strlen(fileArgument) > 0) {
            if (L_IsPathValid(fileArgument))
                *isValidFile = TRUE;
        }
    }

    return fileArgument;
}

extern "C" void __declspec(naked) __cdecl FixCommandLineHook(void) {
    int argCount;
    char **argList;

    __asm {
        mov [argCount], ebx
        mov eax, [ebp+0xC]
        mov [argList], eax
    }

    BOOL validFileFlag;
    char *result;

    validFileFlag = FALSE;

    if (argCount >= 2)
        result = ProcessCommandLineArguments(argList[0], TAppInitCmdLine_SCURK1996->p->array, &validFileFlag);

    if (!validFileFlag)
        result = NULL;

    _chdir(szGamePath);

    __asm {
        mov esi, [result]
    }

    GAMEJMP(0x45A7F6);
}

