    // Structure to cache hitbox data and avoid redundant lookups
    struct HitboxCacheEntry {
        int headBoneIndex = -1;
        int footBoneIndex = -1;
        bool isCacheValid = false;
        void* previousModelPointer = nullptr;
        void Reset() {
            headBoneIndex = -1;
            footBoneIndex = -1;
            isCacheValid = false;
            previousModelPointer = nullptr;
        }
    };

    // Persistent cache across frames
    static HitboxCacheEntry s_BoneCache[65] = {};

    // Helper: Determine if a point lies within the camera frustum (basic test)
    inline bool IsWithinFrustum(const Vector3& position, const XMMATRIX& viewProjection, float tolerance = 1.2f) {
        XMVECTOR worldPos = XMVectorSet(position.x, position.y, position.z, 1.0f);
        XMVECTOR clipPos = XMVector4Transform(worldPos, viewProjection);

        float wComponent = XMVectorGetW(clipPos);
        if (wComponent <= 0.01f) return false; // Behind camera

        float xCoord = XMVectorGetX(clipPos) / wComponent;
        float yCoord = XMVectorGetY(clipPos) / wComponent;

        return (xCoord >= -tolerance && xCoord <= tolerance &&
                yCoord >= -tolerance && yCoord <= tolerance);
    }

    void Esp::Render(ImVec2 windowSize, ImVec2 mousePosition, bool bMouseUp, View3D* cameraView) {
        auto pDrawList = ImGui::GetForegroundDrawList();
        auto pEntitySystem = ::CS2::I::pGameResourceService->GetGameEntitySystem();
        auto CameraMatrix = ConvertToXMMATRIX(::CS2::ViewMatrixResolver::GetViewMatrix());

        cameraView->SetViewMatrix(CameraMatrix);

        XMMATRIX combinedMatrix = CameraMatrix;

        // Iterate through all possible entities
        for (int index = 1; index < 65; ++index) {
            auto entity = &::CS2::CGameEntitySystem::vEntityList[index];

            if (!entity->m_bIsValid || !entity->m_bIsAlive)
                continue;

            if (!entity->m_pPawn)
                continue;

            if (entity->m_bIsLocalPlayer)
                continue;

            if (entity->m_iBoneCount < 0)
                continue;

            if (entity->headBoneIdx < 0)
                continue;

            auto& cache = s_BoneCache[index];
            void* currentModelAddress = entity->m_pPawn->GetCModel_Imp();

            if (!cache.isCacheValid || cache.previousModelPointer != currentModelAddress) {
                auto pHitboxData = ::CS2::pModelManager->GetHitboxAndBoneData((::CS2::resourcesystem::CModel_Imp*)currentModelAddress);

                // Retrieve bone indices from hitbox data
                auto pHeadHbx = pHitboxData.m_Hitboxes["head_0"];
                auto pFootHbx = pHitboxData.m_Hitboxes["ankle_r"];

                cache.headBoneIndex = pHeadHbx.m_iBoneIdx;
                cache.footBoneIndex = pFootHbx.m_iBoneIdx;
                cache.previousModelPointer = currentModelAddress;
                cache.isCacheValid = true;
            }

            if (cache.headBoneIndex < 0 || cache.footBoneIndex < 0)
                continue;

            auto boneMatrices = entity->m_pPawn->GetGameSceneNodeExtended()->pGameSceneNodeBonePtr->m_Bones;
            auto vHeadPosition = boneMatrices[cache.headBoneIndex].GetOrigin();
            auto vFootPosition = boneMatrices[cache.footBoneIndex].GetOrigin();

            Vector3 midPoint = { vHeadPosition.x, vHeadPosition.y, (vHeadPosition.z + vFootPosition.z) / 2.0f };
            if (!IsWithinFrustum(midPoint, combinedMatrix)) {
                continue;
            }

            float bodyHeight = vHeadPosition.z - vFootPosition.z;

            XMFLOAT4 outlineColor = (entity->m_pPawn->m_iTeamNum == 2)
                ? XMFLOAT4(235.f / 255.f, 35.f / 255.f, 0.f / 255.f, 1.0f)
                : XMFLOAT4(0.f / 255.f, 35.f / 255.f, 235.f / 255.f, 1.0f);

            Vector3 boxCenter = { midPoint.x, midPoint.y, midPoint.z + 2.0f };
            Vector3 boxDimensions = { 30.0f, 30.0f, bodyHeight + 12.0f };

            cameraView->DrawBox(boxCenter, boxDimensions, { 0.35f, 0.35f, 0.35f, 0.2f });
            cameraView->DrawWireBox(boxCenter, boxDimensions, outlineColor);

            // DrawHealthBarScreenAligned(cameraView, {vHeadPosition.x, vHeadPosition.y, vHeadPosition.z}, entity->m_pPawn->m_iMaxHealth, entity->m_pPawn->m_iHealth, {5.0f, 5.0f, bodyHeight});
        }
    }

    void Esp::DrawHealthBarWorldLeft(View3D* view3D, const XMFLOAT3& entityPosition, float maxHealth, float curHealth, const XMFLOAT3& dimensions)
    {
        float ratio = curHealth / maxHealth;

        // Use world-space left direction (global -X axis)
        XMVECTOR leftDirection = XMVectorSet(-1.0f, 0.0f, 0.0f, 0.0f);

        // Offset the bar from entity center
        float offsetAmount = dimensions.x * 0.5f + 0.5f;
        XMVECTOR posVector = XMLoadFloat3(&entityPosition);
        XMVECTOR adjustedPos = posVector + leftDirection * offsetAmount;

        // Background bar (full height)
        XMFLOAT3 bgCenter;
        XMStoreFloat3(&bgCenter, adjustedPos);
        view3D->DrawBox({ bgCenter.x, bgCenter.y, bgCenter.z }, { dimensions.x, dimensions.y, dimensions.z }, { 0.35f, 0.35f, 0.35f, 0.86f });

        // Filled portion (vertical, top aligned)
        float filledHeight = dimensions.z * ratio;
        XMFLOAT3 filledCenter;
        XMStoreFloat3(&filledCenter, adjustedPos);
        filledCenter.z -= (dimensions.z - filledHeight) / 2.0f;

        // Health color based on ratio
        XMFLOAT4 fillColors;
        if (ratio > 0.5f) fillColors = { 96.f / 255, 246.f / 255, 113.f / 255, 1.0f };
        else if (ratio > 0.25f) fillColors = { 247.f / 255, 214.f / 255, 103.f / 255, 1.0f };
        else fillColors = { 255.f / 255, 95.f / 255, 95.f / 255, 1.0f };

        view3D->DrawBox({ filledCenter.x, filledCenter.y, filledCenter.z }, { dimensions.x, dimensions.y, filledHeight }, fillColors);
    }

    void Esp::DrawHealthBarScreenAligned(View3D* view3D, const XMFLOAT3& entityPosition, float maxHealth, float curHealth, const XMFLOAT3& dimensions)
    {
        float ratio = curHealth / maxHealth;

        // Extract camera right vector from view matrix
        XMMATRIX viewMatrix = view3D->cpuView;
        XMVECTOR cameraRight = XMVectorSet(viewMatrix.r[0].m128_f32[0], viewMatrix.r[1].m128_f32[0], viewMatrix.r[2].m128_f32[0], 0.0f);

        // Compute left offset relative to camera
        float offsetDistance = dimensions.x * 0.5f + 0.1f;
        XMVECTOR offsetVector = -cameraRight * offsetDistance;

        // Load entity position and apply offset
        XMVECTOR entityPos = XMLoadFloat3(&entityPosition);
        XMVECTOR worldPos = XMVectorAdd(entityPos, offsetVector);

        XMFLOAT3 barCenter;
        XMStoreFloat3(&barCenter, worldPos);

        float width = dimensions.x;
        float depth = dimensions.y;
        float height = dimensions.z;

        // Draw background (full health)
        view3D->DrawBox({ barCenter.x, barCenter.y, barCenter.z }, { width, depth, height }, { 0.35f, 0.35f, 0.35f, 0.86f });

        // Draw filled portion (shrink from top)
        float filledHeight = height * ratio;
        Vector3 adjustedCenter = { barCenter.x, barCenter.y, barCenter.z };
        adjustedCenter.z -= (height - filledHeight) / 2.0f;

        XMFLOAT4 fillColor;
        if (ratio > 0.5f) fillColor = { 96.f / 255, 246.f / 255, 113.f / 255, 1.0f };
        else if (ratio > 0.25f) fillColor = { 247.f / 255, 214.f / 255, 103.f / 255, 1.0f };
        else fillColor = { 255.f / 255, 95.f / 255, 95.f / 255, 1.0f };

        view3D->DrawBox(adjustedCenter, { width, depth, filledHeight }, fillColor);
    }

    void Esp::DrawHealthBarWorld(View3D* view3D, Vector3 topPosition, float MaxHealth, float CurrentHealth, Vector3 size)
    {
        float ratio = CurrentHealth / MaxHealth;

        float width = size.x;
        float depth = size.y;
        float height = size.z;

        // Filled portion (shrink from top)
        float filledHeight = height * ratio;
        Vector3 adjustedCenter = { topPosition.x, topPosition.y, topPosition.z };
        adjustedCenter.z -= (height - filledHeight) / 2.0f;

        // Health color
        XMFLOAT4 fillColor;
        if (ratio > 0.5f) fillColor = { 96.f / 255, 246.f / 255, 113.f / 255, 0.10f };
        else if (ratio > 0.25f) fillColor = { 247.f / 255, 214.f / 255, 103.f / 255, 0.10f };
        else fillColor = { 255.f / 255, 95.f / 255, 95.f / 255, 0.10f };

        view3D->DrawBox(adjustedCenter, { width, depth, filledHeight }, fillColor);
    }
}

