uint64_t ims_operator::as64() const
{
	return *reinterpret_cast<const uint64_t*>(this);
}

void ims_operator::reset()
{
	*reinterpret_cast<uint64_t*>(this) = 0;
	assert(is_undefined());
}


size_t ims_operator::extract_u24() const
{
	return u24[0] | (u24[1] << 8) | (u24[2] << 16);
}

void ims_operator::assign_u24(size_t val)
{
	assert(val < 0x1000000);

	u24[0] = val & 0xFF;
	u24[1] = (val >> 8) & 0xFF;
	u24[2] = (val >> 16) & 0xFF;
}

intptr_t ims_operator::extract_i24() const
{
	let temp = static_cast<intptr_t>(extract_u24());
	if (temp <= 0x7FFFFF) return temp;
	return temp - intptr_t(0x1000000);
}

bool ims_operator::fits_i24(intptr_t val)
{
	return val < 0x800000 && -val <= 0x800000;
}

bool ims_operator::encode_i24(intptr_t val)
{
	if (!fits_i24(val)) {
		return false;
	}

	u24[0] = val & 0xFF;
	u24[1] = (val >> 8) & 0xFF;
	u24[2] = (val >> 16) & 0xFF;

	return true;
}

void ims_operator::store_i32(intptr_t val)
{
	i32 = static_cast<int32_t>(val);
}


void ims_operator::store_u32(size_t val)
{
	u32 = static_cast<uint32_t>(val);
}

