bool ims_operator::is_closed_shape() const
{
	return false;//reserved for future use (e.g., unit ball)
}

bool ims_operator::is_template_type() const
{
	return	tt >= ETYPE::template_first && tt <= ETYPE::template_last;
}

void ims_operator::set_small_integer(int32_t value)
{
	tt = ETYPE::number_imm;
	ts = ESUBTYPE::integer;
	i32 = value;
}

void ims_operator::set_small_fraction(int16_t numer, int16_t denom)
{
	tt = ETYPE::number_imm;
	ts = ESUBTYPE::rational;
	r16[0] = numer;
	r16[1] = denom;
}

bool ims_operator::is_normal_distribution() const
{
	return tt == ETYPE::distribution_int && ts == ESUBTYPE::dist_normal_def;
}

intptr_t ims_operator::get_power_exponent() const
{
	assert(tt == ETYPE::power_imm);
	return extract_i24();
}

intptr_t ims_operator::get_index_value() const
{
	assert(tt == ETYPE::index_imm);
	return extract_i24();
}

size_t ims_operator::get_argument_count() const
{
	return built_in_func::num_args(get_builtin_func());
}

void ims_operator::set_reference_offset(size_t offset_, ESUBTYPE subtype_)
{
	tt = ETYPE::reference;
	ts = subtype_;
	store_u32(offset_);
}

void ims_operator::set_data_offset(size_t offset_)
{
	store_u32(offset_);
}

void ims_operator::configure(ETYPE kind, size_t primary_val, size_t secondary_val)
{
	tt = kind;
	store_u32(primary_val);
	assign_u24(secondary_val);
}

bool ims_operator::decode_integer(int64_t& num, int64_t& den) const
{
	assert(tt == ETYPE::number_imm);

	switch (ts) {

	case ESUBTYPE::integer:
		num = i32;
		den = 1;
		return true;
	case ESUBTYPE::rational:
		num = r16[0];
		den = r16[1];
		return true;
	default:
		return false;
	}
}

