void ims_operator::combine_hash(size_t& accumulator) const
{
	boost::hash_combine(accumulator, tt);

	switch (tt) {
	case ETYPE::reference:
	case ETYPE::unk_reference:
		boost::hash_combine(accumulator, get_data_offset());
		break;
	case ETYPE::number_imm:
		boost::hash_combine(accumulator, ts);
		boost::hash_combine(accumulator, u32);
		break;
	case ETYPE::set_vector:
	case ETYPE::set_permutation:
	case ETYPE::call_built_in:
	case ETYPE::power_imm:
	case ETYPE::index_imm:
		boost::hash_combine(accumulator, extract_i24());
		break;
	case ETYPE::distribution_int:
	case ETYPE::distribution_real:
		boost::hash_combine(accumulator, ts);
		break;
	default:
		break;//additional data may affect hash
	};
}

template<typename T>
bool compare_integers(T lhs, T rhs, intptr_t& diff) 
{
	diff = (intptr_t)lhs - (intptr_t)rhs;
	return diff != 0;
}

intptr_t ims_operator::lexicographic_compare(ims_operator h1, ims_operator h2)
{
	intptr_t cmp = 0;
	if (compare_integers(h1.tt, h2.tt, cmp))return cmp;
	switch (h1.tt) {
	case ETYPE::reference://offset matters only here
	case ETYPE::unk_reference:
		if (compare_integers(h1.get_data_offset(), h2.get_data_offset(), cmp))return cmp;
		break;
	case ETYPE::number_imm: 
		if (compare_integers(h1.ts, h2.ts, cmp))return cmp;
		if (compare_integers(h1.u32, h2.u32, cmp))return cmp;
		break;
	case ETYPE::set_vector:
	case ETYPE::set_permutation:
	case ETYPE::call_built_in:
	case ETYPE::power_imm:
	case ETYPE::index_imm:
		compare_integers(h1.extract_i24(), h2.extract_i24(), cmp);
		break;
	case ETYPE::distribution_int:
	case ETYPE::distribution_real:
		if (compare_integers(h1.ts, h2.ts, cmp))return cmp;
		break;
	default:
		break;
	};
	return cmp;//depends on extra fields
}

size_t ims_operator::data_size() const
{
	switch (tt) {
	case ETYPE::number:
		return 1;
	case ETYPE::distribution_int:
	case ETYPE::distribution_real:
		return 2;//same layout as vector_imm[real, 2]
	case ETYPE::vector_imm:
		return num_args();
	default:
		break;
	};
	return 0;
}

size_t ims_operator::operator_arity() const
{
	switch (tt) {
		//types without additional operator arguments
	case ETYPE::reference:
	case ETYPE::unk_reference:
	case ETYPE::number_imm:
	case ETYPE::undef:
	case ETYPE::number:
	case ETYPE::vector_imm:
	case ETYPE::exchange:
	case ETYPE::inversion:
	case ETYPE::pi:
	case ETYPE::id:
	case ETYPE::empty:
	case ETYPE::this_vector:
		//distribution - same layout as vector_imm[real, 2]
	case ETYPE::distribution_int:
	case ETYPE::distribution_real:
		return 0;
	case ETYPE::power_imm:
	case ETYPE::index_imm:
	case ETYPE::neg:
	case ETYPE::inv:
	case ETYPE::charpoly:
	case ETYPE::set_interval://argument - distribution
	case ETYPE::set_vector:
	case ETYPE::set_permutation:
	case ETYPE::color_style:
	case ETYPE::thickness:
	case ETYPE::set_semigroup://vector
		return 1;
	case ETYPE::power:
		return 2;
	case ETYPE::csg:
		return 4;
	case ETYPE::call_built_in:
		return get_argument_count();
	case ETYPE::call:
	case ETYPE::mul:
	case ETYPE::mod:
	case ETYPE::sum:
	case ETYPE::uni:
	case ETYPE::vector:
	case ETYPE::vector_func:
	case ETYPE::vector_union:
	case ETYPE::companion:
	case ETYPE::diagonal:
	case ETYPE::index:
	case ETYPE::condition:
		return num_args();//dynamic number of operator arguments
	default:
		assert(false);
		return 0;
	};
}

