#ifndef NO_WEBGET
std::string template_fetch_data(inja::Arguments &args)
{
    std::string requested_url = args.at(0)->get<std::string>(), proxy_settings = parseProxy(global.proxyConfig);
    writeLog(0, "Template invoked fetch with URL '" + requested_url + "'.", LOG_LEVEL_INFO);
    return webGet(requested_url, proxy_settings, global.cacheConfig);
}
#endif // NO_WEBGET

int execute_template(const std::string &template_content, const template_args &variables, std::string &result_output, const std::string &base_include_path)
{
    std::string absolute_base_path;
    try
    {
        if(!base_include_path.empty())
            absolute_base_path = std::filesystem::canonical(base_include_path).string();
    }
    catch(std::exception &err)
    {
        writeLog(0, err.what(), LOG_LEVEL_ERROR);
    }

    nlohmann::json payload;
    for(auto &kv_pair : variables.global_vars)
        apply_json_patch(payload["global"], kv_pair.first, kv_pair.second);

    std::string combined_params;
    for(auto &kv_pair : variables.request_params)
    {
        combined_params += kv_pair.first;
        if(!kv_pair.second.empty())
        {
            apply_json_patch(payload["request"], kv_pair.first, kv_pair.second);
            combined_params += "=" + kv_pair.second;
        }
        combined_params += "&";
    }
    if (!combined_params.empty()) {
        combined_params.erase(combined_params.size() - 1);
    }
    apply_json_patch(payload["request"], "_args", combined_params);

    for(auto &kv_pair : variables.local_vars)
        apply_json_patch(payload["local"], kv_pair.first, kv_pair.second);

    inja::Environment engine;
    engine.set_trim_blocks(true);
    engine.set_lstrip_blocks(true);
    engine.set_line_statement("#~#");

    engine.add_callback("UrlEncode", 1, [](inja::Arguments &args)
    {
        std::string input = args.at(0)->get<std::string>();
        return urlEncode(input);
    });

    engine.add_callback("UrlDecode", 1, [](inja::Arguments &args)
    {
        std::string input = args.at(0)->get<std::string>();
        return urlDecode(input);
    });

    engine.add_callback("trim_of", 2, [](inja::Arguments &args)
    {
        std::string text = args.at(0)->get<std::string>(), chars_to_remove = args.at(1)->get<std::string>();
        if(chars_to_remove.empty())
            return text;
        return trimOf(text, chars_to_remove[0]);
    });

    engine.add_callback("trim", 1, [](inja::Arguments &args)
    {
        std::string text = args.at(0)->get<std::string>();
        return trim(text);
    });

    engine.add_callback("find", 2, [](inja::Arguments &args)
    {
        std::string source = args.at(0)->get<std::string>(), target = args.at(1)->get<std::string>();
        return regFind(source, target);
    });

    engine.add_callback("replace", 3, [](inja::Arguments &args)
    {
        std::string source = args.at(0)->get<std::string>(), search = args.at(1)->get<std::string>(), replacement = args.at(2)->get<std::string>();
        if(search.empty() || source.empty())
            return source;
        return regReplace(source, search, replacement);
    });

    engine.add_callback("set", 2, [&payload](inja::Arguments &args)
    {
        std::string key = args.at(0)->get<std::string>(), value = args.at(1)->get<std::string>();
        apply_json_patch(payload, key, value);
        return "";
    });

    engine.add_callback("split", 3, [&payload](inja::Arguments &args)
    {
        std::string content = args.at(0)->get<std::string>(), delimiter = args.at(1)->get<std::string>(), dest = args.at(2)->get<std::string>();
        string_array parts = split(content, delimiter);
        for(size_t idx = 0; idx < parts.size(); idx++)
            apply_json_patch(payload, dest + "." + std::to_string(idx), parts[idx]);
        return "";
    });

    engine.add_callback("append", 2, [&payload](inja::Arguments &args)
    {
        std::string path = args.at(0)->get<std::string>(), value = args.at(1)->get<std::string>(), pointer, current_value;
        inja::convert_dot_to_json_pointer(path, pointer);
        try
        {
            current_value = payload[nlohmann::json::json_pointer(pointer)].get<std::string>();
        }
        catch (std::exception &e)
        {
            // path does not exist, ignore
        }
        current_value.append(value);
        payload[nlohmann::json::json_pointer(pointer)] = current_value;
        return "";
    });

    engine.add_callback("getLink", 1, [](inja::Arguments &args)
    {
        return global.managedConfigPrefix + args.at(0)->get<std::string>();
    });

    engine.add_callback("startsWith", 2, [](inja::Arguments &args)
    {
        return startsWith(args.at(0)->get<std::string>(), args.at(1)->get<std::string>());
    });

    engine.add_callback("endsWith", 2, [](inja::Arguments &args)
    {
        return endsWith(args.at(0)->get<std::string>(), args.at(1)->get<std::string>());
    });

    engine.add_callback("or", -1, [](inja::Arguments &args)
    {
        for(auto iter = args.begin(); iter != args.end(); iter++)
            if((*iter)->get<int>())
                return true;
        return false;
    });

    engine.add_callback("and", -1, [](inja::Arguments &args)
    {
        for(auto iter = args.begin(); iter != args.end(); iter++)
            if(!(*iter)->get<int>())
                return false;
        return true;
    });

    engine.add_callback("bool", 1, [](inja::Arguments &args)
    {
        std::string val = args.at(0)->get<std::string>();
        std::transform(val.begin(), val.end(), val.begin(), [](unsigned char c) { return std::tolower(c); });
        switch(hash_(val))
        {
        case "true"_hash:
        case "1"_hash:
            return 1;
        default:
            return 0;
        }
    });

    engine.add_callback("string", 1, [](inja::Arguments &args)
    {
        return std::to_string(args.at(0)->get<int>());
    });

#ifndef NO_WEBGET
    engine.add_callback("fetch", 1, template_fetch_data);
#endif // NO_WEBGET

    engine.set_include_callback([&](const std::string &name, const std::string &template_name)
    {
        std::string absolute_file_path;
        try
        {
            absolute_file_path = std::filesystem::canonical(template_name).string();
        }
        catch(std::exception &e)
        {
            throw inja::FileError(e.what());
        }
        if(!absolute_base_path.empty() && !startsWith(absolute_file_path, absolute_base_path))
            throw inja::FileError("access denied when trying to include '" + template_name + "': out of scope");
        return engine.parse(fileGet(template_name, true));
    });

    engine.set_search_included_templates_in_files(false);

    try
    {
        std::stringstream buffer;
        engine.render_to(buffer, engine.parse(template_content), payload);
        result_output = buffer.str();
        return 0;
    }
    catch (std::exception &e)
    {
        result_output = "Template render failed! Reason: " + std::string(e.what());
        writeLog(0, result_output, LOG_LEVEL_ERROR);
        return -1;
    }
    return -2;
}

const std::string clash_script_template = R"(def main(ctx, md):
  host = md["host"]
{% for rule in rules %}
{% if rule.set == "true" %}{% include "group_template" %}{% endif %}
{% endfor %}
{% if exists("geoips") %}  geoips = { {{ geoips }} }
  ip = md["dst_ip"]
  if ip == "":
    ip = ctx.resolve_ip(host)
    if ip == "":
      ctx.log('[Script] dns lookup error use {{ match_group }}')
      return "{{ match_group }}"
  for key in geoips:
    if ctx.geoip(ip) == key:
      return geoips[key]{% endif %}
  return "{{ match_group }}")";

const std::string clash_script_group_template = R"({% if (rule.has_domain == "false" and rule.has_ipcidr == "false") or rule.original == "true" %}  if ctx.rule_providers["{{ rule.name }}"].match(md):
    ctx.log('[Script] matched {{ rule.group }} rule')
    return "{{ rule.group }}"{% else %}{% if rule.has_domain == "true" %}  if ctx.rule_providers["{{ rule.name }}_domain"].match(md):
    ctx.log('[Script] matched {{ rule.group }} DOMAIN rule')
    return "{{ rule.group }}"{% endif %}
{% if not rule.keyword == "" %}{% include "keyword_template" %}{% endif %}
{% if rule.has_ipcidr == "true" %}  if ctx.rule_providers["{{ rule.name }}_ipcidr"].match(md):
    ctx.log('[Script] matched {{ rule.group }} IP rule')
    return "{{ rule.group }}"{% endif %}{% endif %})";

const std::string clash_script_keyword_template = R"(  keywords = [{{ rule.keyword }}]
  for keyword in keywords:
    if keyword in host:
      ctx.log('[Script] matched {{ rule.group }} DOMAIN-KEYWORD rule')
      return "{{ rule.group }}")";

std::string extract_filename(const std::string &filepath)
{
    string_size slash_pos = filepath.rfind('/');
    if(slash_pos == std::string::npos)
    {
        slash_pos = filepath.rfind('\\');
        if(slash_pos == std::string::npos)
            slash_pos = 0;
    }
    string_size dot_pos = filepath.rfind('.');
    if(dot_pos < slash_pos || dot_pos == std::string::npos)
        dot_pos = filepath.size();
    return filepath.substr(slash_pos + 1, dot_pos - slash_pos - 1);
}

int generate_clash_script(YAML::Node &config_base, std::vector<RulesetContent> &ruleset_list, const std::string &base_remote_prefix, bool enable_script, bool override_original_rules, bool use_classical_ruleset)
{
    nlohmann::json data_store;
    std::string default_group, geoip_entries, fetched_rules;
    std::string line_buffer, group_name, rule_path, typed_rule_path, rule_key, prev_rule_key;
    std::stringstream stream_buffer;
    string_array temp_array, group_list;
    string_map keyword_map, url_map, name_map;
    std::map<std::string, bool> domain_flag, ipcidr_flag;
    std::map<std::string, int> update_interval_map, rule_category;
    string_array final_rules;
    int counter = 0;

    if(!override_original_rules && config_base["rules"].IsDefined())
        final_rules = safe_as<string_array>(config_base["rules"]);

    for(RulesetContent &entry : ruleset_list)
    {
        group_name = entry.rule_group;
        rule_path = entry.rule_path;
        typed_rule_path = entry.rule_path_typed;

        if(rule_path.empty())
        {
            line_buffer = entry.rule_content.get().substr(2);
            if(enable_script)
            {
                if(startsWith(line_buffer, "MATCH") || startsWith(line_buffer, "FINAL"))
                    default_group = group_name;
                else if(startsWith(line_buffer, "GEOIP"))
                {
                    temp_array = split(line_buffer, ",");
                    if(temp_array.size() < 2)
                        continue;
                    geoip_entries += "\"" + temp_array[1] + "\": \"" + group_name + "\",";
                }
                continue;
            }
            if(startsWith(line_buffer, "FINAL"))
                line_buffer.replace(0, 5, "MATCH");
            line_buffer += "," + group_name;
            if(count_least(line_buffer, ',', 3))
                line_buffer = regReplace(line_buffer, "^(.*?,.*?)(,.*)(,.*)$", "$1$3$2");
            final_rules.emplace_back(std::move(line_buffer));
            continue;
        }
        else
        {
            if(entry.rule_type == RULESET_CLASH_IPCIDR || entry.rule_type == RULESET_CLASH_DOMAIN || entry.rule_type == RULESET_CLASH_CLASSICAL)
            {
                rule_key = prev_rule_key = urlDecode(extract_filename(rule_path));
                int seq = 2;
                while(std::find(group_list.begin(), group_list.end(), rule_key) != group_list.end())
                    rule_key = prev_rule_key + " " + std::to_string(seq++);
                name_map[rule_key] = group_name;
                url_map[rule_key] = "*" + rule_path;
                rule_category[rule_key] = entry.rule_type;
                update_interval_map[rule_key] = entry.update_interval;
                switch(entry.rule_type)
                {
                case RULESET_CLASH_IPCIDR:
                    ipcidr_flag[rule_key] = true;
                    break;
                case RULESET_CLASH_DOMAIN:
                    domain_flag[rule_key] = true;
                    break;
                case RULESET_CLASH_CLASSICAL:
                    break;
                }
                if(!enable_script)
                    final_rules.emplace_back("RULE-SET," + rule_key + "," + group_name);
                group_list.emplace_back(rule_key);
                continue;
            }
            if(!base_remote_prefix.empty())
            {
                if(fileExist(rule_path, true) || isLink(rule_path))
                {
                    rule_key = prev_rule_key = urlDecode(extract_filename(rule_path));
                    int seq = 2;
                    while(std::find(group_list.begin(), group_list.end(), rule_key) != group_list.end())
                        rule_key = prev_rule_key + " " + std::to_string(seq++);
                    name_map[rule_key] = group_name;
                    url_map[rule_key] = typed_rule_path;
                    rule_category[rule_key] = entry.rule_type;
                    update_interval_map[rule_key] = entry.update_interval;
                    if(use_classical_ruleset)
                    {
                        if(!enable_script)
                            final_rules.emplace_back("RULE-SET," + rule_key + "," + group_name);
                        group_list.emplace_back(rule_key);
                        continue;
                    }
                }
                else
                    continue;
            }
            fetched_rules = entry.rule_content.get();
            if(fetched_rules.empty())
            {
                writeLog(0, "Failed to fetch ruleset or ruleset is empty: '" + entry.rule_path + "'!", LOG_LEVEL_WARNING);
                continue;
            }
            fetched_rules = convertRuleset(fetched_rules, entry.rule_type);
            char delimiter = getLineBreak(fetched_rules);
            stream_buffer.clear();
            stream_buffer<<fetched_rules;
            std::string::size_type line_length;
            bool no_resolve_found = false;
            while(getline(stream_buffer, line_buffer, delimiter))
            {
                line_length = line_buffer.size();
                if(line_length && line_buffer[line_length - 1] == '\r')
                    line_buffer.erase(--line_length);
                if(!line_length || line_buffer[0] == ';' || line_buffer[0] == '#' || (line_length >= 2 && line_buffer[0] == '/' && line_buffer[1] == '/'))
                    continue;
                if(startsWith(line_buffer, "DOMAIN-KEYWORD,"))
                {
                    if(enable_script)
                    {
                        temp_array = split(line_buffer, ",");
                        if(temp_array.size() < 2)
                            continue;
                        if(keyword_map.find(rule_key) == keyword_map.end())
                            keyword_map[rule_key] = "\"" + trim(temp_array[1]) + "\"";
                        else
                            keyword_map[rule_key] += ",\"" + trim(temp_array[1]) + "\"";
                    }
                    else
                    {
                        temp_array = split(line_buffer, ",");
                        if(temp_array.size() < 2)
                        {
                            line_buffer = temp_array[0] + "," + group_name;
                        }
                        else
                        {
                            line_buffer = temp_array[0] + "," + trim(temp_array[1]) + "," + group_name;
                            if(temp_array.size() > 2)
                                line_buffer += "," + temp_array[2];
                        }
                        final_rules.emplace_back(line_buffer);
                    }
                }
                else if(!domain_flag[rule_key] && (startsWith(line_buffer, "DOMAIN,") || startsWith(line_buffer, "DOMAIN-SUFFIX,")))
                    domain_flag[rule_key] = true;
                else if(!ipcidr_flag[rule_key] && (startsWith(line_buffer, "IP-CIDR,") || startsWith(line_buffer, "IP-CIDR6,")))
                {
                    ipcidr_flag[rule_key] = true;
                    if(line_buffer.find(",no-resolve") != std::string::npos)
                        no_resolve_found = true;
                }
            }
            if(domain_flag[rule_key] && !enable_script)
                final_rules.emplace_back("RULE-SET," + rule_key + " (Domain)," + group_name);
            if(ipcidr_flag[rule_key] && !enable_script)
            {
                if(no_resolve_found)
                    final_rules.emplace_back("RULE-SET," + rule_key + " (IP-CIDR)," + group_name + ",no-resolve");
                else
                    final_rules.emplace_back("RULE-SET," + rule_key + " (IP-CIDR)," + group_name);
            }
            if(!domain_flag[rule_key] && !ipcidr_flag[rule_key] && !enable_script)
                final_rules.emplace_back("RULE-SET," + rule_key + "," + group_name);
            if(std::find(group_list.begin(), group_list.end(), rule_key) == group_list.end())
                group_list.emplace_back(rule_key);
        }
    }

    for(std::string &key : group_list)
    {
        std::string url = url_map[key], keyword = keyword_map[key], name = name_map[key];
        bool has_domain = domain_flag[key], has_ipcidr = ipcidr_flag[key];
        int interval = update_interval_map[key];

        if(has_domain)
        {
            std::string yaml_key = key;
            if(rule_category[key] != RULESET_CLASH_DOMAIN)
                yaml_key += " (Domain)";
            config_base["rule-providers"][yaml_key]["type"] = "http";
            config_base["rule-providers"][yaml_key]["behavior"] = "domain";
            if(url[0] == '*')
                config_base["rule-providers"][yaml_key]["url"] = url.substr(1);
            else
                config_base["rule-providers"][yaml_key]["url"] = base_remote_prefix + "/getruleset?type=3&url=" + urlSafeBase64Encode(url);
            config_base["rule-providers"][yaml_key]["path"] = "./providers/" + std::to_string(hash_(url)) + "_domain.yaml";
            if(interval)
                config_base["rule-providers"][yaml_key]["interval"] = interval;
        }

        if(has_ipcidr)
        {
            std::string yaml_key = key;
            if(rule_category[key] != RULESET_CLASH_IPCIDR)
                yaml_key += " (IP-CIDR)";
            config_base["rule-providers"][yaml_key]["type"] = "http";
            config_base["rule-providers"][yaml_key]["behavior"] = "ipcidr";
            if(url[0] == '*')
                config_base["rule-providers"][yaml_key]["url"] = url.substr(1);
            else
                config_base["rule-providers"][yaml_key]["url"] = base_remote_prefix + "/getruleset?type=4&url=" + urlSafeBase64Encode(url);
            config_base["rule-providers"][yaml_key]["path"] = "./providers/" + std::to_string(hash_(url)) + "_ipcidr.yaml";
            if(interval)
                config_base["rule-providers"][yaml_key]["interval"] = interval;
        }

        if(!has_domain && !has_ipcidr)
        {
            std::string yaml_key = key;
            config_base["rule-providers"][yaml_key]["type"] = "http";
            config_base["rule-providers"][yaml_key]["behavior"] = "classical";
            if(url[0] == '*')
                config_base["rule-providers"][yaml_key]["url"] = url.substr(1);
            else
                config_base["rule-providers"][yaml_key]["url"] = base_remote_prefix + "/getruleset?type=6&url=" + urlSafeBase64Encode(url);
            config_base["rule-providers"][yaml_key]["path"] = "./providers/" + std::to_string(hash_(url)) + ".yaml";
            if(interval)
                config_base["rule-providers"][yaml_key]["interval"] = interval;
        }

        if(enable_script)
        {
            std::string json_path = "rules." + std::to_string(counter) + ".";
            apply_json_patch(data_store, json_path + "has_domain", has_domain ? "true" : "false");
            apply_json_patch(data_store, json_path + "has_ipcidr", has_ipcidr ? "true" : "false");
            apply_json_patch(data_store, json_path + "name", key);
            apply_json_patch(data_store, json_path + "group", name);
            apply_json_patch(data_store, json_path + "set", "true");
            apply_json_patch(data_store, json_path + "keyword", keyword);
            apply_json_patch(data_store, json_path + "original", (rule_category[key] == RULESET_CLASH_DOMAIN || rule_category[key] == RULESET_CLASH_IPCIDR) ? "true" : "false");
        }
        counter++;
    }

    if(enable_script)
    {
        if(!geoip_entries.empty())
            apply_json_patch(data_store, "geoips", geoip_entries.erase(geoip_entries.size() - 1));
        apply_json_patch(data_store, "match_group", default_group);

        inja::Environment env;
        env.include_template("keyword_template", env.parse(clash_script_keyword_template));
        env.include_template("group_template", env.parse(clash_script_group_template));
        inja::Template tmpl = env.parse(clash_script_template);
        try
        {
            std::string script_output = env.render(tmpl, data_store);
            config_base["script"]["code"] = script_output;
        }
        catch (std::exception &e)
        {
            writeLog(0, "Error when rendering: " + std::string(e.what()), LOG_TYPE_ERROR);
            return -1;
        }
    }
    else
        config_base["rules"] = final_rules;

    return 0;
}

