void
UUIDColumnDelegate::paint(QPainter* painter, const QStyleOptionViewItem& option,
                          const QModelIndex& index) const
{
    painter->save();
    QStyleOptionViewItem styleOpt = option;
    initStyleOption(&styleOpt, index); // important: populate styleOpt with index data
    // Draw the background correctly for selected / hovered / keyboard-focus states
    QApplication::style()->drawPrimitive(QStyle::PE_PanelItemViewItem, &styleOpt, painter);
    // Draw the centered icon
    QRect rect = styleOpt.rect;
    QIcon appIcon = QApplication::style()->standardIcon(QStyle::SP_FileDialogDetailedView);
    appIcon.paint(painter, rect, Qt::AlignCenter);
    painter->restore();
}

QSize
UUIDColumnDelegate::sizeHint(const QStyleOptionViewItem& option,
                             const QModelIndex& index) const
{
    Q_UNUSED(option);
    Q_UNUSED(index);
    int iconDimension = QApplication::style()->pixelMetric(QStyle::PM_SmallIconSize, nullptr, nullptr);
    int margin = 6; // extra space
    return QSize(iconDimension + margin, iconDimension + margin);
}

bool
UUIDColumnDelegate::editorEvent(QEvent* event, QAbstractItemModel* model,
                                const QStyleOptionViewItem& option,
                                const QModelIndex& index)
{
    if (!index.isValid())
        return false;
    QString identifier = index.data(Qt::UserRole).toString();
    if (event->type() == QEvent::MouseButtonRelease) {
        if (auto* mouseEvent = dynamic_cast<QMouseEvent*>(event)) {
            if (mouseEvent->button() == Qt::LeftButton) {
                QApplication::clipboard()->setText(identifier);
                QToolTip::showText(mouseEvent->globalPosition().toPoint(),
                                   tr("UUID copied to clipboard."));
                return true;
            }
        }
    }
    return QStyledItemDelegate::editorEvent(event, model, option, index);
}

