namespace
{
    NSVGimage *parse_file(const char *filepath)
    {
        FILE *fp = boost::nowide::fopen(filepath, "rb");
        assert(fp != nullptr);
        if (fp == nullptr)
            return nullptr;
        Slic3r::ScopeGuard sg([fp]() { fclose(fp); });
        fseek(fp, 0, SEEK_END);
        size_t file_size = ftell(fp);
        fseek(fp, 0, SEEK_SET);
        // Note: +1 is for null termination
        auto buffer_ptr = std::make_unique<char[]>(file_size + 1);
        buffer_ptr[file_size] = '\0'; // Must be null terminated.
        size_t bytes_read = fread(buffer_ptr.get(), 1, file_size, fp);
        assert(bytes_read == file_size);
        if (bytes_read != file_size)
            return nullptr;
        return nsvgParse(buffer_ptr.get(), "px", 96.0f);
    }

    void copy_subdata(unsigned char *dst_buffer, size_t dst_stride,
                      const std::vector<unsigned char> &src_data, size_t src_row_width)
    {
        assert(dst_stride >= src_row_width);
        for (size_t src_idx = 0, dst_idx = 0; src_idx < src_data.size();
             src_idx += src_row_width, dst_idx += dst_stride)
            ::memcpy((void *) (dst_buffer + dst_idx), (const void *) (src_data.data() + src_idx), src_row_width);
    }
} // namespace

IconManager::Icons IconManager::init(const InitTypes &input)
{
    assert(!input.empty());
    if (input.empty())
        return {};
    // TODO: remove in future
    if (m_id != 0)
    {
        glsafe(::glDeleteTextures(1, &m_id));
        m_id = 0;
    }

    int total_area = 0;
    for (const InitType &item : input)
        total_area += item.size.x * item.size.y;

    const int sqrt_surface = (int) std::sqrt((float) total_area) + 1;

    // Start packing
    // Pack our extra data rectangles first, so it will be on the upper-left corner of our texture (UV will have small values).
    const int MAX_TEX_HEIGHT = 1024 * 32;
    int tex_width = (sqrt_surface >= 4096 * 0.7f)   ? 4096
                    : (sqrt_surface >= 2048 * 0.7f) ? 2048
                    : (sqrt_surface >= 1024 * 0.7f) ? 1024
                                                    : 512;

    int node_count = tex_width;
    std::vector<stbrp_node> nodes(node_count);
    stbrp_context context;
    stbrp_init_target(&context, tex_width, MAX_TEX_HEIGHT, nodes.data(), node_count);

    ImVector<stbrp_rect> rects;
    rects.resize(input.size());
    memset(rects.Data, 0, (size_t) rects.size_in_bytes());

    for (size_t i = 0; i < input.size(); i++)
    {
        const ImVec2 &dim = input[i].size;
        assert(dim.x > 1);
        assert(dim.y > 1);
        rects[i].w = dim.x;
        rects[i].h = dim.y;
    }

    int pack_result = stbrp_pack_rects(&context, &rects[0], rects.Size);
    assert(pack_result == 1);
    if (pack_result != 1)
        return {};

    ImVec2 actual_tex_size(tex_width, tex_width);
    for (const stbrp_rect &rect : rects)
    {
        float right = rect.x + rect.w;
        float bottom = rect.y + rect.h;
        if (right > actual_tex_size.x)
            actual_tex_size.x = right;
        if (bottom > actual_tex_size.y)
            actual_tex_size.y = bottom;
    }

    Icons output(input.size());
    for (int idx = 0; idx < rects.Size; idx++)
    {
        const stbrp_rect &rect = rects[idx];
        assert(rect.was_packed);
        if (!rect.was_packed)
            return {};
        ImVec2 uv_min(rect.x / actual_tex_size.x, rect.y / actual_tex_size.y);
        ImVec2 uv_max((rect.x + rect.w) / actual_tex_size.x, (rect.y + rect.h) / actual_tex_size.y);
        assert(input[idx].size.x == rect.w);
        assert(input[idx].size.y == rect.h);
        Icon icon = {input[idx].size, uv_min, uv_max};
        output[idx] = std::make_shared<Icon>(std::move(icon));
    }

    NSVGrasterizer *rasterizer = nsvgCreateRasterizer();
    assert(rasterizer != nullptr);
    if (rasterizer == nullptr)
        return {};
    ScopeGuard sg_rast([rasterizer]() { ::nsvgDeleteRasterizer(rasterizer); });

    int channels = 4;
    int pixel_count = (int)(actual_tex_size.x * actual_tex_size.y);
    // store data for whole texture
    std::vector<unsigned char> tex_data(pixel_count * channels, {0});

    // initialize original index locations
    std::vector<size_t> order(input.size());
    std::iota(order.begin(), order.end(), 0);

    // Group same filename by sort inputs
    // sort indexes based on comparing values in input
    std::sort(order.begin(), order.end(),
              [&input](size_t a, size_t b) { return input[a].filepath < input[b].filepath; });

    for (size_t idx : order)
    {
        const InitType &item = input[idx];
        if (item.filepath.empty())
            continue; // no file path only reservation of space for texture

        assert(boost::filesystem::exists(item.filepath));
        if (!boost::filesystem::exists(item.filepath))
            continue;

        assert(boost::algorithm::iends_with(item.filepath, ".svg"));
        if (!boost::algorithm::iends_with(item.filepath, ".svg"))
            continue;

        NSVGimage *svg_image = parse_file(item.filepath.c_str());
        assert(svg_image != nullptr);
        if (svg_image == nullptr)
            return {};
        ScopeGuard sg_image([svg_image]() { ::nsvgDelete(svg_image); });

        float scale_factor = item.size.y / svg_image->height;
        // scale should be same in both directions
        assert(is_approx(scale_factor, item.size.y / svg_image->width));

        const stbrp_rect &rect = rects[idx];
        int icon_pixels = rect.w * rect.h;
        std::vector<unsigned char> icon_buffer(icon_pixels * channels, {0});
        ::nsvgRasterize(rasterizer, svg_image, 0, 0, scale_factor, icon_buffer.data(),
                        item.size.x, item.size.y, item.size.x * channels);

        // makes white or gray only data in icon
        if (item.type == RasterType::white_only_data || item.type == RasterType::gray_only_data)
        {
            unsigned char value = (item.type == RasterType::white_only_data) ? 255 : 127;
            for (size_t k = 0; k < icon_buffer.size(); k += channels)
                if (icon_buffer[k] != 0 || icon_buffer[k + 1] != 0 || icon_buffer[k + 2] != 0)
                {
                    icon_buffer[k] = value;
                    icon_buffer[k + 1] = value;
                    icon_buffer[k + 2] = value;
                }
        }

        int start_offset = (rect.y * actual_tex_size.x + rect.x) * channels;
        int row_stride = actual_tex_size.x * channels;
        copy_subdata(tex_data.data() + start_offset, row_stride, icon_buffer, rect.w * channels);
    }

    if (m_id != 0)
        glsafe(::glDeleteTextures(1, &m_id));
    glsafe(::glPixelStorei(GL_UNPACK_ALIGNMENT, 1));
    glsafe(::glGenTextures(1, &m_id));
    glsafe(::glBindTexture(GL_TEXTURE_2D, (GLuint) m_id));
    glsafe(::glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR));
    glsafe(::glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAX_LEVEL, 0));
    glsafe(::glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR));
    glsafe(::glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA, (GLsizei) actual_tex_size.x, (GLsizei) actual_tex_size.y, 0, GL_RGBA,
                          GL_UNSIGNED_BYTE, (const void *) tex_data.data()));
    // bind no texture
    glsafe(::glBindTexture(GL_TEXTURE_2D, 0));

    for (const auto &icon : output)
        icon->tex_id = m_id;

    return output;
}

std::vector<IconManager::Icons> IconManager::init(const std::vector<std::string> &file_paths, const ImVec2 &dim,
                                                  RasterType mode)
{
    assert(!file_paths.empty());
    assert(dim.x >= 1);
    assert(dim.x < 256 * 16);

    // TODO: remove in future
    if (!m_icons.empty())
    {
        // not first initialization
        priv::clear(m_icons);
        m_icons.clear();
        m_icons_texture.reset();
    }

    // only rectangle are supported
    assert(dim.x == dim.y);
    // no subpixel supported
    unsigned int icon_dim = static_cast<unsigned int>(std::abs(std::round(dim.x)));
    assert(dim.x == static_cast<float>(icon_dim));

    // state order has to match the enum IconState
    const auto &states = priv::get_states(mode);
    bool compress = false;
    bool is_loaded = m_icons_texture.load_from_svg_files_as_sprites_array(file_paths, states, icon_dim, compress);

    if (!is_loaded || (size_t) m_icons_texture.get_width() < (states.size() * icon_dim) ||
        (size_t) m_icons_texture.get_height() < (file_paths.size() * icon_dim))
    {
        // bad load of icons, but all usage of m_icons_texture check that texture is initialized
        assert(false);
        m_icons_texture.reset();
        return {};
    }

    unsigned count_files = file_paths.size();
    // count icons per file
    unsigned count = states.size();

    // create result
    std::vector<Icons> result;
    result.reserve(count_files);
    Icon default_icon;
    default_icon.tex_id = m_icons_texture.get_id();
    default_icon.size = dim;

    // float beacouse of dividing
    float tex_h = static_cast<float>(m_icons_texture.get_height());
    float tex_w = static_cast<float>(m_icons_texture.get_width());

    for (unsigned f = 0; f < count_files; ++f)
    {
        // NOTE: there are space between icons
        unsigned start_y = f * (icon_dim + 1) + 1;
        float y1 = start_y / tex_h;
        float y2 = (start_y + icon_dim) / tex_h;
        Icons file_icons;
        file_icons.reserve(count);

        for (unsigned j = 0; j < count; ++j)
        {
            auto icon = std::make_shared<Icon>(default_icon);
            // NOTE: there are space between icons
            unsigned start_x = j * (icon_dim + 1) + 1;
            float x1 = start_x / tex_w;
            float x2 = (start_x + icon_dim) / tex_w;
            icon->tl = ImVec2(x1, y1);
            icon->br = ImVec2(x2, y2);
            file_icons.push_back(icon);
            m_icons.push_back(std::move(icon));
        }
        result.emplace_back(std::move(file_icons));
    }

    return result;
}

