void priv::clear(IconManager::Icons &icons)
{
    std::string message;
    for (auto &icon : icons)
    {
        // Exist more than this instance of shared ptr?
        long count = icon.use_count();
        if (count != 1)
        {
            // in existing icon change texture to non existing one
            icon->tex_id = 0;
            std::string descr = ((count > 2) ? (std::to_string(count - 1) + "x") : "") +           // count
                                std::to_string(icon->size.x) + "x" + std::to_string(icon->size.y); // resolution
            if (message.empty())
                message = descr;
            else
                message += ", " + descr;
        }
    }
    if (!message.empty())
        BOOST_LOG_TRIVIAL(warning) << "There is still used icons(" << message << ").";
}

const std::vector<std::pair<int, bool>> &priv::get_states(IconManager::RasterType type)
{
    static std::vector<std::pair<int, bool>> color = {std::make_pair(0, false)};
    static std::vector<std::pair<int, bool>> white = {std::make_pair(1, false)};
    static std::vector<std::pair<int, bool>> gray = {std::make_pair(2, false)};
    static std::vector<std::pair<int, bool>> color_white_gray = {
        std::make_pair(1, false), // Activable
        std::make_pair(0, false), // Hovered
        std::make_pair(2, false)  // Disabled
    };

    switch (type)
    {
    case IconManager::RasterType::color:
        return color;
    case IconManager::RasterType::white_only_data:
        return white;
    case IconManager::RasterType::gray_only_data:
        return gray;
    case IconManager::RasterType::color_wite_gray:
        return color_white_gray;
    default:
        return color;
    }
}

void priv::draw_transparent_icon(const IconManager::Icon &icon)
{
    // Check input
    if (!icon.is_valid())
    {
        assert(false);
        BOOST_LOG_TRIVIAL(warning) << "Drawing invalid Icon.";
        ImGui::Text("?");
        return;
    }

    // size UV texture coors [in texture ratio]
    ImVec2 uv_size(icon.br.x - icon.tl.x, icon.br.y - icon.tl.y);
    ImVec2 one_px(uv_size.x / icon.size.x, uv_size.y / icon.size.y);

    // use top left corner of first icon
    IconManager::Icon px_icon = icon; // copy

    // reduce uv coors to one pixel
    px_icon.tl = ImVec2(0, 0);
    px_icon.br = one_px;

    draw(px_icon);
}

#include "imgui/imgui_internal.h" //ImGuiWindow

namespace Slic3r::GUI
{
void draw(const IconManager::Icon &icon, const ImVec2 &size, const ImVec4 &tint_col, const ImVec4 &border_col)
{
    // Check input
    if (!icon.is_valid())
    {
        assert(false);
        BOOST_LOG_TRIVIAL(warning) << "Drawing invalid Icon.";
        ImGui::Text("?");
        return;
    }

    ImTextureID id = (void *) static_cast<intptr_t>(icon.tex_id);
    const ImVec2 &s = (size.x < 1 || size.y < 1) ? icon.size : size;
    ImGui::Image(id, s, icon.tl, icon.br, tint_col, border_col);
}

bool clickable(const IconManager::Icon &icon_normal, const IconManager::Icon &icon_hover)
{
    // check of hover
    ImGuiWindow *window = ImGui::GetCurrentWindow();
    float cursor_x = ImGui::GetCursorPosX() - window->DC.GroupOffset.x - window->DC.ColumnsOffset.x;
    priv::draw_transparent_icon(icon_normal);
    ImGui::SameLine(cursor_x);
    if (ImGui::IsItemHovered())
    {
        // redraw image
        draw(icon_hover);
    }
    else
    {
        // redraw normal image
        draw(icon_normal);
    }
    return ImGui::IsItemClicked();
}

bool button(const IconManager::Icon &activ, const IconManager::Icon &hover, const IconManager::Icon &disable,
            bool disabled)
{
    if (disabled)
    {
        draw(disable);
        return false;
    }
    return clickable(activ, hover);
}
} // namespace Slic3r::GUI

