namespace X11DPI
{
    typedef struct _XDisplay Display;
    typedef Display* (*XOpenDisplayPtr)(const char*);
    typedef char* (*XGetDefaultPtr)(Display*, const char*, const char*);
    typedef int (*XCloseDisplayPtr)(Display*);
}

SDL2DisplayBackend::SDL2DisplayBackend()
{
    int initResult = SDL_Init(SDL_INIT_VIDEO | SDL_INIT_EVENTS | SDL_INIT_JOYSTICK | SDL_INIT_GAMECONTROLLER);
    if (initResult != 0)
        throw std::runtime_error(std::string("Failed to initialize SDL: ") + SDL_GetError());

    SDL2DisplayWindow::PaintEventNumber = SDL_RegisterEvents(1);

    // Attempt to determine DPI manually on Linux/X11 since SDL lacks native HiDPI support there
#if !defined(_WIN32) && !defined(__APPLE__)
    const char* videoDriver = SDL_GetCurrentVideoDriver();
    if (videoDriver && strcmp(videoDriver, "x11") == 0)
    {
        void* libX11 = dlopen("libX11.so", RTLD_NOW | RTLD_LOCAL);
        if (libX11)
        {
            using namespace X11DPI;
            auto openDisplay = (XOpenDisplayPtr)dlsym(libX11, "XOpenDisplay");
            auto getDefault = (XGetDefaultPtr)dlsym(libX11, "XGetDefault");
            auto closeDisplay = (XCloseDisplayPtr)dlsym(libX11, "XCloseDisplay");

            if (openDisplay && getDefault && closeDisplay)
            {
                auto x11Display = openDisplay(nullptr);
                if (x11Display)
                {
                    char* dpiSetting = getDefault(x11Display, "Xft", "dpi");
                    if (dpiSetting)
                    {
                        int dpiValue = std::atoi(dpiSetting);
                        if (dpiValue > 0)
                        {
                            UIScale = static_cast<double>(dpiValue) / 96.0;
                        }
                    }
                    closeDisplay(x11Display);
                }
            }
            dlclose(libX11);
        }
    }
#endif

    for (int index = 0; index < SDL_NumJoysticks(); ++index)
    {
        SDL_GameControllerOpen(index);
    }
}

