size_t  SPrintArg  (char * o_string, size_t i_bufferSize, voidptr_t i_sp, u8 i_type)
{
    int written = 0;
    *o_string = '\0';
    if      (i_type == c_m3Type_i32)
        written = snprintf(o_string, i_bufferSize, "%" PRIi32, *(i32 *)i_sp);
    else if (i_type == c_m3Type_i64)
        written = snprintf(o_string, i_bufferSize, "%" PRIi64, *(i64 *)i_sp);
#if d_m3HasFloat
    else if (i_type == c_m3Type_f32)
        written = snprintf(o_string, i_bufferSize, "%" PRIf32, *(f32 *)i_sp);
    else if (i_type == c_m3Type_f64)
        written = snprintf(o_string, i_bufferSize, "%" PRIf64, *(f64 *)i_sp);
#endif
    written = M3_MAX(0, written);
    return written;
}

cstr_t  SPrintFunctionArgList  (IM3Function i_func, m3stack_t i_sp)
{
    int result;
    static char buffer [256];
    char * pos = buffer;
    ccstr_t end = buffer + sizeof(buffer) - 1;

    result = snprintf(pos, end-pos, "(");
    pos += M3_MAX(0, result);

    u64 * argSp = (u64 *) i_sp;
    IM3FuncType funcType = i_func->funcType;

    if (funcType)
    {
        u32 count = funcType->numArgs;
        for (u32 index = 0; index < count; ++index)
        {
            u8 type = d_FuncArgType(funcType, index);
            result = snprintf(pos, end-pos, "%s: ", c_waTypes[type]);
            pos += M3_MAX(0, result);
            pos += SPrintArg(pos, end-pos, argSp + index, type);

            if (index != count - 1) {
                result = snprintf(pos, end-pos, ", ");
                pos += M3_MAX(0, result);
            }
        }
    }
    else 
        printf("null signature");

    result = snprintf(pos, end-pos, ")");
    pos += M3_MAX(0, result);

    return buffer;
}
#endif

