#include "ggml-backend-impl.h"
#if defined(__s390x__)
#include <sys/auxv.h>
// Determine hardware capabilities for s390x architecture
#ifndef HWCAP_VXRS_EXT2
#define HWCAP_VXRS_EXT2 (1 << 15)
#endif
#ifndef HWCAP_NNPA
#define HWCAP_NNPA (1 << 20)
#endif

struct s390x_cpu_caps {
    bool supports_vxe2 = false;
    bool supports_nnpa = false;
    s390x_cpu_caps() {
        unsigned long hwcap_val = getauxval(AT_HWCAP);
        // Note: consider using hwcap2 for newer features like DFLT on z17+
        // unsigned long hwcap2_val = getauxval(AT_HWCAP2);
        supports_vxe2 = (hwcap_val & HWCAP_VXRS_EXT2) != 0;
        supports_nnpa = (hwcap_val & HWCAP_NNPA) != 0;
    }
};

static int ggml_backend_cpu_s390x_evaluate() {
    int rating = 1;
    s390x_cpu_caps caps;

#ifdef GGML_USE_VXE2
    if (!caps.supports_vxe2) { return 0; }
    rating += 1 << 1;
#endif

#ifdef GGML_USE_NNPA
    if (!caps.supports_nnpa) { return 0; }
    rating += 1 << 2;
#endif

    return rating;
