/*virtual*/ size_t UniversalFileSystem::read_file(const char* path, RNS::Bytes& buffer) {
    size_t bytes_read = 0;

#ifdef ARDUINO
#ifdef BOARD_ESP32
    File handle = SPIFFS.open(path, FILE_READ);
    if (handle) {
        size_t length = handle.size();
        bytes_read = handle.readBytes((char*)buffer.writable(length), length);
#elif defined(BOARD_NRF52)
    File handle = InternalFS.open(path, FILE_O_READ);
    if (handle) {
        size_t length = handle.size();
        bytes_read = handle.readBytes((char*)buffer.writable(length), length);
#else
    if (false) {
        size_t length = 0;
#endif
#else
    FILE* handle = fopen(path, "r");
    if (handle != nullptr) {
        fseek(handle, 0, SEEK_END);
        size_t length = ftell(handle);
        rewind(handle);
        bytes_read = fread(buffer.writable(length), 1, length, handle);
#endif
        TRACE("read_file: read " + std::to_string(bytes_read) + " bytes from file " + std::string(path));
        if (bytes_read != length) {
            ERROR("read_file: failed to read file " + std::string(path));
            buffer.clear();
        }

#ifdef ARDUINO
#ifdef BOARD_ESP32
        handle.close();
#elif defined(BOARD_NRF52)
        handle.close();
#endif
#else
        fclose(handle);
#endif
    } else {
        ERROR("read_file: failed to open input file " + std::string(path));
    }

    return bytes_read;
}

/*virtual*/ size_t UniversalFileSystem::write_file(const char* path, const RNS::Bytes& buffer) {
    remove_file(path);
    size_t bytes_written = 0;

#ifdef ARDUINO
#ifdef BOARD_ESP32
    File handle = SPIFFS.open(path, FILE_WRITE);
    if (handle) {
        bytes_written = handle.write(buffer.data(), buffer.size());
#elif defined(BOARD_NRF52)
    File handle(InternalFS);
    if (handle.open(path, FILE_O_WRITE)) {
        bytes_written = handle.write(buffer.data(), buffer.size());
#else
    if (false) {
#endif
#else
    FILE* handle = fopen(path, "w");
    if (handle != nullptr) {
        bytes_written = fwrite(buffer.data(), 1, buffer.size(), handle);
#endif
        TRACE("write_file: wrote " + std::to_string(bytes_written) + " bytes to file " + std::string(path));
        if (bytes_written < buffer.size()) {
            WARNING("write_file: not all data was written to file " + std::string(path));
        }

#ifdef ARDUINO
#ifdef BOARD_ESP32
        handle.close();
#elif defined(BOARD_NRF52)
        handle.close();
#endif
#else
        fclose(handle);
#endif
    } else {
        ERROR("write_file: failed to open output file " + std::string(path));
    }

    return bytes_written;
}

/*virtual*/ RNS::FileStream UniversalFileSystem::open_file(const char* path, RNS::FileStream::MODE mode) {
    TRACEF("open_file: opening file %s", path);

#ifdef ARDUINO
#ifdef BOARD_ESP32
    const char* access_mode;
    if (mode == RNS::FileStream::MODE_READ) {
        access_mode = FILE_READ;
    } else if (mode == RNS::FileStream::MODE_WRITE) {
        access_mode = FILE_WRITE;
    } else if (mode == RNS::FileStream::MODE_APPEND) {
        access_mode = FILE_APPEND;
    } else {
        ERRORF("open_file: unsupported mode %d", mode);
        return {RNS::Type::NONE};
    }
    TRACEF("open_file: opening file %s in mode %s", path, access_mode);
    File* handle = new File(SPIFFS.open(path, access_mode));
    if (handle == nullptr || !(*handle)) {
        ERRORF("open_file: failed to open output file %s", path);
        return {RNS::Type::NONE};
    }
    TRACEF("open_file: successfully opened file %s", path);
    return RNS::FileStream(new UniversalFileStream(handle));

#elif defined(BOARD_NRF52)
    File* handle = new File(InternalFS);
    int access_mode;
    if (mode == RNS::FileStream::MODE_READ) {
        access_mode = FILE_O_READ;
    } else if (mode == RNS::FileStream::MODE_WRITE) {
        access_mode = FILE_O_WRITE;
        if (InternalFS.exists(path)) {
            InternalFS.remove(path);
        }
    } else if (mode == RNS::FileStream::MODE_APPEND) {
        access_mode = FILE_O_WRITE;
    } else {
        ERRORF("open_file: unsupported mode %d", mode);
        return {RNS::Type::NONE};
    }
    if (!handle->open(path, access_mode)) {
        ERRORF("open_file: failed to open output file %s", path);
        return {RNS::Type::NONE};
    }
    TRACEF("open_file: successfully opened file %s", path);
    return RNS::FileStream(new UniversalFileStream(handle));

#else
    #warning("unsupported platform")
    return RNS::FileStream(RNS::Type::NONE);
#endif

#else
    const char* access_mode;
    if (mode == RNS::FileStream::MODE_READ) {
        access_mode = "r";
    } else if (mode == RNS::FileStream::MODE_WRITE) {
        access_mode = "w";
    } else if (mode == RNS::FileStream::MODE_APPEND) {
        access_mode = "a";
    } else {
        ERRORF("open_file: unsupported mode %d", mode);
        return {RNS::Type::NONE};
    }
    TRACEF("open_file: opening file %s in mode %s", path, access_mode);
    FILE* handle = fopen(path, access_mode);
    if (handle == nullptr) {
        ERRORF("open_file: failed to open output file %s", path);
        return {RNS::Type::NONE};
    }
    TRACEF("open_file: successfully opened file %s", path);
    return RNS::FileStream(new UniversalFileStream(handle));
#endif
}

