#elif defined(BOARD_NRF52)
    File root = InternalFS.open(dir_path);
#endif
    if (!root) {
        ERROR("list_directory: failed to open directory " + std::string(dir_path));
        return entries;
    }
    File entry = root.openNextFile();
    while (entry) {
        if (!entry.isDirectory()) {
            const char* name = entry.name();
            entries.push_back(name);
        }
        entry.close();
        entry = root.openNextFile();
    }
    TRACE("list_directory: returning directory listing");
    root.close();
    return entries;
#else
    return entries;
#endif
}

