void (Object_229::*method_table_a[5])() = {
    Object_229::handle_state_0,
    Object_229::handle_state_1,
    Object_229::handle_state_2,
    Object_229::handle_state_3,
    Object_229::handle_state_4,
};

void (Object_229::*method_table_b[5])() = {
    Object_229::transition_to_1,
    Object_229::transition_to_2,
    Object_229::transition_to_3,
    Object_229::transition_to_4,
    Object_229::transition_to_0,
};

struct TempData {
    u32 flagA;
    u32 flagB;
};

u32 global_flags[3];
u8 state_control_byte;

bool Object_229::initialize()
{
    this->orientation = (this->config >> 0x1d) & 1;
    this->size.x = 0x2000;
    this->size.y = 0x2000;
    this->size.z = 0x2000;

    i32 tempVal = ((this->config << 3) >> 0x1c);
    if (tempVal < 2) {
        tempVal = 2;
    }
    if (5 < tempVal) {
        tempVal = 5;
    }
    this->layer_mask = (char)(1 << (tempVal - 2));

    u32 maskA = (global_flags[0] & this->_340);
    u32 maskB = (global_flags[1] & this->_344);

    if (!(maskA && maskB)) {
        this->_410 = 4;
        this->setNextState(3);
        state_control_byte |= this->layer_mask;
    } else {
        this->_410 = 0;
        this->setNextState(0);
        state_control_byte &= ~this->layer_mask;
    }

    this->_3c0 = 2;
    return true;
}

