    this->someHelperFunction(1);
    return true;
}

void Object_229::handle_state_0()
{
}

void Object_229::transition_to_1()
{
    if ((global_flags[1] & this->_344) != 0 || (global_flags[0] & this->_340) != 0) {
        this->setNextState(1);
        return;
    }
}

void Object_229::handle_state_1()
{
    state_control_byte |= this->layer_mask;
    this->counter = 1;
}

void Object_229::transition_to_2()
{
    this->counter--;
    if (this->counter != 0) {
        return;
    }
    this->counter = 3;
    this->_410++;
    if (4 <= (i32)this->_410) {
        this->setNextState(3);
        return;
    }
}

void Object_229::handle_state_2()
{
}

void Object_229::transition_to_3()
{
    if (BOOL(((global_flags[0] & this->_340) == (global_flags[1] & this->_344)) == 0) == TRUE) {
        this->setNextState(4);
    }
}

void Object_229::handle_state_3()
{
    state_control_byte &= ~this->layer_mask;
    this->counter = 1;
}

void Object_229::transition_to_4()
{
    this->counter--;
    if (this->counter != 0) {
        return;
    }
    this->counter = 3;
    this->_410--;
    if (this->_410 == 0) {
        this->setNextState(0);
    }
}

void Object_229::setNextState(u32 newState)
{
    this->currentState = newState;
    this->nextAction = method_table_b[newState];
    this->stateCounter = 1;
}

void Object_229::dispatchMethod()
{
    if (this->stateCounter != 0) {
        (this->*(method_table_a[this->currentState]))();
        this->stateCounter = 0;
    }
    (this->*nextAction)();
}

