#define DEFAULT_STROKE_PARAMETERS ((plutovg_stroke_style_t){1.0f, PLUTOVG_LINE_CAP_BUTT, PLUTOVG_LINE_JOIN_MITER, 10.0f})

static plutovg_state_block_t* allocate_new_state(void)
{
    plutovg_state_block_t* block = (plutovg_state_block_t*)malloc(sizeof(plutovg_state_block_t));
    block->current_paint = NULL;
    block->current_font = NULL;
    block->current_color = PLUTOVG_BLACK_COLOR;
    block->current_matrix = PLUTOVG_IDENTITY_MATRIX;
    block->current_stroke.style = DEFAULT_STROKE_PARAMETERS;
    block->current_stroke.dash.offset = 0.0f;
    plutovg_array_init(block->current_stroke.dash.array);
    plutovg_span_buffer_init(&block->clip_spans);
    block->fill_mode = PLUTOVG_FILL_RULE_NON_ZERO;
    block->blend_mode = PLUTOVG_OPERATOR_SRC_OVER;
    block->text_size = 12.0f;
    block->transparency = 1.0f;
    block->mask_active = false;
    block->next = NULL;
    return block;
}

static void reset_current_state(plutovg_state_block_t* block)
{
    plutovg_paint_destroy(block->current_paint);
    plutovg_font_face_destroy(block->current_font);
    block->current_paint = NULL;
    block->current_font = NULL;
    block->current_color = PLUTOVG_BLACK_COLOR;
    block->current_matrix = PLUTOVG_IDENTITY_MATRIX;
    block->current_stroke.style = DEFAULT_STROKE_PARAMETERS;
    block->current_stroke.dash.offset = 0.0f;
    plutovg_array_clear(block->current_stroke.dash.array);
    plutovg_span_buffer_reset(&block->clip_spans);
    block->fill_mode = PLUTOVG_FILL_RULE_NON_ZERO;
    block->blend_mode = PLUTOVG_OPERATOR_SRC_OVER;
    block->text_size = 12.0f;
    block->transparency = 1.0f;
    block->mask_active = false;
}

static void duplicate_state_block(plutovg_state_block_t* target, const plutovg_state_block_t* source)
{
    target->current_paint = plutovg_paint_reference(source->current_paint);
    target->current_font = plutovg_font_face_reference(source->current_font);
    target->current_color = source->current_color;
    target->current_matrix = source->current_matrix;
    target->current_stroke.style = source->current_stroke.style;
    target->current_stroke.dash.offset = source->current_stroke.dash.offset;
    plutovg_array_clear(target->current_stroke.dash.array);
    plutovg_array_append(target->current_stroke.dash.array, source->current_stroke.dash.array);
    plutovg_span_buffer_copy(&target->clip_spans, &source->clip_spans);
    target->fill_mode = source->fill_mode;
    target->blend_mode = source->blend_mode;
    target->text_size = source->text_size;
    target->transparency = source->transparency;
    target->mask_active = source->mask_active;
}

static void release_state_block(plutovg_state_block_t* block)
{
    plutovg_paint_destroy(block->current_paint);
    plutovg_font_face_destroy(block->current_font);
    plutovg_array_destroy(block->current_stroke.dash.array);
    plutovg_span_buffer_destroy(&block->clip_spans);
    free(block);
}

plutovg_surface_t* plutovg_create_surface(int width, int height);

plutovg_canvas_t* plutovg_create_canvas_for_surface(plutovg_surface_t* surface)
{
    plutovg_canvas_t* canvas = (plutovg_canvas_t*)malloc(sizeof(plutovg_canvas_t));
    plutovg_init_reference(canvas);
    canvas->render_target = plutovg_surface_reference(surface);
    canvas->drawing_path = plutovg_path_create();
    canvas->active_state = allocate_new_state();
    canvas->released_states = NULL;
    canvas->font_cache = NULL;
    canvas->clipping_bounds = PLUTOVG_MAKE_RECT(0, 0, surface->width, surface->height);
    plutovg_span_buffer_init(&canvas->clip_spans);
    plutovg_span_buffer_init(&canvas->working_spans);
    return canvas;
}

plutovg_canvas_t* plutovg_canvas_add_ref(plutovg_canvas_t* canvas)
{
    plutovg_increment_reference(canvas);
    return canvas;
}

void plutovg_delete_canvas(plutovg_canvas_t* canvas)
{
    if(plutovg_destroy_reference(canvas)) {
        while(canvas->active_state) {
            plutovg_state_block_t* block = canvas->active_state;
            canvas->active_state = block->next;
            release_state_block(block);
        }
        while(canvas->released_states) {
            plutovg_state_block_t* block = canvas->released_states;
            canvas->released_states = block->next;
            release_state_block(block);
        }
        plutovg_font_face_cache_destroy(canvas->font_cache);
        plutovg_span_buffer_destroy(&canvas->working_spans);
        plutovg_span_buffer_destroy(&canvas->clip_spans);
        plutovg_surface_destroy(canvas->render_target);
        plutovg_path_destroy(canvas->drawing_path);
        free(canvas);
    }
}

