void plutovg_save_state(plutovg_canvas_t* canvas)
{
    plutovg_state_block_t* new_block = canvas->released_states;
    if(new_block == NULL)
        new_block = allocate_new_state();
    else
        canvas->released_states = new_block->next;
    duplicate_state_block(new_block, canvas->active_state);
    new_block->next = canvas->active_state;
    canvas->active_state = new_block;
}

void plutovg_restore_state(plutovg_canvas_t* canvas)
{
    if(canvas->active_state->next == NULL)
        return;
    plutovg_state_block_t* previous_block = canvas->active_state;
    canvas->active_state = previous_block->next;
    reset_current_state(previous_block);
    previous_block->next = canvas->released_states;
    canvas->released_states = previous_block;
}

