bool plutovg_is_point_in_clip_region(plutovg_canvas_t* canvas, float x, float y)
{
    if(canvas->active_state->mask_active) {
        return plutovg_span_buffer_contains(&canvas->active_state->clip_spans, x, y);
    }
    float left = canvas->clipping_bounds.x;
    float top = canvas->clipping_bounds.y;
    float right = canvas->clipping_bounds.x + canvas->clipping_bounds.w;
    float bottom = canvas->clipping_bounds.y + canvas->clipping_bounds.h;
    return x >= left && x <= right && y >= top && y <= bottom;
}

