void plutovg_get_clip_bounds(plutovg_canvas_t* canvas, plutovg_rect_t* bounds)
{
    if(canvas->active_state->mask_active) {
        plutovg_span_buffer_extents(&canvas->active_state->clip_spans, bounds);
    } else {
        bounds->x = canvas->clipping_bounds.x;
        bounds->y = canvas->clipping_bounds.y;
        bounds->w = canvas->clipping_bounds.w;
        bounds->h = canvas->clipping_bounds.h;
    }
}

