    if(canvas->active_state->mask_active) {
        plutovg_blend(canvas, &canvas->active_state->clip_spans);
    } else {
        plutovg_span_buffer_init_rect(&canvas->clip_spans, 0, 0, canvas->render_target->width, canvas->render_target->height);
        plutovg_blend(canvas, &canvas->clip_spans);
    }
}

void plutovg_fill_path_preserve(plutovg_canvas_t* canvas)
{
    plutovg_rasterize(&canvas->working_spans, canvas->drawing_path, &canvas->active_state->current_matrix, &canvas->clipping_bounds, NULL, canvas->active_state->fill_mode);
    if(canvas->active_state->mask_active) {
        plutovg_span_buffer_intersect(&canvas->clip_spans, &canvas->working_spans, &canvas->active_state->clip_spans);
        plutovg_blend(canvas, &canvas->clip_spans);
    } else {
        plutovg_blend(canvas, &canvas->working_spans);
    }
}

void plutovg_stroke_path_preserve(plutovg_canvas_t* canvas)
{
    plutovg_rasterize(&canvas->working_spans, canvas->drawing_path, &canvas->active_state->current_matrix, &canvas->clipping_bounds, &canvas->active_state->current_stroke, PLUTOVG_FILL_RULE_NON_ZERO);
    if(canvas->active_state->mask_active) {
        plutovg_span_buffer_intersect(&canvas->clip_spans, &canvas->working_spans, &canvas->active_state->clip_spans);
        plutovg_blend(canvas, &canvas->clip_spans);
    } else {
        plutovg_blend(canvas, &canvas->working_spans);
    }
}

void plutovg_clip_to_path_preserve(plutovg_canvas_t* canvas)
{
    if(canvas->active_state->mask_active) {
        plutovg_rasterize(&canvas->working_spans, canvas->drawing_path, &canvas->active_state->current_matrix, &canvas->clipping_bounds, NULL, canvas->active_state->fill_mode);
        plutovg_span_buffer_intersect(&canvas->clip_spans, &canvas->working_spans, &canvas->active_state->clip_spans);
        plutovg_span_buffer_copy(&canvas->active_state->clip_spans, &canvas->clip_spans);
    } else {
        plutovg_rasterize(&canvas->active_state->clip_spans, canvas->drawing_path, &canvas->active_state->current_matrix, &canvas->clipping_bounds, NULL, canvas->active_state->fill_mode);
        canvas->active_state->mask_active = true;
    }
}

