void plutovg_clip_to_given_path(plutovg_canvas_t* canvas, const plutovg_path_t* path)
{
    plutovg_clear_path(canvas);
    plutovg_append_path(canvas, path);
    plutovg_clip_to_path(canvas);
}

float plutovg_draw_glyph_at(plutovg_canvas_t* canvas, plutovg_codepoint_t codepoint, float x, float y)
{
    plutovg_state_block_t* state = canvas->active_state;
    if(state->current_font && state->text_size > 0.0f)
        return plutovg_font_face_get_glyph_path(state->current_font, state->text_size, x, y, codepoint, canvas->drawing_path);
    return 0.0f;
}

float plutovg_draw_text_string(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    plutovg_state_block_t* state = canvas->active_state;
    if(state->current_font == NULL || state->text_size <= 0.0f)
        return 0.0f;
    plutovg_text_iterator_t iterator;
    plutovg_text_iterator_init(&iterator, text, length, encoding);
    float total_advance = 0.0f;
    while(plutovg_text_iterator_has_next(&iterator)) {
        plutovg_codepoint_t codepoint = plutovg_text_iterator_next(&iterator);
        total_advance += plutovg_font_face_get_glyph_path(state->current_font, state->text_size, x + total_advance, y, codepoint, canvas->drawing_path);
    }
    return total_advance;
}

float plutovg_fill_text_string(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    plutovg_clear_path(canvas);
    float advance = plutovg_draw_text_string(canvas, text, length, encoding, x, y);
    plutovg_fill_path(canvas);
    return advance;
}

float plutovg_stroke_text_string(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    plutovg_clear_path(canvas);
    float advance = plutovg_draw_text_string(canvas, text, length, encoding, x, y);
    plutovg_stroke_path(canvas);
    return advance;
}

float plutovg_clip_text_string(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    plutovg_clear_path(canvas);
    float advance = plutovg_draw_text_string(canvas, text, length, encoding, x, y);
    plutovg_clip_to_path(canvas);
    return advance;
}

void plutovg_query_font_metrics(const plutovg_canvas_t* canvas, float* ascent, float* descent, float* spacing, plutovg_rect_t* bounds)
{
    plutovg_state_block_t* state = canvas->active_state;
    if(state->current_font && state->text_size > 0.0f) {
        plutovg_font_face_get_metrics(state->current_font, state->text_size, ascent, descent, spacing, bounds);
        return;
    }
    if(ascent) *ascent = 0.0f;
    if(descent) *descent = 0.0f;
    if(spacing) *spacing = 0.0f;
    if(bounds) {
        bounds->x = 0.0f;
        bounds->y = 0.0f;
        bounds->w = 0.0f;
        bounds->h = 0.0f;
    }
}

void plutovg_query_glyph_metrics(plutovg_canvas_t* canvas, plutovg_codepoint_t codepoint, float* advance, float* bearing, plutovg_rect_t* bounds)
{
    plutovg_state_block_t* state = canvas->active_state;
    if(state->current_font && state->text_size > 0.0f) {
        plutovg_font_face_get_glyph_metrics(state->current_font, state->text_size, codepoint, advance, bearing, bounds);
        return;
    }
    if(advance) *advance = 0.0f;
    if(bearing) *bearing = 0.0f;
    if(bounds) {
        bounds->x = 0.0f;
        bounds->y = 0.0f;
        bounds->w = 0.0f;
        bounds->h = 0.0f;
    }
}

float plutovg_measure_text_string(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, plutovg_rect_t* bounds)
{
    plutovg_state_block_t* state = canvas->active_state;
    if(state->current_font && state->text_size > 0.0f) {
        return plutovg_font_face_text_extents(state->current_font, state->text_size, text, length, encoding, bounds);
    }
    if(bounds) {
        bounds->x = 0.0f;
        bounds->y = 0.0f;
        bounds->w = 0.0f;
        bounds->h = 0.0f;
    }
    return 0.0f;
}

#include <stdio.h>
// Test suite for subscriber creation with various invalid configurations

void test_subscriber_invalid_configs() {
    dds_entity_t sub = 0, part = 0;
    dds_qos_t *q = NULL;
    dds_listener_t *lstnr = NULL;

    // Create participant for testing
    part = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    if (part <= 0) return; // Skip further tests if participant creation fails

    // Test 1: NULL participant should fail
    sub = dds_create_subscriber(0, NULL, NULL);
    if (sub != DDS_RETCODE_BAD_PARAMETER) return;

    // Test 2: Valid participant with NULL qos and listener should succeed
    sub = dds_create_subscriber(part, NULL, NULL);
    if (sub <= 0) return;
    dds_delete(sub);

    // Test 3: Valid participant with default qos and NULL listener should succeed
    q = dds_create_qos();
    sub = dds_create_subscriber(part, q, NULL);
    if (sub <= 0) {
        dds_delete_qos(q);
        return;
    }
    dds_delete(sub);
    dds_delete_qos(q);

    // Test 4: Invalid destination order setting (should be ignored but not cause failure)
    q = dds_create_qos();
    DDSRT_WARNING_CLANG_OFF(assign-enum);
    dds_qset_destination_order(q, 3); 
    DDSRT_WARNING_CLANG_ON(assign-enum);
    sub = dds_create_subscriber(part, q, NULL);
    if (sub > 0) {
        dds_delete(sub);
    }
    dds_delete_qos(q);

    // Test 5: Invalid presentation policy should cause failure
    q = dds_create_qos();
    DDSRT_WARNING_CLANG_OFF(assign-enum);
    dds_qset_presentation(q, 123, 1, 1);
    DDSRT_WARNING_CLANG_ON(assign-enum);
    sub = dds_create_subscriber(part, q, NULL);
    if (sub != DDS_RETCODE_BAD_PARAMETER) {
        dds_delete_qos(q);
        return;
    }
    dds_delete_qos(q);

    // Test 6: Valid participant with default listener should succeed
    lstnr = dds_create_listener(NULL);
    sub = dds_create_subscriber(part, NULL, lstnr);
    if (sub > 0) {
        dds_delete(sub);
    }
    dds_delete_listener(lstnr);

    // Test 7: Listener with data available callback set
    lstnr = dds_create_listener(NULL);
    dds_lset_data_available(lstnr, &on_data_available);
    sub = dds_create_subscriber(part, NULL, lstnr);
    if (sub > 0) {
        dds_delete(sub);
    }
    dds_delete_listener(lstnr);

    // Test 8: Listener with publication matched callback (ignored for subscriber)
    lstnr = dds_create_listener(NULL);
    dds_lset_publication_matched(lstnr, &on_publication_matched);
    sub = dds_create_subscriber(part, NULL, lstnr);
    if (sub > 0) {
        dds_delete(sub);
    }
    dds_delete_listener(lstnr);

    // Cleanup
    dds_delete(part);
}

void test_invalid_qos_policy() {
    dds_entity_t part = 0, sub = 0;
