using namespace ChromaPrint3D;

struct LabProjection {
    const Lab& operator()(const Lab& lab) const { return lab; }
};

using TestTree = kdt::KDTree<Lab, 3, LabProjection, std::size_t, float>;

// Test nearest neighbor search with a single point in the tree
TEST(KDTree, NearestSinglePoint) {
    std::vector<Lab> data_points       = {Lab(50.0f, 0.0f, 0.0f)};
    std::vector<std::size_t> data_ids  = {0};
    TestTree tree;
    tree.Reset(data_points, data_ids, LabProjection{});
    auto query_result = tree.Nearest(Lab(51.0f, 0.0f, 0.0f));
    EXPECT_EQ(query_result.index, 0u);
    EXPECT_NEAR(query_result.dist2, 1.0f, 1e-5f);
}

// Test correctness of nearest neighbor search across multiple points
TEST(KDTree, NearestCorrectness) {
    std::vector<Lab> data_points = {
        Lab(0.0f, 0.0f, 0.0f),
        Lab(50.0f, 0.0f, 0.0f),
        Lab(100.0f, 0.0f, 0.0f),
    };
    std::vector<std::size_t> data_ids = {0, 1, 2};
    TestTree tree;
    tree.Reset(data_points, data_ids, LabProjection{});

    auto res0 = tree.Nearest(Lab(10.0f, 0.0f, 0.0f));
    EXPECT_EQ(res0.index, 0u);

    auto res1 = tree.Nearest(Lab(48.0f, 0.0f, 0.0f));
    EXPECT_EQ(res1.index, 1u);

    auto res2 = tree.Nearest(Lab(90.0f, 0.0f, 0.0f));
    EXPECT_EQ(res2.index, 2u);
}

// Test k-nearest neighbors functionality
TEST(KDTree, KNearestNeighbors) {
    std::vector<Lab> data_points;
    std::vector<std::size_t> data_ids;
    for (int idx = 0; idx < 20; ++idx) {
        data_points.emplace_back(static_cast<float>(idx * 5), 0.0f, 0.0f);
        data_ids.push_back(static_cast<std::size_t>(idx));
    }
    TestTree tree;
    tree.Reset(data_points, data_ids, LabProjection{});

    std::vector<kdt::Neighbor<std::size_t, float>> found_neighbors;
    tree.KNearest(Lab(52.0f, 0.0f, 0.0f), 3, found_neighbors);

    EXPECT_EQ(found_neighbors.size(), 3u);

    bool closest_found = false;
    for (const auto& neighbor : found_neighbors) {
        if (neighbor.index == 10) { closest_found = true; }
    }
    EXPECT_TRUE(closest_found);
}

// Test exact match scenario
TEST(KDTree, ExactMatch) {
    std::vector<Lab> data_points       = {Lab(42.0f, 10.0f, -5.0f)};
    std::vector<std::size_t> data_ids  = {0};
    TestTree tree;
    tree.Reset(data_points, data_ids, LabProjection{});

    auto result = tree.Nearest(Lab(42.0f, 10.0f, -5.0f));
    EXPECT_EQ(result.index, 0u);
    EXPECT_NEAR(result.dist2, 0.0f, 1e-10f);
}

