    double const d13 = d10 * omega[0];
    double const d14 = omega[0] * omega[1];
    double const d15 = d12 * d14 - d13 * omega[1];
    double const d16 = omega[0] * omega[2];
    double const d17 = d12 * d16 - d13 * omega[2];
    double const d18 = omega[1] * omega[2];
    double const d19 = -d10 * d18 + d12 * d18;
    double const d20 = 0.5 * d8;
    double const d21 = sin(d4);
    double const d22 = -d21 + d4;
    double const d23 = -d1;
    double const d24 = -d2;
    double const d25 = d23 + d24;
    double const d26 = d25 * d9;
    double const d27 = cos(d4);
    double const d28 = 1 - d27;
    double const d29 = d11 * d28;
    double const d30 = d29 * omega[2];
    double const d31 = d22 * d9;
    double const d32 = d31 * omega[1];
    double const d33 = d32 * omega[0];
    double const d34 = d29 * omega[1];
    double const d35 = d31 * omega[2];
    double const d36 = d35 * omega[0];
    double const d37 = 3 * d22 / pow(d3, 5.0/2.0);
    double const d38 = d25 * d37;
    double const d39 = d5 * omega[0];
