    result[29] = upsilon[0] * (d26 * d70 - d38 * omega[2] + d68) + upsilon[1] * (-d71 + d72 + d74 + d75) + upsilon[2] * (d76 + d77);
    result[30] = d30 + d33;
    result[31] = d31 * d79 + 1;
    result[32] = -d80 + d81;
    result[33] = upsilon[0] * (d49 + d87) + upsilon[1] * (d40 * d83 - d60 * d79 + d82) + upsilon[2] * (d75 - d84 + d85 + d86);
    result[34] = upsilon[0] * (d64 + d76) + upsilon[1] * (d55 * d83 - d88 * omega[1]) + upsilon[2] * (d89 + d91);
    result[35] = upsilon[0] * (d62 + d71 - d72 + d74) + upsilon[1] * (d68 + d70 * d83 - d88 * omega[2]) + upsilon[2] * (d52 + d93);
    result[36] = -d34 + d36;
    result[37] = d80 + d81;
    result[38] = d31 * d94 + 1;
    result[39] = upsilon[0] * (d43 + d89) + upsilon[1] * (d62 + d84 - d85 + d86) + upsilon[2] * (d40 * d95 - d60 * d94 + d82);
    result[40] = upsilon[0] * (-d56 + d57 + d59 + d75) + upsilon[1] * (d48 + d91) + upsilon[2] * (d53 + d55 * d95 - d92 * d94);
    result[41] = upsilon[0] * (d67 + d77) + upsilon[1] * (d87 + d93) + upsilon[2] * (d70 * d95 - d90 * d94);

    std::cout << "Computation completed." << std::endl;
