extern int gCacheConfig;
extern std::string gProxyConfig;

std::string parseProxy(const std::string &source);

// Normalize a file path by resolving ".." components
std::string normalizePath(const std::string &path)
{
    std::string result = path;
    size_t idx_up, idx_slash, idx_unresolved = 0;
    do
    {
        idx_up = result.find("../", idx_unresolved);
        if(idx_up == result.npos)
            break;
        if(idx_up == 0)
        {
            idx_unresolved = idx_up + 3;
            continue;
        }
        idx_slash = result.rfind("/", idx_up - 1);
        if(idx_slash != result.npos)
        {
            idx_slash = result.rfind("/", idx_slash - 1);
            if(idx_slash != result.npos)
                result.erase(idx_slash + 1, idx_up - idx_slash + 2);
            else
                result.erase(0, idx_up + 3);
        }
        else
            idx_unresolved = idx_up + 3;
    } while(idx_up != result.npos);
    return result;
}

static int duktape_fetch_arguments_str(duk_context *ctx, duk_idx_t min_required, duk_idx_t max_allowed, ...)
{
    duk_idx_t arg_count = duk_get_top(ctx);
    if((min_required >= 0 && arg_count < min_required) || (max_allowed >= 0 && arg_count > max_allowed))
        return 0;

    va_list args;
    va_start(args, max_allowed);
    for(duk_idx_t i = 0; i < arg_count; i++)
    {
        std::string *target = va_arg(args, std::string*);
        if(target)
            *target = duk_safe_to_string(ctx, i);
    }
    va_end(args);
    return 1;
}

duk_ret_t module_resolver(duk_context *ctx)
{
    const char *module_requested = duk_get_string(ctx, 0);
    const char *current_module = duk_get_string(ctx, 1);  /* calling module */
    std::string resolved_path, base_dir = current_module;

    if(!base_dir.empty())
    {
        size_t last_slash = base_dir.rfind("/");
        if(last_slash != base_dir.npos)
            resolved_path += base_dir.substr(0, last_slash + 1);
    }

    resolved_path += module_requested;
    if(!endsWith(resolved_path, ".js"))
        resolved_path += ".js";

    resolved_path = normalizePath(resolved_path);

    if(!fileExist(resolved_path))
        duk_push_undefined(ctx);
    else
        duk_push_string(ctx, resolved_path.c_str());

    return 1;
}

duk_ret_t module_loader(duk_context *ctx)
{
    const char *full_path = duk_get_string(ctx, 0);
    std::string source_code = fileGet(full_path, true);
    duk_push_string(ctx, source_code.c_str());
    return 1;
}

static duk_ret_t console_log(duk_context *ctx)
{
	duk_push_string(ctx, " ");
	duk_insert(ctx, 0);
	duk_join(ctx, duk_get_top(ctx) - 1);
	printf("%s\n", duk_safe_to_string(ctx, -1));
	return 0;
}

static duk_ret_t async_fetch(duk_context *ctx)
{
    std::string url, proxy_server, http_method, body_data, response_body;
    if(duktape_fetch_arguments_str(ctx, 1, 4, &url, &proxy_server, &http_method, &body_data) == 0)
        return 0;

    switch(hash_(http_method))
    {
    case "POST"_hash:
        webPost(url, body_data, proxy_server, string_array{}, &response_body);
        break;
    default:
        response_body = fetchFile(url, proxy_server, gCacheConfig);
        break;
    }

    duk_push_lstring(ctx, response_body.c_str(), response_body.size());
    return 1;
}

static duk_ret_t encode_base64(duk_context *ctx)
{
    std::string input = duk_safe_to_string(ctx, -1);
    duk_push_string(ctx, base64Encode(input).c_str());
    return 1;
}

static duk_ret_t decode_base64(duk_context *ctx)
{
    std::string encoded = duk_safe_to_string(ctx, -1);
    encoded = base64Decode(encoded, true);
    duk_push_lstring(ctx, encoded.c_str(), encoded.size());
    return 1;
}

static duk_ret_t geo_lookup(duk_context *ctx)
{
    std::string ip_address, proxy_server;
    duktape_fetch_arguments_str(ctx, 1, 2, &ip_address, &proxy_server);

    if(!isIPv4(ip_address) && !isIPv6(ip_address))
        ip_address = hostnameToIPAddr(ip_address);

    if(ip_address.empty())
        duk_push_undefined(ctx);
    else
        duk_push_string(ctx, fetchFile("https://api.ip.sb/geoip/" + ip_address, parseProxy(proxy_server), gCacheConfig).c_str());

    return 1;
}

duk_context *create_duktape_context()
{
    duk_context *context = duk_create_heap_default();
    if(!context)
        return NULL;

    // Setup module system
    duk_push_object(context);
    duk_push_c_function(context, module_resolver, DUK_VARARGS);
    duk_put_prop_string(context, -2, "resolve");
    duk_push_c_function(context, module_loader, DUK_VARARGS);
    duk_put_prop_string(context, -2, "load");
    duk_module_node_init(context);

    // Register global functions
    duk_push_c_function(context, console_log, DUK_VARARGS);
    duk_put_global_string(context, "print");

    duk_push_c_function(context, async_fetch, DUK_VARARGS);
    duk_put_global_string(context, "fetch");

    duk_push_c_function(context, encode_base64, 1);
    duk_put_global_string(context, "atob");

    duk_push_c_function(context, decode_base64, 1);
    duk_put_global_string(context, "btoa");

    duk_push_c_function(context, geo_lookup, DUK_VARARGS);
    duk_put_global_string(context, "geoip");

    return context;
}

int execute_script(duk_context *ctx, const std::string &code)
{
    return duk_peval_string(ctx, code.c_str());
}

int invoke_function(duk_context *ctx, const std::string &func_name, size_t arg_count, ...)
{
    duk_get_global_string(ctx, func_name.c_str());

    va_list arguments;
    va_start(arguments, arg_count);
    size_t position = 0;
    while(position < arg_count)
    {
        std::string *value = va_arg(arguments, std::string*);
        if(value != NULL)
            duk_push_string(ctx, value->c_str());
        else
            duk_push_undefined(ctx);
        position++;
    }
    va_end(arguments);

    return duk_pcall(ctx, arg_count);
}

int push_node_info(duk_context *ctx, const nodeInfo &info)
{
    duk_push_object(ctx);
    duk_push_string(ctx, info.group.c_str());
    duk_put_prop_string(ctx, -2, "Group");
    duk_push_int(ctx, info.groupID);
    duk_put_prop_string(ctx, -2, "GroupID");
    duk_push_int(ctx, info.id);
    duk_put_prop_string(ctx, -2, "Index");
    duk_push_string(ctx, info.remarks.c_str());
    duk_put_prop_string(ctx, -2, "Remark");
    duk_push_string(ctx, info.proxyStr.c_str());
    duk_put_prop_string(ctx, -2, "ProxyInfo");
    return 0;
}

int push_node_array_entry(duk_context *ctx, const nodeInfo &info, duk_idx_t array_index)
{
    duk_push_object(ctx);
    duk_push_string(ctx, "Group");
    duk_push_string(ctx, info.group.c_str());
    duk_def_prop(ctx, array_index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "GroupID");
    duk_push_int(ctx, info.groupID);
    duk_def_prop(ctx, array_index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "Index");
    duk_push_int(ctx, info.id);
    duk_def_prop(ctx, array_index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "Remark");
    duk_push_string(ctx, info.remarks.c_str());
    duk_def_prop(ctx, array_index - 2, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "ProxyInfo");
    duk_push_string(ctx, info.proxyStr.c_str());
    duk_def_prop(ctx, array_index - 2, DUK_DEFPROP_HAVE_VALUE);

    return 0;
}

int get_integer_result(duk_context *ctx)
{
    int value = duk_to_int(ctx, -1);
    duk_pop(ctx);
    return value;
}

std::string get_string_result(duk_context *ctx)
{
    if(duk_is_null_or_undefined(ctx, -1))
        return "";
    std::string result = duk_safe_to_string(ctx, -1);
    duk_pop(ctx);
    return result;
}

bool get_boolean_result(duk_context *ctx)
{
    bool result = duk_to_boolean(ctx, -1);
    duk_pop(ctx);
    return result;
}

std::string get_error_stack(duk_context *ctx)
{
    duk_get_prop_string(ctx, -1, "stack");
    std::string stack_trace = duk_get_string(ctx, -1);
    duk_pop(ctx);
    return stack_trace;
}

#include "TypeCheckerImpl.h"
using namespace Cangjie;
using namespace AST;

Ptr<Ty> TypeChecker::TypeCheckerImpl::SynthesizeParenthesizedExpression(ASTContext& context, ParenExpr& parenExpr)
{
    (void)Synthesize(context, parenExpr.expr.get());

    if (!parenExpr.expr || !Ty::IsWellFormed(parenExpr.expr->ty)) {
        parenExpr.ty = TypeManager::GetErrorTy();
        return TypeManager::GetErrorTy();
    }

    if (parenExpr.expr->ty->IsAbstract()) {
        SubstituteAbstractTy(*parenExpr.expr);
    }

    parenExpr.ty = parenExpr.expr->ty;

    if (parenExpr.expr->isCompileTimeConst) {
        parenExpr.isCompileTimeConst = true;
        parenExpr.compileTimeValue = parenExpr.expr->compileTimeValue;
    }

    return parenExpr.ty;
}

bool TypeChecker::TypeCheckerImpl::CheckParenthesizedExpression(ASTContext& context, Ty& expectedType, ParenExpr& parenExpr)
{
    if (Check(context, &expectedType, parenExpr.expr.get())) {
        CJC_NULLPTR_CHECK(parenExpr.expr); // When Check returns true, parenExpr.expr must be non-null.

        parenExpr.ty = parenExpr.expr->ty;

        if (parenExpr.expr->isCompileTimeConst) {
            parenExpr.isCompileTimeConst = true;
            parenExpr.compileTimeValue = parenExpr.expr->compileTimeValue;
        }

        return true;
    } else {
        parenExpr.ty = TypeManager::GetErrorTy();
        return false;
    }
}

