static bool extractStringValue(const std::map<std::string,std::string>& pairs,
                               const char* keyName,
                               std::string& result) {
    auto iter = pairs.find(keyName);
    if (iter == pairs.end()) return false;
    result = iter->second;
    return true;
}

static bool convertToUInt32(const std::string& input, uint32_t& output) {
    if (input.empty()) return false;
    char* endPtr = nullptr;
    unsigned long value = std::strtoul(input.c_str(), &endPtr, 10);
    if (!endPtr || *endPtr != '\0') return false;
    output = static_cast<uint32_t>(value);
    return true;
}

static bool convertToUInt16(const std::string& input, uint16_t& output) {
    uint32_t temp = 0;
    if (!convertToUInt32(input, temp) || temp > 0xFFFF) return false;
    output = static_cast<uint16_t>(temp);
    return true;
}

static bool convertToUInt8(const std::string& input, uint8_t& output) {
    uint32_t temp = 0;
    if (!convertToUInt32(input, temp) || temp > 0xFF) return false;
    output = static_cast<uint8_t>(temp);
    return true;
}

static bool convertBooleanFrom01(const std::string& input, bool& output) {
    if (input == "1") { output = true; return true; }
    if (input == "0") { output = false; return true; }
    return false;
}

static bool convertToFloat(const std::string& input, float& output) {
    if (input.empty()) return false;
    char* endPtr = nullptr;
    output = std::strtof(input.c_str(), &endPtr);
    if (!endPtr || *endPtr != '\0') return false;
    return true;
}

bool ProfileTransformer::fromProfileText(
    const std::string& content,
    std::string& errorMessage
) {
    errorMessage.clear();
    auto& state = GlobalState::getInstance();
    const auto mapping = parse(content);

    std::string tempValue;
    uint8_t  byteValue  = 0;
    uint16_t shortValue = 0;
    uint32_t intValue   = 0;
    bool     flagValue  = false;
    float    floatValue = 0.0f;

    // -----------------------------
    // SPI Configuration
    // -----------------------------
    if (extractStringValue(mapping, "spi.chip_select", tempValue) && !convertToUInt8(tempValue, byteValue))  { errorMessage = "Invalid spi.chip_select";}
    else if (!tempValue.empty()) state.setSpiCSPin(byteValue);

    if (extractStringValue(mapping, "spi.clock", tempValue) && !convertToUInt8(tempValue, byteValue))  { errorMessage = "Invalid spi.clock";}
    else if (!tempValue.empty()) state.setSpiCLKPin(byteValue);

    if (extractStringValue(mapping, "spi.miso", tempValue) && !convertToUInt8(tempValue, byteValue))  { errorMessage = "Invalid spi.miso";}
    else if (!tempValue.empty()) state.setSpiMISOPin(byteValue);

    if (extractStringValue(mapping, "spi.mosi", tempValue) && !convertToUInt8(tempValue, byteValue))  { errorMessage = "Invalid spi.mosi";}
    else if (!tempValue.empty()) state.setSpiMOSIPin(byteValue);

    if (extractStringValue(mapping, "spi.frequency", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid spi.frequency";}
    else if (!tempValue.empty()) state.setSpiFrequency(intValue);

    // -----------------------------
    // I2C Configuration
    // -----------------------------
    if (extractStringValue(mapping, "i2c.data", tempValue) && !convertToUInt8(tempValue, byteValue))   { errorMessage = "Invalid i2c.data";}
    else if (!tempValue.empty()) state.setI2cSdaPin(byteValue);

    if (extractStringValue(mapping, "i2c.clk", tempValue) && !convertToUInt8(tempValue, byteValue))   { errorMessage = "Invalid i2c.clk";}
    else if (!tempValue.empty()) state.setI2cSclPin(byteValue);

    if (extractStringValue(mapping, "i2c.speed", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid i2c.speed";}
    else if (!tempValue.empty()) state.setI2cFrequency(intValue);

    // -----------------------------
    // UART Configuration
    // -----------------------------
    if (extractStringValue(mapping, "uart.baudrate", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid uart.baudrate";}
    else if (!tempValue.empty()) state.setUartBaudRate(static_cast<unsigned long>(intValue));

    if (extractStringValue(mapping, "uart.rx_pin", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid uart.rx_pin";}
    else if (!tempValue.empty()) state.setUartRxPin(byteValue);

    if (extractStringValue(mapping, "uart.tx_pin", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid uart.tx_pin";}
    else if (!tempValue.empty()) state.setUartTxPin(byteValue);

    if (extractStringValue(mapping, "uart.data_bits", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid uart.data_bits";}
    else if (!tempValue.empty()) state.setUartDataBits(byteValue);

    if (extractStringValue(mapping, "uart.parity_mode", tempValue)) {
        state.setUartParity(tempValue);
    }

    if (extractStringValue(mapping, "uart.stop_bits", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid uart.stop_bits";}
    else if (!tempValue.empty()) state.setUartStopBits(byteValue);

    if (extractStringValue(mapping, "uart.invert_signal", tempValue) && !convertBooleanFrom01(tempValue, flagValue)) { errorMessage = "Invalid uart.invert_signal";}
    else if (!tempValue.empty()) state.setUartInverted(flagValue);

    // -----------------------------
    // Infrared Configuration
    // -----------------------------
    if (extractStringValue(mapping, "ir.transmit", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid ir.transmit";}
    else if (!tempValue.empty()) state.setInfraredTxPin(byteValue);

    if (extractStringValue(mapping, "ir.receive", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid ir.receive";}
    else if (!tempValue.empty()) state.setInfraredRxPin(byteValue);

    if (extractStringValue(mapping, "ir.protocol_name", tempValue)) {
        state.setInfraredProtocol(InfraredProtocolMapper::toEnum(tempValue));
    }

    // -----------------------------
    // LED Configuration
    // -----------------------------
    if (extractStringValue(mapping, "led.pin_data", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid led.pin_data";}
    else if (!tempValue.empty()) state.setLedDataPin(byteValue);

    if (extractStringValue(mapping, "led.pin_clock", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid led.pin_clock";}
    else if (!tempValue.empty()) state.setLedClockPin(byteValue);

    if (extractStringValue(mapping, "led.count", tempValue) && !convertToUInt16(tempValue, shortValue)) { errorMessage = "Invalid led.count";}
    else if (!tempValue.empty()) state.setLedLength(shortValue);

    if (extractStringValue(mapping, "led.type", tempValue)) {
        state.setLedProtocol(tempValue);
    }

    if (extractStringValue(mapping, "led.intensity", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid led.intensity";}
    else if (!tempValue.empty()) state.setLedBrightness(byteValue);

    // -----------------------------
    // HDUART Configuration
    // -----------------------------
    if (extractStringValue(mapping, "hduart.baudrate", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid hduart.baudrate";}
    else if (!tempValue.empty()) state.setHdUartBaudRate(static_cast<unsigned long>(intValue));

    if (extractStringValue(mapping, "hduart.pin", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid hduart.pin";}
    else if (!tempValue.empty()) state.setHdUartPin(byteValue);

    if (extractStringValue(mapping, "hduart.data_bits", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid hduart.data_bits";}
    else if (!tempValue.empty()) state.setHdUartDataBits(byteValue);

    if (extractStringValue(mapping, "hduart.parity_mode", tempValue)) {
        state.setHdUartParity(tempValue);
    }

    if (extractStringValue(mapping, "hduart.stop_bits", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid hduart.stop_bits";}
    else if (!tempValue.empty()) state.setHdUartStopBits(byteValue);

    if (extractStringValue(mapping, "hduart.invert_signal", tempValue) && !convertBooleanFrom01(tempValue, flagValue)) { errorMessage = "Invalid hduart.invert_signal";}
    else if (!tempValue.empty()) state.setHdUartInverted(flagValue);

    // -----------------------------
    // I2S Configuration
    // -----------------------------
    if (extractStringValue(mapping, "i2s.bit_clock", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid i2s.bit_clock";}
    else if (!tempValue.empty()) state.setI2sBclkPin(byteValue);

    if (extractStringValue(mapping, "i2s.left_right", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid i2s.left_right";}
    else if (!tempValue.empty()) state.setI2sLrckPin(byteValue);

    if (extractStringValue(mapping, "i2s.audio_data", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid i2s.audio_data";}
    else if (!tempValue.empty()) state.setI2sDataPin(byteValue);

    if (extractStringValue(mapping, "i2s.sample_rate", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid i2s.sample_rate";}
    else if (!tempValue.empty()) state.setI2sSampleRate(intValue);

    if (extractStringValue(mapping, "i2s.bit_depth", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid i2s.bit_depth";}
    else if (!tempValue.empty()) state.setI2sBitsPerSample(byteValue);

    if (extractStringValue(mapping, "i2s.volume_percent", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid i2s.volume_percent";}
        state.setI2sPercentLevel(byteValue);
    }

    // -----------------------------
    // CAN Configuration
    // -----------------------------
    if (extractStringValue(mapping, "can.cs", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid can.cs";}
    else if (!tempValue.empty()) state.setCanCspin(byteValue);

    if (extractStringValue(mapping, "can.sck", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid can.sck";}
    else if (!tempValue.empty()) state.setCanSckPin(byteValue);

    if (extractStringValue(mapping, "can.input", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid can.input";}
    else if (!tempValue.empty()) state.setCanSiPin(byteValue);

    if (extractStringValue(mapping, "can.output", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid can.output";}
    else if (!tempValue.empty()) state.setCanSoPin(byteValue);

    if (extractStringValue(mapping, "can.speed_kbps", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid can.speed_kbps";}
    else if (!tempValue.empty()) state.setCanKbps(intValue);

    // -----------------------------
    // SubGHz Configuration
    // -----------------------------
    if (extractStringValue(mapping, "subghz.sck", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid subghz.sck";}
    else if (!tempValue.empty()) state.setSubGhzSckPin(byteValue);

    if (extractStringValue(mapping, "subghz.miso", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid subghz.miso";}
    else if (!tempValue.empty()) state.setSubGhzMisoPin(byteValue);

    if (extractStringValue(mapping, "subghz.mosi", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid subghz.mosi";}
    else if (!tempValue.empty()) state.setSubGhzMosiPin(byteValue);

    if (extractStringValue(mapping, "subghz.cs", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid subghz.cs";}
    else if (!tempValue.empty()) state.setSubGhzCsPin(byteValue);

    if (extractStringValue(mapping, "subghz.gdo", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid subghz.gdo";}
    else if (!tempValue.empty()) state.setSubGhzGdoPin(byteValue);

    if (extractStringValue(mapping, "subghz.frequency", tempValue) && !convertToFloat(tempValue, floatValue)) { errorMessage = "Invalid subghz.frequency";}
    else if (!tempValue.empty()) state.setSubGhzFrequency(floatValue);

    // -----------------------------
    // NRF24 Configuration
    // -----------------------------
    if (extractStringValue(mapping, "rf24.chip_select", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rf24.chip_select";}
    else if (!tempValue.empty()) state.setRf24CsnPin(byteValue);

    if (extractStringValue(mapping, "rf24.enable", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rf24.enable";}
    else if (!tempValue.empty()) state.setRf24CePin(byteValue);

    if (extractStringValue(mapping, "rf24.sck", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rf24.sck";}
    else if (!tempValue.empty()) state.setRf24SckPin(byteValue);

    if (extractStringValue(mapping, "rf24.miso", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rf24.miso";}
    else if (!tempValue.empty()) state.setRf24MisoPin(byteValue);

    if (extractStringValue(mapping, "rf24.mosi", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rf24.mosi";}
    else if (!tempValue.empty()) state.setRf24MosiPin(byteValue);

    // -----------------------------
    // RFID Configuration
    // -----------------------------
    if (extractStringValue(mapping, "rfid.sda", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rfid.sda";}
    else if (!tempValue.empty()) state.setRfidSdaPin(byteValue);

    if (extractStringValue(mapping, "rfid.scl", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid rfid.scl";}
    else if (!tempValue.empty()) state.setRfidSclPin(byteValue);

    // -----------------------------
    // SD Card Configuration
    // -----------------------------
    if (extractStringValue(mapping, "sd.card_select", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid sd.card_select";}
    else if (!tempValue.empty()) state.setSdCardCsPin(byteValue);

    if (extractStringValue(mapping, "sd.clock", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid sd.clock";}
    else if (!tempValue.empty()) state.setSdCardClkPin(byteValue);

    if (extractStringValue(mapping, "sd.miso", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid sd.miso";}
    else if (!tempValue.empty()) state.setSdCardMisoPin(byteValue);

    if (extractStringValue(mapping, "sd.mosi", tempValue) && !convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid sd.mosi";}
    else if (!tempValue.empty()) state.setSdCardMosiPin(byteValue);

    if (extractStringValue(mapping, "sd.clock_speed", tempValue) && !convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid sd.clock_speed";}
    else if (!tempValue.empty()) state.setSdCardFrequency(intValue);

    // -----------------------------
    // USB Configuration
    // -----------------------------
    if (extractStringValue(mapping, "usb.product_name", tempValue)) {
        state.setUSBProductString(tempValue);
    }

    if (extractStringValue(mapping, "usb.manufacturer_name", tempValue)) {
        state.setUSBManufacturerString(tempValue);
    }

    if (extractStringValue(mapping, "usb.serial_number", tempValue)) {
        state.setUSBSerialString(tempValue);
    }

    if (extractStringValue(mapping, "usb.webusb_url", tempValue)) {
        state.setWebUSBString(tempValue);
    }

    if (extractStringValue(mapping, "usb.vendor_id", tempValue)) {
        if (!convertToUInt16(tempValue, shortValue)) { errorMessage = "Invalid usb.vendor_id";}
        state.setUSBVid(shortValue);
    }

    if (extractStringValue(mapping, "usb.product_id", tempValue)) {
        if (!convertToUInt16(tempValue, shortValue)) { errorMessage = "Invalid usb.product_id";}
        state.setUSBPid(shortValue);
    }

    // -----------------------------
    // ETHERNET Configuration
    // -----------------------------
    if (extractStringValue(mapping, "eth.chip_select", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid eth.chip_select";}
        state.setEthernetCsPin(byteValue);
    }

    if (extractStringValue(mapping, "eth.sck", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid eth.sck";}
        state.setEthernetSckPin(byteValue);
    }

    if (extractStringValue(mapping, "eth.miso", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid eth.miso";}
        state.setEthernetMisoPin(byteValue);
    }

    if (extractStringValue(mapping, "eth.mosi", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid eth.mosi";}
        state.setEthernetMosiPin(byteValue);
    }

    if (extractStringValue(mapping, "eth.irq_pin", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid eth.irq_pin";}
        state.setEthernetIrqPin(byteValue);
    }

    if (extractStringValue(mapping, "eth.clock_speed", tempValue)) {
        if (!convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid eth.clock_speed";}
        state.setEthernetFrequency(intValue);
    }

    // -----------------------------
    // FM Configuration
    // -----------------------------
    if (extractStringValue(mapping, "fm.sda", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid fm.sda";}
        state.setTwoWireIoPin(byteValue);
    }

    if (extractStringValue(mapping, "fm.scl", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid fm.scl";}
        state.setTwoWireClkPin(byteValue);
    }

    if (extractStringValue(mapping, "fm.reset", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid fm.reset";}
        state.setTwoWireRstPin(byteValue);
    }

    // -----------------------------
    // CELL Configuration
    // -----------------------------
    if (extractStringValue(mapping, "cell.tx", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid cell.tx";}
        state.setUartTxPin(byteValue);
    }

    if (extractStringValue(mapping, "cell.rx", tempValue)) {
        if (!convertToUInt8(tempValue, byteValue)) { errorMessage = "Invalid cell.rx";}
        state.setUartRxPin(byteValue);
    }

    if (extractStringValue(mapping, "cell.baudrate", tempValue)) {
        if (!convertToUInt32(tempValue, intValue)) { errorMessage = "Invalid cell.baudrate";}
        state.setUartBaudRate(static_cast<unsigned long>(intValue));
    }

    if (!errorMessage.empty()) {
        return false;
    }
    return true;
}

std::map<std::string, std::string>
ProfileTransformer::parse(const std::string& content) {
    std::map<std::string, std::string> result;
    std::stringstream stream(content);
    std::string line;
    while (std::getline(stream, line)) {
        // Trim leading whitespace
        size_t start = line.find_first_not_of(" \t\r\n");
        if (start != std::string::npos) {
            line.erase(0, start);
        } else {
            continue;
        }

        // Trim trailing whitespace
        size_t end = line.find_last_not_of(" \t\r\n");
        if (end != std::string::npos) {
            line.erase(end + 1);
        } else {
            continue;
        }

        if (line.empty() || line[0] == '#') continue;

        size_t equalsPos = line.find('=');
        if (equalsPos == std::string::npos) continue;

        result[line.substr(0, equalsPos)] = line.substr(equalsPos + 1);
    }
    return result;
}

