#define NCB_MODULE_NAME TJS_W("layerExImage.dll")
#ifndef _WIN32
typedef unsigned char BYTE;
typedef unsigned short WORD;
typedef struct tagRGBQUAD {
    BYTE rgbBlue;
    BYTE rgbGreen;
    BYTE rgbRed;
    BYTE rgbReserved;
} RGBQUAD;
