#include "layerExBase_wamsoft.hpp"

// ---------- layerExImage class ----------
class layerExImage : public layerExBase
{
public:
    layerExImage(DispatchT obj) : layerExBase(obj) {}
    virtual void reset() {
        layerExBase::reset();
        _buffer += _clipTop * _pitch + _clipLeft * 4;
        _width  = _clipWidth;
        _height = _clipHeight;
    }
    void applyLookup(BYTE* table);
    void adjustLight(int bright, int contr);
    void tint(int h, int s, double factor);
    void transform(int h, int s, int l);
    void addNoise(int amount);
    void fillWhiteNoise();
    void applyGaussianBlur(float blurRadius);
};

// ---------- Lookup Table (LUT) ----------
void layerExImage::applyLookup(BYTE* table) {
    BYTE *scanline = (BYTE*)_buffer;
    for (int row = 0; row < _height; ++row) {
        BYTE *pixel = scanline;
        for (int col = 0; col < _width; ++col) {
            *pixel = table[*pixel]; ++pixel;
            *pixel = table[*pixel]; ++pixel;
            *pixel = table[*pixel]; ++pixel;
            ++pixel;
        }
        scanline += _pitch;
    }
}

// ---------- Light (Brightness & Contrast) ----------
void layerExImage::adjustLight(int bright, int contr) {
    float contrastFactor = (100.0f + contr) / 100.0f;
    bright += 128;
    BYTE lookup[256];
    for (int i = 0; i < 256; ++i) {
        lookup[i] = (BYTE)std::max(0, std::min(255, (int)((i - 128) * contrastFactor + bright)));
    }
    applyLookup(lookup);
    redraw();
}

// ---------- HSL Utilities ----------
#define HSL_MAX   255
#define RGB_MAX   255
#define HSL_UNDEF (HSL_MAX * 2 / 3)

static RGBQUAD convertRGBtoHSL(RGBQUAD rgbColor) {
    BYTE R = rgbColor.rgbRed;
    BYTE G = rgbColor.rgbGreen;
    BYTE B = rgbColor.rgbBlue;
    BYTE maxVal = std::max(std::max(R, G), B);
    BYTE minVal = std::min(std::min(R, G), B);
    BYTE L = (BYTE)((((maxVal + minVal) * HSL_MAX) + RGB_MAX) / (2 * RGB_MAX));
    BYTE H, S;
    if (maxVal == minVal) {
        S = 0;
        H = HSL_UNDEF;
    } else {
        if (L <= (HSL_MAX / 2))
            S = (BYTE)((((maxVal - minVal) * HSL_MAX) + ((maxVal + minVal) / 2)) / (maxVal + minVal));
        else
            S = (BYTE)((((maxVal - minVal) * HSL_MAX) + ((2 * RGB_MAX - maxVal - minVal) / 2)) / (2 * RGB_MAX - maxVal - minVal));
        WORD Rd = (WORD)((((maxVal - R) * (HSL_MAX / 6)) + ((maxVal - minVal) / 2)) / (maxVal - minVal));
        WORD Gd = (WORD)((((maxVal - G) * (HSL_MAX / 6)) + ((maxVal - minVal) / 2)) / (maxVal - minVal));
        WORD Bd = (WORD)((((maxVal - B) * (HSL_MAX / 6)) + ((maxVal - minVal) / 2)) / (maxVal - minVal));
        if (R == maxVal)
            H = (BYTE)(Bd - Gd);
        else if (G == maxVal)
            H = (BYTE)((HSL_MAX / 3) + Rd - Bd);
        else
            H = (BYTE)(((2 * HSL_MAX) / 3) + Gd - Rd);
        if (H > HSL_MAX) H -= HSL_MAX;
    }
    RGBQUAD hsl = {L, S, H, 0};
    return hsl;
}

static float hueToRGB(float n1, float n2, float hue) {
    float value;
    if (hue > 360) hue -= 360;
    else if (hue < 0) hue += 360;
    if (hue < 60)        value = n1 + (n2 - n1) * hue / 60.0f;
    else if (hue < 180)  value = n2;
    else if (hue < 240)  value = n1 + (n2 - n1) * (240 - hue) / 60;
    else                 value = n1;
    return value;
}

static RGBQUAD convertHSLtoRGB(RGBQUAD hslColor) {
    float h = (float)hslColor.rgbRed * 360.0f / 255.0f;
    float s = (float)hslColor.rgbGreen / 255.0f;
    float l = (float)hslColor.rgbBlue / 255.0f;
    float m2;
    if (l <= 0.5) m2 = l * (1 + s);
    else          m2 = l + s - l * s;
    float m1 = 2 * l - m2;
    BYTE r, g, b;
    if (s == 0) {
        r = g = b = (BYTE)(l * 255.0f);
    } else {
        r = (BYTE)(hueToRGB(m1, m2, h + 120) * 255.0f);
        g = (BYTE)(hueToRGB(m1, m2, h) * 255.0f);
        b = (BYTE)(hueToRGB(m1, m2, h - 120) * 255.0f);
    }
    RGBQUAD rgb = {b, g, r, 0};
    return rgb;
}

// ---------- Tint (colorize) ----------
void layerExImage::tint(int h, int s, double factor) {
    if (factor < 0.0) factor = 0.0;
    if (factor > 1.0) factor = 1.0;
    int weightNew = (int)(256 * factor);
    int weightOld = 256 - weightNew;
    bool fullMix = (factor > 0.999);
    RGBQUAD color, hsl;
    BYTE *scanline = (BYTE*)_buffer;
    for (int y = 0; y < _height; ++y) {
        BYTE *pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            color.rgbBlue  = pixel[0];
            color.rgbGreen = pixel[1];
            color.rgbRed   = pixel[2];
            if (fullMix) {
                color = convertRGBtoHSL(color);
                color.rgbRed = h;
                color.rgbGreen = s;
                color = convertHSLtoRGB(color);
            } else {
                hsl = convertRGBtoHSL(color);
                hsl.rgbRed = h;
                hsl.rgbGreen = s;
                hsl = convertHSLtoRGB(hsl);
                color.rgbRed   = (BYTE)((hsl.rgbRed   * weightNew + color.rgbRed   * weightOld) >> 8);
                color.rgbBlue  = (BYTE)((hsl.rgbBlue  * weightNew + color.rgbBlue  * weightOld) >> 8);
                color.rgbGreen = (BYTE)((hsl.rgbGreen * weightNew + color.rgbGreen * weightOld) >> 8);
            }
            *pixel++ = color.rgbBlue;
            *pixel++ = color.rgbGreen;
            *pixel++ = color.rgbRed;
            ++pixel;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- Transform (modulate) helpers ----------
static int hue2rgb_mod(double n1, double n2, double hue) {
    double color;
    if (hue < 0) hue += 1.0;
    else if (hue > 1.0) hue -= 1.0;
    if (hue < 1.0 / 6.0)
        color = n1 + (n2 - n1) * hue * 6.0;
    else if (hue < 1.0 / 2.0)
        color = n2;
    else if (hue < 2.0 / 3.0)
        color = n1 + (n2 - n1) * (2.0 / 3.0 - hue) * 6.0;
    else
        color = n1;
    return (int)(color * 255.0);
}

static void transform_pixel(int &b, int &g, int &r, double h, double s, double l) {
    double red   = r / 255.0;
    double green = g / 255.0;
    double blue  = b / 255.0;
    double maxC = std::max(std::max(red, green), blue);
    double minC = std::min(std::min(red, green), blue);
    double delta = maxC - minC;
    double sum   = maxC + minC;
    double luminance = sum / 2.0;
    double hue, saturation;
    if (delta == 0) {
        saturation = 0;
        hue = 0;
    } else {
        if (luminance < 0.5)
            saturation = delta / sum;
        else
            saturation = delta / (2.0 - sum);
        if (red == maxC)
            hue = (green - blue) / delta;
        else if (green == maxC)
            hue = 2.0 + (blue - red) / delta;
        else
            hue = 4.0 + (red - green) / delta;
        hue /= 6.0;
    }
    hue += h;
    while (hue < 0) hue += 1.0;
    while (hue > 1.0) hue -= 1.0;
    if (s > 0) saturation += (1.0 - saturation) * s;
    else       saturation += saturation * s;
    if (l > 0) luminance += (1.0 - luminance) * l;
    else       luminance += luminance * l;
    if (saturation == 0.0) {
        r = g = b = (int)(luminance * 255.0);
    } else {
        double m2;
        if (luminance <= 0.5)
            m2 = luminance * (1 + saturation);
        else
            m2 = luminance + saturation - luminance * saturation;
        double m1 = 2.0 * luminance - m2;
        r = hue2rgb_mod(m1, m2, hue + 1.0 / 3.0);
        g = hue2rgb_mod(m1, m2, hue);
        b = hue2rgb_mod(m1, m2, hue - 1.0 / 3.0);
    }
}

// ---------- Transform (modulate) ----------
void layerExImage::transform(int h, int s, int l) {
    double hh = h / 360.0;
    double ss = s / 100.0;
    double ll = l / 100.0;
    BYTE *scanline = (BYTE*)_buffer;
    for (int y = 0; y < _height; ++y) {
        BYTE *pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            int b = pixel[0], g = pixel[1], r = pixel[2];
            transform_pixel(b, g, r, hh, ss, ll);
            *pixel++ = b; *pixel++ = g; *pixel++ = r; ++pixel;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- Noise ----------
void layerExImage::addNoise(int amount) {
    BYTE *scanline = (BYTE*)_buffer;
    for (int y = 0; y < _height; ++y) {
        BYTE *pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            int noise = (int)((rand() / (float)RAND_MAX - 0.5) * amount);
            *pixel = (BYTE)std::max(0, std::min(255, (int)(*pixel + noise))); ++pixel;
            noise = (int)((rand() / (float)RAND_MAX - 0.5) * amount);
            *pixel = (BYTE)std::max(0, std::min(255, (int)(*pixel + noise))); ++pixel;
            noise = (int)((rand() / (float)RAND_MAX - 0.5) * amount);
            *pixel = (BYTE)std::max(0, std::min(255, (int)(*pixel + noise))); ++pixel;
            ++pixel;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- White Noise ----------
void layerExImage::fillWhiteNoise() {
    BYTE *scanline = (BYTE*)_buffer;
    for (int y = 0; y < _height; ++y) {
        BYTE *pixel = scanline;
        for (int x = 0; x < _width; ++x, pixel += 4) {
            BYTE val = (BYTE)(rand() / (RAND_MAX / 255));
            pixel[2] = pixel[1] = pixel[0] = val;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- Gaussian Blur ----------
static int32_t create_convolution_matrix(float radius, float **matrix_ptr) {
    int32_t size;
    float *matrix;
    float stddev, total;
    radius = (float)fabs(0.5 * radius) + 0.25f;
    stddev = radius;
    radius = stddev * 2;
    size = (int32_t)(2 * ceil(radius - 0.5) + 1);
    if (size <= 0) size = 1;
    *matrix_ptr = new float[size];
    matrix = *matrix_ptr;
    for (int32_t i = size / 2 + 1; i < size; i++) {
        float pos = i - (float)floor((float)(size / 2)) - 0.5f;
        total = 0;
        for (int32_t j = 1; j <= 50; j++) {
            if (pos + 0.02f * j <= radius)
                total += (float)exp(-(pos + 0.02f * j) * (pos + 0.02f * j) / (2 * stddev * stddev));
        }
        matrix[i] = total / 50;
    }
    for (int32_t i = 0; i <= size / 2; i++)
        matrix[i] = matrix[size - 1 - i];
    total = 0;
    for (int32_t j = 0; j <= 50; j++)
        total += (float)exp(-(0.5f + 0.02f * j) * (0.5f + 0.02f * j) / (2 * stddev * stddev));
    matrix[size / 2] = total / 51;
    total = 0;
    for (int32_t i = 0; i < size; i++) total += matrix[i];
    for (int32_t i = 0; i < size; i++) matrix[i] = matrix[i] / total;
    return size;
}

static float *create_lookup_table(float *matrix, int32_t matrix_size) {
    float *table = new float[matrix_size * 256];
    float *table_p = table;
    float *matrix_p = matrix;
    for (int32_t i = 0; i < matrix_size; i++) {
        for (int32_t j = 0; j < 256; j++)
            *(table_p++) = *matrix_p * (float)j;
        matrix_p++;
    }
    return table;
}

static void convolve_row(float *ctable, float *cmatrix, int32_t cmatrix_length,
                         BYTE *input, BYTE *output, int32_t rows, int32_t channels) {
    float scale, sum;
    int32_t i, j, row;
    int32_t center = cmatrix_length / 2;
    if (cmatrix_length > rows) {
        for (row = 0; row < rows; row++) {
            scale = 0;
            for (j = 0; j < rows; j++) {
                if ((j + center - row >= 0) && (j + center - row < cmatrix_length))
                    scale += cmatrix[j + center - row];
            }
            for (i = 0; i < channels; i++) {
                sum = 0;
                for (j = 0; j < rows; j++) {
                    if ((j >= row - center) && (j <= row + center))
                        sum += input[j * channels + i] * cmatrix[j];
                }
                output[row * channels + i] = (BYTE)(0.5f + sum / scale);
            }
        }
    } else {
        BYTE *out_p, *in_p, *in_p1;
        float *cmatrix_p, *ctable_p;
        for (row = 0; row < center; row++) {
            scale = 0;
            for (j = center - row; j < cmatrix_length; j++)
                scale += cmatrix[j];
            for (i = 0; i < channels; i++) {
                sum = 0;
                for (j = center - row; j < cmatrix_length; j++)
                    sum += input[(row + j - center) * channels + i] * cmatrix[j];
                output[row * channels + i] = (BYTE)(0.5f + sum / scale);
            }
        }
        out_p = output + row * channels;
        for (; row < rows - center; row++) {
            in_p = (row - center) * channels + input;
            for (i = 0; i < channels; i++) {
                sum = 0;
                cmatrix_p = cmatrix;
                in_p1 = in_p;
                ctable_p = ctable;
                for (j = cmatrix_length; j > 0; j--) {
                    sum += *(ctable_p + *in_p1);
                    in_p1 += channels;
                    ctable_p += 256;
                }
                in_p++;
                *(out_p++) = (BYTE)(0.5f + sum);
            }
        }
        for (; row < rows; row++) {
            scale = 0;
            for (j = 0; j < rows - row + center; j++)
                scale += cmatrix[j];
            for (i = 0; i < channels; i++) {
                sum = 0;
                for (j = 0; j < rows - row + center; j++)
                    sum += input[(row + j - center) * channels + i] * cmatrix[j];
                output[row * channels + i] = (BYTE)(0.5f + sum / scale);
            }
        }
    }
}

static void extractColumn(BYTE *src, BYTE *dest, int height, int pitch) {
    pitch -= 4;
    for (int i = 0; i < height; i++) {
        *dest++ = *src++; *dest++ = *src++; *dest++ = *src++; *dest++ = *src++;
        src += pitch;
    }
}

static void restoreColumn(BYTE *src, BYTE *dest, int height, int pitch) {
    pitch -= 4;
    for (int i = 0; i < height; i++) {
        *src++ = *dest++; *src++ = *dest++; *src++ = *dest++; *src++ = *dest++;
        src += pitch;
    }
}

void layerExImage::applyGaussianBlur(float blurRadius) {
    int stride = _width * 4;
    BYTE *tempBuffer = new BYTE[stride * _height];
    float *convMatrix = NULL;
    int32_t matrixSize = create_convolution_matrix(blurRadius, &convMatrix);
    float *lookupTable = create_lookup_table(convMatrix, matrixSize);
    for (int y = 0; y < _height; y++)
        convolve_row(lookupTable, convMatrix, matrixSize, _buffer + _pitch * y, tempBuffer + stride * y, _width, 4);
    BYTE *colBuffer1 = new BYTE[_height * 4];
    BYTE *colBuffer2 = new BYTE[_height * 4];
    for (int x = 0; x < _width; x++) {
        extractColumn(tempBuffer + x * 4, colBuffer1, _height, stride);
        convolve_row(lookupTable, convMatrix, matrixSize, colBuffer1, colBuffer2, _height, 4);
        restoreColumn(_buffer + x * 4, colBuffer2, _height, _pitch);
    }
    delete[] colBuffer1;
    delete[] colBuffer2;
    delete[] convMatrix;
    delete[] lookupTable;
    delete[] tempBuffer;
    redraw();
}

