#include "memdebug.h"
#define HTTPPOST_PTRNAME CURL_HTTPPOST_PTRNAME
#define HTTPPOST_FILENAME CURL_HTTPPOST_FILENAME
#define HTTPPOST_PTRCONTENTS CURL_HTTPPOST_PTRCONTENTS
#define HTTPPOST_READFILE CURL_HTTPPOST_READFILE
#define HTTPPOST_PTRBUFFER CURL_HTTPPOST_PTRBUFFER
#define HTTPPOST_CALLBACK CURL_HTTPPOST_CALLBACK
#define HTTPPOST_BUFFER CURL_HTTPPOST_BUFFER

/***************************************************************************
 *
 * InsertHttpPost()
 *
 * Inserts an HttpPost structure into the list, if parent_post is provided
 * becomes a subpost of parent_post instead of a direct list element.
 *
 * Returns newly allocated HttpPost on success and NULL if allocation failed.
 *
 ***************************************************************************/
static struct curl_httppost *
InsertHttpPost(struct FormInfo *source,
               struct curl_httppost *parent_post,
               struct curl_httppost **httppost,
               struct curl_httppost **last_post)
{
  struct curl_httppost *new_post;
  size_t name_len = source->namelength;
  if(!name_len && source->name)
    name_len = strlen(source->name);
  if((source->bufferlength > LONG_MAX) || (name_len > LONG_MAX))
    /* prevent overflow during type conversions below */
    return NULL;
  new_post = calloc(1, sizeof(struct curl_httppost));
  if(new_post) {
    new_post->name = source->name;
    new_post->namelength = (long)name_len;
    new_post->contents = source->value;
    new_post->contentlen = source->contentslength;
    new_post->buffer = source->buffer;
    new_post->bufferlength = (long)source->bufferlength;
    new_post->contenttype = source->contenttype;
    new_post->flags = source->flags | CURL_HTTPPOST_LARGE;
    new_post->contentheader = source->contentheader;
    new_post->showfilename = source->showfilename;
    new_post->userp = source->userp;
  }
  else
    return NULL;
  if(parent_post) {
    /* link our 'next' to the original 'next' */
    new_post->more = parent_post->more;
    /* update the original 'next' to point here */
    parent_post->more = new_post;
  }
  else {
    /* connect the previous node to this one */
    if(*last_post)
      (*last_post)->next = new_post;
    else
      (*httppost) = new_post;
    (*last_post) = new_post;
  }
  return new_post;
}

/***************************************************************************
 *
 * InsertFormInfo()
 *
 * Inserts a FormInfo structure into the list represented by parent_form_info.
 *
 * Returns newly allocated FormInfo on success and NULL if allocation failed/
 * parent_form_info is NULL.
 *
 ***************************************************************************/
static struct FormInfo *InsertFormInfo(char *val,
                                       char *ctype,
                                       struct FormInfo *prev_form_info)
{
  struct FormInfo *new_info;
  new_info = calloc(1, sizeof(struct FormInfo));
  if(!new_info)
    return NULL;
  if(val)
    new_info->value = val;
  if(ctype)
    new_info->contenttype = ctype;
  new_info->flags = HTTPPOST_FILENAME;
  if(prev_form_info) {
    /* link our 'next' to the original 'next' */
    new_info->more = prev_form_info->more;
    /* update the original 'next' to point here */
    prev_form_info->more = new_info;
  }
  return new_info;
}

static void release_formlist(struct FormInfo *node)
{
  for(; node != NULL; node = node->more) {
    if(node->name_alloc) {
      Curl_safefree(node->name);
      node->name_alloc = FALSE;
    }
    if(node->value_alloc) {
      Curl_safefree(node->value);
      node->value_alloc = FALSE;
    }
    if(node->contenttype_alloc) {
      Curl_safefree(node->contenttype);
      node->contenttype_alloc = FALSE;
    }
    if(node->showfilename_alloc) {
      Curl_safefree(node->showfilename);
      node->showfilename_alloc = FALSE;
    }
  }
}

/***************************************************************************
 *
 * PrepareForm()
 *
 * Stores a form post parameter and builds the appropriate linked list.
 *
 * Supports two main functionalities: using files and byte arrays as
 * post parts. Byte arrays are either copied or only the pointer is stored
 * (as requested by the user), while for files only the filename (not content)
 * is stored.
 *
 * Multiple filenames can be added per name (hence CURLFORM_END needed after
 * CURLFORM_FILE).
 *
 * Examples:
 *
 * Simple name/value pair with copied contents:
 * curl_formadd (&post, &last, CURLFORM_COPYNAME, "field",
 * CURLFORM_COPYCONTENTS, "data", CURLFORM_END);
 *
 * name/value pair where only the content pointer is remembered:
 * curl_formadd (&post, &last, CURLFORM_COPYNAME, "field",
 * CURLFORM_PTRCONTENTS, ptr, CURLFORM_CONTENTSLENGTH, 10, CURLFORM_END);
 * (if CURLFORM_CONTENTSLENGTH omitted, strlen() is used)
 *
 * storing a filename (CONTENTTYPE optional):
 * curl_formadd (&post, &last, CURLFORM_COPYNAME, "field",
 * CURLFORM_FILE, "file1", CURLFORM_CONTENTTYPE, "text/plain",
 * CURLFORM_END);
 *
 * storing multiple filenames:
 * curl_formadd (&post, &last, CURLFORM_COPYNAME, "field",
 * CURLFORM_FILE, "file1", CURLFORM_FILE, "file2", CURLFORM_END);
 *
 * Returns:
 * CURL_FORMADD_OK             on success
 * CURL_FORMADD_MEMORY         if the FormInfo allocation fails
 * CURL_FORMADD_OPTION_TWICE   if one option is given twice for one Form
 * CURL_FORMADD_NULL           if a null pointer was given for a char
 * CURL_FORMADD_MEMORY         if the allocation of a FormInfo struct failed
 * CURL_FORMADD_UNKNOWN_OPTION if an unknown option was used
 * CURL_FORMADD_INCOMPLETE     if some FormInfo is not complete (or error)
 * CURL_FORMADD_MEMORY         if an HttpPost struct cannot be allocated
 * CURL_FORMADD_MEMORY         if some allocation for string copying failed.
 * CURL_FORMADD_ILLEGAL_ARRAY  if an illegal option is used in an array
 *
 ***************************************************************************/
static CURLFORMcode ValidateForm(struct FormInfo *head_form,
                                 struct curl_httppost **httppost,
                                 struct curl_httppost **last_post)
{
  const char *last_type = NULL;
  struct FormInfo *curr = NULL;
  struct curl_httppost *item = NULL;
  /* traverse the list, verify completeness and validity; if everything
   * checks out, add the HttpPost item; otherwise set retval accordingly */
  for(curr = head_form;
      curr != NULL;
      curr = curr->more) {
    if(((!curr->name || !curr->value) && !item) ||
       ( (curr->contentslength) &&
         (curr->flags & HTTPPOST_FILENAME) ) ||
       ( (curr->flags & HTTPPOST_FILENAME) &&
         (curr->flags & HTTPPOST_PTRCONTENTS) ) ||
       ( (!curr->buffer) &&
         (curr->flags & HTTPPOST_BUFFER) &&
         (curr->flags & HTTPPOST_PTRBUFFER) ) ||
       ( (curr->flags & HTTPPOST_READFILE) &&
         (curr->flags & HTTPPOST_PTRCONTENTS) )
      ) {
      return CURL_FORMADD_INCOMPLETE;
    }
    if(((curr->flags & HTTPPOST_FILENAME) ||
        (curr->flags & HTTPPOST_BUFFER)) &&
       !curr->contenttype) {
      char *f = (curr->flags & HTTPPOST_BUFFER) ?
        curr->showfilename : curr->value;
      char const *mimetype;
      mimetype = Curl_mime_contenttype(f);
      if(!mimetype)
        mimetype = last_type;
      if(!mimetype)
        mimetype = FILE_CONTENTTYPE_DEFAULT;
      /* missing contenttype */
      curr->contenttype = strdup(mimetype);
      if(!curr->contenttype)
        return CURL_FORMADD_MEMORY;
      curr->contenttype_alloc = TRUE;
    }
    if(curr->name && curr->namelength) {
      if(memchr(curr->name, 0, curr->namelength))
        return CURL_FORMADD_NULL;
    }
    if(!(curr->flags & HTTPPOST_PTRNAME) && curr->name) {
      /* Note: there is small risk that curr->name is NULL here if the app
         passed in a bad combo, so we check for that. */
      /* duplicate name (without strdup; possibly non-null-terminated) */
      char *copy_name = Curl_memdup0(curr->name, curr->namelength ?
                                   curr->namelength : strlen(curr->name));
      if(!copy_name)
        return CURL_FORMADD_MEMORY;
      curr->name = copy_name;
      curr->name_alloc = TRUE;
    }
    if(!(curr->flags & (HTTPPOST_FILENAME | HTTPPOST_READFILE |
                        HTTPPOST_PTRCONTENTS | HTTPPOST_PTRBUFFER |
                        HTTPPOST_CALLBACK)) && curr->value) {
      /* duplicate value (without strdup; may contain null chars) */
      size_t vlen  = (size_t) curr->contentslength;
      if(!vlen)
        vlen = strlen(curr->value) + 1;
      curr->value = Curl_memdup(curr->value, vlen);
      if(!curr->value)
        return CURL_FORMADD_MEMORY;
      curr->value_alloc = TRUE;
    }
    item = InsertHttpPost(curr, item, httppost, last_post);
    if(!item)
      return CURL_FORMADD_MEMORY;
    if(curr->contenttype)
      last_type = curr->contenttype;
  }
  return CURL_FORMADD_OK;
}

/* Shallow cleanup. Remove the newly created chain, the structs only and not
   the content they point to */
static void clear_chain(struct curl_httppost *c)
{
  while(c) {
    struct curl_httppost *nxt = c->next;
    if(c->more)
      clear_chain(c->more);
    free(c);
    c = nxt;
  }
}

static
CURLFORMcode BuildForm(struct curl_httppost **httppost,
                     struct curl_httppost **last_post,
                     va_list args)
{
  struct FormInfo *first_form, *current, *info = NULL;
  CURLFORMcode status = CURL_FORMADD_OK;
  CURLformoption opt;
  struct curl_forms *forms = NULL;
  char *rvalue = NULL;
  struct curl_httppost *chain = NULL;
  struct curl_httppost *tail = NULL;
  /* This is a state variable, that if TRUE means that we are parsing an
     array that we got passed to us. If FALSE we are parsing the input
     va_list arguments. */
  bool array_mode = FALSE;
  /*
   * Allocate the first struct to fill in.
   */
  first_form = calloc(1, sizeof(struct FormInfo));
  if(!first_form)
    return CURL_FORMADD_MEMORY;
  current = first_form;
  /*
   * Loop through all the options set. Break if we have an error to report.
   */
  while(status == CURL_FORMADD_OK) {
    /* first see if we have more parts of the array param */
    if(array_mode && forms) {
      /* get the upcoming option from the given array */
      opt = forms->option;
      rvalue = (char *)CURL_UNCONST(forms->value);
      forms++; /* advance this to next entry */
      if(CURLFORM_END == opt) {
        /* end of array mode */
        array_mode = FALSE;
        continue;
      }
    }
    else {
      /* Not array-mode, get next option. This gets an 'int' with
         va_arg() because CURLformoption might be a smaller type than int and
         might cause compiler warnings and wrong behavior. */
      opt = (CURLformoption)va_arg(args, int);
      if(CURLFORM_END == opt)
        break;
    }
    switch(opt) {
    case CURLFORM_ARRAY:
      if(array_mode)
        /* nested arrays not supported */
        status = CURL_FORMADD_ILLEGAL_ARRAY;
      else {
        forms = va_arg(args, struct curl_forms *);
        if(forms)
          array_mode = TRUE;
        else
          status = CURL_FORMADD_NULL;
      }
      break;
      /*
       * Set the Name property.
       */
    case CURLFORM_PTRNAME:
      current->flags |= HTTPPOST_PTRNAME; /* fall through */
      FALLTHROUGH();
    case CURLFORM_COPYNAME:
      if(current->name)
        status = CURL_FORMADD_OPTION_TWICE;
      else {
        if(!array_mode)
          rvalue = va_arg(args, char *);
        if(rvalue)
          current->name = rvalue; /* store for the moment */
        else
          status = CURL_FORMADD_NULL;
      }
      break;
    case CURLFORM_NAMELENGTH:
      if(current->namelength)
        status = CURL_FORMADD_OPTION_TWICE;
      else
        current->namelength =
          array_mode ? (size_t)rvalue : (size_t)va_arg(args, long);
      break;
      /*
       * Set the contents property.
       */
    case CURLFORM_PTRCONTENTS:
      current->flags |= HTTPPOST_PTRCONTENTS;
      FALLTHROUGH();
    case CURLFORM_COPYCONTENTS:
      if(current->value)
        status = CURL_FORMADD_OPTION_TWICE;
      else {
        if(!array_mode)
          rvalue = va_arg(args, char *);
        if(rvalue)
          current->value = rvalue; /* store for the moment */
        else
          status = CURL_FORMADD_NULL;
      }
      break;
    case CURLFORM_CONTENTSLENGTH:
      current->contentslength =
        array_mode ? (size_t)rvalue : (size_t)va_arg(args, long);
      break;
    case CURLFORM_CONTENTLEN:
      current->flags |= CURL_HTTPPOST_LARGE;
      current->contentslength =
        array_mode ? (curl_off_t)(size_t)rvalue :
        va_arg(args, curl_off_t);
      break;
      /* Read contents from a given filename */
    case CURLFORM_FILECONTENT:
      if(current->flags & (HTTPPOST_PTRCONTENTS|HTTPPOST_READFILE))
        status = CURL_FORMADD_OPTION_TWICE;
      else {
        if(!array_mode)
          rvalue = va_arg(args, char *);
        if(rvalue) {
          current->value = strdup(rvalue);
          if(!current->value)
            status = CURL_FORMADD_MEMORY;
          else {
            current->flags |= HTTPPOST_READFILE;
            current->value_alloc = TRUE;
          }
        }
        else
          status = CURL_FORMADD_NULL;
      }
      break;
      /* Upload a file */
    case CURLFORM_FILE:
      if(!array_mode)
        rvalue = va_arg(args, char *);
      if(current->value) {
        if(current->flags & HTTPPOST_FILENAME) {
          if(rvalue) {
            char *fname = strdup(rvalue);
            if(!fname)
              status = CURL_FORMADD_MEMORY;
            else {
              info = InsertFormInfo(fname, NULL, current);
              if(!info) {
                free(fname);
                status = CURL_FORMADD_MEMORY;
              }
              else {
                info->value_alloc = TRUE;
                current = info;
                info = NULL;
              }
            }
          }
          else
            status = CURL_FORMADD_NULL;
        }
        else
          status = CURL_FORMADD_OPTION_TWICE;
      }
      else {
        if(rvalue) {
          current->value = strdup(rvalue);
          if(!current->value)
            status = CURL_FORMADD_MEMORY;
          else {
            current->flags |= HTTPPOST_FILENAME;
            current->value_alloc = TRUE;
          }
        }
        else
          status = CURL_FORMADD_NULL;
      }
      break;
    case CURLFORM_BUFFERPTR:
      current->flags |= HTTPPOST_PTRBUFFER|HTTPPOST_BUFFER;
      if(current->buffer)
        status = CURL_FORMADD_OPTION_TWICE;
      else {
        if(!array_mode)
          rvalue = va_arg(args, char *);
        if(rvalue) {
          current->buffer = rvalue; /* store for the moment */
          current->value = rvalue; /* make it non-NULL to be accepted
                                           as fine */
        }
        else
          status = CURL_FORMADD_NULL;
      }
      break;
    case CURLFORM_BUFFERLENGTH:
      if(current->bufferlength)
        status = CURL_FORMADD_OPTION_TWICE;
      else
        current->bufferlength =
          array_mode ? (size_t)rvalue : (size_t)va_arg(args, long);
      break;
    case CURLFORM_STREAM:
      current->flags |= HTTPPOST_CALLBACK;
      if(current->userp)
        status = CURL_FORMADD_OPTION_TWICE;
      else {
        if(!array_mode)
          rvalue  = va_arg(args, char *);
        if(rvalue) {
          current->userp = rvalue;
          current->value = rvalue; /* this is not strictly true but we derive a
                                   value from this later on and we need this
                                   non-NULL to be accepted as a fine form
                                   part */
        }
        else
          status = CURL_FORMADD_NULL;
      }
      break;
    case CURLFORM_CONTENTTYPE:
      if(!array_mode)
        rvalue = va_arg(args, char *);
      if(current->contenttype) {
        if(current->flags & HTTPPOST_FILENAME) {
          if(rvalue) {
            char *type = strdup(rvalue);
            if(!type)
              status = CURL_FORMADD_MEMORY;
            else {
              info = InsertFormInfo(NULL, type, current);
              if(!info) {
                free(type);
                status = CURL_FORMADD_MEMORY;
              }
              else {
                info->contenttype_alloc = TRUE;
                current = info;
                info = NULL;
              }
            }
          }
          else
            status = CURL_FORMADD_NULL;
        }
        else
          status = CURL_FORMADD_OPTION_TWICE;
      }
      else {
        if(rvalue) {
          current->contenttype = strdup(rvalue);
          if(!current->contenttype)
            status = CURL_FORMADD_MEMORY;
          else
            current->contenttype_alloc = TRUE;
        }
        else
          status = CURL_FORMADD_NULL;
      }
      break;
    case CURLFORM_CONTENTHEADER:
      {
        /* cast avoids alignment warning */
        struct curl_slist *list = array_mode ?
          (struct curl_slist *)(void *)rvalue :
          va_arg(args, struct curl_slist *);
        if(current->contentheader)
          status = CURL_FORMADD_OPTION_TWICE;
        else
          current->contentheader = list;
        break;
      }
    case CURLFORM_FILENAME:
    case CURLFORM_BUFFER:
      if(!array_mode)
        rvalue = va_arg(args, char *);
      if(current->showfilename)
        status = CURL_FORMADD_OPTION_TWICE;
      else {
        current->showfilename = strdup(rvalue);
        if(!current->showfilename)
          status = CURL_FORMADD_MEMORY;
        else
          current->showfilename_alloc = TRUE;
      }
      break;
    default:
      status = CURL_FORMADD_UNKNOWN_OPTION;
      break;
    }
  }
  if(!status)
    status = ValidateForm(first_form, &chain, &tail);
  if(status)
    /* On error, free allocated fields for all nodes of the FormInfo linked
       list without deallocating nodes. List nodes are deallocated later on */
    release_formlist(first_form);
  /* Always deallocate FormInfo linked list nodes without touching node
     fields given that these have either been deallocated or are owned
     now by the httppost linked list */
  while(first_form) {
    struct FormInfo *tmp = first_form->more;
    free(first_form);
    first_form = tmp;
  }
  if(!status) {
    /* Only if all is fine, link the new chain into the provided list */
    if(*last_post)
      (*last_post)->next = chain;
    else
      (*httppost) = chain;
    (*last_post) = tail;
  }
  else
    clear_chain(chain);
  return status;
}

/*
 * curl_formadd() is a public API to add a section to the multipart formpost.
 *
 * @unittest: 1308
 */
CURLFORMcode curl_formadd(struct curl_httppost **httppost,
                          struct curl_httppost **last_post,
                          ...)
{
  va_list ap;
  CURLFORMcode res;
  va_start(ap, last_post);
  res = BuildForm(httppost, last_post, ap);
  va_end(ap);
  return res;
}

/*
 * curl_formget()
 * Serialize a curl_httppost struct.
 * Returns 0 on success.
 *
 * @unittest: 1308
 */
int curl_formget(struct curl_httppost *form, void *arg,
                 curl_formget_callback append)
{
  CURLcode err;
  curl_mimepart top_part;
  Curl_mime_initpart(&top_part); /* default form is empty */
  err = Curl_getformdata(NULL, &top_part, form, NULL);
  if(!err)
    err = Curl_mime_prepare_headers(NULL, &top_part, "multipart/form-data",
                                       NULL, MIMESTRATEGY_FORM);
  while(!err) {
    char buf[8192];
    size_t read_bytes = Curl_mime_read(buf, 1, sizeof(buf), &top_part);
    if(!read_bytes)
      break;
    if(read_bytes > sizeof(buf) || append(arg, buf, read_bytes) != read_bytes) {
      err = CURLE_READ_ERROR;
      if(read_bytes == CURL_READFUNC_ABORT)
        err = CURLE_ABORTED_BY_CALLBACK;
    }
  }
  Curl_mime_cleanpart(&top_part);
  return (int) err;
}

/*
 * curl_formfree() is an external function to free up a whole form post
 * chain
 */
void curl_formfree(struct curl_httppost *form)
{
  struct curl_httppost *next;
  if(!form)
    /* no form to free, just exit */
    return;
  do {
    next = form->next;  /* next form line */
    /* recurse to sub-contents */
    curl_formfree(form->more);
    if(!(form->flags & HTTPPOST_PTRNAME))
      free(form->name); /* free the name */
    if(!(form->flags &
         (HTTPPOST_PTRCONTENTS|HTTPPOST_BUFFER|HTTPPOST_CALLBACK))
      )
      free(form->contents); /* free the contents */
    free(form->contenttype); /* free the content type */
    free(form->showfilename); /* free the fake filename */
    free(form);       /* free the struct */
    form = next;
  } while(form); /* continue */
}

/* Set mime part name, handling non null-terminated name string. */
static CURLcode assign_name(curl_mimepart *part, const char *name, size_t len)
{
  char *zname;
  CURLcode rv;
  if(!name || !len)
    return curl_mime_name(part, name);
  zname = Curl_memdup0(name, len);
  if(!zname)
    return CURLE_OUT_OF_MEMORY;
  rv = curl_mime_name(part, zname);
  free(zname);
  return rv;
}

/* wrap call to fseeko so it matches the calling convention of callback */
static int fseeko_wrapper(void *stream, curl_off_t offset, int whence)
{
#if defined(_WIN32) && defined(USE_WIN32_LARGE_FILES)
  return _fseeki64(stream, (__int64)offset, whence);
#elif defined(HAVE_FSEEKO) && defined(HAVE_DECL_FSEEKO)
  return fseeko(stream, (off_t)offset, whence);
#else
  if(offset > LONG_MAX)
    return -1;
  return fseek(stream, (long)offset, whence);
#endif
}

/*
 * Curl_getformdata() converts a linked list of "meta data" into a mime
 * structure. The input list is in 'post', while the output is stored in
 * mime part at '*finalform'.
 *
 * This function will not do a failf() for the potential memory failures but
 * should for all other errors it spots. Just note that this function MAY get
 * a NULL pointer in the 'data' argument.
 */
CURLcode Curl_getformdata(CURL *handle,
                          curl_mimepart *finalform,
                          struct curl_httppost *post,
                          curl_read_callback fread_func)
{
  CURLcode result = CURLE_OK;
  curl_mime *form = NULL;
  curl_mimepart *part;
  struct curl_httppost *file;
  Curl_mime_cleanpart(finalform); /* default form is empty */
  if(!post)
    return result; /* no input => no output! */
  form = curl_mime_init(handle);
  if(!form)
    result = CURLE_OUT_OF_MEMORY;
  if(!result)
    result = curl_mime_subparts(finalform, form);
  /* Process each top part. */
  for(; !result && post; post = post->next) {
    /* If we have more than a file here, create a mime subpart and fill it. */
    curl_mime *multipart = form;
    if(post->more) {
      part = curl_mime_addpart(form);
      if(!part)
        result = CURLE_OUT_OF_MEMORY;
      if(!result)
        result = assign_name(part, post->name, post->namelength);
      if(!result) {
        multipart = curl_mime_init(handle);
        if(!multipart)
          result = CURLE_OUT_OF_MEMORY;
      }
      if(!result)
        result = curl_mime_subparts(part, multipart);
    }
    /* Generate all the part contents. */
    for(file = post; !result && file; file = file->more) {
      /* Create the part. */
      part = curl_mime_addpart(multipart);
      if(!part)
        result = CURLE_OUT_OF_MEMORY;
      /* Set the headers. */
      if(!result)
        result = curl_mime_headers(part, file->contentheader, 0);
      /* Set the content type. */
      if(!result && file->contenttype)
        result = curl_mime_type(part, file->contenttype);
      /* Set field name. */
      if(!result && !post->more)
        result = assign_name(part, post->name, post->namelength);
      /* Process contents. */
      if(!result) {
        curl_off_t clen = post->contentslength;
        if(post->flags & CURL_HTTPPOST_LARGE)
          clen = post->contentlen;
        if(post->flags & (HTTPPOST_FILENAME | HTTPPOST_READFILE)) {
          if(!strcmp(file->contents, "-")) {
            /* There are a few cases where the code below will not work; in
               particular, freopen(stdin) by the caller is not guaranteed
               to result as expected. This feature has been kept for backward
               compatibility: use of "-" pseudo filename should be avoided. */
            result = curl_mime_data_cb(part, (curl_off_t) -1,
                                       (curl_read_callback) fread,
                                       fseeko_wrapper,
                                       NULL, (void *) stdin);
          }
          else
            result = curl_mime_filedata(part, file->contents);
          if(!result && (post->flags & HTTPPOST_READFILE))
            result = curl_mime_filename(part, NULL);
        }
        else if(post->flags & HTTPPOST_BUFFER)
          result = curl_mime_data(part, post->buffer,
                                  post->bufferlength ?
                                  post->bufferlength : -1);
        else if(post->flags & HTTPPOST_CALLBACK) {
          /* the contents should be read with the callback and the size is set
             with the contentslength */
          if(!clen)
            clen = -1;
          result = curl_mime_data_cb(part, clen,
                                     fread_func, NULL, NULL, post->userp);
        }
        else {
          size_t uclen;
          if(!clen)
            uclen = CURL_ZERO_TERMINATED;
          else
            uclen = (size_t)clen;
          result = curl_mime_data(part, post->contents, uclen);
        }
      }
      /* Set fake filename. */
      if(!result && post->showfilename)
        if(post->more || (post->flags & (HTTPPOST_FILENAME | HTTPPOST_BUFFER |
                                        HTTPPOST_CALLBACK)))
          result = curl_mime_filename(part, post->showfilename);
    }
  }
  if(result)
    Curl_mime_cleanpart(finalform);
  return result;
}
#else
/* if disabled */
CURLFORMcode curl_formadd(struct curl_httppost **httppost,
                          struct curl_httppost **last_post,
                          ...)
{
  (void)httppost;
  (void)last_post;
  return CURL_FORMADD_DISABLED;
}
int curl_formget(struct curl_httppost *form, void *arg,
                 curl_formget_callback append)
{
  (void) form;
  (void) arg;
  (void) append;
  return CURL_FORMADD_DISABLED;
}
void curl_formfree(struct curl_httppost *form)
{
  (void)form;
  /* Nothing to do. */
}
