namespace CTRPF = CTRPluginFramework;
using SlotType = Minecraft::Inventory::InventorySlot;
using ItemType = Game::Item;

// ----------------------------------------------------------------------------
//$Game.LocalPlayer.Inventory
//#$Game.LocalPlayer.Inventory.Slots : ---@type table<"hand"|1|2|...|36,InventorySlot>
//#$Game.LocalPlayer.Inventory.ArmorSlots : ---@type table<"helmet"|"chestplate"|"leggings"|"boots"|1|2|3|4,InventorySlot>
// ----------------------------------------------------------------------------

static int l_Inventory_Slots_get(lua_State *L) {
    int slotIdx = 0;
    if (lua_type(L, 2) == LUA_TNUMBER)
        slotIdx = static_cast<int>(lua_tonumber(L, 2));
    else if (lua_type(L, 2) == LUA_TSTRING) {
        uint32_t hval = hash(lua_tostring(L, 2));
        if (hval == hash("hand"))
            slotIdx = Minecraft::GetHeldSlotNumber();
    }
    LuaObjectUtils::NewObjectCheck(L, "InventorySlot", (SlotType*)Minecraft::GetSlotAddress(slotIdx));
    return 1;
}

// ----------------------------------------------------------------------------
//@@InventorySlot
/*
## return: boolean
### InventorySlot:isEmpty
*/
static int l_InventorySlot_isEmpty(lua_State *L) {
    SlotType* pSlot = LuaObjectUtils::CheckObject<SlotType>(L, 1, "InventorySlot").get();
    lua_pushboolean(L, pSlot->itemCount == 0 || pSlot->itemData == nullptr);
    return 1;
}

/*
## item: GameItem
## value: integer?
## return: boolean
### InventorySlot:setItem
*/
static int l_InventorySlot_setItem(lua_State *L) {
    auto pSlot = LuaObjectUtils::CheckObject<MC3DSPluginFramework::ItemInstance>(L, 1, "InventorySlot").get();
    ItemType* pItem = LuaObjectUtils::CheckObject<ItemType>(L, 2, "GameItem").get();
    u16 nData = 0;
    if (lua_gettop(L) > 2)
        nData = static_cast<u16>(luaL_checknumber(L, 3));

    u8 nCount = pSlot->mCount;
    if (nCount > pItem->maxStackSize)
        nCount = pItem->maxStackSize;

    pSlot->init((MC3DSPluginFramework::ItemId)pItem->itemId, nCount, nData);
    return 1;
}

/*
#$InventorySlot.Item : ---@type GameItem?
=InventorySlot.ItemCount = 0
=InventorySlot.ItemData = 0
*/

// ----------------------------------------------------------------------------
static int l_Inventory_ArmorSlots_get(lua_State *L) {
    int armorIdx = 0;
    if (lua_type(L, 2) == LUA_TNUMBER) {
        armorIdx = static_cast<int>(lua_tonumber(L, 2));
    } else if (lua_type(L, 2) == LUA_TSTRING) {
        uint32_t hval = hash(lua_tostring(L, 2));
        switch (hval) {
            case hash("helmet"):
                armorIdx = 1;
                break;
            case hash("chestplate"):
                armorIdx = 2;
                break;
            case hash("leggings"):
                armorIdx = 3;
                break;
            case hash("boots"):
                armorIdx = 4;
                break;
        }
    }
    LuaObjectUtils::NewObjectCheck(L, "InventorySlot", (SlotType*)Minecraft::GetArmorSlotAddress(armorIdx));
    return 1;
}

// ----------------------------------------------------------------------------
template<>
struct LuaTypeName<ItemType> {
    static constexpr const char* value = "GameItem";
};

// Required to be called inside LocalPlayer definition
bool Core::Module::LocalPlayer::RegisterInventoryModule(lua_State *L) {
    ClassBuilder<SlotType>(L, "InventorySlot")
        .property("Item", &SlotType::itemData)
        .property("ItemCount", &SlotType::itemCount)
        .property("ItemData", &SlotType::dataValue)
        .method("isEmpty", l_InventorySlot_isEmpty)
        .method("setItem", l_InventorySlot_setItem)
        .build();

    LuaCustomTable::RegisterNewCustomTable(L, "Inventory");
    LuaCustomTable::RegisterNewCustomTable(L, "Inventory.Slots", l_Inventory_Slots_get);
    LuaCustomTable::RegisterNewCustomTable(L, "Inventory.ArmorSlots", l_Inventory_ArmorSlots_get);

    LuaCustomTable::GetIndexTable(L, "Inventory"); // LocalPlayer.Inventory
    LuaCustomTable::NewCustomTable(L, "Inventory.Slots"); // LocalPlayer.Inventory.Slots
    lua_setfield(L, -2, "Slots");

    LuaCustomTable::NewCustomTable(L, "Inventory.ArmorSlots"); // LocalPlayer.Inventory.ArmorSlots
    lua_setfield(L, -2, "ArmorSlots");

    lua_pop(L, 1); // Pop inventory index table

    LuaCustomTable::SetNewCustomTable(L, -1, "Inventory"); // Sets Inventory to LocalPlayer
    return true;
}

