#include "USBMIDIParser.h"

uint8_t USBMIDICinToMIDIByteCount(uint8_t type)
{
    switch (type) {
        case kCIN_Misc:              return 0;
        case kCIN_CableEvent:        return 0;
        case kCIN_SystemCommon2Byte: return 2;
        case kCIN_SystemCommon3Byte: return 3;
        case kCIN_SysExStart:        return 3;
        case kCIN_SysExEnd1Byte:     return 1;
        case kCIN_SysExEnd2Byte:     return 2;
        case kCIN_SysExEnd3Byte:     return 3;
        case kCIN_NoteOff:           return 3;
        case kCIN_NoteOn:            return 3;
        case kCIN_PolyAftertouch:    return 3;
        case kCIN_ControlChange:     return 3;
        case kCIN_ProgramChange:     return 2;
        case kCIN_ChannelPressure:   return 2;
        case kCIN_PitchBend:         return 3;
        case kCIN_SingleByte:        return 1;
        default:                     return 0;
    }
}

uint8_t MIDIStatusToCin(uint8_t status)
{
    if (status < 0x80) return kCIN_Misc;

    uint8_t upperNibble = status >> 4;
    switch (upperNibble) {
        case 0x8: return kCIN_NoteOff;
        case 0x9: return kCIN_NoteOn;
        case 0xA: return kCIN_PolyAftertouch;
        case 0xB: return kCIN_ControlChange;
        case 0xC: return kCIN_ProgramChange;
        case 0xD: return kCIN_ChannelPressure;
        case 0xE: return kCIN_PitchBend;
        case 0xF:
            switch (status) {
                case 0xF0: return kCIN_SysExStart;
                case 0xF1: return kCIN_SystemCommon2Byte;
                case 0xF2: return kCIN_SystemCommon3Byte;
                case 0xF3: return kCIN_SystemCommon2Byte;
                case 0xF6: return kCIN_SysExEnd1Byte;
                case 0xF7: return kCIN_SysExEnd1Byte;
                case 0xF8: case 0xFA: case 0xFB: case 0xFC:
                case 0xFE: case 0xFF:
                    return kCIN_SingleByte;
                default:   return kCIN_Misc;
            }
        default: return kCIN_Misc;
    }
}

void USBMIDIParseBulkIn(const uint8_t *inputData,
                        uint32_t size,
                        USBMIDIParseCallback handler,
                        void *userData)
{
    if (!inputData || !handler) return;

    for (uint32_t pos = 0; pos + 4 <= size; pos += 4) {
        uint8_t header = inputData[pos];
        uint8_t cinType = header & 0x0F;
        uint8_t cableNum = (header >> 4) & 0x0F;

        uint8_t bytesExpected = USBMIDICinToMIDIByteCount(cinType);
        if (bytesExpected == 0) continue;

        const uint8_t *payload = &inputData[pos + 1];
        handler(cableNum, payload, bytesExpected, userData);
    }
}

static uint8_t channelMsgLength(uint8_t status)
{
    switch (status & 0xF0) {
        case 0xC0: return 2;
        case 0xD0: return 2;
        default:   return 3;
    }
}

uint32_t USBMIDIBuildBulkOut(const uint8_t *midiData,
                             uint32_t count,
                             uint8_t cableIndex,
                             uint8_t *outputBuffer,
                             uint32_t bufferCapacity)
{
    if (!midiData || !outputBuffer || count == 0) return 0;

    uint32_t writePos = 0;
    uint32_t readIdx = 0;
    bool sysexActive = false;
    uint8_t sysexBuffer[3];
    uint8_t sysexLen = 0;

    while (readIdx < count && writePos + 4 <= bufferCapacity) {
        uint8_t currentByte = midiData[readIdx];

        if (currentByte == 0xF0) {
            sysexActive = true;
            sysexBuffer[0] = currentByte;
            sysexLen = 1;
            readIdx++;
        } else if (sysexActive) {
            if (currentByte == 0xF7) {
                sysexBuffer[sysexLen] = currentByte;
                sysexLen++;

                uint8_t cinCode;
                switch (sysexLen) {
                    case 1: cinCode = kCIN_SysExEnd1Byte; break;
                    case 2: cinCode = kCIN_SysExEnd2Byte; break;
                    case 3: cinCode = kCIN_SysExEnd3Byte; break;
                    default: cinCode = kCIN_SysExEnd1Byte; break;
                }

                outputBuffer[writePos + 0] = (cableIndex << 4) | cinCode;
                outputBuffer[writePos + 1] = (sysexLen >= 1) ? sysexBuffer[0] : 0;
                outputBuffer[writePos + 2] = (sysexLen >= 2) ? sysexBuffer[1] : 0;
                outputBuffer[writePos + 3] = (sysexLen >= 3) ? sysexBuffer[2] : 0;
                writePos += 4;
                sysexActive = false;
                sysexLen = 0;
                readIdx++;
            } else if (currentByte >= 0x80 && currentByte != 0xF7) {
                // Real-time message inside SysEx
                outputBuffer[writePos + 0] = (cableIndex << 4) | kCIN_SingleByte;
                outputBuffer[writePos + 1] = currentByte;
                outputBuffer[writePos + 2] = 0;
                outputBuffer[writePos + 3] = 0;
                writePos += 4;
                readIdx++;
            } else {
                sysexBuffer[sysexLen] = currentByte;
                sysexLen++;
                readIdx++;
                if (sysexLen == 3) {
                    outputBuffer[writePos + 0] = (cableIndex << 4) | kCIN_SysExStart;
                    outputBuffer[writePos + 1] = sysexBuffer[0];
                    outputBuffer[writePos + 2] = sysexBuffer[1];
                    outputBuffer[writePos + 3] = sysexBuffer[2];
                    writePos += 4;
                    sysexLen = 0;
                }
            }
        } else if (currentByte >= 0x80) {
            if (currentByte >= 0xF8) {
                outputBuffer[writePos + 0] = (cableIndex << 4) | kCIN_SingleByte;
                outputBuffer[writePos + 1] = currentByte;
                outputBuffer[writePos + 2] = 0;
                outputBuffer[writePos + 3] = 0;
                writePos += 4;
                readIdx++;
            } else if (currentByte >= 0xF0) {
                uint8_t cinCode = MIDIStatusToCin(currentByte);
                uint8_t msgSize = USBMIDICinToMIDIByteCount(cinCode);
                if (readIdx + msgSize > count) break;
                outputBuffer[writePos + 0] = (cableIndex << 4) | cinCode;
                outputBuffer[writePos + 1] = (msgSize >= 1) ? midiData[readIdx] : 0;
                outputBuffer[writePos + 2] = (msgSize >= 2) ? midiData[readIdx + 1] : 0;
                outputBuffer[writePos + 3] = (msgSize >= 3) ? midiData[readIdx + 2] : 0;
                writePos += 4;
                readIdx += msgSize;
            } else {
                uint8_t msgSize = channelMsgLength(currentByte);
                if (readIdx + msgSize > count) break;
                uint8_t cinCode = MIDIStatusToCin(currentByte);
                outputBuffer[writePos + 0] = (cableIndex << 4) | cinCode;
                outputBuffer[writePos + 1] = midiData[readIdx];
                outputBuffer[writePos + 2] = (msgSize >= 2) ? midiData[readIdx + 1] : 0;
                outputBuffer[writePos + 3] = (msgSize >= 3) ? midiData[readIdx + 2] : 0;
                writePos += 4;
                readIdx += msgSize;
            }
        } else {
            readIdx++; // Skip data byte without status
        }
    }

    return writePos;
}

