/*not-null*/ std::shared_ptr<::snap::valdi_core::Cancelable> 
NativeHTTPRequestManager::JavaProxy::performRequest(
    const ::snap::valdi_core::HTTPRequest & request_obj,
    const /*not-null*/ std::shared_ptr<::snap::valdi_core::HTTPRequestManagerCompletion> & completion_obj) 
{
    DJINNI_FUNCTION_PROLOGUE("HTTPRequestManager.performRequest");

    auto env = ::djinni::jniGetThreadEnv();
    ::djinni::JniLocalScope scope(env, 10);

    const auto& class_data = ::djinni::JniClass<::djinni_generated_client::valdi_core::NativeHTTPRequestManager>::get();

    auto j_result = env->CallObjectMethod(
        Handle::get().get(), 
        class_data.method_performRequest,
        ::djinni::get(::djinni_generated_client::valdi_core::NativeHTTPRequest::fromCpp(env, request_obj)),
        ::djinni::get(::djinni_generated_client::valdi_core::NativeHTTPRequestManagerCompletion::fromCpp(env, completion_obj))
    );

    ::djinni::jniExceptionCheck(env);

    return ::djinni_generated_client::valdi_core::NativeCancelable::toCpp(env, j_result);
