#include <string>

// Process MIDI loading with post-initialization steps
bool OPNMIDIplay::LoadMIDI_post() 
{
    Synth &synth = *m_synth;
    MidiSequencer &seq = *m_sequencer;
    MidiSequencer::FileFormat fileFormat = seq.getFormat();

    if(fileFormat == MidiSequencer::Format_CMF) 
    {
        errorStringOut = "OPNMIDI doesn't support CMF, use ADLMIDI to play this file!";
        /* As a joke, why not implement a converter of patches from OPL3 into OPN2? */
        return false;
    } 
    else if(fileFormat == MidiSequencer::Format_RSXX) 
    {
        synth.m_musicMode     = Synth::MODE_RSXX;
        synth.m_volumeScale   = Synth::VOLUME_Generic;
        synth.m_numChips      = 2;
    } 
    else if(fileFormat == MidiSequencer::Format_IMF) 
    {
        errorStringOut = "OPNMIDI doesn't support IMF, use ADLMIDI to play this file!";
        /* Same as for CMF */
        return false;
    } 
    else if(fileFormat == MidiSequencer::Format_XMIDI) 
    {
        synth.m_musicMode = Synth::MODE_XMIDI;
    }

    m_setup.tick_skip_samples_delay = 0;
    synth.reset(m_setup.emulator, m_setup.PCM_RATE, synth.chipFamily(), this); // Reset OPN2 chip
    m_chipChannels.clear();
    m_chipChannels.resize(synth.m_numChannels);
    resetMIDIDefaults();

#ifdef OPNMIDI_MIDI2VGM
    m_sequencerInterface->onloopStart = synth.m_loopStartHook;
    m_sequencerInterface->onloopStart_userData = synth.m_loopStartHookData;
    m_sequencerInterface->onloopEnd = synth.m_loopEndHook;
    m_sequencerInterface->onloopEnd_userData = synth.m_loopEndHookData;
    m_sequencer->setLoopHooksOnly(m_sequencerInterface->onloopStart != NULL);
#endif

    return true;
}

// Load MIDI from file path
bool OPNMIDIplay::LoadMIDI(const std::string &filepath) 
{
    FileAndMemReader file;
    file.openFile(filepath.c_str());

    if(!LoadMIDI_pre())
        return false;

    MidiSequencer &seq = *m_sequencer;
    if(!seq.loadMIDI(file)) 
    {
        errorStringOut = seq.getErrorString();
        return false;
    }

    if(!LoadMIDI_post())
        return false;

    return true;
}

// Load MIDI from memory buffer
bool OPNMIDIplay::LoadMIDI(const void *buffer, size_t length) 
{
    FileAndMemReader file;
    file.openData(buffer, length);

    if(!LoadMIDI_pre())
        return false;

    MidiSequencer &seq = *m_sequencer;
    if(!seq.loadMIDI(file)) 
    {
        errorStringOut = seq.getErrorString();
        return false;
    }

    if(!LoadMIDI_post())
        return false;

    return true;
}
