#include "AsmWriterInst.h"
#include "CodeGenInstruction.h"
#include "llvm/ADT/StringExtras.h"
#include "llvm/TableGen/Error.h"
#include "llvm/TableGen/Record.h"
using namespace llvm;

static bool isIdentifierChar(char C) { return isAlnum(C) || C == '_'; }

std::string AsmWriterOperand::getAssemblyCode(bool IncludeSubtarget) const {
  if (Kind == LiteralText) {
    if (Text.size() == 1)
      return "O << '" + Text + "';";
    return "O << \"" + Text + "\";";
  }
  if (Kind == LiteralCode)
    return Text;

  std::string Code = Text + "(MI";
  if (IsPCRelative)
    Code += ", Address";
  if (OperandIndex != ~0U)
    Code += ", " + utostr(OperandIndex);
  if (IncludeSubtarget)
    Code += ", STI";
  Code += ", O";
  if (!Modifier.empty())
    Code += ", \"" + Modifier + '"';
  return Code + ");";
}

/// ParseAsmString - Analyze the given Instruction's AsmString and populate this
/// AsmWriterInst accordingly.
///
AsmWriterInst::AsmWriterInst(const CodeGenInstruction &CGI, unsigned InstIndex,
                             unsigned Variant)
    : CGI(&CGI), InstIndex(InstIndex) {
  // NOTE: Any enhancements to this logic must be mirrored in the
  // AsmPrinter::printInlineAsm implementation (for compile-time inline asm handling)!
  std::string AsmTemplate = CGI.FlattenAsmStringVariants(CGI.AsmString, Variant);
  std::string::size_type LastPosition = 0;
  while (LastPosition != AsmTemplate.size()) {
    std::string::size_type DollarPos =
      AsmTemplate.find_first_of("$\\", LastPosition);
    if (DollarPos == std::string::npos) DollarPos = AsmTemplate.size();

    // Emit a constant string fragment.
    if (DollarPos != LastPosition) {
      for (; LastPosition != DollarPos; ++LastPosition)
        switch (AsmTemplate[LastPosition]) {
          case '\n':
            AppendLiteralString("\\n");
            break;
          case '\t':
            AppendLiteralString("\\t");
            break;
          case '"':
            AppendLiteralString("\\\"");
            break;
          case '\\':
            AppendLiteralString("\\\\");
            break;
          default:
            AppendLiteralString(std::string(1, AsmTemplate[LastPosition]));
            break;
        }
    } else if (AsmTemplate[DollarPos] == '\\') {
      if (DollarPos+1 != AsmTemplate.size()) {
        if (AsmTemplate[DollarPos+1] == 'n') {
          AppendLiteralString("\\n");
        } else if (AsmTemplate[DollarPos+1] == 't') {
          AppendLiteralString("\\t");
        } else if (std::string("${|}\\").find(AsmTemplate[DollarPos+1])
                   != std::string::npos) {
          AppendLiteralString(std::string(1, AsmTemplate[DollarPos+1]));
        } else {
          PrintFatalError(
              CGI.TheDef->getLoc(),
              "Unsupported escaped character encountered in instruction '" +
                  CGI.TheDef->getName() + "'!");
        }
        LastPosition = DollarPos+2;
        continue;
      }
    } else if (DollarPos+1 != AsmTemplate.size() &&
               AsmTemplate[DollarPos+1] == '$') {
      AppendLiteralString("$");  // "$$" -> $
      LastPosition = DollarPos+2;
    } else {
      // Extract the variable name.
      std::string::size_type VarEnd = DollarPos+1;

      // Handle ${foo}bar as $foo by detecting whether the character following
      // the dollar sign is a curly brace. If so, advance VarEnd and DollarPos
      // so the variable name does not contain the leading curly brace.
      bool usesCurlyBraces = false;
      if (VarEnd < AsmTemplate.size() && '{' == AsmTemplate[VarEnd]) {
        usesCurlyBraces = true;
        ++DollarPos;
        ++VarEnd;
      }
      while (VarEnd < AsmTemplate.size() && isIdentifierChar(AsmTemplate[VarEnd]))
        ++VarEnd;
      StringRef VariableName(AsmTemplate.data()+DollarPos+1, VarEnd-DollarPos-1);

      // Modifier - Support ${foo:modifier} syntax, where "modifier" is passed
      // into printOperand. Also support ${:feature}, which is passed into
      // PrintSpecial.
      std::string ModValue;

      // Advance past closing curly brace if opening brace was found.
      if (usesCurlyBraces) {
        if (VarEnd >= AsmTemplate.size())
          PrintFatalError(
              CGI.TheDef->getLoc(),
              "Unexpected end of string before closing curly brace in '" +
                  CGI.TheDef->getName() + "'");

        // Check for modifier after colon.
        if (AsmTemplate[VarEnd] == ':') {
          ++VarEnd;
          if (VarEnd >= AsmTemplate.size())
            PrintFatalError(
                CGI.TheDef->getLoc(),
                "Unexpected end of string before modifier in '" +
                    CGI.TheDef->getName() + "'");
          std::string::size_type ModStart = VarEnd;
          while (VarEnd < AsmTemplate.size() && isIdentifierChar(AsmTemplate[VarEnd]))
            ++VarEnd;
          ModValue = AsmTemplate.substr(ModStart, VarEnd - ModStart);
          if (ModValue.empty())
            PrintFatalError(CGI.TheDef->getLoc(),
                            "Invalid operand modifier in '" +
                                CGI.TheDef->getName() + "'");
        }
        if (AsmTemplate[VarEnd] != '}')
          PrintFatalError(
              CGI.TheDef->getLoc(),
              "Variable starting with '{' did not end with '}' in '" +
                  CGI.TheDef->getName() + "'");
        ++VarEnd;
      }

      if (VariableName.empty() && ModValue.empty())
        PrintFatalError(CGI.TheDef->getLoc(),
                        "Dangling '$' in '" + CGI.TheDef->getName() +
                            "' asm string — perhaps you meant $$?");

      if (VariableName.empty()) {
        // Only a modifier present — pass to PrintSpecial.
        Operands.emplace_back("PrintSpecial", ~0U, ModValue);
      } else {
        // Normal operand reference.
        unsigned OpIndex = CGI.Operands.getOperandNamed(VariableName);
        CGIOperandList::OperandInfo OpInfo = CGI.Operands[OpIndex];
        unsigned MIOpNo = OpInfo.MIOperandNo;
        Operands.emplace_back(OpInfo.PrinterMethodName, MIOpNo, ModValue,
                              AsmWriterOperand::isMachineInstrOperand,
                              OpInfo.OperandType == "MCOI::OPERAND_PCREL");
      }
      LastPosition = VarEnd;
    }
  }
  Operands.emplace_back("return;", AsmWriterOperand::isLiteralCode);
}

/// MatchesAllButOneOp - If this instruction matches another exactly except for
/// one differing operand, return the index of that operand. If more than one
/// operand differs, return ~1; if all operands match, return ~0.
unsigned AsmWriterInst::MatchesAllButOneOp(const AsmWriterInst &Other)const{
  if (Operands.size() != Other.Operands.size()) return ~1;
  unsigned DiffOperand = ~0U;
  for (unsigned i = 0, e = Operands.size(); i != e; ++i) {
    if (Operands[i] != Other.Operands[i]) {
      if (DiffOperand != ~0U)  // Already found one mismatch?
        return ~1U;
      DiffOperand = i;
    }
  }
  return DiffOperand;
}

#include "cangjie/CHIR/Transformation/UselessAllocateElimination.h"
#include "cangjie/CHIR/Analysis/Utils.h"
#include "cangjie/CHIR/CHIRCasting.h"
#include "cangjie/CHIR/Expression/Terminator.h"

using namespace Cangjie::CHIR;

void UselessAllocateElimination::RunOnPackage(const Package& pkg, bool verbose)
{
    for (auto fn : pkg.GetGlobalFuncs()) {
        RunOnFunc(*fn, verbose);
    }
}

void UselessAllocateElimination::RunOnFunc(const Func& func, bool verbose)
{
    for (auto blk : func.GetBody()->GetBlocks()) {
        for (auto expr : blk->GetExpressions()) {
            if (expr->GetExprKind() != ExprKind::ALLOCATE) {
                continue;
            }

            auto alloc = StaticCast<Allocate*>(expr);
            if (auto ty = alloc->GetType();
                ty->IsClass() && StaticCast<ClassType*>(ty)->GetClassDef()->GetFinalizer()) {
                continue;
            }

            auto result = alloc->GetResult();
            if (func.GetReturnValue() == result) {
                continue;
            }

            auto users = result->GetUsers();
            auto onlyWrittenTo = std::all_of(users.begin(), users.end(), [result](auto e) {
                return (e->GetExprKind() == ExprKind::STORE && StaticCast<Store*>(e)->GetLocation() == result) ||
                       (e->GetExprKind() == ExprKind::STORE_ELEMENT_REF &&
                        StaticCast<StoreElementRef*>(e)->GetLocation() == result) ||
                       e->GetExprKind() == ExprKind::DEBUGEXPR;
            });

            if (onlyWrittenTo) {
                alloc->RemoveSelfFromBlock();
                for (auto user : users) {
                    user->RemoveSelfFromBlock();
                }

                if (verbose && !alloc->GetDebugLocation().GetBeginPos().IsZero()) {
                    std::string msg = "[UselessAllocateElimination] Allocation" +
                        ToPosInfo(alloc->GetDebugLocation()) + " and its users have been removed\n";
                    std::cout << msg;
                }
            }
        }
    }
}

