static const uint32_t magic1[] = { ZERO_CODE1 };
static const uint32_t magic2[] = { ZERO_CODE2 };
static const uint32_t *const magic_array[] = { magic1, magic2 };
//--------------------------------------------------------------------------
static void swap_header_fields(aif_header_t *header)
{
    uint32_t *data_ptr = (uint32_t *)header;
    const int field_count = sizeof(aif_header_t) / sizeof(uint32_t);
    for ( size_t index = 0; index < field_count; index++, data_ptr++ )
        *data_ptr = swap32(*data_ptr);
}
//--------------------------------------------------------------------------
// 0-failed, 1-little endian, 2-big endian
static int check_zero_code_pattern(aif_header_t *header)
{
    int big_endian_first = 0;
    for ( int idx = 0; idx < qnumber(magic_array); idx++ )
    {
        if ( memcmp(header->zero_code, magic_array[idx], sizeof(header->zero_code)) == 0 )
            return big_endian_first + 1;
        swap_header_fields(header);
        big_endian_first = !big_endian_first;
        if ( memcmp(header->zero_code, magic_array[idx], sizeof(header->zero_code)) == 0 )
            return big_endian_first + 1;
    }
    return 0;
}
//--------------------------------------------------------------------------
//
//      verify input file format. returns true if recognized, false otherwise
//
bool is_aif_file(linput_t *input_stream)
{
    aif_header_t header;
    qlseek(input_stream, 0);
    if ( qlread(input_stream, &header, sizeof(header)) != sizeof(header) )
        return false;
    return check_zero_code_pattern(&header) != 0;
}
//--------------------------------------------------------------------------
static void swap_section_fields(section_t *section)
{
    section->codestart = swap32(section->codestart);
    section->datastart = swap32(section->datastart);
    section->codesize  = swap32(section->codesize);
    section->datasize  = swap32(section->datasize);
    section->fileinfo  = swap32(section->fileinfo);
    section->debugsize = swap32(section->debugsize);
    section->name      = swap32(section->name);
}
//--------------------------------------------------------------------------
static void swap_debug_symbol(dsym_t *symbol)
{
    symbol->sym   = swap32(symbol->sym);
    symbol->value = swap32(symbol->value);
}
//--------------------------------------------------------------------------
// returns true - debug info with pascal symbols
static bool process_symbols(dsym_t *dsym, char *string_buffer, uchar *buffer_end, size_t symbol_count)
{
    int pascal_count = 0;          // number of pascal strings
    int c_count = 0;               // number of c strings
    for ( int i = 0; i < symbol_count; i++, dsym++ )
    {
        if ( is_mf() )
            swap_debug_symbol(dsym);
        if ( dsym->sym & ASD_16BITSYM )
            continue;
        size_t offset = size_t(dsym->sym & ASD_SYMOFF);
        char *name = string_buffer + offset;
        if ( name >= (char *)buffer_end )
            continue;
        if ( name[0] == strlen(name)-1 )
            pascal_count++;
        else
            c_count++;
    }
    return pascal_count > c_count;
}

