std::string TextEdit::GetLineText(int line_index) const
{
    if (line_index >= 0 && line_index < (int)lines.size())
        return lines[line_index].text;
    else
        return std::string();
}

std::string TextEdit::GetText() const
{
    std::string::size_type total_chars = 0;
    for (size_t idx = 0; idx < lines.size(); idx++)
        total_chars += lines[idx].text.size();
    total_chars += lines.size() - 1;

    std::string full_text;
    full_text.reserve(total_chars);
    for (size_t idx = 0; idx < lines.size(); idx++)
    {
        if (idx > 0)
            full_text.push_back('\n');
        full_text += lines[idx].text;
    }
    return full_text;
}

int TextEdit::GetLineCount() const
{
    return (int)lines.size();
}

std::string TextEdit::GetSelection() const
{
    std::string::size_type offset = ToOffset(selection_start_pos);
    int start_idx = (int)std::min(offset, offset + selection_length_val);
    return GetText().substr(start_idx, abs(selection_length_val));
}

