void TextEdit::SelectAll()
{
    std::string::size_type total_chars = 0;
    for (size_t idx = 0; idx < lines.size(); idx++)
        total_chars += lines[idx].text.size();
    total_chars += lines.size() - 1;
    SetSelection(0, (int)total_chars);
}

