void TextEdit::SetMaxLength(int length)
{
    if (max_len != length)
    {
        max_len = length;
        std::string::size_type total_chars = 0;
        for (size_t idx = 0; idx < lines.size(); idx++)
            total_chars += lines[idx].text.size();
        total_chars += lines.size() - 1;

        if ((int)total_chars > length)
        {
            if (FuncBeforeEditChanged)
                FuncBeforeEditChanged();
            SetSelection(length, (int)total_chars - length);
            DeleteSelectedText();
            if (FuncAfterEditChanged)
                FuncAfterEditChanged();
        }
        Update();
    }
}

void TextEdit::SetText(const std::string& text)
{
    lines.clear();
    std::string::size_type start_pos = 0;
    std::string::size_type end_pos = text.find('\n');
    while (end_pos != std::string::npos)
    {
        TextEdit::Line new_line{this};
        new_line.text = text.substr(start_pos, end_pos - start_pos);
        lines.push_back(new_line);
        start_pos = end_pos + 1;
        end_pos = text.find('\n', start_pos);
    }
    TextEdit::Line last_line{this};
    last_line.text = text.substr(start_pos);
    lines.push_back(last_line);
    clip_start_offset = 0;
    SetCursorPos(0);
    ClearSelection();
    Update();
}

void TextEdit::AddText(const std::string& text)
{
    std::string::size_type start_pos = 0;
    std::string::size_type end_pos = text.find('\n');
    while (end_pos != std::string::npos)
    {
        TextEdit::Line new_line{this};
        new_line.text = text.substr(start_pos, end_pos - start_pos);
        lines.push_back(new_line);
        start_pos = end_pos + 1;
        end_pos = text.find('\n', start_pos);
    }
    TextEdit::Line last_line{this};
    last_line.text = text.substr(start_pos);
    lines.push_back(last_line);
    ClearSelection();
    Update();
}

void TextEdit::SetSelection(int pos, int len)
{
    selection_start_pos = ivec2(pos, 0);
    selection_length_val = len;
    Update();
}

void TextEdit::ClearSelection()
{
    SetSelection(0, 0);
    Update();
}

void TextEdit::DeleteSelectedText()
{
    if (GetSelectionLength() == 0)
        return;
    std::string::size_type offset = ToOffset(selection_start_pos);
    int start_idx = (int)std::min(offset, offset + selection_length_val);
    int length = std::abs(selection_length_val);
    ClearSelection();
    std::string text = GetText();
    SetText(text.substr(0, start_idx) + text.substr(start_idx + length));
    SetCursorPos(start_idx);
}

void TextEdit::SetCursorPos(int pos)
{
    cursor_position = FromOffset(pos);
    Update();
}

void TextEdit::SetInputMask(const std::string& mask)
{
    input_mask_pattern = mask;
}

void TextEdit::SetCursorDrawingEnabled(bool enable)
{
    if (!read_only)
        blink_timer->Start(500);
}

void TextEdit::SetSelectAllOnFocusGain(bool enable)
{
    select_all_on_focus_gain = enable;
}

void TextEdit::OnMouseMove(const Point& pos)
{
    if (mouse_selecting && !ignore_mouse_events)
    {
        if (pos.x < 0.0 || pos.x > GetWidth())
        {
            if (pos.x < 0.0)
                mouse_moves_left = true;
            else
                mouse_moves_left = false;
            if (!read_only)
                scroll_blink_timer->Start(50, true);
        }
        else
        {
            scroll_blink_timer->Stop();
            cursor_position = GetCharacterIndex(pos);
            selection_length_val = ToOffset(cursor_position) - ToOffset(selection_start_pos);
            Update();
        }
    }
}

bool TextEdit::OnMouseDown(const Point& pos, InputKey key)
{
    if (key == InputKey::LeftMouse)
    {
        SetPointerCapture();
        mouse_selecting = true;
        cursor_position = GetCharacterIndex(pos);
        selection_start_pos = cursor_position;
        selection_length_val = 0;
        Update();
    }
    return true;
}

bool TextEdit::OnMouseDoubleclick(const Point& pos, InputKey key)
{
    return true;
}

bool TextEdit::OnMouseUp(const Point& pos, InputKey key)
{
    if (mouse_selecting && key == InputKey::LeftMouse)
    {
        if (ignore_mouse_events)
        {
            ReleasePointerCapture();
            ignore_mouse_events = false;
            mouse_selecting = false;
        }
        else
        {
            scroll_blink_timer->Stop();
            ReleasePointerCapture();
            mouse_selecting = false;
            ivec2 sel_end = GetCharacterIndex(pos);
            selection_length_val = ToOffset(sel_end) - ToOffset(selection_start_pos);
            cursor_position = sel_end;
            SetFocus();
            Update();
        }
    }
    return true;
}

void TextEdit::OnKeyChar(std::string chars)
{
    if (!read_only && !chars.empty() && !(chars[0] >= 0 && chars[0] < 32))
    {
        if (FuncBeforeEditChanged)
            FuncBeforeEditChanged();
        DeleteSelectedText();
        ClearSelection();
        if (input_mask_pattern.empty())
        {
            InsertText(cursor_position, chars);
            cursor_position.x += chars.size();
        }
        else
        {
            if (InputMaskAcceptsInput(cursor_position, chars))
            {
                InsertText(cursor_position, chars);
                cursor_position.x += chars.size();
            }
        }
        if (FuncAfterEditChanged)
            FuncAfterEditChanged();
    }
}

void TextEdit::OnKeyDown(InputKey key)
{
    if (!read_only && key == InputKey::Enter)
    {
        if (FuncEnterPressed)
        {
            FuncEnterPressed();
        }
        else
        {
            ClearSelection();
            InsertText(cursor_position, "\n");
            SetCursorPos(GetCursorPos() + 1);
        }
        return;
    }
    if (!read_only)
    {
        cursor_blink_visible = true;
        blink_timer->Start(500);
    }
    if (key == InputKey::Enter || key == InputKey::Escape || key == InputKey::Tab)
    {
        return;
    }
    else if (key == InputKey::A && GetKeyState(InputKey::Ctrl))
    {
        SelectAll();
    }
    else if (key == InputKey::C && GetKeyState(InputKey::Ctrl))
    {
        std::string str = GetSelection();
        SetClipboardText(str);
    }
    else if (read_only)
    {
        return;
    }
    else if (key == InputKey::Up)
    {
        if (GetKeyState(InputKey::Shift) && selection_length_val == 0)
            selection_start_pos = cursor_position;
        if (cursor_position.y > 0)
        {
            cursor_position.y--;
            cursor_position.x = std::min(lines[cursor_position.y].text.size(), (size_t)cursor_position.x);
        }
        if (GetKeyState(InputKey::Shift))
        {
            selection_length_val = ToOffset(cursor_position) - ToOffset(selection_start_pos);
        }
        else
        {
            selection_start_pos = ivec2(0, 0);
            selection_length_val = 0;
        }
        MoveVerticalScroll();
        Update();
        undo_info.first_text_insert = true;
    }
    else if (key == InputKey::Down)
    {
        if (GetKeyState(InputKey::Shift) && selection_length_val == 0)
            selection_start_pos = cursor_position;
        if (cursor_position.y < (int)lines.size() - 1)
        {
            cursor_position.y++;
            cursor_position.x = std::min(lines[cursor_position.y].text.size(), (size_t)cursor_position.x);
        }
        if (GetKeyState(InputKey::Shift))
        {
            selection_length_val = ToOffset(cursor_position) - ToOffset(selection_start_pos);
        }
        else
        {
            selection_start_pos = ivec2(0, 0);
            selection_length_val = 0;
        }
        MoveVerticalScroll();
        Update();
        undo_info.first_text_insert = true;
    }
    else if (key == InputKey::Left)
    {
        Move(-1, GetKeyState(InputKey::Shift), GetKeyState(InputKey::Ctrl));
    }
    else if (key == InputKey::Right)
    {
        Move(1, GetKeyState(InputKey::Shift), GetKeyState(InputKey::Ctrl));
    }
    else if (key == InputKey::Backspace)
    {
        Backspace();
    }
    else if (key == InputKey::Delete)
    {
        Del();
    }
    else if (key == InputKey::Home)
    {
        if (GetKeyState(InputKey::Ctrl))
            cursor_position = ivec2(0, 0);
        else
            cursor_position.x = 0;
        if (GetKeyState(InputKey::Shift))
            selection_length_val = ToOffset(cursor_position) - ToOffset(selection_start_pos);
        else
            ClearSelection();
        Update();
        MoveVerticalScroll();
    }
    else if (key == InputKey::End)
    {
        if (GetKeyState(InputKey::Ctrl))
            cursor_position = ivec2(lines.back().text.length(), lines.size() - 1);
        else
            cursor_position.x = lines[cursor_position.y].text.size();
        if (GetKeyState(InputKey::Shift))
            selection_length_val = ToOffset(cursor_position) - ToOffset(selection_start_pos);
        else
            ClearSelection();
        Update();
    }
    else if (key == InputKey::X && GetKeyState(InputKey::Ctrl))
    {
        std::string str = GetSelection();
        DeleteSelectedText();
        SetClipboardText(str);
    }
    else if (key == InputKey::V && GetKeyState(InputKey::Ctrl))
    {
        std::string str = GetClipboardText();
        std::string::const_iterator end_str = std::remove(str.begin(), str.end(), '\r');
        str.resize(end_str - str.begin());
        DeleteSelectedText();
        if (input_mask_pattern.empty())
        {
            InsertText(cursor_position, str);
            SetCursorPos(GetCursorPos() + str.length());
        }
        else
        {
            if (InputMaskAcceptsInput(cursor_position, str))
            {
                InsertText(cursor_position, str);
                SetCursorPos(GetCursorPos() + str.length());
            }
        }
        MoveVerticalScroll();
    }
    else if (GetKeyState(InputKey::Ctrl) && key == InputKey::Z)
    {
        if (!read_only)
        {
            std::string tmp = undo_info.undo_text;
            undo_info.undo_text = GetText();
            SetText(tmp);
        }
    }
    else if (key == InputKey::Shift)
    {
        if (selection_length_val == 0)
            selection_start_pos = cursor_position;
    }
    if (FuncAfterEditChanged)
        FuncAfterEditChanged();
}

