}

void TextEdit::OnSetFocus()
{
    if (!read_only)
        blink_timer->Start(500);
    if (select_all_on_focus_gain)
        SelectAll();
    ignore_mouse_events = true;
    cursor_position.y = lines.size() - 1;
    cursor_position.x = lines[cursor_position.y].text.length();
    Update();
    if (FuncFocusGained)
        FuncFocusGained();
}

void TextEdit::OnLostFocus()
{
    blink_timer->Stop();
    ClearSelection();
    Update();
    if (FuncFocusLost)
        FuncFocusLost();
}

void TextEdit::InitializeComponents()
{
    vert_scrollbar = new Scrollbar(this);
    vert_scrollbar->FuncScroll = [this]() { OnVerticalScroll(); };
    vert_scrollbar->SetVisible(false);
    vert_scrollbar->SetVertical();
}

void TextEdit::OnVerticalScroll()
{
}

void TextEdit::UpdateVerticalScroll()
{
    Rect rect(
        GetWidth() - vert_scrollbar->GetPreferredWidth(),
        0.0,
        vert_scrollbar->GetPreferredWidth(),
        GetHeight());
    vert_scrollbar->SetFrameGeometry(rect);
    double total_height = GetTotalLineHeight();
    double height_per_line = std::max(1.0, total_height / std::max(1.0, (double)lines.size()));
    bool visible = total_height > GetHeight();
    vert_scrollbar->SetRanges((int)std::round(GetHeight() / height_per_line), (int)std::round(total_height / height_per_line));
    vert_scrollbar->SetLineStep(1);
    vert_scrollbar->SetVisible(visible);
    if (visible == false)
        vert_scrollbar->SetPosition(0);
}

void TextEdit::MoveVerticalScroll()
{
    double total_height = GetTotalLineHeight();
    double height_per_line = std::max(1.0, total_height / std::max((size_t)1, lines.size()));
    int lines_fit = (int)(GetHeight() / height_per_line);
    if (cursor_position.y >= vert_scrollbar->GetPosition() + lines_fit)
    {
        vert_scrollbar->SetPosition(cursor_position.y - lines_fit + 1);
    }
    else if (cursor_position.y < vert_scrollbar->GetPosition())
    {
        vert_scrollbar->SetPosition(cursor_position.y);
    }
}

double TextEdit::GetTotalLineHeight()
{
    double total = 0;
    for (std::vector<Line>::const_iterator iter = lines.begin(); iter != lines.end(); iter++)
    {
        total += iter->layout.GetSize().height;
    }
    return total;
}

void TextEdit::Move(int steps, bool shift, bool ctrl)
{
    if (shift && selection_length_val == 0)
        selection_start_pos = cursor_position;
    if (ctrl)
    {
        if (steps < 0 && cursor_position.x == 0 && cursor_position.y > 0)
        {
            cursor_position.x = (int)lines[cursor_position.y - 1].text.size();
            cursor_position.y--;
        }
        else if (steps > 0 && cursor_position.x == (int)lines[cursor_position.y].text.size() && cursor_position.y + 1 < (int)lines.size())
        {
            cursor_position.x = 0;
            cursor_position.y++;
        }
        ivec2 new_pos;
        if (steps < 0)
            new_pos = FindPreviousBreakCharacter(cursor_position);
        else
            new_pos = FindNextBreakCharacter(cursor_position);
        cursor_position = new_pos;
    }
    else if (steps < 0 && cursor_position.x == 0 && cursor_position.y > 0)
    {
        cursor_position.x = (int)lines[cursor_position.y - 1].text.size();
        cursor_position.y--;
    }
    else if (steps > 0 && cursor_position.x == (int)lines[cursor_position.y].text.size() && cursor_position.y + 1 < (int)lines.size())
    {
        cursor_position.x = 0;
        cursor_position.y++;
    }
    else
    {
        UTF8Reader utf8_reader(lines[cursor_position.y].text.data(), lines[cursor_position.y].text.length());
        utf8_reader.set_position(cursor_position.x);
        if (steps > 0)
        {
            for (int i = 0; i < steps; i++)
                utf8_reader.next();
        }
        else if (steps < 0)
        {
            for (int i = 0; i < -steps; i++)
                utf8_reader.prev();
        }
        cursor_position.x = (int)utf8_reader.position();
    }
    if (shift)
    {
        selection_length_val = (int)ToOffset(cursor_position) - (int)ToOffset(selection_start_pos);
    }
    else
    {
        selection_start_pos = ivec2(0, 0);
        selection_length_val = 0;
    }
    MoveVerticalScroll();
    Update();
    undo_info.first_text_insert = true;
}

std::string TextEdit::break_characters = " ::;,.-";
TextEdit::ivec2 TextEdit::FindNextBreakCharacter(ivec2 search_start)
{
    search_start.x++;
    if (search_start.x >= int(lines[search_start.y].text.size()) - 1)
        return ivec2(lines[search_start.y].text.size(), search_start.y);
    size_t pos = lines[search_start.y].text.find_first_of(break_characters, search_start.x);
    if (pos == std::string::npos)
        return ivec2(lines[search_start.y].text.size(), search_start.y);
    return ivec2((int)pos, search_start.y);
}

TextEdit::ivec2 TextEdit::FindPreviousBreakCharacter(ivec2 search_start)
{
    search_start.x--;
    if (search_start.x <= 0)
        return ivec2(0, search_start.y);
    size_t pos = lines[search_start.y].text.find_last_of(break_characters, search_start.x);
    if (pos == std::string::npos)
        return ivec2(0, search_start.y);
    return ivec2((int)pos, search_start.y);
}

void TextEdit::InsertText(ivec2 pos, const std::string& str)
{
    undo_info.first_erase = false;
    if (undo_info.first_text_insert)
    {
        undo_info.undo_text = GetText();
        undo_info.first_text_insert = false;
    }
    if (ToOffset(ivec2((int)lines[lines.size() - 1].text.size(), (int)lines.size() - 1)) + str.length() > (size_t)max_len)
    {
        return;
    }
    std::string::size_type start = 0;
    while (true)
    {
        std::string::size_type next_newline = str.find('\n', start);
        lines[pos.y].text.insert(pos.x, str.substr(start, next_newline - start));
        lines[pos.y].invalidated = true;
        if (next_newline == std::string::npos)
            break;
        pos.x += next_newline - start;
        Line line{this};
        line.text = lines[pos.y].text.substr(pos.x);
        lines.insert(lines.begin() + pos.y + 1, line);
        lines[pos.y].text = lines[pos.y].text.substr(0, pos.x);
        lines[pos.y].invalidated = true;
        pos = ivec2(0, pos.y + 1);
        start = next_newline + 1;
    }
    MoveVerticalScroll();
    Update();
}

void TextEdit::Backspace()
{
    if (undo_info.first_erase)
    {
        undo_info.first_erase = false;
        undo_info.undo_text = GetText();
    }
    if (GetSelectionLength() != 0)
    {
        DeleteSelectedText();
        ClearSelection();
        Update();
    }
    else
    {
        if (cursor_position.x > 0)
        {
            UTF8Reader utf8_reader(lines[cursor_position.y].text.data(), lines[cursor_position.y].text.length());
            utf8_reader.set_position(cursor_position.x);
            utf8_reader.prev();
            int length = utf8_reader.char_length();
            lines[cursor_position.y].text.erase(cursor_position.x - length, length);
            lines[cursor_position.y].invalidated = true;
            cursor_position.x -= length;
            Update();
        }
        else if (cursor_position.y > 0)
        {
            selection_start_pos = ivec2(lines[cursor_position.y - 1].text.length(), cursor_position.y - 1);
            selection_length_val = 1;
            DeleteSelectedText();
        }
    }
    MoveVerticalScroll();
}

void TextEdit::Del()
{
    if (undo_info.first_erase)
    {
        undo_info.first_erase = false;
        undo_info.undo_text = GetText();
    }
    if (GetSelectionLength() != 0)
    {
        DeleteSelectedText();
        ClearSelection();
        Update();
    }
    else
    {
        if (cursor_position.x < (int)lines[cursor_position.y].text.size())
        {
            UTF8Reader utf8_reader(lines[cursor_position.y].text.data(), lines[cursor_position.y].text.length());
            utf8_reader.set_position(cursor_position.x);
            int length = utf8_reader.char_length();
            lines[cursor_position.y].text.erase(cursor_position.x, length);
            lines[cursor_position.y].invalidated = true;
            Update();
        }
        else if (cursor_position.y + 1 < (int)lines.size())
        {
            selection_start_pos = ivec2((int)lines[cursor_position.y].text.length(), cursor_position.y);
            selection_length_val = 1;
            DeleteSelectedText();
        }
    }
    MoveVerticalScroll();
}

void TextEdit::OnBlinkTimeout()
{
    if (IsVisible() == false)
    {
        blink_timer->Stop();
        return;
    }
    if (cursor_blink_visible)
        blink_timer->Start(500);
    else
        blink_timer->Start(500);
    cursor_blink_visible = !cursor_blink_visible;
    Update();
}

void TextEdit::OnGeometryChanged()
{
    Canvas* canvas = GetCanvas();
    for (auto& line : lines)
    {
        line.invalidated = true;
    }
    vertical_text_align = canvas->verticalTextAlign();
    clip_start_offset = 0;
    UpdateVerticalScroll();
}

void TextEdit::OnScrollBlinkTimeout()
{
    if (mouse_moves_left)
        Move(-1, false, false);
    else
        Move(1, false, false);
}

void TextEdit::OnEnableChanged()
{
    bool enabled = IsEnabled();
    if (!enabled)
    {
        cursor_blink_visible = false;
        blink_timer->Stop();
    }
    Update();
}

bool TextEdit::InputMaskAcceptsInput(ivec2 cursor_pos, const std::string& str)
{
    return str.find_first_not_of(input_mask_pattern) == std::string::npos;
}

std::string::size_type TextEdit::ToOffset(ivec2 pos) const
{
    if (pos.y < (int)lines.size())
    {
        std::string::size_type offset = 0;
        for (int line = 0; line < pos.y; line++)
        {
            offset += lines[line].text.size() + 1;
        }
        return offset + std::min((size_t)pos.x, lines[pos.y].text.size());
    }
    else
    {
        std::string::size_type offset = 0;
        for (size_t line = 0; line < lines.size(); line++)
        {
            offset += lines[line].text.size() + 1;
        }
        return offset - 1;
    }
}

TextEdit::ivec2 TextEdit::FromOffset(std::string::size_type offset) const
{
    int line_offset = 0;
    for (int line = 0; line < (int)lines.size(); line++)
    {
        if (offset <= line_offset + lines[line].text.size())
        {
            return ivec2(offset - line_offset, line);
        }
        line_offset += lines[line].text.size() + 1;
    }
    return ivec2(lines.back().text.size(), lines.size() - 1);
}

double TextEdit::GetTotalHeight()
{
    Canvas* canvas = GetCanvas();
    LayoutLines(canvas);
    if (!lines.empty())
    {
        return lines.back().box.bottom();
    }
    else
    {
        return GetHeight();
    }
}

void TextEdit::LayoutLines(Canvas* canvas)
{
    ivec2 sel_start;
    ivec2 sel_end;
    if (selection_length_val > 0)
    {
        sel_start = selection_start_pos;
        sel_end = FromOffset(ToOffset(selection_start_pos) + selection_length_val);
    }
    else if (selection_length_val < 0)
    {
        sel_start = FromOffset(ToOffset(selection_start_pos) + selection_length_val);
        sel_end = selection_start_pos;
    }
    Colorf textColor = GetStyleColor("color");
    Point draw_pos;
    for (size_t i = (size_t)vert_scrollbar->GetPosition(); i < lines.size(); i++)
    {
        Line& line = lines[i];
        if (line.invalidated)
        {
            line.layout.Clear();
            if (!line.text.empty())
                line.layout.AddText(line.text, font, textColor);
            else
                line.layout.AddText(" ", font, textColor);
            line.layout.Layout(canvas, GetWidth() - vert_scrollbar->GetPreferredWidth());
            line.box = Rect(draw_pos, line.layout.GetSize());
            line.invalidated = false;
        }
        if (sel_start != sel_end && sel_start.y <= (int)i && sel_end.y >= (int)i)
        {
            line.layout.SetSelectionRange(sel_start.y < (int)i ? 0 : sel_start.x, sel_end.y > (int)i ? line.text.size() : sel_end.x);
        }
        else
        {
            line.layout.SetSelectionRange(0, 0);
        }
        line.layout.HideCursor();
        if (HasFocus())
        {
            if (cursor_blink_visible && cursor_position.y == (int)i)
            {
                line.layout.SetCursorPos(cursor_position.x);
                line.layout.SetCursorColor(textColor);
                line.layout.ShowCursor();
            }
        }
        line.box.x = draw_pos.x;
        line.box.y = draw_pos.y;
        line.layout.SetPosition(line.box.topLeft());
        draw_pos = line.box.bottomLeft();
    }
    UpdateVerticalScroll();
}

void TextEdit::OnPaint(Canvas* canvas)
{
    LayoutLines(canvas);
    for (size_t i = (size_t)vert_scrollbar->GetPosition(); i < lines.size(); i++)
        lines[i].layout.DrawLayout(canvas);
}

TextEdit::ivec2 TextEdit::GetCharacterIndex(Point mouse_wincoords)
{
    Canvas* canvas = GetCanvas();
    for (size_t i = 0; i < lines.size(); i++)
    {
        Line& line = lines[i];
        if (line.box.top() <= mouse_wincoords.y && line.box.bottom() > mouse_wincoords.y)
        {
            SpanLayout::HitTestResult result = line.layout.HitTest(canvas, mouse_wincoords);
            switch (result.type)
            {
            case SpanLayout::HitTestResult::inside:
                return ivec2(clamp(result.offset, (size_t)0, line.text.size()), i);
            case SpanLayout::HitTestResult::outside_left:
                return ivec2(0, i);
            default:
            case SpanLayout::HitTestResult::outside_right:
                return ivec2(line.text.size(), i);
            }
        }
    }
    return ivec2(lines.back().text.size(), lines.size() - 1);
}

#include "WALRUS.hh"
#include <fstream>
#include <algorithm>

/*! @file
 * @brief implements the try and check of a time step
*/

// Modified version: renamed variables, adjusted expressions, reordered logic
double WALRUS::fGS_dG(double dG) {
  double temp = std::max(cD - dG, _hS);
  return (cD - _dG - _hS) * temp / cG;
}

void WALRUS::calctryvalues(double tend) {
  // Compute cumulative values over the interval [_time, tend]
  double cumRain = get_cum(fc_P, _time, tend);
  double cumETpot = get_cum(fc_ETpot, _time, tend);

  P_try = cumRain;
  ETpot_try = cumETpot;
  fXG_try = get_cum(fc_XG, _time, tend);
  fXS_try = get_cum(fc_XS, _time, tend);
  fXSact_try = fXS_try;

  _W = W_dV(_dV);
  _dVeq = dVeq_dG(_dG);

  PQ_try = cumRain * _W * aG;
  PV_try = cumRain * (1.0 - _W) * aG;
  PS_try = cumRain * aS;
  ETV_try = cumETpot * beta_dV(_dV) * aG;

  if (_hS > hSzeroforET) {
    ETS_try = cumETpot * aS;
  } else {
    ETS_try = 0.0;
  }

  double dt_hrs = (tend - _time) / 3600.0; // Convert to hours

  ETact_try = ETV_try + ETS_try;
  fQS_try = _hQ / cQ * dt_hrs;
  fGS_try = fGS_dG(_dG) * dt_hrs;
  Q_try = Q_hS(_hS) * dt_hrs;

  // Update trial state variables
  dV_try = _dV + (-fXG_try - PV_try + ETV_try + fGS_try) / aG;
  hQ_try = _hQ + (PQ_try - fQS_try) / aG;

  // Stability update for hQ (March2018, May2021)
  if (hQ_try < min_h) {
    fQS_try = fQS_try + (hQ_try - min_h) * aG;
    hQ_try = min_h;
  }

  hS_try = _hS + (fXSact_try + PS_try - ETS_try + fGS_try + fQS_try - Q_try) / aS;

  // Stability update for hS (March2018)
  if (hS_try < 0.0 && fXSact_try < 0.0) {
    fXSact_try = fXSact_try - hS_try * aS;
    hS_try = 0.0;
  }

  dG_try = _dG + (_dV - _dVeq) / cV * dt_hrs;

  // Handle large-scale ponding and flooding scenarios
  if ((dV_try < 0.0) || (hS_try > cD)) {
    if ((dV_try < 0.0) && (hS_try <= cD)) {
      // Ponding without flooding
      hS_try = hS_try - dV_try * aG / aS;
      dV_try = 0.0;
      if (hS_try > cD) {
        // Transition to flooding without ponding
        dV_try = dV_try + (-hS_try + cD) * aS / aG;
        hS_try = cD;
      }
    }
    else if ((dV_try >= 0.0) && (hS_try > cD)) {
      // Flooding without ponding
      dV_try = dV_try + (-hS_try + cD) * aS / aG;
      hS_try = cD;
    }
    else if ((dV_try < 0.0) && (hS_try > cD)) {
      // Both ponding and flooding
      dV_try = dV_try - (hS_try - cD) * aS / aG;
      hS_try = cD;
    }

    if (dV_try < 0.0) {
      dG_try = dV_try;
    }
  }
}

double WALRUS::pred_time_tries_OK(double tend) {
  if (tend < _time + min_deltime) {
    return tend;
  }

  double tc = tend;

  // Check for minimum hS threshold crossing
  if (hS_try < min_h) {
    double ratio = (_hS - min_h) / (_hS - hS_try);
    double thS = ratio * tend + (1.0 - ratio) * _time;
    if (thS < tc) tc = thS;
    hS_try = min_h;
  }

  // Check for minimum hQ threshold crossing
  if (hQ_try < min_h) {
    double ratio = (_hQ - min_h) / (_hQ - hQ_try);
    double thQ = ratio * tend + (1.0 - ratio) * _time;
    if (thQ < tc) tc = thQ;
    hQ_try = min_h;
  }

  // Step size constraints on fluxes
  double rain_step = get_cum(fc_P, _time, tend);
  if (rain_step > max_Pstep) {
    double ratio = max_Pstep / rain_step;
    double tRain = ratio * tend + (1.0 - ratio) * _time;
    if (tRain < tc) tc = tRain;
  }

  double etpot_step = get_cum(fc_ETpot, _time, tend);
  if (etpot_step > max_Pstep) {
    double ratio = max_Pstep / etpot_step;
    double tETpot = ratio * tend + (1.0 - ratio) * _time;
    if (tETpot < tc) tc = tETpot;
  }

  double fXG_step = get_cum(fc_XG, _time, tend);
  if (fXG_step > max_Pstep) {
    double ratio = max_Pstep / fXG_step;
    double tfXG = ratio * tend + (1.0 - ratio) * _time;
    if (tfXG < tc) tc = tfXG;
  }

  double fXS_step = get_cum(fc_XS, _time, tend);
  if (fXS_step > max_Pstep) {
    double ratio = max_Pstep / fXS_step;
    double tfXS = ratio * tend + (1.0 - ratio) * _time;
    if (tfXS < tc) tc = tfXS;
  }

  // State change constraints
  double abs_hS_change = std::fabs(hS_try - _hS);
  if (abs_hS_change > max_h_change) {
    double ratio = max_h_change / abs_hS_change;
    double thS_change = ratio * tend + (1.0 - ratio) * _time;
    if (thS_change < tc) tc = thS_change;
  }

  double abs_hQ_change = std::fabs(hQ_try - _hQ);
  if (abs_hQ_change > max_h_change) {
    double ratio = max_h_change / abs_hQ_change;
    double thQ_change = ratio * tend + (1.0 - ratio) * _time;
    if (thQ_change < tc) tc = thQ_change;
  }

  double abs_dG_change = std::fabs(dG_try - _dG);
  if (abs_dG_change > max_h_change) {
    double ratio = max_h_change / abs_dG_change;
    double tdG_change = ratio * tend + (1.0 - ratio) * _time;
    if (tdG_change < tc) tc = tdG_change;
  }

  // Final bounds enforcement
  if (tc <= _time) {
    tc = _time + min_deltime;
  }
  if (tc > tend) {
    tc = tend;
  }

  return tc;
}

