	track_property_provider_v5_info_source_wrap(track_property_provider_v3_info_source& chain, trackListRef list) 
		: m_chain(chain), m_list(list) {}

	track_property_provider_v3_info_source & m_chain;
	trackListRef m_list;

	metadb_v2_rec_t get_info(size_t index) override {
