class track_property_provider_v3_info_source_wrap_v5 : public track_property_provider_v3_info_source {
public:
	track_property_provider_v5_info_source* m_next;
	trackInfoContainer::ptr fetch_entry(size_t index) override {
		auto result = m_next->get_info(index).info;
		if (result.is_empty()) {
			result = m_default;
		}
