metadb_v2_rec_t track_property_provider_v5_info_source_impl::get_info(size_t index) {
#if FOOBAR2000_TARGET_VERSION >= 81
	return m_entries[index];
#else
	if (index < m_entries.get_size()) return m_entries[index];
	else if (index < m_tracks.get_size()) return m_tracks[index]->query_v2_();
	else uBugCheck();
#endif
}

track_property_provider_v5_info_source_impl::track_property_provider_v5_info_source_impl(trackListRef list, abort_callback & aborter) {
#if FOOBAR2000_TARGET_VERSION >= 81
	m_entries.resize(list.get_count()); 
	metadb_v2::get()->queryMultiParallel_(list, [this, &aborter](size_t idx, metadb_v2_rec_t const& rec) { 
		aborter.check(); 
		this->m_entries[idx] = rec; 
	});
#else
	auto api = metadb_v2::tryGet();
	if (api.is_valid()) {
		m_entries.resize(list.get_count());
		api->queryMultiParallel_(list, [this](size_t idx, metadb_v2_rec_t const& rec) { 
			this->m_entries[idx] = rec; 
		});
		return;
	}
	m_tracks = list;
#endif
}

void track_property_provider::enumerate_properties_helper(trackListRef items, track_property_provider_v5_info_source* info, track_property_callback_v2& callback, abort_callback& aborter) {
	if (info == nullptr) {
		this->enumerate_properties_helper(items, nullptr, callback, aborter);
	} else {
		{
			track_property_provider_v5::ptr v5;
			if (v5 &= this) {
				v5->enumerate_properties_v5(items, *info, callback, aborter);
				return;
			}
		}
		track_property_provider_v3_info_source_wrap_v5 wrapper;
		wrapper.m_next = info;
		this->enumerate_properties_helper(items, &wrapper, callback, aborter);
	}
}

void track_property_provider::enumerate_properties_helper(trackListRef items, std::nullptr_t, track_property_callback_v2& callback, abort_callback& aborter) {
	track_property_provider_v5::ptr v5;
	if (v5 &= this) {
		track_property_provider_v5_info_source_impl impl(items, aborter);
		v5->enumerate_properties_v5(items, impl, callback, aborter);
		return;
	}
	track_property_provider_v3_info_source* placeholder = nullptr;
	this->enumerate_properties_helper(items, placeholder, callback, aborter);
}

void track_property_provider::enumerate_properties_helper(trackListRef items, track_property_provider_v3_info_source * info, track_property_callback_v2 & callback, abort_callback & aborter) {
	aborter.check();
	track_property_provider_v2::ptr v2;
	if (!this->cast(v2)) {
		PFC_ASSERT(core_api::is_main_thread());
		this->enumerate_properties(items, callback);
		return;
	}
	track_property_provider_v3::ptr v3;
	if (!(v3 &= v2)) {
		PFC_ASSERT(core_api::is_main_thread());
		v2->enumerate_properties_v2(items, callback);
		return;
	}
	track_property_provider_v3_info_source_impl fallback(items);
	if (info == nullptr) info = &fallback;
	track_property_provider_v4::ptr v4;
	if (!(v4 &= v3)) {
		PFC_ASSERT(core_api::is_main_thread());
		v3->enumerate_properties_v3(items, *info, callback);
	} else {
		v4->enumerate_properties_v4(items, *info, callback, aborter);
	}
}

