// Determine ordering: higher depth first, or if equal, larger index first
bool compareLayerPriority(const QPair<int, double>& layer1,
                          const QPair<int, double>& layer2) {
  // If depths are equal, prioritize the one with smaller index (placed above)
  if (layer1.second == layer2.second) return layer1.first > layer2.first;
  return layer1.second > layer2.second;
}

template <typename T>
TRasterGR8P createRasterAndAcquire(T** buffer, TDimensionI size) {
  TRasterGR8P raster(size.lx * sizeof(T), size.ly);
  raster->acquire();
  *buffer = static_cast<T*>(raster->getRawData());
  return raster;
}

// Unlock all rasters and free FFT plans
void cleanupRastersAndPlans(QList<TRasterGR8P>& rasterList,
                            QList<kiss_fftnd_cfg>& planList) {
  for (int idx = 0; idx < rasterList.size(); ++idx) rasterList[idx]->release();
  for (int pIdx = 0; pIdx < planList.size(); ++pIdx) kiss_fft_free(planList[pIdx]);
}
}  // namespace

//--------------------------------------------
// Retrieve sorted indices of sources based on depth
QList<int> Iwa_BokehAdvancedFx::getSortedSourceIndices(double frame) {
  QList<QPair<int, double>> activeSources;

  // Collect connected sources with their depth values
  for (int i = 0; i < LAYER_NUM; ++i) {
    if (m_layerParams[i].m_source.isConnected()) {
      activeSources.append(
          QPair<int, double>(i, m_layerParams[i].m_distance->getValue(frame)));
    }
  }

  if (activeSources.isEmpty()) return QList<int>();

  // Sort by depth using priority comparison
  std::sort(activeSources.begin(), activeSources.end(), compareLayerPriority);

  QList<int> orderedIndices;
  for (int i = 0; i < activeSources.size(); ++i) {
    orderedIndices << activeSources[i].first;
  }
  return orderedIndices;
}

//--------------------------------------------
// Calculate bokeh size per layer and determine maximum size needed
QMap<int, double> Iwa_BokehAdvancedFx::getIrisSizes(
    const double frame, const QList<int>& sourceOrder,
    const double bokehScale, double& maxBlurAmount) {
  // Identify available depth control ports
  QList<int> usableDepthPorts;
  for (int i = 0; i < getInputPortCount(); ++i) {
    QString portName = QString::fromStdString(getInputPortName(i));
    if (portName.startsWith("Depth") && getInputPort(i)->isConnected()) {
      usableDepthPorts << portName.remove(0, 5).toInt();
    }
  }

  double focalPoint = m_onFocusDistance->getValue(frame);
  double largestSize = 0.0;
  QMap<int, double> blurMap;

  for (int s = 0; s < sourceOrder.size(); ++s) {
    int layerIndex = sourceOrder[s];
    double layerDepth = m_layerParams[layerIndex].m_distance->getValue(frame);
    double adjustment = m_layerParams[layerIndex].m_bokehAdjustment->getValue(frame);
    double blurSize;

    // Use reference image if available
    if (m_layerParams[layerIndex].m_depth_ref->getValue() != 0 &&
        usableDepthPorts.contains(m_layerParams[layerIndex].m_depth_ref->getValue())) {
      double halfRange = m_layerParams[layerIndex].m_depthRange->getValue(frame) * 0.5;
      double nearOffset = focalPoint - layerDepth + halfRange;
      double farOffset = focalPoint - layerDepth - halfRange;
      blurSize = (std::abs(nearOffset) > std::abs(farOffset)) ? nearOffset : farOffset;
      blurSize *= bokehScale * adjustment;
    } else {
      // Default calculation without reference
      blurSize = (focalPoint - layerDepth) * bokehScale * adjustment;
    }

    blurMap[layerIndex] = blurSize;
    if (largestSize < std::abs(blurSize)) largestSize = std::abs(blurSize);
  }

  maxBlurAmount = largestSize;
  return blurMap;
}

//-----------------------------------------------------
// Check whether a specific depth control port is in use
bool Iwa_BokehAdvancedFx::portIsUsed(int portIndex) {
  for (int layer = 0; layer < LAYER_NUM; ++layer) {
    if (m_layerParams[layer].m_source.isConnected() &&
        m_layerParams[layer].m_depth_ref->getValue() == portIndex)
      return true;
  }
  return false;
}

//--------------------------------------------
Iwa_BokehAdvancedFx::Iwa_BokehAdvancedFx()
    : m_hardnessPerSource(false), m_control("Depth") {
  // Bind common parameters
  bindParam(this, "on_focus_distance", m_onFocusDistance, false);
  bindParam(this, "bokeh_amount", m_bokehAmount, false);
  bindParam(this, "masterHardness", m_hardness, false);
  bindParam(this, "masterGamma", m_gamma, false);
  bindParam(this, "masterGammaAdjust", m_gammaAdjust, false);
  bindParam(this, "hardnessPerSource", m_hardnessPerSource, false);
  bindParam(this, "linearizeMode", m_linearizeMode, false);

  // Initialize layer parameters
  for (int layer = 0; layer < LAYER_NUM; ++layer) {
    m_layerParams[layer].m_distance        = TDoubleParamP(0.5);
    m_layerParams[layer].m_bokehAdjustment = TDoubleParamP(1);
    m_layerParams[layer].m_hardness        = TDoubleParamP(0.3);
    m_layerParams[layer].m_gamma           = TDoubleParamP(2.2);
    m_layerParams[layer].m_gammaAdjust     = TDoubleParamP(0.);
    m_layerParams[layer].m_depth_ref       = TIntParamP(0);
    m_layerParams[layer].m_depthRange      = TDoubleParamP(1.0);
    m_layerParams[layer].m_fillGap         = TBoolParamP(true);
    m_layerParams[layer].m_doMedian        = TBoolParamP(false);

    std::string name = QString("Source%1").arg(layer + 1).toStdString();
    addInputPort(name, m_layerParams[layer].m_source);

    bindParam(this, QString("distance%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_distance);
    bindParam(this, QString("bokeh_adjustment%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_bokehAdjustment);
    bindParam(this, QString("gamma%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_gamma);
    bindParam(this, QString("gammaAdjust%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_gammaAdjust);
    bindParam(this, QString("hardness%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_hardness);
    bindParam(this, QString("depth_ref%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_depth_ref);
    bindParam(this, QString("depthRange%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_depthRange);
    bindParam(this, QString("fillGap%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_fillGap);
    bindParam(this, QString("doMedian%1").arg(layer + 1).toStdString(),
              m_layerParams[layer].m_doMedian);

    // Set value ranges
    m_layerParams[layer].m_distance->setValueRange(0.0, 1.0);
    m_layerParams[layer].m_bokehAdjustment->setValueRange(0.0, 2.0);
    m_layerParams[layer].m_hardness->setValueRange(0.05, 3.0);
    m_layerParams[layer].m_gamma->setValueRange(1.0, 10.0);
    m_layerParams[layer].m_gammaAdjust->setValueRange(-5., 5.);
    m_layerParams[layer].m_depthRange->setValueRange(0.0, 1.0);
  }

  addInputPort("Depth1", new TRasterFxPort, 0);
  enableComputeInFloat(true);

  setFxVersion(3);  // Version 3 uses gamma from color space + adjust
}

//--------------------------------------------
void Iwa_BokehAdvancedFx::onFxVersionSet() {
  bool usingGamma = getFxVersion() == 2;
  if (getFxVersion() == 1) {
    m_linearizeMode->setValue(Hardness);
    setFxVersion(3);
  } else if (getFxVersion() == 2) {
    if (m_linearizeMode->getValue() == Hardness) {
      usingGamma = false;
      setFxVersion(3);
    }
  }

  getParams()->getParamVar("masterGamma")->setIsHidden(!usingGamma);
  getParams()->getParamVar("masterGammaAdjust")->setIsHidden(usingGamma);

  for (int layer = 0; layer < LAYER_NUM; ++layer) {
    getParams()
        ->getParamVar(QString("gamma%1").arg(layer + 1).toStdString())
        ->setIsHidden(!usingGamma);
    getParams()
        ->getParamVar(QString("gammaAdjust%1").arg(layer + 1).toStdString())
        ->setIsHidden(usingGamma);
  }
}

//--------------------------------------------
void Iwa_BokehAdvancedFx::doCompute(TTile& tile, double frame,
                                    const TRenderSettings& settings) {
  // Early exit if iris input is not connected
  if (!m_iris.isConnected()) {
    tile.getRaster()->clear();
    return;
  }

  // Check if any source is connected
  bool hasActiveSource = false;
  for (int i = 0; i < LAYER_NUM; ++i) {
    if (m_layerParams[i].m_source.isConnected()) {
      hasActiveSource = true;
      break;
    }
  }
  if (!hasActiveSource) {
    tile.getRaster()->clear();
    return;
  }

  // Sort layers by depth
  QList<int> layerOrder = getSortedSourceIndices(frame);

  // Compute bokeh scale factor
  double bokehScale = BokehUtils::getBokehPixelAmount(
      m_bokehAmount->getValue(frame), settings.m_affine);

  // Determine required margin and dimensions
  double maxBlur;
  QMap<int, double> blurMap =
      getIrisSizes(frame, layerOrder, bokehScale, maxBlur);
  int padding = static_cast<int>(std::ceil(maxBlur * 0.5));

  TRectD outputRect(tile.m_pos, TDimensionD(tile.getRaster()->getLx(),
                                            tile.getRaster()->getLy()));
  outputRect = outputRect.enlarge(static_cast<double>(padding));
  TDimensionI finalSize(static_cast<int>(outputRect.getLx() + 0.5),
                        static_cast<int>(outputRect.getLy() + 0.5));

  // Optimize dimensions for kissFFT
  if (finalSize.lx < 10000 && finalSize.ly < 10000) {
    int optimizedX = kiss_fft_next_fast_size(finalSize.lx);
    int optimizedY = kiss_fft_next_fast_size(finalSize.ly);

    while ((optimizedX - finalSize.lx) % 2 != 0)
      optimizedX = kiss_fft_next_fast_size(optimizedX + 1);
    while ((optimizedY - finalSize.ly) % 2 != 0)
      optimizedY = kiss_fft_next_fast_size(optimizedY + 1);

    outputRect = outputRect.enlarge(static_cast<double>(optimizedX - finalSize.lx) / 2.0,
                                    static_cast<double>(optimizedY - finalSize.ly) / 2.0);
    finalSize.lx = optimizedX;
    finalSize.ly = optimizedY;
  }

  // Compute source tiles
  QMap<int, TTile*> sourceTiles;
  for (auto idx : layerOrder) {
    TTile* layerTile = new TTile();
    m_layerParams[idx].m_source->allocateAndCompute(
        *layerTile, outputRect.getP00(), finalSize, tile.getRaster(), frame,
        settings);
    sourceTiles[idx] = layerTile;
  }

  // Get iris bounding box and compute tile
  TRectD irisBBox;
  m_iris->getBBox(frame, irisBBox, settings);
  TTile irisTile;
  m_iris->allocateAndCompute(
      irisTile, irisBBox.getP00(),
      TDimension(static_cast<int>(irisBBox.getLx() + 0.5),
                 static_cast<int>(irisBBox.getLy() + 0.5)),
      tile.getRaster(), frame, settings);

  // Prepare depth control images
  std::vector<TRasterGR8P> depthRasters;
  QMap<int, unsigned char*> depthBuffers;
  for (int i = 0; i < getInputPortCount(); ++i) {
    QString portName = QString::fromStdString(getInputPortName(i));
    if (portName.startsWith("Depth") && getInputPort(i)->isConnected()) {
      int portIndex = portName.remove(0, 5).toInt();
      if (portIsUsed(portIndex)) {
        TTile tempTile;
        TRasterFxPort* depthPort = dynamic_cast<TRasterFxPort*>(getInputPort(i));
        (*depthPort)->allocateAndCompute(tempTile, outputRect.getP00(), finalSize,
                                         tile.getRaster(), frame, settings);

        TRasterGR8P depthRaster(finalSize.lx, finalSize.ly);
        depthRaster->acquire();
        unsigned char* depthMem = static_cast<unsigned char*>(depthRaster->getRawData());

        TRaster32P ras32 = TRaster32P(tempTile.getRaster());
        TRaster64P ras64 = TRaster64P(tempTile.getRaster());
        TRasterFP rasF   = TRasterFP(tempTile.getRaster());

        dataLock.lockForRead();
        if (ras32)
          BokehUtils::setDepthRaster<TRaster32P, TPixel32>(ras32, depthMem, finalSize);
        else if (ras64)
          BokehUtils::setDepthRaster<TRaster64P, TPixel64>(ras64, depthMem, finalSize);
        else if (rasF)
          BokehUtils::setDepthRaster<TRasterFP, TPixelF>(rasF, depthMem, finalSize);
        dataLock.unlock();

        depthRasters.push_back(depthRaster);
        depthBuffers[portIndex] = depthMem;
      }
    }
  }

  // Determine effective gamma/hardness
  double effectiveGamma;
  if (m_linearizeMode->getValue() == Hardness)
    effectiveGamma = m_hardness->getValue(frame);
  else {
    if (getFxVersion() == 2)
      effectiveGamma = m_gamma->getValue(frame);
    else
      effectiveGamma = std::max(1., settings.m_colorSpaceGamma +
                                     m_gammaAdjust->getValue(frame));
    if (tile.getRaster()->isLinear())
      effectiveGamma /= settings.m_colorSpaceGamma;
  }

  // Build layer configuration list
  QList<LayerValue> layerConfigs;
  for (auto idx : layerOrder) {
    LayerValue config;
    config.sourceTile = sourceTiles[idx];
    config.premultiply = false;

    if (m_hardnessPerSource->getValue()) {
      if (m_linearizeMode->getValue() == Hardness)
        config.layerGamma = m_layerParams[idx].m_hardness->getValue(frame);
      else {
        if (getFxVersion() == 2)
          config.layerGamma = m_layerParams[idx].m_gamma->getValue(frame);
        else
          config.layerGamma = std::max(1., settings.m_colorSpaceGamma +
                                          m_layerParams[idx].m_gammaAdjust->getValue(frame));
        if (tile.getRaster()->isLinear())
          config.layerGamma /= settings.m_colorSpaceGamma;
      }
    } else {
      config.layerGamma = effectiveGamma;
    }

    config.depth_ref = m_layerParams[idx].m_depth_ref->getValue();
    config.irisSize = blurMap.value(idx);
    config.distance = m_layerParams[idx].m_distance->getValue(frame);
    config.bokehAdjustment = m_layerParams[idx].m_bokehAdjustment->getValue(frame);
    config.depthRange = m_layerParams[idx].m_depthRange->getValue(frame);
    config.distancePrecision = 10;
    config.fillGap = m_layerParams[idx].m_fillGap->getValue();
    config.doMedian = m_layerParams[idx].m_doMedian->getValue();

    layerConfigs.append(config);
  }

  // Perform main bokeh computation
  Iwa_BokehCommonFx::doFx(tile, frame, settings, bokehScale, padding,
                          finalSize, irisBBox, irisTile, layerConfigs, depthBuffers);

  // Cleanup
  for (int r = 0; r < depthRasters.size(); ++r) depthRasters[r]->release();
  qDeleteAll(sourceTiles);
}

