#ifdef __unix__
const int STACK_OVERFLOW_EXIT_CODE = SIGSEGV + 128;
const std::unordered_map<std::string, int> signalCodeMap = {
    {"SIGABRT", SIGABRT}, {"SIGFPE", SIGFPE}, {"SIGSEGV", SIGSEGV},
    {"SIGILL", SIGILL},   {"SIGTRAP", SIGTRAP}, {"SIGBUS", SIGBUS}};
#elif _WIN32
const DWORD STACK_OVERFLOW_EXIT_CODE = EXCEPTION_STACK_OVERFLOW;
const std::unordered_map<std::string, int> signalCodeMap = {
    {"SIGABRT", SIGABRT}, {"SIGFPE", SIGFPE}, {"SIGSEGV", SIGSEGV}, {"SIGILL", SIGILL}};
#endif

const std::unordered_map<std::string, int64_t> stageValueMap = {
    {"main", static_cast<int64_t>(CompileStage::COMPILE_STAGE_NUMBER)},
    {"parser", static_cast<int64_t>(CompileStage::PARSE)},
    {"sema", static_cast<int64_t>(CompileStage::SEMA)},
    {"chir", static_cast<int64_t>(CompileStage::CHIR)},
    {"codegen", static_cast<int64_t>(CompileStage::CODEGEN)},
    {"driver", static_cast<int64_t>(CompileStage::COMPILE_STAGE_NUMBER)}};

const std::string TEST_CJ_FILE = PROJECT_ROOT + "/unittests/Utils/SignalTest.cj";
const std::string ERROR_LOG_PATH = "./tempError.txt";

class SignalHandlingTests : public testing::Test {
protected:
    void SetUp() override
    {
#ifdef _WIN32
        char* currentDir = getcwd(NULL, 0);
        if (currentDir == nullptr) {
            std::cerr << "Unable to retrieve current working directory!" << std::endl;
            _exit(1);
        }
        std::string dirStr = std::string(currentDir);
        std::optional<std::wstring> wideDir = StringConvertor::StringToWString(dirStr);
        if (!wideDir.has_value()) {
            std::cerr << "Failed to configure TMP environment variable!" << std::endl;
            _exit(1);
        }
        _wputenv_s(L"TMP", wideDir.value().c_str());
#else
        const char* pwd = getenv("PWD");
        setenv("TMPDIR", pwd, 1);
#endif
        std::ofstream dummyFile(ERROR_LOG_PATH);
        dummyFile.close();
    }

    void TearDown() override
    {
        FileUtil::Remove(ERROR_LOG_PATH);
    }
};

std::string BuildSignalMessage(const std::string& sigName, const std::string& stage)
{
    auto iter = stageValueMap.find(stage);
    if (iter == stageValueMap.end()) {
        return "";
    }

    std::string prefix = Cangjie::ICE::MSG_PART_ONE + Cangjie::SIGNAL_MSG_PART_ONE;
    std::string suffix = Cangjie::SIGNAL_MSG_PART_TWO + Cangjie::ICE::MSG_PART_TWO +
                         std::to_string(iter->second) + "\n";

    if (sigName == "StackOverflow") {
#ifdef __unix__
        return CANGJIE_COMPILER_VERSION + "\n" + prefix + std::to_string(SIGSEGV) + suffix;
#elif _WIN32
        return CANGJIE_COMPILER_VERSION + "\n" + prefix + std::to_string(STACK_OVERFLOW_EXIT_CODE) + suffix;
#endif
    }

    auto found = signalCodeMap.find(sigName);
    if (found != signalCodeMap.end()) {
        return CANGJIE_COMPILER_VERSION + "\n" + prefix + std::to_string(found->second) + suffix;
    }

    return "";
}

void CheckTempFilesRemoved()
{
#ifdef _WIN32
    FILE* pipe = popen("dir", "r");
#else
    FILE* pipe = popen("ls", "r");
#endif
    std::string output;
    while (true) {
        int ch = fgetc(pipe);
        if (ch <= 0) break;
        output.push_back(static_cast<char>(ch));
    }
    pclose(pipe);

    const std::string prefix = "cangjie-tmp-";
    const char* match = strstr(output.c_str(), prefix.c_str());
    EXPECT_TRUE(match == nullptr);
}

void ValidateErrorLog(const std::string& sigName, const std::string& stage)
{
    char buffer;
    std::string content;
    std::ifstream file(ERROR_LOG_PATH);
    while (file.get(buffer)) {
        content.push_back(buffer);
    }
    file.close();

    std::string expected = BuildSignalMessage(sigName, stage);
    EXPECT_EQ(content, expected);
    CheckTempFilesRemoved();
}

#ifdef __unix__
#define MAX_BUFFER_SIZE 4096

int RunTestCase(const std::string& sigName, const std::string& stage)
{
    std::ostringstream oss;
    oss << sigName << "_" << stage << "_" << ERROR_LOG_PATH;
    std::string argLine = oss.str();

    char exePath[MAX_BUFFER_SIZE] = {0};
    if (readlink("/proc/self/exe", exePath, MAX_BUFFER_SIZE) == -1) {
        return -1;
    }

    std::string compilerPath = FileUtil::GetDirPath(std::string(exePath)) + "/SignalTestCJC";
    pid_t childPid;
    pid_t waitedPid;
    int exitStatus;

    childPid = fork();
    if (childPid == 0) {
        if (execl(compilerPath.c_str(), compilerPath.c_str(),
                  TEST_CJ_FILE.c_str(), argLine.c_str(), nullptr) == -1) {
            _exit(1);
        }
    } else if (childPid > 0) {
        waitedPid = wait(&exitStatus);
        if (waitedPid == -1) {
            return -1;
        }

        if (WIFEXITED(exitStatus)) {
            return WEXITSTATUS(exitStatus);
        } else if (WIFSIGNALED(exitStatus)) {
            WTERMSIG(exitStatus);
        }
    }

    return -1;
}

#elif _WIN32

DWORD RunTestCase(const std::string& sigName, const std::string& stage)
{
    char exePath[MAX_PATH];
    GetModuleFileName(NULL, exePath, MAX_PATH);
    std::string compilerPath = FileUtil::GetDirPath(std::string(exePath)) + "\\SignalTestCJC.exe";

    std::ostringstream oss;
    oss << compilerPath << " " << TEST_CJ_FILE << " " << sigName << "_" << stage << "_" << ERROR_LOG_PATH;
    std::string cmdLine = oss.str();

    STARTUPINFOA startupInfo{};
    PROCESS_INFORMATION processInfo{};

    startupInfo.cb = sizeof(startupInfo);
    ZeroMemory(&startupInfo, sizeof(startupInfo));
    ZeroMemory(&processInfo, sizeof(processInfo));

    if (!CreateProcessA(compilerPath.c_str(), cmdLine.data(), NULL, NULL,
                        FALSE, 0, NULL, NULL, &startupInfo, &processInfo)) {
        return 1;
    }

    WaitForSingleObject(processInfo.hProcess, INFINITE);

    DWORD exitCode;
    if (!GetExitCodeProcess(processInfo.hProcess, &exitCode)) {
        return 1;
    }

    CloseHandle(processInfo.hProcess);
    CloseHandle(processInfo.hThread);

    return exitCode;
}
#endif

#define RUN_TEST(sig, stage)                                                                                           \
    TEST_F(SignalHandlingTests, stage##Signal##sig)                                                                    \
    {                                                                                                                  \
        EXPECT_EQ(RunTestCase(#sig, #stage), sig + 128);                                                               \
        ValidateErrorLog(#sig, #stage);                                                                                \
    }

#define RUN_STACK_OVERFLOW_TEST(stage)                                                                                 \
    TEST_F(SignalHandlingTests, stage##StackOverflow)                                                                  \
    {                                                                                                                  \
        EXPECT_EQ(RunTestCase("StackOverflow", #stage), STACK_OVERFLOW_EXIT_CODE);                                     \
        ValidateErrorLog("StackOverflow", #stage);                                                                     \
    }

