#ifdef CONFIG_LATX_AVX_OPT

bool translate_vpslldq(IR1_INST * pir1) {
    IR1_OPND * op0 = ir1_get_opnd(pir1, 0);
    IR1_OPND * op1 = ir1_get_opnd(pir1, 1);
    IR1_OPND * op2 = ir1_get_opnd(pir1, 2);
    lsassert((ir1_opnd_is_xmm(op0) && ir1_opnd_is_xmm(op1)) ||
        (ir1_opnd_is_ymm(op0) && ir1_opnd_is_ymm(op1)));
    lsassert(ir1_opnd_is_imm(op2));

    IR2_OPND dst_reg = load_freg256_from_ir1(op0);
    IR2_OPND src_reg = load_freg256_from_ir1(op1);
    uint8_t shift_val = ir1_opnd_uimm(op2);

    if (shift_val > 15) {
        la_xvandi_b(dst_reg, src_reg, 0);
        return true;
    }

    la_xvbsll_v(dst_reg, src_reg, shift_val);

    if (ir1_opnd_is_xmm(op0)) {
        set_high128_xreg_to_zero(dst_reg);
    }

    return true;
}

bool translate_vpsllx(IR1_INST * pir1) {
    IR1_OPND * op0 = ir1_get_opnd(pir1, 0);
    IR1_OPND * op1 = ir1_get_opnd(pir1, 1);
    IR1_OPND * op2 = ir1_get_opnd(pir1, 2);

    lsassert((ir1_opnd_is_xmm(op0) && ir1_opnd_is_xmm(op1)) ||
        (ir1_opnd_is_ymm(op0) && ir1_opnd_is_ymm(op1)));

    IR2_OPND dst_reg = load_freg256_from_ir1(op0);
    IR2_OPND src_reg = load_freg256_from_ir1(op1);

    IR2_INST * ( * repl_func)(IR2_OPND, IR2_OPND);
    IR2_INST * ( * imm_shift_func)(IR2_OPND, IR2_OPND, int);
    IR2_INST * ( * reg_shift_func)(IR2_OPND, IR2_OPND, IR2_OPND);

    int max_shift;

    switch (ir1_opcode(pir1)) {
        case dt_X86_INS_VPSLLW:
            repl_func = la_xvreplve0_h;
            imm_shift_func = la_xvslli_h;
            reg_shift_func = la_xvsll_h;
            max_shift = 15;
            break;
        case dt_X86_INS_VPSLLD:
            repl_func = la_xvreplve0_w;
            imm_shift_func = la_xvslli_w;
            reg_shift_func = la_xvsll_w;
            max_shift = 31;
            break;
        case dt_X86_INS_VPSLLQ:
            repl_func = la_xvreplve0_d;
            imm_shift_func = la_xvslli_d;
            reg_shift_func = la_xvsll_d;
            max_shift = 63;
            break;
        default:
            repl_func = NULL;
            imm_shift_func = NULL;
            reg_shift_func = NULL;
            max_shift = 0;
            lsassert(0);
            break;
    }

    if (ir1_opnd_is_imm(op2)) {
        uint8_t imm = ir1_opnd_uimm(op2);
        if (imm > max_shift) {
            la_xvxor_v(dst_reg, dst_reg, dst_reg);
        } else {
            imm_shift_func(dst_reg, src_reg, imm);
        }
    } else {
        IR2_OPND src_cnt = load_freg256_from_ir1(op2);
        IR2_OPND mask_reg = ra_alloc_ftemp();
        IR2_OPND tmp_reg = ra_alloc_ftemp();

        if (max_shift == 63) {
            la_xvreplve0_d(mask_reg, src_cnt);
            la_xvldi(tmp_reg, VLDI_IMM_TYPE0(3, 63));
            la_xvsle_du(mask_reg, mask_reg, tmp_reg);
        } else {
            la_xvreplve0_d(mask_reg, src_cnt);
            la_xvslei_du(mask_reg, mask_reg, max_shift);
        }

        repl_func(tmp_reg, src_cnt);
        reg_shift_func(dst_reg, src_reg, tmp_reg);
        la_xvand_v(dst_reg, dst_reg, mask_reg);
    }

    if (ir1_opnd_is_xmm(op0)) {
        set_high128_xreg_to_zero(dst_reg);
    }

    return true;
}

bool translate_vpsrldq(IR1_INST * pir1) {
    IR1_OPND * op0 = ir1_get_opnd(pir1, 0);
    IR1_OPND * op1 = ir1_get_opnd(pir1, 1);
    IR1_OPND * op2 = ir1_get_opnd(pir1, 2);

    lsassert((ir1_opnd_is_xmm(op0) && ir1_opnd_is_xmm(op1)) ||
        (ir1_opnd_is_ymm(op0) && ir1_opnd_is_ymm(op1)));

    lsassert(ir1_opnd_is_imm(op2));

    IR2_OPND dst_reg = load_freg256_from_ir1(op0);
    IR2_OPND src_reg = load_freg256_from_ir1(op1);

    uint8_t shift_val = ir1_opnd_uimm(op2);

    if (shift_val > 15) {
        la_xvxor_v(dst_reg, dst_reg, dst_reg);
        return true;
    }

    la_xvbsrl_v(dst_reg, src_reg, shift_val);

    if (ir1_opnd_is_xmm(op0)) {
        set_high128_xreg_to_zero(dst_reg);
    }

    return true;
}

bool translate_vpsrlx(IR1_INST * pir1) {
    IR1_OPND * op0 = ir1_get_opnd(pir1, 0);
    IR1_OPND * op1 = ir1_get_opnd(pir1, 1);
    IR1_OPND * op2 = ir1_get_opnd(pir1, 2);

    lsassert((ir1_opnd_is_xmm(op0) && ir1_opnd_is_xmm(op1)) ||
        (ir1_opnd_is_ymm(op0) && ir1_opnd_is_ymm(op1)));

    IR2_OPND dst_reg = load_freg256_from_ir1(op0);
    IR2_OPND src_reg = load_freg256_from_ir1(op1);

    IR2_INST * ( * repl_func)(IR2_OPND, IR2_OPND);
    IR2_INST * ( * imm_shift_func)(IR2_OPND, IR2_OPND, int);
    IR2_INST * ( * reg_shift_func)(IR2_OPND, IR2_OPND, IR2_OPND);

    IR2_OPND label_done = ra_alloc_label();
    IR2_OPND label_do_shift = ra_alloc_label();

    int max_shift;

    switch (ir1_opcode(pir1)) {
        case dt_X86_INS_VPSRLW:
            repl_func = la_xvreplve0_h;
            imm_shift_func = la_xvsrli_h;
            reg_shift_func = la_xvsrl_h;
            max_shift = 15;
            break;
        case dt_X86_INS_VPSRLD:
            repl_func = la_xvreplve0_w;
            imm_shift_func = la_xvsrli_w;
            reg_shift_func = la_xvsrl_w;
            max_shift = 31;
            break;
        case dt_X86_INS_VPSRLQ:
            repl_func = la_xvreplve0_d;
            imm_shift_func = la_xvsrli_d;
            reg_shift_func = la_xvsrl_d;
            max_shift = 63;
            break;
        default:
            repl_func = NULL;
            imm_shift_func = NULL;
            reg_shift_func = NULL;
            max_shift = 0;
            lsassert(0);
            break;
    }

    if (ir1_opnd_is_imm(op2)) {
        uint8_t imm = ir1_opnd_uimm(op2);
        if (imm > max_shift) {
            la_xvxor_v(dst_reg, dst_reg, dst_reg);
        } else {
            imm_shift_func(dst_reg, src_reg, imm);
        }
    } else {
        IR2_OPND src_cnt = load_freg256_from_ir1(op2);
        IR2_OPND mask_reg = ra_alloc_ftemp();
        IR2_OPND tmp_reg = ra_alloc_ftemp();
        IR2_OPND cnt_reg = ra_alloc_itemp();
        IR2_OPND max_val = ra_alloc_itemp();

        la_addi_d(max_val, zero_ir2_opnd, max_shift);
        la_vpickve2gr_d(cnt_reg, src_cnt, 0);

        la_blt(cnt_reg, max_val, label_do_shift);

        la_xvxor_v(dst_reg, dst_reg, dst_reg);
        la_b(label_done);

        la_label(label_do_shift);

        if (max_shift == 63) {
            la_xvreplve0_d(mask_reg, src_cnt);
            la_xvldi(tmp_reg, VLDI_IMM_TYPE0(3, 63));
            la_xvsle_du(mask_reg, mask_reg, tmp_reg);
        } else {
            la_xvreplve0_d(mask_reg, src_cnt);
            la_xvslei_du(mask_reg, mask_reg, max_shift);
        }

        repl_func(tmp_reg, src_cnt);
        reg_shift_func(dst_reg, src_reg, tmp_reg);
        la_xvand_v(dst_reg, dst_reg, mask_reg);
    }

    if (ir1_opnd_is_xmm(op0)) {
        set_high128_xreg_to_zero(dst_reg);
    }

    la_label(label_done);
    return true;
}

bool translate_vpsrax(IR1_INST * pir1) {
    IR1_OPND * op0 = ir1_get_opnd(pir1, 0);
    IR1_OPND * op1 = ir1_get_opnd(pir1, 1);
    IR1_OPND * op2 = ir1_get_opnd(pir1, 2);

    lsassert((ir1_opnd_is_xmm(op0) && ir1_opnd_is_xmm(op1)) ||
        (ir1_opnd_is_ymm(op0) && ir1_opnd_is_ymm(op1)));

    IR2_OPND dst_reg = load_freg256_from_ir1(op0);
    IR2_OPND src_reg = load_freg256_from_ir1(op1);

    IR2_INST * ( * repl_func)(IR2_OPND, IR2_OPND);
    IR2_INST * ( * imm_shift_func)(IR2_OPND, IR2_OPND, int);
    IR2_INST * ( * reg_shift_func)(IR2_OPND, IR2_OPND, IR2_OPND);

    int max_shift;

    switch (ir1_opcode(pir1)) {
        case dt_X86_INS_VPSRAW:
            repl_func = la_xvreplve0_h;
            imm_shift_func = la_xvsrai_h;
            reg_shift_func = la_xvsra_h;
            max_shift = 15;
            break;
        case dt_X86_INS_VPSRAD:
            repl_func = la_xvreplve0_w;
            imm_shift_func = la_xvsrai_w;
            reg_shift_func = la_xvsra_w;
            max_shift = 31;
            break;
        default:
            repl_func = NULL;
            imm_shift_func = NULL;
            reg_shift_func = NULL;
            max_shift = 0;
            lsassert(0);
            break;
    }

    if (ir1_opnd_is_imm(op2)) {
        uint8_t imm = ir1_opnd_uimm(op2);
        if (imm > max_shift)
            imm = max_shift;
        imm_shift_func(dst_reg, src_reg, imm);
    } else {
        IR2_OPND src_cnt = load_freg256_from_ir1(op2);
        IR2_OPND mask_reg = ra_alloc_ftemp();
        IR2_OPND tmp_reg = ra_alloc_ftemp();
        IR2_OPND sign_ext_reg = ra_alloc_ftemp();

        if (max_shift == 63) {
            la_xvreplve0_d(mask_reg, src_cnt);
            la_vldi(tmp_reg, VLDI_IMM_TYPE0(3, 63));
            la_xvsle_du(mask_reg, mask_reg, tmp_reg);
        } else {
            la_xvreplve0_d(mask_reg, src_cnt);
            la_xvslei_du(mask_reg, mask_reg, max_shift);
        }

        imm_shift_func(sign_ext_reg, src_reg, max_shift);
        repl_func(tmp_reg, src_cnt);
        reg_shift_func(tmp_reg, src_reg, tmp_reg);
        la_xvbitsel_v(dst_reg, sign_ext_reg, tmp_reg, mask_reg);
    }

    if (ir1_opnd_is_xmm(op0)) {
        set_high128_xreg_to_zero(dst_reg);
    }

    return true;
}

