#include <cmath>
#include <format>
#include <gtest/gtest.h>
#include "maths/vector3.h"
#include "utils/formatter.h"

TEST(vector3, default_constructor)
{
    const auto vec = ufps::Vector3{};
    ASSERT_EQ(vec.x, 0.0f);
    ASSERT_EQ(vec.y, 0.0f);
    ASSERT_EQ(vec.z, 0.0f);
}

TEST(vector3, scalar_constructor)
{
    const auto vec = ufps::Vector3{2.5f};
    ASSERT_EQ(vec.x, 2.5f);
    ASSERT_EQ(vec.y, 2.5f);
    ASSERT_EQ(vec.z, 2.5f);
}

TEST(vector3, full_constructor)
{
    const auto vec = ufps::Vector3{1.5f, 3.7f, 9.2f};
    ASSERT_EQ(vec.x, 1.5f);
    ASSERT_EQ(vec.y, 3.7f);
    ASSERT_EQ(vec.z, 9.2f);
}

TEST(vector3, normalize)
{
    const auto magnitude = std::sqrt(35.0f);
    const auto vec = ufps::Vector3{2.0f, 3.0f, 4.0f};
    const auto normalized = ufps::Vector3::normalize(vec);
    EXPECT_NEAR(normalized.x, vec.x / magnitude, 0.0001f);
    EXPECT_NEAR(normalized.y, vec.y / magnitude, 0.0001f);
    EXPECT_NEAR(normalized.z, vec.z / magnitude, 0.0001f);
}

TEST(vector3, cross_product)
{
    const auto a = ufps::Vector3{2.0f, 1.0f, 3.0f};
    const auto b = ufps::Vector3{5.0f, 2.0f, 1.0f};
    ASSERT_EQ(ufps::Vector3::cross(a, b), ufps::Vector3(-5.0f, 13.0f, -1.0f));
}

TEST(vector3, add_vectors)
{
    const auto a = ufps::Vector3{3.0f, 1.0f, 4.0f};
    const auto b = ufps::Vector3{2.0f, 7.0f, 1.0f};
    ASSERT_EQ(a + b, ufps::Vector3(5.0f, 8.0f, 5.0f));
}

TEST(vector3, add_assign)
{
    auto v = ufps::Vector3{1.0f, 4.0f, 2.0f};
    v += ufps::Vector3{3.0f, 2.0f, 5.0f};
    ASSERT_EQ(v, ufps::Vector3(4.0f, 6.0f, 7.0f));
}

TEST(vector3, subtract_vectors)
{
    const auto a = ufps::Vector3{7.0f, 8.0f, 10.0f};
    const auto b = ufps::Vector3{3.0f, 5.0f, 4.0f};
    ASSERT_EQ(a - b, ufps::Vector3(4.0f, 3.0f, 6.0f));
}

TEST(vector3, subtract_assign)
{
    auto v = ufps::Vector3{6.0f, 9.0f, 11.0f};
    v -= ufps::Vector3{2.0f, 4.0f, 5.0f};
    ASSERT_EQ(v, ufps::Vector3(4.0f, 5.0f, 6.0f));
}

TEST(vector3, multiply_vectors)
{
    const auto a = ufps::Vector3{2.0f, 3.0f, 5.0f};
    const auto b = ufps::Vector3{4.0f, 6.0f, 2.0f};
    ASSERT_EQ(a * b, ufps::Vector3(8.0f, 18.0f, 10.0f));
}

TEST(vector3, multiply_assign)
{
    auto v = ufps::Vector3{3.0f, 2.0f, 4.0f};
    v *= ufps::Vector3{2.0f, 5.0f, 3.0f};
    ASSERT_EQ(v, ufps::Vector3(6.0f, 10.0f, 12.0f));
}

TEST(vector3, unary_minus)
{
    const auto v = ufps::Vector3{4.0f, -2.0f, 7.0f};
    const auto negated = ufps::Vector3{-4.0f, 2.0f, -7.0f};
    ASSERT_EQ(-v, negated);
}

TEST(vector3, string_conversion)
{
    const auto v = ufps::Vector3{5.0f, 8.0f, 1.0f};
    const auto s = v.to_string();
    ASSERT_EQ(s, "x=5 y=8 z=1");
}

TEST(vector3, format_support)
{
    const auto v = ufps::Vector3{10.0f, 20.0f, 30.0f};
    const auto formatted = std::format("{}", v);
    ASSERT_EQ(formatted, "x=10 y=20 z=30");
}

