        String ProcessOutColorLocations(const String& shaderSource) {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            static const std::regex colorPattern(R"(\n(out highp vec4 outColor)(\d+);)");
            const String replacement = "\nlayout(location=$2) $1$2;";
            return std::regex_replace(shaderSource, colorPattern, replacement);
        }

        String EnsurePrecisionDirectives(const String& shaderSource) {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            bool hasFloatPrecision = shaderSource.find("precision ") != String::npos &&
                                     shaderSource.find("float;") != String::npos;
            bool hasIntPrecision   = shaderSource.find("precision ") != String::npos &&
                                     shaderSource.find("int;")   != String::npos;

            String processedCode = shaderSource;
            String floatDirective;
            String intDirective;

            if (hasFloatPrecision && hasIntPrecision) {
                std::istringstream stream(processedCode);
                std::vector<String> filteredLines;
                String currentLine;

                while (std::getline(stream, currentLine)) {
                    bool isPrecisionDecl = (currentLine.find("precision ") != String::npos) &&
                                           (currentLine.find("float;") != String::npos ||
                                            currentLine.find("int;")   != String::npos);
                    if (!isPrecisionDecl) {
                        filteredLines.push_back(currentLine);
                    }
                }

                processedCode.clear();
                for (SizeT idx = 0; idx < filteredLines.size(); ++idx) {
                    if (idx > 0) processedCode += '\n';
                    processedCode += filteredLines[idx];
                }

                floatDirective = "precision highp float;\n";
                intDirective   = "precision highp int;\n";
            } else {
                floatDirective = hasFloatPrecision ? "" : "precision highp float;\n";
                intDirective   = hasIntPrecision   ? "" : "precision highp int;\n";
            }

            SizeT lastExtIndex = processedCode.rfind("#extension");
            SizeT insertPos = 0;

            if (lastExtIndex != String::npos) {
                SizeT nextNewline = processedCode.find('\n', lastExtIndex);
                if (nextNewline != String::npos) {
                    insertPos = nextNewline + 1;
                } else {
                    insertPos = processedCode.length();
                }
            } else {
                SizeT firstNewline = processedCode.find('\n');
                if (firstNewline != String::npos) {
                    insertPos = firstNewline + 1;
                } else {
                    processedCode = floatDirective + intDirective + processedCode;
                    return processedCode;
                }
            }

            processedCode.insert(insertPos, floatDirective + intDirective);
            return processedCode;
        }

        String StripLayoutBindings(const String& shaderSource) {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            static std::regex bindingRegex1(R"(layout\s*\(\s*binding\s*=\s*\d+\s*\)\s*)");
            String tempResult = std::regex_replace(shaderSource, bindingRegex1, "");

            static std::regex bindingRegex2(R"(layout\s*\(\s*binding\s*=\s*\d+\s*,)");
            tempResult = std::regex_replace(tempResult, bindingRegex2, "layout(");

            return tempResult;
        }
    } // namespace ProgramImpl

    namespace Utils {
        void ReportGLESFailure() {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            GLenum error;
            while ((error = g_GLESFuncs.glGetError()) != GL_NO_ERROR) {
                MGLOG_E("-> GLES Error: %s", MG_Util::ConvertGLEnumToString(error).c_str());
            }
        }

