struct SCUDSPDisassembler {
    SCUDSPDisassembler(Disassembler &d)
        : dis(d) {}

    SCUDSPDisassembler &Addr(uint8 newAddr = 0) {
        if (newAddr != 0) addr = newAddr;
        dis.Address(addr);
        return *this;
    }

    SCUDSPDisassembler &OpCode(uint32 op) {
        dis.Opcode(op);
        return *this;
    }

    SCUDSPDisassembler &ImmU8(uint8 val) {
        dis.ImmHex(val, "#");
        return *this;
    }

    SCUDSPDisassembler &ImmS8(sint8 val) {
        dis.ImmHexSignAfterPrefix(val, "#");
        return *this;
    }

    SCUDSPDisassembler &ImmS32(sint32 val) {
        dis.ImmHexSignAfterPrefix(val, "#");
        return *this;
    }

    SCUDSPDisassembler &ImmU32(uint32 val) {
        dis.ImmHex(val, "#");
        return *this;
    }

    SCUDSPDisassembler &Mnem(std::string_view name) {
        dis.Mnemonic(name);
        return *this;
    }

    SCUDSPDisassembler &Condition(ymir::scu::SCUDSPInstruction::Cond c) {
        dis.Cond(ymir::scu::ToString(c));
        return *this;
    }

    SCUDSPDisassembler &CommaSep() {
        dis.Comma();
        return *this;
    }

    SCUDSPDisassembler &ReadOp(std::string_view op) {
        dis.OperandRead(op);
        return *this;
    }

    SCUDSPDisassembler &WriteOp(std::string_view op) {
        dis.OperandWrite(op);
        return *this;
    }

    SCUDSPDisassembler &Decode(const ymir::scu::SCUDSPInstruction &inst) {
        using InstrKind = ymir::scu::SCUDSPInstruction::Type;

        switch (inst.type) {
        case InstrKind::Operation: {
            if (inst.operation.aluOp == ymir::scu::SCUDSPInstruction::ALUOp::NOP) {
                dis.NOP("NOP");
            } else {
                Mnem(ymir::scu::ToString(inst.operation.aluOp));
            }
            dis.Align(5);

            using XBusOp = ymir::scu::SCUDSPInstruction::XBusPOp;
            switch (inst.operation.xbusPOp) {
            case XBusOp::NOP: dis.NOP("NOP"); break;
            case XBusOp::MOV_MUL_P: dis.Mnemonic("MOV ").OperandRead("MUL").Comma().OperandWrite("P"); break;
            case XBusOp::MOV_S_P:
                Mnem("MOV ").OperandRead(ymir::scu::ToString(inst.operation.xbusSrc)).Comma().OperandWrite("P");
                break;
            }

            dis.Align(17);

            if (inst.operation.xbusXOp) {
                Mnem("MOV ").OperandRead(ymir::scu::ToString(inst.operation.xbusSrc)).Comma().OperandWrite("X");
            } else {
                dis.NOP("NOP");
            }

            dis.Align(29);

            using YBusOp = ymir::scu::SCUDSPInstruction::YBusAOp;
            switch (inst.operation.ybusAOp) {
            case YBusOp::NOP: dis.NOP("NOP"); break;
            case YBusOp::CLR_A: dis.Mnemonic("CLR ").OperandWrite("A"); break;
            case YBusOp::MOV_ALU_A: dis.Mnemonic("MOV ").OperandRead("ALU").Comma().OperandWrite("A"); break;
            case YBusOp::MOV_S_A:
                Mnem("MOV ").OperandRead(ymir::scu::ToString(inst.operation.xbusSrc)).Comma().OperandWrite("A");
                break;
            }

            dis.Align(41);

            if (inst.operation.ybusYOp) {
                Mnem("MOV ").OperandRead(ymir::scu::ToString(inst.operation.ybusSrc)).Comma().OperandWrite("Y");
            } else {
                dis.NOP("NOP");
            }

            dis.Align(53);

            using D1BusAction = ymir::scu::SCUDSPInstruction::D1BusOp;
            switch (inst.operation.d1BusOp) {
            case D1BusAction::NOP: dis.NOP("NOP"); break;
            case D1BusAction::MOV_SIMM_D: {
                Mnem("MOV ");
                using DstType = ymir::scu::SCUDSPInstruction::OpDst;
                switch (inst.operation.d1BusDst) {
                case DstType::MC0: [[fallthrough]];
                case DstType::MC1: [[fallthrough]];
                case DstType::MC2: [[fallthrough]];
                case DstType::MC3: ImmS8(inst.operation.d1BusSrc.imm); break;
                case DstType::RX: ImmS8(inst.operation.d1BusSrc.imm); break;
                case DstType::P: ImmS8(inst.operation.d1BusSrc.imm); break;
                case DstType::RA0: [[fallthrough]];
                case DstType::WA0:
                    ImmU32((inst.operation.d1BusSrc.imm << 2) & 0x7FF'FFFC);
                    break;
                case DstType::LOP: ImmU32(inst.operation.d1BusSrc.imm & 0xFFF); break;
                case DstType::TOP: ImmU8(inst.operation.d1BusSrc.imm); break;
                case DstType::CT0: [[fallthrough]];
                case DstType::CT1: [[fallthrough]];
                case DstType::CT2: [[fallthrough]];
                case DstType::CT3: ImmU8(inst.operation.d1BusSrc.imm & 0x3F); break;
                default: ImmS8(inst.operation.d1BusSrc.imm); break;
                }
                CommaSep().WriteOp(ymir::scu::ToString(inst.operation.d1BusDst));
                break;
            }
            case D1BusAction::MOV_S_D:
                Mnem("MOV ")
                    .ReadOp(ymir::scu::ToString(inst.operation.d1BusSrc.reg))
                    .CommaSep()
                    .WriteOp(ymir::scu::ToString(inst.operation.d1BusDst));
                break;
            }
            break;
        }

        case InstrKind::MVI:
            Mnem("MVI ");
            using MVIDst = ymir::scu::SCUDSPInstruction::MVIDst;
            switch (inst.mvi.dst) {
            case MVIDst::MC0: [[fallthrough]];
            case MVIDst::MC1: [[fallthrough]];
            case MVIDst::MC2: [[fallthrough]];
            case MVIDst::MC3: ImmU32(inst.mvi.imm & 0x3F); break;
            case MVIDst::RX: ImmU32(inst.mvi.imm); break;
            case MVIDst::P: ImmS32(inst.mvi.imm); break;
            case MVIDst::WA0: [[fallthrough]];
            case MVIDst::RA0: ImmU32((inst.mvi.imm << 2) & 0x7FF'FFFC); break;
            case MVIDst::LOP: ImmU32(inst.mvi.imm & 0xFFF); break;
            case MVIDst::PC: ImmU32(inst.mvi.imm & 0xFF); break;
            default: ImmS32(inst.mvi.imm); break;
            }
            CommaSep().WriteOp(ymir::scu::ToString(inst.mvi.dst));
            if (inst.mvi.cond != ymir::scu::SCUDSPInstruction::Cond::None) {
                CommaSep().Condition(inst.mvi.cond);
            }
            break;

        case InstrKind::DMA:
            Mnem(inst.dma.hold ? "DMAH " : "DMA ");
            if (inst.dma.toD0) {
                ReadOp(ymir::scu::ToString(inst.dma.ramOp));
            } else {
                ReadOp("D0");
            }
            CommaSep();
            if (inst.dma.toD0) {
                WriteOp("D0");
            } else {
                WriteOp(ymir::scu::ToString(inst.dma.ramOp));
            }
            CommaSep();
            if (inst.dma.countType) {
                std::string regName = fmt::format("M{}{}", (inst.dma.count.ct < 4 ? "" : "C"), inst.dma.count.ct & 3);
                ReadOp(regName);
            } else {
                ImmU8(inst.dma.count.imm);
            }
            break;

        case InstrKind::JMP:
            Mnem("JMP ");
            if (inst.jmp.cond != ymir::scu::SCUDSPInstruction::Cond::None) {
                Condition(inst.jmp.cond).CommaSep();
            }
            ImmU8(inst.jmp.target);
            break;

        case InstrKind::LPS: Mnem("LPS"); break;
        case InstrKind::BTM: Mnem("BTM"); break;
        case InstrKind::END: Mnem("END"); break;
        case InstrKind::ENDI: Mnem("ENDI"); break;

        default: dis.IllegalMnemonic(); break;
        }

        return *this;
    }

    SCUDSPDisassembler &Process(uint32 opcode) {
        const auto &instruction = ymir::scu::Disassemble(opcode);
        Addr().OpCode(opcode).Decode(instruction);
        dis.NewLine();
        ++addr;
        return *this;
    }

    Disassembler &dis;
    uint8 addr = 0;
};

using SCUDSPOpcode = uint32;
using SCUDSPOpcodeFetcher = IOpcodeFetcher<SCUDSPOpcode>;
using CommandLineSCUDSPOpcodeFetcher = CommandLineOpcodeFetcher<SCUDSPOpcode>;
using StreamSCUDSPOpcodeFetcher = StreamOpcodeFetcher<SCUDSPOpcode>;

bool DisassembleSCUDSP(Disassembler &dis, std::string_view origin, const std::vector<std::string> &params,
                       const std::string &inputFile) {
    auto parsedAddress = ParseHex<uint8>(origin);
    if (!parsedAddress) {
        fmt::println("Invalid origin address: {}", origin);
        return false;
    }

    SCUDSPDisassembler scuDis{dis};
    scuDis.addr = *parsedAddress;

    auto fetcher =
        MakeFetcher<SCUDSPOpcodeFetcher, CommandLineSCUDSPOpcodeFetcher, StreamSCUDSPOpcodeFetcher>(params, inputFile);
    if (!fetcher) {
        return false;
    }

    bool active = true;
    const auto handleResult = [&](auto &&val) {
        using V = std::decay_t<decltype(val)>;
        if constexpr (std::is_same_v<V, SCUDSPOpcode>) {
            scuDis.Process(val);
        } else if constexpr (std::is_same_v<V, OpcodeFetchError>) {
            fmt::println("{}", val.message);
            active = false;
        } else if constexpr (std::is_same_v<V, OpcodeFetchEnd>) {
            active = false;
        }
    };

    while (active) {
        auto fetched = fetcher->Fetch();
        std::visit(handleResult, fetched);
    }

    return true;
}

#include "ReCraftCore.hpp"
#include "client/gui/screens/GuiInGame.hpp"
#include "client/gui/screens/SelectWorldScreen.hpp"
#include "client/gui/screens/StartScreen.hpp"
