        Text(),
        m_box(),
        m_inset(1.5f, 1.5f),
        m_backgroundColor(sf::Color::White),
        m_borderColor(sf::Color::Black),
        m_borderWidth(2.f),
        m_displayTime(),
        m_activeTime()
    {
    }

    ToolTip::ToolTip(const Font& font, const sf::String& text, const unsigned int fontSize) :
        Text(font, text, fontSize),
        m_box(),
        m_inset(fontSize * (12.f / 100.f), fontSize * (12.f / 100.f)),
        m_backgroundColor(sf::Color::White),
        m_borderColor(sf::Color::Black),
        m_borderWidth(2.f),
        m_displayTime(),
        m_activeTime()
    {
    }

    sf::FloatRect ToolTip::GetLocalBounds() const
    {
        return m_box.GetLocalBounds();
    }

    void ToolTip::Show(Control* owner)
    {
        auto pos = sf::Vector2f();
        auto align = Alignment::Left;
        if (owner)
        {
            const auto bounds = owner->GetLocalBounds();
            pos = sf::Vector2f(bounds.size.x, bounds.size.y) / 2.f;
            pos = sf::Vector2f(static_cast<int>(pos.x), static_cast<int>(pos.y));
            align = Alignment::Center;
        }
        Show(pos, align);
    }

    void ToolTip::Show(const sf::Vector2f position, const Alignment alignment)
    {
        if (alignment == Alignment::Center || alignment == Alignment::Right)
        {
            Invalidate();
            if (alignment == Alignment::Center)
                SetOrigin(m_box.GetSize().x / 2.f, m_box.GetSize().y / 2.f);
            else
                SetOrigin(m_box.GetSize().x, m_box.GetSize().y);
        }
        else
            SetOrigin(sf::Vector2f());
        SetPosition(position);
        Show();
    }

    void ToolTip::Show()
    {
        m_activeTime = sf::Time::Zero;
        Invalidate();
    }

    void ToolTip::Hide()
    {
        m_activeTime = m_displayTime;
    }

    const sf::Time& ToolTip::GetDisplayDuration() const
    {
        return m_displayTime;
    }

    void ToolTip::SetDisplayDuration(const sf::Time& duration)
    {
        if (m_displayTime != duration)
        {
            const bool currentlyVisible = m_activeTime < m_displayTime;
            m_displayTime = duration;
            m_activeTime = currentlyVisible ? sf::Time::Zero : duration;
        }
    }

    sf::Vector2f ToolTip::GetPadding() const
    {
        return m_inset;
    }

    void ToolTip::SetPadding(const sf::Vector2f& inset)
    {
        if (m_inset != inset)
        {
            m_inset = inset;
            Invalidate();
        }
    }

    const sf::Color& ToolTip::GetBackgroundColor() const
    {
        return m_backgroundColor;
    }

    void ToolTip::SetBackgroundColor(const sf::Color& color)
    {
        if (m_backgroundColor != color)
        {
            m_backgroundColor = color;
            Invalidate();
        }
    }

    const sf::Color& ToolTip::GetBorderColor() const
    {
        return m_borderColor;
    }

    void ToolTip::SetBorderColor(const sf::Color& color)
    {
        if (m_borderColor != color)
        {
            m_borderColor = color;
            Invalidate();
        }
    }

    float ToolTip::GetBorderThickness() const
    {
        return m_borderWidth;
    }

    void ToolTip::SetBorderThickness(const float thickness)
    {
        if (m_borderWidth != thickness)
        {
            m_borderWidth = thickness;
            Invalidate();
        }
    }

    RenderStates ToolTip::Render(RenderSurface& surface, const RenderStates states) const
    {
        if (IsVisible() && !GetString().isEmpty())
        {
            auto renderState = states;
            renderState.transform *= GetTransform();
            surface.Render(m_box, renderState);
        }
        return Label::Render(surface, states);
    }

    void ToolTip::Update(const double dt)
    {
        Label::Update(dt);
        if (m_activeTime < m_displayTime)
            m_activeTime += sf::milliseconds(dt);
        if (IsVisible())
            Invalidate();
    }

    void ToolTip::Invalidate()
    {
        Label::Invalidate();
        const auto textBounds = Text::GetLocalBounds();
        const auto boxSize    = sf::Vector2f(textBounds.size.x, textBounds.size.y) + (m_inset * 2.f);
        m_box.SetSize({ std::ceil(boxSize.x), std::ceil(boxSize.y) });
        m_box.SetPosition(sf::Vector2f(0, std::ceil(m_inset.y * 1.75f)));
        m_box.SetColor(m_backgroundColor);
        m_box.SetOutlineColor(m_borderColor);
        m_box.SetOutlineThickness(m_borderWidth);
        SetVisible(m_activeTime < m_displayTime);
    }
}

#include "Distance/DistLine3Circle3.h"
#include "ThirdParty/GTEngine/Mathematics/GteDistLine3Circle3.h"
#include "GteUtil.h"

template <typename T>
T TDistLine3Circle3<T>::ComputeResult()
{
    if (SquaredDistance >= 0)
    {
        return SquaredDistance;
    }

    gte::Line3<T> gteLine = Convert(Line);
    gte::Circle3<T> gteCircle = Convert(Circle);
    gte::DCPQuery<T, gte::Line3<T>, gte::Circle3<T>> distanceQuery;
    auto queryResult = distanceQuery(gteLine, gteCircle);

    SquaredDistance = queryResult.sqrDistance;
    ClosestPairCount = queryResult.numClosestPairs;

    LineClosest[0] = Convert(queryResult.lineClosest[0]);
    LineClosest[1] = Convert(queryResult.lineClosest[1]);
    CircleClosest[0] = Convert(queryResult.circleClosest[0]);
    CircleClosest[1] = Convert(queryResult.circleClosest[1]);

    bIsEquiDistant = queryResult.equidistant;

    return SquaredDistance;
}

