class TransformMessage::Impl : public MessageImpl {
 public:
  Impl();
  Impl(TimeNano timestamp, std::string frame_parent, 
       std::string frame_child, Vector3 trans, Quaternion rot);
  ~Impl() override {}

  const Vector3 GetTrans() const;
  const Quaternion GetRot() const;
  const std::string GetFrameParent() const;
  const std::string GetFrameChild() const;

  std::string Serialize() override;
  void Deserialize(const std::string& data) override;

  MSGPACK_DEFINE_MAP(timestamp, frame_parent, frame_child, trans, rot);

 private:
  TimeNano timestamp;
  std::string frame_parent;
  std::string frame_child;
  Vector3Msgpack trans;
  QuaternionMsgpack rot;
};

TransformMessage::TransformMessage()
    : Message(std::make_shared<TransformMessage::Impl>()) {}

TransformMessage::TransformMessage(TimeNano timestamp,
                                   std::string frame_parent,
                                   std::string frame_child,
                                   Vector3 trans, Quaternion rot)
    : Message(std::make_shared<TransformMessage::Impl>(
          timestamp, frame_parent, frame_child, trans, rot)) {}

TransformMessage::~TransformMessage() {}

const Vector3 TransformMessage::GetTranslation() const {
  return static_cast<TransformMessage::Impl*>(pimpl_.get())->GetTrans();
}

const Quaternion TransformMessage::GetRotation() const {
  return static_cast<TransformMessage::Impl*>(pimpl_.get())->GetRot();
}

const std::string TransformMessage::GetParentFrameId() const {
  return static_cast<TransformMessage::Impl*>(pimpl_.get())->GetFrameParent();
}

const std::string TransformMessage::GetChildFrameId() const {
  return static_cast<TransformMessage::Impl*>(pimpl_.get())->GetFrameChild();
}

std::string TransformMessage::Serialize() const {
  return static_cast<TransformMessage::Impl*>(pimpl_.get())->Serialize();
}

void TransformMessage::Deserialize(const std::string& data) {
  static_cast<TransformMessage::Impl*>(pimpl_.get())->Deserialize(data);
}

TransformMessage::Impl::Impl() : MessageImpl(MessageType::kTransform) {}

TransformMessage::Impl::Impl(TimeNano timestamp, std::string frame_parent,
                             std::string frame_child, Vector3 trans,
                             Quaternion rot)
    : MessageImpl(MessageType::kTransform),
      timestamp(timestamp),
      frame_parent(frame_parent),
      frame_child(frame_child),
      trans(trans),
      rot(rot) {}

const Vector3 TransformMessage::Impl::GetTrans() const {
  return trans.ToVector3();
}

const Quaternion TransformMessage::Impl::GetRot() const {
  return rot.ToQuaternion();
}

const std::string TransformMessage::Impl::GetFrameParent() const {
  return frame_parent;
}

const std::string TransformMessage::Impl::GetFrameChild() const {
  return frame_child;
}

std::string TransformMessage::Impl::Serialize() {
  std::stringstream stream;
  msgpack::packer<std::stringstream> packer(stream);
  this->msgpack_pack(packer);
  return stream.str();
}

void TransformMessage::Impl::Deserialize(const std::string& data) {
  auto handle = msgpack::unpack(data.data(), data.size());
  auto object = handle.get();
  this->msgpack_unpack(object);
}

