#include "thread.h"

namespace LVMon {

CThread::CThread(void) : events_(), fShouldStop_(false), pthread_(nullptr) {}

CThread::~CThread() {
  StopAsync();
  WaitForStop();
}

void CThread::Start(std::function<void(CThread *)> threadFunction) {
  fShouldStop_ = false;
  events_.Reset(kEventExitThread);
  pthread_ = new std::thread(ThreadProcProxy, this, threadFunction);
}

void CThread::StopAsync(void) {
  fShouldStop_ = true;
  events_.Set(kEventExitThread);
}

void CThread::ThreadProcProxy(CThread *threadInstance,
                              std::function<void(CThread *)> threadFunction) {
  threadFunction(threadInstance);
}

void CThread::WaitForStop(void) {
  if (pthread_ != nullptr) {
    auto threadToJoin = pthread_;
    pthread_ = nullptr;
    threadToJoin->join();
    delete threadToJoin;
  }
}

