struct PixelBlock
{
	PixelBlock& operator +=(const PixelBlock& rhs)
	{
		r += rhs.r;
		g += rhs.g;
		b += rhs.b;
		a += rhs.a;
		return *this;
	}

	PixelBlock& operator -=(const PixelBlock& rhs)
	{
		r -= rhs.r;
		g -= rhs.g;
		b -= rhs.b;
		a -= rhs.a;
		return *this;
	}

	PixelBlock& operator -=(const uint8_t* data)
	{
		r -= data[0];
		g -= data[1];
		b -= data[2];
		a -= data[3];
		return *this;
	}

	void Accumulate(const uint8_t* src, uint8_t weight = 1)
	{
		r += src[0] * weight;
		g += src[1] * weight;
		b += src[2] * weight;
		a += src[3] * weight;
	}

	void Clear()
	{
		r = g = b = a = 0;
	}

	uint32_t r{}, g{}, b{}, a{};
};

StackBlur::StackBlur(uint8_t blurRadius, const D2D1_SIZE_U& dimensions) 
	: radius(std::clamp<uint8_t>(blurRadius, 2, 254)), size(dimensions)
{
	windowSize = (radius * 2U) + 1U;
	threadCount = std::max(1U, std::thread::hardware_concurrency());
	rightShiftSum = blur_shr_table[radius];
	multiplierSum = blur_mul_table[radius];
}

void StackBlur::Execute(uint8_t* imageBuffer) noexcept
{
	const uint32_t bufferSize = windowSize * 4U * threadCount;
	std::vector<uint8_t> buffer(bufferSize);
	std::vector<std::thread> threads(threadCount);

	// Horizontal pass
	for (uint32_t tid = 0; tid < threadCount; ++tid)
	{
		threads[tid] = std::thread([&, tid]
			{
				const uint32_t localOffset = windowSize * 4U * tid;
				ProcessThread(1, tid, imageBuffer, &buffer[localOffset]);
			});
	}
	for (auto& t : threads)
		t.join();

	// Vertical pass
	for (uint32_t tid = 0; tid < threadCount; ++tid)
	{
		threads[tid] = std::thread([&, tid]
			{
				const uint32_t localOffset = windowSize * 4U * tid;
				ProcessThread(2, tid, imageBuffer, &buffer[localOffset]);
			});
	}
	for (auto& t : threads)
		t.join();
}

void StackBlur::WriteResult(uint8_t* dst, const PixelBlock& accumulator) noexcept
{
	dst[0] = static_cast<uint8_t>((accumulator.r * multiplierSum) >> rightShiftSum);
	dst[1] = static_cast<uint8_t>((accumulator.g * multiplierSum) >> rightShiftSum);
	dst[2] = static_cast<uint8_t>((accumulator.b * multiplierSum) >> rightShiftSum);
	dst[3] = static_cast<uint8_t>((accumulator.a * multiplierSum) >> rightShiftSum);
}

void StackBlur::ProcessThread(uint32_t phase, uint32_t threadId, uint8_t* input, uint8_t* localStack) noexcept
{
	PixelBlock totalAccumulator, incomingAccumulator, outgoingAccumulator;
	uint8_t* stackPointer;
	uint8_t* sourcePointer;
	uint8_t* destPointer;

	const uint32_t widthMinusOne = size.width - 1;
	const uint32_t heightMinusOne = size.height - 1;
	const uint32_t rowStride = size.width * 4;
	uint32_t stackIndex{}, stackHead{};

	if (phase == 1)
	{
		const uint32_t startY = threadId * size.height / threadCount;
		const uint32_t endY = (threadId + 1) * size.height / threadCount;

		for (uint32_t y = startY; y < endY; ++y)
		{
			totalAccumulator.Clear();
			incomingAccumulator.Clear();
			outgoingAccumulator.Clear();

			sourcePointer = input + rowStride * y;

			for (uint8_t i = 0; i <= radius; ++i)
			{
				stackPointer = &localStack[i * 4];
				memcpy(stackPointer, sourcePointer, 4);
				totalAccumulator.Accumulate(sourcePointer, i + 1);
				outgoingAccumulator.Accumulate(sourcePointer);
			}

			for (uint8_t i = 1; i <= radius; ++i)
			{
				if (i <= widthMinusOne) sourcePointer += 4;
				stackPointer = &localStack[4 * (i + radius)];
				memcpy(stackPointer, sourcePointer, 4);
				totalAccumulator.Accumulate(sourcePointer, radius + 1 - i);
				incomingAccumulator.Accumulate(sourcePointer);
			}

			stackHead = radius;
			uint32_t xPos = std::min<uint32_t>(radius, widthMinusOne);
			sourcePointer = input + 4 * (xPos + y * size.width);
			destPointer = input + y * rowStride;

			for (uint32_t x = 0; x < size.width; ++x)
			{
				WriteResult(destPointer, totalAccumulator);
				destPointer += 4;

				stackHead = stackIndex + windowSize - radius;
				if (stackHead >= windowSize)
					stackHead -= windowSize;

				stackPointer = &localStack[4 * stackHead];

				if (xPos < widthMinusOne)
				{
					sourcePointer += 4;
					++xPos;
				}

				totalAccumulator -= outgoingAccumulator;
				outgoingAccumulator -= stackPointer;
				memcpy(stackPointer, sourcePointer, 4);
				incomingAccumulator.Accumulate(sourcePointer);
				totalAccumulator += incomingAccumulator;

				++stackIndex;
				if (stackIndex >= windowSize)
					stackIndex = 0;

				stackPointer = &localStack[stackIndex * 4];
				outgoingAccumulator.Accumulate(stackPointer);
				incomingAccumulator -= stackPointer;
			}
		}
	}
	else if (phase == 2)
	{
		const uint32_t startX = threadId * size.width / threadCount;
		const uint32_t endX = (threadId + 1) * size.width / threadCount;

		for (uint32_t x = startX; x < endX; ++x)
		{
			totalAccumulator.Clear();
			incomingAccumulator.Clear();
			outgoingAccumulator.Clear();

			sourcePointer = input + 4 * x;

			for (uint8_t i = 0; i <= radius; ++i)
			{
				stackPointer = &localStack[i * 4];
				memcpy(stackPointer, sourcePointer, 4);
				totalAccumulator.Accumulate(sourcePointer, i + 1);
				outgoingAccumulator.Accumulate(sourcePointer);
			}

			for (uint8_t i = 1; i <= radius; ++i)
			{
				if (i <= heightMinusOne) sourcePointer += rowStride;
				stackPointer = &localStack[4 * (i + radius)];
				memcpy(stackPointer, sourcePointer, 4);
				totalAccumulator.Accumulate(sourcePointer, radius + 1 - i);
				incomingAccumulator.Accumulate(sourcePointer);
			}

			stackHead = radius;
			uint32_t yPos = std::min<uint32_t>(radius, heightMinusOne);
			sourcePointer = input + 4 * (x + yPos * size.width);
			destPointer = input + 4 * x;

			for (uint32_t y = 0; y < size.height; ++y)
			{
				WriteResult(destPointer, totalAccumulator);
				destPointer += rowStride;

				stackHead = stackIndex + windowSize - radius;
				if (stackHead >= windowSize)
					stackHead -= windowSize;

				stackPointer = &localStack[4 * stackHead];

				if (yPos < heightMinusOne)
				{
					sourcePointer += rowStride;
					++yPos;
				}

				totalAccumulator -= outgoingAccumulator;
				outgoingAccumulator -= stackPointer;
				memcpy(stackPointer, sourcePointer, 4);
				incomingAccumulator.Accumulate(sourcePointer);
				totalAccumulator += incomingAccumulator;

				++stackIndex;
				if (stackIndex >= windowSize)
					stackIndex = 0;

				stackPointer = &localStack[stackIndex * 4];
				outgoingAccumulator.Accumulate(stackPointer);
				incomingAccumulator -= stackPointer;
			}
		}
	}
}

