/**
 * @brief Initialize the matrix with two random tiles
 */
void init_matrix_num(uint16_t dim, uint16_t **grid)
{
    for (uint8_t row = 0; row < dim; row++) {
        for (uint8_t col = 0; col < dim; col++) {
            grid[row][col] = 0;
        }
    }
    // Add two random tiles
    add_random(dim, grid);
    add_random(dim, grid);
}

/**
 * @brief Add a random tile (2 or 4) to the matrix
 */
void add_random(uint16_t dim, uint16_t **grid)
{
    static bool seeded = false;
    if (!seeded) {
        srand((unsigned int)time(NULL));
        seeded = true;
    }
    uint16_t empty_cells[dim * dim][2];
    uint16_t count = 0;
    for (uint8_t row = 0; row < dim; row++) {
        for (uint8_t col = 0; col < dim; col++) {
            if (grid[row][col] == 0) {
                empty_cells[count][0] = row;
                empty_cells[count][1] = col;
                count++;
            }
        }
    }
    if (count > 0) {
        uint16_t idx = rand() % count;
        uint8_t r_x = empty_cells[idx][0];
        uint8_t r_y = empty_cells[idx][1];
        uint16_t val = (rand() % 10 == 0) ? 4 : 2; // 10% chance for 4, else 2
        grid[r_x][r_y] = val;
    }
}

/**
 * @brief Move up (or left/right/down via rotation)
 */
bool move_up(uint16_t * score, uint16_t dim, uint16_t **grid) {
    bool moved = false;
    for (uint8_t col = 0; col < dim; col++) {
        uint16_t column_data[16]; // Assuming max size <= 16
        for (uint8_t row = 0; row < dim; row++) {
            column_data[row] = grid[row][col];
        }
        moved |= slide_array(score, dim, column_data);
        for (uint8_t row = 0; row < dim; row++) {
            grid[row][col] = column_data[row];
        }
    }
    return moved;
}

bool move_down(uint16_t * score, uint16_t dim, uint16_t **grid) {
    rotate_matrix(dim, grid);
    rotate_matrix(dim, grid);
    bool moved = move_up(score, dim, grid);
    rotate_matrix(dim, grid);
    rotate_matrix(dim, grid);
    return moved;
}

bool move_left(uint16_t * score, uint16_t dim, uint16_t **grid) {
    rotate_matrix(dim, grid);
    bool moved = move_up(score, dim, grid);
    rotate_matrix(dim, grid);
    rotate_matrix(dim, grid);
    rotate_matrix(dim, grid);
    return moved;
}

bool move_right(uint16_t * score, uint16_t dim, uint16_t **grid) {
    rotate_matrix(dim, grid);
    rotate_matrix(dim, grid);
    rotate_matrix(dim, grid);
    bool moved = move_up(score, dim, grid);
    rotate_matrix(dim, grid);
    return moved;
}

/**
 * @brief Check if the game is over (no moves left)
 *        Does not mutate the original matrix
 */
bool game_over(uint16_t dim, const uint16_t **grid) {
    if (count_empty(dim, grid) > 0) return false;
    if (find_pair_down(dim, grid)) return false;

    // Check for possible moves in rotated matrices
    uint16_t **temp_copy = lv_malloc(dim * sizeof(uint16_t*));
    for (uint16_t i = 0; i < dim; i++) {
        temp_copy[i] = lv_malloc(dim * sizeof(uint16_t));
        memcpy(temp_copy[i], grid[i], dim * sizeof(uint16_t));
    }

    rotate_matrix(dim, temp_copy);
    if (find_pair_down(dim, (const uint16_t **)temp_copy)) {
        for (uint16_t i = 0; i < dim; i++) lv_free(temp_copy[i]);
        lv_free(temp_copy);
        return false;
    }

    rotate_matrix(dim, temp_copy);
    if (find_pair_down(dim, (const uint16_t **)temp_copy)) {
        for (uint16_t i = 0; i < dim; i++) lv_free(temp_copy[i]);
        lv_free(temp_copy);
        return false;
    }

    rotate_matrix(dim, temp_copy);
    if (find_pair_down(dim, (const uint16_t **)temp_copy)) {
        for (uint16_t i = 0; i < dim; i++) lv_free(temp_copy[i]);
        lv_free(temp_copy);
        return false;
    }

    for (uint16_t i = 0; i < dim; i++) lv_free(temp_copy[i]);
    lv_free(temp_copy);
    return true;
}

/**
 * @brief Get the current score
 */
uint32_t twoeleven_get_score(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return 0;
    return game_2048->score;
}

/**
 * @brief Get the game over status
 */
bool twoeleven_get_status(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return true;
    return game_2048->game_over;
}

/**
 * @brief Get the best tile value
 */
uint16_t twoeleven_get_best_tile(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return 0;
    uint16_t highest = 0;
    for (uint8_t x = 0; x < game_2048->matrix_size; x++) {
        for (uint8_t y = 0; y < game_2048->matrix_size; y++) {
            if (highest < game_2048->matrix[x][y]) {
                highest = game_2048->matrix[x][y];
            }
        }
    }
    return (uint16_t)(1 << highest);
}

