    void transferIndicesToGroup(MIntArray& indexArray, const MObject& node,
                                MObject& shaderGroup)
    {
        MStatus status;
        MFnDagNode dagNode(node);
        MDagPath shapePath;
        status = dagNode.getPath(shapePath);

        // If the mesh is intermediate (e.g., deformed), assign to the deformed shape
        if (dagNode.isIntermediateObject())
        {
            MDagPath activeShape = shapePath;
            activeShape.pop();
            if (activeShape.extendToShape())
                shapePath = activeShape;
        }

        // Clear existing members from the set
        MFnSet groupFn(shaderGroup);
        MSelectionList currentMembers;
        groupFn.getMembers(currentMembers, false);
        MItSelectionList memberIter(currentMembers);
        for (; !memberIter.isDone(); memberIter.next())
        {
            MDagPath path;
            MObject component;
            memberIter.getDagPath(path, component);
            if ((path == shapePath) && component.isNull())
                groupFn.removeMember(path, component);
        }

        // Prepare indexed component with new indices
        MFnSingleIndexedComponent compFn;
        MObject comp = compFn.create(MFn::kMeshPolygonComponent);
        compFn.addElements(indexArray);

        // Enforce exclusivity: remove from other sets
        MObjectArray connectedSGs(getOutConnectedSG(shapePath));
        MObject sgObj;
        MFnSet otherSetFn;
        MSelectionList currentSetList, otherSetList, xorList;
        currentSetList.add(shapePath, comp);
        int numSGs = connectedSGs.length();
        for (int i = 0; i < numSGs; ++i)
        {
            sgObj = connectedSGs[i];
            if (sgObj != shaderGroup)
            {
                otherSetFn.setObject(sgObj);
                otherSetList.clear();
                otherSetFn.getMembers(otherSetList, false);

                // Handle full partition case
                if (otherSetList.length() >= 1)
                {
                    MItSelectionList it(otherSetList);
                    for (; !it.isDone(); it.next())
                    {
                        MDagPath dp;
                        MObject compObj;
                        it.getDagPath(dp, compObj);
                        if (!(dp == shapePath) || !compObj.isNull())
                            continue;

                        otherSetFn.removeMember(dp, compObj);

                        MFnMesh meshFn(shapePath);
                        MFnSingleIndexedComponent fullCompFn;
                        compObj = fullCompFn.create(MFn::kMeshPolygonComponent);
                        fullCompFn.setCompleteData(meshFn.numPolygons());

                        otherSetList.clear();
                        otherSetList.add(shapePath, compObj);
                        break;
                    }
                }

                xorList = otherSetList;
                xorList.merge(currentSetList, MSelectionList::kXORWithList);
                otherSetList.merge(xorList, MSelectionList::kRemoveFromList);

                if (!otherSetList.isEmpty())
                    otherSetFn.removeMembers(otherSetList);
            }
        }

        // Add the new component to the target set
        groupFn.addMember(shapePath, comp);
    }

    void createFaceSets(MObject & node, Alembic::Abc::IObject & abcObj)
    {
        MStatus status;
        MFnDependencyNode meshFn(node, &status);
        if (status != MS::kSuccess)
            return;

        std::size_t childCount = abcObj.getNumChildren();
        for (std::size_t idx = 0; idx < childCount; ++idx)
        {
            Alembic::Abc::IObject child = abcObj.getChild(idx);
            if (Alembic::AbcGeom::IFaceSet::matches(child.getHeader()))
            {
                Alembic::AbcGeom::IFaceSet faceSet(child, Alembic::Abc::kWrapExisting);
                MObject shadingGroup;
                const MString& setName(faceSet.getName().c_str());

                // Check if SG already exists
                status = getObjectByName(setName, shadingGroup);
                if (shadingGroup.isNull())
                {
                    shadingGroup = createShadingGroup(setName);
                }

                // Ensure 'AbcFacesetName' attribute exists
                MFnDependencyNode sgFn(shadingGroup);
                MPlug namePlug = sgFn.findPlug("AbcFacesetName", true);
                if (namePlug.isNull())
                {
                    MFnStringData strData;
                    MString attrName("AbcFacesetName");
                    MObject strAttr = strData.create("");
                    MFnTypedAttribute typedAttr;
                    MObject attrObj = typedAttr.create(attrName, attrName,
                                                       MFnData::kString, strAttr);
                    sgFn.addAttribute(attrObj);
                    namePlug = sgFn.findPlug(attrObj, true);
                }
                namePlug.setValue(setName);

                // Get face indices
                Alembic::AbcGeom::IFaceSetSchema::Sample sample;
                faceSet.getSchema().get(sample);
                MFnIntArrayData arrFn;
                const int* facesPtr = static_cast<const int*>(sample.getFaces()->getData());
                const size_t count = sample.getFaces()->size();
                MIntArray indices(facesPtr, static_cast<unsigned int>(count));

                // Assign indices to the set
                transferIndicesToGroup(indices, node, shadingGroup);

                // Process properties
                Alembic::Abc::ICompoundProperty arbProp =
                    faceSet.getSchema().getArbGeomParams();
                Alembic::Abc::ICompoundProperty userProp =
                    faceSet.getSchema().getUserProperties();
                addProps(arbProp, shadingGroup, false);
                addProps(userProp, shadingGroup, false);
            }
        }
    }

    void removeDagNode(MDagPath & path)
    {
        MStatus status = deleteDagNode(path);
        if (status != MS::kSuccess)
        {
            MString errorMsg = path.partialPathName();
            errorMsg += MString(" removal failed");
            printError(errorMsg);
        }
    }

    Alembic::Abc::IScalarProperty getVisibility(Alembic::Abc::IObject & obj,
        bool isConstant,
        std::vector<Prop> & propList,
        std::vector<Alembic::AbcGeom::IObject> & staticVisObjs)
    {
        Alembic::AbcGeom::IVisibilityProperty visProp =
            Alembic::AbcGeom::GetVisibilityProperty(obj);
        if (visProp && !visProp.isConstant())
        {
            Prop prop;
            prop.mScalar = visProp;
            propList.push_back(prop);
            if (isConstant)
            {
                staticVisObjs.push_back(obj);
            }
        }
        return visProp;
    }

    void applyConstantVisibility(Alembic::Abc::IScalarProperty visProp,
        MObject & parent)
    {
        if (visProp.valid() && visProp.isConstant())
        {
            Alembic::Util::int8_t visVal;
            visProp.get(&visVal);
            MFnDependencyNode dep(parent);
            MPlug plug = dep.findPlug("visibility", true);
            if (!plug.isNull())
            {
                plug.setBool(visVal != 0);
            }
        }
    }

    bool matchesPattern(const MString& name,
                        const MStringArray & patterns)
    {
        unsigned int count = patterns.length();
        if (count == 0)
            return true;

        for (unsigned int i = 0; i < count; ++i)
        {
            MString script, result;
            script.format("match \"^1s\" \"^2s\";", patterns[i], name);
            MGlobal::executeCommand(script, result);
            if (result.length() > 0)
            {
                return true;
            }
        }
        return false;
    }

    void linkIntermediateMesh(MFnMesh& ioMesh, MFnMesh& targetMesh)
    {
        MDGModifier modifier;

        // Create dynamic attribute to mark intermediate mesh
        MFnNumericAttribute numericAttr;
        MObject aioAttr = numericAttr.create(
            "AlembicIntermediateObject", "aio", MFnNumericData::kBoolean);
        modifier.addAttribute(ioMesh.object(), aioAttr);
        modifier.doIt();

        // Configure intermediate mesh and connect
        modifier.renameNode(ioMesh.object(), targetMesh.name() + "Orig");
        modifier.newPlugValueBool(ioMesh.findPlug("intermediateObject", true), true);
        modifier.newPlugValueBool(ioMesh.findPlug(aioAttr, true), true);
        modifier.connect(ioMesh.findPlug("outMesh", true),
                         targetMesh.findPlug("inMesh", true));
        modifier.doIt();
    }

    void cleanupIntermediateMesh(MFnMesh& fn)
    {
        MPlugArray sources;
        fn.findPlug("inMesh", true).connectedTo(sources, true, false);
        if (sources.length() > 0)
        {
            MObject ioNode = sources[0].node();
            if (MFnMesh(ioNode).hasAttribute("AlembicIntermediateObject"))
            {
                MDGModifier modifier;
                modifier.deleteNode(ioNode);
                modifier.doIt();
            }
        }
    }
}

