//------------------------------------------------------------------------------
//  Static class members and Constants
bool Stream::initialized = false;
pthread_mutex_t Stream::mutex;

enum
{
    MAXBUFFER = 1000, // max string length in bytes
    LISTEN_QUEUE = 10, // max queue of pending connections for listen
    MAX_ATTEMPTS = 20, // number of connect attempts
    WAIT_INTERVAL = 250, // milliseconds to sleep between tries
    // starting and ending TCP port numbers for availability search
    START_PORT = 17000,
    END_PORT = ((1 << (sizeof(IPport) * 8)) - 1),
    HANDSHAKE_MARKER = 17400000 // magic number for MPI mode
};

// Provide missing entities for Windows
//
#if defined(WIN32)
typedef int socklen_t; // From WINSOCK.H which defines the accept() prototype
void usleep(long duration_ms)
{
    Sleep(duration_ms / 1000.0); // sleep() under Windows uses milliseconds - don't ask why
}
#endif

//------------------------------------------------------------------------------
//  Constructors and Destructor - Public Functions
Stream::Stream(
    StreamType type,
    void (*err_handler)(char *),
    void (*trace_handler)(char *))
{
    // Create an unconnected (local) stream end-point.
    // The caller has to pass the resulting handle to the remote peer
    // by other means, and then invoke the Connect method to complete
    // the stream connection.  Once the remote peer instantiates a
    // Stream using the handle sends and receives can be done.
    // This call does not block; Connect does.
    Stream::initialize();
    this->errorfunction = err_handler;
    this->tracefunction = trace_handler;
    memset(&this->local, 0, sizeof this->local);
    memset(&this->remote, 0, sizeof this->remote);
    this->connected = false;
    this->streamtype = type;
    switch (type)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        construct_MPI();
        break;
#endif
    case Stream::TCPIP:
        construct_TCPIP();
        break;
    default:
        error("Unknown stream type in initial constructor");
        break;
    }
}

Stream::Stream(
    StreamType type,
    const char *connection_info,
    void (*err_handler)(char *),
    void (*trace_handler)(char *))
{
    // Create the other half of a two-sided stream connection.
    // This is a blocking call that waits for a Connect from the peer that
    // initially created the stream.
    Stream::initialize();
    this->errorfunction = err_handler;
    this->tracefunction = trace_handler;
    memset(&this->local, 0, sizeof this->local);
    memset(&this->remote, 0, sizeof this->remote);
    this->streamtype = type;
    switch (type)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        connect_MPI(connection_info);
        break;
#endif
    case Stream::TCPIP:
        connect_TCPIP(connection_info);
        break;
    default:
        error("Unknown stream type in secondary constructor");
        break;
    }
}

Stream::~Stream(void)
{
    switch (streamtype)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        if (local.handle != NULL)
            delete[] local.handle;
        if (remote.handle != NULL)
            delete[] remote.handle;
        break;
#endif
    case Stream::TCPIP:
        close(this->local.sock);
        close(this->remote.sock);
        if (local.handle != NULL)
            delete[] local.handle;
        if (remote.handle != NULL)
            delete[] remote.handle;
        break;
    default:
        error("Unknown stream type in destructor");
        break;
    }
}

//------------------------------------------------------------------------------
//  Constructors - Private TCP/IP Functions
void Stream::construct_TCPIP(void)
{
    IPport port; // Declare outside branches
    // Try IPv6 dual-stack first
    this->local.sock = socket(AF_INET6, SOCK_STREAM, IPPROTO_TCP);
    this->is_ipv6 = (this->local.sock != -1);
    if (this->is_ipv6)
    {
        int opt_val = 0;
        setsockopt(this->local.sock, IPPROTO_IPV6, IPV6_V6ONLY, (char *)&opt_val, sizeof(opt_val));
        struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)&this->local.addr;
        sin6->sin6_family = AF_INET6;
        sin6->sin6_addr = IN6ADDR_ANY_INIT;
        // Find an available port (IPv6)
        bool port_found = false;
        for (port = START_PORT; port < END_PORT; port++)
        {
            sin6->sin6_port = htons(port);
            if (bind(this->local.sock, (struct sockaddr *)sin6, sizeof(struct sockaddr_in6)) == 0)
            {
                port_found = true;
                break;
            }
        }
        if (!port_found)
        {
            error("Cannot bind IPv6 stream socket to any port in range [%d,%d]\n", START_PORT, END_PORT - 1);
        }
    }
    else
    {
        // Fallback to IPv4
        this->local.sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (this->local.sock == -1)
            error("Cannot create local socket for unpaired stream");
        struct sockaddr_in *sin = (struct sockaddr_in *)&this->local.addr;
        sin->sin_family = AF_INET;
        sin->sin_addr.s_addr = INADDR_ANY;
        // Find an available port (IPv4)
        bool port_found = false;
        for (port = START_PORT; port < END_PORT; port++)
        {
            sin->sin_port = htons(port);
            if (bind(this->local.sock, (struct sockaddr *)sin, sizeof(struct sockaddr_in)) == 0)
            {
                port_found = true;
                break;
            }
        }
        if (!port_found)
        {
            error("Cannot bind IPv4 stream socket to any port in range [%d,%d]\n", START_PORT, END_PORT - 1);
        }
    }

    char temp_buffer[MAXBUFFER];
    sprintf(temp_buffer, "%s:%d", hostname(), port);
    this->local.handle = new char[strlen(temp_buffer) + 1];
    strcpy(this->local.handle, temp_buffer);
    trace("Created handle %s", this->local.handle);
}

void Stream::connect_TCPIP(const char *connection_info)
{
    if (connection_info == NULL || connection_info[0] == '\0')
        error("Null or empty handle (hostname:port) string in Stream constructor");

    // Parse the hostname:port string
    char host_name[MAXBUFFER];
    char *hp = host_name;
    int port_number;
    while (*connection_info != '\0' && *connection_info != ':')
        *hp++ = *connection_info++;
    *hp = '\0';
    port_number = atoi(connection_info + 1);

    char *ip_address = this->lookup_host(host_name);

    // Try IPv6 dual-stack first
    this->remote.sock = socket(AF_INET6, SOCK_STREAM, IPPROTO_TCP);
    this->is_ipv6 = (this->remote.sock != -1);
    if (this->is_ipv6)
    {
        struct sockaddr_in6 *sin6 = (struct sockaddr_in6 *)&this->remote.addr;
        sin6->sin6_family = AF_INET6;
        sin6->sin6_port = htons(port_number);
        struct in6_addr in6;
        if (inet_pton(AF_INET6, ip_address, &in6) != 1)
        {
            // Assume IPv4 and map to IPv4-mapped IPv6
            struct in_addr in4;
            if (inet_pton(AF_INET, ip_address, &in4) != 1)
            {
                error("Invalid IP address format for host '%s': %s", host_name, ip_address);
            }
            memset(&in6, 0, sizeof(in6));
            in6.s6_addr[10] = 0xFF;
            in6.s6_addr[11] = 0xFF;
            memcpy(&in6.s6_addr[12], &in4, sizeof(in4));
        }
        sin6->sin6_addr = in6;
    }
    else
    {
        // Fallback to IPv4
        this->remote.sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (this->remote.sock == -1)
        {
            error("Cannot create remote socket for paired stream");
        }
        struct sockaddr_in *sin = (struct sockaddr_in *)&this->remote.addr;
        sin->sin_family = AF_INET;
        sin->sin_port = htons(port_number);
        if (inet_pton(AF_INET, ip_address, &sin->sin_addr) != 1)
        {
            error("Invalid IPv4 address format for host '%s': %s", host_name, ip_address);
        }
    }

    char temp_buffer[MAXBUFFER];
    sprintf(temp_buffer, "%s:%d", host_name, port_number);
    this->remote.handle = new char[strlen(temp_buffer) + 1];
    strcpy(this->remote.handle, temp_buffer);

    // Connect to remote address.  Try a few times because the other side may
    // not have done a listen yet.
    trace("Attempting to connect to %s", this->remote.handle);
    int retry_count;
    for (retry_count = 0; retry_count < MAX_ATTEMPTS; retry_count++)
    {
        socklen_t addr_len = this->is_ipv6 ? sizeof(struct sockaddr_in6) : sizeof(struct sockaddr_in);
        if (connect(this->remote.sock, (struct sockaddr *)&this->remote.addr, addr_len) == 0)
            break;
        usleep(1000 * WAIT_INTERVAL);
    }

    if (retry_count == MAX_ATTEMPTS)
        error("Cannot connect to remote socket for paired stream (%s): %s",
              this->remote.handle,
              strerror(errno));

    int bytes_read = recv(this->remote.sock, temp_buffer, MAXBUFFER, 0);
    if (bytes_read == -1)
        error("Recv of local side from new peer fails (%s)", strerror(errno));

    this->local.handle = new char[strlen(temp_buffer) + 1];
    strcpy(this->local.handle, temp_buffer);
    this->connected = true;
    trace("Created handle %s attached to %s", this->local.handle, this->remote.handle);
}

//------------------------------------------------------------------------------
//  Constructors - Private MPI Functions
#if defined(WITH_MPI)
void Stream::construct_MPI(void)
{
    this->local.seqn = next_seqn();
#if defined(NO_CPP_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &this->local.rank);
#else
    this->local.rank = MPI::COMM_WORLD.Get_rank();
#endif
    this->local.handle = new char[Stream::MAXHANDLE];
    sprintf(this->local.handle, "%s:%d:%d", hostname(), this->local.rank, this->local.seqn);
    this->connected = false;
    trace("Created handle %s", this->local.handle);
}

void Stream::connect_MPI(const char *connection_info)
{
    this->remote.handle = new char[Stream::MAXHANDLE];
    strcpy(this->remote.handle, connection_info);
    if (sscanf(connection_info, "%*[^:]:%d:%d", &this->remote.rank, &this->remote.seqn) != 2)
        error("Invalid MPI stream handle \"%s\"", connection_info);

    this->local.seqn = next_seqn();
#if defined(NO_CPP_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &this->local.rank);
#else
    this->local.rank = MPI::COMM_WORLD.Get_rank();
#endif
    this->local.handle = new char[Stream::MAXHANDLE];
    sprintf(this->local.handle, "%s:%d:%d", hostname(), this->local.rank, this->local.seqn);
    this->connected = true;

    // Send first message with local handle so peer knows who I am
#if defined(NO_CPP_MPI)
    MPI_Send((void *)this->local.handle, Stream::MAXHANDLE, MPI_CHAR, this->remote.rank, HANDSHAKE_MARKER + this->remote.seqn, MPI_COMM_WORLD);
#else
    MPI::COMM_WORLD.Send((void *)this->local.handle, Stream::MAXHANDLE, MPI::CHAR, this->remote.rank, HANDSHAKE_MARKER + this->remote.seqn);
#endif
    trace("Created handle %s attached to %s", this->local.handle, this->remote.handle);
}
#endif

//------------------------------------------------------------------------------
//  Send and Receive - Public Functions
void Stream::Connect(void)
{
    // This function is called by the first end-point of a stream to
    // complete the connection. This is a blocking call.
    switch (streamtype)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        first_receive_MPI();
        break;
#endif
    case Stream::TCPIP:
        first_receive_TCPIP();
        break;
    default:
        error("Unknown stream type in Connect");
        break;
    }
}

void Stream::Send(const char *data, int size)
{
    if (!this->connected)
        error("Attempting to send to an unconnected stream (local side is %s)", this->local.handle);

    trace("Sending message from %s to %s (%d bytes)", this->local.handle, this->remote.handle, size);
    switch (streamtype)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
#if defined(NO_CPP_MPI)
        MPI_Send((void *)data, size, MPI_CHAR, this->remote.rank, this->remote.seqn, MPI_COMM_WORLD);
#else
        MPI::COMM_WORLD.Send((void *)data, size, MPI::CHAR, this->remote.rank, this->remote.seqn);
#endif
        break;
#endif
    case Stream::TCPIP:
        if (send(this->remote.sock, data, size, 0) != size) {
            error("Send to %s fails (%s)", this->remote.handle, strerror(errno));
        }
        break;
    default:
        error("Unknown stream type in Send");
        break;
    }
    trace("Sent message from %s to %s (%d bytes)", this->local.handle, this->remote.handle, size);
}

void Stream::Receive(char *buffer, int expected_length)
{
    switch (streamtype)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        receive_MPI(buffer, expected_length);
        break;
#endif
    case Stream::TCPIP:
        receive_TCPIP(buffer, expected_length);
        break;
    default:
        error("Unknown stream type in Receive");
        break;
    }
}

//------------------------------------------------------------------------------
//  Receive - Private TCP/IP Functions
void Stream::first_receive_TCPIP(void)
{
    if (listen(this->local.sock, LISTEN_QUEUE) != 0)
        error("Cannot listen to local socket");

    trace("Waiting for connection on %s", this->local.handle);
    socklen_t addr_len = this->is_ipv6 ? sizeof(struct sockaddr_in6) : sizeof(struct sockaddr_in);
    if ((this->remote.sock = accept(this->local.sock, (struct sockaddr *)&this->remote.addr, &addr_len)) == -1)
        error("Cannot accept connection on stream");

    char addr_str[INET6_ADDRSTRLEN];
    IPport port_value;
    if (this->is_ipv6)
    {
        inet_ntop(AF_INET6, &((struct sockaddr_in6 *)&this->remote.addr)->sin6_addr, addr_str, sizeof(addr_str));
        port_value = ((struct sockaddr_in6 *)&this->remote.addr)->sin6_port;
    }
    else
    {
        inet_ntop(AF_INET, &((struct sockaddr_in *)&this->remote.addr)->sin_addr, addr_str, sizeof(addr_str));
        port_value = ((struct sockaddr_in *)&this->remote.addr)->sin_port;
    }

    this->remote.handle = new char[Stream::MAXHANDLE];
    sprintf(this->remote.handle, "%s:%d", lookup_dotaddr(addr_str), ntohs(port_value));

    if (send(this->remote.sock, this->remote.handle, Stream::MAXHANDLE, 0) != Stream::MAXHANDLE)
        error("Send of remote side to %s fails (%s)", this->remote.handle, strerror(errno));

    this->connected = true;
    trace("Created handle %s attached to %s", this->local.handle, this->remote.handle);
}

void Stream::receive_TCPIP(char *buffer, int required_length)
{
    trace("Waiting for message from %s to %s (%d bytes)", this->remote.handle, this->local.handle, required_length);
    int remaining = required_length;
    while (remaining > 0)
    {
        int received;
        if ((received = recv(this->remote.sock, buffer, remaining, 0)) < 0)
            error("Recv from %s fails (%s)", this->remote.handle, strerror(errno));
        if (received == 0)
            error("Recv from %s returns 0 bytes. Is the peer process dead?", this->remote.handle);
        remaining -= received;
        buffer += received;
    }
    trace("Got message from %s on %s (%d bytes)", this->remote.handle, this->local.handle, required_length);
}

//------------------------------------------------------------------------------
//  Receive - Private MPI Functions
#if defined(WITH_MPI)
void Stream::first_receive_MPI(void)
{
    this->remote.handle = new char[Stream::MAXHANDLE];
#if defined(NO_CPP_MPI)
    MPI_Status status;
    MPI_Recv((void *)this->remote.handle, Stream::MAXHANDLE, MPI_CHAR, MPI_ANY_SOURCE, HANDSHAKE_MARKER + this->local.seqn, MPI_COMM_WORLD, &status);
#else
    MPI::Status status;
    MPI::COMM_WORLD.Recv((void *)this->remote.handle, Stream::MAXHANDLE, MPI::CHAR, MPI::ANY_SOURCE, HANDSHAKE_MARKER + this->local.seqn, status);
#endif
    if (sscanf(this->remote.handle, "%*[^:]:%d:%d", &this->remote.rank, &this->remote.seqn) != 2)
        error("Invalid MPI stream handle \"%s\"", this->remote.handle);
    this->connected = true;
    trace("Created handle %s attached to %s", this->local.handle, this->remote.handle);
}

void Stream::receive_MPI(char *buffer, int required_length)
{
    trace("Waiting for message from %s to %s (%d bytes)", this->remote.handle, this->local.handle, required_length);
#if defined(NO_CPP_MPI)
    MPI_Status status;
    MPI_Recv((void *)buffer, required_length, MPI_CHAR, this->remote.rank, this->local.seqn, MPI_COMM_WORLD, &status);
    int count;
    MPI_Get_count(&status, MPI_CHAR, &count);
    if (required_length != count)
        error("Receive gets message from %s to %s of different length (%d) than requested (%d)", this->remote.handle, this->local.handle, count, required_length);
#else
    MPI::Status status;
    MPI::COMM_WORLD.Recv((void *)buffer, required_length, MPI::CHAR, this->remote.rank, this->local.seqn, status);
    if (required_length != status.Get_count(MPI::CHAR))
        error("Receive gets message from %s to %s of different length (%d) than requested (%d)", this->remote.handle, this->local.handle, status.Get_count(MPI::CHAR), required_length);
#endif
    trace("Got message from %s on %s (%d bytes)", this->remote.handle, this->local.handle, required_length);
}
#endif

//------------------------------------------------------------------------------
//  Other Public Functions
char *Stream::LocalHandle(void)
{
    return this->local.handle;
}

char *Stream::RemoteHandle(void)
{
    if (this->connected)
        return this->remote.handle;
    else
    {
        switch (streamtype)
        {
#if defined(WITH_MPI)
        case Stream::MPI:
            return (char *)"[mpi]:*:*";
#endif
        case Stream::TCPIP:
            return (char *)"[unknown]:0";
        default:
            return NULL;
        }
    }
}

//------------------------------------------------------------------------------
//  Private functions
void Stream::initialize(void)
{
    if (!Stream::initialized)
    {
        Stream::initialized = true;
#if defined(WIN32)
        WORD wVersionRequested = MAKEWORD(2, 2);
        WSADATA wsaData;
        if (WSAStartup(wVersionRequested, &wsaData) != 0)
            error("Initialising Winsock 2 on Windows failed: %d", WSAGetLastError());
#else
        if (pthread_mutex_init(&Stream::mutex, NULL) != 0)
            error("Pthreads error: Cannot create stream class mutex, errno=%d", errno);
#endif
    }
}

int Stream::next_seqn(void)
{
    static int sequence_counter = 101;
#if defined(WIN32)
    // nothing
#else
    if (pthread_mutex_lock(&Stream::mutex) != 0)
        error("Pthreads error: Cannot lock stream class mutex, errno=%d", errno);
#endif
    int next_sequence = sequence_counter++;
#if defined(WIN32)
    // nothing
#else
    if (pthread_mutex_unlock(&Stream::mutex) != 0)
        error("Pthreads error: Cannot unlock stream class mutex, errno=%d", errno);
#endif
    return next_sequence;
}

void Stream::trace(const char *const message, ...)
{
    if (this->tracefunction != NULL)
    {
        va_list args;
        char output[MAXBUFFER];
        va_start(args, message);
        vsprintf(output, message, args);
        va_end(args);
        this->tracefunction(output);
    }
}

char *Stream::hostname(void)
{
    static char buffer[MAXBUFFER + 1]; // not thread safe, but OK
    static bool initialized = false;
    if (!initialized)
    {
        initialized = true;
        buffer[MAXBUFFER] = '\0';
        if (gethostname(buffer, sizeof buffer) != 0)
            error("Cannot get hostname");
        if (strlen(buffer) == MAXBUFFER)
            error("hostname too long");
        for (char *bp = buffer; *bp != '\0'; *bp++)
        { // truncate domain
            if (*bp == '.')
            {
                *bp = '\0';
                break;
            }
        }
    }
    return buffer;
}

void Stream::parse_name(char *input_string, char *output_hostname, int *output_port)
{
    if (input_string == NULL)
        error("Null string in parse_name");
    while (*input_string != '\0' && *input_string != ':')
        *output_hostname++ = *input_string++;
    *output_hostname = '\0';
    *output_port = atoi(input_string + 1);
}

char *Stream::lookup_host(char *host_name)
{
    static char ip_address[INET6_ADDRSTRLEN]; // Not thread-safe, but OK as-is
    struct addrinfo hints = {0};
    struct addrinfo *result = NULL;
    // Try IPv6 first
    hints.ai_family = AF_INET6;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;
    int status = getaddrinfo(host_name, NULL, &hints, &result);
    if (status == 0 && result != NULL)
    {
        if (result->ai_addrlen == sizeof(struct sockaddr_in6))
        {
            struct sockaddr_in6 *ipv6 = (struct sockaddr_in6 *)result->ai_addr;
            inet_ntop(AF_INET6, &ipv6->sin6_addr, ip_address, sizeof(ip_address));
            freeaddrinfo(result);
            return ip_address;
        }
        freeaddrinfo(result);
    }

    // Fallback to IPv4
    hints.ai_family = AF_INET;
    status = getaddrinfo(host_name, NULL, &hints, &result);
    if (status != 0)
    {
        error("Cannot get IP address of host \"%s\": %s", host_name, gai_strerror(status));
        return NULL;
    }
    if (result == NULL || result->ai_addrlen != sizeof(struct sockaddr_in))
    {
        freeaddrinfo(result);
        error("No valid IP address found for \"%s\"", host_name);
        return NULL;
    }
    struct sockaddr_in *ipv4 = (struct sockaddr_in *)result->ai_addr;
    inet_ntop(AF_INET, &ipv4->sin_addr, ip_address, sizeof(ip_address));
    freeaddrinfo(result);
    return ip_address;
}

char *Stream::lookup_dotaddr(char *ip_dotted_address)
{
    // Map IP address to an unqualified host name (IPv6 dual-stack, cross-platform)
    static char resolved_hostname[MAXBUFFER]; // Not thread-safe, but OK
    char temp_host[MAXBUFFER];
    struct sockaddr_in6 addr6 = {0};
    addr6.sin6_family = AF_INET6;
    int status = inet_pton(AF_INET6, ip_dotted_address, &addr6.sin6_addr);
    int name_status;
    if (status == 1)
    {
        if (IN6_IS_ADDR_UNSPECIFIED(&addr6.sin6_addr))
        {
            return (char *)"localhost"; // Or appropriate hostname
        }
        socklen_t addrlen = sizeof(struct sockaddr_in6);
        name_status = getnameinfo((struct sockaddr *)&addr6, addrlen, temp_host, MAXBUFFER, NULL, 0, NI_NAMEREQD);
    }
    else
    {
        // Fallback to IPv4
        struct sockaddr_in addr4 = {0};
        addr4.sin_family = AF_INET;
        status = inet_pton(AF_INET, ip_dotted_address, &addr4.sin_addr);
        socklen_t addrlen = sizeof(struct sockaddr_in);
        name_status = getnameinfo((struct sockaddr *)&addr4, addrlen, temp_host, MAXBUFFER, NULL, 0, NI_NAMEREQD);
    }

    if (name_status != 0)
    {
        // Fallback to IP string if reverse DNS fails
        strncpy(resolved_hostname, ip_dotted_address, MAXBUFFER);
        resolved_hostname[MAXBUFFER - 1] = '\0';
        return resolved_hostname;
    }

    // Truncate at first dot (unqualified hostname)
    char *out_ptr = resolved_hostname;
    const char *in_ptr = temp_host;
    while (*in_ptr != '\0' && *in_ptr != '.')
    {
        *out_ptr++ = *in_ptr++;
    }
    *out_ptr = '\0';
    return resolved_hostname;
}

char *Stream::dotipaddr(struct in6_addr addr)
{
    // Convert IPv6 address to string (handles IPv4-mapped)
    static char dotted_addr[INET6_ADDRSTRLEN]; // not thread safe, but OK
    if (IN6_IS_ADDR_V4MAPPED(&addr))
    {
        // Extract and format IPv4
        uint32_t ipv4_value = ntohl(((uint32_t *)&addr.s6_addr[12])[0]);
        snprintf(dotted_addr, sizeof(dotted_addr), "%d.%d.%d.%d", (ipv4_value >> 24) & 0xFF, (ipv4_value >> 16) & 0xFF, (ipv4_value >> 8) & 0xFF, ipv4_value & 0xFF);
    }
    else
    {
        if (inet_ntop(AF_INET6, &addr, dotted_addr, sizeof(dotted_addr)) == NULL)
        {
            // Handle rare failure
            strcpy(dotted_addr, "[invalid]");
        }
    }
    return dotted_addr;
}

void Stream::error(const char *const reason, ...)
{
    va_list args;
    char message[MAXBUFFER];
    va_start(args, reason);
    vsprintf(message, reason, args);
    va_end(args);
    if (this->errorfunction != NULL)
    {
        this->errorfunction(message);
    }
    else
    {
        fflush(stdout);
        fprintf(stderr, "Fatal error: %s\n", message);
        fflush(stderr);
        exit(2);
    }
}

