static void smooth_normals_corner(const TriangleMesh &mesh, std::vector<stl_normal> &normals)
{
    using MapMatrixXfUnaligned =
        Eigen::Map<const Eigen::Matrix<float, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor | Eigen::DontAlign>>;
    using MapMatrixXiUnaligned =
        Eigen::Map<const Eigen::Matrix<int, Eigen::Dynamic, Eigen::Dynamic, Eigen::RowMajor | Eigen::DontAlign>>;
    std::vector<Vec3f> face_normals = its_face_normals(mesh.its);
    Eigen::MatrixXd vertices =
        MapMatrixXfUnaligned(mesh.its.vertices.front().data(), Eigen::Index(mesh.its.vertices.size()), 3).cast<double>();
    Eigen::MatrixXi indices = MapMatrixXiUnaligned(mesh.its.indices.front().data(),
                                                   Eigen::Index(mesh.its.indices.size()), 3);
    Eigen::MatrixXd in_normals =
        MapMatrixXfUnaligned(face_normals.front().data(), Eigen::Index(face_normals.size()), 3).cast<double>();
    Eigen::MatrixXd out_normals;
    igl::per_corner_normals(vertices, indices, in_normals, 1.0, out_normals);
    normals = std::vector<stl_normal>(mesh.its.vertices.size());
    for (size_t idx = 0; idx < mesh.its.indices.size(); ++idx)
    {
        for (size_t jdx = 0; jdx < 3; ++jdx)
        {
            normals[mesh.its.indices[idx][jdx]] = out_normals.row(idx * 3 + jdx).cast<float>();
        }
    }
}
#endif // ENABLE_SMOOTH_NORMALS

