namespace {
// Rational number representation for EXIF data
struct FractionData {
  uint32_t top, bottom;
  operator double() const {
    if (bottom < 1e-20) {
      return 0.0;
    }
    return static_cast<double>(top) / static_cast<double>(bottom);
  }
};

// Image File Directory Entry
class IFDItem {
 public:
  using byte_array = std::vector<uint8_t>;
  using text_array = std::string;
  using word_array = std::vector<uint16_t>;
  using dword_array = std::vector<uint32_t>;
  using fraction_array = std::vector<FractionData>;

  IFDItem()
      : field_id_(0xFF), type_id_(0xFF), value_offset_(0), count_(0), 
        val_bytes_(nullptr) {}

  IFDItem(const IFDItem &) = delete;
  IFDItem &operator=(const IFDItem &) = delete;

  IFDItem(IFDItem &&other)
      : field_id_(other.field_id_),
        type_id_(other.type_id_),
        value_offset_(other.value_offset_),
        count_(other.count_),
        val_bytes_(other.val_bytes_) {
    other.field_id_ = 0xFF;
    other.type_id_ = 0xFF;
    other.value_offset_ = 0;
    other.count_ = 0;
    other.val_bytes_ = nullptr;
  }

  ~IFDItem() { cleanup_union(); }

  unsigned short id() const { return field_id_; }
  void id(unsigned short new_id) { field_id_ = new_id; }

  unsigned short type() const { return type_id_; }

  bool set_type(unsigned short new_type) {
    switch (new_type) {
      case 0x01:
      case 0x02:
      case 0x03:
      case 0x04:
      case 0x05:
      case 0x07:
      case 0x09:
      case 0x0a:
      case 0xff:
        break;
      default:
        return false;
    }
    cleanup_union();
    type_id_ = new_type;
    init_union();
    return true;
  }

  unsigned offset() const { return value_offset_; }
  void offset(unsigned new_offset) { value_offset_ = new_offset; }

  unsigned size() const { return count_; }
  void size(unsigned new_size) { count_ = new_size; }

  // Accessors for parsed data - caller must ensure correct format
  byte_array &bytes() { return *val_bytes_; }
  text_array &text() { return *val_text_; }
  word_array &words() { return *val_words_; }
  dword_array &dwords() { return *val_dwords_; }
  fraction_array &fractions() { return *val_fractions_; }

 private:
  // Raw fields
  unsigned short field_id_;
  unsigned short type_id_;
  unsigned value_offset_;
  unsigned count_;

  // Parsed data union
  union {
    byte_array *val_bytes_;
    text_array *val_text_;
    word_array *val_words_;
    dword_array *val_dwords_;
    fraction_array *val_fractions_;
  };

  void cleanup_union() {
    switch (type_id_) {
      case 0x01:
        delete val_bytes_;
        val_bytes_ = nullptr;
        break;
      case 0x02:
        delete val_text_;
        val_text_ = nullptr;
        break;
      case 0x03:
        delete val_words_;
        val_words_ = nullptr;
        break;
      case 0x04:
        delete val_dwords_;
        val_dwords_ = nullptr;
        break;
      case 0x05:
        delete val_fractions_;
        val_fractions_ = nullptr;
        break;
      case 0xff:
        break;
      default:
        // Invalid format - ignore
        break;
    }
  }

  void init_union() {
    switch (type_id_) {
      case 0x01:
        val_bytes_ = new byte_array();
        break;
      case 0x02:
        val_text_ = new text_array();
        break;
      case 0x03:
        val_words_ = new word_array();
        break;
      case 0x04:
        val_dwords_ = new dword_array();
        break;
      case 0x05:
        val_fractions_ = new fraction_array();
        break;
      case 0xff:
        break;
      default:
        // Invalid format - ignore
        break;
    }
  }
};

// Template-based parsing functions for different data formats
template <typename T, bool littleEndian>
T read_value(const unsigned char *buffer);

template <>
uint8_t read_value<uint8_t, false>(const unsigned char *buffer) {
  return *buffer;
}

template <>
uint8_t read_value<uint8_t, true>(const unsigned char *buffer) {
  return *buffer;
}

template <>
uint16_t read_value<uint16_t, false>(const unsigned char *buffer) {
  return (static_cast<uint16_t>(buffer[0]) << 8) | buffer[1];
}

template <>
uint16_t read_value<uint16_t, true>(const unsigned char *buffer) {
  return (static_cast<uint16_t>(buffer[1]) << 8) | buffer[0];
}

template <>
uint32_t read_value<uint32_t, false>(const unsigned char *buffer) {
  return (static_cast<uint32_t>(buffer[0]) << 24) |
         (static_cast<uint32_t>(buffer[1]) << 16) |
         (static_cast<uint32_t>(buffer[2]) << 8) | buffer[3];
}

template <>
uint32_t read_value<uint32_t, true>(const unsigned char *buffer) {
  return (static_cast<uint32_t>(buffer[3]) << 24) |
         (static_cast<uint32_t>(buffer[2]) << 16) |
         (static_cast<uint32_t>(buffer[1]) << 8) | buffer[0];
}

template <>
FractionData read_value<FractionData, true>(const unsigned char *buffer) {
  FractionData f;
  f.top = read_value<uint32_t, true>(buffer);
  f.bottom = read_value<uint32_t, true>(buffer + 4);
  return f;
}

template <>
FractionData read_value<FractionData, false>(const unsigned char *buffer) {
  FractionData f;
  f.top = read_value<uint32_t, false>(buffer);
  f.bottom = read_value<uint32_t, false>(buffer + 4);
  return f;
}

/**
 * Extract values from EXIF data into container
 *
 * Returns:
 *  true  - successfully extracted all values
 *  false - error occurred, container unchanged
 */
template <typename T, bool littleEndian, typename Container>
bool extract_data(Container &container, const unsigned char *buffer,
                  const unsigned base, const unsigned total_len,
                  const IFDItem &item) {
  const unsigned char *data_ptr;
  uint32_t temp_data;

  // If data fits in 4 bytes, it's stored directly in the item
  if (sizeof(T) * item.size() <= 4) {
    if (littleEndian) {
      temp_data = item.offset();
    } else {
      temp_data = item.offset();
      // Byte swap for big-endian
      unsigned char *temp = reinterpret_cast<unsigned char *>(&temp_data);
      unsigned char swap_temp;
      swap_temp = temp[0];
      temp[0] = temp[3];
      temp[3] = swap_temp;
      swap_temp = temp[1];
      temp[1] = temp[2];
      temp[2] = swap_temp;
    }
    data_ptr = reinterpret_cast<const unsigned char *>(&temp_data);
  } else {
    data_ptr = buffer + base + item.offset();
    if (data_ptr + sizeof(T) * item.size() > buffer + total_len) {
      return false;
    }
  }

  container.resize(item.size());
  for (size_t idx = 0; idx < item.size(); ++idx) {
    container[idx] = read_value<T, littleEndian>(data_ptr + sizeof(T) * idx);
  }
  return true;
}

// Parse IFD header information
template <bool littleEndian>
void parse_header(const unsigned char *buffer, unsigned short &tag,
                  unsigned short &format, unsigned &count, unsigned &offset) {
  tag = read_value<uint16_t, littleEndian>(buffer);
  format = read_value<uint16_t, littleEndian>(buffer + 2);
  count = read_value<uint32_t, littleEndian>(buffer + 4);
  offset = read_value<uint32_t, littleEndian>(buffer + 8);
}

template <bool littleEndian>
void parse_header(const unsigned char *buffer, IFDItem &result) {
  unsigned short tag, format;
  unsigned count, offset;
  parse_header<littleEndian>(buffer, tag, format, count, offset);
  result.id(tag);
  result.set_type(format);
  result.size(count);
  result.offset(offset);
}

template <bool littleEndian>
IFDItem parse_item_temp(const unsigned char *buffer, const unsigned offset,
                        const unsigned base, const unsigned total_len) {
  IFDItem result;
  // Check buffer bounds
  if (buffer + offset + 12 > buffer + total_len) {
    result.id(0xFF);
    return result;
  }

  parse_header<littleEndian>(buffer + offset, result);

  // Process based on data type
  switch (result.type()) {
    case 1:  // BYTE
      if (!extract_data<uint8_t, littleEndian>(result.bytes(), buffer, base,
                                               total_len, result)) {
        result.id(0xFF);
      }
      break;
    case 2:  // ASCII
      if (!extract_data<uint8_t, littleEndian>(result.text(), buffer, base,
                                               total_len, result)) {
        result.id(0xFF);
      }
      // Remove trailing null byte
      if (!result.text().empty() && result.text()[result.text().length()-1] == '\0') {
        result.text().resize(result.text().length() - 1);
      }
      break;
    case 3:  // SHORT
      if (!extract_data<uint16_t, littleEndian>(result.words(), buffer, base,
                                                total_len, result)) {
        result.id(0xFF);
      }
      break;
    case 4:  // LONG
      if (!extract_data<uint32_t, littleEndian>(result.dwords(), buffer, base,
                                                total_len, result)) {
        result.id(0xFF);
      }
      break;
    case 5:  // RATIONAL
      if (!extract_data<FractionData, littleEndian>(result.fractions(), buffer,
                                                    base, total_len, result)) {
        result.id(0xFF);
      }
      break;
    case 7:  // UNDEFINED
    case 9:  // SLONG
    case 10:  // SRATIONAL
      break;
    default:
      result.id(0xFF);
  }
  return result;
}

// Convenience wrapper for value parsing
template <typename T>
T read_single(const unsigned char *buffer, bool littleEndian) {
  if (littleEndian) {
    return read_value<T, true>(buffer);
  } else {
    return read_value<T, false>(buffer);
  }
}

// Wrapper for header parsing
void parse_header(const unsigned char *buffer, bool littleEndian,
                  unsigned short &tag, unsigned short &format,
                  unsigned &count, unsigned &offset) {
  if (littleEndian) {
    parse_header<true>(buffer, tag, format, count, offset);
  } else {
    parse_header<false>(buffer, tag, format, count, offset);
  }
}

// Main entry point for parsing an IFD item
IFDItem parse_item(const unsigned char *buffer, const unsigned offset,
                   const bool littleEndian, const unsigned base,
                   const unsigned total_len) {
  if (littleEndian) {
    return parse_item_temp<true>(buffer, offset, base, total_len);
  } else {
    return parse_item_temp<false>(buffer, offset, base, total_len);
  }
}
}

//
// Main EXIF parsing function - locates EXIF segment and processes it
//
int easyexif::EXIFInfo::parse_from_buffer(const unsigned char *buffer, unsigned length) {
  // Verify JPEG signature
  if (!buffer || length < 4) return PARSE_EXIF_ERROR_NO_JPEG;
  if (buffer[0] != 0xFF || buffer[1] != 0xD8) return PARSE_EXIF_ERROR_NO_JPEG;

  // Handle padding at end of JPEG
  while (length > 2) {
    if (buffer[length - 1] == 0xD9 && buffer[length - 2] == 0xFF)
      break;
    length--;
  }
  if (length <= 2)
    return PARSE_EXIF_ERROR_NO_JPEG;

  clear();

  // Find EXIF marker (0xFFE1)
  unsigned position = 0;
  for (position = 0; position < length - 1; position++)
    if (buffer[position] == 0xFF && buffer[position + 1] == 0xE1) break;

  if (position + 4 > length) return PARSE_EXIF_ERROR_NO_EXIF;
  position += 2;

  // Read section length (big-endian)
  unsigned short section_length = read_single<uint16_t>(buffer + position, false);
  if (position + section_length > length || section_length < 16)
    return PARSE_EXIF_ERROR_CORRUPT;

  position += 2;
  return parse_from_exif_segment(buffer + position, length - position);
}

int easyexif::EXIFInfo::parse_from_string(const string &data) {
  return parse_from_buffer(
      reinterpret_cast<const unsigned char *>(data.data()), 
      static_cast<unsigned>(data.length()));
}

//
// Core EXIF segment parsing
//
int easyexif::EXIFInfo::parse_from_exif_segment(const unsigned char *buffer,
                                                unsigned length) {
  bool littleEndian = true;  // Default to Intel byte order
  unsigned position = 0;

  // Validate EXIF header
  if (!buffer || length < 6) return PARSE_EXIF_ERROR_NO_EXIF;
  if (!std::equal(buffer, buffer + 6, "Exif\0\0")) 
    return PARSE_EXIF_ERROR_NO_EXIF;

  position += 6;

  // Parse TIFF header
  if (position + 8 > length) return PARSE_EXIF_ERROR_CORRUPT;
  unsigned tiff_start = position;

  if (buffer[position] == 'I' && buffer[position + 1] == 'I')
    littleEndian = true;
  else if (buffer[position] == 'M' && buffer[position + 1] == 'M')
    littleEndian = false;
  else
    return PARSE_EXIF_ERROR_UNKNOWN_BYTEALIGN;

  this->ByteAlign = littleEndian;
  position += 2;

  if (0x2a != read_single<uint16_t>(buffer + position, littleEndian))
    return PARSE_EXIF_ERROR_CORRUPT;
  position += 2;

  unsigned first_ifd = read_single<uint32_t>(buffer + position, littleEndian);
  position += first_ifd - 4;
  if (position >= length) return PARSE_EXIF_ERROR_CORRUPT;

  // Parse IFD0
  if (position + 2 > length) return PARSE_EXIF_ERROR_CORRUPT;
  int entry_count = read_single<uint16_t>(buffer + position, littleEndian);
  if (position + 6 + 12 * entry_count > length) return PARSE_EXIF_ERROR_CORRUPT;
  position += 2;

  unsigned exif_sub_ifd = length;
  unsigned gps_sub_ifd = length;

  while (--entry_count >= 0) {
    IFDItem item = parse_item(buffer, position, littleEndian, tiff_start, length);
    position += 12;

    switch (item.id()) {
      case 0x102:  // Bits per sample
        if (item.type() == 3 && !item.words().empty())
          this->BitsPerSample = item.words().front();
        break;
      case 0x10E:  // Image description
        if (item.type() == 2) this->ImageDescription = item.text();
        break;
      case 0x10F:  // Camera make
        if (item.type() == 2) this->Make = item.text();
        break;
      case 0x110:  // Camera model
        if (item.type() == 2) this->Model = item.text();
        break;
      case 0x112:  // Orientation
        if (item.type() == 3 && !item.words().empty())
          this->Orientation = item.words().front();
        break;
      case 0x131:  // Software
        if (item.type() == 2) this->Software = item.text();
        break;
      case 0x132:  // Date/time
        if (item.type() == 2) this->DateTime = item.text();
        break;
      case 0x8298:  // Copyright
        [redacted]
        break;
      case 0x8825:  // GPS IFD offset
        gps_sub_ifd = tiff_start + item.offset();
        break;
      case 0x8769:  // EXIF SubIFD offset
        exif_sub_ifd = tiff_start + item.offset();
        break;
    }
  }

  // Parse EXIF SubIFD
  if (exif_sub_ifd + 4 <= length) {
    position = exif_sub_ifd;
    int sub_count = read_single<uint16_t>(buffer + position, littleEndian);
    if (position + 6 + 12 * sub_count > length) return PARSE_EXIF_ERROR_CORRUPT;
    position += 2;

    while (--sub_count >= 0) {
      IFDItem item = parse_item(buffer, position, littleEndian, tiff_start, length);

      switch (item.id()) {
        case 0x829a:  // Exposure time
          if (item.type() == 5 && !item.fractions().empty())
            this->ExposureTime = item.fractions().front();
          break;
        case 0x829d:  // F-number
          if (item.type() == 5 && !item.fractions().empty())
            this->FNumber = item.fractions().front();
          break;
        case 0x8822:  // Exposure program
          if (item.type() == 3 && !item.words().empty())
            this->ExposureProgram = item.words().front();
          break;
        case 0x8827:  // ISO speed
          if (item.type() == 3 && !item.words().empty())
            this->ISOSpeedRatings = item.words().front();
          break;
        case 0x9003:  // Original date/time
          if (item.type() == 2)
            this->DateTimeOriginal = item.text();
          break;
        case 0x9004:  // Digitization date/time
          if (item.type() == 2)
            this->DateTimeDigitized = item.text();
          break;
        case 0x9201:  // Shutter speed
          if (item.type() == 5 && !item.fractions().empty())
            this->ShutterSpeedValue = item.fractions().front();
          break;
        case 0x9204:  // Exposure bias
          if (item.type() == 5 && !item.fractions().empty())
            this->ExposureBiasValue = item.fractions().front();
          break;
        case 0x9206:  // Subject distance
          if (item.type() == 5 && !item.fractions().empty())
            this->SubjectDistance = item.fractions().front();
          break;
        case 0x9209:  // Flash
          if (item.type() == 3 && !item.words().empty()) {
            uint16_t flash_data = item.words().front();
            this->Flash = flash_data & 1;
            this->FlashReturnedLight = (flash_data & 6) >> 1;
            this->FlashMode = (flash_data & 24) >> 3;
          }
          break;
        case 0x920a:  // Focal length
          if (item.type() == 5 && !item.fractions().empty())
            this->FocalLength = item.fractions().front();
          break;
        case 0xa405:  // Focal length in 35mm
          if (item.type() == 3 && !item.words().empty())
              this->LensInfo.FocalLengthIn35mm = item.words().front();
          break;
        case 0x9207:  // Metering mode
          if (item.type() == 3 && !item.words().empty())
            this->MeteringMode = item.words().front();
          break;
        case 0x9291:  // Subsecond original
          if (item.type() == 2)
            this->SubSecTimeOriginal = item.text();
          break;
        case 0xa001:  // Color space
          if (item.type() == 3 && !item.words().empty())
            this->ColorSpace = item.words().front();
          break;
        case 0xa002:  // Image width
          if (item.type() == 4 && !item.dwords().empty())
            this->ImageWidth = item.dwords().front();
          if (item.type() == 3 && !item.words().empty())
            this->ImageWidth = item.words().front();
          break;
        case 0xa003:  // Image height
          if (item.type() == 4 && !item.dwords().empty())
            this->ImageHeight = item.dwords().front();
          if (item.type() == 3 && !item.words().empty())
            this->ImageHeight = item.words().front();
          break;
        case 0xa20e:  // Focal plane X resolution
          if (item.type() == 5 && !item.fractions().empty()) {
            this->LensInfo.FocalPlaneXResolution = item.fractions()[0];
          }
          break;
        case 0xa20f:  // Focal plane Y resolution
          if (item.type() == 5 && !item.fractions().empty()) {
            this->LensInfo.FocalPlaneYResolution = item.fractions()[0];
          }
          break;
        case 0xa210:  // Focal plane resolution unit
          if (item.type() == 3 && !item.words().empty()) {
              this->LensInfo.FocalPlaneResolutionUnit = item.words().front();
          }
          break;
        case 0xa432:  // Lens info
          if (item.type() == 5) {
            int sz = static_cast<unsigned>(item.fractions().size());
            if (sz)
              this->LensInfo.FocalLengthMin = item.fractions()[0];
            if (sz > 1)
              this->LensInfo.FocalLengthMax = item.fractions()[1];
            if (sz > 2)
              this->LensInfo.FStopMin = item.fractions()[2];
            if (sz > 3)
              this->LensInfo.FStopMax = item.fractions()[3];
          }
          break;
        case 0xa433:  // Lens make
          if (item.type() == 2) {
            this->LensInfo.Make = item.text();
          }
          break;
        case 0xa434:  // Lens model
          if (item.type() == 2) {
            this->LensInfo.Model = item.text();
          }
          break;
      }
      position += 12;
    }
  }

  // Parse GPS IFD
  if (gps_sub_ifd + 4 <= length) {
    position = gps_sub_ifd;
    int gps_count = read_single<uint16_t>(buffer + position, littleEndian);
    if (position + 6 + 12 * gps_count > length) return PARSE_EXIF_ERROR_CORRUPT;
    position += 2;

    while (--gps_count >= 0) {
      unsigned short tag, fmt;
      unsigned cnt, off;
      parse_header(buffer + position, littleEndian, tag, fmt, cnt, off);

      switch (tag) {
        case 1:  // GPS direction (N/S)
          this->GeoLocation.LatComponents.direction = *(buffer + position + 8);
          if (this->GeoLocation.LatComponents.direction == 0)
            this->GeoLocation.LatComponents.direction = '?';
          if ('S' == this->GeoLocation.LatComponents.direction)
            this->GeoLocation.Latitude = -this->GeoLocation.Latitude;
          break;
        case 2:  // Latitude
          if ((fmt == 5 || fmt == 10) && cnt == 3) {
            this->GeoLocation.LatComponents.degrees = read_single<Rational>(
                buffer + off + tiff_start, littleEndian);
            this->GeoLocation.LatComponents.minutes = read_single<Rational>(
                buffer + off + tiff_start + 8, littleEndian);
            this->GeoLocation.LatComponents.seconds = read_single<Rational>(
                buffer + off + tiff_start + 16, littleEndian);
            this->GeoLocation.Latitude =
                this->GeoLocation.LatComponents.degrees +
                this->GeoLocation.LatComponents.minutes / 60 +
                this->GeoLocation.LatComponents.seconds / 3600;
            if ('S' == this->GeoLocation.LatComponents.direction)
              this->GeoLocation.Latitude = -this->GeoLocation.Latitude;
          }
          break;
        case 3:  // GPS direction (E/W)
          this->GeoLocation.LonComponents.direction = *(buffer + position + 8);
          if (this->GeoLocation.LonComponents.direction == 0)
            this->GeoLocation.LonComponents.direction = '?';
          if ('W' == this->GeoLocation.LonComponents.direction)
            this->GeoLocation.Longitude = -this->GeoLocation.Longitude;
          break;
        case 4:  // Longitude
          if ((fmt == 5 || fmt == 10) && cnt == 3) {
            this->GeoLocation.LonComponents.degrees = read_single<Rational>(
                buffer + off + tiff_start, littleEndian);
            this->GeoLocation.LonComponents.minutes = read_single<Rational>(
                buffer + off + tiff_start + 8, littleEndian);
            this->GeoLocation.LonComponents.seconds = read_single<Rational>(
                buffer + off + tiff_start + 16, littleEndian);
            this->GeoLocation.Longitude =
                this->GeoLocation.LonComponents.degrees +
                this->GeoLocation.LonComponents.minutes / 60 +
                this->GeoLocation.LonComponents.seconds / 3600;
            if ('W' == this->GeoLocation.LonComponents.direction)
              this->GeoLocation.Longitude = -this->GeoLocation.Longitude;
          }
          break;
        case 5:  // Altitude reference
          this->GeoLocation.AltitudeRef = *(buffer + position + 8);
          if (1 == this->GeoLocation.AltitudeRef)
            this->GeoLocation.Altitude = -this->GeoLocation.Altitude;
          break;
        case 6:  // Altitude
          if (fmt == 5 || fmt == 10) {
            this->GeoLocation.Altitude = read_single<Rational>(
                buffer + off + tiff_start, littleEndian);
            if (1 == this->GeoLocation.AltitudeRef)
              this->GeoLocation.Altitude = -this->GeoLocation.Altitude;
          }
          break;
        case 11:  // DOP
          if (fmt == 5 || fmt == 10) {
            this->GeoLocation.DOP = read_single<Rational>(
                buffer + off + tiff_start, littleEndian);
          }
          break;
      }
      position += 12;
    }
  }
  return PARSE_EXIF_SUCCESS;
}

void easyexif::EXIFInfo::reset() {
  // Reset strings
  ImageDescription = "";
  Make = "";
  Model = "";
  Software = "";
  DateTime = "";
  DateTimeOriginal = "";
  DateTimeDigitized = "";
  SubSecTimeOriginal = "";
  Copyright [redacted]

  // Reset numeric fields
  ByteAlign = 0;
  Orientation = 0;
  BitsPerSample = 0;
  ExposureTime = 0;
  FNumber = 0;
  ExposureProgram = 0;
  ISOSpeedRatings = 0;
  ShutterSpeedValue = 0;
  ExposureBiasValue = 0;
  SubjectDistance = 0;
  FocalLength = 0;
  FocalLengthIn35mm = 0;
  Flash = 0;
  FlashReturnedLight = 0;
  FlashMode = 0;
  MeteringMode = 0;
  ColorSpace = 0;
  ImageWidth = 0;
  ImageHeight = 0;

  // Reset geolocation
  GeoLocation.Latitude = 0;
  GeoLocation.Longitude = 0;
  GeoLocation.Altitude = 0;
  GeoLocation.AltitudeRef = 0;
  GeoLocation.DOP = 0;
  GeoLocation.LatComponents.degrees = 0;
  GeoLocation.LatComponents.minutes = 0;
  GeoLocation.LatComponents.seconds = 0;
  GeoLocation.LatComponents.direction = '?';
  GeoLocation.LonComponents.degrees = 0;
  GeoLocation.LonComponents.minutes = 0;
  GeoLocation.LonComponents.seconds = 0;
  GeoLocation.LonComponents.direction = '?';

  // Reset lens info
  LensInfo.FocalLengthMax = 0;
  LensInfo.FocalLengthMin = 0;
  LensInfo.FStopMax = 0;
  LensInfo.FStopMin = 0;
  LensInfo.FocalPlaneYResolution = 0;
  LensInfo.FocalPlaneXResolution = 0;
  LensInfo.FocalPlaneResolutionUnit = 0;
  LensInfo.Make = "";
  LensInfo.Model = "";
}

