#include <OTwo/UI/Playing/ComboCounter.hpp>
#include <OTwo/States/State.hpp>
#include <Genode/Tasks/Action.hpp>
#include <Genode/Tasks/Scheduler.hpp>
#include <Genode/Tween/Move.hpp>

ComboCounter::ComboCounter(Gx::Animation* title, Gx::BitmapNumber* digits) :
    m_title(title),
    m_digits(digits)
{
    if (m_title)
        AddChild(*m_title);
    if (m_digits)
        AddChild(*m_digits);
}

void ComboCounter::Initialize()
{
    Gx::Node::Initialize();
    SetPosition(sf::Vector2f(0.f, -6.f));
    m_animSeq = Gx::Sequence([this]
        {
            if (m_title)
                m_title->Stop();
            SetVisible(false);
        },
        Gx::TaskGroup
        (
            Gx::Action([this]
            {
                if (m_title)
                    m_title->Reset();
                SetVisible(true);
            }),
            Gx::Move(*m_title, sf::Vector2f(m_title->GetPosition().x, m_title->GetPosition().y - 8.f), sf::seconds(1.f / 60.f * 5)),
            Gx::Move(*m_digits, sf::Vector2f(m_digits->GetPosition().x, m_digits->GetPosition().y - 23.f), sf::seconds(1.f / 60.f * 5))
        ),
        Gx::Delay(sf::milliseconds(1000))
    );
    // Pre-record initial transform state
    m_animSeq.Update(0);
    m_animSeq.Stop();
    SetVisible(false);
}

unsigned int ComboCounter::GetCurrentCombo() const
{
    if (m_digits)
        return m_digits->GetValue();
    return 0;
}

void ComboCounter::SetCurrentCombo(const unsigned int value)
{
    if (m_digits)
        m_digits->SetValue(value);
    if (value != 0u)
    {
        SetVisible(true);
        m_animSeq.Reset();
    }
    else
    {
        SetVisible(false);
        m_animSeq.Complete();
    }
}

void ComboCounter::Update(const double elapsed)
{
    m_animSeq.Update(elapsed);
    Gx::UpdatableContainer::Update(elapsed);
}

Gx::RenderStates ComboCounter::Render(Gx::RenderSurface& target, Gx::RenderStates ctx) const
{
    if (!IsVisible())
        return ctx;
    ctx.transform *= GetTransform();
    if (m_title)
        target.Render(*m_title, ctx);
    if (m_digits)
        target.Render(*m_digits, ctx);
    return ctx;
}

