//----------------------------------------------------------------------//
//  FGameplayDebuggerCategory_4ML
//----------------------------------------------------------------------//
FGameplayDebuggerCategory_4ML::FGameplayDebuggerCategory_4ML()
{
	SelectedAgentID = F4ML::InvalidAgentID;
	TrackedDebugActor = nullptr;
	bOnlyDisplayWhenDebugActorPresent = false;

	BindKeyPress(EKeys::RightBracket.GetFName(), FGameplayDebuggerInputModifier::Shift, this, &FGameplayDebuggerCategory_4ML::OnCycleToNextAgent, EGameplayDebuggerInputMode::Replicated);
	BindKeyPress(EKeys::LeftBracket.GetFName(), FGameplayDebuggerInputModifier::Shift, this, &FGameplayDebuggerCategory_4ML::OnRefreshAvatarInfo, EGameplayDebuggerInputMode::Replicated);
	BindKeyPress(EKeys::P.GetFName(), FGameplayDebuggerInputModifier::Shift, this, &FGameplayDebuggerCategory_4ML::OnAssignCurrentAvatarAsDebugTarget, EGameplayDebuggerInputMode::Replicated);
}
void FGameplayDebuggerCategory_4ML::Initialize()
{
	U4MLManager::Get().GetOnCurrentSessionChanged().AddSP(this, &FGameplayDebuggerCategory_4ML::OnSessionChanged);
	if (U4MLManager::Get().HasSession())
	{
		OnSessionChanged();
	}
}
void FGameplayDebuggerCategory_4ML::ClearProperties()
{
	SelectedAgentID = F4ML::InvalidAgentID;
	TrackedDebugActor = nullptr;
}
TSharedRef<FGameplayDebuggerCategory> FGameplayDebuggerCategory_4ML::CreateInstance()
{
	FGameplayDebuggerCategory_4ML* NewInstance = new FGameplayDebuggerCategory_4ML();
	TSharedRef<FGameplayDebuggerCategory> InstanceRef = MakeShareable(NewInstance);
	if (U4MLManager::IsReady())
	{
		NewInstance->Initialize();
	}
	else
	{
		U4MLManager::OnPostInit.AddSP(NewInstance, &FGameplayDebuggerCategory_4ML::Initialize);
	}
	return InstanceRef;
}
void FGameplayDebuggerCategory_4ML::GatherData(APlayerController* OwnerPC, AActor* DebugTarget)
{
	if (U4MLManager::Get().HasSession() == false)
	{
		AddTextLine(TEXT("{red}No active session"));
		return;
	}
	U4MLSession& ActiveSession = U4MLManager::Get().GetSession();
	const U4MLAgent* FoundAgent = nullptr;
	if (TrackedDebugActor != DebugTarget)
	{
		TrackedDebugActor = DebugTarget;
		if (DebugTarget)
		{
			FoundAgent = ActiveSession.FindAgentByAvatar(*DebugTarget);
		}
		SelectedAgentID = FoundAgent ? FoundAgent->GetAgentID() : F4ML::InvalidAgentID;
	}
	if (SelectedAgentID != F4ML::InvalidAgentID && FoundAgent == nullptr)
	{
		FoundAgent = ActiveSession.GetAgent(SelectedAgentID);
		ensureMsgf(FoundAgent, TEXT("Retrieved null agent despite valid AgentID"));
	}
	ActiveSession.DescribeSelfToGameplayDebugger(*this);
	AddTextLine(FString::Printf(TEXT("{DimGrey}---------------------")));
	if (FoundAgent)
	{
		FoundAgent->DescribeSelfToGameplayDebugger(*this);
	}
	else if (SelectedAgentID != F4ML::InvalidAgentID)
	{
		AddTextLine(FString::Printf(TEXT("{orange}Agent %d lacks an avatar"), SelectedAgentID));
	}
	else
	{
		AddTextLine(FString::Printf(TEXT("{orange}No agent currently selected"), SelectedAgentID));
	}
}
void FGameplayDebuggerCategory_4ML::RenderData(APlayerController* OwnerPC, FGameplayDebuggerCanvasContext& CanvasContext)
{
	CanvasContext.Printf(TEXT("\n[{yellow}%s{white}] Next agent"), *GetInputHandlerDescription(0));
	CanvasContext.Printf(TEXT("[{yellow}%s{white}] Refresh avatar"), *GetInputHandlerDescription(1));
	CanvasContext.Printf(TEXT("[{yellow}%s{white}] Set current avatar as debug target"), *GetInputHandlerDescription(2));
	FGameplayDebuggerCategory::RenderData(OwnerPC, CanvasContext);
}
void FGameplayDebuggerCategory_4ML::OnCycleToNextAgent()
{
	TrackedDebugActor = nullptr;
	// should get called on Authority
	if (U4MLManager::Get().HasSession())
	{
		SelectedAgentID = U4MLManager::Get().GetSession().GetNextAgentID(SelectedAgentID);
		if (SelectedAgentID != F4ML::InvalidAgentID)
		{
			const U4MLAgent* Agent = U4MLManager::Get().GetSession().GetAgent(SelectedAgentID);
			if (ensure(Agent) && Agent->GetAvatar())
			{
				AGameplayDebuggerCategoryReplicator* Replicator = GetReplicator();
				if (ensure(Replicator))
				{
					Replicator->SetDebugActor(Agent->GetAvatar());
				}
			}
		}
	}
}
void FGameplayDebuggerCategory_4ML::OnRefreshAvatarInfo()
{
	if (U4MLManager::Get().HasSession() && SelectedAgentID != F4ML::InvalidAgentID)
	{
		U4MLManager::Get().GetSession().RequestAvatarForAgent(SelectedAgentID);
	}
}
void FGameplayDebuggerCategory_4ML::OnAssignCurrentAvatarAsDebugTarget()
{
	if (SelectedAgentID != F4ML::InvalidAgentID && U4MLManager::Get().HasSession())
	{
		const U4MLAgent* Agent = U4MLManager::Get().GetSession().GetAgent(SelectedAgentID);
		if (ensure(Agent) && Agent->GetAvatar())
		{
			AGameplayDebuggerCategoryReplicator* Replicator = GetReplicator();
			if (ensure(Replicator))
			{
				Replicator->SetDebugActor(Agent->GetAvatar());
			}
		}
	}
}
void FGameplayDebuggerCategory_4ML::OnSessionChanged()
{
	if (U4MLManager::Get().HasSession())
	{
		U4MLManager::Get().GetSession().GetOnAgentAvatarChanged().AddSP(this, &FGameplayDebuggerCategory_4ML::OnAvatarUpdated);
		U4MLManager::Get().GetSession().GetOnBeginAgentRemove().AddSP(this, &FGameplayDebuggerCategory_4ML::OnAgentRemoved);
	}
	else
	{
		ClearProperties();
	}
}
void FGameplayDebuggerCategory_4ML::OnAvatarUpdated(U4MLAgent& Agent, AActor* PreviousAvatar)
{
	if (Agent.GetAgentID() == SelectedAgentID)
	{
		// pass
	}
}
void FGameplayDebuggerCategory_4ML::OnAgentRemoved(U4MLAgent& Agent)
{
	if (Agent.GetAgentID() == SelectedAgentID)
	{
		ClearProperties();
	}
}
