    // Repack trim curves into Maya format
    void repackTrimCurves( Alembic::AbcGeom::INuPatchSchema::Sample & samp,
        MFnNurbsSurface & surfaceFn )
    {
        Alembic::Util::int32_t numLoops = samp.getTrimNumLoops();
        if (numLoops == 0)
            return;

        MTrimBoundaryArray boundaryArray;

        double uMin, uMax, vMin, vMax;
        surfaceFn.getKnotDomain(uMin, uMax, vMin, vMax);
        double vOffset = vMin + vMax;

        Alembic::Abc::Int32ArraySamplePtr loopsCount =
            samp.getTrimNumCurves();
        Alembic::Abc::Int32ArraySamplePtr vertsPerCurve =
            samp.getTrimNumVertices();
        Alembic::Abc::Int32ArraySamplePtr curveOrders =
            samp.getTrimOrders();
        Alembic::Abc::FloatArraySamplePtr knotSeqs =
            samp.getTrimKnots();
        Alembic::Abc::FloatArraySamplePtr uCoords =
            samp.getTrimU();
        Alembic::Abc::FloatArraySamplePtr vCoords =
            samp.getTrimV();
        Alembic::Abc::FloatArraySamplePtr wCoords =
            samp.getTrimW();

        Alembic::Util::int32_t curveIdx = 0;
        Alembic::Util::int32_t posIdx   = 0;
        Alembic::Util::int32_t knotIdx  = 0;

        for (Alembic::Util::int32_t loop = 0; loop < numLoops; ++loop)
        {
            MObjectArray curveLoop;
            Alembic::Util::int32_t numCurvesInLoop = (*loopsCount)[loop];
            for (Alembic::Util::int32_t c = 0; c < numCurvesInLoop; ++c, ++curveIdx)
            {
                unsigned int order = (*curveOrders)[curveIdx];
                unsigned int degree = (order > 0) ? order - 1 : 0;
                Alembic::Util::int32_t numPoints = (*vertsPerCurve)[curveIdx];
                Alembic::Util::int32_t numKnots = numPoints + degree + 1;

                MPointArray cvs;
                cvs.setLength(numPoints);

                for (Alembic::Util::int32_t p = 0; p < numPoints; ++p, ++posIdx)
                {
                    double xu = (*uCoords)[posIdx];
                    double yv = (*vCoords)[posIdx];
                    double ww = (*wCoords)[posIdx];
                    cvs.set(p, xu, vOffset - yv, 0.0, ww);
                }

                MDoubleArray knots;
                knots.setLength(numKnots - 2);
                ++knotIdx;
                for (Alembic::Util::int32_t k = 1; k < numKnots - 1; ++k, ++knotIdx)
                {
                    knots.set((*knotSeqs)[knotIdx], k - 1);
                }
                ++knotIdx;

                MFnNurbsCurve fnCurve;
                MFnNurbsCurveData data;
                MObject curveDataObj = data.create();
                MObject curveObj = fnCurve.create(cvs, knots, degree,
                    MFnNurbsCurve::kOpen, true, true, curveDataObj);
                if (curveObj != MObject::kNullObj)
                {
                    curveLoop.append(curveDataObj);
                }
            }
            boundaryArray.append(curveLoop);
        }

        MTrimBoundaryArray currentRegion;
        for (unsigned int i = 0; i < boundaryArray.length(); ++i)
        {
            if (i > 0)
            {
                MStatus stat;
                MObject merged = boundaryArray.getMergedBoundary(i, &stat);
                if (stat != MS::kSuccess) continue;

                MFnNurbsCurve loopFn(merged, &stat);
                if (stat != MS::kSuccess) continue;

                bool outer = false;
                double totalLen = loopFn.length();
                unsigned int samples = std::max(loopFn.numCVs(), 10u);
                MPointArray samplePts;
                samplePts.setLength(samples);

                for (unsigned int s = 0; s < samples; ++s)
                {
                    double param = loopFn.findParamFromLength(totalLen * s / samples);
                    loopFn.getPointAtParam(param, samplePts[s]);
                }

                MPoint extremeRight = samplePts[0];
                unsigned int rightIdx = 0;
                for (unsigned int s = 0; s < samplePts.length(); ++s)
                {
                    if (extremeRight.x < samplePts[s].x)
                    {
                        extremeRight = samplePts[s];
                        rightIdx = s;
                    }
                }

                int prevIdx = (rightIdx == 0) ? samplePts.length() - 1 : rightIdx - 1;
                int nextIdx = (rightIdx == samplePts.length() - 1) ? 0 : rightIdx + 1;

                for (unsigned int s = 0; s < samplePts.length(); ++s)
                {
                    if (fabs(samplePts[prevIdx].x - extremeRight.x) < 1e-5)
                    {
                        prevIdx = (prevIdx == 0) ? samplePts.length() - 1 : prevIdx - 1;
                    }
                }

                for (unsigned int s = 0; s < samplePts.length(); ++s)
                {
                    if (fabs(samplePts[nextIdx].x - extremeRight.x) < 1e-5)
                    {
                        nextIdx = (nextIdx == (int)(samplePts.length()) - 1) ? 0 : nextIdx + 1;
                    }
                }

                if (fabs(samplePts[nextIdx].x - extremeRight.x) < 1e-5 &&
                    fabs(samplePts[prevIdx].x - extremeRight.x) < 1e-5)
                {
                    continue;
                }

                if (prevIdx < 0) prevIdx += samplePts.length();
                if (prevIdx >= (int)(samplePts.length())) prevIdx &= (samplePts.length() - 1);
                if (nextIdx < 0) nextIdx += samplePts.length();
                if (nextIdx >= (int)(samplePts.length())) nextIdx &= (samplePts.length() - 1);

                MVector dir1 = samplePts[prevIdx] - extremeRight;
                MVector dir2 = samplePts[nextIdx] - extremeRight;
                if ((dir1 ^ dir2).z < 0.0)
                {
                    outer = true;
                }

                if (outer)
                {
#if MAYA_API_VERSION < 201300
                    stat = surfaceFn.trimWithBoundaries(currentRegion);
#else
                    stat = surfaceFn.trimWithBoundaries(currentRegion, false, 1e-3, 1e-5, true);
#endif
                    if (stat != MS::kSuccess)
                    {
                        MGlobal::displayError("Failed to trim outer boundary.");
                    }
                    currentRegion.clear();
                }
            }
            currentRegion.append(boundaryArray[i]);
        }

#if MAYA_API_VERSION < 201300
        MStatus stat = surfaceFn.trimWithBoundaries(currentRegion);
#else
        MStatus stat = surfaceFn.trimWithBoundaries(currentRegion, false, 1e-3, 1e-5, true);
#endif
        if (stat != MS::kSuccess)
        {
            MGlobal::displayError("Surface trimming failed.");
        }
    }
}

MObject buildNurbsSurface(double timeVal, Alembic::AbcGeom::INuPatch & node,
    MObject & parentObj)
{
    MStatus status;
    MObject result;

    Alembic::AbcGeom::INuPatchSchema schema = node.getSchema();
    Alembic::AbcCoreAbstract::index_t idx, ceilIdx;
    getWeightAndIndex(timeVal, schema.getTimeSampling(),
        schema.getNumSamples(), idx, ceilIdx);

    Alembic::AbcGeom::INuPatchSchema::Sample sample;
    schema.get(sample, Alembic::Abc::ISampleSelector(idx));

    Alembic::Abc::P3fArraySamplePtr positions = sample.getPositions();
    Alembic::Abc::FloatArraySamplePtr weights = sample.getPositionWeights();

    MString name(node.getName().c_str());
    unsigned int orderU = sample.getUOrder();
    unsigned int orderV = sample.getVOrder();
    unsigned int degreeU = (orderU > 0) ? orderU - 1 : 0;
    unsigned int degreeV = (orderV > 0) ? orderV - 1 : 0;
    unsigned int countU = sample.getNumU();
    unsigned int countV = sample.getNumV();
    unsigned int totalCVs = countU * countV;

    MPointArray cvs;
    cvs.setLength(totalCVs);

    unsigned int flatIdx = 0;
    for (unsigned int v = 0; v < countV; ++v)
    {
        for (unsigned int u = 0; u < countU; ++u, ++flatIdx)
        {
            unsigned int mayaIdx = u * countV + (countV - v - 1);
            MPoint pt((*positions)[flatIdx].x,
                      (*positions)[flatIdx].y,
                      (*positions)[flatIdx].z);
            if (weights)
            {
                pt.w = (*weights)[flatIdx];
            }
            cvs.set(pt, mayaIdx);
        }
    }

    MFnNurbsSurface::Form formU = MFnNurbsSurface::kPeriodic;
    MFnNurbsSurface::Form formV = MFnNurbsSurface::kPeriodic;

    bool closedU = true;
    for (unsigned int v = 0; closedU && v < countV; ++v)
    {
        for (unsigned int u = 0; u < degreeU; ++u)
        {
            unsigned int first = u * countV + (countV - v - 1);
            unsigned int lastPeriodic = (countU - degreeU + u) * countV + (countV - v - 1);
            if (!cvs[first].isEquivalent(cvs[lastPeriodic]))
            {
                formU = MFnNurbsSurface::kOpen;
                closedU = false;
                break;
            }
        }
    }

    if (formU == MFnNurbsSurface::kOpen)
    {
        formU = MFnNurbsSurface::kClosed;
        for (unsigned int v = 0; v < countV; ++v)
        {
            unsigned int lastU = (countU - 1) * countV + (countV - v - 1);
            if (!cvs[countV - v - 1].isEquivalent(cvs[lastU]))
            {
                formU = MFnNurbsSurface::kOpen;
                break;
            }
        }
    }

    bool closedV = true;
    for (unsigned int u = 0; closedV && u < countU; ++u)
    {
        for (unsigned int v = 0; v < degreeV; ++v)
        {
            unsigned int first = u * countV + (countV - v - 1);
            unsigned int lastPeriodic = u * countV + (degreeV - v - 1);
            if (!cvs[first].isEquivalent(cvs[lastPeriodic]))
            {
                formV = MFnNurbsSurface::kOpen;
                closedV = false;
                break;
            }
        }
    }

    if (formV == MFnNurbsSurface::kOpen)
    {
        formV = MFnNurbsSurface::kClosed;
        for (unsigned int u = 0; u < countU; ++u)
        {
            if (!cvs[u * countV + (countV - 1)].isEquivalent(cvs[u * countV]))
            {
                formV = MFnNurbsSurface::kOpen;
                break;
            }
        }
    }

    Alembic::Abc::FloatArraySamplePtr uknots = sample.getUKnot();
    Alembic::Abc::FloatArraySamplePtr vknots = sample.getVKnot();

    unsigned int numUKnots = (uknots->size() > 2) ?
        static_cast<unsigned int>(uknots->size() - 2) : 0;
    MDoubleArray uKnots;
    uKnots.setLength(numUKnots);
    for (unsigned int i = 0; i < numUKnots; ++i)
    {
        uKnots.set((*uknots)[i+1], i);
    }

    unsigned int numVKnots = (vknots->size() > 2) ?
        static_cast<unsigned int>(vknots->size() - 2) : 0;
    MDoubleArray vKnots;
    vKnots.setLength(numVKnots);
    for (unsigned int i = 0; i < numVKnots; ++i)
    {
        vKnots.set((*vknots)[i+1], i);
    }

    MFnNurbsSurface fn;
    result = fn.create(cvs, uKnots, vKnots,
        degreeU, degreeV, formU, formV,
        true, parentObj, &status);

    if (status != MS::kSuccess &&
        (formU != MFnNurbsSurface::kOpen || formV != MFnNurbsSurface::kOpen))
    {
        result = fn.create(cvs, uKnots, vKnots,
            degreeU, degreeV, MFnNurbsSurface::kOpen, MFnNurbsSurface::kOpen,
            true, parentObj, &status);
    }

    if (status == MS::kSuccess)
    {
        fn.setName(name);
    }
    else
    {
        MGlobal::displayError(status.errorString());
        MString err = "Failed to create Nurbs Surface: ";
        err += name;
        MGlobal::displayError(err);
    }

    repackTrimCurves(sample, fn);
    return result;
}

MObject generateNurbs(double frameTime, Alembic::AbcGeom::INuPatch & node,
    MObject & parent)
{
    MObject obj = buildNurbsSurface(frameTime, node, parent);
    if (!obj.isNull())
    {
        MFnNurbsSurface fn(obj);
        setInitialShadingGroup(fn.partialPathName());
    }
    return obj;
}

#include "runsmap.h"
//---------------------------------------------------------------------------------------------
void RunsMap::setRunLength(TPixelGR8 *pixel, TUINT32 len) {
  TPixelGR8 *initialPixel = pixel;
  pixel                   = initialPixel;
  TPixelGR8 *endPixel     = pixel + len - 1;
  --len;
  if (len < 3)
    pixel->value = endPixel->value = (len << 6);
  else {
    pixel->value = endPixel->value = (3 << 6);
    ++pixel, --endPixel;
    if (len < 255)
      pixel->value = endPixel->value = len;
    else {
      pixel->value = endPixel->value = 255;
      ++pixel, endPixel -= 4;
      TUINT32 *lengthPtr = (TUINT32 *)pixel;
      *lengthPtr         = len;
    }
  }
  assert(runLength(initialPixel) == (len + 1));
}
//---------------------------------------------------------------------------------------------
TUINT32 RunsMap::runLength(const TPixelGR8 *pixel, bool reverse) const {
  int length = pixel->value >> 6;
  if (length >= 3) {
    pixel += (reverse) ? -1 : 1, length = pixel->value;
    if (length >= 255) {
      pixel += (reverse) ? -4 : 1;
      length = *(TUINT32 *)pixel;
    }
  }
  return length + 1;
}

