ParsedNumber::ParsedNumber() {
    reset();
}

void ParsedNumber::reset() {
    value.bogus = true;
    endOffset = 0;
    stateFlags = 0;
    leadingText.setToBogus();
    trailingText.setToBogus();
    currency[0] = 0;
}

void ParsedNumber::updateConsumed(const StringSegment& segment) {
    endOffset = segment.getOffset();
}

void ParsedNumber::finalize() {
    if (!value.bogus && 0 != (stateFlags & FLAG_NEGATIVE)) {
        value.negate();
    }
}

bool ParsedNumber::isValid() const {
    return endOffset > 0 && 0 == (stateFlags & FLAG_FAIL);
}

bool ParsedNumber::hasNumber() const {
    return !value.bogus || 0 != (stateFlags & FLAG_NAN) || 0 != (stateFlags & FLAG_INFINITY);
}

double ParsedNumber::asDouble(UErrorCode& err) const {
    bool isNaN = 0 != (stateFlags & FLAG_NAN);
    bool isInf = 0 != (stateFlags & FLAG_INFINITY);

    // Handle special values: NaN, infinity, and -0.0
    if (isNaN) {
        // Use platform-independent NaN representation
        return uprv_getNaN();
    }
    if (isInf) {
        return (0 != (stateFlags & FLAG_NEGATIVE)) ? -INFINITY : INFINITY;
    }

    if (value.bogus) {
        err = U_INVALID_STATE_ERROR;
        return 0.0;
    }

    if (value.isZeroish() && value.isNegative()) {
        return -0.0;
    }

    if (value.fitsInLong()) {
        return static_cast<double>(value.toLong());
    } else {
        return value.toDouble();
    }
}

void ParsedNumber::fillFormattable(Formattable& result, parse_flags_t flags) const {
    bool isNaN = 0 != (stateFlags & FLAG_NAN);
    bool isInf = 0 != (stateFlags & FLAG_INFINITY);
    bool intOnly = 0 != (flags & PARSE_FLAG_INTEGER_ONLY);

    if (isNaN) {
        result.setDouble(uprv_getNaN());
        return;
    }
    if (isInf) {
        if (0 != (stateFlags & FLAG_NEGATIVE)) {
            result.setDouble(-INFINITY);
        } else {
            result.setDouble(INFINITY);
        }
        return;
    }

    U_ASSERT(!value.bogus);
    if (value.isZeroish() && value.isNegative() && !intOnly) {
        result.setDouble(-0.0);
        return;
    }

    result.adoptDecimalQuantity(new DecimalQuantity(value));
}

bool ParsedNumber::beats(const ParsedNumber& other) {
    // Prefer results that consumed more characters
    return endOffset > other.endOffset;
}
