#include "pruning.h"
#include <algorithm>

/*********************************************
	class Pruning
*********************************************/
/**
	Steffen Klaere's pruning algorithm (modified version)
*/
void Pruning::run(Params &params, vector<PDTaxaSet> &taxa_set)
{
    // Adjust minimum size if needed
    if (params.min_size < 2) 
        params.min_size = params.sub_size;

    list_size = 2 * (leafNum - params.sub_size) - 1;

    if (!initialset.empty()) {
        initializeInitialSet();
    }

    constructLeafList();

    for (int iteration = leafNum; iteration > params.sub_size; iteration--) {
        removeExternalNode(findClosestLeaf());
        list_size -= 2;
    }

    taxa_set.resize(1);
    taxa_set[0].setTree(*this);
}

void Pruning::initializeInitialSet() {
    for (NodeVector::iterator it = initialset.begin(); it != initialset.end(); it++) {
        (*it)->height = 1;
    }
}

void Pruning::printLeaves() {
    for (LeafSet::iterator it = leaves.begin(); it != leaves.end(); it++) {
        Node *node = *it;
        std::cout << node->id << " " << node->neighbors[0]->length << std::endl;
    }
}

void Pruning::constructLeafList(Node *node, Node *parent) {
    if (!node) node = root;

    if (node->isLeaf()) {
        addLeafToSet(node);
    }

    FOR_NEIGHBOR_IT(node, parent, it) {
        constructLeafList((*it)->node, node);
    }
}

LeafSet::iterator Pruning::locateNode(Node *node) {
    std::pair<LeafSet::iterator, LeafSet::iterator>
        bounds = leaves.equal_range(node);

    for (LeafSet::iterator it = bounds.first; it != bounds.second; it++) {
        if (*it == node) {
            return it;
        }
    }

    return leaves.end();
}

void Pruning::removeExternalNode(LeafSet::iterator position) {
    Node *target = *position;
    Node *internal_node = target->neighbors[0]->node;
    Node *adjacent_nodes[2] = { nullptr, nullptr };
    int count = 0;
    NeighborVec::iterator iter;
    double combined_length = 0.0;
    bool can_merge = true;

    FOR_NEIGHBOR(internal_node, target, iter) {
        combined_length += (*iter)->length;

        if (adjacent_nodes[0] == nullptr) {
            adjacent_nodes[0] = (*iter)->node;
        } else if (adjacent_nodes[1] == nullptr) {
            adjacent_nodes[1] = (*iter)->node;
        } else {
            can_merge = false;
        }
    }

    if (can_merge) {
        // Merge branches when possible
        for (count = 0; count < 2; count++) {
            if (adjacent_nodes[count]->isLeaf()) {
                LeafSet::iterator temp = locateNode(adjacent_nodes[count]);
                if (temp != leaves.end()) {
                    leaves.erase(temp);
                }
            }
        }

        for (count = 0; count < 2; count++) {
            for (iter = adjacent_nodes[count]->neighbors.begin(); 
                 iter != adjacent_nodes[count]->neighbors.end(); 
                 iter++) {
                if ((*iter)->node == internal_node) {
                    (*iter)->node = adjacent_nodes[1 - count];
                    (*iter)->length = combined_length;
                }
            }
        }
    } else {
        // Simple deletion of neighbor
        for (iter = internal_node->neighbors.begin(); 
             iter != internal_node->neighbors.end(); 
             iter++) {
            if ((*iter)->node == target) {
                internal_node->neighbors.erase(iter);
                break;
            }
        }
    }

    leaves.erase(position);

    if (can_merge) {
        for (count = 0; count < 2; count++) {
            if (adjacent_nodes[count]->isLeaf()) {
                addLeafToSet(adjacent_nodes[count]);
            }
        }
    }

    // Remove last element if exceeding capacity
    if (leaves.size() > list_size && leaves.size() > 1) {
        LeafSet::iterator final_iter = leaves.end();
        --final_iter;
        leaves.erase(final_iter);
    }

    if (target == root) {
        root = *(leaves.begin());
    }
}

LeafSet::iterator Pruning::findClosestLeaf() {
    return leaves.begin();
}

/**
	insert a leaf into the LeafSet
*/
void Pruning::addLeafToSet(Node* leaf) {
    // Skip if leaf is part of initial set
    if (leaf->height == 1) {
        return;
    }

    if (list_size <= 0) {
        return;
    }

    if (leaves.size() < list_size) {
        leaves.insert(leaf);
    } else {
        LeafSet::iterator last_pos = leaves.end();
        --last_pos;
        Node* current_last = *last_pos;

        if (leaf->neighbors[0]->length < current_last->neighbors[0]->length) {
            leaves.erase(last_pos);
            leaves.insert(leaf);
        }
    }
}

#include "math/Rand2.h"

// Random number generator implementation using linear congruential method
RandomGen::RandomGen(int seedInput) {
    seedValue = seedInput;
    if (seedInput == 0) {
        seedValue = 1;
        return;
    }
    if (seedInput < 0)
        seedValue = -seedInput;
}

int RandomGen::Generate() {
    int nextVal = ((seedValue % 127773) * 0x41A7) - ((seedValue / 127773) * 0xB14);
    if (nextVal >= 0)
        seedValue = nextVal;
    else
        seedValue = nextVal + 0x7FFFFFFF;
    return seedValue;
}

