template <typename T>
struct get_dim {};

template <int dim, typename T, InstSetExt ISE>
struct get_dim<VectorND<dim, T, ISE>> {
  constexpr static int value = dim;
};

// Helper to construct vector constructors based on dimensionality
template <int dim, typename T>
struct VectorInitializer {};

template <typename T>
struct VectorInitializer<1, T> {
  static auto get() {
    return py::init<T>();
  }
};

template <typename T>
struct VectorInitializer<2, T> {
  static auto get() {
    return py::init<T, T>();
  }
};

template <typename T>
struct VectorInitializer<3, T> {
  static auto get() {
    return py::init<T, T, T>();
  }
};

template <typename T>
struct VectorInitializer<4, T> {
  static auto get() {
    return py::init<T, T, T, T>();
  }
};

// Accessor for vector components by index
template <int idx, typename VEC>
struct get_vec_field {};

template <typename VEC>
struct get_vec_field<0, VEC> {
  static auto get() {
    return &VEC::x;
  }
};

template <typename VEC>
struct get_vec_field<1, VEC> {
  static auto get() {
    return &VEC::y;
  }
};

template <typename VEC>
struct get_vec_field<2, VEC> {
  static auto get() {
    return &VEC::z;
  }
};

template <typename VEC>
struct get_vec_field<3, VEC> {
  static auto get() {
    return &VEC::w;
  }
};

// Conditionally register vector fields depending on dimension
template <int idx,
          typename VEC,
          typename Class,
          std::enable_if_t<get_dim<VEC>::value < idx + 1, int> = 0>
void register_vec_component(Class &) {}

template <int idx,
          typename VEC,
          typename Class,
          std::enable_if_t<get_dim<VEC>::value >= idx + 1, int> = 0>
void register_vec_component(Class &cls) {
  static const char *component_names[4] = {"x", "y", "z", "w"};
  cls.def_readwrite(component_names[idx], get_vec_field<idx, VEC>::get());
}

// Main registration logic for vector types
template <typename T>
struct VectorBinding {};

template <int dim, typename T, InstSetExt ISE>
struct VectorBinding<VectorND<dim, T, ISE>> {
  static void execute(py::module &mod) {
    using VecType = VectorND<dim, T, ISE>;

    // Build class name like Vector3f
    std::string class_name =
        std::string("Vector") + std::to_string(dim) + get_type_short_name<T>();

    auto cls = py::class_<VecType>(mod, class_name.c_str());

    cls.def(VectorInitializer<dim, T>::get())
       .def(py::init<T>())
       .def("__len__", [](VecType *) { return VecType::dim; })
       .def("__getitem__", [](VecType *v, int i) { return (*v)[i]; });

    register_vec_component<0, VecType>(cls);
    register_vec_component<1, VecType>(cls);
    register_vec_component<2, VecType>(cls);
    register_vec_component<3, VecType>(cls);
  }
};

// Export all supported vector types
void export_math(py::module &m) {
  VectorBinding<Vector2f>::execute(m);
  VectorBinding<Vector3f>::execute(m);
  VectorBinding<Vector4f>::execute(m);
  VectorBinding<Vector2d>::execute(m);
  VectorBinding<Vector3d>::execute(m);
  VectorBinding<Vector4d>::execute(m);
  VectorBinding<Vector2i>::execute(m);
  VectorBinding<Vector3i>::execute(m);
  VectorBinding<Vector4i>::execute(m);
}

