    // Traverse the DAG to gather all nurbs curves beneath the specified path.
    // The curve group is marked as animated if any single curve exhibits animation.
    void gatherNurbsCurves(const MDagPath &dagPath, bool skipInvisible,
        MDagPathArray &curveList, bool & outIsAnimated)
    {
        MStatus status;
        MItDag iter(MItDag::kDepthFirst, MFn::kNurbsCurve, &status);
        status = iter.reset(dagPath, MItDag::kDepthFirst, MFn::kNurbsCurve);
        if (status == MS::kSuccess)
        {
            for (; !iter.isDone(); iter.next())
            {
                MDagPath currentPath;
                status = iter.getPath(currentPath);
                if (status == MS::kSuccess)
                {
                    MObject node = currentPath.node();
                    if (!util::isIntermediate(node) &&
                        node.hasFn(MFn::kNurbsCurve) &&
                        (!skipInvisible || util::isRenderable(node)))
                    {
                        curveList.append(currentPath);
                    }
                    else
                    {
                        continue;
                    }

                    if (!outIsAnimated)
                    {
                        if (util::isAnimated(node, true))
                        {
                            outIsAnimated = true;
                        }
                        MObject transformNode(currentPath.transform());
                        if (util::isAnimated(transformNode, true))
                        {
                            outIsAnimated = true;
                        }
                    }
                }
            }
        }
    }  // end of function gatherNurbsCurves
}

MayaNurbsCurveWriter::MayaNurbsCurveWriter(MDagPath & inputPath,
    Alembic::Abc::OObject & parentObj, Alembic::Util::uint32_t timeIndex,
    bool iIsCurveGrp, const JobArgs & args) :
    mIsAnimated(false), mRootDagPath(inputPath), mIsCurveGrp(iIsCurveGrp)
{
    MStatus status;
    MFnDependencyNode depNode(inputPath.node(), &status);
    MString objName = depNode.name();

    if (mIsCurveGrp)
    {
        gatherNurbsCurves(mRootDagPath, args.excludeInvisible,
            mNurbsCurves, mIsAnimated);
        if (mNurbsCurves.length() == 0)
            return;
    }
    else
    {
        MObject curveObj = inputPath.node();
        if (timeIndex != 0 && util::isAnimated(curveObj))
        {
            mIsAnimated = true;
        }
        else
        {
            timeIndex = 0;
        }
    }

    objName = util::stripNamespaces(objName, args.stripNamespace);
    Alembic::AbcGeom::OCurves curveObj(parentObj, objName.asChar(), timeIndex);
    mSchema = curveObj.getSchema();

    Alembic::Abc::OCompoundProperty arbParams;
    Alembic::Abc::OCompoundProperty userProps;
    if (AttributesWriter::hasAnyAttr(depNode, args))
    {
        arbParams = mSchema.getArbGeomParams();
        userProps = mSchema.getUserProperties();
    }

    mAttrs = AttributesWriterPtr(new AttributesWriter(arbParams, userProps, curveObj,
        depNode, timeIndex, args, true));

    if (!mIsAnimated || args.setFirstAnimShape)
    {
        write();
    }
}

unsigned int MayaNurbsCurveWriter::getNumCVs()
{
    return mCVCount;
}

unsigned int MayaNurbsCurveWriter::getNumCurves()
{
    if (mIsCurveGrp)
        return mNurbsCurves.length();
    else
        return 1;
}

bool MayaNurbsCurveWriter::isAnimated() const
{
    return mIsAnimated;
}

void MayaNurbsCurveWriter::write()
{
    Alembic::AbcGeom::OCurvesSchema::Sample sample;
    sample.setBasis(Alembic::AbcGeom::kBsplineBasis);

    MStatus status;
    mCVCount = 0;

    MMatrix inverseWorldMatrix = mRootDagPath.exclusiveMatrixInverse(&status);
    std::size_t numCurves = 1;
    if (mIsCurveGrp)
        numCurves = mNurbsCurves.length();

    std::vector<Alembic::Util::int32_t> vertexCounts(numCurves);
    std::vector<float> positions;
    std::vector<float> widths;
    std::vector<float> knotValues;
    std::vector<Alembic::Util::uint8_t> degrees(numCurves);

    MMatrix worldMatrix;
    bool useUniformWidth = false;
    MFnDependencyNode transformDep(mRootDagPath.transform());
    MPlug widthPlug = transformDep.findPlug("width", true);
    if (!widthPlug.isNull())
    {
        useUniformWidth = true;
        widths.push_back(widthPlug.asFloat());
    }

    for (unsigned int idx = 0; idx < numCurves; ++idx)
    {
        MFnNurbsCurve curveFn;
        if (mIsCurveGrp)
        {
            curveFn.setObject(mNurbsCurves[idx]);
            MMatrix localToWorld = mNurbsCurves[idx].inclusiveMatrix(&status);
            worldMatrix = localToWorld * inverseWorldMatrix;
        }
        else
        {
            curveFn.setObject(mRootDagPath.node());
        }

        if (idx == 0)
        {
            if (curveFn.form() == MFnNurbsCurve::kOpen)
            {
                sample.setWrap(Alembic::AbcGeom::kNonPeriodic);
            }
            else
            {
                sample.setWrap(Alembic::AbcGeom::kPeriodic);
            }

            if (curveFn.degree() == 3)
            {
                sample.setType(Alembic::AbcGeom::kCubic);
            }
            else if (curveFn.degree() == 1)
            {
                sample.setType(Alembic::AbcGeom::kLinear);
            }
            else
            {
                sample.setType(Alembic::AbcGeom::kVariableOrder);
            }
        }
        else
        {
            if (curveFn.form() == MFnNurbsCurve::kOpen)
            {
                sample.setWrap(Alembic::AbcGeom::kNonPeriodic);
            }

            if ((sample.getType() == Alembic::AbcGeom::kCubic &&
                curveFn.degree() != 3) ||
                (sample.getType() == Alembic::AbcGeom::kLinear &&
                curveFn.degree() != 1))
            {
                sample.setType(Alembic::AbcGeom::kVariableOrder);
            }
        }

        degrees[idx] = static_cast<Alembic::Util::uint8_t>(curveFn.degree() + 1);

        Alembic::Util::int32_t cvCount = curveFn.numCVs(&status);
        MPointArray cvs;
        status = curveFn.getCVs(cvs, MSpace::kObject);
        mCVCount += cvCount;
        vertexCounts[idx] = cvCount;

        for (Alembic::Util::int32_t j = 0; j < cvCount; ++j)
        {
            MPoint transformedPt;
            if (mIsCurveGrp)
            {
                transformedPt = cvs[j] * worldMatrix;
            }
            else
            {
                transformedPt = cvs[j];
            }

            positions.push_back(static_cast<float>(transformedPt.x));
            positions.push_back(static_cast<float>(transformedPt.y));
            positions.push_back(static_cast<float>(transformedPt.z));
        }

        MDoubleArray knotArr;
        curveFn.getKnots(knotArr);
        knotValues.reserve(knotArr.length() + 2);

        if (knotArr.length() > 1)
        {
            unsigned int knotLen = knotArr.length();
            if (knotArr[0] == knotArr[knotLen - 1] ||
                knotArr[0] == knotArr[1])
            {
                knotValues.push_back(static_cast<float>(knotArr[0]));
            }
            else
            {
                knotValues.push_back(static_cast<float>(2 * knotArr[0] - knotArr[1]));
            }

            for (unsigned int k = 0; k < knotLen; ++k)
            {
                knotValues.push_back(static_cast<float>(knotArr[k]));
            }

            if (knotArr[0] == knotArr[knotLen - 1] ||
                knotArr[knotLen - 1] == knotArr[knotLen - 2])
            {
                knotValues.push_back(static_cast<float>(knotArr[knotLen - 1]));
            }
            else
            {
                knotValues.push_back(static_cast<float>(2 * knotArr[knotLen - 1] -
                                knotArr[knotLen - 2]));
            }
        }

        MPlug curveWidthPlug = curveFn.findPlug("width", true);
        if (!useUniformWidth && !curveWidthPlug.isNull())
        {
            MObject widthDataObj;
            MStatus plugStatus = curveWidthPlug.getValue(widthDataObj);
            MFnDoubleArrayData doubleArrayFn(widthDataObj, &plugStatus);
            MDoubleArray dataArr = doubleArrayFn.array();
            Alembic::Util::int32_t arrSize = dataArr.length();

            if (arrSize == cvCount)
            {
                for (Alembic::Util::int32_t k = 0; k < arrSize; ++k)
                {
                    widths.push_back(static_cast<float>(dataArr[k]));
                }
            }
            else if (plugStatus == MS::kSuccess)
            {
                MString warningMsg = "Curve ";
                warningMsg += curveFn.partialPathName();
                warningMsg += " has incorrect size for the width vector.";
                warningMsg += "\nUsing default constant width of 0.1.";
                MGlobal::displayWarning(warningMsg);

                widths.clear();
                widths.push_back(0.1f);
                useUniformWidth = true;
            }
            else
            {
                widths.push_back(curveWidthPlug.asFloat());
            }
        }
        else if (!useUniformWidth)
        {
            widths.clear();
            widths.push_back(0.1f);
            useUniformWidth = true;
        }
    }

    Alembic::AbcGeom::GeometryScope scope = Alembic::AbcGeom::kVertexScope;
    if (!useUniformWidth && widths.size() > 1 && widths.size() == numCurves)
    {
        scope = Alembic::AbcGeom::kUniformScope;
    }
    else if (widths.size() == 1)
    {
        scope = Alembic::AbcGeom::kConstantScope;
    }

    samp.setCurvesNumVertices(Alembic::Abc::Int32ArraySample(vertexCounts));
    samp.setPositions(Alembic::Abc::V3fArraySample(
        (const Imath::V3f *)&positions.front(), positions.size() / 3 ));
    samp.setWidths(Alembic::AbcGeom::OFloatGeomParam::Sample(
        Alembic::Abc::FloatArraySample(widths), scope) );

    if (samp.getType() == Alembic::AbcGeom::kVariableOrder)
    {
        samp.setOrders(Alembic::Abc::UcharArraySample(degrees));
    }

    if (!knotValues.empty())
    {
        samp.setKnots(Alembic::Abc::FloatArraySample(knotValues));
    }

    mSchema.set(samp);
}

