void recordCommand(const std::string& cmd) {
    if (cmd.empty()) return;
    if (logSize > 0 && commandLog[(logPosition - 1 + MAX_HISTORY_ENTRIES) % MAX_HISTORY_ENTRIES] == cmd) return;
    commandLog[logPosition] = cmd;
    logPosition = (logPosition + 1) % MAX_HISTORY_ENTRIES;
    if (logSize < MAX_HISTORY_ENTRIES) logSize++;
}

