    printLine("Command history:");
    int firstIndex = (logPosition - logSize + MAX_HISTORY_ENTRIES) % MAX_HISTORY_ENTRIES;
    for (int i = 0; i < logSize; i++) {
        int idx = (firstIndex + i) % MAX_HISTORY_ENTRIES;
        printLine(std::to_string(i + 1) + ": " + commandLog[idx]);
