    sprintf(buffer, "Free Heap: %u bytes (%.2f KB)", ESP.getFreeHeap(), freeKB);
    printLine(buffer);
    sprintf(buffer, "Min Free Heap: %u bytes (%.2f KB)", ESP.getMinFreeHeap(), minFreeKB);
    printLine(buffer);
    sprintf(buffer, "Max Alloc Heap: %u bytes (%.2f KB)", ESP.getMaxAllocHeap(), maxAllocKB);
    printLine(buffer);
