Frustum* Frustum::instance = new Frustum();

Frustum::Frustum()
{
    _projectionMatrix = MemoryTracker::createFloatBuffer(16);
    _modelViewMatrix = MemoryTracker::createFloatBuffer(16);
    _combinedMatrix = MemoryTracker::createFloatBuffer(16);
}

Frustum::~Frustum()
{
    delete _projectionMatrix;
    delete _modelViewMatrix;
    delete _combinedMatrix;
}

FrustumData* Frustum::getInstance()
{
    instance->updateFrustum();
    return instance;
}

// Normalize a plane vector to unit length
void Frustum::normalizePlane(float (**planes), int index)
{
    float length = (float)sqrt(planes[index][X] * planes[index][X] +
                               planes[index][Y] * planes[index][Y] +
                               planes[index][Z] * planes[index][Z]);

    // Scale the plane coefficients by the inverse length
    planes[index][X] /= length;
    planes[index][Y] /= length;
    planes[index][Z] /= length;
    planes[index][W] /= length;
}

void Frustum::updateFrustum()
{
    _projectionMatrix->clear();
    _modelViewMatrix->clear();
    _combinedMatrix->clear();

    glGetFloat(GL_PROJECTION_MATRIX, _projectionMatrix);
    glGetFloat(GL_MODELVIEW_MATRIX, _modelViewMatrix);

    _projectionMatrix->flip()->limit(16);
    _projectionMatrix->get(&projData);
    _modelViewMatrix->flip()->limit(16);
    _modelViewMatrix->get(&modelData);

    // Compute combined clipping matrix by multiplying modelview and projection matrices
    clip[0]  = modelData[0] * projData[0] + modelData[1] * projData[4] + modelData[2] * projData[8] + modelData[3] * projData[12];
    clip[1]  = modelData[0] * projData[1] + modelData[1] * projData[5] + modelData[2] * projData[9] + modelData[3] * projData[13];
    clip[2]  = modelData[0] * projData[2] + modelData[1] * projData[6] + modelData[2] * projData[10] + modelData[3] * projData[14];
    clip[3]  = modelData[0] * projData[3] + modelData[1] * projData[7] + modelData[2] * projData[11] + modelData[3] * projData[15];
    clip[4]  = modelData[4] * projData[0] + modelData[5] * projData[4] + modelData[6] * projData[8] + modelData[7] * projData[12];
    clip[5]  = modelData[4] * projData[1] + modelData[5] * projData[5] + modelData[6] * projData[9] + modelData[7] * projData[13];
    clip[6]  = modelData[4] * projData[2] + modelData[5] * projData[6] + modelData[6] * projData[10] + modelData[7] * projData[14];
    clip[7]  = modelData[4] * projData[3] + modelData[5] * projData[7] + modelData[6] * projData[11] + modelData[7] * projData[15];
    clip[8]  = modelData[8] * projData[0] + modelData[9] * projData[4] + modelData[10] * projData[8] + modelData[11] * projData[12];
    clip[9]  = modelData[8] * projData[1] + modelData[9] * projData[5] + modelData[10] * projData[9] + modelData[11] * projData[13];
    clip[10] = modelData[8] * projData[2] + modelData[9] * projData[6] + modelData[10] * projData[10] + modelData[11] * projData[14];
    clip[11] = modelData[8] * projData[3] + modelData[9] * projData[7] + modelData[10] * projData[11] + modelData[11] * projData[15];
    clip[12] = modelData[12] * projData[0] + modelData[13] * projData[4] + modelData[14] * projData[8] + modelData[15] * projData[12];
    clip[13] = modelData[12] * projData[1] + modelData[13] * projData[5] + modelData[14] * projData[9] + modelData[15] * projData[13];
    clip[14] = modelData[12] * projData[2] + modelData[13] * projData[6] + modelData[14] * projData[10] + modelData[15] * projData[14];
    clip[15] = modelData[12] * projData[3] + modelData[13] * projData[7] + modelData[14] * projData[11] + modelData[15] * projData[15];

    // Extract frustum planes from the combined matrix
    // Right plane
    frustum[RIGHT][X] = clip[3] - clip[0];
    frustum[RIGHT][Y] = clip[7] - clip[4];
    frustum[RIGHT][Z] = clip[11] - clip[8];
    frustum[RIGHT][W] = clip[15] - clip[12];
    normalizePlane(frustum, RIGHT);

    // Left plane
    frustum[LEFT][X] = clip[3] + clip[0];
    frustum[LEFT][Y] = clip[7] + clip[4];
    frustum[LEFT][Z] = clip[11] + clip[8];
    frustum[LEFT][W] = clip[15] + clip[12];
    normalizePlane(frustum, LEFT);

    // Bottom plane
    frustum[BOTTOM][X] = clip[3] + clip[1];
    frustum[BOTTOM][Y] = clip[7] + clip[5];
    frustum[BOTTOM][Z] = clip[11] + clip[9];
    frustum[BOTTOM][W] = clip[15] + clip[13];
    normalizePlane(frustum, BOTTOM);

    // Top plane
    frustum[TOP][X] = clip[3] - clip[1];
    frustum[TOP][Y] = clip[7] - clip[5];
    frustum[TOP][Z] = clip[11] - clip[9];
    frustum[TOP][W] = clip[15] - clip[13];
    normalizePlane(frustum, TOP);

    // Back plane
    frustum[BACK][X] = clip[3] - clip[2];
    frustum[BACK][Y] = clip[7] - clip[6];
    frustum[BACK][Z] = clip[11] - clip[10];
    frustum[BACK][W] = clip[15] - clip[14];
    normalizePlane(frustum, BACK);

    // Front plane
    frustum[FRONT][X] = clip[3] + clip[2];
    frustum[FRONT][Y] = clip[7] + clip[6];
    frustum[FRONT][Z] = clip[11] + clip[10];
    frustum[FRONT][W] = clip[15] + clip[14];
    normalizePlane(frustum, FRONT);
}

