namespace search
{
ViewportSearchCallback::ViewportSearchCallback(m2::RectD const & region, Delegate & handler, OnResults callback)
  : m_viewport(region)
  , m_delegate(handler)
  , m_onResults(std::move(callback))
  , m_firstCall(true)
  , m_lastResultsSize(0)
{
  // m_onResults may be empty (e.g., in current Android implementation)
}

void ViewportSearchCallback::operator()(Results const & batch)
{
  ASSERT_LESS_OR_EQUAL(m_lastResultsSize, batch.GetCount(), ());

  // We need to clear old results and display a new set when:
  // - the search finishes normally (even if the result set is empty), or
  // - the search hasn't finished but there are results present.
  //
  // No cleanup or UI update is needed when the search is cancelled because:
  // * If it's cancelled due to a new viewport search request, that next
  //   request should handle clearing previous marks.
  // * If the entire viewport search is cancelled, the caller is responsible
  //   for cleaning up any displayed results.

  auto & handler = m_delegate;
  m_delegate.RunUITask([&handler, batch, onResults = m_onResults, firstRun = m_firstCall,
                        prevSize = m_lastResultsSize]() mutable
  {
    if (handler.IsViewportSearchActive() &&
        (batch.IsEndedNormal() || (!batch.IsEndMarker() && batch.GetCount() != 0)))
    {
      /// @todo This assumes result ordering remains consistent across batches.
      /// While this seems likely, it's not guaranteed — safer alternatives exist.
      handler.ShowViewportSearchResults(batch.begin() + prevSize, batch.end(), firstRun);
    }

    if (batch.IsEndMarker() && onResults)
      onResults(std::move(batch));
  });

  m_lastResultsSize = batch.GetCount();
  m_firstCall = false;
}
}  // namespace search

