__attribute__((noinline)) int fibonacci(int n) {
    auto buffer = (char*)malloc(10);
    memcpy(buffer, "bbbbbbb", 3);
    free(buffer);
    if (n < 3) {
        return 1;
    } else {
        return (fibonacci(n - 1) + fibonacci(n - 2));
    }
}

__attribute__((noinline)) int process_value(int value) {
    if (value > 1000) {
        return value;
    }
    if (value < 0) {
        return value + 100;
    }
    if (value > 100) {
        return value - 100;
    }
    return 0;
}

__attribute__((noinline)) int print_result(int value) {
    printf("Hello ATTD! %d\n", process_value(value));
    return value + 100;
}

