const int SLOT_LOCKED = 1;
const int SLOT_SPECIAL = 2;

void MemSlotVector::initialize(PhyloTree *pt, int num_slots) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    reserve(num_slots + 2);
    resize(num_slots);

    size_t partial_lh_size = pt->getPartialLhSize();
    size_t scale_num_size = pt->getScaleNumSize();

    reset();

    for (iterator iter = begin(); iter != end(); iter++) {
        iter->partial_lh = pt->central_partial_lh + partial_lh_size * (iter - begin());
        iter->scale_num = pt->central_scale_num + scale_num_size * (iter - begin());
    }
}

void MemSlotVector::reset() {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    for (iterator iter = begin(); iter != end(); iter++) {
        iter->status = 0;
        iter->nei = NULL;
    }

    nei_id_map.clear();
    free_count = 0;
}

MemSlotVector::iterator MemSlotVector::searchNei(PhyloNeighbor *neighbor) {
    auto iter = nei_id_map.find(neighbor);
    ASSERT(iter != nei_id_map.end());
    // assert(at(iter->second).nei == neighbor);
    return begin() + iter->second;
}

void MemSlotVector::insertNei(PhyloNeighbor *neighbor, iterator pos) {
    // assert((pos->status & SLOT_SPECIAL) == 0);
    neighbor->partial_lh = pos->partial_lh;
    neighbor->scale_num = pos->scale_num;
    pos->nei = neighbor;
    nei_id_map[neighbor] = pos - begin();
}

void MemSlotVector::insertSpecialNei(PhyloNeighbor *neighbor) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    MemSlot slot;
    slot.status = SLOT_SPECIAL | SLOT_LOCKED;
    slot.nei = neighbor;
    slot.partial_lh = neighbor->partial_lh;
    slot.scale_num = neighbor->scale_num;

    push_back(slot);
    nei_id_map[neighbor] = size() - 1;
}

void MemSlotVector::removeSpecialNei() {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    while (back().status & SLOT_SPECIAL) {
        nei_id_map.erase(back().nei);
        pop_back();
    }
}

bool MemSlotVector::acquireLock(PhyloNeighbor *neighbor) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return false;

    if (neighbor->node->isLeaf())
        return false;

    iterator pos = searchNei(neighbor);

    if (pos->status & SLOT_SPECIAL)
        return false;

    ASSERT((pos->status & SLOT_LOCKED) == 0);
    pos->status |= SLOT_LOCKED;
    return true;
}

void MemSlotVector::releaseLock(PhyloNeighbor *neighbor) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    if (neighbor->node->isLeaf())
        return;

    iterator pos = searchNei(neighbor);

    if (pos->status & SLOT_SPECIAL)
        return;

    ASSERT((pos->status & SLOT_LOCKED) != 0);
    pos->status &= ~SLOT_LOCKED;
}

bool MemSlotVector::isLocked(PhyloNeighbor *neighbor) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return false;

    if (neighbor->node->isLeaf())
        return false;

    iterator pos = searchNei(neighbor);

    if (pos->status & SLOT_SPECIAL)
        return false;

    if ((pos->status & SLOT_LOCKED) == 0)
        return false;
    else
        return true;
}

int MemSlotVector::assignSlot(PhyloNeighbor *neighbor) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return -1;

    // First try to find a free slot
    if (free_count < size() && (at(free_count).status & SLOT_SPECIAL) == 0) {
        iterator pos = begin() + free_count;
        ASSERT(pos->nei == NULL);
        insertNei(neighbor, pos);
        free_count++;
        return pos - begin();
    }

    int min_size = INT_MAX;
    iterator best = end();

    // No free slot found, look for an unlocked slot with minimal size
    for (iterator pos = begin(); pos != end(); pos++) {
        if ((pos->status & SLOT_LOCKED) == 0 && 
            (pos->status & SLOT_SPECIAL) == 0 && 
            min_size > pos->nei->size) {

            best = pos;
            min_size = pos->nei->size;

            // Minimum size is 2
            if (min_size == 2)
                break;
        }
    }

    if (best == end())
        return -1;

    // Clear memory assigned to best->nei
    best->nei->clearPartialLh();

    // Assign memory to the new neighbor
    insertNei(neighbor, best);

    return best - begin();
}

void MemSlotVector::refresh(PhyloNeighbor *neighbor) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator pos = searchNei(neighbor);

    // if (pos->status & SLOT_SPECIAL)
    //     return;

    if (pos->nei != neighbor) {
        // Clear memory assigned to current neighbor
        pos->nei->clearPartialLh();

        // Assign memory to the new neighbor
        insertNei(neighbor, pos);
    }
}

