void MemSlotVector::transfer(PhyloNeighbor *new_neighbor, PhyloNeighbor *source_neighbor) {
    ASSERT(source_neighbor->partial_lh);

    new_neighbor->partial_lh = source_neighbor->partial_lh;
    new_neighbor->scale_num = source_neighbor->scale_num;

    source_neighbor->partial_lh = NULL;
    source_neighbor->scale_num = NULL;
    source_neighbor->partial_lh_computed &= ~1; // clear bit

    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator pos = searchNei(source_neighbor);

    // if (pos->status & SLOT_SPECIAL)
    //     return;

    nei_id_map.erase(nei_id_map.find(source_neighbor));
    nei_id_map[new_neighbor] = pos - begin();

    if (pos->nei == source_neighbor) {
        pos->nei = new_neighbor;
    }
}

void MemSlotVector::substitute(PhyloNeighbor *replacement, PhyloNeighbor *original) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator pos = searchNei(original);
    ASSERT(pos->partial_lh == original->partial_lh);

    pos->saved_nei = pos->nei;
    pos->nei = replacement;
    pos->partial_lh = replacement->partial_lh;
    pos->scale_num = replacement->scale_num;
    pos->status = SLOT_LOCKED | SLOT_SPECIAL;

    nei_id_map[replacement] = pos - begin();

    cout << "slot " << distance(begin(), pos) << " replaced" << endl;
}

void MemSlotVector::revert(PhyloNeighbor *current, PhyloNeighbor *previous) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator pos = searchNei(current);
    ASSERT(pos->nei == current);
    ASSERT(nei_id_map[previous] == pos - begin());

    pos->nei = pos->saved_nei;
    pos->saved_nei = NULL;
    pos->partial_lh = previous->partial_lh;
    pos->scale_num = previous->scale_num;
    pos->status = 0;

    nei_id_map.erase(current);

    cout << "slot " << distance(begin(), pos) << " restored" << endl;
}

#include "Utils/Parallel/MultiThreading.h"

// Constructor: creates and initializes a pthread mutex
PPMutex::PPMutex() {
  int result = pthread_mutex_init(&mutex, nullptr);
  is_valid = (result == 0);
}

// Destructor: destroys the pthread mutex
PPMutex::~PPMutex() {
  pthread_mutex_destroy(&mutex);
  is_valid = false;
}

// Checks whether the mutex was successfully created
bool PPMutex::isValid() { return is_valid; }

// Attempts to lock the mutex; returns true if successful
bool PPMutex::lock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_mutex_lock(&mutex);
  return result == 0;
}

// Attempts to unlock the mutex; returns true if successful
bool PPMutex::unlock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_mutex_unlock(&mutex);
  return result == 0;
}

// Constructor: initializes a pthread read-write lock
PPReadWriteLock::PPReadWriteLock() {
  int result = pthread_rwlock_init(&mutex, nullptr);
  is_valid = (result == 0);
}

// Destructor: destroys the pthread read-write lock
PPReadWriteLock::~PPReadWriteLock() {
  pthread_rwlock_destroy(&mutex);
  is_valid = false;
}

// Checks whether the read-write lock was successfully created
bool PPReadWriteLock::isValid() { return is_valid; }

// Acquires a read lock; returns true on success
bool PPReadWriteLock::rdLock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_rdlock(&mutex);
  return result == 0;
}

// Acquires a write lock; returns true on success
bool PPReadWriteLock::wrLock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_wrlock(&mutex);
  return result == 0;
}

// Releases a read lock; returns true on success
bool PPReadWriteLock::rdUnlock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_unlock(&mutex);
  return result == 0;
}

// Releases a write lock; returns true on success
bool PPReadWriteLock::wrUnlock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_unlock(&mutex);
  return result == 0;
}

// Constructor: creates a thread-specific data key with optional destructor
PPThreadData::PPThreadData(void (*destructor)(void *)) {
  int result = pthread_key_create(&key, destructor);
  is_valid = (result == 0);
}

// Destructor: deletes the thread-specific data key
PPThreadData::~PPThreadData() {
  pthread_key_delete(key);
  is_valid = false;
}

// Checks whether the thread data key was successfully created
bool PPThreadData::isValid() { return is_valid; }

// Sets the value for the current thread; returns true on success
bool PPThreadData::setValue(void *data) {
  if (!isValid()) {
    return false;
  }
  int result = pthread_setspecific(key, data);
  return result == 0;
}

// Gets the value associated with the current thread; returns nullptr if invalid
void *PPThreadData::getValue() {
  if (!isValid()) {
    return nullptr;
  }
  return pthread_getspecific(key);
}

// Returns the identifier of the calling thread
PPThreadIDType getCurrentThreadID() { return pthread_self(); }

