LOGMODULE("ftpd");

constexpr u16 ServerPort = 21;
constexpr u8 MaxSimultaneousConnections = 1;

CFTPDaemon::CFTPDaemon(const char* pUsername, const char* pPass)
    : CTask(TASK_STACK_SIZE, true),
      m_pAcceptSocket(nullptr),
      m_pUserName(pUsername),
      m_pUserPass(pPass) {
}

CFTPDaemon::~CFTPDaemon() {
    if (m_pAcceptSocket)
        delete m_pAcceptSocket;
}

bool CFTPDaemon::Initialize() {
    CNetSubSystem* const pNetwork = CNetSubSystem::Get();
    if ((m_pAcceptSocket = new CSocket(pNetwork, IPPROTO_TCP)) == nullptr)
        return false;

    if (m_pAcceptSocket->Bind(ServerPort) != 0) {
        LOGERR("Unable to bind to port %d", ServerPort);
        return false;
    }

    if (m_pAcceptSocket->Listen() != 0) {
        LOGERR("Failed to start listening on control socket");
        return false;
    }

    Start();
    return true;
}

void CFTPDaemon::Run() {
    assert(m_pAcceptSocket != nullptr);
    LOGNOTE("Control listener task started");

    while (true) {
        CIPAddress remoteAddress;
        u16 remotePort;

        LOGDBG("Waiting for incoming connection");
        CSocket* pClientSocket = m_pAcceptSocket->Accept(&remoteAddress, &remotePort);

        if (pClientSocket == nullptr) {
            LOGERR("Connection acceptance failed");
            continue;
        }

        CString addressBuffer;
        remoteAddress.Format(&addressBuffer);
        LOGNOTE("New connection from %s:%d", static_cast<const char*>(addressBuffer), remotePort);

        if (CFTPWorker::GetInstanceCount() >= MaxSimultaneousConnections) {
            pClientSocket->Send("421 Too many connections.\r\n", 27, 0);
            delete pClientSocket;
            LOGWARN("Connection limit exceeded");
            continue;
        }

        // Create new worker for the client
        new CFTPWorker(pClientSocket, m_pUserName, m_pUserPass);
    }
}

#include <charPipeline/structures/dolphinString.h>

// Concatenates two strings into a destination buffer
u8 ConcatenateStrings(char* source1, char* source2, char* destination) {
    char* readPtr1 = source1;
    char* writePtr = destination;

    if (!destination) {
        return 0;
    }
    if (!source1) {
        return 0;
    }
    if (!source2) {
        return 0;
    }

    // Copy first string
    while ((s8)*readPtr1 != 0) {
        *writePtr = *readPtr1;
        writePtr++;
        readPtr1++;
    }

    // Copy second string
    readPtr1 = source2;
    while ((s8)*readPtr1 != 0) {
        *writePtr = *readPtr1;
        writePtr++;
        readPtr1++;
    }

    // Null-terminate the result
    *writePtr = 0;
    return 1;
}

// Copies source string to destination
void CopyString(char* destination, char* source) {
    do {
        *destination = *source;
        destination++;
        source++;
    } while ((s8)*source != 0);
}

// Compares two strings lexicographically
s8 CompareStrings(char* strA, char* strB) {
    char* ptrA = strA;
    char* ptrB = strB;

    while (1) {
        if ((s8)*ptrA < (s8)*ptrB) {
            return 1;
        }
        if ((s8)*ptrA > (s8)*ptrB) {
            return -1;
        }
        ptrA++;
        ptrB++;

        if ((s8)*ptrA == 0 || (s8)*ptrB == 0) {
            return 0;
        }
    }
}

// Returns the length of a null-terminated string
u32 GetStringLength(char* inputStr) {
    char* scanPtr = inputStr;
    u32 lengthCounter = 0;

    if (!inputStr) {
        return 0;
    }

    while ((s8)*scanPtr != 0) {
        scanPtr++;
        lengthCounter++;
    }

    return lengthCounter;
}

