/// Reverse the order of the requested least significant nr. of bits.
/// @param[in] input Bit pattern/integer to reverse.
/// @param[in] nbits Nr. of bits to reverse. (LSB -> MSB)
/// @return The reversed bit pattern.
uint64_t reverseBits(uint64_t input, uint16_t nbits) {
  if (nbits <= 1) return input;

  nbits = std::min(nbits, static_cast<uint16_t>((sizeof(input) * 8)));
  uint64_t output = 0;

  for (uint16_t idx = 0; idx < nbits; idx++) {
    output <<= 1;
    output |= (input & 1);
    input >>= 1;
  }

  return (input << nbits) | output;
}

/// Convert a uint64_t (unsigned long long) to a string.
String uint64ToString(uint64_t value, uint8_t radix) {
  String result = "";

  if (radix < 2) radix = 10;
  if (radix > 36) radix = 10;

  result.reserve(16);

  do {
    char c = value % radix;
    value /= radix;

    if (c < 10)
      c += '0';
    else
      c += 'A' - 10;

    result = c + result;
  } while (value);

  return result;
}

/// Convert a int64_t (signed long long) to a string.
String int64ToString(int64_t value, uint8_t radix) {
  if (value < 0) {
    return String(kDashStr) + uint64ToString(-value, radix);
  }
  return uint64ToString(value, radix);
}

