#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <stack>
#include <cassert>
using namespace std;

struct Room {
    int identifier;
    int predecessor;      
    int entrance_tube;    
    int next_tube;        
    int stone_direction;   // 0 for left, 1 for right
    int stone_tube;       
    bool completed;
};

int size;
int chamber_counter = 0;
vector<Room> rooms;
map<pair<int, int>, int> hash_to_room; // (direction, tube) -> identifier
stack<int> traversal_stack;

void read_stone(string& direction_str, int& tube) {
    cin >> direction_str;
    if (direction_str == "center") {
        tube = -1;
    } else if (direction_str == "left" || direction_str == "right") {
        cin >> tube;
    } else if (direction_str == "treasure") {
        tube = -1;
    }
}

int direction_to_int(const string& d) {
    if (d == "left") return 0;
    if (d == "right") return 1;
    return -1;
}

string int_to_direction(int x) {
    return x == 0 ? "left" : "right";
}

int distance(int start, int end) {
    return (end - start + size) % size;
}

int main() {
    cin >> size;
    string direction_str;
    int tube;
    read_stone(direction_str, tube);
    assert(direction_str == "center");

    Room initial_room;
    initial_room.identifier = chamber_counter++;
    initial_room.predecessor = -1;
    initial_room.entrance_tube = -1;
    initial_room.next_tube = 0;
    initial_room.stone_direction = 0;
    initial_room.stone_tube = 0;
    initial_room.completed = false;
    rooms.push_back(initial_room);

    hash_to_room[make_pair(0, 0)] = initial_room.identifier;
    traversal_stack.push(initial_room.identifier);

    cout << "0 left 0" << endl;

    while (true) {
        read_stone(direction_str, tube);
        if (direction_str == "treasure") {
            break;
        }

        int current_room_id;

        if (direction_str == "center") {
            Room new_room;
            new_room.identifier = chamber_counter++;
            new_room.predecessor = traversal_stack.top();
            new_room.entrance_tube = -1;
            new_room.next_tube = 0;
            new_room.completed = false;

            int hash_dir, hash_tub;
            if (new_room.identifier < size) {
                hash_dir = 0;
                hash_tub = new_room.identifier;
            } else if (new_room.identifier - size < size) {
                hash_dir = 1;
                hash_tub = new_room.identifier - size;
            } else {
                hash_dir = (new_room.identifier / size) % 2;
                hash_tub = new_room.identifier % size;
            }

            new_room.stone_direction = hash_dir;
            new_room.stone_tube = hash_tub;
            rooms.push_back(new_room);
            hash_to_room[make_pair(hash_dir, hash_tub)] = new_room.identifier;
            current_room_id = new_room.identifier;
            traversal_stack.push(current_room_id);
        } else {
            int dir_int = direction_to_int(direction_str);
            pair<int, int> key = make_pair(dir_int, tube);

            if (hash_to_room.find(key) == hash_to_room.end()) {
                Room new_room;
                new_room.identifier = chamber_counter++;
                new_room.predecessor = -1;
                new_room.entrance_tube = -1;
                new_room.next_tube = 0;
                new_room.stone_direction = dir_int;
                new_room.stone_tube = tube;
                new_room.completed = false;
                rooms.push_back(new_room);
                hash_to_room[key] = new_room.identifier;
                current_room_id = new_room.identifier;
                traversal_stack.push(current_room_id);
            } else {
                current_room_id = hash_to_room[key];
            }
        }

        Room& current = rooms[current_room_id];

        if (current.next_tube < size) {
            int k = current.next_tube;
            current.next_tube = current.next_tube + 1;
            int d1 = distance(current.stone_tube, k);
            cout << d1 << " left " << d1 << endl;
            current.stone_direction = 0;
            current.stone_tube = k;
            hash_to_room[make_pair(0, k)] = current_room_id;
        } else {
            current.completed = true;
            if (current.predecessor == -1) {
                int d1 = distance(current.stone_tube, current.stone_tube);
                cout << d1 << " right " << 0 << endl;
                current.stone_direction = 1;
                hash_to_room[make_pair(1, current.stone_tube)] = current_room_id;
            } else {
                Room& prev = rooms[current.predecessor];
                int d1 = distance(current.stone_tube, current.entrance_tube);
                int d2 = distance(current.stone_tube, current.entrance_tube);
                cout << d1 << " right " << d2 << endl;
                current.stone_direction = 1;
                current.stone_tube = current.entrance_tube;
                hash_to_room[make_pair(1, current.entrance_tube)] = current_room_id;
                traversal_stack.pop();
            }
        }
    }
    return 0;
}

