//=============================================================================
enum {
  SUCCESS,
  WSAINIT_ERROR,
  HOST_NOT_FOUND,
  SOCKET_ERROR_CODE,
  CONNECT_FAIL,
  SEND_ERROR,
  RECV_ERROR
};
//=============================================================================
int queryServer(const string& serverName, int serverPort, const string& query, string& response) {
  struct hostent *hostInfo = gethostbyname(serverName.c_str());
  if (!hostInfo) return HOST_NOT_FOUND;

  int sock_fd = socket(AF_INET, SOCK_STREAM, 0);
  if (sock_fd == -1) return SOCKET_ERROR_CODE;

  struct sockaddr_in serverAddr;
  memset((char *)&serverAddr, 0, sizeof(serverAddr));
  serverAddr.sin_family = hostInfo->h_addrtype;
  serverAddr.sin_port   = htons(serverPort);
  memcpy((char *)&(serverAddr.sin_addr), hostInfo->h_addr, hostInfo->h_length);

  int connectResult = connect(sock_fd, (struct sockaddr *)&serverAddr, sizeof(serverAddr));
  if (connectResult == SOCKET_ERROR) {
    closesocket(sock_fd);
    return CONNECT_FAIL;
  }

  string dataToSend = query;
  int bytesSent = send(sock_fd, dataToSend.c_str(), dataToSend.length(), 0);
  if (bytesSent == SOCKET_ERROR) {
    closesocket(sock_fd);
    return SEND_ERROR;
  }

  char recvBuffer[2048];
  memset(&recvBuffer, 0, sizeof(recvBuffer));
  int bytesRead = recv(sock_fd, recvBuffer, sizeof(recvBuffer) - 1, 0);
  if (bytesRead == SOCKET_ERROR) {
    closesocket(sock_fd);
    return RECV_ERROR;
  }

  recvBuffer[bytesRead] = '\0';
  closesocket(sock_fd);
  response = recvBuffer;
  return SUCCESS;
}
//=============================================================================
TServerProxy::TServerProxy(const string serverName, int portNumber)
    : m_hostName(serverName), m_portId(portNumber) {
#ifdef _WIN32
  WSADATA wsaData;
  WORD versionRequested = MAKEWORD(2, 2);
  int initResult = WSAStartup(versionRequested, &wsaData);
#endif
}
//-----------------------------------------------------------------------------
TServerProxy::~TServerProxy() {
#ifdef _WIN32
  WSACleanup();
#endif
}
//-----------------------------------------------------------------------------
bool TServerProxy::checkConnection() const {
  struct hostent *hostEntry = gethostbyname(m_hostName.c_str());
  if (!hostEntry) return false;

  int sock = socket(AF_INET, SOCK_STREAM, 0);
  if (sock == -1) return false;

  struct sockaddr_in addrStruct;
  memset((char *)&addrStruct, 0, sizeof(addrStruct));
  addrStruct.sin_family = hostEntry->h_addrtype;
  addrStruct.sin_port   = htons(m_portId);
  memcpy((char *)&(addrStruct.sin_addr), hostEntry->h_addr, hostEntry->h_length);

  bool connectionStatus = (SOCKET_ERROR != connect(sock, (struct sockaddr *)&addrStruct, sizeof(addrStruct)));
  closesocket(sock);
  return connectionStatus;
}
//-----------------------------------------------------------------------------
int TServerProxy::execute(int count, char *args[], string& result) {
  string command;
  assert(count >= 0);
  if (count > 0) {
    command = args[0];
    for (int index = 1; index < count; ++index) {
      command += ",";
      command += args[index];
    }
  }
  return queryServer(m_hostName, m_portId, command, result);
}

