static BOOL InitializeDefaults(void) {
    const char* config_file = GetIniPath();
    const char* section;
    char buffer[64];
    int entries_count = 0;

    section = "Registration";
    memset(buffer, 0, sizeof(buffer));
    if (GetPrivateProfileStringA(section, "Mayor Name", "", buffer, sizeof(buffer) - 1, config_file) > 0) {
        if (buffer[0] && strlen(buffer) > 0)
            entries_count++;
    }

    memset(buffer, 0, sizeof(buffer));
    if (GetPrivateProfileStringA(section, "Company Name", "", buffer, sizeof(buffer) - 1, config_file) > 0) {
        if (buffer[0] && strlen(buffer) > 0)
            entries_count++;
    }

    // Ensure shell registrations are updated regardless of previous install state
    HKEY hKeySC2, hKeyMIF;
    extern BOOL bFixFileAssociations;
    if (RegOpenKeyA(HKEY_CURRENT_USER, "Software\\Classes\\.sc2", &hKeySC2) != ERROR_SUCCESS ||
        RegOpenKeyA(HKEY_CURRENT_USER, "Software\\Classes\\.mif", &hKeyMIF) != ERROR_SUCCESS ||
        bFixFileAssociations) {
        ResetFileAssociations();
    } else {
        RegCloseKey(hKeySC2);
        RegCloseKey(hKeyMIF);
        if (debug_level & REGISTRY_DEBUG_FILEASSOCIATIONS)
            ConsoleLog(LOG_DEBUG, "MISC: Skipping shell class registry due to existing .sc2 and .mif entries.\n");
    }

    // Determine if installation is needed
    section = "Portable";
    if (GetPrivateProfileIntA(section, "Installed", 0, config_file) == 1) {
        if (entries_count == 2)
            return FALSE;
    }

    WritePrivateProfileIntA(section, "Installed", 1, config_file);

    // Prompt user for configuration
    DialogBox(hSC2KFixModule, MAKEINTRESOURCE(IDD_INSTALL), NULL, SetupDialogProc);

    // Version info
    DWORD version_number = 0x00000100;
    section = "Version";
    WritePrivateProfileIntA(section, "SCURK", version_number, config_file);
    WritePrivateProfileIntA(section, "SimCity 2000", version_number, config_file);

    // Language settings
    section = "Localize";
    WritePrivateProfileStringA(section, "Language", "USA", config_file);

    // Default options
    section = "Options";
    WritePrivateProfileIntA(section, "Disasters", TRUE, config_file);
    WritePrivateProfileIntA(section, "Music", TRUE, config_file);
    WritePrivateProfileIntA(section, "Sound", TRUE, config_file);
    WritePrivateProfileIntA(section, "AutoGoto", TRUE, config_file);
    WritePrivateProfileIntA(section, "AutoBudget", FALSE, config_file);
    WritePrivateProfileIntA(section, "AutoSave", FALSE, config_file);
    WritePrivateProfileIntA(section, "Speed", INI_GAME_SPEED_SETTING(GAME_SPEED_LLAMA), config_file);

    // Editor defaults
    section = "SCURK";
    WritePrivateProfileIntA(section, "CycleColors", 1, config_file);
    WritePrivateProfileIntA(section, "GridHeight", 2, config_file);
    WritePrivateProfileIntA(section, "GridWidth", 2, config_file);
    WritePrivateProfileIntA(section, "ShowClipRegion", 0, config_file);
    WritePrivateProfileIntA(section, "ShowDrawGrid", 0, config_file);
    WritePrivateProfileIntA(section, "SnapToGrid", 0, config_file);
    WritePrivateProfileIntA(section, "Sound", 1, config_file);

    SaveSettings(TRUE);
    return TRUE;
}

