static BOOL IsRedirectedKey(HKEY hKey, int index) {
    if (index < keySoftware || index >= keyTotal)
        return FALSE;
    if (hKey == (HKEY)(HKEY_BASE_ADDRESS + index))
        return TRUE;
    return FALSE;
}

static BOOL IsVirtualKey(unsigned long key_value) {
    if ((key_value) >= (HKEY_BASE_ADDRESS + keySoftware) && (key_value) < (HKEY_BASE_ADDRESS + keyTotal))
        return TRUE;
    return FALSE;
}

static int FindRedirectIndex(HKEY hKey) {
    for (int i = 0; i < keyTotal; i++) {
        if (IsRedirectedKey(hKey, i))
            return i;
    }
    return keyTotal;
}

static BOOL MapSubKey(const char *subkey_name, unsigned long *mapped_key) {
    BOOL found = FALSE;
    if (_stricmp(subkey_name, "Software") == 0) {
        *mapped_key = keySoftware;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Maxis") == 0) {
        *mapped_key = keyMaxis;
        found = TRUE;
    } else if (_stricmp(subkey_name, primary_product_name) == 0) {
        *mapped_key = keyGame;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Paths") == 0) {
        *mapped_key = keyPaths;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Windows") == 0) {
        *mapped_key = keyWindows;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Version") == 0) {
        *mapped_key = keyVersion;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Options") == 0) {
        *mapped_key = keySettings;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Localize") == 0) {
        *mapped_key = keyLocalization;
        found = TRUE;
    } else if (_stricmp(subkey_name, "Registration") == 0) {
        *mapped_key = keyUser;
        found = TRUE;
    } else if (_stricmp(subkey_name, "SCURK") == 0) {
        *mapped_key = keyEditor;
        found = TRUE;
    }
    return found;
}

static const char *GetSectionName(HKEY hKey) {
    switch (FindRedirectIndex(hKey)) {
        case keyWindows:
            return "Windows";
        case keyVersion:
            return "Version";
        case keySettings:
            return "Options";
        case keyLocalization:
            return "Localize";
        case keyEditor:
            return "SCURK";
        default:
            break;
    }
    return NULL;
}

BOOL ValidateFilePath(const char *path) {
    return (path && PathFileExistsA(path)) ? TRUE : FALSE;
}

BOOL ValidateDirectoryPath(const char *path) {
    return (ValidateFilePath(path) && PathIsDirectoryA(path)) ? TRUE : FALSE;
}

static void OutputString(const char *source, LPBYTE buffer, LPDWORD size) {
    if (buffer == NULL)
        *size = strlen(source) + 1;
    else
        memcpy(buffer, source, *size);
}

static void OutputDWORD(DWORD value, LPBYTE buffer, LPDWORD size) {
    if (buffer == NULL)
        *size = sizeof(DWORD);
    else
        memcpy(buffer, &value, sizeof(DWORD));
}

static void ConstructFullPath(const char *base, const char *relative, LPBYTE buffer, LPDWORD size) {
    char full_path[MAX_PATH];
    sprintf_s(full_path, MAX_PATH, "%s\\%s", base, relative);
    OutputString(full_path, buffer, size);
}

static void ReadIniString(const char *section, const char *entry, const char *default_val, LPBYTE buffer, LPDWORD size) {
    const char *config_file = GetIniPath();
    char temp_buffer[64];
    GetPrivateProfileStringA(section, entry, default_val, temp_buffer, sizeof(temp_buffer) - 1, config_file);
    OutputString(temp_buffer, buffer, size);
}

static void ReadIniDWORD(const char *section, const char *entry, DWORD default_val, LPBYTE buffer, LPDWORD size) {
    const char *config_file = GetIniPath();
    OutputDWORD(GetPrivateProfileIntA(section, entry, default_val, config_file), buffer, size);
}

extern "C" LSTATUS __stdcall Hook_RegSetValueExA(HKEY hKey, LPCSTR value_name, DWORD reserved, DWORD type, const BYTE *data, DWORD data_size) {
    const char *section = GetSectionName(hKey);
    if (section) {
        const char *config_file = GetIniPath();
        if (type == REG_DWORD || (type == REG_BINARY && data_size == sizeof(DWORD)))
            WritePrivateProfileIntA(section, value_name, *(const DWORD*)data, config_file);
        return ERROR_SUCCESS;
    }

    if (debug_level & REGISTRY_DEBUG_REGISTRY)
        ConsoleLog(LOG_DEBUG, "MISC: 0x%08X -> RegSetValueExA(0x%08x, %s, 0x%08X, 0x%08X, 0x%08X, 0x%08X)\n", _ReturnAddress(), hKey, value_name,
            reserved, type, *data, data_size);
    return RegSetValueExA(hKey, value_name, reserved, type, data, data_size);
}

extern "C" LSTATUS __stdcall Hook_RegQueryValueExA(HKEY hKey, LPCSTR value_name, LPDWORD reserved, LPDWORD type, LPBYTE buffer, LPDWORD size) {
    if (IsRedirectedKey(hKey, keyPaths)) {
        char target_path[MAX_PATH];
        strcpy_s(target_path, MAX_PATH, szGamePath);

        if (_stricmp(value_name, "Goodies") == 0) {
            if (debug_level & REGISTRY_DEBUG_REGISTRY)
                ConsoleLog(LOG_DEBUG, "MISC: 0x%08X -> Query Adjustment - %s -> %s\n", _ReturnAddress(), value_name, "MOVIES");
            ConstructFullPath(target_path, "Movies", buffer, size);
        }
        else if (_stricmp(value_name, "Cities") == 0 || _stricmp(value_name, "SaveGame") == 0) {
            if (ValidateDirectoryPath(last_city_path) && dwDetectedVersion == VERSION_SC2K_1996)
                OutputString(last_city_path, buffer, size);
            else
                ConstructFullPath(target_path, "Cities", buffer, size);
        }
        else if (_stricmp(value_name, "Data") == 0)
            ConstructFullPath(target_path, "Data", buffer, size);
        else if (_stricmp(value_name, "Graphics") == 0)
            ConstructFullPath(target_path, "Bitmaps", buffer, size);
        else if (_stricmp(value_name, "Home") == 0)
            OutputString(target_path, buffer, size);
        else if (_stricmp(value_name, "Music") == 0)
            ConstructFullPath(target_path, "Sounds", buffer, size);
        else if (_stricmp(value_name, "Scenarios") == 0)
            ConstructFullPath(target_path, "Scenario", buffer, size);
        else if (_stricmp(value_name, "TileSets") == 0) {
            if (ValidateDirectoryPath(last_tileset_path) && dwDetectedVersion == VERSION_SC2K_1996)
                OutputString(last_tileset_path, buffer, size);
            else
                ConstructFullPath(target_path, "ScurkArt", buffer, size);
        }
        return ERROR_SUCCESS;
    }

    if (IsRedirectedKey(hKey, keyWindows)) {
        if (_stricmp(value_name, "Display") == 0)
            ReadIniString("Windows", value_name, "8 1", buffer, size);
        else if (_stricmp(value_name, "Color Check") == 0)
            ReadIniDWORD("Windows", value_name, 0, buffer, size);
        else if (_stricmp(value_name, "Last Color Depth") == 0)
            ReadIniDWORD("Windows", value_name, 20, buffer, size);
        return ERROR_SUCCESS;
    }

    if (IsRedirectedKey(hKey, keyVersion)) {
        if (_stricmp(value_name, "SimCity 2000") == 0)
            ReadIniDWORD("Version", value_name, 256, buffer, size);
        else if (_stricmp(value_name, "SCURK") == 0)
            ReadIniDWORD("Version", value_name, 256, buffer, size);
        return ERROR_SUCCESS;
    }

    if (IsRedirectedKey(hKey, keySettings)) {
        if (_stricmp(value_name, "Disasters") == 0)
            ReadIniDWORD("Options", value_name, 1, buffer, size);
        else if (_stricmp(value_name, "Music") == 0)
            ReadIniDWORD("Options", value_name, 1, buffer, size);
        else if (_stricmp(value_name, "Sound") == 0)
            ReadIniDWORD("Options", value_name, 1, buffer, size);
        else if (_stricmp(value_name, "AutoGoto") == 0)
            ReadIniDWORD("Options", value_name, 1, buffer, size);
        else if (_stricmp(value_name, "AutoBudget") == 0)
            ReadIniDWORD("Options", value_name, 0, buffer, size);
        else if (_stricmp(value_name, "AutoSave") == 0)
            ReadIniDWORD("Options", value_name, 0, buffer, size);
        else if (_stricmp(value_name, "Speed") == 0)
            ReadIniDWORD("Options", value_name, INI_GAME_SPEED_SETTING(GAME_SPEED_LLAMA), buffer, size);
        return ERROR_SUCCESS;
    }

    if (IsRedirectedKey(hKey, keyLocalization)) {
        if (_stricmp(value_name, "Language") == 0)
            ReadIniString("Localize", value_name, "USA", buffer, size);
        return ERROR_SUCCESS;
    }

    if (IsRedirectedKey(hKey, keyUser)) {
        if (_stricmp(value_name, "Mayor Name") == 0)
            ReadIniString("Registration", value_name, szSettingsMayorName, buffer, size);
        else if (_stricmp(value_name, "Company Name") == 0)
            ReadIniString("Registration", value_name, szSettingsCompanyName, buffer, size);
        return ERROR_SUCCESS;
    }

    if (IsRedirectedKey(hKey, keyEditor)) {
        if (_stricmp(value_name, "CycleColors") == 0)
            ReadIniDWORD("SCURK", value_name, 1, buffer, size);
        else if (_stricmp(value_name, "GridHeight") == 0)
            ReadIniDWORD("SCURK", value_name, 2, buffer, size);
        else if (_stricmp(value_name, "GridWidth") == 0)
            ReadIniDWORD("SCURK", value_name, 2, buffer, size);
        else if (_stricmp(value_name, "ShowClipRegion") == 0)
            ReadIniDWORD("SCURK", value_name, 0, buffer, size);
        else if (_stricmp(value_name, "ShowDrawGrid") == 0)
            ReadIniDWORD("SCURK", value_name, 0, buffer, size);
        else if (_stricmp(value_name, "SnapToGrid") == 0)
            ReadIniDWORD("SCURK", value_name, 0, buffer, size);
        else if (_stricmp(value_name, "Sound") == 0)
            ReadIniDWORD("SCURK", value_name, 1, buffer, size);
        return ERROR_SUCCESS;
    }

    if (debug_level & REGISTRY_DEBUG_REGISTRY)
        ConsoleLog(LOG_DEBUG, "MISC: 0x%08X -> RegQueryValueExA(0x%08x, %s, 0x%08X, 0x%08X, 0x%08X, 0x%08X)\n", _ReturnAddress(), hKey, value_name,
            reserved, *type, buffer, size);
    return RegQueryValueExA(hKey, value_name, reserved, type, buffer, size);
}

extern "C" LSTATUS __stdcall Hook_RegCreateKeyExA(HKEY hKey, LPCSTR subkey, DWORD reserved, LPSTR class_name, DWORD options, REGSAM desired,
    const LPSECURITY_ATTRIBUTES security, PHKEY result, LPDWORD disposition) {
    unsigned long mapped_key = 0;
    if (MapSubKey(subkey, &mapped_key)) {
        *result = (HKEY)(HKEY_BASE_ADDRESS + mapped_key);
        return ERROR_SUCCESS;
    }

    if (debug_level & REGISTRY_DEBUG_REGISTRY)
        ConsoleLog(LOG_DEBUG, "MISC: 0x%08X -> RegCreateKeyExA(0x%08x, %s, ...)\n", _ReturnAddress(), hKey, subkey);
    return RegCreateKeyExA(hKey, subkey, reserved, class_name, options, desired, security, result, disposition);
}

extern "C" LSTATUS __stdcall Hook_RegOpenKeyExA(HKEY hKey, LPCSTR subkey, DWORD options, REGSAM desired, PHKEY result) {
    unsigned long mapped_key = 0;
    if (MapSubKey(subkey, &mapped_key)) {
        *result = (HKEY)(HKEY_BASE_ADDRESS + mapped_key);
        return ERROR_SUCCESS;
    }

    if (debug_level & REGISTRY_DEBUG_REGISTRY)
        ConsoleLog(LOG_DEBUG, "MISC: 0x%08X -> RegOpenKeyExA(0x%08x, %s, ...)\n", _ReturnAddress(), hKey, subkey);
    return RegOpenKeyExA(hKey, subkey, options, desired, result);
}

extern "C" LSTATUS __stdcall Hook_RegCloseKey(HKEY hKey) {
    if (IsVirtualKey((unsigned long)hKey))
        return ERROR_SUCCESS;

    if (debug_level & REGISTRY_DEBUG_REGISTRY)
        ConsoleLog(LOG_DEBUG, "MISC: 0x%08X -> RegCloseKey(0x%08x)\n", _ReturnAddress(), hKey);
    return RegCloseKey(hKey);
}

