VulkanDevice::VulkanDevice(std::shared_ptr<VulkanInstance> instance, std::shared_ptr<VulkanSurface> surface, const VulkanCompatibleDevice& chosenDevice) : Instance(instance), Surface(surface)
{
	PhysicalDevice = *chosenDevice.Device;
	EnabledDeviceExtensions = chosenDevice.EnabledDeviceExtensions;
	EnabledFeatures = chosenDevice.EnabledFeatures;
	GraphicsFamily = chosenDevice.GraphicsFamily;
	PresentFamily = chosenDevice.PresentFamily;
	GraphicsTimeQueries = chosenDevice.GraphicsTimeQueries;
	try
	{
		InitializeDevice();
		InitializeAllocator();
	}
	catch (...)
	{
		CleanupResources();
		throw;
	}
}

VulkanDevice::~VulkanDevice()
{
	CleanupResources();
}

bool VulkanDevice::HasExtension(const char* ext) const
{
	return
		EnabledDeviceExtensions.find(ext) != EnabledDeviceExtensions.end() ||
		Instance->EnabledExtensions.find(ext) != Instance->EnabledExtensions.end();
}

void VulkanDevice::InitializeAllocator()
{
	VmaAllocatorCreateInfo allocParams = {};
	allocParams.vulkanApiVersion = Instance->ApiVersion;
	if (HasExtension(VK_KHR_DEDICATED_ALLOCATION_EXTENSION_NAME) && HasExtension(VK_KHR_GET_MEMORY_REQUIREMENTS_2_EXTENSION_NAME))
		allocParams.flags |= VMA_ALLOCATOR_CREATE_KHR_DEDICATED_ALLOCATION_BIT;
	if (HasExtension(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME))
		allocParams.flags |= VMA_ALLOCATOR_CREATE_BUFFER_DEVICE_ADDRESS_BIT;
	allocParams.physicalDevice = PhysicalDevice.Device;
	allocParams.device = device;
	allocParams.instance = Instance->Instance;
	allocParams.preferredLargeHeapBlockSize = 128 * 1024 * 1024;
	if (vmaCreateAllocator(&allocParams, &allocator) != VK_SUCCESS)
		VulkanError("Failed to initialize allocator");
}

void VulkanDevice::InitializeDevice()
{
	float queuePriority = 1.0f;
	std::vector<VkDeviceQueueCreateInfo> queueInitInfos;
	std::set<int> requiredFamilies;
	if (GraphicsFamily != -1)
		requiredFamilies.insert(GraphicsFamily);
	if (PresentFamily != -1)
		requiredFamilies.insert(PresentFamily);
	for (int index : requiredFamilies)
	{
		VkDeviceQueueCreateInfo queueInfo = {};
		queueInfo.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
		queueInfo.queueFamilyIndex = index;
		queueInfo.queueCount = 1;
		queueInfo.pQueuePriorities = &queuePriority;
		queueInitInfos.push_back(queueInfo);
	}

	std::vector<const char*> extensionList;
	extensionList.reserve(EnabledDeviceExtensions.size());
	for (const auto& name : EnabledDeviceExtensions)
		extensionList.push_back(name.c_str());

	VkDeviceCreateInfo deviceInitInfo = { VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO };
	deviceInitInfo.queueCreateInfoCount = static_cast<uint32_t>(queueInitInfos.size());
	deviceInitInfo.pQueueCreateInfos = queueInitInfos.data();
	deviceInitInfo.enabledExtensionCount = static_cast<uint32_t>(extensionList.size());
	deviceInitInfo.ppEnabledExtensionNames = extensionList.data();
	deviceInitInfo.enabledLayerCount = 0;

	VkPhysicalDeviceFeatures2 features2 = { VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2 };
	features2.features = EnabledFeatures.Features;
	void** nextPtr = const_cast<void**>(&deviceInitInfo.pNext);

	if (HasExtension(VK_KHR_GET_PHYSICAL_DEVICE_PROPERTIES_2_EXTENSION_NAME))
	{
		*nextPtr = &features2;
		nextPtr = &features2.pNext;
	}
	else // legacy vulkan 1.0 feature specification
	{
		deviceInitInfo.pEnabledFeatures = &features2.features;
	}

	if (HasExtension(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME))
	{
		*nextPtr = &EnabledFeatures.BufferDeviceAddress;
		nextPtr = &EnabledFeatures.BufferDeviceAddress.pNext;
	}

	if (HasExtension(VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME))
	{
		*nextPtr = &EnabledFeatures.AccelerationStructure;
		nextPtr = &EnabledFeatures.AccelerationStructure.pNext;
	}

	if (HasExtension(VK_KHR_RAY_QUERY_EXTENSION_NAME))
	{
		*nextPtr = &EnabledFeatures.RayQuery;
		nextPtr = &EnabledFeatures.RayQuery.pNext;
	}

	if (HasExtension(VK_EXT_DESCRIPTOR_INDEXING_EXTENSION_NAME))
	{
		*nextPtr = &EnabledFeatures.DescriptorIndexing;
		nextPtr = &EnabledFeatures.DescriptorIndexing.pNext;
	}

	VkResult res = vkCreateDevice(PhysicalDevice.Device, &deviceInitInfo, nullptr, &device);
	CheckVulkanError(res, "Failed to create Vulkan device");
	volkLoadDevice(device);

	if (GraphicsFamily != -1)
		vkGetDeviceQueue(device, GraphicsFamily, 0, &GraphicsQueue);
	if (PresentFamily != -1)
		vkGetDeviceQueue(device, PresentFamily, 0, &PresentQueue);
}

void VulkanDevice::CleanupResources()
{
	if (device)
		vkDeviceWaitIdle(device);
	if (allocator)
		vmaDestroyAllocator(allocator);
	if (device)
		vkDestroyDevice(device, nullptr);
	device = nullptr;
}

void VulkanDevice::SetDebugName(const char* name, uint64_t handle, VkObjectType type)
{
	if (!DebugLayerActive) return;
	VkDebugUtilsObjectNameInfoEXT info = {};
	info.sType = VK_STRUCTURE_TYPE_DEBUG_UTILS_OBJECT_NAME_INFO_EXT;
	info.objectHandle = handle;
	info.objectType = type;
	info.pObjectName = name;
	vkSetDebugUtilsObjectNameEXT(device, &info);
}

