template <typename T>
inline std::vector<T> merge_vectors(const std::vector<T> &first,
                                    const std::vector<T> &second) {
  std::vector<T> output;
  output.reserve(first.size() + second.size());
  output.insert(output.end(), first.begin(), first.end());
  output.insert(output.end(), second.begin(), second.end());
  return output;
}

}  // namespace

LaunchContextBuilder::LaunchContextBuilder(CallableBase *func_kernel)
    : kernel_(func_kernel),
      owned_ctx_(std::make_unique<RuntimeContext>()),
      ctx_(owned_ctx_.get()),
      arg_buffer_(std::make_unique<char[]>(kernel_->args_size)),
      result_buffer_(std::make_unique<char[]>(kernel_->ret_size)),
      ret_type_(kernel_->ret_type),
      arg_buffer_size(kernel_->args_size),
      args_type(kernel_->args_type),
      result_buffer_size(kernel_->ret_size) {
  ctx_->result_buffer = reinterpret_cast<uint64 *>(result_buffer_.get());
  ctx_->arg_buffer = arg_buffer_.get();
}

void LaunchContextBuilder::duplicate(const LaunchContextBuilder &source) {
  QD_ASSERT(kernel_ == source.kernel_);
  QD_ASSERT(array_runtime_sizes.empty());
  QD_ASSERT(device_allocation_type.empty());
  QD_ASSERT(array_ptrs.empty());

  std::memcpy(arg_buffer_.get(), source.arg_buffer_.get(), kernel_->args_size);
  array_runtime_sizes = source.array_runtime_sizes;
  device_allocation_type = source.device_allocation_type;
  array_ptrs = source.array_ptrs;
}

void LaunchContextBuilder::assign_float(int param_id, float64 value) {
  auto dtype = kernel_->args_type->get_element_type(std::array{param_id});
  QD_ASSERT_INFO(dtype->is<PrimitiveType>(),
                 "Assigning scalar value to external (numpy) array argument is "
                 "not allowed.");
  PrimitiveTypeID type_id = dtype->as<PrimitiveType>()->type;
  switch (type_id) {
#define PER_C_TYPE(tp, ctype)   \
  case PrimitiveTypeID::tp:     \
    assign_scalar(param_id, (ctype)value); \
    break;
#include "quadrants/inc/data_type_with_c_type.inc.h"
#undef PER_C_TYPE
    case PrimitiveTypeID::f16: {
      uint16 half_val = fp16_ieee_from_fp32_value(static_cast<float32>(value));
      assign_scalar(param_id, half_val);
      break;
    }
    default:
      QD_NOT_IMPLEMENTED
  }
}

void LaunchContextBuilder::assign_multiple_floats(const std::vector<int> &ids,
                                                  const std::vector<float64> &vals) {
  const size_t count = ids.size();
  QD_ASSERT(count == vals.size());
  for (int idx = 0; idx < static_cast<int>(count); ++idx) {
    assign_float(ids[idx], vals[idx]);
  }
}

template <typename T, std::size_t N>
void LaunchContextBuilder::assign_struct_value(const std::array<int, N> &indices,
                                               T val) {
  auto dtype = kernel_->args_type->get_element_type(indices);
  QD_ASSERT(dtype->template is<PrimitiveType>() || dtype->template is<PointerType>());
  if (dtype->template is<PointerType>()) {
    assign_struct_value_impl(indices, static_cast<uint64>(val));
    return;
  }
  PrimitiveTypeID type_id = dtype->template as<PrimitiveType>()->type;
  switch (type_id) {
#define PER_C_TYPE(tp, ctype)                    \
  case PrimitiveTypeID::tp:                      \
    assign_struct_value_impl(indices, (ctype)val); \
    break;
#include "quadrants/inc/data_type_with_c_type.inc.h"
#undef PER_C_TYPE
    case PrimitiveTypeID::f16: {
      uint16 half_val = fp16_ieee_from_fp32_value(static_cast<float32>(val));
      assign_struct_value_impl(indices, half_val);
      break;
    }
    default:
      QD_NOT_IMPLEMENTED
  }
}

template <std::size_t... I>
constexpr auto vector_to_array(const std::vector<int> &vec,
                               std::index_sequence<I...>) {
  return std::array<int, sizeof...(I)>{vec[I]...};
}

template <typename T>
void LaunchContextBuilder::assign_struct_value(const std::vector<int> &indices,
                                               T val) {
  switch (indices.size()) {
#define CASE(N)                                                       \
  case N: {                                                           \
    return assign_struct_value(                                       \
        vector_to_array(indices, std::make_index_sequence<N>{}), val); \
  }
    CASE(1)
    CASE(2)
    CASE(3)
    CASE(4)
    CASE(5)
    CASE(6)
    CASE(7)
#undef CASE
    default:
      QD_NOT_IMPLEMENTED
  }
}

void LaunchContextBuilder::assign_ndarray_pointers(int param_id,
                                                   uint64 data_ptr,
                                                   uint64 grad_ptr) {
  assign_struct_value(std::array{param_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY},
                      data_ptr);
  if (kernel_->nested_parameters[param_id].needs_grad) {
    assign_struct_value(std::array{param_id, TypeFactory::GRAD_PTR_POS_IN_NDARRAY},
                        grad_ptr);
  }
}

