void LaunchContextBuilder::assign_integer(int param_id, int64 value) {
  auto dtype = kernel_->args_type->get_element_type(std::array{param_id});
  QD_ASSERT_INFO(dtype->is<PrimitiveType>(),
                 "Assigning scalar value to external (numpy) array argument is "
                 "not allowed.");
  if (dtype->is_primitive(PrimitiveTypeID::i32)) {
    assign_scalar(param_id, static_cast<int32>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::i64)) {
    assign_scalar(param_id, static_cast<int64>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::i8)) {
    assign_scalar(param_id, static_cast<int8>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::i16)) {
    assign_scalar(param_id, static_cast<int16>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::u1)) {
    assign_scalar(param_id, static_cast<uint1>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::u8)) {
    assign_scalar(param_id, static_cast<uint8>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::u16)) {
    assign_scalar(param_id, static_cast<uint16>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::u32)) {
    assign_scalar(param_id, static_cast<uint32>(value));
  } else if (dtype->is_primitive(PrimitiveTypeID::u64)) {
    assign_scalar(param_id, static_cast<uint64>(value));
  } else {
    QD_INFO(dtype->to_string());
    QD_NOT_IMPLEMENTED
  }
}

