template <>
void LaunchContextBuilder::assign<TypedConstant>(int param_id, TypedConstant val) {
  if (is_real(val.dt)) {
    assign_float(param_id, val.val_float());
  } else if (is_signed(val.dt)) {
    assign_integer(param_id, val.val_int());
  } else {
    assign_unsigned(param_id, val.val_uint());
  }
}

template <typename T, std::size_t N>
void LaunchContextBuilder::assign_struct_value_impl(
    const std::array<int, N> &indices,
    T val) {
  int offset = args_type->get_element_offset(indices);
  QD_ASSERT(offset + sizeof(T) <= arg_buffer_size);
  *(T *)(ctx_->arg_buffer + offset) = val;
}

template <typename T>
T LaunchContextBuilder::fetch_argument(const std::vector<int> &indices) {
  return fetch_struct_value<T>(indices);
}

template <typename T>
T LaunchContextBuilder::fetch_struct_value(std::vector<int> indices) {
  int offset = args_type->get_element_offset(indices);
  QD_ASSERT(offset + sizeof(T) <= arg_buffer_size);
  return *(T *)(ctx_->arg_buffer + offset);
}

template <typename T>
void LaunchContextBuilder::assign_scalar(int param_id, T val) {
  assign_struct_value_impl(std::array{param_id}, val);
  set_array_device_allocation_type(param_id, DevAllocType::kNone);
}

template <typename T>
T LaunchContextBuilder::fetch_result(int index) {
  return quadrants_union_cast_with_different_sizes<T>(ctx_->result_buffer[index]);
}

