void LaunchContextBuilder::assign_external_array_with_shape(
    int param_id,
    uintptr_t ptr,
    uint64 total_elements,
    const std::vector<int64> &dims,
    uintptr_t grad_ptr) {
  QD_ASSERT_INFO(
      kernel_->nested_parameters[param_id].is_array,
      "Assigning external (numpy) array to scalar argument is not allowed.");
  QD_ASSERT_INFO(dims.size() <= quadrants_max_num_indices,
                 "External array cannot have > {max_num_indices} indices");
  array_ptrs[{param_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY}] = reinterpret_cast<void *>(ptr);
  if (grad_ptr != 0) {
    array_ptrs[{param_id, TypeFactory::GRAD_PTR_POS_IN_NDARRAY}] =
        reinterpret_cast<void *>(grad_ptr);
  }
  set_array_runtime_size(param_id, total_elements);
  set_array_device_allocation_type(param_id, DevAllocType::kNone);
  for (int dim_idx = 0; dim_idx < static_cast<int>(dims.size()); ++dim_idx) {
    assign_struct_value(std::array{param_id, 0, dim_idx}, static_cast<int32>(dims[dim_idx]));
  }
}

void LaunchContextBuilder::assign_ndarray(int param_id, const Ndarray &arr) {
  intptr_t ptr = arr.get_device_allocation_ptr_as_int();
  QD_ASSERT_INFO(arr.shape.size() <= quadrants_max_num_indices,
                 "External array cannot have > {max_num_indices} indices");
  assign_ndarray_impl(param_id, ptr, arr.shape);
}

void LaunchContextBuilder::assign_multiple_ndarrays(
    const std::vector<int> &param_ids,
    const std::vector<Ndarray *> &arrays) {
  const size_t count = param_ids.size();
  array_ptrs.reserve(array_ptrs.size() + count);
  array_runtime_sizes.reserve(array_runtime_sizes.size() + count);
  device_allocation_type.reserve(device_allocation_type.size() + count);
  QD_ASSERT(count == param_ids.size());
  for (int idx = 0; idx < static_cast<int>(count); ++idx) {
    const int param_id = param_ids[idx];
    const Ndarray &arr = *arrays[idx];
    intptr_t ptr = arr.get_device_allocation_ptr_as_int();
    array_ptrs[{param_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY}] = reinterpret_cast<void *>(ptr);
    set_array_device_allocation_type(param_id, DevAllocType::kNdarray);
    const std::vector<int> &shape = arr.shape;
    size_t total_elements = 1;
    for (int dim_idx = 0; dim_idx < static_cast<int>(shape.size()); ++dim_idx) {
      assign_struct_value(std::array{param_id, 0, dim_idx}, static_cast<int32>(shape[dim_idx]));
      total_elements *= shape[dim_idx];
    }
    set_array_runtime_size(param_id, total_elements);
  }
}

void LaunchContextBuilder::assign_ndarray_with_gradient(int param_id,
                                                        const Ndarray &arr,
                                                        const Ndarray &grad_arr) {
  intptr_t ptr = arr.get_device_allocation_ptr_as_int();
  intptr_t grad_ptr = grad_arr.get_device_allocation_ptr_as_int();
  QD_ASSERT_INFO(arr.shape.size() <= quadrants_max_num_indices,
                 "External array cannot have > {max_num_indices} indices");
  assign_ndarray_impl(param_id, ptr, arr.shape, grad_ptr);
}

void LaunchContextBuilder::assign_multiple_ndarrays_with_gradients(
    const std::vector<int> &param_ids,
    const std::vector<Ndarray *> &arrays,
    const std::vector<Ndarray *> &grad_arrays) {
  const size_t count = param_ids.size();
  QD_ASSERT(count == arrays.size());
  QD_ASSERT(count == grad_arrays.size());
  for (int idx = 0; idx < static_cast<int>(count); ++idx) {
    assign_ndarray_with_gradient(param_ids[idx], *arrays[idx], *grad_arrays[idx]);
  }
}

void LaunchContextBuilder::assign_ndarray_impl(int param_id,
                                               intptr_t dev_alloc_ptr,
                                               const std::vector<int> &dims,
                                               intptr_t dev_alloc_grad_ptr) {
  array_ptrs[{param_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY}] =
      reinterpret_cast<void *>(dev_alloc_ptr);
  if (dev_alloc_grad_ptr != 0) {
    array_ptrs[{param_id, TypeFactory::GRAD_PTR_POS_IN_NDARRAY}] =
        reinterpret_cast<void *>(dev_alloc_grad_ptr);
  }
  set_array_device_allocation_type(param_id, DevAllocType::kNdarray);
  QD_ASSERT(dims.size() <= quadrants_max_num_indices);
  size_t total_elements = 1;
  for (int dim_idx = 0; dim_idx < static_cast<int>(dims.size()); ++dim_idx) {
    assign_struct_value(std::array{param_id, 0, dim_idx}, static_cast<int32>(dims[dim_idx]));
    total_elements *= dims[dim_idx];
  }
  set_array_runtime_size(param_id, total_elements);
}

void LaunchContextBuilder::assign_matrix(int param_id, const Matrix &matrix) {
  int element_size = data_type_size(matrix.dtype());
  for (int elem_idx = 0; elem_idx < matrix.length(); ++elem_idx) {
    switch (element_size) {
      case 1:
        assign_struct_value_impl(std::array{param_id, elem_idx},
                                 quadrants_union_cast_with_different_sizes<int8>(
                                     reinterpret_cast<uint8_t *>(matrix.data())[elem_idx]));
        break;
      case 2:
        assign_struct_value_impl(
            std::array{param_id, elem_idx},
            quadrants_union_cast_with_different_sizes<int16>(
                reinterpret_cast<uint16_t *>(matrix.data())[elem_idx]));
        break;
      case 4:
        assign_struct_value_impl(
            std::array{param_id, elem_idx},
            quadrants_union_cast_with_different_sizes<int32>(
                reinterpret_cast<uint32_t *>(matrix.data())[elem_idx]));
        break;
      case 8:
        assign_struct_value_impl(
            std::array{param_id, elem_idx},
            quadrants_union_cast_with_different_sizes<int64>(
                reinterpret_cast<uint64_t *>(matrix.data())[elem_idx]));
        break;
      default:
        QD_ERROR("Unsupported type size {}", element_size);
    }
  }
}

TypedConstant LaunchContextBuilder::retrieve_return_value(const std::vector<int> &index) {
  const Type *dtype = ret_type_->get_element_type(index);
