TypedConstant LaunchContextBuilder::retrieve_return_value_impl(int offset, const Type *dtype) {
  QD_ASSERT(dtype->is<PrimitiveType>());
  auto primitive_type = dtype->as<PrimitiveType>();
  char *buffer_ptr = result_buffer_.get() + offset;
  switch (primitive_type->type) {
#define PER_C_TYPE(type, ctype) \
  case PrimitiveTypeID::type:   \
    return TypedConstant(*(ctype *)buffer_ptr);
#include "quadrants/inc/data_type_with_c_type.inc.h"
#undef PER_C_TYPE
    case PrimitiveTypeID::f16: {
      uint16 half_val = *(uint16 *)buffer_ptr;
      return TypedConstant(fp16_ieee_to_fp32_value(half_val));
    }
    default:
      QD_NOT_IMPLEMENTED
  }
}

