using namespace std;

// Normalize a numeric string by removing leading zeros
string cleanNumber(string num) {
    if (num.empty()) return "0";
    size_t firstNonZero = num.find_first_not_of('0');
    if (firstNonZero == string::npos) return "0";
    return num.substr(firstNonZero);
}

// Add two large numbers represented as strings
string addLargeNumbers(string first, string second) {
    if (first == "0") return second;
    if (second == "0") return first;

    string A = first;
    string B = second;
    reverse(A.begin(), A.end());
    reverse(B.begin(), B.end());

    size_t maxLength = max(A.size(), B.size());
    A.resize(maxLength, '0');
    B.resize(maxLength, '0');

    string result(maxLength + 1, '0');
    int carry = 0;

    for (size_t i = 0; i < maxLength; ++i) {
        int digitSum = (A[i] - '0') + (B[i] - '0') + carry;
        result[i] = (digitSum % 10) + '0';
        carry = digitSum / 10;
    }

    result[maxLength] = carry + '0';
    reverse(result.begin(), result.end());

    size_t startPos = result.find_first_not_of('0');
    if (startPos == string::npos) return "0";
    return result.substr(startPos);
}

// Subtract two large numbers represented as strings (assumes first >= second)
string subtractLargeNumbers(string minuend, string subtrahend) {
    if (subtrahend == "0") return minuend;
    if (minuend == subtrahend) return "0";

    string A = minuend;
    string B = subtrahend;
    reverse(A.begin(), A.end());
    reverse(B.begin(), B.end());

    size_t length = A.size();
    B.resize(length, '0');

    string diff(length, '0');
    int borrow = 0;

    for (size_t i = 0; i < length; ++i) {
        int difference = (A[i] - '0') - (B[i] - '0') - borrow;
        if (difference < 0) {
            difference += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }
        diff[i] = difference + '0';
    }

    reverse(diff.begin(), diff.end());

    size_t startPos = diff.find_first_not_of('0');
    if (startPos == string::npos) return "0";
    return diff.substr(startPos);
}

int main() {
    int itemCount;
    string capacityStr;
    cin >> itemCount >> capacityStr;
    capacityStr = cleanNumber(capacityStr);

    vector<string> weights(itemCount);
    for (auto& w : weights) {
        cin >> w;
        w = cleanNumber(w);
    }

    vector<pair<string, int>> items(itemCount);
    for (int idx = 0; idx < itemCount; idx++) {
        items[idx] = {weights[idx], idx};
    }

    // Custom comparator for comparing large number strings
    auto compareBigNumbers = [](const string& num1, const string& num2) -> int {
        if (num1.length() > num2.length()) return 1;
        if (num1.length() < num2.length()) return -1;
        if (num1 > num2) return 1;
        if (num1 < num2) return -1;
        return 0;
    };

    // Sort items in descending order based on their numeric value
    sort(items.begin(), items.end(), [&](const pair<string, int>& item1, const pair<string, int>& item2) {
        return compareBigNumbers(item1.first, item2.first) > 0;
    });

    vector<int> selected(itemCount, 0);
    string currentSum = "0";

    // Greedy selection of items
    for (auto& item : items) {
        string tentativeSum = addLargeNumbers(currentSum, item.first);
        if (compareBigNumbers(tentativeSum, capacityStr) <= 0) {
            currentSum = tentativeSum;
            selected[item.second] = 1;
        }
    }

    string remainingCapacity = subtractLargeNumbers(capacityStr, currentSum);

    // Try to improve solution by adding smallest unused item if beneficial
    if (compareBigNumbers(remainingCapacity, "0") > 0) {
        string smallestCandidate = "";
        int bestIndex = -1;

        for (int i = 0; i < itemCount; i++) {
            if (selected[i] == 0 && compareBigNumbers(weights[i], "0") > 0) {
                if (bestIndex == -1 || compareBigNumbers(weights[i], smallestCandidate) < 0) {
                    smallestCandidate = weights[i];
                    bestIndex = i;
                }
            }
        }

        if (bestIndex != -1) {
            string newSum = addLargeNumbers(currentSum, smallestCandidate);
            string excess = subtractLargeNumbers(newSum, capacityStr);
            if (compareBigNumbers(excess, remainingCapacity) < 0) {
                selected[bestIndex] = 1;
            }
        }
    }

    // Output the selection result
    for (int i = 0; i < itemCount; i++) {
        if (i > 0) cout << " ";
        cout << selected[i];
    }
    cout << endl;

    return 0;
}

