FT6X36* FT6X36::_instance = nullptr;

FT6X36::FT6X36(TwoWire* bus, int8_t irqPin) {
    _instance = this;
    _wire = bus;
    _intPin = irqPin;
}

FT6X36::~FT6X36() {
    detachInterrupt(digitalPinToInterrupt(_intPin));
}

void ISR_ATTR FT6X36::isr() {
    if (_instance) _instance->onInterrupt();
}

bool FT6X36::begin(uint8_t sensitivity) {
    if (readRegister8(FT6X36_REG_PANEL_ID) != FT6X36_VENDID) return false;
    uint8_t chipId = readRegister8(FT6X36_REG_CHIPID);
    if (chipId != FT6206_CHIPID && chipId != FT6236_CHIPID && chipId != FT6336_CHIPID) return false;

    pinMode(_intPin, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt(_intPin), FT6X36::isr, FALLING);

    writeRegister8(FT6X36_REG_DEVICE_MODE, 0x00);
    writeRegister8(FT6X36_REG_THRESHHOLD, sensitivity);
    writeRegister8(FT6X36_REG_TOUCHRATE_ACTIVE, 0x0E);

    return true;
}

void FT6X36::registerIsrHandler(void (*handler)()) {
    _isrHandler = handler;
}

void FT6X36::registerTouchHandler(void (*handler)(TPoint pt, TEvent evt)) {
    _touchHandler = handler;
}

uint8_t FT6X36::touched() {
    uint8_t count = readRegister8(FT6X36_REG_NUM_TOUCHES);
    if (count > 2) count = 0;
    return count;
}

void FT6X36::loop() {
    if (_irqPending) {
        _irqPending = false;
        processTouch();
    }
}

void FT6X36::processTouch() {
    readData();

    uint8_t idx = 0;
    TRawEvent ev = (TRawEvent)_touchEvent[idx];
    TPoint pos{_touchX[idx], _touchY[idx]};

    if (ev == TRawEvent::PressDown) {
        _points[0] = pos;
        _pointIdx = 1;
        _dragMode = false;
        _touchStartTime = millis();
        fireEvent(pos, TEvent::TouchStart);
    } else if (ev == TRawEvent::Contact) {
        if (_pointIdx < 10) {
            _points[_pointIdx] = pos;
            ++_pointIdx;
        }

        if (!_dragMode && _points[0].aboutEqual(pos) && millis() - _touchStartTime > 300) {
            _dragMode = true;
            fireEvent(pos, TEvent::DragStart);
        } else if (_dragMode) {
            fireEvent(pos, TEvent::DragMove);
        }
        fireEvent(pos, TEvent::TouchMove);
    } else if (ev == TRawEvent::LiftUp) {
        _points[9] = pos;
        _touchEndTime = millis();
        fireEvent(pos, TEvent::TouchEnd);

        if (_dragMode) {
            fireEvent(pos, TEvent::DragEnd);
            _dragMode = false;
        }

        if (_points[0].aboutEqual(pos) && (_touchEndTime - _touchStartTime) <= 300) {
            fireEvent(pos, TEvent::Tap);
            _points[0] = {0, 0};
            _touchStartTime = 0;
        }
    }
}

void FT6X36::onInterrupt() {
    _irqPending = true;
    if (_isrHandler) _isrHandler();
}

void FT6X36::readData() {
    const uint8_t bufSize = 16;
    uint8_t buffer[bufSize];

    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(0);
    _wire->endTransmission();
    _wire->requestFrom((uint8_t)FT6X36_ADDR, bufSize);

    for (uint8_t i = 0; i < bufSize; ++i) {
        buffer[i] = Wire.read();
    }

    #ifdef FT6X36_DEBUG
    Serial.println("REGISTER DUMP:");
    for (int16_t reg = 0; reg < bufSize; ++reg) {
        Serial.print("0x");
        Serial.print(reg, HEX);
        Serial.print(": 0x");
        Serial.println(buffer[reg], HEX);
    }
    Serial.println();
    Serial.print("ACTIVE TOUCHES: ");
    Serial.println(buffer[FT6X36_REG_NUM_TOUCHES]);
    Serial.print("GESTURE: ");
    Serial.println(buffer[FT6X36_REG_GESTURE_ID]);
    #endif

    _touches = buffer[FT6X36_REG_NUM_TOUCHES];

    const uint8_t offset = 6;
    for (uint8_t touch = 0; touch < 2; ++touch) {
        uint8_t base = FT6X36_REG_P1_XH + touch * offset;

        _touchX[touch] = buffer[base] & 0x0F;
        _touchX[touch] <<= 8;
        _touchX[touch] |= buffer[base + 1];

        _touchY[touch] = buffer[base + 2] & 0x0F;
        _touchY[touch] <<= 8;
        _touchY[touch] |= buffer[base + 3];

        _touchEvent[touch] = buffer[base] >> 6;
    }
}

void FT6X36::writeRegister8(uint8_t addr, uint8_t data) {
    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(addr);
    _wire->write(data);
    _wire->endTransmission();
}

uint8_t FT6X36::readRegister8(uint8_t addr) {
    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(addr);
    _wire->endTransmission();
    _wire->requestFrom((uint8_t)FT6X36_ADDR, 1);
    uint8_t val = _wire->read();

    #ifdef I2C_DEBUG
    Serial.print("REG 0x");
    Serial.print(addr, HEX);
    Serial.print(": 0x");
    Serial.println(val, HEX);
    #endif

    return val;
}

void FT6X36::fireEvent(TPoint pt, TEvent evt) {
    if (_touchHandler) _touchHandler(pt, evt);
}

