#include "test/jemalloc_test.h"
#include "jemalloc/internal/ph.h"

typedef struct tree_node_s tree_node_t;
ph_structs(priority_queue, tree_node_t);

struct tree_node_s {
#define NODE_SIGNATURE 0x1A2B3C4D
    uint32_t signature;
    priority_queue_link_t connection;
    uint64_t value;
};

static int
tree_node_compare(const tree_node_t *x, const tree_node_t *y) {
    int result;
    result = (x->value > y->value) - (x->value < y->value);
    if (result == 0) {
        /*
         * To maintain consistency, non-identical elements with identical
         * keys must follow an arbitrary ordering rule.
         */
        result = (((uintptr_t)x) > ((uintptr_t)y))
               - (((uintptr_t)x) < ((uintptr_t)y));
    }
    return result;
}

static int
tree_node_validate_and_compare(const tree_node_t *x, const tree_node_t *y) {
    expect_u32_eq(x->signature, NODE_SIGNATURE, "Invalid node marker");
    expect_u32_eq(y->signature, NODE_SIGNATURE, "Invalid node marker");
    return tree_node_compare(x, y);
}

ph_gen(static, priority_queue, tree_node_t, connection, tree_node_validate_and_compare);

static tree_node_t *
get_successor(const tree_node_t *node) {
    return phn_next_get((tree_node_t *)node, offsetof(tree_node_t, connection));
}

static tree_node_t *
get_predecessor(const tree_node_t *node) {
    return phn_prev_get((tree_node_t *)node, offsetof(tree_node_t, connection));
}

static tree_node_t *
get_left_child(const tree_node_t *node) {
    return phn_lchild_get((tree_node_t *)node, offsetof(tree_node_t, connection));
}

static void
display_tree(const tree_node_t *node, unsigned level) {
    unsigned i;
    tree_node_t *first_child, *next_sibling;

    for (i = 0; i < level; i++) {
        malloc_printf("    ");
    }
    malloc_printf("%2"FMTu64"\n", node->value);

    first_child = get_left_child(node);
    if (first_child == NULL) {
        return;
    }

    display_tree(first_child, level + 1);
    for (next_sibling = get_successor(first_child); next_sibling != NULL;
         next_sibling = get_successor(next_sibling)) {
        display_tree(next_sibling, level + 1);
    }
}

static void
print_priority_queue(const priority_queue_t *queue) {
    tree_node_t *auxiliary_node;
    malloc_printf("--- priority queue %p ---\n", queue);

    if (queue->pq_root == NULL) {
        goto cleanup;
    }

    display_tree(queue->pq_root, 0);
    for (auxiliary_node = get_successor(queue->pq_root); auxiliary_node != NULL;
         auxiliary_node = get_successor(auxiliary_node)) {
        expect_ptr_eq(get_successor(get_predecessor(auxiliary_node)), auxiliary_node,
            "Link integrity violation in auxiliary traversal");
        display_tree(auxiliary_node, 0);
    }

cleanup:
    malloc_printf("--- end of priority queue %p ---\n", queue);
}

static unsigned
validate_tree(const tree_node_t *node, const tree_node_t *parent) {
    unsigned count = 1;
    tree_node_t *first_child, *sibling;

    if (parent != NULL) {
        expect_d_ge(tree_node_validate_and_compare(node, parent), 0,
            "Heap property violated: child smaller than parent");
    }

    first_child = get_left_child(node);
    if (first_child == NULL) {
        return count;
    }

    expect_ptr_eq(get_predecessor(first_child),
        (void *)node, "First child does not link back to parent");

    count += validate_tree(first_child, node);

    for (sibling = get_successor(first_child); sibling != NULL;
         sibling = get_successor(sibling)) {
        expect_ptr_eq(get_successor(get_predecessor(sibling)), sibling,
            "Sibling link integrity violation");
        count += validate_tree(sibling, node);
    }

    return count;
}

static unsigned
verify_priority_queue(const priority_queue_t *queue) {
    unsigned total_nodes = 0;
    tree_node_t *auxiliary_node;

    if (queue->pq_root == NULL) {
        goto done;
    }

    total_nodes += validate_tree(queue->pq_root, NULL);

    for (auxiliary_node = get_successor(queue->pq_root); auxiliary_node != NULL;
         auxiliary_node = get_successor(auxiliary_node)) {
        expect_ptr_eq(get_successor(get_predecessor(auxiliary_node)), auxiliary_node,
            "Link integrity violation in root list");
        total_nodes += validate_tree(auxiliary_node, NULL);
    }

done:
    if (false) {
        print_priority_queue(queue);
    }
    return total_nodes;
}

TEST_BEGIN(test_empty_priority_queue) {
    priority_queue_t queue;
    priority_queue_new(&queue);

    expect_true(priority_queue_empty(&queue), "Queue should be empty initially");
    expect_ptr_null(priority_queue_first(&queue), "Expected no nodes in empty queue");
    expect_ptr_null(priority_queue_any(&queue), "Expected no nodes in empty queue");
}
TEST_END

static void
remove_node(priority_queue_t *queue, tree_node_t *node) {
    priority_queue_remove(queue, node);
    node->signature = 0;
}

static tree_node_t *
extract_minimum(priority_queue_t *queue) {
    tree_node_t *node = priority_queue_remove_first(queue);
    node->signature = 0;
    return node;
}

static tree_node_t *
extract_arbitrary(priority_queue_t *queue) {
    tree_node_t *node = priority_queue_remove_any(queue);
    node->signature = 0;
    return node;
}

