    tree_node_t nodes[NODE_COUNT];
    unsigned i, j, k;

    random_generator = init_gen_rand(RANDOM_SEED);

    for (i = 0; i < TEST_ITERATIONS; i++) {
        switch (i) {
        case 0:
            /* Sequential insertion */
            for (j = 0; j < NODE_COUNT; j++) {
                insertion_order[j] = j;
            }
            break;
        case 1:
            /* Reverse sequential insertion */
            for (j = 0; j < NODE_COUNT; j++) {
                insertion_order[j] = NODE_COUNT - j - 1;
            }
            break;
        default:
            for (j = 0; j < NODE_COUNT; j++) {
                insertion_order[j] = gen_rand64_range(random_generator, NODE_COUNT);
            }
        }

        for (j = 1; j <= NODE_COUNT; j++) {
            priority_queue_new(&queue);
            expect_u_eq(verify_priority_queue(&queue), 0, "Initial node count mismatch");

            for (k = 0; k < j; k++) {
                nodes[k].signature = NODE_SIGNATURE;
                nodes[k].value = insertion_order[k];
                priority_queue_insert(&queue, &nodes[k]);

                if (i % 17 == 16) {
                    expect_ptr_not_null(priority_queue_any(&queue),
                        "Queue should contain elements");
                    (void)priority_queue_first(&queue); // Force structural operations
                }

                expect_u_eq(verify_priority_queue(&queue), k + 1,
                    "Node count incorrect after insertion");
            }

            expect_false(priority_queue_empty(&queue), "Queue should not be empty");

            switch (i % 5) {
            case 0:
                for (k = 0; k < j; k++) {
                    expect_u_eq(verify_priority_queue(&queue), j - k,
                        "Node count incorrect before removal");
                    remove_node(&queue, &nodes[k]);
                    expect_u_eq(verify_priority_queue(&queue), j - k - 1,
                        "Node count incorrect after removal");
                }
                break;
            case 1:
                for (k = j; k > 0; k--) {
                    remove_node(&queue, &nodes[k-1]);
                    expect_u_eq(verify_priority_queue(&queue), k - 1,
                        "Node count incorrect after removal");
                }
                break;
            case 2: {
                tree_node_t *previous = NULL;
                for (k = 0; k < j; k++) {
                    tree_node_t *current = extract_minimum(&queue);
                    expect_u_eq(verify_priority_queue(&queue), j - k - 1,
                        "Node count incorrect after extraction");
                    if (previous != NULL) {
                        expect_d_ge(tree_node_compare(current, previous), 0,
                            "Extraction order violates heap property");
                    }
                    previous = current;
                }
                break;
            }
            case 3: {
                tree_node_t *previous = NULL;
                for (k = 0; k < j; k++) {
                    tree_node_t *current = priority_queue_first(&queue);
                    expect_u_eq(verify_priority_queue(&queue), j - k,
                        "Node count incorrect before removal");
                    if (previous != NULL) {
                        expect_d_ge(tree_node_compare(current, previous), 0,
                            "Removal order violates heap property");
                    }
                    remove_node(&queue, current);
                    expect_u_eq(verify_priority_queue(&queue), j - k - 1,
                        "Node count incorrect after removal");
                    previous = current;
                }
                break;
            }
            case 4: {
                for (k = 0; k < j; k++) {
                    extract_arbitrary(&queue);
                    expect_u_eq(verify_priority_queue(&queue), j - k - 1,
                        "Node count incorrect after arbitrary removal");
                }
                break;
            }
            default:
                not_reached();
            }

            expect_ptr_null(priority_queue_first(&queue),
                "Queue should be empty after full removal");
            expect_ptr_null(priority_queue_any(&queue),
                "Queue should be empty after full removal");
            expect_true(priority_queue_empty(&queue),
                "Queue should be empty after full removal");
        }
    }

    fini_gen_rand(random_generator);
#undef NODE_COUNT
#undef TEST_ITERATIONS
#undef RANDOM_SEED
}
TEST_END

int
main(void) {
    return test(
        test_empty_priority_queue,
        test_priority_queue_operations);
}

