DEFINE_bool(metrics_enabled, false, "Enable metrics collection");
DEFINE_string(metrics_server_port, "18081", "Port for metrics server");

bool DataSubstrate::InitializeMetrics(const INIReader &config_reader)
{
    /* Parse metrics configuration */
    metrics::enable_metrics =
        config_reader.GetBoolean("metrics", "metrics_enabled", false);
    DLOG(INFO) << "metrics_enabled: "
               << (metrics::enable_metrics ? "ACTIVE" : "INACTIVE");

    if (metrics::enable_metrics)
    {
        FLAGS_metrics_server_port = std::to_string(config_reader.GetInteger(
            "metrics", "metrics_server_port", std::stoi(FLAGS_metrics_server_port)));
        LOG(INFO) << "metrics_server_port: " << FLAGS_metrics_server_port;

        // Global metrics settings
        metrics::enable_memory_usage =
            config_reader.GetBoolean("metrics", "enable_memory_usage", true);
        LOG(INFO) << "enable_memory_usage: "
                  << (metrics::enable_memory_usage ? "ENABLED" : "DISABLED");

        if (metrics::enable_memory_usage)
        {
            metrics::collect_memory_usage_interval = config_reader.GetInteger(
                "metrics", "collect_memory_usage_interval", 10000);
            LOG(INFO) << "memory usage collection interval: "
                      << metrics::collect_memory_usage_interval << " rounds";
        }

        metrics::enable_cache_hit_rate =
            config_reader.GetBoolean("metrics", "enable_cache_hit_rate", true);
        LOG(INFO) << "enable_cache_hit_rate: "
                  << (metrics::enable_cache_hit_rate ? "ENABLED" : "DISABLED");

        // Transaction metrics
        metrics::enable_tx_metrics =
            config_reader.GetBoolean("metrics", "enable_tx_metrics", true);
        LOG(INFO) << "enable_tx_metrics: "
                  << (metrics::enable_tx_metrics ? "ENABLED" : "DISABLED");

        if (metrics::enable_tx_metrics)
        {
            metrics::collect_tx_duration_interval = config_reader.GetInteger(
                "metrics", "collect_tx_duration_interval", 100);
            LOG(INFO) << "transaction duration sampling interval: "
                      << metrics::collect_tx_duration_interval << " rounds";
        }

        // Busy round metrics
        metrics::enable_busy_round_metrics = config_reader.GetBoolean(
            "metrics", "enable_busy_round_metrics", true);
        LOG(INFO) << "enable_busy_round_metrics: "
                  << (metrics::enable_busy_round_metrics ? "ENABLED" : "DISABLED");

        if (metrics::enable_busy_round_metrics)
        {
            metrics::busy_round_threshold =
                config_reader.GetInteger("metrics", "busy_round_threshold", 10);
            LOG(INFO) << "busy round threshold set to "
                      << metrics::busy_round_threshold;
        }

        // Remote request metrics
        metrics::enable_remote_request_metrics =
            config_reader.GetBoolean("metrics",
                                     "enable_remote_request_metrics",
                                     metrics::enable_tx_metrics);
        LOG(INFO) << "enable_remote_request_metrics: "
                  << (metrics::enable_remote_request_metrics ? "ENABLED" : "DISABLED");

        if (core_config_.enable_data_store)
        {
            metrics::enable_kv_metrics =
                config_reader.GetBoolean("metrics", "enable_kv_metrics", true);
            LOG(INFO) << "enable_kv_metrics: "
                      << (metrics::enable_kv_metrics ? "ENABLED" : "DISABLED");

            metrics::enable_eloqstore_metrics = config_reader.GetBoolean(
                "metrics", "enable_eloqstore_metrics", true);
            LOG(INFO) << "enable_eloqstore_metrics: "
                      << (metrics::enable_eloqstore_metrics ? "ENABLED" : "DISABLED");
        }

#if (WITH_LOG_SERVICE)
        if (core_config_.enable_wal)
        {
            // log_service metrics
            metrics::enable_log_service_metrics = config_reader.GetBoolean(
                "metrics", "enable_log_service_metrics", true);
            LOG(INFO) << "enable_log_service_metrics: "
                      << (metrics::enable_log_service_metrics ? "ENABLED" : "DISABLED");
        }
#endif

        // Standby/failure metrics
        metrics::enable_standby_metrics =
            config_reader.GetBoolean("metrics", "enable_standby_metrics", true);
        LOG(INFO) << "standby metrics enabled: "
                  << (metrics::enable_standby_metrics ? "YES" : "NO");

        if (metrics::enable_standby_metrics)
        {
            metrics::collect_standby_metrics_interval = config_reader.GetInteger(
                "metrics", "collect_standby_metrics_interval", 10000);
            LOG(INFO) << "standby metrics collection interval: "
                      << metrics::collect_standby_metrics_interval << " rounds";
        }

#ifdef ELOQ_MODULE_ELOQSQL
        metrics::enable_mysql_tx_metrics = config_reader.GetBoolean(
            "metrics", "enable_mysql_tx_metrics", true);
        metrics::enable_mysql_dml_metrics = config_reader.GetBoolean(
            "metrics", "enable_mysql_dml_metrics", true);
#endif

        setenv("ELOQ_METRICS_PORT", FLAGS_metrics_server_port.c_str(), false);

        eloq_metrics_app::MetricsRegistryImpl::MetricsRegistryResult
            registry_result =
                eloq_metrics_app::MetricsRegistryImpl::GetRegistry();

        if (registry_result.not_ok_ != nullptr)
        {
            LOG(ERROR)
                << "!!!!!!!! Failed to initialize MetricsRegistry !!!!!!!!";
            return false;
        }

        metrics_registry_ = registry_result.metrics_registry_;

#ifdef ELOQ_MODULE_ELOQSQL
        metrics::CommonLabels mysql_labels{};
        mysql_labels["node_ip"] = network_config_.local_ip;
        mysql_labels["node_port"] =
            std::to_string(network_config_.local_port);
        metrics::register_mysql_metrics(metrics_registry_.get(),
                                        mysql_labels);
#endif

#ifdef ELOQ_MODULE_ELOQKV
        metrics::CommonLabels redis_labels{};
        redis_labels["node_ip"] = network_config_.local_ip;
        redis_labels["node_port"] =
            std::to_string(network_config_.local_port);
        redis_labels["node_id"] =
            std::to_string(network_config_.node_id);
        metrics::register_redis_metrics(metrics_registry_.get(),
                                        redis_labels,
                                        core_config_.core_num);
        metrics::redis_meter->Collect(metrics::NAME_MAX_CONNECTION,
                                      core_config_.maxclients);
#endif

        tx_service_common_labels_["node_ip"] = network_config_.local_ip;
        tx_service_common_labels_["node_port"] =
            std::to_string(network_config_.local_port);
        tx_service_common_labels_["node_id"] =
            std::to_string(network_config_.node_id);
    }

    return true;
}

bool DataSubstrate::RegisterKvStoreMetrics()
{
    if (!metrics::enable_metrics || metrics_registry_ == nullptr)
    {
        return true;  // Metrics not active or registry unavailable
    }

    if (core_config_.enable_data_store && store_hd_ != nullptr)
    {
        metrics::CommonLabels kv_common_labels{};
        kv_common_labels["node_ip"] = network_config_.local_ip;
        kv_common_labels["node_port"] =
            std::to_string(network_config_.local_port);
        store_hd_->RegisterKvMetrics(metrics_registry_.get(),
                                     kv_common_labels);
    }

    return true;
}

#include <ankerl/unordered_dense.h>
#include <fuzz/provider.h>
#include <fuzz/run.h>
#include <app/doctest.h>
#include <unordered_map>

namespace {
template <typename Container>
void test_string_operations(fuzz::provider p) {
    auto dense_map = Container();
    auto std_map = std::unordered_map<std::string, std::string>();

    while (p.has_remaining_bytes()) {
        auto key1 = p.string(32);
        REQUIRE(dense_map.try_emplace(key1, "hello!").second == std_map.try_emplace(key1, "hello!").second);

        auto key2 = p.string(32);
        auto it_dense = dense_map.find(key2);
        auto it_std = std_map.find(key2);
        REQUIRE((it_dense == dense_map.end()) == (it_std == std_map.end()));

        if (it_dense != dense_map.end()) {
            dense_map.erase(it_dense);
            std_map.erase(it_std);
        }

        REQUIRE(dense_map.size() == std_map.size());

        auto key3 = p.string(32);
        REQUIRE(dense_map.try_emplace(key3, "huh").second == std_map.try_emplace(key3, "huh").second);

        auto key4 = p.string(32);
        REQUIRE(dense_map.erase(key4) == std_map.erase(key4));
    }

    REQUIRE(std::unordered_map(dense_map.begin(), dense_map.end()) == std_map);
}
} // namespace

TEST_CASE("fuzz_string" * doctest::test_suite("fuzz")) {
    fuzz::run([](fuzz::provider p) {
        test_string_operations<ankerl::unordered_dense::map<std::string, std::string>>(p.copy());
        test_string_operations<ankerl::unordered_dense::segmented_map<std::string, std::string>>(p.copy());
        test_string_operations<ankerl::unordered_dense::map<std::string,
                                                            std::string,
                                                            ankerl::unordered_dense::hash<std::string>,
                                                            std::equal_to<std::string>,
                                                            std::deque<std::pair<std::string, std::string>>>>(p.copy());
    });
}

#include "kbm_config_dialog.h"
#include "kbm_help_dialog.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include "common/config.h"
#include "common/path_util.h"
#include "game_info.h"
#include <QCheckBox>
#include <QCloseEvent>
