QString last_selected_game = "default";
bool helpWindowActive = false;
HelpDialog* helpWindowInstance;

EditorDialog::EditorDialog(QWidget* parent) : QDialog(parent) {
    setWindowTitle(tr("Modify Keyboard + Mouse and Controller input mappings"));
    resize(800, 500);

    // Create the editor widget
    textEditor = new QPlainTextEdit(this);
    editorFont.setPointSize(12); // Adjusted default text size
    textEditor->setFont(editorFont); // Apply font to the editor

    // Create the game selection combo box
    gameSelector = new QComboBox(this);
    gameSelector->addItem("default"); // Add default option

    // Load all installed games
    populateInstalledGames();

    QCheckBox* unifiedInputToggle = new QCheckBox(tr("Enable Unified Input Settings"), this);
    unifiedInputToggle->setChecked(Config::GetUseUnifiedInputConfig());

    // Connect checkbox signal
    connect(unifiedInputToggle, &QCheckBox::toggled, this, [](bool checked) {
        Config::SetUseUnifiedInputConfig(checked);
        Config::save(Common::FS::GetUserPath(Common::FS::PathType::UserDir) / "config.toml");
    });

    // Create Save, Cancel, Reset, and Help buttons
    QPushButton* confirmButton = new QPushButton("Confirm", this);
    QPushButton* discardButton = new QPushButton("Discard", this);
    QPushButton* resetButton = new QPushButton("Restore Defaults", this);
    QPushButton* infoButton = new QPushButton("Info", this);

    // Layout for the game selection and action buttons
    QHBoxLayout* headerLayout = new QHBoxLayout();
    headerLayout->addWidget(unifiedInputToggle);
    headerLayout->addWidget(gameSelector);
    headerLayout->addStretch();
    headerLayout->addWidget(confirmButton);
    headerLayout->addWidget(discardButton);
    headerLayout->addWidget(resetButton);
    headerLayout->addWidget(infoButton);

    // Main layout with editor and controls
    QVBoxLayout* mainLayout = new QVBoxLayout(this);
    mainLayout->addLayout(headerLayout);
    mainLayout->addWidget(textEditor);

    // Load the current config file content into the editor
    loadConfiguration(gameSelector->currentText());

    // Connect button and combo box signals
    connect(confirmButton, &QPushButton::clicked, this, &EditorDialog::onConfirmClicked);
    connect(discardButton, &QPushButton::clicked, this, &EditorDialog::onDiscardClicked);
    connect(infoButton, &QPushButton::clicked, this, &EditorDialog::onInfoClicked);
    connect(resetButton, &QPushButton::clicked, this, &EditorDialog::onRestoreDefaultsClicked);
    connect(gameSelector, &QComboBox::currentTextChanged, this,
            &EditorDialog::onGameSelectionChanged);
}

void EditorDialog::loadConfiguration(QString game) {
    const auto config_path = Config::GetFoolproofInputConfigFile(game.toStdString());
    QFile file(config_path);
    if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
        QTextStream in(&file);
        textEditor->setPlainText(in.readAll());
        savedConfig = textEditor->toPlainText();
        file.close();
    } else {
        QMessageBox::warning(this, tr("Error"), tr("Unable to open file for reading"));
    }
}

void EditorDialog::saveConfiguration(QString game) {
    const auto config_path = Config::GetFoolproofInputConfigFile(game.toStdString());
    QFile file(config_path);
    if (file.open(QIODevice::WriteOnly | QIODevice::Text)) {
        QTextStream out(&file);
        out << textEditor->toPlainText();
        file.close();
    } else {
        QMessageBox::warning(this, tr("Error"), tr("Unable to open file for writing"));
    }
}

// Override the close event to show the save confirmation dialog only if changes were made
void EditorDialog::closeEvent(QCloseEvent* event) {
    if (helpWindowActive) {
        helpWindowInstance->close();
        helpWindowActive = false;
    }

    if (hasUnsavedModifications()) {
        QMessageBox::StandardButton reply;
        reply = QMessageBox::question(this, tr("Save Modifications"), tr("Do you want to save your changes?"),
                                      QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel);
        if (reply == QMessageBox::Yes) {
            saveConfiguration(gameSelector->currentText());
            event->accept(); // Close the dialog
        } else if (reply == QMessageBox::No) {
            event->accept(); // Close the dialog without saving
        } else {
            event->ignore(); // Cancel the close event
        }
    } else {
        event->accept(); // No changes, close the dialog without prompting
    }
}

void EditorDialog::keyPressEvent(QKeyEvent* event) {
    if (event->key() == Qt::Key_Escape) {
        if (helpWindowActive) {
            helpWindowInstance->close();
            helpWindowActive = false;
        }
        close(); // Trigger the close action, same as pressing the close button
    } else {
        QDialog::keyPressEvent(event); // Call the base class implementation for other keys
    }
}

void EditorDialog::onConfirmClicked() {
    if (helpWindowActive) {
        helpWindowInstance->close();
        helpWindowActive = false;
    }
    saveConfiguration(gameSelector->currentText());
    reject(); // Close the dialog
}

void EditorDialog::onDiscardClicked() {
    if (helpWindowActive) {
        helpWindowInstance->close();
        helpWindowActive = false;
    }
    reject(); // Close the dialog
}

void EditorDialog::onInfoClicked() {
    if (!helpWindowActive) {
        helpWindowInstance = new HelpDialog(&helpWindowActive, this);
        helpWindowInstance->setWindowTitle(tr("User Guide"));
        helpWindowInstance->setAttribute(Qt::WA_DeleteOnClose); // Clean up on close

        // Get the position and size of the Config window
        QRect configGeometry = this->geometry();
        int infoX = configGeometry.x() + configGeometry.width() + 15; // 15 pixels offset
        int infoY = configGeometry.y();

        // Move the Info dialog to the right side of the Config window
        helpWindowInstance->move(infoX, infoY);
        helpWindowInstance->show();
        helpWindowActive = true;
    } else {
        helpWindowInstance->close();
        helpWindowActive = false;
    }
}

void EditorDialog::onRestoreDefaultsClicked() {
    bool isDefaultSelection = gameSelector->currentText() == "default";
    QString prompt =
        isDefaultSelection
            ? tr("Would you like to restore your default configuration to factory settings?")
            : tr("Would you like to restore this configuration to your custom default?");

    QMessageBox::StandardButton reply = QMessageBox::question(this, tr("Reset Configuration"), prompt,
                                                              QMessageBox::Yes | QMessageBox::No);
    if (reply == QMessageBox::Yes) {
        if (isDefaultSelection) {
            const auto default_file = Config::GetFoolproofInputConfigFile("default");
            std::filesystem::remove(default_file);
        }

        const auto config_file = Config::GetFoolproofInputConfigFile("default");
        QFile file(config_file);
        if (file.open(QIODevice::ReadOnly | QIODevice::Text)) {
            QTextStream in(&file);
            textEditor->setPlainText(in.readAll());
            file.close();
        } else {
            QMessageBox::warning(this, tr("Error"), tr("Failed to read default configuration file"));
        }
    }
}

bool EditorDialog::hasUnsavedModifications() {
    // Compare the current content with the original content to check if there are unsaved changes
    return textEditor->toPlainText() != savedConfig;
}

void EditorDialog::populateInstalledGames() {
    last_selected_game = "default";
    QStringList filePaths;

    for (const auto& installLoc : Config::getGameInstallDirs()) {
        QString installDir;
        Common::FS::PathToQString(installDir, installLoc);
        QDir parentFolder(installDir);
        QFileInfoList fileList = parentFolder.entryInfoList(QDir::Dirs | QDir::NoDotAndDotDot);

        for (const auto& fileInfo : fileList) {
            if (fileInfo.isDir() && (!fileInfo.filePath().endsWith("-UPDATE") ||
                                     !fileInfo.filePath().endsWith("-patch"))) {
                gameSelector->addItem(fileInfo.fileName()); // Add game name to combo box
            }
        }
    }
}

void EditorDialog::onGameSelectionChanged(const QString& game) {
    saveConfiguration(last_selected_game);
    loadConfiguration(gameSelector->currentText()); // Reload file based on the selected game
    last_selected_game = gameSelector->currentText();
}

#include "Stochastic.hpp"
namespace MayaFlux::Kinesis::Stochastic {
Stochastic::Stochastic(Algorithm algo)
    : m_generator(std::random_device {}())
    , m_method(algo)
    , m_xorshift_state(std::random_device {}() | (static_cast<uint64_t>(std::random_device {}()) << 32))
{
    if (m_xorshift_state == 0)
        m_xorshift_state = 0xDEADBEEFCAFEBABE;
}
void Stochastic::seed(uint64_t seed_val)
{
    m_generator.seed(static_cast<std::mt19937::result_type>(seed_val));
    m_xorshift_state = seed_val;
    if (m_xorshift_state == 0)
        m_xorshift_state = 0xDEADBEEFCAFEBABE;
    reset_internal();
}
void Stochastic::set_algorithm(Algorithm algo)
{
    if (m_method != algo) {
        m_method = algo;
        reset_internal();
        m_distribution_dirty = true;
    }
}
void Stochastic::configure(const std::string& param, std::any value)
{
    m_parameters[param] = std::move(value);
    m_distribution_dirty = true;
}
std::optional<std::any> Stochastic::get_config(const std::string& param) const
{
    auto it = m_parameters.find(param);
    if (it != m_parameters.end()) {
        return it->second;
    }
    return std::nullopt;
}
double Stochastic::operator()(double lower, double upper)
{
    validate_bounds(lower, upper);
    switch (m_method) {
    case Algorithm::UNIFORM:
    case Algorithm::NORMAL:
    case Algorithm::EXPONENTIAL:
    case Algorithm::POISSON:
        return generate_memoryless(lower, upper);
    case Algorithm::PERLIN:
        return generate_perlin_impl(m_internal.phase, 0.0, 0.0);
    case Algorithm::GENDY:
        return generate_gendy_impl(lower, upper);
    case Algorithm::BROWNIAN:
        return generate_brownian_impl(lower, upper);
    case Algorithm::PINK:
    case Algorithm::BLUE:
        return generate_colored_noise_impl(lower, upper);
    default:
        return generate_memoryless(lower, upper);
    }
}
double Stochastic::at(double x, double y, double z)
{
    if (m_method != Algorithm::PERLIN) {
        throw std::runtime_error("Multi-dimensional access only supported for PERLIN algorithm");
    }
    return generate_perlin_impl(x, y, z);
}
std::vector<double> Stochastic::batch(double lower, double upper, size_t num_samples)
{
    validate_bounds(lower, upper);
    std::vector<double> output;
    output.reserve(num_samples);
    for (size_t idx = 0; idx < num_samples; ++idx) {
        output.push_back((*this)(lower, upper));
    }
    return output;
}
void Stochastic::reset_internal()
{
    m_internal.reset();
}
double Stochastic::generate_memoryless(double lower, double upper)
{
    if (lower != m_cached_lower || upper != m_cached_upper) {
        m_cached_lower = lower;
        m_cached_upper = upper;
        m_distribution_dirty = true;
    }
    double raw_sample = 0.0;
    switch (m_method) {
    [[likely]] case Algorithm::UNIFORM:
        return lower + fast_uniform() * (upper - lower);
    case Algorithm::NORMAL: {
        rebuild_distributions_if_needed(lower, upper);
        raw_sample = m_normal_dist(m_generator);
        return std::clamp(raw_sample, lower, upper);
    }
    case Algorithm::EXPONENTIAL: {
        rebuild_distributions_if_needed(lower, upper);
        raw_sample = m_exponential_dist(m_generator);
        raw_sample /= upper;
        return lower + raw_sample * (upper - lower);
    }
    case Algorithm::POISSON: {
        std::poisson_distribution<int> dist(static_cast<int>(upper - lower));
        return static_cast<double>(dist(m_generator));
    }
    default:
        return lower + fast_uniform() * (upper - lower);
    }
}
double Stochastic::generate_stateful(double lower, double upper)
{
    m_internal.step_count++;
    return m_internal.current_value;
}
double Stochastic::generate_perlin_impl(double x, double y, double z)
{
    return 0.0;
}
double Stochastic::generate_gendy_impl(double lower, double upper)
{
    return lower + fast_uniform() * (upper - lower);
}
double Stochastic::generate_brownian_impl(double lower, double upper)
{
    double step_size = 0.01;
    if (auto cfg = get_config("step_size"); cfg.has_value()) {
        step_size = std::any_cast<double>(*cfg);
    }
    double increment = (fast_uniform() - 0.5) * 2.0 * step_size;
    m_internal.current_value += increment;
    m_internal.current_value = std::clamp(m_internal.current_value, lower, upper);
    m_internal.step_count++;
    return m_internal.current_value;
}
double Stochastic::generate_colored_noise_impl(double lower, double upper)
{
    return lower + fast_uniform() * (upper - lower);
}
void Stochastic::validate_bounds(double lower, double upper) const
{
    if (lower > upper) {
        throw std::invalid_argument("Stochastic: lower must be <= upper");
    }
}
void Stochastic::rebuild_distributions_if_needed(double lower, double upper)
{
    if (!m_distribution_dirty)
        return;
    const double span = upper - lower;
    if (m_method == Algorithm::NORMAL) {
        double spread = 4.0;
        if (auto cfg = get_config("spread"); cfg.has_value()) {
            spread = std::any_cast<double>(*cfg);
        }
        m_normal_dist = std::normal_distribution<double>(0.0, span / spread);
    } else if (m_method == Algorithm::EXPONENTIAL) {
        m_exponential_dist = std::exponential_distribution<double>(1.0);
    }
    m_distribution_dirty = false;
}
}

#include "bishengir/Dialect/HIVM/Transforms/InjectSync/MoveSyncState.h"
#include "bishengir/Dialect/HIVM/Transforms/InjectSync/SyncCommon.h"
#include "llvm/ADT/STLExtras.h"
#define DEBUG_TYPE "hivm-inject-sync"
using namespace mlir;
using namespace mlir::hivm;

void MoveSyncState::OptimizeState() {
  EliminateRedundantBranchSync();
  RelocateLoopSync();
}

void MoveSyncState::EliminateRedundantBranchSync() {
  for (auto &item : syncIR) {
    if (auto *branchElem = dyn_cast<BranchInstanceElement>(item.get())) {
      if (branchElem->getBranchKind() == KindOfBranch::IF_BEGIN) {
        std::pair<unsigned, unsigned> range = {branchElem->beginId,
                                               branchElem->endId};
        for (unsigned idx = branchElem->beginId + 1;
             idx < branchElem->branchId; idx++) {
          PrepareBranchSyncRelocation(
              syncIR[idx].get(),
              {branchElem->beginId, branchElem->branchId}, range);
        }
        if (branchElem->endId == branchElem->branchId) {
          continue;
        }
        for (unsigned idx = branchElem->branchId + 1; idx < branchElem->endId;
             idx++) {
          PrepareBranchSyncRelocation(syncIR[idx].get(),
                                      {branchElem->branchId, branchElem->endId},
                                      range);
        }
      }
    }
  }
}

void MoveSyncState::PrepareBranchSyncRelocation(
    InstanceElement *elem, std::pair<unsigned int, unsigned int> innerRange,
    std::pair<unsigned int, unsigned int> outerRange) {
  checkCondition(
      innerRange.first < elem->GetIndex() && elem->GetIndex() < innerRange.second,
      "PrepareBranchSyncRelocation expects element to lie strictly inside inner bounds");
  SyncOps relocatedBefore;
  for (auto &op : elem->pipeBefore) {
    DecideWaitSyncRelocation(relocatedBefore, op, innerRange, outerRange);
  }
  SyncOps relocatedAfter;
  for (auto &op : llvm::reverse(elem->pipeAfter)) {
    DecideSetSyncRelocation(relocatedAfter, op, innerRange, outerRange);
  }
  elem->pipeAfter = relocatedAfter;
  elem->pipeBefore = relocatedBefore;
}

void MoveSyncState::DecideWaitSyncRelocation(
    SyncOps &relocatedBefore, SyncOperation *op,
    std::pair<unsigned int, unsigned int> innerRange,
    std::pair<unsigned int, unsigned int> outerRange) {
  if (op->GetType() != SyncOperation::TYPE::WAIT_EVENT &&
      op->GetType() != SyncOperation::TYPE::SYNC_BLOCK_WAIT) {
    relocatedBefore.push_back(op);
    return;
  }
  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(!syncPair.empty(), "expected non-empty sync pair");
  auto *setOp = syncPair[0].get();
  if ((setOp->GetSyncIRIndex() >= innerRange.second) ||
      (setOp->GetSyncIRIndex() <= innerRange.first)) {
    // Scenario:
    // setFlag
    // if():
    //    waitFlag
    //    compound
    // →
    // setFlag
    // waitFlag
    // if():
    //    compound
    checkSyncIRIndex(syncIR, outerRange.first);
    syncIR[outerRange.first]->pipeBefore.push_back(op);
    op->SetSyncIRIndex(outerRange.first);
  } else {
    relocatedBefore.push_back(op);
  }
}

void MoveSyncState::DecideSetSyncRelocation(
    SyncOps &relocatedAfter, SyncOperation *op,
    std::pair<unsigned int, unsigned int> innerRange,
    std::pair<unsigned int, unsigned int> outerRange) {
  if (op->GetType() != SyncOperation::TYPE::SET_EVENT &&
      op->GetType() != SyncOperation::TYPE::SYNC_BLOCK_SET) {
    relocatedAfter.push_back(op);
    return;
  }
  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(syncPair.size() > 1, "expected sync pair size > 1");
  auto *waitOp = syncPair[1].get();
  if ((waitOp->GetSyncIRIndex() >= innerRange.second) ||
      (waitOp->GetSyncIRIndex() <= innerRange.first)) {
    // Scenario:
    // if():
    //    compound
    //    setFlag
    // waitFlag
    // →
    // if():
    //    compound
    // setFlag
    // waitFlag
    checkSyncIRIndex(syncIR, outerRange.second);
    syncIR[outerRange.second]->pipeAfter.push_front(op);
    op->SetSyncIRIndex(outerRange.second);
  } else {
    relocatedAfter.push_back(op);
  }
}

void MoveSyncState::RelocateLoopSync() {
  for (auto &item : syncIR) {
    if (auto *loopElem = dyn_cast<LoopInstanceElement>(item.get())) {
      if (loopElem->getLoopKind() == KindOfLoop::LOOP_END) {
        if (loopElem->ignore_block_sync_move_out) {
          continue;
        }
        for (unsigned idx = loopElem->beginId + 1; idx < loopElem->endId; idx++)
          RelocateSync(syncIR[idx].get(),
                       {loopElem->beginId, loopElem->endId});
      }
    }
  }
}

void MoveSyncState::RelocateSync(InstanceElement *elem,
                                 std::pair<unsigned int, unsigned int> range) {
  checkCondition(range.first < elem->GetIndex() && elem->GetIndex() < range.second,
                 "RelocateSync expects element to be strictly within range");
  SyncOps newBefore;
  for (auto &op : elem->pipeBefore) {
    EvaluateWaitSyncRelocation(newBefore, op, range);
  }
  SyncOps newAfter;
  for (auto &op : llvm::reverse(elem->pipeAfter)) {
    EvaluateSetSyncRelocation(newAfter, op, range);
  }
  elem->pipeAfter = newAfter;
  elem->pipeBefore = newBefore;
}

void MoveSyncState::EvaluateWaitSyncRelocation(
    SyncOps &newBefore, SyncOperation *op,
    std::pair<unsigned int, unsigned int> range) {
  if (op->GetType() != SyncOperation::TYPE::WAIT_EVENT &&
      op->GetType() != SyncOperation::TYPE::SYNC_BLOCK_WAIT) {
    newBefore.push_back(op);
    return;
  }
  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(!syncPair.empty(), "expected non-empty sync pair");
  auto *setOp = syncPair[0].get();
  if ((setOp->GetSyncIRIndex() > range.second) ||
      (setOp->GetSyncIRIndex() < range.first)) {
    // Scenario:
    // setFlag
    // for():
    //    waitFlag
    //    compound
    // →
    // setFlag
    // waitFlag
    // for():
    //    compound
    checkSyncIRIndex(syncIR, range.first);
    syncIR[range.first]->pipeBefore.push_back(op);
    op->SetSyncIRIndex(range.first);
    return;
  }
  newBefore.push_back(op);
}

void MoveSyncState::EvaluateSetSyncRelocation(
    SyncOps &newAfter, SyncOperation *op,
    const std::pair<unsigned int, unsigned int> range) {
  if (op->GetType() != SyncOperation::TYPE::SET_EVENT &&
      op->GetType() != SyncOperation::TYPE::SYNC_BLOCK_SET) {
    newAfter.push_back(op);
    return;
  }
  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(syncPair.size() > 1, "expected sync pair size > 1");
  auto *waitOp = syncPair[1].get();
  if ((waitOp->GetSyncIRIndex() > range.second) ||
      (waitOp->GetSyncIRIndex() < range.first)) {
    // Scenario:
    // for():
    //    compound
    //    setFlag
    // waitFlag
    // →
    // for():
    //    compound
    // setFlag
    // waitFlag
    checkSyncIRIndex(syncIR, range.second);
    syncIR[range.second]->pipeAfter.push_front(op);
    op->SetSyncIRIndex(range.second);
    return;
  }
  newAfter.push_back(op);
}

#include <sycl/sycl.hpp>
#include "../utils.h"
#include "../dispatch_utils.h"

namespace vllm {
namespace GroupedTopKImpl {

enum class ScoringMode {
  NONE = 0,
  SOFTMAX_MODE = 1,
  SIGMOID_MODE = 2,
};

template <typename T, int MAX_GROUPS>
struct Fused_Grouped_Topk {
  static constexpr int warp_size = 32;
  static constexpr int max_warp_capacity = 1024;
  static constexpr int per_thread_alloc = MAX_GROUPS;
  static constexpr float NEG_INF_VAL = -INFINITY;

  Fused_Grouped_Topk(
      float* out_weights,
      int* out_indices,
      const T* input_logits,
      const T* expert_bias,
      const double scale_factor,
      const ScoringMode mode,
      const bool do_normalize,
      const int batch_size,
      const int total_experts,
      const int k_select,
      const int num_groups,
      const int group_select)
      : output_weights(out_weights),
        output_ids(out_indices),
        logits(input_logits),
        bias_ptr(expert_bias),
        scaling(scale_factor),
        scoring(mode),
        normalize(do_normalize),
        batch(batch_size),
        experts(total_experts),
        k(k_select),
        groups(num_groups),
        group_k(group_select) {}

  static inline sycl::nd_range<3>
  compute_launch_config(const int tokens, const int experts_count) {
    int items_per_workitem = (experts_count + warp_size - 1) / warp_size;
    int local_dim = (experts_count + items_per_workitem - 1) / items_per_workitem;
    local_dim = local_dim < warp_size ? warp_size : local_dim;
    local_dim = local_dim < max_warp_capacity ? local_dim : max_warp_capacity;
    int warps_per_group = (local_dim + warp_size - 1) / warp_size;
    local_dim = warps_per_group * warp_size;
    int global_dim =
        (tokens + warps_per_group - 1) / warps_per_group;
    sycl::range<3> local(1, 1, local_dim);
    sycl::range<3> global(1, 1, global_dim);
    return sycl::nd_range<3>(global * local, local);
  }

  static inline float sigmoid_func(float x) {
    return 1.0f / (1.0f + sycl::native::exp(-x));
  }

  [[sycl::reqd_sub_group_size(warp_size)]] void
  operator()(sycl::nd_item<3> item) const {
    int group_id = item.get_group_linear_id();
    int local_range = item.get_local_range(2);
    int warps_per_group = local_range / warp_size;
    int items_per_workitem = (experts + warp_size - 1) / warp_size;
    int experts_per_group = experts / groups;
    sycl::sub_group sg = item.get_sub_group();
    int sg_id = sg.get_group_id();
    int sg_lane_id = sg.get_local_id();
    int thread_id = group_id * warps_per_group + sg_id;

    if (thread_id >= batch) {
      return;
    }

    T local_values[per_thread_alloc];
    int local_positions[per_thread_alloc];
    T local_biases[per_thread_alloc];

    int start_idx = sg_lane_id * items_per_workitem;
    int count = items_per_workitem;
    if (start_idx + count >= experts) {
      count = experts - start_idx;
      if (count < 0) count = 0;
    }

    for (int i = 0; i < items_per_workitem; ++i) {
      local_values[i] = NEG_INF_VAL;
      local_positions[i] = -1;
      local_biases[i] = 0.0f;
    }

    for (int i = 0; i < count; ++i) {
      local_values[i] = logits[thread_id * experts + start_idx + i];
    }

    T processed_vals[per_thread_alloc];
    for (int i = 0; i < count; ++i) {
      processed_vals[i] = local_values[i];
      local_positions[i] = start_idx + i;
    }

    if (scoring == ScoringMode::SOFTMAX_MODE) {
      float max_val = NEG_INF_VAL;
      for (int i = 0; i < count; ++i) {
        float val = local_values[i];
        max_val = (max_val > val) ? max_val : val;
      }
      for (int offset = warp_size / 2; offset > 0; offset /= 2) {
        float peer_val = sycl::permute_group_by_xor(sg, max_val, offset);
        max_val = (max_val > peer_val) ? max_val : peer_val;
      }

      float exp_sum = 0.0f;
      for (int i = 0; i < count; ++i) {
        float val = processed_vals[i];
        exp_sum += sycl::native::exp(val - max_val);
      }
      for (int offset = warp_size / 2; offset > 0; offset /= 2) {
        float peer_sum = sycl::permute_group_by_xor(sg, exp_sum, offset);
        exp_sum += peer_sum;
      }

      for (int i = 0; i < count; ++i) {
        float val = processed_vals[i];
        processed_vals[i] = sycl::native::exp(val - max_val) / exp_sum;
      }
    } else if (scoring == ScoringMode::SIGMOID_MODE) {
      for (int i = 0; i < count; ++i) {
        float val = local_values[i];
        local_values[i] = sigmoid_func(val);
      }
      for (int i = 0; i < count; ++i) {
        processed_vals[i] = local_values[i];
      }
    }

    bool has_bias = bias_ptr != nullptr;
    if (has_bias) {
      for (int i = 0; i < count; ++i) {
        local_biases[i] = bias_ptr[start_idx + i];
      }
    }

    // Compute group scores
    float group_scores[per_thread_alloc * 2];
    for (int i = 0; i < groups * 2; ++i) {
      group_scores[i] = NEG_INF_VAL;
    }

    for (int i = 0; i < count; ++i) {
      float b = local_biases[i];
      float score = processed_vals[i] + b;
      int group_idx = (items_per_workitem * sg_lane_id + i) / experts_per_group;
      float current_max = group_scores[group_idx];
      float second_max = group_scores[groups + group_idx];

      if (score > current_max) {
        second_max = current_max;
        current_max = score;
      } else if (score > second_max) {
        second_max = score;
      }

      group_scores[group_idx] = current_max;
      group_scores[groups + group_idx] = second_max;
    }

    for (int g = 0; g < groups; ++g) {
      float top_score = group_scores[g];
      float second_score = group_scores[groups + g];
      float best = sycl::reduce_over_group(
          sg, sycl::max(top_score, second_score), sycl::maximum<>());
      float candidate_second =
          (top_score < best && top_score > -INFINITY) ? top_score : -INFINITY;
      candidate_second =
          (second_score < best && second_score > candidate_second)
              ? second_score
              : candidate_second;
      float final_second = sycl::reduce_over_group(sg, candidate_second, sycl::maximum<>());
      group_scores[g] = best + (has_bias ? final_second : 0.0f);
    }

    // Select top-k groups
    int selected_groups[per_thread_alloc];
    for (int k = 0; k < group_k; ++k) {
      float best_score = group_scores[0];
      int best_idx = 0;
      for (int g = 1; g < groups; ++g) {
        float score = group_scores[g];
        if (score > best_score) {
          best_score = score;
          best_idx = g;
        }
      }
      group_scores[best_idx] = NEG_INF_VAL;
      selected_groups[k] = best_idx;
    }

    // Mask non-selected groups
    for (int i = 0; i < items_per_workitem; ++i) {
      bool keep = false;
      for (int k = 0; k < group_k; ++k) {
        if ((local_positions[i] / experts_per_group) == selected_groups[k]) {
          keep = true;
          break;
        }
      }
      if (!keep) {
        processed_vals[i] = NEG_INF_VAL;
      }
    }

    // Final top-k selection
    T final_weights[per_thread_alloc];
    int final_indices[per_thread_alloc];
    for (int k = 0; k < k; ++k) {
      float best_val = NEG_INF_VAL;
      int best_pos = -1;
      int remove_idx = -1;

      for (int i = 0; i < items_per_workitem; ++i) {
        float val = processed_vals[i];
        float bias = local_biases[i];
        float combined = val + bias;
        int pos = local_positions[i];

        for (int offset = warp_size / 2; offset > 0; offset /= 2) {
          float peer_val = sycl::permute_group_by_xor(sg, combined, offset);
          int peer_pos = sycl::permute_group_by_xor(sg, pos, offset);
          if (peer_val > combined ||
              (peer_val == combined && peer_pos < pos)) {
            combined = peer_val;
            pos = peer_pos;
          }
        }

        if (combined > best_val || (combined == best_val && pos < best_pos)) {
          best_val = combined;
          best_pos = pos;
          if (best_pos == local_positions[i]) {
            remove_idx = i;
          } else {
            remove_idx = -1;
          }
        }
      }

      int slot = best_pos / items_per_workitem;
      int elem = best_pos % items_per_workitem;
      best_val = processed_vals[elem];
      best_val = sycl::group_broadcast(sg, best_val, slot);

      if (remove_idx != -1) {
        processed_vals[remove_idx] = NEG_INF_VAL;
        local_positions[remove_idx] = -1;
        remove_idx = -1;
      }

      final_weights[k] = best_val;
      final_indices[k] = (best_pos < 0 || best_pos >= experts) ? k : best_pos;
    }

    if (normalize) {
      float sum = 0.0f;
      for (int i = 0; i < k; ++i) {
        sum += final_weights[i];
      }
      if (sum > 0.0f) {
        for (int i = 0; i < k; ++i) {
          final_weights[i] /= sum;
        }
      }
    }

    if (sg_lane_id == 0) {
      int base = thread_id * k;
      for (int i = 0; i < k; ++i) {
        output_weights[base + i] = final_weights[i] * scaling;
        int idx = final_indices[i];
        if (idx < 0 || idx >= experts) {
          output_ids[base + i] = 0;
        } else {
          output_ids[base + i] = idx;
        }
      }
    }
  }

  float* output_weights;
  int* output_ids;
  const T* logits;
  const T* bias_ptr;
  const double scaling;
  const ScoringMode scoring;
  const bool normalize;
  const int batch;
  const int experts;
  const int k;
  const int groups;
  const int group_k;
};

template <typename T, int MAX_GROUPS>
void launch_fused_grouped_topk(
    sycl::queue& queue,
    float* out_weights,
    int* out_indices,
    const T* input_logits,
    const T* expert_bias,
    const double scale_factor,
    const ScoringMode mode,
    const bool do_normalize,
    const int batch_size,
    const int total_experts,
    const int k_select,
    const int num_groups,
    const int group_select) {
  using Kernel = Fused_Grouped_Topk<T, MAX_GROUPS>;
  auto range = Kernel::compute_launch_config(batch_size, total_experts);
  queue.submit([&](sycl::handler& cgh) {
    Kernel task(
        out_weights,
        out_indices,
        input_logits,
        expert_bias,
        scale_factor,
        mode,
        do_normalize,
        batch_size,
        total_experts,
        k_select,
        num_groups,
        group_select);
    cgh.parallel_for(range, task);
  });
}

template <typename T>
void fused_grouped_topk(
    float* out_weights,
    int* out_indices,
    const T* input_logits,
    const T* expert_bias,
    const double scale_factor,
    const ScoringMode mode,
    const bool do_normalize,
    const int batch_size,
    const int total_experts,
    const int k_select,
    const int num_groups,
    const int group_select) {
  auto& queue = vllm::xpu::vllmGetQueue();
  TORCH_CHECK(
      group_select <= num_groups,
      "group_select must be less than or equal to num_groups");
  TORCH_CHECK(
      total_experts % num_groups == 0,
      "The number of experts (",
      total_experts,
      ") must be divisible by num_groups (",
      num_groups,
      ").");

  int padded_groups = ((num_groups + 7) / 8) * 8;

#define CASE_GROUP(G)                \
  case G:                            \
    launch_fused_grouped_topk<T, G>( \
        queue,                       \
        out_weights,                 \
        out_indices,                 \
        input_logits,                \
        expert_bias,                 \
        scale_factor,                \
        mode,                        \
        do_normalize,                \
        batch_size,                  \
        total_experts,               \
        k_select,                    \
        num_groups,                  \
        group_select);               \
    break;

  switch (padded_groups) {
    CASE_GROUP(8)
    CASE_GROUP(16)
    default:
      TORCH_CHECK(
          false, "error: unsupported num_groups=%d,\n", num_groups);
  }
#undef CASE_GROUP
}

};  // namespace GroupedTopKImpl
}  // namespace vllm

std::tuple<torch::Tensor, torch::Tensor> fused_grouped_topk(
    const torch::Tensor& hidden_states,
    const torch::Tensor& gating_output,
    const int64_t n_topk,
    const bool renormalize,
    const int64_t n_expert_group,
    const int64_t n_topk_group,
    const c10::string_view scoring_func,
    const double routed_scaling_factor,
    const c10::optional<torch::Tensor>& bias) {
  auto shape = gating_output.sizes().vec();
  TORCH_CHECK(
      hidden_states.sizes()[0] == gating_output.sizes()[0],
      "Number of tokens mismatch")
  TORCH_CHECK(
      shape.size() == 2,
      "gating_output must be 2D tensor, but got ",
      shape.size(),
      "D");
  if (bias.has_value()) {
    auto bias_shape = bias->sizes().vec();
    TORCH_CHECK(
        bias_shape[0] == shape[1],
        "gating_output and bias must have same innermost dimension, but got ",
        shape,
        " and ",
        bias_shape);
  }

  int n_tokens = shape[0];
  int n_experts = shape[1];

  vllm::GroupedTopKImpl::ScoringMode scoring_mode;
  if (scoring_func == "sigmoid") {
    scoring_mode = vllm::GroupedTopKImpl::ScoringMode::SIGMOID_MODE;
  } else if (scoring_func == "softmax") {
    scoring_mode = vllm::GroupedTopKImpl::ScoringMode::SOFTMAX_MODE;
  } else {
    scoring_mode = vllm::GroupedTopKImpl::ScoringMode::NONE;
  }

  auto topk_weights =
      torch::empty({n_tokens, n_topk}, at::dtype(at::kFloat).device(at::kXPU));
  auto topk_indices =
      torch::empty({n_tokens, n_topk}, at::dtype(at::kInt).device(at::kXPU));

  if (gating_output.scalar_type() == at::kBFloat16) {
    using scalar_t = sycl::ext::oneapi::bfloat16;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr())
                         : nullptr,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  } else if (gating_output.scalar_type() == at::kHalf) {
    using scalar_t = sycl::half;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr())
                         : nullptr,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  } else {
    using scalar_t = float;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr())
                         : nullptr,
        routed_scaling_factor,
        scoring_mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  }

  return std::make_tuple(topk_weights, topk_indices);
}

