    void DrawNeoSequencerHeaderBackground(const ImVec4 &fillColor, const ImVec2 &origin, const ImVec2 &extent,
                                          ImDrawList *renderer, float cornerRounding) {
        if(!renderer) renderer = ImGui::GetWindowDrawList();
        const ImRect headerRegion = {origin, origin + extent};
        renderer->AddRectFilled(headerRegion.Min, headerRegion.Max, ColorConvertFloat4ToU32(fillColor), cornerRounding);
    }

    void
    DrawNeoSequencerHeaderOverlay(float zoomFactor, float labelWidth,unsigned firstKey, unsigned lastKey, unsigned frameOffset, const ImVec2 &origin, const ImVec2 &dimensions,
                                    ImDrawList *renderer, bool showTickMarks,
                                    bool showNumbers, float maxSpacingBetweenTicks) {
        if(!renderer) renderer = ImGui::GetWindowDrawList();
        const auto & style = GetStyle();
        const ImRect headerArea = {origin + ImVec2{style.FramePadding.x + labelWidth,style.FramePadding.y}, origin + dimensions };
        const unsigned visibleEnd = lastKey + frameOffset;
        const unsigned visibleStart = firstKey + frameOffset;
        if(showTickMarks) {
            const auto totalTicks = (int)((float)((visibleEnd + 1) - visibleStart) / zoomFactor);
            int stepCounter = 0;
            unsigned majorInterval = static_cast<unsigned>(pow(10.0f, stepCounter++));
            unsigned minorInterval = static_cast<unsigned>(pow(10.0f, stepCounter));
            float widthPerKey = CalculateWidthPerKey(dimensions.x, labelWidth, lastKey, firstKey, zoomFactor);
            if(widthPerKey <= 0.0f) return;
            while (widthPerKey < maxSpacingBetweenTicks)
            {
                majorInterval = static_cast<unsigned>(pow(10.0f, stepCounter++));
                minorInterval = static_cast<unsigned>(pow(10.0f, stepCounter));
                widthPerKey *= static_cast<float>(majorInterval);
            }
            if(majorInterval == 0 || minorInterval == 0) {
                majorInterval = 1;
                minorInterval = 10;
            }
            for(int idx = 0; idx < totalTicks; idx++) {
                const auto isMajor = ((visibleStart + idx) % majorInterval == 0);
                const auto isMinor = ((visibleStart + idx) % minorInterval == 0);
                if(!isMajor && !isMinor) continue;
                const auto tickHeight = isMinor ? headerArea.GetSize().y : headerArea.GetSize().y / 2.0f;
                const ImVec2 startP = {headerArea.Min.x + static_cast<float>(idx) * (widthPerKey / static_cast<float>(majorInterval)), headerArea.Max.y};
                const ImVec2 endP = {headerArea.Min.x + static_cast<float>(idx) * (widthPerKey / static_cast<float>(majorInterval)), headerArea.Max.y - tickHeight};
                renderer->AddLine(startP, endP, IM_COL32_WHITE, 1.0f);
                if(showNumbers && isMinor) {
                    char buffer[16];
                    const auto written = snprintf(buffer, sizeof(buffer), "%u", visibleStart + idx);
                    if(written > 0) {
                        renderer->AddText(NULL, 0, {startP.x + 2.0f, headerArea.Min.y }, IM_COL32_WHITE,buffer);
                    }
                }
            }
        }
    }

    void DrawNeoTimelineEntry(const char * name,const ImVec2 & pos,const ImVec2 & dims, const ImVec4& textColor,bool isContainer, bool expanded, ImDrawList *renderer)
    {
        const auto& imStyle = GetStyle();
        if(!renderer) renderer = ImGui::GetWindowDrawList();
        auto currentPos = pos;
        if(isContainer) {
            DrawArrow(renderer,currentPos,IM_COL32_WHITE,expanded ? ImGuiDir_Down : ImGuiDir_Right);
            currentPos.x += dims.y + imStyle.ItemSpacing.x;
        }
        renderer->AddText(currentPos,ColorConvertFloat4ToU32(textColor),name, FindRenderedTextEnd(name));
    }

    void DrawNeoTimelineBorder(const ImVec4 &borderColor, const ImVec2 &pos, const ImVec2 &dims, ImDrawList *renderer,
                                  float rounding, float thickness)
    {
        if(!renderer) renderer = ImGui::GetWindowDrawList();
