    void DrawNeoTrackHighlight(bool isActive,const ImVec2 & pos, const ImVec2& dims, const ImVec4& selectionColor, ImDrawList *renderer) {
        if(!renderer) renderer = ImGui::GetWindowDrawList();
        if(isActive) {
            const ImRect rect = {pos, pos + dims};
            renderer->AddRectFilled(rect.Min, rect.Max, ColorConvertFloat4ToU32(selectionColor));
        }
    }

    float CalculateWidthPerKey(float availableWidth, float labelWidth, unsigned lastKey, unsigned firstKey, float zoom) {
        const auto& imStyle = GetStyle();
        const auto usableWidth = availableWidth - labelWidth - imStyle.FramePadding.x;
        auto keyCount = (lastKey + 1) - firstKey;
        return ((usableWidth / static_cast<float>(keyCount)) * zoom);
    }

    struct FloatPair {
        ImVec2 first;
        ImVec2 second;
    };

    static FloatPair GetCurrentFrameIndicator(const ImRect & selectionBox, float trackHeight) {
        const auto midPoint = ImVec2{selectionBox.Min.x, selectionBox.Max.y} + ImVec2{selectionBox.GetSize().x / 2.0f, 0};
        return FloatPair{ midPoint, midPoint + ImVec2{0, trackHeight} };
    }

    void DrawNeoSequencerPlayhead(const ImVec4 &lineColor, const ImVec4 &pointerColor, const ImRect &selectionBox,
                                               float trackHeight, float strokeWidth, ImDrawList *renderer) {
        if(!renderer) renderer = ImGui::GetWindowDrawList();
        const auto pair = GetCurrentFrameIndicator(selectionBox, trackHeight);
        renderer->AddLine(pair.first, pair.second, ColorConvertFloat4ToU32(lineColor), strokeWidth);
        renderer->PopClipRect();
        { //Custom top pointer shape
            const auto size = selectionBox.GetSize();
            ImVec2 points[5];
            points[0] = selectionBox.Min;
            points[1] = selectionBox.Min + ImVec2{size.x, 0};
            points[2] = selectionBox.Min + ImVec2{size.x, size.y * 0.85f};
            points[3] = selectionBox.Min + ImVec2{size.x / 2, size.y};
            points[4] = selectionBox.Min + ImVec2{0, size.y * 0.85f};
            renderer->AddConvexPolyFilled(points, sizeof(points) / sizeof(*points), ColorConvertFloat4ToU32(pointerColor));
        }
    }
}

