static PlanetCondition convert_planet_dict_to_condition(py::dict input_planet) {
    PlanetCondition result_condition = PlanetCondition();
    result_condition.satisfy_num = input_planet["satisfy_num"].cast<uint8_t>();
    result_condition.dsp_level = input_planet["dsp_level"].cast<uint8_t>();
    result_condition.type = input_planet["type"].cast<uint8_t>();
    result_condition.liquid = input_planet["liquid"].cast<uint8_t>();
    result_condition.singularity = input_planet["singularity"].cast<uint8_t>();
    result_condition.need_veins = input_planet["need_veins"].cast<uint16_t>();
    result_condition.veins_group = input_planet["veins_group"].cast<vector<int>>();
    result_condition.veins_point = input_planet["veins_point"].cast<vector<int>>();

    auto satellite_conditions = input_planet["moons"].cast<py::list>();
    for (auto satellite_condition : satellite_conditions) {
        result_condition.moons.push_back(
            convert_planet_dict_to_condition(satellite_condition.cast<py::dict>())
        );
    }
    return result_condition;
}

static StarCondition convert_star_dict_to_condition(py::dict input_star) {
    StarCondition result_condition = StarCondition();
    result_condition.satisfy_num = input_star["satisfy_num"].cast<uint8_t>();
    result_condition.type = input_star["type"].cast<uint8_t>();
    result_condition.distance = input_star["distance"].cast<float>();
    result_condition.dyson_lumino = input_star["dyson_lumino"].cast<float>();
    result_condition.need_veins = input_star["need_veins"].cast<uint16_t>();
    result_condition.veins_group = input_star["veins_group"].cast<vector<int>>();
    result_condition.veins_point = input_star["veins_point"].cast<vector<int>>();

    auto planet_conditions = input_star["planets"].cast<py::list>();
    for (auto planet_condition : planet_conditions) {
        result_condition.planets.push_back(
            convert_planet_dict_to_condition(planet_condition.cast<py::dict>())
        );
    }
    return result_condition;
}

GalaxyCondition convert_galaxy_dict_to_condition(py::dict input_galaxy) {
    GalaxyCondition result_condition = GalaxyCondition();
    result_condition.need_veins = input_galaxy["need_veins"].cast<uint16_t>();
    result_condition.veins_group = input_galaxy["veins_group"].cast<vector<int>>();
    result_condition.veins_point = input_galaxy["veins_point"].cast<vector<int>>();

    auto star_conditions = input_galaxy["stars"].cast<py::list>();
    for (auto star_condition : star_conditions) {
        result_condition.stars.push_back(
            convert_star_dict_to_condition(star_condition.cast<py::dict>())
        );
    }

    auto planet_conditions = input_galaxy["planets"].cast<py::list>();
    for (auto planet_condition : planet_conditions) {
        result_condition.planets.push_back(
            convert_planet_dict_to_condition(planet_condition.cast<py::dict>())
        );
    }
    return result_condition;
}

#include "include/xml_buffer.hpp"
#include "duckdb/common/exception.hpp"
#include "duckdb/common/helper.hpp"

XMLBuffer::XMLBuffer(std::string filepath, std::string base_uri, duckdb::FileSystem *filesystem, const bool strict_mode,
                     const bool expand_ns, const ITriplesBuffer::FileType type)
    : ITriplesBuffer(filepath, base_uri, strict_mode, expand_ns),
      _parser([this](const RdfStatement &s) { this->handleStatement(s); },
              [this](const std::string &prefix, const std::string &uri) { this->handleNamespace(prefix, uri); },
              [this](const std::string &msg) { this->handleError(msg); }, base_uri) {
	if (!filesystem) {
		throw std::runtime_error("XMLBuffer requires a valid DuckDB FileSystem pointer");
	}
	this->_fs = filesystem;
	try {
		this->_file_handle = this->_fs->OpenFile(this->_file_path, duckdb::FileFlags::FILE_FLAGS_READ);
	} catch (std::exception &err) {
		throw std::runtime_error("Could not open RDF file: " + this->_file_path + ": " + err.what());
	}
	_parser.setBlankNodePrefix("bnode");
}

XMLBuffer::~XMLBuffer() {
}

void XMLBuffer::PopulateChunk(duckdb::DataChunk &result) {
	_active_chunk = &result;
	_rows_filled = 0;

	// First drain overflow buffer if any
	while (!_overflow_queue.empty() && _rows_filled < STANDARD_VECTOR_SIZE) {
		RDFRow entry = _overflow_queue.front();
		_overflow_queue.pop_front();

		result.SetValue(0, _rows_filled, duckdb::Value(entry.graph));
		result.SetValue(1, _rows_filled, duckdb::Value(entry.subject));
		result.SetValue(2, _rows_filled, duckdb::Value(entry.predicate));
		result.SetValue(3, _rows_filled, duckdb::Value(entry.object));
		result.SetValue(4, _rows_filled, duckdb::Value(entry.datatype));
		result.SetValue(5, _rows_filled, duckdb::Value(entry.lang));
		_rows_filled++;
	}

	char temp_buffer[PARSING_CHUNK_SIZE];
	while (_rows_filled < STANDARD_VECTOR_SIZE && !_end_of_file) {
		int64_t bytes_read = _file_handle->Read(temp_buffer, PARSING_CHUNK_SIZE);
		if (bytes_read < PARSING_CHUNK_SIZE) {
			_end_of_file = true;
		}
		_parser.parseChunk(temp_buffer, (int)bytes_read, _end_of_file);
	}

	result.SetCardinality(_rows_filled);
	_active_chunk = nullptr;
}

void XMLBuffer::StartParse() {
}

void XMLBuffer::storeInVector(duckdb::Vector &vec, idx_t position, const std::string &value) {
	if (value.empty()) {
		duckdb::FlatVector::SetNull(vec, position, true);
		return;
	}
	auto str = duckdb::StringVector::AddString(vec, value);
	duckdb::FlatVector::GetData<duckdb::string_t>(vec)[position] = str;
}

void XMLBuffer::handleStatement(const RdfStatement &stmt) {
	if (_rows_filled >= STANDARD_VECTOR_SIZE) {
		RDFRow row;
		row.subject = stmt.subject;
		row.predicate = stmt.predicate;
		row.object = stmt.object;
		row.graph = "";
		row.datatype = stmt.datatype;
		row.lang = stmt.language;
		_overflow_queue.push_back(std::move(row));
		return;
	}

	storeInVector(_active_chunk->data[0], _rows_filled, "");
	storeInVector(_active_chunk->data[1], _rows_filled, stmt.subject);
	storeInVector(_active_chunk->data[2], _rows_filled, stmt.predicate);
	storeInVector(_active_chunk->data[3], _rows_filled, stmt.object);
	storeInVector(_active_chunk->data[4], _rows_filled, stmt.datatype);
	storeInVector(_active_chunk->data[5], _rows_filled, stmt.language);
	_rows_filled++;
}

void XMLBuffer::handleNamespace(const std::string &prefix, const std::string &uri) {
	_parser.addNameSpace(prefix, uri);
}

void XMLBuffer::handleError(const std::string &msg) {
	throw duckdb::SyntaxException("Error: " + msg);
}

#include "core/cancellation.h"
#include "gtest/gtest.h"

namespace slop {
namespace {

// Test that a newly created CancellationRequest is not cancelled by default
TEST(CancellationRequestTest, InitialState) {
  CancellationRequest request;
  EXPECT_FALSE(request.IsCancelled());
}

// Test that calling Cancel sets the state to cancelled
TEST(CancellationRequestTest, Cancel) {
  CancellationRequest request;
  request.Cancel();
  EXPECT_TRUE(request.IsCancelled());
}

// Test that calling Cancel multiple times still leaves the request in cancelled state
TEST(CancellationRequestTest, MultipleCancel) {
  CancellationRequest request;
  request.Cancel();
  request.Cancel();
  EXPECT_TRUE(request.IsCancelled());
}

// Test that callbacks registered before cancellation are invoked on cancel
TEST(CancellationRequestTest, RegisterCallbackBeforeCancel) {
  CancellationRequest request;
  bool executed = false;
  request.RegisterCallback([&] { executed = true; });
  EXPECT_FALSE(executed);
  request.Cancel();
  EXPECT_TRUE(executed);
}

// Test that callbacks registered after cancellation are invoked immediately
TEST(CancellationRequestTest, RegisterCallbackAfterCancel) {
  CancellationRequest request;
  request.Cancel();
  bool executed = false;
  request.RegisterCallback([&] { executed = true; });
  EXPECT_TRUE(executed);
}

// Test that multiple callbacks are all invoked on cancellation
TEST(CancellationRequestTest, MultipleCallbacks) {
  CancellationRequest request;
  int counter = 0;
  request.RegisterCallback([&] { counter++; });
  request.RegisterCallback([&] { counter++; });
  request.Cancel();
  EXPECT_EQ(counter, 2);
}

