namespace flutter_engine_bridge {

// static
void FlutterEngineBridgePlugin::RegisterWithRegistrar(
    flutter::PluginRegistrarWindows *registrar) {
  auto channel =
      std::make_unique<flutter::MethodChannel<flutter::EncodableValue>>(
          registrar->messenger(), "flutter_engine_bridge",
          &flutter::StandardMethodCodec::GetInstance());
  auto plugin_instance = std::make_unique<FlutterEngineBridgePlugin>();
  channel->SetMethodCallHandler(
      [plugin_ptr = plugin_instance.get()](const auto &call, auto result) {
        plugin_ptr->HandleMethodCall(call, std::move(result));
      });
  registrar->AddPlugin(std::move(plugin_instance));
}

FlutterEngineBridgePlugin::FlutterEngineBridgePlugin() {}

FlutterEngineBridgePlugin::~FlutterEngineBridgePlugin() {}

void FlutterEngineBridgePlugin::HandleMethodCall(
    const flutter::MethodCall<flutter::EncodableValue> &method_call,
    std::unique_ptr<flutter::MethodResult<flutter::EncodableValue>> result) {
  if (method_call.method_name().compare("getPlatformVersion") == 0) {
    std::ostringstream version_stream;
    version_stream << "Windows ";
    if (IsWindows10OrGreater()) {
      version_stream << "10+";
    } else if (IsWindows8OrGreater()) {
      version_stream << "8";
    } else if (IsWindows7OrGreater()) {
      version_stream << "7";
    }
    result->Success(flutter::EncodableValue(version_stream.str()));
  } else {
    result->NotImplemented();
  }
}

