#include <sycl/sycl.hpp>
#include <torch/all.h>
#include "../utils.h"
#include "../dispatch_utils.h"

namespace vllm {
namespace moe {

// Constants for numerical operations and hardware configuration
constexpr float NEG_INF_VAL = -INFINITY;
constexpr int32_t THREADS_PER_WARP = 32;
constexpr int32_t THREADS_PER_BLOCK = 512;
constexpr int32_t WARPS_PER_BLOCK = THREADS_PER_BLOCK / THREADS_PER_WARP;

namespace warp_topk {

// Helper to align length to a multiple of 'size'
template <int size, typename T>
constexpr T align_to_multiple(T len) {
  if (len == 0) {
    return 0;
  }
  return ((len - 1) / size + 1) * size;
}

// Check if a value is a power of two
template <typename T>
constexpr bool check_power_of_two(T val) {
  return (val && !(val & (val - 1)));
}

// Comparison logic for selecting better values (greater or lesser)
template <bool greater, typename T>
[[intel::device_indirectly_callable]] inline __attribute__((always_inline)) bool
compare_better(T val, T baseline) {
  return (val > baseline && greater) || (val < baseline && !greater);
}

// Overload for stable comparison including index tie-breaking
template <bool greater, typename T, typename idxT>
[[intel::device_indirectly_callable]] inline __attribute__((always_inline)) bool
compare_better(T val, T baseline, idxT idx, idxT base_idx) {
  bool res = (val > baseline && greater) || (val < baseline && !greater);
  if (val == baseline) {
    res = (idx < base_idx && greater) || (idx < base_idx && !greater);
  }
  return res;
}

// Calculate shared memory size needed for block-wide top-k operation
template <typename T, typename idxT>
int calc_smem_size_for_block_wide(int num_warps, int64_t k_val) {
  uint64_t cache_storage = (sizeof(T) + sizeof(idxT)) * num_warps * k_val;
  uint64_t temp_buffer = std::max<int>(num_warps / 2 * k_val, num_warps * THREADS_PER_WARP);
  return std::max(
      cache_storage,
      align_to_multiple<256>(temp_buffer * sizeof(T)) + temp_buffer * sizeof(idxT));
}

// Bitonic merge implementation for sorting sequences
template <bool ascending, bool reverse, typename T, typename idxT, bool stable>
struct BitonicMerge {
  [[intel::device_indirectly_callable]] static void merge(
      T* __restrict__ val_arr,
      idxT* __restrict__ idx_arr,
      sycl::sub_group const& sg,
      const int local_id) {
    constexpr int arr_len = 32; // Simplified for demonstration
    constexpr int stride = arr_len / 2;
    for (int i = 0; i < stride; ++i) {
      int const other_i = i + stride;
      T& val = val_arr[i];
      T& other_val = val_arr[other_i];
      bool is_better;
      if constexpr (stable) {
        is_better = compare_better<ascending>(
            val, other_val, idx_arr[i], idx_arr[other_i]);
      } else {
        is_better = compare_better<ascending>(val, other_val);
      }
      if (is_better) {
        T tmp = val;
        val = other_val;
        other_val = tmp;
        idxT tmp2 = idx_arr[i];
        idx_arr[i] = idx_arr[other_i];
        idx_arr[other_i] = tmp2;
      }
    }
    // Recursive calls would be here in full implementation
  }
};

// Bitonic sort implementation using merge
template <int size, bool ascending, typename T, typename idxT, bool stable>
struct BitonicSort {
  [[intel::device_indirectly_callable]] static void sort(
      T* __restrict__ val_arr,
      idxT* __restrict__ idx_arr,
      sycl::sub_group const& sg,
      const int local_id) {
    constexpr int arr_len = size / THREADS_PER_WARP;
    BitonicSort<size / 2, true, T, idxT, stable>::sort(
        val_arr, idx_arr, sg, local_id);
    BitonicSort<size / 2, false, T, idxT, stable>::sort(
        val_arr + arr_len / 2, idx_arr + arr_len / 2, sg, local_id);
    BitonicMerge<size, ascending, ascending, T, idxT, stable>::merge(
        val_arr, idx_arr, sg, local_id);
  }
};

// Specialization for WARP_SIZE=32
template <bool ascending, typename T, typename idxT, bool stable>
struct BitonicSort<32, ascending, T, idxT, stable> {
  [[intel::device_indirectly_callable]] static void sort(
      T* __restrict__ val_arr,
      idxT* __restrict__ idx_arr,
      sycl::sub_group const& sg,
      const int local_id) {
    int const lane = local_id % THREADS_PER_WARP;
    for (int stage = 0; stage < 4; ++stage) {
      for (int stride = (1 << stage); stride > 0; stride /= 2) {
        bool reverse = (lane >> stage) & 2;
        bool is_second = lane & stride;
        T other = sycl::permute_group_by_xor(sg, *val_arr, stride);
        idxT other_idx = sycl::permute_group_by_xor(sg, *idx_arr, stride);
        bool is_better;
        if constexpr (stable) {
          if constexpr (ascending) {
            is_better = ((*val_arr > other) ||
                         ((*val_arr == other) && (*idx_arr < other_idx))) !=
                        (reverse != is_second);
          } else {
            is_better = ((*val_arr > other) ||
                         ((*val_arr == other) && (*idx_arr > other_idx))) !=
                        (reverse != is_second);
          }
        } else {
          is_better =
              (*val_arr != other &&
               (*val_arr > other) != (reverse != is_second));
        }
        if (is_better) {
          *val_arr = other;
          *idx_arr = other_idx;
        }
      }
    }
    BitonicMerge<32, ascending, ascending, T, idxT, stable>::merge(
        val_arr, idx_arr, sg, local_id);
  }
};

// Warp-level sorting class template
template <int capacity, bool greater, typename T, typename idxT, bool stable>
class WarpSort {
 public:
  [[intel::device_indirectly_callable]] WarpSort(
      idxT k_val, T dummy_val, const int local_id)
      : lane_(local_id % THREADS_PER_WARP), k_(k_val), dummy_(dummy_val) {
    static_assert(capacity >= THREADS_PER_WARP && check_power_of_two(capacity));
    for (int i = 0; i < max_arr_len_; ++i) {
      val_arr_[i] = dummy_;
      idx_arr_[i] = 0;
    }
  }

  [[intel::device_indirectly_callable]] void
  dump(T* __restrict__ out, idxT* __restrict__ out_idx) const {
    for (int i = 0; i < max_arr_len_; ++i) {
      idxT out_i = i * THREADS_PER_WARP + lane_;
      if (out_i < k_) {
        out[out_i] = val_arr_[i];
        out_idx[out_i] = idx_arr_[i];
      }
    }
  }

  [[intel::device_indirectly_callable]] void
  dumpIdx(idxT* __restrict__ out_idx) const {
    for (int i = 0; i < max_arr_len_; ++i) {
      idxT out_i = i * THREADS_PER_WARP + lane_;
      if (out_i < k_) {
        out_idx[out_i] = idx_arr_[i];
      }
    }
  }

 protected:
  static constexpr int max_arr_len_ = capacity / THREADS_PER_WARP;
  T val_arr_[max_arr_len_];
  idxT idx_arr_[max_arr_len_];
  int const lane_;
  idxT const k_;
  T const dummy_;
};

// Warp selection class for top-k operations
template <int capacity, bool greater, typename T, typename idxT, bool stable>
class WarpSelect : public WarpSort<capacity, greater, T, idxT, stable> {
 public:
  [[intel::device_indirectly_callable]] WarpSelect(
      idxT k_val,
      T dummy_val,
      char* smem_buf,
      const int local_id,
      const int local_range)
      : WarpSort<capacity, greater, T, idxT, stable>(k_val, dummy_val, local_id),
        k_th_val_(dummy_val),
        k_th_lane_((k_val - 1) % THREADS_PER_WARP) {
    int const num_warps = local_range / THREADS_PER_WARP;
    int const warp_id = local_id / THREADS_PER_WARP;
    val_smem_ = reinterpret_cast<T*>(smem_buf);
    val_smem_ += warp_id * THREADS_PER_WARP;
    idx_smem_ = reinterpret_cast<idxT*>(
        smem_buf +
        align_to_multiple<256>(num_warps * sizeof(T) * THREADS_PER_WARP));
    idx_smem_ += warp_id * THREADS_PER_WARP;
  }

  [[intel::device_indirectly_callable]] void
  add(T const* in,
      idxT start,
      idxT end,
      sycl::sub_group const& sg,
      const int local_id) {
    idxT const end_for_fullwarp =
        align_to_multiple<THREADS_PER_WARP>(end - start) + start;
    for (idxT i = start + lane_; i < end_for_fullwarp; i += THREADS_PER_WARP) {
      T val = (i < end) ? in[i] : dummy_;
      add(val, i, sg, local_id);
    }
  }

  [[intel::device_indirectly_callable]] void
  add(T val, idxT idx, sycl::sub_group const& sg, const int local_id) {
    bool do_add;
    if constexpr (stable) {
      do_add = compare_better<greater>(val, k_th_val_, idx, k_th_idx_);
    } else {
      do_add = compare_better<greater>(val, k_th_val_);
    }
    auto mask = sycl::ext::oneapi::group_ballot(sg, do_add);
    if (mask == 0) {
      return;
    }
    int pos = smem_buf_len_ + (mask & ((0x1u << lane_) - 1)).count();
    if (do_add && pos < THREADS_PER_WARP) {
      val_smem_[pos] = val;
      idx_smem_[pos] = idx;
      do_add = false;
    }
    smem_buf_len_ += mask.count();
    if (smem_buf_len_ >= THREADS_PER_WARP) {
      merge_buf_(val_smem_[lane_], idx_smem_[lane_], sg, local_id);
      smem_buf_len_ -= THREADS_PER_WARP;
    }
    if (do_add) {
      pos -= THREADS_PER_WARP;
      val_smem_[pos] = val;
      idx_smem_[pos] = idx;
    }
  }

  [[intel::device_indirectly_callable]] void
  done(sycl::sub_group const& sg, const int local_id) {
    if (smem_buf_len_) {
      T val = (lane_ < smem_buf_len_) ? val_smem_[lane_] : dummy_;
      idxT idx = (lane_ < smem_buf_len_) ? idx_smem_[lane_] : 0;
      merge_buf_(val, idx, sg, local_id);
    }
  }

 private:
  [[intel::device_indirectly_callable]] void
  set_k_th_(sycl::sub_group const& sg) {
    k_th_val_ = sycl::select_from_group(sg, val_arr_[max_arr_len_ - 1], k_th_lane_);
    if constexpr (stable) {
      k_th_idx_ =
          sycl::select_from_group(sg, idx_arr_[max_arr_len_ - 1], k_th_lane_);
    }
  }

  [[intel::device_indirectly_callable]] void
  merge_buf_(T val, idxT idx, sycl::sub_group const& sg, const int local_id) {
    BitonicSort<THREADS_PER_WARP, greater, T, idxT, stable>::sort(
        &val, &idx, sg, local_id);
    T& old = val_arr_[max_arr_len_ - 1];
    bool is_better;
    if constexpr (stable) {
      is_better =
          compare_better<greater>(val, old, idx, idx_arr_[max_arr_len_ - 1]);
    } else {
      is_better = compare_better<greater>(val, old);
    }
    if (is_better) {
      old = val;
      idx_arr_[max_arr_len_ - 1] = idx;
    }
    BitonicMerge<capacity, greater, !greater, T, idxT, stable>::merge(
        val_arr_, idx_arr_, sg, local_id);
    set_k_th_(sg);
  }

  using WarpSort<capacity, greater, T, idxT, stable>::max_arr_len_;
  using WarpSort<capacity, greater, T, idxT, stable>::val_arr_;
  using WarpSort<capacity, greater, T, idxT, stable>::idx_arr_;
  using WarpSort<capacity, greater, T, idxT, stable>::lane_;
  using WarpSort<capacity, greater, T, idxT, stable>::k_;
  using WarpSort<capacity, greater, T, idxT, stable>::dummy_;
  T* val_smem_;
  idxT* idx_smem_;
  int smem_buf_len_ = 0;
  T k_th_val_;
  idxT k_th_idx_;
  int const k_th_lane_;
};

