bool WinsockNetLayer::Initialize()
{
	if (s_setupComplete) return true;

	WSADATA wsaData;
	int status = WSAStartup(MAKEWORD(2, 2), &wsaData);
	if (status != 0)
	{
		app.DebugPrintf("WSAStartup failed: %d\n", status);
		return false;
	}

	InitializeCriticalSection(&s_transmitMutex);
	InitializeCriticalSection(&s_peerListMutex);
	InitializeCriticalSection(&s_broadcastMutex);
	InitializeCriticalSection(&s_searchMutex);
	InitializeCriticalSection(&s_removeMutex);
	InitializeCriticalSection(&s_releaseIdMutex);

	s_setupComplete = true;
	StartSearch();
	return true;
}

void WinsockNetLayer::Shutdown()
{
	StopBroadcasting();
	StopSearch();

	s_running = false;
	s_linkEstablished = false;

	if (s_serverSocket != INVALID_SOCKET)
	{
		closesocket(s_serverSocket);
		s_serverSocket = INVALID_SOCKET;
	}

	if (s_clientConnectionSocket != INVALID_SOCKET)
	{
		closesocket(s_clientConnectionSocket);
		s_clientConnectionSocket = INVALID_SOCKET;
	}

	EnterCriticalSection(&s_peerListMutex);
	for (size_t i = 0; i < s_activePeers.size(); i++)
	{
		s_activePeers[i].active = false;
		if (s_activePeers[i].tcpSocket != INVALID_SOCKET)
		{
			closesocket(s_activePeers[i].tcpSocket);
		}
	}
	s_activePeers.clear();
	LeaveCriticalSection(&s_peerListMutex);

	if (s_acceptLoopThread != NULL)
	{
		WaitForSingleObject(s_acceptLoopThread, 2000);
		CloseHandle(s_acceptLoopThread);
		s_acceptLoopThread = NULL;
	}

	if (s_clientListenThread != NULL)
	{
		WaitForSingleObject(s_clientListenThread, 2000);
		CloseHandle(s_clientListenThread);
		s_clientListenThread = NULL;
	}

	if (s_setupComplete)
	{
		DeleteCriticalSection(&s_transmitMutex);
		DeleteCriticalSection(&s_peerListMutex);
		DeleteCriticalSection(&s_broadcastMutex);
		DeleteCriticalSection(&s_searchMutex);
		DeleteCriticalSection(&s_removeMutex);
		s_removedIds.clear();
		DeleteCriticalSection(&s_releaseIdMutex);
		s_availableIds.clear();
		WSACleanup();
		s_setupComplete = false;
	}
}

bool WinsockNetLayer::StartServer(int port)
{
	if (!s_setupComplete && !Initialize()) return false;

	s_isServer = true;
	s_localPlayerId = 0;
	s_remotePlayerId = 0;
	s_nextAvailableId = 1;
	s_gamePort = port;

	EnterCriticalSection(&s_releaseIdMutex);
	s_availableIds.clear();
	LeaveCriticalSection(&s_releaseIdMutex);

	struct addrinfo hints = {};
	struct addrinfo *result = NULL;
	hints.ai_family = AF_INET;
	hints.ai_socktype = SOCK_STREAM;
	hints.ai_protocol = IPPROTO_TCP;
	hints.ai_flags = AI_PASSIVE;

	char portStr[16];
	sprintf_s(portStr, "%d", port);

	int iResult = getaddrinfo(NULL, portStr, &hints, &result);
	if (iResult != 0)
	{
		app.DebugPrintf("getaddrinfo failed: %d\n", iResult);
		return false;
	}

	s_serverSocket = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
	if (s_serverSocket == INVALID_SOCKET)
	{
		app.DebugPrintf("socket() failed: %d\n", WSAGetLastError());
		freeaddrinfo(result);
		return false;
	}

	int opt = 1;
	setsockopt(s_serverSocket, SOL_SOCKET, SO_REUSEADDR, (const char *)&opt, sizeof(opt));

	iResult = ::bind(s_serverSocket, result->ai_addr, (int)result->ai_addrlen);
	freeaddrinfo(result);

	if (iResult == SOCKET_ERROR)
	{
		app.DebugPrintf("bind() failed: %d\n", WSAGetLastError());
		closesocket(s_serverSocket);
		s_serverSocket = INVALID_SOCKET;
		return false;
	}

	iResult = listen(s_serverSocket, SOMAXCONN);
	if (iResult == SOCKET_ERROR)
	{
		app.DebugPrintf("listen() failed: %d\n", WSAGetLastError());
		closesocket(s_serverSocket);
		s_serverSocket = INVALID_SOCKET;
		return false;
	}

	s_running = true;
	s_linkEstablished = true;
	s_acceptLoopThread = CreateThread(NULL, 0, AcceptLoopProc, NULL, 0, NULL);

	app.DebugPrintf("Win64 LAN: Hosting on port %d\n", port);
	return true;
}

bool WinsockNetLayer::ConnectToServer(const char *ip, int port)
{
	if (!s_setupComplete && !Initialize()) return false;

	s_isServer = false;
	s_remotePlayerId = 0;
	s_linkEstablished = false;
	s_running = false;

	if (s_clientConnectionSocket != INVALID_SOCKET)
	{
		closesocket(s_clientConnectionSocket);
		s_clientConnectionSocket = INVALID_SOCKET;
	}

	struct addrinfo hints = {};
	struct addrinfo *result = NULL;
	hints.ai_family = AF_INET;
	hints.ai_socktype = SOCK_STREAM;
	hints.ai_protocol = IPPROTO_TCP;

	char portStr[16];
	sprintf_s(portStr, "%d", port);

	int iResult = getaddrinfo(ip, portStr, &hints, &result);
	if (iResult != 0)
	{
		app.DebugPrintf("getaddrinfo failed for %s:%d - %d\n", ip, port, iResult);
		return false;
	}

	bool connected = false;
	BYTE assignedId = 0;
	const int maxRetries = 3;
	const int timeoutMs = 3000;

	for (int attempt = 0; attempt < maxRetries; ++attempt)
	{
		s_clientConnectionSocket = socket(result->ai_family, result->ai_socktype, result->ai_protocol);
		if (s_clientConnectionSocket == INVALID_SOCKET)
		{
			app.DebugPrintf("socket() failed: %d\n", WSAGetLastError());
			break;
		}

		int noDelay = 1;
		setsockopt(s_clientConnectionSocket, IPPROTO_TCP, TCP_NODELAY, (const char *)&noDelay, sizeof(noDelay));

		u_long nonBlocking = 1;
		ioctlsocket(s_clientConnectionSocket, FIONBIO, &nonBlocking);

		iResult = connect(s_clientConnectionSocket, result->ai_addr, (int)result->ai_addrlen);
		if (iResult == SOCKET_ERROR)
		{
			int err = WSAGetLastError();
			if (err == WSAEWOULDBLOCK)
			{
				fd_set writeFds, exceptFds;
				FD_ZERO(&writeFds);
				FD_ZERO(&exceptFds);
				FD_SET(s_clientConnectionSocket, &writeFds);
				FD_SET(s_clientConnectionSocket, &exceptFds);

				struct timeval tv;
				tv.tv_sec = timeoutMs / 1000;
				tv.tv_usec = (timeoutMs % 1000) * 1000;

				int selectResult = select(0, NULL, &writeFds, &exceptFds, &tv);
				if (selectResult <= 0 || FD_ISSET(s_clientConnectionSocket, &exceptFds))
				{
					app.DebugPrintf("connect() to %s:%d timed out or failed (attempt %d/%d)\n", ip, port, attempt + 1, maxRetries);
					closesocket(s_clientConnectionSocket);
					s_clientConnectionSocket = INVALID_SOCKET;
					continue;
				}

				int sockErr = 0;
				int sockErrLen = sizeof(sockErr);
				getsockopt(s_clientConnectionSocket, SOL_SOCKET, SO_ERROR, (char *)&sockErr, &sockErrLen);
				if (sockErr != 0)
				{
					app.DebugPrintf("connect() to %s:%d failed with SO_ERROR %d (attempt %d/%d)\n", ip, port, sockErr, attempt + 1, maxRetries);
					closesocket(s_clientConnectionSocket);
					s_clientConnectionSocket = INVALID_SOCKET;
					continue;
				}
			}
			else
			{
				app.DebugPrintf("connect() to %s:%d failed (attempt %d/%d): %d\n", ip, port, attempt + 1, maxRetries, err);
				closesocket(s_clientConnectionSocket);
				s_clientConnectionSocket = INVALID_SOCKET;
				continue;
			}
		}

		u_long blocking = 0;
		ioctlsocket(s_clientConnectionSocket, FIONBIO, &blocking);

		DWORD recvTimeout = 3000;
		setsockopt(s_clientConnectionSocket, SOL_SOCKET, SO_RCVTIMEO, (const char *)&recvTimeout, sizeof(recvTimeout));

		BYTE idBuffer[1];
		int bytesReceived = recv(s_clientConnectionSocket, (char *)idBuffer, 1, 0);
		if (bytesReceived != 1)
		{
			app.DebugPrintf("Failed to receive player ID from server (attempt %d/%d)\n", attempt + 1, maxRetries);
			closesocket(s_clientConnectionSocket);
			s_clientConnectionSocket = INVALID_SOCKET;
			continue;
		}

		assignedId = idBuffer[0];
		connected = true;
		break;
	}

	freeaddrinfo(result);

	if (!connected)
	{
		return false;
	}

	s_localPlayerId = assignedId;

	app.DebugPrintf("Win64 LAN: Connected to %s:%d, assigned playerId=%d\n", ip, port, s_localPlayerId);
	s_running = true;
	s_linkEstablished = true;
	s_clientListenThread = CreateThread(NULL, 0, ClientListenProc, NULL, 0, NULL);

	return true;
}

bool WinsockNetLayer::TransmitOnSocket(SOCKET sock, const void *data, int size)
{
	if (sock == INVALID_SOCKET || size <= 0) return false;

	EnterCriticalSection(&s_transmitMutex);

	BYTE header[4];
	header[0] = (BYTE)((size >> 24) & 0xFF);
	header[1] = (BYTE)((size >> 16) & 0xFF);
	header[2] = (BYTE)((size >> 8) & 0xFF);
	header[3] = (BYTE)(size & 0xFF);

	int totalSent = 0;
	int toSend = 4;

	while (totalSent < toSend)
	{
		int sent = send(sock, (const char *)header + totalSent, toSend - totalSent, 0);
		if (sent == SOCKET_ERROR || sent == 0)
		{
			LeaveCriticalSection(&s_transmitMutex);
			return false;
		}
		totalSent += sent;
	}

	totalSent = 0;
	while (totalSent < size)
	{
		int sent = send(sock, (const char *)data + totalSent, size - totalSent, 0);
		if (sent == SOCKET_ERROR || sent == 0)
		{
			LeaveCriticalSection(&s_transmitMutex);
			return false;
		}
		totalSent += sent;
	}

	LeaveCriticalSection(&s_transmitMutex);
	return true;
}

bool WinsockNetLayer::SendToPlayer(BYTE targetId, const void *data, int size)
{
	if (!s_running) return false;

	if (s_isServer)
	{
		SOCKET sock = GetSocketForPlayerId(targetId);
		if (sock == INVALID_SOCKET) return false;
		return TransmitOnSocket(sock, data, size);
	}
	else
	{
		return TransmitOnSocket(s_clientConnectionSocket, data, size);
	}
}

SOCKET WinsockNetLayer::GetSocketForPlayerId(BYTE playerId)
{
	EnterCriticalSection(&s_peerListMutex);
	for (size_t i = 0; i < s_activePeers.size(); i++)
	{
		if (s_activePeers[i].playerId == playerId && s_activePeers[i].active)
		{
			SOCKET sock = s_activePeers[i].tcpSocket;
			LeaveCriticalSection(&s_peerListMutex);
			return sock;
		}
	}
	LeaveCriticalSection(&s_peerListMutex);
	return INVALID_SOCKET;
}

static bool ReceiveExact(SOCKET sock, BYTE *buffer, int length)
{
	int totalReceived = 0;
	while (totalReceived < length)
	{
		int r = recv(sock, (char *)buffer + totalReceived, length - totalReceived, 0);
		if (r <= 0) return false;
		totalReceived += r;
	}
	return true;
}

void WinsockNetLayer::ProcessReceivedData(BYTE fromId, BYTE toId, unsigned char *data, unsigned int size)
{
	INetworkPlayer *pSender = g_NetworkManager.GetPlayerBySmallId(fromId);
	INetworkPlayer *pRecipient = g_NetworkManager.GetPlayerBySmallId(toId);

	if (pSender == NULL || pRecipient == NULL) return;

	if (s_isServer)
	{
		::Socket *pSocket = pSender->GetSocket();
		if (pSocket != NULL)
			pSocket->pushDataToQueue(data, size, false);
	}
	else
	{
		::Socket *pSocket = pRecipient->GetSocket();
		if (pSocket != NULL)
			pSocket->pushDataToQueue(data, size, true);
	}
}

DWORD WINAPI WinsockNetLayer::AcceptLoopProc(LPVOID param)
{
	while (s_running)
	{
		SOCKET clientSocket = accept(s_serverSocket, NULL, NULL);
		if (clientSocket == INVALID_SOCKET)
		{
			if (s_running)
				app.DebugPrintf("accept() failed: %d\n", WSAGetLastError());
			break;
		}

		int noDelay = 1;
		setsockopt(clientSocket, IPPROTO_TCP, TCP_NODELAY, (const char *)&noDelay, sizeof(noDelay));

		extern QNET_STATE _iQNetStubState;
		if (_iQNetStubState != QNET_STATE_GAME_PLAY)
		{
			app.DebugPrintf("Win64 LAN: Rejecting connection, game not ready\n");
			closesocket(clientSocket);
			continue;
		}

		BYTE assignedId;
		EnterCriticalSection(&s_releaseIdMutex);
		if (!s_availableIds.empty())
		{
			assignedId = s_availableIds.back();
			s_availableIds.pop_back();
		}
		else if (s_nextAvailableId < MINECRAFT_NET_MAX_PLAYERS)
		{
			assignedId = s_nextAvailableId++;
		}
		else
		{
			LeaveCriticalSection(&s_releaseIdMutex);
			app.DebugPrintf("Win64 LAN: Server full, rejecting connection\n");
			closesocket(clientSocket);
			continue;
		}
		LeaveCriticalSection(&s_releaseIdMutex);

		BYTE idBuffer[1] = { assignedId };
		int sent = send(clientSocket, (const char *)idBuffer, 1, 0);
		if (sent != 1)
		{
			app.DebugPrintf("Failed to send player ID to client\n");
			closesocket(clientSocket);
			continue;
		}

		Win64RemoteConnection conn;
		conn.tcpSocket = clientSocket;
		conn.playerId = assignedId;
		conn.active = true;
		conn.listenThread = NULL;

		EnterCriticalSection(&s_peerListMutex);
		s_activePeers.push_back(conn);
		int index = (int)s_activePeers.size() - 1;
		LeaveCriticalSection(&s_peerListMutex);

		app.DebugPrintf("Win64 LAN: Client connected, assigned playerId=%d\n", assignedId);

		IQNetPlayer *qnetPlayer = &IQNet::m_player[assignedId];
		extern void Win64_SetupRemoteQNetPlayer(IQNetPlayer *player, BYTE playerId, bool isHost, bool isLocal);
		Win64_SetupRemoteQNetPlayer(qnetPlayer, assignedId, false, false);

		extern CPlatformNetworkManagerStub *g_pPlatformNetworkManager;
		g_pPlatformNetworkManager->NotifyPlayerJoined(qnetPlayer);

		DWORD *threadParam = new DWORD;
		*threadParam = index;

		HANDLE hThread = CreateThread(NULL, 0, ListenLoopProc, threadParam, 0, NULL);

		EnterCriticalSection(&s_peerListMutex);
		if (index < (int)s_activePeers.size())
			s_activePeers[index].listenThread = hThread;
		LeaveCriticalSection(&s_peerListMutex);
	}

	return 0;
}

DWORD WINAPI WinsockNetLayer::ListenLoopProc(LPVOID param)
{
	DWORD peerIndex = *(DWORD *)param;
	delete (DWORD *)param;

	EnterCriticalSection(&s_peerListMutex);
	if (peerIndex >= (DWORD)s_activePeers.size())
	{
		LeaveCriticalSection(&s_peerListMutex);
		return 0;
	}

	SOCKET sock = s_activePeers[peerIndex].tcpSocket;
	BYTE clientId = s_activePeers[peerIndex].playerId;
	LeaveCriticalSection(&s_peerListMutex);

	std::vector<BYTE> buffer;
	buffer.resize(WIN64_NET_RECV_BUFFER_SIZE);

	while (s_running)
	{
		BYTE header[4];
		if (!ReceiveExact(sock, header, 4))
		{
			app.DebugPrintf("Win64 LAN: Client playerId=%d disconnected (header)\n", clientId);
			break;
		}

		int packetSize =
			((uint32_t)header[0] << 24) |
			((uint32_t)header[1] << 16) |
			((uint32_t)header[2] << 8) |
			((uint32_t)header[3]);

		if (packetSize <= 0 || packetSize > WIN64_NET_MAX_PACKET_SIZE)
		{
			app.DebugPrintf("Win64 LAN: Invalid packet size %d from client playerId=%d (max=%d)\n",
				packetSize,
				clientId,
				(int)WIN64_NET_MAX_PACKET_SIZE);
			break;
		}

		if ((int)buffer.size() < packetSize)
		{
			buffer.resize(packetSize);
			app.DebugPrintf("Win64 LAN: Resized host recv buffer to %d bytes for client playerId=%d\n", packetSize, clientId);
		}

		if (!ReceiveExact(sock, &buffer[0], packetSize))
		{
			app.DebugPrintf("Win64 LAN: Client playerId=%d disconnected (body)\n", clientId);
			break;
		}

		ProcessReceivedData(clientId, s_remotePlayerId, &buffer[0], packetSize);
	}

	EnterCriticalSection(&s_peerListMutex);
	for (size_t i = 0; i < s_activePeers.size(); i++)
	{
		if (s_activePeers[i].playerId == clientId)
		{
			s_activePeers[i].active = false;
			if (s_activePeers[i].tcpSocket != INVALID_SOCKET)
			{
				closesocket(s_activePeers[i].tcpSocket);
				s_activePeers[i].tcpSocket = INVALID_SOCKET;
			}
			break;
		}
	}
	LeaveCriticalSection(&s_peerListMutex);

	EnterCriticalSection(&s_removeMutex);
	s_removedIds.push_back(clientId);
	LeaveCriticalSection(&s_removeMutex);

	return 0;
}

bool WinsockNetLayer::PopRemovedPlayerId(BYTE *outId)
{
	bool found = false;
	EnterCriticalSection(&s_removeMutex);
	if (!s_removedIds.empty())
	{
		*outId = s_removedIds.back();
		s_removedIds.pop_back();
		found = true;
	}
	LeaveCriticalSection(&s_removeMutex);
	return found;
}

void WinsockNetLayer::ReleasePlayerId(BYTE playerId)
{
	EnterCriticalSection(&s_releaseIdMutex);
	s_availableIds.push_back(playerId);
	LeaveCriticalSection(&s_releaseIdMutex);
}

void WinsockNetLayer::ForceCloseConnection(BYTE playerId)
{
	EnterCriticalSection(&s_peerListMutex);
	for (size_t i = 0; i < s_activePeers.size(); i++)
	{
		if (s_activePeers[i].playerId == playerId && s_activePeers[i].active && s_activePeers[i].tcpSocket != INVALID_SOCKET)
		{
			closesocket(s_activePeers[i].tcpSocket);
			s_activePeers[i].tcpSocket = INVALID_SOCKET;
			app.DebugPrintf("Win64 LAN: Force-closed TCP connection for playerId=%d\n", playerId);
			break;
		}
	}
	LeaveCriticalSection(&s_peerListMutex);
}

DWORD WINAPI WinsockNetLayer::ClientListenProc(LPVOID param)
{
	std::vector<BYTE> buffer;
	buffer.resize(WIN64_NET_RECV_BUFFER_SIZE);

	while (s_running && s_clientConnectionSocket != INVALID_SOCKET)
	{
		BYTE header[4];
		if (!ReceiveExact(s_clientConnectionSocket, header, 4))
		{
			app.DebugPrintf("Win64 LAN: Disconnected from server (header)\n");
			break;
		}

		int packetSize = (header[0] << 24) | (header[1] << 16) | (header[2] << 8) | header[3];

		if (packetSize <= 0 || packetSize > WIN64_NET_MAX_PACKET_SIZE)
		{
			app.DebugPrintf("Win64 LAN: Invalid packet size %d from server (max=%d)\n",
				packetSize,
				(int)WIN64_NET_MAX_PACKET_SIZE);
			break;
		}

		if ((int)buffer.size() < packetSize)
		{
			buffer.resize(packetSize);
			app.DebugPrintf("Win64 LAN: Resized client recv buffer to %d bytes\n", packetSize);
		}

		if (!ReceiveExact(s_clientConnectionSocket, &buffer[0], packetSize))
		{
			app.DebugPrintf("Win64 LAN: Disconnected from server (body)\n");
			break;
		}

		ProcessReceivedData(s_remotePlayerId, s_localPlayerId, &buffer[0], packetSize);
	}

	s_linkEstablished = false;
	return 0;
}

bool WinsockNetLayer::StartBroadcasting(int gamePort, const wchar_t *hostName, unsigned int gameSettings, unsigned int texPackId, unsigned char subTexId, unsigned short netVer)
{
	if (s_broadcasting) return true;
	if (!s_setupComplete) return false;

	EnterCriticalSection(&s_broadcastMutex);
	memset(&s_broadcastData, 0, sizeof(s_broadcastData));
	s_broadcastData.magic = WIN64_LAN_BROADCAST_MAGIC;
	s_broadcastData.netVersion = netVer;
	s_broadcastData.gamePort = (WORD)gamePort;
	wcsncpy_s(s_broadcastData.hostName, 32, hostName, _TRUNCATE);
	s_broadcastData.playerCount = 1;
	s_broadcastData.maxPlayers = MINECRAFT_NET_MAX_PLAYERS;
	s_broadcastData.gameHostSettings = gameSettings;
	s_broadcastData.texturePackParentId = texPackId;
	s_broadcastData.subTexturePackId = subTexId;
	s_broadcastData.isJoinable = 0;
	s_gamePort = gamePort;
	LeaveCriticalSection(&s_broadcastMutex);

	s_broadcastSock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
	if (s_broadcastSock == INVALID_SOCKET)
	{
		app.DebugPrintf("Win64 LAN: Failed to create broadcast socket: %d\n", WSAGetLastError());
		return false;
	}

	BOOL broadcast = TRUE;
	setsockopt(s_broadcastSock, SOL_SOCKET, SO_BROADCAST, (const char *)&broadcast, sizeof(broadcast));

	s_broadcasting = true;
	s_broadcastThread = CreateThread(NULL, 0, BroadcastThreadProc, NULL, 0, NULL);

	app.DebugPrintf("Win64 LAN: Started broadcasting on UDP port %d\n", WIN64_LAN_DISCOVERY_PORT);
	return true;
}

void WinsockNetLayer::StopBroadcasting()
{
	s_broadcasting = false;

	if (s_broadcastSock != INVALID_SOCKET)
	{
		closesocket(s_broadcastSock);
		s_broadcastSock = INVALID_SOCKET;
	}

	if (s_broadcastThread != NULL)
	{
		WaitForSingleObject(s_broadcastThread, 2000);
		CloseHandle(s_broadcastThread);
		s_broadcastThread = NULL;
	}
}

void WinsockNetLayer::UpdateBroadcastPlayerCount(BYTE count)
{
	EnterCriticalSection(&s_broadcastMutex);
	s_broadcastData.playerCount = count;
	LeaveCriticalSection(&s_broadcastMutex);
}

void WinsockNetLayer::UpdateBroadcastPlayerNames(BYTE count, const char playerNames[][XUSER_NAME_SIZE])
{
	EnterCriticalSection(&s_broadcastMutex);
	memset(s_broadcastData.playerNames, 0, sizeof(s_broadcastData.playerNames));
	s_broadcastData.playerCount = count;

	for (int i = 0; i < count && i < 8; i++)
	{
		memcpy(s_broadcastData.playerNames[i], playerNames[i], XUSER_NAME_SIZE);
	}

	LeaveCriticalSection(&s_broadcastMutex);
}

void WinsockNetLayer::UpdateBroadcastJoinable(bool joinable)
{
	EnterCriticalSection(&s_broadcastMutex);
	s_broadcastData.isJoinable = joinable ? 1 : 0;
	LeaveCriticalSection(&s_broadcastMutex);
}

DWORD WINAPI WinsockNetLayer::BroadcastThreadProc(LPVOID param)
{
	struct sockaddr_in broadcastAddr;
	memset(&broadcastAddr, 0, sizeof(broadcastAddr));
	broadcastAddr.sin_family = AF_INET;
	broadcastAddr.sin_port = htons(WIN64_LAN_DISCOVERY_PORT);
	broadcastAddr.sin_addr.s_addr = INADDR_BROADCAST;

	while (s_broadcasting)
	{
		EnterCriticalSection(&s_broadcastMutex);
		Win64LANBroadcast data = s_broadcastData;
		LeaveCriticalSection(&s_broadcastMutex);

		int sent = sendto(s_broadcastSock, (const char *)&data, sizeof(data), 0,
			(struct sockaddr *)&broadcastAddr, sizeof(broadcastAddr));

		if (sent == SOCKET_ERROR && s_broadcasting)
		{
			app.DebugPrintf("Win64 LAN: Broadcast sendto failed: %d\n", WSAGetLastError());
		}

		Sleep(1000);
	}

	return 0;
}

bool WinsockNetLayer::StartSearch()
{
	if (s_scanning) return true;
	if (!s_setupComplete) return false;

	s_searchSock = socket(AF_INET, SOCK_DGRAM, IPPROTO_UDP);
	if (s_searchSock == INVALID_SOCKET)
	{
		app.DebugPrintf("Win64 LAN: Failed to create search socket: %d\n", WSAGetLastError());
		return false;
	}

	BOOL reuseAddr = TRUE;
	setsockopt(s_searchSock, SOL_SOCKET, SO_REUSEADDR, (const char *)&reuseAddr, sizeof(reuseAddr));

	struct sockaddr_in bindAddr;
	memset(&bindAddr, 0, sizeof(bindAddr));
	bindAddr.sin_family = AF_INET;
	bindAddr.sin_port = htons(WIN64_LAN_DISCOVERY_PORT);
	bindAddr.sin_addr.s_addr = INADDR_ANY;

	if (::bind(s_searchSock, (struct sockaddr *)&bindAddr, sizeof(bindAddr)) == SOCKET_ERROR)
	{
		app.DebugPrintf("Win64 LAN: Search bind failed: %d\n", WSAGetLastError());
		closesocket(s_searchSock);
		s_searchSock = INVALID_SOCKET;
		return false;
	}

	DWORD timeout = 500;
	setsockopt(s_searchSock, SOL_SOCKET, SO_RCVTIMEO, (const char *)&timeout, sizeof(timeout));

	s_scanning = true;
	s_searchThread = CreateThread(NULL, 0, SearchThreadProc, NULL, 0, NULL);

	app.DebugPrintf("Win64 LAN: Listening for LAN games on UDP port %d\n", WIN64_LAN_DISCOVERY_PORT);
	return true;
}

void WinsockNetLayer::StopSearch()
{
	s_scanning = false;

	if (s_searchSock != INVALID_SOCKET)
	{
		closesocket(s_searchSock);
		s_searchSock = INVALID_SOCKET;
	}

	if (s_searchThread != NULL)
	{
		WaitForSingleObject(s_searchThread, 2000);
		CloseHandle(s_searchThread);
		s_searchThread = NULL;
	}

	EnterCriticalSection(&s_searchMutex);
	s_foundSessions.clear();
	LeaveCriticalSection(&s_searchMutex);
}

std::vector<Win64LANSession> WinsockNetLayer::GetFoundSessions()
{
	std::vector<Win64LANSession> result;
	EnterCriticalSection(&s_searchMutex);
	result = s_foundSessions;
	LeaveCriticalSection(&s_searchMutex);
	return result;
}

DWORD WINAPI WinsockNetLayer::SearchThreadProc(LPVOID param)
{
	char buffer[1024];

	while (s_scanning)
	{
		struct sockaddr_in senderAddr;
		int senderLen = sizeof(senderAddr);

		int recvLen = recvfrom(s_searchSock, buffer, sizeof(buffer), 0,
			(struct sockaddr *)&senderAddr, &senderLen);

		if (recvLen == SOCKET_ERROR)
		{
			continue;
		}

		if (recvLen < (int)sizeof(Win64LANBroadcast))
			continue;

		Win64LANBroadcast *broadcast = (Win64LANBroadcast *)buffer;

		if (broadcast->magic != WIN64_LAN_BROADCAST_MAGIC)
			continue;

		char senderIP[64];
		inet_ntop(AF_INET, &senderAddr.sin_addr, senderIP, sizeof(senderIP));

		DWORD now = GetTickCount();

		EnterCriticalSection(&s_searchMutex);
		bool found = false;

		for (size_t i = 0; i < s_foundSessions.size(); i++)
		{
			if (strcmp(s_foundSessions[i].hostIP, senderIP) == 0 &&
				s_foundSessions[i].hostPort == (int)broadcast->gamePort)
			{
				s_foundSessions[i].netVersion = broadcast->netVersion;
				wcsncpy_s(s_foundSessions[i].hostName, 32, broadcast->hostName, _TRUNCATE);
				s_foundSessions[i].playerCount = broadcast->playerCount;
				s_foundSessions[i].maxPlayers = broadcast->maxPlayers;
				s_foundSessions[i].gameHostSettings = broadcast->gameHostSettings;
				s_foundSessions[i].texturePackParentId = broadcast->texturePackParentId;
				s_foundSessions[i].subTexturePackId = broadcast->subTexturePackId;
				s_foundSessions[i].isJoinable = (broadcast->isJoinable != 0);
				s_foundSessions[i].lastSeenTick = now;
				memcpy(s_foundSessions[i].playerNames, broadcast->playerNames, sizeof(broadcast->playerNames));
				found = true;
				break;
			}
		}

		if (!found)
		{
			Win64LANSession session;
			memset(&session, 0, sizeof(session));
			strncpy_s(session.hostIP, sizeof(session.hostIP), senderIP, _TRUNCATE);
			session.hostPort = (int)broadcast->gamePort;
			session.netVersion = broadcast->netVersion;
			wcsncpy_s(session.hostName, 32, broadcast->hostName, _TRUNCATE);
			session.playerCount = broadcast->playerCount;
			session.maxPlayers = broadcast->maxPlayers;
			session.gameHostSettings = broadcast->gameHostSettings;
			session.texturePackParentId = broadcast->texturePackParentId;
			session.subTexturePackId = broadcast->subTexturePackId;
			session.isJoinable = (broadcast->isJoinable != 0);
			session.lastSeenTick = now;
			memcpy(session.playerNames, broadcast->playerNames, sizeof(broadcast->playerNames));
			s_foundSessions.push_back(session);

			app.DebugPrintf("Win64 LAN: Discovered game \"%ls\" at %s:%d\n",
				session.hostName, session.hostIP, session.hostPort);
		}

		for (size_t i = s_foundSessions.size(); i > 0; i--)
		{
			if (now - s_foundSessions[i - 1].lastSeenTick > 5000)
			{
				app.DebugPrintf("Win64 LAN: Session \"%ls\" at %s timed out\n",
					s_foundSessions[i - 1].hostName, s_foundSessions[i - 1].hostIP);
				s_foundSessions.erase(s_foundSessions.begin() + (i - 1));
			}
		}

		LeaveCriticalSection(&s_searchMutex);
	}

	return 0;
}
