static void safe_release_resource(IUnknown * &ptr)
{
   if (ptr) {
      ptr->Release();
      ptr = NULL;
   }
}

static void clear_bound_resources(void)
{
   IDirect3DDevice9 *dev = global_gdraw->device;
   for (int i = 0; i < 3; ++i) {
      dev->SetTexture(i, NULL);
   }
   dev->SetStreamSource(0, NULL, 0, 0);
   dev->SetIndices(NULL);
}

static void release_graphics_resource(GDrawHandle *res)
{
   clear_bound_resources();
   if (res->state != GDRAW_HANDLE_STATE_user_owned) {
      if (!res->cache->is_vertex_buffer) {
         safe_release_resource(res->handle.texture.d3d_tex);
      } else {
         safe_release_resource(res->handle.vbuffer.vertex_buffer);
         safe_release_resource(res->handle.vbuffer.index_buffer);
      }
   }
}

static void RADLINK gdraw_UnlockAllHandles(GDrawStats * /*unused*/)
{
   gdraw_HandleCacheUnlockAll(global_gdraw->texture_pool);
   gdraw_HandleCacheUnlockAll(global_gdraw->vbuffer_pool);
}

