static rrbool RADLINK gdraw_CreateTextureBegin(void *owner, S32 w, S32 h, gdraw_texture_format fmt, U32 flags, GDraw_MakeTexture_ProcessingInfo *info, GDrawStats *stats)
{
   GDrawHandle *t = NULL;
   D3DFORMAT d3d_format;
   S32 bytes_per_pixel;

   if (fmt == GDRAW_TEXTURE_FORMAT_rgba32) {
      d3d_format = D3DFMT_A8R8G8B8;
      bytes_per_pixel = 4;
   } else {
      d3d_format = D3DFMT_A8;
      bytes_per_pixel = 1;
   }

   S32 estimated_size = w * h * bytes_per_pixel;
   if (flags & GDRAW_MAKETEXTURE_FLAGS_mipmap)
      estimated_size = estimated_size * 4 / 3;

   t = gdraw_res_alloc_begin(global_gdraw->texture_pool, estimated_size, stats);
   if (!t) 
      return false;

   HRESULT hr = global_gdraw->device->CreateTexture(w, h, (flags & GDRAW_MAKETEXTURE_FLAGS_mipmap) ? 0 : 1,
                                         0, d3d_format, D3DPOOL_MANAGED, &t->handle.texture.d3d_tex, NULL);
   if (FAILED(hr)) {
      gdraw_HandleCacheAllocateFail(t);
      IggyGDrawSendWarning(NULL, "GDraw CreateTexture() failed with error code 0x%08x", hr);
      return false;
   }

   t->handle.texture.width = w;
   t->handle.texture.height = h;
   gdraw_HandleCacheAllocateEnd(t, estimated_size, owner, (flags & GDRAW_MAKETEXTURE_FLAGS_never_flush) ? GDRAW_HANDLE_STATE_pinned : GDRAW_HANDLE_STATE_locked);

   stats->nonzero_flags |= GDRAW_STATS_alloc_tex;
   stats->alloc_tex += 1;
   stats->alloc_tex_bytes += estimated_size;

   info->texture_type = GDRAW_TEXTURE_TYPE_bgra;
   info->p0 = t;

   if (flags & GDRAW_MAKETEXTURE_FLAGS_mipmap) {
      rrbool ok;
      assert(info->temp_buffer != NULL);
      ok = gdraw_MipmapBegin(&global_gdraw->mipmap_context, w, h, t->handle.texture.d3d_tex->GetLevelCount(), bytes_per_pixel, info->temp_buffer, info->temp_buffer_bytes);
      assert(ok);
      info->p1 = &global_gdraw->mipmap_context;
      info->texture_data = global_gdraw->mipmap_context.pixels[0];
      info->num_rows = global_gdraw->mipmap_context.bheight;
      info->stride_in_bytes = global_gdraw->mipmap_context.pitch[0];
      info->i0 = 0;
      info->i1 = bytes_per_pixel;
   } else {
      D3DLOCKED_RECT locked;
      hr = t->handle.texture.d3d_tex->LockRect(0, &locked, NULL, 0);
      if (FAILED(hr)) {
         t->handle.texture.d3d_tex->Release();
         gdraw_HandleCacheAllocateFail(t);
         if (hr == E_OUTOFMEMORY) {
            IggyGDrawSendWarning(NULL, "GDraw out of texture memory allocating %dx%d (%dbpp) texture", w, h, 8*bytes_per_pixel);
            return false;
         } else {
            IggyGDrawSendWarning(NULL, "GDraw LockRect for texture allocation failed, D3D error 0x%08x\n", hr);
            return false;
         }
      }

      info->p1 = NULL;
      info->texture_data = (U8 *) locked.pBits;
      info->num_rows = h;
      info->stride_in_bytes = locked.Pitch;
   }
   return true;
}

static rrbool RADLINK gdraw_CreateTextureContinue(GDraw_MakeTexture_ProcessingInfo *info)
{
   GDrawHandle *t = (GDrawHandle *) info->p0;

   if (info->p1) {
      GDrawMipmapContext *ctx = (GDrawMipmapContext *) info->p1;
      U32 current_row = info->i0;
      U32 bpp = info->i1;
      U32 width = ctx->width;
      U32 height = ctx->height;
      U32 block_height = ctx->bheight;
      U32 level = 0;
      if (current_row >= ctx->height)
         return false;

      do {
         D3DLOCKED_RECT locked;
         HRESULT hr = t->handle.texture.d3d_tex->LockRect(level, &locked, NULL, 0);
         if (FAILED(hr))
            return false;

         for (U32 y=0; y < block_height; ++y)
            memcpy((U8 *) locked.pBits + ((current_row >> level) + y) * locked.Pitch, ctx->pixels[level] + y * ctx->pitch[level], width * bpp);

         t->handle.texture.d3d_tex->UnlockRect(level);

         width = RR_MAX(width >> 1, 1);
         height = RR_MAX(height >> 1, 1);
         block_height = RR_MAX(block_height >> 1, 1);
      } while (gdraw_MipmapAddLines(ctx, ++level));

      info->i0 += info->num_rows;
      info->texture_data = ctx->pixels[0];
      info->num_rows = ctx->bheight = RR_MIN(ctx->bheight, ctx->height - info->i0);
      return true;
   } else
      return false;
}

static GDrawTexture * RADLINK gdraw_CreateTextureEnd(GDraw_MakeTexture_ProcessingInfo *info, GDrawStats * /*stats*/)
{
   GDrawHandle *t = (GDrawHandle *) info->p0;
   if (info->p1)
      gdraw_CreateTextureContinue(info);
   else
      t->handle.texture.d3d_tex->UnlockRect(0);
   return (GDrawTexture *) t;
}

static rrbool RADLINK gdraw_UpdateTextureStart(GDrawTexture *t, void *unique_id, GDrawStats * /*stats*/)
{
