}

static void RADLINK gdraw_UpdateTextureRegion(GDrawTexture *t, void * /*unique_id*/, S32 x, S32 y, S32 stride, S32 w, S32 h, U8 *samples, gdraw_texture_format format)
{
   GDrawHandle *s = (GDrawHandle *) t;
   RECT dest_rect = { x, y, x+w, y+h };
   S32 i, bytes_per_line = (format == GDRAW_TEXTURE_FORMAT_font ? 1 : 4) * w;
   D3DLOCKED_RECT lr;
   HRESULT hr = s->handle.texture.d3d_tex->LockRect(0, &lr, &dest_rect, 0);
   if (FAILED(hr)) {
      IggyGDrawSendWarning(0, "GDraw LockRect() for texture update failed; D3D error 0x%08x", hr);
      return;
   }
   for (i=0; i < h; i++)
      memcpy((U8 *) lr.pBits + i * lr.Pitch, samples + i*stride, bytes_per_line);
   s->handle.texture.d3d_tex->UnlockRect(0);
}

static void RADLINK gdraw_UpdateTextureFinish(GDrawTexture *t, void * /*unique_id*/, GDrawStats * /*stats*/)
{
   gdraw_HandleCacheUnlock((GDrawHandle *) t);
}

static void RADLINK gdraw_DeleteTexture(GDrawTexture *tt, void *unique_id, GDrawStats *stats)
{
