static void RADLINK gdraw_SetAntialiasPattern(S32 width, U8 *rgba)
{
   HRESULT hr;
   D3DLOCKED_RECT lr;
   S32 i;
   U8 *dst;
   safe_release_resource(global_gdraw->antialias_texture);
   hr = global_gdraw->device->CreateTexture(width, 1, 1, 0, D3DFMT_A8R8G8B8, D3DPOOL_MANAGED, &global_gdraw->antialias_texture, NULL);
   if (FAILED(hr)) {
      IggyGDrawSendWarning(0, "GDraw D3D error in CreateTexture 0x%08x", hr);
      return;
   }
   hr = global_gdraw->antialias_texture->LockRect(0, &lr, NULL, 0);
   if (!FAILED(hr)) {
      dst = (U8 *) lr.pBits;
      for (i=0; i < width; i++) {
         dst[i*4+0] = rgba[i*4+2];
         dst[i*4+1] = rgba[i*4+1];
         dst[i*4+2] = rgba[i*4+0];
         dst[i*4+3] = rgba[i*4+3];
      }
      global_gdraw->antialias_texture->UnlockRect(0);
   } else
      IggyGDrawSendWarning(0, "GDraw D3D error in LockRect for texture creation: 0x%08x", hr);
}

static rrbool RADLINK gdraw_CreateVertexBufferStart(void *unique_id, gdraw_vformat /*fmt*/, S32 vbuf_size, S32 ibuf_size, GDraw_MakeVertexBuffer_ProcessingInfo *info, GDrawStats *stats)
{
   char *failure_point;
   GDrawHandle *vb = gdraw_res_alloc_begin(global_gdraw->vbuffer_pool, vbuf_size + ibuf_size, stats);
   if (!vb)
      return false;
   vb->handle.vbuffer.vertex_buffer = NULL;
   vb->handle.vbuffer.index_buffer = NULL;
   HRESULT hr;
   hr = global_gdraw->device->CreateVertexBuffer(vbuf_size, D3DUSAGE_WRITEONLY, 0, D3DPOOL_MANAGED, &vb->handle.vbuffer.vertex_buffer, NULL);
   failure_point = "CreateVertexBuffer";
   if (!FAILED(hr)) {
      hr = global_gdraw->device->CreateIndexBuffer(ibuf_size, D3DUSAGE_WRITEONLY, D3DFMT_INDEX16, D3DPOOL_MANAGED, &vb->handle.vbuffer.index_buffer, NULL);
      failure_point = "CreateIndexBuffer";
   }
   if (!FAILED(hr)) {
      hr = vb->handle.vbuffer.vertex_buffer->Lock(0, vbuf_size, (void **) &info->vertex_data, 0);
      failure_point = "Lock";
   }
   if (!FAILED(hr))
      hr = vb->handle.vbuffer.index_buffer->Lock(0, ibuf_size, (void **) &info->index_data, 0);
   if (FAILED(hr)) {
      if (vb->handle.vbuffer.vertex_buffer)
         vb->handle.vbuffer.vertex_buffer->Unlock();
      safe_release_resource(vb->handle.vbuffer.vertex_buffer);
      safe_release_resource(vb->handle.vbuffer.index_buffer);
      gdraw_HandleCacheAllocateFail(vb);
      report_d3d_error(hr, failure_point, " creating vertex buffer");
      return false;
   }
   info->vertex_data_length = vbuf_size;
   info->index_data_length = ibuf_size;
   info->p0 = vb;
   gdraw_HandleCacheAllocateEnd(vb, vbuf_size + ibuf_size, unique_id, GDRAW_HANDLE_STATE_locked);
   return true;
}

static rrbool RADLINK gdraw_CreateVertexBufferContinue(GDraw_MakeVertexBuffer_ProcessingInfo * /*info*/)
{
   assert(0);
   return false;
}

static GDrawVertexBuffer * RADLINK gdraw_CreateVertexBufferEnd(GDraw_MakeVertexBuffer_ProcessingInfo *info, GDrawStats * /*stats*/)
{
   GDrawHandle *vb = (GDrawHandle *) info->p0;
   vb->handle.vbuffer.vertex_buffer->Unlock();
   vb->handle.vbuffer.index_buffer->Unlock();
   return (GDrawVertexBuffer *) vb;
}

static rrbool RADLINK gdraw_AttemptLockVertexBuffer(GDrawVertexBuffer *vb, void *unique_id, GDrawStats * /*stats*/)
{
   return gdraw_HandleCacheLock((GDrawHandle *) vb, unique_id);
}

static void RADLINK gdraw_DeleteVertexBuffer(GDrawVertexBuffer *vb, void *unique_id, GDrawStats *stats)
{
   GDrawHandle *h = (GDrawHandle *) vb;
   assert(h != NULL);
   if (h->owner == unique_id)
      gdraw_res_free(h, stats);
}

static void RADLINK gdraw_GetVertexBufferInfo(GDrawVertexBuffer *vbuf, GDraw_VertexBuffer_Description *desc)
{
   GDrawHandle *p = (GDrawHandle *) vbuf;
   desc->size_in_bytes = p->bytes;
}

static GDrawHandle *get_color_rendertarget(GDrawStats *stats)
{
   GDrawHandle *t = gdraw_HandleCacheGetLRU(&global_gdraw->render_target_cache);
   if (t) {
      gdraw_HandleCacheLock(t, (void *) 1);
      return t;
   }

   S32 size = global_gdraw->rt_width * global_gdraw->rt_height * 4;
   if (global_gdraw->render_target_cache.bytes_free < size) {
      IggyGDrawSendWarning(NULL, "GDraw rendertarget allocation failed: hit size limit of %d bytes", global_gdraw->render_target_cache.total_bytes);
      return NULL;
   }

   t = gdraw_HandleCacheAllocateBegin(&global_gdraw->render_target_cache);
   if (!t) {
      IggyGDrawSendWarning(NULL, "GDraw rendertarget allocation failed: hit handle limit");
      return t;
   }

   HRESULT hr = global_gdraw->device->CreateTexture(global_gdraw->rt_width, global_gdraw->rt_height, 1, D3DUSAGE_RENDERTARGET,
      D3DFMT_A8R8G8B8, D3DPOOL_DEFAULT, &t->handle.texture.d3d_tex, NULL);
   if (FAILED(hr)) {
      report_d3d_error(hr, "CreateTexture", " creating rendertarget");
      gdraw_HandleCacheAllocateFail(t);
      return NULL;
   }

   gdraw_HandleCacheAllocateEnd(t, size, (void *) 1, GDRAW_HANDLE_STATE_locked);
   stats->nonzero_flags |= GDRAW_STATS_alloc_tex;
   stats->alloc_tex += 1;
   stats->alloc_tex_bytes += size;
   return t;
}

static IDirect3DSurface9 *get_rendertarget_depthbuffer(GDrawStats *stats)
{
   if (!global_gdraw->rt_depth_surface) {
      HRESULT hr = global_gdraw->device->CreateDepthStencilSurface(global_gdraw->rt_width, global_gdraw->rt_height, D3DFMT_D24S8, D3DMULTISAMPLE_NONE, 0, TRUE, &global_gdraw->rt_depth_surface, NULL);
      if (FAILED(hr))
         IggyGDrawSendWarning(NULL, "GDraw D3D error in CreateDepthStencilSurface: 0x%08x", hr);
      else {
         stats->nonzero_flags |= GDRAW_STATS_alloc_tex;
         stats->alloc_tex += 1;
         stats->alloc_tex_bytes += global_gdraw->rt_width * global_gdraw->rt_height * 4;
      }
   }
   return global_gdraw->rt_depth_surface;
}

static void flush_rendertargets(GDrawStats *stats)
{
   gdraw_res_flush(&global_gdraw->render_target_cache, stats);
   safe_release_resource(global_gdraw->rt_depth_surface);
}

