static void set_d3d_texture(U32 sampler, IDirect3DTexture9 *tex, U32 wrap, U32 nearest)
{
   static const int addrmodes[4] = {
      D3DTADDRESS_CLAMP,
      D3DTADDRESS_WRAP,
      D3DTADDRESS_MIRROR,
      D3DTADDRESS_CLAMP,
   };
   static const int filtermodes[2] = {
      D3DTEXF_LINEAR,
      D3DTEXF_POINT,
   };
   assert(wrap < sizeof(addrmodes) / sizeof(addrmodes[0]));
   assert(nearest < sizeof(filtermodes) / sizeof(filtermodes[0]));
   IDirect3DDevice9 *d3d = global_gdraw->device;
   d3d->SetTexture(sampler, tex);
   d3d->SetSamplerState(sampler, D3DSAMP_MAGFILTER, filtermodes[nearest]);
   d3d->SetSamplerState(sampler, D3DSAMP_ADDRESSU, addrmodes[wrap]);
   d3d->SetSamplerState(sampler, D3DSAMP_ADDRESSV, addrmodes[wrap]);
}

static void set_viewport_direct(S32 x, S32 y, S32 w, S32 h)
{
   D3DVIEWPORT9 vp = { x, y, w, h, 0.0f, 1.0f };
   global_gdraw->device->SetViewport(&vp);
}

static void set_projection_base_values(void)
{
   F32 m[3][4] = { 0 };
   m[0][0] = global_gdraw->projection_params[0];
   m[1][1] = global_gdraw->projection_params[1];
   m[2][0] = global_gdraw->projection_params[2];
   m[2][1] = global_gdraw->projection_params[3];
   m[2][2] = 1.0;
   m[2][3] = 1.0;
   global_gdraw->device->SetVertexShaderConstantF(VVAR_x3d, m[0], 3);
}

static void set_projection_direct(S32 x0, S32 x1, S32 y0, S32 y1)
{
   global_gdraw->projection_params[0] = 2.0f / (x1-x0);
   global_gdraw->projection_params[1] = 2.0f / (y1-y0);
   global_gdraw->projection_params[2] = (x1+x0)/(F32)(x0-x1) - 0.5f * global_gdraw->projection_params[0];
   global_gdraw->projection_params[3] = (y1+y0)/(F32)(y0-y1) - 0.5f * global_gdraw->projection_params[1];
   set_projection_base_values();
}

static void set_viewport(void)
{
   if (global_gdraw->currently_in_blur_pass) {
      set_viewport_direct(0, 0, global_gdraw->padded_tile_w, global_gdraw->padded_tile_h);
      return;
   }
   if (global_gdraw->current_render_state == global_gdraw->render_stack)
      set_viewport_direct(global_gdraw->viewport_x, global_gdraw->viewport_y, global_gdraw->tile_w, global_gdraw->tile_h);
   else if (global_gdraw->current_render_state->is_cached)
      set_viewport_direct(0, 0, global_gdraw->current_render_state->render_width, global_gdraw->current_render_state->render_height);
   else
      set_viewport_direct(0, 0, global_gdraw->padded_tile_w, global_gdraw->padded_tile_h);
}

static void set_projection(void)
{
   if (global_gdraw->currently_in_blur_pass) return;
   if (global_gdraw->current_render_state == global_gdraw->render_stack)
      set_projection_direct(global_gdraw->tile_origin_x, global_gdraw->tile_origin_x+global_gdraw->tile_w, global_gdraw->tile_origin_y+global_gdraw->tile_h, global_gdraw->tile_origin_y);
   else if (global_gdraw->current_render_state->is_cached)
      set_projection_direct(global_gdraw->current_render_state->origin_x, global_gdraw->current_render_state->origin_x+global_gdraw->current_render_state->render_width, global_gdraw->current_render_state->origin_y, global_gdraw->current_render_state->origin_y+global_gdraw->current_render_state->render_height);
   else
      set_projection_direct(global_gdraw->padded_tile_origin_x, global_gdraw->padded_tile_origin_x+global_gdraw->padded_tile_w, global_gdraw->padded_tile_origin_y+global_gdraw->padded_tile_h, global_gdraw->padded_tile_origin_y);
}

static void set_common_renderstate()
{
   IDirect3DDevice9 *d3d = global_gdraw->device;
   S32 i;
   d3d->SetRenderState(D3DRS_CULLMODE, D3DCULL_NONE);
   d3d->SetRenderState(D3DRS_STENCILFAIL, D3DSTENCILOP_KEEP);
   d3d->SetRenderState(D3DRS_STENCILZFAIL, D3DSTENCILOP_KEEP);
   d3d->SetRenderState(D3DRS_STENCILPASS, D3DSTENCILOP_REPLACE);
   d3d->SetRenderState(D3DRS_STENCILFUNC, D3DCMP_EQUAL);
   d3d->SetRenderState(D3DRS_STENCILREF,  255);
   d3d->SetRenderState(D3DRS_ALPHATESTENABLE, FALSE);
   d3d->SetRenderState(D3DRS_SLOPESCALEDEPTHBIAS, 0 ); 
   d3d->SetRenderState(D3DRS_DEPTHBIAS, 0 );
   d3d->SetRenderState(D3DRS_BLENDOP, D3DBLENDOP_ADD);
   d3d->SetRenderState(D3DRS_SEPARATEALPHABLENDENABLE, FALSE);
   for (i=0; i < 3; i++) {
      d3d->SetTextureStageState(i, D3DTSS_TEXCOORDINDEX, i);
      d3d->SetTextureStageState(i, D3DTSS_TEXTURETRANSFORMFLAGS, D3DTTFF_DISABLE);
      d3d->SetSamplerState(i, D3DSAMP_MIPFILTER, D3DTEXF_LINEAR);
      d3d->SetSamplerState(i, D3DSAMP_MINFILTER, D3DTEXF_LINEAR);
      d3d->SetSamplerState(i, D3DSAMP_MIPMAPLODBIAS, 0);
      d3d->SetSamplerState(i, D3DSAMP_MAXMIPLEVEL, 0);
   }
   d3d->SetTextureStageState(AA_TEXTURE_SAMPLER_INDEX, D3DTSS_TEXCOORDINDEX, AA_TEXTURE_SAMPLER_INDEX);
   d3d->SetTexture(AA_TEXTURE_SAMPLER_INDEX, global_gdraw->antialias_texture);
   d3d->SetSamplerState(AA_TEXTURE_SAMPLER_INDEX, D3DSAMP_ADDRESSU, D3DTADDRESS_CLAMP);
   d3d->SetSamplerState(AA_TEXTURE_SAMPLER_INDEX, D3DSAMP_ADDRESSV, D3DTADDRESS_CLAMP);
   d3d->SetSamplerState(AA_TEXTURE_SAMPLER_INDEX, D3DSAMP_MINFILTER, D3DTEXF_LINEAR);
   d3d->SetSamplerState(AA_TEXTURE_SAMPLER_INDEX, D3DSAMP_MAGFILTER, D3DTEXF_LINEAR);
   d3d->SetSamplerState(AA_TEXTURE_SAMPLER_INDEX, D3DSAMP_MIPMAPLODBIAS, 0);
   d3d->SetSamplerState(AA_TEXTURE_SAMPLER_INDEX, D3DSAMP_MAXMIPLEVEL, 0);

   global_gdraw->cached_scissor_state = ~0u;
   global_gdraw->cached_blend_mode = -1;
   global_gdraw->cached_stencil_config = ~0u;
   global_gdraw->cached_z_config = ~0u;

   VertexConstants vvars = { 0 };
   d3d->SetVertexShaderConstantF(0, vvars.world[0], VVAR_count);
}

