void FDisplayClusterDeviceSideBySideBase::AdjustViewRect(enum EStereoscopicPass StereoPassType, int32& X, int32& Y, uint32& SizeX, uint32& SizeY) const
{
	const int ViewIndexLocal = DecodeViewportIndex(StereoPassType);
	const EStereoscopicPass PassType = DecodeStereoscopicPass(StereoPassType);
	const uint32 ViewId = DecodeViewIndex(StereoPassType);

	// Retrieve viewport information for current pass
	FDisplayClusterRenderViewport& CurrentViewport = RenderViewports[ViewIndexLocal];
	// Set up the engine-facing viewport rectangle
	const FIntRect& ViewportBounds = CurrentViewport.GetRect();

	if (PassType == EStereoscopicPass::eSSP_LEFT_EYE)
	{
		X = ViewportBounds.Min.X / 2;
	}
	else if (PassType == EStereoscopicPass::eSSP_RIGHT_EYE)
	{
		X = SizeX / 2 + ViewportBounds.Min.X / 2;
	}

	Y = ViewportBounds.Min.Y;
	SizeX = ViewportBounds.Width() / 2;
	SizeY = ViewportBounds.Height();

	// Update rendering context with adjusted rectangle
	FDisplayClusterRenderViewContext& ViewCtx = CurrentViewport.GetContext(ViewId);
	ViewCtx.RenderTargetRect = FIntRect(X, Y, X + SizeX, Y + SizeY);

	const FIntRect& AdjustedRect = ViewCtx.RenderTargetRect;
	UE_LOG(LogDisplayClusterRender, Verbose, TEXT("Adjusted view rect: ViewportIdx=%d, ViewIndex=%d, [%d,%d - %d,%d]"), 
		ViewIndexLocal, ViewId, AdjustedRect.Min.X, AdjustedRect.Min.Y, AdjustedRect.Max.X, AdjustedRect.Max.Y);
}

