namespace routing
{
// static
std::vector<Restriction::Type> const RestrictionHeader::kAllTypes = {
    Restriction::Type::No, Restriction::Type::Only, Restriction::Type::NoUTurn, Restriction::Type::OnlyUTurn};

bool Restriction::operator==(Restriction const & other) const
{
  return m_featureIds == other.m_featureIds && m_type == other.m_type;
}

bool Restriction::operator<(Restriction const & other) const
{
  if (m_type != other.m_type)
    return m_type < other.m_type;
  return m_featureIds < other.m_featureIds;
}

uint32_t RestrictionHeader::GetCount(Restriction::Type type) const
{
  return m_restrictionCount.at(type);
}

void RestrictionHeader::SetCount(Restriction::Type type, uint32_t count)
{
  m_restrictionCount[type] = count;
}

void RestrictionHeader::Clear()
{
  m_version = kLatestVersion;
  m_reserved = 0;
  for (auto const t : kAllTypes)
    m_restrictionCount.emplace(t, 0);
}

std::string DebugPrint(Restriction::Type const & type)
{
  switch (type)
  {
  case Restriction::Type::No: return kNegative;
  case Restriction::Type::Only: return kPositive;
  case Restriction::Type::NoUTurn: return kNoReverse;
  case Restriction::Type::OnlyUTurn: return kOnlyReverse;
  }
  return "Unknown";
}

std::string DebugPrint(Restriction const & restriction)
{
  std::ostringstream out;
  out << "[" << DebugPrint(restriction.m_type) << "]: {";
  for (size_t idx = 0; idx < restriction.m_featureIds.size(); ++idx)
  {
    out << restriction.m_featureIds[idx];
    if (idx + 1 != restriction.m_featureIds.size())
      out << ", ";
  }
  out << "}";
  return out.str();
}

std::string DebugPrint(RestrictionHeader const & header)
{
  std::string result = "RestrictionHeader: { ";
  size_t const total = RestrictionHeader::kAllTypes.size();
  for (size_t i = 0; i < total; ++i)
  {
    auto const t = RestrictionHeader::kAllTypes[i];
    result += DebugPrint(t) + " => " + std::to_string(header.GetCount(t));
    if (i + 1 != total)
      result += ", ";
  }
  result += " }";
  return result;
}

bool IsUTurnType(Restriction::Type type)
{
  return type == Restriction::Type::NoUTurn || type == Restriction::Type::OnlyUTurn;
}
