void Input::getInput() {
    inputButtons.clear();
    mousePointer.isPressed = false;

#ifdef PLATFORM_HAS_KEYBOARD
    int totalKeys;
    Uint8 *keyboardState = SDL_GetKeyState(&totalKeys);
    for (int idx = 0; idx < SDLK_LAST; ++idx) {
        if (keyboardState[idx]) {
            const char *keyLabel = SDL_GetKeyName(static_cast<SDLKey>(idx));
            if (keyLabel && keyLabel[0] != '\0') {
                std::string keyName(keyLabel);
                std::transform(keyName.begin(), keyName.end(), keyName.begin(), ::tolower);
                if (keyName == "up") keyName = "up arrow";
                else if (keyName == "down") keyName = "down arrow";
                else if (keyName == "left") keyName = "left arrow";
                else if (keyName == "right") keyName = "right arrow";
                else if (keyName == "return") keyName = "enter";
                inputButtons.push_back(keyName);
            }
        }
    }
#endif

#ifdef PLATFORM_HAS_CONTROLLER
    if (gamepad) {
        Uint8 hatState = SDL_JoystickGetHat(gamepad, 0);
        if (hatState & SDL_HAT_UP) {
            Input::buttonPress("dpadUp");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(gamepad, 4)) mousePointer.y += 3;
#endif
        }
        if (hatState & SDL_HAT_DOWN) {
            Input::buttonPress("dpadDown");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(gamepad, 4)) mousePointer.y -= 3;
#endif
        }
        if (hatState & SDL_HAT_LEFT) {
            Input::buttonPress("dpadLeft");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(gamepad, 4)) mousePointer.x -= 3;
#endif
        }
        if (hatState & SDL_HAT_RIGHT) {
            Input::buttonPress("dpadRight");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(gamepad, 4)) mousePointer.x += 3;
#endif
        }

        if (SDL_JoystickGetButton(gamepad, 0)) Input::buttonPress("A");
        if (SDL_JoystickGetButton(gamepad, 1)) Input::buttonPress("B");
        if (SDL_JoystickGetButton(gamepad, 2)) Input::buttonPress("X");
        if (SDL_JoystickGetButton(gamepad, 3)) Input::buttonPress("Y");
        if (SDL_JoystickGetButton(gamepad, 4)) {
            Input::buttonPress("shoulderL");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            mousePointer.isMoving = true;
#endif
        } else mousePointer.isMoving = false;

        if (SDL_JoystickGetButton(gamepad, 5)) {
            Input::buttonPress("shoulderR");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(gamepad, 4)) mousePointer.isPressed = true;
#endif
        }

        if (SDL_JoystickGetButton(gamepad, 7)) Input::buttonPress("start");
        if (SDL_JoystickGetButton(gamepad, 6)) Input::buttonPress("back");
        if (SDL_JoystickGetButton(gamepad, 8)) Input::buttonPress("LeftStickPressed");
        if (SDL_JoystickGetButton(gamepad, 9)) Input::buttonPress("RightStickPressed");

        float axisLeftX = SDL_JoystickGetAxis(gamepad, 0);
        float axisLeftY = SDL_JoystickGetAxis(gamepad, 1);
        if (axisLeftX > CONTROLLER_DEADZONE_X) Input::buttonPress("LeftStickRight");
        if (axisLeftX < -CONTROLLER_DEADZONE_X) Input::buttonPress("LeftStickLeft");
        if (axisLeftY > CONTROLLER_DEADZONE_Y) Input::buttonPress("LeftStickDown");
        if (axisLeftY < -CONTROLLER_DEADZONE_Y) Input::buttonPress("LeftStickUp");

        float axisRightX = SDL_JoystickGetAxis(gamepad, 2);
        float axisRightY = SDL_JoystickGetAxis(gamepad, 3);
        if (axisRightX > CONTROLLER_DEADZONE_X) Input::buttonPress("RightStickRight");
        if (axisRightX < -CONTROLLER_DEADZONE_X) Input::buttonPress("RightStickLeft");
        if (axisRightY > CONTROLLER_DEADZONE_Y) Input::buttonPress("RightStickDown");
        if (axisRightY < -CONTROLLER_DEADZONE_Y) Input::buttonPress("RightStickUp");

        if (SDL_JoystickGetAxis(gamepad, 4) > CONTROLLER_DEADZONE_TRIGGER) Input::buttonPress("LT");
        if (SDL_JoystickGetAxis(gamepad, 5) > CONTROLLER_DEADZONE_TRIGGER) Input::buttonPress("RT");
    }
#endif

    if (!inputButtons.empty()) inputButtons.push_back("any");
    BlockExecutor::executeKeyHats();

#ifdef PLATFORM_HAS_MOUSE
    std::vector<int> rawCoords = getTouchPosition();
    auto scratchCoords = Scratch::screenToScratchCoords(rawCoords[0], rawCoords[1], Render::getWidth(), Render::getHeight());
    mousePointer.x = scratchCoords.first;
    mousePointer.y = scratchCoords.second;
    Uint32 mouseButtons = SDL_GetMouseState(NULL, NULL);
    if (mouseButtons & (SDL_BUTTON(SDL_BUTTON_LEFT) | SDL_BUTTON(SDL_BUTTON_RIGHT))) {
        mousePointer.isPressed = true;
    }
#endif

    BlockExecutor::doSpriteClicking();
}

std::string Input::openSoftwareKeyboard(const char *promptText) {
    std::unique_ptr<TextObject> displayText = createTextObject(std::string(promptText), 0, 0);
    displayText->setCenterAligned(true);
    displayText->setColor(Math::color(0, 0, 0, 170));
    if (displayText->getSize()[0] > Render::getWidth() * 0.85) {
        float scaleFactor = (float)Render::getWidth() / (displayText->getSize()[0] * 1.15);
        displayText->setScale(scaleFactor);
    }

    std::unique_ptr<TextObject> instructionText = createTextObject("ENTER TEXT:", 0, 0);
    instructionText->setCenterAligned(true);
    instructionText->setColor(Math::color(0, 0, 0, 255));

    std::string userText = "";
    bool isInputActive = true;
    SDL_Event event;

    while (isInputActive) {
        while (SDL_PollEvent(&event)) {
            switch (event.type) {
            case SDL_KEYDOWN:
                if (event.key.keysym.unicode != 0 &&
                    (event.key.keysym.unicode & 0xFF80) == 0 &&
                    event.key.keysym.unicode >= ' ') {
                    userText += event.key.keysym.unicode;
                    displayText->setText(userText);
                    displayText->setColor(Math::color(0, 0, 0, 255));
                }

                switch (event.key.keysym.sym) {
                case SDLK_RETURN:
                case SDLK_KP_ENTER:
                    isInputActive = false;
                    break;
                case SDLK_BACKSPACE:
                    if (!userText.empty()) {
                        userText.pop_back();
                    }
                    if (userText.empty()) {
                        displayText->setText(std::string(promptText));
                        displayText->setColor(Math::color(0, 0, 0, 170));
                    } else {
                        displayText->setText(userText);
                    }
                    break;
                case SDLK_ESCAPE:
                    isInputActive = false;
                    break;
                }
                break;

            case SDL_QUIT:
                OS::toExit = true;
                isInputActive = false;
                break;
            }
        }

        displayText->setScale(1.0f);
        if (displayText->getSize()[0] > Render::getWidth() * 0.95) {
            float scaleFactor = (float)Render::getWidth() / (displayText->getSize()[0] * 1.05);
            displayText->setScale(scaleFactor);
        } else {
            displayText->setScale(1.0f);
        }

        Render::beginFrame(0, 117, 77, 117);
        displayText->render(Render::getWidth() / 2, Render::getHeight() * 0.25);
        instructionText->render(Render::getWidth() / 2, Render::getHeight() * 0.15);
        Render::endFrame(false);
    }

    return userText;
}

