    m_cached_shader = AssetFactory::get_instance().get_instance().create_synthetic_asset<Shader>(
        "Default Shader",
        UUID::from_hash("ENGINE_DEFAULT_SHADER"));

    auto shader = AssetManager::get_instance().get_asset<Shader>(*m_cached_shader);
    shader->set_source(make_scope<ShaderSourceFile>(
        "./default_resources/default_shader.glsl"));
