template <typename T>
class SharedDataBuffer {
 public:
  void Update(const T &newData) {
    std::unique_lock<std::shared_mutex> mtxLock(mutex);
    buffer = std::make_shared<T>(newData);
  }
  std::shared_ptr<const T> Fetch() {
    std::shared_lock<std::shared_mutex> mtxLock(mutex);
    return buffer ? buffer : nullptr;
  }
  void Reset() {
    std::unique_lock<std::shared_mutex> mtxLock(mutex);
    buffer = nullptr;
  }
 private:
  std::shared_ptr<T> buffer;
  std::shared_mutex mutex;
};

