inline uint32_t CalculateCrc32(uint32_t *dataPtr, uint32_t dataLength) {
  uint32_t bitMask = 0;
  uint32_t currentData = 0;
  uint32_t crcRegister = 0xFFFFFFFF;
  const uint32_t generatorPolynomial = 0x04c11db7;
  for (uint32_t i = 0; i < dataLength; i++) {
    bitMask = 1 << 31;
    currentData = dataPtr[i];
    for (uint32_t bitIndex = 0; bitIndex < 32; bitIndex++) {
      if (crcRegister & 0x80000000) {
        crcRegister <<= 1;
        crcRegister ^= generatorPolynomial;
      } else {
        crcRegister <<= 1;
      }
      if (currentData & bitMask) crcRegister ^= generatorPolynomial;
      bitMask >>= 1;
    }
  }
  return crcRegister;
}

