  SharedDataBuffer<JointFeedback> joint_feedback_buffer_;
  SharedDataBuffer<JointCommand> joint_command_buffer_;
  SharedDataBuffer<ImuData> imu_feedback_buffer_;
  ChannelPublisherPtr<LowCmd_> command_publisher_;
  ChannelSubscriberPtr<LowState_> state_subscriber_;
  ChannelSubscriberPtr<IMUState_> torso_imu_subscriber_;
  ThreadPtr command_sender_thread_, controller_thread_;
  std::shared_ptr<unitree::robot::b2::MotionSwitcherClient> motion_controller_client_;

 public:
  G1RobotController(std::string networkInterface)
      : simulation_time_(0.0),
        control_period_(0.002),
        motion_duration_(3.0),
        update_counter_(0),
        pr_mode_setting_(ControlMode::PR),
        robot_mode_state_(0) {
    ChannelFactory::Instance()->Init(0, networkInterface);

    // Attempt to release any active motion control services
    motion_controller_client_ = std::make_shared<unitree::robot::b2::MotionSwitcherClient>();
    motion_controller_client_->SetTimeout(5.0f);
    motion_controller_client_->Init();

    std::string mode_form, mode_name;
    while (motion_controller_client_->CheckMode(mode_form, mode_name), !mode_name.empty()) {
      if (motion_controller_client_->ReleaseMode())
        std::cout << "Failed to switch to Release Mode\n";
      sleep(5);
    }

    // Initialize publisher and subscriber
    command_publisher_.reset(new ChannelPublisher<LowCmd_>(CMD_CHANNEL_NAME));
    command_publisher_->InitChannel();

    state_subscriber_.reset(new ChannelSubscriber<LowState_>(STATE_CHANNEL_NAME));
    state_subscriber_->InitChannel(std::bind(&G1RobotController::ProcessLowState, this, std::placeholders::_1), 1);

    torso_imu_subscriber_.reset(new ChannelSubscriber<IMUState_>(IMU_SECONDARY_TOPIC));
    torso_imu_subscriber_->InitChannel(std::bind(&G1RobotController::ProcessTorsoImu, this, std::placeholders::_1), 1);

    // Create threads
    command_sender_thread_ = CreateRecurrentThreadEx("command_sender", UT_CPU_ID_NONE, 2000, &G1RobotController::SendCommand, this);
    controller_thread_ = CreateRecurrentThreadEx("controller_loop", UT_CPU_ID_NONE, 2000, &G1RobotController::RunController, this);
  }

  void ProcessTorsoImu(const void *message) {
    IMUState_ imu_message = *(const IMUState_ *)message;
    auto &rpy_angles = imu_message.rpy();
    if (update_counter_ % 500 == 0)
      printf("IMU.torso.rpy: %.2f %.2f %.2f\n", rpy_angles[0], rpy_angles[1], rpy_angles[2]);
  }

  void ProcessLowState(const void *message) {
    LowState_ low_state_msg = *(const LowState_ *)message;
    if (low_state_msg.crc() != CalculateCrc32((uint32_t *)&low_state_msg, (sizeof(LowState_) >> 2) - 1)) {
      std::cout << "[ERROR] CRC Error" << std::endl;
      return;
    }

    // Extract motor state
    JointFeedback joint_data;
    for (int idx = 0; idx < G1_JOINT_COUNT; ++idx) {
      joint_data.position.at(idx) = low_state_msg.motor_state()[idx].q();
      joint_data.velocity.at(idx) = low_state_msg.motor_state()[idx].dq();
      if (low_state_msg.motor_state()[idx].motorstate() && idx <= RightAnkleRoll)
        std::cout << "[ERROR] motor " << idx << " with code " << low_state_msg.motor_state()[idx].motorstate() << "\n";
    }
    joint_feedback_buffer_.Update(joint_data);

    // Extract IMU state
    ImuData imu_data;
    imu_data.angular_velocity = low_state_msg.imu_state().gyroscope();
    imu_data.orientation = low_state_msg.imu_state().rpy();
    imu_feedback_buffer_.Update(imu_data);

    // Update gamepad
    memcpy(rx_data_.buff, &low_state_msg.wireless_remote()[0], 40);
    remote_controller_.update(rx_data_.RF_RX);

    // Update mode machine
    if (robot_mode_state_ != low_state_msg.mode_machine()) {
      if (robot_mode_state_ == 0) std::cout << "G1 type: " << unsigned(low_state_msg.mode_machine()) << std::endl;
      robot_mode_state_ = low_state_msg.mode_machine();
    }

    // Report robot status every second
    if (++update_counter_ % 500 == 0) {
      update_counter_ = 0;
      // IMU
      auto &rpy = low_state_msg.imu_state().rpy();
      printf("IMU.pelvis.rpy: %.2f %.2f %.2f\n", rpy[0], rpy[1], rpy[2]);
      // RC
      printf("gamepad_.A.pressed: %d\n", static_cast<int>(remote_controller_.A.pressed));
      printf("gamepad_.B.pressed: %d\n", static_cast<int>(remote_controller_.B.pressed));
      printf("gamepad_.X.pressed: %d\n", static_cast<int>(remote_controller_.X.pressed));
      printf("gamepad_.Y.pressed: %d\n", static_cast<int>(remote_controller_.Y.pressed));
      // Motor
      auto &ms = low_state_msg.motor_state();
      printf("All %d Motors:", G1_JOINT_COUNT);
      printf("\nmode: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%u,", ms[i].mode());
      printf("\npos: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%.2f,", ms[i].q());
      printf("\nvel: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%.2f,", ms[i].dq());
      printf("\ntau_est: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%.2f,", ms[i].tau_est());
      printf("\ntemperature: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%d,%d;", ms[i].temperature()[0], ms[i].temperature()[1]);
      printf("\nvol: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%.2f,", ms[i].vol());
      printf("\nsensor: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%u,%u;", ms[i].sensor()[0], ms[i].sensor()[1]);
      printf("\nmotorstate: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%u,", ms[i].motorstate());
      printf("\nreserve: ");
      for (int i = 0; i < G1_JOINT_COUNT; ++i) printf("%u,%u,%u,%u;", ms[i].reserve()[0], ms[i].reserve()[1], ms[i].reserve()[2], ms[i].reserve()[3]);
      printf("\n");
    }
  }

  void SendCommand() {
    LowCmd_ dds_low_command;
    dds_low_command.mode_pr() = static_cast<uint8_t>(pr_mode_setting_);
    dds_low_command.mode_machine() = robot_mode_state_;

    const std::shared_ptr<const JointCommand> cmd = joint_command_buffer_.Fetch();
    if (cmd) {
      for (size_t i = 0; i < G1_JOINT_COUNT; i++) {
        dds_low_command.motor_cmd().at(i).mode() = 1;  // 1:Enable, 0:Disable
        dds_low_command.motor_cmd().at(i).tau() = cmd->feedforward_torque.at(i);
        dds_low_command.motor_cmd().at(i).q() = cmd->position_cmd.at(i);
        dds_low_command.motor_cmd().at(i).dq() = cmd->velocity_cmd.at(i);
        dds_low_command.motor_cmd().at(i).kp() = cmd->kp_gain.at(i);
        dds_low_command.motor_cmd().at(i).kd() = cmd->kd_gain.at(i);
      }
      dds_low_command.crc() = CalculateCrc32((uint32_t *)&dds_low_command, (sizeof(dds_low_command) >> 2) - 1);
      command_publisher_->Write(dds_low_command);
    }
  }

  void RunController() {
    JointCommand output_command;
    const std::shared_ptr<const JointFeedback> feedback = joint_feedback_buffer_.Fetch();

    for (int i = 0; i < G1_JOINT_COUNT; ++i) {
      output_command.feedforward_torque.at(i) = 0.0;
      output_command.position_cmd.at(i) = 0.0;
      output_command.velocity_cmd.at(i) = 0.0;
      output_command.kp_gain.at(i) = stiffness_values[i];
      output_command.kd_gain.at(i) = damping_values[i];
    }

    if (feedback) {
      simulation_time_ += control_period_;
      if (simulation_time_ < motion_duration_) {
        // [Stage 1]: set robot to zero posture
        for (int i = 0; i < G1_JOINT_COUNT; ++i) {
          double ratio = std::clamp(simulation_time_ / motion_duration_, 0.0, 1.0);
          output_command.position_cmd.at(i) = (1.0 - ratio) * feedback->position.at(i);
        }
      } else if (simulation_time_ < motion_duration_ * 2) {
        // [Stage 2]: swing ankle using PR mode
        pr_mode_setting_ = ControlMode::PR;
        double max_P = M_PI * 30.0 / 180.0;
        double max_R = M_PI * 10.0 / 180.0;
        double t = simulation_time_ - motion_duration_;
        double L_P_des = max_P * std::sin(2.0 * M_PI * t);
        double L_R_des = max_R * std::sin(2.0 * M_PI * t);
        double R_P_des = max_P * std::sin(2.0 * M_PI * t);
        double R_R_des = -max_R * std::sin(2.0 * M_PI * t);
        output_command.position_cmd.at(LeftAnklePitch) = L_P_des;
        output_command.position_cmd.at(LeftAnkleRoll) = L_R_des;
        output_command.position_cmd.at(RightAnklePitch) = R_P_des;
        output_command.position_cmd.at(RightAnkleRoll) = R_R_des;
      } else {
        // [Stage 3]: swing ankle using AB mode
        pr_mode_setting_ = ControlMode::AB;
        double max_A = M_PI * 30.0 / 180.0;
        double max_B = M_PI * 10.0 / 180.0;
        double t = simulation_time_ - motion_duration_ * 2;
        double L_A_des = +max_A * std::sin(M_PI * t);
        double L_B_des = +max_B * std::sin(M_PI * t + M_PI);
        double R_A_des = -max_A * std::sin(M_PI * t);
        double R_B_des = -max_B * std::sin(M_PI * t + M_PI);
        output_command.position_cmd.at(LeftAnkleA) = L_A_des;
        output_command.position_cmd.at(LeftAnkleB) = L_B_des;
        output_command.position_cmd.at(RightAnkleA) = R_A_des;
        output_command.position_cmd.at(RightAnkleB) = R_B_des;
      }
      joint_command_buffer_.Update(output_command);
    }
  }
};

int main(int argc, char const *argv[]) {
  if (argc < 2) {
    std::cout << "Usage: g1_ankle_swing_example network_interface" << std::endl;
    exit(0);
  }
  std::string networkInterface = argv[1];
  G1RobotController controller(networkInterface);
  while (true) sleep(10);
  return 0;
}

