// ----------------------------------------------------------------------------
// Internal classes to implement gzstream. See header file for user classes.
// ----------------------------------------------------------------------------
// --------------------------------------
// class gzstreambuf:
// --------------------------------------
gzstreambuf* gzstreambuf::init_stream( const char* filename, int access_mode, int compress_factor) {
    if ( is_open())
        return (gzstreambuf*)0;
    flags = access_mode;
    // reject append mode or read/write simultaneously
    if ((flags & std::ios::ate) || (flags & std::ios::app)
        || ((flags & std::ios::in) && (flags & std::ios::out)))
        return (gzstreambuf*)0;
    char  mode_string[10];
    char* mode_ptr = mode_string;
    if ( flags & std::ios::in)
        *mode_ptr++ = 'r';
    else if ( flags & std::ios::out)
        *mode_ptr++ = 'w';
    *mode_ptr++ = 'b';
    if (flags & GZ_NO_COMPRESSION)
        *mode_ptr++ = '0'; // disable compression
    else
        *mode_ptr++ = '9'; // best compression ratio
    *mode_ptr = '\0';

    // BEGIN - Calculate size of compressed data
    if ( flags & std::ios::in) {
        FILE *handle = fopen(filename, "rb");
        if (handle) {
            fseek(handle, 0, SEEK_END);
            #if defined(_WIN64)
                input_size = _ftelli64(handle);
            #elif defined(_WIN32)
                input_size = ftell(handle);
            #else       
                input_size = ftello(handle); 
            #endif          
            fclose(handle);
        }
    }
    // END - Size calculation completed

    file = gzopen( filename, mode_string);
    if (file == 0) {
        return (gzstreambuf*)0;
    }
    active = 1;

    if ( flags & std::ios::out) {
        gzsetparams(file, compress_factor, Z_DEFAULT_STRATEGY );
    }

    return this;
}
gzstreambuf * gzstreambuf::terminate() {
    if ( is_open()) {
        flush();
        active = 0;
        if ( gzclose( file) == Z_OK)
            return this;
    }
    return (gzstreambuf*)0;
}
int gzstreambuf::fill_buffer() { // used for input buffer only
    if ( gptr() && ( gptr() < egptr()))
        return * reinterpret_cast<unsigned char *>( gptr());
    if ( ! (flags & std::ios::in) || ! active)
        return EOF;
    // Implementation from Josuttis' book
    long saved_chars = gptr() - eback();
    if ( saved_chars > 5)
        saved_chars = 5;
    memcpy( work_buffer + (5 - saved_chars), gptr() - saved_chars, saved_chars);
    int bytes_read = gzread( file, work_buffer+5, bufferCapacity-5);
    if (bytes_read <= 0) // ERROR or EOF
        return EOF;

    current_offset = gzoffset(file);

    // adjust buffer pointers
    setg( work_buffer + (5 - saved_chars),   // start of saved area
          work_buffer + 5,                 // current position
          work_buffer + 5 + bytes_read);   // end of valid data
    // return next character
    return * reinterpret_cast<unsigned char *>( gptr());    
}
int gzstreambuf::write_output() {
    // Isolate buffer writing from overflow() and
    // sync() operations.
    int  written = static_cast<int> ( pptr() - pbase() );
    long actual_written = gzwrite( file, pbase(), written);
    if ( actual_written != written)
        return EOF;
    pbump( -written);
    return written;
}
int gzstreambuf::extend_buffer( int c) { // used for output buffer only
    if ( ! ( flags & std::ios::out) || ! active)
        return EOF;
    if (c != EOF) {
        *pptr() = c;
        pbump(1);
    }
    if ( write_output() == EOF)
        return EOF;
    return c;
}
int gzstreambuf::flush() {
    // Use write_output() instead of extend_buffer( EOF)
    // which caused issues with std::endl and flush(),
    // as reported by Vincent Ricard.
    if ( pptr() && pptr() > pbase()) {
        if ( write_output() == EOF)
            return -1;
    }
    return 0;
}
size_t gzstreambuf::get_total_bytes() {
    return input_size;
}
size_t gzstreambuf::get_current_position() {
    return current_offset;
}
// --------------------------------------
// class gzstreambase:
// --------------------------------------
gzstreambase::gzstreambase( const char* path, int flags) {
    init( &buffer);
    init_stream( path, flags);
}
gzstreambase::~gzstreambase() {
    buffer.terminate();
}
void gzstreambase::init_stream( const char* path, int access_flags) {
    if ( ! buffer.init_stream( path, access_flags))
        clear( rdstate() | std::ios::badbit);
}
void gzstreambase::shutdown() {
    if ( buffer.is_open())
        if ( ! buffer.terminate())
            clear( rdstate() | std::ios::badbit);
}
z_off_t gzstreambase::get_uncompressed_count() {
	return gztell(buffer.file);
}
