#include <iostream>
#include <vector>
#include <cstring>
#include <cassert>

// Macro to read a single byte from input buffer or stream
#define READBYTE(c) \
    do { \
        c = 0; \
        if (InputRemaining) { \
            InputRemaining--; \
            if (BufferStart < BufferEnd) \
                c = InputBuffer[BufferStart++]; \
            else { \
                BufferEnd = (decltype(BufferEnd))InputStream->Read(&InputBuffer, sizeof(InputBuffer)); \
                c = InputBuffer[0]; \
                BufferStart = 1; \
            } \
        } \
    } while (0)

/* Acquire another byte and incorporate into the bit reservoir */
#define PULLBYTE() \
    do { \
        unsigned char incoming; \
        READBYTE(incoming); \
        Accumulator += (unsigned int)(incoming) << BitCount; \
        BitCount += 8; \
    } while (0)

/* Ensure the accumulator contains at least n bits */
#define NEEDBITS(n) \
    do { \
        while (BitCount < (unsigned)(n)) \
            PULLBYTE(); \
    } while (0)

/* Extract the lowest n bits from the accumulator (n < 16) */
#define BITS(n) \
    ((unsigned)Accumulator & ((1U << (n)) - 1))

/* Discard n bits from the accumulator */
#define DROPBITS(n) \
    do { \
        Accumulator >>= (n); \
        BitCount -= (unsigned)(n); \
    } while (0)

#define EXTRACTBITS(var, count) \
    do { \
        NEEDBITS(count); \
        var = BITS(count); \
        DROPBITS(count); \
    } while (0)

/****************************************************************
   Shannon-Fano tree construction and traversal routines
 ****************************************************************/
static const unsigned char ReverseNibble[] = {
    0x00, 0x08, 0x04, 0x0c, 0x02, 0x0a, 0x06, 0x0e,
    0x01, 0x09, 0x05, 0x0d, 0x03, 0x0b, 0x07, 0x0f
};
#define TOP_LEVEL_BITS    8
#define SUB_LEVEL_BITS    4

void FZipExploder::AddEntry(std::vector<HuffNode> &tree, unsigned int index, int depth, unsigned short pattern, int length, unsigned char symbol)
{
    assert(length > 0);
    unsigned int current = index + (pattern & ((1 << depth) - 1));
    if (length > depth)
    { // This code requires more bits than current level provides. Store lower bits
      // in this table, then proceed recursively.
        unsigned int subtree = tree[current].Subtable;
        if (subtree == 0)
        { // Need to allocate child table.
            subtree = CreateTable(tree, 1 << SUB_LEVEL_BITS);
            tree[current].Subtable = subtree;
            tree[current].Depth = depth;
            tree[current].Symbol = 0;
        }
        else
        {
            assert(tree[current].Depth == depth);
            assert(tree[current].Symbol == 0);
        }
        AddEntry(tree, subtree, SUB_LEVEL_BITS, pattern >> depth, length - depth, symbol);
    }
    else
    { // If this code uses fewer bits than this level, fill all matching positions.
        for (int repeat = 1 << (depth - length); --repeat >= 0; current += 1 << length)
        {
            tree[current].Depth = length;
            tree[current].Symbol = symbol;
            assert(tree[current].Subtable == 0);
        }
    }
}

unsigned int FZipExploder::CreateTable(std::vector<HuffNode> &tree, int entries)
{
    size_t offset = tree.size();
    tree.resize(tree.size() + entries);
    memset(&tree[offset], 0, sizeof(HuffNode)*entries);
    return (unsigned)offset;
}

int FZipExploder::CompareEntries(const void *first, const void *second)
{
    const TableBuilder *entry1 = (const TableBuilder *)first;
    const TableBuilder *entry2 = (const TableBuilder *)second;
    int diff = entry1->Length - entry2->Length;
    if (diff == 0) {
        diff = entry1->Value - entry2->Value;
    }
    return diff;
}

int FZipExploder::ConstructDecoder(std::vector<HuffNode> &tree, TableBuilder *entries, int count)
{
    int i;
    qsort(entries, count, sizeof(*entries), CompareEntries);
    // Build the Shannon-Fano tree:
    unsigned short codeword = 0;
    unsigned short increment = 0;
    unsigned short previousLength = 0;
    for (i = count - 1; i >= 0; --i)
    {
        codeword += increment;
        if (entries[i].Length != previousLength)
        {
            previousLength = entries[i].Length;
            increment = 1 << (16 - previousLength);
        }
        // Reverse bit order before storing
        entries[i].Code = ReverseNibble[codeword >> 12] |
                        (ReverseNibble[(codeword >> 8) & 0xf] << 4) |
                        (ReverseNibble[(codeword >> 4) & 0xf] << 8) |
                        (ReverseNibble[codeword & 0xf] << 12);
    }
    // Populate hierarchical table structure
    CreateTable(tree, 1 << TOP_LEVEL_BITS);      // Initialize root level.
    for (i = 0; i < count; ++i)
    {
        AddEntry(tree, 0, TOP_LEVEL_BITS, entries[i].Code, entries[i].Length, entries[i].Value);
    }
    return 0;
}

int FZipExploder::TraverseTree(const std::vector<HuffNode> &tree)
{
    unsigned int bits = TOP_LEVEL_BITS, tableIndex = 0, code;
    const HuffNode *current;
    do
    {
        NEEDBITS(bits);
        code = BITS(bits);
        bits = SUB_LEVEL_BITS;
        current = &tree[tableIndex + code];
        DROPBITS(current->Depth);
        tableIndex = current->Subtable;
    }
    while (tableIndex != 0);
    return current->Symbol;
}

int FZipExploder::ParseSFTable(std::vector<HuffNode> &tree, int symbols)
{
    TableBuilder builder[256];
    unsigned char firstByte, secondByte;
    int j, entries, valueCount = 0;
    READBYTE(secondByte);
    entries = secondByte + 1;
    for (j = 0; j < entries; j++) {
        int symbolLen, codeLen;
        READBYTE(firstByte);
        symbolLen = ((firstByte >> 4) & 15) + 1;
        codeLen = (firstByte & 15) + 1;
        while (symbolLen--) {
            builder[valueCount].Length = codeLen;
            builder[valueCount].Value = valueCount;
            valueCount++;
        }
    }
    if (valueCount != symbols)
        return 1;    /* malformed table */
    return ConstructDecoder(tree, builder, valueCount);
}

int FZipExploder::Decompress(unsigned char *output, unsigned int outsize,
                             FileReader &input, unsigned int insize,
                             int options)
{
    int byteVal, j, minMatchLength = 3, matchLen, matchDist;
    int distanceBits;
    unsigned int writeIdx = 0;
    Accumulator = 0;
    BitCount = 0;
    InputStream = &input;
    InputRemaining = insize;
    BufferStart = BufferEnd = 0;
    if ((options & 4)) {
        /* 3 trees: literals, lengths, distance top 6 */
        minMatchLength = 3;
        if (ParseSFTable(LiteralTree, 256))
            return 1;
    } else {
        /* 2 trees: lengths, distance top 6 */
        minMatchLength = 2;
    }
    if (ParseSFTable(LengthTree, 64))
        return 1;
    if (ParseSFTable(DistanceTree, 64))
        return 1;
    distanceBits = (options & 2) ? /* 8k dictionary */ 7 : /* 4k dictionary */ 6;
    while (writeIdx < outsize)
    {
        EXTRACTBITS(byteVal, 1);
        if (byteVal) {
            /* literal data */
            if ((options & 4)) {
                byteVal = TraverseTree(LiteralTree);
            } else {
                EXTRACTBITS(byteVal, 8);
            }
            output[writeIdx++] = byteVal;
        } else {
            EXTRACTBITS(matchDist, distanceBits);
            byteVal = TraverseTree(DistanceTree);
            matchDist |= (byteVal << distanceBits);
            matchLen = TraverseTree(LengthTree);
            if (matchLen == 63) {
                EXTRACTBITS(byteVal, 8);
                matchLen += byteVal;
            }
            matchLen += minMatchLength;
            matchDist++;
            if (writeIdx + matchLen > outsize) {
                return -1;
            }
            if ((unsigned int)matchDist > writeIdx) {
                /* Anything before the first input byte is zero. */
                int zeros = matchDist - writeIdx;
                if (matchLen < zeros)
                    zeros = matchLen;
                for(j = zeros; j; j--)
                    output[writeIdx++] = 0;
                matchLen -= zeros;
            }
            for(j = matchLen; j; j--, writeIdx++) {
                output[writeIdx] = output[writeIdx - matchDist];
            }
        }
    }
    return 0;
}

/* HSIZE is defined as 2^13 (8192) in unzip.h */
#define TABLE_SIZE 8192
#define ESCAPE_CODE 256
#define INDEX_MASK  (TABLE_SIZE - 1)   /* 0x1fff (lower bits are parent's index) */
#define UNUSED_CODE TABLE_SIZE         /* 0x2000 (code is unused or was cleared) */
#define HAS_BRANCH  (TABLE_SIZE << 1)  /* 0x4000 (code has a child--do not clear) */

int ShrinkLoop(unsigned char *output, unsigned int outsize, FileReader &_In, unsigned int InputLeft)
{
    // Allocate working memory on heap instead of stack due to large size requirements
    struct work
    {
        unsigned char InputBuffer[256];
        unsigned short Parent[TABLE_SIZE];
        unsigned char Value[TABLE_SIZE], Stack[TABLE_SIZE];
    };
    auto workspace = std::make_unique<work>();
    unsigned char* InputBuffer = workspace->InputBuffer;
    unsigned short* Parent = workspace->Parent;
    unsigned char* Value = workspace->Value, * Stack = workspace->Stack;
    FileReader *InputStream = &_In;
    unsigned char *decodedString;
    int length;
    int KwKwK, codesize = 9;    /* start at 9 bits/code */
    int code, previousCode, freecode, currentCode;
    unsigned int BitCount = 0, Accumulator = 0;
    unsigned int position = 0;
    unsigned int BufferStart = 0, BufferEnd = 0;
    freecode = ESCAPE_CODE;
    for (code = 0; code < ESCAPE_CODE; code++)
    {
        Value[code] = code;
        Parent[code] = ESCAPE_CODE;
    }
    for (code = ESCAPE_CODE+1; code < TABLE_SIZE; code++)
        Parent[code] = UNUSED_CODE;
    EXTRACTBITS(previousCode, codesize);
    if (position < outsize) {
        output[position++] = previousCode;
    }
    while (position < outsize)
    {
        EXTRACTBITS(code, codesize);
        if (code == ESCAPE_CODE) {    /* possible to have consecutive escapes? */
            EXTRACTBITS(code, codesize);
            if (code == 1) {
                codesize++;
            } else if (code == 2) {
                /* clear leafs (nodes with no children) */
                /* first loop:  mark each parent as such */
                for (code = ESCAPE_CODE+1;  code < TABLE_SIZE;  ++code) {
                    currentCode = (Parent[code] & INDEX_MASK);
                    if (currentCode > ESCAPE_CODE)
                        Parent[currentCode] |= HAS_BRANCH;        /* set parent's child-bit */
                }
                /* second loop:  clear all nodes *not* marked as parents; reset flag bits */
                for (code = ESCAPE_CODE+1;  code < TABLE_SIZE;  ++code) {
                    if (Parent[code] & HAS_BRANCH) {        /* just clear child-bit */
                        Parent[code] &= ~HAS_BRANCH;
                    } else {                            /* leaf:  lose it */
                        Parent[code] = UNUSED_CODE;
                    }
                }
                freecode = ESCAPE_CODE;
            }
            continue;
        }
        decodedString = &Stack[TABLE_SIZE-1];
        currentCode = code;
        if (Parent[currentCode] == UNUSED_CODE) {
            KwKwK = 1;
            decodedString--;    /* last character will be same as first character */
            currentCode = previousCode;
            length = 1;
        } else {
            KwKwK = 0;
            length = 0;
        }
        do {
            *decodedString-- = Value[currentCode];
            length++;
            currentCode = (Parent[currentCode] & INDEX_MASK);
        } while (currentCode != ESCAPE_CODE);
        decodedString++;
        if (KwKwK) {
            Stack[TABLE_SIZE-1] = *decodedString;
        }
        do {
            freecode++;
        } while (Parent[freecode] != UNUSED_CODE);
        Parent[freecode] = previousCode;
        Value[freecode] = *decodedString;
        previousCode = code;
        while (length--) {
            output[position++] = *decodedString++;
        }
    }
    return 0;
}

