// Command to copy shared texture resources between devices
struct FRHICommandCopySharedTexture final : public FRHICommand<FRHICommandCopySharedTexture>
{
	TComPtr<ID3D11Texture2D> SourceTexture;
	FTexture2DRHIRef DestinationTexture;

	FRHICommandCopySharedTexture(ID3D11Texture2D* InSource, FRHITexture2D* InDest)
		: SourceTexture(InSource)
		, DestinationTexture(InDest)
	{
	}

	void Execute(FRHICommandListBase& CmdList) override
	{
		LLM_SCOPE(ELLMTag::MediaStreaming);
		ID3D11Device* NativeDevice = static_cast<ID3D11Device*>(GDynamicRHI->RHIGetNativeDevice());
		ID3D11DeviceContext* ImmediateContext = nullptr;
		NativeDevice->GetImmediateContext(&ImmediateContext);

		if (ImmediateContext)
		{
			ID3D11Resource* DestResource = reinterpret_cast<ID3D11Resource*>(DestinationTexture->GetNativeResource());
			if (DestResource)
			{
				TComPtr<IDXGIResource> SharedResource(nullptr);
				if (SUCCEEDED(SourceTexture->QueryInterface(__uuidof(IDXGIResource), (void**)&SharedResource)))
				{
					HANDLE SharedHandle = nullptr;
					if (SUCCEEDED(SharedResource->GetSharedHandle(&SharedHandle)) && SharedHandle != 0)
					{
						TComPtr<ID3D11Resource> OpenedSharedResource;
						if (SUCCEEDED(NativeDevice->OpenSharedResource(SharedHandle, __uuidof(ID3D11Texture2D), (void**)&OpenedSharedResource)))
						{
							TComPtr<IDXGIKeyedMutex> Mutex(nullptr);
							if (SUCCEEDED(OpenedSharedResource->QueryInterface(_uuidof(IDXGIKeyedMutex), (void**)&Mutex)))
							{
								// Key 1: New data available; Key 2: Data already consumed
								HRESULT AcquireResult = Mutex->AcquireSync(1, 0);
								if (AcquireResult == S_OK)
								{
									ImmediateContext->CopyResource(DestResource, OpenedSharedResource);
									Mutex->ReleaseSync(2);
								}
								else if (AcquireResult != S_FALSE)
								{
									// Wait for other reader to finish (key 2)
									if (Mutex->AcquireSync(2, INFINITE) == S_OK)
									{
										Mutex->ReleaseSync(2);
									}
								}
							}
						}
					}
				}
			}
			ImmediateContext->Release();
		}
	}
};

bool FWmfMediaHardwareVideoDecodingParameters::ConvertTextureFormat_RenderThread(FWmfMediaHardwareVideoDecodingTextureSample* Sample, FTexture2DRHIRef DstTexture)
{
	LLM_SCOPE(ELLMTag::MediaStreaming);
	if (!Sample || !DstTexture.IsValid())
	{
		return false;
	}

	check(IsInRenderingThread());
	check(Sample);

	TComPtr<ID3D11Texture2D> TextureSource = Sample->GetSourceTexture();
	ID3D11Device* Device = static_cast<ID3D11Device*>(GDynamicRHI->RHIGetNativeDevice());
	ID3D11DeviceContext* Context = nullptr;
	Device->GetImmediateContext(&Context);

	if (Context)
	{
		FRHICommandListImmediate& CmdList = FRHICommandListExecutor::GetImmediateCommandList();
		SCOPED_DRAW_EVENT(CmdList, FWmfMediaHardwareVideoDecodingParameters_Convert);
		SCOPED_GPU_STAT(CmdList, MediaTextureConversion);

		FTexture2DRHIRef TempDestTexture = Sample->GetOrCreateDestinationTexture();

		FRHIRenderPassInfo RPInfo(TempDestTexture, ERenderTargetActions::DontLoad_Store);
		CmdList.BeginRenderPass(RPInfo, TEXT("ConvertTextureFormat"));

		// Set viewport to match sample dimensions
		FIntPoint Dim = Sample->GetDim();
		CmdList.SetViewport(0, 0, 0.f, Dim.X, Dim.Y, 1.f);

		// Configure graphics pipeline
		FGraphicsPipelineStateInitializer PSOInit;
		CmdList.ApplyCachedRenderTargets(PSOInit);
		PSOInit.DepthStencilState = TStaticDepthStencilState<false, CF_Always>::GetRHI();
		PSOInit.BlendState = TStaticBlendState<>::GetRHI();
		PSOInit.RasterizerState = TStaticRasterizerState<>::GetRHI();
		PSOInit.PrimitiveType = PT_TriangleList;
		PSOInit.BoundShaderState.VertexDeclarationRHI = GetVertexDeclarationFVector4();

		if (CmdList.Bypass())
		{
			FRHICommandCopySharedTexture CopyCmd(TextureSource, TempDestTexture);
			CopyCmd.Execute(CmdList);
		}
		else
		{
			new (CmdList.AllocCommand<FRHICommandCopySharedTexture>()) FRHICommandCopySharedTexture(TextureSource, TempDestTexture);
		}

		FGlobalShaderMap* ShaderMap = GetGlobalShaderMap(GMaxRHIFeatureLevel);

		switch (Sample->GetFormat())
		{
		case EMediaTextureSampleFormat::CharNV12:
		{
			TShaderMapRef< FHardwareVideoDecodingVS > VS(ShaderMap);
			TShaderMapRef< FHardwareVideoDecodingPS > PS(ShaderMap);
			PSOInit.BoundShaderState.VertexShaderRHI = VS.GetVertexShader();
			PSOInit.BoundShaderState.PixelShaderRHI = PS.GetPixelShader();
			SetGraphicsPipelineState(CmdList, PSOInit);

			FShaderResourceViewRHIRef Y_SRV = RHICreateShaderResourceView(TempDestTexture, 0, 1, PF_G8);
			FShaderResourceViewRHIRef UV_SRV = RHICreateShaderResourceView(TempDestTexture, 0, 1, PF_R8G8);
			VS->SetParameters(CmdList, VS.GetVertexShader(), Y_SRV, UV_SRV, Sample->IsOutputSrgb());
			PS->SetParameters(CmdList, PS.GetPixelShader(), Y_SRV, UV_SRV, Sample->IsOutputSrgb());
			break;
		}
		case EMediaTextureSampleFormat::CharBGRA:
		{
			TShaderMapRef< FHardwareVideoDecodingVS > VS(ShaderMap);
			TShaderMapRef< FHardwareVideoDecodingPassThroughPS > PS(ShaderMap);
			PSOInit.BoundShaderState.VertexShaderRHI = VS.GetVertexShader();
			PSOInit.BoundShaderState.PixelShaderRHI = PS.GetPixelShader();
			SetGraphicsPipelineState(CmdList, PSOInit);

			FShaderResourceViewRHIRef SRV = RHICreateShaderResourceView(TempDestTexture, 0, 1, PF_B8G8R8A8);
			VS->SetParameters(CmdList, VS.GetVertexShader(), SRV, Sample->IsOutputSrgb());
			PS->SetParameters(CmdList, PS.GetPixelShader(), SRV, Sample->IsOutputSrgb());
			break;
		}
		case EMediaTextureSampleFormat::Y416:
		{
			TShaderMapRef< FHardwareVideoDecodingVS > VS(ShaderMap);
			TShaderMapRef< FHardwareVideoDecodingY416PS > PS(ShaderMap);
			PSOInit.BoundShaderState.VertexShaderRHI = VS.GetVertexShader();
			PSOInit.BoundShaderState.PixelShaderRHI = PS.GetPixelShader();
			SetGraphicsPipelineState(CmdList, PSOInit);

			FShaderResourceViewRHIRef SRV = RHICreateShaderResourceView(TempDestTexture, 0, 1, PF_A16B16G16R16);
			VS->SetParameters(CmdList, VS.GetVertexShader(), SRV, Sample->IsOutputSrgb());
			PS->SetParameters(CmdList, PS.GetPixelShader(), SRV, Sample->IsOutputSrgb());
			break;
		}
		default:
			break;
		}

		CmdList.DrawPrimitive(0, 2, 1);
		CmdList.EndRenderPass();
		Context->Release();
	}

	return true;
}
#endif

