#define NOINLINE __attribute__((noinline))
#define LOG_TAG "NativeLeakTest"
#define NUM_THREADS 10
#define NUM_CASES 10
#define KB(val) ((val) * 1024L)
#define MB(val) (KB(val) * 1024L)
#define INFO_LOG(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)

static NOINLINE void LeakTestMalloc() {
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    size_t block_size = MB(std::rand() % 10);
    auto memory_block = malloc(block_size);
    if (idx % 2 != 0) {
      INFO_LOG("%s %p size %u", __FUNCTION__, memory_block, block_size);
    } else {
      free(memory_block);
    }
  }
}

static NOINLINE void LeakTestRealloc() {
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    size_t block_size = KB(std::rand() % 1000);
    auto memory_block = realloc(nullptr, block_size);
    if (idx % 2 != 0) {
      INFO_LOG("%s %p size %u", __FUNCTION__, memory_block, block_size);
    } else {
      free(memory_block);
    }
  }
}

static NOINLINE void LeakTestCalloc() {
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    size_t element_count = std::rand() % 1000;
    auto memory_block = calloc(element_count, 8);
    if (idx % 2 != 0) {
      INFO_LOG("%s %p size %u", __FUNCTION__, memory_block, element_count);
    } else {
      free(memory_block);
    }
  }
}

static NOINLINE void LeakTestMemalign() {
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    size_t block_size = KB(std::rand() % 1000);
    auto memory_block = memalign(16, block_size);
    if (idx % 2 != 0) {
      INFO_LOG("%s %p size %u", __FUNCTION__, memory_block, block_size);
    } else {
      free(memory_block);
    }
  }
}

static NOINLINE void LeakTestNewOperator() {
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    auto string_ptr = new std::string("test_leak_string");
    if (idx % 2 != 0) {
      INFO_LOG("%s %p size %u", __FUNCTION__, string_ptr, string_ptr->size());
    } else {
      delete string_ptr;
    }
  }
}

static NOINLINE void LeakTestNewArray() {
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    size_t array_size = std::rand() % 1000;
    auto array_ptr = new std::string[array_size];
    if (idx % 2 != 0) {
      INFO_LOG("%s %p size %u", __FUNCTION__, array_ptr, array_size * sizeof(std::string));
    } else {
      delete[] array_ptr;
    }
  }
}

static NOINLINE void LeakTestContainer() {
  std::vector<std::string *> string_vector(NUM_CASES);
  for (int idx = 0; idx < NUM_CASES; ++idx) {
    string_vector[idx] = new std::string("test_leak_container");
  }
}

static NOINLINE jlong TestJavaReferenceNative() {
  auto native_pointer = (void **) malloc(sizeof(void *) * NUM_THREADS);
  INFO_LOG("%s Holder addr %p", __FUNCTION__, native_pointer);
  for (int idx = 0; idx < NUM_THREADS; ++idx) {
    size_t block_size = std::rand() % 1000;
    native_pointer[idx] = malloc(block_size);
    INFO_LOG("%s %p size %u", __FUNCTION__, native_pointer[idx], block_size);
  }
  return reinterpret_cast<jlong>(native_pointer);
}

extern "C" JNIEXPORT jlong
Java_com_kwai_koom_demo_nativeleak_NativeLeakTest_triggerLeak(
    JNIEnv *env,
    jclass,
    jobject unused/* this */) {
  auto leak_function = []() {
    LeakTestMalloc();
    LeakTestCalloc();
    LeakTestRealloc();
    LeakTestMemalign();
    LeakTestNewOperator();
    LeakTestNewArray();
    LeakTestContainer();
  };

  for (int thread_idx = 0; thread_idx < NUM_THREADS; ++thread_idx) {
    std::thread worker_thread(leak_function);
    worker_thread.detach();
  }

  return TestJavaReferenceNative();
}

