// Custom Lua file loader implementation
static int l_custom_loadfile(lua_State *L)
{
    const char *filepath = luaL_checkstring(L, 1);
    {
        std::string cleanFilename = filepath;
        std::string fileContent = Core::Utils::LoadFile(filepath);
        if (fileContent.empty()) {
            lua_pushfstring(L, "cannot open %s", filepath);
            goto __fail;
        }
        Core::Utils::Replace(cleanFilename, PLUGIN_FOLDER "/", ""); // Strip known directory prefix
        if (luaL_loadbuffer(L, fileContent.c_str(), fileContent.size(), cleanFilename.c_str()) != 0)
            goto __fail;
        return 1;
    }
    __fail:
    return lua_error(L);
}

// Custom dofile implementation
static int l_custom_dofile(lua_State *L) 
{
    lua_getglobal(L, "loadfile");
    lua_pushvalue(L, 1);
    if (lua_pcall(L, 1, 1, 0) != 0)
        return lua_error(L);
    if (!lua_isfunction(L, -1))
        return luaL_error(L, "Failed to load");

    lua_Debug info;
    if (lua_getstack(L, 1, &info) && lua_getinfo(L, "f", &info)) {
        lua_getfenv(L, -1);
        lua_remove(L, -2);
    } else {
        lua_pushvalue(L, LUA_GLOBALSINDEX);
    }
    lua_setfenv(L, -2);
    lua_remove(L, 1);

    int initialTop = lua_gettop(L);
    if (lua_pcall(L, 0, LUA_MULTRET, 0) != 0)
        return lua_error(L);

    int finalTop = lua_gettop(L);
    return finalTop - initialTop + 1;
}

// Custom module loader implementation
static int l_custom_loader(lua_State *L) 
{
    const char *moduleName = luaL_checkstring(L, 1);
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "path");
    const char *pathTemplate = lua_tostring(L, -1);
    lua_pop(L, 2);

    {
        std::string modulePath(moduleName);
        std::replace(modulePath.begin(), modulePath.end(), '.', '/');
        std::string searchPaths(pathTemplate);
        size_t index = 0;
        std::string failureMessages = "\n\tno file with name '"+std::string(moduleName)+"' found";

        while (index < searchPaths.size()) {
            size_t nextSeparator = searchPaths.find(';', index);
            std::string currentPath = searchPaths.substr(index, nextSeparator - index);
            size_t placeholder = currentPath.find('?');

            if (placeholder != std::string::npos)
                currentPath.replace(placeholder, 1, modulePath);

            std::string fileContent = Core::Utils::LoadFile(currentPath);
            if (!fileContent.empty()) {
                if (luaL_loadbuffer(L, fileContent.c_str(), fileContent.size(), currentPath.c_str()) == 0)
                    return 1;
                else
                    goto __fail;
            }

            if (nextSeparator == std::string::npos)
                break;
            index = nextSeparator + 1;
        }

        lua_pushstring(L, failureMessages.c_str());
        goto __fail;
    }
    __fail:
    return lua_error(L);
}

// Register custom file loading functions in Lua environment
bool Core::RegisterCustomFileLoader(lua_State *L)
{
    lua_pushcfunction(L, l_custom_loadfile);
    lua_setglobal(L, "loadfile");

    lua_pushcfunction(L, l_custom_dofile);
    lua_setglobal(L, "dofile");

    lua_getglobal(L, "package");
    lua_getfield(L, -1, "loaders");

    if (lua_istable(L, -1)) {
        for (int idx = lua_objlen(L, -1) + 1; idx > 1; --idx) {
            lua_rawgeti(L, -1, idx - 1);
            lua_rawseti(L, -2, idx);
        }
        lua_pushcfunction(L, l_custom_loader);
        lua_rawseti(L, -2, 1);
    }
    else {
        lua_pop(L, 2);
        return false;
    }

    lua_pop(L, 2);
    return true;
}

#include "ParseHelper.h"
namespace glslang {
//
// The inductive loop-body traverser.
//
// Focus only on constructs that could change the loop counter.
//
class TInductiveTraverser : public TIntermTraverser {
public:
    TInductiveTraverser(long long varId, TSymbolTable& symTab)
    : loopVarId(varId), symbolTable(symTab), isInvalid(false) { }
    virtual bool visitBinary(TVisit, TIntermBinary* node);
    virtual bool visitUnary(TVisit, TIntermUnary* node);
    virtual bool visitAggregate(TVisit, TIntermAggregate* node);
    long long loopVarId;        // identifier of the symbol acting as the loop counter
    TSymbolTable& symbolTable;
    bool isInvalid;
    TSourceLoc errorLoc;
protected:
    TInductiveTraverser(TInductiveTraverser&);
    TInductiveTraverser& operator=(TInductiveTraverser&);
};

// Examine binary operations for those affecting the loop counter
bool TInductiveTraverser::visitBinary(TVisit /* visit */, TIntermBinary* node)
{
    if (node->modifiesState() && node->getLeft()->getAsSymbolNode() &&
                                 node->getLeft()->getAsSymbolNode()->getId() == loopVarId) {
        isInvalid = true;
        errorLoc = node->getLoc();
    }
    return true;
}

// Examine unary operations for those affecting the loop counter
bool TInductiveTraverser::visitUnary(TVisit /* visit */, TIntermUnary* node)
{
    if (node->modifiesState() && node->getOperand()->getAsSymbolNode() &&
                                 node->getOperand()->getAsSymbolNode()->getId() == loopVarId) {
        isInvalid = true;
        errorLoc = node->getLoc();
    }
    return true;
}

// Examine function calls for arguments that may modify the loop counter
bool TInductiveTraverser::visitAggregate(TVisit /* visit */, TIntermAggregate* node)
{
    if (node->getOp() == EOpFunctionCall) {
        // Check if any out/inout argument corresponds to the loop counter
        const TIntermSequence& paramList = node->getSequence();
        for (int idx = 0; idx < (int)paramList.size(); ++idx) {
            if (paramList[idx]->getAsSymbolNode() && paramList[idx]->getAsSymbolNode()->getId() == loopVarId) {
                TSymbol* funcSym = symbolTable.find(node->getName());
                const TType* paramType = (*funcSym->getAsFunction())[idx].type;
                if (paramType->getQualifier().storage == EvqOut ||
                    paramType->getQualifier().storage == EvqInOut) {
                    isInvalid = true;
                    errorLoc = node->getLoc();
                }
            }
        }
    }
    return true;
}

//
// Public interface for loop body validation.
//
void TParseContext::inductiveLoopBodyCheck(TIntermNode* loopBody, long long loopVarId, TSymbolTable& symbolTable)
{
    TInductiveTraverser it(loopVarId, symbolTable);
    if (loopBody == nullptr)
        return;
    loopBody->traverse(&it);
    if (it.isInvalid)
        error(it.errorLoc, "inductive loop index modified", "limitations", "");
}

//
// The "constant-index-expression" traverser.
//
// Inspect nodes involved in forming an array index.
//
class TIndexTraverser : public TIntermTraverser {
public:
    TIndexTraverser(const TIdSetType& ids) : loopVarIds(ids), isInvalid(false) { }
    virtual void visitSymbol(TIntermSymbol* symbol);
    virtual bool visitAggregate(TVisit, TIntermAggregate* node);
    const TIdSetType& loopVarIds;
    bool isInvalid;
    TSourceLoc errorLoc;
protected:
    TIndexTraverser(TIndexTraverser&);
    TIndexTraverser& operator=(TIndexTraverser&);
};

// Verify that symbols used are valid loop indices
void TIndexTraverser::visitSymbol(TIntermSymbol* symbol)
{
    if (loopVarIds.find(symbol->getId()) == loopVarIds.end()) {
        isInvalid = true;
        errorLoc = symbol->getLoc();
    }
}

// Treat function calls as invalid, per spec guidance
bool TIndexTraverser::visitAggregate(TVisit /* visit */, TIntermAggregate* node)
{
    if (node->getOp() == EOpFunctionCall) {
        isInvalid = true;
        errorLoc = node->getLoc();
    }
    return true;
}

//
// Public interface for constant index expression validation.
//
void TParseContext::constantIndexExpressionCheck(TIntermNode* indexExpr)
{
#ifndef GLSLANG_WEB
    TIndexTraverser it(loopVarIds);
    indexExpr->traverse(&it);
    if (it.isInvalid)
        error(it.errorLoc, "Non-constant-index-expression", "limitations", "");
#endif
}
} // end namespace glslang

