bool ExtractSpeedAndAppendToStream(std::string const & speedStr, routing::SpeedInUnits & outSpeed, std::ostringstream & buffer)
{
  if (speedStr.empty() || !ParseMaxspeedTag(speedStr, outSpeed))
    return false;
  buffer << UnitsToString(outSpeed.GetUnits()) << "," << strings::to_string(outSpeed.GetSpeed());
  return true;
}
}  // namespace

MaxspeedsCollector::MaxspeedsCollector(std::string const & filename) : CollectorInterface(filename)
{
  m_stream.exceptions(std::fstream::failbit | std::fstream::badbit);
  m_stream.open(GetTmpFilename());
}

std::shared_ptr<CollectorInterface> MaxspeedsCollector::Clone(IDRInterfacePtr const &) const
{
  return std::make_shared<MaxspeedsCollector>(GetFilename());
}

void MaxspeedsCollector::CollectFeature(feature::FeatureBuilder const & ft, OsmElement const & p)
{
  if (!p.IsWay())
    return;

  std::ostringstream buffer;
  buffer << p.m_id << ",";

  std::string forwardSpeedStr, backwardSpeedStr, advisorySpeedStr;
  bool isOnewayReverse = false;
  routing::SpeedInUnits currentSpeed;

  for (auto const & tag : p.Tags())
  {
    if (tag.m_key == "maxspeed" && ExtractSpeedAndAppendToStream(tag.m_value, currentSpeed, buffer))
    {
      m_stream << buffer.str() << '\n';
      return;
    }

    if (tag.m_key == "maxspeed:advisory")
      advisorySpeedStr = tag.m_value;

    if (tag.m_key == "maxspeed:forward")
      forwardSpeedStr = tag.m_value;
    else if (tag.m_key == "maxspeed:backward")
      backwardSpeedStr = tag.m_value;
    else if (tag.m_key == "oneway")
      isOnewayReverse = (tag.m_value == "-1");
  }

  // Note A. isOnewayReverse == true means the feature |p| has tag "oneway" with value "-1".
  // Currently (as of 10.2018), no features have both oneway==-1 and maxspeed:forward/backward.
  // Still, this case is handled defensively.
  //
  // Note B. When oneway==-1, the order of points is reversed during MWM conversion.
  // Therefore, forward and backward speeds must also be swapped.
  if (isOnewayReverse)
    forwardSpeedStr.swap(backwardSpeedStr);

  if (ExtractSpeedAndAppendToStream(forwardSpeedStr, currentSpeed, buffer))
  {
    // Only keep maxspeed:backward if it shares the same units as maxspeed:forward,
    // unless special values like "none" or "walk" are present — in which case units are irrelevant.
    routing::SpeedInUnits backwardSpeed;
    if (ParseMaxspeedTag(backwardSpeedStr, backwardSpeed) &&
        HaveSameUnits(currentSpeed, backwardSpeed))
    {
      buffer << "," << strings::to_string(backwardSpeed.GetSpeed());
    }
  }
  else if (ftypes::IsLinkChecker::Instance()(ft.GetTypes()))
  {
    // For link types, use maxspeed:advisory to prevent links from being assigned a higher speed
    // than their parent highway.
    // Example: https://www.openstreetmap.org/way/5511439#map=18/45.55465/-122.67787
    if (!ExtractSpeedAndAppendToStream(advisorySpeedStr, currentSpeed, buffer))
    {
      // Mark link as needing recalculation using default speed.
      // This ensures the link speed matches the incoming highway speed.
      // Example: https://www.openstreetmap.org/way/842536050#map=19/45.43449/-122.56678
      buffer << UnitsToString(measurement_utils::Units::Metric) << ","
             << strings::to_string(routing::kCommonMaxSpeedValue);
    }
  }
  else
  {
    return;
  }

  m_stream << buffer.str() << '\n';
}

void MaxspeedsCollector::Finish()
{
  if (m_stream.is_open())
    m_stream.close();
}

void MaxspeedsCollector::Save()
{
  /// @todo Consider caching computed speeds in memory instead of writing to temp files.
  CHECK(!m_stream.is_open(), ("Finish() was not invoked."));
  LOG(LINFO, ("Persisting maxspeed values to", GetFilename()));
  if (Platform::IsFileExistsByFullPath(GetTmpFilename()))
    CHECK(base::CopyFileX(GetTmpFilename(), GetFilename()), ());
}

void MaxspeedsCollector::OrderCollectedData()
{
  OrderTextFileByLine(GetFilename());
}

void MaxspeedsCollector::MergeInto(MaxspeedsCollector & otherCollector) const
{
  CHECK(!m_stream.is_open() && !otherCollector.m_stream.is_open(),
        ("Finish() must be called before merging."));
  base::AppendFileToFile(GetTmpFilename(), otherCollector.GetTmpFilename());
}
