// Compute intersection of multiple result sets, filtering out self-loops
std::unordered_set<std::pair<int, int>, IntPairHasher> intersectResults(
    const std::vector<std::unordered_set<Edge, EdgeHasher>> &sets) {
  size_t count = sets.size();
  assert(count >= 1);
  std::unordered_set<std::pair<int, int>, IntPairHasher> common;

  // Initialize with first set, excluding self-loops
  for (const auto &edge : sets[0]) {
    if (std::get<0>(edge) != std::get<2>(edge)) {
      common.insert(std::make_pair(std::get<0>(edge), std::get<2>(edge)));
    }
  }

  // Intersect with remaining sets
  for (size_t idx = 1; idx < count; ++idx) {
    std::unordered_set<std::pair<int, int>, IntPairHasher> temp;
    for (const auto &edge : sets[idx]) {
      std::pair<int, int> pair = std::make_pair(std::get<0>(edge), std::get<2>(edge));
      if (common.find(pair) != common.end()) {
        temp.insert(pair);
      }
    }
    common = std::move(temp);
  }

  return common;
}

// Assign unique integer IDs to string names
std::unordered_map<std::string, int>
assignIDs(const std::vector<std::string> &identifiers) {
  std::unordered_map<std::string, int> mapping;
  int idCounter = 0;
  for (const auto &id : identifiers) {
    if (mapping.find(id) == mapping.end()) {
      mapping[id] = idCounter++;
    }
  }
  return mapping;
}

// Reverse a map: swap keys and values
template <typename Key, typename Value>
std::unordered_map<Value, Key> invertMap(const std::unordered_map<Key, Value> &original) {
  std::unordered_map<Value, Key> inverted;
  for (const auto &entry : original) {
    inverted[entry.second] = entry.first;
  }
  return inverted;
}

/* Load raw grammars from file format:
 * { 
 * | production1
 * | production2
 * } */
std::vector<std::vector<std::vector<std::string>>>
loadRawGrammars(const std::string &filename) {
  std::ifstream input(filename);
  std::vector<std::vector<std::vector<std::string>>> allGrammars;
  std::vector<std::vector<std::string>> currentGrammar;
  std::string line;

  while (std::getline(input, line)) {
    if (!line.empty()) {
      if (line[0] == '{') {
        currentGrammar.clear();
      } else if (line[0] == '|') {
        std::istringstream stream(line.substr(1));
        std::vector<std::string> tokens;
        std::string token;
        while (stream >> token) {
          tokens.push_back(std::move(token));
        }
        currentGrammar.push_back(std::move(tokens));
      } else if (line[0] == '}') {
        allGrammars.push_back(std::move(currentGrammar));
      }
    }
  }

  return allGrammars;
}

// Parse graph file into list of edges (source, label, target)
std::vector<std::tuple<std::string, std::string, std::string>>
loadRawGraph(const std::string &filename) {
  std::ifstream input(filename);
  std::vector<std::tuple<std::string, std::string, std::string>> edgeList;
  std::string line;

  while (std::getline(input, line)) {
    if (line.find("->") != std::string::npos) {
      size_t arrowPos = line.find("->");
      size_t bracketStart = line.find('[');
      size_t equalsPos = line.find('=');
      size_t bracketEnd = line.find(']');

      std::string src = line.substr(0, arrowPos - 0);
      std::string label = line.substr(equalsPos + 2, (bracketEnd - 1) - (equalsPos + 2));
      std::string dst = line.substr(arrowPos + 2, bracketStart - (arrowPos + 2));

      edgeList.emplace_back(src, label, dst);
    }
  }

  return edgeList;
}

// Encode raw grammars and graph into integer-based representation
std::tuple<std::vector<Grammar>, size_t, std::unordered_set<Edge, EdgeHasher>>
encodeData(
    std::vector<std::vector<std::vector<std::string>>> rawGrammars,
    std::vector<std::tuple<std::string, std::string, std::string>> rawEdges) {

  // Collect all symbols for encoding
  std::vector<std::string> symbolList;
  for (const auto &grammar : rawGrammars) {
    for (const auto &rule : grammar) {
      for (const auto &symbol : rule) {
        symbolList.push_back(symbol);
      }
    }
  }

  auto symbolToId = assignIDs(symbolList);
  auto idToSymbol = invertMap(symbolToId);

  // Collect all nodes for encoding
  std::vector<std::string> nodeList;
  for (const auto &edge : rawEdges) {
    nodeList.push_back(std::get<0>(edge));
    nodeList.push_back(std::get<2>(edge));
  }

  auto nodeToId = assignIDs(nodeList);
  auto idToNode = invertMap(nodeToId);

  // Build grammars
  std::vector<Grammar> grammars;
  for (auto &rawGrammar : rawGrammars) {
    Grammar gm;

    // Classify symbols as terminals/nonterminals
    for (const auto &rule : rawGrammar) {
      for (const auto &symbol : rule) {
        if (isupper(symbol[0])) {
          gm.addNonterminal(symbolToId[symbol]);
        } else {
          assert(islower(symbol[0]));
          gm.addTerminal(symbolToId[symbol]);
        }
      }
    }

    // Add productions
    size_t ruleCount = rawGrammar.size();
    for (size_t i = 1; i < ruleCount; ++i) {
      if (rawGrammar[i].size() == 1) {
        gm.addEmptyProduction(symbolToId[rawGrammar[i][0]]);
      } else if (rawGrammar[i].size() == 2) {
        gm.addUnaryProduction(symbolToId[rawGrammar[i][0]],
                              symbolToId[rawGrammar[i][1]]);
      } else {
        assert(rawGrammar[i].size() == 3);
        gm.addBinaryProduction(symbolToId[rawGrammar[i][0]],
                               symbolToId[rawGrammar[i][1]],
                               symbolToId[rawGrammar[i][2]]);
      }
    }

    // Set start symbol
    gm.addStartSymbol(symbolToId[rawGrammar[0][0]]);
    gm.initFastIndices();
    grammars.push_back(std::move(gm));
  }

  // Build encoded edge set
  size_t nodeCount = nodeToId.size();
  std::unordered_set<Edge, EdgeHasher> encodedEdges;
  for (const auto &rawEdge : rawEdges) {
    encodedEdges.insert(std::make_tuple(nodeToId[std::get<0>(rawEdge)],
                                        symbolToId[std::get<1>(rawEdge)],
                                        nodeToId[std::get<2>(rawEdge)]));
  }

  return std::make_tuple(std::move(grammars), nodeCount, std::move(encodedEdges));
}

// Main execution logic based on mode
void execute(int argc, char *argv[]) {
  if (argc != 4) {
    std::cerr << "Usage: " << argv[0]
              << " <grammar-file> <graph-file> <\"naive\"/\"refine\">"
              << '\n';
    return;
  }

  std::string grammarPath = argv[1];
  std::string graphPath = argv[2];
  std::string strategy = argv[3];

  auto encodedData = encodeData(loadRawGrammars(grammarPath), loadRawGraph(graphPath));
  const std::vector<Grammar> &grammars = std::get<0>(encodedData);
  size_t nodeCount = std::get<1>(encodedData);
  const std::unordered_set<Edge, EdgeHasher> &edges = std::get<2>(encodedData);
  size_t grammarCount = grammars.size();

  if (strategy == "naive") {
    std::vector<Graph> graphs(grammarCount);
    std::vector<std::unordered_set<Edge, EdgeHasher>> results(grammarCount);

    for (size_t i = 0; i < grammarCount; ++i) {
      graphs[i].reinit(nodeCount, edges);
      results[i] = graphs[i].runCFLReachability(grammars[i]);
    }

    std::cout << "Number of Reachable Pairs (Excluding Self-loops): "
              << intersectResults(results).size() << '\n';
  } 
  else if (strategy == "refine") {
    std::unordered_set<Edge, EdgeHasher> edgeSet = edges;
    size_t initialSize = edgeSet.size();
    std::unordered_set<Edge, EdgeHasher>::size_type lastSize;
    std::vector<Graph> graphs(grammarCount);
    std::vector<std::unordered_set<Edge, EdgeHasher>> results(grammarCount);
    size_t iterationCount = 0;

    do {
      lastSize = edgeSet.size();
      for (size_t i = 0; i < grammarCount; ++i) {
        graphs[i].reinit(nodeCount, edgeSet);
        std::unordered_map<Edge, std::unordered_set<int>, EdgeHasher>
            singleRecord;
        std::unordered_map<
            Edge,
            std::unordered_set<std::tuple<int, int, int>, IntTripleHasher>,
            EdgeHasher>
            binaryRecord;

        results[i] = graphs[i].runCFLReachability(grammars[i], singleRecord,
                                                  binaryRecord);
        edgeSet = graphs[i].getEdgeClosure(grammars[i], results[i],
                                           singleRecord, binaryRecord);
      }
      iterationCount++;
    } while (edgeSet.size() != lastSize);

    size_t finalSize = edgeSet.size();
    std::cout << "Edge Set Reduction: " << initialSize << " -> "
              << finalSize << '\n';
    std::cout << "Number of Refinement Iterations: " << iterationCount
              << '\n';
    std::cout << "Number of Reachable Pairs (Excluding Self-loops): "
              << intersectResults(results).size() << '\n';
  }
}

// Read peak memory usage from /proc/self/status
std::string getPeakMemoryUsage() {
  std::ifstream status("/proc/self/status");
  std::string line;
  std::string peakValue;

  while (std::getline(status, line)) {
    std::istringstream stream(line);
    std::string tag;
    stream >> tag;
    if (tag == "VmPeak:") {
      stream >> peakValue;
      break;
    }
  }

  return peakValue;
}

// Entry point with timing and memory reporting
int mutual_refinement_main(int argc, char *argv[]) {
  auto startTime = std::chrono::steady_clock::now();
  execute(argc, argv);
  auto endTime = std::chrono::steady_clock::now();

  std::chrono::duration<double> duration = endTime - startTime;
  std::cout << "*** Resource Consumption ***" << '\n'
            << "Total Time (Seconds): " << duration.count() << '\n'
            << "Peak Space (kB): " << getPeakMemoryUsage() << '\n';

  return 0;
}

#include <iostream>
using std::cin;
using std::cout;
using std::abs;
namespace helpers {
    int greatestCommonDivisor(int x, int y) {
        return y == 0 ? x : greatestCommonDivisor(y, x % y);
    }
}
struct Fraction {
    int top;
    int bottom;
};
void simplifyFraction(Fraction& fraction) {
    int commonFactor = helpers::greatestCommonDivisor(fraction.bottom, fraction.top);
    fraction.top /= commonFactor;
    fraction.bottom /= commonFactor;
}
Fraction sumFractions(const Fraction& f1, const Fraction& f2) {
    int newBottom = f1.bottom * f2.bottom;
    int newTop = f1.top * f2.bottom + f1.bottom * f2.top;
    Fraction result { newTop, newBottom };
    simplifyFraction(result);
    return result;
}
Fraction differenceFractions(const Fraction& f1, const Fraction& f2) {
    int newBottom = f1.bottom * f2.bottom;
    int newTop = f1.top * f2.bottom - f1.bottom * f2.top;
    Fraction result { newTop, newBottom };
    simplifyFraction(result);
    return result;
}
Fraction productFractions(const Fraction& f1, const Fraction& f2) {
    Fraction result = { f1.top * f2.top, f1.bottom * f2.bottom };
    simplifyFraction(result);
    return result;
}
Fraction quotientFractions(const Fraction& f1, const Fraction& f2) {
    Fraction invertedF2 { f2.bottom, f2.top };
    return productFractions(f1, invertedF2);
}
bool isProperFraction(const Fraction& fraction) {
    return fraction.bottom != 0;
}
bool isInteger(const Fraction& fraction) {
    return fraction.top % fraction.bottom == 0;
}
void displayFraction(const Fraction& fraction) {
    bool isBottomNegative = fraction.bottom < 0;
    bool isTopNegative = fraction.top < 0;
    bool overallNegative = !(isBottomNegative && isTopNegative) && (isBottomNegative || isTopNegative);
    cout << (overallNegative ? "-(" : "") << abs(fraction.top) << "/" << abs(fraction.bottom) << (overallNegative ? ")" : "") << '\n';
}
int main() {
    Fraction first{ 1, 2 };
    Fraction second = { 3, 4 };
    displayFraction(sumFractions(first, second)); // 5/4
    displayFraction(differenceFractions(first, second)); // -(1/4)
    displayFraction(productFractions(first, second)); // 3/8 
    displayFraction(quotientFractions(first, second)); // 2/3
    displayFraction({-1, -2}); // 1/2
}

#include "wndproc.hpp"

memory::hooks::WndProc* memory::hooks::WndProc::_singleton = nullptr;

memory::hooks::WndProc::WndProc(HWND windowHandle) : Hook("WndProc", nullptr, nullptr, nullptr)
{
    _singleton = this;
    _windowHandle = windowHandle;
}

memory::hooks::WndProc::~WndProc()
{
    disable(false);
    if (_singleton == this)
    {
        _singleton = nullptr;
    }
}

bool memory::hooks::WndProc::activate()
{
    _previousWndProc = reinterpret_cast<WNDPROC>(SetWindowLongPtr(
        _windowHandle,
        GWLP_WNDPROC,
        reinterpret_cast<LONG_PTR>(hookedWndProc)
    ));
    if (!_previousWndProc)
    {
        return false;
    }
    return true;
}

bool memory::hooks::WndProc::deactivate(bool cleanup)
{
    SetWindowLongPtr(_windowHandle, GWLP_WNDPROC, reinterpret_cast<LONG_PTR>(_previousWndProc));
    return true;
}

void memory::hooks::WndProc::registerCallback(const std::function<uintptr_t(HWND, UINT, WPARAM, LPARAM)>& func)
{
    _callbackList.push_back(func);
}

LRESULT memory::hooks::WndProc::processMessage(HWND hWnd, const UINT message, const WPARAM wparam, const LPARAM lparam) const
{
    bool proceedWithDefault = true;
    for (const auto& handler : _callbackList)
    {
        if (handler(hWnd, message, wparam, lparam) == 0)
        {
            proceedWithDefault = false;
        }
    }
    if (!proceedWithDefault)
    {
        return 0;
    }
    return CallWindowProc(_previousWndProc, hWnd, message, wparam, lparam);
}

LRESULT memory::hooks::WndProc::hookedWndProc(HWND hWnd, const UINT msg, const WPARAM wParam, const LPARAM lParam)
{
    if (!_singleton)
    {
        return 0;
    }
    return _singleton->processMessage(hWnd, msg, wParam, lParam);
}

