std::vector<std::string> StrUtils::readFile(std::istream& input, char marker)
{
  std::string buffer;
  std::vector<std::string> result(0);
  while (getline(input, buffer))
  {
    if (buffer.length() > 0) result.push_back(extractBefore(buffer, marker));
    buffer.clear();
  }
  return result;
}

std::vector<std::string> StrUtils::splitIntoLines(const std::string& source)
{
  int start = 0;
  std::vector<std::string> result;
  const unsigned int size = source.length();
  for (unsigned int index=0; index<size; ++index) {
    const bool isLastChar = index==size-1;
    if( source[index]=='\n' || source[index]=='\0' || source[index]=='\r' || isLastChar )
    {
      if (index-start > 1)
        result.push_back(
          extractSubstring( source, start, index+(isLastChar?(source[size-1]=='\n'?0:1):0) )
          );
      start = index+1;
    }
  }
  return result;
}

std::vector<std::vector<std::string> > StrUtils::tokenizeFile(std::istream& input, char marker)
{
  std::string buffer;
  std::vector<std::vector<std::string> > result(0);
  std::vector<std::string> lines = readFile(input, marker);
  result.reserve(lines.size());
  int counter = 0;
  for (unsigned int i=0; i<lines.size(); i++)
  {
    if (lines[i].length() == 0) continue;
    std::vector<std::string> tokens = parseTokens(lines[i]);
    if (tokens.size() == 0) continue;
    result.push_back(tokens);
    counter++;
  }
  return result;
}

bool StrUtils::getline(std::istream& input, std::string& line)
{
  char buffer[500];
  if (line.length() > 0) line[0] = '\0';
  if (input.eof()) return false;
  if (input.getline(buffer, 499))
  {
    line = std::string(buffer);
  }
  return true;
}

std::vector<std::string> StrUtils::getTokensPlusWhitespace(const std::string& text){
  std::vector<std::string> result(0);
  unsigned int position = 0;
  while(position < text.length())
  {
    unsigned int wordStart =  locateNextNonWhitespace(text, position);
    /* add any preceding whitespace */
    if (wordStart > position)
    {
      result.push_back(extractSubstring(text, position, wordStart));
    }
    position = wordStart;
    /* add the next word */
    int stop = locateNextWhitespace(text, position);
    if (position-stop == 0) return result;
    std::string segment = extractSubstring(text, position, stop);
    result.push_back(segment);
    position = stop;
  }
  return result;
}

std::vector<std::string> StrUtils::parseTokens(const std::string& text){
  std::vector<std::string> result(0);
  unsigned int position = 0;
  while(position < text.length())
  {
    position =  locateNextNonWhitespace(text, position);
    int stop = locateNextWhitespace(text, position);
    if (position-stop == 0) return result;
    std::string segment = extractSubstring(text, position, stop);
    result.push_back(segment);
    position =  locateNextNonWhitespace(text, stop);
  }
  return result;
}

std::string StrUtils::reassembleFromTokens(const std::vector<std::string>& tokens,
  int startIndex)
{
  std::string result;
  for (unsigned int i=startIndex; i<tokens.size(); i++)
  {
    result += tokens[i];
    if (i < (tokens.size()-1)) result += " ";
  }
  return result;
}

void StrUtils::splitList(const std::string& input, std::vector<std::string>& output)
{
  if (extractSubstring(input, 0,1)!="[")
  {
    output.resize(1);
    output[0] = input;
    return;
  }
  int bracketDepth = 0;
  int localIndex = 0;
  std::string temp(input);
  output.resize(0);
  // start at 1 to ignore '[';
  for (unsigned int i=1; i<input.length(); i++)
  {
    if (input[i]=='(') bracketDepth++;
    if (input[i]==')') bracketDepth--;
    if (input[i]==']')
    {
      temp[localIndex]='\0';
      output.push_back(temp);
      break;
    }
    if (input[i]==',' && bracketDepth==0)
    {
      temp[localIndex]='\0';
      output.push_back(temp);
      temp = input;
      localIndex = 0;
      continue;
    }
    temp[localIndex] = input[i];
    localIndex++;
  }
}

// return the position of the next whitespace in a std::string.
// If no whitespace, return -1;
int StrUtils::locateNextWhitespace(const std::string& text, int offset)
{
  for (unsigned int i=0; i<(text.length()-offset); i++)
  {
    if (text[i+offset]==' ' || text[i+offset]=='\t' || text[i+offset]=='\n')
    {
      return i+offset;
    }
  }
  return text.length();
}

int StrUtils::locateNextNonWhitespace(const std::string& text, int offset)
{
  for (unsigned int i=0; i<(text.length()-offset); i++)
  {
    if (!(text[i+offset]==' ' || text[i+offset]=='\t' || text[i+offset]=='\n'))
    {
      return i+offset;
    }
  }
  return text.length();
}

std::string StrUtils::varTableSubstitute(const std::string& rawLine,
  const std::vector<std::string>& varNames,
  const std::vector<std::string>& varValues)
{
  TEUCHOS_TEST_FOR_EXCEPTION(varNames.size() != varValues.size(),
    std::runtime_error,
    "mismatched variable tables in varTableSubstitute");
  std::string line = rawLine;
  for (unsigned int i=0; i<varNames.size(); i++)
  {
    line = varSubstitute(line, varNames[i], varValues[i]);
  }
  return line;
}

std::string StrUtils::varSubstitute(const std::string& rawLine,
  const std::string& varName,
  const std::string& varValue)
{
  std::string line = rawLine;
  // iterate because there might be more than one occurrence on this line
  while (locate(line, varName) >= 0)
  {
    std::string b = extractBefore(line, varName);
    std::string a = extractAfter(line, varName);
    line = b + varValue + a;
  }
  return line;
}

std::string StrUtils::extractBefore(const std::string& text, char delimiter)
{
  char c[2];
  c[0] = delimiter;
  c[1] = 0;
  return extractBefore(text, c);
}

std::string StrUtils::extractBefore(const std::string& text, const std::string& delimiter)
{
  TEUCHOS_TEST_FOR_EXCEPTION(delimiter.c_str()==0,
    std::runtime_error, "String::before: arg is null pointer");
  char* pos = std::strstr((char*) text.c_str(), (char*) delimiter.c_str());
  if (pos==0) return text;
  int delimiterLen = pos-text.c_str();
  std::string result(text.c_str(), delimiterLen);
  return result;
}

std::string StrUtils::extractAfter(const std::string& text, const std::string& delimiter)
{
  TEUCHOS_TEST_FOR_EXCEPTION(delimiter.c_str()==0,
    std::runtime_error, "String::after: arg is null pointer");
  // find beginning of substring
  char* pos = std::strstr((char*) text.c_str(), (char*) delimiter.c_str()) ;
  // if substring not found, return empty std::string
  if (pos==0) return std::string();
  // offset to end of substring
  pos+= std::strlen(delimiter.c_str());
  return std::string(pos);
}

int StrUtils::locate(const std::string& text, const std::string& delimiter)
{
  char* pos = std::strstr((char*) text.c_str(), (char*) delimiter.c_str());
  if (pos==0) return -1;
  return pos-text.c_str();
}

bool StrUtils::isWhitespace(const std::string& text)
{
  for (unsigned int i=0; i<text.length(); i++)
  {
    unsigned char c = text[i];
    if (c >= 33 && c <= 126)
    {
      return false;
    }
  }
  return true;
}

std::string StrUtils::fixUnprintableCharacters(const std::string& text)
{
  std::string result = text;
  for (unsigned int i=0; i<result.length(); i++)
  {
    unsigned char c = result[i];
    if (c < 33 || c > 126)
    {
      if (c != '\t' && c != '\n'&& c != '\r' && c != '\f' && c != ' ')
      {
        result[i] = ' ';
      }
    }
  }
  return result;
}

std::string StrUtils::between(const std::string& text, const std::string& beginMarker,
  const std::string& endMarker, std::string& prefix,
  std::string& suffix)
{
  prefix = extractBefore(text, beginMarker);
  std::string middle = extractBefore(extractAfter(text, beginMarker), endMarker);
  suffix = extractAfter(text, endMarker);
  return middle;
}

std::string StrUtils::extractSubstring(const std::string& text, int start, int end)
{
  return std::string(text.c_str()+start, end-start);
}

