std::ostream& StrUtils::printLines(
  std::ostream             &output
  ,const std::string       &prefix
  ,const std::string       &content
  )
{
  std::vector<std::string> linesArray = splitIntoLines(content);
  for(unsigned int i = 0; i < linesArray.size(); ++i )
  {
    output << prefix << linesArray[i] << "\n";
  }
  return output;
}

std::string StrUtils::removeAllSpaces(std::string input)
{
  std::string::size_type pos=0;
  bool spacesLeft = true;
  while(spacesLeft){
    pos = input.find(" ");
    if(pos != std::string::npos){
      input.erase(pos,1);
    }
    else{
      spacesLeft = false;
    }
  }
  return input;
}

