    void checkForDuplicateNames(const util::ShapeSet & pathSet, unsigned int depthToStrip)
    {
        std::map<std::string, MDagPath> rootMap;
        const util::ShapeSet::const_iterator endIter = pathSet.end();
        for (util::ShapeSet::const_iterator iter = pathSet.begin();
            iter != endIter; ++iter)
        {
            std::string fullPath = iter->fullPathName().asChar();
            if (!fullPath.empty() && fullPath[0] == '|')
            {
                fullPath = fullPath.substr(1);
            }
            if (depthToStrip > 0)
            {
                MString nameStr = fullPath.c_str();
                fullPath = util::stripNamespaces(nameStr, depthToStrip).asChar();
            }
            std::map<std::string, MDagPath>::iterator foundIter =
                rootMap.find(fullPath);
            if (foundIter != rootMap.end())
            {
                std::string errorMsg = "Duplicate root node names detected: ";
                errorMsg += iter->fullPathName().asChar();
                errorMsg += " and ";
                errorMsg += foundIter->second.fullPathName().asChar();
                if (depthToStrip > 0)
                {
                    errorMsg += " due to -stripNamespace option.";
                }
                throw std::runtime_error(errorMsg);
            }
            else
            {
                rootMap[fullPath] = *iter;
            }
        }
    }

