    void executeCallback(std::string callbackStr, bool isMelScript,
        double frameNum, const MBoundingBox & bounds)
    {
        if (callbackStr.empty())
            return;

        size_t pos = callbackStr.find("#FRAME#");
        if (pos != std::string::npos)
        {
            std::stringstream sstrm;
            sstrm.precision(std::numeric_limits<double>::digits10);
            sstrm << frameNum;
            std::string strVal = sstrm.str();
            callbackStr.replace(pos, 7, strVal);
        }

        pos = callbackStr.find("#BOUNDS#");
        if (pos != std::string::npos)
        {
            std::stringstream sstrm;
            sstrm.precision(std::numeric_limits<float>::digits10);
            sstrm << " " << bounds.min().x << " " << bounds.min().y << " " <<
                bounds.min().z << " " << bounds.max().x << " " <<
                bounds.max().y << " " << bounds.max().z;
            std::string strVal = sstrm.str();
            callbackStr.replace(pos, 8, strVal);
        }

        pos = callbackStr.find("#BOUNDSARRAY#");
        if (pos != std::string::npos)
        {
            std::stringstream sstrm;
            sstrm.precision(std::numeric_limits<float>::digits10);
            if (isMelScript)
            {
                sstrm << " {";
            }
            else
            {
                sstrm << " [";
            }
            sstrm << bounds.min().x << "," << bounds.min().y << "," <<
                bounds.min().z << "," << bounds.max().x << "," <<
                bounds.max().y << "," << bounds.max().z;
            if (isMelScript)
            {
                sstrm << "} ";
            }
            else
            {
                sstrm << "] ";
            }
            std::string strVal = sstrm.str();
            callbackStr.replace(pos, 13, strVal);
        }

        if (isMelScript)
            MGlobal::executeCommand(callbackStr.c_str(), true);
        else
            MGlobal::executePythonCommand(callbackStr.c_str(), true);
    }
