IntWidth ToWidth(const Type& ty)
{
    switch (ty.GetTypeKind()) {
        case Type::TypeKind::TYPE_INT8:
        case Type::TypeKind::TYPE_UINT8:
            return IntWidth::I8;
        case Type::TypeKind::TYPE_INT16:
        case Type::TypeKind::TYPE_UINT16:
            return IntWidth::I16;
        case Type::TypeKind::TYPE_INT32:
        case Type::TypeKind::TYPE_UINT32:
            return IntWidth::I32;
        default:
            return IntWidth::I64;
    }
}

static unsigned ExtractDigit(char ch, Radix base)
{
    unsigned result;
    constexpr unsigned offset11 = 11u;
    constexpr unsigned offsetAdd = static_cast<unsigned>(Radix::R10);

    if (base == Radix::R16) {
        result = static_cast<unsigned int>(ch) - static_cast<unsigned int>('0');
        if (result < Radix::R10) {
            return result;
        }
        result = static_cast<unsigned int>(ch) - static_cast<unsigned int>('A');
        if (result <= base - offset11) {
            return result + offsetAdd;
        }
        result = static_cast<unsigned int>(ch) - static_cast<unsigned int>('a');
        if (result <= base - offset11) {
            return result + offsetAdd;
        }
        base = Radix::R10;
    }

    result = static_cast<unsigned int>(ch) - static_cast<unsigned int>('0');
    if (result < static_cast<unsigned>(base)) {
        return result;
    }
    return 0xFFFFFFFFU;
}

