}

void SInt::AShrInPlace(unsigned count)
{
    CJC_ASSERT(count <= bitWidth);
    int64_t sextVal = SignExtend64(value, bitWidth);
    if (count == bitWidth) {
        value = static_cast<uint64_t>(sextVal >> (BITS_PER_WORD - 1));
    } else {
        value = static_cast<uint64_t>(sextVal >> count);
    }
    ClearUnusedBits();
}

SInt SInt::LShr(unsigned count) const
{
    SInt result{*this};
    result.LShrInPlace(count);
    return result;
}

void SInt::LShrInPlace(unsigned count)
{
    CJC_ASSERT(count <= bitWidth);
    value = count == bitWidth ? 0 : value >> count;
}

SInt SInt::Ashr(const SInt& count) const
{
    SInt result{*this};
    result.AShrInPlace(static_cast<unsigned>(count.value));
    return result;
