    result.LShrInPlace(count);
    return result;
}

void SInt::LShrInPlace(const SInt& count)
{
    return LShrInPlace(static_cast<unsigned>(count.GetULimitedValue(bitWidth)));
}

SInt SInt::Shl(unsigned count) const
{
    SInt result{*this};
    result <<= count;
    return result;
}

SInt SInt::Shl(const SInt& count) const
{
    SInt result{*this};
    result <<= count;
    return result;
}

SInt SInt::Concat(const SInt& v) const
{
    unsigned nw = bitWidth + v.bitWidth;
    switch (nw) {
        case IntWidth::I8:
        case IntWidth::I16:
        case IntWidth::I32:
        case IntWidth::I64:
            break;
        default:
            CJC_ABORT();
            break;
    }
    return {FromUnsigned(nw), (value << v.bitWidth) | v.value};
}

