    ClearUnusedBits();
}

void SInt::SetBit(unsigned pos)
{
    CJC_ASSERT(pos < bitWidth);
    value |= MaskBit(pos);
}

void SInt::SetBits(unsigned lo, unsigned hi)
{
    CJC_ASSERT(lo <= hi);
    CJC_ASSERT(hi <= bitWidth);
    if (lo == hi) {
        return;
    }
    WordType mask = WORD_TYPE_MAX >> (BITS_PER_WORD - hi + lo);
    mask <<= lo;
    value |= mask;
}

void SInt::SetLowBits(unsigned count)
{
    SetBits(0, count);
}

void SInt::SetHighBits(unsigned count)
{
    SetBits(bitWidth - count, bitWidth);
