}

void SInt::FlipAllBits()
{
    value ^= WORD_TYPE_MAX;
    ClearUnusedBits();
}

void SInt::Neg()
{
    FlipAllBits();
    ++*this;
}

unsigned SInt::ActiveBits() const
{
