SInt& SInt::ClearUnusedBits()
{
    CJC_ASSERT(bitWidth > 0);
    unsigned wordBits = (bitWidth - 1) % BITS_PER_WORD + 1;
    uint64_t mask = WORD_TYPE_MAX >> (BITS_PER_WORD - wordBits);
    value &= mask;
    return *this;
}

void SInt::FromString(const std::string& str, Radix base)
{
    size_t slen = str.size();
    auto p = str.begin();
    bool isNegative = *p == '-';
    if (*p == '-' || *p == '+') {
        ++p;
        --slen;
        CJC_ASSERT(slen != 0);
    }
    value = 0;
    unsigned shift = base == Radix::R16 ? 4 : base == Radix::R2 ? 1 : 0;
    for (auto e = str.end(); p != e; ++p) {
        unsigned digit = ExtractDigit(*p, base);
        CJC_ASSERT(digit < static_cast<unsigned>(base));
        if (slen > 1) {
            if (shift != 0) {
                value <<= shift;
            } else {
                value *= base;
            }
        }
        value += digit;
    }
    if (isNegative) {
        Neg();
    }
}

decltype(std::setbase(0)) SIntFormatterBase::GetBaseManip() const
{
    if (radix == Radix::R2) {
        CJC_ABORT();
    }
    return std::setbase(static_cast<int>(radix));
}

std::ostream& operator<<(std::ostream& out, const SInt::Formatter& fmt)
{
    out << fmt.GetBaseManip();
    if ((out.flags() & std::ios_base::basefield) == std::ios_base::hex) {
        out << std::showbase;
    }
    if (fmt.asUnsigned) {
        return out << fmt.value.UVal();
    }
    return out << fmt.value.SVal();
}

SInt SInt::UDiv(const SInt& rhs) const
{
    CJC_ASSERT(bitWidth == rhs.bitWidth);
    return UDiv(rhs.value);
}

SInt SInt::UDiv(uint64_t rhs) const
{
    CJC_ASSERT(rhs != 0);
    return {bitWidth, value / rhs};
}

SInt SInt::SDiv(const SInt& rhs) const
{
    CJC_ASSERT(bitWidth == rhs.bitWidth);
    if (IsNeg()) {
        if (rhs.IsNeg()) {
            return (-*this).UDiv(-rhs);
        }
        return -(-*this).UDiv(rhs);
    }
    if (rhs.IsNeg()) {
        return -UDiv(-rhs);
    }
    return UDiv(rhs);
}

SInt SInt::SDiv(int64_t rhs) const
{
    CJC_ASSERT(rhs != 0);
    if (IsNeg()) {
        if (rhs < 0) {
            return (-*this).UDiv(static_cast<uint64_t>(-rhs));
        }
        return -(-*this).UDiv(static_cast<uint64_t>(rhs));
    }
    if (rhs < 0) {
        return -UDiv(static_cast<uint64_t>(-rhs));
    }
    return UDiv(static_cast<uint64_t>(rhs));
}

SInt SInt::URem(const SInt& rhs) const
{
