SInt SInt::SRem(const SInt& rhs) const
{
    CJC_ASSERT(bitWidth == rhs.bitWidth);
    if (IsNeg()) {
        if (rhs.IsNeg()) {
            return -(-*this).URem(-rhs);
        }
        return -(-*this).URem(rhs);
    }
    if (rhs.IsNeg()) {
        return URem(-rhs);
    }
    return URem(rhs);
}

SInt SInt::SRem(int64_t rhs) const
{
    CJC_ASSERT(rhs != 0);
    if (IsNeg()) {
        if (rhs < 0) {
            return -(-*this).URem(static_cast<uint64_t>(-rhs));
