#include <llarp/path/path.hpp>
#include <catch2/catch.hpp>

using PathType   = llarp::path::Path;
using Path_sp    = llarp::path::Path_ptr;
using EndpointSet = llarp::path::Path::UniqueEndpointSet_t;
using RelayContact = llarp::RelayContact;

static RelayContact
GenerateHop(char label)
{
  RelayContact hop;
  hop.pubkey.Fill(label);
  return hop;
}

static Path_sp
BuildPath(std::vector< char > hopLabels)
{
  std::vector< RelayContact > hopList;
  for(const auto& hopLabel : hopLabels)
    hopList.push_back(GenerateHop(hopLabel));
  return std::make_shared< PathType >(hopList, std::weak_ptr<llarp::path::PathSet>{}, 0, "example");
}

TEST_CASE("EndpointSet contains only distinct endpoints", "[path]")
{
  EndpointSet collection;
  REQUIRE(collection.empty());

  const bool firstInsert =
      collection.emplace(BuildPath({'x', 'y', 'z', 'w'})).second;
  REQUIRE(firstInsert);

  const bool duplicateInsert =
      collection.emplace(BuildPath({'x', 'y', 'z', 'w'})).second;
  REQUIRE(not duplicateInsert);

  const bool reverseInsert =
      collection.emplace(BuildPath({'w', 'z', 'y', 'x'})).second;
  REQUIRE(reverseInsert);
}

