using namespace gte;

// Destructor for ETManifoldMesh
ETManifoldMesh::~ETManifoldMesh()
{
}

// Constructor with custom creators
ETManifoldMesh::ETManifoldMesh(ECreator eCreator, TCreator tCreator)
    :
    mECreator(eCreator ? eCreator : CreateEdge),
    mTCreator(tCreator ? tCreator : CreateTriangle),
    mAssertOnNonmanifoldInsertion(true)
{
}

// Copy constructor
ETManifoldMesh::ETManifoldMesh(ETManifoldMesh const& mesh)
{
    *this = mesh;
}

// Assignment operator
ETManifoldMesh& ETManifoldMesh::operator=(ETManifoldMesh const& mesh)
{
    Clear();
    mECreator = mesh.mECreator;
    mTCreator = mesh.mTCreator;
    mAssertOnNonmanifoldInsertion = mesh.mAssertOnNonmanifoldInsertion;
    for (auto const& element : mesh.mTMap)
    {
        Insert(element.first.V[0], element.first.V[1], element.first.V[2]);
    }
    return *this;
}

// Get edges map (const reference)
ETManifoldMesh::EMap const& ETManifoldMesh::GetEdges() const
{
    return mEMap;
}

// Get triangles map (const reference)
ETManifoldMesh::TMap const& ETManifoldMesh::GetTriangles() const
{
    return mTMap;
}

// Toggle assertion flag for non-manifold insertions
bool ETManifoldMesh::AssertOnNonmanifoldInsertion(bool doAssert)
{
    std::swap(doAssert, mAssertOnNonmanifoldInsertion);
    return doAssert;  // return the previous state
}

// Insert a triangle into the mesh
std::shared_ptr<ETManifoldMesh::Triangle> ETManifoldMesh::Insert(int v0, int v1, int v2)
{
    TriangleKey<true> tkey(v0, v1, v2);
    if (mTMap.find(tkey) != mTMap.end())
    {
        // The triangle already exists. Return null pointer to signal failure.
        return nullptr;
    }

    // Create new triangle
    std::shared_ptr<Triangle> tri = mTCreator(v0, v1, v2);

    // Add edges to the mesh if they do not already exist
    for (int i0 = 2, i1 = 0; i1 < 3; i0 = i1++)
    {
        EdgeKey<false> ekey(tri->V[i0], tri->V[i1]);
        std::shared_ptr<Edge> edge;
        auto eiter = mEMap.find(ekey);
        if (eiter == mEMap.end())
        {
            // First occurrence of this edge
            edge = mECreator(tri->V[i0], tri->V[i1]);
            mEMap[ekey] = edge;
            edge->T[0] = tri;
            tri->E[i0] = edge;
        }
        else
        {
            // Second occurrence of this edge
            edge = eiter->second;
            if (!edge)
            {
                LogError("Unexpected condition.");
                return nullptr;
            }

            if (edge->T[1].lock())
            {
                if (mAssertOnNonmanifoldInsertion)
                {
                    LogInformation("The mesh must be manifold.");
                }
                return nullptr;
            }

            edge->T[1] = tri;

            // Update adjacent triangles
            auto adjacent = edge->T[0].lock();
            if (!adjacent)
            {
                LogError("Unexpected condition.");
                return nullptr;
            }

            for (int j = 0; j < 3; ++j)
            {
                if (adjacent->E[j].lock() == edge)
                {
                    adjacent->T[j] = tri;
                    break;
                }
            }

            tri->E[i0] = edge;
            tri->T[i0] = adjacent;
        }
    }

    mTMap[tkey] = tri;
    return tri;
}

// Remove a triangle from the mesh
bool ETManifoldMesh::Remove(int v0, int v1, int v2)
{
    TriangleKey<true> tkey(v0, v1, v2);
    auto titer = mTMap.find(tkey);
    if (titer == mTMap.end())
    {
        // Triangle does not exist
        return false;
    }

    std::shared_ptr<Triangle> tri = titer->second;

    // Remove edges and update adjacent triangles
    for (int i = 0; i < 3; ++i)
    {
        auto edge = tri->E[i].lock();
        if (!edge)
        {
            LogError("Unexpected condition.");
            return false;
        }

        if (edge->T[0].lock() == tri)
        {
            edge->T[0] = edge->T[1];
            edge->T[1].reset();
        }
        else if (edge->T[1].lock() == tri)
        {
            edge->T[1].reset();
        }
        else
        {
            LogError("Unexpected condition.");
            return false;
        }

        // Remove edge if no longer used
        if (!edge->T[0].lock() && !edge->T[1].lock())
        {
            EdgeKey<false> ekey(edge->V[0], edge->V[1]);
            mEMap.erase(ekey);
        }

        // Inform adjacent triangles
        auto adjacent = tri->T[i].lock();
        if (adjacent)
        {
            for (int j = 0; j < 3; ++j)
            {
                if (adjacent->T[j].lock() == tri)
                {
                    adjacent->T[j].reset();
                    break;
                }
            }
        }
    }

    mTMap.erase(tkey);
    return true;
}

// Clear all data
void ETManifoldMesh::Clear()
{
    mEMap.clear();
    mTMap.clear();
}

// Check if mesh is closed (every edge has two incident triangles)
bool ETManifoldMesh::IsClosed() const
{
    for (auto const& element : mEMap)
    {
        auto edge = element.second;
        if (!edge->T[0].lock() || !edge->T[1].lock())
        {
            return false;
        }
    }
    return true;
}

// Check if mesh is oriented (consistent triangle orientations)
bool ETManifoldMesh::IsOriented() const
{
    for (auto const& element : mEMap)
    {
        auto edge = element.second;
        if (edge->T[0].lock() && edge->T[1].lock())
        {
            bool edgePositive[2] = { false, false };
            int vOpposite[2] = { -1, -1 };

            for (int j = 0; j < 2; ++j)
            {
                auto tri = edge->T[j].lock();
                for (int i = 0; i < 3; ++i)
                {
                    if (tri->V[i] == element.first.V[0])
                    {
                        int vNext = tri->V[(i + 1) % 3];
                        if (vNext == element.first.V[1])
                        {
                            edgePositive[j] = true;
                            vOpposite[j] = tri->V[(i + 2) % 3];
                        }
                        else
                        {
                            edgePositive[j] = false;
                            vOpposite[j] = vNext;
                        }
                        break;
                    }
                }
            }

            if (edgePositive[0] == edgePositive[1] || vOpposite[0] == vOpposite[1])
            {
                return false;
            }
        }
    }
    return true;
}

// Get connected components using triangle pointers
void ETManifoldMesh::GetComponents(
    std::vector<std::vector<std::shared_ptr<Triangle>>>& components) const
{
    std::map<std::shared_ptr<Triangle>, int> visited;
    for (auto const& element : mTMap)
    {
        visited.insert(std::make_pair(element.second, 0));
    }

    for (auto& element : mTMap)
    {
        auto tri = element.second;
        if (visited[tri] == 0)
        {
            std::vector<std::shared_ptr<Triangle>> component;
            DepthFirstSearch(tri, visited, component);
            components.push_back(component);
        }
    }
}

// Get connected components using triangle keys
void ETManifoldMesh::GetComponents(
    std::vector<std::vector<TriangleKey<true>>>& components) const
{
    std::map<std::shared_ptr<Triangle>, int> visited;
    for (auto const& element : mTMap)
    {
        visited.insert(std::make_pair(element.second, 0));
    }

    for (auto& element : mTMap)
    {
        std::shared_ptr<Triangle> tri = element.second;
        if (visited[tri] == 0)
        {
            std::vector<std::shared_ptr<Triangle>> component;
            DepthFirstSearch(tri, visited, component);
            std::vector<TriangleKey<true>> keyComponent;
            keyComponent.reserve(component.size());
            for (auto const& t : component)
            {
                keyComponent.push_back(TriangleKey<true>(t->V[0], t->V[1], t->V[2]));
            }
            components.push_back(keyComponent);
        }
    }
}

// Depth-first search helper for component traversal
void ETManifoldMesh::DepthFirstSearch(std::shared_ptr<Triangle> const& tInitial,
    std::map<std::shared_ptr<Triangle>, int>& visited,
    std::vector<std::shared_ptr<Triangle>>& component) const
{
    std::vector<std::shared_ptr<Triangle>> tStack(mTMap.size());
    int top = -1;
    tStack[++top] = tInitial;

    while (top >= 0)
    {
        std::shared_ptr<Triangle> tri = tStack[top];
        visited[tri] = 1;
        int i;
        for (i = 0; i < 3; ++i)
        {
            std::shared_ptr<Triangle> adj = tri->T[i].lock();
            if (adj && visited[adj] == 0)
            {
                tStack[++top] = adj;
                break;
            }
        }
        if (i == 3)
        {
            visited[tri] = 2;
            component.push_back(tri);
            --top;
        }
    }
}

// Default edge creator
std::shared_ptr<ETManifoldMesh::Edge> ETManifoldMesh::CreateEdge(int v0, int v1)
{
    return std::make_shared<Edge>(v0, v1);
}

// Default triangle creator
std::shared_ptr<ETManifoldMesh::Triangle> ETManifoldMesh::CreateTriangle(int v0, int v1, int v2)
{
    return std::make_shared<Triangle>(v0, v1, v2);
}

// Edge destructor
ETManifoldMesh::Edge::~Edge()
{
}

// Edge constructor
ETManifoldMesh::Edge::Edge(int v0, int v1)
{
    V[0] = v0;
    V[1] = v1;
}

// Triangle destructor
ETManifoldMesh::Triangle::~Triangle()
{
}

// Triangle constructor
ETManifoldMesh::Triangle::Triangle(int v0, int v1, int v2)
{
    V[0] = v0;
    V[1] = v1;
    V[2] = v2;
}

#include <cmath>
// DDS
#include <unitree/robot/channel/channel_publisher.hpp>
#include <unitree/robot/channel/channel_subscriber.hpp>
// IDL
#include <unitree/idl/hg/LowCmd_.hpp>
#include <unitree/idl/hg/LowState_.hpp>

static const std::string COMMAND_CHANNEL = "rt/lowcmd";
static const std::string STATE_CHANNEL = "rt/lowstate";

using namespace unitree::common;
using namespace unitree::robot;

const int MOTOR_COUNT = 27;

enum ControlMode { POSITION_VELOCITY = 0, IMPEDANCE = 1 };

inline uint32_t CalculateCRC(uint32_t *buffer, uint32_t length) {
  uint32_t bitMask = 0;
  uint32_t inputValue = 0;
  uint32_t crcRegister = 0xFFFFFFFF;
  const uint32_t generator = 0x04c11db7;

  for (uint32_t i = 0; i < length; i++) {
    bitMask = 1 << 31;
    inputValue = buffer[i];
    for (uint32_t j = 0; j < 32; j++) {
      if (crcRegister & 0x80000000) {
        crcRegister <<= 1;
        crcRegister ^= generator;
      } else {
        crcRegister <<= 1;
      }
      if (inputValue & bitMask) {
        crcRegister ^= generator;
      }
      bitMask >>= 1;
    }
  }
  return crcRegister;
};

class HumanoidController {
 private:
  double simulationTime_;
  double controlPeriod_;  // [2ms]
  double transitionTime_; // [3 s]
  ControlMode actionMode_;
  unitree_hg::msg::dds_::LowState_ currentState_;
  ChannelPublisherPtr<unitree_hg::msg::dds_::LowCmd_> commandPublisher_;
  ChannelSubscriberPtr<unitree_hg::msg::dds_::LowState_> stateSubscriber_;
  ThreadPtr writerThread_, controllerThread_;

 public:
  HumanoidController(std::string networkInterface)
      : simulationTime_(0.0), controlPeriod_(0.002), transitionTime_(3.0), actionMode_(POSITION_VELOCITY) {
    ChannelFactory::Instance()->Init(0, networkInterface);

    // Initialize publisher
    commandPublisher_.reset(
        new ChannelPublisher<unitree_hg::msg::dds_::LowCmd_>(COMMAND_CHANNEL));
    commandPublisher_->InitChannel();

    // Initialize subscriber
    stateSubscriber_.reset(
        new ChannelSubscriber<unitree_hg::msg::dds_::LowState_>(
            STATE_CHANNEL));
    stateSubscriber_->InitChannel(
        std::bind(&HumanoidController::OnStateUpdate, this, std::placeholders::_1), 1);

    // Start control loop
    controllerThread_ = CreateRecurrentThreadEx(
        "controller", UT_CPU_ID_NONE, 2000, &HumanoidController::RunControl, this);
  }

  void OnStateUpdate(const void *data) {
    currentState_ = *(const unitree_hg::msg::dds_::LowState_ *)data;
    if (currentState_.crc() !=
        CalculateCRC((uint32_t *)&currentState_,
                  (sizeof(unitree_hg::msg::dds_::LowState_) >> 2) - 1)) {
      std::cout << "State message CRC mismatch detected" << std::endl;
      return;
    }
  }

  void RunControl() {
    unitree_hg::msg::dds_::LowCmd_ outgoingCommand;
    outgoingCommand.mode_pr() = actionMode_;
    outgoingCommand.mode_machine() = currentState_.mode_machine();

    for (int idx = 0; idx < MOTOR_COUNT; ++idx) {
      outgoingCommand.motor_cmd().at(idx).mode() = 1;  // 1:Enable, 0:Disable
      outgoingCommand.motor_cmd().at(idx).tau() = 0.0;
      outgoingCommand.motor_cmd().at(idx).q() = 0.0;
      outgoingCommand.motor_cmd().at(idx).dq() = 0.0;
      outgoingCommand.motor_cmd().at(idx).kp() = (idx < 13) ? 100.0 : 50.0;
      outgoingCommand.motor_cmd().at(idx).kd() = 1.0;
    }

    simulationTime_ += controlPeriod_;

    if (simulationTime_ < transitionTime_) {
      // [Phase 1]: Move to home position
      for (int idx = 0; idx < MOTOR_COUNT; ++idx) {
        double progress = std::clamp(simulationTime_ / transitionTime_, 0.0, 1.0);
        outgoingCommand.motor_cmd().at(idx).q() =
            (1.0 - progress) * currentState_.motor_state().at(idx).q();
      }
    } else {
      // [Phase 2]: Ankle oscillation in PR mode
      actionMode_ = POSITION_VELOCITY;  // Activate position-velocity mode

      // Generate sinusoidal trajectories
      double amplitudePitch = 0.25;   // [rad]
      double amplitudeRoll = 0.25;    // [rad]
      double elapsed = simulationTime_ - transitionTime_;

      double leftPitchTarget = amplitudePitch * std::cos(2.0 * M_PI * elapsed);
      double leftRollTarget = amplitudeRoll * std::sin(2.0 * M_PI * elapsed);
      double rightPitchTarget = amplitudePitch * std::cos(2.0 * M_PI * elapsed);
      double rightRollTarget = -amplitudeRoll * std::sin(2.0 * M_PI * elapsed);

      // Configure ankle joints
      float pitchGain = 80.0f;
      float pitchDamping = 1.0f;
      float rollGain = 80.0f;
      float rollDamping = 1.0f;

      // Left ankle
      outgoingCommand.motor_cmd().at(4).q() = leftPitchTarget;  // 4: LeftAnklePitch
      outgoingCommand.motor_cmd().at(4).dq() = 0.0f;
      outgoingCommand.motor_cmd().at(4).kp() = pitchGain;
      outgoingCommand.motor_cmd().at(4).kd() = pitchDamping;
      outgoingCommand.motor_cmd().at(4).tau() = 0.0f;

      outgoingCommand.motor_cmd().at(5).q() = leftRollTarget;   // 5: LeftAnkleRoll
      outgoingCommand.motor_cmd().at(5).dq() = 0.0f;
      outgoingCommand.motor_cmd().at(5).kp() = rollGain;
      outgoingCommand.motor_cmd().at(5).kd() = rollDamping;
      outgoingCommand.motor_cmd().at(5).tau() = 0.0f;

      // Right ankle
      outgoingCommand.motor_cmd().at(10).q() = rightPitchTarget; // 10: RightAnklePitch
      outgoingCommand.motor_cmd().at(10).dq() = 0.0f;
      outgoingCommand.motor_cmd().at(10).kp() = pitchGain;
      outgoingCommand.motor_cmd().at(10).kd() = pitchDamping;
      outgoingCommand.motor_cmd().at(10).tau() = 0.0f;

      outgoingCommand.motor_cmd().at(11).q() = rightRollTarget;  // 11: RightAnkleRoll
      outgoingCommand.motor_cmd().at(11).dq() = 0.0f;
      outgoingCommand.motor_cmd().at(11).kp() = rollGain;
      outgoingCommand.motor_cmd().at(11).kd() = rollDamping;
      outgoingCommand.motor_cmd().at(11).tau() = 0.0f;

      // Read current joint positions for logging
      float actualLeftPitch = currentState_.motor_state().at(4).q();
      float actualLeftRoll = currentState_.motor_state().at(5).q();
      float actualRightPitch = currentState_.motor_state().at(10).q();
      float actualRightRoll = currentState_.motor_state().at(11).q();

      // Output trajectory data
      printf("%f,%f,%f,%f,%f,%f,%f,%f\n",
             leftPitchTarget, actualLeftPitch,
             leftRollTarget, actualLeftRoll,
             rightPitchTarget, actualRightPitch,
             rightRollTarget, actualRightRoll);
    }

    // Compute and set CRC
    outgoingCommand.crc() = CalculateCRC((uint32_t *)&outgoingCommand,
                                        (sizeof(outgoingCommand) >> 2) - 1);
    commandPublisher_->Write(outgoingCommand);
  }
};

int main(int argc, char const *argv[]) {
  if (argc < 2) {
    std::cout << "Usage: h1_2_ankle_track network_interface_name" << std::endl;
    exit(0);
  }

  std::string interfaceName = argv[1];
  HumanoidController controller(interfaceName);

  while (true) sleep(10);
  return 0;
}

