#include "plutovg-private.h"
#include "plutovg-utils.h"
#include <assert.h>
#include <math.h>

// Initialize a path iterator to traverse the given path
void plutovg_path_iterator_init(plutovg_path_iterator_t* iter, const plutovg_path_t* p)
{
    iter->elements = p->elements.data;
    iter->size = p->elements.size;
    iter->index = 0;
}

// Check if there are more elements in the path
bool plutovg_path_iterator_has_next(const plutovg_path_iterator_t* iter)
{
    return iter->index < iter->size;
}

// Get the next command and its points from the path iterator
plutovg_path_command_t plutovg_path_iterator_next(plutovg_path_iterator_t* iter, plutovg_point_t pts[3])
{
    const plutovg_path_element_t* elts = iter->elements + iter->index;
    switch(elts[0].header.command) {
    case PLUTOVG_PATH_COMMAND_MOVE_TO:
    case PLUTOVG_PATH_COMMAND_LINE_TO:
    case PLUTOVG_PATH_COMMAND_CLOSE:
        pts[0] = elts[1].point;
        break;
    case PLUTOVG_PATH_COMMAND_CUBIC_TO:
        pts[0] = elts[1].point;
        pts[1] = elts[2].point;
        pts[2] = elts[3].point;
        break;
    }
    iter->index += elts[0].header.length;
    return elts[0].header.command;
}

// Create a new empty path
plutovg_path_t* plutovg_path_create(void)
{
    plutovg_path_t* p = malloc(sizeof(plutovg_path_t));
    plutovg_init_reference(p);
    p->num_points = 0;
    p->num_contours = 0;
    p->num_curves = 0;
    p->start_point = PLUTOVG_EMPTY_POINT;
    plutovg_array_init(p->elements);
    return p;
}

// Increment reference count for path
plutovg_path_t* plutovg_path_reference(plutovg_path_t* p)
{
    plutovg_increment_reference(p);
    return p;
}

// Destroy path when reference count reaches zero
void plutovg_path_destroy(plutovg_path_t* p)
{
    if(plutovg_destroy_reference(p)) {
        plutovg_array_destroy(p->elements);
        free(p);
    }
}

// Get current reference count of path
int plutovg_path_get_reference_count(const plutovg_path_t* p)
{
    return plutovg_get_reference_count(p);
}

// Get elements array and size
int plutovg_path_get_elements(const plutovg_path_t* p, const plutovg_path_element_t** elts)
{
    if(elts)
        *elts = p->elements.data;
    return p->elements.size;
}

// Internal function to add a command with specified number of points
static plutovg_path_element_t* plutovg_path_add_command(plutovg_path_t* p, plutovg_path_command_t cmd, int npoints)
{
    const int length = npoints + 1;
    plutovg_array_ensure(p->elements, length);
    plutovg_path_element_t* elts = p->elements.data + p->elements.size;
    elts->header.command = cmd;
    elts->header.length = length;
    p->elements.size += length;
    p->num_points += npoints;
    return elts + 1;
}

// Add a move-to command to path
void plutovg_path_move_to(plutovg_path_t* p, float x, float y)
{
    plutovg_path_element_t* elts = plutovg_path_add_command(p, PLUTOVG_PATH_COMMAND_MOVE_TO, 1);
    elts[0].point = PLUTOVG_MAKE_POINT(x, y);
    p->start_point = PLUTOVG_MAKE_POINT(x, y);
    p->num_contours += 1;
}

// Add a line-to command to path
void plutovg_path_line_to(plutovg_path_t* p, float x, float y)
{
    if(p->elements.size == 0)
        plutovg_path_move_to(p, 0, 0);
    plutovg_path_element_t* elts = plutovg_path_add_command(p, PLUTOVG_PATH_COMMAND_LINE_TO, 1);
    elts[0].point = PLUTOVG_MAKE_POINT(x, y);
}

// Add a quadratic bezier curve using conversion to cubic
void plutovg_path_quad_to(plutovg_path_t* p, float x1, float y1, float x2, float y2)
{
    float cx, cy;
    plutovg_path_get_current_point(p, &cx, &cy);
    float cp1x = 2.f / 3.f * x1 + 1.f / 3.f * cx;
    float cp1y = 2.f / 3.f * y1 + 1.f / 3.f * cy;
    float cp2x = 2.f / 3.f * x1 + 1.f / 3.f * x2;
    float cp2y = 2.f / 3.f * y1 + 1.f / 3.f * y2;
    plutovg_path_cubic_to(p, cp1x, cp1y, cp2x, cp2y, x2, y2);
}

// Add a cubic bezier curve to path
void plutovg_path_cubic_to(plutovg_path_t* p, float x1, float y1, float x2, float y2, float x3, float y3)
{
    if(p->elements.size == 0)
        plutovg_path_move_to(p, 0, 0);
    plutovg_path_element_t* elts = plutovg_path_add_command(p, PLUTOVG_PATH_COMMAND_CUBIC_TO, 3);
    elts[0].point = PLUTOVG_MAKE_POINT(x1, y1);
    elts[1].point = PLUTOVG_MAKE_POINT(x2, y2);
    elts[2].point = PLUTOVG_MAKE_POINT(x3, y3);
    p->num_curves += 1;
}

// Add an arc to path using approximation with cubic beziers
void plutovg_path_arc_to(plutovg_path_t* p, float rx, float ry, float angle, bool large_arc_flag, bool sweep_flag, float x, float y)
{
    float cx, cy;
    plutovg_path_get_current_point(p, &cx, &cy);
    if(rx == 0.f || ry == 0.f || (cx == x && cy == y)) {
        plutovg_path_line_to(p, x, y);
        return;
    }
    if(rx < 0.f) rx = -rx;
    if(ry < 0.f) ry = -ry;
    float dx = (cx - x) * 0.5f;
    float dy = (cy - y) * 0.5f;
    plutovg_matrix_t mtx;
    plutovg_matrix_init_rotate(&mtx, -angle);
    plutovg_matrix_map(&mtx, dx, dy, &dx, &dy);
    float rxrx = rx * rx;
    float ryry = ry * ry;
    float dxdx = dx * dx;
    float dydy = dy * dy;
    float radius = dxdx / rxrx + dydy / ryry;
    if(radius > 1.f) {
        rx *= sqrtf(radius);
        ry *= sqrtf(radius);
    }
    plutovg_matrix_init_scale(&mtx, 1.f / rx, 1.f / ry);
    plutovg_matrix_rotate(&mtx, -angle);
    float x1, y1;
    float x2, y2;
    plutovg_matrix_map(&mtx, cx, cy, &x1, &y1);
    plutovg_matrix_map(&mtx, x, y, &x2, &y2);
    float dx1 = x2 - x1;
    float dy1 = y2 - y1;
    float d = dx1 * dx1 + dy1 * dy1;
    float scale_sq = 1.f / d - 0.25f;
    if(scale_sq < 0.f) scale_sq = 0.f;
    float scale = sqrtf(scale_sq);
    if(sweep_flag == large_arc_flag)
        scale = -scale;
    dx1 *= scale;
    dy1 *= scale;
    float cx1 = 0.5f * (x1 + x2) - dy1;
    float cy1 = 0.5f * (y1 + y2) + dx1;
    float th1 = atan2f(y1 - cy1, x1 - cx1);
    float th2 = atan2f(y2 - cy1, x2 - cx1);
    float th_arc = th2 - th1;
    if(th_arc < 0.f && sweep_flag)
        th_arc += PLUTOVG_TWO_PI;
    else if(th_arc > 0.f && !sweep_flag)
        th_arc -= PLUTOVG_TWO_PI;
    plutovg_matrix_init_rotate(&mtx, angle);
    plutovg_matrix_scale(&mtx, rx, ry);
    int segments = (int)(ceilf(fabsf(th_arc / (PLUTOVG_HALF_PI + 0.001f))));
    for(int i = 0; i < segments; i++) {
        float th_start = th1 + i * th_arc / segments;
        float th_end = th1 + (i + 1) * th_arc / segments;
        float t = (8.f / 6.f) * tanf(0.25f * (th_end - th_start));
        float x3 = cosf(th_end) + cx1;
        float y3 = sinf(th_end) + cy1;
        float cp2x = x3 + t * sinf(th_end);
        float cp2y = y3 - t * cosf(th_end);
        float cp1x = cosf(th_start) - t * sinf(th_start);
        float cp1y = sinf(th_start) + t * cosf(th_start);
        cp1x += cx1;
        cp1y += cy1;
        plutovg_matrix_map(&mtx, cp1x, cp1y, &cp1x, &cp1y);
        plutovg_matrix_map(&mtx, cp2x, cp2y, &cp2x, &cp2y);
        plutovg_matrix_map(&mtx, x3, y3, &x3, &y3);
        plutovg_path_cubic_to(p, cp1x, cp1y, cp2x, cp2y, x3, y3);
    }
}

// Close the current subpath
void plutovg_path_close(plutovg_path_t* p)
{
    if(p->elements.size == 0)
        return;
    plutovg_path_element_t* elts = plutovg_path_add_command(p, PLUTOVG_PATH_COMMAND_CLOSE, 1);
    elts[0].point = p->start_point;
}

// Get current point from path
void plutovg_path_get_current_point(const plutovg_path_t* p, float* x, float* y)
{
    float xx = 0.f;
    float yy = 0.f;
    if(p->num_points > 0) {
        xx = p->elements.data[p->elements.size - 1].point.x;
        yy = p->elements.data[p->elements.size - 1].point.y;
    }
    if(x) *x = xx;
    if(y) *y = yy;
}

// Reserve space in path elements array
void plutovg_path_reserve(plutovg_path_t* p, int count)
{
    plutovg_array_ensure(p->elements, count);
}

// Reset path to empty state
void plutovg_path_reset(plutovg_path_t* p)
{
    plutovg_array_clear(p->elements);
    p->start_point = PLUTOVG_EMPTY_POINT;
    p->num_points = 0;
    p->num_contours = 0;
    p->num_curves = 0;
}

// Add rectangle to path
void plutovg_path_add_rect(plutovg_path_t* p, float x, float y, float w, float h)
{
    plutovg_path_reserve(p, 6 * 2);
    plutovg_path_move_to(p, x, y);
    plutovg_path_line_to(p, x + w, y);
    plutovg_path_line_to(p, x + w, y + h);
    plutovg_path_line_to(p, x, y + h);
    plutovg_path_line_to(p, x, y);
    plutovg_path_close(p);
}

// Add rounded rectangle to path
void plutovg_path_add_round_rect(plutovg_path_t* p, float x, float y, float w, float h, float rx, float ry)
{
    rx = plutovg_min(rx, w * 0.5f);
    ry = plutovg_min(ry, h * 0.5f);
    if(rx == 0.f && ry == 0.f) {
        plutovg_path_add_rect(p, x, y, w, h);
        return;
    }
    float right = x + w;
    float bottom = y + h;
    float cpx = rx * PLUTOVG_KAPPA;
    float cpy = ry * PLUTOVG_KAPPA;
    plutovg_path_reserve(p, 6 * 2 + 4 * 4);
    plutovg_path_move_to(p, x, y+ry);
    plutovg_path_cubic_to(p, x, y+ry-cpy, x+rx-cpx, y, x+rx, y);
    plutovg_path_line_to(p, right-rx, y);
    plutovg_path_cubic_to(p, right-rx+cpx, y, right, y+ry-cpy, right, y+ry);
    plutovg_path_line_to(p, right, bottom-ry);
    plutovg_path_cubic_to(p, right, bottom-ry+cpy, right-rx+cpx, bottom, right-rx, bottom);
    plutovg_path_line_to(p, x+rx, bottom);
    plutovg_path_cubic_to(p, x+rx-cpx, bottom, x, bottom-ry+cpy, x, bottom-ry);
    plutovg_path_line_to(p, x, y+ry);
    plutovg_path_close(p);
}

// Add ellipse to path
void plutovg_path_add_ellipse(plutovg_path_t* p, float cx, float cy, float rx, float ry)
{
    float left = cx - rx;
    float top = cy - ry;
    float right = cx + rx;
    float bottom = cy + ry;
    float cpx = rx * PLUTOVG_KAPPA;
    float cpy = ry * PLUTOVG_KAPPA;
    plutovg_path_reserve(p, 2 * 2 + 4 * 4);
    plutovg_path_move_to(p, cx, top);
    plutovg_path_cubic_to(p, cx+cpx, top, right, cy-cpy, right, cy);
    plutovg_path_cubic_to(p, right, cy+cpy, cx+cpx, bottom, cx, bottom);
    plutovg_path_cubic_to(p, cx-cpx, bottom, left, cy+cpy, left, cy);
    plutovg_path_cubic_to(p, left, cy-cpy, cx-cpx, top, cx, top);
    plutovg_path_close(p);
}

// Add circle to path
void plutovg_path_add_circle(plutovg_path_t* p, float cx, float cy, float r)
{
    plutovg_path_add_ellipse(p, cx, cy, r, r);
}

// Add arc to path
void plutovg_path_add_arc(plutovg_path_t* p, float cx, float cy, float r, float a0, float a1, bool ccw)
{
    float da = a1 - a0;
    if(fabsf(da) > PLUTOVG_TWO_PI) {
        da = PLUTOVG_TWO_PI;
    } else if(da != 0.f && ccw != (da < 0.f)) {
        da += PLUTOVG_TWO_PI * (ccw ? -1 : 1);
    }
    int seg_n = (int)(ceilf(fabsf(da) / PLUTOVG_HALF_PI));
    if(seg_n == 0)
        return;
    float a = a0;
    float ax = cx + cosf(a) * r;
    float ay = cy + sinf(a) * r;
    float seg_a = da / seg_n;
    float d = (seg_a / PLUTOVG_HALF_PI) * PLUTOVG_KAPPA * r;
    float dx = -sinf(a) * d;
    float dy = cosf(a) * d;
    plutovg_path_reserve(p, 2 + 4 * seg_n);
    if(path->elements.size == 0) {
        plutovg_path_move_to(p, ax, ay);
    } else {
        plutovg_path_line_to(p, ax, ay);
    }
    for(int i = 0; i < seg_n; i++) {
        float cp1x = ax + dx;
        float cp1y = ay + dy;
        a += seg_a;
        ax = cx + cosf(a) * r;
        ay = cy + sinf(a) * r;
        dx = -sinf(a) * d;
        dy = cosf(a) * d;
        float cp2x = ax - dx;
        float cp2y = ay - dy;
        plutovg_path_cubic_to(p, cp1x, cp1y, cp2x, cp2y, ax, ay);
    }
}

// Transform all points in path by matrix
void plutovg_path_transform(plutovg_path_t* p, const plutovg_matrix_t* mtx)
{
    plutovg_path_element_t* elts = p->elements.data;
    for(int i = 0; i < p->elements.size; i += elts[i].header.length) {
        switch(elts[i].header.command) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
        case PLUTOVG_PATH_COMMAND_LINE_TO:
        case PLUTOVG_PATH_COMMAND_CLOSE:
            plutovg_matrix_map_point(mtx, &elts[i + 1].point, &elts[i + 1].point);
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            plutovg_matrix_map_point(mtx, &elts[i + 1].point, &elts[i + 1].point);
            plutovg_matrix_map_point(mtx, &elts[i + 2].point, &elts[i + 2].point);
            plutovg_matrix_map_point(mtx, &elts[i + 3].point, &elts[i + 3].point);
            break;
        }
    }
}

// Add another path to this path with optional transformation
void plutovg_path_add_path(plutovg_path_t* p, const plutovg_path_t* src, const plutovg_matrix_t* mtx)
{
    if(mtx == NULL) {
        plutovg_array_append(p->elements, src->elements);
        p->start_point = src->start_point;
        p->num_points += src->num_points;
        p->num_contours += src->num_contours;
        p->num_curves += src->num_curves;
        return;
    }
    plutovg_path_iterator_t iter;
    plutovg_path_iterator_init(&iter, src);
    plutovg_point_t pts[3];
    plutovg_array_ensure(p->elements, src->elements.size);
    while(plutovg_path_iterator_has_next(&iter)) {
        switch(plutovg_path_iterator_next(&iter, pts)) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
            plutovg_matrix_map_points(mtx, pts, pts, 1);
            plutovg_path_move_to(p, pts[0].x, pts[0].y);
            break;
        case PLUTOVG_PATH_COMMAND_LINE_TO:
            plutovg_matrix_map_points(mtx, pts, pts, 1);
            plutovg_path_line_to(p, pts[0].x, pts[0].y);
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            plutovg_matrix_map_points(mtx, pts, pts, 3);
            plutovg_path_cubic_to(p, pts[0].x, pts[0].y, pts[1].x, pts[1].y, pts[2].x, pts[2].y);
            break;
        case PLUTOVG_PATH_COMMAND_CLOSE:
            plutovg_path_close(p);
            break;
        }
    }
}

// Traverse path with callback function
void plutovg_path_traverse(const plutovg_path_t* p, plutovg_path_traverse_func_t traverse_func, void* closure)
{
    plutovg_path_iterator_t iter;
    plutovg_path_iterator_init(&iter, p);
    plutovg_point_t pts[3];
    while(plutovg_path_iterator_has_next(&iter)) {
        switch(plutovg_path_iterator_next(&iter, pts)) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_MOVE_TO, pts, 1);
            break;
        case PLUTOVG_PATH_COMMAND_LINE_TO:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_LINE_TO, pts, 1);
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_CUBIC_TO, pts, 3);
            break;
        case PLUTOVG_PATH_COMMAND_CLOSE:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_CLOSE, pts, 1);
            break;
        }
    }
}

// Structure for bezier curve representation
typedef struct {
    float x1; float y1;
    float x2; float y2;
    float x3; float y3;
    float x4; float y4;
} bezier_t;

// Split a bezier curve into two halves
static inline void split_bezier(const bezier_t* b, bezier_t* first, bezier_t* second)
{
    float c = (b->x2 + b->x3) * 0.5f;
    first->x2 = (b->x1 + b->x2) * 0.5f;
    second->x3 = (b->x3 + b->x4) * 0.5f;
    first->x1 = b->x1;
    second->x4 = b->x4;
    first->x3 = (first->x2 + c) * 0.5f;
    second->x2 = (second->x3 + c) * 0.5f;
    first->x4 = second->x1 = (first->x3 + second->x2) * 0.5f;
    c = (b->y2 + b->y3) * 0.5f;
    first->y2 = (b->y1 + b->y2) * 0.5f;
    second->y3 = (b->y3 + b->y4) * 0.5f;
    first->y1 = b->y1;
    second->y4 = b->y4;
    first->y3 = (first->y2 + c) * 0.5f;
    second->y2 = (second->y3 + c) * 0.5f;
    first->y4 = second->y1 = (first->y3 + second->y2) * 0.5f;
}

// Traverse path with flattening (convert curves to lines)
void plutovg_path_traverse_flatten(const plutovg_path_t* p, plutovg_path_traverse_func_t traverse_func, void* closure)
{
    if(p->num_curves == 0) {
        plutovg_path_traverse(p, traverse_func, closure);
        return;
    }
    const float threshold = 0.25f;
    plutovg_path_iterator_t iter;
    plutovg_path_iterator_init(&iter, p);
    bezier_t beziers[32];
    plutovg_point_t pts[3];
    plutovg_point_t current_point = {0, 0};
    while(plutovg_path_iterator_has_next(&iter)) {
        plutovg_path_command_t cmd = plutovg_path_iterator_next(&iter, pts);
        switch(cmd) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
        case PLUTOVG_PATH_COMMAND_LINE_TO:
        case PLUTOVG_PATH_COMMAND_CLOSE:
            traverse_func(closure, cmd, pts, 1);
            current_point = pts[0];
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            beziers[0].x1 = current_point.x;
            beziers[0].y1 = current_point.y;
            beziers[0].x2 = pts[0].x;
            beziers[0].y2 = pts[0].y;
            beziers[0].x3 = pts[1].x;
            beziers[0].y3 = pts[1].y;
            beziers[0].x4 = pts[2].x;
            beziers[0].y4 = pts[2].y;
            bezier_t* b = beziers;
            while(b >= beziers) {
                float y4y1 = b->y4 - b->y1;
                float x4x1 = b->x4 - b->x1;
                float l = fabsf(x4x1) + fabsf(y4y1);
                float d;
                if(l > 1.f) {
                    d = fabsf((x4x1)*(b->y1 - b->y2) - (y4y1)*(b->x1 - b->x2)) + fabsf((x4x1)*(b->y1 - b->y3) - (y4y1)*(b->x1 - b->x3));
                } else {
                    d = fabsf(b->x1 - b->x2) + fabsf(b->y1 - b->y2) + fabsf(b->x1 - b->x3) + fabsf(b->y1 - b->y3);
                    l = 1.f;
                }
                if(d < threshold*l || b == beziers + 31) {
                    plutovg_point_t pt = { b->x4, b->y4 };
                    traverse_func(closure, PLUTOVG_PATH_COMMAND_LINE_TO, &pt, 1);
                    --b;
                } else {
                    split_bezier(b, b + 1, b);
                    ++b;
                }
            }
            current_point = pts[2];
            break;
        }
    }
}

// Dasher structure for dashed line traversal
typedef struct {
    const float* dashes; int ndashes;
    float start_phase; float phase;
    int start_index; int index;
    bool start_toggle; bool toggle;
    plutovg_point_t current_point;
    plutovg_path_traverse_func_t traverse_func;
    void* closure;
} dasher_t;

// Dashed line traversal callback
static void dash_traverse_func(void* closure, plutovg_path_command_t cmd, const plutovg_point_t* pts, int npoints)
{
    dasher_t* dasher = (dasher_t*)(closure);
    if(cmd == PLUTOVG_PATH_COMMAND_MOVE_TO) {
        if(dasher->start_toggle)
            dasher->traverse_func(dasher->closure, PLUTOVG_PATH_COMMAND_MOVE_TO, pts, npoints);
        dasher->current_point = pts[0];
        dasher->phase = dasher->start_phase;
        dasher->index = dasher->start_index;
        dasher->toggle = dasher->start_toggle;
        return;
    }
    assert(cmd == PLUTOVG_PATH_COMMAND_LINE_TO || cmd == PLUTOVG_PATH_COMMAND_CLOSE);
    plutovg_point_t p0 = dasher->current_point;
    plutovg_point_t p1 = pts[0];
    float dx = p1.x - p0.x;
    float dy = p1.y - p0.y;
    float dist0 = sqrtf(dx*dx + dy*dy);
    float dist1 = 0.f;
    while(dist0 - dist1 > dasher->dashes[dasher->index % dasher->ndashes] - dasher->phase) {
        dist1 += dasher->dashes[dasher->index % dasher->ndashes] - dasher->phase;
        float a = dist1 / dist0;
        plutovg_point_t p = { p0.x + a * dx, p0.y + a * dy };
        if(dasher->toggle) {
            dasher->traverse_func(dasher->closure, PLUTOVG_PATH_COMMAND_LINE_TO, &p, 1);
        } else {
            dasher->traverse_func(dasher->closure, PLUTOVG_PATH_COMMAND_MOVE_TO, &p, 1);
        }
        dasher->phase = 0.f;
        dasher->toggle = !dasher->toggle;
        dasher->index++;
    }
    if(dasher->toggle) {
        dasher->traverse_func(dasher->closure, PLUTOVG_PATH_COMMAND_LINE_TO, &p1, 1);
    }
    dasher->phase += dist0 - dist1;
    dasher->current_point = p1;
}

// Traverse path with dashed pattern
void plutovg_path_traverse_dashed(const plutovg_path_t* p, float offset, const float* dashes, int ndashes, plutovg_path_traverse_func_t traverse_func, void* closure)
{
    float dash_sum = 0.f;
    for(int i = 0; i < ndashes; ++i)
        dash_sum += dashes[i];
    if(ndashes % 2 == 1)
        dash_sum *= 2.f;
    if(dash_sum <= 0.f) {
        plutovg_path_traverse(p, traverse_func, closure);
        return;
    }
    dasher_t dasher;
    dasher.dashes = dashes;
    dasher.ndashes = ndashes;
    dasher.start_phase = fmodf(offset, dash_sum);
    if(dasher.start_phase < 0.f)
        dasher.start_phase += dash_sum;
    dasher.start_index = 0;
    dasher.start_toggle = true;
    while(dasher.start_phase > 0.f && dasher.start_phase >= dasher.dashes[dasher.start_index % dasher.ndashes]) {
        dasher.start_phase -= dashes[dasher.start_index % dasher.ndashes];
        dasher.start_toggle = !dasher.start_toggle;
        dasher.start_index++;
    }
    dasher.phase = dasher.start_phase;
    dasher.index = dasher.start_index;
    dasher.toggle = dasher.start_toggle;
    dasher.current_point = PLUTOVG_EMPTY_POINT;
    dasher.traverse_func = traverse_func;
    dasher.closure = closure;
    plutovg_path_traverse_flatten(p, dash_traverse_func, &dasher);
}

// Clone a path
plutovg_path_t* plutovg_path_clone(const plutovg_path_t* p)
{
    plutovg_path_t* clone = plutovg_path_create();
    plutovg_array_append(clone->elements, p->elements);
    clone->start_point = p->start_point;
    clone->num_points = p->num_points;
    clone->num_contours = p->num_contours;
    clone->num_curves = p->num_curves;
    return clone;
}

// Traversal function for cloning paths
static void clone_traverse_func(void* closure, plutovg_path_command_t cmd, const plutovg_point_t* pts, int npoints)
{
    plutovg_path_t* p = (plutovg_path_t*)(closure);
    switch(cmd) {
    case PLUTOVG_PATH_COMMAND_MOVE_TO:
        plutovg_path_move_to(p, pts[0].x, pts[0].y);
        break;
    case PLUTOVG_PATH_COMMAND_LINE_TO:
        plutovg_path_line_to(p, pts[0].x, pts[0].y);
        break;
    case PLUTOVG_PATH_COMMAND_CUBIC_TO:
        plutovg_path_cubic_to(p, pts[0].x, pts[0].y, pts[1].x, pts[1].y, pts[2].x, pts[2].y);
        break;
    case PLUTOVG_PATH_COMMAND_CLOSE:
        plutovg_path_close(p);
        break;
    }
}

// Clone path with flattening
plutovg_path_t* plutovg_path_clone_flatten(const plutovg_path_t* p)
{
    plutovg_path_t* clone = plutovg_path_create();
    plutovg_path_reserve(clone, p->elements.size + p->num_curves * 32);
    plutovg_path_traverse_flatten(p, clone_traverse_func, clone);
    return clone;
}

// Clone path with dashed pattern
plutovg_path_t* plutovg_path_clone_dashed(const plutovg_path_t* p, float offset, const float* dashes, int ndashes)
{
    plutovg_path_t* clone = plutovg_path_create();
    plutovg_path_reserve(clone, p->elements.size + p->num_curves * 32);
    plutovg_path_traverse_dashed(p, offset, dashes, ndashes, clone_traverse_func, clone);
    return clone;
}

// Extents calculator structure
typedef struct {
    plutovg_point_t current_point;
    bool is_first_point;
    float length;
    float x1;
    float y1;
    float x2;
    float y2;
} extents_calculator_t;

// Extents calculation traversal function
static void extents_traverse_func(void* closure, plutovg_path_command_t cmd, const plutovg_point_t* pts, int npoints)
{
    extents_calculator_t* calc = (extents_calculator_t*)(closure);
    if(calc->is_first_point) {
        assert(cmd == PLUTOVG_PATH_COMMAND_MOVE_TO);
        calc->is_first_point = false;
        calc->current_point = pts[0];
        calc->x1 = pts[0].x;
        calc->y1 = pts[0].y;
        calc->x2 = pts[0].x;
        calc->y2 = pts[0].y;
        calc->length = 0;
        return;
    }
    for(int i = 0; i < npoints; ++i) {
        calc->x1 = plutovg_min(calc->x1, pts[i].x);
        calc->y1 = plutovg_min(calc->y1, pts[i].y);
        calc->x2 = plutovg_max(calc->x2, pts[i].x);
        calc->y2 = plutovg_max(calc->y2, pts[i].y);
        if(cmd != PLUTOVG_PATH_COMMAND_MOVE_TO)
            calc->length += hypotf(pts[i].x - calc->current_point.x, pts[i].y - calc->current_point.y);
        calc->current_point = pts[i];
    }
}

// Calculate path extents and length
float plutovg_path_extents(const plutovg_path_t* p, plutovg_rect_t* extents, bool tight)
{
    extents_calculator_t calc = {{0, 0}, true, 0, 0, 0, 0, 0};
    if(tight) {
        plutovg_path_traverse_flatten(p, extents_traverse_func, &calc);
    } else {
        plutovg_path_traverse(p, extents_traverse_func, &calc);
    }
    if(extents) {
        extents->x = calc.x1;
        extents->y = calc.y1;
        extents->w = calc.x2 - calc.x1;
        extents->h = calc.y2 - calc.y1;
    }
    return calc.length;
}

// Get path length
float plutovg_path_length(const plutovg_path_t* p)
{
    return plutovg_path_extents(p, NULL, true);
}

