	bool bCompatible = false;

	EGraphType GraphKind = TargetGraph->GetSchema()->GetGraphType(TargetGraph);
	bool const bPermitLatentCalls = (GraphKind == GT_Ubergraph || GraphKind == GT_Macro);

	if (bPermitLatentCalls)
	{
		UBlueprint* OwnerBlueprint = FBlueprintEditorUtils::FindBlueprintForGraph(TargetGraph);
		if (OwnerBlueprint && OwnerBlueprint->GeneratedClass)
		{
			if (OwnerBlueprint->GeneratedClass->IsChildOf(UGameplayAbility::StaticClass()))
			{
				bCompatible = true;
			}
		}
	}

	return bCompatible;
}

void UK2Node_LatentAbilityCall::GetMenuActions(FBlueprintActionDatabaseRegistrar& ActionRegistrar) const
{
	struct LocalHelpers
	{
		static void ConfigureNode(UEdGraphNode* SpawnedNode, bool /*bIsTemplate*/, TWeakObjectPtr<UFunction> FunctionRef)
		{
			UK2Node_LatentAbilityCall* TaskNode = CastChecked<UK2Node_LatentAbilityCall>(SpawnedNode);
			if (FunctionRef.IsValid())
			{
				UFunction* Func = FunctionRef.Get();
				FObjectProperty* ResultProp = CastFieldChecked<FObjectProperty>(Func->GetReturnProperty());

				TaskNode->ProxyFactoryFunctionName = Func->GetFName();
				TaskNode->ProxyFactoryClass        = Func->GetOuterUClass();
				TaskNode->ProxyClass               = ResultProp->PropertyClass;
			}
		}
	};

	UClass* NodeTypeInfo = GetClass();
	ActionRegistrar.RegisterClassFactoryActions<UAbilityTask>(
		FBlueprintActionDatabaseRegistrar::FMakeFuncSpawnerDelegate::CreateLambda(
			[NodeTypeInfo](const UFunction* FactoryFunc)->UBlueprintNodeSpawner*
			{
				UBlueprintNodeSpawner* Spawner = UBlueprintFunctionNodeSpawner::Create(FactoryFunc);
				check(Spawner != nullptr);
				Spawner->NodeClass = NodeTypeInfo;
				TWeakObjectPtr<UFunction> FunctionRef = MakeWeakObjectPtr(const_cast<UFunction*>(FactoryFunc));
				Spawner->CustomizeNodeDelegate = UBlueprintNodeSpawner::FCustomizeNodeDelegate::CreateStatic(LocalHelpers::ConfigureNode, FunctionRef);
				return Spawner;
			}
		)
	);
}

void UK2Node_LatentAbilityCall::ValidateNodeDuringCompilation(class FCompilerResultsLog& MessageLog) const
{
	Super::ValidateNodeDuringCompilation(MessageLog);

	UFunction* DelegateSignatureFunction = nullptr;
	for (TFieldIterator<FProperty> PropIt(ProxyClass); PropIt; ++PropIt)
	{
		if (FMulticastDelegateProperty* Property = CastField<FMulticastDelegateProperty>(*PropIt))
		{
			if (Property->GetBoolMetaData(FK2Node_LatentAbilityCallHelper_RequiresConnection))
			{
				if (UEdGraphPin* ExecPin = FindPin(Property->GetFName()))
				{
					if (ExecPin->LinkedTo.Num() == 0)
					{
						const FText Msg = FText::Format(
							LOCTEXT("NoConnectionToRequiredExecPin", "@@ - Unhandled event. You need something connected to the '{0}' pin"),
							FText::FromName(Property->GetFName())
						);
						MessageLog.Warning(*Msg.ToString(), this);
					}
				}
			}
		}
	}
}

