#include <chrono>
#include <gtest/gtest.h>
#include <folly/io/async/ScopedEventBaseThread.h>
#include <folly/logging/xlog.h>
#include "comms/ctran/bootstrap/AsyncSocket.h"
#include "comms/ctran/bootstrap/Socket.h"

using namespace ::testing;
using namespace std::literals::chrono_literals;

namespace {
enum class MessageState {
  PENDING,
  FINISHED,
  FAILED,
};
}

TEST(AsyncSocket, LifecycleTest) {
  const std::string test_request = "ping";
  auto workerThread = std::make_unique<folly::ScopedEventBaseThread>();
  std::string received_data;
  std::atomic<MessageState> receive_state(MessageState::PENDING);

  ctran::bootstrap::AsyncServerSocket listener(*workerThread->getEventBase());

  // Start server on localhost and register callback
  auto listenAddrFuture = listener.start(
      folly::SocketAddress("::1", 0),
      test_request.size(),
      [&received_data, &receive_state](std::unique_ptr<folly::IOBuf> buffer) {
        received_data = buffer->moveToFbString().toStdString();
        receive_state.store(MessageState::FINISHED);
      });

  // Acquire server address and verify properties
  auto serverAddress = std::move(listenAddrFuture).get();
  EXPECT_EQ(serverAddress.getFamily(), AF_INET6);
  EXPECT_NE(serverAddress.getPort(), 0);
  EXPECT_EQ(serverAddress.getIPAddress().str(), "::1");

  // Client sends request to server
  std::atomic<MessageState> transmit_state(MessageState::PENDING);
  ctran::bootstrap::AsyncClientSocket::send(
      *workerThread->getEventBase(),
      serverAddress,
      test_request.data(),
      test_request.size(),
      [&transmit_state](const folly::AsyncSocketException* exception) {
        if (exception != nullptr) {
          transmit_state.store(MessageState::FAILED);
        } else {
          transmit_state.store(MessageState::FINISHED);
        }
      });

  // Poll until transmission completes
  while (transmit_state.load() == MessageState::PENDING) {
  }
  EXPECT_EQ(transmit_state.load(), MessageState::FINISHED);

  // Poll until reception completes
  while (receive_state.load() == MessageState::PENDING) {
  }

  // Validate results
  EXPECT_EQ(receive_state.load(), MessageState::FINISHED);
  EXPECT_EQ(received_data, test_request);

  // Terminate server and confirm cleanup
  auto shutdownFuture = listener.stop();
  EXPECT_EQ(folly::unit, std::move(shutdownFuture).get());
}

TEST(AsyncSocket, MultiMessageOrderingTest) {
  struct Payload {
    char content;
    int sequence;
  };

  const std::string original_str = "abcdefghijk";
  auto ioThread = std::make_unique<folly::ScopedEventBaseThread>();

  std::atomic_int total_received = 0;
  int expected_seq = 0;
  std::unordered_map<int, char> order_map;
  std::string assembled_str = "";

  ctran::bootstrap::AsyncServerSocket server(*ioThread->getEventBase());

  auto listenAddrFuture = server.start(
      folly::SocketAddress("::1", 0),
      sizeof(Payload),
      [&total_received, &expected_seq, &order_map, &assembled_str](
          std::unique_ptr<folly::IOBuf> buffer) {
        Payload item;
        std::memcpy(&item, buffer->data(), sizeof(Payload));
        order_map[item.sequence] = item.content;

        while (order_map.find(expected_seq) != order_map.end()) {
          assembled_str += order_map[expected_seq];
          order_map.erase(expected_seq);
          expected_seq++;
        }
        total_received.fetch_add(1);
      });

  auto serverAddress = std::move(listenAddrFuture).get();
  EXPECT_EQ(serverAddress.getFamily(), AF_INET6);
  EXPECT_NE(serverAddress.getPort(), 0);
  EXPECT_EQ(serverAddress.getIPAddress().str(), "::1");

  std::vector<std::atomic<MessageState>> send_states(original_str.size());
  for (auto& state : send_states) {
    state.store(MessageState::PENDING);
  }

  std::vector<Payload> items(original_str.size());
  for (int idx = 0; idx < original_str.size(); ++idx) {
    items[idx] = Payload{.content = original_str[idx], .sequence = idx};
    ctran::bootstrap::AsyncClientSocket::send(
        *ioThread->getEventBase(),
        serverAddress,
        &items[idx],
        sizeof(Payload),
        [status = &send_states[idx]](const folly::AsyncSocketException* err) {
          if (err != nullptr) {
            status->store(MessageState::FAILED);
          } else {
            status->store(MessageState::FINISHED);
          }
        });
  }

  // Wait for all transmissions to finish
  for (size_t i = 0; i < original_str.size(); ++i) {
    while (send_states[i].load() == MessageState::PENDING) {
    }
    EXPECT_EQ(send_states[i].load(), MessageState::FINISHED);
  }

  // Wait until all messages are received
  while (total_received.load() < static_cast<int>(original_str.size())) {
  }

  EXPECT_EQ(assembled_str, original_str);

  auto stopFuture = server.stop();
  EXPECT_EQ(folly::unit, std::move(stopFuture).get());
}

TEST(AsyncSocket, ConnectionFailureTest) {
  const std::string test_msg = "ping";
  auto workerThread = std::make_unique<folly::ScopedEventBaseThread>();
  auto invalidAddr = folly::SocketAddress();

  std::atomic<MessageState> send_result(MessageState::PENDING);
  ctran::bootstrap::AsyncClientSocket::send(
      *workerThread->getEventBase(),
      invalidAddr,
      test_msg.data(),
      test_msg.size(),
      [&send_result](const folly::AsyncSocketException* error) {
        if (error != nullptr) {
          send_result.store(MessageState::FAILED);
        } else {
          send_result.store(MessageState::FINISHED);
        }
      });

  while (send_result.load() == MessageState::PENDING) {
  }
  EXPECT_EQ(send_result.load(), MessageState::FAILED);
}

TEST(AsyncSocket, ServerTimeoutNoDataTest) {
  const std::string test_msg = "ping";
  auto workerThread = std::make_unique<folly::ScopedEventBaseThread>();
  std::atomic<bool> callback_executed(false);

  ctran::bootstrap::AsyncServerSocket server(*workerThread->getEventBase());

  auto listenAddrFuture = server.start(
      folly::SocketAddress("::1", 0),
      test_msg.size(),
      [&callback_executed](std::unique_ptr<folly::IOBuf> buf) {
        XLOGF(INFO, "Server received {} bytes", buf->computeChainDataLength());
        callback_executed.store(true);
      },
      std::chrono::milliseconds(500));

  auto serverAddress = std::move(listenAddrFuture).get();

  ctran::bootstrap::Socket silent_client;
  ASSERT_EQ(0, silent_client.connect(serverAddress, "lo"));
  XLOG(INFO) << "Client connected but will not send data";

  std::this_thread::sleep_for(std::chrono::milliseconds(1000));

  EXPECT_FALSE(callback_executed.load())
      << "Callback should not be triggered on timeout without data";

  silent_client.close();
  auto stopFuture = server.stop();
  std::move(stopFuture).get();
}

TEST(AsyncSocket, ServerTimeoutPartialDataTest) {
  const size_t required_bytes = 100;
  auto workerThread = std::make_unique<folly::ScopedEventBaseThread>();
  std::atomic<bool> callback_executed(false);

  ctran::bootstrap::AsyncServerSocket server(*workerThread->getEventBase());

  auto listenAddrFuture = server.start(
      folly::SocketAddress("::1", 0),
      required_bytes,
      [&callback_executed](std::unique_ptr<folly::IOBuf> buf) {
        XLOGF(INFO, "Server received {} bytes", buf->computeChainDataLength());
        callback_executed.store(true);
      },
      std::chrono::milliseconds(500));

  auto serverAddress = std::move(listenAddrFuture).get();

  ctran::bootstrap::Socket partial_client;
  ASSERT_EQ(0, partial_client.connect(serverAddress, "lo"));

  const std::string short_data(50, 'y');
  ASSERT_EQ(0, partial_client.send(short_data.data(), short_data.size()));

  XLOGF(
      INFO,
      "Client sent {} bytes (partial), server expects {} bytes",
      short_data.size(),
      required_bytes);

  std::this_thread::sleep_for(std::chrono::milliseconds(1000));

  EXPECT_FALSE(callback_executed.load())
      << "Callback should not be invoked when incomplete data arrives before timeout";

  partial_client.close();
  auto stopFuture = server.stop();
  std::move(stopFuture).get();
}

#include <Python.h>

typedef struct {
    PyObject_HEAD
    Py_ssize_t current_index;
    PyByteArrayObject *sequence_ref; /* Set to NULL when iterator is exhausted */
} bytearray_iterator;

static void
bytearray_iterator_dealloc(bytearray_iterator *iter)
{
    _PyObject_GC_UNTRACK(iter);
    Py_XDECREF(iter->sequence_ref);
    PyObject_GC_Del(iter);
}

static int
bytearray_iterator_traverse(bytearray_iterator *iter, visitproc visitor, void *arg)
{
    Py_VISIT(iter->sequence_ref);
    return 0;
}

static PyObject *
bytearray_iterator_next(bytearray_iterator *iter)
{
    PyByteArrayObject *seq;
    PyObject *element;
    assert(iter != NULL);
    seq = iter->sequence_ref;
    if (seq == NULL)
        return NULL;
    assert(PyByteArray_Check(seq));
    if (iter->current_index < PyByteArray_GET_SIZE(seq)) {
        element = PyInt_FromLong(
            (unsigned char)seq->ob_bytes[iter->current_index]);
        if (element != NULL)
            ++iter->current_index;
        return element;
    }
    iter->sequence_ref = NULL;
    Py_DECREF(seq);
    return NULL;
}

static PyObject *
bytearray_iterator_length_hint(bytearray_iterator *iter)
{
    Py_ssize_t remaining = 0;
    if (iter->sequence_ref)
        remaining = PyByteArray_GET_SIZE(iter->sequence_ref) - iter->current_index;
    return PyInt_FromSsize_t(remaining);
}

PyDoc_STRVAR(hint_doc,
    "Private helper method providing an estimated count of remaining items.");

static PyMethodDef bytearray_iterator_methods[] = {
    {"__length_hint__", (PyCFunction)bytearray_iterator_length_hint, METH_NOARGS,
     hint_doc},
    {NULL, NULL} /* sentinel */
};

PyTypeObject PyByteArrayIter_Type = {
    PyVarObject_HEAD_INIT(&PyType_Type, 0)
    "bytearray_iterator",              /* tp_name */
    sizeof(bytearray_iterator),        /* tp_basicsize */
    0,                                 /* tp_itemsize */
    /* methods */
    (destructor)bytearray_iterator_dealloc, /* tp_dealloc */
    0,                                 /* tp_print */
    0,                                 /* tp_getattr */
    0,                                 /* tp_setattr */
    0,                                 /* tp_compare */
    0,                                 /* tp_repr */
    0,                                 /* tp_as_number */
    0,                                 /* tp_as_sequence */
    0,                                 /* tp_as_mapping */
    0,                                 /* tp_hash */
    0,                                 /* tp_call */
    0,                                 /* tp_str */
    PyObject_GenericGetAttr,           /* tp_getattro */
    0,                                 /* tp_setattro */
    0,                                 /* tp_as_buffer */
    Py_TPFLAGS_DEFAULT | Py_TPFLAGS_HAVE_GC, /* tp_flags */
    0,                                 /* tp_doc */
    (traverseproc)bytearray_iterator_traverse,  /* tp_traverse */
    0,                                 /* tp_clear */
    0,                                 /* tp_richcompare */
    0,                                 /* tp_weaklistoffset */
    PyObject_SelfIter,                 /* tp_iter */
    (iternextfunc)bytearray_iterator_next,  /* tp_iternext */
    bytearray_iterator_methods,        /* tp_methods */
    0,
};

static PyObject *
bytearray_iter(PyObject *obj)
{
    bytearray_iterator *iter;
    if (!PyByteArray_Check(obj)) {
        PyErr_BadInternalCall();
        return NULL;
    }
    iter = PyObject_GC_New(bytearray_iterator, &PyByteArrayIter_Type);
    if (iter == NULL)
        return NULL;
    iter->current_index = 0;
    Py_INCREF(obj);
    iter->sequence_ref = (PyByteArrayObject *)obj;
    _PyObject_GC_TRACK(iter);
    return (PyObject *)iter;
}

