#include <stdlib.h>

// Helper macro to get pointer to element at position idx (1-indexed)
#define get_element(idx) (((char*)data_array) + (element_width * ((idx)-1)))

// Swap two memory blocks of specified size
void swap_blocks(void* block_a, void* block_b, size_t bytes_to_swap) {
    char* ptr_a = (char*)block_a;
    char* ptr_b = (char*)block_b;
    size_t count = bytes_to_swap;

    while (count--) {
        char temp = *ptr_a;
        *ptr_a++ = *ptr_b;
        *ptr_b++ = temp;
    }
}

void heap_sort(void* data_array, size_t element_count, size_t element_width, int (*compare_elements)(const void*, const void*)) 
{
    size_t left, right, index;
    char* left_ptr;
    char* right_ptr;
    char* temp_ptr1;
    char* temp_ptr2;
    char* temp_ptr3;

    if (element_count <= 1)
        return;

    right = element_count;
    left = (right / 2) + 1;
    left_ptr = get_element(left);
    right_ptr = get_element(right);

    for (;;) {
        if (left > 1) {
            left--;
            left_ptr -= element_width;
        } else {
            swap_blocks(left_ptr, right_ptr, element_width);
            if (--right == 1)
                return;
            right_ptr -= element_width;
        }

        index = left;
        temp_ptr1 = get_element(index);

        while (index * 2 <= right) {
            index *= 2;
            temp_ptr2 = temp_ptr1;
            temp_ptr1 = get_element(index);

            if (index < right) {
                temp_ptr3 = temp_ptr1 + element_width;
                if (compare_elements(temp_ptr1, temp_ptr3) < 0) {
                    index++;
                    temp_ptr1 = temp_ptr3;
                }
            }

            if (compare_elements(temp_ptr2, temp_ptr1) < 0) {
                swap_blocks(temp_ptr2, temp_ptr1, element_width);
            } else {
                break;
            }
        }
    }
}

