TEST(InifileParserTest, test_options_renamed) {
  using namespace sdb::options;

  uint64_t buffer_size = UINT64_MAX;
  uint64_t total_buffer_size = UINT64_MAX;
  uint64_t max_buffer_count = UINT64_MAX;
  uint64_t wal_size_limit = UINT64_MAX;
  uint64_t cache_capacity = UINT64_MAX;
  bool enforce_cache_limit = false;
  uint64_t memory_cache_size = UINT64_MAX;
  uint64_t unused_option = UINT64_MAX;

  uint64_t val_with_suffix1 = UINT64_MAX;
  uint64_t val_with_suffix2 = UINT64_MAX;
  uint64_t val_with_suffix3 = UINT64_MAX;
  uint64_t val_with_suffix4 = UINT64_MAX;
  uint64_t val_in_gb = UINT64_MAX;
  uint64_t inline_comment_val = UINT64_MAX;

  bool flag_on = false;
  bool flag_true = false;
  bool flag_false = true;
  bool flag_unset = false;

  double float_value = -1.0;
  double float_with_comment = -1.0;
  double float_not_set = -1.0;

  std::string str_empty = "default";
  std::string str_value = "hello";
  std::string str_inline_comment = "world";
  std::string another_str_inline = "test";
  std::string str_not_set = "end";

  containers::FlatHashSet<std::string> valid_sounds = {
    "meow", "woof", "chirp", "buzz", "honk", "quack"};
  std::vector<std::string> selected_sounds = {"chirp"};
  std::vector<std::string> extra_sounds = {"chirp", "buzz"};

  ProgramOptions cfg("demo", "demo [options]", "description", "/tmp/demo");
  cfg.addSection("storage", "storage settings");
  cfg.addOption("--storage.buffer-size", "buffer size",
                new UInt64Parameter(&buffer_size));
  cfg.addOption("--storage.total-buffer-size", "total buffer",
                new UInt64Parameter(&total_buffer_size));
  cfg.addOption("--storage.max-buffer-count", "max buffers",
                new UInt64Parameter(&max_buffer_count));
  cfg.addOption("--storage.wal-size-limit", "wal limit",
                new UInt64Parameter(&wal_size_limit));
  cfg.addOption("--storage.cache-capacity", "cache capacity",
                new UInt64Parameter(&cache_capacity));
  cfg.addOption("--storage.enforce-cache-limit", "enforce limit",
                new BooleanParameter(&enforce_cache_limit));

  cfg.addSection("memory", "memory settings");
  cfg.addOption("--memory.cache-size", "cache size",
                new UInt64Parameter(&memory_cache_size));
  cfg.addOption("--memory.unused-option", "unused",
                new UInt64Parameter(&unused_option));

  cfg.addSection("animals", "animal sounds");
  cfg.addOption("--animals.flag-on", "enable flag",
                new BooleanParameter(&flag_on, true));
  cfg.addOption("--animals.flag-true", "always true",
                new BooleanParameter(&flag_true, true));
  cfg.addOption("--animals.flag-false", "always false",
                new BooleanParameter(&flag_false, true));
  cfg.addOption("--animals.flag-unset", "not set",
                new BooleanParameter(&flag_unset, true));
  cfg.addOption("--animals.value-suffix1", "suffix value 1",
                new UInt64Parameter(&val_with_suffix1));
  cfg.addOption("--animals.value-suffix2", "suffix value 2",
                new UInt64Parameter(&val_with_suffix2));
  cfg.addOption("--animals.value-suffix3", "suffix value 3",
                new UInt64Parameter(&val_with_suffix3));
  cfg.addOption("--animals.value-suffix4", "suffix value 4",
                new UInt64Parameter(&val_with_suffix4));
  cfg.addOption("--animals.value-gb", "gigabyte value",
                new UInt64Parameter(&val_in_gb));
  cfg.addOption("--animals.inline-comment", "inline comment",
                new UInt64Parameter(&inline_comment_val));
  cfg.addOption("--animals.float-value", "float param",
                new DoubleParameter(&float_value));
  cfg.addOption("--animals.float-comment", "float with comment",
                new DoubleParameter(&float_with_comment));
  cfg.addOption("--animals.float-not-set", "float not set",
                new DoubleParameter(&float_not_set));
  cfg.addOption("--animals.str-empty", "empty string",
                new StringParameter(&str_empty));
  cfg.addOption("--animals.str-value", "string value",
                new StringParameter(&str_value));
  cfg.addOption("--animals.str-inline", "string with comment",
                new StringParameter(&str_inline_comment));
  cfg.addOption("--animals.another-str-inline", "another string",
                new StringParameter(&another_str_inline));
  cfg.addOption("--animals.str-not-set", "string not set",
                new StringParameter(&str_not_set));
  cfg.addOption(
    "--animals.sounds", "list of animal sounds",
    new DiscreteValuesVectorParameter<StringParameter>(&selected_sounds,
                                                       valid_sounds),
    sdb::options::MakeDefaultFlags(options::Flags::FlushOnFirst));
  cfg.addOption(
    "--animals.extra-sounds", "extra sounds list",
    new DiscreteValuesVectorParameter<StringParameter>(&extra_sounds,
                                                       valid_sounds),
    sdb::options::MakeDefaultFlags(options::Flags::FlushOnFirst));

  auto config_data = R"data(
[storage]
# Buffer configuration
buffer-size = 2048000 # 2M
total-buffer-size = 536870912
max-buffer-count = 4
wal-size-limit = 1024000 # 1M
# Cache settings
cache-capacity = 268435456
enforce-cache-limit = true

[memory]
cache-size = 268435456 # 256M

[animals]
flag-on = true
flag-true = true
flag-false = false
value-suffix1 = 1M
value-suffix2 = 1MiB
value-suffix3 = 12MB
   value-suffix4 = 256kb
   value-gb = 256GB
inline-comment = 12345#1234M
float-value = 335.25
float-comment = 2948.434#343
str-empty =
str-value = 486hbsbq,r
str-inline = abc#def h
another-str-inline = abc  #def h
sounds = meow
sounds = quack
sounds = buzz
)data";

  IniFileParser parser(&cfg);
  bool success = parser.parseContent("demo.conf", config_data, true);
  ASSERT_TRUE(success);

  ASSERT_EQ(2048000U, buffer_size);
  ASSERT_EQ(536870912U, total_buffer_size);
  ASSERT_EQ(4U, max_buffer_count);
  ASSERT_EQ(1024000U, wal_size_limit);
  ASSERT_EQ(268435456U, cache_capacity);
  ASSERT_TRUE(enforce_cache_limit);
  ASSERT_EQ(268435456U, memory_cache_size);
  ASSERT_EQ(UINT64_MAX, unused_option);

  ASSERT_TRUE(flag_on);
  ASSERT_TRUE(flag_true);
  ASSERT_FALSE(flag_false);
  ASSERT_FALSE(flag_unset);

  ASSERT_EQ(1000000U, val_with_suffix1);
  ASSERT_EQ(1048576U, val_with_suffix2);
  ASSERT_EQ(12000000U, val_with_suffix3);
  ASSERT_EQ(256000U, val_with_suffix4);
  ASSERT_EQ(256000000000U, val_in_gb);
  ASSERT_EQ(12345U, inline_comment_val);

  ASSERT_DOUBLE_EQ(335.25, float_value);
  ASSERT_DOUBLE_EQ(2948.434, float_with_comment);
  ASSERT_DOUBLE_EQ(-1.0, float_not_set);

  ASSERT_EQ("", str_empty);
  ASSERT_EQ("486hbsbq,r", str_value);
  ASSERT_EQ("abc#def h", str_inline_comment);
  ASSERT_EQ("abc  #def h", another_str_inline);
  ASSERT_EQ("end", str_not_set);

  auto find_sound = [&selected_sounds](std::string sound) {
    return std::find(selected_sounds.begin(), selected_sounds.end(), sound);
  };

  ASSERT_EQ(selected_sounds.size(), 3);
  ASSERT_EQ(find_sound("end"), selected_sounds.end());
  ASSERT_EQ(find_sound("chirp"), selected_sounds.end());

  auto iter = selected_sounds.begin();
  ASSERT_EQ(find_sound("meow"), iter);
  iter++;
  ASSERT_EQ(find_sound("quack"), iter);
  iter++;
  ASSERT_EQ(find_sound("buzz"), iter);

  auto find_extra_sound = [&extra_sounds](std::string sound) {
    return std::find(extra_sounds.begin(), extra_sounds.end(), sound);
  };

  ASSERT_EQ(extra_sounds.size(), 2);
  iter = extra_sounds.begin();
  ASSERT_EQ(find_extra_sound("chirp"), iter);
  iter++;
  ASSERT_EQ(find_extra_sound("buzz"), iter);
  ASSERT_EQ(find_extra_sound("woof"), extra_sounds.end());
}

TEST(InifileParserTest, test_exit_codes_for_valid_options_renamed) {
  using namespace sdb::options;
