void InterpTangent(
    const Vector3 &pointA,
    const Vector3 &pointB,
    const Vector3 &pointC,
    const Vector3 &pointD,
    float t,
    Vector3 &result
) {
    float tTimesSix;
    float scaleSquared;
    float scaleFactor;

    tTimesSix = t * 6.0f;
    scaleSquared = t * t;
    Scale(pointA, (scaleSquared * 6.0f) - tTimesSix, result);

    Vector3 tempVector;
    scaleFactor = scaleSquared * 3.0f;
    Scale(pointB, 1.0f + (scaleFactor - (t * 4.0f)), tempVector);
    Add(result, tempVector, result);

    Scale(pointC, (scaleSquared * -6.0f) + tTimesSix, tempVector);
    Add(result, tempVector, result);

    Scale(pointD, (scaleFactor - (t * 2.0f)), tempVector);
    Add(result, tempVector, result);
}

void SplineTangent(const Keys<Vector3, Vector3> &keyframes, int index, Vector3 &output) {
    int count = keyframes.size();
    MILO_ASSERT(count > 1, 0x17);

    if (count == 2) {
        Subtract(keyframes[1].value, keyframes[0].value, output);
    } 
    else if (index <= 0) {
        Subtract(keyframes[1].value, keyframes[0].value, output);
        Scale(output, 1.5f, output);

        Vector3 temp;
        Subtract(keyframes[2].value, keyframes[0].value, temp);
        Scale(temp, 0.25f, temp);
        Subtract(output, temp, output);
    } 
    else if (index >= count - 1) {
        Subtract(keyframes[count - 1].value, keyframes[count - 2].value, output);
        Scale(output, 1.5f, output);

        Vector3 temp;
        Subtract(keyframes[count - 1].value, keyframes[count - 3].value, temp);
        Scale(temp, 0.25f, temp);
        Subtract(output, temp, output);
    } 
    else {
        Subtract(keyframes[index + 1].value, keyframes[index - 1].value, output);
        Scale(output, 0.5f, output);
    }
}

void InterpVector(
    const Keys<Vector3, Vector3> &keyframes,
    const Key<Vector3> *previous,
    const Key<Vector3> *nextKey,
    float parameter,
    bool useSpline,
    Vector3 &outValue,
    Vector3 *outDerivative
) {
    if (keyframes.size() < 3) {
        useSpline = false;

        if (keyframes.size() < 2) {
            if (outDerivative)
                outDerivative->Set(0.0f, 1.0f, 0.0f);

            if (keyframes.size() != 0)
                outValue = previous->value;
            else
                outValue.Set(0, 0, 0);

            return;
        }
    }

    int position = previous - keyframes.begin();

    if (useSpline) {
        float tSquared = parameter * parameter;
        float tCubed = tSquared * parameter;
        float threeTSq = tSquared * 3.0f;

        Scale(previous->value, (tCubed * 2.0f - threeTSq) + 1.0f, outValue);

        Vector3 tangentStart;
        SplineTangent(keyframes, position, tangentStart);

        Vector3 temp1;
        Vector3 temp2;

        Scale(tangentStart, parameter + tSquared * -2.0f + tCubed, temp2);
        Add(outValue, temp2, outValue);

        Scale(nextKey->value, tCubed * -2.0f + threeTSq, temp2);
        Add(outValue, temp2, outValue);

        SplineTangent(keyframes, position + 1, temp1);
        Scale(temp1, tCubed - tSquared, temp2);
        Add(outValue, temp2, outValue);

        if (outDerivative) {
            InterpTangent(previous->value, tangentStart, nextKey->value, temp1, parameter, *outDerivative);
        }
    } 
    else {
        Interp(previous->value, nextKey->value, parameter, outValue);

        if (outDerivative) {
            if (position == keyframes.size() - 1) {
                position--;
            }
            Subtract(keyframes[position + 1].value, keyframes[position].value, *outDerivative);
        }
    }
}

void InterpVector(
    const Keys<Vector3, Vector3> &keyframes,
    bool useSpline,
    float time,
    Vector3 &outValue,
    Vector3 *outDerivative
) {
    const Key<Vector3> *prev;
    const Key<Vector3> *next;
    float param;

    keyframes.AtFrame(time, prev, next, param);
    InterpVector(keyframes, prev, next, param, useSpline, outValue, outDerivative);
}

void QuatSpline(
    const Keys<Hmx::Quat, Hmx::Quat> &keyframes,
    const Key<Hmx::Quat> *previous,
    const Key<Hmx::Quat> *nextKey,
    float t,
    Hmx::Quat &output
) {
    MILO_ASSERT(keyframes.size(), 0x9B);

    if (previous == nextKey) {
        output = previous->value;
    } 
    else {
        int idx = previous - &keyframes.front();
        Hmx::Quat pQuat = previous->value;
        Hmx::Quat nQuat = nextKey->value;
        Hmx::Quat q88 = idx == 0 ? pQuat : keyframes[idx - 1].value;
        Hmx::Quat q58 = idx + 1 == keyframes.size() - 1 ? nQuat : keyframes[idx + 2].value;

        NormalizeTo(pQuat, q88);
        NormalizeTo(pQuat, nQuat);
        NormalizeTo(pQuat, q58);

        for (int i = 0; i < 4; i++) {
            // Match base computation order exactly
            float pq = pQuat[i];
            float p2 = pq * 2.0f;
            float nq = nQuat[i];
            float q8 = q88[i];
            float n3mq8 = nq * 3.0f - q8;
            float q5 = q58[i];
            float diff = nq - q8;
            float n4p2 = nq * 4.0f + p2;
            float coef3part = q5 - n3mq8;
            float coef1 = diff * 0.5f;
            float tmp = n4p2 - pq * 5.0f;
            float coef3 = coef3part - diff;
            float coef2 = tmp - q5;

            output[i] = ((coef3 * t + coef2) * t + coef1) * t + p2;
        }

        Normalize(output, output);
    }
}

