#include "Utils/LLVM/RecursiveTimer.h"

// Tracks the current nesting level for timer indentation
static unsigned TimeRecorderDepth = 0;

// Flag to enable or disable timing functionality
bool RecursiveTimer::Enabled = true;

// Generates a string consisting of N four-space indentation units
static inline std::string Indent(unsigned Count) {
  std::string Result;
  while (Count-- > 0)
    Result.append("    ");
  return Result;
}

// Constructor accepting a C-string prefix
RecursiveTimer::RecursiveTimer(const char *Label)
    : Begin(std::chrono::steady_clock::now()), Prefix(Label) {
  if (!Enabled)
    return;
  Active = true;
  outs() << Indent(TimeRecorderDepth++) << Label << "...\n";
}

// Constructor accepting a std::string prefix
RecursiveTimer::RecursiveTimer(const std::string &Label)
    : Begin(std::chrono::steady_clock::now()), Prefix(Label) {
  if (!Enabled)
    return;
  Active = true;
  outs() << Indent(TimeRecorderDepth++) << Label << "...\n";
}

// Destructor outputs elapsed time upon scope exit
RecursiveTimer::~RecursiveTimer() {
  if (!Active)
    return;
  std::chrono::steady_clock::time_point Finish = std::chrono::steady_clock::now();
  auto DurationMs =
      std::chrono::duration_cast<std::chrono::milliseconds>(Finish - Begin)
          .count();
  auto DisplayValue = DurationMs > 1000 ? DurationMs / 1000 : DurationMs;
  const char *TimeUnit = DurationMs > 1000 ? "s" : "ms";
  outs() << Indent(--TimeRecorderDepth) << Prefix << " requires " << DisplayValue << TimeUnit
         << "!\n";
}

