    class TPortGuard : public NTesting::IPort, TNonCopyable {
    public:
        TPortGuard(ui16 assignedPort, THolder<TFileLock> acquiredLock)
            : Lock_(std::move(acquiredLock))
            , Port_(assignedPort)
        {
        }

        ~TPortGuard() override {
            try {
                if (!NFs::Remove(Lock_->GetName())) {
                    // If deletion fails (e.g., due to insufficient permissions),
                    // at least release the lock explicitly.
                    Lock_->Release();
                }
            } catch (const TSystemError& err) {
                Y_ABORT("Failed to unlock port %d, error=%d", Port_, err.Status());
            }
        }

        ui16 Get() override {
            return Port_;
        }

    private:
        THolder<TFileLock> Lock_;
        ui16 Port_;
    };

    std::pair<ui16, ui16> DetermineEphemeralRange() {
        // IANA-recommended range for dynamic/private ports
        std::pair<ui16, ui16> result{(1 << 15) + (1 << 14), (1 << 16) - 1};

#ifdef _linux_
        const TString path = "/proc/sys/net/ipv4/ip_local_port_range";
        if (NFs::Exists(path)) {
            TIFStream stream(path);
            stream >> result.first >> result.second;
        }
#endif

#ifdef _darwin_
        ui32 low, high;
        size_t len = sizeof(ui32);
        sysctlbyname("net.inet.ip.portrange.first", &low, &len, nullptr, 0);
        sysctlbyname("net.inet.ip.portrange.last", &high, &len, nullptr, 0);
        result.first = static_cast<ui16>(low);
        result.second = static_cast<ui16>(high);
#endif

        return result;
    }

    TVector<std::pair<ui16, ui16>> CollectAvailablePortRanges() {
        TString userSpecified = GetEnv("VALID_PORT_RANGE");
        TVector<std::pair<ui16, ui16>> ranges;

        if (userSpecified.Contains(':')) {
            auto parts = StringSplitter(userSpecified).Split(':').Limit(2).ToList<TString>();
            ranges.emplace_back(FromString<ui16>(parts.front()), FromString<ui16>(parts.back()));
        } else {
            const ui16 minStandard = 1025;
            const ui16 maxStandard = Max<ui16>();
            auto [minDynamic, maxDynamic] = DetermineEphemeralRange();

            const ui16 startExcluded = Max(minDynamic, minStandard);
            const ui16 endExcluded = Min(maxDynamic, maxStandard);

            if (startExcluded > minStandard) {
                ranges.emplace_back(minStandard, startExcluded - 1);
            }
            if (endExcluded < maxStandard) {
                ranges.emplace_back(endExcluded + 1, maxStandard);
            }
        }

        return ranges;
    }

    class TPortManager {
        static constexpr size_t MaxAttempts = 20;

    public:
        TPortManager() {
            InitializeFromEnvironment();
        }

        void InitializeFromEnvironment() {
            SyncDir_ = TFsPath(GetEnv("PORT_SYNC_PATH"));
            if (!SyncDir_.IsDefined()) {
                SyncDir_ = TFsPath(GetSystemTempDir()) / "testing_port_locks";
            }
            Y_ABORT_UNLESS(SyncDir_.IsDefined());
            NFs::MakeDirectoryRecursive(SyncDir_);
            Chmod(SyncDir_.c_str(), NFs::FP_COMMON_FILE); // override umask
            Ranges_ = CollectAvailablePortRanges();

            TotalCount_ = 0;
            for (const auto& [leftBound, rightBound] : Ranges_) {
                TotalCount_ += rightBound - leftBound;
            }
            Y_ABORT_UNLESS(TotalCount_ != 0);

            DisableRandomPorts_ = !GetEnv("NO_RANDOM_PORTS").empty();
        }

        NTesting::TPortHolder AcquireFreePort() const {
            ui16 offset = RandomNumber<ui16>();
            for (ui16 attempt = 0; attempt < TotalCount_; ++attempt) {
                ui16 candidate = (offset + attempt) % TotalCount_;
                for (const auto& [low, high] : Ranges_) {
                    if (candidate >= (high - low)) {
                        candidate -= (high - low);
                    } else {
                        candidate += low;
                        break;
                    }
                }
                auto guard = TryAcquirePort(candidate);
                if (guard) {
                    return NTesting::TPortHolder{std::move(guard)};
                }
            }
            Y_ABORT("Unable to allocate a free port!");
        }

        TVector<NTesting::TPortHolder> AcquireConsecutivePorts(size_t needed) const {
            Y_ABORT_UNLESS(needed > 0);
            TVector<NTesting::TPortHolder> collected;
            collected.Reserve(needed);

            for (size_t trial = 0; trial < MaxAttempts; ++trial) {
                for (const auto& [low, high] : Ranges_) {
                    if ((high - low) < needed) {
                        continue;
                    }

                    ui16 base = low + RandomNumber<ui16>((high - low) / 2);
                    if ((high - base) < needed) {
                        continue;
                    }

                    for (ui16 probe = base; probe < high; ++probe) {
                        auto guard = TryAcquirePort(probe);
                        if (guard) {
                            collected.emplace_back(std::move(guard));
                        } else {
                            collected.clear();
                        }

                        if (collected.size() == needed) {
                            return collected;
                        }
                    }

                    // Reset and try next range
                    collected.clear();
                }
            }

            Y_ABORT("Failed to reserve %zu consecutive ports!", needed);
        }

        NTesting::TPortHolder AcquireSpecificPort(ui16 requested) const {
            if (requested && DisableRandomPorts_) {
                auto guard = TryAcquirePort(requested);
                if (guard) {
                    return NTesting::TPortHolder{std::move(guard)};
                }
                Y_ABORT("Cannot reserve requested port %hu!", requested);
            }
            return AcquireFreePort();
        }

    private:
        THolder<NTesting::IPort> TryAcquirePort(ui16 port) const {
            TString lockFilePath = TString(SyncDir_ / ::ToString(port));
            auto lock = MakeHolder<TFileLock>(lockFilePath);

            if (!lock->TryAcquire()) {
                return nullptr;
            }

            TInet6StreamSocket socket;
            Y_ASSERT_SYSTEM_ERROR(INVALID_SOCKET != static_cast<SOCKET>(socket));

            TSockAddrInet6 addr("::", port);
            if (socket.Bind(&addr) != 0) {
                lock->Release();
                Y_ABORT_UNLESS(EADDRINUSE == LastSystemError(),
                               "Unexpected bind error: %d on port %d", LastSystemError(), port);
                return nullptr;
            }

            return MakeHolder<TPortGuard>(port, std::move(lock));
        }

    private:
        TFsPath SyncDir_;
        TVector<std::pair<ui16, ui16>> Ranges_;
        size_t TotalCount_;
        bool DisableRandomPorts_;
    };
}

namespace NTesting {
