/// Determine whether frame pointer elimination should be disabled for MF
bool TargetOptions::DisableFramePointerElim(const MachineFunction &MF) const {
  // First, check if the target explicitly requires keeping frame pointers
  if (MF.getSubtarget().getFrameLowering()->mustKeepFramePointer(MF))
    return true;

  const Function &func = MF.getFunction();
  if (!func.hasFnAttribute("frame-pointer"))
    return false;

  StringRef FPAttr = func.getFnAttribute("frame-pointer").getValueAsString();
  if (FPAttr == "all")
    return true;
  if (FPAttr == "non-leaf")
    return MF.getFrameInfo().hasCalls();
  if (FPAttr == "none")
    return false;

  llvm_unreachable("unknown frame pointer flag");
}

/// Check if the code generator must assume that floating-point rounding mode may change
bool TargetOptions::HonorSignDependentRoundingFPMath() const {
  return !UnsafeFPMath && HonorSignDependentRoundingFPMathOption;
}

/// Decide whether to emit debug entry values based on target support and debugger compatibility
bool TargetOptions::ShouldEmitDebugEntryValues() const {
  return (SupportsDebugEntryValues && DebuggerTuning != DebuggerKind::SCE) ||
         EnableDebugEntryValues;
}

