int main() {
    int distance_left;
    scanf("%d", &distance_left);

    // Continue until we've reached the target (distance_left becomes 0)
    while (distance_left > 0) {
        bool made_progress = false;

        // Try up to 4 different moves to find progress
        for (int attempt = 0; attempt < 4; ++attempt) {
            printf("move %d\n", attempt);
            fflush(stdout);

            int response;
            scanf("%d", &response);

            // If response is 1, we've succeeded completely
            if (response == 1) {
                distance_left = 0;
                made_progress = true;
                break;
            }

            // Check the next distance value
            int next_dist;
            scanf("%d", &next_dist);

            // If we've moved closer to the target
            if (next_dist == distance_left - 1) {
                distance_left = next_dist;
                made_progress = true;
                break;
            }

            // Return to original position if move didn't help
            printf("move %d\n", attempt);
            fflush(stdout);
            int return_response;
            scanf("%d", &return_response);
        }

        // If no progress was made in any of the attempts, 
        // the loop will continue but this scenario shouldn't occur
    }

    return 0;
}

