__inline void mic_fma4x80(const double* inv, double* outv, double* mulv)
{
    __mmask8 mask1 = _mm512_int2mask(0x0F);
    __mmask8 mask2 = _mm512_int2mask(0xF0);
    for(int idx = 0; idx < 80; idx += 40)
    {
        __m512d temp = _mm512_setzero_pd();
        temp = _mm512_extload_pd(&inv[idx], _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);
        __m512d mult = _mm512_load_pd(&mulv[idx]);
        __m512d acc = _mm512_load_pd(&outv[idx]);
        __m512d res = _mm512_fmadd_pd(temp, mult, acc);
        _mm512_store_pd(&outv[idx], res);

        mult = _mm512_load_pd(&mulv[idx + 8]);
        acc = _mm512_load_pd(&outv[idx + 8]);
        res = _mm512_fmadd_pd(temp, mult, acc);
        _mm512_store_pd(&outv[idx + 8], res);

        temp = _mm512_mask_extload_pd(temp, mask1, &inv[idx], _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);
        temp = _mm512_mask_extload_pd(temp, mask2, &inv[idx+20], _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);

        mult = _mm512_load_pd(&mulv[idx + 16]);
        acc = _mm512_load_pd(&outv[idx + 16]);
        res = _mm512_fmadd_pd(temp, mult, acc);
        _mm512_store_pd(&outv[idx + 16], res);

        temp = _mm512_extload_pd(&inv[idx+20], _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);
        mult = _mm512_load_pd(&mulv[idx + 24]);
        acc = _mm512_load_pd(&outv[idx + 24]);
        res = _mm512_fmadd_pd(temp, mult, acc);
        _mm512_store_pd(&outv[idx + 24], res);

        mult = _mm512_load_pd(&mulv[idx + 32]);
        acc = _mm512_load_pd(&outv[idx + 32]);
        res = _mm512_fmadd_pd(temp, mult, acc);
        _mm512_store_pd(&outv[idx + 32], res);
    }
}

void newviewGTRGAMMAPROT_MIC(int tipCase,
                  double *node1, double *node2, double *node3, double *extEV, double *tipVec,
                  int *ex3, unsigned char *tipData1, unsigned char *tipData2,
                  int count, double *leftMat, double *rightMat, int *weights, int *scaleInc, const pllBoolean fastScale)
{
  __m512d minLike_MIC = _mm512_set1_pd(PLL_MINLIKELIHOOD);
  __m512d scaleFactor_MIC = _mm512_set1_pd(PLL_TWOTOTHE256);
  __m512i absMask_MIC = _mm512_set1_epi64(0x7fffffffffffffffULL);
  int totalScale = 0;
  double aEV[1600] __attribute__((align(PLL_BYTE_ALIGNMENT)));
  #pragma ivdep
  for (int i = 0; i < 1600; ++i)
  {
      aEV[i] = extEV[(i / spanLen) * numStates + (i % numStates)];
  }

  switch(tipCase)
  {
    case PLL_TIP_TIP:
      {
        double umpX1[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        double umpX2[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        for(int i = 0; i < maxVal; ++i)
        {
          for(int k = 0; k < spanLen; ++k)
          {
              umpX1[i * spanLen + k] = 0.0;
              umpX2[i * spanLen + k] = 0.0;
              #pragma ivdep
              for(int l = 0; l < numStates; ++l)
              {
                  umpX1[i * spanLen + k] +=  tipVec[i * numStates + l] *  leftMat[k * numStates + l];
                  umpX2[i * spanLen + k] +=  tipVec[i * numStates + l] * rightMat[k * numStates + l];
              }
          }
        }

        for (int site = 0; site < count; site++)
        {
            const double *uX1 = &umpX1[spanLen * tipData1[site]];
            const double *uX2 = &umpX2[spanLen * tipData2[site]];
            double uX[spanLen] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double* v3 = &node3[site * spanLen];

            #pragma ivdep
            #pragma vector aligned
            for(int l = 0; l < spanLen; ++l)
            {
                uX[l] = uX1[l] * uX2[l];
                v3[l] = 0.;
            }

            for(int k = 0; k < numStates; ++k)
            {
                for (int j = 0; j < spanLen; j += 8)
                {
                    _mm_prefetch((const char *)&aEV[spanLen*(k+1) + j], _MM_HINT_T0);
                }
                mic_fma4x80(&uX[k], v3, &aEV[k * spanLen]);
            }

            if (!fastScale)
                ex3[site] = 0;
        }
      }
      break;

    case PLL_TIP_INNER:
      {
        double umpX1[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        for(int i = 0; i < maxVal; ++i)
        {
          for(int k = 0; k < spanLen; ++k)
          {
              umpX1[i * spanLen + k] = 0.0;
              #pragma ivdep
              for(int l = 0; l < numStates; ++l)
              {
                  umpX1[i * spanLen + k] +=  tipVec[i * numStates + l] *  leftMat[k * numStates + l];
              }
          }
        }

        double aRight[4 * stateSq] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        for(int j = 0; j < 4; j++)
        {
            for(int k = 0; k < numStates; k++)
            {
                for(int l = 0; l < numStates; l++)
                {
                    aRight[k * spanLen + j * numStates + l] = rightMat[j * stateSq +  l * numStates + k];
                }
            }
        }

        for (int site = 0; site < count; site++)
        {
            #pragma unroll(10)
            for (int j = 0; j < spanLen; j += 8)
            {
                _mm_prefetch((const char *)&node2[spanLen*(site+1) + j], _MM_HINT_T1);
            }

            double* uX1 = &umpX1[spanLen * tipData1[site]];
            double uX2[spanLen] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double uX[spanLen] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double* v3 = &(node3[spanLen * site]);
            const double* v2 = &(node2[spanLen * site]);

            #pragma vector aligned
            for(int l = 0; l < spanLen; ++l)
            {
                uX2[l] = 0.;
            }

            for(int k = 0; k < numStates; ++k)
            {
                for (int j = 0; j < spanLen; j += 8)
                {
                    _mm_prefetch((const char *)&aRight[spanLen*(k+1) + j], _MM_HINT_T0);
                }
                mic_fma4x80(&v2[k], uX2, &aRight[k * spanLen]);
            }

            #pragma ivdep
            #pragma vector aligned
            for(int l = 0; l < spanLen; ++l)
            {
                uX[l] = uX1[l] * uX2[l];
                v3[l] = 0.;
            }

            for(int k = 0; k < numStates; ++k)
            {
                for (int j = 0; j < spanLen; j += 8)
                {
                    _mm_prefetch((const char *)&aEV[spanLen*(k+1) + j], _MM_HINT_T0);
                }
                mic_fma4x80(&uX[k], v3, &aEV[k * spanLen]);
            }

            __m512d t1 = _mm512_load_pd(&v3[0]);
            t1 = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t1), absMask_MIC));
            double vmax = _mm512_reduce_gmax_pd(t1);
            double mx[16] __attribute__((align(PLL_BYTE_ALIGNMENT)));

            for (int l = 8; l < spanLen; l += 8)
            {
                __m512d t = _mm512_load_pd(&v3[l]);
                t = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t), absMask_MIC));
                double vmax2 = _mm512_reduce_gmax_pd(t);
                vmax = PLL_MAX(vmax, vmax2);
            }

            if (vmax < PLL_MINLIKELIHOOD)
            {
                #pragma vector aligned nontemporal
                for(int l = 0; l < spanLen; l++)
                  v3[l] *= PLL_TWOTOTHE256;

                if(!fastScale)
                  ex3[site] += 1;
                else
                  totalScale += weights[site];
            }
        }
      }
      break;

    case PLL_INNER_INNER:
    {
        double aLeft[4 * stateSq] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        double aRight[4 * stateSq] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        for(int j = 0; j < 4; j++)
        {
            for(int k = 0; k < numStates; k++)
            {
                for(int l = 0; l < numStates; l++)
                {
                    aLeft[k * spanLen + j * numStates + l] = leftMat[j * stateSq + l * numStates + k];
                    aRight[k * spanLen + j * numStates + l] = rightMat[j * stateSq + l * numStates + k];
                }
            }
        }

        for (int site = 0; site < count; site++)
        {
            #pragma unroll(10)
            for (int j = 0; j < spanLen; j += 8)
            {
                _mm_prefetch((const char *)&node1[spanLen*(site+1) + j], _MM_HINT_T1);
                _mm_prefetch((const char *)&node2[spanLen*(site+1) + j], _MM_HINT_T1);
            }

            double uX1[spanLen] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double uX2[spanLen] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double uX[spanLen] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double* v3 = &(node3[spanLen * site]);
            const double* v1 = &(node1[spanLen * site]);
            const double* v2 = &(node2[spanLen * site]);

            #pragma vector aligned
            for(int l = 0; l < spanLen; ++l)
            {
                uX1[l] = 0.;
                uX2[l] = 0.;
            }

            for(int k = 0; k < numStates; ++k)
            {
                for (int j = 0; j < spanLen; j += 8)
                {
                    _mm_prefetch((const char *)&aRight[spanLen*(k+1) + j], _MM_HINT_T0);
                    _mm_prefetch((const char *)&aLeft[spanLen*(k+1) + j], _MM_HINT_T0);
                }
                mic_fma4x80(&v1[k], uX1, &aLeft[k * spanLen]);
                mic_fma4x80(&v2[k], uX2, &aRight[k * spanLen]);
            }

            #pragma ivdep
            #pragma vector aligned
            for(int l = 0; l < spanLen; ++l)
            {
                uX[l] = uX1[l] * uX2[l];
                v3[l] = 0.;
            }

            for(int k = 0; k < numStates; ++k)
            {
                for (int j = 0; j < spanLen; j += 8)
                {
                    _mm_prefetch((const char *)&aEV[spanLen*(k+1) + j], _MM_HINT_T0);
                }
                mic_fma4x80(&uX[k], v3, &aEV[k * spanLen]);
            }

            __m512d t1 = _mm512_load_pd(&v3[0]);
            t1 = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t1), absMask_MIC));
            double vmax = _mm512_reduce_gmax_pd(t1);
            double mx[16] __attribute__((align(PLL_BYTE_ALIGNMENT)));

            for (int l = 8; l < spanLen; l += 8)
            {
                __m512d t = _mm512_load_pd(&v3[l]);
                t = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t), absMask_MIC));
                double vmax2 = _mm512_reduce_gmax_pd(t);
                vmax = PLL_MAX(vmax, vmax2);
            }

            if (vmax < PLL_MINLIKELIHOOD)
            {
                #pragma vector aligned nontemporal
                for(int l = 0; l < spanLen; l++)
                  v3[l] *= PLL_TWOTOTHE256;

                if(!fastScale)
                  ex3[site] += 1;
                else
                  totalScale += weights[site];
            }
        }
    } break;

    default:
      break;
  }

  *scaleInc = totalScale;
}

