#ifndef _LIBCPP_ABI_STRING_OPTIMIZED_EXTERNAL_INSTANTIATION
template <class _CharT, class _Traits, class _Allocator>
void basic_string<_CharT, _Traits, _Allocator>::__init(const value_type* __src, size_type __len, size_type __cap) {
  if (__libcpp_is_constant_evaluated())
    __rep_ = __rep();
  if (__cap > max_size())
    __throw_length_error();
  pointer __dest;
  if (__fits_in_sso(__cap)) {
    __set_short_size(__len);
    __dest = __get_short_pointer();
  } else {
    auto __alloc_result = std::__allocate_at_least(__alloc_, __recommend(__cap) + 1);
    __dest              = __alloc_result.ptr;
    __begin_lifetime(__dest, __alloc_result.count);
    __set_long_pointer(__dest);
    __set_long_cap(__alloc_result.count);
    __set_long_size(__len);
  }
  traits_type::copy(std::__to_address(__dest), __src, __len);
  traits_type::assign(__dest[__len], value_type());
  __annotate_new(__len);
}
