inline void throw_from_string_out_of_range(const string& func_name) {
  std::__throw_out_of_range((func_name + ": out of range").c_str());
}

inline void throw_from_string_invalid_arg(const string& func_name) {
  std::__throw_invalid_argument((func_name + ": no conversion").c_str());
}

// as_integer
template <typename ResultType, typename StringType, typename ConversionFunc>
inline ResultType as_integer_helper(const string& func_name, const StringType& input_str, size_t* idx, int base, ConversionFunc conv_func) {
  typename StringType::value_type* end_ptr                = nullptr;
  const typename StringType::value_type* const start_ptr  = input_str.c_str();
  __libcpp_remove_reference_t<decltype(errno)> saved_errno = errno;
  errno                                                    = 0;
  ResultType result                                        = conv_func(start_ptr, &end_ptr, base);
  swap(errno, saved_errno);

  if (saved_errno == ERANGE)
    throw_from_string_out_of_range(func_name);
  if (end_ptr == start_ptr)
    throw_from_string_invalid_arg(func_name);
  if (idx)
    *idx = static_cast<size_t>(end_ptr - start_ptr);
  return result;
}

template <typename ResultType, typename StringType>
inline ResultType as_integer(const string& func_name, const StringType& s, size_t* idx, int base);

// string specializations
template <>
inline int as_integer(const string& func_name, const string& s, size_t* idx, int base) {
  long temp_result = as_integer_helper<long>(func_name, s, idx, base, strtol);
  if (temp_result < numeric_limits<int>::min() || numeric_limits<int>::max() < temp_result)
    throw_from_string_out_of_range(func_name);
  return static_cast<int>(temp_result);
}

