// to_string
namespace {

// as_string
template <typename StringT, typename PrintFunc, typename ValueT>
inline StringT as_string(PrintFunc sprintf_like, StringT s, const typename StringT::value_type* fmt, ValueT val) {
  typedef typename StringT::size_type size_type;
  size_type buffer_capacity = s.size();
  while (true) {
    int status = sprintf_like(&s[0], buffer_capacity + 1, fmt, val);
    if (status >= 0) {
      size_type used_chars = static_cast<size_type>(status);
      if (used_chars <= buffer_capacity) {
        s.resize(used_chars);
        break;
      }
      buffer_capacity = used_chars; // Assume this is advice of how much space we need.
    } else
      buffer_capacity = buffer_capacity * 2 + 1;
    s.resize(buffer_capacity);
  }
  return s;
}

template <class S>
struct initial_string;
template <>
struct initial_string<string> {
  string operator()() const {
    string temp;
    temp.resize(temp.capacity());
    return temp;
  }
};

