template <typename StringT, typename ValueT>
StringT i_to_string(ValueT value) {
  //  numeric_limits::digits10 returns value less on 1 than desired for unsigned numbers.
  //  For example, for 1-byte unsigned value digits10 is 2 (999 can not be represented),
  //  so we need +1 here.
  constexpr size_t buffer_size = numeric_limits<ValueT>::digits10 + 2; // +1 for minus, +1 for digits10
  char buffer[buffer_size];
  const auto conversion_result = to_chars(buffer, buffer + buffer_size, value);
  _LIBCPP_ASSERT_INTERNAL(conversion_result.ec == errc(), "buffer must be large enough to accomodate the value");
  return StringT(buffer, conversion_result.ptr);
}

