#include "Scope.h"

Scope::Scope() {
    enterNewLevel();
}

void Scope::enterNewLevel() {
    nestingLevels.push(ScopeLevel());
}

void Scope::exitLevel() {
    nestingLevels.pop();
}

bool Scope::assignValue(string varName, shared_ptr<WrappedValue> value) {
    if (nestingLevels.top().valueTable[varName] != nullptr)
        return false;
    nestingLevels.top().valueTable[varName] = value;
    return true;
}

shared_ptr<WrappedValue> Scope::findValue(string varName) {
    stack<ScopeLevel> tempLevels = this->nestingLevels;
    while (!tempLevels.empty()) {
        shared_ptr<WrappedValue> val = tempLevels.top().valueTable[varName];
        if (val != nullptr)
            return val;
        tempLevels.pop();
    }
    return nullptr;
}

bool Scope::registerFunction(string funcName, llvm::Function *func) {
    if (nestingLevels.top().functionTable[funcName] != nullptr)
        return false;
    nestingLevels.top().functionTable[funcName] = func;
    return true;
}

llvm::Function* Scope::lookupFunction(string funcName) {
    stack<ScopeLevel> tempLevels = this->nestingLevels;
    while (!tempLevels.empty()) {
        llvm::Function *func = tempLevels.top().functionTable[funcName];
        if (func != nullptr)
            return func;
        tempLevels.pop();
    }
    return nullptr;
}

bool Scope::registerInlineAsm(string label, llvm::InlineAsm *asmObj) {
    if (nestingLevels.top().asmTable[label] != nullptr)
        return false;

    nestingLevels.top().asmTable[label] = asmObj;
    return true;
}

llvm::InlineAsm *Scope::lookupInlineAsm(string label) {
    stack<ScopeLevel> tempLevels = this->nestingLevels;
    while (!tempLevels.empty()) {
        llvm::InlineAsm *asmObj = tempLevels.top().asmTable[label];
        if (asmObj != nullptr)
            return asmObj;
        tempLevels.pop();
    }
    return nullptr;
}

bool Scope::defineStruct(string typeName, llvm::StructType *type, vector<string> fieldNames) {
    nestingLevels.top().structTypeTable[typeName] = type;
    nestingLevels.top().structFieldTable[typeName] = fieldNames;
    return true;
}

llvm::StructType *Scope::resolveStructType(string typeName) {
    stack<ScopeLevel> tempLevels = this->nestingLevels;
    while (!tempLevels.empty()) {
        llvm::StructType *type = tempLevels.top().structTypeTable[typeName];
        if (type != nullptr)
            return type;
        tempLevels.pop();
    }
    return nullptr;
}

optional<int> Scope::getFieldIndex(string typeName, string fieldName) {
    stack<ScopeLevel> tempLevels = this->nestingLevels;
    while (!tempLevels.empty()) {
        if (tempLevels.top().structFieldTable.contains(typeName)) {
            vector<string> fields = tempLevels.top().structFieldTable[typeName];
            for (int idx = 0; idx < fields.size(); idx++) {
                if (fields[idx].compare(fieldName) == 0)
                    return idx;
            }
        }
        tempLevels.pop();
    }
    return {};
}

#include "TuringTest.h"
#include "ByteBuffer.h"
#include "ByteBufferIterator.h"
using namespace turing::test;

class ByteBufferIteratorValidation : public TuringTest {
protected:
    void setup() override {
    }
    void cleanup() override {
    }
};

template <fs::TrivialPrimitive Type>
void addData(fs::ByteBuffer& buffer, std::vector<Type>& elements) {
    const size_t originalSize = buffer.size();
    const size_t additionalBytes = elements.size() * sizeof(Type);
    buffer.resize(originalSize + additionalBytes);
    std::memcpy(buffer.data() + originalSize, elements.data(), additionalBytes);
}

template <fs::TrivialPrimitive Type>
void addData(fs::ByteBuffer& buffer, Type value) {
    const size_t originalSize = buffer.size();
    const size_t byteCount = sizeof(Type);
    buffer.resize(originalSize + byteCount);
    std::memcpy(buffer.data() + originalSize, &value, byteCount);
}

template <fs::CharPrimitive CharType>
void addData(fs::ByteBuffer& buffer, std::basic_string_view<CharType> text) {
    const size_t originalSize = buffer.size();
    const size_t byteCount = text.size() * sizeof(CharType);
    buffer.resize(originalSize + byteCount);
    std::memcpy(buffer.data() + originalSize, text.data(), byteCount);
}

TEST_F(ByteBufferIteratorValidation, BasicFunctionality) {
    using namespace std::literals;
    fs::ByteBuffer buffer;

    // Prepare test data
    std::vector<uint16_t> shortIntegers = {0, 1, 2, 3, 4};
    std::vector<float> floatingPoints = {3.14159f, 1.61803f};

    addData(buffer, shortIntegers);
    addData(buffer, floatingPoints);
    addData(buffer, 2.71828);
    addData(buffer, "Hello world"sv);

    // Process and verify data
    fs::ByteBufferIterator iterator(buffer);

    std::span<const uint16_t> segment1 = iterator.get<uint16_t>(3);
    ASSERT_EQ(segment1[0], 0);
    ASSERT_EQ(segment1[1], 1);
    ASSERT_EQ(segment1[2], 2);

    ASSERT_EQ(iterator.get<uint16_t>(), 3);
    ASSERT_EQ(iterator.get<uint16_t>(), 4);

    ASSERT_NEAR(iterator.get<float>(), 3.14159f, 0.00001f);
    ASSERT_NEAR(iterator.get<float>(), 1.61803f, 0.00001f);

    ASSERT_NEAR(iterator.get<double>(), 2.71828, 0.00001);

    ASSERT_TRUE(iterator.get<char>(11) == "Hello world"sv);
}

int main(int argc, char** argv) {
    return turing::test::turingTestMain(argc, argv, [] {
        testing::GTEST_FLAG(repeat) = 4;
    });
}

#include <gtest/gtest.h>
#include <ocs2_core/ComputationRequest.h>
#include <ocs2_core/PreComputation.h>

using RequestSet = ocs2::Request;

TEST(testPrecomputation, convenientInterface) {
  // Verify that this compiles correctly
  ocs2::PreComputation preComp;
  preComp.request(RequestSet::Dynamics + RequestSet::Approximation, 0.5, ocs2::vector_t(), ocs2::vector_t());
  preComp.requestPreJump(RequestSet::Dynamics + RequestSet::Approximation, 1.0, ocs2::vector_t());
  preComp.requestFinal(RequestSet::Approximation, 2.0, ocs2::vector_t());
}

TEST(testPrecomputation, contains) {
  constexpr auto req = RequestSet::Dynamics + RequestSet::Cost + RequestSet::Constraint + RequestSet::SoftConstraint + RequestSet::Approximation;
  EXPECT_TRUE(req.contains(RequestSet::Dynamics));
  EXPECT_TRUE(req.contains(RequestSet::Cost));
  EXPECT_TRUE(req.contains(RequestSet::Constraint));
  EXPECT_TRUE(req.contains(RequestSet::SoftConstraint));
  EXPECT_TRUE(req.contains(RequestSet::Approximation));

  constexpr ocs2::RequestSet req2 = RequestSet::Cost;
  EXPECT_TRUE(req2.contains(RequestSet::Cost));
  EXPECT_FALSE(req2.contains(RequestSet::Dynamics));
  EXPECT_FALSE(req2.contains(RequestSet::Constraint));
  EXPECT_FALSE(req2.contains(RequestSet::SoftConstraint));
  EXPECT_FALSE(req2.contains(RequestSet::Approximation));

  constexpr auto req3 = RequestSet::Constraint + RequestSet::SoftConstraint;
  EXPECT_FALSE(req3.contains(RequestSet::Dynamics));
  EXPECT_FALSE(req3.contains(RequestSet::Cost));
  EXPECT_TRUE(req3.contains(RequestSet::Constraint));
  EXPECT_TRUE(req3.contains(RequestSet::SoftConstraint));
  EXPECT_FALSE(req3.contains(RequestSet::Approximation));
}

TEST(testPrecomputation, containsAnyAll) {
  constexpr auto reqA = RequestSet::Dynamics + RequestSet::Cost;
  constexpr auto reqB = RequestSet::Constraint + RequestSet::Cost;
  EXPECT_TRUE(reqA.containsAny(reqB));
  EXPECT_FALSE(reqA.containsAll(reqB));

  constexpr auto reqC = RequestSet::Constraint + RequestSet::Cost + RequestSet::Approximation;
  EXPECT_TRUE(reqC.containsAll(reqB));
}

