#include "plugin_tile_interface.h"
#include "ttile.h"

// Retrieve the raw memory address of a tile's raster data (unsafe operation)
int tile_interface_get_raw_address_unsafe(toonz_tile_handle_t handle,
                                          void **address) {
  if (!handle || !address) return -1;  // invalid input
  TTile *tile = reinterpret_cast<TTile *>(handle);
  tile->getRaster()->lock();
  *address = tile->getRaster()->getRawData();
  return 0;
}

// Safely unlock a tile's raster after access
int tile_interface_safen(toonz_tile_handle_t handle) {
  if (!handle) {
    return -1;  // invalid input
  }
  TTile *tile = reinterpret_cast<TTile *>(handle);
  tile->getRaster()->unlock();
  return 0;
}

// Get the stride (in bytes) between consecutive rows in the tile's raster
int tile_interface_get_raw_stride(toonz_tile_handle_t handle, int *stride) {
  if (!handle || !stride) return -1;  // invalid input
  TTile *tile = reinterpret_cast<TTile *>(handle);
  // Return stride in bytes, not pixels
  *stride = tile->getRaster()->getWrap() * tile->getRaster()->getPixelSize();
  return 0;
}

// Determine the pixel format type of the tile's raster
int tile_interface_get_element_type(toonz_tile_handle_t handle, int *element) {
  if (!handle || !element) return -1;  // invalid input
  TTile *tile     = reinterpret_cast<TTile *>(handle);
  TRasterP raster = tile->getRaster();

  if (false)
    ;
  else if (TRaster32P(raster))
    *element = TOONZ_TILE_TYPE_32P;
  else if (TRaster64P(raster))
    *element = TOONZ_TILE_TYPE_64P;
  else if (TRasterGR8P(raster))
    *element = TOONZ_TILE_TYPE_GR8P;
  else if (TRasterGR16P(raster))
    *element = TOONZ_TILE_TYPE_GR16P;
  else if (TRasterGRDP(raster))
    *element = TOONZ_TILE_TYPE_GRDP;
  else if (TRasterYUV422P(raster))
    *element = TOONZ_TILE_TYPE_YUV422P;
  else {
    *element = TOONZ_TILE_TYPE_NONE;
    return -1;
  }
  return 0;
}

// Copy a rectangular region from the tile to an external buffer
int tile_interface_copy_rect(toonz_tile_handle_t handle, int left, int top,
                             int width, int height, void *dst, int dststride) {
  if (!handle || !dst || !dststride) return -1;  // invalid input
  if (!width || !height) return 0;               // nothing to copy

  TTile *tile     = reinterpret_cast<TTile *>(handle);
  TRasterP raster = tile->getRaster();

  // Validate rectangle bounds
  if (!(0 <= left && left + width <= raster->getLx() && 0 <= top &&
        top + height <= raster->getLy())) {
    return -1;
  }

  for (int y = 0; y < height; y++) {
    memcpy((UCHAR *)dst + y * dststride, raster->getRawData(left, top + y),
           width * raster->getPixelSize());
  }
  return 0;
}

// Create a new tile as a copy of an existing one
int tile_interface_create_from(toonz_tile_handle_t handle,
                               toonz_tile_handle_t *newhandle) {
  if (!handle || !newhandle) return -1;  // invalid input
  TTile *tile    = reinterpret_cast<TTile *>(handle);
  TTile *newtile = new TTile(tile->getRaster());
  *newhandle     = reinterpret_cast<toonz_tile_handle_t *>(newtile);
  return 0;
}

// Create a new empty tile
int tile_interface_create(toonz_tile_handle_t *newhandle) {
  if (!newhandle) return -1;  // invalid input
  *newhandle = reinterpret_cast<toonz_tile_handle_t *>(new TTile());
  return 0;
}

// Destroy and deallocate a tile
int tile_interface_destroy(toonz_tile_handle_t handle) {
  if (!handle) return -1;  // invalid input
  TTile *tile = reinterpret_cast<TTile *>(handle);
  delete tile;
  return 0;
}

// Retrieve the bounding rectangle of a tile in global coordinates
int tile_interface_get_rectangle(toonz_tile_handle_t handle,
                                 toonz_rect_t *rect) {
  if (!handle || !rect) {
    return -1;  // invalid input
  }
  TTile *tile = reinterpret_cast<TTile *>(handle);
  rect->x0    = tile->m_pos.x;
  rect->y0    = tile->m_pos.y;
  rect->x1    = tile->m_pos.x + tile->getRaster()->getLx();
  rect->y1    = tile->m_pos.y + tile->getRaster()->getLy();
  return 0;
}

#include "client/renderer/block/Variant.hpp"
#include <sstream>
#include <stdexcept>

// Variant class implementation with JSON serialization support
Variant::Variant(ResourceLocation modelLoc, const ModelRotation& rot, bool lockUV, int w) :
    m_modelLocation(std::move(modelLoc)), m_rotation(rot), m_uvLock(lockUV), m_weight(w) {}

const ResourceLocation& Variant::getModelLocation() const { return m_modelLocation; }
const ModelRotation& Variant::getRotation() const { return m_rotation; }
bool Variant::isUvLock() const { return m_uvLock; }
int Variant::getWeight() const { return m_weight; }

bool Variant::operator==(const Variant& rhs) const {
    return m_modelLocation == rhs.m_modelLocation && 
           m_rotation == rhs.m_rotation && 
           m_uvLock == rhs.m_uvLock &&
           m_weight == rhs.m_weight;
}

bool Variant::operator!=(const Variant& rhs) const { return !(*this == rhs); }

std::size_t Variant::hashCode() const {
    // Hash computation following Java-style pattern: h = 31*h + next
    std::size_t hash = ResourceLocation::Hash{}(m_modelLocation);
    hash = 31 * hash + m_rotation.hashCode();
    hash = 31 * hash + std::hash<bool>{}(m_uvLock);
    hash = 31 * hash + static_cast<std::size_t>(m_weight);
    return hash;
}

std::string Variant::toString() const {
    std::ostringstream buffer;
    buffer << "Variant{"
           << "modelLocation=" << m_modelLocation.toString() << ", rotation=" << m_rotation.toString()
           << ", uvLock=" << (m_uvLock ? "true" : "false") << ", weight=" << m_weight << '}';
    return buffer.str();
}

static ResourceLocation resolveBlockResource(const std::string& modelName) {
    ResourceLocation base(modelName);
    return ResourceLocation(base.getResourceDomain(), "block/" + base.getResourcePath());
}

static ModelRotation extractModelRotation(const nlohmann::json& json) {
    int xAngle = json.value("x", 0);
    int yAngle = json.value("y", 0);
    auto result = ModelRotation::getModelRotation(xAngle, yAngle);
    if (!result)
        throw nlohmann::json::parse_error::create(
            101, 0, "Invalid BlockModelRotation x: " + std::to_string(xAngle) + ", y: " + std::to_string(yAngle), nullptr);
    return *result;
}

static int extractWeight(const nlohmann::json& json) {
    int value = json.value("weight", 1);
    if (value < 1)
        throw nlohmann::json::parse_error::create(
            101, 0, "Invalid weight " + std::to_string(value) + " found, expected integer >= 1", nullptr);
    return value;
}

Variant Variant::fromJson(const nlohmann::json& json) {
    const std::string modelPath = json.at("model").get<std::string>();
    ModelRotation rotation = extractModelRotation(json);
    bool uvLocked = json.value("uvlock", false);
    int weightValue = extractWeight(json);
    return Variant(resolveBlockResource(modelPath), rotation, uvLocked, weightValue);
}

void from_json(const nlohmann::json& json, Variant& variant) {
    const std::string modelPath = json.at("model").get<std::string>();
    ModelRotation rotation = extractModelRotation(json);
    bool uvLocked = json.value("uvlock", false);
    int weightValue = extractWeight(json);
    variant = Variant(resolveBlockResource(modelPath), rotation, uvLocked, weightValue);
}

void to_json(nlohmann::json& json, const Variant& variant) {
    json = nlohmann::json{
        {"model", variant.getModelLocation().toString()},
        {"x", variant.getRotation().getX()},
        {"y", variant.getRotation().getY()},
        {"uvlock", variant.isUvLock()},
        {"weight", variant.getWeight()}
    };
}

