void VolumeGenerator::process(Ctl &ctl)
{
    if (!validate(m_data))
        throw std::runtime_error("Invalid input data for EmbossCreateVolumeJob.");
    m_output_mesh = generate_mesh(*m_data.base_data, check_cancellation(ctl, *m_data.base_data), ctl);
}

void VolumeGenerator::finalize(bool canceled, std::exception_ptr &eptr)
{
    if (!::finish_processing(canceled, eptr, *m_data.base_data))
        return;
    if (m_output_mesh.its.empty())
        return display_message("Cannot create empty volume.");
    insert_volume(std::move(m_output_mesh), m_data.parent_object_id, m_data.volume_category, m_data.transform_matrix, *m_data.base_data,
                  m_data.active_gizmo);
}

/////////////////
/// Object Creation
ObjectGenerator::ObjectGenerator(ObjectCreationData &&input) : m_input_data(std::move(input))
{
    assert(validate(m_input_data));
}

void ObjectGenerator::process(Ctl &ctl)
{
    if (!validate(m_input_data))
        throw JobError("Invalid input data for EmbossCreateObjectJob.");

    // Cannot create new object with surface usage
    if (m_input_data.base_shape->shape.projection.use_surface)
        m_input_data.base_shape->shape.projection.use_surface = false;

    auto cancellation_check = ::check_cancellation(ctl, *m_input_data.base_shape);
    m_result_mesh = generate_mesh(*m_input_data.base_shape, cancellation_check, ctl);

    if (cancellation_check())
        return;

    // Calculate X,Y offset to position object on platter
    Vec2d bed_position = CameraUtils::get_z0_position(m_input_data.cam_params, m_input_data.screen_coordinates);

    // Check if point is within build plate:
    Points bed_polygon_;
    bed_polygon_.reserve(m_input_data.bed_contour.size());
    for (const Vec2d &point : m_input_data.bed_contour)
        bed_polygon_.emplace_back(point.cast<coord_t>());

    Slic3r::Polygon bed_boundary(bed_polygon_);
    if (!bed_boundary.contains(bed_position.cast<coord_t>()))
        // Mouse position is outside build plate, create object at center
        bed_position = bed_boundary.centroid().cast<double>();

    double z = m_input_data.base_shape->shape.projection.depth / 2;
    Vec3d offset(bed_position.x(), bed_position.y(), z);
    offset -= m_result_mesh.center();

    Transform3d::TranslationType tt(offset.x(), offset.y(), offset.z());
    m_final_transform = Transform3d(tt);

    // Apply Z-axis rotation from style settings
    if (m_input_data.z_rotation.has_value())
    {
        std::optional<float> distance; // new object ignores surface distance
        apply_transformation(m_input_data.z_rotation, distance, m_final_transform);
    }
}

void ObjectGenerator::finalize(bool canceled, std::exception_ptr &eptr)
{
    if (!::finish_processing(canceled, eptr, *m_input_data.base_shape))
        return;

    // Safety check
    if (m_result_mesh.empty())
        return display_message("Cannot create empty object.");

    GUI_App &app = wxGetApp();
    Plater *plater = app.plater();
    plater->take_snapshot(_L("Add Emboss text object"));
    Model &model = plater->model();

#ifdef _DEBUG
    validate_model_ids(model);
#endif /* _DEBUG */

    {
        // Create new object following pattern from ObjectList::load_mesh_object()
        ModelObject *new_object = model.add_object();
        new_object->name = m_input_data.base_shape->volume_label;
        new_object->add_instance(); // Each object needs at least one instance
        ModelVolume *new_volume = new_object->add_volume(std::move(m_result_mesh));

        // Set default extruder value since user cannot add manually
        new_volume->config.set_key_value("extruder", new ConfigOptionInt(0));

        // Write emboss data into volume
        m_input_data.base_shape->apply_to_volume(*new_volume);

        // Apply transformation
        Slic3r::Geometry::Transformation tr(m_final_transform);
        new_object->instances.front()->set_transformation(tr);
        new_object->instances.front()->set_offset(
            new_object->instances.front()->get_offset() +
            s_multiple_beds.get_bed_translation(s_multiple_beds.get_active_bed()));
        new_object->ensure_on_bed();

        // Update right panel and selection
        app.obj_list()->paste_objects_into_list({model.objects.size() - 1});
    }

#ifdef _DEBUG
    validate_model_ids(model);
#endif /* _DEBUG */

    // When adding new object, selection might be empty
    // When cursor moves and no object selected, Manager::reset_all() closes Gizmo
    GLCanvas3D *canvas = plater->canvas3D();
    GLGizmosManager &manager = canvas->get_gizmos_manager();
    if (manager.get_current_type() != m_input_data.gizmo_type)
        manager.open_gizmo(m_input_data.gizmo_type);

    // Redraw scene
    canvas->reload_scene(true);
}

/////////////////
/// Volume Update
UpdateJob::UpdateJob(DataUpdate &&input) : m_input(std::move(input))
{
    assert(validate(m_input, true));
}

void UpdateJob::process(Ctl &ctl)
{
    if (!validate(m_input))
        throw JobError("Invalid input data for EmbossUpdateJob.");

    auto cancellation_check = ::check_cancellation(ctl, *m_input.base);
    m_result = ::attempt_create_mesh(*m_input.base, cancellation_check);

    if (cancellation_check())
        return;

    if (m_result.its.empty())
        throw JobError("Created text volume is empty. Change text or font.");
}

void UpdateJob::finalize(bool canceled, std::exception_ptr &eptr)
{
    if (!::finish_processing(canceled, eptr, *m_input.base))
        return;

    ::complete_volume_update(std::move(m_result), m_input);
}

void UpdateJob::update_volume(ModelVolume *volume, TriangleMesh &&mesh, const DataBase &base)
{
    // Validate inputs
    bool valid_inputs = volume != nullptr && !mesh.empty() && !base.volume_label.empty();
    assert(valid_inputs);
    if (!valid_inputs)
        return;

    // Update volume
    volume->set_mesh(std::move(mesh));
    volume->set_new_unique_id();
    volume->calculate_convex_hull();

    // Write data from base into volume
    base.apply_to_volume(*volume);

    GUI_App &app = wxGetApp(); // could be moved to input

    if (volume->name != base.volume_label)
    {
        volume->name = base.volume_label;
        const ObjectList *obj_list = app.obj_list();
        if (obj_list != nullptr)
            refresh_name_display(*obj_list, *volume);
    }

    ModelObject *object = volume->get_object();
    assert(object != nullptr);
    if (object == nullptr)
        return;

    Plater *plater = app.plater();
    if (plater->printer_technology() == ptSLA)
        plater->changed_object(*object);
}

