SurfaceVolumeData::ModelSources generate_volume_sources(const ModelVolume &text_volume)
{
    const ModelVolumePtrs &volumes = text_volume.get_object()->volumes;
    // No other volume in object
    if (volumes.size() <= 1)
        return {};

    return ::extract_sources(volumes, text_volume.id().id);
}

bool initiate_volume_creation(CreateVolumeParams &input, const Vec2d &mouse_pos)
{
    if (input.data == nullptr)
        return false;

    if (!validate(input))
        return false;

    if (input.gl_volume == nullptr)
        // Object not under mouse position, create object on plater
        return ::initiate_object_creation_job(input, mouse_pos);

    bool try_without_coor = true;
    return ::initiate_surface_volume_job(input, mouse_pos, try_without_coor);
}

bool initiate_volume_creation_without_position(CreateVolumeParams &input)
{
    assert(input.data != nullptr);
    if (input.data == nullptr)
        return false;

    if (!validate(input))
        return false;

    // Select position based on camera position and view direction
    const Selection &selection = input.canvas.get_selection();
    int object_idx = selection.get_object_idx();
    Size canvas_size = input.canvas.get_canvas_size();
    Vec2d screen_center(canvas_size.get_width() / 2., canvas_size.get_height() / 2.);
    const ModelObjectPtrs &objects = selection.get_model()->objects;

    // No selected object, create new object
    if (selection.is_empty() || object_idx < 0 || static_cast<size_t>(object_idx) >= objects.size())
        // Create Object at center of screen
        // When ray through center doesn't hit bed, creates object at center of bed
        return ::initiate_object_creation_job(input, screen_center);

    // Create volume inside selected object
    Vec2d coor;
    const Camera &camera = wxGetApp().plater()->get_camera();
    input.gl_volume = ::find_nearest_volume(selection, screen_center, camera, objects, &coor);

    if (input.gl_volume == nullptr)
        return ::initiate_object_creation_job(input, screen_center);

    bool try_without_coor = false;
    return ::initiate_surface_volume_job(input, coor, try_without_coor);
}

