// Run Job on main thread (blocking) - ONLY DEBUG
static inline bool execute_job_direct(std::shared_ptr<Job> j)
{
    struct MyCtl : public Job::Ctl
    {
        void update_status(int st, const std::string &msg = "") override {};
        bool was_canceled() const override { return false; }
        std::future<void> call_on_main_thread(std::function<void()> fn) override { return std::future<void>{}; }
    } ctl;

    j->process(ctl);
    wxGetApp().plater()->CallAfter(
        [j]()
        {
            std::exception_ptr e_ptr = nullptr;
            j->finalize(false, e_ptr);
        });
    return true;
}
} // namespace
#endif

bool initiate_volume_update(DataUpdate &&data, const ModelVolume &volume, const Selection &selection,
                            RaycastManager &raycaster)
{
    assert(data.volume_id == volume.id());

    // Check cutting from source mesh
    bool &use_surface = data.base->shape.projection.use_surface;
    if (use_surface && volume.is_the_only_one_part())
        use_surface = false;

    std::unique_ptr<Job> job = nullptr;
    if (use_surface)
    {
        // Model to cut surface from.
        SurfaceVolumeData::ModelSources sources = generate_volume_sources(volume);
        if (sources.empty())
            return false;

        Transform3d volume_transform = volume.get_matrix();
        const std::optional<Transform3d> &fix_3mf = volume.emboss_shape->fix_3mf_tr;
        if (fix_3mf.has_value())
            volume_transform = volume_transform * fix_3mf->inverse();

        // When first applying surface, move origin onto surface
        if (!volume.emboss_shape->projection.use_surface)
        {
            auto offset = calculate_surface_offset(selection, raycaster);
            if (offset.has_value())
                volume_transform *= Eigen::Translation<double, 3>(*offset);
        }

        UpdateSurfaceVolumeData surface_data{std::move(data), {volume_transform, std::move(sources)}};
        job = std::make_unique<UpdateSurfaceVolumeJob>(std::move(surface_data));
    }
    else
    {
        job = std::make_unique<UpdateJob>(std::move(data));
    }

#ifndef EXECUTE_UPDATE_ON_MAIN_THREAD
    auto &worker = wxGetApp().plater()->get_ui_job_worker();
    return queue_job(worker, std::move(job));
#else
    // Run Job on main thread (blocking) - ONLY DEBUG
    return execute_job_direct(std::move(job));
#endif // EXECUTE_UPDATE_ON_MAIN_THREAD
}

