namespace vllm {

template <typename T, int64_t rot_dim, bool neox_mode>
class deepseek_scaling_rope_kernel_v2 {
 public:
  static constexpr int sub_group_thread_count = 16;

  deepseek_scaling_rope_kernel_v2(
      const int64_t* pos_data,
      const T* q_in,
      const T* k_in,
      const int64_t* off_data,
      const T* cache_cos_sin,
      T* q_out,
      T* k_out,
      const int64_t batch_size,
      const int64_t num_q_heads,
      const int64_t num_k_heads,
      const int64_t head_dim,
      const int64_t stride_q_head,
      const int64_t stride_q_batch,
      const int64_t stride_k_head,
      const int64_t stride_k_batch)
      : positions(pos_data),
        query(q_in),
        key(k_in),
        offsets(off_data),
        cos_sin_cache(cache_cos_sin),
        query_output(q_out),
        key_output(k_out),
        batch(batch_size),
        q_num_heads(num_q_heads),
        k_num_heads(num_k_heads),
        head_size(head_dim),
        q_head_stride(stride_q_head),
        q_batch_stride(stride_q_batch),
        k_head_stride(stride_k_head),
        k_batch_stride(stride_k_batch) {}

  void apply_rotary_embedding(
      const int64_t pos,
      const T* input_vec,
      const T* cache,
      T* output_vec) const {
    constexpr int64_t half_rot = rot_dim / 2;
    constexpr int64_t vec_len_2 = 2;
    using v2_type = sycl::vec<T, vec_len_2>;

    const int64_t cache_offset = pos * rot_dim;
    const T* cos_ptr = &cache[cache_offset];
    const T* sin_ptr = cos_ptr + half_rot;

    if constexpr (neox_mode) {
      for (int64_t idx = 0; idx < half_rot; ++idx) {
        int64_t opp_idx = idx + half_rot;
        T c_val = cos_ptr[idx];
        T s_val = sin_ptr[idx];
        output_vec[idx] = input_vec[idx] * c_val - input_vec[opp_idx] * s_val;
        output_vec[opp_idx] = input_vec[opp_idx] * c_val + input_vec[idx] * s_val;
      }
    } else {
      const v2_type* in_v2 = reinterpret_cast<const v2_type*>(input_vec);
      v2_type* out_v2 = reinterpret_cast<v2_type*>(output_vec);
      for (int64_t h = 0; h < half_rot; ++h) {
        T c = cos_ptr[h];
        T s = sin_ptr[h];
        v2_type c_pair = {c, c};
        v2_type s_pair = {s, s};
        v2_type val = in_v2[h];
        v2_type* dst = &out_v2[h];
        v2_type rotated = {-val[1], val[0]};
        *dst = val * c_pair + rotated * s_pair;
      }
    }
  }

  [[sycl::reqd_sub_group_size(sub_group_thread_count)]]
  void operator()(sycl::nd_item<3> item) const {
    int64_t batch_id = item.get_global_id(0);
    int64_t group_id = item.get_local_id(1);
    int64_t local_tid = item.get_global_id(2);
    int64_t head_id = group_id * sub_group_thread_count + local_tid;

    int64_t qo_offset = batch_id * q_num_heads * head_size + head_id * head_size;
    int64_t ko_offset = batch_id * k_num_heads * head_size +
                        (head_id - q_num_heads) * head_size;

    int64_t qi_offset = batch_id * q_batch_stride + head_id * q_head_stride;
    int64_t ki_offset = batch_id * k_batch_stride +
                        (head_id - q_num_heads) * k_head_stride;

    if (head_id < q_num_heads) {
      apply_rotary_embedding(
          positions[batch_id],
          &query[qi_offset],
          cos_sin_cache,
          &query_output[qo_offset]);
    } else if (head_id < q_num_heads + k_num_heads) {
      apply_rotary_embedding(
          positions[batch_id],
          &key[ki_offset],
          cos_sin_cache,
          &key_output[ko_offset]);
    }
  }

 private:
  const int64_t* positions;
  const T* query;
  const T* key;
  const int64_t* offsets;
  const T* cos_sin_cache;
  T* query_output;
  T* key_output;
  const int64_t batch;
  const int64_t q_num_heads;
  const int64_t k_num_heads;
  const int64_t head_size;
  const int64_t q_head_stride;
  const int64_t q_batch_stride;
  const int64_t k_head_stride;
  const int64_t k_batch_stride;
};

}  // namespace vllm

template <typename T>
void call_deepseek_scaling_rope_v2(
    const int64_t* pos,
    const T* q_in,
    const T* k_in,
    const int64_t* off,
    const T* cache,
    T* q_out,
    T* k_out,
    int64_t bsz,
    int64_t nq,
    int64_t nk,
    int64_t hs,
    int64_t rot_dim,
    bool neox,
    int64_t qhd,
    int64_t qbd,
    int64_t khd,
    int64_t kbd) {
  static constexpr std::array<int, 5> valid_dims = {32, 64, 96, 128, 256};
  auto it = std::find(valid_dims.begin(), valid_dims.end(), rot_dim);
  TORCH_CHECK(
      it != valid_dims.end(),
      "Invalid rotary_dim (",
      rot_dim,
      "). Supported: 32,64,96,128,256");

  TORCH_CHECK(
      rot_dim == hs,
      "rotary_dim (",
      rot_dim,
      ") must equal head_size (",
      hs,
      ")");

  const int dim_index = std::distance(valid_dims.begin(), it);
  const int mode_index = neox ? 1 : 0;
  const int func_index = mode_index * valid_dims.size() + dim_index;

  using LaunchFunc = void (*)(
      sycl::queue&,
      const int64_t*,
      const T*,
      const T*,
      const int64_t*,
      const T*,
      T*,
      T*,
      int64_t,
      int64_t,
      int64_t,
      int64_t,
      int64_t,
      int64_t,
      int64_t,
      int64_t);

#define REGISTER_CASE(dim, neox)                                           \
  [](sycl::queue& q,                                                       \
     const int64_t* pos_arr,                                               \
     const T* q_ptr,                                                       \
     const T* k_ptr,                                                       \
     const int64_t* off_ptr,                                               \
     const T* cache_ptr,                                                   \
     T* q_res,                                                             \
     T* k_res,                                                             \
     int64_t b,                                                            \
     int64_t qh,                                                           \
     int64_t kh,                                                           \
     int64_t hs_val,                                                       \
     int64_t qhd_val,                                                      \
     int64_t qbd_val,                                                      \
     int64_t khd_val,                                                      \
     int64_t kbd_val) {                                                    \
    constexpr int sg_threads = 16;                                         \
    int64_t groups_per_head = (qh + kh + sg_threads - 1) / sg_threads;     \
    sycl::range<3> local_range(1, groups_per_head, sg_threads);            \
    sycl::range<3> global_range(b, groups_per_head, sg_threads);           \
    at::DeviceGuard guard(at::Device(at::kXPU, at::xpu::current_device()));\
    q.submit([&](sycl::handler& cgh) {                                     \
      cgh.parallel_for(                                                    \
          sycl::nd_range<3>(global_range, local_range),                    \
          vllm::deepseek_scaling_rope_kernel_v2<T, dim, neox>{             \
              pos_arr,                                                     \
              q_ptr,                                                       \
              k_ptr,                                                       \
              off_ptr,                                                     \
              cache_ptr,                                                   \
              q_res,                                                       \
              k_res,                                                       \
              b,                                                           \
              qh,                                                          \
              kh,                                                          \
              hs_val,                                                      \
              qhd_val,                                                     \
              qbd_val,                                                     \
              khd_val,                                                     \
              kbd_val});                                                   \
    });                                                                    \
  }

  static constexpr std::array<LaunchFunc, valid_dims.size() * 2> dispatch_table = {
      REGISTER_CASE(32, false),
      REGISTER_CASE(64, false),
      REGISTER_CASE(96, false),
      REGISTER_CASE(128, false),
      REGISTER_CASE(256, false),
      REGISTER_CASE(32, true),
      REGISTER_CASE(64, true),
      REGISTER_CASE(96, true),
      REGISTER_CASE(128, true),
      REGISTER_CASE(256, true),
  };

#undef REGISTER_CASE

  auto& queue = vllm::xpu::vllmGetQueue();
  dispatch_table[func_index](
      queue,
      pos,
      q_in,
      k_in,
      off,
      cache,
      q_out,
      k_out,
      bsz,
      nq,
      nk,
      hs,
      qhd,
      qbd,
      khd,
      kbd);
}

/**
 * @brief Perform deepseek rotary embedding with q&k.
 * @param positions index of embedding [batch]
 * @param query query to be processed [batch, num_head, head_dim]
 * @param key key to be processed [batch, num_head, head_dim]
 * @param offsets optional tensor for offset with position
 * @param cos_sin_cache shared cache with cos/sin
 * @param is_neox choose interleave or half.
 * @return A tuple of tensors (query_out, key_out).
 */
std::tuple<torch::Tensor, torch::Tensor> deepseek_scaling_rope_v2(
    const torch::Tensor& positions,
    const torch::Tensor& query,
    const torch::Tensor& key,
    const c10::optional<torch::Tensor>& offsets_opt,
    const torch::Tensor& cos_sin_cache,
    int64_t rotary_dim,
    bool is_neox) {
  auto query_out = at::empty_like(query);
  auto key_out = at::empty_like(key);

  auto q_shape = query.sizes();
  auto q_strides = query.strides();
  int64_t head_dim = q_shape[2];
  int64_t num_q_heads = q_shape[1];
  int64_t batch_size = q_shape[0];
  int64_t q_head_stride = q_strides[1];
  int64_t q_batch_stride = q_strides[0];

  auto k_shape = key.sizes();
  auto k_strides = key.strides();
  int64_t num_k_heads = k_shape[1];
  int64_t k_head_stride = k_strides[1];
  int64_t k_batch_stride = k_strides[0];

  if (is_neox) {
    query_out = query_out.reshape({1, batch_size, num_q_heads, head_dim});
    key_out = key_out.reshape({1, batch_size, num_k_heads, head_dim});
  }

  TORCH_CHECK(
      cos_sin_cache.sizes()[1] == head_dim,
      "Rotary dim doesn't match query head_size");
  TORCH_CHECK(
      cos_sin_cache.sizes()[1] == k_shape[2],
      "Rotary dim doesn't match key head_size");

  const c10::MaybeOwned<torch::Tensor> offsets_maybe_owned =
      at::borrow_from_optional_tensor(offsets_opt);
  const torch::Tensor& offsets = *offsets_maybe_owned;
  auto offsets_ptr = offsets.defined() ? offsets.data_ptr() : nullptr;

  switch (query.scalar_type()) {
    case torch::kFloat:
      call_deepseek_scaling_rope_v2<float>(
          reinterpret_cast<int64_t*>(positions.data_ptr()),
          reinterpret_cast<float*>(query.data_ptr()),
          reinterpret_cast<float*>(key.data_ptr()),
          reinterpret_cast<int64_t*>(offsets_ptr),
          reinterpret_cast<float*>(cos_sin_cache.data_ptr()),
          reinterpret_cast<float*>(query_out.data_ptr()),
          reinterpret_cast<float*>(key_out.data_ptr()),
          batch_size,
          num_q_heads,
          num_k_heads,
          head_dim,
          rotary_dim,
          is_neox,
          q_head_stride,
          q_batch_stride,
          k_head_stride,
          k_batch_stride);
      break;
    case torch::kFloat16:
      call_deepseek_scaling_rope_v2<sycl::half>(
          reinterpret_cast<int64_t*>(positions.data_ptr()),
          reinterpret_cast<sycl::half*>(query.data_ptr()),
          reinterpret_cast<sycl::half*>(key.data_ptr()),
          reinterpret_cast<int64_t*>(offsets_ptr),
          reinterpret_cast<sycl::half*>(cos_sin_cache.data_ptr()),
          reinterpret_cast<sycl::half*>(query_out.data_ptr()),
          reinterpret_cast<sycl::half*>(key_out.data_ptr()),
          batch_size,
          num_q_heads,
          num_k_heads,
          head_dim,
          rotary_dim,
          is_neox,
          q_head_stride,
          q_batch_stride,
          k_head_stride,
          k_batch_stride);
      break;
    case torch::kBFloat16:
      call_deepseek_scaling_rope_v2<sycl::ext::oneapi::bfloat16>(
          reinterpret_cast<int64_t*>(positions.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(query.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(key.data_ptr()),
          reinterpret_cast<int64_t*>(offsets_ptr),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(
              cos_sin_cache.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(query_out.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(key_out.data_ptr()),
          batch_size,
          num_q_heads,
          num_k_heads,
          head_dim,
          rotary_dim,
          is_neox,
          q_head_stride,
          q_batch_stride,
          k_head_stride,
          k_batch_stride);
      break;
    default:
      throw std::invalid_argument(
          "Invalid dtype, only supports float32, float16, and bfloat16");
  }

  return {query_out, key_out};
}

