    // Rationale: more than one HWND on the list is extremely uncommon, hence forward_list
    static std::forward_list<HWND> g_activeEdits;
    static HHOOK g_mouseHook = NULL /*, g_kbHook = NULL*/;

    static void TerminateInput(HWND editBox, t_uint32 reason) {
        CWindow parent = ::GetParent(editBox);
        parent.SendMessage(MSG_STOP_INPUT_MODE);
        parent.PostMessage(MSG_COMPLETE_INPUT, reason, 0);
    }

