    static bool AreSamePopup(CWindow windowA, CWindow windowB) {
        return pfc::findOwningPopup(windowA) == pfc::findOwningPopup(windowB);
    }

    static void HandleMouseInteraction(HWND target, CPoint position, bool isWheelEvent) {
        for (CWindow edit : g_activeEdits) {
            bool shouldCancel = false;
            if (target != edit && AreSamePopup(target, edit)) {
                shouldCancel = true;
            } else if (isWheelEvent) {
                CWindow hitTest = WindowFromPoint(position);
                if (hitTest != edit && AreSamePopup(hitTest, edit)) {
                    shouldCancel = true;
                }
            }

            if (shouldCancel) TerminateInput(edit, KLostFocusReason);
        }
    }

    static LRESULT CALLBACK MouseFilterProc(int nCode, WPARAM wParam, LPARAM lParam) {
        if (nCode == HC_ACTION) {
            const MOUSEHOOKSTRUCT* mhs = reinterpret_cast<const MOUSEHOOKSTRUCT*>(lParam);
            switch (wParam) {
            case WM_NCLBUTTONDOWN:
            case WM_NCRBUTTONDOWN:
            case WM_NCMBUTTONDOWN:
            case WM_NCXBUTTONDOWN:
            case WM_LBUTTONDOWN:
            case WM_RBUTTONDOWN:
            case WM_MBUTTONDOWN:
            case WM_XBUTTONDOWN:
                HandleMouseInteraction(mhs->hwnd, mhs->pt, false);
                break;
            case WM_MOUSEWHEEL:
            case WM_MOUSEHWHEEL:
                HandleMouseInteraction(mhs->hwnd, mhs->pt, true);
                break;
            }
        }
        return CallNextHookEx(g_mouseHook, nCode, wParam, lParam);
    }

    static void RegisterEditBox(HWND newEdit) {
        // PFC_ASSERT(core_api::is_main_thread());
        g_activeEdits.push_front(newEdit);
        if (g_mouseHook == NULL) {
            g_mouseHook = SetWindowsHookEx(WH_MOUSE, MouseFilterProc, NULL, GetCurrentThreadId());
        }
        /*if (g_kbHook == NULL) {
            g_kbHook = SetWindowsHookEx(WH_KEYBOARD, KeyboardFilterProc, NULL, GetCurrentThreadId());
        }*/
    }

    static void UnregisterHook(HHOOK& hookRef) {
        HHOOK temp = pfc::replace_null_t(hookRef);
        if (temp != NULL) UnhookWindowsHookEx(temp);
    }

    static void DeregisterEditBox(HWND oldEdit) {
        // PFC_ASSERT(core_api::is_main_thread());
        g_activeEdits.remove(oldEdit);
        if (g_activeEdits.empty()) {
            UnregisterHook(g_mouseHook); /*UnregisterHook(g_kbHook);*/
        }
    }

    class CInlineEditor : public CWindowImpl<CInlineEditor, CEdit> {
