            MSG_WM_KEYDOWN(OnKeyDownInput)
            MSG_WM_PASTE(OnPasteAction)
        END_MSG_MAP()

        void OnInitialize() {
            RegisterEditBox(m_hWnd);
        }

    private:
        void OnDestroyEditor() {
            m_autoDelete = true;
            DeregisterEditBox(m_hWnd);
            SetMsgHandled(FALSE);
        }

        int OnCreate(LPCREATESTRUCT) {
            OnInitialize();
            SetMsgHandled(FALSE);
            return 0;
        }

        UINT OnDialogCode(LPMSG lpMsg) {
            if (lpMsg == nullptr) {
                SetMsgHandled(FALSE); return 0;
            } else {
                switch (lpMsg->message) {
                case WM_KEYDOWN:
                case WM_SYSKEYDOWN:
                    switch (lpMsg->wParam) {
                    case VK_TAB:
                    case VK_ESCAPE:
                    case VK_RETURN:
                        return DLGC_WANTMESSAGE;
                    default:
                        SetMsgHandled(FALSE); return 0;
                    }
                default:
                    SetMsgHandled(FALSE); return 0;
                }
            }
        }

        void OnFocusLost(CWindow focusTarget) {
            if (focusTarget != NULL) ForwardResult(KLostFocusReason);
            SetMsgHandled(FALSE);
        }

        bool ValidatePaste(const char* text) {
            if (m_options & InPlaceEdit::KAllowSignedNumber) {
                if (pfc::string_is_numeric(text)) return true;
                if (text[0] == '-' && pfc::string_is_numeric(text + 1) && GetWindowTextLength() == 0) return true;
                return false;
            }
            if (m_options & InPlaceEdit::KAllowUnsignedNumber) {
                return pfc::string_is_numeric(text);
            }
            return true;
        }

        void OnPasteAction() {
            if (m_options & (InPlaceEdit::KAllowNumber | InPlaceEdit::KAllowSignedNumber)) {
                pfc::string8 buffer;
                ClipboardHelper::OpenScope scope; scope.Open(m_hWnd);
                if (ClipboardHelper::GetString(buffer)) {
                    if (!ValidatePaste(buffer)) return;
                }
            }
            SetMsgHandled(FALSE);
        }

        bool ValidateChar(UINT ch) {
            if (ch < ' ') return true;

            if (m_options & InPlaceEdit::KAllowSignedNumber) {
                if (pfc::char_is_numeric(ch)) return true;
                if (ch == '-') {
                    return GetWindowTextLength() == 0;
                }
                return false;
            }
            if (m_options & InPlaceEdit::KAllowUnsignedNumber) {
                return pfc::char_is_numeric(ch);
            }
            return true;
        }

        void OnCharacterInput(UINT ch, UINT repeat, UINT flags) {
            (void)repeat;
            if (m_ignoreNextKey != 0) {
                UINT scan = flags & 0xFF;
                if (scan == m_ignoreNextKey) return;
            }

            if (!ValidateChar(ch)) {
                MessageBeep(0);
                return;
            }

            SetMsgHandled(FALSE);
        }

        void OnKeyDownInput(UINT vk, UINT repeat, UINT flags) {
            (void)repeat;
            m_ignoreNextKey = flags & 0xFF;
            switch (vk) {
            case VK_BACK:
                if (GetHotkeyModifierFlags() == MOD_CONTROL) {
                    CEditPPHooks::DeleteLastWord(*this);
                    return;
                }
                break;
            case 'A':
                if (GetHotkeyModifierFlags() == MOD_CONTROL) {
                    this->SetSelAll(); return;
                }
                break;
            case VK_RETURN:
                if (!IsKeyPressed(VK_LCONTROL) && !IsKeyPressed(VK_RCONTROL)) {
                    ForwardResult(KEnterPressed);
                    return;
                }
                break;
            case VK_TAB:
                ForwardResult(IsKeyPressed(VK_SHIFT) ? KShiftTabPressed : KTabPressed);
                return;
            case VK_ESCAPE:
                ForwardResult(KAborted);
                return;
            }
            m_ignoreNextKey = 0;
            SetMsgHandled(FALSE);
        }

        void ForwardResult(t_uint32 code) {
            if (IsWindowEnabled()) {
                CWindow owner = GetParent();
                owner.SendMessage(MSG_STOP_INPUT_MODE);
                owner.PostMessage(MSG_COMPLETE_INPUT, code, 0);
                EnableWindow(FALSE);
            }
        }

        const uint32_t m_options;
        bool m_autoDelete = false;
        UINT m_ignoreNextKey = 0;
    };

    class InlineEditorHost : public CWindowImpl<InlineEditorHost> {
    public:
        DECLARE_WND_CLASS_EX(_T("{54340C80-248C-4b8e-8CD4-D624A8E9377B}"), 0, -1);

        HWND Create(CWindow host) {

            RECT area;
            {
                RECT client;
                WIN32_OP_D(host.GetClientRect(&client));
                IntersectRect(&area, &client, &m_initialRect);
            }
            const DWORD containerStyle = WS_BORDER | WS_CHILD;
            AdjustWindowRect(&area, containerStyle, FALSE);

            WIN32_OP(__super::Create(host, area, NULL, containerStyle) != NULL);

            try {
                CRect rcClient;
                WIN32_OP_D(GetClientRect(rcClient));

                DWORD style = WS_CHILD | WS_VISIBLE;
                if (m_flags & KFlagMultiLine) style |= WS_VSCROLL | ES_MULTILINE;
                else style |= ES_AUTOHSCROLL;
                if (m_flags & KFlagReadOnly) style |= ES_READONLY;
                if (m_flags & KFlagAlignCenter) style |= ES_CENTER;
                else if (m_flags & KFlagAlignRight) style |= ES_RIGHT;
                else style |= ES_LEFT;

                CEdit edit;

                WIN32_OP(edit.Create(*this, rcClient, NULL, style, 0, ID_EDITBOX) != NULL);
                edit.SetFont(host.GetFont());

                if ((m_flags & KFlagDark) != 0) DarkMode::DarkenEditLite(edit);

                if (m_ACData.is_valid()) InitializeSimpleAC(edit, m_ACData.get_ptr(), m_ACOpts);
                m_editor.SubclassWindow(edit);
                m_editor.OnInitialize();

                pfc::setWindowText(m_editor, *m_textContent);
                m_editor.SetSelAll();
            } catch (...) {
                PostMessage(MSG_COMPLETE_INPUT, InPlaceEdit::KAborted, 0);
                return m_hWnd;
            }

            ShowWindow(SW_SHOW);
            m_editor.SetFocus();

            m_ready = true;

            PFC_ASSERT(m_hWnd != NULL);

            return m_hWnd;
        }

        InlineEditorHost(const RECT& rect, t_uint32 flags, pfc::rcptr_t<pfc::string_base> content, reply_t callback, IUnknown* acData, DWORD acOptions)
            : m_textContent(content), m_callback(callback), m_initialRect(rect),
            m_flags(flags), m_ACData(acData), m_ACOpts(acOptions),
            m_editor(flags)
        {
        }

        enum { ID_EDITBOX = 777 };

        BEGIN_MSG_MAP_EX(InlineEditorHost)
            MESSAGE_HANDLER_EX(WM_CTLCOLOREDIT, MsgForwardToParent)
            MESSAGE_HANDLER_EX(WM_CTLCOLORSTATIC, MsgForwardToParent)
            MESSAGE_HANDLER_EX(WM_MOUSEWHEEL, MsgOnMouseWheel)
            MESSAGE_HANDLER_EX(WM_MOUSEHWHEEL, MsgOnMouseWheel)
            MESSAGE_HANDLER_SIMPLE(MSG_STOP_INPUT_MODE, OnMsgStopEditing)
            MESSAGE_HANDLER_EX(MSG_COMPLETE_INPUT, OnMsgCompletion)
            COMMAND_HANDLER_EX(ID_EDITBOX, EN_CHANGE, OnEditChange)
            MSG_WM_DESTROY(OnDestroyHost)
        END_MSG_MAP()

        HWND GetEditHandle() const { return m_editor; }

    private:
        void OnDestroyHost() { m_autoDelete = true; }

        LRESULT MsgForwardToParent(UINT msg, WPARAM wParam, LPARAM lParam) {
            return GetParent().SendMessage(msg, wParam, lParam);
        }

        LRESULT MsgOnMouseWheel(UINT, WPARAM, LPARAM) {
            PostMessage(MSG_COMPLETE_INPUT, InPlaceEdit::KLostFocusReason, 0);
            return 0;
        }

        void OnMsgStopEditing() {
            ShowWindow(SW_HIDE);
            GetParent().UpdateWindow();
            m_inputDisabled = true;
        }

        LRESULT OnMsgCompletion(UINT, WPARAM wParam, LPARAM) {
            PFC_ASSERT(m_ready);
            if ((wParam & KEditMaskReason) != KLostFocusReason) {
                GetParent().SetFocus();
            }
            if (m_modified && m_editor != NULL) {
                *m_textContent = pfc::getWindowText(m_editor);
            }
            Finalize((unsigned)wParam);
            if (!m_autoDelete) {
                m_autoDelete = true;
                DestroyWindow();
            }
            return 0;
        }

        void OnEditChange(UINT, int, CWindow source) {
            if (m_ready && !m_inputDisabled) {
                *m_textContent = pfc::getWindowText(source);
                m_modified = true;
            }
        }

    private:

        void Finalize(unsigned status) {
            if (!m_done) {
                m_done = true;
                status &= KEditMaskReason;
                unsigned code = status;
                if (m_modified && status != KAborted) code |= KEditFlagContentChanged;
                if (m_callback) m_callback(code);
            }
        }

        const pfc::rcptr_t<pfc::string_base> m_textContent;
        const reply_t m_callback;
        bool m_done = false;
        bool m_ready = false, m_modified = false;
        bool m_inputDisabled = false;
        bool m_autoDelete = false;
        const CRect m_initialRect;
        const t_uint32 m_flags;
        CInlineEditor m_editor;

        const pfc::com_ptr_t<IUnknown> m_ACData;
        const DWORD m_ACOpts;
    };

}

static void fail(reply_t callback) {
    callback(KAborted);
}

HWND InPlaceEdit::Start(HWND parent, const RECT& rect, bool multiline, pfc::rcptr_t<pfc::string_base> content, reply_t callback) {
    return StartEx(parent, rect, multiline ? KFlagMultiLine : 0, content, callback);
}

void InPlaceEdit::Start_FromListView(HWND listView, unsigned item, unsigned subitem, unsigned lines, pfc::rcptr_t<pfc::string_base> content, reply_t callback) {
    Start_FromListViewEx(listView, item, subitem, lines, 0, content, callback);
}

bool InPlaceEdit::TableEditAdvance_ListView(HWND listView, unsigned colBase, unsigned& item, unsigned& col, unsigned itemCount, unsigned colCount, unsigned action) {
    if (col >= colCount) return false;

    pfc::array_t<t_size> orderRev;
    {
        pfc::array_t<unsigned> order;
        const unsigned totalCols = /*colBase + colCount*/ ListView_GetColumnCount(listView);
        PFC_ASSERT(totalCols >= colBase + colCount);
        pfc::array_t<int> orderEx; orderEx.set_size(totalCols);
        if (!ListView_GetColumnOrderArray(listView, totalCols, orderEx.get_ptr())) {
            PFC_ASSERT(!"Should not get here - probably mis-calculated column count");
            return false;
        }
        order.set_size(colCount);
        for (unsigned i = 0; i < colCount; ++i) order[i] = orderEx[colBase + i];

        orderRev.set_size(colCount); order_helper::g_fill(orderRev);
        pfc::sort_get_permutation_t(order, pfc::compare_t<unsigned, unsigned>, colCount, orderRev.get_ptr());
    }

    unsigned visibleCol = (unsigned)orderRev[col];

    if (!TableEditAdvance(item, visibleCol, itemCount, colCount, action)) return false;

    col = (unsigned)order_helper::g_find_reverse(orderRev.get_ptr(), visibleCol);

    return true;
}

bool InPlaceEdit::TableEditAdvance(unsigned& item, unsigned& col, unsigned itemCount, unsigned colCount, unsigned action) {
    if (item >= itemCount || col >= colCount) return false;
    int delta = 0;

    switch (action & KEditMaskReason) {
    case KEnterPressed:
        delta = (int)colCount;
        break;
    case KTabPressed:
        delta = 1;
        break;
    case KShiftTabPressed:
        delta = -1;
        break;
    default:
        return false;
    }
    while (delta > 0) {
        col++;
        if (col >= colCount) {
            col = 0;
            item++;
            if (item >= itemCount) return false;
        }
        delta--;
    }
    while (delta < 0) {
        if (col == 0) {
            if (item == 0) return false;
            item--;
            col = colCount;
        }
        col--;
        delta++;
    }
    return true;
}

HWND InPlaceEdit::StartEx(HWND parent, const RECT& rect, unsigned flags, pfc::rcptr_t<pfc::string_base> content, reply_t callback, IUnknown* acData, DWORD acOpts) {
    try {
        PFC_ASSERT((CWindow(parent).GetWindowLong(GWL_STYLE) & WS_CLIPCHILDREN) != 0);
        return (new CWindowCreateAndDelete<InlineEditorHost>(parent, rect, flags, content, callback, acData, acOpts))->GetEditHandle();
    } catch (...) {
        fail(callback);
        return NULL;
    }
}

void InPlaceEdit::Start_FromListViewEx(HWND listView, unsigned item, unsigned subitem, unsigned lines, unsigned flags, pfc::rcptr_t<pfc::string_base> content, reply_t callback) {
    try {
        ListView_EnsureVisible(listView, item, FALSE);
        RECT itemRect;
        WIN32_OP_D(ListView_GetSubItemRect(listView, item, subitem, LVIR_LABEL, &itemRect));

        const bool multiline = lines > 1;
        if (multiline) {
            itemRect.bottom = itemRect.top + (itemRect.bottom - itemRect.top) * lines;
        }

        StartEx(listView, itemRect, flags | (multiline ? KFlagMultiLine : 0), content, callback);
    } catch (...) {
        fail(callback);
    }
}

