// Function to locate the first occurrence of either sub1 or sub2 in name,
// ensuring the character after the match isn't alphabetic
std::string::size_type locateSubstring(std::string &input, std::string pattern1, std::string pattern2) {
    std::string::size_type index1, index2;

    // Search for pattern1
    for (index1 = 0; index1 != std::string::npos; index1++) {
        index1 = input.find(pattern1, index1);
        if (index1 == std::string::npos)
            break;
        if (index1+2 >= input.length() || !isalpha(input[index1+2])) {
            break;
        }
    }

    // Search for pattern2
    for (index2 = 0; index2 != std::string::npos; index2++) {
        index2 = input.find(pattern2, index2);
        if (index2 == std::string::npos)
            break;
        if (index2+2 >= input.length() || !isalpha(input[index2+2]))
            break;
    }

    // Return the earliest valid position
    if (index1 != std::string::npos && index2 != std::string::npos) {
        return std::min(index1, index2);
    } else if (index1 != std::string::npos) {
        return index1;
    } else {
        return index2;
    }
}

// Find position of heterotachy rate model (+H or *H)
std::string::size_type findHeterotachyPosition(std::string model_identifier) {
    return locateSubstring(model_identifier, "+H", "*H");
}

// Find position of free rate model (+R or *R)
std::string::size_type findFreeRatePosition(std::string &model_identifier) {
    return locateSubstring(model_identifier, "+R", "*R");
}

// Find position of PoMo model (+P or *P)
std::string::size_type findPoMoPosition(std::string &model_identifier) {
    return locateSubstring(model_identifier, "+P", "*P");
}

// Parse model definitions from built-in and external sources
ModelsBlock *parseModelDefinitions(Options &options) {
    ModelsBlock *model_collection = new ModelsBlock;
    try {
        // Load internal mixture model definitions
        std::stringstream buffer(builtin_mixmodels_definition);
        ASSERT(buffer && "stringstream initialization successful");
        NxsReader nexus_parser;
        nexus_parser.Add(model_collection);
        MyToken token_stream(buffer);
        nexus_parser.Execute(token_stream);
    } catch (...) {
        ASSERT(0 && "predefined mixture models not initialized");
    }

    try {
        // Load internal protein model definitions
        std::stringstream buffer(builtin_prot_models);
        ASSERT(buffer && "stringstream initialization successful");
        NxsReader nexus_parser;
        nexus_parser.Add(model_collection);
        MyToken token_stream(buffer);
        nexus_parser.Execute(token_stream);
    } catch (...) {
        ASSERT(0 && "predefined protein models not initialized");
    }

    if (options.model_def_file) {
        std::cout << "Reading model definition file " << options.model_def_file << " ... ";
        MyReader nexus_reader(options.model_def_file);
        nexus_reader.Add(model_collection);
        MyToken token_stream(nexus_reader.inf);
        nexus_reader.Execute(token_stream);

        int num_models = 0, num_freq_vectors = 0;
        for (ModelsBlock::iterator iter = model_collection->begin(); iter != model_collection->end(); iter++) {
            if (iter->second.flag & NM_FREQ) 
                num_freq_vectors++; 
            else 
                num_models++;
        }
        std::cout << num_models << " models and " << num_freq_vectors << " frequency vectors loaded" << std::endl;
    }
    return model_collection;
}

// ModelFactory constructor without parameters
ModelFactory::ModelFactory() : CheckpointFactory() {
    current_model = NULL;
    site_rate_process = NULL;
    store_transition_matrix = false;
    storing_state = false;
    optimize_jointly = false;
    fused_mixture_rate = false;
    ascertainment_correction_type = ASC_NONE;
    checkpoint_synchronization = nullptr;
}

// Helper function to find matching closing bracket
std::size_t locateMatchingBracket(std::string &expression, std::size_t opening_position) {
    int nesting_counter = 0;
    for (std::size_t pos = opening_position+1; pos < expression.length(); pos++) {
        if (expression[pos] == '{') nesting_counter++;
        if (expression[pos] == '}') {
            if (nesting_counter == 0) 
                return pos; 
            else 
                nesting_counter--;
        }
    }
    return std::string::npos;
}

// ModelFactory constructor with parameters
ModelFactory::ModelFactory(Options &options, std::string &model_identifier, PhyloTree *phylogeny, ModelsBlock *model_database) : CheckpointFactory() {
    store_transition_matrix = options.store_trans_matrix;
    storing_state = false;
    optimize_jointly = options.optimize_model_rate_joint;
    fused_mixture_rate = false;
    ascertainment_correction_type = ASC_NONE;
    checkpoint_synchronization = nullptr;

    std::string model_string = model_identifier;
    std::string rate_string;

    try {
        // Set default model based on sequence type if none specified
        if (model_string == "") {
            if (phylogeny->aln->seq_type == SEQ_DNA) 
                model_string = "HKY";
            else if (phylogeny->aln->seq_type == SEQ_PROTEIN) 
                model_string = "LG";
            else if (phylogeny->aln->seq_type == SEQ_BINARY) 
                model_string = "GTR2";
            else if (phylogeny->aln->seq_type == SEQ_CODON) 
                model_string = "GY";
            else if (phylogeny->aln->seq_type == SEQ_MORPH) 
                model_string = "MK";
            else if (phylogeny->aln->seq_type == SEQ_POMO) 
                model_string = "HKY+P";
            else 
                model_string = "JC";

            // Warn about potential under-fitting with default model
            if (phylogeny->aln->seq_type != SEQ_POMO && options.model_joint.empty())
                outWarning("Default model "+model_string + " may be under-fitting. Use option '-m TEST' to determine the best-fit model.");
        }

        // Handle continuous gamma model by removing 'C' from "+GC"
        if (model_string.find("+GC") != std::string::npos) {
            std::string temp_model(1, model_string[0]);
            for (int idx = 1; idx < model_string.length(); idx++)
                if (!(model_string[idx-1]=='G' && model_string[idx]=='C'))
                    temp_model = temp_model + model_string[idx];
            model_identifier = temp_model;
        }

        /********* preprocessing model string ****************/
        NxsModel *nxsmodel_ptr  = NULL;
        std::string updated_model = "";
        std::size_t mix_index;

        // Process mixture models
        for (mix_index = 0; mix_index < model_string.length(); mix_index++) {
            std::size_t next_mix_index = model_string.find_first_of("+*", mix_index);
            std::string sub_model = model_string.substr(mix_index, next_mix_index-mix_index);
            nxsmodel_ptr = model_database->findMixModel(sub_model);
            if (nxsmodel_ptr) 
                sub_model = nxsmodel_ptr->description;
            updated_model += sub_model;

            if (next_mix_index != std::string::npos)
                updated_model += model_string[next_mix_index];
            else
                break;
            mix_index = next_mix_index;
        }

        if (updated_model != model_string)
            std::cout << "Model " << model_string << " is alias for " << updated_model << std::endl;
        model_string = updated_model;

        // Handle joint model if specified
        if (!Options::getInstance().model_joint.empty()) {
            std::string curr_model_str = Options::getInstance().model_joint;
            updated_model = "";
            for (mix_index = 0; mix_index < curr_model_str.length(); mix_index++) {
                std::size_t next_mix_index = curr_model_str.find_first_of("+*", mix_index);
                std::string sub_model = curr_model_str.substr(mix_index, next_mix_index-mix_index);
                nxsmodel_ptr = model_database->findMixModel(sub_model);
                if (nxsmodel_ptr) 
                    sub_model = nxsmodel_ptr->description;
                updated_model += sub_model;

                if (next_mix_index != std::string::npos)
                    updated_model += curr_model_str[next_mix_index];
                else
                    break;
                mix_index = next_mix_index;
            }
            if (updated_model != curr_model_str)
                std::cout << "Model " << curr_model_str << " is alias for " << updated_model << std::endl;
            Options::getInstance().model_joint = updated_model;
        }

        // Detect PoMo and validate usage
        std::string::size_type pomo_pos = findPoMoPosition(model_string);
        bool is_pomo = (pomo_pos != std::string::npos);
        if ((pomo_pos == std::string::npos) &&
            (phylogeny->aln->seq_type == SEQ_POMO))
            outError("Provided alignment is exclusively used by PoMo but model string does not contain, e.g., \"+P\".");

        // Decompose model string into model and rate parts
        std::size_t special_pos = model_string.find_first_of("{+*");
        if (special_pos != std::string::npos) {
            if (model_string[special_pos] == '{') {
                // Scan for the corresponding '}'.
                std::size_t bracket_end = locateMatchingBracket(model_string, special_pos);
                if (bracket_end == std::string::npos)
                    outError("Model name has wrong bracket notation '{...}'");
                rate_string = model_string.substr(bracket_end+1);
                model_string = model_string.substr(0, bracket_end+1);
            } else {
                rate_string = model_string.substr(special_pos);
                model_string = model_string.substr(0, special_pos);
            }
        }

        // Extract frequency specification from rate string
        std::string freq_spec = "";
        while ((special_pos = rate_string.find("+F")) != std::string::npos) {
            std::size_t end_pos = rate_string.find_first_of("+*", special_pos+1);
            if (end_pos == std::string::npos) {
                freq_spec += rate_string.substr(special_pos);
                rate_string = rate_string.substr(0, special_pos);
            } else {
                freq_spec += rate_string.substr(special_pos, end_pos - special_pos);
                rate_string = rate_string.substr(0, special_pos) + rate_string.substr(end_pos);
            }
        }

        // Extract codon mixture specification
        std::string cmix_spec = "";
        if ((special_pos = rate_string.find("+CMIX")) != std::string::npos) {
            std::size_t end_pos = rate_string.find_first_of("+*", special_pos+1);
            if (end_pos == std::string::npos) {
                cmix_spec += rate_string.substr(special_pos);
                rate_string = rate_string.substr(0, special_pos);
            } else {
                cmix_spec += rate_string.substr(special_pos, end_pos - special_pos);
                rate_string = rate_string.substr(0, special_pos) + rate_string.substr(end_pos);
            }
        }

        // Apply joint model if specified
        if (!Options::getInstance().model_joint.empty()) {
            model_string = Options::getInstance().model_joint;
            freq_spec = "";
            std::size_t mx_end_pos = 0;
            if (model_string.substr(0,4) == "MIX{") {
                std::size_t last_bracket = model_string.find_last_of("}");
                if (last_bracket == std::string::npos)
                    outError("Missing } in the joint model name " + model_string);
            }
            while ((special_pos = model_string.find("+F", mx_end_pos)) != std::string::npos) {
                std::size_t end_pos = model_string.find_first_of("+*", special_pos+1);
                if (end_pos == std::string::npos) {
                    freq_spec += model_string.substr(special_pos);
                    model_string = model_string.substr(0, special_pos);
                } else {
                    freq_spec += model_string.substr(special_pos, end_pos - special_pos);
                    model_string = model_string.substr(0, special_pos) + model_string.substr(end_pos);
                }
            }
        }

        // Move error model +E from rate string to model string
        while ((special_pos = rate_string.find("+E")) != std::string::npos) {
            std::size_t end_pos = rate_string.find_first_of("+*", special_pos+1);
            if (end_pos == std::string::npos) {
                model_string += rate_string.substr(special_pos);
                rate_string = rate_string.substr(0, special_pos);
            } else {
                model_string += rate_string.substr(special_pos, end_pos - special_pos);
                rate_string = rate_string.substr(0, special_pos) + rate_string.substr(end_pos);
            }
        }

        // Handle PoMo specific flags
        std::size_t n_pos_start = rate_string.find("+N");
        std::size_t n_pos_end   = rate_string.find_first_of("+", n_pos_start+1);
        if (n_pos_start != std::string::npos) {
            if (!is_pomo)
                outError("Virtual population size can only be set with PoMo.");
            if (n_pos_end != std::string::npos)
                rate_string = rate_string.substr(0, n_pos_start)
                    + rate_string.substr(n_pos_end);
            else
                rate_string = rate_string.substr(0, n_pos_start);
        }

        std::size_t wb_pos = rate_string.find("+WB");
        if (wb_pos != std::string::npos) {
          if (!is_pomo)
            outError("Weighted binomial sampling can only be used with PoMo.");
          rate_string = rate_string.substr(0, wb_pos)
            + rate_string.substr(wb_pos+3);
        }

        std::size_t wh_pos = rate_string.find("+WH");
        if (wh_pos != std::string::npos) {
            if (!is_pomo)
                outError("Weighted hypergeometric sampling can only be used with PoMo.");
            rate_string = rate_string.substr(0, wh_pos)
                + rate_string.substr(wh_pos+3);
        }

        std::size_t s_pos = rate_string.find("+S");
        if (s_pos != std::string::npos) {
            if (!is_pomo)
                outError("Binomial sampling can only be used with PoMo.");
            rate_string = rate_string.substr(0, s_pos)
                + rate_string.substr(s_pos+2);
        }

        // Validate PoMo constraints
        if (is_pomo) {
            if (rate_string.find("+ASC") != std::string::npos)
                outError("PoMo does not yet support ascertainment bias correction (+ASC).");
            if (findFreeRatePosition(rate_string) != std::string::npos)
                outError("PoMo does not yet support free rate models (+R).");
            if (rate_string.find("+FMIX") != std::string::npos)
                outError("PoMo does not yet support frequency mixture models (+FMIX).");
            if (findHeterotachyPosition(rate_string) != std::string::npos)
                outError("PoMo does not yet support heterotachy models (+H).");
        }

        // Move PoMo parameters to model string when not using mixture models
        if (model_string.substr(0, 3) != "MIX" && is_pomo) {
            pomo_pos = findPoMoPosition(rate_string);
            if (pomo_pos != std::string::npos) {
                if (rate_string[pomo_pos+2] == '{') {
                    std::string::size_type close_bracket = rate_string.find("}");
                    if (close_bracket == std::string::npos)
                        outError("No closing bracket in PoMo parameters.");
                    else {
                        std::string pomo_heterozygosity = rate_string.substr(pomo_pos+3, close_bracket-pomo_pos-3);
                        rate_string = rate_string.substr(0, pomo_pos) + rate_string.substr(close_bracket+1);
                        model_string += "+P{" + pomo_heterozygosity + "}";
                    }
                } else {
                    rate_string = rate_string.substr(0, pomo_pos) + rate_string.substr(pomo_pos + 2);
                    model_string += "+P";
                }
            }

            // Handle +G flag
            std::size_t pomo_rate_start;
            if ((pomo_rate_start = rate_string.find("+G")) != std::string::npos) {
                std::string pomo_rate_part = "";
                std::size_t pomo_rate_end = rate_string.find_first_of("+*", pomo_rate_start+1);
                if (pomo_rate_end == std::string::npos) {
                    pomo_rate_part = rate_string.substr(pomo_rate_start, rate_string.length() - pomo_rate_start);
                    rate_string = rate_string.substr(0, pomo_rate_start);
                    model_string += pomo_rate_part;
                } else {
                    pomo_rate_part = rate_string.substr(pomo_rate_start, pomo_rate_end - pomo_rate_start);
                    rate_string = rate_string.substr(0, pomo_rate_start) + rate_string.substr(pomo_rate_end);
                    model_string += pomo_rate_part;
                }
            }
        }

        /******************** initialize state frequency ****************************/
        StateFreqType freq_type = options.freq_type;
        if (model_string.substr(0, 3) != "MIX" && freq_type == FREQ_UNKNOWN) {
            switch (phylogeny->aln->seq_type) {
            case SEQ_BINARY: freq_type = FREQ_ESTIMATE; break;
            case SEQ_PROTEIN: break;
            case SEQ_MORPH: freq_type = FREQ_EQUAL; break;
            case SEQ_CODON: freq_type = FREQ_UNKNOWN; break;
                break;
            default: freq_type = FREQ_EMPIRICAL; break;
            }
        }

        // Handle mixture frequency
        std::string::size_type freq_mix_pos = freq_spec.find("+FMIX");
        std::string freq_parameters;
        std::size_t bracket_close;
        if (freq_mix_pos != std::string::npos) {
            std::string fmix_part;
            std::size_t last_pos = freq_spec.find_first_of("+*", freq_mix_pos+1);
            if (last_pos == std::string::npos) {
                fmix_part = freq_spec.substr(freq_mix_pos);
                freq_spec = freq_spec.substr(0, freq_mix_pos);
            } else {
                fmix_part = freq_spec.substr(freq_mix_pos, last_pos-freq_mix_pos);
                freq_spec = freq_spec.substr(0, freq_mix_pos) + freq_spec.substr(last_pos);
            }
            if (fmix_part[5] != OPEN_BRACKET)
                outError("Mixture-frequency must start with +FMIX{");
            bracket_close = fmix_part.find(CLOSE_BRACKET);
            if (bracket_close == std::string::npos)
                outError("Close bracket not found in ", fmix_part);
            if (bracket_close != fmix_part.length()-1)
                outError("Wrong close bracket position ", fmix_part);
            freq_type = FREQ_MIXTURE;
            freq_parameters = fmix_part.substr(6, bracket_close-6);
        }

        // Handle normal frequency specifications
        if (freq_spec.find("+FO") != std::string::npos)
            freq_mix_pos = freq_spec.find("+FO");
        else if (freq_spec.find("+Fo") != std::string::npos)
            freq_mix_pos = freq_spec.find("+Fo");
        else
            freq_mix_pos = freq_spec.find("+F");

        // Handle AliSim cases for +FO{...} or +FU{...}
        if (freq_spec.find("+FO{") != std::string::npos || freq_spec.find("+FU{") != std::string::npos)
            freq_spec = "+F" + freq_spec.substr(3, freq_spec.length() - 3);

        bool optimize_mixmodel_weight = options.optimize_mixmodel_weight;
        if (freq_mix_pos != std::string::npos) {
            std::string fstr;
            std::size_t last_pos = freq_spec.find_first_of("+*", freq_mix_pos+1);
            if (last_pos == std::string::npos) {
                fstr = freq_spec.substr(freq_mix_pos);
                freq_spec = freq_spec.substr(0, freq_mix_pos);
            } else {
                fstr = freq_spec.substr(freq_mix_pos, last_pos-freq_mix_pos);
                freq_spec = freq_spec.substr(0, freq_mix_pos) + freq_spec.substr(last_pos);
            }

            if (fstr.length() > 2 && fstr[2] == OPEN_BRACKET) {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with user-defined frequency is not allowed");
                bracket_close = fstr.find(CLOSE_BRACKET);
                if (bracket_close == std::string::npos)
                    outError("Close bracket not found in ", fstr);
                if (bracket_close != fstr.length()-1)
                    outError("Wrong close bracket position ", fstr);
                freq_type = FREQ_USER_DEFINED;
                freq_parameters = fstr.substr(3, bracket_close-3);
            } else if (fstr == "+FC" || fstr == "+Fc" || fstr == "+F") {
                if (freq_type == FREQ_MIXTURE) {
                    freq_parameters = "empirical," + freq_parameters;
                    optimize_mixmodel_weight = true;
                } else
                    freq_type = FREQ_EMPIRICAL;
            } else if (fstr == "+FU" || fstr == "+Fu") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with user-defined frequency is not allowed");
                else
                    freq_type = FREQ_USER_DEFINED;
            } else if (fstr == "+FQ" || fstr == "+Fq") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with equal frequency is not allowed");
                else
                    freq_type = FREQ_EQUAL;
            } else if (fstr == "+FO" || fstr == "+Fo") {
                if (freq_type == FREQ_MIXTURE) {
                    freq_parameters = "optimize," + freq_parameters;
                    optimize_mixmodel_weight = true;
                } else
                    freq_type = FREQ_ESTIMATE;
            } else if (fstr == "+F1x4" || fstr == "+F1X4") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with " + fstr + " is not allowed");
                else
                    freq_type = FREQ_CODON_1x4;

                // Validate +F1X4{<freq_0>,...,<freq_3>}
                if ((fstr[5]!='{') || (fstr[fstr.length()-1]!='}'))
                    throw "To use F1X4, please specify 4 frequencies by +F1X4{<freq_0>,...,<freq_3>} or let AliSim randomly generate the frequencies by +F1X4.";
                else
                    freq_parameters = fstr.substr(6, fstr.length()-6-1);

            } else if (fstr == "+F3x4" || fstr == "+F3X4") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with " + fstr + " is not allowed");
                else
                    freq_type = FREQ_CODON_3x4;
            } else if (fstr == "+F3x4C" || fstr == "+F3x4c" || fstr == "+F3X4C" || fstr == "+F3X4c") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with " + fstr + " is not allowed");
                else
                    freq_type = FREQ_CODON_3x4C;

                // Validate +F3X4{<freq_0>,...,<freq_11>}
                if ((fstr[5]!='{') || (fstr[fstr.length()-1]!='}'))
                    throw "To use F3X4, please specify 12 frequencies by +F3X4{<freq_0>,...,<freq_11>} or let AliSim randomly generate the frequencies by +F3X4.";
                else
                    freq_parameters = fstr.substr(6, fstr.length()-6-1);

            } else if (fstr == "+FRY") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with " + fstr + " is not allowed");
                else
                    freq_type = FREQ_DNA_RY;
            } else if (fstr == "+FWS") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with " + fstr + " is not allowed");
                else
                    freq_type = FREQ_DNA_WS;
            } else if (fstr == "+FMK") {
                if (freq_type == FREQ_MIXTURE)
                    outError("Mixture frequency with " + fstr + " is not allowed");
                else
                    freq_type = FREQ_DNA_MK;
            } else {
                // Handle custom frequency models
                NxsModel *freq_mod = model_database->findModel(fstr.substr(2));
                if (freq_mod) {
                    freq_type = FREQ_USER_DEFINED;
                    freq_parameters = freq_mod->description;
                } else {
                    // Handle numeric format +F####
                    try {
                        freq_type = parseStateFreqDigits(fstr.substr(2));
                    } catch (...) {
                        outError("Unknown state frequency type ",fstr);
                    }
                }
            }
        }

        /******************** initialize model ****************************/
        if (phylogeny->aln->site_state_freq.empty()) {
            if (model_string.substr(0, 3) == "MIX" || freq_type == FREQ_MIXTURE) {
                std::string model_list;
                if (model_string.substr(0, 3) == "MIX") {
                    if (model_string[3] != OPEN_BRACKET)
                        outError("Mixture model name must start with 'MIX{'");
                    if (model_string.rfind(CLOSE_BRACKET) != model_string.length()-1)
                        outError("Close bracket not found at the end of ", model_string);
                    model_list = model_string.substr(4, model_string.length()-5);
                    model_string = model_string.substr(0, 3);
                }
                current_model = new ModelMixture(model_identifier, model_string, model_list, model_database, freq_type, freq_parameters, phylogeny, optimize_mixmodel_weight);
            } else if (model_identifier.find("+CMIX") != std::string::npos) {
                current_model = new ModelCodonMixture(model_identifier, model_string, model_database, freq_type, freq_parameters, phylogeny, optimize_mixmodel_weight);
            } else {
                current_model = createModel(model_string, model_database, freq_type, freq_parameters, phylogeny);
            }
        } else {
            // Site-specific model handling
            if (model_string == "JC" || model_string == "POISSON")
                outError("JC is not suitable for site-specific model");

            current_model = new ModelSet(model_string.c_str(), phylogeny);
            ModelSet *models = (ModelSet*)current_model;
            models->init((options.freq_type != FREQ_UNKNOWN) ? options.freq_type : FREQ_EMPIRICAL);
            models->pattern_model_map.resize(phylogeny->aln->getNPattern(), -1);

            for (size_t i = 0; i < phylogeny->aln->getNSite(); ++i) {
                models->pattern_model_map[phylogeny->aln->getPatternID(i)] = phylogeny->aln->site_model[i];
            }

            double *state_freq = new double[current_model->num_states];
            double *rates = new double[current_model->getNumRateEntries()];

            for (size_t i = 0; i < phylogeny->aln->site_state_freq.size(); ++i) {
                ModelMarkov *model_i;
                if (i == 0) {
                    model_i = (ModelMarkov*)createModel(model_string, model_database, 
                        (options.freq_type != FREQ_UNKNOWN) ? options.freq_type : FREQ_EMPIRICAL, "", phylogeny);
                    model_i->getStateFrequency(state_freq);
                    model_i->getRateMatrix(rates);
                } else {
                    model_i = (ModelMarkov*)createModel(model_string, model_database, FREQ_EQUAL, "", phylogeny);
                    model_i->setStateFrequency(state_freq);
                    model_i->setRateMatrix(rates);
                }
                if (phylogeny->aln->site_state_freq[i])
                    model_i->setStateFrequency(phylogeny->aln->site_state_freq[i]);
                model_i->init(FREQ_USER_DEFINED);
                models->push_back(model_i);
            }
            delete [] rates;
            delete [] state_freq;
            models->joinEigenMemory();
            models->decomposeRateMatrix();
        }

        /******************** initialize ascertainment bias correction model ****************************/
        std::string::size_type asc_pos;
        if ((asc_pos = rate_string.find("+ASC_INF")) != std::string::npos) {
            ascertainment_correction_type = ASC_INFORMATIVE;
            phylogeny->aln->getUnobservedConstPatterns(ascertainment_correction_type, unobserved_ptns);

            if (phylogeny->aln->num_informative_sites != phylogeny->getAlnNSite()) {
                if (!options.partition_file) {
                    std::string inf_file = (std::string(options.out_prefix) + ".infsites.phy");
                    phylogeny->aln->printAlignment(options.aln_output_format, inf_file.c_str(), false, NULL, EXCLUDE_UNINF);
                    std::cerr << "For your convenience alignment with parsimony-informative sites printed to " << inf_file << std::endl;
                }
                outError("Invalid use of +ASC_INF because of " + convertIntToString(phylogeny->getAlnNSite() - phylogeny->aln->num_informative_sites) +
                         " parsimony-uninformative sites in the alignment");
            }
            if (verbose_mode >= VB_MED)
                std::cout << "Ascertainment bias correction: " << unobserved_ptns.size() << " unobservable uninformative patterns"<< std::endl;
            rate_string = rate_string.substr(0, asc_pos) + rate_string.substr(asc_pos+8);
        } else if ((asc_pos = rate_string.find("+ASC_MIS")) != std::string::npos) {
            ascertainment_correction_type = ASC_VARIANT_MISSING;
            phylogeny->aln->getUnobservedConstPatterns(ascertainment_correction_type, unobserved_ptns);

            if (phylogeny->aln->frac_invariant_sites > 0) {
                if (!options.partition_file) {
                    std::string var_file = (std::string(options.out_prefix) + ".varsites.phy");
                    phylogeny->aln->printAlignment(options.aln_output_format, var_file.c_str(), false, NULL, EXCLUDE_INVAR);
                    std::cerr << "For your convenience alignment with variable sites printed to " << var_file << std::endl;
                }
                outError("Invalid use of +ASC_MIS because of " + convertIntToString(phylogeny->aln->frac_invariant_sites*phylogeny->aln->getNSite()) +
                         " invariant sites in the alignment");
            }
            if (verbose_mode >= VB_MED)
                std::cout << "Holder's ascertainment bias correction: " << unobserved_ptns.size() << " unobservable constant patterns" << std::endl;
            rate_string = rate_string.substr(0, asc_pos) + rate_string.substr(asc_pos+8);
        } else if ((asc_pos = rate_string.find("+ASC")) != std::string::npos) {
            ascertainment_correction_type = ASC_VARIANT;
            phylogeny->aln->getUnobservedConstPatterns(ascertainment_correction_type, unobserved_ptns);

            // Remove rarely observed states
            for (int i = unobserved_ptns.size()-1; i >= 0; i--)
                if (current_model->state_freq[(int)unobserved_ptns[i][0]] < 1e-8)
                    unobserved_ptns.erase(unobserved_ptns.begin() + i);

            if (phylogeny->aln->frac_invariant_sites > 0) {
                if (!options.partition_file) {
                    std::string inv_file = (std::string(options.out_prefix) + ".invsites.phy");
                    phylogeny->aln->printAlignment(options.aln_output_format, inv_file.c_str(), false, NULL, EXCLUDE_VAR);
                    std::cerr << "For your convenience alignment with invariant sites printed to " << inv_file << std::endl;
                }
                outError("Invalid use of +ASC because of " + convertIntToString(phylogeny->aln->frac_invariant_sites*phylogeny->aln->getNSite()) +
                         " invariant sites in the alignment");
            }

            if (verbose_mode >= VB_MED)
                std::cout << "Standard ascertainment bias correction: " << unobserved_ptns.size() << " unobservable constant patterns" << std::endl;
            rate_string = rate_string.substr(0, asc_pos) + rate_string.substr(asc_pos+4);
        }
    } catch (...) {
        // Exception handling
    }
}

