using namespace sdb;
using namespace sdb::app;
using namespace sdb::basics;
using namespace sdb::options;

namespace {
static bool gTerminated = false;
static int gChildPid = 0;
static const char* gRestartMsg = "will now start a new child process";
static const char* gNoRestartMsg =
  "will intentionally not start a new child process";
static const char* gFixErrMsg =
  "please check what causes the child process to fail and fix the error "
  "first";

static void TerminationHandler(int) {
  SDB_INFO("supervisor", Logger::STARTUP,
           "received SIGINT for supervisor); commanding child [", gChildPid,
           "] to shut down.");
  int rc = kill(gChildPid, SIGTERM);
  if (rc < 0) {
    SDB_ERROR("supervisor", Logger::STARTUP, "commanding child [", gChildPid,
              "] to shut down failed: [", errno, "] ", strerror(errno));
  }
  gTerminated = true;
}

static void ReloadHandler(int) {
  SDB_INFO("supervisor", Logger::STARTUP,
           "received SIGHUP for supervisor); commanding child [", gChildPid,
           "] to perform log rotation.");
  int rc = kill(gChildPid, SIGHUP);
  if (rc < 0) {
    SDB_ERROR("supervisor", Logger::STARTUP, "commanding child [", gChildPid,
              "] to rotate logs failed: [", errno, "] ", strerror(errno));
  }
}
}  // namespace

SupervisorFeature::SupervisorFeature(Server& server)
  : SerenedFeature{server, name()}, _supervisor(false), _child_pid(0) {
  setOptional(true);
}

void SupervisorFeature::collectOptions(
  std::shared_ptr<ProgramOptions> options) {
  options
    ->addOption(
      "--supervisor",
      "Start the server in supervisor mode. Requires --pid-file to be set.",
      new BooleanParameter(&_supervisor),
      sdb::options::MakeDefaultFlags(sdb::options::Flags::Uncommon))
    .setLongDescription(R"(Runs an serened process as supervisor with another
serened process as child, which acts as the server. In the event that the server
unexpectedly terminates due to an internal error, the supervisor automatically
restarts the server. Enabling this option implies that the server runs as a
daemon.)");
}

void SupervisorFeature::validateOptions(
  std::shared_ptr<ProgramOptions> options) {
  if (_supervisor) {
    try {
      DaemonFeature& daemon = server().getFeature<DaemonFeature>();
      daemon.setDaemon(true);
      daemon.validateOptions(options);
    } catch (...) {
      SDB_FATAL("supervisor", sdb::Logger::FIXME,
                "daemon mode not available, cannot start supervisor");
    }
  }
}

void SupervisorFeature::daemonize() {
  static const time_t kMinSurvivalThreshold = 45;
  if (!_supervisor) {
    return;
  }

  time_t startTime = time(nullptr);
  time_t elapsed;
  bool finished = false;
  int exitCode = EXIT_SUCCESS;

  sdb::signals::UnmaskAllSignals();

  if (!server().hasFeature<LoggerFeature>()) {
    SDB_FATAL("supervisor", Logger::STARTUP, "missing required feature 'Logger', giving up");
  }

  LoggerFeature& logger = server().getFeature<LoggerFeature>();
  logger.setSupervisor(true);
  logger.prepare();

  SDB_DEBUG("supervisor", Logger::STARTUP, "starting supervisor loop");

  while (!finished) {
    logger.setSupervisor(false);

    signal(SIGINT, SIG_DFL);
    signal(SIGTERM, SIG_DFL);

    SDB_DEBUG("supervisor", Logger::STARTUP,
              "supervisor will now attempt to spawn a new child process");

    _child_pid = fork();
    if (_child_pid < 0) {
      SDB_FATAL("supervisor", Logger::STARTUP, "fork failed, giving up");
    }

    if (0 < _child_pid) {
      // Parent (supervisor)
      signal(SIGINT, TerminationHandler);
      signal(SIGTERM, TerminationHandler);
      signal(SIGHUP, ReloadHandler);

      SDB_INFO("supervisor", Logger::STARTUP,
               "supervisor has spawned a child process with pid ", _child_pid);

      SetProcessTitle("serenedb [supervisor]");
      SDB_DEBUG("supervisor", Logger::STARTUP, "supervisor mode: inside parent");

      gChildPid = _child_pid;
      gTerminated = false;

      int status;
      int res = waitpid(_child_pid, &status, 0);

      bool abnormalExit = true;

      SDB_INFO("supervisor", Logger::STARTUP, "waitpid returned ", res,
               " with status ", status,
               " and TERMINATED = ", (gTerminated ? "true" : "false"));

      if (gTerminated) {
        finished = true;
        abnormalExit = false;
      } else {
        if (WIFEXITED(status)) {
          if (WEXITSTATUS(status) == 0) {
            SDB_INFO("supervisor", Logger::STARTUP, "child process ", _child_pid,
                     " exited normally. ", gNoRestartMsg);
            finished = true;
            abnormalExit = false;
          } else {
            elapsed = time(nullptr) - startTime;
            if (elapsed < kMinSurvivalThreshold) {
              SDB_ERROR(
                "supervisor", Logger::STARTUP, "child process ", _child_pid,
                " exited prematurely, exit code ", WEXITSTATUS(status),
                ". it only lived for ", elapsed,
                " seconds, below minimum threshold of ",
                kMinSurvivalThreshold, " s. ", gNoRestartMsg, ". ",
                gFixErrMsg);
              finished = true;
            } else {
              SDB_ERROR("supervisor", Logger::STARTUP, "child process ", _child_pid,
                        " exited unexpectedly, exit code ",
                        WEXITSTATUS(status), ". ", gRestartMsg);
              finished = false;
            }
          }
        } else if (WIFSIGNALED(status)) {
          int sig = WTERMSIG(status);
          switch (sig) {
            case 2:   // SIGINT
            case 9:   // SIGKILL
            case 15:  // SIGTERM
              SDB_INFO("supervisor", Logger::STARTUP, "child process ", _child_pid,
                       " terminated gracefully, signal ", sig, " (",
                       sdb::signals::Name(sig), "). ", gNoRestartMsg);
              finished = true;
              abnormalExit = false;
              break;
            default:
              elapsed = time(nullptr) - startTime;
              if (elapsed < kMinSurvivalThreshold) {
                SDB_ERROR("supervisor", Logger::STARTUP, "child process ",
                          _child_pid, " crashed unexpectedly, signal ", sig,
                          " (", sdb::signals::Name(sig),
                          "). it survived only ", elapsed,
                          " seconds — less than minimum ", kMinSurvivalThreshold,
                          " s. ", gNoRestartMsg, ". ", gFixErrMsg);
                finished = true;
#ifdef WCOREDUMP
                if (WCOREDUMP(status)) {
                  SDB_WARN("supervisor", Logger::STARTUP, "child process ",
                           _child_pid, " also dumped core");
                }
#endif
              } else {
                SDB_ERROR("supervisor", Logger::STARTUP, "child process ",
                          _child_pid, " crashed unexpectedly, signal ", sig,
                          " (", sdb::signals::Name(sig), "). ", gRestartMsg);
                finished = false;
              }
              break;
          }
        } else {
          SDB_ERROR("supervisor", Logger::STARTUP, "child process ", _child_pid,
                    " terminated abnormally, unknown cause. ", gRestartMsg);
          finished = false;
        }
      }

      exitCode = abnormalExit ? EXIT_FAILURE : EXIT_SUCCESS;
    } else {
      // Child process
      log::Shutdown();
      log::Appender::allowStdLogging(false);
      DaemonFeature::remapStandardFileDescriptors();

      SDB_DEBUG("supervisor", Logger::STARTUP, "supervisor mode: inside child");
      SetProcessTitle("serenedb [server]");

#ifdef SERENEDB_HAVE_PRCTL
      prctl(PR_SET_PDEATHSIG, SIGTERM, 0, 0, 0);
#endif

      try {
        DaemonFeature& daemon = server().getFeature<DaemonFeature>();
        daemon.setDaemon(false);
      } catch (...) {
        // ignore errors during child initialization
      }

      return;
    }
  }

  SDB_DEBUG("supervisor", Logger::STARTUP, "supervisor exiting with code ",
            exitCode);
  log::Flush();
  log::Shutdown();
  exit(exitCode);
}

