#endif
UINT mci_trace = MCI_LOG;
static const char* MCICommandName(UINT message) {
    switch (message) {
    case MCI_OPEN:
        return "MCI_OPEN";
    case MCI_CLOSE:
        return "MCI_CLOSE";
    case MCI_PLAY:
        return "MCI_PLAY";
    case MCI_SEEK:
        return "MCI_SEEK";
    case MCI_STOP:
        return "MCI_STOP";
    case MCI_PAUSE:
        return "MCI_PAUSE";
    case MCI_INFO:
        return "MCI_INFO";
    case MCI_STATUS:
        return "MCI_STATUS";
    case MCI_RESUME:
        return "MCI_RESUME";
    default:
        return HexPls(message, 8);
    }
}
extern "C" BOOL __stdcall Intercept_mciSendCommandA(void* callerAddr, MCIERROR* result, MCIDEVICEID devID, UINT cmd, DWORD_PTR flags, DWORD_PTR args) {
    if (mci_trace & MCI_LOG_CALLS)
        ConsoleLog(LOG_DEBUG, "MCI:  0x%08p <- mciSendCommand(0x%08X, %s, 0x%08X, 0x%08X)\n", callerAddr, devID, MCICommandName(cmd), flags, args);
    switch (cmd) {
    case MCI_OPEN: {
        if (mci_trace & (MCI_LOG_CALLS | MCI_LOG_DUMPS)) {
            MCI_OPEN_PARMS* openParams = (MCI_OPEN_PARMS*)args;
			ConsoleLog(LOG_NONE,
                "MCI_OPEN_PARMS {\n"
				"    dwCallback       = 0x%08X,\n"
				"    wDeviceID        = 0x%08X,\n"
				"    lpstrDeviceType  = %s,\n"
				"    lpstrElementName = %s,\n"
				"    lpstrAlias       = %s\n"
				"}\n\n", openParams->dwCallback, openParams->wDeviceID,
				((UINT)(openParams->lpstrDeviceType) > 4096 && (INT)(openParams->lpstrDeviceType) != MCI_ALL_DEVICE_ID ? openParams->lpstrDeviceType : HexPls((UINT)(openParams->lpstrDeviceType), 8)),
				openParams->lpstrElementName,
				((UINT)(openParams->lpstrAlias) == 0 ? openParams->lpstrAlias : "NULL"));
        }
        break;
    }
    case MCI_STATUS: {
        if (mci_trace & (MCI_LOG_CALLS | MCI_LOG_DUMPS)) {
            MCI_STATUS_PARMS* statusParams = (MCI_STATUS_PARMS*)args;
			ConsoleLog(LOG_NONE,
                "MCI_STATUS_PARMS {\n"
				"    dwCallback = 0x%08X,\n"
				"    dwReturn   = 0x%08X,\n"
				"    dwItem     = 0x%08X,\n"
				"    dwTrack    = 0x%08X\n"
				"}\n\n", statusParams->dwCallback, statusParams->dwReturn, statusParams->dwItem, statusParams->dwTrack);
        }
        break;
    }
    case MCI_PLAY: {
        if (mci_trace & (MCI_LOG_CALLS | MCI_LOG_DUMPS)) {
            MCI_PLAY_PARMS* playParams = (MCI_PLAY_PARMS*)args;
			ConsoleLog(LOG_NONE,
                "MCI_PLAY_PARMS {\n"
				"    dwCallback = 0x%08X,\n"
				"    dwFrom     = 0x%08X,\n"
				"    dwTo       = 0x%08X\n"
				"}\n\n", playParams->dwCallback, playParams->dwFrom, playParams->dwTo);
        }
        break;
    }
    case MCI_CLOSE:
        break;
    default:
        if (mci_trace & MCI_LOG_CALLS)
            ConsoleLog(LOG_WARNING, "MCI:  mciSendCommand invoked with unknown command %s.\n", MCICommandName(cmd));
    }
    *result = 0;
    return TRUE;
}
extern "C" BOOL __stdcall PostIntercept_mciSendCommandA(void* callerAddr, MCIERROR* result, MCIDEVICEID devID, UINT cmd, DWORD_PTR flags, DWORD_PTR args) {
    return TRUE;
}
extern "C" MCIERROR __stdcall _mciSendCommandA(MCIDEVICEID devID, UINT cmd, DWORD_PTR flags, DWORD_PTR args) {
    MCIERROR result = 0;
    if (!Intercept_mciSendCommandA(_ReturnAddress(), &result, devID, cmd, flags, args))
        return result;
    __asm {
        push args
        push flags
        push cmd
        push devID
        call fpWinMMHookList[41 * 4]
        mov [result], eax
    }

    PostIntercept_mciSendCommandA(_ReturnAddress(), &result, devID, cmd, flags, args);
    return result;
}

