// Check if the periodic timer has expired and update next trigger time
periodic::periodic(std::chrono::steady_clock::duration interval)
    : m_interval(interval) {}

periodic::operator bool() {
    auto current_time = std::chrono::steady_clock::now();
    if (current_time < m_next_trigger) {
        return false;
    }
    m_next_trigger = current_time + m_interval;
    return true;
}

