TEST_CASE_MAP("iterators_insert", int, int) {
    auto container = std::vector<std::pair<int, int>>();
    container.reserve(1000);
    for (int index = 0; index < 1000; ++index) {
        container.emplace_back(index, index);
    }
    auto hash_map = map_t(container.begin(), container.end());
    REQUIRE(hash_map.size() == container.size());
    for (auto const& element : container) {
        REQUIRE(hash_map.count(element.first) == 1);
        auto iter = hash_map.find(element.first);
        REQUIRE(iter != hash_map.end());
    }
}

#include "future.h"
#include <library/cpp/testing/unittest/registar.h>
#include <util/generic/noncopyable.h>
#include <util/generic/xrange.h>
#include <util/thread/pool.h>
#include <atomic>
#include <exception>

using NThreading::NewPromise;
using NThreading::TFuture;
using NThreading::TPromise;
using NThreading::TWaitPolicy;

namespace {
    // Alternative Wait* implementation without optimizations, for testing TWaitGroup robustness
    template <class WaitPolicy, class TContainer>
    TFuture<void> WaitAlt(const TContainer& futures) {
        NThreading::TWaitGroup<WaitPolicy> wg;
        for (const auto& fut : futures) {
            wg.Add(fut);
        }
        return std::move(wg).Finish();
    }

    class TLooseBarrier {
    public:
        explicit TLooseBarrier(i64 count)
            : Remaining_{count} {
        }

        void Step() {
            // barrier used only for timing, not synchronization — relaxed ordering sufficient
            Remaining_.fetch_sub(1, std::memory_order_relaxed);
            while (Remaining_.load(std::memory_order_relaxed)) {
                // busy-wait until all participants arrive
            }
            Y_ASSERT(Remaining_.load(std::memory_order_relaxed) >= 0);
        }

    private:
        std::atomic<i64> Remaining_;
    };

    THolder<TThreadPool> BuildPool() {
        auto pool = MakeHolder<TThreadPool>(TThreadPool::TParams{}.SetBlocking(false).SetCatching(false));
        pool->Start(8);
        return pool;
    }

    template <class T>
    TVector<TFuture<T>> CollectFutures(const TVector<TPromise<T>>& promises) {
        TVector<TFuture<T>> result;
        for (auto&& p : promises) {
            result.emplace_back(p);
        }
        return result;
    }

    struct TGlobalState {
        i64 Initiated = -1;
        i64 InitiatedWithException = -1;
        const TVector<TFuture<void>>* ActiveFutures = nullptr;
    };

    // Generic test runner using a factory to construct the wait logic
    template <class TFactory>
    void ExecuteWaitScenario(TFactory globalBuilder) {
        auto pool = BuildPool();
        const auto errPtr = std::make_exception_ptr(99);

        for (auto numPromises : xrange(1, 5)) {
            for (auto iteration : xrange(1024 * 64)) {
                const auto totalTasks = numPromises + 1;
                TLooseBarrier syncPoint{totalTasks};
                std::atomic<i64> initiatedCount{0};
                std::atomic<i64> exceptionCount{0};
                std::atomic<i64> finishedCount{0};

                TVector<TPromise<void>> promiseList;
                for (auto idx : xrange(numPromises)) {
                    Y_UNUSED(idx);
                    promiseList.push_back(NewPromise());
                }

                const auto futureList = CollectFutures(promiseList);

                auto stateCapture = [&] {
                    return TGlobalState{
                        .Initiated = initiatedCount.load(std::memory_order_relaxed),
                        .InitiatedWithException = exceptionCount.load(std::memory_order_relaxed),
                        .ActiveFutures = &futureList,
                    };
                };

                // Launch promise setters
                for (auto idx : xrange(numPromises)) {
                    pool->SafeAddFunc([&, idx] {
                        syncPoint.Step();
                        initiatedCount.fetch_add(1, std::memory_order_relaxed);

                        if ((iteration % 4 == 0) && (idx == 0)) {
                            exceptionCount.fetch_add(1, std::memory_order_relaxed);
                            promiseList[idx].SetException(errPtr);
                        } else {
                            promiseList[idx].SetValue();
                        }

                        finishedCount.fetch_add(1, std::memory_order_release);
                    });
                }

                // Launch wait operation
                pool->SafeAddFunc([&] {
                    auto waiter = globalBuilder(stateCapture);
                    syncPoint.Step();
                    waiter();
                    finishedCount.fetch_add(1, std::memory_order_release);
                });

                // Wait for all tasks to complete
                while (finishedCount.load() != totalTasks) {
                }
            }
        }
    }
}

Y_UNIT_TEST_SUITE(TFutureConcurrencyTest) {
    Y_UNIT_TEST(WaitAllOperation) {
        ExecuteWaitScenario(
            [](auto captureState) {
                return [=]() {
                    auto* futures = captureState().ActiveFutures;
                    auto allDone = WaitAlt<TWaitPolicy::TAll>(*futures);

                    allDone.Subscribe([=](auto&& result) {
                        TGlobalState state = captureState();
                        // If allDone has value, then all futures must be ready and none had exception
                        UNIT_ASSERT(result.HasValue() <= ((state.Initiated == (i64)futures->size()) && (state.InitiatedWithException == 0)));
                        // If allDone has exception, then at least one future must have thrown
                        UNIT_ASSERT(result.HasException() <= ((state.Initiated == (i64)futures->size()) && (state.InitiatedWithException > 0)));
                    });

                    allDone.Wait();
                };
            }
        );
    }

    Y_UNIT_TEST(WaitAnyOperation) {
        ExecuteWaitScenario(
            [](auto captureState) {
                return [=]() {
                    auto* futures = captureState().ActiveFutures;
                    auto anyReady = WaitAlt<TWaitPolicy::TAny>(*futures);

                    anyReady.Subscribe([=](auto&&) {
                        UNIT_ASSERT(captureState().Initiated > 0);
                    });

                    anyReady.Wait();
                };
            }
        );
    }

    Y_UNIT_TEST(WaitExceptionOrAllOperation) {
        ExecuteWaitScenario(
            [](auto captureState) {
                return [=]() {
                    NThreading::WaitExceptionOrAll(*captureState().ActiveFutures)
                        .Subscribe([=](auto&&) {
                            auto* futures = captureState().ActiveFutures;
                            auto exOrAll = WaitAlt<TWaitPolicy::TExceptionOrAll>(*futures);

                            exOrAll.Subscribe([captureState](auto&& result) {
                                TGlobalState state = captureState();
                                // If result has exception, at least one future must have thrown
                                UNIT_ASSERT(result.HasException() ? (state.InitiatedWithException > 0) : true);
                                // If result has value, all futures must have succeeded
                                UNIT_ASSERT(result.HasValue() == ((state.Initiated == (i64)futures->size()) && (state.InitiatedWithException == 0)));
                            });

                            exOrAll.Wait();
                        });
                };
            }
        );
    }
}

#include "tcenterlinevectP.h"
//==========================================================================
//============================================
//      Conversion of centerline sequences into TStroke objects
//============================================
// Global configuration constants for simplification and conversion
namespace {
const double Simplify_max_error = 1.0;     // Maximum deviation allowed during point reduction
const double Simplify_thickness_factor = 0.75;  // Error scaling based on local thickness
const double Stroke_max_error =
    infinity;  // Upper bound for quadratic approximation error
// const double Stroke_thickness_factor = 0.25;  // NOTE: Replaced by global config parameter
}

//--------------------------------------------------------------------------
//-------------------------------
//      Sequence Simplification Logic
//-------------------------------
// Purpose: Reduce redundant points lying approximately on straight segments,
// retaining only key vertices.
class SequenceSimplifier {
  const Sequence *m_sequence;
  const SkeletonGraph *m_graphStructure;
private:
  class CostMetric {
  public:
    int vertexCount;
    double totalError;
    UINT startNode, endNode;
    CostMetric() : vertexCount(0), totalError(0) {}
    CostMetric(int v, double e) : vertexCount(v), totalError(e) {}
    inline void setInfinite(void) {
      vertexCount = infinity;
      totalError  = infinity;
    }
    inline bool operator<(const CostMetric &other) const {
      return vertexCount < other.vertexCount ? true :
             vertexCount > other.vertexCount ? false :
             totalError < other.totalError ? true : false;
    }
    inline CostMetric operator+(const CostMetric &other) const {
      return CostMetric(vertexCount + other.vertexCount, totalError + other.totalError);
    }
  };
  CostMetric computeCost(UINT nodeA, UINT linkA, UINT nodeB);

public:
  explicit SequenceSimplifier(const Sequence *seq)
      : m_sequence(seq), m_graphStructure(seq->m_graphHolder) {}
  void reduce(std::vector<unsigned int> &outputIndices);
};

//--------------------------------------------------------------------------
// Bellman-Ford style dynamic programming for optimal path selection in Sequences
// Handles circular sequences correctly
void SequenceSimplifier::reduce(std::vector<unsigned int> &outputIndices) {
  unsigned int count;
  unsigned int idxA, idxB, linkA, linkB;

  // Locate sequence boundaries
  idxA     = m_sequence->m_head;
  linkA    = m_sequence->m_headLink;

  // Count number of nodes in the sequence (including wrap-around)
  for (count = 1; idxA != m_sequence->m_tail || count == 1; ++count, m_sequence->next(idxA, linkA))
    ;

  CostMetric currentBest, minSegment, segmentCost;
  unsigned int predecessorIdx, forwardIdx, backwardIdx;
  std::vector<CostMetric> dpCost(count);
  std::vector<CostMetric> dpSegment(count);
  std::vector<unsigned int> dpPredecessor(count);

  // Forward pass: compute minimal cost to reach each node
  idxA     = m_sequence->m_head;
  linkA    = m_sequence->m_headLink;
  for (forwardIdx = 1; idxA != m_sequence->m_tail || forwardIdx == 1;
       m_sequence->next(idxA, linkA), ++forwardIdx) {
    currentBest.setInfinite();
    minSegment.setInfinite();
    predecessorIdx = 0;

    idxB     = m_sequence->m_head;
    linkB    = m_sequence->m_headLink;
    unsigned int nextNode = m_graphStructure->getNode(idxA).getLink(linkA).getNext();

    for (backwardIdx = 0; idxB != nextNode || backwardIdx == 0;
         m_sequence->next(idxB, linkB), ++backwardIdx) {
      if ((segmentCost = dpCost[backwardIdx] + (minSegment = computeCost(idxB, linkB, nextNode))) < currentBest) {
        currentBest = segmentCost;
        predecessorIdx = backwardIdx;
        dpSegment[forwardIdx] = minSegment;
      }
    }

    dpCost[forwardIdx] = currentBest;
    dpPredecessor[forwardIdx] = predecessorIdx;
  }

  // Backtrack to reconstruct simplified path
  unsigned int outSize = outputIndices.size();
  outputIndices.resize(outSize + dpCost[count - 1].vertexCount + 1);
  outputIndices[outSize + dpCost[count - 1].vertexCount] = dpSegment[count - 1].endNode;

  for (backwardIdx = count - 1, forwardIdx = outSize + dpCost[count - 1].vertexCount - 1;
       backwardIdx > 0; backwardIdx = dpPredecessor[backwardIdx], --forwardIdx) {
    outputIndices[forwardIdx] = dpSegment[backwardIdx].startNode;
  }
}

//--------------------------------------------------------------------------
// Compute cost between two sequence points considering geometric fidelity
SequenceSimplifier::CostMetric SequenceSimplifier::computeCost(UINT nodeA, UINT linkA,
                                                              UINT nodeB) {
  UINT currNode, prevNode;
  T3DPointD directionVector;
  double distSq, dotProduct;
  CostMetric result;
  result.vertexCount = 1;
  result.startNode   = nodeA;
  result.endNode     = nodeB;

  directionVector = *m_graphStructure->getNode(nodeB) - *m_graphStructure->getNode(nodeA);
  dotProduct = norm(directionVector);
  currNode = m_graphStructure->getNode(nodeA).getLink(linkA).getNext();
  prevNode = nodeA;

  // If endpoints are very close, verify internal points also lie nearby
  if (dotProduct < 0.1) {
    for (; currNode != nodeB; m_sequence->advance(prevNode, currNode)) {
      distSq = tdistance(*m_graphStructure->getNode(currNode), *m_graphStructure->getNode(nodeA));
      if (distSq > 0.1) result.setInfinite();
    }
    return result;
  }

  // Otherwise, measure perpendicular distance from line defined by endpoints
  directionVector = directionVector * (1.0 / dotProduct);
  for (; currNode != nodeB; m_sequence->advance(prevNode, currNode)) {
    distSq = tdistance2(*m_graphStructure->getNode(currNode), directionVector, *m_graphStructure->getNode(nodeA));
    if (distSq >
        std::min(m_graphStructure->getNode(currNode)->z * Simplify_thickness_factor, Simplify_max_error)) {
      result.setInfinite();
      return result;
    } else
      result.totalError += distSq;
  }
  return result;
}

//==========================================================================
//===============================
//      Sequence-to-Stroke Converter
//===============================
// Converts a reduced sequence into a smooth quadratic stroke using least-squares fitting
// Penalizes deviations based on local thickness and global error thresholds.
class SequenceConverter {
  const Sequence *m_sequence;
  const SkeletonGraph *m_graphStructure;
  double m_penaltyWeight;
public:
  unsigned int midIndex;
  std::vector<double> parameters;

  class CostMetric {
  public:
    int arcCount;
    double errorSum;
    std::vector<T3DPointD> controlPoints;
    CostMetric() : arcCount(0), errorSum(0) {}
    CostMetric(int n, double e) : arcCount(n), errorSum(e) {}
    inline void setInfinite(void) {
      arcCount = infinity;
      errorSum = infinity;
    }
    inline bool operator<(const CostMetric &other) const {
      return arcCount < other.arcCount ? true :
             arcCount > other.arcCount ? false :
             errorSum < other.errorSum ? true : false;
    }
    inline CostMetric operator+(const CostMetric &other) const {
      return CostMetric(arcCount + other.arcCount, errorSum + other.errorSum);
    }
    void assignControlPoints(const T3DPointD &p0, const T3DPointD &p1, const T3DPointD &p2) {
      controlPoints.resize(3);
      controlPoints[0] = p0;
      controlPoints[1] = p1;
      controlPoints[2] = p2;
    }
    void assignControlPoints(const T3DPointD &p0, const T3DPointD &p1, const T3DPointD &p2,
                             const T3DPointD &p3, const T3DPointD &p4) {
      controlPoints.resize(5);
      controlPoints[0] = p0;
      controlPoints[1] = p1;
      controlPoints[2] = p2;
      controlPoints[3] = p3;
      controlPoints[4] = p4;
    }
  };

  std::vector<T3DPointD> interpolatedPoints;
  std::vector<unsigned int> *inputIndices;

  explicit SequenceConverter(const Sequence *seq, double penalty)
      : m_sequence(seq), m_graphStructure(seq->m_graphHolder), m_penaltyWeight(penalty) {}

  CostMetric evaluateCost(unsigned int start, unsigned int end);
  void insertMidpoints();
  TStroke *operator()(std::vector<unsigned int> *indices);
  bool computeParameters(unsigned int start, unsigned int end);
  void processTriplet(unsigned int index, CostMetric &metric);
  bool determineControlPoints(unsigned int i, unsigned int j, CostMetric &metric);
  bool applyPenalty(unsigned int start, unsigned int end, CostMetric &metric);
};

//--------------------------------------------------------------------------
// Thickness changes contribute more significantly to penalty
inline double weightedDot(const T3DPointD &a, const T3DPointD &b) {
  return a.x * b.x + a.y * b.y + 5 * a.z * b.z;
}

//--------------------------------------------------------------------------
// Insert intermediate points between selected indices for smoother interpolation
inline void SequenceConverter::insertMidpoints() {
  unsigned int i, j, size;
  size = inputIndices->size();
  interpolatedPoints.clear();

  if (size == 2) {
    interpolatedPoints.resize(3);
    interpolatedPoints[0] = *m_graphStructure->getNode((*inputIndices)[0]);
    interpolatedPoints[1] = (*m_graphStructure->getNode((*inputIndices)[0]) +
                             *m_graphStructure->getNode((*inputIndices)[1])) *
                            0.5;
    interpolatedPoints[2] = *m_graphStructure->getNode((*inputIndices)[1]);
  } else {
    interpolatedPoints.resize(2 * size - 3);
    interpolatedPoints[0] = *m_graphStructure->getNode((*inputIndices)[0]);
    for (i = j = 1; i < size - 2; ++i, j += 2) {
      interpolatedPoints[j]     = *m_graphStructure->getNode((*inputIndices)[i]);
      interpolatedPoints[j + 1] = (*m_graphStructure->getNode((*inputIndices)[i]) +
                                   *m_graphStructure->getNode((*inputIndices)[i + 1])) *
                                  0.5;
    }
    interpolatedPoints[j]     = *m_graphStructure->getNode((*inputIndices)[size - 2]);
    interpolatedPoints[j + 1] = *m_graphStructure->getNode((*inputIndices)[size - 1]);
  }
}

//--------------------------------------------------------------------------
TStroke *SequenceConverter::operator()(std::vector<unsigned int> *indices) {
  inputIndices = indices;
  insertMidpoints();

  unsigned int n = (interpolatedPoints.size() + 1) / 2;
  unsigned int i;
  int j;
  CostMetric candidate, best, segment, edgeCost;
  unsigned int pred, fIdx, bIdx;
  std::vector<CostMetric> dpCost(n);
  std::vector<CostMetric> dpSegment(n);
  std::vector<unsigned int> dpPred(n);

  // Dynamic programming loop over midpoint positions
  for (i = 2, fIdx = 1; i < interpolatedPoints.size(); i += 2, ++fIdx) {
    best.setInfinite();
    segment.setInfinite();
    pred = 0;

    for (j = i - 2, bIdx = j / 2; j >= 0; j -= 2, --bIdx) {
      if ((candidate = dpCost[bIdx] + (edgeCost = evaluateCost(j, i))) < best) {
        best = candidate;
        pred = bIdx;
        dpSegment[fIdx] = edgeCost;
      } else if (edgeCost.arcCount == infinity)
        break;  // Early termination for invalid segments
    }

    dpCost[fIdx] = best;
    dpPred[fIdx] = pred;
  }

  // Extract optimal control points
  std::vector<TThickPoint> finalCPs(2 * dpCost[n - 1].arcCount + 1);
  for (bIdx = n - 1, fIdx = 2 * dpCost[n - 1].arcCount; bIdx > 0; bIdx = dpPred[bIdx]) {
    for (i = dpSegment[bIdx].controlPoints.size() - 1; i > 0; --i, --fIdx)
      finalCPs[fIdx] = dpSegment[bIdx].controlPoints[i];
  }
  finalCPs[0] = interpolatedPoints[0];

  TStroke *stroke = new TStroke(finalCPs);
  return stroke;
}

//--------------------------------------------------------------------------
// Evaluate cost between two indices in the interpolated sequence
SequenceConverter::CostMetric SequenceConverter::evaluateCost(unsigned int start,
                                                            unsigned int end) {
  CostMetric metric;
  if (end == start + 2) {
    processTriplet(start, metric);
    return metric;
  }

  if (!computeParameters(start, end) ||
      !determineControlPoints(start, end, metric) ||
      !applyPenalty(start, end, metric))
    metric.setInfinite();

  return metric;
}

//--------------------------------------------------------------------------
void SequenceConverter::processTriplet(unsigned int idx, CostMetric &metric) {
  T3DPointD A = interpolatedPoints[idx];
  T3DPointD B = interpolatedPoints[idx + 1];
  T3DPointD C = interpolatedPoints[idx + 2];

  metric.errorSum = 0;
  double deviation = tdistance(B, C - A, A);

  if (deviation <= 2.0) {
    metric.arcCount = 1;
    metric.assignControlPoints(A, B, C);
  } else if (deviation <= 6.0) {
    metric.arcCount = 2;
    double scale = (deviation - 1.0) / deviation;
    T3DPointD U = A + scale * (B - A), V = C + scale * (B - C);
    metric.assignControlPoints(A, U, (U + V) * 0.5, V, C);
  } else {
    metric.arcCount = 2;
    metric.assignControlPoints(A, (A + B) * 0.5, B, (B + C) * 0.5, C);
  }
}

//--------------------------------------------------------------------------
bool SequenceConverter::computeParameters(unsigned int start, unsigned int end) {
  unsigned int curr, prev;
  unsigned int k;
  double weight, cumulative;
  double denominator;
  parameters.clear();
  parameters.push_back(0);

  for (prev = start, curr = start + 1, denominator = 0; curr < end; prev = curr, curr += 2) {
    weight = norm(interpolatedPoints[curr] - interpolatedPoints[prev]);
    denominator += weight;
    parameters.push_back(weight);
  }

  weight = norm(interpolatedPoints[end] - interpolatedPoints[prev]);
  denominator += weight;
  parameters.push_back(weight);

  if (denominator < 0.1) return false;

  for (k = 1, cumulative = 0; k < parameters.size(); ++k) {
    cumulative += 2 * parameters[k] / denominator;
    parameters[k] = cumulative;
  }

  for (midIndex = 0; midIndex < parameters.size() && parameters[midIndex + 1] <= 1; ++midIndex)
    ;

  return true;
}

//==========================================================================
//------------------------
//    Control Point Calculation
//------------------------
// Helper integrals for least-squares fitting
inline T3DPointD integral_H(const T3DPointD &A, const T3DPointD &B, double t1,
                            double t2) {
  return -(0.375 * (pow(t2, 4) - pow(t1, 4))) * B +
         (pow(t2, 3) - pow(t1, 3)) * (B * 0.6667 - A * 0.5) +
         (pow(t2, 2) - pow(t1, 2)) * A;
}

inline T3DPointD integral_K(const T3DPointD &A, const T3DPointD &B, double t1,
                            double t2) {
  return (pow(t2, 4) - pow(t1, 4)) * (B * 0.125) +
         (pow(t2, 3) - pow(t1, 3)) * (A * 0.1667);
}

bool SequenceConverter::determineControlPoints(unsigned int i, unsigned int j,
                                              CostMetric &metric) {
  unsigned int curr, prev;
  TAffine matrix;
  TPointD rhs;
  T3DPointD a, e, x, y, A, B;
  T3DPointD IH, IK, IM, IN_;  // 'IN' avoided due to reserved keyword
  double HxL, KyL, MxO, NyO;
  unsigned int k;

  a = interpolatedPoints[i];
  e = interpolatedPoints[j];
  x = interpolatedPoints[i + 1] - a;
  y = interpolatedPoints[j - 1] - e;

  double par = weightedDot(x, y) / 5;
  matrix = TAffine(weightedDot(x, x) / 3, par, 0, par, weightedDot(y, y) / 3, 0);

  // Accumulate polygonal integrals from start to mid
  for (k = 0, prev = i, curr = i + 1; k < midIndex; ++k, prev = curr, curr += 2) {
    B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
        (1 / (parameters[k + 1] - parameters[k]));
    A = interpolatedPoints[prev] - parameters[k] * B;
    IH += integral_H(A, B, parameters[k], parameters[k + 1]);
    IK += integral_K(A, B, parameters[k], parameters[k + 1]);
  }
  if (curr == j + 1) curr = j;
  B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
      (1 / (parameters[k + 1] - parameters[k]));
  A = interpolatedPoints[prev] - parameters[k] * B;
  IH += integral_H(A, B, parameters[k], 1.0);
  IK += integral_K(A, B, parameters[k], 1.0);

  // Accumulate from end backwards to mid
  for (k = parameters.size() - 1, prev = j, curr = j - 1; k > midIndex + 1;
       --k, prev = curr, curr -= 2) {
    B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
        (1 / (parameters[k] - parameters[k - 1]));
    A = interpolatedPoints[curr] - (2 - parameters[k - 1]) * B;
    IM += integral_K(A, B, 2 - parameters[k], 2 - parameters[k - 1]);
    IN_ += integral_H(A, B, 2 - parameters[k], 2 - parameters[k - 1]);
  }
  if (prev == i + 1) curr = i;
  B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
      (1 / (parameters[k] - parameters[k - 1]));
  A = interpolatedPoints[curr] - (2 - parameters[k - 1]) * B;
  IM += integral_K(A, B, 2 - parameters[k], 1.0);
  IN_ += integral_H(A, B, 2 - parameters[k], 1.0);

  // Polygonal-free terms
  T3DPointD mid = (a + e) * 0.5;
  HxL = (weightedDot(a, x) * 0.3) + (weightedDot(mid, x) / 5.0);
  NyO = (weightedDot(e, y) * 0.3) + (weightedDot(mid, y) / 5.0);
  KyL = (weightedDot(a, y) / 15.0) + (weightedDot(mid, y) / 10.0);
  MxO = ((e * x) / 15.0) + (weightedDot(mid, x) / 10.0);

  rhs = TPointD(weightedDot(IH, x) - HxL + weightedDot(IM, x) - MxO,
                weightedDot(IK, y) - KyL + weightedDot(IN_, y) - NyO);
  matrix.a13 = -rhs.x;
  matrix.a23 = -rhs.y;

  if (fabs(matrix.det()) < 0.01) return false;
  matrix = matrix.inv();

  if (matrix.a13 < 0 || matrix.a23 < 0) return false;

  T3DPointD b = a + matrix.a13 * x;
  T3DPointD d = e + matrix.a23 * y;

  if (b.z < 0 || d.z < 0) return false;

  metric.assignControlPoints(a, b, (b + d) * 0.5, d, e);
  return true;
}

//==========================================================================
//------------------------
//      Penalty Evaluation
//------------------------
inline T3DPointD integral_B0(const T3DPointD &A, const T3DPointD &B, double t1,
                             double t2) {
  return (0.25 * (pow(t2, 4) - pow(t1, 4))) * B +
         ((pow(t2, 3) - pow(t1, 3)) / 3.0) * (A - 2.0 * B) +
         (0.5 * (pow(t2, 2) - pow(t1, 2))) * (B - 2.0 * A) + (t2 - t1) * A;
}

inline T3DPointD integral_B1(const T3DPointD &A, const T3DPointD &B, double t1,
                             double t2) {
  return -(0.5 * (pow(t2, 4) - pow(t1, 4))) * B +
         (2.0 * ((pow(t2, 3) - pow(t1, 3)) / 3.0) * (B - A) +
          (pow(t2, 2) - pow(t1, 2)) * A);
}

inline T3DPointD integral_B2(const T3DPointD &A, const T3DPointD &B, double t1,
                             double t2) {
  return (0.25 * (pow(t2, 4) - pow(t1, 4))) * B +
         ((pow(t2, 3) - pow(t1, 3)) / 3.0) * A;
}

inline double integral_a2(const T3DPointD &A, const T3DPointD &B, double t1,
                          double t2) {
  return weightedDot(A, A) * (t2 - t1) + weightedDot(A, B) * (pow(t2, 2) - pow(t1, 2)) +
         (weightedDot(B, B) * (pow(t2, 3) - pow(t1, 3)) / 3.0);
}

bool SequenceConverter::applyPenalty(unsigned int start, unsigned int end, CostMetric &metric) {
  unsigned int curr, prev;
  const std::vector<T3DPointD> &ctrlPts = metric.controlPoints;
  T3DPointD A, B, P0, P1, P2;
  double penalty, maxPenalty;
  unsigned int k;

  metric.arcCount = 2;

  // Estimate maximum acceptable penalty
  maxPenalty = 0;
  for (curr = start + 1, prev = start, k = 0; curr < end; ++k, prev = curr, curr += 2) {
    maxPenalty += (interpolatedPoints[curr].z + interpolatedPoints[prev].z) *
                  (parameters[k + 1] - parameters[k]) / 2;
  }
  maxPenalty += (interpolatedPoints[end].z + interpolatedPoints[prev].z) *
                (parameters[k + 1] - parameters[k]) / 2;

  maxPenalty = std::min(sqrt(maxPenalty) * m_penaltyWeight, Stroke_max_error);

  // Base quadratic energy
  penalty = (weightedDot(ctrlPts[0], ctrlPts[0]) + 2 * weightedDot(ctrlPts[2], ctrlPts[2]) +
             weightedDot(ctrlPts[4], ctrlPts[4]) + weightedDot(ctrlPts[0], ctrlPts[1]) +
             weightedDot(ctrlPts[1], ctrlPts[2]) + weightedDot(ctrlPts[2], ctrlPts[3]) +
             weightedDot(ctrlPts[3], ctrlPts[4])) /
            5.0 +
      (2 * (weightedDot(ctrlPts[1], ctrlPts[1]) + weightedDot(ctrlPts[3], ctrlPts[3])) +
       weightedDot(ctrlPts[0], ctrlPts[2]) + weightedDot(ctrlPts[2], ctrlPts[4])) /
          15.0;

  // Forward integration
  P0 = P1 = P2 = T3DPointD();
  for (k = 0, prev = start, curr = start + 1; k < midIndex; ++k, prev = curr, curr += 2) {
    B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
        (1 / (parameters[k + 1] - parameters[k]));
    A = interpolatedPoints[prev] - parameters[k] * B;
    P0 += integral_B0(A, B, parameters[k], parameters[k + 1]);
    P1 += integral_B1(A, B, parameters[k], parameters[k + 1]);
    P2 += integral_B2(A, B, parameters[k], parameters[k + 1]);
    penalty += integral_a2(A, B, parameters[k], parameters[k + 1]);
  }
  if (curr == end + 1) curr = end;
  B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
      (1 / (parameters[k + 1] - parameters[k]));
  A = interpolatedPoints[prev] - parameters[k] * B;
  P0 += integral_B0(A, B, parameters[k], 1.0);
  P1 += integral_B1(A, B, parameters[k], 1.0);
  P2 += integral_B2(A, B, parameters[k], 1.0);
  penalty += integral_a2(A, B, parameters[k], 1.0);
  penalty -= 2 * (weightedDot(P0, ctrlPts[0]) + weightedDot(P1, ctrlPts[1]) + weightedDot(P2, ctrlPts[2]));

  // Backward integration
  P0 = P1 = P2 = T3DPointD();
  for (k = parameters.size() - 1, prev = end, curr = end - 1; k > midIndex + 1;
       --k, prev = curr, curr -= 2) {
    B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
        (1 / (parameters[k] - parameters[k - 1]));
    A = interpolatedPoints[curr] - (2 - parameters[k - 1]) * B;
    P0 += integral_B0(A, B, 2 - parameters[k], 2 - parameters[k - 1]);
    P1 += integral_B1(A, B, 2 - parameters[k], 2 - parameters[k - 1]);
    P2 += integral_B2(A, B, 2 - parameters[k], 2 - parameters[k - 1]);
    penalty += integral_a2(A, B, 2 - parameters[k], 2 - parameters[k - 1]);
  }
  if (prev == start + 1) curr = start;
  B = (interpolatedPoints[curr] - interpolatedPoints[prev]) *
      (1 / (parameters[k] - parameters[k - 1]));
  A = interpolatedPoints[curr] - (2 - parameters[k - 1]) * B;
  P0 += integral_B0(A, B, 2 - parameters[k], 1.0);
  P1 += integral_B1(A, B, 2 - parameters[k], 1.0);
  P2 += integral_B2(A, B, 2 - parameters[k], 1.0);
  penalty += integral_a2(A, B, 2 - parameters[k], 1.0);
  penalty -= 2 * (weightedDot(P0, ctrlPts[4]) + weightedDot(P1, ctrlPts[3]) + weightedDot(P2, ctrlPts[2]));

  if (penalty > maxPenalty || penalty < 0)
    return false;
  else
    metric.errorSum = penalty;

  return true;
}

//--------------------------------------------------------------------------
// Main entry point for converting a single sequence into a stroke
inline TStroke *convert(const Sequence &seq, double penalty) {
  SkeletonGraph *graph = seq.m_graphHolder;
  TStroke *result;

  std::vector<unsigned int> reducedIndices;

  // Special handling for circular sequences with degree-2 nodes
  if (seq.m_head == seq.m_tail && graph->getNode(seq.m_head).degree() == 2) {
    Sequence temp = seq;
    SequenceSimplifier simplifier(&temp);
    reducedIndices.push_back(seq.m_head);

    temp.m_head     = graph->getNode(seq.m_head).getLink(0).getNext();
    temp.m_headLink = !graph->getNode(temp.m_head).linkOfNode(seq.m_head);
    temp.m_tail     = graph->getNode(seq.m_tail).getLink(1).getNext();
    temp.m_tailLink = !graph->getNode(temp.m_tail).linkOfNode(seq.m_tail);

    simplifier.reduce(reducedIndices);
    reducedIndices.push_back(seq.m_tail);
  } else {
    SequenceSimplifier simplifier(&seq);
    simplifier.reduce(reducedIndices);
  }

  // Direct conversion for simple two-point segments
  if (reducedIndices.size() == 2) {
    std::vector<TThickPoint> segment(3);
    segment[0] = *graph->getNode(seq.m_head);
    segment[1] = (*graph->getNode(seq.m_head) + *graph->getNode(seq.m_tail)) * 0.5;
    segment[2] = *graph->getNode(seq.m_tail);
    return new TStroke(segment);
  }

  // Full conversion pipeline
  SequenceConverter converter(&seq, penalty);
  result = converter(&reducedIndices);

  // Preserve outline flags
  if (graph->getNode(seq.m_head)
          .getLink(seq.m_headLink)
          ->hasAttribute(SkeletonArc::SS_OUTLINE))
    result->setFlag(SkeletonArc::SS_OUTLINE, true);
  else if (graph->getNode(seq.m_head)
               .getLink(seq.m_headLink)
               ->hasAttribute(SkeletonArc::SS_OUTLINE_REVERSED))
    result->setFlag(SkeletonArc::SS_OUTLINE_REVERSED, true);

  return result;
}

//--------------------------------------------------------------------------
// Top-level conversion routine for all sequences in the image
void conversionToStrokes(std::vector<TStroke *> &strokes,
                         VectorizerCoreGlobals &g) {
  SequenceList &singleSequences           = g.singleSequences;
  JointSequenceGraphList &organizedGraphs = g.organizedGraphs;
  double penalty                          = g.currConfig->m_penalty;

  // Process isolated sequences
  for (unsigned int i = 0; i < singleSequences.size(); ++i) {
    if (singleSequences[i].m_head == singleSequences[i].m_tail) {
      // Adjust circular sequence endpoints for smoother closure
      SkeletonGraph *currGraph = singleSequences[i].m_graphHolder;
      unsigned int head     = singleSequences[i].m_head;
      unsigned int headLink = singleSequences[i].m_headLink;
      unsigned int next = currGraph->getNode(head).getLink(headLink).getNext();
      unsigned int nextLink = currGraph->getNode(next).linkOfNode(head);
      unsigned int newNode = currGraph->newNode(
          (*currGraph->getNode(head) + *currGraph->getNode(next)) * 0.5);
      currGraph->insert(newNode, head, headLink);
      *currGraph->node(newNode).link(0) = *currGraph->node(head).link(headLink);
      currGraph->insert(newNode, next, nextLink);
      *currGraph->node(newNode).link(1) = *currGraph->node(next).link(nextLink);
      singleSequences[i].m_head     = newNode;
      singleSequences[i].m_headLink = 0;
      singleSequences[i].m_tail     = newNode;
      singleSequences[i].m_tailLink = 1;
    }
    strokes.push_back(convert(singleSequences[i], penalty));
  }

  // Process graph-based sequences
  for (unsigned int i = 0; i < organizedGraphs.size(); ++i)
    for (unsigned int j = 0; j < organizedGraphs[i].getNodesCount(); ++j)
      if (!organizedGraphs[i].getNode(j).hasAttribute(JointSequenceGraph::ELIMINATED))
        for (unsigned int k = 0; k < organizedGraphs[i].getNode(j).getLinksCount(); ++k) {
          if (organizedGraphs[i].getNode(j).getLink(k)->isForward())
            strokes.push_back(
                convert(*organizedGraphs[i].getNode(j).getLink(k), penalty));
        }
}

#include "pch.h"
#include "window_finder.h"

HWND WindowFinder::LocateGameWindow() noexcept
{
    const DWORD currentProcId = GetCurrentProcessId();
    const HWND consoleWindow = GetConsoleWindow();
    SearchData info{ currentProcId, consoleWindow, nullptr };
    EnumWindows(EnumCallback, reinterpret_cast<LPARAM>(&info));
    return info.selectedHandle;
}

BOOL CALLBACK WindowFinder::EnumCallback(const HWND hwnd, const LPARAM lParam) noexcept
{
    const auto info = reinterpret_cast<SearchData*>(lParam);
    if (hwnd == info->consoleWindow || IsTerminalWindow(hwnd)) return TRUE;

    DWORD procId = 0;
    GetWindowThreadProcessId(hwnd, &procId);
    if (procId != info->processId) return TRUE;

    if (!IsPrimaryWindow(hwnd, info->consoleWindow)) return TRUE;

    info->selectedHandle = hwnd;
    return FALSE;
}

bool WindowFinder::IsPrimaryWindow(const HWND hwnd, const HWND consoleWindow) noexcept
{
    if (hwnd == consoleWindow) return false;
    if (!IsWindowVisible(hwnd)) return false;
    if (GetParent(hwnd) != nullptr) return false;

    RECT bounds;
    GetWindowRect(hwnd, &bounds);
    constexpr int MIN_DIMENSION = 150;
    if ((bounds.right - bounds.left) < MIN_DIMENSION || (bounds.bottom - bounds.top) < MIN_DIMENSION) return false;

    return true;
}

bool WindowFinder::IsTerminalWindow(const HWND hwnd) noexcept
{
    wchar_t windowClass[512];
    if (GetClassNameW(hwnd, windowClass, 512) == 0) return false;
    return wcscmp(windowClass, L"ConsoleWindowClass") == 0;
}

#include <bits/stdc++.h>
using namespace std;
#define int long long
#define pr pair<int, int>
#define pb push_back
#define mid (l + r) / 2
#define ls num << 1
#define rs num << 1 | 1

inline int read() {
    int value = 0, sign = 1;
    char ch = getchar();
    while (!isdigit(ch)) {
        if (ch == '-') sign = -1;
        ch = getchar();
    }
    while (isdigit(ch)) {
        value = value * 10 + ch - '0';
        ch = getchar();
    }
    return value * sign;
}

inline void write(int value) {
    if (value < 0) {
        putchar('-');
        write(-value);
        return;
    }
    if (value >= 10) write(value / 10);
    putchar('0' + value % 10);
}

#define Pr pair<int, pr>
const int MAX_SIZE = 30;
char grid1[MAX_SIZE][MAX_SIZE], grid2[MAX_SIZE][MAX_SIZE], pattern[MAX_SIZE][MAX_SIZE][MAX_SIZE], tempGrid[MAX_SIZE][MAX_SIZE];
int patternRows[MAX_SIZE], patternCols[MAX_SIZE], patternCount[MAX_SIZE][128], visited[MAX_SIZE][MAX_SIZE];
int totalCount[128];
vector<Pr> operations;

char readChar() {
    char ch = getchar();
    while ((ch < 'a' || ch > 'z') && (ch < 'A' || ch > 'Z') && !isdigit(ch)) ch = getchar();
    return ch;
}

signed main() {
    // freopen("2.in","r",stdin);
    // freopen("1.ans","w",stdout);
    int rows = read(), cols = read(), patterns = read();

    for (int i = 1; i <= rows; i++) {
        for (int j = 1; j <= cols; j++) {
            grid1[i][j] = readChar();
        }
    }

    for (int i = 1; i <= rows; i++) {
        for (int j = 1; j <= cols; j++) {
            grid2[i][j] = readChar();
            totalCount[grid2[i][j]]++;
        }
    }

    for (int p = 1; p <= patterns; p++) {
        int n1 = read(), m1 = read();
        patternRows[p] = n1;
        patternCols[p] = m1;
        for (int i = 1; i <= n1; i++) {
            for (int j = 1; j <= m1; j++) {
                pattern[p][i][j] = readChar();
                patternCount[p][pattern[p][i][j]]++;
            }
        }
    }

    while (1) {
        int selectedPattern = 0;
        for (int p = 1; p <= patterns; p++) {
            int needed = 0, hasChars = 0;
            for (int ch = 0; ch < 128; ch++) {
                needed += max(0ll, patternCount[p][ch] - totalCount[ch]);
                if (patternCount[p][ch] && totalCount[ch]) hasChars = 1;
            }
            if (needed <= totalCount[' '] && hasChars) {
                selectedPattern = p;
                break;
            }
        }

        if (!selectedPattern) break;

        memset(visited, 0, sizeof(visited));
        int n1 = patternRows[selectedPattern], m1 = patternCols[selectedPattern];

        for (int i = 1; i <= n1; i++) {
            for (int j = 1; j <= m1; j++) {
                int targetX = 0, targetY = 0;

                for (int x = 1; x <= rows; x++) {
                    for (int y = 1; y <= cols; y++) {
                        if (visited[x][y]) continue;
                        if (grid2[x][y] == pattern[selectedPattern][i][j]) {
                            targetX = x;
                            targetY = y;
                            break;
                        }
                    }
                    if (targetX) break;
                }

                if (!targetX) {
                    for (int x = 1; x <= rows; x++) {
                        for (int y = 1; y <= cols; y++) {
                            if (visited[x][y]) continue;
                            if (x == i && y < j) continue;
                            if (grid2[x][y] == ' ') {
                                targetX = x;
                                targetY = y;
                                break;
                            }
                        }
                        if (targetX) break;
                    }
                }

                while (targetX < i) {
                    operations.pb({-3, {targetX, targetY}});
                    swap(grid2[targetX][targetY], grid2[targetX + 1][targetY]);
                    targetX++;
                }

                while (targetY < j) {
                    operations.pb({-1, {targetX, targetY}});
                    swap(grid2[targetX][targetY], grid2[targetX][targetY + 1]);
                    targetY++;
                }

                while (targetY > j) {
                    operations.pb({-2, {targetX, targetY}});
                    swap(grid2[targetX][targetY], grid2[targetX][targetY - 1]);
                    targetY--;
                }

                while (targetX > i) {
                    operations.pb({-4, {targetX, targetY}});
                    swap(grid2[targetX][targetY], grid2[targetX - 1][targetY]);
                    targetX--;
                }

                visited[i][j] = 1;
                totalCount[grid2[i][j]]--;
                grid2[i][j] = ' ';
                totalCount[grid2[i][j]]++;
            }
        }

        operations.pb({selectedPattern, {1, 1}});

        while (1) {
            int sourceX = 0, sourceY = 0;
            for (int i = 1; i <= rows; i++) {
                for (int j = 1; j <= cols; j++) {
                    if (visited[i][j]) continue;
                    if (patternCount[selectedPattern][grid2[i][j]]) {
                        sourceX = i;
                        sourceY = j;
                        break;
                    }
                }
                if (sourceX) break;
            }

            if (!sourceX) break;

            int found = 0;
            for (int i = 1; i <= n1; i++) {
                for (int j = 1; j <= m1; j++) {
                    if (pattern[selectedPattern][i][j] == grid2[sourceX][sourceY]) {
                        found = 1;

                        while (sourceX < i) {
                            operations.pb({-3, {sourceX, sourceY}});
                            swap(grid2[sourceX][sourceY], grid2[sourceX + 1][sourceY]);
                            sourceX++;
                        }

                        while (sourceY < j) {
                            operations.pb({-1, {sourceX, sourceY}});
                            swap(grid2[sourceX][sourceY], grid2[sourceX][sourceY + 1]);
                            sourceY++;
                        }

                        while (sourceY > j) {
                            operations.pb({-2, {sourceX, sourceY}});
                            swap(grid2[sourceX][sourceY], grid2[sourceX][sourceY - 1]);
                            sourceY--;
                        }

                        while (sourceX > i) {
                            operations.pb({-4, {sourceX, sourceY}});
                            swap(grid2[sourceX][sourceY], grid2[sourceX - 1][sourceY]);
                            sourceX--;
                        }

                        totalCount[grid2[i][j]]--;
                        grid2[i][j] = ' ';
                        totalCount[grid2[i][j]]++;
                        operations.pb({selectedPattern, {1, 1}});
                        break;
                    }
                }
                if (found) break;
            }
        }
    }

    memset(visited, 0, sizeof(visited));
    int success = 1;

    for (int i = 1; i <= rows; i++) {
        for (int j = 1; j <= cols; j++) {
            int sourceX = 0, sourceY = 0;

            for (int x = 1; x <= rows; x++) {
                for (int y = 1; y <= cols; y++) {
                    if (visited[x][y]) continue;
                    if (grid2[x][y] == grid1[i][j]) {
                        sourceX = x;
                        sourceY = y;
                        break;
                    }
                }
                if (sourceX) break;
            }

            if (!sourceX) {
                for (int x = 1; x <= rows; x++) {
                    for (int y = 1; y <= cols; y++) {
                        if (visited[x][y]) continue;
                        if (grid2[x][y] == ' ') {
                            sourceX = x;
                            sourceY = y;
                            break;
                        }
                    }
                    if (sourceX) break;
                }
            }

            if (!sourceX) {
                success = 0;
                break;
            }

            while (sourceX < i) {
                operations.pb({-3, {sourceX, sourceY}});
                swap(grid2[sourceX][sourceY], grid2[sourceX + 1][sourceY]);
                sourceX++;
            }

            while (sourceY < j) {
                operations.pb({-1, {sourceX, sourceY}});
                swap(grid2[sourceX][sourceY], grid2[sourceX][sourceY + 1]);
                sourceY++;
            }

            while (sourceY > j) {
                operations.pb({-2, {sourceX, sourceY}});
                swap(grid2[sourceX][sourceY], grid2[sourceX][sourceY - 1]);
                sourceY--;
            }

            while (sourceX > i) {
                operations.pb({-4, {sourceX, sourceY}});
                swap(grid2[sourceX][sourceY], grid2[sourceX - 1][sourceY]);
                sourceX--;
            }

            visited[i][j] = 1;
        }
        if (!success) break;
    }

    if (!success) {
        puts("-1");
        return 0;
    }

    reverse(operations.begin(), operations.end());
    write(operations.size());
    putchar('\n');

    for (auto op : operations) {
        write(op.first);
        putchar(' ');
        write(op.second.first);
        putchar(' ');
        write(op.second.second);
        putchar('\n');
    }
}

