class DecorationShadowTextureCache {
public:
    ~DecorationShadowTextureCache();
    DecorationShadowTextureCache(const DecorationShadowTextureCache &) = delete;
    static DecorationShadowTextureCache &getInstance();
    void unregister(ShadowTextureProvider *provider);
    std::shared_ptr<GLTexture> getTexture(ShadowTextureProvider *provider);

private:
    DecorationShadowTextureCache() = default;

    struct CacheEntry {
        std::shared_ptr<GLTexture> texture;
        QList<ShadowTextureProvider *> providers;
    };

    QHash<KDecoration3::DecorationShadow *, CacheEntry> m_cache;
};

DecorationShadowTextureCache &DecorationShadowTextureCache::getInstance()
{
    static DecorationShadowTextureCache s_instance;
    return s_instance;
}

DecorationShadowTextureCache::~DecorationShadowTextureCache()
{
    Q_ASSERT(m_cache.isEmpty());
}

void DecorationShadowTextureCache::unregister(ShadowTextureProvider *provider)
{
    auto it = m_cache.begin();
    while (it != m_cache.end()) {
        auto &entry = it.value();
        auto providerIt = entry.providers.begin();
        while (providerIt != entry.providers.end()) {
            if (*providerIt == provider) {
                providerIt = entry.providers.erase(providerIt);
            } else {
                ++providerIt;
            }
        }
        if (entry.providers.isEmpty()) {
            it = m_cache.erase(it);
        } else {
            ++it;
        }
    }
}

std::shared_ptr<GLTexture> DecorationShadowTextureCache::getTexture(ShadowTextureProvider *provider)
{
    Shadow *shadow = provider->shadow();
    Q_ASSERT(shadow->hasDecorationShadow());

    unregister(provider);

    const auto decoShadow = shadow->decorationShadow().lock();
    Q_ASSERT(decoShadow);

    auto it = m_cache.find(decoShadow.get());
    if (it != m_cache.end()) {
        Q_ASSERT(!it.value().providers.contains(provider));
        it.value().providers << provider;
        return it.value().texture;
    }

    CacheEntry entry;
    entry.providers << provider;

    entry.texture = GLTexture::upload(shadow->decorationShadowImage());
    if (!entry.texture) {
        return nullptr;
    }

    entry.texture->setFilter(GL_LINEAR);
    entry.texture->setWrapMode(GL_CLAMP_TO_EDGE);

    m_cache.insert(decoShadow.get(), entry);
    return entry.texture;
}

// OpenGL-specific shadow texture provider implementation
class OpenGLShadowTextureProvider : public ShadowTextureProvider {
public:
    explicit OpenGLShadowTextureProvider(Shadow *shadow);
    ~OpenGLShadowTextureProvider() override;

    void update() override;

private:
    std::shared_ptr<GLTexture> m_texture;
};

OpenGLShadowTextureProvider::OpenGLShadowTextureProvider(Shadow *shadow)
    : ShadowTextureProvider(shadow)
    , m_texture()
{
}

OpenGLShadowTextureProvider::~OpenGLShadowTextureProvider()
{
    if (m_texture) {
        Compositor::self()->scene()->makeOpenGLContextCurrent();
        DecorationShadowTextureCache::getInstance().unregister(this);
        m_texture.reset();
    }
}

void OpenGLShadowTextureProvider::update()
{
    if (m_shadow->hasDecorationShadow()) {
        m_texture = DecorationShadowTextureCache::getInstance().getTexture(this);
        return;
    }

    // Compute total size needed for all shadow parts
    const QSize partTopLeft(m_shadow->shadowElement(Shadow::ShadowElementTopLeft).size());
    const QSize partTop(m_shadow->shadowElement(Shadow::ShadowElementTop).size());
    const QSize partTopRight(m_shadow->shadowElement(Shadow::ShadowElementTopRight).size());
    const QSize partLeft(m_shadow->shadowElement(Shadow::ShadowElementLeft).size());
    const QSize partRight(m_shadow->shadowElement(Shadow::ShadowElementRight).size());
    const QSize partBottomLeft(m_shadow->shadowElement(Shadow::ShadowElementBottomLeft).size());
    const QSize partBottom(m_shadow->shadowElement(Shadow::ShadowElementBottom).size());
    const QSize partBottomRight(m_shadow->shadowElement(Shadow::ShadowElementBottomRight).size());

    const int totalWidth = std::max({partTopLeft.width(), partLeft.width(), partBottomLeft.width()})
                         + std::max(partTop.width(), partBottom.width())
                         + std::max({partTopRight.width(), partRight.width(), partBottomRight.width()});
    const int totalHeight = std::max({partTopLeft.height(), partTop.height(), partTopRight.height()})
                          + std::max(partLeft.height(), partRight.height())
                          + std::max({partBottomLeft.height(), partBottom.height(), partBottomRight.height()});

    if (totalWidth <= 0 || totalHeight <= 0) {
        return;
    }

    QImage combinedImage(totalWidth, totalHeight, QImage::Format_ARGB32);
    combinedImage.fill(Qt::transparent);

    const int innerTop = std::max({partTopLeft.height(), partTop.height(), partTopRight.height()});
    const int innerLeft = std::max({partTopLeft.width(), partLeft.width(), partBottomLeft.width()});

    QPainter painter(&combinedImage);
    painter.drawImage(QRectF(0, 0, partTopLeft.width(), partTopLeft.height()), m_shadow->shadowElement(Shadow::ShadowElementTopLeft));
    painter.drawImage(QRectF(innerLeft, 0, partTop.width(), partTop.height()), m_shadow->shadowElement(Shadow::ShadowElementTop));
    painter.drawImage(QRectF(totalWidth - partTopRight.width(), 0, partTopRight.width(), partTopRight.height()), m_shadow->shadowElement(Shadow::ShadowElementTopRight));
    painter.drawImage(QRectF(0, innerTop, partLeft.width(), partLeft.height()), m_shadow->shadowElement(Shadow::ShadowElementLeft));
    painter.drawImage(QRectF(totalWidth - partRight.width(), innerTop, partRight.width(), partRight.height()), m_shadow->shadowElement(Shadow::ShadowElementRight));
    painter.drawImage(QRectF(0, totalHeight - partBottomLeft.height(), partBottomLeft.width(), partBottomLeft.height()), m_shadow->shadowElement(Shadow::ShadowElementBottomLeft));
    painter.drawImage(QRectF(innerLeft, totalHeight - partBottom.height(), partBottom.width(), partBottom.height()), m_shadow->shadowElement(Shadow::ShadowElementBottom));
    painter.drawImage(QRectF(totalWidth - partBottomRight.width(), totalHeight - partBottomRight.height(), partBottomRight.width(), partBottomRight.height()), m_shadow->shadowElement(Shadow::ShadowElementBottomRight));
    painter.end();

    // Optimize format if possible
    const auto currentContext = OpenGlContext::currentContext();
    if (!currentContext->isOpenGLES() && currentContext->supportsTextureSwizzle() && currentContext->supportsRGTextures()) {
        QImage alphaOnly(totalWidth, totalHeight, QImage::Format_Alpha8);
        bool isAlphaOnly = true;
        for (int y = 0; isAlphaOnly && y < combinedImage.height(); ++y) {
            const uint32_t *srcRow = reinterpret_cast<const uint32_t *>(combinedImage.scanLine(y));
            uint8_t *dstRow = reinterpret_cast<uint8_t *>(alphaOnly.scanLine(y));
            for (int x = 0; x < combinedImage.width(); ++x) {
                if (srcRow[x] & 0x00FFFFFF) {
                    isAlphaOnly = false;
                }
                dstRow[x] = qAlpha(srcRow[x]);
            }
        }
        if (isAlphaOnly) {
            combinedImage = alphaOnly;
        }
    }

    m_texture = GLTexture::upload(combinedImage);
    if (!m_texture) {
        return;
    }

    m_texture->setFilter(GL_LINEAR);
    m_texture->setWrapMode(GL_CLAMP_TO_EDGE);

    if (m_texture->internalFormat() == GL_R8) {
        m_texture->bind();
        m_texture->setSwizzle(GL_ZERO, GL_ZERO, GL_ZERO, GL_RED);
    }
}

