// Helper functions for clamping image edges
static void clamp_row(int left, int width, int right, const uint32_t *src, uint32_t *dest)
{
    std::fill_n(dest, left, *src);
    std::copy(src, src + width, dest + left);
    std::fill_n(dest + left + width, right, *(src + width - 1));
}

static void clamp_sides(int left, int width, int right, const uint32_t *src, uint32_t *dest)
{
    std::fill_n(dest, left, *src);
    std::fill_n(dest + left + width, right, *(src + width - 1));
}

static void clamp(QImage &image, const QRect &viewport)
{
    Q_ASSERT(image.depth() == 32);
    if (viewport.isEmpty()) {
        image = {};
        return;
    }

    const QRect rect = image.rect();
    const int leftPadding = viewport.left() - rect.left();
    const int topPadding = viewport.top() - rect.top();
    const int rightPadding = rect.right() - viewport.right();
    const int bottomPadding = rect.bottom() - viewport.bottom();

    const int innerWidth = rect.width() - leftPadding - rightPadding;
    const int innerHeight = rect.height() - topPadding - bottomPadding;

    const uint32_t *firstRow = reinterpret_cast<uint32_t *>(image.scanLine(topPadding));
    const uint32_t *lastRow = reinterpret_cast<uint32_t *>(image.scanLine(topPadding + innerHeight - 1));

    for (int i = 0; i < topPadding; ++i) {
        uint32_t *destRow = reinterpret_cast<uint32_t *>(image.scanLine(i));
        clamp_row(leftPadding, innerWidth, rightPadding, firstRow + leftPadding, destRow);
    }

    for (int i = 0; i < innerHeight; ++i) {
        uint32_t *destRow = reinterpret_cast<uint32_t *>(image.scanLine(topPadding + i));
        clamp_sides(leftPadding, innerWidth, rightPadding, destRow + leftPadding, destRow);
    }

    for (int i = 0; i < bottomPadding; ++i) {
        uint32_t *destRow = reinterpret_cast<uint32_t *>(image.scanLine(topPadding + innerHeight + i));
        clamp_row(leftPadding, innerWidth, rightPadding, lastRow + leftPadding, destRow);
    }
}

void SceneOpenGLDecorationRenderer::render(const QRegion &region)
{
    if (areImageSizesDirty()) {
        resizeTexture();
        resetImageSizesDirty();
    }

    if (!m_texture) {
        return;
    }

    QRectF leftRect, topRect, rightRect, bottomRect;
    client()->window()->layoutDecorationRects(leftRect, topRect, rightRect, bottomRect);

    const qreal pixelScale = effectiveDevicePixelRatio();
    const int topH = std::round(topRect.height() * pixelScale);
    const int bottomH = std::round(bottomRect.height() * pixelScale);
    const int leftW = std::round(leftRect.width() * pixelScale);

    const QPoint topPos(0, 0);
    const QPoint bottomPos(0, topPos.y() + topH + (2 * TexturePad));
    const QPoint leftPos(0, bottomPos.y() + bottomH + (2 * TexturePad));
    const QPoint rightPos(0, leftPos.y() + leftW + (2 * TexturePad));

    const QRect dirtyRect = region.boundingRect();

    renderPart(topRect.intersected(dirtyRect), topRect, topPos, pixelScale);
    renderPart(bottomRect.intersected(dirtyRect), bottomRect, bottomPos, pixelScale);
    renderPart(leftRect.intersected(dirtyRect), leftRect, leftPos, pixelScale, true);
    renderPart(rightRect.intersected(dirtyRect), rightRect, rightPos, pixelScale, true);
}

void SceneOpenGLDecorationRenderer::renderPart(const QRectF &rect, const QRectF &partRect,
                                               const QPoint &textureOffset,
                                               qreal devicePixelRatio, bool rotated)
{
    if (!rect.isValid() || !m_texture) {
        return;
    }

    const QMargins padding = texturePadForPart(rect, partRect);
    int verticalPad = padding.top() + padding.bottom();
    int horizontalPad = padding.left() + padding.right();

    QSize finalSize(toNativeSize(rect.width()), toNativeSize(rect.height()));
    if (rotated) {
        std::swap(finalSize.width(), finalSize.height());
    }

    QSize paddedSize = finalSize;
    paddedSize.rheight() += verticalPad;
    paddedSize.rwidth() += horizontalPad;

    QImage image(paddedSize, QImage::Format_ARGB32_Premultiplied);
    image.setDevicePixelRatio(devicePixelRatio);
    image.fill(Qt::transparent);

    QRect clipRect(padding.left(), padding.top(), finalSize.width(), finalSize.height());
    QPainter painter(&image);
    const qreal invScale = 1.0 / devicePixelRatio;
    painter.scale(invScale, invScale);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setClipRect(clipRect);
    painter.translate(padding.left(), padding.top());

    if (rotated) {
        painter.translate(0, finalSize.height());
        painter.rotate(-90);
    }

    painter.scale(devicePixelRatio, devicePixelRatio);
    painter.translate(-rect.topLeft());
    renderToPainter(&painter, rect);
    painter.end();

    clamp(image, clipRect);

    QPoint offset = ((rect.topLeft() - partRect.topLeft()) * devicePixelRatio).toPoint();
    if (padding.top() == 0) {
        offset.ry() += TexturePad;
    }
    if (padding.left() == 0) {
        offset.rx() += TexturePad;
    }

    m_texture->update(image, image.rect(), textureOffset + offset);
}

const QMargins SceneOpenGLDecorationRenderer::texturePadForPart(
    const QRectF &rect, const QRectF &partRect)
{
    QMargins result;
    if (rect.top() == partRect.top()) {
        result.setTop(TexturePad);
    }
    if (rect.bottom() == partRect.bottom()) {
        result.setBottom(TexturePad);
    }
    if (rect.left() == partRect.left()) {
        result.setLeft(TexturePad);
    }
    if (rect.right() == partRect.right()) {
        result.setRight(TexturePad);
    }
    return result;
}

static int alignValue(int value, int alignment)
{
    return (value + alignment - 1) & ~(alignment - 1);
}

void SceneOpenGLDecorationRenderer::resizeTexture()
{
    QRectF leftRect, topRect, rightRect, bottomRect;
    client()->window()->layoutDecorationRects(leftRect, topRect, rightRect, bottomRect);

    QSize size;
    size.rwidth() = toNativeSize(std::max({topRect.width(), bottomRect.width(), leftRect.height(), rightRect.height()}));
    size.rheight() = toNativeSize(topRect.height()) + toNativeSize(bottomRect.height()) + toNativeSize(leftRect.width()) + toNativeSize(rightRect.width());
    size.rheight() += 4 * (2 * TexturePad);
    size.rwidth() += 2 * TexturePad;
    size.rwidth() = alignValue(size.width(), 128);

    if (m_texture && m_texture->size() == size) {
        return;
    }

    if (!size.isEmpty()) {
        m_texture = GLTexture::allocate(GL_RGBA8, size);
        if (!m_texture) {
            return;
        }
        m_texture->setContentTransform(OutputTransform::FlipY);
        m_texture->setFilter(GL_LINEAR);
        m_texture->setWrapMode(GL_CLAMP_TO_EDGE);
    } else {
        m_texture.reset();
    }
}

int SceneOpenGLDecorationRenderer::toNativeSize(double size) const
{
    return std::round(size * effectiveDevicePixelRatio());
}

