#include "ArcKnowledgeFilter.h"
#include "ArcKnowledgeEntry.h"
#include "ArcKnowledgeQuery.h"

// Check if entry is within maximum allowed distance
bool FArcKnowledgeFilter_MaxDistance::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
	const float DistanceSquared = FVector::DistSquared(Entry.Location, Context.QueryOrigin);
	return DistanceSquared <= FMath::Square(MaxDistance);
}

// Check if entry meets minimum relevance requirement
bool FArcKnowledgeFilter_MinRelevance::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
	return Entry.Relevance >= MinRelevance;
}

// Check if entry is not older than allowed age
bool FArcKnowledgeFilter_MaxAge::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
	const double EntryAge = Context.CurrentTime - Entry.Timestamp;
	return EntryAge <= static_cast<double>(MaxAgeSeconds);
}

// Check if entry has required payload type
bool FArcKnowledgeFilter_PayloadType::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
	if (!RequiredPayloadType)
	{
		return true;
	}
	return Entry.Payload.IsValid() && Entry.Payload.GetScriptStruct()->IsChildOf(RequiredPayloadType);
}

// Check if entry has not been claimed yet
bool FArcKnowledgeFilter_NotClaimed::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
	return !Entry.bClaimed;
}

#include <guik/screen_capture.hpp>
#include <glk/io/png_io.hpp>
#include <glk/io/jpeg_io.hpp>
#include <glk/pixel_buffer.hpp>
#include <glk/console_colors.hpp>
#include <guik/viewer/light_viewer.hpp>

namespace guik {

ScreenCapture::ScreenCapture(
  const Eigen::Vector2i& img_dims,
  int num_worker_threads,
  int num_buffers,
  std::shared_ptr<guik::ConcurrentQueue<std::pair<std::string, PixelsPtr>>> output_queue)
: image_size(img_dims),
  frame_counter(0),
  shutdown_flag(false),
  work_queue(output_queue) {

  pending_outputs.resize(num_worker_threads);
  buffers.resize(num_buffers);

  for (auto& buffer : buffers) {
    buffer = std::make_shared<glk::PixelBuffer>(img_dims, sizeof(unsigned char) * 4);
  }

  workers.resize(num_worker_threads);
  for (auto& worker : workers) {
    worker = std::thread([this] { worker_task(); });
  }
}

ScreenCapture::~ScreenCapture() {
  for (int idx = 0; idx < buffers.size(); ++idx) {
    if (pending_outputs[idx].empty()) {
      continue;
    }

    auto pixel_data = std::make_shared<std::vector<unsigned char>>(std::move(buffers[idx]->read_pixels<unsigned char>()));
    work_queue->push(std::make_pair(pending_outputs[idx], pixel_data));
  }

  shutdown_flag = true;
  for (auto& worker : workers) {
    worker.join();
  }
}

size_t ScreenCapture::pending_count() const {
  return work_queue->size();
}

void ScreenCapture::capture(const std::string& output_path) {
  auto viewer = guik::viewer();
  capture(output_path, viewer->color_buffer());
}

void ScreenCapture::capture(const std::string& output_path, const glk::Texture& texture) {
  const int current_index = frame_counter % buffers.size();

  if (texture.size() != image_size) {
    std::cerr << glk::console::yellow << "warning: image dimensions mismatch!!" << glk::console::reset << std::endl;
    return;
  }

  if (!pending_outputs[current_index].empty()) {
    const auto& saved_filename = pending_outputs[current_index];
    auto pixel_data = std::make_shared<std::vector<unsigned char>>(std::move(buffers[current_index]->read_pixels<unsigned char>()));
    work_queue->push(std::make_pair(saved_filename, pixel_data));
  }

  pending_outputs[current_index] = output_path;
  buffers[current_index]->copy_from_texture(texture, GL_RGBA, GL_UNSIGNED_BYTE);
  frame_counter++;
}

void ScreenCapture::worker_task() {
  while (true) {
    auto batch = work_queue->try_pop(4);

    if (batch.empty()) {
      if (shutdown_flag) {
        break;
      }
      std::this_thread::sleep_for(std::chrono::milliseconds(10));
      continue;
    }

    for (const auto& [filename, pixels] : batch) {
      std::vector<unsigned char> temp_row(4 * image_size[0]);

      for (int row_top = 0; row_top < image_size[1] / 2; ++row_top) {
        const int row_bottom = image_size[1] - row_top - 1;

        auto line_top = pixels->data() + sizeof(unsigned char) * 4 * image_size[0] * row_top;
        auto line_bottom = pixels->data() + sizeof(unsigned char) * 4 * image_size[0] * row_bottom;

        memcpy(temp_row.data(), line_top, sizeof(unsigned char) * 4 * image_size[0]);
        memcpy(line_top, line_bottom, sizeof(unsigned char) * 4 * image_size[0]);
        memcpy(line_bottom, temp_row.data(), sizeof(unsigned char) * 4 * image_size[0]);
      }

      if (filename.size() >= 4 && filename.substr(filename.size() - 4) == ".png") {
        if (!glk::save_png(filename, image_size[0], image_size[1], *pixels)) {
          std::cerr << glk::console::yellow << "warning: failed to save " << filename << glk::console::reset << std::endl;
        }
      } else if (filename.size() >= 4 && filename.substr(filename.size() - 4) == ".jpg") {
        if (!glk::save_jpeg(filename, image_size[0], image_size[1], *pixels)) {
          std::cerr << glk::console::yellow << "warning: failed to save " << filename << glk::console::reset << std::endl;
        }
      } else {
        std::cerr << glk::console::yellow << "warning: unsupported file extension " << filename << glk::console::reset << std::endl;
      }
    }
  }
}

}

#include "tests.h"
