static void check_parse_result_match(testing & t, common_peg_parse_result_type expected, common_peg_parse_result_type actual) {
    t.assert_equal(common_peg_parse_result_type_name(expected), common_peg_parse_result_type_name(actual));
}

static std::string to_hex_string(const std::string& str) {
    std::ostringstream oss;
    for (unsigned char c : str) {
        if (std::isprint(c)) {
            oss << c;
        } else {
            oss << "\\x" << std::hex << std::setw(2) << std::setfill('0') << static_cast<int>(c);
        }
    }
    return oss.str();
}

void test_unicode_support(testing &t) {
    struct test_entry {
        std::string input_data;
        std::string expected_output;
        common_peg_parse_result_type expected_status;
    };

    t.test("any parser", [](testing &t) {
        std::vector<test_entry> cases {
            // Valid UTF-8 sequences
            {"World", "World", COMMON_PEG_PARSE_RESULT_SUCCESS},
            {std::string("M\xC3\xBCnchen"), std::string("M\xC3\xBCnchen"), COMMON_PEG_PARSE_RESULT_SUCCESS},
            {std::string("\xE4\xB8\xAD\xE6\x96\x87"), std::string("\xE4\xB8\xAD\xE6\x96\x87"), COMMON_PEG_PARSE_RESULT_SUCCESS},
            {std::string("\xF0\x9F\x91\x8D"), std::string("\xF0\x9F\x91\x8D"), COMMON_PEG_PARSE_RESULT_SUCCESS},
            // Incomplete UTF-8 sequences
            {std::string("Test\xC3"), "Test", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
            {std::string("\xE4"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
            {std::string("\xF0\x9F"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
            // Invalid/malformed UTF-8 sequences
            {std::string("\xFF\xFE"), "", COMMON_PEG_PARSE_RESULT_FAIL},
            {std::string("Data\x80End", 8), "Data", COMMON_PEG_PARSE_RESULT_FAIL},
            {std::string("\xC3\x41"), "", COMMON_PEG_PARSE_RESULT_FAIL},
        };
        auto parser = build_peg_parser([](common_peg_parser_builder& p) {
            return p.sequence({p.zero_or_more(p.any()), p.end()});
        });
        for (size_t idx = 0; idx < cases.size(); ++idx) {
            const auto & entry = cases[idx];
            std::string name = "case " + std::to_string(idx) + ": " + to_hex_string(entry.input_data);
            t.test(name, [&](testing &t) {
                common_peg_parse_context context(entry.input_data, true);
                auto result = parser.parse(context);
                check_parse_result_match(t, entry.expected_status, result.type);
                if (result.success() || result.need_more_input()) {
                    std::string captured = entry.input_data.substr(result.start, result.end - result.start);
                    t.assert_equal(entry.expected_output, captured);
                }
            });
        }
    });

    t.test("character sets", [](testing &t) {
        t.test("range U+3400-U+9FFF (CJK Extension A)", [](testing &t) {
            std::vector<test_entry> cases {
                // Within range
                {std::string("\xE3\x80\x80"), std::string("\xE3\x80\x80"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+3000
                {std::string("\xE4\xB8\x80"), std::string("\xE4\xB8\x80"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+4E00
                {std::string("\xE9\xBF\xBF"), std::string("\xE9\xBF\xBF"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+9FFF
                // Outside range
                {"z", "", COMMON_PEG_PARSE_RESULT_FAIL},
                {std::string("\xE4\xB7\xBF"), "", COMMON_PEG_PARSE_RESULT_FAIL}, // U+4DFF
                {std::string("\xEA\x80\x80"), "", COMMON_PEG_PARSE_RESULT_FAIL}, // U+A000
                // Incomplete sequences
                {std::string("\xE4"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
                {std::string("\xE9\xBF"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
            };
            auto parser = build_peg_parser([](common_peg_parser_builder& p) {
                return p.sequence({p.chars(R"([\u3400-\u9FFF])"), p.end()});
            });
            for (size_t idx = 0; idx < cases.size(); ++idx) {
                const auto & entry = cases[idx];
                std::string name = "case " + std::to_string(idx) + ": " + to_hex_string(entry.input_data);
                t.test(name, [&](testing &t) {
                    common_peg_parse_context context(entry.input_data, true);
                    auto result = parser.parse(context);
                    check_parse_result_match(t, entry.expected_status, result.type);
                    if (result.success() || result.need_more_input()) {
                        std::string captured = entry.input_data.substr(result.start, result.end - result.start);
                        t.assert_equal(entry.expected_output, captured);
                    }
                });
            }
        });

        t.test("emoji range U+1F600-U+1F64F", [](testing &t) {
            std::vector<test_entry> cases {
                // Within range
                {std::string("\xF0\x9F\x98\x80"), std::string("\xF0\x9F\x98\x80"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+1F600
                {std::string("\xF0\x9F\x98\x8A"), std::string("\xF0\x9F\x98\x8A"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+1F60A
                {std::string("\xF0\x9F\x99\x8F"), std::string("\xF0\x9F\x99\x8F"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+1F64F
                // Outside range
                {std::string("\xF0\x9F\x97\xBF"), "", COMMON_PEG_PARSE_RESULT_FAIL}, // U+1F5FF
                {std::string("\xF0\x9F\x99\x90"), "", COMMON_PEG_PARSE_RESULT_FAIL}, // U+1F650
                {std::string("\xF0\x9F\x9A\x80"), "", COMMON_PEG_PARSE_RESULT_FAIL}, // U+1F680
                // Incomplete sequences
                {std::string("\xF0\x9F\x98"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
                {std::string("\xF0"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
            };
            auto parser = build_peg_parser([](common_peg_parser_builder& p) {
                return p.sequence({p.chars(R"([\U0001F600-\U0001F64F])"), p.end()});
            });
            for (size_t idx = 0; idx < cases.size(); ++idx) {
                const auto & entry = cases[idx];
                std::string name = "case " + std::to_string(idx) + ": " + to_hex_string(entry.input_data);
                t.test(name, [&](testing &t) {
                    common_peg_parse_context context(entry.input_data, true);
                    auto result = parser.parse(context);
                    check_parse_result_match(t, entry.expected_status, result.type);
                    if (result.success() || result.need_more_input()) {
                        std::string captured = entry.input_data.substr(result.start, result.end - result.start);
                        t.assert_equal(entry.expected_output, captured);
                    }
                });
            }
        });

        t.test("combined ranges", [](testing &t) {
            std::vector<test_entry> cases {
                // CJK match
                {std::string("\xE4\xB8\x80"), std::string("\xE4\xB8\x80"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+4E00
                {std::string("\xE4\xBD\xA0"), std::string("\xE4\xBD\xA0"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+4F60
                // Emoji match
                {std::string("\xF0\x9F\x98\x80"), std::string("\xF0\x9F\x98\x80"), COMMON_PEG_PARSE_RESULT_SUCCESS}, // U+1F600
                // ASCII digit match
                {"7", "7", COMMON_PEG_PARSE_RESULT_SUCCESS},
                // No match
                {"x", "", COMMON_PEG_PARSE_RESULT_FAIL},
                {std::string("\xF0\x9F\x9A\x80"), "", COMMON_PEG_PARSE_RESULT_FAIL}, // U+1F680
                // Incomplete
                {std::string("\xE4"), "", COMMON_PEG_PARSE_RESULT_NEED_MORE_INPUT},
