            };
            auto parser = build_peg_parser([](common_peg_parser_builder& p) {
                return p.sequence({p.chars(R"([\u3400-\u9FFF\U0001F600-\U0001F64F0-9])"), p.end()});
            });
            for (size_t idx = 0; idx < cases.size(); ++idx) {
