    t.test("until parser", [](testing &t) {
        t.test("unicode before delimiter", [](testing &t) {
            std::vector<test_entry> cases {
                {std::string("\xE4\xBD\xA0\xE5\xA5\xBD</end>"), std::string("\xE4\xBD\xA0\xE5\xA5\xBD"), COMMON_PEG_PARSE_RESULT_SUCCESS},
