    });

    t.test("json_string parser", [](testing &t) {
        t.test("valid UTF-8 in strings", [](testing &t) {
            std::vector<test_entry> cases {
                {"Simple\"", "Simple", COMMON_PEG_PARSE_RESULT_SUCCESS},
                {std::string("G\xC3\xBCte\""), std::string("G\xC3\xBCte"), COMMON_PEG_PARSE_RESULT_SUCCESS},
                {std::string("\xE4\xB8\xAD\xE6\x96\x87\""), std::string("\xE4\xB8\xAD\xE6\x96\x87"), COMMON_PEG_PARSE_RESULT_SUCCESS},
                {std::string("\xF0\x9F\x91\x8D\""), std::string("\xF0\x9F\x91\x8D"), COMMON_PEG_PARSE_RESULT_SUCCESS},
                {std::string("Mix \xE4\xB8\x96\xE7\x95\x8C!\""), std::string("Mix \xE4\xB8\x96\xE7\x95\x8C!"), COMMON_PEG_PARSE_RESULT_SUCCESS},
            };
            for (size_t idx = 0; idx < cases.size(); ++idx) {
