#include <stdio.h>
#include <string.h>
#include <algorithm>
#include <deque>
#include <string>
#include <utility>
#include <vector>
#include "logging.h"
#include "pod_array.h"
#include "prog.h"
#include "regexp.h"
#include "sparse_array.h"
#include "sparse_set.h"
#include "strutil.h"

namespace lbug {
namespace regex {

static const bool ExtraDebug = false;

class NFA {
public:
    NFA(Prog* program);
    ~NFA();

    // Searches for a matching string.
    //   * If fixed is true, only considers matches starting at position.
    //     Otherwise finds leftmost match at or after position.
    //   * If maximal is true, returns the longest match starting
    //     at the chosen start point.  Otherwise returns the so-called
    //     left-biased match, the one traditional backtracking engines
    //     (like Perl and PCRE) find.
    // Records submatch boundaries in result[1..nresult-1].
    // Submatch[0] is the entire match.  When there is a choice in
    // which text matches each subexpression, the submatch boundaries
    // are chosen to match what a backtracking implementation would choose.
    bool Search(const StringPiece& input, const StringPiece& context, bool fixed, bool maximal,
        StringPiece* result, int nresult);

private:
    struct Thread {
        union {
            int ref;
            Thread* next; // when on free list
        };
        const char** capture;
    };

    // State for explicit stack in ExpandThreadq.
    struct WorkItem {
        int id;    // Inst to process
        Thread* t; // if not null, set t0 = t before processing id
    };

    // Threadq is a list of threads.  The list is sorted by the order
    // in which Perl would explore that particular state -- the earlier
    // choices appear earlier in the list.
    typedef SparseArray<Thread*> ThreadQueue;

    inline Thread* NewThread();
    inline Thread* AddRef(Thread* t);
    inline void ReleaseRef(Thread* t);

    // Follows all empty arrows from id0 and enqueues all the states reached.
    // Enqueues only the ByteRange instructions that match byte c.
    // context is used (with p) for evaluating empty-width specials.
    // p is the current input position, and t0 is the current thread.
    void ExpandThreadq(
        ThreadQueue* q, int id0, int c, const StringPiece& context, const char* p, Thread* t0);

    // Process runq on byte c, appending new states to nextq.
    // Updates found_ and best_ as new, better matches are found.
    // context is used (with p) for evaluating empty-width specials.
    // p is the position of byte c in the input string for ExpandThreadq;
    // p-1 will be used when processing Match instructions.
    // Frees all the threads on runq.
    // If there is a shortcut to the end, returns that shortcut.
    int Advance(ThreadQueue* runq, ThreadQueue* nextq, int c, const StringPiece& context, const char* p);

    // Returns text version of capture information, for debugging.
    std::string ShowCapture(const char** capture);

    void SaveCaptures(const char** dst, const char** src) {
        memmove(dst, src, capcount_ * sizeof src[0]);
    }

    Prog* prog_;               // underlying program
    int first_;                // start instruction in program
    int capcount_;             // number of submatches to track
    bool maximal_;             // whether searching for longest match
    bool mustend_;             // whether match must end at text.end()
    const char* btext_;        // beginning of text (for FormatSubmatch)
    const char* etext_;        // end of text (for mustend_)
    ThreadQueue q0_, q1_;      // pre-allocated for Search.
    PODArray<WorkItem> workstack_; // pre-allocated for ExpandThreadq
    std::deque<Thread> pool_;  // thread arena
    Thread* freelist_;         // thread freelist
    const char** best_;        // best match so far
    bool found_;               // any match so far?

    NFA(const NFA&) = delete;
    NFA& operator=(const NFA&) = delete;
};

// Constructor: Initialize NFA with given program
NFA::NFA(Prog* program) {
    prog_ = program;
    first_ = program_->start();
    capcount_ = 0;
    maximal_ = false;
    mustend_ = false;
    btext_ = NULL;
    etext_ = NULL;
    q0_.resize(prog_->size());
    q1_.resize(prog_->size());

    // See NFA::ExpandThreadq() for why this is so.
    int nstack = 2 * prog_->inst_count(kInstCapture) + prog_->inst_count(kInstEmptyWidth) +
                 prog_->inst_count(kInstNop) + 1; // + 1 for start inst
    workstack_ = PODArray<WorkItem>(nstack);
    freelist_ = NULL;
    best_ = NULL;
    found_ = false;
}

// Destructor: Clean up allocated resources
NFA::~NFA() {
    delete[] best_;
    for (const Thread& t : pool_)
        delete[] t.capture;
}

// Allocate a new thread from the pool or create a new one
NFA::Thread* NFA::NewThread() {
    Thread* t = freelist_;
    if (t != NULL) {
        freelist_ = t->next;
        t->ref = 1;
        // We don't need to touch t->capture because
        // the caller will immediately overwrite it.
        return t;
    }
    pool_.emplace_back();
    t = &pool_.back();
    t->ref = 1;
    t->capture = new const char*[capcount_];
    return t;
}

// Increment reference count of a thread
NFA::Thread* NFA::AddRef(Thread* t) {
    DCHECK(t != NULL);
    t->ref++;
    return t;
}

// Decrement reference count and free if zero
void NFA::ReleaseRef(Thread* t) {
    DCHECK(t != NULL);
    t->ref--;
    if (t->ref > 0)
        return;
    DCHECK_EQ(t->ref, 0);
    t->next = freelist_;
    freelist_ = t;
}

// Follows all empty arrows from id0 and enqueues all the states reached.
// Enqueues only the ByteRange instructions that match byte c.
// context is used (with p) for evaluating empty-width specials.
// p is the current input position, and t0 is the current thread.
void NFA::ExpandThreadq(
    ThreadQueue* q, int id0, int c, const StringPiece& context, const char* p, Thread* t0) {
    if (id0 == 0)
        return;

    // Use workstack_ to hold our stack of instructions yet to process.
    // It was preallocated as follows:
    //   two entries per Capture;
    //   one entry per EmptyWidth; and
    //   one entry per Nop.
    // This reflects the maximum number of stack pushes that each can
    // perform. (Each instruction can be processed at most once.)
    WorkItem* stk = workstack_.data();
    int nstk = 0;
    stk[nstk++] = {id0, NULL};

    while (nstk > 0) {
        DCHECK_LE(nstk, workstack_.size());
        WorkItem a = stk[--nstk];

    Loop:
        if (a.t != NULL) {
            // t0 was a thread that we allocated and copied in order to
            // record the capture, so we must now release it.
            ReleaseRef(t0);
            t0 = a.t;
        }
        int id = a.id;
        if (id == 0)
            continue;
        if (q->has_index(id)) {
            if (ExtraDebug)
                fprintf(stderr, "  [%d%s]\n", id, ShowCapture(t0->capture).c_str());
            continue;
        }

        // Create entry in q no matter what.  We might fill it in below,
        // or we might not.  Even if not, it is necessary to have it,
        // so that we don't revisit id0 during the recursion.
        q->set_new(id, NULL);
        Thread** tp = &q->get_existing(id);
        int j;
        Thread* t;
        Prog::Inst* ip = prog_->inst(id);

        switch (ip->opcode()) {
        default:
            LOG(DFATAL) << "unhandled " << ip->opcode() << " in ExpandThreadq";
            break;
        case kInstFail:
            break;
        case kInstAltMatch:
            // Save state; will pick up at next byte.
            t = AddRef(t0);
            *tp = t;
            DCHECK(!ip->last());
            a = {id + 1, NULL};
            goto Loop;
        case kInstNop:
            if (!ip->last())
                stk[nstk++] = {id + 1, NULL};
            // Continue on.
            a = {ip->out(), NULL};
            goto Loop;
        case kInstCapture:
            if (!ip->last())
                stk[nstk++] = {id + 1, NULL};
            if ((j = ip->cap()) < capcount_) {
                // Push a dummy whose only job is to restore t0
                // once we finish exploring this possibility.
                stk[nstk++] = {0, t0};
                // Record capture.
                t = NewThread();
                SaveCaptures(t->capture, t0->capture);
                t->capture[j] = p;
                t0 = t;
            }
            a = {ip->out(), NULL};
            goto Loop;
        case kInstByteRange:
            if (!ip->Matches(c))
                goto Next;
            // Save state; will pick up at next byte.
            t = AddRef(t0);
            *tp = t;
            if (ExtraDebug)
                fprintf(stderr, " + %d%s\n", id, ShowCapture(t0->capture).c_str());
            if (ip->hint() == 0)
                break;
            a = {id + ip->hint(), NULL};
            goto Loop;
        case kInstMatch:
            // Save state; will pick up at next byte.
            t = AddRef(t0);
            *tp = t;
            if (ExtraDebug)
                fprintf(stderr, " ! %d%s\n", id, ShowCapture(t0->capture).c_str());
        Next:
            if (ip->last())
                break;
            a = {id + 1, NULL};
            goto Loop;
        case kInstEmptyWidth:
            if (!ip->last())
                stk[nstk++] = {id + 1, NULL};
            // Continue on if we have all the right flag bits.
            if (ip->empty() & ~Prog::EmptyFlags(context, p))
                break;
            a = {ip->out(), NULL};
            goto Loop;
        }
    }
}

// Process runq on byte c, appending new states to nextq.
// Updates found_ and best_ as new, better matches are found.
// context is used (with p) for evaluating empty-width specials.
// p is the position of byte c in the input string for ExpandThreadq;
// p-1 will be used when processing Match instructions.
// Frees all the threads on runq.
// If there is a shortcut to the end, returns that shortcut.
int NFA::Advance(ThreadQueue* runq, ThreadQueue* nextq, int c, const StringPiece& context, const char* p) {
    nextq->clear();
    for (ThreadQueue::iterator i = runq->begin(); i != runq->end(); ++i) {
        Thread* t = i->value();
        if (t == NULL)
            continue;
        if (maximal_) {
            // Can skip any threads started after our current best match.
            if (found_ && best_[0] < t->capture[0]) {
                ReleaseRef(t);
                continue;
            }
        }
        int id = i->index();
        Prog::Inst* ip = prog_->inst(id);
        switch (ip->opcode()) {
        default:
            // Should only see the values handled below.
            LOG(DFATAL) << "Unhandled " << ip->opcode() << " in advance";
            break;
        case kInstByteRange:
            ExpandThreadq(nextq, ip->out(), c, context, p, t);
            break;
        case kInstAltMatch:
            if (i != runq->begin())
                break;
            // The match is ours if we want it.
            if (ip->greedy(prog_) || maximal_) {
                SaveCaptures(best_, t->capture);
                found_ = true;
                ReleaseRef(t);
                for (++i; i != runq->end(); ++i) {
                    if (i->value() != NULL)
                        ReleaseRef(i->value());
                }
                runq->clear();
                if (ip->greedy(prog_))
                    return ip->out1();
                return ip->out();
            }
            break;
        case kInstMatch: {
            // Avoid invoking undefined behavior (arithmetic on a null pointer)
            // by storing p instead of p-1. (What would the latter even mean?!)
            // This complements the special case in NFA::Search().
            if (p == NULL) {
                SaveCaptures(best_, t->capture);
                best_[1] = p;
                found_ = true;
                break;
            }
            if (mustend_ && p - 1 != etext_)
                break;
            if (maximal_) {
                // Leftmost-longest mode: save this match only if
                // it is either farther to the left or at the same
                // point but longer than an existing match.
                if (!found_ || t->capture[0] < best_[0] ||
                    (t->capture[0] == best_[0] && p - 1 > best_[1])) {
                    SaveCaptures(best_, t->capture);
                    best_[1] = p - 1;
                    found_ = true;
                }
            } else {
                // Leftmost-biased mode: this match is by definition
                // better than what we've already found (see next line).
                SaveCaptures(best_, t->capture);
                best_[1] = p - 1;
                found_ = true;
                // Cut off the threads that can only find matches
                // worse than the one we just found: don't run the
                // rest of the current Threadq.
                ReleaseRef(t);
                for (++i; i != runq->end(); ++i) {
                    if (i->value() != NULL)
                        ReleaseRef(i->value());
                }
                runq->clear();
                return 0;
            }
            break;
        }
        }
        ReleaseRef(t);
    }
    runq->clear();
    return 0;
}

// Convert capture array to human-readable string for debugging
std::string NFA::ShowCapture(const char** capture) {
    std::string s;
    for (int i = 0; i < capcount_; i += 2) {
        if (capture[i] == NULL)
            s += "(?,?)";
        else if (capture[i + 1] == NULL)
            s += StringPrintf("(%td,?)", capture[i] - btext_);
        else
            s += StringPrintf("(%td,%td)", capture[i] - btext_, capture[i + 1] - btext_);
    }
    return s;
}

// Main search function
bool NFA::Search(const StringPiece& text, const StringPiece& const_context, bool fixed,
    bool maximal, StringPiece* result, int nresult) {
    if (first_ == 0)
        return false;
    StringPiece context = const_context;
    if (context.data() == NULL)
        context = text;

    // Sanity check: make sure that text lies within context.
    if (BeginPtr(text) < BeginPtr(context) || EndPtr(text) > EndPtr(context)) {
        LOG(DFATAL) << "context does not contain text";
        return false;
    }

    if (prog_->anchor_start() && BeginPtr(context) != BeginPtr(text))
        return false;
    if (prog_->anchor_end() && EndPtr(context) != EndPtr(text))
        return false;

    fixed |= prog_->anchor_start();
    if (prog_->anchor_end()) {
        maximal = true;
        mustend_ = true;
    }

    if (nresult < 0) {
        LOG(DFATAL) << "Bad args: nresult=" << nresult;
        return false;
    }

    // Save search parameters.
    capcount_ = 2 * nresult;
    maximal_ = maximal;
    if (nresult == 0) {
        // We need to maintain best[0], both to distinguish the
        // maximal match (if maximal is true) and also to tell
        // whether we've seen any matches at all.
        capcount_ = 2;
    }

    best_ = new const char*[capcount_];
    memset(best_, 0, capcount_ * sizeof best_[0]);
    found_ = false;

    // For debugging prints.
    btext_ = context.data();
    // For convenience.
    etext_ = text.data() + text.size();

    if (ExtraDebug)
        fprintf(stderr, "NFA::Search %s (context: %s) fixed=%d maximal=%d\n",
            std::string(text).c_str(), std::string(context).c_str(), fixed, maximal);

    // Set up search.
    ThreadQueue* runq = &q0_;
    ThreadQueue* nextq = &q1_;
    runq->clear();
    nextq->clear();

    // Loop over the text, stepping the machine.
    for (const char* p = text.data();; p++) {
        if (ExtraDebug) {
            int c = 0;
            if (p == btext_)
                c = '^';
            else if (p > etext_)
                c = '$';
            else if (p < etext_)
                c = p[0] & 0xFF;
            fprintf(stderr, "%c:", c);
            for (ThreadQueue::iterator i = runq->begin(); i != runq->end(); ++i) {
                Thread* t = i->value();
                if (t == NULL)
                    continue;
                fprintf(stderr, " %d%s", i->index(), ShowCapture(t->capture).c_str());
            }
            fprintf(stderr, "\n");
        }

        // This is a no-op the first time around the loop because runq is empty.
        int id = Advance(runq, nextq, p < etext_ ? p[0] & 0xFF : -1, context, p);
        DCHECK_EQ(runq->size(), 0);
        using std::swap;
        swap(nextq, runq);
        nextq->clear();

        if (id != 0) {
            // We're done: full match ahead.
            p = etext_;
            for (;;) {
                Prog::Inst* ip = prog_->inst(id);
                switch (ip->opcode()) {
                default:
                    LOG(DFATAL) << "Unexpected opcode in short circuit: " << ip->opcode();
                    break;
                case kInstCapture:
                    if (ip->cap() < capcount_)
                        best_[ip->cap()] = p;
                    id = ip->out();
                    continue;
                case kInstNop:
                    id = ip->out();
                    continue;
                case kInstMatch:
                    best_[1] = p;
                    found_ = true;
                    break;
                }
                break;
            }
            break;
        }

        if (p > etext_)
            break;

        // Start a new thread if there have not been any matches.
        // (No point in starting a new thread if there have been
        // matches, since it would be to the right of the match
        // we already found.)
        if (!found_ && (!fixed || p == text.data())) {
            // Try to use prefix accel (e.g. memchr) to skip ahead.
            // The search must be unanchored and there must be zero
            // possible matches already.
            if (!fixed && runq->size() == 0 && p < etext_ && prog_->can_prefix_accel()) {
                p = reinterpret_cast<const char*>(prog_->PrefixAccel(p, etext_ - p));
                if (p == NULL)
                    p = etext_;
            }

            Thread* t = NewThread();
            SaveCaptures(t->capture, best_);
            t->capture[0] = p;
            ExpandThreadq(runq, first_, p < etext_ ? p[0] & 0xFF : -1, context, p, t);
            ReleaseRef(t);
        }

        // If all the threads have died, stop early.
        if (runq->size() == 0) {
            if (ExtraDebug)
                fprintf(stderr, "dead\n");
            break;
        }

        // Avoid invoking undefined behavior (arithmetic on a null pointer)
        // by simply not continuing the loop.
        // This complements the special case in NFA::Advance().
        if (p == NULL) {
            (void)Advance(runq, nextq, -1, context, p);
            DCHECK_EQ(runq->size(), 0);
            using std::swap;
            swap(nextq, runq);
            nextq->clear();
            break;
        }
    }

    for (ThreadQueue::iterator i = runq->begin(); i != runq->end(); ++i) {
        if (i->value() != NULL)
            ReleaseRef(i->value());
    }

    if (found_) {
        for (int i = 0; i < nresult; i++)
            result[i] =
                StringPiece(best_[2 * i], static_cast<size_t>(best_[2 * i + 1] - best_[2 * i]));
        if (ExtraDebug)
            fprintf(stderr, "match (%td,%td)\n", best_[0] - btext_, best_[1] - btext_);
        return true;
    }
    return false;
}

// Public interface for NFA search
bool Prog::SearchNFA(const StringPiece& text, const StringPiece& context, Anchor anchor,
    MatchKind kind, StringPiece* match, int nmatch) {
    if (ExtraDebug)
        Dump();
    NFA nfa(this);
    StringPiece sp;
    if (kind == kFullMatch) {
        anchor = kAnchored;
        if (nmatch == 0) {
            match = &sp;
            nmatch = 1;
        }
    }
    if (!nfa.Search(text, context, anchor == kAnchored, kind != kFirstMatch, match, nmatch))
        return false;
    if (kind == kFullMatch && EndPtr(match[0]) != EndPtr(text))
        return false;
    return true;
}

// Compute fanout for each reachable instruction
void Prog::Fanout(SparseArray<int>* fanout) {
    DCHECK_EQ(fanout->max_size(), size());
    SparseSet reachable(size());
    fanout->clear();
    fanout->set_new(start(), 0);
    for (SparseArray<int>::iterator i = fanout->begin(); i != fanout->end(); ++i) {
        int* count = &i->value();
        reachable.clear();
        reachable.insert(i->index());
        for (SparseSet::iterator j = reachable.begin(); j != reachable.end(); ++j) {
            int id = *j;
            Prog::Inst* ip = inst(id);
            switch (ip->opcode()) {
            default:
                LOG(DFATAL) << "unhandled " << ip->opcode() << " in Prog::Fanout()";
                break;
            case kInstByteRange:
                if (!ip->last())
                    reachable.insert(id + 1);
                (*count)++;
                if (!fanout->has_index(ip->out())) {
                    fanout->set_new(ip->out(), 0);
                }
                break;
            case kInstAltMatch:
                DCHECK(!ip->last());
                reachable.insert(id + 1);
                break;
            case kInstCapture:
            case kInstEmptyWidth:
            case kInstNop:
                if (!ip->last())
                    reachable.insert(id + 1);
                reachable.insert(ip->out());
                break;
            case kInstMatch:
                if (!ip->last())
                    reachable.insert(id + 1);
                break;
            case kInstFail:
                break;
            }
        }
    }
}

