const fs_info *
bk_util::get_filesystem_info_by_name(const fs_map &container, const std::string &key)
{
    auto iter = container.find(key);
    if (iter == container.end())
        return nullptr;
    return &(iter->second); // immutable reference, no copying involved
}

/* NOTE FOR THE DEVS: you must ensure that the next three function's
* return vectors NEVER EVER contain the same UUID across their return
* values.
*
* For example:
*
* Good:
* - added: abcde
* - added: fghij
* - changed: klmno
* - removed: pqrst
*
* DANGEROUS, DON'T ALLOW THIS TO HAPPEN
* - added: abcde
* - added: fghij
* - changed: abcde <- also in "added"
* - changed: fghij <- also in "added" and "removed"
* - removed: uvwxy
* - removed: fghij
* 
* The same UUID contained within multiple function returns will
* cause table refresh issues in the GUI and break functionality.
* The above "Dangerous" must NEVER happen.
*/

/**
* @brief Return a new fs_vec containing only the new filesystem
* entities.
*
* @return A fs_vec containing filesystem entities from current_list
* that don't exist in the previous filesystem list.
*
* @param old_snapshot Your latest filesystem list snapshot, prior refresh.
* @param current_list Your new filesystem list snapshot you want to
* compare your last one against; whatever is contained here that
* isn't present in the old fs_vec will be added to this function's
* return.
*/
fs_map
bk_util::extract_newly_added_filesystems (const std::vector<std::string> &old_snapshot, const fs_map &current_list) 
{
    fs_map newly_discovered;
    newly_discovered.reserve(current_list.size());
    for (const auto &[uuid, info] : current_list) { // avoid unnecessary copies
        if (std::find(old_snapshot.begin(), old_snapshot.end(), uuid) == old_snapshot.end()) {
            newly_discovered.emplace(uuid, info); // copy only when needed
        }
        // if it already exists, skip processing
    }
    return newly_discovered;
}

/**
* @brief Return a new fs_vec containing the filesystem entities
* that have been removed from the last snapshot.
*
* @return A fs_vec containing filesystem entities from old_snapshot
* that don't exist in the newer filesystem list but did exist in
* the previous list. Note that this must NOT include newly added
* filesystems.
*
* @param old_snapshot Your latest filesystem list snapshot, prior refresh.
* @param current_list Your new filesystem list snapshot you want to
* compare your last one against; whatever is contained in the old
* list that isn't present in the new fs_vec will be added to this
* function's return.
*/
std::vector<std::string>
bk_util::extract_just_removed_filesystems (const std::vector<std::string> &old_snapshot, const fs_map &current_list) 
{
    std::vector<std::string> missing_entries;
    missing_entries.reserve(old_snapshot.size());
    for (const std::string &uuid : old_snapshot) {
        if (current_list.find(uuid) == current_list.end()) {
            missing_entries.emplace_back(uuid);
            // if it still exists, do nothing
        }
    }
    return missing_entries;
}

/**
* @brief Return a new fs_vec which contains all filesystem entities
* that still exist in both old_snapshot and current list and that have at
* least one of its data values changed.
*
* @return A fs_vec containing all filesystem entities that exist in
* both the old_snapshot and the current list and have at least one of its data
* values changed, comparing everything but the UUIDs since that's the
* reference key and so those comparisons would always be true.
*/
fs_map
bk_util::extract_changed_filesystems (const fs_map &old_snapshot, const fs_map &current_list)
{
    fs_map modified_entries;
    modified_entries.reserve(current_list.size());
    for (const auto &[uuid, info] : current_list) {
        const auto existing_entry = old_snapshot.find(uuid);
        // if it DOES exist in both current and old snapshot
        if (existing_entry != old_snapshot.end()) {
            // if any field differs, record the change
            if (
                info.label != existing_entry->second.label
            ||  info.status != existing_entry->second.status
            ||  info.devname != existing_entry->second.devname
            ) {
                modified_entries.emplace(uuid, info);
            }
        }
    }
    return modified_entries;
}

fs_diff
bk_util::compute_fs_difference (
    const fs_map &old_snapshot,
    const fs_map &current_list
)
{
    fs_diff result;
    std::vector<std::string> old_uuids;
    for (const auto &[uuid, info] : old_snapshot) {
        old_uuids.emplace_back(uuid);
    }
    result.added = extract_newly_added_filesystems(old_uuids, current_list);
    result.removed = extract_just_removed_filesystems(old_uuids, current_list);
    result.changed = extract_changed_filesystems(old_snapshot, current_list);
    return result;
}

