StudentImpl::StudentImpl(std::string name, std::string surName, std::string firstName)
  : Parent(std::move(name), std::move(surName), std::move(firstName))
{
  attentionNoise_.seed(sen::hashCombine(sen::crc32("attention"), sen::crc32(name), rand()));        // NOLINT
  breathingLevelNoise_.seed(sen::hashCombine(sen::crc32("breathing"), sen::crc32(name), rand()));  // NOLINT
  setNextStatus(Idle {});
}
StudentImpl::~StudentImpl() = default;

void StudentImpl::update(sen::kernel::RunApi& runApi)
{
  PersonImpl::update(runApi);
  // update our status
  std::visit(sen::Overloaded {[&](const Idle& activity) { remainIdle(runApi.getTime(), activity); },
                              [&](const Engaged& activity) { engage(runApi.getTime(), activity); },
                              [&](const Resting& activity) { rest(runApi.getTime(), activity); }},
             getStatus());
}

std::string StudentImpl::respondImpl(const std::string& query)
{
  std::ignore = query;  // this is the typical behavior in schools and corporate environments
  // answer depending on what we were doing
  return std::visit(sen::Overloaded {[&](const Idle& /*activity*/) -> std::string
                                     {
                                       std::array<const char*, 3> replies = {
                                         "Sure",
                                         "Not really",
                                         "Maybe...",
                                       };
                                       return replies.at(rand() % replies.size());  // NOLINT
                                     },
                                     [&](const Engaged& /*activity*/) -> std::string
                                     {
                                       std::array<const char*, 3> replies = {
                                         "I'm occupied!",
                                         "Can't tell yet",
                                         "Wait a sec, I'm wrapping up",
                                       };
                                       return replies.at(rand() % replies.size());  // NOLINT
                                     },
                                     [&](const Resting& /*activity*/) -> std::string
                                     {
                                       setNextStatus(Idle {getLastCommitTime()});  // wake up
                                       std::array<const char*, 3> replies = {
                                         "hmm...?",
                                         "uhhh... ??",
                                         "....zzzZzzZz",
                                       };
                                       return replies.at(rand() % replies.size());  // NOLINT
                                     }},
                    getStatus());
}

bool StudentImpl::beginTaskImpl(const std::string& taskName, float32_t challenge)
{
  // reject the task if we are already doing something
  if (std::holds_alternative<Engaged>(getStatus()))
  {
    return false;
  }
  setNextStatus(Engaged {this->getLastCommitTime(), taskName, challenge, 0.0f});
  return true;
}

void StudentImpl::remainIdle(const sen::TimeStamp& time, const Idle& activity)
{
  setNextAttentionLevel((static_cast<float32_t>(attentionNoise_({time.sinceEpoch().toSeconds()})) + 1.0f) * 0.5f * 0.1f);
  // ensure we mark the time since we idle
  if (activity.since.sinceEpoch().getNanoseconds() == 0)
  {
    setNextStatus(Idle {time});
  }
  else if (time - activity.since > sen::Duration(std::chrono::seconds(5)))
  {
    // go to rest after some time of idling
    setNextStatus(Resting {time});
    setNextAttentionLevel(0.0f);
  }
  else if (rand() % 10 == 0)  // NOLINT
  {
    // otherwise, say random things
    static std::array<const char*, 4> remarks = {"I'm tired", "la la la...", "teacher's boring", "this is dull"};
    saidSomething(remarks.at(rand() % remarks.size()));  // NOLINT
  }
}

void StudentImpl::engage(const sen::TimeStamp& time, const Engaged& activity)
{
  auto advancement = activity.advance + activity.challenge;
  setNextAttentionLevel((static_cast<float32_t>(attentionNoise_({time.sinceEpoch().toSeconds()})) + 1.0f) * 0.5f);
  if (advancement >= 1.0f)
  {
    setNextStatus(Idle {time});
    saidSomething("completed " + activity.taskName);
  }
  else
  {
    Engaged newValue = activity;
    newValue.advance = advancement;
    setNextStatus(std::move(newValue));
    if (rand() % 7 == 0)  // NOLINT
    {
      saidSomething("this " + activity.taskName + " isn't simple...");
    }
  }
}

void StudentImpl::rest(const sen::TimeStamp& time, const Resting& activity)
{
  auto t = time.sinceEpoch().toSeconds();
  if (time - activity.since > std::chrono::seconds(3))
  {
    // wake up due own breathing
    setNextStatus(Idle {time});
    saidSomething("did I nap?");
    return;
  }
  auto breathIntensity = breathingLevelNoise_({t});
  if (breathIntensity < 0.9)
  {
    Resting nextStatus = activity;
    nextStatus.breathIntensity = static_cast<float32_t>(breathIntensity);
    setNextStatus(nextStatus);
  }
  else
  {
    static std::array<const char*, 4> sounds = {"snrghh..phfff", "mmfmm.ghnff", "mmm?...zzzZzz", "grr..ffpg"};
    static std::array<float32_t, 5> intensities = {0.1f, 0.7f, 0.33f, 1.3f, 0.41f};
    // wake up due own breathing
    setNextStatus(Idle {time});
    // make some sound
    madeSomeNoise(sounds.at(rand() % sounds.size()), intensities.at(rand() % intensities.size()));  // NOLINT
  }
}

void StudentImpl::noticeSound(const std::string& sound, float32_t intensity)
{
  if (rand() % 2 == 0)  // NOLINT
  {
    std::string cause;
    cause.append("detected sound '");
    cause.append(sound);
    cause.append("' with intensity ");
    cause.append(std::to_string(intensity));
    gotDistracted(cause);
  }
}
