// Function to evaluate the VDE model
void VDE_fun_model(const double* input, double* output,
                      int (*vde_solver)(const double**, double**, int*, double*,
                                 int)) {
    const int STATE_DIM = 4;
    const int INPUT_DIM = 1;
    const double* state = input;
    const double* Su_input = input + STATE_DIM;
    const double* Sx_input = input + STATE_DIM + INPUT_DIM * STATE_DIM;
    const double* control = input + STATE_DIM + STATE_DIM * (STATE_DIM + INPUT_DIM);
    double* state_out = output;
    double* Su_output = output + STATE_DIM;
    double* Sx_output = output + STATE_DIM + INPUT_DIM * STATE_DIM;
    const double* casadi_inputs[4];
    double* casadi_outputs[3];
    casadi_inputs[0] = state;
    casadi_inputs[1] = Sx_input;
    casadi_inputs[2] = Su_input;
    casadi_inputs[3] = control;
    casadi_outputs[0] = state_out;
    casadi_outputs[1] = Sx_output;
    casadi_outputs[2] = Su_output;
    int* integer_work = 0;
    double* float_work = 0;
    int memory_id = 0;
    vde_solver(casadi_inputs, casadi_outputs, integer_work, float_work, memory_id);
}

