namespace {

class XCOFFSymbolicReader : public ObjDumper {
public:
  XCOFFSymbolicReader(const XCOFFObjectFile &binaryImage, ScopedPrinter &printer)
      : ObjDumper(printer), Image(binaryImage) {}

  void displayFileProperties() override;
  void displaySectionTable() override;
  void displayRelocationEntries() override;
  void displaySymbolTable() override;
  void displayDynamicSymbols() override;
  void displayUnwindData() override;
  void displayStackMapInfo() const override;
  void displayRequiredLibraries() override;

private:
  const XCOFFObjectFile &Image;
};

} // end anonymous namespace

void XCOFFSymbolicReader::displayFileProperties() {
  DictScope root(W, "FileHeader");

  uint16_t magicVal = Image.getMagic();
  W.printHex("MagicNumber", magicVal);

  uint16_t secCount = Image.getNumberOfSections();
  W.printNumber("SectionCount", secCount);

  int32_t timestampRaw = Image.getTimeStamp();

  if (timestampRaw > 0) {
    time_t hostTime = static_cast<time_t>(timestampRaw);
    char formatted[24] = {};
    size_t written = strftime(formatted, sizeof(formatted),
                              "%Y-%m-%dT%H:%M:%SZ", gmtime(&hostTime));
    if (written != 0 && formatted[0] != '\0')
      W.printHex("Timestamp", formatted, timestampRaw);
    else
      W.printHex("TimestampValue", timestampRaw);
  } else {
    StringRef desc = (timestampRaw == 0) ? "NoTimestamp" : "FutureReserved";
    W.printHex("Timestamp", desc, timestampRaw);
  }

  uint32_t symTabOffset = Image.getSymbolTableOffset();
  W.printHex("SymbolTableFileOffset", symTabOffset);

  int32_t symTabEntryCount = Image.getRawNumberOfSymbolTableEntries();
  if (symTabEntryCount >= 0) {
    W.printNumber("SymbolTableEntryCount", symTabEntryCount);
  } else {
    W.printHex("SymbolTableEntryCount", "ReservedField", symTabEntryCount);
  }

  uint16_t optHeaderSize = Image.getOptionalHeaderSize();
  W.printHex("OptionalHeaderByteSize", optHeaderSize);

  uint16_t flags = Image.getFlags();
  W.printHex("FlagBits", flags);

  // TODO: Support auxiliary headers once XCOFFObjectFile provides accessors.
}

void XCOFFSymbolicReader::displaySectionTable() {
  llvm_unreachable("Section table dumping not yet implemented for XCOFF");
