// Configuration constants for cellular automaton simulation
static float survivalChance = 0.45f;
static int deathThreshold = 3;
static int birthThreshold = 4;
static unsigned mapWidth = 80u;
static unsigned mapHeight = 80u;
static unsigned stepsToRun = 17u;
static unsigned pixelScale = 1u;
static char const * outputPath = "/path/to/user/Projects/AutomataDungeone/buffer/dungeone.png";
static unsigned winX = 0u;
static unsigned winY = 0u;
static unsigned winW = 640u;
static unsigned winH = 480u;

int main() {
    // Initialize the cellular automaton grid
    CellAutomat dungeonMap(survivalChance, deathThreshold, birthThreshold, mapWidth, mapHeight);

    // Execute simulation steps
    dungeonMap.runSimulation();
    dungeonMap.update(stepsToRun);

    // Generate PNG image from final state
    Png outputImage(dungeonMap.synthesis(), outputPath, pixelScale, stounPalette, cavePalette);
    outputImage.genPng();

    // Set up graphical window and event handling
    Graphics display(outputPath, winX, winY, winW, winH);
    SDL_Event currentEvent;

    // Main loop: keep rendering until window close requested
    bool running = true;
    while (running) {
        while (SDL_PollEvent(&currentEvent)) {
            if (currentEvent.type == SDL_QUIT) {
                running = false;
            }
        }
        display.draw();
    }

    return 0;
}

