// Helper to wrap optional-like behavior explicitly
template<typename T>
struct OptionalResult {
    bool has_value = false;
    T value{};

    explicit operator bool() const { return has_value; }
};

class Swapchain_image {
public:
    Swapchain_image(Swapchain* swapchain, uint32_t index)
        : m_swapchain{swapchain}
        , m_image_index{index}
    {}

    ~Swapchain_image() {
        if (m_swapchain) {
            m_swapchain->release();
        }
    }

    Swapchain_image(const Swapchain_image&) = delete;
    Swapchain_image& operator=(const Swapchain_image&) = delete;

    Swapchain_image(Swapchain_image&& other) noexcept
        : m_swapchain{other.m_swapchain}
        , m_image_index{other.m_image_index}
    {
        other.m_swapchain = nullptr;
    }

    Swapchain_image& operator=(Swapchain_image&& other) noexcept {
        if (this != &other) {
            m_swapchain = other.m_swapchain;
            m_image_index = other.m_image_index;
            other.m_swapchain = nullptr;
        }
        return *this;
    }

    [[nodiscard]] auto get_image_index() const -> uint32_t {
        ERHE_VERIFY(m_swapchain != nullptr);
        return m_image_index;
    }

    [[nodiscard]] auto get_gl_texture() const -> uint32_t {
        ERHE_VERIFY(m_swapchain != nullptr);
        return m_swapchain->get_gl_texture(m_image_index);
    }

private:
    Swapchain* m_swapchain{nullptr};
    uint32_t m_image_index{0};
};

class Swapchain {
public:
    explicit Swapchain(XrSwapchain handle)
        : m_xr_swapchain{handle}
    {
        ERHE_PROFILE_FUNCTION;
        Expects(handle != XR_NULL_HANDLE);
        enumerate_images();
    }

    ~Swapchain() {
        ERHE_PROFILE_FUNCTION;
        if (m_xr_swapchain != XR_NULL_HANDLE) {
            check_gl_context_in_current_in_this_thread();
            check(xrDestroySwapchain(m_xr_swapchain));
        }
    }

    Swapchain(const Swapchain&) = delete;
    Swapchain& operator=(const Swapchain&) = delete;

    Swapchain(Swapchain&& other) noexcept
        : m_xr_swapchain{other.m_xr_swapchain}
        , m_gl_textures{std::move(other.m_gl_textures)}
    {
        other.m_xr_swapchain = XR_NULL_HANDLE;
    }

    Swapchain& operator=(Swapchain&& other) noexcept {
        if (this != &other) {
            if (m_xr_swapchain != XR_NULL_HANDLE) {
                check_gl_context_in_current_in_this_thread();
                check(xrDestroySwapchain(m_xr_swapchain));
            }
            m_xr_swapchain = other.m_xr_swapchain;
            m_gl_textures = std::move(other.m_gl_textures);
            other.m_xr_swapchain = XR_NULL_HANDLE;
        }
        return *this;
    }

    [[nodiscard]] auto acquire() -> OptionalResult<Swapchain_image> {
        ERHE_PROFILE_FUNCTION;
        if (m_xr_swapchain == XR_NULL_HANDLE) {
            return {};
        }

        const XrSwapchainImageAcquireInfo acquire_info{
            .type = XR_TYPE_SWAPCHAIN_IMAGE_ACQUIRE_INFO,
            .next = nullptr
        };

        uint32_t img_idx = 0;
        check_gl_context_in_current_in_this_thread();

        if (!check(xrAcquireSwapchainImage(
                m_xr_swapchain,
                &acquire_info,
                &img_idx
            ))
        ) {
            return {};
        }

        ERHE_ASSERT(img_idx < 16u);
        return OptionalResult<Swapchain_image>{true, Swapchain_image{this, img_idx}};
    }

    [[nodiscard]] auto release() -> bool {
        ERHE_PROFILE_FUNCTION;
        if (m_xr_swapchain == XR_NULL_HANDLE) {
            return true;
        }

        const XrSwapchainImageReleaseInfo release_info{
            .type = XR_TYPE_SWAPCHAIN_IMAGE_RELEASE_INFO,
            .next = nullptr
        };

        check_gl_context_in_current_in_this_thread();
        return check(xrReleaseSwapchainImage(m_xr_swapchain, &release_info));
    }

    [[nodiscard]] auto wait() -> bool {
        ERHE_PROFILE_FUNCTION;
        if (m_xr_swapchain == XR_NULL_HANDLE) {
            return false;
        }

        const XrSwapchainImageWaitInfo wait_info{
            .type    = XR_TYPE_SWAPCHAIN_IMAGE_WAIT_INFO,
            .next    = nullptr,
            .timeout = XR_INFINITE_DURATION
        };

        check_gl_context_in_current_in_this_thread();
        return check(xrWaitSwapchainImage(m_xr_swapchain, &wait_info));
    }

    [[nodiscard]] auto get_gl_texture(uint32_t idx) const -> unsigned int {
        ERHE_VERIFY(idx < m_gl_textures.size());
        return m_gl_textures[idx];
    }

    [[nodiscard]] auto get_xr_swapchain() const -> XrSwapchain {
        return m_xr_swapchain;
    }

private:
    auto enumerate_images() -> bool {
        ERHE_PROFILE_FUNCTION;
        if (m_xr_swapchain == XR_NULL_HANDLE) {
            return false;
        }

        uint32_t count{0};
        check_gl_context_in_current_in_this_thread();
        ERHE_XR_CHECK(xrEnumerateSwapchainImages(m_xr_swapchain, 0, &count, nullptr));

        m_gl_textures.resize(count);

        std::vector<XrSwapchainImageOpenGLKHR> images(count);
        std::generate(images.begin(), images.end(), []() {
            return XrSwapchainImageOpenGLKHR{
                .type = XR_TYPE_SWAPCHAIN_IMAGE_OPENGL_KHR,
                .next = nullptr,
                .image = 0
            };
        });

        check_gl_context_in_current_in_this_thread();
        ERHE_XR_CHECK(
            xrEnumerateSwapchainImages(
                m_xr_swapchain,
                count,
                &count,
                reinterpret_cast<XrSwapchainImageBaseHeader*>(images.data())
            )
        );

        std::transform(images.begin(), images.end(), m_gl_textures.begin(),
                       [](const auto& img) { return img.image; });

        return true;
    }

    XrSwapchain m_xr_swapchain{XR_NULL_HANDLE};
    std::vector<unsigned int> m_gl_textures{};
};

