// Static member definitions with modified naming
template <uint16_t k> constexpr size_t CdBG<k>::ASYNC_LOG_QUEUE_SZ;
template <uint16_t k> constexpr uint16_t CdBG<k>::ASYNC_LOG_N_THREADS;
template <uint16_t k> const std::string CdBG<k>::GFA1_HEADER = "H\tVN:Z:1.0";
template <uint16_t k> const std::string CdBG<k>::GFA2_HEADER = "H\tVN:Z:2.0";

// Renamed function with altered control flow for temp file prefix generation
template <uint16_t k>
void CdBG<k>::set_temp_file_prefixes(const std::string& working_dir)
{
    // Attempt to generate unique temporary file identifiers
    const uint64_t MAX_ATTEMPTS = 10;
    std::string random_prefix;

    bool found_unique = false;
    for(uint64_t trial = 0; trial < MAX_ATTEMPTS && !found_unique; ++trial)
    {
        random_prefix = get_random_string(TEMP_FILE_PREFIX_LEN);
        if(!file_prefix_exists(working_dir, random_prefix))
        {
            path_file_prefix = working_dir + "/" + path_file_prefix + random_prefix;
            overlap_file_prefix = working_dir + "/" + overlap_file_prefix + random_prefix;
            std::cout << "Temporary path file name prefixes: " << path_file_prefix << "\n";
            found_unique = true;
        }
    }

    if(!found_unique)
    {
        std::cerr << "Failed to find any random prefix for temporary file names. Aborting.\n";
        std::exit(EXIT_FAILURE);
    }
}

// Modified reset_path_loggers with different initialization approach
template <uint16_t k>
void CdBG<k>::reset_path_loggers(const uint64_t file_id)
{
    const cuttlefish::Output_Format gfa_version = params.output_format();
    const uint16_t num_threads = params.thread_count();

    // Clear existing output structures
    path_output_.clear();
    if(gfa_version == cuttlefish::Output_Format::gfa1)
        overlap_output_.clear();

    // Resize containers based on thread count
    path_output_.resize(num_threads);
    if(gfa_version == cuttlefish::Output_Format::gfa1)
        overlap_output_.resize(num_threads);

    // Create shared thread pool for async logging
    tp_path = std::make_shared<spdlog::details::thread_pool>(ASYNC_LOG_QUEUE_SZ, ASYNC_LOG_N_THREADS);

    for(uint16_t t_idx = 0; t_idx < num_threads; ++t_idx)
    {
        const std::string path_filename = construct_path_filename(t_idx, file_id);

        // Initialize output file by truncating it
        std::ofstream init_file(path_filename.c_str(), std::ofstream::out | std::ofstream::trunc);
        init_file.close();

        // Configure async logger for paths
        std::string logger_tag("async_path_logger_");
        logger_tag += std::to_string(t_idx);

        auto path_sink = std::make_shared<spdlog::sinks::basic_file_sink_mt>(path_filename);
        path_output_[t_idx] = std::make_shared<spdlog::async_logger>(
            logger_tag, path_sink, tp_path, spdlog::async_overflow_policy::block);
        path_output_[t_idx]->set_pattern("%v");

        // Handle overlap logger for GFA1 format
        if(gfa_version == cuttlefish::Output_Format::gfa1)
        {
            const std::string overlap_filename = overlap_file_prefix + std::to_string(t_idx);

            // Initialize overlap output file
            std::ofstream init_overlap(overlap_filename.c_str(), std::ofstream::out | std::ofstream::trunc);
            init_overlap.close();

            // Configure async logger for overlaps
            std::string overlap_logger_tag("async_overlap_logger_");
            overlap_logger_tag += std::to_string(t_idx);

            auto overlap_sink = std::make_shared<spdlog::sinks::basic_file_sink_mt>(overlap_filename);
            overlap_output_[t_idx] = std::make_shared<spdlog::async_logger>(
                overlap_logger_tag, overlap_sink, tp_path, spdlog::async_overflow_policy::block);
            overlap_output_[t_idx]->set_pattern("%v");
        }
    }
}

// Renamed helper function for constructing path filenames
template <uint16_t k>
std::string CdBG<k>::construct_path_filename(const uint16_t thread_id, const uint64_t file_id) const
{
    return path_file_prefix + std::to_string(thread_id) +
           (file_id ? ("_" + std::to_string(file_id)) : "");
}

// Modified buffer allocation with different initialization pattern
template <uint16_t k>
void CdBG<k>::allocate_path_buffers()
{
    const uint16_t num_threads = params.thread_count();
    const cuttlefish::Output_Format gfa_version = params.output_format();

    path_buffer.resize(num_threads);
    if(gfa_version == cuttlefish::Output_Format::gfa1)
        overlap_buffer.resize(num_threads);

    // Reserve capacity for each thread's buffer
    for(uint16_t t_idx = 0; t_idx < num_threads; ++t_idx)
    {
        path_buffer[t_idx].reserve(BUFFER_CAPACITY);
        if(gfa_version == cuttlefish::Output_Format::gfa1)
            overlap_buffer[t_idx].reserve(BUFFER_CAPACITY);
    }
}

// Reset extreme unitigs with different initialization approach
template <uint16_t k>
void CdBG<k>::reset_extreme_unitigs()
{
    const uint16_t num_threads = params.thread_count();

    first_unitig.resize(num_threads);
    second_unitig.resize(num_threads);
    last_unitig.resize(num_threads);

    // Initialize all unitigs to invalid state
    std::fill(first_unitig.begin(), first_unitig.end(), Oriented_Unitig());
    std::fill(second_unitig.begin(), second_unitig.end(), Oriented_Unitig());
    std::fill(last_unitig.begin(), last_unitig.end(), Oriented_Unitig());
}

// Modified substring processing with restructured loop logic
template <uint16_t k>
void CdBG<k>::output_gfa_off_substring(const uint16_t thread_id, const char* const seq, const size_t seq_len, const size_t left_end, const size_t right_end)
{
    size_t current_kmer_pos = left_end;
    while(current_kmer_pos <= right_end)
    {
        current_kmer_pos = search_valid_kmer(seq, current_kmer_pos, right_end);
        if(current_kmer_pos > right_end)
            break;

        current_kmer_pos = output_maximal_unitigs_gfa(thread_id, seq, seq_len, right_end, current_kmer_pos);
    }
}

// Refactored maximal unitig output with changed iteration strategy
template <uint16_t k>
size_t CdBG<k>::output_maximal_unitigs_gfa(const uint16_t thread_id, const char* const seq, const size_t seq_len, const size_t right_end, const size_t start_idx)
{
    size_t kmer_pos = start_idx;
    Annotated_Kmer<k> current_kmer(Kmer<k>(seq, kmer_pos), kmer_pos, Vertices);

    // Check for isolated k-mer case
    if((kmer_pos == 0 || Kmer<k>::is_placeholder(seq[kmer_pos - 1])) &&
       (kmer_pos + k == seq_len || Kmer<k>::is_placeholder(seq[kmer_pos + k])))
    {
        output_gfa_unitig(thread_id, seq, current_kmer, current_kmer);
        return kmer_pos + k;
    }

    // Handle cases where only one neighbor exists
    if(kmer_pos + k == seq_len || Kmer<k>::is_placeholder(seq[kmer_pos + k]))
    {
        Annotated_Kmer<k> prev_kmer(Kmer<k>(seq, kmer_pos - 1), kmer_pos, Vertices);
        if(is_unipath_start(current_kmer.state_class(), current_kmer.dir(), prev_kmer.state_class(), prev_kmer.dir()))
            output_gfa_unitig(thread_id, seq, current_kmer, current_kmer);
        return kmer_pos + k;
    }

    // Process sequences with valid neighbors on both sides
    Annotated_Kmer<k> next_kmer = current_kmer;
    next_kmer.roll_to_next_kmer(seq[kmer_pos + k], Vertices);

    bool on_unipath = false;
    Annotated_Kmer<k> unipath_start;
    Annotated_Kmer<k> prev_kmer;

    if(kmer_pos == 0 || Kmer<k>::is_placeholder(seq[kmer_pos - 1]))
    {
        on_unipath = true;
        unipath_start = current_kmer;
    }
    else
    {
        prev_kmer = Annotated_Kmer<k>(Kmer<k>(seq, kmer_pos - 1), kmer_pos, Vertices);
        if(is_unipath_start(current_kmer.state_class(), current_kmer.dir(), prev_kmer.state_class(), prev_kmer.dir()))
        {
            on_unipath = true;
            unipath_start = current_kmer;
        }
    }

    if(on_unipath && is_unipath_end(current_kmer.state_class(), current_kmer.dir(), next_kmer.state_class(), next_kmer.dir()))
    {
        output_gfa_unitig(thread_id, seq, unipath_start, current_kmer);
        on_unipath = false;
    }

    // Main processing loop for remaining k-mers
    for(kmer_pos++; on_unipath || kmer_pos <= right_end; ++kmer_pos)
    {
        prev_kmer = current_kmer;
        current_kmer = next_kmer;

        if(is_unipath_start(current_kmer.state_class(), current_kmer.dir(), prev_kmer.state_class(), prev_kmer.dir()))
        {
            on_unipath = true;
            unipath_start = current_kmer;
        }

        if(kmer_pos + k == seq_len || Kmer<k>::is_placeholder(seq[kmer_pos + k]))
        {
            if(on_unipath)
            {
                output_gfa_unitig(thread_id, seq, unipath_start, current_kmer);
                on_unipath = false;
            }
            return kmer_pos + k;
        }
        else
        {
            next_kmer.roll_to_next_kmer(seq[kmer_pos + k], Vertices);
            if(on_unipath && is_unipath_end(current_kmer.state_class(), current_kmer.dir(), next_kmer.state_class(), next_kmer.dir()))
            {
                output_gfa_unitig(thread_id, seq, unipath_start, current_kmer);
                on_unipath = false;
            }
        }
    }

    return kmer_pos + k;
}

// Modified unitig output with changed canonical form handling
template <uint16_t k>
void CdBG<k>::output_gfa_unitig(const uint16_t thread_id, const char* const seq, const Annotated_Kmer<k>& start_kmer, const Annotated_Kmer<k>& end_kmer)
{
    // Determine canonical representation to avoid race conditions
    const Kmer<k> min_flanking = std::min(start_kmer.canonical(), end_kmer.canonical());
    const uint64_t bucket_id = Vertices.bucket_id(min_flanking);
    Kmer_Hash_Entry_API hash_entry = Vertices[bucket_id];
    State& state = hash_entry.get_state();

    // Generate unitig identifier
    const uint64_t unitig_id = bucket_id;
    const cuttlefish::dir_t unitig_direction = (start_kmer.kmer() < end_kmer.rev_compl() ? cuttlefish::FWD : cuttlefish::BWD);
    const Oriented_Unitig current_unitig(unitig_id, unitig_direction, start_kmer.idx(), end_kmer.idx());

    // Output segment if not already processed
    if(!state.is_outputted())
    {
        state = state.outputted();
        if(Vertices.update(hash_entry))
        {
            if(params.output_format() == cuttlefish::Output_Format::gfa_reduced)
                write_segment(thread_id, seq, unitig_id, start_kmer.idx(), end_kmer.idx(), unitig_direction);
            else
                write_gfa_segment(thread_id, seq, unitig_id, start_kmer.idx(), end_kmer.idx(), unitig_direction);
        }
    }

    // Manage connections between unitigs
    if(!first_unitig[thread_id].is_valid())
        first_unitig[thread_id] = current_unitig;
    else if(!second_unitig[thread_id].is_valid())
        second_unitig[thread_id] = current_unitig;

    Oriented_Unitig& previous_unitig = last_unitig[thread_id];
    if(previous_unitig.is_valid())
        write_gfa_connection(thread_id, previous_unitig, current_unitig);

    previous_unitig = current_unitig;
}

// Header writing with simplified logic
template <uint16_t k>
void CdBG<k>::write_gfa_header() const
{
    const std::string& output_path = params.output_file_path();
    const cuttlefish::Output_Format gfa_version = params.output_format();

    std::ofstream out(output_path.c_str(), std::ofstream::out);
    out << (gfa_version == cuttlefish::Output_Format::gfa1 ? GFA1_HEADER : GFA2_HEADER) << "\n";
    out.close();
}

// Modified segment writing with different formatting approach
template <uint16_t k>
void CdBG<k>::write_gfa_segment(const uint16_t thread_id, const char* const seq, const uint64_t segment_name, const size_t start_kmer_idx, const size_t end_kmer_idx, const cuttlefish::dir_t dir)
{
    std::chrono::high_resolution_clock::time_point start_time = std::chrono::high_resolution_clock::now();
    const cuttlefish::Output_Format gfa_version = params.output_format();
    std::string& buffer = output_buffer[thread_id];
    const size_t segment_length = end_kmer_idx - start_kmer_idx + k;

    ensure_buffer_space(buffer, segment_length + 49, output_[thread_id]);

    // Add record type
    buffer += "S";

    // Add name field
    buffer += "\t" + fmt::format_int(segment_name).c_str();

    // Add length field for GFA2
    if(gfa_version == cuttlefish::Output_Format::gfa2)
        buffer += "\t" + fmt::format_int(segment_length).c_str();

    // Add sequence data
    buffer += "\t";
    if(dir == cuttlefish::FWD)
        for(size_t offset = 0; offset < segment_length; ++offset)
            buffer += Kmer<k>::upper(seq[start_kmer_idx + offset]);
    else
        for(size_t offset = 0; offset < segment_length; ++offset)
            buffer += Kmer<k>::complement(seq[end_kmer_idx + k - 1 - offset]);

    // Add optional fields for GFA1
    if(gfa_version == cuttlefish::Output_Format::gfa1)
        buffer += "\tLN:i:" + fmt::format_int(segment_length).c_str();

    buffer += "\n";

    // Track timing
    std::chrono::high_resolution_clock::time_point end_time = std::chrono::high_resolution_clock::now();
    double elapsed = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    seg_write_time[thread_id] += elapsed;

    check_output_buffer(thread_id);
}

// Modified connection writing with different routing logic
template <uint16_t k>
void CdBG<k>::write_gfa_connection(const uint16_t thread_id, const Oriented_Unitig& left_unitig, const Oriented_Unitig& right_unitig)
{
    const uint8_t gfa_version = params.output_format();
    if(gfa_version == cuttlefish::Output_Format::gfa1)
        write_gfa_link(thread_id, left_unitig, right_unitig);
    else if(gfa_version == cuttlefish::Output_Format::gfa2)
    {
        if(right_unitig.start_kmer_idx == left_unitig.end_kmer_idx + 1)
            write_gfa_edge(thread_id, left_unitig, right_unitig);
        else
            write_gfa_gap(thread_id, left_unitig, right_unitig);
    }
    else
        append_edge_to_path(thread_id, left_unitig, right_unitig);
}

// Modified link writing with different overlap calculation
template <uint16_t k>
void CdBG<k>::write_gfa_link(const uint16_t thread_id, const Oriented_Unitig& left_unitig, const Oriented_Unitig& right_unitig)
{
    std::chrono::high_resolution_clock::time_point start_time = std::chrono::high_resolution_clock::now();
    std::string& buffer = output_buffer[thread_id];

    buffer += "L";
    buffer += "\t" + fmt::format_int(left_unitig.unitig_id).c_str();
    buffer += "\t" + (left_unitig.dir == cuttlefish::FWD ? "+" : "-");
    buffer += "\t" + fmt::format_int(right_unitig.unitig_id).c_str();
    buffer += "\t" + (right_unitig.dir == cuttlefish::FWD ? "+" : "-");

    // Calculate overlap
    const uint16_t overlap_size = (right_unitig.start_kmer_idx == left_unitig.end_kmer_idx + 1 ? k - 1 : 0);
    buffer += "\t" + fmt::format_int(overlap_size).c_str() + "M\n";

    std::chrono::high_resolution_clock::time_point end_time = std::chrono::high_resolution_clock::now();
    double elapsed = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    link_write_time[thread_id] += elapsed;

    check_output_buffer(thread_id);
    append_link_to_path(thread_id, left_unitig, right_unitig);
}

// Modified edge writing with different coordinate handling
template <uint16_t k>
void CdBG<k>::write_gfa_edge(const uint16_t thread_id, const Oriented_Unitig& left_unitig, const Oriented_Unitig& right_unitig)
{
    std::string& buffer = output_buffer[thread_id];

    buffer += "E";
    buffer += "\t*";  // Edge-ID

    // Segment references
    buffer += "\t" + fmt::format_int(left_unitig.unitig_id).c_str();
    buffer += (left_unitig.dir == cuttlefish::FWD ? "+" : "-");
    buffer += "\t" + fmt::format_int(right_unitig.unitig_id).c_str();
    buffer += (right_unitig.dir == cuttlefish::FWD ? "+" : "-");

    // First segment coordinates
    size_t unitig_len = left_unitig.length(k);
    if(left_unitig.dir == cuttlefish::FWD)
    {
        buffer += "\t" + fmt::format_int(unitig_len - (k - 1)).c_str();
        buffer += "\t" + fmt::format_int(unitig_len).c_str() + "$";
    }
    else
    {
        buffer += "\t0";
        buffer += "\t" + fmt::format_int(k - 1).c_str();
    }

    // Second segment coordinates
    unitig_len = right_unitig.length(k);
    if(right_unitig.dir == cuttlefish::FWD)
    {
        buffer += "\t0";
        buffer += "\t" + fmt::format_int(k - 1).c_str();
    }
    else
    {
        buffer += "\t" + fmt::format_int(unitig_len - (k - 1)).c_str();
        buffer += "\t" + fmt::format_int(unitig_len).c_str() + "$";
    }

    buffer += "\t*";  // Alignment field
    buffer += "\n";

    check_output_buffer(thread_id);
    append_edge_to_path(thread_id, left_unitig, right_unitig);
}

// Modified gap writing with different distance calculation
template <uint16_t k>
void CdBG<k>::write_gfa_gap(const uint16_t thread_id, const Oriented_Unitig& left_unitig, const Oriented_Unitig& right_unitig)
{
    std::string& buffer = output_buffer[thread_id];

    buffer += "G";
    buffer += "\t*";  // Gap-ID

    // Segment references
    buffer += "\t" + fmt::format_int(left_unitig.unitig_id).c_str();
    buffer += (left_unitig.dir == cuttlefish::FWD ? "+" : "-");
    buffer += "\t" + fmt::format_int(right_unitig.unitig_id).c_str();
    buffer += (right_unitig.dir == cuttlefish::FWD ? "+" : "-");

    // Distance calculation
    int gap_distance = right_unitig.start_kmer_idx - (left_unitig.end_kmer_idx + k);
    buffer += "\t" + fmt::format_int(gap_distance).c_str();
    buffer += "\t*";  // Variance field

    buffer += "\n";

    check_output_buffer(thread_id);
    append_edge_to_path(thread_id, left_unitig, right_unitig);
}

// Modified path appending with different buffer management
template <uint16_t k>
void CdBG<k>::append_link_to_path(const uint16_t thread_id, const Oriented_Unitig& left_unitig, const Oriented_Unitig& right_unitig)
{
    std::chrono::high_resolution_clock::time_point start_time = std::chrono::high_resolution_clock::now();

    std::string& p_buffer = path_buffer[thread_id];
    p_buffer += ",";
    p_buffer += fmt::format_int(right_unitig.unitig_id).c_str();
    p_buffer += (right_unitig.dir == cuttlefish::FWD ? "+" : "-");

    std::string& o_buffer = overlap_buffer[thread_id];
    o_buffer += ",";
    o_buffer += fmt::format_int(right_unitig.start_kmer_idx == left_unitig.end_kmer_idx + 1 ? k - 1 : 0).c_str();
    o_buffer += "M";

    std::chrono::high_resolution_clock::time_point end_time = std::chrono::high_resolution_clock::now();
    double elapsed = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    path_write_time[thread_id] += elapsed;

    check_path_buffer(thread_id);
}

// Modified edge appending with simplified logic
template <uint16_t k>
void CdBG<k>::append_edge_to_path(const uint16_t thread_id, const Oriented_Unitig& left_unitig, const Oriented_Unitig& right_unitig)
{
    (void)left_unitig;  // Suppress unused parameter warning

    std::string& buffer = path_buffer[thread_id];
    buffer += " ";
    buffer += fmt::format_int(right_unitig.unitig_id).c_str();
    buffer += (right_unitig.dir == cuttlefish::FWD ? "+" : "-");

    check_path_buffer(thread_id);
}

// Modified buffer checking with different threshold handling
template <uint16_t k>
void CdBG<k>::check_path_buffer(const uint16_t thread_id)
{
    std::chrono::high_resolution_clock::time_point start_time = std::chrono::high_resolution_clock::now();

    if(path_buffer[thread_id].size() >= BUFFER_THRESHOLD)
        flush_buffer(path_buffer[thread_id], path_output_[thread_id]);

    const cuttlefish::Output_Format gfa_version = params.output_format();
    if(gfa_version == cuttlefish::Output_Format::gfa1 && overlap_buffer[thread_id].size() >= BUFFER_THRESHOLD)
        flush_buffer(overlap_buffer[thread_id], overlap_output_[thread_id]);

    std::chrono::high_resolution_clock::time_point end_time = std::chrono::high_resolution_clock::now();
    double elapsed = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    path_flush_time[thread_id] += elapsed;
}

// Modified inter-thread connection writing with different traversal order
template <uint16_t k>
void CdBG<k>::write_inter_thread_connections()
{
    const uint16_t thread_count = params.thread_count();
    Oriented_Unitig left_unitig;
    uint16_t left_thread_id;

    // Find first valid unitig across threads
    for(uint16_t t_id = 0; t_id < thread_count; ++t_id)
    {
        if(!left_unitig.is_valid())
        {
            left_unitig = last_unitig[t_id];
            left_thread_id = t_id;
        }
        else if(first_unitig[t_id].is_valid())
        {
            const Oriented_Unitig& right_unitig = first_unitig[t_id];
            write_gfa_connection(left_thread_id, left_unitig, right_unitig);
            left_unitig = last_unitig[t_id];
            left_thread_id = t_id;
        }
    }
}

// Modified first connection search with different termination condition
template <uint16_t k>
void CdBG<k>::search_first_connection(Oriented_Unitig& left_unitig, Oriented_Unitig& right_unitig) const
{
    const uint16_t thread_count = params.thread_count();
    left_unitig = Oriented_Unitig();
    right_unitig = Oriented_Unitig();

    for(uint16_t t_id = 0; t_id < thread_count; ++t_id)
    {
        if(first_unitig[t_id].is_valid())
        {
            if(!left_unitig.is_valid())
                left_unitig = first_unitig[t_id];
            else
            {
                right_unitig = first_unitig[t_id];
                return;
            }
        }
        if(second_unitig[t_id].is_valid())
        {
            right_unitig = second_unitig[t_id];
            return;
        }
    }
}

// Modified path buffer flushing with different cleanup approach
template <uint16_t k>
void CdBG<k>::flush_path_buffers()
{
    const uint16_t thread_count = params.thread_count();
    const cuttlefish::Output_Format gfa_version = params.output_format();

    for(uint16_t t_id = 0; t_id < thread_count; ++t_id)
    {
        std::chrono::high_resolution_clock::time_point start_time = std::chrono::high_resolution_clock::now();

        if(!path_buffer[t_id].empty())
            flush_buffer(path_buffer[t_id], path_output_[t_id]);

        if(gfa_version == cuttlefish::Output_Format::gfa1 && !overlap_buffer[t_id].empty())
            flush_buffer(overlap_buffer[t_id], overlap_output_[t_id]);

        std::chrono::high_resolution_clock::time_point end_time = std::chrono::high_resolution_clock::now();
        double elapsed = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
        path_flush_time[t_id] += elapsed;
    }
}

// Modified GFA path writing with different file handling
template <uint16_t k>
void CdBG<k>::write_gfa_path(const std::string& path_name)
{
    std::chrono::high_resolution_clock::time_point start_time = std::chrono::high_resolution_clock::now();
    const uint16_t thread_count = params.thread_count();
    const std::string& output_path = params.output_file_path();

    // Find first connection in sequence
    Oriented_Unitig left_unitig;
    Oriented_Unitig right_unitig;
    search_first_connection(left_unitig, right_unitig);

    if(!left_unitig.is_valid())
        return;

    // Open output file in append mode
    std::ofstream output(output_path.c_str(), std::ios_base::app);

    // Write path header
    output << "P";
    output << "\t" << path_name;
    output << "\t";

    // Write first vertex
    output << left_unitig.unitig_id << (left_unitig.dir == cuttlefish::FWD ? "+" : "-");

    // Append thread-specific path outputs
    for(uint16_t t_id = 0; t_id < thread_count; ++t_id)
    {
        const std::string path_filename = (path_file_prefix + std::to_string(t_id));
        std::ifstream input(path_filename.c_str(), std::ios_base::in);

        if(input.fail())
        {
            std::cerr << "Error opening temporary path output file " << path_filename << ". Aborting.\n";
            std::exit(EXIT_FAILURE);
        }

        if(input.peek() != EOF)
            output << input.rdbuf();
        input.close();
    }

    // Write overlaps section
    output << "\t";
    if(!right_unitig.is_valid())
        output << "*";
    else
    {
        const uint16_t overlap_size = (right_unitig.start_kmer_idx == left_unitig.end_kmer_idx + 1 ? k - 1 : 0);
        output << overlap_size << "M";

        for(uint16_t t_id = 0; t_id < thread_count; ++t_id)
        {
            const std::string overlap_filename = (overlap_file_prefix + std::to_string(t_id));
            std::ifstream input(overlap_filename.c_str(), std::ifstream::in);

            if(input.fail())
            {
                std::cerr << "Error opening temporary overlap output file " << overlap_filename << ". Aborting.\n";
                std::exit(EXIT_FAILURE);
            }

            if(input.peek() != EOF)
                output << input.rdbuf();
            input.close();
        }
    }

    output << "\n";
    output.close();

    std::chrono::high_resolution_clock::time_point end_time = std::chrono::high_resolution_clock::now();
    double elapsed = std::chrono::duration_cast<std::chrono::duration<double>>(end_time - start_time).count();
    path_concat_time += elapsed;
}

