CD3DX12AffinityCommandList::CD3DX12AffinityCommandList(CD3DX12AffinityDevice* device, ID3D12CommandList** commandLists, UINT Count)
    : CD3DX12AffinityDeviceChild(device, reinterpret_cast<ID3D12DeviceChild**>(commandLists), Count)
{
    // Initialize all command list pointers to nullptr first
    for (UINT i = 0; i < D3DX12_MAX_ACTIVE_NODES; ++i)
    {
        mCommandLists[i] = nullptr;
    }

    // Assign only the valid command lists up to Count
    for (UINT j = 0; j < Count && j < D3DX12_MAX_ACTIVE_NODES; ++j)
    {
        mCommandLists[j] = commandLists[j];
    }

#ifdef DEBUG_OBJECT_NAME
    mObjectTypeName = L"CommandList";
#endif
}

D3D12_COMMAND_LIST_TYPE STDMETHODCALLTYPE CD3DX12AffinityCommandList::GetType(UINT AffinityIndex)
{
    return mCommandLists[AffinityIndex]->GetType();
}

BOOL STDMETHODCALLTYPE CD3DX12AffinityCommandList::AssertResourceState(
    CD3DX12AffinityResource* pResource,
    UINT Subresource,
    UINT State)
{
    UINT idx = GetActiveNodeIndex();
    ID3D12CommandList* pCmdList = mCommandLists[idx];
    ID3D12DebugCommandList* pDebugCmdList = nullptr;

    HRESULT result = pCmdList->QueryInterface(IID_PPV_ARGS(&pDebugCmdList));
    if (FAILED(result))
    {
        return FALSE;
    }

    BOOL success = pDebugCmdList->AssertResourceState(pResource->mResources[idx], Subresource, State);
    return success;
}

HRESULT STDMETHODCALLTYPE CD3DX12AffinityCommandList::SetFeatureMask(
    D3D12_DEBUG_FEATURE Mask)
{
    for (UINT nodeIdx = 0; nodeIdx < D3DX12_MAX_ACTIVE_NODES; ++nodeIdx)
    {
        if ((mAffinityMask & (1u << nodeIdx)) != 0)
        {
            ID3D12CommandList* pCmdList = mCommandLists[nodeIdx];
            ID3D12DebugCommandList* pDebugCmdList = nullptr;

            HRESULT hr = pCmdList->QueryInterface(IID_PPV_ARGS(&pDebugCmdList));
            if (FAILED(hr))
            {
                return hr;
            }

            hr = pDebugCmdList->SetFeatureMask(Mask);
            if (FAILED(hr))
            {
                return hr;
            }
        }
    }
    return S_OK;
}

ID3D12CommandList* CD3DX12AffinityCommandList::GetChildObject(UINT AffinityIndex)
{
    return mCommandLists[AffinityIndex];
}

bool CD3DX12AffinityCommandList::IsReady()
{
    return mPendingBroadcast == 0;
}

void CD3DX12AffinityCommandList::RegisterPendingBroadcast()
{
    std::lock_guard<std::mutex> guard(mMutexPendingBroadcast);
    ++mPendingBroadcast;
}

void CD3DX12AffinityCommandList::UnRegisterPendingBroadcast()
{
    std::lock_guard<std::mutex> guard(mMutexPendingBroadcast);
    --mPendingBroadcast;
}

