#include <vector>
#include <map>

class Solution {
public:
  int countElements(std::vector<int>& arr) {
    int result = 0;
    std::map<int, int> frequencyMap;

    // Count occurrences of each number
    for (int value : arr) {
      frequencyMap[value]++;
    }

    // Check for each element if its successor exists
    for (int value : arr) {
      if (frequencyMap.find(value + 1) != frequencyMap.end() && 
          frequencyMap[value + 1] > 0) {
        result++;
      }
    }

    return result;
  }
};

