// Test basic formatting functionality with various data types
TEST(Printf, Basic) {
  char buffer[1024];
  uptr written = internal_snprintf(buffer, sizeof(buffer),
      "a%db%zdc%ue%zuf%xh%zxq%pe%sr",
      (int)-1, (uptr)-2, // NOLINT
      (unsigned)-4, (uptr)5, // NOLINT
      (unsigned)10, (uptr)11, // NOLINT
      (void*)0x123, "_string_");

  EXPECT_EQ(written, strlen(buffer));

  std::string expected = "a-1b-2c4294967292e5fahbq0x";
  expected.append(SANITIZER_POINTER_FORMAT_LENGTH - 3, '0');
  expected += "123e_string_r";

  EXPECT_STREQ(expected.c_str(), buffer);
}

// Verify behavior when string output is truncated due to buffer size
TEST(Printf, OverflowStr) {
  char buffer[] = "123456789";
  uptr len = internal_snprintf(buffer, 4, "%s", "abcdef");  // NOLINT

  EXPECT_EQ(len, (uptr)6);
  EXPECT_STREQ("abc", buffer);
  EXPECT_EQ(buffer[3], '\0');
  EXPECT_EQ(buffer[4], '5');
  EXPECT_EQ(buffer[5], '6');
  EXPECT_EQ(buffer[6], '7');
  EXPECT_EQ(buffer[7], '8');
  EXPECT_EQ(buffer[8], '9');
  EXPECT_EQ(buffer[9], '\0');
}

// Check integer truncation behavior in snprintf
TEST(Printf, OverflowInt) {
  char buffer[] = "123456789";
  internal_snprintf(buffer, 4, "%d", -123456789);  // NOLINT

  EXPECT_STREQ("-12", buffer);
  EXPECT_EQ(buffer[3], '\0');
  EXPECT_EQ(buffer[4], '5');
  EXPECT_EQ(buffer[5], '6');
  EXPECT_EQ(buffer[6], '7');
  EXPECT_EQ(buffer[7], '8');
  EXPECT_EQ(buffer[8], '9');
  EXPECT_EQ(buffer[9], '\0');
}

// Verify unsigned integer overflow handling
TEST(Printf, OverflowUint) {
  char buffer[] = "123456789";
  uptr value;

  if (sizeof(value) == 4) {
    value = (uptr)0x12345678;
  } else {
    value = (uptr)0x123456789ULL;
  }

  internal_snprintf(buffer, 4, "a%zx", value);  // NOLINT
  EXPECT_STREQ("a12", buffer);
  EXPECT_EQ(buffer[3], '\0');
  EXPECT_EQ(buffer[4], '5');
  EXPECT_EQ(buffer[5], '6');
  EXPECT_EQ(buffer[6], '7');
  EXPECT_EQ(buffer[7], '8');
  EXPECT_EQ(buffer[8], '9');
  EXPECT_EQ(buffer[9], '\0');
}

// Test pointer format truncation
TEST(Printf, OverflowPtr) {
  char buffer[] = "123456789";
  void *ptr;

  if (sizeof(ptr) == 4) {
    ptr = (void*)0x1234567;
  } else {
    ptr = (void*)0x123456789ULL;
  }

  internal_snprintf(buffer, 4, "%p", ptr);  // NOLINT
  EXPECT_STREQ("0x0", buffer);
  EXPECT_EQ(buffer[3], '\0');
  EXPECT_EQ(buffer[4], '5');
  EXPECT_EQ(buffer[5], '6');
  EXPECT_EQ(buffer[6], '7');
  EXPECT_EQ(buffer[7], '8');
  EXPECT_EQ(buffer[8], '9');
  EXPECT_EQ(buffer[9], '\0');
}

