// Helper function to compare internal_snprintf with standard snprintf
template<typename T>
static void CompareWithStandard(const char *format, T first, T second) {
  char internal_buf[1024];
  uptr internal_len = internal_snprintf(internal_buf, sizeof(internal_buf), 
                                        format, first, second);

  char libc_buf[1024];
  snprintf(libc_buf, sizeof(libc_buf), format, first, second);

  EXPECT_EQ(internal_len, strlen(internal_buf));
  EXPECT_STREQ(libc_buf, internal_buf);
}

// Test boundary values for integers and pointers
TEST(Printf, MinMax) {
  CompareWithStandard<int>("%d-%d", INT_MIN, INT_MAX);  // NOLINT
  CompareWithStandard<unsigned>("%u-%u", 0, UINT_MAX);  // NOLINT
  CompareWithStandard<unsigned>("%x-%x", 0, UINT_MAX);  // NOLINT

#if !defined(_WIN32)
  CompareWithStandard<long>("%zd-%zd", LONG_MIN, LONG_MAX);  // NOLINT
  CompareWithStandard<unsigned long>("%zu-%zu", 0, ULONG_MAX);  // NOLINT
  CompareWithStandard<unsigned long>("%zx-%zx", 0, ULONG_MAX);  // NOLINT
#endif
}

// Test field width and padding behaviors
TEST(Printf, Padding) {
  CompareWithStandard<int>("%3d - %3d", 1, 0);
  CompareWithStandard<int>("%3d - %3d", -1, 123);
  CompareWithStandard<int>("%3d - %3d", -1, -123);
  CompareWithStandard<int>("%3d - %3d", 12, 1234);
  CompareWithStandard<int>("%3d - %3d", -12, -1234);
  CompareWithStandard<int>("%03d - %03d", 1, 0);
  CompareWithStandard<int>("%03d - %03d", -1, 123);
  CompareWithStandard<int>("%03d - %03d", -1, -123);
  CompareWithStandard<int>("%03d - %03d", 12, 1234);
  CompareWithStandard<int>("%03d - %03d", -12, -1234);
}

// Test precision and alignment in string formatting
TEST(Printf, Precision) {
  char buffer[1024];
  uptr length;

  length = internal_snprintf(buffer, sizeof(buffer), "%.*s", 3, "12345");
  EXPECT_EQ(3U, length);
  EXPECT_STREQ("123", buffer);

  length = internal_snprintf(buffer, sizeof(buffer), "%.*s", 6, "12345");
  EXPECT_EQ(5U, length);
  EXPECT_STREQ("12345", buffer);

  length = internal_snprintf(buffer, sizeof(buffer), "%-6s", "12345");
  EXPECT_EQ(6U, length);
  EXPECT_STREQ("12345 ", buffer);

  // Ensure width doesn't exceed buffer size even when requested
  length = internal_snprintf(buffer, 8, "%-10s", "12345");
  EXPECT_EQ(10U, length);  // Total required size should be reported
  EXPECT_STREQ("12345  ", buffer);
}

