// Benchmark configuration constants
constexpr fxl::StringView kBenchmarkBinary = "fuchsia-pkg://fuchsia.com/ledger_benchmarks#meta/fetch.cmx";
constexpr fxl::StringView kStorageRoot = "/data/benchmark/ledger/fetch";
constexpr fxl::StringView kNumEntriesOpt = "entry-count";
constexpr fxl::StringView kPayloadSizeOpt = "value-size";
constexpr fxl::StringView kChunkSizeOpt = "part-size";
constexpr size_t kIdentifierLength = 100u;
const std::string kUserDirSuffix = "/fetch-user";

void ShowHelp() {
  std::cout << "Usage: trace record "
            << kBenchmarkBinary
            << " --" << kNumEntriesOpt << "=<int>"
            << " --" << kPayloadSizeOpt << "=<int>"
            << " --" << kChunkSizeOpt << "=<int>" << GetSyncParamsUsage() << std::endl;
}

// Measures time to fetch lazy values from server using multiple partial or full reads.
// Required flags:
//   --entry-count=<int> number of entries to store and retrieve
//   --value-size=<int>  size in bytes of each stored value
//   --part-size=<int>   chunk size for FetchPartial; if zero, use full Fetch
//   --credentials-path=<file path> Firestore credentials file
class LazyFetchBenchmarker : public SyncWatcher {
 public:
  LazyFetchBenchmarker(async::Loop* runner,
                       std::unique_ptr<sys::ComponentContext> ctx,
                       size_t item_count,
                       size_t payload_bytes,
                       size_t chunk_bytes,
                       SyncParams cloud_opts);

  void Execute();

  // SyncWatcher implementation
  void SyncStateChanged(SyncState download, SyncState upload,
                        SyncStateChangedCallback callback) override;

 private:
  void SeedData();
  void AwaitWriterCompletion();
  void LaunchReaderInstance();
  void AwaitReaderCompletion();
  void IssueFetches(PageSnapshotPtr snap, size_t idx);
  void IssueChunkedFetch(PageSnapshotPtr snap, size_t idx, size_t offset);
  void Terminate();

  fit::closure ExitHandler();
  async::Loop* const event_loop_;
  rng::TestRandom entropy_source_;
  DataGenerator data_producer_;
  PageDataGenerator page_populator_;
  std::unique_ptr<sys::ComponentContext> system_context_;
  cloud_provider_firestore::CloudProviderFactory cloud_factory_;
  fidl::Binding<SyncWatcher> sync_watcher_binding_;
  const size_t total_items_;
  const size_t item_size_;
  const size_t chunk_size_;
  const cloud_provider_firestore::CloudProviderFactory::UserId user_id_;
  files::ScopedTempDir writer_storage_;
  files::ScopedTempDir reader_storage_;
  fuchsia::sys::ComponentControllerPtr writer_ctrl_;
  fuchsia::sys::ComponentControllerPtr reader_ctrl_;
  LedgerPtr writer_ledger_;
  LedgerPtr reader_ledger_;
  PageId active_page_id_;
  PagePtr writer_page_;
  PagePtr reader_page_;
  std::vector<std::vector<uint8_t>> entry_keys_;
  fit::function<void(SyncState, SyncState)> on_sync_change_;

  FXL_DISALLOW_COPY_AND_ASSIGN(LazyFetchBenchmarker);
};

LazyFetchBenchmarker::LazyFetchBenchmarker(async::Loop* runner,
                                           std::unique_ptr<sys::ComponentContext> ctx,
                                           size_t item_count,
                                           size_t payload_bytes,
                                           size_t chunk_bytes,
                                           SyncParams cloud_opts)
    : event_loop_(runner),
      entropy_source_(0),
      data_producer_(&entropy_source_),
      page_populator_(&entropy_source_),
      system_context_(std::move(ctx)),
      cloud_factory_(system_context_.get(), &entropy_source_,
                     std::move(cloud_opts.api_key),
                     std::move(cloud_opts.credentials)),
      sync_watcher_binding_(this),
      total_items_(item_count),
      item_size_(payload_bytes),
      chunk_size_(chunk_bytes),
      user_id_(cloud_provider_firestore::CloudProviderFactory::UserId::New()),
      writer_storage_(kStorageRoot),
      reader_storage_(kStorageRoot) {
  FXL_DCHECK(event_loop_);
  FXL_DCHECK(total_items_ > 0);
  FXL_DCHECK(item_size_ > 0);
  FXL_DCHECK(chunk_size_ <= item_size_);
  cloud_factory_.Initialize();
}

void LazyFetchBenchmarker::SyncStateChanged(SyncState download, SyncState upload,
                                            SyncStateChangedCallback callback) {
  if (on_sync_change_) {
    on_sync_change_(download, upload);
  }
  callback();
}

void LazyFetchBenchmarker::Execute() {
  std::string writer_path = writer_storage_.path() + kUserDirSuffix;
  bool created = files::CreateDirectory(writer_path);
  FXL_DCHECK(created);

  cloud_provider::CloudProviderPtr writer_cloud;
  cloud_factory_.MakeCloudProvider(user_id_, writer_cloud.NewRequest());

  Status status = GetLedger(system_context_.get(), writer_ctrl_.NewRequest(),
                            std::move(writer_cloud), user_id_.user_id(), "lazy_fetch",
                            DetachedPath(std::move(writer_path)), ExitHandler(),
                            &writer_ledger_, kDefaultGarbageCollectionPolicy);
  if (QuitOnError(ExitHandler(), status, "Failed to initialize writer ledger")) {
    return;
  }

  GetPageEnsureInitialized(
      &writer_ledger_, nullptr, DelayCallback::YES, ExitHandler(),
      [this](Status status, PagePtr page, PageId id) {
        if (QuitOnError(ExitHandler(), status, "Writer page init failed")) {
          return;
        }
        writer_page_ = std::move(page);
        active_page_id_ = std::move(id);
        SeedData();
      });
}

void LazyFetchBenchmarker::SeedData() {
  auto keys = data_producer_.GenerateKeys(total_items_, kIdentifierLength, total_items_);
  for (size_t i = 0; i < total_items_; ++i) {
    entry_keys_.push_back(std::move(keys[i]));
  }

  page_populator_.Populate(
      &writer_page_, std::move(keys), item_size_, total_items_,
      PageDataGenerator::ReferenceStrategy::REFERENCE, Priority::LAZY,
      [this](Status status) {
        if (QuitOnError(ExitHandler(), status, "Data seeding failed")) {
          return;
        }
        AwaitWriterCompletion();
      });
}

void LazyFetchBenchmarker::AwaitWriterCompletion() {
  on_sync_change_ = [this](SyncState dl, SyncState ul) {
    if (ul == SyncState::IDLE) {
      on_sync_change_ = nullptr;
      sync_watcher_binding_.Unbind();
      LaunchReaderInstance();
    }
  };
  writer_page_->SetSyncStateWatcher(sync_watcher_binding_.NewBinding());
}

void LazyFetchBenchmarker::LaunchReaderInstance() {
  std::string reader_path = reader_storage_.path() + kUserDirSuffix;
  bool created = files::CreateDirectory(reader_path);
  FXL_DCHECK(created);

  cloud_provider::CloudProviderPtr reader_cloud;
  cloud_factory_.MakeCloudProvider(user_id_, reader_cloud.NewRequest());

  Status status = GetLedger(system_context_.get(), reader_ctrl_.NewRequest(),
                            std::move(reader_cloud), user_id_.user_id(), "lazy_fetch",
                            DetachedPath(std::move(reader_path)), ExitHandler(),
                            &reader_ledger_, kDefaultGarbageCollectionPolicy);
  if (QuitOnError(ExitHandler(), status, "Reader setup failed")) {
    return;
  }

  reader_ledger_->GetPage(fidl::MakeOptional(active_page_id_), reader_page_.NewRequest());
  AwaitReaderCompletion();
}

void LazyFetchBenchmarker::AwaitReaderCompletion() {
  on_sync_change_ = [this](SyncState dl, SyncState ul) {
    if (dl == SyncState::IDLE) {
      on_sync_change_ = nullptr;
      PageSnapshotPtr snapshot;
      reader_page_->GetSnapshot(snapshot.NewRequest(), {}, nullptr);
      IssueFetches(std::move(snapshot), 0u);
    }
  };
  reader_page_->SetSyncStateWatcher(sync_watcher_binding_.NewBinding());
}

void LazyFetchBenchmarker::IssueFetches(PageSnapshotPtr snap, size_t index) {
  if (index >= total_items_) {
    Terminate();
    return;
  }

  if (chunk_size_ > 0u) {
    TRACE_ASYNC_BEGIN("benchmark", "CumulativeFetch", index);
    IssueChunkedFetch(std::move(snap), index, 0u);
    return;
  }

  PageSnapshot* raw_snap = snap.get();
  TRACE_ASYNC_BEGIN("benchmark", "FullFetch", index);
  raw_snap->Fetch(std::move(entry_keys_[index]),
                  [this, snap = std::move(snap), index](
                      fuchsia::ledger::PageSnapshot_Fetch_Result result) mutable {
                    if (QuitOnError(ExitHandler(), result, "Fetch failed")) {
                      return;
                    }
                    TRACE_ASYNC_END("benchmark", "FullFetch", index);
                    IssueFetches(std::move(snap), index + 1);
                  });
}

void LazyFetchBenchmarker::IssueChunkedFetch(PageSnapshotPtr snap, size_t index, size_t offset) {
  if (offset * chunk_size_ >= item_size_) {
    TRACE_ASYNC_END("benchmark", "CumulativeFetch", index);
    IssueFetches(std::move(snap), index + 1);
    return;
  }

  PageSnapshot* raw_snap = snap.get();
  auto trace_id = TRACE_NONCE();
  TRACE_ASYNC_BEGIN("benchmark", "PartialFetch", trace_id);

  raw_snap->FetchPartial(
      entry_keys_[index], offset * chunk_size_, chunk_size_,
      [this, snap = std::move(snap), index, offset, trace_id](
          fuchsia::ledger::PageSnapshot_FetchPartial_Result result) mutable {
        if (QuitOnError(ExitHandler(), result, "FetchPartial failed")) {
          return;
        }
        TRACE_ASYNC_END("benchmark", "PartialFetch", trace_id);
        IssueChunkedFetch(std::move(snap), index, offset + 1);
      });
}

void LazyFetchBenchmarker::Terminate() {
  KillLedgerProcess(&writer_ctrl_);
  KillLedgerProcess(&reader_ctrl_);
  event_loop_->Quit();
}

fit::closure LazyFetchBenchmarker::ExitHandler() {
  return [this] { event_loop_->Quit(); };
}

int RunBenchmark(int argc, char** argv) {
  fxl::CommandLine cmdline = fxl::CommandLineFromArgcArgv(argc, argv);
  async::Loop loop(&kAsyncLoopConfigAttachToCurrentThread);
  auto context = sys::ComponentContext::Create();

  std::string items_str;
  size_t items;
  std::string size_str;
  size_t size;
  std::string chunk_str;
  size_t chunk;
  SyncParams cloud_config;

  if (!cmdline.GetOptionValue(kNumEntriesOpt.ToString(), &items_str) ||
      !fxl::StringToNumberWithError(items_str, &items) || items == 0 ||
      !cmdline.GetOptionValue(kPayloadSizeOpt.ToString(), &size_str) ||
      !fxl::StringToNumberWithError(size_str, &size) || size == 0 ||
      !cmdline.GetOptionValue(kChunkSizeOpt.ToString(), &chunk_str) ||
      !fxl::StringToNumberWithError(chunk_str, &chunk) ||
      !ParseSyncParamsFromCommandLine(cmdline, context.get(), &cloud_config)) {
    ShowHelp();
    return -1;
  }

  LazyFetchBenchmarker bench(&loop, std::move(context), items, size, chunk,
                             std::move(cloud_config));
  return RunWithTracing(&loop, [&bench] { bench.Execute(); });
}

}  // namespace
}  // namespace ledger

int main(int argc, char** argv) {
  return ledger::RunBenchmark(argc, argv);
}

#include <iostream>
#include <cstring>
#include <cstddef>

// Replaced header includes with standard equivalents
namespace xslab_impl {
    // Constants redefined with equivalent values
    const unsigned int SLAB_PAGE_MASK = 3;
    const unsigned int SLAB_PAGE = 0;
    const unsigned int SLAB_BIG = 1;
    const unsigned int SLAB_EXACT = 2;
    const unsigned int SLAB_SMALL = 3;

    // Platform-specific constants based on pointer size
    #if (SIZE_MAX == 0xFFFFFFFF)
    const uintptr_t SLAB_PAGE_FREE = 0;
    const uintptr_t SLAB_PAGE_BUSY = 0xFFFFFFFF;
    const uintptr_t SLAB_PAGE_START = 0x80000000;
    const uintptr_t SLAB_SHIFT_MASK = 0x0000000F;
    const uintptr_t SLAB_MAP_MASK = 0xFFFF0000;
    const int SLAB_MAP_SHIFT = 16;
    const uintptr_t SLAB_BUSY = 0xFFFFFFFF;
    #else
    const uintptr_t SLAB_PAGE_FREE = 0;
    const uintptr_t SLAB_PAGE_BUSY = 0xFFFFFFFFFFFFFFFF;
    const uintptr_t SLAB_PAGE_START = 0x8000000000000000;
    const uintptr_t SLAB_SHIFT_MASK = 0x000000000000000F;
    const uintptr_t SLAB_MAP_MASK = 0xFFFFFFFF00000000;
    const int SLAB_MAP_SHIFT = 32;
    const uintptr_t SLAB_BUSY = 0xFFFFFFFFFFFFFFFF;
    #endif

    // Global variables
    unsigned int pagesize_val = 0;
    unsigned int pagesize_shift = 0;
    unsigned int cacheline_size = 0;

    // Helper macros converted to inline functions
    inline void* slabs_slots(void* pool_ptr) {
        return reinterpret_cast<void*>(reinterpret_cast<unsigned char*>(pool_ptr) + sizeof(void*));
    }

    inline unsigned int page_type(unsigned long prev) {
        return static_cast<unsigned int>(prev & SLAB_PAGE_MASK);
    }

    inline unsigned long page_prev(unsigned long prev) {
        return prev & ~SLAB_PAGE_MASK;
    }

    // Simplified debug macro
    #if defined(DEBUG_MODE)
    inline void slab_junk(void* ptr, size_t sz) {
        memset(ptr, 0xA5, sz);
    }
    #else
    inline void slab_junk(void*, size_t) {}
    #endif

    // Data structures simplified
    struct slab_page {
        unsigned long slab;
        slab_page* next;
        unsigned long prev;
    };

    struct slab_pool {
        size_t min_size;
        unsigned int min_shift;
        unsigned char* start;
        unsigned char* end;
        slab_page free;
        slab_page* pages;
        slab_page* last;
        unsigned int pfree;
        bool log_nomem;
        void* log_ctx;
        char zero;
        // Additional fields would be needed in real implementation
    };

    // Size calculation functions
    unsigned int max_block_size = 0;
    unsigned int exact_size = 0;
    unsigned int exact_shift = 0;

    void init_sizes() {
        max_block_size = pagesize_val / 2;
        exact_size = pagesize_val / (8 * sizeof(size_t));

        unsigned int n = exact_size;
        while (n >>= 1) {
            exact_shift++;
        }
    }

    // Pool initialization
    void init_pool(slab_pool* pool) {
        unsigned char* pos = reinterpret_cast<unsigned char*>(slabs_slots(pool));
        size_t total_size = pool->end - pos;

        slab_junk(pos, total_size);

        unsigned int shift_diff = pagesize_shift - pool->min_shift;

        // Initialize slot list headers
        for (unsigned int i = 0; i < shift_diff; ++i) {
            slab_page* slot = reinterpret_cast<slab_page*>(pos);
            slot->slab = 0;
            slot->next = slot;
            slot->prev = 0;
            pos += sizeof(slab_page);
        }

        // Calculate remaining space for pages
        total_size -= shift_diff * sizeof(slab_page);
        pos += shift_diff * sizeof(void*); // Skip stats area

        unsigned int num_pages = static_cast<unsigned int>(
            total_size / (pagesize_val + sizeof(slab_page)));

        pool->pages = reinterpret_cast<slab_page*>(pos);
        memset(pool->pages, 0, num_pages * sizeof(slab_page));

        slab_page* first_page = pool->pages;
        pool->free.slab = 0;
        pool->free.next = first_page;
        pool->free.prev = 0;
        first_page->slab = num_pages;
        first_page->next = &pool->free;
        first_page->prev = reinterpret_cast<unsigned long>(&pool->free);

        // Align start address
        size_t align_offset = (pagesize_val - 1);
        pool->start = reinterpret_cast<unsigned char*>(
            (reinterpret_cast<size_t>(pos + num_pages * sizeof(slab_page)) + align_offset) & ~align_offset);

        // Adjust page count if necessary
        int adjustment = num_pages - (pool->end - pool->start) / pagesize_val;
        if (adjustment > 0) {
            num_pages -= adjustment;
            first_page->slab = num_pages;
        }

        pool->last = pool->pages + num_pages;
        pool->pfree = num_pages;
        pool->log_nomem = true;
        pool->log_ctx = &pool->zero;
        pool->zero = '\0';
    }

    // Allocation function
    void* allocate_from_pool(slab_pool* pool, size_t req_size) {
        if (req_size > max_block_size) {
            unsigned int page_count = (req_size >> pagesize_shift) + 
                                     ((req_size % pagesize_val) ? 1 : 0);
            slab_page* page = allocate_pages(pool, page_count);
            if (page) {
                return reinterpret_cast<void*>(
                    (((page - pool->pages) << pagesize_shift) + 
                     reinterpret_cast<uintptr_t>(pool->start)));
            }
            return nullptr;
        }

        unsigned int shift = 1;
        size_t temp = req_size - 1;
        while (temp >>= 1) {
            shift++;
        }

        unsigned int slot = shift - pool->min_shift;
        if (req_size <= pool->min_size) {
            shift = pool->min_shift;
            slot = 0;
        }

        slab_page* slots = reinterpret_cast<slab_page*>(slabs_slots(pool));
        slab_page* page = slots[slot].next;

        if (page->next != page) {
            if (shift < exact_shift) {
                // Handle small allocations with bitmap
                uintptr_t* bitmap = reinterpret_cast<uintptr_t*>(
                    (((page - pool->pages) << pagesize_shift) + 
                     reinterpret_cast<uintptr_t>(pool->start)));
                unsigned int map_size = (pagesize_val >> shift) / (8 * sizeof(uintptr_t));

                for (unsigned int n = 0; n < map_size; ++n) {
                    if (bitmap[n] != SLAB_BUSY) {
                        for (uintptr_t mask = 1, idx = 0; mask; mask <<= 1, idx++) {
                            if (bitmap[n] & mask) continue;

                            bitmap[n] |= mask;
                            size_t offset = (n * 8 * sizeof(uintptr_t) + idx) << shift;
                            void* result = reinterpret_cast<void*>(
                                reinterpret_cast<uintptr_t>(bitmap) + offset);
                            return result;
                        }
                    }
                }
            } else if (shift == exact_shift) {
                // Handle exact-sized allocations
                for (uintptr_t mask = 1, idx = 0; mask; mask <<= 1, idx++) {
                    if (page->slab & mask) continue;

                    page->slab |= mask;
                    void* result = reinterpret_cast<void*>(
                        (((page - pool->pages) << pagesize_shift) + 
                         reinterpret_cast<uintptr_t>(pool->start)) + (idx << shift));
                    return result;
                }
            } else {
                // Handle big allocations
                uintptr_t mask = ((uintptr_t)1 << (pagesize_val >> shift)) - 1;
                mask <<= SLAB_MAP_SHIFT;

                for (uintptr_t bit = 1 << SLAB_MAP_SHIFT, idx = 0; bit & mask; bit <<= 1, idx++) {
                    if (page->slab & bit) continue;

                    page->slab |= bit;
                    void* result = reinterpret_cast<void*>(
                        (((page - pool->pages) << pagesize_shift) + 
                         reinterpret_cast<uintptr_t>(pool->start)) + (idx << shift));
                    return result;
                }
            }
        }

        // Allocate new page if needed
        page = allocate_pages(pool, 1);
        if (page) {
            // Initialize new page for requested size class
            if (shift < exact_shift) {
                uintptr_t* bitmap = reinterpret_cast<uintptr_t*>(
                    (((page - pool->pages) << pagesize_shift) + 
                     reinterpret_cast<uintptr_t>(pool->start)));
                unsigned int chunk_count = (pagesize_val >> shift) / ((1 << shift) * 8);
                if (chunk_count == 0) chunk_count = 1;

                for (unsigned int i = 0; i < (chunk_count + 1) / (8 * sizeof(uintptr_t)); ++i) {
                    bitmap[i] = SLAB_BUSY;
                }

                uintptr_t final_mask = ((uintptr_t)1 << ((chunk_count + 1) % (8 * sizeof(uintptr_t)))) - 1;
                bitmap[(chunk_count + 1) / (8 * sizeof(uintptr_t))] = final_mask;

                page->slab = shift;
                page->next = &slots[slot];
                page->prev = reinterpret_cast<unsigned long>(&slots[slot]) | SLAB_SMALL;
                slots[slot].next = page;

                void* result = reinterpret_cast<void*>(
                    (((page - pool->pages) << pagesize_shift) + 
                     reinterpret_cast<uintptr_t>(pool->start)) + (chunk_count << shift));
                return result;
            } else if (shift == exact_shift) {
                page->slab = 1;
                page->next = &slots[slot];
                page->prev = reinterpret_cast<unsigned long>(&slots[slot]) | SLAB_EXACT;
                slots[slot].next = page;

                void* result = reinterpret_cast<void*>(
                    (((page - pool->pages) << pagesize_shift) + 
                     reinterpret_cast<uintptr_t>(pool->start)));
                return result;
            } else {
                page->slab = ((uintptr_t)1 << SLAB_MAP_SHIFT) | shift;
                page->next = &slots[slot];
                page->prev = reinterpret_cast<unsigned long>(&slots[slot]) | SLAB_BIG;
                slots[slot].next = page;

                void* result = reinterpret_cast<void*>(
                    (((page - pool->pages) << pagesize_shift) + 
                     reinterpret_cast<uintptr_t>(pool->start)));
                return result;
            }
        }

        return nullptr;
    }

    // Page allocation helper
    slab_page* allocate_pages(slab_pool* pool, unsigned int needed_pages) {
        slab_page* current = pool->free.next;

        while (current != &pool->free) {
            if (current->slab >= needed_pages) {
                if (current->slab > needed_pages) {
                    // Split the page
                    slab_page* split_page = current + needed_pages;
                    split_page->slab = current->slab - needed_pages;
                    split_page->next = current->next;
                    split_page->prev = current->prev;

                    slab_page* prev_page = reinterpret_cast<slab_page*>(current->prev);
                    prev_page->next = split_page;
                    split_page->next->prev = reinterpret_cast<unsigned long>(split_page);
                } else {
                    // Remove entire page from free list
                    slab_page* prev_page = reinterpret_cast<slab_page*>(current->prev);
                    prev_page->next = current->next;
                    current->next->prev = current->prev;
                }

                current->slab = needed_pages | SLAB_PAGE_START;
                current->next = nullptr;
                current->prev = SLAB_PAGE;
                pool->pfree -= needed_pages;

                if (--needed_pages == 0) {
                    return current;
                }

                // Mark remaining pages as busy
                for (slab_page* p = current + 1; needed_pages; --needed_pages, ++p) {
                    p->slab = SLAB_PAGE_BUSY;
                    p->next = nullptr;
                    p->prev = SLAB_PAGE;
                }

                return current;
            }
            current = current->next;
        }

        return nullptr;
    }

    // Free page handling
    void free_pages(slab_pool* pool, slab_page* page, unsigned int num_pages) {
        pool->pfree += num_pages;
        page->slab = num_pages--;

        if (num_pages) {
            memset(&page[1], 0, num_pages * sizeof(slab_page));
        }

        // Coalesce adjacent free pages
        slab_page* join_page = page + page->slab;
        if (join_page < pool->last && page_type(join_page->prev) == SLAB_PAGE) {
            if (join_page->next != nullptr) {
                num_pages += join_page->slab;
                page->slab += join_page->slab;

                slab_page* prev_page = reinterpret_cast<slab_page*>(join_page->prev);
                prev_page->next = join_page->next;
                join_page->next->prev = join_page->prev;

                join_page->slab = SLAB_PAGE_FREE;
                join_page->next = nullptr;
                join_page->prev = SLAB_PAGE;
            }
        }

        if (page > pool->pages) {
            join_page = page - 1;
            if (page_type(join_page->prev) == SLAB_PAGE) {
                if (join_page->slab == SLAB_PAGE_FREE) {
                    join_page = reinterpret_cast<slab_page*>(join_page->prev);
                }
                if (join_page->next != nullptr) {
                    num_pages += join_page->slab;
                    join_page->slab += page->slab;

                    slab_page* prev_page = reinterpret_cast<slab_page*>(join_page->prev);
                    prev_page->next = join_page->next;
                    join_page->next->prev = join_page->prev;

                    page->slab = SLAB_PAGE_FREE;
                    page->next = nullptr;
                    page->prev = SLAB_PAGE;
                    page = join_page;
                }
            }
        }

        if (num_pages) {
            page[num_pages].prev = reinterpret_cast<unsigned long>(page);
        }

        page->prev = reinterpret_cast<unsigned long>(&pool->free);
        page->next = pool->free.next;
        page->next->prev = reinterpret_cast<unsigned long>(page);
        pool->free.next = page;
    }
}

