u32 MsgHeader::gSharedSN = 0;
const s8* G_CFGFILE = "Config/config.json";

Engine::Engine() :
    mPPID(0),
    mPID(0),
    mWorkers(32),
    mIsParent(true) {
}

Engine::~Engine() {
}

void Engine::cleanup() {
    //Logger::clear();
    System::removeFile(mSettings.mPidPath.c_str());
}


void Engine::broadcastCommand(s32 cmdVal) {
    MsgHeader header;
    switch (cmdVal) {
    case ECT_EXIT:
        header.finish(ECT_EXIT, ++MsgHeader::gSharedSN, ECT_VERSION);
        break;
    case ECT_ACTIVE:
        header.finish(ECT_ACTIVE, ++MsgHeader::gSharedSN, ECT_VERSION);
        break;
    default:
        Logger::log(ELL_INFO, "Engine::broadcastCommand>>invalid command = %d", cmdVal);
        return;
    }

    for (usz idx = 0; idx < mWorkers.size(); ++idx) {
        if (sizeof(header) != mWorkers[idx].mSocket.sendAll(&header, sizeof(header))) {
            Logger::log(ELL_INFO, "Engine::broadcastCommand>>failed to send cmd=%d to child pid=%d",
                cmdVal, mWorkers[idx].mID);
        }
    }

    if (ECT_EXIT == cmdVal) {
        for (usz idx = 0; idx < mWorkers.size(); ++idx) {
            if (mWorkers[idx].mHandle) {
                System::waitProcess(mWorkers[idx].mHandle);
                mWorkers[idx].mHandle = nullptr;
                Logger::log(ELL_INFO, "Engine::broadcastCommand>>worker[%zu] terminated, pid=%d",
                    idx, mWorkers[idx].mID);
            }
        }
        if (mParentProc.mHandle) {
            mParentProc.mSocket.sendAll(&header, sizeof(header));
        }
    }
}


bool Engine::startup(const s8* cfgPath, bool isChild) {
    mIsParent = !isChild;
    AppStrConverterInit();
#if defined(DOS_WINDOWS)
    s8 utf8Buf[260];
    AppGbkToUTF8(cfgPath, utf8Buf, sizeof(utf8Buf));
    cfgPath = utf8Buf;
#endif

    MsgHeader::gSharedSN = 0;
    mAppDir = cfgPath;
    mAppDir.deleteFilename();
    mAppDir.replace('\\', '/');
    mAppName = cfgPath + mAppDir.getLen();

    if (!mSettings.load(mAppDir, G_CFGFILE)) {
        mSettings.save(mAppDir + G_CFGFILE + ".gen.json");
        return false;
    }

    Timer::getTimeZone();
    System::getCoreCount();
    System::getPageSize();
    System::getDiskSectorSize();

    System::createPath(mSettings.mLogPath);

    Logger::getInstance();

    mPID = System::getPID();
    Logger::addFileReceiver();

    bool netOk = (0 == System::loadNetLib());
    if (!netOk) {
        Logger::log(ELL_ERROR, "Engine::startup>>network library load failed");
        return false;
    }

    mTlsENG.init();

    if (mSettings.mMaxWorkers > 0) {
        if (App4Char2S32("GMEM") == App4Char2S32(mSettings.mMemName.c_str())) {
            if (mIsParent) {
                if (!mMapfile.createMem(mSettings.mMemSize, mSettings.mMemName.c_str(), false, true)) {
                    Logger::log(ELL_INFO, "Engine::startup>>memory mapping creation failed: %s",
                        mSettings.mMemName.c_str());
                    return false;
                }
            } else {
                if (!mMapfile.openMem(mSettings.mMemName.c_str(), false)) {
                    Logger::log(ELL_INFO, "Engine::startup>>child failed to open shared memory: %s",
                        mSettings.mMemName.c_str());
                    return false;
                }
            }
        } else {
            if (mIsParent) {
                if (!mMapfile.createMapfile(mSettings.mMemSize, mSettings.mMemName.c_str(), false, false, true)) {
                    Logger::log(ELL_INFO, "Engine::startup>>mapfile creation failed: %s",
                        mSettings.mMemName.c_str());
                    return false;
                }
            } else {
                if (!mMapfile.openMem(mSettings.mMemName.c_str(), false)) {
                    Logger::log(ELL_INFO, "Engine::startup>>child failed to open mapfile: %s",
                        mSettings.mMemName.c_str());
                    return false;
                }
            }
        }

        MemSlabPool& slabPool = getMemSlabPool();
        if (mIsParent) {
            new (&slabPool) MemSlabPool(mSettings.mMemSize);
        } else {
            slabPool.initSlabSize();
        }
    }

    if (mIsParent) {
        FileWriter pidFile;
        if (pidFile.openFile(mSettings.mPidPath, false)) {
            pidFile.writeParams("%d", mPID);
            pidFile.close();
        } else {
            return false;
        }
        Logger::log(ELL_INFO, "Engine::startup>>parent PID = %d, role = %c", mPID, mIsParent ? 'P' : 'C');
        bool procCreated = spawnWorkers();
        if (!procCreated) return false;
    }

    if (mIsParent) {
        Logger::addPrintReceiver();
        return runParentProcess();
    } else {
#if defined(DOS_WINDOWS)
        net::Socket stdinSock = (net::netsocket)GetStdHandle(STD_INPUT_HANDLE);
        Logger::log(ELL_INFO, "Engine::startup>>child PID = %d, stdinSock = %llu", mPID, stdinSock.getValue());
        if (!stdinSock.isOpen()) {
            Logger::log(ELL_INFO, "Engine::startup>>child PID = %d, role = %c", mPID, mIsParent ? 'P' : 'C');
            return false;
        }

        Logger::log(ELL_INFO, "Engine::startup>>child PID = %d, role = %c", mPID, mIsParent ? 'P' : 'C');
        return runWorkerProcess(stdinSock);
#endif
    }

    mPID = System::getPID();
    return true;
}


bool Engine::shutdown() {
    Logger::flush();
    mThreadPool.stop();
    cleanup();
    mTlsENG.uninit();
    return (0 == System::unloadNetLib());
}

void Engine::loopForever() {
    while (mEventLoop.run()) {
        // keep running
    }
}

bool Engine::stepOnce() {
    return mEventLoop.run();
}

bool Engine::runParentProcess() {
    String pipePath = Engine::getInstance().getSettings().mLogPath;
    pipePath += System::getPID();
    pipePath += ".unpath";

    mParentProc.mHandle = nullptr;
    net::SocketPair pipe;
    if (pipe.open(pipePath.c_str())) {
        mParentProc.mID = System::getPID();
        mParentProc.mStatus = 0;
        mParentProc.mSocket = pipe.getSocketA();
    } else {
        Logger::log(ELL_ERROR, "Engine::runParentProcess>> pipe creation failed");
        return false;
    }

    mThreadPool.start(mSettings.mMaxThreads);
    bool ok = mEventLoop.start(pipe.getSocketB());
    if (ok) { setupTasks(); }
    return ok;
}

bool Engine::runWorkerProcess(net::Socket& sock) {
    mThreadPool.start(mSettings.mMaxThreads);
    bool ok = mEventLoop.start(sock);
    if (ok) {
        setupTasks();
    }
    return ok;
}

bool Engine::spawnWorkers() {
    bool success = true;
    String pipePath = Engine::getInstance().getSettings().mLogPath;
    pipePath += System::getPID();
    pipePath += ".unpath";

    Process workerNode;
    mWorkers.reallocate(mSettings.mMaxWorkers);
    net::SocketPair pipe;
    for (s16 i = 0; i < mSettings.mMaxWorkers; ++i) {
        if (pipe.open(pipePath.c_str())) {
            workerNode.mSocket = pipe.getSocketA();
            workerNode.mID = System::createProcess(pipe.getSocketB().getValue(), workerNode.mHandle);
            workerNode.mStatus = 1;

#if defined(DOS_LINUX)
            if (0 == workerNode.mID) {
                pipe.getSocketA().close();
                runWorkerProcess(pipe.getSocketB());
                mIsParent = false;
                return true;
            } else {
                pipe.getSocketB().close();
                if (workerNode.mID < 0) {
                    pipe.close();
                    continue;
                }
            }
#endif

            mWorkers.pushBack(workerNode);
            Logger::log(ELL_INFO, "Engine::spawnWorkers>>worker[%d] spawned, pid=%d, sock=%llu",
                i, workerNode.mID, workerNode.mSocket.getValue());
        } else {
            Logger::log(ELL_ERROR, "Engine::spawnWorkers>>failed to create worker[%d]", (s32)i);
            success = false;
            break;
        }
    }
    return success;
}


void Engine::setupTasks() {
    for (usz idx = 0; idx < mSettings.mProxies.size(); ++idx) {
        net::Acceptor* acc = new net::Acceptor(mEventLoop, net::TcpProxy::funcOnLink, &mSettings.mProxies[idx]);
        acc->setTimeout(mSettings.mProxies[idx].mTimeout);
        acc->setBackend(mSettings.mProxies[idx].mRemote);
        if (0 == acc->open(mSettings.mProxies[idx].mLocal)) {
            Logger::log(ELL_INFO, "Engine::setupTasks>>started proxy [%s -> %s]",
                mSettings.mProxies[idx].mLocal.getStr(), mSettings.mProxies[idx].mRemote.getStr());
        } else {
            Logger::log(ELL_ERROR, "Engine::setupTasks>>failed proxy [%s -> %s]",
                mSettings.mProxies[idx].mLocal.getStr(), mSettings.mProxies[idx].mRemote.getStr());
            delete acc;
        }
    }

    for (usz idx = 0; idx < mSettings.mSites.size(); ++idx) {
        switch (mSettings.mSites[idx].mKind) {
        case 0: // HTTP
        case 1: // HTTPS
        {
            net::Acceptor* acc = new net::Acceptor(mEventLoop, net::HttpLayer::funcOnLink, &mSettings.mSites[idx]);
            acc->getHandleTCP().setTimeGap(mSettings.mSites[idx].mTimeout);
            acc->getHandleTCP().setTimeout(mSettings.mSites[idx].mTimeout);
            if (0 == acc->open(mSettings.mSites[idx].mLocal)) {
                Logger::log(ELL_INFO, "Engine::setupTasks>>started site [%s, root=%s]",
                    mSettings.mSites[idx].mLocal.getStr(), mSettings.mSites[idx].mRootPath.c_str());
            } else {
                Logger::log(ELL_ERROR, "Engine::setupTasks>>failed site [%s, root=%s]",
                    mSettings.mSites[idx].mLocal.getStr(), mSettings.mSites[idx].mRootPath.c_str());
                delete acc;
            }
            break;
        }
        default:
            Logger::log(ELL_ERROR, "Engine::setupTasks>>unsupported service type (%d) at index %zu",
                mSettings.mSites[idx].mKind, idx);
            break;
        }
    }
}

