    void TileRenderer::offsetLayerHorizontally(double offset) {
        std::lock_guard<std::mutex> guard(_mutex);
        _horizontalLayerOffset += offset;
    }

    void TileRenderer::onSurfaceCreated(const std::shared_ptr<ShaderManager>& shaderManager, const std::shared_ptr<TextureManager>& textureManager) {
        std::lock_guard<std::mutex> guard(_mutex);

        Log::Debug("TileRenderer: Surface created");

        auto weakThis = std::weak_ptr<TileRenderer>(std::static_pointer_cast<TileRenderer>(shared_from_this()));
        auto deleterFunc = [weakThis](vt::GLTileRenderer* rawPtr) {
            std::unique_ptr<vt::GLTileRenderer> owned(rawPtr);
            Log::Debug("TileRenderer: Releasing renderer resources");
            if (auto mapRend = weakThis.lock()) {
                if (auto mapRenderer = mapRend->_mapRenderer.lock()) {
                    mapRenderer->addRenderThreadCallback(std::make_shared<GLTileRendererDisposer>(std::move(owned)));
                }
            }
        };

        _glRenderer = std::shared_ptr<vt::GLTileRenderer>(
            new vt::GLTileRenderer(_glRendererMutex, std::make_shared<carto::vt::GLExtensions>(), Const::WORLD_SIZE),
            deleterFunc
        );

        _glRenderer->initializeRenderer();
        _tiles.clear();
        GLContext::CheckGLError("TileRenderer::onSurfaceCreated");
    }

    bool TileRenderer::onDrawFrame(float deltaSeconds, const ViewState& viewState) {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return false;
        }

        auto modelViewMat = viewState.getModelviewMat();
        modelViewMat = modelViewMat * cglib::translate4_matrix(cglib::vec3<double>(_horizontalLayerOffset, 0.0, 0.0));
        _glRenderer->setViewState(viewState.getProjectionMat(), modelViewMat,
                                  viewState.getZoom(), viewState.getAspectRatio(), viewState.getNormalizedResolution());
        _glRenderer->setInteractionMode(_interactionMode);
        _glRenderer->setSubTileBlending(_subTileBlending);
        _glRenderer->setBackground(vt::Color(_backgroundColor.getARGB()), _backgroundPattern);
        _glRenderer->startFrame(deltaSeconds * 3.0);

        bool needsRefresh = false;

        // Render in specified order based on layer priorities
        if (_labelOrder == 0) {
            needsRefresh |= _glRenderer->renderLabels(true, false);
        }
        if (_buildingOrder == 0) {
            needsRefresh |= _glRenderer->renderGeometry3D();
        }
        if (_labelOrder == 0) {
            needsRefresh |= _glRenderer->renderLabels(false, true);
        }

        // Restore expected OpenGL state
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glDisable(GL_DEPTH_TEST);
        glDepthMask(GL_TRUE);
        GLContext::CheckGLError("TileRenderer::onDrawFrame");

        return needsRefresh;
    }

    bool TileRenderer::onDrawFrame3D(float deltaSeconds, const ViewState& viewState) {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return false;
        }

        bool needsRefresh = false;

        // Alternate rendering order for 3D frame
        if (_labelOrder == 1) {
            needsRefresh |= _glRenderer->renderLabels(true, false);
        }
        if (_buildingOrder == 1) {
            needsRefresh |= _glRenderer->renderGeometry3D();
        }
        if (_labelOrder == 1) {
            needsRefresh |= _glRenderer->renderLabels(false, true);
        }

        _glRenderer->endFrame();

        // Restore expected OpenGL state
        glEnable(GL_CULL_FACE);
        glCullFace(GL_BACK);
        glDisable(GL_DEPTH_TEST);
        glDepthMask(GL_TRUE);
        GLContext::CheckGLError("TileRenderer::onDrawFrame3D");

        return needsRefresh;
    }

    void TileRenderer::onSurfaceDestroyed() {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return;
        }

        Log::Debug("TileRenderer: Surface destroyed");
        _glRenderer->resetRenderer();
        _glRenderer.reset();
    }

    bool TileRenderer::cullLabels(const ViewState& viewState) {
        auto modelViewMat = viewState.getModelviewMat();

        std::vector<std::shared_ptr<vt::TileLabel>> visibleLabels;
        {
            std::lock_guard<std::mutex> guard(_mutex);
            if (!_glRenderer) {
                return false;
            }
            modelViewMat = modelViewMat * cglib::translate4_matrix(cglib::vec3<double>(_horizontalLayerOffset, 0.0, 0.0));
            visibleLabels = _glRenderer->getVisibleLabels();
        }

        vt::TileLabelCuller culler(_glRendererMutex, Const::WORLD_SIZE);
        culler.setViewState(viewState.getProjectionMat(), modelViewMat,
                            viewState.getZoom(), viewState.getAspectRatio(), viewState.getNormalizedResolution());
        culler.process(visibleLabels);

        return true;
    }

    bool TileRenderer::refreshTiles(const std::vector<std::shared_ptr<TileDrawData>>& drawDatas) {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return false;
        }

        std::map<vt::TileId, std::shared_ptr<const vt::Tile>> updatedTiles;
        for (const auto& dd : drawDatas) {
            updatedTiles.emplace(dd->getVTTileId(), dd->getVTTile());
        }

        bool changed = (updatedTiles != _tiles);
        if (changed) {
            _glRenderer->setVisibleTiles(updatedTiles, _horizontalLayerOffset == 0.0);
            _tiles = std::move(updatedTiles);
        }

        _horizontalLayerOffset = 0.0;
        return changed;
    }

    void TileRenderer::calculateRayIntersectedElements(const cglib::ray3<double>& ray, const ViewState& viewState, std::vector<std::tuple<vt::TileId, double, long long>>& results) const {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return;
        }

        float radius = CLICK_RADIUS; // DPI-aware scaling handled internally

        _glRenderer->findGeometryIntersections(ray, results, radius, true, false);
        if (_labelOrder == 0) {
            _glRenderer->findLabelIntersections(ray, results, radius, true, false);
        }
        if (_buildingOrder == 0) {
            _glRenderer->findGeometryIntersections(ray, results, radius, false, true);
        }
        if (_labelOrder == 0) {
            _glRenderer->findLabelIntersections(ray, results, radius, false, true);
        }
    }

    void TileRenderer::calculateRayIntersectedBitmaps(const cglib::ray3<double>& ray, const ViewState& viewState, std::vector<std::tuple<vt::TileId, double, vt::TileBitmap, cglib::vec2<float>>>& results) const {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return;
        }

        _glRenderer->findBitmapIntersections(ray, results);
    }

    void TileRenderer::calculateRayIntersectedElements3D(const cglib::ray3<double>& ray, const ViewState& viewState, std::vector<std::tuple<vt::TileId, double, long long>>& results) const {
        std::lock_guard<std::mutex> guard(_mutex);

        if (!_glRenderer) {
            return;
        }

        float radius = viewState.getUnitToDPCoef() * CLICK_RADIUS;

        if (_labelOrder == 1) {
            _glRenderer->findLabelIntersections(ray, results, radius, true, false);
        }
        if (_buildingOrder == 1) {
            _glRenderer->findGeometryIntersections(ray, results, radius, false, true);
        }
        if (_labelOrder == 1) {
            _glRenderer->findLabelIntersections(ray, results, radius, false, true);
        }
    }

}

