#include <vector>
#include <algorithm>
#include <numeric>

class Solution {
public:
    int maxProfit(int k, std::vector<int>& prices) {
        // Collect all profitable intervals (valley to peak)
        std::vector<std::pair<int, int>> intervals;
        int n = prices.size();

        if (n <= 1) return 0;

        int i = 0;
        while (i < n - 1) {
            // Find local minimum (valley)
            while (i < n - 1 && prices[i] >= prices[i + 1]) {
                ++i;
            }
            int valley = i;

            // Find local maximum (peak)
            while (i < n - 1 && prices[i] <= prices[i + 1]) {
                ++i;
            }
            int peak = i;

            // Record the interval if valid
            if (valley < peak) {
                intervals.emplace_back(valley, peak);
            }
        }

        // Extract profits from each interval
        std::vector<int> gains;
        for (const auto& interval : intervals) {
            gains.push_back(prices[interval.second] - prices[interval.first]);
        }

        // If allowed transactions >= available opportunities, take all
        if (gains.size() <= static_cast<size_t>(k)) {
            return std::accumulate(gains.begin(), gains.end(), 0);
        }

        // Otherwise, pick top k profits using partial sort
        std::nth_element(gains.begin(), gains.end() - k, gains.end());
        int total = 0;
        for (int i = 1; i <= k; ++i) {
            total += gains[gains.size() - i];
        }
        return total;
    }
};

