// Helper: Convert narrow C-string to wide BSTR-compatible wstring
static std::wstring narrow_to_wide(const char* src) {
    if (!src) return {};
    std::wstring result;
    const int needed = MultiByteToWideChar(CP_ACP, 0, src, -1, nullptr, 0);
    if (needed > 0) {
        result.resize(needed - 1);
        const int written = MultiByteToWideChar(CP_ACP, 0, src, -1, &result[0], needed);
        if (written == 0 && GetLastError() != ERROR_INSUFFICIENT_BUFFER) {
            result.clear();
        }
    }
    return result;
}

// Helper: Convert BSTR to narrow string (handles embedded NULs)
static std::string wide_to_narrow(BSTR src) {
    if (!src) return {};
    const auto len = SysStringLen(src);
    std::string output;
    const int required = WideCharToMultiByte(CP_ACP, 0, src, static_cast<int>(len) + 1, nullptr, 0, nullptr, nullptr);
    if (required > 0) {
        output.resize(required, '\0');
        const int converted = WideCharToMultiByte(CP_ACP, 0, src, static_cast<int>(len) + 1, &output[0], required, nullptr, nullptr);
        if (converted == 0) {
            output.clear();
        } else {
            output.resize(required - 1); // Trim trailing NUL added by WC2MB
        }
    }
    return output;
}

// Retrieve OS name using WMI query on Win32_OperatingSystem
static std::string fetch_windows_os_name() {
    // Initialize COM for this thread
    if (FAILED(CoInitializeEx(nullptr, COINIT_MULTITHREADED))) {
        return {};
    }

    // Ensure COM is cleaned up at scope exit
    iware::detail::quickscope_wrapper com_cleanup{CoUninitialize};

    // Secure COM communication
    if (FAILED(CoInitializeSecurity(nullptr, -1, nullptr, nullptr,
                                    RPC_C_AUTHN_LEVEL_DEFAULT,
                                    RPC_C_IMP_LEVEL_IMPERSONATE,
                                    nullptr, EOAC_NONE, nullptr))) {
        return {};
    }

    // Create WMI locator instance
    IWbemLocator* pLocator = nullptr;
    if (FAILED(CoCreateInstance(CLSID_WbemLocator, nullptr,
                                CLSCTX_INPROC_SERVER, IID_IWbemLocator,
                                reinterpret_cast<void**>(&pLocator)))) {
        return {};
    }
    std::unique_ptr<IWbemLocator, iware::detail::release_deleter> spLocator(pLocator);

    // Connect to WMI namespace
    IWbemServices* pServices = nullptr;
    const auto bstrNamespace = narrow_to_wide("ROOT\\CIMV2");
    if (FAILED(spLocator->ConnectServer(bstrNamespace.c_str(), nullptr, nullptr, 0,
                                        0, 0, 0, &pServices))) {
        return {};
    }
    std::unique_ptr<IWbemServices, iware::detail::release_deleter> spServices(pServices);

    // Set security blanket for proxy
    if (FAILED(CoSetProxyBlanket(spServices.get(), RPC_C_AUTHN_WINNT,
                                 RPC_C_AUTHZ_NONE, nullptr,
                                 RPC_C_AUTHN_LEVEL_CALL,
                                 RPC_C_IMP_LEVEL_IMPERSONATE,
                                 nullptr, EOAC_NONE))) {
        return {};
    }

    // Execute WQL query
    IEnumWbemClassObject* pEnum = nullptr;
    const auto bstrQueryLang = narrow_to_wide("WQL");
    const auto bstrQueryStmt = narrow_to_wide("SELECT Name FROM Win32_OperatingSystem");
    if (FAILED(spServices->ExecQuery(bstrQueryLang.c_str(), bstrQueryStmt.c_str(),
                                     WBEM_FLAG_FORWARD_ONLY | WBEM_FLAG_RETURN_IMMEDIATELY,
                                     nullptr, &pEnum))) {
        return {};
    }
    std::unique_ptr<IEnumWbemClassObject, iware::detail::release_deleter> spEnum(pEnum);

    // Iterate results (expecting exactly one row)
    std::string osName;
    while (spEnum) {
        IWbemClassObject* pObj = nullptr;
        ULONG uCount = 0;
        const HRESULT hr = spEnum->Next(WBEM_INFINITE, 1, &pObj, &uCount);
        if (FAILED(hr) || uCount == 0) break;

        std::unique_ptr<IWbemClassObject, iware::detail::release_deleter> spObj(pObj);

        VARIANT vName;
        VariantInit(&vName);
        iware::detail::quickscope_wrapper variant_guard{[&] { VariantClear(&vName); }};

        if (SUCCEEDED(spObj->Get(L"Name", 0, &vName, nullptr, nullptr)) &&
            vName.vt == VT_BSTR) {
            osName = wide_to_narrow(vName.bstrVal);
            break;
        }
    }

    // Strip version suffix after first pipe (e.g., "Microsoft® Windows Server® 2022 Standard|...")
    if (!osName.empty()) {
        const auto pos = osName.find('|');
        if (pos != std::string::npos) {
            osName.erase(pos);
        }
    }

    return osName;
}

iware::system::OS_info_t iware::system::OS_info() {
    const auto kernel_info = iware::system::kernel_info();
    return {"Windows NT",
            fetch_windows_os_name(),
            kernel_info.major,
            kernel_info.minor,
            kernel_info.patch,
            kernel_info.build_number};
}

