PYBIND11_MODULE(utils_serialization, m) {
  // Helper lambda to extract real and imaginary parts into a list
  m.def(
      "complex_to_list",
      [](const std::complex<double>& c) -> json {
        return json{{"real", c.real()}, {"imag", c.imag()}};
      },
      "Convert complex number to serializable JSON object with 'real' and 'imag' keys.");

  // Helper lambda to reconstruct complex number from JSON object
  m.def(
      "list_to_complex",
      [](const json& j) -> std::complex<double> {
        double re = j.at("real").get<double>();
        double im = j.at("imag").get<double>();
        return std::complex<double>(re, im);
      },
      "Reconstruct complex number from JSON object produced by `complex_to_list`.");
}

