void HouseTypeExt::ExtData::InitializeConstants() {
    auto pOwner = this->OwnerObject();
    const char* countryID = pOwner->ID;

    static const std::vector<std::string> countryNames = {
        "Americans", "Alliance", "French", "Germans", "British", "Africans",
        "Arabs", "Confederation", "Russians", "YuriCountry"
    };

    int countryIdx = -1;
    for (size_t i = 0; i < countryNames.size(); ++i) {
        if (!_strcmpi(countryID, countryNames[i].c_str())) {
            countryIdx = static_cast<int>(i);
            break;
        }
    }

    static const auto& defaults = BuildCountryDefaults();

    const char* flagFile = nullptr;
    const char* loadScreenBrief = nullptr;
    const char* loadScreenBackground = nullptr;
    const char* loadScreenName = nullptr;
    const char* loadScreenPalette = nullptr;
    const char* loadScreenSpecialName = nullptr;
    const char* statusText = nullptr;
    const char* tauntFile = nullptr;
    const char* observerBgSHP = nullptr;
    const char* observerFlagSHP = nullptr;
    bool observerFlagYuriPAL = false;

    if (countryIdx >= 0 && countryIdx < static_cast<int>(defaults.size())) {
        const auto& def = defaults[countryIdx];
        flagFile = def.FlagFile;
        loadScreenBrief = def.LoadScreenBrief;
        loadScreenBackground = def.LoadScreenBackground;
        loadScreenName = def.LoadScreenName;
        loadScreenPalette = def.LoadScreenPalette;
        loadScreenSpecialName = def.LoadScreenSpecialName;
        statusText = def.StatusText;
        tauntFile = def.TauntFile;
        observerBgSHP = def.ObserverBackgroundSHP;
        observerFlagSHP = def.ObserverFlagSHP;
        observerFlagYuriPAL = def.ObserverFlagYuriPAL;
    } else {
        // Unknown fallback
        flagFile = "rani.pcx";
        loadScreenBrief = "GUI:Unknown";
        loadScreenBackground = "ls%sobs.shp";
        loadScreenName = "GUI:Unknown";
        loadScreenPalette = "mplsobs.pal";
        loadScreenSpecialName = "GUI:Unknown";
        statusText = "GUI:Unknown";
        tauntFile = "taunts\\tauam%02i.wav";
    }

    this->FlagFile = flagFile;
    this->LoadScreenBrief = loadScreenBrief;
    this->LoadScreenBackground = loadScreenBackground;
    this->LoadScreenName = loadScreenName;
    this->LoadScreenPalette = loadScreenPalette;
    this->LoadScreenSpecialName = loadScreenSpecialName;
    this->StatusText = statusText;
    this->TauntFile = tauntFile;

    if (observerBgSHP) {
        this->ObserverBackgroundSHP = FileSystem::LoadSHPFile(observerBgSHP);
    }
    if (observerFlagSHP) {
        this->ObserverFlagSHP = FileSystem::LoadSHPFile(observerFlagSHP);
    }
    this->ObserverFlagYuriPAL = observerFlagYuriPAL;
}

