#include <vector>
#include <algorithm>

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode *left;
    TreeNode *right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
};

class Solution {
public:
    // Helper function to build the tree recursively using preorder and postorder traversals
    TreeNode* buildTree(const std::vector<int>& preorder, int preIndex,
                        const std::vector<int>& postorder, int start, int end) {
        // Base case: no elements to construct the tree
        if (start > end) {
            return nullptr;
        }

        // Root value is the last element in current postorder segment
        TreeNode* newNode = new TreeNode(postorder[end]);

        // If only one node in this subtree, return it
        if (start == end) {
            return newNode;
        }

        // Find the index of the next root (preorder[preIndex + 1]) in the postorder array
        int leftSubtreeRootValue = preorder[preIndex + 1];
        auto it = std::find(postorder.begin() + start, postorder.begin() + end, leftSubtreeRootValue);
        int leftSubtreeLastIndex = std::distance(postorder.begin(), it);

        // Recursively build left and right subtrees
        newNode->left = buildTree(preorder, preIndex + 1, postorder, start, leftSubtreeLastIndex);
        newNode->right = buildTree(preorder, preIndex + leftSubtreeLastIndex - start + 2, 
                                   postorder, leftSubtreeLastIndex + 1, end - 1);

        return newNode;
    }

    TreeNode* constructFromPrePost(std::vector<int>& preorder, std::vector<int>& postorder) {
        int n = postorder.size();
        return buildTree(preorder, 0, postorder, 0, n - 1);
    }
};

