#include "apply_move.hpp"
#include "src/new_tree_rearrangements/check_samples.hpp"
#include "src/new_tree_rearrangements/mutation_annotated_tree.hpp"
#include <algorithm>
#include <cstdio>
#include <tbb/blocked_range.h>
#include <tbb/parallel_for.h>
#include <unordered_set>
#include <vector>

// Adjust child mutation states to remain consistent after parent state changes;
// record any necessary updates in the output list.
void clean_up_src_states(MAT::Node *source_node,
                         std::vector<Altered_Node_t> &update_list) {
    MAT::Mutations_Collection &mut_collection = source_node->mutations;
    State_Change_Collection state_updates;

    for (auto &mutation : mut_collection) {
        nuc_one_hot expected_state =
            mutation.get_par_one_hot() & mutation.get_all_major_allele();
        nuc_one_hot current_state = mutation.get_mut_one_hot();

        // Update if new expected state is valid and differs from current
        if (expected_state && current_state != expected_state) {
            source_node->changed = true;
            mutation.set_mut_one_hot(expected_state);
            state_updates.emplace_back(mutation, current_state);
        }
    }

    // Remove mutations that are now redundant: major allele matches parent,
    // and no sensitive alleles remain (i.e., boundary1 is unset).
    auto is_irrelevant = [](const MAT::Mutation &m) {
        return (m.get_par_one_hot() == m.get_all_major_allele()) &&
               (!m.get_boundary1_one_hot());
    };

    auto begin = mut_collection.mutations.begin();
    auto end = mut_collection.mutations.end();
    mut_collection.mutations.erase(
        std::remove_if(begin, end, is_irrelevant), end);

    if (!state_updates.empty()) {
        update_list.emplace_back(source_node);
        update_list.back().changed_states = std::move(state_updates);
    }
}

#ifdef CHECK_STATE_REASSIGN
void compare_mutations(MAT::Node *old_node, MAT::Node *new_node) {
    const auto &old_mut_vec = old_node->mutations;
    const auto &new_mut_vec = new_node->mutations;

    for (size_t idx = 0; idx < old_mut_vec.size(); ++idx) {
        if (!(old_mut_vec[idx] == new_mut_vec[idx])) {
            fprintf(stderr, "%zu\n", idx);
            assert(false);
        }
        assert(old_mut_vec[idx] == new_mut_vec[idx]);

        if (old_node->children.size() == 2) {
            assert(old_mut_vec[idx].get_left_child_state() ==
                   new_mut_vec[idx].get_left_child_state());
            assert(old_mut_vec[idx].get_right_child_state() ==
                   new_mut_vec[idx].get_right_child_state());
        }
    }
}
#endif

void check_major_state(MAT::Node *node, const MAT::Tree &new_tree);

// Utility function used during debugging — locate an altered node by identifier.
const Altered_Node_t* find_altered_node(char* node_id,
                                        const std::vector<Altered_Node_t>& candidates) {
    for (const auto& candidate : candidates) {
        if (candidate.altered_node->identifier == node_id) {
            return &candidate;
        }
    }
    return nullptr;
}

#ifdef CHECK_STATE_REASSIGN
void compare_mutation_tree(MAT::Tree &original_tree, MAT::Tree &revised_tree) {
    auto old_nodes = original_tree.breadth_first_expansion();
    auto new_nodes = revised_tree.breadth_first_expansion();

    for (int i = static_cast<int>(old_nodes.size()) - 1; i >= 0; --i) {
        compare_mutations(old_nodes[i], new_nodes[i]);
    }
    revised_tree.delete_nodes();
}
#endif

/**
 * @brief Apply all non-conflicting moves to the tree.
 * @param all_moves List of moves to apply.
 * @param t Tree being modified.
 * @param bfs_ordered_nodes Nodes in BFS order (unused here, kept for interface).
 * @param to_filter Nodes to consider in next round (filtered in-place).
 */
void apply_moves(std::vector<Profitable_Moves_ptr_t> &all_moves,
                 MAT::Tree &t,
                 std::vector<MAT::Node *> &bfs_ordered_nodes,
                 tbb::concurrent_vector<MAT::Node *> &to_filter
#ifdef CHECK_STATE_REASSIGN
                 ,
                 const Original_State_t &original_state
#endif
) {
    std::vector<MAT::Node *> nodes_with_altered_topology;     // nodes affected structurally
    std::vector<Altered_Node_t> forward_pass_updates;         // nodes needing state propagation
    std::unordered_set<size_t> removed_node_addresses;        // delayed deletion set
    std::vector<MAT::Node *> nodes_requiring_cleanup;         // src/sibling nodes whose parent changed

#ifdef CHECK_STATE_REASSIGN
    /*std::unordered_set<std::string> samples_to_verify;
    for(const auto& s:original_state){
        samples_to_verify.insert(s.first);
    }*/
#ifndef SINGLE_THREAD_TEST
    FILE* log_file = fopen("moves", "w");
#endif
#endif

    for (const auto &mv : all_moves) {
        // Skip moves involving already-deleted endpoints or self-loops
        if (removed_node_addresses.count((size_t)mv->src) ||
            removed_node_addresses.count((size_t)mv->get_dst()) ||
            mv->src->parent == mv->get_dst()) {
            continue;
        }

#ifdef CHECK_STATE_REASSIGN
#ifdef SINGLE_THREAD_TEST
        fprintf(stderr, "%s\tto\t%s\n",
                mv->src->identifier.c_str(),
                mv->get_dst()->identifier.c_str());
#else
        fprintf(log_file, "%s\tto\t%s\n",
                mv->src->identifier.c_str(),
                mv->get_dst()->identifier.c_str());
        fflush(log_file);
#endif
#endif

        // Perform move while preserving internal node states temporarily
        move_node(mv->src, mv->get_dst(), nodes_with_altered_topology, t,
                  removed_node_addresses, nodes_requiring_cleanup);
        delete mv;
    }

    // Re-traverse in DFS order for correct Fitch/Sankoff propagation
    std::vector<MAT::Node*> dfs_order = t.depth_first_expansion();

    // Filter out deleted nodes from structural updates
    auto filter_deleted = [&removed_node_addresses](MAT::Node *n) {
        return removed_node_addresses.count((size_t)n) != 0;
    };

    auto topo_end = std::remove_if(nodes_with_altered_topology.begin(),
                                   nodes_with_altered_topology.end(),
                                   filter_deleted);
    nodes_with_altered_topology.erase(topo_end, nodes_with_altered_topology.end());

    auto cleanup_end = std::remove_if(nodes_requiring_cleanup.begin(),
                                      nodes_requiring_cleanup.end(),
                                      filter_deleted);
    nodes_requiring_cleanup.erase(cleanup_end, nodes_requiring_cleanup.end());

#ifdef CHECK_STATE_REASSIGN
    // For validation: reconstruct tree with updated states
    // MAT::Tree reconstructed_tree;
    // reconstructed_tree.load_detatiled_mutations("After_reassign.pb");
    MAT::Tree reconstructed_tree = reassign_state_full(t);
    reconstructed_tree.save_detailed_mutations("After_reassign.pb");
#endif

    // Backward pass: propagate major allele updates
    if (!nodes_with_altered_topology.empty()) {
        reassign_backward_pass(nodes_with_altered_topology, forward_pass_updates
#ifdef CHECK_STATE_REASSIGN
                               ,
                               reconstructed_tree
#endif
        );
    }

    // Clean up source nodes whose parent may have changed due to condensation
    for (auto *node : nodes_requiring_cleanup) {
        clean_up_src_states(node, forward_pass_updates);
    }

    // Forward pass: enforce consistency from parent → child states
    if (!forward_pass_updates.empty()) {
        forward_pass(forward_pass_updates
#ifdef CHECK_STATE_REASSIGN
                     ,
                     reconstructed_tree
#endif
        );
    }

#ifdef CHECK_STATE_REASSIGN
    compare_mutation_tree(t, reconstructed_tree);
#endif

    // Update `to_filter` by excluding deleted nodes
    tbb::concurrent_vector<MAT::Node*> remaining_nodes;
    remaining_nodes.reserve(to_filter.size());
    for (const auto *node : to_filter) {
        if (!removed_node_addresses.count((size_t)node)) {
            remaining_nodes.push_back(const_cast<MAT::Node*>(node));
        }
    }
    to_filter.swap(remaining_nodes);

    // Final cleanup: delete nodes marked for removal
    for (auto addr : removed_node_addresses) {
        MAT::Node *del_node = reinterpret_cast<MAT::Node*>(addr);
        t.all_nodes.erase(del_node->identifier);
        delete del_node;
    }

#ifdef CHECK_STATE_REASSIGN
#ifndef SINGLE_THREAD_TEST
    fclose(log_file);
#endif
#endif
}

