namespace openspace {

Dashboard::Dashboard()
    : properties::PropertyOwner({ "Dashboard" })
    , _isVisible(VisibilityInfo, true)
    , _offsetFromOrigin(
        properties::IVec2Property(OffsetFromOriginInfo, glm::ivec2(10, -10))
    )
{
    addProperty(_isVisible);
    addProperty(_offsetFromOrigin);
}

void Dashboard::appendDashboardComponent(std::unique_ptr<DashboardItem> component) {
    const std::string& baseName = component->identifier();
    int counter = 1;

    do {
        bool foundDuplicate = false;
        for (const auto& existing : dashboardComponents) {
            if (existing->identifier() == component->identifier()) {
                foundDuplicate = true;
                break;
            }
        }

        if (!foundDuplicate) {
            break;
        }

        component->setIdentifier(baseName + "_" + std::to_string(counter));
        component->setGuiName(baseName + " (" + std::to_string(counter) + ")");
        ++counter;
    } while (true);

    addPropertySubOwner(component.get());
    dashboardComponents.push_back(std::move(component));
}

void Dashboard::eraseDashboardComponent(int position) {
    ghoul_assert(position >= 0 && position < static_cast<int>(dashboardComponents.size()),
                 "Index out of bounds");
    removePropertySubOwner(dashboardComponents[position].get());
    dashboardComponents.erase(dashboardComponents.begin() + position);
}

void Dashboard::eraseDashboardComponent(const std::string& tag) {
    auto iter = dashboardComponents.begin();
    for (; iter != dashboardComponents.end(); ++iter) {
        if ((*iter)->identifier() == tag) {
            break;
        }
    }

    if (iter == dashboardComponents.end()) {
        return;
    }

    removePropertySubOwner(iter->get());
    dashboardComponents.erase(iter);
}

bool Dashboard::containsComponent(int index) const {
    return (index >= 0) && (index < static_cast<int>(dashboardComponents.size()));
}

const DashboardItem& Dashboard::componentAt(int index) const {
    ghoul_assert(index >= 0 && index < static_cast<int>(dashboardComponents.size()),
                 "Invalid index");
    return *dashboardComponents[index];
}

void Dashboard::removeAllComponents() {
    for (auto& comp : dashboardComponents) {
        removePropertySubOwner(comp.get());
    }
    dashboardComponents.clear();
}

void Dashboard::draw(glm::vec2& cursor) {
    if (!_isVisible) {
        return;
    }

    for (const auto& comp : dashboardComponents) {
        if (comp->isVisible()) {
            comp->draw(cursor);
        }
    }
}

glm::vec2 Dashboard::screenOffset() {
    return _offsetFromOrigin.value();
}

