int main(int argc, char* argv[]) {
    int count = 1000000;
    float* buffer_data = static_cast<float*>(::malloc(count * 4 * sizeof(float) + 16));
    float* hsv_buffer = static_cast<float*>(::malloc(count * 4 * sizeof(float) + 16));

    float* aligned_argb = SimdUtils::align(buffer_data, 16);
    float* aligned_ahsv = SimdUtils::align(hsv_buffer, 16);

    rgbhsv_fill(aligned_argb, count);
    rgbhsv_check("ref" , ahsv_from_argb_ref , argb_from_ahsv_ref , aligned_argb, count);

    rgbhsv_fill(aligned_argb, count);
    rgbhsv_check("sse2", ahsv_from_argb_sse2, argb_from_ahsv_sse2, aligned_argb, count);

    rgbhsv_bench("ref" , ahsv_from_argb_ref , argb_from_ahsv_ref , aligned_argb, aligned_ahsv, count);
    rgbhsv_bench("sse2", ahsv_from_argb_sse2, argb_from_ahsv_sse2, aligned_argb, aligned_ahsv, count);

    ::free(buffer_data);
    ::free(hsv_buffer);

    return 0;
}

