using json = nlohmann::json;
using QuatDatum = glm::quat;

// Convert JSON array to quaternion; default to identity if invalid
QuatDatum quat_from_json(const json& input) {
    QuatDatum result(1.0f, 0.0f, 0.0f, 0.0f);
    if (input.is_array() && input.size() == 4) {
        result.w = static_cast<float>(input[0]);
        result.x = static_cast<float>(input[1]);
        result.y = static_cast<float>(input[2]);
        result.z = static_cast<float>(input[3]);
    }
    return result;
}

// Serialize quaternion to JSON array [w, x, y, z]
json quat_to_json(const QuatDatum& q) {
    json arr = json::array();
    arr.push_back(q.w);
    arr.push_back(q.x);
    arr.push_back(q.y);
    arr.push_back(q.z);
    return arr;
}

// Generate a random unit quaternion with fixed angle ~π/2
QuatDatum generate_random_quat() {
    constexpr float ROTATION_ANGLE = 1.57f; // ≈ π/2 radians
    glm::vec3 axis = RandomUtil::unitSphereSurface();
    return glm::angleAxis(ROTATION_ANGLE, axis);
}

// Check if two quaternions represent approximately the same rotation
bool quats_are_similar(const QuatDatum& first, const QuatDatum& second) {
    constexpr float DOT_TOLERANCE = 8.0e-7f; // ~0.1 degrees angular error
    float dot_val = std::abs(glm::dot(first, second));
    return std::abs(1.0f - dot_val) < DOT_TOLERANCE;
}

class TestConfiguration : public ConfigUtil::ConfigInterface {
public:
    TestConfiguration() = default;
    ~TestConfiguration() = default;

    // Required override: serialize internal state to JSON
    nlohmann::json getJson() const override {
        std::unique_lock<std::mutex> guard(_mutex);
        json output;
        output["label"] = _label;
        output["value"] = _value;
        json items = json::array();
        for (const auto& item : _items) {
            items.push_back(quat_to_json(item));
        }
        output["items"] = items;
        return output;
    }

    // Required override: deserialize JSON into internal state
    void updateJson(const nlohmann::json& input) override {
        std::unique_lock<std::mutex> guard(_mutex);
        bool modified = false;

        if (input.contains("label") && input["label"].is_string()) {
            _label = input["label"];
            modified = true;
        }

        if (input.contains("value") && input["value"].is_number_integer()) {
            _value = input["value"];
            modified = true;
        }

        if (input.contains("items") && input["items"].is_array()) {
            _items.clear();
            const auto& arr = input["items"];
            _items.reserve(arr.size());
            for (const auto& elem : arr) {
                _items.emplace_back(quat_from_json(elem));
            }
            modified = true;
        }

        if (modified) {
            incrementVersion();
        }
    }

    // Set label string
    void setLabel(const std::string& label) {
        std::unique_lock<std::mutex> guard(_mutex);
        if (_label != label) {
            _label = label;
            incrementVersion();
        }
    }

    // Set numeric value
    void setValue(int32_t val) {
        std::unique_lock<std::mutex> guard(_mutex);
        if (_value != val) {
            _value = val;
            incrementVersion();
        }
    }

    // Replace entire item list
    void setItems(const std::vector<QuatDatum>& new_items) {
        std::unique_lock<std::mutex> guard(_mutex);
        bool changed = false;
        size_t count = new_items.size();

        if (count != _items.size()) {
            _items.clear();
            changed = true;
        }

        _items.resize(count);
        for (size_t idx = 0; idx < count; ++idx) {
            if (_items[idx] != new_items[idx]) {
                _items[idx] = new_items[idx];
                changed = true;
            }
        }

        if (changed) {
            incrementVersion();
        }
    }

    // Equality comparison (ignoring version)
    bool operator==(const TestConfiguration& rhs) const {
        std::unique_lock<std::mutex> guard(_mutex);
        if (_label != rhs._label || _value != rhs._value || _items.size() != rhs._items.size()) {
            return false;
        }

        for (size_t i = 0; i < _items.size(); ++i) {
            if (!quats_are_similar(_items[i], rhs._items[i])) {
                return false;
            }
        }

        return true;
    }

private:
    std::string _label;
    int32_t _value{0};
    std::vector<QuatDatum> _items;
};

TEST(ConfigUtil_test, read_write) {
    constexpr size_t ITEM_COUNT = 16;
    std::vector<QuatDatum> items;
    items.reserve(ITEM_COUNT);

    for (size_t k = 0; k < ITEM_COUNT; ++k) {
        items.push_back(generate_random_quat());
    }

    TestConfiguration cfg1;
    cfg1.setLabel("alpha");
    cfg1.setValue(42);
    cfg1.setItems(items);

    TestConfiguration cfg2;
    EXPECT_FALSE(cfg1 == cfg2);
    EXPECT_FALSE(cfg2 == cfg1);

    // Sync via JSON
    json serialized = cfg1.getJson();
    cfg2.updateJson(serialized);
    EXPECT_TRUE(cfg1 == cfg2);
    EXPECT_TRUE(cfg2 == cfg1);

    // Modify cfg1 and verify inequality
    cfg1.setLabel("beta");
    EXPECT_FALSE(cfg1 == cfg2);

    // Sync via file I/O
    std::string path = fmt::format("/tmp/test_ConfigUtil-{:08x}.json", RandomUtil::uint32());
    cfg1.setFilename(path);
    bool wrote_ok = cfg1.writeFile();
    EXPECT_TRUE(wrote_ok);

    TestConfiguration cfg3;
    cfg3.setFilename(path);
    bool loaded_ok = cfg3.readFileIfChanged();
    EXPECT_TRUE(loaded_ok);
    EXPECT_TRUE(cfg1 == cfg3);

    bool removed_ok = std::filesystem::remove(path);
    EXPECT_TRUE(removed_ok);
}

