void TopologyHandler::ApplyTopologyChanges(const std::list<const core::topology::TopologyChange *>& events, const unsigned int size)
{
    // Early exit if no topology data is registered
    if (!this->isTopologyDataRegistered())
        return;

    // Copy event list to local storage (same semantics as original)
    std::list<const core::topology::TopologyChange *> changes = events;

    // Ensure data array matches current topology size
    this->setDataSetArraySize(size);

    // Iterate over each topology change event
    auto iter = changes.begin();
    while (iter != changes.end())
    {
        const core::topology::TopologyChange* change = *iter;
        const core::topology::TopologyChangeType type = change->getChangeType();

        // Dispatch based on change type using same macro expansion
        switch (type)
        {
#define SOFA_DISPATCH_EVENT(name, type) \
        case core::topology::name: \
            this->ApplyTopologyChange(static_cast<const type*>(change)); \
            break

            SOFA_DISPATCH_EVENT(ENDING_EVENT, EndingEvent);
            SOFA_DISPATCH_EVENT(POINTSINDICESSWAP, PointsIndicesSwap);
            SOFA_DISPATCH_EVENT(POINTSADDED, PointsAdded);
            SOFA_DISPATCH_EVENT(POINTSREMOVED, PointsRemoved);
            SOFA_DISPATCH_EVENT(POINTSMOVED, PointsMoved);
            SOFA_DISPATCH_EVENT(POINTSRENUMBERING, PointsRenumbering);
            SOFA_DISPATCH_EVENT(EDGESINDICESSWAP, EdgesIndicesSwap);
            SOFA_DISPATCH_EVENT(EDGESADDED, EdgesAdded);
            SOFA_DISPATCH_EVENT(EDGESREMOVED, EdgesRemoved);
            SOFA_DISPATCH_EVENT(EDGESMOVED_REMOVING, EdgesMoved_Removing);
            SOFA_DISPATCH_EVENT(EDGESMOVED_ADDING, EdgesMoved_Adding);
            SOFA_DISPATCH_EVENT(EDGESRENUMBERING, EdgesRenumbering);
            SOFA_DISPATCH_EVENT(TRIANGLESINDICESSWAP, TrianglesIndicesSwap);
            SOFA_DISPATCH_EVENT(TRIANGLESADDED, TrianglesAdded);
            SOFA_DISPATCH_EVENT(TRIANGLESREMOVED, TrianglesRemoved);
            SOFA_DISPATCH_EVENT(TRIANGLESMOVED_REMOVING, TrianglesMoved_Removing);
            SOFA_DISPATCH_EVENT(TRIANGLESMOVED_ADDING, TrianglesMoved_Adding);
            SOFA_DISPATCH_EVENT(TRIANGLESRENUMBERING, TrianglesRenumbering);
            SOFA_DISPATCH_EVENT(TETRAHEDRAINDICESSWAP, TetrahedraIndicesSwap);
            SOFA_DISPATCH_EVENT(TETRAHEDRAADDED, TetrahedraAdded);
            SOFA_DISPATCH_EVENT(TETRAHEDRAREMOVED, TetrahedraRemoved);
            SOFA_DISPATCH_EVENT(TETRAHEDRAMOVED_REMOVING, TetrahedraMoved_Removing);
            SOFA_DISPATCH_EVENT(TETRAHEDRAMOVED_ADDING, TetrahedraMoved_Adding);
            SOFA_DISPATCH_EVENT(TETRAHEDRARENUMBERING, TetrahedraRenumbering);
            SOFA_DISPATCH_EVENT(QUADSINDICESSWAP, QuadsIndicesSwap);
            SOFA_DISPATCH_EVENT(QUADSADDED, QuadsAdded);
            SOFA_DISPATCH_EVENT(QUADSREMOVED, QuadsRemoved);
            SOFA_DISPATCH_EVENT(QUADSMOVED_REMOVING, QuadsMoved_Removing);
            SOFA_DISPATCH_EVENT(QUADSMOVED_ADDING, QuadsMoved_Adding);
            SOFA_DISPATCH_EVENT(QUADSRENUMBERING, QuadsRenumbering);
            SOFA_DISPATCH_EVENT(HEXAHEDRAINDICESSWAP, HexahedraIndicesSwap);
            SOFA_DISPATCH_EVENT(HEXAHEDRAADDED, HexahedraAdded);
            SOFA_DISPATCH_EVENT(HEXAHEDRAREMOVED, HexahedraRemoved);
            SOFA_DISPATCH_EVENT(HEXAHEDRAMOVED_REMOVING, HexahedraMoved_Removing);
            SOFA_DISPATCH_EVENT(HEXAHEDRAMOVED_ADDING, HexahedraMoved_Adding);
            SOFA_DISPATCH_EVENT(HEXAHEDRARENUMBERING, HexahedraRenumbering);

#undef SOFA_DISPATCH_EVENT

        default:
            // No action for unknown change types
            break;
        }

        ++iter;  // Explicit increment in while loop
    }
}

