#include "RandomWordIterator.h"

// Initialize random distribution if dictionary size has changed
void RandomWordIterator::initRandom()
{
    if (lastSize != dict.Size()) // Check if dictionary size has been modified
    {
        dist.reset(new std::uniform_int_distribution<size_t>(0, dict.Size() - 1));
        lastSize = dict.Size();
    }
}

// Get next valid word that satisfies the predicate
std::string RandomWordIterator::Next()
{
    if (!HasNext())
    {
        return "";
    }

    initRandom();

    std::string candidate;
    do
    {
        size_t index = (*dist)(engine);
        candidate = dict[index];
    }
    while (!pred(candidate));

    return candidate;
}

// Check if there exists at least one word satisfying the predicate
bool RandomWordIterator::HasNext()
{
    bool exists = false;
    for (size_t idx = 0; idx < dict.Size(); ++idx)
    {
        if (pred(dict[idx]))
        {
            exists = true;
            break;
        }
    }
    return exists;
}

