#define DEBUG_TYPE "stack-promotion"

STATISTIC(NumObjectsOnStack, "Number of heap allocations moved to stack storage");

using namespace swift;

namespace {

/// Transforms heap-allocated class instances into stack-based ones when safe.
///
/// For eligible alloc_ref instructions on native Swift types:
/// - Marks them with [stack] attribute.
/// - Inserts corresponding dealloc_ref [stack] at end of lifetime.
class StackAllocator : public SILFunctionTransform {
public:
  StackAllocator() = default;

private:
  void run() override;
  bool processBasicBlock(SILBasicBlock *BB, EscapeAnalysis *EA, DeadEndBlocks &DEBs);
  bool attemptPromotion(AllocRefInst *ARI, EscapeAnalysis *EA, DeadEndBlocks &DEBs);
};

void StackAllocator::run() {
  auto *func = getFunction();
  DEBUG(llvm::dbgs() << "** StackAllocator processing " << func->getName() << " **\n");

  auto *escapeAnalysis = PM->getAnalysis<EscapeAnalysis>();
  DeadEndBlocks deadEndBlocks(func);
  bool modified = false;

  for (auto &block : *func) {
    modified |= processBasicBlock(&block, escapeAnalysis, deadEndBlocks);
  }

  if (!modified)
    return;

  StackNesting stackNester;
  switch (stackNester.correctStackNesting(func)) {
    case StackNesting::Changes::CFG:
      invalidateAnalysis(SILAnalysis::InvalidationKind::BranchesAndInstructions);
      break;
    default:
      invalidateAnalysis(SILAnalysis::InvalidationKind::Instructions);
      break;
  }
}

bool StackAllocator::processBasicBlock(SILBasicBlock *BB, EscapeAnalysis *EA,
                                       DeadEndBlocks &DEBs) {
  bool changed = false;
  auto iter = BB->begin();

  while (iter != BB->end()) {
    auto *inst = &*iter++;
    if (auto *alloc = dyn_cast<AllocRefInst>(inst)) {
      // Skip promotion in unreachable/dead-end regions to avoid premature deallocation.
      if (DEBs.isDeadEnd(BB))
        continue;

      changed |= attemptPromotion(alloc, EA, DEBs);
    }
  }

  return changed;
}

bool StackAllocator::attemptPromotion(AllocRefInst *ARI, EscapeAnalysis *EA,
                                      DeadEndBlocks &DEBs) {
  // Skip Objective-C or already stack-allocatable references.
  if (ARI->isObjC() || ARI->canAllocOnStack())
    return false;

  auto *connGraph = EA->getConnectionGraph(ARI->getFunction());
  auto *node = connGraph->getNodeOrNull(ARI, EA);
  if (!node)
    return false;

  // Must not escape current function scope.
  if (node->escapes())
    return false;

  DEBUG(llvm::dbgs() << "Promoting: " << *ARI);

  // Gather all use points: refcount ops and apply sites.
  llvm::SmallVector<ValueBase *, 8> rawUsePoints;
  connGraph->getUsePoints(node, rawUsePoints);

  llvm::SmallVector<SILInstruction *, 8> useInstrs;
  for (ValueBase *vp : rawUsePoints) {
    if (auto *ip = dyn_cast<SILInstruction>(vp)) {
      useInstrs.push_back(ip);
    } else {
      auto *phiArg = cast<SILPHIArgument>(vp);
      useInstrs.push_back(&phiArg->getParent()->front());
    }
  }

  ValueLifetimeAnalysis vla(ARI, useInstrs);

  // Ensure object isn’t used before its allocation point.
  auto *entryBB = ARI->getFunction()->getEntryBlock();
  if (vla.isAliveAtBeginOfBlock(entryBB)) {
    DEBUG(llvm::dbgs() << "  Use precedes allocation — skipping promotion");
    return false;
  }

  ValueLifetimeAnalysis::Frontier frontier;
  if (!vla.computeFrontier(frontier, ValueLifetimeAnalysis::UsersMustPostDomDef, &DEBs)) {
    DEBUG(llvm::dbgs() << "  Uses do not post-dominate def — skipping promotion");
    return false;
  }

  ++NumObjectsOnStack;
  ARI->setStackAllocatable();

  // Insert final deallocation at each frontier point.
  for (SILInstruction *fi : frontier) {
    SILBuilder builder(fi);
    builder.createDeallocRef(ARI->getLoc(), ARI, true);
  }

  return true;
}

} // anonymous namespace

SILTransform *swift::createStackPromotion() {
  return new StackAllocator();
}

