MobileManipulatorInterface::MobileManipulatorInterface(const std::string& taskFile, const std::string& libFolder,
                                                       const std::string& robotModelFile) {
  // Validate task file path
  boost::filesystem::path taskPath(taskFile);
  if (!boost::filesystem::exists(taskPath)) {
    throw std::invalid_argument("[MobileManipulatorInterface] Task file not found: " + taskPath.string());
  }
  std::cerr << "[MobileManipulatorInterface] Loading task file: " << taskPath << std::endl;

  // Validate URDF path
  boost::filesystem::path urdfPath(robotModelFile);
  if (!boost::filesystem::exists(urdfPath)) {
    throw std::invalid_argument("[MobileManipulatorInterface] URDF file not found: " + urdfPath.string());
  }
  std::cerr << "[MobileManipulatorInterface] Loading Pinocchio model from: " << urdfPath << std::endl;

  // Ensure library directory exists
  boost::filesystem::path libPath(libFolder);
  boost::filesystem::create_directories(libPath);
  std::cerr << "[MobileManipulatorInterface] Generated library path: " << libPath << std::endl;

  // Initialize Pinocchio interface
  pinocchioInterfacePtr_.reset(new PinocchioInterface(buildPinocchioInterface(robotModelFile)));
  std::cerr << *pinocchioInterfacePtr_;

  bool usePreComp = true;
  bool forceRecompile = true;
  boost::property_tree::ptree params;
  boost::property_tree::read_info(taskFile, params);

  std::cerr << "\n #### Model Settings:";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadPtreeValue(params, usePreComp, "model_settings.usePreComputation", true);
  loadData::loadPtreeValue(params, forceRecompile, "model_settings.recompileLibraries", true);
  std::cerr << " #### =============================================================================\n";

  // Load initial state
  loadData::loadEigenMatrix(taskFile, "initialState", initialState_);
  std::cerr << "Initial State:   " << initialState_.transpose() << std::endl;

  // Load DDP & MPC settings
  ddpSettings_ = ddp::loadSettings(taskFile, "ddp");
  mpcSettings_ = mpc::loadSettings(taskFile, "mpc");

  // Setup reference manager
  referenceManagerPtr_.reset(new ReferenceManager);

  /*
   * Build optimal control problem
   */
  // Cost terms
  problem_.costPtr->add("inputCost", getQuadraticInputCost(taskFile));

  // Soft constraints
  problem_.softConstraintPtr->add("jointVelocityLimit", getJointVelocityLimitConstraint(taskFile));
  problem_.stateSoftConstraintPtr->add("selfCollision",
                                       getSelfCollisionConstraint(*pinocchioInterfacePtr_, taskFile, robotModelFile,
                                                                  usePreComp, libFolder, forceRecompile));
  problem_.stateSoftConstraintPtr->add("endEffector",
                                       getEndEffectorConstraint(*pinocchioInterfacePtr_, taskFile, "endEffector",
                                                                usePreComp, libFolder, forceRecompile));
  problem_.finalSoftConstraintPtr->add("finalEndEffector",
                                       getEndEffectorConstraint(*pinocchioInterfacePtr_, taskFile, "finalEndEffector",
                                                                usePreComp, libFolder, forceRecompile));

  // Dynamics
  problem_.dynamicsPtr.reset(new MobileManipulatorDynamics("mobile_manipulator_dynamics", libFolder, forceRecompile, true));

  // Pre-computation module
  if (usePreComp) {
    problem_.preComputationPtr.reset(new MobileManipulatorPreComputation(*pinocchioInterfacePtr_));
  }

  // Rollout configuration
  const auto rolloutParams = rollout::loadSettings(taskFile, "rollout");
  rolloutPtr_.reset(new TimeTriggeredRollout(*problem_.dynamicsPtr, rolloutParams));

  // Initialization strategy
  initializerPtr_.reset(new DefaultInitializer(INPUT_DIM));
}

PinocchioInterface MobileManipulatorInterface::buildPinocchioInterface(const std::string& urdfFile) {
  // Append base joint for planar motion (x, y, theta)
  pinocchio::JointModelComposite baseJoint(3);
  baseJoint.addJoint(pinocchio::JointModelPX());
  baseJoint.addJoint(pinocchio::JointModelPY());
  baseJoint.addJoint(pinocchio::JointModelRZ());
  return getPinocchioInterfaceFromUrdfFile(urdfFile, baseJoint);
}

std::unique_ptr<StateInputCost> MobileManipulatorInterface::getQuadraticInputCost(const std::string& taskFile) {
  matrix_t inputWeight(INPUT_DIM, INPUT_DIM);
  std::cerr << "\n #### Input Cost Settings: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadEigenMatrix(taskFile, "inputCost.R", inputWeight);
  std::cerr << "inputCost.R:  \n" << inputWeight << '\n';
  std::cerr << " #### =============================================================================\n";
  return std::unique_ptr<StateInputCost>(new QuadraticInputCost(std::move(inputWeight)));
}

std::unique_ptr<StateCost> MobileManipulatorInterface::getEndEffectorConstraint(
    const PinocchioInterface& pinocchioInterface, const std::string& taskFile,
    const std::string& prefixName, bool usePreComp, const std::string& libFolder, bool forceRecompile) {
  scalar_t muPos = 1.0;
  scalar_t muOri = 1.0;
  const std::string linkName = "WRIST_2";
  boost::property_tree::ptree cfg;
  boost::property_tree::read_info(taskFile, cfg);

  std::cerr << "\n #### " << prefixName << " Settings: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadPtreeValue(cfg, muPos, prefixName + ".muPosition", true);
  loadData::loadPtreeValue(cfg, muOri, prefixName + ".muOrientation", true);
  std::cerr << " #### =============================================================================\n";

  if (!referenceManagerPtr_) {
    throw std::runtime_error("[getEndEffectorConstraint] referenceManagerPtr_ must be initialized first!");
  }

  std::unique_ptr<StateConstraint> constraintImpl;
  if (usePreComp) {
    MobileManipulatorPinocchioMapping<scalar_t> mapping;
    PinocchioEndEffectorKinematics kinematics(pinocchioInterface, mapping, {linkName});
    constraintImpl.reset(new EndEffectorConstraint(kinematics, *referenceManagerPtr_));
  } else {
    MobileManipulatorPinocchioMapping<ad_scalar_t> adMapping;
    PinocchioEndEffectorKinematicsCppAd adKinematics(pinocchioInterface, adMapping, {linkName},
                                                     STATE_DIM, INPUT_DIM,
                                                     "end_effector_kinematics", libFolder, forceRecompile, false);
    constraintImpl.reset(new EndEffectorConstraint(adKinematics, *referenceManagerPtr_));
  }

  std::vector<std::unique_ptr<PenaltyBase>> penaltyVec(6);
  for (int i = 0; i < 3; ++i) {
    penaltyVec[i].reset(new QuadraticPenalty(muPos));
  }
  for (int i = 3; i < 6; ++i) {
    penaltyVec[i].reset(new QuadraticPenalty(muOri));
  }

  return std::unique_ptr<StateCost>(new StateSoftConstraint(std::move(constraintImpl), std::move(penaltyVec)));
}

std::unique_ptr<StateCost> MobileManipulatorInterface::getSelfCollisionConstraint(
    const PinocchioInterface& pinocchioInterface, const std::string& taskFile,
    const std::string& urdfFile, bool usePreComp, const std::string& libFolder, bool forceRecompile) {
  std::vector<std::pair<size_t, size_t>> collisionIndices;
  std::vector<std::pair<std::string, std::string>> collisionLinks;
  scalar_t barrierMu = 1e-2;
  scalar_t barrierDelta = 1e-3;
  scalar_t minDist = 0.0;

  boost::property_tree::ptree config;
  boost::property_tree::read_info(taskFile, config);
  const std::string section = "selfCollision.";
  std::cerr << "\n #### SelfCollision Settings: ";
  std::cerr << "\n #### =============================================================================\n";
  loadData::loadPtreeValue(config, barrierMu, section + "mu", true);
  loadData::loadPtreeValue(config, barrierDelta, section + "delta", true);
  loadData::loadPtreeValue(config, minDist, section + "minimumDistance", true);
  loadData::loadStdVectorOfPair(taskFile, section + "collisionObjectPairs", collisionIndices, true);
  loadData::loadStdVectorOfPair(taskFile, section + "collisionLinkPairs", collisionLinks, true);
  std::cerr << " #### =============================================================================\n";

  PinocchioGeometryInterface geomInterface(pinocchioInterface, collisionLinks, collisionIndices);
  const size_t numPairs = geomInterface.getNumCollisionPairs();
  std::cerr << "SelfCollision: Checking " << numPairs << " collision pairs\n";

  std::unique_ptr<StateConstraint> constraintImpl;
  if (usePreComp) {
    constraintImpl.reset(new MobileManipulatorSelfCollisionConstraint(
        MobileManipulatorPinocchioMapping<scalar_t>(), std::move(geomInterface), minDist));
  } else {
    constraintImpl.reset(new SelfCollisionConstraintCppAd(
        pinocchioInterface, MobileManipulatorPinocchioMapping<scalar_t>(),
        std::move(geomInterface), minDist, "self_collision", libFolder, forceRecompile, false));
  }

  std::unique_ptr<PenaltyBase> barrier(new RelaxedBarrierPenalty({barrierMu, barrierDelta}));
  return std::unique_ptr<StateCost>(new StateSoftConstraint(std::move(constraintImpl), std::move(barrier)));
}

std::unique_ptr<StateInputCost> MobileManipulatorInterface::getJointVelocityLimitConstraint(const std::string& taskFile) {
  vector_t lowerBound(INPUT_DIM);
  vector_t upperBound(INPUT_DIM);
  scalar_t barrierMu = 1e-2;
  scalar_t barrierDelta = 1e-3;

  boost::property_tree::ptree cfg;
  boost::property_tree::read_info(taskFile, cfg);
  const std::string section = "jointVelocityLimits.";
  std::cerr << "\n #### JointVelocityLimits Settings: ";
  std::cerr << "\n #### =============================================================================\n";

  loadData::loadEigenMatrix(taskFile, "jointVelocityLimits.lowerBound", lowerBound);
  std::cerr << " #### 'lowerBound':  " << lowerBound.transpose() << std::endl;
  loadData::loadEigenMatrix(taskFile, "jointVelocityLimits.upperBound", upperBound);
  std::cerr << " #### 'upperBound':  " << upperBound.transpose() << std::endl;
  loadData::loadPtreeValue(cfg, barrierMu, section + "mu", true);
  loadData::loadPtreeValue(cfg, barrierDelta, section + "delta", true);
  std::cerr << " #### =============================================================================\n";

  std::unique_ptr<StateInputConstraint> constraint(new JointVelocityLimits);
  std::vector<std::unique_ptr<PenaltyBase>> penalties(INPUT_DIM);
  int idx = 0;
  while (idx < INPUT_DIM) {
    auto barrier = std::make_unique<RelaxedBarrierPenalty>({barrierMu, barrierDelta});
    penalties[idx] = std::make_unique<DoubleSidedPenalty>(lowerBound(idx), upperBound(idx), std::move(barrier));
    ++idx;
  }

  return std::unique_ptr<StateInputCost>(new StateInputSoftConstraint(std::move(constraint), std::move(penalties)));
}

