// GLFW error handler
static void OnGlfwError(int errCode, const char* errMsg)
{
    fprintf(stderr, "GLFW Error %d: %s\n", errCode, errMsg);
}

int GuiApplication::start()
{
    // Initialize GLFW with error handling
    glfwSetErrorCallback(OnGlfwError);
    if (!glfwInit())
        return 1;

    // Configure OpenGL context version based on platform
#ifdef __APPLE__
    const char* shaderVersion = "#version 150";
    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 2);
    glfwWindowHint(GLFW_OPENGL_PROFILE, GLFW_OPENGL_CORE_PROFILE);
    glfwWindowHint(GLFW_OPENGL_FORWARD_COMPAT, GL_TRUE);
#else
    const char* shaderVersion = "#version 130";
    glfwWindowHint(GLFW_CONTEXT_VERSION_MAJOR, 3);
    glfwWindowHint(GLFW_CONTEXT_VERSION_MINOR, 0);
#endif

    // Create main window
    m_window = glfwCreateWindow(1280, 720, this->getApplicationName().c_str(), nullptr, nullptr);
    if (!m_window) {
        return 1;
    }

    glfwMakeContextCurrent(m_window);
    glfwSwapInterval(1); // VSync enabled

    // Load OpenGL functions via selected loader
#if defined(IMGUI_IMPL_OPENGL_LOADER_GL3W)
    bool initFailed = gl3wInit() != 0;
#elif defined(IMGUI_IMPL_OPENGL_LOADER_GLEW)
    bool initFailed = glewInit() != GLEW_OK;
#elif defined(IMGUI_IMPL_OPENGL_LOADER_GLAD)
    bool initFailed = gladLoadGL() == 0;
#elif defined(IMGUI_IMPL_OPENGL_LOADER_GLAD2)
    bool initFailed = gladLoadGL(glfwGetProcAddress) == 0;
#elif defined(IMGUI_IMPL_OPENGL_LOADER_GLBINDING2)
    glbinding::Binding::initialize();
    bool initFailed = false;
#elif defined(IMGUI_IMPL_OPENGL_LOADER_GLBINDING3)
    glbinding::initialize([](const char* symbol) -> glbinding::ProcAddress {
        return (glbinding::ProcAddress)glfwGetProcAddress(symbol);
    });
    bool initFailed = false;
#else
    bool initFailed = false; // Custom loader assumed initialized elsewhere
#endif

    if (initFailed) {
        fprintf(stderr, "Failed to initialize OpenGL loader!\n");
        return 1;
    }

    // Enable debug output if requested
    if (m_useGlDebug) {
        glEnable(GL_DEBUG_OUTPUT);
        glDebugMessageCallback(GlDebugCallback, nullptr);
    }

    // Initialize Dear ImGui
    IMGUI_CHECKVERSION();
    ImGui::CreateContext();
    ImGuiIO& io = ImGui::GetIO();

    ImGui::StyleColorsDark();
    ImGui_ImplGlfw_InitForOpenGL(m_window, true);
    ImGui_ImplOpenGL3_Init(shaderVersion);

    ImVec4 bgColor = ImVec4(0.45f, 0.55f, 0.60f, 1.00f);

    // Setup fonts and user-defined initialization
    this->configureFonts();
    this->initialize();

    // Main rendering loop
    while (!glfwWindowShouldClose(m_window)) {
        glfwPollEvents();

        int fbWidth, fbHeight;
        glfwGetFramebufferSize(m_window, &fbWidth, &fbHeight);
        glViewport(0, 0, fbWidth, fbHeight);
        glClearColor(bgColor.x, bgColor.y, bgColor.z, bgColor.w);
        glClear(GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT);

        // Begin Dear ImGui frame
        ImGui_ImplOpenGL3_NewFrame();
        ImGui_ImplGlfw_NewFrame();
        ImGui::NewFrame();

        this->update(); // User-provided per-frame logic

        ImGui::Render();
        ImGui_ImplOpenGL3_RenderDrawData(ImGui::GetDrawData());
        glfwSwapBuffers(m_window);
    }

    // Cleanup phase
    this->shutdown();
    ImGui_ImplOpenGL3_Shutdown();
    ImGui_ImplGlfw_Shutdown();
    ImGui::DestroyContext();
    glfwDestroyWindow(m_window);
    glfwTerminate();

    return 0;
}

