// Alternative implementation of ceiling function with platform-specific handling
double CeilingValue(double value) {
#if defined(__APPLE__)
    // Special case for negative numbers between -1 and 0 on macOS
    if (value > -1.0 && value < 0.0) {
        return -0.0;
    } else {
        return std::ceil(value);
    }
#else
    return std::ceil(value);
#endif
}

// Custom abort function for error handling with platform-specific behavior
void OS::Abort() {
#if defined(_WIN32)
    // Avoid DebugBreak() on Windows to preserve call stack in MSVS debugger
    *reinterpret_cast<int*>(nullptr) = 0;
    std::exit(3);
#elif defined(__APPLE__)
    // On macOS, raise SIGABRT as Breakpad doesn't handle signals
    *reinterpret_cast<int*>(nullptr) = 0;  // For GDB: use "return" then "continue"
    std::raise(SIGABRT);  // Fallback in case compiler optimizes away the null write
#else
    std::raise(SIGABRT);  // Standard POSIX abort mechanism
#endif
}

}  // namespace internal
}  // namespace v8

// Additional compatibility implementations for Windows/MSVC
#ifdef _MSC_VER
#include <float.h>

// Floating-point classification using Microsoft-specific API
int fpclassify(double x) {
    int classification = _fpclass(x);

    // Check positive/negative normal numbers
    if (classification & (_FPCLASS_PN | _FPCLASS_NN)) {
        return FP_NORMAL;
    }
    // Check positive/negative zero
    if (classification & (_FPCLASS_PZ | _FPCLASS_NZ)) {
        return FP_ZERO;
    }
    // Check positive/negative subnormal numbers
    if (classification & (_FPCLASS_PD | _FPCLASS_ND)) {
        return FP_SUBNORMAL;
    }
    // Check positive/negative infinities
    if (classification & (_FPCLASS_PINF | _FPCLASS_NINF)) {
        return FP_INFINITE;
    }

    // Remaining cases are signaling/quiet NaNs
    V8_ASSERT(classification & (_FPCLASS_SNAN | _FPCLASS_QNAN));
    return FP_NAN;
}
#endif  // _MSC_VER

// Solaris-specific floating-point classification
#ifdef SOLARIS
#include <ieeefp.h>

int fpclassify(double x) {
    fpclass_t result = fpclass(x);

    switch (result) {
        case FP_SNAN:
        case FP_QNAN:
            return FP_NAN;
        case FP_NINF:
        case FP_PINF:
            return FP_INFINITE;
        case FP_NDENORM:
        case FP_PDENORM:
            return FP_SUBNORMAL;
        case FP_NZERO:
        case FP_PZERO:
            return FP_ZERO;
        default:
            V8_ASSERT(result == FP_NNORM || result == FP_PNORM);
            return FP_NORMAL;
    }
}
#endif  // SOLARIS

