#include "stdafx.h"
#include "POWorkerThread.h"

// Helper to map job types to configuration presets
struct JobConfig {
    int filtering;
    PngDumpSettings::ZlibStrategy strategy;
    int windowBitsAndMem;
};

static const JobConfig s_jobConfigs[] = {
    {0, PngDumpSettings::zlibStrategyDefault, 0},                     // jobType 0: no filter, default zlib
    {0, PngDumpSettings::zlibStrategyDefault, PngDumpSettings::zlibWindowBitsAndMemLow}, // jobType 1: low mem
    {1, PngDumpSettings::zlibStrategyFilter, 0},                      // jobType 2: filter + zlib filter
    {1, PngDumpSettings::zlibStrategyDefault, 0}                      // jobType 3: filter + default zlib
};

POWorkerThread::POWorkerThread()
    : m_jobType(-1)
    , m_success(false)
    , m_created(false)
    , m_pPdd(nullptr)
{
}

POWorkerThread::~POWorkerThread()
{
    Exit();
}

int POWorkerThread::ThreadProcStatic(void* arg)
{
    auto* self = static_cast<POWorkerThread*>(arg);
    return self->Run();
}

bool POWorkerThread::ExecuteJob()
{
    if (!m_pPdd || m_jobType < 0 || m_jobType > 3)
        return false;

    const auto& dd = *m_pPdd;
    PngDumpSettings settings{};

    // Use pre-defined config based on job type
    const auto& cfg = s_jobConfigs[m_jobType];
    settings.filtering = cfg.filtering;
    settings.zlibStrategy = cfg.strategy;
    settings.zlibWindowBitsAndMem = cfg.windowBitsAndMem;

    // Special handling for jobType == 1: only valid for <=8 bpp
    if (m_jobType == 1) {
        const int bitsPerPixel = ImageFormat::SizeofPixelInBits(dd.pixelFormat);
        if (bitsPerPixel > 8)
            return false;
    }

    return PngDumper::Dump(m_dmf, dd, settings);
}

int POWorkerThread::Run()
{
    for (;;) {
        if (m_semBegin.Wait() != 0)
            break;

        if (m_jobType < 0) {
            // Termination signal received
            break;
        }

        m_success = ExecuteJob();
        m_semWait.Increment();
    }

    return 0;
}

bool POWorkerThread::Create()
{
    constexpr size_t initialAlloc = 256 * 1024 - 64;
    if (!m_dmf.Open(initialAlloc))
        return false;

    if (!m_semBegin.Create() || !m_semWait.Create())
        return false;

    if (!m_thread.Start(&ThreadProcStatic, this))
        return false;

    m_created = true;
    return true;
}

bool POWorkerThread::Begin(int jobType, const PngDumpData* pData)
{
    if (!m_created && !Create())
        return false;

    if (jobType < 0 || jobType > 3 || !pData)
        return false;

    m_pPdd = pData;
    m_jobType = jobType;
    m_success = false;
    m_dmf.SetPosition(0);

    m_semBegin.Increment();
    return true;
}

void POWorkerThread::Wait()
{
    if (m_jobType < 0)
        return;

    m_semWait.Wait();
    m_jobType = -1;
    m_pPdd = nullptr;
}

void POWorkerThread::Exit()
{
    if (!m_created)
        return;

    m_pPdd = nullptr;
    m_jobType = -1; // Signal thread to exit
    m_success = false;

    m_semBegin.Increment(); // Wake up worker if blocked
    m_thread.WaitForExit();

    m_semBegin.Close();
    m_created = false;
}

bool POWorkerThread::Succeeded() const
{
    return m_success;
}

DynamicMemoryFile& POWorkerThread::GetResult()
{
    return m_dmf;
}

