// Conversion from rho0 parametrization to base rhos parametrization
#define MODEL Halo_Einasto_rho0
#define PARENT Halo_Einasto
    void MODEL_NAMESPACE::Halo_Einasto_rho0_to_Halo_Einasto(const ModelParameters &input_params, ModelParameters &output_params)
    {
        // Extract parameters: central density, scale radius, solar distance, shape parameter
        double central_density = input_params.get("rho0");
        double scale_radius    = input_params.get("rs");
        double solar_dist      = input_params.get("r_sun");
        double shape_param     = input_params.get("alpha");

        // Compute reference density rhos at r_sun using exponential relation
        double exponent = (2.0 / shape_param) * (std::pow(solar_dist / scale_radius, shape_param) - 1.0);
        double ref_density = central_density * std::exp(-exponent);

        // Copy all input values first, then override with computed rhos
        output_params.setValues(input_params, true);
        output_params.set("rhos", ref_density);
    }
#undef PARENT
#undef MODEL

// Conversion from rhos parametrization to base rho0 parametrization
#define MODEL Halo_Einasto_rhos
#define PARENT Halo_Einasto
    void MODEL_NAMESPACE::Halo_Einasto_rhos_to_Halo_Einasto(const ModelParameters &input_params, ModelParameters &output_params)
    {
        // Extract parameters: reference density, scale radius, solar distance, shape parameter
        double ref_density     = input_params.get("rhos");
        double scale_radius    = input_params.get("rs");
        double solar_dist      = input_params.get("r_sun");
        double shape_param     = input_params.get("alpha");

        // Compute central density rho0 via inverse exponential relation
        double exponent = (2.0 / shape_param) * (std::pow(solar_dist / scale_radius, shape_param) - 1.0);
        double central_density = ref_density * std::exp(exponent);

        // Copy all input values first, then override with computed rho0
        output_params.setValues(input_params, true);
        output_params.set("rho0", central_density);
    }
#undef PARENT
#undef MODEL

