// Helper: Determine viewport dimensions safely
inline void GetViewportSize(FTexture2DRHIParamRef Buffer, uint32& Width, uint32& Height)
{
	Width = Buffer->GetSizeX();
	Height = Buffer->GetSizeY();
}

// Helper: Set up full-screen quad rendering state
inline void SetupFullScreenQuadState(FRHICommandListImmediate& RHICmdList, FRenderingCompositePassContext& Context, const auto FeatureLevel)
{
	auto ShaderMap = GetGlobalShaderMap(FeatureLevel);
	TShaderMapRef<FScreenVS> VertexShader(ShaderMap);
	TShaderMapRef<FScreenPS> PixelShader(ShaderMap);

	static FGlobalBoundShaderState BoundShaderState;
	SetGlobalBoundShaderState(RHICmdList, FeatureLevel, BoundShaderState,
		RendererModule->GetFilterVertexDeclaration().VertexDeclarationRHI,
		*VertexShader, *PixelShader);
}

// Helper: Draw rectangle with given UV coordinates
inline void DrawRectWithUVs(FRHICommandListImmediate& RHICmdList,
	int X, int Y, int W, int H,
	float U0, float V0, float U1, float V1,
	FTexture2DRHIParamRef SrcTexture,
	const TShaderMapRef<FScreenVS>& VertexShader,
	const TShaderMapRef<FScreenPS>& PixelShader)
{
	PixelShader->SetParameters(RHICmdList, TStaticSamplerState<SF_Bilinear>::GetRHI(), SrcTexture);
	RendererModule->DrawRectangle(
		RHICmdList,
		X, Y, W, H,
		U0, V0, U1, V1,
		FIntPoint(SrcTexture->GetSizeX(), SrcTexture->GetSizeY()),
		FIntPoint(1, 1),
		*VertexShader,
		EDRF_Default);
}

void FSteamVRHMD::DrawDistortionMesh_RenderThread(struct FRenderingCompositePassContext& Context, const FIntPoint& TextureSize)
