	check(0); // Not implemented
}

void FSteamVRHMD::RenderTexture_RenderThread(FRHICommandListImmediate& RHICmdList, FTexture2DRHIParamRef BackBuffer, FTexture2DRHIParamRef SrcTexture) const
{
	check(IsInRenderingThread());

	if (!WindowMirrorMode) return;

	uint32 ViewportWidth, ViewportHeight;
	GetViewportSize(BackBuffer, ViewportWidth, ViewportHeight);

	SetRenderTarget(RHICmdList, BackBuffer, FTextureRHIRef());
	RHICmdList.SetViewport(0, 0, 0, ViewportWidth, ViewportHeight, 1.0f);
	RHICmdList.SetBlendState(TStaticBlendState<>::GetRHI());
	RHICmdList.SetRasterizerState(TStaticRasterizerState<>::GetRHI());
	RHICmdList.SetDepthStencilState(TStaticDepthStencilState<false, CF_Always>::GetRHI());

	const auto FeatureLevel = GMaxRHIFeatureLevel;
	SetupFullScreenQuadState(RHICmdList, /*unused context*/, FeatureLevel);

	TShaderMapRef<FScreenVS> VertexShader(GetGlobalShaderMap(FeatureLevel));
	TShaderMapRef<FScreenPS> PixelShader(GetGlobalShaderMap(FeatureLevel));

	if (WindowMirrorMode == 1)
	{
		RHICmdList.Clear(true, FLinearColor::Black, false, 0, false, 0, FIntRect());
		DrawRectWithUVs(RHICmdList,
			ViewportWidth / 4, 0,
			ViewportWidth / 2, ViewportHeight,
			0.1f, 0.2f, 0.3f, 0.6f,
			SrcTexture,
			VertexShader, PixelShader);
	}
	else if (WindowMirrorMode == 2)
	{
		DrawRectWithUVs(RHICmdList,
			0, 0,
			ViewportWidth, ViewportHeight,
			0.0f, 0.0f, 1.0f, 1.0f,
			SrcTexture,
			VertexShader, PixelShader);
	}
}

// Shared occlusion mesh drawing logic
static void RenderOcclusionMesh(FRHICommandList& RHICmdList, EStereoscopicPass StereoPass, const FHMDViewMesh MeshAssets[])
{
	check(IsInRenderingThread());
	check(StereoPass != eSSP_FULL);

	const uint32 MeshIdx = (StereoPass == eSSP_LEFT_EYE) ? 0u : 1u;
	const FHMDViewMesh& Mesh = MeshAssets[MeshIdx];
	check(Mesh.IsValid());

	DrawIndexedPrimitiveUP(
		RHICmdList,
		PT_TriangleList,
		0,
		Mesh.NumVertices,
		Mesh.NumTriangles,
		Mesh.pIndices,
		sizeof(Mesh.pIndices[0]),
		Mesh.pVertices,
		sizeof(Mesh.pVertices[0])
	);
}

void FSteamVRHMD::DrawHiddenAreaMesh_RenderThread(FRHICommandList& RHICmdList, EStereoscopicPass StereoPass) const
{
	RenderOcclusionMesh(RHICmdList, StereoPass, HiddenAreaMeshes);
}

void FSteamVRHMD::DrawVisibleAreaMesh_RenderThread(FRHICommandList& RHICmdList, EStereoscopicPass StereoPass) const
{
	RenderOcclusionMesh(RHICmdList, StereoPass, VisibleAreaMeshes);
}

