FSteamVRHMD::D3D11Bridge::D3D11Bridge(FSteamVRHMD* plugin):
	BridgeBaseImpl(plugin),
	RenderTargetTexture(nullptr)
{
}

void FSteamVRHMD::D3D11Bridge::BeginRendering()
{
	check(IsInRenderingThread());
	static bool Initialized = false;
	if (!Initialized)
	{
		Initialized = true;
	}
}

void FSteamVRHMD::D3D11Bridge::FinishRendering()
{
	vr::VRTextureBounds_t LeftBounds = {};
	LeftBounds.uMin = 0.0f; LeftBounds.uMax = 0.5f;
	LeftBounds.vMin = 0.0f; LeftBounds.vMax = 1.0f;

	vr::Texture_t Texture = {};
	Texture.handle = RenderTargetTexture;
	Texture.eType = vr::API_DirectX;
	Texture.eColorSpace = vr::ColorSpace_Auto;

	vr::EVRCompositorError Err = Plugin->VRCompositor->Submit(vr::Eye_Left, &Texture, &LeftBounds);

	vr::VRTextureBounds_t RightBounds = {};
	RightBounds.uMin = 0.5f; RightBounds.uMax = 1.0f;
	RightBounds.vMin = 0.0f; RightBounds.vMax = 1.0f;

	Err = Plugin->VRCompositor->Submit(vr::Eye_Right, &Texture, &RightBounds);

	if (Err != vr::VRCompositorError_None)
	{
		UE_LOG(LogHMD, Log, TEXT("Warning: SteamVR Compositor error on present (%d)"), static_cast<int32>(Err));
	}
}

