#include "pawn.hpp"
namespace chess
{
    pawn::pawn(color c, const position_type& pos)
        : chess_piece(c, pos)
        , m_has_moved(false)
    {
    }

    bool pawn::can_move(const position_type& new_pos,
                        const has_piece_callback& cb) const
    {
        color piece_color = get_color();
        const position_type& current_position = get_position();
        bool is_valid = false;

        // Check if the target square is in the same file (column)
        bool aligned_same_file = (new_pos.first == current_position.first);

        // Forward movement logic for white and black pawns
        bool forward_one_white = (new_pos.second == current_position.second + 1) && (piece_color == 'w');
        bool forward_two_white = (new_pos.second == current_position.second + 2) && (piece_color == 'w');
        bool forward_one_black = (current_position.second == new_pos.second + 1) && (piece_color == 'b');
        bool forward_two_black = (current_position.second == new_pos.second + 2) && (piece_color == 'b');

        bool can_step_forward_one = aligned_same_file && (forward_one_white || forward_one_black);
        bool can_step_forward_two = aligned_same_file && (forward_two_white || forward_two_black);

        // Diagonal capture logic for both colors
        bool diagonal_capture_white = ((new_pos.first == current_position.first + 1) || 
                                       (new_pos.first == current_position.first - 1)) &&
                                      (new_pos.second == current_position.second + 1);
        bool diagonal_capture_black = ((new_pos.first == current_position.first + 1) || 
                                       (new_pos.first == current_position.first - 1)) &&
                                      (new_pos.second == current_position.second - 1);

        if (diagonal_capture_white || diagonal_capture_black)
        {
            is_valid = cb(new_pos, get_opposite_color());
        }
        else if (can_step_forward_one)
        {
            is_valid = !cb(new_pos, 'a'); // No piece at destination
        }
        else if (can_step_forward_two)
        {
            is_valid = !m_has_moved;

            // Ensure path is clear for two-square advance
            if (piece_color == 'w')
            {
                is_valid &= !cb(position_type(current_position.first, current_position.second + 1), 'a');
            }
            else
            {
                is_valid &= !cb(position_type(current_position.first, current_position.second - 1), 'a');
            }

            is_valid &= !cb(new_pos, 'a');
        }

        return is_valid;
    }

    void pawn::print(std::ostream& out) const
    {
        out << "P" << get_color();
    }

    void pawn::notify_move()
    {
        m_has_moved = true;
    }
}

