namespace gui::settings {

    ActionSettingsPane::ActionSettingsPane(model::settings::ActionSettingsModel *model, QWidget *parent)
        : QWidget(parent), settings(model) {
        // Initialize local state from model
        currentMode = settings->getMode();
        currentSound = settings->getSound();
        currentColor = settings->getColor();
        currentInterval = settings->getInterval();
        currentCount = settings->getCount();

        buildUI();
    }

    void ActionSettingsPane::buildUI() {
        auto *layout = new QGridLayout(this);

        // --- Mode selection ---
        {
            auto *modeCombo = new QComboBox;
            auto *label = new QLabel("Mode");
            auto *fieldGroup = new util::FieldSet<QComboBox>(0, label, modeCombo);

            gui::util::widget::addItems<model::ActionMode>(
                modeCombo,
                model::actionModes(),
                [](model::ActionMode m) { return model::getName(m); }
            );
            modeCombo->setCurrentText(model::getName(settings->getMode()));
            util::addFieldSet(layout, *fieldGroup);

            connect(modeCombo, SIGNAL(currentIndexChanged(int)), this, SLOT(setMode(int)));
        }

        // --- Sound selection ---
        {
            auto *soundCombo = new QComboBox;
            auto *label = new QLabel("Sound");
            auto *fieldGroup = new util::FieldSet<QComboBox>(1, label, soundCombo);

            gui::util::widget::addItems<model::Sound>(
                soundCombo,
                model::sounds(),
                [](model::Sound s) { return model::getName(s); }
            );
            soundCombo->setCurrentText(model::getName(settings->getSound()));
            util::addFieldSet(layout, *fieldGroup);

            connect(soundCombo, SIGNAL(currentIndexChanged(int)), this, SLOT(setSound(int)));

            // Visibility logic for sound fieldset
            connect(this, &ActionSettingsPane::modeChanged, [layout, fieldGroup](int modeVal) {
                bool shouldShow = (modeVal == model::ActionMode::AUDIO || modeVal == model::ActionMode::AV);
                util::setVisible(layout, *fieldGroup, shouldShow);
            });
        }

        // --- Color picker ---
        {
            auto *colorBtn = new QPushButton;
            auto *label = new QLabel("Color");
            auto *fieldGroup = new util::FieldSet<QPushButton>(2, label, colorBtn);

            applyColorIcon(colorBtn, currentColor);
            connect(colorBtn, &QPushButton::clicked, [this, colorBtn]() {
                QColor picked = QColorDialog::getColor(currentColor, this);
                if (picked.isValid()) {
                    applyColorIcon(colorBtn, picked);
                    currentColor = picked;
                }
            });

            // Visibility logic for color fieldset
            connect(this, &ActionSettingsPane::modeChanged, [layout, fieldGroup](int modeVal) {
                bool shouldShow = (modeVal == model::ActionMode::VISUAL || modeVal == model::ActionMode::AV);
                util::setVisible(layout, *fieldGroup, shouldShow);
            });

            util::addFieldSet(layout, *fieldGroup);
        }

        // --- Interval setting ---
        {
            auto *intervalSpin = new QSpinBox;
            auto *label = new QLabel("Interval");
            auto *fieldGroup = new util::FieldSet<QSpinBox>(3, label, intervalSpin);

            gui::util::widget::setModel(intervalSpin, 1, 1000, settings->getInterval());
            util::addFieldSet(layout, *fieldGroup);

            connect(intervalSpin, SIGNAL(valueChanged(int)), this, SLOT(setInterval(int)));
        }

        // --- Count setting ---
        {
            auto *countSpin = new QSpinBox;
            auto *label = new QLabel("Count");
            auto *fieldGroup = new util::FieldSet<QSpinBox>(4, label, countSpin);

            gui::util::widget::setModel(countSpin, 1, 50, settings->getCount());
            util::addFieldSet(layout, *fieldGroup);

            connect(countSpin, SIGNAL(valueChanged(int)), this, SLOT(setCount(int)));
        }

        // Trigger initial visibility update based on current mode
        emit modeChanged(currentMode);
    }

    void ActionSettingsPane::updateSettings() {
        settings->setMode(model::actionMode(static_cast<unsigned int>(currentMode)));
        settings->setSound(model::sound(static_cast<unsigned int>(currentSound)));
        settings->setInterval(static_cast<unsigned int>(currentInterval));
        settings->setCount(static_cast<unsigned int>(currentCount));
        settings->setColor(currentColor);
    }

    void ActionSettingsPane::setMode(int newMode) {
        if (currentMode != newMode) {
            currentMode = newMode;
            emit modeChanged(newMode);
        }
    }

    void ActionSettingsPane::setSound(int newSound) {
        currentSound = newSound;
    }

    void ActionSettingsPane::setInterval(int newInterval) {
        currentInterval = newInterval;
    }

    void ActionSettingsPane::setCount(int newCount) {
        currentCount = newCount;
    }

    void ActionSettingsPane::applyColorIcon(QPushButton *button, const QColor &color) {
        QPixmap iconPixmap(64, 64);
        iconPixmap.fill(color);
        button->setIcon(QIcon(iconPixmap));
    }

} // namespace gui::settings

#include "test_helper.h"
#include "compiler/lexical_grammar.h"
#include "compiler/prepare_grammar/expand_tokens.h"
#include "helpers/stream_methods.h"
START_TEST
using namespace rules;
using prepare_grammar::expand_token;
using prepare_grammar::ExpandTokenResult;

describe("token_expansion", [&]() {
  MetadataParams string_metadata;
  string_metadata.is_string = true;
  string_metadata.is_token = true;

  describe("string-based rules", [&]() {
    it("converts string literals into character set sequences", [&]() {
      auto expanded = expand_token(Rule::seq({
        String{"a"},
        String{"bcd"},
        String{"e"}
      }));

      AssertThat(
        expanded.rule,
        Equals(Rule::seq({
          CharacterSet{{ 'a' }},
          Rule::seq({
            CharacterSet{{ 'b' }},
            CharacterSet{{ 'c' }},
            CharacterSet{{ 'd' }},
          }),
          CharacterSet{{ 'e' }},
        }))
      );
    });

    it("processes multi-byte UTF-8 strings correctly", [&]() {
      auto expanded = expand_token(String{"\xCE\xB1 \xCE\xB2"});

      AssertThat(
        expanded.rule,
        Equals(Rule::seq({
          CharacterSet{{ static_cast<char>(945) }},
          CharacterSet{{ ' ' }},
          CharacterSet{{ static_cast<char>(946) }},
        }))
      );
    });
  });

  describe("regular expression handling", [&]() {
    it("transforms regex patterns into appropriate rule constructs", [&]() {
      auto expanded = expand_token(Rule::seq({
        String{"a"},
        Pattern{"x+"},
        String{"b"},
      }));

      AssertThat(
        expanded.rule,
        Equals(Rule::seq({
          CharacterSet{{'a'}},
          Repeat{CharacterSet{{ 'x' }}},
          CharacterSet{{'b'}},
        }))
      );
    });

    it("supports Unicode-aware negated character classes", [&]() {
      auto expanded = expand_token(Pattern{"[^\xCE\xB1-\xCE\xB4]+"});

      AssertThat(
        expanded.rule,
        Equals(Rule(Repeat{
          CharacterSet().include_all().exclude(945, 948)
        }))
      );
    });

    it("reports syntax errors for malformed regular expressions", [&]() {
      auto result = expand_token(Rule::seq({
        Pattern{"("},
        String{"xyz"},
        Pattern{"["},
      }));

      AssertThat(
        result.error,
        Equals(CompileError(
          TSCompileErrorTypeInvalidRegex,
          "unmatched open paren"
        ))
      );
    });
  });
});
END_TEST

#include <LuaConsole/LuaSFMLConsoleView.hpp>
#include <LuaConsole/LuaConsoleModel.hpp>
#include <SFML/Graphics/RenderTarget.hpp>

namespace blua {

constexpr unsigned kDefaultFontSize = 18u;
constexpr char const* kMonoFontPath = "DejaVuSansMono.ttf";

// Convert raw uint32 color to sf::Color using bit shifts
static sf::Color rgbaFromUint(unsigned int colorValue) {
    sf::Color result;
    result.r = static_cast<sf::Uint8>((colorValue >> 24) & 0xFF);
    result.g = static_cast<sf::Uint8>((colorValue >> 16) & 0xFF);
    result.b = static_cast<sf::Uint8>((colorValue >> 8) & 0xFF);
    result.a = static_cast<sf::Uint8>(colorValue & 0xFF);
    return result;
}

LuaSFMLConsoleView::LuaSFMLConsoleView(bool useSystemFont) :
    m_dirtyLevel(0u),
    m_fontPtr(nullptr),
    m_ownsFont(false),
    m_systemFontRequested(useSystemFont),
    m_isVisible(false)
{
    m_vertexArray.setPrimitiveType(sf::Quads);

    if (m_systemFontRequested) {
        auto* defaultFont = new sf::Font{};
        if (defaultFont->loadFromFile(kMonoFontPath)) {
            m_fontPtr = defaultFont;
            m_ownsFont = true;
        } else {
            delete defaultFont;
        }
    }
}

LuaSFMLConsoleView::~LuaSFMLConsoleView() {
    if (m_ownsFont && m_fontPtr) {
        delete m_fontPtr;
        m_fontPtr = nullptr;
    }
}

void LuaSFMLConsoleView::draw(sf::RenderTarget& target, sf::RenderStates states) const {
    if (!m_fontPtr || !m_isVisible) return;

    // Save current view and set up orthographic 1:1 mapping
    sf::View originalView = target.getView();
    sf::Vector2u winSize = target.getSize();
    sf::View orthoView{sf::FloatRect{{}, {static_cast<float>(winSize.x), static_cast<float>(winSize.y)}}};
    target.setView(orthoView);

    states.texture = &m_fontPtr->getTexture(kDefaultFontSize);
    target.draw(m_vertexArray, states);

    target.setView(originalView);
}

void LuaSFMLConsoleView::setFont(const sf::Font* newFont) {
    if (m_ownsFont && m_fontPtr) {
        delete m_fontPtr;
        m_fontPtr = nullptr;
        m_ownsFont = false;
    }

    m_fontPtr = newFont;

    if (!m_fontPtr && m_systemFontRequested) {
        auto* fallbackFont = new sf::Font{};
        if (fallbackFont->loadFromFile(kMonoFontPath)) {
            m_fontPtr = fallbackFont;
            m_ownsFont = true;
        } else {
            delete fallbackFont;
        }
    }
}

const sf::Font* LuaSFMLConsoleView::getFont() const {
    return m_fontPtr;
}

// Rebuilds geometry based on model state
void LuaSFMLConsoleView::updateGeometry(const LuaConsoleModel* model) {
    if (!model) return;

    unsigned currentDirtyLevel = model->getDirtyness();
    if (currentDirtyLevel == m_dirtyLevel) return;

    if (!m_fontPtr) return;

    m_dirtyLevel = currentDirtyLevel;
    m_isVisible = model->isVisible();

    if (!m_isVisible) {
        m_vertexArray.clear();
        return;
    }

    const ScreenCell* buffer = model->getScreenBuffer();
    std::size_t totalCells = model->getConsoleWidth() * model->getConsoleHeight();

    m_vertexArray.clear();

    // Reserve space for background quad (4 vertices)
    for (int idx = 0; idx < 4; ++idx) {
        m_vertexArray.append(sf::Vertex{});
    }

    // Metrics
    float charWidth = m_fontPtr->getGlyph(L' ', kDefaultFontSize, false).advance;
    float lineHeight = m_fontPtr->getLineSpacing(kDefaultFontSize);

    float cursorX = 0.0f;
    float cursorY = static_cast<float>(kDefaultFontSize);
    sf::Uint32 lastChar = 0u;

    for (std::size_t index = 0u; index < totalCells; ++index) {
        sf::Uint32 currentChar = buffer[index].Char;

        // Move reserved background vertices out of bounds early
        if (index == 1u) {
            for (std::size_t bgIdx = 0u; bgIdx < 4u; ++bgIdx) {
                m_vertexArray[bgIdx].position = m_vertexArray[4].position;
            }
        }

        // Kerning adjustment
        cursorX += m_fontPtr->getKerning(lastChar, currentChar, kDefaultFontSize);
        lastChar = currentChar;

        // Draw cursor block at special position
        if (index == model->getCurPos() + (model->getConsoleWidth() * (model->getConsoleHeight() - 2))) {
            constexpr sf::Uint32 fullBlockCode = 0x2588u;
            const sf::Glyph blockGlyph = m_fontPtr->getGlyph(fullBlockCode, kDefaultFontSize, false);
            const sf::Color cursorColor = rgbaFromUint(model->getColor(ECC_CURSOR));
            const sf::Vector2f texCoord{1.f, 1.f};

            float gx = cursorX + blockGlyph.bounds.left;
            float gy = cursorY + blockGlyph.bounds.top;
            float gw = blockGlyph.bounds.width;
            float gh = blockGlyph.bounds.height;

            m_vertexArray.append({{gx, gy}, cursorColor, texCoord});
            m_vertexArray.append({{gx, gy + gh}, cursorColor, texCoord});
            m_vertexArray.append({{gx + gw, gy + gh}, cursorColor, texCoord});
            m_vertexArray.append({{gx + gw, gy}, cursorColor, texCoord});
        }

        // Handle whitespace characters
        switch (currentChar) {
            case '\t':
            case '\n':
            case ' ':
                cursorX += charWidth;
                continue;
        }

        // Get glyph data
        const sf::Glyph& g = m_fontPtr->getGlyph(currentChar, kDefaultFontSize, false);
        float left = g.bounds.left;
        float top = g.bounds.top;
        float right = left + g.bounds.width;
        float bottom = top + g.bounds.height;

        float u1 = g.textureRect.left;
        float v1 = g.textureRect.top;
        float u2 = u1 + g.textureRect.width;
        float v2 = v1 + g.textureRect.height;

        const sf::Color textColor = rgbaFromUint(buffer[index].Color);

        // Append character quad
        m_vertexArray.append({{cursorX + left, cursorY + top}, textColor, {u1, v1}});
        m_vertexArray.append({{cursorX + right, cursorY + top}, textColor, {u2, v1}});
        m_vertexArray.append({{cursorX + right, cursorY + bottom}, textColor, {u2, v2}});
        m_vertexArray.append({{cursorX + left, cursorY + bottom}, textColor, {u1, v2}});

        cursorX += g.advance;

        // Line wrapping
        if ((index + 1) % model->getConsoleWidth() == 0) {
            cursorY += lineHeight;
            cursorX = 0.0f;
            lastChar = L'\n';
        }
    }

    // Finalize background quad
    sf::FloatRect bounds = m_vertexArray.getBounds();
    m_vertexArray[0].position = {bounds.left, bounds.top};
    m_vertexArray[1].position = {bounds.left, bounds.top + bounds.height};
    m_vertexArray[2].position = {bounds.left + bounds.width, bounds.top + bounds.height};
    m_vertexArray[3].position = {bounds.left + bounds.width, bounds.top};

    const sf::Color bgColor = rgbaFromUint(model->getColor(ECC_BACKGROUND));
    for (int i = 0; i < 4; ++i) {
        m_vertexArray[i].texCoords = {1.f, 1.f};
        m_vertexArray[i].color = bgColor;
    }
}

