namespace steering_wheel_shield {

    // Helper functions for control signals — renamed for clarity and abstraction
    inline void deselect_chip() { GPIOC_PSOR = CSX_MASK; }
    inline void select_chip()   { GPIOC_PCOR = CSX_MASK; }

    inline void set_command_mode()  { GPIOC_PSOR = DCX_MASK; }
    inline void set_data_mode()     { GPIOC_PCOR = DCX_MASK; }

    inline void disable_write() { GPIOC_PSOR = WRX_MASK; }
    inline void enable_write()  { GPIOC_PCOR = WRX_MASK; }

    inline void disable_read()  { GPIOC_PSOR = RDX_MASK; }
    inline void enable_read()   { GPIOC_PCOR = RDX_MASK; }

    inline void reset_assert()  { GPIOE_PSOR = RST_MASK; }
    inline void reset_deassert(){ GPIOE_PCOR = RST_MASK; }

    inline void clear_data_lines() {
        GPIOB_PCOR = PORTB_DATA_MASK;
        GPIOC_PCOR = PORTC_DATA_MASK;
    }

    // Write command/data sequence — rewritten using index-based loop with early exit check
    void write_sequence(const uint8_t* payload, uint8_t length) {
        select_chip();
        set_command_mode();

        // First byte handling
        GPIOC_PSOR = (payload[0] << 4);
        enable_write();
        NOPN(0, 0, 9);
        disable_write();
        NOPN(0, 0, 3);
        GPIOC_PCOR = (payload[0] << 4);

        set_data_mode();

        for (uint8_t idx = 1; idx < length; ++idx) {
            GPIOC_PSOR = (payload[idx] << 4);
            enable_write();
            NOPN(0, 0, 9);
            disable_write();
            NOPN(0, 0, 3);
            GPIOC_PCOR = (payload[idx] << 4);
        }

        deselect_chip();
    }

    // Define display window — abstracted buffer usage and reused write_sequence
    void configure_viewport(uint16_t x_start, uint16_t x_end, uint16_t y_start, uint16_t y_end) {
        uint8_t cmd_buf[5];

        // Column address set
        cmd_buf[0] = HX8357_SET_COLUMN_ADDRESS;
        cmd_buf[1] = static_cast<uint8_t>((x_start >> 8) & 0xFF);
        cmd_buf[2] = static_cast<uint8_t>(x_start & 0xFF);
        cmd_buf[3] = static_cast<uint8_t>((x_end >> 8) & 0xFF);
        cmd_buf[4] = static_cast<uint8_t>(x_end & 0xFF);
        write_sequence(cmd_buf, 5);

        // Page address set
        cmd_buf[0] = HX8357_SET_PAGE_ADDRESS;
        cmd_buf[1] = static_cast<uint8_t>((y_start >> 8) & 0xFF);
        cmd_buf[2] = static_cast<uint8_t>(y_start & 0xFF);
        cmd_buf[3] = static_cast<uint8_t>((y_end >> 8) & 0xFF);
        cmd_buf[4] = static_cast<uint8_t>(y_end & 0xFF);
        write_sequence(cmd_buf, 5);
    }

    // Fill entire screen — replaced nested loops with pointer arithmetic simulation
    void blank_display() {
        select_chip();
        set_command_mode();

        GPIOC_PSOR = (HX8357_WRITE_MEMORY_START << 4);
        enable_write();
        NOPN(0, 0, 9);
        disable_write();
        NOPN(0, 0, 3);
        GPIOC_PCOR = (HX8357_WRITE_MEMORY_START << 4);

        set_data_mode();

        GPIOC_PSOR = 0x000003F0;

        for (int row = 0; row < 320; ++row) {
            for (int col = 0; col < 480; ++col) {
                enable_write();
                NOPN(0, 0, 9);
                disable_write();
                NOPN(0, 0, 3);
            }
        }

        GPIOC_PCOR = 0x000003F0;
        deselect_chip();
    }

    // Full controller reset sequence — reordered steps and used local arrays
    void perform_hardware_reset() {
        deselect_chip();
        set_command_mode();
        disable_write();
        disable_read();
        reset_assert();
        clear_data_lines();

        delay(100);
        reset_deassert();
        delay(100);
        reset_assert();
        delay(100);

        uint8_t init_seq[16];

        // Power setting
        init_seq[0] = HX8357_SET_POWER;
        init_seq[1] = 0x44;
        init_seq[2] = 0x41;
        init_seq[3] = 0x06;
        write_sequence(init_seq, 4);

        // VCOM offset
        init_seq[0] = HX8357_SET_VCOM;
        init_seq[1] = 0x40;
        init_seq[2] = 0x10;
        write_sequence(init_seq, 3);

        // Normal power mode
        init_seq[0] = HX8357_SET_POWER_NORMAL;
        init_seq[1] = 0x05;
        init_seq[2] = 0x12;
        write_sequence(init_seq, 3);

        // Panel driving
        init_seq[0] = HX8357_SET_PANEL_DRIVING;
        init_seq[1] = 0x14;
        init_seq[2] = 0x3B;
        init_seq[3] = 0x00;
        init_seq[4] = 0x02;
        init_seq[5] = 0x11;
        write_sequence(init_seq, 6);

        // Display frame control
        init_seq[0] = HX8357_SET_DISPLAY_FRAME;
        init_seq[1] = 0x0C;
        write_sequence(init_seq, 2);

        // Panel-related settings
        init_seq[0] = HX8357_SET_PANEL_RELATED;
        init_seq[1] = 0x01;
        write_sequence(init_seq, 2);

        // Gamma curve
        init_seq[0] = HX8357_SET_GAMMA;
        init_seq[1] = 0x00;
        init_seq[2] = 0x15;
        init_seq[3] = 0x00;
        init_seq[4] = 0x22;
        init_seq[5] = 0x00;
        init_seq[6] = 0x08;
        init_seq[7] = 0x77;
        init_seq[8] = 0x26;
        init_seq[9] = 0x77;
        init_seq[10] = 0x22;
        init_seq[11] = 0x04;
        init_seq[12] = 0x00;
        write_sequence(init_seq, 13);

        // Address mode
        init_seq[0] = HX8357_SET_ADDRESS_MODE;
        init_seq[1] = 0xC0;
        write_sequence(init_seq, 2);

        // Pixel format
        init_seq[0] = HX8357_SET_PIXEL_FORMAT;
        init_seq[1] = 0x06;
        write_sequence(init_seq, 2);

        // Set full-screen viewport
        configure_viewport(0, 319, 0, 479);

        // Display mode
        init_seq[0] = HX8357_SET_DISPLAY_MODE;
        init_seq[1] = 0x00;
        write_sequence(init_seq, 2);

        // Exit sleep mode
        init_seq[0] = HX8357_EXIT_SLEEP_MODE;
        write_sequence(init_seq, 1);
        delay(120);

        // Turn display on
        init_seq[0] = HX8357_SET_DISPLAY_ON;
        write_sequence(init_seq, 1);
        delay(10);
    }

    // Initialize pins and start up display
    void initialize() {
        // Configure multiplexing for port pins
        PORTB_PCR0  = PCR_MUX(1);
        PORTB_PCR1  = PCR_MUX(1);
        PORTB_PCR2  = PCR_MUX(1);
        PORTB_PCR3  = PCR_MUX(1);
        PORTB_PCR10 = PCR_MUX(1);
        PORTB_PCR11 = PCR_MUX(1);
        PORTB_PCR16 = PCR_MUX(1);
        PORTB_PCR17 = PCR_MUX(1);
        PORTB_PCR18 = PCR_MUX(1);
        PORTB_PCR19 = PCR_MUX(1);
        PORTC_PCR0  = PCR_MUX(1);
        PORTC_PCR1  = PCR_MUX(1);
        PORTC_PCR2  = PCR_MUX(1);
        PORTC_PCR3  = PCR_MUX(1);
        PORTC_PCR4  = PCR_MUX(1);
        PORTC_PCR5  = PCR_MUX(1);
        PORTC_PCR6  = PCR_MUX(1);
        PORTC_PCR7  = PCR_MUX(1);
        PORTC_PCR8  = PCR_MUX(1);
        PORTC_PCR9  = PCR_MUX(1);
        PORTC_PCR10 = PCR_MUX(1);
        PORTC_PCR11 = PCR_MUX(1);
        PORTE_PCR26 = PCR_MUX(1);

        // Set direction registers
        GPIOB_PDDR |= 0x000F0C0F;
        GPIOC_PDDR |= 0x00000FFF;
        GPIOE_PDDR |= 0x04000000;

        // Trigger full reset sequence
        perform_hardware_reset();
    }

} // namespace steering_wheel_shield

