/*
Test Example: f(v)=x^2+(x+y-10)^2+(2*y-z)^2+2*z;
Approximate Hessian Matrix using SR1.
*/

double objectiveFunction(const Vector3d& v)
{
    double x = v(0);
    double y = v(1);
    double z = v(2);

    return x * x + (x + y - 10) * (x + y - 10) + (2 * y - z) * (2 * y - z) + 2 * z;
}

Vector3d gradient(const Vector3d& v)
{
    Vector3d grad;
    double x = v(0);
    double y = v(1);
    double z = v(2);

    double dx = 2 * x + 2 * (x + y - 10);
    double dy = 2 * (x + y - 10) + 4 * (2 * y - z);
    double dz = 2 * (z - 2 * y) + 2;

    grad << dx, dy, dz;
    return grad;
}

bool isPositiveDefinite(const Matrix3d& matrix)
{
    SelfAdjointEigenSolver<Matrix3d> es(matrix);
    const Vector3d& eigenvalues = es.eigenvalues();

    return eigenvalues(0) > 1e-10 && eigenvalues(1) > 1e-10 && eigenvalues(2) > 1e-10;
}

int main()
{
    Vector3d currentPoint(100.0, 100.0, 100.0);
    double damping = 0.25;
    Matrix3d hessianApprox; hessianApprox.setIdentity();
    Matrix3d identity; identity.setIdentity();

    while (true)
    {
        Vector3d grad = gradient(currentPoint);
        if (grad.norm() < 1e-6) break;

        // Ensure positive definiteness by increasing damping
        while (!isPositiveDefinite(hessianApprox + damping * identity))
        {
            damping *= 4.0;
        }

        Matrix3d regularizedHessian = hessianApprox + damping * identity;
        Vector3d step = -regularizedHessian.inverse() * grad;

        double actualReduction = objectiveFunction(currentPoint) - objectiveFunction(currentPoint + step);
        double predictedReduction = objectiveFunction(currentPoint) - 
                                   (objectiveFunction(currentPoint) + grad.transpose() * step + 
                                    0.5 * step.transpose() * hessianApprox * step);

        double rho = actualReduction / predictedReduction;

        if (rho < 0.25) damping *= 4.0;
        else if (rho > 0.75) damping *= 0.5;

        if (rho > 0)
        {
            currentPoint += step;

            Vector3d s = -step;
            Vector3d y = grad - gradient(currentPoint);
            double denominator = (s - hessianApprox * y).transpose() * y;

            if (abs(denominator) > 1e-12)
            {
                hessianApprox = hessianApprox + 
                               (s - hessianApprox * y) * (s - hessianApprox * y).transpose() / denominator;
            }
        }
    }

    cout << currentPoint.transpose() << endl;
    cout << objectiveFunction(currentPoint) << endl;

    return 0;
}

