// Log level for TurboJPEG warnings
constexpr int ANDROID_LOG_WARN_TJ = 5;

#ifdef _WINDOWS_
    #define LOG_TJ(...) do { printf(__VA_ARGS__); printf("\n"); } while(0)
#else
    #define LOG_TJ(...) __android_log_print(ANDROID_LOG_WARN_TJ, __FILE__, __VA_ARGS__)
#endif

namespace OVR {

bool SaveAsJpeg(const char* outputPath, const unsigned char* rgbxData, int imgWidth, int imgHeight) {
    // Initialize compressor handle
    tjhandle compressor = tjInitCompress();
    if (!compressor) return false;

    unsigned char* jpegBuffer = nullptr;
    unsigned long jpegSize = 0;

    // Perform JPEG compression
    int compressResult = tjCompress2(
        compressor,
        const_cast<unsigned char*>(rgbxData),
        imgWidth,
        imgWidth * 4,
        imgHeight,
        TJPF_RGBX,
        &jpegBuffer,
        &jpegSize,
        TJSAMP_444,
        90,
        0
    );

    if (compressResult != 0) {
        LOG_TJ("Compression failed: %s", tjGetErrorStr());
        tjDestroy(compressor);
        return false;
    }

    // Write to file
    FILE* outFile = std::fopen(outputPath, "wb");
    if (!outFile) {
        LOG_TJ("Failed to open output file: %s", outputPath);
        tjFree(jpegBuffer);
        tjDestroy(compressor);
        return false;
    }

    size_t written = std::fwrite(jpegBuffer, 1, jpegSize, outFile);
    std::fclose(outFile);

    if (written != jpegSize) {
        LOG_TJ("Incomplete write to %s", outputPath);
        tjFree(jpegBuffer);
        tjDestroy(compressor);
        return false;
    }

    tjFree(jpegBuffer);
    tjDestroy(compressor);
    return true;
}

unsigned char* DecodeJpegFromMemory(const unsigned char* jpegData, int dataLength, int* outWidth, int* outHeight) {
    tjhandle decompressor = tjInitDecompress();
    if (!decompressor) return nullptr;

    int w = 0, h = 0, subsamp = 0, colorspace = 0;

    // Parse header first
    int headerStatus = tjDecompressHeader3(
        decompressor,
        const_cast<unsigned char*>(jpegData),
        dataLength,
        &w, &h, &subsamp, &colorspace
    );

    if (headerStatus != 0) {
        LOG_TJ("Header parsing failed: %s", tjGetErrorStr());
        tjDestroy(decompressor);
        return nullptr;
    }

    const int bufferSize = w * h * 4;
    unsigned char* decodedBuffer = static_cast<unsigned char*>(malloc(bufferSize));
    if (!decodedBuffer) {
        tjDestroy(decompressor);
        return nullptr;
    }

    // Decompress image
    int decodeStatus = tjDecompress2(
        decompressor,
        const_cast<unsigned char*>(jpegData),
        dataLength,
        decodedBuffer,
        w,
        w * 4,
        h,
        TJPF_RGBX,
        0
    );

    if (decodeStatus != 0) {
        LOG_TJ("Decompression failed: %s", tjGetErrorStr());
        free(decodedBuffer);
        tjDestroy(decompressor);
        return nullptr;
    }

    tjDestroy(decompressor);

    *outWidth = w;
    *outHeight = h;
    return decodedBuffer;
}

unsigned char* LoadJpegFromFile(const char* filePath, int* width, int* height) {
    int fileDescriptor = open(filePath, O_RDONLY);
    if (fileDescriptor < 0) {
        return nullptr;
    }

    struct stat fileInfo = {};
    if (fstat(fileDescriptor, &fileInfo) == -1) {
        LOG_TJ("Failed to get file info for %s", filePath);
        close(fileDescriptor);
        return nullptr;
    }

    size_t fileSize = static_cast<size_t>(fileInfo.st_size);
    void* mappedPtr = mmap(nullptr, fileSize, PROT_READ, MAP_SHARED, fileDescriptor, 0);
    if (mappedPtr == MAP_FAILED) {
        LOG_TJ("mmap failed for %s (%zu bytes): %s", filePath, fileSize, strerror(errno));
        close(fileDescriptor);
        return nullptr;
    }

    LOG_TJ("Mapped %s (%zu bytes) at %p", filePath, fileSize, mappedPtr);

    unsigned char* result = DecodeJpegFromMemory(
        static_cast<unsigned char*>(mappedPtr),
        static_cast<int>(fileSize),
        width,
        height
    );

    munmap(mappedPtr, fileSize);
    close(fileDescriptor);

    return result;
}

