#include "Core/OUUDataTableLibrary.h"

bool UOUUDataTableLibrary::AddRowToDataTable(UDataTable* DataTable, FName RowName, FTableRowBase RowStruct)
{
	// This function should never be called directly; use Generic_AddRowToDataTable instead
	UE_LOG(LogTemp, Warning, TEXT("UOUUDataTableLibrary::AddRowToDataTable was called directly. This is not supported."));
	return false;
}

bool UOUUDataTableLibrary::RemoveRowFromDataTable(UDataTable* DataTable, FName RowName)
{
	if (!IsValid(DataTable))
	{
		return false;
	}

	// Use FindRow to avoid double lookup (once for check, once for removal)
	const FTableRowBase* ExistingRow = DataTable->FindRow<FTableRowBase>(RowName, /*out*/ nullptr);
	if (!ExistingRow)
	{
		return false;
	}

	DataTable->RemoveRow(RowName);
	return true;
}

DEFINE_FUNCTION(UOUUDataTableLibrary::execAddRowToDataTable)
{
	P_GET_OBJECT(UDataTable, TargetDataTable);
	P_GET_PROPERTY(FNameProperty, TargetRowName);
	Stack.StepCompiledIn<FStructProperty>(nullptr);
	void* RawRowAddress = Stack.MostRecentPropertyAddress;

	P_FINISH;

	FStructProperty* RowProperty = CastField<FStructProperty>(Stack.MostRecentProperty);

	bool bResult = false;

	// Early validation of critical inputs
	if (!IsValid(TargetDataTable))
	{
		FBlueprintExceptionInfo ExceptionInfo(
			EBlueprintExceptionType::AccessViolation,
			INVTEXT("Invalid DataTable provided to AddRowToDataTable.")
		);
		FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ExceptionInfo);
	}
	else if (!RowProperty || !RawRowAddress)
	{
		FBlueprintExceptionInfo ExceptionInfo(
			EBlueprintExceptionType::AccessViolation,
			INVTEXT("Failed to extract row data for AddRowToDataTable.")
		);
		FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ExceptionInfo);
	}
	else
	{
		const UScriptStruct* InputStruct = RowProperty->Struct;
		const UScriptStruct* ExpectedStruct = TargetDataTable->GetRowStruct();

		// Validate structural compatibility
		bool bIsCompatible = (InputStruct == ExpectedStruct) ||
			(InputStruct->IsChildOf(ExpectedStruct) && FStructUtils::TheSameLayout(InputStruct, ExpectedStruct));

		if (!bIsCompatible)
		{
			FBlueprintExceptionInfo ExceptionInfo(
				EBlueprintExceptionType::AccessViolation,
				INVTEXT("Row type mismatch: input struct does not match DataTable row type.")
			);
			FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ExceptionInfo);
		}
		else
		{
			// Perform safe cast and call generic implementation
			FTableRowBase* RowAsBase = static_cast<FTableRowBase*>(RawRowAddress);
			if (!RowAsBase)
			{
				FBlueprintExceptionInfo ExceptionInfo(
					EBlueprintExceptionType::AccessViolation,
					INVTEXT("Null pointer passed as row data.")
				);
				FBlueprintCoreDelegates::ThrowScriptException(P_THIS, Stack, ExceptionInfo);
			}
			else
			{
				P_NATIVE_BEGIN;
				bResult = Generic_AddRowToDataTable(TargetDataTable, TargetRowName, RowProperty, RowAsBase);
				P_NATIVE_END;
			}
		}
	}

	*(bool*)RESULT_PARAM = bResult;
}

bool UOUUDataTableLibrary::Generic_AddRowToDataTable(UDataTable* DataTable, FName RowName, FStructProperty* RowProperty, void* RowData)
{
	// Validate all required parameters
	if (!IsValid(DataTable) || !RowData || !RowProperty)
	{
		return false;
	}

	// Ensure row name is unique
	if (DataTable->GetRowMap().Contains(RowName))
	{
		return false;
	}

	const UScriptStruct* ExpectedStruct = DataTable->GetRowStruct();
	if (!ExpectedStruct)
	{
		return false;
	}

	// Double-check that the passed-in struct matches expected layout
	FStructProperty* ActualProp = CastField<FStructProperty>(RowProperty);
	if (!ActualProp || ActualProp->Struct != ExpectedStruct)
	{
		return false;
	}

	// Safe downcast to FTableRowBase
	FTableRowBase* RowAsBase = static_cast<FTableRowBase*>(RowData);
	if (!RowAsBase)
	{
		return false;
	}

	DataTable->AddRow(RowName, *RowAsBase);
	return true;
}

#include "Tetrahedron.h"
#include <Ziran/CS/Util/Debug.h>
#include <Eigen/Dense>

namespace ZIRAN {

template <class T>
void barycentricWeights(
    const Vector<T, 3>& p,
    const Vector<T, 3>& a,
    const Vector<T, 3>& b,
    const Vector<T, 3>& c,
    const Vector<T, 3>& d,
    Vector<T, 4>& weights)
{
    // Construct matrix Dm from edge vectors of tetrahedron (a-d, b-d, c-d)
    Matrix<T, 3, 3> Dm;
    Dm.col(0) = a - d;
    Dm.col(1) = b - d;
    Dm.col(2) = c - d;

    // Solve for barycentric coordinates of p relative to tetrahedron vertices
    Vector<T, 3> coord_abc = Dm.partialPivLu().solve(p - d);

    // Assign first three weights and compute the fourth via complementarity
    weights.template head<3>() = coord_abc;
    weights(3) = static_cast<T>(1) - coord_abc.sum();

    // Validate weights are within [0,1] and sum to 1
    ZIRAN_ASSERT((weights.array() >= static_cast<T>(0)).all(), weights.transpose());
    ZIRAN_ASSERT((weights.array() <= static_cast<T>(1)).all(), weights.transpose());
    ZIRAN_ASSERT(std::abs(weights.array().sum() - static_cast<T>(1)) < static_cast<T>(1e-7), weights.transpose());

    // Verify reconstruction accuracy by recombining vertices with computed weights
    Vector<T, 3> reconstructed_p = Vector<T, 3>::Zero();
    reconstructed_p += weights(0) * a;
    reconstructed_p += weights(1) * b;
    reconstructed_p += weights(2) * c;
    reconstructed_p += weights(3) * d;

    ZIRAN_ASSERT((p - reconstructed_p).squaredNorm() < static_cast<T>(1e-7));
}

// Explicit template instantiations
template void barycentricWeights<double>(
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<double, 4, 1, 0, 4, 1>&);

template void barycentricWeights<float>(
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
    Eigen::Matrix<float, 3, 1, 0, 3, 1> const&,
