// Helper function to convert string to vector of bytes
std::vector<uint8_t> toBytes(const std::string& str) {
    return std::vector<uint8_t>(str.begin(), str.end());
}

// Parse a GS2 block from a string input
gs2::Block parseGS2Block(const std::string &inputCode) {
    std::vector<uint8_t> byteStream = toBytes(inputCode);
    return gs2::Block::parseBytes(byteStream);
}

// Verify parsed commands match expected byte sequences
void validateParsing(const std::string &source, const std::vector<std::string> &expectedCommands) {
    auto parsedBlock = parseGS2Block(source);
    auto commandList = parsedBlock.getCommands();

    REQUIRE(expectedCommands.size() == commandList.size());

    for (size_t idx = 0; idx < expectedCommands.size(); ++idx) {
        std::vector<uint8_t> targetBytes = toBytes(expectedCommands[idx]);
        CHECK(targetBytes == commandList[idx].getBytes());
    }
}

// Ensure parsing fails with expected exception type
void expectParseFailure(const std::string &malformedInput) {
    std::vector<uint8_t> inputBytes = toBytes(malformedInput);
    CHECK_THROWS_AS(gs2::Block::parseBytes(inputBytes), gs2::GS2Exception);
}

TEST_CASE("GS2 Code Parsing Tests") {
    // Standard ASCII text parsing
    validateParsing("Hello there", {"H", "e", "l", "l", "o", " ", "t", "h", "e", "r", "e"});

    // Unsigned byte push operations
    validateParsing("\x01\xee\x01\xdd", {"\x01\xee", "\x01\xdd"});

    // Signed short push operations
    validateParsing("\x02\xee\x01\x02\x11\x22", {"\x02\xee\x01", "\x02\x11\x22"});

    // Signed long push operations
    validateParsing("\x03\x01\x02\x03\x04\xbb", {"\x03\x01\x02\x03\x04", "\xbb"});

    // Single-character string pushes
    validateParsing("\x07\x32\x07\x42", {"\x07\x32", "\x07\x42"});

    // Multi-character string pushes
    validateParsing("\x04hello there\x05\x04\x05", {"\x04hello there\x05", "\x04\x05"});
    validateParsing("\x04gamma\x9b\x04knife\x9c\x04rattlesnake\x9d",
                    {"\x04gamma\x9b", "\x04knife\x9c", "\x04rattlesnake\x9d"});
    validateParsing("\x04???\x9e\x04!!!\x9f", {"\x04???\x9e", "\x04!!!\x9f"});

    // Implicit beginning string handling
    validateParsing("who\x05", {"\x04who\x05"});
    validateParsing("what\x06k", {"\x04what\x06", "k"});
    validateParsing("where\x9b??", {"\x04where\x9b", "?", "?"});
    validateParsing("why\x9c!!!", {"\x04why\x9c", "!", "!", "!"});
    validateParsing("how\x9d", {"\x04how\x9d"});
    validateParsing("which\x9e", {"\x04which\x9e"});
    validateParsing("\x01\x02\x03\x9f", {"\x04\x01\x02\x03\x9f"});

    // Invalid inputs that should throw exceptions
    expectParseFailure("\x01");
    expectParseFailure("\x02?");
    expectParseFailure("\x03???");
    expectParseFailure("\x04 blah blah blah");
    expectParseFailure("\x07");
    expectParseFailure("\x09");
}

TEST_CASE("GS2 Mode Switching Behavior") {
    // Line mode test case
    auto parsedCommands = parseGS2Block("\x30Hey\x05?").getCommands();
    REQUIRE(parsedCommands.size() == 4);

    // First command should be bytes with value 0x2a
    REQUIRE(parsedCommands[0].isBytes());
    CHECK(parsedCommands[0].getBytes() == std::vector<uint8_t>{ 0x2a });

    // Third command should be bytes with value 0x34
    REQUIRE(parsedCommands[2].isBytes());
    CHECK(parsedCommands[2].getBytes() == std::vector<uint8_t>{ 0x34 });

    // Fourth command should be bytes with value 0x54
    REQUIRE(parsedCommands[3].isBytes());
    CHECK(parsedCommands[3].getBytes() == std::vector<uint8_t>{ 0x54 });

    // Second command should be a nested block
    REQUIRE(parsedCommands[1].isBlock());
    auto innerBlock = parsedCommands[1].getBlock().getCommands();
    REQUIRE(innerBlock.size() == 2);

    // Check contents of the inner block
    REQUIRE(innerBlock[0].isBytes());
    CHECK(innerBlock[0].getBytes() == std::vector<uint8_t>{ 0x04, 'H', 'e', 'y', 0x05 });
    REQUIRE(innerBlock[1].isBytes());
    CHECK(innerBlock[1].getBytes() == std::vector<uint8_t>{ '?' });
}

TEST_CASE("GS2 Block Structure Validation") {
    // Simple block structure
    auto outerBlock = parseGS2Block("\x08hey\x09").getCommands();
    REQUIRE(outerBlock.size() == 2);

    // Last command is terminator byte (0)
    REQUIRE(outerBlock[1].isBytes());
    REQUIRE(outerBlock[1].getBytes() == std::vector<uint8_t>{ 0 });

    // First command is the actual block content
    REQUIRE(outerBlock[0].isBlock());
    auto innerContent = outerBlock[0].getBlock().getCommands();
    REQUIRE(innerContent.size() == 3);

    // Verify individual characters in the block
    REQUIRE(innerContent[0].isBytes());
    CHECK(innerContent[0].getBytes() == std::vector<uint8_t>{ 'h' });
    REQUIRE(innerContent[1].isBytes());
    CHECK(innerContent[1].getBytes() == std::vector<uint8_t>{ 'e' });
    REQUIRE(innerContent[2].isBytes());
    CHECK(innerContent[2].getBytes() == std::vector<uint8_t>{ 'y' });

    // Nested blocks test
    auto topLevel = parseGS2Block("\x08\x08\x08\x08").getCommands();
    for (int depth = 0; depth < 4; ++depth) {
        REQUIRE(topLevel.size() == 2);
        REQUIRE(topLevel[1].isBytes());
        CHECK(topLevel[1].getBytes() == std::vector<uint8_t>{ 0 });
        REQUIRE(topLevel[0].isBlock());

        if (depth == 3) {
            REQUIRE(topLevel[0].getBlock().getCommands().empty());
        } else {
            topLevel = topLevel[0].getBlock().getCommands();
        }
    }

    // Filter block test
    auto filterResult = parseGS2Block("\xff?!").getCommands();
    REQUIRE(filterResult.size() == 2);
    REQUIRE(filterResult[1].isBytes());
    CHECK(filterResult[1].getBytes() == std::vector<uint8_t>{ 0x35 });
    REQUIRE(filterResult[0].isBlock());
    auto filterInner = filterResult[0].getBlock().getCommands();
    REQUIRE(filterInner.size() == 2);
    REQUIRE(filterInner[0].isBytes());
    CHECK(filterInner[0].getBytes() == std::vector<uint8_t>{ '?' });
    REQUIRE(filterInner[1].isBytes());
    CHECK(filterInner[1].getBytes() == std::vector<uint8_t>{ '!' });

    // Map block test
    auto mapResult = parseGS2Block("\xfe?!").getCommands();
    REQUIRE(mapResult.size() == 2);
    REQUIRE(mapResult[1].isBytes());
    CHECK(mapResult[1].getBytes() == std::vector<uint8_t>{ 0x34 });
    REQUIRE(mapResult[0].isBlock());
    auto mapInner = mapResult[0].getBlock().getCommands();
    REQUIRE(mapInner.size() == 2);
    REQUIRE(mapInner[0].isBytes());
    CHECK(mapInner[0].getBytes() == std::vector<uint8_t>{ '?' });
    REQUIRE(mapInner[1].isBytes());
    CHECK(mapInner[1].getBytes() == std::vector<uint8_t>{ '!' });
}

