{
	using namespace Reflection;

	static auto audio_scene_def = scene("audio",
		component("ambient_sound",
			property("3D", LUMIX_PROP(AudioScene, isAmbientSound3D, setAmbientSound3D)),
			dyn_enum_property("Sound", LUMIX_PROP(AudioScene, getAmbientSoundClipIndex, setAmbientSoundClipIndex),
				&AudioScene::getClipCount, &AudioScene::getClipName)
		),
		component("audio_listener"),
