				MinAttribute(0.0f)),
			property("Delay (ms)", LUMIX_PROP(AudioScene, getChorusZoneDelay, setChorusZoneDelay),
				MinAttribute(0))
		)
	);
	registerScene(audio_scene_def);
}


// Internal implementation of the AudioSystem interface
struct AudioSystemBackend LUMIX_FINAL : public AudioSystem
{
	explicit AudioSystemBackend(Engine& ctx)
		: m_engine(ctx)
		, m_clip_mgr(ctx.getAllocator())
		, m_audio_dev(nullptr)
	{
		// Initialize reflection and Lua bindings
		registerAudioProperties(ctx.getAllocator());
		AudioScene::registerLuaAPI(ctx.getState());

		// Create audio device and clip manager
		m_audio_dev = AudioDevice::create(ctx);
		m_clip_mgr.create(AUDIO_CLIP_RESOURCE, ctx.getResourceManager());
	}


	~AudioSystemBackend()
	{
		// Cleanup resources in reverse order of creation
		AudioDevice::destroy(*m_audio_dev);
		m_clip_mgr.destroy();
	}


	// Interface implementations
	Engine& getEngine() override { return m_engine; }
	AudioDevice& getDevice() override { return *m_audio_dev; }
	ClipManager& getClipManager() override { return m_clip_mgr; }


	const char* systemName() const override { return "audio"; }


	void instantiateScenes(Universe& world) override
	{
		auto* scene = AudioScene::createInstance(*this, world, m_engine.getAllocator());
		world.addScene(scene);
	}


	void releaseScene(IScene* scene) override
	{
		AudioScene::destroyInstance(static_cast<AudioScene*>(scene));
	}


	// Member variables
	ClipManager m_clip_mgr;
	Engine& m_engine;
	AudioDevice* m_audio_dev;
};


// Plugin entry point registration
LUMIX_PLUGIN_ENTRY(audio)
{
	return LUMIX_NEW(engine.getAllocator(), AudioSystemBackend)(engine);
}


