// Helper lambda to enumerate adapters safely
void EnumerateAdapters(IDXGIFactory* pFactory, std::vector<IDXGIAdapter*>& outAdapters, bool useDefault)
{
    if (!useDefault)
    {
        UINT idx = 0;
        IDXGIAdapter* pAdapter = nullptr;
        while (pFactory->EnumAdapters(idx, &pAdapter) != DXGI_ERROR_NOT_FOUND)
        {
            outAdapters.push_back(pAdapter);
            ++idx;
            pAdapter = nullptr; // reset for next iteration safety
        }
    }
    else
    {
        IDXGIAdapter* pAdapter = nullptr;
        if (pFactory->EnumAdapters(0, &pAdapter) != DXGI_ERROR_NOT_FOUND)
            outAdapters.push_back(pAdapter);
    }
}

// Helper lambda to collect display modes below or equal to 60Hz
void CollectAcceptableDisplayModes(IDXGIOutput* pOutput, DXGI_FORMAT fmt, std::vector<DXGI_MODE_DESC>& outModes)
{
    UINT count = 0;
    if (FAILED(pOutput->GetDisplayModeList(fmt, 0, &count, nullptr)))
        return;

    std::vector<DXGI_MODE_DESC> rawModes(count);
    if (FAILED(pOutput->GetDisplayModeList(fmt, 0, &count, rawModes.data())))
        return;

    for (size_t i = 0; i < rawModes.size(); ++i)
    {
        const auto& mode = rawModes[i];
        double refreshRate = static_cast<double>(mode.RefreshRate.Numerator) / mode.RefreshRate.Denominator;
        if (refreshRate <= 60.0)
            outModes.push_back(mode);
    }
}

CD3DRenderer::CD3DRenderer(HWND& window)
{
    m_hWnd = window;

    if (!CALL_D3D_API(CreateDXGIFactory(__uuidof(IDXGIFactory), reinterpret_cast<void**>(&m_pdxgiFactory)),
                      "Failed to create DXGI Factory."))
        return;

    const bool useDefaultAdapter = gDebugSettings.GetToggleField("UseDefaultAdapter");
    EnumerateAdapters(m_pdxgiFactory, m_vAdapters, useDefaultAdapter);

    if (m_vAdapters.empty())
        return;

    IDXGIOutput* pOutput = nullptr;
    if (!CALL_D3D_API(m_vAdapters[m_uiCurrentAdapter]->EnumOutputs(0, &pOutput),
                      "Failed to enumerate adapter output #0."))
        return;

    DXGI_FORMAT format = DXGI_FORMAT_R8G8B8A8_UNORM;
    CollectAcceptableDisplayModes(pOutput, format, m_vAdapterModes);

    pOutput->Release();
}

CD3DRenderer::~CD3DRenderer()
{
    for (auto pAdapter : m_vAdapters)
        pAdapter->Release();
}

bool CD3DRenderer::InitDevice()
{
    if (m_vAdapterModes.empty() || m_uiCurrentAdapterMode >= m_vAdapterModes.size())
        return false;

    auto currentMode = m_vAdapterModes[m_uiCurrentAdapterMode];
    auto currentAdapter = m_vAdapters[m_uiCurrentAdapter];
    bool bWindowed = gDebugSettings.GetToggleField("Windowed");

    g_pDebug->printMsg("Device initialization: start", 1);

    // Resize window if needed
    RECT rc;
    GetClientRect(m_hWnd, &rc);
    UINT width = rc.right - rc.left;
    UINT height = rc.bottom - rc.top;

    if (width != currentMode.Width || height != currentMode.Height)
    {
        width = currentMode.Width;
        height = currentMode.Height;
        SetWindowPos(m_hWnd, nullptr, 0, 0, width, height, 0);
    }

    UINT createFlags = 0;
#ifdef _DEBUG
    createFlags |= D3D11_CREATE_DEVICE_DEBUG;
#endif

    D3D_DRIVER_TYPE driverTypes[] =
    {
        D3D_DRIVER_TYPE_UNKNOWN,
        D3D_DRIVER_TYPE_HARDWARE,
        D3D_DRIVER_TYPE_WARP,
        D3D_DRIVER_TYPE_REFERENCE,
    };
    const size_t numDriverTypes = sizeof(driverTypes) / sizeof(driverTypes[0]);

    D3D_FEATURE_LEVEL featureLevels[] =
    {
        D3D_FEATURE_LEVEL_12_1,
        D3D_FEATURE_LEVEL_12_0,
        D3D_FEATURE_LEVEL_11_1,
        D3D_FEATURE_LEVEL_11_0,
        D3D_FEATURE_LEVEL_10_1,
        D3D_FEATURE_LEVEL_10_0,
        D3D_FEATURE_LEVEL_9_3,
        D3D_FEATURE_LEVEL_9_2,
        D3D_FEATURE_LEVEL_9_1,
    };
    const size_t numFeatureLevels = sizeof(featureLevels) / sizeof(featureLevels[0]);

    HRESULT hr = S_OK;
    for (size_t dtIdx = 0; dtIdx < numDriverTypes; ++dtIdx)
    {
        m_driverType = driverTypes[dtIdx];
        ID3D11Device* dev = nullptr;
        ID3D11DeviceContext* ctx = nullptr;

        hr = D3D11CreateDevice(
            m_driverType == D3D_DRIVER_TYPE_HARDWARE ? nullptr : currentAdapter,
            m_driverType,
            nullptr,
            createFlags,
            featureLevels,
            static_cast<UINT>(numFeatureLevels),
            D3D11_SDK_VERSION,
            &dev,
            &m_featureLevel,
            &ctx
        );

        if (hr == E_INVALIDARG)
        {
            for (size_t flIdx = 1; flIdx < numFeatureLevels - 1; ++flIdx)
            {
                hr = D3D11CreateDevice(
                    m_driverType == D3D_DRIVER_TYPE_HARDWARE ? nullptr : currentAdapter,
                    m_driverType,
                    nullptr,
                    createFlags,
                    &featureLevels[flIdx],
                    static_cast<UINT>(numFeatureLevels - flIdx),
                    D3D11_SDK_VERSION,
                    &dev,
                    &m_featureLevel,
                    &ctx
                );
                if (SUCCEEDED(hr))
                    break;
            }
        }

        if (SUCCEEDED(hr))
        {
            m_pd3dDevice = dev;
            m_pImmediateContext = ctx;
            break;
        }
    }

    if (FAILED(hr))
    {
        g_pDebug->printError("Failed to create device, invalid input arguments");
        return false;
    }

    g_pDebug->printMsg("D3D11 Device created", 1);

    // Query debug interface
    m_pd3dDevice->QueryInterface(__uuidof(ID3D11Debug), (void**)&m_pDebug);

    // Swap Chain Creation
    IDXGIFactory2* pFactory2 = nullptr;
    if (SUCCEEDED(m_pdxgiFactory->QueryInterface(__uuidof(IDXGIFactory2), (void**)&pFactory2)))
    {
        m_pImmediateContext->QueryInterface(__uuidof(ID3DUserDefinedAnnotation), reinterpret_cast<void**>(&m_pRenderingAnnotation));

        DXGI_SWAP_CHAIN_DESC1 sd = {};
        sd.Width = currentMode.Width;
        sd.Height = currentMode.Height;
        sd.Format = currentMode.Format;
        sd.SampleDesc.Count = 1;
        sd.SampleDesc.Quality = 0;
        sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
        sd.BufferCount = 1;
        sd.Flags = bWindowed ? DXGI_SWAP_CHAIN_FLAG_ALLOW_MODE_SWITCH : 0;
        sd.SwapEffect = DXGI_SWAP_EFFECT_SEQUENTIAL;

        DXGI_SWAP_CHAIN_FULLSCREEN_DESC fsd = {};
        fsd.Scaling = currentMode.Scaling;
        fsd.ScanlineOrdering = currentMode.ScanlineOrdering;
        fsd.Windowed = bWindowed;
        fsd.RefreshRate = currentMode.RefreshRate;

        if (CALL_D3D_API(pFactory2->CreateSwapChainForHwnd(m_pd3dDevice, m_hWnd, &sd, &fsd, nullptr, &m_pSwapChain1),
                         "Failed to create swap chain using DX11.1 API."))
        {
            m_pSwapChain1->QueryInterface(__uuidof(IDXGISwapChain1), reinterpret_cast<void**>(&m_pSwapChain));
        }

        pFactory2->Release();
    }
    else
    {
        DXGI_SWAP_CHAIN_DESC sd = {};
        sd.BufferCount = 1;
        sd.BufferDesc.Width = currentMode.Width;
        sd.BufferDesc.Height = currentMode.Height;
        sd.BufferDesc.Format = currentMode.Format;
        sd.BufferDesc.RefreshRate = currentMode.RefreshRate;
        sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
        sd.OutputWindow = m_hWnd;
        sd.SampleDesc.Count = 1;
        sd.SampleDesc.Quality = 0;
        sd.Windowed = bWindowed;
        sd.Flags = bWindowed ? DXGI_SWAP_CHAIN_FLAG_ALLOW_MODE_SWITCH : 0;

        CALL_D3D_API(m_pdxgiFactory->CreateSwapChain(m_pd3dDevice, &sd, &m_pSwapChain),
                     "Failed to create swap chain using DX11 API.");
    }

    m_pdxgiFactory->Release();
    g_pDebug->printMsg("Device initialization: end", 1);
    return true;
}

void CD3DRenderer::DeInitDevice()
{
    if (m_pImmediateContext)
    {
        m_pImmediateContext->ClearState();
        m_pImmediateContext->Flush();
    }

    if (m_pSwapChain1)
    {
        m_pSwapChain1->Release();
        m_pSwapChain1 = nullptr;
    }
    else if (m_pSwapChain)
    {
        m_pSwapChain->Release();
        m_pSwapChain = nullptr;
    }

    if (m_pImmediateContext)
    {
        m_pImmediateContext->Release();
        m_pImmediateContext = nullptr;
    }

    if (m_pd3dDevice)
    {
        m_pd3dDevice->Release();
        m_pd3dDevice = nullptr;
    }

    if (m_pRenderingAnnotation)
    {
        m_pRenderingAnnotation->Release();
        m_pRenderingAnnotation = nullptr;
    }

    if (m_pDebug)
    {
        m_pDebug->ReportLiveDeviceObjects(D3D11_RLDO_DETAIL);
        m_pDebug->Release();
        m_pDebug = nullptr;
    }
}

void CD3DRenderer::BeginUpdate(RwCamera* camera)
{
    RwD3D1XRaster* pDepthRaster = GetD3D1XRaster(camera->zBuffer);
    RwD3D1XRaster* pRTRaster = GetD3D1XRaster(camera->frameBuffer);

    if (camera->frameBuffer)
    {
        auto rtTex = dynamic_cast<ID3D1XRenderTargetViewable*>(pRTRaster->resourse);
        ID3D11RenderTargetView* rtv = rtTex ? rtTex->GetRenderTargetView() : nullptr;

        if (camera->zBuffer)
        {
            auto depthTex = dynamic_cast<CD3D1XDepthStencilTexture*>(pDepthRaster->resourse);
            g_pStateMgr->SetRenderTargets(1, &rtv, depthTex->GetDepthStencilView());
        }
        else
        {
            g_pStateMgr->SetRenderTargets(1, &rtv, nullptr);
        }
    }
    else if (camera->zBuffer)
    {
        auto depthTex = dynamic_cast<CD3D1XDepthStencilTexture*>(pDepthRaster->resourse);
        g_pStateMgr->SetRenderTargets(0, nullptr, depthTex->GetDepthStencilView());
    }

    if (camera->frameBuffer)
    {
        D3D11_VIEWPORT vp = {};
        vp.Width = static_cast<FLOAT>(camera->frameBuffer->width);
        vp.Height = static_cast<FLOAT>(camera->frameBuffer->height);
        vp.MinDepth = 0.0f;
        vp.MaxDepth = 1.0f;
        vp.TopLeftX = 0;
        vp.TopLeftY = 0;
        g_pStateMgr->SetViewport(vp);
    }

    g_pStateMgr->FlushRenderTargets();
}

void CD3DRenderer::EndUpdate(RwCamera* camera)
{
    RwD3D1XRaster* pRTRaster = GetD3D1XRaster(camera->frameBuffer);
    if (camera->frameBuffer && pRTRaster->textureFlags == 64)
    {
        ID3D11UnorderedAccessView* uavs[] = { nullptr };
        m_pImmediateContext->OMSetRenderTargetsAndUnorderedAccessViews(0, nullptr, nullptr, 2, 1, uavs, nullptr);
    }
}

void CD3DRenderer::Clear(RwCamera* camera, RwRGBA& color, RwInt32 flags)
{
    RwD3D1XRaster* pDepthRaster = GetD3D1XRaster(camera->zBuffer);
    RwD3D1XRaster* pRTRaster = GetD3D1XRaster(camera->frameBuffer);

    if (flags & rwCAMERACLEARIMAGE && camera->frameBuffer)
    {
        auto rtTex = dynamic_cast<ID3D1XRenderTargetViewable*>(pRTRaster->resourse);
        float clearColor[4] = {
            static_cast<float>(color.red) / 255.0f,
            static_cast<float>(color.green) / 255.0f,
            static_cast<float>(color.blue) / 255.0f,
            static_cast<float>(color.alpha) / 255.0f
        };
        m_pImmediateContext->ClearRenderTargetView(rtTex->GetRenderTargetView(), clearColor);
    }

    if ((flags & rwCAMERACLEARZ || flags & rwCAMERACLEARSTENCIL) && camera->zBuffer)
    {
        auto depthTex = dynamic_cast<CD3D1XDepthStencilTexture*>(pDepthRaster->resourse);
        UINT clearFlags = 0;
        if (flags & rwCAMERACLEARZ) clearFlags |= D3D11_CLEAR_DEPTH;
        if (flags & rwCAMERACLEARSTENCIL) clearFlags |= D3D11_CLEAR_STENCIL;

        m_pImmediateContext->ClearDepthStencilView(depthTex->GetDepthStencilView(), clearFlags, 1.0f, 0);
    }
}

