void load_data_header(std::istream& in, DataHeader& header)
{
    size_t num_str_tags, num_real_tags, num_int_tags;
    in >> num_str_tags;
    header.string_tags.clear();
    header.string_tags.reserve(num_str_tags);
    for (size_t idx = 0; idx < num_str_tags; ++idx) {
        in >> std::quoted(header.string_tags.emplace_back());
    }

    in >> num_real_tags;
    header.real_tags.clear();
    header.real_tags.reserve(num_real_tags);
    for (size_t idx = 0; idx < num_real_tags; ++idx) {
        in >> header.real_tags.emplace_back();
    }

    in >> num_int_tags;
    header.int_tags.clear();
    header.int_tags.reserve(num_int_tags);
    for (size_t idx = 0; idx < num_int_tags; ++idx) {
        in >> header.int_tags.emplace_back();
    }

    assert(in.good());
}

namespace v41 {

void load_data_entry(
    std::istream& in, DataEntry& entry, size_t fields_per_entry, bool is_element_node_data)
{
    int32_t tag_32;
    in.read(reinterpret_cast<char*>(&tag_32), sizeof(int32_t));
    entry.tag = static_cast<size_t>(tag_32);

    if (is_element_node_data) {
        int32_t node_count;
        in.read(reinterpret_cast<char*>(&node_count), sizeof(int32_t));
        entry.num_nodes_per_element = static_cast<int>(node_count);
        entry.data.resize(fields_per_entry * static_cast<size_t>(entry.num_nodes_per_element));
    } else {
        entry.data.resize(fields_per_entry);
    }

    in.read(reinterpret_cast<char*>(entry.data.data()),
        static_cast<std::streamsize>(sizeof(double) * entry.data.size()));
}

} // namespace v41

namespace v22 {

void load_data_entry(
    std::istream& in, DataEntry& entry, size_t fields_per_entry, bool is_element_node_data)
{
    int32_t tag_32;
    in.read(reinterpret_cast<char*>(&tag_32), sizeof(int32_t));
    entry.tag = static_cast<size_t>(tag_32);

    if (is_element_node_data) {
        int32_t node_count;
        in.read(reinterpret_cast<char*>(&node_count), sizeof(int32_t));
        entry.num_nodes_per_element = static_cast<int>(node_count);
        entry.data.resize(fields_per_entry * static_cast<size_t>(entry.num_nodes_per_element));
    } else {
        entry.data.resize(fields_per_entry);
    }

    in.read(reinterpret_cast<char*>(entry.data.data()),
        static_cast<std::streamsize>(sizeof(double) * entry.data.size()));
}

} // namespace v22

void load_data(std::istream& in,
    Data& data,
    const std::string& version,
    bool is_binary,
    bool is_element_node_data)
{
    load_data_header(in, data.header);

    if (data.header.int_tags.size() < 3u) {
        throw InvalidFormat("Data requires at least 3 int tags.");
    }

    size_t fields_per_entry = static_cast<size_t>(data.header.int_tags[1]);
    size_t total_entries = static_cast<size_t>(data.header.int_tags[2]);

    data.entries.resize(total_entries);

    if (is_binary) {
        eat_white_space(in);

        if (version == "4.1") {
            size_t i = 0;
            while (i < total_entries) {
                v41::load_data_entry(in, data.entries[i], fields_per_entry, is_element_node_data);
                ++i;
            }
        } else if (version == "2.2") {
            size_t i = 0;
            while (i < total_entries) {
                v22::load_data_entry(in, data.entries[i], fields_per_entry, is_element_node_data);
                ++i;
            }
        } else {
            throw InvalidFormat("Unsupported version: " + version);
        }
    } else {
        size_t i = 0;
        while (i < total_entries) {
            DataEntry& entry = data.entries[i];
            entry.data.resize(fields_per_entry);
            in >> entry.tag;
            size_t j = 0;
            while (j < fields_per_entry) {
                in >> entry.data[j];
                ++j;
            }
            ++i;
        }
    }

    assert(in.good());
}

} // namespace internal

void load_node_data(std::istream& in, MshSpec& spec)
{
    const std::string& ver = spec.mesh_format.version;
    bool bin_flag = spec.mesh_format.file_type > 0;
    spec.node_data.emplace_back();
    internal::load_data(in, spec.node_data.back(), ver, bin_flag, false);
}

void load_element_data(std::istream& in, MshSpec& spec)
{
    const std::string& ver = spec.mesh_format.version;
    bool bin_flag = spec.mesh_format.file_type > 0;
    spec.element_data.emplace_back();
    internal::load_data(in, spec.element_data.back(), ver, bin_flag, false);
}

void load_element_node_data(std::istream& in, MshSpec& spec)
{
    const std::string& ver = spec.mesh_format.version;
    bool bin_flag = spec.mesh_format.file_type > 0;
    spec.element_node_data.emplace_back();
    internal::load_data(in, spec.element_node_data.back(), ver, bin_flag, true);
}

