#include <vector>
#include <algorithm>

// Generate all subsets (power set) of the input vector A
void generateSubsets(int position, const std::vector<int>& input, std::vector<std::vector<int>>& result, std::vector<int>& currentSubset) {
    // Base case: when we've processed all elements
    if (position == input.size()) {
        result.push_back(currentSubset);
        return;
    }

    // Exclude current element and proceed
    generateSubsets(position + 1, input, result, currentSubset);

    // Include current element
    currentSubset.push_back(input[position]);
    generateSubsets(position + 1, input, result, currentSubset);

    // Backtrack: remove the last added element
    currentSubset.pop_back();
}

std::vector<std::vector<int>> Solution::subsets(std::vector<int>& A) {
    // Sort the input array to ensure lexicographic order
    std::sort(A.begin(), A.end());

    std::vector<std::vector<int>> allSubsets;
    std::vector<int> subsetBuilder;

    // Start recursive generation from index 0
    generateSubsets(0, A, allSubsets, subsetBuilder);

    // Sort the result to ensure proper ordering of subsets
    std::sort(allSubsets.begin(), allSubsets.end());

    return allSubsets;
}

#include <cstdlib>
#include <cstring>
#include <iostream>
#include <boost/asio.hpp>
using boost::asio::local::datagram_protocol;

enum { buffer_size = 4096 };
const char *socket_prefix = "/tmp/rclogger.";

int main(int argc, char* argv[])
{
  try
  {
    if (argc != 2)
    {
      std::cerr << "Usage: rclogger <socket_path>\n";
      return 1;
    }

    boost::asio::io_service service;
    datagram_protocol::endpoint target_endpoint(argv[1]);
    datagram_protocol::socket socket(service);

    // Connect to the server endpoint
    socket.connect(target_endpoint);

    // Create unique client socket name using process ID
    std::string client_socket_path = std::string(socket_prefix) + std::to_string(::getpid());

    // Clean up any existing socket file
    ::unlink(client_socket_path.c_str());

    // Bind to our client endpoint
    datagram_protocol::endpoint client_endpoint(client_socket_path);
    socket.bind(client_endpoint);

    // Read all input into a single string
    std::string message_body;
    std::string current_line;
    while (std::getline(std::cin, current_line))
    {
      message_body.append(current_line);
      message_body.push_back('\n');
    }

    // Check message size constraint
    if (message_body.size() > buffer_size)
    {
      std::cerr << "Error: message exceeds maximum allowed size of " 
                << buffer_size << " bytes!" << std::endl;
    }

    // Send the message to server
    socket.send_to(boost::asio::buffer(message_body), target_endpoint);

    // Receive response
    char response_buffer[buffer_size];
    datagram_protocol::endpoint sender_endpoint;
    size_t bytes_received = socket.receive_from(
        boost::asio::buffer(response_buffer, buffer_size), sender_endpoint);

    std::cout << "Reply is: ";
    std::cout.write(response_buffer, bytes_received);
    std::cout << "\n";

    // Cleanup
    socket.close();
    ::unlink(client_socket_path.c_str());
  }
  catch (std::exception& exception)
  {
    std::cerr << "Exception occurred: " << exception.what() << "\n";
  }

  return 0;
}

