#include <vector>
using namespace std;

class Solution {
public:
    bool searchMatrix(vector<vector<int>>& matrix, int target) {
        if (matrix.empty() || matrix[0].empty()) return false;

        int rows = matrix.size();
        int cols = matrix[0].size();

        // Start recursive search from the full matrix boundaries
        return searchSubmatrix(matrix, 0, 0, rows - 1, cols - 1, target);
    }

private:
    bool searchSubmatrix(const vector<vector<int>>& matrix, int top, int left, int bottom, int right, int target) {
        // Base case: invalid submatrix bounds
        if (top > bottom || left > right) {
            return false;
        }

        // Binary search along the diagonal of the current submatrix
        int diagLen = min(bottom - top, right - left);
        int lo = 0;
        int hi = diagLen;

        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            int current = matrix[top + mid][left + mid];

            if (current == target) {
                return true;
            } else if (current < target) {
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }

        // Recursively search in the two remaining submatrices
        // Top-right submatrix: same top row, but columns start after diagonal end
        bool foundRight = searchSubmatrix(matrix, top, left + lo, bottom, right, target);

        // Bottom-left submatrix: same left column, but rows start after diagonal end
        bool foundBottom = searchSubmatrix(matrix, top + lo, left, bottom, right, target);

        return foundRight || foundBottom;
    }
};

