// HTTP response parser helper
static size_t ParseIntegerFromText(const char* start, const char* end)
{
    size_t value = 0;
    for (const char* p = start; p < end && isdigit(*p); ++p)
    {
        value = value * 10 + (*p - '0');
    }
    return value;
}

bool CASC_MIME_HTTP::IsDataComplete(const char* response, size_t respLen)
{
    if (response_valid == 0 && respLen > 8)
    {
        if (strncmp(response, "HTTP/1.1", 8) == 0)
        {
            const char* contentStart = strstr(response, "\r\n\r\n");
            if (contentStart != nullptr)
            {
                const char* lengthHeader = strstr(response, "Content-Length: ");
                if (lengthHeader != nullptr && lengthHeader < contentStart)
                {
                    response_valid = 0x48545450; // 'HTTP'
                    content_offset = static_cast<size_t>(contentStart + 4 - response);
                    content_length = ParseIntegerFromText(lengthHeader + 16, contentStart);
                    total_length = content_offset + content_length;
                }
            }
        }
    }
    return (response_valid != 0) && (total_length == respLen);
}

