// MIME blob line iterator
CASC_MIME_BLOB::CASC_MIME_BLOB(char* dataPtr, char* dataEnd)
    : ptr(dataPtr), end(dataEnd)
{}

CASC_MIME_BLOB::~CASC_MIME_BLOB()
{
    ptr = end = nullptr;
}

char* CASC_MIME_BLOB::GetNextLine()
{
    char* lineStart = ptr;
    while (ptr < end)
    {
        if (ptr[0] == '\r' && ptr[1] == '\n')
        {
            if (ptr[2] == '\t' || ptr[2] == ' ')
            {
                ptr += 2;
                continue;
            }
            ptr[0] = '\0';
            ptr[1] = '\0';
            ptr += 2;
            return lineStart;
        }
        ++ptr;
    }
    return nullptr;
}

