DWORD CASC_MIME_ELEMENT::Load(char* mimeBegin, char* mimeEnd, const char* boundary)
{
    CASC_MIME_ENCODING encType = MimeEncodingTextPlain;
    CASC_MIME_BLOB blob(mimeBegin, mimeEnd);
    CASC_MIME_HTTP httpInfo;
    size_t boundaryStartLen, boundaryEndLen;
    char bndStart[MAX_LENGTH_BOUNDARY + 2];
    char bndEnd[MAX_LENGTH_BOUNDARY + 4];
    DWORD err = ERROR_SUCCESS;
    bool hasMimeVersion = false;

    // Fast path for HTTP responses
    if (httpInfo.IsDataComplete(mimeBegin, mimeEnd - mimeBegin))
    {
        data.begin = CASC_ALLOC<BYTE>(httpInfo.content_length);
        if (data.begin == nullptr)
            return ERROR_NOT_ENOUGH_MEMORY;
        memcpy(data.begin, mimeBegin + httpInfo.content_offset, httpInfo.content_length);
        data.length = httpInfo.content_length;
        return ERROR_SUCCESS;
    }

    boundary[0] = '\0'; // Reset local boundary

    // Parse headers
    char* line;
    while ((line = blob.GetNextLine()) != nullptr)
    {
        if (line[0] == '\0')
        {
            blob.ptr = line + 2;
            break;
        }

        if (boundary == nullptr && !hasMimeVersion)
        {
            if (strcmp(line, "MIME-Version: 1.0") == 0 || strcmp(line, "HTTP/1.1 200 OK") == 0)
            {
                hasMimeVersion = true;
                continue;
            }
        }

        if (strncmp(line, "Content-Transfer-Encoding: ", 27) == 0)
        {
            ExtractEncoding(line + 27, encType);
            continue;
        }

        if (strncmp(line, "Content-Type: ", 14) == 0)
        {
            ExtractBoundary(line + 14);
            continue;
        }
    }

    if (boundary != nullptr || hasMimeVersion)
    {
        if (boundary[0])
        {
            CASC_MIME_ELEMENT* last = nullptr;
            CASC_MIME_ELEMENT* child;
            CASC_MIME_BLOB subBlob(blob.ptr, nullptr);

            boundaryStartLen = CascStrPrintf(bndStart, _countof(bndStart), "--%s", boundary);
            err = ERROR_SUCCESS;

            if (memcmp(subBlob.ptr, bndStart, boundaryStartLen) != 0)
                return ERROR_BAD_FORMAT;
            subBlob.ptr += boundaryStartLen;

            boundaryEndLen = CascStrPrintf(bndEnd, _countof(bndEnd), "--%s--\r\n", boundary);
            subBlob.end = strstr(subBlob.ptr, bndEnd);
            if (subBlob.end == nullptr)
                return ERROR_BAD_FORMAT;

            while (subBlob.ptr < subBlob.end)
            {
                if (subBlob.ptr[0] != '\r' || subBlob.ptr[1] != '\n')
                    return ERROR_BAD_FORMAT;
                subBlob.ptr += 2;

                char* nextBnd = strstr(subBlob.ptr, bndStart);
                if (nextBnd == nullptr)
                    return ERROR_BAD_FORMAT;

                child = AllocateAndLoadElement(subBlob.ptr, nextBnd - 2, bndStart);
                if (child == nullptr)
                {
                    err = GetCascError();
                    break;
                }

                if (folder.pChild == nullptr)
                    folder.pChild = child;
                if (last != nullptr)
                    last->folder.pNext = child;
                last = child;

                subBlob.ptr = nextBnd + boundaryStartLen;
            }
        }
        else
        {
            CASC_MIME_BLOB contentBlob(blob.ptr, nullptr);
            unsigned char* decodedBuffer = nullptr;
            size_t decodedLen = 0;
            size_t rawLen;

            if (boundary != nullptr)
            {
                contentBlob.end = strstr(contentBlob.ptr, boundary);
                if (contentBlob.end == nullptr || (contentBlob.ptr + 2) >= contentBlob.end)
                    return ERROR_BAD_FORMAT;
                contentBlob.end -= 2;
            }
            else
            {
                contentBlob.end = mimeEnd - 2;
                if (contentBlob.end[0] != '\r' || contentBlob.end[1] != '\n' || (contentBlob.ptr + 2) >= contentBlob.end)
                    return ERROR_BAD_FORMAT;
            }

            rawLen = contentBlob.end - contentBlob.ptr;
            decodedBuffer = CASC_ALLOC<unsigned char>(rawLen);
            if (decodedBuffer != nullptr)
            {
                switch (encType)
                {
                case MimeEncodingTextPlain:
                    err = DecodeTextPlain(contentBlob.ptr, contentBlob.end, decodedBuffer, &decodedLen);
                    break;
                case MimeEncodingQuotedPrintable:
                    err = DecodeQuotedPrintable(contentBlob.ptr, contentBlob.end, decodedBuffer, &decodedLen);
                    break;
                case MimeEncodingBase64:
                    err = DecodeBase64(contentBlob.ptr, contentBlob.end, decodedBuffer, &decodedLen);
                    break;
                default:
                    break;
                }

                if (err != ERROR_SUCCESS)
                {
                    CASC_FREE(decodedBuffer);
                    decodedBuffer = nullptr;
                    decodedLen = 0;
                }
            }
            else
            {
                err = ERROR_NOT_ENOUGH_MEMORY;
            }

            data.begin = decodedBuffer;
            data.length = decodedLen;
        }
    }
    else
    {
        err = ERROR_NOT_SUPPORTED;
    }

    return err;
}

#ifdef _DEBUG
void CASC_MIME_ELEMENT::Print(size_t depth, size_t index)
{
    char prefix[(MAX_LEVEL * 4) + 0x20 + 1] = {0};
    size_t spaceCount;

    spaceCount = (depth < MAX_LEVEL) ? (depth * 4) : (MAX_LEVEL * 4);
    memset(prefix, ' ', spaceCount);

    printf("%s* [%u]: ", prefix, (unsigned)index);
    memset(prefix, ' ', strlen(prefix));

    if (folder.pChild != nullptr)
    {
        printf("Folder item (boundary: %s)\n", boundary);
        folder.pChild->Print(depth + 1, 0);
    }
    else
    {
        char printable[0x20] = {0};
        for (size_t i = 0; i < data.length && i < _countof(printable) - 1; ++i)
        {
            printable[i] = (data.begin[i] >= 0x20 && data.begin[i] <= 0x7F) ? data.begin[i] : '.';
        }
        printf("Data item (%u bytes): \"%s\"\n", (unsigned)data.length, printable);
    }

    if (folder.pNext != nullptr)
        folder.pNext->Print(depth, index + 1);
}
#endif

CASC_MIME_ELEMENT* CASC_MIME_ELEMENT::AllocateAndLoadElement(char* begin, char* end, const char* boundary)
{
    CASC_MIME_ELEMENT* elem = new CASC_MIME_ELEMENT();
    if (elem == nullptr)
    {
        SetCascError(ERROR_NOT_ENOUGH_MEMORY);
        return nullptr;
    }

    DWORD res = elem->Load(begin, end, boundary);
    if (res == ERROR_SUCCESS)
        return elem;

    delete elem;
    SetCascError(res);
    return nullptr;
}

bool CASC_MIME_ELEMENT::ExtractEncoding(const char* line, CASC_MIME_ENCODING& encoding)
{
    if (_stricmp(line, "base64") == 0)
    {
        encoding = MimeEncodingBase64;
        return true;
    }
    if (_stricmp(line, "quoted-printable") == 0)
    {
        encoding = MimeEncodingQuotedPrintable;
        return true;
    }
    return false;
}

bool CASC_MIME_ELEMENT::ExtractBoundary(const char* line)
{
    const char* start = strstr(line, "boundary=\"");
    if (start != nullptr)
    {
        start += 10;
        const char* finish = strchr(start, '\"');
        if (finish != nullptr)
        {
            CascStrCopy(boundary, _countof(boundary), start, finish - start);
            return true;
        }
    }
    return false;
}

DWORD CASC_MIME_ELEMENT::DecodeTextPlain(char* srcBegin, char* srcEnd, unsigned char* dst, size_t* outLen)
{
    size_t len = static_cast<size_t>(srcEnd - srcBegin);
    memcpy(dst, srcBegin, len);
    if (outLen != nullptr)
        *outLen = len;
    return ERROR_SUCCESS;
}

DWORD CASC_MIME_ELEMENT::DecodeQuotedPrintable(char* srcBegin, char* srcEnd, unsigned char* dst, size_t* outLen)
{
    unsigned char* writePos = dst;
    char* readPos;

    for (readPos = srcBegin; readPos < srcEnd; )
    {
        if (*readPos == '=')
        {
            if (readPos[1] == '\r' && readPos[2] == '\n')
            {
                readPos += 3;
                continue;
            }
            DWORD res = BinaryFromString(readPos + 1, 2, dst);
            if (res != ERROR_SUCCESS)
                return res;
            readPos += 3;
            ++dst;
            continue;
        }
        *dst++ = static_cast<unsigned char>(*readPos++);
    }

    if (outLen != nullptr)
        *outLen = static_cast<size_t>(dst - writePos);
    return ERROR_SUCCESS;
}

DWORD CASC_MIME_ELEMENT::DecodeBase64(char* srcBegin, char* srcEnd, unsigned char* dst, size_t* outLen)
{
    unsigned char* writePos = dst;
    uint32_t bitBuffer = 0;
    uint32_t bitCount = 0;
    unsigned char ch;

    // Initialize decode table once
    if (Base64DecodeMap[0] == 0)
    {
        memset(Base64DecodeMap, INVALID_BASE64_CHAR, sizeof(Base64DecodeMap));
        for (unsigned char i = 1; i <= 0x20; ++i)
            Base64DecodeMap[i] = WHITESPACE_BASE64_CHAR;
        for (unsigned char i = 0; Base64EncodingTable[i] != '\0'; ++i)
        {
            ch = Base64EncodingTable[i];
            Base64DecodeMap[ch] = i;
        }
    }

    while (srcBegin < srcEnd && *srcBegin != '=')
    {
        if (*srcBegin >= sizeof(Base64DecodeMap))
            return ERROR_BAD_FORMAT;

        ch = Base64DecodeMap[static_cast<unsigned char>(*srcBegin++)];
        if (ch == INVALID_BASE64_CHAR)
            return ERROR_BAD_FORMAT;
        if (ch == WHITESPACE_BASE64_CHAR)
            continue;

        bitBuffer = (bitBuffer << 6) | ch;
        bitCount += 6;

        while (bitCount >= 8)
        {
            bitCount -= 8;
            ch = static_cast<unsigned char>(bitBuffer >> bitCount);
            bitBuffer &= (1U << bitCount) - 1;
            *dst++ = ch;
        }
    }

    if (outLen != nullptr)
        *outLen = static_cast<size_t>(dst - writePos);
    return ERROR_SUCCESS;
}

//-----------------------------------------------------------------------------
// Top-level MIME handler
CASC_MIME::CASC_MIME() {}
CASC_MIME::~CASC_MIME() {}

unsigned char* CASC_MIME::GiveAway(size_t* outLen)
{
    unsigned char* result = root.GiveAway(outLen);
    if (result != nullptr)
        return result;

    CASC_MIME_ELEMENT* child = root.GetChild();
    if (child != nullptr)
        return child->GiveAway(outLen);

    if (outLen != nullptr)
        *outLen = 0;
    return nullptr;
}

DWORD CASC_MIME::Load(char* data, size_t length)
{
    memset(&root, 0, sizeof(CASC_MIME_ELEMENT));
    return root.Load(data, data + length);
}

DWORD CASC_MIME::Load(LPCTSTR filename)
{
    char* fileData = nullptr;
    DWORD fileSize = 0;
    DWORD err = LoadFileToMemory(filename, &fileSize, reinterpret_cast<void**>(&fileData));
    if (err == ERROR_SUCCESS)
    {
        err = Load(fileData, fileSize);
        CASC_FREE(fileData);
    }
    return err;
}

