class sqlrconfigsImpl {
public:
	sqlrconfigsImpl(sqlrpaths *sqlrpth) {
		debugFunction();
		libexecDir = sqlrpth->getLibExecDir();
		configInstance = nullptr;
		dynamicLoader = nullptr;
	}

	~sqlrconfigsImpl() {
		debugFunction();
		delete configInstance;
		delete dynamicLoader;
	}

	void retrieveActiveIds(const char *connectionUrls,
							linkedlist<char*> *idList) {
		debugFunction();

		if (!connectionUrls || !idList) return;

		char **urlArray = nullptr;
		uint64_t urlCount = 0;
		charstring::split(connectionUrls, ",", true, &urlArray, &urlCount);

		for (uint64_t idx = 0; idx < urlCount; ++idx) {
			const char *currentUrl = urlArray[idx];
			char *proto = nullptr;

			const char *colonPos = charstring::findFirst(currentUrl, ':');
			if (colonPos) {
				proto = charstring::duplicate(currentUrl, colonPos - currentUrl);
			}

			if (proto) {
				attemptLoadConfig(proto);
				delete[] proto;
			}

			if (!configInstance) {
				attemptLoadConfig("xmldom");
			}

			if (configInstance) {
				configInstance->getEnabledIds(currentUrl, idList);
			}

			cleanupCurrentConfig();
		}

		for (uint64_t i = 0; i < urlCount; ++i) {
			delete[] urlArray[i];
		}
		delete[] urlArray;
	}

	sqlrconfig *instantiateConfig(const char *connectionUrls, const char *identifier) {
		debugFunction();

		if (charstring::isNullOrEmpty(connectionUrls) || charstring::isNullOrEmpty(identifier)) {
			return nullptr;
		}

		debugPrintf("urls: %s\n", connectionUrls);
		debugPrintf("id: %s\n", identifier);

		char **urlArray = nullptr;
		uint64_t urlCount = 0;
		charstring::split(connectionUrls, ",", true, &urlArray, &urlCount);

		bool loadedSuccessfully = false;
		for (uint64_t i = 0; i < urlCount && !loadedSuccessfully; ++i) {
			const char *url = urlArray[i];
			debugPrintf("    url: %s\n", url);

			char *proto = nullptr;
			const char *colonPos = charstring::findFirst(url, ':');
			if (colonPos) {
				proto = charstring::duplicate(url, colonPos - url);
			}

			if (proto) {
				attemptLoadConfig(proto);
				delete[] proto;
			}

			if (!configInstance) {
				attemptLoadConfig("xmldom");
			}

			if (configInstance) {
				if (configInstance->load(url, identifier)) {
					loadedSuccessfully = true;
				} else {
					delete configInstance;
					configInstance = nullptr;
				}
			}
		}

		for (uint64_t i = 0; i < urlCount; ++i) {
			delete[] urlArray[i];
		}
		delete[] urlArray;

		if (!configInstance) {
			stderror.printf("Couldn't find id %s.\n", identifier);
		}

		return configInstance;
	}

private:
	char *libexecDir;
	sqlrconfig *configInstance;
	dynamiclib *dynamicLoader;

	void attemptLoadConfig(const char *moduleName) {
		debugFunction();
		debugPrintf("loading config: %s\n", moduleName);

#ifdef SQLRELAY_ENABLE_SHARED
		stringbuffer modulePath;
		modulePath.append(libexecDir);
		modulePath.append(SQLR);
		modulePath.append("config_");
		modulePath.append(moduleName)->append(".")->append(SQLRELAY_MODULESUFFIX);

		dynamicLoader = new dynamiclib();
		if (!dynamicLoader->open(modulePath.getString(), true, true)) {
			debugPrintf("failed to load config module: %s\n", moduleName);
			char *err = dynamicLoader->getError();
			debugPrintf("%s\n", err);
			delete[] err;
			delete dynamicLoader;
			dynamicLoader = nullptr;
			return;
		}

		stringbuffer funcName;
		funcName.append("new_sqlrconfig_")->append(moduleName);
		sqlrconfig *(*factoryFunc)() =
			(sqlrconfig *(*)()) dynamicLoader->getSymbol(funcName.getString());

		if (!factoryFunc) {
			debugPrintf("failed to create config: %s\n", moduleName);
			char *err = dynamicLoader->getError();
			debugPrintf("%s\n", err);
			delete[] err;
			dynamicLoader->close();
			delete dynamicLoader;
			dynamicLoader = nullptr;
			return;
		}

		configInstance = (*factoryFunc)();
#else
		#include "sqlrconfigassignments.cpp"
		{
			configInstance = nullptr;
		}
#endif
	}

	void cleanupCurrentConfig() {
		delete configInstance;
		configInstance = nullptr;
		delete dynamicLoader;
		dynamicLoader = nullptr;
	}
};

// Wrapper to match original interface
sqlrconfigs::sqlrconfigs(sqlrpaths *sqlrpth) : impl(new sqlrconfigsImpl(sqlrpth)) {}
sqlrconfigs::~sqlrconfigs() { delete impl; }

void sqlrconfigs::getEnabledIds(const char *urls, linkedlist<char*> *idlist) {
	impl->retrieveActiveIds(urls, idlist);
}

sqlrconfig *sqlrconfigs::load(const char *urls, const char *id) {
	return impl->instantiateConfig(urls, id);
}

void sqlrconfigs::loadConfig(const char *module) {
	impl->attemptLoadConfig(module);
}

#include <BladePCH.h>
#include <utility/StringTable.h>

namespace Blade
{
	/************************************************************************/
	/*                                                                      */
	/************************************************************************/
	//////////////////////////////////////////////////////////////////////////
	tchar* StringTable::readStrings(IOBuffer& buffer, StringInfoList& info, uint32& count, uint32& bytes, IPool* pool/* = Memory::getResourcePool() */)
	{
		if (!pool)
		{
			assert(false);
			return nullptr;
		}

		count = 0u;
		bytes = 0u;

		buffer.read(&count);
		buffer.read(&bytes);

		if (count == 0u || bytes == 0u)
			return nullptr;

		info.resize(count); // assuming create() is equivalent to resize + allocation

		IOBuffer tempBuffer;
		uint32 currentIndex = 0u;
		while (currentIndex < count)
		{
			TString utf8String;
			buffer.readTString(utf8String);
			tempBuffer.writeTStringRAW(utf8String);

			if (currentIndex == 0u)
				info[currentIndex].start = 0u;
			else
				info[currentIndex].start = info[currentIndex - 1].start + info[currentIndex - 1].size + 1u;

			info[currentIndex].size = static_cast<uint32>(utf8String.size());
			++currentIndex;
		}

		assert(buffer.eof());
		bytes = static_cast<uint32>(tempBuffer.tell());

		tchar* stringBuffer = static_cast<tchar*>(pool->allocate(static_cast<size_t>(bytes)));
		std::copy_n(tempBuffer.getData(), static_cast<size_t>(bytes), stringBuffer);
		return stringBuffer;
	}

	//////////////////////////////////////////////////////////////////////////
	tchar* StringTable::readStrings(const HSTREAM& stream, StringInfoList& info, uint32& count, uint32& bytes, IPool* pool/* = Memory::getResourcePool()*/)
	{
		if (!stream || !pool || !(stream->getAccesMode() & IStream::AM_READ))
			return nullptr;

		count = 0u;
		bytes = 0u;

		stream->readAtom(count);
		stream->readAtom(bytes);

		if (count == 0u || bytes == 0u)
			return nullptr;

		IOBuffer internalBuffer;
		const size_t requiredCapacity = static_cast<size_t>(bytes) + sizeof(uint32) * 2u;
		internalBuffer.reserve(requiredCapacity);

		internalBuffer.write(&count);
		internalBuffer.write(&bytes);
		stream->readData(internalBuffer.getCurrentData(), bytes);
		internalBuffer.rewind();

		return readStrings(internalBuffer, info, count, bytes, pool);
	}

	//////////////////////////////////////////////////////////////////////////
	bool StringTable::writeStrings(IOBuffer& buffer, const TString* stringArray, uint32 count)
	{
		if (!stringArray && count != 0u)
		{
			assert(false);
			return false;
		}

		IOBuffer tempBuffer;
		for (uint32 i = 0u; i < count; ++i)
			tempBuffer.writeTString(stringArray[i]);

		buffer.write(&count);
		const uint32 totalBytes = static_cast<uint32>(tempBuffer.tell());
		buffer.write(&totalBytes);
		buffer.writeData(tempBuffer.getData(), totalBytes);

		return true;
	}

	//////////////////////////////////////////////////////////////////////////
	bool StringTable::writeStrings(const HSTREAM& stream, const TString* stringArray, uint32 count)
	{
		IOBuffer localBuffer;
		if (stream && (stream->getAccesMode() & IStream::AM_WRITE) &&
			StringTable::writeStrings(localBuffer, stringArray, count))
		{
			return localBuffer.saveToStream(stream);
		}
		return false;
	}

	/************************************************************************/
	/*                                                                      */
	/************************************************************************/
	//////////////////////////////////////////////////////////////////////////
	bool StringTableCache::persist(const TStringParam& params, StringTable& table, IPool* pool/* = Memory::getResourcePool()*/)
	{
		IOBuffer serializationBuffer;
		if (!StringTable::writeStrings(serializationBuffer, params))
			return false;

		serializationBuffer.rewind();
		return StringTable::readStrings(serializationBuffer, table, pool);
	}

}// namespace Blade

