UNiagaraDataInterfaceColorCurve::UNiagaraDataInterfaceColorCurve(FObjectInitializer const& ObjectInitializer)
	: Super(ObjectInitializer)
{
	RefreshLookupTable();
}

void UNiagaraDataInterfaceColorCurve::PostInitProperties()
{
	Super::PostInitProperties();

	if (IsDefaultObject())
	{
		FNiagaraTypeRegistry::Register(FNiagaraTypeDefinition(GetClass()), true, false, false);
	}
	RefreshLookupTable();
}

void UNiagaraDataInterfaceColorCurve::PostLoad()
{
	Super::PostLoad();
	RefreshLookupTable();
}

#if WITH_EDITOR
void UNiagaraDataInterfaceColorCurve::PostEditChangeProperty(struct FPropertyChangedEvent& PropertyChangedEvent)
{
	Super::PostEditChangeProperty(PropertyChangedEvent);

	const FName PropName = PropertyChangedEvent.Property ? PropertyChangedEvent.Property->GetFName() : NAME_None;
	if (PropName == GET_MEMBER_NAME_CHECKED(UNiagaraDataInterfaceColorCurve, SourceCurveAsset))
	{
		UCurveLinearColor* LoadedCurve = Cast<UCurveLinearColor>(SourceCurveAsset.TryLoad());
		if (LoadedCurve)
		{
			Modify();

			ChannelRed.FloatCurves[0]   = LoadedCurve->FloatCurves[0];
			ChannelGreen.FloatCurves[0] = LoadedCurve->FloatCurves[1];
			ChannelBlue.FloatCurves[0]  = LoadedCurve->FloatCurves[2];
			ChannelAlpha.FloatCurves[0] = LoadedCurve->FloatCurves[3];

			RefreshLookupTable();
		}
	}
}
#endif

void UNiagaraDataInterfaceColorCurve::RefreshLookupTable()
{
	ShaderLUT.Reset();
	for (uint32 Index = 0; Index < LUTResolution; ++Index)
	{
		float T = static_cast<float>(Index) / static_cast<float>(LUTResolution);
		FLinearColor Sample(
			ChannelRed.FloatCurves[0].Eval(T),
			ChannelGreen.FloatCurves[0].Eval(T),
			ChannelBlue.FloatCurves[0].Eval(T),
			ChannelAlpha.FloatCurves[0].Eval(T)
		);

		ShaderLUT.Emplace(Sample.R);
		ShaderLUT.Emplace(Sample.G);
		ShaderLUT.Emplace(Sample.B);
		ShaderLUT.Emplace(Sample.A);
	}
	bGPUBufferNeedsUpdate = true;
}

bool UNiagaraDataInterfaceColorCurve::CopyTo(UNiagaraDataInterface* Target) const
{
	if (!Super::CopyTo(Target))
	{
		return false;
	}

	UNiagaraDataInterfaceColorCurve* TargetColorCurve = CastChecked<UNiagaraDataInterfaceColorCurve>(Target);
	TargetColorCurve->ChannelRed   = ChannelRed;
	TargetColorCurve->ChannelGreen = ChannelGreen;
	TargetColorCurve->ChannelBlue  = ChannelBlue;
	TargetColorCurve->ChannelAlpha = ChannelAlpha;

	TargetColorCurve->RefreshLookupTable();
	return true;
}

bool UNiagaraDataInterfaceColorCurve::Equals(const UNiagaraDataInterface* OtherObj) const
{
	if (!Super::Equals(OtherObj))
	{
		return false;
	}

	const UNiagaraDataInterfaceColorCurve* OtherColorCurve = CastChecked<const UNiagaraDataInterfaceColorCurve>(OtherObj);
	return OtherColorCurve->ChannelRed   == ChannelRed &&
		   OtherColorCurve->ChannelGreen == ChannelGreen &&
		   OtherColorCurve->ChannelBlue  == ChannelBlue &&
		   OtherColorCurve->ChannelAlpha == ChannelAlpha;
}

void UNiagaraDataInterfaceColorCurve::GetCurveData(TArray<FCurveData>& OutCurveList)
{
	OutCurveList.Emplace(&ChannelRed.FloatCurves[0], TEXT("Red"),   FLinearColor::Red);
	OutCurveList.Emplace(&ChannelGreen.FloatCurves[0], TEXT("Green"), FLinearColor::Green);
	OutCurveList.Emplace(&ChannelBlue.FloatCurves[0],  TEXT("Blue"),  FLinearColor::Blue);
	OutCurveList.Emplace(&ChannelAlpha.FloatCurves[0], TEXT("Alpha"), FLinearColor::White);
}

void UNiagaraDataInterfaceColorCurve::GetFunctions(TArray<FNiagaraFunctionSignature>& OutFuncList)
{
	FNiagaraFunctionSignature Sig;
	Sig.Name = TEXT("SampleColorCurve");
	Sig.bMemberFunction = true;
	Sig.bRequiresContext = false;
	Sig.Inputs.Emplace(FNiagaraVariable(FNiagaraTypeDefinition(GetClass()), TEXT("ColorCurve")));
	Sig.Inputs.Emplace(FNiagaraVariable(FNiagaraTypeDefinition::GetFloatDef(), TEXT("T")));
	Sig.Outputs.Emplace(FNiagaraVariable(FNiagaraTypeDefinition::GetColorDef(), TEXT("Result")));
	OutFuncList.Emplace(MoveTemp(Sig));
}

bool UNiagaraDataInterfaceColorCurve::GetFunctionHLSL(FString FuncName, TArray<DIGPUBufferParamDescriptor>& DescList, FString& InterfaceID, FString& HLSLOut)
{
	const FString BufferVar = DescList[0].BufferParamName;
	HLSLOut += TEXT("void ") + FuncName + TEXT("(in float In_T, out float4 Out_Result) \n{\n");

	const int32 LUTSize = LUTResolution;
	HLSLOut += FString::Printf(TEXT("\t Out_Result.x = %s[(int)(In_T * %d) * 4 + 0];\n"), *BufferVar, LUTSize);
	HLSLOut += FString::Printf(TEXT("\t Out_Result.y = %s[(int)(In_T * %d) * 4 + 1];\n"), *BufferVar, LUTSize);
	HLSLOut += FString::Printf(TEXT("\t Out_Result.z = %s[(int)(In_T * %d) * 4 + 2];\n"), *BufferVar, LUTSize);
	HLSLOut += FString::Printf(TEXT("\t Out_Result.w = %s[(int)(In_T * %d) * 4 + 3];\n"), *BufferVar, LUTSize);
	HLSLOut += TEXT("\n}\n");

	return true;
}

void UNiagaraDataInterfaceColorCurve::GetBufferDefinitionHLSL(FString DI_ID, TArray<DIGPUBufferParamDescriptor>& BufferDescs, FString& HLSLOut)
{
	const FString BufferName = TEXT("CurveLUT") + DI_ID;
	HLSLOut += TEXT("Buffer<float> ") + BufferName + TEXT(";\n");
	BufferDescs.Emplace(DIGPUBufferParamDescriptor(BufferName, 0));
}

void UNiagaraDataInterfaceColorCurve::SetupBuffers(TArray<DIGPUBufferParamDescriptor>& DescList)
{
	for (DIGPUBufferParamDescriptor& Desc : DescList)
	{
		GPUBuffers.Emplace(FNiagaraDataInterfaceBufferData(Desc.BufferParamName));
	}
}

TArray<FNiagaraDataInterfaceBufferData>& UNiagaraDataInterfaceColorCurve::GetBufferDataArray()
{
	check(IsInRenderingThread());

	if (bGPUBufferNeedsUpdate)
	{
		check(GPUBuffers.Num() > 0);
		FNiagaraDataInterfaceBufferData& GPUData = GPUBuffers[0];

		GPUData.Buffer.Release();
		GPUData.Buffer.Initialize(sizeof(float), LUTResolution * 4, EPixelFormat::PF_R32_FLOAT, BUF_Volatile);

		const uint32 ByteSize = ShaderLUT.Num() * sizeof(float);
		int32* RawData = static_cast<int32*>(RHILockVertexBuffer(GPUData.Buffer.Buffer, 0, ByteSize, EResourceLockMode::RLM_WriteOnly));
		FPlatformMemory::Memcpy(RawData, ShaderLUT.GetData(), ByteSize);
		RHIUnlockVertexBuffer(GPUData.Buffer.Buffer);

		bGPUBufferNeedsUpdate = false;
	}

	return GPUBuffers;
}

