FVMExternalFunction UNiagaraDataInterfaceColorCurve::GetVMExternalFunction(const FVMExternalFunctionBindingInfo& Info, void* InstancePtr)
{
	if (Info.Name == TEXT("SampleColorCurve") && Info.GetNumInputs() == 1 && Info.GetNumOutputs() == 4)
	{
		return TNDIParamBinder<0, float, NDI_FUNC_BINDER(UNiagaraDataInterfaceColorCurve, SampleFromCurve)>::Bind(this, Info, InstancePtr);
	}
	else
	{
		UE_LOG(LogNiagara, Error, TEXT("Invalid function binding for Niagara Data Interface.\n\tExpected: SampleColorCurve\n\tActual: %s\n\tInputs: %d (expected 1)\n\tOutputs: %d (expected 4)"),
			*Info.Name.ToString(), Info.GetNumInputs(), Info.GetNumOutputs());
		return FVMExternalFunction{};
	}
}

template<typename T>
void UNiagaraDataInterfaceColorCurve::SampleFromCurve(FVectorVMContext& Context)
{
	T ParamX(Context);
	FRegisterHandler<float> OutR(Context);
	FRegisterHandler<float> OutG(Context);
	FRegisterHandler<float> OutB(Context);
	FRegisterHandler<float> OutA(Context);

	for (int32 i = 0; i < Context.NumInstances; ++i)
	{
		const float t = ParamX.Get();
		const FLinearColor Sampled(
			ChannelRed.FloatCurves[0].Eval(t),
			ChannelGreen.FloatCurves[0].Eval(t),
			ChannelBlue.FloatCurves[0].Eval(t),
			ChannelAlpha.FloatCurves[0].Eval(t)
		);

		*OutR.GetDest() = Sampled.R;
		*OutG.GetDest() = Sampled.G;
		*OutB.GetDest() = Sampled.B;
		*OutA.GetDest() = Sampled.A;

		ParamX.Advance();
		OutR.Advance();
		OutG.Advance();
		OutB.Advance();
		OutA.Advance();
	}
}

