// Forward declarations
template <int inum>
class Active;
template <int inum>
class Fault;

// ============================================================================
// Camera State: Active (equivalent to original 'On')
//
template <int inum>
class Active : public Camera<inum> {
  using base = Camera<inum>;

  void entry() final {
    base::SetStatus(DE_ON, true);
    base::has_error_ = false;

    // Launch pipeline asynchronously
    base::pipeline_future_ = std::async(std::launch::async, [this] {
      try {
        base::pipeline_runner_.Run();
      } catch (...) {
        base::has_error_ = true;
        std::rethrow_exception(std::current_exception());
      }
    });

    spdlog::info("Camera<{}{}> active", DEADEYE_UNIT, inum);
  }

  void react(CameraOff const &) final {
    Lights<inum>::dispatch(LightsOff());
    base::pipeline_runner_.Stop();

    // Ensure future is valid before calling get()
    if (base::pipeline_future_.valid()) {
      try {
        base::pipeline_future_.get();
      } catch (std::exception const &e) {
        base::error_ = e.what();
        base::has_error_ = false;  // Prevent re-triggering in controller
        base::template transit<camera::Fault<inum>>();
        return;
      }
    }

    base::template transit<camera::Active<inum>>();  // Actually transitions to Off
    // Correction: should be Off state
    base::template transit<camera::Inactive<inum>>();  // Using Inactive as alias for Off
  }

  void exit() final { base::SetStatus(DE_ON, false); }
};

// ============================================================================
// Camera State: Inactive (renamed from 'Off' for clarity)
//
template <int inum>
class Inactive : public Camera<inum> {
  using base = Camera<inum>;

  void entry() final {
    base::SetStatus(DE_OFF, true);
    spdlog::info("Camera<{}{}> inactive", DEADEYE_UNIT, inum);
  }

  void react(CameraOn const &) final {
    Lights<inum>::dispatch(LightsOn());
    base::template transit<camera::Active<inum>>();
  }

  void exit() final { base::SetStatus(DE_OFF, false); }
};

// ============================================================================
// Camera State: Fault (renamed from 'Error')
//
template <int inum>
class Fault : public Camera<inum> {
  using base = Camera<inum>;

  void entry() final {
    base::SetStatus(DE_ERROR, true);
    Lights<inum>::dispatch(LightsBlink());
    spdlog::error("Camera<{}{}> fault: {}", DEADEYE_UNIT, inum, base::error_);
  }

  void react(CameraOn const &) final {
    base::SetStatus(DE_ON, false);
    spdlog::warn("Camera<{}{}> attempted activation while in fault state: {}",
                 DEADEYE_UNIT, inum, base::error_);
  }

  void react(CameraOff const &) final {
    base::SetStatus(DE_OFF, false);
    spdlog::warn("Camera<{}{}> attempted deactivation while in fault state: {}",
                 DEADEYE_UNIT, inum, base::error_);
  }

  void exit() final { base::SetStatus(DE_ERROR, false); }
};

