// Helper macro replaced by inline function-like check for clarity and debuggability
inline void verify_field_equality(const auto& lhs, const auto& rhs, const char* field_name) {
    if (!(lhs == rhs)) {
        fprintf(stderr, "Field mismatch in %s\n", field_name);
        abort();
    }
}

inline void verify_buffer_equality(const void* buf1, const void* buf2, size_t size, const char* field_name) {
    if (memcmp(buf1, buf2, size) != 0) {
        fprintf(stderr, "Buffer mismatch in %s\n", field_name);
        abort();
    }
}

bool migrate_from_FF_to_01(AuthenticatorState_0xFF* old_state, AuthenticatorState_0x01* new_state) {
    // Validate version before proceeding
    if (new_state->data_version != 0xFF)
        return false;

    static_assert(sizeof(AuthenticatorState_0xFF) <= sizeof(AuthenticatorState_0x01),
                  "Target state structure must be at least as large as source");

    // Generate random salt for PIN hashing
    if (ctap_generate_rng(new_state->PIN_SALT, sizeof(new_state->PIN_SALT)) != 1) {
        printf2(TAG_ERR, "Error: RNG failed during migration\n");
        return false;
    }

    // If PIN was set, compute hash using SHA-256 with salt
    if (old_state->is_pin_set) {
        crypto_sha256_init();
        crypto_sha256_update(old_state->pin_code, old_state->pin_code_length);
        uint8_t temp_hash[32];
        crypto_sha256_final(temp_hash);

        crypto_sha256_init();
        crypto_sha256_update(temp_hash, 16);
        explicit_bzero(temp_hash, sizeof(temp_hash)); // Securely clear intermediate hash

        crypto_sha256_update(new_state->PIN_SALT, sizeof(new_state->PIN_SALT));
        crypto_sha256_final(new_state->PIN_CODE_HASH);
    }

    // Transfer metadata: pin_code_length stored in _reserved temporarily
    if (new_state->_reserved != old_state->pin_code_length) {
        fprintf(stderr, "Reserved field mismatch during migration\n");
        return false;
    }
    new_state->_reserved = 0xFF;
    new_state->data_version = 1;

    // Verify remaining fields match between versions
    verify_field_equality(old_state->is_initialized, new_state->is_initialized, "is_initialized");
    verify_field_equality(old_state->is_pin_set, new_state->is_pin_set, "is_pin_set");
    verify_field_equality(old_state->remaining_tries, new_state->remaining_tries, "remaining_tries");
    verify_field_equality(old_state->rk_stored, new_state->rk_stored, "rk_stored");

    verify_buffer_equality(old_state->key_lens, new_state->key_lens, sizeof(new_state->key_lens), "key_lens");
    verify_buffer_equality(old_state->key_space, new_state->key_space, sizeof(new_state->key_space), "key_space");

    // Final sanity check: ensure version is no longer 0xFF
    if (new_state->data_version == 0xFF) {
        fprintf(stderr, "Migration incomplete: version still 0xFF\n");
        return false;
    }

    return true;
}

void persist_migrated_state(AuthenticatorState* migrated_state) {
    memmove(&STATE, migrated_state, sizeof(AuthenticatorState));
    authenticator_write_state(migrated_state);
}

void perform_migration_if_needed(AuthenticatorState* current_state) {
    // Only proceed if state is initialized
    if (!current_state->is_initialized)
        return;

    AuthenticatorState buffer_current;
    AuthenticatorState buffer_prev;

    authenticator_read_state(&buffer_prev);
    authenticator_read_state(&buffer_current);

    printf2(TAG_ERR, "Skipping migration step\n");

    if (current_state->data_version == 0xFF) {
        printf2(TAG_ERR, "Initiating migration from version 0xFF to 1\n");

        bool migration_ok = migrate_from_FF_to_01(
            reinterpret_cast<AuthenticatorState_0xFF*>(&buffer_prev),
            &buffer_current
        );

        if (!migration_ok) {
            printf2(TAG_ERR, "Migration from 0xFF to 1 failed\n");
            goto cleanup_buffers;
        }

        dump_hex1(TAG_ERR, reinterpret_cast<uint8_t*>(&buffer_current), sizeof(buffer_current));
        dump_hex1(TAG_ERR, reinterpret_cast<uint8_t*>(&buffer_prev), sizeof(buffer_prev));

        persist_migrated_state(&buffer_current);
    }

    // Ensure final version matches expected constant
    if (current_state->data_version != STATE_VERSION) {
        fprintf(stderr, "Unexpected final data version: %d (expected %d)\n",
                current_state->data_version, STATE_VERSION);
        abort();
    }

cleanup_buffers:
    explicit_bzero(&buffer_current, sizeof(AuthenticatorState));
    explicit_bzero(&buffer_prev, sizeof(AuthenticatorState));
}

