CorrelMatAna2D::CorrelMatAna2D(int Nima)
{
    Nbr_Image = Nima;
    MatCor.alloc(Nima);
    TabMean.alloc(Nima);
    CorrelMat.alloc(Nbr_Image, Nbr_Image);
    TabMean.init();
}

/************************************************************/
void CorrelMatAna2D::print()
{
    for (int idx = 0; idx < Nbr_Image; ++idx)
        std::cout << "image " << (idx + 1) << ": mean = " << TabMean(idx) << std::endl;
    MatCor.print();
}

/************************************************************/
void CorrelMatAna2D::subtract_mean(Ifloat *TabIma)
{
    int imgIdx, pixelIdx;
    int rows = TabIma[0].nl();
    int cols = TabIma[0].nc();
    int totalPixels = rows * cols;

    for (imgIdx = 0; imgIdx < Nbr_Image; ++imgIdx)
    {
        TabMean(imgIdx) = average(TabIma[imgIdx]);
        for (pixelIdx = 0; pixelIdx < totalPixels; ++pixelIdx)
            TabIma[imgIdx](pixelIdx) -= TabMean(imgIdx);
    }
}

/************************************************************/
void CorrelMatAna2D::add_mean(Ifloat *TabIma)
{
    int imgIdx, pixelIdx;
    int rows = TabIma[0].nl();
    int cols = TabIma[0].nc();
    int totalPixels = rows * cols;

    for (imgIdx = 0; imgIdx < Nbr_Image; ++imgIdx)
    {
        for (pixelIdx = 0; pixelIdx < totalPixels; ++pixelIdx)
            TabIma[imgIdx](pixelIdx) += TabMean(imgIdx);
    }
}

/************************************************************/
void CorrelMatAna2D::compute(Ifloat *TabIma, float ValMin)
{
    int rowIdx, colIdx;

    // Initialize correlation matrix
    CorrelMat.init();

    // Set diagonal entries to 1.0
    for (rowIdx = 0; rowIdx < Nbr_Image; ++rowIdx)
        CorrelMat(rowIdx, rowIdx) = 1.0f;

    // Compute upper-triangular part of symmetric correlation matrix
    for (rowIdx = 0; rowIdx < Nbr_Image; ++rowIdx)
    {
        for (colIdx = rowIdx + 1; colIdx < Nbr_Image; ++colIdx)
        {
            if (ValMin > 0.0f)
                CorrelMat(rowIdx, colIdx) = correlation(TabIma[rowIdx], TabIma[colIdx], ValMin);
            else
                CorrelMat(rowIdx, colIdx) = correlation(TabIma[rowIdx], TabIma[colIdx]);

            // Enforce symmetry
            CorrelMat(colIdx, rowIdx) = CorrelMat(rowIdx, colIdx);
        }
    }

    // Perform eigenvalue decomposition
    MatCor.compute_eigen(CorrelMat);
}

/************************************************************/
void CorrelMatAna2D::transform(Ifloat *TabImaIn, Ifloat *TabImaOut)
{
    int x, y, k;
    fltarray inputVec(Nbr_Image);
    fltarray outputVec(Nbr_Image);

    int height = TabImaIn[0].nl();
    int width  = TabImaIn[0].nc();

    for (x = 0; x < height; ++x)
    {
        for (y = 0; y < width; ++y)
        {
            for (k = 0; k < Nbr_Image; ++k)
                inputVec(k) = TabImaIn[k](x, y);

            MatCor.transform(inputVec, outputVec);

            for (k = 0; k < Nbr_Image; ++k)
                TabImaOut[k](x, y) = outputVec(k);
        }
    }
}

/************************************************************/
void CorrelMatAna2D::invtransform(Ifloat *TabImaIn, Ifloat *TabImaOut)
{
    int x, y, k;
    fltarray inputVec(Nbr_Image);
    fltarray outputVec(Nbr_Image);

    int height = TabImaIn[0].nl();
    int width  = TabImaIn[0].nc();

    for (x = 0; x < height; ++x)
    {
        for (y = 0; y < width; ++y)
        {
            for (k = 0; k < Nbr_Image; ++k)
                inputVec(k) = TabImaIn[k](x, y);

            MatCor.invtransform(inputVec, outputVec);

            for (k = 0; k < Nbr_Image; ++k)
                TabImaOut[k](x, y) = outputVec(k);
        }
    }
}

/************************************************************/
void CorrelMatAna2D::invsubtransform(Ifloat *TabImaIn, Ifloat *TabImaOut,
                                     int NbrEigen, int *TabKill)
{
    int x, y, k;
    fltarray inputVec(Nbr_Image);
    fltarray outputVec(Nbr_Image);

    int effectiveComponents = NbrEigen;
    if ((effectiveComponents < 1) || (effectiveComponents > Nbr_Image))
        effectiveComponents = Nbr_Image;

    int height = TabImaIn[0].nl();
    int width  = TabImaIn[0].nc();

    for (x = 0; x < height; ++x)
    {
        for (y = 0; y < width; ++y)
        {
            for (k = 0; k < effectiveComponents; ++k)
            {
                if ((TabKill != nullptr) && (TabKill[k] == 1))
                    inputVec(k) = 0.0f;
                else
                    inputVec(k) = TabImaIn[k](x, y);
            }

            MatCor.invtransform(inputVec, outputVec, effectiveComponents);

            for (k = 0; k < Nbr_Image; ++k)
                TabImaOut[k](x, y) = outputVec(k);
        }
    }
}

