// Register required subresource metadata for the copy operation
inline void Vulkan::CopyImagePass::RegisterSubresources(std::span<SubresourceMetadataPayload> inoutMetadataPayloads)
{
    assert(inoutMetadataPayloads.size() == static_cast<size_t>(PassSubresourceId::Count));

    const uint32_t sourceIndex = static_cast<uint32_t>(PassSubresourceId::SrcImage);
    const uint32_t destIndex   = static_cast<uint32_t>(PassSubresourceId::DstImage);

    // Source image configuration
    inoutMetadataPayloads[sourceIndex].Layout = VK_IMAGE_LAYOUT_TRANSFER_SRC_OPTIMAL;
    inoutMetadataPayloads[sourceIndex].Usage  = VK_IMAGE_USAGE_TRANSFER_SRC_BIT;
    inoutMetadataPayloads[sourceIndex].Stage  = VK_PIPELINE_STAGE_TRANSFER_BIT;
    inoutMetadataPayloads[sourceIndex].Access = VK_ACCESS_TRANSFER_READ_BIT;

    // Destination image configuration
    inoutMetadataPayloads[destIndex].Layout = VK_IMAGE_LAYOUT_TRANSFER_DST_OPTIMAL;
    inoutMetadataPayloads[destIndex].Usage  = VK_IMAGE_USAGE_TRANSFER_DST_BIT;
    inoutMetadataPayloads[destIndex].Stage  = VK_PIPELINE_STAGE_TRANSFER_BIT;
    inoutMetadataPayloads[destIndex].Access = VK_ACCESS_TRANSFER_WRITE_BIT;
}

