// Propagate format information between source and destination if one is undefined
inline bool Vulkan::CopyImagePass::PropagateSubresourceInfos(std::span<SubresourceMetadataPayload> inoutMetadataPayloads)
{
    const uint32_t sourceIndex = static_cast<uint32_t>(PassSubresourceId::SrcImage);
    const uint32_t destIndex   = static_cast<uint32_t>(PassSubresourceId::DstImage);
    bool formatChanged = false;

    // If source has undefined format but destination doesn't, copy from dest to src
    if (inoutMetadataPayloads[sourceIndex].Format == VK_FORMAT_UNDEFINED &&
        inoutMetadataPayloads[destIndex].Format != VK_FORMAT_UNDEFINED)
    {
        inoutMetadataPayloads[sourceIndex].Format = inoutMetadataPayloads[destIndex].Format;
        formatChanged = true;
    }

    // If destination has undefined format but source doesn't, copy from src to dest
    if (inoutMetadataPayloads[destIndex].Format == VK_FORMAT_UNDEFINED &&
        inoutMetadataPayloads[sourceIndex].Format != VK_FORMAT_UNDEFINED)
    {
        inoutMetadataPayloads[destIndex].Format = inoutMetadataPayloads[sourceIndex].Format;
        formatChanged = true;
    }

    return formatChanged;
}

