static bool s_debug_symbols_initialized = false;

// Helper lambda to initialize debug symbols once
auto init_debug_symbols = [](HANDLE proc) -> void {
    if (!s_debug_symbols_initialized) {
        s_debug_symbols_initialized = true;
        if (!SymInitialize(proc, nullptr, TRUE)) {
            WARN_("Failed to initialize debug symbol handling.");
        }
        SymSetOptions(SYMOPT_LOAD_LINES);
    }
};

// Capture raw stack frames as vector of pointers
std::vector<void*> collect_stack_frames() {
    static constexpr size_t max_capture_depth = 32;
    std::vector<void*> frames(max_capture_depth, nullptr);

    HANDLE current_process = GetCurrentProcess();
    init_debug_symbols(current_process);

    DWORD skipped = 0;
    ULONG hash = 0;
    USHORT captured = CaptureStackBackTrace(
        skipped,
        static_cast<DWORD>(frames.size()),
        frames.data(),
        &hash
    );

    frames.resize(captured);
    return frames;
}

// Format a single frame into human-readable string
std::string format_frame(HANDLE proc, void* addr, uint32_t& idx) {
    static constexpr size_t name_capacity = 1024;
    alignas(SYMBOL_INFO) char buffer[sizeof(SYMBOL_INFO) + name_capacity + sizeof(ULONG) - 1];
    auto sym_info = reinterpret_cast<SYMBOL_INFO*>(buffer);
    sym_info->SizeOfStruct = sizeof(SYMBOL_INFO);
    sym_info->MaxNameLen = name_capacity;

    DWORD64 displacement = 0;
    std::string result = "<Unknown>";

    if (SymFromAddr(proc, reinterpret_cast<DWORD64>(addr), &displacement, sym_info)) {
        result = sym_info->Name;

        // Skip internal tracing functions
        if (result == "GetStackTrace" || result == "PrintStack") {
            return "";
        }

        // Try to get source location
        IMAGEHLP_LINE64 line_info{};
        line_info.SizeOfStruct = sizeof(IMAGEHLP_LINE64);
        DWORD file_displacement = 0;

        if (SymGetLineFromAddr(proc, reinterpret_cast<DWORD64>(addr), &file_displacement, &line_info)) {
            result += " @ " + std::string(line_info.FileName) + ":" + std::to_string(line_info.LineNumber);
        }

        // Stop at main
        if (result.find("main") != std::string::npos && result.rfind("main") == result.length() - 4) {
            // Mark as final frame
            idx |= 0x80000000u; // use high bit as sentinel
        }
    }

    return fmt::format("[{:03}] {} | {}\n", idx & 0x7FFFFFFF, addr, result);
}

void PrintStack() {
    SpeedLog()->info("Stack Trace:\n" + GetStackTrace());
}

std::string GetStackTrace() {
    HANDLE process = GetCurrentProcess();
    auto frames = collect_stack_frames();

    std::string full_trace;
    uint32_t frame_index = 0;

    for (void* addr : frames) {
        std::string formatted = format_frame(process, addr, frame_index);
        if (formatted.empty()) continue;

        full_trace += formatted;
        if (frame_index & 0x80000000u) break;
        ++frame_index;
    }

    return full_trace;
}

