// SPI command opcodes for register access
namespace spi_op {
    constexpr uint8_t cmd_read_ctrl = 0;
    constexpr uint8_t cmd_read_data = 1;
    constexpr uint8_t cmd_write_ctrl = 2;
    constexpr uint8_t cmd_write_data = 3;
    constexpr uint8_t cmd_bit_set = 4;
    constexpr uint8_t cmd_bit_clr = 5;
    constexpr uint8_t cmd_reset = 7;
} // namespace spi_op

// Helper to encode register address: bank (2 bits) + reg (5 bits)
static inline constexpr uint8_t encode_reg_addr(uint8_t bank_id, uint8_t reg_id) {
    return ((bank_id & 0x3U) << 5) | (reg_id & 0x1FU);
}

// Register address definitions grouped by memory bank
namespace reg_addr {
    // Common registers (bank 0)
    constexpr uint8_t eie = encode_reg_addr(0, 0x1B); // Interrupt Enable
    constexpr uint8_t eir = encode_reg_addr(0, 0x1C); // Interrupt Flag
    constexpr uint8_t estat = encode_reg_addr(0, 0x1D); // Status
    constexpr uint8_t econ2 = encode_reg_addr(0, 0x1E); // Control 2
    constexpr uint8_t econ1 = encode_reg_addr(0, 0x1F); // Control 1

    // Bank 0: Ethernet buffer pointers
    constexpr uint8_t erdpt_l = encode_reg_addr(0, 0x00);
    constexpr uint8_t erdpt_h = encode_reg_addr(0, 0x01);
    constexpr uint8_t ewrpt_l = encode_reg_addr(0, 0x02);
    constexpr uint8_t ewrpt_h = encode_reg_addr(0, 0x03);
    constexpr uint8_t etxst_l = encode_reg_addr(0, 0x04);
