namespace lab {

AnalyserNode::AnalyserNode(float sampleRate, size_t fftSize) 
    : AudioBasicInspectorNode(sampleRate, 2), m_analyser(fftSize)
{
    setNodeType(NodeTypeAnalyser);
    initialize();
}

AnalyserNode::~AnalyserNode() {
    uninitialize();
}

void AnalyserNode::process(ContextRenderLock& r, size_t framesToProcess) {
    auto* outputBus = output(0)->bus(r);

    if (!isInitialized() || !input(0)->isConnected()) {
        outputBus->zero();
        return;
    }

    auto* inputBus = input(0)->bus(r);

    // Feed the incoming audio into the analyser for analysis
    m_analyser.writeInput(r, inputBus, framesToProcess);

    // Handle data routing: if input and output buses differ (e.g., channel count mismatch),
    // copy from input to output; otherwise, in-place processing is assumed
    if (inputBus != outputBus) {
        outputBus->copyFrom(*inputBus);
    }
}

void AnalyserNode::reset(ContextRenderLock&) {
    m_analyser.reset();
}

