namespace multiple {

	// Helper: round toward zero for integer conversion
	template<typename T>
	inline int to_int_trunc(T value) {
		return static_cast<int>(value >= 0 ? std::floor(value) : std::ceil(value));
	}

	// Core scalar implementation using subtraction instead of ternary
	template<typename genType>
	GLM_FUNC_QUALIFIER genType higherMultiple(genType const& Source, genType const& Multiple)
	{
		if (Multiple == genType(0)) return Source; // avoid division by zero

		genType remainder = Source % Multiple;
		if (remainder == genType(0))
			return Source;

		// Equivalent to: Source + Multiple - remainder
		return Source + (Multiple - remainder);
	}

	// Specialization for thalf
	template<>
	GLM_FUNC_QUALIFIER detail::thalf higherMultiple(detail::thalf const& Source, detail::thalf const& Multiple)
	{
		float s = float(Source);
		float m = float(Multiple);
		if (m == 0.0f) return Source;

		int r = to_int_trunc(s) % to_int_trunc(m);
		return r ? Source + Multiple - detail::thalf(float(r)) : Source;
	}

	// Specialization for float
	template<>
	GLM_FUNC_QUALIFIER float higherMultiple(float const& Source, float const& Multiple)
	{
		if (Multiple == 0.0f) return Source;

		int r = to_int_trunc(Source) % to_int_trunc(Multiple);
		return r ? Source + Multiple - float(r) : Source;
	}

	// Specialization for double
	template<>
	GLM_FUNC_QUALIFIER double higherMultiple(double const& Source, double const& Multiple)
	{
		if (Multiple == 0.0) return Source;

		long r = static_cast<long>(std::trunc(Source)) % static_cast<long>(std::trunc(Multiple));
		return r ? Source + Multiple - double(r) : Source;
	}

	// Vector helpers: use std::transform instead of manual loop
	template<typename T, template<typename> class vec>
	GLM_FUNC_QUALIFIER vec<T> higherMultipleVec(vec<T> const& Source, vec<T> const& Multiple)
	{
		vec<T> Result;
		std::transform(Source.begin(), Source.end(),
		               Multiple.begin(),
		               Result.begin(),
		               [](T const& s, T const& m) { return higherMultiple(s, m); });
		return Result;
	}

	// Explicit instantiations for tvec2/3/4 using helper
	template<typename T>
	GLM_FUNC_QUALIFIER detail::tvec2<T> higherMultiple(detail::tvec2<T> const& Source, detail::tvec2<T> const& Multiple)
	{
		return higherMultipleVec(Source, Multiple);
	}

	template<typename T>
	GLM_FUNC_QUALIFIER detail::tvec3<T> higherMultiple(detail::tvec3<T> const& Source, detail::tvec3<T> const& Multiple)
	{
		return higherMultipleVec(Source, Multiple);
	}

	template<typename T>
	GLM_FUNC_QUALIFIER detail::tvec4<T> higherMultiple(detail::tvec4<T> const& Source, detail::tvec4<T> const& Multiple)
	{
		return higherMultipleVec(Source, Multiple);
	}


	// --- lowerMultiple implementations ---

	template<typename genType>
	GLM_FUNC_QUALIFIER genType lowerMultiple(genType const& Source, genType const& Multiple)
	{
		if (Multiple == genType(0)) return Source;

		genType remainder = Source % Multiple;
		return remainder ? Source - remainder : Source;
	}

	template<>
	GLM_FUNC_QUALIFIER detail::thalf lowerMultiple(detail::thalf const& Source, detail::thalf const& Multiple)
	{
		float s = float(Source);
		float m = float(Multiple);
		if (m == 0.0f) return Source;

		int r = to_int_trunc(s) % to_int_trunc(m);
		return r ? Source - detail::thalf(float(r)) : Source;
	}

	template<>
	GLM_FUNC_QUALIFIER float lowerMultiple(float const& Source, float const& Multiple)
	{
		if (Multiple == 0.0f) return Source;

		int r = to_int_trunc(Source) % to_int_trunc(Multiple);
		return r ? Source - float(r) : Source;
	}

	template<>
	GLM_FUNC_QUALIFIER double lowerMultiple(double const& Source, double const& Multiple)
	{
		if (Multiple == 0.0) return Source;

		long r = static_cast<long>(std::trunc(Source)) % static_cast<long>(std::trunc(Multiple));
		return r ? Source - double(r) : Source;
	}

	template<typename T, template<typename> class vec>
	GLM_FUNC_QUALIFIER vec<T> lowerMultipleVec(vec<T> const& Source, vec<T> const& Multiple)
	{
		vec<T> Result;
		std::transform(Source.begin(), Source.end(),
		               Multiple.begin(),
		               Result.begin(),
		               [](T const& s, T const& m) { return lowerMultiple(s, m); });
		return Result;
	}

	template<typename T>
	GLM_FUNC_QUALIFIER detail::tvec2<T> lowerMultiple(detail::tvec2<T> const& Source, detail::tvec2<T> const& Multiple)
	{
		return lowerMultipleVec(Source, Multiple);
	}

	template<typename T>
	GLM_FUNC_QUALIFIER detail::tvec3<T> lowerMultiple(detail::tvec3<T> const& Source, detail::tvec3<T> const& Multiple)
	{
		return lowerMultipleVec(Source, Multiple);
	}

	template<typename T>
	GLM_FUNC_QUALIFIER detail::tvec4<T> lowerMultiple(detail::tvec4<T> const& Source, detail::tvec4<T> const& Multiple)
	{
		return lowerMultipleVec(Source, Multiple);
	}

