            170, 213, 119, 248, 152, 2, 44, 154, 163, 70, 221, 153, 101, 155, 167, 43, 172, 9, 129,
            22, 39, 253, 19, 98, 108, 110, 79, 113, 224, 232, 178, 185, 112, 104, 218, 246, 97, 228,
            251, 34, 242, 193, 238, 210, 144, 12, 191, 179, 162, 241, 81, 51, 145, 235, 249, 14, 239,
            107, 49, 192, 214, 31, 181, 199, 106, 157, 184, 84, 204, 176, 115, 121, 50, 45, 127, 4,
            150, 254, 138, 236, 205, 93, 222, 114, 67, 29, 24, 72, 243, 141, 128, 195, 78, 66, 215,
            61, 156, 180
        };
    }

    // Duplicate and extend permutation table to size 512
    if (p == nullptr) {
        p = new int[512];
        for (int idx = 0; idx < 512; ++idx) {
            p[idx] = permutation[idx % 256];
        }
    }

    this->repeat = repeat;
}

// Core Perlin noise function
double Perlin::perlin(double x, double y, double z) {
    // Apply wrapping if repeat is enabled
    if (repeat > 0) {
        x = static_cast<int>(x) % repeat;
        y = static_cast<int>(y) % repeat;
        z = static_cast<int>(z) % repeat;
    }

    // Determine integer coordinates of the unit cube corner
    int ix = static_cast<int>(x) & 255;
    int iy = static_cast<int>(y) & 255;
    int iz = static_cast<int>(z) & 255;

    // Compute fractional parts and fade them
    double fx = x - static_cast<int>(x);
    double fy = y - static_cast<int>(y);
    double fz = z - static_cast<int>(z);

    double u = fade(fx);
    double v = fade(fy);
    double w = fade(fz);

    // Get indices for surrounding corners using wrap-around logic
    int xi_next = inc(ix);
    int yi_next = inc(iy);
    int zi_next = inc(iz);

    // Hash values at the 8 corners of the unit cube
    int h000 = p[p[p[ix] + iy] + iz];
    int h100 = p[p[p[xi_next] + iy] + iz];
    int h010 = p[p[p[ix] + yi_next] + iz];
    int h110 = p[p[p[xi_next] + yi_next] + iz];
    int h001 = p[p[p[ix] + iy] + zi_next];
    int h101 = p[p[p[xi_next] + iy] + zi_next];
    int h011 = p[p[p[ix] + yi_next] + zi_next];
    int h111 = p[p[p[xi_next] + yi_next] + zi_next];

    // Compute dot products with gradients
    double g000 = grad(h000, fx, fy, fz);
    double g100 = grad(h100, fx - 1.0, fy, fz);
    double g010 = grad(h010, fx, fy - 1.0, fz);
    double g110 = grad(h110, fx - 1.0, fy - 1.0, fz);
    double g001 = grad(h001, fx, fy, fz - 1.0);
    double g101 = grad(h101, fx - 1.0, fy, fz - 1.0);
    double g011 = grad(h011, fx, fy - 1.0, fz - 1.0);
    double g111 = grad(h111, fx - 1.0, fy - 1.0, fz - 1.0);

    // Trilinear interpolation
    double x00 = lerp(g000, g100, u);
    double x10 = lerp(g010, g110, u);
    double y0 = lerp(x00, x10, v);

    double x01 = lerp(g001, g101, u);
    double x11 = lerp(g011, g111, u);
    double y1 = lerp(x01, x11, v);

    double result = lerp(y0, y1, w);
    return (result + 1.0) / 2.0; // Normalize from [-1,1] to [0,1]
}

// Increment index with optional modulo wrapping
int Perlin::inc(int num) {
    ++num;
    if (repeat > 0) {
        num %= repeat;
    }
    return num;
}

// Gradient function: computes dot product between hash-derived direction and input vector
double Perlin::grad(int hash, double x, double y, double z) {
    int h = hash & 15;
    double u, v;

    // Select components based on lower 4 bits of hash
    if (h < 8) {
        u = x;
    } else {
        u = y;
    }

    if (h < 4) {
        v = y;
    } else if (h == 12 || h == 14) {
        v = x;
    } else {
        v = z;
    }

    // Apply sign flips based on remaining bits
    double signU = ((h & 1) == 0) ? 1.0 : -1.0;
    double signV = ((h & 2) == 0) ? 1.0 : -1.0;

    return signU * u + signV * v;
}

// Smoothstep-like fade curve
double Perlin::fade(double t) {
    return t * t * t * (t * (t * 6.0 - 15.0) + 10.0); // 6t^5 - 15t^4 + 10t^3
}

// Linear interpolation helper
double Perlin::lerp(double a, double b, double t) {
    return a + t * (b - a);
}

// Octave-based layered Perlin noise
double Perlin::OctavePerlin(double x, double y, double z, int octaves, double persistence) {
    double total = 0.0;
    double amplitude = 1.0;
    double maxAmpSum = 0.0;
    double freq = 1.0;

    for (int i = 0; i < octaves; ++i) {
        total += perlin(x * freq, y * freq, z * freq) * amplitude;
        maxAmpSum += amplitude;
        amplitude *= persistence;
        freq *= 2.0;
    }

    return total / maxAmpSum;
}

