struct LLVMJIT::ModuleMemoryManager : llvm::RTDyldMemoryManager
{
	ModuleMemoryManager()
	: imageBaseAddress(nullptr)
	, isFinalized(false)
	, codeSection({nullptr, 0, 0})
	, readOnlySection({nullptr, 0, 0})
	, readWriteSection({nullptr, 0, 0})
	, hasRegisteredEHFrames(false)
	{
	}

	virtual ~ModuleMemoryManager() override
	{
		deregisterEHFrames();
		if (!KEEP_UNLOADED_MODULE_ADDRESSES_RESERVED)
		{ 
			Platform::freeVirtualPages(imageBaseAddress, numAllocatedImagePages); 
		}
		else
		{
			Platform::decommitVirtualPages(imageBaseAddress, numAllocatedImagePages);
		}
	}

	void registerEHFrames(U8* addr, U64 loadAddr, uintptr_t numBytes) override
	{
		if (!USE_WINDOWS_SEH)
		{
			Platform::registerEHFrames(imageBaseAddress, addr, numBytes);
			hasRegisteredEHFrames = true;
			ehFramesAddr = addr;
			ehFramesNumBytes = numBytes;
		}
	}

	void registerFixedSEHFrames(U8* addr, Uptr numBytes)
	{
		Platform::registerEHFrames(imageBaseAddress, addr, numBytes);
		hasRegisteredEHFrames = true;
		ehFramesAddr = addr;
		ehFramesNumBytes = numBytes;
	}

	void deregisterEHFrames() override
	{
		if (hasRegisteredEHFrames)
		{
			hasRegisteredEHFrames = false;
			Platform::deregisterEHFrames(imageBaseAddress, ehFramesAddr, ehFramesNumBytes);
		}
	}

	virtual bool needsToReserveAllocationSpace() override { return true; }

	virtual void reserveAllocationSpace(uintptr_t numCodeBytes,
										U32 codeAlignment,
										uintptr_t numReadOnlyBytes,
										U32 readOnlyAlignment,
										uintptr_t numReadWriteBytes,
										U32 readWriteAlignment) override
	{
		if (USE_WINDOWS_SEH)
		{
			numCodeBytes += 32;
		}

		codeSection.numPages = shrAndRoundUp(numCodeBytes, Platform::getPageSizeLog2());
		readOnlySection.numPages = shrAndRoundUp(numReadOnlyBytes, Platform::getPageSizeLog2());
		readWriteSection.numPages = shrAndRoundUp(numReadWriteBytes, Platform::getPageSizeLog2());

		numAllocatedImagePages = codeSection.numPages + readOnlySection.numPages + readWriteSection.numPages;

		if (numAllocatedImagePages)
		{
			imageBaseAddress = Platform::allocateVirtualPages(numAllocatedImagePages);
			if (!imageBaseAddress || !Platform::commitVirtualPages(imageBaseAddress, numAllocatedImagePages))
			{ Errors::fatal("memory allocation for JIT code failed"); }

			codeSection.baseAddress = imageBaseAddress;
			readOnlySection.baseAddress = codeSection.baseAddress + (codeSection.numPages << Platform::getPageSizeLog2());
			readWriteSection.baseAddress = readOnlySection.baseAddress + (readOnlySection.numPages << Platform::getPageSizeLog2());
		}
	}

	virtual U8* allocateCodeSection(uintptr_t numBytes,
									U32 alignment,
									U32 sectionID,
									llvm::StringRef sectionName) override
	{
		return allocateBytes((Uptr)numBytes, alignment, codeSection);
	}

	virtual U8* allocateDataSection(uintptr_t numBytes,
									U32 alignment,
									U32 sectionID,
									llvm::StringRef SectionName,
									bool isReadOnly) override
	{
		return allocateBytes(
			(Uptr)numBytes, alignment, isReadOnly ? readOnlySection : readWriteSection);
	}

	virtual bool finalizeMemory(std::string* ErrMsg = nullptr) override
	{
		return true;
	}

	void reallyFinalizeMemory()
	{
		wavmAssert(!isFinalized);
		isFinalized = true;

		const Platform::MemoryAccess codeAccess = Platform::MemoryAccess::execute;
		if (codeSection.numPages)
		{
			errorUnless(Platform::setVirtualPageAccess(codeSection.baseAddress, codeSection.numPages, codeAccess));
		}
		if (readOnlySection.numPages)
		{
			errorUnless(Platform::setVirtualPageAccess(readOnlySection.baseAddress,
													   readOnlySection.numPages,
													   Platform::MemoryAccess::readOnly));
		}
		if (readWriteSection.numPages)
		{
			errorUnless(Platform::setVirtualPageAccess(readWriteSection.baseAddress,
													   readWriteSection.numPages,
													   Platform::MemoryAccess::readWrite));
		}
		invalidateInstructionCache();
	}

	virtual void invalidateInstructionCache()
	{
		llvm::sys::Memory::InvalidateInstructionCache(
			imageBaseAddress, numAllocatedImagePages << Platform::getPageSizeLog2());
	}

	U8* getImageBaseAddress() const { return imageBaseAddress; }
	Uptr getNumImageBytes() const { return numAllocatedImagePages << Platform::getPageSizeLog2(); }

private:
	struct Section
	{
		U8* baseAddress;
		Uptr numPages;
		Uptr numCommittedBytes;
	};

	U8* imageBaseAddress;
	Uptr numAllocatedImagePages;
	bool isFinalized;
	Section codeSection;
	Section readOnlySection;
	Section readWriteSection;
	bool hasRegisteredEHFrames;
	const U8* ehFramesAddr;
	Uptr ehFramesNumBytes;

	U8* allocateBytes(Uptr numBytes, Uptr alignment, Section& section)
	{
		if (alignment == 0) { alignment = 1; }
		wavmAssert(section.baseAddress);
		wavmAssert(!(alignment & (alignment - 1)));
		wavmAssert(!isFinalized);

		U8* allocationBaseAddress = section.baseAddress + align(section.numCommittedBytes, alignment);
		wavmAssert(!(reinterpret_cast<Uptr>(allocationBaseAddress) & (alignment - 1)));

		section.numCommittedBytes = align(section.numCommittedBytes, alignment) + align(numBytes, alignment);

		if (section.numCommittedBytes > (section.numPages << Platform::getPageSizeLog2()))
		{ Errors::fatal("didn't reserve enough space in section"); }

		return allocationBaseAddress;
	}

	static Uptr align(Uptr size, Uptr alignment)
	{
		return (size + alignment - 1) & ~(alignment - 1);
	}

	static Uptr shrAndRoundUp(Uptr value, Uptr shift)
	{
		return (value + (Uptr(1) << shift) - 1) >> shift;
	}

	ModuleMemoryManager(const ModuleMemoryManager&) = delete;
	void operator=(const ModuleMemoryManager&) = delete;
};

static void disassembleFunction(U8* bytes, Uptr numBytes)
{
	LLVMDisasmContextRef disasmRef = LLVMCreateDisasm(llvm::sys::getProcessTriple().c_str(), nullptr, 0, nullptr, nullptr);
	U8* nextByte = bytes;
	Uptr remaining = numBytes;

	while (remaining > 0)
	{
		char instructionBuffer[256];
		Uptr instrLen = LLVMDisasmInstruction(disasmRef, nextByte, remaining,
											  reinterpret_cast<Uptr>(nextByte),
											  instructionBuffer, sizeof(instructionBuffer));
		if (instrLen == 0) { instrLen = 1; }
		wavmAssert(instrLen <= remaining);
		remaining -= instrLen;
		nextByte += instrLen;
		Log::printf(Log::output, "\t\t0x%04" PRIxPTR " %s\n", (nextByte - bytes - instrLen), instructionBuffer);
	}
	LLVMDisasmDispose(disasmRef);
}

Module::Module(const std::vector<U8>& objectBytes,
			   const HashMap<std::string, Uptr>& importedSymbolMap,
			   bool shouldLogMetrics)
: memoryManager(new ModuleMemoryManager())
#if LLVM_VERSION_MAJOR < 8
, objectBytes(objectBytes)
#endif
{
	Timing::Timer loadObjectTimer;

#if LLVM_VERSION_MAJOR >= 8
	std::unique_ptr<llvm::object::ObjectFile> objFile;
#endif

	objFile = cantFail(llvm::object::ObjectFile::createObjectFile(
		llvm::MemoryBufferRef(llvm::StringRef((const char*)objectBytes.data(), objectBytes.size()), "memory")));

	struct SymbolResolver : llvm::JITSymbolResolver
	{
		const HashMap<std::string, Uptr>& importedSymbolMap;
		SymbolResolver(const HashMap<std::string, Uptr>& inImportedSymbolMap)
		: importedSymbolMap(inImportedSymbolMap)
		{}

#if LLVM_VERSION_MAJOR >= 8
		virtual void lookup(const LookupSet& symbols,
							llvm::JITSymbolResolver::OnResolvedFunction onResolvedFunction) override
		{
			LookupResult result;
			for (auto sym : symbols)
				result.emplace(sym, findSymbolImpl(sym));
			onResolvedFunction(result);
		}
		virtual llvm::Expected<LookupSet> getResponsibilitySet(const LookupSet& symbols) override
		{
			return LookupSet();
		}
#elif LLVM_VERSION_MAJOR == 7
		virtual llvm::Expected<LookupResult> lookup(const LookupSet& symbols) override
		{
			LookupResult result;
			for (auto sym : symbols)
				result.emplace(sym, findSymbolImpl(sym));
			return result;
		}
		virtual llvm::Expected<LookupFlagsResult> lookupFlags(const LookupSet& symbols) override
		{
			LookupFlagsResult result;
			for (auto sym : symbols)
				result.emplace(sym, findSymbolImpl(sym).getFlags());
			return result;
		}
#else
		virtual llvm::JITSymbol findSymbolInLogicalDylib(const std::string& name) override
		{
			return findSymbolImpl(name);
		}
		virtual llvm::JITSymbol findSymbol(const std::string& name) override
		{
			return findSymbolImpl(name);
		}
#endif

	private:
		llvm::JITEvaluatedSymbol findSymbolImpl(llvm::StringRef name)
		{
			const std::string demangled = demangleSymbol(name.str());
			const Uptr* valPtr = importedSymbolMap.get(demangled);
			if (!valPtr)
				return resolveJITImport(demangled);
			else
			{
				wavmAssert(*valPtr);
				return llvm::JITEvaluatedSymbol(U64(*valPtr), llvm::JITSymbolFlags::None);
			}
		}
	};

	SymbolResolver resolver(importedSymbolMap);
	llvm::RuntimeDyld loader(*memoryManager, resolver);

#ifndef _WIN32
	loader.setProcessAllSections(true);
#endif

	llvm::object::SectionRef pdataSection;
	U8* pdataCopy = nullptr;
	Uptr pdataNumBytes = 0;
	llvm::object::SectionRef xdataSection;
	U8* xdataCopy = nullptr;

	if (USE_WINDOWS_SEH)
	{
		for (auto sec : objFile->sections())
		{
			llvm::StringRef secName;
			if (!sec.getName(secName))
			{
#if LLVM_VERSION_MAJOR >= 9
				auto contentsOrErr = sec.getContents();
				if (contentsOrErr)
				{
					const auto& contents = *contentsOrErr;
#else
				llvm::StringRef contents;
				if (!sec.getContents(contents))
				{
#endif
					const U8* loadedSec = (const U8*)contents.data();
					if (secName == ".pdata")
					{
						pdataCopy = new U8[sec.getSize()];
						pdataNumBytes = sec.getSize();
						pdataSection = sec;
						memcpy(pdataCopy, loadedSec, sec.getSize());
					}
					else if (secName == ".xdata")
					{
						xdataCopy = new U8[sec.getSize()];
						xdataSection = sec;
						memcpy(xdataCopy, loadedSec, sec.getSize());
					}
				}
			}
		}
	}

	std::unique_ptr<llvm::RuntimeDyld::LoadedObjectInfo> loadedObj = loader.loadObject(*objFile);
	loader.finalizeWithMemoryManagerLocking();

	if (loader.hasError())
	{ Errors::fatalf("RuntimeDyld failed: %s", loader.getErrorString().data()); }

	if (USE_WINDOWS_SEH && pdataCopy)
	{
		const llvm::JITEvaluatedSymbol sehHandlerSym = resolveJITImport("__CxxFrameHandler3");
		errorUnless(sehHandlerSym);
		const U64 sehHandlerAddr = U64(sehHandlerSym.getAddress());

		U8* tramp = memoryManager->allocateCodeSection(16, 16, 0, "seh_trampoline");
		tramp[0] = 0xff;
		tramp[1] = 0x25;
		memset(tramp + 2, 0, 4);
		memcpy(tramp + 6, &sehHandlerAddr, sizeof(U64));

		processSEPTables(memoryManager->getImageBaseAddress(),
						 *loadedObj,
						 pdataSection,
						 pdataCopy,
						 pdataNumBytes,
						 xdataSection,
						 xdataCopy,
						 reinterpret_cast<Uptr>(tramp));

		memoryManager->registerFixedSEHFrames(
			reinterpret_cast<U8*>(Uptr(loadedObj->getSectionLoadAddress(pdataSection))),
			pdataNumBytes);
	}

	if (pdataCopy)
	{
		delete[] pdataCopy;
		pdataCopy = nullptr;
	}
	if (xdataCopy)
	{
		delete[] xdataCopy;
		xdataCopy = nullptr;
	}

	memoryManager->reallyFinalizeMemory();

	{
		Lock<Platform::Mutex> lock(gdbRegistrationListenerMutex);
		if (!gdbRegistrationListener)
			gdbRegistrationListener = llvm::JITEventListener::createGDBRegistrationListener();

#if LLVM_VERSION_MAJOR >= 8
		gdbRegistrationListener->notifyObjectLoaded(reinterpret_cast<Uptr>(this), *objFile, *loadedObj);
#else
		gdbRegistrationListener->NotifyObjectEmitted(*objFile, *loadedObj);
#endif
	}

	auto dwarfCtx = llvm::DWARFContext::create(*objFile, &*loadedObj);

	for (auto&& [sym, size] : llvm::object::computeSymbolSizes(*objFile))
	{
		if (!(sym.getFlags() & llvm::object::SymbolRef::SF_Global)) continue;

		auto type = sym.getType();
		if (!type || *type != llvm::object::SymbolRef::ST_Function) continue;

		auto name = sym.getName();
		if (!name) continue;

		auto addr = sym.getAddress();
		if (!addr) continue;

		Uptr loadedAddr = Uptr(*addr);
		if (auto sec = sym.getSection())
			loadedAddr += Uptr(loadedObj->getSectionLoadAddress(*sec));

#if LLVM_VERSION_MAJOR >= 9
		if (auto sec = sym.getSection())
		{
#endif
			llvm::DILineInfoTable lineInfo = dwarfCtx->getLineInfoForAddressRange(
#if LLVM_VERSION_MAJOR >= 9
				llvm::object::SectionedAddress{loadedAddr, sec->getIndex()},
#else
				loadedAddr,
#endif
				size);

			std::map<U32, U32> offsetToOpIndex;
			for (auto&& [offset, info] : lineInfo)
				offsetToOpIndex.emplace(U32(offset - loadedAddr), info.Line);

			if (PRINT_DISASSEMBLY && shouldLogMetrics)
			{
				Log::printf(Log::output, "Disassembly for function %s\n", name.get().data());
				disassembleFunction(reinterpret_cast<U8*>(loadedAddr), Uptr(size));
			}

			Runtime::Function* func = (Runtime::Function*)(loadedAddr - offsetof(Runtime::Function, code));
			nameToFunctionMap.addOrFail(*name, func);
			addressToFunctionMap.emplace(Uptr(loadedAddr + size), func);

			wavmAssert(func->mutableData);
			func->mutableData->jitModule = this;
			func->mutableData->function = func;
			func->mutableData->numCodeBytes = Uptr(size);
			func->mutableData->offsetToOpIndexMap = std::move(offsetToOpIndex);
#if LLVM_VERSION_MAJOR >= 9
		}
#endif
	}

	const Uptr moduleEnd = reinterpret_cast<Uptr>(
		memoryManager->getImageBaseAddress() + memoryManager->getNumImageBytes());

	{
		Lock<Platform::Mutex> lock(addressToModuleMapMutex);
		addressToModuleMap.emplace(moduleEnd, this);
	}

	if (shouldLogMetrics)
	{
		Timing::logRatePerSecond("Loaded object", loadObjectTimer,
								 (F64)objectBytes.size() / 1024.0 / 1024.0, "MB");
	}
}

Module::~Module()
{
	{
		Lock<Platform::Mutex> lock(gdbRegistrationListenerMutex);
#if LLVM_VERSION_MAJOR >= 8
		gdbRegistrationListener->notifyFreeingObject(reinterpret_cast<Uptr>(this));
#else
		gdbRegistrationListener->NotifyFreeingObject(*object);
#endif
	}

	{
		Lock<Platform::Mutex> lock(addressToModuleMapMutex);
		addressToModuleMap.erase(
			addressToModuleMap.find(reinterpret_cast<Uptr>(
				memoryManager->getImageBaseAddress() + memoryManager->getNumImageBytes())));
	}

	for (auto&& [_, func] : addressToFunctionMap)
		delete func->mutableData;

	delete memoryManager;
}

std::shared_ptr<LLVMJIT::Module> LLVMJIT::loadModule(
	const std::vector<U8>& objectFileBytes,
	HashMap<std::string, FunctionBinding>&& wavmIntrinsicsExportMap,
	std::vector<IR::FunctionType>&& types,
	std::vector<FunctionBinding>&& functionImports,
	std::vector<TableBinding>&& tables,
	std::vector<MemoryBinding>&& memories,
	std::vector<GlobalBinding>&& globals,
	std::vector<ExceptionTypeBinding>&& exceptionTypes,
	ModuleInstanceBinding moduleInstance,
	Uptr tableReferenceBias,
	const std::vector<Runtime::FunctionMutableData*>& functionDefMutableDatas)
{
	HashMap<std::string, Uptr> importedSymbolMap;

	for (auto&& [key, val] : wavmIntrinsicsExportMap)
	{
		wavmAssert(val.callingConvention == IR::CallingConvention::intrinsic);
		importedSymbolMap.addOrFail(key, reinterpret_cast<Uptr>(val.code));
	}

	for (Uptr i = 0; i < types.size(); ++i)
	{
		importedSymbolMap.addOrFail(getExternalName("typeId", i), types[i].getEncoding().impl);
	}

	for (Uptr i = 0; i < functionImports.size(); ++i)
	{
		importedSymbolMap.addOrFail(getExternalName("functionImport", i),
									reinterpret_cast<Uptr>(functionImports[i].code));
	}

	for (Uptr i = 0; i < tables.size(); ++i)
	{
		importedSymbolMap.addOrFail(getExternalName("tableOffset", i),
									offsetof(Runtime::CompartmentRuntimeData, tableBases)
										+ sizeof(void*) * tables[i].id);
	}

	for (Uptr i = 0; i < memories.size(); ++i)
	{
		importedSymbolMap.addOrFail(getExternalName("memoryOffset", i),
									offsetof(Runtime::CompartmentRuntimeData, memoryBases)
										+ sizeof(void*) * memories[i].id);
	}

	for (Uptr i = 0; i < globals.size(); ++i)
	{
		const GlobalBinding& globalSpec = globals[i];
		Uptr value;
		if (globalSpec.type.isMutable)
		{
			value = offsetof(Runtime::ContextRuntimeData, mutableGlobals)
					+ globalSpec.mutableGlobalIndex * sizeof(IR::UntaggedValue);
		}
		else
		{
			value = reinterpret_cast<Uptr>(globalSpec.immutableValuePointer);
		}
		importedSymbolMap.addOrFail(getExternalName("global", i), value);
	}

	for (Uptr i = 0; i < exceptionTypes.size(); ++i)
	{
		importedSymbolMap.addOrFail(getExternalName("biasedExceptionTypeId", i),
									exceptionTypes[i].id + 1);
	}

	for (Uptr i = 0; i < functionDefMutableDatas.size(); ++i)
	{
		Runtime::FunctionMutableData* data = functionDefMutableDatas[i];
		importedSymbolMap.addOrFail(getExternalName("functionDefMutableDatas", i),
									reinterpret_cast<Uptr>(data));
	}

	wavmAssert(moduleInstance.id != UINTPTR_MAX);
	importedSymbolMap.addOrFail("biasedModuleInstanceId", moduleInstance.id + 1);
	importedSymbolMap.addOrFail("tableReferenceBias", tableReferenceBias);

#if !USE_WINDOWS_SEH
	std::type_info* runtimeExceptionTypeInfo = nullptr;
	try
	{
		throw(Runtime::Exception*) nullptr;
	}
	catch (Runtime::Exception*)
	{
		runtimeExceptionTypeInfo = __cxxabiv1::__cxa_current_exception_type();
	}
	importedSymbolMap.addOrFail("runtimeExceptionTypeInfo",
								reinterpret_cast<Uptr>(runtimeExceptionTypeInfo));
#endif

	return std::make_shared<Module>(objectFileBytes, importedSymbolMap, true);
}

Runtime::Function* LLVMJIT::getFunctionByAddress(Uptr address)
{
	Module* jitModule;
	{
		Lock<Platform::Mutex> lock(addressToModuleMapMutex);
		auto it = addressToModuleMap.upper_bound(address);
		if (it == addressToModuleMap.end()) return nullptr;
		jitModule = it->second;
	}

	auto funcIt = jitModule->addressToFunctionMap.upper_bound(address);
	if (funcIt == jitModule->addressToFunctionMap.end()) return nullptr;

	Runtime::Function* func = funcIt->second;
	const Uptr codeAddr = reinterpret_cast<Uptr>(func->code);
	return (address >= codeAddr && address < codeAddr + func->mutableData->numCodeBytes)
		   ? func
		   : nullptr;
}

