    backend_ctx->write_idx = handle->queue_descs[buffer_id].write_idx;
    backend_ctx->read_idx = handle->queue_descs[buffer_id].read_idx;
    backend_ctx->status = handle->queue_descs[buffer_id].status;
    backend_ctx->host_read_idx = &handle->queue_descs[buffer_id].read_idx;
    backend_ctx->queue = handle->queues[buffer_id];
    backend_ctx->queue_size = handle->queue_size;
    backend_ctx->barrier_ptr = handle->barrier_ptr;
    backend_ctx->g_ret = handle->g_ret;
    backend_ctx->atomic_ret.atomic_base_ptr = handle->atomic_ret->atomic_base_ptr;
    backend_ctx->atomic_ret.atomic_counter = 0;
    ipcImpl_.ipc_bases = b.ipcImpl.ipc_bases;
    backend_ctx->profiler.resetStats();
}

__device__
ROContext::ROContext(const Backend &b, long option)
    : Context(b, false)
{
    int thread_id = get_flat_block_id();
    auto* handle = static_cast<ROBackend*>(device_backend_proxy)->backend_handle;
    GPU_DPRINTF("Function: ro_ctx_create\n");

    backend_ctx = reinterpret_cast<ro_net_wg_handle*>(
        WGState::instance()->allocateDynamicShared(sizeof(ro_net_wg_handle)));

    ipcImpl_.ipcGpuInit(static_cast<Backend*>(device_backend_proxy), this, thread_id);

    if (is_thread_zero_in_block()) {
        type = BackendType::RO_BACKEND;
        int buffer_id = WGState::instance()->get_global_buffer_id();

        // Element-wise copy avoids slow device-side memcpy
        backend_ctx->write_idx = handle->queue_descs[buffer_id].write_idx;
        backend_ctx->read_idx = handle->queue_descs[buffer_id].read_idx;
        backend_ctx->status = handle->queue_descs[buffer_id].status;
        backend_ctx->host_read_idx = &handle->queue_descs[buffer_id].read_idx;
        backend_ctx->queue = handle->queues[buffer_id];
        backend_ctx->queue_size = handle->queue_size;
        backend_ctx->barrier_ptr = handle->barrier_ptr;
        backend_ctx->g_ret = handle->g_ret;
        backend_ctx->atomic_ret.atomic_base_ptr = handle->atomic_ret->atomic_base_ptr;
        backend_ctx->atomic_ret.atomic_counter = handle->atomic_ret->atomic_counter;
        backend_ctx->profiler.resetStats();

        new (&backend_ctx->hdp_policy) HdpPolicy(*handle->hdp_policy);
    }
    __syncthreads();
}

__device__ void ROContext::threadfence_system()
{
    int tid = get_flat_block_id();
    if (tid % WF_SIZE == lowerID()) {
        backend_ctx->hdp_policy.flushCoherency();
    }
    __threadfence_system();
}

__device__ void ROContext::putmem(void* dest, const void* source, size_t nelems, int pe)
{
    if (ipcImpl_.isIpcAvailable(my_pe, pe)) {
        uint64_t offset = reinterpret_cast<char*>(dest) - ipcImpl_.ipc_bases[my_pe];
        ipcImpl_.ipcCopy(ipcImpl_.ipc_bases[pe] + offset,
                         const_cast<void*>(source),
                         nelems);
    } else {
        bool must_send = wf_coal_.coalesce(pe, source, dest, nelems);
        if (!must_send) return;

        build_queue_element(RO_NET_PUT, dest, const_cast<void*>(source), nelems, pe,
                            0, 0, 0, nullptr, nullptr, MPI_COMM_NULL, backend_ctx, true);
    }
}

