    if (is_thread_zero_in_block()) {
        auto* handle = static_cast<ROBackend*>(device_backend_proxy)->backend_handle;
        build_queue_element(RO_NET_FINALIZE, nullptr, nullptr, 0, 0, 0, 0, 0,
                            nullptr, nullptr, MPI_COMM_NULL, backend_ctx, true);

        int buffer_id = WGState::instance()->get_global_buffer_id();
        handle->queue_descs[buffer_id].write_idx = backend_ctx->write_idx;

        ROStats& global_prof = handle->profiler[buffer_id];
        global_prof.accumulateStats(backend_ctx->profiler);
    }
    __syncthreads();
}

__device__ int64_t ROContext::amo_fetch_cas(void* dst, int64_t value, int64_t cond, int pe)
{
    if (ipcImpl_.isIpcAvailable(my_pe, pe)) {
        uint64_t offset = reinterpret_cast<char*>(dst) - ipcImpl_.ipc_bases[my_pe];
        auto* addr = ipcImpl_.ipc_bases[pe] + offset;
        auto* cast_addr = reinterpret_cast<unsigned long long*>(addr); // NOLINT
        return ipcImpl_.ipcAMOFetchCas(cast_addr,
            static_cast<unsigned long long>(cond),  // NOLINT
            static_cast<unsigned long long>(value));  // NOLINT
    } else {
        uint64_t pos = atomicAdd(reinterpret_cast<unsigned long long*>(&backend_ctx->atomic_ret.atomic_counter), 1);
        pos %= max_nb_atomic;
        auto* base = reinterpret_cast<int64_t*>(backend_ctx->atomic_ret.atomic_base_ptr);
        int64_t* slot = &base[pos];

        build_queue_element(RO_NET_AMO_FCAS, dst, slot, value, pe, 0, 0, 0,
                            reinterpret_cast<void*>(cond), nullptr, MPI_COMM_NULL, backend_ctx, true);
        __threadfence();
        return *slot;
    }
}

