/***
 *
 * Internal Device-side API functions
 *
 ***/
__device__ bool isFull(uint64_t read_idx, uint64_t write_idx, uint64_t queue_size) {
    return ((queue_size - (write_idx - read_idx)) == 0);
}

__device__ void build_queue_element(ro_net_cmds type, void* dst, void* src,
                                    size_t size, int pe, int logPE_stride,
                                    int PE_size, int PE_root,
                                    void* pWrk, long* pSync, MPI_Comm team_comm,
                                    struct ro_net_wg_handle* handle,
                                    bool blocking, ROC_SHMEM_OP op,
                                    ro_net_types datatype)
{
    int tid = get_flat_block_id();
    uint64_t timer_start = handle->profiler.startTimer();

    unsigned long long current_write_slot = handle->write_idx;
    unsigned long long expected_write_slot;

    do {
        expected_write_slot = current_write_slot;

        // Poll until space available
        while (isFull(handle->read_idx, expected_write_slot, handle->queue_size)) {
            __asm__ volatile ("global_load_dwordx2 %0 %1 off glc slc\n "
                              "s_waitcnt vmcnt(0)" :
                              "=v"(handle->read_idx) :
                              "v"(handle->host_read_idx));
        }

        current_write_slot = atomicCAS((unsigned long long*)&handle->write_idx,
                                       expected_write_slot, expected_write_slot + 1);
    } while (expected_write_slot != current_write_slot);

    handle->profiler.endTimer(timer_start, WAITING_ON_SLOT);

    timer_start = handle->profiler.startTimer();
    unsigned long long actual_slot = current_write_slot % handle->queue_size;

    handle->queue[actual_slot].type = type;
    handle->queue[actual_slot].PE = pe;
    handle->queue[actual_slot].size = size;
    handle->queue[actual_slot].dst = dst;

    if (type == RO_NET_P)
        memcpy(&handle->queue[actual_slot].src, src, size);
    else
        handle->queue[actual_slot].src = src;

    handle->queue[actual_slot].threadId = tid;

    if (type == RO_NET_AMO_FOP)
        handle->queue[actual_slot].op = op;
    if (type == RO_NET_AMO_FCAS)
        handle->queue[actual_slot].pWrk = pWrk;

    if (type == RO_NET_TO_ALL) {
        handle->queue[actual_slot].logPE_stride = logPE_stride;
        handle->queue[actual_slot].PE_size = PE_size;
        handle->queue[actual_slot].pWrk = pWrk;
        handle->queue[actual_slot].pSync = pSync;
        handle->queue[actual_slot].op = op;
        handle->queue[actual_slot].datatype = datatype;
    }

    if (type == RO_NET_TEAM_TO_ALL) {
        handle->queue[actual_slot].op = op;
        handle->queue[actual_slot].datatype = datatype;
        handle->queue[actual_slot].team_comm = team_comm;
    }

    if (type == RO_NET_BROADCAST) {
        handle->queue[actual_slot].logPE_stride = logPE_stride;
        handle->queue[actual_slot].PE_size = PE_size;
        handle->queue[actual_slot].pSync = pSync;
        handle->queue[actual_slot].PE_root = PE_root;
        handle->queue[actual_slot].datatype = datatype;
    }

    if (type == RO_NET_TEAM_BROADCAST) {
        handle->queue[actual_slot].PE_root = PE_root;
        handle->queue[actual_slot].datatype = datatype;
        handle->queue[actual_slot].team_comm = team_comm;
    }

    handle->profiler.endTimer(timer_start, PACK_QUEUE);

    timer_start = handle->profiler.startTimer();
    __threadfence();
    handle->profiler.endTimer(timer_start, THREAD_FENCE_1);

    timer_start = handle->profiler.startTimer();
    handle->queue[actual_slot].valid = 1;
    __threadfence();
    handle->profiler.endTimer(timer_start, THREAD_FENCE_2);

    if (blocking) {
        int net_status = 0;
        do {
            __asm__ volatile ("s_sleep 32\n"
                              "global_load_sbyte %0 %1 off glc slc\n "
                              "s_waitcnt vmcnt(0)" :
                              "=v"(net_status) :
                              "v"(&handle->status[tid]));
        } while (net_status == 0);

        handle->status[tid] = 0;
        __threadfence();
    }

    handle->profiler.endTimer(timer_start, WAITING_ON_HOST);
}

