namespace proxy_wasm {

// Test successful verification of a properly signed WebAssembly module
TEST(TestSignatureUtil, GoodSignature) {
#ifndef PROXY_WASM_VERIFY_WITH_ED25519_PUBKEY
  FAIL() << "Built without a key for verifying signed Wasm modules.";
#endif
  const auto bytecode = readTestWasmFile("abi_export.signed.with.key1.wasm");
  std::string message;
  bool result = SignatureUtil::verifySignature(bytecode, message);
  EXPECT_TRUE(result);
  EXPECT_STREQ(message.c_str(), "Wasm signature OK (Ed25519)");
}

// Test rejection of a WebAssembly module with an invalid signature
TEST(TestSignatureUtil, BadSignature) {
#ifndef PROXY_WASM_VERIFY_WITH_ED25519_PUBKEY
  FAIL() << "Built without a key for verifying signed Wasm modules.";
#endif
  const auto bytecode = readTestWasmFile("abi_export.signed.with.key2.wasm");
  std::string message;
  bool result = SignatureUtil::verifySignature(bytecode, message);
  EXPECT_FALSE(result);
  EXPECT_STREQ(message.c_str(), "Signature mismatch");
}

// Test rejection of a WebAssembly module lacking any signature section
TEST(TestSignatureUtil, NoSignature) {
#ifndef PROXY_WASM_VERIFY_WITH_ED25519_PUBKEY
  FAIL() << "Built without a key for verifying signed Wasm modules.";
#endif
  const auto bytecode = readTestWasmFile("abi_export.wasm");
  std::string message;
  bool result = SignatureUtil::verifySignature(bytecode, message);
  EXPECT_FALSE(result);
  EXPECT_STREQ(message.c_str(), "Custom Section \"signature_wasmsign\" not found");
}

