BOOST_AUTO_TEST_SUITE(BufferTests)

// Test case: Verify basic packet buffer operations (write, commit, read, mark)
BOOST_AUTO_TEST_CASE(PacketBufferTest0_VariantA)
{
    IPacketBufferPtr buffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(buffer->GetSize() == 0);

    // Write test values at specific offsets
    WriteUint32(buffer, 0u, 10u);
    WriteUint32(buffer, 4u, 20u);
    WriteUint32(buffer, 8u, 30u);
    WriteUint32(buffer, 12u, 40u);

    // Commit the written data
    buffer->Commit(16u);
    BOOST_TEST(buffer->GetSize() == 16u);

    // Read and verify committed data
    auto readableData = buffer->GetReadableData();
    uint32_t val0 = ReadUint32(readableData, 0u);
    uint32_t val1 = ReadUint32(readableData, 4u);
    uint32_t val2 = ReadUint32(readableData, 8u);
    uint32_t val3 = ReadUint32(readableData, 12u);

    BOOST_TEST(val0 == 10u);
    BOOST_TEST(val1 == 20u);
    BOOST_TEST(val2 == 30u);
    BOOST_TEST(val3 == 40u);

    // Mark as read to reset buffer state
    buffer->MarkRead();
    BOOST_TEST(buffer->GetSize() == 0u);
}

// Test case: Alternative write path using GetWritableData
BOOST_AUTO_TEST_CASE(PacketBufferTest1_VariantA)
{
    IPacketBufferPtr buffer = std::make_unique<PacketBuffer>(512);
    BOOST_TEST(buffer->GetSize() == 0u);

    // Acquire writable pointer and populate data
    auto writablePtr = buffer->GetWritableData();
    WriteUint32(writablePtr, 0u, 10u);
    WriteUint32(writablePtr, 4u, 20u);
    WriteUint32(writablePtr, 8u, 30u);
    WriteUint32(writablePtr, 12u, 40u);

    buffer->Commit(16u);
    BOOST_TEST(buffer->GetSize() == 16u);

    // Validate via readable interface
    auto readablePtr = buffer->GetReadableData();
    BOOST_TEST(ReadUint32(readablePtr, 0u) == 10u);
    BOOST_TEST(ReadUint32(readablePtr, 4u) == 20u);
    BOOST_TEST(ReadUint32(readablePtr, 8u) == 30u);
    BOOST_TEST(ReadUint32(readablePtr, 12u) == 40u);

    buffer->MarkRead();
