// Test case: Release and re-reserve flow
BOOST_AUTO_TEST_CASE(BufferReleaseTest_VariantA)
{
    BufferManager manager(2u, 512u);

    unsigned int sz0 = 0u;
    auto b0 = manager.Reserve(512u, sz0);
    BOOST_TEST(sz0 == 512u);
    BOOST_TEST(b0 != nullptr);

    unsigned int sz1 = 0u;
    auto b1 = manager.Reserve(128u, sz1);
    BOOST_TEST(sz1 == 128u);
    BOOST_TEST(b1 != nullptr);

    // Exhausted now
    unsigned int sz2 = 0u;
    auto b2 = manager.Reserve(512u, sz2);
    BOOST_TEST(sz2 == 0u);
    BOOST_TEST(b2 == nullptr);

    // Release first buffer
    manager.Release(b0);

    // Now able to reserve again
    unsigned int sz3 = 0u;
    auto b3 = manager.Reserve(128u, sz3);
    BOOST_TEST(sz3 == 128u);
    BOOST_TEST(b3 != nullptr);
}

// Test case: Committing partial data and checking readability
BOOST_AUTO_TEST_CASE(BufferCommitTest_VariantA)
{
    BufferManager manager(2u, 512u);

    unsigned int sz0 = 0u;
    auto b0 = manager.Reserve(512u, sz0);
    BOOST_TEST(sz0 == 512u);
    BOOST_TEST(b0 != nullptr);

    unsigned int sz1 = 0u;
    auto b1 = manager.Reserve(128u, sz1);
    BOOST_TEST(sz1 == 128u);
    BOOST_TEST(b1 != nullptr);

    // No more space left
    unsigned int sz2 = 0u;
    auto b2 = manager.Reserve(512u, sz2);
    BOOST_TEST(sz2 == 0u);
    BOOST_TEST(b2 == nullptr);

    // Commit part of first buffer
    manager.Commit(b0, 256u);

    // Should be readable now
    auto readable = manager.GetReadableBuffer();
    BOOST_TEST(readable != nullptr);
    BOOST_TEST(readable->GetSize() == 256u);

    // Still no available buffers
    unsigned int sz3 = 0u;
    auto b3 = manager.Reserve(512u, sz3);
    BOOST_TEST(sz3 == 0u);
    BOOST_TEST(b3 == nullptr);
}

// Test case: Full lifecycle including commit, read, and mark-read
BOOST_AUTO_TEST_CASE(BufferMarkReadTest_VariantA)
{
    BufferManager manager(2u, 512u);

    unsigned int sz0 = 0u;
    auto b0 = manager.Reserve(512u, sz0);
    BOOST_TEST(sz0 == 512u);
    BOOST_TEST(b0 != nullptr);

    unsigned int sz1 = 0u;
    auto b1 = manager.Reserve(128u, sz1);
    BOOST_TEST(sz1 == 128u);
    BOOST_TEST(b1 != nullptr);

    // Exhausted
    unsigned int sz2 = 0u;
    auto b2 = manager.Reserve(512u, sz2);
    BOOST_TEST(sz2 == 0u);
    BOOST_TEST(b2 == nullptr);

    manager.Commit(b0, 256u);

    auto readable = manager.GetReadableBuffer();
    BOOST_TEST(readable != nullptr);
    BOOST_TEST(readable->GetSize() == 256u);

    // Still exhausted
    unsigned int sz3 = 0u;
    auto b3 = manager.Reserve(512u, sz3);
    BOOST_TEST(sz3 == 0u);
    BOOST_TEST(b3 == nullptr);

    // Mark read to return buffer to pool
    manager.MarkRead(readable);

    // No readable buffers left
    auto emptyReadable = manager.GetReadableBuffer();
    BOOST_TEST(emptyReadable == nullptr);

    // Now can reserve again
    unsigned int sz4 = 0u;
    auto b4 = manager.Reserve(56u, sz4);
    BOOST_TEST(sz4 == 56u);
    BOOST_TEST(b4 != nullptr);
}

