#include "UEBoidManager.h"
#include "Components/BrushComponent.h"
#include "UEBoids.h"
#include "Runtime\Core\Public\Math\Box.h"
#include "Runtime\Engine\Classes\Kismet\KismetMathLibrary.h"
#include "Runtime/Engine/Classes/Components/InstancedStaticMeshComponent.h"

ABoidManager::ABoidManager(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	PrimaryActorTick.bCanEverTick = true;
	SetActorTickEnabled(true);
	myMeshComponent = CreateDefaultSubobject<UInstancedStaticMeshComponent>(TEXT("myMeshComponent"));
	myMeshComponent->SetupAttachment(RootComponent);
	GetBrushComponent()->Mobility = EComponentMobility::Static;
	BrushColor = FColor(255, 255, 255, 255);
	bColored = true;
}

ABoidManager::~ABoidManager()
{
	myBoidData.Empty();
}

void ABoidManager::BeginPlay()
{
	Super::BeginPlay();
	myMeshComponent->SetStaticMesh(myMesh);
	myBoidData.Reserve(myParameters.myNumBoids);

	const FBox worldBounds = GetComponentsBoundingBox(false);
	myAABBMin = worldBounds.GetCenter() - worldBounds.GetExtent();
	myAABBMax = worldBounds.GetCenter() + worldBounds.GetExtent();

	for (int idx = 0; idx < myParameters.myNumBoids; ++idx)
	{
		int newIdx = myBoidData.Emplace();
		BoidState& state = myBoidData[newIdx];

		state.pos = (FMath::RandPointInBox(GetComponentsBoundingBox(true)) / GetTransform().GetScale3D());
		state.vel = FVector(FMath::VRand()).GetSafeNormal() * myParameters.myVelocityMax;

		FTransform instanceTransform;
		instanceTransform.SetLocation(state.pos);
		instanceTransform.SetScale3D(FVector(myMeshScale));
		myMeshComponent->AddInstance(instanceTransform);
	}

	myParameters.Update();
}

void ABoidManager::Tick(float DeltaTime)
{
	Super::Tick(DeltaTime);

	const int totalBoids = myBoidData.Num();
	if (totalBoids == 0) return;

	for (int i = 0; i < totalBoids; ++i)
	{
		BoidState& current = myBoidData[i];
		FVector groupCenter(0.f);
		FVector avgVelocity(0.f);
		FVector repulsionForce(0.f);

		int countCohesion = 0;
		int countAlignment = 0;

		for (int j = 0; j < totalBoids; ++j)
		{
			if (i == j) continue;

			const BoidState& neighbor = myBoidData[j];
			float distSq = FVector::DistSquared(current.pos, neighbor.pos);

			// Cohesion: accumulate nearby positions
			if (distSq < myParameters.myCohesionRange2)
			{
				groupCenter += neighbor.pos;
				++countCohesion;
			}

			// Separation: push away from close neighbors
			if (distSq < myParameters.myAvoidRange2)
			{
				repulsionForce += (current.pos - neighbor.pos).GetSafeNormal() * (1.0f / FMath::Sqrt(distSq));
			}

			// Alignment: accumulate nearby velocities
			if (distSq < myParameters.myAlignRange2)
			{
				avgVelocity += neighbor.vel;
				++countAlignment;
			}
		}

		// Compute steering forces
		FVector cohesionSteer = FVector::ZeroVector;
		if (countCohesion > 0)
		{
			groupCenter /= static_cast<float>(countCohesion);
			cohesionSteer = (groupCenter - current.pos).GetSafeNormal() * myParameters.myCohesionWeight;
		}

		FVector alignmentSteer = FVector::ZeroVector;
		if (countAlignment > 0)
		{
			avgVelocity /= static_cast<float>(countAlignment);
			alignmentSteer = avgVelocity.GetSafeNormal() * myParameters.myAlignWeight;
		}

		// Boundary avoidance via clamping
		FVector boundaryCorrection(0.f);
		boundaryCorrection.X = (current.pos.X < myAABBMin.X) ? myParameters.myAvoidBoundsWeight :
		                       (current.pos.X > myAABBMax.X) ? -myParameters.myAvoidBoundsWeight : 0.f;
		boundaryCorrection.Y = (current.pos.Y < myAABBMin.Y) ? myParameters.myAvoidBoundsWeight :
		                       (current.pos.Y > myAABBMax.Y) ? -myParameters.myAvoidBoundsWeight : 0.f;
		boundaryCorrection.Z = (current.pos.Z < myAABBMin.Z) ? myParameters.myAvoidBoundsWeight :
		                       (current.pos.Z > myAABBMax.Z) ? -myParameters.myAvoidBoundsWeight : 0.f;

		// Combine all influences into final desired velocity
		FVector desiredVel = current.vel + cohesionSteer + repulsionForce + alignmentSteer + boundaryCorrection;
		desiredVel = desiredVel.GetClampedToMaxSize(myParameters.myVelocityMax);

		// Smoothly interpolate toward desired velocity
		current.vel = FMath::Lerp(current.vel, desiredVel, DeltaTime * 5.0f);

		// Update position
		current.pos += current.vel * DeltaTime;

		// Update visual transform
		FTransform tx;
		myMeshComponent->GetInstanceTransform(i, tx);

		// Use FindBetweenNormals for robust orientation
		if (!current.vel.IsNearlyZero())
		{
			FVector forwardDir = current.vel.GetSafeNormal();
			FQuat rot = FQuat::FindBetweenNormals(FVector::ForwardVector, forwardDir);
			tx.SetRotation(rot);
		}

		tx.SetLocation(current.pos);
		myMeshComponent->UpdateInstanceTransform(i, tx, false, i == totalBoids - 1, true);
	}
}

#include "types.h"
#include <3ds.h>
