    void ScreenImpl::GetFrameBufferInfos(int& rowStride, int& bpp, GSPGPU_FramebufferFormat& fmt) const
    {
        rowStride = _stride;
        bpp = _bytesPerPixel;
        fmt = _format;
    }

    u8* ScreenImpl::GetLeftFrameBuffer(bool current)
    {
        return reinterpret_cast<u8*>(_leftFrameBuffers[current ? _activeBuffer : !_activeBuffer]);
    }

    u8* ScreenImpl::GetLeftFrameBuffer(int posX, int posY)
    {
        posX = std::max(posX, 0);
        posX = std::min(posX, (_isTopScreen ? 400 : 320));
        posY = std::max(posY, 0);
        posY = std::min(posY, 240);
        posY += _rowSize - 240;
        u32 offset = (_rowSize - 1 - posY + posX * _rowSize) * _bytesPerPixel;
        return reinterpret_cast<u8*>(_leftFrameBuffers[!_activeBuffer]) + offset;
    }

    u8* ScreenImpl::GetRightFrameBuffer(bool current)
    {
        if (!_isTopScreen)
            return nullptr;
        return reinterpret_cast<u8*>(_rightFrameBuffers[current ? _activeBuffer : !_activeBuffer]);
    }

    u8* ScreenImpl::GetRightFrameBuffer(int posX, int posY)
    {
        if (!_isTopScreen)
            return nullptr;
        posX = std::max(posX, 0);
        posX = std::min(posX, (_isTopScreen ? 400 : 320));
        posY = std::max(posY, 0);
        posY = std::min(posY, 240);
        posY += _rowSize - 240;
        u32 offset = (_rowSize - 1 - posY + posX * _rowSize) * _bytesPerPixel;
        return reinterpret_cast<u8*>(_rightFrameBuffers[!_activeBuffer]) + offset;
    }

    void ScreenImpl::GetPosFromAddress(u32 addr, int& posX, int& posY)
    {
        addr -= _leftFrameBuffers[!_activeBuffer];
        posX = addr / (_rowSize * _bytesPerPixel);
        posY = _rowSize - 1 - ((addr / _bytesPerPixel) - (_rowSize * posX));
        posY -= _rowSize - 240;
    }
}

