#include <bits/stdc++.h>
using namespace std;
using ll = long long int;

int main(void) {
    ll height, width;
    scanf("%lld %lld", &height, &width);

    // Initialize answer with a large value
    ll best_diff = (ll)(1e18);

    // First set of iterations: vertical cuts based on height partitioning
    for (ll top_part = 1; top_part < height; ++top_part) {
        ll optimal_mid = (top_part + height) / 2;
        ll area_top = width * top_part;

        // Search around the optimal midpoint with small offsets
        for (ll cut_pos = max(optimal_mid - 2LL, top_part); 
             cut_pos <= min(optimal_mid + 2LL, height); ++cut_pos) {

            ll area_middle = (cut_pos - top_part) * width;
            ll area_bottom = (height - cut_pos) * width;

            ll max_area = max(area_top, max(area_middle, area_bottom));
            ll min_area = min(area_top, min(area_middle, area_bottom));
            ll current_diff = max_area - min_area;

            best_diff = min(best_diff, current_diff);
        }
    }

    // Second set: horizontal partitions using fixed mid-point near half width
    for (ll top_part = 1; top_part < height; ++top_part) {
        ll center_width = width / 2;
        ll area_top = width * top_part;

        for (ll split_col = max(center_width - 2LL, 0LL); 
             split_col <= min(center_width + 2LL, width); ++split_col) {

            ll area_left = (height - top_part) * split_col;
            ll area_right = (height - top_part) * (width - split_col);

            ll max_area = max(area_top, max(area_left, area_right));
            ll min_area = min(area_top, min(area_left, area_right));
            ll current_diff = max_area - min_area;

            best_diff = min(best_diff, current_diff);
        }
    }

    // Third set: horizontal cuts based on width partitioning
    for (ll left_part = 1; left_part < width; ++left_part) {
        ll optimal_mid = (left_part + width) / 2;
        ll area_left = height * left_part;

        for (ll cut_row = max(optimal_mid - 2LL, left_part); 
             cut_row <= min(optimal_mid + 2LL, width); ++cut_row) {

            ll area_center = height * (cut_row - left_part);
            ll area_right = height * (width - cut_row);

            ll max_area = max(area_left, max(area_center, area_right));
            ll min_area = min(area_left, min(area_center, area_right));
            ll current_diff = max_area - min_area;

            best_diff = min(best_diff, current_diff);
        }
    }

    // Fourth set: vertical partitions using fixed mid-point near half height
    for (ll left_part = 1; left_part < width; ++left_part) {
        ll center_height = height / 2;
        ll area_left = height * left_part;

        for (ll split_row = max(center_height - 2LL, 0LL); 
             split_row <= min(center_height + 2LL, height); ++split_row) {

            ll area_upper = split_row * (width - left_part);
            ll area_lower = (height - split_row) * (width - left_part);

            ll max_area = max(area_left, max(area_upper, area_lower));
            ll min_area = min(area_left, min(area_upper, area_lower));
            ll current_diff = max_area - min_area;

            best_diff = min(best_diff, current_diff);
        }
    }

    printf("%lld\n", best_diff);
    return 0;
}

#include "BBE/BrotBoxEngine.h"
#include <iostream>

constexpr int SCREEN_WIDTH = 1280;
constexpr int SCREEN_HEIGHT = 720;

class InteractiveRectangles : public bbe::Game
{
    bbe::Vector2 projectionDirection = bbe::Vector2{4, 1}.normalize();
    bbe::RectangleRotated rectA;
    bbe::RectangleRotated rectB;

    static constexpr float rotationSpeedBase = 1.0f;

    virtual void onStart() override
    {
        // Initialize two rotated rectangles with different positions and dimensions
        rectA = bbe::RectangleRotated(100, 200, 100, 140, 0);
        rectB = bbe::RectangleRotated(400, 400, 40, 20, 0);
    }

    virtual void update(float deltaTime) override
    {
        // Rotate both rectangles at different speeds
        float currentRotationA = rectA.getRotation() + deltaTime * rotationSpeedBase;
        float currentRotationB = rectB.getRotation() + deltaTime * 0.4f * rotationSpeedBase;

        rectA.setRotation(currentRotationA);
        rectB.setRotation(currentRotationB);

        // Move rectB to follow the mouse cursor
        rectB.setX(getMouseX());
        rectB.setY(getMouseY());

        // Update projection direction when left mouse button is pressed
        if (isMouseDown(bbe::MouseButton::LEFT))
        {
            projectionDirection = getMouse().normalize();
        }
    }

    virtual void draw3D(bbe::PrimitiveBrush3D&) override
    {
        // No 3D rendering needed for this example
    }

    virtual void draw2D(bbe::PrimitiveBrush2D& brush) override
    {
        // Draw first rectangle (rectA)
        brush.setColorRGB(1, 1, 1);
        brush.fillRect(rectA);

        // Get and draw vertices of rectA
        auto verticesA = rectA.getVertices();
        brush.setColorRGB(1, 0, 0);
        brush.fillLineStrip(verticesA, true);

        // Project rectA onto the projection direction
        const auto projectionResult = rectA.project(projectionDirection);
        brush.setColorRGB(0, 1, 0);
        brush.fillLine(projectionDirection * projectionResult.start, 
                       projectionDirection * projectionResult.stop);

        // Project each vertex of rectA and draw lines from original to projected points
        auto projectedPoints = bbe::Math::project(verticesA, projectionDirection);
        assert(projectedPoints.getLength() == verticesA.getLength());
        for (size_t i = 0; i < projectedPoints.getLength(); ++i)
        {
            brush.fillLine(verticesA[i], projectedPoints[i]);
        }

        // Draw normals of rectA
        auto normalsA = rectA.getNormals();
        brush.setColorRGB(0, 0, 1);
        for (size_t i = 0; i < normalsA.getLength(); ++i)
        {
            brush.fillLine(verticesA[i], normalsA[i] * 10 + verticesA[i]);
        }

        // Determine color based on intersection with rectB
        if (rectB.intersects(rectA))
        {
            brush.setColorRGB(0, 1, 1); // Cyan if intersecting
        }
        else
        {
            brush.setColorRGB(1, 1, 0); // Yellow if not intersecting
        }

        // Draw second rectangle (rectB)
        brush.fillRect(rectB);
    }

    virtual void onEnd() override
    {
        // Cleanup or finalization logic (if needed)
    }
};

int main()
{
    InteractiveRectangles* gameInstance = new InteractiveRectangles();
    gameInstance->start(SCREEN_WIDTH, SCREEN_HEIGHT, "Interactive Rotating Rectangles");
    return 0;
}

