#include "indirect_inode.hpp"
#include <algorithm>
#include <stdexcept>

namespace FSFS {

IndirectInode::IndirectInode(const inode_block& inode_data) : inode(inode_data) { clear(); }

int32_t IndirectInode::ptr(int32_t index) const {
    return indirect_ptrs_list.at(index);
}

int32_t IndirectInode::last_indirect_ptr(int32_t block_index) const {
    if (block_index < 0 || static_cast<size_t>(block_index) >= indirect_block_n.size()) {
        return fs_nullptr;
    }
    return indirect_block_n[block_index];
}

// Helper: allocate and link one new indirect block
static void link_new_indirect_block(Block& data_block, BlockBitmap& data_bitmap,
                                    int32_t& prev_block_addr, int32_t& next_block_addr) {
    next_block_addr = data_bitmap.next_free(0);
    if (next_block_addr == fs_nullptr) return;

    data_bitmap.set_status(next_block_addr, true);
    int32_t prev_abs_addr = data_block.data_n_to_block_n(prev_block_addr);
    data_block.write(prev_abs_addr,
                     reinterpret_cast<const uint8_t*>(&next_block_addr),
                     -static_cast<int32_t>(sizeof(int32_t)), sizeof(int32_t));
    prev_block_addr = next_block_addr;
}

int32_t IndirectInode::commit(Block& data_block, BlockBitmap& data_bitmap, PtrsLList& ptrs_to_allocate) {
    if (inode.indirect_inode_ptr == fs_nullptr) {
        throw std::runtime_error("Attempted to commit to indirect inode without base pointer.");
    }

    if (ptrs_to_allocate.empty()) {
        return 0;
    }

    // Initialize indirect block list if empty
    if (indirect_block_n.empty()) {
        indirect_block_n.push_back(inode.indirect_inode_ptr);
    }

    // Count how many indirect pointers already used by current file size
    int32_t total_direct_used = meta_n_direct_ptrs;
    int32_t current_file_blocks = data_block.bytes_to_blocks(inode.file_len);
    int32_t existing_ptrs_count = std::max(current_file_blocks - total_direct_used, 0);

    int32_t new_ptr_count = static_cast<int32_t>(ptrs_to_allocate.size());
    int32_t remaining_to_write = new_ptr_count;

    // Extend local buffer to hold all new pointers
    indirect_ptrs_list.resize(existing_ptrs_count + new_ptr_count);

    // Copy new pointers into buffer after existing ones
    std::copy_n(std::make_move_iterator(ptrs_to_allocate.begin()),
                new_ptr_count,
                indirect_ptrs_list.begin() + existing_ptrs_count);

    // Clear input list
    ptrs_to_allocate.clear();

    // Determine position within first indirect block
    int32_t entries_per_block = data_block.get_n_addreses_in_block() - 1;
    int32_t offset_in_first_block = existing_ptrs_count % entries_per_block;
    int32_t space_left_in_first = entries_per_block - offset_in_first_block;
    int32_t to_write_first = std::min(space_left_in_first, remaining_to_write);

    if (to_write_first > 0) {
        int32_t abs_addr = data_block.data_n_to_block_n(indirect_block_n[0]);
        uint8_t* src = reinterpret_cast<uint8_t*>(&indirect_ptrs_list[existing_ptrs_count]);
        data_block.write(abs_addr, src, offset_in_first_block * sizeof(int32_t),
                         to_write_first * sizeof(int32_t));
        remaining_to_write -= to_write_first;
        existing_ptrs_count += to_write_first;
    }

    // Allocate additional indirect blocks as needed
    auto allocate_and_fill_next_block = [&](int32_t& written_so_far) -> bool {
        int32_t new_block;
        link_new_indirect_block(data_block, data_bitmap, indirect_block_n.back(), new_block);
        if (new_block == fs_nullptr) return false;

        indirect_block_n.push_back(new_block);
        int32_t capacity = entries_per_block;
        int32_t to_write_now = std::min(capacity, remaining_to_write);
        if (to_write_now <= 0) return true;

        uint8_t* src = reinterpret_cast<uint8_t*>(&indirect_ptrs_list[written_so_far]);
        int32_t target_abs = data_block.data_n_to_block_n(new_block);
        data_block.write(target_abs, src, 0, to_write_now * sizeof(int32_t));

        written_so_far += to_write_now;
        remaining_to_write -= to_write_now;
        return true;
    };

    while (remaining_to_write > 0) {
        if (!allocate_and_fill_next_block(existing_ptrs_count)) {
            break;
        }
    }

    clear();
    return new_ptr_count - remaining_to_write;
}

void IndirectInode::clear() {
    indirect_ptrs_list.clear();
    indirect_block_n.clear();
}

void IndirectInode::load(Block& data_block) {
    int32_t total_direct_used = meta_n_direct_ptrs;
    int32_t total_indirect_needed = data_block.bytes_to_blocks(inode.file_len) - total_direct_used;

    if (total_indirect_needed <= 0 || inode.indirect_inode_ptr == fs_nullptr) {
        return;
    }

    clear();
    indirect_ptrs_list.resize(total_indirect_needed);
    indirect_block_n.reserve((total_indirect_needed + data_block.get_n_addreses_in_block() - 2) / (data_block.get_n_addreses_in_block() - 1));

    int32_t current_block = inode.indirect_inode_ptr;
    indirect_block_n.push_back(current_block);

    int32_t entries_per_block = data_block.get_n_addreses_in_block() - 1;
    int32_t bytes_per_block = data_block.get_block_size() - sizeof(int32_t);
    int32_t read_so_far = 0;

    // Read full indirect blocks
    while (read_so_far + entries_per_block <= total_indirect_needed) {
        int32_t abs_addr = data_block.data_n_to_block_n(current_block);
        uint8_t* dst = reinterpret_cast<uint8_t*>(&indirect_ptrs_list[read_so_far]);
        data_block.read(abs_addr, dst, 0, bytes_per_block);
        data_block.read(abs_addr, dst + bytes_per_block, bytes_per_block, sizeof(int32_t));
        current_block = *reinterpret_cast<int32_t*>(dst + bytes_per_block);
        indirect_block_n.push_back(current_block);
        read_so_far += entries_per_block;
    }

    // Handle final partial block
    if (read_so_far < total_indirect_needed) {
        int32_t remaining = total_indirect_needed - read_so_far;
        int32_t abs_addr = data_block.data_n_to_block_n(current_block);
        uint8_t* dst = reinterpret_cast<uint8_t*>(&indirect_ptrs_list[read_so_far]);
        data_block.read(abs_addr, dst, 0, remaining * sizeof(int32_t));
    }
}

}

#include "Animation_RuntimeGraph_RootMotionRecorder.h"
#include "System/Animation/AnimationSkeleton.h"
#include "System/Core/Drawing/DebugDrawing.h"
//-------------------------------------------------------------------------
#if KRG_DEVELOPMENT_TOOLS

namespace KRG::Animation
{
    RootMotionRecorder::RootMotionRecorder()
        : m_currentBufferSlot(0)
    {
        m_recordedRootTransforms.reserve(c_maxRecordedFrames);
    }

    void RootMotionRecorder::SetDebugMode(DebugMode mode)
    {
        // Reset internal state if entering drawing modes
        if (m_debugMode < DebugMode::DrawRecordedRootMotion && mode >= DebugMode::DrawRecordedRootMotion)
        {
            m_currentBufferSlot = 0;
            m_recordedRootTransforms.clear();
        }
        m_debugMode = mode;
    }

    void RootMotionRecorder::StartCharacterUpdate(Transform const& characterWorldTransform)
    {
        m_startWorldTransform = characterWorldTransform;
        m_recordedActions.clear();
    }

    void RootMotionRecorder::EndCharacterUpdate(Transform const& characterWorldTransform)
    {
        m_endWorldTransform = characterWorldTransform;

        if (m_debugMode >= DebugMode::DrawRecordedRootMotion)
        {
            KRG_ASSERT(m_currentBufferSlot < c_maxRecordedFrames);

            // Ensure space exists in vector before writing
            if (m_currentBufferSlot == static_cast<int32>(m_recordedRootTransforms.size()))
            {
                m_recordedRootTransforms.emplace_back();
            }

            auto& entry = m_recordedRootTransforms[m_currentBufferSlot];

            if (m_recordedActions.empty())
            {
                entry.m_actualTransform = characterWorldTransform;
                entry.m_expectedTransform = characterWorldTransform;
            }
            else
            {
                entry.m_actualTransform = characterWorldTransform;
                entry.m_expectedTransform = m_recordedActions.back().m_rootMotionDelta * m_startWorldTransform;
            }

            // Advance circular index
            ++m_currentBufferSlot;
            if (m_currentBufferSlot >= c_maxRecordedFrames)
            {
                m_currentBufferSlot = 0;
            }
        }
    }

    void RootMotionRecorder::DrawDebug(Drawing::DrawContext& drawingContext)
    {
        if (m_debugMode == DebugMode::DrawRoot)
        {
            DrawRootBone(drawingContext, m_endWorldTransform);
        }
        else if (m_debugMode == DebugMode::DrawRecordedRootMotion ||
                 m_debugMode == DebugMode::DrawRecordedRootMotionAdvanced)
        {
            bool const isAdvanced = (m_debugMode == DebugMode::DrawRecordedRootMotionAdvanced);
            auto const verticalOffset = Vector(0.0f, 0.0f, 0.2f);
            static Color const actualColors[2] = { Colors::Blue, Colors::Red };
            static Color const expectedColors[2] = { Colors::Cyan, Colors::Magenta };

            auto DrawSegment = [&](int32 idxA, int32 idxB, int32 colorIndex)
            {
                drawingContext.DrawLine(
                    m_recordedRootTransforms[idxA].m_actualTransform.GetTranslation(),
                    m_recordedRootTransforms[idxB].m_actualTransform.GetTranslation(),
                    actualColors[colorIndex],
                    3.0f);

                drawingContext.DrawAxis(m_recordedRootTransforms[idxB].m_actualTransform, 0.1f, 2.0f);

                if (isAdvanced)
                {
                    drawingContext.DrawLine(
                        m_recordedRootTransforms[idxA].m_expectedTransform.GetTranslation() + verticalOffset,
                        m_recordedRootTransforms[idxB].m_expectedTransform.GetTranslation() + verticalOffset,
                        expectedColors[colorIndex],
                        3.0f);

                    Transform axisTfm = m_recordedRootTransforms[idxB].m_expectedTransform;
                    axisTfm.AddTranslation(verticalOffset);
                    drawingContext.DrawAxis(axisTfm, 0.1f, 2.0f);
                }
            };

            int32 const totalEntries = static_cast<int32>(m_recordedRootTransforms.size());
            bool const isFull = (totalEntries == c_maxRecordedFrames);

            if (!isFull)
            {
                for (int32 i = 1; i < m_currentBufferSlot; ++i)
                {
                    int32 const colorIdx = Math::IsEven(i) ? 0 : 1;
                    DrawSegment(i - 1, i, colorIdx);
                }
            }
            else
            {
                // First segment: from next slot after current to end
                for (int32 i = m_currentBufferSlot + 1; i < totalEntries; ++i)
                {
                    int32 const colorIdx = Math::IsEven(i) ? 0 : 1;
                    DrawSegment(i - 1, i, colorIdx);
                }

                // Second segment: wrap-around from beginning up to current
                for (int32 i = 1; i < m_currentBufferSlot; ++i)
                {
                    int32 const colorIdx = Math::IsEven(i) ? 0 : 1;
                    DrawSegment(i - 1, i, colorIdx);
                }

                // Final bridge between last and first segments
                if (m_currentBufferSlot != 0)
                {
                    DrawSegment(0, c_maxRecordedFrames - 1, 0);
                }
            }
        }
    }
}
