#define TEST(s) if (!(s)) { cout << __LINE__ << " " << #s << endl; exit(-1); }
#define DEBUG 0
const long long INF = 1e9;
namespace JohnsonSPFA {
struct graph {
    typedef int flow_type;
    typedef int cost_type;
    struct Edge {
        int src, dst;
        flow_type cap, flow;
        cost_type cost;
        size_t rev_idx;
    };

    vector<vector<Edge>> adj;
    int n;

    graph(int nodes) : n(nodes), adj(n) {}

    void add_edge(int u, int v, flow_type capacity, cost_type expense) {
        adj[u].push_back({u, v, capacity, 0, expense, adj[v].size()});
        adj[v].push_back({v, u, 0, 0, -expense, adj[u].size()-1});
    }

    // Standard max-flow using Edmonds-Karp
    flow_type compute_max_flow(int source, int sink) {
        vector<int> level(n), ptr(n);
        auto bfs_level = [&]() -> bool {
            fill(level.begin(), level.end(), -1);
            queue<int> q;
            q.push(source);
            level[source] = 0;

            while (!q.empty()) {
                int u = q.front(); q.pop();
                for (const auto& e : adj[u]) {
                    if (e.cap > e.flow && level[e.dst] == -1) {
                        level[e.dst] = level[u] + 1;
                        q.push(e.dst);
                    }
                }
            }
            return level[sink] != -1;
        };

        function<flow_type(int, flow_type)> dfs = [&](int u, flow_type cur_flow) -> flow_type {
            if (u == sink) return cur_flow;
            for (int& i = ptr[u]; i < adj[u].size(); ++i) {
                Edge& e = adj[u][i];
                if (e.cap > e.flow && level[e.dst] == level[u] + 1) {
                    flow_type pushed = dfs(e.dst, min(cur_flow, e.cap - e.flow));
                    if (pushed > 0) {
                        e.flow += pushed;
                        adj[e.dst][e.rev_idx].flow -= pushed;
                        return pushed;
                    }
                }
            }
            return 0;
        };

        // Reset flows
        for (auto& list : adj)
            for (auto& e : list) e.flow = 0;

        flow_type total_flow = 0;
        while (bfs_level()) {
            fill(ptr.begin(), ptr.end(), 0);
            flow_type f;
            while ((f = dfs(source, INF)) > 0) {
                total_flow += f;
            }
        }
        return total_flow;
    }

    // Johnson-style reweighting + Dijkstra for shortest paths
    bool find_negative_cycle(int source, vector<int>& path, cost_type& cycle_cost, int& cycle_length) {
        vector<cost_type> dist(n, INF);
        vector<int> parent(n, -1);
        vector<bool> in_queue(n, false);
        queue<int> q;

        // Initialize with zero-cost edges from source
        for (int i = 0; i < n; ++i) {
            dist[i] = 0;
            parent[i] = -1;
            q.push(i);
            in_queue[i] = true;
        }

        vector<int> count(n, 0);
        while (!q.empty()) {
            int u = q.front(); q.pop();
            in_queue[u] = false;
            count[u]++;

            if (count[u] > n) {
                // Found negative cycle - reconstruct it
                int v = u;
                for (int k = 0; k < n; ++k) {
                    v = parent[v];
                }

                int start = v;
                path.clear();
                do {
                    path.push_back(v);
                    v = parent[v];
                } while (v != start);
                path.push_back(start);

                // Calculate actual cycle cost
                cycle_cost = 0;
                cycle_length = path.size() - 1;
                for (int i = 0; i < cycle_length; ++i) {
                    int u_node = path[i];
                    int v_node = path[(i+1) % cycle_length];
                    for (const auto& e : adj[u_node]) {
                        if (e.dst == v_node && e.cap > e.flow) {
                            cycle_cost += e.cost;
                            break;
                        }
                    }
                }
                return true;
            }

            for (const auto& e : adj[u]) {
                if (e.cap > e.flow && dist[e.dst] > dist[u] + e.cost) {
                    dist[e.dst] = dist[u] + e.cost;
                    parent[e.dst] = u;
                    if (!in_queue[e.dst]) {
                        q.push(e.dst);
                        in_queue[e.dst] = true;
                    }
                }
            }
        }
        return false;
    }

    // Cycle cancellation using SPFA-based detection
    void cancel_cycles() {
        while (true) {
            vector<int> cycle_path;
            cost_type cycle_cost;
            int cycle_len;

            if (!find_negative_cycle(0, cycle_path, cycle_cost, cycle_len)) {
                break;
            }

            if (cycle_cost >= 0) break;

            // Find minimum residual capacity along the cycle
            flow_type min_cap = INF;
            for (int i = 0; i < cycle_len; ++i) {
                int u = cycle_path[i];
                int v = cycle_path[(i+1) % cycle_len];
                for (auto& e : adj[u]) {
                    if (e.dst == v && e.cap > e.flow) {
                        min_cap = min(min_cap, e.cap - e.flow);
                        break;
                    }
                }
            }

            // Augment flow along the cycle
            for (int i = 0; i < cycle_len; ++i) {
                int u = cycle_path[i];
                int v = cycle_path[(i+1) % cycle_len];
                for (auto& e : adj[u]) {
                    if (e.dst == v && e.cap > e.flow) {
                        e.flow += min_cap;
                        adj[e.dst][e.rev_idx].flow -= min_cap;
                        break;
                    }
                }
            }
        }
    }

    pair<flow_type, cost_type> solve_min_cost_flow(int s, int t) {
        flow_type total_flow = compute_max_flow(s, t);
        cancel_cycles();

        cost_type total_cost = 0;
        for (int u = 0; u < n; ++u) {
            for (const auto& e : adj[u]) {
                if (e.flow > 0) {
                    total_cost += static_cast<cost_type>(e.flow) * e.cost;
                }
            }
        }
        return {total_flow, total_cost};
    }
};
}

namespace OptimizedSuccessiveShortestPath {
struct graph {
    typedef int flow_type;
    typedef int cost_type;
    struct Edge {
        int src, dst;
        flow_type cap, flow;
        cost_type cost;
        size_t rev_idx;
    };

    vector<vector<Edge>> adj;
    int n;

    graph(int nodes) : n(nodes), adj(n) {}

    void add_edge(int u, int v, flow_type capacity, cost_type expense) {
        adj[u].push_back({u, v, capacity, 0, expense, adj[v].size()});
        adj[v].push_back({v, u, 0, 0, -expense, adj[u].size()-1});
    }

    pair<flow_type, cost_type> min_cost_flow(int source, int sink) {
        flow_type total_flow = 0;
        cost_type total_cost = 0;

        // Initialize flows
        for (auto& list : adj)
            for (auto& e : list) e.flow = 0;

        // Potential function for Johnson's algorithm
        vector<cost_type> potential(n, 0);

        auto dijkstra = [&](vector<int>& prev_node, vector<cost_type>& dist) -> bool {
            dist.assign(n, INF);
            prev_node.assign(n, -1);
            priority_queue<pair<cost_type, int>, vector<pair<cost_type, int>>, greater<pair<cost_type, int>>> pq;

            dist[source] = 0;
            pq.push({0, source});

            while (!pq.empty()) {
                auto [cur_dist, u] = pq.top(); pq.pop();
                if (cur_dist != dist[u]) continue;

                for (const auto& e : adj[u]) {
                    if (e.cap <= e.flow) continue;

                    cost_type reduced_cost = e.cost + potential[u] - potential[e.dst];
                    if (dist[e.dst] > dist[u] + reduced_cost) {
                        dist[e.dst] = dist[u] + reduced_cost;
                        prev_node[e.dst] = e.rev_idx;
                        pq.push({dist[e.dst], e.dst});
                    }
                }
            }
            return dist[sink] != INF;
        };

        while (true) {
            vector<int> prev_node;
            vector<cost_type> dist;

            if (!dijkstra(prev_node, dist)) break;

            // Update potentials
            for (int i = 0; i < n; ++i) {
                if (dist[i] < INF) {
                    potential[i] += dist[i];
                }
            }

            // Find bottleneck capacity
            flow_type bottleneck = INF;
            for (int v = sink; v != source; ) {
                int rev_idx = prev_node[v];
                int u = adj[v][rev_idx].src;
                const Edge& e = adj[u][adj[v][rev_idx].rev_idx];
                bottleneck = min(bottleneck, e.cap - e.flow);
                v = u;
            }

            // Augment flow
            for (int v = sink; v != source; ) {
                int rev_idx = prev_node[v];
                int u = adj[v][rev_idx].src;
                Edge& e = adj[u][adj[v][rev_idx].rev_idx];
                e.flow += bottleneck;
                adj[v][rev_idx].flow -= bottleneck;
                v = u;
            }

            total_flow += bottleneck;
            total_cost += bottleneck * (potential[sink] - potential[source]);
        }

        return {total_flow, total_cost};
    }
};
}

// Time measurement utility
double get_time() {
    static clock_t last_time = 0;
    clock_t current = clock();
    double elapsed = 1.0 * (current - last_time) / CLOCKS_PER_SEC;
    last_time = current;
    return elapsed;
}

int main() {
    for (int seed = 0; seed < 5000; ++seed) {
        cout << "--------------------" << endl;
        cout << "Test case: seed = " << seed << endl;
        srand(seed);

        int n = 200;
        OptimizedSuccessiveShortestPath::graph g1(n);
        JohnsonSPFA::graph g2(n);

        // Generate random graph
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) {
                if (i == j) continue;
                if (rand() % 3 == 0) {  // Sparsify slightly
                    int capacity = 1 + rand() % 10;
                    int cost = 1 + rand() % 10;
                    g1.add_edge(i, j, capacity, cost);
                    g2.add_edge(i, j, capacity, cost);
                }
            }
        }

        int source = 0;
        int sink = n - 1;

        // Run first algorithm
        get_time();  // reset timer
        auto result1 = g1.min_cost_flow(source, sink);
        double time1 = get_time();

        // Run second algorithm
        auto result2 = g2.solve_min_cost_flow(source, sink);
        double time2 = get_time();

        cout << "Algorithm 1: flow=" << result1.fst << ", cost=" << result1.snd 
             << ", time=" << fixed << time1 << endl;
        cout << "Algorithm 2: flow=" << result2.fst << ", cost=" << result2.snd 
             << ", time=" << fixed << time2 << endl;

        // Verify results match
        if (result1.fst != result2.fst || result1.snd != result2.snd) {
            cout << "MISMATCH DETECTED!" << endl;
            break;
        }
    }

    cout << "All tests passed successfully." << endl;
    return 0;
}

