GBlender::GBlender()
    : mBlendDesc(D3D11_BLEND_DESC{}), mState(nullptr), mColor(GVector4D{})
{
    // Intentionally left empty; initialization handled in member initializer list
}

GBlender::~GBlender()
{
    if (mState != nullptr)
    {
        mState->Release();
        mState = nullptr;
    }
}

bool GBlender::Create()
{
    // Initialize default blend description for standard alpha blending
    ZeroMemory(&mBlendDesc, sizeof(mBlendDesc));
    mBlendDesc.AlphaToCoverageEnable = FALSE;
    mBlendDesc.IndependentBlendEnable = FALSE;

    auto& rt = mBlendDesc.RenderTarget[0];
    rt.BlendEnable = TRUE;
    rt.RenderTargetWriteMask = D3D11_COLOR_WRITE_ENABLE_ALL;
    rt.BlendOp = D3D11_BLEND_OP_ADD;
    rt.BlendOpAlpha = D3D11_BLEND_OP_ADD;
    rt.SrcBlend = D3D11_BLEND_SRC_ALPHA;
    rt.SrcBlendAlpha = D3D11_BLEND_ONE;
    rt.DestBlend = D3D11_BLEND_INV_SRC_ALPHA;
    rt.DestBlendAlpha = D3D11_BLEND_ZERO;

    return Create(mBlendDesc);
}

bool GBlender::Create(const D3D11_BLEND_DESC& desc)
{
    if (&desc != &mBlendDesc)
    {
        mBlendDesc = desc;
    }

    ID3D11Device* device = GEngineDevice::MainDevice().GetIDevice().Get();
    if (FAILED(device->CreateBlendState(&mBlendDesc, &mState)))
    {
        CRASH_PROG;
        return false;
    }

    return true;
}

void GBlender::Update()
{
    ID3D11DeviceContext* context = GEngineDevice::MainDevice().GetIContext().Get();
    context->OMSetBlendState(
        mState,
        reinterpret_cast<const FLOAT*>(&mColor),
        0xFFFFFFFFu  // sample mask: all bits enabled
    );
}

