namespace app {

class ScopedLock {
public:
    explicit ScopedLock(CMutex& mtx) : mMutex(mtx) { mMutex.lock(); }
    ~ScopedLock() { mMutex.unlock(); }
private:
    CMutex& mMutex;
};

CMemoryHub::CMemoryHub() :
    mReferenceCount(1) {
    adjustPageSizes(16);
}

CMemoryHub::~CMemoryHub() {
    APP_ASSERT(0 == mReferenceCount);
}

void CMemoryHub::grab() {
    APP_ASSERT(mReferenceCount > 0);
    AppAtomicIncrementFetch(&mReferenceCount);
}

void CMemoryHub::drop() {
    s32 newCount = AppAtomicDecrementFetch(&mReferenceCount);
    APP_ASSERT(newCount >= 0);
    if (0 == newCount) {
        delete this;
    }
}

void CMemoryHub::adjustPageSizes(s32 factor) {
    mBlockPoolSmall.setPageSize(128 * factor);
    mBlockPoolMedium.setPageSize(512 * factor);
    mBlockPoolLarge.setPageSize(2048 * factor);
    mBlockPoolXLarge.setPageSize(8192 * factor);
    mBlockPoolHuge.setPageSize(10240 * factor);
}

s8* CMemoryHub::allocateAndClear(u64 requestedBytes, u64 alignment/* = sizeof(void*)*/) {
    s8* ptr = allocate(requestedBytes, alignment);
    if (ptr) {
        memset(ptr, 0, requestedBytes);
    }
    return ptr;
}

s8* CMemoryHub::allocate(u64 requestedBytes, u64 alignment/* = sizeof(void*)*/) {
#if defined(APP_DEBUG)
    grab();
#endif

    // Ensure minimum alignment for metadata header
    if (alignment < sizeof(SMemHead)) {
        alignment = sizeof(SMemHead);
    }

    // Reserve space for header + requested size, then align total
    u64 totalSize = requestedBytes + alignment;
    totalSize = APP_ALIGN_DATA(totalSize, alignment);

#ifdef APP_DISABLE_BYTE_POOL
    void* raw = malloc(totalSize);
    return reinterpret_cast<s8*>(raw);
#endif

    // Determine required pool size category
    EMemoryType type = EMT_DEFAULT;
    void* raw = nullptr;

    do {
        if (totalSize <= 128) {
            type = EMT_128;
#ifdef APP_THREADSAFE_MEMORY_POOL
            ScopedLock lock(mMutexSmall);
#endif
            raw = mBlockPoolSmall.allocate();
            break;
        }
        if (totalSize <= 512) {
            type = EMT_512;
#ifdef APP_THREADSAFE_MEMORY_POOL
            ScopedLock lock(mMutexMedium);
#endif
            raw = mBlockPoolMedium.allocate();
            break;
        }
        if (totalSize <= 2048) {
            type = EMT_2048;
#ifdef APP_THREADSAFE_MEMORY_POOL
            ScopedLock lock(mMutexLarge);
#endif
            raw = mBlockPoolLarge.allocate();
            break;
        }
        if (totalSize <= 8192) {
            type = EMT_8192;
#ifdef APP_THREADSAFE_MEMORY_POOL
            ScopedLock lock(mMutexXLarge);
#endif
            raw = mBlockPoolXLarge.allocate();
            break;
        }
        if (totalSize <= 10240) {
            type = EMT_10K;
#ifdef APP_THREADSAFE_MEMORY_POOL
            ScopedLock lock(mMutexHuge);
#endif
            raw = mBlockPoolHuge.allocate();
            break;
        }

        // Fallback: use system allocator with extra byte for tracking
        raw = ::malloc(totalSize + 1);
        type = EMT_DEFAULT;
    } while (false);

    if (!raw) {
        return nullptr;
    }

    return getUserPointer(static_cast<s8*>(raw), alignment, type);
}

void CMemoryHub::release(void* userPtr) {
    if (!userPtr) {
        return;
    }

#if defined(APP_DEBUG)
    drop();
#endif

#ifdef APP_DISABLE_BYTE_POOL
    ::free(userPtr);
    return;
#endif

    s8* realPtr = nullptr;
    EMemoryType memType = getRealPointer(userPtr, realPtr);

    switch (memType) {
    case EMT_128: {
#ifdef APP_THREADSAFE_MEMORY_POOL
        ScopedLock lock(mMutexSmall);
#endif
        mBlockPoolSmall.release(reinterpret_cast<u8(*)[128]>(realPtr));
        break;
    }
    case EMT_512: {
#ifdef APP_THREADSAFE_MEMORY_POOL
        ScopedLock lock(mMutexMedium);
#endif
        mBlockPoolMedium.release(reinterpret_cast<u8(*)[512]>(realPtr));
        break;
    }
    case EMT_2048: {
#ifdef APP_THREADSAFE_MEMORY_POOL
        ScopedLock lock(mMutexLarge);
#endif
        mBlockPoolLarge.release(reinterpret_cast<u8(*)[2048]>(realPtr));
        break;
    }
    case EMT_8192: {
#ifdef APP_THREADSAFE_MEMORY_POOL
        ScopedLock lock(mMutexXLarge);
#endif
        mBlockPoolXLarge.release(reinterpret_cast<u8(*)[8192]>(realPtr));
        break;
    }
    case EMT_10K: {
#ifdef APP_THREADSAFE_MEMORY_POOL
        ScopedLock lock(mMutexHuge);
#endif
        mBlockPoolHuge.release(reinterpret_cast<u8(*)[10240]>(realPtr));
        break;
    }
    case EMT_DEFAULT:
        ::free(realPtr);
        break;
    default:
        APP_ASSERT(false);
        break;
    }
}

void CMemoryHub::clear() {
#ifdef APP_THREADSAFE_MEMORY_POOL
    mBlockPoolSmall.clear();
    mBlockPoolMedium.clear();
    mBlockPoolLarge.clear();
    mBlockPoolXLarge.clear();
    mBlockPoolHuge.clear();
#endif // APP_THREADSAFE_MEMORY_POOL
}

