// Generates a space-separated string of pseudo-random words
std::string GenerateRandomWords(
    const size_t min_len,
    const size_t max_len,
    const std::string_view char_set,
    const size_t word_qty)
{
    std::string result;
    std::minstd_rand rng_engine;

    for(size_t idx = 0; idx < word_qty; ++idx)
    {
        // Determine word length within [min_len, max_len]
        const size_t word_length = (rng_engine() % (max_len - min_len + 1)) + min_len;

        // Append random characters from the provided set
        for(size_t pos = 0; pos < word_length; ++pos)
            result.push_back(char_set[rng_engine() % char_set.size()]);

        // Add space separator
        result.push_back(' ');
    }

    return result;
}
} // anonymous namespace

