// Compute bucket-stored encrypted ID from plaintext ID
::rlwe::StatusOr<std::string> ComputeBucketStoredEncryptedId(
    RlwePlaintextId id,
    const EncryptedBucketsParameters& params,
    private_join_and_compute::ECCommutativeCipher* cipher,
    private_join_and_compute::Context* context) {
  if (!cipher || !context) {
    return absl::InvalidArgumentError("Both ECCommutativeCipher and Context must be valid.");
  }

  std::string raw_id = rlwe::HashRlwePlaintextId(id);
  auto encryption_result = cipher->Encrypt(raw_id);
  if (!encryption_result.ok()) {
    return absl::InvalidArgumentError(encryption_result.status().message());
  }

  std::string encrypted_payload = std::move(encryption_result).value();
  return ComputeBucketStoredEncryptedId(encrypted_payload, params, context);
}

// Compute bucket-stored encrypted ID from already encrypted ID
::rlwe::StatusOr<std::string> ComputeBucketStoredEncryptedId(
    const std::string& encrypted_id,
    const EncryptedBucketsParameters& params,
    private_join_and_compute::Context* context) {
  if (!context) {
    return absl::InvalidArgumentError("Context must be non-null.");
  }

  std::string hashed_encrypted = HashEncryptedId(encrypted_id, context);

  // Determine starting byte index for bucket ID extraction
  int offset_byte = (params.encrypted_bucket_id_length() / 8) + 
                    (params.encrypted_bucket_id_length() % 8 != 0 ? 1 : 0);

  // Compute how many bytes to retain after bucket ID
  int required_bytes = kStoredEncryptedIdByteLength - (params.encrypted_bucket_id_length() / 8);
  if (required_bytes < 0) {
    required_bytes = 0;
  }

  std::string extracted(hashed_encrypted.begin() + offset_byte,
                        hashed_encrypted.begin() + offset_byte + required_bytes);
  return extracted;
}

// Hash RLWE plaintext ID into canonical string representation
std::string HashRlwePlaintextId(const RlwePlaintextId& id) {
  // Legacy path: empty non-sensitive ID → no delimiter needed
  if (id.non_sensitive_id().empty()) {
    return absl::StrCat(0, id.sensitive_id().size(), id.sensitive_id());
  }

  static constexpr char separator[] = "/";
  // Ensure injectivity using explicit length prefixes and delimiters
  return absl::StrCat(id.non_sensitive_id().size(), separator,
                      id.non_sensitive_id(), separator,
                      id.sensitive_id().size(), separator,
                      id.sensitive_id());
}

// Hash non-sensitive ID with salted SHA256
::rlwe::StatusOr<std::string> HashNonsensitiveIdWithSalt(
    absl::string_view nsid,
    HashType hash_algo,
    private_join_and_compute::Context* ctx) {
  switch (hash_algo) {
    case HashType::TEST_HASH_TYPE:
    case HashType::SHA256: {
      if (!ctx) {
        return absl::InvalidArgumentError("Context pointer cannot be null.");
      }

      // Fixed salt to prevent precomputation attacks via rainbow tables
      static constexpr unsigned char salt_bytes[] = {
          0xD6, 0x50, 0x82, 0x81, 0x82, 0xD9, 0x99, 0x11,
          0x61, 0xE6, 0x7D, 0xB2, 0x91, 0x72, 0xE4, 0x05,
          0x3E, 0x4A, 0xE8, 0x54, 0x0D, 0xFF, 0xB7, 0x8F,
          0x61, 0x08, 0x0D, 0x96, 0x4D, 0x8F, 0x58, 0xFE};

      std::string input = absl::StrCat(std::string(salt_bytes, sizeof(salt_bytes)), nsid);
      return ctx->Sha256String(input);
    }
    default:
      return absl::InvalidArgumentError("Unsupported hashing algorithm specified.");
  }
}

