// Helper to convert vs_array<T> to Python list recursively
template<typename T>
static PyObject* array_to_pylist(const vs_array<T>& arr) {
    PyObject* outer_list = PyList_New(arr.n_rows());
    for (size_t i = 0; i < static_cast<size_t>(arr.n_rows()); ++i) {
        if constexpr (std::is_same_v<T, uint8_t>) {
            // For 2D point-like arrays (e.g., BBOX/EVENTS)
            PyObject* vec = Py_BuildValue("(ii)", arr(i, 0), arr(i, 1));
            PyList_SET_ITEM(outer_list, i, vec);
        } else {
            // For matrix-like arrays (INT8/INT16/INT32/FLOAT)
            PyObject* row = PyList_New(arr.n_cols());
            for (size_t j = 0; j < static_cast<size_t>(arr.n_cols()); ++j) {
                PyObject* elem = std::is_floating_point_v<T>
                    ? PyFloat_FromDouble(static_cast<double>(arr(i, j)))
                    : PyLong_FromLong(static_cast<long>(arr(i, j)));
                PyList_SET_ITEM(row, j, elem);
            }
            PyList_SET_ITEM(outer_list, i, row);
        }
    }
    return outer_list;
}

// Internal handler registry type
using packet_handler = std::function<void()>;

class py_decoder_adapter : public vs_packet_decoder {
public:
    py_decoder_adapter();
    PyObject* last_result = nullptr;

private:
    void setup_handlers();

    // Handler storage: maps internal enum-like types to handlers
    std::unique_ptr<packet_handler[]> handlers;
    size_t handler_count = 0;
};

py_decoder_adapter::py_decoder_adapter()
    : handlers(std::make_unique<packet_handler[]>(12)), handler_count(12) {
    setup_handlers();
}

