    // REQUEST_FILE handler
    handlers[idx++] = [this]() {
        const char* path = get_request_filepath();
        int32_t chunk = get_request_chunk_size();
        last_result = Py_BuildValue("{ss,si,ss,si,si, ss,ss,si}",
            "type", "data",
            "size", static_cast<int>(get_packet_header()->payload_size),
            "datatype", "REQUEST",
            "loopcounter", static_cast<int>(get_loop_counter()),
            "channel", static_cast<int>(get_data_channel()),
            "filetype", "FILE",
            "filepath", path,
            "chunksize", static_cast<int>(chunk)
        );
    };
}

// Global decode function (same interface as original)
PyObject* decode_packet(uint8_t* packet_buffer, size_t packet_size) {
    static py_decoder_adapter decoder;
    static uint32_t counter = 0;

    auto status = decoder.decode_packet(packet_buffer, packet_size, counter++);
    if (status == vs_packet_decoder::done) {
        return decoder.last_result;
    } else {
        auto header = reinterpret_cast<vs_packet_header_t*>(packet_buffer);
        int payload_len = header->payload_size;
        uint8_t* payload = packet_buffer + sizeof(vs_packet_header_t);

        return Py_BuildValue("{ss,si,sy#}",
            "type", "unknown",
            "size", payload_len,
            "payload", payload, static_cast<size_t>(payload_len)
        );
    }
}

