// Internal state management for downloader
static network::Downloader* _downloaderInstance = nullptr;
static std::function<void(const downloader::FileTask&)> _dispatcherCallback = nullptr;
static std::vector<downloader::FileTask> _pendingTasks;
static std::unordered_map<std::string, int64_t> _expectedSizeMap;
static std::mutex _taskMutex;
static std::thread* _workerThread = nullptr;
static std::condition_variable _taskSignal;
static bool _shutdownRequested = false;

// Cleanup resources safely
void downloader::end() {
    if (_downloaderInstance) {
        _shutdownRequested = true;
        _taskSignal.notify_one();

        if (_workerThread && _workerThread->joinable()) {
            _workerThread->join();
        }

        delete _workerThread;
        delete _downloaderInstance;

        _workerThread = nullptr;
        _downloaderInstance = nullptr;
        _shutdownRequested = false;
    }
}

// Initialize downloader with background worker
void downloader::init() {
    if (_downloaderInstance) return;

    _workerThread = new std::thread(&downloader::_processQueue);

    DownloaderHints config = {6, 10, ".tmp"};
    _downloaderInstance = new Downloader(config);

    // Handle download errors
    _downloaderInstance->onTaskError = [](const DownloadTask& task, int errCode, int internalErr, const std::string& msg) {
        FileTask result;
        result.md5 = task.identifier;
        result.url = task.requestURL;
        result.path = task.storagePath;
        result.state = FileState::IOERROR;

        std::lock_guard<std::mutex> guard(_taskMutex);
        _pendingTasks.emplace_back(result);
        _taskSignal.notify_one();
    };

    // On successful download, validate size and enqueue for verification
    _downloaderInstance->onFileTaskSuccess = [](const DownloadTask& task) {
        FileTask result;
        result.md5 = task.identifier;
        result.url = task.requestURL;
        result.path = task.storagePath;
        result.state = FileState::PENDING;

        auto it = _expectedSizeMap.find(task.requestURL);
        int64_t expectedSize = (it != _expectedSizeMap.end()) ? it->second : 0;
        _expectedSizeMap.erase(it);

        if (FileUtils::getInstance()->getFileSize(result.path) != expectedSize || expectedSize == 0) {
            result.state = FileState::IOERROR;
        }

        std::lock_guard<std::mutex> guard(_taskMutex);
        _pendingTasks.emplace_back(result);
        _taskSignal.notify_one();
    };

    // Track expected file sizes during download
    _downloaderInstance->onTaskProgress = [](const DownloadTask& task, int64_t, int64_t, int64_t totalExpected) {
        _expectedSizeMap[task.requestURL] = totalExpected;
    };
}

// Set callback to dispatch completed tasks
void downloader::setDispatcher(const std::function<void(const FileTask&)>& cb) {
    _dispatcherCallback = cb;
}

// Verify integrity using MD5
static bool _checkIntegrity(const downloader::FileTask& task) {
    unsigned char hashBuffer[MD5_STR_LEN];
    if (!md5f(hashBuffer, task.path.c_str())) return false;
    return strcaseequal(reinterpret_cast<const char*>(hashBuffer), task.md5.c_str());
}

// Enqueue a new download request
void downloader::load(const FileTask& task) {
    std::string dirPath = task.path;
    size_t lastSlash = dirPath.rfind('/');
    if (lastSlash != std::string::npos) {
        dirPath = dirPath.substr(0, lastSlash);
    }

    filesystem::createDirectory(dirPath);
    filesystem::remove(task.path + ".tmp");

    _expectedSizeMap[task.url] = 0;
    _downloaderInstance->createDownloadFileTask(task.url, task.path, task.md5);
}

// Worker loop: process pending tasks
void downloader::_processQueue() {
    while (!_shutdownRequested) {
        FileTask currentTask;

        {
            std::unique_lock<std::mutex> lock(_taskMutex);
            if (_pendingTasks.empty()) {
                _taskSignal.wait(lock);
                continue;
            }
            currentTask = _pendingTasks.back();
            _pendingTasks.pop_back();
        }

        // Post-process based on state
        if (currentTask.state == FileState::PENDING) {
            if (!currentTask.md5.empty()) {
                currentTask.state = _checkIntegrity(currentTask) ? FileState::LOADED : FileState::INVALID;
            } else {
                currentTask.state = FileState::LOADED;
            }
        }

        // Clean up partial or failed files
        if (currentTask.state != FileState::LOADED && filesystem::exist(currentTask.path)) {
            filesystem::remove(currentTask.path);
        }

        // Dispatch result back to main thread
        Director::getInstance()->getScheduler()->performFunctionInCocosThread([=]() {
            if (_dispatcherCallback) {
                _dispatcherCallback(currentTask);
            }
        });
    }
}

NS_XGAME_END

#include "LexTokenStream.hpp"
#include "antlr/CommonToken.hpp"

extern "C" {
    extern char* yytext;
    extern int yylex();
    extern int yyrestart(std::FILE*);
}

static LexTokenStream* activeLexer = nullptr;

extern "C"
void newLine() {
    if (activeLexer != nullptr) {
        activeLexer->incrementLine();
    }
}

LexTokenStream::LexTokenStream(std::FILE* fp) {
    yyrestart(fp);
    endOfFileReached = false;
    currentLineNumber = 1;
}

void LexTokenStream::incrementLine() {
    ++currentLineNumber;
}

ANTLR_USE_NAMESPACE(antlr)RefToken LexTokenStream::nextToken() {
    ANTLR_USE_NAMESPACE(antlr)RefToken token;

    if (!endOfFileReached) {
        int tokenType;
        activeLexer = this;

        // Keep scanning until we get a valid token (not -1/SKIP)
        do {
            tokenType = yylex();
        } while (tokenType == -1);

        if (tokenType != 0) {
            token = ANTLR_USE_NAMESPACE(antlr)RefToken(
                new ANTLR_USE_NAMESPACE(antlr)CommonToken(tokenType, yytext)
            );
        } else {
            endOfFileReached = true;
        }
    }

    // If EOF was reached (either just now or previously), emit EOF token
    if (endOfFileReached) {
        token = ANTLR_USE_NAMESPACE(antlr)RefToken(
            new ANTLR_USE_NAMESPACE(antlr)CommonToken(1, "EOF")
        );
    }

    token->setLine(currentLineNumber);
    return token;
}

#include "user_console_ui.h"
#include "exceptions.h"

// Constants for external commands
static const char BROWSER_LAUNCHER[] = "/usr/bin/firefox --new-window ";
static const char WINDOW_CLOSER[] = "wmctrl -ic \"$(wmctrl -l | grep 'Mozilla Firefox' | tail -1 | awk '{ print $1 }')\"";

UserConsoleUI::UserConsoleUI(std::shared_ptr<Repository<Trenchcoat>> repo,
                             std::shared_ptr<Repository<Trenchcoat>> cartRepo)
    : service(repo, cartRepo) {}

void UserConsoleUI::seeCoats() {
    std::string selectedSize;
    bool sizeValid = false;

    // Prompt until valid size is entered
    do {
        if (!sizeValid && !selectedSize.empty()) {
            this->displayError("Invalid size. Please enter a correct one.\n");
        }
        selectedSize = this->getString("Size: ");
        sizeValid = true;
        try {
            Validator<Trenchcoat>::validSize(selectedSize);
        } catch (const InvalidTrenchcoatSize&) {
            sizeValid = false;
        }
    } while (!sizeValid || selectedSize.empty());

    std::vector<Trenchcoat> availableCoats = this->service.getCoats(selectedSize);
    if (availableCoats.empty()) {
        this->displayError("No coats found in this size. Sorry.");
        return;
    }

    int coatIndex = 0;
    bool inputAccepted = true;

    // Loop through coats interactively
    while (true) {
        Trenchcoat currentCoat = availableCoats[coatIndex];

        // Cycle through coats using modulo arithmetic
        if (inputAccepted) {
            coatIndex = (coatIndex + 1) % static_cast<int>(availableCoats.size());
        }
        inputAccepted = true;

        // Launch browser to show photo
        std::string launchCmd = std::string(BROWSER_LAUNCHER) + " \"" + currentCoat.photoLink() + "\"";
        system(launchCmd.c_str());

        // Display coat details
        this->displayEntity<Trenchcoat>(currentCoat);

        // Get user choice
        std::string action = this->getString(
            "Buy (" + std::string(1, BUY_KEY) +
                "), Skip (" + std::string(1, SKIP_KEY) +
                ") or Menu (" + std::string(1, MENU_KEY) +
                "): "
        );

        // Close browser window after interaction
        system(WINDOW_CLOSER);

        // Normalize input: truncate multi-character strings to first char only
        if (action.length() > 1) {
            action[0] = '\0';
        }

        switch (action[0]) {
            case BUY_KEY:
                this->service.buyCoat(currentCoat);
                this->displayMessage("Total cost so far: $" +
                        std::to_string(this->service.getShoppingCartPrice()));
                break;

            case SKIP_KEY:
                // Do nothing; proceed to next coat
                break;

            case MENU_KEY:
                return; // Exit function to return to main menu

            default:
                this->displayError("Unknown option. Try again.\n");
                inputAccepted = false;
                break;
        }

        this->displayMessage("");
    }
}

void UserConsoleUI::showCart() {
    auto cartItems = this->service.getShoppingCart();
    this->displayEntityVector<Trenchcoat>(cartItems);
    this->displayMessage("Cart total: $" +
        std::to_string(this->service.getShoppingCartPrice()));
}

void UserConsoleUI::seeCoatsFile() {
    std::string cmd = this->service.getDisplayFileCommand();
    system(cmd.c_str());
}

void UserConsoleUI::exit() {
    this->displayMessage("Exiting...");
}

void UserConsoleUI::displayMenu() {
    this->displayMessage(
        "\n+++++++++++++ USER MODE +++++++++++++\n" +
        std::string(1, LIST_KEY) + ". View available coats.\n" +
        std::string(1, BASKET_KEY) + ". View your shopping basket.\n" +
        std::string(1, FILE_LIST_KEY) + ". Show coats from file.\n" +
        std::string(1, EXIT_KEY) + ". Quit application.\n"
    );
}

void UserConsoleUI::run() {
    while (true) {
        this->displayMenu();
        std::string userInput = this->getString("Your selection: ");

        // Truncate long inputs to single character
        if (userInput.length() > 1) {
            userInput[0] = '\0';
        }

        switch (userInput[0]) {
            case LIST_KEY:
                this->seeCoats();
                break;

            case BASKET_KEY:
                this->showCart();
                break;

            case FILE_LIST_KEY:
                this->seeCoatsFile();
                break;

            case EXIT_KEY:
                this->exit();
                return;

            default:
                this->displayError("Invalid command. Please try again.\n");
                break;
        }
    }
}

