/////////////////////////////////////////////////////////////////////////////
void CMySplitWnd::RecalcLayout()
{
    ASSERT_VALID(this);
    ASSERT(m_nRows > 0 && m_nCols > 0); // At least one pane required

    CRect rcClient;
    GetClientRect(rcClient);
    rcClient.InflateRect(-m_cxBorder, -m_cyBorder);

    CRect rcInner;
    GetInsideRect(rcInner);

    // Compute column widths and row heights
    AllocateRowOrColumnSizes(m_pColInfo, m_nCols, rcInner.Width(), m_cxSplitterGap);
    AllocateRowOrColumnSizes(m_pRowInfo, m_nRows, rcInner.Height(), m_cySplitterGap);

    // Prepare batch window positioning
    AFX_SIZEPARENTPARAMS layoutParams;
    layoutParams.hDWP = ::BeginDeferWindowPos((m_nCols + 1) * (m_nRows + 1) + 1);

    // Determine scrollbar sizes
    int sbWidth = rcClient.right - rcInner.right;
    int sbHeight = rcClient.bottom - rcInner.bottom;

    // Handle size box (bottom-right corner grip)
    if (m_bHasHScroll && m_bHasVScroll)
    {
        CWnd* pGrip = GetDlgItem(AFX_IDW_SIZE_BOX);
        ASSERT(pGrip != nullptr);

        bool bUsingSizingParent = (GetSizingParent() != nullptr);
        bool bStyleChanged = pGrip->ModifyStyle(SBS_SIZEGRIP | SBS_SIZEBOX,
            bUsingSizingParent ? SBS_SIZEGRIP : SBS_SIZEBOX);
        if (bStyleChanged)
            pGrip->Invalidate();
        pGrip->EnableWindow(bUsingSizingParent);

        RepositionChildWindow(&layoutParams, pGrip,
            rcInner.right, rcInner.bottom, sbWidth, sbHeight, TRUE);
    }

    // Horizontal scrollbars
    if (m_bHasHScroll)
    {
        int splitterBoxWidth = m_cxSplitter;
        int xPos = rcClient.left;
        int yPos = rcInner.bottom;

        for (int colIdx = 0; colIdx < m_nCols; ++colIdx)
        {
            CWnd* pSB = GetDlgItem(AFX_IDW_HSCROLL_FIRST + colIdx);
            ASSERT(pSB != nullptr);

            int colWidth = m_pColInfo[colIdx].nCurSize;
            if (colIdx == 0 && m_nCols < m_nMaxCols)
            {
                xPos += splitterBoxWidth;
                colWidth -= splitterBoxWidth;
            }

            RepositionChildWindow(&layoutParams, pSB,
                xPos, yPos, colWidth, sbHeight, TRUE);
            xPos += colWidth + m_cxSplitterGap;
        }
    }

    // Vertical scrollbars
    if (m_bHasVScroll)
    {
        int splitterBoxHeight = m_cySplitter;
        int xPos = rcInner.right;
        int yPos = rcClient.top;

        for (int rowIdx = 0; rowIdx < m_nRows; ++rowIdx)
        {
            CWnd* pSB = GetDlgItem(AFX_IDW_VSCROLL_FIRST + rowIdx);
            ASSERT(pSB != nullptr);

            int rowHeight = m_pRowInfo[rowIdx].nCurSize;
            if (rowIdx == 0 && m_nRows < m_nMaxRows)
            {
                yPos += splitterBoxHeight;
                rowHeight -= splitterBoxHeight;
            }

            RepositionChildWindow(&layoutParams, pSB,
                xPos, yPos, sbWidth, rowHeight, TRUE);
            yPos += rowHeight + m_cySplitterGap;
        }
    }

    // Position all panes
    int xBase = rcClient.left;
    for (int col = 0; col < m_nCols; ++col)
    {
        int w = m_pColInfo[col].nCurSize;
        int yBase = rcClient.top;
        for (int row = 0; row < m_nRows; ++row)
        {
            int h = m_pRowInfo[row].nCurSize;
            CWnd* pPane = GetPane(row, col);
            RepositionChildWindow(&layoutParams, pPane,
                xBase, yBase, w, h, FALSE);
            yBase += h + m_cySplitterGap;
        }
        xBase += w + m_cxSplitterGap;
    }

    // Commit all changes at once
    if (!layoutParams.hDWP || !::EndDeferWindowPos(layoutParams.hDWP))
    {
        TRACE0("Warning: DeferWindowPos failed — insufficient system resources.\n");
    }
}

/////////////////////////////////////////////////////////////////////////////
void CMySplitWnd::TrackRowSize(int y, int rowIndex)
{
    ASSERT_VALID(this);
    ASSERT(m_nRows > 1);

    CPoint pt(0, y);
    ClientToScreen(&pt);
    GetPane(rowIndex + 1, 0)->ScreenToClient(&pt);

    m_pRowInfo[rowIndex + 1].nIdealSize = m_pRowInfo[rowIndex + 1].nCurSize - pt.y;
}

void CMySplitWnd::TrackColumnSize(int x, int colIndex)
{
    ASSERT_VALID(this);
    ASSERT(m_nCols > 1);

    CPoint pt(x, 0);
    ClientToScreen(&pt);
    GetPane(0, colIndex + 1)->ScreenToClient(&pt);

    m_pColInfo[colIndex + 1].nIdealSize = m_pColInfo[colIndex + 1].nCurSize - pt.x;
}

/////////////////////////////////////////////////////////////////////////////
// Generic layout routine: allocates space from rightmost to leftmost
// (opposite of default MFC behavior)
static void AllocateRowOrColumnSizes(CSplitterWndEx::CRowColInfo* pEntries,
    int nCount, int nAvailable, int nGap)
{
    ASSERT(pEntries != nullptr);
    ASSERT(nCount > 0);
    ASSERT(nGap > 0);

    if (nAvailable < 0)
        nAvailable = 0;

    // Initialize ideal sizes (skip last entry for now)
    for (int i = 0; i < nCount - 1; ++i)
    {
        auto& entry = pEntries[nCount - 2 - i];
        if (entry.nIdealSize < entry.nMinSize)
            entry.nIdealSize = 0;
        entry.nCurSize = entry.nIdealSize;
    }

    // Last entry gets remaining space
    pEntries[0].nCurSize = INT_MAX;

    // Now adjust actual sizes based on available space
    for (int idx = 0; idx < nCount; ++idx)
    {
        auto& current = pEntries[nCount - 1 - idx];

        if (nAvailable <= 0)
        {
            current.nCurSize = 0;
            continue;
        }

        if (nAvailable < current.nMinSize && idx != 0)
        {
            // Not enough room — collapse this pane
            current.nCurSize = 0;
            // Add leftover to previous pane
            auto& prev = pEntries[nCount - idx];
            prev.nCurSize += nAvailable + afxData.cxBorder2;
            nAvailable = 0;
        }
        else
        {
            if (current.nCurSize == 0)
            {
                if (idx != 0)
                    current.nCurSize = 0;
            }
            else if (nAvailable < current.nCurSize)
            {
                current.nCurSize = nAvailable;
                nAvailable = 0;
            }
            else
            {
                nAvailable -= current.nCurSize;
            }
        }

        // Reserve space for splitter if not last item
        if (idx != nCount - 1)
        {
            if (nAvailable > nGap)
            {
                nAvailable -= nGap;
                ASSERT(nAvailable >= 0);
            }
            else
            {
                current.nCurSize += nAvailable;
                if (current.nCurSize > (nGap - afxData.cyBorder2))
                    current.nCurSize -= (nGap - afxData.cyBorder2);
                nAvailable = 0;
            }
        }
    }

    ASSERT(nAvailable == 0);
}

/////////////////////////////////////////////////////////////////////////////
// Positions a child window with optional border adjustment
static void RepositionChildWindow(AFX_SIZEPARENTPARAMS* pLayout,
    CWnd* pTarget, int nX, int nY, int nW, int nH, BOOL bIsScroll)
{
    ASSERT(pTarget != nullptr);
    ASSERT(pTarget->m_hWnd != nullptr);

    if (bIsScroll)
    {
        bool needsBorder = (nW <= AFX_CX_BORDER || nH <= AFX_CY_BORDER);
        pTarget->ModifyStyle(needsBorder ? 0 : WS_BORDER,
            needsBorder ? WS_BORDER : 0);
    }

    CRect rcNew(nX, nY, nX + nW, nY + nH);

    // Account for 3D borders (especially for splitter children)
    if ((pTarget->GetExStyle() & WS_EX_CLIENTEDGE) ||
        pTarget->IsKindOf(RUNTIME_CLASS(CSplitterWndEx)))
    {
        rcNew.InflateRect(afxData.cxBorder2, afxData.cyBorder2);
    }

    // Avoid redundant moves
    CRect rcOld;
    pTarget->GetWindowRect(rcOld);
    pTarget->GetParent()->ScreenToClient(rcOld);
    if (rcNew != rcOld)
        AfxRepositionWindow(pLayout, pTarget->m_hWnd, rcNew);
}

