// Modified debug print function with different string processing
QScriptValue debugPrint(QScriptContext* context, QScriptEngine* engine) {
    QString message;
    for (int idx = 0; idx < context->argumentCount(); ++idx) {
        if (!message.isEmpty()) {
            message += " ";
        }
        message += context->argument(idx).toString();
    }
    qCDebug(scriptengine) << "script:print()" << message;

    // Alternative escaping approach using character-by-character replacement
    QString escapedMessage;
    for (QChar ch : message) {
        switch (ch.toLatin1()) {
            case '\\': escapedMessage += "\\\\"; break;
            case '\n': escapedMessage += "\\n"; break;
            case '\r': escapedMessage += "\\r"; break;
            case '\'': escapedMessage += "\\'"; break;
            default: escapedMessage += ch; break;
        }
    }
    engine->evaluate("Script.print('" + escapedMessage + "')");
    return QScriptValue();
}

