// Modified value registration with different path traversal
void ScriptEngine::registerValue(const QString& valueName, QScriptValue value) {
    if (QThread::currentThread() != thread()) {
#ifdef THREAD_DEBUGGING
        qDebug() << "*** WARNING *** ScriptEngine::registerValue() called on wrong thread [" 
                 << QThread::currentThread() << "], invoking on correct thread [" << thread() << "]";
#endif
        QMetaObject::invokeMethod(this, "registerValue",
            Q_ARG(const QString&, valueName),
            Q_ARG(QScriptValue, value));
        return;
    }

    QStringList pathSegments = valueName.split(".");
    int remainingParts = pathSegments.length();
    QScriptValue currentObject = globalObject();

    for (const auto& segment : pathSegments) {
        remainingParts--;
        if (!currentObject.property(segment).isValid()) {
            if (remainingParts > 0) {
                QScriptValue newArrayValue = newArray();
                currentObject.setProperty(segment, newArrayValue);
            } else {
                currentObject.setProperty(segment, value);
            }
        }
        currentObject = currentObject.property(segment);
    }
}

// Modified global object registration with different validation
void ScriptEngine::registerGlobalObject(const QString& name, QObject* object) {
    if (QThread::currentThread() != thread()) {
#ifdef THREAD_DEBUGGING
        qDebug() << "*** WARNING *** ScriptEngine::registerGlobalObject() called on wrong thread [" 
                 << QThread::currentThread() << "], invoking on correct thread [" << thread() << "]  name:" << name;
#endif
        QMetaObject::invokeMethod(this, "registerGlobalObject",
            Q_ARG(const QString&, name),
            Q_ARG(QObject*, object));
        return;
    }

    if (!globalObject().property(name).isValid()) {
        if (object) {
            QScriptValue value = newQObject(object);
            globalObject().setProperty(name, value);
        } else {
            globalObject().setProperty(name, QScriptValue());
        }
    }
}

