enum class seat_state : char
{
    floor = '.',
    empty = 'L',
    occupied = '#'
};

using seating_grid = std::vector<std::vector<seat_state>>;

auto operator<<(std::ostream& os, const seating_grid& grid) -> std::ostream&
{
    for(size_t row = 0; row < grid.size(); ++row)
    {
        for(size_t col = 0; col < grid[row].size(); ++col)
        {
            os << static_cast<char>(grid[row][col]);
        }
        os << "\n";
    }
    return os;
}

auto count_occupied(const seating_grid& grid) -> size_t
{
    size_t total{0};
    for(const auto& row : grid)
    {
        for(const auto& cell : row)
        {
            if(cell == seat_state::occupied)
            {
                ++total;
            }
        }
    }
    return total;
}

// Directions: all 8 compass directions (including diagonals)
static std::array<std::pair<int64_t, int64_t>, 8> directions = {
    std::pair{-1, -1},   std::pair{0, -1},    std::pair{1, -1},
    std::pair{-1, 0},                         std::pair{1, 0},
    std::pair{-1, 1},    std::pair{0, 1},     std::pair{1, 1}
};

// Apply one iteration of the seating rules
static auto evolve(const seating_grid& current_layout) -> seating_grid
{
    seating_grid next_layout = current_layout;
    const auto rows = current_layout.size();
    const auto cols = current_layout[0].size();

    for(size_t r = 0; r < rows; ++r)
    {
        for(size_t c = 0; c < cols; ++c)
        {
            const auto state = current_layout[r][c];
            if(state == seat_state::floor)
            {
                continue;
            }

            size_t visible_occupied{0};

            // Look in each direction until we find a seat or go out of bounds
            for(const auto& [dr, dc] : directions)
            {
                int64_t i = static_cast<int64_t>(r);
                int64_t j = static_cast<int64_t>(c);
                bool found_seat = false;

                while(!found_seat && i >= 0 && i < static_cast<int64_t>(rows) &&
                      j >= 0 && j < static_cast<int64_t>(cols))
                {
                    i += dr;
                    j += dc;

                    if(i < 0 || i >= static_cast<int64_t>(rows) ||
                       j < 0 || j >= static_cast<int64_t>(cols))
                    {
                        break;
                    }

                    switch(current_layout[i][j])
                    {
                        case seat_state::floor:
                            // Continue looking in this direction
                            break;
                        case seat_state::empty:
                            found_seat = true;
                            break;
                        case seat_state::occupied:
                            found_seat = true;
                            ++visible_occupied;
                            break;
                    }
                }
            }

            // Apply rules based on current state
            switch(state)
            {
                case seat_state::empty:
                    if(visible_occupied == 0)
                    {
                        next_layout[r][c] = seat_state::occupied;
                    }
                    break;
                case seat_state::occupied:
                    if(visible_occupied >= 5)
                    {
                        next_layout[r][c] = seat_state::empty;
                    }
                    break;
            }
        }
    }

    return next_layout;
}

int main(int argc, char* argv[])
{
    std::vector<std::string> arguments{argv, argv + argc};
    if(arguments.size() != 2)
    {
        std::cout << arguments[0] << " <input_file>" << std::endl;
        return 0;
    }

    auto file_content = file::read(arguments[1]);
    auto lines = chain::str::split(file_content, '\n');

    // Parse input into grid of seat states
    seating_grid layout{};
    for(const auto& line : lines)
    {
        auto& row = layout.emplace_back();
        for(const auto& ch : line)
        {
            switch(ch)
            {
                case '.':
                    row.push_back(seat_state::floor);
                    break;
                case 'L':
                    row.push_back(seat_state::empty);
                    break;
                case '#':
                    row.push_back(seat_state::occupied);
                    break;
            }
        }
    }

    // Iterate until stable configuration is reached
    seating_grid previous_layout{};
    do
    {
        std::cout << layout << "\n\n";
        previous_layout = layout;
        layout = evolve(layout);
    } while(previous_layout != layout);

    std::cout << "final occupied seats = " << count_occupied(layout) << "\n";
    return 0;
}

