Live_pass_pack::Live_pass_pack(int argc, const char **argv) {
  Options::setup(argc, argv);

  auto& desc = *Options::get_desc();
  desc.add_options()
    ("original_lgdb,o", boost::program_options::value(&orig_lgdb_path)->required(), "lgdb path of the original netlist")
    ("modified_lgdb,m", boost::program_options::value(&mod_lgdb_path)->required(), "lgdb path of the modified netlist")
    ("synth_lgdb,s",  boost::program_options::value(&synth_lgdb_path)->required(), "lgdb path of the synthesized netlist")
    ("delta_lgdb,d",  boost::program_options::value(&delta_lgdb_path), "lgdb path for the generated delta lgraph (default olgdb)")
    ("boundaries,b",  boost::program_options::value(&inv_boundaries_file)->required(), "invariant boundaries files generated by lginvariant")
    ("diff,f",        boost::program_options::value(&diff_output_file), "file containing different boundaries (default=diff)")
    ("help,h",        "print usage message");

  boost::program_options::variables_map parsed_vm;
  boost::program_options::store(
    boost::program_options::command_line_parser(
      Options::get_cargc(), Options::get_cargv()
    ).options(desc).allow_unregistered().run(),
    parsed_vm
  );

  if (parsed_vm.count("help")) {
    return;
  }

  // Assign values with validation and defaults
  orig_lgdb_path = parsed_vm.count("original_lgdb") 
    ? parsed_vm["original_lgdb"].as<std::string>() 
    : (console->error("original_lgdb is required\n"), exit(-1), std::string{});

  mod_lgdb_path = parsed_vm.count("modified_lgdb")
    ? parsed_vm["modified_lgdb"].as<std::string>()
    : (console->error("modified_lgdb is required\n"), exit(-1), std::string{});

  synth_lgdb_path = parsed_vm.count("synth_lgdb")
    ? parsed_vm["synth_lgdb"].as<std::string>()
    : (console->error("synth_lgdb is required\n"), exit(-1), std::string{});

  delta_lgdb_path = parsed_vm.count("delta_lgdb")
    ? parsed_vm["delta_lgdb"].as<std::string>()
    : "olgdb";

  inv_boundaries_file = parsed_vm.count("boundaries")
    ? parsed_vm["boundaries"].as<std::string>()
    : (console->error("boundaries is required\n"), exit(-1), std::string{});

  diff_output_file = parsed_vm.count("diff")
    ? parsed_vm["diff"].as<std::string>()
    : "diff";

  Options::setup_lock();
}

