namespace diy
{
    struct Master::IExchangeInfoDUD: public IExchangeInfo
    {
        struct TransferRecord
        {
            std::array<int, 2>   payload;
            mpi::request        pending_op;
        };

        using IExchangeInfo::IExchangeInfo;

        inline bool       is_complete() override;                             // determine if all processes have finished
        inline void       increment_work(int amount) override;                // increase global work counter by specified amount
        inline void       manage_communication() override;
        inline void       propagate_subtree_change(int delta);
        inline bool       handle_work_update();
        inline void       verify_no_abort();
        inline void       terminate(int round);
        inline void       handle_completion(int sender, int round);
        inline void       clear_child_acknowledgments();

        int               get_lowest_set_bit(int val) const                     { return ((val ^ (val-1)) + 1) >> 1; }

        void              transmit(int dest_rank, int msg_type, int value)
        {
            pending_transfers.emplace_back();
            TransferRecord& record = pending_transfers.back();
            record.payload[0] = msg_type;
            record.payload[1] = value;
            record.pending_op = comm.issend(dest_rank, tags::iexchange, record.payload);
            log->trace("[{}] Dispatching to {}, type = {}, value = {}", comm.rank(), dest_rank, msg_type, value);
        }

        void              receive(int source_rank, int& msg_type, int& value)
        {
            std::array<int, 2> buffer;
            comm.recv(source_rank, tags::iexchange, buffer);
            msg_type = buffer[0];
            value = buffer[1];
            log->trace("[{}] Acquired from {}, type = {}, value = {}, data = {}", comm.rank(), source_rank, msg_type, value);
        }

        inline bool       advance();
        int               get_parent_rank() const                               { return comm.rank() & (comm.rank() - 1); }
        inline void       notify_descendants(int signal, int value);
        bool              has_pending_activity() const                          { return subtree_load > 0 || !pending_transfers.empty(); }
        bool              outdated() const                                      { return subtree_load != last_subtree_report || local_load != last_local_report; }

        enum class MessageType : int {
            load_adjustment = 0,
            termination_signal,
            abort_command
        };

        std::unordered_map<int, bool> completion_status;                        // gid -> done status
        int                           local_load = 0, last_local_report = 0;
        int                           subtree_load = 0, last_subtree_report = 0;
        int                           phase_counter = 0;
        std::list<TransferRecord>     pending_transfers;
        int                           current_round = -1;
        int                           child_responses = -1;

        // debugging aid
        bool                            initial_phase = true;
        using IExchangeInfo::prof;
    };
}

// Determine if all processes have completed execution
bool
diy::Master::IExchangeInfoDUD::
is_complete()
{
    if (phase_counter == 3)
        while (!pending_transfers.empty()) advance();     // ensure all messages are delivered before concluding

    return phase_counter == 3;
}

// Increase global work counter by specified amount
void
diy::Master::IExchangeInfoDUD::
increment_work(int amount)
{
    int previous_local_load = local_load;
    local_load += amount;
    assert(local_load >= 0);

    log->trace("[{}] Work adjustment: increment = {}, local_load = {}, previous_local_load = {}", 
               comm.rank(), amount, local_load, previous_local_load);

    if ((previous_local_load == 0) != (local_load == 0))     // zero-crossing detected
    {
        int delta = (local_load - last_local_report);
        propagate_subtree_change(delta);
        last_local_report = local_load;
    }
}

void
diy::Master::IExchangeInfoDUD::
propagate_subtree_change(int delta)
{
    int prior_subtree_load = subtree_load;
    subtree_load += delta;

    log->debug("[{}] Subtree adjustment: delta = {}, subtree_load = {}", 
               comm.rank(), delta, subtree_load);

    assert(subtree_load >= 0);

    if ((prior_subtree_load == 0) != (subtree_load == 0))     // zero-crossing in subtree
    {
        if (comm.rank() != 0)
        {
            int subtree_delta = (subtree_load - last_subtree_report);
            log->debug("[{}] Propagating subtree update: delta = {}, subtree_delta = {}", 
                       comm.rank(), delta, subtree_delta);

            transmit(get_parent_rank(), static_cast<int>(MessageType::load_adjustment), subtree_delta);
            last_subtree_report = subtree_load;

            if (phase_counter == 1)
                terminate(current_round);
            else if (phase_counter == 2)
                log->warn("[{}] Queueing work update after completion, delta = {}", 
                         comm.rank(), subtree_delta);
            else if (phase_counter == 3)
                log->critical("[{}] Queueing work update after finalization, delta = {}", 
                             comm.rank(), subtree_delta);
        }
        else
        {
            assert(phase_counter < 2);
            phase_counter = 0;      // reset protocol state on root when updating work
        }
    }
}

void
diy::Master::IExchangeInfoDUD::
manage_communication()
{
    mpi::optional<mpi::status> pending_msg = comm.iprobe(mpi::any_source, tags::iexchange);

    while(pending_msg)
    {
        int msg_type, value;
        receive(pending_msg->source(), msg_type, value);

        if (msg_type == static_cast<int>(MessageType::load_adjustment))
        {
            log->debug("[{}] Load adjustment from {}, delta = {}", 
                      comm.rank(), pending_msg->source(), value);
            propagate_subtree_change(value);
        }
        else if (msg_type == static_cast<int>(MessageType::abort_command))
        {
            assert(value >= -1);
            terminate(value);
        }
        else if (msg_type == static_cast<int>(MessageType::termination_signal))
        {
            handle_completion(pending_msg->source(), value);
        }

        pending_msg = comm.iprobe(mpi::any_source, tags::iexchange);
    }

    // Start down-up-down consensus protocol
    if (subtree_load == 0 && comm.rank() == 0 && phase_counter == 0)
    {
        if (initial_phase)
        {
            prof >> "iexchange-control";
            prof << "consensus-time";
            prof << "iexchange-control";
            initial_phase = false;
        }

        phase_counter = 1;
        clear_child_acknowledgments();

        if (child_responses)
        {
            notify_descendants(static_cast<int>(MessageType::termination_signal), ++current_round);
            log->info("Initiated down-up-down protocol, round = {}", current_round);
        }
        else
            phase_counter = 3;
    }

    while(advance());
}

void
diy::Master::IExchangeInfoDUD::
terminate(int round)
{
    if (phase_counter == 0) // already terminated
        return;

    if (round != current_round)
        return;

    log->warn("[{}] Terminating round {}", comm.rank(), round);
    assert(round >= 0);

    phase_counter = 0;

    if (comm.rank() != 0)
    {
        transmit(get_parent_rank(), static_cast<int>(MessageType::abort_command), round);

        if (phase_counter >= 2)
            log->critical("[{}] Sending abort after completion", comm.rank());

        current_round = -1;
    }
}

void
diy::Master::IExchangeInfoDUD::
handle_completion(int sender, int round)
{
    if (round < -1)
    {
        log->critical("[{}] Completion notification from {}, round = {}", 
                     comm.rank(), sender, round);
        assert(round >= -1);
    }

    while(advance());     // flush completed operations

    if (sender == get_parent_rank())
    {
        if (round == current_round)       // confirmation of completion
        {
            assert(phase_counter == 2);
            log->info("[{}] Received completion confirmation from parent, round = {}; "
                     "has_pending = {}, subtree = {}, is_outdated = {}",
                     comm.rank(), round, has_pending_activity(), subtree_load, outdated());

            phase_counter = 3;
            assert(!has_pending_activity() && !outdated());
        }
        else
        {
            current_round = round;
            phase_counter = 1;

            if (has_pending_activity() || outdated())
                abort(round);
        }

        if (phase_counter > 0)
        {
            clear_child_acknowledgments();
            if (child_responses)
            {
                log->info("[{}] Notifying descendants of completion, round = {}", 
                         comm.rank(), round);
                notify_descendants(static_cast<int>(MessageType::termination_signal), round);
            }
            else if (phase_counter < 2)
            {
                phase_counter = 2;
                log->info("[{}] Signaling completion to parent (1), round = {}, has_pending = {}", 
                         comm.rank(), round, has_pending_activity());
                transmit(get_parent_rank(), static_cast<int>(MessageType::termination_signal), round);
            }
        }
    }
    else // message from child
    {
        if (round == current_round)
        {
            int child_flag = get_lowest_set_bit(sender);
            child_responses &= ~child_flag;

            if (child_responses == 0)       // all children confirmed
            {
                if (comm.rank() != 0)
                {
                    if (has_pending_activity() || outdated())
                        abort(round);
                    else
                    {
                        phase_counter = 2;
                        log->info("[{}] Signaling completion to parent (2), round = {}, has_pending = {}", 
                                 comm.rank(), round, has_pending_activity());
                        transmit(get_parent_rank(), static_cast<int>(MessageType::termination_signal), round);
                    }
                }
                else if (phase_counter == 1)
                {
                    log->info("[{}] Received completion confirmations from children at root, round = {}", 
                             comm.rank(), round);

                    phase_counter = 3;
                    notify_descendants(static_cast<int>(MessageType::termination_signal), round);
                }
            }
        }
    }
}

void
diy::Master::IExchangeInfoDUD::
clear_child_acknowledgments()
{
    child_responses = 0;
    int child_flag = 1;
    int child = child_flag | comm.rank();

    while (child != comm.rank() && child < comm.size())
    {
        child_responses |= child_flag;
        child_flag <<= 1;
        child = child_flag | comm.rank();
    }
}

void
diy::Master::IExchangeInfoDUD::
notify_descendants(int signal, int value)
{
    int child_flag = 1;
    int child = child_flag | comm.rank();

    while (child != comm.rank() && child < comm.size())
    {
        transmit(child, signal, value);
        child_flag <<= 1;
        child = child_flag | comm.rank();
    }
}

bool
diy::Master::IExchangeInfoDUD::
advance()
{
    bool progress_made = false;

    for (auto iter = pending_transfers.begin(); iter != pending_transfers.end();)
    {
        mpi::optional<mpi::status> status_check = iter->pending_op.test();

        if (status_check)
        {
            progress_made = true;
            iter = pending_transfers.erase(iter);
        }
        else
            ++iter;
    }

    return progress_made;
}

