namespace {
class RISCVMCCodeEmitter : public MCCodeEmitter {
  const MCInstrInfo &InstrTable;
  MCContext &Context;
public:
  RISCVMCCodeEmitter(const MCInstrInfo &ii, MCContext &ctx)
    : InstrTable(ii), Context(ctx) {
  }
  ~RISCVMCCodeEmitter() {}

  void EncodeInstruction(const MCInst &Inst, raw_ostream &OS,
                         SmallVectorImpl<MCFixup> &Fixups,
                         const MCSubtargetInfo &STI) const override;

private:
  uint64_t getBinaryCodeForInstr(const MCInst &Inst,
                                 SmallVectorImpl<MCFixup> &Fixups,
                                 const MCSubtargetInfo &STI) const;

  unsigned getMachineOpValue(const MCInst &Inst, const MCOperand &Op,
                             SmallVectorImpl<MCFixup> &Fixups, 
                             const MCSubtargetInfo &STI) const;

  unsigned getJumpTargetEncoding(const MCInst &Inst, unsigned OpIdx,
                                 SmallVectorImpl<MCFixup> &Fixups, 
                                 const MCSubtargetInfo &STI) const {
    const MCOperand &Operand = Inst.getOperand(OpIdx);
    if (Operand.isImm())
      return Operand.getImm() << 1;
    llvm_unreachable("Jump with no immediate field");
  }

  unsigned getBranchTargetEncoding(const MCInst &Inst, unsigned OpIdx,
                                   SmallVectorImpl<MCFixup> &Fixups, 
                                   const MCSubtargetInfo &STI) const {
    const MCOperand &Operand = Inst.getOperand(OpIdx);
    if (Operand.isImm())
      return Operand.getImm() << 1;
    llvm_unreachable("Branch with no immediate field");
  }

  unsigned getPCImmEncoding(const MCInst &Inst, unsigned OpIdx,
                            SmallVectorImpl<MCFixup> &Fixups, 
                            const MCSubtargetInfo &STI) const {
    const MCOperand &Operand = Inst.getOperand(OpIdx);
    if (Operand.isImm())
      return Operand.getImm() << 12;
    llvm_unreachable("Branch with no immediate field");
  }

  unsigned getPCImm64Encoding(const MCInst &Inst, unsigned OpIdx,
                              SmallVectorImpl<MCFixup> &Fixups, 
                              const MCSubtargetInfo &STI) const {
    const MCOperand &Operand = Inst.getOperand(OpIdx);
    if (Operand.isImm())
      return Operand.getImm() << 12;
    llvm_unreachable("Branch with no immediate field");
  }

  unsigned getPCRelEncoding(const MCInst &Inst, unsigned OpIdx,
                            SmallVectorImpl<MCFixup> &Fixups,
                            unsigned Kind, int64_t Offset) const;

  unsigned getPC16DBLEncoding(const MCInst &Inst, unsigned OpIdx,
                              SmallVectorImpl<MCFixup> &Fixups, 
                              const MCSubtargetInfo &STI) const {
    return getPCRelEncoding(Inst, OpIdx, Fixups, RISCV::FK_390_PC16DBL, 2);
  }

  unsigned getPC32DBLEncoding(const MCInst &Inst, unsigned OpIdx,
                              SmallVectorImpl<MCFixup> &Fixups, 
                              const MCSubtargetInfo &STI) const {
    return getPCRelEncoding(Inst, OpIdx, Fixups, RISCV::FK_390_PC32DBL, 2);
  }

  unsigned getPLT16DBLEncoding(const MCInst &Inst, unsigned OpIdx,
                               SmallVectorImpl<MCFixup> &Fixups, 
                               const MCSubtargetInfo &STI) const {
    return getPCRelEncoding(Inst, OpIdx, Fixups, RISCV::FK_390_PLT16DBL, 2);
  }

  unsigned getPLT32DBLEncoding(const MCInst &Inst, unsigned OpIdx,
                               SmallVectorImpl<MCFixup> &Fixups, 
                               const MCSubtargetInfo &STI) const {
    return getPCRelEncoding(Inst, OpIdx, Fixups, RISCV::FK_390_PLT32DBL, 2);
  }

  unsigned getPLT64DBLEncoding(const MCInst &Inst, unsigned OpIdx,
                               SmallVectorImpl<MCFixup> &Fixups, 
                               const MCSubtargetInfo &STI) const {
    return getPCRelEncoding(Inst, OpIdx, Fixups, RISCV::FK_390_PLT64DBL, 2);
  }
};
}

MCCodeEmitter *llvm::createRISCVMCCodeEmitter(const MCInstrInfo &II,
                                              const MCRegisterInfo &MRI,
                                              const MCSubtargetInfo &STI,
                                              MCContext &Ctx) {
  return new RISCVMCCodeEmitter(II, Ctx);
}

void RISCVMCCodeEmitter::
EncodeInstruction(const MCInst &Inst, raw_ostream &OS,
                  SmallVectorImpl<MCFixup> &Fixups,
                  const MCSubtargetInfo &STI) const {
  uint64_t EncodedBits = getBinaryCodeForInstr(Inst, Fixups, STI);
  unsigned ByteCount = InstrTable.get(Inst.getOpcode()).getSize();

  // Process bytes from most significant to least significant
  unsigned BitShift = (ByteCount * 8) - 8;
  for (unsigned Idx = 0; Idx < ByteCount; ++Idx) {
    OS << static_cast<uint8_t>(EncodedBits >> BitShift);
    BitShift -= 8;
  }
}

unsigned RISCVMCCodeEmitter::
getMachineOpValue(const MCInst &Inst, const MCOperand &Op,
                  SmallVectorImpl<MCFixup> &Fixups, 
                  const MCSubtargetInfo &STI) const {
  if (Op.isReg()) {
    auto RegInfo = Context.getRegisterInfo();
    return RegInfo->getEncodingValue(Op.getReg());
  }
  if (Op.isImm())
    return static_cast<unsigned>(Op.getImm());

  llvm_unreachable("Unexpected operand type!");
}

unsigned
RISCVMCCodeEmitter::getPCRelEncoding(const MCInst &Inst, unsigned OpIdx,
                                     SmallVectorImpl<MCFixup> &Fixups,
                                     unsigned Kind, int64_t Offset) const {
  const MCOperand &Operand = Inst.getOperand(OpIdx);

  // Immediate case: treat as unadjusted offset
  if (Operand.isImm())
    return Operand.getImm() / 2;

  const MCExpr *Expr = Operand.getExpr();

  if (Offset != 0) {
    const MCExpr *AdjustedExpr = MCBinaryExpr::CreateAdd(
        Expr, MCConstantExpr::Create(Offset, Context), Context);
    Expr = AdjustedExpr;
  }

  Fixups.push_back(MCFixup::Create(Offset, Expr, static_cast<MCFixupKind>(Kind)));
  return 0;
}

