	, bPendingRefresh(false)
	, LayoutDirection(EPropertyTableOrientation::AlignPropertiesInColumns)
{
}

void FPropertyTable::Update()
{
	// Process pending operations
	for (int32 ActionIndex = 0; ActionIndex < PendingOperations.Num(); ++ActionIndex)
	{
		PendingOperations[ActionIndex].ExecuteIfBound();
	}
	PendingOperations.Reset();

	// Update each column's state
	for (int32 ColIdx = 0; ColIdx < TableColumns.Num(); ++ColIdx)
	{
		TableColumns[ColIdx]->Update();
	}

	if (bPendingRefresh)
	{
		bPendingRefresh = false;
		CleanupInvalidNodes();
		RebuildRows();

		if (LayoutDirection == EPropertyTableOrientation::AlignPropertiesInRows)
		{
			RebuildColumns();
		}
	}
}

