void FPropertyTable::DeleteColumn(const TSharedRef<IPropertyTableColumn>& Column)
{
	TSet<TSharedRef<IPropertyTableCell>> NewSelection;
	for (const TSharedRef<IPropertyTableCell>& Cell : SelectedItems)
	{
		if (Cell->GetOwningColumn() != Column)
		{
			NewSelection.Add(Cell);
		}
	}
	TableColumns.Remove(Column);
	TableStructureChanged.Broadcast();

	if (NewSelection.Num() != SelectedItems.Num())
	{
		ApplySelection(NewSelection);
	}
}

void FPropertyTable::DeleteRow(const TSharedRef<IPropertyTableRow>& Row)
{
	if (!Row->HasChildren() && !Row->GetSource()->AsPropertyPath().IsValid())
	{
		const TWeakObjectPtr<UObject> Object = Row->GetSource()->AsUObject();
		ObjectNodeMap.Remove(Object);
		if (!Object.IsValid())
		{
			CleanupInvalidNodes();
		}
	}

	TSet<TSharedRef<IPropertyTableCell>> NewSelection;
	for (const TSharedRef<IPropertyTableCell>& Cell : SelectedItems)
	{
		if (Cell->GetOwningRow() != Row)
		{
			NewSelection.Add(Cell);
		}
	}
	TableRows.Remove(Row);
	TableRowStructureChanged.Broadcast();

	for (const TSharedRef<IPropertyTableColumn>& Column : TableColumns)
	{
		Column->RemoveCellForRow(Row);
	}

	if (NewSelection.Num() != SelectedItems.Num())
	{
		ApplySelection(NewSelection);
	}
}

void FPropertyTable::CleanupInvalidNodes()
{
	TArray<TSharedRef<FObjectPropertyNode>> ValidEntries;
	for (auto Iterator = ObjectNodeMap.CreateIterator(); Iterator; ++Iterator)
	{
		const TWeakObjectPtr<UObject> Key = Iterator.Key();
		if (!Key.IsValid())
		{
			ValidEntries.Add(Iterator.Value());
		}
	}
	ObjectNodeMap.Empty();
	for (auto Iterator = ValidEntries.CreateIterator(); Iterator; ++Iterator)
	{
		const TSharedRef<FObjectPropertyNode>& Node = *Iterator;
		ObjectNodeMap.Add(Node->GetTargetObject(0), Node);
	}
}

