TArray<FPropertyInfo> FPropertyTable::GetPossibleExtensions(const TSharedRef<FPropertyPath>& Path) const
{
	TArray<FPropertyInfo> ValidExtensions;
	for (auto Iterator = ObjectNodeMap.CreateConstIterator(); Iterator; ++Iterator)
	{
		TArray<FPropertyInfo> Extensions = FPropertyNode::GetPossibleExtensionsForPath(Path, Iterator.Value());
		for (auto ExtIter = Extensions.CreateIterator(); ExtIter; ++ExtIter)
		{
			const FPropertyInfo& Info = *ExtIter;
			if (Info.ArrayIndex == INDEX_NONE &&
				(Info.Property->IsA(UStructProperty::StaticClass()) ||
				 Info.Property->IsA(UArrayProperty::StaticClass())))
			{
				bool AlreadyPresent = false;
				for (auto ExistingIter = ValidExtensions.CreateConstIterator(); ExistingIter; ++ExistingIter)
				{
					if (*ExistingIter == Info)
					{
						AlreadyPresent = true;
						break;
					}
				}
				if (!AlreadyPresent)
				{
					ValidExtensions.Add(Info);
				}
			}
		}
	}
	return ValidExtensions;
}

