void FPropertyTable::SortByColumnIdentifier(EColumnSortPriority::Type Priority, const FName& ColumnId, EColumnSortMode::Type Mode)
{
	for (auto Iterator = TableColumns.CreateIterator(); Iterator; ++Iterator)
	{
		const TSharedRef<IPropertyTableColumn> Column = *Iterator;
		if (Column->GetIdentifier() == ColumnId)
		{
			SortByColumn(Column, Mode);
			break;
		}
	}
}

void FPropertyTable::SortByColumn(const TSharedRef<IPropertyTableColumn>& Column, EColumnSortMode::Type Mode)
{
	if (!Column->CanSort())
	{
		SortedColumn = nullptr;
		SortedColumnMode = EColumnSortMode::None;
		return;
	}

	SortedColumn = Column;
	EColumnSortMode::Type PreviousMode = SortedColumnMode;
	SortedColumnMode = Mode;

	if (SortedColumnMode == EColumnSortMode::None)
	{
		return;
	}

	Column->Sort(TableRows, SortedColumnMode);
	if (SortedColumn.IsValid())
	{
		TableRowStructureChanged.Broadcast();
	}
}

void SetCellValue(const TSharedRef<IPropertyTableCell>& Cell, FString Value)
{
	if (Cell->IsReadOnly())
	{
		return;
	}

	TSharedPtr<FPropertyNode> PropertyNode = Cell->GetPropertyNode();
	if (PropertyNode.IsValid())
	{
		UProperty* NodeProperty = PropertyNode->GetProperty();
		if (NodeProperty->IsA(UNameProperty::StaticClass()))
		{
			Value = Value.TrimQuotes().Replace(TEXT("\n"), TEXT(""));
		}
	}

	FString CurrentValue = Cell->GetValueAsString();
	if (CurrentValue != Value)
	{
		Cell->SetValueFromString(Value);
	}
}

void FPropertyTable::PasteTextIntoCell(const FString& Text, const TSharedRef<IPropertyTableCell>& Cell)
{
	if (!SelectedItems.Contains(Cell))
	{
		return;
	}

	int32 CurrentRowIndex = 0;
	int32 CurrentColumnIndex = 0;
	TSharedPtr<IPropertyTableCell> StartCell = Cell;
	TSharedPtr<IPropertyTableCell> TargetCell = Cell;

	TArray<FString> RowStrings;
	Text.ParseIntoArray(RowStrings, TEXT("\n"), true);

	TArray<FString> CellStrings;
	RowStrings[CurrentRowIndex++].ParseIntoArray(CellStrings, TEXT("\t"), false);

	int32 OperationsBeforeWarning = GetDefault<UEditorPerProjectUserSettings>()->PropertyMatrix_NumberOfPasteOperationsBeforeWarning;

	const bool bShowCancel = false;
	const bool bShowProgress = SelectedItems.Num() > OperationsBeforeWarning;
	GWarn->BeginSlowTask(LOCTEXT("UpdatingPropertiesSlowTaskLabel", "Updating properties..."), bShowProgress, bShowCancel);

	if (RowStrings.Num() == 1 && CellStrings.Num() == 1)
	{
		int32 CellIndex = 0;
		for (auto Iterator = SelectedItems.CreateIterator(); Iterator; ++Iterator)
		{
			SetCellValue(*Iterator, CellStrings[0]);

			if (bShowProgress)
			{
				GWarn->UpdateProgress(CellIndex, SelectedItems.Num());
				CellIndex++;
			}
		}
	}
	else if (StartSelectionRange.IsValid() && EndSelectionRange.IsValid())
	{
		while (TargetCell.IsValid() && SelectedItems.Contains(TargetCell.ToSharedRef()) && CurrentColumnIndex < CellStrings.Num())
		{
			SetCellValue(TargetCell.ToSharedRef(), CellStrings[CurrentColumnIndex++]);
			TargetCell = AdvanceToNextCellInRow(TargetCell.ToSharedRef());

			if ((!TargetCell.IsValid() || !SelectedItems.Contains(TargetCell.ToSharedRef()) || CurrentColumnIndex == CellStrings.Num()) && CurrentRowIndex < RowStrings.Num())
			{
				TargetCell = AdvanceToNextCellInColumn(StartCell.ToSharedRef());
				if (TargetCell.IsValid() && SelectedItems.Contains(TargetCell.ToSharedRef()))
				{
					CurrentColumnIndex = 0;
					StartCell = TargetCell;
					RowStrings[CurrentRowIndex++].ParseIntoArray(CellStrings, TEXT("\t"), false);

					if (bShowProgress)
					{
						GWarn->UpdateProgress(CurrentRowIndex, RowStrings.Num());
					}
				}
			}
		}
	}

	GWarn->EndSlowTask();
}

TSharedPtr<IPropertyTableColumn> FPropertyTable::FindNextColumnWithCells(int32 StartIndex, int32 Step) const
{
	TSharedPtr<IPropertyTableColumn> Column;
	for (int32 Index = StartIndex; Index >= 0 && Index < TableColumns.Num() && (!Column.IsValid() || !Column->CanSelectCells()); Index += Step)
	{
		Column = TableColumns[Index];
	}
	if (!Column.IsValid() || !Column->CanSelectCells())
	{
		return nullptr;
	}
	return Column;
}

TSharedPtr<IPropertyTableRow> FPropertyTable::FindNextRowWithCells(int32 StartIndex, int32 Step) const
{
	TSharedPtr<IPropertyTableRow> Row;
	for (int32 Index = StartIndex; Index >= 0 && Index < TableRows.Num() && (!Row.IsValid() || !Row->HasCells()); Index += Step)
	{
		Row = TableRows[Index];
	}
	if (!Row.IsValid() || !Row->HasCells())
	{
		return nullptr;
	}
	return Row;
}

