TSharedPtr<IPropertyTableCell> FPropertyTable::AdvanceToNextCellInRow(const TSharedRef<IPropertyTableCell>& Cell)
{
	int32 FoundIndex = TableColumns.Find(Cell->GetOwningColumn());
	if (FoundIndex == INDEX_NONE)
	{
		return nullptr;
	}

	int32 StartIndex = FoundIndex + 1;
	TSharedPtr<IPropertyTableColumn> NextColumn = FindNextColumnWithCells(StartIndex, 1);
	if (!NextColumn.IsValid())
	{
		return nullptr;
	}
	return NextColumn->GetCell(Cell->GetOwningRow());
}

