void FPropertyTable::SetActiveCell(const TSharedPtr<IPropertyTableCell>& Cell)
{
	if (ActiveCell == Cell || !SupportsCellSelection())
	{
		return;
	}

	if (ActiveCell.IsValid())
	{
		ActiveCell->ExitEditMode();
	}

	if (Cell.IsValid())
	{
		ActiveRow = Cell->GetOwningRow();
		ActiveColumn = Cell->GetOwningColumn();
	}
	ActiveCell = Cell;

	bool NotifyChange = false;
	if (ActiveRow.IsValid() && (!SelectedRows.Contains(ActiveRow.ToSharedRef()) || (ActiveCell.IsValid() && !SelectedItems.Contains(ActiveCell.ToSharedRef()))))
	{
		SelectedRows.Empty();
		SelectedRows.Add(ActiveRow.ToSharedRef());
		NotifyChange = true;
	}

	if (ActiveCell.IsValid() && !SelectedItems.Contains(ActiveCell.ToSharedRef()))
	{
		SelectedItems.Empty();
		SelectedItems.Add(ActiveCell.ToSharedRef());
		StartSelectionRange = ActiveCell;
		EndSelectionRange = ActiveCell;
		NotifyChange = true;
	}

	if (NotifyChange)
	{
		SelectionChanged.Broadcast();
	}
}

void FPropertyTable::SetActiveColumn(const TSharedPtr<IPropertyTableColumn>& Column)
{
	if (ActiveColumn == Column || !SupportsCellSelection())
	{
		return;
	}
	ActiveColumn = Column;

	if (ActiveCell.IsValid() && ActiveCell->GetOwningColumn() != Column)
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}
}

void FPropertyTable::SetActiveRow(const TSharedPtr<IPropertyTableRow>& Row)
{
	if (ActiveRow == Row || !SupportsRowSelection())
	{
		return;
	}
	ActiveRow = Row;

	if (!ActiveRow.IsValid() || (ActiveCell.IsValid() && ActiveCell->GetOwningRow() != ActiveRow))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}

	if (ActiveRow.IsValid() && !SelectedRows.Contains(ActiveRow.ToSharedRef()))
	{
		SelectedRows.Empty();
		SelectedRows.Add(ActiveRow.ToSharedRef());
		SelectionChanged.Broadcast();
	}
}

void FPropertyTable::ApplyRowSelection(const TSet<TSharedRef<IPropertyTableRow>>& Rows)
{
	SelectedColumns.Empty();
	SelectedRows.Empty();

	if (!SupportsRowSelection())
	{
		return;
	}

	SelectedRows.Append(Rows);

	TSet<TSharedRef<IPropertyTableCell>> PreviousSelection(SelectedItems);
	bool RemovedCells = false;
	for (auto Iterator = PreviousSelection.CreateConstIterator(); Iterator; ++Iterator)
	{
		const TSharedRef<IPropertyTableCell> Cell = *Iterator;
		if (!SelectedRows.Contains(Cell->GetOwningRow()))
		{
			SelectedItems.Remove(Cell);
			SelectedColumns.Add(Cell->GetOwningColumn());
			RemovedCells = true;
		}
	}

	if (RemovedCells)
	{
		StartSelectionRange = nullptr;
		EndSelectionRange = nullptr;
	}

	if (ActiveRow.IsValid() && !SelectedRows.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRow = nullptr;
	}
	if (ActiveColumn.IsValid() && !SelectedColumns.Contains(ActiveColumn.ToSharedRef()))
	{
		ActiveColumn = nullptr;
	}
	if (ActiveCell.IsValid() && !SelectedItems.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}
	SelectionChanged.Broadcast();
}

void FPropertyTable::ApplyCellSelection(const TSet<TSharedRef<IPropertyTableCell>>& Cells)
{
	SelectedItems.Empty();

	if (!SupportsCellSelection())
	{
		return;
	}

	SelectedItems.Append(Cells);
	SelectedColumns.Empty();
	SelectedRows.Empty();

	TSharedPtr<IPropertyTableCell> LastCell;
	for (auto Iterator = SelectedItems.CreateConstIterator(); Iterator; ++Iterator)
	{
		LastCell = *Iterator;
		SelectedRows.Add(LastCell->GetOwningRow());
		SelectedColumns.Add(LastCell->GetOwningColumn());
	}

	if (ActiveRow.IsValid() && !SelectedRows.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRow = nullptr;
	}
	if (ActiveColumn.IsValid() && !SelectedColumns.Contains(ActiveColumn.ToSharedRef()))
	{
		ActiveColumn = nullptr;
	}

	if (LastCell.IsValid() && SelectedItems.Num() == 1)
	{
		StartSelectionRange = LastCell;
		EndSelectionRange = LastCell;
	}
	else
	{
		StartSelectionRange = nullptr;
		EndSelectionRange = nullptr;
	}

	if (ActiveCell.IsValid() && !SelectedItems.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}
	SelectionChanged.Broadcast();
}

void FPropertyTable::SelectRange(const TSharedRef<IPropertyTableCell>& Start, const TSharedRef<IPropertyTableCell>& End)
{
	SelectedColumns.Empty();
	SelectedRows.Empty();
	SelectedItems.Empty();

	int32 StartRow = TableRows.Find(Start->GetOwningRow());
	int32 EndRow = TableRows.Find(End->GetOwningRow());
	for (int32 RowIndex = StartRow; RowIndex < TableRows.Num() && RowIndex <= EndRow; RowIndex++)
	{
		SelectedRows.Add(TableRows[RowIndex]);
	}

	int32 StartCol = TableColumns.Find(Start->GetOwningColumn());
	int32 EndCol = TableColumns.Find(End->GetOwningColumn());
	for (int32 ColIndex = StartCol; ColIndex < TableColumns.Num() && ColIndex <= EndCol; ColIndex++)
	{
		SelectedColumns.Add(TableColumns[ColIndex]);
		for (auto RowIter = SelectedRows.CreateConstIterator(); RowIter; ++RowIter)
		{
			SelectedItems.Add(TableColumns[ColIndex]->GetCell(*RowIter));
		}
	}

	if (ActiveRow.IsValid() && !SelectedRows.Contains(ActiveRow.ToSharedRef()))
	{
		ActiveRow = nullptr;
	}
	if (ActiveColumn.IsValid() && !SelectedColumns.Contains(ActiveColumn.ToSharedRef()))
	{
		ActiveColumn = nullptr;
	}

	StartSelectionRange = Start;
	EndSelectionRange = End;

	if (ActiveCell.IsValid() && !SelectedItems.Contains(ActiveCell.ToSharedRef()))
	{
		ActiveCell->ExitEditMode();
		ActiveCell = nullptr;
	}
	SelectionChanged.Broadcast();
}

void FPropertyTable::CollectSelectedObjects(TArray<TWeakObjectPtr<UObject>>& OutObjects) const
