TSharedRef<FObjectPropertyNode> FPropertyTable::GetObjectNode(const TSharedRef<IPropertyTableColumn>& Column, const TSharedRef<IPropertyTableRow>& Row)
{
	TWeakObjectPtr<UObject> Object;
	if (LayoutDirection == EPropertyTableOrientation::AlignPropertiesInColumns)
	{
		Object = Row->GetSource()->AsUObject();
	}
	else
	{
		Object = Column->GetSource()->AsUObject();
	}
	return GetObjectNode(Object);
}

TSharedRef<FObjectPropertyNode> FPropertyTable::GetObjectNode(const TWeakObjectPtr<UObject>& Object)
{
	TSharedRef<FObjectPropertyNode>* NodePtr = ObjectNodeMap.Find(Object);
	if (NodePtr != nullptr)
	{
		return *NodePtr;
	}

	TSharedRef<FObjectPropertyNode> Node(new FObjectPropertyNode());
	Node->AddObject(Object.Get());
	FPropertyNodeInitParams Params;
	Params.bCreateCategoryNodes = false;
	Node->InitializeNode(Params);
	ObjectNodeMap.Add(Object, Node);
	return Node;
}

