void FPropertyTable::RebuildRows()
{
	if (LayoutDirection == EPropertyTableOrientation::AlignPropertiesInColumns)
	{
		TMultiMap<UObject*, TSharedRef<IPropertyTableRow>> RowMapping;
		for (int32 RowIndex = 0; RowIndex < TableRows.Num(); ++RowIndex)
		{
			RowMapping.Add(TableRows[RowIndex]->GetSource()->AsUObject().Get(), TableRows[RowIndex]);
		}

		TableRows.Empty();
		for (auto Iterator = ObjectsList.CreateConstIterator(); Iterator; ++Iterator)
		{
			const TWeakObjectPtr<UObject>& Object = *Iterator;
			if (Object.IsValid())
			{
				const TSharedRef<FObjectPropertyNode> Node = GetObjectNode(Object);
				const TSharedPtr<FPropertyNode> PropertyNode = FPropertyNode::FindPropertyNodeByPath(BasePath, Node);

				if (PropertyNode.IsValid())
				{
					UProperty* Property = PropertyNode->GetProperty();
					if (Property != nullptr && Property->IsA(UArrayProperty::StaticClass()))
					{
						for (int32 ChildIndex = 0; ChildIndex < PropertyNode->GetChildCount(); ++ChildIndex)
						{
							TSharedPtr<FPropertyNode> ChildNode = PropertyNode->GetChildNode(ChildIndex);
							FPropertyInfo Extension;
							Extension.Property = ChildNode->GetProperty();
							Extension.ArrayIndex = ChildNode->GetArrayIndex();
							TSharedRef<FPropertyPath> Path = FPropertyPath::CreateEmpty()->ExtendPath(Extension);

							TArray<TSharedRef<IPropertyTableRow>> Matches;
							bool Found = false;
							RowMapping.MultiFind(Object.Get(), Matches);
							for (int32 MapIndex = 0; MapIndex < Matches.Num(); ++MapIndex)
							{
								if (FPropertyPath::AreEqual(Path, Matches[MapIndex]->GetPartialPath()))
								{
									Found = true;
									TableRows.Add(Matches[MapIndex]);
									break;
								}
							}
							if (!Found)
							{
								TableRows.Add(MakeShareable(new FPropertyTableRow(SharedThis(this), Object, Path)));
							}
						}
					}
					else
					{
						TArray<TSharedRef<IPropertyTableRow>> Matches;
						bool Found = false;
						RowMapping.MultiFind(Object.Get(), Matches);
						for (int32 MapIndex = 0; MapIndex < Matches.Num(); ++MapIndex)
						{
							if (Matches[MapIndex]->GetPartialPath()->GetPropertyCount() == 0)
							{
								Found = true;
								TableRows.Add(Matches[MapIndex]);
								break;
							}
						}
						if (!Found)
						{
							TableRows.Add(MakeShareable(new FPropertyTableRow(SharedThis(this), Object)));
						}
					}
				}
			}
		}
	}

	const TSharedPtr<IPropertyTableColumn> Column = SortedColumn.Pin();
	if (Column.IsValid() && SortedColumnMode != EColumnSortMode::None)
	{
		Column->Sort(TableRows, SortedColumnMode);
	}
	TableRowStructureChanged.Broadcast();
}

void FPropertyTable::RebuildColumns()
{
	if (LayoutDirection == EPropertyTableOrientation::AlignPropertiesInColumns)
	{
		TMultiMap<UProperty*, TSharedRef<IPropertyTableColumn>> ColumnMapping;
		for (int32 ColIndex = 0; ColIndex < TableColumns.Num(); ++ColIndex)
		{
			TSharedRef<IDataSource> Source = TableColumns[ColIndex]->GetSource();
			TSharedPtr<FPropertyPath> Path = Source->AsPropertyPath();
			if (Path.IsValid() && Path->GetPropertyCount() > 0)
			{
				ColumnMapping.Add(Path->GetRootProperty().Property.Get(), TableColumns[ColIndex]);
			}
		}

		TableColumns.Empty();

		if (bDisplayRowHeader)
		{
			TSharedRef<IPropertyTableColumn> NewColumn = MakeShareable(new FPropertyTableRowHeaderColumn(SharedThis(this)));
			TableColumns.Add(NewColumn);
		}

		if (bShowObjectNames)
		{
			TSharedRef<IPropertyTableColumn> NewColumn = MakeShareable(new FPropertyTableObjectNameColumn(SharedThis(this)));
			NewColumn->SetFrozen(true);
			TableColumns.Add(NewColumn);
		}

		TArray<TWeakObjectPtr<UStruct>> UniqueTypes;
		TArray<int> TypeCounter;
		for (auto Iterator = ObjectsList.CreateConstIterator(); Iterator; ++Iterator)
		{
			UObject* Object = *Iterator;
			if (!Object)
			{
				continue;
			}

			const TSharedRef<FObjectPropertyNode> RootNode = GetObjectNode(Object);
			TWeakObjectPtr<UStruct> Type;

			if (BasePath->GetPropertyCount() == 0)
			{
				Type = RootNode->GetBaseClass();
			}
			else
			{
				const TSharedPtr<FPropertyNode> PropertyNode = FPropertyNode::FindPropertyNodeByPath(BasePath, RootNode);
				if (!PropertyNode.IsValid())
				{
					continue;
				}

				const TWeakObjectPtr<UProperty> Property = PropertyNode->GetProperty();
				if (!Property.IsValid() || !Property->IsA(UStructProperty::StaticClass()))
				{
					continue;
				}

				UStructProperty* StructProperty = Cast<UStructProperty>(Property.Get());
				Type = StructProperty->Struct;
			}

			if (Type.IsValid())
			{
				int32 TypeIndex = UniqueTypes.IndexOfByKey(Type);
				if (TypeIndex == INDEX_NONE)
				{
					TypeIndex = UniqueTypes.Add(Type);
					TypeCounter.Add(1);
				}
				else
				{
					TypeCounter[TypeIndex]++;
				}
			}
		}

		for (int32 TypeIndex = 0; TypeIndex < UniqueTypes.Num(); ++TypeIndex)
		{
			TWeakObjectPtr<UStruct> Type = UniqueTypes[TypeIndex];
			if (!Type.IsValid())
			{
				continue;
			}

			for (auto Iterator = ObjectsList.CreateConstIterator(); Iterator; ++Iterator)
			{
				UObject* Object = *Iterator;
				if (!Object || Object->GetClass() != Type)
				{
					continue;
				}

				const TSharedRef<FObjectPropertyNode> ObjectNode = GetObjectNode(Object);
				const TSharedPtr<FPropertyNode> PropertyNode = FPropertyNode::FindPropertyNodeByPath(BasePath, ObjectNode);
				if (!PropertyNode.IsValid())
				{
					continue;
				}

				for (int32 ChildIndex = 0; ChildIndex < PropertyNode->GetChildCount(); ++ChildIndex)
				{
					TSharedPtr<FPropertyNode> ChildNode = PropertyNode->GetChildNode(ChildIndex);
					if (!ChildNode.IsValid())
					{
						continue;
					}

					UProperty* Property = ChildNode->GetProperty();
					if (!Property)
					{
						continue;
					}

					FPropertyInfo Info;
					Info.Property = Property;
					Info.ArrayIndex = ChildNode->GetArrayIndex();
					TSharedRef<FPropertyPath> Path = FPropertyPath::CreateEmpty()->ExtendPath(Info);

					TArray<TSharedRef<IPropertyTableColumn>> Matches;
					bool Found = false;
					ColumnMapping.MultiFind(Property, Matches);
					for (int32 MatchIndex = 0; MatchIndex < Matches.Num(); ++MatchIndex)
					{
						if (FPropertyPath::AreEqual(Path, Matches[MatchIndex]->GetPath()))
						{
							Found = true;
							TableColumns.Add(Matches[MatchIndex]);
							break;
						}
					}
					if (!Found)
					{
						TableColumns.Add(MakeShareable(new FPropertyTableColumn(SharedThis(this), Path)));
					}
				}
			}
		}
	}

	const TSharedPtr<IPropertyTableColumn> Column = SortedColumn.Pin();
	if (Column.IsValid() && SortedColumnMode != EColumnSortMode::None)
	{
		Column->Sort(TableColumns, SortedColumnMode);
	}
	TableStructureChanged.Broadcast();
}

