// [[Rcpp::export]]
NumericMatrix term_score(NumericMatrix beta) {
  // calculate term score (Blei and Lafferty 2009)
  int W = beta.nrow();
  int K = beta.ncol();
  NumericMatrix result(W, K);

  for (int w = 0; w < W; ++w) {
    // Compute log of geometric mean instead of direct product
    double log_sum = 0.0;
    for (int k = 0; k < K; ++k) {
      if (beta(w, k) > 0) {
        log_sum += log(beta(w, k));
      }
    }
    double geo_mean_exp = (K > 0) ? exp(log_sum / K) : 0.0;

    for (int k = 0; k < K; ++k) {
      if (beta(w, k) > 0 && geo_mean_exp > 0) {
        result(w, k) = beta(w, k) * log(beta(w, k) / geo_mean_exp);
      } else {
        result(w, k) = 0.0;
      }
    }
  }

  return result;
}

// [[Rcpp::export]]
NumericVector calc_coherence(List ctot, NumericMatrix top_words_topics) {
  int K = top_words_topics.ncol();
  int M = top_words_topics.nrow();
  NumericMatrix cond_topic_count = ctot["cond_topic_count"];
  NumericVector coherence_scores(K, 0.0);
  NumericVector composer_id = ctot["composer_id"];

  for (int k = 0; k < K; ++k) {
    for (int l = 0; l < M - 1; ++l) {
      for (int m = l + 1; m < M; ++m) {
        double doc_freq_l = 0.0;
        double co_doc_freq = 0.0;

        for (int i = 0; i < composer_id.size(); ++i) {
          bool is_l = (composer_id[i] == top_words_topics(l, k));
          bool is_m = (composer_id[i] == top_words_topics(m, k));

          doc_freq_l += (double)is_l;
          co_doc_freq += (double)(is_l && is_m);
        }

        coherence_scores[k] += log((co_doc_freq + 1.0) / doc_freq_l);
      }
    }
  }

  return coherence_scores;
}

