LabelType* LabelType::lookup(const char* labelName) {
  LabelType* current = LabelType::head;
  while (current != nullptr) {
    if (current->labelName && !strcasecmp(labelName, current->labelName)) {
      return current;
    }
    current = current->next;
  }
  return nullptr;
}

LabelType* LabelType::head = nullptr;

