void LabelType::render(const char* text,
                       const Rectangle& bounds,
                       Flags state) const {
  if (state & INACTIVE) {
    Color originalColor = getcolor();
    setcolor(GRAY90);
    Rectangle offsetBounds(bounds);
    offsetBounds.move(1, 1);
    renderText(text, offsetBounds, state);
    setcolor(originalColor);
  }
  renderText(text, bounds, state);
}

