}

void Widget::drawLabel() const {
  Flags state = this->flags();
  if (!graphic() && (!text() || !*text() ||
                     ((state & 15) && !(state & ALIGN_INSIDE)))) {
    return;
  }

  Rectangle innerRect(width(), height());
  frame()->inset(innerRect);

  applyStyle(style(), this->flags() ^ OUTPUT);
  drawLabel(innerRect, state);
}

void Widget::drawLabel(const Rectangle& targetArea, Flags state) const {
  const Symbol* img = graphic();
  Rectangle workingRect(targetArea);

  if (img) {
    int imgW = workingRect.w();
    int imgH = workingRect.h();
    img->getSize(imgW, imgH);

    if (state & CLIP_REGION) push_clip(workingRect);

    // Scaling logic based on resize flags
    if (state & SCALE_FIT) {
      if ((state & SCALE_FILL) || imgW > workingRect.w() || imgH > workingRect.h()) {
        if (imgW * workingRect.h() > imgH * workingRect.w()) {
          imgH = imgH * workingRect.w() / imgW;
          imgW = workingRect.w();
        } else {
          imgW = imgW * workingRect.h() / imgH;
          imgH = workingRect.h();
        }
      }
    } else if (state & SCALE_FILL) {
      imgW = workingRect.w();
      imgH = workingRect.h();
    }

    // Special handling when no alignment flags are set
    if (text_ && !(state & 0x3f) && !(text_[0] == '@' && text_[1] == ';')) {
      int verticalOffset = (workingRect.h() - (int)(imgH + textSize() + leading() + .5)) >> 1;
      if (verticalOffset < 0) {
        if (imgW < workingRect.w()) {
          int textWidth = workingRect.w() - imgW;
          int textHeight = workingRect.h();
          measure(text_, textWidth, textHeight, state);
          int horizontalOffset = (workingRect.w() - imgW - textWidth) >> 1;
          if (horizontalOffset >= 0) {
            workingRect.move_x(horizontalOffset);
            state |= LEFT_ALIGN | INSIDE_TEXT;
            goto placeImageAndText;
          }
        }
        verticalOffset = 0;
      }
      workingRect.move_y(verticalOffset);
      state |= TOP_ALIGN | INSIDE_TEXT;
    placeImageAndText:;
    }

    if (state & CENTER_ALIGN) {
      Rectangle imageRect(workingRect, imgW, imgH, 0);
      img->render(imageRect);
    } else {
      Rectangle imageRect(workingRect, imgW, imgH, state);
      img->render(imageRect);

      if (state & TOP_ALIGN) workingRect.set_y(imageRect.bottom());
      else if (state & BOTTOM_ALIGN) workingRect.set_bottom(imageRect.top());
      else if (state & LEFT_ALIGN) workingRect.set_x(imageRect.right());
      else if (state & RIGHT_ALIGN) workingRect.set_right(imageRect.left());
      else workingRect.set_y(imageRect.bottom());
    }
  }

  // Draw text only if inside or properly aligned
  if ((!(state & POSITION_MASK) || (state & INSIDE_TEXT)) &&
      workingRect.width() > 0 && text_ && *text_) {

    // Add padding for interior borders
    if (workingRect.width() > 6 && (state & LEFT_ALIGN)) {
      if (workingRect.width() > 9) {
        workingRect.move_x(3);
        workingRect.move_right(-3);
      } else {
        workingRect.set_x(workingRect.right() - 6);
      }
    }

    if (workingRect.width() > 6 && (state & RIGHT_ALIGN)) {
      if (workingRect.width() > 9) {
        workingRect.move_right(-6);
      } else {
        workingRect.set_width(6);
      }
    }

    if (!img && (state & CLIP_REGION)) push_clip(workingRect);
    labeltype()->render(text_, workingRect, state);
  } else {
    if (!img) return;
  }

  if (state & CLIP_REGION) pop_clip();
}

void Group::drawOutsideLabel(Widget& widget) const {
  Flags state = widget.flags();
  if (state & INVISIBLE) return;

  if (!(state & 15) || (state & INSIDE_TEXT)) return;
  if (!widget.text() || !*widget.text()) return;

  Rectangle labelRect(widget);
  if (state & TOP_ALIGN) {
    if (state & BOTTOM_ALIGN) {
      if (state & LEFT_ALIGN) {
        state &= ~(TOP_ALIGN | LEFT_ALIGN);
      } else {
        state &= ~BOTTOM_ALIGN;
      }
      if (state & RIGHT_ALIGN) {
        labelRect.x(labelRect.right() + 3);
        labelRect.set_right(this->width());
        state = (state & ~RIGHT_ALIGN) | LEFT_ALIGN;
      } else {
        labelRect.x(0);
        labelRect.w(widget.x() - 3);
        state |= RIGHT_ALIGN;
      }
    } else {
      state ^= (BOTTOM_ALIGN | TOP_ALIGN);
      labelRect.y(0);
      labelRect.h(widget.y());
    }
  } else if (state & BOTTOM_ALIGN) {
    state ^= (BOTTOM_ALIGN | TOP_ALIGN);
    labelRect.y(labelRect.bottom());
    labelRect.set_bottom(height());
  } else if (state & LEFT_ALIGN) {
    state ^= (LEFT_ALIGN | RIGHT_ALIGN);
    labelRect.x(0);
    labelRect.w(widget.x() - 3);
  } else if (state & RIGHT_ALIGN) {
    state ^= (LEFT_ALIGN | RIGHT_ALIGN);
    labelRect.x(labelRect.right() + 3);
    labelRect.set_right(this->width());
  }

  state = (state & ~(HIGHLIGHT | PUSHED)) | OUTPUT;
  applyStyle(widget.style(), state);
  widget.labeltype()->render(widget.text(), labelRect, state);
}

void Widget::measureLabel(int& outW, int& outH) const {
  setFont(labelfont(), labelsize());
  outW = outH = 300; // arbitrary wrap width for backward compatibility
  measure(text(), outW, outH, flags());
}

