PIXELFORMATDESCRIPTOR GetDefaultPixelFormatDescriptor()
{
    PIXELFORMATDESCRIPTOR desc = {};
    desc.nSize     = sizeof(PIXELFORMATDESCRIPTOR);
    desc.nVersion  = 1;
    desc.dwFlags   = PFD_DRAW_TO_WINDOW | PFD_GENERIC_ACCELERATED |
                     PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
    desc.iPixelType = PFD_TYPE_RGBA;
    desc.cColorBits = 24;
    desc.cAlphaBits = 8;
    desc.cDepthBits = 24;
    desc.cStencilBits = 8;
    desc.iLayerType = PFD_MAIN_PLANE;
    return desc;
}

// Helper to append an attribute-value pair to the list
static void AddAttribute(std::vector<int>& list, int attr, int value)
{
    list.push_back(attr);
    list.push_back(value);
}

std::vector<int> GetDefaultPixelFormatAttributes(bool preservedSwap)
{
    std::vector<int> attribs;
    attribs.reserve(20); // Pre-allocate space for efficiency

    AddAttribute(attribs, WGL_DRAW_TO_WINDOW_ARB, TRUE);
    AddAttribute(attribs, WGL_ACCELERATION_ARB, WGL_FULL_ACCELERATION_ARB);
    AddAttribute(attribs, WGL_SUPPORT_OPENGL_ARB, TRUE);
    AddAttribute(attribs, WGL_DOUBLE_BUFFER_ARB, TRUE);
    AddAttribute(attribs, WGL_PIXEL_TYPE_ARB, WGL_TYPE_RGBA_ARB);
    AddAttribute(attribs, WGL_COLOR_BITS_ARB, 24);
    AddAttribute(attribs, WGL_ALPHA_BITS_ARB, 8);
    AddAttribute(attribs, WGL_DEPTH_BITS_ARB, 24);
    AddAttribute(attribs, WGL_STENCIL_BITS_ARB, 8);

    int swapMethod = preservedSwap ? WGL_SWAP_COPY_ARB : WGL_SWAP_UNDEFINED_ARB;
    AddAttribute(attribs, WGL_SWAP_METHOD_ARB, swapMethod);

    attribs.push_back(0); // Terminate list
    return attribs;
}

int QueryWGLFormatAttrib(HDC dc, int formatID, int attributeName, const FunctionsWGL* funcs)
{
    if (funcs == nullptr || funcs->getPixelFormatAttribivARB == nullptr)
        return 0;

    int value = 0;
    BOOL success = funcs->getPixelFormatAttribivARB(dc, formatID, 0, 1, &attributeName, &value);
    if (!success)
        return 0;

    return value;
}

