	: m_Time{ std::chrono::steady_clock::now() - nsOffset }
{
}

// Constructor: Initialize by subtracting microseconds from current time
TimeSince::TimeSince(std::chrono::microseconds usOffset)
	: m_Time{ std::chrono::steady_clock::now() - usOffset }
{
}

// Constructor: Initialize by subtracting milliseconds from current time
TimeSince::TimeSince(std::chrono::milliseconds msOffset)
	: m_Time{ std::chrono::steady_clock::now() - msOffset }
{
}

// Constructor: Initialize by subtracting seconds from current time
TimeSince::TimeSince(std::chrono::seconds secOffset)
	: m_Time{ std::chrono::steady_clock::now() - secOffset }
{
}

// Constructor: Initialize by subtracting minutes from current time
TimeSince::TimeSince(std::chrono::minutes minOffset)
	: m_Time{ std::chrono::steady_clock::now() - minOffset }
{
}

// Constructor: Initialize by subtracting hours from current time
TimeSince::TimeSince(std::chrono::hours hourOffset)
	: m_Time{ std::chrono::steady_clock::now() - hourOffset }
{
}

// Conversion operator to float: returns elapsed time in seconds as a floating-point value
TimeSince::operator float() const
{
    auto now = std::chrono::steady_clock::now();
    auto diff = now - m_Time;
    return std::chrono::duration_cast<std::chrono::duration<float>>(diff).count();
}

