// Helper to find PlayerController in actor hierarchy
static APlayerController* LocatePlayerController(AActor* StartActor)
{
	APlayerController* FoundPC = nullptr;
	AActor* Current = StartActor;

	while (Current && !FoundPC)
	{
		if ((FoundPC = Cast<APlayerController>(Current)) == nullptr)
		{
			if (APawn* Pawn = Cast<APawn>(Current))
			{
				FoundPC = Cast<APlayerController>(Pawn->GetController());
			}
			else
			{
				Current = Current->GetOwner();
			}
		}
	}

	return FoundPC;
}

void FGameplayAbilityActorInfo::InitializeFromActor(AActor* NewOwner, AActor* NewAvatar, UAbilitySystemComponent* ASC)
{
	check(NewOwner);
	check(ASC);

	OwnerActor = NewOwner;
	AvatarActor = NewAvatar;
	AbilitySystemComponent = ASC;
	AffectedAnimInstanceTag = ASC->AffectedAnimInstanceTag;

	APlayerController* PreviousPC = PlayerController.Get();
	APlayerController* NewPC = LocatePlayerController(NewOwner);
	PlayerController = NewPC;

	if (!PreviousPC && NewPC)
	{
		ASC->OnPlayerControllerSet();
	}

	if (AActor* const AvatarPtr = AvatarActor.Get())
	{
		SkeletalMeshComponent = AvatarPtr->FindComponentByClass<USkeletalMeshComponent>();
		MovementComponent = AvatarPtr->FindComponentByClass<UMovementComponent>();
	}
	else
	{
		SkeletalMeshComponent = nullptr;
		MovementComponent = nullptr;
	}
}

void FGameplayAbilityActorInfo::SetAvatarActor(AActor* InAvatarActor)
{
	InitializeFromActor(OwnerActor.Get(), InAvatarActor, AbilitySystemComponent.Get());
}

void FGameplayAbilityActorInfo::ClearAllReferences()
{
	OwnerActor = nullptr;
	AvatarActor = nullptr;
	PlayerController = nullptr;
	SkeletalMeshComponent = nullptr;
	MovementComponent = nullptr;
}

bool FGameplayAbilityActorInfo::IsLocallyControlled() const
{
	if (const APlayerController* PC = PlayerController.Get())
	{
		return PC->IsLocalController();
	}
	return IsNetAuthority(); // Non-player actors are locally controlled on server
}

bool FGameplayAbilityActorInfo::IsLocallyControlledPlayer() const
{
	const APlayerController* PC = PlayerController.Get();
	return PC ? PC->IsLocalController() : false;
}

bool FGameplayAbilityActorInfo::IsNetAuthority() const
{
	AActor* const OwnerPtr = OwnerActor.Get(true); // bEvenIfPendingKill=true
	if (OwnerPtr)
	{
		return (OwnerPtr->GetLocalRole() == ROLE_Authority);
	}

	ABILITY_LOG(Warning, TEXT("IsNetAuthority called when OwnerActor was invalid. Returning false. AbilitySystemComponent: %s"), *GetNameSafe(AbilitySystemComponent.Get()));
	return false;
}

