TSharedPtr<FAbilityReplicatedDataCache> FGameplayAbilityReplicatedDataContainer::Retrieve(const FGameplayAbilitySpecHandleAndPredictionKey& Key) const
{
	for (const FKeyDataPair& Entry : InUseData)
	{
		if (Entry.Key == Key)
		{
			return Entry.Value;
		}
	}
	return TSharedPtr<FAbilityReplicatedDataCache>();
}

TSharedRef<FAbilityReplicatedDataCache> FGameplayAbilityReplicatedDataContainer::AcquireOrAllocate(const FGameplayAbilitySpecHandleAndPredictionKey& Key)
{
	// First check if already in use
	for (const FKeyDataPair& Entry : InUseData)
	{
		if (Entry.Key == Key)
		{
			return Entry.Value;
		}
	}

	// Try to reuse from free list
	TSharedPtr<FAbilityReplicatedDataCache> Candidate;
	for (int32 Idx = FreeData.Num() - 1; Idx >= 0; --Idx)
	{
		TSharedRef<FAbilityReplicatedDataCache>& Ref = FreeData[Idx];
		if (Ref.IsUnique())
		{
			Candidate = Ref;
			Candidate->ResetAll();
			FreeData.RemoveAtSwap(Idx, 1, false);
			break;
		}
	}

	// Allocate new if needed
	if (!Candidate.IsValid())
	{
		Candidate = MakeShareable(new FAbilityReplicatedDataCache());
	}

	TSharedRef<FAbilityReplicatedDataCache> Result = Candidate.ToSharedRef();
	InUseData.Emplace(Key, Result);
	return Result;
}

void FGameplayAbilityReplicatedDataContainer::Discard(const FGameplayAbilitySpecHandleAndPredictionKey& Key)
{
	for (int32 Idx = InUseData.Num() - 1; Idx >= 0; --Idx)
	{
		if (InUseData[Idx].Key == Key)
		{
			TSharedRef<FAbilityReplicatedDataCache>& Removed = InUseData[Idx].Value;
			FreeData.Add(Removed);
			InUseData.RemoveAtSwap(Idx, 1, false);
			break;
		}
	}
}

void FGameplayAbilityReplicatedDataContainer::DumpDebugInfo()
{
	ABILITY_LOG(Warning, TEXT("============================="));
	for (const auto& Pair : InUseData)
	{
		ABILITY_LOG(Warning, TEXT("  %s. %d"), *Pair.Key.AbilityHandle.ToString(), Pair.Key.PredictionKeyAtCreation);
	}
	ABILITY_LOG(Warning, TEXT("In Use Size: %d Free Size: %d"), InUseData.Num(), FreeData.Num());
	ABILITY_LOG(Warning, TEXT("============================="));
}

bool FGameplayAbilityRepAnimMontage::SerializeForNetwork(FArchive& Ar, class UPackageMap* Map, bool& bSuccess)
{
	uint8 PackedPositionFlag = bRepPosition ? 1 : 0;
	Ar.SerializeBits(&PackedPositionFlag, 1);
	bRepPosition = (PackedPositionFlag != 0);

	if (bRepPosition)
	{
		SectionIdToPlay = 0;
		SkipPositionCorrection = false;
		Ar << Position;
	}
	else
	{
		bRepPosition = false;
		SkipPositionCorrection = true;
		Position = 0.0f;
		Ar.SerializeBits(&SectionIdToPlay, 7);
	}

	uint8 PackedStopFlag = IsStopped ? 1 : 0;
	Ar.SerializeBits(&PackedStopFlag, 1);
	IsStopped = (PackedStopFlag & 1) != 0;

	if (Ar.EngineNetVer() < HISTORY_MONTAGE_PLAY_INST_ID_SERIALIZATION)
	{
		uint8 ForcePlayBit = 0;
		Ar.SerializeBits(&ForcePlayBit, 1);
		if (Ar.IsLoading())
		{
			PlayInstanceId = ForcePlayBit ? 1 : 0;
		}
	}

	uint8 PackedSkipCorrection = SkipPositionCorrection ? 1 : 0;
	Ar.SerializeBits(&PackedSkipCorrection, 1);
	SkipPositionCorrection = (PackedSkipCorrection & 1) != 0;

	uint8 PackedSkipRate = bSkipPlayRate ? 1 : 0;
	Ar.SerializeBits(&PackedSkipRate, 1);
	bSkipPlayRate = (PackedSkipRate & 1) != 0;

	Ar << AnimMontage;
	Ar << PlayRate;
	Ar << BlendTime;
	Ar << NextSectionID;

	if (Ar.EngineNetVer() >= HISTORY_MONTAGE_PLAY_INST_ID_SERIALIZATION)
	{
		Ar << PlayInstanceId;
	}

	PredictionKey.NetSerialize(Ar, Map, bSuccess);
	bSuccess = true;
	return true;
}

void FGameplayAbilityRepAnimMontage::ConfigureReplicationMode(ERepAnimPositionMethod Mode)
{
	switch (Mode)
	{
	case ERepAnimPositionMethod::Position:
		bRepPosition = true;
		break;
	case ERepAnimPositionMethod::CurrentSectionId:
		bRepPosition = false;
		break;
	default:
		break;
	}
}

