#include "getcomputername.h"

//! @brief GetComputerName retrieves the name of the host associated with
//! the current thread.
//!
//! @exception errno Passes these errors via errno to GetLastError:
//! - ERROR_INVALID_FUNCTION: getlogin_r() returned an unrecognized error code
//! - ERROR_INVALID_ADDRESS: buffer is an invalid address
//! - ERROR_GEN_FAILURE: buffer not large enough
//!
//! @retval username as UTF-8 string, or null if unsuccessful
char* GetComputerName()
{
    errno = 0;

    // Allocate buffer for hostname using dynamic allocation
    char* hostnameBuffer = new char[_POSIX_HOST_NAME_MAX];

    int result = gethostname(hostnameBuffer, _POSIX_HOST_NAME_MAX);

    if (result != 0)
    {
        // Translate system error codes to Windows-style error codes
        switch (errno)
        {
            case EFAULT:
                errno = ERROR_INVALID_ADDRESS;
                break;
            case ENAMETOOLONG:
                errno = ERROR_GEN_FAILURE;
                break;
            default:
                errno = ERROR_INVALID_FUNCTION;
        }

        delete[] hostnameBuffer;
        return nullptr;
    }

    // Convert to std::string to ensure proper handling, then duplicate for return
    std::string hostString(hostnameBuffer);
    delete[] hostnameBuffer;

    return strdup(hostString.c_str());
}

#include "sweptSurface.h"

SweptSurface::SweptSurface(int p_, int q_, std::vector<double> knotU_, std::vector<double> knotV_, std::vector<std::vector<Point3D>> controlNet_)
    : p(p_), q(q_), knotU(std::move(knotU_)), knotV(std::move(knotV_)), controlNet(std::move(controlNet_)) {}

void SweptSurface::generateTranslationalSweep(int degreeU, const std::vector<double>& uknots,
                                              int degreeV, const std::vector<double>& vknots,
                                              const std::vector<Point3D>& profileU,
                                              const std::vector<Point3D>& profileV) {
    p = degreeU;
    q = degreeV;
    knotU = uknots;
    knotV = vknots;

    // Compute dimensions based on B-spline theory: r = n + p + 1, s = m + q + 1
    const int r = static_cast<int>(knotU.size()) - 1;
    const int s = static_cast<int>(knotV.size()) - 1;
    const int n = r - p - 1;
    const int m = s - q - 1;

    const int numCtrlPtsU = n + 1;
    const int numCtrlPtsV = m + 1;

    controlNet.assign(numCtrlPtsU, std::vector<Point3D>(numCtrlPtsV));

    for (int i = 0; i < numCtrlPtsU; ++i) {
        const Point3D& uPoint = profileU[i];
        for (int j = 0; j < numCtrlPtsV; ++j) {
            controlNet[i][j] = uPoint + profileV[j];
        }
    }
}

void SweptSurface::exportSurfaceData(int& outP, int& outQ,
                                     std::vector<double>& outKnotU,
                                     std::vector<double>& outKnotV,
                                     std::vector<std::vector<Point3D>>& outControlNet) const {
    outP = p;
    outQ = q;
    outKnotU = knotU;
    outKnotV = knotV;
    outControlNet = controlNet;
}

void SweptSurface::constructSweptSurface(const BSplineCurve& pathCurve,
                                         const BSplineCurve& sectionCurve,
                                         const vector3D& binormalDir,
                                         const Matrix33& scaleTransform,
                                         int desiredSections) {
    p = sectionCurve.getDegree();
    knotU = sectionCurve.getKnotVec();
    q = pathCurve.getDegree();

    auto pathKnots = pathCurve.getKnotVec();
    const int initialKnotCount = static_cast<int>(pathKnots.size());
    const int targetSectionCount = desiredSections + 1;

    if (initialKnotCount <= targetSectionCount + q) {
        const int neededInsertions = targetSectionCount + q - initialKnotCount + 1;
        refinePathCurve(pathCurve, neededInsertions);
        knotV = pathCurve.getKnotVec();
    } else {
        knotV = pathKnots;
        if (initialKnotCount > targetSectionCount + q + 1) {
            // Adjust number of sections to match available knots
            // (more instances of C(u) needed)
            // Recompute actual number of sections possible
            // targetSectionCount = initialKnotCount - q - 1;
        }
    }

    // Sample parameter values along v-direction
    const int numSections = static_cast<int>(knotV.size()) - q - 1;
    std::vector<double> sampleParams(numSections);
    sampleParams.front() = 0.0;
    sampleParams.back() = 1.0;

    for (int idx = 1; idx < numSections - 1; ++idx) {
        double sum = 0.0;
        for (int k = 1; k <= q; ++k) {
            sum += knotV[idx + k];
        }
        sampleParams[idx] = sum / static_cast<double>(q);
    }

    // Generate transformed control points per section
    std::vector<std::vector<Point3D>> sectionPoints;
    sectionPoints.reserve(numSections);

    for (int secIdx = 0; secIdx < numSections; ++secIdx) {
        auto pts = sectionCurve.getControlPts();
        for (auto& pt : pts) {
            pt = scaleTransform * pt;
        }

        const vector3D tangent = pathCurve.getFirstDerivative(sampleParams[secIdx]).normalize();
        const vector3D normal = binormalDir.normalize();
        const vector3D biNormal = normal.cross(tangent);

        const Point3D pathPoint = pathCurve.getPointAt(sampleParams[secIdx]);
        Matrix33 orientation(normal, tangent, biNormal);

        for (auto& pt : pts) {
            pt = orientation * pt + pathPoint;
        }

        sectionPoints.push_back(pts);
    }

    // Transpose matrix of control points: [sections][controlPtsInSection] -> [controlPtsInSection][sections]
    const int ctrlPerSection = static_cast<int>(sectionPoints[0].size());
    const int totalSections = static_cast<int>(sectionPoints.size());

    controlNet.resize(ctrlPerSection);
    for (int col = 0; col < ctrlPerSection; ++col) {
        controlNet[col].resize(totalSections);
        for (int row = 0; row < totalSections; ++row) {
            controlNet[col][row] = sectionPoints[row][col];
        }
    }

    // TODO: Interpolate across sections (currently placeholder)
}

void SweptSurface::refinePathCurve(const BSplineCurve& curve, int insertCount) {
    BSplineCurve currentCurve = curve;
    for (int i = 0; i < insertCount; ++i) {
        double paramToInsert = findMidpointOfLongestSpan(currentCurve.getKnotVec());
        currentCurve = insertSingleKnot(currentCurve, paramToInsert);
    }
    // Update internal state if needed — currently only used locally in caller
}

double SweptSurface::findMidpointOfLongestSpan(const std::vector<double>& knotVector) const {
    size_t longestSpanIndex = 0;
    double maxSpan = 0.0;

    for (size_t i = 0; i + 1 < knotVector.size(); ++i) {
        double span = knotVector[i + 1] - knotVector[i];
        if (span > maxSpan) {
            maxSpan = span;
            longestSpanIndex = i;
        }
    }

    return (knotVector[longestSpanIndex] + knotVector[longestSpanIndex + 1]) * 0.5;
}

