// Type III clone: Renamed macros and variables, preserved semantics
#define VERIFY_CUDA_TENSOR(t) AT_ASSERTM((t).type().is_cuda(), #t " expected to be on GPU")
#define ENSURE_CONTIGUOUS(t)  AT_ASSERTM((t).is_contiguous(), #t " must be contiguous in memory")
#define VALIDATE_TENSOR(t)     VERIFY_CUDA_TENSOR(t); ENSURE_CONTIGUOUS(t)

#define ENSURE_SHAPE_3D(var, B, H, W, D) \
    AT_ASSERTM(((var).size(0) == (B)) && ((var).size(1) == (H)) && \
               ((var).size(2) == (W)) && ((var).size(3) == (D)), \
               #var " has incorrect spatial dimensions")

#define ENSURE_SHAPE_2D(var, B, F, C) \
    AT_ASSERTM(((var).size(0) == (B)) && ((var).size(1) == (F)) && \
               ((var).size(2) == (C)), \
               #var " has incorrect feature-channel shape")

// Forward declarations (unchanged semantics)
void dr_cuda_forward_batch(
    at::Tensor pts2d_bxfx6,
    at::Tensor dir_bxfx1,
    at::Tensor bbox_bxfx4,
    at::Tensor len_bxfx3,
    at::Tensor lbl_fx2,
    at::Tensor mu_n,
    at::Tensor wei_3vf,
    at::Tensor idx_vf,
    at::Tensor vis_cnt_bxhxwx1,
    at::Tensor first_idx_bxhxwx1,
    at::Tensor img_bxhxwx1,
    int use_vis_cnt,
    float max_sino_value);

void dr_forward_batch(
    at::Tensor pts2d_bxfx6,
    at::Tensor dir_bxfx1,
    at::Tensor bbox_bxfx4,
    at::Tensor len_bxfx3,
    at::Tensor lbl_fx2,
    at::Tensor mu_n,
    at::Tensor wei_3vf,
    at::Tensor idx_vf,
    at::Tensor vis_cnt_bxhxwx1,
    at::Tensor first_idx_bxhxwx1,
    at::Tensor img_bxhxwx1,
    int use_vis_cnt,
    float max_sino_value) {

    VALIDATE_TENSOR(pts2d_bxfx6);
    VALIDATE_TENSOR(dir_bxfx1);
    VALIDATE_TENSOR(bbox_bxfx4);
    VALIDATE_TENSOR(len_bxfx3);
    VALIDATE_TENSOR(lbl_fx2);
    VALIDATE_TENSOR(mu_n);
    // VALIDATE_TENSOR(idx_vf); // commented out as original
    VALIDATE_TENSOR(vis_cnt_bxhxwx1);
    // VALIDATE_TENSOR(wei_3vf); // commented out as original
    VALIDATE_TENSOR(first_idx_bxhxwx1);
    VALIDATE_TENSOR(img_bxhxwx1);

    const auto batch_size = pts2d_bxfx6.size(0);
    const auto num_features = pts2d_bxfx6.size(1);
    const auto height = img_bxhxwx1.size(1);
    const auto width  = img_bxhxwx1.size(2);
    const auto depth  = img_bxhxwx1.size(3);

    ENSURE_SHAPE_2D(pts2d_bxfx6, batch_size, num_features, 6);
    ENSURE_SHAPE_2D(dir_bxfx1, batch_size, num_features, 1);
    ENSURE_SHAPE_2D(bbox_bxfx4, batch_size, num_features, 4);
    ENSURE_SHAPE_2D(len_bxfx3, batch_size, num_features, 3);
    ENSURE_SHAPE_3D(vis_cnt_bxhxwx1, batch_size, height, width, 1);
    ENSURE_SHAPE_3D(img_bxhxwx1, batch_size, height, width, depth);

    dr_cuda_forward_batch(
        pts2d_bxfx6, dir_bxfx1, bbox_bxfx4, len_bxfx3,
        lbl_fx2, mu_n, wei_3vf, idx_vf,
        vis_cnt_bxhxwx1, first_idx_bxhxwx1,
        img_bxhxwx1, use_vis_cnt, max_sino_value);
}

// Backward pass declaration & implementation
void dr_cuda_backward_batch(
    at::Tensor grad_sino_bxhxwxd,
    at::Tensor image_bxhxwxd,
    at::Tensor idx_vf,
    at::Tensor vis_cnt_bxhxwx1,
    at::Tensor first_idx_bxhxwx1,
    at::Tensor wei_3vf,
    at::Tensor pts2d_bxfx6,
    at::Tensor len_bxfx3,
    at::Tensor lbl_fx2,
    at::Tensor mu_n,
    at::Tensor front_facing_bxfx1,
    at::Tensor grad_pts2d_bxfx6,
    at::Tensor grad_len_bxfx3,
    at::Tensor grad_mu_n);

void dr_backward_batch(
    at::Tensor grad_sino_bxhxwxd,
    at::Tensor image_bxhxwxd,
    at::Tensor idx_vf,
    at::Tensor vis_cnt_bxhxwx1,
    at::Tensor first_idx_bxhxwx1,
    at::Tensor wei_3vf,
    at::Tensor pts2d_bxfx6,
    at::Tensor len_bxfx3,
    at::Tensor lbl_fx2,
    at::Tensor mu_n,
    at::Tensor front_facing_bxfx1,
    at::Tensor grad_pts2d_bxfx6,
    at::Tensor grad_len_bxfx3,
    at::Tensor grad_mu_n) {

    VALIDATE_TENSOR(grad_sino_bxhxwxd);
    VALIDATE_TENSOR(image_bxhxwxd);
    VALIDATE_TENSOR(idx_vf);
    VALIDATE_TENSOR(vis_cnt_bxhxwx1);
    VALIDATE_TENSOR(first_idx_bxhxwx1);
    VALIDATE_TENSOR(wei_3vf);
    VALIDATE_TENSOR(pts2d_bxfx6);
    VALIDATE_TENSOR(len_bxfx3);
    VALIDATE_TENSOR(lbl_fx2);
    VALIDATE_TENSOR(mu_n);
    VALIDATE_TENSOR(front_facing_bxfx1);
    VALIDATE_TENSOR(grad_pts2d_bxfx6);
    VALIDATE_TENSOR(grad_len_bxfx3);
    VALIDATE_TENSOR(grad_mu_n);

    const auto batch_size = grad_sino_bxhxwxd.size(0);
    const auto height = grad_sino_bxhxwxd.size(1);
    const auto width  = grad_sino_bxhxwxd.size(2);
    const auto depth  = grad_sino_bxhxwxd.size(3);
    const auto num_features = pts2d_bxfx6.size(1);

    ENSURE_SHAPE_3D(grad_sino_bxhxwxd, batch_size, height, width, depth);
    ENSURE_SHAPE_3D(image_bxhxwxd, batch_size, height, width, depth);
    ENSURE_SHAPE_3D(vis_cnt_bxhxwx1, batch_size, height, width, 1);
    ENSURE_SHAPE_2D(pts2d_bxfx6, batch_size, num_features, 6);
    ENSURE_SHAPE_2D(len_bxfx3, batch_size, num_features, 3);
    ENSURE_SHAPE_2D(front_facing_bxfx1, batch_size, num_features, 1);
    ENSURE_SHAPE_2D(grad_pts2d_bxfx6, batch_size, num_features, 6);
    ENSURE_SHAPE_2D(grad_len_bxfx3, batch_size, num_features, 3);

    dr_cuda_backward_batch(
        grad_sino_bxhxwxd, image_bxhxwxd, idx_vf,
        vis_cnt_bxhxwx1, first_idx_bxhxwx1, wei_3vf,
        pts2d_bxfx6, len_bxfx3, lbl_fx2, mu_n,
        front_facing_bxfx1,
        grad_pts2d_bxfx6, grad_len_bxfx3, grad_mu_n);
}

