#include "scriptengine.hpp"
#include "../tier0/tier0.hpp"
#include "../tier1/tier1.hpp"
#include "classfile.hpp"

namespace scriptengine::jvm {
    using namespace tier0;
    using namespace tier1;
}

namespace scriptengine::jvm {
    void eval(mut_ref<VM> runtime, MethodHandle methodRef, Frame executionFrame) {
        var &bytecodeEvaluator = runtime.evaluator;
        let classHandle = methodRef.handle_;
        let constantPool = classHandle.handle_->constantPool_;
        let currentMethod = classHandle.handle_->methods_.get(methodRef.index_);
        let className = constantPool.getClassName(classHandle.handle_->thisClass_);
        let methodName = constantPool.getName(currentMethod.nameIndex_);
        var methodIdentifier = Tuple(className, methodName);
        (void) methodIdentifier;

        let bytecodeOpt = load_code(runtime, methodRef);
        if (!bytecodeOpt.hasValue()) {
            // native method
            return;
        }

        let bytecode = bytecodeOpt.value();
        var &operandStack = executionFrame.stack;
        var &localVariables = executionFrame.locals;

        operandStack.stack_.ensure(Int(bytecode.maxStack_));
        let localCount = Int(bytecode.maxLocals_);
        localVariables.ensure(localCount);
        localVariables._size(localCount);

        var continueExecution = Boolean(true);
        var unsupportedOperation = [&]() {
            terminate_execution();
        };

        var programCounter = Int(0);
        var branch = [&](Int offset) { programCounter = programCounter + offset - 1; };

        while (continueExecution) {
            let opcode = bytecode.code_.get(programCounter).variant_;

            switch (opcode.index()) {
                case Instruction::Invalid: {
                    terminate_execution();
                }
                case Instruction::athrow: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::monitorenter: {
                    var monitorObject = operandStack.pop().get<Stack::ValueKind::Reference>();
                    (void) monitorObject;
                    break;
                }
                case Instruction::monitorexit: {
                    var monitorObject = operandStack.pop().get<Stack::ValueKind::Reference>();
                    (void) monitorObject;
                    break;
                }
                case Instruction::nop: {
                    break;
                }
                case Instruction::_return: {
                    continueExecution = false;
                    break;
                }
                case Instruction::wide: {
                    unsupportedOperation();
                    break;
                }

                // CLASS operations
                case Instruction::anewarray: {
                    let arrayInstruction = opcode.get<Instruction::anewarray>();
                    var elementCount = operandStack.pop().get<Stack::ValueKind::Int>();
                    let arrayType = constantPool.getClassName(arrayInstruction.index);
                    operandStack.push(bytecodeEvaluator._newarray(runtime, arrayType, elementCount));
                    break;
                }
                case Instruction::arraylength: {
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(bytecodeEvaluator.arraysize(runtime, arrayRef));
                    break;
                }
                case Instruction::checkcast: {
                    var referenceValue = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Reference>(referenceValue));
                    break;
                }
                case Instruction::getfield: {
                    let fieldInstruction = opcode.get<Instruction::getfield>();
                    let fieldRef = constantPool.getAny(fieldInstruction.index).variant_.get<Constant::Fieldref>();
                    let declaringClass = constantPool.getClassName(fieldRef.classIndex);
                    let nameAndType = constantPool.getAny(fieldRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let fieldName = constantPool.getName(nameAndType.nameIndex);
                    let fieldType = constantPool.getName(nameAndType.descriptorIndex);
                    (void) declaringClass;
                    (void) fieldType;
                    var receiver = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(bytecodeEvaluator.getinstance(runtime, receiver, fieldName));
                    break;
                }
                case Instruction::getstatic: {
                    let staticInstruction = opcode.get<Instruction::getstatic>();
                    let fieldRef = constantPool.getAny(staticInstruction.index).variant_.get<Constant::Fieldref>();
                    let declaringClass = constantPool.getClassName(fieldRef.classIndex);
                    let nameAndType = constantPool.getAny(fieldRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let fieldName = constantPool.getName(nameAndType.nameIndex);
                    let fieldType = constantPool.getName(nameAndType.descriptorIndex);
                    (void) fieldType;
                    operandStack.push(bytecodeEvaluator.getstatic(runtime, declaringClass, fieldName));
                    break;
                }
                case Instruction::instanceof: {
                    var referenceValue = operandStack.pop().get<Stack::ValueKind::Reference>();
                    (void) referenceValue;
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(1));
                    break;
                }
                case Instruction::multianewarray: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::_new: {
                    let newInstruction = opcode.get<Instruction::_new>();
                    let className = constantPool.getClassName(newInstruction.index);
                    operandStack.push(bytecodeEvaluator._new(runtime, className));
                    break;
                }
                case Instruction::newarray: {
                    let arrayTypeInstruction = opcode.get<Instruction::newarray>();
                    var primitiveType = arrayTypeInstruction.atype;
                    (void) primitiveType;
                    var elementCount = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(bytecodeEvaluator._newarray(runtime, "<primitive>", elementCount));
                    break;
                }
                case Instruction::putfield: {
                    let putFieldInstruction = opcode.get<Instruction::putfield>();
                    let fieldRef = constantPool.getAny(putFieldInstruction.index).variant_.get<Constant::Fieldref>();
                    let declaringClass = constantPool.getClassName(fieldRef.classIndex);
                    let nameAndType = constantPool.getAny(fieldRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let fieldName = constantPool.getName(nameAndType.nameIndex);
                    let fieldType = constantPool.getName(nameAndType.descriptorIndex);
                    (void) declaringClass;
                    (void) fieldType;
                    var value = operandStack.pop();
                    var receiver = operandStack.pop().get<Stack::ValueKind::Reference>();
                    bytecodeEvaluator.putinstance(runtime, receiver, move(fieldName), move(value));
                    break;
                }
                case Instruction::putstatic: {
                    let putStaticInstruction = opcode.get<Instruction::putstatic>();
                    let fieldRef = constantPool.getAny(putStaticInstruction.index).variant_.get<Constant::Fieldref>();
                    let declaringClass = constantPool.getClassName(fieldRef.classIndex);
                    let nameAndType = constantPool.getAny(fieldRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let fieldName = constantPool.getName(nameAndType.nameIndex);
                    let fieldType = constantPool.getName(nameAndType.descriptorIndex);
                    (void) fieldType;
                    bytecodeEvaluator.putstatic(runtime, declaringClass, fieldName, operandStack.pop());
                    break;
                }

                // INVOKE operations
                case Instruction::invokedynamic: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::invokeinterface: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::invokespecial: {
                    let invokeSpecialInstruction = opcode.get<Instruction::invokespecial>();
                    let methodRef = constantPool.getAny(invokeSpecialInstruction.index).variant_.get<Constant::Methodref>();
                    let declaringClass = constantPool.getClassName(methodRef.classIndex);
                    let nameAndType = constantPool.getAny(methodRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let methodName = constantPool.getName(nameAndType.nameIndex);
                    let methodSignature = constantPool.getName(nameAndType.descriptorIndex);
                    bytecodeEvaluator.invokespecial(
                            runtime,
                            declaringClass, methodName, methodSignature,
                            executionFrame
                    );
                    break;
                }
                case Instruction::invokestatic: {
                    let invokeStaticInstruction = opcode.get<Instruction::invokestatic>();
                    let methodRef = constantPool.getAny(invokeStaticInstruction.index).variant_.get<Constant::Methodref>();
                    let declaringClass = constantPool.getClassName(methodRef.classIndex);
                    let nameAndType = constantPool.getAny(methodRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let methodName = constantPool.getName(nameAndType.nameIndex);
                    let methodSignature = constantPool.getName(nameAndType.descriptorIndex);
                    bytecodeEvaluator.invokestatic(
                            runtime,
                            declaringClass, methodName, methodSignature,
                            executionFrame
                    );
                    break;
                }
                case Instruction::invokevirtual: {
                    let invokeVirtualInstruction = opcode.get<Instruction::invokevirtual>();
                    let methodRef = constantPool.getAny(invokeVirtualInstruction.index).variant_.get<Constant::Methodref>();
                    let declaringClass = constantPool.getClassName(methodRef.classIndex);
                    let nameAndType = constantPool.getAny(methodRef.nameAndTypeIndex).variant_.get<Constant::NameAndType>();
                    let methodName = constantPool.getName(nameAndType.nameIndex);
                    let methodSignature = constantPool.getName(nameAndType.descriptorIndex);
                    bytecodeEvaluator.invokevirtual(
                            runtime,
                            declaringClass, methodName, methodSignature,
                            executionFrame
                    );
                    break;
                }

                // STACK operations
                case Instruction::dup: {
                    operandStack.push(operandStack.peek().copy());
                    break;
                }
                case Instruction::dup_x1: {
                    var topValue = operandStack.pop();
                    var secondValue = operandStack.pop();
                    operandStack.push(topValue.copy());
                    operandStack.push(move(secondValue));
                    operandStack.push(move(topValue));
                    break;
                }
                case Instruction::dup_x2: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::dup2: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::dup2_x1: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::dup2_x2: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::ldc:
                case Instruction::ldc_w: {
                    var index = opcode.index() == Instruction::ldc
                                ? UShort(opcode.get<Instruction::ldc>().index)
                                : UShort(opcode.get<Instruction::ldc_w>().index);
                    let constantEntry = constantPool.getAny(index);
                    var tag = constantEntry.variant_.index();
                    if (tag == Constant::String) {
                        let stringConstant = constantEntry.variant_.get<Constant::String>();
                        let stringValue = constantPool.getName(stringConstant.stringIndex);
                        var charArray = bytecodeEvaluator._newarray(runtime, "<primitive>", stringValue.size()).get<Stack::ValueKind::Reference>();
                        for (let position : Range<Int>::until(0, stringValue.size())) {
                            bytecodeEvaluator.arrayset(runtime, charArray, position,
                                               Stack::Value::of<Stack::ValueKind::Int>(Int(stringValue.data_.get(position))));
                        }
                        var stringInstance = bytecodeEvaluator._new(runtime, "java/lang/String").get<Stack::ValueKind::Reference>();
                        bytecodeEvaluator.putinstance(runtime, stringInstance, "value", Stack::Value::of<Stack::ValueKind::Reference>(charArray));
                        operandStack.push(Stack::Value::of<Stack::ValueKind::Reference>(stringInstance));
                    } else {
                        operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(0));
                    }
                    break;
                }
                case Instruction::ldc2_w: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::pop: {
                    operandStack.pop();
                    break;
                }
                case Instruction::swap: {
                    var firstValue = operandStack.pop();
                    var secondValue = operandStack.pop();
                    operandStack.push(move(firstValue));
                    operandStack.push(move(secondValue));
                    break;
                }

                // BRANCH operations
                case Instruction::_goto: {
                    let gotoInstruction = opcode.get<Instruction::_goto>();
                    branch(Int(gotoInstruction.branch));
                    break;
                }
                case Instruction::goto_w: {
                    let wideGotoInstruction = opcode.get<Instruction::goto_w>();
                    branch(Int(wideGotoInstruction.branch));
                    break;
                }
                case Instruction::if_acmpeq: {
                    let ifEqInstruction = opcode.get<Instruction::if_acmpeq>();
                    var secondRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    var firstRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    if (firstRef == secondRef) {
                        branch(Int(ifEqInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_acmpne: {
                    let ifNeInstruction = opcode.get<Instruction::if_acmpne>();
                    var secondRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    var firstRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    if (firstRef != secondRef) {
                        branch(Int(ifNeInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_icmpeq: {
                    let ifIntEqInstruction = opcode.get<Instruction::if_icmpeq>();
                    var secondInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    if (firstInt == secondInt) {
                        branch(Int(ifIntEqInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_icmpge: {
                    let ifGeInstruction = opcode.get<Instruction::if_icmpge>();
                    var secondInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    if (firstInt >= secondInt) {
                        branch(Int(ifGeInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_icmpgt: {
                    let ifGtInstruction = opcode.get<Instruction::if_icmpgt>();
                    var secondInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    if (firstInt > secondInt) {
                        branch(Int(ifGtInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_icmple: {
                    let ifLeInstruction = opcode.get<Instruction::if_icmple>();
                    var secondInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    if (firstInt <= secondInt) {
                        branch(Int(ifLeInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_icmplt: {
                    let ifLtInstruction = opcode.get<Instruction::if_icmplt>();
                    var secondInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    if (firstInt < secondInt) {
                        branch(Int(ifLtInstruction.branch));
                    }
                    break;
                }
                case Instruction::if_icmpne: {
                    let ifIntNeInstruction = opcode.get<Instruction::if_icmpne>();
                    var secondInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstInt = operandStack.pop().get<Stack::ValueKind::Int>();
                    if (firstInt != secondInt) {
                        branch(Int(ifIntNeInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifeq: {
                    let ifZeroInstruction = opcode.get<Instruction::ifeq>();
                    var value = operandStack.pop();
                    var intValue = value.get<Stack::ValueKind::Int>();
                    if (intValue == Int(0)) {
                        branch(Int(ifZeroInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifge: {
                    let ifNonNegativeInstruction = opcode.get<Instruction::ifge>();
                    var value = operandStack.pop();
                    var intValue = value.get<Stack::ValueKind::Int>();
                    if (intValue >= Int(0)) {
                        branch(Int(ifNonNegativeInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifgt: {
                    let ifPositiveInstruction = opcode.get<Instruction::ifgt>();
                    var value = operandStack.pop();
                    var intValue = value.get<Stack::ValueKind::Int>();
                    if (intValue > Int(0)) {
                        branch(Int(ifPositiveInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifle: {
                    let ifNonPositiveInstruction = opcode.get<Instruction::ifle>();
                    var value = operandStack.pop();
                    var intValue = value.get<Stack::ValueKind::Int>();
                    if (intValue <= Int(0)) {
                        branch(Int(ifNonPositiveInstruction.branch));
                    }
                    break;
                }
                case Instruction::iflt: {
                    let ifNegativeInstruction = opcode.get<Instruction::iflt>();
                    var value = operandStack.pop();
                    var intValue = value.get<Stack::ValueKind::Int>();
                    if (intValue < Int(0)) {
                        branch(Int(ifNegativeInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifne: {
                    let ifNotZeroInstruction = opcode.get<Instruction::ifne>();
                    var value = operandStack.pop();
                    var intValue = value.get<Stack::ValueKind::Int>();
                    if (intValue != Int(0)) {
                        branch(Int(ifNotZeroInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifnonnull: {
                    let ifNotNullInstruction = opcode.get<Instruction::ifnonnull>();
                    var isNotNull = Boolean(false);
                    var value = operandStack.pop();
                    switch (value.index()) {
                        case Stack::ValueKind::Reference: {
                            let refValue = value.get<Stack::ValueKind::Reference>();
                            isNotNull = refValue.value() != nullptr;
                            break;
                        }
                        case Stack::ValueKind::Invalid:
                        case Stack::ValueKind::Int:
                        case Stack::ValueKind::Long: {
                            terminate_execution();
                        }
                    }
                    if (isNotNull) {
                        branch(Int(ifNotNullInstruction.branch));
                    }
                    break;
                }
                case Instruction::ifnull: {
                    let ifNullInstruction = opcode.get<Instruction::ifnull>();
                    var isNull = Boolean(false);
                    var value = operandStack.pop();
                    switch (value.index()) {
                        case Stack::ValueKind::Reference: {
                            let refValue = value.get<Stack::ValueKind::Reference>();
                            isNull = refValue.value() == nullptr;
                            break;
                        }
                        case Stack::ValueKind::Invalid:
                        case Stack::ValueKind::Int:
                        case Stack::ValueKind::Long: {
                            terminate_execution();
                        }
                    }
                    if (isNull) {
                        branch(Int(ifNullInstruction.branch));
                    }
                    break;
                }
                case Instruction::jsr: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::jsr_w: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::lookupswitch: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::ret: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::tableswitch: {
                    unsupportedOperation();
                    break;
                }

                // REFERENCE operations
                case Instruction::aaload: {
                    var index = operandStack.pop().get<Stack::ValueKind::Int>();
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(bytecodeEvaluator.arrayget(runtime, arrayRef, index));
                    break;
                }
                case Instruction::aastore: {
                    var value = operandStack.pop();
                    var index = operandStack.pop().get<Stack::ValueKind::Int>();
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    bytecodeEvaluator.arrayset(runtime, arrayRef, index, move(value));
                    break;
                }
                case Instruction::aconst_null: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(0));
                    break;
                }
                case Instruction::aload: {
                    let loadInstruction = opcode.get<Instruction::aload>();
                    operandStack.push(localVariables.get(Int(loadInstruction.index)).copy());
                    break;
                }
                case Instruction::aload_0: {
                    operandStack.push(localVariables.get(0).copy());
                    break;
                }
                case Instruction::aload_1: {
                    operandStack.push(localVariables.get(1).copy());
                    break;
                }
                case Instruction::aload_2: {
                    operandStack.push(localVariables.get(2).copy());
                    break;
                }
                case Instruction::aload_3: {
                    operandStack.push(localVariables.get(3).copy());
                    break;
                }
                case Instruction::areturn: {
                    var result = operandStack.pop();
                    var &callerFrame = *executionFrame.parent.value();
                    callerFrame.stack.push(move(result));
                    continueExecution = false;
                    break;
                }
                case Instruction::astore: {
                    let storeInstruction = opcode.get<Instruction::astore>();
                    localVariables.set(Int(storeInstruction.index), operandStack.pop());
                    break;
                }
                case Instruction::astore_0: {
                    localVariables.set(0, operandStack.pop());
                    break;
                }
                case Instruction::astore_1: {
                    localVariables.set(1, operandStack.pop());
                    break;
                }
                case Instruction::astore_2: {
                    localVariables.set(2, operandStack.pop());
                    break;
                }
                case Instruction::astore_3: {
                    localVariables.set(3, operandStack.pop());
                    break;
                }

                // BYTE operations
                case Instruction::baload: {
                    var index = operandStack.pop().get<Stack::ValueKind::Int>();
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(bytecodeEvaluator.arrayget(runtime, arrayRef, index));
                    break;
                }
                case Instruction::bastore: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::bipush: {
                    let pushByteInstruction = opcode.get<Instruction::bipush>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(Int(pushByteInstruction.value)));
                    break;
                }

                // CHAR operations
                case Instruction::caload: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::castore: {
                    unsupportedOperation();
                    break;
                }

                // SHORT operations
                case Instruction::saload: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::sastore: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::sipush: {
                    let pushShortInstruction = opcode.get<Instruction::sipush>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(Int(pushShortInstruction.value)));
                    break;
                }

                // INT conversions
                case Instruction::i2b: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::i2c: {
                    var value = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(Int(UShort(value))));
                    break;
                }
                case Instruction::i2d: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::i2f: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::i2l: {
                    var value = operandStack.pop().get<Stack::ValueKind::Long>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Long>(Long(value)));
                    break;
                }
                case Instruction::i2s: {
                    var value = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(Int(Short(value))));
                    break;
                }
                case Instruction::iadd: {
                    var secondOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(firstOperand + secondOperand));
                    break;
                }
                case Instruction::iaload: {
                    var index = operandStack.pop().get<Stack::ValueKind::Int>();
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    operandStack.push(bytecodeEvaluator.arrayget(runtime, arrayRef, index));
                    break;
                }
                case Instruction::iand: {
                    var secondOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(firstOperand & secondOperand));
                    break;
                }
                case Instruction::iastore: {
                    var value = operandStack.pop();
                    var index = operandStack.pop().get<Stack::ValueKind::Int>();
                    var arrayRef = operandStack.pop().get<Stack::ValueKind::Reference>();
                    bytecodeEvaluator.arrayset(runtime, arrayRef, index, move(value));
                    break;
                }
                case Instruction::iconst_0: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(0));
                    break;
                }
                case Instruction::iconst_1: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(1));
                    break;
                }
                case Instruction::iconst_2: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(2));
                    break;
                }
                case Instruction::iconst_3: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(3));
                    break;
                }
                case Instruction::iconst_4: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(4));
                    break;
                }
                case Instruction::iconst_5: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(5));
                    break;
                }
                case Instruction::iconst_m1: {
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(-1));
                    break;
                }
                case Instruction::idiv: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::iinc: {
                    let incrementInstruction = opcode.get<Instruction::iinc>();
                    localVariables.set(
                            Int(incrementInstruction.index),
                            Stack::Value::of<Stack::ValueKind::Int>(
                                    localVariables.get(Int(incrementInstruction.index)).get<Stack::ValueKind::Int>()
                                    + Int(incrementInstruction.value)
                            )
                    );
                    break;
                }
                case Instruction::iload: {
                    let loadInstruction = opcode.get<Instruction::iload>();
                    operandStack.push(localVariables.get(Int(loadInstruction.index)).copy());
                    break;
                }
                case Instruction::iload_0: {
                    operandStack.push(localVariables.get(0).copy());
                    break;
                }
                case Instruction::iload_1: {
                    operandStack.push(localVariables.get(1).copy());
                    break;
                }
                case Instruction::iload_2: {
                    operandStack.push(localVariables.get(2).copy());
                    break;
                }
                case Instruction::iload_3: {
                    operandStack.push(localVariables.get(3).copy());
                    break;
                }
                case Instruction::imul: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::ineg: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::ior: {
                    var secondOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(firstOperand | secondOperand));
                    break;
                }
                case Instruction::irem: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::ireturn: {
                    var result = operandStack.pop();
                    var &callerFrame = *executionFrame.parent.value();
                    callerFrame.stack.push(move(result));
                    continueExecution = false;
                    break;
                }
                case Instruction::ishl: {
                    var shiftAmount = operandStack.pop().get<Stack::ValueKind::Int>();
                    var value = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(value << shiftAmount));
                    break;
                }
                case Instruction::ishr: {
                    var shiftAmount = operandStack.pop().get<Stack::ValueKind::Int>();
                    var value = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(value >> shiftAmount));
                    break;
                }
                case Instruction::istore: {
                    let storeInstruction = opcode.get<Instruction::istore>();
                    localVariables.set(Int(storeInstruction.index), operandStack.pop());
                    break;
                }
                case Instruction::istore_0: {
                    localVariables.set(0, operandStack.pop());
                    break;
                }
                case Instruction::istore_1: {
                    localVariables.set(1, operandStack.pop());
                    break;
                }
                case Instruction::istore_2: {
                    localVariables.set(2, operandStack.pop());
                    break;
                }
                case Instruction::istore_3: {
                    localVariables.set(3, operandStack.pop());
                    break;
                }
                case Instruction::isub: {
                    var secondOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    var firstOperand = operandStack.pop().get<Stack::ValueKind::Int>();
                    operandStack.push(Stack::Value::of<Stack::ValueKind::Int>(firstOperand - secondOperand));
                    break;
                }
                case Instruction::iushr: {
                    unsupportedOperation();
                    break;
                }
                case Instruction::ixor: {
                    unsupportedOperation();
                    break;
                }

                // LONG operations
                case Instruction::l2d:
                case Instruction::l2f:
                case Instruction::l2i:
                case Instruction::ladd:
