#include "network_packets.h"

// -------------------- NetworkPacket --------------------------
// serialization
Packet::Packet(int32_t packet_id, uint32_t packet_flag, int extra_size) 
  : id(packet_id), flag(packet_flag), packet_size(extra_size + header_size) {
  packet = (char*)malloc(packet_size);
  std::cout << "Packet Created: size: " << packet_size << std::endl;

  // Initialize header fields
  uint32_t* header_ptr = reinterpret_cast<uint32_t*>(packet);
  header_ptr[0] = packet_size;
  header_ptr[1] = id;
  header_ptr[2] = flag;
}

// deserialization
Packet::Packet(void* buffer, ssize_t total_size) 
  : packet(buffer), packet_size(total_size) {
  uint32_t* header_data = static_cast<uint32_t*>(buffer);
  packet_size = header_data[0];
  id = *reinterpret_cast<int32_t*>(header_data + 1);
  flag = header_data[2];
}

Packet::~Packet() {
  free(packet);
}

int Packet::dataSize() const {
  return header_size;
}

std::ostream& Packet::print(std::ostream& stream) const {
  stream << "Packet" << std::endl;
  stream << "\tpacket_size: " << packet_size << std::endl;
  stream << "\tid: " << id << std::endl;
  stream << "\tflag: " << flag << std::endl;
  return stream; 
}

std::ostream& operator<<(std::ostream& stream, const Packet &p) {
  return p.print(stream); 
}

