EspressoInit::EspressoInit(void* buffer, ssize_t buf_size) : Packet(buffer, buf_size) {
  uint8_t* base_addr = static_cast<uint8_t*>(buffer) + Packet::dataSize();
  node_id = *reinterpret_cast<uint32_t*>(base_addr);
}

EspressoInit::EspressoInit(int node_identifier) 
  : Packet(0, ESPRESSO_INIT, data_size), node_id(node_identifier) {
  uint8_t* payload = static_cast<uint8_t*>(packet) + Packet::dataSize();
  *reinterpret_cast<uint32_t*>(payload) = node_id;
}

std::ostream& EspressoInit::print(std::ostream& stream) const {
  stream << "EspressoInitializationPacket" << std::endl;
  stream << "\tnode_id: " << node_id << std::endl;
  return Packet::print(stream); 
}

std::ostream& operator<<(std::ostream& stream, const EspressoInit &p) {
  return p.print(stream); 
