// ---------------------- FilePacket --------------------
FilePacket::FilePacket(uint32_t pkt_id, int pkt_flag, int extra_bytes,
                       uint32_t file_descriptor, uint32_t file_identity,
                       uint32_t stripe_number, uint32_t chunk_index,
                       uint32_t byte_offset, int32_t byte_count) 
  : Packet(pkt_id, pkt_flag, extra_bytes + data_size),
    fd(file_descriptor),
    file_id(file_identity),
    stripe_id(stripe_number),
    chunk_num(chunk_index),
    offset(byte_offset),
    count(byte_count) {
  uint8_t* payload = static_cast<uint8_t*>(packet) + Packet::dataSize();
  uint32_t* payload_words = reinterpret_cast<uint32_t*>(payload);
  payload_words[0] = fd;
  payload_words[1] = file_id;
  payload_words[2] = stripe_id;
  payload_words[3] = chunk_num;
  payload_words[4] = offset;
  payload_words[5] = count;
}

FilePacket::FilePacket(void* buffer, ssize_t buf_size) : Packet(buffer, buf_size) {
  uint8_t* payload = static_cast<uint8_t*>(buffer) + Packet::dataSize();
  uint32_t* payload_words = reinterpret_cast<uint32_t*>(payload);
  fd = payload_words[0];
  file_id = payload_words[1];
  stripe_id = payload_words[2];
  chunk_num = payload_words[3];
  offset = payload_words[4];
  count = payload_words[5];
}

int FilePacket::dataSize() const {
  return Packet::dataSize() + data_size;
}

std::ostream& FilePacket::print(std::ostream& stream) const {
  stream << "FilePacket" << std::endl;
  stream << "\tfd: " << fd << std::endl;
  stream << "\tfile_id: " << file_id << std::endl;
  stream << "\tstripe_id: " << stripe_id << std::endl;
  stream << "\tchunk_num: " << chunk_num << std::endl;
  stream << "\toffset: " << offset << std::endl;
  stream << "\tcount: " << count << std::endl;
  return Packet::print(stream);
}

std::ostream& operator<<(std::ostream& stream, const FilePacket &pkt) {
  return pkt.print(stream);
}

// ---------------------- FileDataPacket ------------
FileDataPacket::FileDataPacket(void* buffer, ssize_t buf_size) : FilePacket(buffer, buf_size) {
  if (count > 0) {
    data_buffer = static_cast<uint8_t*>(buffer) + FilePacket::dataSize();
  } else {
    data_buffer = nullptr;
  }
}

FileDataPacket::FileDataPacket(uint32_t pkt_id, int pkt_flag, int extra_bytes,
                               uint32_t file_descriptor, uint32_t file_identity,
                               uint32_t stripe_number, uint32_t chunk_index,
                               uint32_t byte_offset, int32_t byte_count,
                               const uint8_t* source_data) 
  : FilePacket(pkt_id, pkt_flag, std::max(0, byte_count), 
               file_descriptor, file_identity, stripe_number, chunk_index, 
               byte_offset, byte_count) {
  data_buffer = static_cast<uint8_t*>(packet) + FilePacket::dataSize();
  if (byte_count > 0 && source_data != nullptr) {
    std::memcpy(data_buffer, source_data, static_cast<size_t>(byte_count));
  }
}

int FileDataPacket::dataSize() const {
  return FilePacket::dataSize() + data_size;
}

std::ostream& FileDataPacket::print(std::ostream& stream) const {
  stream << "FileDataPacket" << std::endl;
  stream << "data_buffer: ";
  if (data_buffer) {
    stream.write(reinterpret_cast<const char*>(data_buffer), count);
  } else {
    stream << "<NULL>";
  }
  stream << std::endl;
  return FilePacket::print(stream);
}

std::ostream& operator<<(std::ostream& stream, const FileDataPacket &pkt) {
  return pkt.print(stream);
}

