#include "include/libcolor/libcolor.hpp"
#include <string>
#include <cstdio>

using namespace LibColor;

int main() {
    // Display color parsed from short hex string '#123'
    std::printf("Color from '#123'\n");
    auto color1 = Color::fromHexString("#123");
    std::printf("  RGB: %d, %d, %d\n", color1.red(), color1.green(), color1.blue());
    std::printf("  HSV: %.6f, %.6f, %.6f\n", color1.h, color1.s, color1.v);
    std::printf("  HEX: %s\n", color1.hex().c_str());

    // Display color parsed from web name 'pink'
    std::printf("\nColor from 'pink'\n");
    auto color2 = Color::fromWebName("pink");
    std::printf("  RGB: %d, %d, %d\n", color2.red(), color2.green(), color2.blue());
    std::printf("  HSV: %.6f, %.6f, %.6f\n", color2.h, color2.s, color2.v);
    std::printf("  HEX: %s\n", color2.hex().c_str());

    // Blend white and black with default factor (0.5)
    std::printf("\nBlend #fff color with #000 (k = 0.5)\n");
    auto light = Color::fromHexString("#ffffff");
    auto dark = Color::fromHexString("#000");
    light.blend(dark);  // uses default blending factor 0.5
    std::printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
    std::printf("  HSV: %.6f, %.6f, %.6f\n", light.h, light.s, light.v);
    std::printf("  HEX: %s\n", light.hex().c_str());

    // Blend white and black with full weight of dark (k = 1)
    std::printf("\nBlend #fff color with #000 (k = 1)\n");
    light = Color::fromHexString("#ffffff");
    light.blend(dark, 1.0f);
    std::printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
    std::printf("  HSV: %.6f, %.6f, %.6f\n", light.h, light.s, light.v);
    std::printf("  HEX: %s\n", light.hex().c_str());

    // Rotate hue in steps of 72 degrees (360/5) starting from red
    std::printf("\nRotate hue from red to red\n");
    light = Color::fromHexString("#ff0000");
    std::printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
    std::printf("  HSV: %.6f, %.6f, %.6f\n", light.h, light.s, light.v);
    std::printf("  HEX: %s\n", light.hex().c_str());

    for (int step = 0; step < 5; ++step) {
        float currentHue = light.hue();
        light.hue(currentHue + 360.0f / 5.0f);
        std::printf("  RGB: %d, %d, %d\n", light.red(), light.green(), light.blue());
        std::printf("  HSV: %.6f, %.6f, %.6f\n", light.h, light.s, light.v);
        std::printf("  HEX: %s\n", light.hex().c_str());
    }

    return 0;
}

