// Helper to extract numeric value from Val as double
double getNumericValue(Val v) {
    if (isVal<IntVal>(v)) {
        return static_cast<double>(static_cast<IntVal*>(v)->get());
    } else if (isVal<RealVal>(v)) {
        return static_cast<double>(static_cast<RealVal*>(v)->get());
    }
    throw_err("type", "Expected numeric argument");
    return 0.0;
}

auto std_rand_uniform = [](Env env) -> Val {
    Val paramA = env->apply("lower_bound");
    if (!val_is_number(paramA)) {
        throw_err("type", "random.uniform : R -> R -> R expects real numbers; got " + paramA->toString());
        return nullptr;
    }

    Val paramB = env->apply("upper_bound");
    if (!val_is_number(paramB)) {
        throw_err("type", "random.uniform : R -> R -> R expects real numbers; got " + paramB->toString());
        return nullptr;
    }

    double lower = getNumericValue(paramA);
    double upper = getNumericValue(paramB);

    // Ensure lower <= upper
    if (lower > upper) {
        std::swap(lower, upper);
    }

    static std::mt19937 gen(std::random_device{}());
    std::uniform_real_distribution<double> dist(lower, upper);
    double result = dist(gen);

    return new RealVal(static_cast<float>(result));
};

auto std_rand_normal = [](Env env) -> Val {
    Val meanVal = env->apply("mean");
    if (!val_is_number(meanVal)) {
        throw_err("type", "random.normal : R -> R -> R expects real numbers; got " + meanVal->toString());
        return nullptr;
    }

    Val stddevVal = env->apply("stddev");
    if (!val_is_number(stddevVal)) {
        throw_err("type", "random.normal : R -> R -> R expects real numbers; got " + stddevVal->toString());
        return nullptr;
    }

    double mean = getNumericValue(meanVal);
    double stddev = std::abs(getNumericValue(stddevVal)); // ensure non-negative

    static std::mt19937 rng(std::random_device{}());
    std::normal_distribution<double> normDist(mean, stddev);
    double sample = normDist(rng);

    return new RealVal(static_cast<float>(sample));
};

Type* type_stdlib_random() {
    return new DictType {
        {
            "uniform",
            new LambdaType("lower",
                new RealType,
                new LambdaType("upper",
                    new RealType,
                    new RealType))
        },
        {
            "normal",
            new LambdaType("mean",
                new RealType,
                new LambdaType("stddev",
                    new RealType,
                    new RealType))
        }
    };
}

Val load_stdlib_random() {
    return new DictVal {
        {
            "uniform",
            new LambdaVal(new std::string[3]{"lower", "upper", ""},
                new ImplementExp(std_rand_uniform, nullptr))
        },
        {
            "normal",
            new LambdaVal(new std::string[3]{"mean", "stddev", ""},
                new ImplementExp(std_rand_normal, nullptr))
        }
    };
}

#include "memory.h"

// Copies count bytes from source to destination
void* memcpy(void* dest, const void* src, size_t count)
{
    const unsigned char* source = static_cast<const unsigned char*>(src);
    unsigned char* destination = static_cast<unsigned char*>(dest);

    while (count > 0) {
        *destination++ = *source++;
        --count;
    }
    return dest;
}

// Compares first n bytes of two memory blocks
int memcmp(const void* s1, const void* s2, size_t n)
{
    const unsigned char* p1 = static_cast<const unsigned char*>(s1);
    const unsigned char* p2 = static_cast<const unsigned char*>(s2);

    for (size_t i = 0; i < n; ++i) {
        if (p1[i] != p2[i]) {
            return p1[i] - p2[i];
        }
    }
    return 0;
}

// Fills first n bytes of memory block with specified value
void* memset(void* dest, int val, size_t count)
{
    unsigned char* ptr = static_cast<unsigned char*>(dest);
    unsigned char byte_val = static_cast<unsigned char>(val);

    for (size_t i = 0; i < count; ++i) {
        ptr[i] = byte_val;
    }
    return dest;
}

// Copies n bytes from src to dest, handling overlapping regions safely
void* memmove(void* dest, void* src, size_t n)
{
    unsigned char* d = static_cast<unsigned char*>(dest);
    const unsigned char* s = static_cast<const unsigned char*>(src);

    // No action needed if pointers are equal
    if (d == s) {
        return dest;
    }

    // Copy in forward direction if no overlap or src is after dest
    if (s > d || (s + n <= d)) {
        for (size_t i = 0; i < n; ++i) {
            d[i] = s[i];
        }
    } 
    // Copy in backward direction when src is before dest and they overlap
    else {
        for (size_t i = n; i > 0; --i) {
            d[i - 1] = s[i - 1];
        }
    }

    return dest;
}

// Searches for first occurrence of character c in first n bytes of s
void* memchr(const void* s, int c, size_t n)
{
    const unsigned char* p = static_cast<const unsigned char*>(s);
    unsigned char target = static_cast<unsigned char>(c);

    for (size_t i = 0; i < n; ++i) {
        if (p[i] == target) {
            return const_cast<unsigned char*>(p + i);
        }
    }
    return nullptr;
}

