TEST(NonceGeneration, generateNonces) {
  std::set<std::string> uniqueNonces;
  const int nonceCount = 100;
  for (int i=0; i < nonceCount; ++i) {
    uniqueNonces.insert(Nonce::nonce());
  }
  // Verify no duplicate nonces were generated
  ASSERT_EQ(uniqueNonces.size(), nonceCount);
  for (std::set<std::string>::iterator iter = uniqueNonces.begin();
                                       iter != uniqueNonces.end();
                                       ++iter) {
    ASSERT_TRUE(iter->size() > 0);
    ASSERT_TRUE(iter->size() <= 128);
  }
}

TEST(NonceGeneration, updateInputParameters) {
  JSON inputParams(JSON_OBJECT);
  inputParams["param1"] = "value1";
  inputParams["param2"] = "value2";
  JSON updatedInput = Nonce::updateNonce(inputParams);

  ASSERT_EQ(inputParams["param1"], updatedInput["param1"]);
  ASSERT_EQ(inputParams["param2"], updatedInput["param2"]);
  ASSERT_TRUE(updatedInput.has("nonce"));

  std::string generatedNonce = updatedInput["nonce"].get<string>();
  ASSERT_TRUE(generatedNonce.size() > 0);
  ASSERT_TRUE(generatedNonce.size() <= 128);

  std::string existingNonce = Nonce::nonce();
  inputParams["nonce"] = existingNonce;
  updatedInput = Nonce::updateNonce(inputParams);

  ASSERT_EQ(inputParams["param1"], updatedInput["param1"]);
  ASSERT_EQ(inputParams["param2"], updatedInput["param2"]);
  ASSERT_TRUE(updatedInput.has("nonce"));
  generatedNonce = updatedInput["nonce"].get<string>();
  ASSERT_EQ(existingNonce, generatedNonce);
  ASSERT_TRUE(generatedNonce.size() > 0);
  ASSERT_TRUE(generatedNonce.size() <= 128);
}

