// Verify that repeated API calls with same parameters produce identical responses
void verifyEqualResponses(JSON (*apiFunction)(const dx::JSON &, const bool), 
                         const JSON &parameters, 
                         const bool retryAllowed=false) {
  JSON firstResponse =  (*apiFunction)(parameters, retryAllowed);
  JSON secondResponse =  (*apiFunction)(parameters, retryAllowed);
  ASSERT_EQ(firstResponse, secondResponse);
}

void verifyEqualResponses(JSON (*apiFunction)(const string &, const dx::JSON &, const bool),
                         const string& objectId, 
                         const JSON &parameters, 
                         const bool retryAllowed=false) {
  JSON firstResponse =  (*apiFunction)(objectId, parameters, retryAllowed);
  JSON secondResponse =  (*apiFunction)(objectId, parameters, retryAllowed);
  ASSERT_EQ(firstResponse, secondResponse);
}

static const std::string nonceErrorString =
  "InvalidInput: 'Nonce was reused for an earlier API request that had a different input', Server returned HTTP code '422'";

// Verify that reusing a nonce with different input throws an error
void verifyNonceReuseViolation(JSON (*apiFunction)(const dx::JSON &, const bool), 
                              const JSON &parameters, 
                              const bool retryAllowed=false) {
  try {
    (*apiFunction)(parameters, retryAllowed);
    ASSERT_THROW((*apiFunction)(parameters, retryAllowed), DXAPIError);
  } catch(DXAPIError &error) {
    ASSERT_EQ(error.resp_code, 422);
    ASSERT_EQ(std::string(error.what()), nonceErrorString);
  }
}

void verifyNonceReuseViolation(JSON (*apiFunction)(const string &, const dx::JSON &, const bool),
                              const string& objectId, 
                              const JSON &parameters, 
                              const bool retryAllowed=false) {
  try {
    (*apiFunction)(objectId, parameters, retryAllowed);
    ASSERT_THROW((*apiFunction)(objectId, parameters, retryAllowed), DXAPIError);
  } catch(DXAPIError &error) {
    ASSERT_EQ(error.resp_code, 422);
    ASSERT_EQ(std::string(error.what()), nonceErrorString);
  }
}

