  for (int i = 0; i < file_size; ++i)
    lf<<"$";
  lf.close();

  DXFile dxf = DXFile::uploadLocalFile(fname);
  dxf.waitOnClose();

  char fname2[L_tmpnam];
  ASSERT_STRNE(NULL, tmpnam(fname2));
