  // Reserve memory for string upfront (to avoid having reallocation multiple time)
  fp.seekg(0, ios::end);
  ASSERT_EQ(file_size, fp.tellg());
  fp.seekg(0, ios::beg);
  int count = 0;
  while (fp.good()) {
    char ch = fp.get();
    if (fp.eof())
      break;
    count++;
    ASSERT_EQ('$', ch);
  }
  fp.close();
  ASSERT_EQ(count, file_size);
  remove(fname);
  remove(fname2);
  dxf.flush();
  dxf.remove();
}

