// Constructor: initializes context and color, then records command buffers
color_renderer::color_renderer(uint32_t width, uint32_t height, std::array<float, 4> color)
    : context_{width, height}
    , color_{std::move(color)}
{
    prepare_command_buffers();
}

// Draw method: starts and ends the drawing process via context
void color_renderer::draw()
{
    context_.start_rendering();
    context_.finish_rendering();
}

// Update the renderer's color and re-record command buffers accordingly
void color_renderer::update_color(std::array<float, 4> new_color)
{
    color_ = std::move(new_color);
    prepare_command_buffers();
}

// Rebuilds command buffers for all swapchain images with appropriate memory barriers and clear operations
void color_renderer::prepare_command_buffers()
{
    auto& swapchain       = context_.get_swapchain();
    auto& physical_device = context_.get_physical_device();
    auto& cmd_buffers     = context_.get_command_buffers();

    vk::ImageSubresourceRange subresource_range =
        {vk::ImageAspectFlagBits::eColor, 0u, 1u, 0u, 1u};

    for (uint32_t i = 0; i < swapchain.images.size(); ++i) {
        // Transition from present layout to clear destination layout
        vk::ImageMemoryBarrier pre_clear_barrier = {
            vk::AccessFlagBits::eMemoryRead,
            vk::AccessFlagBits::eTransferWrite,
            vk::ImageLayout::eUndefined,
            vk::ImageLayout::eTransferDstOptimal,
            physical_device.graphics_queue_family_index,
            physical_device.graphics_queue_family_index,
            swapchain.images[i],
            subresource_range};

        // Transition from clear destination layout back to presentable layout
        vk::ImageMemoryBarrier post_clear_barrier = {
            vk::AccessFlagBits::eTransferWrite,
            vk::AccessFlagBits::eMemoryRead,
            vk::ImageLayout::eTransferDstOptimal,
            vk::ImageLayout::ePresentSrcKHR,
            physical_device.graphics_queue_family_index,
            physical_device.graphics_queue_family_index,
            swapchain.images[i],
            subresource_range};

        cmd_buffers[i]->begin(vk::CommandBufferBeginInfo{});

        // Insert pipeline barrier before clearing
        cmd_buffers[i]->pipelineBarrier(
            vk::PipelineStageFlagBits::eTransfer,
            vk::PipelineStageFlagBits::eTransfer,
            {},
            {},
            {},
            pre_clear_barrier);

        // Perform the actual color clear operation
        cmd_buffers[i]->clearColorImage(
            swapchain.images[i],
            vk::ImageLayout::eTransferDstOptimal,
            color_,
            subresource_range);

        // Insert pipeline barrier after clearing to make it visible to presentation
        cmd_buffers[i]->pipelineBarrier(
            vk::PipelineStageFlagBits::eTransfer,
            vk::PipelineStageFlagBits::eBottomOfPipe,
            {},
            {},
            {},
            post_clear_barrier);

        cmd_buffers[i]->end();
    }
}

