struct WebStream::impl : public StreamSockSetter {
    impl(const char* port_str, HWND wnd) 
        : m_listener(port_str), m_init_block(true), m_window(wnd) {
        // Launch acceptor thread
        m_worker = std::thread(&WebStream::impl::AcceptConnections, this);

        // Synchronize until first client connects or error occurs
        std::mutex mtx;
        std::unique_lock<std::mutex> lk(mtx);
        while (m_init_block)
            m_cv.wait(lk);
    }

    void AcceptConnections() {
        for (;;) {
            auto conn = m_listener.WaitForIncoming();
            if (!conn)
                break;

            // Handle new connection asynchronously
            conn->Activate(m_window, this);
            m_active_clients.emplace_back(std::move(conn));
        }
        SignalReady();
    }

    void SetStreamSocket(ClientSock& s) override {
        for (size_t idx = 0; idx < m_active_clients.size(); ++idx) {
            if (m_active_clients[idx].get() == &s) {
                m_primary_client = std::move(m_active_clients[idx]);
                return;
            }
        }
    }

    void SignalReady() override {
        m_init_block = false;
        m_cv.notify_all();
    }

    ~impl() override {
        // Terminate listening socket to unblock accept calls
        m_listener = ServerSock();
        if (m_worker.joinable())
            m_worker.join();

        // Clean up streaming socket
        m_primary_client.reset();

        // Ensure all client threads exit gracefully
        for (auto& cl : m_active_clients) {
            if (cl)
                cl.reset();
        }
    }

    ServerSock                    m_listener;         ///< accepts incoming connections
    std::unique_ptr<ClientSock>   m_primary_client;   ///< active streaming channel
    std::atomic<bool>             m_init_block;       ///< blocks constructor until ready
    std::condition_variable       m_cv;               ///< used to signal readiness
    std::thread                   m_worker;           ///< background acceptor thread
    std::vector<std::unique_ptr<ClientSock>> m_active_clients;
    HWND                          m_window = nullptr;
    unsigned __int64              m_position = 0;
    MP4FragmentEditor             m_stream_processor;
};

