HRESULT WebStream::WriteImpl(const BYTE* pb, ULONG cb) {
#ifndef ENABLE_FFMPEG
    std::tie(pb, cb) = m_impl->m_stream_processor.ModifyData(pb, cb);
#endif

    int sent_bytes = send(m_impl->m_primary_client->Socket(), reinterpret_cast<const char*>(pb), cb, 0);
    if (sent_bytes == SOCKET_ERROR) {
        m_impl->m_primary_client.reset();
        return E_FAIL;
    }

    m_impl->m_position += static_cast<unsigned __int64>(sent_bytes);
    return S_OK;
}

HRESULT STDMETHODCALLTYPE WebStream::Write(const BYTE* pb, ULONG cb, ULONG* cbWritten) {
    std::lock_guard<std::mutex> guard(m_mutex);
    HRESULT result = WriteImpl(pb, cb);
    if (FAILED(result))
        return E_FAIL;

    *cbWritten = cb;
    return S_OK;
}

HRESULT STDMETHODCALLTYPE WebStream::BeginWrite(const BYTE* pb, ULONG cb, IMFAsyncCallback* callback, IUnknown* unkState) {
    m_mutex.lock();
    HRESULT res = WriteImpl(pb, cb);
    if (FAILED(res)) {
        m_mutex.unlock();
        return E_FAIL;
    }

    m_last_write_size = cb;

    CComPtr<IMFAsyncResult> async_result;
#ifndef ENABLE_FFMPEG
    if (FAILED(MFCreateAsyncResult(nullptr, callback, unkState, &async_result)))
        throw std::runtime_error("MFCreateAsyncResult failed");
#endif

    res = callback->Invoke(async_result); // triggers EndWrite
    return res;
}

HRESULT STDMETHODCALLTYPE WebStream::EndWrite(IMFAsyncResult* /*result*/, ULONG* cbWritten) {
    *cbWritten = m_last_write_size;
    m_last_write_size = 0;
    m_mutex.unlock();
    return S_OK;
}

HRESULT STDMETHODCALLTYPE WebStream::Seek(MFBYTESTREAM_SEEK_ORIGIN /*SeekOrigin*/, LONGLONG /*SeekOffset*/, DWORD /*SeekFlags*/, QWORD* /*CurrentPosition*/) {
    return E_NOTIMPL;
}

HRESULT STDMETHODCALLTYPE WebStream::Flush() {
    return S_OK;
}

HRESULT STDMETHODCALLTYPE WebStream::Close() {
    std::lock_guard<std::mutex> guard(m_mutex);
    m_impl.reset();
    return S_OK;
}

#include "wallsquareworld.h"
#include <cmath>
#include <algorithm>

namespace rlly
{
namespace env
{

WallSquareWorld::WallSquareWorld(/* args */)
{
    id = "WallSquareWorld";
    state.emplace_back(start_x);
    state.emplace_back(start_y);

    // Define observation space bounds
    std::vector<double> obs_low  = {0.0, 0.0};
    std::vector<double> obs_high = {1.0, 1.0};
    observation_space.set_bounds(obs_low, obs_high);

    action_space.set_n(4);

    // Random seed initialization
    int random_seed = std::rand();
    set_seed(random_seed);

    // Rendering configuration
    refresh_interval_for_render2d = 500;
    clipping_area_for_render2d[0] = 0.0;
    clipping_area_for_render2d[1] = 1.0;
    clipping_area_for_render2d[2] = 0.0;
    clipping_area_for_render2d[3] = 1.0;
}

env::StepResult<std::vector<double>> WallSquareWorld::step(int action)
{
    if (rendering_enabled)
        append_state_for_rendering(state);

    bool terminal_flag = false;

    // Compute reward based on distance to goal with Gaussian noise
    double dist_sq = std::pow(state[0] - goal_x, 2) + std::pow(state[1] - goal_y, 2);
    double base_reward = std::exp(-0.5 * dist_sq / std::pow(reward_smoothness, 2));
    double noisy_reward = base_reward + randgen.sample_gaussian(0, reward_noise_stdev);

    // Apply transition noise before movement
    double x_noise = randgen.sample_gaussian(0, transition_noise_stdev);
    double y_noise = randgen.sample_gaussian(0, transition_noise_stdev);

    double old_x = state[0];
    double old_y = state[1];

    // Update position with noise first
    double tentative_x = state[0] + x_noise;
    double tentative_y = state[1] + y_noise;

    // Clamp noisy positions to [0,1]
    tentative_x = std::clamp(tentative_x, 0.0, 1.0);
    tentative_y = std::clamp(tentative_y, 0.0, 1.0);

    // Apply deterministic action-based displacement
    switch (action)
    {
        case 0: tentative_x = std::max(0.0, tentative_x - displacement); break;
        case 1: tentative_x = std::min(1.0, tentative_x + displacement); break;
        case 2: tentative_y = std::max(0.0, tentative_y - displacement); break;
        case 3: tentative_y = std::min(1.0, tentative_y + displacement); break;
        default: break;
    }

    // Collision detection via line interpolation
    double dx = tentative_x - old_x;
    double dy = tentative_y - old_y;
    double curr_x = old_x;
    double curr_y = old_y;

    const int steps = 10;
    double step_x = dx / static_cast<double>(steps);
    double step_y = dy / static_cast<double>(steps);

    for (int k = 1; k <= steps; ++k)
    {
        double probe_x = curr_x + step_x;
        double probe_y = curr_y + step_y;

        if (! is_obstructed(probe_x, probe_y))
        {
            curr_x = probe_x;
            curr_y = probe_y;
        }
    }

    // Final domain clamping
    enforce_domain_bounds(curr_x, curr_y);

    state[0] = curr_x;
    state[1] = curr_y;

    env::StepResult<std::vector<double>> outcome(state, noisy_reward, terminal_flag);
    return outcome;
}

void WallSquareWorld::enforce_domain_bounds(double &x, double &y)
{
    x = std::max(0.0, x);
    x = std::min(1.0, x);
    y = std::max(0.0, y);
    y = std::min(1.0, y);
}

bool WallSquareWorld::is_obstructed(double x, double y)
{
    enforce_domain_bounds(x, y);

    bool blocked = false;

    // Check against wall 1
    if (x >= wall_1_x0 && x <= wall_1_x1 &&
        y >= wall_1_y0 && y <= wall_1_y1)
        blocked = true;

    // Check against wall 2
    if (!blocked && x >= wall_2_x0 && x <= wall_2_x1 &&
                   y >= wall_2_y0 && y <= wall_2_y1)
        blocked = true;

    return blocked;
}

std::vector<double> WallSquareWorld::reset()
{
    std::vector<double> reset_state = {start_x, start_y};
    state = reset_state;
    return reset_state;
}

std::unique_ptr<ContinuousStateEnv> WallSquareWorld::clone() const
{
    return std::make_unique<WallSquareWorld>(*this);
}

utils::render::Scene2D WallSquareWorld::get_scene_for_render2d(std::vector<double> agent_pos)
{
    utils::render::Scene2D scene;
    utils::render::Geometric2D agent_shape;
    agent_shape.type = "GL_QUADS";
    agent_shape.set_color(0.75, 0.0, 0.5);

    float half_width = 0.025f;
    float x = static_cast<float>(agent_pos[0]);
    float y = static_cast<float>(agent_pos[1]);

    // Draw cross-shaped agent
    // Horizontal bar
    agent_shape.add_vertex(x - half_width, y - half_width / 4.0f);
    agent_shape.add_vertex(x + half_width, y - half_width / 4.0f);
    agent_shape.add_vertex(x + half_width, y + half_width / 4.0f);
    agent_shape.add_vertex(x - half_width, y + half_width / 4.0f);

    // Vertical bar
    agent_shape.add_vertex(x - half_width / 4.0f, y - half_width);
    agent_shape.add_vertex(x + half_width / 4.0f, y - half_width);
    agent_shape.add_vertex(x + half_width / 4.0f, y + half_width);
    agent_shape.add_vertex(x - half_width / 4.0f, y + half_width);

    scene.add_shape(agent_shape);
    return scene;
}

utils::render::Scene2D WallSquareWorld::get_background_for_render2d()
{
    utils::render::Scene2D bg;

    // Goal flag
    utils::render::Geometric2D flag;
    flag.type = "GL_TRIANGLES";
    flag.set_color(0.0, 0.5, 0.0);
    flag.add_vertex(goal_x, goal_y);
    flag.add_vertex(goal_x + 0.025f, goal_y + 0.075f);
    flag.add_vertex(goal_x - 0.025f, goal_y + 0.075f);
    bg.add_shape(flag);

    // Wall 1
    utils::render::Geometric2D w1;
    w1.type = "GL_QUADS";
    w1.set_color(0.0, 0.0, 0.0);
    w1.add_vertex(wall_1_x0, wall_1_y0);
    w1.add_vertex(wall_1_x0, wall_1_y1);
    w1.add_vertex(wall_1_x1, wall_1_y1);
    w1.add_vertex(wall_1_x1, wall_1_y0);
    bg.add_shape(w1);

    // Wall 2
    utils::render::Geometric2D w2;
    w2.type = "GL_QUADS";
    w2.set_color(0.0, 0.0, 0.0);
    w2.add_vertex(wall_2_x0, wall_2_y0);
    w2.add_vertex(wall_2_x0, wall_2_y1);
    w2.add_vertex(wall_2_x1, wall_2_y1);
    w2.add_vertex(wall_2_x1, wall_2_y0);
    bg.add_shape(w2);

    return bg;
}

