    auto samples_it = samples().begin();
    auto samples_end = samples().end();

    while (samples_it != samples_end) {
        const auto& sample = *samples_it++;

        // sRGB conversions
        TRY(src_sRGB = C_sRGB(sample.sRGB));              TRY(convert_colour(src_sRGB, dst_sRGB));          TEST_VECTORS(dst_sRGB, sample.sRGB, 1e-10);
        TRY(src_sRGB = C_sRGB(sample.sRGB));              TRY(convert_colour(src_sRGB, dst_adobe));       TEST_VECTORS(dst_adobe, sample.AdobeRGB, 0.001);
