        TRY(src_hsl = C_HSL(sample.HSL));                 TRY(convert_colour(src_hsl, dst_lab));          TEST_VECTORS(dst_lab, sample.CIELab, 0.1);
        TRY(src_hsl = C_HSL(sample.HSL));                 TRY(convert_colour(src_hsl, dst_luv));          TEST_VECTORS(dst_luv, sample.CIELuv, 0.1);
        TRY(src_hsl = C_HSL(sample.HSL));                 TRY(convert_colour(src_hsl, dst_hsl));          TEST_VECTORS_HSPACE(dst_hsl, sample.HSL, 1e-10);
        TRY(src_hsl = C_HSL(sample.HSL));                 TRY(convert_colour(src_hsl, dst_hsv));          TEST_VECTORS_HSPACE(dst_hsv, sample.HSV, 0.001);

        // HSV conversions
