        TRY(src_hsv = C_HSV(sample.HSV));                 TRY(convert_colour(src_hsv, dst_hsl));          TEST_VECTORS_HSPACE(dst_hsl, sample.HSL, 0.001);
        TRY(src_hsv = C_HSV(sample.HSV));                 TRY(convert_colour(src_hsv, dst_hsv));          TEST_VECTORS_HSPACE(dst_hsv, sample.HSV, 1e-10);
    }
