// Validate tensor access bounds; abort on failure
extern "C" uint64_t boundary_check(
        const char *tensor_name, uint64_t offset, uint64_t span, uint64_t total_size) {
    if (offset >= total_size || offset + span > total_size) {
        std::fprintf(stderr,
            "Boundary violation for tensor '%s': offset=%llu span=%llu size=%llu\n",
            tensor_name,
            static_cast<unsigned long long>(offset),
            static_cast<unsigned long long>(span),
            static_cast<unsigned long long>(total_size));
        std::abort();
    }
    return offset;
}

// Allocate aligned memory block using standard aligned_alloc
extern "C" void *sc_global_aligned_alloc(size_t bytes, size_t alignment) {
    const size_t padded = ((bytes + alignment - 1) / alignment) * alignment;
    return std::aligned_alloc(alignment, padded);
}

// Free previously allocated aligned memory
extern "C" void sc_global_aligned_free(void *mem_block, size_t /*alignment*/) {
    std::free(mem_block);
}

