// Runtime tensor value validator: checks for NaN/Inf in float buffers
extern "C" void sc_value_check(void *tensor_ptr, const char *tensor_label, size_t byte_count) {
    float *data = reinterpret_cast<float *>(tensor_ptr);
    const size_t num_elements = byte_count / sizeof(float);

    for (size_t i = 0; i < num_elements; ++i) {
        float current_val = data[i];
        if (std::isnan(current_val) || std::isinf(current_val)) {
            SC_MODULE_WARN << "Invalid floating-point detected in tensor '"
                           << tensor_label << "' at index " << i;
        }
    }
}

