#include <iostream>
#include <vector>
#include <string>
using namespace std;

class PermutationChecker {
 public:
  bool containsPermutation(const string& pattern, const string& text) {
    int patternLen = pattern.size();
    int textLen = text.size();

    if (patternLen > textLen) return false;

    // Frequency array for characters 'a' to 'z'
    int freq[26] = {0};

    // Count required characters (negative counts indicate needed occurrences)
    for (char c : pattern) {
      freq[c - 'a']--;
    }

    int unmatchedCount = patternLen; // Number of characters still unmatched

    // Initialize the first window of size patternLen
    for (int j = 0; j < patternLen; ++j) {
      int idx = text[j] - 'a';
      freq[idx]++;
      if (freq[idx] <= 0) {
        unmatchedCount--;
      } else {
        unmatchedCount++;
      }
    }

    if (unmatchedCount == 0) return true;

    // Slide the window across the text
    for (int j = patternLen; j < textLen; ++j) {
      // Add new character entering the window
      int newCharIdx = text[j] - 'a';
      freq[newCharIdx]++;
      if (freq[newCharIdx] <= 0) {
        unmatchedCount--;
      } else {
        unmatchedCount++;
      }

      // Remove character leaving the window
      int oldCharIdx = text[j - patternLen] - 'a';
      freq[oldCharIdx]--;
      if (freq[oldCharIdx] >= 0) {
        unmatchedCount--;
      } else {
        unmatchedCount++;
      }

      if (unmatchedCount == 0) return true;
    }

    return false;
  }
};

int main(int argc, char const *argv[]) {
  PermutationChecker checker;
  string input1, input2;

  while (cin >> input1 >> input2) {
    cout << checker.containsPermutation(input1, input2) << endl;
  }

  return 0;
}

#include "errors.h"
#include <csignal>
#include <exception>
#include <type_traits>
#include "interface/messagebox.h"
#include "program/exit.h"

namespace Program
{
    // Custom signal handler for various system signals
    static void SignalHandler(int sig)
    {
        switch (sig)
        {
            case SIGABRT:
            case SIGINT:
            case SIGTERM:
                Exit(0);
                break;
            case SIGFPE:
                HardError("Runtime error: Floating point exception detected.");
                break;
            case SIGILL:
                HardError("Runtime error: Illegal instruction encountered.");
                break;
            case SIGSEGV:
                HardError("Runtime error: Segmentation fault occurred.");
                break;
            default:
                HardError("Runtime error: Unrecognized signal received.");
                break;
        }
    }

    // Global termination handler for uncaught exceptions
    static void TerminateHandler()
    {
        if (std::exception_ptr e = std::current_exception())
        {
            try
            {
                std::rethrow_exception(e);
            }
            catch (const std::exception& e)
            {
                std::string errorMsg;
                ExceptionToString(e, [&](const char* msg)
                {
                    if (!errorMsg.empty())
                        errorMsg += "\n";
                    errorMsg += msg;
                });
                HardError(errorMsg);
            }
            catch (...)
            {
                HardError("Termination due to unknown exception type.");
            }
        }
        else
        {
            HardError("Program terminated unexpectedly without an exception.");
        }
    }

    // Flag to track whether handlers have been installed
    static bool handlers_initialized = false;

    // Display error message in a modal dialog and exit
    void HardError(const std::string& message)
    {
        static bool first_call = true;
        if (!first_call)
            Exit(1);
        first_call = false;
        Interface::MessageBox(Interface::MessageBoxType::error, "Critical Error", "Error: " + message);
        Exit(1);
    }

    // Install signal and exception handlers (optionally only once)
    void SetErrorHandlers(bool install_once)
    {
        if (install_once && handlers_initialized)
            return;

        // List of signals to handle
        static constexpr int handled_signals[] = {SIGSEGV, SIGABRT, SIGINT, SIGTERM, SIGFPE, SIGILL};
        for (int signal_code : handled_signals)
            std::signal(signal_code, SignalHandler);

        std::set_terminate(TerminateHandler);
        handlers_initialized = true;
    }
}

#include "RTC/PipeTransport.hpp"
#include "Logger.hpp"
#include "MediaSoupErrors.hpp"
#include "Utils.hpp"

namespace RTC
{
	// Helper to extract and validate listen IP configuration
	static void ExtractListenIp(const json& data, std::string& ip, std::string& announcedIp)
	{
		auto listenIt = data.find("listenIp");
		if (listenIt == data.end() || !listenIt->is_object())
			MS_THROW_TYPE_ERROR("missing or invalid listenIp");

		auto ipIt = listenIt->find("ip");
		if (ipIt == listenIt->end() || !ipIt->is_string())
			MS_THROW_TYPE_ERROR("missing or invalid listenIp.ip");

		ip.assign(ipIt->get<std::string>());
		Utils::IP::NormalizeIp(ip);

		auto annIt = listenIt->find("announcedIp");
		if (annIt != listenIt->end())
		{
			if (!annIt->is_string())
				MS_THROW_TYPE_ERROR("invalid listenIp.announcedIp");
			announcedIp.assign(annIt->get<std::string>());
		}
	}

	// Helper to build remote address from JSON request
	static bool BuildRemoteAddress(const json& reqData, struct sockaddr_storage& addrStorage, std::string& ipStr)
	{
		auto ipIt = reqData.find("ip");
		if (ipIt == reqData.end() || !ipIt->is_string())
			return false;
		ipStr = ipIt->get<std::string>();
		Utils::IP::NormalizeIp(ipStr);

		auto portIt = reqData.find("port");
		if (portIt == reqData.end() || !Utils::Json::IsPositiveInteger(*portIt))
			return false;

		uint16_t port = portIt->get<uint16_t>();
		int family = Utils::IP::GetFamily(ipStr);
		int err = 0;

		switch (family)
		{
			case AF_INET:
				err = uv_ip4_addr(ipStr.c_str(), static_cast<int>(port),
					reinterpret_cast<sockaddr_in*>(&addrStorage));
				break;
			case AF_INET6:
				err = uv_ip6_addr(ipStr.c_str(), static_cast<int>(port),
					reinterpret_cast<sockaddr_in6*>(&addrStorage));
				break;
			default:
				return false;
		}

		if (err != 0)
			MS_ABORT("address parsing failed: %s", uv_strerror(err));

		return true;
	}

	/* Instance methods. */
	PipeTransport::PipeTransport(const std::string& id, Transport::Listener* listener, json& data)
	  : Transport(id, listener, data)
	{
		MS_TRACE();

		std::string localIp, announcedIp;
		ExtractListenIp(data, localIp, announcedIp);

		this->listenIp.ip = localIp;
		this->listenIp.announcedIp = announcedIp;

		try
		{
			this->udpSocket = new UdpSocket(this, this->listenIp.ip);
		}
		catch (const MediaSoupError&)
		{
			delete this->udpSocket;
			this->udpSocket = nullptr;
			throw;
		}
	}

	PipeTransport::~PipeTransport()
	{
		MS_TRACE();
		delete this->udpSocket;
		this->udpSocket = nullptr;
		delete this->tuple;
		this->tuple = nullptr;
	}

	void PipeTransport::FillJson(json& jsonObject) const
	{
		MS_TRACE();
		RTC::Transport::FillJson(jsonObject);

		jsonObject["tuple"] = json::object();
		auto& tupleObj = jsonObject["tuple"];

		if (this->tuple != nullptr)
		{
			this->tuple->FillJson(tupleObj);
		}
		else
		{
			const std::string& localIp = this->listenIp.announcedIp.empty()
			                             ? this->udpSocket->GetLocalIp()
			                             : this->listenIp.announcedIp;
			tupleObj["localIp"]   = localIp;
			tupleObj["localPort"] = this->udpSocket->GetLocalPort();
			tupleObj["protocol"]  = "udp";
		}
	}

	void PipeTransport::FillJsonStats(json& jsonArray)
	{
		MS_TRACE();
		RTC::Transport::FillJsonStats(jsonArray);
		auto& statsObj = jsonArray[0];

		statsObj["type"] = "pipe-transport";
		statsObj["tuple"] = json::object();
		auto& tupleObj = statsObj["tuple"];

		if (this->tuple != nullptr)
		{
			this->tuple->FillJson(tupleObj);
		}
		else
		{
			const std::string& localIp = this->listenIp.announcedIp.empty()
			                             ? this->udpSocket->GetLocalIp()
			                             : this->listenIp.announcedIp;
			tupleObj["localIp"]   = localIp;
			tupleObj["localPort"] = this->udpSocket->GetLocalPort();
			tupleObj["protocol"]  = "udp";
		}
	}

	void PipeTransport::HandleRequest(Channel::Request* request)
	{
		MS_TRACE();

		switch (request->methodId)
		{
			case Channel::Request::MethodId::TRANSPORT_CONNECT:
			{
				if (this->tuple != nullptr)
					MS_THROW_ERROR("connect() already invoked");

				struct sockaddr_storage remoteAddr{};
				std::string ipStr;
				if (!BuildRemoteAddress(request->data, remoteAddr, ipStr))
					MS_THROW_TYPE_ERROR("invalid connect parameters");

				try
				{
					this->tuple = new TransportTuple(
						this->udpSocket, reinterpret_cast<const sockaddr*>(&remoteAddr));
					if (!this->listenIp.announcedIp.empty())
						this->tuple->SetLocalAnnouncedIp(this->listenIp.announcedIp);
				}
				catch (const MediaSoupError&)
				{
					delete this->tuple;
					this->tuple = nullptr;
					throw;
				}

				json reply = json::object();
				this->tuple->FillJson(reply["tuple"]);
				request->Accept(reply);

				RTC::Transport::Connected();
				break;
			}
			default:
				RTC::Transport::HandleRequest(request);
		}
	}

	bool PipeTransport::IsConnected() const
	{
		return this->tuple != nullptr;
	}

	void PipeTransport::SendRtpPacket(RTC::RtpPacket* packet, onSendCallback* cb)
	{
		MS_TRACE();
		if (!IsConnected())
		{
			if (cb)
			{
				(*cb)(false);
				delete cb;
			}
			return;
		}

		size_t bytesSent = packet->GetSize();
		const uint8_t* payload = packet->GetData();
		this->tuple->Send(payload, bytesSent, cb);
		DataSent(bytesSent);
	}

	void PipeTransport::SendRtcpPacket(RTCP::Packet* packet)
	{
		MS_TRACE();
		if (!IsConnected()) return;

		size_t len = packet->GetSize();
		const uint8_t* data = packet->GetData();
		this->tuple->Send(data, len);
		DataSent(len);
	}

	void PipeTransport::SendRtcpCompoundPacket(RTCP::CompoundPacket* packet)
	{
		MS_TRACE();
		if (!IsConnected()) return;

		size_t len = packet->GetSize();
		const uint8_t* data = packet->GetData();
		this->tuple->Send(data, len);
		DataSent(len);
	}

	void PipeTransport::SendSctpData(const uint8_t* buffer, size_t length)
	{
		MS_TRACE();
		if (!IsConnected()) return;

		this->tuple->Send(buffer, length);
		DataSent(length);
	}

	void PipeTransport::OnPacketReceived(TransportTuple* sender, const uint8_t* data, size_t size)
	{
		MS_TRACE();
		DataReceived(size);

		if (RTCP::Packet::IsRtcp(data, size))
		{
			OnRtcpDataReceived(sender, data, size);
		}
		else if (RtpPacket::IsRtp(data, size))
		{
			OnRtpDataReceived(sender, data, size);
		}
		else if (SctpAssociation::IsSctp(data, size))
		{
			OnSctpDataReceived(sender, data, size);
		}
		else
		{
			MS_WARN_DEV("received unknown packet type");
		}
	}

	void PipeTransport::OnRtpDataReceived(TransportTuple* sender, const uint8_t* data, size_t size)
	{
		MS_TRACE();
		if (!IsConnected()) return;

		if (!this->tuple->Compare(sender))
		{
			MS_DEBUG_TAG(rtp, "ignoring RTP packet from unexpected source");
			return;
		}

		RtpPacket* pkt = RtpPacket::Parse(data, size);
		if (!pkt)
		{
			MS_WARN_TAG(rtp, "malformed RTP packet discarded");
			return;
		}

		ReceiveRtpPacket(pkt);
	}

	void PipeTransport::OnRtcpDataReceived(TransportTuple* sender, const uint8_t* data, size_t size)
	{
		MS_TRACE();
		if (!IsConnected()) return;

		if (!this->tuple->Compare(sender))
		{
			MS_DEBUG_TAG(rtcp, "ignoring RTCP packet from unknown endpoint");
			return;
		}

		RTCP::Packet* rtcp = RTCP::Packet::Parse(data, size);
		if (!rtcp)
		{
			MS_WARN_TAG(rtcp, "invalid RTCP data received");
			return;
		}

		ReceiveRtcpPacket(rtcp);
	}

	void PipeTransport::OnSctpDataReceived(TransportTuple* sender, const uint8_t* data, size_t size)
	{
		MS_TRACE();
		if (!IsConnected()) return;

		if (!this->tuple->Compare(sender))
		{
			MS_DEBUG_TAG(sctp, "ignoring SCTP packet from foreign address");
			return;
		}

		ReceiveSctpData(data, size);
	}

	void PipeTransport::OnUdpSocketPacketReceived(
		UdpSocket* sock, const uint8_t* data, size_t len, const struct sockaddr* addr)
	{
		MS_TRACE();
		TransportTuple temp(sock, addr);
		OnPacketReceived(&temp, data, len);
	}
} // namespace RTC

