#include <vector>
#include <utility>

struct Node {
    int key;
    Node* left;
    Node* right;
    Node(int val) : key(val), left(nullptr), right(nullptr) {}
};

// Helper function to determine LCA using post-order traversal with flags
std::pair<Node*, bool> findLCAHelper(Node* node, int target1, int target2, bool& found1, bool& found2) {
    if (!node) return {nullptr, false};

    // Recurse on left and right subtrees
    auto leftResult  = findLCAHelper(node->left,  target1, target2, found1, found2);
    auto rightResult = findLCAHelper(node->right, target1, target2, found1, found2);

    // If we've already found the LCA in a subtree, propagate it up
    if (leftResult.second) return leftResult;
    if (rightResult.second) return rightResult;

    // Check current node
    bool isCurrentMatch = (node->key == target1) || (node->key == target2);
    if (isCurrentMatch) {
        if (found1 && found2) {
            // Already fully found — shouldn't happen unless both targets are same
            return {node, true};
        }
        if (node->key == target1) found1 = true;
        if (node->key == target2) found2 = true;
    }

    // Combine findings from children and current node
    bool totalFound1 = found1 || (leftResult.first && (leftResult.first->key == target1)) || (rightResult.first && (rightResult.first->key == target1));
    bool totalFound2 = found2 || (leftResult.first && (leftResult.first->key == target2)) || (rightResult.first && (rightResult.first->key == target2));

    // If both targets are now known to be present in this subtree
    if (totalFound1 && totalFound2) {
        // Current node is LCA only if it's the first point where both sides contributed
        bool leftHasOne = (leftResult.first && ((leftResult.first->key == target1) || (leftResult.first->key == target2)));
        bool rightHasOne = (rightResult.first && ((rightResult.first->key == target1) || (rightResult.first->key == target2)));
        if ((leftHasOne && rightHasOne) || (isCurrentMatch && (leftHasOne || rightHasOne))) {
            return {node, true};
        }
    }

    // Propagate found status upward
    if (isCurrentMatch) {
        if (node->key == target1) found1 = true;
        if (node->key == target2) found2 = true;
    }

    // Return non-null child or current node if matched
    if (leftResult.first) return {leftResult.first, false};
    if (rightResult.first) return {rightResult.first, false};
    if (isCurrentMatch) return {node, false};

    return {nullptr, false};
}

// Wrapper that ensures both nodes exist before returning LCA
int findLCA(Node* root, int n1, int n2) {
    bool f1 = false, f2 = false;
    auto result = findLCAHelper(root, n1, n2, f1, f2);
    if (f1 && f2 && result.first) {
        return result.first->key;
    }
    return -1;
}

// Alternative path-based method (rewritten for completeness)
bool findPath(Node* root, std::vector<int>& path, int k) {
    if (!root) return false;

    path.push_back(root->key);

    if (root->key == k) return true;

    if ((root->left && findPath(root->left, path, k)) ||
        (root->right && findPath(root->right, path, k))) {
        return true;
    }

    path.pop_back();
    return false;
}

int findLCA_PathBased(Node* root, int n1, int n2) {
    std::vector<int> path1, path2;
    if (!findPath(root, path1, n1) || !findPath(root, path2, n2))
        return -1;

    int i = 0;
    while (i < path1.size() && i < path2.size() && path1[i] == path2[i]) {
        ++i;
    }
    return (i > 0) ? path1[i - 1] : -1;
}

