#include "RemoteUdpOutput.h"

#ifdef _WIN32
#include <WinSock2.h>
#include <Windows.h>
#else
#include <arpa/inet.h>
#include <fcntl.h>
#include <unistd.h>
#endif

#include "ChannelStrip.h"
#include <cstring>
#include <string>

// Sample rate list — same as original, but declared const
static constexpr uint32_t VBAN_SAMPLE_RATES[] = {
    6000,   12000,  24000,  48000, 96000, 192000, 384000,
    8000,   16000,  32000, 64000, 128000, 256000, 512000,
    11025,  22050,  44100,  88200, 176400, 352800, 705600
};

// Protocol constants unchanged
#define VBAN_PROTOCOL_AUDIO 0x00
#define VBAN_PROTOCOL_SERIAL 0x20
#define VBAN_PROTOCOL_TXT 0x40
#define VBAN_PROTOCOL_SERVICE 0x60
#define VBAN_DATATYPE_BYTE8 0x00
#define VBAN_DATATYPE_INT16 0x01
#define VBAN_DATATYPE_INT24 0x02
#define VBAN_DATATYPE_INT32 0x03
#define VBAN_DATATYPE_FLOAT32 0x04
#define VBAN_DATATYPE_FLOAT64 0x05
#define VBAN_DATATYPE_12BITS 0x06
#define VBAN_DATATYPE_10BITS 0x00
#define VBAN_CODEC_PCM 0x00

// Helper: find sample rate index in table
static int findSampleRateIndex(uint32_t sr) {
    for (size_t idx = 0; idx < sizeof(VBAN_SAMPLE_RATES) / sizeof(VBAN_SAMPLE_RATES[0]); ++idx) {
        if (VBAN_SAMPLE_RATES[idx] == sr)
            return static_cast<int>(idx);
    }
    return -1; // Not found
}

RemoteUdpOutput::RemoteUdpOutput(OscContainer* oscParent, const char* name)
    : started(false), sampleRateMeasure(oscParent, name) {}

RemoteUdpOutput::~RemoteUdpOutput() {
    stop();
}

int RemoteUdpOutput::init(int index, int samplerate, const char* ip, int port) {
    std::string streamName = ChannelStrip::JACK_CLIENT_NAME_PREFIX + std::to_string(index);
    uint32_t targetIp = inet_addr(ip);

    if (started)
        return 1;

    started = true;
    SPDLOG_INFO("Sending audio {} to {}:{}", index, ip, port);

    sin_server.sin_addr.s_addr = targetIp;
    sin_server.sin_family = AF_INET;
    sin_server.sin_port = htons(static_cast<u_short>(port));

    sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (sock_fd == -1) {
        SPDLOG_ERROR("Cannot create UDP socket: {} ({})", strerror(errno), errno);
        return 2;
    }

#ifndef _WIN32
    int flags = fcntl(sock_fd, F_GETFL, 0);
    fcntl(sock_fd, F_SETFL, flags | O_NONBLOCK);
    int broadcastFlag = 1;
    setsockopt(sock_fd, SOL_SOCKET, SO_BROADCAST, &broadcastFlag, sizeof(broadcastFlag));
#else
    unsigned long nonblocking = 1;
    ioctlsocket(sock_fd, FIONBIO, &nonblocking);
#endif

    // Initialize VBAN header
    dataBuffer.header.vban = 0x4e414256; // "VBAN"
    int srIdx = findSampleRateIndex(static_cast<uint32_t>(samplerate));
    if (srIdx >= 0)
        dataBuffer.header.format_SR = static_cast<uint8_t>(srIdx);
    else
        dataBuffer.header.format_SR = 0; // fallback

    dataBuffer.header.format_nbc = 2 - 1;                // stereo: numChannels - 1
    dataBuffer.header.format_bit = VBAN_DATATYPE_INT16;  // INT16 PCM
    strncpy(dataBuffer.header.streamname, streamName.c_str(), sizeof(dataBuffer.header.streamname) - 1);
    dataBuffer.header.nuFrame = 0;

    return 0;
}

void RemoteUdpOutput::stop() {
    if (!started)
        return;

    started = false;
    int localFd = sock_fd;
    sock_fd = -1;

#ifdef _WIN32
    closesocket(localFd);
#else
    close(localFd);
#endif
}

bool RemoteUdpOutput::isStarted() {
    return started;
}

void RemoteUdpOutput::onSlowTimer() {
    sampleRateMeasure.onTimeoutTimer();
}

void RemoteUdpOutput::setSampleRate(uint32_t sampleRate) {
    int idx = findSampleRateIndex(sampleRate);
    if (idx >= 0)
        dataBuffer.header.format_SR = static_cast<uint8_t>(idx);
}

void RemoteUdpOutput::sendAudio(float* leftCh, float* rightCh, size_t totalSamples) {
    if (sock_fd <= 0)
        return;

    size_t processed = 0;
    while (processed < totalSamples) {
        size_t remaining = totalSamples - processed;
        size_t chunkSize = (remaining > 256) ? 256 : remaining;

        dataBuffer.header.format_nbs = static_cast<uint8_t>(chunkSize - 1);

        // Pack interleaved samples (L-R-L-R...)
        for (size_t i = 0; i < chunkSize; ++i) {
            int16_t lVal = static_cast<int16_t>(leftCh[processed + i] * 32768.0f);
            int16_t rVal = static_cast<int16_t>(rightCh[processed + i] * 32768.0f);
            dataBuffer.data[i * 2] = lVal;
            dataBuffer.data[i * 2 + 1] = rVal;
        }

        size_t packetBytes = sizeof(dataBuffer.header) + chunkSize * 2 * sizeof(int16_t);
        int sent = sendto(sock_fd,
                          reinterpret_cast<char*>(&dataBuffer),
                          packetBytes,
                          0,
                          reinterpret_cast<sockaddr*>(&sin_server),
                          sizeof(sin_server));

        if (sent == -1) {
            if (errno == EWOULDBLOCK || errno == EAGAIN) {
                sent = 0; // treat as success for flow control
            } else {
                SPDLOG_ERROR("Socket error during sendto: {}", errno);
                break;
            }
        }

        processed += chunkSize;
        ++dataBuffer.header.nuFrame;
    }

    sampleRateMeasure.notifySampleProcessed(totalSamples);
}

void RemoteUdpOutput::sendAudioWithoutVBAN(float* leftCh, float* rightCh, size_t totalSamples) {
    if (sock_fd <= 0)
        return;

    size_t processed = 0;
    while (processed < totalSamples) {
        size_t remaining = totalSamples - processed;
        size_t chunkSize = (remaining > sizeof(dataBuffer.data) / sizeof(dataBuffer.data[0])) ?
                           sizeof(dataBuffer.data) / sizeof(dataBuffer.data[0]) :
                           remaining;

        for (size_t i = 0; i < chunkSize; ++i) {
            int16_t lVal = static_cast<int16_t>(leftCh[processed + i] * 32768.0f);
            int16_t rVal = static_cast<int16_t>(rightCh[processed + i] * 32768.0f);
            dataBuffer.data[i * 2] = lVal;
            dataBuffer.data[i * 2 + 1] = rVal;
        }

        size_t payloadBytes = chunkSize * 2 * sizeof(int16_t);
        int sent = sendto(sock_fd,
                          reinterpret_cast<char*>(dataBuffer.data),
                          payloadBytes,
                          0,
                          reinterpret_cast<sockaddr*>(&sin_server),
                          sizeof(sin_server));

        if (sent == -1) {
            if (errno != EWOULDBLOCK && errno != EAGAIN) {
                // Silent failure per original comment
            }
        }

        processed += chunkSize;
    }

    sampleRateMeasure.notifySampleProcessed(totalSamples);
}

