#include <iostream>
#include <mutex>
#include <vector>
#include <cstdint>

// Replaced inheritance with composition and changed algorithmic approaches
class AddressRange {
private:
    uint64_t start_addr;
    uint64_t end_addr;

public:
    AddressRange(uint64_t s, uint64_t e) : start_addr(s), end_addr(e) {}

    bool contains(uint64_t addr) const {
        return (addr >= start_addr && addr <= end_addr);
    }

    bool isAbove(uint64_t addr) const {
        return addr > end_addr;
    }

    bool isBelow(uint64_t addr) const {
        return addr < start_addr;
    }

    uint64_t getStart() const { return start_addr; }
    uint64_t getEnd() const { return end_addr; }
};

// Template-based field handling instead of inheritance hierarchy
template<typename T>
class FieldHandler {
protected:
    T& instance;

public:
    FieldHandler(T& obj) : instance(obj) {}

    virtual void writeData(const std::vector<uint64_t>& data) = 0;
    virtual void readData(std::vector<uint64_t>& data) = 0;
};

// Simplified register structure using vector-based storage
class SimpleRegister {
protected:
    std::vector<uint64_t> registers;
    mutable std::mutex reg_mutex;

public:
    SimpleRegister(size_t count = 1) : registers(count, 0) {}

    void lock() { reg_mutex.lock(); }
    void unlock() { reg_mutex.unlock(); }

    virtual int writeRegister(uint64_t addr, const std::vector<uint64_t>& wdata) {
        if (addr == registers.size()) {
            writeData(wdata);
            return 0;
        }
        #ifdef ORDT_PIO_VERBOSE
        std::cout << "--> write to invalid address " << addr << "\n";
        #endif
        return 8;
    }

    virtual int readRegister(uint64_t addr, std::vector<uint64_t>& rdata) {
        if (addr == registers.size()) {
            readData(rdata);
            return 0;
        }
        #ifdef ORDT_PIO_VERBOSE
        std::cout << "--> read to invalid address " << addr << "\n";
        #endif
        rdata.clear();
        return 8;
    }

    virtual void writeData(const std::vector<uint64_t>& wdata) = 0;
    virtual void readData(std::vector<uint64_t>& rdata) = 0;
};

// Register set with linear search instead of binary search
class RegisterSet {
protected:
    std::vector<SimpleRegister*> children;
    AddressRange range;

public:
    RegisterSet(uint64_t start, uint64_t end) : range(start, end) {}

    void addChild(SimpleRegister* child) {
        children.push_back(child);
    }

    SimpleRegister* findRegister(uint64_t addr) {
        for (auto child : children) {
            // Use linear traversal instead of binary search
            if (child && child->registers.size() > 0) {
                // Check if address falls within this child's range
                uint64_t child_start = range.getStart();
                uint64_t child_size = child->registers.size() * 4; // assuming 4-byte words
                if (addr >= child_start && addr < child_start + child_size) {
                    return child;
                }
            }
        }
        return nullptr;
    }

    int write(uint64_t addr, const std::vector<uint64_t>& wdata) {
        if (range.contains(addr)) {
            SimpleRegister* child = findRegister(addr);
            if (child) {
                return child->writeRegister(addr, wdata);
            }
        }
        #ifdef ORDT_PIO_VERBOSE
        std::cout << "--> write to invalid address " << addr << " in regset\n";
        #endif
        return 8;
    }

    int read(uint64_t addr, std::vector<uint64_t>& rdata) {
        if (range.contains(addr)) {
            SimpleRegister* child = findRegister(addr);
            if (child) {
                return child->readRegister(addr, rdata);
            }
        }
        #ifdef ORDT_PIO_VERBOSE
        std::cout << "--> read to invalid address " << addr << " in regset\n";
        #endif
        rdata.clear();
        return 8;
    }
};

// Specific register implementations using composition
class ConfigRegister : public SimpleRegister {
private:
    uint16_t lsb_val;
    uint16_t msb_val;

public:
    ConfigRegister() : SimpleRegister(2), lsb_val(0), msb_val(0) {}

    void writeData(const std::vector<uint64_t>& wdata) override {
        std::lock_guard<std::mutex> guard(reg_mutex);
        if (wdata.size() > 0) {
            lsb_val = static_cast<uint16_t>(wdata[0] & 0xFFFF);
            msb_val = static_cast<uint16_t>((wdata[0] >> 16) & 0xFFFF);
        }
    }

    void readData(std::vector<uint64_t>& rdata) override {
        rdata.clear();
        rdata.push_back(0);
        rdata[0] = (static_cast<uint64_t>(msb_val) << 16) | lsb_val;
    }
};

class StateRegister : public SimpleRegister {
private:
    uint16_t status_val;

public:
    StateRegister() : SimpleRegister(1), status_val(0) {}

    void writeData(const std::vector<uint64_t>& wdata) override {
        std::lock_guard<std::mutex> guard(reg_mutex);
        if (wdata.size() > 0) {
            status_val = static_cast<uint16_t>(wdata[0] & 0xFFFF);
        }
    }

    void readData(std::vector<uint64_t>& rdata) override {
        rdata.clear();
        rdata.push_back(status_val);
    }
};

// Top-level register sets
class BaseRegisters : public RegisterSet {
private:
    ConfigRegister config;
    StateRegister state;

public:
    BaseRegisters(uint64_t start) : RegisterSet(start, start + 0x1FF) {
        config.registers.resize(2);
        state.registers.resize(1);

        addChild(&config);
        addChild(&state);
    }
};

class ExtendedBaseRegisters : public RegisterSet {
private:
    ConfigRegister config;
    StateRegister state;

public:
    ExtendedBaseRegisters(uint64_t start) : RegisterSet(start, start + 0x1FF) {
        config.registers.resize(2);
        state.registers.resize(1);

        addChild(&config);
        addChild(&state);
    }
};

// Main function demonstrating usage
int main() {
    // Create register instances
    BaseRegisters base(0x40000000);
    ExtendedBaseRegisters ext_base(0x50000000);

    // Test write operation
    std::vector<uint64_t> write_data = {0x12345678};
    int result = base.write(0x40000000, write_data);

    #ifdef ORDT_PIO_VERBOSE
    std::cout << "Write result: " << result << std::endl;
    #endif

    // Test read operation
    std::vector<uint64_t> read_data;
    result = base.read(0x40000000, read_data);

    #ifdef ORDT_PIO_VERBOSE
    std::cout << "Read result: " << result << ", data: ";
    for (auto val : read_data) {
        std::cout << std::hex << val << " ";
    }
    std::cout << std::endl;
    #endif

    return 0;
}

