// Helper: print register operand in human-readable form
static inline void emitRegName(raw_ostream &out, unsigned regNum,
                               const TargetRegisterInfo *regInfo = nullptr) {
  if (regNum && TargetRegisterInfo::isPhysicalRegister(regNum)) {
    if (regInfo)
      out << " %" << regInfo->get(regNum).Name;
    else
      out << " %physreg" << regNum;
  } else {
    out << " %reg" << regNum;
  }
}

MachineBasicBlock::MachineBasicBlock(MachineFunction &func, const BasicBlock *bb)
  : BB(bb), Number(-1), xParent(&func), Alignment(0), IsLandingPad(false),
    AddressTaken(false) {
  Insts.Parent = this;
}

MachineBasicBlock::~MachineBasicBlock() {
  LeakDetector::removeGarbageObject(this);
}

raw_ostream &llvm::operator<<(raw_ostream &OS, const MachineBasicBlock &MBB) {
  MBB.print(OS);
  return OS;
}

void ilist_traits<MachineBasicBlock>::addNodeToList(MachineBasicBlock *node) {
  MachineFunction &MF = *node->getParent();
  node->Number = MF.addToMBBNumbering(node);

  MachineRegisterInfo &regInfo = MF.getRegInfo();
  for (auto instIt = node->begin(), endIt = node->end(); instIt != endIt; ++instIt)
    instIt->AddRegOperandsToUseLists(regInfo);

  LeakDetector::removeGarbageObject(node);
}

void ilist_traits<MachineBasicBlock>::removeNodeFromList(MachineBasicBlock *node) {
  node->getParent()->removeFromMBBNumbering(node->Number);
  node->Number = -1;
  LeakDetector::addGarbageObject(node);
}

void ilist_traits<MachineInstr>::addNodeToList(MachineInstr *instr) {
  assert(instr->getParent() == nullptr && "Instruction already belongs to block");
  instr->setParent(Parent);

  MachineFunction *MF = Parent->getParent();
  instr->AddRegOperandsToUseLists(MF->getRegInfo());
  LeakDetector::removeGarbageObject(instr);
}

void ilist_traits<MachineInstr>::removeNodeFromList(MachineInstr *instr) {
  assert(instr->getParent() != nullptr && "Instruction not in any block");
  instr->RemoveRegOperandsFromUseLists();
  instr->setParent(nullptr);
  LeakDetector::addGarbageObject(instr);
}

void ilist_traits<MachineInstr>::transferNodesFromList(
    ilist_traits<MachineInstr> &sourceList,
    MachineBasicBlock::iterator start,
    MachineBasicBlock::iterator finish) {
  assert(Parent->getParent() == sourceList.Parent->getParent() &&
         "Parent function mismatch during transfer");

  if (Parent == sourceList.Parent) return;

  auto curr = start;
  while (curr != finish) {
    curr->setParent(Parent);
    ++curr;
  }
}

void ilist_traits<MachineInstr>::deleteNode(MachineInstr *MI) {
  assert(!MI->getParent() && "Still attached to block!");
  Parent->getParent()->DeleteMachineInstr(MI);
}

MachineBasicBlock::iterator MachineBasicBlock::getFirstTerminator() {
  iterator it = end();
  // Walk backwards until we find first terminator or reach begin()
  while (it != begin()) {
    --it;
    if (!it->getDesc().isTerminator())
      break;
  }
  // If current is not a terminator, move forward one step
  if (it != end() && !it->getDesc().isTerminator())
    ++it;
  return it;
}

bool MachineBasicBlock::isOnlyReachableByFallthrough() const {
  if (isLandingPad() || pred_empty())
    return false;

  const_pred_iterator predIt = pred_begin();
  const_pred_iterator nextPred = predIt;
  ++nextPred;
  if (nextPred != pred_end())
    return false;

  const MachineBasicBlock *pred = *predIt;
  if (!pred->isLayoutSuccessor(this))
    return false;

  if (pred->empty())
    return true;

  const MachineInstr &lastInstr = pred->back();
  return !lastInstr.getDesc().isBarrier();
}

void MachineBasicBlock::dump() const {
  print(errs());
}

void MachineBasicBlock::print(raw_ostream &OS) const {
  const MachineFunction *MF = getParent();
  if (!MF) {
    OS << "Cannot print MachineBasicBlock: parent MachineFunction is null\n";
    return;
  }

  if (Alignment > 0)
    OS << "Alignment " << Alignment << "\n";

  OS << "BB#" << getNumber() << ": ";
  const char *sep = "";
  if (const BasicBlock *llvmBB = getBasicBlock()) {
    OS << sep << "derived from LLVM BB ";
    WriteAsOperand(OS, llvmBB, /*PrintType=*/false);
    sep = ", ";
  }

  if (isLandingPad()) { OS << sep << "EH LANDING PAD"; sep = ", "; }
  if (hasAddressTaken()) { OS << sep << "ADDRESS TAKEN"; sep = ", "; }
  OS << '\n';

  const TargetRegisterInfo *TRI = MF->getTarget().getRegisterInfo();

  if (!livein_empty()) {
    OS << "    Live Ins:";
    for (const_livein_iterator lit = livein_begin(), lie = livein_end(); lit != lie; ++lit)
      emitRegName(OS, *lit, TRI);
    OS << '\n';
  }

  if (!pred_empty()) {
    OS << "    Predecessors according to CFG:";
    for (const_pred_iterator pit = pred_begin(), pie = pred_end(); pit != pie; ++pit)
      OS << " BB#" << (*pit)->getNumber();
    OS << '\n';
  }

  for (const_iterator iit = begin(); iit != end(); ++iit) {
    OS << '\t';
    iit->print(OS, &getParent()->getTarget());
  }

  if (!succ_empty()) {
    OS << "    Successors according to CFG:";
    for (const_succ_iterator sit = succ_begin(), sie = succ_end(); sit != sie; ++sit)
      OS << " BB#" << (*sit)->getNumber();
    OS << '\n';
  }
}

void MachineBasicBlock::removeLiveIn(unsigned reg) {
  livein_iterator pos = std::find(livein_begin(), livein_end(), reg);
  assert(pos != livein_end() && "Register not live-in!");
  LiveIns.erase(pos);
}

bool MachineBasicBlock::isLiveIn(unsigned reg) const {
  return std::find(livein_begin(), livein_end(), reg) != livein_end();
}

void MachineBasicBlock::moveBefore(MachineBasicBlock *target) {
  getParent()->splice(target, this);
}

void MachineBasicBlock::moveAfter(MachineBasicBlock *before) {
  MachineFunction::iterator iter = before;
  getParent()->splice(++iter, this);
}

void MachineBasicBlock::updateTerminator() {
  const TargetInstrInfo *TII = getParent()->getTarget().getInstrInfo();

  if (this->succ_empty()) return;

  MachineBasicBlock *targetBB = nullptr, *fallBB = nullptr;
  SmallVector<MachineOperand, 4> cond;
  bool success = TII->AnalyzeBranch(*this, targetBB, fallBB, cond);
  (void)success;
  assert(!success && "UpdateTerminators requires analyzable predecessors!");

  if (cond.empty()) {
    if (targetBB) {
      if (isLayoutSuccessor(targetBB))
        TII->RemoveBranch(*this);
    } else {
      targetBB = *succ_begin();
      if (!isLayoutSuccessor(targetBB))
        TII->InsertBranch(*this, targetBB, nullptr, cond);
    }
  } else {
    if (fallBB) {
      if (isLayoutSuccessor(targetBB)) {
        TII->RemoveBranch(*this);
        TII->ReverseBranchCondition(cond);
        TII->InsertBranch(*this, fallBB, nullptr, cond);
      } else if (isLayoutSuccessor(fallBB)) {
        TII->RemoveBranch(*this);
        TII->InsertBranch(*this, targetBB, nullptr, cond);
      }
    } else {
      MachineBasicBlock *firstSucc = *succ_begin();
      MachineBasicBlock *secondSucc = *next(succ_begin());
      if (firstSucc == targetBB) std::swap(firstSucc, secondSucc);
      if (isLayoutSuccessor(targetBB)) {
        TII->RemoveBranch(*this);
        TII->ReverseBranchCondition(cond);
        TII->InsertBranch(*this, firstSucc, nullptr, cond);
      } else if (!isLayoutSuccessor(firstSucc)) {
        TII->RemoveBranch(*this);
        TII->InsertBranch(*this, targetBB, firstSucc, cond);
      }
    }
  }
}

void MachineBasicBlock::addSuccessor(MachineBasicBlock *succ) {
  Successors.push_back(succ);
  succ->addPredecessor(this);
}

void MachineBasicBlock::removeSuccessor(MachineBasicBlock *succ) {
  succ->removePredecessor(this);
  succ_iterator pos = std::find(Successors.begin(), Successors.end(), succ);
  assert(pos != Successors.end() && "Not a current successor!");
  Successors.erase(pos);
}

MachineBasicBlock::succ_iterator 
MachineBasicBlock::removeSuccessor(succ_iterator pos) {
  assert(pos != Successors.end() && "Invalid successor iterator!");
  (*pos)->removePredecessor(this);
  return Successors.erase(pos);
}

void MachineBasicBlock::addPredecessor(MachineBasicBlock *pred) {
  Predecessors.push_back(pred);
}

void MachineBasicBlock::removePredecessor(MachineBasicBlock *pred) {
  auto pos = std::find(Predecessors.begin(), Predecessors.end(), pred);
  assert(pos != Predecessors.end() && "Not a predecessor!");
  Predecessors.erase(pos);
}

void MachineBasicBlock::transferSuccessors(MachineBasicBlock *src) {
  if (this == src) return;

  for (MachineBasicBlock::succ_iterator sit = src->succ_begin(),
       sie = src->succ_end(); sit != sie; ++sit)
    addSuccessor(*sit);

  while (!src->succ_empty())
    src->removeSuccessor(src->succ_begin());
}

bool MachineBasicBlock::isSuccessor(const MachineBasicBlock *mbb) const {
  return std::find(Successors.begin(), Successors.end(), mbb) != Successors.end();
}

bool MachineBasicBlock::isLayoutSuccessor(const MachineBasicBlock *mbb) const {
  MachineFunction::const_iterator cur(this);
  return next(cur) == MachineFunction::const_iterator(mbb);
}

MachineBasicBlock *MachineBasicBlock::removeFromParent() {
  assert(getParent() && "Not part of a function!");
  getParent()->remove(this);
  return this;
}

void MachineBasicBlock::eraseFromParent() {
  assert(getParent() && "Not part of a function!");
  getParent()->erase(this);
}

void MachineBasicBlock::ReplaceUsesOfBlockWith(MachineBasicBlock *old,
                                               MachineBasicBlock *nw) {
  assert(old != nw && "Cannot replace self with self!");
  MachineBasicBlock::iterator it = end();
  while (it != begin()) {
    --it;
    if (!it->getDesc().isTerminator()) break;
    for (unsigned idx = 0, cnt = it->getNumOperands(); idx != cnt; ++idx) {
      MachineOperand &op = it->getOperand(idx);
      if (op.isMBB() && op.getMBB() == old)
        op.setMBB(nw);
    }
  }
  removeSuccessor(old);
  addSuccessor(nw);
}

bool MachineBasicBlock::CorrectExtraCFGEdges(MachineBasicBlock *destA,
                                             MachineBasicBlock *destB,
                                             bool isConditional) {
  bool changed = false;
  bool addedFallThrough = false;
  MachineFunction::iterator fallThru = next(MachineFunction::iterator(this));

  if (isConditional) {
    if (!destB && fallThru != getParent()->end()) {
      destB = fallThru;
      addedFallThrough = true;
    }
  } else {
    if (!destA && fallThru != getParent()->end()) {
      destA = fallThru;
      addedFallThrough = true;
    }
  }

  MachineBasicBlock *origA = destA, *origB = destB;
  MachineBasicBlock::succ_iterator sit = succ_begin();
  while (sit != succ_end()) {
    if (*sit == destA) {
      destA = nullptr;
      ++sit;
    } else if (*sit == destB) {
      destB = nullptr;
      ++sit;
    } else if ((*sit)->isLandingPad() &&
               *sit != origA && *sit != origB) {
      ++sit;
    } else {
      sit = removeSuccessor(sit);
      changed = true;
    }
  }

  if (!addedFallThrough) {
    assert(!destA && !destB && "Missing expected edges!");
  } else if (isConditional) {
    assert(!destA && "Missing expected edge!");
  }

  return changed;
}

void llvm::WriteAsOperand(raw_ostream &OS, const MachineBasicBlock *MBB, bool) {
  OS << "BB#" << MBB->getNumber();
}

