// Helper: convert multiple points at once
static std::vector<DLibV::Representacion_primitiva_poligono_base::punto>
convertir_vertices(const DLibH::Poligono_2d<double>& poly) {
	std::vector<DLibV::Representacion_primitiva_poligono_base::punto> result;
	result.reserve(poly.acc_vertices().size());
	for (const auto& pt : poly.acc_vertices()) {
		result.emplace_back(cartesiano_a_sdl(pt));
	}
	return result;
}

