void Representador::dibujar_rejilla(DLibV::Pantalla& pantalla,
                                    int grid,
                                    tcolor color,
                                    double nx,
                                    double ny,
                                    double zoom,
                                    int w,
                                    int h)
{
	DLibV::Representacion_primitiva_linea lin(0, 0, 0, 0, color.r, color.g, color.b);
	lin.establecer_alpha(color.a);

	const double step_x = grid / zoom;
	const double step_y = grid / zoom;

	// Vertical lines
	double x_start = -(std::fmod(nx, static_cast<double>(grid))) / zoom;
	for (double x = x_start; x < x_start + w; x += step_x) {
		lin.establecer_puntos(x, 0.0, x, static_cast<double>(h));
		lin.volcar(pantalla);
	}

	// Horizontal lines
	double y_start = (std::fmod(ny, static_cast<double>(grid))) / zoom;
	for (double y = y_start; y < y_start + h; y += step_y) {
		lin.establecer_puntos(0.0, y, static_cast<double>(w), y);
		lin.volcar(pantalla);
	}
}

