	std::vector<DLibV::Representacion_primitiva_poligono_base::punto> puntos;
	puntos.reserve(poligono.acc_vertices().size());

	for (const auto& v : poligono.acc_vertices()) {
		puntos.push_back({static_cast<int>(std::floor(v.x)), static_cast<int>(std::floor(-v.y))});
	}

	DLibV::Representacion_primitiva_poligono poli(puntos, color.r, color.g, color.b);
	poli.establecer_alpha(color.a);
	poli.volcar(pantalla);
}

