}

void Representador::dibujar_hud(DLibV::Pantalla& pantalla,
                                const DLibV::Fuente_TTF& f,
                                const std::string& cad_tiempo,
                                bool aviso_tiempo,
                                int max_vel,
                                int act_vel,
                                int tot_vel)
{
	const SDL_Color tiempo_color = aviso_tiempo ? SDL_Color{255, 32, 32, 255} : SDL_Color{255, 255, 255, 255};
	DLibV::Representacion_TTF txt(f, tiempo_color, cad_tiempo);
	txt.ir_a(16, 70);
	txt.volcar(pantalla);

	DLibV::Representacion_bitmap sprite(DLibV::Gestor_texturas::obtener(r_graficos::g_hud));
	sprite.establecer_modo_blend(DLibV::Representacion::BLEND_ALPHA);

	// Lambda to draw velocity bars
	auto dibujar_barras = [&](int& current, int limit, int rec_x, int alpha) {
		sprite.establecer_recorte(rec_x, 0, 31, 40);
		sprite.establecer_alpha(alpha);
		for (; current <= limit; ++current) {
			sprite.establecer_posicion((current * 33) + 16, 16, 31, 40);
			sprite.volcar(pantalla);
		}
	};

	// Draw current speed bar
	sprite.establecer_recorte(31, 0, 31, 40);
	sprite.establecer_alpha(255);
	int vel_actual = 0;
	dibujar_barras(vel_actual, act_vel, 31, 255);

	// Warning overlay if needed
	if (aviso_velocidad_minima.tiempo > 0.0f && vel_actual <= aviso_velocidad_minima.velocidad) {
		float remaining = aviso_velocidad_minima.tiempo;
		int alpha = static_cast<int>((remaining * 255.0f) / 1.2f);
		if (alpha < 128) alpha = 128;
		int temp = vel_actual;
		dibujar_barras(temp, aviso_velocidad_minima.velocidad, 62, alpha);
	}

	// Max and total speed overlays
	if (vel_actual <= max_vel) dibujar_barras(vel_actual, max_vel, 0, 128);
	if (vel_actual <= tot_vel) dibujar_barras(vel_actual, tot_vel, 93, 128);
}

void Representador::turno(float delta)
{
	if (aviso_velocidad_minima.tiempo > 0.0f) {
		aviso_velocidad_minima.tiempo -= delta;
		if (aviso_velocidad_minima.tiempo < 0.0f) {
			aviso_velocidad_minima.tiempo = 0.0f;
		}
	}
}

void Representador::avisar_velocidad_minima(int vel)
{
	aviso_velocidad_minima = {vel, 1.2f};
}

