// Helper to print range objects
template <int Dims>
std::ostream& operator<<(std::ostream& OS, const range<Dims>& Rng) {
    OS << "{";
    if constexpr (Dims > 0) OS << Rng[0];
    if constexpr (Dims > 1) OS << ", " << Rng[1];
    if constexpr (Dims > 2) OS << ", " << Rng[2];
    OS << "}";
    return OS;
}

// Template class for kernel naming
template <typename T, bool B> class KernelTag;

// Core test function supporting both SYCL 2020 and OneAPI reduction APIs
template <typename KernelName, bool IsSYCL2020, access::mode AccMode, typename ValueType,
          int DimCount = 1, typename BinaryOp, int Rank>
void runReductionTest(queue& Q, ValueType IdentityVal, ValueType InitVal,
                      BinaryOp CombineOp, range<Rank> WorkRange) {
    std::string ModeStr = IsSYCL2020 ? "SYCL2020" : "ONEAPI  ";
    std::cout << "Running test: " << ModeStr
              << " {T=" << typeid(ValueType).name()
              << ", Op=" << typeid(BinaryOp).name()
              << ", Range=" << WorkRange << "}\n";

    // Avoid testing extremely large ranges due to memory constraints
    constexpr size_t MaxSize = static_cast<size_t>(2LL * 1024 * 1024 * 1024);
    if (WorkRange.size() > MaxSize) {
        std::cerr << "[SKIP] Range too large: " << WorkRange.size() << " elements\n";
        return;
    }

    buffer<ValueType, Rank> InputBuffer(WorkRange);
    buffer<ValueType, 1> OutputBuffer{1};

    // Compute expected result
    ValueType ExpectedResult{};
    initInputData(InputBuffer, ExpectedResult, IdentityVal, CombineOp, WorkRange);

    if constexpr (AccMode == access::mode::read_write) {
        ExpectedResult = CombineOp(ExpectedResult, InitVal);
    }

    // Initialize output buffer — value will be overwritten in read_write mode
    {
        auto OutAcc = OutputBuffer.template get_access<access::mode::write>();
        OutAcc[0] = InitVal;
    }

    // Submit kernel
    if constexpr (IsSYCL2020) {
        Q.submit([&](handler& CmdGroup) {
            auto InAcc = InputBuffer.template get_access<access::mode::read>(CmdGroup);
            property_list Props = makePropertyList<AccMode>();
            auto Redu = sycl::reduction(OutputBuffer, CmdGroup, IdentityVal, CombineOp, Props);
            CmdGroup.parallel_for<KernelName>(
                WorkRange, Redu, [=](id<Rank> Idx, auto& Accum) {
                    Accum.combine(InAcc[Idx]);
                });
        });
    } else {
        Q.submit([&](handler& CmdGroup) {
            auto InAcc = InputBuffer.template get_access<access::mode::read>(CmdGroup);
            accessor<ValueType, DimCount, AccMode, access::target::global_buffer> OutAcc(
                OutputBuffer, CmdGroup);
            auto Redu = ext::oneapi::reduction(OutAcc, IdentityVal, CombineOp);
            CmdGroup.parallel_for<KernelName>(
                WorkRange, Redu, [=](id<Rank> Idx, auto& Accum) {
                    Accum.combine(InAcc[Idx]);
                });
        });
    }

    // Verify result
    auto FinalOut = OutputBuffer.template get_access<access::mode::read>();
    ValueType ActualResult = *FinalOut.get_pointer();
    if (ActualResult != ExpectedResult) {
        printDeviceInfo(Q, true);
        std::cerr << "Mismatch! Range=" << WorkRange
                  << ", Got=" << ActualResult
                  << ", Expected=" << ExpectedResult << "\n";
        assert(false && "Incorrect reduction result.");
    }
}

// Wrapper to run both SYCL 2020 and OneAPI variants
template <typename Tag, access::mode AccMode, typename T, class BinaryOperation, int Dim>
void runBothModes(queue& Q, T IdentityVal, T InitVal, BinaryOperation CombineOp,
                  range<Dim> WorkRange) {
    runReductionTest<KernelTag<Tag, false>, false, AccMode>(Q, IdentityVal, InitVal, CombineOp, WorkRange);
    runReductionTest<KernelTag<Tag, true>, true, AccMode>(Q, IdentityVal, InitVal, CombineOp, WorkRange);
}

void ExtensionServiceBackend::LoadSingleExtension(const FilePath& path_in) {
    CHECK(BrowserThread::CurrentlyOn(BrowserThread::FILE));
    FilePath extension_path = path_in;
    file_util::AbsolutePath(&extension_path);

    // Determine flags using ternary operator instead of if statement
    int flags = (Extension::ShouldAlwaysAllowFileAccess(Extension::LOAD)) 
                ? Extension::ALLOW_FILE_ACCESS 
                : Extension::NO_FLAGS;

    // Add strict error checking flag conditionally
    if (Extension::ShouldDoStrictErrorChecking(Extension::LOAD))
        flags |= Extension::STRICT_ERROR_CHECKS;

    std::string error;
    scoped_refptr<const Extension> extension(extension_file_util::LoadExtension(
        extension_path,
        Extension::LOAD,
        flags,
        &error));

    // Handle loading failure by directly calling error method on FILE thread
    // instead of posting task when error occurs
    if (!extension) {
        if (BrowserThread::PostTask(
            BrowserThread::UI, FROM_HERE,
            NewRunnableMethod(
                this,
                &ExtensionServiceBackend::ReportExtensionLoadError,
                extension_path, error))) {
            return;
        }
        NOTREACHED() << error;
        return;
    }

    // Report installation - use direct call pattern with early return check
    bool posted_successfully = BrowserThread::PostTask(
        BrowserThread::UI, FROM_HERE,
        NewRunnableMethod(
            this,
            &ExtensionServiceBackend::OnExtensionInstalled,
            extension));

    if (!posted_successfully) {
        NOTREACHED();
    }
}

