bool validateProfile(std::map<uint64_t, BinaryFunction> &functions) {
  bool valid = true;
  for (auto &pair : functions) {
    BinaryFunction &func = pair.second;
    if (!func.isSimple())
      continue;
    for (BinaryBasicBlock *bb : func.layout()) {
      auto branchIt = bb->branch_info_begin();
      for (BinaryBasicBlock *succ : bb->successors()) {
        if (branchIt->Count != BinaryBasicBlock::COUNT_NO_PROFILE &&
            branchIt->Count > 0) {
          if (bb->getKnownExecutionCount() == 0 ||
              succ->getKnownExecutionCount() == 0) {
            errs() << "BOLT-WARNING: Profile verification failed after ICP for "
                      "function "
                   << func << '\n';
            valid = false;
          }
        }
        ++branchIt;
      }
    }
  }
  return valid;
}
}

// Constructor implementation
IndirectCallPromotion::Callsite::Callsite(BinaryFunction &BF,
                                          const IndirectCallProfile &profile)
    : From(BF.getSymbol()), To(profile.Offset), Mispreds(profile.Mispreds),
      Branches(profile.Count) {
  if (profile.Symbol) {
    To.Sym = profile.Symbol;
    To.Addr = 0;
  }
}

void IndirectCallPromotion::printDecision(
    raw_ostream &OS,
    std::vector<Callsite> &targets, unsigned N) const {
  uint64_t totalBranches = 0;
  uint64_t totalMispredictions = 0;
  for (const Callsite &site : targets) {
    totalBranches += site.Branches;
    totalMispredictions += site.Mispreds;
  }
  if (totalBranches == 0) totalBranches = 1;
  if (totalMispredictions == 0) totalMispredictions = 1;

  OS << "BOLT-INFO: ICP decision for call site with " << targets.size()
     << " targets, Count = " << totalBranches << ", Mispreds = " 
     << totalMispredictions << "\n";

  size_t idx = 0;
  for (const Callsite &site : targets) {
    OS << "Count = " << site.Branches << ", "
       << format("%.1f", (100.0 * site.Branches) / totalBranches) << ", "
       << "Mispreds = " << site.Mispreds << ", "
       << format("%.1f", (100.0 * site.Mispreds) / totalMispredictions);
    if (idx < N)
      OS << " * to be optimized *";
    if (!site.JTIndices.empty()) {
      OS << " Indices:";
      for (uint64_t index : site.JTIndices)
        OS << " " << index;
    }
    OS << "\n";
    idx += site.JTIndices.empty() ? 1 : site.JTIndices.size();
  }
}

std::vector<IndirectCallPromotion::Callsite>
IndirectCallPromotion::getCallTargets(BinaryBasicBlock &BB,
                                      const MCInst &inst) const {
  BinaryFunction &func = *BB.getFunction();
  const BinaryContext &ctx = func.getBinaryContext();
  std::vector<Callsite> candidates;

  if (const JumpTable *jt = func.getJumpTable(inst)) {
    // Skip PIC jump tables unless targeting targets directly
    if (!opts::OptimizeJumpTableByTarget && jt->Type == JumpTable::JTT_PIC)
      return candidates;

    const Location from(func.getSymbol());
    const std::pair<size_t, size_t> range =
        jt->getEntriesForAddress(ctx.MIB->getJumpTable(inst));
    assert(jt->Counts.empty() || jt->Counts.size() >= range.second);

    JumpTable::JumpInfo defaultJI;
    const JumpTable::JumpInfo *ji =
        jt->Counts.empty() ? &defaultJI : &jt->Counts[range.first];
    const size_t jiStep = jt->Counts.empty() ? 0 : 1;

    for (size_t i = range.first; i < range.second; ++i, ji += jiStep) {
      MCSymbol *entry = jt->Entries[i];
      if (entry == func.getFunctionEndLabel() ||
          entry == func.getFunctionColdEndLabel())
        continue;

      const Location to(entry);
      const BinaryBasicBlock::BinaryBranchInfo &bi = BB.getBranchInfo(entry);
      candidates.emplace_back(from, to, bi.MispredictedCount, bi.Count,
                              i - range.first);
    }

    // Sort by symbol or address
    std::sort(candidates.begin(), candidates.end(),
              [](const Callsite &a, const Callsite &b) {
                if (a.To.Sym && b.To.Sym)
                  return a.To.Sym < b.To.Sym;
                else if (a.To.Sym && !b.To.Sym)
                  return true;
                else if (!a.To.Sym && b.To.Sym)
                  return false;
                else
                  return a.To.Addr < b.To.Addr;
              });

    // Merge duplicate targets with different indices
    auto first = candidates.begin();
    auto last = candidates.end();
    auto result = first;
    while (++first != last) {
      Callsite &a = *result;
      const Callsite &b = *first;
      if (a.To.Sym && b.To.Sym && a.To.Sym == b.To.Sym)
        a.JTIndices.insert(a.JTIndices.end(), b.JTIndices.begin(),
                           b.JTIndices.end());
      else
        *(++result) = *first;
    }
    ++result;
    LLVM_DEBUG(if (candidates.end() - result > 0) {
      dbgs() << "BOLT-INFO: ICP: " << (candidates.end() - result)
             << " duplicate targets removed\n";
    });
    candidates.erase(result, candidates.end());

  } else {
    // Skip PC-relative indirect calls
    if (inst.getOperand(0).isReg() &&
        inst.getOperand(0).getReg() == ctx.MRI->getProgramCounter())
      return candidates;

    const auto ICSP = ctx.MIB->tryGetAnnotationAs<IndirectCallSiteProfile>(
        inst, "CallProfile");
    if (ICSP) {
      for (const IndirectCallProfile &csp : ICSP.get()) {
        Callsite site(func, csp);
        if (site.isValid())
          candidates.emplace_back(std::move(site));
      }
    }
  }

  // Sort by branches, then indices count, then mispredicts, then address
  std::stable_sort(candidates.begin(), candidates.end(),
                   [](const Callsite &a, const Callsite &b) {
                     if (a.Branches != b.Branches)
                       return a.Branches > b.Branches;
                     if (a.JTIndices.size() != b.JTIndices.size())
                       return a.JTIndices.size() < b.JTIndices.size();
                     if (a.Mispreds != b.Mispreds)
                       return a.Mispreds > b.Mispreds;
                     return a.To.Addr < b.To.Addr;
                   });

  // Remove non-symbol targets
  auto last = std::remove_if(candidates.begin(), candidates.end(),
                             [](const Callsite &cs) { return !cs.To.Sym; });
  candidates.erase(last, candidates.end());

  LLVM_DEBUG(if (func.getJumpTable(inst)) {
    uint64_t totalBranches = 0;
    uint64_t totalMispredictions = 0;
    for (const Callsite &s : candidates) {
      totalBranches += s.Branches;
      totalMispredictions += s.Mispreds;
    }
    if (!totalBranches) totalBranches = 1;
    if (!totalMispredictions) totalMispredictions = 1;
    dbgs() << "BOLT-INFO: ICP: jump table size = " << candidates.size()
           << ", Count = " << totalBranches << ", Mispreds = " 
           << totalMispredictions << "\n";
    size_t i = 0;
    for (const Callsite &s : candidates) {
      dbgs() << "Count[" << i << "] = " << s.Branches << ", "
             << format("%.1f", (100.0 * s.Branches) / totalBranches) << ", "
             << "Mispreds[" << i << "] = " << s.Mispreds << ", "
             << format("%.1f", (100.0 * s.Mispreds) / totalMispredictions) << "\n";
      ++i;
    }
  });

  return candidates;
}

