        xmlrpc_asset_provider_ = std::make_shared<XMLRPCAssetProvider>(framework_);
        manager_->RegisterAssetProvider(xmlrpc_asset_provider_);

        // HTTP handler registered next to intercept texture requests via UUID
        http_asset_provider_ = std::make_shared<QtHttpAssetProvider>(framework_);
        manager_->RegisterAssetProvider(http_asset_provider_);

        // Local asset provider with default directory
        local_asset_provider_ = std::make_shared<LocalAssetProvider>(framework_, "./data/assets");
        manager_->RegisterAssetProvider(local_asset_provider_);

        // Fallback: UDP-based provider
        udp_asset_provider_ = std::make_shared<UDPAssetProvider>(framework_);
        manager_->RegisterAssetProvider(udp_asset_provider_);

        framework_category_id_ = framework_->GetEventManager()->QueryEventCategory("Framework");
    }

    void AssetModule::PostInitialize()
    {
        Console::Command cmd = Console::CreateCommand(
            "RequestAsset",
            "Request asset from server. Usage: RequestAsset(uuid,assettype)",
            Console::Bind(this, &AssetModule::ConsoleRequestAsset)
        );
        RegisterConsoleCommand(std::move(cmd));
    }

    void AssetModule::SubscribeToNetworkEvents(boost::weak_ptr<ProtocolUtilities::ProtocolModuleInterface> protoModule)
    {
        protocolModule_ = protoModule;
        if (udp_asset_provider_)
            udp_asset_provider_->SetCurrentProtocolModule(protocolModule_);

        network_state_category_id_ = framework_->GetEventManager()->QueryEventCategory("NetworkState");
        inboundcategory_id_ = framework_->GetEventManager()->QueryEventCategory("NetworkIn");
    }

    void AssetModule::UnsubscribeNetworkEvents()
    {
        // Currently no cleanup needed on unsubscription
    }

    // virtual
    void AssetModule::Update(f64 delta_time)
    {
        {
            PROFILE(AssetModule_Update);
            if (manager_)
                manager_->Update(delta_time);
        }
        RESETPROFILER;
    }

    // virtual 
    void AssetModule::Uninitialize()
    {
        if (manager_)
        {
            manager_->UnregisterAssetProvider(udp_asset_provider_);
            manager_->UnregisterAssetProvider(xmlrpc_asset_provider_);
            manager_->UnregisterAssetProvider(local_asset_provider_);
            manager_->UnregisterAssetProvider(http_asset_provider_);
            framework_->GetServiceManager()->UnregisterService(manager_);
        }
        manager_.reset();
    }

    Console::CommandResult AssetModule::ConsoleRequestAsset(const StringVector &params)
    {
        if (params.size() != 2u)
            return Console::ResultFailure("Usage: RequestAsset(uuid,assettype)");

        manager_->RequestAsset(params[0], params[1]);
        return Console::ResultSuccess();
    }

    bool AssetModule::HandleEvent(
        event_category_id_t cat_id,
        event_id_t evt_id,
        IEventData* payload)
    {
        PROFILE(AssetModule_HandleEvent);

        if (cat_id == inboundcategory_id_)
        {
            if (udp_asset_provider_)
                return checked_static_cast<UDPAssetProvider*>(udp_asset_provider_.get())->HandleNetworkEvent(payload);
        }
        else if (cat_id == framework_category_id_ && evt_id == Foundation::NETWORKING_REGISTERED)
        {
            auto* netRegEvent = dynamic_cast<ProtocolUtilities::NetworkingRegisteredEvent*>(payload);
            if (netRegEvent)
                SubscribeToNetworkEvents(netRegEvent->currentProtocolModule);
            return false;
        }

        if (cat_id == network_state_category_id_ && evt_id == ProtocolUtilities::Events::EVENT_SERVER_DISCONNECTED)
        {
            if (udp_asset_provider_)
                checked_static_cast<UDPAssetProvider*>(udp_asset_provider_.get())->ClearAllTransfers();
            if (http_asset_provider_)
                checked_static_cast<QtHttpAssetProvider*>(http_asset_provider_.get())->ClearAllTransfers();
        }

        if (cat_id == network_state_category_id_ && evt_id == ProtocolUtilities::Events::EVENT_CAPS_FETCHED)
        {
            auto sp_proto = protocolModule_.lock();
            if (sp_proto && http_asset_provider_)
            {
                std::string cap_url = sp_proto->GetCapability("GetTexture");
                checked_static_cast<QtHttpAssetProvider*>(http_asset_provider_.get())->SetGetTextureCap(cap_url);
            }
        }

        return false;
    }
}

