// Helper lambda to map framebuffer status codes to human-readable messages
static auto makeFramebufferErrorMessage = [](GLenum status) -> std::string {
    switch (status) {
        case GL_FRAMEBUFFER_UNDEFINED:
            return "Frame Buffer creation error code: GL_FRAMEBUFFER_UNDEFINED";
        case GL_FRAMEBUFFER_INCOMPLETE_ATTACHMENT:
            return "Frame Buffer creation error code: GL_FRAMEBUFFER_INCOMPLETE_ATTACHMENT";
        case GL_FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT:
            return "Frame Buffer creation error code: GL_FRAMEBUFFER_INCOMPLETE_MISSING_ATTACHMENT";
        case GL_FRAMEBUFFER_UNSUPPORTED:
            return "Frame Buffer creation error code: GL_FRAMEBUFFER_UNSUPPORTED";
        case GL_FRAMEBUFFER_INCOMPLETE_MULTISAMPLE:
            return "Frame Buffer creation error code: GL_FRAMEBUFFER_INCOMPLETE_MULTISAMPLE";
        default:
            return "Frame Buffer creation error code: UNKNOWN (You should be very scared about this)";
    }
};

// Validate framebuffer completeness and log detailed info on failure
void Framebuffer::checkFrameBufferStatus() {
    const GLenum fbs = glCheckFramebufferStatus(GL_FRAMEBUFFER);
    if (fbs == GL_FRAMEBUFFER_COMPLETE) {
        return;
    }

    const std::string errMessage = makeFramebufferErrorMessage(fbs);

    LOGRS("Framebuffer \"" << mName << "\" size: [" << mWidth << ":" << mHeight 
                           << "] format : [" 
                           << glEnumToString(pixelFormatToGlInternalFormat(mFormat)) 
                           << "] Texture Slot: [" << mTextureGPUSlot << "]");
}

// Determine texture target based on multisampling
GLenum Framebuffer::framebufferTextureTarget(bool _multisampled) {
    return _multisampled ? GL_TEXTURE_2D_MULTISAMPLE : GL_TEXTURE_2D;
}

// Attach a texture to the framebuffer at specified attachment point
void Framebuffer::framebufferTexture2D(GLuint rth, const std::string& renderTargetIndex, [[maybe_unused]] int mipMapIndex) {
    if (mCubeMap) {
        const GLenum targetSide = nameToCubeMapSide(renderTargetIndex);
        GLCALL(glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, targetSide, rth, mipMapIndex));
    } else {
        const GLenum texTarget = framebufferTextureTarget(mMultisample);
        GLCALL(glFramebufferTexture2D(GL_FRAMEBUFFER, GL_COLOR_ATTACHMENT0, texTarget, rth, mipMapIndex));
    }
}

