#include "numbers.dat"
#include <iostream>
#include <memory>

int main(int argc, char *argv[]) {
    const int max = 100001;

    // Allocate memory for prime checking array using smart pointer
    std::unique_ptr<bool[]> isPrime_ptr(new bool[max]);
    bool* isPrime = isPrime_ptr.get();

    // Initialize all numbers as potentially prime
    for (int i = 0; i < max; ++i) {
        isPrime[i] = true;
    }

    // Mark 0 and 1 as not prime
    isPrime[0] = false;
    isPrime[1] = false;

    // Sieve of Eratosthenes to find primes
    for (int i = 2; i * i < max; ++i) {
        if (isPrime[i]) {
            for (int j = i * i; j < max; j += i) {
                isPrime[j] = false;
            }
        }
    }

    // Create prefix sum array for counting primes up to each position
    std::unique_ptr<int[]> prefixCount_ptr(new int[Size]);
    int* prefixCount = prefixCount_ptr.get();

    prefixCount[0] = isPrime[Data[0]] ? 1 : 0;
    for (int i = 1; i < Size; ++i) {
        prefixCount[i] = prefixCount[i - 1] + (isPrime[Data[i]] ? 1 : 0);
    }

    // Validate command line arguments
    if (argc % 2 != 1 || argc == 1) {
        return -1;
    }

    // Process each query pair
    for (int k = 1; k < argc; k += 2) {
        int n = std::atoi(argv[k]);
        int m = std::atoi(argv[k + 1]);

        // Check if range is valid
        if (m < n) {
            std::cout << 0 << std::endl;
            continue;
        }

        // Find index of n in Data array
        int idx_n = -1;
        for (int i = 0; i < Size; ++i) {
            if (Data[i] == n) {
                idx_n = i;
                break;
            }
        }

        if (idx_n == -1) {
            std::cout << 0 << std::endl;
            continue;
        }

        // Find index of m in Data array
        int idx_m = -1;
        for (int i = Size - 1; i >= 0; --i) {
            if (Data[i] == m) {
                idx_m = i;
                break;
            }
        }

        if (idx_m == -1) {
            std::cout << 0 << std::endl;
            continue;
        }

        // Calculate count of primes between n and m inclusive
        int primeCount = prefixCount[idx_m] - prefixCount[idx_n] + (isPrime[Data[idx_n]] ? 1 : 0);
        std::cout << primeCount << std::endl;
    }

    return 0;
}

