//===----------------------------------------------------------------------===//
// Command-line Interface
//===----------------------------------------------------------------------===//

static cl::opt<std::string>
    inputFile(cl::Positional, cl::desc("<input file>"), cl::Required);

static cl::opt<std::string>
    outputFile("o", cl::init("-"),
               cl::desc("Destination for the minimized test case"));

static cl::opt<bool>
    preserveBest("keep-best", cl::init(false),
                 cl::desc("Persist improved reductions to output file"));

static cl::opt<std::string> testCmd(
    "test", cl::Required,
    cl::desc("Executable or script used to determine interestingness"));

static cl::list<std::string>
    testArgs("test-arg", cl::ZeroOrMore,
             cl::desc("Extra arguments passed to the test command"));

//===----------------------------------------------------------------------===//
// Utility Functions
//===----------------------------------------------------------------------===//

/// Writes the current module state to the configured output path.
static LogicalResult saveModule(ModuleOp mod) {
  std::string err;
  auto out = openOutputFile(outputFile, &err);
  if (!out) {
    emitError(UnknownLoc::get(mod.getContext()),
              "cannot open output file '")
        << outputFile << "': " << err << "\n";
    return failure();
  }
  mod.print(out->os());
  out->keep();
  return success();
}

/// Main driver: loads input, applies reduction strategies iteratively.
static LogicalResult run(MLIRContext &ctx) {
  std::string err;

  // Load input IR
  LLVM_DEBUG(dbgs() << "Loading input IR...\n");
  OwningModuleRef ir = parseSourceFile(inputFile, &ctx);
  if (!ir)
    return failure();

  // Validate initial interestingness
  LLVM_DEBUG({
    dbgs() << "Running tester: `" << testCmd << "`\n";
    for (const auto &arg : testArgs)
      dbgs() << "  arg: `" << arg << "`\n";
  });

  Tester evaluator(testCmd, testArgs);
  auto baseline = evaluator.isInteresting(ir.get());
  if (baseline.first != Tester::Interestingness::True) {
    emitError(UnknownLoc::get(&ctx), "input is not interesting");
    return failure();
  }

  size_t bestSize = baseline.second;
  LLVM_DEBUG(dbgs() << "Initial size: " << bestSize << "\n");

  // Collect all available reduction passes
  SmallVector<std::unique_ptr<Reduction>> strategies;
  createAllReductions(&ctx, [&](auto strat) {
    strategies.emplace_back(std::move(strat));
  });

  // Iterative reduction loop over strategies
  unsigned strategyIdx = 0;
  while (strategyIdx < strategies.size()) {
    Reduction &pass = *strategies[strategyIdx];
    LLVM_DEBUG(dbgs() << "Applying reduction: `" << pass.getName() << "`\n");

    size_t startIdx = 0;
    size_t chunkSize = static_cast<size_t>(-1);
    bool reducedSoFar = false;

    while (chunkSize > 0) {
      size_t opCount = 0;
      OwningModuleRef candidate = ir->clone();
      candidate->walk([&](Operation *op) {
        if (!pass.match(op)) return;
        auto idx = opCount++;
        if (idx < startIdx || idx - startIdx >= chunkSize) return;
        (void)pass.rewrite(op);
      });

      if (opCount == 0) {
        LLVM_DEBUG(dbgs() << "- No matching operations left\n");
        break;
      }

      auto result = evaluator.isInteresting(candidate.get());
      if (result.first == Tester::Interestingness::True &&
          (result.second < bestSize || pass.acceptSizeIncrease())) {
        reducedSoFar = true;
        bestSize = result.second;
        LLVM_DEBUG(dbgs() << "- Accepted new size: " << bestSize << "\n");
        ir = std::move(candidate);

        if (chunkSize == static_cast<size_t>(-1)) {
          chunkSize = 0; // Done with full scan
        } else {
          startIdx = 0;
          chunkSize = static_cast<size_t>(-1);
        }

        if (preserveBest && failed(saveModule(ir.get())))
          return failure();
      } else {
        startIdx += chunkSize;
        if (startIdx >= opCount) {
          chunkSize = std::min(chunkSize, opCount) / 2;
          startIdx = 0;
          if (chunkSize > 0)
            LLVM_DEBUG(dbgs() << "- Trying chunks of " << chunkSize << " ops\n");
        }
      }
    }

    if (reducedSoFar && strategyIdx > 0) {
      LLVM_DEBUG(dbgs() << "- Strategy `" << pass.getName()
                        << "` succeeded; restarting from first strategy\n\n");
      strategyIdx = 0;
    } else {
      ++strategyIdx;
    }
  }

  LLVM_DEBUG(dbgs() << "All strategies exhausted.\n");
  return saveModule(ir.get());
}

//===----------------------------------------------------------------------===//
// Entry Point
//===----------------------------------------------------------------------===//

int main(int argc, char **argv) {
  InitLLVM init(argc, argv);
  registerMLIRContextCLOptions();
  registerAsmPrinterCLOptions();
  cl::ParseCommandLineOptions(argc, argv,
                              "CIRCT test case minimizer\n");

  DialectRegistry registry;
  registerAllDialects(registry);
  MLIRContext ctx(registry);

  exit(failed(run(ctx)));
}

