namespace rt {
namespace math {

Distribution::Distribution()
    : mPDF(nullptr)
    , mCDF(nullptr)
    , mSize(0)
{}

Distribution::~Distribution()
{
    if (mCDF) {
        DefaultAllocator::Free(mCDF);
        mCDF = nullptr;
    }
    if (mPDF) {
        DefaultAllocator::Free(mPDF);
        mPDF = nullptr;
    }
}

bool Distribution::Initialize(const float* pdfValues, uint32 numValues)
{
    // Validate input parameters
    if (numValues == 0u)
    {
        RT_LOG_ERROR("Empty distribution provided");
        return false;
    }

    if (!pdfValues)
    {
        RT_LOG_ERROR("Null pointer passed for PDF values");
        return false;
    }

    // Allocate memory for PDF array
    mPDF = static_cast<float*>(DefaultAllocator::Allocate(sizeof(float) * static_cast<size_t>(numValues), RT_CACHE_LINE_SIZE));
    if (!mPDF)
    {
        RT_LOG_ERROR("Memory allocation failed for PDF buffer");
        return false;
    }

    // Allocate memory for CDF array (size + 1 for cumulative sums)
    mCDF = static_cast<float*>(DefaultAllocator::Allocate(sizeof(float) * (static_cast<size_t>(numValues) + 1u), RT_CACHE_LINE_SIZE));
    if (!mCDF)
    {
        RT_LOG_ERROR("Memory allocation failed for CDF buffer");
        return false;
    }

    // Compute unnormalized cumulative distribution function
    float totalSum = 0.0f;
    mCDF[0] = 0.0f;

    for (uint32 idx = 0; idx < numValues; ++idx)
    {
        RT_ASSERT(IsValid(pdfValues[idx]), "Invalid PDF value detected");
        RT_ASSERT(pdfValues[idx] >= 0.0f, "All PDF values must be non-negative");

        totalSum += pdfValues[idx];
        mCDF[idx + 1] = totalSum;
    }

    RT_ASSERT(totalSum > 0.0f, "Total PDF weight must be positive");

    // Normalize both CDF and PDF
    const float invTotalSum = 1.0f / totalSum;
    const float pdfScale = invTotalSum * static_cast<float>(numValues);

    for (uint32 i = 0; i < numValues; ++i)
    {
        mCDF[i] *= invTotalSum;
        mPDF[i] = pdfValues[i] * pdfScale;
    }
    mCDF[numValues] *= invTotalSum;

    mSize = numValues;
    return true;
}

uint32 Distribution::SampleDiscrete(const float u, float& outPdf) const
{
    // Binary search to find the index where u falls in the CDF
    uint32 left = 0u;
    uint32 right = mSize;

    while (left < right)
    {
        uint32 mid = left + ((right - left) >> 1); // Avoid overflow and use bit shift for division by 2

        if (u >= mCDF[mid])
        {
            left = mid + 1u;
        }
        else
        {
            right = mid;
        }
    }

    // The sample index is one less than the found position
    uint32 sampleIndex = left - 1u;
    outPdf = mPDF[sampleIndex];

    return sampleIndex;
}

