#include "sketch/pc.h"
using namespace sketch;

int main() {
    // Initialize two probabilistic counters and two PCSA structures
    ProbabilisticCounter<uint64_t> counter1, counter2;
    PCSA<uint64_t> pcsaStructure1(1000);
    wy::WyRand<uint64_t> randomGenerator;

    // First batch: add 100,000 hashed values to both counters
    for (size_t idx = 0; idx < 100000; ++idx) {
        uint64_t value = randomGenerator();
        counter1.addh(value);
        pcsaStructure1.addh(value);
    }

    // Second batch: initialize new counters and add another 100,000 hashed values
    PCSA<uint64_t> pcsaStructure2(1000);
    for (size_t idx = 0; idx < 100000; ++idx) {
        uint64_t value = randomGenerator();
        counter2.addh(value);
        pcsaStructure2.addh(value);
    }

    // Output cardinality estimates for individual runs
    std::fprintf(stderr, "100000: %g, pcsa: %g\n", counter1.report(), pcsaStructure1.report());
    std::fprintf(stderr, "100000: %g, pcsa: %g\n", counter2.report(), pcsaStructure2.report());

    // Merge the two counter pairs using bitwise OR operation
    pcsaStructure2 |= pcsaStructure1;
    counter2 |= counter1;

    // Output cardinality estimate for the union of both runs
    std::fprintf(stderr, "200000 (union): %g, pcsa: %g\n", counter2.report(), pcsaStructure2.report());

    return 0;
}

