// Reuse or forward-declare minimal types to avoid external dependencies in this example
namespace tket {

enum class Pauli { I, X, Y, Z };

struct BoolPauli {
  bool x, z;
  bool operator<(const BoolPauli& other) const {
    if (x == other.x) return z < other.z;
    return x < other.x;
  }
  Pauli to_pauli() const {
    if (x && z) return Pauli::Y;
    if (x) return Pauli::X;
    if (z) return Pauli::Z;
    return Pauli::I;
  }
  static const std::map<std::pair<BoolPauli, BoolPauli>, std::pair<BoolPauli, std::complex<double>>> mult_lut;
};

// Define multiplication lookup table inline for completeness
const std::map<std::pair<BoolPauli, BoolPauli>, std::pair<BoolPauli, std::complex<double>>>
    BoolPauli::mult_lut = {
        {{{false, false}, {false, false}}, {{false, false}, 1.}},
        {{{false, false}, {false, true}}, {{false, true}, 1.}},
        {{{false, false}, {true, false}}, {{true, false}, 1.}},
        {{{false, false}, {true, true}}, {{true, true}, 1.}},
        {{{false, true}, {false, false}}, {{false, true}, 1.}},
        {{{false, true}, {false, true}}, {{false, false}, 1.}},
        {{{false, true}, {true, false}}, {{true, true}, std::complex<double>(0, 1)}},
        {{{false, true}, {true, true}}, {{true, false}, std::complex<double>(0, -1)}},
        {{{true, false}, {false, false}}, {{true, false}, 1.}},
        {{{true, false}, {false, true}}, {{true, true}, std::complex<double>(0, -1)}},
        {{{true, false}, {true, false}}, {{false, false}, 1.}},
        {{{true, false}, {true, true}}, {{false, true}, std::complex<double>(0, 1)}},
        {{{true, true}, {false, false}}, {{true, true}, 1.}},
        {{{true, true}, {false, true}}, {{true, false}, std::complex<double>(0, 1)}},
        {{{true, true}, {true, false}}, {{false, true}, std::complex<double>(0, -1)}},
        {{{true, true}, {true, true}}, {{false, false}, 1.}}};

struct PauliStabiliser {
  std::vector<Pauli> string;
  bool coeff; // true means +1, false means -1
};

class SymplecticTableau {
public:
  using MatrixXb = std::vector<std::vector<bool>>;
  using VectorXb = std::vector<bool>;
  using Complex = std::complex<double>;

private:
  unsigned n_rows_, n_qubits_;
  MatrixXb xmat_, zmat_;
  VectorXb phase_;

  void row_mult_impl(
      const MatrixXb::value_type& xa, const MatrixXb::value_type& za,
      bool pa,
      const MatrixXb::value_type& xb, const MatrixXb::value_type& zb,
      bool pb,
      Complex phase,
      MatrixXb::value_type& xw, MatrixXb::value_type& zw, bool& pw);

  void col_mult_impl(
      const MatrixXb::value_type& a, const MatrixXb::value_type& b,
      bool flip,
      MatrixXb::value_type& w, VectorXb& pw);

public:
  SymplecticTableau(const MatrixXb& xmat, const MatrixXb& zmat, const VectorXb& phase);
  explicit SymplecticTableau(const std::vector<PauliStabiliser>& rows);

  unsigned get_n_rows() const { return n_rows_; }
  unsigned get_n_qubits() const { return n_qubits_; }

  PauliStabiliser get_pauli(unsigned i) const;

  friend std::ostream& operator<<(std::ostream& os, const SymplecticTableau& tab);

  bool operator==(const SymplecticTableau& other) const;

  void row_mult(unsigned ra, unsigned rw, Complex coeff);
  void apply_S(unsigned qb);
  void apply_V(unsigned qb);
  void apply_CX(unsigned qc, unsigned qt);
  void apply_gate(OpType type, const std::vector<unsigned>& qbs);
  void apply_pauli_gadget(const PauliStabiliser& pauli, unsigned half_pis);
  MatrixXb anticommuting_rows() const;
  unsigned rank() const;
  SymplecticTableau conjugate() const;
};

// Helper: convert Pauli enum to BoolPauli pair
inline std::pair<bool, bool> pauli_to_bools(Pauli p) {
  switch (p) {
    case Pauli::X: return {true, false};
    case Pauli::Y: return {true, true};
    case Pauli::Z: return {false, true};
    default:       return {false, false};
  }
}

// Helper: build BoolPauli from Pauli enum
inline BoolPauli pauli_to_BoolPauli(Pauli p) {
  auto [x, z] = pauli_to_bools(p);
  return {x, z};
}

// Helper: compute anticommutation between two rows
inline bool rows_anticommute(
    const MatrixXb::value_type& xr, const MatrixXb::value_type& zr,
    const MatrixXb::value_type& xs, const MatrixXb::value_type& zs) {
  bool anti = false;
  for (size_t q = 0; q < xr.size(); ++q) {
    anti ^= (xr[q] && zs[q]) || (zr[q] && xs[q]);
  }
  return anti;
}

