// Helper function: constructs 4x4 projection matrix and its inverse
inline void BuildProjectionMatrices(const double intrinsics[9],
                                    const double rotation[9],
                                    const double translation[3],
                                    const double final_row[4],
                                    double proj_matrix_out[16],
                                    double inv_proj_matrix_out[16]) {
    // Construct 3x4 projection matrix P = K * [R | t]
    Eigen::Matrix<double, 3, 4, Eigen::RowMajor> temp_3x4;
    temp_3x4.block<3, 3>(0, 0) = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(rotation);
    temp_3x4.col(3) = Eigen::Map<const Eigen::Matrix<double, 3, 1>>(translation);
    temp_3x4 = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(intrinsics) * temp_3x4;

    // Extend to 4x4
    Eigen::Matrix<double, 4, 4, Eigen::RowMajor> full_proj;
    full_proj.block<3, 4>(0, 0) = temp_3x4;
    full_proj.row(3) = Eigen::Map<const Eigen::Matrix<double, 1, 4>>(final_row);

    // Numerical stabilization: scale so max entry is ~10
    const double scale_factor = 10.0 / full_proj.maxCoeff();
    full_proj *= scale_factor;

    // Copy forward projection
    std::copy(full_proj.data(), full_proj.data() + 16, proj_matrix_out);

    // Compute inverse and stabilize similarly
    Eigen::Matrix<double, 4, 4, Eigen::RowMajor> inv_full_proj = full_proj.inverse();
    const double inv_scale_factor = 10.0 / inv_full_proj.maxCoeff();
    inv_full_proj *= inv_scale_factor;

    std::copy(inv_full_proj.data(), inv_full_proj.data() + 16, inv_proj_matrix_out);
}

// Helper function: compute camera center from R and T
inline void CalculateCameraCenter(const double rotation[9], const double translation[3], double center_out[3]) {
    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> rot_mat(rotation);
    Eigen::Map<const Eigen::Matrix<double, 3, 1>> trans_vec(translation);
    Eigen::Matrix<double, 3, 1> cam_center = -rot_mat.transpose() * trans_vec;
    std::copy(cam_center.data(), cam_center.data() + 3, center_out);
}

// Helper function: convert double array to float array
inline void ConvertDoubleToFloat(const double* src, float* dst, size_t count) {
    for (size_t idx = 0; idx < count; ++idx) {
        dst[idx] = static_cast<float>(src[idx]);
    }
}

