float Image::GetDepth(double x, double y, double z) const {
    // Reconstruct 3x4 projection matrix
    Eigen::Matrix<double, 3, 4, Eigen::RowMajor> proj_3x4;
    proj_3x4.block<3, 3>(0, 0) = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(R_);
    proj_3x4.col(3) = Eigen::Map<const Eigen::Matrix<double, 3, 1>>(T_);
    proj_3x4 = Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>>(K_) * proj_3x4;

    // Build 4x4 matrix with last row
    Eigen::Matrix<double, 4, 4, Eigen::RowMajor> proj_4x4;
    proj_4x4.block<3, 4>(0, 0) = proj_3x4;
    proj_4x4.row(3) = Eigen::Map<const Eigen::Matrix<double, 1, 4>>(last_row_);

    // Apply to homogeneous point
    Eigen::Matrix<double, 4, 1> point(x, y, z, 1.0);
    Eigen::Matrix<double, 4, 1> projected = proj_4x4 * point;

    // Depth = w / z (homogeneous division)
    double depth_val = projected[3] / projected[2];
    return static_cast<float>(depth_val);
}

