void Image::Original(float K[9], float inv_K[9], float R[9], float T[3], float P[16], float inv_P[16], float C[3]) const {
    double P_double[16];
    double inv_P_double[16];
    BuildProjectionMatrices(K_, R_, T_, last_row_, P_double, inv_P_double);

    double C_double[3];
    CalculateCameraCenter(R_, T_, C_double);

    // Invert K manually
    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> K_mat(K_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> K_inv = K_mat.inverse();

    ConvertDoubleToFloat(K_, K, 9);
    ConvertDoubleToFloat(K_inv.data(), inv_K, 9);
    ConvertDoubleToFloat(R_, R, 9);
    ConvertDoubleToFloat(T_, T, 3);
    ConvertDoubleToFloat(P_double, P, 16);
    ConvertDoubleToFloat(inv_P_double, inv_P, 16);
    ConvertDoubleToFloat(C_double, C, 3);
}

