void Image::Rotate90Multi(int cnt, float K[9], float inv_K[9], float R[9], float T[3], float P[16], float inv_P[16], float C[3]) const {
    switch (cnt % 4) {
        case 0:
            Original(K, inv_K, R, T, P, inv_P, C);
            break;
        case 1:
            Rotate90(K, inv_K, R, T, P, inv_P, C);
            break;
        case 2:
            Rotate180(K, inv_K, R, T, P, inv_P, C);
            break;
        case 3:
            Rotate270(K, inv_K, R, T, P, inv_P, C);
            break;
        default:
            break;
    }
}

void Image::Rotate90(float K[9], float inv_K[9], float R[9], float T[3], float P[16], float inv_P[16], float C[3]) const {
    // Adjust intrinsics
    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> old_intrin(K_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> A;
    A << 0, 1, 0,
         -1, 0, static_cast<double>(width_ - 1),
         0, 0, 1;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> B;
    B << 0, -1, 0,
         1, 0, 0,
         0, 0, 1;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_intrin = A * old_intrin * B;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_intrin_inv = new_intrin.inverse();

    // Adjust extrinsics
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> rot;
    rot << 0, 1, 0,
           -1, 0, 0,
           0, 0, 1;
    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> old_rot(R_);
    Eigen::Map<const Eigen::Matrix<double, 3, 1>> old_trans(T_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_rot = rot * old_rot;
    Eigen::Matrix<double, 3, 1> new_trans = rot * old_trans;

    double P_new[16], inv_P_new[16];
    BuildProjectionMatrices(new_intrin.data(), new_rot.data(), new_trans.data(), last_row_, P_new, inv_P_new);

    double C_new[3];
    CalculateCameraCenter(new_rot.data(), new_trans.data(), C_new);

    ConvertDoubleToFloat(new_intrin.data(), K, 9);
    ConvertDoubleToFloat(new_intrin_inv.data(), inv_K, 9);
    ConvertDoubleToFloat(new_rot.data(), R, 9);
    ConvertDoubleToFloat(new_trans.data(), T, 3);
    ConvertDoubleToFloat(P_new, P, 16);
    ConvertDoubleToFloat(inv_P_new, inv_P, 16);
    ConvertDoubleToFloat(C_new, C, 3);
}

void Image::Rotate180(float K[9], float inv_K[9], float R[9], float T[3], float P[16], float inv_P[16], float C[3]) const {
    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> old_intrin(K_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> A;
    A << -1, 0, static_cast<double>(width_ - 1),
          0, -1, static_cast<double>(height_ - 1),
          0, 0, 1;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> B;
    B << -1, 0, 0,
          0, -1, 0,
          0, 0, 1;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_intrin = A * old_intrin * B;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_intrin_inv = new_intrin.inverse();

    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> rot;
    rot << 0, 1, 0,
           -1, 0, 0,
           0, 0, 1;
    rot = rot * rot;

    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> old_rot(R_);
    Eigen::Map<const Eigen::Matrix<double, 3, 1>> old_trans(T_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_rot = rot * old_rot;
    Eigen::Matrix<double, 3, 1> new_trans = rot * old_trans;

    double P_new[16], inv_P_new[16];
    BuildProjectionMatrices(new_intrin.data(), new_rot.data(), new_trans.data(), last_row_, P_new, inv_P_new);

    double C_new[3];
    CalculateCameraCenter(new_rot.data(), new_trans.data(), C_new);

    ConvertDoubleToFloat(new_intrin.data(), K, 9);
    ConvertDoubleToFloat(new_intrin_inv.data(), inv_K, 9);
    ConvertDoubleToFloat(new_rot.data(), R, 9);
    ConvertDoubleToFloat(new_trans.data(), T, 3);
    ConvertDoubleToFloat(P_new, P, 16);
    ConvertDoubleToFloat(inv_P_new, inv_P, 16);
    ConvertDoubleToFloat(C_new, C, 3);
}

void Image::Rotate270(float K[9], float inv_K[9], float R[9], float T[3], float P[16], float inv_P[16], float C[3]) const {
    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> old_intrin(K_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> A;
    A << 0, -1, static_cast<double>(height_ - 1),
         1, 0, 0,
         0, 0, 1;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> B;
    B << 0, 1, 0,
        -1, 0, 0,
         0, 0, 1;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_intrin = A * old_intrin * B;
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_intrin_inv = new_intrin.inverse();

    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> rot;
    rot << 0, 1, 0,
           -1, 0, 0,
           0, 0, 1;
    rot = rot * rot * rot;

    Eigen::Map<const Eigen::Matrix<double, 3, 3, Eigen::RowMajor>> old_rot(R_);
    Eigen::Map<const Eigen::Matrix<double, 3, 1>> old_trans(T_);
    Eigen::Matrix<double, 3, 3, Eigen::RowMajor> new_rot = rot * old_rot;
    Eigen::Matrix<double, 3, 1> new_trans = rot * old_trans;

    double P_new[16], inv_P_new[16];
    BuildProjectionMatrices(new_intrin.data(), new_rot.data(), new_trans.data(), last_row_, P_new, inv_P_new);

    double C_new[3];
    CalculateCameraCenter(new_rot.data(), new_trans.data(), C_new);

    ConvertDoubleToFloat(new_intrin.data(), K, 9);
    ConvertDoubleToFloat(new_intrin_inv.data(), inv_K, 9);
    ConvertDoubleToFloat(new_rot.data(), R, 9);
    ConvertDoubleToFloat(new_trans.data(), T, 3);
    ConvertDoubleToFloat(P_new, P, 16);
    ConvertDoubleToFloat(inv_P_new, inv_P, 16);
    ConvertDoubleToFloat(C_new, C, 3);
}

void Image::Rescale(const float factor) { Rescale(factor, factor); }

void Image::Rescale(const float factor_x, const float factor_y) {
    const size_t new_width = static_cast<size_t>(std::round(width_ * factor_x));
    const size_t new_height = static_cast<size_t>(std::round(height_ * factor_y));

    if (bitmap_.Data() != nullptr) {
        bitmap_.Rescale(new_width, new_height);
    }

    const double scale_x = static_cast<double>(new_width) / static_cast<double>(width_);
    const double scale_y = static_cast<double>(new_height) / static_cast<double>(height_);

    K_[0] *= scale_x;
    K_[1] *= scale_x;
    K_[2] *= scale_x;
    K_[4] *= scale_y;
    K_[5] *= scale_y;

    width_ = new_width;
    height_ = new_height;
}

void Image::Downsize(const size_t max_width, const size_t max_height) {
    if (width_ <= max_width && height_ <= max_height) {
        return;
    }

    const float factor_x = static_cast<float>(max_width) / static_cast<float>(width_);
    const float factor_y = static_cast<float>(max_height) / static_cast<float>(height_);
    Rescale(std::min(factor_x, factor_y));
}

