	// Returns index of first occurrence of any character from searchCharacters in stringToSearch starting at startIndex
	static int IndexOfAny(const std::string& inputString, const std::vector<char>& targets, size_t startPos) {
		if (inputString.empty() || targets.empty() || startPos >= inputString.size()) {
			return -1;
		}

		for (size_t idx = startPos; idx < inputString.size(); ++idx) {
			char currentChar = inputString[idx];
			if (std::find(targets.begin(), targets.end(), currentChar) != targets.end()) {
				return static_cast<int>(idx);
			}
		}
		return -1;
	}

	// Empties the queue by repeatedly popping until empty (note: original had bug: while(queue.empty()) should be while(!queue.empty()))
	static void ClearQueue(std::queue<std::string>& queueToClear) {
		while (!queueToClear.empty()) {
			queueToClear.pop();
		}
	}

	// Appends elements from raw array to vector buffer
	static void AppendRange(std::vector<char>& destination, const char* source, size_t count) {
		destination.insert(destination.end(), source, source + count);
	}

	// Copies contents of vector into pre-allocated char array
	static void CopyVectorToBuffer(const std::vector<char>& source, char* target) {
		size_t len = std::min(source.size(), static_cast<size_t>(8190)); // safety cap
		for (size_t i = 0; i < len; ++i) {
			target[i] = source[i];
		}
	}

	// Placeholder method for callback reset
	static void NoOpCallback(std::string&) { }

#pragma endregion

