	void ClientBase::RegisterDisconnectionHandler(OnDisconnection handler) {
		disconnectionCallback = handler;
	}

	void ClientBase::UnregisterDisconnectionHandler() {
		if (disconnectionCallback) {
			disconnectionCallback = NoOpCallback;
		}
	}

	bool ClientBase::IsConnected() const {
		return !isShuttingDown;
	}

	ClientBase::ClientBase()
		: errorOccured(false), isShuttingDown(true), sslEnabled(false) {
		pthread_mutex_init(&writeList_mutex, nullptr);
		pthread_mutex_init(&readList_mutex, nullptr);
		pthread_cond_init(&writeList_cond, nullptr);
		pthread_cond_init(&readList_cond, nullptr);
	}

