#pragma region Private Methods

	void ClientBase::start() {
		errorOccured = false;
		pthread_attr_t attributes;
		pthread_attr_init(&attributes);
		pthread_attr_setdetachstate(&attributes, PTHREAD_CREATE_DETACHED);

		pthread_create(&readerThread, &attributes, &ClientBase::readThreadEntry, this);
		pthread_create(&writerThread, &attributes, &ClientBase::writeThreadEntry, this);
		pthread_create(&progressThread, &attributes, &ClientBase::processThreadEntry, this);

		pthread_attr_destroy(&attributes);
	}

	bool ClientBase::shutdown(bool forceClose, bool alreadyClosed) {
		if (isShuttingDown) return true;

		isShuttingDown = true;
		closeSockets();
		clearDataStructures();

		if (!alreadyClosed && disconnectionCallback) {
			std::string msg = "Connection Failure: Lost connection with the server";
			disconnectionCallback(msg);
		}
		return true;
	}

	void ClientBase::enqueueWriteRequest(ResponseContainer request) {
		pthread_mutex_lock(&writeList_mutex);
		writeList.push(std::move(request));
		pthread_cond_broadcast(&writeList_cond);
		pthread_mutex_unlock(&writeList_mutex);
	}

	bool ClientBase::closeSockets() {
		errorOccured = true;

		if (sslEnabled) {
			BIO_free_all(bio);
			SSL_CTX_free(ctx);
			sslEnabled = false;
		}

#if !_WIN32
		if (!sslEnabled) {
			shutdown(_socket, SHUT_RDWR);
		}
#endif

		if (!sslEnabled)
			close(_socket);

#ifdef _WIN32
		if (!sslEnabled && wsaStarted) {
			WSACleanup();
		}
#endif
		return true;
	}

	void* ClientBase::writeThreadEntry(void* param) {
		return write(param);
	}

	void* ClientBase::write(void* threadId) {
		int result = 1;
		const char stx = '\x02';
		const char etx = '\x03';

		auto self = static_cast<ClientBase*>(threadId);

		while (self->IsConnected()) {
			if (result <= 0) break;

			pthread_mutex_lock(&self->writeList_mutex);
			if (self->writeList.empty()) {
				pthread_cond_wait(&self->writeList_cond, &self->writeList_mutex);
			}

			std::vector<ResponseContainer> batch;
			while (!self->writeList.empty()) {
				batch.emplace_back(std::move(self->writeList.front()));
				self->writeList.pop();
			}
			pthread_mutex_unlock(&self->writeList_mutex);

			if (!self->isShuttingDown && !self->errorOccured) {
				std::string xmlPayload = XmlRequest::CreateAllRequests(batch);
				if (xmlPayload.empty()) continue;

				result = self->sendData(&stx, sizeof(stx));
				if (result == -1) break;

				result = self->sendData(xmlPayload.c_str(), static_cast<int>(xmlPayload.size()));
				if (result == -1) break;

				result = self->sendData(&etx, sizeof(etx));
				if (result == -1) break;
			}
		}

		self->shutdown(false, false);
		pthread_exit(nullptr);
		return nullptr;
	}

	int ClientBase::sendData(const char* data, int length) {
		if (!sslEnabled) {
			return send(_socket, data, length, 0);
		}
		return BIO_write(bio, data, length);
	}

	void* ClientBase::readThreadEntry(void* param) {
		return read(param);
	}

	void* ClientBase::read(void* threadId) {
		std::vector<char> delimiters;
		delimiters.push_back('\x02');
		delimiters.push_back('\x03');

		std::vector<char> stxOnly;
		stxOnly.push_back('\x02');

		std::vector<char> byteBuffer;
		std::stringstream parserStream;
		char tempBuffer[4096] = {};

		auto self = static_cast<ClientBase*>(threadId);

		while (!self->isShuttingDown && !self->errorOccured) {
			int bytesReceived = self->receiveData(tempBuffer, sizeof(tempBuffer) - 1);
			if (bytesReceived > 0) {
				AppendRange(byteBuffer, tempBuffer, bytesReceived);
			} else {
				break;
			}

			parserStream << std::string(byteBuffer.data(), byteBuffer.size());
			std::string parsedString = parserStream.str();
			parserStream.str("");

			size_t stxPos = parsedString.find('\x02');
			int etxPos = -1;

			while (stxPos != std::string::npos) {
				etxPos = IndexOfAny(parsedString, delimiters, stxPos + 1);
				if (etxPos == -1) break;

				if (parsedString[etxPos] == '\x03') {
					std::string message = parsedString.substr(stxPos + 1, etxPos - stxPos - 1);
					pthread_mutex_lock(&self->readList_mutex);
					self->readList.push(std::move(message));
					pthread_cond_broadcast(&self->readList_cond);
					pthread_mutex_unlock(&self->readList_mutex);
				}

				stxPos = IndexOfAny(parsedString, stxOnly, static_cast<size_t>(etxPos));
			}

			if (stxPos == std::string::npos && etxPos == -1) {
				byteBuffer.clear();
			} else if (etxPos >= 0) {
				std::string consumed = parsedString.substr(0, etxPos + 1);
				byteBuffer.erase(byteBuffer.begin(), byteBuffer.begin() + consumed.size());
			} else if (stxPos > 0) {
				std::string prefix = parsedString.substr(0, stxPos);
				byteBuffer.erase(byteBuffer.begin(), byteBuffer.begin() + prefix.size());
			}
		}

		self->shutdown(false, false);
		pthread_exit(nullptr);
		return nullptr;
	}

	int ClientBase::receiveData(char* buffer, int bufferSize) {
		if (!sslEnabled) {
			return recv(_socket, buffer, bufferSize, 0);
		}
		return BIO_read(bio, buffer, bufferSize);
	}

	void* ClientBase::processThreadEntry(void* param) {
		return process(param);
	}

	void* ClientBase::process(void* threadId) {
		auto self = static_cast<ClientBase*>(threadId);
		std::vector<std::string> pendingMessages;

		while (self->IsConnected()) {
			for (const auto& msg : pendingMessages) {
				self->processMessages(msg);
			}
			pendingMessages.clear();

			pthread_mutex_lock(&self->readList_mutex);
			if (self->readList.empty()) {
				pthread_cond_wait(&self->readList_cond, &self->readList_mutex);
			}
			pthread_mutex_unlock(&self->readList_mutex);

			while (!self->readList.empty()) {
				pendingMessages.push_back(std::move(self->readList.front()));
				self->readList.pop();
			}
		}

		self->shutdown(false, false);
		pthread_exit(nullptr);
		return nullptr;
	}

	void ClientBase::clearDataStructures() {
		pthread_mutex_lock(&readList_mutex);
		ClearQueue(readList);
		pthread_cond_broadcast(&readList_cond);
		pthread_mutex_unlock(&readList_mutex);

		pthread_mutex_lock(&writeList_mutex);
		ClearQueue(writeList);
		pthread_cond_broadcast(&writeList_cond);
		pthread_mutex_unlock(&writeList_mutex);
	}

#pragma endregion
}

