// Windows Universal Application restricts access to system display info.
// Only current view's bounds and DPI are available at runtime.
// We cache initial display metrics on construction and monitor DPI changes only.
DeviceManagerImpl::DeviceManagerImpl(DeviceManager* devMgr, Private::MainDispatcher* dispatcher)
    : deviceManager(devMgr)
    , mainDispatcher(dispatcher)
{
    using ::Windows::UI::ViewManagement::ApplicationView;
    using ::Windows::Graphics::Display::DisplayInformation;

    auto^ appView = ApplicationView::GetForCurrentView();
    auto^ dispInfo = DisplayInformation::GetForCurrentView();

    // Extract visible area in logical pixels
    auto bounds = appView->VisibleBounds;
    float32 scaleFactor = static_cast<float32>(dispInfo->RawPixelsPerViewPixel);

    // Initialize cached display metadata
    cachedDisplay.systemId = 0;
    cachedDisplay.name = L"primary"; // Placeholder name; no native API exposes this
    cachedDisplay.rawDpiX = dispInfo->RawDpiX;
    cachedDisplay.rawDpiY = dispInfo->RawDpiY;

    // Convert from logical to raw pixel units for size
    cachedDisplay.rect.x = static_cast<float32>(bounds.X);
    cachedDisplay.rect.y = static_cast<float32>(bounds.Y);
    cachedDisplay.rect.dx = static_cast<float32>(bounds.Width * scaleFactor);
    cachedDisplay.rect.dy = static_cast<float32>(bounds.Height * scaleFactor);

    // Register the single known display
    deviceManager->displays.emplace_back(cachedDisplay);
}

void DeviceManagerImpl::UpdateDisplayConfig()
{
    using ::Windows::Graphics::Display::DisplayInformation;

    auto^ currentDispInfo = DisplayInformation::GetForCurrentView();

    // Check if DPI has changed (only supported change type)
    if (cachedDisplay.rawDpiX != currentDispInfo->RawDpiX ||
        cachedDisplay.rawDpiY != currentDispInfo->RawDpiY)
    {
        // Update cached values
        cachedDisplay.rawDpiX = currentDispInfo->RawDpiX;
        cachedDisplay.rawDpiY = currentDispInfo->RawDpiY;

        // Allocate and copy updated info for event
        DisplayInfo* updatedInfo = new DisplayInfo[1];
        updatedInfo[0] = cachedDisplay;

        // Notify main thread of config change
        mainDispatcher->PostEvent(MainDispatcherEvent::CreateDisplayConfigChangedEvent(updatedInfo, 1));
    }
}

