UAugmentaReceiver::UAugmentaReceiver()
{
}

UAugmentaReceiver::~UAugmentaReceiver()
{
	Disconnect();
	CleanupActiveData();
}

void UAugmentaReceiver::Connect(FString HostAddress, int32 PortNumber)
{
	if (IsListening()) return;

	// Create OSC server with specified parameters
	OSCServer = UOSCManager::CreateOSCServer(
		HostAddress,
		PortNumber,
		false,
		true,
		TEXT("AugmentaOSCServer")
	);

	// Bind message handler
	if (OSCServer.IsValid())
	{
		OSCServer->OnOscMessageReceived.AddDynamic(this, &UAugmentaReceiver::HandleIncomingMessage);
	}
}

void UAugmentaReceiver::Disconnect()
{
	if (IsValidServer())
	{
		OSCServer->Stop();
		OSCServer->ConditionalBeginDestroy();
		OSCServer = nullptr;
	}
}

UAugmentaReceiver* UAugmentaReceiver::CreateAugmentaReceiver(FString HostAddress, int32 PortNumber)
{
	UAugmentaReceiver* Instance = NewObject<UAugmentaReceiver>();
	Instance->Connect(HostAddress, PortNumber);
	return Instance;
}

bool UAugmentaReceiver::IsConnected() const
{
	return IsValidServer() && OSCServer->IsActive();
}

