TArray<FAugmentaPerson> UAugmentaReceiver::GetPersonsArray() const
{
	TArray<FAugmentaPerson> Result;
	Result.Reserve(ActiveObjects.Num());
	for (const auto& Entry : ActiveObjects)
	{
		Result.Add(Entry.Value);
	}
	return Result;
}

FAugmentaPerson UAugmentaReceiver::GetNewestPerson() const
{
	FAugmentaPerson Candidate;
	Candidate.Age = FLT_MAX;

	for (const auto& Pair : ActiveObjects)
	{
		if (Pair.Value.Age < Candidate.Age)
		{
			Candidate = Pair.Value;
		}
	}
	return Candidate;
}

FAugmentaPerson UAugmentaReceiver::GetOldestPerson() const
{
	FAugmentaPerson Candidate;
	Candidate.Age = -FLT_MAX; // Initialize to lowest possible

	bool bFoundAny = false;
	for (const auto& Pair : ActiveObjects)
	{
		if (!bFoundAny || Pair.Value.Age > Candidate.Age)
		{
			Candidate = Pair.Value;
			bFoundAny = true;
		}
	}
	return Candidate;
}

