void UAugmentaReceiver::HandleIncomingMessage(const FOSCMessage& Message, const FString& IPAddress, int32 Port)
{
	const FOSCAddress Addr = Message.GetAddress();
	const FString FirstLevel = Addr.GetContainer(0);
	const FString SecondLevel = Addr.GetContainer(1);
	const FString Action = Addr.GetMethod();

	// Route based on top-level container
	if (FirstLevel == ContainerObject)
	{
		if (SecondLevel.IsEmpty())
		{
			const bool bIsEnter = Action == MethodObjectEnter;
			if (bIsEnter || Action == MethodObjectUpdate)
			{
				ProcessPersonUpdate(Message, bIsEnter);
			}
			else if (Action == MethodObjectLeave)
			{
				ProcessPersonExit(Message);
			}
		}
		else if (Action == MethodObjectExtra)
		{
			const bool bIsEnter = SecondLevel == MethodObjectEnter;
			if (bIsEnter || SecondLevel == MethodObjectUpdate)
			{
				ProcessExtraUpdate(Message, bIsEnter);
			}
			else if (SecondLevel == MethodObjectLeave)
			{
				ProcessExtraExit(Message);
			}
		}
	}
	else if (Action == MethodScene)
	{
		ProcessSceneUpdate(Message);
	}
	else if (Action == MethodVideoOutput)
	{
		ProcessVideoUpdate(Message);
	}
}

void UAugmentaReceiver::ProcessSceneUpdate(const FOSCMessage& Message)
{
	int32 TimeVal = 0, PeopleCount = 0;
	float Width = 0.f, Height = 0.f;

	UOSCManager::GetInt32(Message, 0, TimeVal);
	UOSCManager::GetInt32(Message, 1, PeopleCount);
	UOSCManager::GetFloat(Message, 2, Width);
	UOSCManager::GetFloat(Message, 3, Height);

	Scene.CurrentTime = TimeVal;
	Scene.NumPeople = PeopleCount;
	Scene.SceneSize = FVector2D(Width, Height);

	OnSceneUpdated.Broadcast(Scene);
}

void UAugmentaReceiver::ProcessPersonUpdate(const FOSCMessage& Message, bool bJustEntered)
{
	int32 PersonId = -1;
	UOSCManager::GetInt32(Message, 1, PersonId);

	FAugmentaPerson& Person = ActiveObjects.FindOrAdd(PersonId);
	Person.Pid = PersonId;

	UOSCManager::GetInt32(Message, 0, Person.Frame);
	UOSCManager::GetInt32(Message, 2, Person.Oid);
	UOSCManager::GetFloat(Message, 3, Person.Age);
	UOSCManager::GetFloat(Message, 4, Person.Centroid.X);
	UOSCManager::GetFloat(Message, 5, Person.Centroid.Y);
	UOSCManager::GetFloat(Message, 6, Person.Velocity.X);
	UOSCManager::GetFloat(Message, 7, Person.Velocity.Y);
	UOSCManager::GetFloat(Message, 8, Person.Orientation);
	UOSCManager::GetFloat(Message, 9, Person.BoundingRectPos.X);
	UOSCManager::GetFloat(Message, 10, Person.BoundingRectPos.Y);
	UOSCManager::GetFloat(Message, 11, Person.BoundingRectSize.X);
	UOSCManager::GetFloat(Message, 12, Person.BoundingRectSize.Y);
	UOSCManager::GetFloat(Message, 13, Person.BoundingRectRotation);
	UOSCManager::GetFloat(Message, 14, Person.Height);

	if (bJustEntered)
	{
		OnPersonEntered.Broadcast(Person);
	}
	else
	{
		OnPersonUpdated.Broadcast(Person);
	}
}

void UAugmentaReceiver::ProcessPersonExit(const FOSCMessage& Message)
{
	int32 PersonId = -1;
	UOSCManager::GetInt32(Message, 1, PersonId);

	FAugmentaPerson RemovedPerson;
	if (ActiveObjects.RemoveAndCopyValue(PersonId, RemovedPerson))
	{
		OnPersonWillLeave.Broadcast(RemovedPerson);
	}
}

void UAugmentaReceiver::ProcessVideoUpdate(const FOSCMessage& Message)
{
	FVector2D Offset, Size;
	FIntPoint Resolution;

	UOSCManager::GetFloat(Message, 0, Offset.X);
	UOSCManager::GetFloat(Message, 1, Offset.Y);
	UOSCManager::GetFloat(Message, 2, Size.X);
	UOSCManager::GetFloat(Message, 3, Size.Y);
	UOSCManager::GetInt32(Message, 4, Resolution.X);
	UOSCManager::GetInt32(Message, 5, Resolution.Y);

	VideoOutput.Offset = Offset;
	VideoOutput.Size = Size;
	VideoOutput.Resolution = Resolution;

	OnVideoOutputUpdated.Broadcast(VideoOutput);
}

void UAugmentaReceiver::ProcessExtraUpdate(const FOSCMessage& Message, bool bJustEntered)
{
	int32 ExtraId = -1;
	UOSCManager::GetInt32(Message, 1, ExtraId);

	FAugmentaObjectExtra& Extra = ActiveObjectsExtraData.FindOrAdd(ExtraId);
	Extra.Id = ExtraId;

	UOSCManager::GetInt32(Message, 0, Extra.Frame);
	UOSCManager::GetInt32(Message, 2, Extra.Oid);
	UOSCManager::GetFloat(Message, 3, Extra.Highest.X);
	UOSCManager::GetFloat(Message, 4, Extra.Highest.Y);
	UOSCManager::GetFloat(Message, 5, Extra.Distance);
	UOSCManager::GetFloat(Message, 6, Extra.Reflectivity);

	if (bJustEntered)
	{
		OnEnteredExtraData.Broadcast(Extra);
	}
	else
	{
		OnUpdatedExtraData.Broadcast(Extra);
	}
}

void UAugmentaReceiver::ProcessExtraExit(const FOSCMessage& Message)
{
	int32 ExtraId = -1;
	UOSCManager::GetInt32(Message, 1, ExtraId);

	FAugmentaObjectExtra RemovedExtra;
	if (ActiveObjectsExtraData.RemoveAndCopyValue(ExtraId, RemovedExtra))
	{
		OnLeaveExtraData.Broadcast(RemovedExtra);
	}
}

void UAugmentaReceiver::CleanupActiveData()
{
	ActiveObjects.Empty();
	ActiveObjectsExtraData.Empty();
}

bool UAugmentaReceiver::IsValidServer() const
{
	return OSCServer && OSCServer->IsValidLowLevel();
}

bool UAugmentaReceiver::IsListening() const
{
	return OSCServer && OSCServer->IsValidLowLevel();
}

