#include <stddef.h>
#include <stdint.h>
#include <emmintrin.h>

//---------------------------------------------------------------------
// force inline for compilers - restructured conditionals
//---------------------------------------------------------------------
#ifndef INLINE
#ifdef __GNUC__
    #if (__GNUC__ > 3) || ((__GNUC__ == 3) && (__GNUC_MINOR__ >= 1))
        #define INLINE __inline__ __attribute__((always_inline))
    #else
        #define INLINE __inline__
    #endif
#elif defined(_MSC_VER)
    #define INLINE __forceinline
#else
    #define INLINE 
#endif
#endif

//---------------------------------------------------------------------
// Helper functions for different block sizes - rewritten with consistent patterns
//---------------------------------------------------------------------
static INLINE void copy_block_16(void *dest, const void *src) {
    __m128i reg = _mm_loadu_si128((const __m128i*)src);
    _mm_storeu_si128((__m128i*)dest, reg);
}

static INLINE void copy_block_32(void *dest, const void *src) {
    __m128i r0 = _mm_loadu_si128((const __m128i*)src);
    __m128i r1 = _mm_loadu_si128((const __m128i*)src + 1);
    _mm_storeu_si128((__m128i*)dest, r0);
    _mm_storeu_si128((__m128i*)dest + 1, r1);
}

static INLINE void copy_block_64(void *dest, const void *src) {
    __m128i r[4];
    r[0] = _mm_loadu_si128((const __m128i*)src);
    r[1] = _mm_loadu_si128((const __m128i*)src + 1);
    r[2] = _mm_loadu_si128((const __m128i*)src + 2);
    r[3] = _mm_loadu_si128((const __m128i*)src + 3);
    _mm_storeu_si128((__m128i*)dest,     r[0]);
    _mm_storeu_si128((__m128i*)dest + 1, r[1]);
    _mm_storeu_si128((__m128i*)dest + 2, r[2]);
    _mm_storeu_si128((__m128i*)dest + 3, r[3]);
}

static INLINE void copy_block_128(void *dest, const void *src) {
    __m128i r[8];
    for (int i = 0; i < 8; ++i) {
        r[i] = _mm_loadu_si128((const __m128i*)src + i);
    }
    for (int i = 0; i < 8; ++i) {
        _mm_storeu_si128((__m128i*)dest + i, r[i]);
    }
}

