int hourglassSum(std::vector<std::vector<int>> grid) {
    int n = grid.size();
    if (n == 0) return -1;

    int m = grid[0].size();
    if (m < 3 || n < 3) return -1;

    int best = INT_MIN;

    for (int r = 0; r <= n - 3; ++r) {
        for (int c = 0; c <= m - 3; ++c) {
            int current = 0;

            // Top row of hourglass
            current += grid[r][c];
            current += grid[r][c + 1];
            current += grid[r][c + 2];

            // Middle element
            current += grid[r + 1][c + 1];

            // Bottom row of hourglass
            current += grid[r + 2][c];
            current += grid[r + 2][c + 1];
            current += grid[r + 2][c + 2];

            if (current > best) {
                best = current;
            }
        }
    }

    return best;
}

