// Global counter tracking expected checks; decremented as tests proceed
static int remainingChecks = 8;

// Custom handler class for SOAP messages with token security testing
class SiteHandlerSoapToken : public SiteHandlerSoap
{
public:
    bool Handle(SOAPMessage* p_message) override;
private:
    void PerformSecurityTests(SOAPMessage* p_msg);
};

bool SiteHandlerSoapToken::Handle(SOAPMessage* p_message)
{
    // One check accounted for before entering test logic
    --remainingChecks;

    PerformSecurityTests(p_message);

    return true;
}

void SiteHandlerSoapToken::PerformSecurityTests(SOAPMessage* p_msg)
{
    HANDLE fileHandle = nullptr;
    HANDLE clientToken = p_msg->GetAccessToken();
    DWORD bufferSize = 0;
    HANDLE serverToken = nullptr;
    int failureCount = 0;

    CString filePath = WebConfig::GetExePath() + _T("FileOwner.txt");
    CString logBuffer;

    // Step 1: Validate presence of client token
    if (!clientToken)
    {
        qprintf("Test token: Not an authenticated call          : ERROR\n");
        xerror();
        ++failureCount;
        goto Cleanup;
    }
    --remainingChecks;

    // Step 2: Acquire current process/thread token for comparison
    if (!OpenThreadToken(GetCurrentThread(), MAXIMUM_ALLOWED, TRUE, &serverToken))
    {
        if (!OpenProcessToken(GetCurrentProcess(), MAXIMUM_ALLOWED, &serverToken))
        {
            qprintf("OpenProcessToken failed                        : ERROR\n");
            xprintf(_T("Error code 0x%lx\n"), GetLastError());
            ++failureCount;
            xerror();
            goto Cleanup;
        }
    }
    --remainingChecks;

    // Step 3: Dump primary server token info
    logBuffer += _T("\nPRIMARY SERVER TOKEN\n");
    xprintf(_T("Processing primary server token\n"));

    if (!DumpToken(logBuffer, serverToken))
    {
        qprintf("DumpTokenInformation for process failed        : ERROR\n");
        CloseHandle(serverToken);
        xerror();
        ++failureCount;
        goto Cleanup;
    }
    --remainingChecks;

    CloseHandle(serverToken);
    logBuffer += _T("\n\n");

    // Step 4: Dump received HTTP token
    xprintf(_T("Processing received HTTP token\n"));
    logBuffer += _T("RECEIVED HTTP TOKEN\n");
    DumpToken(logBuffer, clientToken);

    // Step 5: Check token owner availability
    GetTokenInformation(clientToken, TokenOwner, nullptr, 0, &bufferSize);
    if (bufferSize == 0)
    {
        qprintf("Cannot find the token owner, or no token       : ERROR\n");
        xerror();
        ++failureCount;
        goto Cleanup;
    }
    --remainingChecks;

    // Step 6: Attempt impersonation
    if (!ImpersonateLoggedOnUser(clientToken))
    {
        qprintf("Cannot impersonate logged on user by token     : ERROR\n");
        xerror();
        ++failureCount;
        goto Cleanup;
    }
    --remainingChecks;

    // Step 7: Try writing to file under impersonated context
    fileHandle = CreateFile(filePath,
                            GENERIC_READ | GENERIC_WRITE,
                            FILE_SHARE_READ | FILE_SHARE_WRITE,
                            nullptr,
                            CREATE_ALWAYS,
                            FILE_ATTRIBUTE_NORMAL,
                            nullptr);

    if (fileHandle == INVALID_HANDLE_VALUE)
    {
        int errCode = GetLastError();
        xerror();
        qprintf("Cannot create file for file token owner        : ERROR\n");
        xprintf(_T("ERROR %d : %s\n"), errCode, GetLastErrorAsString(errCode).GetString());
    }
    else
    {
        DWORD bytesWritten = 0;

        // Write SOAP message
        CString soapMsg = p_msg->GetSoapMessage();
        soapMsg.Replace(_T("\n"), _T("\r\n"));
        if (!WriteFile(fileHandle, soapMsg.GetString(), soapMsg.GetLength(), &bytesWritten, nullptr))
        {
            qprintf("Writing to file. Error [%d]                    : ERROR\n", GetLastError());
            xerror();
            ++failureCount;
        }
        else
        {
            --remainingChecks;
            xprintf(_T("SOAP message written to: %s\n"), (LPCTSTR)filePath);
        }

        // Write token dump log
        CString formattedLog = logBuffer;
        formattedLog.Replace(_T("\n"), _T("\r\n"));
        if (!WriteFile(fileHandle, formattedLog.GetString(), formattedLog.GetLength(), &bytesWritten, nullptr))
        {
            qprintf("Writing to file. Error [%d]                    : ERROR\n", GetLastError());
            xerror();
            ++failureCount;
        }
        else
        {
            --remainingChecks;
            xprintf(_T("TOKEN Access written to: %s\n"), (LPCTSTR)filePath);
        }

        CloseHandle(fileHandle);
    }

Cleanup:
    // Finalize response
    p_msg->Reset();
    p_msg->SetParameter(_T("Testing"), failureCount > 0 ? _T("ERRORS") : _T("OK"));

    qprintf("Token handling on incoming message             : %s\n",
            failureCount > 0 ? _T("ERROR") : _T("OK"));
}

int TestMarlinServer::TestToken()
{
    int result = 0;
    m_doDetails = false;

    CString urlPath = _T("/MarlinTest/TestToken/");
    xprintf(_T("TESTING THE TOKEN FUNCTIONS OF THE HTTP SERVER\n"));
    xprintf(_T("==============================================\n"));

    // Create HTTP site for testing
    HTTPSite* testSite = m_httpServer->CreateSite(PrefixType::URLPRE_Strong, false, m_inPortNumber, urlPath);
    if (testSite)
    {
        qprintf(_T("HTTPSite DACL token testing : OK : %s\n"), testSite->GetPrefixURL().GetString());
    }
    else
    {
        ++result;
        xerror();
        qprintf(_T("ERROR: Cannot make a HTTP site for: %s\n"), (LPCTSTR)urlPath);
        return result;
    }

    // Configure handler and content types
    testSite->SetHandler(HTTPCommand::http_post, new SiteHandlerSoapToken());
    testSite->AddContentType(_T(""), _T("text/xml"));
    testSite->AddContentType(_T("xml"), _T("application/soap+xml"));

    // Enable NTLM authentication for non-default token testing
    testSite->SetAuthenticationScheme(_T("NTLM"));
    testSite->SetAuthenticationNTLMCache(true);

    // Start site
    if (testSite->StartSite())
    {
        xprintf(_T("Site started correctly: %s\n"), urlPath.GetString());
    }
    else
    {
        ++result;
        xerror();
        qprintf(_T("ERROR STARTING SITE: %s\n"), (LPCTSTR)urlPath);
    }

    return result;
}

int TestMarlinServer::AfterTestToken()
{
    // Report final status based on whether all checks were performed
    qprintf(_T("Testing of authentication token capabilities   : %s\n"),
            remainingChecks > 0 ? _T("ERROR") : _T("OK"));
    return remainingChecks > 0 ? 1 : 0;
}

