  ASSERT_EQ(read_dram_region_owner(1), 0xabababab);
  ASSERT_EQ(read_dram_region_owner(2), 0x98765432);
  ASSERT_EQ(read_dram_region_owner(5), 0x12345678);
  ASSERT_EQ(read_dram_region_owner(7), 0xfccffccf);
}

TEST_F(DramRegionInlTest, BzeroDramRegion) {
  // Pre-fill DRAM with non-zero pattern
  for (size_t offset = 0; offset < 256 * 1024; offset += sizeof(uintptr_t))
    *(phys_ptr<uintptr_t>{offset}) = ~0u;

  // Zero out region 1 (32KB–64KB)
  bzero_dram_region(1);

  // Verify region 0 and region 2 remain unchanged
  for (size_t offset = 0; offset < 32 * 1024; offset += sizeof(uintptr_t))
    ASSERT_EQ(*(phys_ptr<uintptr_t>{offset}), ~0u);

  for (size_t offset = 32 * 1024; offset < 64 * 1024; offset += sizeof(uintptr_t))
    ASSERT_EQ(*(phys_ptr<uintptr_t>{offset}), 0u);

  for (size_t offset = 64 * 1024; offset < 256 * 1024; offset += sizeof(uintptr_t))
    ASSERT_EQ(*(phys_ptr<uintptr_t>{offset}), ~0u);
}

