#include "Analyzer/Candidates.h"
#include <gtest/gtest.h>

// Helper to check if a candidate set includes a value
TEST(Candidates, includes)
{
    int val = 1;
    while (val <= 9)
    {
        EXPECT_TRUE(Candidates::includes(Candidates::fromValue(val), val));
        EXPECT_FALSE(Candidates::includes((~Candidates::fromValue(val)) & Candidates::ALL, val));
        ++val;
    }
}

// Verify that single-value candidates are considered solved
TEST(Candidates, isSolved)
{
    int val = 1;
    while (val <= 9)
    {
        EXPECT_TRUE(Candidates::isSolved(Candidates::fromValue(val)));
        ++val;
    }
    EXPECT_FALSE(Candidates::isSolved(Candidates::ALL));
}

// Test bivalue detection: exactly two distinct candidates
TEST(Candidates, isBivalue)
{
    int first = 1;
    while (first <= 9)
    {
        int second = 1;
        while (second <= 9)
        {
            if (first == second)
                EXPECT_FALSE(Candidates::isBivalue(Candidates::fromValue(first)));
            else
                EXPECT_TRUE(Candidates::isBivalue(Candidates::fromValue(first) | Candidates::fromValue(second)));
            ++second;
        }
        ++first;
    }
    EXPECT_FALSE(Candidates::isBivalue(Candidates::ALL));
}

// Ensure value extraction matches original input
TEST(Candidates, value_fromValue)
{
    EXPECT_EQ(Candidates::value(Candidates::NONE), 0);
    int v = 1;
    while (v <= 9)
    {
        EXPECT_EQ(Candidates::value(Candidates::fromValue(v)), v);
        ++v;
    }
}

// Validate conversion from candidate set to vector of values
TEST(Candidates, values)
{
    EXPECT_EQ(Candidates::values(Candidates::NONE), std::vector<int>());

    Candidates::Type x = 0;
    while (x <= Candidates::ALL)
    {
        std::vector<int> expectedList;
        int idx = 1;
        while (idx <= 9)
        {
            if ((x & (1 << idx)) != 0)
                expectedList.push_back(idx);
            ++idx;
        }
        EXPECT_EQ(Candidates::values(x), expectedList);
        ++x;
    }
}

// Count number of set bits in candidate mask using manual bit-counting for verification
TEST(Candidates, count)
{
    Candidates::Type cand = 0;
    while (cand <= Candidates::ALL)
    {
        Candidates::Type temp = cand;
        int cnt = 0;
        while (temp != 0)
        {
            temp >>= 1;
            if (temp & 1)
                ++cnt;
        }
        EXPECT_EQ(Candidates::count(cand), cnt);
        cand += 2;
    }
}

