WavReaderTester::WavReaderTester() {
    inputDirectoryPath = nullptr;
    rawSampleBuffer = nullptr;
    int16Buffer = nullptr;
    readerInstance = new WavReader();
}

WavReaderTester::~WavReaderTester() {
    if (readerInstance) {
        delete readerInstance;
        readerInstance = nullptr;
    }
    if (rawSampleBuffer) {
        std::free(rawSampleBuffer);
        rawSampleBuffer = nullptr;
    }
    if (int16Buffer) {
        std::free(int16Buffer);
        int16Buffer = nullptr;
    }
}

bool WavReaderTester::setup(const char* dirPath) {
    // printf("Setting up WavReaderTester.\n\n");

    if (!dirPath) {
        std::fprintf(stderr, "Error: Input directory path is NULL.\n");
        return false;
    }

    char tempPath[MAX_PATH_LENGTH];
    std::snprintf(tempPath, MAX_PATH_LENGTH, "%s/WavReaderTesterTempFile.txt", dirPath);

    FILE* testFile = std::fopen(tempPath, "w");
    if (!testFile) {
        std::fprintf(stderr, "Error: Unable to open temp file at path:\n%s.\n", tempPath);
        return false;
    }
    std::fclose(testFile);

    if (std::remove(tempPath) != 0) {
        std::fprintf(stderr, "Error: Failed to remove temporary validation file.\n");
        return false;
    }

    inputDirectoryPath = dirPath;

    if (rawSampleBuffer) {
        std::free(rawSampleBuffer);
        rawSampleBuffer = nullptr;
    }

    if (int16Buffer) {
        std::free(int16Buffer);
        int16Buffer = nullptr;
    }

    return true;
}

bool WavReaderTester::executeTests() {
    std::printf("Executing WavReaderTest.\n");

    std::printf("    Testing full-file read...\n");
    for (size_t idx = 0; idx < NUM_FILE_PARAM_SETS; ++idx) {
        if (!processFullRead(&fileParams[idx])) {
            std::fprintf(stderr, "executeTests(): Full-read test failed for index %zu.\n", idx);
            return false;
        }
    }

    std::printf("    Testing incremental read...\n");
    for (size_t idx = 0; idx < NUM_FILE_PARAM_SETS; ++idx) {
        if (!processIncrementalRead(&fileParams[idx])) {
            std::fprintf(stderr, "executeTests(): Incremental-read test failed for index %zu.\n", idx);
            return false;
        }
    }

    std::printf("    Testing int16 conversion...\n");
    for (size_t idx = 0; idx < NUM_FILE_PARAM_SETS; ++idx) {
        if (!processInt16Read(&fileParams[idx])) {
            std::fprintf(stderr, "executeTests(): Int16-read test failed for index %zu.\n", idx);
            return false;
        }
    }

    std::printf("Done WavReaderTest.\n\n");
    return true;
}

bool WavReaderTester::processFullRead(const InFileParamSetDef* params) {
    const char* filename = params->fileName;
    char fullPath[MAX_PATH_LENGTH];
    std::snprintf(fullPath, MAX_PATH_LENGTH, "%s/%s", inputDirectoryPath, filename);

    if (!readerInstance->init(fullPath)) {
        std::fprintf(stderr, "processFullRead(): Initialization failed.\n");
        return false;
    }

    if (!readerInstance->start()) {
        std::fprintf(stderr, "processFullRead(): Start operation failed.\n");
        return false;
    }

    uint32_t totalBytes = readerInstance->getDataSize();
    if (rawSampleBuffer) {
        std::free(rawSampleBuffer);
        rawSampleBuffer = nullptr;
    }
    rawSampleBuffer = static_cast<uint8_t*>(std::malloc(totalBytes));
    if (!rawSampleBuffer) {
        std::fprintf(stderr, "processFullRead(): Memory allocation failed.\n");
        return false;
    }

    if (!readerInstance->read(rawSampleBuffer, totalBytes)) {
        std::fprintf(stderr, "processFullRead(): Data read failed.\n");
        return false;
    }

    if (!readerInstance->end()) {
        std::fprintf(stderr, "processFullRead(): Finalization failed.\n");
        return false;
    }

    if (!validate(params, VALIDATION_SOURCE_SAMPLEDATA)) {
        std::fprintf(stderr, "processFullRead(): Validation failed.\n");
        return false;
    }

    return true;
}

bool WavReaderTester::processIncrementalRead(const InFileParamSetDef* params) {
    const char* filename = params->fileName;
    const uint32_t channels = params->numChannels;
    const uint32_t depth = params->byteDepth;

    char fullPath[MAX_PATH_LENGTH];
    std::snprintf(fullPath, MAX_PATH_LENGTH, "%s/%s", inputDirectoryPath, filename);

    if (!readerInstance->init(fullPath)) {
        std::fprintf(stderr, "processIncrementalRead(): Init failed.\n");
        return false;
    }

    if (!readerInstance->start()) {
        std::fprintf(stderr, "processIncrementalRead(): Start failed.\n");
        return false;
    }

    const uint32_t expectedSize = readerInstance->getSampleCount() * channels * depth;
    if (rawSampleBuffer) {
        std::free(rawSampleBuffer);
        rawSampleBuffer = nullptr;
    }
    rawSampleBuffer = static_cast<uint8_t*>(std::malloc(expectedSize));
    if (!rawSampleBuffer) {
        std::fprintf(stderr, "processIncrementalRead(): Buffer allocation failed.\n");
        return false;
    }

    const uint32_t chunkSize = channels * depth * 1; // One sample per channel
    uint8_t chunk[chunkSize];

    uint32_t offset = 0;
    while (offset < expectedSize) {
        uint32_t remaining = expectedSize - offset;
        uint32_t toRead = (remaining < chunkSize) ? remaining : chunkSize;

        if (!readerInstance->read(chunk, toRead)) {
            std::fprintf(stderr, "processIncrementalRead(): Chunk read failed.\n");
            return false;
        }

        for (uint32_t k = 0; k < toRead; ++k) {
            rawSampleBuffer[offset + k] = chunk[k];
        }
        offset += toRead;
    }

    if (!readerInstance->end()) {
        std::fprintf(stderr, "processIncrementalRead(): End operation failed.\n");
        return false;
    }

    if (!validate(params, VALIDATION_SOURCE_SAMPLEDATA)) {
        std::fprintf(stderr, "processIncrementalRead(): Validation failed.\n");
        return false;
    }

    return true;
}

bool WavReaderTester::processInt16Read(const InFileParamSetDef* params) {
    const char* filename = params->fileName;
    char fullPath[MAX_PATH_LENGTH];
    std::snprintf(fullPath, MAX_PATH_LENGTH, "%s/%s", inputDirectoryPath, filename);

    if (!readerInstance->init(fullPath)) {
        std::fprintf(stderr, "processInt16Read(): Init failed.\n");
        return false;
    }

    if (!readerInstance->start()) {
        std::fprintf(stderr, "processInt16Read(): Start failed.\n");
        return false;
    }

    const size_t int16ByteCount = readerInstance->getSampleCount() * readerInstance->getNumChannels() * sizeof(int16_t);
    if (int16Buffer) {
        std::free(int16Buffer);
        int16Buffer = nullptr;
    }
    int16Buffer = static_cast<int16_t*>(std::malloc(int16ByteCount));
    if (!int16Buffer) {
        std::fprintf(stderr, "processInt16Read(): Int16 buffer allocation failed.\n");
        return false;
    }

    if (!readerInstance->readAsInt16(int16Buffer, readerInstance->getSampleCount())) {
        std::fprintf(stderr, "processInt16Read(): Int16 read failed.\n");
        return false;
    }

    if (!readerInstance->end()) {
        std::fprintf(stderr, "processInt16Read(): End failed.\n");
        return false;
    }

    if (!validate(params, VALIDATION_SOURCE_INT16SAMPLES)) {
        std::fprintf(stderr, "processInt16Read(): Validation failed.\n");
        return false;
    }

    return true;
}

bool WavReaderTester::validate(const InFileParamSetDef* params, ValidationSource src) {
    const char* filename = params->fileName;

    // Metadata checks
    if (params->numChannels != readerInstance->getNumChannels()) {
        std::fprintf(stderr, "Error: numChannels mismatch for %s.\n", filename);
        return false;
    }

    if (params->byteDepth != readerInstance->getByteDepth()) {
        std::fprintf(stderr, "Error: byteDepth mismatch for %s.\n", filename);
        return false;
    }

    if (params->samplesAreInts != readerInstance->getIntFlag()) {
        std::fprintf(stderr, "Error: samplesAreInts mismatch for %s.\n", filename);
        return false;
    }

    // Content validation: detect zero-crossings for ~440Hz sine wave
    int16_t ch1Prev = 0, ch2Prev = 0;
    int16_t ch1Curr = 0, ch2Curr = 0;
    uint32_t posZcCh1 = 0, posZcCh2 = 0;
    const uint32_t totalSamples = readerInstance->getSampleCount();
    const uint32_t numChannels = readerInstance->getNumChannels();

    for (uint32_t s = 0; s < totalSamples; ++s) {
        ch1Prev = ch1Curr;
        ch2Prev = ch2Curr;

        if (src == VALIDATION_SOURCE_SAMPLEDATA) {
            readerInstance->extractInt16FromBuffer(rawSampleBuffer,
                                                   readerInstance->getDataSize(),
                                                   s,
                                                   ch1Curr,
                                                   ch2Curr);
        } else {
            ch1Curr = int16Buffer[s * numChannels];
            ch2Curr = (numChannels == 1) ? 0 : int16Buffer[s * numChannels + 1];
        }

        if (ch1Prev < 0 && ch1Curr >= 0) ++posZcCh1;
        if (ch2Prev < 0 && ch2Curr >= 0) ++posZcCh2;
    }

    const double durationSec = static_cast<double>(totalSamples) / SAMPLE_RATE;
    const double freqCh1 = static_cast<double>(posZcCh1) / durationSec;
    const double freqCh2 = static_cast<double>(posZcCh2) / durationSec;

    constexpr double tolerance = 80.0;
    if (freqCh1 < SINE_FREQUENCY - tolerance || freqCh1 > SINE_FREQUENCY + tolerance) {
        std::fprintf(stderr, "Error: Channel 1 frequency (%.0fHz) outside ±%.0fHz of %.0fHz for %s.\n",
                     std::ceil(freqCh1), tolerance, SINE_FREQUENCY, filename);
        return false;
    }

    if (numChannels == 2) {
        if (freqCh2 < SINE_FREQUENCY - tolerance || freqCh2 > SINE_FREQUENCY + tolerance) {
            std::fprintf(stderr, "Error: Channel 2 frequency (%.0fHz) outside ±%.0fHz of %.0fHz for %s.\n",
                         std::ceil(freqCh2), tolerance, SINE_FREQUENCY, filename);
            return false;
        }
    }

    return true;
}

