PSContext2D_t* PSContext2DAllocate() {
  PSContext2D_t* context = static_cast<PSContext2D_t*>(malloc(sizeof(PSContext2D_t)));
  if (!context) return nullptr;

  memset(context, 0, sizeof(PSContext2D_t));
  const PPB_ImageData* img_iface = PSInterfaceImageData();
  context->format = img_iface->GetNativeImageDataFormat();

  return context;
}

void PSContext2DFree(PSContext2D_t* ctx) {
  if (!ctx) return;

  if (ctx->graphic_2d) {
    PSInterfaceCore()->ReleaseResource(ctx->graphic_2d);
    ctx->graphic_2d = 0;
  }

  if (ctx->image) {
    PSInterfaceCore()->ReleaseResource(ctx->image);
    ctx->image = 0;
  }

  free(ctx);
}

// Process incoming events relevant to 2D rendering context changes.
// Returns 1 if event was handled, otherwise 0.
int PSContext2DHandleEvent(PSContext2D_t* ctx, PSEvent* evt) {
  if (!ctx || !evt) return 0;

  switch (evt->type) {
    case PSE_INSTANCE_DIDCHANGEVIEW: {
      PP_Rect viewRect;
      PSInterfaceView()->GetRect(evt->as_resource, &viewRect);

      // Release old graphics context before resizing
      if (ctx->graphic_2d) {
        PSInterfaceCore()->ReleaseResource(ctx->graphic_2d);
        ctx->graphic_2d = 0;
      }
      ctx->bound = 0;
      ctx->width = viewRect.size.width;
      ctx->height = viewRect.size.height;

      // Create new 2D graphics context with updated dimensions
      ctx->graphic_2d =
          PSInterfaceGraphics2D()->Create(PSGetInstanceId(), &viewRect.size,
                                          PP_TRUE);

      // Attempt binding to instance
      if (ctx->graphic_2d) {
        ctx->bound =
            PSInterfaceInstance()->BindGraphics(PSGetInstanceId(),
                                                ctx->graphic_2d);
      }

      // Discard any existing image buffer to force reallocation on next GetBuffer()
      if (ctx->image) {
        PSInterfaceCore()->ReleaseResource(ctx->image);
        ctx->image = 0;
      }

      return 1;
    }
    default:
      break;
  }

  return 0;
}

// Acquire an offscreen image buffer for drawing.
// Returns 1 on success, 0 otherwise.
int PSContext2DGetBuffer(PSContext2D_t* ctx) {
  if (!ctx || !ctx->bound) return 0;

  // Reuse existing image if already allocated
  if (ctx->image) return 1;

  PP_Size bufferSize = { ctx->width, ctx->height };
  const PPB_ImageData* img_iface = PSInterfaceImageData();
  PP_Resource newImage =
      img_iface->Create(PSGetInstanceId(), ctx->format, &bufferSize, PP_FALSE);

  if (!newImage) {
    PSInstance::GetInstance()->Error("Failed to allocate 2D image resource.\n");
    return 0;
  }

  PP_ImageDataDesc desc;
  img_iface->Describe(newImage, &desc);

  ctx->image = newImage;
  ctx->data = static_cast<uint32_t*>(img_iface->Map(newImage));
  ctx->stride = desc.stride;

  return 1;
}

// Commit current image buffer to screen and release it.
// Returns 1 on successful swap, 0 otherwise.
int PSContext2DSwapBuffer(PSContext2D_t* ctx) {
  if (!ctx || !ctx->bound || !ctx->image) return 0;

  const PPB_ImageData* img_iface = PSInterfaceImageData();
  const PPB_Graphics2D* gfx_iface = PSInterfaceGraphics2D();

  img_iface->Unmap(ctx->image);
  gfx_iface->ReplaceContents(ctx->graphic_2d, ctx->image);
  gfx_iface->Flush(ctx->graphic_2d, PP_BlockUntilComplete());

  img_iface->ReleaseResource(ctx->image);
  ctx->image = 0;
  ctx->stride = 0;
  ctx->data = nullptr;

  return 1;
}

