enum class InstructionType {
  ADDR,
  ADDI,
  MULR,
  MULI,
  BANR,
  BANI,
  BORR,
  BORI,
  SETR,
  SETI,
  GTIR,
  GTRI,
  GTRR,
  EQIR,
  EQRI,
  EQRR,
};

const std::vector<InstructionType> ALL_INSTRUCTIONS = {
  InstructionType::ADDR,
  InstructionType::ADDI,
  InstructionType::MULR,
  InstructionType::MULI,
  InstructionType::BANR,
  InstructionType::BANI,
  InstructionType::BORR,
  InstructionType::BORI,
  InstructionType::SETR,
  InstructionType::SETI,
  InstructionType::GTIR,
  InstructionType::GTRI,
  InstructionType::GTRR,
  InstructionType::EQIR,
  InstructionType::EQRI,
  InstructionType::EQRR,
};

struct Sample {
  std::array<int, 4> priorState;
  int instructionCode;
  int operandA;
  int operandB;
  int resultRegister;
  std::set<InstructionType> plausibleInstructions;
  std::array<int, 4> postState;
  Sample() : priorState{{0,0,0,0}}, postState{{0,0,0,0}} {}
};

struct Command {
  InstructionType type;
  int src1;
  int src2;
  int dest;
};

void execute(Command cmd, std::array<int, 4>& mem) {
  int op1 = cmd.src1;
  int op2 = cmd.src2;
  int dst = cmd.dest;

  switch (cmd.type) {
    case InstructionType::ADDR:
      mem[dst] = mem[op1] + mem[op2];
      break;
    case InstructionType::ADDI:
      mem[dst] = mem[op1] + op2;
      break;
    case InstructionType::MULR:
      mem[dst] = mem[op1] * mem[op2];
      break;
    case InstructionType::MULI:
      mem[dst] = mem[op1] * op2;
      break;
    case InstructionType::BANR:
      mem[dst] = mem[op1] & mem[op2];
      break;
    case InstructionType::BANI:
      mem[dst] = mem[op1] & op2;
      break;
    case InstructionType::BORR:
      mem[dst] = mem[op1] | mem[op2];
      break;
    case InstructionType::BORI:
      mem[dst] = mem[op1] | op2;
      break;
    case InstructionType::SETR:
      mem[dst] = mem[op1];
      break;
    case InstructionType::SETI:
      mem[dst] = op1;
      break;
    case InstructionType::GTIR:
      mem[dst] = (op1 > mem[op2]) ? 1 : 0;
      break;
    case InstructionType::GTRI:
      mem[dst] = (mem[op1] > op2) ? 1 : 0;
      break;
    case InstructionType::GTRR:
      mem[dst] = (mem[op1] > mem[op2]) ? 1 : 0;
      break;
    case InstructionType::EQIR:
      mem[dst] = (op1 == mem[op2]) ? 1 : 0;
      break;
    case InstructionType::EQRI:
      mem[dst] = (mem[op1] == op2) ? 1 : 0;
      break;
    case InstructionType::EQRR:
      mem[dst] = (mem[op1] == mem[op2]) ? 1 : 0;
      break;
  }
}

bool matchesOperation(const Sample* sample, InstructionType instr) {
  for (int idx = 0; idx < 4; ++idx) {
    if (idx != sample->resultRegister) {
      assert(sample->priorState[idx] == sample->postState[idx]);
    }
  }

  switch (instr) {
    case InstructionType::ADDR:
      return (sample->priorState[sample->operandA] + sample->priorState[sample->operandB]) == sample->postState[sample->resultRegister];
    case InstructionType::ADDI:
      return (sample->priorState[sample->operandA] + sample->operandB) == sample->postState[sample->resultRegister];
    case InstructionType::MULR:
      return (sample->priorState[sample->operandA] * sample->priorState[sample->operandB]) == sample->postState[sample->resultRegister];
    case InstructionType::MULI:
      return (sample->priorState[sample->operandA] * sample->operandB) == sample->postState[sample->resultRegister];
    case InstructionType::BANR:
      return (sample->priorState[sample->operandA] & sample->priorState[sample->operandB]) == sample->postState[sample->resultRegister];
    case InstructionType::BANI:
      return (sample->priorState[sample->operandA] & sample->operandB) == sample->postState[sample->resultRegister];
    case InstructionType::BORR:
      return (sample->priorState[sample->operandA] | sample->priorState[sample->operandB]) == sample->postState[sample->resultRegister];
    case InstructionType::BORI:
      return (sample->priorState[sample->operandA] | sample->operandB) == sample->postState[sample->resultRegister];
    case InstructionType::SETR:
      return sample->priorState[sample->operandA] == sample->postState[sample->resultRegister];
    case InstructionType::SETI:
      return sample->operandA == sample->postState[sample->resultRegister];
    case InstructionType::GTIR: {
      bool cond = (sample->operandA > sample->priorState[sample->operandB]);
      return (cond && sample->postState[sample->resultRegister] == 1) ||
             (!cond && sample->postState[sample->resultRegister] == 0);
    }
    case InstructionType::GTRI: {
      bool cond = (sample->priorState[sample->operandA] > sample->operandB);
      return (cond && sample->postState[sample->resultRegister] == 1) ||
             (!cond && sample->postState[sample->resultRegister] == 0);
    }
    case InstructionType::GTRR: {
      bool cond = (sample->priorState[sample->operandA] > sample->priorState[sample->operandB]);
      return (cond && sample->postState[sample->resultRegister] == 1) ||
             (!cond && sample->postState[sample->resultRegister] == 0);
    }
    case InstructionType::EQIR: {
      bool cond = (sample->operandA == sample->priorState[sample->operandB]);
      return (cond && sample->postState[sample->resultRegister] == 1) ||
             (!cond && sample->postState[sample->resultRegister] == 0);
    }
    case InstructionType::EQRI: {
      bool cond = (sample->priorState[sample->operandA] == sample->operandB);
      return (cond && sample->postState[sample->resultRegister] == 1) ||
             (!cond && sample->postState[sample->resultRegister] == 0);
    }
    case InstructionType::EQRR: {
      bool cond = (sample->priorState[sample->operandA] == sample->priorState[sample->operandB]);
      return (cond && sample->postState[sample->resultRegister] == 1) ||
             (!cond && sample->postState[sample->resultRegister] == 0);
    }
  }
  return false;
}

std::set<InstructionType> determinePlausibleInstructions(const Sample* sample) {
  std::set<InstructionType> options;
  for (auto type : ALL_INSTRUCTIONS) {
    if (matchesOperation(sample, type)) {
      options.insert(type);
    }
  }
  return options;
}

std::vector<Sample*> parseSamples(const std::string& filename) {
  std::ifstream file(filename);
  std::vector<Sample*> samples;
  std::regex beforePattern("Before: \\[(\\d+), (\\d+), (\\d+), (\\d+)\\]");
  std::regex commandPattern("(\\d+) (\\d+) (\\d+) (\\d+)");
  std::regex afterPattern("After:  \\[(\\d+), (\\d+), (\\d+), (\\d+)\\]");
  std::string line;

  if (file.is_open()) {
    while (std::getline(file, line)) {
      Sample* s = new Sample();
      std::smatch m;
      assert(std::regex_search(line, m, beforePattern));
      for (int i = 0; i < 4; ++i)
        s->priorState[i] = std::stoi(m[i+1].str());

      assert(std::getline(file, line));
      assert(std::regex_search(line, m, commandPattern));
      s->instructionCode = std::stoi(m[1].str());
      s->operandA = std::stoi(m[2].str());
      s->operandB = std::stoi(m[3].str());
      s->resultRegister = std::stoi(m[4].str());

      assert(std::getline(file, line));
      assert(std::regex_search(line, m, afterPattern));
      for (int i = 0; i < 4; ++i)
        s->postState[i] = std::stoi(m[i+1].str());

      samples.push_back(s);
      std::getline(file, line); // skip blank line
    }
  }
  return samples;
}

std::map<int, InstructionType> resolveMappings(std::vector<Sample*>& samples) {
  int highCount = 0;
  std::multimap<int, InstructionType> possibleCodes;

  for (auto s : samples) {
    auto candidates = determinePlausibleInstructions(s);
    if (candidates.size() >= 3) {
      ++highCount;
    }

    if (possibleCodes.count(s->instructionCode) > 0) {
      auto range = possibleCodes.equal_range(s->instructionCode);
      for (auto it = range.first; it != range.second;) {
        if (candidates.find(it->second) == candidates.end()) {
          it = possibleCodes.erase(it);
        } else {
          ++it;
        }
      }
    } else {
      for (auto c : candidates) {
        possibleCodes.emplace(s->instructionCode, c);
      }
    }
  }

  std::cout << "Samples with 3+ possible opcodes: " << highCount << "\n";

  std::map<int, InstructionType> finalMap;
  while (!possibleCodes.empty()) {
    for (int code = 0; code < 16; ++code) {
      if (possibleCodes.count(code) == 1) {
        auto range = possibleCodes.equal_range(code);
        InstructionType resolved = range.first->second;
        finalMap[code] = resolved;
        possibleCodes.erase(code);

        auto iter = possibleCodes.begin();
        while (iter != possibleCodes.end()) {
          if (iter->second == resolved) {
            iter = possibleCodes.erase(iter);
          } else {
            ++iter;
          }
        }
      }
    }
  }

  assert(possibleCodes.empty());
  return finalMap;
}

void runProgram(const std::map<int, InstructionType>& mapping) {
  std::ifstream programFile("16.2.input");
  std::string line;
  std::regex cmdRegex("(\\d+) (\\d+) (\\d+) (\\d+)");
  std::array<int, 4> registers{{0, 0, 0, 0}};

  if (programFile.is_open()) {
    while (std::getline(programFile, line)) {
      std::smatch match;
      assert(std::regex_search(line, match, cmdRegex));
      Command cmd;
      cmd.type = mapping.at(std::stoi(match[1].str()));
      cmd.src1 = std::stoi(match[2].str());
      cmd.src2 = std::stoi(match[3].str());
      cmd.dest = std::stoi(match[4].str());
      execute(cmd, registers);
    }
  }

  std::cout << "Final value in register 0: " << registers[0] << "\n";
}

int main() {
  auto samples = parseSamples("16.1.input");
  auto opcodeMap = resolveMappings(samples);
  runProgram(opcodeMap);
  return 0;
}

