// Read battery voltage with clamping to maximum value
double BatReader::readBatVoltage(void) {
    int rawValue = analogRead(BAT_PIN);
    double voltage = (static_cast<double>(rawValue) * ANA_REF) / 1024.0;

    // Clamp voltage to not exceed the maximum allowed value
    if (voltage > BAT_MAX) {
        return BAT_MAX;
    }
    return voltage;
}

// Calculate battery percentage using linear calibration
double BatReader::readBatPercent(void) {
    double measuredVoltage = readBatVoltage();
    double percent = (SLOPE * measuredVoltage) - OFFSET;

    // Ensure percentage doesn't go below zero
    if (percent < 0.0) {
        return 0.0;
    }
    return percent;
}

