DTint ContextSwitcher::swap_context(uContext *dest_ctx, const uContext *src_ctx)
{
    if (0 == context(dest_ctx)) {
        set_context(src_ctx);
    }
    return 0;
}

void ContextSwitcher::make_context(uContext *ucp, void (*entry_func)(void*), void *arg_data)
{
#if DT3_CPU == DT3_INTEL && DT3_POINTER_SIZE == DT3_32_BIT
    // Initialize machine context state
    ::memset(&ucp->uc_mcontext, 0, sizeof(ucp->uc_mcontext));

    // Calculate stack pointer position
    DTuint *stack_ptr = (DTuint*)ucp->uc_stack_sp;
    stack_ptr += ucp->uc_stack_ss / sizeof(void*);

    // Reserve space for argument and align stack
    stack_ptr -= 1;
    stack_ptr = (DTuint*)((DTuint)stack_ptr - ((DTuint)stack_ptr & 0xF)); // 16-byte alignment

    // Push function argument onto stack
    *stack_ptr = (DTuint64)arg_data;
    ucp->uc_mcontext.gregs[1] = *stack_ptr;

    // Set up return address and function entry point
    *--stack_ptr = 0; // return address
    ucp->uc_mcontext.gregs[15] = (DTuint)entry_func; // eip
    ucp->uc_mcontext.gregs[18] = (DTuint)stack_ptr;  // esp

#elif DT3_CPU == DT3_INTEL && DT3_POINTER_SIZE == DT3_64_BIT
    // Initialize machine context state
    ::memset(&ucp->uc_mcontext, 0, sizeof(ucp->uc_mcontext));

    // Calculate stack pointer position
    DTuint64 *stack_ptr = (DTuint64*)ucp->uc_stack_sp;
    stack_ptr += ucp->uc_stack_ss / sizeof(void*);

    // Reserve space for argument and align stack
    stack_ptr -= 1;
    stack_ptr = (DTuint64*)((DTuint64)stack_ptr - ((DTuint64)stack_ptr & 0xF)); // 16-byte alignment

    // Push function argument onto stack
    *stack_ptr = (DTuint64)arg_data;
    ucp->uc_mcontext.gregs[1] = *stack_ptr;

    // Set up return address and function entry point
    *--stack_ptr = 0; // return address
    ucp->uc_mcontext.gregs[20] = (DTuint64)entry_func;
    ucp->uc_mcontext.gregs[23] = (DTuint64)stack_ptr;

#elif DT3_CPU == DT3_ARM
    DTuint *stack_ptr;
    stack_ptr = (DTuint*)ucp->uc_stack_sp;
    stack_ptr += ucp->uc_stack_ss / sizeof(void*);

    // Setup ARM registers for context switch
    ucp->uc_mcontext.gregs[0] = (DTuint)arg_data;
    ucp->uc_mcontext.gregs[13] = (DTuint)stack_ptr;
    ucp->uc_mcontext.gregs[14] = (DTuint)entry_func;
#else
    // Architecture not yet supported
    ASSERT(false)
#endif
}

DTint ContextSwitcher::context(uContext *ucp)
{
    return m_context(&(ucp->uc_mcontext));
}

void ContextSwitcher::set_context(const uContext *ucp)
{
    set_m_context(&(ucp->uc_mcontext));
}
