namespace mio {

// Page size configuration - initialized at runtime
int kPageSizeShift = 12;
int kPageSize = (1 << kPageSizeShift); // 4 KB default
int kLargeSize = kPageSize / 4;
int kDefaultNativeCodeSize = 4 * kPageSize;
uintptr_t kPageAlignmentMask = -1;
int kNumberOfCpuCores = 1;

// Helper template function to fill memory with repeated pattern of type T
template<typename T>
inline void* FillMemoryPattern(const T value, void* buffer, size_t byteCount) {
    static_assert(sizeof(T) > 1 && sizeof(T) <= 8, "T must be int16, int32, or int64");
    static_assert(std::is_integral<T>::value, "T must be an integral type");
    DCHECK_GE(byteCount, 0);

    void* originalBuffer = buffer;
    size_t fullElements = byteCount / sizeof(T);

    // Fill full elements of size T
    while (fullElements--) {
        auto elementPtr = static_cast<T*>(buffer);
        *elementPtr = value;
        buffer = elementPtr + 1;
    }

    // Handle remaining bytes (< sizeof(T))
    const uint8_t* bytePattern = reinterpret_cast<const uint8_t*>(&value);
    size_t remainingBytes = byteCount % sizeof(T);

    while (remainingBytes--) {
        auto bytePtr = static_cast<uint8_t*>(buffer);
        *bytePtr = *bytePattern++;
        buffer = bytePtr + 1;
    }

    return originalBuffer;
}

// Type-specific wrappers for common integer sizes
void* FillWithUint16(const uint16_t pattern, void* buffer, size_t size) {
    return FillMemoryPattern<uint16_t>(pattern, buffer, size);
}

void* FillWithUint32(const uint32_t pattern, void* buffer, size_t size) {
    return FillMemoryPattern<uint32_t>(pattern, buffer, size);
}

void* FillWithUint64(const uint64_t pattern, void* buffer, size_t size) {
    return FillMemoryPattern<uint64_t>(pattern, buffer, size);
}

// Initialize environment settings based on system capabilities
void EnvironmentInitialize() {
    // Get system page size
    kPageSize = static_cast<int>(sysconf(_SC_PAGESIZE));
    PLOG_IF(FATAL, kPageSize <= 0) << "Failed to retrieve system page size!";

    // Calculate bit shift for page size
    int shiftAmount = 0;
    while ((1 << shiftAmount) < kPageSize) {
        ++shiftAmount;
    }
    kPageSizeShift = shiftAmount;

    // Compute alignment mask for page boundaries
    kPageAlignmentMask = ~(kPageSize - 1);

    DLOG(INFO) << "System page size: " << kPageSize << " bytes, shift: " << kPageSizeShift;

    // Detect number of online CPU cores
    kNumberOfCpuCores = static_cast<int>(sysconf(_SC_NPROCESSORS_ONLN));
    DLOG(INFO) << "Number of online CPU cores: " << kNumberOfCpuCores;

    // Update derived constants
    kLargeSize = kPageSize / 4;
    kDefaultNativeCodeSize = 4 * kPageSize;
}

} // namespace mio

