// Custom hash implementation for GUIDs — computes a polynomial rolling hash
template<>
class frg::hash<guid_t> {
public:
    unsigned int operator()(const guid_t &g) const {
        unsigned int h = g.d1;
        h = h * 31 + g.d2;
        h = h * 31 + g.d3;
        for (size_t idx = 0; idx < 8; ++idx) {
            h = h * 31 + g.d4[idx];
        }
        return h;
    }
};

namespace devices {

    // Type alias for filesystem initialization function pointer
    using filesystem_init_t = fs::fs_volume*(*)(partition_device*);

    // Structure representing a registered filesystem type
    struct filesystem_entry {
        const char* label;
        filesystem_init_t constructor;
    };

    // Map from GPT type GUID to supported filesystem implementations
    using filesystem_registry = frg::hash_map<
        guid_t,
        filesystem_entry,
        frg::hash<guid_t>,
        frg::stl_allocator
    >;

    // Pre-populated registry: only ext2 is supported for Linux data partitions
    static filesystem_registry filesystem_table{
        frg::hash<guid_t>{},
        {
            frg::make_tuple(gpt::GUID_LINUX_FS_DATA, filesystem_entry{"ext2", ext2_init})
        }
    };

    // Static counter for generating unique disk device numbers
    unsigned disk_device::next_device_num = 0;

    // Constructor: initializes base device and assigns name like "hd0", "hd1", ...
    disk_device::disk_device()
        : device(device_type::storage)
    {
        flags = fs::FS_NODE_BLKDEVICE;
        _name = static_cast<char*>(malloc(16));
        std::strncpy(_name, "hd", 2);
        itoa(next_device_num++, _name + 2, 10);
        _instance_name = _name;
    }

    // Destructor: releases dynamically allocated name buffer
    disk_device::~disk_device() {
        free(_name);
    }

    // Initialize and register each partition based on its filesystem type
    int disk_device::initialize_partitions() {
        char letter = 'a'; // unused in current logic but kept for compatibility

        size_t index = 0;
        while (index < _partitions.size()) {
            partition_device* current_partition = _partitions[index];

            auto lookup = filesystem_table.find(current_partition->type());
            if (lookup == filesystem_table.end()) {
                ++index;
                continue;
            }

            filesystem_entry& entry = lookup->second;
            fs::fs_volume* volume = entry.constructor(current_partition);

            if (!volume) {
                ++index;
                continue;
            }

            if (volume->error()) {
                delete volume;
            } else {
                fs::register_volume(volume, false);
            }

            ++index;
        }

        return 0;
    }

    // Read blocks from disk device
    ssize_t disk_device::read(size_t offset, size_t length, uint8_t* buffer) {
        if (offset % _block_size != 0) {
            return -EINVAL;
        }

        size_t block_index = offset / _block_size;
        return read_disk_block(block_index, length, buffer) ? static_cast<ssize_t>(length) : -EIO;
    }

    // Write operation not implemented
    ssize_t disk_device::write(size_t, size_t, uint8_t*) {
        return -ENOSYS;
    }

}

