namespace grains {
    // Calculate grains on a specific square using exponentiation
    unsigned long long square(int position) {
        return 1ULL << (position - 1);
    }

    // Compute total grains on entire chessboard by summing all squares
    uint64_t total() {
        unsigned long long result = 0;
        for (int i = 1; i <= 64; ++i) {
            result += square(i);
        }
        return result;
    }
}  // namespace grains

