#define PATTERN "%p memory, %zu length, %s file -> %p"

t_bunny_picture *bunny_read_picture_id(const void *_pic,
                                       size_t len,
                                       const char *file)
{
  struct bunny_picture *img;
  sf::Texture temp_texture;
  sf::Sprite temp_sprite;
  uint64_t identifier;

  identifier = bunny_hash(BH_FNV, file, strlen(file));

  // Allocate main picture structure
  if ((img = new (std::nothrow) struct bunny_picture) == NULL)
    goto FailureReturn;

  // Allocate sprite object
  if ((img->sprite = new (std::nothrow) sf::Sprite) == NULL)
    goto FreePicture;

  // Check if resource manager is disabled or file is null or texture not in cache
  if (RessourceManager.disable_manager ||
      file == NULL ||
      (img->texture = (sf::RenderTexture*)
       RessourceManager.TryGet(ResManager::SF_RENDERTEXTURE, identifier)) == NULL)
    {
      // Load from memory into temporary texture
      if (temp_texture.loadFromMemory(_pic, len) == false)
        goto FreeSprite;

      temp_sprite.setTexture(temp_texture);

      // Create new render texture
      if ((img->texture = new (std::nothrow) sf::RenderTexture) == NULL)
        goto FreeSprite;

      // Initialize render texture with same dimensions as loaded texture
      if (img->texture->create(temp_texture.getSize().x, temp_texture.getSize().y) == false)
        goto FreeRenderTexture;

      // Draw the sprite onto the render texture
      img->texture->clear(sf::Color(0, 0, 0, 0));
      img->texture->draw(temp_sprite);
      img->texture->display();
    }

  // Register with resource manager if enabled
  if (RessourceManager.disable_manager == false)
    RessourceManager.AddToPool(ResManager::SF_RENDERTEXTURE, file, identifier, img, img->texture);

  // Set up picture properties
  img->res_id = identifier;
  img->tex = &img->texture->getTexture();
  img->sprite->setTexture(*img->tex);
  img->type = GRAPHIC_RAM;
  img->width = img->tex->getSize().x;
  img->height = img->tex->getSize().y;
  img->rect.x = 0;
  img->rect.y = 0;
  img->rect.w = img->width;
  img->rect.h = img->height;
  img->position.x = 0;
  img->position.y = 0;
  img->origin.x = 0;
  img->origin.y = 0;
  img->scale.x = 1;
  img->scale.y = 1;
  img->rotation = 0;
  img->color_mask.full = WHITE;
  img->smooth = false;
  img->mosaic = false;

  scream_log_if(PATTERN, "ressource,graphics", _pic, len, file, img);
  return ((t_bunny_picture*)img);

FreeRenderTexture:
  delete img->texture;
FreeSprite:
  delete img->sprite;
FreePicture:
  delete img;
FailureReturn:
  scream_error_if(return (NULL), ENOMEM, PATTERN, "ressource,graphics", _pic, len, file, (void*)NULL);
  return (NULL);
}

