//----------------------------------------------------------------------------------------------
// @name                    : initializeStorageManager
//
// @description             : Creates pools based on initial pool sizes specified.
//
// @param initialPoolSize   : This is the size of each pool (in bytes) that will be allocated
//                            at startup.
// @param numPools          : Number of pools specified at startup
// @param pools             : Array containing size of different pools that need to be created
//                            at startup
//
// @returns                 : Nothing
//----------------------------------------------------------------------------------------------
void initStorageManager(const unsigned initialPoolSize, int numPools, const unsigned int *pools)
{
    g_initialPoolSize = initialPoolSize;
    unsigned long totalAllocatedBytes = 0;

    printf("StorageManager:: Initial Pools- ");
    for (int idx = 0; idx < numPools; ++idx)
    {
        PoolData_t *poolInfo = static_cast<PoolData_t*>(malloc(sizeof(PoolData_t)));
        if (!poolInfo)
        {
            printf("\n\n**MEMORY ERROR: initStorageManager: Failed to allocate metadata for pool %u!!\n\n", pools[idx]);
            std::abort();
        }

        std::memset(poolInfo, 0, sizeof(PoolData_t));

        size_t poolByteCount = static_cast<size_t>(pools[idx]) * sizeof(char) * g_initialPoolSize;
        totalAllocatedBytes += poolByteCount;

        char *memoryBlock = static_cast<char*>(malloc(poolByteCount));
        if (!memoryBlock)
        {
            printf("\n\n**MEMORY ERROR: initStorageManager: Failed to allocate memory for pool %u!!\n\n", pools[idx]);
            std::free(poolInfo);
            std::abort();
        }

        setupPoolStructure(poolByteCount, memoryBlock, pools[idx], poolInfo);

        printf("%d ", pools[idx]);
    }

    printf("\nStorageManager:: Pool initialization complete\n");
    printf("Total claimed memory: %lu MB\n\n", totalAllocatedBytes / (1024UL * 1024UL));
}

//----------------------------------------------------------------------------------------------
// @name                    : instantiateNewPool
//
// @description             : Creates a new memory pool when an allocation request exceeds
//                            existing pool sizes. Memory is allocated and initialized.
//
// @param requestedSize     : The size (in bytes) for which no pool currently exists.
//
// @returns                 : Nothing
//----------------------------------------------------------------------------------------------
void createNewPool(unsigned requestedSize)
{
    PoolData_t *poolInfo = static_cast<PoolData_t*>(malloc(sizeof(PoolData_t)));
    if (!poolInfo)
    {
        printf("\n\n**MEMORY ERROR: instantiateNewPool: Failed to allocate metadata for pool %u!!\n\n", requestedSize);
        std::abort();
    }

    std::memset(poolInfo, 0, sizeof(PoolData_t));

    size_t poolByteCount = static_cast<size_t>(requestedSize) * sizeof(char) * g_initialPoolSize;
    char *memoryBlock = static_cast<char*>(malloc(poolByteCount));
    if (!memoryBlock)
    {
        printf("\n\n**MEMORY ERROR: instantiateNewPool: Failed to allocate memory for pool %u!!\n\n", requestedSize);
        std::free(poolInfo);
        std::abort();
    }

    setupPoolStructure(poolByteCount, memoryBlock, requestedSize, poolInfo);
    printf("Created new pool : %u\n", requestedSize);
}

//----------------------------------------------------------------------------------------------
// @name                    : setupPoolStructure
//
// @description             : Initialize the Pool-specific metadata structure.
//
// @param totalBytes        : Total size of the pool in bytes.
// @param baseAddress       : Pointer to start of this memory pool.
// @param blockSize         : Size ID of this pool (e.g., 8 for 8-byte blocks).
// @param poolMetadata      : Pool metadata structure to be initialized.
//
// @returns                 : Nothing
//----------------------------------------------------------------------------------------------
void setupPoolStructure(size_t totalBytes, char *baseAddress, unsigned int blockSize, PoolData_t *poolMetadata)
{
    poolMetadata->poolSize = blockSize;
    poolMetadata->startAddress = baseAddress;
    poolMetadata->endAddress = baseAddress + totalBytes;
    poolMetadata->totalSize = totalBytes;
    poolMetadata->remainingSpace = totalBytes;
    poolMetadata->totalBlocks = totalBytes / blockSize;
    poolMetadata->freeBlocks = poolMetadata->totalBlocks;
    poolMetadata->usedBlocks = 0;
    poolMetadata->nextFreeBlock = -1;
    poolMetadata->nextFreeBlockInSequence = 0;
    poolMetadata->isFreedBlockBlockAvailable = false;
    poolMetadata->totalAllocationsFromThisPool = 0;

    g_poolRegistry[blockSize] = poolMetadata;
}

