//----------------------------------------------------------------------------------------------
// @name                    : SM_alloc
//
// @description             : Allocates memory from an appropriate pool or creates a new one.
//
// @param requestedSize     : Size of memory requested for heap allocation.
//
// @returns                 : Pointer to allocated memory block.
//----------------------------------------------------------------------------------------------
void * SM_alloc(size_t requestedSize)
{
    PoolData_t *targetPool = g_poolRegistry[requestedSize];

    if (!targetPool)
    {
        createNewPool(static_cast<unsigned>(requestedSize));
        targetPool = g_poolRegistry[requestedSize];
    }

    if (targetPool->freeBlocks == 0)
    {
        printf("ERROR: Pool %u exhausted!\n", requestedSize);
        std::abort();
    }

    char *allocatedPtr = nullptr;

    if (targetPool->isFreedBlockBlockAvailable && targetPool->nextFreeBlock >= 0)
    {
        allocatedPtr = getPointerFromBlockIndex(targetPool->nextFreeBlock, targetPool);
        targetPool->isFreedBlockBlockAvailable = false;
        targetPool->nextFreeBlock = -1;
    }
    else
    {
        allocatedPtr = getPointerFromBlockIndex(targetPool->nextFreeBlockInSequence, targetPool);
        ++targetPool->nextFreeBlockInSequence;
    }

    /* Update statistics */
    --targetPool->freeBlocks;
    ++targetPool->usedBlocks;
    targetPool->remainingSpace -= requestedSize;
    ++targetPool->totalAllocationsFromThisPool;

    return allocatedPtr;
}

//----------------------------------------------------------------------------------------------
// @name                    : SM_dealloc
//
// @description             : Marks memory as reusable without actually freeing it.
//
// @param ptr               : Pointer to memory to be deallocated.
//
// @returns                 : Nothing
//----------------------------------------------------------------------------------------------
void SM_dealloc(void *ptr)
{
    if (!ptr)
        return;

    unsigned int poolId = locatePoolForAddress(ptr);
    PoolData_t *pool = g_poolRegistry[poolId];

    ++pool->freeBlocks;
    --pool->usedBlocks;
    pool->nextFreeBlock = getBlockIndexFromPointer(static_cast<char*>(ptr), pool);
    pool->isFreedBlockBlockAvailable = true;
    pool->remainingSpace += poolId;

    // Optional debug output:
    // printf("Deallocated 0x%p block (%u) from pool %u\n", ptr, pool->nextFreeBlock, poolId);
}

//----------------------------------------------------------------------------------------------
// @name                    : locatePoolForAddress
//
// @description             : Determines which pool contains the given pointer.
//
// @param addr              : Memory address to search for.
//
// @returns                 : Pool size (ID) containing the address.
//----------------------------------------------------------------------------------------------
unsigned int locatePoolForAddress(void *addr)
{
    for (const auto& entry : g_poolRegistry)
    {
        PoolData_t *pool = entry.second;
        if (addr >= pool->startAddress && addr < pool->endAddress)
        {
            return pool->poolSize;
        }
    }

    printf("\n\n**ERROR: 0x%p not found in any memory pool!!\n\n", addr);
    std::abort();
}

//----------------------------------------------------------------------------------------------
// @name                    : getPointerFromBlockIndex
//
// @description             : Converts block index to actual memory address within a pool.
//
// @param blockIndex        : Index of the block in the pool.
// @param pool              : Pool metadata.
//
// @returns                 : Pointer to the block.
//----------------------------------------------------------------------------------------------
char *getPointerFromBlockIndex(unsigned int blockIndex, PoolData_t *pool)
{
    return pool->startAddress + (blockIndex * pool->poolSize);
}

//----------------------------------------------------------------------------------------------
// @name                    : getBlockIndexFromPointer
//
// @description             : Converts memory address to its corresponding block index.
//
// @param address           : Memory address.
// @param pool              : Pool metadata.
//
// @returns                 : Block index.
//----------------------------------------------------------------------------------------------
unsigned int getBlockIndexFromPointer(char *address, PoolData_t *pool)
{
    return static_cast<unsigned int>((address - pool->startAddress) / pool->poolSize);
}

