class NumMatrix {
public:
    // Sparse table storing prefix sums per row in power-of-two intervals
    std::vector<std::vector<std::vector<int>>> sparseTable;
    int maxLog;

    NumMatrix(std::vector<std::vector<int>>& matrix) {
        int rows = matrix.size();
        if (rows == 0) return;

        int cols = matrix[0].size();
        maxLog = static_cast<int>(std::log2(cols));

        // Initialize sparse table with dimensions [rows][cols][maxLog+1]
        sparseTable.resize(rows, std::vector<std::vector<int>>(cols, std::vector<int>(maxLog + 1, 0)));

        // Base case: intervals of length 1
        for (int r = 0; r < rows; ++r) {
            for (int c = 0; c < cols; ++c) {
                sparseTable[r][c][0] = matrix[r][c];
            }
        }

        // Build sparse table for each row independently
        for (int r = 0; r < rows; ++r) {
            for (int j = 1; j <= maxLog; ++j) {
                int intervalSize = 1 << j;  // 2^j
                for (int start = 0; start + intervalSize <= cols; ++start) {
                    int half = 1 << (j - 1);  // 2^(j-1)
                    sparseTable[r][start][j] = sparseTable[r][start][j-1] + 
                                               sparseTable[r][start + half][j-1];
                }
            }
        }
    }

    int sumRegion(int row1, int col1, int row2, int col2) {
        int totalSum = 0;

        // Process each row in the range [row1, row2]
        for (int r = row1; r <= row2; ++r) {
            int currentPos = col1;

            // Use sparse table to compute sum from col1 to col2 efficiently
            for (int j = maxLog; j >= 0; --j) {
                int segmentLength = 1 << j;  // 2^j

                if (currentPos + segmentLength - 1 <= col2) {
                    totalSum += sparseTable[r][currentPos][j];
                    currentPos += segmentLength;
                }
            }
        }

        return totalSum;
    }
};

/**
 * Your NumMatrix object will be instantiated and called as such:
 * NumMatrix* obj = new NumMatrix(matrix);
 * int param_1 = obj->sumRegion(row1,col1,row2,col2);
 */

