// Helper function to parse integer from string
size_t ConvertToInt(const std::string& input) {
  size_t value = 0;
  std::istringstream stream(input);
  stream >> value;
  return value;
}

int main(int argc, char* argv[]) {
  // Validate command-line arguments
  if (argc != 5) {
    std::cerr << "Usage: " << argv[0]
              << " width height endian_mode shift_bits < infile > outfile\n"
              << "    width, height: dimensions of each video frame in pixels\n"
              << "    endian_mode: byte order of raw data (0 for little-endian, 1 for big-endian)\n"
              << "    shift_bits: number of bits to left-shift to align 12-bit data to MSBs:\n"
              << "                xxxxxxxxxxxx0000 format\n"
              << std::endl;
    return 1;
  }

  // Parse and validate parameters
  size_t frame_width = ConvertToInt(argv[1]);
  size_t frame_height = ConvertToInt(argv[2]);
  size_t is_big_endian = ConvertToInt(argv[3]);
  size_t bit_shift = ConvertToInt(argv[4]);

  // Input validation for frame dimensions
  if (frame_width == 0 || frame_width > 65536 || 
      frame_height == 0 || frame_height > 65536) {
    std::cerr << "Error: invalid frame dimensions - width=" << frame_width 
              << ", height=" << frame_height << std::endl;
    return 1;
  }

  // Validate shift parameter
  if (bit_shift > 16) {
    std::cerr << "Error: invalid bit shift value: " << bit_shift << std::endl;
    return 1;
  }

  // Calculate buffer sizes
  size_t frame_bytes = frame_width * frame_height * 2;
  std::vector<uint16_t> decoded_frame;
  std::vector<uint8_t> compressed_data;

  // Initialize decoder and processing variables
  fpvc::StreamingDecoder video_decoder;
  const size_t chunk_size = (1 << 20);  // 1MB chunks
  std::vector<uint8_t> input_chunk(chunk_size);
  std::vector<uint8_t> output_frame(frame_bytes);
  size_t frame_counter = 0;

  // Process input stream in chunks
  while (std::cin) {
    size_t bytes_read = chunk_size;

    // Read next chunk from stdin
    if (!std::cin.read(reinterpret_cast<char*>(input_chunk.data()), chunk_size)) {
      bytes_read = static_cast<size_t>(std::cin.gcount());
      if (bytes_read == 0) break;
    }

    // Decode the current chunk
    video_decoder.Decode(
        input_chunk.data(), bytes_read,
        [bit_shift, is_big_endian, &frame_counter, &output_frame](
            bool success, const uint16_t* frame_data,
            size_t width, size_t height, void* /*payload*/) {
          if (!success) {
            std::cerr << "Frame decompression failed" << std::endl;
            std::exit(1);
          }

          // Extract and convert frame data
          fpvc::UnextractFrame(frame_data, width, height, bit_shift, 
                              is_big_endian, output_frame.data());

          // Write raw frame to stdout
          fwrite(output_frame.data(), sizeof(uint8_t), output_frame.size(), stdout);

          // Log progress
          std::cerr << "Processed frame #" << frame_counter++ << std::endl;
        },
        nullptr);
  }

  return 0;
}

