void fvec_madd_ref(
        size_t n,
        const float* a,
        float bf,
        const float* b,
        float* c) {
    size_t idx = 0;
    while (idx < n) {
        c[idx] = a[idx] + bf * b[idx];
        idx++;
    }
}

int fvec_madd_and_argmin_ref(
        size_t n,
        const float* a,
        float bf,
        const float* b,
        float* c) {
    int min_pos = -1;
    float curr_min = 0.0f;
    bool first_val = true;

    for (size_t j = 0; j < n; j++) {
        c[j] = a[j] + bf * b[j];

        if (first_val || c[j] < curr_min) {
            curr_min = c[j];
            min_pos = j;
            first_val = false;
        }
    }

    return min_pos;
}
