// Compute product of integers from 'from' to 'to' inclusive
uint64_t rangeProduct(uint64_t from, uint64_t to) {
    if (from > to) return 1;
    uint64_t result = 1;
    for (uint64_t k = from; k <= to; ++k) {
        result *= k;
    }
    return result;
}

// Evaluate Jacobi polynomial P_n^(a,b)(x) using recurrence relation
double JacobiP(unsigned n, unsigned a, unsigned b, double x) {
    if (n == 0) {
        return 1.0;
    }

    double prev_prev = 1.0;
    double prev_val = 0.5 * (a - b) + (1.0 + 0.5 * (a + b)) * x;

    double coeff_a2_b2 = static_cast<double>(a * a - b * b);

    for (unsigned m = 2; m <= n; ++m) {
        double curr = ((2.0 * m + a + b - 1.0) * 
                      (coeff_a2_b2 + (2.0 * m + a + b) * (2.0 * m + a + b - 2.0) * x) * prev_val -
                      2.0 * (m + a - 1.0) * (m + b - 1.0) * (2.0 * m + a + b) * prev_prev) /
                     (2.0 * m * (m + a + b) * (2.0 * m + a + b - 2.0));

        prev_prev = prev_val;
        prev_val = curr;
    }

    return prev_val;
}

// Derivative of Jacobi polynomial using known identity
double JacobiPDerivative(unsigned n, unsigned a, unsigned b, double x) {
    if (n == 0) {
        return 0.0;
    }
    return 0.5 * (n + a + b + 1.0) * JacobiP(n - 1, a + 1, b + 1, x);
}

// Precompute coefficients for singularity-free Jacobi recurrence
std::array<double, 5> SingularityFreeJacobiPFactors(unsigned m, unsigned a, unsigned b) {
    double c0 = 2.0 * m + a + b;
    double c1 = c0 - 1.0;
    double c2 = static_cast<double>(a * a - b * b);
    double c3 = c0 * (c0 - 2.0);
    double c4 = 2.0 * (m + a - 1.0) * (m + b - 1.0) * c0;
    double c5 = 2.0 * m * (m + a + b) * (c0 - 2.0);

    return {c1, c2, c3, c4, c5};
}

// Perform one step of singularity-free Jacobi recurrence
double SingularityFreeJacobiPRecursion(double x, double y, std::array<double, 5> const& cm,
                                       double Pm_1, double Pm_2) {
    return (cm[0] * (cm[1] * y + cm[2] * x) * Pm_1 - cm[3] * y * y * Pm_2) / cm[4];
}

// Evaluate Jacobi polynomial in singularity-free form using two variables
double SingularityFreeJacobiP(unsigned n, unsigned a, unsigned b, double x, double y) {
    if (n == 0) {
        return 1.0;
    }

    double prev_prev = 1.0;
    double prev_val = (0.5 * a - 0.5 * b) * y + (1.0 + 0.5 * (a + b)) * x;

    for (unsigned m = 2; m <= n; ++m) {
        double curr = SingularityFreeJacobiPRecursion(x, y, 
            SingularityFreeJacobiPFactors(m, a, b), prev_val, prev_prev);

        prev_prev = prev_val;
        prev_val = curr;
    }

    return prev_val;
}

// Compute value and partial derivatives of singularity-free Jacobi polynomial
std::array<double, 3> SingularityFreeJacobiPAndDerivatives(unsigned n, unsigned a, unsigned b,
                                                           double x, double y) {
    if (n == 0) {
        return {1.0, 0.0, 0.0};
    }

    double P_prev_prev = 1.0, ddx_P_prev_prev = 0.0, ddy_P_prev_prev = 0.0;
    double P_prev = 1.0, ddx_P_prev = 0.0, ddy_P_prev = 0.0;

    // First-order polynomial
    double P_curr = SingularityFreeJacobiP(1, a, b, x, y);
    double ddx_P_curr = 1.0 + 0.5 * (a + b);
    double ddy_P_curr = 0.5 * (static_cast<double>(a) - static_cast<double>(b));

    for (unsigned m = 2; m <= n; ++m) {
        auto coeffs = SingularityFreeJacobiPFactors(m, a, b);

        // Update function value
        double temp_P = SingularityFreeJacobiPRecursion(x, y, coeffs, P_curr, P_prev);

        // Update derivatives
        double temp_ddx_P = (coeffs[0] * (coeffs[2] * P_curr + (coeffs[1] * y + coeffs[2] * x) * ddx_P_curr) -
                            coeffs[3] * y * y * ddx_P_prev) / coeffs[4];
        double temp_ddy_P = (coeffs[0] * (coeffs[1] * P_curr + (coeffs[1] * y + coeffs[2] * x) * ddy_P_curr) -
                            coeffs[3] * (2.0 * y * P_prev + y * y * ddy_P_prev)) / coeffs[4];

        // Shift values forward
        P_prev_prev = P_prev;
        P_prev = P_curr;
        P_curr = temp_P;

        ddx_P_prev_prev = ddx_P_prev;
        ddx_P_prev = ddx_P_curr;
        ddx_P_curr = temp_ddx_P;

        ddy_P_prev_prev = ddy_P_prev;
        ddy_P_prev = ddy_P_curr;
        ddy_P_curr = temp_ddy_P;
    }

    return {P_curr, ddx_P_curr, ddy_P_curr};
}

// Triangular Dubiner polynomial evaluation
double TriDubinerP(std::array<unsigned, 2> const& i, std::array<double, 2> const& xi) {
    double r_num = 2.0 * xi[0] - 1.0 + xi[1];
    double s = 2.0 * xi[1] - 1.0;
    double theta = 1.0 - xi[1];

    double ti = SingularityFreeJacobiP(i[0], 0, 0, r_num, theta);
    double tij = SingularityFreeJacobiP(i[1], 2 * i[0] + 1, 0, s, 1.0);

    return ti * tij;
}

// Gradient of triangular Dubiner polynomial
std::array<double, 2> gradTriDubinerP(std::array<unsigned, 2> const& i,
                                      std::array<double, 2> const& xi) {
    double r_num = 2.0 * xi[0] - 1.0 + xi[1];
    double s = 2.0 * xi[1] - 1.0;
    double theta = 1.0 - xi[1];

    auto ti_vals = SingularityFreeJacobiPAndDerivatives(i[0], 0, 0, r_num, theta);
    auto tij_vals = SingularityFreeJacobiPAndDerivatives(i[1], 2 * i[0] + 1, 0, s, 1.0);

    auto ddalpha = [&](double dr_num, double dtheta, double dt) {
        return (ti_vals[1] * dr_num + ti_vals[2] * dtheta) * tij_vals[0] + 
               ti_vals[0] * tij_vals[1] * dt;
    };

    return {ddalpha(2.0, 0.0, 0.0), ddalpha(1.0, -1.0, 2.0)};
}

// Tetrahedral Dubiner polynomial evaluation
double TetraDubinerP(std::array<unsigned, 3> const& i, std::array<double, 3> const& xi) {
    double r_num = 2.0 * xi[0] - 1.0 + xi[1] + xi[2];
    double s_num = 2.0 * xi[1] - 1.0 + xi[2];
    double t = 2.0 * xi[2] - 1.0;
    double sigmatheta = 1.0 - xi[1] - xi[2];
    double theta = 1.0 - xi[2];

    double ti = SingularityFreeJacobiP(i[0], 0, 0, r_num, sigmatheta);
    double tij = SingularityFreeJacobiP(i[1], 2 * i[0] + 1, 0, s_num, theta);
    double tijk = SingularityFreeJacobiP(i[2], 2 * i[0] + 2 * i[1] + 2, 0, t, 1.0);

    return ti * tij * tijk;
}

// Gradient of tetrahedral Dubiner polynomial
std::array<double, 3> gradTetraDubinerP(std::array<unsigned, 3> const& i,
                                        std::array<double, 3> const& xi) {
    double r_num = 2.0 * xi[0] - 1.0 + xi[1] + xi[2];
    double s_num = 2.0 * xi[1] - 1.0 + xi[2];
    double t = 2.0 * xi[2] - 1.0;
    double sigmatheta = 1.0 - xi[1] - xi[2];
    double theta = 1.0 - xi[2];

    auto ti_vals = SingularityFreeJacobiPAndDerivatives(i[0], 0, 0, r_num, sigmatheta);
    auto tij_vals = SingularityFreeJacobiPAndDerivatives(i[1], 2 * i[0] + 1, 0, s_num, theta);
    auto tijk_vals = SingularityFreeJacobiPAndDerivatives(i[2], 2 * i[0] + 2 * i[1] + 2, 0, t, 1.0);

    auto ddalpha = [&](double dr_num, double dsigmatheta, double ds_num, double dtheta, double dt) {
        return (ti_vals[1] * dr_num + ti_vals[2] * dsigmatheta) * tij_vals[0] * tijk_vals[0] +
               ti_vals[0] * (tij_vals[1] * ds_num + tij_vals[2] * dtheta) * tijk_vals[0] +
               ti_vals[0] * tij_vals[0] * (tijk_vals[1] * dt);
    };

    return {ddalpha(2.0, 0.0, 0.0, 0.0, 0.0), 
            ddalpha(1.0, -1.0, 2.0, 0.0, 0.0),
            ddalpha(1.0, -1.0, 1.0, -1.0, 2.0)};
}

