WebrootOverridesProvider::WebrootOverridesProvider(
    Config const & cfg,
    unsigned int interval
)
:   categorizationsMutex(),
    categorizationsMap(),
    sleepMutex(),
    updateThread(),
    stopCondition(),
    stopped(false),
    forceUpdateRequired(false),
    readyCondition(),
    ready(false),
    config(cfg),
    updateInterval(interval)
{
}

WebrootOverridesProvider::~WebrootOverridesProvider()
{
    {
        std::lock_guard<std::mutex> guard(sleepMutex);
        stopped = true;
        stopCondition.notify_one();
    }
    updateThread.join();
}

void WebrootOverridesProvider::forceUpdateMap()
{
    std::lock_guard<std::mutex> guard(sleepMutex);
    forceUpdateRequired = true;
    stopCondition.notify_one();
}

void WebrootOverridesProvider::start()
{
    updateThread = std::thread(&WebrootOverridesProvider::updateLoop, this);
}

void WebrootOverridesProvider::waitUntilReady()
{
    std::unique_lock<std::mutex> lock(sleepMutex);
    readyCondition.wait(lock, [this]() { return ready; });
}

webroot::Categorizations WebrootOverridesProvider::findCategorization(std::string const & inputUrl) const
{
    DASSERT(ready, "database not yet loaded");
    webroot::Categorizations output;
    int lcpMatches = 0;
    std::string normalizedUrl = inputUrl;

    // Normalize URL to lowercase for consistent matching
    std::transform(normalizedUrl.begin(), normalizedUrl.end(), normalizedUrl.begin(),
                   [](unsigned char c){ return std::tolower(c); });

    // Parse LCP representation
    cLcpParse lcpParser(&normalizedUrl[0], psCfg->nLcpLoopLimit, lcpMatches);
    if (!lcpMatches)
    {
        DLOG(1, "Failed to parse LCP for URL: " << inputUrl);
        return output;
    }

    boost::shared_lock<boost::shared_mutex> readLock(categorizationsMutex);
    c_md5 hasher;
    char lcpBuffer[URL_SIZE];

    while (lcpParser.nGetLcp(&normalizedUrl[0], lcpBuffer))
    {
        DLOG(3, "Processing LCP: " << lcpBuffer << " for original URL: " << inputUrl);
        hasher.setByUrl(lcpBuffer);

        auto iter = categorizationsMap.find(hasher);
        if (iter != categorizationsMap.end())
        {
            DLOG(1, "Matched override: " << lcpBuffer << " => " << iter->second);
            output.push_back(iter->second);
            break;
        }
    }

    return output;
}

static std::vector<db::PreparedStatement> const sqlStatements =
{
    {
        "get_overrides",
        "SELECT address, code_categories_ext_id FROM webroot_overrides",
        0
    }
};

void WebrootOverridesProvider::updateLoop()
{
    LOG(INFO, "Starting webroot overrides refresh thread");

    db::DBConnection::ResultType connRes = db::DBConnection::create(
        config.dbHost,
        config.dbPort,
        config.dbName,
        config.dbUser,
        config.dbPassword,
        config.sslMode
    );

    if (connRes.isError())
    {
        LOG(ERROR, "Database connection failed: " << connRes.getError());
        FAILURE("Unable to connect to database.");
    }

    db::DBConnection & db = *connRes.getValue();
    db.setSocketTimeout(boost::posix_time::seconds(30));
    db.setPreparedStatements(sqlStatements);

    for (;;)
    {
        CategorizationsMap tempMap;
        bool success = fetchOverrides(db, tempMap);

        if (success)
        {
            boost::unique_lock<boost::shared_mutex> writeLock(categorizationsMutex);
            categorizationsMap = std::move(tempMap);
        }
        else
        {
            LOG(ERROR, "Failed to retrieve webroot overrides from DB");
            ASSERT(ready, "Initial load failed — check configuration or DB status");
        }

        std::unique_lock<std::mutex> sleepLock(sleepMutex);

        if (!ready)
        {
            ready = true;
            readyCondition.notify_all();
        }

        auto waitResult = stopCondition.wait_until(
            sleepLock,
            computeNextRefreshTime(),
            [this]() { return forceUpdateRequired || stopped; }
        );

        if (waitResult)
        {
            if (stopped)
                break;

            if (forceUpdateRequired)
            {
                forceUpdateRequired = false;
            }
        }
    }

    LOG(INFO, "Webroot overrides refresh thread exiting");
}

system_clock::time_point WebrootOverridesProvider::computeNextRefreshTime() const
{
    time_t current = system_clock::to_time_t(system_clock::now());
    time_t nextBoundary = ((current / updateInterval) + 1) * updateInterval;
    return system_clock::from_time_t(nextBoundary);
}

bool WebrootOverridesProvider::fetchOverrides(db::DBConnection const & dbConn, CategorizationsMap & targetMap)
{
    LOG(INFO, "Retrieving webroot overrides from database");

    db::DBConnection::QueryResult queryRes = dbConn.queryPrepared(
        "get_overrides",
        0, nullptr, nullptr, nullptr
    );

    if (queryRes.isError())
    {
        return false;
    }

    std::list<db::DBConnection::row_t> const & rows = *queryRes.getValue();
    c_md5 hasher;
    char buffer[URL_SIZE];

    for (auto const & row : rows)
    {
        std::string rawUrl = su::shortenUrl(row.at(0));
        webroot::Category cat = static_cast<webroot::Category>(
            boost::lexical_cast<unsigned int>(row.at(1))
        );

        int lcpFound = 0;
        std::string urlLower = rawUrl;
        std::transform(urlLower.begin(), urlLower.end(), urlLower.begin(),
                       [](unsigned char c){ return std::tolower(c); });

        cLcpParse parser(&urlLower[0], psCfg->nLcpLoopLimit, lcpFound);
        if (!lcpFound)
        {
            LOG(ERROR, "LCP parsing failed for override URL: " << rawUrl);
            continue;
        }

        int parsedCount = parser.nGetLcp(&urlLower[0], buffer);
        DASSERT(parsedCount == 1, "Expected exactly one LCP segment", rawUrl);

        hasher.setByUrl(buffer);
        DLOG(1, "Registering override: " << buffer << " -> " << webroot::Categorization::forCategory(cat));

        auto insertPair = targetMap.emplace(hasher, webroot::Categorization::forCategory(cat));
        if (!insertPair.second)
        {
            ALERT("Duplicate override detected for LCP [" << buffer << "] (original: " << rawUrl << ")");
        }
    }

    return true;
}

