// Stub implementation of __cxa_demangle to reduce binary size.
// Prevents pulling in LLVM demangler from libc++.
extern "C" char* __cxa_demangle(const char* mangled,
                                char* buffer,
                                size_t* len,
                                int* err) {
  static const int kAllocFail = -1;
  if (err)
    *err = kAllocFail;
  return nullptr;
}

#ifdef __arm__
extern "C" int __cxa_atexit(void (*)(void*), void*, void*);

// ARM EABI requires __aeabi_atexit; fallback wrapper.
int __aeabi_atexit(void* obj, void (*dtor)(void*), void* dso) {
  return __cxa_atexit(dtor, obj, dso);
}
#endif

// Save system dlerror() into thread-local storage.
void RecordSystemError() {
  ThreadData* tls = GetThreadData();
  tls->SetError(::dlerror());
}

// Return current error string and swap buffers.
char* FetchAndSwapError() {
  ThreadData* tls = GetThreadData();
  const char* msg = tls->GetError();
  tls->SwapErrorBuffers();
  return const_cast<char*>(msg);
}

// Wrapper around dlopen: try crazy first, fall back to system.
void* OpenLibrary(const char* filename, int flags) {
  ScopedGlobalLock guard;

  if (filename) {
    LibraryList* libs = Globals::GetLibraries();
    Error err;
    LibraryView* lib = libs->LoadLibrary(filename,
                                         flags,
                                         0U,
                                         0U,
                                         Globals::GetSearchPaths(),
                                         false,
                                         &err);
    if (lib)
      return lib;
  }

  // Fallback to system loader
  ::dlerror();
  void* sys_lib = ::dlopen(filename, flags);
  if (!sys_lib) {
    RecordSystemError();
    return nullptr;
  }

  LibraryView* wrap = new LibraryView();
  wrap->SetSystem(sys_lib, filename ? filename : "<main>");
  Globals::GetLibraries()->AddLibrary(wrap);
  return wrap;
}

// Wrapper around dlsym: search in crazy or system library.
void* ResolveSymbol(void* handle, const char* sym) {
  LibraryView* lib = reinterpret_cast<LibraryView*>(handle);

  if (!sym) {
    SetLinkerError("dlsym: NULL symbol name");
    return nullptr;
  }
  if (!handle) {
    SetLinkerError("dlsym: NULL library handle");
    return nullptr;
  }

  if (handle == RTLD_DEFAULT || handle == RTLD_NEXT) {
    SetLinkerError("dlsym: RTLD_DEFAULT/RTLD_NEXT not supported");
    return nullptr;
  }

  if (lib->IsSystem()) {
    void* addr = ::dlsym(lib->GetSystem(), sym);
    if (!addr) {
      RecordSystemError();
      LOG("dlsym:%s: symbol '%s' not found in system lib\n%s",
          lib->GetName(),
          sym,
          GetThreadData()->GetError());
    }
    return addr;
  }

  if (lib->IsCrazy()) {
    ScopedGlobalLock guard;
    LibraryList* list = Globals::GetLibraries();
    void* addr = list->FindSymbolFrom(sym, lib);
    if (addr)
      return addr;

    SetLinkerError("dlsym: symbol '%s' not found in '%s'", sym, lib->GetName());
    return nullptr;
  }

  SetLinkerError("dlsym: invalid handle %p for symbol '%s'", handle, sym);
  return nullptr;
}

// Wrapper around dladdr: find symbol info for address.
int FindAddressInfo(void* addr, Dl_info* info) {
  {
    ScopedGlobalLock guard;
    LibraryList* list = Globals::GetLibraries();
    LibraryView* lib = list->FindLibraryForAddress(addr);
    if (lib && lib->IsCrazy()) {
      size_t size = 0;
      SharedLibrary* shlib = lib->GetCrazy();
      ::memset(info, 0, sizeof(*info));
      info->dli_fname = shlib->base_name();
      info->dli_fbase = reinterpret_cast<void*>(shlib->load_address());
      (void)shlib->FindNearestSymbolForAddress(addr,
                                               &info->dli_sname,
                                               &info->dli_saddr,
                                               &size);
      return 0;
    }
  }

  // Fallback to system dladdr()
  ::dlerror();
  int res = ::dladdr(addr, info);
  if (res != 0)
    RecordSystemError();
  return res;
}

// Wrapper around dlclose: unload library.
int CloseLibrary(void* handle) {
  LibraryView* lib = reinterpret_cast<LibraryView*>(handle);
  if (!lib) {
    SetLinkerError("NULL library handle");
    return -1;
  }

  if (lib->IsSystem() || lib->IsCrazy()) {
    ScopedGlobalLock guard;
    LibraryList* list = Globals::GetLibraries();
    list->UnloadLibrary(lib);
    return 0;
  }

  SetLinkerError("Invalid library handle %p", handle);
  return -1;
}

#ifdef __arm__
_Unwind_Ptr FindArmExIdx(_Unwind_Ptr pc, int* count) {
  {
    ScopedGlobalLock guard;
    LibraryList* list = Globals::GetLibraries();
    _Unwind_Ptr result = list->FindArmExIdx(pc, count);
    if (result)
      return result;
  }
  return ::dl_unwind_find_exidx(pc, count);
}
#else
int IteratePhdr(int (*cb)(dl_phdr_info*, size_t, void*), void* data) {
  {
    ScopedGlobalLock guard;
    LibraryList* list = Globals::GetLibraries();
    int res = list->IteratePhdr(cb, data);
    if (res)
      return res;
  }
  return ::dl_iterate_phdr(cb, data);
}
#endif

// Map known linker symbols to their wrappers.
void* GetWrappedSymbol(const char* name) {
  // Fast path: only 'dl*' functions and __aeabi_atexit on ARM
  if (name[0] != 'd' || name[1] != 'l') {
#ifdef __arm__
    if (name[0] == '_' && !strcmp("__aeabi_atexit", name))
      return reinterpret_cast<void*>(&__aeabi_atexit);
#endif
    return nullptr;
  }

  static const struct {
    const char* key;
    void* value;
  } mapping[] = {
      {"dlopen", reinterpret_cast<void*>(&OpenLibrary)},
      {"dlclose", reinterpret_cast<void*>(&CloseLibrary)},
      {"dlerror", reinterpret_cast<void*>(&FetchAndSwapError)},
      {"dlsym", reinterpret_cast<void*>(&ResolveSymbol)},
      {"dladdr", reinterpret_cast<void*>(&FindAddressInfo)},
#ifdef __arm__
      {"dl_unwind_find_exidx", reinterpret_cast<void*>(&FindArmExIdx)},
#else
      {"dl_iterate_phdr", reinterpret_cast<void*>(&IteratePhdr)},
#endif
  };

  constexpr size_t count = sizeof(mapping) / sizeof(mapping[0]);
  for (size_t i = 0; i < count; ++i) {
    if (!strcmp(mapping[i].key, name))
      return mapping[i].value;
  }
  return nullptr;
}

}  // namespace

// Public entry point to retrieve wrapped symbol addresses.
void* WrapLinkerSymbol(const char* name) {
  return GetWrappedSymbol(name);
}

