// Constants for naming conventions
#define GUARD_HANDLER "__guard_failure"
#define UNOPT_MARKER "__unopt_"

using namespace llvm;
using std::vector;
using std::map;
using std::pair;

namespace {

struct CheckPointPass : public FunctionPass {
  static char id;

  // Stores patchpoint IDs per function name (used to correlate optimized/unoptimized versions)
  static map<StringRef, vector<uint64_t>> patchpointIDs;

  CheckPointPass() : FunctionPass(id) {}

  virtual bool doInitialization(Module &M) override {
    auto &Ctx = M.getContext();
    Type *VoidTy = Type::getVoidTy(Ctx);
    Type *I64Ty = Type::getInt64Ty(Ctx);

    // Declare external guard handler function
    FunctionType *FTy = FunctionType::get(VoidTy, {I64Ty}, false);
    Function::Create(FTy, Function::ExternalLinkage, GUARD_HANDLER, &M);
    return true;
  }

  virtual bool runOnFunction(Function &F) override {
    Module *Mod = F.getParent();
    StringRef FuncName = F.getName();
    outs() << "Processing: " << FuncName << "\n";

    Type *I8PtrTy = PointerType::getUnqual(IntegerType::getInt8Ty(Mod->getContext()));
    vector<Instruction*> recordedCalls;

    Constant* GuardCallback = ConstantExpr::getBitCast(
        Mod->getFunction(GUARD_HANDLER), I8PtrTy);

    for (auto &BB : F) {
      for (auto It = BB.begin(); It != BB.end(); ++It) {
        Instruction *Inst = &*It;

        // Special handling for return instructions in functions named "...more_indirection"
        if (FuncName.endswith("more_indirection") && isa<ReturnInst>(Inst)) {
          IRBuilder<> Builder(&BB, Inst->getIterator());
          uint64_t ID = allocatePatchpointID(FuncName);
          vector<Value*> Args = {
            Builder.getInt64(ID),
            Builder.getInt32(13)  // shadow size
          };

          Function *IntrinsicDecl = nullptr;
          if (!FuncName.startswith(UNOPT_MARKER)) {
            // Optimized version: include callback info
            Args.insert(Args.end(), {
              GuardCallback,
              Builder.getInt32(1),
              Builder.getInt64(ID)
            });
            IntrinsicDecl = Intrinsic::getDeclaration(
                Mod, Intrinsic::experimental_patchpoint_void);
          } else {
            // Unoptimized version: no callback
            Value *NullPtr = Builder.CreateIntToPtr(Builder.getInt64(0), Builder.getInt8PtrTy());
            Args.insert(Args.end(), {
              NullPtr,
              Builder.getInt32(0)
            });
            IntrinsicDecl = Intrinsic::getDeclaration(
                Mod, Intrinsic::experimental_patchpoint_void);
          }
          CallInst *Call = Builder.CreateCall(IntrinsicDecl, Args);
          recordedCalls.push_back(Call);
          continue;
        }

        if (CallInst *CI = dyn_cast<CallInst>(Inst)) {
          if (CI->isInlineAsm() ||
              CI->getCalledFunction()->hasAvailableExternallyLinkage() ||
              CI->getCalledFunction()->isDeclaration()) {
            continue;  // Skip inline asm, declarations, and externally available functions
          }

          Function *TargetFun = CI->getCalledFunction();
          uint64_t PPID = allocatePatchpointID(FuncName);
          IRBuilder<> Builder(CI->getNextNode());

          vector<Value*> Args = {
            Builder.getInt64(PPID),
            Builder.getInt32(13)
          };

          if (FuncName.startswith(UNOPT_MARKER)) {
            // Replace original call with patchpoint in unoptimized version
            Function *Twin = getTwinFunction(Mod, TargetFun->getName());
            Constant *Callback = ConstantExpr::getBitCast(Twin, I8PtrTy);
            Args.insert(Args.end(), {
              Callback,
              Builder.getInt32(CI->getNumArgOperands())
            });

            // Copy original arguments
            for (unsigned i = 0; i < CI->getNumArgOperands(); ++i)
              Args.push_back(CI->getArgOperand(i));

            Function *IntrinsicDecl = nullptr;
            Type *RetTy = TargetFun->getReturnType();
            if (RetTy->isVoidTy()) {
              IntrinsicDecl = Intrinsic::getDeclaration(
                  Mod, Intrinsic::experimental_patchpoint_void);
            } else {
              IntrinsicDecl = Intrinsic::getDeclaration(
                  Mod, Intrinsic::experimental_patchpoint_i64);
            }

            CallInst *NewCall = CallInst::Create(IntrinsicDecl, Args);
            Value *Replacement = NewCall;

            if (!RetTy->isVoidTy()) {
              if (RetTy->isIntegerTy()) {
                Replacement = Builder.CreateTruncOrBitCast(NewCall, RetTy);
              } else {
                Type *FloatPtrTy = PointerType::getUnqual(RetTy);
                Value *Addr = Builder.CreateIntToPtr(NewCall, FloatPtrTy);
                Replacement = Builder.CreateLoad(RetTy, Addr);
              }
            }

            if (!CI->use_empty())
              CI->replaceAllUsesWith(Replacement);

            ReplaceInstWithInst(CI, NewCall);
            It = NewCall->getIterator();
            recordedCalls.push_back(NewCall);
          } else {
            // Insert stackmap after call in optimized version
            Function *StackmapDecl = Intrinsic::getDeclaration(
                Mod, Intrinsic::experimental_stackmap);
            CallInst *SMCall = Builder.CreateCall(StackmapDecl, Args);
            recordedCalls.push_back(SMCall);
          }
        }
      }
    }

    // Insert empty inline assembly blocks at recorded positions
    for (Instruction *I : recordedCalls) {
      IRBuilder<> Builder(I);
      FunctionType *EmptyTy = FunctionType::get(Builder.getVoidTy(), false);
      InlineAsm *EmptyASM = InlineAsm::get(
          EmptyTy,
          "",       // assembly string
          "",       // constraints
          true,     // hasSideEffects
          false     // isAlignStack
      );
      Builder.CreateCall(EmptyASM, {});
    }

    return true;
  }

  // Helper: Get twin function name (optimized ↔ unoptimized)
  static std::string getTwinName(StringRef Name) {
    if (Name.startswith(UNOPT_MARKER)) {
      return Name.substr(strlen(UNOPT_MARKER)).str();
    }
    return std::string(UNOPT_MARKER) + Name.str();
  }

  // Helper: Retrieve or create twin function in module
  static Function *getTwinFunction(Module *M, StringRef Name) {
    StringRef TwinName = getTwinName(Name);
    Function *Twin = M->getFunction(TwinName);
    if (!Twin) {
      // If not found, assume it will be created later — return original
      return M->getFunction(Name);
    }
    return Twin;
  }

  // Allocate next patchpoint ID for given function
  static uint64_t allocatePatchpointID(StringRef FuncName) {
    uint64_t NextID = 0;

    if (!patchpointIDs.empty()) {
      std::string TwinName = getTwinName(FuncName);
      auto It = patchpointIDs.find(TwinName);

      if (It == patchpointIDs.end()) {
        // No IDs yet for twin → increment from max existing ID
        auto MaxIt = std::max_element(patchpointIDs.begin(), patchpointIDs.end(),
            [](const pair<StringRef, vector<uint64_t>> &A,
               const pair<StringRef, vector<uint64_t>> &B) {
              return A.second.back() < B.second.back();
            });
        NextID = (*MaxIt).second.back() + 1;
      } else {
        // Use negation of corresponding ID in twin
        size_t Idx = patchpointIDs[FuncName].size();
        NextID = ~It->second[Idx];
      }
    }

    // Ensure first function starts at ID=1
    if (patchpointIDs.find(FuncName) == patchpointIDs.end() &&
        patchpointIDs.find(getTwinName(FuncName)) == patchpointIDs.end()) {
      ++NextID;
    }

    patchpointIDs[FuncName].push_back(NextID);
    return NextID;
  }
};

