#include "InverseExponentialElasticConstant.h"
#include "../../../Tools/Math/Point.h"
#include <cmath>

InverseExponentialElasticConstant::InverseExponentialElasticConstant(double k,
    double x0, int power) : ElasticConstantCalculator(k) {
    this->x0 = x0;
    this->power = power;
}

InverseExponentialElasticConstant::~InverseExponentialElasticConstant() {
}

double InverseExponentialElasticConstant::calculateK(Point& r_i, Point& r_j) {
    // Compute distance between points r_i and r_j
    double distance = r_i.distance(r_j);

    // Retrieve base stiffness parameter
    double base_k = initial_constant;

    // Normalize distance by characteristic length scale
    double normalized_distance = distance / x0;

    // Raise to the specified power
    double power_term = std::pow(normalized_distance, power);

    // Compute inverse exponential decay factor
    double denominator = 1.0 + power_term;

    // Final elastic constant value
    return base_k / denominator;
}

#include "sip_hash.h"
#include <cstring>  // memcpy
#include "vec.h"

namespace {

// Paper: https://www.131002.net/siphash/siphash.pdf
// SSE41 implementation: https://goo.gl/80GBSD
// The hash state is updated by injecting 8-byte packets;
// XORing together all state variables yields the final hash.
// 32 bytes. Parameters are hardwired to c=2, d=4 [rounds].

class SipHashState {
 public:
  explicit INLINE SipHashState(const uint64_t keys[2]) {
    const V2x64U key = LoadU(keys);
    // Initialize v0,v1 with key XORed against fixed constants
    const V2x64U init0 =
        key ^ V2x64U(0x646f72616e646f6dull, 0x736f6d6570736575ull);
    const V2x64U init1 =
        key ^ V2x64U(0x7465646279746573ull, 0x6c7967656e657261ull);

    // Interleave the two initial vectors into separate pairs
    v02 = UnpackLow(init0, init1);  // v0 and v2
    v13 = UnpackHigh(init0, init1); // v1 and v3
  }

  INLINE void Update(const V2x64U& packet) {
    // Inject packet into v3 (upper half of v13)
    v13 ^= V2x64U(_mm_slli_si128(packet, 8));
    PerformCompress<2>();
    // Inject packet into v0 (lower half of v02)
    v02 ^= packet;
  }

  INLINE uint64_t Finalize() {
    // Mix in padding bits to prevent key leakage on zero inputs
    v02 ^= V2x64U(0xFF, 0);
    PerformCompress<4>();

    // Combine v0 and v1 for final result
    const V2x64U combined = v02 ^ v13;
    const V2x64U upper_half(_mm_unpackhi_epi64(combined, combined));
    return _mm_cvtsi128_si64(combined ^ upper_half);
  }

 private:
  // Rotates both lanes of a vector by different amounts
  template <uint64_t rot_high, uint64_t rot_low>
  static INLINE V2x64U RotateVector(const V2x64U& input) {
    const V2x64U left_shift(rot_high, rot_low);
    const V2x64U right_shift(64 - rot_high, 64 - rot_low);
    const V2x64U shifted_left(_mm_sllv_epi64(input, left_shift));
    const V2x64U shifted_right(_mm_srlv_epi64(input, right_shift));
    return shifted_left | shifted_right;
  }

  // Swaps and rotates each 32-bit word within the vector
  static INLINE V2x64U RotateWords32(const V2x64U& input) {
    return V2x64U(_mm_shuffle_epi32(input, _MM_SHUFFLE(0, 1, 3, 2)));
  }

  // One ARX round: add, rotate, xor
  template <uint64_t rot_high, uint64_t rot_low>
  INLINE void HalfRound() {
    v02 += v13;
    v13 = RotateVector<rot_high, rot_low>(v13);
    v13 ^= v02;
  }

  // Perform multiple rounds of mixing
  template <size_t num_rounds>
  INLINE void PerformCompress() {
    for (size_t i = 0; i < num_rounds; ++i) {
      HalfRound<16, 13>();
      v02 = RotateWords32(v02);
      HalfRound<21, 17>();
      v02 = RotateWords32(v02);
    }
  }

  // State variables stored as interleaved pairs for SIMD efficiency
  V2x64U v02;  // Contains v0 (low) and v2 (high)
  V2x64U v13;  // Contains v1 (low) and v3 (high)
};

// Loads an 8-byte packet from memory into a vector with upper half zeroed
static INLINE V2x64U LoadPacket64(const uint8_t* data) {
  uint64_t temp;
  memcpy(&temp, data, sizeof(temp));
  return V2x64U(_mm_cvtsi64_si128(temp));
}

// Handles final partial block: copies remaining bytes, pads with size byte
static INLINE V2x64U LoadFinalPacket64(const uint8_t* data,
                                       const uint64_t total_size,
                                       const size_t current_offset) {
  ALIGNED(uint8_t, 16) buffer[8] = {0};
  const size_t remaining = total_size - current_offset;
  memcpy(buffer, data + current_offset, remaining);
  buffer[7] = static_cast<uint8_t>(total_size & 0xFF);
  return LoadPacket64(buffer);
}

}  // namespace

uint64_t SipHash(const uint64_t key[2], const uint8_t* data,
                 const uint64_t length) {
  SipHashState hasher(key);
  size_t pos = 0;

  // Process full 8-byte chunks
  for (; pos < (length & ~7); pos += 8) {
    const V2x64U chunk = LoadPacket64(data + pos);
    hasher.Update(chunk);
  }

  // Handle final partial or empty chunk
  const V2x64U final_chunk = LoadFinalPacket64(data, length, pos);
  hasher.Update(final_chunk);

  return hasher.Finalize();
}

uint64_t ReduceSipTreeHash(const uint64_t key[2], const uint64_t hashes[4]) {
  SipHashState hasher(key);
  for (int idx = 0; idx < 4; ++idx) {
    const V2x64U chunk(_mm_cvtsi64_si128(hashes[idx]));
    hasher.Update(chunk);
  }
  return hasher.Finalize();
}

#include "../helpers_event.h"

void do_item_description(std::ostream & s, const event_context & context, df::item *item)
{
    // Check if the item is an artifact first
    if (auto artifact_ref = Items::getGeneralRef(item, general_ref_type::IS_ARTIFACT))
    {
        if (auto artifact = artifact_ref->getArtifact())
        {
            event_link(s, context, artifact);
            return;
        }
    }

    std::string description;

    // Get prefix and main description parts
    item->getItemDescriptionPrefix(&description, 0);
    s << description;
    description.clear();

    item->getItemDescription(&description, 0);

    // Handle body component items with historical figures
    if (auto corpse = virtual_cast<df::item_body_component>(item))
    {
        if (auto hf = df::historical_figure::find(corpse->hist_figure_id))
        {
            std::string figure_name = Translation::capitalize(Translation::TranslateName(&hf->name, false), true);

            size_t search_pos = 0;
            size_t found_pos;

            while ((found_pos = description.find(figure_name, search_pos)) != std::string::npos)
            {
                s << description.substr(search_pos, found_pos - search_pos);
                link(s, hf);
                search_pos = found_pos + figure_name.length();
            }

            s << description.substr(search_pos);
            return;
        }
    }

    s << description;
}

