// Verify that an empty invocation log has all expected empty/default states
void validateEmptyLog(const InvocationLogParseResult &empty) {
  REQUIRE(empty.invocations.entries.empty());
  REQUIRE(empty.invocations.created_directories.empty());
  REQUIRE(empty.warning.empty());
  REQUIRE(!empty.needs_recompaction);
  REQUIRE(empty.parse_data.path_ids.empty());
  REQUIRE(empty.parse_data.fingerprint_ids.empty());
  REQUIRE(empty.parse_data.fingerprint_entry_count == 0);
  REQUIRE(empty.parse_data.path_entry_count == 0);
  REQUIRE(!empty.parse_data.buffer);
}

// Record a command execution in the log with specified dependencies
void recordCommand(
    InvocationLog &log,
    const Hash &step_hash,
    std::vector<std::string> output_paths,
    std::vector<std::string> input_paths,
    std::vector<uint32_t> skipped_deps,
    std::vector<Hash> extra_deps) {
  auto output_fps = log.fingerprintFiles(output_paths);
  auto input_fps = log.fingerprintFiles(input_paths);

  log.ranCommand(
      step_hash,
      std::move(output_paths),
      std::move(output_fps),
      std::move(input_paths),
      std::move(input_fps),
      std::move(skipped_deps),
      std::move(extra_deps));
}

// Execute test callback against both persistent and in-memory implementations
template <typename Func>
void testBothImplementations(Func &&func) {
  InMemoryFileSystem file_system;
  InMemoryInvocationLog mem_log(file_system, [] { return 0; });

  auto persistent_log = openPersistentInvocationLog(
      file_system,
      [] { return 0; },
      "invocation_log",
      InvocationLogParseResult::ParseData());

  func(*persistent_log, file_system);
  func(mem_log, file_system);

  auto persistent_result = parsePersistentInvocationLog(file_system, "invocation_log");
  auto memory_result = mem_log.invocations();

  REQUIRE(persistent_result.warning == "");
  REQUIRE(memory_result == persistent_result.invocations);
}

