// Run multiple write cycles to test persistence across restarts
template <typename Func>
void testMultipleCycles(Func &&func, InMemoryFileSystem file_system) {
  InMemoryInvocationLog mem_log(file_system, [] { return 0; });
  func(mem_log, file_system);

  for (size_t cycle = 0; cycle < 5; ++cycle) {
    auto result = parsePersistentInvocationLog(file_system, "invocation_log");
    REQUIRE(result.warning == "");

    auto persistent_log = openPersistentInvocationLog(
        file_system,
        [] { return 0; },
        "invocation_log",
        std::move(result.parse_data));

    func(*persistent_log, file_system);
  }

  auto final_result = parsePersistentInvocationLog(file_system, "invocation_log");
  auto memory_result = mem_log.invocations();

  REQUIRE(final_result.warning == "");
  REQUIRE(memory_result == final_result.invocations);
}

// Test that recompaction gets requested after sufficient writes
template <typename Func>
void testRecompactionTrigger(Func &&func) {
  InMemoryFileSystem file_system;

  size_t attempt_count = 0;
  for (;;) {
    auto persistent_log = openPersistentInvocationLog(
        file_system,
        [] { return 0; },
        "invocation_log",
        InvocationLogParseResult::ParseData());

    func(*persistent_log, file_system);

    auto result = parsePersistentInvocationLog(file_system, "invocation_log");

    if (result.needs_recompaction) {
      REQUIRE(attempt_count > 10);  // Should not request immediately
      break;
    }

    ++attempt_count;
    REQUIRE(attempt_count <= 10000);  // Should eventually trigger
  }
}

// Test recompaction functionality
template <typename Func>
void testRecompact(Func &&func, int iterations = 5) {
  InMemoryFileSystem file_system;
  InMemoryInvocationLog mem_log(file_system, [] { return 0; });

  func(mem_log, file_system);

  for (size_t i = 0; i < static_cast<size_t>(iterations); ++i) {
    auto result = parsePersistentInvocationLog(file_system, "invocation_log");
    REQUIRE(result.warning == "");

    auto persistent_log = openPersistentInvocationLog(
        file_system,
        [] { return 0; },
        "invocation_log",
        std::move(result.parse_data));

    func(*persistent_log, file_system);
  }

  auto parse_data = recompactPersistentInvocationLog(
      file_system,
      [] { return 0; },
      parsePersistentInvocationLog(file_system, "invocation_log").invocations,
      "invocation_log");

  auto result = parsePersistentInvocationLog(file_system, "invocation_log");
  REQUIRE(!result.needs_recompaction);

  auto memory_result = mem_log.invocations();
  REQUIRE(result.warning == "");
  REQUIRE(memory_result == result.invocations);

  // Validate parse_data integrity
  REQUIRE(parse_data.buffer);
  REQUIRE(parse_data.fingerprint_entry_count == result.invocations.fingerprints.size());
  REQUIRE(parse_data.path_entry_count == static_cast<int>(parse_data.path_ids.size()));

  for (const auto &fingerprint : memory_result.fingerprints) {
    std::string path(fingerprint.first);
    REQUIRE(parse_data.path_ids.count(path));
    REQUIRE(parse_data.fingerprint_ids.count(path));
  }

  // Check for duplicate IDs
  std::unordered_set<uint32_t> fingerprint_ids;
  std::unordered_set<uint32_t> path_ids;

  auto checkNoDuplicates = [](std::unordered_set<uint32_t> &set, uint32_t id) {
    bool inserted = set.insert(id).second;
    REQUIRE(inserted);
  };

  for (const auto &fingerprint : memory_result.fingerprints) {
    std::string path(fingerprint.first);
    auto path_it = parse_data.path_ids.find(path);
    if (path_it != parse_data.path_ids.end()) {
      checkNoDuplicates(path_ids, path_it->second);
    }
    parse_data.path_ids.erase(path);

    auto fp_it = parse_data.fingerprint_ids.find(path);
    if (fp_it != parse_data.fingerprint_ids.end()) {
      checkNoDuplicates(fingerprint_ids, fp_it->second.record_id);
    }
    parse_data.fingerprint_ids.erase(path);
  }

  REQUIRE(parse_data.path_ids.empty());
  REQUIRE(parse_data.fingerprint_ids.empty());

  for (const auto &dir : memory_result.created_directories) {
    REQUIRE(parse_data.path_ids.count(dir.second));
  }

  // Final verification of data consistency
  REQUIRE(memory_result.fingerprints == result.invocations.fingerprints);
  REQUIRE(memory_result.entries == result.invocations.entries);
  REQUIRE(memory_result.created_directories == result.invocations.created_directories);
}

// Test handling of truncated input files
template <typename Func>
void testTruncatedInput(Func &&func) {
  InMemoryFileSystem file_system;
  constexpr size_t signature_size = 16;

  // Create initial file
  REQUIRE(file_system.open("invocation_log", "w").second == IoError::success());
  size_t warning_count = 0;

  for (size_t truncate_point = 1;; ++truncate_point) {
    REQUIRE(file_system.unlink("invocation_log") == IoError::success());

    auto persistent_log = openPersistentInvocationLog(
        file_system,
        [] { return 0; },
        "invocation_log",
        InvocationLogParseResult::ParseData());

    func(*persistent_log, file_system);

    auto stat_result = file_system.stat("invocation_log");
    size_t new_size = stat_result.metadata.size - truncate_point;

    if (new_size <= signature_size) {
      break;
    }

    REQUIRE(file_system.truncate("invocation_log", new_size) == IoError::success());

    auto result = parsePersistentInvocationLog(file_system, "invocation_log");
    if (!result.warning.empty()) {
      ++warning_count;
    }

    // After parsing, file should be truncated properly
    auto after_parse = parsePersistentInvocationLog(file_system, "invocation_log");
    REQUIRE(after_parse.warning.empty());
  }

  REQUIRE(warning_count > 0);
}

// Comprehensive test runner for various scenarios
template <typename Func>
void runFullTestSuite(Func &&func) {
  testBothImplementations(func);
  testMemoryLeak(func);
  testRecompactionTrigger(func);
  testMultipleCycles(func, InMemoryFileSystem());
  testRecompact(func);
  testTruncatedInput(func);
}

// Helper to create a file with header for testing
void createFileWithHeader(
    FileSystem &fs,
    const std::string &filename,
    uint32_t version) {
  auto stream_result = fs.open(filename, "w");
  REQUIRE(stream_result.second == IoError::success());

  const std::string signature = "invocations:";
  REQUIRE(stream_result.first->write(
      reinterpret_cast<const uint8_t*>(signature.data()),
      signature.size(), 1) == IoError::success());

  REQUIRE(stream_result.first->write(
      reinterpret_cast<const uint8_t*>(&version),
      sizeof(version), 1) == IoError::success());
}

