          fps[0].hash.data[0] = iteration;

          log.ranCommand(
              zero_hash,
              std::move(outputs),
              std::move(fps),
              {},
              {},
              {},
              {});
        }
      });
    }

    SECTION("DifferentStepsSameFingerprints") {
      runFullTestSuite([&](InvocationLog &log, FileSystem &) {
        REQUIRE(file_system.writeFile("common1", "") == IoError::success());
        REQUIRE(file_system.writeFile("common2", "") == IoError::success());

        for (int i = 0; i < 2; ++i) {
          std::vector<std::string> outputs = { "unique1", "common1" };
          auto fps = log.fingerprintFiles(outputs);
          zero_hash.data.data()[0] = i;

          log.ranCommand(
              zero_hash,
              std::move(outputs),
              std::move(fps),
              {},
              {},
              {},
              {});
        }
      });
    }

    SECTION("ManyFingerprints") {
      testRecompact([&](InvocationLog &log, FileSystem &) {
        REQUIRE(file_system.writeFile("file1", "data1") == IoError::success());
        REQUIRE(file_system.writeFile("file2", "data2") == IoError::success());

        for (int i = 0; i < 3000; ++i) {
          std::vector<std::string> outputs = { "result1", "file1", "file2" };
          auto fps = log.fingerprintFiles(outputs);

          for (auto &fp : fps) {
            *reinterpret_cast<int*>(fp.hash.data.data()) = i;
          }
          *reinterpret_cast<int*>(zero_hash.data.data()) = i;

          log.ranCommand(
              zero_hash,
              std::move(outputs),
              std::move(fps),
              {},
              {},
              {},
              {});
        }
      }, /*run_times=*/1);
    }

    SECTION("IgnoredDependency") {
      runFullTestSuite([&](InvocationLog &log, FileSystem &) {
        recordCommand(log, zero_hash, {}, {}, { 1337 }, {});
      });
    }

    SECTION("AdditionalDependency") {
      runFullTestSuite([&](InvocationLog &log, FileSystem &) {
        recordCommand(log, zero_hash, {}, {}, {}, { one_hash });
      });
    }

    SECTION("OverwrittenCommand") {
      runFullTestSuite([&](InvocationLog &log, FileSystem &) {
        recordCommand(log, zero_hash, {}, {}, {}, {});
        recordCommand(log, zero_hash, { "new_output" }, {}, {}, {});
      });
    }

    SECTION("CleanedMissingCommand") {
      runFullTestSuite([&](InvocationLog &log, FileSystem &) {
