#include <iostream>
#include <nlohmann/json.hpp>
using json = nlohmann::json;

int main() {
    // Input string containing three parallel arrays: tickers, IDs, and descriptions
    std::string str =
        R"([["Si-9.15","RTS-9.15","GAZP-9.15"],[100024, 100027, 100050],["Futures contract for USD/RUB", "Futures contract for index RTS", "Futures contract for Gazprom shares"]])";

    auto parsed_data = json::parse(str);

    // Output the original JSON structure with indentation
    std::cout << parsed_data.dump(3) << std::endl;

    // Validate input format
    if (!parsed_data.is_array()) {
        std::cerr << "Error: Expected a JSON array at top level" << std::endl;
        return 1;
    }

    if (parsed_data.size() != 3) {
        std::cerr << "Error: Expected exactly 3 sub-arrays" << std::endl;
        return 1;
    }

    // Ensure all sub-arrays have equal length
    size_t count = parsed_data[0].size();
    if (parsed_data[1].size() != count || parsed_data[2].size() != count) {
        std::cerr << "Error: All sub-arrays must have the same number of elements" << std::endl;
        return 1;
    }

    // Build result array by combining corresponding elements from each sub-array
    json output_array = json::array();
    for (size_t idx = 0; idx < count; ++idx) {
        json item;
        item["ticker"] = parsed_data[0][idx];
        item["id"] = parsed_data[1][idx];
        item["description"] = parsed_data[2][idx];
        output_array.push_back(item);
    }

    // Output the transformed JSON with minimal indentation
    std::cout << output_array.dump(1) << std::endl;

    return 0;
}

