// Alternative implementation of TestSplashScreen with renamed members and slightly different structure
struct CustomSplashScreen : implements<CustomSplashScreen, ISplashScreen>
{
    operator SplashScreen() const noexcept
    {
        SplashScreen result = nullptr;
        copy_from_abi(result, to_abi<ISplashScreen>(this));
        return result;
    }

    event<TypedEventHandler<SplashScreen, IInspectable>> m_onDismissed;

    Rect GetImageRect()
    {
        m_onDismissed(*this, nullptr);
        return {};
    }

    event_token AddDismissedHandler(const TypedEventHandler<SplashScreen, IInspectable>& handler)
    {
        return m_onDismissed.add(handler);
    }

    void RemoveDismissedHandler(event_token token)
    {
        m_onDismissed.remove(token);
    }
};

// Refactored clipboard mock with renamed methods and internal state
struct CustomClipboardManager : implements<CustomClipboardManager, IClipboardStatics>
{
    event<EventHandler<IInspectable>> m_onContentChanged;

    DataPackageView RetrieveContent() const { return nullptr; }
    void Synchronize() const {}
    void EraseContent() const {}

    void UpdateContent(const DataPackage& pkg)
    {
        m_onContentChanged(*this, nullptr);
    }

    event_token SubscribeToChanges(const EventHandler<IInspectable>& handler)
    {
        return m_onContentChanged.add(handler);
    }

    void UnsubscribeFromChanges(event_token token)
    {
        m_onContentChanged.remove(token);
    }
};

// Wrapper for static clipboard access using alternative naming
struct ClipboardProxy
{
    static IClipboardStatics AcquireStatics()
    {
        static IClipboardStatics s_instance = make<CustomClipboardManager>();
        return s_instance;
    }

    static void Update(const DataPackage& content)
    {
        AcquireStatics().UpdateContent(content);
    }

    static event_token OnContentChange(const Windows::Foundation::EventHandler<Windows::Foundation::IInspectable>& handler)
    {
        return AcquireStatics().SubscribeToChanges(handler);
    }

    using ChangeRevoker = impl::factory_event_revoker<
        IClipboardStatics,
        &impl::abi_t<Windows::ApplicationModel::DataTransfer::IClipboardStatics>::remove_ContentChanged>;

    static ChangeRevoker AutoSubscribe(auto_revoke_t,
                                       const Windows::Foundation::EventHandler<Windows::Foundation::IInspectable>& handler)
    {
        auto factory = AcquireStatics();
        return{ factory, factory.SubscribeToChanges(handler) };
    }

    static void Revoke(event_token token)
    {
        AcquireStatics().UnsubscribeFromChanges(token);
    }
};

// Test instance event revokers via splash screen
TEST_CASE("instance event consumption")
{
    ISplashScreen splash = make<CustomSplashScreen>();
    unsigned long counter = 0;

    // Use alias and auto_revoke as before
    SplashScreen::Dismissed_revoker revoker =
        splash.AddDismissedHandler(auto_revoke,
            [&](auto&&...) { ++counter; });

    splash.GetImageRect(); // trigger event
    REQUIRE(counter == 1);

    revoker.revoke();      // explicit revoke
    revoker.revoke();      // double revoke should be safe
    splash.GetImageRect(); // no effect now
    REQUIRE(counter == 1);

    {
        SplashScreen::Dismissed_revoker scopedRevoker =
            splash.AddDismissedHandler(auto_revoke,
                [&](auto&&...) { ++counter; });

        splash.GetImageRect(); // triggers again
        REQUIRE(counter == 2);

        // scope exit auto-revokes
    }

    splash.GetImageRect(); // no change
    REQUIRE(counter == 2);
}

// Test factory-based event revokers via clipboard proxy
TEST_CASE("factory event revocation")
{
    unsigned long callbackCount = 0;

    ClipboardProxy::ChangeRevoker factoryRevoker =
        ClipboardProxy::AutoSubscribe(auto_revoke,
            [&](auto&&...) { ++callbackCount; });

    ClipboardProxy::Update(nullptr); // fire event
    REQUIRE(callbackCount == 1);

    factoryRevoker.revoke();
    factoryRevoker.revoke(); // harmless duplicate
    ClipboardProxy::Update(nullptr);
    REQUIRE(callbackCount == 1);

    {
        ClipboardProxy::ChangeRevoker tempRevoker =
            ClipboardProxy::AutoSubscribe(auto_revoke,
                [&](auto&&...) { ++callbackCount; });

        ClipboardProxy::Update(nullptr);
        REQUIRE(callbackCount == 2);

        // destructor revokes automatically
    }

    ClipboardProxy::Update(nullptr);
    REQUIRE(callbackCount == 2);
}

