using ScreenUnit = int;

ScreenUnit getBaseCharWidth()                { return 9; /* TODO: Use GetDialogBaseUnits */ }
ScreenUnit getQuarterCharUnit()              { return getBaseCharWidth() / 4; }
ScreenUnit getBorderThickness()              { return getQuarterCharUnit() * 2; }
ScreenUnit computeTextPixelLength(size_t len){ return getBaseCharWidth() * static_cast<ScreenUnit>(len); }
ScreenUnit requiredTotalWidth(size_t maxLen)
{
    return 2 * getBorderThickness() + computeTextPixelLength(maxLen);
}

struct LongerStringFirst
{
    bool operator()(const std::string& left, const std::string& right) const
    {
        return left.length() > right.length();
    }
};

