ListBoxDialog::ListBoxDialog(
    InstanceHandle hInstance,
    Handle parentWindow,
    const std::string& title,
    const std::string& copyDelimiter)
    : Dialog(hInstance, parentWindow, ResourceId(ID_LIST_BOX_DIALOG), title),
      m_lastSelectedIndex(-1),
      itemDelimiter(copyDelimiter)
{
    registerHandler(MsgMatchers::ButtonClick(IDOK),     [this]() { onOkClicked(); });
    registerHandler(MsgMatchers::ButtonClick(IDCANCEL), [this]() { onCancelClicked(); });
    registerHandler(MsgMatchers::MsgCodeAndValue(ID_LIST_BOX, LBN_SELCHANGE), [this]() { onSelectChanged(); });
    registerHandler(MsgMatchers::MsgCodeAndValue(ID_LIST_BOX, LBN_DBLCLK),    [this]() { onDoubleClicked(); });
}

void ListBoxDialog::initialize()
{
    populateListBox();
    adjustHorizontalScroll();
    setKeyboardFocusToListBox();
}

Handle ListBoxDialog::getListBoxControl() const
{
    return getItem(ResourceId(ID_LIST_BOX));
}

void ListBoxDialog::setKeyboardFocusToListBox()
{
    SetFocus(getListBoxControl());
}

void ListBoxDialog::adjustHorizontalScroll()
{
    if (m_entries.empty()) return;

    auto longestIt = std::max_element(m_entries.begin(), m_entries.end(), LongerStringFirst());
    size_t maxLength = longestIt->length();
    SendMessage(getListBoxControl(), LB_SETHORIZONTALEXTENT, requiredTotalWidth(maxLength), 0);
}

void ListBoxDialog::populateListBox()
{
    StringInserter inserter(getListBoxControl());
    for (const auto& entry : m_entries)
        inserter.add(entry);
}

void ListBoxDialog::onOkClicked()
{
    close(RESULT_OK);
}

void ListBoxDialog::onCancelClicked()
{
    m_lastSelectedIndex = -1;
    close(RESULT_CANCEL);
}

void ListBoxDialog::onSelectChanged()
{
    m_lastSelectedIndex = static_cast<int>(SendMessage(getListBoxControl(), LB_GETCURSEL, 0, 0));
}

void ListBoxDialog::onDoubleClicked()
{
    onSelectChanged();
    close(RESULT_OK);
}

int ListBoxDialog::getSelectedIndex() const
{
    return m_lastSelectedIndex;
}

void ListBoxDialog::setEntries(const std::vector<std::string>& newEntries)
{
    m_entries = newEntries;
}

bool ListBoxDialog::showContextMenu(int xPos, int yPos)
{
    ContextMenu popup(m_self);
    popup.add({ L"Copy table",           [this]() { copyAllData(); } });
    popup.add({ L"Copy selected row",    [this]() { copySingleSelection(); } });
    popup.show(xPos, yPos);
    return true;
}

void ListBoxDialog::copyAllData() const
{
    std::string combined;
    for (const auto& line : m_entries)
        combined += line + itemDelimiter;
    Clipboard::set(Clipboard::String(combined));
}

void ListBoxDialog::copySingleSelection() const
{
    int index = static_cast<int>(SendMessage(getListBoxControl(), LB_GETCURSEL, 0, 0));
    if (index >= 0 && static_cast<size_t>(index) < m_entries.size())
        Clipboard::set(Clipboard::String(m_entries[index] + itemDelimiter));
}

