// Convert a long integer to a Pascal-style string (Str255), storing length in first byte
void NumToString(long theNum, Str255 theString)
{
    int written = snprintf(reinterpret_cast<char*>(theString + 1), 254, "%ld", theNum);
    theString[0] = (written <= 0) ? 0 : 
                   (written > 255) ? static_cast<unsigned char>(255) : 
                   static_cast<unsigned char>(written);
}

// Convert a long integer to a C-style null-terminated string, return number of characters written
int NumToStringC(long theNum, Str255 theString)
{
    return snprintf(reinterpret_cast<char*>(theString), 256, "%ld", theNum);
}

// Retrieve a string from a STR# resource by index (1-based indexing)
void GetIndStringC(Str255 theStringC, short strListID, short index)
{
    // Initialize output string as empty
    theStringC[0] = '\0';

    // Load the STR# resource
    Handle strListHandle = GetResource('STR#', strListID);
    if (!strListHandle)
        return;

    // Create input stream from resource data
    memstream substream(*strListHandle, GetHandleSize(strListHandle));
    Pomme::BigEndianIStream f(substream);

    // Read total number of strings in the list
    int16_t nStrings = f.Read<int16_t>();

    // Validate index (index starts at 1)
    if (index > nStrings) {
        ReleaseResource(strListHandle);
        return;
    }

    // Skip over preceding strings to reach desired index
    uint8_t pstrlen = 0;
    for (int i = 1; i < index; ++i) {
        pstrlen = f.Read<uint8_t>();
        f.Skip(pstrlen);
    }

    // Read the target string's length and content
    pstrlen = f.Read<uint8_t>();
    f.Read(theStringC, pstrlen);
    theStringC[pstrlen] = '\0';

    // Ensure consistency with expected structure
    static_assert(sizeof(Str255) == 256, "Str255 must be exactly 256 bytes");

    ReleaseResource(strListHandle);
}

#include <iostream>
#include <vector>
#include <string>

// Simulated IconImage class for demonstration purposes
class IconImage {
public:
    std::string source;
    IconImage(void*, const std::string& src) : source(src) {}
};

// Simulated IconImageCache class
class IconImageCache {
private:
    std::vector<std::pair<std::string, IconImage*>> cache;
    size_t maxSize;

public:
    IconImageCache(size_t initialSize = 4) : maxSize(initialSize) {}

    void set(const std::string& key, void*, void*, IconImage* img) {
        // Remove existing entry if present
        for (auto it = cache.begin(); it != cache.end(); ++it) {
            if (it->first == key) {
                delete it->second;
                cache.erase(it);
                break;
            }
        }
        cache.push_back({key, img});
        expire();
    }

    IconImage* get(const std::string& key, void*, void*) {
        for (const auto& item : cache) {
            if (item.first == key) {
                return item.second;
            }
        }
        return nullptr;
    }

    size_t cacheSize() const {
        return cache.size();
    }

    void expire() {
        while (cache.size() > maxSize) {
            delete cache.front().second;
            cache.erase(cache.begin());
        }
    }

    void clear() {
        for (const auto& item : cache) {
            delete item.second;
        }
        cache.clear();
    }

    void setSize(size_t newSize) {
        maxSize = newSize;
        expire();
    }
};

// Global cache instance
IconImageCache iconImageCache;

int main() {
    // Test case 1: Expiration behavior
    std::cout << "Test Case 1: Expiration behavior" << std::endl;

    // Set max cache size to 4
    iconImageCache.setSize(4);

    // Add 4 items
    for (int i = 0; i < 4; ++i) {
        std::string src = std::to_string(i);
        IconImage* img = new IconImage(nullptr, src);
        iconImageCache.set(src, nullptr, nullptr, img);
    }

    std::cout << "After adding 4 items, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Expire - should not remove anything yet
    iconImageCache.expire();
    std::cout << "After first expire, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Add one more item (should trigger expiration)
    std::string src = "4";
    IconImage* img = new IconImage(nullptr, src);
    iconImageCache.set(src, nullptr, nullptr, img);
    std::cout << "After adding 5th item, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Expire again - should remove oldest items
    iconImageCache.expire();
    std::cout << "After second expire, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Add back '0' and '4' with listeners (simulated by keeping references)
    src = "0";
    img = new IconImage(nullptr, src);
    iconImageCache.set(src, nullptr, nullptr, img);
    std::cout << "After adding '0', cache size: " << iconImageCache.cacheSize() << std::endl;

    src = "4";
    img = new IconImage(nullptr, src);
    iconImageCache.set(src, nullptr, nullptr, img);
    std::cout << "After adding '4' again, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Final expiration check
    iconImageCache.expire();
    std::cout << "After final expire, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Verify '0' and '4' are still in cache
    IconImage* found0 = iconImageCache.get("0", nullptr, nullptr);
    IconImage* found4 = iconImageCache.get("4", nullptr, nullptr);
    std::cout << "'0' in cache: " << (found0 ? "yes" : "no") << std::endl;
    std::cout << "'4' in cache: " << (found4 ? "yes" : "no") << std::endl;

    // Test case 2: Setting size and expiring
    std::cout << "\nTest Case 2: Setting size and expiring" << std::endl;

    // Clear and add 3 items
    iconImageCache.clear();
    for (int i = 0; i < 3; ++i) {
        std::string src = std::to_string(i);
        IconImage* img = new IconImage(nullptr, src);
        iconImageCache.set(src, nullptr, nullptr, img);
    }

    std::cout << "After adding 3 items, cache size: " << iconImageCache.cacheSize() << std::endl;

    // Set size to 2
    iconImageCache.setSize(2);
    std::cout << "After setting size to 2, cache size: " << iconImageCache.cacheSize() << std::endl;

    return 0;
}

