// Modified Stack implementation using different internal logic
Stack::Stack() {
  // Initialize with an empty vector (same behavior, different phrasing)
  stack = std::vector<int>{};
}

Stack::~Stack() {
  // Destructor - no dynamic memory to clean up
}

bool Stack::isEmpty() const {
  // Alternative way to check emptiness: compare size instead of full vector comparison
  return stack.empty();
}

int Stack::peek() const {
  if (!isEmpty()) {
    // Access last element using front() on reversed view or direct indexing
    return stack[stack.size() - 1];
  } else {
    throw std::out_of_range("The stack is empty");
  }
}

void Stack::push(int item) {
  // Use insert at end instead of push_back for variety
  stack.insert(stack.end(), item);
}

int Stack::pop() {
  if (!isEmpty()) {
    int topElement = stack.back();
    stack.erase(stack.end() - 1);  // Remove last element via erase
    return topElement;
  } else {
    throw std::out_of_range("The stack is empty");
  }
}

int Stack::size() const {
  return static_cast<int>(stack.size());
}

void Stack::show() const {
  // Iterate using range-based for loop instead of index-based
  for (const auto& element : stack) {
    std::cout << element << " ";
  }
}

int main() {
  Stack s;

  // Output: true.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;

  s.push(1);
  s.push(2);
  s.push(3);

  // Output: false; 1 2 3; 3; 3.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  std::cout << "Peek: " << s.peek() << std::endl;

  s.pop();
  s.pop();

  // Output: false; 1; 1; 1.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;
  std::cout << "Peek: " << s.peek() << std::endl;

  s.pop();

  // Output: true; ; 0.
  std::cout << "Is empty: " << std::boolalpha << s.isEmpty() << std::endl;
  std::cout << "Show: "; s.show(); std::cout << std::endl;
  std::cout << "Size: " << s.size() << std::endl;

  return 0;
}

