void WidgetInertialSensor::transmitSensorData(char const* topic, int xVal, int yVal, int zVal)
{
    aJsonObject* payloadRoot = aJson.createObject();
    if (!payloadRoot) {
        return;
    }

    aJson.addNumberToObject(payloadRoot, "x", xVal);
    aJson.addNumberToObject(payloadRoot, "y", yVal);
    aJson.addNumberToObject(payloadRoot, "z", zVal);

    char* serialized = aJson.print(payloadRoot);
    if (serialized != nullptr) {
        IntoRobot.publish(topic, serialized);
        free(serialized);
    }

    aJson.deleteItem(payloadRoot);
}

