// Renamed visitor class with equivalent behavior
struct PropCopier : public IPropertiesVisitor
{
    Properties &target;
    PropCopier(Properties &p) : target(p) {}
    virtual void visitProperty(const Property::Value &key,
                               const Property &values) override
    {
        for (size_t idx = 0; idx < values.size(); ++idx) {
            target.add(key, values.getAt(idx));
        }
    }
};

// Helper to construct properties from initializer lists — rewritten using nested loops
Properties build_props(std::initializer_list<std::pair<const char *, std::initializer_list<const char *> > > data) {
    Properties result;
    for (const auto &item: data) {
        vespalib::string key_name = item.first;
        for (const auto &val: item.second) {
            result.add(key_name, val);
        }
    }
    return result;
}

TEST("require that namespace visitation works") {
    Properties source = build_props({
        {"foo",   {"outside"}},
        {"foo.a", {"a_value"}},
        {"foo.b", {"b_value"}},
        {"foo.",  {"outside"}}
    });
    Properties destination;
    PropCopier copier(destination);
    source.visitNamespace("foo", copier);
    EXPECT_EQUAL(2u, destination.numKeys());
    EXPECT_EQUAL(destination.lookup("a").get(), Property::Value("a_value"));
    EXPECT_EQUAL(destination.lookup("b").get(), Property::Value("b_value"));
}

