#include "ShaderImporter.h"
#include "EngineCore/Renderer/Material/Shader.h"
#include "RenderAPI/Interface/Shader.h"

namespace cube
{
    Resource* ShaderImporter::Import(SPtr<platform::File>& file, const FrameJsonValue& info)
    {
        // Retrieve file size and allocate buffer for raw shader source
        uint64_t fileSize = file->GetFileSize();
        char* sourceBuffer = static_cast<char*>(malloc(fileSize + 1));
        uint64_t bytesRead = 0;

        // Read the entire file content into the buffer
        file->Read(sourceBuffer, fileSize, bytesRead);
        sourceBuffer[fileSize] = '\0';  // Null-terminate the string

        // Extract compilation parameters from metadata
        ShaderCompileDesc compileInfo = ExtractCompilationParameters(info);

        // Prepare initialization structure for the render-side shader object
        render::ShaderAttribute initParams;
        initParams.language = compileInfo.language;
        initParams.type     = compileInfo.type;
        initParams.entryPoint = compileInfo.entryPoint.c_str();
        initParams.code     = sourceBuffer;

        // Instantiate and load the shader
        Shader* loadedShader = new Shader();
        loadedShader->_LoadShader(mDevice, initParams);

        // Clean up temporary resources
        free(sourceBuffer);
        return loadedShader;
    }

    ShaderCompileDesc ShaderImporter::ExtractCompilationParameters(const FrameJsonValue& info)
    {
        using namespace render;
        ShaderCompileDesc desc;

        // Extract string values from JSON metadata
        U8String languageName = info["language"].GetString();
        U8String shaderType   = info["type"].GetString();
        U8String entryPoint   = info["entry_point"].GetString();

        // Map language identifiers to internal enum values
        if (languageName == "glsl") {
            desc.language = ShaderLanguage::GLSL;
        } else if (languageName == "hsls") {
            desc.language = ShaderLanguage::HLSL;
        } else if (languageName == "spir-v") {
            desc.language = ShaderLanguage::SPIRV;
        }

        // Map shader type identifiers to internal enum values
        if (shaderType == "vertex") {
            desc.type = ShaderType::Vertex;
        } else if (shaderType == "fragment" || shaderType == "pixel") {
            desc.type = ShaderType::Pixel;
        } else if (shaderType == "compute") {
            desc.type = ShaderType::Compute;
        }

        // Set entry point name
        desc.entryPoint = entryPoint;
        return desc;
    }
} // namespace cube

