  prctl(PR_SET_NAME, reinterpret_cast<unsigned long>(thread_name), 0UL, 0UL, 0UL);
#  elif defined(CAF_NET_BSD)
  pthread_setname_np(pthread_self(), thread_name, nullptr);
#  elif defined(CAF_BSD)
  pthread_set_name_np(pthread_self(), thread_name);
#  endif
#endif // CAF_WINDOWS
}

