#include "wav.h"
#include "win32_file_io.h"
#include <stdlib.h>
#include <string.h>
#ifdef DEBUG
#include <assert.h>
#else
#define assert(x)
#endif

// Helper macro to suppress unused variable warnings
#define SKIP_UNUSED(x) (void)(x)

// Four-character codes for WAV file parsing
u32 const kWavFourCC_RIFF = 'FFIR';
u32 const kWavFourCC_DATA = 'atad';
u32 const kWavFourCC_FMT  = ' tmf';
u32 const kWavFourCC_WAVE = 'EVAW';
u32 const kWavFourCC_XWMA = 'AMWX';

// Internal state structure for reading WAV data sequentially
struct wav_reader_context
{
    u8 *BufferBegin = nullptr;
    size_t CurrentOffset = 0;
    size_t BufferLength = 0;
    bool HasError = false;
};

// Check if we've reached or exceeded the buffer boundary
bool IsPastEnd(wav_reader_context *Ctx, u32 BytesNeeded = 0)
{
    bool PastBoundary = false;

    if (!Ctx->BufferBegin || ((Ctx->CurrentOffset + BytesNeeded) > Ctx->BufferLength))
    {
        Ctx->HasError = true;
        PastBoundary = true;
    }

    return PastBoundary;
}

// Verify that the context is still valid for reading
bool IsValidContext(wav_reader_context *Ctx)
{
    bool Valid = false;

    if (!Ctx->HasError && !IsPastEnd(Ctx))
    {
        Valid = true;
    }

    return Valid;
}

// Move forward in the buffer by specified number of bytes
void SkipBytes(wav_reader_context *Ctx, u32 Count)
{
    if (!IsPastEnd(Ctx, Count))
    {
        Ctx->CurrentOffset += Count;
    }
}

// Get current read position pointer
u8 *GetCurrentPosition(wav_reader_context *Ctx)
{
    u8 *Pos = nullptr;

    if (IsValidContext(Ctx))
    {
        Pos = Ctx->BufferBegin + Ctx->CurrentOffset;
    }

    return Pos;
}

// Read a 32-bit unsigned integer without advancing the cursor
u32 Peek_u32(wav_reader_context *Ctx)
{
    u32 Value = 0;

    if (IsValidContext(Ctx))
    {
        Value = *reinterpret_cast<u32*>(GetCurrentPosition(Ctx));
    }

    return Value;
}

// Read and consume a 32-bit unsigned integer
u32 Read_u32(wav_reader_context *Ctx)
{
    u32 Value = 0;

    if (IsValidContext(Ctx))
    {
        Value = *reinterpret_cast<u32*>(GetCurrentPosition(Ctx));
        SkipBytes(Ctx, 4);
    }

    return Value;
}

// Read and consume a 16-bit unsigned integer
u16 Read_u16(wav_reader_context *Ctx)
{
    u16 Value = 0;

    if (IsValidContext(Ctx))
    {
        Value = *reinterpret_cast<u16*>(GetCurrentPosition(Ctx));
        SkipBytes(Ctx, 2);
    }

    return Value;
}

// Parse RIFF header chunk
bool ParseRIFFHeader(wav_reader_context *Ctx, wav *Result)
{
    bool Success = false;

    if (IsValidContext(Ctx))
    {
        u32 Signature = Peek_u32(Ctx);
        if (Signature == kWavFourCC_RIFF)
        {
            SkipBytes(Ctx, 4);

            u32 TotalSize = Read_u32(Ctx);
            SKIP_UNUSED(TotalSize); // Not used further

            u32 WaveType = Read_u32(Ctx);
            if (WaveType == kWavFourCC_WAVE)
            {
                Result->Type = WavType_Wave;
                Success = true;
            }
#if 0
            else if (WaveType == kWavFourCC_XWMA)
            {
                Result->Type = WavType_XWMA;
                Success = true;
            }
#endif
        }
    }

    Ctx->HasError = !Success;
    return Success;
}

// Parse format ('fmt ') chunk
bool ParseFormatChunk(wav_reader_context *Ctx, wav *Result)
{
    bool Success = false;

    if (IsValidContext(Ctx))
    {
        u32 ChunkID = Peek_u32(Ctx);
        if (ChunkID == kWavFourCC_FMT)
        {
            SkipBytes(Ctx, 4);

            u32 ChunkSize = Read_u32(Ctx);
            SKIP_UNUSED(ChunkSize);

            wav_format *Fmt = &Result->Format;
            Fmt->Compression = Read_u16(Ctx);
            Fmt->NumberOfChannels = Read_u16(Ctx);
            Fmt->SampleRate = Read_u32(Ctx);
            Fmt->AverageBytesPerSecond = Read_u32(Ctx);
            Fmt->BlockAlign = Read_u16(Ctx);
            Fmt->SignificantBitsPerSample = Read_u16(Ctx);

            if (ChunkSize > 16)
            {
                Fmt->ExtraFormatBytes = Read_u16(Ctx);
                SkipBytes(Ctx, Fmt->ExtraFormatBytes);
            }

            // Only uncompressed PCM supported currently
            if (Fmt->Compression != 1)
            {
                assert(false);
            }

            // Ensure bit depth is byte-aligned
            if (Fmt->SignificantBitsPerSample % 8 != 0)
            {
                assert(false);
            }

            Success = true;
        }
    }

    Ctx->HasError = !Success;
    return Success;
}

// Parse data ('data') chunk
bool ParseDataChunk(wav_reader_context *Ctx, wav *Result)
{
    bool Success = false;

    if (IsValidContext(Ctx))
    {
        u32 ChunkID = Peek_u32(Ctx);
        if (ChunkID == kWavFourCC_DATA)
        {
            SkipBytes(Ctx, 4);

            Result->DataSize = Read_u32(Ctx);
            Result->Data = static_cast<u8*>(malloc(Result->DataSize));
            assert(Result->Data != nullptr);

            memcpy(Result->Data, GetCurrentPosition(Ctx), Result->DataSize);

            Success = true;
        }
    }

    return Success;
}

// Main entry point for parsing WAV data from memory buffer
bool LoadWAV(u8 *InputBuffer, size_t InputSize, wav *Output)
{
    bool Success = false;

    if (Output && InputBuffer && InputSize > 0)
    {
        wav_reader_context Context;
        Context.BufferBegin = InputBuffer;
        Context.CurrentOffset = 0;
        Context.BufferLength = InputSize;

        Success = ParseRIFFHeader(&Context, Output);
        assert(Success);

        Success = ParseFormatChunk(&Context, Output);
        assert(Success);

        Success = ParseDataChunk(&Context, Output);
        assert(Success);
    }

    return Success;
}

// Clean up allocated resources in wav structure
void DestroyWAV(wav *File)
{
    if (File)
    {
        if (File->Data)
        {
            free(File->Data);
            memset(File, 0, sizeof(wav));
        }
    }
}

#include <gtest/gtest.h>
