class SingleStateTest : public StateMachine, public ::testing::Test
{
public:
    SingleStateTest()
        : guard1(false)
        , guard2(false)
        , guard3(false)
    {
        InitializeStateMachine();
    }

    std::string GetLog() const { return recordedEvents; }

    std::string GetCurrentStateName() const
    {
        return StateNames.at(GetCurrentState());
    }

protected:
    bool guard1;
    bool guard2;
    bool guard3;

private:
    void AppendToLog(const std::string& event)
    {
        if (!recordedEvents.empty()) { recordedEvents += ':'; }
        recordedEvents += event;
    }

    void OnInitialAction() override { AppendToLog("Initial"); }
    void HandleEventA1() override { AppendToLog("A1"); }
    void HandleEventA2() override { AppendToLog("A2"); }
    void HandleEventA3() override { AppendToLog("A3"); }
    void HandleEventA4() override { AppendToLog("A4"); }
    void HandleEventA5() override { AppendToLog("A5"); }
    void HandleEventA6() override { AppendToLog("A6"); }
    void OnEntry() override { AppendToLog("Entry"); }
    void OnExit() override { AppendToLog("Exit"); }
    bool CheckGuard1() const override { return guard1; }
    bool CheckGuard2() const override { return guard2; }

    std::string recordedEvents;
};

TEST_F(SingleStateTest, VerifyInitialState)
{
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, InitialAndEntryActionsRunAtStart)
{
    EXPECT_EQ("Initial:Entry", GetLog());
}

TEST_F(SingleStateTest, InternalEventTriggersActionOnce)
{
    TriggerE1();
    EXPECT_EQ("Initial:Entry:A1", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, SameEventProcessedMultipleTimes)
{
    TriggerE1();
    TriggerE1();
    EXPECT_EQ("Initial:Entry:A1:A1", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, SelfTransitionWithEntryExit)
{
    TriggerE2();
    EXPECT_EQ("Initial:Entry:Exit:A2:Entry", GetLog());
    EXPECT_EQ("S", GetCurrentStateName());
}

TEST_F(SingleStateTest, TransitionToTerminationState)
{
    TriggerE3();
    EXPECT_EQ("Initial:Entry:Exit:A3", GetLog());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", GetCurrentStateName());
}

TEST_F(SingleStateTest, NoFurtherActionsAfterTermination)
{
    TriggerE3();
    EXPECT_EQ("Initial:Entry:Exit:A3", GetLog());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", GetCurrentStateName());

    TriggerE1();
    TriggerE2();
    TriggerE3();
    EXPECT_EQ("Initial:Entry:Exit:A3", GetLog());
    EXPECT_EQ("FloHsmFinal_5OdpEA31BEcPrWrNx8u7", GetCurrentStateName());
}

