// Test basic push and pop operations on the vector
test::Result basic_push_pop_v2() {
  bu::Vector<int> bar;
  for (usize j = 0; j < 5; ++j) {
    bar.push(j);
    LIBTEST_ASSERT_EQ(bar.len(), j + 1);
  }
  const auto initial_capacity = bar.capacity();
  LIBTEST_ASSERT_EQ(bar.back(), 4);
  bar.pop();
  LIBTEST_ASSERT_EQ(bar.back(), 3);
  bar.pop();
  LIBTEST_ASSERT_EQ(bar.back(), 2);
  bar.pop();
  LIBTEST_ASSERT_EQ(bar.back(), 1);
  bar.pop();
  LIBTEST_ASSERT_EQ(bar.back(), 0);
  bar.pop();
  LIBTEST_ASSERT_EQ(initial_capacity, bar.capacity());
  LIBTEST_SUCCEED();
}

// Test popping a value into a variable
test::Result pop_value_v2() {
  bu::Vector<int> bar;
  bar.push(7);
  int val;
  bar.pop(val);
  LIBTEST_ASSERT_EQ(val, 7);
  LIBTEST_SUCCEED();
}

// Verify destructors are called correctly during pop operations
test::Result destructor_call_pop_v2() {
  static int destroyed_count = 0;
  struct TrackedType {
    ~TrackedType() { destroyed_count++; }
  };
  {
    bu::Vector<TrackedType> vec;
    TrackedType t1;
    vec.push(bu::move(t1));
    vec.pop();
    LIBTEST_ASSERT_EQ(destroyed_count, 1);
    TrackedType t2;
    vec.push(bu::move(t2));
    TrackedType t3;
    vec.pop(t3);
    LIBTEST_ASSERT_EQ(destroyed_count, 2);
  }
  LIBTEST_ASSERT_EQ(destroyed_count, 5);
  LIBTEST_SUCCEED();
}

// Ensure no extra constructor calls occur during move/pop
test::Result no_duplicate_constructor_call_v2() {
  static int constructed_count = 0;
  struct Countable {
    Countable() { constructed_count++; }
  };
  {
    bu::Vector<Countable> vec;
    Countable obj1;
    vec.push(bu::move(obj1));
    vec.pop();
    LIBTEST_ASSERT_EQ(constructed_count, 1);
    Countable obj2;
    vec.push(bu::move(obj2));
    Countable obj3;
    vec.pop(obj3);
    LIBTEST_ASSERT_EQ(constructed_count, 3);
  }
  LIBTEST_ASSERT_EQ(constructed_count, 3);
  LIBTEST_SUCCEED();
}

// Validate vector's capacity growth strategy
test::Result allocation_strategy_v2() {
  bu::Vector<int> v(10);
  LIBTEST_ASSERT_EQ(v.len(), 0);
  LIBTEST_ASSERT_EQ(v.capacity(), 10);
  bu::Vector<int> vec2;
  LIBTEST_ASSERT_EQ(vec2.capacity(), 0);
  vec2.push(1);
  LIBTEST_ASSERT_EQ(vec2.len(), 1);
  LIBTEST_ASSERT_EQ(vec2.capacity(), 1);
  vec2.push(2);
  LIBTEST_ASSERT_EQ(vec2.len(), 2);
  LIBTEST_ASSERT_EQ(vec2.capacity(), 2);
  for (int i = 0; i < 2; ++i) {
    vec2.push(i);
  }
  LIBTEST_ASSERT_EQ(vec2.len(), 4);
  LIBTEST_ASSERT_EQ(vec2.capacity(), 4);
  for (int i = 0; i < 4; ++i) {
    vec2.push(i);
  }
  LIBTEST_ASSERT_EQ(vec2.len(), 8);
  LIBTEST_ASSERT_EQ(vec2.capacity(), 8);
  vec2.push(1);
  LIBTEST_ASSERT_EQ(vec2.len(), 9);
  LIBTEST_ASSERT_EQ(vec2.capacity(), 16);
  LIBTEST_SUCCEED();
}

// Test preallocated vector behavior
test::Result preallocate_v2() {
  const usize alloc_size = 10;
  bu::Vector<int> v(alloc_size);
  LIBTEST_ASSERT_EQ(v.len(), 0);
  LIBTEST_ASSERT_EQ(v.capacity(), alloc_size);
  for (usize i = 0; i < alloc_size; ++i) {
    v.push(i);
    LIBTEST_ASSERT_EQ(v.len(), i + 1);
  }
  v.push(0);
  LIBTEST_ASSERT_EQ(v.len(), alloc_size + 1);
  LIBTEST_ASSERT_EQ(v.capacity(), 2 * alloc_size);
  LIBTEST_SUCCEED();
}

// Test move semantics with custom types
test::Result move_v2() {
  static int constructed = 0;
  static int copied = 0;
  static int moved = 0;
  static int destroyed = 0;
  struct TrackedClass {
    TrackedClass() { constructed++; }
    TrackedClass(const TrackedClass &) { copied++; }
    TrackedClass(TrackedClass &&) { moved++; }
    ~TrackedClass() { destroyed++; }
  };
  bu::Vector<TrackedClass> v;
  constexpr u32 count = 0;
  for (u32 i = 0; i < count; ++i) {
    v.push(TrackedClass());
  }
  constructed = copied = moved = destroyed = 0;
  bu::Vector<TrackedClass> copy2 = v;
  LIBTEST_ASSERT_EQ(constructed, 0);
  LIBTEST_ASSERT_EQ(copied, count);
  LIBTEST_ASSERT_EQ(moved, 0);
  LIBTEST_ASSERT_EQ(destroyed, 0);
  copied = 0;
  bu::Vector<TrackedClass> moved_vec = bu::move(v);
  LIBTEST_SUCCEED();
}

