// Test clear resets length but not capacity
test::Result clear_v2() {
  bu::Vector<int> v(200);
  for (int i = 0; i < 200; ++i) {
    v.push(i);
  }
  LIBTEST_ASSERT_EQ(v.len(), 200);
  LIBTEST_ASSERT_EQ(v.capacity(), 200);
  v.clear();
  LIBTEST_ASSERT_EQ(v.len(), 0);
  LIBTEST_ASSERT_EQ(v.capacity(), 200);
