// Test remove operation shifts elements correctly
test::Result remove_v2() {
  bu::Vector<usize> v;
  for (usize i = 0; i < 10; ++i) {
    v.push(i);
  }
  v.remove(0);
  LIBTEST_ASSERT_EQ(v.len(), 9);
  LIBTEST_ASSERT_NE(v[0], 0);
  for (usize i = 0; i < v.len(); ++i) {
    LIBTEST_ASSERT_EQ(v[i], i + 1);
  }
  LIBTEST_SUCCEED();
}

// Verify destructors are called when removing elements
test::Result remove_destructor_sanity_v2() {
  static int destruction_counter = 0;
  static bool tracking_enabled = false;
  struct DestructionTracker {
    ~DestructionTracker() {
      if (tracking_enabled) {
        destruction_counter++;
      }
    }
  };
  {
    bu::Vector<DestructionTracker> vec;
    for (int i = 0; i < 3; ++i) {
      vec.push(DestructionTracker());
    }
    tracking_enabled = true;
    vec.remove(0);
    LIBTEST_ASSERT_EQ(destruction_counter, 1);
  }
  LIBTEST_ASSERT_EQ(destruction_counter, 3);
  LIBTEST_SUCCEED();
}

// Test remove_if with predicate
test::Result remove_if_v2() {
  bu::Vector<usize> v;
  for (usize i = 0; i < 100; ++i) {
    v.push(i);
  }
  const usize original_len = v.len();
  v.remove_if([](usize x) { return x % 2 == 0; });
  LIBTEST_ASSERT_EQ(v.len(), original_len / 2);
  for (usize i = 0; i < v.len(); ++i) {
    LIBTEST_ASSERT_NE(v[i] % 2, 0);
  }
  LIBTEST_SUCCEED();
}

// Test range-based for loop support
test::Result range_for_v2() {
  bu::Vector<usize> v;
  for (usize i = 0; i < 50; ++i) {
    v.push(i);
  }
  usize idx = 0;
  for (auto &item : v) {
    LIBTEST_ASSERT_EQ(item, idx);
    item *= 3;
    ++idx;
  }
  idx = 0;
  for (const auto &item : v) {
    LIBTEST_ASSERT_EQ(item, 3 * idx);
    ++idx;
  }
  for (usize i = 0; i < v.len(); ++i) {
    LIBTEST_ASSERT_EQ(v[i], i * 3);
  }
  bu::Vector<usize> empty_vec;
  for (auto &item : empty_vec) {
    LIBTEST_ASSERT(false);
    (void)item;
  }
  LIBTEST_SUCCEED();
}

