  RUN_TEST(no_duplicate_constructor_call_v2);
  RUN_TEST(pop_value_v2);
  RUN_TEST(preallocate_v2);
  RUN_TEST(range_for_v2);
  RUN_TEST(remove_v2);
  RUN_TEST(remove_destructor_sanity_v2);
  RUN_TEST(remove_if_v2);
  RUN_TEST(resize_to_fit_v2);
  LIBTEST_CLEANUP();
}

#include "napi.h"
#include "readXlsxAsync.h"
#include "AsyncReader.h"
#include "AsyncError.h"
#include "normalizeString.h"
#include <set>
// filepathString, doReadHeaders, headerTransformObj, columnsToDeleteArr, doPascalCase, pascalWords, stringColumnsArr, (error, result) =>
namespace xlsx
{
    void readXlsxAsync( const Napi::CallbackInfo& info )
    {
        Napi::Env env = info.Env();
        // Validate argument count and callback presence
        if( info.Length() != 8 || !info[7].IsFunction() )
        {
            std::string msg = info.Length() != 8 
                ? "xlsx-util: invalid argument count - expected 8" 
                : "xlsx-util: invalid callback function [arg7]";
            Napi::TypeError::New(env, msg).ThrowAsJavaScriptException();
            return;
        }

        Napi::Function callback = info[7].As<Napi::Function>();

        // Validate filename (arg0)
        if( !info[0].IsString() )
        {
            auto err = new AsyncError{ callback, "xlsx-util: [arg0] must be a string [filename]" };
            err->Queue();
            return;
        }
        std::string filePath = info[0].As<Napi::String>().Utf8Value();

        // Parse hasHeaders (arg1)
        bool readHeaders = false;
        if( info[1].IsBoolean() )
        {
            readHeaders = info[1].ToBoolean();
        }

        // Build header transformation map (arg2)
        std::map<std::string, std::string> headerReplacements;
        if( info[2].IsObject() )
        {
            Napi::Object transformObj = info[2].As<Napi::Object>();
            Napi::Array keys = transformObj.GetPropertyNames();
            for( uint32_t idx = 0; idx < keys.Length(); ++idx )
            {
                Napi::String keyStr = keys.Get(idx).As<Napi::String>();
                std::string normKey = normalizeString(keyStr.Utf8Value());
                Napi::Value val = transformObj.Get(keyStr);
                if( val.IsString() )
                {
                    std::string normVal = val.As<Napi::String>().Utf8Value();
                    if( !normKey.empty() && !normVal.empty() )
                    {
                        headerReplacements[normKey] = normVal;
                    }
                }
            }
        }

        // Collect columns to delete (arg3)
        std::set<std::string> excludedCols;
        if( info[3].IsArray() )
        {
            Napi::Array delList = info[3].As<Napi::Array>();
            for( uint32_t i = 0; i < delList.Length(); ++i )
            {
                Napi::Value item = delList.Get(i);
                if( item.IsString() )
                {
                    excludedCols.insert(item.As<Napi::String>().Utf8Value());
                }
            }
        }

        // Determine Pascal-case flag (arg4)
        bool applyPascalCase = false;
        if( info[4].IsBoolean() )
        {
            applyPascalCase = info[4].ToBoolean();
        }

        // Load Pascal-case exceptions (arg5)
        std::set<std::string> pascalExceptions;
        if( info[5].IsArray() )
        {
            Napi::Array pascalArr = info[5].As<Napi::Array>();
            for( uint32_t i = 0; i < pascalArr.Length(); ++i )
            {
                Napi::Value elem = pascalArr.Get(i);
                if( elem.IsString() )
                {
                    pascalExceptions.insert(elem.As<Napi::String>().Utf8Value());
                }
            }
        }

        // Define string-typed columns (arg6)
        std::set<std::string> forceStringCols;
        if( info[6].IsArray() )
        {
            Napi::Array strCols = info[6].As<Napi::Array>();
            for( uint32_t i = 0; i < strCols.Length(); ++i )
            {
                Napi::Value entry = strCols.Get(i);
                if( entry.IsString() )
                {
                    forceStringCols.insert(entry.As<Napi::String>().Utf8Value());
                }
            }
        }

        // Launch async processing
        AsyncReader* processor = new AsyncReader{
            filePath,
            readHeaders,
            headerReplacements,
            excludedCols,
            applyPascalCase,
            pascalExceptions,
            forceStringCols,
            callback
        };
        processor->Queue();
    }
}

#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <cctype>
#include <sys/stat.h>

// Simplified version of path utilities with different implementation approach

class PathManager {
private:
    std::vector<std::string> paths;

    // Helper to normalize path representation
    std::string normalizePath(const std::string& path) {
        std::string result = path;

        // Convert backslashes to forward slashes
        std::replace(result.begin(), result.end(), '\\', '/');

        // Remove trailing slash unless it's root
        if (result.length() > 1 && result.back() == '/') {
            result.pop_back();
        }

        return result;
    }

    // Check if path is absolute using different approach
    bool isAbsolutePath(const std::string& path) const {
        if (path.empty()) return false;

        // Unix-style absolute path
        if (path[0] == '/') return true;

        // Windows-style absolute path
        if (path.length() >= 2 && path[1] == ':') return true;
        if (path.length() >= 2 && (path[0] == '\\' || path[1] == '\\')) return true;

        return false;
    }

public:
    // Add path with duplicate checking
    bool addPath(const std::string& path) {
        std::string normalized = normalizePath(path);

        // Check if already exists
        if (std::find(paths.begin(), paths.end(), normalized) != paths.end()) {
            return false;
        }

        paths.push_back(normalized);
        return true;
    }

    // Add multiple paths
    void addPaths(const std::vector<std::string>& pathList) {
        for (const auto& path : pathList) {
            addPath(path);
        }
    }

    // Find file in path list
    std::string findFile(const std::string& filename) const {
        std::string cleanName = filename;

        // Normalize filename
        std::replace(cleanName.begin(), cleanName.end(), '\\', '/');

        // Extract just the filename part
        size_t pos = cleanName.find_last_of('/');
        std::string fileNameOnly = (pos != std::string::npos) ? 
                                   cleanName.substr(pos + 1) : cleanName;

        // Search each path
        for (const auto& path : paths) {
            std::string fullPath = path + "/" + fileNameOnly;

            // Check if file exists (simplified check)
            struct stat buffer;
            if (stat(fullPath.c_str(), &buffer) == 0) {
                return fullPath;
            }
        }

        return "";
    }

    // Get all paths
    const std::vector<std::string>& getPaths() const {
        return paths;
    }
};

// File existence check using different approach
bool fileExists(const std::string& filename) {
    struct stat buffer;
    return (stat(filename.c_str(), &buffer) == 0);
}

// Copy file with different implementation
bool copyFile(const std::string& src, const std::string& dest, bool overwrite) {
    // Check if destination exists and overwrite is false
    if (!overwrite && fileExists(dest)) {
        return false;
    }

    // Open files
    FILE* source = fopen(src.c_str(), "rb");
    if (!source) return false;

    FILE* destination = fopen(dest.c_str(), "wb");
    if (!destination) {
        fclose(source);
        return false;
    }

    // Copy contents
    char buffer[8192];
    size_t bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), source)) > 0) {
        if (fwrite(buffer, 1, bytesRead, destination) != bytesRead) {
            fclose(source);
            fclose(destination);
            return false;
        }
    }

    fclose(source);
    fclose(destination);
    return true;
}

// Rename file using different approach
bool renameFile(const std::string& oldName, const std::string& newName, bool allowOverwrite) {
    // First try direct rename
    if (rename(oldName.c_str(), newName.c_str()) == 0) {
        return true;
    }

    // If direct rename fails, try copy + delete
    if (copyFile(oldName, newName, allowOverwrite)) {
        remove(oldName.c_str());
        return true;
    }

    return false;
}

// Path extraction functions
std::string extractDirectory(const std::string& fullPath) {
    if (fullPath.empty()) return "";

    // Find last path separator
    size_t pos = fullPath.find_last_of("/\\");
    if (pos == std::string::npos) {
        return ""; // No directory component
    }

    return fullPath.substr(0, pos);
}

std::string extractFilename(const std::string& fullPath) {
    if (fullPath.empty()) return "";

    // Find last path separator
    size_t pos = fullPath.find_last_of("/\\");
    if (pos == std::string::npos) {
        return fullPath; // No directory component
    }

    return fullPath.substr(pos + 1);
}

// Main function demonstrating usage
int main() {
    PathManager pathManager;

    // Add some paths
    pathManager.addPath("/usr/local/bin");
    pathManager.addPath("/opt/bin");
    pathManager.addPath("C:\\Program Files\\Tools");

    // Try to find a file
    std::string found = pathManager.findFile("myapp.exe");
    if (!found.empty()) {
        std::cout << "Found file at: " << found << std::endl;
    } else {
        std::cout << "File not found in path list" << std::endl;
    }

    // Test file operations
    std::string sourceFile = "source.txt";
    std::string destFile = "destination.txt";

    if (fileExists(sourceFile)) {
        std::cout << "Source file exists" << std::endl;
        if (copyFile(sourceFile, destFile, true)) {
            std::cout << "File copied successfully" << std::endl;
        }
    }

    // Test path extraction
    std::string fullPath = "/path/to/user/documents/file.txt";
    std::cout << "Directory: " << extractDirectory(fullPath) << std::endl;
    std::cout << "Filename: " << extractFilename(fullPath) << std::endl;

    return 0;
}

#include "ncbind/ncbind.hpp"
#include "discord_rpc.h"
#include "discord_register.h"
#include "CharacterSet.h"

class DiscordRPC
{
private:
    // Helper to convert tTJSVariant to UTF-8 std::string
    static std::string ToUtf8(const tTJSVariant& var)
    {
        tjs_string utf16 = ttstr(var).c_str();
        std::string utf8;
        TVPUtf16ToUtf8(utf8, utf16);
        return utf8;
    }

    // Helper to extract string property from closure as UTF-8 c_str()
    static const char* GetStringProp(tTJSVariantClosure& clo, const wchar_t* name)
    {
        static ttstr nameStr = name;
        tTJSVariant val;
        clo.PropGet(0, nameStr.c_str(), nameStr.GetHint(), &val, nullptr);
        std::string s = ToUtf8(val);
        return s.empty() ? nullptr : s.c_str();
    }

    // Helper to extract integer property from closure
    static int GetIntProp(tTJSVariantClosure& clo, const wchar_t* name)
    {
        static ttstr nameStr = name;
        tTJSVariant val;
        clo.PropGet(0, nameStr.c_str(), nameStr.GetHint(), &val, nullptr);
        return val.AsInteger();
    }

public:
    static void Initialize(tTJSVariant applicationId, tTJSVariant handlers, tTJSVariant autoRegister, tTJSVariant optionalSteamId)
    {
        DiscordEventHandlers handlers_c{};
        std::string appIdStr = ToUtf8(applicationId);
        std::string steamIdStr = ToUtf8(optionalSteamId);
        Discord_Initialize(
            appIdStr.c_str(),
            &handlers_c,
            autoRegister.AsInteger() != 0,
            !steamIdStr.empty() ? steamIdStr.c_str() : nullptr
        );
    }

    static void Shutdown()
    {
        Discord_Shutdown();
    }

    static void RunCallbacks()
    {
        Discord_RunCallbacks();
    }

#if 0
    static void UpdateConnection()
    {
        Discord_UpdateConnection();
    }
#endif

    static void UpdatePresence(tTJSVariant presence)
    {
        DiscordRichPresence rpc{};
        tTJSVariantClosure clo = presence.AsObjectClosureNoAddRef();

        rpc.state             = GetStringProp(clo, TJS_W("state"));
        rpc.details           = GetStringProp(clo, TJS_W("details"));
        rpc.startTimestamp    = GetIntProp(clo, TJS_W("startTimestamp"));
        rpc.endTimestamp      = GetIntProp(clo, TJS_W("endTimestamp"));
        rpc.largeImageKey     = GetStringProp(clo, TJS_W("largeImageKey"));
        rpc.largeImageText    = GetStringProp(clo, TJS_W("largeImageText"));
        rpc.smallImageKey     = GetStringProp(clo, TJS_W("smallImageKey"));
        rpc.smallImageText    = GetStringProp(clo, TJS_W("smallImageText"));
        rpc.partyId           = GetStringProp(clo, TJS_W("partyId"));
        rpc.partySize         = GetIntProp(clo, TJS_W("partySize"));
        rpc.partyMax          = GetIntProp(clo, TJS_W("partyMax"));
        rpc.partyPrivacy      = GetIntProp(clo, TJS_W("partyPrivacy"));
        rpc.matchSecret       = GetStringProp(clo, TJS_W("matchSecret"));
        rpc.joinSecret        = GetStringProp(clo, TJS_W("joinSecret"));
        rpc.spectateSecret    = GetStringProp(clo, TJS_W("spectateSecret"));
        rpc.instance          = GetIntProp(clo, TJS_W("instance"));

        Discord_UpdatePresence(&rpc);
    }

    static void ClearPresence()
    {
        Discord_ClearPresence();
    }

    static void Respond(tTJSVariant userid, tTJSVariant reply)
    {
        std::string userIdStr = ToUtf8(userid);
        Discord_Respond(userIdStr.c_str(), reply.AsInteger());
    }

    static void UpdateHandlers(tTJSVariant handlers)
    {
        // Placeholder: not yet implemented
    }

    static void Register(tTJSVariant applicationId, tTJSVariant command)
    {
        std::string appIdStr = ToUtf8(applicationId);
        std::string cmdStr   = ToUtf8(command);
        Discord_Register(appIdStr.c_str(), cmdStr.c_str());
    }

    static void RegisterSteamGame(tTJSVariant applicationId, tTJSVariant steamId)
    {
        std::string appIdStr = ToUtf8(applicationId);
        std::string steamStr = ToUtf8(steamId);
        Discord_RegisterSteamGame(appIdStr.c_str(), steamStr.c_str());
    }
