#include "Animator.hpp"
#include <algorithm>
#include <unordered_set>

namespace crisp
{
    Animator::Animator()
        : m_shouldClearAll(false)
    {
    }

    void Animator::update(double deltaTime)
    {
        // Handle global clear request
        if (m_shouldClearAll)
        {
            m_pendingAnimations.clear();
            m_activeAnimations.clear();
            m_toRemoveAnimations.clear();
            m_objectAnimationMap.clear();
            m_shouldClearAll = false;
        }

        // Process animations marked for removal
        if (!m_toRemoveAnimations.empty())
        {
            // Remove from active animations
            m_activeAnimations.erase(
                std::remove_if(m_activeAnimations.begin(), m_activeAnimations.end(),
                    [this](const std::shared_ptr<Animation>& anim) {
                        return m_toRemoveAnimations.find(anim) != m_toRemoveAnimations.end();
                    }),
                m_activeAnimations.end()
            );

            // Remove from pending animations
            m_pendingAnimations.erase(
                std::remove_if(m_pendingAnimations.begin(), m_pendingAnimations.end(),
                    [this](const std::shared_ptr<Animation>& anim) {
                        return m_toRemoveAnimations.find(anim) != m_toRemoveAnimations.end();
                    }),
                m_pendingAnimations.end()
            );

            m_toRemoveAnimations.clear();
        }

        // Move pending animations to active list
        if (!m_pendingAnimations.empty())
        {
            m_activeAnimations.insert(m_activeAnimations.end(),
                m_pendingAnimations.begin(), m_pendingAnimations.end());
            m_pendingAnimations.clear();
        }

        // Update all active animations and track finished ones
        bool anyFinished = false;
        for (auto& animation : m_activeAnimations)
        {
            animation->update(deltaTime);
            if (animation->isFinished())
            {
                animation->setActive(false);
                anyFinished = true;
            }
        }

        // Clean up finished animations
        if (anyFinished)
        {
            m_activeAnimations.erase(
                std::remove_if(m_activeAnimations.begin(), m_activeAnimations.end(),
                    [](const std::shared_ptr<Animation>& anim) {
                        return anim->isFinished();
                    }),
                m_activeAnimations.end()
            );
        }
    }

    void Animator::add(std::shared_ptr<Animation> anim)
    {
        m_pendingAnimations.push_back(anim);
        anim->setActive(true);
    }

    void Animator::add(std::shared_ptr<Animation> animation, void* targetObject)
    {
        m_pendingAnimations.push_back(animation);
        m_objectAnimationMap[targetObject].push_back(animation);
        animation->setActive(true);
    }

    void Animator::remove(std::shared_ptr<Animation> anim)
    {
        m_toRemoveAnimations.insert(anim);
    }

    void Animator::clearAllAnimations()
    {
        m_shouldClearAll = true;
    }

    void Animator::clearObjectAnimations(void* targetObject)
    {
        auto it = m_objectAnimationMap.find(targetObject);
        if (it == m_objectAnimationMap.end())
            return;

        for (auto& anim : it->second)
            m_toRemoveAnimations.insert(anim);

        m_objectAnimationMap.erase(it);
    }
}

