void FUnrealcvServer::Tick(float DeltaTime)
{
	SCOPE_CYCLE_COUNTER(STAT_Tick);
	EnsureWorldControllerExists();
	FlushPendingRequests();
}

void FUnrealcvServer::EnsureWorldControllerExists()
{
	UWorld* ActiveWorld = GetActiveWorld();
	if (!IsValid(ActiveWorld) || WorldController.IsValid())
		return;

	UE_LOG(LogTemp, Display, TEXT("FUnrealcvServer::EnsureWorldControllerExists Creating WorldController"));
	AUnrealcvWorldController* NewController = Cast<AUnrealcvWorldController>(
		ActiveWorld->SpawnActor(AUnrealcvWorldController::StaticClass())
	);

	if (NewController != nullptr)
	{
		WorldController = NewController;
		WorldController->InitWorld();
	}
	else
	{
		UE_LOG(LogUnrealCV, Error, TEXT("Failed to spawn WorldController"));
	}
}

APawn* FUnrealcvServer::GetPawn()
{
	UWorld* CurrentWorld = GetWorld();
	if (!IsValid(CurrentWorld))
		return nullptr;

	APlayerController* Controller = CurrentWorld->GetFirstPlayerController();
	if (!IsValid(Controller))
		return nullptr;

	APawn* FoundPawn = Controller->GetPawn();
	return FoundPawn;
}

