{
	// Cleanup handled by engine lifecycle
}

UWorld* FUnrealcvServer::GetWorld()
{
#if WITH_EDITOR
	UEditorEngine* EditorEngine = Cast<UEditorEngine>(GEngine);
	if (EditorEngine == nullptr)
	{
		UE_LOG(LogUnrealCV, Error, TEXT("EditorEngine is invalid"));
		return nullptr;
	}

	UWorld* TargetWorld = nullptr;
	if (EditorEngine->GetPIEWorldContext() != nullptr)
	{
		TargetWorld = EditorEngine->GetPIEWorldContext()->World();
	}
	else
	{
		TargetWorld = EditorEngine->GetEditorWorldContext().World();
	}

	if (IsValid(TargetWorld))
		return TargetWorld;
#else
	UGameEngine* GameEngine = Cast<UGameEngine>(GEngine);
	if (GameEngine == nullptr)
	{
		UE_LOG(LogUnrealCV, Error, TEXT("GameEngine is invalid"));
		return nullptr;
	}

	UWorld* TargetWorld = GameEngine->GetGameWorld();
	if (IsValid(TargetWorld))
		return TargetWorld;
#endif

	UE_LOG(LogUnrealCV, Error, TEXT("UWorld pointer is invalid: %p."), TargetWorld);
	return nullptr;
}

UWorld* FUnrealcvServer::GetActiveWorld()
{
#if WITH_EDITOR
	UEditorEngine* EditorEngine = Cast<UEditorEngine>(GEngine);
	if (EditorEngine != nullptr)
	{
		UWorld* PlayWorld = EditorEngine->PlayWorld;
		if (IsValid(PlayWorld) && PlayWorld->IsGameWorld())
			return PlayWorld;
	}
#endif

	UGameEngine* GameEngine = Cast<UGameEngine>(GEngine);
	if (GameEngine != nullptr)
	{
		UWorld* GameWorld = GameEngine->GetGameWorld();
		if (IsValid(GameWorld))
			return GameWorld;
	}

	return nullptr;
}

void FUnrealcvServer::ProcessRequest(FRequest& Request)
{
	SCOPE_CYCLE_COUNTER(STAT_ProcessRequest);
	FExecStatus Result = CommandDispatcher->Exec(Request.Message);
	UE_LOG(LogUnrealCV, Warning, TEXT("Response: %s"), *Result.GetMessage());

	FString Header = FString::Printf(TEXT("%d:"), Request.RequestId);
	TArray<uint8> ResponseData;
	FExecStatus::BinaryArrayFromString(Header, ResponseData);
	ResponseData.Append(Result.GetData());
	TcpServer->SendData(ResponseData);
}

void FUnrealcvServer::FlushPendingRequests()
{
	while (!PendingRequest.IsEmpty())
	{
		FRequest CurrentRequest;
		if (!PendingRequest.Dequeue(CurrentRequest))
			continue;

		uint32 RequestId = CurrentRequest.RequestId;
		const FString& Message = CurrentRequest.Message;

		if (Message.StartsWith(TEXT("vbatch")))
		{
			FString BatchSizeStr = Message.RightChop(6); // skip "vbatch"
			int32 DesiredBatchSize = FCString::Atoi(*BatchSizeStr);
			if (DesiredBatchSize < 1)
			{
				UE_LOG(LogUnrealCV, Warning, TEXT("Invalid batch size: %d"), DesiredBatchSize);
				continue;
			}

			FString Header = FString::Printf(TEXT("%d:"), RequestId);
			TArray<uint8> Reply;
			FExecStatus::BinaryArrayFromString(Header, Reply);
			Reply += FExecStatus::OK().GetData();
			TcpServer->SendData(Reply);
			BatchSize = DesiredBatchSize;
			continue;
		}

		BatchSize = 1;

		if (BatchSize > 0)
		{
			PendingBatch.Add(CurrentRequest);
			BatchSize--;
		}

		if (BatchSize == 0)
		{
			for (const FRequest& Req : PendingBatch)
			{
				ProcessRequest(Req);
			}
			PendingBatch.Empty();
		}
	}
}

void FUnrealcvServer::HandleRawMessage(const FString& Endpoint, const FString& RawInput)
{
	UE_LOG(LogUnrealCV, Warning, TEXT("Request: %s"), *RawInput);

	const FString Pattern = TEXT("(\\d{1,8}):(.*)");
	FRegexPattern Regex(Pattern);
	FRegexMatcher Matcher(Regex, RawInput);

	if (Matcher.FindNext())
	{
		FString IdStr = Matcher.GetCaptureGroup(1);
		FString Msg = Matcher.GetCaptureGroup(2);
		uint32 Id = FCString::Atoi(*IdStr);

		FRequest NewRequest(Endpoint, Msg, Id);
		PendingRequest.Enqueue(NewRequest);
	}
	else
	{
		UE_LOG(LogUnrealCV, Warning, TEXT("Malformed request: '%s'"), *RawInput);
	}
}

void FUnrealcvServer::HandleError(const FString& ErrMsg)
{
	if (Config.ExitOnFailure)
	{
		UE_LOG(LogUnrealCV, Error, TEXT("Critical error: %s. Shutting down."), *ErrMsg);
		FGenericPlatformMisc::RequestExit(false);
	}
}

