// Helper function to validate numeric conversions
template<typename T>
bool verify_conversion(T original, const std::string& expected) {
    apex::string256_t converted = apex::to_string(original);
    return converted.c_str() == expected || std::string(converted.c_str()) == expected;
}

// Test unsigned integer string conversions with alternative validation
TEST(string, alternative_uint_conversions) {
    // Verify basic digit conversions
    EXPECT_EQ(apex::string16_t::to_string(0U), "0");
    EXPECT_EQ(apex::string16_t::to_string(1U), "1");
    EXPECT_EQ(apex::string16_t::to_string(99U), "99");

    // Check boundary values
    EXPECT_STREQ(apex::string16_t::to_string(uint32_t(INT32_MAX)).c_str(), "2147483647");
    EXPECT_STREQ(apex::string16_t::to_string(UINT32_MAX).c_str(), "4294967295");

    // Test overflow conditions with smaller buffers
    EXPECT_THROW(apex::String<1>::to_string(0U).c_str(), std::overflow_error);
    EXPECT_STREQ(apex::String<2>::to_string(0U).c_str(), "0");
    EXPECT_THROW(apex::String<2>::to_string(12U).c_str(), std::overflow_error);

    // Verify 8-bit string buffer limits
    EXPECT_STREQ(apex::string8_t::to_string(1234567U).c_str(), "1234567");
    EXPECT_THROW(apex::string8_t::to_string(12345670U).c_str(), std::overflow_error);
    EXPECT_THROW(apex::string8_t::to_string(123456701U).c_str(), std::overflow_error);
    EXPECT_THROW(apex::string8_t::to_string(1234567012U).c_str(), std::overflow_error);
}

// Bidirectional conversion verification for unsigned integers
template<typename BufferType>
void bidirectional_unsigned_test() {
    std::vector<uint32_t> test_values = {0, 1, 12, 123, 1234, 12345, 
                                        123456, 1234567, 12345678, 
                                        123456789, 1234567890};

    for (const auto& val : test_values) {
        BufferType str_val = apex::to_string(val);
        uint32_t parsed_val = apex::stoul(str_val);
        EXPECT_EQ(parsed_val, val);
    }

    // Special cases
    EXPECT_EQ(apex::stoul(BufferType("-1")), 0xFFFFFFFF);
    EXPECT_EQ(apex::stoul(BufferType("4294967298")), UINT32_MAX);
}

TEST(string, roundtrip_unsigned_values) {
    bidirectional_unsigned_test<apex::string16_t>();
    bidirectional_unsigned_test<apex::string32_t>();
    bidirectional_unsigned_test<apex::string64_t>();
    bidirectional_unsigned_test<apex::string128_t>();
    bidirectional_unsigned_test<apex::string256_t>();
    bidirectional_unsigned_test<apex::string_strict16_t>();
    bidirectional_unsigned_test<apex::string_strict32_t>();
    bidirectional_unsigned_test<apex::string_strict64_t>();
    bidirectional_unsigned_test<apex::string_strict128_t>();
