// Floating point conversion verification
template<typename BufferType>
void floating_point_roundtrip_test() {
#ifndef APEX_OSX
    // OS X's POSIX gcvt call uses dynamic memory calls
#endif

    std::vector<float> test_values = {0.0F, -0.0F, 9.123456F, -9.123456F,
                                     9.123456E+37F, -9.123456E+37F,
                                     9.123456E-37F, -9.123456E-37F,
                                     0.1F, 0.02F, 0.003F, 9.0E-9F,
                                     FLT_MAX, -FLT_MAX, FLT_MIN, -FLT_MIN};

    for (const auto& val : test_values) {
        if (!std::isinf(val) && !std::isnan(val)) {
            BufferType str_val = apex::to_string(val);
            float parsed_val = apex::stof(str_val);
            EXPECT_FLOAT_EQ(parsed_val, val);
        }
    }

    // Special float values
    EXPECT_TRUE(std::isnan(apex::stof(BufferType(apex::to_string(std::nanf("0x7FC00000"))))));
}

TEST(string, roundtrip_float_values) {
    floating_point_roundtrip_test<apex::string16_t>();
