    floating_point_roundtrip_test<apex::string64_t>();
    floating_point_roundtrip_test<apex::string128_t>();
    floating_point_roundtrip_test<apex::string256_t>();
    floating_point_roundtrip_test<apex::string_strict16_t>();
    floating_point_roundtrip_test<apex::string_strict32_t>();
    floating_point_roundtrip_test<apex::string_strict64_t>();
    floating_point_roundtrip_test<apex::string_strict128_t>();
    floating_point_roundtrip_test<apex::string_strict256_t>();
}

