// String parsing edge cases
TEST(string, string_parsing_edge_cases) {
    const apex::string8_t invalid_number("????");
    const apex::string32_t large_positive("100000000000000000000");
    const apex::string32_t large_negative("-100000000000000000000");
    const apex::string_strict8_t strict_invalid("????");

    EXPECT_EQ(apex::stoul(invalid_number), 0U);
    EXPECT_EQ(apex::stoul(strict_invalid), 0U);
    EXPECT_EQ(apex::stoul(apex::to_string(0U)), 0U);
    EXPECT_EQ(apex::stoul(apex::to_string(UINT32_MAX)), UINT32_MAX);
    EXPECT_EQ(apex::stoul(apex::to_string("4294967296")), UINT32_MAX);
    EXPECT_EQ(apex::stoul(large_positive), UINT32_MAX);
    EXPECT_EQ(apex::stoul(large_negative), UINT32_MAX);

    EXPECT_EQ(apex::stol(invalid_number), 0);
    EXPECT_EQ(apex::stol(strict_invalid), 0);
    EXPECT_EQ(apex::stol(apex::to_string(0)), 0);
    EXPECT_EQ(apex::stol(apex::to_string(INT32_MAX)), INT32_MAX);
    EXPECT_EQ(apex::stol(apex::to_string(INT32_MIN)), INT32_MIN);
    EXPECT_EQ(apex::stol(apex::to_string("-2147483649")), INT32_MIN);
    EXPECT_EQ(apex::stol(large_positive), INT32_MAX);
    EXPECT_EQ(apex::stol(large_negative), INT32_MIN);

    EXPECT_EQ(apex::stoull(invalid_number), 0ULL);
    EXPECT_EQ(apex::stoull(strict_invalid), 0ULL);
    EXPECT_EQ(apex::stoull(apex::to_string(0ULL)), 0ULL);
    EXPECT_EQ(apex::stoull(apex::to_string(UINT64_MAX)), UINT64_MAX);
    EXPECT_EQ(apex::stoull(large_positive), UINT64_MAX);
    EXPECT_EQ(apex::stoull(large_negative), UINT64_MAX);

    EXPECT_EQ(apex::stoll(invalid_number), 0LL);
    EXPECT_EQ(apex::stoll(strict_invalid), 0LL);
    EXPECT_EQ(apex::stoll(apex::to_string(0LL)), 0LL);
    EXPECT_EQ(apex::stoll(apex::to_string(INT64_MAX)), INT64_MAX);
    EXPECT_EQ(apex::stoll(apex::to_string(INT64_MIN)), INT64_MIN);
    EXPECT_EQ(apex::stoll(large_positive), INT64_MAX);
    EXPECT_EQ(apex::stoll(large_negative), INT64_MIN);
}

