#include <iostream>

// Helper function to swap two integers
void exchange(int* x, int* y) {
    int buffer = *x;
    *x = *y;
    *y = buffer;
}

// Merge two sorted subarrays
void combine(int data[], int left, int mid, int right) {
    int lenLeft = mid - left + 1;
    int lenRight = right - mid;

    int tempLeft[lenLeft], tempRight[lenRight];

    for (int i = 0; i < lenLeft; ++i)
        tempLeft[i] = data[left + i];
    for (int j = 0; j < lenRight; ++j)
        tempRight[j] = data[mid + 1 + j];

    int idxL = 0, idxR = 0, idxMerge = left;

    while (idxL < lenLeft && idxR < lenRight) {
        if (tempLeft[idxL] <= tempRight[idxR]) {
            data[idxMerge] = tempLeft[idxL++];
        } else {
            data[idxMerge] = tempRight[idxR++];
        }
        ++idxMerge;
    }

    while (idxL < lenLeft) {
        data[idxMerge++] = tempLeft[idxL++];
    }

    while (idxR < lenRight) {
        data[idxMerge++] = tempRight[idxR++];
    }
}

// Recursive merge sort implementation
void mergeData(int arr[], int low, int high) {
    if (low < high) {
        int center = low + (high - low) / 2;
        mergeData(arr, low, center);
        mergeData(arr, center + 1, high);
        combine(arr, low, center, high);
    }
}

// Partition function for quicksort using middle element as pivot
int separate(int data[], int begin, int finish) {
    int pivotVal = data[begin + (finish - begin) / 2];
    int i = begin - 1;
    int j = finish + 1;

    while (true) {
        while (data[++i] < pivotVal);
        while (data[--j] > pivotVal);

        if (i >= j) return j;
        exchange(&data[i], &data[j]);
    }
}

// Recursive quicksort implementation
void sortQuick(int arr[], int start, int end) {
    if (start >= end) return;

    int splitPoint = separate(arr, start, end);
    sortQuick(arr, start, splitPoint);
    sortQuick(arr, splitPoint + 1, end);
}

int main() {
    // First array for merge sort
    int numbers[] = {5, 1, 6, 2, 7, 1, 8, 2, 9, 2};
    mergeData(numbers, 0, 9);

    for (int val : numbers) {
        std::cout << val << " ";
    }
    std::cout << std::endl;

    // Second array for quicksort
    int values[] = {5, 1, 6, 2, 7, 1, 8, 2, 9, 2};
    sortQuick(values, 0, 9);

    for (int val : values) {
        std::cout << val << " ";
    }

    return 0;
}

