	int* pindex;     /* parent in this struct */
	double** state;
	double* a;
	double* b;
	double* d;
	double* rhs;
	double* af;      /* efficiency benefit is very low, rall/dx^2 */
	double* bf;      /* 1/dx^2 */
	double* vol;     /* volatile volume from COMPARTMENT */
	double* dc;      /* volatile diffusion constant * cross sectional area */
} LongDifus;

typedef struct LongDifusThreadData {
	int nthread;
	LongDifus** ldifus;
	Memb_list** ml;
} LongDifusThreadData;

