extern "C" void nrn_tree_solve(double* a, double* d, double* b, double* rhs, int* pindex, int node_count) {
    int idx;
    // Forward elimination (triangulation)
    for (idx = node_count - 1; idx > 0; --idx) {
        int parent_idx = pindex[idx];
        if (parent_idx > -1) {
            double factor = a[idx] / d[idx];
            d[parent_idx] -= factor * b[idx];
            rhs[parent_idx] -= factor * rhs[idx];
        }
    }

    // Back substitution
    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = pindex[idx];
        if (parent_idx > -1) {
            rhs[idx] -= b[idx] * rhs[parent_idx];
        }
        rhs[idx] /= d[idx];
    }
}

void long_difus_solve(int method, NrnThread* nt) {
    ldifusfunc2_t* func_ptr = NULL;
    int idx;

    if (ldifusfunc) {
        switch (method) {
            case 0: func_ptr = stagger; break;
            case 1: func_ptr = ode; break;
            case 2: func_ptr = matsol; break;
            case 3: func_ptr = overall_setup; break;
        }
        assert(func_ptr);

        for (idx = 0; idx < ldifusfunccnt; ++idx) {
            (*ldifusfunc[idx])(func_ptr, nt);
        }
    }
}

static void longdifusfree(LongDifus** ppld) {
    if (*ppld) {
        LongDifus* ld_ptr = *ppld;
#if 0
printf("free longdifus structure_change=%d %d\n", ld_ptr->schange, structure_change_cnt);
#endif
        free(ld_ptr->mindex);
        free(ld_ptr->pindex);
        free(ld_ptr->state);
        free(ld_ptr->a);
        free(ld_ptr->b);
        free(ld_ptr->d);
        free(ld_ptr->rhs);
        free(ld_ptr->af);
        free(ld_ptr->bf);
        free(ld_ptr->vol);
        free(ld_ptr->dc);
        free(ld_ptr);
    }
    *ppld = (LongDifus*)0;
}

static void longdifus_diamchange(LongDifus* ld_ptr, int m, int sindex, Memb_list* ml, NrnThread* _nt) {
    int idx, node_count, mi, mpi, j, vnodecount;
    Node* nd, *pnd;
    double rall, dxp, dxc;

    if (ld_ptr->dchange == diam_change_cnt) return;

    vnodecount = _nt->end;
    node_count = ml->nodecount;

    for (idx = 0; idx < node_count; ++idx) {
        mi = ld_ptr->mindex[idx];
        if (sindex < 0) {
            ld_ptr->state[idx] = ml->pdata[mi][-sindex - 1].pval;
        } else {
            ld_ptr->state[idx] = ml->data[mi] + sindex;
        }

        nd = ml->nodelist[mi];
        int pindex = ld_ptr->pindex[idx];

        if (pindex > -1) {
            mpi = ld_ptr->mindex[pindex];
            pnd = ml->nodelist[mpi];

            if (nd->sec_node_index_ == 0) {
                rall = nd->sec->prop->dparam[4].val;
            } else {
                rall = 1.0;
            }

            dxc = section_length(nd->sec) / ((double)(nd->sec->nnode - 1));
            dxp = section_length(pnd->sec) / ((double)(pnd->sec->nnode - 1));

            ld_ptr->af[idx] = 2.0 * rall / dxp / (dxc + dxp);
            ld_ptr->bf[idx] = 2.0 / dxc / (dxc + dxp);
        }
    }

    ld_ptr->dchange = diam_change_cnt;
}

static void longdifusalloc(LongDifus** ppld, int m, int sindex, Memb_list* ml, NrnThread* _nt) {
    LongDifus* ld_ptr;
    int idx, node_count, mi, mpi, vnodecount;
    int* map, *omap;
    Node* nd, *pnd;

    vnodecount = _nt->end;
    *ppld = ld_ptr = (LongDifus*)emalloc(sizeof(LongDifus));
    node_count = ml->nodecount;

    ld_ptr->dchange = 0;
    ld_ptr->mindex = (int*)ecalloc(node_count, sizeof(int));
    ld_ptr->pindex = (int*)ecalloc(node_count, sizeof(int));
    ld_ptr->state = (double**)ecalloc(node_count, sizeof(double*));
    ld_ptr->a = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->b = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->d = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->rhs = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->af = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->bf = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->vol = (double*)ecalloc(node_count, sizeof(double));
    ld_ptr->dc = (double*)ecalloc(node_count, sizeof(double));

    map = (int*)ecalloc(vnodecount, sizeof(int));
    omap = (int*)ecalloc(node_count, sizeof(int));

    for (idx = 0; idx < vnodecount; ++idx) {
        map[idx] = -1;
    }

    for (idx = 0; idx < node_count; ++idx) {
        map[ml->nodelist[idx]->v_node_index] = idx;
    }

    int ordered_idx = 0;
    for (idx = 0; idx < vnodecount; ++idx) {
        if (map[idx] > -1) {
            ld_ptr->mindex[ordered_idx] = map[idx];
            omap[map[idx]] = ordered_idx;

            pnd = _nt->_v_parent[idx];
            int parent_map_idx = map[pnd->v_node_index];

            if (parent_map_idx == -1) {
                pnd = _nt->_v_parent[pnd->v_node_index];
                if (pnd) {
                    parent_map_idx = map[pnd->v_node_index];
                    if (parent_map_idx < 0) {
                        Section* psec = _nt->_v_node[idx]->sec->parentsec;
                        if (psec) {
                            pnd = psec->pnode[0];
                            parent_map_idx = map[pnd->v_node_index];
                        }
                    }
                } else {
                    Section* psec = _nt->_v_node[idx]->sec->parentsec;
                    if (psec) {
                        pnd = psec->pnode[0];
                        parent_map_idx = map[pnd->v_node_index];
                    }
                }
            }

            if (parent_map_idx > -1) {
                ld_ptr->pindex[ordered_idx] = omap[parent_map_idx];
            } else {
                ld_ptr->pindex[ordered_idx] = -1;
            }

            ordered_idx += 1;
        }
    }

    longdifus_diamchange(ld_ptr, m, sindex, ml, _nt);

#if 0
	for (idx=0; idx < node_count; ++idx) {
printf("i=%d pin=%d mi=%d :%s node %d state[(%i)]=%g\n", idx, ld_ptr->pindex[idx],
	ld_ptr->mindex[idx], secname(ml->nodelist[ld_ptr->mindex[idx]]->sec),
	ml->nodelist[ld_ptr->mindex[idx]]->sec_node_index_
	, sindex, ld_ptr->state[idx][0]);
	}
#endif

    free(map);
    free(omap);
}

static void overall_setup(int m, ldifusfunc3_t diffunc, void** v, int ai, int sindex, int dindex, NrnThread* _nt) {
    int idx;
    LongDifusThreadData** ppldtd = (LongDifusThreadData**)v;
    LongDifusThreadData* ldtd = *ppldtd;

    if (ldtd) {
        free(ldtd->ml);
        for (idx = 0; idx < ldtd->nthread; ++idx) {
            if (ldtd->ldifus[idx]) {
                longdifusfree(ldtd->ldifus + idx);
            }
        }
        free(ldtd->ldifus);
        free(ldtd);
        *ppldtd = (LongDifusThreadData*)0;
    }

    *ppldtd = (LongDifusThreadData*)emalloc(sizeof(LongDifusThreadData));
    ldtd = *ppldtd;
    ldtd->nthread = nrn_nthread;
    ldtd->ldifus = (LongDifus**)ecalloc(nrn_nthread, sizeof(LongDifus*));
    ldtd->ml = (Memb_list**)ecalloc(nrn_nthread, sizeof(Memb_list*));

    for (idx = 0; idx < nrn_nthread; ++idx) {
        NrnThreadMembList* tml;
        for (tml = nrn_threads[idx].tml; tml; tml = tml->next) {
            if (tml->index == m) {
                ldtd->ml[idx] = tml->ml;
                longdifusalloc(ldtd->ldifus + idx, m, sindex, tml->ml, nrn_threads + idx);
                break;
            }
        }
    }
}

static LongDifus* v2ld(void** v, int tid) {
    LongDifusThreadData** ppldtd = (LongDifusThreadData**)v;
    return (*ppldtd)->ldifus[tid];
}

static Memb_list* v2ml(void** v, int tid) {
    LongDifusThreadData** ppldtd = (LongDifusThreadData**)v;
    return (*ppldtd)->ml[tid];
}

static void stagger(int m, ldifusfunc3_t diffunc, void** v, int ai, int sindex, int dindex, NrnThread* _nt) {
    LongDifus* ld_ptr;
    int idx, node_count, di;
    double dc, vol, dfdi, dx;
    double** data;
    Datum** pdata;
    Datum* thread;
    Memb_list* ml;

    di = dindex + ai;
    ld_ptr = v2ld(v, _nt->id);
    if (!ld_ptr) return;

    ml = v2ml(v, _nt->id);
    node_count = ml->nodecount;
    data = ml->data;
    pdata = ml->pdata;
    thread = ml->_thread;

    longdifus_diamchange(ld_ptr, m, sindex, ml, _nt);

    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = ld_ptr->pindex[idx];
        int mi = ld_ptr->mindex[idx];
        ld_ptr->dc[idx] = (*diffunc)(ai, data[mi], pdata[mi], ld_ptr->vol + idx, &dfdi, thread, _nt);
        ld_ptr->d[idx] = 0.0;

        if (parent_idx > -1) {
            dc = (ld_ptr->dc[idx] + ld_ptr->dc[parent_idx]) * 0.5;
            ld_ptr->a[idx] = -ld_ptr->af[idx] * dc / ld_ptr->vol[parent_idx];
            ld_ptr->b[idx] = -ld_ptr->bf[idx] * dc / ld_ptr->vol[idx];
        }
    }

    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = ld_ptr->pindex[idx];
        int mi = ld_ptr->mindex[idx];
        ld_ptr->d[idx] += 1.0 / nt_dt;
        ld_ptr->rhs[idx] = ld_ptr->state[idx][ai] * (1.0 / nt_dt);

        if (parent_idx > -1) {
            ld_ptr->d[idx] -= ld_ptr->b[idx];
            ld_ptr->d[parent_idx] -= ld_ptr->a[idx];
        }
    }

    nrn_tree_solve(ld_ptr->a, ld_ptr->d, ld_ptr->b, ld_ptr->rhs, ld_ptr->pindex, node_count);

    for (idx = 0; idx < node_count; ++idx) {
        ld_ptr->state[idx][ai] = ld_ptr->rhs[idx];
    }
}

static void ode(int m, ldifusfunc3_t diffunc, void** v, int ai, int sindex, int dindex, NrnThread* _nt) {
    LongDifus* ld_ptr;
    int idx, node_count, di;
    double dc, vol, dfdi;
    double** data;
    Datum** pdata;
    Datum* thread;
    Memb_list* ml;

    di = dindex + ai;
    ld_ptr = v2ld(v, _nt->id);
    if (!ld_ptr) return;

    ml = v2ml(v, _nt->id);
    node_count = ml->nodecount;
    data = ml->data;
    pdata = ml->pdata;
    thread = ml->_thread;

    longdifus_diamchange(ld_ptr, m, sindex, ml, _nt);

    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = ld_ptr->pindex[idx];
        int mi = ld_ptr->mindex[idx];
        ld_ptr->dc[idx] = (*diffunc)(ai, data[mi], pdata[mi], ld_ptr->vol + idx, &dfdi, thread, _nt);

        if (parent_idx > -1) {
            dc = (ld_ptr->dc[idx] + ld_ptr->dc[parent_idx]) * 0.5;
            ld_ptr->a[idx] = ld_ptr->af[idx] * dc / ld_ptr->vol[parent_idx];
            ld_ptr->b[idx] = ld_ptr->bf[idx] * dc / ld_ptr->vol[idx];
        }
    }

    for (idx = 0; idx < node_count; ++idx) {
        double dif;
        int parent_idx = ld_ptr->pindex[idx];
        int mi = ld_ptr->mindex[idx];

        if (parent_idx > -1) {
            dif = (ld_ptr->state[parent_idx][ai] - ld_ptr->state[idx][ai]);
            data[mi][di] += dif * ld_ptr->b[idx];
            data[ld_ptr->mindex[parent_idx]][di] -= dif * ld_ptr->a[idx];
        }
    }
}

static void matsol(int m, ldifusfunc3_t diffunc, void** v, int ai, int sindex, int dindex, NrnThread* _nt) {
    LongDifus* ld_ptr;
    int idx, node_count, di;
    double dc, vol, dfdi;
    double** data;
    Datum** pdata;
    Datum* thread;
    Memb_list* ml;

    di = dindex + ai;
    ld_ptr = v2ld(v, _nt->id);
    if (!ld_ptr) return;

    ml = v2ml(v, _nt->id);
    node_count = ml->nodecount;
    data = ml->data;
    pdata = ml->pdata;
    thread = ml->_thread;

    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = ld_ptr->pindex[idx];
        int mi = ld_ptr->mindex[idx];
        ld_ptr->dc[idx] = (*diffunc)(ai, data[mi], pdata[mi], ld_ptr->vol + idx, &dfdi, thread, _nt);
        ld_ptr->d[idx] = 0.0;

        if (dfdi) {
            ld_ptr->d[idx] += fabs(dfdi) / ld_ptr->vol[idx] / ld_ptr->state[idx][ai];
        }

        if (parent_idx > -1) {
            dc = (ld_ptr->dc[idx] + ld_ptr->dc[parent_idx]) * 0.5;
            ld_ptr->a[idx] = -ld_ptr->af[idx] * dc / ld_ptr->vol[parent_idx];
            ld_ptr->b[idx] = -ld_ptr->bf[idx] * dc / ld_ptr->vol[idx];
        }
    }

    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = ld_ptr->pindex[idx];
        int mi = ld_ptr->mindex[idx];
        ld_ptr->d[idx] += 1.0 / nt_dt;
        ld_ptr->rhs[idx] = data[mi][di] * (1.0 / nt_dt);

        if (parent_idx > -1) {
            ld_ptr->d[idx] -= ld_ptr->b[idx];
            ld_ptr->d[parent_idx] -= ld_ptr->a[idx];
        }
    }

    // Triangularization
    for (idx = node_count - 1; idx > 0; --idx) {
        int parent_idx = ld_ptr->pindex[idx];
        if (parent_idx > -1) {
            double factor = ld_ptr->a[idx] / ld_ptr->d[idx];
            ld_ptr->d[parent_idx] -= factor * ld_ptr->b[idx];
            ld_ptr->rhs[parent_idx] -= factor * ld_ptr->rhs[idx];
        }
    }

    // Back substitution
    for (idx = 0; idx < node_count; ++idx) {
        int parent_idx = ld_ptr->pindex[idx];
        if (parent_idx > -1) {
            ld_ptr->rhs[idx] -= ld_ptr->b[idx] * ld_ptr->rhs[parent_idx];
        }
        ld_ptr->rhs[idx] /= ld_ptr->d[idx];
    }

    for (idx = 0; idx < node_count; ++idx) {
        int mi = ld_ptr->mindex[idx];
        data[mi][di] = ld_ptr->rhs[idx];
    }
}

#include <cstring>
