CompilerOptions* parseCompilerOptions(int argc, char** argv) {
    CompilerOptions* options = new CompilerOptions;

    // Extract source file information from the first argument
    options->mainSourceFileName = getFileName(argv[1]);
    options->mainSourceFilePath = getFileParentPath(argv[1]);
    options->compilationPath = argv[1];

    // Process command-line arguments starting from index 2
    for (int idx = 2; idx < argc; ++idx) {
        if (strcmp(argv[idx], COMPILER_NAME_FLAG) == 0 && idx + 1 < argc) {
            options->compilerName = argv[idx + 1];
            idx += 2;
            continue;
        }

        if (strcmp(argv[idx], OPTIMIZATION_FLAG) == 0 && idx + 1 < argc) {
            options->optimizationLevel = argv[idx + 1];
            idx += 2;
            continue;
        }

        if (strcmp(argv[idx], GENERATED_FILE_NAME_FLAG) == 0 && idx + 1 < argc) {
            options->generatedFileName = argv[idx + 1];
            idx += 2;
            continue;
        }

        if (strcmp(argv[idx], EXECUTABLE_NAME_FLAG) == 0 && idx + 1 < argc) {
            options->executableFileName = argv[idx + 1];
            idx += 2;
            continue;
        }

        if (strcmp(argv[idx], GENERATE_RUN_EXECUTABLE_FLAG) == 0) {
            options->generateExecutable = true;
            options->runExecutable = true;
            continue;
        }

        if (strcmp(argv[idx], GENERATE_EXECUTABLE_FLAG) == 0) {
            options->generateExecutable = true;
            continue;
        }
    }

    return options;
}

void parseCompilerFlags(char* flag) {
    if (strcmp(flag, COMPILER_HELP_FLAG) == 0) {
        std::cout << "Done is compiler to generate C" << std::endl;
        std::cout << "Usage:" << std::endl;
        std::cout << "    donec <source file> <options>" << std::endl;
        exit(EXIT_SUCCESS);
    }

    if (strcmp(flag, COMPILER_VERSION_FLAG) == 0) {
        std::cout << "Done Compiler version is 1.0.0" << std::endl;
        exit(EXIT_SUCCESS);
    }
}

