// Convert a date string in 'YYYY-MM-DD HH:MM:SS' format to Unix timestamp
time_t convertDateStringToUnixTime(const std::string& dateString) {
    // Extract components from the formatted string
    int y = std::stoi(dateString.substr(0, 4));
    int m = std::stoi(dateString.substr(5, 2));
    int d = std::stoi(dateString.substr(8, 2));
    int h = std::stoi(dateString.substr(11, 2));
    int min = std::stoi(dateString.substr(14, 2));
    int s = std::stoi(dateString.substr(17, 2));

    // Populate tm structure with adjusted values (year since 1900, month 0-based, day 1-based)
    struct tm timeInfo = {};
    timeInfo.tm_year = y - 1900;
    timeInfo.tm_mon = m - 1;
    timeInfo.tm_mday = d;
    timeInfo.tm_hour = h;
    timeInfo.tm_min = min;
    timeInfo.tm_sec = s;

    // Convert to time_t (local time zone assumed)
    time_t result = mktime(&timeInfo);
    return result;
}

