// Populate attribute list with current values
void GridSettings::getAttributeList(const std::string &prefix, T::AttributeList &attributeList) const {
  try {
    char buffer[300];

    snprintf(buffer, sizeof(buffer), "%sGridSettings.Ni", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mNi));

    snprintf(buffer, sizeof(buffer), "%sGridSettings.Nj", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mNj));

    snprintf(buffer, sizeof(buffer), "%sGridSettings.BasicAngleOfTheInitialProductionDomain", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mBasicAngleOfTheInitialProductionDomain));

    snprintf(buffer, sizeof(buffer), "%sGridSettings.SubdivisionsOfBasicAngle", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mSubdivisionsOfBasicAngle));

    snprintf(buffer, sizeof(buffer), "%sGridSettings.LatitudeOfFirstGridPoint", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mLatitudeOfFirstGridPoint));

    snprintf(buffer, sizeof(buffer), "%sGridSettings.LongitudeOfFirstGridPoint", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mLongitudeOfFirstGridPoint));

    std::string resolutionPrefix = prefix + "GridSettings.";
    mResolution.getAttributeList(resolutionPrefix, attributeList);

    snprintf(buffer, sizeof(buffer), "%sGridSettings.LatitudeOfLastGridPoint", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mLatitudeOfLastGridPoint));

    snprintf(buffer, sizeof(buffer), "%sGridSettings.LongitudeOfLastGridPoint", prefix.c_str());
    attributeList.addAttribute(buffer, toString(mLongitudeOfLastGridPoint));
  } catch (...) {
    throw Fmi::Exception(BCP, "Failed to get attribute list", nullptr);
  }
}

// Retrieve attribute value by name
bool GridSettings::getAttributeValue(const char *attrName, std::string &attrValue) const {
  try {
    if (!attrName)
      return false;

    if (strcasecmp(attrName, "Ni") == 0) {
      attrValue = toString(mNi);
      return true;
    }
    if (strcasecmp(attrName, "Nj") == 0) {
      attrValue = toString(mNj);
      return true;
    }
    if (strcasecmp(attrName, "BasicAngleOfTheInitialProductionDomain") == 0) {
      attrValue = toString(mBasicAngleOfTheInitialProductionDomain);
      return true;
    }
    if (strcasecmp(attrName, "SubdivisionsOfBasicAngle") == 0) {
      attrValue = toString(mSubdivisionsOfBasicAngle);
      return true;
    }
    if (strcasecmp(attrName, "LatitudeOfFirstGridPoint") == 0) {
      attrValue = toString(mLatitudeOfFirstGridPoint);
      return true;
    }
    if (strcasecmp(attrName, "LongitudeOfFirstGridPoint") == 0) {
      attrValue = toString(mLongitudeOfFirstGridPoint);
      return true;
    }
    if (mResolution.getAttributeValue(attrName, attrValue))
      return true;
    if (strcasecmp(attrName, "LatitudeOfLastGridPoint") == 0) {
      attrValue = toString(mLatitudeOfLastGridPoint);
      return true;
    }
    if (strcasecmp(attrName, "LongitudeOfLastGridPoint") == 0) {
      attrValue = toString(mLongitudeOfLastGridPoint);
      return true;
    }

    return false;
  } catch (...) {
    throw Fmi::Exception(BCP, "Failed to get attribute value", nullptr);
  }
}

// Check if attribute matches given value
bool GridSettings::hasAttributeValue(const char *attrName, const char *attrValue) const {
  try {
    if (!attrName || !attrValue)
      return false;

    if (strcasecmp(attrName, "Ni") == 0 && strcasecmp(attrValue, toString(mNi).c_str()) == 0)
      return true;
    if (strcasecmp(attrName, "Nj") == 0 && strcasecmp(attrValue, toString(mNj).c_str()) == 0)
      return true;
    if (strcasecmp(attrName, "BasicAngleOfTheInitialProductionDomain") == 0 && 
        strcasecmp(attrValue, toString(mBasicAngleOfTheInitialProductionDomain).c_str()) == 0)
      return true;
    if (strcasecmp(attrName, "SubdivisionsOfBasicAngle") == 0 && 
        strcasecmp(attrValue, toString(mSubdivisionsOfBasicAngle).c_str()) == 0)
      return true;
    if (strcasecmp(attrName, "LatitudeOfFirstGridPoint") == 0 && 
        strcasecmp(attrValue, toString(mLatitudeOfFirstGridPoint).c_str()) == 0)
      return true;
    if (strcasecmp(attrName, "LongitudeOfFirstGridPoint") == 0 && 
        strcasecmp(attrValue, toString(mLongitudeOfFirstGridPoint).c_str()) == 0)
      return true;
    if (mResolution.hasAttributeValue(attrName, attrValue))
      return true;
    if (strcasecmp(attrName, "LatitudeOfLastGridPoint") == 0 && 
        strcasecmp(attrValue, toString(mLatitudeOfLastGridPoint).c_str()) == 0)
      return true;
    if (strcasecmp(attrName, "LongitudeOfLastGridPoint") == 0 && 
        strcasecmp(attrValue, toString(mLongitudeOfLastGridPoint).c_str()) == 0)
      return true;

    return false;
  } catch (...) {
    throw Fmi::Exception(BCP, "Failed to check attribute value", nullptr);
  }
}

