  }
}

// Compute hash for the object
T::Hash GridSettings::countHash() const {
  try {
    std::size_t hashSeed = 0;

    if (mNi)
      boost::hash_combine(hashSeed, *mNi);
    if (mNj)
      boost::hash_combine(hashSeed, *mNj);
    if (mLatitudeOfFirstGridPoint)
      boost::hash_combine(hashSeed, *mLatitudeOfFirstGridPoint);
    if (mLongitudeOfFirstGridPoint)
      boost::hash_combine(hashSeed, *mLongitudeOfFirstGridPoint);

    return static_cast<T::Hash>(hashSeed);
  } catch (...) {
    throw Fmi::Exception(BCP, "Failed to compute hash", nullptr);
  }
}

