void AudioNode::init()
{
    CK_ASSERT(nullptr == s_pool);

    // Determine sample rate based on platform
    int nativeRate = 0;
#if CK_PLATFORM_ANDROID
    nativeRate = Audio::getNativeSampleRate();
#elif CK_PLATFORM_IOS || CK_PLATFORM_TVOS || CK_PLATFORM_OSX
    nativeRate = Audio::getSessionSampleRate();
#else
    nativeRate = k_maxSampleRate; // fallback for unsupported platforms
#endif
    s_sampleRate = nativeRate;

    // Compute buffer size in frames
    const float updateMs = System::get()->getConfig().audioUpdateMs;
    int frameCount = static_cast<int>(s_sampleRate * updateMs * 0.001f);
    frameCount <<= 1; // double buffer size to accommodate up to 2x playback speed at 48kHz

    s_pool = new BufferPool(k_maxChannels * frameCount);
}

void AudioNode::shutdown()
{
    CK_ASSERT(nullptr != s_pool);
    delete s_pool;
    s_pool = nullptr;
}

