void AudioNode::printImpl(int depth, const char* label)
{
    for (int i = 0; i < depth; ++i)
    {
        CK_PRINT("  ");
    }
    CK_PRINT("%p %s\n", this, label);
}
#endif

BufferPool* AudioNode::s_pool = nullptr;
int AudioNode::s_sampleRate = k_maxSampleRate;

////////////////////////////////////////
void AudioNode::setVolumeRampTime(float durationMs)
{
    s_volRampTime = durationMs;
}

float AudioNode::getVolumeRampTime()
{
    return s_volRampTime;
}

float AudioNode::getVolumeRate()
{
    // If ramp time is zero or negligible, use fast (instantaneous) interpolation
    if (s_volRampTime <= 0.0f || s_volRampTime <= 1.0f / s_sampleRate)
    {
        return 10.0f;
    }

    // Otherwise compute per-frame interpolation step
    const float secondsPerFrame = 1000.0f / s_sampleRate;
    return 1.0f / (s_volRampTime * secondsPerFrame);
}

float AudioNode::s_volRampTime = Ck_volumeRampTimeMsDefault;

