        void to_string::operator()(bool val) const
        {
            out_ << std::boolalpha << val;
        }

        void to_string::operator()(std::string const& str) const
        {
            if (util::is_repr(out_))
            {
                out_ << "\"";
                for (char c : str)
                {
                    switch (c)
                    {
                    case '\b':  out_ << "\\b"; break;
                    case '\n':  out_ << "\\n"; break;
                    case '\r':  out_ << "\\r"; break;
                    case '\t':  out_ << "\\t"; break;
                    case '\\':  out_ << "\\\\"; break;
                    case '\"':  out_ << "\\\""; break;
                    default:    out_ << c;
                    }
                }
                out_ << "\"";
            }
            else
            {
                out_ << str;
            }
        }
    }

    std::ostream& operator<<(std::ostream& out, primary_expr const& pe)
    {
        util::visit(detail::to_string{out}, pe.get());
        return out;
    }

    std::ostream& operator<<(std::ostream& out, operand const& op)
    {
        util::visit(detail::to_string{out}, op.get());
        return out;
    }

    std::ostream& operator<<(std::ostream& out, unary_expr const& ue)
    {
        out << ue.op_code << ue.operand_;
        return out;
    }

    std::ostream& operator<<(std::ostream& out, operation const& op)
    {
        out << " " << op.op_code << " " << op.operand_;
        return out;
    }

    std::ostream& operator<<(std::ostream& out, expression const& expr)
    {
        if (!expr.tail.empty())
        {
            out << "(";
        }
        out << expr.head;
        if (!expr.tail.empty())
        {
            for (auto const& op : expr.tail)
                out << op;
            out << ")";
        }
        return out;
    }

    std::ostream& operator<<(std::ostream& out, function_call const& f)
    {
        out << f.target_name << "(";
        bool first = true;
        for (auto const& arg : f.arguments)
        {
            if (!first)
            {
                out << ", ";
            }
            first = false;
            out << arg;
        }
        out << ")";
        return out;
    }

    std::ostream& operator<<(
        std::ostream& out, std::vector<ast::expression> const& list)
    {
        out << "list(";
        bool first = true;
        for (auto const& item : list)
        {
            if (!first)
            {
                out << ", ";
            }
            first = false;
            out << item;
        }
        out << ")";
        return out;
    }

    std::string to_string(expression const& expr)
    {
        std::ostringstream stream;
        stream << expr;
        return stream.str();
    }
}}

