BOOL
IsVirtualAddressValid(
    PVOID pAddress,
    PBOOL pValid
)
{
    PSAPI_WORKING_SET_EX_INFORMATION wsInfo = {};
    BOOL result = TRUE;

    // Initialize output parameter to false
    *pValid = FALSE;

    // Prepare structure for querying working set information
    wsInfo.VirtualAddress = pAddress;

    // Query process working set extended information
    result = QueryWorkingSetEx(
        GetCurrentProcess(),
        &wsInfo,
        sizeof(wsInfo));

    if (!result)
    {
        DWORD errCode = GetLastError();
        fprintf(stderr, "QueryWorkingSetEx error: %lu\n", errCode);
        goto cleanup;
    }

    // Update validity flag based on PTE status
    if (wsInfo.VirtualAttributes.Valid)
    {
        *pValid = TRUE;
    }

cleanup:
    return result;
}

