#include <vector>
#include <queue>

class Solution {
public:
    std::vector<int> findMinHeightTrees(int totalNodes, std::vector<std::vector<int>>& connections) {
        // Build adjacency list using vector of vectors
        std::vector<std::vector<int>> adjacencyList(totalNodes);
        std::vector<int> degree(totalNodes, 0);

        // Populate adjacency list and calculate degrees
        for (const auto& conn : connections) {
            int nodeA = conn[0];
            int nodeB = conn[1];
            adjacencyList[nodeA].push_back(nodeB);
            adjacencyList[nodeB].push_back(nodeA);
            degree[nodeA]++;
            degree[nodeB]++;
        }

        // Track remaining nodes count
        int remainingNodes = totalNodes;

        // Iteratively remove leaves until we have 1 or 2 nodes left
        while (remainingNodes > 2) {
            std::vector<int> currentLeaves;

            // Find all current leaves (degree == 1)
            for (int node = 0; node < totalNodes; ++node) {
                if (degree[node] == 1) {
                    currentLeaves.push_back(node);
                    degree[node] = -1;  // Mark as removed
                    remainingNodes--;
                }
            }

            // Update degrees of neighbors
            for (int leaf : currentLeaves) {
                for (int neighbor : adjacencyList[leaf]) {
                    if (degree[neighbor] != -1) {
                        degree[neighbor]--;
                    }
                }
            }
        }

        // Collect remaining nodes (potential roots of MHTs)
        std::vector<int> result;
        for (int node = 0; node < totalNodes; ++node) {
            if (degree[node] >= 0) {  // Nodes that weren't removed
                result.push_back(node);
            }
        }

        return result;
    }
};

#include <string>
#include <cmath>

class Solution {
public:
    std::string smallestGoodBase(std::string numStr) {
        unsigned long long targetNum = std::stoull(numStr);

        // Start checking from the longest possible base representation (62 digits)
        for (int length = 62; length >= 1; --length) {
            // Early pruning: if 2^length is already greater than targetNum, skip
            if ((1ULL << length) > targetNum && length > 1) continue;

            unsigned long long base = findValidBase(targetNum, length);
            if (base != 0) {
                return std::to_string(base);
            }
        }

        // If no smaller base found, the answer is always n-1 (for base n-1, number becomes "11")
        return std::to_string(targetNum - 1);
    }

private:
    unsigned long long findValidBase(unsigned long long n, int digits) {
        // Binary search for the base that gives sum = 1 + b + b^2 + ... + b^(d-1) = n
        unsigned long long low = 2;
        unsigned long long high = static_cast<unsigned long long>(std::pow(n, 1.0 / (digits - 1))) + 1;

        while (low <= high) {
            unsigned long long base = low + (high - low) / 2;
            unsigned long long total = 1;
            unsigned long long power = 1;

            // Calculate 1 + base + base^2 + ... + base^(digits-1)
            for (int i = 0; i < digits; ++i) {
                if (i > 0) {
                    power *= base;
                    total += power;
                    // Early termination if sum exceeds n
                    if (total > n) break;
                }
            }

            if (total == n) {
                return base;
            } else if (total > n) {
                high = base - 1;
            } else {
                low = base + 1;
            }
        }

        return 0;
    }
};

