using namespace snmalloc;

// Custom allocator configuration using fixed global state
using CustomGlobals = FixedGlobals<PALNoAlloc<DefaultPal>>;
using FixedAlloc = LocalAllocator<CustomGlobals>;

int main()
{
#ifndef SNMALLOC_PASS_THROUGH // Requires snmalloc-specific functionality
  setup();

  // Reserve a memory region large enough to trigger nested allocator behavior
  // Using 2^28 bytes (256 MiB) ensures sufficient space for testing
  size_t region_size = bits::one_at_bit(28);
  void* region_start = Pal::reserve(region_size);
  Pal::notify_using<NoZero>(region_start, region_size);
  void* region_end = pointer_offset(region_start, region_size);

  std::cout << "Memory region: " << region_start << " to "
            << region_end << std::endl;

  // Initialize custom allocator with reserved region
  CustomGlobals::init(nullptr, region_start, region_size);
  FixedAlloc allocator;

  size_t allocation_size = 128;
  size_t total_bytes_allocated = 0;
  size_t iteration_count = 0;

  while (true)
  {
    void* allocated_ptr = allocator.alloc(allocation_size);

    if (allocated_ptr != nullptr)
    {
      total_bytes_allocated += allocation_size;
    }

    iteration_count++;

    // Progress indicator every 1024 allocations
    if (iteration_count % 1024 == 0)
    {
      std::cout << ".";
      std::cout.flush();
    }

    // Stop when allocation fails (region exhausted)
    if (allocated_ptr == nullptr)
      break;

    // Verify allocation stays within reserved bounds
    if (allocated_ptr < region_start || allocated_ptr >= region_end)
    {
      std::cerr << "Allocation out of bounds: " << allocated_ptr << std::endl;
      abort();
    }
  }

  // Report statistics
  std::cout << "\nTotal allocated: " << total_bytes_allocated 
            << " bytes out of " << region_size << std::endl;

  double overhead_ratio = static_cast<double>(region_size) / 
                          static_cast<double>(region_size - total_bytes_allocated);
  std::cout << "Overhead factor: 1/" << overhead_ratio << std::endl;

  allocator.teardown();
#endif
}

#include <stdio.h>
#include "StackBlurFilter.h"

// Helper function to compute minimum of two integers
static inline int min_val(int a, int b) {
    return (a < b) ? a : b;
}

// Helper function to compute maximum of two integers
static inline int max_val(int a, int b) {
    return (a > b) ? a : b;
}

void doHorizontalBlur(uint32_t *pix, int w, int h, int radius, int startX, int startY, int deltaX, int deltaY);
void doVerticalBlur(uint32_t *pix, int w, int h, int radius, int startX, int startY, int deltaX, int deltaY);

void stackBlur(uint32_t *pixels, int radius, int cores, int index, int direction, int w, int h) {
    using namespace hokoblur;
    if (nullptr == pixels) {
        return;
    }

    if (HORIZONTAL == direction) {
        int deltaY = h / cores;
        int startY = index * deltaY;
        if (index == cores - 1) {
            deltaY = h - (cores - 1) * deltaY;
        }
        doHorizontalBlur(pixels, w, h, radius, 0, startY, w, deltaY);
    } else if (VERTICAL == direction) {
        int deltaX = w / cores;
        int startX = index * deltaX;
        if (index == cores - 1) {
            deltaX = w - (cores - 1) * (w / cores);
        }
        doVerticalBlur(pixels, w, h, radius, startX, 0, deltaX, h);
    }
}

void doHorizontalBlur(uint32_t *pix, int w, int h, int radius, int startX, int startY, int deltaX, int deltaY) {
    const int wm = w - 1;
    const int div = radius + radius + 1;
    int rsum, gsum, bsum, x, y, i, p, yi;

    // Allocate and initialize lookup table for division
    int *vmin = (int *)malloc(sizeof(int) * max_val(w, h));
    const int divsum = ((div + 1) >> 1) * div;
    short *dv = (short *)malloc(sizeof(short) * 256 * divsum);

    for (i = 0; i < 256 * divsum; ++i) {
        dv[i] = static_cast<short>(i / divsum);
    }

    // Stack allocation: [div][3]
    int (*stack)[3] = (int (*)[3])malloc(sizeof(int) * div * 3);

    int stackpointer;
    int stackstart;
    int *sir;
    int rbs;
    const int r1 = radius + 1;
    int routsum, goutsum, boutsum;
    int rinsum, ginsum, binsum;

    const int endX = startX + deltaX;
    const int endY = startY + deltaY;

    for (y = startY; y < endY; ++y) {
        rinsum = ginsum = binsum = routsum = goutsum = boutsum = 
        rsum = gsum = bsum = 0;

        const int baseIndex = y * w;

        // Initialize the stack with initial pixels
        for (i = -radius; i <= radius; ++i) {
            int idx = min_val(wm, max_val(startX, i + startX));
            p = pix[baseIndex + idx];

            sir = stack[i + radius];
            sir[0] = (p & 0xff0000) >> 16;
            sir[1] = (p & 0x00ff00) >> 8;
            sir[2] = (p & 0x0000ff);

            rbs = r1 - abs(i);
            rsum += sir[0] * rbs;
            gsum += sir[1] * rbs;
            bsum += sir[2] * rbs;

            if (i > 0) {
                rinsum += sir[0];
                ginsum += sir[1];
                binsum += sir[2];
            } else {
                routsum += sir[0];
                goutsum += sir[1];
                boutsum += sir[2];
            }
        }

        stackpointer = radius;
        yi = baseIndex + startX;

        for (x = startX; x < endX; ++x) {
            // Write blurred pixel value
            pix[yi] = (0xff000000 & pix[yi]) | (dv[rsum] << 16) | (dv[gsum] << 8) | dv[bsum];

            // Remove oldest element from sums
            rsum -= routsum;
            gsum -= goutsum;
            bsum -= boutsum;

            // Update stack pointer and retrieve next element
            stackstart = (stackpointer - radius + div) % div;
            sir = stack[stackstart];
            routsum -= sir[0];
            goutsum -= sir[1];
            boutsum -= sir[2];

            // Determine next pixel to add to stack
            vmin[x] = min_val(x + radius + 1, wm);
            p = pix[baseIndex + vmin[x]];
            sir[0] = (p & 0xff0000) >> 16;
            sir[1] = (p & 0x00ff00) >> 8;
            sir[2] = (p & 0x0000ff);

            // Add new values to running sums
            rinsum += sir[0];
            ginsum += sir[1];
            binsum += sir[2];
            rsum += rinsum;
            gsum += ginsum;
            bsum += binsum;

            // Advance stack pointer
            stackpointer = (stackpointer + 1) % div;
            sir = stack[stackpointer];
            routsum += sir[0];
            goutsum += sir[1];
            boutsum += sir[2];
            rinsum -= sir[0];
            ginsum -= sir[1];
            binsum -= sir[2];

            ++yi;
        }
    }

    free(dv);
    free(stack);
    free(vmin);
}

void doVerticalBlur(uint32_t *pix, int w, int h, int radius, int startX, int startY, int deltaX, int deltaY) {
    const int hm = h - 1;
    const int hmw = hm * w;
    const int div = radius + radius + 1;
    int rsum, gsum, bsum, x, y, i, p, yi;

    int *vmin = (int *)malloc(sizeof(int) * max_val(w, h));
    const int divsum = ((div + 1) >> 1) * div;
    short *dv = (short *)malloc(sizeof(short) * 256 * divsum);

    for (i = 0; i < 256 * divsum; ++i) {
        dv[i] = static_cast<short>(i / divsum);
    }

    int (*stack)[3] = (int (*)[3])malloc(sizeof(int) * div * 3);

    int stackpointer;
    int stackstart;
    int *sir;
    int rbs;
    const int r1 = radius + 1;
    int routsum, goutsum, boutsum;
    int rinsum, ginsum, binsum;

    const int endX = startX + deltaX;
    const int endY = startY + deltaY;

    for (x = startX; x < endX; ++x) {
        rinsum = ginsum = binsum = routsum = goutsum = boutsum = 
        rsum = gsum = bsum = 0;

        const int baseIndex = startY * w;

        // Initialize vertical stack
        for (i = -radius; i <= radius; ++i) {
            int offset = min_val(hmw, max_val(baseIndex + i * w, baseIndex)) + x;
            p = pix[offset];

            sir = stack[i + radius];
            sir[0] = (p & 0xff0000) >> 16;
            sir[1] = (p & 0x00ff00) >> 8;
            sir[2] = (p & 0x0000ff);

            rbs = r1 - abs(i);
            rsum += sir[0] * rbs;
            gsum += sir[1] * rbs;
            bsum += sir[2] * rbs;

            if (i > 0) {
                rinsum += sir[0];
                ginsum += sir[1];
                binsum += sir[2];
            } else {
                routsum += sir[0];
                goutsum += sir[1];
                boutsum += sir[2];
            }
        }

        stackpointer = radius;
        yi = baseIndex + x;

        for (y = startY; y < endY; ++y) {
            pix[yi] = (0xff000000 & pix[yi]) | (dv[rsum] << 16) | (dv[gsum] << 8) | dv[bsum];

            rsum -= routsum;
            gsum -= goutsum;
            bsum -= boutsum;

            stackstart = (stackpointer - radius + div) % div;
            sir = stack[stackstart];
            routsum -= sir[0];
            goutsum -= sir[1];
            boutsum -= sir[2];

            vmin[y] = min_val(y + radius + 1, hm);
            p = pix[vmin[y] * w + x];
            sir[0] = (p & 0xff0000) >> 16;
            sir[1] = (p & 0x00ff00) >> 8;
            sir[2] = (p & 0x0000ff);

            rinsum += sir[0];
            ginsum += sir[1];
            binsum += sir[2];
            rsum += rinsum;
            gsum += ginsum;
            bsum += binsum;

            stackpointer = (stackpointer + 1) % div;
            sir = stack[stackpointer];
            routsum += sir[0];
            goutsum += sir[1];
            boutsum += sir[2];
            rinsum -= sir[0];
            ginsum -= sir[1];
            binsum -= sir[2];

            yi += w;
        }
    }

    free(dv);
    free(stack);
    free(vmin);
}

#include <vector>
#include <set>
#include <algorithm>
#include <climits>

class Solution {
public:
    int coinChange(std::vector<int>& coins, int amount) {
        if (amount == 0) return 0;

        std::vector<int> minCoins(amount + 1, INT_MAX);
        minCoins[amount] = 0;

        std::set<int> pendingAmounts;
        pendingAmounts.insert(amount);

        std::sort(coins.begin(), coins.end());

        for (int coinIndex = coins.size() - 1; coinIndex >= 0; --coinIndex) {
            int currentCoin = coins[coinIndex];

            // Process all amounts in reverse order
            for (auto it = pendingAmounts.rbegin(); it != pendingAmounts.rend(); ++it) {
                int currentAmount = *it;

                // Try to use current coin to reach a smaller amount
                int nextAmount = currentAmount - currentCoin;

                if (nextAmount >= 0 && minCoins[currentAmount] != INT_MAX) {
                    if (minCoins[nextAmount] > minCoins[currentAmount] + 1) {
                        minCoins[nextAmount] = minCoins[currentAmount] + 1;
                        pendingAmounts.insert(nextAmount);
                    }
                }
            }
        }

        return (minCoins[0] == INT_MAX) ? -1 : minCoins[0];
    }
};

