void JayDImpl::initializeSystem() {
    // Initialize PSRAM if available
    if (psramFound()) {
        bool psramOk = psramInit();
        Serial.printf("PSRAM setup: %s, remaining: %d B\n", psramOk ? "Success" : "Failed", ESP.getFreePsram());
    } else {
        Serial.println("No PSRAM found");
    }

    // Disable watchdog timers on both cores to prevent unexpected resets
    disableCore0WDT();
    disableCore1WDT();

    // Power down wireless subsystems to reduce interference and power usage
    WiFi.mode(WIFI_OFF);
    btStop();

    // Configure SPI bus for peripherals (e.g., SD card, display)
    SPI.begin(SPI_SCK, SPI_MISO, SPI_MOSI, SPI_SS);
    SPI.setFrequency(60000000);

    // Attempt to mount SD card filesystem
    if (!SD.begin(SD_CS, SPI)) {
        Serial.println("SD card not detected");
    }

    // Mount SPIFFS for file storage
    if (!SPIFFS.begin()) {
        Serial.println("SPIFFS initialization failed");
    }

    // Initialize main display
    display.begin();
    SPI.setFrequency(20000000); // Lower frequency for OLED/I2C devices

    // Start LED matrix controller
    if (!screenMatrix.begin(I2C_SDA, I2C_SCL)) {
        Serial.println("Failed to initialize LED matrix");
    }

    // Register loop listeners for periodic tasks
    LoopManager::addListener(&Sched);
    LoopManager::addListener(&matrixController);
    LoopManager::addListener(new InputJayD());

    // Initialize input handler singleton
    InputJayD::getInstance()->setup();

    // Load user settings from persistent storage
    Settings.begin();

    // Apply brightness setting with scaling factor
    float brightnessScale = static_cast<float>(Settings.get().brightnessLevel) / 255.0f;
    screenMatrix.setBrightness(80.0f * brightnessScale);
}

