    // Handle special URLs using a dispatch table approach
    struct RouteEntry {
        const char* pattern;
        bool exactMatch;
        CefRefPtr<CefStreamReader> (*loader)(int resId);
        int resourceId;
        const char* mimeType;
    };

    static const RouteEntry routes[] = {
        {"http://tests/request", true, nullptr, 0, "text/plain"},
        {"/ps_logo2.png", false, GetBinaryResourceReader, IDS_LOGO, "image/png"},
        {"http://tests/uiapp", true, GetBinaryResourceReader, IDS_UIPLUGIN, "text/html"},
        {"http://tests/osrapp", true, GetBinaryResourceReader, IDS_OSRPLUGIN, "text/html"},
        {"http://tests/localstorage", true, GetBinaryResourceReader, IDS_LOCALSTORAGE, "text/html"},
        {"http://tests/xmlhttprequest", true, GetBinaryResourceReader, IDS_XMLHTTPREQUEST, "text/html"},
        {"http://tests/domaccess", true, GetBinaryResourceReader, IDS_DOMACCESS, "text/html"},
        {"/logoball.png", false, GetBinaryResourceReader, IDS_LOGOBALL, "image/png"},
        {"http://tests/modalmain", true, GetBinaryResourceReader, IDS_MODALMAIN, "text/html"},
        {"http://tests/modaldialog", true, GetBinaryResourceReader, IDS_MODALDIALOG, "text/html"},
        {"http://tests/transparency", true, GetBinaryResourceReader, IDS_TRANSPARENCY, "text/html"}
    };

    size_t numRoutes = sizeof(routes) / sizeof(routes[0]);
    for (size_t i = 0; i < numRoutes; ++i) {
        const RouteEntry& entry = routes[i];
        bool matched = entry.exactMatch ? (url == entry.pattern)
                                        : ContainsSubstring(url, entry.pattern);

        if (matched) {
            if (entry.loader && entry.resourceId > 0) {
                resourceStream = entry.loader(entry.resourceId);
            } else if (url == "http://tests/request") {
                std::string dump;
                DumpRequestContents(request, dump);
                resourceStream = CefStreamReader::CreateForData(
                    const_cast<char*>(dump.c_str()), dump.size());
            } else if (url == "http://tests/plugin") {
                std::string html =
                    "<html><body>\n"
                    "Client Plugin loaded by Mime Type:<br>\n"
                    "<embed type=\"application/x-client-plugin\" width=600 height=40>\n"
                    "<br><br>Client Plugin loaded by File Extension:<br>\n"
                    "<embed src=\"test.xcp\" width=600 height=40>\n"
                    "<div style=\"height:1000px;\">&nbsp;</div>\n"
                    "</body></html>";
                resourceStream = CefStreamReader::CreateForData(
                    const_cast<char*>(html.c_str()), html.size());
            }

            ConfigureResourceResponse(response, entry.mimeType);
            return false;
        }
    }

    return false;
}

