{
    namespace Internal
    {
        bool ParseMapsLine(const std::string& line,
                           uintptr_t& startAddr,
                           uintptr_t& endAddr,
                           char& readPerm,
                           char& writePerm,
                           char& execPerm,
                           char& shareType,
                           unsigned long& inodeNum,
                           std::string& path)
        {
            std::istringstream iss(line);
            std::string range;
            char perms[5];
            char dummy[8]; // skip offset
            char dev[6];   // skip dev
            unsigned long ino;
            std::string filepath;

            if (!(iss >> range >> perms >> dummy >> dev >> ino >> filepath))
                return false;

            // Parse address range like "08048000-08049000"
            auto dashPos = range.find('-');
            if (dashPos == std::string::npos)
                return false;

            try {
                startAddr = std::stoul(range.substr(0, dashPos), nullptr, 16);
                endAddr   = std::stoul(range.substr(dashPos + 1), nullptr, 16);
            } catch (...) {
                return false;
            }

            if (strlen(perms) != 4)
                return false;

            readPerm   = perms[0];
            writePerm  = perms[1];
            execPerm   = perms[2];
            shareType  = perms[3];

            inodeNum   = ino;
            path       = filepath;

            return true;
        }

        bool IsHeapMapping(const std::string& path, unsigned long inode)
        {
            return path == "[heap]" && inode == 0;
        }

        bool IsAlignedToPageSize(uintptr_t addr, size_t pageSize)
        {
            return (addr & (pageSize - 1)) == 0;
        }
    }

    void ModifyKSM(bool enable)
    {
        static const size_t PAGE_SIZE = static_cast<size_t>(getpagesize());

        std::ifstream mapsFile("/proc/self/maps");
        if (!mapsFile.is_open()) {
            Msg("Failed to open '/proc/self/maps': %s\n", strerror(errno));
            return;
        }

        std::string line;
        while (std::getline(mapsFile, line)) {
            uintptr_t regionStart = 0;
            uintptr_t regionEnd   = 0;
            char r, w, x, s;
            unsigned long inode = 0;
            std::string filePath;

            if (!Internal::ParseMapsLine(line, regionStart, regionEnd, r, w, x, s, inode, filePath)) {
                continue;
            }

            if (!Internal::IsHeapMapping(filePath, inode)) {
                continue;
            }

            if (!Internal::IsAlignedToPageSize(regionStart, PAGE_SIZE) ||
                !Internal::IsAlignedToPageSize(regionEnd, PAGE_SIZE)) {
                continue;
            }

            if (regionStart >= regionEnd) {
                continue;
            }

            if (s != 'p') {
                continue;
            }

            size_t regionSize = regionEnd - regionStart;
            int advice = enable ? MADV_MERGEABLE : MADV_UNMERGEABLE;

            Msg("madvise(0x%08lx, 0x%08zx, MADV_%sMERGEABLE)\n",
                regionStart, regionSize, enable ? "" : "UN");

            if (madvise(reinterpret_cast<void*>(regionStart), regionSize, advice) < 0) {
                Msg("madvise failed: %s\n", strerror(errno));
            }
        }
    }

    CON_COMMAND(sig_util_heap_ksm_enable, "Utility: enable Kernel Samepage Merging for all private anonymous mappings")
    {
        ModifyKSM(true);
    }

    CON_COMMAND(sig_util_heap_ksm_disable, "Utility: disable Kernel Samepage Merging for all private anonymous mappings")
    {
        ModifyKSM(false);
    }

