// __________________________________________________________________________________________
// Name			: AEInit
// Input		: None
// Output		: OSErr: error status if initialization fails
// Description	: Registers handlers for standard Apple Events: open app, open docs, print, quit,
//				  plus custom 'reqd' and 'c2ci' events, and sets up OSL object accessors.
OSErr AEInit()
{
	OSErr result = noErr;
	AEEventHandlerUPP openAppHandler;
	AEEventHandlerUPP openDocHandler;
	AEEventHandlerUPP printDocHandler;
	AEEventHandlerUPP quitAppHandler;
	AEEventHandlerUPP insertIconHandler;
	OSLAccessorUPP	fileObjectHandler;

	openAppHandler = NewAEEventHandlerProc(AEOpenApp);
	openDocHandler = NewAEEventHandlerProc(AEOpenDoc);
	printDocHandler = NewAEEventHandlerProc(AEPrintDoc);
	quitAppHandler = NewAEEventHandlerProc(AEQuitApp);
	insertIconHandler = NewAEEventHandlerProc(AEInsertIcon);
	fileObjectHandler = NewOSLAccessorProc(FileObjectAccessor);

	result = AEInstallEventHandler(kCoreEventClass, kAEOpenApplication, openAppHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler(kCoreEventClass, kAEOpenDocuments, openDocHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler(kCoreEventClass, kAEPrintDocuments, printDocHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler(kCoreEventClass, kAEQuitApplication, quitAppHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEOpenApplication, openAppHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEOpenDocuments, openDocHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEPrintDocuments, printDocHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('reqd', kAEQuitApplication, quitAppHandler, 0L, false);
	if (result == noErr)
		result = AEInstallEventHandler('c2ci', 'insr', insertIconHandler, 0L, false);
	if (result == noErr)
		result = AEObjectInit();
	if (result == noErr)
		result = AEInstallObjectAccessor('alis', typeNull, fileObjectHandler, 0, false);

	return result;
}

// __________________________________________________________________________________________
// Name			: AEGotRequiredParams
// Input		: Pointer to an AppleEvent structure
// Output		: OSErr: noErr if all required parameters are present, errAEParamMissed otherwise
// Description	: Checks whether the AppleEvent contains any missing keywords.
OSErr AEGotRequiredParams(const AppleEvent *theAppleEvent)
{
	DescType foundType;
	Size sizeNeeded;
	if ( AEGetAttributePtr(theAppleEvent, keyMissedKeywordAttr, typeWildCard, &foundType, NULL, 0, &sizeNeeded) == errAEDescNotFound )
		return noErr;
	else
		return errAEParamMissed;
}			  

pascal OSErr AEOpenApp(const AppleEvent *theAppleEvent, AppleEvent *reply, long refCon)
{
	(void)reply;
	(void)refCon; 
	return AEGotRequiredParams(theAppleEvent);
}

pascal OSErr AEOpenDoc(const AppleEvent *theAppleEvent, AppleEvent *reply, long refCon)
{
	OSErr		status;
	AEDescList	fileSpecList;
	long		itemCount;
	Size		actualSize;
	FSSpec		currentSpec;
	AEKeyword	keyword;
	DescType	type;
	(void)reply;
	(void)refCon;

	status = AEGetParamDesc(theAppleEvent, keyDirectObject, typeAEList, &fileSpecList);

	if (status == noErr)
		status = AECountItems(&fileSpecList, &itemCount);
	for (long index = 1; index <= itemCount && status == noErr; ++index)
	{
		status = AEGetNthPtr(&fileSpecList, index, typeFSS, &keyword, &type, (Ptr)&currentSpec, sizeof(FSSpec), &actualSize);
		if (status == noErr)
		{
			fileSpec = currentSpec;
			EditIcon(false);
			break;
		}
	}
	return AEGotRequiredParams(theAppleEvent);
}

pascal OSErr AEPrintDoc(const AppleEvent *theAppleEvent, AppleEvent *reply, long refCon)
{
	(void)theAppleEvent;
	(void)reply;
	(void)refCon;
	return errAEEventNotHandled;
}

pascal OSErr AEQuitApp(const AppleEvent *theAppleEvent, AppleEvent *reply, long refCon)
{
	(void)reply;
	(void)refCon;
	isDone = true;
	return AEGotRequiredParams(theAppleEvent);
}

pascal OSErr AEInsertIcon(const AppleEvent *theAppleEvent, AppleEvent *reply, long refCon)
{
	(void)reply;
	(void)refCon;
	long iconID;
	Size	actualSize;
	DescType actualType;
	AEDescList	fileSpecList;
	Str255	resourceName;
	OSStatus err;
	long count;
	AEKeyword	keyword;
	FSSpec		desc;
	DescType	type;
	int dummy;
	bool hasID;

	err = AEGetParamDesc(theAppleEvent, 'iFil', typeAEList, &fileSpecList);

	err = AECountItems(&fileSpecList, &count);
	for (int i = 1; i <= count; ++i)
	{
		err = AEGetNthPtr(&fileSpecList, i, typeFSS, &keyword, &type, (Ptr)&desc, sizeof(FSSpec), &actualSize);
		if (err == noErr)
		{
			fileSpec = desc;
		}
		else
		{
			AEDesc object, token;
			unsigned char aliasResolved;
			err = AEGetParamDesc(theAppleEvent, 'iFil', typeObjectSpecifier, &object);

			err = AEResolve(&object, kAEIDoMinimum, &token);

			err = ResolveAlias(NULL, (AliasHandle)(token.dataHandle), &desc, &aliasResolved);

			AEDisposeDesc(&token);

			fileSpec = desc;
		}
	}

	err = AEGetParamPtr(theAppleEvent, 'iID ', typeSInt32, &actualType, &iconID, sizeof(long), &actualSize);
	if (err != noErr)
		hasID = false;
	else
		hasID = true;

	err = AEGetParamPtr(theAppleEvent, 'iNam', typeChar, &actualType, (Ptr)(&(resourceName[1])), 255, &actualSize);
	if (err == noErr)
		resourceName[0] = (unsigned char)actualSize;
	else if ((**preferences).nameResources && hasID)
		GetIconMenu(iconID, &dummy, &dummy, resourceName);

	if (hasID)
		clip2icns(iconID, resourceName);
	else
	{
		AEInteractAllowed oldLevel;
		AEGetInteractionAllowed(&oldLevel);
		AESetInteractionAllowed(kAEInteractWithLocal);
		AEInteractWithUser(kAEDefaultTimeout, NULL, NULL);
		EditIcon(false);
		AESetInteractionAllowed(oldLevel);
	}

	return AEGotRequiredParams(theAppleEvent);
}

pascal OSErr FileObjectAccessor(DescType	desiredClass,
								AEDesc*		containerToken,
								DescType	containerClass,
								DescType	keyForm,
								AEDesc*		keyData,
								AEDesc*		resultToken,
								long		refCon)
{
#pragma unused (desiredClass, containerToken, containerClass, keyForm, refCon)
	OSErr err;
	AEKeyword	keyword;

	err = AEGetNthDesc(keyData, 1, 'alis', &keyword, resultToken);

	return err;
}

#include "../../include/utility/math.hpp"

// Linear interpolation for 2D vector
xd::vec2 lerp(const xd::vec2& begin, const xd::vec2& finish, float t) noexcept {
    xd::vec2 output;
    output.x = detail::lerp(begin.x, finish.x, t);
    output.y = detail::lerp(begin.y, finish.y, t);
    return output;
}

// Linear interpolation for 3D vector
xd::vec3 lerp(const xd::vec3& begin, const xd::vec3& finish, float t) noexcept {
    xd::vec3 output;
    output.x = detail::lerp(begin.x, finish.x, t);
    output.y = detail::lerp(begin.y, finish.y, t);
    output.z = detail::lerp(begin.z, finish.z, t);
    return output;
}

// Linear interpolation for 4D vector
xd::vec4 lerp(const xd::vec4& begin, const xd::vec4& finish, float t) noexcept {
    xd::vec4 output;
    output.x = detail::lerp(begin.x, finish.x, t);
    output.y = detail::lerp(begin.y, finish.y, t);
    output.z = detail::lerp(begin.z, finish.z, t);
    output.w = detail::lerp(begin.w, finish.w, t);
    return output;
}

#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    int n;
    cin >> n;

    // Frequency array to count occurrences of each number
    vector<int> freq(100002, 0);
    int maxVal = 0;

    for (int i = 0; i < n; i++) {
        int value;
        cin >> value;
        freq[value]++;
        maxVal = max(maxVal, value);
    }

    // Dynamic programming array to store maximum sum up to index i
    vector<long long> dp(maxVal + 2, 0);
    dp[0] = 0;
    dp[1] = 1LL * freq[1];

    // Fill the dp array using the recurrence relation
    for (int i = 2; i <= maxVal; i++) {
        dp[i] = max(dp[i-1], dp[i-2] + 1LL * i * freq[i]);
    }

    cout << dp[maxVal] << endl;
    return 0;
}

