TEST_CASE("Write arbitrary byte sequence to file - should succeed", "[file]")
{
  std::string outputPath = "./../../content/file_tests/file1.txt";
  std::vector<uint8_t> testData {34, 32, 156, 4, 4, 4, 9};
  plz::FileStatus result = plz::File::ToFile(outputPath, testData);
  REQUIRE(result.status() == plz::FileStatus::Code::Ok);
}

TEST_CASE("Attempt write to non-existent directory - should fail", "[file]")
{
    std::string badPath = "./../../content/file_tests_fail/file2.txt";
    std::vector<uint8_t> sampleData {34, 32, 156, 4, 4, 4, 9};
    plz::FileStatus outcome = plz::File::ToFile(badPath, sampleData);
    REQUIRE(outcome.status() == plz::FileStatus::Code::FileWriteErrorFailBit);
}

TEST_CASE("Write data then read back - verify round-trip integrity", "[file]")
{
    std::string filePath = "./../../content/file_tests/file3.txt";
    std::vector<uint8_t> originalData {34, 32, 156, 4, 4, 4, 9};
    std::vector<uint8_t> loadedData;

    // Perform write operation
    plz::FileStatus writeResult = plz::File::ToFile(filePath, originalData);
    REQUIRE(writeResult.status() == plz::FileStatus::Code::Ok);

    // Perform read operation
    plz::FileStatus readResult = plz::File::FromFile(filePath, loadedData);
    REQUIRE(readResult.status() == plz::FileStatus::Code::Ok);

    // Verify contents match
    REQUIRE(loadedData == originalData);

    // Test reading from a path that doesn't exist
    std::vector<uint8_t> emptyBuffer;
    std::string nonexistentPath = "./../../content/file_tests_fail/fileblobba.txt";
    plz::FileStatus failedRead = plz::File::FromFile(nonexistentPath, emptyBuffer);
    REQUIRE(failedRead.status() == plz::FileStatus::Code::FileReadError);
}

