FArticyEditorModule::~FArticyEditorModule() = default;

void FArticyEditorModule::StartupModule()
{
    CustomizationManager = MakeShareable(new FArticyEditorCustomizationManager);

    InitializeAssetTypes();
    InitializeConsoleCommands();
    InitializePropertyExtensions();
    InitializeDetailsLayouts();
    InitializeGraphPins();
    InitializeSettings();
    InitializeUICommands();
    InitializeToolbar();
    InitializeTabs();

    FArticyEditorStyle::Initialize();
}

void FArticyEditorModule::ShutdownModule()
{
    if (!UObjectInitialized()) return;

    GetCustomizationManager()->Shutdown();
    DeregisterSettings();

    if (ConsoleCommands)
    {
        delete ConsoleCommands;
        ConsoleCommands = nullptr;
    }
}

void FArticyEditorModule::WatchGeneratedCodeFolder()
{
    FDirectoryWatcherModule& DirWatcherMod = FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>("DirectoryWatcher");
    IDirectoryWatcher* Watcher = DirWatcherMod.Get();
    if (!Watcher) return;

    const FString SourcePath = CodeGenerator::GetSourceFolder();
    Watcher->RegisterDirectoryChangedCallback_Handle(
        SourcePath,
        IDirectoryWatcher::FDirectoryChanged::CreateRaw(this, &FArticyEditorModule::OnGeneratedCodeChanged),
        GeneratedCodeWatcherHandle
    );
}

