TArray<UArticyPackage*> FArticyEditorModule::GetPackagesSlow()
{
    FAssetRegistryModule& RegModule = FModuleManager::LoadModuleChecked<FAssetRegistryModule>("AssetRegistry");
    TArray<FAssetData> AssetList;
    RegModule.Get().GetAssetsByClass(UArticyPackage::StaticClass()->GetFName(), AssetList);

    TArray<UArticyPackage*> Result;
    Result.Reserve(AssetList.Num());
    for (const FAssetData& Data : AssetList)
    {
        if (UArticyPackage* Package = Cast<UArticyPackage>(Data.GetAsset()))
        {
            Result.Add(Package);
        }
    }
    return Result;
}

