    if (!Menu) return;

    FToolMenuSection& Section = Menu->AddSection("ArticyUtilities", LOCTEXT("ArticyUtilities", "Articy Utilities"));
    Section.AddMenuEntryWithCommandList(FArticyEditorCommands::Get().OpenArticyImporter, PluginCommands);
    Section.AddMenuEntryWithCommandList(FArticyEditorCommands::Get().OpenArticyGVDebugger, PluginCommands);
#else
    FLevelEditorModule& LevelEditorMod = FModuleManager::LoadModuleChecked<FLevelEditorModule>("LevelEditor");
    TSharedPtr<FExtender> ToolbarExtender = MakeShareable(new FExtender);
    ToolbarExtender->AddToolBarExtension("Settings", EExtensionHook::After, PluginCommands,
        FToolBarExtensionDelegate::CreateRaw(this, &FArticyEditorModule::AppendToolbarButtons));
    LevelEditorMod.GetToolBarExtensibilityManager()->AddExtender(ToolbarExtender);
#endif
}

