bool FArticyEditorModule::IsImportPending() const
{
    return bIsImportQueued;
}

void FArticyEditorModule::ScheduleImport()
{
    bIsImportQueued = true;

    FOnMsgDlgResult OnClosed;
    FText Msg = LOCTEXT("ImportWhilePlaying", "To import articy:draft data, exit play mode first.");
    FText Title = LOCTEXT("ImportWhilePlaying_Title", "Import Not Allowed");

    TSharedRef<SWindow> Dialog = OpenMsgDlgInt_NonModal(EAppMsgType::Ok, Msg, Title, OnClosed);
    Dialog->BringToFront(true);

    QueuedImportHandle = FEditorDelegates::EndPIE.AddRaw(this, &FArticyEditorModule::ExecuteScheduledImport);
}

void FArticyEditorModule::CancelScheduledImport()
{
    FEditorDelegates::EndPIE.Remove(QueuedImportHandle);
    QueuedImportHandle.Reset();
    bIsImportQueued = false;
}

void FArticyEditorModule::ExecuteScheduledImport(bool /*b*/)
{
    FArticyEditorFunctionLibrary::ReimportChanges();
    CancelScheduledImport();
}

