EImportStatusValidity FArticyEditorModule::ValidateImportState() const
{
    UArticyImportData* ImportData = nullptr;
    FArticyEditorFunctionLibrary::EnsureImportDataAsset(&ImportData);
    if (!ImportData)
        return EImportStatusValidity::ImportDataAssetMissing;

    TArray<FString> Files;
    IFileManager::Get().FindFiles(Files, *CodeGenerator::GetSourceFolder());
    if (Files.Num() < 5)
        return EImportStatusValidity::FileMissing;

    FAssetRegistryModule& RegModule = FModuleManager::LoadModuleChecked<FAssetRegistryModule>("AssetRegistry");
    TArray<FAssetData> Assets;
    RegModule.Get().GetAssetsByPath(FName(*ArticyHelpers::GetArticyGeneratedFolder()), Assets, true);

    for (const FAssetData& Data : Assets)
    {
        if (!Data.GetAsset())
            return EImportStatusValidity::FileMissing;
    }

    if (Assets.Num() < 3)
        return EImportStatusValidity::ImportantAssetMissing;

    return EImportStatusValidity::Valid;
}

void FArticyEditorModule::OnGeneratedCodeChanged(const TArray<FFileChangeData>& Changes) const
{
    const EImportStatusValidity Status = ValidateImportState();
    if (Status != EImportStatusValidity::FileMissing)
        return;

    FText Message = FText::FromString(TEXT("A generated code file seems missing. Reimport now?"));
    FText Title = FText::FromString(TEXT("Articy Warning"));

#if ENGINE_MAJOR_VERSION == 4 && ENGINE_MINOR_VERSION <= 24
    EAppReturnType::Type Response = OpenMsgDlgInt(EAppMsgType::YesNo, Message, Title);
#else
    EAppReturnType::Type Response = FMessageDialog::Open(EAppMsgType::YesNo, Message, &Title);
#endif

    if (Response == EAppReturnType::Yes)
    {
        FArticyEditorFunctionLibrary::ForceCompleteReimport();
    }
}

