// Command constants renamed
#define SVC_CMD_INSTALL       L"Install"
#define SVC_CMD_UNINSTALL     L"Uninstall"
#define SVC_CMD_START         L"Start"
#define SVC_CMD_STOP          L"Stop"
#define SVC_CMD_QUERY_STATUS  L"Status"
#define SVC_CMD_DEBUG_RUN     L"DebugRun"

// Helper: retrieve current module handle safely
static HMODULE FetchCurrentModuleInstance() {
    HMODULE hMod = nullptr;
    if (!GetModuleHandleEx(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                           reinterpret_cast<LPCWSTR>(&FetchCurrentModuleInstance), &hMod)) {
        SYSFAIL(L"Failed to query current module instance");
    }
    return hMod;
}

// Registry paths updated with local constants
static constexpr LPCTSTR _SVCHOST_CMDLINE_PREFIX = L"%SystemRoot%\\system32\\svchost.exe -k ";
static constexpr LPCTSTR _SVCHOST_REG_PATH       = L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion\\Svchost";
static constexpr LPCTSTR _SERVICE_BASE_REG       = L"SYSTEM\\CurrentControlSet\\services\\";

// RAII wrappers for Windows handles
using SCManagerHandle = TInitResource<SC_HANDLE>;
using RegKeyHandle    = TAllocResource<HKEY>;

// Update svchost group membership list via callback
static void ModifySvchostGroupMembers(
    LPCTSTR GroupName,
    std::function<bool(TString&)> const& ModifierCallback) {

    RegKeyHandle baseKey{
        []() -> HKEY {
            HKEY key = nullptr;
            LONG err = RegOpenKeyEx(HKEY_LOCAL_MACHINE, _SVCHOST_REG_PATH, 0, KEY_ALL_ACCESS, &key);
            if (err != ERROR_SUCCESS)
                SYSERRFAIL(err, L"Unable to open svchost configuration key");
            return key;
        },
        [](HKEY& k) { CloseHandle(k); }
    };

    DWORD bufferSize = MAX_PATH * sizeof(TCHAR);
    TString members;
    LONG result = ERROR_MORE_DATA;

    // Grow buffer until full data fits
    while (result == ERROR_MORE_DATA) {
        members.resize((bufferSize + sizeof(TCHAR) - 1) / sizeof(TCHAR));
        result = RegGetValue(*baseKey, nullptr, GroupName, RRF_RT_REG_MULTI_SZ,
                             nullptr, reinterpret_cast<LPBYTE>(members.data()), &bufferSize);
    }

    if (result != ERROR_SUCCESS && result != ERROR_FILE_NOT_FOUND)
        SYSERRFAIL(result, L"Failed to read svchost group '%s'", GroupName);

    if (result == ERROR_FILE_NOT_FOUND)
        members.clear();

    if (ModifierCallback(members)) {
        if (members.empty()) {
            result = RegDeleteValue(*baseKey, GroupName);
            if (result != ERROR_SUCCESS && result != ERROR_FILE_NOT_FOUND)
                SYSERRFAIL(result, L"Failed to delete value for group '%s'", GroupName);

            result = RegDeleteKey(*baseKey, GroupName);
            if (result != ERROR_SUCCESS && result != ERROR_FILE_NOT_FOUND)
                SYSERRFAIL(result, L"Failed to delete key for group '%s'", GroupName);
        } else {
            result = RegSetValueEx(*baseKey, GroupName, 0, REG_MULTI_SZ,
                                   reinterpret_cast<LPBYTE>(members.data()),
                                   static_cast<DWORD>((members.length() + 1) * sizeof(TCHAR)));
            if (result != ERROR_SUCCESS)
                SYSERRFAIL(result, L"Failed to write svchost group '%s'", GroupName);
        }
    }
}

// Install service into system
static void RegisterService(
    LPCTSTR serviceName,
    LPCTSTR displayName,
    LPCTSTR description,
    LPCTSTR groupName,
    bool autoStart,
    LPCTSTR dependencies = nullptr,
    LPCTSTR dllPath = nullptr,
    int crashRestartAttempts = 0,
    DWORD restartDelayMs = static_cast<DWORD>(Convert(1, TimeUnit::MIN, TimeUnit::MSEC)),
    LPCTSTR privileges = nullptr,
    LPCTSTR account = nullptr,
    LPCTSTR password = nullptr,
    DWORD sidType = SERVICE_SID_TYPE_NONE) {

    // Add service to svchost group
    ModifySvchostGroupMembers(groupName,
        [&](TString& members) -> bool {
            bool found = false;
            for (LPCTSTR p = members.data(); *p; p += _tcslen(p) + 1) {
                if (_tcsicmp(p, serviceName) == 0) {
                    found = true;
                    break;
                }
            }
            if (!found) {
                if (!members.empty())
                    members.pop_back();
                members.append(serviceName).push_back('\0');
                return true;
            }
            return false;
        });

    SC_HANDLE scmHandle = OpenSCManager(nullptr, nullptr, GENERIC_WRITE);
    if (!scmHandle)
        SYSFAIL(L"Could not connect to Service Control Manager");

    SCManagerHandle scm(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    TCHAR exePath[MAX_PATH];
    if (!dllPath) {
        dllPath = exePath;
        DWORD len = GetModuleFileName(FetchCurrentModuleInstance(), exePath, MAX_PATH);
        if (len == 0)
            SYSFAIL(L"Failed to get module file name");
        if (len == MAX_PATH)
            FAIL(L"Module path too long");
    }
    LOGV(L"Service DLL path: %s", dllPath);

    // Build command line
    TCHAR cmdLine[MAX_PATH];
    _tcscpy_s(cmdLine, _SVCHOST_CMDLINE_PREFIX);
    if (_tcsncat_s(cmdLine, groupName, _TRUNCATE) != 0)
        FAIL(L"Command line buffer overflow");

    LOGV(L"Service command line: %s", cmdLine);

    // Create service entry
    scmHandle = CreateService(*scm, serviceName, displayName,
                              SERVICE_ALL_ACCESS, SERVICE_WIN32_SHARE_PROCESS,
                              autoStart ? SERVICE_AUTO_START : SERVICE_DEMAND_START,
                              SERVICE_ERROR_NORMAL, cmdLine, nullptr, 0, dependencies,
                              account, password);
    if (!scmHandle)
        SYSFAIL(L"Failed to create service");

    SCManagerHandle svcHandle(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    // Set optional configurations
    if (description) {
        if (!ChangeServiceConfig2(*svcHandle, SERVICE_CONFIG_DESCRIPTION, &description))
            SYSFAIL(L"Failed to set service description");
    }

    if (privileges) {
        if (!ChangeServiceConfig2(*svcHandle, SERVICE_CONFIG_REQUIRED_PRIVILEGES_INFO, &privileges))
            SYSFAIL(L"Failed to set required privileges");
    }

    if (sidType != SERVICE_SID_TYPE_NONE) {
        if (!ChangeServiceConfig2(*svcHandle, SERVICE_CONFIG_SERVICE_SID_INFO, &sidType))
            SYSFAIL(L"Failed to set SID type");
    }

    if (crashRestartAttempts != 0) {
        LOGV(L"Crash restart configured: %d attempts, delay %s",
             crashRestartAttempts > 0 ? crashRestartAttempts : -1,
             TimeSpan(restartDelayMs, TimeUnit::MSEC).toString(TimeUnit::MIN).c_str());

        SERVICE_FAILURE_ACTIONS actions{};
        actions.dwResetPeriod = static_cast<DWORD>(Convert(1, TimeUnit::DAY, TimeUnit::SEC));
        actions.cActions = std::max(crashRestartAttempts, 0) + 1;

        TTypedBuffer<SC_ACTION> actionList(sizeof(SC_ACTION) * actions.cActions);
        int idx = actions.cActions - 1;
        actionList[idx].Delay = restartDelayMs;
        actionList[idx].Type = crashRestartAttempts > 0 ? SC_ACTION_NONE : SC_ACTION_RESTART;
        while (--idx >= 0) {
            actionList[idx].Delay = restartDelayMs;
            actionList[idx].Type = SC_ACTION_RESTART;
        }
        actions.lpsaActions = actionList;

        if (!ChangeServiceConfig2(*svcHandle, SERVICE_CONFIG_FAILURE_ACTIONS, &actions))
            SYSFAIL(L"Failed to configure failure actions");

        SERVICE_FAILURE_ACTIONS_FLAG flag{};
        flag.fFailureActionsOnNonCrashFailures = TRUE;
        if (!ChangeServiceConfig2(*svcHandle, SERVICE_CONFIG_FAILURE_ACTIONS_FLAG, &flag))
            SYSFAIL(L"Failed to set failure action flag");
    }

    // Configure per-service registry keys
    RegKeyHandle svcKey{
        [&]() -> HKEY {
            HKEY key = nullptr;
            TString regPath = TStringCast(_SERVICE_BASE_REG) + serviceName;
            LONG res = RegOpenKeyEx(HKEY_LOCAL_MACHINE, regPath.c_str(), 0, KEY_ALL_ACCESS, &key);
            if (res != ERROR_SUCCESS)
                SYSERRFAIL(res, L"Failed to open service registry key");
            return key;
        },
        [](HKEY& k) { CloseHandle(k); }
    };

    LONG err = RegSetValueEx(*svcKey, L"ServiceDll", 0, REG_EXPAND_SZ,
                             reinterpret_cast<LPBYTE>(dllPath),
                             static_cast<DWORD>((_tcslen(dllPath) + 1) * sizeof(TCHAR)));
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to set ServiceDll path");

    DWORD unloadFlag = 1;
    err = RegSetValueEx(*svcKey, L"ServiceDllUnloadOnStop", 0, REG_DWORD,
                        reinterpret_cast<LPBYTE>(&unloadFlag), sizeof(unloadFlag));
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to set unload flag");

    LOG(L"Service '%s' registered successfully", serviceName);
}

// Uninstall service from system
static void DeregisterService(LPCTSTR serviceName, LPCTSTR groupName) {
    SC_HANDLE scmHandle = OpenSCManager(nullptr, nullptr, GENERIC_WRITE);
    if (!scmHandle)
        SYSFAIL(L"Could not connect to SCM");

    SCManagerHandle scm(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    scmHandle = OpenService(*scm, serviceName, SERVICE_ALL_ACCESS);
    if (!scmHandle) {
        DWORD err = GetLastError();
        if (err != ERROR_SERVICE_DOES_NOT_EXIST)
            SYSERRFAIL(err, L"Failed to open service");
        LOG(L"Service '%s' does not exist", serviceName);
        return;
    }

    SCManagerHandle svcHandle(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    if (!DeleteService(*svcHandle))
        SYSFAIL(L"Failed to delete service");

    // Remove from svchost group
    ModifySvchostGroupMembers(groupName,
        [&](TString& members) -> bool {
            bool found = false;
            TString newMembers;
            for (LPCTSTR p = members.data(); *p; p += _tcslen(p) + 1) {
                if (_tcsicmp(p, serviceName) != 0)
                    newMembers.append(p).push_back('\0');
                else
                    found = true;
            }
            if (found) {
                members.assign(std::move(newMembers));
                return true;
            }
            return false;
        });

    LOG(L"Service '%s' unregistered", serviceName);
}

// Generic service control dispatcher
static DWORD PerformServiceControl(
    LPCTSTR serviceName,
    std::function<DWORD(SCManagerHandle const&)> handler) {

    SC_HANDLE scmHandle = OpenSCManager(nullptr, nullptr, GENERIC_READ);
    if (!scmHandle)
        SYSFAIL(L"Could not connect to SCM");

    SCManagerHandle scm(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    scmHandle = OpenService(*scm, serviceName, SERVICE_ALL_ACCESS);
    if (!scmHandle)
        SYSFAIL(L"Failed to open service");

    SCManagerHandle svcHandle(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });
    return handler(svcHandle);
}

// Start service and optionally wait for completion
static DWORD InitiateServiceStartup(LPCTSTR serviceName, bool wait) {
    return PerformServiceControl(serviceName,
        [&](SCManagerHandle const& svc) -> DWORD {
            SERVICE_STATUS status{};
            if (!QueryServiceStatus(*svc, &status))
                SYSFAIL(L"Failed to query service status");

            if (status.dwCurrentState == SERVICE_START_PENDING || status.dwCurrentState == SERVICE_RUNNING) {
                LOG(L"Service '%s' already starting or running", serviceName);
            } else {
                LOG(L"Starting service '%s'...", serviceName);
                if (!StartService(*svc, 0, nullptr))
                    SYSFAIL(L"Failed to start service");
                if (!QueryServiceStatus(*svc, &status))
                    SYSFAIL(L"Failed to query status after start");
            }

            if (wait) {
                while (status.dwCurrentState == SERVICE_START_PENDING) {
                    Sleep(100);
                    if (!QueryServiceStatus(*svc, &status))
                        SYSFAIL(L"Failed to poll service status");
                }
                if (status.dwCurrentState == SERVICE_RUNNING)
                    LOG(L"Service '%s' is now running", serviceName);
                else
                    LOG(L"Service '%s' failed to start (state=%d)", serviceName, status.dwCurrentState);
            }
            return status.dwCurrentState;
        });
}

// Stop service and optionally wait for completion
static DWORD RequestServiceShutdown(LPCTSTR serviceName, bool wait) {
    return PerformServiceControl(serviceName,
        [&](SCManagerHandle const& svc) -> DWORD {
            SERVICE_STATUS status{};
            if (!QueryServiceStatus(*svc, &status))
                SYSFAIL(L"Failed to query service status");

            if (status.dwCurrentState == SERVICE_STOP_PENDING || status.dwCurrentState == SERVICE_STOPPED) {
                LOG(L"Service '%s' already stopping or stopped", serviceName);
            } else {
                LOG(L"Stopping service '%s'...", serviceName);
                if (!ControlService(*svc, SERVICE_CONTROL_STOP, &status))
                    SYSFAIL(L"Failed to stop service");
            }

            if (wait) {
                while (status.dwCurrentState == SERVICE_STOP_PENDING) {
                    Sleep(100);
                    if (!QueryServiceStatus(*svc, &status))
                        SYSFAIL(L"Failed to poll service status");
                }
                if (status.dwCurrentState == SERVICE_STOPPED)
                    LOG(L"Service '%s' has stopped", serviceName);
                else
                    LOG(L"Service '%s' did not stop (state=%d)", serviceName, status.dwCurrentState);
            }
            return status.dwCurrentState;
        });
}

// Query current state of a service
static DWORD CheckServiceState(LPCTSTR serviceName) {
    SC_HANDLE scmHandle = OpenSCManager(nullptr, nullptr, GENERIC_READ);
    if (!scmHandle)
        SYSFAIL(L"Could not connect to SCM");

    SCManagerHandle scm(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    scmHandle = OpenService(*scm, serviceName, SERVICE_ALL_ACCESS);
    if (!scmHandle)
        SYSFAIL(L"Failed to open service");

    SCManagerHandle svcHandle(scmHandle, [](SC_HANDLE& h) { CloseServiceHandle(h); });

    SERVICE_STATUS status{};
    if (!QueryServiceStatus(*svcHandle, &status))
        SYSFAIL(L"Failed to query service status");

    switch (status.dwCurrentState) {
        case SERVICE_START_PENDING:   LOG(L"Service '%s' is starting...", serviceName); break;
        case SERVICE_RUNNING:         LOG(L"Service '%s' is running", serviceName); break;
        case SERVICE_STOP_PENDING:    LOG(L"Service '%s' is stopping...", serviceName); break;
        case SERVICE_STOPPED:         LOG(L"Service '%s' is stopped", serviceName); break;
        case SERVICE_PAUSE_PENDING:   LOG(L"Service '%s' is pausing...", serviceName); break;
        case SERVICE_PAUSED:          LOG(L"Service '%s' is paused", serviceName); break;
        case SERVICE_CONTINUE_PENDING:LOG(L"Service '%s' is resuming...", serviceName); break;
        default:                      LOG(L"Unknown service state (%d) for '%s'", status.dwCurrentState, serviceName);
    }
    return status.dwCurrentState;
}

// Clone one svchost group to another
static void DuplicateSvchostGroup(LPCTSTR srcGroup, LPCTSTR dstGroup) {
    HKEY baseKey = nullptr;
    LONG err = RegOpenKeyEx(HKEY_LOCAL_MACHINE, _SVCHOST_REG_PATH, 0, KEY_ALL_ACCESS, &baseKey);
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to open svchost config");

    RegKeyHandle base(baseKey, [](HKEY& k) { CloseHandle(k); });

    err = RegCreateKeyEx(*base, dstGroup, 0, nullptr, REG_OPTION_NON_VOLATILE,
                         KEY_ALL_ACCESS, nullptr, &baseKey, nullptr);
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to create target group '%s'", dstGroup);

    RegKeyHandle dstKey(baseKey, [](HKEY& k) { CloseHandle(k); });

    err = RegOpenKeyEx(*base, srcGroup, 0, KEY_ALL_ACCESS, &baseKey);
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to open source group '%s'", srcGroup);

    RegKeyHandle srcKey(baseKey, [](HKEY& k) { CloseHandle(k); });

    constexpr size_t ITEM_SIZE = 16384;
    std::string valueBuffer;
    DWORD valueType = REG_NONE;
    DWORD dataSize = 0;

    for (int i = 0;; ++i) {
        do {
            valueBuffer.resize(dataSize);
            DWORD itemLen = ITEM_SIZE;
            err = RegEnumValue(*srcKey, i, reinterpret_cast<TCHAR*>(valueBuffer.data()), &itemLen,
                               nullptr, &valueType, reinterpret_cast<LPBYTE>(valueBuffer.data()), &dataSize);
        } while (err == ERROR_MORE_DATA);

        if (err != ERROR_SUCCESS) {
            if (err == ERROR_NO_MORE_ITEMS) break;
            SYSERRFAIL(err, L"Failed to enumerate value #%d in group '%s'", i, srcGroup);
        }

        err = RegSetValueEx(*dstKey, reinterpret_cast<TCHAR*>(valueBuffer.data()), 0, valueType,
                            reinterpret_cast<LPBYTE>(valueBuffer.data()), dataSize);
        if (err != ERROR_SUCCESS)
            SYSERRFAIL(err, L"Failed to copy value '%s' to group '%s'",
                       reinterpret_cast<TCHAR*>(valueBuffer.data()), dstGroup);

        dataSize = static_cast<DWORD>(valueBuffer.size());
    }
}

// Move service between groups atomically using transaction
static void RelocateServiceGroup(LPCTSTR serviceName, LPCTSTR oldGroup, LPCTSTR newGroup) {
    HANDLE txn = CreateTransaction(nullptr, 0, 0, 0, 0, 0, L"Move Service");
    if (txn == INVALID_HANDLE_VALUE)
        SYSFAIL(L"Failed to create transaction");

    struct TransactionGuard {
        HANDLE h;
        ~TransactionGuard() { RollbackTransaction(h); }
    } guard{txn};

    HKEY baseKey = nullptr;
    LONG err = RegOpenKeyTransacted(HKEY_LOCAL_MACHINE, _SVCHOST_REG_PATH, 0, KEY_ALL_ACCESS, &baseKey, txn, nullptr);
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to open svchost key in transaction");

    RegKeyHandle base(baseKey, [](HKEY& k) { CloseHandle(k); });

    // Remove from old group
    DWORD bufSize = MAX_PATH * sizeof(TCHAR);
    TString members;
    err = ERROR_MORE_DATA;
    while (err == ERROR_MORE_DATA) {
        members.resize((bufSize + sizeof(TCHAR) - 1) / sizeof(TCHAR));
        err = RegGetValue(*base, nullptr, oldGroup, RRF_RT_REG_MULTI_SZ,
                          nullptr, reinterpret_cast<LPBYTE>(members.data()), &bufSize);
    }
    if (err != ERROR_SUCCESS && err != ERROR_FILE_NOT_FOUND)
        SYSERRFAIL(err, L"Failed to read old group '%s'", oldGroup);
    if (err == ERROR_FILE_NOT_FOUND)
        members.clear();

    bool found = false;
    TString remaining;
    for (LPCTSTR p = members.data(); *p; p += _tcslen(p) + 1) {
        if (_tcsicmp(p, serviceName) != 0)
            remaining.append(p).push_back('\0');
        else
            found = true;
    }

    if (!found) {
        LOG(L"Service '%s' not in group '%s'", serviceName, oldGroup);
        return;
    }

    err = RegSetValueEx(*base, oldGroup, 0, REG_MULTI_SZ,
                        reinterpret_cast<LPBYTE>(remaining.data()),
                        static_cast<DWORD>((remaining.length() + 1) * sizeof(TCHAR)));
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to update old group '%s'", oldGroup);

    // Add to new group
    members.clear();
    bufSize = 0;
    do {
        members.resize((bufSize + sizeof(TCHAR) - 1) / sizeof(TCHAR));
        err = RegGetValue(*base, nullptr, newGroup, RRF_RT_REG_MULTI_SZ,
                          nullptr, reinterpret_cast<LPBYTE>(members.data()), &bufSize);
    } while (err == ERROR_MORE_DATA);
    if (err != ERROR_SUCCESS && err != ERROR_FILE_NOT_FOUND)
        SYSERRFAIL(err, L"Failed to read new group '%s'", newGroup);
    if (err == ERROR_FILE_NOT_FOUND)
        members.clear();

    found = false;
    for (LPCTSTR p = members.data(); *p; p += _tcslen(p) + 1) {
        if (_tcsicmp(p, serviceName) == 0) {
            found = true;
            break;
        }
    }

    if (!found) {
        if (!members.empty())
            members.resize((bufSize - sizeof(TCHAR)) / sizeof(TCHAR));
        members.append(serviceName).push_back('\0');

        err = RegSetValueEx(*base, newGroup, 0, REG_MULTI_SZ,
                            reinterpret_cast<LPBYTE>(members.data()),
                            static_cast<DWORD>((members.length() + 1) * sizeof(TCHAR)));
        if (err != ERROR_SUCCESS)
            SYSERRFAIL(err, L"Failed to update new group '%s'", newGroup);
    }

    // Update ImagePath in service key
    TString svcRegPath = TStringCast(_SERVICE_BASE_REG) + serviceName;
    err = RegOpenKeyTransacted(HKEY_LOCAL_MACHINE, svcRegPath.c_str(), 0, KEY_ALL_ACCESS, &baseKey, txn, nullptr);
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to open service key in transaction");

    RegKeyHandle svcKey(baseKey, [](HKEY& k) { CloseHandle(k); });

    bufSize = MAX_PATH * sizeof(TCHAR);
    TString imagePath;
    err = ERROR_MORE_DATA;
    while (err == ERROR_MORE_DATA) {
        imagePath.resize((bufSize + sizeof(TCHAR) - 1) / sizeof(TCHAR));
        err = RegGetValue(*svcKey, nullptr, L"ImagePath", RRF_RT_REG_EXPAND_SZ | RRF_NOEXPAND,
                          nullptr, reinterpret_cast<LPBYTE>(imagePath.data()), &bufSize);
    }
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to read ImagePath for '%s'", serviceName);

    TString matchPattern = TStringCast(L" -k ") + oldGroup;
    LPCTSTR pos = _tcsstr(imagePath.data(), matchPattern.data());
    if (!pos)
        FAIL(L"Service image path missing group identifier '%s'", oldGroup);

    imagePath.replace(pos + 4 - imagePath.data(), _tcslen(oldGroup), newGroup);

    err = RegSetValueEx(*svcKey, L"ImagePath", 0, REG_EXPAND_SZ,
                        reinterpret_cast<LPBYTE>(imagePath.data()),
                        static_cast<DWORD>((imagePath.length() + 1) * sizeof(TCHAR)));
    if (err != ERROR_SUCCESS)
        SYSERRFAIL(err, L"Failed to update ImagePath");

    if (!CommitTransaction(txn))
        SYSFAIL(L"Failed to commit transaction");

    guard.h = INVALID_HANDLE_VALUE;

    RequestServiceShutdown(serviceName, true);
}

// Entry point for service control commands
void CALLBACK ServiceCtrlW(HWND hwnd, HINSTANCE hinst, LPCWSTR lpszCmdLine, int nCmdShow) {
    ControlSEHTranslation(true);
#ifdef _DEBUG
    _CrtSetReportMode(_CRT_WARN, _CRTDBG_MODE_FILE | _CRTDBG_MODE_DEBUG);
    _CrtSetReportFile(_CRT_WARN, _CRTDBG_FILE_STDERR);
    _CrtSetDbgFlag(_CRTDBG_LEAK_CHECK_DF);
#endif

    BOOL consoleAllocated = FALSE;
    DEBUGV_DO(consoleAllocated = AllocConsole());
    if (consoleAllocated) {
        FILE* in, *out, *err;
        freopen_s(&in, "CONIN$", "r", stdin);
        freopen_s(&out, "CONOUT$", "w", stdout);
        freopen_s(&err, "CONOUT$", "w", stderr);
    }

    LOG(L"Processing request: %s", lpszCmdLine);
    try {
        TString cmd = lpszCmdLine;
        if (cmd == SVC_CMD_INSTALL) {
            RegisterService(SERVICE_NAME, SERVICE_DISPNAME, SERVICE_DESC, SERVICE_GROUP,
                            SERVICE_AUTOSTART, SERVICE_DEPENDS, nullptr,
                            SERVICE_CRASHRESTART, SERVICE_RESTARTDELAY,
                            SERVICE_USER, nullptr, SERVICE_PRIVILEGES);
        } else if (cmd == SVC_CMD_UNINSTALL) {
            if (CheckServiceState(SERVICE_NAME) != SERVICE_STOPPED)
                FAIL(L"Stop service before uninstalling");
            DeregisterService(SERVICE_NAME, SERVICE_GROUP);
        } else if (cmd == SVC_CMD_START) {
            InitiateServiceStartup(SERVICE_NAME, true);
        } else if (cmd == SVC_CMD_STOP) {
            RequestServiceShutdown(SERVICE_NAME, true);
        } else if (cmd == SVC_CMD_QUERY_STATUS) {
            CheckServiceState(SERVICE_NAME);
        } else if (cmd == SVC_CMD_DEBUG_RUN) {
            LPCWSTR args[] = { SVC_CMD_DEBUG_RUN };
            ServiceMain_DebugRun(1, args);
        } else {
            LOG(L"Unknown command: %s", cmd.c_str());
        }
    } catch (_ECR_ e) {
        LOGEXCEPTIONV(e, L"Request processing failed");
    }

    if (consoleAllocated)
        system("pause");
}

