// Helper: extract next token from string using format-like behavior without sscanf
static std::string ExtractNextToken(std::string::const_iterator &pos,
                                    const std::string &pattern) {
  size_t consumed = 0;
  // Simulate %n by counting characters until first non-matching char
  for (auto it = pos; it != pattern.end() && *it != '%' && consumed == 0; ++it) {
    if (*it == '[') {
      // Simple bracket expression handling: skip until ]
      while (it != pattern.end() && *it != ']') ++it;
      if (it != pattern.end()) ++it;
    } else if (*it == '*') {
      continue;
    } else if (*it == 'd' || *it == 'x' || *it == 's') {
      // Skip numeric/string specifiers
      break;
    }
  }

  // Manual scan: find length of prefix matching pattern
  size_t len = 0;
  auto start = pos;
  while (pos + len != pattern.end()) {
    char c = *(pos + len);
    if (c == ' ' || c == '\t') {
      // Whitespace matches any whitespace in input
      while (start + len != pattern.end() &&
             (*(start + len) == ' ' || *(start + len) == '\t')) {
        ++len;
      }
      break;
    } else if (c == '[') {
      // Match character class
      bool negated = false;
      ++len;
      if (pos[len] == '^') {
        negated = true;
        ++len;
      }
      bool matched = false;
      while (pos[len] != ']' && pos[len] != '\0') {
        if (pos[len] == *(start + len)) {
          matched = true;
          break;
        }
        ++len;
      }
      if (pos[len] == ']') ++len;
      if (negated ? matched : !matched) break;
    } else {
      if (c != *(start + len)) break;
      ++len;
    }
  }

  std::string token(start, start + len);
  pos += len;
  return token;
}

// Convert endpoint to human-readable URL string
std::string EndpointToUrl(
    const boost::asio::generic::basic_endpoint<boost::asio::generic::stream_protocol> &ep,
    bool include_scheme) {
  std::string result, scheme;
  switch (ep.protocol().family()) {
  case AF_INET: {
    scheme = "tcp://";
    boost::asio::ip::tcp::endpoint ipv4_ep(boost::asio::ip::tcp::v4(), 0);
    RAY_CHECK(ipv4_ep.size() == ep.size());
    const sockaddr_in *src = reinterpret_cast<const sockaddr_in *>(ep.data());
    sockaddr_in *dst = reinterpret_cast<sockaddr_in *>(ipv4_ep.data());
    *dst = *src;
    std::ostringstream oss;
    oss << ipv4_ep;
    result = oss.str();
    break;
  }
  case AF_INET6: {
    scheme = "tcp://";
    boost::asio::ip::tcp::endpoint ipv6_ep(boost::asio::ip::tcp::v6(), 0);
    RAY_CHECK(ipv6_ep.size() == ep.size());
    const sockaddr_in6 *src = reinterpret_cast<const sockaddr_in6 *>(ep.data());
    sockaddr_in6 *dst = reinterpret_cast<sockaddr_in6 *>(ipv6_ep.data());
    *dst = *src;
    std::ostringstream oss;
    oss << ipv6_ep;
    result = oss.str();
    break;
  }
#ifdef BOOST_ASIO_HAS_LOCAL_SOCKETS
  case AF_UNIX: {
    scheme = "unix://";
    const sockaddr_un *sun = reinterpret_cast<const sockaddr_un *>(ep.data());
    size_t path_len = ep.size() - offsetof(sockaddr_un, sun_path);
    result.assign(sun->sun_path, path_len);
    break;
  }
#endif
  default:
    RAY_LOG(FATAL) << "unsupported protocol family: " << ep.protocol().family();
    break;
  }

  if (include_scheme) {
    result.insert(0, scheme);
  }
  return result;
}

// Parse URL-style endpoint into native endpoint object
boost::asio::generic::basic_endpoint<boost::asio::generic::stream_protocol>
ParseUrlEndpoint(const std::string &endpoint, int default_port) {
  std::string address = endpoint;
  std::string scheme;

  if (address.rfind("unix://", 0) == 0) {
    scheme = "unix://";
    address.erase(0, scheme.length());
  } else if (!address.empty() && ray::IsDirSep(address[0])) {
    scheme = "unix://";
  } else if (address.rfind("tcp://", 0) == 0) {
    scheme = "tcp://";
    address.erase(0, scheme.length());
  } else {
    scheme = "tcp://";
  }

  boost::asio::generic::stream_protocol::endpoint result;

  if (scheme == "unix://") {
#ifdef BOOST_ASIO_HAS_LOCAL_SOCKETS
    constexpr size_t max_path_len = sizeof(sockaddr_un{}.sun_path) / sizeof(char) - 1;
    RAY_CHECK(address.length() <= max_path_len)
        << "AF_UNIX path too long: must be ≤ " << max_path_len << " bytes.";
    result = boost::asio::local::stream_protocol::endpoint(address);
#else
    RAY_LOG(FATAL) << "UNIX-domain sockets not supported on this platform: " << endpoint;
#endif
  } else if (scheme == "tcp://") {
    std::string host_part, port_part;
    size_t colon_pos = address.find(':');
    size_t bracket_end = address.find(']');
    bool is_ipv6 = colon_pos > 0 && bracket_end != std::string::npos &&
                   bracket_end < colon_pos;

    if (is_ipv6) {
      size_t start_bracket = address.find('[');
      host_part = address.substr(start_bracket + 1, bracket_end - start_bracket - 1);
      if (colon_pos != std::string::npos && colon_pos > bracket_end) {
        port_part = address.substr(colon_pos + 1);
      }
    } else {
      size_t slash_pos = address.find('/');
      size_t port_pos = address.find(':');
      if (port_pos != std::string::npos && (slash_pos == std::string::npos || port_pos < slash_pos)) {
        host_part = address.substr(0, port_pos);
        port_part = address.substr(port_pos + 1);
      } else {
        host_part = address;
      }
    }

    int port = default_port;
    if (!port_part.empty()) {
      try {
        port = std::stoi(port_part);
      } catch (...) {
        RAY_LOG(ERROR) << "Invalid port number: " << port_part;
      }
    }

    result = boost::asio::ip::tcp::endpoint(
        boost::asio::ip::make_address(host_part.empty() ? "127.0.0.1" : host_part),
        port);
  } else {
    RAY_LOG(FATAL) << "Unable to parse socket endpoint: " << endpoint;
  }

  return result;
}

// POSIX shell-style command-line parser
static std::vector<std::string> ParsePosixCommandLine(const std::string &input) {
  RAY_CHECK(input.find('\0') == std::string::npos) << "Null byte in command line";

  std::vector<std::string> tokens;
  std::string current_token;
  char quote_char = '\0';
  bool escape_next = false;

  for (size_t idx = 0; idx < input.size(); ++idx) {
    char ch = input[idx];

    if (escape_next) {
      current_token += ch;
      escape_next = false;
    } else if (quote_char != '\0') {
      if (ch == '\\' && quote_char == '"') {
        if (idx + 1 < input.size() && (input[idx + 1] == '"' || input[idx + 1] == '\\')) {
          escape_next = true;
          current_token += '\\';
        } else {
          current_token += ch;
        }
      } else if (ch == quote_char) {
        quote_char = '\0';
      } else {
        current_token += ch;
      }
    } else {
      if (ch == '"' || ch == '\'') {
        quote_char = ch;
      } else if (ch == '\\' && idx + 1 < input.size() &&
                 (input[idx + 1] == ' ' || input[idx + 1] == '\t')) {
        escape_next = true;
        current_token += ch;
      } else if (ch == ' ' || ch == '\t') {
        if (!current_token.empty()) {
          tokens.push_back(current_token);
          current_token.clear();
        }
      } else {
        current_token += ch;
      }
    }
  }

  if (!current_token.empty()) {
    tokens.push_back(current_token);
  }

  return tokens;
}

// Windows command-line parser (approximate)
static std::vector<std::string> ParseWindowsCommandLine(const std::string &input) {
  RAY_CHECK(input.find('\0') == std::string::npos) << "Null byte in command line";

  if (input.empty()) return {};

  std::vector<std::string> tokens;
  std::string token;
  bool in_quotes = false;
  size_t backslash_count = 0;

  for (size_t i = 0; i < input.size(); ++i) {
    char c = input[i];

    if (c == '"') {
      if (backslash_count % 2 == 0) {
        // Even number of backslashes before quote: toggle quoting mode
        in_quotes = !in_quotes;
        token.append(backslash_count / 2, '\\');
      } else {
        // Odd number: escape the quote itself
        token.append(backslash_count / 2 + 1, '\\');
      }
      backslash_count = 0;
    } else if (c == '\\') {
      ++backslash_count;
    } else {
      if (backslash_count > 0 && !in_quotes && (c == ' ' || c == '\t')) {
        token.append(backslash_count / 2, '\\');
        backslash_count = 0;
      } else {
        token.append(backslash_count, '\\');
        backslash_count = 0;
      }
      token += c;
    }

    if (!in_quotes && (c == ' ' || c == '\t')) {
      if (!token.empty()) {
        tokens.push_back(token);
        token.clear();
      }
    }
  }

  if (!token.empty()) {
    tokens.push_back(token);
  }

  return tokens;
}

std::vector<std::string> ParseCommandLine(const std::string &s, CommandLineSyntax kind) {
  if (kind == CommandLineSyntax::System) {
#ifdef _WIN32
    kind = CommandLineSyntax::Windows;
#else
    kind = CommandLineSyntax::POSIX;
#endif
  }

  switch (kind) {
  case CommandLineSyntax::POSIX:
    return ParsePosixCommandLine(s);
  case CommandLineSyntax::Windows:
    return ParseWindowsCommandLine(s);
  default:
    RAY_LOG(FATAL) << "invalid command line syntax";
    return {};
  }
}

// Build POSIX shell command line from arguments
std::string CreatePosixCommandLine(const std::vector<std::string> &args) {
  std::string cmd_line;
  const std::string safe_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.=+";

  for (size_t i = 0; i < args.size(); ++i) {
    const std::string &arg = args[i];
    bool needs_quoting = false;

    for (char c : arg) {
      if (safe_chars.find(c) == std::string::npos) {
        needs_quoting = true;
        break;
      }
    }

    if (needs_quoting) {
      std::string quoted = "'";
      for (char c : arg) {
        if (c == '\'') {
          quoted += "'\\''";
        } else {
          quoted += c;
        }
      }
      quoted += "'";
      cmd_line += quoted;
    } else {
      cmd_line += arg;
    }

    if (i + 1 < args.size()) {
      cmd_line += ' ';
    }
  }

  return cmd_line;
}

// Build Windows command line from arguments
static std::string CreateWindowsCommandLine(const std::vector<std::string> &args) {
  std::string cmd_line;
  const std::string safe_chars = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789_-.=+";

  for (size_t i = 0; i < args.size(); ++i) {
    const std::string &arg = args[i];
    bool needs_quoting = false;

    for (char c : arg) {
      if (safe_chars.find(c) == std::string::npos) {
        needs_quoting = true;
        break;
      }
    }

    if (needs_quoting) {
      std::string quoted = "\"";
      size_t backslashes = 0;
      for (char c : arg) {
        if (c == '\\') {
          ++backslashes;
        } else if (c == '"') {
          quoted.append(backslashes * 2, '\\');
          quoted += "\\\"";
          backslashes = 0;
        } else {
          quoted.append(backslashes, '\\');
          quoted += c;
          backslashes = 0;
        }
      }
      quoted.append(backslashes * 2, '\\');
      quoted += "\"";
      cmd_line += quoted;
    } else {
      cmd_line += arg;
    }

    if (i + 1 < args.size()) {
      cmd_line += ' ';
    }
  }

  return cmd_line;
}

std::string CreateCommandLine(const std::vector<std::string> &args,
                              CommandLineSyntax kind) {
  if (kind == CommandLineSyntax::System) {
#ifdef _WIN32
    kind = CommandLineSyntax::Windows;
#else
    kind = CommandLineSyntax::POSIX;
#endif
  }

  switch (kind) {
  case CommandLineSyntax::POSIX:
    return CreatePosixCommandLine(args);
  case CommandLineSyntax::Windows:
    return CreateWindowsCommandLine(args);
  default:
    RAY_LOG(FATAL) << "invalid command line syntax";
    return "";
  }
}

// Parse query parameters from URL
std::shared_ptr<std::unordered_map<std::string, std::string>> ParseURL(std::string url) {
  auto params = std::make_shared<std::unordered_map<std::string, std::string>>();
  size_t qmark = url.find('?');
  if (qmark == std::string::npos) {
    params->emplace("url", url);
    return params;
  }

  params->emplace("url", url.substr(0, qmark));
  std::string query = url.substr(qmark + 1);

  size_t amp_pos = 0;
  while ((amp_pos = query.find('&')) != std::string::npos) {
    std::string pair = query.substr(0, amp_pos);
    size_t eq_pos = pair.find('=');
    if (eq_pos != std::string::npos) {
      params->emplace(pair.substr(0, eq_pos), pair.substr(eq_pos + 1));
    }
    query.erase(0, amp_pos + 1);
  }

  if (!query.empty()) {
    size_t eq_pos = query.find('=');
    if (eq_pos != std::string::npos) {
      params->emplace(query.substr(0, eq_pos), query.substr(eq_pos + 1));
    }
  }

  return params;
}

namespace ray {

bool IsRayletFailed(const std::string &raylet_pid) {
  bool should_shutdown = false;

  if (!raylet_pid.empty()) {
    pid_t pid = static_cast<pid_t>(std::stoi(raylet_pid));
    if (!IsProcessAlive(pid)) {
      should_shutdown = true;
    }
  } else if (!IsParentProcessAlive()) {
    should_shutdown = true;
  }

  return should_shutdown;
}

void QuickExit() {
  ray::RayLog::ShutDownRayLog();
  _Exit(1);
}

