// Global state management class
class FPhyaGlobals
{
public:
	FPhyaGlobals() {}
};

// Global singleton pointer
static FPhyaGlobals* GPhyaGlobals = nullptr;

// Initialize Phya audio engine
static void InitPhya()
{
	if (GPhyaGlobals == nullptr)
	{
		paBlock::setnMaxFrames(BlockSize);						// Set block size
		paBlock::pool.allocate(N_BODIES + 5);					// Reserve memory for resonators + buffer
		paContact::pool.allocate(100);
		paImpact::pool.allocate(100);
		paFunSurface::contactGenPool.allocate(20);				// Contact generators pool
		paFunSurface::impactGenPool.allocate(20);				// Impact generators pool
		paRes::activeResList.allocate(N_BODIES);				// Resonator list allocation
		paSetnFramesPerSecond(SampleRate);						// Set sample rate
		paInit();												// Initialize Phya core
		GPhyaGlobals = new FPhyaGlobals;						// Allocate global state
	}
}

// Initialize collision handler and audio components
void UPhyaCollisionHandler::InitCollisionHandler()
{
	// Ensure Phya is initialized
	InitPhya();

	// Setup procedural audio wave
	ProceduralWave = NewObject<USoundWaveProcedural>(this);
	ProceduralWave->SampleRate = SampleRate;
	ProceduralWave->NumChannels = 1;
	ProceduralWave->Duration = INDEFINITELY_LOOPING_DURATION;
	ProceduralWave->bLooping = false;
	ProceduralWave->OnSoundWaveProceduralUnderflow = FOnSoundWaveProceduralUnderflow::CreateUObject(
		this, &UPhyaCollisionHandler::ProceduralWaveUnderflow);

	// Create and configure audio component
	AudioComp = NewObject<UAudioComponent>(this);
	AudioComp->SetSound(ProceduralWave);
	AudioComp->Play();

	// Configure surface and noise generator
	Whitesurf = new paFunSurface;
	Whitefun = new paWhiteFun;
	Whitesurf->setFun(Whitefun);
	Whitesurf->setContactGain(32000.0f);
	Whitesurf->setCutoffFreqAtRoll(10.0f);
	Whitesurf->setCutoffFreqRate(1000.0f);
	Whitesurf->setCutoffFreq2AtRoll(10.0f);
	Whitesurf->setCutoffFreq2Rate(1000.0f);
	Whitesurf->setContactDirectGain(0.0f);
	Whitesurf->setContactGain(70000.0f);
	Whitesurf->setHardness(10000.0f);

	// Load modal data and create resonators
	ModalData = new paModalData;
	ModalData->read(ModalDataString);

	for (int32 i = 0; i < N_BODIES; ++i)
	{
		paModalRes* Res = new paModalRes;
		Res->setData(ModalData);
		Res->setQuietLevel(1.0f);
		Res->setAuxAmpScale(0.1f);
		Res->setAuxFreqScale(1.0f);
		Res->setAuxDampScale(1.0f);

		paBody* Body = new paBody;
		Body->setRes(Res);
		Body->setSurface(Whitesurf);
		Bodies.Add(Body);
	}
}

// Handle audio buffer underflow by generating samples
void UPhyaCollisionHandler::ProceduralWaveUnderflow(USoundWaveProcedural* InProceduralWave, int32 SamplesRequired)
{
	check(ProceduralWave == InProceduralWave);

	const int32 QueuedSamples = ProceduralWave->GetAvailableAudioByteCount() / sizeof(uint16);
	const int32 SamplesNeeded = SamplesRequired - QueuedSamples;
	const int32 BlocksNeeded = FMath::CeilToInt(SamplesNeeded / BlockSize);

	TArray<int16> SampleData;
	SampleData.AddUninitialized(BlocksNeeded * BlockSize);

	int32 CurrSample = 0;
	for (int32 BlockIdx = 0; BlockIdx < BlocksNeeded; ++BlockIdx)
	{
		paBlock* AudioBlock = paTick();
		float* AudioData = AudioBlock->getStart();
		for (int32 SampleIdx = 0; SampleIdx < BlockSize; ++SampleIdx)
		{
			SampleData[CurrSample] = static_cast<int16>(AudioData[SampleIdx]);
			++CurrSample;
		}
	}

	ProceduralWave->QueueAudio(reinterpret_cast<uint8*>(SampleData.GetData()), 
							   SampleData.Num() * sizeof(int16));
}

// Generate a test impact event
void UPhyaCollisionHandler::TestImpact()
{
	paImpact* Impact = paImpact::newImpact();
	if (Impact != nullptr)
	{
		Impact->setBody1(Bodies[0]);
		paImpactDynamicData ImpactData;
		ImpactData.relTangentSpeedAtImpact = 0.0f;
		ImpactData.impactImpulse = 1.0f;
		Impact->setDynamicData(&ImpactData);
	}
}

// Process physics collisions and manage contact states
void UPhyaCollisionHandler::HandlePhysicsCollisions_AssumesLocked(const TArray<FCollisionNotifyInfo>& PendingCollisionNotifies)
{
	if (!GetWorld()->HasBegunPlay())
		return;

	TMap<FPhyaBodyInstancePair, TSharedPtr<FPhyaPairInfo>> ExpiredPairHash = PairHash;

	for (const FCollisionNotifyInfo& Info : PendingCollisionNotifies)
	{
		FPhyaBodyInstancePair Pair(Info.Info0.GetBodyInstance(), Info.Info1.GetBodyInstance());
		TSharedPtr<FPhyaPairInfo> PairInfo = PairHash.FindRef(Pair);

		if (PairInfo.IsValid())
		{
			ExpiredPairHash.Remove(Pair);
		}
		else
		{
			PairInfo = MakeShareable(new FPhyaPairInfo);
			PairHash.Add(Pair, PairInfo);

			paImpact* Impact = paImpact::newImpact();
			if (Impact != nullptr)
			{
				Impact->setBody1(Bodies[0]);
				paImpactDynamicData ImpactData;
				ImpactData.relTangentSpeedAtImpact = 0.0f;
				ImpactData.impactImpulse = 1.0f;
				Impact->setDynamicData(&ImpactData);
			}
		}
	}

	// Clean up expired pairs
	for (auto It = ExpiredPairHash.CreateConstIterator(); It; ++It)
	{
		PairHash.Remove(It.Key());
	}
}

