/// \TODO generalize to have pins and frequency be maintained by caller
void PWM::initialize(const uint32_t cpu_frequency_hz) {
  enable_peripheral_clock(PeripheralID::Timer2);

  // Map PB3 to Timer 2 channel 2 (AF1)
  // [DS] Table 17 (pg 77)
  GPIO::alternate_function(GPIO::Port::B, /*pin =*/3,
                           GPIO::AlternativeFuncion::AF1);  // TIM2_CH2

  TimerReg *timer_instance = Timer2Base;

  // Compute reload value for desired PWM frequency
  timer_instance->auto_reload = (cpu_frequency_hz / pwm_freq_hz_) - 1;

  // Configure Channel 2 for PWM mode 1 with preload enabled
  // Mode bits: 0b0110_1000_0000_0000 = 0x6800 → OC2M = 110 (PWM mode 1), OC2PE = 1
  timer_instance->capture_compare_mode[0] = 0x6800;
  // Enable output compare channel 2 (bit 4 = CC2E)
  timer_instance->capture_compare_enable = 0x10;

  // Initialize duty cycle to zero
  timer_instance->capture_compare[1] = 0u;

  // Trigger update event to load shadow registers
  timer_instance->event = 1u;

  // Enable auto-reload preload and start counter
  timer_instance->control_reg1.bitfield.auto_reload_preload = 1;
  timer_instance->control_reg1.bitfield.counter_enable = 1;
}

// Adjust PWM duty cycle for given pin
void PWM::set(const PwmPin pin, const float duty_ratio) {
  TimerReg *selected_timer = nullptr;
  int channel_index = -1;

  if (pin == PwmPin::Blower) {
    selected_timer = Timer2Base;
    channel_index = 1;
  } else {
    // Defensive programming: ensure all cases handled
    __builtin_unreachable();
  }

  // Compute compare value based on current auto-reload and requested duty ratio
  const uint32_t compare_value = static_cast<uint32_t>(duty_ratio * static_cast<float>(selected_timer->auto_reload));
  selected_timer->capture_compare[channel_index] = compare_value;
}
