namespace Certain
{
    static const uint64_t kSendIntervalMS = 10;

    // Renamed class and methods; internal logic preserved
    void clsCatchUpCtrl::AdjustRateLimit(uint32_t newSpeedKB)
    {
        if (newSpeedKB == m_iMaxCatchUpSpeedKB || newSpeedKB == 0)
            return;

        CertainLogImpt("Changing speed limit: %u KB/s → %u KB/s",
                       m_iMaxCatchUpSpeedKB, newSpeedKB);

        m_iMaxCatchUpSpeedKB = newSpeedKB;
        const uint64_t bytesPerSec = static_cast<uint64_t>(newSpeedKB) << 10;
        const double intervalFactor = 1000.0 / kSendIntervalMS;
        m_iMaxByteSize = static_cast<uint64_t>(bytesPerSec / intervalFactor);
        assert(m_iMaxByteSize > 0);

        m_iNextSendTimeMS = 0;
        m_iRemainByteSize = 0;

        CertainLogInfo("Bytes/sec: %lu | Max per send: %lu", bytesPerSec, m_iMaxByteSize);
    }

    void clsCatchUpCtrl::SetMaxConcurrentRequests(uint32_t maxCount)
    {
        if (maxCount == m_iMaxCatchUpCnt)
            return;

        CertainLogImpt("Updating max concurrent requests: %u → %u",
                       m_iMaxCatchUpCnt, maxCount);
        m_iMaxCatchUpCnt = maxCount;
        m_iUseCount = 0;
        m_iNextCountTimeMS = GetCurrTimeMS() + 1000;
    }

    uint64_t clsCatchUpCtrl::ReserveRequestSlot()
    {
        if (m_iUseCount < m_iMaxCatchUpCnt)
        {
            ++m_iUseCount;
            return 0;
        }

        const uint64_t now = GetCurrTimeMS();
        if (now < m_iNextCountTimeMS)
            return m_iNextCountTimeMS - now;

        // Reset window: allow at least one request per second
        m_iUseCount = 1;
        m_iNextCountTimeMS = now + 1000;
        return 0;
    }

    uint64_t clsCatchUpCtrl::ReserveBandwidth(uint64_t bytesRequested)
    {
        if (m_iRemainByteSize >= bytesRequested)
        {
            m_iRemainByteSize -= bytesRequested;
            return 0;
        }

        const uint64_t now = GetCurrTimeMS();
        if (now < m_iNextSendTimeMS)
            return m_iNextSendTimeMS - now;

        if (bytesRequested <= m_iMaxByteSize)
        {
            m_iRemainByteSize = m_iMaxByteSize - bytesRequested;
            m_iNextSendTimeMS = now + kSendIntervalMS;
            return 0;
        }

        // Scale wait time proportionally to excess size
        const uint64_t scaledInterval = (kSendIntervalMS * bytesRequested) / m_iMaxByteSize;
        m_iNextSendTimeMS = now + scaledInterval;
        m_iRemainByteSize = 0;
        return 0;
    }

    uint64_t clsCatchUpWorker::EstimateCommandSize(clsPaxosCmd *cmd)
    {
        uint64_t baseOverhead = 42; // typical header + metadata overhead
        const EntryRecord_t &srcRec = cmd->GetSrcRecord();
        const EntryRecord_t &dstRec = cmd->GetDestRecord();

        if (srcRec.tValue.iValueID > 0 &&
            srcRec.tValue.iValueID != dstRec.tValue.iValueID)
        {
            baseOverhead += srcRec.tValue.strValue.size();
        }
        return baseOverhead;
    }

    int clsCatchUpWorker::Initialize(clsConfigure *config,
                                     clsCertainUserBase *userLayer)
    {
        m_poConf = config;
        m_iLocalServerID = config->GetLocalServerID();
        m_iMaxCatchUpConcurr = config->GetMaxCatchUpConcurr();
        m_iAcceptorNum = config->GetAcceptorNum();
        m_iServerNum = config->GetServerNum();
        m_iPrevPrintTimeMS = 0;

        m_iCatchUpCnt.assign(m_iServerNum, 0);
        m_iCatchUpSize.assign(m_iServerNum, 0);

        const uint32_t speedKB = config->GetMaxCatchUpSpeedKB();
        if (speedKB == 0)
        {
            CertainLogFatal("Invalid catch-up speed: zero KB/s");
            return -1;
        }

        m_poCatchUpCtrl = new clsCatchUpCtrl;
        m_poCatchUpCtrl->AdjustRateLimit(speedKB);

        m_poCatchUpQueue = clsAsyncQueueMng::GetInstance()->GetCatchUpReqQueue(0);
        m_poIOWorkerRouter = clsIOWorkerRouter::GetInstance();
        m_poCertainUser = userLayer;

        return 0;
    }

    void clsCatchUpWorker::Cleanup()
    {
        delete m_poCatchUpQueue;
        m_poCatchUpQueue = nullptr;
        delete m_poCatchUpCtrl;
        m_poCatchUpCtrl = nullptr;
    }

    int clsCatchUpWorker::EnqueueCatchUpRequest(clsPaxosCmd *cmd)
    {
        AssertNotMore(cmd->GetEntry(), cmd->GetMaxChosenEntry());

        if (m_poCatchUpQueue->Size() >= m_iMaxCatchUpConcurr)
            return -1;

        int res = m_poCatchUpQueue->PushByMultiThread(cmd);
        if (res != 0)
        {
            OSS::ReportCatchUpQueueErr();
            CertainLogError("Failed to push catch-up request (code %d)", res);
            return -2;
        }
        return 0;
    }

    void clsCatchUpWorker::LogStatistics()
    {
        const uint64_t now = GetCurrTimeMS();
        if (now < m_iPrevPrintTimeMS + 1000)
            return;

        uint64_t totalOps = 0, totalBytes = 0;
        bool anyActivity = false;
        std::string details;

        for (uint32_t srvIdx = 0; srvIdx < m_iServerNum; ++srvIdx)
        {
            char buf[128];
            snprintf(buf, sizeof(buf), " S%u(%lu, %lu)",
                     srvIdx, m_iCatchUpCnt[srvIdx], m_iCatchUpSize[srvIdx]);
            details += buf;

            if (m_iCatchUpCnt[srvIdx] > 0)
                anyActivity = true;

            totalOps += m_iCatchUpCnt[srvIdx];
            totalBytes += m_iCatchUpSize[srvIdx];

            m_iCatchUpCnt[srvIdx] = 0;
            m_iCatchUpSize[srvIdx] = 0;
        }

        if (anyActivity)
        {
            CertainLogImpt("Catch-up stats for server %u [total ops=%lu, bytes=%lu]: %s",
                           m_iLocalServerID, totalOps, totalBytes, details.c_str());
        }

        m_iPrevPrintTimeMS = now;
    }

    void clsCatchUpWorker::TrackProgress(uint64_t entityID,
                                         uint32_t destAcceptorID,
                                         uint64_t payloadSize)
    {
        uint32_t localAcceptorID = 0;
        AssertEqual(m_poCertainUser->GetLocalAcceptorID(entityID, localAcceptorID), 0);

        uint32_t targetServerID = m_iServerNum;
        if (destAcceptorID < m_iAcceptorNum)
        {
            AssertNotEqual(destAcceptorID, localAcceptorID);
            AssertEqual(m_poCertainUser->GetServerID(entityID, destAcceptorID, targetServerID), 0);
            AssertLess(targetServerID, m_iServerNum);

            ++m_iCatchUpCnt[targetServerID];
            m_iCatchUpSize[targetServerID] += payloadSize;
        }
        else
        {
            for (uint32_t accID = 0; accID < m_iAcceptorNum; ++accID)
            {
                if (accID == localAcceptorID)
                    continue;

                AssertEqual(m_poCertainUser->GetServerID(entityID, accID, targetServerID), 0);
                AssertLess(targetServerID, m_iServerNum);

                ++m_iCatchUpCnt[targetServerID];
                m_iCatchUpSize[targetServerID] += payloadSize;
            }
        }

        LogStatistics();
    }

    void clsCatchUpWorker::MainLoop()
    {
        SetThreadTitle("catchup_%u", m_iLocalServerID);
        CertainLogInfo("Catch-up worker %u started", m_iLocalServerID);

        clsSmartSleepCtrl sleepController(200, 1000);

        while (true)
        {
            if (CheckIfExiting(1000))
            {
                printf("Catch-up worker %u shutting down\n", m_iLocalServerID);
                CertainLogInfo("Catch-up worker %u exiting", m_iLocalServerID);
                break;
            }

            // Refresh rate limits from config periodically
            m_poCatchUpCtrl->AdjustRateLimit(m_poConf->GetMaxCatchUpSpeedKB());
            m_poCatchUpCtrl->SetMaxConcurrentRequests(m_poConf->GetMaxCatchUpCnt());

            clsPaxosCmd *request = nullptr;
            int status = m_poCatchUpQueue->TakeByOneThread(&request);

            if (status != 0)
            {
                sleepController.Sleep();
                LogStatistics();
                continue;
            }
            else
            {
                sleepController.Reset();
            }

            const uint64_t entityID = request->GetEntityID();
            const uint32_t destAcceptor = request->GetDestAcceptorID();
            const uint64_t estimatedSize = EstimateCommandSize(request);

            // Enforce bandwidth throttling
            while (true)
            {
                const uint64_t delayMs = m_poCatchUpCtrl->ReserveBandwidth(estimatedSize);
                if (delayMs == 0)
                    break;

                CertainLogImpt("Bandwidth throttled: waiting %lu ms for %lu bytes",
                               delayMs, estimatedSize);
                usleep(delayMs * 1000);
            }

            // Enforce concurrency throttling
            while (true)
            {
                const uint64_t delayMs = m_poCatchUpCtrl->ReserveRequestSlot();
                if (delayMs == 0)
                    break;

                CertainLogImpt("Concurrency throttled: waiting %lu ms", delayMs);
                usleep(delayMs * 1000);
            }

            // Dispatch command
            status = m_poIOWorkerRouter->Go(request);
            if (status != 0)
            {
                CertainLogError("Failed to route catch-up request (code %d): %s",
                                status, request->GetTextCmd().c_str());
                delete request;
                request = nullptr;
            }
            else
            {
                TrackProgress(entityID, destAcceptor, estimatedSize);
            }
        }
    }
