{
    CMICMDBASE_GETOPTION(pArgGdbOption, ListOfN, m_constStrArgNamedGdbOption);
    const CMICmdArgValListBase::VecArgObjPtr_t &rWordList(pArgGdbOption->GetExpectedOptions());

    // Extract first word as option name
    CMICmdArgValListBase::VecArgObjPtr_t::const_iterator iter = rWordList.begin();
    const CMICmdArgValString *pOption = static_cast<const CMICmdArgValString *>(*iter);
    const CMIUtilString strOptionName(pOption->GetValue());
    ++iter;

    // Collect remaining words as parameters
    CMIUtilString::VecString_t vecParameters;
    while (iter != rWordList.end())
    {
        const CMICmdArgValString *pParam = static_cast<const CMICmdArgValString *>(*iter);
        vecParameters.push_back(pParam->GetValue());
        ++iter;
    }

    // Look up handler function
    FnGdbOptionPtr pHandler = nullptr;
    if (!FindHandler(strOptionName, pHandler))
    {
        // Use fallback handler when specific handler not found
        if (!FindHandler("fallback", pHandler))
        {
            m_bOptionFound = false;
            m_strOptionName = "fallback";
            return MIstatus::success;
        }
    }

    // Execute handler and check result
    m_bHandlerExecutionOk = (this->*(pHandler))(vecParameters);
    if (!m_bHandlerExecutionOk && !m_bHandlerErrorFlag)
        return MIstatus::failure;
    return MIstatus::success;
}

// Generate MI response record
bool
CMICmdCmdGdbShow::Acknowledge()
{
    // Handle unrecognized option case
    if (!m_bOptionFound)
    {
        const CMICmnMIValueConst miValueConst(
            CMIUtilString::Format(MIRSRC(IDS_CMD_ERR_INFO_PRINTFN_NOT_FOUND), m_strOptionName.c_str()));
        const CMICmnMIValueResult miValueResult("msg", miValueConst);
        const CMICmnMIResultRecord miRecordResult(m_cmdData.strMiCmdToken, CMICmnMIResultRecord::eResultClass_Error, miValueResult);
        m_miResultRecord = miRecordResult;
        return MIstatus::success;
    }

    // Handle successful execution with value
    if (m_bHandlerExecutionOk && !m_strValue.empty())
    {
        const CMICmnMIValueConst miValueConst(m_strValue);
        const CMICmnMIValueResult miValueResult("value", miValueConst);
        const CMICmnMIResultRecord miRecordResult(m_cmdData.strMiCmdToken, CMICmnMIResultRecord::eResultClass_Done, miValueResult);
        m_miResultRecord = miRecordResult;
        return MIstatus::success;
    }
    else if (m_bHandlerExecutionOk)
    {
        // Handle empty value case
        const CMICmnMIResultRecord miRecordResult(m_cmdData.strMiCmdToken, CMICmnMIResultRecord::eResultClass_Done);
        m_miResultRecord = miRecordResult;
        return MIstatus::success;
    }

    // Handle execution failure
    const CMICmnMIValueConst miValueConst(CMIUtilString::Format(MIRSRC(IDS_CMD_ERR_INFO_PRINTFN_FAILED), m_strHandlerErrorMessage.c_str()));
    const CMICmnMIValueResult miValueResult("msg", miValueConst);
    const CMICmnMIResultRecord miRecordResult(m_cmdData.strMiCmdToken, CMICmnMIResultRecord::eResultClass_Error, miValueResult);
    m_miResultRecord = miRecordResult;
    return MIstatus::success;
}

// Factory method for command instantiation
CMICmdBase *
CMICmdCmdGdbShow::Instantiate()
{
    return new CMICmdCmdGdbShow();
}

// Find handler function by name
bool
CMICmdCmdGdbShow::FindHandler(const CMIUtilString &vrHandlerName, FnGdbOptionPtr &vrwpHandler) const
{
    vrwpHandler = nullptr;
    const MapGdbOptionNameToFnGdbOptionPtr_t::const_iterator it = ms_mapGdbOptionNameToFnGdbOptionPtr.find(vrHandlerName);
    if (it != ms_mapGdbOptionNameToFnGdbOptionPtr.end())
    {
        vrwpHandler = (*it).second;
        return true;
    }
    return false;
}

// Handler for target-async option
bool
CMICmdCmdGdbShow::HandlerTargetAsync(const CMIUtilString::VecString_t &vrParams)
{
    MIunused(vrParams);
    CMICmnLLDBDebugSessionInfo &rSessionInfo(CMICmnLLDBDebugSessionInfo::Instance());
    const bool bAsyncMode = rSessionInfo.GetDebugger().GetAsync();
    m_strValue = bAsyncMode ? "on" : "off";
    return MIstatus::success;
}

// Handler for print settings option
bool
CMICmdCmdGdbShow::HandlerPrintSettings(const CMIUtilString::VecString_t &vrParams)
{
    const bool bSingleArgument(vrParams.size() == 1);
    if (!bSingleArgument)
    {
        m_bHandlerErrorFlag = true;
        m_strHandlerErrorMessage = MIRSRC(IDS_CMD_ERR_GDBSHOW_OPT_PRINT_BAD_ARGS);
        return MIstatus::failure;
    }

    const CMIUtilString strSetting(vrParams[0]);
    CMIUtilString strSettingKey;
    bool bDefaultValue = false;

    if (CMIUtilString::Compare(strSetting, "char-array-as-string"))
        strSettingKey = m_rLLDBDebugSessionInfo.m_constStrPrintCharArrayAsString;
    else if (CMIUtilString::Compare(strSetting, "expand-aggregates"))
        strSettingKey = m_rLLDBDebugSessionInfo.m_constStrPrintExpandAggregates;
    else if (CMIUtilString::Compare(strSetting, "aggregate-field-names"))
    {
        strSettingKey = m_rLLDBDebugSessionInfo.m_constStrPrintAggregateFieldNames;
        bDefaultValue = true;
    }
    else
    {
        m_bHandlerErrorFlag = true;
        m_strHandlerErrorMessage = CMIUtilString::Format(MIRSRC(IDS_CMD_ERR_GDBSHOW_OPT_PRINT_UNKNOWN_OPTION), strSetting.c_str());
        return MIstatus::failure;
    }

    bool bSettingValue = false;
    bSettingValue = bDefaultValue ? !m_rLLDBDebugSessionInfo.SharedDataRetrieve<bool>(strSettingKey, bSettingValue) || bSettingValue
        : m_rLLDBDebugSessionInfo.SharedDataRetrieve<bool>(strSettingKey, bSettingValue) && bSettingValue;

    m_strValue = bSettingValue ? "on" : "off";
    return MIstatus::success;
}

// Handler for language setting option
bool
CMICmdCmdGdbShow::HandlerLanguageSetting(const CMIUtilString::VecString_t &vrParams)
{
    MIunused(vrParams);
    CMICmnLLDBDebugSessionInfo &rSessionInfo(CMICmnLLDBDebugSessionInfo::Instance());
    lldb::SBThread sbThread = rSessionInfo.GetProcess().GetSelectedThread();
    const lldb::SBFrame sbFrame = sbThread.GetSelectedFrame();
    lldb::SBCompileUnit sbCompileUnit = sbFrame.GetCompileUnit();
    const lldb::LanguageType eLanguageType = sbCompileUnit.GetLanguage();
    m_strValue = lldb::SBLanguageRuntime::GetNameForLanguageType(eLanguageType);
    return MIstatus::success;
}

// Default/fallback handler
bool
CMICmdCmdGdbShow::HandlerDefaultCase(const CMIUtilString::VecString_t &vrParams)
{
    MIunused(vrParams);
    return MIstatus::success;
}

