namespace Vishala {

  BinaryPackage LobbyModel::toBinary() const {
    BinaryPackage result;

    // Serialize open games
    size_t gameCount = openGames.size();
    BinaryPackage::val2bin(result, static_cast<int>(gameCount));
    for (size_t idx = 0; idx < gameCount; ++idx) {
      result.add(openGames[idx].toBinary());
    }

    // Serialize players
    size_t playerCount = players.size();
    BinaryPackage::val2bin(result, static_cast<int>(playerCount));
    size_t pIdx = 0;
    while (pIdx < playerCount) {
      result.add(players[pIdx].toBinary());
      ++pIdx;
    }

    // Serialize open requests
    size_t reqCount = openRequests.size();
    BinaryPackage::val2bin(result, static_cast<int>(reqCount));
    for (size_t rIdx = 0; rIdx < reqCount; ++rIdx) {
      result.add(openRequests[rIdx].toBinary());
    }

    // Serialize next identifiers
    BinaryPackage::val2bin(result, nextPlayerNumber);
    BinaryPackage::val2bin(result, nextGameNumber);

    return result;
  }

  void LobbyModel::fromBinary(BinaryPackage& Package) {
    openGames.clear();
    players.clear();
    openRequests.clear();

    int gameCount = BinaryPackage::bin2val<int>(Package);
    for (int i = 0; i < gameCount; ++i) {
      LobbyGame game;
      game.fromBinary(Package);
      openGames.emplace_back(std::move(game));
    }

    int playerCount = BinaryPackage::bin2val<int>(Package);
    int pCounter = 0;
    while (pCounter < playerCount) {
      LobbyPlayerModel player;
      player.fromBinary(Package);
      players.push_back(std::move(player));
      ++pCounter;
    }

    int reqCount = BinaryPackage::bin2val<int>(Package);
    for (int j = 0; j < reqCount; ++j) {
      OpenLobbyRequest request;
      request.fromBinary(Package);
      openRequests.emplace_back(std::move(request));
    }

    nextPlayerNumber = BinaryPackage::bin2val<size_t>(Package);
    nextGameNumber   = BinaryPackage::bin2val<size_t>(Package);
  }

  nlohmann::json LobbyModel::toJson() const {
    nlohmann::json result;

    // Serialize open games
    nlohmann::json gamesArray = nlohmann::json::array();
    for (const auto& g : openGames) {
      gamesArray.push_back(g.toJson());
    }
    result["OpenGames"] = gamesArray;

    // Serialize players
    nlohmann::json playersArray = nlohmann::json::array();
    for (const auto& pl : players) {
      playersArray.push_back(pl.toJson());
    }
    result["Player"] = playersArray;

    // Serialize open requests
    nlohmann::json requestsArray = nlohmann::json::array();
    for (const auto& req : openRequests) {
      requestsArray.push_back(req.toJson());
    }
    result["OpenRequests"] = requestsArray;

    // Serialize next identifiers
    result["NextPlayerNumber"] = nextPlayerNumber;
    result["NextGameNumber"]   = nextGameNumber;

    return result;
  }

  void LobbyModel::fromJson(nlohmann::json data) {
    openGames.clear();
    for (auto& item : data["OpenGames"]) {
      LobbyGame g;
      g.fromJson(item);
      openGames.push_back(std::move(g));
    }

    players.clear();
    for (auto& item : data["Player"]) {
      LobbyPlayerModel p;
      p.fromJson(item);
      players.push_back(std::move(p));
    }

    openRequests.clear();
    for (auto& item : data["OpenRequests"]) {
      OpenLobbyRequest r;
      r.fromJson(item);
      openRequests.push_back(std::move(r));
    }

    nextPlayerNumber = data["NextPlayerNumber"].get<size_t>();
    nextGameNumber   = data["NextGameNumber"].get<size_t>();
  }

}

#include "btree/backfill.hpp"
#include "arch/runtime/coroutines.hpp"
#include "btree/backfill_debug.hpp"
#include "btree/depth_first_traversal.hpp"
#include "btree/leaf_node.hpp"
#include "concurrency/pmap.hpp"
