#include <vector>
#include <tuple>
#include <limits>

class Solution {
    std::tuple<int, int> min_skip_thresholds = {std::numeric_limits<int>::max(), std::numeric_limits<int>::max()};
public:
    bool increasingTriplet(std::vector<int>& nums) {
        for (int idx = 0; idx < static_cast<int>(nums.size()); ++idx) {
            // Skip if current element is not smaller than the first threshold
            if (nums[idx] >= std::get<0>(min_skip_thresholds))
                continue;

            for (int jdx = idx + 1; jdx < static_cast<int>(nums.size()); ++jdx) {
                // Only consider elements greater than nums[idx]
                if (nums[jdx] > nums[idx]) {
                    // Skip if current pair's second element is not better than stored threshold
                    if (nums[jdx] >= std::get<1>(min_skip_thresholds))
                        continue;

                    for (int kdx = jdx + 1; kdx < static_cast<int>(nums.size()); ++kdx) {
                        if (nums[kdx] > nums[jdx]) {
                            return true;
                        }
                    }
                    // Update the second threshold with this valid pair
                    std::get<1>(min_skip_thresholds) = nums[jdx];
                }
            }
            // Update the first threshold with this starting value
            std::get<0>(min_skip_thresholds) = nums[idx];
        }
        return false;
    }
};

