// SLA tests: Shift Left Arithmetic (rotate left within register A)
__TEST_U(TestMachineShiftsAndMoves, shift_left_zero) {
    system.rA.set(false, 1, 2, 3, 4, 5);
    auto instruction = mixal::Parser::parseLine("SLA 0", "", false);
    system.runSingleStep(&instruction);
    __ASSERT_EQ(mixal::ComputerWord(false, 1, 2, 3, 4, 5), system.rA);
}

