    system.rA.set(false, 1, 2, 3, 4, 5);
    auto instruction = mixal::Parser::parseLine("SLA 1", "", false);
    system.runSingleStep(&instruction);
    __ASSERT_EQ(mixal::ComputerWord(false, 2, 3, 4, 5, 0), system.rA);
}

