// MOVE tests: Memory block move operation
__TEST_U(TestMachineShiftsAndMoves, move_operation_safe) {
    system.rI1.set(999);
    system.memory[1000].set(1);
    system.memory[1001].set(12);
    system.memory[1002].set(123);
    auto instruction = mixal::Parser::parseLine("MOVE 1000(3)", "", false);
    system.runSingleStep(&instruction);
    __ASSERT_EQ(1, system.memory[999].value());
    __ASSERT_EQ(12, system.memory[1000].value());
    __ASSERT_EQ(123, system.memory[1001].value());
    __ASSERT_EQ(123, system.memory[1002].value());
}

