#include "pch.h"
using namespace winrt;
using namespace Windows::Foundation;
using namespace Windows::Foundation::Collections;

TEST_CASE("single_threaded_observable_vector_rewritten")
{
    {
        // Basic smoke test for strongly-typed observable vector - exhaustive tests already exist elsewhere.
        IObservableVector<int> vec = single_threaded_observable_vector<int>();
        bool eventTriggered{};
        vec.VectorChanged([&](auto && ...)
            {
                eventTriggered = vec.GetAt(0) == 123;
            });
        vec.Append(123);
        REQUIRE(eventTriggered);
    }
    {
        // Ensuring IInspectable collections still work as expected (not treated specially).
        IObservableVector<IInspectable> vec = single_threaded_observable_vector<IInspectable>();
        bool eventTriggered{};
        vec.VectorChanged([&](auto && ...)
            {
                eventTriggered = unbox_value<int>(vec.GetAt(0)) == 123;
            });
        vec.Append(box_value(123));
        REQUIRE(eventTriggered);
    }
    {
        // VectorChanged notifications arrive on both interface views.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        bool intNotified{};
        bool objNotified{};
        intVec.VectorChanged([&](IObservableVector<int> const& sender, IVectorChangedEventArgs const&)
            {
                intNotified = sender.GetAt(0) == 123;
                REQUIRE(sender == intVec);
            });
        objVec.VectorChanged([&](IObservableVector<IInspectable> const& sender, IVectorChangedEventArgs const&)
            {
                objNotified = unbox_value<int>(sender.GetAt(0)) == 123;
                REQUIRE(sender == objVec);
            });
        intVec.Append(123);
        REQUIRE(intNotified);
        REQUIRE(objNotified);
    }
    {
        // Event token management works correctly across interfaces.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        int intCount{};
        int objCount{};
        auto tokenInt = intVec.VectorChanged([&](IObservableVector<int> const&, IVectorChangedEventArgs const&)
            {
                ++intCount;
            });
        auto tokenObj = objVec.VectorChanged([&](IObservableVector<IInspectable> const&, IVectorChangedEventArgs const&)
            {
                ++objCount;
            });
        REQUIRE(intCount == 0);
        REQUIRE(objCount == 0);
        intVec.Append(1);
        REQUIRE(intCount == 1);
        REQUIRE(objCount == 1);
        intVec.VectorChanged(tokenInt);
        intVec.Append(1);
        REQUIRE(intCount == 1);
        REQUIRE(objCount == 2);
        objVec.VectorChanged(tokenObj);
        intVec.Append(1);
        REQUIRE(intCount == 1);
        REQUIRE(objCount == 2);
    }
    {
        // Shared underlying storage remains consistent between views.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        intVec.Append(0);
        objVec.Append(box_value(1));
        REQUIRE(intVec.Size() == 2);
        REQUIRE(objVec.Size() == 2);
        REQUIRE(intVec.GetAt(0) == 0);
        REQUIRE(unbox_value<int>(objVec.GetAt(0)) == 0);
        REQUIRE(intVec.GetAt(1) == 1);
        REQUIRE(unbox_value<int>(objVec.GetAt(1)) == 1);
    }
    {
        // Iterators behave consistently across type views.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        IIterator<int> iterInt = intVec.First();
        IIterator<IInspectable> iterObj = objVec.First();
        REQUIRE(iterInt.HasCurrent());
        REQUIRE(iterObj.HasCurrent());
        REQUIRE(iterInt.Current() == 1);
        REQUIRE(unbox_value<int>(iterObj.Current()) == 1);
        REQUIRE(iterInt.MoveNext());
        REQUIRE(iterObj.MoveNext());
        REQUIRE(iterInt.HasCurrent());
        REQUIRE(iterObj.HasCurrent());
        REQUIRE(iterInt.Current() == 2);
        REQUIRE(unbox_value<int>(iterObj.Current()) == 2);
        REQUIRE(!iterInt.MoveNext());
        REQUIRE(!iterObj.MoveNext());
        REQUIRE(!iterInt.HasCurrent());
        REQUIRE(!iterObj.HasCurrent());
        REQUIRE_THROWS_AS(iterInt.Current(), hresult_out_of_bounds);
        REQUIRE_THROWS_AS(iterObj.Current(), hresult_out_of_bounds);
    }
    {
        // GetMany functionality verified with boxing/unboxing.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        IIterator<int> iterInt = intVec.First();
        IIterator<IInspectable> iterObj = objVec.First();
        std::array<int, 3> bufferInt{};
        REQUIRE(2 == iterInt.GetMany(bufferInt));
        REQUIRE(bufferInt[0] == 1);
        REQUIRE(bufferInt[1] == 2);
        REQUIRE(bufferInt[2] == 0);
        std::array<IInspectable, 3> bufferObj{};
        REQUIRE(2 == iterObj.GetMany(bufferObj));
        REQUIRE(unbox_value<int>(bufferObj[0]) == 1);
        REQUIRE(unbox_value<int>(bufferObj[1]) == 2);
        REQUIRE(bufferObj[2] == nullptr);
        REQUIRE(0 == iterInt.GetMany(bufferInt));
        REQUIRE(0 == iterObj.GetMany(bufferObj));
    }
    {
        // Partial GetMany calls work correctly.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        IIterator<int> iterInt = intVec.First();
        IIterator<IInspectable> iterObj = objVec.First();
        std::array<int, 1> smallBufferInt{};
        REQUIRE(1 == iterInt.GetMany(smallBufferInt));
        REQUIRE(smallBufferInt[0] == 1);
        std::array<IInspectable, 1> smallBufferObj{};
        REQUIRE(1 == iterObj.GetMany(smallBufferObj));
        REQUIRE(unbox_value<int>(smallBufferObj[0]) == 1);
    }
    {
        // Iterator invalidation occurs consistently across views.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        IIterator<int> iterInt = intVec.First();
        IIterator<IInspectable> iterObj = objVec.First();
        REQUIRE(iterInt.HasCurrent());
        REQUIRE(iterObj.HasCurrent());
        intVec.Append(3);
        REQUIRE_THROWS_AS(iterInt.HasCurrent(), hresult_changed_state);
        REQUIRE_THROWS_AS(iterObj.HasCurrent(), hresult_changed_state);
    }
    {
        // IndexOf operations work across type boundaries.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        uint32_t idx{};
        REQUIRE((intVec.IndexOf(2, idx) && idx == 1));
        idx = 0;
        REQUIRE((objVec.IndexOf(box_value(2), idx) && idx == 1));
    }
    {
        // GetView returns consistent results.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        REQUIRE(intVec.GetView().GetAt(1) == 2);
        REQUIRE(unbox_value<int>(objVec.GetView().GetAt(1)) == 2);
    }
    {
        // SetAt updates shared state correctly.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        REQUIRE(intVec.GetAt(0) == 1);
        REQUIRE(intVec.GetAt(1) == 2);
        intVec.SetAt(0, 10);
        objVec.SetAt(1, box_value(20));
        REQUIRE(intVec.GetAt(0) == 10);
        REQUIRE(intVec.GetAt(1) == 20);
    }
    {
        // InsertAt maintains consistency across views.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,4 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        REQUIRE(intVec.Size() == 2);
        intVec.InsertAt(1, 2);
        objVec.InsertAt(2, box_value(3));
        REQUIRE(intVec.Size() == 4);
        REQUIRE(intVec.GetAt(0) == 1);
        REQUIRE(intVec.GetAt(1) == 2);
        REQUIRE(intVec.GetAt(2) == 3);
        REQUIRE(intVec.GetAt(3) == 4);
    }
    {
        // Append works identically through either interface.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>();
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        REQUIRE(intVec.Size() == 0);
        intVec.Append(1);
        objVec.Append(box_value(2));
        REQUIRE(intVec.Size() == 2);
        REQUIRE(intVec.GetAt(0) == 1);
        REQUIRE(intVec.GetAt(1) == 2);
    }
    {
        // GetMany with offset and large buffers.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2,3,4,5 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        {
            std::array<int, 3> bufferInt{};
            REQUIRE(0 == intVec.GetMany(5, bufferInt));
        }
        {
            std::array<int, 3> bufferInt{};
            REQUIRE(3 == intVec.GetMany(0, bufferInt));
            REQUIRE(bufferInt[0] == 1);
            REQUIRE(bufferInt[1] == 2);
            REQUIRE(bufferInt[2] == 3);
        }
        {
            std::array<int, 3> bufferInt{};
            REQUIRE(2 == intVec.GetMany(3, bufferInt));
            REQUIRE(bufferInt[0] == 4);
            REQUIRE(bufferInt[1] == 5);
            REQUIRE(bufferInt[2] == 0);
        }
        {
            std::array<IInspectable, 3> bufferObj{};
            REQUIRE(0 == objVec.GetMany(5, bufferObj));
        }
        {
            std::array<IInspectable, 3> bufferObj{};
            REQUIRE(3 == objVec.GetMany(0, bufferObj));
            REQUIRE(unbox_value<int>(bufferObj[0]) == 1);
            REQUIRE(unbox_value<int>(bufferObj[1]) == 2);
            REQUIRE(unbox_value<int>(bufferObj[2]) == 3);
        }
        {
            std::array<IInspectable, 3> bufferObj{};
            REQUIRE(2 == objVec.GetMany(3, bufferObj));
            REQUIRE(unbox_value<int>(bufferObj[0]) == 4);
            REQUIRE(unbox_value<int>(bufferObj[1]) == 5);
            REQUIRE(bufferObj[2] == nullptr);
        }
    }
    {
        // ReplaceAll triggers events and invalidates iterators.
        IObservableVector<int> intVec = single_threaded_observable_vector<int>({ 1,2,3,4,5 });
        IObservableVector<IInspectable> objVec = intVec.as<IObservableVector<IInspectable>>();
        {
            IIterator<int> iterInt = intVec.First();
            IIterator<IInspectable> iterObj = objVec.First();
            REQUIRE(iterInt.HasCurrent());
            REQUIRE(iterObj.HasCurrent());
            bool intEvent{}, objEvent{};
            intVec.VectorChanged([&](IObservableVector<int> const& sender, IVectorChangedEventArgs const&)
                {
                    intEvent = sender.GetAt(0) == 123;
                    REQUIRE(sender == intVec);
                });
            objVec.VectorChanged([&](IObservableVector<IInspectable> const& sender, IVectorChangedEventArgs const&)
                {
                    objEvent = unbox_value<int>(sender.GetAt(0)) == 123;
                    REQUIRE(sender == objVec);
                });
            intVec.ReplaceAll({ 123 });
            REQUIRE(intEvent);
            REQUIRE(objEvent);
            REQUIRE_THROWS_AS(iterInt.HasCurrent(), hresult_changed_state);
            REQUIRE_THROWS_AS(iterObj.HasCurrent(), hresult_changed_state);
            REQUIRE(intVec.Size() == 1);
            REQUIRE(intVec.GetAt(0) == 123);
        }
        {
            IIterator<int> iterInt = intVec.First();
            IIterator<IInspectable> iterObj = objVec.First();
            REQUIRE(iterInt.HasCurrent());
            REQUIRE(iterObj.HasCurrent());
            bool intEvent{}, objEvent{};
            intVec.VectorChanged([&](IObservableVector<int> const& sender, IVectorChangedEventArgs const&)
                {
                    intEvent = sender.GetAt(0) == 123;
                    REQUIRE(sender == intVec);
                });
            objVec.VectorChanged([&](IObservableVector<IInspectable> const& sender, IVectorChangedEventArgs const&)
                {
                    objEvent = unbox_value<int>(sender.GetAt(0)) == 123;
                    REQUIRE(sender == objVec);
                });
            objVec.ReplaceAll({ box_value(123) });
            REQUIRE(intEvent);
            REQUIRE(objEvent);
            REQUIRE_THROWS_AS(iterInt.HasCurrent(), hresult_changed_state);
            REQUIRE_THROWS_AS(iterObj.HasCurrent(), hresult_changed_state);
            REQUIRE(intVec.Size() == 1);
            REQUIRE(intVec.GetAt(0) == 123);
        }
    }
}

#include "MeshMergingSettingsCustomization.h"
#include "Engine/MeshMerging.h"
