#define LOCTEXT_NAMESPACE "FMeshMergingSettingCustomization"

FMeshMergingSettingsObjectCustomization::~FMeshMergingSettingsObjectCustomization()
{
}

void FMeshMergingSettingsObjectCustomization::CustomizeDetails(IDetailLayoutBuilder& LayoutBuilder)
{
	TSharedRef<IPropertyHandle> MainSettingsProp = LayoutBuilder.GetProperty(FName("UMeshMergingSettingsObject.Settings"));

	const FName MeshSectionName("MeshSettings");
	IDetailCategoryBuilder& MeshSection = LayoutBuilder.EditCategory(MeshSectionName);
	TArray<TSharedRef<IPropertyHandle>> PropertyList;
	MeshSection.GetDefaultProperties(PropertyList, true, true);
	MeshSection.AddProperty(MainSettingsProp);

	const FName CategoryKey("Category");

	for (const TSharedRef<IPropertyHandle>& Prop : PropertyList)
	{
		FString SectionName = Prop->GetMetaData(CategoryKey);
		IDetailCategoryBuilder& TargetCategory = LayoutBuilder.EditCategory(*SectionName);
		IDetailPropertyRow& Row = TargetCategory.AddProperty(Prop);

		if (Prop->GetProperty()->GetFName() == GET_MEMBER_NAME_CHECKED(FMeshMergingSettings, SpecificLOD))
		{
			static const FName VisibilityTrigger = "EnumCondition";
			int32 TriggerValue = Prop->GetINTMetaData(VisibilityTrigger);
			Row.Visibility(TAttribute<EVisibility>::Create(
				TAttribute<EVisibility>::FGetter::CreateSP(this, &FMeshMergingSettingsObjectCustomization::IsPropertyVisible, TriggerValue)));
		}
		else if (Prop->GetProperty()->GetFName() == GET_MEMBER_NAME_CHECKED(FMeshMergingSettings, LODSelectionType))
		{
			SelectedLODProperty = Prop;

			TSharedPtr<FPropertyRestriction> Limitation = MakeShareable(new FPropertyRestriction(LOCTEXT("NotSupported","This option is not supported in Merge Actor")));
			const UEnum* const LODTypeEnum = FindObject<UEnum>(ANY_PACKAGE, TEXT("EMeshLODSelectionType"));
			Limitation->AddDisabledValue(LODTypeEnum->GetNameStringByValue((uint8)EMeshLODSelectionType::CalculateLOD));
			SelectedLODProperty->AddRestriction(Limitation.ToSharedRef());
		}
	}

	const FName MaterialSectionName("MaterialSettings");
	IDetailCategoryBuilder& MaterialSection = LayoutBuilder.EditCategory(MaterialSectionName);
	PropertyList.Reset();
	MaterialSection.GetDefaultProperties(PropertyList, true, true);

	for (TSharedRef<IPropertyHandle>& Prop : PropertyList)
	{
		FString SectionName = Prop->GetMetaData(CategoryKey);
		IDetailCategoryBuilder& TargetCategory = LayoutBuilder.EditCategory(*SectionName);
		IDetailPropertyRow& Row = TargetCategory.AddProperty(Prop);

		if (SectionName.Compare("MaterialSettings") == 0)
		{
			Row.IsEnabled(TAttribute<bool>::Create(
				TAttribute<bool>::FGetter::CreateSP(this, &FMeshMergingSettingsObjectCustomization::IsMaterialEditingAllowed)));
		}
	}
}

TSharedRef<IDetailCustomization> FMeshMergingSettingsObjectCustomization::MakeInstance()
{
	return MakeShareable(new FMeshMergingSettingsObjectCustomization);
}

EVisibility FMeshMergingSettingsObjectCustomization::IsPropertyVisible(const int32 ExpectedValue) const
{
	uint8 CurrentValue = 0;
	SelectedLODProperty->GetValue(CurrentValue);
	return (CurrentValue == ExpectedValue) ? EVisibility::Visible : EVisibility::Collapsed;
}

bool FMeshMergingSettingsObjectCustomization::IsMaterialEditingAllowed() const
{
	uint8 CurrentValue = 0;
	SelectedLODProperty->GetValue(CurrentValue);
	return !(CurrentValue == (uint8)EMeshLODSelectionType::AllLODs);
}

