// =============================================
// Packet flags (restructured bit manipulation)
// =============================================
static constexpr uint16_t FLAG_MASK(uint16_t bits, uint16_t shift) {
    return ((1u << bits) - 1u) << shift;
}

static constexpr uint16_t EXTRACT(uint16_t value, uint16_t mask, uint16_t shift) {
    return (value & mask) >> shift;
}

static constexpr uint16_t INSERT(uint16_t value, uint16_t mask, uint16_t shift) {
    return (value << shift) & mask;
}

// Reuse original constants but compute via helper macros for variation
static constexpr uint16_t FLAGS_PACKET_TYPE_BITS = 1;
static constexpr uint16_t FLAGS_PACKET_TYPE_SHIFT = 15;
static constexpr uint16_t FLAGS_PACKET_TYPE_MASK = FLAG_MASK(FLAGS_PACKET_TYPE_BITS, FLAGS_PACKET_TYPE_SHIFT);

static constexpr uint16_t FLAGS_OPCODE_BITS = 4;
static constexpr uint16_t FLAGS_OPCODE_SHIFT = 11;
static constexpr uint16_t FLAGS_OPCODE_MASK = FLAG_MASK(FLAGS_OPCODE_BITS, FLAGS_OPCODE_SHIFT);

static constexpr uint16_t FLAGS_AUTH_ANSWER_BITS = 1;
static constexpr uint16_t FLAGS_AUTH_ANSWER_SHIFT = 10;
static constexpr uint16_t FLAGS_AUTH_ANSWER_MASK = FLAG_MASK(FLAGS_AUTH_ANSWER_BITS, FLAGS_AUTH_ANSWER_SHIFT);

static constexpr uint16_t FLAGS_TRUNCATION_BITS = 1;
static constexpr uint16_t FLAGS_TRUNCATION_SHIFT = 9;
static constexpr uint16_t FLAGS_TRUNCATION_MASK = FLAG_MASK(FLAGS_TRUNCATION_BITS, FLAGS_TRUNCATION_SHIFT);

static constexpr uint16_t FLAGS_RECURSION_DESIRED_BITS = 1;
static constexpr uint16_t FLAGS_RECURSION_DESIRED_SHIFT = 8;
static constexpr uint16_t FLAGS_RECURSION_DESIRED_MASK = FLAG_MASK(FLAGS_RECURSION_DESIRED_BITS, FLAGS_RECURSION_DESIRED_SHIFT);

static constexpr uint16_t FLAGS_RECURSION_AVAILABLE_BITS = 1;
static constexpr uint16_t FLAGS_RECURSION_AVAILABLE_SHIFT = 7;
static constexpr uint16_t FLAGS_RECURSION_AVAILABLE_MASK = FLAG_MASK(FLAGS_RECURSION_AVAILABLE_BITS, FLAGS_RECURSION_AVAILABLE_SHIFT);

static constexpr uint16_t FLAGS_RESERVED_BITS = 3;
static constexpr uint16_t FLAGS_RESERVED_SHIFT = 4;
static constexpr uint16_t FLAGS_RESERVED_MASK = FLAG_MASK(FLAGS_RESERVED_BITS, FLAGS_RESERVED_SHIFT);

static constexpr uint16_t FLAGS_RESPONSE_CODE_BITS = 4;
static constexpr uint16_t FLAGS_RESPONSE_CODE_SHIFT = 0;
static constexpr uint16_t FLAGS_RESPONSE_CODE_MASK = FLAG_MASK(FLAGS_RESPONSE_CODE_BITS, FLAGS_RESPONSE_CODE_SHIFT);

void PacketFlags::setType(PacketType type) {
    value_ &= ~FLAGS_PACKET_TYPE_MASK;
    value_ |= INSERT(static_cast<uint16_t>(type), FLAGS_PACKET_TYPE_MASK, FLAGS_PACKET_TYPE_SHIFT);
}
PacketType PacketFlags::type() {
    return PacketType(EXTRACT(value_, FLAGS_PACKET_TYPE_MASK, FLAGS_PACKET_TYPE_SHIFT));
}

void PacketFlags::setOpcode(Opcode opcode) {
    value_ &= ~FLAGS_OPCODE_MASK;
    value_ |= INSERT(static_cast<uint16_t>(opcode), FLAGS_OPCODE_MASK, FLAGS_OPCODE_SHIFT);
}
Opcode PacketFlags::opcode() {
    return Opcode(EXTRACT(value_, FLAGS_OPCODE_MASK, FLAGS_OPCODE_SHIFT));
}

void PacketFlags::setAuthoritativeAnswer(bool authAnswer) {
    value_ &= ~FLAGS_AUTH_ANSWER_MASK;
    value_ |= INSERT(static_cast<uint16_t>(authAnswer), FLAGS_AUTH_ANSWER_MASK, FLAGS_AUTH_ANSWER_SHIFT);
}
bool PacketFlags::authoritativeAnswer() {
    return bool(EXTRACT(value_, FLAGS_AUTH_ANSWER_MASK, FLAGS_AUTH_ANSWER_SHIFT));
}

void PacketFlags::setTruncation(bool truncation) {
    value_ &= ~FLAGS_TRUNCATION_MASK;
    value_ |= INSERT(static_cast<uint16_t>(truncation), FLAGS_TRUNCATION_MASK, FLAGS_TRUNCATION_SHIFT);
}
bool PacketFlags::truncation() {
    return bool(EXTRACT(value_, FLAGS_TRUNCATION_MASK, FLAGS_TRUNCATION_SHIFT));
}

void PacketFlags::setRecursionDesired(bool recDesired) {
    value_ &= ~FLAGS_RECURSION_DESIRED_MASK;
    value_ |= INSERT(static_cast<uint16_t>(recDesired), FLAGS_RECURSION_DESIRED_MASK, FLAGS_RECURSION_DESIRED_SHIFT);
}
bool PacketFlags::recursionDesired() {
    return bool(EXTRACT(value_, FLAGS_RECURSION_DESIRED_MASK, FLAGS_RECURSION_DESIRED_SHIFT));
}

void PacketFlags::setRecursionAvailable(bool recAvail) {
    value_ &= ~FLAGS_RECURSION_AVAILABLE_MASK;
    value_ |= INSERT(static_cast<uint16_t>(recAvail), FLAGS_RECURSION_AVAILABLE_MASK, FLAGS_RECURSION_AVAILABLE_SHIFT);
}
bool PacketFlags::recursionAvailable() {
    return bool(EXTRACT(value_, FLAGS_RECURSION_AVAILABLE_MASK, FLAGS_RECURSION_AVAILABLE_SHIFT));
}

void PacketFlags::setReservedBits(ReservedFlagsTriple reserved) {
    value_ &= ~FLAGS_RESERVED_MASK;
    value_ |= INSERT(static_cast<uint16_t>(reserved), FLAGS_RESERVED_MASK, FLAGS_RESERVED_SHIFT);
}
ReservedFlagsTriple PacketFlags::reservedBits() {
    return ReservedFlagsTriple(EXTRACT(value_, FLAGS_RESERVED_MASK, FLAGS_RESERVED_SHIFT));
}

void PacketFlags::setResponseCode(ResponseCode code) {
    value_ &= ~FLAGS_RESPONSE_CODE_MASK;
    value_ |= INSERT(static_cast<uint16_t>(code), FLAGS_RESPONSE_CODE_MASK, FLAGS_RESPONSE_CODE_SHIFT);
}
ResponseCode PacketFlags::responseCode() {
    return ResponseCode(EXTRACT(value_, FLAGS_RESPONSE_CODE_MASK, FLAGS_RESPONSE_CODE_SHIFT));
}

// =============================================
// Record Data (toBytes) — refactored implementation
// =============================================
std::vector<uint8_t> RecordData::toBytes() const {
    std::vector<uint8_t> result;
    toBytes(result);
    return result;
}

void RecordDataIPv4::toBytes(std::vector<uint8_t> &v) const {
    v.clear();
    // Extract each byte using bitwise operations in reverse order
    uint32_t temp = addr_;
    for (int i = 3; i >= 0; --i) {
        v.push_back(static_cast<uint8_t>((temp >> (i * 8)) & 0xFF));
    }
}

void RecordDataGeneric::toBytes(std::vector<uint8_t> &v) const {
    v.clear();
    // Use range-based loop instead of std::copy
    for (auto byte : data_) {
        v.push_back(byte);
    }
}
