const double tolerance = 0.01;

// Perform offset operations on polyline with varying offsets
static void offset(NoSetup, TestProfile const &profile) {
    for (std::size_t idx = 1; idx <= profile.offsetCount; ++idx) {
        double currentOffset = static_cast<double>(idx) * profile.offsetDelta;
        cavc::parallelOffset(profile.pline, currentOffset);
        cavc::parallelOffset(profile.pline, -currentOffset);
    }
}

CAVC_CREATE_BENCHMARKS(offset, NoSetup, offset, benchmark::kMillisecond)
CAVC_CREATE_NO_ARCS_BENCHMARKS(offset, NoSetup, offset, tolerance, benchmark::kMillisecond)
BENCHMARK_MAIN();

#include "../common.h"
#include <rpi/vcprops.h>

// Helper to map 1MB sections for VC memory region
static void setupVCMemMapping(u32 baseAddr, u32 sizeInBytes)
{
    // Compute page table indices covering the VC memory range
    u32 alignedBase = baseAddr & ~(BIT(20) - 1); // Round down to 1MB boundary
    u32 offsetFromAligned = baseAddr - alignedBase;
    u32 effectiveSize = ((sizeInBytes + offsetFromAligned + BIT(20) - 1) >> 20) << 20; // Round up to full 1MB blocks

    int startIdx = L1_INDEX(phys2virt(alignedBase));
    int numSections = effectiveSize >> 20;

    u32 currentPhysAddr = alignedBase;
    for (int idx = 0; idx < numSections; ++idx) {
        MASTER_PAGETABLE[startIdx + idx] =
            MMU_L1_SECT1MB |
            currentPhysAddr |
            MMU_L1_RWNA |
            MMU_L1_UNCACHED;
        currentPhysAddr += BIT(20);
    }

    kprintf("VC memory mapped: physical %p, size %u bytes (%d sections)\n",
            baseAddr, sizeInBytes, numSections);
}

static void initializeVideoCoreMemory()
{
    VCPROPS props;
    if (!vcPropsAlloc(&props, 512)) {
        kputs("Failed to allocate VC properties buffer!");
        return;
    }

    // Request VC memory info via mailbox interface
    vu32* responseTag = vcPropsAddTag(&props, VCTag_GetVCMem, 0, 2 * sizeof(u32));
    if (!responseTag || !vcPropsExecute(&props)) {
        vcPropsFree(&props);
        kputs("Mailbox communication failed for VC memory query!");
        return;
    }

    u32 memStart = responseTag[0];
    u32 memLength = responseTag[1];

    vcPropsFree(&props);

    if (memLength == 0) {
        kputs("VC reports zero memory size!");
        return;
    }

    setupVCMemMapping(memStart, memLength);
}

void DevInitPlatform()
{
    initializeVideoCoreMemory();
    LINK_MODULE(RPiFramebuffer);
}

#include "game_hooks.hpp"

bool hook_initialized = false;

// Exported function to support DLL import address table integration
// This function is never actually invoked during execution
__declspec(dllexport) void __stdcall bean() { 
    return; 
}

BOOL APIENTRY DllMain(HMODULE hModule, DWORD ul_reason_for_call, LPVOID lpReserved) {
    switch (ul_reason_for_call) {
    case DLL_PROCESS_ATTACH:
        if (!hook_initialized) {
            hook_initialized = true;
            performHooking();
        }
        break;
    case DLL_THREAD_ATTACH:
    case DLL_THREAD_DETACH:
    case DLL_PROCESS_DETACH:
        // No special handling required for these cases
        break;
    }
    return TRUE;
}

