}

void pywrap_GLM(
    double* x, int x_row, int x_col,
    double* y, int y_row, int y_col,
    double* weight, int weight_len,
    int n, int p,
    int normalize_type, int algorithm_type, int model_type,
    int max_iter, int exchange_num, int path_type,
    bool is_warm_start, int ic_type, double ic_coef, int Kfold,
    int* gindex, int gindex_len,
    int* sequence, int sequence_len,
    double* lambda_sequence, int lambda_sequence_len,
    int* cv_fold_id, int cv_fold_id_len,
    int s_min, int s_max,
    double lambda_min, double lambda_max, int n_lambda,
    int screening_size,
    int* always_select, int always_select_len,
    int primary_model_fit_max_iter, double primary_model_fit_epsilon,
    bool early_stop, bool approximate_Newton, int thread,
    bool covariance_update, bool sparse_matrix,
    int splicing_type, int sub_search,
    int* A_init, int A_init_len,
    double* beta_out, int beta_out_len,
    double* coef0_out, int coef0_out_len,
    double* train_loss_out, int train_loss_out_len,
    double* test_loss_out, int test_loss_out_len,
    double* ic_out, int ic_out_len) {

    // Convert input arrays to Eigen types
    Eigen::MatrixXd designMatrix = Pointer2MatrixXd(x, x_row, x_col);
    Eigen::MatrixXd responseMatrix = Pointer2MatrixXd(y, y_row, y_col);
    Eigen::VectorXd weightsVec = Pointer2VectorXd(weight, weight_len);
    Eigen::VectorXi groupIdxVec = Pointer2VectorXi(gindex, gindex_len);
    Eigen::VectorXi seqVec = Pointer2VectorXi(sequence, sequence_len);
    Eigen::VectorXd lambdaSeqVec = Pointer2VectorXd(lambda_sequence, lambda_sequence_len);
    Eigen::VectorXi alwaysSelectVec = Pointer2VectorXi(always_select, always_select_len);
    Eigen::VectorXi foldIdVec = Pointer2VectorXi(cv_fold_id, cv_fold_id_len);
    Eigen::VectorXi initActiveSetVec = Pointer2VectorXi(A_init, A_init_len);

    // Call core abessGLM API
    List result = abessGLM_API(
        designMatrix, responseMatrix, n, p,
        normalize_type, weightsVec,
        algorithm_type, model_type,
        max_iter, exchange_num, path_type,
        is_warm_start, ic_type, ic_coef, Kfold,
        seqVec, lambdaSeqVec,
        s_min, s_max, lambda_min, lambda_max, n_lambda,
        screening_size, groupIdxVec, alwaysSelectVec,
        primary_model_fit_max_iter, primary_model_fit_epsilon,
        early_stop, approximate_Newton, thread,
        covariance_update, sparse_matrix,
        splicing_type, sub_search,
        foldIdVec, initActiveSetVec
    );

    // Handle output based on number of response variables
    if (y_col == 1) {
        Eigen::VectorXd estimatedBeta;
        double intercept = 0.0;
        double trainingLoss = 0.0;
        double testingLoss = 0.0;
        double informationCriterion = 0.0;

        result.get_value_by_name("beta", estimatedBeta);
        result.get_value_by_name("coef0", intercept);
        result.get_value_by_name("train_loss", trainingLoss);
        result.get_value_by_name("test_loss", testingLoss);
        result.get_value_by_name("ic", informationCriterion);

        VectorXd2Pointer(estimatedBeta, beta_out);
        *coef0_out = intercept;
        *train_loss_out = trainingLoss;
        *test_loss_out = testingLoss;
        *ic_out = informationCriterion;
    } else {
        Eigen::MatrixXd estimatedBeta;
        Eigen::VectorXd intercepts;
        double trainingLoss = 0.0;
        double testingLoss = 0.0;
        double informationCriterion = 0.0;

        result.get_value_by_name("beta", estimatedBeta);
        result.get_value_by_name("coef0", intercepts);
        result.get_value_by_name("train_loss", trainingLoss);
        result.get_value_by_name("test_loss", testingLoss);
        result.get_value_by_name("ic", informationCriterion);

        MatrixXd2Pointer(estimatedBeta, beta_out);
        VectorXd2Pointer(intercepts, coef0_out);
        train_loss_out[0] = trainingLoss;
        test_loss_out[0] = testingLoss;
        ic_out[0] = informationCriterion;
    }
}

void pywrap_PCA(
    double* x, int x_row, int x_col,
    double* weight, int weight_len,
    int n, int p,
    int normalize_type,
    double* sigma, int sigma_row, int sigma_col,
    int max_iter, int exchange_num, int path_type,
    bool is_warm_start, int ic_type, double ic_coef, int Kfold,
    int* gindex, int gindex_len,
    int* sequence, int sequence_row, int sequence_col,
    int* cv_fold_id, int cv_fold_id_len,
    int s_min, int s_max,
    int screening_size,
    int* always_select, int always_select_len,
    bool early_stop, int thread,
    bool sparse_matrix,
    int splicing_type, int sub_search,
    int pca_num,
    int* A_init, int A_init_len,
    double* beta_out, int beta_out_len,
    double* coef0_out, int coef0_out_len,
    double* train_loss_out, int train_loss_out_len,
    double* test_loss_out, int test_loss_out_len,
    double* ic_out, int ic_out_len) {

    // Prepare data matrices
    Eigen::MatrixXd dataMat = Pointer2MatrixXd(x, x_row, x_col);
    Eigen::MatrixXd covMat = Pointer2MatrixXd(sigma, sigma_row, sigma_col);
    Eigen::MatrixXi seqMat = Pointer2MatrixXi(sequence, sequence_row, sequence_col);
    Eigen::VectorXd weights = Pointer2VectorXd(weight, weight_len);
    Eigen::VectorXi groupIndices = Pointer2VectorXi(gindex, gindex_len);
    Eigen::VectorXi alwaysIncluded = Pointer2VectorXi(always_select, always_select_len);
    Eigen::VectorXi foldAssignments = Pointer2VectorXi(cv_fold_id, cv_fold_id_len);
    Eigen::VectorXi initialSupport = Pointer2VectorXi(A_init, A_init_len);

    // Run PCA abess routine
    List pcaResult = abessPCA_API(
        dataMat, n, p,
        normalize_type, weights,
        covMat,
        max_iter, exchange_num, path_type,
        is_warm_start, ic_type, ic_coef, Kfold,
        seqMat,
        s_min, s_max, screening_size,
        groupIndices, alwaysIncluded,
        early_stop, thread,
        sparse_matrix, splicing_type, sub_search,
        foldAssignments, pca_num,
        initialSupport
    );

    // Extract beta depending on number of components requested
    Eigen::MatrixXd loadings;
    if (pca_num == 1) {
        loadings.resize(p, 1);
        pcaResult.get_value_by_name("beta", loadings);
        VectorXd2Pointer(loadings.col(0), beta_out);
    } else {
        loadings.resize(p, pca_num);
        pcaResult.get_value_by_name("beta", loadings);
        MatrixXd2Pointer(loadings, beta_out);
    }

    // Extract scalar outputs
    double intercept = 0.0;
    double trainingLoss = 0.0;
    double testingLoss = 0.0;
    double informationCriterion = 0.0;

    pcaResult.get_value_by_name("coef0", intercept);
    pcaResult.get_value_by_name("train_loss", trainingLoss);
    pcaResult.get_value_by_name("test_loss", testingLoss);
    pcaResult.get_value_by_name("ic", informationCriterion);

    *coef0_out = intercept;
    *train_loss_out = trainingLoss;
    *test_loss_out = testingLoss;
    *ic_out = informationCriterion;
}

void pywrap_RPCA(
    double* x, int x_row, int x_col,
    int n, int p,
    int normalize_type,
    int max_iter, int exchange_num, int path_type,
    bool is_warm_start, int ic_type, double ic_coef,
    int* gindex, int gindex_len,
    int* sequence, int sequence_len,
    double* lambda_sequence, int lambda_sequence_len,
    int s_min, int s_max,
    double lambda_min, double lambda_max, int n_lambda,
    int screening_size,
    int* always_select, int always_select_len,
    int primary_model_fit_max_iter, double primary_model_fit_epsilon,
    bool early_stop, int thread,
    bool sparse_matrix,
    int splicing_type, int sub_search,
    int* A_init, int A_init_len,
    double* beta_out, int beta_out_len,
    double* coef0_out, int coef0_out_len,
    double* train_loss_out, int train_loss_out_len,
    double* test_loss_out, int test_loss_out_len,
    double* ic_out, int ic_out_len) {

    // Map inputs to Eigen objects
    Eigen::MatrixXd obsData = Pointer2MatrixXd(x, x_row, x_col);
    Eigen::VectorXi seqVec = Pointer2VectorXi(sequence, sequence_len);
    Eigen::VectorXd lambdaVec = Pointer2VectorXd(lambda_sequence, lambda_sequence_len);
    Eigen::VectorXi grpIdx = Pointer2VectorXi(gindex, gindex_len);
    Eigen::VectorXi fixedVars = Pointer2VectorXi(always_select, always_select_len);
    Eigen::VectorXi warmStartSet = Pointer2VectorXi(A_init, A_init_len);

    // Perform RPCA optimization
    List rpcaResult = abessRPCA_API(
        obsData, n, p,
        max_iter, exchange_num, path_type,
        is_warm_start, ic_type, ic_coef,
        seqVec, lambdaVec,
        s_min, s_max, lambda_min, lambda_max, n_lambda,
        screening_size,
        primary_model_fit_max_iter, primary_model_fit_epsilon,
        grpIdx, fixedVars,
        early_stop, thread,
        sparse_matrix, splicing_type, sub_search,
        warmStartSet
    );

    // Retrieve results
    Eigen::VectorXd estimatedBeta;
    double intercept = 0.0;
    double trainingLoss = 0.0;
    double testingLoss = 0.0;
    double informationCriterion = 0.0;

    rpcaResult.get_value_by_name("beta", estimatedBeta);
    rpcaResult.get_value_by_name("coef0", intercept);
    rpcaResult.get_value_by_name("train_loss", trainingLoss);
    rpcaResult.get_value_by_name("test_loss", testingLoss);
    rpcaResult.get_value_by_name("ic", informationCriterion);

    VectorXd2Pointer(estimatedBeta, beta_out);
    *coef0_out = intercept;
    *train_loss_out = trainingLoss;
    *test_loss_out = testingLoss;
    *ic_out = informationCriterion;
}

