    LuaDebug::AddDebug(lua);

    LuaComponents::AddComponentFunctions(lua, engineRef.registry);
    LuaUI::AddComponentFunctions(lua, engineRef.registry, engineRef.ui);

    LuaTime::AddTime(lua, engineRef.timer);
    LuaWorld::AddWorld(lua, engineRef);
    LuaWindow::AddWindowInterface(lua, engineRef.window);
}

