    bool IsCompressed(GLenum format)
    {
        // Check if format belongs to S3TC DXT or ETC1 compression families
        if(format == GL_COMPRESSED_RGB_S3TC_DXT1_EXT) return true;
        if(format == GL_COMPRESSED_RGBA_S3TC_DXT1_EXT) return true;
        if(format == GL_ETC1_RGB8_OES) return true;
        return false;
    }

    bool IsSizedInternalFormat(GLint internalformat)
    {
        // List of sized internal formats supported
        if(internalformat == GL_ALPHA8_EXT) return true;
        if(internalformat == GL_LUMINANCE8_ALPHA8_EXT) return true;
        if(internalformat == GL_LUMINANCE8_EXT) return true;
        if(internalformat == GL_RGBA4_OES) return true;
        if(internalformat == GL_RGB5_A1_OES) return true;
        if(internalformat == GL_RGB565_OES) return true;
        if(internalformat == GL_RGB8_OES) return true;
        if(internalformat == GL_RGBA8_OES) return true;
        if(internalformat == GL_BGRA8_EXT) return true;   // GL_APPLE_texture_format_BGRA8888
        if(internalformat == GL_DEPTH_COMPONENT16_OES) return true;
        if(internalformat == GL_STENCIL_INDEX8_OES) return true;
        if(internalformat == GL_DEPTH24_STENCIL8_OES) return true;
        return false;
    }

    GLenum ValidateSubImageParams(bool compressed, bool copy, GLenum target, GLint level, GLint xoffset, GLint yoffset,
                                  GLsizei width, GLsizei height, GLenum format, GLenum type, Texture *texture)
    {
        if(!texture)
        {
            return GL_INVALID_OPERATION;
        }

        GLenum sizedInternalFormat = texture->getFormat(target, level);

        if(compressed)
        {
            if(format != sizedInternalFormat)
            {
                return GL_INVALID_OPERATION;
            }

            // Compressed textures require dimensions to be multiples of 4, except for the base level
            bool widthValid = (width % 4 == 0) || (width == texture->getWidth(target, 0));
            bool heightValid = (height % 4 == 0) || (height == texture->getHeight(target, 0));

            if(!widthValid || !heightValid)
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(!copy)   // CopyTexSubImage doesn't have format/type parameters.
        {
            GLenum validationError = ValidateTextureFormatType(format, type, sizedInternalFormat, target);
            if(validationError != GL_NO_ERROR)
            {
                return validationError;
            }
        }

        // Check bounds against texture dimensions
        if(xoffset + width > texture->getWidth(target, level) ||
           yoffset + height > texture->getHeight(target, level))
        {
            return GL_INVALID_VALUE;
        }

        return GL_NO_ERROR;
    }

