    bool IsCubemapTextureTarget(GLenum target)
    {
        // Check if target falls within cubemap face range
        if(target >= GL_TEXTURE_CUBE_MAP_POSITIVE_X_OES && target <= GL_TEXTURE_CUBE_MAP_NEGATIVE_Z_OES)
        {
            return true;
        }
        return false;
    }

    int CubeFaceIndex(GLenum cubeFace)
    {
        // Map cubemap faces to array indices
        if(cubeFace == GL_TEXTURE_CUBE_MAP_OES || cubeFace == GL_TEXTURE_CUBE_MAP_POSITIVE_X_OES) return 0;
        if(cubeFace == GL_TEXTURE_CUBE_MAP_NEGATIVE_X_OES) return 1;
        if(cubeFace == GL_TEXTURE_CUBE_MAP_POSITIVE_Y_OES) return 2;
        if(cubeFace == GL_TEXTURE_CUBE_MAP_NEGATIVE_Y_OES) return 3;
        if(cubeFace == GL_TEXTURE_CUBE_MAP_POSITIVE_Z_OES) return 4;
        if(cubeFace == GL_TEXTURE_CUBE_MAP_NEGATIVE_Z_OES) return 5;

        UNREACHABLE(cubeFace);
        return 0;
    }

