    // Verify that format/type are one of the combinations from table 3.4.
    GLenum ValidateTextureFormatType(GLenum format, GLenum type, GLint internalformat, GLenum target)
    {
        // First validate type values
        if(type != GL_UNSIGNED_BYTE &&
           type != GL_UNSIGNED_SHORT_4_4_4_4 &&
           type != GL_UNSIGNED_SHORT_5_5_5_1 &&
           type != GL_UNSIGNED_SHORT_5_6_5 &&
           type != GL_UNSIGNED_INT_24_8_OES)
        {
            return GL_INVALID_ENUM;
        }

        // Then validate format values
        if(format != GL_ALPHA &&
           format != GL_RGB &&
           format != GL_RGBA &&
           format != GL_LUMINANCE &&
           format != GL_LUMINANCE_ALPHA &&
           format != GL_BGRA_EXT)
        {
            // Special case for depth-stencil
            if(format != GL_DEPTH_STENCIL_OES)
            {
                return GL_INVALID_ENUM;
            }

            // Depth-stencil only valid for 2D textures
            if(target != GL_TEXTURE_2D)
            {
                return GL_INVALID_OPERATION;
            }
        }

        // Check internal format compatibility
        if((GLenum)internalformat != format)
        {
            if(gl::IsUnsizedInternalFormat(internalformat))
            {
                return GL_INVALID_OPERATION;
            }
            if(!IsSizedInternalFormat(internalformat))
            {
                return GL_INVALID_VALUE;
            }
        }

        // When internalformat matches format, validate combinations [OpenGL ES 1.1 Table 3.3]
        if((GLenum)internalformat == format)
        {
            if(format == GL_RGBA)
            {
                if(type != GL_UNSIGNED_BYTE &&
                   type != GL_UNSIGNED_SHORT_4_4_4_4 &&
                   type != GL_UNSIGNED_SHORT_5_5_5_1)
                {
                    return GL_INVALID_OPERATION;
                }
            }
            else if(format == GL_RGB)
            {
                if(type != GL_UNSIGNED_BYTE &&
                   type != GL_UNSIGNED_SHORT_5_6_5)
                {
                    return GL_INVALID_OPERATION;
                }
            }
            else if(format == GL_LUMINANCE_ALPHA || format == GL_LUMINANCE || format == GL_ALPHA)
            {
                if(type != GL_UNSIGNED_BYTE)
                {
                    return GL_INVALID_OPERATION;
                }
            }
            else if(format == GL_DEPTH_STENCIL_OES)
            {
                if(type != GL_UNSIGNED_INT_24_8_OES)
                {
                    return GL_INVALID_OPERATION;
                }
            }
            else if(format == GL_BGRA_EXT)
            {
                if(type != GL_UNSIGNED_BYTE)
                {
                    return GL_INVALID_OPERATION;
                }
            }
            else
            {
                UNREACHABLE(format);
                return GL_INVALID_ENUM;
            }
            return GL_NO_ERROR;
        }

        // Validate format, type, and sized internalformat combinations [OpenGL ES 3.0 Table 3.2]
        bool validSizedInternalformat = false;

        if(format == GL_RGBA)
        {
            if(type == GL_UNSIGNED_BYTE)
            {
                validSizedInternalformat = (internalformat == GL_RGBA8_OES || 
                                           internalformat == GL_RGB5_A1_OES || 
                                           internalformat == GL_RGBA4_OES);
            }
            else if(type == GL_UNSIGNED_SHORT_4_4_4_4)
            {
                validSizedInternalformat = (internalformat == GL_RGBA4_OES);
            }
            else if(type == GL_UNSIGNED_SHORT_5_5_5_1)
            {
                validSizedInternalformat = (internalformat == GL_RGB5_A1_OES);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(format == GL_RGB)
        {
            if(type == GL_UNSIGNED_BYTE)
            {
                validSizedInternalformat = (internalformat == GL_RGB8_OES || 
                                           internalformat == GL_RGB565_OES);
            }
            else if(type == GL_UNSIGNED_SHORT_5_6_5)
            {
                validSizedInternalformat = (internalformat == GL_RGB565_OES);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(format == GL_DEPTH_STENCIL_OES)
        {
            if(type == GL_UNSIGNED_INT_24_8_OES)
            {
                validSizedInternalformat = (internalformat == GL_DEPTH24_STENCIL8_OES);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(format == GL_LUMINANCE_ALPHA)
        {
            if(type == GL_UNSIGNED_BYTE)
            {
                validSizedInternalformat = (internalformat == GL_LUMINANCE8_ALPHA8_EXT);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(format == GL_LUMINANCE)
        {
            if(type == GL_UNSIGNED_BYTE)
            {
                validSizedInternalformat = (internalformat == GL_LUMINANCE8_EXT);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(format == GL_ALPHA)
        {
            if(type == GL_UNSIGNED_BYTE)
            {
                validSizedInternalformat = (internalformat == GL_ALPHA8_EXT);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else if(format == GL_BGRA_EXT)
        {
            if(type == GL_UNSIGNED_BYTE)
            {
                validSizedInternalformat = (internalformat == GL_BGRA8_EXT);
            }
            else
            {
                return GL_INVALID_OPERATION;
            }
        }
        else
        {
            UNREACHABLE(format);
            return GL_INVALID_ENUM;
        }

        if(!validSizedInternalformat)
        {
            return GL_INVALID_OPERATION;
        }

        return GL_NO_ERROR;
    }

    bool IsColorRenderable(GLint internalformat)
    {
        if(internalformat == GL_RGBA4_OES) return true;
        if(internalformat == GL_RGB5_A1_OES) return true;
        if(internalformat == GL_RGB565_OES) return true;
        if(internalformat == GL_RGB8_OES) return true;
        if(internalformat == GL_RGBA8_OES) return true;

        if(internalformat == GL_DEPTH_COMPONENT16_OES) return false;
        if(internalformat == GL_STENCIL_INDEX8_OES) return false;
        if(internalformat == GL_DEPTH24_STENCIL8_OES) return false;

        UNIMPLEMENTED();
        return false;
    }

