    {
        if(internalformat == GL_DEPTH_COMPONENT16_OES) return true;
        if(internalformat == GL_DEPTH24_STENCIL8_OES) return true;

        if(internalformat == GL_STENCIL_INDEX8_OES) return false;
        if(internalformat == GL_RGBA4_OES) return false;
        if(internalformat == GL_RGB5_A1_OES) return false;
        if(internalformat == GL_RGB565_OES) return false;
        if(internalformat == GL_RGB8_OES) return false;
        if(internalformat == GL_RGBA8_OES) return false;

        UNIMPLEMENTED();
        return false;
    }

    bool IsStencilRenderable(GLint internalformat)
    {
        if(internalformat == GL_STENCIL_INDEX8_OES) return true;
        if(internalformat == GL_DEPTH24_STENCIL8_OES) return true;

        if(internalformat == GL_RGBA4_OES) return false;
        if(internalformat == GL_RGB5_A1_OES) return false;
        if(internalformat == GL_RGB565_OES) return false;
        if(internalformat == GL_RGB8_OES) return false;
        if(internalformat == GL_RGBA8_OES) return false;
        if(internalformat == GL_DEPTH_COMPONENT16_OES) return false;

        UNIMPLEMENTED();
        return false;
    }

