    sw::DepthCompareMode ConvertDepthComparison(GLenum comparison)
    {
        if(comparison == GL_NEVER) return sw::DEPTH_NEVER;
        if(comparison == GL_ALWAYS) return sw::DEPTH_ALWAYS;
        if(comparison == GL_LESS) return sw::DEPTH_LESS;
        if(comparison == GL_LEQUAL) return sw::DEPTH_LESSEQUAL;
        if(comparison == GL_EQUAL) return sw::DEPTH_EQUAL;
        if(comparison == GL_GREATER) return sw::DEPTH_GREATER;
        if(comparison == GL_GEQUAL) return sw::DEPTH_GREATEREQUAL;
        if(comparison == GL_NOTEQUAL) return sw::DEPTH_NOTEQUAL;

        UNREACHABLE(comparison);
        return sw::DEPTH_ALWAYS;
    }

