    sw::CullMode ConvertCullMode(GLenum cullFace, GLenum frontFace)
    {
        if(cullFace == GL_FRONT)
        {
            return (frontFace == GL_CCW ? sw::CULL_CLOCKWISE : sw::CULL_COUNTERCLOCKWISE);
        }
        if(cullFace == GL_BACK)
        {
            return (frontFace == GL_CCW ? sw::CULL_COUNTERCLOCKWISE : sw::CULL_CLOCKWISE);
        }
        if(cullFace == GL_FRONT_AND_BACK)
        {
            return sw::CULL_NONE;
        }

        UNREACHABLE(cullFace);
        return sw::CULL_COUNTERCLOCKWISE;
    }

    unsigned int ConvertColorMask(bool red, bool green, bool blue, bool alpha)
    {
        unsigned int mask = 0;
        if(red) mask |= 0x00000001;
        if(green) mask |= 0x00000002;
        if(blue) mask |= 0x00000004;
        if(alpha) mask |= 0x00000008;
        return mask;
    }

    sw::MipmapType ConvertMipMapFilter(GLenum minFilter)
    {
        if(minFilter == GL_NEAREST || minFilter == GL_LINEAR)
        {
            return sw::MIPMAP_NONE;
        }
        if(minFilter == GL_NEAREST_MIPMAP_NEAREST || minFilter == GL_LINEAR_MIPMAP_NEAREST)
        {
            return sw::MIPMAP_POINT;
        }
        if(minFilter == GL_NEAREST_MIPMAP_LINEAR || minFilter == GL_LINEAR_MIPMAP_LINEAR)
        {
            return sw::MIPMAP_LINEAR;
        }

        UNREACHABLE(minFilter);
        return sw::MIPMAP_NONE;
    }

    sw::FilterType ConvertTextureFilter(GLenum minFilter, GLenum magFilter, float maxAnisotropy)
    {
        if(maxAnisotropy > 1.0f)
        {
            return sw::FILTER_ANISOTROPIC;
        }

        sw::FilterType magFilterType = sw::FILTER_POINT;
        if(magFilter == GL_NEAREST) magFilterType = sw::FILTER_POINT;
        else if(magFilter == GL_LINEAR) magFilterType = sw::FILTER_LINEAR;
        else UNREACHABLE(magFilter);

        if(minFilter == GL_NEAREST || minFilter == GL_NEAREST_MIPMAP_NEAREST || minFilter == GL_NEAREST_MIPMAP_LINEAR)
        {
            return (magFilterType == sw::FILTER_POINT) ? sw::FILTER_POINT : sw::FILTER_MIN_POINT_MAG_LINEAR;
        }
        if(minFilter == GL_LINEAR || minFilter == GL_LINEAR_MIPMAP_NEAREST || minFilter == GL_LINEAR_MIPMAP_LINEAR)
        {
            return (magFilterType == sw::FILTER_POINT) ? sw::FILTER_MIN_LINEAR_MAG_POINT : sw::FILTER_LINEAR;
        }

        UNREACHABLE(minFilter);
        return (magFilterType == sw::FILTER_POINT) ? sw::FILTER_POINT : sw::FILTER_MIN_POINT_MAG_LINEAR;
    }

    bool ConvertPrimitiveType(GLenum primitiveType, GLsizei elementCount, GLenum elementType,  
                             sw::DrawType &drawType, int &primitiveCount)
    {
        switch(primitiveType)
        {
        case GL_POINTS:
            drawType = sw::DRAW_POINTLIST;
            primitiveCount = elementCount;
            break;
        case GL_LINES:
            drawType = sw::DRAW_LINELIST;
            primitiveCount = elementCount / 2;
            break;
        case GL_LINE_LOOP:
            drawType = sw::DRAW_LINELOOP;
            primitiveCount = elementCount;
            break;
        case GL_LINE_STRIP:
            drawType = sw::DRAW_LINESTRIP;
            primitiveCount = elementCount - 1;
            break;
        case GL_TRIANGLES:
            drawType = sw::DRAW_TRIANGLELIST;
            primitiveCount = elementCount / 3;
            break;
        case GL_TRIANGLE_STRIP:
            drawType = sw::DRAW_TRIANGLESTRIP;
            primitiveCount = elementCount - 2;
            break;
        case GL_TRIANGLE_FAN:
            drawType = sw::DRAW_TRIANGLEFAN;
            primitiveCount = elementCount - 2;
            break;
        default:
            return false;
        }

        sw::DrawType elementSize;
        switch(elementType)
        {
        case GL_NONE_OES:       elementSize = sw::DRAW_NONINDEXED; break;
        case GL_UNSIGNED_BYTE:  elementSize = sw::DRAW_INDEXED8;   break;
        case GL_UNSIGNED_SHORT: elementSize = sw::DRAW_INDEXED16;  break;
        case GL_UNSIGNED_INT:   elementSize = sw::DRAW_INDEXED32;  break;
        default: return false;
        }

        drawType = sw::DrawType(drawType | elementSize);
        return true;
    }

    sw::TextureStage::StageOperation ConvertCombineOperation(GLenum operation)
    {
        if(operation == GL_REPLACE) return sw::TextureStage::STAGE_SELECTARG1;
        if(operation == GL_MODULATE) return sw::TextureStage::STAGE_MODULATE;
        if(operation == GL_ADD) return sw::TextureStage::STAGE_ADD;
        if(operation == GL_ADD_SIGNED) return sw::TextureStage::STAGE_ADDSIGNED;
        if(operation == GL_INTERPOLATE) return sw::TextureStage::STAGE_LERP;
        if(operation == GL_SUBTRACT) return sw::TextureStage::STAGE_SUBTRACT;
        if(operation == GL_DOT3_RGB || operation == GL_DOT3_RGBA) return sw::TextureStage::STAGE_DOT3;

        UNREACHABLE(operation);
        return sw::TextureStage::STAGE_SELECTARG1;
    }

    sw::TextureStage::SourceArgument ConvertSourceArgument(GLenum argument)
    {
        if(argument == GL_TEXTURE) return sw::TextureStage::SOURCE_TEXTURE;
        if(argument == GL_CONSTANT) return sw::TextureStage::SOURCE_CONSTANT;
        if(argument == GL_PRIMARY_COLOR) return sw::TextureStage::SOURCE_DIFFUSE;
        if(argument == GL_PREVIOUS) return sw::TextureStage::SOURCE_CURRENT;

        UNREACHABLE(argument);
        return sw::TextureStage::SOURCE_CURRENT;
    }

    sw::TextureStage::ArgumentModifier ConvertSourceOperand(GLenum operand)
    {
        if(operand == GL_SRC_COLOR) return sw::TextureStage::MODIFIER_COLOR;
        if(operand == GL_ONE_MINUS_SRC_COLOR) return sw::TextureStage::MODIFIER_INVCOLOR;
        if(operand == GL_SRC_ALPHA) return sw::TextureStage::MODIFIER_ALPHA;
        if(operand == GL_ONE_MINUS_SRC_ALPHA) return sw::TextureStage::MODIFIER_INVALPHA;

        UNREACHABLE(operand);
        return sw::TextureStage::MODIFIER_COLOR;
    }
}

namespace sw2es
{
    GLenum ConvertBackBufferFormat(sw::Format format)
    {
        if(format == sw::FORMAT_A4R4G4B4) return GL_RGBA4_OES;
        if(format == sw::FORMAT_A8R8G8B8) return GL_RGBA8_OES;
        if(format == sw::FORMAT_A8B8G8R8) return GL_RGBA8_OES;
        if(format == sw::FORMAT_A1R5G5B5) return GL_RGB5_A1_OES;
        if(format == sw::FORMAT_R5G6B5) return GL_RGB565_OES;
        if(format == sw::FORMAT_X8R8G8B8) return GL_RGB8_OES;
        if(format == sw::FORMAT_X8B8G8R8) return GL_RGB8_OES;

        UNREACHABLE(format);
        return GL_RGBA4_OES;
    }

    GLenum ConvertDepthStencilFormat(sw::Format format)
    {
        if(format == sw::FORMAT_D16 || format == sw::FORMAT_D24X8 || format == sw::FORMAT_D32)
        {
            return GL_DEPTH_COMPONENT16_OES;
        }
        if(format == sw::FORMAT_D24S8)
        {
            return GL_DEPTH24_STENCIL8_OES;
        }

        UNREACHABLE(format);
        return GL_DEPTH24_STENCIL8_OES;
    }
}

#include "test_generator2.h"

class TestPtnGenerator : public TestGenerator {
public:
  void setInitialRegValue() override {
    setDumpZRegMode(SP_DT);
    setInputZregAllRandomHex();

    // Initialize ZReg[15] with a fixed pattern: 0x0706050403020100
    for (int idx = 0; idx < 16; ++idx) {
      inputZReg[15].us_dt[idx] =
          (7u << 28) | (6u << 24) | (5u << 20) | (4u << 16) |
          (3u << 12) | (2u << 8)  | (1u << 4)  | (0u << 0);
    }

    // Populate special values into ZReg[0..13]
    for (int i = 0; i < 14; ++i) {
      auto &zr = inputZReg[i];
      zr.us_dt[0] = uint32_t(0x7f800001); // SNaN
      zr.us_dt[1] = uint32_t(0x7fc00001); // QNaN
      zr.sp_dt[2] = 0.0f;                 // zero
      zr.sp_dt[3] = 1.0f;                 // positive one
      zr.us_dt[4] = uint32_t(0x7f800000); // negative infinity (bit pattern)
      zr.us_dt[5] = uint32_t(0xff800000); // positive infinity (bit pattern)
      zr.sp_dt[6] = -123.45f;             // negative value
      zr.sp_dt[7] = 123.45f;              // positive value
      zr.us_dt[8]  = uint32_t(0x00000001);
      zr.us_dt[9]  = uint32_t(0x80000001);
      zr.us_dt[10] = uint32_t(0x7f800000);
      zr.us_dt[11] = uint32_t(0xff800000);
      zr.us_dt[12] = uint32_t(0xff800001); // SNaN
      zr.us_dt[13] = uint32_t(0xffc00001); // QNaN
    }
  }

  void setCheckRegFlagAll() override {
    // Placeholder: no specific check flags needed for this test pattern
  }

private:
  // Helper to reduce duplication in genJitTestCode()
  void emitFixupOp(int dstIdx, int src1Idx, int src2Idx, uint8_t imm8) {
    vfixupimmps(Zmm(dstIdx), Zmm(src1Idx), Zmm(src2Idx), imm8);
  }

public:
  void genJitTestCode() override {
    // Emit multiple vfixupimmps instructions using helper function
    emitFixupOp(16, 0, 15, 0);
    emitFixupOp(17, 1, 15, 0);
    emitFixupOp(18, 2, 15, 0);
    emitFixupOp(19, 3, 15, 0);
    emitFixupOp(20, 4, 15, 0);
    emitFixupOp(21, 5, 15, 0);
    emitFixupOp(22, 6, 15, 0);
    emitFixupOp(23, 7, 15, 0);
    emitFixupOp(24, 8, 15, 0);
    emitFixupOp(25, 9, 15, 0);
    emitFixupOp(26, 10, 15, 0);
    emitFixupOp(27, 11, 15, 0);
    emitFixupOp(28, 12, 15, 0);
    emitFixupOp(29, 13, 15, 0);
  }
};

int main(int argc, char *argv[]) {
  TestPtnGenerator generator;
  generator.parseArgs(argc, argv);

  void (*jitFunc)();
  if (generator.isOutputJitOn()) {
    jitFunc = reinterpret_cast<void(*)()>(generator.gen());
  }

  generator.dumpJitCode();

  if (generator.isExecJitOn()) {
    generator.dumpInputReg();
    jitFunc();               // Execute generated JIT code
    generator.dumpOutputReg();
    generator.dumpCheckReg();
  }

  return 0;
}

