CRenderTarget::CRenderTarget()
{
    InitializeRenderTarget(0, 0, RTKIND_COLOR);
}

CRenderTarget::CRenderTarget(unsigned int width, unsigned int height, UCHAR type)
{
    InitializeRenderTarget(width, height, type);
}

CRenderTarget::~CRenderTarget()
{
    Cleanup();
}

void CRenderTarget::Cleanup()
{
    if (ReleaseReference())
    {
        LPDIRECT3DSURFACE9 currentTarget = nullptr;
        RENDERER->GetDevice()->GetRenderTarget(0, &currentTarget);

        if (currentTarget == mSurfaceHandle)
        {
            RENDERER->SetRenderTarget(nullptr);
        }

        SAFE_RELEASE(mTextureHandle);
        SAFE_RELEASE(mSurfaceHandle);
        SAFE_RELEASE(mDepthStencilSurfaceHandle);
        delete this;
    }
}

void CRenderTarget::Activate()
{
    RENDERER->SetRenderTarget(this);
}

void CRenderTarget::InitializeRenderTarget(unsigned int width, unsigned int height, UCHAR kind)
{
    mKind = kind;
    mTextureHandle = nullptr;
    mSurfaceHandle = nullptr;
    mDepthStencilSurfaceHandle = nullptr;

    D3DSURFACE_DESC displayDesc = RENDERER->GetDisplayDesc();

    // Supported render target formats
    D3DFORMAT supportedFormats[] = { 
        displayDesc.Format, 
        D3DFMT_R32F, 
        D3DFMT_A16B16G16R16F, 
        D3DFMT_A32B32G32R32F 
    };

    // Determine dimensions: use provided values or fall back to display resolution
    unsigned int finalWidth = (width != 0u) ? width : displayDesc.Width;
    unsigned int finalHeight = (height != 0u) ? height : displayDesc.Height;

    HRESULT hr = RENDERER->GetDevice()->CreateTexture(
        finalWidth,
        finalHeight,
        1,
        D3DUSAGE_RENDERTARGET,
        supportedFormats[kind],
        D3DPOOL_DEFAULT,
        &mTextureHandle,
        nullptr
    );

    if (FAILED(hr))
    {
        MessageBoxA(nullptr, "Failed to create render target!", "Renderer error", MB_OK);
        ENGINE->Shutdown();
        return;
    }

    // Create depth-stencil surface only for non-depth render targets
    if (kind != RTKIND_DEPTH)
    {
        RENDERER->GetDevice()->CreateDepthStencilSurface(
            finalWidth,
            finalHeight,
            D3DFMT_D24S8,
            D3DMULTISAMPLE_NONE,
            0,
            TRUE,
            &mDepthStencilSurfaceHandle,
            nullptr
        );
    }

    // Retrieve the top-level surface from the texture
    mTextureHandle->GetSurfaceLevel(0, &mSurfaceHandle);
}

