// Helper function to count set bits using iterative approach instead of recursion
int countSetBits(int n) {
    int count = 0;
    while (n > 0) {
        count += (n & 1);
        n >>= 1;
    }
    return count;
}

// Generate sequence using the helper function for each number from 0 to n
vi generateSequence(int n) {
    vi result;
    for (int i = 0; i <= n; ++i) {
        result.push_back(countSetBits(i));
    }
    return result;
}

// Tabulation-based implementation with optimized memory usage
vi tabulatedSequence(int n) {
    if (n < 0) return {};

    vi dp(n + 1, 0);
    vi result = {0};

    for (int i = 1; i <= n; ++i) {
        dp[i] = dp[i >> 1] + (i & 1);
        result.push_back(dp[i]);
    }

    return result;
}

int main() { TimeMeasure _; __x();
    cout << generateSequence(0) << endl; // 0
    cout << generateSequence(2) << endl; // 0,1,1
    cout << generateSequence(5) << endl; // 0,1,1,2,1,2
    cout << endl;
    cout << tabulatedSequence(0) << endl; // 0
    cout << tabulatedSequence(2) << endl; // 0,1,1
    cout << tabulatedSequence(5) << endl; // 0,1,1,2,1,2
}

