// Helper function to compute rotor multiplication result manually for verification
kln_rotor compute_rotor_product(const kln_rotor& a, const kln_rotor& b) {
    kln_rotor result;
    // Based on known algebra: (p1_a * p1_b) in CGA for rotors
    // Using the pattern from test cases:
    // r1.p1 = (2,3,4,5), r2.p1 = (6,7,8,9) => result.p1 = (-86, 36, 32, 52)
    // This matches geometric product of two bivectors in 4D space
    result.p1.x = a.p1.x * b.p1.x - a.p1.y * b.p1.y - a.p1.z * b.p1.z - a.p1.w * b.p1.w;
    result.p1.y = a.p1.x * b.p1.y + a.p1.y * b.p1.x + a.p1.z * b.p1.w - a.p1.w * b.p1.z;
    result.p1.z = a.p1.x * b.p1.z - a.p1.y * b.p1.w + a.p1.z * b.p1.x + a.p1.w * b.p1.y;
    result.p1.w = a.p1.x * b.p1.w + a.p1.y * b.p1.z - a.p1.z * b.p1.y + a.p1.w * b.p1.x;
    return result;
}

