        VkDescriptorSetLayout create_descriptor_set_layout_0(VulkanBackend& backend)
        {
            std::vector<VkDescriptorSetLayoutBinding> descLayoutBindings;
            descLayoutBindings.emplace_back(VkDescriptorSetLayoutBinding{
                0, VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, 1,
                VK_SHADER_STAGE_VERTEX_BIT | VK_SHADER_STAGE_FRAGMENT_BIT, nullptr});
            descLayoutBindings.emplace_back(VkDescriptorSetLayoutBinding{
                1, VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, 1, VK_SHADER_STAGE_VERTEX_BIT, nullptr});
            descLayoutBindings.emplace_back(VkDescriptorSetLayoutBinding{
                2, VK_DESCRIPTOR_TYPE_SAMPLER, 1, VK_SHADER_STAGE_FRAGMENT_BIT, nullptr});
            descLayoutBindings.emplace_back(VkDescriptorSetLayoutBinding{
                3, VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE, ShadowMapMaxCount,
                VK_SHADER_STAGE_FRAGMENT_BIT, nullptr});

            std::vector<VkDescriptorBindingFlags> bindingFlags(descLayoutBindings.size(), VK_FLAGS_NONE);
            bindingFlags.back() = VK_DESCRIPTOR_BINDING_PARTIALLY_BOUND_BIT;

            VkDescriptorSetLayoutBindingFlagsCreateInfo bindFlagsInfo = {};
            bindFlagsInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_BINDING_FLAGS_CREATE_INFO;
            bindFlagsInfo.bindingCount = static_cast<u32>(bindingFlags.size());
            bindFlagsInfo.pBindingFlags = bindingFlags.data();

            VkDescriptorSetLayoutCreateInfo layoutInfo = {};
            layoutInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
            layoutInfo.pNext = &bindFlagsInfo;
            layoutInfo.flags = 0;
            layoutInfo.bindingCount = static_cast<u32>(descLayoutBindings.size());
            layoutInfo.pBindings = descLayoutBindings.data();

            VkDescriptorSetLayout layout = VK_NULL_HANDLE;
            Assert(vkCreateDescriptorSetLayout(backend.device, &layoutInfo, nullptr, &layout) == VK_SUCCESS);
            return layout;
        }

        void update_descriptor_set_0(VulkanBackend& backend, const MainPassResources& resources,
                                     const nonstd::span<VkImageView> shadow_map_views)
        {
            const VkDescriptorBufferInfo passParams = default_descriptor_buffer_info(resources.drawPassConstantBuffer);
            const VkDescriptorBufferInfo instanceParams =
                default_descriptor_buffer_info(resources.drawInstanceConstantBuffer);
            const VkDescriptorImageInfo shadowMapSampler = {resources.shadowMapSampler, VK_NULL_HANDLE,
                                                            VK_IMAGE_LAYOUT_UNDEFINED};

            std::vector<VkDescriptorImageInfo> shadowImages;
            shadowImages.reserve(shadow_map_views.size());
            for (const auto view : shadow_map_views)
            {
                shadowImages.push_back({VK_NULL_HANDLE, view, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL});
            }

            VkWriteDescriptorSet shadowBindlessWrite = {};
            shadowBindlessWrite.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
            shadowBindlessWrite.dstSet = resources.descriptor_set;
            shadowBindlessWrite.dstBinding = 3;
            shadowBindlessWrite.dstArrayElement = 0;
            shadowBindlessWrite.descriptorCount = static_cast<u32>(shadowImages.size());
            shadowBindlessWrite.descriptorType = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
            shadowBindlessWrite.pImageInfo = shadowImages.data();

            std::vector<VkWriteDescriptorSet> writes;
            writes.push_back(create_buffer_descriptor_write(resources.descriptor_set, 0,
                                                            VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER, &passParams));
            writes.push_back(create_buffer_descriptor_write(resources.descriptor_set, 1,
                                                            VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, &instanceParams));
            writes.push_back(create_image_descriptor_write(resources.descriptor_set, 2,
                                                           VK_DESCRIPTOR_TYPE_SAMPLER, &shadowMapSampler));
            writes.push_back(shadowBindlessWrite);

            vkUpdateDescriptorSets(backend.device, static_cast<u32>(writes.size()), writes.data(), 0, nullptr);
        }

        VkDescriptorSetLayout create_descriptor_set_layout_1(VulkanBackend& backend)
        {
            std::vector<VkDescriptorSetLayoutBinding> descLayoutBindings;
            descLayoutBindings.emplace_back(VkDescriptorSetLayoutBinding{
                0, VK_DESCRIPTOR_TYPE_SAMPLER, 1, VK_SHADER_STAGE_FRAGMENT_BIT, nullptr});
            descLayoutBindings.emplace_back(VkDescriptorSetLayoutBinding{
                1, VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE, DiffuseMapMaxCount,
                VK_SHADER_STAGE_FRAGMENT_BIT, nullptr});

            std::vector<VkDescriptorBindingFlags> bindingFlags(descLayoutBindings.size(), VK_FLAGS_NONE);
            bindingFlags.back() = VK_DESCRIPTOR_BINDING_PARTIALLY_BOUND_BIT;

            VkDescriptorSetLayoutBindingFlagsCreateInfo bindFlagsInfo = {};
            bindFlagsInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_BINDING_FLAGS_CREATE_INFO;
            bindFlagsInfo.bindingCount = static_cast<u32>(bindingFlags.size());
            bindFlagsInfo.pBindingFlags = bindingFlags.data();

            VkDescriptorSetLayoutCreateInfo layoutInfo = {};
            layoutInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
            layoutInfo.pNext = &bindFlagsInfo;
            layoutInfo.flags = 0;
            layoutInfo.bindingCount = static_cast<u32>(descLayoutBindings.size());
            layoutInfo.pBindings = descLayoutBindings.data();

            VkDescriptorSetLayout layout = VK_NULL_HANDLE;
            Assert(vkCreateDescriptorSetLayout(backend.device, &layoutInfo, nullptr, &layout) == VK_SUCCESS);
            return layout;
        }

        void update_descriptor_set_1(VulkanBackend& backend, const MainPassResources& resources,
                                     const MaterialResources& material_resources)
        {
            std::vector<VkDescriptorImageInfo> diffuseMaps;
            diffuseMaps.reserve(material_resources.texture_handles.size());

            for (const auto handle : material_resources.texture_handles)
            {
                const auto& tex = material_resources.textures.at(handle);
                diffuseMaps.push_back({VK_NULL_HANDLE, tex.default_view, VK_IMAGE_LAYOUT_SHADER_READ_ONLY_OPTIMAL});
            }

            Assert(diffuseMaps.size() <= DiffuseMapMaxCount);

            VkWriteDescriptorSet diffuseBindlessWrite = {};
            diffuseBindlessWrite.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
            diffuseBindlessWrite.dstSet = resources.material_descriptor_set;
            diffuseBindlessWrite.dstBinding = 1;
            diffuseBindlessWrite.dstArrayElement = 0;
            diffuseBindlessWrite.descriptorCount = static_cast<u32>(diffuseMaps.size());
            diffuseBindlessWrite.descriptorType = VK_DESCRIPTOR_TYPE_SAMPLED_IMAGE;
            diffuseBindlessWrite.pImageInfo = diffuseMaps.data();

            const VkDescriptorImageInfo diffuseSampler = {
                resources.diffuseMapSampler, VK_NULL_HANDLE, VK_IMAGE_LAYOUT_UNDEFINED};

            std::vector<VkWriteDescriptorSet> writes;
            writes.push_back(create_image_descriptor_write(resources.material_descriptor_set, 0,
                                                           VK_DESCRIPTOR_TYPE_SAMPLER, &diffuseSampler));
            writes.push_back(diffuseBindlessWrite);

            vkUpdateDescriptorSets(backend.device, static_cast<u32>(writes.size()), writes.data(), 0, nullptr);
        }
    } // namespace

    MainPipelineInfo create_main_pipeline(ReaperRoot& root, VulkanBackend& backend, VkRenderPass renderPass)
    {
        VkShaderModule blitShaderFS = VK_NULL_HANDLE;
        VkShaderModule blitShaderVS = VK_NULL_HANDLE;
        const char* fileNameVS = "./build/shader/mesh_transformed_shaded.vert.spv";
        const char* fileNameFS = "./build/shader/mesh_transformed_shaded.frag.spv";
        const char* entryPoint = "main";

        vulkan_create_shader_module(blitShaderFS, backend.device, fileNameFS);
        vulkan_create_shader_module(blitShaderVS, backend.device, fileNameVS);

        std::vector<VkVertexInputBindingDescription> vertexBindings = {
            {0, sizeof(hlsl_float3), VK_VERTEX_INPUT_RATE_VERTEX},
            {1, sizeof(hlsl_float3), VK_VERTEX_INPUT_RATE_VERTEX},
            {2, sizeof(hlsl_float2), VK_VERTEX_INPUT_RATE_VERTEX}
        };

        std::vector<VkVertexInputAttributeDescription> vertexAttrs = {
            {0, 0, VK_FORMAT_R32G32B32_SFLOAT, 0},
            {1, 1, VK_FORMAT_R32G32B32_SFLOAT, 0},
            {2, 2, VK_FORMAT_R32G32_SFLOAT, 0}
        };

        std::vector<VkPipelineShaderStageCreateInfo> shaderStages = {
            {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, nullptr, 0, VK_SHADER_STAGE_VERTEX_BIT, blitShaderVS, entryPoint, nullptr},
            {VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO, nullptr, 0, VK_SHADER_STAGE_FRAGMENT_BIT, blitShaderFS, entryPoint, nullptr}
        };

        VkPipelineVertexInputStateCreateInfo vertexInputState = {};
        vertexInputState.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
        vertexInputState.vertexBindingDescriptionCount = static_cast<u32>(vertexBindings.size());
        vertexInputState.pVertexBindingDescriptions = vertexBindings.data();
        vertexInputState.vertexAttributeDescriptionCount = static_cast<u32>(vertexAttrs.size());
        vertexInputState.pVertexAttributeDescriptions = vertexAttrs.data();

        VkPipelineInputAssemblyStateCreateInfo inputAssembly = {};
        inputAssembly.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO;
        inputAssembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;

        VkPipelineViewportStateCreateInfo viewportState = {};
        viewportState.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
        viewportState.viewportCount = 1;
        viewportState.scissorCount = 1;

        VkPipelineRasterizationStateCreateInfo rasterState = {};
        rasterState.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
        rasterState.cullMode = VK_CULL_MODE_BACK_BIT;
        rasterState.frontFace = VK_FRONT_FACE_COUNTER_CLOCKWISE;
        rasterState.polygonMode = VK_POLYGON_MODE_FILL;

        VkPipelineMultisampleStateCreateInfo msState = {};
        msState.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
        msState.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;

        VkPipelineDepthStencilStateCreateInfo depthStencil = {};
        depthStencil.sType = VK_STRUCTURE_TYPE_PIPELINE_DEPTH_STENCIL_STATE_CREATE_INFO;
        depthStencil.depthTestEnable = VK_TRUE;
        depthStencil.depthWriteEnable = VK_TRUE;
        depthStencil.depthCompareOp = UseReverseZ ? VK_COMPARE_OP_GREATER : VK_COMPARE_OP_LESS;

        VkPipelineColorBlendAttachmentState blendAttachment = {};
        blendAttachment.colorWriteMask = VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                                         VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;

        VkPipelineColorBlendStateCreateInfo blendState = {};
        blendState.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
        blendState.attachmentCount = 1;
        blendState.pAttachments = &blendAttachment;

        VkDescriptorSetLayout setLayout0 = create_descriptor_set_layout_0(backend);
        VkDescriptorSetLayout setLayout1 = create_descriptor_set_layout_1(backend);

        std::vector<VkDescriptorSetLayout> setLayouts = {setLayout0, setLayout1};

        VkPipelineLayoutCreateInfo pipelineLayoutInfo = {};
        pipelineLayoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
        pipelineLayoutInfo.setLayoutCount = static_cast<u32>(setLayouts.size());
        pipelineLayoutInfo.pSetLayouts = setLayouts.data();

        VkPipelineLayout pipelineLayout = VK_NULL_HANDLE;
        Assert(vkCreatePipelineLayout(backend.device, &pipelineLayoutInfo, nullptr, &pipelineLayout) == VK_SUCCESS);
        log_debug(root, "vulkan: created blit pipeline layout with handle: {}", static_cast<void*>(pipelineLayout));

        std::vector<VkDynamicState> dynamicStates = {VK_DYNAMIC_STATE_VIEWPORT, VK_DYNAMIC_STATE_SCISSOR};
        VkPipelineDynamicStateCreateInfo dynamicState = {};
        dynamicState.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO;
        dynamicState.dynamicStateCount = static_cast<u32>(dynamicStates.size());
        dynamicState.pDynamicStates = dynamicStates.data();

        VkGraphicsPipelineCreateInfo pipelineInfo = {};
        pipelineInfo.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
        pipelineInfo.stageCount = static_cast<u32>(shaderStages.size());
        pipelineInfo.pStages = shaderStages.data();
        pipelineInfo.pVertexInputState = &vertexInputState;
        pipelineInfo.pInputAssemblyState = &inputAssembly;
        pipelineInfo.pViewportState = &viewportState;
        pipelineInfo.pRasterizationState = &rasterState;
        pipelineInfo.pMultisampleState = &msState;
        pipelineInfo.pDepthStencilState = &depthStencil;
        pipelineInfo.pColorBlendState = &blendState;
        pipelineInfo.pDynamicState = &dynamicState;
        pipelineInfo.layout = pipelineLayout;
        pipelineInfo.renderPass = renderPass;

        VkPipeline pipeline = VK_NULL_HANDLE;
        Assert(vkCreateGraphicsPipelines(backend.device, VK_NULL_HANDLE, 1, &pipelineInfo, nullptr, &pipeline)
               == VK_SUCCESS);
        log_debug(root, "vulkan: created blit pipeline with handle: {}", static_cast<void*>(pipeline));

        vkDestroyShaderModule(backend.device, blitShaderVS, nullptr);
        vkDestroyShaderModule(backend.device, blitShaderFS, nullptr);

        return MainPipelineInfo{pipeline, pipelineLayout, setLayout0, setLayout1};
    }

    namespace
    {
        VkRenderPass create_main_pass(ReaperRoot& /*root*/, VulkanBackend& backend, const MainPassResources& resources)
        {
            const GPUTextureProperties& depthProps = resources.depthBuffer.properties;
            const GPUTextureProperties& hdrProps = resources.hdrBuffer.properties;

            VkAttachmentDescription2 colorAttachment = {};
            colorAttachment.sType = VK_STRUCTURE_TYPE_ATTACHMENT_DESCRIPTION_2;
            colorAttachment.format = PixelFormatToVulkan(hdrProps.format);
            colorAttachment.samples = SampleCountToVulkan(hdrProps.sampleCount);
            colorAttachment.loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
            colorAttachment.storeOp = VK_ATTACHMENT_STORE_OP_STORE;
            colorAttachment.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
            colorAttachment.finalLayout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;

            VkAttachmentDescription2 depthAttachment = {};
            depthAttachment.sType = VK_STRUCTURE_TYPE_ATTACHMENT_DESCRIPTION_2;
            depthAttachment.format = PixelFormatToVulkan(depthProps.format);
            depthAttachment.samples = SampleCountToVulkan(depthProps.sampleCount);
            depthAttachment.loadOp = VK_ATTACHMENT_LOAD_OP_CLEAR;
            depthAttachment.storeOp = VK_ATTACHMENT_STORE_OP_DONT_CARE;
            depthAttachment.initialLayout = VK_IMAGE_LAYOUT_UNDEFINED;
            depthAttachment.finalLayout = VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL;

            std::vector<VkAttachmentDescription2> attachments = {colorAttachment, depthAttachment};

            VkAttachmentReference2 colorRef = {};
            colorRef.sType = VK_STRUCTURE_TYPE_ATTACHMENT_REFERENCE_2;
            colorRef.attachment = 0;
            colorRef.layout = VK_IMAGE_LAYOUT_COLOR_ATTACHMENT_OPTIMAL;
            colorRef.aspectMask = VK_IMAGE_ASPECT_COLOR_BIT;

            VkAttachmentReference2 depthRef = {};
            depthRef.sType = VK_STRUCTURE_TYPE_ATTACHMENT_REFERENCE_2;
            depthRef.attachment = 1;
            depthRef.layout = VK_IMAGE_LAYOUT_DEPTH_ATTACHMENT_OPTIMAL;
            depthRef.aspectMask = VK_IMAGE_ASPECT_DEPTH_BIT;

            VkSubpassDescription2 subpass = {};
            subpass.sType = VK_STRUCTURE_TYPE_SUBPASS_DESCRIPTION_2;
            subpass.pipelineBindPoint = VK_PIPELINE_BIND_POINT_GRAPHICS;
            subpass.colorAttachmentCount = 1;
            subpass.pColorAttachments = &colorRef;
            subpass.pDepthStencilAttachment = &depthRef;

            VkSubpassDependency2 depColor = {};
            depColor.sType = VK_STRUCTURE_TYPE_SUBPASS_DEPENDENCY_2;
            depColor.srcSubpass = VK_SUBPASS_EXTERNAL;
            depColor.dstSubpass = 0;
            depColor.srcStageMask = VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT;
            depColor.dstStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
            depColor.srcAccessMask = VK_ACCESS_SHADER_READ_BIT;
            depColor.dstAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;

            VkSubpassDependency2 depDepth = {};
            depDepth.sType = VK_STRUCTURE_TYPE_SUBPASS_DEPENDENCY_2;
            depDepth.srcSubpass = 0;
            depDepth.dstSubpass = VK_SUBPASS_EXTERNAL;
            depDepth.srcStageMask = VK_PIPELINE_STAGE_COLOR_ATTACHMENT_OUTPUT_BIT;
            depDepth.dstStageMask = VK_PIPELINE_STAGE_FRAGMENT_SHADER_BIT;
            depDepth.srcAccessMask = VK_ACCESS_COLOR_ATTACHMENT_WRITE_BIT;
            depDepth.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;

            std::vector<VkSubpassDependency2> dependencies = {depColor, depDepth};

            VkRenderPassCreateInfo2 rpInfo = {};
            rpInfo.sType = VK_STRUCTURE_TYPE_RENDER_PASS_CREATE_INFO_2;
            rpInfo.attachmentCount = static_cast<u32>(attachments.size());
            rpInfo.pAttachments = attachments.data();
            rpInfo.subpassCount = 1;
            rpInfo.pSubpasses = &subpass;
            rpInfo.dependencyCount = static_cast<u32>(dependencies.size());
            rpInfo.pDependencies = dependencies.data();

            VkRenderPass renderPass = VK_NULL_HANDLE;
            Assert(vkCreateRenderPass2(backend.device, &rpInfo, nullptr, &renderPass) == VK_SUCCESS);
            return renderPass;
        }

        VkFramebuffer create_main_framebuffer(VulkanBackend& backend, MainPassResources& resources)
        {
            std::vector<VkFormat> formats(2);
            std::vector<VkFramebufferAttachmentImageInfo> attachmentInfos(2);
            attachmentInfos[0] = get_attachment_info_from_image_properties(resources.hdrBuffer.properties, &formats[0]);
            attachmentInfos[1] = get_attachment_info_from_image_properties(resources.depthBuffer.properties, &formats[1]);

            VkFramebufferAttachmentsCreateInfo attachInfo = {};
            attachInfo.sType = VK_STRUCTURE_TYPE_FRAMEBUFFER_ATTACHMENTS_CREATE_INFO;
            attachInfo.attachmentImageInfoCount = static_cast<u32>(attachmentInfos.size());
            attachInfo.pAttachmentImageInfos = attachmentInfos.data();

            VkFramebufferCreateInfo fbInfo = {};
            fbInfo.sType = VK_STRUCTURE_TYPE_FRAMEBUFFER_CREATE_INFO;
            fbInfo.flags = VK_FRAMEBUFFER_CREATE_IMAGELESS_BIT;
            fbInfo.renderPass = resources.mainRenderPass;
            fbInfo.attachmentCount = static_cast<u32>(attachmentInfos.size());
            fbInfo.width = attachmentInfos[0].width;
            fbInfo.height = attachmentInfos[0].height;
            fbInfo.layers = 1;
            fbInfo.pNext = &attachInfo;

            VkFramebuffer framebuffer = VK_NULL_HANDLE;
            Assert(vkCreateFramebuffer(backend.device, &fbInfo, nullptr, &framebuffer) == VK_SUCCESS);
            return framebuffer;
        }

        void create_main_pass_resizable_resources(ReaperRoot& root, VulkanBackend& backend, MainPassResources& resources)
        {
            resources.hdrBuffer =
                create_image(root, backend.device, "Main HDR Target", resources.hdrBuffer.properties, backend.vma_instance);
            resources.hdrBufferView = create_default_image_view(root, backend.device, resources.hdrBuffer);

            resources.depthBuffer =
                create_image(root, backend.device, "Main Depth Target", resources.depthBuffer.properties, backend.vma_instance);
            resources.depthBufferView = create_depth_image_view(root, backend.device, resources.depthBuffer);

            resources.main_framebuffer = create_main_framebuffer(backend, resources);
        }

        void destroy_main_pass_resizable_resources(VulkanBackend& backend, MainPassResources& resources)
        {
            vkDestroyFramebuffer(backend.device, resources.main_framebuffer, nullptr);
            vkDestroyImageView(backend.device, resources.hdrBufferView, nullptr);
            vmaDestroyImage(backend.vma_instance, resources.hdrBuffer.handle, resources.hdrBuffer.allocation);
            vkDestroyImageView(backend.device, resources.depthBufferView, nullptr);
            vmaDestroyImage(backend.vma_instance, resources.depthBuffer.handle, resources.depthBuffer.allocation);

            resources.hdrBuffer = {};
            resources.hdrBufferView = VK_NULL_HANDLE;
            resources.depthBuffer = {};
            resources.depthBufferView = VK_NULL_HANDLE;
        }

        void update_resource_properties(MainPassResources& resources, glm::uvec2 extent)
        {
            GPUTextureProperties hdrProps =
                DefaultGPUTextureProperties(extent.x, extent.y, PixelFormat::B10G11R11_UFLOAT_PACK32);
            hdrProps.usageFlags = GPUTextureUsage::ColorAttachment | GPUTextureUsage::Sampled;

            GPUTextureProperties depthProps = DefaultGPUTextureProperties(extent.x, extent.y, PixelFormat::D16_UNORM);
            depthProps.usageFlags = GPUTextureUsage::DepthStencilAttachment;

            resources.hdrBuffer.properties = hdrProps;
            resources.depthBuffer.properties = depthProps;
        }

        VkDescriptorSet create_main_pass_descriptor_set(ReaperRoot& root, VulkanBackend& backend,
                                                        VkDescriptorSetLayout layout)
        {
            VkDescriptorSetAllocateInfo allocInfo = {};
