namespace ocs2 {
namespace legged_robot {

GaitKeyboardPublisher::GaitKeyboardPublisher(ros::NodeHandle nodeHandle, const std::string& gaitFile, const std::string& robotName,
                                             bool verbose) {
  ROS_INFO_STREAM(robotName + "_mpc_mode_schedule node is setting up ...");
  loadData::loadStdVector(gaitFile, "list", availableGaits_, verbose);
  modeSchedulePublisher_ = nodeHandle.advertise<ocs2_msgs::mode_schedule>(robotName + "_mpc_mode_schedule", 1, true);
  gaitRegistry_.clear();
  for (const auto& name : availableGaits_) {
    gaitRegistry_[name] = loadModeSequenceTemplate(gaitFile, name, verbose);
  }
  ROS_INFO_STREAM(robotName + "_mpc_mode_schedule command node is ready.");
}

void GaitKeyboardPublisher::getKeyboardCommand() {
  const std::string promptMsg = "Enter the desired gait; type \"list\" to see all options";
  std::cout << promptMsg << ": ";

  auto shutdownCheck = []() { return !ros::ok() || !ros::master::check(); };
  std::vector<std::string> tokens = stringToWords(getCommandLineString(shutdownCheck));

  if (tokens.empty()) {
    return;
  }

  if (tokens.size() != 1) {
    std::cerr << "WARNING: Input must be exactly one word." << std::endl;
    return;
  }

  // Normalize input to lowercase
  std::string input = tokens[0];
  std::transform(input.begin(), input.end(), input.begin(),
                 [](unsigned char c) { return std::tolower(c); });

  if (input == "list") {
    displayAvailableGaits(availableGaits_);
    return;
  }

  // Check existence before access
  auto it = gaitRegistry_.find(input);
  if (it != gaitRegistry_.end()) {
    modeSchedulePublisher_.publish(createModeSequenceTemplateMsg(it->second));
  } else {
    std::cout << "Gait \"" << input << "\" not recognized.\n";
    displayAvailableGaits(availableGaits_);
  }
}

void GaitKeyboardPublisher::displayAvailableGaids(const std::vector<std::string>& gaits) const {
  std::cout << "Available gaits:\n";
  int index = 0;
  for (const auto& gaitName : gaits) {
    std::cout << "[" << index++ << "] " << gaitName << "\n";
  }
  std::cout << std::endl;
}

