Code GetLocalIp(const std::string &interface, std::string *ip)
{/*{{{*/
    if (!ip) return kInvalidParam;
    struct in_addr addr{};
    Code status = GetLocalIp(interface, &addr);
    if (status != kOk) return status;

    char buffer[kMaxLenOfIp];
    inet_ntop(AF_INET, &addr, buffer, sizeof(buffer));
    ip->assign(buffer);
    return kOk;
}/*}}}*/

Code GetLocalIp(const std::string &interface, struct in_addr *addr)
{/*{{{*/
    if (!addr) return kInvalidParam;

    struct ifreq request{};
    std::strncpy(request.ifr_name, interface.c_str(), IFNAMSIZ - 1);
    request.ifr_name[IFNAMSIZ - 1] = '\0';

    int socket_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (socket_fd < 0) return kSocketError;

    int result = ioctl(socket_fd, SIOCGIFADDR, &request);
    if (result < 0)
    {
        close(socket_fd);
        return kIOCtlError;
    }

    auto *sock_in = reinterpret_cast<struct sockaddr_in*>(&request.ifr_addr);
    *addr = sock_in->sin_addr;
    close(socket_fd);

    return kOk;
}/*}}}*/

Code GetInterfaces(std::vector<std::string> *ifs)
{/*{{{*/
    if (!ifs) return kInvalidParam;

    struct ifaddrs *list = nullptr;
    if (getifaddrs(&list) == -1)
        return kGetIfsError;

    for (auto *entry = list; entry != nullptr; entry = entry->ifa_next)
    {
        if (entry->ifa_addr && entry->ifa_addr->sa_family == AF_INET)
        {
            ifs->emplace_back(entry->ifa_name);
        }
    }

    freeifaddrs(list);
    return kOk;
}/*}}}*/

Code GetInterfaces(std::map<std::string, struct in_addr> *if_in_addrs)
{/*{{{*/
    if (!if_in_addrs) return kInvalidParam;

    struct ifaddrs *list = nullptr;
    if (getifaddrs(&list) == -1)
        return kGetIfsError;

    for (auto *entry = list; entry != nullptr; entry = entry->ifa_next)
    {
        if (entry->ifa_addr && entry->ifa_addr->sa_family == AF_INET)
        {
            auto *sock_in = reinterpret_cast<struct sockaddr_in*>(entry->ifa_addr);
            if_in_addrs->try_emplace(entry->ifa_name, sock_in->sin_addr);
        }
    }

    freeifaddrs(list);
    return kOk;
}/*}}}*/

Code GetInterfaces(std::map<std::string, std::string> *if_ips)
{/*{{{*/
    if (!if_ips) return kInvalidParam;

    struct ifaddrs *list = nullptr;
    if (getifaddrs(&list) == -1)
        return kGetIfsError;

    char ip_str[INET_ADDRSTRLEN];

    for (auto *entry = list; entry != nullptr; entry = entry->ifa_next)
    {
        if (entry->ifa_addr && entry->ifa_addr->sa_family == AF_INET)
        {
            auto *sock_in = reinterpret_cast<struct sockaddr_in*>(entry->ifa_addr);
            inet_ntop(AF_INET, &sock_in->sin_addr, ip_str, sizeof(ip_str));
            if_ips->try_emplace(entry->ifa_name, ip_str);
        }
    }

    freeifaddrs(list);
    return kOk;
}/*}}}*/

Code GetPeerIp(int sock_fd, std::string *peer_ip)
{/*{{{*/
    if (!peer_ip) return kInvalidParam;

    struct sockaddr_in peer_addr{};
    socklen_t len = sizeof(peer_addr);

    if (getpeername(sock_fd, reinterpret_cast<struct sockaddr*>(&peer_addr), &len) == -1)
        return kSocketError;

    char buffer[kMaxLenOfIp];
    inet_ntop(AF_INET, &peer_addr.sin_addr, buffer, sizeof(buffer));
    peer_ip->assign(buffer);
    return kOk;
}/*}}}*/

Code GetHostIpByName(const std::string &host_name, std::string *ip)
{/*{{{*/
    if (host_name.empty() || !ip) return kInvalidParam;
    ip->clear();

    struct addrinfo hints{};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *res = nullptr;
    int err = getaddrinfo(host_name.c_str(), nullptr, &hints, &res);
    if (err != 0) return kGetHostByNameFailed;

    for (auto *node = res; node != nullptr; node = node->ai_next)
    {
        char buf[INET_ADDRSTRLEN]{};
        const auto *sock_in = reinterpret_cast<struct sockaddr_in*>(node->ai_addr);
        if (inet_ntop(AF_INET, &sock_in->sin_addr, buf, sizeof(buf)) == nullptr)
        {
            freeaddrinfo(res);
            return kNetAddrConvertFailed;
        }
        ip->append(buf);
        break;
    }

    freeaddrinfo(res);
    return kOk;
}/*}}}*/

Code GetHostIpByName(const std::string &host_name, uint32_t *ip)
{/*{{{*/
    if (host_name.empty() || !ip) return kInvalidParam;

    struct addrinfo hints{};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *res = nullptr;
    int err = getaddrinfo(host_name.c_str(), nullptr, &hints, &res);
    if (err != 0) return kGetHostByNameFailed;

    for (auto *node = res; node != nullptr; node = node->ai_next)
    {
        const auto *sock_in = reinterpret_cast<const struct sockaddr_in*>(node->ai_addr);
        *ip = sock_in->sin_addr.s_addr;
        break;
    }

    freeaddrinfo(res);
    return kOk;
}/*}}}*/

Code GetHostIpByName(const std::string &host_name, std::deque<std::string> *ips)
{/*{{{*/
    if (host_name.empty() || !ips) return kInvalidParam;
    ips->clear();

    struct addrinfo hints{};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *res = nullptr;
    int err = getaddrinfo(host_name.c_str(), nullptr, &hints, &res);
    if (err != 0) return kGetHostByNameFailed;

    for (auto *node = res; node != nullptr; node = node->ai_next)
    {
        char buf[INET_ADDRSTRLEN]{};
        const auto *sock_in = reinterpret_cast<const struct sockaddr_in*>(node->ai_addr);
        if (inet_ntop(AF_INET, &sock_in->sin_addr, buf, sizeof(buf)) == nullptr)
        {
            freeaddrinfo(res);
            return kNetAddrConvertFailed;
        }
        ips->emplace_back(buf);
    }

    freeaddrinfo(res);
    return kOk;
}/*}}}*/

Code GetHostIpByName(const std::string &host_name, std::deque<uint32_t> *ips)
{/*{{{*/
    if (host_name.empty() || !ips) return kInvalidParam;
    ips->clear();

    struct addrinfo hints{};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    struct addrinfo *res = nullptr;
    int err = getaddrinfo(host_name.c_str(), nullptr, &hints, &res);
    if (err != 0) return kGetHostByNameFailed;

    for (auto *node = res; node != nullptr; node = node->ai_next)
    {
        const auto *sock_in = reinterpret_cast<const struct sockaddr_in*>(node->ai_addr);
        ips->push_back(sock_in->sin_addr.s_addr);
    }

    freeaddrinfo(res);
    return kOk;
}/*}}}*/

Code GetUIntIpByStr(const std::string &str_ip, uint32_t *uint_ip)
{/*{{{*/
    if (!uint_ip) return kInvalidParam;

    struct in_addr tmp{};
    int conv_result = inet_pton(AF_INET, str_ip.c_str(), &tmp);
    if (conv_result == 1)
    {
        *uint_ip = static_cast<uint32_t>(tmp.s_addr);
        return kOk;
    }
    return kInvalidIp;
}/*}}}*/

Code GetStrIpByUint(uint32_t uint_ip, std::string *str_ip)
{/*{{{*/
    if (!str_ip) return kInvalidParam;

    struct in_addr tmp{};
    tmp.s_addr = uint_ip;

    char buffer[kSmallBufLen]{};
    const char *res = inet_ntop(AF_INET, &tmp, buffer, sizeof(buffer));
    if (!res) return kInvalidIp;

    str_ip->assign(buffer);
    return kOk;
}/*}}}*/
}

