#include "Direct3D12.h"
#include "vertexbuffer.h"
#include <kinc/graphics5/vertexbuffer.h>
#include <kinc/backend/SystemMicrosoft.h>
#include <kinc/graphics4/graphics.h>

// Global state tracking for current active vertex buffer
kinc_g5_vertex_buffer_t *_active_vertex_buffer = nullptr;

// Initialize a vertex buffer with given parameters
void kinc_g5_vertex_buffer_init(kinc_g5_vertex_buffer_t *vb, int vertexCount, kinc_g5_vertex_structure_t *layout, bool useGpuMem, int instanceStepRate) {
    vb->impl.vertexCount = vertexCount;
    vb->impl.lastRegionStart = -1;
    vb->impl.lastRegionSize = -1;

    static_assert(sizeof(D3D12VertexBufferView) == sizeof(D3D12_VERTEX_BUFFER_VIEW), "Mismatch in D3D12 view types");

    // Compute stride by summing element sizes based on data type
    vb->impl.strideInBytes = 0;
    for (int idx = 0; idx < layout->elementCount; ++idx) {
        switch (layout->elements[idx].type) {
            case KINC_G4_VERTEX_DATA_FLOAT1:
                vb->impl.strideInBytes += 4;
                break;
            case KINC_G4_VERTEX_DATA_FLOAT2:
                vb->impl.strideInBytes += 8;
                break;
            case KINC_G4_VERTEX_DATA_FLOAT3:
                vb->impl.strideInBytes += 12;
                break;
            case KINC_G4_VERTEX_DATA_FLOAT4:
                vb->impl.strideInBytes += 16;
                break;
            case KINC_G4_VERTEX_DATA_COLOR:
                vb->impl.strideInBytes += 4;
                break;
            case KINC_G4_VERTEX_DATA_SHORT2_NORM:
                vb->impl.strideInBytes += 4;
                break;
            case KINC_G4_VERTEX_DATA_SHORT4_NORM:
                vb->impl.strideInBytes += 8;
                break;
        }
    }

    const size_t totalUploadSize = vb->impl.strideInBytes * vb->impl.vertexCount;

    CD3DX12_HEAP_PROPERTIES uploadHeap(D3D12_HEAP_TYPE_UPLOAD);
    CD3DX12_RESOURCE_DESC bufferDesc = CD3DX12_RESOURCE_DESC::Buffer(totalUploadSize);

    device->CreateCommittedResource(
        &uploadHeap,
        D3D12_HEAP_FLAG_NONE,
        &bufferDesc,
        D3D12_RESOURCE_STATE_GENERIC_READ,
        nullptr,
        IID_GRAPHICS_PPV_ARGS(&vb->impl.uploadResource)
    );

    // Setup view
    vb->impl.view.BufferLocation = vb->impl.uploadResource->GetGPUVirtualAddress();
    vb->impl.view.SizeInBytes = static_cast<UINT>(totalUploadSize);
    vb->impl.view.StrideInBytes = static_cast<UINT>(vb->impl.strideInBytes);
}

// Cleanup resources (currently no-op as original also had no implementation)
void kinc_g5_vertex_buffer_destroy(kinc_g5_vertex_buffer_t *vb) {
    // Original: commented out release/delete
}

// Lock entire buffer
float *kinc_g5_vertex_buffer_lock_all(kinc_g5_vertex_buffer_t *vb) {
    return kinc_g5_vertex_buffer_lock(vb, 0, kinc_g5_vertex_buffer_count(vb));
}

// Lock a sub-region of the buffer
float *kinc_g5_vertex_buffer_lock(kinc_g5_vertex_buffer_t *vb, int startIdx, int count) {
    vb->impl.lastRegionStart = startIdx;
    vb->impl.lastRegionSize = count;

    void *mappedPtr = nullptr;
    D3D12_RANGE range;
    range.Begin = static_cast<SIZE_T>(startIdx * vb->impl.strideInBytes);
    range.End = range.Begin + static_cast<SIZE_T>(count * vb->impl.strideInBytes);

    vb->impl.uploadResource->Map(0, &range, &mappedPtr);

    uint8_t *bytePtr = static_cast<uint8_t*>(mappedPtr);
    bytePtr += startIdx * vb->impl.strideInBytes;
    return reinterpret_cast<float*>(bytePtr);
}

// Unlock entire last-locked region
void kinc_g5_vertex_buffer_unlock_all(kinc_g5_vertex_buffer_t *vb) {
    D3D12_RANGE range;
    range.Begin = static_cast<SIZE_T>(vb->impl.lastRegionStart * vb->impl.strideInBytes);
    range.End = range.Begin + static_cast<SIZE_T>(vb->impl.lastRegionSize * vb->impl.strideInBytes);
    vb->impl.uploadResource->Unmap(0, &range);
}

// Unlock specific number of vertices from last lock
void kinc_g5_vertex_buffer_unlock(kinc_g5_vertex_buffer_t *vb, int numVertices) {
    D3D12_RANGE range;
    range.Begin = static_cast<SIZE_T>(vb->impl.lastRegionStart * vb->impl.strideInBytes);
    range.End = range.Begin + static_cast<SIZE_T>(numVertices * vb->impl.strideInBytes);
    vb->impl.uploadResource->Unmap(0, &range);
}

// Set current vertex buffer for rendering (internal)
int kinc_g5_internal_vertex_buffer_set(kinc_g5_vertex_buffer_t *vb, int offset) {
    _active_vertex_buffer = vb;
    return 0;
}

// Return number of vertices in buffer
int kinc_g5_vertex_buffer_count(kinc_g5_vertex_buffer_t *vb) {
    return vb->impl.vertexCount;
}

// Return stride in bytes
int kinc_g5_vertex_buffer_stride(kinc_g5_vertex_buffer_t *vb) {
    return vb->impl.strideInBytes;
}

