}

// Check if the constraint is currently active
bool ActorConstraint::isActive() const
{
    return m_Active;
}

// Retrieve current influence factor
float ActorConstraint::influence() const
{
    return m_Influence;
}

// Set new influence factor; update only if changed
void ActorConstraint::influence(float newValue)
{
    if (m_Influence == newValue)
        return;

    m_Influence = newValue;
    getOwner()->markTransformDirty();
}

// Handle dirty state propagation
void ActorConstraint::onUpdated(unsigned char flags)
{
    getOwner()->markTransformDirty();
}

// Resolve indices and register constraint with parent actor
void ActorConstraint::resolveIndices(ActorComponent** table)
{
    Base::resolveIndices(table);
    if (getOwner() != nullptr)
    {
        // Constraints are appended in hierarchy order during deserialization
        getOwner()->appendConstraint(this);
    }
}

// Copy properties from another constraint instance
void ActorConstraint::clone(ActorConstraint* source, Actor* target)
{
    Base::clone(source, target);
    m_Active = source->m_Active;
    m_Influence = source->m_Influence;
}

// Deserialize constraint data from stream
ActorConstraint* ActorConstraint::load(Actor* owner, BlockReader* stream, ActorConstraint* existing)
{
    Base::load(owner, stream, existing);
    existing->m_Influence = stream->readFloat();
    existing->m_Active = (stream->readByte() != 0);
    return existing;
}

#include "\tc\CLib\addons\CLib\ModuleMacros.hpp"

/*
 * CLibRef — A modular extension built on top of the CLib framework.
 * Provides shared utilities and integration points across multiple game modules.
 * Each submodule declares its own functionality via FNC(...) macros,
 * and registers entry points automatically based on naming conventions.
 */
class CfgCLibModules {
    class CLibRef {
        // Root directory for all modules defined under this class.
        // Must match the PBO prefix used during packaging.
        path = "rvn\clibref\addons\clibref";

        // Dependencies required by *all* submodules in this module group.
        // These are merged with per-module dependency lists at load time.
        dependency[] = {};

        // Module: PFH — PerFrame Hook handler
        // Handles per-frame logic execution, typically used for UI updates or polling.
        MODULE(PFH) {
            // Requires CLib's core event system and per-frame hook infrastructure.
            dependency[] = {"CLib/PerFrame", "Clib/Events"};

            // Entry point: Called once per client upon interface availability.
            FNC(clientInit);
        };

        // Module: flagInteraction — Flag capture mechanics & interaction handling
        // Implements flag-based gameplay logic (e.g., capture-the-flag).
        MODULE(flagInteraction) {
            // Depends on CLib's interaction system and event dispatcher.
            dependency[] = {"CLib/Interaction", "CLib/Events"};

            // Initialization routine for client-side flag UI/state.
            FNC(clientInit);

            // Core logic for flag capture events (server + client).
            FNC(captureFlag);
        };
    };
};

// ========================= ENTRY POINT SEMANTICS =========================
// CLib defines several standardized hooks that trigger automatically:
//
// • clientInit   → triggered only on players with UI (i.e., not server/HC)
// • serverInit   → runs exclusively on the dedicated server instance
// • hcInit       → executes on each headless client (client without UI)
// • init         → universal initializer, runs everywhere (earliest possible)
//
// Order of invocation: global 'init' fires first, then specialized ones.
// For implementation details, see:
//   - Autoload: https://github.com/TaktiCool/CLib/blob/master/addons/CLib/Core/Autoload/fn_callModules.sqf
//   - Module parsing: https://github.com/TaktiCool/CLib/blob/master/addons/CLib/Core/Compile/fn_readAllModules.sqf
//   - Full compile pipeline: addons/CLib/Core/Compile/

