// Function to find the smaller of two integers
int getSmaller(int& val1, int& val2) {
    return (val1 < val2) ? val1 : val2;
}

// Determine the value at position (row, col) in the spiral matrix
int computeSpiralValue(int row, int col, int size) {
    // Calculate the layer (distance from nearest edge)
    int layer = getSmaller(getSmaller(row, size + 1 - row), 
                          getSmaller(col, size + 1 - col));

    if (row == layer) {
        // Top edge of current layer
        return col - row + 1 + 4 * (size - layer + 1) * (layer - 1);
    }
    else if (row == size + 1 - layer) {
        // Bottom edge of current layer
        return 3 * size - col - 5 * layer + 4 * (size - layer + 1) * (layer - 1) + 4;
    }
    else if (col == layer) {
        // Left edge of current layer
        return col - row + 4 * size - 8 * layer + 4 * (size - layer + 1) * (layer - 1) + 5;
    }
    else {
        // Right edge of current layer
        return row + size - 3 * layer + 4 * (size - layer + 1) * (layer - 1) + 2;
    }
}

int main() {
    int dimension;
    cin >> dimension;

    for (int row = 0; row < dimension; row++) {
        if (row > 0) {
            cout << endl;
        }
        for (int col = 0; col < dimension; col++) {
            cout << setw(6) << computeSpiralValue(row + 1, col + 1, dimension);
        }
    }

    return 0;
}

