// Namespace alias for standard library
using namespace std;

/*
//  bbLua constructor/destructor - kept minimal as initialization is handled separately
*/
bbLua::bbLua() { }
bbLua::~bbLua() { }

/*
//  Custom function exposed to Lua environment
*/
int bbLua::my_function(lua_State *L)
{
    int argCount = lua_gettop(L);
    cerr << "-- my_function() invoked with " << argCount << " parameters:" << endl;

    // Iterate through arguments using index-based loop
    for (int idx = 1; idx <= argCount; ++idx)
    {
        cerr << "-- parameter " << idx << ": "
             << lua_tostring(L, idx) << endl;
    }

    lua_pushnumber(L, 123); // Push return value onto stack
    return 1;               // Indicate one return value
}

/*
//  Error reporting utility
*/
void bbLua::report_errors(lua_State *L, int result)
{
    if (result != 0)
    {
        cerr << "-- " << lua_tostring(L, -1) << endl;
        lua_pop(L, 1); // Pop error message from stack
    }
}

/*
//  Cleanup Lua state
*/
void bbLua::close()
{
    lua_close(LuaContext);
}

/*
//  Initialize Lua interpreter and register built-in modules
*/
void bbLua::init()
{
    /* Create new Lua state */
    LuaContext = lua_open();

    // Load standard libraries
    luaopen_io(LuaContext);           // io.*
    luaopen_base(LuaContext);         // base functions
    luaopen_table(LuaContext);        // table manipulation
    luaopen_string(LuaContext);       // string operations
    luaopen_math(LuaContext);         // math functions
    luaopen_loadlib(LuaContext);      // package loading

    // Register custom application functions
    lua_register(LuaContext, "Print", luaPrint);
    lua_register(LuaContext, "Reconfigure", luaReconfigure);
    lua_register(LuaContext, "SwitchDesktop", luaSwitchDesktop);
    lua_register(LuaContext, "SendBroam", luaSendBroam);
    lua_register(LuaContext, "GetBlackboxWindow", luaGetBlackboxWindow);
    lua_register(LuaContext, "GetProxyWindow", luaGetProxyWindow);
    lua_register(LuaContext, "FindWindow", luaFindWindow);
    lua_register(LuaContext, "SendMessage", luaSendMessage);
    lua_register(LuaContext, "RegisterEvent", luaRegisterEvent);
    lua_register(LuaContext, "UnregisterEvent", luaUnregisterEvent);
}

/*
//  Execute a Lua script file
//
//  This could be enhanced to support include directives or module loading.
*/
void bbLua::loadFile(const char* filename) 
{
    int status = luaL_loadfile(LuaContext, filename);
    cerr << "Executing script" << endl;

    if (status == 0)
    {
        status = lua_pcall(LuaContext, 0, LUA_MULTRET, 0);
    }

    report_errors(LuaContext, status);
}

/*
//  Accessor for internal Lua state
*/
lua_State* bbLua::GetLuaContext()
{
    return LuaContext;
}

/*
//  Invoke a named Lua function with variable arguments
*/
int bbLua::CallLuaFunctionByName(char* funcName, int numArgs, ...)
{
    va_list argList;
    va_start(argList, numArgs);

    // Push function name and arguments onto the stack
    lua_pushstring(LuaContext, funcName);

    for (int i = 0; i < numArgs; ++i)
    {
        const char* val = va_arg(argList, const char*);
        lua_pushstring(LuaContext, val);
    }

    // Execute the function call
    lua_pcall(LuaContext, numArgs, LUA_MULTRET, 0);

    va_end(argList);
    return 0;
}

