bool XG_UndoBuffer::HasUndoAvailable() const {
    if (!m_enabled)
        return false;
    return m_index > 0;
}

bool XG_UndoBuffer::HasRedoAvailable() const {
    if (!m_enabled)
        return false;
    return m_index < static_cast<int>(buffer.size());
}

bool XG_UndoBuffer::PerformUndo() {
    if (HasUndoAvailable()) {
        --m_index;
        buffer[m_index].Execute(false);
        return true;
    }
    return false;
}

bool XG_UndoBuffer::PerformRedo() {
    if (HasRedoAvailable()) {
        buffer[m_index].Execute(true);
        ++m_index;
        return true;
    }
    return false;
}

void XG_UndoBuffer::Record(const XG_UndoInfo& info) {
    if (!m_enabled)
        return;

    buffer.resize(m_index);

    buffer.emplace_back(info);
    ++m_index;
}

static constexpr int kMaxUndoSteps = 25;

void XG_UndoBuffer::Record(UINT msgId,
    std::shared_ptr<XG_UndoData> prior, std::shared_ptr<XG_UndoData> current)
{
    if (!m_enabled)
        return;

    buffer.resize(m_index);

    buffer.emplace_back(msgId, prior, current);
    ++m_index;

    if (static_cast<int>(buffer.size()) > kMaxUndoSteps) {
        buffer.pop_front();
        --m_index;
    }
}

