static void* g_flv_writer = nullptr;

// Custom send handler for RTMP client
static int rtmp_send_data(void* ctx, const void* hdr, size_t hdr_len, const void* payload, size_t payload_len)
{
    socket_t* sock = static_cast<socket_t*>(ctx);
    socket_bufvec_t iov[2];
    socket_setbufvec(iov, 0, const_cast<void*>(hdr), hdr_len);
    socket_setbufvec(iov, 1, const_cast<void*>(payload), payload_len);
    size_t vec_count = (payload_len > 0) ? 2u : 1u;
    return socket_send_v_all_by_time(*sock, iov, vec_count, 0, 2000);
}

// Audio packet callback
static int on_audio_frame(void*, const void* data, size_t len, uint32_t ts)
{
    return flv_writer_input(g_flv_writer, FLV_TYPE_AUDIO, data, len, ts);
}

// Video packet callback
static int on_video_frame(void*, const void* data, size_t len, uint32_t ts)
{
    return flv_writer_input(g_flv_writer, FLV_TYPE_VIDEO, data, len, ts);
}

// Metadata/script callback
static int on_script_data(void*, const void* data, size_t len, uint32_t ts)
{
    return flv_writer_input(g_flv_writer, FLV_TYPE_SCRIPT, data, len, ts);
}

// Play RTMP stream and save to local FLV file
void rtmp_play_test(const char* hostname, const char* app_name, const char* stream_name, const char* output_file)
{
    // Allocate large buffer for incoming RTMP packets
    static char recv_buffer[8 * 1024 * 1024];

    // Construct tcurl: rtmp://host/app
    snprintf(recv_buffer, sizeof(recv_buffer), "rtmp://%s/%s", hostname, app_name);

    // Initialize socket layer
    socket_init();

    // Connect to RTMP server
    socket_t conn_socket = socket_connect_host(hostname, 1935, 2000);
    socket_setnonblock(conn_socket, 0);

    // Setup handler callbacks
    struct rtmp_client_handler_t handler;
    std::memset(&handler, 0, sizeof(handler));
    handler.send       = rtmp_send_data;
    handler.onaudio    = on_audio_frame;
    handler.onvideo    = on_video_frame;
    handler.onscript   = on_script_data;

    // Create and configure RTMP client
    rtmp_client_t* client = rtmp_client_create(app_name, stream_name, recv_buffer, &conn_socket, &handler);
    g_flv_writer = flv_writer_create(output_file);

    // Start RTMP playback
    int status = rtmp_client_start(client, 1);

    // Main receive loop: pull data from socket and feed into RTMP parser
    while ((status = socket_recv(conn_socket, recv_buffer, sizeof(recv_buffer), 0)) > 0)
    {
        status = rtmp_client_input(client, recv_buffer, static_cast<size_t>(status));
        if (status != 0) break;
    }

    // Cleanup resources in reverse order of creation
    rtmp_client_stop(client);
    flv_writer_destroy(g_flv_writer);
    rtmp_client_destroy(client);
    socket_close(conn_socket);
    socket_cleanup();
}

