Condition CompareIC::ComputeCondition(Token::Value op) {
  switch (op) {
    case Token::EQ_STRICT:
    case Token::EQ:
      return eq;
    case Token::LT:
      return lt;
    case Token::GT:
      return gt;
    case Token::LTE:
      return le;
    case Token::GTE:
      return ge;
    default:
      UNREACHABLE();
      return kNoCondition;
  }
}

bool CompareIC::HasInlinedSmiCode(Address addr) {
  Address next_instr_addr = Assembler::return_address_from_call_start(addr);
  return Instruction::S390OpcodeValue(next_instr_addr) == CHI;
}

void PatchInlinedSmiCode(Isolate* isolate, Address call_site,
                         InlinedSmiCheck mode) {
  // Locate the comparison instruction following the call
  Address cmp_loc = Assembler::return_address_from_call_start(call_site);

  // Early exit if not a CHI instruction
  if (Instruction::S390OpcodeValue(cmp_loc) != CHI) {
    return;
  }

  // Ensure the call site is BRASL
  if (Instruction::S390OpcodeValue(call_site) != BRASL) {
    return;
  }

  // Extract delta from CHI instruction (lower 16 bits)
  uint32_t raw_cmp = Assembler::instr_at(cmp_loc);
  int offset_to_smi_check = static_cast<int>(raw_cmp & 0x0000ffff);
  if (offset_to_smi_check == 0) {
    return;  // No inlined smi check present
  }

  if (FLAG_trace_ic) {
    PrintF("[  patching ic at %p, cmp=%p, delta=%d\n",
           static_cast<void*>(call_site),
           static_cast<void*>(cmp_loc), offset_to_smi_check);
  }

  // Compute addresses for patching
  Address smi_check_loc = cmp_loc - offset_to_smi_check;
  Address branch_loc = smi_check_loc + 4;  // Size of CR/CGR + LR sequence

  Instr smi_instr = Assembler::instr_at(smi_check_loc);
  SixByteInstr branch_data = Assembler::instr_at(branch_loc);

  // Determine patch size based on branch type
  size_t total_patch_bytes = 0;
  if (Instruction::S390OpcodeValue(branch_loc) == BRC) {
    total_patch_bytes = 4 + 4;
  } else if (Instruction::S390OpcodeValue(branch_loc) == BRCL) {
    total_patch_bytes = 4 + 6;
  } else {
    DCHECK(false);
    return;
  }

  CodePatcher patcher(isolate, smi_check_loc, total_patch_bytes);
  Register target_reg;
  target_reg.reg_code = smi_instr & 0x0F;

  if (mode == ENABLE_INLINED_SMI_CHECK) {
    patcher.masm()->TestIfSmi(target_reg);
  } else {
    // Disable: emit compare-with-self + NOP (for 31-bit compatibility)
    DCHECK(mode == DISABLE_INLINED_SMI_CHECK);
    patcher.masm()->CmpP(target_reg, target_reg);
#ifndef V8_TARGET_ARCH_S390X
    patcher.masm()->nop();
#endif
  }

  // Adjust branch condition
  Condition cond = al;
  if (Instruction::S390OpcodeValue(branch_loc) == BRC) {
    uint32_t raw_branch = static_cast<uint32_t>(branch_data);
    cond = static_cast<Condition>((raw_branch & 0x00f00000) >> 20);
    DCHECK(cond == ne || cond == eq);
    cond = (cond == ne) ? eq : ne;
    patcher.masm()->brc(cond, Operand(raw_branch & 0xffff));
  } else if (Instruction::S390OpcodeValue(branch_loc) == BRCL) {
    uint64_t raw_branch = static_cast<uint64_t>(branch_data);
    cond = static_cast<Condition>((raw_branch & (static_cast<uint64_t>(0x00f0) << 32)) >> 36);
    DCHECK(cond == ne || cond == eq);
    cond = (cond == ne) ? eq : ne;
    patcher.masm()->brcl(cond, Operand(raw_branch & 0xffffffff));
  } else {
    DCHECK(false);
  }
}

}  // namespace internal
}  // namespace v8
#endif  // V8_TARGET_ARCH_S390

#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y, z; 
    int frequency; 
    int dominance_count;

    bool operator< (const Point& other) const { 
        if (x != other.x) return x < other.x;
        if (y != other.y) return y < other.y;
        return z < other.z;
    }

    bool operator== (const Point& other) const { 
        return x == other.x && y == other.y && z == other.z; 
    }
};

Point original_points[100005], processed_points[100005];
int result_counts[100005];

class FenwickTree {
    int tree[200005];

public:
    void reset() { 
        memset(tree, 0, sizeof(tree)); 
    }

    int getLowBit(int index) { 
        return index & -index; 
    }

    int query(int index) {
        int sum = 0;
        while (index > 0) {
            sum += tree[index];
            index -= getLowBit(index);
        }
        return sum;
    }

    void update(int index, int value = 1) {
        while (index <= 200000) {
            tree[index] += value;
            index += getLowBit(index);
        }
    }

    int rangeQuery(int left, int right) {
        if (left > right) return 0;
        return query(right) - (left > 0 ? query(left - 1) : 0);
    }
} fenwick;

void solveDivideConquer(int left, int right, bool needSort = true) {
    if (left >= right) return;

    int center = left + (right - left) / 2;
    solveDivideConquer(left, center, false);
    solveDivideConquer(center + 1, right, false);

    // Merge process: process right half using data from left half
    int leftIndex = left;
    for (int rightIndex = center + 1; rightIndex <= right; ++rightIndex) {
        // Add all points from left half with y <= current right point's y
        while (leftIndex <= center && processed_points[leftIndex].y <= processed_points[rightIndex].y) {
            fenwick.update(processed_points[leftIndex].z, processed_points[leftIndex].frequency);
            ++leftIndex;
        }
        // Count points with z <= current point's z
        processed_points[rightIndex].dominance_count += fenwick.query(processed_points[rightIndex].z);
    }

    // Remove contributions from left half for next iterations
    for (int i = left; i < leftIndex; ++i) {
        fenwick.update(processed_points[i].z, -processed_points[i].frequency);
    }

    // Sort by y-coordinate for next level
    if (needSort) {
        sort(processed_points + left, processed_points + right + 1, 
             [](const Point& p1, const Point& p2) { 
                 return p1.y < p2.y; 
             });
    }
}

int main() {
    int n, k;
    scanf("%d%d", &n, &k);

    for (int i = 1; i <= n; ++i) {
        scanf("%d%d%d", &original_points[i].x, &original_points[i].y, &original_points[i].z);
        original_points[i].frequency = 1;
    }

    // Sort and compress duplicate points
    sort(original_points + 1, original_points + 1 + n);

    int uniqueCount = 1;
    processed_points[1] = original_points[1];

    for (int i = 2; i <= n; ++i) {
        if (original_points[i] == original_points[i-1]) {
            processed_points[uniqueCount].frequency++;
        } else {
            processed_points[++uniqueCount] = original_points[i];
        }
    }

    // Run CDQ divide and conquer
    solveDivideConquer(1, uniqueCount, false);

    // Aggregate results
    for (int i = 1; i <= uniqueCount; ++i) {
        int count = processed_points[i].dominance_count + processed_points[i].frequency - 1;
        result_counts[count] += processed_points[i].frequency;
    }

    // Output results
    for (int i = 0; i < n; ++i) {
        printf("%d\n", result_counts[i]);
    }

    return 0;
}

