namespace libq {

// Hash function: maps 64-bit key to a width-sized index
static inline unsigned int hash64(state_t key, int w) {
    unsigned int lower = static_cast<unsigned int>(key & 0xFFFFFFFF);
    unsigned int upper = static_cast<unsigned int>(key >> 32);
    unsigned int mixed = lower ^ upper;
    mixed *= 0x9e370001UL;
    return mixed >> (32 - w);
}

// Retrieve position of state 'a' in register; returns -1 if not found
state_t get_state(state_t val, qureg *r) {
    unsigned int idx = hash64(val, r->hashw);
    while (r->hash[idx]) {
        if (r->state[r->hash[idx] - 1] == val) {
            return static_cast<state_t>(r->hash[idx] - 1);
        }
        ++idx;
        if (idx == static_cast<unsigned int>(1U << r->hashw)) {
            break;
        }
    }
    return -1;
}

// Insert mapping from state 'val' to position 'pos' into hash table
void libq_add_hash(state_t val, int pos, qureg *r) {
    unsigned int probe = hash64(val, r->hashw);
    bool wrapped = false;
    while (r->hash[probe]) {
        ++probe;
        if (probe == static_cast<unsigned int>(1U << r->hashw)) {
            if (!wrapped) {
                probe = 0;
                wrapped = true;
            } else {
                // TODO(rhundt): Handle full hashtable.
                break;
            }
        }
    }
    r->hash[probe] = pos + 1;

    if (r->hash_caching && r->hits < HASH_CACHE_SIZE) {
        r->hash_hits[r->hits] = static_cast<int>(probe);
        ++(r->hits);
    }
}

// Rebuild hash table from scratch
void libq_reconstruct_hash(qureg *r) {
    ++(r->hash_computes);

    if (r->hash_caching && r->hits < HASH_CACHE_SIZE) {
        for (int k = 0; k < r->hits; ++k) {
            r->hash[r->hash_hits[k]] = 0;
            r->hash_hits[k] = 0;
        }
        r->hits = 0;
    } else {
        size_t hash_bytes = (1U << r->hashw) * sizeof(int);
        memset(r->hash, 0, hash_bytes);
        if (r->hits > 0) {
            memset(r->hash_hits, 0, r->hits * sizeof(int));
        }
        r->hits = 0;
        // Manual loop unrolling or alternative optimization could be applied here.
        // Original comment: compiler may not optimize this loop — investigate.
        // for (int i = 0; i < (1 << r->hashw); ++i) { r->hash[i] = 0; }
    }

    for (int idx = 0; idx < r->size; ++idx) {
        libq_add_hash(r->state[idx], idx, r);
    }
}

// Apply single-qubit gate matrix 'm' at 'target' qubit
void libq_gate1(int target, cmplx m[4], qureg *r) {
    int extra_states = 0;

    libq_reconstruct_hash(r);

    // Count how many new basis states will be needed
    for (int i = 0; i < r->size; ++i) {
        state_t flipped = r->state[i] ^ (static_cast<state_t>(1) << target);
        if (get_state(flipped, r) == -1) {
            ++extra_states;
        }
    }

    // Expand storage if necessary
    if (extra_states > 0) {
        r->state = static_cast<state_t *>(
            realloc(r->state, (r->size + extra_states) * sizeof(state_t)));
        r->amplitude = static_cast<cmplx *>(
            realloc(r->amplitude, (r->size + extra_states) * sizeof(cmplx)));

        // Initialize new entries to zero
        memset(&r->state[r->size], 0, extra_states * sizeof(state_t));
        memset(&r->amplitude[r->size], 0, extra_states * sizeof(cmplx));

        if (r->size + extra_states > r->maxsize) {
            r->maxsize = r->size + extra_states;
        }
    }

    char *processed = static_cast<char *>(calloc(r->size + extra_states, sizeof(char)));
    int next_slot = r->size;

    const float threshold = (1.0f / (static_cast<state_t>(1) << r->width)) * 1e-6f;

    // Perform transformation on each amplitude pair
    for (int i = 0; i < r->size; ++i) {
        if (!processed[i]) {
            bool bit_set = (r->state[i] & (static_cast<state_t>(1) << target)) != 0;
            int partner_idx = get_state(r->state[i] ^ (static_cast<state_t>(1) << target), r);

            cmplx amp_i = r->amplitude[i];
            cmplx amp_partner = (partner_idx >= 0) ? r->amplitude[partner_idx] : cmplx{0.0, 0.0};

            if (bit_set) {
                r->amplitude[i] = m[2] * amp_partner + m[3] * amp_i;
            } else {
                r->amplitude[i] = m[0] * amp_i + m[1] * amp_partner;
            }

            if (partner_idx >= 0) {
                processed[partner_idx] = 1;
                if (bit_set) {
                    r->amplitude[partner_idx] = m[0] * amp_partner + m[1] * amp_i;
                } else {
                    r->amplitude[partner_idx] = m[2] * amp_i + m[3] * amp_partner;
                }
            } else {
                // Create new state only if corresponding matrix element is non-zero
                if ((std::abs(m[1]) == 0.0f && bit_set) ||
                    (std::abs(m[2]) == 0.0f && !bit_set)) {
                    continue;
                }

                r->state[next_slot] = r->state[i] ^ (static_cast<state_t>(1) << target);
                r->amplitude[next_slot] = bit_set ? m[1] * amp_i : m[2] * amp_i;
                ++next_slot;
            }
        }
    }

    r->size += extra_states;
    free(processed);

    // Trim negligible amplitudes
    if (r->hashw > 0) {
        int removed = 0;
        for (int write_pos = 0, read_pos = 0; read_pos < r->size; ++read_pos) {
            if (probability(r->amplitude[read_pos]) < threshold) {
                ++removed;
            } else if (write_pos != read_pos) {
                r->state[write_pos] = r->state[read_pos];
                r->amplitude[write_pos] = r->amplitude[read_pos];
                ++write_pos;
            } else {
                ++write_pos;
            }
        }
        if (removed > 0) {
            r->size -= removed;
            // Optional reallocation omitted per original comments
        }
    }

    // Warn if hash table too sparse
    if (r->size > (1U << (r->hashw - 1))) {
        fprintf(stderr, "Warning: inefficient hash table (size %i vs hash %i)\n",
                r->size, 1 << r->hashw);
    }
}

