#include <array>
#include <iostream>
using namespace std;

int main() {
    ios::sync_with_stdio(false);

    // Process multiple game rounds until negative number is entered
    while (true) {
        int roundNumber;
        cin >> roundNumber;

        if (roundNumber < 0) {
            break;
        }

        cout << "Round " << roundNumber << endl;

        string targetWord, guessSequence;
        cin >> targetWord >> guessSequence;

        array<int, 26> letterCount;
        letterCount.fill(0);

        // Count frequency of each letter in the target word
        for (char ch : targetWord) {
            letterCount[ch - 'a']++;
        }

        int matchedLetters = 0;
        int wrongGuesses = 0;

        // Process each guessed character
        for (char ch : guessSequence) {
            int index = ch - 'a';

            if (letterCount[index] > 0) {
                // Correct letter guess
                matchedLetters += letterCount[index];
                letterCount[index] = -1; // Mark as used

                if (matchedLetters == targetWord.length()) {
                    break;
                }
            } else if (letterCount[index] == 0) {
                // Incorrect letter guess
                wrongGuesses++;
                letterCount[index] = -1; // Mark as tried

                if (wrongGuesses == 7) {
                    break;
                }
            }
        }

        // Determine game outcome
        if (matchedLetters == targetWord.length()) {
            cout << "You win." << endl;
        } else if (wrongGuesses == 7) {
            cout << "You lose." << endl;
        } else {
            cout << "You chickened out." << endl;
        }
    }

    return 0;
}

#include "napi.h"
