// Helper macro: throw JS TypeError with message s and return null
#define THROW_ERROR(msg) { \
    Napi::TypeError::New(env, msg).ThrowAsJavaScriptException(); \
    return env.Null(); \
}

using namespace Napi;

// Check if a Number value is an integer (within double precision)
inline bool isIntegerValue(const Value& val) {
    double d = val.As<Number>().DoubleValue();
    return static_cast<I>(d) == d;
}

// Get array element at index i from a JavaScript array
Value getArrayElement(const Value& arr, I idx) {
    Array jsArray = arr.As<Array>();
    return jsArray[idx];
}

// Determine K type symbol for a JS value
I inferKType(const Value& val) {
    if (val.IsNumber()) {
        return isIntegerValue(val) ? 'j' : 'f';
    }
    if (val.IsArray()) {
        return ' ';
    }
    return 0; // unsupported type
}

// Convert JS Value to K object
K jsToK(const Value& val) {
    I type = inferKType(val);
    switch (type) {
        case 'j': {
            return kj(val.As<Number>().Int64Value());
        }
        case 'f': {
            return kf(val.As<Number>().DoubleValue());
        }
        case ' ': {
            Array jsArr = val.As<Array>();
            I len = jsArr.Length();
            K kArr = k(' ', nullptr, len);
            if (!kArr) return nullptr;
            for (I i = 0; i < len; ++i) {
                K elem = jsToK(jsArr[i]);
                if (!elem) {
                    k(0, kArr); // cleanup on error
                    return nullptr;
                }
                X(kArr, i) = elem;
            }
            return kArr;
        }
        default:
            return nullptr;
    }
}

// Convert K object back to JS Value
Value kToJs(const Env& env, K kObj) {
    switch (kt(kObj)) {
        case KJ: {
            return Number::New(env, static_cast<F>(kObj->j));
        }
        caseKF: {
            return Number::New(env, kObj->f);
        }
        case ' ': {
            Array result = Array::New(env, kn(kObj));
            for (I i = 0; i < kn(kObj); ++i) {
                K elem = kx(kObj, i);
                result[i] = kToJs(env, elem);
            }
            return result;
        }
        default:
            return env.Null();
    }
}

// Main exported function: k(funcName, argsArray)
Value KFunctionWrapper(const CallbackInfo& info) {
    Env env = info.Env();

    // Validate argument count
    if (info.Length() != 2) {
        THROW_ERROR("Usage: k(functionName, argsArray)");
    }

    // Validate types
    if (!info[0].IsString() || !info[1].IsObject()) {
        THROW_ERROR("Arguments must be: (string function name, object/array arguments)");
    }

    // Extract function name
    std::string funcName = info[0].ToString().Utf8Value();

    // Convert JS args to K structure
    K kArgs = jsToK(info[1]);
    if (!kArgs) {
        THROW_ERROR("Failed to convert arguments to K format");
    }

    // Execute k function
    K result = k((K)funcName.c_str(), kArgs);
    if (!result || ERR(result)) {
        k(0, kArgs); // cleanup input
        THROW_ERROR("kdb+ function execution failed");
    }

    // Convert result back to JS
    Value jsResult = kToJs(env, result);

    // Cleanup both input and output K objects
    k(0, kArgs);
    k(0, result);

    return jsResult;
}

// Module initialization
Object Init(Env env, Object exports) {
    exports.Set(
        String::New(env, "k"),
        Function::New(env, KFunctionWrapper)
    );
    return exports;
}

NODE_API_MODULE(k, Init);

#include <keisan/angle/euler_angles.hpp>
