namespace keisan
{

std::ostream & operator<<(std::ostream & out, const EulerAngles & euler)
{
  return out << euler.roll << " " << euler.pitch << " " << euler.yaw;
}

EulerAngles::EulerAngles()
: roll(), pitch(), yaw()
{
}

EulerAngles::EulerAngles(const Angle & roll_val, const Angle & pitch_val, const Angle & yaw_val)
: roll(roll_val), pitch(pitch_val), yaw(yaw_val)
{
}

EulerAngles::EulerAngles(const EulerAngles & other)
: roll(other.roll), pitch(other.pitch), yaw(other.yaw)
{
}

EulerAngles & EulerAngles::operator=(const EulerAngles & other)
{
  if (this != &other) {
    roll = other.roll;
    pitch = other.pitch;
    yaw = other.yaw;
  }
  return *this;
}

bool EulerAngles::operator==(const EulerAngles & other) const
{
  return roll == other.roll && pitch == other.pitch && yaw == other.yaw;
}

bool EulerAngles::operator!=(const EulerAngles & other) const
{
  return !(*this == other);
}

Quaternion EulerAngles::quaternion() const
{
  // Compute half-angle trigonometric values
  double half_roll  = 0.5 * roll;
  double half_pitch = 0.5 * pitch;
  double half_yaw   = 0.5 * yaw;

  double sin_r = sin(half_roll);
  double cos_r = cos(half_roll);
  double sin_p = sin(half_pitch);
  double cos_p = cos(half_pitch);
  double sin_y = sin(half_yaw);
  double cos_y = cos(half_yaw);

  Quaternion result;
  result.x = sin_r * cos_p * cos_y - cos_r * sin_p * sin_y;
  result.y = cos_r * sin_p * cos_y + sin_r * cos_p * sin_y;
  result.z = cos_r * cos_p * sin_y - sin_r * sin_p * cos_y;
  result.w = cos_r * cos_p * cos_y + sin_r * sin_p * sin_y;

  return result;
}

