namespace jfs {
namespace support {

// JFSStat implementation
JFSStat::JFSStat(JFSStatKind k, llvm::StringRef n) : kind(k) {
  name = std::string(n.begin(), n.end());
}

JFSStat::~JFSStat() = default;

void JFSStat::dump() const {
  llvm::ScopedPrinter printer(llvm::errs());
  printYAML(printer);
}

llvm::StringRef JFSStat::getName() const {
  return llvm::StringRef(name);
}

// JFSTimerStat implementation
JFSTimerStat::JFSTimerStat(RecordTy rec, llvm::StringRef n)
    : JFSStat(SINGLE_TIMER, n), record(std::move(rec)) {}

JFSTimerStat::~JFSTimerStat() = default;

void JFSTimerStat::printYAML(llvm::ScopedPrinter& sp) const {
  sp.indent();
  auto& out = sp.getOStream();
  out << "\n";
  sp.startLine() << "name: " << getName() << "\n";

  constexpr char timeFormat[] = "%.6f";
  sp.startLine() << "user_time: "
                 << llvm::format(timeFormat, record.getUserTime()) << "\n";
  sp.startLine() << "sys_time: "
                 << llvm::format(timeFormat, record.getSystemTime()) << "\n";
  sp.startLine() << "wall_time: "
                 << llvm::format(timeFormat, record.getWallTime()) << "\n";
  sp.startLine() << "mem_use: " << record.getMemUsed() << "\n";

  sp.unindent();
}

// JFSAggregateTimerStat implementation
JFSAggregateTimerStat::JFSAggregateTimerStat(llvm::StringRef n)
    : JFSStat(AGGREGATE_TIMER, n) {}

JFSAggregateTimerStat::~JFSAggregateTimerStat() = default;

void JFSAggregateTimerStat::append(std::unique_ptr<JFSTimerStat> timer) {
  timers.emplace_back(std::move(timer));
}

void JFSAggregateTimerStat::clear() {
  timers.clear();
}

void JFSAggregateTimerStat::printYAML(llvm::ScopedPrinter& sp) const {
  sp.indent();
  auto& out = sp.getOStream();
  out << "\n";
  sp.startLine() << "name: " << getName() << "\n";
  sp.startLine() << "stats:";

  if (timers.empty()) {
    out << " []\n";
    sp.unindent();
    return;
  }

  out << "\n";
  sp.indent();

  for (const auto& item : timers) {
    sp.startLine() << "-";
    item->printYAML(sp);
  }

  sp.unindent();
  sp.unindent();
}

}
}

#include <string>
#include <cstring>
#include <vector>
#include <iostream>
#include <fstream>
#include "socket.hh"
#include "gason.h"
#include "sql_message.hh"

// Function declarations with minor renaming and reordering
int receive_response(socket_t &, std::string &);
int fetch_http_headers(socket_t &, std::string &);

void print_usage()
{
  std::cout << "usage: sqlite_client -u URI <-p PORT> <-h>" << std::endl;
  std::cout << "-u URI" << std::endl;
  std::cout << "-h: help, exit" << std::endl;
  std::cout << "-o PORT: port (default 3000)" << std::endl;
  exit(0);
}

int main(int argc, char *argv[])
{
  std::string target_uri;
  unsigned short server_port = 3000;
  sql_action_t action_type = sql_action_t::none;
  std::string new_item;
  std::string new_place;

  for (int i = 1; i < argc && argv[i][0] == '-'; ++i)
  {
    switch (argv[i][1])
    {
    case 'h':
      print_usage();
      break;
    case 'o':
      server_port = static_cast<unsigned short>(atoi(argv[i + 1]));
      ++i;
      break;
    case 'u':
      target_uri = argv[i + 1];
      ++i;
      break;
    }
  }

  // Parse URI to extract host and endpoint
  std::size_t protocol_end = target_uri.find("://");
  if (protocol_end == std::string::npos)
  {
    print_usage();
  }
  protocol_end += 3;
  std::size_t path_start = target_uri.find("/", protocol_end + 1);
  std::string hostname = target_uri.substr(protocol_end, path_start - protocol_end);
  std::cout << "host: " << hostname << std::endl;

  std::string endpoint = target_uri.substr(path_start);

  // Map endpoint to SQL actions
  if (endpoint == "/get_places")
  {
    action_type = sql_action_t::get_places;
  }
  else if (endpoint == "/get_items")
  {
    action_type = sql_action_t::get_items;
  }
  else if (endpoint == "/create_table_places")
  {
    action_type = sql_action_t::create_table_places;
  }
  else if (endpoint == "/create_table_items")
  {
    action_type = sql_action_t::create_table_items;
  }
  else if (endpoint.find("/insert_place/") == 0)
  {
    action_type = sql_action_t::insert_place;
    new_place = endpoint.substr(std::string("/insert_place/").length());
  }
  else if (endpoint.find("/insert_item/") == 0)
  {
    action_type = sql_action_t::insert_item;
    new_item = endpoint.substr(std::string("/insert_item/").length());
  }
  else if (endpoint == "/select_places")
  {
    action_type = sql_action_t::select_places;
  }
  else if (endpoint == "/select_items")
  {
    action_type = sql_action_t::select_items;
  }
  else
  {
    print_usage();
  }

  // Build JSON request body
  std::string json_payload = "[";
  sql_t db_handler;
  switch (action_type)
  {
  case sql_action_t::none:
    print_usage();
    return 0;
  case sql_action_t::create_table_places:
    json_payload += "\"";
    json_payload += db_handler.create_table_places();
    json_payload += "\"";
    break;
  case sql_action_t::create_table_items:
    json_payload += "\"";
    json_payload += db_handler.create_table_items();
    json_payload += "\"";
    break;
  case sql_action_t::insert_place:
    assert(!new_place.empty());
    json_payload += "\"";
    json_payload += db_handler.insert_place(new_place.c_str());
    json_payload += "\"";
    break;
  case sql_action_t::insert_item:
    assert(!new_item.empty());
    json_payload += "\"";
    json_payload += db_handler.insert_item(new_item.c_str(), "home");
    json_payload += "\"";
    break;
  case sql_action_t::select_places:
    json_payload += "\"";
    json_payload += db_handler.select_places(nullptr);
    json_payload += "\"";
    break;
  case sql_action_t::select_items:
    json_payload += "\"";
    json_payload += db_handler.select_items(nullptr);
    json_payload += "\"";
    break;
  default:
    break;
  }
  json_payload += "]";

  // Write JSON to file
  std::ofstream output_file("request.json");
  output_file << json_payload;
  output_file.close();

  // Prepare HTTP request
  char request_buffer[1024];
  if (action_type == sql_action_t::get_items || action_type == sql_action_t::get_places)
  {
    sprintf(request_buffer, "GET %s HTTP/1.1\r\n\r\n", endpoint.c_str());
  }
  else
  {
    sprintf(request_buffer, "POST / HTTP/1.1\r\nContent-Length: %zu\r\nConnection: close\r\n\r\n%s",
            strlen(json_payload.c_str()), json_payload.c_str());
  }

#if _MSC_VER
  Sleep(500);
#endif

  tcp_client_t client(hostname.c_str(), server_port);
  std::cout << "client connecting to: " << hostname << ":" << server_port 
            << " <" << client.m_socket_fd << "> " << std::endl;

  if (client.open() < 0)
  {
    std::string error_msg = "connect error to: ";
    error_msg += hostname;
    std::cout << error_msg << std::endl;
    return 1;
  }

  std::cout << "client: connected to: " << hostname << ":" << server_port << std::endl;

  // Send request
  if (client.write_all(request_buffer, strlen(request_buffer)) < 0)
  {
    std::cerr << "Failed to send request" << std::endl;
  }
  std::cout << "client sent: \n" << request_buffer << std::endl;

  // Receive response
  std::string server_response;
  if (receive_response(client, server_response) > 0)
  {
    std::cout << "client received:\n" << server_response << std::endl;
  }

  client.close_socket();
  return 0;
}

int receive_response(socket_t &sock, std::string &response_data)
{
  std::string header_section;
  if (fetch_http_headers(sock, header_section) == 0)
  {
    return 0;
  }

  unsigned int content_length = static_cast<unsigned int>(
      http_get_field("Content-Length: ", header_section));

  if (content_length > 0)
  {
    char *buffer = new char[content_length];
    if (sock.read_all(buffer, content_length) < 0)
    {
      std::cout << "recv error: " << strerror(errno) << std::endl;
    }
    response_data.assign(buffer, content_length);
    delete[] buffer;
    return 1;
  }

  return 1;
}

int fetch_http_headers(socket_t &sock, std::string &header_output)
{
  int bytes_received;
  const int buffer_capacity = 4096;
  char temp_buffer[buffer_capacity];

  if ((bytes_received = recv(sock.m_socket_fd, temp_buffer, buffer_capacity, MSG_PEEK)) == -1)
  {
    std::cout << "recv error: " << strerror(errno) << std::endl;
    return -1;
  }

  if (bytes_received == 0)
  {
    return 0;
  }

  std::string peeked_data(temp_buffer);
  size_t header_terminator = peeked_data.find("\r\n\r\n");

  if (header_terminator == std::string::npos)
  {
    std::cout << "HTTP header bad format" << std::endl;
    return -1;
  }

  header_output = peeked_data.substr(0, header_terminator + 4);
  int header_bytes = static_cast<int>(header_terminator + 4);

  if ((bytes_received = recv(sock.m_socket_fd, temp_buffer, header_bytes, 0)) == -1)
  {
    std::cout << "recv error: " << strerror(errno) << std::endl;
  }

  std::string verified_header(temp_buffer);
  assert(verified_header == peeked_data);

  std::cout << "HTTP header size: " << header_output.size() << std::endl;
  std::cout << header_output.c_str() << std::endl;

  return 1;
}

#include "runtime/date-parse-util.h"
#include "cctz/civil_time.h"
