// Worker class responsible for mesh construction off the game thread
class FVoxelAsyncMeshBuilder : public FVoxelAsyncWork
{
public:
	static FVoxelAsyncMeshBuilder* Spawn(
		FVoxelRendererBasicMeshHandler& Owner,
		FVoxelRendererBasicMeshHandler::FChunkInfoRef ChunkRef,
		FVoxelChunkMeshesToBuild&& MeshData)
	{
		auto* Info = Owner.GetChunkInfo(ChunkRef);
		check(Info);
		return new FVoxelAsyncMeshBuilder(
			ChunkRef,
			Info->Position,
			Owner,
			Info->UpdateIndex.ToSharedRef(),
			MoveTemp(MeshData));
	}

private:
	const FVoxelRendererBasicMeshHandler::FChunkInfoRef ChunkReference;
	const FIntVector ChunkWorldLocation;
	const FVoxelRendererSettingsBase RendererConfig;
	const TVoxelWeakPtr<FVoxelRendererBasicMeshHandler> WeakOwner;
	const FVoxelChunkMeshesToBuild MeshDataToProcess;
	const TVoxelSharedRef<FThreadSafeCounter> SequenceNumberPtr;
	const int32 ExpectedSequenceNumber;

	FVoxelAsyncMeshBuilder(
		FVoxelRendererBasicMeshHandler::FChunkInfoRef Ref,
		const FIntVector& Location,
		FVoxelRendererBasicMeshHandler& Owner,
		const TVoxelSharedRef<FThreadSafeCounter>& SeqPtr,
		FVoxelChunkMeshesToBuild&& Data)
		: FVoxelAsyncWork(STATIC_FNAME("FVoxelAsyncMeshBuilder"), 1e9, true)
		, ChunkReference(Ref)
		, ChunkWorldLocation(Location)
		, RendererConfig(static_cast<const FVoxelRendererSettingsBase&>(Owner.Renderer.Settings))
		, WeakOwner(StaticCastVoxelSharedRef<FVoxelRendererBasicMeshHandler>(Owner.AsShared()))
		, MeshDataToProcess(MoveTemp(Data))
		, SequenceNumberPtr(SeqPtr)
		, ExpectedSequenceNumber(SeqPtr->GetValue())
	{
	}

	~FVoxelAsyncMeshBuilder() = default;

	virtual uint32 GetPriority() const override
	{
		return 0u;
	}

	virtual void DoWork() override
	{
		if (SequenceNumberPtr->GetValue() > ExpectedSequenceNumber)
		{
			// Task superseded by newer request; abort
			return;
		}

		auto Result = FVoxelRenderUtilities::GenerateMeshes_AnyThread(
			MeshDataToProcess,
			RendererConfig,
			ChunkWorldLocation,
			SequenceNumberPtr,
			ExpectedSequenceNumber);

		if (!Result.IsValid())
		{
			// Canceled mid-processing
			return;
		}

		TSharedPtr<FVoxelRendererBasicMeshHandler> OwnerPtr = WeakOwner.Pin();
		if (OwnerPtr.IsValid())
		{
			OwnerPtr->OnMeshBuilt(ChunkReference, ExpectedSequenceNumber, MoveTemp(Result));
			FVoxelUtilities::ScheduleDestructionOnGameThread(OwnerPtr);
		}
	}
};

// Destructor ensures cleanup before destruction
FVoxelRendererBasicMeshHandler::~FVoxelRendererBasicMeshHandler()
{
	DrainPendingMeshUpdates();
	DrainPendingActions(MAX_dbl);

	ensureMsgf(ChunkInfos.Num() == 0, TEXT("All chunks should have been removed"));
}

