}

// Processes queued actions based on type
void FVoxelRendererBasicMeshHandler::ApplyAction(const FAction& Action)
{
	VOXEL_FUNCTION_COUNTER();

	switch (Action.Action)
	{
	case EAction::UpdateChunk:
	{
		const auto& UpdateParams = Action.UpdateChunk();
		check(UpdateParams.InitialCall.MainChunk);
		const auto& MainChunk = *UpdateParams.InitialCall.MainChunk;
		const auto* TransitionChunk = UpdateParams.InitialCall.TransitionChunk;

		ensure(!MainChunk.IsEmpty() || (TransitionChunk && !TransitionChunk->IsEmpty()));

		FChunkInfo& TargetChunk = ChunkInfos[Action.ChunkId];

		if (!TargetChunk.Materials.IsValid())
		{
			TargetChunk.Materials = MakeShared<FVoxelChunkMaterials>();
		}

		if (!TargetChunk.UpdateIndex.IsValid())
		{
			TargetChunk.UpdateIndex = MakeVoxelShared<FThreadSafeCounter>();
		}

		// Invalidate prior build attempts
		TargetChunk.UpdateIndex->Increment();

		// Prepare mesh data for async processing
		FVoxelChunkMeshesToBuild MeshesToConstruct = FVoxelRenderUtilities::ExtractMeshesForProcessing(
			TargetChunk.LOD,
			TargetChunk.Position,
			Renderer.Settings,
			UpdateParams.InitialCall.ChunkSettings,
			*TargetChunk.Materials,
			MainChunk,
			TransitionChunk,
			Renderer.OnMaterialInstanceCreated,
			TargetChunk.DitheringInfo);

		// Launch background task
		auto* BuilderTask = FVoxelAsyncMeshBuilder::Spawn(*this, { Action.ChunkId, TargetChunk.UniqueId }, MoveTemp(MeshesToConstruct));
		Renderer.Settings.Pool->Submit(EVoxelTaskType::MeshMerge, BuilderTask);

		// Enqueue post-build action
		FAction DeferredAction;
		DeferredAction.Action = EAction::UpdateChunk;
		DeferredAction.ChunkId = Action.ChunkId;
		DeferredAction.UpdateChunk().AfterCall.UpdateIndex = TargetChunk.UpdateIndex->GetValue();
		DeferredAction.UpdateChunk().AfterCall.DistanceFieldVolumeData = MainChunk.GetDistanceFieldVolumeData();
		ActionQueue.Enqueue(DeferredAction);

		if (Renderer.Settings.RenderType == EVoxelRenderType::SurfaceNets)
		{
			ConfigureTransitionsMaskForSurfaceNets(Action.ChunkId, UpdateParams.InitialCall.ChunkSettings.TransitionsMask);
		}
		break;
	}

	case EAction::RemoveChunk:
	case EAction::DitherChunk:
	case EAction::ResetDithering:
	case EAction::SetTransitionsMaskForSurfaceNets:
	case EAction::HideChunk:
	case EAction::ShowChunk:
	{
		ActionQueue.Enqueue(Action);
		break;
	}

	default:
		ensure(false);
	}
}

// Clears all material references across chunks
void FVoxelRendererBasicMeshHandler::ClearChunkMaterials()
{
	for (auto& Chunk : ChunkInfos)
	{
		if (Chunk.Materials.IsValid())
		{
			Chunk.Materials->Clear();
		}
	}
}

// Tick handler: flush pending work and update stats
void FVoxelRendererBasicMeshHandler::Tick(double TimeLimit)
{
	VOXEL_FUNCTION_COUNTER();
	IVoxelRendererMeshHandler::Tick(TimeLimit);
	DrainPendingMeshUpdates();
	DrainPendingActions(TimeLimit);
	Renderer.Settings.DebugManager->ReportMeshActionQueueLength(ActionQueue.Num());
}

// Applies completed mesh builds from async callbacks
void FVoxelRendererBasicMeshHandler::DrainPendingMeshUpdates()
{
	VOXEL_FUNCTION_COUNTER();

	FBuildCallback Item;
	while (CallbackQueue.Dequeue(Item))
	{
		auto& BuiltResult = Item.BuiltData;
		if (!ensure(BuiltResult.BuiltMeshes.IsValid())) continue;

		FChunkInfo* Target = GetChunkInfo(Item.ChunkInfoRef);
		if (Target && BuiltResult.UpdateIndex >= Target->UpdateIndex->GetValue())
		{
			ensure(BuiltResult.UpdateIndex == Target->UpdateIndex->GetValue());
			Target->BuiltData = MoveTemp(BuiltResult);
		}
	}
}

// Executes pending actions in order, respecting timing constraints
void FVoxelRendererBasicMeshHandler::DrainPendingActions(double MaxTimeSeconds)
{
	VOXEL_FUNCTION_COUNTER();

	FAction CurrentAction;
	double CurrentTime = FPlatformTime::Seconds();

	// Process high-priority dither-in actions immediately regardless of time limit
	while (ActionQueue.Peek(CurrentAction) &&
		   (CurrentTime < MaxTimeSeconds ||
			(CurrentAction.Action == EAction::DitherChunk &&
			 CurrentAction.DitherChunk().DitheringType == EDitheringType::Classic_DitherIn)))
	{
		FChunkInfo& TargetChunk = ChunkInfos[CurrentAction.ChunkId];
		ReleaseMeshResources(TargetChunk.Meshes);

		if (IsDestroying() && CurrentAction.Action != EAction::RemoveChunk)
		{
			ActionQueue.Pop();
			continue;
		}

		switch (CurrentAction.Action)
		{
		case EAction::UpdateChunk:
		{
			const int32 RequiredSequence = CurrentAction.UpdateChunk().AfterCall.UpdateIndex;
			if (TargetChunk.MeshUpdateIndex >= RequiredSequence)
			{
				// Already processed this update
				break;
			}

			if (RequiredSequence > TargetChunk.BuiltData.UpdateIndex)
			{
				// Still waiting for build result
				if (TargetChunk.BuiltData.UpdateIndex != -1)
				{
					// Discard outdated cached data
					ensure(TargetChunk.BuiltData.BuiltMeshes.IsValid());
					TargetChunk.BuiltData.BuiltMeshes.Reset();
					TargetChunk.BuiltData.UpdateIndex = -1;
				}
				return;
			}

			// Apply freshly built meshes
			TUniquePtr<FVoxelBuiltChunkMeshes> FinalMeshes = MoveTemp(TargetChunk.BuiltData.BuiltMeshes);
			TargetChunk.MeshUpdateIndex = TargetChunk.BuiltData.UpdateIndex;
			TargetChunk.BuiltData.UpdateIndex = -1;

			if (!ensure(FinalMeshes.IsValid())) break;

			int32 SectionIndex = 0;
			for (const auto& [MeshConfig, Sections] : *FinalMeshes)
			{
				if (TargetChunk.Meshes.Num() <= SectionIndex)
				{
					auto* NewMesh = AllocateNewMesh(CurrentAction.ChunkId, TargetChunk.Position, TargetChunk.LOD);
					if (!ensure(NewMesh)) return;
					TargetChunk.Meshes.Add(NewMesh);
				}

				auto& MeshRef = *TargetChunk.Meshes[SectionIndex];
				MeshConfig.ApplyTo(MeshRef);
				MeshRef.SetDistanceFieldData(nullptr);
				MeshRef.ClearSections(EVoxelProcMeshSectionUpdate::DelayUpdate);

				for (const auto& [SectionID, ProcSection] : Sections)
				{
					if (!ensure(ProcSection.IsValid())) continue;
					MeshRef.AddProcMeshSection(SectionID, MoveTemp(ProcSection), EVoxelProcMeshSectionUpdate::DelayUpdate);
				}

				MeshRef.FinishSectionsUpdates();
				++SectionIndex;
			}

			// Remove excess meshes
			for (; SectionIndex < TargetChunk.Meshes.Num(); ++SectionIndex)
			{
				auto& MeshRef = *TargetChunk.Meshes[SectionIndex];
				MeshRef.SetDistanceFieldData(nullptr);
				MeshRef.ClearSections(EVoxelProcMeshSectionUpdate::UpdateNow);
			}

			// Attach distance field if present
			const auto& DFData = CurrentAction.UpdateChunk().AfterCall.DistanceFieldVolumeData;
			if (DFData.IsValid() && ensure(TargetChunk.Meshes.Num() > 0))
			{
				TargetChunk.Meshes[0]->SetDistanceFieldData(DFData);
			}
			break;
		}

		case EAction::RemoveChunk:
		{
			for (auto& MeshPtr : TargetChunk.Meshes)
			{
				RemoveMesh(*MeshPtr);
			}
			ChunkInfos.RemoveAt(CurrentAction.ChunkId);
			break;
		}

		case EAction::DitherChunk:
		{
			TargetChunk.DitheringInfo.bIsValid = true;
			TargetChunk.DitheringInfo.DitheringType = CurrentAction.DitherChunk().DitheringType;
			TargetChunk.DitheringInfo.Time = FVoxelRenderUtilities::GetCurrentWorldTime(Renderer.Settings.World.Get());

			for (auto& MeshPtr : TargetChunk.Meshes)
			{
				FVoxelRenderUtilities::BeginMeshFadeEffect(
					*MeshPtr,
					Renderer.Settings,
					TargetChunk.DitheringInfo);
			}
			break;
		}

		case EAction::ResetDithering:
		{
			TargetChunk.DitheringInfo.bIsValid = false;
			for (auto& MeshPtr : TargetChunk.Meshes)
			{
				FVoxelRenderUtilities::StopMeshFadeEffect(*MeshPtr, Renderer.Settings);
			}
			break;
		}

		case EAction::SetTransitionsMaskForSurfaceNets:
		{
			for (auto& MeshPtr : TargetChunk.Meshes)
			{
				FVoxelRenderUtilities::AssignMeshTransitionMask(*MeshPtr, CurrentAction.SetTransitionsMaskForSurfaceNets().TransitionsMask);
			}
			break;
		}

		case EAction::HideChunk:
		{
			for (auto& MeshPtr : TargetChunk.Meshes)
			{
				FVoxelRenderUtilities::SetMeshVisibility(*MeshPtr, false);
			}
			break;
		}

		case EAction::ShowChunk:
		{
			for (auto& MeshPtr : TargetChunk.Meshes)
			{
				FVoxelRenderUtilities::SetMeshVisibility(*MeshPtr, true);
			}
			break;
		}

		default:
			ensure(false);
		}

		if (CVarLogActionQueue.GetValueOnGameThread() != 0)
		{
			LOG_VOXEL(Log, TEXT("Processed action: LOD=%d; Type=%s; Pos=%s"),
				TargetChunk.LOD,
				*CurrentAction.ToString(),
				*TargetChunk.Position.ToString());
		}

		ActionQueue.Pop();
	}
}

// Callback invoked after mesh building completes
void FVoxelRendererBasicMeshHandler::OnMeshBuilt(FChunkInfoRef Ref, int32 Sequence, TUniquePtr<FVoxelBuiltChunkMeshes> Meshes)
{
	CallbackQueue.Enqueue({ Ref, FChunkBuiltData{ Sequence, MoveTemp(Meshes) } });
}

