        // Helper to map normalized types to Vulkan formats
        VkFormat MapNormalizedFormat(const GLint components, const GLenum dataType) noexcept {
            struct FormatEntry {
                GLint size;
                GLenum type;
                VkFormat fmt;
            };

            static constexpr FormatEntry normalizedTable[] = {
                {1, GL_UNSIGNED_BYTE, VK_FORMAT_R8_UNORM},
                {1, GL_BYTE,          VK_FORMAT_R8_SNORM},
                {1, GL_UNSIGNED_SHORT,VK_FORMAT_R16_UNORM},
                {1, GL_SHORT,         VK_FORMAT_R16_SNORM},

                {2, GL_UNSIGNED_BYTE, VK_FORMAT_R8G8_UNORM},
                {2, GL_BYTE,          VK_FORMAT_R8G8_SNORM},
                {2, GL_UNSIGNED_SHORT,VK_FORMAT_R16G16_UNORM},
                {2, GL_SHORT,         VK_FORMAT_R16G16_SNORM},

                {3, GL_UNSIGNED_BYTE, VK_FORMAT_R8G8B8_UNORM},
                {3, GL_BYTE,          VK_FORMAT_R8G8B8_SNORM},
                {3, GL_UNSIGNED_SHORT,VK_FORMAT_R16G16B16_UNORM},
                {3, GL_SHORT,         VK_FORMAT_R16G16B16_SNORM},

                {4, GL_UNSIGNED_BYTE, VK_FORMAT_R8G8B8A8_UNORM},
                {4, GL_BYTE,          VK_FORMAT_R8G8B8A8_SNORM},
                {4, GL_UNSIGNED_SHORT,VK_FORMAT_R16G16B16A16_UNORM},
                {4, GL_SHORT,         VK_FORMAT_R16G16B16A16_SNORM}
            };

            for (const auto& entry : normalizedTable) {
                if (entry.size == components && entry.type == dataType)
                    return entry.fmt;
            }
            return VK_FORMAT_UNDEFINED;
        }

        // Helper to map integer (non-normalized) types to Vulkan formats
        VkFormat MapIntegerFormat(const GLint components, const GLenum dataType) noexcept {
            struct IntFormatEntry {
                GLint size;
                GLenum type;
                VkFormat fmt;
            };

            static constexpr IntFormatEntry intTable[] = {
                {1, GL_UNSIGNED_BYTE,  VK_FORMAT_R8_UINT},
                {1, GL_BYTE,           VK_FORMAT_R8_SINT},
                {1, GL_UNSIGNED_SHORT, VK_FORMAT_R16_UINT},
                {1, GL_SHORT,          VK_FORMAT_R16_SINT},
                {1, GL_UNSIGNED_INT,   VK_FORMAT_R32_UINT},
                {1, GL_INT,            VK_FORMAT_R32_SINT},

                {2, GL_UNSIGNED_BYTE,  VK_FORMAT_R8G8_UINT},
                {2, GL_BYTE,           VK_FORMAT_R8G8_SINT},
                {2, GL_UNSIGNED_SHORT, VK_FORMAT_R16G16_UINT},
                {2, GL_SHORT,          VK_FORMAT_R16G16_SINT},
                {2, GL_UNSIGNED_INT,   VK_FORMAT_R32G32_UINT},
                {2, GL_INT,            VK_FORMAT_R32G32_SINT},

                {3, GL_UNSIGNED_BYTE,  VK_FORMAT_R8G8B8_UINT},
                {3, GL_BYTE,           VK_FORMAT_R8G8B8_SINT},
                {3, GL_UNSIGNED_SHORT, VK_FORMAT_R16G16B16_UINT},
                {3, GL_SHORT,          VK_FORMAT_R16G16B16_SINT},
                {3, GL_UNSIGNED_INT,   VK_FORMAT_R32G32B32_UINT},
                {3, GL_INT,            VK_FORMAT_R32G32B32_SINT},

                {4, GL_UNSIGNED_BYTE,  VK_FORMAT_R8G8B8A8_UINT},
                {4, GL_BYTE,           VK_FORMAT_R8G8B8A8_SINT},
                {4, GL_UNSIGNED_SHORT, VK_FORMAT_R16G16B16A16_UINT},
                {4, GL_SHORT,          VK_FORMAT_R16G16B16A16_SINT},
                {4, GL_UNSIGNED_INT,   VK_FORMAT_R32G32B32A32_UINT},
                {4, GL_INT,            VK_FORMAT_R32G32B32A32_SINT}
            };

            for (const auto& entry : intTable) {
                if (entry.size == components && entry.type == dataType)
                    return entry.fmt;
            }
            return VK_FORMAT_UNDEFINED;
        }

        // Helper to map floating-point types to Vulkan formats
        VkFormat MapFloatFormat(const GLint components, const GLenum dataType) noexcept {
            struct FloatFormatEntry {
                GLint size;
                GLenum type;
                VkFormat fmt;
            };

            static constexpr FloatFormatEntry floatTable[] = {
                {1, GL_HALF_FLOAT, VK_FORMAT_R16_SFLOAT},
                {1, GL_FLOAT,      VK_FORMAT_R32_SFLOAT},
                {1, GL_DOUBLE,     VK_FORMAT_R64_SFLOAT},

                {2, GL_HALF_FLOAT, VK_FORMAT_R16G16_SFLOAT},
                {2, GL_FLOAT,      VK_FORMAT_R32G32_SFLOAT},
                {2, GL_DOUBLE,     VK_FORMAT_R64G64_SFLOAT},

                {3, GL_HALF_FLOAT, VK_FORMAT_R16G16B16_SFLOAT},
                {3, GL_FLOAT,      VK_FORMAT_R32G32B32_SFLOAT},
                {3, GL_DOUBLE,     VK_FORMAT_R64G64B64_SFLOAT},

                {4, GL_HALF_FLOAT, VK_FORMAT_R16G16B16A16_SFLOAT},
                {4, GL_FLOAT,      VK_FORMAT_R32G32B32A32_SFLOAT},
                {4, GL_DOUBLE,     VK_FORMAT_R64G64B64A64_SFLOAT}
            };

            for (const auto& entry : floatTable) {
                if (entry.size == components && entry.type == dataType)
                    return entry.fmt;
            }
            return VK_FORMAT_UNDEFINED;
        }

        // Renamed and refactored versions of original functions
        VkFormat GetFormat(const GLint size, const GLenum type, const bool normalized) noexcept {
            return normalized ? MapNormalizedFormat(size, type) : 
                   (type == GL_HALF_FLOAT || type == GL_FLOAT || type == GL_DOUBLE) ?
                   MapFloatFormat(size, type) : MapIntegerFormat(size, type);
        }

        VkFormat GetFormatI(const GLint size, const GLenum type) noexcept {
            return MapIntegerFormat(size, type);
        }

        VkFormat GetFormatF(const GLint size, const GLenum type) noexcept {
            return MapFloatFormat(size, type);
        }

        struct DescriptorLayoutBuilder final {
            std::vector<VkDescriptorSetLayoutBinding> bindings;
        };

        struct GraphicsPipelineBuilder final {
            std::vector<VkVertexInputAttributeDescription> attributes;
            std::vector<VkVertexInputBindingDescription> vertexBindings;
            const Program* programRef = nullptr;
            const PipelineLayout* layoutRef = nullptr;

            VkVertexInputAttributeDescription& AppendAttribute(GLuint locationIndex) noexcept {
                attributes.emplace_back();
                auto& attr = attributes.back();
                attr.location = static_cast<uint32_t>(locationIndex);
                return attr;
            }

            VkVertexInputBindingDescription& AppendBinding(GLuint bindingIndex) noexcept {
                vertexBindings.emplace_back();
                auto& bind = vertexBindings.back();
                bind.binding = static_cast<uint32_t>(bindingIndex);
                return bind;
            }
        };

        // Convert OpenGL enum to Vulkan descriptor type
        VkDescriptorType TranslateDescriptorType(const GLenum glType) noexcept {
            switch (glType) {
            case GL_UNIFORM_BUFFER: return VK_DESCRIPTOR_TYPE_UNIFORM_BUFFER;
            default: return VK_DESCRIPTOR_TYPE_RANGE_SIZE; // Use end range as undefined
            }
        }
    }

    PipelineLayout::PipelineLayout() noexcept {
        _Layout = reinterpret_cast<uintptr_t>(new DescriptorLayoutBuilder) + 1;
    }

    PipelineLayout::~PipelineLayout() noexcept {
        if (_Layout & 1) {
            delete reinterpret_cast<DescriptorLayoutBuilder*>(_Layout - 1);
        } else {
            vkDestroyPipelineLayout(D::context->GetDevice(), reinterpret_cast<VkPipelineLayout>(_Layout), nullptr);
            vkDestroyDescriptorSetLayout(D::context->GetDevice(), _Sets, nullptr);
        }
    }

    void PipelineLayout::Compile() noexcept {
        if (_Layout & 1) {
            auto builder = reinterpret_cast<DescriptorLayoutBuilder*>(_Layout - 1);

            VkDescriptorSetLayoutCreateInfo descLayoutInfo = {};
            descLayoutInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
            descLayoutInfo.pNext = nullptr;
            descLayoutInfo.bindingCount = static_cast<uint32_t>(builder->bindings.size());
            descLayoutInfo.pBindings = builder->bindings.data();

            vkCreateDescriptorSetLayout(D::context->GetDevice(), &descLayoutInfo, nullptr, &_Sets);

            delete builder;

            VkPipelineLayoutCreateInfo pipelineLayoutInfo = {};
            pipelineLayoutInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO;
            pipelineLayoutInfo.pNext = nullptr;
            pipelineLayoutInfo.pushConstantRangeCount = 0;
            pipelineLayoutInfo.pPushConstantRanges = nullptr;
            pipelineLayoutInfo.setLayoutCount = 1;
            pipelineLayoutInfo.pSetLayouts = &_Sets;

            vkCreatePipelineLayout(D::context->GetDevice(), &pipelineLayoutInfo, nullptr,
                reinterpret_cast<VkPipelineLayout*>(&_Layout));
        }
    }

    void PipelineLayout::AddBinding(GLuint binding, GLenum type) noexcept {
        if (_Layout & 1) {
            auto builder = reinterpret_cast<DescriptorLayoutBuilder*>(_Layout - 1);
            VkDescriptorSetLayoutBinding vkBinding = {};
            vkBinding.binding = binding;
            vkBinding.descriptorType = TranslateDescriptorType(type);
            vkBinding.descriptorCount = 1;
            vkBinding.stageFlags = VK_SHADER_STAGE_ALL;
            vkBinding.pImmutableSamplers = nullptr;
            builder->bindings.push_back(vkBinding);
        }
    }

    Pipeline::Pipeline() noexcept {
        _Pipeline = reinterpret_cast<uintptr_t>(new GraphicsPipelineBuilder) + 1;
    }

    Pipeline::~Pipeline() noexcept {
        if (_Pipeline & 1) {
            delete reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1);
        } else {
            vkDestroyPipeline(D::context->GetDevice(), reinterpret_cast<VkPipeline>(_Pipeline), nullptr);
        }
    }

    void Pipeline::ElementBuffer(GLuint buffer) noexcept {}

    void Pipeline::Compile() noexcept {
        if (_Pipeline & 1) {
            auto builder = reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1);
            auto shaderStages = builder->programRef->DumpStages();

            VkPipelineVertexInputStateCreateInfo vertexInputInfo = {};
            vertexInputInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_VERTEX_INPUT_STATE_CREATE_INFO;
            vertexInputInfo.vertexBindingDescriptionCount = static_cast<uint32_t>(builder->vertexBindings.size());
            vertexInputInfo.vertexAttributeDescriptionCount = static_cast<uint32_t>(builder->attributes.size());
            vertexInputInfo.pVertexBindingDescriptions = builder->vertexBindings.data();
            vertexInputInfo.pVertexAttributeDescriptions = builder->attributes.data();

            VkPipelineInputAssemblyStateCreateInfo inputAssembly = {};
            inputAssembly.sType = VK_STRUCTURE_TYPE_PIPELINE_INPUT_ASSEMBLY_STATE_CREATE_INFO;
            inputAssembly.topology = VK_PRIMITIVE_TOPOLOGY_TRIANGLE_LIST;
            inputAssembly.primitiveRestartEnable = VK_FALSE;

            VkDynamicState dynamicStates[VK_DYNAMIC_STATE_RANGE_SIZE];
            memset(dynamicStates, 0, sizeof dynamicStates);
            VkPipelineDynamicStateCreateInfo dynamicStateInfo = {};
            dynamicStateInfo.sType = VK_STRUCTURE_TYPE_PIPELINE_DYNAMIC_STATE_CREATE_INFO;
            dynamicStateInfo.pNext = nullptr;
            dynamicStateInfo.pDynamicStates = dynamicStates;
            dynamicStateInfo.dynamicStateCount = 0;

            VkPipelineViewportStateCreateInfo viewportState = {};
            viewportState.sType = VK_STRUCTURE_TYPE_PIPELINE_VIEWPORT_STATE_CREATE_INFO;
            viewportState.pNext = nullptr;
            viewportState.flags = 0;
            viewportState.viewportCount = 1;
            dynamicStates[dynamicStateInfo.dynamicStateCount++] = VK_DYNAMIC_STATE_VIEWPORT;
            viewportState.scissorCount = 1;
            dynamicStates[dynamicStateInfo.dynamicStateCount++] = VK_DYNAMIC_STATE_SCISSOR;
            viewportState.pScissors = nullptr;
            viewportState.pViewports = nullptr;

            VkPipelineColorBlendAttachmentState colorBlendAttachment = {};
            colorBlendAttachment.colorWriteMask =
                VK_COLOR_COMPONENT_R_BIT | VK_COLOR_COMPONENT_G_BIT |
                VK_COLOR_COMPONENT_B_BIT | VK_COLOR_COMPONENT_A_BIT;
            colorBlendAttachment.blendEnable = VK_FALSE;

            VkPipelineColorBlendStateCreateInfo colorBlending = {};
            colorBlending.sType = VK_STRUCTURE_TYPE_PIPELINE_COLOR_BLEND_STATE_CREATE_INFO;
            colorBlending.logicOpEnable = VK_FALSE;
            colorBlending.logicOp = VK_LOGIC_OP_COPY;
            colorBlending.attachmentCount = 1;
            colorBlending.pAttachments = &colorBlendAttachment;
            colorBlending.blendConstants[0] = 0.0f;
            colorBlending.blendConstants[1] = 0.0f;
            colorBlending.blendConstants[2] = 0.0f;
            colorBlending.blendConstants[3] = 0.0f;

            VkPipelineRasterizationStateCreateInfo rasterizer = {};
            rasterizer.sType = VK_STRUCTURE_TYPE_PIPELINE_RASTERIZATION_STATE_CREATE_INFO;
            rasterizer.depthClampEnable = VK_FALSE;
            rasterizer.rasterizerDiscardEnable = VK_FALSE;
            rasterizer.polygonMode = VK_POLYGON_MODE_FILL;
            rasterizer.lineWidth = 1.0f;
            rasterizer.cullMode = VK_CULL_MODE_BACK_BIT;
            rasterizer.frontFace = VK_FRONT_FACE_CLOCKWISE;
            rasterizer.depthBiasEnable = VK_FALSE;

            VkPipelineMultisampleStateCreateInfo multisampling = {};
            multisampling.sType = VK_STRUCTURE_TYPE_PIPELINE_MULTISAMPLE_STATE_CREATE_INFO;
            multisampling.sampleShadingEnable = VK_FALSE;
            multisampling.rasterizationSamples = VK_SAMPLE_COUNT_1_BIT;

            VkGraphicsPipelineCreateInfo pipelineCreateInfo = {};
            pipelineCreateInfo.sType = VK_STRUCTURE_TYPE_GRAPHICS_PIPELINE_CREATE_INFO;
            pipelineCreateInfo.stageCount = static_cast<uint32_t>(shaderStages.size());
            pipelineCreateInfo.pStages = shaderStages.data();
            pipelineCreateInfo.pVertexInputState = &vertexInputInfo;
            pipelineCreateInfo.pInputAssemblyState = &inputAssembly;
            pipelineCreateInfo.pViewportState = &viewportState;
            pipelineCreateInfo.pRasterizationState = &rasterizer;
            pipelineCreateInfo.pMultisampleState = &multisampling;
            pipelineCreateInfo.pColorBlendState = &colorBlending;
            pipelineCreateInfo.layout = builder->layoutRef->GetLayout();
            pipelineCreateInfo.renderPass = nullptr; // TODO: supply render pass
            pipelineCreateInfo.subpass = 0;
            pipelineCreateInfo.basePipelineHandle = nullptr;

            vkCreateGraphicsPipelines(D::context->GetDevice(), D::context->GetPipelineCache(), 1,
                &pipelineCreateInfo, nullptr, reinterpret_cast<VkPipeline*>(&_Pipeline));

            delete builder;
        }
    }

    void Pipeline::AttachProgram(const Program& program) noexcept {
        if (_Pipeline & 1) {
            reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1)->programRef = std::addressof(program);
        }
    }

    void Pipeline::AttachLayout(const PipelineLayout& layout) noexcept {
        if (_Pipeline & 1) {
            reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1)->layoutRef = std::addressof(layout);
        }
    }

    void Pipeline::VertexBuffer(GLuint bindingIndex, Buffer& buffer) noexcept {}
    void Pipeline::VertexBuffers(GLuint first, GLsizei count, const Buffer* buffers) noexcept {}

    void Pipeline::AddVertexBinding(GLuint index, GLsizei stride, GLboolean instanceFeed) noexcept {
        if (_Pipeline & 1) {
            auto& binding = reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1)->AppendBinding(index);
            binding.stride = static_cast<uint32_t>(stride);
            binding.inputRate = instanceFeed ? VK_VERTEX_INPUT_RATE_INSTANCE : VK_VERTEX_INPUT_RATE_VERTEX;
        }
    }

    void Pipeline::AddAttribFormat(GLuint index, GLuint binding, GLint size, GLenum type, GLboolean normalized,
            GLuint offset) noexcept {
        if (_Pipeline & 1) {
            auto& attr = reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1)->AppendAttribute(index);
            attr.format = GetFormat(size, type, normalized != 0);
            attr.offset = static_cast<uint32_t>(offset);
            attr.binding = static_cast<uint32_t>(binding);
        }
    }

    void Pipeline::AddAttribIFormat(GLuint index, GLuint binding, GLint size, GLenum type, GLuint offset) noexcept {
        if (_Pipeline & 1) {
            auto& attr = reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1)->AppendAttribute(index);
            attr.format = GetFormatI(size, type);
            attr.offset = static_cast<uint32_t>(offset);
            attr.binding = static_cast<uint32_t>(binding);
        }
    }

    void Pipeline::AddAttribLFormat(GLuint index, GLuint binding, GLint size, GLenum type, GLuint offset) noexcept {
        if (_Pipeline & 1) {
            auto& attr = reinterpret_cast<GraphicsPipelineBuilder*>(_Pipeline - 1)->AppendAttribute(index);
            attr.format = GetFormatF(size, type);
            attr.offset = static_cast<uint32_t>(offset);
            attr.binding = static_cast<uint32_t>(binding);
        }
    }

    void Pipeline::BindingDivisor(GLuint bindingIndex, GLuint divisor) noexcept {}
}

