namespace tilegen
{
namespace alpha
{
void CalculatorLinear::updateAlphasAux(const Weights& weights)
{
    int remainingAlpha = 255;
    double sumWeights = std::accumulate(weights.cbegin(), weights.cend(), 0.0);

    // Handle edge case where total weight is negligible
    if (sumWeights <= std::numeric_limits<double>::epsilon() * 255 * 4)
    {
        return;
    }

    // Initial allocation proportional to weights (with floor rounding)
    for (size_t idx = 0; idx < weights.size(); ++idx)
    {
        int assignedAlpha = static_cast<int>((255.0 * weights[idx]) / sumWeights);
        remainingAlpha -= assignedAlpha;
        getAlpha(idx) = static_cast<sf::Uint8>(assignedAlpha);
    }

    // If all alpha has been distributed, we're done
    if (remainingAlpha == 0)
        return;

    // Determine how many corners currently have positive alpha values
    size_t activeCorners = 0;
    for (const auto& alphaVal : getAlphas())
    {
        if (alphaVal > 0)
            ++activeCorners;
    }

    assert(activeCorners > 0);

    // Distribute leftover alpha points evenly among active corners
    int quotient = remainingAlpha / static_cast<int>(activeCorners);
    int remainder = remainingAlpha % static_cast<int>(activeCorners);

    assert(quotient >= 0);

    int cornersWithExtra = 0;
    for (size_t i = 0; i < getAlphas().size(); ++i)
    {
        auto& currentAlpha = getAlpha(i);
        if (currentAlpha == 0)
            continue;

        currentAlpha += static_cast<sf::Uint8>(quotient);
        remainingAlpha -= quotient;

        // Distribute the remainder one by one to first 'remainder' corners
        if (cornersWithExtra < remainder)
        {
            currentAlpha++;
            remainingAlpha--;
            cornersWithExtra++;
        }
    }

    assert(remainingAlpha == 0);
}
