int32 UK2Node_CommutativeAssociativeBinaryOperator::GetMaxInputPinsNum()
{
	// Compute max number of input pins as ASCII range from 'A' to 'Z'
	return static_cast<int32>('Z' - 'A');
}

FString UK2Node_CommutativeAssociativeBinaryOperator::GetNameForPin(int32 Index)
{
	check(Index < GetMaxInputPinsNum());
	FString Result;
	Result.AppendChar(static_cast<TCHAR>('A' + Index));
	return Result;
}

UK2Node_CommutativeAssociativeBinaryOperator::UK2Node_CommutativeAssociativeBinaryOperator(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	ExtraInputsCount = 0;
}

UEdGraphPin* UK2Node_CommutativeAssociativeBinaryOperator::FindOutputPin() const
{
	for (auto PinIt = Pins.CreateConstIterator(); PinIt; ++PinIt)
	{
		if ((*PinIt)->Direction == EEdGraphPinDirection::EGPD_Output)
		{
			return *PinIt;
		}
	}
	return nullptr;
}

UEdGraphPin* UK2Node_CommutativeAssociativeBinaryOperator::FindSelfPinReference() const
{
	const UEdGraphSchema_K2* K2Schema = GetDefault<UEdGraphSchema_K2>();
	for (auto PinIt = Pins.CreateConstIterator(); PinIt; ++PinIt)
	{
		if ((*PinIt)->PinName == K2Schema->PN_Self)
		{
			return *PinIt;
		}
	}
	return nullptr;
}

bool UK2Node_CommutativeAssociativeBinaryOperator::CanAddAdditionalInput() const
{
	return (ExtraInputsCount + FixedInputCount) < GetMaxInputPinsNum();
}

bool UK2Node_CommutativeAssociativeBinaryOperator::CanRemoveAdditionalInput(const UEdGraphPin* TargetPin) const
{
	return (
		TargetPin &&
		ExtraInputsCount > 0 &&
		Pins.Contains(const_cast<UEdGraphPin*>(TargetPin)) &&
		TargetPin->Direction == EEdGraphPinDirection::EGPD_Input
	);
}

UEdGraphPin* UK2Node_CommutativeAssociativeBinaryOperator::GetInputPinByLogicalIndex(int32 LogicalIndex)
{
	const UEdGraphPin* OutputRef = FindOutputPin();
	const UEdGraphPin* SelfRef = FindSelfPinReference();
	int32 CurrentCounter = 0;

	for (auto PinIt = Pins.CreateIterator(); PinIt; ++PinIt)
	{
		UEdGraphPin* CurrentPin = *PinIt;
		if ((CurrentPin != OutputRef) && (CurrentPin != SelfRef))
		{
			if (CurrentCounter == LogicalIndex)
			{
				return CurrentPin;
			}
			++CurrentCounter;
		}
	}
	return nullptr;
}

FEdGraphPinType UK2Node_CommutativeAssociativeBinaryOperator::DeterminePinType() const
{
	for (auto PinIt = Pins.CreateConstIterator(); PinIt; ++PinIt)
	{
		if (*PinIt != FindSelfPinReference())
		{
			return (*PinIt)->PinType;
		}
	}
	return FEdGraphPinType{};
}

void UK2Node_CommutativeAssociativeBinaryOperator::AllocateDefaultPinsInternal()
{
	Super::AllocateDefaultPins();

	const UFunction* TargetFunction = GetTargetFunction();
	if (TargetFunction)
	{
		check(TargetFunction->HasAnyFunctionFlags(FUNC_BlueprintPure));

#if DO_CHECK
		ensure(FindOutputPin());
		ensure((FindSelfPinReference() ? 4 : 3) == Pins.Num());

		{
			const FEdGraphPinType InputType = DeterminePinType();
			int32 ActualInputCount = 0;

			for (auto PinIt = Pins.CreateConstIterator(); PinIt; ++PinIt)
			{
				const UEdGraphPin* Pin = *PinIt;
				if (Pin != FindSelfPinReference())
				{
					ensure(InputType == Pin->PinType);
					if (Pin->Direction == EEdGraphPinDirection::EGPD_Input)
					{
						++ActualInputCount;
					}
				}
			}
			ensure(FixedInputCount == ActualInputCount);
		}
#endif // DO_CHECK

		for (int32 i = 0; i < ExtraInputsCount; ++i)
		{
			AppendInputPin(i);
		}
	}
	else
	{
		const UClass* OwnerClass = FunctionReference.GetMemberParentClass(GetBlueprintClassFromNode());
		Message_Error(FString::Printf(
			*LOCTEXT("NoFunction_Error", "CommutativeAssociativeBinaryOperator has no function: '%s' class: '%s'").ToString(),
			*FunctionReference.GetMemberName().ToString(),
			(OwnerClass ? *OwnerClass->GetName() : TEXT("None"))
		));
	}
}

void UK2Node_CommutativeAssociativeBinaryOperator::AppendInputPin(int32 SlotIndex)
{
	const FEdGraphPinType Type = DeterminePinType();
	CreatePin(
		EGPD_Input,
		Type.PinCategory,
		Type.PinSubCategory,
		Type.PinSubCategoryObject.Get(),
		Type.bIsArray,
		Type.bIsReference,
		*GetNameForPin(SlotIndex + FixedInputCount)
	);
}

void UK2Node_CommutativeAssociativeBinaryOperator::AddInputPin()
{
	if (CanAddAdditionalInput())
	{
		FScopedTransaction Transaction(LOCTEXT("AddPinTx", "AddPin"));
		Modify();
		AppendInputPin(ExtraInputsCount);
		++ExtraInputsCount;

		FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(GetBlueprint());
	}
}

void UK2Node_CommutativeAssociativeBinaryOperator::DeleteInputPin(UEdGraphPin* PinToRemove)
{
	if (CanRemoveAdditionalInput(PinToRemove))
	{
		FScopedTransaction Transaction(LOCTEXT("RemovePinTx", "RemovePin"));
		Modify();

		if (RemovePin(PinToRemove))
		{
			--ExtraInputsCount;

			int32 NameCounter = 0;
			const UEdGraphPin* OutputRef = FindOutputPin();
			const UEdGraphPin* SelfRef = FindSelfPinReference();

			for (auto PinIt = Pins.CreateIterator(); PinIt; ++PinIt)
			{
				UEdGraphPin* LocalPin = *PinIt;
				if (LocalPin && (LocalPin != OutputRef) && (LocalPin != SelfRef))
				{
					const FString ExpectedName = GetNameForPin(NameCounter);
					if (ExpectedName != LocalPin->PinName)
					{
						LocalPin->Modify();
						LocalPin->PinName = ExpectedName;
					}
					++NameCounter;
				}
			}

			FBlueprintEditorUtils::MarkBlueprintAsStructurallyModified(GetBlueprint());
		}
	}
}

void UK2Node_CommutativeAssociativeBinaryOperator::GetContextMenuActions(const FGraphNodeContextMenuBuilder& Context) const
{
	Super::GetContextMenuActions(Context);

	if (!Context.bIsDebugging)
	{
		static FName OperatorNodeSection = FName("CommutativeAssociativeBinaryOperatorNode");
		FText OperatorNodeLabel = LOCTEXT("CommutativeAssociativeBinaryOperatorNode", "Operator Node");

		if (Context.Pin)
		{
			if (CanRemoveAdditionalInput(Context.Pin))
			{
				Context.MenuBuilder->BeginSection(OperatorNodeSection, OperatorNodeLabel);
				Context.MenuBuilder->AddMenuEntry(
					LOCTEXT("RemovePin", "Remove pin"),
					LOCTEXT("RemovePinTooltip", "Remove this input pin"),
					FSlateIcon(),
					FUIAction(
						FExecuteAction::CreateUObject(this, &UK2Node_CommutativeAssociativeBinaryOperator::DeleteInputPin, const_cast<UEdGraphPin*>(Context.Pin))
					)
				);
				Context.MenuBuilder->EndSection();
			}
		}
		else if (CanAddAdditionalInput())
		{
			Context.MenuBuilder->BeginSection(OperatorNodeSection, OperatorNodeLabel);
			Context.MenuBuilder->AddMenuEntry(
				LOCTEXT("AddPin", "Add pin"),
				LOCTEXT("AddPinTooltip", "Add another input pin"),
				FSlateIcon(),
				FUIAction(
					FExecuteAction::CreateUObject(this, &UK2Node_CommutativeAssociativeBinaryOperator::AddInputPin)
				)
			);
			Context.MenuBuilder->EndSection();
		}
	}
}

void UK2Node_CommutativeAssociativeBinaryOperator::ExpandNode(FKismetCompilerContext& CompilerContext, UEdGraph* SourceGraph)
{
	Super::ExpandNode(CompilerContext, SourceGraph);

	if (ExtraInputsCount > 0)
	{
		const UEdGraphSchema_K2* Schema = CompilerContext.GetSchema();
		UEdGraphPin* PreviousOutput = nullptr;

		const UFunction* const TargetFunc = GetTargetFunction();
		const UEdGraphPin* OriginalOutput = FindOutputPin();
		const UEdGraphPin* OriginalSelf = FindSelfPinReference();
		UEdGraphPin* FirstInput = GetInputPinByLogicalIndex(0);
		check(FirstInput);

		for (auto PinIt = Pins.CreateIterator(); PinIt; ++PinIt)
		{
			UEdGraphPin* CurrentPin = *PinIt;
			if ((CurrentPin == FirstInput) || (CurrentPin == OriginalOutput) || (CurrentPin == OriginalSelf))
			{
				continue;
			}

			UK2Node_CommutativeAssociativeBinaryOperator* NewNode = SourceGraph->CreateBlankNode<UK2Node_CommutativeAssociativeBinaryOperator>();
			NewNode->SetFromFunction(TargetFunc);
			NewNode->AllocateDefaultPinsInternal();
			CompilerContext.MessageLog.NotifyIntermediateObjectCreation(NewNode, this);

			UEdGraphPin* NewInputA = NewNode->GetInputPinByLogicalIndex(0);
			check(NewInputA);

			if (PreviousOutput)
			{
				Schema->TryCreateConnection(PreviousOutput, NewInputA);
			}
			else
			{
				CompilerContext.MovePinLinksToIntermediate(*FirstInput, *NewInputA);
			}

			UEdGraphPin* NewInputB = NewNode->GetInputPinByLogicalIndex(1);
			check(NewInputB);
			CompilerContext.MovePinLinksToIntermediate(*CurrentPin, *NewInputB);

			PreviousOutput = NewNode->FindOutputPin();
			check(PreviousOutput);
		}

		UEdGraphPin* FinalOutput = FindOutputPin();
		check(FinalOutput);
		CompilerContext.MovePinLinksToIntermediate(*FinalOutput, *PreviousOutput);
		BreakAllNodeLinks();
	}
}

