auto ConverterFactory::make_converter(ConverterFactory::ConversionType type,
                                      const QString &inputFile,
                                      const QString &outputFile,
                                      const QString &fieldSeparator,
                                      const QString &stringSeparator,
                                      const QString &tsVersion)
    -> std::unique_ptr<Converter>
{
    switch (type) {
        case ConversionType::Ts2Csv: {
            InOutParameter parserParams{ inputFile, outputFile, tsVersion,
                                        CsvProperty{ stringSeparator, fieldSeparator } };
            InOutParameter builderParams{ inputFile, outputFile, tsVersion,
                                         CsvProperty{ fieldSeparator, stringSeparator } };
            return std::make_unique<Converter>(
                std::make_unique<TsParser>(parserParams),
                std::make_unique<CsvBuilder>(builderParams));
        }
        case ConversionType::Csv2Ts: {
            InOutParameter parserParams{ inputFile, outputFile, tsVersion,
                                        CsvProperty{ stringSeparator, fieldSeparator } };
            InOutParameter builderParams{ inputFile, outputFile, tsVersion,
                                         CsvProperty{ fieldSeparator, stringSeparator } };
            return std::make_unique<Converter>(
                std::make_unique<CsvParser>(parserParams),
                std::make_unique<TsBuilder>(builderParams));
        }
        case ConversionType::Ts2Xlsx: {
            InOutParameter parserParams{ inputFile, outputFile, tsVersion,
                                        CsvProperty{ stringSeparator, fieldSeparator } };
            InOutParameter builderParams{ inputFile, outputFile, tsVersion,
                                         CsvProperty{ fieldSeparator, stringSeparator } };
            return std::make_unique<Converter>(
                std::make_unique<TsParser>(parserParams),
                std::make_unique<XlsxBuilder>(builderParams));
        }
        case ConversionType::Xlsx2Ts: {
            InOutParameter parserParams{ inputFile, outputFile, tsVersion,
                                        CsvProperty{ stringSeparator, fieldSeparator } };
            InOutParameter builderParams{ inputFile, outputFile, tsVersion,
                                         CsvProperty{ fieldSeparator, stringSeparator } };
            return std::make_unique<Converter>(
                std::make_unique<XlsxParser>(parserParams),
                std::make_unique<TsBuilder>(builderParams));
        }
        default:
            break;
    }
    assert(false);
    return {};
}

#include "Albero.hpp"
#include "Nodo.hpp"
#include <iostream>

int main() {
    // Build the same binary tree:
    //         0
    //     1       2
    //   3   4

    // Create leaf nodes first
    auto* leftLeaf = Albero::costruisci(Nodo::costruisci(3));
    auto* rightLeaf = Albero::costruisci(Nodo::costruisci(4));

    // Build node 1 with children 3 and 4
    auto* subtree1 = Albero::unisci(
        Albero::costruisci(Nodo::costruisci(1)),
        leftLeaf,
        rightLeaf
    );

    // Build node 2 (leaf)
    auto* subtree2 = Albero::costruisci(Nodo::costruisci(2));

    // Build root node 0 with children 1 and 2
    auto* fullTree = Albero::uniji(
        Albero::costruisci(Nodo::costruisci(0)),
        subtree1,
        subtree2
    );

    // Print root value: 0
    std::cout << Nodo::valore(Albero::radice(fullTree)) << '\n';

    // Print left child of root: 1
    std::cout << Nodo::valore(Albero::radice(Albero::sx(fullTree))) << '\n';

    // Print right child of root: 2
    std::cout << Nodo::valore(Albero::radice(Albero::dx(fullTree))) << '\n';

    // Print traversal string: "0 1 3 4 2"
    std::string traversal;
    Albero::visita_in_ordine(fullTree, [&](const Nodo& n) {
        if (!traversal.empty()) traversal += ' ';
        traversal += std::to_string(Nodo::valore(n));
    });
    std::cout << traversal << '\n';

    return 0;
}

