#define INDEX_ACCESS(width, row, col) (((row) * (width)) + (col))

// ===================== GPU_FIXED_POINT_STUFF_BEGIN ===========================
__global__ void propagateValues(int *inputVec, int *outputVec,
                                std::uint64_t vecSize, int *edgeList,
                                std::uint64_t edgeCount,
                                bool isSecondPass) {
  std::uint64_t col = hipThreadIdx_x + hipBlockIdx_x * hipBlockDim_x;
  std::uint64_t edgeIdx = hipThreadIdx_y + hipBlockIdx_y * hipBlockDim_y;
  if (edgeIdx >= edgeCount || col >= vecSize)
    return;

  std::uint64_t srcIdxPos = INDEX_ACCESS(edgeCount, 0, edgeIdx);
  std::uint64_t dstIdxPos = INDEX_ACCESS(edgeCount, 1, edgeIdx);

  int srcNode = edgeList[srcIdxPos];
  int dstNode = edgeList[dstIdxPos];

  std::uint64_t srcBitPos = INDEX_ACCESS(vecSize, srcNode, col);
  std::uint64_t dstBitPos = INDEX_ACCESS(vecSize, dstNode, col);

  if (isSecondPass)
    outputVec[dstBitPos] |= inputVec[srcBitPos];
  else
    outputVec[dstBitPos] = inputVec[srcBitPos];
}

__global__ void updateTransfer(int *inData, int *outData, int *genData,
                               int *killData, std::uint64_t vecLen,
                               std::uint64_t numInstrs) {
  std::uint64_t instrIdx = hipThreadIdx_y + hipBlockIdx_y * hipBlockDim_y;
  std::uint64_t bitIdx = hipThreadIdx_x + hipBlockIdx_x * hipBlockDim_x;

  if (instrIdx >= numInstrs || bitIdx >= vecLen)
    return;

  std::uint64_t pos = INDEX_ACCESS(vecLen, instrIdx, bitIdx);
  bool gen = genData[pos];
  bool kill = killData[pos];
  bool outVal = outData[pos];

  inData[pos] = gen | (outVal & !kill);
}
// ======================= GPU_FIXED_POINT_STUFF_END ===========================

// ======================== LIVENESS_GEN_KILL_BEGIN ============================
static bool shouldTrack(const llvm::Value *val) {
  if (!val->hasName())
    return false;
  if (llvm::isa<llvm::Constant>(val))
    return false;
  if (llvm::isa<llvm::BasicBlock>(val))
    return false;
  return true;
}

static std::vector<Value *> collectGen(Instruction *inst) {
  std::vector<Value *> gens;
  if (auto br = dyn_cast<BranchInst>(inst)) {
    if (br->isConditional())
      gens.push_back(br->getCondition());
    return gens;
  }

  for (auto op : inst->operand_values()) {
    if (shouldTrack(op))
      gens.push_back(op);
  }
  return gens;
}

static std::vector<Value *> collectKill(Instruction *inst) {
  std::vector<Value *> kills;
  if (isa<BranchInst>(inst) || isa<StoreInst>(inst) || isa<ReturnInst>(inst))
    return kills;

  if (Value *v = dyn_cast<Value>(inst)) {
    if (shouldTrack(v))
      kills.push_back(v);
  }
  return kills;
}
// ========================= LIVENESS_GEN_KILL_END =============================

class LiveVariableSolver {
private:
  std::map<Instruction *, BitVector> genMap, killMap;
  std::map<Instruction *, BitVector> inMap, outMap;
  int *genArr, *killArr, *inArr, *outArr;
  BitVectorMapping mapping;
  std::uint64_t numInstrs, vecLength;
  std::vector<Instruction *> idToInstr;
  std::map<Instruction *, int> instrToId;
  int *predArr, *succArr;
  std::uint64_t predCount, succCount;
  std::uint64_t maxIterations;

public:
  LiveVariableSolver(BitVectorMapping map) : mapping(map) {
    numInstrs = 0;
    vecLength = 0;
  }

  std::vector<llvm::Instruction *> getSuccessors(llvm::Instruction *inst) {
    std::vector<llvm::Instruction *> succs;
    llvm::BasicBlock *bb = inst->getParent();
    if (&bb->back() == inst) {
      for (llvm::BasicBlock *nextBB : successors(bb)) {
        succs.push_back(&nextBB->front());
      }
    } else {
      succs.push_back(inst->getNextNonDebugInstruction());
    }
    return succs;
  }

  void setupEdgeArrays(Function &func) {
    std::vector<std::pair<int, int>> edges1, edges2;
    for (inst_iterator I = inst_begin(func), E = inst_end(func); I != E; ++I) {
      auto succs = getSuccessors(&*I);
      int curId = instrToId[&*I];
      assert(succs.size() <= 2 && "Only up to two successors supported");
      if (succs.empty()) continue;

      edges1.emplace_back(curId, instrToId[succs[0]]);
      if (succs.size() == 2)
        edges2.emplace_back(curId, instrToId[succs[1]]);
    }

    predCount = edges1.size();
    succCount = edges2.size();

    hipMallocManaged(&predArr, 2 * predCount * sizeof(int));
    for (std::uint64_t j = 0; j < predCount; ++j) {
      int idx0 = INDEX_ACCESS(predCount, 0, j);
      int idx1 = INDEX_ACCESS(predCount, 1, j);
      predArr[idx0] = edges1[j].first;
      predArr[idx1] = edges1[j].second;
    }

    hipMallocManaged(&succArr, 2 * succCount * sizeof(int));
    for (std::uint64_t j = 0; j < succCount; ++j) {
      int idx0 = INDEX_ACCESS(succCount, 0, j);
      int idx1 = INDEX_ACCESS(succCount, 1, j);
      succArr[idx0] = edges2[j].first;
      succArr[idx1] = edges2[j].second;
    }
  }

  void allocateAndInitializeVectors(Function &func) {
    hipMallocManaged(&genArr, numInstrs * vecLength * sizeof(int));
    hipMallocManaged(&killArr, numInstrs * vecLength * sizeof(int));
    hipMallocManaged(&inArr, numInstrs * vecLength * sizeof(int));
    hipMallocManaged(&outArr, numInstrs * vecLength * sizeof(int));

    int idx = 0;
    for (inst_iterator I = inst_begin(func), E = inst_end(func); I != E; ++I) {
      for (int b = 0; b < vecLength; ++b) {
        int pos = INDEX_ACCESS(vecLength, idx, b);
        genArr[pos] = genMap[&*I].test(b) ? 1 : 0;
        killArr[pos] = killMap[&*I].test(b) ? 1 : 0;
        inArr[pos] = inMap[&*I].test(b) ? 1 : 0;
        outArr[pos] = outMap[&*I].test(b) ? 1 : 0;
      }
      ++idx;
    }
  }

  void dumpEdgeInfo() {
    std::cout << "Predecessor list:\n";
    for (int i = 0; i < predCount; ++i) {
      std::cout << predArr[INDEX_ACCESS(predCount, 0, i)] << ' ';
    }
    std::cout << "\n";
    for (int i = 0; i < predCount; ++i) {
      std::cout << predArr[INDEX_ACCESS(predCount, 1, i)] << ' ';
    }
    std::cout << "\n";

    std::cout << "Successor list:\n";
    for (int i = 0; i < succCount; ++i) {
      std::cout << succArr[INDEX_ACCESS(succCount, 0, i)] << ' ';
    }
    std::cout << "\n";
    for (int i = 0; i < succCount; ++i) {
      std::cout << succArr[INDEX_ACCESS(succCount, 1, i)] << ' ';
    }
    std::cout << "\n";
  }

  void dumpResults() {
    std::cout << "In vectors:\n";
    for (int i = 0; i < numInstrs; ++i) {
      for (int j = 0; j < vecLength; ++j) {
        std::cout << inArr[INDEX_ACCESS(vecLength, i, j)] << ' ';
      }
      std::cout << '\n';
    }

    std::cout << "Out vectors:\n";
    for (int i = 0; i < numInstrs; ++i) {
      for (int j = 0; j < vecLength; ++j) {
        std::cout << outArr[INDEX_ACCESS(vecLength, i, j)] << ' ';
      }
      std::cout << '\n';
    }

    std::cout << "Gen vectors:\n";
    for (int i = 0; i < numInstrs; ++i) {
      for (int j = 0; j < vecLength; ++j) {
        std::cout << genArr[INDEX_ACCESS(vecLength, i, j)] << ' ';
      }
      std::cout << '\n';
    }

    std::cout << "Kill vectors:\n";
    for (int i = 0; i < numInstrs; ++i) {
      for (int j = 0; j < vecLength; ++j) {
        std::cout << killArr[INDEX_ACCESS(vecLength, i, j)] << ' ';
      }
      std::cout << '\n';
    }
  }

  void assignIndices(Module *mod) {
    for (auto gi = mod->global_begin(), ge = mod->global_end(); gi != ge; ++gi) {
      Value *v = &*gi;
      if (shouldTrack(v))
        mapping.assignIndexToValue(v);
    }
  }

  void processFunction(Function &func) {
    for (inst_iterator it = inst_begin(func), end = inst_end(func); it != end; ++it) {
      Instruction *inst = &*it;
      if (Value *v = dyn_cast<Value>(inst)) {
        if (mapping.shouldMap(v) && !mapping.getBitVectorIndexForValue(v))
          mapping.assignIndexToValue(v);
      }
      for (auto op : inst->operand_values()) {
        if (mapping.shouldMap(op) && !mapping.getBitVectorIndexForValue(op))
          mapping.assignIndexToValue(op);
      }
    }
  }

  void solveOnGPU() {
    for (std::uint64_t iter = 0; iter < maxIterations; ++iter) {
      dim3 threadsPerBlock(32, 32);
      int gridX = (vecLength + threadsPerBlock.x - 1) / threadsPerBlock.x;
      int gridY = (numInstrs + threadsPerBlock.y - 1) / threadsPerBlock.y;

      hipLaunchKernelGGL(updateTransfer,
                         dim3(gridX, gridY),
                         threadsPerBlock,
                         0, 0,
                         inArr, outArr, genArr, killArr,
                         vecLength, numInstrs);

      gridY = (predCount + threadsPerBlock.y - 1) / threadsPerBlock.y;
      hipLaunchKernelGGL(propagateValues,
                         dim3(gridX, gridY),
                         threadsPerBlock,
                         0, 0,
                         inArr, outArr, vecLength, predArr, predCount,
                         /*isSecond=*/false);

      gridY = (succCount + threadsPerBlock.y - 1) / threadsPerBlock.y;
      hipLaunchKernelGGL(propagateValues,
                         dim3(gridX, gridY),
                         threadsPerBlock,
                         0, 0,
                         inArr, outArr, vecLength, succArr, succCount,
                         /*isSecond=*/true);
    }
    hipDeviceSynchronize();
  }

  void execute(Function &func) {
    assignIndices(func.getParent());
    processFunction(func);
    mapping.printMapping();
    std::cout << mapping.getAddressToIndexMap().size() << '\n';

    int idCounter = 0;
    for (inst_iterator it = inst_begin(func), end = inst_end(func); it != end; ++it) {
      Instruction *inst = &*it;
      idToInstr.push_back(inst);
      instrToId[inst] = idCounter++;
      genMap[inst] = mapping.createBitVectorWithTrue(collectGen(inst));
      if (idCounter == 1)
        vecLength = genMap[inst].size();
      killMap[inst] = mapping.createBitVectorWithTrue(collectKill(inst));
      inMap[inst] = mapping.createBitVectorWithAllBitsZero();
      outMap[inst] = mapping.createBitVectorWithAllBitsZero();
    }

    numInstrs = idCounter;
    allocateAndInitializeVectors(func);
    setupEdgeArrays(func);

    maxIterations = numInstrs * numInstrs;

    auto startTime = std::chrono::steady_clock::now();
    solveOnGPU();
    auto endTime = std::chrono::steady_clock::now();
    auto elapsed = std::chrono::duration<float>(endTime - startTime);
    std::cout << "Computation took " << std::setprecision(10) << elapsed.count()
              << " seconds\n";
    std::cout.flush();

    std::cout << "Final dataflow results:\n";
    dumpResults();

    hipFree(genArr);
    hipFree(killArr);
    hipFree(inArr);
    hipFree(outArr);
    hipFree(predArr);
    hipFree(succArr);
    mapping.reset();
  }
};

int main(int argc, char *argv[]) {
  if (argc != 2) {
    std::cerr << "Usage: " << argv[0] << " <input.ll>\n";
    return 1;
  }

  LLVMContext context;
  SMDiagnostic err;
  std::unique_ptr<Module> module = parseAssemblyFile(argv[1], err, context);
  if (verifyModule(*module)) {
    std::cerr << "Error: Invalid LLVM IR\n";
    return 1;
  }

  for (auto funcIt = module->begin(); funcIt != module->end(); ++funcIt) {
    BitVectorMapping bvMap;
    LiveVariableSolver solver(bvMap);
    solver.execute(*funcIt);
  }

  return 0;
}

