// Simplified zip iterator implementation for demonstration
template<typename... Iters>
class zip_iterator {
private:
    std::tuple<Iters...> iterators;

public:
    // Constructor
    zip_iterator(Iters... its) : iterators(its...) {}

    // Copy constructor
    zip_iterator(const zip_iterator& other) : iterators(other.iterators) {}

    // Assignment operator
    zip_iterator& operator=(const zip_iterator& other) {
        if (this != &other) {
            iterators = other.iterators;
        }
        return *this;
    }

    // Equality comparison
    bool operator==(const zip_iterator& other) const {
        return iterators == other.iterators;
    }

    bool operator!=(const zip_iterator& other) const {
        return !(*this == other);
    }

    // Dereference operator - returns tuple of dereferenced values
    auto operator*() const -> decltype(std::apply([](auto&&... its) { 
        return std::make_tuple(*its...); 
    }, iterators)) {
        return std::apply([](auto&&... its) { 
            return std::make_tuple(*its...); 
        }, iterators);
    }

    // Pre-increment
    zip_iterator& operator++() {
        std::apply([](auto&&... its) { 
            ((++its), ...); 
        }, iterators);
        return *this;
    }

    // Post-increment
    zip_iterator operator++(int) {
        zip_iterator temp(*this);
        ++(*this);
        return temp;
    }

    // Swap function
    friend void swap(zip_iterator& first, zip_iterator& second) {
        using std::swap;
        swap(first.iterators, second.iterators);
    }
};

// Helper function to create zip_iterator
template<typename... Iters>
zip_iterator<Iters...> make_zip_iterator(Iters... its) {
    return zip_iterator<Iters...>(its...);
}

int main() {
    // Test basic functionality similar to the original test suite

    // Single vector test
    std::vector<int> v1 = {0, 1, 2};
    auto iter_a = make_zip_iterator(v1.begin());
    auto iter_b = make_zip_iterator(v1.begin());

    // Test equality
    if (iter_a == iter_b) {
        std::cout << "Equality test passed" << std::endl;
    }

    // Test increment
    ++iter_a;
    if (iter_a != iter_b) {
        std::cout << "Inequality after increment test passed" << std::endl;
    }

    // Test dereference
    auto val = *iter_a;
    int first_val = std::get<0>(val);
    if (first_val == 1) {
        std::cout << "Dereference test passed: " << first_val << std::endl;
    }

    // Multi-vector test
    std::vector<int> v2 = {0, 1, 2};
    std::vector<char> v3 = {'a', 'b', 'c'};
    auto iter_c = make_zip_iterator(v2.begin(), v3.begin());
    auto iter_d = make_zip_iterator(v2.begin(), v3.begin());

    if (iter_c == iter_d) {
        std::cout << "Multi-vector equality test passed" << std::endl;
    }

    // Test swap
    auto iter_e = make_zip_iterator(v2.begin(), v3.begin());
    auto iter_f = make_zip_iterator(v2.begin() + 1, v3.begin() + 1);

    auto val_e = *iter_e;
    auto val_f = *iter_f;

    int e_first = std::get<0>(val_e);
    char e_second = std::get<1>(val_e);
    int f_first = std::get<0>(val_f);
    char f_second = std::get<1>(val_f);

    std::swap(iter_e, iter_f);

    auto val_e_after = *iter_e;
    auto val_f_after = *iter_f;

    int e_first_after = std::get<0>(val_e_after);
    char e_second_after = std::get<1>(val_e_after);
    int f_first_after = std::get<0>(val_f_after);
    char f_second_after = std::get<1>(val_f_after);

    if (e_first_after == f_first && e_second_after == f_second &&
        f_first_after == e_first && f_second_after == e_second) {
        std::cout << "Swap test passed" << std::endl;
    }

    return 0;
}

