}

void DreamsControlPanel::ponder(const float deltaT)
{
    if (mpDoHelpEvent && mpDoHelpEvent->update())
    {
        mpDoHelpEvent = nullptr;
        return;
    }

    if (mpLineInput)
    {
        mpLineInput->update();
        return;
    }

    VW_FixRefreshBuffer();
    US_ControlPanel_Ponder();
}

void DreamsControlPanel::render()
{
    if (mpLineInput)
    {
        mpLineInput->draw();
        return;
    }

    VW_UpdateScreen();
}

void DreamsControlPanel::pumpEvent(const CEvent *evPtr)
{
    if (auto openLine = dynamic_cast<const OpenLineInput*>(evPtr))
    {
        mpLineInput.reset(new LineInput);
        mpLineInput->activate(openLine->x, openLine->y,
                              openLine->buf, openLine->def,
                              openLine->escok,
                              openLine->maxchars, openLine->maxwidth,
                              openLine->mN);
    }
    else if (auto helpEv = dynamic_cast<const DoHelp*>(evPtr))
    {
        auto* pHelper = new DoHelpImpl(helpEv->mText, helpEv->mLen);
        mpDoHelpEvent.reset(pHelper);
        pHelper->initialize();
    }
    else if (dynamic_cast<const CloseLineInput*>(evPtr))
    {
        mpLineInput = nullptr;
    }
    else if (auto saveEv = dynamic_cast<const SaveGameEvent*>(evPtr))
    {
        saveEv->save();
    }
}

// LineInput implementation
void LineInput::activate(int x, int y,
                         char *buffer, const char *defaultValue,
                         bool allowEscape,
                         int maxChars, int maxWidth,
                         int slotIndex)
{
    mMaxChars = maxChars;
    mMaxWidth = maxWidth;
    mX = x;
    mY = y;
    mSlot = slotIndex;
    mAllowEsc = allowEscape;
    VW_HideCursor();

    if (defaultValue)
        mContent = defaultValue;

    mBuffer = buffer;
    mCursorPos = static_cast<int>(mContent.size());
    mLastTick = SD_GetTimeCount();
}

void LineInput::update()
{
    if (mFinished)
        return;

    // Simulate input polling (original commented-out section replaced by simulated behavior)
    // Original: BE_ST_ShortSleep(); scan/ascii handling...
    // Here we simulate key press detection via gInput (as per original comment)

    std::string prevContent = mContent;

    // Handle navigation keys
    if (gInput.getPressedCommand(IC_LEFT)) {
        if (mCursorPos > 0) --mCursorPos;
        mNeedsRedraw = true;
    }
    else if (gInput.getPressedCommand(IC_RIGHT)) {
        if (mContent[mCursorPos]) ++mCursorPos;
        mNeedsRedraw = true;
    }
    else if (gInput.getPressedCommand(IC_HOME)) {
        mCursorPos = 0;
        mNeedsRedraw = true;
    }
    else if (gInput.getPressedCommand(IC_END)) {
        mCursorPos = static_cast<int>(mContent.size());
        mNeedsRedraw = true;
    }
    else if (gInput.getPressedCommand(IC_BACKSPACE)) {
        if (mCursorPos > 0) {
            mContent.erase(--mCursorPos, 1);
            mNeedsRedraw = true;
        }
    }
    else if (gInput.getPressedCommand(IC_DELETE)) {
        if (mContent[mCursorPos]) {
            mContent.erase(mCursorPos, 1);
            mNeedsRedraw = true;
        }
    }
    else if (gInput.getPressedCommand(IC_JUMP)) {
        // Auto-fill with timestamp
        time_t rawtime;
        struct tm * info = localtime(&rawtime);
        char timeBuf[64];
        strftime(timeBuf, sizeof(timeBuf), "%Y-%m-%d %H:%M:%S", info);
        mContent = timeBuf;
        mCursorPos = static_cast<int>(mContent.size());
        mNeedsRedraw = true;
        strcpy(mBuffer, mContent.c_str());
        mFinished = true;
        mSuccess = true;
    }
    else if (gInput.getPressedCommand(IC_BACK)) {
        mFinished = true;
        mSuccess = false;
    }
    else {
        char ch = gInput.getLatestChar();
        if (ch && isprint(ch)) {
            uint16_t w = 0, h = 0;
            USL_MeasureString(mContent.c_str(), nullptr, &w, &h);

            size_t currentLen = mContent.size();
            if ((mMaxChars == 0 || currentLen < mMaxChars) &&
                (mMaxWidth == 0 || w < mMaxWidth) &&
                currentLen < MaxString - 1)
            {
                mContent.insert(mCursorPos++, 1, ch);
                mNeedsRedraw = true;
            }
        }
    }

    // Redraw if needed
    if (mNeedsRedraw) {
        px = mX; py = mY;
        USL_DrawString(prevContent.c_str(), nullptr);
        px = mX; py = mY;
        USL_DrawString(mContent.c_str(), nullptr);
        mNeedsRedraw = false;
    }

    // Cursor blinking logic
    if (SD_GetTimeCount() - mLastTick > TickBase / 2) {
        mLastTick = SD_GetTimeCount();
        mCursorVisible = !mCursorVisible;
    }
}

void LineInput::draw()
{
    if (mCursorVisible)
        USL_XORICursor(mX, mY, mContent.c_str(), mCursorPos);
    VW_UpdateScreen();
}

