// Helper: Convert mode flags to platform-specific values
static uint _MapOpenFlags(uint uiModeFlags) {
    uint result = 0;
#ifdef _WIN32
    if (uiModeFlags & OF_READWRITE) result |= GENERIC_READ | GENERIC_WRITE;
    else if (uiModeFlags & OF_WRITE) result |= GENERIC_WRITE;
    else result |= GENERIC_READ;

    if (uiModeFlags & OF_CREATE) {
        result |= CREATE_NEW;
    } else {
        result |= OPEN_EXISTING;
    }
#else
    // POSIX open() flags mapping
    if (uiModeFlags & OF_READWRITE) result |= O_RDWR;
    else if (uiModeFlags & OF_WRITE) result |= O_WRONLY;
    else result |= O_RDONLY;

    if (uiModeFlags & OF_CREATE) result |= O_CREAT;
#endif
    return result;
}

// Helper: Platform-specific file opening
static void* _OpenFileHandle(lpctstr ptcFilename, uint uiModeFlags) {
#ifdef _WIN32
    DWORD dwDesiredAccess = 0;
    if (uiModeFlags & OF_READWRITE) dwDesiredAccess = GENERIC_READ | GENERIC_WRITE;
    else if (uiModeFlags & OF_WRITE) dwDesiredAccess = GENERIC_WRITE;
    else dwDesiredAccess = GENERIC_READ;

    DWORD dwShareMode = FILE_SHARE_READ | FILE_SHARE_WRITE;
    if (uiModeFlags & OF_SHARE_EXCLUSIVE) dwShareMode = 0;
    else if (uiModeFlags & OF_SHARE_DENY_WRITE) dwShareMode = FILE_SHARE_READ;
    else if (uiModeFlags & OF_SHARE_DENY_READ) dwShareMode = FILE_SHARE_WRITE;

    DWORD dwCreationDisposition = (uiModeFlags & OF_CREATE) ? OPEN_ALWAYS : OPEN_EXISTING;

    HANDLE h = CreateFileA(ptcFilename, dwDesiredAccess, dwShareMode, nullptr,
                           dwCreationDisposition, FILE_ATTRIBUTE_NORMAL, nullptr);
    return reinterpret_cast<void*>(h);
#else
    int flags = _MapOpenFlags(uiModeFlags);
    int fd = open(ptcFilename, flags, 0644);
    return reinterpret_cast<void*>(fd);
#endif
}

// Helper: Close file handle safely
static void _CloseFileHandle(void* hFile) {
#ifdef _WIN32
    CloseHandle(reinterpret_cast<HANDLE>(hFile));
#else
    close(reinterpret_cast<int>(reinterpret_cast<uintptr_t>(hFile)));
#endif
}

// Helper: Get current position
static long _GetFilePosition(void* hFile) {
#ifdef _WIN32
    LONG pos = SetFilePointer(reinterpret_cast<HANDLE>(hFile), 0, nullptr, FILE_CURRENT);
    return (pos == INVALID_SET_FILE_POINTER) ? -1 : pos;
#else
    off_t pos = lseek(reinterpret_cast<int>(reinterpret_cast<uintptr_t>(hFile)), 0, SEEK_CUR);
    return (pos == -1) ? -1 : static_cast<long>(pos);
#endif
}

// Helper: Seek within file
static long _SeekFile(void* hFile, long offset, int origin) {
#ifdef _WIN32
    return SetFilePointer(reinterpret_cast<HANDLE>(hFile), offset, nullptr, origin);
#else
    return lseek(reinterpret_cast<int>(reinterpret_cast<uintptr_t>(hFile)), offset, origin);
#endif
}

// Helper: Read data from file
static size_t _ReadFile(void* hFile, void* buffer, size_t size) {
#ifdef _WIN32
    DWORD bytesRead = 0;
    if (!ReadFile(reinterpret_cast<HANDLE>(hFile), buffer, static_cast<DWORD>(size), &bytesRead, nullptr))
        return 0;
    return bytesRead;
#else
    ssize_t res = read(reinterpret_cast<int>(reinterpret_cast<uintptr_t>(hFile)), buffer, size);
    return (res < 0) ? 0 : static_cast<size_t>(res);
#endif
}

// Helper: Write data to file
static bool _WriteFile(void* hFile, const void* buffer, size_t size) {
#ifdef _WIN32
    DWORD bytesWritten = 0;
    BOOL ok = WriteFile(reinterpret_cast<HANDLE>(hFile), buffer, static_cast<DWORD>(size), &bytesWritten, nullptr);
    return ok && (bytesWritten == size);
#else
    ssize_t written = write(reinterpret_cast<int>(reinterpret_cast<uintptr_t>(hFile)), buffer, size);
    return written == static_cast<ssize_t>(size);
#endif
}

