    if (_hFile != nullptr) {
        _CloseFileHandle(_hFile);
        _hFile = nullptr;
    }
}

// CSFile:: Error Logging.
int CSFile::GetLastError() {
#ifdef _WIN32
    return static_cast<int>(GetLastError());
#else
    return errno;
#endif
}

void CSFile::_NotifyIOError(lpctstr szMessage) const {
    ADDTOCALLSTACK("CSFile::_NotifyIOError");
    int errCode = GetLastError();
    std::string msg;

#ifdef _WIN32
    LPVOID lpMsgBuf = nullptr;
    FormatMessage(FORMAT_MESSAGE_ALLOCATE_BUFFER | FORMAT_MESSAGE_FROM_SYSTEM | FORMAT_MESSAGE_IGNORE_INSERTS,
                  nullptr, errCode, MAKELANGID(LANG_NEUTRAL, SUBLANG_DEFAULT),
                  reinterpret_cast<LPTSTR>(&lpMsgBuf), 0, nullptr);

    if (lpMsgBuf) {
        msg = static_cast<char*>(lpMsgBuf);
        LocalFree(lpMsgBuf);
    } else {
        msg = "No System Error";
    }
#else
    msg = strerror(errCode);
#endif

    g_Log.Event(LOGL_ERROR | LOGM_NOCONTEXT,
                "File I/O \"%s\" failed on file \"%s\" (%lX): %s\n",
                szMessage, _strFileName.GetPtr(), errCode, msg.c_str());
}

// CSFile:: File Management.
void CSFile::_Close() {
    ADDTOCALLSTACK("CSFile::_Close");
    if (_hFile == nullptr) return;

    _CloseFileHandle(_hFile);
    _hFile = nullptr;
}

void CSFile::Close() {
    ADDTOCALLSTACK("CSFile::Close");
    THREAD_UNIQUE_LOCK_SET;
    _Close();
}

bool CSFile::_Open(lpctstr ptcFilename, uint uiModeFlags) {
    ADDTOCALLSTACK("CSFile::_Open");

    if (!ptcFilename) {
        if (_hFile != nullptr) return true;
    } else {
        _Close(); // Ensure closed before re-opening
    }

    if (!ptcFilename) {
        ptcFilename = _strFileName.GetPtr();
    } else {
        _strFileName = ptcFilename;
    }

    if (_strFileName.IsEmpty()) return false;

    _uFlags = uiModeFlags;
    _hFile = _OpenFileHandle(ptcFilename, uiModeFlags);
    return (_hFile != nullptr);
}

bool CSFile::Open(lpctstr ptcFilename, uint uiModeFlags) {
    ADDTOCALLSTACK("CSFile::Open");
    THREAD_UNIQUE_LOCK_RETURN(_Open(ptcFilename, uiModeFlags));
}

bool CSFile::_IsFileOpen() const {
    return (_hFile != nullptr);
}

bool CSFile::IsFileOpen() const {
    THREAD_SHARED_LOCK_RETURN(_hFile != nullptr);
}

lpctstr CSFile::_GetFilePath() const {
    return _strFileName.GetPtr();
}

lpctstr CSFile::GetFilePath() const {
    THREAD_SHARED_LOCK_RETURN(_strFileName.GetPtr());
}

bool CSFile::_SetFilePath(lpctstr pszName) {
    ADDTOCALLSTACK("CSFile::_SetFilePath");
    if (!pszName) return false;

    if (_strFileName.CompareNoCase(pszName) == 0) return true;

    bool wasOpen = (_hFile != nullptr);
    if (wasOpen) _Close();

    _strFileName = pszName;

    if (wasOpen) {
        return _Open(); // reopen with previous flags
    }
    return true;
}

bool CSFile::SetFilePath(lpctstr pszName) {
    ADDTOCALLSTACK("CSFile::SetFilePath");
    THREAD_UNIQUE_LOCK_RETURN(_SetFilePath(pszName));
}

// CSFile:: Content management.
int CSFile::_GetLength() {
    ADDTOCALLSTACK("CSFile::_GetLength");
    bool fWasOpen = (_hFile != nullptr);
    if (!fWasOpen && !Open()) return 0;

    long curPos = _GetPosition();
    long endPos = _SeekToEnd();
    _Seek(curPos, SEEK_SET);

    if (!fWasOpen) {
        _Close();
    }

    return (endPos >= 0) ? endPos : 0;
}

int CSFile::GetLength() {
