CSString CSFile::GetMergedFileName(lpctstr pszBase, lpctstr pszName) { // static
    ADDTOCALLSTACK("CSFile::GetMergedFileName");
    char path[_MAX_PATH];
    size_t len = 0;

    if (pszBase && pszBase[0]) {
        len = Str_CopyLimitNull(path, pszBase, sizeof(path) - 1);
        if (len > 0 && path[len - 2] != '\\' && path[len - 2] != '/') {
#ifdef _WIN32
            strncat(path, "\\", sizeof(path) - len - 1);
#else
            strncat(path, "/", sizeof(path) - len - 1);
#endif
        }
    } else {
        path[0] = '\0';
    }

    if (pszName) {
        Str_ConcatLimitNull(path, pszName, sizeof(path) - len);
    }

    return CSString(path);
}

