#include "circular_buffer.hpp"
#include <iostream>

// Demonstration of CircularQueue and CircularBuffer usage with different types and operations
int main() {
    std::cout << "Queue" << std::endl;

    // Create a queue of integers with capacity 3
    CircularQueue<int, 3> queue;

    // Add elements to the queue
    queue.pushBack(3);
    queue.pushBack(4);

    // Check if queue is full (should be false at this point)
    std::cout << "Full (2/3)? " << queue.full() << std::endl;

    // Add one more element to fill the queue
    queue.pushBack(5);
    std::cout << "Full (3/3)? " << queue.full() << std::endl;

    // Check front element (should be 3)
    std::cout << "Front (should be 3) " << queue.front() << std::endl;

    // Remove two elements
    queue.popFront();
    queue.popFront();

    // Now front should be 5
    std::cout << "Front (should be 5) " << queue.front() << std::endl;

    // Check if queue is empty (should be false, only one element left)
    std::cout << "Empty (1/3)? " << queue.empty() << std::endl;

    // Remove the last element
    queue.popFront();

    // Queue is now empty but not full
    std::cout << "Full (0/3)? " << queue.full() << std::endl;
    std::cout << "Empty (0/3)? " << queue.empty() << std::endl;

    std::cout << std::endl;

    // Test with float queue of capacity 2
    CircularQueue<float, 2> floatQueue;
    floatQueue.pushBack(3.3f);
    floatQueue.pushBack(4.4f);
    floatQueue.popFront();  // Remove 3.3
    floatQueue.pushBack(5.5f);  // Add 5.5, overwriting nothing since not full yet

    // Front should be 4.4
    std::cout << "Front (should be 4.4) " << floatQueue.front() << std::endl;
    std::cout << "Size (2/2) " << floatQueue.size() << std::endl;

    floatQueue.popFront();  // Remove 4.4
    std::cout << "Size (1/2) " << floatQueue.size() << std::endl;

    floatQueue.popFront();  // Remove 5.5
    std::cout << "Size (0/2) " << floatQueue.size() << std::endl;

    std::cout << std::endl;
    std::cout << "Buffer" << std::endl;

    // Define a struct for testing CircularBuffer
    struct Inside {
        float value;
        int index;
    };

    // Create a circular buffer that uses 'index' as the key field
    CircularBuffer<Inside, &Inside::index, 3> dataBuffer;

    // Insert two elements
    dataBuffer.insert({3.3f, 3});
    dataBuffer.insert({4.4f, 4});

    // Verify size and content
    std::cout << "Size is (should be 2) " << dataBuffer.size() << std::endl;
    std::cout << "Is 3 there? (should be) " << dataBuffer.has(3) << std::endl;
    std::cout << "Is 5 there? (shouldn't be) " << dataBuffer.has(5) << std::endl;
    std::cout << "What is on 4? (4.4) " << dataBuffer.get(4).value << std::endl;

    // Extract an element by key
    std::cout << "Extracting 3. (3.3) " << dataBuffer.extract(3).value << std::endl;
    std::cout << "Is 3 there? (shouldn't be) " << dataBuffer.has(3) << std::endl;
    std::cout << "Size is (should be 1) " << dataBuffer.size() << std::endl;

    // Extract another element
    std::cout << "Extracting 4. (4.4) " << dataBuffer.extract(4).value << std::endl;
    std::cout << "Size is (should be 0) " << dataBuffer.size() << std::endl;

    // Try to get a non-existent element
    std::cout << "Can get 4 now? (shouldn't) " << bool(dataBuffer.tryGet(4)) << std::endl;

    return 0;
}

#include <iostream>
using namespace std;

int main() {
    int * kingdom1 = new int[10000], * kingdom2 = new int[10000];
    int N, R, C, K;

    while (cin >> N >> R >> C >> K) {
        if (N == 0 && R == 0 && C == 0 && K == 0) break;

        // Read initial kingdom state
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                cin >> kingdom1[i * 100 + j];
            }
        }

        // Simulate K days of transformation
        for (int day = 0; day < K; day++) {
            int* current = (day % 2 == 0) ? kingdom1 : kingdom2;
            int* nextState = (day % 2 == 0) ? kingdom2 : kingdom1;

            for (int row = 0; row < R; row++) {
                for (int col = 0; col < C; col++) {
                    int cellValue = current[row * 100 + col];
                    int targetValue = (cellValue + N - 1) % N;
                    bool isAttacked = false;

                    // Check all four adjacent cells
                    if (row > 0 && current[(row - 1) * 100 + col] == targetValue) {
                        isAttacked = true;
                    }
                    if (col > 0 && current[row * 100 + (col - 1)] == targetValue) {
                        isAttacked = true;
                    }
                    if (row < R - 1 && current[(row + 1) * 100 + col] == targetValue) {
                        isAttacked = true;
                    }
                    if (col < C - 1 && current[row * 100 + (col + 1)] == targetValue) {
                        isAttacked = true;
                    }

                    if (isAttacked) {
                        nextState[row * 100 + col] = targetValue;
                    } else {
                        nextState[row * 100 + col] = cellValue;
                    }
                }
            }
        }

        // Output final state
        int* finalState = (K % 2 == 0) ? kingdom1 : kingdom2;
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < C; j++) {
                if (j > 0) cout << " ";
                cout << finalState[i * 100 + j];
            }
            cout << "\n";
        }
    }

    delete[] kingdom1;
    delete[] kingdom2;
    return 0;
}

#include "CameraMan.h"

CameraMan::CameraMan(Camera* cam)
	: mCam(nullptr)
	, mFocus(nullptr)
{
	assignCamera(cam);
	SceneNode* node = (mFocus ? mFocus : mCam->getSceneManager()->getRootSceneNode());
	mFocus = node;
	mCam->setFixedYawAxis(true);
	repositionCamera(Degree(0), Degree(15), 150.0f);
}

CameraMan::~CameraMan() {}

void CameraMan::assignCamera(Camera* cam) {
	mCam = cam;
}

Camera* CameraMan::retrieveCamera() const {
	return mCam;
}

void CameraMan::assignTarget(SceneNode* target) {
	if (target != mFocus) {
		mFocus = target;
		if (target) {
			repositionCamera(Degree(0), Degree(15), 150.0f);
			mCam->setAutoTracking(true, mFocus);
		} else {
			mCam->setAutoTracking(false);
		}
	}
}

SceneNode* CameraMan::acquireTarget() const {
	return mFocus;
}

void CameraMan::repositionCamera(Radian yaw, Radian pitch, Real distance) {
	Vector3 pos = mFocus->_getDerivedPosition();
	Quaternion orient = mFocus->_getDerivedOrientation();

	mCam->setPosition(pos);
	mCam->setOrientation(orient);
	mCam->yaw(yaw);
	mCam->pitch(-pitch);
	mCam->moveRelative(Vector3(0.0f, 0.0f, distance));
}

void CameraMan::injectMouseMove(const MouseEvent& evt) {
	Real range = (mCam->getPosition() - mFocus->_getDerivedPosition()).length();

	mCam->setPosition(mFocus->_getDerivedPosition());

	mCam->yaw(Degree(-static_cast<float>(evt.state.X.rel) * 0.25f));
	mCam->pitch(Degree(-static_cast<float>(evt.state.Y.rel) * 0.25f));
	mFocus->yaw(Degree(-static_cast<float>(evt.state.X.rel) * 0.25f));

	mCam->moveRelative(Vector3(0.0f, 0.0f, range));

	if (evt.state.Z.rel != 0) {
		mCam->moveRelative(Vector3(0.0f, 0.0f, -static_cast<float>(evt.state.Z.rel) * 0.0008f * range));
	}
}

#include "llvm/TextAPI/Architecture.h"
#include "llvm/ADT/StringSwitch.h"
#include "llvm/ADT/Triple.h"
#include "llvm/BinaryFormat/MachO.h"
#include "llvm/Support/raw_ostream.h"
#include "llvm/TextAPI/ArchitectureSet.h"

namespace llvm {
namespace MachO {

// Convert CPU type and subtype to architecture enum
Architecture getArchitectureFromCpuType(uint32_t CPUType, uint32_t CPUSubType) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  if (CPUType == (Type) &&                                                     \
      (CPUSubType & ~MachO::CPU_SUBTYPE_MASK) == (Subtype))                    \
    return AK_##Arch;
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  return AK_unknown;
}

// Map string name to architecture enum
Architecture getArchitectureFromName(StringRef Name) {
  return StringSwitch<Architecture>(Name)
#define ARCHINFO(Arch, Type, Subtype, NumBits) .Case(#Arch, AK_##Arch)
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
      .Default(AK_unknown);
}

// Get string representation of architecture enum
StringRef getArchitectureName(Architecture Arch) {
  switch (Arch) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  case AK_##Arch:                                                              \
    return #Arch;
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  case AK_unknown:
    return "unknown";
  }
  // Fallback for compilers requiring explicit handling
  return "unknown";
}

// Retrieve CPU type and subtype from architecture enum
std::pair<uint32_t, uint32_t> getCPUTypeFromArchitecture(Architecture Arch) {
  switch (Arch) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  case AK_##Arch:                                                              \
    return std::make_pair(Type, Subtype);
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  case AK_unknown:
    return std::make_pair(0u, 0u);
  }
  // Compiler safety fallback
  return std::make_pair(0u, 0u);
}

// Derive architecture from LLVM Triple target description
Architecture mapToArchitecture(const Triple &Target) {
  return getArchitectureFromName(Target.getArchName());
}

// Determine if architecture is 64-bit
bool is64Bit(Architecture Arch) {
  switch (Arch) {
#define ARCHINFO(Arch, Type, Subtype, NumBits)                                 \
  case AK_##Arch:                                                              \
    return NumBits == 64;
#include "llvm/TextAPI/Architecture.def"
#undef ARCHINFO
  case AK_unknown:
    return false;
  }
  // Ensure compiler recognizes exhaustive coverage
  llvm_unreachable("Fully handled switch case above.");
}

// Output stream operator for architecture enum
raw_ostream &operator<<(raw_ostream &OS, Architecture Arch) {
  OS << getArchitectureName(Arch);
  return OS;
}

} // end namespace MachO.
} // end namespace llvm.

