Parse_HTTP_Response::Parse_HTTP_Response (const char *response)
  : code_ (200),
    code_str_ (0),
    major_version_ (0),
    minor_version_ (0),
    version_ (0),
    response_ (0),
    error_ (0)
{
  if (response != 0)
    this->process_response (response);
}

Parse_HTTP_Response::~Parse_HTTP_Response (void)
{
  if (this->response_)
    ACE_OS::free (this->response_);
  this->response_ = 0;
  this->code_str_ = 0;
  this->version_ = 0;
}

void
Parse_HTTP_Response::process_response (const char *response)
{
  this->response_ = ACE_OS::strdup (response);
  if (this->response_ == 0)
    {
      this->error_ = NO_MEMORY;
      return;
    }

  int parsed_fields = ::sscanf (this->response_, "HTTP/%d.%d %d %*s",
                                &(this->major_version_),
                                &(this->minor_version_),
                                &(this->code_));

  if (parsed_fields == 3)
    {
      char *cursor = this->response_;

      // Skip leading whitespace
      while (*cursor == ' ' || *cursor == '\t')
        cursor++;

      this->version_ = cursor++;

      // Move to end of version string
      while (*cursor != ' ' && *cursor != '\t' && *cursor != '\0')
        cursor++;

      *cursor++ = '\0';

      // Skip whitespace after version
      while (*cursor == ' ' || *cursor == '\t')
        cursor++;

      this->code_str_ = cursor;

      // Terminate status text at first whitespace or line ending
      while (*cursor != '\0' && !ACE_OS::strchr (" \t\r\n", *cursor))
        cursor++;

      *cursor++ = '\0';
    }
  else
    {
      this->error_ = BAD_RESPONSE;
    }
}

