#include "NSSimulatorUtil.h"

bool consumerActive = false;

void onProviderChanged(NSProvider * provider, NSProviderState response)
{
    IOTIVITYTEST_LOG(INFO, "onProviderChanged() invoked !!");
    NSSubscribe(provider->providerId);
}

void onNotificationPosted(NSMessage * notification)
{
    IOTIVITYTEST_LOG(INFO, "onNotificationPosted() invoked !!");
}

void onNotificationSync(NSSyncInfo * sync)
{
    IOTIVITYTEST_LOG(INFO, "onNotificationSync() invoked !!");
}

void initializeConsumer() {
    IOTIVITYTEST_LOG(INFO, "Initializing Consumer.......");
    NSConsumerConfig settings;
    settings.providerChangeHandler = &onProviderChanged;
    settings.messageHandler = &onNotificationPosted;
    settings.syncHandler = &onNotificationSync;

    NSResult outcome = NSStartConsumer(settings);
    if (outcome == NS_OK) {
        consumerActive = true;
        IOTIVITYTEST_LOG(INFO, "Consumer initialized successfully !!");
    } else {
        consumerActive = false;
        IOTIVITYTEST_LOG(INFO, "Failed to initialize Consumer !!");
    }
}

void shutdownConsumer() {
    if (consumerActive) {
        NSStopConsumer();
    }
}

void handleSelection(int option) {
    switch (option) {
        case 0:
            initializeConsumer();
            break;
        default:
            IOTIVITYTEST_LOG(INFO, "Simulator will use default configuration...");
            initializeConsumer();
            break;
    }
}

int main(int argc, char **argv) {
    PlatformConfig setup
    { ServiceType::InProc, ModeType::Both, "0.0.0.0", 0, QualityOfService::LowQos };
    OCPlatform::Configure(setup);
    IOTIVITYTEST_LOG(INFO, "Platform Setup Completed!!");

    try
    {
        OCPlatform::stopPresence();
        IOTIVITYTEST_LOG(INFO, "Successfully executed stopPresence() !!");
    }
    catch (...)
    {
        IOTIVITYTEST_LOG(WARNING, "Unable to execute stopPresence..!!!");
    }

    int selectedOption = 0;
    if (argc > 1) {
        try {
            selectedOption = std::atoi(argv[1]);
        } catch (...) {
            selectedOption = 0;
        }
    }

    handleSelection(selectedOption);
    IOTIVITYTEST_LOG(INFO, "Notification Consumer is Active :-)....");

    // Infinite loop to keep the consumer running
    while(true) {
        // Busy-wait loop intentionally left empty
    }

    shutdownConsumer();
    return 0;
}

