// Custom panic handler: logs error and returns control to Lua for abort
static int lua_unsafe_panic_handler(lua_State* L) {
    luai_writestringerror("PANIC: unguarded Lua API call failed (%s)\n",
                          lua_tostring(L, -1));
    return 0;
}

// Helper to extract stack trace info from Lua state
static std::string describe_lua_frame(lua_State* L, int depth = 1) {
    lua_Debug frame_info;
    std::ostringstream msg;

    if (lua_getstack(L, depth, &frame_info) && lua_getinfo(L, "Sln", &frame_info)) {
        msg << frame_info.short_src << ":" << frame_info.currentline
            << " (" << frame_info.what << " "
            << frame_info.namewhat << " "
            << (frame_info.name ? frame_info.name : "(anonymous)") << ")";
    } else {
        msg << "<unknown location>:?";
    }

    return msg.str();
}

// Collect full backtrace using iterative traversal instead of recursion
static std::string build_backtrace(lua_State* L, const char* err_msg = nullptr) {
    std::ostringstream report;
    report << "Lua Runtime Error" << (err_msg ? ": " + std::string(err_msg) : "") << "\n";

    int current_depth = 0;
    lua_Debug dummy;
    while (lua_getstack(L, current_depth, &dummy)) {
        report << "  at " << describe_lua_frame(L, current_depth) << "\n";
        ++current_depth;
    }

    return report.str();
}

// Overload for debug vs release logging
static void log_lua_error(const std::string& msg) {
#ifdef DEBUG
    std::printf("%s\n", msg.c_str());
#else
    errlog << msg << std::endl;
#endif
}

LuaInterface::LuaInterface(const char* script_path, int arg_count, const char* const* args)
    : script_file(script_path), num_args(arg_count), arg_list(args), vm(nullptr) {
#ifdef DEBUG
    std::puts("LuaInterface: Loaded " LUA_RELEASE);
#else
    errlog << "LuaInterface: Using " << LUA_RELEASE << std::endl;
#endif
}

LuaInterface::~LuaInterface() {
    Cleanup();
}

void LuaInterface::Cleanup() {
    if (vm) {
        lua_close(vm);
        vm = nullptr;
    }
}

void LuaInterface::CollectGarbage() {
    lua_gc(vm, LUA_GCCOLLECT, 0);
}

unsigned int LuaInterface::GetMemoryUsage() const {
    return static_cast<unsigned int>(lua_gc(vm, LUA_GCCOUNT, 0));
}

bool LuaInterface::Initialize() {
    if (!vm) {
        vm = luaL_newstate();
        if (!vm) return false;

        lua_atpanic(vm, lua_unsafe_panic_handler);
        luaL_openlibs(vm);
        register_engine_functions(vm);
    }

    if (luaL_loadfile(vm, script_file) != LUA_OK) {
        return false;
    }

    // Push command-line arguments onto the stack
    std::vector<const char*> safe_argv(num_args);
    for (int i = 0; i < num_args; ++i) {
        safe_argv[i] = arg_list[i];
        lua_pushstring(vm, safe_argv[i]);
    }

    return ExecuteCall(num_args);
}

void LuaInterface::ResolveFunction(const char* func_name) {
    lua_getglobal(vm, func_name);
}

bool LuaInterface::ExecuteCall(int param_count, int result_count /*= 0*/) {
    if (lua_pcall(vm, param_count, result_count, 0) != LUA_OK) {
        const char* raw_err = getCStr(vm, -1);
        log_lua_error(build_backtrace(vm, raw_err));
        lua_pop(vm, 1);  // Pop error string
        return false;
    }
    return true;
}

bool LuaInterface::Invoke(const char* name) {
    ResolveFunction(name);
    return ExecuteCall(0);
}

bool LuaInterface::Invoke(const char* name, const char* arg1) {
    ResolveFunction(name);
    lua_pushstring(vm, arg1);
    return ExecuteCall(1);
}

bool LuaInterface::Invoke(const char* name,
                          const char* a, const char* b,
                          const char* c, const char* d,
                          const char* e) {
    ResolveFunction(name);
    lua_pushstring(vm, a);
    lua_pushstring(vm, b);
    lua_pushstring(vm, c);
    lua_pushstring(vm, d);
    lua_pushstring(vm, e);
    return ExecuteCall(5);
}

bool LuaInterface::Invoke(const char* name,
                          const char* a, const char* b,
                          const char* c, const char* d) {
    ResolveFunction(name);
    lua_pushstring(vm, a);
    lua_pushstring(vm, b);
    lua_pushstring(vm, c);
    lua_pushstring(vm, d);
    return ExecuteCall(4);
}

bool LuaInterface::Invoke(const char* name,
                          const char* a, const char* b) {
    ResolveFunction(name);
    lua_pushstring(vm, a);
    lua_pushstring(vm, b);
    return ExecuteCall(2);
}

bool LuaInterface::Invoke(const char* name, float value) {
    ResolveFunction(name);
    lua_pushnumber(vm, value);
    return ExecuteCall(1);
}

bool LuaInterface::Invoke(const char* name, int x, int y) {
    ResolveFunction(name);
    lua_pushinteger(vm, x);
    lua_pushinteger(vm, y);
    return ExecuteCall(2);
}

bool LuaInterface::Invoke(const char* name, int x, int y, bool flag) {
    ResolveFunction(name);
    lua_pushinteger(vm, x);
    lua_pushinteger(vm, y);
    lua_pushboolean(vm, flag);
    return ExecuteCall(3);
}

bool LuaInterface::Invoke(const char* name, int a, int b, int c, int d) {
    ResolveFunction(name);
    lua_pushinteger(vm, a);
    lua_pushinteger(vm, b);
    lua_pushinteger(vm, c);
    lua_pushinteger(vm, d);
    return ExecuteCall(4);
}

bool LuaInterface::Invoke(const char* name, int a, int b, int c, int d, int e) {
    ResolveFunction(name);
    lua_pushinteger(vm, a);
    lua_pushinteger(vm, b);
    lua_pushinteger(vm, c);
    lua_pushinteger(vm, d);
