{
}

CPTGameObject::CPTGameObject(const CPTGameObject& src)
{
    inside_color = src.inside_color;
    outside_color = src.outside_color;
    m_nOnSketch = src.m_nOnSketch;
    m_nFlags = src.m_nFlags;
    m_nObjType = src.m_nObjType;
    m_ptPos1 = src.m_ptPos1;
    m_ptPos2 = src.m_ptPos2;
    // m_ptPos3 = src.m_ptPos3;
}

CPTGameObject& CPTGameObject::operator=(const CPTGameObject& src)
{
    if (this != &src) {
        inside_color = src.inside_color;
        outside_color = src.outside_color;
        m_nOnSketch = src.m_nOnSketch;
        m_nFlags = src.m_nFlags;
        m_nObjType = src.m_nObjType;
        m_ptPos1 = src.m_ptPos1;
        m_ptPos2 = src.m_ptPos2;
        // m_ptPos3 = src.m_ptPos3;
    }
    return *this;
}

void CPTGameObject::Serialize(CArchive& ar)
{
    CObject::Serialize(ar);

    if (ar.IsStoring()) {
        ar << m_nObjType;

        if (m_nObjType == LINE || m_nObjType == CIRCLE) {
            ar << inside_color;
            ar << outside_color;
            ar << m_ptPos2;
        }

        ar << m_nOnSketch;
        ar << m_nFlags;
        ar << m_ptPos1;
        // ar << m_ptPos3;
    } else {
        ar >> m_nObjType;

        if (m_nObjType == LINE || m_nObjType == CIRCLE) {
            ar >> inside_color;
            ar >> outside_color;
            ar >> m_ptPos2;
        }

        ar >> m_nOnSketch;
        ar >> m_nFlags;
        ar >> m_ptPos1;
        // ar >> m_ptPos3;
    }
}

