namespace llvm {

DwarfFile::DwarfFile(AsmPrinter *AP, DwarfDebug &DD, StringRef Pref,
                     BumpPtrAllocator &DA)
    : Asm(AP), DD(DD), StrPool(DA, *Asm, Pref) {}

DwarfFile::~DwarfFile() = default;

// Assigns a unique abbreviation number to the given DIEAbbrev.
void DwarfFile::assignAbbrevNumber(DIEAbbrev &Abbrev) {
  // Insert or retrieve existing node from set
  auto *Existing = AbbreviationsSet.GetOrInsertNode(&Abbrev);

  if (Existing != &Abbrev) {
    // Already exists: reuse its number
    Abbrev.setNumber(Existing->getNumber());
  } else {
    // New entry: assign new number based on position
    Abbreviations.push_back(&Abbrev);
    Abbrev.setNumber(Abbreviations.size());
  }
}

void DwarfFile::addUnit(std::unique_ptr<DwarfUnit> U) {
  CUs.emplace_back(std::move(U));
}

// Emit all compile units into their respective sections
void DwarfFile::emitUnits(const MCSymbol *ASectionSym) {
  for (size_t Idx = 0; Idx < CUs.size(); ++Idx) {
    auto &UnitPtr = CUs[Idx];
    DIE &RootDie = UnitPtr->getUnitDie();
    const MCSection *UnitSec = UnitPtr->getSection();

    Asm->OutStreamer.SwitchSection(UnitSec);
    UnitPtr->emitHeader(ASectionSym);
    DD.emitDIE(RootDie);
  }
}

// Compute sizes and offsets for all DIEs across all CUs
void DwarfFile::computeSizeAndOffsets() {
  unsigned TotalOffset = 0;
  for (auto &CU : CUs) {
    CU->setDebugInfoOffset(TotalOffset);

    // Start offset after length field + header
    unsigned LocalOffset = sizeof(int32_t) + CU->getHeaderSize();
    unsigned FinalOffset = computeSizeAndOffsetRecursive(CU->getUnitDie(), LocalOffset);
    TotalOffset += FinalOffset;
  }
}

// Helper: recursively compute size and offset for a DIE and its children
unsigned DwarfFile::computeSizeAndOffsetRecursive(DIE &Die, unsigned Offset) {
  // Ensure abbreviation is assigned
  assignAbbrevNumber(Die.getAbbrev());

  const DIEAbbrev &Abbr = Die.getAbbrev();
  Die.setOffset(Offset);

  // Account for abbreviation code
  Offset += getULEB128Size(Die.getAbbrevNumber());

  // Process attributes
  const auto &Attrs = Die.getValues();
  const auto &AbbrData = Abbr.getData();
  for (size_t i = 0; i < Attrs.size(); ++i) {
    Offset += Attrs[i]->SizeOf(Asm, AbbrData[i].getForm());
  }

  // Handle children
  auto &Kids = Die.getChildren();
  if (!Kids.empty()) {
    assert(Abbr.hasChildren() && "Expected children flag");
    for (auto &Child : Kids) {
      Offset = computeSizeAndOffsetRecursive(*Child, Offset);
    }
    // End-of-children marker
    Offset += sizeof(int8_t);
  }

  Die.setSize(Offset - Die.getOffset());
  return Offset;
}

// Emit abbreviations into debug_abbrev section
void DwarfFile::emitAbbrevs(const MCSection *Section) {
  if (Abbreviations.empty())
    return;

  Asm->OutStreamer.SwitchSection(Section);

  for (const DIEAbbrev *Abbr : Abbreviations) {
    Asm->EmitULEB128(Abbr->getNumber(), "Abbreviation Code");
    Abbr->Emit(Asm);
  }

  Asm->EmitULEB128(0, "End of Abbreviations Marker");
}

// Emit string pool into .debug_str and optional index section
void DwarfFile::emitStrings(const MCSection *StrSection,
                            const MCSection *OffsetSection) {
  StrPool.emit(*Asm, StrSection, OffsetSection);
}

// Insert a DbgVariable into scope list, preserving parameter ordering
void DwarfFile::addScopeVariable(LexicalScope *LS, DbgVariable *Var) {
  auto &VarList = ScopeVariables[LS];
  DIVariable DV = Var->getVariable();
  unsigned ArgNum = DV.getArgNumber();

  if (ArgNum == 0) {
    // Non-parameter: append at end
    VarList.push_back(Var);
    return;
  }

  // Find first position where current var should be inserted
  auto It = std::find_if(VarList.begin(), VarList.end(),
                         [&](DbgVariable *V) {
                           unsigned CurArg = V->getVariable().getArgNumber();
                           return CurArg == 0 || CurArg > ArgNum;
                         });

  // Insert before found iterator (or at end if none)
  VarList.insert(It, Var);
}

