using document::test::makeDocumentBucket;
using namespace ::testing;

namespace storage::distributor {

struct JoinOperationTest : Test, DistributorTestUtil {
    void verifySourceBucketsAndTriggerReply(
            JoinOperation& op,
            size_t requestIdx,
            const std::vector<document::BucketId>& expectedIds);

    void SetUp() override {
        createLinks();
    };

    void TearDown() override {
        close();
    }
};

TEST_F(JoinOperationTest, basic_functionality) {
    getConfig().setJoinCount(100);
    getConfig().setJoinSize(1000);

    addNodesToBucketDB(document::BucketId(33, 1), "0=250/50/300");
    addNodesToBucketDB(document::BucketId(33, 0x100000001), "0=300/40/200");

    enableDistributorClusterState("distributor:1 storage:1");

    JoinOperation op("storage",
                     BucketAndNodes(makeDocumentBucket(document::BucketId(32, 0)),
                                    toVector<uint16_t>(0)),
                     toVector(document::BucketId(33, 1),
                              document::BucketId(33, 0x100000001)));

    op.setIdealStateManager(&getIdealStateManager());
    op.start(_sender, framework::MilliSecTime(0));

    verifySourceBucketsAndTriggerReply(op, 0, {{33, 1}, {33, 0x100000001}});

    EXPECT_FALSE(getBucket(document::BucketId(33, 0x100000001)).valid());
    EXPECT_FALSE(getBucket(document::BucketId(33, 1)).valid());

    BucketDatabase::Entry entry = getBucket(document::BucketId(32, 0));
    ASSERT_TRUE(entry.valid());
    EXPECT_EQ(0, entry->getNodeRef(0).getNode());
    EXPECT_EQ(api::BucketInfo(666, 90, 500), entry->getNodeRef(0).getBucketInfo());
}

void
JoinOperationTest::verifySourceBucketsAndTriggerReply(
        JoinOperation& op,
        size_t requestIdx,
        const std::vector<document::BucketId>& expectedIds)
{
    ASSERT_GT(_sender.commands().size(), requestIdx);
    std::shared_ptr<api::StorageCommand> msg(_sender.command(requestIdx));
    ASSERT_EQ(api::MessageType::JOINBUCKETS, msg->getType());

    auto& joinCmd = dynamic_cast<api::JoinBucketsCommand&>(*msg);
    EXPECT_THAT(joinCmd.getSourceBuckets(), ContainerEq(expectedIds));

    std::shared_ptr<api::StorageReply> reply(joinCmd.makeReply());
    auto& sreply = dynamic_cast<api::JoinBucketsReply&>(*reply);
    sreply.setBucketInfo(api::BucketInfo(666, 90, 500));
    op.receive(_sender, reply);
}

/**
 * When the buckets reside on disjoint sets of nodes, send sparse joins 
 * (where both source buckets are identical) for nodes that only hold one bucket.
 */
TEST_F(JoinOperationTest, sparse_joins_for_disjoint_node_sets) {
    getConfig().setJoinCount(100);
    getConfig().setJoinSize(1000);

    addNodesToBucketDB(document::BucketId(33, 1), "0=250/50/300,1=250/50/300");
    addNodesToBucketDB(document::BucketId(33, 0x100000001), "0=300/40/200");

    enableDistributorClusterState("distributor:1 storage:2");

    JoinOperation op("storage",
                     BucketAndNodes(makeDocumentBucket(document::BucketId(32, 0)),
                                    toVector<uint16_t>(0, 1)),
                     toVector(document::BucketId(33, 1),
                              document::BucketId(33, 0x100000001)));

    op.setIdealStateManager(&getIdealStateManager());
    op.start(_sender, framework::MilliSecTime(0));

    ASSERT_NO_FATAL_FAILURE(verifySourceBucketsAndTriggerReply(op, 0, {{33, 1}, {33, 0x100000001}}));
    ASSERT_NO_FATAL_FAILURE(verifySourceBucketsAndTriggerReply(op, 1, {{33, 1}, {33, 1}}));
}

