int main(int argc, char *argv[]) {
    using namespace httplib;
    Server httpServer;

    // Validate command-line arguments
    if (argc < 3) {
        std::cerr << "Usage: " << argv[0] << " <BIND_ADDRESS> <PORT>" << std::endl;
        return 1;
    }

    const char* bindAddr = argv[1];
    unsigned long serverPort = std::stoul(argv[2]);

    LOG_INF("Starting HTTP server on %s:%lu", bindAddr, serverPort);

    // Handle GET /hi endpoint
    httpServer.Get("/hi", [](const httplib::Request&, httplib::Response& response) {
        response.set_content("Hello World!", "text/plain");
    });

    // Handle POST /configure endpoint
    httpServer.Post("/configure", [](const httplib::Request& request, httplib::Response& response) {
        json incomingJson = json::parse(request.body);
        json outgoingJson;
        response.status = Controller::setup(incomingJson, outgoingJson);
        response.set_content("{\"status\": \"configured\"}", "application/json");
    });

    // Handle POST /createSession endpoint
    httpServer.Post("/createSession", [](const httplib::Request& request, httplib::Response& response) {
        json sessionRequest = json::parse(request.body);
        json sessionResponse;
        response.status = Controller::createSesssion(sessionRequest, sessionResponse);
        response.set_content("{\"session\": \"created\"}", "application/json");
    });

    // Start the server
    httpServer.listen(bindAddr, static_cast<int>(serverPort));
}

#include "clang/Basic/SourceMgrAdapter.h"
#include "clang/Basic/Diagnostic.h"
using namespace clang;

// Static handler to delegate diagnostics to the adapter instance
void SourceMgrAdapter::handleDiag(const llvm::SMDiagnostic &diag,
                                  void *context) {
  auto *adapter = static_cast<SourceMgrAdapter *>(context);
  adapter->processDiagnostic(diag);
}

// Constructor initializes internal state for mapping and diagnostics
SourceMgrAdapter::SourceMgrAdapter(SourceManager &srcMgr,
                                   DiagnosticsEngine &diag,
                                   unsigned errorDiagID,
                                   unsigned warningDiagID,
                                   unsigned noteDiagID,
                                   const FileEntry *defaultFile)
  : SrcMgr(srcMgr), Diag(diag), ErrorDiagID(errorDiagID),
    WarningDiagID(warningDiagID), NoteDiagID(noteDiagID),
    DefaultFile(defaultFile) { }

// Destructor (no special cleanup required currently)
SourceMgrAdapter::~SourceMgrAdapter() { }

// Convert an LLVM source location to Clang's SourceLocation
SourceLocation SourceMgrAdapter::mapLocation(const llvm::SourceMgr &llvmSrcMgr,
                                             llvm::SMLoc loc) {
  // Handle invalid input location early
  if (!loc.isValid())
    return SourceLocation();

  // Locate the buffer containing this position
  unsigned bufferID = llvmSrcMgr.FindBufferContainingLoc(loc);
  if (!bufferID)
    return SourceLocation();

  // Retrieve the memory buffer
  auto buffer = llvmSrcMgr.getMemoryBuffer(bufferID);

  // Check if we've already mapped this buffer
  auto knownBuffer = FileIDMapping.find(std::make_pair(&llvmSrcMgr, bufferID));
  if (knownBuffer == FileIDMapping.end()) {
    FileID fileID;
    if (DefaultFile) {
      // Use provided default file for initial mapping
      fileID = SrcMgr.createFileID(DefaultFile, SourceLocation(),
                                   SrcMgr::C_User);
      DefaultFile = nullptr; // Ensure only one-time use
    } else {
      // Duplicate buffer content into a new owned MemoryBuffer
      StringRef bufferName = buffer->getBufferIdentifier();
      auto bufferCopy = std::unique_ptr<llvm::MemoryBuffer>(
          llvm::MemoryBuffer::getMemBufferCopy(buffer->getBuffer(), bufferName));
      fileID = SrcMgr.createFileID(std::move(bufferCopy));
    }
    // Record the mapping for future lookups
    knownBuffer = FileIDMapping.emplace(
        std::make_pair(&llvmSrcMgr, bufferID), fileID).first;
  }

  // Compute byte offset within the buffer
  unsigned offset = loc.getPointer() - buffer->getBufferStart();
  return SrcMgr.getLocForStartOfFile(knownBuffer->second)
           .getLocWithOffset(offset);
}

// Map an LLVM source range to Clang's SourceRange
SourceRange SourceMgrAdapter::mapRange(const llvm::SourceMgr &llvmSrcMgr,
                                       llvm::SMRange range) {
  if (!range.isValid())
    return SourceRange();

  SourceLocation start = mapLocation(llvmSrcMgr, range.Start);
  SourceLocation end   = mapLocation(llvmSrcMgr, range.End);
  return SourceRange(start, end);
}

// Internal method to process and emit diagnostics using Clang's engine
void SourceMgrAdapter::processDiagnostic(const llvm::SMDiagnostic &diag) {
  // Translate location
  SourceLocation loc;
  if (auto *llvmSrcMgr = diag.getSourceMgr())
    loc = mapLocation(*llvmSrcMgr, diag.getLoc());

  // Extract diagnostic message text
  StringRef message = diag.getMessage();

  // Determine diagnostic severity level
  unsigned diagID;
  switch (diag.getKind()) {
  case llvm::SourceMgr::DK_Error:
    diagID = ErrorDiagID;
    break;
  case llvm::SourceMgr::DK_Warning:
    diagID = WarningDiagID;
    break;
  case llvm::SourceMgr::DK_Note:
    diagID = NoteDiagID;
    break;
  default:
    diagID = ErrorDiagID; // fallback
    break;
  }

  // Emit diagnostic via Clang's DiagnosticEngine
  DiagnosticBuilder builder = Diag.Report(loc, diagID) << message;

  // Attach source ranges and fix-its if available
  if (auto *llvmSrcMgr = diag.getSourceMgr()) {
    // Align ranges relative to beginning of line
    SourceLocation startOfLine = loc.getLocWithOffset(-diag.getColumnNo());
    for (const auto &range : diag.getRanges()) {
      builder << SourceRange(startOfLine.getLocWithOffset(range.first),
                             startOfLine.getLocWithOffset(range.second));
    }

    // Apply any suggested fixes
    for (const llvm::SMFixIt &fixIt : diag.getFixIts()) {
      CharSourceRange range(mapRange(*llvmSrcMgr, fixIt.getRange()), false);
      builder << FixItHint::CreateReplacement(range, fixIt.getText());
    }
  }
}

#include <iostream>
