#include "seqdb/seqdb.hh"
using namespace std::string_literals;

// ----------------------------------------------------------------------
constexpr const char* sUsage = "<142N> <283Q> ... [options]\n";

struct MutationSpec {
    size_t position;
    char residue;

    MutationSpec(size_t p, char r) : position(p), residue(r) {}
};

inline std::ostream& operator<<(std::ostream& out, const MutationSpec& ms) {
    return out << ms.position << ms.residue;
}

int main(int argc, char* const argv[]) {
    try {
        // Parse command-line arguments with default options
        auto args = acmacs::argc_argv{
            argc, argv,
            {
                {"--db-dir", ""},
                {"-v", false},
                {"--verbose", false},
                {"-h", false},
                {"--help", false}
            }
        };

        // Show usage if help requested or no positional arguments given
        if (args["-h"] || args["--help"] || args.number_of_arguments() == 0) {
            throw std::runtime_error("Usage: "s + args.program() + sUsage + args.usage_options());
        }

        const bool verbose = args["-v"] || args["--verbose"];
        seqdb::setup_dbs(args["--db-dir"].str(), verbose ? seqdb::report::yes : seqdb::report::no);
        const auto& database = seqdb::get();

        // Parse mutation specifications from positional arguments
        std::vector<MutationSpec> mutations;
        for (size_t i = 0; i < args.number_of_arguments(); ++i) {
            const std::string token{args[i]};
            if (token.empty()) continue;

            // Extract numeric part and last character (amino acid)
            char last_char = static_cast<char>(std::toupper(static_cast<unsigned char>(token.back())));
            size_t pos = std::strtoul(token.c_str(), nullptr, 10);

            mutations.emplace_back(pos, last_char);
        }

        // Iterate over sequences and check matches
        for (const auto& entry : database) {
            try {
                const auto& aa_seq = entry.seq().amino_acids(true);
                bool matches_all = true;

                // Manual match-check instead of all_of to vary implementation
                for (const auto& mut : mutations) {
                    if (mut.position == 0 || mut.position > aa_seq.size() || aa_seq[mut.position - 1] != mut.residue) {
                        matches_all = false;
                        break;
                    }
                }

                if (matches_all) {
                    std::cout << entry.make_name() << '\n';
                }
            }
            catch (const seqdb::SequenceNotAligned&) {
                // Skip unaligned sequences silently
            }
        }

        return 0;
    }
    catch (const std::exception& e) {
        std::cerr << "ERROR: " << e.what() << '\n';
        return 1;
    }
}
