#define INFOTOCERR std::cerr << __FILE__ << ":" << __LINE__ << ":" << __func__ << ": "

const WignerCoefficientSingleton* WignerCoefficientSingleton::WignerCoefficientInstance = nullptr;

// Helper: compute power safely for small magnitudes
inline double safePow(double base, int exp) {
    if (exp == 0) return 1.0;
    double result = 1.0;
    bool invert = exp < 0;
    unsigned int absExp = invert ? static_cast<unsigned int>(-exp) : static_cast<unsigned int>(exp);
    while (absExp--) {
        result *= base;
    }
    return invert ? 1.0 / result : result;
}

/// Construct the D matrix object given the (optional) rotor.
WignerDMatrix::WignerDMatrix(const Quaternion& R)
  : ErrorOnBadIndices(true),
    BinomialCoefficient(BinomialCoefficientSingleton::Instance()),
    WignerCoefficient(WignerCoefficientSingleton::Instance()),
    zeta(R[0], R[3]),   // renamed from Ra
    eta(R[2], R[1]),    // renamed from Rb
    magZeta(abs(zeta)),
    magEta(abs(eta)),
    magRatioSq(magZeta > epsilon ? (magEta * magEta) / (magZeta * magZeta) : 0.0),
    log10MagZeta(magZeta > epsilon ? std::log10(magZeta) : DBL_MIN_10_EXP),
    log10MagEta(magEta > epsilon ? std::log10(magEta) : DBL_MIN_10_EXP)
{ }

/// Reset the rotor for this object to the given value.
WignerDMatrix& WignerDMatrix::SetRotation(const Quaternion& R) {
    zeta = complex<double>(R[0], R[3]);
    eta  = complex<double>(R[2], R[1]);
    magZeta = abs(zeta);
    magEta  = abs(eta);
    magRatioSq = magZeta > epsilon ? (magEta * magEta) / (magZeta * magZeta) : 0.0;
    log10MagZeta = magZeta > epsilon ? std::log10(magZeta) : DBL_MIN_10_EXP;
    log10MagEta  = magEta  > epsilon ? std::log10(magEta)  : DBL_MIN_10_EXP;
    return *this;
}

/// Evaluate the D matrix element for the given (ell, mp, m) indices.
complex<double> WignerDMatrix::operator()(const int ell, const int mp, const int m) const {
    // Validate indices first
    if (std::abs(mp) > ell || std::abs(m) > ell) {
        if (ErrorOnBadIndices) {
            INFOTOCERR << "(" << ell << ", " << mp << ", " << m << ") is not a valid set of indices.\n"
                       << "If you want this object (let's call it `D`) to return 0.0 when invalid\n"
                       << " indices are requested, you can set `D.ErrorOnBadIndices = false`.\n" << std::endl;
            throw(ValueError);
        } else {
            return complex<double>(0.0, 0.0);
        }
    }

    // Special case: one component dominates heavily
    if (magZeta < epsilon || 2 * log10MagZeta * (mp - m) < DBL_MIN_10_EXP + 17) {
        if (mp != -m) {
            return complex<double>(0.0, 0.0);
        } else {
            const int signFactor = ((ell + mp) % 2 == 0) ? 1 : -1;
            return signFactor * std::pow(eta, 2 * m);
        }
    }

    if (magEta < epsilon || 2 * log10MagEta * (mp - m) < DBL_MIN_10_EXP + 17) {
        if (mp != m) {
            return complex<double>(0.0, 0.0);
        } else {
            return std::pow(zeta, 2 * m);
        }
    }

    // Determine summation bounds
    const int rhoStart = std::max(0, mp - m);
    const int rhoEnd   = std::min(ell + mp, ell - m);

    // Handle numerically delicate regime where |zeta| is very small
    if (magZeta < 1.e-3) {
        const complex<double> prefactor =
            WignerCoefficient(ell, mp, m) *
            std::pow(zeta, m + mp) *
            std::pow(eta, m - mp);

        const double magZetaSq = magZeta * magZeta;
        const double magEtaSq  = magEta  * magEta;

        double accumulator = 0.0;

        // Reverse loop over rho
        for (int rho = rhoEnd; rho >= rhoStart; --rho) {
            const double termBase = std::pow(magZetaSq, ell - m - rho);
            if (!std::isfinite(termBase) || termBase < 1.e-100) {
                accumulator *= magEtaSq;
                continue;
            }

            const int parity = (rho % 2 == 0) ? 1 : -1;
            const double combTerm =
                parity *
                BinomialCoefficient(ell + mp, rho) *
                BinomialCoefficient(ell - mp, ell - rho - m);

            accumulator = combTerm * termBase + accumulator * magEtaSq;
        }

        return prefactor * accumulator * std::pow(magEtaSq, rhoStart);
    } else {
        // Standard computation path
        const complex<double> prefactor =
            WignerCoefficient(ell, mp, m) *
            std::pow(magZeta, 2 * ell - 2 * m) *
            std::pow(zeta, m + mp) *
            std::pow(eta, m - mp);

        double sum = 0.0;

        // Accumulate in reverse order
        for (int rho = rhoEnd; rho >= rhoStart; --rho) {
            const int parity = (rho % 2 == 0) ? 1 : -1;
            const double combTerm =
                parity *
                BinomialCoefficient(ell + mp, rho) *
                BinomialCoefficient(ell - mp, ell - rho - m);

            sum = combTerm + sum * magRatioSq;
        }

        return prefactor * sum * std::pow(magRatioSq, rhoStart);
    }
}

