namespace dragon::lumberyard::chunk::emfx {
    ActorMesh::ActorMesh(Array<char>* buffer, EMFX_CHUNK_HEADER header, int& ptr) {
        assert(header.Version <= 2);
        Chunk = header;
        Header = buffer->lpcast<ACTOR_MESH_V1_HEADER>(&ptr);

        // Initialize VBO and submesh containers with appropriate sizes
        VBOs = Array<std::shared_ptr<ActorVertexBuffer>>(Header.NumVBOs, nullptr);
        Submeshes = Array<std::shared_ptr<ActorSubmesh>>(Header.NumSubMeshes, nullptr);

        // Load vertex buffers using index-based iteration
        for (uint32_t idx = 0; idx < Header.NumVBOs; ++idx) {
            VBOs[idx] = std::make_shared<ActorVertexBuffer>(buffer, header, Header, ptr);
        }

        // Load submeshes using a separate counter variable
        uint32_t submeshIndex = 0;
        while (submeshIndex < Header.NumSubMeshes) {
            Submeshes[submeshIndex] = std::make_shared<ActorSubmesh>(buffer, header, ptr);
            ++submeshIndex;
        }
    }
} // namespace dragon::lumberyard::chunk::emfx

