// Circle area calculation using radius r
double circle_shape::get_area() {
    return PI * r * r;
}

// Circle perimeter (circumference) calculation
double circle_shape::get_perimeter() {
    return 2.0 * PI * r;
}

// Rectangle area calculation using opposite corners (x,y) and (x1,y1)
double rectangle_shape::get_area() {
    double width = x1 - x;
    double height = y - y1;
    return width * height;
}

// Rectangle perimeter calculation using opposite corners
double rectangle_shape::get_perimeter() {
    double width = x1 - x;
    double height = y - y1;
    return 2.0 * (width + height);
}

