// Reusable point buffer for polar chart rendering
static lv_point_t polar_points[acquisition::kCaptureBufferSize];

// Axis configuration for the polar plot
static const ui::ChartAxisConfigs kPolarChartAxes{
    .y_range = {.min = -2500, .max = 2500},
    .x = {.labels = "-2.5A\n0\n2.5A", .num_ticks = 3, .dividers = 1},
    .y = {.labels = "2.5A\n0\n-2.5A", .num_ticks = 3, .dividers = 1}};

void PhaseScreen::setup(uint8_t screen_index) {
  ui::create_screen(&screen_);
  ui::create_page_elements(screen_, "PHASE PATTERNS", screen_index, nullptr);
  ui::create_polar_chart(screen_, kPolarChartAxes, ui_events::UI_EVENT_SCALE,
                         &polar_chart_);
  capture_controls_.setup(screen_);

  // Dynamic label for scale/time info
  ui::create_label(screen_, 0, 350, 180, "??", ui::kFontSmallText,
                   LV_LABEL_ALIGN_CENTER, LV_COLOR_SILVER, &time_label_);

  lv_label_set_long_mode(time_label_.lv_label, LV_LABEL_LONG_EXPAND);
  time_label_.set_click_event(ui_events::UI_EVENT_SCALE);
}

void PhaseScreen::on_load() {
  capture_controls_.sync_button_to_state();
  refresh_display();
}

void PhaseScreen::on_event(ui_events::UiEventId event_id) {
  switch (event_id) {
    case ui_events::UI_EVENT_RESET:
      capture_util::clear_data();
      capture_controls_.sync_button_to_state();
      refresh_display();
      break;

    case ui_events::UI_EVENT_SCALE: {
      capture_util::toggle_scale();
      capture_controls_.sync_button_to_state();
      refresh_display();
    } break;

    default:
      break;
  }
}

// Convert milliampere value to coordinate relative to max radius
static lv_coord_t convert_milliamps_to_coord(int ma_value, lv_coord_t radius_limit) {
  constexpr int kFullScaleCurrent = 2500;
  return radius_limit + static_cast<lv_coord_t>((ma_value * radius_limit) / kFullScaleCurrent);
}

void PhaseScreen::refresh_display() {
  capture_controls_.update_display_from_state();

  // Update time/scale label based on current mode
  time_label_.set_text(capture_util::alternative_scale()
                           ? "SLOW Capture\ntime:  100ms"
                           : "FAST Capture\ntime:  20ms");

  if (!capture_util::has_data()) {
    lv_line_set_points(polar_chart_.lv_line, polar_points, 0);
    return;
  }

  // Populate points using captured data
  for (int idx = 0; idx < acquisition::kCaptureBufferSize; ++idx) {
    const acquisition::CaptureItem* sample =
        capture_util::capture_buffer()->items.get(idx);

    const int i1_ma = acquisition::adc_value_to_milliamps(sample->v1);
    const int i2_ma = acquisition::adc_value_to_milliamps(sample->v2);

    polar_points[idx].x = convert_milliamps_to_coord(i1_ma, polar_chart_.max_radius);
    polar_points[idx].y = convert_milliamps_to_coord(i2_ma, polar_chart_.max_radius);
  }

  lv_line_set_points(polar_chart_.lv_line, polar_points,
                     acquisition::kCaptureBufferSize);
}

void PhaseScreen::loop() {
  // Check for button-triggered state changes first
  if (capture_util::maybe_update_state_from_controls(capture_controls_)) {
    refresh_display();
    return;
  }

  // Then check for new data availability
  if (capture_util::maybe_update_capture_data()) {
    refresh_display();
  }
}

