    {
        Q_UNUSED(parent);
        return static_cast<int>(mEntries.size());
    }

    int GatelibraryTableModel::columnCount(const QModelIndex& parent) const
    {
        Q_UNUSED(parent);
        return 4;
    }

    QVariant GatelibraryTableModel::data(const QModelIndex& index, int role) const
    {
        if (index.row() >= mEntries.size() || index.column() >= 4)
            return QVariant();

        if (role == Qt::DisplayRole)
        {
            const Entry& entry = mEntries[index.row()];
            switch (index.column())
            {
                case 0: return entry.name;
                case 1: return entry.gatecount;
                case 2: return QString::fromStdString(entry.path.string());
                case 3: return entry.timestring;
                default: return QVariant();
            }
        }
        else if (role == Qt::TextAlignmentRole)
        {
            if (index.column() == 0 || index.column() == 2)
            {
                Qt::Alignment align;
                align |= Qt::AlignLeft;
                align |= Qt::AlignVCenter;
                return QVariant(align);
            }
            return Qt::AlignCenter;
        }
        else if (role == Qt::UserRole && index.column() == 3)
        {
            return mEntries[index.row()].timevalue;
        }

        return QVariant();
    }

    QVariant GatelibraryTableModel::headerData(int section, Qt::Orientation orientation, int role) const
    {
        if (role != Qt::DisplayRole)
            return QVariant();

        if (orientation == Qt::Horizontal)
        {
            switch (section)
            {
                case 0: return QStringLiteral("Name");
                case 1: return QStringLiteral("Gate Count");
                case 2: return QStringLiteral("Path");
                case 3: return QStringLiteral("Load Time");
                default: return QVariant();
            }
        }

        // For vertical headers: row numbers starting from 1
        return section + 1;
    }

    void GatelibraryTableModel::clear()
    {
        beginResetModel();
        mEntries.clear();
        endResetModel();
    }

    void GatelibraryTableModel::setup()
    {
        QList<Entry> tempEntries;
        auto gateLibs = gate_library_manager::get_gate_libraries();

        for (auto it = gateLibs.begin(); it != gateLibs.end(); ++it)
        {
            GateLibrary* lib = *it;
            Entry newEntry;

            newEntry.name = QString::fromStdString(lib->get_name());
            newEntry.gatecount = static_cast<u32>(lib->get_gate_types().size());
            newEntry.path = lib->get_path();
            newEntry.timestring = QStringLiteral("Program Start");
            newEntry.timevalue = 0;

            tempEntries.append(newEntry);
        }

        beginResetModel();
        mEntries = tempEntries;
        endResetModel();
    }

    QString GatelibraryTableModel::getNameFromIndex(const QModelIndex& index)
    {
        return mEntries[index.row()].name;
    }

    u32 GatelibraryTableModel::getGatecountFromIndex(const QModelIndex& index)
    {
        return mEntries[index.row()].gatecount;
    }

    void GatelibraryTableModel::loadFile(const QString& path)
    {
        std::filesystem::path filePath = path.toStdWString().c_str(); // Use wide string for compatibility
        GateLibrary* loadedLib = gate_library_manager::load(filePath, false);
        if (!loadedLib)
            return;

        int currentRowCount = rowCount(QModelIndex());

        beginInsertRows(QModelIndex(), currentRowCount, currentRowCount);

        Entry newEntry;
        newEntry.name = QString::fromStdString(loadedLib->get_name());
        newEntry.gatecount = static_cast<u32>(loadedLib->get_gate_types().size());
        newEntry.path = loadedLib->get_path();
        newEntry.timestring = QDateTime::currentDateTime().toString();
        newEntry.timevalue = QDateTime::currentDateTime().toMSecsSinceEpoch();

        mEntries.append(newEntry);
        endInsertRows();
    }

    void GatelibraryTableModel::reloadIndex(const QModelIndex& index)
    {
        int rowIndex = index.row();
        if (rowIndex >= mEntries.size())
            return;

        const Entry& entryToReload = mEntries[rowIndex];
        gate_library_manager::load(entryToReload.path, true);

        QDateTime now = QDateTime::currentDateTime();
        mEntries[rowIndex].timestring = now.toString();
        mEntries[rowIndex].timevalue = now.toMSecsSinceEpoch();

        QModelIndex topRight = createIndex(rowIndex, 3, &mEntries[rowIndex]);
        Q_EMIT dataChanged(topRight, topRight);
    }

    void GatelibraryTableModel::removeIndex(const QModelIndex& index)
    {
        int rowIndex = index.row();
        if (rowIndex >= mEntries.size())
            return;

        const Entry& entryToRemove = mEntries[rowIndex];
        gate_library_manager::remove(entryToRemove.path);

        beginRemoveRows(index.parent(), rowIndex, rowIndex);
        mEntries.removeAt(rowIndex);
        endRemoveRows();
    }
}

#include "pxt.h"
#define mbit_p8                     P0_18       //PIN 18
#define mbit_p12                    P0_20       //PIN 20
#define mbit_p13                    P0_23       //SCK
#define mbit_p14                    P0_22       //MISO
#define mbit_p15                    P0_21       //MOSI
#define mbit_p16                    P0_16       //PIN 16
#define LCD_CMD                         0
#define LCD_DAT                         1
#define LCD_TEMP                        0
#define LCD_BIAS                        3
#define LCD_VOP                         63
using namespace pxt;

namespace pins
{
    extern SPI* allocSPI();
    extern int  spiWrite(int value);
    extern void spiFrequency(int frequency);
    extern void spiFormat(int bits, int mode);
    extern void spiTransfer(Buffer command, Buffer response);
}
using namespace pins;
namespace nokialcd {
    DigitalOut LCD_CE(mbit_p12);
    DigitalOut LCD_RST(mbit_p8);
    DigitalOut LCD_DC(mbit_p16);
    static Buffer bytearray = NULL;
    static bool state = true;
    static int lcdDE = 0;

    //%
    void setState(bool s) {
        state = s;
    }

    //%
    void writeSPIByte(int b) {
        auto spi = allocSPI();
        LCD_CE = 0;
        spi->write(b);
        LCD_CE = 1;
    }

    //%
    void writeSPIBuf() {
        LCD_CE = 0;
        spiTransfer(bytearray, NULL);
        LCD_CE = 1;
    }

    //%
    void setYAddr(int y) {
        LCD_DC = LCD_CMD;
        writeSPIByte(0x40 + y);
        LCD_DC = LCD_DAT;
    }

    //%
    void setXAddr(int x) {
        LCD_DC = LCD_CMD;
        writeSPIByte(0x80 + x);
        LCD_DC = LCD_DAT;
    }

    void lcdDisplayMode(int mode) {
        lcdDE = ((mode & 2) << 1) + (mode & 1);
        LCD_DC = LCD_CMD;
        writeSPIByte(0x08 | lcdDE);
        LCD_DC = LCD_DAT;
    }

    void writeFunctionSet(int v, int h) {
        auto spi = allocSPI();
        LCD_DC = LCD_CMD;
        LCD_CE = 0;
        spi->write(0x20 | (v << 1) | (h & 1));
        LCD_CE = 1;
        LCD_DC = LCD_DAT;
    }    

    void lcdExtendedFunctions(int temp, int bias, int vop) {
        LCD_DC = LCD_CMD;
        writeSPIByte(0x21);
        writeSPIByte(0x04 | (0x03 & temp));
        writeSPIByte(0x10 | (0x07 & bias));
        writeSPIByte(0x80 | (0x7f & vop));
        writeSPIByte(0x20);
        LCD_DC = LCD_DAT;
    }

    //%
    void SPIinit() {
        LCD_CE = 1;
        lcdDE = 0;
        LCD_RST = 0;
        spiFormat(8,0);
        spiFrequency(1000000);
        wait(0.5);
        LCD_RST = 1;
        writeFunctionSet(0, 1);
        lcdExtendedFunctions(0, 3, 63);
        writeFunctionSet(0, 0);
        lcdDisplayMode(2);
        setXAddr(0);
        setYAddr(0);
        setState(true);
    }

    //%
    void writeBufToLCD() {
        setYAddr(0);
        writeSPIBuf();
    }

    //%
    Buffer initBuffer() {
        bytearray = mkBuffer(NULL,504);
        return bytearray;
    }

    //%
    void pixel(int x, int y, bool val) {
        if (x > 83 || y > 47 || (x | y) < 0) return;

        uint8_t bitMask = 1 << (y & 7);
        int index = x + 84 * (y >> 3);

        if (val) {
            bytearray->data[index] |= bitMask;
        } else {
            bytearray->data[index] &= ~bitMask;
        }
    }

    //%
    void scrollRow(int row, int dir, int step) {
        if (row < 0 || row > 5) return;

        int startIdx = row * 84;
        int endIdx = startIdx + 83;

        if (dir & 1) {
            if (dir & 2) {
                // left shift
                for (int i = startIdx; i < endIdx; i++) {
                    bytearray->data[i] = bytearray->data[i + 1];
                }
                bytearray->data[endIdx] = 0;
            } else {
                // right shift
                for (int i = endIdx; i > startIdx; i--) {
                    bytearray->data[i] = bytearray->data[i - 1];
                }
                bytearray->data[startIdx] = 0;
            }
        }
    }

    //%
    void scrollRowStep(int row, int dir, int step) {
        if (row < 0 || row > 5) return;

        int startIdx = row * 84;
        int endIdx = startIdx + 83;

        if (dir & 1) {
            if (dir & 2) {
                // left shift
                for (int i = startIdx; i < endIdx; i++) {
                    bytearray->data[i] = bytearray->data[i + 1];
                }
                bytearray->data[endIdx] = 0;
            } else {
                // right shift
                for (int i = endIdx; i > startIdx; i--) {
                    bytearray->data[i] = bytearray->data[i - 1];
                }
                bytearray->data[startIdx] = 0;
            }
        }
    }

    //%
    void vLine(int x, int y0, int y1) {
        // Ensure y0 <= y1
        if (y0 > y1) {
            int temp = y0;
            y0 = y1;
            y1 = temp;
        }

        // Bounds checking
        if (x < 0 || x > 83 || y1 < 0) return;
        if (y0 < 0) y0 = 0;
        if (y1 > 47) y1 = 47;

        uint8_t topMask = 0xff << (y0 & 7);
        int byteIndex = x + 84 * (y0 >> 3);

        if ((y0 >> 3) == (y1 >> 3)) {
            // Single byte
            uint8_t bottomMask = 0xfe << (y1 & 7);
            uint8_t combinedMask = topMask ^ bottomMask;

            if (state) bytearray->data[byteIndex] |= combinedMask;
            else bytearray->data[byteIndex] &= ~combinedMask;
        } else {
            // Multiple bytes
            if (state) bytearray->data[byteIndex] |= topMask;
            else bytearray->data[byteIndex] &= ~topMask;

            byteIndex += 84;
            int fullBytes = (y1 >> 3) - (y0 >> 3) - 1;

            if (state) {
                while (fullBytes > 0) {
                    bytearray->data[byteIndex] = 0xff;
                    fullBytes--;
                    byteIndex += 84;
                }
            } else {
                while (fullBytes > 0) {
                    bytearray->data[byteIndex] = 0x00;
                    fullBytes--;
                    byteIndex += 84;
                }
            }

            uint8_t bottomMask = (2 << (y1 & 7)) - 1;
            if (state) bytearray->data[byteIndex] |= bottomMask;
            else bytearray->data[byteIndex] &= ~bottomMask;
        }
    }

    //%
    void hLine(int x0, int x1, int y) {
        // Ensure x0 <= x1
        if (x0 > x1) {
            int temp = x0;
            x0 = x1;
            x1 = temp;
        }

        // Bounds checking
        if (y < 0 || y > 47 || x1 < 0) return;
        if (x0 < 0) x0 = 0;
        if (x1 > 83) x1 = 83;

        uint8_t bitMask = 1 << (y & 7);
        int byteIndex = x0 + 84 * (y >> 3);

        if (state) {
            for (int x = x0; x <= x1; x++, byteIndex++) {
                bytearray->data[byteIndex] |= bitMask;
            }
        } else {
            bitMask = ~bitMask;
            for (int x = x0; x <= x1; x++, byteIndex++) {
                bytearray->data[byteIndex] &= bitMask;
            }
        }
    }

    //%
    void pLine(int x0, int y0, int x1, int y1) {
        int dx = abs(x1 - x0);
        if (dx == 0) {
            vLine(x0, y0, y1);
            return;
        }

        int dy = abs(y1 - y0);
        if (dy == 0) {
            hLine(x0, x1, y0);
            return;
        }

        // Bresenham's line algorithm
        int x = x0;
        int y = y0;

        if (dx > dy) {
            // X-dominant
            if (x0 > x1) {
                int tempX = x0, tempY = y0;
                x0 = x1; y0 = y1;
                x1 = tempX; y1 = tempY;
                x = x0; y = y0;
            }

            int yStep = (y1 > y) ? 1 : -1;
            int midPoint = (x + x1) >> 1;
            int errorAccum = dy << 1;
            int errorDelta = errorAccum - dx;
            int errorDecrement = errorDelta - dx;

            pixel(x, y, state);

            while (x < x1) {
                if (errorAccum < 0 || (errorAccum == 0 && x >= midPoint)) {
                    errorAccum += errorAccum;
                } else {
                    errorAccum += errorDecrement;
                    y += yStep;
                }
                x++;
                pixel(x, y, state);
            }
        } else {
            // Y-dominant
            if (y0 > y1) {
                int tempX = x0, tempY = y0;
                x0 = x1; y0 = y1;
                x1 = tempX; y1 = tempY;
                x = x0; y = y0;
            }

            int xStep = (x1 > x) ? 1 : -1;
            int midPoint = (y + y1) >> 1;
            int errorAccum = dx << 1;
            int errorDelta = errorAccum - dy;
            int errorDecrement = errorDelta - dy;

            pixel(x, y, state);

            while (y < y1) {
                if (errorAccum < 0 || (errorAccum == 0 && y >= midPoint)) {
                    errorAccum += errorAccum;
                } else {
                    errorAccum += errorDecrement;
                    x += xStep;
                }
                y++;
                pixel(x, y, state);
            }
        }
    }

    //%
    void pBox(int x0, int y0, int x1, int y1) {
        // Normalize coordinates
        if (x1 < x0) {
            int temp = x0;
            x0 = x1;
            x1 = temp;
        }
        if (y1 < y0) {
            int temp = y0;
            y0 = y1;
            y1 = temp;
        }

        // Bounds checking
        if (x1 < 0 || y1 < 0) return;
        if (y0 < 0) y0 = 0;
        if (y1 > 47) y1 = 47;
        if (x1 > 83) x1 = 83;

        uint8_t topMask = 0xff << (y0 & 7);
        int startY = y0 >> 3;
        int endY = y1 >> 3;

        if (startY == endY) {
            // Single row
            uint8_t bottomMask = 0xfe << (y1 & 7);
            uint8_t combinedMask = topMask ^ bottomMask;
            int baseIndex = 84 * startY + x0;

            if (state) {
                for (int x = x0; x <= x1; x++, baseIndex++) {
                    bytearray->data[baseIndex] |= combinedMask;
                }
            } else {
                combinedMask = ~combinedMask;
                for (int x = x0; x <= x1; x++, baseIndex++) {
                    bytearray->data[baseIndex] &= combinedMask;
                }
            }
        } else {
            // Multiple rows
            int baseIndex = 84 * startY + x0;

            if (state) {
                for (int x = x0; x <= x1; x++) {
                    bytearray->data[x + baseIndex] |= topMask;
                }

                baseIndex += 84;
                int fullRows = endY - startY - 1;

                while (fullRows > 0) {
                    for (int x = x0; x <= x1; x++) {
                        bytearray->data[x + baseIndex] = 0xff;
                    }
                    fullRows--;
                    baseIndex += 84;
                }

                uint8_t bottomMask = (2 << (y1 & 7)) - 1;
                for (int x = x0; x <= x1; x++) {
                    bytearray->data[x + baseIndex] |= bottomMask;
                }
            } else {
                uint8_t invertedTop = ~topMask;
                for (int x = x0; x <= x1; x++) {
                    bytearray->data[x + baseIndex] &= invertedTop;
                }

                baseIndex += 84;
                int fullRows = endY - startY - 1;

                while (fullRows > 0) {
                    for (int x = x0; x <= x1; x++) {
                        bytearray->data[x + baseIndex] = 0x00;
                    }
                    fullRows--;
                    baseIndex += 84;
                }

                uint8_t invertedBottom = ~(0xfe << (y1 & 7));
                for (int x = x0; x <= x1; x++) {
                    bytearray->data[x + baseIndex] &= invertedBottom;
                }
            }
        }
    }
}

