#else
  #include <unistd.h>
#endif

#include "simdjson/simdjson.h"

// Parse JSON from buffer into ParsedJson object, optionally reallocating if needed for safety across page boundaries
WARN_UNUSED
int parse_json_document(const uint8_t* input_data, size_t data_length, ParsedJson& parsed_output, bool should_reallocate) {
    // Ensure capacity before proceeding
    if (parsed_output.bytecapacity < data_length) {
        return simdjson::CAPACITY;
    }

    bool was_buffer_reallocated = false;
    const uint8_t* working_buffer = input_data;

    if (should_reallocate) {
        // Determine system page size
        size_t page_size;
#ifdef _MSC_VER
        SYSTEM_INFO system_info{};
        GetSystemInfo(&system_info);
        page_size = static_cast<size_t>(system_info.dwPageSize);
#else
        page_size = static_cast<size_t>(sysconf(_SC_PAGESIZE));
#endif

        // Check if last byte of document crosses into next page within padding zone
        uintptr_t end_address = reinterpret_cast<uintptr_t>(input_data + data_length - 1);
        if ((end_address % page_size) < SIMDJSON_PADDING) {
            // Allocate padded buffer and copy original content
            working_buffer = static_cast<const uint8_t*>(allocate_padded_buffer(data_length));
            if (!working_buffer) {
                return simdjson::MEMALLOC;
            }
            std::memcpy(const_cast<uint8_t*>(working_buffer), input_data, data_length);
            was_buffer_reallocated = true;
        }
    }

    // Step 1: Locate structural elements in the JSON
    int parse_result = !find_structural_bits(working_buffer, data_length, parsed_output);

    // Step 2: If structure detection succeeded, proceed to parsing
    if (parse_result == 0) {
        parse_result = unified_machine(working_buffer, data_length, parsed_output);
    }

    // Cleanup: free temporary buffer if allocated
    if (was_buffer_reallocated) {
        aligned_free(const_cast<void*>(reinterpret_cast<const void*>(working_buffer)));
    }

    return parse_result;
}

// Factory function to build a ParsedJson instance from raw data
WARN_UNUSED
ParsedJson construct_parsed_json(const uint8_t* source, size_t size, bool need_reallocation) {
    ParsedJson result;
    bool success = result.allocateCapacity(size);

    if (success) {
        int status = parse_json_document(source, size, result, need_reallocation);
        success = (status == simdjson::SUCCESS);
        // Sanity check: validity flag must match success
        assert(success == result.isValid());
    } else {
        std::cerr << "Memory allocation failed during ParsedJson construction" << std::endl;
    }

    return result;
}

#include <string>
#include <vector>

class Solution {
public:
    bool isIsomorphic(std::string s, std::string t) {
        return checkMapping(s, t);
    }

private:
    bool checkMapping(const std::string& s, const std::string& t) {
        // Using arrays instead of raw arrays for clarity and safety
        std::vector<int> mappingS(256, 0);
        std::vector<int> mappingT(256, 0);
        int length = s.length();

        for (int index = 0; index < length; ++index) {
            // Check if current character mappings are inconsistent
            if (mappingS[s[index]] != mappingT[t[index]]) {
                return false;
            }

            // Store the latest position (using index+1 to avoid conflict with initial 0)
            mappingS[s[index]] = index + 1;
            mappingT[t[index]] = index + 1;
        }

        return true;
    }
};

