namespace pbrt {
    Point2f ConcentricSampleDisk(const Point2f &u) {
        // Transform uniform random numbers to [-1,1] range centered at origin
        Vector2f transformed = 2.f * u - Vector2f(1, 1);

        // Special case: point at the center maps to origin
        if (transformed.x == 0 && transformed.y == 0) 
            return Point2f(0, 0);

        // Determine radius and angle using alternative branch logic
        float radius, angle;
        if (std::abs(transformed.x) >= std::abs(transformed.y)) {
            radius = transformed.x;
            angle = PiOver4 * (transformed.y / transformed.x);
        } else {
            radius = transformed.y;
            angle = PiOver2 - PiOver4 * (transformed.x / transformed.y);
        }

        // Convert polar coordinates to Cartesian and scale by radius
        return radius * Point2f(std::cos(angle), std::sin(angle));
    }
}

