}

#include "../../head.h"
class Solution {
public:
    bool winnerSquareGame(int n) {
        std::vector<bool> canWin(n + 1, false);

        for (int stones = 1; stones <= n; stones++) {
            for (int root = 1; ; root++) {
                int removed = root * root;
                if (removed > stones) break;

                if (!canWin[stones - removed]) {
                    canWin[stones] = true;
                    break;
                }
            }
        }

        return canWin[n];
    }
};

#include "PrismPrecompiledHeader.h"
#include "SceneCamera.h"
#include "glm/gtc/matrix_transform.hpp"

namespace Prism
{
	SceneCamera::SceneCamera()
	{
		UpdateProjection();
	}

	void SceneCamera::SetOrthographic(float size, float nearClip, float farClip)
	{
		m_ProjectionType = ProjectionType::Orthographic;
		m_OrthographicSize = size;
		m_OrthographicNearClip = nearClip;
		m_OrthographicFarClip = farClip;
		UpdateProjection();
	}

	void SceneCamera::SetPerspective(float verticalFieldOfView, float nearClip, float farClip)
	{
		m_ProjectionType = ProjectionType::Perspective;
		m_PerspectiveFieldOfView = verticalFieldOfView;
		m_PerspectiveNearClip = nearClip;
		m_PerspectiveFarClip = farClip;
		UpdateProjection();
	}

	void SceneCamera::SetViewportSize(uint32_t newWidth, uint32_t newHeight)
	{
		m_AspectRatio = static_cast<float>(newWidth) / static_cast<float>(newHeight);
		UpdateProjection();
	}

	void SceneCamera::UpdateProjection()
	{
		if (m_ProjectionType == ProjectionType::Perspective)
		{
			m_ProjectionMatrix = glm::perspective(m_PerspectiveFieldOfView, m_AspectRatio, m_PerspectiveNearClip, m_PerspectiveFarClip);
		}
		else
		{
			float halfWidth = m_OrthographicSize * m_AspectRatio * 0.5f;
			float halfHeight = m_OrthographicSize * 0.5f;

			m_ProjectionMatrix = glm::ortho(-halfWidth, halfWidth, -halfHeight, halfHeight, m_OrthographicNearClip, m_OrthographicFarClip);
		}
	}
}

