namespace QMBT
{
	StackAllocator::StackAllocator(const char* debugName, Size totalSize)
		: m_Data(std::make_shared<AllocatorData>(debugName, totalSize))
		, m_HeadPtr(malloc(m_Data->TotalSize))
		, m_Offset(0)
	{
		QMBT_CORE_ASSERT(totalSize < 1_GB && totalSize > 0, "Total size of allocator cannot be more than 1 GB or less than 0");

		MemoryManager::GetInstance().Register(m_Data);
		LOG_MEMORY_INFO("Initialized {0} of size {1}", m_Data->DebugName, Utility::ToReadable(m_Data->TotalSize));
	}

	StackAllocator::~StackAllocator()
	{
		MemoryManager::GetInstance().UnRegister(m_Data);
		free(m_HeadPtr);
	}

	void* StackAllocator::Allocate(const Size size, const Size alignment)
	{
		const uintptr_t baseAddress = reinterpret_cast<uintptr_t>(m_HeadPtr);
		uintptr_t currentPos = baseAddress + m_Offset;

		Size padding = Utility::CalculatePaddingWithHeader(currentPos, alignment, sizeof(AllocationHeader));

		if (m_Offset + padding + size > m_Data->TotalSize)
		{
			LOG_MEMORY_CRITICAL("{0}: Allocation exceeded maximum size of {1}!",
								m_Data->DebugName,
								Utility::ToReadable(m_Data->TotalSize));
			return nullptr;
		}

		m_Offset += padding;
		uintptr_t alignedAddress = currentPos + padding;
		m_Offset += size;
		m_Data->UsedSize = m_Offset;

		LOG_MEMORY_INFO("{0} Allocated {1} bytes with alignment {2}", m_Data->DebugName, size, alignment);
		return reinterpret_cast<void*>(alignedAddress);
	}

	void StackAllocator::Deallocate(const Size ptr)
	{
		const Size previousOffset = m_Offset;
		uintptr_t headerLocation = ptr - sizeof(AllocationHeader);
		const AllocationHeader* header = reinterpret_cast<const AllocationHeader*>(headerLocation);

		m_Offset = static_cast<Size>(ptr - header->padding - reinterpret_cast<uintptr_t>(m_HeadPtr));
		m_Data->UsedSize = m_Offset;

		LOG_MEMORY_INFO("{0} Deallocated {1} bytes", m_Data->DebugName, Utility::ToReadable(previousOffset - m_Offset));
	}
} // namespace QMBT

#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    int n;
    cin >> n;
    vector<int> arr(n);
    for (int i = 0; i < n; ++i) {
        cin >> arr[i];
    }

    // Append first element to handle circular nature
    arr.push_back(arr[0]);

    int minDiff = numeric_limits<int>::max();
    int idx = -1;

    // Find the pair of adjacent elements with minimum absolute difference
    for (int i = 0; i < n; ++i) {
        int diff = abs(arr[i + 1] - arr[i]);
        if (diff < minDiff) {
            minDiff = diff;
            idx = i;
        }
    }

    // Output the 1-based indices of the pair
    if (idx == n - 1) {
        cout << idx + 1 << " " << 1 << endl;
    } else {
        cout << idx + 1 << " " << idx + 2 << endl;
    }

    return 0;
}

