#include <mpi.h>
#include <omp.h>
#ifdef HAS_PETSC
#include <petscksp.h>
#endif
#include "general_definitions.hpp"
#include "simulation/ompi/simulation_ompi_base.hpp"

int main(int argc, char* argv[]) {
    // Validate command-line arguments
    if (argc != 2) {
        std::cerr << "Usage:\n"
                  << "    /path/to/dgswemv2-ompi input_file\n";
        return 1;
    }

    auto start_time = std::chrono::high_resolution_clock::now();

    int thread_support_level;
    MPI_Init_thread(&argc, &argv, MPI_THREAD_MULTIPLE, &thread_support_level);

    // Check thread support when OpenMP is enabled
    if (thread_support_level != MPI_THREAD_MULTIPLE && omp_get_max_threads() > 1) {
        std::cerr << "dgswemv2 with ompi parallelization was submitted with more than \n"
                  << "1 thread per MPI rank and MPI_THREAD_MULTIPLE is not provided!\n"
                  << "Please either find an MPI implementation that supports MPI_THREAD_MULTIPLE,\n"
                  << " or resubmit the job with one thread per MPI rank and set the\n"
                  << " environment variable OMP_NUM_THREADS=1\n";
        MPI_Abort(MPI_COMM_WORLD, MPI_ERR_OTHER);
        return 1;
    }

#ifdef HAS_PETSC
    PetscInitialize(&argc, &argv, (char*)nullptr, nullptr);
#endif

    // Load simulation from input file
    std::string config_path(argv[1]);
    std::unique_ptr<OMPISimulationBase> sim_instance = OMPISimulationFactory::Create(config_path);
    sim_instance->Run();

    // Synchronize all ranks before timing
    MPI_Barrier(MPI_COMM_WORLD);

    auto end_time = std::chrono::high_resolution_clock::now();

    int world_rank;
    MPI_Comm_rank(MPI_COMM_WORLD, &world_rank);

    // Only rank 0 reports the elapsed time
    if (world_rank == 0) {
        auto duration_us = std::chrono::duration_cast<std::chrono::microseconds>(end_time - start_time);
        std::cout << "Time Elapsed (in us): " << duration_us.count() << std::endl;
    }

    // Cleanup phase
    sim_instance->Finalize();

#ifdef HAS_PETSC
    PetscFinalize();
#endif

    MPI_Finalize();
    return 0;
}

