namespace {
    static Logger logger;
}

// Custom thread class inheriting from gusc::Threads::Thread
class DerivedThread : public gusc::Threads::Thread {};

// Standalone callable function
void executeStandaloneFunction()
{
    logger << "Standalone function executed on thread: " + tidToStr(std::this_thread::get_id());
}

// Wrapper for member function calls
class MemberFunctionAdapter
{
public:
    void invokeMemberMethod()
    {
        logger << "Member method executed on thread: " + tidToStr(std::this_thread::get_id());
    }
};

// Function object (functor)
struct InvocableObject
{
    void operator()() const
    {
        logger << "Functor invoked on thread: " + tidToStr(std::this_thread::get_id());
    }
};

// Global constant lambda expression
static const auto immutableLambda = [](){
    logger << "Immutable global lambda executed on thread: " + tidToStr(std::this_thread::get_id());
};

// Mutable global lambda expression
static auto mutableLambda = [](){
    logger << "Mutable global lambda executed on thread: " + tidToStr(std::this_thread::get_id());
};

void runAllThreadScenarios()
{
    logger << "Starting Thread Scenarios";

    gusc::Threads::ThisThread mainLoop;
    gusc::Threads::Thread worker1;
    DerivedThread worker2;

    logger << "Main thread identifier: " + tidToStr(std::this_thread::get_id());

    // Execute standalone function directly and via threads
    executeStandaloneFunction();
    mainLoop.send(&executeStandaloneFunction);
    worker1.send(&executeStandaloneFunction);
    worker2.send(&executeStandaloneFunction);

    // Test member function binding
    MemberFunctionAdapter instance;
    instance.invokeMemberMethod();
    mainLoop.send(std::bind(&MemberFunctionAdapter::invokeMemberMethod, &instance));
    worker1.send(std::bind(&MemberFunctionAdapter::invokeMemberMethod, &instance));
    worker2.send(std::bind(&MemberFunctionAdapter::invokeMemberMethod, &instance));

    // Test functor (function object)
    const InvocableObject invObj;
    invObj();
    mainLoop.send(invObj);
    worker1.send(invObj);
    worker2.send(invObj);

    // Test temporary functor
    mainLoop.send(InvocableObject{});
    worker1.send(InvocableObject{});
    worker2.send(InvocableObject{});

    // Local-defined lambda
    auto localLambdaExpr = [](){
        logger << "Local lambda executed on thread: " + tidToStr(std::this_thread::get_id());
    };
    localLambdaExpr();
    mainLoop.send(localLambdaExpr);
    worker1.send(localLambdaExpr);
    worker2.send(localLambdaExpr);

    // Global lambdas
    mutableLambda();
    mainLoop.send(mutableLambda);
    worker1.send(mutableLambda);
    worker2.send(mutableLambda);

    immutableLambda();
    mainLoop.send(immutableLambda);
    worker1.send(immutableLambda);
    worker2.send(immutableLambda);

    // Anonymous lambdas passed directly to send()
    mainLoop.send([](){
        logger << "Anonymous lambda executed on thread: " + tidToStr(std::this_thread::get_id());
    });
    worker1.send([](){
        logger << "Anonymous lambda executed on thread: " + tidToStr(std::this_thread::get_id());
    });
    worker2.send([](){
        logger << "Anonymous lambda executed on thread: " + tidToStr(std::this_thread::get_id());
    });

    // Terminate main loop after all tasks are queued
    mainLoop.stop();

    // Launch all worker threads
    worker1.start();
    worker2.start();
    mainLoop.start();
}

#include <gtest/gtest.h>
#include "ocs2_sqp/MultipleShootingSolver.h"
#include <ocs2_core/initialization/DefaultInitializer.h>
#include <ocs2_oc/test/circular_kinematics.h>

// Test case: Solve using projected equality constraints (state & input)
TEST(test_circular_kinematics, solve_projected_EqConstraints) {
  // Setup optimal control problem
  ocs2::OptimalControlProblem model = ocs2::createCircularKinematicsProblem("/tmp/sqp_test_generated");

  // State initializer (zero input, zero dynamics)
  ocs2::DefaultInitializer stateInit(2);

  // Configure solver parameters
  ocs2::multiple_shooting::Settings conf;
  conf.timeStep = 0.01;
  conf.maxIterations = 20;
  conf.applyProjectionForEqualityConstraints = true;
  conf.enableFeedbackControl = true;
  conf.logStatistics = true;
  conf.logSolverBehavior = true;
  conf.verboseLineSearch = true;
  conf.parallelThreads = 1;

  // Define time and initial state
  const ocs2::scalar_t t0 = 0.0;
  const ocs2::scalar_t tf = 1.0;
  ocs2::vector_t x0(2); 
  x0 << 1.0, 0.0;  // start at radius 1 on unit circle

  const ocs2::scalar_array_t switchTimes{0.0};  // placeholder for switching times

  // Instantiate and run solver
  ocs2::MultipleShootingSolver optimizer(conf, model, stateInit);
  optimizer.solve(t0, x0, tf, switchTimes);

  // Retrieve solution trajectory
  const auto& result = optimizer.getSolution(tf);

  // Print trajectory info
  for (size_t idx = 0; idx < result.timeTrajectory.size(); ++idx) {
    std::cout << "t=" << result.timeTrajectory[idx] 
              << ", x=" << result.stateTrajectory[idx].transpose()
              << ", u=" << result.inputTrajectory[idx].transpose() << std::endl;
  }

  // Validate initial condition and time bounds
  EXPECT_TRUE(result.stateTrajectory.front().isApprox(x0));
  EXPECT_DOUBLE_EQ(result.timeTrajectory.front(), t0);
  EXPECT_DOUBLE_EQ(result.timeTrajectory.back(), tf);

  // Verify constraint satisfaction
  const auto stats = optimizer.getPerformanceIndices();
  EXPECT_LT(stats.stateEqConstraintISE, 1e-6);
  EXPECT_LT(stats.stateInputEqConstraintISE, 1e-6);

  // Validate feedback policy matches feedforward inputs
  for (size_t k = 0; k + 1 < result.timeTrajectory.size(); ++k) {
    const auto time = result.timeTrajectory[k];
    const auto& state = result.stateTrajectory[k];
    const auto& input = result.inputTrajectory[k];
    EXPECT_TRUE(input.isApprox(result.controller->computeInput(time, state)));
  }
}

// Test case: Solve without projecting equality constraints (handled in QP subproblem)
TEST(test_circular_kinematics, solve_EqConstraints_inQPSubproblem) {
  // Recreate problem setup
  ocs2::OptimalControlProblem model = ocs2::createCircularKinematicsProblem("/tmp/sqp_test_generated");
  ocs2::DefaultInitializer stateInit(2);

  // Adjust settings to disable projection
  ocs2::multiple_shooting::Settings conf;
  conf.timeStep = 0.01;
  conf.maxIterations = 20;
  conf.applyProjectionForEqualityConstraints = false;  // key difference
  conf.enableFeedbackControl = true;
  conf.logStatistics = true;
  conf.logSolverBehavior = true;
  conf.verboseLineSearch = true;

  // Same initial conditions as before
  const ocs2::scalar_t t0 = 0.0;
  const ocs2::scalar_t tf = 1.0;
  ocs2::vector_t x0(2); 
  x0 << 1.0, 0.0;

  const ocs2::scalar_array_t switchTimes{0.0};

  // Run solver with modified settings
  ocs2::MultipleShootingSolver optimizer(conf, model, stateInit);
  optimizer.solve(t0, x0, tf, switchTimes);

  // Extract and inspect solution
  const auto& result = optimizer.getSolution(tf);
  for (size_t idx = 0; idx < result.timeTrajectory.size(); ++idx) {
    std::cout << "t=" << result.timeTrajectory[idx] 
              << ", x=" << result.stateTrajectory[idx].transpose()
              << ", u=" << result.inputTrajectory[idx].transpose() << std::endl;
  }

  // Re-validate boundary conditions
  EXPECT_TRUE(result.stateTrajectory.front().isApprox(x0));
  EXPECT_DOUBLE_EQ(result.timeTrajectory.front(), t0);
  EXPECT_DOUBLE_EQ(result.timeTrajectory.back(), tf);

  // Confirm constraints still satisfied despite no explicit projection
  const auto stats = optimizer.getPerformanceIndices();
  EXPECT_LT(stats.stateEqConstraintISE, 1e-6);
  EXPECT_LT(stats.stateInputEqConstraintISE, 1e-6);

  // Ensure controller consistency across trajectory
  for (size_t k = 0; k + 1 < result.timeTrajectory.size(); ++k) {
    const auto time = result.timeTrajectory[k];
    const auto& state = result.stateTrajectory[k];
    const auto& input = result.inputTrajectory[k];
    EXPECT_TRUE(input.isApprox(result.controller->computeInput(time, state)));
  }
}

