// Custom error handler wrapper for cleaner exit-on-error semantics
struct SafeExecutor {
  std::function<void(Error)> onError;
  template <typename T>
  Expected<T> unwrap(Expected<T> &&val) {
    if (!val)
      onError(val.takeError());
    return std::move(val);
  }
};

int main(int argc, char *argv[]) {
  // Initialize LLVM infrastructure
  InitLLVM E(argc, argv);
  InitializeNativeTarget();
  InitializeNativeTargetAsmPrinter();

  cl::ParseCommandLineOptions(argc, argv, "LLJITWithLazyReexports");

  SafeExecutor safe;
  auto reportError = [](Error err) {
    errs() << "Fatal error: ";
    handleAllErrors(std::move(err), [](const ErrorInfoBase &EIB) {
      EIB.log(errs());
      errs() << "\n";
    });
    std::exit(1);
  };
  safe.onError = reportError;

  // Build LLJIT instance
  auto jitOrErr = LLJITBuilder().create();
  auto jit = safe.unwrap(std::move(jitOrErr));

  // Attach IR transformation layer to log compilation events
  jit->getIRTransformLayer().setTransform(
      [](ThreadSafeModule tsm, const MaterializationResponsibility &) {
        tsm.withModuleDo([](Module &mod) { dbgs() << "---Compiling---\n" << mod; });
        return tsm;
      });

  // Construct indirect stubs manager and lazy call-through manager
  std::unique_ptr<IndirectStubsManager> stubMgr;
  {
    auto triple = jit->getTargetTriple();
    auto builder = createLocalIndirectStubsManagerBuilder(triple);
    if (!builder)
      safe.onError(make_error<StringError>("Failed to build stub manager for " +
                                           triple.str(),
                                        inconvertibleErrorCode()));
    stubMgr = builder();
  }

  auto lctmOrErr = createLocalLazyCallThroughManager(
      jit->getTargetTriple(), jit->getExecutionSession(), 0);
  auto lctm = safe.unwrap(std::move(lctmOrErr));

  // Load example modules into JIT
  auto fooMod = parseExampleModule(FooMod, "foo-mod");
  auto barMod = parseExampleModule(BarMod, "bar-mod");
  auto mainMod = parseExampleModule(MainMod, "main-mod");

  jit->addIRModule(safe.unwrap(std::move(fooMod)));
  jit->addIRModule(safe.unwrap(std::move(barMod)));
  jit->addIRModule(safe.unwrap(std::move(mainMod)));

  // Define lazy reexports: map public symbols to internal bodies
  MangleAndInterner mangle(jit->getExecutionSession(), jit->getDataLayout());

  SymbolAliasMap aliases;
  aliases.try_emplace(mangle("foo"),
                      SymbolAliasEntry{mangle("foo_body"),
                                       JITSymbolFlags::Exported |
                                           JITSymbolFlags::Callable});
  aliases.try_emplace(mangle("bar"),
                      SymbolAliasEntry{mangle("bar_body"),
                                       JITSymbolFlags::Exported |
                                           JITSymbolFlags::Callable});

  auto defRes = jit->getMainJITDylib().define(
      lazyReexports(*lctm, *stubMgr, jit->getMainJITDylib(), std::move(aliases)));
  safe.unwrap(std::move(defRes));

  // Print session state for debugging
  dbgs() << "---Session state---\n";
  jit->getExecutionSession().dump(dbgs());
  dbgs() << "\n";

  // Resolve entry point and invoke it
  auto entrySym = jit->lookup("entry");
  auto entryPtr = (int (*)(int))safe.unwrap(entrySym).getAddress();
  int result = entryPtr(argc);

  outs() << "---Result---\n"
         << "entry(" << argc << ") = " << result << "\n";

  return 0;
}

