// Base class for client-side functional map tests
class FClientMapFunctionalTester : public FAutomationTestBase
{
public:
	FClientMapFunctionalTester(const FString& TestName, bool bIsComplex)
		: FAutomationTestBase(TestName, bIsComplex)
	{
	}

	// Extracts map info from parameters string (semicolon-separated)
	static void DecodeMapParameters(const FString& Input, FString& OutMapPath, FString& OutPackageName, FString& OutTestLabel)
	{
		TArray<FString> Tokens;
		Input.ParseIntoArray(Tokens, TEXT(";"), /*bIgnoreEmpty=*/true);
		OutMapPath = Tokens.IsValidIndex(0) ? Tokens[0] : TEXT("");
		OutPackageName = Tokens.IsValidIndex(1) ? Tokens[1] : TEXT("");
		OutTestLabel = Tokens.Num() > 2 ? Tokens[2] : TEXT("");
	}

	// Retrieves an active game/PIE world if available
	static UWorld* FindActiveGameWorld()
	{
		UWorld* FoundWorld = nullptr;
		const TIndirectArray<FWorldContext>& ContextList = GEngine->GetWorldContexts();
		for (const FWorldContext& Context : ContextList)
		{
			if ((Context.WorldType == EWorldType::PIE || Context.WorldType == EWorldType::Game) && Context.World())
			{
				FoundWorld = Context.World();
				break;
			}
		}
		return FoundWorld;
	}

	// Generates command to open map and focus actor
	virtual FString GenerateOpenCommand(const FString& Params) const override
	{
		FString MapPath, PackageName, TestLabel;
		DecodeMapParameters(Params, MapPath, PackageName, TestLabel);
		return FString::Printf(TEXT("Automate.OpenMapAndFocusActor %s %s"), *MapPath, *TestLabel);
	}

	// Returns the full path to the asset being tested
	virtual FString GetAssetIdentifier(const FString& Params) const override
	{
		FString MapPath, _, __;
		DecodeMapParameters(Params, MapPath, _, __);
		return MapPath;
	}

	// Enumerates available tests via FunctionalTestingModule
	virtual void CollectTestCases(TArray<FString>& DisplayNames, TArray<FString>& CommandStrings) const override
	{
		bool bOnlyEditorTests = !(GetTestFlags() & EAutomationTestFlags::ClientContext);
		TArray<FString> UnusedMapList;
		IFunctionalTestingModule::Get().RetrieveMapTests(bOnlyEditorTests, DisplayNames, CommandStrings, UnusedMapList);
	}

	// Executes the actual test logic
	virtual bool ExecuteTest(const FString& Parameters) override
	{
		FString MapPath, PackageName, TestLabel;
		DecodeMapParameters(Parameters, MapPath, PackageName, TestLabel);

		bool bReadyToRun = false;
		IFunctionalTestingModule::Get().SetActivationPending();

		UWorld* ActiveWorld = FindActiveGameWorld();
		if (ActiveWorld && ActiveWorld->GetMapName() == PackageName)
		{
			bReadyToRun = true;
		}
		else
		{
			bReadyToRun = AutomationOpenMap(PackageName);
		}

		if (bReadyToRun)
		{
			if (TestLabel.IsEmpty())
			{
				ADD_LATENT_AUTOMATION_COMMAND(FLaunchAllFTestsOnCurrentMap());
			}
			else
			{
				ADD_LATENT_AUTOMATION_COMMAND(FLaunchSingleFTestOnMap(TestLabel));
			}
			return true;
		}

		UE_LOG(LogExtendedFunctionalTest, Error, TEXT("Unable to launch map '%s' — possible build or compilation error."), *PackageName);
		return false;
	}
};

