#include "global.h"
#include "functions.h"

int preProcessing(int rowNum,
                  int columnNum,
                  int *threadNum,
                  int *diffPos,
                  int& matrixIniElem)
{
    int totalLaunches = rowNum + columnNum - 1;
    int currentLaunchIndex;
    int prevColumnCount, currentDiffPos, finalEndPosition;
    int threadsPerLaunch;

    int alignedBase = COALESCED_OFFSET;
    int currentStartOffset;
    int additionalOffset;

    additionalOffset = 0;
    currentStartOffset = alignedBase;
    threadsPerLaunch = 1;
    prevColumnCount = alignedBase - 1;

    for (currentLaunchIndex = 1; currentLaunchIndex < totalLaunches; currentLaunchIndex++)
    {
        if (currentLaunchIndex < rowNum)
        {
            if (currentLaunchIndex < columnNum)
            {
                threadsPerLaunch++;
                threadNum[currentLaunchIndex] = threadsPerLaunch - 2;
            }
            else
            {
                threadNum[currentLaunchIndex] = threadsPerLaunch - 1;
            }
            finalEndPosition = currentStartOffset;
        }
        else
        {
            threadsPerLaunch--;
            threadNum[currentLaunchIndex] = threadsPerLaunch;
        }

        if (currentLaunchIndex > rowNum)
        {
            additionalOffset = 1;
        }

        int tempThreads;
        if ((rowNum == columnNum) && (currentLaunchIndex == rowNum - 1))
        {
            tempThreads = ((threadsPerLaunch + alignedBase - 2) / alignedBase) * alignedBase;
        }
        else
        {
            tempThreads = ((threadsPerLaunch + alignedBase - 1) / alignedBase) * alignedBase;
        }

        currentStartOffset += tempThreads;

        if (currentLaunchIndex <= rowNum)
        {
            diffPos[currentLaunchIndex] = prevColumnCount;
        }
        else
        {
            diffPos[currentLaunchIndex] = prevColumnCount - additionalOffset;
        }

        prevColumnCount = tempThreads;
    }

    matrixIniElem = finalEndPosition + rowNum;
    return currentStartOffset;
}

float maxScore(float *scoreArray, int arraySize)
{
    float highestScore = 0.0f;
    int index;

    for (index = 0; index < arraySize; index++)
    {
        if (highestScore < scoreArray[index])
        {
            highestScore = scoreArray[index];
        }
    }

    return highestScore;
}

