#include "propconst.h"

// Token storage container for Propeller 2 language elements
class TokenRegistry {
    std::vector<std::tuple<PropToken, QString, QString>> m_entries;

public:
    void registerEntry(PropToken t, const QString& symbol, const QString& explanation) {
        m_entries.emplace_back(t, symbol, explanation);
    }

    const std::vector<std::tuple<PropToken, QString, QString>>& getEntries() const {
        return m_entries;
    }
};

// Constructor implementation for CPropToken
CPropToken::CPropToken(const PropToken tokenValue, const QString& tokenName, const QString& tokenDescription)
    : m_token(tokenValue)
    , m_name(tokenName)
    , m_desc(tokenDescription)
{
}

// Accessor methods for token properties
PropToken CPropToken::identifier() const {
    return m_token;
}

const QString& CPropToken::symbol() const {
    return m_name;
}

const QString& CPropToken::documentation() const {
    return m_desc;
}

