#include <iostream>
#include <atomic>
using namespace std;

int main() {
    // Initialize atomic integer with value 10
    atomic<int> counter{10};

    // Display initial value
    cout << counter << endl; // 10

    // Load current value into regular variable
    int temp = counter.load();
    cout << temp << endl; // 10

    // Modify local copy and store back to atomic
    temp += 10;
    counter.store(temp);
    cout << "After Store" << endl;
    cout << counter << endl; // 20
    cout << temp << endl; // 20

    // Exchange current value with new one, get old value
    temp = 100;
    int previous = counter.exchange(temp);
    cout << "temp = 100 \nAfter Exchange. . ." << endl;
    cout << counter << endl; // 100
    cout << temp << endl; // 100
    cout << previous << endl; // 20

    // Compare-and-exchange: if counter == temp, set counter = previous
    bool operationSucceeded = counter.compare_exchange_strong(temp, previous);
    /*
        Logic:
        - If counter equals temp, then counter becomes previous and returns true
        - Otherwise, temp gets updated to counter's current value and returns false
    */
    cout << "After compare_exchange_strong" << endl;
    cout << counter << endl; // 20
    cout << temp << endl; // 100 (unchanged because comparison failed)
    cout << previous << endl; // 20
    cout << operationSucceeded << endl; // 1 (true)

    return 0;
}

#include "Element.h"
#include "HyperSolveMiniApp.h"
#include "Ddata.h"

template<typename T, std::size_t NumEqns, std::size_t NCorners>
using CornerSolution = std::array<std::array<T, NumEqns>, NCorners>;

// Computes viscous flux over multiple simulated cells
template<typename T>
std::array<std::array<T, 5>, 4> SimulateCellFlux(long total_cells) {
    // Base state vector for all corners
    std::array<double, 5> base_state = {2.0, 0.25, 0.1, 0.1, 0.767};
    std::array<std::array<T, 5>, 4> solution;

    // Initialize each corner with the same base state
    for (int c = 0; c < 4; ++c) {
        for (int e = 0; e < 5; ++e) {
            solution[c][e] = base_state[e];
        }
    }

    // Define tetrahedron node coordinates
    std::array<HS::Point<double>, 4> node_coords;
    node_coords[0] = {0.0, 0.0, 0.0};
    node_coords[1] = {1.0, 0.0, 0.0};
    node_coords[2] = {0.0, 1.0, 0.0};
    node_coords[3] = {0.0, 0.0, 1.0};

    // Compute dual edge normals from geometry
    auto edge_normals = HS::Element::Tet::calcDualNormals(node_coords);

    // Gradient fields: uniform mock gradient in all directions
    T const_unit(1.0);
    HS::Point<T> grad_u = {const_unit, const_unit, const_unit};
    HS::Point<T> grad_v = grad_u;
    HS::Point<T> grad_w = grad_u;
    HS::Point<T> grad_t = grad_u;

    // Duplicate gradients per edge (6 edges for tetrahedron)
    std::array<HS::Point<T>, 6> edge_grads_u, edge_grads_v, edge_grads_w, edge_grads_t;
    edge_grads_u.fill(grad_u);
    edge_grads_v.fill(grad_v);
    edge_grads_w.fill(grad_w);
    edge_grads_t.fill(grad_t);

    // Material properties (hardcoded to avoid thermodynamics dependency)
    T viscosity(0.01);
    T conductivity(0.1);
    HS::Point<T> visc_coeffs;
    visc_coeffs[0] = 1.0;
    visc_coeffs[1] = 1.1;
    visc_coeffs[2] = 1.2;

    // Result storage
    std::array<std::array<T, 5>, 4> result_flux;

    long processed = 0;
    int progress_marker = 0;
    int percent_complete = 0;

    // Loop over all cells
    while (processed < total_cells) {
        ++processed;
        ++progress_marker;

        if (progress_marker == total_cells / 10) {
            percent_complete += 10;
            printf("[%d%%] processing cell: %ld of %ld\n", percent_complete, processed, total_cells);
            progress_marker = 0;
        }

        result_flux = HS::ElementBasedViscousFlux<4, 5>(
            HS::Element::Tet::edge_to_node,
            edge_normals,
            edge_grads_u, edge_grads_v, edge_grads_w, edge_grads_t,
            conductivity,
            viscosity,
            visc_coeffs
        );
    }

    printf("[%d%%] processing complete: %ld of %ld\n", 100, total_cells, total_cells);
    return result_flux;
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <number_of_cells>\n", argv[0]);
        return 1;
    }

    std::string input_str = argv[1];
    long num_cells;

    try {
        std::size_t end_idx;
        double parsed_val = std::stod(input_str, &end_idx);
        if (end_idx != input_str.size()) {
            std::cerr << "Error: Non-numeric suffix in input '" << input_str << "'\n";
            return 1;
        }
        if (parsed_val < 0 || parsed_val > static_cast<double>(std::numeric_limits<long>::max())) {
            throw std::out_of_range("Value out of long range");
        }
        num_cells = static_cast<long>(parsed_val);
    } catch (std::invalid_argument const&) {
        std::cerr << "Error: Invalid numeric format '" << input_str << "'\n";
        return 1;
    } catch (std::out_of_range const&) {
        std::cerr << "Error: Number too large or negative: '" << input_str << "'\n";
        return 1;
    }

    printf("Simulating %lu cells.\n", num_cells);
    printf("Right-hand side (real):\n");
    auto real_result = SimulateCellFlux<double>(num_cells);

    printf("Left-hand side (linearized DDT):\n");
    auto ddt_result = SimulateCellFlux<Linearize::Ddata<double, 5>>(num_cells);

    // Compare results element-wise
    constexpr double tolerance = 1e-15;
    for (int corner = 0; corner < 4; ++corner) {
        for (int eqn = 0; eqn < 5; ++eqn) {
            double diff = std::abs(real_result[corner][eqn] - ddt_result[corner][eqn].value);
            if (diff > tolerance) {
                fprintf(stderr, "Mismatch at [%d][%d]: %e vs %e (diff=%e)\n",
                        corner, eqn, real_result[corner][eqn], ddt_result[corner][eqn].value, diff);
                return 1;
            }
        }
    }

    printf("Verification passed.\n");
    return 0;
}

#include "stack.h"
#include <stdlib.h>
#include <assert.h>

// Push a value onto the stack
void push_stack(Stack *S, address_type val) {
   assert(S->top < S->max_size);
   S->v[S->top] = val;
   ++(S->top);
}

// Pop and return the top element from the stack
address_type pop_stack(Stack *S) {
   --(S->top);
   return S->v[S->top];
}

// Return the top element without removing it
address_type top_stack(Stack *S) {
   assert(S->top >= 1);
   return S->v[S->top - 1];
}

// Create a new stack with given size
Stack* new_stack(int size) {
   Stack* S = (Stack*)malloc(sizeof(Stack));
   S->max_size = size;
   S->top = 0;
   S->v = (address_type*)calloc(size, sizeof(address_type));
   return S;
}

// Free all memory associated with the stack
void free_stack(Stack *S) {
   free(S->v);
   free(S);
}

// Return current number of elements in the stack
int size_stack(Stack *S) {
   return S->top;
}

// Check if the stack is full
int full_stack(Stack *S) {
   return S->top == S->max_size;
}

// Check if the stack is empty
int empty_stack(Stack *S) {
   return S->top == 0;
}

// Check whether a specific value exists in the stack
int element_exist_stack(Stack *S, address_type value) {
   for (int i = 0; i < S->top; ++i) {
      if (S->v[i] == value) {
         return 1;
      }
   }
   return 0;
}

// Reset the stack to empty state
void reset_stack(Stack *S) {
   S->top = 0;
}

