namespace kaldi {

void UnitTestOnlineCmvn() {
  // Run multiple random test cases
  for (int32 test_idx = 0; test_idx < 1000; test_idx++) {
    // Generate random dimensions for test data
    int32 frame_count = 1 + (Rand() % 10 * 10);
    int32 feature_dim = 1 + Rand() % 10;

    // Configure CMN options randomly
    SlidingWindowCmnOptions cmn_opts;
    cmn_opts.center = (Rand() % 2 == 0);
    cmn_opts.normalize_variance = (Rand() % 2 == 0);
    cmn_opts.cmn_window = 5 + Rand() % 50;
    cmn_opts.min_window = 1 + Rand() % 100;

    // Ensure min_window doesn't exceed cmn_window
    if (cmn_opts.min_window > cmn_opts.cmn_window) {
      cmn_opts.min_window = cmn_opts.cmn_window;
    }

    // Create input features and two output matrices for comparison
    Matrix<BaseFloat> input_feats(frame_count, feature_dim);
    Matrix<BaseFloat> result1(frame_count, feature_dim);
    Matrix<BaseFloat> result2(frame_count, feature_dim);

    // Fill with random values
    input_feats.SetRandn();

    // Apply the optimized CMN implementation
    SlidingWindowCmn(cmn_opts, input_feats, &result1);

    // Compute expected results using direct calculation
    for (int32 t = 0; t < frame_count; t++) {
      int32 start_frame, end_frame;

      // Calculate window boundaries based on centering option
      if (cmn_opts.center) {
        start_frame = t - (cmn_opts.cmn_window / 2);
        end_frame = start_frame + cmn_opts.cmn_window;

        // Adjust window if it goes beyond boundaries
        int32 offset = 0;
        if (start_frame < 0) {
          offset = -start_frame;
        } else if (end_frame > frame_count) {
          offset = frame_count - end_frame;
        }
        start_frame += offset;
        end_frame += offset;
      } else {
        // Causal window: from (t - cmn_window) to t+1
        start_frame = t - cmn_opts.cmn_window;
        end_frame = t + 1;

        // Ensure minimum window size
        if (end_frame - start_frame < cmn_opts.min_window) {
          end_frame = start_frame + cmn_opts.min_window;
        }
      }

      // Clamp window to valid range
      if (start_frame < 0) start_frame = 0;
      if (end_frame > frame_count) end_frame = frame_count;

      int32 window_len = end_frame - start_frame;

      // Process each dimension independently
      for (int32 d = 0; d < feature_dim; d++) {
        double local_sum = 0.0;
        double local_sq_sum = 0.0;

        // Accumulate statistics over the window
        for (int32 w = start_frame; w < end_frame; w++) {
          double val = input_feats(w, d);
          local_sum += val;
          local_sq_sum += val * val;
        }

        // Compute mean and variance
        double mean_val = local_sum / window_len;
        double var_val = (local_sq_sum / window_len) - (mean_val * mean_val);
        var_val = std::max(var_val, 1.0e-20);  // Prevent underflow

        // Normalize the current frame value
        double normalized_val = input_feats(t, d) - mean_val;

        if (cmn_opts.normalize_variance) {
          if (window_len != 1) {
            normalized_val /= std::sqrt(var_val);
          } else {
            normalized_val = 0.0;
          }
        }

        result2(t, d) = normalized_val;
      }
    }

    // Verify results match within tolerance
    if (!result1.ApproxEqual(result2, 0.0001)) {
      KALDI_ERR << "CMN implementation mismatch detected!";
    }
  }
}

}  // namespace kaldi

int main() {
  using namespace kaldi;

  try {
    UnitTestOnlineCmvn();
    std::cout << "All tests passed successfully." << std::endl;
    return 0;
  } catch (const std::exception& error) {
    std::cerr << "Test failed: " << error.what() << std::endl;
    return 1;
  }
}

