    std::shared_ptr<hub_connection_impl> hub_connection_impl::create(
        const std::string& endpoint_url,
        std::unique_ptr<hub_protocol>&& protocol,
        trace_level verbosity,
        const std::shared_ptr<log_writer>& writer,
        std::function<std::shared_ptr<http_client>(const signalr_client_config&)> http_factory,
        std::function<std::shared_ptr<websocket_client>(const signalr_client_config&)> ws_factory,
        bool bypass_negotiation)
    {
        auto instance = std::shared_ptr<hub_connection_impl>(
            new hub_connection_impl(endpoint_url, std::move(protocol), verbosity, writer, http_factory, ws_factory, bypass_negotiation));
        instance->setup();
        return instance;
    }

    hub_connection_impl::hub_connection_impl(
        const std::string& endpoint_url,
        std::unique_ptr<hub_protocol>&& protocol,
        trace_level verbosity,
        const std::shared_ptr<log_writer>& writer,
        std::function<std::shared_ptr<http_client>(const signalr_client_config&)> http_factory,
        std::function<std::shared_ptr<websocket_client>(const signalr_client_config&)> ws_factory,
        bool bypass_negotiation)
        : m_connection(connection_impl::create(endpoint_url, verbosity, writer, http_factory, ws_factory, bypass_negotiation)),
          m_logger(writer, verbosity),
          m_callback_manager("connection went out of scope before invocation result was received"),
          m_handshakeReceived(false),
          m_disconnected([](std::exception_ptr) noexcept {}),
          m_protocol(std::move(protocol))
    {}

    void hub_connection_impl::setup()
    {
        std::weak_ptr<hub_connection_impl> self_weak = shared_from_this();

        m_connection->set_message_received([self_weak](std::string&& payload)
        {
            auto self = self_weak.lock();
            if (self)
            {
                self->handle_incoming_message(std::move(payload));
            }
        });

        m_connection->set_disconnected([self_weak](std::exception_ptr err)
        {
            auto self = self_weak.lock();
            if (self)
            {
                self->m_handshakeTask->set(std::make_exception_ptr(
                    signalr_exception("connection closed while handshake was in progress.")));

                try
                {
                    self->m_disconnect_cts->cancel();
                }
                catch (const std::exception& ex)
                {
                    if (self->m_logger.is_enabled(trace_level::warning))
                    {
                        self->m_logger.log(trace_level::warning,
                            std::string("disconnect event threw an exception during connection closure: ").append(ex.what()));
                    }
                }

                self->m_callback_manager.clear("connection was stopped before invocation result was received");
                self->m_disconnected(err);
            }
        });
    }

    void hub_connection_impl::on(const std::string& event_name, const std::function<void(const std::vector<signalr::value>&)>& handler)
    {
        if (event_name.empty())
        {
            throw std::invalid_argument("event_name cannot be empty");
        }

        auto self_weak = std::weak_ptr<hub_connection_impl>(shared_from_this());
        auto self = self_weak.lock();
        if (self && self->get_connection_state() != connection_state::disconnected)
        {
            throw signalr_exception("can't register a handler if the connection is in a disconnected state");
        }

        if (m_subscriptions.count(event_name) > 0)
        {
            throw signalr_exception(
                "an action for this event has already been registered. event name: " + event_name);
        }

        m_subscriptions.emplace(event_name, handler);
    }

    void hub_connection_impl::start(std::function<void(std::exception_ptr)> callback) noexcept
    {
        if (m_connection->get_connection_state() != connection_state::disconnected)
        {
            callback(std::make_exception_ptr(signalr_exception(
                "the connection can only be started if it is in the disconnected state")));
            return;
        }

        m_connection->set_client_config(m_signalr_client_config);
        m_handshakeTask = std::make_shared<completion_event>();
        m_disconnect_cts = std::make_shared<cancellation_token_source>();
        m_handshakeReceived = false;

        std::weak_ptr<hub_connection_impl> self_weak = shared_from_this();

        m_connection->start([self_weak, callback](std::exception_ptr start_err)
        {
            auto self = self_weak.lock();
            if (!self)
            {
                callback(std::make_exception_ptr(signalr_exception("the hub connection has been deconstructed")));
                return;
            }

            if (start_err)
            {
                assert(self->get_connection_state() == connection_state::disconnected);
                callback(start_err);
                return;
            }

            auto lock = std::make_shared<std::mutex>();
            auto done_flag = std::make_shared<bool>(false);

            auto handle_handshake = [self, lock, done_flag, callback](std::exception_ptr ex, bool from_send)
            {
                if (!self)
                {
                    callback(std::make_exception_ptr(signalr_exception("the hub connection has been deconstructed")));
                    return;
                }

                {
                    std::lock_guard<std::mutex> guard(*lock);
                    if (!from_send && *done_flag)
                        return;
                    *done_flag = true;
                }

                try
                {
                    if (!ex)
                    {
                        self->m_handshakeTask->get();
                        callback(nullptr);
                    }
                }
                catch (...)
                {
                    ex = std::current_exception();
                }

                if (ex)
                {
                    self->m_connection->stop([callback, ex](std::exception_ptr) { callback(ex); }, ex);
                }
            };

            auto handshake_msg = handshake::write_handshake(self->m_protocol);
            auto handshake_future = self->m_handshakeTask;
            auto timeout_duration = self->m_signalr_client_config.get_handshake_timeout();

            self->m_disconnect_cts->register_callback([handle_handshake, lock, done_flag]()
            {
                {
                    std::lock_guard<std::mutex> guard(*lock);
                    if (*done_flag)
                        return;
                }
                handle_handshake(nullptr, false);
            });

            timer(self->m_signalr_client_config.get_scheduler(),
                [handle_handshake, handshake_future, timeout_duration, lock](std::chrono::milliseconds elapsed)
                {
                    {
                        std::lock_guard<std::mutex> guard(*lock);
                        if (handshake_future->is_set())
                            return true;
                        if (elapsed < timeout_duration)
                            return false;
                    }
                    auto ex = std::make_exception_ptr(
                        signalr_exception("timed out waiting for the server to respond to the handshake message."));
                    handshake_future->set(ex);
                    handle_handshake(ex, false);
                    return true;
                });

            self->m_connection->send(handshake_msg, self->m_protocol->transfer_format(),
                [handle_handshake, done_flag, lock](std::exception_ptr ex)
                {
                    {
                        std::lock_guard<std::mutex> guard(*lock);
                        if (*done_flag)
                            return;
                        *done_flag = true;
                    }
                    handle_handshake(ex, true);
                });
        });
    }

    void hub_connection_impl::stop(std::function<void(std::exception_ptr)> callback) noexcept
    {
        if (get_connection_state() == connection_state::disconnected)
        {
            m_logger.log(trace_level::info, "Stop ignored because the connection is already disconnected.");
            callback(nullptr);
            return;
        }

        {
            std::lock_guard<std::mutex> guard(m_stop_callback_lock);
            m_stop_callbacks.push_back(callback);
            if (m_stop_callbacks.size() > 1)
            {
                m_logger.log(trace_level::info, "Stop is already in progress, waiting for it to finish.");
                return;
            }
        }

        std::weak_ptr<hub_connection_impl> self_weak = shared_from_this();
        m_connection->stop([self_weak](std::exception_ptr err)
        {
            auto self = self_weak.lock();
            if (!self)
                return;

            assert(self->get_connection_state() == connection_state::disconnected);

            std::vector<std::function<void(std::exception_ptr)>> handlers;
            {
                std::lock_guard<std::mutex> guard(self->m_stop_callback_lock);
                handlers.swap(self->m_stop_callbacks);
            }

            for (auto& cb : handlers)
            {
                cb(err);
            }
        }, nullptr);
    }

    void hub_connection_impl::handle_incoming_message(std::string&& response)
    {
        try
        {
            if (!m_handshakeReceived)
            {
                signalr::value handshake_data;
                std::tie(response, handshake_data) = handshake::parse_handshake(response);

                auto& obj = handshake_data.as_map();
                auto err_it = obj.find("error");
                if (err_it != obj.end())
                {
                    const auto& msg = err_it->second.as_string();
                    if (m_logger.is_enabled(trace_level::error))
                    {
                        m_logger.log(trace_level::error, std::string("handshake error: ").append(msg));
                    }
                    m_handshakeTask->set(std::make_exception_ptr(
                        signalr_exception(std::string("Received an error during handshake: ").append(msg))));
                    return;
                }
                else
                {
                    auto type_it = obj.find("type");
                    if (type_it != obj.end())
                    {
                        m_handshakeTask->set(std::make_exception_ptr(
                            signalr_exception("Received unexpected message while waiting for the handshake response.")));
                        return;
                    }
                    m_handshakeReceived = true;
                    m_handshakeTask->set();
                    if (response.empty())
                        return;
                }
            }

            auto messages = m_protocol->parse_messages(response);
            for (const auto& msg_ptr : messages)
            {
                switch (msg_ptr->message_type)
                {
                case message_type::invocation:
                {
                    auto* invoc = static_cast<invocation_message*>(msg_ptr.get());
                    auto handler_it = m_subscriptions.find(invoc->target);
                    if (handler_it != m_subscriptions.end())
                    {
                        handler_it->second(invoc->arguments);
                    }
                    else
                    {
                        m_logger.log(trace_level::info, "handler not found");
                    }
                    break;
                }
                case message_type::stream_invocation:
                    throw std::runtime_error("Received unexpected message type 'StreamInvocation'");
                case message_type::stream_item:
                    // TODO
                    break;
                case message_type::completion:
                {
                    auto* comp = static_cast<completion_message*>(msg_ptr.get());
                    process_completion(comp);
                    break;
                }
                case message_type::cancel_invocation:
                    throw std::runtime_error("Received unexpected message type 'CancelInvocation'.");
                case message_type::ping:
                    // TODO
                    break;
                case message_type::close:
                    // TODO
                    break;
                }
            }
        }
        catch (const std::exception& e)
        {
            if (m_logger.is_enabled(trace_level::error))
            {
                m_logger.log(trace_level::error,
                    std::string("error occurred when parsing response: ").append(e.what()).append(". response: \"").append(response).append("\""));
            }
            m_connection->stop([](std::exception_ptr) {}, std::current_exception());
        }
    }

    bool hub_connection_impl::process_completion(completion_message* completion)
    {
        const char* error_msg = nullptr;
        if (!completion->error.empty())
        {
            error_msg = completion->error.data();
        }

        if (!m_callback_manager.invoke_callback(completion->invocation_id, error_msg, completion->result, true))
        {
            if (m_logger.is_enabled(trace_level::info))
            {
                m_logger.log(trace_level::info, std::string("no callback found for id: ").append(completion->invocation_id));
            }
        }
        return true;
    }

    void hub_connection_impl::invoke(const std::string& method_name, const std::vector<signalr::value>& args, std::function<void(const signalr::value&, std::exception_ptr)> callback) noexcept
    {
        const auto& id = m_callback_manager.register_callback(
            build_invocation_handler(m_logger,
                [callback](const signalr::value& res) { callback(res, nullptr); },
                [callback](const std::exception_ptr e) { callback(signalr::value(), e); }));

        invoke_hub_method(method_name, args, id, nullptr,
            [callback](const std::exception_ptr e){ callback(signalr::value(), e); });
    }

    void hub_connection_impl::send(const std::string& method_name, const std::vector<signalr::value>& args, std::function<void(std::exception_ptr)> callback) noexcept
    {
        invoke_hub_method(method_name, args, "",
            [callback]() { callback(nullptr); },
            [callback](const std::exception_ptr e){ callback(e); });
    }

    void hub_connection_impl::invoke_hub_method(
        const std::string& method_name,
        const std::vector<signalr::value>& args,
        const std::string& callback_id,
        std::function<void()> on_sent,
        std::function<void(const std::exception_ptr)> on_fail) noexcept
    {
        try
        {
            invocation_message msg(callback_id, method_name, args);
            auto serialized = m_protocol->write_message(&msg);

            auto self_weak = std::weak_ptr<hub_connection_impl>(shared_from_this());

            m_connection->send(serialized, m_protocol->transfer_format(),
                [on_sent, on_fail, self_weak, callback_id](std::exception_ptr err)
                {
                    if (err)
                    {
                        auto self = self_weak.lock();
                        if (self)
                        {
                            self->m_callback_manager.remove_callback(callback_id);
                        }
                        on_fail(err);
                    }
                    else
                    {
                        if (callback_id.empty())
                        {
                            on_sent();
                        }
                    }
                });
        }
        catch (const std::exception& e)
        {
            m_callback_manager.remove_callback(callback_id);
            if (m_logger.is_enabled(trace_level::warning))
            {
                m_logger.log(trace_level::warning, std::string("failed to send invocation: ").append(e.what()));
            }
            on_fail(std::current_exception());
        }
    }

    connection_state hub_connection_impl::get_connection_state() const noexcept
    {
        return m_connection->get_connection_state();
    }

    std::string hub_connection_impl::get_connection_id() const
    {
        return m_connection->get_connection_id();
    }

    void hub_connection_impl::set_client_config(const signalr_client_config& cfg)
    {
        m_signalr_client_config = cfg;
        m_connection->set_client_config(cfg);
    }

    void hub_connection_impl::set_disconnected(const std::function<void(std::exception_ptr)>& handler)
    {
        m_disconnected = handler;
    }

    namespace
    {
        static std::function<void(const char*, const signalr::value&)> build_invocation_handler(
            const logger& log,
            const std::function<void(const signalr::value&)>& on_success,
            const std::function<void(const std::exception_ptr)>& on_failure)
        {
            return [on_success, on_failure](const char* error, const signalr::value& value)
            {
                if (error != nullptr)
                {
                    on_failure(std::make_exception_ptr(hub_exception(error)));
                }
                else
                {
                    on_success(value);
                }
            };
        }
    }
}

#include "Logging.h"
