namespace mms {

QTextStream* Logging::STDOUT = nullptr;

void Logging::init() {
    ASSERT_TR(STDOUT == nullptr);
    STDOUT = new QTextStream(stdout);
    qInstallMessageHandler(handler);
}

void Logging::handler(
        QtMsgType type,
        const QMessageLogContext& context,
        const QString& msg) {
    ASSERT_FA(STDOUT == nullptr);

    // Map message types to string representations
    static const QMap<QtMsgType, QString> levelMap {
        {QtDebugMsg,    "DEBUG"   },
        {QtInfoMsg,     "INFO"    },
        {QtWarningMsg,  "WARN"    },
        {QtCriticalMsg, "CRITICAL"},
        {QtFatalMsg,    "FATAL"   },
    };

    // Build formatted log line: [LEVEL][file:line] - message
    QString prefix = levelMap.value(type);
    QString location = QString("%1:%2").arg(context.file).arg(context.line);
    QString outputLine = QString("[%1][%2] - %3").arg(prefix).arg(location).arg(msg);

    *STDOUT << outputLine << endl;
}

