// Transform global integer variables into local ones within main function
void promote_globals_to_locals(CompileUnit &unit) {
    std::map<MemObject *, MemObject *> mapping;

    // Collect all single-variable global memory objects
    unit.scope.iterate([&](MemObject *obj) {
        if (obj->is_single_variable()) {
            mapping[obj] = nullptr;
        }
    });

    // Remove any globals that are referenced via LoadAddr in non-main functions
    unit.each_function([&](NormalFunc *func) {
        if (func->name != "main") {
            func->each_instruction([&](Instr *inst) {
                if (auto *load_addr = dynamic_cast<LoadAddrInstr*>(inst)) {
                    MemObject *target = load_addr->base_offset;
                    if (target->is_global()) {
                        mapping.erase(target);
                    }
                }
            });
        }
    });

    // For remaining candidates, allocate new local MemObjects in main's scope
    NormalFunc *entry_func = unit.get_function("main");
    for (auto &[global_obj, local_obj] : mapping) {
        local_obj = entry_func->scope.create_mem_object(global_obj->name);
        local_obj->set_size(4);
    }

    // Rewrite LoadAddr instructions in main to point to locals instead of globals
    entry_func->each_instruction([&](Instr *inst) {
        if (auto *load_addr = dynamic_cast<LoadAddrInstr*>(inst)) {
            MemObject *&addr_target = load_addr->base_offset;
            auto it = mapping.find(addr_target);
            if (it != mapping.end()) {
                addr_target = it->second;
            }
        }
    });

    // Insert prologue code: load address of global → load value → store to local
    auto &prologue = entry_func->entry_block->instructions;
