        prologue.push_front(new StoreInstr(tmp3, tmp2));
        prologue.push_front(new LoadAddrInstr(tmp3, local_obj));
        prologue.push_front(new LoadInstr(tmp2, tmp1));
        prologue.push_front(new LoadAddrInstr(tmp1, global_obj));
    }

