#include <vector>
#include <algorithm>

class Solution {
public:
    int maxProduct(std::vector<int>& nums) {
        if (nums.empty()) return 0;

        int currentMax = nums[0];
        int currentMin = nums[0];
        int globalMax = nums[0];

        for (int i = 1; i < nums.size(); ++i) {
            int tempMax = std::max({currentMax * nums[i], currentMin * nums[i], nums[i]});
            int tempMin = std::min({currentMax * nums[i], currentMin * nums[i], nums[i]});

            currentMax = tempMax;
            currentMin = tempMin;

            globalMax = std::max(globalMax, currentMax);
        }

        return globalMax;
    }
};

#include "EnginePrivate.h"
