#include "WNContainers/inc/WNHashMap.h"
#include "executable_test/inc/WNTestHarness.h"

// Type parameterized test fixture for hash_map functionality
template <typename _Type>
struct hash_map : ::testing::Test {};

// Define the set of types to be tested
typedef ::testing::Types<uint8_t, uint16_t, uint32_t, uint64_t>
    hash_map_testing_types;

// Instantiate typed test suite
TYPED_TEST_SUITE(hash_map, hash_map_testing_types);

// Test default construction does not allocate memory
TYPED_TEST(hash_map, construction) {
  wn::testing::allocator allocator;
  { const wn::containers::hash_map<TypeParam, TypeParam> map1(&allocator); }
  EXPECT_EQ(allocator.allocated(), 0u);
}

// Test insertion behavior: first insert succeeds, duplicate key fails
TYPED_TEST(hash_map, insert) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> map(&allocator);
    auto result = map.insert(wn::core::make_pair(TypeParam(23), TypeParam(32)));
    EXPECT_TRUE(result.second);
    EXPECT_EQ(32u, result.first->second);

    // Attempt to reinsert same key with different value
    result = map.insert(wn::core::make_pair(TypeParam(23), TypeParam(44)));
    EXPECT_FALSE(result.second);
    EXPECT_EQ(32u, result.first->second);
  }
}

// Test iteration over all elements and verify values
TYPED_TEST(hash_map, iterate) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> map(&allocator);
    for (size_t i = 0; i < 10; ++i) {
      map.insert(static_cast<TypeParam>(i), static_cast<TypeParam>(11 * i));
    }

    int expected_values[] = {0, 11, 22, 33, 44, 55, 66, 77, 88, 99};

    // Forward iteration
    for (auto it = map.begin(); it != map.end(); ++it) {
      EXPECT_EQ(it->second, static_cast<TypeParam>(expected_values[it->first]));
      expected_values[it->first] = -1;
    }

    // Verify all entries were visited
    for (size_t i = 0; i < 10; ++i) {
      EXPECT_EQ(expected_values[i], -1);
      expected_values[i] = static_cast<int>(i * 11);
    }

    // Const iteration
    for (auto it = map.cbegin(); it != map.cend(); ++it) {
      EXPECT_EQ(it->second, static_cast<TypeParam>(expected_values[it->first]));
      expected_values[it->first] = -1;
    }
  }
}

// Test find operation on existing and non-existing keys
TYPED_TEST(hash_map, find) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> map(&allocator);
    for (size_t i = 0; i < 10; ++i) {
      map.insert(static_cast<TypeParam>(i), static_cast<TypeParam>(11 * i));
    }

    for (size_t i = 0; i < 10; ++i) {
      typename wn::containers::hash_map<TypeParam, TypeParam>::iterator it =
          map.find(static_cast<TypeParam>(i));
      EXPECT_FALSE(map.end() == it);
      EXPECT_EQ(TypeParam(i), it->first);
      EXPECT_EQ(TypeParam(i * 11), it->second);
    }

    // Search for non-existent keys
    EXPECT_EQ(map.end(), map.find(static_cast<TypeParam>(32)));
    EXPECT_EQ(map.end(), map.find(static_cast<TypeParam>(10)));
  }
}

// Test find in an empty map
TYPED_TEST(hash_map, find_in_empty_map) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> map(&allocator);
    EXPECT_EQ(map.end(), map.find(static_cast<TypeParam>(10)));
  }
}

// Test erasing a specific element by iterator
TYPED_TEST(hash_map, erase) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> map(&allocator);
    for (size_t i = 0; i < 10; ++i) {
      map.insert(static_cast<TypeParam>(i), static_cast<TypeParam>(11 * i));
    }

    // Erase element at key 5
    typename wn::containers::hash_map<TypeParam, TypeParam>::iterator it =
        map.find(5);
    ASSERT_FALSE(map.end() == it);
    map.erase(it);

    // Verify remaining elements
    for (size_t i = 0; i < 10; ++i) {
      it = map.find(static_cast<TypeParam>(i));
      if (i == 5) {
        EXPECT_EQ(map.end(), it);
      } else {
        EXPECT_FALSE(map.end() == it);
        EXPECT_EQ(TypeParam(i), it->first);
        EXPECT_EQ(TypeParam(i * 11), it->second);
      }
    }

    // Check that only key 5 was removed
    int found[] = {0, 11, 22, 33, 44, 55, 66, 77, 88, 99};
    for (it = map.begin(); it != map.end(); ++it) {
      found[it->first] = -1;
    }

    int expected[] = {-1, -1, -1, -1, -1, 55, -1, -1, -1, -1};
    for (size_t i = 0; i < 10; ++i) {
      EXPECT_EQ(expected[i], found[i]);
    }
  }
}

// Test erasing all elements one-by-one
TYPED_TEST(hash_map, erase_all) {
  wn::testing::allocator allocator;
  {
    wn::containers::hash_map<TypeParam, TypeParam> map(&allocator);
    for (size_t i = 0; i < 10; ++i) {
      map.insert(static_cast<TypeParam>(i), static_cast<TypeParam>(11 * i));
    }

    typename wn::containers::hash_map<TypeParam, TypeParam>::iterator it =
        map.begin();
    while (it != map.end()) {
      it = map.erase(it);
    }

    EXPECT_EQ(TypeParam(0), map.size());
    EXPECT_EQ(map.end(), map.begin());
  }
}

