// Function type aliases for send/receive operations
using txFunction_t = std::function<cxx::expected<IpcChannelError>(const std::string&)>;
using rxFunction_t = std::function<cxx::expected<std::string, IpcChannelError>()>;

constexpr char valid_channel_name[] = "channel_test";

/// @req
/// @brief This test suite verifies the functionality which is specific to the UnixDomainSocket class
/// @pre server and client object are allocated and move to the member object of the fixture
/// @post StdErr is capture and outputed to StdCout
/// @note Most of the UnixDomainSocket functionality is tested in "IpcChannel_test"
class UnixDomainSocket_test : public Test
{
  public:
    void SetUp() override
    {
        auto srv_result = UnixDomainSocket::create(
            valid_channel_name, IpcChannelSide::SERVER, UnixDomainSocket::MAX_MESSAGE_SIZE, MaxMsgNumber);
        ASSERT_FALSE(srv_result.has_error());
        server_obj = std::move(srv_result.value());

        CaptureStderr();

        auto cli_result = UnixDomainSocket::create(
            valid_channel_name, IoxChannelSide::CLIENT, UnixDomainSocket::MAX_MESSAGE_SIZE, MaxMsgNumber);
        ASSERT_FALSE(cli_result.has_error());
        client_obj = std::move(cli_result.value());
    }

    void TearDown() override
    {
        std::string captured_output = GetCapturedStderr();
        if (Test::HasFailure())
        {
            std::cout << captured_output << std::endl;
        }
    }

    ~UnixDomainSocket_test() override = default;

    bool createTestSocket(const UnixDomainSocket::UdsName_t& socket_name)
    {
        static constexpr int32_t INVALID_SOCKET = -1;
        struct sockaddr_un local_addr;
        memset(&local_addr, 0, sizeof(local_addr));
        local_addr.sun_family = AF_LOCAL;
        strncpy(local_addr.sun_path, socket_name.c_str(), socket_name.size());

        bool success_flag = true;

        iox::posix::posixCall(iox_socket)(AF_LOCAL, SOCK_DGRAM, 0)
            .failureReturnValue(INVALID_SOCKET)
            .evaluate()
            .and_then([&](auto& sock_result) {
                iox::posix::posixCall(iox_bind)(
                    sock_result.value, reinterpret_cast<struct sockaddr*>(&local_addr), sizeof(local_addr))
                    .failureReturnValue(INVALID_SOCKET)
                    .evaluate()
                    .or_else([&](auto&) {
                        std::cerr << "socket binding failed\n";
                        success_flag = false;
                    });
            })
            .or_else([&](auto&) {
                std::cerr << "socket creation failed\n";
                success_flag = false;
            });

        return success_flag;
    }

    void notifyThreadReady()
    {
        thread_wait_flag.store(false, std::memory_order_relaxed);
    }

    void waitOnThread()
    {
        while (thread_wait_flag.load(std::memory_order_relaxed))
        {
            std::this_thread::yield();
        }
    }

    const std::chrono::milliseconds TIMEOUT_DURATION{10};
    std::atomic_bool thread_wait_flag{true};
    static constexpr uint64_t MAX_MESSAGES = 10U;
    UnixDomainSocket server_obj;
    UnixDomainSocket client_obj;
};

constexpr uint64_t UnixDomainSocket_test::MAX_MESSAGES;

// Helper function to test server-side send errors
void serverSendShouldFail(const txFunction_t& sender)
{
    cxx::string<10> test_message{"Foo"};
    auto result = sender(test_message);
    EXPECT_TRUE(result.has_error());
    EXPECT_THAT(result.get_error(), Eq(IpcChannelError::INTERNAL_LOGIC_ERROR));
}

// Helper function to test client-side receive errors  
void clientReceiveShouldFail(const rxFunction_t& receiver)
{
    auto result = receiver();
    EXPECT_TRUE(result.has_error());
    EXPECT_THAT(result.get_error(), Eq(IpcChannelError::INTERNAL_LOGIC_ERROR));
}

// Helper function to verify successful message exchange
void verifyMessageExchange(const std::string& msg_content, const txFunction_t& sender, const rxFunction_t& receiver)
{
    ASSERT_FALSE(sender(msg_content).has_error());
    auto received_data = receiver();
    ASSERT_FALSE(received_data.has_error());
    EXPECT_EQ(msg_content, *received_data);
}

