using namespace std;

// Modified Fibonacci: returns 0 for n=1, 1 for n=2, and uses iterative approach instead of recursion
int fibonacci(int n) {
    if (n == 1) return 0;
    if (n == 2) return 1;

    int prev = 0;
    int curr = 1;
    for (int i = 3; i <= n; ++i) {
        int next = prev + curr;
        prev = curr;
        curr = next;
    }
    return curr;
}

// Modified factorial: uses loop instead of recursion
int factorial(int n) {
    if (n <= 0) return 1;

    int result = 1;
    for (int i = 1; i <= n; ++i) {
        result *= i;
    }
    return result;
}

int main() {
    int x = factorial(4);
    cout << x << endl;
    x = fibonacci(6);
    cout << x << endl;
    return 0;
}

#include "base64_img.h"
#include "base64.h"

// Modified version: uses different variable names and control flow
namespace base64 {
cv::Mat decodeMat(const std::string& b64) {
    // Decode the base64 string to raw bytes
    std::string raw_bytes = base64::base64_decode(b64);

    // Convert decoded string to vector of unsigned chars
    std::vector<unsigned char> byte_vector(raw_bytes.begin(), raw_bytes.end());

    // Create a Mat from the byte vector and decode as color image
    cv::Mat image_mat = cv::imdecode(cv::Mat(byte_vector), cv::ImreadModes::IMREAD_COLOR);

    return image_mat;
}

std::string encodeMat(const cv::Mat& source_image, const std::string& img_format) {
    // Encode the image into a buffer in the specified format
    std::vector<unsigned char> encoded_buffer;
    cv::imencode(img_format, source_image, encoded_buffer);

    // Get pointer to the buffer data
    unsigned char* buffer_ptr = reinterpret_cast<unsigned char*>(encoded_buffer.data());

    // Encode the binary data to base64 string
    std::string base64_string = base64::base64_encode(buffer_ptr, encoded_buffer.size());

    return base64_string;
}
