namespace XYO {
	namespace Pixel32 {
		namespace Process {

			using namespace XYO;

			bool convert32BitTo1BitAlpha(Bmp *inputBmp, TPointer<Bmp> &outputBmp, int threshold) {
				if(inputBmp->getPixelWidth() == 32) {
					uint32_t width, height;
					width = inputBmp->getWidth();
					height = inputBmp->getHeight();

					outputBmp = Bmp::newImage1Bit(width, height);

					uint32_t x, y;
					BmpRgbQuad pixel32;
					uint8_t alphaValue;

					// Setup palette: index 0 = black, index 1 = white
					pixel32.rgbBlue = 0; pixel32.rgbGreen = 0; pixel32.rgbRed = 0; pixel32.rgbReserved = 0;
					outputBmp->setPaletteIndex(0, pixel32);
					pixel32.rgbBlue = 255; pixel32.rgbGreen = 255; pixel32.rgbRed = 255; pixel32.rgbReserved = 0;
					outputBmp->setPaletteIndex(1, pixel32);

					for(y = 0; y < height; ++y) {
						for(x = 0; x < width; ++x) {
							inputBmp->getPixel32(x, y, pixel32);
							alphaValue = pixel32.rgbReserved;
							outputBmp->setPixel1(x, y, (alphaValue < threshold) ? 1 : 0);
						}
					}

					return true;
				}
				return false;
			};

			bool split32BitTo24And8Alpha(Bmp *inputBmp, TPointer<Bmp> &rgbOutput, TPointer<Bmp> &alphaOutput) {
				if(inputBmp->getPixelWidth() == 32) {
					uint32_t width, height;
					width = inputBmp->getWidth();
					height = inputBmp->getHeight();

					rgbOutput = Bmp::newImage24Bits(width, height);
					alphaOutput = Bmp::newImage8Bits(width, height);

					uint32_t x, y;
					BmpRgbQuad pixel32;
					BmpRgbTriple rgbPixel;
					uint8_t alphaVal;

					// Copy RGB data to 24-bit image
					for(y = 0; y < height; ++y) {
						for(x = 0; x < width; ++x) {
							inputBmp->getPixel32(x, y, pixel32);
							rgbPixel.rgbtBlue = pixel32.rgbBlue;
							rgbPixel.rgbtGreen = pixel32.rgbGreen;
							rgbPixel.rgbtRed = pixel32.rgbRed;
							rgbOutput->setPixel24(x, y, rgbPixel);
						}
					}

					// Build grayscale palette for 8-bit alpha image
					for(uint8_t i = 0; i < 256; ++i) {
						pixel32.rgbBlue = pixel32.rgbGreen = pixel32.rgbRed = i;
						pixel32.rgbReserved = 0;
						alphaOutput->setPaletteIndex(i, pixel32);
					}

					// Copy alpha channel to 8-bit image
					for(y = 0; y < height; ++y) {
						for(x = 0; x < width; ++x) {
							inputBmp->getPixel32(x, y, pixel32);
							alphaVal = pixel32.rgbReserved;
							alphaOutput->setPixel8(x, y, alphaVal);
						}
					}

					return true;
				}
				return false;
			};

			bool convert32BitTo8BitWithAlpha(Bmp *inputBmp, TPointer<Bmp> &paletteOutput, TPointer<Bmp> &alphaOutput, int threshold, bool &paletteOverflow) {
				paletteOverflow = false;

				if(inputBmp->getPixelWidth() == 32) {
					uint32_t width, height;
					width = inputBmp->getWidth();
					height = inputBmp->getHeight();

					paletteOutput = Bmp::newImage8Bits(width, height);

					uint32_t x, y;
					BmpRgbQuad currentPixel;
					BmpRgbQuad paletteEntry;
					uint8_t paletteIndex;
					int usedColors = 0;

					for(y = 0; y < height; ++y) {
						for(x = 0; x < width; ++x) {
							inputBmp->getPixel32(x, y, currentPixel);

							// Search for existing color in palette
							int foundIndex = -1;
							for(int k = 0; k < usedColors; ++k) {
								paletteOutput->getPaletteIndex((uint8_t)k, paletteEntry);
								if(paletteEntry.rgbBlue == currentPixel.rgbBlue &&
								   paletteEntry.rgbGreen == currentPixel.rgbGreen &&
								   paletteEntry.rgbRed == currentPixel.rgbRed) {
									foundIndex = k;
									break;
								}
							}

							if(foundIndex >= 0) {
								paletteIndex = static_cast<uint8_t>(foundIndex);
							} else {
								if(usedColors < 256) {
									paletteIndex = static_cast<uint8_t>(usedColors);
									currentPixel.rgbReserved = 0;
									paletteOutput->setPaletteIndex(paletteIndex, currentPixel);
									++usedColors;
								} else {
									paletteOverflow = true;
									continue;
								}
							}

							paletteOutput->setPixel8(x, y, paletteIndex);
						}
					}

					return convert32BitTo1BitAlpha(inputBmp, alphaOutput, threshold);
				}

				return false;
			};

			bool convert32BitTo4BitWithAlpha(Bmp *inputBmp, TPointer<Bmp> &paletteOutput, TPointer<Bmp> &alphaOutput, int threshold, bool &paletteOverflow) {
				paletteOverflow = false;

				if(inputBmp->getPixelWidth() == 32) {
					uint32_t width, height;
					width = inputBmp->getWidth();
					height = inputBmp->getHeight();

					paletteOutput = Bmp::newImage4Bits(width, height);

					uint32_t x, y;
					BmpRgbQuad currentPixel;
					BmpRgbQuad paletteEntry;
					uint8_t paletteIndex;
					int usedColors = 0;

					for(y = 0; y < height; ++y) {
						for(x = 0; x < width; ++x) {
							inputBmp->getPixel32(x, y, currentPixel);

							// Search for existing color in palette
							int foundIndex = -1;
							for(int k = 0; k < usedColors; ++k) {
								paletteOutput->getPaletteIndex((uint8_t)k, paletteEntry);
								if(paletteEntry.rgbBlue == currentPixel.rgbBlue &&
								   paletteEntry.rgbGreen == currentPixel.rgbGreen &&
								   paletteEntry.rgbRed == currentPixel.rgbRed) {
									foundIndex = k;
									break;
								}
							}

							if(foundIndex >= 0) {
								paletteIndex = static_cast<uint8_t>(foundIndex);
							} else {
								if(usedColors < 16) {
									paletteIndex = static_cast<uint8_t>(usedColors);
									currentPixel.rgbReserved = 0;
									paletteOutput->setPaletteIndex(paletteIndex, currentPixel);
									++usedColors;
								} else {
									paletteOverflow = true;
									continue;
								}
							}

							paletteOutput->setPixel4(x, y, paletteIndex);
						}
					}

					return convert32BitTo1BitAlpha(inputBmp, alphaOutput, threshold);
				}

				return false;
			};

			TPointer<Bmp> extractAlphaAs8Bit(Image *sourceImage) {
				uint32_t width = sourceImage->width;
				uint32_t height = sourceImage->height;

				TPointer<Bmp> outputBmp = Bmp::newImage8Bits(width, height);

				// Initialize grayscale palette where each entry's reserved field matches its index
				for(int idx = 0; idx < 256; ++idx) {
					BmpRgbQuad palColor;
					palColor.rgbBlue = palColor.rgbGreen = palColor.rgbRed = 0;
					palColor.rgbReserved = static_cast<uint8_t>(idx);
					outputBmp->setPaletteIndex(idx, palColor);
				}

				for(uint32_t row = 0; row < height; ++row) {
					for(uint32_t col = 0; col < width; ++col) {
						uint8_t alphaVal = XYO_PIXEL32_A(sourceImage->pixel[height - row - 1][col]);
						outputBmp->setPixel8(col, row, alphaVal);
					}
				}

				return outputBmp;
			};

			TPointer<Bmp> extractAlphaAs1Bit(Image *sourceImage, int threshold) {
				uint32_t width = sourceImage->width;
				uint32_t height = sourceImage->height;

				TPointer<Bmp> outputBmp = Bmp::newImage1Bit(width, height);

				BmpRgbQuad black, white;
				black.rgbBlue = black.rgbGreen = black.rgbRed = black.rgbReserved = 0;
				white.rgbBlue = white.rgbGreen = white.rgbRed = 255;
				white.rgbReserved = 0;
				outputBmp->setPaletteIndex(0, black);
				outputBmp->setPaletteIndex(1, white);

				for(uint32_t row = 0; row < height; ++row) {
					for(uint32_t col = 0; col < width; ++col) {
						uint8_t alphaVal = XYO_PIXEL32_A(sourceImage->pixel[height - row - 1][col]);
						outputBmp->setPixel1(col, row, (alphaVal < threshold) ? 1 : 0);
					}
				}

				return outputBmp;
			};

			TPointer<Bmp> convertTo24Bit(Image *sourceImage) {
				uint32_t width = sourceImage->width;
				uint32_t height = sourceImage->height;

				TPointer<Bmp> outputBmp = Bmp::newImage24Bits(width, height);

				for(uint32_t row = 0; row < height; ++row) {
					for(uint32_t col = 0; col < width; ++col) {
						uint32_t pixel = sourceImage->pixel[height - row - 1][col];
						BmpRgbTriple rgb;
						rgb.rgbtRed   = XYO_PIXEL32_R(pixel);
						rgb.rgbtGreen = XYO_PIXEL32_G(pixel);
						rgb.rgbtBlue  = XYO_PIXEL32_B(pixel);
						outputBmp->setPixel24(col, row, rgb);
					}
				}

				return outputBmp;
			};

			TPointer<Bmp> convertTo32Bit(Image *sourceImage) {
				uint32_t width = sourceImage->width;
				uint32_t height = sourceImage->height;

				TPointer<Bmp> outputBmp = Bmp::newImage32Bits(width, height);

				for(uint32_t row = 0; row < height; ++row) {
					for(uint32_t col = 0; col < width; ++col) {
						uint32_t pixel = sourceImage->pixel[height - row - 1][col];
						BmpRgbQuad rgba;
						rgba.rgbRed   = XYO_PIXEL32_R(pixel);
						rgba.rgbGreen = XYO_PIXEL32_G(pixel);
						rgba.rgbBlue  = XYO_PIXEL32_B(pixel);
						rgba.rgbReserved = XYO_PIXEL32_A(pixel);
						outputBmp->setPixel32(col, row, rgba);
					}
				}

				return outputBmp;
			};

		};
	};
