    void GapVisualizer::setup(ros::NodeHandle& nh, const PotentialGapConfig& params) {
        config = &params;

        arc_pub = nh.advertise<visualization_msgs::MarkerArray>("pg_arcs", 1000);
        side_pub = nh.advertise<visualization_msgs::MarkerArray>("pg_sides", 100);
        marker_pub = nh.advertise<visualization_msgs::MarkerArray>("pg_markers", 10);

        std_msgs::ColorRGBA base_color;
        std::vector<std_msgs::ColorRGBA> raw_radial_colors;
        std::vector<std_msgs::ColorRGBA> raw_axial_colors;
        std::vector<std_msgs::ColorRGBA> final_radial_colors;
        std::vector<std_msgs::ColorRGBA> final_axial_colors;
        std::vector<std_msgs::ColorRGBA> extent_colors;
        std::vector<std_msgs::ColorRGBA> agc_colors;

        // Raw colors: lower alpha for transparency
        base_color.a = 0.5f;
        base_color.r = 0.7f; base_color.g = 0.1f; base_color.b = 0.5f;
        raw_radial_colors.push_back(base_color);
        raw_radial_colors.push_back(base_color);

        base_color.r = 0.6f; base_color.g = 0.2f; base_color.b = 0.1f;
        raw_axial_colors.push_back(base_color);
        raw_axial_colors.push_back(base_color);

        base_color.a = 1.0f;
        base_color.r = 1.0f; base_color.g = 0.9f; base_color.b = 0.3f;
        final_radial_colors.push_back(base_color);
        final_radial_colors.push_back(base_color);

        base_color.r = 0.4f; base_color.g = 0.0f; base_color.b = 0.9f;
        final_axial_colors.push_back(base_color);
        final_axial_colors.push_back(base_color);

        base_color.r = 0.0f; base_color.g = 1.0f; base_color.b = 0.0f;
        extent_colors.push_back(base_color);
        extent_colors.push_back(base_color);

        base_color.r = 1.0f; base_color.g = 0.0f; base_color.b = 0.0f;
        agc_colors.push_back(base_color);
        agc_colors.push_back(base_color);

        color_map["raw_axial"] = raw_axial_colors;
        color_map["raw_radial"] = raw_radial_colors;
        color_map["fin_radial"] = final_radial_colors;
        color_map["fin_axial"] = final_axial_colors;
        color_map["fin_extent"] = extent_colors;
        color_map["fin_agc"] = agc_colors;
    }

    void GapVisualizer::renderSegment(visualization_msgs::MarkerArray& output, Gap segment, const std::string& name_space, const std::string& /*unused*/) {
        if (!config->gap_viz.debug_viz) return;

        int jitter_offset = 0;
        double jitter_amount = config->gap_viz.viz_jitter;
        if (jitter_amount > 0 && segment.isAxial()) {
            jitter_offset = segment.isLeftType() ? -2 : 2;
        }

        int num_segments = (segment._right_idx - segment._left_idx) / config->gap_viz.min_resoln + 1;
        float distance_increment = (segment._rdist - segment._ldist) / static_cast<float>(num_segments);

        int current_left_idx = segment._left_idx + jitter_offset;
        float current_left_dist = segment._ldist;

        visualization_msgs::Marker marker;
        marker.header.frame_id = segment._frame;
        marker.header.stamp = ros::Time();
        marker.ns = name_space;
        marker.type = visualization_msgs::Marker::LINE_STRIP;
        marker.action = visualization_msgs::Marker::ADD;

        std::string local_ns = name_space;
        if (segment.isAxial()) {
            local_ns += "_axial";
        } else {
            local_ns += "_radial";
        }

        auto color_it = color_map.find(local_ns);
        if (color_it == color_map.end()) {
            ROS_FATAL_STREAM("Missing color definition for namespace: " << local_ns);
            return;
        }

        marker.colors = color_it->second;
        double line_width = config->gap_viz.fig_gen ? 0.05 : 0.01;
        marker.scale.x = line_width;
        marker.scale.y = 0.1;
        marker.scale.z = 0.1;

        bool is_final_namespace = (name_space == "fin");
        geometry_msgs::Point start_point, end_point;
        std::vector<geometry_msgs::Point> points;

        if (is_final_namespace) {
            marker.colors[0].a = 1.0;
            marker.colors[1].a = 1.0;
            start_point.z = 0.1;
            end_point.z = 0.1;
        }

        int marker_id = static_cast<int>(output.markers.size());

        for (int idx = 0; idx < num_segments - 1; ++idx) {
            points.clear();

            float angle_start = -static_cast<float>(segment.half_scan - current_left_idx) / segment.half_scan * M_PI;
            start_point.x = (current_left_dist + jitter_amount) * cos(angle_start);
            start_point.y = (current_left_dist + jitter_amount) * sin(angle_start);

            current_left_idx += config->gap_viz.min_resoln;
            current_left_dist += distance_increment;

            float angle_end = -static_cast<float>(segment.half_scan - current_left_idx) / segment.half_scan * M_PI;
            end_point.x = (current_left_dist + jitter_amount) * cos(angle_end);
            end_point.y = (current_left_dist + jitter_amount) * sin(angle_end);

            points.push_back(start_point);
            points.push_back(end_point);

            marker.points = points;
            marker.id = marker_id++;
            marker.lifetime = ros::Duration(segment.life_time);
            output.markers.push_back(marker);
        }

        // Final segment
        points.clear();
        float last_angle = -static_cast<float>(segment.half_scan - current_left_idx) / segment.half_scan * M_PI;
        start_point.x = (current_left_dist + jitter_amount) * cos(last_angle);
        start_point.y = (current_left_dist + jitter_amount) * sin(last_angle);

        float final_angle = -static_cast<float>(segment.half_scan - segment._right_idx) / segment.half_scan * M_PI;
        end_point.x = (segment._rdist + jitter_amount) * cos(final_angle);
        end_point.y = (segment._rdist + jitter_amount) * sin(final_angle);

        points.push_back(start_point);
        points.push_back(end_point);
        marker.points = points;
        marker.id = marker_id++;
        marker.lifetime = ros::Duration(segment.life_time);
        output.markers.push_back(marker);
    }

    void GapVisualizer::renderSegments(std::vector<Gap> segments, const std::string& ns, const std::string& color) {
        if (!config->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray array;
        for (auto& seg : segments) {
            renderSegment(array, seg, ns);
        }
        arc_pub.publish(array);
    }

    void GapVisualizer::renderModifiedSegment(visualization_msgs::MarkerArray& output, Gap segment, bool& circle_drawn) {
        if (!config->gap_viz.debug_viz) return;
        if (!segment.mode.reduced && !segment.mode.convex && !segment.mode.agc) {
            return;
        }

        float jitter = static_cast<float>(config->gap_viz.viz_jitter);
        int offset = 0;
        if (jitter > 0 && segment.isAxial()) {
            offset = segment.isLeftType() ? -2 : 2;
        }

        std::string ns;
        if (segment.mode.reduced) {
            ns = "fin_radial";
            jitter += 0.1f;
        } else if (segment.mode.convex) {
            ns = "fin_extent";
        } else if (segment.mode.agc) {
            ns = "fin_agc";
        }

        int count = (segment.convex.convex_ridx - segment.convex.convex_lidx) / config->gap_viz.min_resoln + 1;
        float dist_step = (segment.convex.convex_rdist - segment.convex.convex_ldist) / static_cast<float>(count);
        int left_idx = segment.convex.convex_lidx + offset;
        float left_dist = segment.convex.convex_ldist;

        visualization_msgs::Marker marker;
        marker.header.frame_id = segment._frame;
        marker.header.stamp = ros::Time();
        marker.ns = ns;
        marker.type = visualization_msgs::Marker::LINE_STRIP;
        marker.action = visualization_msgs::Marker::ADD;

        auto col_it = color_map.find(ns);
        if (col_it == color_map.end()) {
            ROS_FATAL_STREAM("[drawManipGap] Color not found for namespace: " << ns);
            return;
        }

        marker.colors = col_it->second;
        double thickness = config->gap_viz.fig_gen ? 0.05 : 0.01;
        marker.scale.x = thickness;
        marker.scale.y = 0.1;
        marker.scale.z = 0.1;

        geometry_msgs::Point p1, p2;
        p1.z = 0.1;
        p2.z = 0.1;

        std::vector<geometry_msgs::Point> pts;
        int id = static_cast<int>(output.markers.size());
        marker.lifetime = ros::Duration(0.25);

        for (int i = 0; i < count - 1; ++i) {
            pts.clear();

            float theta1 = -static_cast<float>(segment.half_scan - left_idx) / segment.half_scan * M_PI;
            p1.x = (left_dist + jitter) * cos(theta1);
            p1.y = (left_dist + jitter) * sin(theta1);

            left_idx += config->gap_viz.min_resoln;
            left_dist += dist_step;

            float theta2 = -static_cast<float>(segment.half_scan - left_idx) / segment.half_scan * M_PI;
            p2.x = (left_dist + jitter) * cos(theta2);
            p2.y = (left_dist + jitter) * sin(theta2);

            pts.push_back(p1);
            pts.push_back(p2);
            marker.points = pts;
            marker.id = id++;
            output.markers.push_back(marker);
        }

        // Last segment
        pts.clear();
        float last_theta = -static_cast<float>(segment.half_scan - left_idx) / segment.half_scan * M_PI;
        p1.x = (left_dist + jitter) * cos(last_theta);
        p1.y = (left_dist + jitter) * sin(last_theta);

        float last_seg_theta = -static_cast<float>(segment.half_scan - segment.convex.convex_ridx) / segment.half_scan * M_PI;
        p2.x = (segment.convex.convex_rdist + jitter) * cos(last_seg_theta);
        p2.y = (segment.convex.convex_rdist + jitter) * sin(last_seg_theta);

        pts.push_back(p1);
        pts.push_back(p2);
        marker.points = pts;
        marker.id = id++;
        marker.lifetime = ros::Duration(segment.life_time);
        output.markers.push_back(marker);

        if (segment.mode.convex) {
            float radius = segment.getMinSafeDist();
            if (radius < 0) {
                ROS_WARN_STREAM("Minimum safe distance not set.");
            }

            auto convex_color = color_map["fin_extent"];
            marker.ns = "fin_extent";

            if (!circle_drawn) {
                for (int k = 0; k < 50; ++k) {
                    pts.clear();
                    float angle1 = M_PI / 25.0f * static_cast<float>(k);
                    float angle2 = M_PI / 25.0f * static_cast<float>(k + 1);

                    p1.x = radius * cos(angle1);
                    p1.y = radius * sin(angle1);
                    p2.x = radius * cos(angle2);
                    p2.y = radius * sin(angle2);

                    pts.push_back(p1);
                    pts.push_back(p2);
                    marker.points = pts;
                    marker.colors = convex_color;
                    marker.id = id++;
                    marker.lifetime = ros::Duration(); // persistent
                    output.markers.push_back(marker);
                }
                circle_drawn = true;
            }

            auto drawLine = [&](int idx, float dist,
                                Eigen::Vector2f& ptB,
                                std::vector<geometry_msgs::Point>& lines,
                                geometry_msgs::Point& pA,
                                geometry_msgs::Point& pB,
                                visualization_msgs::Marker& m,
                                std::vector<std_msgs::ColorRGBA>& cols,
                                visualization_msgs::MarkerArray& arr,
                                int half_scan,
                                int marker_id) -> void {
                lines.clear();
                pA.x = ptB(0);
                pA.y = ptB(1);
                pA.z = 0.1;
                float ang = M_PI / half_scan * (idx - half_scan);
                pB.x = dist * cos(ang);
                pB.y = dist * sin(ang);
                pB.z = 0.1;
                lines.push_back(pA);
                lines.push_back(pB);
                m.points = lines;
                m.colors = cols;
                m.id = marker_id;
                m.lifetime = ros::Duration(0.2);
                arr.markers.push_back(m);
            };

            {
                marker.ns = "extent_line";
                drawLine(segment.convex.convex_lidx, segment.convex.convex_ldist, segment.qB,
                         pts, p1, p2, marker, convex_color, output, segment.half_scan, id++);
                drawLine(segment.convex.convex_ridx, segment.convex.convex_rdist, segment.qB,
                         pts, p1, p2, marker, convex_color, output, segment.half_scan, id++);

                Eigen::Vector2f origin(0.0, 0.0);
                marker.ns = "orig_line";
                drawLine(segment._left_idx, segment._ldist, origin,
                         pts, p1, p2, marker, color_map["fin_agc"], output, segment.half_scan, id++);
                drawLine(segment._right_idx, segment._rdist, origin,
                         pts, p1, p2, marker, color_map["fin_agc"], output, segment.half_scan, id++);
            }
        }
    }

    void GapVisualizer::renderModifiedSegments(std::vector<Gap> list) {
        if (!config->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray array;
        bool circle_flag = false;
        for (auto& seg : list) {
            renderModifiedSegment(array, seg, circle_flag);
        }
        side_pub.publish(array);
    }

    TrajectoryVisualizer::TrajectoryVisualizer(ros::NodeHandle& nh, const PotentialGapConfig& cfg)
    {
        config = &cfg;
        traj_goal_vis = nh.advertise<geometry_msgs::PoseArray>("goal_select_traj", 1000);
        score_vis = nh.advertise<visualization_msgs::MarkerArray>("traj_score", 1000);
        all_traj_vis = nh.advertise<visualization_msgs::MarkerArray>("all_traj_vis", 1000);
    }

    void TrajectoryVisualizer::publishGlobalPlanInRobotFrame(const std::vector<geometry_msgs::PoseStamped>& plan) {
        if (!config->gap_viz.debug_viz) return;
        if (plan.empty()) {
            ROS_WARN_STREAM("Goal Selector returned empty trajectory.");
            return;
        }

        geometry_msgs::PoseArray pose_array;
        pose_array.header = plan.front().header;
        for (const auto& ps : plan) {
            pose_array.poses.push_back(ps.pose);
        }
        traj_goal_vis.publish(pose_array);
    }

    void TrajectoryVisualizer::publishTrajectoryScores(geometry_msgs::PoseArray poses, std::vector<double> scores) {
        if (!config->gap_viz.debug_viz) return;
        ROS_FATAL_STREAM_COND(scores.size() != poses.poses.size(), 
                              "Size mismatch in publishTrajectoryScores: poses=" << poses.poses.size()
                              << ", scores=" << scores.size());

        visualization_msgs::MarkerArray arr;
        visualization_msgs::Marker text_marker;
        text_marker.header.frame_id = poses.header.frame_id;
        text_marker.header.stamp = ros::Time::now();
        text_marker.ns = "trajScore";
        text_marker.type = visualization_msgs::Marker::TEXT_VIEW_FACING;
        text_marker.action = visualization_msgs::Marker::ADD;
        text_marker.pose.orientation.w = 1.0;
        text_marker.scale.x = 0.1;
        text_marker.scale.y = 0.1;
        text_marker.scale.z = 0.1;
        text_marker.color.a = 1.0;
        text_marker.color.r = 1.0;
        text_marker.color.g = 1.0;
        text_marker.color.b = 1.0;

        for (size_t i = 0; i < scores.size(); ++i) {
            text_marker.id = static_cast<int>(arr.markers.size());
            text_marker.pose.position.x = poses.poses[i].position.x;
            text_marker.pose.position.y = poses.poses[i].position.y;
            text_marker.pose.position.z = 0.5;
            text_marker.text = std::to_string(scores[i]);
            arr.markers.push_back(text_marker);
        }
        score_vis.publish(arr);
    }

    void TrajectoryVisualizer::publishAllScores(std::vector<geometry_msgs::PoseArray> traj_list, std::vector<std::vector<double>> cost_list) {
        if (!config->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray arr;
        visualization_msgs::Marker txt;
        if (traj_list.empty()) {
            ROS_WARN_STREAM("No trajectories to visualize scores for.");
            return;
        }

        txt.header.frame_id = traj_list[0].header.frame_id;
        txt.header.stamp = ros::Time::now();
        txt.ns = "trajScore";
        txt.type = visualization_msgs::Marker::TEXT_VIEW_FACING;
        txt.action = visualization_msgs::Marker::ADD;
        txt.pose.orientation.w = 1.0;
        txt.scale.x = 0.1;
        txt.scale.y = 0.1;
        txt.scale.z = 0.05;
        txt.color.a = 1.0;
        txt.color.r = 1.0;
        txt.color.g = 1.0;
        txt.color.b = 1.0;
        txt.lifetime = ros::Duration(0.25);

        ROS_FATAL_STREAM_COND(traj_list.size() != cost_list.size(),
                              "Mismatch in trajectory and cost vector sizes.");

        for (size_t i = 0; i < traj_list.size(); ++i) {
            ROS_FATAL_STREAM_COND(traj_list[i].poses.size() != cost_list[i].size(),
                                  "Mismatch at index " << i << ": traj="
                                  << traj_list[i].poses.size() << ", cost=" << cost_list[i].size());

            for (size_t j = 0; j < traj_list[i].poses.size(); ++j) {
                txt.id = static_cast<int>(arr.markers.size());
                txt.pose = traj_list[i].poses[j];
                std::ostringstream oss;
                oss << std::fixed << std::setprecision(2) << cost_list[i][j];
                txt.text = oss.str();
                arr.markers.push_back(txt);
            }
        }
        score_vis.publish(arr);
    }

    void TrajectoryVisualizer::publishAllTrajectories(std::vector<geometry_msgs::PoseArray> trajs) {
        if (!config->gap_viz.debug_viz) return;
        visualization_msgs::MarkerArray arr;
        visualization_msgs::Marker arrow;
        if (trajs.empty()) {
            ROS_WARN_STREAM("Empty trajectory list.");
            return;
        }

        arrow.header.frame_id = trajs[0].header.frame_id;
        arrow.header.stamp = ros::Time::now();
        arrow.ns = "allTraj";
        arrow.type = visualization_msgs::Marker::ARROW;
        arrow.action = visualization_msgs::Marker::ADD;
        arrow.scale.x = 0.1;
        arrow.scale.y = config->gap_viz.fig_gen ? 0.02 : 0.01;
        arrow.scale.z = 0.1;
        arrow.color.a = 1.0;
        arrow.color.r = 0.5;
        arrow.color.g = 0.5;
        arrow.lifetime = ros::Duration(0.25);

        for (const auto& traj : trajs) {
            for (const auto& pose : traj.poses) {
                arrow.id = static_cast<int>(arr.markers.size());
                arrow.pose = pose;
                arr.markers.push_back(arrow);
            }
        }
        all_traj_vis.publish(arr);
    }

