#include "ArmCollisionDetector2018.h"
#include <PlatformInterface/Platform.h>
#include "Tools/Math/Polygon.h"
using namespace naoth;

ArmCollisionDetector2018::ArmCollisionDetector2018()
{
    getDebugParameterList().add(&params);

    const std::string& configDir = Platform::getInstance().theConfigDirectory;

    // Load left arm hull points
    {
        std::ifstream file(configDir + params.point_configLeft);
        std::vector<Vector2d> rawPoints;
        double alpha, beta;
        while (file >> alpha >> beta) {
            rawPoints.emplace_back(alpha, beta);
        }
        file.close();
        getCollisionPercept().referenceHullLeft = ConvexHull::convexHull(rawPoints);
    }

    // Load right arm hull points
    {
        std::ifstream file(configDir + params.point_configRight);
        std::vector<Vector2d> rawPoints;
        double alpha, beta;
        while (file >> alpha >> beta) {
            rawPoints.emplace_back(alpha, beta);
        }
        file.close();
        getCollisionPercept().referenceHullRight = ConvexHull::convexHull(rawPoints);
    }

    refpolyL.makeFromPointSet(getCollisionPercept().referenceHullLeft);
    refpolyR.makeFromPointSet(getCollisionPercept().referenceHullRight);
}

ArmCollisionDetector2018::~ArmCollisionDetector2018()
{
    getDebugParameterList().remove(&params);
}

void ArmCollisionDetector2018::execute()
{
    // Early exit if conditions for collision detection are not met
    const bool isUpright = getBodyState().fall_down_state == BodyState::upright;
    const bool validArmMode =
        getMotionRequest().armMotionRequest.id == ArmMotionRequest::arms_synchronised_with_walk ||
        getMotionRequest().armMotionRequest.id == ArmMotionRequest::arms_down;
    const bool validMotionMode =
        getMotionStatus().currentMotion == motion::walk ||
        getMotionStatus().currentMotion == motion::stand;

    if (!validArmMode || !validMotionMode || isUpright) {
        resetBuffers();
        return;
    }

    // Record motor positions (compensate for 4-frame delay)
    auto& motorData = getMotorJointData().position;
    jointDataBufferLeft.add(motorData[JointData::LShoulderPitch]);
    jointDataBufferRight.add(motorData[JointData::RShoulderPitch]);
    jointDataBufferLeftRoll.add(motorData[JointData::LShoulderRoll]);
    jointDataBufferRightRoll.add(motorData[JointData::RShoulderRoll]);

    const auto& sensorData = getSensorJointData().position;

    // Special handling when arms are down: use error-based threshold method
    if (getMotionRequest().armMotionRequest.id == ArmMotionRequest::arms_down) {
        processArmDownCollision(sensorData, motorData);
        return;
    }

    // Clear buffers used only in arms-down mode
    resetErrorBuffers();

    // Process shoulder roll collisions
    processRollCollision<JointData::LShoulderRoll, JointData::RShoulderRoll>(
        jointDataBufferLeftRoll, jointDataBufferRightRoll,
        collisionBufferLeftRoll, collisionBufferRightRoll,
        params.armRollError
    );

    // Polygon-based collision detection (main method)
    detectPolygonCollision<JointData::LShoulderPitch, JointData::RShoulderPitch>(
        jointDataBufferLeft, jointDataBufferRight,
        refpolyL, refpolyR,
        sensorData
    );
}

// Helper: Reset all internal buffers
void ArmCollisionDetector2018::resetBuffers()
{
    jointDataBufferLeft.clear();
    jointDataBufferRight.clear();
    collisionBufferLeft.clear();
    collisionBufferRight.clear();
    collisionBufferLeftRoll.clear();
    collisionBufferRightRoll.clear();
}

// Helper: Reset only error-related buffers (used when switching modes)
void ArmCollisionDetector2018::resetErrorBuffers()
{
    collisionBufferLeft.clear();
    collisionBufferRight.clear();
}

// Template function to handle shoulder roll collision detection
template<int LIdx, int RIdx>
void ArmCollisionDetector2018::processRollCollision(
    RingBuffer<double>& leftBuf, RingBuffer<double>& rightBuf,
    RingBuffer<double>& leftErrBuf, RingBuffer<double>& rightErrBuf,
    double threshold)
{
    auto& sensorPos = getSensorJointData().position;

    if (leftBuf.isFull()) {
        double err = leftBuf.first() - sensorPos[LIdx];
        leftErrBuf.add(err);
    }
    if (rightBuf.isFull()) {
        double err = rightBuf.first() - sensorPos[RIdx];
        rightErrBuf.add(err);
    }

    if (leftErrBuf.isFull() && std::fabs(leftErrBuf.getAverage()) > threshold) {
        getCollisionPercept().timeCollisionArmLeft = getFrameInfo().getTime();
        leftBuf.clear();
        leftErrBuf.clear();
    }

    if (rightErrBuf.isFull() && std::fabs(rightErrBuf.getAverage()) > threshold) {
        getCollisionPercept().timeCollisionArmRight = getFrameInfo().getTime();
        rightBuf.clear();
        rightErrBuf.clear();
    }
}

// Template function for polygon-based collision detection
template<int LIdx, int RIdx>
void ArmCollisionDetector2018::detectPolygonCollision(
    RingBuffer<double>& leftBuf, RingBuffer<double>& rightBuf,
    const Polygon& leftPoly, const Polygon& rightPoly,
    const double* sensorPositions)
{
    auto& frameInfo = getFrameInfo();

    if (leftBuf.isFull()) {
        double motorPos = leftBuf.first();
        double sensorPos = sensorPositions[LIdx];
        double diff = sensorPos - motorPos; // positive = front, negative = back

        if (!leftPoly.isInside(Vector2d(motorPos, diff))) {
            getCollisionPercept().lastCollisionDirection = (diff < 0) ? "Back" : "Front";
            getCollisionPercept().timeCollisionArmLeft = frameInfo.getTime();
            leftBuf.clear();
        }
    }

    if (rightBuf.isFull()) {
        double motorPos = rightBuf.first();
        double sensorPos = sensorPositions[RIdx];
        double diff = sensorPos - motorPos;

        if (!rightPoly.isInside(Vector2d(motorPos, diff))) {
            getCollisionPercept().lastCollisionDirection = (diff < 0) ? "Back" : "Front";
            getCollisionPercept().timeCollisionArmRight = frameInfo.getTime();
            rightBuf.clear();
        }
    }
}

// Specific handler for 'arms_down' mode
void ArmCollisionDetector2018::processArmDownCollision(const double* sensorPos, const double* motorPos)
{
    // Compute absolute position errors
    if (jointDataBufferLeft.isFull()) {
        double error = std::fabs(jointDataBufferLeft.first() - sensorPos[JointData::LShoulderPitch]);
        collisionBufferLeft.add(error);
    }
    if (jointDataBufferRight.isFull()) {
        double error = std::fabs(jointDataBufferRight.first() - sensorPos[JointData::RShoulderPitch]);
        collisionBufferRight.add(error);
    }

    // Check average against threshold
    if (collisionBufferLeft.isFull() && collisionBufferLeft.getAverage() > params.maxErrorStand) {
        getCollisionPercept().timeCollisionArmLeft = getFrameInfo().getTime();
        jointDataBufferLeft.clear();
        collisionBufferLeft.clear();
    }

    if (collisionBufferRight.isFull() && collisionBufferRight.getAverage() > params.maxErrorStand) {
        getCollisionPercept().timeCollisionArmRight = getFrameInfo().getTime();
        jointDataBufferRight.clear();
        collisionBufferRight.clear();
    }
}

#include "singlerole.h"
#include <QVariant>

/*!
    \qmltype SingleRole
    \qmlabstract
    \inherits ProxyRole
    \inqmlmodule SortFilterProxyModel
    \ingroup ProxyRoles
    \brief Base type for the \l SortFilterProxyModel proxy roles defining a single role.
    SingleRole serves as a foundational class for proxy roles that expose just one data role.
    It is not intended for direct instantiation in QML code.
    This class centralizes shared functionality—including property accessors and helper methods—
    among all derived proxy role implementations.
    Direct usage of this class in QML will trigger a runtime error.
*/
/*!
    \qmlproperty string SingleRole::name
    Holds the identifier string associated with the role.
*/
QString SingleRole::name() const
{
    return m_roleName;
}

void SingleRole::setName(const QString& newName)
{
    if (m_roleName == newName)
        return;

    Q_EMIT aboutToChangeNames();
    m_roleName = newName;
    Q_EMIT nameChanged();
    Q_EMIT namesUpdated();
}

QStringList SingleRole::names()
{
    return QStringList { m_roleName };
}

QVariant SingleRole::data(const QModelIndex &sourceIndex, const QQmlSortFilterProxyModel &proxyModel, const QString &roleName)
{
    Q_UNUSED(roleName);
    return data(sourceIndex, proxyModel);
}

