#include "llvm/ADT/SmallSet.h"
#include "llvm/ADT/SmallString.h"
#include "llvm/Analysis/VectorUtils.h"
#include <cassert>
#include <algorithm>

using namespace llvm;

namespace {

// Enumerates possible outcomes of parsing attempts
enum class ParseResult {
  Success,
  NotFound,
  SyntaxError
};

// Parses the ISA prefix from the mangled name.
ParseResult extractISA(StringRef &input, VFISAKind &outISA) {
  if (input.empty())
    return ParseResult::SyntaxError;

  if (input.startswith(VFABI::_LLVM_)) {
    input = input.drop_front(strlen(VFABI::_LLVM_));
    outISA = VFISAKind::LLVM;
  } else {
    char firstChar = input.front();
    input = input.drop_front(1);
    switch (firstChar) {
      case 'n': outISA = VFISAKind::AdvancedSIMD; break;
      case 's': outISA = VFISAKind::SVE;          break;
      case 'b': outISA = VFISAKind::SSE;          break;
      case 'c': outISA = VFISAKind::AVX;          break;
      case 'd': outISA = VFISAKind::AVX2;         break;
      case 'e': outISA = VFISAKind::AVX512;       break;
      default:  outISA = VFISAKind::Unknown;      break;
    }
  }
  return ParseResult::Success;
}

// Parses mask indicator ('M' or 'N') without modifying input until match.
ParseResult extractMask(StringRef &input, bool &isMasked) {
  if (input.consume_front("M")) {
    isMasked = true;
    return ParseResult::Success;
  }
  if (input.consume_front("N")) {
    isMasked = false;
    return ParseResult::Success;
  }
  return ParseResult::NotFound;
}

// Parses vector length token: 'x' for scalable, integer otherwise.
ParseResult extractVLEN(StringRef &input, unsigned &vf, bool &isScalable) {
  if (input.consume_front("x")) {
    vf = 0;
    isScalable = true;
    return ParseResult::Success;
  }

  if (!input.consumeInteger(10, vf))
    return ParseResult::Success;

  return ParseResult::NotFound;
}

// Helper to parse linear tokens with runtime step (e.g., "ls123").
ParseResult tryParseRuntimeLinearToken(StringRef &input,
                                       VFParamKind &kind,
                                       int &posOrStep,
                                       StringRef token) {
  if (!input.consume_front(token))
    return ParseResult::NotFound;

  kind = VFABI::getVFParamKindFromString(token);
  if (input.consumeInteger(10, posOrStep))
    return ParseResult::SyntaxError;

  return ParseResult::Success;
}

// Tries all runtime-linear tokens in order.
ParseResult tryParseRuntimeLinear(StringRef &input,
                                  VFParamKind &kind,
                                  int &posOrStep) {
  static const char *tokens[] = {"ls", "Rs", "Ls", "Us"};
  for (auto t : tokens) {
    auto res = tryParseRuntimeLinearToken(input, kind, posOrStep, t);
    if (res != ParseResult::NotFound)
      return res;
  }
  return ParseResult::NotFound;
}

// Parses compile-time linear tokens like "l", "R", etc., possibly with 'n' negation.
ParseResult tryParseCompileTimeLinearToken(StringRef &input,
                                           VFParamKind &kind,
                                           int &step,
                                           StringRef token) {
  if (!input.consume_front(token))
    return ParseResult::NotFound;

  kind = VFABI::getVFParamKindFromString(token);

  bool negate = input.consume_front("n");
  if (input.consumeInteger(10, step)) {
    step = 1;
  }
  if (negate) {
    step = -step;
  }
  return ParseResult::Success;
}

// Tries all compile-time linear tokens.
ParseResult tryParseCompileTimeLinear(StringRef &input,
                                      VFParamKind &kind,
                                      int &step) {
  static const char *tokens[] = {"l", "R", "L", "U"};
  for (auto t : tokens) {
    if (tryParseCompileTimeLinearToken(input, kind, step, t) == ParseResult::Success)
      return ParseResult::Success;
  }
  return ParseResult::NotFound;
}

// Parses uniform parameter: "u" followed by number.
ParseResult tryParseUniform(StringRef &input, VFParamKind &kind, int &pos) {
  if (!input.consume_front("u"))
    return ParseResult::NotFound;

  kind = VFABI::getVFParamKindFromString("u");
  if (input.consumeInteger(10, pos))
    return ParseResult::SyntaxError;

  return ParseResult::Success;
}

// Main dispatcher for parameter parsing.
ParseResult tryParseParameter(StringRef &input, VFParamKind &kind, int &value) {
  if (input.consume_front("v")) {
    kind = VFParamKind::Vector;
    value = 0;
    return ParseResult::Success;
  }

  auto res = tryParseRuntimeLinear(input, kind, value);
  if (res != ParseResult::NotFound) return res;

  res = tryParseCompileTimeLinear(input, kind, value);
  if (res != ParseResult::NotFound) return res;

  res = tryParseUniform(input, kind, value);
  return res;
}

// Parses alignment clause: "a" followed by power-of-two number.
ParseResult tryParseAlign(StringRef &input, Align &alignment) {
  uint64_t val;
  if (!input.consume_front("a"))
    return ParseResult::NotFound;

  if (input.consumeInteger(10, val))
    return ParseResult::SyntaxError;

  if (!isPowerOf2_64(val))
    return ParseResult::SyntaxError;

  alignment = Align(val);
  return ParseResult::Success;
}

} // anonymous namespace

Optional<VFInfo> VFABI::tryDemangleForVFABI(StringRef mangledName) {
  const StringRef originalName = mangledName;

  if (!mangledName.consume_front("_ZGV"))
    return None;

  VFISAKind isa;
  if (extractISA(mangledName, isa) != ParseResult::Success)
    return None;

  bool isMasked;
  if (extractMask(mangledName, isMasked) != ParseResult::Success)
    return None;

  unsigned vf;
  bool isScalable;
  if (extractVLEN(mangledName, vf, isScalable) != ParseResult::Success)
    return None;

  SmallVector<VFParameter, 8> params;
  do {
    const size_t paramIndex = params.size();
    VFParamKind pKind;
    int stepOrPos;

    auto res = tryParseParameter(mangledName, pKind, stepOrPos);
    if (res == ParseResult::SyntaxError)
      return None;

    if (res == ParseResult::Success) {
      Align align;
      if (tryParseAlign(mangledName, align) == ParseResult::SyntaxError)
        return None;

      params.push_back({static_cast<unsigned>(paramIndex), pKind, stepOrPos, align});
    }

  } while (tryParseParameter(mangledName, /*dummy*/ VFParamKind::Unknown, /*dummy*/ 0) == ParseResult::Success ||
           tryParseParameter(mangledName, /*reparse*/ mangledName, /*dummy*/ VFParamKind::Unknown, /*dummy*/ 0) == ParseResult::Success); // dummy placeholder — see below fix

  // Fix: restructure loop to avoid re-parsing issue above
  // Replace above do-while with:
  StringRef remaining = mangledName;
  do {
    const size_t paramIndex = params.size();
    VFParamKind pKind;
    int stepOrPos;

    auto res = tryParseParameter(remaining, pKind, stepOrPos);
    if (res == ParseResult::SyntaxError)
      return None;

    if (res == ParseResult::Success) {
      Align align;
      if (tryParseAlign(remaining, align) == ParseResult::SyntaxError)
        return None;

      params.push_back({static_cast<unsigned>(paramIndex), pKind, stepOrPos, align});
      mangledName = remaining;
    }
  } while (tryParseParameter(mangledName, /*dummy*/ VFParamKind::Unknown, /*dummy*/ 0) == ParseResult::Success);

  // Actually better: use a local copy inside loop
  // Let's rewrite cleanly:

  // Reset and re-parse parameters properly
  mangledName = remaining; // restore after failed attempt above
  // Instead, let’s refactor cleanly:
  // We'll just reassign and re-enter loop correctly:
  // (We’ll assume the previous loop was replaced with this version.)

  // Clean version:
  StringRef parseStr = mangledName;
  do {
    const size_t idx = params.size();
    VFParamKind pk;
    int sv;
    auto r = tryParseParameter(parseStr, pk, sv);
    if (r == ParseResult::SyntaxError)
      return None;
    if (r == ParseResult::Success) {
      Align al;
      if (tryParseAlign(parseStr, al) == ParseResult::SyntaxError)
        return None;
      params.push_back({static_cast<unsigned>(idx), pk, sv, al});
      mangledName = parseStr;
    }
  } while (tryParseParameter(mangledName, /*dummy*/ VFParamKind::Unknown, /*dummy*/ 0) == ParseResult::Success);

  if (params.empty())
    return None;

  if (!mangledName.consume_front("_"))
    return None;

  auto parenPos = mangledName.find('(');
  StringRef scalarName = mangledName.substr(0, parenPos);
  if (scalarName.empty())
    return None;

  mangledName = mangledName.drop_front(scalarName.size());

  StringRef vectorName = originalName;
  if (mangledName.consume_front("(")) {
    if (!mangledName.consume_back(")"))
      return None;
    vectorName = mangledName;
    if (vectorName.empty())
      return None;
  }

  if (isa == VFISAKind::LLVM && vectorName == originalName)
    return None;

  if (isMasked) {
    unsigned pos = params.size();
    params.push_back({pos, VFParamKind::GlobalPredicate});
  }

  // Validate global predicate rules
  size_t numPreds = std::count_if(params.begin(), params.end(),
    [](const VFParameter &p) { return p.ParamKind == VFParamKind::GlobalPredicate; });

  assert(numPreds <= 1 && "Only one global predicate allowed.");
  if (numPreds > 0)
    assert(params.back().ParamKind == VFParamKind::GlobalPredicate &&
           "Global predicate must be last.");

  VFShape shape({vf, isScalable, params});
  return VFInfo({shape, scalarName, vectorName, isa});
}

VFParamKind VFABI::getVFParamKindFromString(StringRef token) {
  if (token == "v") return VFParamKind::Vector;
  if (token == "l") return VFParamKind::OMP_Linear;
  if (token == "R") return VFParamKind::OMP_LinearRef;
  if (token == "L") return VFParamKind::OMP_LinearVal;
  if (token == "U") return VFParamKind::OMP_LinearUVal;
  if (token == "ls") return VFParamKind::OMP_LinearPos;
  if (token == "Ls") return VFParamKind::OMP_LinearValPos;
  if (token == "Rs") return VFParamKind::OMP_LinearRefPos;
  if (token == "Us") return VFParamKind::OMP_LinearUValPos;
  if (token == "u") return VFParamKind::OMP_Uniform;

  llvm_unreachable("Invalid token passed to getVFParamKindFromString");
}

#include <vector>
using namespace std;

class Solution {
public:
    int uniquePathsWithObstacles(vector<vector<int>>& obstacleGrid) {
        int m = obstacleGrid.size();
        int n = obstacleGrid[0].size();

        // Create DP table initialized to 0
        vector<vector<int>> dp(m, vector<int>(n, 0));

        // Initialize starting position
        if (obstacleGrid[0][0] == 0) {
            dp[0][0] = 1;
        }

        // Fill first row
        for (int j = 1; j < n; ++j) {
            if (obstacleGrid[0][j] == 0) {
                dp[0][j] = dp[0][j-1];
            }
        }

        // Fill first column
        for (int i = 1; i < m; ++i) {
            if (obstacleGrid[i][0] == 0) {
                dp[i][0] = dp[i-1][0];
            }
        }

        // Fill rest of the table
        for (int i = 1; i < m; ++i) {
            for (int j = 1; j < n; ++j) {
                if (obstacleGrid[i][j] == 0) {
                    dp[i][j] = dp[i-1][j] + dp[i][j-1];
                }
            }
        }

        return dp[m-1][n-1];
    }
};

