    struct ReplicaInfo
    {
        ReplicaInfo() : IsReplicaUp(true) {}
        int64 ReplicaIdentifier;
        int64 InstanceIdentifier;
        Reliability::ReplicaStates::Enum CurrentState;
        bool IsReplicaUp;
    };
}

namespace Reliability
{
    namespace ReconfigurationAgentComponent
    {
        namespace ReliabilityUnitTest
        {
            namespace StateManagement
            {
                template<>
                struct ReaderImpl<ReplicaInfo>
                {
                    static bool Read(std::wstring const & input, ReadOption::Enum option, ReadContext const & context, ReplicaInfo & result)
                    {
                        ErrorLogger logger(L"ReplicaInfo", input);
                        Reader reader(input, context);
                        result = ReplicaInfo();

                        if (!reader.Read<Reliability::ReplicaStates::Enum>(L' ', result.CurrentState))
                        {
                            logger.Log(L"State");
                            return false;
                        }

                        if (!reader.Read<int64>(L':', result.ReplicaIdentifier))
                        {
                            logger.Log(L"ReplicaId");
                            return false;
                        }

                        if (!reader.Read<int64>(L' ', result.InstanceIdentifier))
                        {
                            logger.Log(L"ReplicaInstanceId");
                            return false;
                        }

                        if (!reader.IsEOF)
                        {
                            if (!reader.Read<bool>(L' ', result.IsReplicaUp))
                            {
                                logger.Log(L"IsUp");
                                return false;
                            }
                        }

                        return true;
                    }
                };
            }
        }
    }
