class TestStateMachine_ReplicaUpReply_V2 : public StateMachineTestBase
{
protected:
    void SetupDroppedReplicaPendingFT()
    {
        Test.AddFT(FT, L"C None 000/000/411 1:2 G");
    }

    void SetupUpReplicaPendingFT()
    {
        Test.AddFT(FT, L"O None 000/000/411 1:1 CMK [N/N/P SB U N F 1:1]");
    }

    void SetupClosedDownPending(wstring const & ftName)
    {
        AddFT(ftName, L"C None 000/000/411 1:1 I");
    }

    void SetupDownDownPending(wstring const & ftName)
    {
        AddFT(ftName, L"O None 000/000/411 1:1 1 I [N/N/P SB D N F 1:1]");
    }

    void SetupReopeningDownPending(wstring const & ftName)
    {
        AddFT(ftName, L"O None 000/000/411 1:2 1 IS [N/N/P SB U N F 1:2]");
    }

    void AddFT(wstring const & ftName, wstring const & state)
    {
        Test.AddFT(ftName, state);
    }

    void ExecuteFMMessage(wstring const & message)
    {
        Test.ProcessFMMessageAndDrain<MessageType::ReplicaUpReply>(message);
    }

    CommitTypeDescriptionUtility HandleReplicaOnFT(wstring const & replicaDesc)
    {
        return HandleReplicaOnFT(FT, replicaDesc);
    }

    CommitTypeDescriptionUtility HandleReplicaOnFT(wstring const & ftShortName, wstring const & replicaDesc)
    {
        auto & ft = Test.GetFT(ftShortName);
        auto info = Reader::ReadHelper<ReplicaInfo>(replicaDesc);
        ReplicaDescription desc;
        desc.ReplicaId = info.ReplicaIdentifier;
        desc.InstanceId = info.InstanceIdentifier;
        desc.State = info.CurrentState;
        desc.IsUp = info.IsReplicaUp;

        return Test.EntityExecutionContextTestUtilityObj.ExecuteEntityProcessor(
            ftShortName,
            [&](Infrastructure::EntityExecutionContext& base)
        {
            auto & context = base.As<FailoverUnitEntityExecutionContext>();
            ft.ProcessReplicaUpReply(desc, context);
        });
    }

    void ConfirmDroppedPending()
    {
        Confirm(FMMessageStage::ReplicaDropped);
    }

    void ConfirmCleared()
    {
        Confirm(FMMessageStage::None);
    }

    void ConfirmCleared(wstring const & ftName)
    {
        Confirm(ftName, FMMessageStage::None);
    }

    void Confirm(FMMessageStage::Enum expected)
    {
        Confirm(FT, expected);
    }

    void Confirm(wstring const & ftShortName, FMMessageStage::Enum expected)
    {
        auto & ft = Test.GetFT(ftShortName);
        Verify::AreEqual(expected, ft.FMMessageStage, L"FMMessageStage");
    }

    void RunTestCase(bool isNodeActive, wstring const & testCaseName, wstring const & shortName, wstring const & initialState, wstring const & msg, wstring const & expectedFinalState)
    {
        Recreate();
        Test.SetNodeActivationState(isNodeActive, 10);
        Test.LogStep(testCaseName);
        Test.AddFT(shortName, initialState);
        ExecuteFMMessage(msg);
        Test.ValidateFT(shortName, expectedFinalState);
    }

    void RunWithNodeActive(wstring const & testCaseName, wstring const & shortName, wstring const & initialState, wstring const & msg, wstring const & expectedFinalState)
    {
        RunTestCase(true, testCaseName, shortName, initialState, msg, expectedFinalState);
    }

    void RunWithNodeInactive(wstring const & testCaseName, wstring const & shortName, wstring const & initialState, wstring const & msg, wstring const & expectedFinalState)
    {
        RunTestCase(false, testCaseName, shortName, initialState, msg, expectedFinalState);
    }
};

