// Adjusts wheel speeds to move forward when no nearby obstacles, 
// and retreats when sensors detect proximity to another robot
WheelVelocity Explore::CalcWheelVelocity(double left_sensor,
  double right_sensor) {
  return WheelVelocity(MAX_READING - right_sensor,
    MAX_READING - left_sensor);
}

// Combines light avoidance and food-seeking behaviors:
// The robot steers away from bright lights while also moving toward food sources
WheelVelocity Explore::CalcWheelVelocityWFood(double left_light,
  double right_light, double left_nutrient, double right_nutrient) {
  double left_wheel = ((MAX_READING - right_light) * 0.5) +
    (right_nutrient * 0.5);
  double right_wheel = ((MAX_READING - left_light) * 0.5) +
    (left_nutrient * 0.5);

  return WheelVelocity(left_wheel, right_wheel);
}

