#include "include/BER.h"

// Decodes BER long-form integer: handles multi-byte encoding with continuation bits
static size_t parse_ber_long_integer(const uint8_t* input, long* result, int limit) {
    int count = 1;
    long accumulator = 0;

    while (*input >= 128 && count < limit && accumulator <= INT_MAX / 128) {
        accumulator = (accumulator + (*input & 0x7F)) * 128;
        ++input;
        ++count;
    }

    accumulator += *input; // final octet
    *result = accumulator;
    return count;
}

// Decodes BER length field: short form (<=127) or long form (>127)
static size_t parse_ber_length_field(const uint8_t* input, int* out_len, int) {
    if (*input <= 127) {
        *out_len = *input;
        return 1;
    } else {
        int byte_count = *input & 0x7F;
        int total = 0;
        for (int idx = 0; idx < byte_count; ++idx) {
            ++input;
            total = (total << 8) | *input;
        }
        *out_len = total;
        return byte_count + 1;
    }
}

int BER_CONTAINER::fromBuffer(const uint8_t *buffer, size_t max_size) {
    if (max_size < 2) return SNMP_BUFFER_ERROR_TLV_TOO_SMALL;

    const uint8_t* cursor = buffer;

    if (*cursor != _type) {
        SNMP_LOGE("Type mismatch during decode: expected %d, got %d\n", _type, *cursor);
        return SNMP_BUFFER_ERROR_TYPE_MISMATCH;
    }

    ++cursor; // skip type
    cursor += parse_ber_length_field(cursor, &_length, max_size);

    if ((size_t)_length + 2 > max_size) {
        return SNMP_BUFFER_ERROR_MAX_LEN_EXCEEDED;
    }

    return cursor - buffer;
}

int NetworkAddress::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* pos = buffer + consumed;
    _value = IPAddress(pos);
    return pos - buffer;
}

int IntegerType::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* pos = buffer + consumed;
    unsigned short remaining = _length;
    uint32_t temp = 0;

    while (remaining > 0) {
        temp <<= 8;
        temp |= *pos++;
        --remaining;
    }

    switch (_length) {
        case 1:
            _value = static_cast<int8_t>(temp);
            break;
        case 2:
            _value = static_cast<int16_t>(temp);
            break;
        case 3:
            if (temp & 0x00800000) {
                temp |= 0xFF000000;
            }
            _value = static_cast<int32_t>(temp);
            break;
        default:
            _value = static_cast<int32_t>(temp);
    }

    return pos - buffer;
}

int OctetType::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* pos = buffer + consumed;
    if (_length > OCTET_TYPE_MAX_LENGTH) return SNMP_BUFFER_ERROR_OCTET_TOO_BIG;

    _value.assign(reinterpret_cast<const char*>(pos), _length);
    return _length + consumed;
}

int OpaqueType::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* pos = buffer + consumed;
    _value = static_cast<uint8_t*>(calloc(_length, sizeof(uint8_t)));
    memcpy(_value, pos, _length);
    _dataLength = _length;
    return _length + consumed;
}

int OIDType::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* data = buffer + consumed;
    if (*data != 0x2b) return SNMP_BUFFER_ERROR_INVALID_OID;

    this->data.reserve(_length);
    this->data.assign(data, data + _length);
    this->valid = true;
    return _length + 2;
}

// Converts long integer to string recursively in base-10
static inline void int_to_str(char* dst, long val, short depth = 0) {
    if (val > 9) {
        int_to_str(dst + 1, val / 10L, depth + 1);
    }
    *(dst + 1) = static_cast<char>((val % 10) + '0');
    if (!depth) {
        *(dst + 2) = '\0';
    }
}

const std::string& OIDType::string() {
    if (!_value.empty()) return _value;

    const uint8_t* ptr = this->data.data();
    _value = ".1.3";

    if (!this->valid) return _value;

    ++ptr;
    int remain = this->data.size() - 1;
    char scratch[16];

    while (remain > 0) {
        memset(scratch, 0, sizeof(scratch));
        long component = 0;
        int len = parse_ber_long_integer(ptr, &component, remain);
        ptr += len;
        remain -= len;

        scratch[0] = '.';
        int_to_str(scratch, component);
        _value.append(scratch);
    }

    return _value;
}

const std::vector<unsigned long> SortableOIDType::generateSortingMap() const {
    std::vector<unsigned long> mapping;
    mapping.reserve(this->data.size());

    const uint8_t* pos = this->data.data();
    ++pos; // skip first byte (assumed fixed prefix)
    int remain = this->data.size() - 1;

    while (remain > 0) {
        long value;
        size_t used = parse_ber_long_integer(pos, &value, remain);
        pos += used;
        remain -= used;
        mapping.push_back(static_cast<unsigned long>(value));
    }

    return mapping;
}

int NullType::fromBuffer(const uint8_t *, size_t) {
    _length = 0;
    return 2;
}

int Counter64::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* pos = buffer + consumed;
    int bytes_left = _length;
    _value = 0ULL;

    while (bytes_left > 0) {
        _value <<= 8U;
        _value |= *pos++;
        --bytes_left;
    }

    return _length + 2;
}

std::shared_ptr<BER_CONTAINER> ComplexType::createObjectForType(ASN_TYPE kind) {
    SNMP_LOGD("Instantiating object of type: %d\n", kind);
    switch (kind) {
        case INTEGER:
            return std::make_shared<IntegerType>();
        case STRING:
            return std::make_shared<OctetType>();
        case OID:
            return std::make_shared<OIDType>();
        case NULLTYPE:
            return std::make_shared<NullType>();
        case NOSUCHOBJECT:
            return std::make_shared<ImplicitNullType>(NOSUCHOBJECT);
        case NOSUCHINSTANCE:
            return std::make_shared<ImplicitNullType>(NOSUCHINSTANCE);
        case ENDOFMIBVIEW:
            return std::make_shared<ImplicitNullType>(ENDOFMIBVIEW);
        case NETWORK_ADDRESS:
            return std::make_shared<NetworkAddress>();
        case TIMESTAMP:
            return std::make_shared<TimestampType>();
        case COUNTER32:
            return std::make_shared<Counter32>();
        case GUAGE32:
            return std::make_shared<Guage>();
        case COUNTER64:
            return std::make_shared<Counter64>();
        case OPAQUE:
            return std::make_shared<OpaqueType>();
        case STRUCTURE:
        case GetRequestPDU:
        case GetNextRequestPDU:
        case GetResponsePDU:
        case SetRequestPDU:
        case GetBulkRequestPDU:
        case InformRequestPDU:
        case Trapv2PDU:
            return std::make_shared<ComplexType>(kind);
        default:
            return nullptr;
    }
}

int ComplexType::fromBuffer(const uint8_t *buffer, size_t max_size) {
    int consumed = BER_CONTAINER::fromBuffer(buffer, max_size);
    CHECK_DECODE_ERR(consumed);

    const uint8_t* pos = buffer + consumed;
    size_t processed = 1;

    while (processed < static_cast<size_t>(_length) && processed <= max_size) {
        ASN_TYPE type = static_cast<ASN_TYPE>(*pos);
        auto child = ComplexType::createObjectForType(type);
        if (!child) {
            SNMP_LOGD("Failed to instantiate type %d\n", type);
            return SNMP_BUFFER_ERROR_UNKNOWN_TYPE;
        }

        int used = child->fromBuffer(pos, max_size - processed);
        if (used < 0) {
            SNMP_LOGD("Error decoding sub-object of type %d\n", type);
            return SNMP_BUFFER_ERROR_PROBLEM_DESERIALISING;
        }

        addValueToList(child);
        pos += used;
        processed += used;
    }

    return _length + 2;
}

