using namespace circt;

//===----------------------------------------------------------------------===//
// Moore to Core Dialect Conversion Pass
//===----------------------------------------------------------------------===//

namespace {

struct MooreToLLVMPass : public ConvertMooreToCoreBase<MooreToLLVMPass> {
  void runOnOperation() override;
};

} // namespace

std::unique_ptr<OperationPass<ModuleOp>> circt::createConvertMooreToCorePass() {
  return std::make_unique<MooreToLLVMPass>();
}

namespace {

// Helper: convert Moore types to target dialect types
static Type translateMooreType(Type input) {
  return llvm::TypeSwitch<Type, Type>(input)
      .Case<moore::IntType>([](auto t) {
        return IntegerType::get(t.getContext(), t.getBitWidth());
      })
      .Case<moore::RValueType>([](auto t) { return translateMooreType(t.getInner()); })
      .Case<moore::LValueType>([](auto t) {
        return llhd::SigType::get(translateMooreType(t.getInner()));
      })
      .Default([](Type t) { return t; });
}

// Forward declarations for conversion patterns
struct ConstPattern;
struct VarDeclPattern;
struct DrvAssignPattern;

void MooreToLLVMPass::runOnOperation() {
  MLIRContext &ctx = getContext();
  ModuleOp mod = getOperation();

  // Set up conversion target
  ConversionTarget target(ctx);
  target.addIllegalDialect<moore::MooreDialect>();
  target.addLegalDialect<hw::HWDialect, llhd::LLHDDialect, comb::CombDialect>();
  target.addLegalOp<ModuleOp>();

  // Configure type converter
  TypeConverter converter;
  converter.addConversion(translateMooreType);

  // Register conversion patterns
  RewritePatternSet patterns(&ctx);
  patterns.insert<ConstPattern, VarDeclPattern, DrvAssignPattern>(&converter, &ctx);

  if (failed(applyFullConversion(mod, target, std::move(patterns))))
    signalPassFailure();
}

//===----------------------------------------------------------------------===//
// Pattern implementations
//===----------------------------------------------------------------------===//

struct ConstPattern : public OpConversionPattern<moore::ConstantOp> {
  using OpConversionPattern::OpConversionPattern;

  LogicalResult matchAndRewrite(moore::ConstantOp op,
                                OpAdaptor adaptor,
                                ConversionPatternRewriter &rewriter) const override {
    rewriter.replaceOpWithNewOp<hw::ConstantOp>(op, op.getValueAttr());
    return success();
  }
};

struct VarDeclPattern : public OpConversionPattern<moore::VariableDeclOp> {
  using OpConversionPattern::OpConversionPattern;

  LogicalResult matchAndRewrite(moore::VariableDeclOp op,
                                OpAdaptor adaptor,
                                ConversionPatternRewriter &rewriter) const override {
    Type targetType = getTypeConverter()->convertType(op.getResult().getType());
    Location loc = op.getLoc();
    Value initVal = rewriter.create<hw::ConstantOp>(loc, op.getInitAttr());
    rewriter.replaceOpWithNewOp<llhd::SigOp>(op, targetType, op.getName(), initVal);
    return success();
  }
};

struct DrvAssignPattern : public OpConversionPattern<moore::AssignOp> {
  using OpConversionPattern::OpConversionPattern;

  LogicalResult matchAndRewrite(moore::AssignOp op,
                                OpAdaptor adaptor,
                                ConversionPatternRewriter &rewriter) const override {
    Location loc = op.getLoc();
    Value zeroTime = rewriter.create<llhd::ConstantTimeOp>(loc, 0, "s", 0, 1);

    Type destTy = getTypeConverter()->convertType(op.getDest().getType());
    Type srcTy = getTypeConverter()->convertType(op.getSrc().getType());

    op.getDest().setType(destTy);
    op.getSrc().setType(srcTy);

    rewriter.replaceOpWithNewOp<llhd::DrvOp>(op, op.getDest(), op.getSrc(), zeroTime, Value{});
    return success();
  }
};

} // namespace

