void FDlgParticipantData::AddConditionPrimaryData(const FDlgCondition& Condition)
{
	const EDlgConditionType Type = Condition.ConditionType;
	const FName Name = Condition.CallbackName;

	if (Type == EDlgConditionType::EventCall)
	{
		Conditions.Add(Name);
	}
	else if (Type == EDlgConditionType::IntCall)
	{
		IntVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::FloatCall)
	{
		FloatVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::BoolCall)
	{
		BoolVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::NameCall)
	{
		NameVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::ClassIntVariable)
	{
		ClassIntVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::ClassFloatVariable)
	{
		ClassFloatVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::ClassBoolVariable)
	{
		ClassBoolVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::ClassNameVariable)
	{
		ClassNameVariableNames.Add(Name);
	}
	else if (Type == EDlgConditionType::Custom && Condition.CustomCondition.IsValid())
	{
		CustomConditions.Add(Condition.CustomCondition->GetClass());
	}
}

void FDlgParticipantData::AddConditionSecondaryData(const FDlgCondition& Condition)
{
	const FName VarName = Condition.OtherVariableName;

	if (Condition.CompareType != EDlgCompare::ToConst)
	{
		const bool bIsClassVar = (Condition.CompareType == EDlgCompare::ToClassVariable);

		const EDlgConditionType CType = Condition.ConditionType;

		if (CType == EDlgConditionType::IntCall || CType == EDlgConditionType::ClassIntVariable)
		{
			(bIsClassVar ? ClassIntVariableNames : IntVariableNames).Add(VarName);
		}
		else if (CType == EDlgConditionType::FloatCall || CType == EDlgConditionType::ClassFloatVariable)
		{
			(bIsClassVar ? ClassFloatVariableNames : FloatVariableNames).Add(VarName);
		}
		else if (CType == EDlgConditionType::BoolCall || CType == EDlgConditionType::ClassBoolVariable)
		{
			(bIsClassVar ? ClassBoolVariableNames : BoolVariableNames).Add(VarName);
		}
		else if (CType == EDlgConditionType::NameCall || CType == EDlgConditionType::ClassNameVariable)
		{
			(bIsClassVar ? ClassNameVariableNames : NameVariableNames).Add(VarName);
		}
	}
}

void FDlgParticipantData::AddEventData(const FDlgEvent& Event)
{
	const EDlgEventType EvtType = Event.EventType;

	if (EvtType == EDlgEventType::Event)
	{
		Events.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyInt)
	{
		IntVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyFloat)
	{
		FloatVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyBool)
	{
		BoolVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyName)
	{
		NameVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyClassIntVariable)
	{
		ClassIntVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyClassFloatVariable)
	{
		ClassFloatVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyClassBoolVariable)
	{
		ClassBoolVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::ModifyClassNameVariable)
	{
		ClassNameVariableNames.Add(Event.EventName);
	}
	else if (EvtType == EDlgEventType::Custom && Event.CustomEvent.IsValid())
	{
		CustomEvents.Add(Event.CustomEvent->GetClass());
	}
}

void FDlgParticipantData::AddTextArgumentData(const FDlgTextArgument& TextArgument)
{
	const EDlgTextArgumentType ArgType = TextArgument.Type;

	if (ArgType == EDlgTextArgumentType::DialogueInt)
	{
		IntVariableNames.Add(TextArgument.VariableName);
	}
	else if (ArgType == EDlgTextArgumentType::DialogueFloat)
	{
		// Intentionally no break here — matches original behavior
		FloatVariableNames.Add(TextArgument.VariableName);
	}
	else if (ArgType == EDlgTextArgumentType::ClassInt)
	{
		ClassIntVariableNames.Add(TextArgument.VariableName);
	}
	else if (ArgType == EDlgTextArgumentType::ClassFloat)
	{
		ClassFloatVariableNames.Add(TextArgument.VariableName);
	}
	else if (ArgType == EDlgTextArgumentType::ClassText)
	{
		ClassTextVariableNames.Add(TextArgument.VariableName);
	}
	else if (ArgType == EDlgTextArgumentType::Custom && TextArgument.CustomTextArgument.IsValid())
	{
		CustomTextArguments.Add(TextArgument.CustomTextArgument->GetClass());
	}
}

#include "LoadSound.hpp"
#include <dspbb/Filtering/Interpolation.hpp>
#include <sndfile.hh>
using namespace dspbb;

StereoSound LoadStereoSound(const std::filesystem::path& file) {
    SndfileHandle soundFile(file.string().c_str());
    if (!soundFile) {
        throw std::runtime_error("Failed to open demo sound file.");
    }

    const size_t frameCount = soundFile.frames();
    const size_t channelCount = soundFile.channels();
    const uint64_t sampleRate = soundFile.samplerate();

    if (channelCount != 2) {
        throw std::runtime_error("You can only load stereo files at the moment.");
    }

    Signal<float> interleaved(frameCount * channelCount);
    soundFile.read(interleaved.Data(), interleaved.Size());

    // Extract left and right channels using stride-based extraction
    Signal<float> leftChannel;
    Signal<float> rightChannel;

    leftChannel.reserve(frameCount);
    rightChannel.reserve(frameCount);

    for (size_t i = 0; i < frameCount; ++i) {
        leftChannel.push_back(interleaved[2 * i]);
        rightChannel.push_back(interleaved[2 * i + 1]);
    }

    return { std::move(leftChannel), std::move(rightChannel), sampleRate };
}

