#include <bits/stdc++.h>
using namespace std;

// Structure to represent a point with coordinates
struct Point {
    long long x, y;
};

int N;
vector<Point> points;

// Compute total cost for aligning points to positions (x+i, y)
long long computeCost(long long startX, long long startY) {
    long long total = 0;
    for (int i = 0; i < N; ++i) {
        total += abs(points[i].x - (startX + i));
        total += abs(points[i].y - startY);
    }
    return total;
}

// Solve one test case
long long solveCase() {
    cin >> N;
    points.resize(N);
    for (int i = 0; i < N; ++i) {
        cin >> points[i].x >> points[i].y;
    }

    // Sort points by x-coordinate, then by y-coordinate
    sort(points.begin(), points.end(), [](const Point& a, const Point& b) {
        if (a.x != b.x) return a.x < b.x;
        return a.y < b.y;
    });

    // First, optimize over x using ternary search
    long long leftX = -1'010'000'000LL;
    long long rightX = 1'010'000'000LL;

    while (rightX - leftX > 2) {
        long long third1 = leftX + (rightX - leftX) / 3;
        long long third2 = rightX - (rightX - leftX) / 3;

        long long cost1 = computeCost(third1, 0);
        long long cost2 = computeCost(third2, 0);

        if (cost1 < cost2) {
            rightX = third2;
        } else {
            leftX = third1;
        }
    }

    long long bestX = leftX;
    long long minCostX = computeCost(leftX, 0);

    for (long long candidate = leftX + 1; candidate <= rightX; ++candidate) {
        long long currentCost = computeCost(candidate, 0);
        if (currentCost < minCostX) {
            minCostX = currentCost;
            bestX = candidate;
        }
    }

    // Then, optimize over y using ternary search with fixed x
    long long leftY = -1'010'000'000LL;
    long long rightY = 1'010'000'000LL;

    while (rightY - leftY > 2) {
        long long third1 = leftY + (rightY - leftY) / 3;
        long long third2 = rightY - (rightY - leftY) / 3;

        long long cost1 = computeCost(bestX, third1);
        long long cost2 = computeCost(bestX, third2);

        if (cost1 < cost2) {
            rightY = third2;
        } else {
            leftY = third1;
        }
    }

    long long bestY = leftY;
    long long finalCost = computeCost(bestX, leftY);

    for (long long candidate = leftY + 1; candidate <= rightY; ++candidate) {
        long long currentCost = computeCost(bestX, candidate);
        if (currentCost < finalCost) {
            finalCost = currentCost;
            bestY = candidate;
        }
    }

    return finalCost;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    unsigned testCaseCount;
    cin >> testCaseCount;

    for (unsigned t = 1; t <= testCaseCount; ++t) {
        cout << "Case #" << t << ": " << solveCase() << '\n';
    }

    return 0;
}

