}

// Test pointer conversion round-trip with data pointers
TEST(ExecutorAddrTest, PtrConversion) {
  int value = 42;
  auto addrFromPtr = ExecutorAddr::fromPtr(&value);
  int* restoredPtr = addrFromPtr.toPtr<int*>();
  EXPECT_EQ(restoredPtr, &value);
}

// Helper function for testing function pointer conversions
static void testFunc() {}

// Ensure function types (not just function pointers) work with toPtr
TEST(ExecutorAddrTest, PtrConversionWithFunctionType) {
  auto addr = ExecutorAddr::fromPtr(testFunc);
  void (*funcPtr)() = addr.toPtr<void()>();
  EXPECT_EQ(funcPtr, &testFunc);
}

// Test range operations including containment and overlap
TEST(ExecutorAddrTest, AddrRanges) {
  ExecutorAddr Start0(0), Start1(1), Start2(2), Start3(3);
  ExecutorAddrRange Range0(Start0, Start1),
                     Range1(Start1, Start2),
                     Range2(Start2, Start3),
                     Range3(Start0, Start2),
                     Range4(Start1, Start3);

  // Verify equality and construction variants
  EXPECT_EQ(Range1, ExecutorAddrRange(Start1, Start2));
  EXPECT_EQ(Range1, ExecutorAddrRange(Start1, ExecutorAddrDiff(1)));
  EXPECT_NE(Range1, Range2);

  // Check element containment
  EXPECT_TRUE(Range1.contains(Start1));
  EXPECT_FALSE(Range1.contains(Start0));
  EXPECT_FALSE(Range1.contains(Start2));

  // Check overlap relationships
  EXPECT_FALSE(Range1.overlaps(Range0));
  EXPECT_FALSE(Range1.overlaps(Range2));
  EXPECT_TRUE(Range1.overlaps(Range3));
  EXPECT_TRUE(Range1.overlaps(Range4));
}

