// Helper to convert plugin to searchable string array
static void ConvertPluginToSearchStrings(const IPlugin* InPlugin, TArray<FString>& OutStrings)
{
    OutStrings.Add(InPlugin->GetDescriptor().FriendlyName);
}

SPluginBrowser::~SPluginBrowser()
{
    FDirectoryWatcherModule& DirectoryWatcherModule = FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
    for (auto It = WatchDirectories.CreateIterator(); It; ++It)
    {
        const FString& DirPath = It.Key();
        const FDelegateHandle& Handle = It.Value();
        DirectoryWatcherModule.Get()->UnregisterDirectoryChangedCallback_Handle(DirPath, Handle);
    }
    FPluginBrowserModule::Get().OnNewPluginCreated().RemoveAll(this);
}

void SPluginBrowser::Construct(const FArguments& Args)
{
    // Gather root directories containing plugins
    TArray<FString> PluginSearchPaths;
    PluginSearchPaths.Add(FPaths::EnginePluginsDir());
    if (FApp::HasProjectName())
    {
        PluginSearchPaths.Add(FPaths::ProjectPluginsDir());
        const FProjectDescriptor* ActiveProject = IProjectManager::Get().GetCurrentProject();
        if (ActiveProject != nullptr)
        {
            const TArray<FString>& ExtraPaths = ActiveProject->GetAdditionalPluginDirectories();
            for (int32 Idx = 0; Idx < ExtraPaths.Num(); ++Idx)
            {
                PluginSearchPaths.Add(ExtraPaths[Idx]);
            }
        }
    }

    // Register directory change listeners
    FDirectoryWatcherModule& DirectoryWatcherModule = FModuleManager::LoadModuleChecked<FDirectoryWatcherModule>(TEXT("DirectoryWatcher"));
    for (int32 PathIndex = 0; PathIndex < PluginSearchPaths.Num(); ++PathIndex)
    {
        const FString& CurrentPath = PluginSearchPaths[PathIndex];
        FDelegateHandle CallbackToken;
        if (DirectoryWatcherModule.Get()->RegisterDirectoryChangedCallback_Handle(
                CurrentPath,
                IDirectoryWatcher::FDirectoryChanged::CreateRaw(this, &SPluginBrowser::OnPluginDirectoryChanged),
                CallbackToken,
                IDirectoryWatcher::WatchOptions::IncludeDirectoryChanges))
        {
            WatchDirectories.Add(CurrentPath, CallbackToken);
        }
    }

    // Subscribe to new plugin creation events
    FPluginBrowserModule::Get().OnNewPluginCreated().AddSP(this, &SPluginBrowser::OnNewPluginCreated);

    // Schedule breadcrumb refresh on first tick
    RegisterActiveTimer(0.f, FWidgetActiveTimerDelegate::CreateSP(this, &SPluginBrowser::TriggerBreadcrumbRefresh));

    // Setup text filtering using custom converter
    PluginTextFilter = MakeShareable(new FPluginTextFilter(
        FPluginTextFilter::FItemToStringArray::CreateStatic(&ConvertPluginToSearchStrings)));

    const float PaddingAmount = 2.0f;

    // Initialize category tree
    PluginCategories = SNew(SPluginCategoryTree, SharedThis(this));

    // Build main UI layout
    TSharedRef<SVerticalBox> MainContent = SNew(SVerticalBox)
        + SVerticalBox::Slot()
        [
            SNew(SSplitter)
            + SSplitter::Slot()
              .Value(.3f)
              [
                  PluginCategories.ToSharedRef()
              ]
            + SSplitter::Slot()
              [
                  SNew(SVerticalBox)
                  + SVerticalBox::Slot()
                    .Padding(FMargin(0.0f, 0.0f, 0.0f, PaddingAmount))
                    .AutoHeight()
                    [
                        SNew(SHorizontalBox)
                        + SHorizontalBox::Slot()
                          .Padding(PaddingAmount)
                          [
                              SAssignNew(BreadcrumbTrail, SBreadcrumbTrail<TSharedPtr<FPluginCategory>>)
                                .DelimiterImage(FPluginStyle::Get()->GetBrush("Plugins.BreadcrumbArrow"))
                                .ShowLeadingDelimiter(true)
                                .OnCrumbClicked(this, &SPluginBrowser::BreadcrumbTrail_OnCrumbClicked)
                          ]
                        + SHorizontalBox::Slot()
                          .Padding(PaddingAmount)
                          [
                              SAssignNew(SearchBoxPtr, SSearchBox)
                                .OnTextChanged(this, &SPluginBrowser::SearchBox_OnPluginSearchTextChanged)
                          ]
                    ]
                  + SVerticalBox::Slot()
                    [
                        SAssignNew(PluginList, SPluginTileList, SharedThis(this))
                    ]
                  + SVerticalBox::Slot()
                    .AutoHeight()
                    .Padding(FMargin(PaddingAmount, PaddingAmount, PaddingAmount, 0.0f))
                    [
                        SNew(SBorder)
                          .BorderBackgroundColor(FLinearColor::Yellow)
                          .BorderImage(FEditorStyle::GetBrush("ToolPanel.GroupBorder"))
                          .Padding(8.0f)
                          .Visibility(this, &SPluginBrowser::HandleRestartEditorNoticeVisibility)
                          [
                              SNew(SHorizontalBox)
                              + SHorizontalBox::Slot()
                                .AutoWidth()
                                .VAlign(VAlign_Center)
                                .Padding(FMargin(0.0f, 0.0f, 8.0f, 0.0f))
                                [
                                    SNew(SImage)
                                      .Image(FPluginStyle::Get()->GetBrush("Plugins.Warning"))
                                ]
                              + SHorizontalBox::Slot()
                                .VAlign(VAlign_Center)
                                [
                                    SNew(STextBlock)
                                      .Text(LOCTEXT("PluginSettingsRestartNotice", "Unreal Editor must be restarted for the plugin changes to take effect."))
                                ]
                              + SHorizontalBox::Slot()
                                .AutoWidth()
                                .VAlign(VAlign_Center)
                                .HAlign(HAlign_Right)
                                [
                                    SNew(SButton)
                                      .Text(LOCTEXT("PluginSettingsRestartEditor", "Restart Now"))
                                      .OnClicked(this, &SPluginBrowser::HandleRestartEditorButtonClicked)
                                ]
                          ]
                    ]
              ]
        ];

    // Add 'New Plugin' button at top-right
    MainContent->AddSlot()
