    return FReply::Handled();
}

#undef LOCTEXT_NAMESPACE

#include "mex.h"
#define KDTREE_USE_SQUARED_DISTANCE
#include <kdtree++/kdtree.hpp>
#include <vector>
#include <list>
#include <algorithm>
#include <cmath>

// Point structure used internally
struct Pnt {
    int id;
    double coord[2];
    bool operator==(const Pnt& other) const {
        return id == other.id && coord[0] == other.coord[0] && coord[1] == other.coord[1];
    }
};

// Helper to extract coordinate for KDTree
inline double get_coord(const Pnt& p, size_t dim) { return p.coord[dim]; }

// Type alias for 2D KDTree
typedef KDTree::KDTree<2, Pnt, std::pointer_to_binary_function<const Pnt&, size_t, double>> Tree2D;

// Double-precision 2D point (matches MATLAB input layout)
struct DPoint {
    double x, y;
};

// Match record: distance, index in A, index in B
struct Assignment {
    double dist_sq;
    int idxA;
    int idxB;
};

// Comparator for priority queue behavior (min-heap on dist_sq)
struct AssignmentCompare {
    bool operator()(const Assignment& a, const Assignment& b) const {
        return a.dist_sq > b.dist_sq; // min-heap semantics
    }
};

// Squared Euclidean distance between two DPoints
inline double sq_dist(const DPoint& pa, const DPoint& pb) {
    double dx = pa.x - pb.x;
    double dy = pa.y - pb.y;
    return dx * dx + dy * dy;
}

// Core matching routine — rewritten with explicit heap management instead of multiset
void performMatching(DPoint* ptsA, DPoint* ptsB, int N, int* assignments) {
    // Build KD-tree over points in B
    Tree2D treeB(std::ptr_fun(get_coord));
    for (int i = 0; i < N; ++i) {
        Pnt p = {i, ptsB[i].x, ptsB[i].y};
        treeB.insert(p);
    }
    treeB.optimize(); // balance tree

    // Initialize structures:
    // - bestMatch[i] stores current best match for point i in A
    // - incoming[B] lists all A-points currently claiming B
    std::vector<int> bestMatch(N, -1);       // idxB for each A
    std::vector<std::list<int>> incoming(N); // list of A indices per B

    // Priority queue (min-heap) of pending assignments (by increasing distance)
    std::vector<Assignment> pq;
    pq.reserve(N);

    // Phase 1: initial nearest neighbor matches
    for (int i = 0; i < N; ++i) {
        Pnt query{-1, ptsA[i].x, ptsA[i].y};
        auto [iter, distSq] = treeB.find_nearest(query);
        if (iter == treeB.end()) {
            mexErrMsgIdAndTxt("pmRefinement:initMatch", "Failed to find initial match.");
            return;
        }
        int j = iter->id;
        bestMatch[i] = j;
        incoming[j].push_back(i);
        pq.push_back({distSq, i, j});
    }
    std::make_heap(pq.begin(), pq.end(), AssignmentCompare());

    // Phase 2: resolve conflicts greedily
    while (!pq.empty()) {
        // Extract minimum-distance unmatched assignment
        std::pop_heap(pq.begin(), pq.end(), AssignmentCompare());
        Assignment curr = pq.back();
        pq.pop_back();

        // Skip if already reassigned (stale entry)
        if (bestMatch[curr.idxA] != curr.idxB || curr.idxB == -1)
            continue;

        // Fix this assignment
        assignments[curr.idxA] = curr.idxB;

        // Remove matched B point from tree
        Pnt removed{curr.idxB, ptsB[curr.idxB].x, ptsB[curr.idxB].y};
        treeB.erase_exact(removed);

        // Reassign any other A-points that previously chose this B
        auto& claimants = incoming[curr.idxB];
        if (claimants.size() > 1) {
            for (auto it = claimants.begin(); it != claimants.end(); ++it) {
                int a = *it;
                if (a == curr.idxA) continue; // skip self

                // Find new nearest neighbor for A[a]
                Pnt q{-1, ptsA[a].x, ptsA[a].y};
                auto [newIter, newDistSq] = treeB.find_nearest(q);
                if (newIter == treeB.end()) {
                    mexErrMsgIdAndTxt("pmRefinement:reassign", "No remaining match possible.");
                    return;
                }

                int newB = newIter->id;
                // Update assignment
                bestMatch[a] = newB;
                incoming[newB].push_back(a);

                // Push updated assignment into heap
                pq.push_back({newDistSq, a, newB});
                std::push_heap(pq.begin(), pq.end(), AssignmentCompare());
            }
        }
        claimants.clear();
    }
}

// MEX gateway
void mexFunction(int nlhs, mxArray *plhs[], int nrhs, const mxArray *prhs[]) {
    if (nrhs != 2) {
        mexErrMsgIdAndTxt("pmRefinement:nrhs", "Two inputs required.");
        return;
    }
    if (nlhs != 1) {
        mexErrMsgIdAndTxt("pmRefinement:nlhs", "One output required.");
        return;
    }

    // Validate inputs
    mwSize rowsA = mxGetM(prhs[0]), colsA = mxGetN(prhs[0]);
    mwSize rowsB = mxGetM(prhs[1]), colsB = mxGetN(prhs[1]);

    if (rowsA != rowsB || colsA != colsB) {
        mexErrMsgIdAndTxt("pmRefinement:sizeMismatch", "Input matrices must have identical dimensions.");
        return;
    }
    if (rowsA != 2) {
        mexErrMsgIdAndTxt("pmRefinement:dim", "Only 2D points are supported.");
        return;
    }

    // Cast inputs as arrays of DPoint
    DPoint* dataA = reinterpret_cast<DPoint*>(mxGetData(prhs[0]));
    DPoint* dataB = reinterpret_cast<DPoint*>(mxGetData(prhs[1]));

    int N = static_cast<int>(colsA);

    // Create output array (1xN int32)
    plhs[0] = mxCreateNumericMatrix(1, N, mxINT32_CLASS, mxREAL);
    int* out = reinterpret_cast<int*>(mxGetData(plhs[0]));

    // Perform matching
    performMatching(dataA, dataB, N, out);

    // Convert from 0-based (C++) to 1-based (MATLAB)
    for (int i = 0; i < N; ++i) {
        out[i] += 1;
    }
}

#include <gtest/gtest.h>
#include <QCoreApplication>
#include <QPushButton>
#include <QTest>
