#include "AnnotatingSourceCodeDialog.h"
#include "CodeReport/AnnotateDisassembly.h"
#include "CodeReport/AnnotatingLine.h"
#include "CodeReport/DisassemblyReport.h"
#include "CodeViewer/OwningDialog.h"
#include "OrbitBase/Logging.h"
#include "OrbitBase/ReadFileToString.h"
#include "SourcePathsMapping/Mapping.h"
#include "SourcePathsMapping/MappingManager.h"
#include "SyntaxHighlighter/X86Assembly.h"
#include "Test/Path.h"
#include "capture_data.pb.h"

using namespace std::string_view_literals;

// Instructions for the main function in the test binary
const std::string_view kMainFunctionInstructions =
    "\x50\xbf\x04\x20\x40\x00\xe8\xe5\xfe\xff\xff\x31\xc0\x59\xc3\x90"sv;

constexpr const char* kOrganizationName = "The Orbit Authors";

TEST(AnnotatingSourceCodeDialog, SmokeTest) {
  QCoreApplication::setOrganizationName(kOrganizationName);
  QCoreApplication::setApplicationName("AnnotatingSourceCodeDialog.SmokeTest");

  // Setup source path mapping
  {
    orbit_source_paths_mapping::MappingManager pathMapper{};
    pathMapper.SetMappings({});
    pathMapper.AppendMapping(orbit_source_paths_mapping::Mapping{
        std::filesystem::path{"."} / "..", orbit_test::GetTestdataDir()});
  }

  const std::filesystem::path binaryPath = orbit_test::GetTestdataDir() / "line_info_test_binary";

  // Load and validate ELF file
  auto elfResult = orbit_object_utils::CreateElfFile(binaryPath);
  ASSERT_TRUE(elfResult.has_value()) << elfResult.error().message();

  constexpr uint64_t kEntryAddress = 0x401140;
  auto lineInfoResult = elfResult.value()->GetLocationOfFunction(kEntryAddress);
  ASSERT_TRUE(lineInfoResult.has_value()) << lineInfoResult.error().message();

  const std::filesystem::path cppSourcePath =
      orbit_test::GetTestdataDir() / "LineInfoTestBinary.cpp";
  ASSERT_TRUE(std::filesystem::exists(cppSourcePath));

  auto fileContentResult = orbit_base::ReadFileToString(cppSourcePath);
  ASSERT_TRUE(fileContentResult.has_value()) << fileContentResult.error().message();
  std::string sourceContent = std::move(fileContentResult.value());

  // Prepare function metadata
  orbit_client_protos::FunctionInfo funcInfo{};
  funcInfo.set_name("main");
  funcInfo.set_pretty_name("main");
  funcInfo.set_module_path("line_info_test_binary");
  funcInfo.set_address(0x401140);
  funcInfo.set_size(kMainFunctionInstructions.size());

  // Disassemble instructions
  orbit_code_report::Disassembler disasm{};
  disasm.Disassemble(static_cast<const void*>(kMainFunctionInstructions.data()),
                     kMainFunctionInstructions.size(), kEntryAddress, true);

  std::string assemblyOutput = disasm.GetResult();
  orbit_code_report::DisassemblyReport report{std::move(disasm), kEntryAddress};

  // UI setup
  orbit_qt::AnnotatingSourceCodeDialog dialog{};
  auto highlighter = std::make_unique<orbit_syntax_highlighter::X86Assembly>();
  dialog.SetMainContent(QString::fromStdString(assemblyOutput), std::move(highlighter));
  dialog.SetDisassemblyCodeReport(std::move(report));

  bool annotationCallbackTriggered = false;
  dialog.AddAnnotatingSourceCode(funcInfo,
                                 [&](const std::string&, const std::string&) -> auto {
                                   annotationCallbackTriggered = true;
                                   return orbit_base::Future<ErrorMessageOr<std::filesystem::path>>{
                                       binaryPath};
                                 });

  bool sourceLoadedFlag = false;
  QObject::connect(&dialog, &orbit_qt::AnnotatingSourceCodeDialog::SourceCodeLoaded, &dialog,
                   [&]() {
                     sourceLoadedFlag = true;
                     dialog.close();
                   });

  QObject::connect(&dialog, &orbit_qt::AnnotatingSourceCodeDialog::SourceCodeAvailable, &dialog,
                   [&]() {
                     QPushButton* loadBtn = dialog.findChild<QPushButton*>("notification_action_button");
                     if (!loadBtn) return;
                     QTest::mouseClick(loadBtn, Qt::LeftButton);
                   });

  QTimer::singleShot(std::chrono::seconds{2}, &dialog, [&]() { dialog.close(); });

  dialog.exec();

  EXPECT_TRUE(annotationCallbackTriggered);
  EXPECT_TRUE(sourceLoadedFlag);
}

#include "KeshUI/KeshUI.h"
#include "KeshUI/KUIInterfaceElement.h"
#include "KeshUI/Widget/KUIButtonWidget.h"
#include "KeshUI/WidgetChildManager/KUIManagedButtonWidgetChildManager.h"

UKUIManagedButtonWidgetChildManager::UKUIManagedButtonWidgetChildManager(const class FObjectInitializer& oObjectInitializer)
	: Super(oObjectInitializer)
{
	eDisabled = EKUIBoolMatch::V_Any;
	eMouseOver = EKUIBoolMatch::V_Any;
	eDown = EKUIBoolMatch::V_Any;
	arOffsets.SetNum(8);

	for (uint8 idx = 0; idx < 8; ++idx)
		arOffsets[idx] = FVector2D::ZeroVector;
}

UKUIButtonWidget* UKUIManagedButtonWidgetChildManager::GetButton() const
{
	return Cast<UKUIButtonWidget>(cmWidget.Get());
}

void UKUIManagedButtonWidgetChildManager::SetStates(
	TEnumAsByte<EKUIBoolMatch::Value> stateDisabled,
	TEnumAsByte<EKUIBoolMatch::Value> stateMouseOver,
	TEnumAsByte<EKUIBoolMatch::Value> stateDown)
{
	eDisabled = stateDisabled;
	eMouseOver = stateMouseOver;
	eDown = stateDown;
}

void UKUIManagedButtonWidgetChildManager::SetOffset(
	FVector2D v2Offset,
	TEnumAsByte<EKUIBoolMatch::Value> stateDisabled,
	TEnumAsByte<EKUIBoolMatch::Value> stateMouseOver,
	TEnumAsByte<EKUIBoolMatch::Value> stateDown)
{
	for (uint8 bitMask = 0; bitMask < 8; ++bitMask)
	{
		bool skip = false;

		if ((bitMask & 1) && stateDisabled == EKUIBoolMatch::V_False) skip = true;
		if (!(bitMask & 1) && stateDisabled == EKUIBoolMatch::V_True) skip = true;
		if ((bitMask & 2) && stateMouseOver == EKUIBoolMatch::V_False) skip = true;
		if (!(bitMask & 2) && stateMouseOver == EKUIBoolMatch::V_True) skip = true;
		if ((bitMask & 4) && stateDown == EKUIBoolMatch::V_False) skip = true;
		if (!(bitMask & 4) && stateDown == EKUIBoolMatch::V_True) skip = true;

		if (!skip)
			arOffsets[bitMask] = v2Offset;
	}
}

void UKUIManagedButtonWidgetChildManager::Update()
{
	Super::Update();

	UKUIButtonWidget* pButton = GetButton();
	if (!pButton)
	{
		KUIErrorDebugUO("Null button");
		return;
	}

	if (!oChild.IsValid())
	{
		KUIErrorDebugUO("Null child");
		return;
	}

	bool bShouldShow = true;

	// Handle disabled state logic
	if (eDisabled != EKUIBoolMatch::V_Any)
	{
		bool bCurrentlyDisabled = pButton->IsDisabled();
		if (bCurrentlyDisabled)
		{
			if (eDisabled == EKUIBoolMatch::V_False)
				bShouldShow = false;
		}
		else
		{
			if (eDisabled == EKUIBoolMatch::V_True)
				bShouldShow = false;
		}
	}

	// Handle mouse-over state logic
	if (bShouldShow && eMouseOver != EKUIBoolMatch::V_Any)
	{
		bool bCurrentlyMouseOver = pButton->IsMouseOver();
		if (bCurrentlyMouseOver)
		{
			if (eMouseOver == EKUIBoolMatch::V_False)
				bShouldShow = false;
		}
		else
		{
			if (eMouseOver == EKUIBoolMatch::V_True)
				bShouldShow = false;
		}
	}

	// Handle pressed/down state logic
	if (bShouldShow && eDown != EKUIBoolMatch::V_Any)
	{
		bool bCurrentlyDown = pButton->IsDown();
		if (bCurrentlyDown)
		{
			if (eDown == EKUIBoolMatch::V_False)
				bShouldShow = false;
		}
		else
		{
			if (eDown == EKUIBoolMatch::V_True)
				bShouldShow = false;
		}
	}

	oChild->SetVisible(bShouldShow);

	uint8 index = 0;
	if (pButton->IsDisabled())  index |= 1;
	if (pButton->IsMouseOver()) index |= 2;
	if (pButton->IsDown())      index |= 4;

	oChild->SetLocationStruct(arOffsets[index]);
}

