// --- Base Task Node ---
class TaskNodeModel : public NodeDataModel {
public:
  TaskNodeModel() : _taskLabel("unnamed task") {}

  virtual ~TaskNodeModel() = default;

  QString caption() const override { return _taskLabel; }

  QString portLabel(PortType pt, PortIndex idx) const override {
    if (pt == PortType::In && idx >= 1) {
      return portLabels.at(idx - 1).label_;
    }
    return {};
  }

  bool showPortLabel(PortType pt, PortIndex idx) const override { return true; }

  QString objectName() const override { return QStringLiteral("Task"); }

  std::unique_ptr<NodeDataModel> duplicate() const override {
    return std::make_unique<TaskNodeModel>();
  }

  QJsonObject serialize() const override {
    QJsonObject obj;
    obj["type"] = objectName();
    return obj;
  }

  size_t portCount(PortType pt) const override {
    return (pt == PortType::In) ? portLabels.size() + 1 : 1;
  }

  void onUserInputChanged(QString const&) {}

  NodeDataType portDataType(PortType pt, PortIndex idx) const override {
    return (idx == 0) ? CtrlSignal{}.type()
                      : determinePortType(portLabels[idx - 1].kind_);
  }

  std::shared_ptr<NodeData> produce(PortIndex) override {
    return std::make_shared<CtrlSignal>();
  }

  void consume(std::shared_ptr<NodeData>, int) override {}

  QWidget* customWidget() override { return nullptr; }

  void setTaskLabel(QString const& label) override {
    _taskLabel = label;
  }

  QString getTaskLabel() const override {
    return _taskLabel;
  }

private:
  NodeDataType determinePortType(int kind) const {
    switch (kind) {
      case 1: return ShapeData{}.type();
      case 2: return ModelData{}.type();
      default: return FlowParam{}.type();
    }
  }

  QString _taskLabel;
};

