// Preserves current read functions by backing them up and setting defaults
void ILAPIENTRY iPreserveReadFuncs()
{
	// Save current function pointers
	GetcBackup = GetcProc;
	ReadBackup = ReadProc;
	SeekRBackup = SeekRProc;
	TellRBackup = TellRProc;
	iopenr_backup = iopenr;
	icloser_backup = icloser;

	// Install default reading functions
	ilResetRead();
	return;
}

// Restores previously preserved read functions
void ILAPIENTRY iRestoreReadFuncs()
{
	GetcProc = GetcBackup;
	ReadProc = ReadBackup;
	SeekRProc = SeekRBackup;
	TellRProc = TellRBackup;
	iopenr = iopenr_backup;
	icloser = icloser_backup;
	return;
}

// Preserves current write functions by backing them up and setting defaults
void ILAPIENTRY iPreserveWriteFuncs()
{
	// Save current function pointers
	PutcBackup = PutcProc;
	SeekWBackup = SeekWProc;
	TellWBackup = TellWProc;
	WriteBackup = WriteProc;
	iopenw_backup = iopenw;
	iclosew_backup = iclosew;

	// Install default writing functions
	ilResetWrite();
	return;
}

// Restores previously preserved write functions
void ILAPIENTRY iRestoreWriteFuncs()
{
	PutcProc = PutcBackup;
	SeekWProc = SeekWBackup;
	TellWProc = TellWBackup;
	WriteProc = WriteBackup;
	iopenw = iopenw_backup;
	iclosew = iclosew_backup;
	return;
}

// Default file opening for reading
ILHANDLE ILAPIENTRY iDefaultOpenR(ILconst_string FileName)
{
#ifndef _UNICODE
	return (ILHANDLE)fopen((char*)FileName, "rb");
#else
	#ifdef _WIN32
		return (ILHANDLE)_wfopen(FileName, L"rb");
	#else
		return (ILHANDLE)fopen((char*)FileName, "rb");
	#endif
#endif
}

// Default file closing for reading
void ILAPIENTRY iDefaultCloseR(ILHANDLE Handle)
{
	fclose((FILE*)Handle);
	return;
}

// Default EOF check for reading
ILboolean ILAPIENTRY iDefaultEof(ILHANDLE Handle)
{
	ILuint OriginalPosition, EndOfFilePosition;

	OriginalPosition = itell();
	iseek(0, IL_SEEK_END);
	EndOfFilePosition = itell();
	iseek(OriginalPosition, IL_SEEK_SET);

	if (itell() >= EndOfFilePosition)
		return IL_TRUE;
	return IL_FALSE;
}

// Default character reading
ILint ILAPIENTRY iDefaultGetc(ILHANDLE Handle)
{
	ILint CharacterValue;
	if (!CachingEnabled) {
		CharacterValue = fgetc((FILE*)Handle);
		if (CharacterValue == IL_EOF)
			ilSetError(IL_FILE_READ_ERROR);
	}
	else {
		CharacterValue = 0;
		if (iread(&CharacterValue, 1, 1) != 1)
			return IL_EOF;
	}
	return CharacterValue;
}

// Default block reading
ILint ILAPIENTRY iDefaultRead(void *Buffer, ILuint Size, ILuint Number, ILHANDLE Handle)
{
	return (ILint)fread(Buffer, Size, Number, (FILE*)Handle);
}

// Default seeking for reading
ILint ILAPIENTRY iDefaultRSeek(ILHANDLE Handle, ILint Offset, ILint Mode)
{
	return fseek((FILE*)Handle, Offset, Mode);
}

// Default seeking for writing
ILint ILAPIENTRY iDefaultWSeek(ILHANDLE Handle, ILint Offset, ILint Mode)
{
	return fseek((FILE*)Handle, Offset, Mode);
}

// Default tell position for reading
ILint ILAPIENTRY iDefaultRTell(ILHANDLE Handle)
{
	return ftell((FILE*)Handle);
}

// Default tell position for writing
ILint ILAPIENTRY iDefaultWTell(ILHANDLE Handle)
{
	return ftell((FILE*)Handle);
}

// Default file opening for writing
ILHANDLE ILAPIENTRY iDefaultOpenW(ILconst_string FileName)
{
#ifndef _UNICODE
	return (ILHANDLE)fopen((char*)FileName, "wb");
#else
	#ifdef _WIN32
		return (ILHANDLE)_wfopen(FileName, L"wb");
	#else
		return (ILHANDLE)fopen((char*)FileName, "wb");
	#endif
#endif
}

// Default file closing for writing
void ILAPIENTRY iDefaultCloseW(ILHANDLE Handle)
{
	fclose((FILE*)Handle);
	return;
}

// Default character writing
ILint ILAPIENTRY iDefaultPutc(ILubyte Char, ILHANDLE Handle)
{
	return fputc(Char, (FILE*)Handle);
}

// Default block writing
ILint ILAPIENTRY iDefaultWrite(const void *Buffer, ILuint Size, ILuint Number, ILHANDLE Handle)
{
	return (ILint)fwrite(Buffer, Size, Number, (FILE*)Handle);
}

// Reset to default reading functions
void ILAPIENTRY ilResetRead()
{
	ilSetRead(iDefaultOpenR, iDefaultCloseR, iDefaultEof, iDefaultGetc, 
				iDefaultRead, iDefaultRSeek, iDefaultRTell);
	return;
}

// Reset to default writing functions
void ILAPIENTRY ilResetWrite()
{
	ilSetWrite(iDefaultOpenW, iDefaultCloseW, iDefaultPutc,
				iDefaultWSeek, iDefaultWTell, iDefaultWrite);
	return;
}

// Set custom reading functions
void ILAPIENTRY ilSetRead(fOpenRProc Open, fCloseRProc Close, fEofProc Eof, fGetcProc Getc, fReadProc Read, fSeekRProc Seek, fTellRProc Tell)
{
	iopenr    = Open;
	icloser   = Close;
	EofProc   = Eof;
	GetcProc  = Getc;
	ReadProc  = Read;
	SeekRProc = Seek;
	TellRProc = Tell;
	return;
}

// Set custom writing functions
void ILAPIENTRY ilSetWrite(fOpenRProc Open, fCloseRProc Close, fPutcProc Putc, fSeekWProc Seek, fTellWProc Tell, fWriteProc Write)
{
	iopenw    = Open;
	iclosew   = Close;
	PutcProc  = Putc;
	WriteProc = Write;
	SeekWProc = Seek;
	TellWProc = Tell;
	return;
}

// Configure input source as a file
void iSetInputFile(ILHANDLE File)
{
	ieof  = iEofFile;
	igetc = iGetcFile;
	iread = iReadFile;
	iseek = iSeekRFile;
	itell = iTellRFile;
	FileReadHandle = File;
	ReadFileBase = itell();
}

// Configure input source as a memory lump
void iSetInputLump(const void *Lump, ILuint Size)
{
	ieof  = iEofLump;
	igetc = iGetcLump;
	iread = iReadLump;
	iseek = iSeekRLump;
	itell = iTellRLump;
	InputLumpPtr = Lump;
	InputLumpOffset = 0;
	InputLumpTotal = Size;
}

// Configure output destination as a file
void iSetOutputFile(ILHANDLE File)
{
	OutputLumpPtr = NULL;
	OutputLumpOffset = 0;
	OutputLumpTotal = 0;
	iputc  = iPutcFile;
	iseekw = iSeekWFile;
	itellw = iTellWFile;
	iwrite = iWriteFile;
	FileWriteHandle = File;
}

// Configure output destination as "fake" for size calculation
void iSetOutputFake(void)
{
	iputc  = iSizePutc;
	iseekw = iSizeSeek;
	itellw = iSizeTell;
	iwrite = iSizeWrite;
	return;
}

// Configure output destination as a memory lump
void iSetOutputLump(void *Lump, ILuint Size)
{
	if (Lump == NULL)
		return;
	iputc  = iPutcLump;
	iseekw = iSeekWLump;
	itellw = iTellWLump;
	iwrite = iWriteLump;
	OutputLumpPtr = Lump;
	OutputLumpOffset = 0;
	OutputLumpTotal = Size;
}

// Get current position in lump output
ILuint ILAPIENTRY ilGetLumpPos()
{
	if (OutputLumpPtr)
		return OutputLumpOffset;
	return 0;
}

// Formatted output function
ILuint ILAPIENTRY ilprintf(const char *Line, ...)
{
	char	Buffer[2048];
	va_list	VaLine;
	ILuint	i;
	va_start(VaLine, Line);
	vsprintf(Buffer, Line, VaLine);
	va_end(VaLine);
	i = ilCharStrLen(Buffer);
	iwrite(Buffer, 1, i);
	return i;
}

// Pad with zeros
void ipad(ILuint NumZeros)
{
	ILuint i = 0;
	for (; i < NumZeros; i++)
		iputc(0);
	return;
}

// Implementation of EOF check for file input
ILboolean ILAPIENTRY iEofFile(void)
{
	return EofProc((FILE*)FileReadHandle);
}

// Implementation of EOF check for lump input
ILboolean ILAPIENTRY iEofLump(void)
{
	if (InputLumpTotal)
		return (InputLumpOffset >= InputLumpTotal);
	return IL_FALSE;
}

// Implementation of character reading from file
ILint ILAPIENTRY iGetcFile(void)
{
	if (!CachingEnabled) {
		return GetcProc(FileReadHandle);
	}
	if (CacheIndex >= CacheSizeVal) {
		iPreCache(CacheSizeVal);
	}
	CacheBytesCount++;
	return CacheBuffer[CacheIndex++];
}

// Implementation of character reading from lump
ILint ILAPIENTRY iGetcLump(void)
{
	if (InputLumpTotal > 0) {
		if (InputLumpOffset + 1 > InputLumpTotal) {
			InputLumpOffset--;
			ilSetError(IL_FILE_READ_ERROR);
			return IL_EOF;
		}
	}
	return *((ILubyte*)InputLumpPtr + InputLumpOffset++);
}

// Implementation of block reading from file
ILuint ILAPIENTRY iReadFile(void *Buffer, ILuint Size, ILuint Number)
{
	ILuint	TotalBytes = 0, BytesCopied;
	ILuint	BuffSize = Size * Number;
	ILuint	NumRead;

	if (!CachingEnabled) {
		NumRead = ReadProc(Buffer, Size, Number, FileReadHandle);
		if (NumRead != Number)
			ilSetError(IL_FILE_READ_ERROR);
		return NumRead;
	}

	if (BuffSize < CacheSizeVal - CacheIndex) {
		memcpy(Buffer, CacheBuffer + CacheIndex, BuffSize);
		CacheIndex += BuffSize;
		CacheBytesCount += BuffSize;
		if (Size != 0)
			BuffSize /= Size;
		return BuffSize;
	}
	else {
		while (TotalBytes < BuffSize) {
			if (TotalBytes + CacheSizeVal - CacheIndex > BuffSize)
				BytesCopied = BuffSize - TotalBytes;
			else
				BytesCopied = CacheSizeVal - CacheIndex;
			memcpy((ILubyte*)Buffer + TotalBytes, CacheBuffer + CacheIndex, BytesCopied);
			TotalBytes += BytesCopied;
			CacheIndex += BytesCopied;
			if (TotalBytes < BuffSize) {
				iPreCache(CacheSizeVal);
			}
		}
	}
	CacheBytesCount = CacheIndex;
	if (Size != 0)
		TotalBytes /= Size;
	if (TotalBytes != Number)
		ilSetError(IL_FILE_READ_ERROR);
	return TotalBytes;
}

// Implementation of block reading from lump
ILuint ILAPIENTRY iReadLump(void *Buffer, const ILuint Size, const ILuint Number)
{
	ILuint i, ByteSize = IL_MIN( Size*Number, InputLumpTotal-InputLumpOffset);
	for (i = 0; i < ByteSize; i++) {
		*((ILubyte*)Buffer + i) = *((ILubyte*)InputLumpPtr + InputLumpOffset + i);
		if (InputLumpTotal > 0) {
			if (InputLumpOffset + i > InputLumpTotal) {
				InputLumpOffset += i;
				if (i != Number)
					ilSetError(IL_FILE_READ_ERROR);
				return i;
			}
		}
	}
	InputLumpOffset += i;
	if (Size != 0)
		i /= Size;
	if (i != Number)
		ilSetError(IL_FILE_READ_ERROR);
	return i;
}

// Pre-cache data for efficient reading
ILboolean iPreCache(ILuint Size)
{
	if (iread == iReadLump) {
		return IL_TRUE;
	}
	if (CacheBuffer) {
		ifree(CacheBuffer);
	}
	if (Size == 0) {
		Size = 1;
	}
	CacheBuffer = (ILubyte*)ialloc(Size);
	if (CacheBuffer == NULL) {
		return IL_FALSE;
	}
	CachingEnabled = IL_FALSE;
	CacheOriginPos = itell();
	CacheSizeVal = iread(CacheBuffer, 1, Size);
	if (CacheSizeVal != Size)
		ilGetError();
	CacheSizeVal = Size;
	CacheIndex = 0;
	CachingEnabled = IL_TRUE;
	CacheBytesCount = 0;
	return IL_TRUE;
}

// Un-cache data and restore original position
void iUnCache()
{
	if (!CachingEnabled)
		return;
	if (iread == iReadLump)
		return;
	CacheSizeVal = 0;
	CacheIndex = 0;
	if (CacheBuffer) {
		ifree(CacheBuffer);
		CacheBuffer = NULL;
	}
	CachingEnabled = IL_FALSE;
	iseek(CacheOriginPos + CacheBytesCount, IL_SEEK_SET);
	return;
}

// Implementation of seeking for file input
ILint ILAPIENTRY iSeekRFile(ILint Offset, ILuint Mode)
{
	if (Mode == IL_SEEK_SET)
		Offset += ReadFileBase;
	return SeekRProc(FileReadHandle, Offset, Mode);
}

// Implementation of seeking for lump input
ILint ILAPIENTRY iSeekRLump(ILint Offset, ILuint Mode)
{
	switch (Mode)
	{
		case IL_SEEK_SET:
			if (Offset > (ILint)InputLumpTotal)
				return 1;
			InputLumpOffset = Offset;
			break;
		case IL_SEEK_CUR:
			if (InputLumpOffset + Offset > InputLumpTotal)
				return 1;
			InputLumpOffset += Offset;
			break;
		case IL_SEEK_END:
			if (Offset > 0)
				return 1;
			if (abs(Offset) > (ILint)InputLumpTotal)
				return 1;
			InputLumpOffset = InputLumpTotal + Offset;
			break;
		default:
			return 1;
	}
	return 0;
}

// Implementation of tell position for file input
ILuint ILAPIENTRY iTellRFile(void)
{
	return TellRProc(FileReadHandle);
}

// Implementation of tell position for lump input
ILuint ILAPIENTRY iTellRLump(void)
{
	return InputLumpOffset;
}

// Get current file handle
ILHANDLE ILAPIENTRY iGetFile(void)
{
	return FileReadHandle;
}

// Get current lump pointer
const ILubyte* ILAPIENTRY iGetLump(void) {
	return (ILubyte*)InputLumpPtr;
}

// Implementation of character writing to file
ILint ILAPIENTRY iPutcFile(ILubyte Char)
{
	return PutcProc(Char, FileWriteHandle);
}

// Implementation of character writing to lump
ILint ILAPIENTRY iPutcLump(ILubyte Char)
{
	if (OutputLumpOffset >= OutputLumpTotal)
		return IL_EOF;
	*((ILubyte*)(OutputLumpPtr) + OutputLumpOffset++) = Char;
	return Char;
}

// Implementation of block writing to file
ILint ILAPIENTRY iWriteFile(const void *Buffer, ILuint Size, ILuint Number)
{
	ILuint NumWritten;
	NumWritten = WriteProc(Buffer, Size, Number, FileWriteHandle);
	if (NumWritten != Number) {
		ilSetError(IL_FILE_WRITE_ERROR);
		return 0;
	}
	return NumWritten;
}

// Implementation of block writing to lump
ILint ILAPIENTRY iWriteLump(const void *Buffer, ILuint Size, ILuint Number)
{
	ILuint SizeBytes = Size * Number;
	ILuint i = 0;
	for (; i < SizeBytes; i++) {
		if (OutputLumpTotal > 0) {
			if (OutputLumpOffset + i >= OutputLumpTotal) {
				ilSetError(IL_FILE_WRITE_ERROR);
				OutputLumpOffset += i;
				return i;
			}
		}
		*((ILubyte*)OutputLumpPtr + OutputLumpOffset + i) = *((ILubyte*)Buffer + i);
	}
	OutputLumpOffset += SizeBytes;
	return SizeBytes;
}

// Implementation of seeking for file output
ILint ILAPIENTRY iSeekWFile(ILint Offset, ILuint Mode)
{
	if (Mode == IL_SEEK_SET)
		Offset += WriteFileBase;
	return SeekWProc(FileWriteHandle, Offset, Mode);
}

// Implementation of seeking for lump output
ILint ILAPIENTRY iSeekWLump(ILint Offset, ILuint Mode)
{
	switch (Mode)
	{
		case IL_SEEK_SET:
			if (Offset > (ILint)OutputLumpTotal)
				return 1;
			OutputLumpOffset = Offset;
			break;
		case IL_SEEK_CUR:
			if (OutputLumpOffset + Offset > OutputLumpTotal)
				return 1;
			OutputLumpOffset += Offset;
			break;
		case IL_SEEK_END:
			if (Offset > 0)
				return 1;
			if (abs(Offset) > (ILint)OutputLumpTotal)
				return 1;
			OutputLumpOffset = OutputLumpTotal + Offset;
			break;
		default:
			return 1;
	}
