#include <bits/stdc++.h>
using namespace std;

// Generate m pairs by dividing into two segments
void generatePairs() {
    int totalRange, pairCount;
    cin >> totalRange >> pairCount;

    // Split pairs into two groups: roughly half and remaining
    int firstGroupSize = pairCount / 2;
    int secondGroupSize = pairCount - firstGroupSize;

    // Define first segment: starts at 1, spans 2*firstGroupSize numbers
    int firstStart = 1;
    int firstEnd = firstStart + 2 * firstGroupSize - 1;

    // Define second segment: immediately follows first segment
    int secondStart = firstEnd + 1;
    int secondEnd = secondStart + 2 * secondGroupSize - 1;

    // Verify the second segment fits within the total range
    assert(secondEnd <= totalRange);

    // Output pairs from first segment (moving inward)
    int leftPtr = firstStart;
    int rightPtr = firstEnd;
    for (int i = 0; i < firstGroupSize; ++i) {
        cout << leftPtr << ' ' << rightPtr << '\n';
        leftPtr++;
        rightPtr--;
    }

    // Output pairs from second segment (moving inward)
    int upperLeft = secondStart;
    int upperRight = secondEnd;
    for (int i = 0; i < secondGroupSize; ++i) {
        cout << upperLeft << ' ' << upperRight << '\n';
        upperLeft++;
        upperRight--;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);
    generatePairs();
    return 0;
}

