#include "averagecalculator.h"
#include <cmath>

// Renamed and restructured to avoid redundant includes and improve clarity
double AverageCalculator::autoResetError() const
{
    return m_autoResetError;
}

void AverageCalculator::setAutoResetError(double threshold)
{
    m_autoResetError = threshold;
}

bool AverageCalculator::enableAutoReset() const
{
    return m_enableAutoReset;
}

void AverageCalculator::setEnableAutoReset(bool flag)
{
    m_enableAutoReset = flag;
}

AverageCalculator::AverageCalculator() : average(0.0), count(0) {}

// Modified logic: uses temporary variable for clarity and avoids duplicate math.h includes
double AverageCalculator::proceed(double inputValue) {
    if (m_enableAutoReset && 
        inputValue != e172::Math::null && 
        (std::fabs(average - inputValue) / std::fabs(inputValue)) > m_autoResetError) {
        average = inputValue;
        count = 0; // Reset count when resetting average
    }

    // Update running average using accumulator pattern
    double newSum = average * count + inputValue;
    ++count;
    average = newSum / count;

    return average;
}

