class ColumnVectorTest : public testing::Test {
public:
    ColumnVectorTest() : _mem_pool(&_mem_tracker) {}
protected:
    void SetUp() override {}
    void TearDown() override {}
private:
    MemTracker _mem_tracker;
    MemPool _mem_pool;
