template <FieldType field_type>
void test_scalar_column_vector(std::shared_ptr<const TypeInfo> type_info,
                               const uint8_t* input_data,
                               size_t total_count) {
    using CppType = typename TypeTraits<field_type>::CppType;
    CppType* src_values = reinterpret_cast<CppType*>(const_cast<uint8_t*>(input_data));
    size_t element_size = sizeof(CppType);
    size_t initial_capacity = total_count / 2;

    std::unique_ptr<ColumnVectorBatch> vector_batch;
    ASSERT_TRUE(ColumnVectorBatch::create(initial_capacity, true, type_info, nullptr, &vector_batch).ok());

    // First write: copy first half
    size_t first_chunk_bytes = initial_capacity * element_size;
    memcpy(vector_batch->mutable_cell_ptr(0), src_values, first_chunk_bytes);
    vector_batch->set_null_bits(0, initial_capacity, false);

    // Resize to accommodate full data
    ASSERT_TRUE(vector_batch->resize(total_count).ok());

    // Second write: copy remaining elements
    size_t second_chunk_count = total_count - initial_capacity;
    size_t second_chunk_bytes = second_chunk_count * element_size;
    memcpy(vector_batch->mutable_cell_ptr(initial_capacity), src_values + initial_capacity, second_chunk_bytes);
    vector_batch->set_null_bits(initial_capacity, second_chunk_count, false);

    // Verify correctness
    for (size_t pos = 0; pos < total_count; ++pos) {
        if (type_info->type() == OLAP_FIELD_TYPE_VARCHAR || type_info->type() == OLAP_FIELD_TYPE_CHAR) {
            Slice* original_slice = reinterpret_cast<Slice*>(const_cast<uint8_t*>(input_data));
            Slice read_slice = *reinterpret_cast<const Slice*>(vector_batch->cell_ptr(pos));
            ASSERT_EQ(original_slice[pos].to_string(), read_slice.to_string()) << "Position: " << pos;
        } else {
            CppType expected = src_values[pos];
            CppType actual = *reinterpret_cast<const CppType*>(vector_batch->cell_ptr(pos));
            ASSERT_EQ(expected, actual) << "Mismatch at index " << pos;
        }
    }
}

template <FieldType item_field_type>
void test_array_column_vector(std::shared_ptr<const TypeInfo> array_type_info,
                              size_t num_arrays,
                              CollectionValue* array_data) {
    static_assert(item_field_type != OLAP_FIELD_TYPE_UNKNOWN, "Item type must be specified");
    using ItemCppType = typename TypeTraits<item_field_type>::CppType;
    size_t item_element_size = sizeof(ItemCppType);

    TabletColumn array_col(OLAP_FIELD_AGGREGATION_NONE, OLAP_FIELD_TYPE_ARRAY);
    TabletColumn item_col(OLAP_FIELD_AGGREGATION_NONE, item_field_type, true, 0, 0);
    array_col.add_sub_column(item_col);

    Field* field_obj = FieldFactory::create(array_col);

    size_t initial_array_capacity = num_arrays / 2;
    std::unique_ptr<ColumnVectorBatch> base_batch;
    ASSERT_TRUE(ColumnVectorBatch::create(initial_array_capacity, true, array_type_info, field_obj, &base_batch).ok());

    auto* array_batch = static_cast<ArrayColumnVectorBatch*>(base_batch.get());
    ColumnVectorBatch* items_batch = array_batch->elements();
    ColumnVectorBatch* offsets_batch = array_batch->offsets();

    // --- First batch write ---
    for (size_t i = 0; i < initial_array_capacity; ++i) {
        uint32_t len = array_data[i].length();
        memcpy(offsets_batch->mutable_cell_ptr(i + 1), &len, sizeof(uint32_t));
    }
    array_batch->set_null_bits(0, initial_array_capacity, false);
    array_batch->get_offset_by_length(0, initial_array_capacity);

    size_t first_item_count = array_batch->item_offset(initial_array_capacity);
    ASSERT_TRUE(items_batch->resize(first_item_count).ok());

    for (size_t i = 0; i < initial_array_capacity; ++i) {
        size_t offset = array_batch->item_offset(i);
        size_t byte_len = array_data[i].length() * item_element_size;
        memcpy(items_batch->mutable_cell_ptr(offset), array_data[i].data(), byte_len);
    }
    items_batch->set_null_bits(0, first_item_count, false);
    array_batch->prepare_for_read(0, initial_array_capacity, false);

    // --- Extend and second batch write ---
    ASSERT_TRUE(array_batch->resize(num_arrays).ok());

    for (size_t i = initial_array_capacity; i < num_arrays; ++i) {
        uint32_t len = array_data[i].length();
        memcpy(offsets_batch->mutable_cell_ptr(i + 1), &len, sizeof(uint32_t));
    }
    array_batch->set_null_bits(initial_array_capacity, num_arrays - initial_array_capacity, false);
    array_batch->get_offset_by_length(initial_array_capacity, num_arrays - initial_array_capacity);

    size_t total_items = array_batch->item_offset(num_arrays);
    ASSERT_TRUE(items_batch->resize(total_items).ok());

    for (size_t i = initial_array_capacity; i < num_arrays; ++i) {
        size_t offset = array_batch->item_offset(i);
        size_t byte_len = array_data[i].length() * item_element_size;
        memcpy(items_batch->mutable_cell_ptr(offset), array_data[i].data(), byte_len);
    }

    size_t second_item_count = total_items - first_item_count;
    items_batch->set_null_bits(first_item_count, second_item_count, false);
    array_batch->prepare_for_read(0, num_arrays, false);

    // Final validation
    for (size_t idx = 0; idx < num_arrays; ++idx) {
        ASSERT_TRUE(array_type_info->equal(&array_data[idx], array_batch->cell_ptr(idx)))
                << "Array mismatch at index " << idx;
    }

    delete field_obj;
}

TEST_F(ColumnVectorTest, scalar_column_vector_test) {
    {
        constexpr size_t count = 1024;
        auto* buffer = new uint8_t[count];
        for (size_t i = 0; i < count; ++i) {
            buffer[i] = static_cast<uint8_t>(i);
        }
        auto ti = get_scalar_type_info(OLAP_FIELD_TYPE_TINYINT);
        test_scalar_column_vector<OLAP_FIELD_TYPE_TINYINT>(ti, buffer, count);
        delete[] buffer;
    }

    {
        constexpr size_t count = 1024;
        auto* char_slices = new Slice[count];
        for (size_t i = 0; i < count; ++i) {
            set_column_value_by_type(OLAP_FIELD_TYPE_CHAR, static_cast<int>(i),
                                     reinterpret_cast<char*>(&char_slices[i]), &_mem_pool, 8);
        }
        auto ti = get_scalar_type_info(OLAP_FIELD_TYPE_CHAR);
        test_scalar_column_vector<OLAP_FIELD_TYPE_CHAR>(ti, reinterpret_cast<uint8_t*>(char_slices), count);
        delete[] char_slices;
    }
}

TEST_F(ColumnVectorTest, array_column_vector_test) {
    constexpr size_t num_arrays = 1024;
    constexpr size_t num_items = num_arrays * 3;

    {
        auto* arrays = new CollectionValue[num_arrays];
        bool null_flags[3] = {false, false, false};
        auto* items_buffer = new uint8_t[num_items];

        memset(null_flags, 0, sizeof(null_flags));
        for (size_t i = 0; i < num_items; ++i) {
            items_buffer[i] = static_cast<uint8_t>(i);
            if (i % 3 == 0) {
                size_t arr_idx = i / 3;
                arrays[arr_idx].set_data(reinterpret_cast<ItemValue*>(items_buffer + i));
                arrays[arr_idx].set_null_signs(null_flags);
                arrays[arr_idx].set_length(3);
            }
        }

        auto type_info = ArrayTypeInfoResolver::instance()->get_type_info(OLAP_FIELD_TYPE_TINYINT);
        test_array_column_vector<OLAP_FIELD_TYPE_TINYINT>(type_info, num_arrays, arrays);

        // Test hash_code method on CollectionValue
        type_info->hash_code(arrays, 0);

        delete[] arrays;
        delete[] items_buffer;
    }
}

