#include <vector>
#include <string>

class Solution {
public:
    std::string longestCommonPrefix(std::vector<std::string>& strs) {
        // Handle edge cases: empty input or single string
        if (strs.empty()) return "";
        if (strs.size() == 1) return strs[0];

        // Check for any empty string in the list
        for (const auto& s : strs) {
            if (s.empty()) return "";
        }

        // Start with the first two strings to find initial common prefix
        int prefixLen = 0;
        while (prefixLen < strs[0].size() && 
               prefixLen < strs[1].size() && 
               strs[0][prefixLen] == strs[1][prefixLen]) {
            prefixLen++;
        }

        // If no common prefix found between first two strings
        if (prefixLen == 0) return "";

        // Extend the check to remaining strings
        for (int i = 2; i < strs.size(); ++i) {
            // Adjust prefix length if current string is shorter
            if (strs[i].size() < static_cast<size_t>(prefixLen)) {
                prefixLen = static_cast<int>(strs[i].size());
            }

            // Reduce prefix length until it matches current string's prefix
            while (prefixLen > 0 && strs[i][prefixLen - 1] != strs[0][prefixLen - 1]) {
                prefixLen--;
            }

            // Early termination if no common prefix remains
            if (prefixLen == 0) return "";
        }

        return strs[0].substr(0, prefixLen);
    }
};

