#include "include/printer.h"

namespace JSON {
    // Helper function to determine if a value is of a specific type
    bool isType(const Value& val, ValueType type) {
        return val.getType() == type;
    }

    void Printer::dispatchType(const Value &val, std::ostringstream &out) {
        switch (val.getType()) {
            case JSON_OBJECT:
                printObject(val, out);
                break;
            case JSON_ARRAY:
                printArray(val, out);
                break;
            case JSON_NUMBER:
                printNumber(val, out);
                break;
            case JSON_BOOL:
                printBoolean(val, out);
                break;
            case JSON_STRING:
                printString(val, out);
                break;
            case EXT_BINARY:
                printBinary(val, out);
                break;
            case JSON_NULL:
                out << "null";
                break;
        }
    }

    void Printer::printObject(const Value &val, std::ostringstream &out) {
        const auto& obj = val.as<Object>();
        out << "{";
        size_t count = 0;
        for (const auto& pair : obj) {
            if (count > 0) {
                out << ",";
            }
            out << "\"";
            out << pair.first;
            out << "\"";
            out << ":";
            dispatchType(pair.second, out);
            ++count;
        }
        out << "}";
    }

    void Printer::printArray(const Value &val, std::ostringstream &out) {
        const auto& arr = val.as<Array>();
        out << "[";
        size_t idx = 0;
        for (const auto& item : arr) {
            if (idx > 0) {
                out << ",";
            }
            dispatchType(item, out);
            ++idx;
        }
        out << "]";
    }

    void Printer::printNumber(const Value &val, std::ostringstream &out) {
        double num = val.as<double>();
        out << num;
    }

    void Printer::printBoolean(const Value &val, std::ostringstream &out) {
        bool flag = val.as<bool>();
        out << (flag ? "true" : "false");
    }

    void Printer::printString(const Value &val, std::ostringstream &out) {
        std::string str = val.as<std::string>();
        out << "\"";
        out << str;
        out << "\"";
    }

    void Printer::printBinary(const Value &val, std::ostringstream &out) {
        std::string binData = val.as<std::string>();
        size_t len = binData.length();
        out << "<<binary, size: ";
        out << len;
        out << " bytes>>";
    }

    void Printer::print(const Value val, std::ostringstream &out) {
        dispatchType(val, out);
    }

    std::string Printer::print(const Value val) {
        std::ostringstream oss;
        dispatchType(val, oss);
        return oss.str();
    }

    void PrettyPrinter::printIndent(std::ostringstream &out) {
        for (unsigned int i = 0; i < currentIndent; ++i) {
            out << ' ';
        }
    }

    void PrettyPrinter::printArray(const Value &value, std::ostringstream &out) {
        const auto& arr = value.as<Array>();
        out << "[";
        size_t pos = 0;
        for (const auto& item : arr) {
            if (pos > 0) {
                out << ", ";
            }
            dispatchType(item, out);
            ++pos;
        }
        out << "]";
    }

    void PrettyPrinter::printObject(const Value &value, std::ostringstream &out) {
        currentIndent += indentDepth;
        out << "{\n";
        const auto& obj = value.as<Object>();
        size_t index = 0;
        for (const auto& pair : obj) {
            if (index > 0) {
                out << ",\n";
            }
            printIndent(out);
            out << "\"";
            out << pair.first;
            out << "\"";
            out << ": ";
            dispatchType(pair.second, out);
            ++index;
        }
        currentIndent -= indentDepth;
        out << "\n";
        printIndent(out);
        out << "}";
    }
} // End namespace JSON

