#include "GLTypeUtils.hpp"
using namespace gut;

// Convert image data format to corresponding OpenGL enum
GLenum gut::imageDataFormatToGLEnum(Image::DataFormat dataFormat)
{
    GLenum result = 0;

    if (dataFormat == Image::DataFormat::GRAY) {
        result = GL_RED;
    } else if (dataFormat == Image::DataFormat::RGB) {
        result = GL_RGB;
    } else if (dataFormat == Image::DataFormat::RGBA) {
        result = GL_RGBA;
    } else {
        throw std::runtime_error("ERROR: imageDataFormatToGLEnum(): image data format to GLEnum conversion failed");
    }

    return result;
}

// Convert image data type to corresponding OpenGL enum
GLenum gut::imageDataTypeToGLEnum(Image::DataType dataType)
{
    GLenum result = 0;

    if (dataType == Image::DataType::U8) {
        result = GL_UNSIGNED_BYTE;
    } else if (dataType == Image::DataType::U16) {
        result = GL_UNSIGNED_SHORT;
    } else if (dataType == Image::DataType::F32) {
        result = GL_FLOAT;
    } else {
        throw std::runtime_error("ERROR: imageDataTypeToGLEnum(): image data type to GLEnum conversion failed");
    }

    return result;
}

// Convert OpenGL channel format enum to image data format
Image::DataFormat gut::glEnumToImageDataFormat(GLenum channelFormat)
{
    Image::DataFormat result = Image::DataFormat::GRAY; // default initialization

    switch (channelFormat) {
        case GL_RED:
        case GL_R8:
        case GL_R8I:
        case GL_R8UI:
        case GL_R16:
        case GL_R16I:
        case GL_R16UI:
        case GL_R16F:
        case GL_R32I:
        case GL_R32UI:
        case GL_R32F:
            result = Image::DataFormat::GRAY;
            break;
        case GL_RGB:
        case GL_RGB8:
        case GL_RGB8I:
        case GL_RGB8UI:
        case GL_RGB16:
        case GL_RGB16I:
        case GL_RGB16UI:
        case GL_RGB16F:
        case GL_RGB32I:
        case GL_RGB32UI:
        case GL_RGB32F:
            result = Image::DataFormat::RGB;
            break;
        case GL_RGBA:
        case GL_RGBA2:
        case GL_RGBA4:
        case GL_RGBA12:
        case GL_RGBA8:
        case GL_RGBA8I:
        case GL_RGBA8UI:
        case GL_RGBA8_SNORM:
        case GL_RGBA16:
        case GL_RGBA16I:
        case GL_RGBA16UI:
        case GL_RGBA16F:
        case GL_RGBA16_SNORM:
        case GL_RGBA32I:
        case GL_RGBA32UI:
        case GL_RGBA32F:
            result = Image::DataFormat::RGBA;
            break;
        default:
            throw std::runtime_error("ERROR: glEnumToImageDataFormat(): Unknown GL channel format");
    }

    return result;
}

// Convert OpenGL data type enum to image data type
Image::DataType gut::glEnumToImageDataType(GLenum dataType)
{
    Image::DataType result = Image::DataType::U8; // default initialization

    switch (dataType) {
        case GL_UNSIGNED_BYTE:
            result = Image::DataType::U8;
            break;
        case GL_UNSIGNED_SHORT:
            result = Image::DataType::U16;
            break;
        case GL_FLOAT:
            result = Image::DataType::F32;
            break;
        default:
            throw std::runtime_error("ERROR: glEnumToImageDataType(): GLEnum conversion to image data type failed");
    }

    return result;
}

// Get size in bytes for a given OpenGL data type
size_t gut::glDataTypeSize(GLenum dataType)
{
    size_t result = 0;

    if (dataType == GL_UNSIGNED_BYTE) {
        result = 1;
    } else if (dataType == GL_UNSIGNED_SHORT) {
        result = 2;
    } else if (dataType == GL_FLOAT) {
        result = 4;
    } else {
        throw std::runtime_error("ERROR: glDataTypeSize(): Unknown GL data type");
    }

    return result;
}

// Determine number of channels from OpenGL channel format enum
int gut::glNumberOfChannels(GLenum channelFormat)
{
    int numChannels = 0;

    switch (channelFormat) {
        case GL_RED:
        case GL_R8:
        case GL_R8I:
        case GL_R8UI:
        case GL_R16:
        case GL_R16I:
        case GL_R16UI:
        case GL_R16F:
        case GL_R32I:
        case GL_R32UI:
        case GL_R32F:
            numChannels = 1;
            break;
        case GL_RG:
        case GL_RG8:
        case GL_RG8I:
        case GL_RG8UI:
        case GL_RG16:
        case GL_RG16I:
        case GL_RG16UI:
        case GL_RG16F:
        case GL_RG32I:
        case GL_RG32UI:
        case GL_RG32F:
            numChannels = 2;
            break;
        case GL_RGB:
        case GL_RGB8:
        case GL_RGB8I:
        case GL_RGB8UI:
        case GL_RGB16:
        case GL_RGB16I:
        case GL_RGB16UI:
        case GL_RGB16F:
        case GL_RGB32I:
        case GL_RGB32UI:
        case GL_RGB32F:
            numChannels = 3;
            break;
        case GL_RGBA:
        case GL_RGBA2:
        case GL_RGBA4:
        case GL_RGBA12:
        case GL_RGBA8:
        case GL_RGBA8I:
        case GL_RGBA8UI:
        case GL_RGBA8_SNORM:
        case GL_RGBA16:
        case GL_RGBA16I:
        case GL_RGBA16UI:
        case GL_RGBA16F:
        case GL_RGBA16_SNORM:
        case GL_RGBA32I:
        case GL_RGBA32UI:
        case GL_RGBA32F:
            numChannels = 4;
            break;
        default:
            throw std::runtime_error("ERROR: glNumberOfChannels(): Unknown GL channel format");
    }

    return numChannels;
}

