void SCSVImportOptions::Construct(const FArguments& InArgs)
{
	WidgetWindow = InArgs._WidgetWindow;

	// Populate available import types
	TSharedPtr<ECSVImportType> dtPtr = MakeShareable(new ECSVImportType(ECSVImportType::ECSV_DataTable));
	TypeChoices.Add(dtPtr);
	TypeChoices.Add(MakeShareable(new ECSVImportType(ECSVImportType::ECSV_CurveTable)));
	TypeChoices.Add(MakeShareable(new ECSVImportType(ECSVImportType::ECSV_CurveFloat)));
	TypeChoices.Add(MakeShareable(new ECSVImportType(ECSVImportType::ECSV_CurveVector)));

	// Discover valid row struct types
	UScriptStruct* BaseRowStruct = FindObjectChecked<UScriptStruct>(ANY_PACKAGE, TEXT("TableRowBase"));
	if (BaseRowStruct)
	{
		for (TObjectIterator<UScriptStruct> It; It; ++It)
		{
			UScriptStruct* Candidate = *It;
			bool bIsSubclass = Candidate->IsChildOf(BaseRowStruct) && (Candidate != BaseRowStruct);
			bool bIsUdStruct = Candidate->IsA<UUserDefinedStruct>();
			bool bNotTransient = (Candidate->GetOutermost() != GetTransientPackage());

			if ((bIsSubclass || bIsUdStruct) && bNotTransient)
			{
				StructList.Add(Candidate);
			}
		}
	}

	// Build UI layout
	this->ChildSlot
	[
		SNew(SBorder)
		.BorderImage(FEditorStyle::GetBrush(TEXT("Menu.Background")))
		.Padding(10)
		[
			SNew(SVerticalBox)

			// Import type label
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(STextBlock)
				.Text(LOCTEXT("ChooseAssetType", "Import As:"))
			]

			// Import type dropdown
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SAssignNew(TypeSelector, SComboBox<TSharedPtr<ECSVImportType>>)
				.OptionsSource(&TypeChoices)
				.OnGenerateWidget(this, &SCSVImportOptions::BuildTypeItemWidget)
				[
					SNew(STextBlock)
					.Text(this, &SCSVImportOptions::GetCurrentTypeLabel)
				]
			]

			// Row struct label
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(STextBlock)
				.Text(LOCTEXT("ChooseRowType", "Choose DataTable Row Type:"))
				.Visibility(this, &SCSVImportOptions::ShouldShowRowOptions)
			]

			// Row struct dropdown
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SAssignNew(StructSelector, SComboBox<UScriptStruct*>)
				.OptionsSource(&StructList)
				.OnGenerateWidget(this, &SCSVImportOptions::BuildStructItemWidget)
				.Visibility(this, &SCSVImportOptions::ShouldShowRowOptions)
				[
					SNew(STextBlock)
					.Text(this, &SCSVImportOptions::GetCurrentStructLabel)
				]
			]

			// Curve interpolation label
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(STextBlock)
				.Text(LOCTEXT("ChooseCurveType", "Choose Curve Interpolation Type:"))
				.Visibility(this, &SCSVImportOptions::ShouldShowCurveOptions)
			]

			// Curve interpolation dropdown
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SAssignNew(CurveModeSelector, SComboBox<CurveInterpModePtr>)
				.OptionsSource(&CurveModes)
				.OnGenerateWidget(this, &SCSVImportOptions::BuildCurveModeWidget)
				.Visibility(this, &SCSVImportOptions::ShouldShowCurveOptions)
				[
					SNew(STextBlock)
					.Text(this, &SCSVImportOptions::GetCurrentCurveModeLabel)
				]
			]

			// OK / Cancel buttons
			+SVerticalBox::Slot()
			.AutoHeight()
			[
				SNew(SHorizontalBox)
				+SHorizontalBox::Slot()
				.AutoWidth()
				[
					SNew(SButton)
					.Text(LOCTEXT("OK", "OK"))
					.OnClicked(this, &SCSVImportOptions::OnConfirm)
				]
				+SHorizontalBox::Slot()
				.AutoWidth()
				[
					SNew(SButton)
					.Text(LOCTEXT("Cancel", "Cancel"))
					.OnClicked(this, &SCSVImportOptions::OnAbort)
				]
			]
		]
	];

	// Initialize default selections
	TypeSelector->SetSelectedItem(dtPtr);

	// Pre-populate curve interpolation modes
	CurveModes.Add(MakeShareable(new ERichCurveInterpMode(ERichCurveInterpMode::RCIM_Constant)));
	CurveModes.Add(MakeShareable(new ERichCurveInterpMode(ERichCurveInterpMode::RCIM_Linear)));
	CurveModes.Add(MakeShareable(new ERichCurveInterpMode(ERichCurveInterpMode::RCIM_Cubic)));
}

