FString SCSVImportOptions::GetCurveModeLabel(CurveInterpModePtr ModePtr) const
{
	FString ModeLabel;
	switch (*ModePtr)
	{
	case ERichCurveInterpMode::RCIM_Constant:
		ModeLabel = TEXT("Constant");
		break;
	case ERichCurveInterpMode::RCIM_Linear:
		ModeLabel = TEXT("Linear");
		break;
	case ERichCurveInterpMode::RCIM_Cubic:
		ModeLabel = TEXT("Cubic");
		break;
	default:
		ModeLabel = TEXT("Unknown");
		break;
	}
	return ModeLabel;
}

TSharedRef<SWidget> SCSVImportOptions::BuildCurveModeWidget(CurveInterpModePtr ModePtr)
{
	return SNew(STextBlock).Text(FText::FromString(GetCurveModeLabel(ModePtr)));
}

FReply SCSVImportOptions::OnConfirm()
{
	SelectedStructRef = StructSelector->GetSelectedItem();
	CurrentImportType = *TypeSelector->GetSelectedItem();

	if (CurveModeSelector->GetSelectedItem().IsValid())
	{
		CurrentCurveMode = *CurveModeSelector->GetSelectedItem();
	}

	bProceed = true;

	if (WidgetWindow.IsValid())
	{
		WidgetWindow.Pin()->RequestDestroyWindow();
	}

	return FReply::Handled();
}

FReply SCSVImportOptions::OnAbort()
{
	bProceed = false;

	if (WidgetWindow.IsValid())
	{
		WidgetWindow.Pin()->RequestDestroyWindow();
	}

	return FReply::Handled();
}

FText SCSVImportOptions::GetCurrentTypeLabel() const
{
	TSharedPtr<ECSVImportType> Selected = TypeSelector->GetSelectedItem();
	return Selected.IsValid()
		? FText::FromString(GetTypeLabel(Selected))
		: FText::GetEmpty();
}

FText SCSVImportOptions::GetCurrentStructLabel() const
{
	UScriptStruct* Selected = StructSelector->GetSelectedItem();
	return Selected
		? FText::FromString(Selected->GetName())
		: FText::GetEmpty();
}

FText SCSVImportOptions::GetCurrentCurveModeLabel() const
{
	CurveInterpModePtr Selected = CurveModeSelector->GetSelectedItem();
	return Selected.IsValid()
		? FText::FromString(GetCurveModeLabel(Selected))
		: FText::GetEmpty();
}

