// Global state for resource trends and colors
static Font* s_font = nullptr;

enum class TrendDirection {
    STEADY,
    INCREASING,
    DECREASING
};

static TrendDirection s_commonMetalsTrend = TrendDirection::STEADY;
static TrendDirection s_commonMineralsTrend = TrendDirection::STEADY;
static TrendDirection s_rareMetalsTrend = TrendDirection::STEADY;
static TrendDirection s_rareMineralsTrend = TrendDirection::STEADY;

static Color_4ub s_commonMetalsColor = COLOR_WHITE;
static Color_4ub s_commonMineralsColor = COLOR_WHITE;
static Color_4ub s_rareMetalsColor = COLOR_WHITE;
static Color_4ub s_rareMineralsColor = COLOR_WHITE;

// Helper: map trend to icon offset X coordinate
static float getIconOffsetX(TrendDirection t) {
    switch (t) {
        case TrendDirection::STEADY:     return 16.0f;
        case TrendDirection::INCREASING: return 8.0f;
        case TrendDirection::DECREASING: return 0.0f;
        default:                         return 16.0f; // fallback
    }
}

// Helper: map trend to text color
static Color_4ub getColorForTrend(TrendDirection t) {
    switch (t) {
        case TrendDirection::STEADY:     return {255, 255, 255, 255};
        case TrendDirection::INCREASING: return {0,   185, 0,   255};
        case TrendDirection::DECREASING: return {255, 0,   0,   255};
        default:                         return {255, 255, 255, 255}; // fallback
    }
}

// Compare two values and determine trend direction
static TrendDirection evaluateTrend(int current, int previous) {
    if (current > previous) return TrendDirection::INCREASING;
    if (current < previous) return TrendDirection::DECREASING;
    return TrendDirection::STEADY;
}

// ResourceBreakdownPanel implementation
ResourceBreakdownPanel::ResourceBreakdownPanel() : mIcons("ui/icons.png") {
    size(270, 80);

