        "ui/skin/window_bottom_left.png",
        "ui/skin/window_bottom_middle.png",
        "ui/skin/window_bottom_right.png"
    };

    for (const auto& path : skinPaths) {
        mSkin.emplace_back(path);
    }

    s_font = Utility<FontManager>::get().font(constants::FONT_PRIMARY, constants::FONT_PRIMARY_NORMAL);
