void ResourceBreakdownPanel::resourceCheck() {
    s_commonMetalsTrend = evaluateTrend(mPlayerResources->commonMetals(), mPreviousResources.commonMetals());
    s_commonMineralsTrend = evaluateTrend(mPlayerResources->commonMinerals(), mPreviousResources.commonMinerals());
    s_rareMetalsTrend = evaluateTrend(mPlayerResources->rareMetals(), mPreviousResources.rareMetals());
    s_rareMineralsTrend = evaluateTrend(mPlayerResources->rareMinerals(), mPreviousResources.rareMinerals());

    s_commonMetalsColor = getColorForTrend(s_commonMetalsTrend);
    s_commonMineralsColor = getColorForTrend(s_commonMineralsTrend);
    s_rareMetalsColor = getColorForTrend(s_rareMetalsTrend);
    s_rareMineralsColor = getColorForTrend(s_rareMineralsTrend);
}

void ResourceBreakdownPanel::update() {
    Renderer& renderer = Utility<Renderer>::get();

    // Draw background panel
    renderer.drawImageRect(rect().x(), rect().y(), rect().width(), rect().height(), mSkin);

    // Define layout constants
    const float baseY = rect().y();
    const float labelX = 28.0f;
    const float valueXBase = 200.0f;
    const float diffX = 235.0f;
    const float iconStartX = 5.0f;
    const float trendIconX = 220.0f;

    // Resource labels and values
    struct ResourceInfo {
        const char* label;
        int (*getter)(void);
        TrendDirection& trendRef;
        Color_4ub& colorRef;
    };

    ResourceInfo resources[] = {
        {"Common Metals",    &PlayerResources::commonMetals,    s_commonMetalsTrend,    s_commonMetalsColor},
        {"Rare Metals",      &PlayerResources::rareMetals,      s_rareMetalsTrend,      s_rareMetalsColor},
        {"Common Minerals",  &PlayerResources::commonMinerals,  s_commonMineralsTrend,  s_commonMineralsColor},
        {"Rare Minerals",    &PlayerResources::rareMinerals,    s_rareMineralsTrend,    s_rareMineralsColor}
    };

    // Draw icons and labels
    for (int i = 0; i < 4; ++i) {
        float yPos = baseY + 5.0f + static_cast<float>(i * 18);
        float iconU = getIconOffsetX(resources[i].trendRef);

        // Draw small icon at fixed vertical positions
        renderer.drawSubImage(mIcons, iconStartX, yPos, iconU, 64.0f, 16.0f, 16.0f);
        renderer.drawText(*s_font, resources[i].label, labelX, yPos, 255, 255, 255);

        // Draw current value (right-aligned)
        std::string valStr = string_format("%i", (mPlayerResources->*(resources[i].getter))());
        float valWidth = s_font->width(valStr);
        renderer.drawText(*s_font, valStr, valueXBase - valWidth, yPos, 255, 255, 255);

        // Draw trend indicator icon
        renderer.drawSubImage(mIcons, trendIconX, yPos + 3.0f, iconU, 64.0f, 8.0f, 8.0f);

        // Draw difference with colored text
        int prev = (mPreviousResources.*resources[i].getter)();
        int curr = (mPlayerResources->*(resources[i].getter))();
        int delta = curr - prev;
        std::string diffStr = string_format("%+i", delta);
        renderer.drawText(*s_font, diffStr, diffX, yPos,
                          resources[i].colorRef.red(),
                          resources[i].colorRef.green(),
                          resources[i].colorRef.blue());
    }
}

