extern "C"
{
    // CMSIS-RTOS time-related declarations
    extern std::uint32_t os_time;
    extern std::uint32_t const os_trv;
    extern std::uint32_t os_tick_val(void);
    extern std::uint32_t os_tick_ovf(void);
}

namespace std
{
namespace chrono_impl
{
    // Atomic storage for tracking overflow state:
    // - Upper 4 bits: most significant bits of os_time (bits [31:28])
    // - Lower 28 bits: overflow count
    static atomic<std::uint32_t> overflow_tracker{0};

    // Retrieve current system clock ticks, accounting for timer overflows.
    // Must be called frequently enough to avoid missing overflows:
    // at least once every 2^28 os_time intervals.
    static std::int64_t get_system_clock_ticks()
    {
        std::uint32_t tick1, time1, tick2, time2;

        // Ensure consistent snapshot by re-checking until stable
        do
        {
            atomic_thread_fence(memory_order_seq_cst);
            tick1 = os_tick_val();
            time1 = os_tick_ovf() ? os_time + 1 : os_time;
            atomic_thread_fence(memory_order_seq_cst);
            tick2 = os_tick_val();
            time2 = os_tick_ovf() ? os_time + 1 : os_time;
        }
        while (tick2 > tick1 || time1 != time2);

        // Extract high-order bits from the timestamp
        std::uint32_t msb = time1 & 0xF0000000U;
        std::uint32_t overflow_count;

        // Update overflow counter atomically if MSB changed
        while (true)
        {
            std::uint32_t current_state = overflow_tracker.load(memory_order_relaxed);
            std::uint32_t stored_msb = current_state & 0xF0000000U;
            overflow_count = current_state & 0x0FFFFFFFU;

            if (msb == stored_msb)
                break; // No change in overflow

            // Detect wrap-around: if new MSB < previous MSB, increment overflow count
            if (msb < stored_msb)
                ++overflow_count;

            std::uint32_t new_state = (msb & 0xF0000000U) | (overflow_count & 0x0FFFFFFFU);
            if (overflow_tracker.compare_exchange_weak(current_state, new_state,
                                                       memory_order_acq_rel,
                                                       memory_order_relaxed))
                break;
        }

        return (static_cast<std::uint64_t>(overflow_count) << 32 | time1) * (os_trv + 1) + tick1;
    }
} // namespace chrono_impl

// ----=====================================================================----
//     system_clock implementation
// ----=====================================================================----
system_clock::time_point system_clock::now()
{
    static_assert(WEOS_SYSTEM_CLOCK_FREQUENCY % WEOS_SYSTICK_FREQUENCY == 0,
                  "System clock frequency must be an integer multiple of SysTick");

    constexpr std::uint64_t ticks_per_interval =
        WEOS_SYSTEM_CLOCK_FREQUENCY / WEOS_SYSTICK_FREQUENCY;

    return time_point(duration(chrono_impl::get_system_clock_ticks() / ticks_per_interval));
}

// ----=====================================================================----
//     high_resolution_clock implementation
// ----=====================================================================----
high_resolution_clock::time_point high_resolution_clock::now()
{
    return time_point(duration(chrono_impl::get_system_clock_ticks()));
}

} // namespace std

