using namespace std;

class Solution {
private:
    int rows;
    int cols;
    int targetColor;
    int originalColor;
    // Direction vectors: up, down, left, right
    int directions[4][2] = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

public:
    vector<vector<int>> performFloodFill(vector<vector<int>>& grid, int row, int col, int fillColor) {
        rows = grid.size();
        if (rows == 0) {
            return grid;
        }

        cols = grid[0].size();
        if (cols == 0) {
            return grid;
        }

        // Check if starting position is valid
        if (!isValidPosition(row, col)) {
            return grid;
        }

        targetColor = fillColor;
        originalColor = grid[row][col];

        // If the new color is the same as the original, no changes needed
        if (targetColor == originalColor) {
            return grid;
        }

        fillRegion(grid, row, col);
        return grid;
    }

private:
    void fillRegion(vector<vector<int>>& image, int x, int y) {
        // Base case: stop if current cell doesn't match original color
        if (image[x][y] != originalColor) {
            return;
        }

        // Update current cell with new color
        image[x][y] = targetColor;

        // Explore all four adjacent cells
        for (int i = 0; i < 4; ++i) {
            int nextRow = x + directions[i][0];
            int nextCol = y + directions[i][1];

            // Recursively fill valid adjacent cells with original color
            if (isValidPosition(nextRow, nextCol) && image[nextRow][nextCol] == originalColor) {
                fillRegion(image, nextRow, nextCol);
            }
        }
    }

    bool isValidPosition(int x, int y) const {
        return x >= 0 && x < rows && y >= 0 && y < cols;
    }
};

