#pragma pack(push, 1)
struct NVX2FileHeader
{
    U32 fileSignature;
    U32 primitiveGroupCount;
    U32 vertexCountTotal;
    U32 vertexStrideInBytes;
    U32 indexCountTotal; // Note: stored as triangle count in file
    U32 edgeCount;
    U32 activeVertexAttributes;
};
struct NVX2GroupData
{
    U32 startVertexIndex;
    U32 vertexRangeSize;
    U32 firstTriangleOffset; // in triangles
    U32 triangleCount;
    U32 firstEdgeIndex;
    U32 edgeCountInGroup;
};
#pragma pack(pop)

enum class ENVX2AttributeFlag : U32
{
    Position3 = (1u << 0),
    Normal = (1u << 1),
    TexCoord0 = (1u << 2),
    TexCoord1 = (1u << 3),
    TexCoord2 = (1u << 4),
    TexCoord3 = (1u << 5),
    Color = (1u << 6),
    Tangent = (1u << 7),
    Bitangent = (1u << 8),
    BoneWeights = (1u << 9),
    BoneIndices = (1u << 10),
    Position4 = (1u << 11),
    All = ((1u << 12) - 1u)
};

// Helper to append vertex component only if flag is set
static void TryAddComponent(
    U32 mask,
    ENVX2AttributeFlag flag,
    Render::EVertexComponentSemantic semantic,
    Render::EVertexComponentFormat format,
    U32 index,
    std::vector<Render::CVertexComponent>& outComponents
) {
    if (mask & static_cast<U32>(flag)) {
        Render::CVertexComponent cmp{};
        cmp.Stream = 0;
        cmp.OffsetInVertex = Render::VertexComponentOffsetAuto;
        cmp.UserDefinedName = nullptr;
        cmp.PerInstanceData = false;
        cmp.Format = format;
        cmp.Semantic = semantic;
        cmp.Index = index;
        outComponents.emplace_back(std::move(cmp));
    }
}

// Special handling for position (Coord vs Coord4)
static void SetupPositionComponent(
    U32 mask,
    std::vector<Render::CVertexComponent>& outComponents
) {
    if (mask & static_cast<U32>(ENVX2AttributeFlag::Position3)) {
        Render::CVertexComponent cmp{};
        cmp.Stream = 0;
        cmp.OffsetInVertex = Render::VertexComponentOffsetAuto;
        cmp.UserDefinedName = nullptr;
        cmp.PerInstanceData = false;
        cmp.Format = Render::EVertexComponentFormat::Float32_3;
        cmp.Semantic = Render::EVertexComponentSemantic::Position;
        cmp.Index = 0;
        outComponents.emplace_back(std::move(cmp));
    } else if (mask & static_cast<U32>(ENVX2AttributeFlag::Position4)) {
        Render::CVertexComponent cmp{};
        cmp.Stream = 0;
        cmp.OffsetInVertex = Render::VertexComponentOffsetAuto;
        cmp.UserDefinedName = nullptr;
        cmp.PerInstanceData = false;
        cmp.Format = Render::EVertexComponentFormat::Float32_4;
        cmp.Semantic = Render::EVertexComponentSemantic::Position;
        cmp.Index = 0;
        outComponents.emplace_back(std::move(cmp));
    }
}

// Populate vertex format based on bitmask
static void BuildVertexLayout(U32 attributeMask, std::vector<Render::CVertexComponent>& layout) {
    layout.clear();
    SetupPositionComponent(attributeMask, layout);

    TryAddComponent(attributeMask, ENVX2AttributeFlag::Normal,
                    Render::EVertexComponentSemantic::Normal,
                    Render::EVertexComponentFormat::Float32_3, 0, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::TexCoord0,
                    Render::EVertexComponentSemantic::TexCoord,
                    Render::EVertexComponentFormat::Float32_2, 0, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::TexCoord1,
                    Render::EVertexComponentSemantic::TexCoord,
                    Render::EVertexComponentFormat::Float32_2, 1, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::TexCoord2,
                    Render::EVertexComponentSemantic::TexCoord,
                    Render::EVertexComponentFormat::Float32_2, 2, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::TexCoord3,
                    Render::EVertexComponentSemantic::TexCoord,
                    Render::EVertexComponentFormat::Float32_2, 3, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::Color,
                    Render::EVertexComponentSemantic::Color,
                    Render::EVertexComponentFormat::Float32_4, 0, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::Tangent,
                    Render::EVertexComponentSemantic::Tangent,
                    Render::EVertexComponentFormat::Float32_3, 0, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::Bitangent,
                    Render::EVertexComponentSemantic::Bitangent,
                    Render::EVertexComponentFormat::Float32_3, 0, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::BoneWeights,
                    Render::EVertexComponentSemantic::BoneWeights,
                    Render::EVertexComponentFormat::Float32_4, 0, layout);
    TryAddComponent(attributeMask, ENVX2AttributeFlag::BoneIndices,
                    Render::EVertexComponentSemantic::BoneIndices,
                    Render::EVertexComponentFormat::Float32_4, 0, layout);
}

