Core::PObject CMeshLoaderNVX2::CreateResource(CStrID resourceID)
{
    const char* subId = nullptr;
    IO::PStream stream = _ResMgr.CreateResourceStream(resourceID.CStr(), subId, IO::SAP_SEQUENTIAL);
    if (!stream || !stream->IsOpened())
        return nullptr;

    IO::CBinaryReader reader(*stream);

    NVX2FileHeader nvx2Header;
    if (!reader.Read(nvx2Header) || nvx2Header.fileSignature != 'NVX2')
        return nullptr;

    // Convert triangle count to index count (3 indices per triangle)
    const U32 totalIndices = nvx2Header.indexCountTotal * 3;

    auto meshData = n_new(Render::CMeshData);
    meshData->IndexType = Render::Index_16;
    meshData->VertexCount = nvx2Header.vertexCountTotal;
    meshData->IndexCount = totalIndices;

    std::vector<Render::CPrimitiveGroup> groups;
    groups.reserve(nvx2Header.primitiveGroupCount);

    U32 groupIdx = 0;
    while (groupIdx < nvx2Header.primitiveGroupCount)
    {
        NVX2GroupData groupData;
        if (!reader.Read(groupData))
            return nullptr;

        Render::CPrimitiveGroup& pg = groups.emplace_back();
        pg.FirstVertex = groupData.startVertexIndex;
        pg.VertexCount = groupData.vertexRangeSize;
        pg.FirstIndex = groupData.firstTriangleOffset * 3;
        pg.IndexCount = groupData.triangleCount * 3;
        pg.Topology = Render::Prim_TriList;

        ++groupIdx;
    }

    BuildVertexLayout(nvx2Header.activeVertexAttributes, meshData->VertexFormat);

    // Read vertex buffer data
    const size_t vbSize = static_cast<size_t>(nvx2Header.vertexCountTotal) *
                          static_cast<size_t>(nvx2Header.vertexStrideInBytes);
    meshData->VBData.reset(n_new(Data::CBufferMallocAligned(vbSize, 16)));
    if (!stream->Read(meshData->VBData->GetPtr(), vbSize))
        return nullptr;

    // Read index buffer data
    const size_t ibSize = totalIndices * sizeof(U16);
    meshData->IBData.reset(n_new(Data::CBufferMallocAligned(ibSize, 16)));
    if (!stream->Read(meshData->IBData->GetPtr(), ibSize))
        return nullptr;

    meshData->InitGroups(groups.data(), groups.size(), groups.size(), 1, false, true);
    return meshData;
}

