#include <vector>
#include <set>
#include <algorithm>
#include <climits>
#include <numeric>

class Solution {
public:
    int maxEvents(std::vector<std::vector<int>>& events) {
        // Sort events by their end day in ascending order
        std::sort(events.begin(), events.end(), 
            [](const std::vector<int>& x, const std::vector<int>& y) {
                return x[1] < y[1];
            });

        // Find the overall minimum start day and maximum end day
        int min_start = INT_MAX;
        int max_end = INT_MIN;

        for (const auto& event : events) {
            min_start = std::min(min_start, event[0]);
            max_end = std::max(max_end, event[1]);
        }

        // Create a set containing all possible days from min_start to max_end
        std::set<int> available_days;
        for (int day = min_start; day <= max_end; ++day) {
            available_days.insert(day);
        }

        int count = 0;

        // For each event, try to assign the earliest possible available day
        for (const auto& event : events) {
            int start = event[0];
            int end = event[1];

            auto it = available_days.lower_bound(start);
            if (it != available_days.end() && *it <= end) {
                available_days.erase(it);
                ++count;
            }
        }

        return count;
    }
};

