namespace {
// Insert missing semicolons before newlines if previous non-space char wasn't ';'
L<C>& add_missing_semicolons(L<C>& input_script) {
    char prev_significant = '\0';
    for (size_t idx = 0; idx < input_script.size(); ++idx) {
        const char current_char = C::rep(input_script[idx]);
        if (current_char == '\n' && prev_significant != ';') {
            input_script[idx] = C(';');
        }
        if (!isspace(current_char)) {
            prev_significant = current_char;
        }
    }
    return input_script;
}
} // unnamed namespace

int main(int argc, char* argv[]) {
    L<S> reserved_words{"in"_s};
    KV<S, KV<S,O>> environment;
    const S target_module_name(0);
    environment.add(target_module_name, init_module(target_module_name));
    KV<S,O> system_module(init_module("sys"_s));

    bool verbose_mode = false;

    int arg_index = 1;
    while (arg_index < argc) {
        const char* current_arg = argv[arg_index++];
        if (current_arg[0] == '-') {
            if (current_arg[1] == 't') {
                verbose_mode = true;
            }
        } else {
            // Collect remaining arguments as script args
            L<L<C>> positional_args(argc - arg_index);
            int arg_counter = 0;
            while (arg_index < argc) {
                size_t len = strlen(argv[arg_index]);
                positional_args[arg_counter++] = L<C>(argv[arg_index], argv[arg_index] + len);
                ++arg_index;
            }

            system_module.add("argv"_s, positional_args);
            environment.add("sys"_s, system_module);

            L<C> input_script = read_text(current_arg);
            add_missing_semicolons(input_script);

            try {
                O evaluation_result(interp(environment, input_script, reserved_words, verbose_mode));
                H(1) << evaluation_result << '\n' << flush;
            } catch (const Exception& err) {
                H(2) << err.what() << '\n';
            }
        }
    }

    // Prompt if stdin is terminal
    if (isatty(0)) H(1) << "  " << flush;

    L<C> user_input = getline();
    while (trim(user_input) != "\\\\") {
        try {
            const L<C> trimmed_line = trim(user_input);
            if (!trimmed_line.empty()) {
                const L<C>& command = trimmed_line;
                if (command.size() == 0 || command[0] != C('\\')) {
                    const O eval_output(interp(environment, command, reserved_words, verbose_mode));
                    if (eval_output->type != generic_null_type) {
                        H(1) << eval_output << '\n' << flush;
                    }
                } else {
                    H(1) << "nyi: \\ commands";
                }
            }
        } catch (const Exception& ex) {
            H(2) << '\'' << ex.what() << '\n' << flush;
        }

        if (isatty(0)) H(1) << "  " << flush;
        user_input = getline();
    }

    return 0;
}

