constexpr uint32_t kNumChannelsDefault = 2;
constexpr uint32_t kFrameRateDefault = 48000;

const Format kFormatDefault =
    Format::Create(fuchsia::media::AudioStreamType{
                       .sample_format = fuchsia::media::AudioSampleFormat::FLOAT,
                       .channels = kNumChannelsDefault,
                       .frames_per_second = kFrameRateDefault,
                   })
        .take_value();

enum ClockScenario { IDENTICAL, OFFSETTED, RATE_CHANGED };

class MixStageTest : public testing::ThreadingModelFixture {
  static constexpr uint32_t kBlockLengthFrames = 240;

 protected:
  void Initialize() override {
    device_clock_ =
        AudioClock::CreateAsDeviceStatic(clock::CloneOfMonotonic(), AudioClock::kMonotonicDomain);
    mix_stage_ = std::make_shared<MixStage>(kFormatDefault, kBlockLengthFrames, timeline_function_,
                                            device_clock_);
  }

  zx::time TimeAt(zx::duration offset) { return zx::time(offset.to_nsecs()); }

  fbl::RefPtr<VersionedTimelineFunction> timeline_function_ =
      fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(TimelineRate(
          Fixed(kFormatDefault.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  template <typename T, size_t N>
  std::array<T, N>& CastTo(std::void_t* buffer, size_t skip_elements = 0) {
    return reinterpret_cast<std::array<T, N>&>(static_cast<T*>(buffer)[skip_elements]);
  }

  AudioClock GenerateCustomClock() { return AudioClock::CreateAsCustom(clock::CloneOfMonotonic()); }

  AudioClock ConfigureFactoryWithClockOffset(zx::duration clock_shift,
                                             testing::PacketFactory& factory);

  void ValidateTrimming(ClockScenario scenario);
  void ValidateUniformMixing(ClockScenario scenario);
  void ValidateSingleSourceMix(ClockScenario scenario);
  void ValidatePositionTracking(ClockScenario scenario, int32_t adjust_ppm = 0);

  std::shared_ptr<MixStage> mix_stage_;
  AudioClock device_clock_;
};

AudioClock MixStageTest::ConfigureFactoryWithClockOffset(zx::duration clock_shift,
                                                         testing::PacketFactory& factory) {
  auto custom_clock_result =
      clock::testing::CreateCustomClock({.start_val = zx::clock::get_monotonic() + clock_shift});
  EXPECT_TRUE(custom_clock_result.is_ok());
  zx::clock adjusted_clock = custom_clock_result.take_value();
  EXPECT_TRUE(adjusted_clock.is_valid());

  auto offset_result = clock::testing::GetOffsetFromMonotonic(adjusted_clock);
  EXPECT_TRUE(offset_result.is_ok());
  auto actual_shift = offset_result.take_value();

  int64_t frame_offset = static_cast<int64_t>(
      round(static_cast<double>(kFormatDefault.frames_per_second() * actual_shift.get()) / ZX_SEC(1)));
  factory.SeekToFrame(frame_offset);

  return AudioClock::CreateAsCustom(std::move(adjusted_clock));
}

void MixStageTest::ValidateTrimming(ClockScenario scenario) {
  auto timeline_func = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormatDefault.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  std::shared_ptr<PacketQueue> input_queue;
  testing::PacketFactory packet_gen(dispatcher(), kFormatDefault, PAGE_SIZE);

  if (scenario == ClockScenario::IDENTICAL) {
    input_queue =
        std::make_shared<PacketQueue>(kFormatDefault, timeline_func, GenerateCustomClock());
  } else if (scenario == ClockScenario::OFFSETTED) {
    AudioClock custom_clock = ConfigureFactoryWithClockOffset(zx::sec(-2), packet_gen);
    ASSERT_TRUE(custom_clock.is_valid());
    input_queue = std::make_shared<PacketQueue>(kFormatDefault, timeline_func, std::move(custom_clock));
  } else {
    ASSERT_EQ(scenario, ClockScenario::RATE_CHANGED);
    FAIL() << "Multi-rate tests not yet implemented";
  }

  mix_stage_->AddInput(input_queue);

  bool first_packet_freed = false;
  bool second_packet_freed = false;

  input_queue->PushPacket(packet_gen.CreatePacket(
      1.0f, zx::msec(5), [&first_packet_freed] { first_packet_freed = true; }));
  input_queue->PushPacket(packet_gen.CreatePacket(
      0.5f, zx::msec(5), [&second_packet_freed] { second_packet_freed = true; }));

  constexpr zx::duration tolerance = zx::sec(1) / kFrameRateDefault;

  // Before 5ms: both packets still active
  mix_stage_->Trim(TimeAt(zx::msec(5) - tolerance));
  RunLoopUntilIdle();
  EXPECT_FALSE(first_packet_freed);

  // After 5ms: first packet should be released
  mix_stage_->Trim(TimeAt(zx::msec(5) + tolerance));
  RunLoopUntilIdle();
  EXPECT_TRUE(first_packet_freed);
  EXPECT_FALSE(second_packet_freed);

  // Before 10ms: second packet still active
  mix_stage_->Trim(TimeAt(zx::msec(10) - tolerance));
  RunLoopUntilIdle();
  EXPECT_FALSE(second_packet_freed);

  // After 10ms: second packet should be released
  mix_stage_->Trim(TimeAt(zx::msec(10) + tolerance));
  RunLoopUntilIdle();
  EXPECT_TRUE(second_packet_freed);

  // Cleanup to avoid slab_allocator asserts
  mix_stage_->Trim(zx::time::infinite());
}

TEST_F(MixStageTest, Trim_Packets) { ValidateTrimming(ClockScenario::IDENTICAL); }
TEST_F(MixStageTest, Trim_OffsettedClock) { ValidateTrimming(ClockScenario::OFFSETTED); }

void MixStageTest::ValidateUniformMixing(ClockScenario scenario) {
  auto timeline_func = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormatDefault.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  testing::PacketFactory gen1(dispatcher(), kFormatDefault, PAGE_SIZE);
  testing::PacketFactory gen2(dispatcher(), kFormatDefault, PAGE_SIZE);

  auto queue1 =
      std::make_shared<PacketQueue>(kFormatDefault, timeline_func, GenerateCustomClock());
  std::shared_ptr<PacketQueue> queue2;

  if (scenario == ClockScenario::IDENTICAL) {
    queue2 =
        std::make_shared<PacketQueue>(kFormatDefault, timeline_func, GenerateCustomClock());
  } else if (scenario == ClockScenario::OFFSETTED) {
    AudioClock custom_clock = ConfigureFactoryWithClockOffset(zx::sec(10), gen2);
    ASSERT_TRUE(custom_clock.is_valid());
    queue2 = std::make_shared<PacketQueue>(kFormatDefault, timeline_func, std::move(custom_clock));
  } else {
    ASSERT_EQ(scenario, ClockScenario::RATE_CHANGED);
    FAIL() << "Multi-rate tests not yet implemented";
  }

  mix_stage_->AddInput(queue1);
  mix_stage_->AddInput(queue2);

  // Feed test data in three batches of 2ms each
  {
    queue1->PushPacket(gen1.CreatePacket(0.1f, zx::msec(1)));
    queue1->PushPacket(gen1.CreatePacket(0.2f, zx::msec(2)));
    queue1->PushPacket(gen1.CreatePacket(0.3f, zx::msec(3)));

    queue2->PushPacket(gen2.CreatePacket(0.7f, zx::msec(3)));
    queue2->PushPacket(gen2.CreatePacket(0.5f, zx::msec(2)));
    queue2->PushPacket(gen2.CreatePacket(0.3f, zx::msec(1)));
  }

  int64_t current_dest_frame = 0;
  uint32_t frames_per_slice = 96;

  // First 2ms window: expect [0.8, 0.9]
  {
    auto buffer = mix_stage_->ReadLock(TimeAt(zx::msec(2)), current_dest_frame, frames_per_slice);
    ASSERT_TRUE(buffer);
    ASSERT_EQ(buffer->length().Floor(), 96u);

    auto& samples1 = CastTo<float, 96>(buffer->payload(), 0);
    EXPECT_THAT(samples1, Each(FloatEq(0.8f)));

    auto& samples2 = CastTo<float, 96>(buffer->payload(), 96);
    EXPECT_THAT(samples2, Each(FloatEq(0.9f)));
  }

  current_dest_frame += frames_per_slice;

  // Second 2ms window: expect [0.9, 0.8]
  {
    auto buffer = mix_stage_->ReadLock(TimeAt(zx::msec(4)), current_dest_frame, frames_per_slice);
    ASSERT_TRUE(buffer);
    ASSERT_EQ(buffer->length().Floor(), 96u);

    auto& samples1 = CastTo<float, 96>(buffer->payload(), 0);
    EXPECT_THAT(samples1, Each(FloatEq(0.9f)));

    auto& samples2 = CastTo<float, 96>(buffer->payload(), 96);
    EXPECT_THAT(samples2, Each(FloatEq(0.8f)));
  }

  current_dest_frame += frames_per_slice;

  // Third 2ms window: expect [0.8, 0.6]
  {
    auto buffer = mix_stage_->ReadLock(TimeAt(zx::msec(6)), current_dest_frame, frames_per_slice);
    ASSERT_TRUE(buffer);
    ASSERT_EQ(buffer->length().Floor(), 96u);

    auto& samples1 = CastTo<float, 96>(buffer->payload(), 0);
    EXPECT_THAT(samples1, Each(FloatEq(0.8f)));

    auto& samples2 = CastTo<float, 96>(buffer->payload(), 96);
    EXPECT_THAT(samples2, Each(FloatEq(0.6f)));
  }

  mix_stage_->Trim(zx::time::infinite());
}

TEST_F(MixStageTest, UniformFormatMixing) { ValidateUniformMixing(ClockScenario::IDENTICAL); }
TEST_F(MixStageTest, UniformFormatMixing_Offset) { ValidateUniformMixing(ClockScenario::OFFSETTED); }

TEST_F(MixStageTest, SincSamplerRingBuffer) {
  constexpr uint32_t kRingCapacityFrames = 64;
  constexpr uint32_t kRingCapacitySamples = kRingCapacityFrames * kNumChannelsDefault;

  auto ring_endpoints = BaseRingBuffer::AllocateSoftwareBuffer(
      kFormatDefault, timeline_function_, device_clock_, kRingCapacityFrames);

  mix_stage_->AddInput(ring_endpoints.reader, Mixer::Resampler::WindowedSinc);

  float* ring_samples = reinterpret_cast<float*>(ring_endpoints.writer->virt());
  for (size_t idx = 0; idx < kRingCapacitySamples / 2; ++idx) {
    ring_samples[idx] = 0.5f;
    ring_samples[kRingCapacitySamples / 2 + idx] = 0.7f;
  }

  constexpr uint32_t kSliceSize = kRingCapacityFrames / 2;

  {
    auto buffer = mix_stage_->ReadLock(TimeAt(zx::msec(1)), 0, kSliceSize);
    ASSERT_TRUE(buffer);
    ASSERT_EQ(buffer->start().Floor(), 0u);
    ASSERT_EQ(buffer->length().Floor(), kSliceSize);

    auto& samples = CastTo<float, kSliceSize * kNumChannelsDefault>(buffer->payload(), 0);
    EXPECT_THAT(samples, Each(FloatEq(0.5f)));
  }

  {
    auto buffer = mix_stage_->ReadLock(TimeAt(zx::msec(2)), kSliceSize, kSliceSize);
    ASSERT_TRUE(buffer);
    ASSERT_EQ(buffer->start().Floor(), kSliceSize);
    ASSERT_EQ(buffer->length().Floor(), kSliceSize);

    auto& samples = CastTo<float, kSliceSize * kNumChannelsDefault>(buffer->payload(), 0);
    EXPECT_THAT(samples, Each(FloatEq(0.7f)));
  }
}

