void MixStageTest::ValidateSingleSourceMix(ClockScenario scenario) {
  auto timeline_func = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormatDefault.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  testing::PacketFactory packet_gen(dispatcher(), kFormatDefault, PAGE_SIZE);
  std::shared_ptr<PacketQueue> input_queue;

  if (scenario == ClockScenario::IDENTICAL) {
    input_queue =
        std::make_shared<PacketQueue>(kFormatDefault, timeline_func, GenerateCustomClock());
  } else if (scenario == ClockScenario::OFFSETTED) {
    AudioClock custom_clock = ConfigureFactoryWithClockOffset(zx::sec(5), packet_gen);
    ASSERT_TRUE(custom_clock.is_valid());
    input_queue = std::make_shared<PacketQueue>(kFormatDefault, timeline_func, std::move(custom_clock));
