    ASSERT_EQ(scenario, ClockScenario::RATE_CHANGED);
    FAIL() << "Multi-rate tests not yet implemented";
  }

  input_queue->set_usage(kInputUsage);
  mix_stage_->AddInput(input_queue);

  input_queue->PushPacket(packet_gen.CreatePacket(1.0f, zx::msec(5)));

  constexpr uint32_t kRequestedFrames = 48;
