void MixStageTest::ValidatePositionTracking(ClockScenario scenario, int32_t adjust_ppm) {
  clock::testing::ClockProperties props;

  if (scenario == ClockScenario::OFFSETTED) {
    props = {.start_val = zx::clock::get_monotonic() - zx::sec(2)};
  } else if (scenario == ClockScenario::RATE_CHANGED) {
    props = {.start_val = zx::time(0) + zx::sec(3), .rate_adjust_ppm = adjust_ppm};
  }

  auto custom_clock_result = clock::testing::CreateCustomClock(props);
  EXPECT_TRUE(custom_clock_result.is_ok()) << "Failed to create custom clock";

  zx::clock raw_clock = custom_clock_result.take_value();
  EXPECT_TRUE(raw_clock.is_valid());

  auto offset_result = clock::testing::GetOffsetFromMonotonic(raw_clock);
  EXPECT_TRUE(offset_result.is_ok()) << "Failed to get clock offset";

  auto clock_offset = offset_result.take_value();
  auto seek_frac_frame =
      Fixed::FromRaw(round(static_cast<double>(clock_offset.get()) * Fixed(1).raw_value() *
                           kFormatDefault.frames_per_second() / ZX_SEC(1)));

  testing::PacketFactory packet_gen(
      dispatcher(), kFormatDefault,
      kFormatDefault.frames_per_second() * kFormatDefault.bytes_per_frame());
  packet_gen.SeekToFrame(seek_frac_frame.Round());

  AudioClock audio_clock = AudioClock::CreateAsCustom(std::move(raw_clock));
  EXPECT_TRUE(audio_clock.is_valid());

  auto src_transform = fbl::MakeRefCounted<VersionedTimelineFunction>(TimelineFunction(
      TimelineRate(Fixed(kFormatDefault.frames_per_second()).raw_value(), zx::sec(1).to_nsecs())));

  std::shared_ptr<PacketQueue> input_queue =
      std::make_shared<PacketQueue>(kFormatDefault, src_transform, std::move(audio_clock));

  auto& mixer_info = mix_stage_->AddInput(input_queue)->source_info();

  Fixed upper_bound, lower_bound;

  if (adjust_ppm > 0) {
    upper_bound = Fixed::FromRaw(adjust_ppm * 8);
    lower_bound = Fixed::FromRaw(adjust_ppm * -16);
  } else {
    upper_bound = Fixed::FromRaw(adjust_ppm * -16);
    lower_bound = Fixed::FromRaw(adjust_ppm * 8);
  }

  if (adjust_ppm != 0) {
    upper_bound = std::max(upper_bound, Fixed::FromRaw(16));
    lower_bound = std::min(lower_bound, Fixed::FromRaw(-16));
  }

  constexpr Fixed kFinalUpperBound = Fixed::FromRaw(8);
  constexpr Fixed kFinalLowerBound = Fixed::FromRaw(-8);

  constexpr int kTotalIterations = 400;
  constexpr zx::duration kStepDuration = zx::msec(5);
  constexpr uint32_t kFramesPerStep = kBlockLengthFrames;

  Fixed max_error{0}, min_error{0};
  Fixed max_error_final_window{0}, min_error_final_window{0};
  int max_error_step = 0, min_error_step = 0;

  for (int step = 0; step < kTotalIterations; ++step) {
    mix_stage_->ReadLock(TimeAt(kStepDuration * step), kFramesPerStep * step, kFramesPerStep);
    EXPECT_EQ(mixer_info.next_dest_frame, kFramesPerStep * (step + 1));

    if (mixer_info.frac_source_error > max_error) {
      max_error = mixer_info.frac_source_error;
      max_error_step = step;
    }
    if (mixer_info.frac_source_error < min_error) {
      min_error = mixer_info.frac_source_error;
      min_error_step = step;
    }

    if (step >= kTotalIterations - 10) {
      max_error_final_window = std::max(max_error_final_window, mixer_info.frac_source_error);
      min_error_final_window = std::min(min_error_final_window, mixer_info.frac_source_error);
    }
  }

  EXPECT_LE(max_error, upper_bound)
      << "Max error " << max_error.raw_value() << " exceeds upper bound "
      << upper_bound.raw_value() << " at step " << max_error_step;

  EXPECT_GE(min_error, lower_bound)
      << "Min error " << min_error.raw_value() << " below lower bound "
      << lower_bound.raw_value() << " at step " << min_error_step;

  if (adjust_ppm != 0) {
    EXPECT_LE(max_error_final_window, kFinalUpperBound);
    EXPECT_GE(min_error_final_window, kFinalLowerBound);
  }
}

