using namespace llvm;

MCSectionXCOFF::~MCSectionXCOFF() = default;

static StringRef convertStorageClassToString(XCOFF::StorageMappingClass storageClass) {
  switch (storageClass) {
    case XCOFF::XMC_DS:
      return "DS";
    case XCOFF::XMC_RW:
      return "RW";
    case XCOFF::XMC_PR:
      return "PR";
    default:
      report_fatal_error("Unsupported storage mapping class encountered.");
  }
}

void MCSectionXCOFF::PrintSwitchToSection(const MCAsmInfo &MAI, const Triple &T,
                                          raw_ostream &OS,
                                          const MCExpr *Subsection) const {
  if (Kind.isText()) {
    if (MappingClass != XCOFF::XMC_PR)
      report_fatal_error("Unexpected storage-mapping class for .text csect");
    OS << "\t.csect " << SectionName << "["
       << convertStorageClassToString(MappingClass) << "]" << '\n';
    return;
  }

  if (Kind.isData()) {
    switch (MappingClass) {
      case XCOFF::XMC_RW:
      case XCOFF::XMC_DS:
        OS << "\t.csect " << SectionName << "["
           << convertStorageClassToString(MappingClass) << "]" << '\n';
        break;
      case XCOFF::XMC_TC0:
        OS << "\t.toc\n";
        break;
      default:
        report_fatal_error("Unhandled storage-mapping class for .data csect.");
    }
    return;
  }

  if (Kind.isBSSLocal() || Kind.isCommon()) {
    assert((MappingClass == XCOFF::XMC_RW || MappingClass == XCOFF::XMC_BS) &&
           "Encountered unsupported storage-mapping class for common/BSS csect.");
    assert(Type == XCOFF::XTY_CM &&
           "Incorrect csect type for .bss section.");
    // Common sections do not require a section-switch directive; 
    // '.comm' and '.lcomm' directives handle csect creation.
    return;
  }

  report_fatal_error("Printing support for this SectionKind is not implemented.");
}

bool MCSectionXCOFF::UseCodeAlign() const { return Kind.isText(); }
bool MCSectionXCOFF::isVirtualSection() const { return Type == XCOFF::XTY_CM; }

