using namespace std;

// Definition for a binary tree node.
struct TreeNode {
    int val;
    TreeNode* left;
    TreeNode* right;
    TreeNode() : val(0), left(nullptr), right(nullptr) {}
    TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
    TreeNode(int x, TreeNode* l, TreeNode* r) : val(x), left(l), right(r) {}
};

class Solution {
public:
    // Helper function to compute depth recursively with current depth tracking
    int computeDepth(TreeNode* node, int currentDepth) {
        if (node == nullptr) {
            return currentDepth;
        }
        currentDepth++;
        int leftDepth = computeDepth(node->left, currentDepth);
        int rightDepth = computeDepth(node->right, currentDepth);
        return max(leftDepth, rightDepth);
    }

    // Public method to find maximum depth of the tree
    int findMaxDepth(TreeNode* root) {
        if (root == nullptr) {
            return 0;
        }
        return computeDepth(root, 0);
    }
};

int main() {
    TreeNode leafNode(2);
    TreeNode rootNode(1, &leafNode, nullptr);
    Solution solver;
    cout << "\n " << solver.findMaxDepth(&rootNode) << endl;
    return 0;
}

#include "Helpers/KeySequence.hpp"

namespace CTRPluginFramework
{
    KeySequence::KeySequence(KeyVector sequence) : 
        _sequence(sequence), _currentIndex(0)
    {            
    }

    bool KeySequence::operator()(void)
    {
        // Check if the current key in the sequence is pressed
        if (Controller::IsKeyDown(_sequence[_currentIndex]))
        {
            _currentIndex++;

            // If all keys in the sequence have been pressed successfully
            if (_currentIndex >= static_cast<int>(_sequence.size()))
            {
                _currentIndex = 0;
                return true;
            }

            // Reset timer after successful key detection
            _timer.Reset();
        }

        // If too much time has passed since last correct key press, reset sequence
        if (_timer.ElapsedTime() > Seconds(1.0))
        {
            _currentIndex = 0;
            _timer.Reset();
        }

        return false;
    }
}

