#include <gtest/gtest.h>
#include "Packets/Tag2/Sub29.h"

namespace {
    constexpr uint8_t revocation_code = OpenPGP::Subpacket::Tag2::Revoke::NO_REASON_SPECIFIED;
    const std::string empty_reason = "";

    void populate_revocation_subpacket(OpenPGP::Subpacket::Tag2::Sub29 & pkt) {
        pkt.set_code(revocation_code);
        pkt.set_reason(empty_reason);
    }

    void verify_revocation_subpacket(const OpenPGP::Subpacket::Tag2::Sub29 & pkt) {
        EXPECT_EQ(pkt.get_code(), revocation_code);
        EXPECT_EQ(pkt.get_reason(), empty_reason);
        EXPECT_EQ(pkt.valid(true), OpenPGP::Status::SUCCESS);
    }
}

TEST(Tag2Sub29, Constructor) {
    // Default initialization
    OpenPGP::Subpacket::Tag2::Sub29 packet;
    EXPECT_EQ(packet.raw(), std::string(1, '\x00'));
    EXPECT_NO_THROW(populate_revocation_subpacket(packet));

    // Construct from raw string
    {
        OpenPGP::Subpacket::Tag2::Sub29 from_raw(packet.raw());
        verify_revocation_subpacket(from_raw);
    }

    // Copy constructor
    {
        OpenPGP::Subpacket::Tag2::Sub29 copied(packet);
        verify_revocation_subpacket(copied);
    }

    // Move constructor
    {
        OpenPGP::Subpacket::Tag2::Sub29 moved(std::move(packet));
        verify_revocation_subpacket(moved);
    }
}

TEST(Tag2Sub29, AssignmentOperators) {
    OpenPGP::Subpacket::Tag2::Sub29 original;
    EXPECT_NO_THROW(populate_revocation_subpacket(original));

    // Copy assignment
    {
        OpenPGP::Subpacket::Tag2::Sub29 assigned;
        assigned = original;
        verify_revocation_subpacket(assigned);
    }

    // Move assignment
    {
        OpenPGP::Subpacket::Tag2::Sub29 moved_to;
        moved_to = std::move(original);
        verify_revocation_subpacket(moved_to);
    }
}

TEST(Tag2Sub29, Serialization) {
    std::string serialized;
    serialized.append(1, static_cast<char>(revocation_code));
    serialized.append(empty_reason);

    OpenPGP::Subpacket::Tag2::Sub29 parsed(serialized);
    verify_revocation_subpacket(parsed);
    EXPECT_EQ(parsed.raw(), serialized);
}

TEST(Tag2Sub29, Display) {
    OpenPGP::Subpacket::Tag2::Sub29 pkt;
    EXPECT_NO_THROW(populate_revocation_subpacket(pkt));
    EXPECT_NO_THROW(pkt.show());
}

TEST(Tag2Sub29, SetAndGet) {
    OpenPGP::Subpacket::Tag2::Sub29 pkt;
    populate_revocation_subpacket(pkt);
    verify_revocation_subpacket(pkt);
}

TEST(Tag2Sub29, CloneOperation) {
    OpenPGP::Subpacket::Tag2::Sub29 pkt;
    EXPECT_NO_THROW(populate_revocation_subpacket(pkt));

    OpenPGP::Subpacket::Sub::Ptr cloned = pkt.clone();
    ASSERT_NE(cloned, nullptr);
    EXPECT_NE(&pkt, cloned.get());

    auto casted = std::static_pointer_cast<OpenPGP::Subpacket::Tag2::Sub29>(cloned);
    verify_revocation_subpacket(*casted);
}

#include <cstring>
#include <cstdint>

// Replaced ROTR with inline function to avoid macro side effects
inline uint32_t rotateRight(uint32_t value, unsigned int shift) {
    return (value >> shift) | (value << (32 - shift));
}

// Helper functions for SHA-256 operations
inline uint32_t choice(uint32_t x, uint32_t y, uint32_t z) {
    return (z ^ (x & (y ^ z)));
}

inline uint32_t majority(uint32_t x, uint32_t y, uint32_t z) {
    return ((x & y) ^ (z & (x ^ y)));
}

inline uint32_t bigSigma0(uint32_t x) {
    return rotateRight(x, 2) ^ rotateRight(x, 13) ^ rotateRight(x, 22);
}

inline uint32_t bigSigma1(uint32_t x) {
    return rotateRight(x, 6) ^ rotateRight(x, 11) ^ rotateRight(x, 25);
}

inline uint32_t smallSigma0(uint32_t x) {
    return rotateRight(x, 7) ^ rotateRight(x, 18) ^ (x >> 3);
}

inline uint32_t smallSigma1(uint32_t x) {
    return rotateRight(x, 17) ^ rotateRight(x, 19) ^ (x >> 10);
}

// Process one 64-byte block
static void processBlock(const uint8_t* block, uint32_t state[8]) {
    uint32_t schedule[64];

    // Build first 16 words from block bytes (big-endian)
    for (int idx = 0; idx < 16; ++idx) {
        schedule[idx] = static_cast<uint32_t>(block[idx * 4]) << 24 |
                        static_cast<uint32_t>(block[idx * 4 + 1]) << 16 |
                        static_cast<uint32_t>(block[idx * 4 + 2]) << 8 |
                        static_cast<uint32_t>(block[idx * 4 + 3]);
    }

    // Extend to 64 words
    for (int j = 16; j < 64; ++j) {
        schedule[j] = smallSigma1(schedule[j - 2]) +
                      schedule[j - 7] +
                      smallSigma0(schedule[j - 15]) +
                      schedule[j - 16];
    }

    // Initialize working variables
    uint32_t a = state[0], b = state[1], c = state[2], d = state[3];
    uint32_t e = state[4], f = state[5], g = state[6], h = state[7];

    // Constants array (same as K in original)
    static const uint32_t roundConstants[64] = {
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5,
        0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3,
        0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc,
        0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7,
        0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13,
        0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3,
        0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5,
        0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208,
        0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2
    };

    // Main compression loop
    for (int r = 0; r < 64; ++r) {
        uint32_t temp1 = h + bigSigma1(e) + choice(e, f, g) + roundConstants[r] + schedule[r];
        uint32_t temp2 = temp1 + bigSigma0(a) + majority(a, b, c);
        h = temp1;
        d += temp1;
        h = temp2;
        a = temp2;
        // Rotate registers: a←b←c←d←e←f←g←h←a
        uint32_t t = g; g = f; f = e; e = d; d = c; c = b; b = a; a = t;
    }

    // Update hash state
    state[0] += a; state[1] += b; state[2] += c; state[3] += d;
    state[4] += e; state[5] += f; state[6] += g; state[7] += h;
}

void sha256(const uint8_t* input, int length, uint8_t* output) {
    uint32_t internalState[8] = {
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    };

    // Process full blocks
    int offset = 0;
    while (offset + 64 <= length) {
        processBlock(input + offset, internalState);
        offset += 64;
    }

    // Prepare final padded block
    uint8_t buffer[64];
    int remaining = length - offset;
    std::memcpy(buffer, input + offset, remaining);

    // Append bit '1' followed by zeros until 56 bytes
    buffer[remaining++] = 0x80;
    while (remaining < 56) {
        buffer[remaining++] = 0x00;
    }

    // If not enough space left for length field, process current block and start new one
    if (remaining > 56) {
        std::memset(buffer + remaining, 0, 64 - remaining);
        processBlock(buffer, internalState);
        std::memset(buffer, 0, 56);
        remaining = 0;
    }

    // Append original message length in bits (as 64-bit big-endian)
    uint64_t bitLength = static_cast<uint64_t>(length) * 8;
    buffer[56] = static_cast<uint8_t>(bitLength >> 56);
    buffer[57] = static_cast<uint8_t>(bitLength >> 48);
    buffer[58] = static_cast<uint8_t>(bitLength >> 40);
    buffer[59] = static_cast<uint8_t>(bitLength >> 32);
    buffer[60] = static_cast<uint8_t>(bitLength >> 24);
    buffer[61] = static_cast<uint8_t>(bitLength >> 16);
    buffer[62] = static_cast<uint8_t>(bitLength >> 8);
    buffer[63] = static_cast<uint8_t>(bitLength);

    processBlock(buffer, internalState);

    // Convert final hash to byte array (big-endian)
    for (int i = 0; i < 8; ++i) {
        output[i * 4]     = static_cast<uint8_t>(internalState[i] >> 24);
        output[i * 4 + 1] = static_cast<uint8_t>(internalState[i] >> 16);
        output[i * 4 + 2] = static_cast<uint8_t>(internalState[i] >> 8);
        output[i * 4 + 3] = static_cast<uint8_t>(internalState[i]);
    }
}

// Optimized version for short messages (<56 bytes)
void sha256f(const uint8_t* input, int len, uint8_t* output) {
    uint8_t buffer[64];
    uint32_t state[8] = {
        0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a,
        0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19
    };

    std::memcpy(buffer, input, len);
    buffer[len++] = 0x80;

    while (len < 56) {
        buffer[len++] = 0x00;
    }

    uint64_t bitLen = static_cast<uint64_t>(len - 1) * 8; // Note: len already includes 0x80
    buffer[56] = static_cast<uint8_t>(bitLen >> 56);
    buffer[57] = static_cast<uint8_t>(bitLen >> 48);
    buffer[58] = static_cast<uint8_t>(bitLen >> 40);
    buffer[59] = static_cast<uint8_t>(bitLen >> 32);
    buffer[60] = static_cast<uint8_t>(bitLen >> 24);
    buffer[61] = static_cast<uint8_t>(bitLen >> 16);
    buffer[62] = static_cast<uint8_t>(bitLen >> 8);
    buffer[63] = static_cast<uint8_t>(bitLen);

    processBlock(buffer, state);

    for (int i = 0; i < 8; ++i) {
        output[i * 4]     = static_cast<uint8_t>(state[i] >> 24);
        output[i * 4 + 1] = static_cast<uint8_t>(state[i] >> 16);
        output[i * 4 + 2] = static_cast<uint8_t>(state[i] >> 8);
        output[i * 4 + 3] = static_cast<uint8_t>(state[i]);
    }
}

#include "rive/animation/keyframe_double.hpp"
#include "rive/generated/core_registry.hpp"
using namespace rive;

// Interpolate between two double values based on weight factor
static void blendValue(Core* target, int propertyId, float weight, float newValue)
{
    if (weight >= 1.0f)
    {
        CoreRegistry::setDouble(target, propertyId, newValue);
    }
    else
    {
        float inverseWeight = 1.0f - weight;
        float currentValue = CoreRegistry::getDouble(target, propertyId);
        float blended = currentValue * inverseWeight + newValue * weight;
        CoreRegistry::setDouble(target, propertyId, blended);
    }
}

void KeyFrameDouble::apply(Core* object, int propertyKey, float mixFactor)
{
    blendValue(object, propertyKey, mixFactor, value());
}

void KeyFrameDouble::applyInterpolation(Core* object,
                                        int propertyKey,
                                        float currentTime,
                                        const KeyFrame* followingFrame,
                                        float mixFactor)
{
    auto nextKey = followingFrame->as<KeyFrameDouble>();
    const KeyFrameDouble& nextDouble = *nextKey;

    // Calculate normalized time position between frames
    float duration = nextDouble.seconds() - seconds();
    float t = (currentTime - seconds()) / duration;

    // Apply cubic easing if available
    if (CubicInterpolator* easing = interpolator())
    {
        t = easing->transform(t);
    }

    // Compute interpolated value
    float startVal = value();
    float endVal = nextDouble.value();
    float interpolated = startVal + (endVal - startVal) * t;

    blendValue(object, propertyKey, mixFactor, interpolated);
}

