    // Helper to apply selector filtering and return flat string representation
    static std::string ApplySelectorFilter(
        const RenderCore::Techniques::TechniqueEntry& techEntry,
        std::initializer_list<std::pair<const utf8*, const char*>> selectorValues)
    {
        ParameterBox inputParams(selectorValues);
        auto filteredTable = ShaderSourceParser::FilterSelectors(
            inputParams,
            techEntry._selectorFiltering,
            ShaderSourceParser::SelectorFilteringRules{});
        return BuildFlatStringTable(filteredTable);
    }

    TEST_CASE("TechniqueFileTests-TechniqueSelectorFiltering", "[rendercore_techniques]")
    {
        SECTION("file1")
        {
            const char* techniqueContent = R"--(
                Shared=~
                    Selectors=~
                        CLASSIFY_NORMAL_MAP
                        SKIP_MATERIAL_DIFFUSE=~; relevance=<:(value!=0):>
                        SELECTOR_0=~; relevance=1
                Config=~
                    Inherit=~; Shared
                    Selectors=~
                        SELECTOR_0=1
            )--";

            InputStreamFormatter<utf8> parser{ MakeStringSection(techniqueContent) };
            RenderCore::Techniques::TechniqueSetFile techniqueSet(parser, ::Assets::DirectorySearchRules{}, ::Assets::DependencyValidation{});
            (void)techniqueSet;

            auto* techEntry = techniqueSet.FindEntry(Hash64("Config"));
            REQUIRE(techEntry != nullptr);

            // Override SELECTOR_0 and provide SKIP_MATERIAL_DIFFUSE=0 → should be filtered out due to relevance
            auto resultA = ApplySelectorFilter(
                *techEntry,
                {
                    std::make_pair("SELECTOR_0", "2"),
                    std::make_pair("SKIP_MATERIAL_DIFFUSE", "0")
                });
            REQUIRE(std::string{"SELECTOR_0=2"} == resultA);

            // Provide SKIP_MATERIAL_DIFFUSE=3 (relevant) and CLASSIFY_NORMAL_MAP=5 (overrides default)
            auto resultB = ApplySelectorFilter(
                *techEntry,
                {
                    std::make_pair("SKIP_MATERIAL_DIFFUSE", "3"),
                    std::make_pair("CLASSIFY_NORMAL_MAP", "5")
                });
            REQUIRE(std::string{"SELECTOR_0=1;CLASSIFY_NORMAL_MAP=5;SKIP_MATERIAL_DIFFUSE=3"} == resultB);
        }

        SECTION("file2")
        {
            const char* techniqueContent = R"--(
                Shared=~
                    Selectors=~
                        SELECTOR_0=~; relevance=<:(value!=0):>
                        SELECTOR_1=~; set=2; relevance=1
                        SELECTOR_2=~; relevance=<:(value!=5):>
                Config=~
                    Inherit=~; Shared
                    Selectors=~
                        SELECTOR_0=~; relevance=<:(value!=1):>
                        SELECTOR_1=3
                        SELECTOR_2=4
            )--";

            InputStreamFormatter<utf8> parser{ MakeStringSection(techniqueContent) };
            RenderCore::Techniques::TechniqueSetFile techniqueSet(parser, ::Assets::DirectorySearchRules{}, ::Assets::DependencyValidation{});
            (void)techniqueSet;

            auto* techEntry = techniqueSet.FindEntry(Hash64("Config"));
            REQUIRE(techEntry != nullptr);

            // Override SELECTOR_0=0 and UNKNOWN_SELECTOR=6 → only known selectors with relevance survive
            auto resultA = ApplySelectorFilter(
                *techEntry,
                {
                    std::make_pair("SELECTOR_0", "0"),
                    std::make_pair("UNKNOWN_SELECTOR", "6")
                });
            REQUIRE(std::string{"SELECTOR_2=4;SELECTOR_0=0;SELECTOR_1=3"} == resultA);

            // Set SELECTOR_2=5 → violates its own relevance rule (<:(value!=5):>) → removed entirely
            auto resultB = ApplySelectorFilter(
                *techEntry,
                {
                    std::make_pair("SELECTOR_2", "5")
                });
            REQUIRE(std::string{"SELECTOR_1=3"} == resultB);
        }
    }
}

