#include <iostream>
#include <vector>

std::vector<bool> decode(const std::vector<bool>& message, int N, int K) {
    std::vector<bool> decoded(N, false);

    // First bit is directly taken from message
    decoded[0] = message[0];

    // For subsequent bits, compute XOR of relevant previous decoded bits
    for (int i = 1; i < N; ++i) {
        bool xor_value = message[i];

        // XOR with the appropriate previous decoded bit if within range
        if (i >= K) {
            xor_value ^= decoded[i - K];
        }

        decoded[i] = xor_value;
    }

    return decoded;
}

int main() {
    int N, K;
    std::cin >> N >> K;

    int length = N + K - 1;
    std::vector<bool> message(length);

    char c;
    for (int i = 0; i < length; ++i) {
        std::cin >> c;
        message[i] = (c == '1');
    }

    std::vector<bool> result = decode(message, N, K);

    // Output the decoded vector
    for (size_t i = 0; i < result.size(); ++i) {
        std::cout << result[i];
    }

    return 0;
}

