// Helper lambda for type-specific parsing
void ParsePropertyValue(FProperty* Prop, void* ValuePtr)
{
    // Early exit if null
    if (!Prop || !ValuePtr) return;

    // Dispatch based on property type using cascading casts
    if (auto NumProp = Cast<FNumericProperty>(Prop))
    {
        if (NumProp->IsFloatingPoint())
            NumProp->SetFloatingPointPropertyValue(ValuePtr, NumProp->GetFloatingPointPropertyValue(ValuePtr));
        else if (NumProp->IsInteger())
            NumProp->SetSignedIntPropertyValue(ValuePtr, NumProp->GetSignedIntPropertyValue(ValuePtr));
    }
    else if (auto BoolProp = Cast<FBoolProperty>(Prop))
    {
        bool Val = BoolProp->GetPropertyValue(ValuePtr);
        BoolProp->SetPropertyValue(ValuePtr, Val);
    }
    else if (auto NameProp = Cast<FNameProperty>(Prop))
    {
        FName Val = NameProp->GetPropertyValue(ValuePtr);
        NameProp->SetPropertyValue(ValuePtr, Val);
    }
    else if (auto StrProp = Cast<FStrProperty>(Prop))
    {
        FString Val = StrProp->GetPropertyValue(ValuePtr);
        StrProp->SetPropertyValue(ValuePtr, Val);
    }
    else if (auto TextProp = Cast<FTextProperty>(Prop))
    {
        FText Val = TextProp->GetPropertyValue(ValuePtr);
        TextProp->SetPropertyValue(ValuePtr, Val);
    }
}

// Recursive parser for nested properties and arrays
void TraverseAndParse(FProperty* Property, void* ValuePtr)
{
    if (!Property || !ValuePtr) return;

    // Handle arrays recursively
    if (FArrayProperty* ArrayProp = CastField<FArrayProperty*>(Property))
    {
        FScriptArrayHelper Helper(ArrayProp, ValuePtr);
        int32 Count = Helper.Num();
        int32 Idx = 0;
        while (Idx < Count)
        {
            TraverseAndParse(ArrayProp->Inner, Helper.GetRawPtr(Idx));
            ++Idx;
        }
    }
    else
    {
        ParsePropertyValue(Property, ValuePtr);
    }
}

// Generate normal distribution using Box-Muller with improved randomness handling
void UImplotFunction::MakeNormalDistribution(FNormalDistribution& dist, float Mean, float StdDev)
{
    // Reset data container
    dist.Data.Empty();
    dist.Data.SetNumZeroed(dist.count);

    // Local RNG state (not thread-safe, but matches original intent)
    auto GaussianSample = []() -> double
    {
        static double A = 0.0, B = 0.0;
        static bool Used = false;

        if (!Used)
        {
            double u1 = (double)FMath::Rand() / RAND_MAX;
            double u2 = (double)FMath::Rand() / RAND_MAX;
            A = sqrt(-2.0 * log(u1)) * cos(2.0 * M_PI * u2);
            B = sqrt(-2.0 * log(u1)) * sin(2.0 * M_PI * u2);
            Used = true;
            return A;
        }
        else
        {
            Used = false;
            return B;
        }
    };

    for (int32 i = 0; i < dist.count; ++i)
    {
        dist.Data[i] = static_cast<float>(GaussianSample() * StdDev + Mean);
    }
}

