// Generic array shuffler — rewritten with copy-based swap and clearer loop structure
void UImplotWrapperFunctionLibrary::GenericArray_Shuffle2(void* ArrayBase, const FArrayProperty* ArrayDescriptor)
{
    if (!ArrayBase || !ArrayDescriptor) return;

    FScriptArrayHelper Helper(ArrayDescriptor, ArrayBase);
    const int32 TotalElements = Helper.Num();

    if (TotalElements <= 1) return;

    // Optional logging for bool elements (kept from original)
    if (const FBoolProperty* BoolProp = CastField<const FBoolProperty>(ArrayDescriptor->Inner))
    {
        ensure((BoolProp->ElementSize * BoolProp->ArrayDim) == sizeof(uint8));
        UE_LOG(LogTemp, Log, TEXT("Detected boolean array"));
    }

    // Fisher-Yates shuffle variant
    int32 CurrentIndex = 0;
    while (CurrentIndex < TotalElements)
    {
        int32 SwapIndex = FMath::RandRange(CurrentIndex, TotalElements - 1);
        if (CurrentIndex != SwapIndex)
        {
            // Manual swap using temporary buffer
            uint8 TempBuffer[256]; // Safe upper bound for small element sizes
            void* SrcA = Helper.GetRawPtr(CurrentIndex);
            void* SrcB = Helper.GetRawPtr(SwapIndex);

            // Copy first value to temp
            FMemory::Memcpy(TempBuffer, SrcA, Helper.ElementSize);
            // Move second to first
            FMemory::Memcpy(SrcA, SrcB, Helper.ElementSize);
            // Move temp to second
            FMemory::Memcpy(SrcB, TempBuffer, Helper.ElementSize);
        }
        ++CurrentIndex;
    }
}

#include "libusb.h"
#include "device.h"
#include <cstdio>
#include <cstdint>
#include <cstdlib>
#include <cstring>
#include <queue>
#include <utility>

// Constants for device identification and endpoints
constexpr uint16_t VENDOR_ID   = 0x1546;
constexpr uint16_t PRODUCT_ID  = 0x01A6;
constexpr uint8_t  IFACE_NUM   = 1;
constexpr uint8_t  EP_OUT      = 0x01;
constexpr uint8_t  EP_IN       = 0x82;
constexpr size_t   BUF_SZ      = 1024;

// Internal state container
struct io_context {
    libusb_context* ctx;
    libusb_device_handle* dev;
    libusb_transfer* tx_xfer;
    libusb_transfer* rx_xfer;
    uint8_t in_buf[BUF_SZ];
    size_t in_len;
    std::queue<std::pair<uint8_t*, size_t>> out_q;
    bool tx_ready;
};

static io_context ctx{};
static int connect_usb(void);
static void disconnect_usb(void);
static int get_fds_usb(struct pollfd***);
static int process_events_usb(void);
static int send_data(const uint8_t*, size_t);
static int start_read(size_t);
static void on_rx_complete(libusb_transfer*);
static void on_tx_complete(libusb_transfer*);

extern "C" int parse_ublox_message(uint8_t*, int);

// Device interface table
device dev_usb = {
    .open        = connect_usb,
    .close       = disconnect_usb,
    .get_pollfd  = get_fds_usb,
    .handle_event= process_events_usb,
    .write       = send_data
};

// Establish connection to LEA-6T via USB
static int connect_usb(void)
{
    std::memset(&ctx, 0, sizeof(ctx));
    if (libusb_init(&ctx.ctx) != LIBUSB_SUCCESS) {
        std::fprintf(stderr, "Failed to initialize libusb\n");
        return -1;
    }

    ctx.dev = libusb_open_device_with_vid_pid(ctx.ctx, VENDOR_ID, PRODUCT_ID);
    if (!ctx.dev) {
        std::fprintf(stderr, "LEA-6T not detected\n");
        goto err;
    }

    std::printf("LEA-6T opened successfully\n");

    // Auto-detach kernel driver if supported
    if (libusb_set_auto_detach_kernel_driver(ctx.dev, 1) == LIBUSB_SUCCESS)
        std::printf("Kernel driver auto-detach enabled\n");

    if (libusb_claim_interface(ctx.dev, IFACE_NUM) != LIBUSB_SUCCESS) {
        std::fprintf(stderr, "Interface claim failed\n");
        goto err;
    }
    std::printf("Interface %u claimed\n", IFACE_NUM);

    // Allocate transfers
    ctx.tx_xfer = libusb_alloc_transfer(0);
    ctx.rx_xfer = libusb_alloc_transfer(0);
    if (!ctx.tx_xfer || !ctx.rx_xfer) {
        std::fprintf(stderr, "Transfer allocation failed\n");
        goto err;
    }

    ctx.in_len = 0;
    ctx.tx_ready = true;

    return start_read(BUF_SZ);

err:
    disconnect_usb();
    return -1;
}

// Cleanup resources
static void disconnect_usb(void)
{
    if (ctx.tx_xfer) libusb_free_transfer(ctx.tx_xfer);
    if (ctx.rx_xfer) libusb_free_transfer(ctx.rx_xfer);
    if (ctx.dev) {
        libusb_release_interface(ctx.dev, IFACE_NUM);
        libusb_close(ctx.dev);
    }
    if (ctx.ctx) libusb_exit(ctx.ctx);
}

// Initiate async read from IN endpoint
static int start_read(size_t len)
{
    libusb_fill_bulk_transfer(
        ctx.rx_xfer,
        ctx.dev,
        EP_IN,
        ctx.in_buf + (BUF_SZ - len),
        static_cast<int>(len),
        on_rx_complete,
        nullptr,
        0
    );
    return libusb_submit_transfer(ctx.rx_xfer);
}

// Queue data for transmission
static int send_data(const uint8_t* src, size_t sz)
{
    uint8_t* buf = static_cast<uint8_t*>(std::malloc(sz));
    if (!buf) return -1;

    std::memcpy(buf, src, sz);

    if (ctx.tx_ready) {
        libusb_fill_bulk_transfer(
            ctx.tx_xfer,
            ctx.dev,
            EP_OUT,
            buf,
            static_cast<int>(sz),
            on_tx_complete,
            nullptr,
            0
        );
        libusb_submit_transfer(ctx.tx_xfer);
        ctx.tx_ready = false;
    } else {
        ctx.out_q.emplace(buf, sz);
    }
    return 0;
}

// Retrieve file descriptors for polling
static int get_fds_usb(struct pollfd*** fds_out)
{
    const libusb_pollfd** list = libusb_get_pollfds(ctx.ctx);
    if (!list) return -1;

    int n = 0;
    for (const libusb_pollfd** p = list; *p; ++p) ++n;

    if (n == 0) {
        libusb_free_pollfds(list);
        return 0;
    }

    *fds_out = static_cast<pollfd**>(std::calloc(n, sizeof(**fds_out)));
    for (int i = 0; i < n; ++i) {
        (*fds_out)[i].fd     = list[i]->fd;
        (*fds_out)[i].events = list[i]->events;
    }

    libusb_free_pollfds(list);
    return n;
}

// Handle pending events (non-blocking)
static int process_events_usb(void)
{
    timeval zero = {0, 0};
    return libusb_handle_events_timeout(ctx.ctx, &zero);
}

// Callback for incoming data
static void on_rx_complete(libusb_transfer* xfer)
{
    bool ok = (xfer->status == LIBUSB_TRANSFER_COMPLETED ||
               xfer->status == LIBUSB_TRANSFER_OVERFLOW);

    if (ok) {
        int consumed = parse_ublox_message(ctx.in_buf, static_cast<int>(ctx.in_len + xfer->actual_length));
        size_t remaining = ctx.in_len + xfer->actual_length - consumed;

        if (remaining > 0) {
            std::memmove(ctx.in_buf, ctx.in_buf + consumed, remaining);
        }

        ctx.in_len = remaining;

        if (ctx.in_len < BUF_SZ) {
            start_read(BUF_SZ - ctx.in_len);
        } else {
            ctx.in_len = 0;
            start_read(BUF_SZ);
        }
    } else {
        ctx.in_len = 0;
        start_read(BUF_SZ);
    }
}

// Callback for outgoing data
static void on_tx_complete(libusb_transfer* xfer)
{
    std::free(xfer->buffer);

    if (!ctx.out_q.empty()) {
        auto [data, len] = ctx.out_q.front();
        libusb_fill_bulk_transfer(
            ctx.tx_xfer,
            ctx.dev,
            EP_OUT,
            data,
            static_cast<int>(len),
            on_tx_complete,
            nullptr,
            0
        );
        libusb_submit_transfer(ctx.tx_xfer);
        ctx.out_q.pop();
    } else {
        ctx.tx_ready = true;
    }

    if (xfer->status == LIBUSB_TRANSFER_COMPLETED) {
        std::printf("Sent %d bytes\n", xfer->actual_length);
    }
}

#include <vector>
#include <gtest/gtest.h>
#include <mpi.h>
#include "tasktorrent/tasktorrent.hpp"

using namespace std;
using namespace ttor;

int VERBOSITY_LEVEL = 0;

// Helper to compute next rank in ring topology
inline int next_rank_in_ring(int current, int total) {
    return (current + 1) % total;
}

TEST(ActiveMsgBody, twoStepsBlocking)
{
    const int my_rank = comm_rank();
    const int world_size = comm_size();
    const int MSG_COUNT = 64;
    Communicator world_comm(MPI_COMM_WORLD, VERBOSITY_LEVEL);

    vector<vector<int>> payload(world_size, vector<int>(MSG_COUNT, 0));
    vector<bool> msg_received(world_size, false);
    vector<bool> transfer_done(world_size, false);

    msg_received[my_rank] = true;
    transfer_done[my_rank] = true;

    // Fill local data
    for (int idx = 0; idx < MSG_COUNT; ++idx) {
        payload[my_rank][idx] = my_rank * MSG_COUNT + idx;
    }

    auto active_msg_handler = world_comm.make_large_active_msg(
        [&](int& src, int& dst) {
            EXPECT_EQ(dst, my_rank);
            EXPECT_FALSE(msg_received[src]);
            msg_received[src] = true;
        },
        [&](int& src, int& dst) {
            EXPECT_EQ(dst, my_rank);
            return reinterpret_cast<char*>(payload[src].data());
        },
        [&](int& src, int& dst) {
            EXPECT_EQ(src, my_rank);
            EXPECT_FALSE(transfer_done[dst]);
            transfer_done[dst] = true;
        });

    // Send phase: only sender ranks initiate sends
    for (int sender = 0; sender < world_size; ++sender) {
        if (my_rank == sender) {
            for (int receiver = 0; receiver < world_size; ++receiver) {
                if (receiver != sender) {
                    int source_id = my_rank;
                    auto view_data = view<int>(payload[my_rank].data(), payload[my_rank].size());
                    active_msg_handler->blocking_send_large(receiver, view_data, source_id, receiver);
                }
            }
        } else {
            world_comm.recv_process();
        }
    }

    // Verification phase
    for (int r = 0; r < world_size; ++r) {
        if (r != my_rank) {
            EXPECT_TRUE(msg_received[r]);
            EXPECT_TRUE(transfer_done[r]) << "Transfer incomplete at index " << r << " on rank " << my_rank;
            for (int i = 0; i < MSG_COUNT; ++i) {
                EXPECT_EQ(payload[r][i], r * MSG_COUNT + i);
            }
        }
    }

    EXPECT_EQ(world_comm.get_n_msg_processed(), world_size - 1);
    EXPECT_EQ(world_comm.get_n_msg_queued(), world_size - 1);
    MPI_Barrier(MPI_COMM_WORLD);
}

TEST(ActiveMsgBody, twoStepsMixedNonBlocking)
{
    const int my_rank = comm_rank();
    const int world_size = comm_size();
    const int MSG_COUNT = 64;
    Communicator world_comm(MPI_COMM_WORLD, VERBOSITY_LEVEL);

    vector<vector<int>> payload(world_size, vector<int>(MSG_COUNT, 0));
    vector<int> recv_count(world_size, 0);
    vector<int> completion_count(world_size, 0);

    const int expected_total_ops = 3 * world_size;
    int ops_completed = 0;

    for (int i = 0; i < MSG_COUNT; ++i) {
        payload[my_rank][i] = my_rank * MSG_COUNT + i;
    }

    auto handler_0 = world_comm.make_active_msg(
        [&](int& src, int& dest) {
            EXPECT_EQ(dest, my_rank);
            recv_count[src]++;
            ops_completed++;
        });

    auto handler_1 = world_comm.make_large_active_msg(
        [&](int& src, int& dest) {
            EXPECT_EQ(dest, my_rank);
            recv_count[src]++;
            ops_completed++;
        },
        [&](int& src, int& dest) {
            EXPECT_EQ(dest, my_rank);
            return reinterpret_cast<char*>(payload[src].data());
        },
        [&](int& src, int& dest) {
            EXPECT_EQ(src, my_rank);
            EXPECT_EQ(completion_count[dest], 0);
            completion_count[dest]++;
        });

    auto handler_2 = world_comm.make_active_msg(
        [&](int& src, int& dest) {
            EXPECT_EQ(dest, my_rank);
            recv_count[src]++;
            ops_completed++;
        });

    // Initiate all sends
    for (int dest = 0; dest < world_size; ++dest) {
        int src = my_rank;
        auto v = view<int>(payload[src].data(), payload[src].size());
        handler_0->send(dest, src, dest);
        handler_1->send_large(dest, v, src, dest);
        handler_2->send(dest, src, dest);
    }

    // Wait until all messages processed and expected count reached
    while (!world_comm.is_done() || ops_completed != expected_total_ops) {
        world_comm.progress();
    }

    // Validate results
    for (int r = 0; r < world_size; ++r) {
        EXPECT_EQ(completion_count[r], 1);
        EXPECT_EQ(recv_count[r], 3);
        for (int i = 0; i < MSG_COUNT; ++i) {
            EXPECT_EQ(payload[r][i], r * MSG_COUNT + i);
        }
    }

    EXPECT_EQ(world_comm.get_n_msg_processed(), 3 * world_size);
    EXPECT_EQ(world_comm.get_n_msg_queued(), 3 * world_size);
    MPI_Barrier(MPI_COMM_WORLD);
}

TEST(ActiveMsgBody, multipleBodiesBreakSize)
{
    vector<double> header_factors = {0.001, 0.1, 0.9, 1.1, 1.5, 4.0, 8.0};
    const size_t threshold = (1 << 22); // >1MB but <2^31

    for (auto h_factor : header_factors) {
        for (auto b_factor : header_factors) {
            if (VERBOSITY_LEVEL) {
                printf("Size factor = %e, %e=======================\n", h_factor, b_factor);
            }

            Communicator comm(MPI_COMM_WORLD, VERBOSITY_LEVEL, threshold);
            int done_flag = 0;
            int rcvd_flag = 0;
            const int target = 1;
            int completed_flag = 0;

            size_t hdr_len = static_cast<size_t>(threshold * h_factor);
            size_t body_len = static_cast<size_t>(threshold * b_factor);

            char* hdr_buf = static_cast<char*>(calloc(hdr_len, sizeof(char)));
            char* send_body = static_cast<char*>(calloc(body_len, sizeof(char)));
            char* recv_body = static_cast<char*>(calloc(body_len, sizeof(char)));

            send_body[0] = 'l';
            send_body[body_len - 1] = 'd';
            hdr_buf[0] = 'l';
            hdr_buf[hdr_len - 1] = 'd';

            auto am = comm.make_large_active_msg(
                [&](view<char>& header) {
                    EXPECT_EQ(done_flag, 0);
                    EXPECT_EQ(rcvd_flag, 1);
                    EXPECT_EQ(header.size(), hdr_len);
                    EXPECT_EQ(header.data()[0], 'l');
                    EXPECT_EQ(header.data()[hdr_len - 1], 'd');
                    EXPECT_EQ(recv_body[0], 'l');
                    EXPECT_EQ(recv_body[body_len - 1], 'd');
                    done_flag++;
                },
                [&](view<char>& header) {
                    EXPECT_EQ(header.size(), hdr_len);
                    EXPECT_EQ(header.data()[0], 'l');
                    EXPECT_EQ(header.data()[hdr_len - 1], 'd');
                    EXPECT_EQ(done_flag, 0);
                    EXPECT_EQ(rcvd_flag, 0);
                    rcvd_flag++;
                    return recv_body;
                },
                [&](view<char>&) {
                    completed_flag++;
                });

            auto body_view = view<char>(send_body, body_len);
            auto header_view = view<char>(hdr_buf, hdr_len);
            int peer = next_rank_in_ring(comm_rank(), comm_size());
            am->send_large(peer, body_view, header_view);

            while (!comm.is_done() || done_flag != target) {
                comm.progress();
            }

            EXPECT_EQ(done_flag, target);
            EXPECT_EQ(rcvd_flag, target);
            EXPECT_EQ(completed_flag, 1);
            MPI_Barrier(MPI_COMM_WORLD);

            free(send_body);
            free(recv_body);
            free(hdr_buf);
        }
    }
}

void run_multi_size_test(vector<size_t> sizes, size_t break_point)
{
    Communicator comm(MPI_COMM_WORLD, VERBOSITY_LEVEL, break_point);
    int N = sizes.size();

    vector<unsigned char*> send_bufs(N * N);
    vector<unsigned char*> recv_bufs(N * N);
    vector<unsigned char*> header_bufs(N * N);

    int headers_rcvd = 0;
    int bodies_rcvd = 0;
    const int total_expected = N * N;
    int completed_count = 0;

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int idx = i + j * N;
            size_t hlen = sizes[i];
            size_t blen = sizes[j];

            header_bufs[idx] = static_cast<unsigned char*>(malloc(hlen));
            *(header_bufs[idx]) = static_cast<unsigned char>(-idx);
            *(header_bufs[idx] + hlen - 1) = static_cast<unsigned char>(-idx);

            send_bufs[idx] = static_cast<unsigned char*>(malloc(blen));
            *(send_bufs[idx]) = static_cast<unsigned char>(idx);
            *(send_bufs[idx] + blen - 1) = static_cast<unsigned char>(idx);

            recv_bufs[idx] = static_cast<unsigned char*>(malloc(blen));
            *(recv_bufs[idx]) = 0;
            *(recv_bufs[idx] + blen - 1) = 0;
        }
    }

    auto am = comm.make_large_active_msg(
        [&](int& i, int& j, view<unsigned char>& header) {
            int k = i + j * N;
            size_t hlen = sizes[i];
            EXPECT_EQ(header.size(), hlen);
            EXPECT_EQ(*header.begin(), static_cast<unsigned char>(-k));
            EXPECT_EQ(*(header.end() - 1), static_cast<unsigned char>(-k));

            size_t blen = sizes[j];
            EXPECT_EQ(*(recv_bufs[k]), static_cast<unsigned char>(k));
            EXPECT_EQ(*(recv_bufs[k] + blen - 1), static_cast<unsigned char>(k));
            bodies_rcvd++;
        },
        [&](int& i, int& j, view<unsigned char>& header) {
            int k = i + j * N;
            size_t hlen = sizes[i];
            EXPECT_EQ(header.size(), hlen);
            EXPECT_EQ(*header.begin(), static_cast<unsigned char>(-k));
            EXPECT_EQ(*(header.end() - 1), static_cast<unsigned char>(-k));

            size_t blen = sizes[j];
            EXPECT_EQ(*(recv_bufs[k]), 0u);
            EXPECT_EQ(*(recv_bufs[k] + blen - 1), 0u);
            headers_rcvd++;
            return recv_bufs[k];
        },
        [&](int&, int&, view<unsigned char>&) {
            completed_count++;
        });

    int peer = next_rank_in_ring(comm_rank(), comm_size());

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int k = i + j * N;
            size_t hlen = sizes[i];
            size_t blen = sizes[j];
            auto body_view = view<unsigned char>(send_bufs[k], blen);
            auto header_view = view<unsigned char>(header_bufs[k], hlen);
            am->send_large(peer, body_view, i, j, header_view);
        }
    }

    while (!comm.is_done() || bodies_rcvd != total_expected) {
        comm.progress();
    }

    EXPECT_EQ(bodies_rcvd, total_expected);
    EXPECT_EQ(headers_rcvd, total_expected);
    EXPECT_EQ(completed_count, N * N);

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            int k = i + j * N;
            size_t blen = sizes[j];
            EXPECT_EQ(*(recv_bufs[k]), static_cast<unsigned char>(k));
            EXPECT_EQ(*(recv_bufs[k] + blen - 1), static_cast<unsigned char>(k));
        }
    }

    MPI_Barrier(MPI_COMM_WORLD);

    for (auto ptr : send_bufs) free(ptr);
    for (auto ptr : recv_bufs) free(ptr);
    for (auto ptr : header_bufs) free(ptr);
}

