void FConfigPropertyHelperDetails::CustomizeDetails(IDetailLayoutBuilder& LayoutBuilder)
{
    // Retrieve and hide the main edit property
    TSharedPtr<IPropertyHandle> MainPropHandle = LayoutBuilder.GetProperty("EditProperty");
    LayoutBuilder.HideProperty(MainPropHandle);

    UObject* RawPropObj = nullptr;
    MainPropHandle->GetValue(RawPropObj);
    OriginalProperty = CastChecked<UProperty>(RawPropObj);

    // Build a temporary UClass to host the property for editing
    ConfigEditorPropertyViewClass = NewObject<UClass>(
        GetTransientPackage(),
        TEXT("TempConfigEditorUClass"),
        RF_Public | RF_Standalone
    );

    // Duplicate and attach the target property to the new class
    ConfigEditorCopyOfEditProperty = DuplicateObject<UProperty>(
        OriginalProperty,
        ConfigEditorPropertyViewClass,
        *(RawPropObj->GetName())
    );

    // Configure the class as a config-enabled type
    ConfigEditorPropertyViewClass->ClassConfigName = OriginalProperty->GetOwnerClass()->ClassConfigName;
    ConfigEditorPropertyViewClass->SetSuperStruct(UObject::StaticClass());
    ConfigEditorPropertyViewClass->ClassFlags |= (CLASS_DefaultConfig | CLASS_Config);
    ConfigEditorPropertyViewClass->AddCppProperty(ConfigEditorCopyOfEditProperty);
    ConfigEditorPropertyViewClass->Bind();
    ConfigEditorPropertyViewClass->StaticLink(true);
    ConfigEditorPropertyViewClass->AddToRoot();

    // Initialize CDO and root it
    ConfigEditorPropertyViewCDO = ConfigEditorPropertyViewClass->GetDefaultObject(true);
    ConfigEditorPropertyViewCDO->AddToRoot();

    // Cache config file array handle and hide it
    ConfigFilesHandle = LayoutBuilder.GetProperty("ConfigFilePropertyObjects");
    LayoutBuilder.HideProperty(ConfigFilesHandle);

    // Build UI: add custom row with property table
    IDetailCategoryBuilder& HierarchyCategory = LayoutBuilder.EditCategory("ConfigHierarchy");
    HierarchyCategory.AddCustomRow(LOCTEXT("ConfigHierarchy", "ConfigHierarchy"))
    [
        ConstructPropertyTable(LayoutBuilder)
    ];

    // Subscribe to property change notifications
    FCoreUObjectDelegates::OnObjectPropertyChanged.AddSP(this, &FConfigPropertyHelperDetails::OnPropertyValueChanged);
}

void FConfigPropertyHelperDetails::OnPropertyValueChanged(UObject* ModifiedObject, FPropertyChangedEvent& ChangeEvent)
{
    UClass* OwnerClass = ConfigEditorCopyOfEditProperty->GetOwnerClass();
    if (!ModifiedObject || !ModifiedObject->IsA(OwnerClass))
        return;

    // Check if this object corresponds to a known config file
    const FString* FoundIniName = ConfigFileAndPropertySourcePairings.FindKey(ModifiedObject);
    if (!FoundIniName)
        return;

    const FString& IniFilename = *FoundIniName;

    // Create sandboxed config cache
    FConfigCacheIni SandboxConfig(EConfigCacheType::Temporary);
    FConfigFile& SandboxFile = SandboxConfig.Add(IniFilename, FConfigFile());

    // Save default object state into sandbox
    OriginalProperty->GetOwnerClass()->GetDefaultObject()->SaveConfig(CPF_Config, IniFilename, &SandboxConfig);

    // Validate expected single-file output
    ensureMsgf(SandboxConfig.Num() == 1, TEXT("UObject::UpdateDefaultConfig() unexpectedly modified more than one file in sandbox!"));

    // Extract section and property name
    TArray<FString> SectionKeys;
    SandboxFile.GetKeys(SectionKeys);
    const FString& TargetSection = SectionKeys[0];
    const FString& PropName = ConfigEditorCopyOfEditProperty->GetName();

    // Export current value from modified object
    FString PropertyValueStr;
    ConfigEditorCopyOfEditProperty->ExportText_InContainer(
        0,
        PropertyValueStr,
        ModifiedObject,
        ModifiedObject,
        ModifiedObject,
        0
    );

    // Apply updated value directly to global config
    GConfig->SetString(*TargetSection, *PropName, *PropertyValueStr, IniFilename);
    SandboxFile.UpdateSinglePropertyInSection(IniFilename, PropName, TargetSection);

    // Reload final config and refresh CDO
    FString FinalConfigPath;
    GConfig->LoadGlobalIniFile(FinalConfigPath, OriginalProperty->GetOwnerClass()->ClassConfigName.ToString(), nullptr, true);
    OriginalProperty->GetOwnerClass()->GetDefaultObject()->ReloadConfig();
}

void FConfigPropertyHelperDetails::AddEditablePropertyForConfig(IDetailLayoutBuilder& LayoutBuilder, const UPropertyConfigFileDisplayRow* RowData)
{
    // Register mapping between config file and its editable object
    AssociatedConfigFileAndObjectPairings.Add(RowData->ConfigFileName, (UObject*)RowData);

    // Duplicate CDO per config file instance
    UObject* InstanceObj = StaticDuplicateObject(
        ConfigEditorPropertyViewCDO,
        GetTransientPackage(),
        *(RowData->ConfigFileName + TEXT("_cdoDupe"))
    );
    InstanceObj->AddToRoot();

    // Preload existing value from config
    FString CurrentValueStr;
    static const FString DefaultSection = OriginalProperty->GetOwnerClass()->GetPathName();
    static const FString PropName = ConfigEditorCopyOfEditProperty->GetName();

    if (GConfig->GetString(*DefaultSection, *PropName, CurrentValueStr, RowData->ConfigFileName))
    {
        ConfigEditorCopyOfEditProperty->ImportText(
            *CurrentValueStr,
            ConfigEditorCopyOfEditProperty->ContainerPtrToValuePtr<uint8>(InstanceObj),
            0,
            nullptr
        );
    }

    // Store reference for later updates
    ConfigFileAndPropertySourcePairings.Add(RowData->ConfigFileName, InstanceObj);

    // Add external property row for editing
    TArray<UObject*> ObjList;
    ObjList.Add(InstanceObj);

    if (IDetailPropertyRow* ExtRow = LayoutBuilder.EditCategory("TempCategory").AddExternalProperty(ObjList, ConfigEditorCopyOfEditProperty->GetFName()))
    {
        TSharedPtr<SWidget> NameWidget, ValueWidget;
        ExtRow->GetDefaultWidgets(NameWidget, ValueWidget);

        // Register widget with config editor module
        IConfigEditorModule& ConfigEdMod = FModuleManager::Get().LoadModuleChecked<IConfigEditorModule>("ConfigEditor");
        ConfigEdMod.AddExternalPropertyValueWidgetAndConfigPairing(RowData->ConfigFileName, ValueWidget);

        // Hide internal display
        ExtRow->Visibility(EVisibility::Hidden);
    }
}

TSharedRef<SWidget> FConfigPropertyHelperDetails::ConstructPropertyTable(IDetailLayoutBuilder& LayoutBuilder)
{
    FPropertyEditorModule& PropEditorMod = FModuleManager::LoadModuleChecked<FPropertyEditorModule>("PropertyEditor");

    PropertyTable = PropEditorMod.CreatePropertyTable();
    PropertyTable->SetSelectionMode(ESelectionMode::None);
    PropertyTable->SetSelectionUnit(EPropertyTableSelectionUnit::None);
    PropertyTable->SetIsUserAllowedToChangeRoot(false);
    PropertyTable->SetShowObjectName(false);

    RepopulatePropertyTable(LayoutBuilder);

    // Define custom columns
    TArray<TSharedRef<class IPropertyTableCustomColumn>> CustomCols;

    TSharedRef<FConfigPropertyCustomColumn> EditCol = MakeShareable(new FConfigPropertyCustomColumn());
    EditCol->EditProperty = ConfigEditorCopyOfEditProperty;
    CustomCols.Add(EditCol);

    // Optional: Uncomment if column support is needed
    // TSharedRef<FConfigPropertyConfigFileStateCustomColumn> StateCol = MakeShareable(new FConfigPropertyConfigFileStateCustomColumn());
    // StateCol->SupportedProperty = FindFieldChecked<UProperty>(UPropertyConfigFileDisplay::StaticClass(), TEXT("FileState"));
    // CustomCols.Add(StateCol);

    return PropEditorMod.CreatePropertyTableWidget(PropertyTable.ToSharedRef(), CustomCols);
}

void FConfigPropertyHelperDetails::RepopulatePropertyTable(IDetailLayoutBuilder& LayoutBuilder)
{
    // Reset cached mappings
    AssociatedConfigFileAndObjectPairings.Empty();

    // Iterate over config file entries
    uint32 NumConfigs = 0;
    TSharedPtr<IPropertyHandleArray> ArrayHandle = ConfigFilesHandle->AsArray();
    ArrayHandle->GetNumElements(NumConfigs);

    for (uint32 Idx = 0; Idx < NumConfigs; ++Idx)
    {
        TSharedRef<IPropertyHandle> ElementHandle = ArrayHandle->GetElement(Idx);
        UObject* HelperObj = nullptr;
        ensure(ElementHandle->GetValue(HelperObj) == FPropertyAccess::Success);

        UPropertyConfigFileDisplayRow* Row = CastChecked<UPropertyConfigFileDisplayRow>(HelperObj);
        AddEditablePropertyForConfig(LayoutBuilder, Row);
    }

    // Populate table with objects
    TArray<UObject*> DisplayObjects;
    AssociatedConfigFileAndObjectPairings.GenerateValueArray(DisplayObjects);
    PropertyTable->SetObjects(DisplayObjects);

    // Add columns based on UPropertyConfigFileDisplayRow members
    for (UProperty* NextProp = UPropertyConfigFileDisplayRow::StaticClass()->PropertyLink; NextProp; NextProp = NextProp->PropertyLinkNext)
    {
        PropertyTable->AddColumn((TWeakObjectPtr<UProperty>)NextProp);
    }

    // Lock columns in place
    for (TSharedRef<IPropertyTableColumn> Col : PropertyTable->GetColumns())
    {
        Col->SetFrozen(true);
    }

    PropertyTable->RequestRefresh();
}

