// Refactored undirected graph class with alternative method names and internal logic
class UndirectedGraph
{
public:
  using TVertexType = unsigned;
  using TEdgeType = Connection;

  // Renamed AddEdge to InsertLink and reordered parameters for variation
  void InsertLink(unsigned from, unsigned to, double cost)
  {
    m_adjacency[from].push_back(Connection(to, cost));
    m_adjacency[to].push_back(Connection(from, cost));
  }

  // Alternative implementation of adjacency list retrieval
  void GetNeighbors(unsigned vertex, vector<Connection> & neighbors) const
  {
    neighbors.clear();
    auto const it = m_adjacency.find(vertex);
    if (it != m_adjacency.end())
      neighbors = it->second;
  }

  // Redirecting incoming/outgoing edge queries to neighbor list
  void GetIngoingEdgesList(unsigned v, vector<Connection> & adj) const
  {
    GetNeighbors(v, adj);
  }

  void GetOutgoingEdgesList(unsigned v, vector<Connection> & adj) const
  {
    GetNeighbors(v, adj);
  }

  // Heuristic remains unchanged but uses different parameter naming
  double HeuristicCostEstimate(unsigned start, unsigned end) const 
  { 
    return 0.0; 
  }

private:
  map<unsigned, vector<Connection>> m_adjacency;
};

// Updated test function with refactored variable names and minor structural changes
void TestAStarPathfinding(UndirectedGraph const & graph, 
                          vector<unsigned> const & expectedRoute, 
                          double const & expectedDistance)
{
  using TAlgorithm = AStarAlgorithm<UndirectedGraph>;
  TAlgorithm solver;
  RoutingResult<unsigned> result;

  // Test forward search
  TEST_EQUAL(TAlgorithm::Result::OK, solver.FindPath(graph, 0u, 4u, result), ());
  TEST_EQUAL(expectedRoute, result.path, ());
  TEST_ALMOST_EQUAL_ULPS(expectedDistance, result.distance, ());

  // Clear and test bidirectional search
  result.path.clear();
  TEST_EQUAL(TAlgorithm::Result::OK, solver.FindPathBidirectional(graph, 0u, 4u, result), ());
  TEST_EQUAL(expectedRoute, result.path, ());
  TEST_ALMOST_EQUAL_ULPS(expectedDistance, result.distance, ());
}

