// Convert backslashes to forward slashes in a path string
String remotePath(TCchar* path) {
    String result = path;
    int len = result.length();
    for (int idx = 0; idx < len; ++idx) {
        if (result[idx] == _T('\\')) {
            result[idx] = _T('/');
        }
    }
    return result;
}

// Convert forward slashes to backslashes in a path string
String localPath(TCchar* path) {
    String result = path;
    int len = result.length();
    for (int idx = 0; idx < len; ++idx) {
        if (result[idx] == _T('/')) {
            result[idx] = _T('\\');
        }
    }
    return result;
}

// Extract filename from a path (last component after directory separators)
String parseName(TCchar* path) {
    String result = path;
    int pos = result.findLastOf(_T('\\'));
    if (pos < 0) {
        pos = result.findLastOf(_T('/')); // Also handle forward slashes
        if (pos < 0) return result;
    }
    return result.substr(pos + 1);
}

// Ensure root path ends with a backslash
void fixRootPath(String& root) {
    if (root.empty() || root[root.length() - 1] != _T('\\')) {
        root += _T('\\');
    }
}

