// Extracts the local bind pose for a specific joint from the skeleton's SoA-formatted bind pose.
math::Transform GetJointLocalBindPose(const Skeleton& _skeleton, int _joint) {
  assert(_joint >= 0 && _joint < _skeleton.num_joints() &&
         "Joint index out of range.");

  const int soa_index = _joint / 4;
  const int lane_index = _joint % 4;

  const ozz::math::SoaTransform& soa_data = _skeleton.bind_pose()[soa_index];

  // Convert SoA (Structure-of-Arrays) to AoS (Array-of-Structures)
  ozz::math::SimdFloat4 trans_vecs[4];
  ozz::math::Transpose3x4(&soa_data.translation.x, trans_vecs);

  ozz::math::SimdFloat4 rot_vecs[4];
  ozz::math::Transpose4x4(&soa_data.rotation.x, rot_vecs);

  ozz::math::SimdFloat4 scale_vecs[4];
  ozz::math::Transpose3x4(&soa_data.scale.x, scale_vecs);

  math::Transform result;
  ozz::math::Store3PtrU(trans_vecs[lane_index], &result.translation.x);
  ozz::math::StorePtrU(rot_vecs[lane_index], &result.rotation.x);
  ozz::math::Store3PtrU(scale_vecs[lane_index], &result.scale.x);

  return result;
}

// Helper macro: checks whether the next joint shares the same parent (i.e., is a sibling)
#define _IS_SIBLING(_idx, _total, _props) \
  ((_idx + 1 < _total) && (_props[_idx].parent == _props[_idx + 1].parent))

// Performs depth-first traversal over joint hierarchy using an explicit stack.
void IterateJointsDF(const Skeleton& _skeleton, int _start_joint,
                     JointsIterator* _iter) {
  assert(_iter != nullptr);

  const int total_joints = _skeleton.num_joints();
  const Range<const Skeleton::JointProperties> props_range =
      _skeleton.joint_properties();

  // Early exit conditions
  if (total_joints == 0) {
    _iter->num_joints = 0;
    return;
  }

  if (_start_joint != Skeleton::kNoParentIndex &&
      (_start_joint < 0 || _start_joint >= total_joints)) {
    _iter->num_joints = 0;
    return;
  }

  // Stack structure to simulate recursion
  struct Frame {
    uint16_t joint_id : 15;
    uint16_t has_sibling : 1;
  };

  Frame dfs_stack[Skeleton::kMaxJoints];
  int stack_top = -1;

  // Initialize starting frame
  Frame initial_frame;
  if (_start_joint != Skeleton::kNoParentIndex) {
    initial_frame.joint_id = static_cast<uint16_t>(_start_joint);
    initial_frame.has_sibling = 0;
  } else {
    initial_frame.joint_id = 0;
    initial_frame.has_sibling = _IS_SIBLING(0, total_joints, props_range.begin);
  }
  dfs_stack[++stack_top] = initial_frame;

  _iter->num_joints = 0;

  while (stack_top >= 0) {
    const Frame& current = dfs_stack[stack_top];
    _iter->joints[_iter->num_joints++] = current.joint_id;

    // If current joint is not a leaf, find its first child
    if (!props_range.begin[current.joint_id].is_leaf) {
      uint16_t child_candidate = current.joint_id + 1;
      while (child_candidate < total_joints &&
             props_range.begin[child_candidate].parent != current.joint_id) {
        ++child_candidate;
      }

      if (child_candidate < total_joints) {
        Frame child_frame;
        child_frame.joint_id = child_candidate;
        child_frame.has_sibling =
            _IS_SIBLING(child_candidate, total_joints, props_range.begin);
        dfs_stack[++stack_top] = child_frame;
        continue;
      }
    }

    // Backtrack: pop frames until we find one with a sibling
    while (stack_top >= 0 && !dfs_stack[stack_top].has_sibling) {
      --stack_top;
    }

    // If there's a sibling, replace current frame with it
    if (stack_top >= 0) {
      Frame& sibling_frame = dfs_stack[stack_top];
      assert(sibling_frame.has_sibling && sibling_frame.joint_id + 1 < total_joints);
      sibling_frame.joint_id++;
      sibling_frame.has_sibling =
          _IS_SIBLING(sibling_frame.joint_id, total_joints, props_range.begin);
    }
  }

#undef _IS_SIBLING
}

