#include "Transforms/MultiTransformer.h"

void UMultiTransformer::Setup(UInteractiveGizmoManager* ManagerIn, IToolContextTransactionProvider* TxnProviderIn)
{
	GizmoManager = ManagerIn;
	TransactionProvider = TxnProviderIn;

	CurrentFrame = FFrame3d();
	CurrentScale = FVector3d::One();
	CurrentMode = EMultiTransformerMode::DefaultGizmo;

	// Initialize proxy object for gizmo interaction
	ProxyActor = NewObject<UTransformProxy>(this);
	ProxyActor->SetTransform(CurrentFrame.ToFTransform());

	ActivateGizmo(true);

	// Bind delegate callbacks to proxy events
	ProxyActor->OnTransformChanged.AddUObject(this, &UMultiTransformer::HandleProxyTransformUpdate);
	ProxyActor->OnBeginTransformEdit.AddUObject(this, &UMultiTransformer::HandleTransformStart);
	ProxyActor->OnEndTransformEdit.AddUObject(this, &UMultiTransformer::HandleTransformEnd);
}

void UMultiTransformer::Cleanup()
{
	if (GizmoManager != nullptr)
	{
		GizmoManager->DestroyAllGizmosByOwner(this);
	}
}

void UMultiTransformer::SetCoordinateSystemOverride(EToolContextCoordinateSystem System)
{
	if (GizmoSpace != System || !bIsCoordSystemForced)
	{
		bIsCoordSystemForced = true;
		GizmoSpace = System;

		if (MainGizmo != nullptr)
		{
			ActivateGizmo(false);
			ActivateGizmo(true);
		}
	}
}

void UMultiTransformer::ConfigureActiveGizmoComponents(ETransformGizmoSubElements ActiveParts)
{
	if (ActiveSubElements != ActiveParts)
	{
		ActiveSubElements = ActiveParts;

		if (MainGizmo != nullptr)
		{
			ActivateGizmo(false);
			ActivateGizmo(true);
		}
	}
}

void UMultiTransformer::SwitchMode(EMultiTransformerMode NewState)
{
	if (NewState != CurrentMode)
	{
		if (NewState == EMultiTransformerMode::DefaultGizmo)
		{
			ActivateGizmo(true);
		}
		else
		{
			ActivateGizmo(false);
		}
		CurrentMode = NewState;
	}
}

