void UMultiTransformer::InitializeFromWorldFrame(const FFrame3d& Frame, bool bClearScale)
{
	CurrentFrame = Frame;
	if (bClearScale)
	{
		CurrentScale = FVector3d::One();
	}

	if (MainGizmo != nullptr)
	{
		MainGizmo->ReinitializeGizmoTransform(CurrentFrame.ToFTransform());
	}
}

void UMultiTransformer::ApplyWorldFrameUpdate(const FFrame3d& Frame, bool bResetScaleFactor)
{
	CurrentFrame = Frame;
	if (bResetScaleFactor)
	{
		CurrentScale = FVector3d::One();
	}

	if (MainGizmo != nullptr)
	{
		MainGizmo->SetNewGizmoTransform(CurrentFrame.ToFTransform());
	}
}

void UMultiTransformer::ResetScaling()
{
	CurrentScale = FVector3d::One();

	if (MainGizmo != nullptr)
	{
		MainGizmo->SetNewChildScale(FVector::OneVector);
	}
}

void UMultiTransformer::HandleProxyTransformUpdate(UTransformProxy* Actor, FTransform Transform)
{
	CurrentFrame = FFrame3d(Transform);
	CurrentScale = FVector3d(Transform.GetScale3D());
	OnTransformUpdated.Broadcast();
}

void UMultiTransformer::HandleTransformStart(UTransformProxy* Actor)
{
	bCurrentlyEditing = true;
	OnTransformStarted.Broadcast();
}

void UMultiTransformer::HandleTransformEnd(UTransformProxy* Actor)
{
	bCurrentlyEditing = false;
	OnTransformCompleted.Broadcast();
}

void UMultiTransformer::ActivateGizmo(bool bShow)
{
	if (!bShow)
	{
		if (GizmoManager != nullptr)
		{
			GizmoManager->DestroyAllGizmosByOwner(this);
		}
		MainGizmo = nullptr;
	}
	else
	{
		check(MainGizmo == nullptr);

		MainGizmo = GizmoManager->CreateCustomTransformGizmo(ActiveSubElements, this);

		if (bIsCoordSystemForced)
		{
			MainGizmo->bUseContextCoordinateSystem = false;
			MainGizmo->CurrentCoordinateSystem = GizmoSpace;
		}

		MainGizmo->SetActiveTarget(ProxyActor, TransactionProvider);
		MainGizmo->ReinitializeGizmoTransform(CurrentFrame.ToFTransform());
		MainGizmo->SetVisibility(bTargetVisibility);
	}
}

