CDVDAudio::CDVDAudio(CDVDClock *clock) : m_pClock(clock) {
    m_pAudioStream = nullptr;
    m_bPassthrough = false;
    m_iBitsPerSample = 0;
    m_sampleRate = 0; // renamed from m_sampeRate for typo fix
    m_bPaused = true;
    m_currentPts = DVD_NOPTS_VALUE; // renamed from m_playingPts
    m_ptsTimestamp = 0.0;
    m_syncOffset = 0.0;
    m_syncOffsetTime = 0;
}

CDVDAudio::~CDVDAudio() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream) {
        CAEFactory::FreeStream(m_pAudioStream);
        m_pAudioStream = nullptr;
    }
}

bool CDVDAudio::Initialize(const DVDAudioFrame &frame, AVCodecID codec, bool useResampler) {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);

    unsigned int flags = 0;
    if (useResampler && !frame.passthrough)
        flags |= AESTREAM_FORCE_RESAMPLE;
    flags |= AESTREAM_PAUSED;

    AEAudioFormat fmt = frame.format;
    m_pAudioStream = CAEFactory::MakeStream(fmt, flags, this);

    if (!m_pAudioStream)
        return false;

    m_sampleRate = frame.format.m_sampleRate;
    m_iBitsPerSample = frame.bits_per_sample;
    m_bPassthrough = frame.passthrough;
    m_channelLayout = frame.format.m_channelLayout;

    return true;
}

void CDVDAudio::Shutdown() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream) {
        CAEFactory::FreeStream(m_pAudioStream);
        m_pAudioStream = nullptr;
    }
    m_sampleRate = 0;
    m_iBitsPerSample = 0;
    m_bPassthrough = false;
    m_bPaused = true;
    m_currentPts = DVD_NOPTS_VALUE;
}

unsigned int CDVDAudio::EnqueueFrames(const DVDAudioFrame &frame) {
    m_abortRequested = false;
    std::unique_lock<std::recursive_mutex> lock(m_critSection);

    if (!m_pAudioStream)
        return 0;

    CAESyncInfo sync = m_pAudioStream->GetSyncInfo();
    if (sync.state == CAESyncInfo::SYNC_INSYNC) {
        unsigned long newTime = sync.errortime;
        if (newTime != m_syncOffsetTime) {
            m_syncOffsetTime = newTime;
            m_syncOffset = static_cast<double>(sync.error) / 1000.0 * DVD_TIME_BASE;
            m_resampleFactor = sync.rr;
        }
    } else {
        m_syncOffsetTime = 0;
        m_syncOffset = 0.0;
    }

    double deadline = DVD_SEC_TO_TIME(m_pAudioStream->GetDelay()) + frame.duration;
    deadline += DVD_SEC_TO_TIME(1.0);
    deadline += m_pClock->GetAbsoluteClock();

    unsigned int totalFrames = frame.nb_frames;
    unsigned int remaining = frame.nb_frames;
    size_t byteOffset = 0;

    while (remaining > 0 && !m_abortRequested) {
        double ptsVal = (byteOffset == 0) ? frame.pts / DVD_TIME_BASE * 1000.0 : 0.0;
        unsigned int written = m_pAudioStream->AddData(frame.data, byteOffset, remaining, ptsVal);
        byteOffset += written;
        remaining -= written;

        if (written == 0 && m_pClock->GetAbsoluteClock() > deadline)
            break;

        lock.unlock();
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
        lock.lock();
    }

    m_currentPts = frame.pts + frame.duration - GetDelayInternal();
    m_ptsTimestamp = m_pClock->GetAbsoluteClock();

    return totalFrames - remaining;
}

void CDVDAudio::DrainOutput() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream)
        m_pAudioStream->Drain(true);
}

void CDVDAudio::PausePlayback() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream)
        m_pAudioStream->Pause();
    m_currentPts = DVD_NOPTS_VALUE;
}

void CDVDAudio::ResumePlayback() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream)
        m_pAudioStream->Resume();
}

double CDVDAudio::GetLatency() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    double delay = 0.3;
    if (m_pAudioStream)
        delay = m_pAudioStream->GetDelay();
    return delay * DVD_TIME_BASE;
}

void CDVDAudio::FlushBuffers() {
    m_abortRequested = true;
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream) {
        m_pAudioStream->Flush();
    }
    m_currentPts = DVD_NOPTS_VALUE;
    m_syncOffset = 0.0;
    m_syncOffsetTime = 0;
}

void CDVDAudio::SignalAbort() { m_abortRequested = true; }

bool CDVDAudio::MatchesFormat(const DVDAudioFrame &frame) const {
    if (!m_pAudioStream)
        return false;
    if (frame.passthrough != m_bPassthrough)
        return false;
    if (m_sampleRate != frame.format.m_sampleRate ||
        m_iBitsPerSample != frame.bits_per_sample ||
        m_channelLayout != frame.format.m_channelLayout)
        return false;
    return true;
}

double CDVDAudio::GetCurrentBufferedTime() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (!m_pAudioStream)
        return 0.0;
    return m_pAudioStream->GetCacheTime();
}

double CDVDAudio::GetTotalBufferCapacity() {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (!m_pAudioStream)
        return 0.0;
    return m_pAudioStream->GetCacheTotal();
}

double CDVDAudio::GetCurrentPresentationTime() {
    if (m_currentPts == DVD_NOPTS_VALUE)
        return 0.0;

    double now = m_pClock->GetAbsoluteClock();
    double elapsed = now - m_ptsTimestamp;
    double buffered = GetCurrentBufferedTime();
    double consumed = (elapsed < buffered) ? elapsed : buffered;

    m_ptsTimestamp = now;
    m_currentPts += consumed;
    return m_currentPts;
}

double CDVDAudio::GetTimingError() { return m_syncOffset; }

void CDVDAudio::ApplyTimingCorrection(double adjustment) {
    m_syncOffset += adjustment;
}

double CDVDAudio::GetResampleRate() { return m_resampleFactor; }

void CDVDAudio::ConfigureResampling(int mode) {
    std::lock_guard<std::recursive_mutex> guard(m_critSection);
    if (m_pAudioStream)
        m_pAudioStream->SetResampleMode(mode);
}

double CDVDAudio::GetReferenceTime() {
    if (m_pClock)
        return (m_pClock->GetClock() + m_pClock->GetVsyncAdjust()) /
               DVD_TIME_BASE * 1000.0;
    else
        return 0.0;
}

double CDVDAudio::GetPlaybackSpeed() {
    if (m_pClock)
        return m_pClock->GetClockSpeed();
    else
        return 1.0;
}

// Helper to avoid duplication in GetDelay()
double CDVDAudio::GetDelayInternal() {
    if (m_pAudioStream)
        return m_pAudioStream->GetDelay();
    return 0.3;
}

