#include "QrDecoder.h"
#include "quirc/quirc.h"
#include <qdebug.h>
#include "quirc/quirc_internal.h"

QrDecoder::QrDecoder()
    : m_qr(quirc_new())
{
}

QrDecoder::~QrDecoder()
{
    if (m_qr != nullptr) {
        quirc_destroy(m_qr);
        m_qr = nullptr;
    }
}

QVector<QString> QrDecoder::decode(const QImage &image)
{
    QVector<QString> decodedStrings;

    // Validate decoder instance
    if (!m_qr) {
        return decodedStrings;
    }

    // Resize the QR context to match image dimensions
    if (quirc_resize(m_qr, image.width(), image.height()) < 0) {
        return decodedStrings;
    }

    // Get raw buffer for image data
    uint8_t* buffer = quirc_begin(m_qr, nullptr, nullptr);
    if (!buffer) {
        return decodedStrings;
    }

    // Copy grayscale image data into the buffer
    const int totalPixels = image.width() * image.height();
    std::copy(image.constBits(), image.constBits() + totalPixels, buffer);

    // Process the image for QR codes
    quirc_end(m_qr);

    // Count detected QR codes
    int qrCount = quirc_count(m_qr);
    if (qrCount <= 0) {
        return decodedStrings;
    }

    // Extract and decode each QR code
    for (int i = 0; i < qrCount; ++i) {
        quirc_code qrCode;
        quirc_extract(m_qr, i, &qrCode);

        quirc_data qrData;
        quirc_decode_error_t status = quirc_decode(&qrCode, &qrData);

        if (status == QUIRC_SUCCESS) {
            QString content = QLatin1String(reinterpret_cast<const char*>(qrData.payload));
            decodedStrings.append(content);
        }
    }

    return decodedStrings;
}

