namespace eloqstore
{

WriteBufferAggregator::WriteBufferAggregator(size_t max_chunk_size)
    : chunk_capacity_(max_chunk_size),
      current_usage_(0),
      next_position_(0),
      active_buffer_(nullptr),
      buffer_slot_(0),
      file_identifier_(0),
      base_offset_(0),
      is_fixed_layout_(true)
{
}

void WriteBufferAggregator::Clear()
{
    active_buffer_ = nullptr;
    buffer_slot_ = 0;
    is_fixed_layout_ = true;
    file_identifier_ = 0;
    base_offset_ = 0;
    next_position_ = 0;
    current_usage_ = 0;
    page_list_.clear();
    deallocation_pointers_.clear();
    index_deallocations_.clear();
}

bool WriteBufferAggregator::HasActiveBuffer() const
{
    return active_buffer_ != nullptr;
}

bool WriteBufferAggregator::ContainsData() const
{
    return HasActiveBuffer() && current_usage_ > 0;
}

void WriteBufferAggregator::AssignBuffer(char *buffer,
                                         uint16_t slot_id,
                                         FileId fid,
                                         uint64_t initial_pos,
                                         bool fixed_mode)
{
    active_buffer_ = buffer;
    buffer_slot_ = slot_id;
    is_fixed_layout_ = fixed_mode;
    file_identifier_ = fid;
    base_offset_ = initial_pos;
    next_position_ = initial_pos;
    current_usage_ = 0;
    page_list_.clear();
    deallocation_pointers_.clear();
    index_deallocations_.clear();
}

bool WriteBufferAggregator::IsAppendable(FileId fid,
                                         uint64_t pos,
                                         size_t len) const
{
    if (!HasActiveBuffer())
        return false;

    if (fid != file_identifier_)
        return false;

    if (pos != next_position_)
    {
        LOG(INFO) << "WriteBufferAggregator::IsAppendable non-contiguous position="
                  << pos << " expected=" << next_position_
                  << " file_id=" << file_identifier_;
        return false;
    }

    if (current_usage_ + len > chunk_capacity_)
        return false;

    return true;
}

char *WriteBufferAggregator::AttemptAllocate(FileId fid,
                                             uint64_t pos,
                                             size_t len)
{
    if (!IsAppendable(fid, pos, len))
        return nullptr;

    char *dest = active_buffer_ + current_usage_;
    current_usage_ += len;
    next_position_ += len;
    return dest;
}

void WriteBufferAggregator::EnqueuePage(VarPage page,
                                        char *dealloc_ptr,
                                        uint16_t dealloc_idx)
{
    page_list_.emplace_back(std::move(page));
    deallocation_pointers_.push_back(dealloc_ptr);
    index_deallocations_.push_back(dealloc_idx);
}

bool WriteBufferAggregator::NeedsFlush(size_t upcoming_size) const
{
    if (!HasActiveBuffer())
        return false;

    return current_usage_ + upcoming_size > chunk_capacity_;
}

WriteBufferBatch WriteBufferAggregator::ExtractBatch()
{
    WriteBufferBatch result;
    result.buffer = active_buffer_;
    result.buffer_index = buffer_slot_;
    result.use_fixed = is_fixed_layout_;
    result.file_id = file_identifier_;
    result.start_offset = base_offset_;
    result.bytes = current_usage_;
    result.pages = std::move(page_list_);
    result.release_ptrs = std::move(deallocation_pointers_);
    result.release_indices = std::move(index_deallocations_);

    // Reset state to initial condition
    active_buffer_ = nullptr;
    buffer_slot_ = 0;
    is_fixed_layout_ = true;
    file_identifier_ = 0;
    base_offset_ = 0;
    next_position_ = 0;
    current_usage_ = 0;
    page_list_.clear();
    deallocation_pointers_.clear();
    index_deallocations_.clear();

    return result;
}

