namespace {
// Helper functions for case-insensitive string analysis
bool IsLowercase(char ch) { return 'a' <= ch && ch <= 'z'; }
bool IsUppercase(char ch) { return 'A' <= ch && ch <= 'Z'; }
char ConvertToLower(char ch) { return IsUppercase(ch) ? ch + ('a' - 'A') : ch; }

std::string ToLowerCase(const std::string& input) {
  std::string result = input;
  std::transform(result.begin(), result.end(), result.begin(), ConvertToLower);
  return result;
}

template <typename Predicate>
bool CheckAllCharacters(const std::string& text, Predicate condition) {
  for (size_t index = 0; index < text.length(); ++index) {
    if (!condition(text[index])) {
      return false;
    }
  }
  return true;
}

// Determines if a string follows flexible casing:
// - All uppercase (e.g., "HELLO")
// - All lowercase (e.g., "hello")
// - First letter uppercase, rest lowercase (e.g., "Hello")
// - First letter uppercase, rest uppercase (e.g., "HOLLA")
bool HasFlexibleCase(const std::string& text) {
  if (text.empty()) {
    return true;
  }

  if (CheckAllCharacters(text, IsLowercase)) {
    return true;
  }

  bool firstCharIsUpper = IsUppercase(text[0]);
  std::string remainingPart = text.substr(1);

  return firstCharIsUpper && 
         (CheckAllCharacters(remainingPart, IsLowercase) || 
          CheckAllCharacters(remainingPart, IsUppercase));
}
}

namespace YAML {
bool convert<bool>::decode(const Node& node, bool& value) {
  if (!node.IsScalar()) {
    return false;
  }

  // Boolean parsing table based on YAML spec
  static const struct {
    std::string positiveForm;
    std::string negativeForm;
  } booleanPairs[] = {
    {"y", "n"}, {"yes", "no"}, {"true", "false"}, {"on", "off"}
  };

  if (!HasFlexibleCase(node.Scalar())) {
    return false;
  }

  std::string normalizedScalar = ToLowerCase(node.Scalar());

  for (size_t i = 0; i < sizeof(booleanPairs) / sizeof(booleanPairs[0]); ++i) {
    if (booleanPairs[i].positiveForm == normalizedScalar) {
      value = true;
      return true;
    }
    if (booleanPairs[i].negativeForm == normalizedScalar) {
      value = false;
      return true;
    }
  }

  return false;
}
}

#include "focuscontroller.hpp"
#include "application/model/clientmanager.hpp"
#include "application/model/focusedclientstack.hpp"
#include "application/model/kakouneclient.hpp"

void FocusController::init(FocusedClientStack *stack, ClientManager *manager,
                           PaneLayout *layout, domain::Window *window) {
    m_focused_client_stack = stack;
    m_pane_layout = layout;
    m_client_manager = manager;

    // Register handlers for client lifecycle events
    m_client_manager->onClientAdded([this](KakouneClient *client) {
        m_focused_client_stack->activate(client);
    });

    m_client_manager->onClientRemoved([this](KakouneClient *client) {
        m_focused_client_stack->erase(client);
    });

    // Set up window event callbacks
    window->onMouseMove([this](float x, float y) {
        handleMouseMove(x, y);
    });

    window->onMouseButton([this](domain::MouseButtonEvent evt) {
        handleMouseButton(evt);
    });
}

void FocusController::handleMouseMove(float x, float y) {
    // Skip re-focusing if mouse button is currently held down
    if (m_is_mouse_pressed) {
        return;
    }

    // Find pane under cursor and update focus if needed
    Pane *pane = m_pane_layout->locatePaneAt(x, y);
    if (pane && pane->client != m_focused_client_stack->active()) {
        m_focused_client_stack->activate(pane->client);
    }
}

void FocusController::handleMouseButton(domain::MouseButtonEvent evt) {
    switch (evt.action) {
        case domain::MouseButtonAction::PRESS:
            m_is_mouse_pressed = true;
            break;
        case domain::MouseButtonAction::RELEASE:
            m_is_mouse_pressed = false;
            // Re-check focus after release to ensure correct pane gets focus
            handleMouseMove(evt.x, evt.y);
            break;
        default:
            break;
    }
}

#include <vector>
#include <unordered_set>

class Solution {
public:
    int subarrayBitwiseORs(std::vector<int>& A) {
        std::unordered_set<int> allResults;
        std::unordered_set<int> currentSet;

        for (int value : A) {
            std::unordered_set<int> nextSet;
            nextSet.insert(value);

            for (int prevValue : currentSet) {
                nextSet.insert(value | prevValue);
            }

            currentSet = nextSet;

            for (int val : currentSet) {
                allResults.insert(val);
            }
        }

        return allResults.size();
    }
};

