// Helper to build endpoint spec string based on transport, encryption, and domain
static std::string MakeEndpointSpec(Endpoint::DomainType domain,
                                    Endpoint::TransportType trans,
                                    Endpoint::EncryptionType enc,
                                    const std::string& addr,
                                    uint16_t port_num) {
  std::string spec;

  // Determine protocol prefix
  if (trans == Endpoint::TransportType::HTTP) {
    spec = kHttp;
  } else if (trans == Endpoint::TransportType::PGSQL) {
    spec = kPgSql;
  }

  // Append transport scheme
  if (enc == Endpoint::EncryptionType::None) {
    spec += "tcp://";
  } else if (enc == Endpoint::EncryptionType::SSL) {
    spec += "ssl://";
  }

  // Format host + port depending on IP version
  if (domain == Endpoint::DomainType::IPv4) {
    spec += addr + ":" + string_utils::Itoa(port_num);
  } else if (domain == Endpoint::DomainType::IPv6) {
    spec += "[" + addr + "]" + ":" + string_utils::Itoa(port_num);
  } else {
    SDB_ASSERT(false && "Unsupported domain type");
  }

  return spec;
}

