EndpointIp::EndpointIp(DomainType domain_type, EndpointType ep_type,
                       TransportType transport, EncryptionType encryption,
                       int backlog_size, bool allow_reuse,
                       const std::string& ip_addr, const uint16_t port_num)
  : Endpoint(domain_type, ep_type, transport, encryption,
             MakeEndpointSpec(domain_type, transport, encryption, ip_addr, port_num),
             backlog_size),
    _host(ip_addr),
    _port(port_num),
    _reuse_address(allow_reuse) {
  SDB_ASSERT(domain_type == Endpoint::DomainType::IPv4 ||
             domain_type == Endpoint::DomainType::IPv6);
}

