////////////////////////////////////////////////////////////////////////////////
/// Internal helper to establish connection or bind/listen for server
////////////////////////////////////////////////////////////////////////////////
SocketWrapper EndpointIp::connectSocket(const struct addrinfo* ai_ptr,
                                        double conn_timeout,
                                        double req_timeout) {
  const char* err_str;
  char err_msg[1080];

  // Resolve address/port into human-readable form
  char ip_host[NI_MAXHOST];
  char svc_port[NI_MAXSERV];
  if (::getnameinfo(ai_ptr->ai_addr, (socklen_t)ai_ptr->ai_addrlen,
                    ip_host, sizeof(ip_host), svc_port, sizeof(svc_port),
                    NI_NUMERICHOST | NI_NUMERICSERV) == 0) {
    SDB_TRACE("xxxxx", sdb::Logger::FIXME, "binding to '", ip_host,
              "', port ", _port);
  }

  SocketWrapper sock;
  sock = Sdbsocket(ai_ptr->ai_family, ai_ptr->ai_socktype, ai_ptr->ai_protocol);
  if (!Sdbisvalidsocket(sock)) {
    err_str = STR_ERROR();
    snprintf(err_msg, sizeof(err_msg), "socket() failed with %d - %s", errno,
             err_str);
    error_message = err_msg;
    return sock;
  }

  if (_type == EndpointType::Server) {
    // Reuse address option
    if (_reuse_address) {
      int yes = 1;
      if (Sdbsetsockopt(sock, SOL_SOCKET, SO_REUSEADDR,
                        reinterpret_cast<char*>(&yes), sizeof(yes)) == -1) {
        err_str = STR_ERROR();
        snprintf(err_msg, sizeof(err_msg), "setsockopt(SO_REUSEADDR) failed: #%d - %s",
                 errno, err_str);
        error_message = err_msg;
        Sdbclosesocket(sock);
        Sdbinvalidatesocket(&sock);
        return sock;
      }
    }

    // Bind step
    int rc = Sdbbind(sock, ai_ptr->ai_addr, ai_ptr->ai_addrlen);
    if (rc != 0) {
      err_str = STR_ERROR();
      snprintf(err_msg, sizeof(err_msg),
               "bind(address '%s', port %d) failed: #%d - %s", ip_host,
               (int)_port, errno, err_str);
      error_message = err_msg;
      Sdbclosesocket(sock);
      Sdbinvalidatesocket(&sock);
      return sock;
    }

    // Listen step
    SDB_TRACE("xxxxx", sdb::Logger::FIXME, "backlog size set to ", _listen_backlog);
    rc = Sdblisten(sock, _listen_backlog);
    if (rc != 0) {
      err_str = STR_ERROR();
      snprintf(err_msg, sizeof(err_msg), "listen() failed: #%d - %s", errno,
               err_str);
      error_message = err_msg;
      Sdbclosesocket(sock);
      Sdbinvalidatesocket(&sock);
      return sock;
    }

  } else if (_type == EndpointType::Client) {
    setTimeout(sock, conn_timeout);
    int res = Sdbconnect(sock, (const struct sockaddr*)ai_ptr->ai_addr,
                         ai_ptr->ai_addrlen);
    if (res != 0) {
      err_str = STR_ERROR();
      snprintf(err_msg, sizeof(err_msg), "connect() failed: #%d - %s", errno,
               err_str);
      error_message = err_msg;
      Sdbclosesocket(sock);
      Sdbinvalidatesocket(&sock);
      return sock;
    }
  }

  // Apply common socket flags
  if (!setSocketFlags(sock)) {
    Sdbclosesocket(sock);
    Sdbinvalidatesocket(&sock);
    return sock;
  }

  if (_type == EndpointType::Client) {
    setTimeout(sock, req_timeout);
  }

  _connected = true;
  _socket = sock;
  return _socket;
}

////////////////////////////////////////////////////////////////////////////////
/// Public method to initiate connection using DNS resolution
////////////////////////////////////////////////////////////////////////////////
SocketWrapper EndpointIp::connect(double connect_timeout,
                                  double request_timeout) {
  struct addrinfo* info_list = nullptr;
  struct addrinfo hints;
  int status;
  SocketWrapper result_socket;
  Sdbinvalidatesocket(&result_socket);

  SDB_DEBUG("xxxxx", sdb::Logger::FIXME, "connecting to endpoint '",
            _specification, "'");
  SDB_ASSERT(!Sdbisvalidsocket(_socket));
  SDB_ASSERT(!_connected);

  memset(&hints, 0, sizeof(hints));
  hints.ai_family   = domain();         // IPv4 or IPv6
  hints.ai_flags    = AI_PASSIVE | AI_NUMERICSERV | AI_ALL;
  hints.ai_socktype = SOCK_STREAM;

  std::string port_str = string_utils::Itoa(_port);
  status = getaddrinfo(_host.c_str(), port_str.c_str(), &hints, &info_list);
  if (status != 0) {
    error_message = std::string("getaddrinfo for '") + _host +
                    std::string("': ") + gai_strerror(status);
    if (info_list != nullptr) {
      freeaddrinfo(info_list);
    }
    return result_socket;
  }

  // Iterate through results until one succeeds
  struct addrinfo* current = info_list;
  while (current != nullptr) {
    result_socket = connectSocket(current, connect_timeout, request_timeout);
    if (Sdbisvalidsocket(result_socket)) {
      break;  // success!
    }
    current = current->ai_next;
  }

  freeaddrinfo(info_list);
  return result_socket;
}

////////////////////////////////////////////////////////////////////////////////
/// Disconnect and clean up socket resources
////////////////////////////////////////////////////////////////////////////////
void EndpointIp::disconnect() {
  if (_connected) {
    SDB_ASSERT(Sdbisvalidsocket(_socket));
    _connected = false;
    Sdbclosesocket(_socket);
    Sdbinvalidatesocket(&_socket);
  }
}

