// Safe replacement for mkdtemp on Windows
inline char* safe_mkdtemp(char* templ) {
  if (!templ || std::strlen(templ) == 0) return nullptr;
  if (_mktemp_s(templ, std::strlen(templ) + 1) != 0) return nullptr;
  if (_mkdir(templ) != 0) return nullptr;
  return templ;
}
