struct TestIterationCounter final : ::testing::Environment {
  static uint32_t sCurrentIteration;
  void SetUp() override { ++sCurrentIteration; }
};
uint32_t TestIterationCounter::sCurrentIteration = (std::numeric_limits<uint32_t>::max)();

const std::string kHelpFlag("help");
const std::string kLogLevelFlag("log_level");
const std::string kLogStackFlag("log_stack");
const std::string kXmlOutputFlag("xml_output");
const std::string kOutputPathFlag("output_path");
const std::string kResourceDirFlag("resource_dir");

}  // namespace

const std::string TestEnv::kTestResults("test_detail.xml");
std::filesystem::path TestEnv::gExecPath;
std::filesystem::path TestEnv::gExecDir;
std::filesystem::path TestEnv::gExecFile;
