std::filesystem::path TestEnv::gResourceDir;
std::filesystem::path TestEnv::gResDir;
std::filesystem::path TestEnv::gResPath;
std::string TestEnv::gTestName;
int TestEnv::gArgc;
char** TestEnv::gArgv;
decltype(TestEnv::gArgvIresOutput) TestEnv::gArgvIresOutput;

uint32_t TestEnv::iteration() { return TestIterationCounter::sCurrentIteration; }

std::filesystem::path TestEnv::resource(const std::string& name) {
  return gResourceDir / name;
}

bool TestEnv::prepare(const cmdline::parser& parser) {
  if (parser.exist(kHelpFlag)) {
    return true;
  }

  setupDirectories();

  auto logLevelValue =
    parser.get<std::underlying_type_t<sdb::LogLevel>>(kLogLevelFlag);
  sdb::Logger::IRESEARCH.SetLevel(sdb::LogLevel{logLevelValue});

  if (parser.exist(kXmlOutputFlag)) {
    std::unique_ptr<char*[]> newArgv(new char*[2 + gArgc]);
    std::memcpy(newArgv.get(), gArgv, sizeof(char*) * gArgc);

    gArgvIresOutput = "--gtest_output=xml:" + gResPath.string();
    newArgv[gArgc++] = &gArgvIresOutput[0];
    newArgv[gArgc] = nullptr;
    gArgv = newArgv.release();
  }

  return true;
}

void TestEnv::setupDirectories() {
  std::filesystem::path execPath(gArgv[0]);
  auto parts = irs::file_utils::PathParts(execPath.c_str());

  gExecPath = execPath;
  gExecFile = std::filesystem::path{
    irs::basic_string_view<std::filesystem::path::value_type>(parts.basename)};
  gExecDir = std::filesystem::path{
    irs::basic_string_view<std::filesystem::path::value_type>(parts.dirname)};
  gTestName = std::filesystem::path{
    irs::basic_string_view<std::filesystem::path::value_type>(parts.stem)}.string();

  if (gOutDir.empty()) {
    gOutDir = gExecDir;
  }

  std::cout << "launching: " << gExecPath.string() << "\n";
  std::cout << "options:\n";
  std::cout << "\t" << kOutputPathFlag << ": " << gOutDir.string() << "\n";
  std::cout << "\t" << kResourceDirFlag << ": " << gResourceDir.string() << "\n";

  irs::file_utils::EnsureAbsolute(gOutDir);

  (gResDir = gOutDir) /= gTestName;

  // Append timestamp
  {
    std::tm tinfo{};
    if (irs::Localtime(tinfo, std::time(nullptr))) {
      char buffer[21]{};
      strftime(buffer, sizeof buffer, "_%Y_%m_%d_%H_%M_%S", &tinfo);
      gResDir += std::string_view{buffer, sizeof buffer - 1};
    } else {
      gResDir += "_unknown";
    }
  }

  // Append temporary suffix
  {
    char tempSuffix[] = "_XXXXXX";
    gResDir += std::string_view{tempSuffix, sizeof tempSuffix - 1};
  }

  auto templStr = gResDir.string();
  gResDir = mkdtemp(templStr.data());
  (gResPath = gResDir) /= kTestResults;
}

void TestEnv::parseCommandLine(cmdline::parser& cmd) {
  cmd.add(kHelpFlag, '?', "print this message");
  cmd.add(kLogLevelFlag, 0,
          "threshold log level <FATAL|ERROR|WARN|INFO|DEBUG|TRACE>", false,
          std::to_underlying(sdb::LogLevel::FATAL), [](std::string_view s) {
            auto level = sdb::LogLevel::FATAL;
            sdb::log::TranslateLogLevel(s, false, level);
            return std::to_underlying(level);
          });
  cmd.add(kLogStackFlag, 0, "always log stack trace", false, false);
  cmd.add(kXmlOutputFlag, 0, "generate an XML report");
  cmd.add(kOutputPathFlag, 0, "output directory", false, gOutDir.string());
  cmd.add(kResourceDirFlag, 0, "resource directory", false,
          std::filesystem::path(IRS_TEST_RESOURCE_DIR).string());
  cmd.parse(gArgc, gArgv);

  if (cmd.exist(kHelpFlag)) {
    std::cout << cmd.usage() << std::endl;
    return;
  }

  gResourceDir = std::filesystem::path{cmd.get<std::string>(kResourceDirFlag)};
  gOutDir = std::filesystem::path{cmd.get<std::string>(kOutputPathFlag)};
}

int TestEnv::initialize(int argc, char* argv[]) {
  gArgc = argc;
  gArgv = argv;

  cmdline::parser cmd;
  parseCommandLine(cmd);

  if (!prepare(cmd)) {
    return -1;
  }

  ::testing::AddGlobalTestEnvironment(new TestIterationCounter());
  ::testing::InitGoogleTest(&gArgc, gArgv);

  irs::analysis::analyzers::Init();
  irs::formats::Init();
  irs::scorers::Init();
  irs::compression::Init();

  return RUN_ALL_TESTS();
}

void TestBase::SetUp() {
  const auto* info = ::testing::UnitTest::GetInstance()->current_test_info();
  if (!info) {
    throw std::runtime_error("not a test suite");
  }

  _test_case_dir = test_results_dir();
  if (GTEST_FLAG_GET(repeat) < 0 || 1 < GTEST_FLAG_GET(repeat)) {
    _test_case_dir /= absl::StrCat("iteration ", iteration());
  }
  _test_case_dir /= info->test_case_name();
  (_test_dir = _test_case_dir) /= info->name();
  std::filesystem::create_directories(_test_dir);
}

void TestBase::TearDown() {
  if (!_test_dir.empty()) {
    auto path = _test_dir;
    if (!HasFailure()) {
      std::filesystem::remove_all(path);
    } else if (std::filesystem::is_empty(path)) {
      std::filesystem::remove(path);
    }
  }
}

int main(int argc, char* argv[]) {
  sdb::log::Initialize();
  const int exitCode = TestEnv::initialize(argc, argv);

  SDB_INFO("xxxxx", sdb::Logger::IRESEARCH,
           "Path to test result directory: ",
           TestEnv::test_results_dir().string());

  size_t totalEntries = 0;
  std::vector<std::filesystem::path> emptyDirs;

  for (const auto& entry : std::filesystem::recursive_directory_iterator{
         TestEnv::test_results_dir()}) {
    ++totalEntries;
    if (std::filesystem::is_empty(entry.path())) {
      emptyDirs.emplace_back(entry.path());
    }
  }

  if (totalEntries == 0) {
    std::filesystem::remove(TestEnv::test_results_dir());
  } else {
    for (auto& dirPath : emptyDirs) {
      do {
        std::filesystem::remove(dirPath);
        dirPath = dirPath.parent_path();
      } while (!dirPath.empty() && std::filesystem::is_empty(dirPath));
    }
  }

  return exitCode;
}

