UUnrealRobotJoint::UUnrealRobotJoint(const FObjectInitializer& ObjectInitializer)
    : UPhysicsConstraintComponent(ObjectInitializer) {
  bAutoActivate = true;
  PrimaryComponentTick.bCanEverTick = true;
  PrimaryComponentTick.TickGroup = TG_PrePhysics;
}

void UUnrealRobotJoint::Initialize(const projectairsim::Joint& joint_desc) {
  InitializePoseFromTransform(joint_desc.GetOrigin());
  SetupConstraintFromJoint(joint_desc);
  RegisterComponent();
  joint = joint_desc;
}

void UUnrealRobotJoint::InitializePoseFromTransform(const projectairsim::Transform& pose) {
  auto const& translation = pose.translation_;
  FVector location{
      translation.x() * 100.0f,
      translation.y() * 100.0f,
     -translation.z() * 100.0f  // NED m → NEU cm
  };
  SetRelativeLocation(location);

  auto rpy = projectairsim::TransformUtils::ToRPY(pose.rotation_);
  FRotator rotation{
      projectairsim::TransformUtils::ToDegrees<float>(rpy.y()),  // Pitch
      projectairsim::TransformUtils::ToDegrees<float>(rpy.z()),  // Yaw
      projectairsim::TransformUtils::ToDegrees<float>(rpy.x())   // Roll
  };
  SetRelativeRotation(rotation);
}

void UUnrealRobotJoint::SetupConstraintFromJoint(const projectairsim::Joint& joint_desc) {
  FConstraintInstance constraint;
  auto axis_vec = joint_desc.GetAxis();
  FVector const axis{axis_vec.x(), axis_vec.y(), axis_vec.z()};

  // Disable soft constraints for all limit types
  constraint.ProfileInstance.LinearLimit.bSoftConstraint = false;
  constraint.ProfileInstance.TwistLimit.bSoftConstraint = false;
  constraint.ProfileInstance.ConeLimit.bSoftConstraint = false;
  constraint.AngularRotationOffset = FRotator::ZeroRotator;

  // Helper lambda to set angular limits based on joint type and axis
  auto configureAngularLimits = [&](EAngularConstraintMotion swing1, float swing1Angle,
                                    EAngularConstraintMotion swing2, float swing2Angle,
                                    EAngularConstraintMotion twist, float twistAngle) {
    constraint.SetAngularSwing1Limit(swing1, swing1Angle);
    constraint.SetAngularSwing2Limit(swing2, swing2Angle);
    constraint.SetAngularTwistLimit(twist, twistAngle);
  };

  // Determine axis direction and apply appropriate configuration
  if (axis.IsNearlyEqual(FVector::ForwardVector)) {
    switch (joint_desc.GetJointType()) {
      case projectairsim::JointType::kFixed:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kRevolute:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Limited,
                               projectairsim::TransformUtils::ToDegrees<float>(joint_desc.GetLimit()));
        break;
      case projectairsim::JointType::kContinuous:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Free, 0.0f);
        break;
    }
  } else if (axis.IsNearlyEqual(FVector::RightVector)) {
    switch (joint_desc.GetJointType()) {
      case projectairsim::JointType::kFixed:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kRevolute:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Limited,
                               projectairsim::TransformUtils::ToDegrees<float>(joint_desc.GetLimit()),
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kContinuous:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Free, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
    }
  } else if (axis.IsNearlyEqual(FVector::UpVector)) {
    switch (joint_desc.GetJointType()) {
      case projectairsim::JointType::kFixed:
        configureAngularLimits(EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kRevolute:
        configureAngularLimits(EAngularConstraintMotion::ACM_Limited,
                               projectairsim::TransformUtils::ToDegrees<float>(joint_desc.GetLimit()),
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
      case projectairsim::JointType::kContinuous:
        configureAngularLimits(EAngularConstraintMotion::ACM_Free, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f,
                               EAngularConstraintMotion::ACM_Locked, 0.0f);
        break;
    }
  }

  // Drive mode settings for revolute & continuous joints
  auto const jtype = joint_desc.GetJointType();
  if (jtype == projectairsim::JointType::kContinuous || jtype == projectairsim::JointType::kRevolute) {
    constraint.SetAngularDriveMode(EAngularDriveMode::TwistAndSwing);
    constraint.SetOrientationDriveSLERP(false);
    constraint.SetOrientationDriveTwistAndSwing(false, true);
    constraint.SetAngularVelocityDriveSLERP(false);
    constraint.SetAngularVelocityDriveTwistAndSwing(false, true);
  }

  constraint.ProfileInstance.bParentDominates = joint_desc.GetParentDominates();
  constraint.ProfileInstance.bDisableCollision = true;
  constraint.SetAngularDriveParams(joint_desc.GetSpringConstant(),
                                   joint_desc.GetDampingConstant(),
                                   joint_desc.GetMaxForce());

  ConstraintInstance = constraint;
}

void UUnrealRobotJoint::BeginPlay() {
  Super::BeginPlay();
  joint.SetCallbackJointStateUpdated(
      [this](auto const& msg) { this->OnJointStateUpdate(msg); });
  joint.BeginUpdate();
}

void UUnrealRobotJoint::TickComponent(float DeltaTime, ELevelTick TickType,
                                      FActorComponentTickFunction* ThisTickFunction) {
  Super::TickComponent(DeltaTime, TickType, ThisTickFunction);

  auto const jtype = joint.GetJointType();
  auto const axis = FVector(joint.GetAxis().x(), joint.GetAxis().y(), joint.GetAxis().z());

  if (jtype == projectairsim::JointType::kRevolute) {
    ApplyRevoluteTarget(axis);
  } else if (jtype == projectairsim::JointType::kContinuous) {
    ApplyContinuousTarget(axis);
  }

  PublishJointState();
}

void UUnrealRobotJoint::ApplyRevoluteTarget(FVector const& axis) {
  float angle_deg = projectairsim::TransformUtils::ToDegrees<float>(target_position.load());
  if (axis.IsNearlyEqual(FVector::ForwardVector)) {
    SetAngularOrientationTarget({0, 0, angle_deg});
  } else if (axis.IsNearlyEqual(FVector::RightVector)) {
    SetAngularOrientationTarget({angle_deg, 0, 0});
  } else if (axis.IsNearlyEqual(FVector::UpVector)) {
    SetAngularOrientationTarget({0, angle_deg, 0});
  }
}

void UUnrealRobotJoint::ApplyContinuousTarget(FVector const& axis) {
  float vel_deg = projectairsim::TransformUtils::ToDegrees<float>(target_velocity.load());
  if (axis.IsNearlyEqual(FVector::ForwardVector)) {
    SetAngularVelocityTarget({vel_deg, 0, 0});
  } else if (axis.IsNearlyEqual(FVector::RightVector)) {
    SetAngularVelocityTarget({0, vel_deg, 0});
  } else if (axis.IsNearlyEqual(FVector::UpVector)) {
    SetAngularVelocityTarget({0, 0, vel_deg});
  }
}

void UUnrealRobotJoint::EndPlay(EEndPlayReason::Type EndPlayReason) {
  joint.EndUpdate();
  Super::EndPlay(EndPlayReason);
}

void UUnrealRobotJoint::PublishJointState() {
  float pos = 0.0f;
  float vel = 0.0f;

  auto const jtype = joint.GetJointType();
  if (jtype == projectairsim::JointType::kFixed) return;

  if (jtype == projectairsim::JointType::kRevolute) {
    FVector const axis(joint.GetAxis().x(), joint.GetAxis().y(), joint.GetAxis().z());
    if (axis.IsNearlyEqual(FVector::ForwardVector))
      pos = projectairsim::TransformUtils::ToRadians(GetCurrentTwist());
    else if (axis.IsNearlyEqual(FVector::RightVector))
      pos = projectairsim::TransformUtils::ToRadians(GetCurrentSwing2());
    else if (axis.IsNearlyEqual(FVector::UpVector))
      pos = projectairsim::TransformUtils::ToRadians(GetCurrentSwing1());
  }

  if (jtype == projectairsim::JointType::kContinuous) {
    FVector const axis(joint.GetAxis().x(), joint.GetAxis().y(), joint.GetAxis().z());
    FVector const angularVel = ConstraintInstance.ProfileInstance.AngularDrive.AngularVelocityTarget;
    if (axis.IsNearlyEqual(FVector::ForwardVector))
      vel = projectairsim::TransformUtils::ToRadians(angularVel.X);
    else if (axis.IsNearlyEqual(FVector::RightVector))
      vel = projectairsim::TransformUtils::ToRadians(angularVel.Y);
    else if (axis.IsNearlyEqual(FVector::UpVector))
      vel = projectairsim::TransformUtils::ToRadians(angularVel.Z);
  }

  projectairsim::JointStateMessage state(pos, vel, 0.0f);
  joint.PublishJointState(state);
}

void UUnrealRobotJoint::OnJointStateUpdate(projectairsim::JointStateMessage const& message) {
  switch (joint.GetJointType()) {
    case projectairsim::JointType::kRevolute:
      target_position.store(message.GetPosition());
      break;
    case projectairsim::JointType::kContinuous:
      target_velocity.store(message.GetVelocity());
      break;
    default:
      break;
  }
}

