LRESULT CALLBACK MainWndProc(HWND hwnd, UINT message, WPARAM wParam, LPARAM lParam)
{
	switch (message)
	{
	case WM_CLOSE:
		DestroyWindow(hwnd);
		return 0;
	case WM_DESTROY:
		PostQuitMessage(0);
		return 0;
	default:
		return DefWindowProc(hwnd, message, wParam, lParam);
	}
}

int WINAPI wWinMain(HINSTANCE hInstance, HINSTANCE /*hPrevInstance*/, LPWSTR /*lpCmdLine*/, int nCmdShow)
{
	int argumentCount;
	LPWSTR* argumentList = CommandLineToArgvW(GetCommandLineW(), &argumentCount);
	if (!argumentList) {
		MessageBox(nullptr,
			TEXT("An error occurred while reading command line arguments."),
			TEXT("Error!"),
			MB_ICONERROR | MB_OK);
		return EXIT_FAILURE;
	}

	auto cleanup_argument_memory = [&argumentList]() {
		if (argumentList) {
			LocalFree(argumentList);
			argumentList = nullptr;
		}
	};

	if (argumentCount < 2) {
		MessageBox(nullptr,
			TEXT("No model file specified. The program will now close."),
			TEXT("Error!"),
			MB_ICONERROR | MB_OK);
		cleanup_argument_memory();
		return EXIT_FAILURE;
	}

	std::wstring modelFilename(argumentList[1]);
	char* utf8Buffer = new char[modelFilename.size() + 1];
	memset(utf8Buffer, '\0', modelFilename.size() + 1);
	utf8::utf16to8(modelFilename.c_str(), modelFilename.c_str() + modelFilename.size(), utf8Buffer);
	modelFilePath = utf8Buffer;
	delete[] utf8Buffer;
	cleanup_argument_memory();

	WNDCLASSEX windowClass;
	MSG message;
	windowClass.cbSize = sizeof(WNDCLASSEX);
	windowClass.style = CS_HREDRAW | CS_VREDRAW;
	windowClass.lpfnWndProc = MainWndProc;
	windowClass.cbClsExtra = 0;
	windowClass.cbWndExtra = 0;
	windowClass.hInstance = hInstance;
	windowClass.hIcon = LoadIcon(nullptr, IDI_APPLICATION);
	windowClass.hCursor = LoadCursor(nullptr, IDC_ARROW);
	windowClass.hbrBackground = (HBRUSH)(COLOR_WINDOW + 1);
	windowClass.lpszMenuName = nullptr;
	windowClass.lpszClassName = windowClassName;
	windowClass.hIconSm = LoadIcon(nullptr, IDI_APPLICATION);

	if (!RegisterClassEx(&windowClass)) {
		MessageBox(nullptr, "Window Registration Failed!", "Error!",
			MB_ICONEXCLAMATION | MB_OK);
		return 0;
	}

	RECT windowRect = { 0, 0, WINDOW_WIDTH, WINDOW_HEIGHT };
	AdjustWindowRect(&windowRect, WS_OVERLAPPEDWINDOW, FALSE);

	mainHwnd = CreateWindowEx(
		WS_EX_CLIENTEDGE,
		windowClassName,
		"Simple Textured Directx11 Sample",
		WS_OVERLAPPEDWINDOW,
		CW_USEDEFAULT, CW_USEDEFAULT,
		windowRect.right - windowRect.left,
		windowRect.bottom - windowRect.top,
		nullptr, nullptr, hInstance, nullptr
	);

	if (!mainHwnd) {
		MessageBox(nullptr, "Window Creation Failed!", "Error!",
			MB_ICONEXCLAMATION | MB_OK);
		return 0;
	}

	ShowWindow(mainHwnd, nCmdShow);
	UpdateWindow(mainHwnd);

	clientWidth = windowRect.right - windowRect.left;
	clientHeight = windowRect.bottom - windowRect.top;

	try {
		InitializeDirect3D(hInstance, mainHwnd);

		while (true) {
			if (PeekMessage(&message, nullptr, 0, 0, PM_REMOVE)) {
				TranslateMessage(&message);
				DispatchMessage(&message);
				if (message.message == WM_QUIT)
					break;
			}
			UpdateAndRender();
		}

		CleanupDirect3D();
		return static_cast<int>(message.wParam);
	}
	catch (const std::exception& e) {
		MessageBox(mainHwnd, e.what(), TEXT("Error!"), MB_ICONERROR | MB_OK);
		CleanupDirect3D();
		return EXIT_FAILURE;
	}
	catch (...) {
		MessageBox(mainHwnd, TEXT("Caught an unknown exception."), TEXT("Error!"), MB_ICONERROR | MB_OK);
		CleanupDirect3D();
		return EXIT_FAILURE;
	}
}

void InitializeDirect3D(HINSTANCE /*hInstance*/, HWND hWnd)
{
	HRESULT hr;
	UINT creationFlags = 0;
#ifdef _DEBUG
	creationFlags |= D3D11_CREATE_DEVICE_DEBUG;
#endif

	D3D_DRIVER_TYPE availableDrivers[] = {
		D3D_DRIVER_TYPE_HARDWARE,
		D3D_DRIVER_TYPE_WARP,
		D3D_DRIVER_TYPE_REFERENCE,
	};
	const size_t driverCount = ARRAYSIZE(availableDrivers);

	D3D_FEATURE_LEVEL requestedLevels[] = {
		D3D_FEATURE_LEVEL_11_1,
		D3D_FEATURE_LEVEL_11_0,
		D3D_FEATURE_LEVEL_10_1,
		D3D_FEATURE_LEVEL_10_0,
	};
	const size_t levelCount = ARRAYSIZE(requestedLevels);

	size_t driverIndex = 0;
	while (driverIndex < driverCount) {
		driverType = availableDrivers[driverIndex];
		hr = D3D11CreateDevice(
			nullptr,
			driverType,
			nullptr,
			creationFlags,
			requestedLevels,
			static_cast<UINT>(levelCount),
			D3D11_SDK_VERSION,
			&device,
			&featureLevel,
			&context
		);

		if (hr == E_INVALIDARG) {
			hr = D3D11CreateDevice(
				nullptr,
				driverType,
				nullptr,
				creationFlags,
				&requestedLevels[1],
				static_cast<UINT>(levelCount - 1),
				D3D11_SDK_VERSION,
				&device,
				&featureLevel,
				&context
			);
		}

		if (SUCCEEDED(hr))
			break;

		driverIndex++;
	}

	if (FAILED(hr))
		ReportError("DirectX Device Creation Failed!");

#if _DEBUG
	hr = device->QueryInterface(IID_PPV_ARGS(&debugInterface));
	if (FAILED(hr))
		OutputDebugString(TEXT("Failed to retrieve DirectX 11 debug interface.\n"));
#endif

	UINT msaaQualityLevel = 0;
	device->CheckMultisampleQualityLevels(
		DXGI_FORMAT_R8G8B8A8_UNORM, 4, &msaaQualityLevel);

	IDXGIFactory1* dxgiFactory = nullptr;
	{
		IDXGIDevice* dxgiDevice = nullptr;
		hr = device->QueryInterface(__uuidof(IDXGIDevice), reinterpret_cast<void**>(&dxgiDevice));
		if (SUCCEEDED(hr)) {
			IDXGIAdapter* adapter = nullptr;
			hr = dxgiDevice->GetAdapter(&adapter);
			if (SUCCEEDED(hr)) {
				hr = adapter->GetParent(__uuidof(IDXGIFactory1), reinterpret_cast<void**>(&dxgiFactory));
				adapter->Release();
			}
			dxgiDevice->Release();
		}
	}

	if (FAILED(hr))
		ReportError("DXGI Factory couldn't be obtained!");

	IDXGIFactory2* dxgiFactory2 = nullptr;
	hr = dxgiFactory->QueryInterface(__uuidof(IDXGIFactory2), reinterpret_cast<void**>(&dxgiFactory2));

	if (dxgiFactory2) {
		hr = device->QueryInterface(__uuidof(ID3D11Device1), reinterpret_cast<void**>(&device1));
		if (SUCCEEDED(hr)) {
			(void)context->QueryInterface(__uuidof(ID3D11DeviceContext1), reinterpret_cast<void**>(&context1));
		}

		DXGI_SWAP_CHAIN_DESC1 sd = {};
		sd.Width = WINDOW_WIDTH;
		sd.Height = WINDOW_HEIGHT;
		sd.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
		sd.SampleDesc.Count = 4;
		sd.SampleDesc.Quality = msaaQualityLevel - 1;
		sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
		sd.BufferCount = 1;

		hr = dxgiFactory2->CreateSwapChainForHwnd(device, hWnd, &sd, nullptr, nullptr, &swapChain1);
		if (SUCCEEDED(hr)) {
			hr = swapChain1->QueryInterface(__uuidof(IDXGISwapChain), reinterpret_cast<void**>(&swapChain));
		}
		dxgiFactory2->Release();
	}
	else {
		DXGI_SWAP_CHAIN_DESC sd = {};
		sd.BufferCount = 1;
		sd.BufferDesc.Width = WINDOW_WIDTH;
		sd.BufferDesc.Height = WINDOW_HEIGHT;
		sd.BufferDesc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
		sd.BufferDesc.RefreshRate.Numerator = 60;
		sd.BufferDesc.RefreshRate.Denominator = 1;
		sd.BufferUsage = DXGI_USAGE_RENDER_TARGET_OUTPUT;
		sd.OutputWindow = hWnd;
		sd.SampleDesc.Count = 1;
		sd.SampleDesc.Quality = msaaQualityLevel - 1;
		sd.Windowed = TRUE;

		hr = dxgiFactory->CreateSwapChain(device, &sd, &swapChain);
	}

	dxgiFactory->MakeWindowAssociation(mainHwnd, DXGI_MWA_NO_ALT_ENTER);
	dxgiFactory->Release();

	if (FAILED(hr))
		ReportError("Swapchain Creation Failed!");

	ID3D11Texture2D* backBufferTexture = nullptr;
	swapChain->GetBuffer(0, __uuidof(ID3D11Texture2D), reinterpret_cast<void**>(&backBufferTexture));
	device->CreateRenderTargetView(backBufferTexture, nullptr, &renderTargetView);
	backBufferTexture->Release();

	D3D11_TEXTURE2D_DESC depthStencilDesc = {};
	depthStencilDesc.Width = WINDOW_WIDTH;
	depthStencilDesc.Height = WINDOW_HEIGHT;
	depthStencilDesc.MipLevels = 1;
	depthStencilDesc.ArraySize = 1;
	depthStencilDesc.Format = DXGI_FORMAT_D24_UNORM_S8_UINT;
	depthStencilDesc.SampleDesc.Count = 4;
	depthStencilDesc.SampleDesc.Quality = msaaQualityLevel - 1;
	depthStencilDesc.Usage = D3D11_USAGE_DEFAULT;
	depthStencilDesc.BindFlags = D3D11_BIND_DEPTH_STENCIL;
	depthStencilDesc.CPUAccessFlags = 0;
	depthStencilDesc.MiscFlags = 0;

	hr = device->CreateTexture2D(&depthStencilDesc, nullptr, &depthStencilBuffer);
	if (FAILED(hr))
		ReportError("Depth Stencil Texture couldn't be created!");

	D3D11_DEPTH_STENCIL_VIEW_DESC dsvDesc = {};
	dsvDesc.Format = depthStencilDesc.Format;
	dsvDesc.ViewDimension = D3D11_DSV_DIMENSION_TEXTURE2D;
	dsvDesc.Texture2D.MipSlice = 0;

	hr = device->CreateDepthStencilView(depthStencilBuffer, &dsvDesc, &depthStencilView);
	if (FAILED(hr))
		ReportError("Depth Stencil View couldn't be created!");

	context->OMSetRenderTargets(1, &renderTargetView, depthStencilView);

	D3D11_RASTERIZER_DESC rasterizerDesc = {};
	rasterizerDesc.AntialiasedLineEnable = false;
	rasterizerDesc.CullMode = D3D11_CULL_BACK;
	rasterizerDesc.DepthBias = 0;
	rasterizerDesc.DepthBiasClamp = 0.0f;
	rasterizerDesc.DepthClipEnable = true;
	rasterizerDesc.FillMode = D3D11_FILL_SOLID;
	rasterizerDesc.FrontCounterClockwise = false;
	rasterizerDesc.MultisampleEnable = false;
	rasterizerDesc.ScissorEnable = false;
	rasterizerDesc.SlopeScaledDepthBias = 0.0f;

	device->CreateRasterizerState(&rasterizerDesc, &rasterizerState);
	context->RSSetState(rasterizerState);

	D3D11_VIEWPORT viewport = {};
	viewport.TopLeftX = 0.0f;
	viewport.TopLeftY = 0.0f;
	viewport.MinDepth = 0.0f;
	viewport.MaxDepth = 1.0f;
	viewport.Width = static_cast<float>(WINDOW_WIDTH);
	viewport.Height = static_cast<float>(WINDOW_HEIGHT);
	context->RSSetViewports(1, &viewport);

	SetupPipeline();
	SetupSceneGeometry();
}

void CleanupDirect3D()
{
	if (swapChain)
		swapChain->SetFullscreenState(FALSE, nullptr);

	if (sceneModel) {
		sceneModel->Close();
		delete sceneModel;
		sceneModel = nullptr;
	}

	SafeRelease(textureSampler);
	SafeRelease(constantBuffer);
	SafeRelease(inputLayout);
	SafeRelease(vertexShader);
	SafeRelease(pixelShader);
	SafeRelease(rasterizerState);
	SafeRelease(depthStencilView);
	SafeRelease(depthStencilBuffer);
	SafeRelease(renderTargetView);
	SafeRelease(swapChain);
	SafeRelease(swapChain1);
	SafeRelease(context1);
	SafeRelease(device1);
	SafeRelease(context);

#if _DEBUG
	if (debugInterface) {
		OutputDebugString(TEXT("Dumping DirectX 11 live objects.\n"));
		debugInterface->ReportLiveDeviceObjects(D3D11_RLDO_DETAIL);
		SafeRelease(debugInterface);
	} else {
		OutputDebugString(TEXT("Unable to dump live objects: no DirectX 11 debug interface available.\n"));
	}
#endif

	SafeRelease(device);
}

void UpdateAndRender()
{
	static float timeElapsed = 0.0f;
	static ULONGLONG startTime = GetTickCount64();
	ULONGLONG currentTime = GetTickCount64();
	if (startTime == 0) startTime = currentTime;
	timeElapsed = static_cast<float>(currentTime - startTime) / 1000.0f;

	float clearColors[4] = { 0.0f, 0.2f, 0.4f, 1.0f };
	context->ClearRenderTargetView(renderTargetView, clearColors);
	context->ClearDepthStencilView(depthStencilView, D3D11_CLEAR_DEPTH | D3D11_CLEAR_STENCIL, 1.0f, 0);

	context->IASetPrimitiveTopology(D3D11_PRIMITIVE_TOPOLOGY_TRIANGLELIST);

	worldTransform = XMMatrixRotationY(-timeElapsed);

	PerFrameConstants frameData = {};
	frameData.worldMatrix = XMMatrixTranspose(worldTransform);
	frameData.viewMatrix = XMMatrixTranspose(viewTransform);
	frameData.projMatrix = XMMatrixTranspose(projectionTransform);

	context->UpdateSubresource(constantBuffer, 0, nullptr, &frameData, 0, 0);

	context->VSSetShader(vertexShader, nullptr, 0);
	context->VSSetConstantBuffers(0, 1, &constantBuffer);
	context->PSSetShader(pixelShader, nullptr, 0);
	context->PSSetSamplers(0, 1, &textureSampler);

	sceneModel->Draw(context);

	swapChain->Present(0, 0);
}

void SetupPipeline()
{
	ID3DBlob* vertexShaderBlob = nullptr;
	ID3DBlob* pixelShaderBlob = nullptr;

	if (FAILED(CompileShaderFromDisk(SHADER_PATH VERTEX_SHADER_FILE, nullptr, "main", "vs_4_0", &vertexShaderBlob)))
		ReportError("Failed to compile vertex shader from file");

	if (FAILED(CompileShaderFromDisk(SHADER_PATH PIXEL_SHADER_FILE, nullptr, "main", "ps_4_0", &pixelShaderBlob)))
		ReportError("Failed to compile pixel shader from file");

	device->CreateVertexShader(vertexShaderBlob->GetBufferPointer(), vertexShaderBlob->GetBufferSize(), nullptr, &vertexShader);
	device->CreatePixelShader(pixelShaderBlob->GetBufferPointer(), pixelShaderBlob->GetBufferSize(), nullptr, &pixelShader);

	D3D11_INPUT_ELEMENT_DESC layoutDesc[] = {
		{ "POSITION", 0, DXGI_FORMAT_R32G32B32_FLOAT, 0, 0, D3D11_INPUT_PER_VERTEX_DATA, 0 },
		{ "TEXCOORD", 0, DXGI_FORMAT_R32G32_FLOAT, 0, D3D11_APPEND_ALIGNED_ELEMENT, D3D11_INPUT_PER_VERTEX_DATA, 0 }
	};

	device->CreateInputLayout(layoutDesc, ARRAYSIZE(layoutDesc),
		vertexShaderBlob->GetBufferPointer(), vertexShaderBlob->GetBufferSize(), &inputLayout);
	context->IASetInputLayout(inputLayout);

	SafeRelease(vertexShaderBlob);
	SafeRelease(pixelShaderBlob);
}

void SetupSceneGeometry()
{
	HRESULT hr;

	projectionTransform = XMMatrixPerspectiveFovLH(XM_PIDIV4, static_cast<float>(WINDOW_WIDTH) / static_cast<float>(WINDOW_HEIGHT), 0.01f, 1000.0f);

	D3D11_BUFFER_DESC cbDesc = {};
	cbDesc.Usage = D3D11_USAGE_DEFAULT;
	cbDesc.ByteWidth = sizeof(PerFrameConstants);
	cbDesc.BindFlags = D3D11_BIND_CONSTANT_BUFFER;
	cbDesc.CPUAccessFlags = 0;

	hr = device->CreateBuffer(&cbDesc, nullptr, &constantBuffer);
	if (FAILED(hr))
		ReportError("Constant buffer couldn't be created");

	D3D11_SAMPLER_DESC samplerDesc = {};
	samplerDesc.Filter = D3D11_FILTER_MIN_MAG_MIP_LINEAR;
	samplerDesc.AddressU = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.AddressV = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.AddressW = D3D11_TEXTURE_ADDRESS_WRAP;
	samplerDesc.ComparisonFunc = D3D11_COMPARISON_NEVER;
	samplerDesc.MinLOD = 0;
	samplerDesc.MaxLOD = D3D11_FLOAT32_MAX;

	hr = device->CreateSamplerState(&samplerDesc, &textureSampler);
	if (FAILED(hr))
		ReportError("Texture sampler state couldn't be created");

	XMVECTOR cameraPosition = XMVectorSet(0.0f, 5.0f, -300.0f, 0.0f);
	XMVECTOR lookAtPoint = XMVectorSet(0.0f, 100.0f, 0.0f, 0.0f);
	XMVECTOR upDirection = XMVectorSet(0.0f, 1.0f, 0.0f, 0.0f);
	viewTransform = XMMatrixLookAtLH(cameraPosition, lookAtPoint, upDirection);

	sceneModel = new ModelLoader;
	if (!sceneModel->Load(mainHwnd, device, context, modelFilePath))
		ReportError("Model couldn't be loaded");
}

HRESULT CompileShaderFromDisk(LPCWSTR pFileName, const D3D_SHADER_MACRO* pDefines, LPCSTR pEntryPoint, LPCSTR pShaderModel, ID3DBlob** ppBytecodeBlob)
{
	UINT compileFlags = D3DCOMPILE_ENABLE_STRICTNESS | D3DCOMPILE_PACK_MATRIX_COLUMN_MAJOR;
#ifdef _DEBUG
	compileFlags |= D3DCOMPILE_DEBUG;
#endif

	ID3DBlob* errorBlob = nullptr;
	HRESULT result = D3DCompileFromFile(pFileName, pDefines, D3D_COMPILE_STANDARD_FILE_INCLUDE, pEntryPoint, pShaderModel, compileFlags, 0, ppBytecodeBlob, &errorBlob);

	if (FAILED(result)) {
		if (errorBlob != nullptr)
			OutputDebugStringA((LPCSTR)errorBlob->GetBufferPointer());
	}

	if (errorBlob != nullptr)
		errorBlob->Release();

	return result;
}

void ReportError(LPCSTR errorMessage)
{
	throw std::runtime_error(errorMessage);
}

