// Alternative implementation of memory statistics dump using different approach
namespace irs::memory {

void DumpMemStatsTrace() noexcept {
#ifndef _MSC_VER
  // Skip on Apple platforms and non-glibc systems
#if !defined(__APPLE__) && defined(__GLIBC__)
  // Print memory usage information in a custom format
  constexpr const char* kHeader = "Memory Statistics Report:\n";
  fprintf(stderr, "%s", kHeader);

  // Use mallinfo to gather heap statistics
  auto mi = mallinfo();

  // Output formatted statistics with descriptive labels
  fprintf(stderr, "Non-mmapped memory area size:       %u bytes\n", 
          static_cast<unsigned>(mi.arena));
  fprintf(stderr, "Free memory chunks:                 %u\n", 
          static_cast<unsigned>(mi.ordblks));
  fprintf(stderr, "Fastbin free blocks:                %u\n", 
          static_cast<unsigned>(mi.smblks));
  fprintf(stderr, "Mapped regions count:               %u\n", 
          static_cast<unsigned>(mi.hblks));
  fprintf(stderr, "Bytes in mapped regions:            %u bytes\n", 
          static_cast<unsigned>(mi.hblkhd));
  fprintf(stderr, "Maximum allocated space:            %u bytes\n", 
          static_cast<unsigned>(mi.usmblks));
  fprintf(stderr, "Free bytes in fastbins:             %u bytes\n", 
          static_cast<unsigned>(mi.fsmblks));
  fprintf(stderr, "Total allocated space:              %u bytes\n", 
          static_cast<unsigned>(mi.uordblks));
  fprintf(stderr, "Total free space available:         %u bytes\n", 
          static_cast<unsigned>(mi.fordblks));
  fprintf(stderr, "Topmost releasable block size:      %u bytes\n", 
          static_cast<unsigned>(mi.keepcost));

  // Display additional malloc statistics
  malloc_stats();
#endif

  // Print stack trace if enabled
#ifndef DISABLE_EXECINFO
  void* call_stack[128];
  int frame_count = backtrace(call_stack, std::size(call_stack));

  fprintf(stderr, "\nStack Trace:\n");
  char** symbols = backtrace_symbols(call_stack, frame_count);
  if (symbols) {
    for (int i = 0; i < frame_count; ++i) {
      fprintf(stderr, "[%d] %s\n", i, symbols[i]);
    }
    free(symbols);
  }
#endif
#endif
}

