// Type alias for MiniDumpWriteDump function pointer
using MiniDumpWriter = BOOL(WINAPI*)(HANDLE, DWORD, HANDLE, MINIDUMP_TYPE,
                                     const MINIDUMP_EXCEPTION_INFORMATION*,
                                     const MINIDUMP_USER_STREAM_INFORMATION*,
                                     const MINIDUMP_CALLBACK_INFORMATION*);

static dynutils::lib_obj* s_dbghelpLib = nullptr;
static MiniDumpWriter s_writeDumpFunc = nullptr;

// Shared buffers for user data and dump filename
static char s_userData[1025] = {};
static wchar_t s_dumpPath[257] = {};

// Synchronization primitives
static volatile LONG s_dumpActive = 0;
static HANDLE s_dumpDoneEvent = nullptr;

// Global exception context storage
static CONTEXT s_savedContext{};
static EXCEPTION_RECORD s_savedRecord{};

// Helper: ensure only one thread writes the dump
inline bool try_acquire_dump_lock() {
    return InterlockedCompareExchange(&s_dumpActive, 1, 0) == 0 ||
           (s_dumpDoneEvent && WAIT_OBJECT_0 == WaitForSingleObject(s_dumpDoneEvent, INFINITE));
}

// Generate unique crash dump filename using timestamp + PID
void generate_dump_filename(wchar_t* buffer, size_t bufferSize) {
    SYSTEMTIME localTime{};
    GetLocalTime(&localTime);
    const DWORD processId = GetCurrentProcessId();

    swprintf_s(buffer, bufferSize,
               L"crash_%04hu-%02hu-%02hu_%02hu-%02hu-%02hu_pid%lu.dmp",
               localTime.wYear, localTime.wMonth, localTime.wDay,
               localTime.wHour, localTime.wMinute, localTime.wSecond,
               processId);
}

// Core dump writing logic
LONG write_dump(EXCEPTION_POINTERS* pExceptionInfo) {
    // Prepare filename
    generate_dump_filename(s_dumpPath, std::size(s_dumpPath));

    // Open file for writing
    HANDLE hFile = CreateFileW(s_dumpPath, GENERIC_WRITE, FILE_SHARE_READ,
                               nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (hFile == INVALID_HANDLE_VALUE) {
        fflush(stdout);
        fflush(stderr);
        if (s_dumpDoneEvent) SetEvent(s_dumpDoneEvent);
        return EXCEPTION_EXECUTE_HANDLER;
    }

    // Setup exception info structure
    MINIDUMP_EXCEPTION_INFORMATION exInfo{
        .ThreadId = GetCurrentThreadId(),
        .ExceptionPointers = pExceptionInfo,
        .ClientPointers = FALSE
    };

    // Dump flags
    constexpr MINIDUMP_TYPE dumpFlags =
        static_cast<MINIDUMP_TYPE>(MiniDumpWithDataSegs |
                                   MiniDumpWithHandleData |
                                   MiniDumpWithThreadInfo);

    // Optional user stream
    MINIDUMP_USER_STREAM userStream{};
    MINIDUMP_USER_STREAM_INFORMATION userStreamInfo{};
    if (s_userData[0] != '\0') {
        userStream.Type = 0x4D430000; // "MC"
        userStream.BufferSize = strlen(s_userData);
        userStream.Buffer = s_userData;
        userStreamInfo.UserStreamCount = 1;
        userStreamInfo.UserStreamArray = &userStream;
    } else {
        userStreamInfo.UserStreamCount = 0;
        userStreamInfo.UserStreamArray = nullptr;
    }

    // Write the dump
    BOOL result = s_writeDumpFunc(GetCurrentProcess(), GetCurrentProcessId(),
                                  hFile, dumpFlags, &exInfo, &userStreamInfo, nullptr);
    (void)result;

    CloseHandle(hFile);

    fflush(stdout);
    fflush(stderr);

    if (s_dumpDoneEvent) {
        SetEvent(s_dumpDoneEvent);
    }

    return EXCEPTION_EXECUTE_HANDLER;
}

// Unhandled exception filter callback
LONG WINAPI unhandled_exception_filter(EXCEPTION_POINTERS* pExPtrs) {
    if (!try_acquire_dump_lock()) {
        return EXCEPTION_EXECUTE_HANDLER;
    }
    return write_dump(pExPtrs);
}

// Signal handler for SIGABRT and similar
void signal_abort_handler(int /*sig*/) {
    if (!try_acquire_dump_lock()) {
        _exit(3);
    }

    // Capture current context manually
    RtlCaptureContext(&s_savedContext);
    ZeroMemory(&s_savedRecord, sizeof(s_savedRecord));
    s_savedRecord.ExceptionCode = EXCEPTION_BREAKPOINT;
    s_savedRecord.ExceptionAddress = RET_ADDR();
    s_savedRecord.ExceptionFlags = 0;

    EXCEPTION_POINTERS exPtrs{
        .ExceptionRecord = &s_savedRecord,
        .ContextRecord = &s_savedContext
    };

    write_dump(&exPtrs);
    _exit(3);
}

// CRT terminate handler
void crt_terminate() {
    signal_abort_handler(SIGABRT);
}

// CRT pure virtual call handler
void crt_purecall() {
    if (!try_acquire_dump_lock()) {
        _exit(3);
    }

    RtlCaptureContext(&s_savedContext);
    ZeroMemory(&s_savedRecord, sizeof(s_savedRecord));
    s_savedRecord.ExceptionCode = STATUS_NONCONTINUABLE_EXCEPTION;
    s_savedRecord.ExceptionAddress = RET_ADDR();

    EXCEPTION_POINTERS exPtrs{
        .ExceptionRecord = &s_savedRecord,
        .ContextRecord = &s_savedContext
    };

    write_dump(&exPtrs);
    _exit(3);
}

// CRT invalid parameter handler
void crt_invalid_param(const wchar_t* expr, const wchar_t* func, const wchar_t* file,
                       unsigned int line, uintptr_t /*reserved*/) {
    if (!try_acquire_dump_lock()) {
        _exit(3);
    }

    RtlCaptureContext(&s_savedContext);
    ZeroMemory(&s_savedRecord, sizeof(s_savedRecord));
    s_savedRecord.ExceptionCode = STATUS_INVALID_PARAMETER;
    s_savedRecord.ExceptionAddress = RET_ADDR();

    // Build diagnostic message
    UString msg{US_("Invalid parameter detected:\n")};
    if (expr) {
        msg += US_("  Expression: ");
        msg += expr;
        msg += u'\n';
    }
    if (func) {
        msg += US_("  Function: ");
        msg += func;
        msg += u'\n';
    }
    if (file) {
        wchar_t buf[16]{};
        swprintf_s(buf, L"%u", line);
        msg += US_("  File: ");
        msg += file;
        msg += u':';
        msg += buf;
        msg += u'\n';
    }

    // Copy to global buffer
    auto utf8 = msg.toUtf8();
    strncpy_s(s_userData, std::size(s_userData), utf8.c_str(), std::size(s_userData) - 1);

    EXCEPTION_POINTERS exPtrs{
        .ExceptionRecord = &s_savedRecord,
        .ContextRecord = &s_savedContext
    };

    write_dump(&exPtrs);
    _exit(3);
}

} // anonymous namespace

void init() {
    // Load dbghelp.dll and resolve MiniDumpWriteDump
    s_dbghelpLib = dynutils::load_lib_system("dbghelp.dll");
    if (s_dbghelpLib) {
        s_writeDumpFunc = dynutils::load_func<MiniDumpWriter>(
            s_dbghelpLib, "MiniDumpWriteDump");
    }

    if (!s_writeDumpFunc || !s_dbghelpLib) {
        debugLog("WARNING: crash dumps unavailable — failed to load MiniDumpWriteDump: {}",
                 dynutils::get_error());
        dynutils::unload_lib(s_dbghelpLib);
        s_dbghelpLib = nullptr;
        return;
    }

    // Create synchronization event
    s_dumpDoneEvent = CreateEventW(nullptr, TRUE, FALSE, nullptr);

    // Install Windows unhandled exception filter
    SetUnhandledExceptionFilter(unhandled_exception_filter);

    // Adjust abort behavior to preserve our handler
#ifndef MCENGINE_PLATFORM_WINDOWS_MSVCRT
#ifndef _DEBUG
    _set_abort_behavior(0, _WRITE_ABORT_MSG | _CALL_REPORTFAULT);
#else
    _set_abort_behavior(0, _CALL_REPORTFAULT);
#endif
#endif

    // Register CRT handlers
    signal(SIGABRT, signal_abort_handler);
    _set_purecall_handler(crt_purecall);
    _set_invalid_parameter_handler(crt_invalid_param);
    std::set_terminate(crt_terminate);

    // Reserve stack space and suppress WER
    {
        HMODULE kernel32 = GetModuleHandleA("kernel32.dll");
        if (kernel32) {
            using SetStackGuaranteeFn = BOOL(WINAPI*)(PULONG);
            using SetErrorModeFn = UINT(WINAPI*)(UINT);

            auto set_stack = reinterpret_cast<SetStackGuaranteeFn>(
                GetProcAddress(kernel32, "SetThreadStackGuarantee"));
            auto set_errmode = reinterpret_cast<SetErrorModeFn>(
                GetProcAddress(kernel32, "SetErrorMode"));

            if (set_stack) {
                ULONG stackReserve = 32 * 1024;
                set_stack(&stackReserve);
            }

            if (set_errmode) {
                set_errmode(SEM_FAILCRITICALERRORS | SEM_NOGPFAULTERRORBOX);
            }
        }
    }
}

