// Helper: map standard Win32 MB_* flags to internal button enum
static popup_message_v3::button_t convertButtonFlags(unsigned winFlags) {
    switch (winFlags & 0xF) {
        case MB_OK: return popup_message_v3::buttonOK;
        case MB_OKCANCEL: return popup_message_v3::buttonOK | popup_message_v3::buttonCancel;
        case MB_ABORTRETRYIGNORE: return popup_message_v3::buttonAbort | popup_message_v3::buttonRetry | popup_message_v3::buttonIgnore;
        case MB_YESNOCANCEL: return popup_message_v3::buttonYes | popup_message_v3::buttonNo | popup_message_v3::buttonCancel;
        case MB_YESNO: return popup_message_v3::buttonYes | popup_message_v3::buttonNo;
        case MB_RETRYCANCEL: return popup_message_v3::buttonRetry | popup_message_v3::buttonCancel;
        default: return popup_message_v3::buttonOK;
    }
}

// Helper: determine default button based on MB_DEFBUTTON* flags
static popup_message_v3::button_t determineDefaultButton(unsigned winFlags, popup_message_v3::button_t primaryButtons) {
    if (primaryButtons & popup_message_v3::buttonOK && (winFlags & MB_DEFBUTTON2)) return popup_message_v3::buttonCancel;
    if (primaryButtons & popup_message_v3::buttonYes && (winFlags & MB_DEFBUTTON3)) return popup_message_v3::buttonCancel;
    if (primaryButtons & popup_message_v3::buttonYes && (winFlags & MB_DEFBUTTON2)) return popup_message_v3::buttonNo;
    if (primaryButtons & popup_message_v3::buttonAbort && (winFlags & MB_DEFBUTTON3)) return popup_message_v3::buttonIgnore;
    if (primaryButtons & popup_message_v3::buttonAbort && (winFlags & MB_DEFBUTTON2)) return popup_message_v3::buttonRetry;

    // Fallback defaults
    if (primaryButtons & popup_message_v3::buttonOK) return popup_message_v3::buttonOK;
    if (primaryButtons & popup_message_v3::buttonYes) return popup_message_v3::buttonYes;
    if (primaryButtons & popup_message_v3::buttonAbort) return popup_message_v3::buttonAbort;
    if (primaryButtons & popup_message_v3::buttonRetry) return popup_message_v3::buttonRetry;
    return popup_message_v3::buttonOK;
}

