#include "geometry/angles.hpp"

namespace ang
{
double NormalizeAngle(double angle)
{
  double const twoPi = 2.0 * math::pi;
  angle = fmod(angle, twoPi);
  if (angle < 0.0)
    angle += twoPi;
  if (AlmostEqualULPs(twoPi, angle))
    return 0.0;
  return angle;
}

double CalculateAngularDifference(double angle1, double angle2)
{
  double const twoPi = 2.0 * math::pi;
  angle1 = fmod(angle1, twoPi);
  angle2 = fmod(angle2, twoPi);

  double diff = angle2 - angle1;
  if (fabs(diff) > math::pi)
  {
    if (diff < 0.0)
      diff += twoPi;
    else
      diff -= twoPi;
  }
  return diff;
}

double ComputeMidAngle(double firstAngle, double secondAngle)
{
  double midAngle = (firstAngle + secondAngle) * 0.5;
  if (fabs(firstAngle - secondAngle) > math::pi)
  {
    if (midAngle > 0.0)
      midAngle -= math::pi;
    else
      midAngle += math::pi;
  }
  return midAngle;
}
}  // namespace ang

