using Scalar = double;

int
main(int argc, char * argv[])
{
  Kokkos::initialize();
  ::testing::GTEST_FLAG(print_time) = (argc > 1) ? true : false;
  ::testing::InitGoogleTest(&argc, argv);
  int const
  result = RUN_ALL_TESTS();
  Kokkos::finalize();
  return result;
}

// Helper function to determine output stream based on test flag
inline std::ostream&
get_output_stream(bool verbose)
{
  static ROL::nullstream null_out;
  return verbose ? std::cout : null_out;
}

TEST(MiniTensor_ROL, Rosenbrock_Unconstrained_Alternative)
{
  bool const
  verbose = ::testing::GTEST_FLAG(print_time);
  std::ostream &
  out = get_output_stream(verbose);

  constexpr minitensor::Index
  DIMENSION{2};
  Scalar const
  alpha = 1.0;
  Scalar const
  beta = 100.0;
  minitensor::Rosenbrock<Scalar, DIMENSION>
  objective(alpha, beta);

  // Algorithm configuration
  std::string const
  method{"Line Search"};

  Teuchos::ParameterList
  settings;
  settings.sublist("Step").sublist("Line Search").sublist("Descent Method").
    set("Type", "Newton-Krylov");
  settings.sublist("Status Test").set("Gradient Tolerance", 1.0e-16);
  settings.sublist("Status Test").set("Step Tolerance", 1.0e-16);
  settings.sublist("Status Test").set("Iteration Limit", 128);

  // Initial point
  minitensor::Vector<Scalar, DIMENSION>
  x(minitensor::Filler::RANDOM);

  ROL::MiniTensor_Minimizer<Scalar, DIMENSION>
  solver;
  solver.solve(method, settings, objective, x);
  solver.printReport(out);

  Scalar const
  tolerance{1.0e-10};
  minitensor::Vector<Scalar, DIMENSION>
  expected_solution(alpha, alpha * alpha);
  Scalar const
  deviation = minitensor::norm(expected_solution - x);
  ASSERT_LE(deviation, tolerance);
}

TEST(MiniTensor_ROL, Paraboloid_BoundConstraint_Alternative)
{
  bool const
  verbose = ::testing::GTEST_FLAG(print_time);
  std::ostream &
  out = get_output_stream(verbose);

  constexpr minitensor::Index
  VARIABLES{2};
  minitensor::Vector<Scalar, VARIABLES>
  lower(1.0, -10.0);
  minitensor::Vector<Scalar, VARIABLES>
  upper(10.0, 10.0);

  // Optimization target
  minitensor::Paraboloid<Scalar, VARIABLES>
  objective;

  // Feasible region definition
  minitensor::Bounds<Scalar, VARIABLES>
  bounds(lower, upper);

  // Algorithm setup
  std::string const
  strategy{"Line Search"};

  Teuchos::ParameterList
  config;
