template<typename T, minitensor::Index D = 2>
class HS24_Function : public minitensor::Function_Base<HS24_Function<T, D>, T, D>
{
public:
  HS24_Function() = default;

  static constexpr
  char const *
  NAME{"HS24's Function"};

  using Base = minitensor::Function_Base<HS24_Function<T, D>, T, D>;

  template<typename U, minitensor::Index N>
  U
  value(minitensor::Vector<U, N> const & vars)
  {
    U const
    root3 = std::sqrt(3.0);
    U const
    cubic_term = vars(1) * vars(1) * vars(1);
    return root3 * vars(0) * cubic_term * (vars(0) - 6.0) / 81.0;
  }

  template<typename U, minitensor::Index N>
  minitensor::Vector<U, N>
  gradient(minitensor::Vector<U, N> const & vars)
  {
    return Base::gradient(*this, vars);
  }

  template<typename U, minitensor::Index N>
  minitensor::Tensor<U, N>
  hessian(minitensor::Vector<U, N> const & vars)
  {
    return Base::hessian(*this, vars);
  }
};

template<typename T, minitensor::Index D = 2>
class HS4_Function : public minitensor::Function_Base<HS4_Function<T, D>, T, D>
{
public:
  HS4_Function() = default;

  static constexpr
  char const *
  NAME{"HS4's Function"};

  using Base = minitensor::Function_Base<HS4_Function<T, D>, T, D>;

  template<typename U, minitensor::Index N>
  U
  value(minitensor::Vector<U, N> const & vars)
  {
    U const
    shift = vars(0) + 1.0;
    return shift * shift * shift / 3.0 + vars(1);
  }

  template<typename U, minitensor::Index N>
  minitensor::Vector<U, N>
  gradient(minitensor::Vector<U, N> const & vars)
  {
    return Base::gradient(*this, vars);
  }

  template<typename U, minitensor::Index N>
  minitensor::Tensor<U, N>
  hessian(minitensor::Vector<U, N> const & vars)
  {
    return Base::hessian(*this, vars);
  }
};

template<typename T, minitensor::Index NC = 3, minitensor::Index NV = 2>
class HS24_FeasibleRegion : public minitensor::Inequality_Constraint<HS24_FeasibleRegion<T, NC, NV>, T, NC, NV>
{
public:
  HS24_FeasibleRegion() = default;

  static constexpr
  char const *
  NAME{"HS24 feasible region"};

  using Base = minitensor::Inequality_Constraint<HS24_FeasibleRegion<T, NC, NV>, T, NC, NV>;

  template<typename U, minitensor::Index N = 2>
  minitensor::Vector<U, NC>
  value(minitensor::Vector<U, N> const & vars)
  {
    assert(vars.get_dimension() == NV);
    U const
    c = std::sqrt(3.0);
    minitensor::Vector<U, NC>
    constraints(minitensor::Filler::ZEROS);
    constraints(0) = vars(0) / c - vars(1);
    constraints(1) = vars(0) + c * vars(1);
    constraints(2) = -vars(0) - c * vars(1) + 6.0;
    return constraints;
  }

  template<typename U, minitensor::Index N = 2>
  minitensor::Matrix<U, NC, NV>
  gradient(minitensor::Vector<U, N> const & vars)
  {
    return Base::gradient(*this, vars);
  }
};
