#include "OpenColorIOEditorSettings.h"

const FOpenColorIODisplayConfiguration* UOpenColorIOLevelViewportSettings::GetViewportSettings(FName ViewportIdentifier) const
{
    // Search for a matching viewport entry using a lambda predicate
    const FPerViewportDisplaySettingPair* FoundEntry = nullptr;
    for (const auto& Entry : ViewportsSettings)
    {
        if (Entry.ViewportIdentifier == ViewportIdentifier)
        {
            FoundEntry = &Entry;
            break;
        }
    }

    if (FoundEntry)
    {
        return &FoundEntry->DisplayConfiguration;
    }
    return nullptr;
}

void UOpenColorIOLevelViewportSettings::SetViewportSettings(FName ViewportIdentifier, const FOpenColorIODisplayConfiguration& Configuration)
{
    // First, try to locate an existing entry with the same viewport identifier
    FPerViewportDisplaySettingPair* FoundEntry = nullptr;
    for (auto& Entry : ViewportsSettings)
    {
        if (Entry.ViewportIdentifier == ViewportIdentifier)
        {
            FoundEntry = &Entry;
            break;
        }
    }

    if (FoundEntry)
    {
        // Update existing configuration
        FoundEntry->DisplayConfiguration = Configuration;
    }
    else
    {
        // Create and add new entry if not found
        FPerViewportDisplaySettingPair NewEntry;
        NewEntry.ViewportIdentifier = ViewportIdentifier;
        NewEntry.DisplayConfiguration = Configuration;
        ViewportsSettings.Add(MoveTemp(NewEntry));
    }
}

