void Packet::Append(const void* data, const std::size_t sizeInBytes)
{
    if (data && sizeInBytes > 0)
    {
        const auto* start = static_cast<const std::byte*>(data);
        const auto* finish = start + sizeInBytes;
        m_data.insert(m_data.end(), start, finish);
    }
}

