Packet& Packet::operator>>(char* data)
{
    if (!data)
        throw Gx::ArgumentOutOfRangeException("Packet::operator>> Data must not be null");

    while (m_isValid)
    {
        std::uint8_t ch{};
        *this >> ch;
        *data++ = static_cast<char>(ch);
        if (ch == '\0')
            break;
    }
    return *this;
}

Packet& Packet::operator>>(std::string& data)
{
    data.clear();
    while (m_isValid)
    {
        std::uint8_t ch{};
        *this >> ch;
        if (ch == '\0')
            break;
        data += static_cast<char>(ch);
    }
    return *this;
}

Packet& Packet::operator>>(wchar_t* data)
{
    while (m_isValid)
    {
        std::uint32_t ch{};
        *this >> ch;
        *data++ = static_cast<wchar_t>(ch);
        if (ch == 0)
            break;
    }
    return *this;
}

Packet& Packet::operator>>(std::wstring& data)
{
    data.clear();
    while (m_isValid)
    {
        std::uint16_t ch{};
