        if (ch == 0)
            break;
        data += static_cast<wchar_t>(ch);
    }
    return *this;
}

Packet& Packet::operator>>(sf::String& data)
{
    data.clear();
    std::vector<char> buffer{};

    while (m_isValid)
    {
        std::uint8_t ch{};
        *this >> ch;
        if (ch == 0)
            break;
        buffer.push_back(static_cast<char>(ch));
    }

    bool reliable = false;
    int consumed = 0;
    const auto encoding = CompactEncDet::DetectEncoding(
        buffer.data(),
        buffer.size(),
        nullptr,
        nullptr,
        nullptr,
        0,
        Language::UNKNOWN_LANGUAGE,
        CompactEncDet::TextCorpusType::QUERY_CORPUS,
        true,
        &consumed,
        &reliable
    );

    switch (encoding)
    {
        case Encoding::ASCII_7BIT:
        case Encoding::UTF8:
        case Encoding::UTF8UTF8:
        {
            data = sf::String::fromUtf8(buffer.begin(), buffer.end());
            break;
        }
        case Encoding::UTF32LE:
        case Encoding::UTF32BE:
        case Encoding::GB18030:
        {
            auto* ptr = reinterpret_cast<std::uint32_t*>(buffer.data());
            data = sf::String::fromUtf16(ptr, ptr + buffer.size() / sizeof(std::uint32_t));
            break;
        }
        default:
        {
            auto* ptr = reinterpret_cast<std::uint16_t*>(buffer.data());
            data = sf::String::fromUtf16(ptr, ptr + buffer.size() / sizeof(std::uint16_t));
            break;
        }
    }
    return *this;
}

