Packet& Packet::operator<<(const std::string& data)
{
    if (!data.empty())
    {
        Append(data.c_str(), data.size());
        if (data.back() != '\0')
            *this << static_cast<std::uint8_t>(0);
    }
    return *this;
}

Packet& Packet::operator<<(const wchar_t* data)
{
    *this << std::wstring(data ? data : L"");
    return *this;
}

Packet& Packet::operator<<(const std::wstring& data)
{
    if (!data.empty())
    {
        for (const wchar_t c : data)
            *this << static_cast<std::uint16_t>(c);
        if (static_cast<std::uint16_t>(data.back()) != 0)
            *this << static_cast<std::uint16_t>(0);
    }
    return *this;
}

Packet& Packet::operator<<(const sf::String& data)
{
    if (data.getSize() > 0)
    {
        for (const std::uint32_t c : data)
        {
            if (c <= std::numeric_limits<std::uint8_t>::max())
                *this << static_cast<std::uint8_t>(c);
            else if (c <= std::numeric_limits<std::uint16_t>::max())
                *this << static_cast<std::uint16_t>(c);
            else
                *this << c;
        }
        if (static_cast<std::uint32_t>(*(data.end() - 1)) != 0)
            *this << static_cast<std::uint8_t>(0);
    }
    return *this;
}

const void* Packet::OnSend(std::size_t& size)
{
    size = GetDataSize();
    return GetData();
}

void Packet::OnReceive(const void* data, const std::size_t size)
{
    Append(data, size);
}

void Packet::Read(void* data, const std::size_t size)
{
    if (m_readPos + size <= m_data.size())
    {
        std::memcpy(data, &m_data[m_readPos], size);
        m_readPos += size;
    }
    else
    {
        m_isValid = false;
    }
}

#include "Helpers/TCPConnection.hpp"
#include <unistd.h>
#include <arpa/inet.h>
#include <sys/socket.h>
#include <cstring>
#include <fcntl.h>

namespace Core {
    namespace Network {
        TCPServer::TCPServer(int port) {
            // Create a TCP socket for the server
            server_fd = socket(AF_INET, SOCK_STREAM, 0);
            if (server_fd == -1) {
                success = false;
                return;
            }

            // Initialize and configure the server address structure
            std::memset(&addr, 0, sizeof(addr));
            addr.sin_family = AF_INET;
            addr.sin_addr.s_addr = INADDR_ANY;
            addr.sin_port = htons(static_cast<u_short>(port));

            // Attempt to bind the socket to the specified port
            if (bind(server_fd, reinterpret_cast<sockaddr*>(&addr), sizeof(addr)) < 0) {
                success = false;
                return;
            }

            success = true;
        }

        TCPServer::~TCPServer() {
            // Safely close connected client and server sockets
            if (client_fd > 0) {
                close(client_fd);
                client_fd = -1;
            }
            if (server_fd > 0) {
                close(server_fd);
                server_fd = -1;
            }
        }

        std::string TCPServer::getHostName() {
            in_addr host_id;
            host_id.s_addr = gethostid();
            if (host_id.s_addr == INADDR_NONE)
                return "";

            char ip_str[INET_ADDRSTRLEN];
            const char* result = inet_ntop(AF_INET, &host_id, ip_str, INET_ADDRSTRLEN);
            return result ? std::string(ip_str) : "";
        }

        bool TCPServer::waitConnection(WaitConnectionCallback callback) {
            aborted = false;

            // Start listening for incoming connections
            if (listen(server_fd, 1) < 0)
                return false;

            fd_set read_fds;
            struct timeval interval;
            interval.tv_sec = 0;
            interval.tv_usec = 100000; // 100 ms

            while (true) {
                // Allow external abort via callback
                if (callback != nullptr && !callback()) {
                    aborted = true;
                    return false;
                }

                FD_ZERO(&read_fds);
                FD_SET(server_fd, &read_fds);

                int status = select(server_fd + 1, &read_fds, nullptr, nullptr, &interval);
                if (status < 0)
                    return false;
                else if (status == 0)
                    continue;

                // Accept the incoming connection
                client_fd = accept(server_fd, nullptr, nullptr);
                if (client_fd < 0)
                    return false;

                break;
            }

            return true;
        }

        bool TCPServer::send_all(void *data, size_t size) {
            const char* buffer = static_cast<const char*>(data);
            size_t bytes_sent = 0;

            while (bytes_sent < size) {
                ssize_t sent = ::send(client_fd, buffer + bytes_sent, size - bytes_sent, MSG_NOSIGNAL);
                if (sent <= 0) {
                    if (errno == EINTR)
                        continue;
                    return false;
                }
                bytes_sent += static_cast<size_t>(sent);
            }

            return true;
        }

        bool TCPServer::recv(void *buffer, size_t size) {
            char* dst = static_cast<char*>(buffer);
            size_t total_read = 0;

            while (total_read < size) {
                ssize_t len = ::read(client_fd, dst + total_read, size - total_read);
                if (len <= 0)
                    return false;

                total_read += static_cast<size_t>(len);
            }

            return total_read == size;
        }
    }
}

#include "pybind11_qt/pybind11_qt_basic.h"
#include <type_traits>
#include <pybind11/stl/filesystem.h>
#include "pybind11_qt/details/pybind11_qt_utils.h"
// Required to support QVariantList and QVariantMap conversions
#include "pybind11_qt/pybind11_qt_containers.h"

namespace pybind11::detail {

    // Helper function to convert std::basic_string variants to QString
    template <class CharT>
    QString qstring_from_stdstring(std::basic_string<CharT> const& s)
    {
        if constexpr (std::is_same_v<CharT, char>) {
            return QString::fromStdString(s);
        }
        else if constexpr (std::is_same_v<CharT, wchar_t>) {
            return QString::fromStdWString(s);
        }
        else if constexpr (std::is_same_v<CharT, char16_t>) {
            return QString::fromStdU16String(s);
        }
        else if constexpr (std::is_same_v<CharT, char32_t>) {
            return QString::fromStdU32String(s);
        }
        // Fallback for unsupported character types
        return QString{};
    }

    /**
     * Python -> C++ conversion: PyObject to QString
     */
    bool type_caster<QString>::load(handle src, bool /*convert*/)
    {
        PyObject* obj = src.ptr();

        if (PyBytes_Check(obj)) {
            value = QString::fromUtf8(PyBytes_AsString(obj));
            return true;
        }
        else if (PyUnicode_Check(obj)) {
            switch (PyUnicode_KIND(obj)) {
            case PyUnicode_1BYTE_KIND:
                value = QString::fromUtf8(PyUnicode_AsUTF8(obj));
                break;
            case PyUnicode_2BYTE_KIND:
                value = QString::fromUtf16(
                    reinterpret_cast<char16_t*>(PyUnicode_2BYTE_DATA(obj)),
                    PyUnicode_GET_LENGTH(obj));
                break;
            case PyUnicode_4BYTE_KIND:
                value = QString::fromUcs4(
                    reinterpret_cast<char32_t*>(PyUnicode_4BYTE_DATA(obj)),
                    PyUnicode_GET_LENGTH(obj));
                break;
            default:
                return false;
            }
            return true;
        }
        return false;
    }

    /**
     * C++ -> Python conversion: QString to PyObject
     */
    handle type_caster<QString>::cast(QString src, return_value_policy /* policy */,
                                      handle /* parent */)
    {
        return PyUnicode_DecodeUTF16(reinterpret_cast<const char*>(src.utf16()),
                                     2 * src.length(), nullptr, 0);
    }

    /**
     * Python -> C++ conversion: PyObject to QVariant
     */
    bool type_caster<QVariant>::load(handle src, bool /*convert*/)
    {
        PyObject* obj = src.ptr();

        // Handle string-like objects first
        if (PyBytes_Check(obj) || PyUnicode_Check(obj)) {
            value = src.cast<QString>();
            return true;
        }
        // Sequence handling (e.g., lists, tuples)
        else if (PySequence_Check(obj)) {
            value = src.cast<QVariantList>();
            return true;
        }
        // Mapping (e.g., dicts)
        else if (PyMapping_Check(obj)) {
            value = src.cast<QVariantMap>();
            return true;
        }
        // None value
        else if (src.is(pybind11::none())) {
            value = QVariant{};
            return true;
        }
        // Explicit dict check (fallback)
        else if (PyDict_Check(obj)) {
            value = src.cast<QVariantMap>();
            return true;
        }
        // Boolean handling (must be checked before integer)
        else if (PyBool_Check(obj)) {
            value = src.cast<bool>();
            return true;
        }
        // Integer handling (int, long)
        else if (PyLong_Check(obj)) {
            value = src.cast<int>();
            return true;
        }

        return false;
    }

    /**
     * C++ -> Python conversion: QVariant to PyObject
     */
    handle type_caster<QVariant>::cast(QVariant var, return_value_policy policy,
                                       handle parent)
    {
        switch (var.userType()) {
        case QMetaType::UnknownType:
            return Py_None;
        case QMetaType::Int:
            return PyLong_FromLong(var.toInt());
        case QMetaType::UInt:
            return PyLong_FromUnsignedLong(var.toUInt());
        case QMetaType::Bool:
            return PyBool_FromLong(var.toBool());
        case QMetaType::QString:
            return type_caster<QString>::cast(var.toString(), policy, parent);
        case QMetaType::QStringList:
            return type_caster<QStringList>::cast(var.toStringList(), policy, parent);
        case QMetaType::QVariantList:
            return type_caster<QVariantList>::cast(var.toList(), policy, parent);
        case QMetaType::QVariantMap:
            return type_caster<QVariantMap>::cast(var.toMap(), policy, parent);
        default:
            PyErr_Format(PyExc_TypeError, "Unsupported QVariant type: %d", var.userType());
            throw pybind11::error_already_set();
        }
    }

}  // namespace pybind11::detail

