// Helper function to check if two node elements match by type and ID
static bool MatchNodeElement(const X3DNodeElementBase* node, const std::string& id, X3DElemType type) {
    return node != nullptr && node->Type == type && node->ID == id;
}

bool X3DImporter::FindNodeElement_FromRoot(const std::string& pID, const X3DElemType pType, X3DNodeElementBase** pElement) {
    auto it = std::find_if(NodeElement_List.begin(), NodeElement_List.end(),
        [&](X3DNodeElementBase* node) {
            return MatchNodeElement(node, pID, pType);
        });

    if (it != NodeElement_List.end()) {
        if (pElement != nullptr) {
            *pElement = *it;
        }
        return true;
    }

    return false;
}

bool X3DImporter::FindNodeElement_FromNode(X3DNodeElementBase* pStartNode, const std::string& pID,
                                           const X3DElemType pType, X3DNodeElementBase** pElement) {
    // Early exit: check current node first
    if (MatchNodeElement(pStartNode, pID, pType)) {
        if (pElement != nullptr) {
            *pElement = pStartNode;
        }
        return true;
    }

    // Recursively search children
    for (X3DNodeElementBase* child : pStartNode->Children) {
        if (FindNodeElement_FromNode(child, pID, pType, pElement)) {
            return true;
        }
    }

    return false;
}

bool X3DImporter::FindNodeElement(const std::string& pID, const X3DElemType pType, X3DNodeElementBase** pElement) {
    X3DNodeElementBase* currentNode = mNodeElementCur;

    // Traverse upward to find if any ancestor is a static group
    while (currentNode != nullptr) {
        if (currentNode->Type == X3DElemType::ENET_Group) {
            auto* groupNode = static_cast<X3DNodeElementGroup*>(currentNode);
            if (groupNode->Static) {
                // Found static group — perform search from this node
                return FindNodeElement_FromNode(currentNode, pID, pType, pElement);
            }
        }
        currentNode = currentNode->Parent;
    }

    // No static ancestor found — search from root
    return FindNodeElement_FromRoot(pID, pType, pElement);
}

/*********************************************************************************************************************************************/
/************************************************************ Functions: parse set ***********************************************************/
/*********************************************************************************************************************************************/

void X3DImporter::ParseHelper_Group_Begin(const bool pStatic) {
    auto* newGroup = new X3DNodeElementGroup(mNodeElementCur, pStatic);

    if (mNodeElementCur != nullptr) {
        mNodeElementCur->Children.emplace_back(newGroup);
    }

    NodeElement_List.emplace_back(newGroup);
    mNodeElementCur = newGroup;
}

void X3DImporter::ParseHelper_Node_Enter(X3DNodeElementBase* pNode) {
    ai_assert(pNode != nullptr);

    mNodeElementCur->Children.emplace_back(pNode);
    mNodeElementCur = pNode;
}

void X3DImporter::ParseHelper_Node_Exit() {
    if (mNodeElementCur != nullptr && mNodeElementCur->Parent != nullptr) {
        mNodeElementCur = mNodeElementCur->Parent;
    }
}

