// MARK: File Descriptors ------------------------------------------------------
Res<Rc<Fd>> openFile(String const& path) {
    int raw = ::open(path.c_str(), O_RDONLY);
    if (raw < 0)
        return Posix::fromLastErrno();

    auto fd = makeRc<Posix::Fd>(raw);
    auto st = try$(fd->stat());
    if (st.type == Type::DIR)
        return Error::isADirectory();
    return Ok(fd);
}

Res<Rc<Fd>> createFile(String const& path) {
    int raw = ::open(path.c_str(), O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (raw < 0)
        return Posix::fromLastErrno();
    return Ok(makeRc<Posix::Fd>(raw));
}

Res<Rc<Fd>> openOrCreateFile(String const& path) {
    int raw = ::open(path.c_str(), O_RDWR | O_CREAT, 0644);
    if (raw < 0)
        return Posix::fromLastErrno();

    auto fd = makeRc<Posix::Fd>(raw);
    auto st = try$(fd->stat());
    if (st.type == Type::DIR)
        return Error::isADirectory();
    return Ok(fd);
}

Res<Pair<Rc<Fd>>> createPipe() {
    int pipeFds[2];
    if (::pipe(pipeFds) < 0)
        return Posix::fromLastErrno();

    return Ok(Pair<Rc<Fd>>{
        makeRc<Posix::Fd>(pipeFds[0]),
        makeRc<Posix::Fd>(pipeFds[1])
    });
}

