// MARK: Directory Operations --------------------------------------------------
Res<Vec<DirEntry>> listDirectory(String const& path) {
    DIR* dir = ::opendir(path.c_str());
    if (!dir)
        return Posix::fromLastErrno();

    Vec<DirEntry> result;
    struct dirent* entry;
    errno = 0;

    while ((entry = ::readdir(dir))) {
        try$(Posix::consumeErrno());

        String name(entry->d_name);
        if (name == "." || name == "..")
            continue;

        Type t = (entry->d_type == DT_DIR) ? Type::DIR : Type::FILE;
        result.pushBack({name, t});
    }

    if (::closedir(dir) < 0)
        return Posix::fromLastErrno();

    return Ok(result);
}

Res<> makeDirectory(String const& path) {
    if (::mkdir(path.c_str(), 0755) < 0) {
        if (errno == EEXIST)
            return Error::alreadyExists("directory already exists");
        return Posix::fromLastErrno();
    }
    return Ok();
}

Res<Vec<DirEntry>> ensureDirectory(String const& path) {
    DIR* dir = ::opendir(path.c_str());
    Defer cleanup([&]() { if (dir) ::closedir(dir); });

    if (dir) {
        Vec<DirEntry> entries;
        struct dirent* entry;
        errno = 0;

        while ((entry = ::readdir(dir))) {
            try$(Posix::consumeErrno());
            String name(entry->d_name);
            if (name == "." || name == "..") continue;

            Type t = (entry->d_type == DT_DIR) ? Type::DIR : Type::FILE;
            entries.pushBack({name, t});
        }
        return Ok(entries);
    } else {
        if (errno != ENOENT)
            return Posix::fromLastErrno();
        try$(makeDirectory(path));
        return Ok(Vec<DirEntry>{});
    }
}

Res<Stat> getFileStatus(String const& path) {
    struct stat buf;
    if (::stat(path.c_str(), &buf) < 0)
        return Posix::fromLastErrno();
    return Ok(Posix::fromStat(buf));
}

// MARK: Process Spawning ------------------------------------------------------
struct PosixPid : Pid {
    pid_t _pid;
    PosixPid(pid_t p) : _pid(p) {}

    Res<> terminate() override {
        if (::kill(_pid, SIGKILL) == -1)
            return Posix::fromLastErrno();
        return Ok();
    }

    Res<> awaitTermination() override {
        int status;
        if (::waitpid(_pid, &status, 0) == -1)
            return Posix::fromLastErrno();
        return Ok();
    }
};

Res<Rc<Pid>> runProcess(Command const& cmd) {
    if (!cmd.exe || cmd.exe.empty())
        return Error::invalidInput("no executable specified");

    // Build argument vector
    std::vector<char*> args;
    args.push_back(const_cast<char*>(cmd.exe.c_str()));
    for (auto const& arg : cmd.args)
        args.push_back(const_cast<char*>(arg.c_str()));
    args.push_back(nullptr);

    // Build environment vector
    std::vector<std::string> envStrings;
    std::vector<char*> envPtrs;
    for (auto const& [k, v] : cmd.env) {
        envStrings.emplace_back(Io::format("{}={}", k, v));
    }
    for (auto& s : envStrings)
        envPtrs.push_back(const_cast<char*>(s.c_str()));
    envPtrs.push_back(nullptr);

    // Prepare file descriptors
    int inFD = -1, outFD = -1, errFD = -1;
    if (cmd.in)  inFD  = try$(Posix::ensurePosixFd(cmd.in.value()))->_raw;
    if (cmd.out) outFD = try$(Posix::ensurePosixFd(cmd.out.value()))->_raw;
    if (cmd.err) errFD = try$(Posix::ensurePosixFd(cmd.err.value()))->_raw;

    pid_t child = ::fork();
    if (child < 0)
        return Posix::fromLastErrno();

    if (child == 0) {
        // Child process
        if (cmd.in && ::dup2(inFD, STDIN_FILENO) < 0)
            _exit(127);
        if (cmd.out && ::dup2(outFD, STDOUT_FILENO) < 0)
            _exit(127);
        if (cmd.err && ::dup2(errFD, STDERR_FILENO) < 0)
            _exit(127);

        if (!cmd.env.empty()) {
            ::execve(cmd.exe.c_str(), args.data(), envPtrs.data());
        } else {
            ::execvp(cmd.exe.c_str(), args.data());
        }
        _exit(127);
    }

    return Ok(makeRc<PosixPid>(child));
}

Res<Tuple<Rc<Pid>, Rc<Fd>>> runPtyProcess(Command const& cmd) {
    if (!cmd.exe || cmd.exe.empty())
        return Error::invalidInput("no executable specified");

    std::vector<char*> args;
    args.push_back(const_cast<char*>(cmd.exe.c_str()));
    for (auto const& arg : cmd.args)
        args.push_back(const_cast<char*>(arg.c_str()));
    args.push_back(nullptr);

    std::vector<std::string> envStrings;
    std::vector<char*> envPtrs;
    for (auto const& [k, v] : cmd.env) {
        envStrings.emplace_back(Io::format("{}={}", k, v));
    }
    for (auto& s : envStrings)
        envPtrs.push_back(const_cast<char*>(s.c_str()));
    envPtrs.push_back(nullptr);

    int ptyFD = -1;
    pid_t child = ::forkpty(&ptyFD, nullptr, nullptr, nullptr);
    ArmedDefer closePty([&]() { if (ptyFD != -1) ::close(ptyFD); });

    if (child < 0)
        return Posix::fromLastErrno();

    if (child == 0) {
        if (!cmd.env.empty()) {
            ::execve(cmd.exe.c_str(), args.data(), envPtrs.data());
        } else {
            ::execvp(cmd.exe.c_str(), args.data());
        }
        _exit(127);
    }

    closePty.disarm();
    return Ok(Tuple<Rc<Pid>, Rc<Fd>>(
        makeRc<PosixPid>(child),
        makeRc<Posix::Fd>(ptyFD)
    ));
}

// MARK: Network Sockets -------------------------------------------------------
Res<Rc<Fd>> bindUdp(SocketAddr const& addr) {
    int sock = ::socket(AF_INET, SOCK_DGRAM, 0);
    if (sock < 0)
        return Posix::fromLastErrno();

    sockaddr_in sa = Posix::toSockAddr(addr);
    if (::bind(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) < 0)
        return Posix::fromLastErrno();

    return Ok(makeRc<Posix::Fd>(sock));
}

Res<Rc<Fd>> connectTcp(SocketAddr const& addr) {
    int sock = ::socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0)
        return Posix::fromLastErrno();

    sockaddr_in sa = Posix::toSockAddr(addr);
    if (::connect(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) < 0)
        return Posix::fromLastErrno();

    return Ok(makeRc<Posix::Fd>(sock));
}

Res<Rc<Fd>> listenTcp(SocketAddr const& addr) {
    int sock = ::socket(AF_INET, SOCK_STREAM, 0);
    if (sock < 0)
        return Posix::fromLastErrno();

    int reuse = 1;
    if (::setsockopt(sock, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse)) < 0)
        return Posix::fromLastErrno();

    sockaddr_in sa = Posix::toSockAddr(addr);
    if (::bind(sock, reinterpret_cast<sockaddr*>(&sa), sizeof(sa)) < 0)
        return Posix::fromLastErrno();
    if (::listen(sock, 128) < 0)
        return Posix::fromLastErrno();

    return Ok(makeRc<Posix::Fd>(sock));
}

Res<Rc<Fd>> connectIpc(String const& path) {
    int sock = ::socket(AF_UNIX, SOCK_STREAM, 0);
    if (sock < 0)
        return Posix::fromLastErrno();

    sockaddr_un sun{};
    sun.sun_family = AF_UNIX;
    String normalizedPath = path;
    size_t maxLen = sizeof(sun.sun_path) - 1;
    if (normalizedPath.size() > maxLen)
        normalizedPath.resize(maxLen);
    std::memcpy(sun.sun_path, normalizedPath.c_str(), normalizedPath.size());

    if (::connect(sock, reinterpret_cast<sockaddr*>(&sun), sizeof(sun)) < 0)
        return Posix::fromLastErrno();

    return Ok(makeRc<Posix::Fd>(sock));
}

Res<Rc<Fd>> listenIpc(String const& path) {
    int sock = ::socket(AF_UNIX, SOCK_STREAM, 0);
    if (sock < 0)
        return Posix::fromLastErrno();

    sockaddr_un sun{};
    sun.sun_family = AF_UNIX;
    String normalizedPath = path;
    size_t maxLen = sizeof(sun.sun_path) - 1;
    if (normalizedPath.size() > maxLen)
        normalizedPath.resize(maxLen);
    std::memcpy(sun.sun_path, normalizedPath.c_str(), normalizedPath.size());

    if (::bind(sock, reinterpret_cast<sockaddr*>(&sun), sizeof(sun)) < 0)
        return Posix::fromLastErrno();
    if (::listen(sock, 128) < 0)
        return Posix::fromLastErrno();

    return Ok(makeRc<Posix::Fd>(sock));
}

// MARK: Time Management -------------------------------------------------------
Duration fromTimespec(timespec const& ts) {
    u64 usecs = static_cast<u64>(ts.tv_sec) * 1000000 + static_cast<u64>(ts.tv_nsec) / 1000;
    return Duration::fromUSecs(usecs);
}

SystemTime currentTime() {
    timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    return SystemTime::epoch() + fromTimespec(ts);
}

Instant monotonicTime() {
    timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return Instant::epoch() + fromTimespec(ts);
}

Duration systemUptime() {
    timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return fromTimespec(ts);
}

// MARK: Memory Mapping --------------------------------------------------------
int mapProtection(MmapProps const& opts) {
    int prot = 0;
    if (opts.options & MmapOption::READ)  prot |= PROT_READ;
    if (opts.options & MmapOption::WRITE) prot |= PROT_WRITE;
    if (opts.options & MmapOption::EXEC)  prot |= PROT_EXEC;
    return prot;
}

Res<MmapResult> mapMemory(MmapProps const& opts) {
    void* ptr = ::mmap(reinterpret_cast<void*>(opts.vaddr), opts.size,
                       mapProtection(opts), MAP_ANONYMOUS | MAP_PRIVATE, -1, 0);
    if (ptr == MAP_FAILED)
        return Posix::fromLastErrno();

    if (opts.options & MmapOption::PREFETCH) {
        if (::madvise(ptr, opts.size, MADV_WILLNEED) < 0)
            return Posix::fromLastErrno();
    }

    return Ok(MmapResult{0, reinterpret_cast<usize>(ptr), opts.size});
}

Res<MmapResult> mapMemory(MmapProps const& opts, Rc<Fd> fd) {
    Rc<Posix::Fd> posixFd = try$(fd.cast<Posix::Fd>());
    usize len = opts.size ?: try$(Io::size(*posixFd));

    void* ptr = ::mmap(reinterpret_cast<void*>(opts.vaddr), len,
                       mapProtection(opts), MAP_SHARED,
                       posixFd->_raw, opts.offset);
    if (ptr == MAP_FAILED)
        return Posix::fromLastErrno();

    return Ok(MmapResult{0, reinterpret_cast<usize>(ptr), len});
}

Res<> unmapMemory(void const* addr, usize len) {
    if (::munmap(const_cast<void*>(addr), len) < 0)
        return Posix::fromLastErrno();
    return Ok();
}

Res<> flushMemory(void* addr, usize len) {
    if (::msync(addr, len, MS_INVALIDATE) < 0)
        return Posix::fromLastErrno();
    return Ok();
}

usize getPageSize() {
