        return Posix::fromLastErrno();

    info.sysName = "Posix";
    info.sysVersion = Io::format("{}", _POSIX_VERSION);
    info.kernelName = Str::fromNullterminated(unameData.sysname, sizeof(unameData.sysname));
    info.kernelVersion = Str::fromNullterminated(unameData.release, sizeof(unameData.release));
    info.hostname = Str::fromNullterminated(unameData.nodename, sizeof(unameData.nodename));
    return Ok();
}

