Res<> gatherUserInfo(UserInfo& info) {
    char const* user = getenv("USER");
    char const* home = getenv("HOME");
    char const* shell = getenv("SHELL");

    info.name = user ? Str::fromNullterminated(user) : "";
    info.home.scheme = "file"_sym;
    info.home.path = Ref::Path::parse(home ? home : "");
    info.shell.scheme = "file"_sym;
    info.shell.path = Ref::Path::parse(shell ? shell : "");
    return Ok();
