    return Ok();
}

// MARK: Sleep & Exit ----------------------------------------------------------
Res<> delay(Duration span) {
    timespec req{};
    req.tv_sec = span.toSecs();
    req.tv_nsec = (span.toUSecs() % 1000000) * 1000;
    if (::nanosleep(&req, nullptr) < 0)
        return Posix::fromLastErrno();
    return Ok();
}

