Res<String> currentWorkingDirectory() {
    Buf<char> buffer(256);
    while (true) {
        if (::getcwd(buffer.buf(), buffer.len()))
            break;
        if (errno != ERANGE)
            return Posix::fromLastErrno();
        buffer.resize(buffer.len() * 2);
    }
    return Ok(Str::fromNullterminated(buffer.buf()));
}

// MARK: DNS Resolution --------------------------------------------------------
Async::Task<Vec<Ip>> resolveHostAsync(Str hostname) {
    addrinfo hints{};
    hints.ai_family = AF_INET;
    hints.ai_socktype = SOCK_STREAM;

    Vec<Ip> addresses;

    if (hostname == "localhost") {
        addresses.pushBack(Ip4::localhost());
        addresses.pushBack(Ip6::localhost());
        co_return Ok(addresses);
    }

    addrinfo* res;
    int rc = getaddrinfo(hostname.c_str(), nullptr, &hints, &res);
    if (rc != 0) {
        switch (rc) {
        case EAI_ADDRFAMILY: co_return Error::invalidInput("unsupported address family");
        case EAI_AGAIN:      co_return Error::timedOut("DNS resolution timed out");
        case EAI_FAIL:       co_return Error::other("non-recoverable DNS failure");
        case EAI_FAMILY:     co_return Error::invalidInput("unsupported address family");
        case EAI_MEMORY:     co_return Error::outOfMemory("memory allocation failed");
        case EAI_NONAME:     co_return Error::notFound("host not found");
        case EAI_SERVICE:    co_return Error::invalidInput("service not supported");
        case EAI_SOCKTYPE:   co_return Error::invalidInput("socket type not supported");
        default:             co_return Posix::fromLastErrno();
        }
    }

    for (auto* node = res; node; node = node->ai_next) {
        if (node->ai_family == AF_INET) {
            sockaddr_in* sin = reinterpret_cast<sockaddr_in*>(node->ai_addr);
            u32 raw = bswap(ntohl(sin->sin_addr.s_addr));
            addresses.pushBack(Ip4::fromRaw(raw));
        } else if (node->ai_family == AF_INET6) {
            sockaddr_in6* sin6 = reinterpret_cast<sockaddr_in6*>(node->ai_addr);
            u128 raw = 0;
            u16 const* words = reinterpret_cast<u16 const*>(sin6->sin6_addr.s6_addr);
            for (usize i = 0; i < 8; ++i)
                raw |= (u128)words[i] << (i * 16);
            addresses.pushBack(Ip6::fromRaw(bswap(raw)));
        }
    }

    freeaddrinfo(res);
    co_return Ok(addresses);
}

