// Helper to verify that all generated trees are distinct and count matches expectation
void validate_tree_collection(multitree_node* root, index expected_count) {
    multitree_iterator iter(root);
    std::vector<std::vector<simple_bitvector>> tree_signatures;

    // Collect bipartition signatures for each tree
    do {
        tree_signatures.emplace_back(tree_bipartitions(iter.tree()));
    } while (iter.next());

    // Ensure no duplicates: use set-based deduplication
    std::set<std::vector<simple_bitvector>> unique_sigs(tree_signatures.begin(), tree_signatures.end());
    REQUIRE(unique_sigs.size() == tree_signatures.size());

    // Confirm correct number of trees
    REQUIRE(tree_signatures.size() == expected_count);
}

TEST_CASE("multitree_iterator init simple", "[multitree]") {
    auto input = std::istringstream{"7 4\n1 1 1 1 s1\n0 0 1 0 s2\n1 1 0 0 s3\n1 1 1 0 "
                                    "s4\n1 1 0 1 s5\n1 0 0 1 s7\n0 0 0 1 s13"};
    auto matrix_data = terraces::parse_bitmatrix(input);
    auto phylogeny = terraces::parse_nwk("((((s2,s4),((s13,s1),s7)),s3),s5);", matrix_data.indices);
    auto supertree_info = terraces::create_supertree_data(phylogeny, matrix_data.matrix);

    tree_enumerator<variants::multitree_callback> gen{{}};
    auto enumeration_result = gen.run(supertree_info.num_leaves,
                                      supertree_info.constraints,
                                      supertree_info.root);

    validate_tree_collection(enumeration_result, 9);
}

TEST_CASE("multitree_iterator init unconstrained", "[multitree]") {
    name_map taxa{"1", "2", "3", "4", "5", "6", "7", "8"};
    constraints fixed_clades{{0, 1, 2}};
    index root_taxon = 0;

    tree_enumerator<variants::multitree_callback> generator{{}};
    auto generated_trees = generator.run(taxa.size(), fixed_clades, root_taxon);

    validate_tree_collection(generated_trees, count_unrooted_trees<index>(taxa.size() - 1));
}

