// Helper macro to adjust dialog size on main thread
#define RESIZE_DIALOG runOnThread([=, this] { resize(sizeHint()); move(centeredPosition(mainwindow)); }, this);

DialogEditGroup::DialogEditGroup(const std::shared_ptr<Configs::Group> &groupData, QWidget *parent)
    : QDialog(parent), ui(new Ui::DialogEditGroup) {
    CHECK_SETTINGS_ACCESS
    ui->setupUi(this);
    currentGroup = groupData;

    // Handle type change: hide category sub if not URL-based
    connect(ui->type, &QComboBox::currentIndexChanged, this, [=, this](int idx) {
        ui->cat_sub->setVisible(idx != 0);
        RESIZE_DIALOG
    });

    // Initialize fields from group data
    ui->name->setText(groupData->name);
    ui->archive->setChecked(groupData->archive);
    ui->skip_auto_update->setChecked(groupData->skip_auto_update);
    ui->url->setText(groupData->url);

    // Set combo box based on whether URL is empty
    int initialTypeIndex = groupData->url.isEmpty() ? 0 : 1;
    ui->type->setCurrentIndex(initialTypeIndex);
    ui->type->currentIndexChanged(ui->type->currentIndex());

    // Restore column width setting
    ui->manually_column_width->setChecked(Configs::tableSettings.manually_column_width);

    // Determine if sharing tab should be hidden
    bool shareTabHidden = true;
    if (groupData->id >= 0) {
        ui->type->setEnabled(false);
        if (!groupData->Profiles().isEmpty()) {
            shareTabHidden = false;
        }
    }

    // Copy links lambda: builds list of share links for profiles in this group
    auto copyShareLinks = [gid = groupData->id, this](bool useNekorayFormat) {
        QStringList linkList;
        for (const auto &[_, profilePtr] : Configs::profileManager->profiles) {
            if (profilePtr->gid != gid) continue;
            QString link;
            if (useNekorayFormat) {
                link = profilePtr->bean->ToNekorayShareLink(profilePtr->type);
            } else {
                link = profilePtr->bean->ToShareLink();
            }
            linkList.append(link);
        }
        QApplication::clipboard()->setText(linkList.join("\n"));
        runOnUiThread([this]() {
            QMessageBox::information(this, software_name, tr("Copied"));
        });
    };

    // Connect copy buttons
    connect(ui->copy_links, &QPushButton::clicked, this, [copyShareLinks]() {
        copyShareLinks(false);
    });
    connect(ui->copy_links_nkr, &QPushButton::clicked, this, [copyShareLinks]() {
        copyShareLinks(true);
    });

    // Focus name field
    ui->name->setFocus();

    // Load cache values
    CACHE.landing_proxy_id = groupData->landing_proxy_id;
    CACHE.front_proxy_id = groupData->front_proxy_id;
    CACHE.edited = false;
    CACHE.loaded = false;

    // Tab switching handler
    connect(ui->tabs, &QTabWidget::currentChanged, this, &DialogEditGroup::on_refresh_proxy_items);

    // Hide share tab if needed
    if (shareTabHidden) {
        ui->tabs->tabBar()->setTabVisible(2, false);
    }

    RESIZE_DIALOG
}

// Proxy model for filtering table rows by address/name
class GroupTableProxyFilter : public QSortFilterProxyModel {
public:
    explicit GroupTableProxyFilter(DialogGroupChooseProxy *owner = nullptr)
        : QSortFilterProxyModel(owner), ownerWindow(owner) {}

protected:
    bool filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const override {
        QModelIndex addrIdx = sourceModel()->index(sourceRow, 1, sourceParent); // col 1 = address
        QModelIndex nameIdx = sourceModel()->index(sourceRow, 2, sourceParent); // col 2 = name

        QString addrStr = addrIdx.data().toString();
        QString nameStr = nameIdx.data().toString();
        QString filterText = ownerWindow->ui->search_line->text();

        return addrStr.contains(filterText, Qt::CaseInsensitive) ||
               nameStr.contains(filterText, Qt::CaseInsensitive);
    }

private:
    DialogGroupChooseProxy *ownerWindow;
};

// Table model for displaying group profiles
class ProfileTableModel : public QAbstractTableModel {
public:
    std::shared_ptr<Configs::Group> targetGroup;

    ProfileTableModel(std::shared_ptr<Configs::Group> grp, QObject *parent = nullptr)
        : QAbstractTableModel(parent), targetGroup(grp) {}

    int rowCount(const QModelIndex &parent = QModelIndex()) const override {
        return targetGroup ? static_cast<int>(targetGroup->profiles.size()) : 0;
    }

    int columnCount(const QModelIndex &parent = QModelIndex()) const override {
        return 3; // Type, Address, Name
    }

    QVariant headerData(int section, Qt::Orientation orientation, int role) const override {
        if (role == Qt::DisplayRole && orientation == Qt::Horizontal) {
            switch (section) {
                case 0: return QCoreApplication::translate("MainWindow", "Type");
                case 1: return QCoreApplication::translate("MainWindow", "Address");
                case 2: return QCoreApplication::translate("MainWindow", "Name");
            }
        }
        return QVariant();
    }

    enum CustomRoles {
        RawProfileIdRole = 909090
    };

    QVariant data(const QModelIndex &index, int role) const override {
        if (!index.isValid() || !targetGroup) return QVariant();

        int row = index.row();
        if (row >= targetGroup->profiles.size()) return QVariant();

        int profileId = targetGroup->profiles[row];
        auto bean = Configs::profileManager->profiles.at(profileId)->bean;

        if (role == RawProfileIdRole) {
            return profileId;
        }

        if (role == Qt::DisplayRole) {
            int col = index.column();
            switch (col) {
                case 0: return bean->DisplayType();
                case 1: return bean->DisplayAddress();
                case 2: return bean->name;
            }
        }

        return QVariant();
    }

    bool setData(const QModelIndex &, const QVariant &, int) override { return false; }

    Qt::ItemFlags flags(const QModelIndex &index) const override {
        return index.isValid() ? (Qt::ItemIsSelectable | Qt::ItemIsEnabled) : Qt::NoItemFlags;
    }
};

// Dialog to choose proxy from groups
DialogGroupChooseProxy::DialogGroupChooseProxy(QWidget *parent)
    : QDialog(parent), ui(new Ui::DialogGroupChooseProxy) {
    ui->setupUi(this);

    // Populate group tabs
    auto groupTabs = ui->groups;
    groupTabs->clear();
    groupIds.clear();

    auto currentGroup = Configs::profileManager->CurrentGroup();
    int currentGroupId = currentGroup->id;
    int activeTabIndex = 0;
    QWidget *activeTabWidget = nullptr;

    int tabIndex = 0;
    for (const auto &[groupId, groupPtr] : Configs::profileManager->groups) {
        QWidget *tabWidget = new QWidget();
        groupIds.push_back(groupId);

        if (groupId == currentGroupId) {
            activeTabWidget = tabWidget;
            activeTabIndex = tabIndex;
        }

        groupTabs->addTab(tabWidget, groupPtr->name);
        ++tabIndex;
    }

    connect(groupTabs, &QTabWidget::currentChanged, this, &DialogGroupChooseProxy::switchTab);

    // Button box handling
    connect(ui->buttons, &QDialogButtonBox::clicked, this, &DialogGroupChooseProxy::handleButtonPress);

    if (activeTabIndex == 0) {
        switchTab(activeTabIndex);
    } else {
        groupTabs->setCurrentIndex(activeTabIndex);
    }
}

void DialogGroupChooseProxy::handleButtonPress(QAbstractButton *btn) {
    auto role = ui->buttons->buttonRole(btn);
    int selectedProfileId = -1;

    switch (role) {
        case QDialogButtonBox::ResetRole:
            selectedProfileId = defaultProfileId;
            [[fallthrough]];
        case QDialogButtonBox::DestructiveRole:
            emit select_proxy(selectedProfileId);
            break;
        case QDialogButtonBox::ApplyRole:
        case QDialogButtonBox::AcceptRole:
            emit set_proxy(selectedProxyId);
            break;
        case QDialogButtonBox::RejectRole:
        default:
            break;
    }

    if (role == QDialogButtonBox::AcceptRole ||
        role == QDialogButtonBox::RejectRole ||
        role == QDialogButtonBox::DestructiveRole) {
        close();
    }
}

void DialogGroupChooseProxy::selectProfile(int id, bool markAsDefault) {
    if (selectedProxyId != id) {
        emit select_proxy(id);
    }
    selectedProxyId = id;
    ui->profile_label->setText(DialogEditGroup::getProxyName(id, isForRouteProfile));

    if (markAsDefault) {
        defaultProfileId = id;
    }
}

void DialogGroupChooseProxy::switchTab(int groupIndex) {
    QWidget *tabWidget = ui->groups->widget(groupIndex);
    if (!tabWidget->layout()) {
        auto groupData = Configs::profileManager->groups[groupIds[groupIndex]];

        QVBoxLayout *mainLayout = new QVBoxLayout(tabWidget);
        ProfileTableModel *model = new ProfileTableModel(groupData, this);
        QTableView *tableView = new QTableView();

        mainLayout->addWidget(tableView);
        tabWidget->setLayout(mainLayout);

        tableView->setSelectionBehavior(QAbstractItemView::SelectRows);
        tableView->setSelectionMode(QAbstractItemView::SingleSelection);

        auto selectionModel = tableView->selectionModel();
        GroupTableProxyFilter *filterModel = new GroupTableProxyFilter(this);
        filterModel->setSourceModel(model);

        // Selection handlers
        connect(selectionModel, &QItemSelectionModel::currentChanged,
            this, [selectionModel, filterModel, this](const QModelIndex &current, const QModelIndex &) {
                if (current.isValid() && selectionModel->hasSelection()) {
                    int pid = filterModel->data(current, ProfileTableModel::RawProfileIdRole).toInt();
                    selectProfile(pid);
                }
            });

        connect(tableView, &QTableView::clicked,
            this, [filterModel, this](const QModelIndex &idx) {
                if (idx.isValid()) {
                    int pid = filterModel->data(idx, ProfileTableModel::RawProfileIdRole).toInt();
                    selectProfile(pid);
                }
            });

        connect(tableView, &QTableView::selectRow,
            this, [filterModel, this](int row) {
                QModelIndex idx = filterModel->index(row, 1);
                int pid = filterModel->data(idx, ProfileTableModel::RawProfileIdRole).toInt();
                selectProfile(pid);
            });

        // Resize columns
        auto header = tableView->horizontalHeader();
        header->setSectionResizeMode(0, QHeaderView::ResizeToContents);
        header->setSectionResizeMode(1, QHeaderView::ResizeToContents);
        header->setSectionResizeMode(2, QHeaderView::ResizeToContents);

        ui->profile_label->setReadOnly(true);

        // Search filter binding
        connect(ui->search_line, &QLineEdit::textChanged,
            filterModel, &QSortFilterProxyModel::setFilterFixedString);

        tableView->setModel(filterModel);
    } else {
        QTableView *view = qobject_cast<QTableView*>(tabWidget->layout()->itemAt(0)->widget());
        if (view) view->clearSelection();
    }
}

