void DialogEditGroup::accept() {
    // Validate URL input for remote groups
    if (currentGroup->id >= 0 && !currentGroup->url.isEmpty() && ui->url->text().isEmpty()) {
        runOnUiThread([this]() {
            QMessageBox::warning(this, tr("Warning"), tr("Please input URL"));
        });
        return;
    }

    // Save updated group data
    currentGroup->name = ui->name->text();
    currentGroup->url = ui->url->text();
    currentGroup->archive = ui->archive->isChecked();
    currentGroup->skip_auto_update = ui->skip_auto_update->isChecked();
    Configs::tableSettings.manually_column_width = ui->manually_column_width->isChecked();

    if (CACHE.edited) {
        currentGroup->landing_proxy_id = CACHE.landing_proxy_id;
        currentGroup->front_proxy_id = CACHE.front_proxy_id;
    }

    if (NOTES.edited) {
        QString notes = ui->group_notes->toPlainText();
        currentGroup->saveNotes(notes);
    }

    currentGroup->Save();
    QDialog::accept();
}

void DialogEditGroup::on_refresh_proxy_items(int tabIndex) {
    if (tabIndex == 1) {
        if (!CACHE.loaded) {
            CACHE.loaded = true;
            goto load_proxies;
        }
    } else if (tabIndex == 3) {
        if (!NOTES.loaded) {
            NOTES.loaded = true;
            ui->group_notes->setText(currentGroup->getNotes());
            connect(ui->group_notes, &QTextEdit::textChanged,
                this, [this]() { NOTES.edited = true; }, Qt::SingleShotConnection);
        }
    }

    if (NOTES.loaded && CACHE.loaded) {
        disconnect(ui->tabs, &QTabWidget::currentChanged, this, &DialogEditGroup::on_refresh_proxy_items);
    }
    return;

load_proxies:
    ui->front_proxy->setText(getProxyName(currentGroup->front_proxy_id).trimmed());
    ui->landing_proxy->setText(getProxyName(currentGroup->landing_proxy_id).trimmed());

    // Front proxy button handler
    connect(ui->front_proxy, &QCommandLinkButton::clicked, this, [=, this](bool) {
        auto window = new DialogGroupChooseProxy(this);
        QObject::connect(window, &DialogGroupChooseProxy::set_proxy, this, &DialogEditGroup::setFrontProxy);
        window->setWindowTitle(QCoreApplication::translate("DialogGroupChooseProxy",
            "Front proxy for group %1").arg(currentGroup->name));
        window->ui->profile_label->setText(QCoreApplication::translate("DialogGroupChooseProxy", "Front proxy: "));
        window->selectProfile(currentGroup->front_proxy_id, true);
        window->show();
    });

    // Landing proxy button handler
    connect(ui->landing_proxy, &QCommandLinkButton::clicked, this, [=, this](bool) {
        auto window = new DialogGroupChooseProxy(this);
        QObject::connect(window, &DialogGroupChooseProxy::set_proxy, this, &DialogEditGroup::setLandingProxy);
        window->setWindowTitle(QCoreApplication::translate("DialogGroupChooseProxy",
            "Landing proxy for group %1").arg(currentGroup->name));
        window->ui->profile_label->setText(QCoreApplication::translate("DialogGroupChooseProxy", "Landing proxy: "));
        window->selectProfile(currentGroup->landing_proxy_id, true);
        window->show();
    });
}

QString DialogEditGroup::getProxyName(int id, bool isForRouteProfile) {
    std::shared_ptr<Configs::ProxyEntity> profile;
    if (id < 0 || !(profile = Configs::profileManager->GetProfile(id))) {
        if (isForRouteProfile) {
            if (id == -1) return QCoreApplication::translate("DialogGroupChooseProxy", "Proxy");
            if (id == -2) return QCoreApplication::translate("DialogGroupChooseProxy", "Direct");
        }
        return QCoreApplication::translate("DialogGroupChooseProxy", "None");
    }

    QString name = profile->bean->name;
    if (name.isEmpty()) {
        return QString("ID: ") + QString::number(id);
    }
    return name;
}

#include <iostream>
#include <cmath>

// Define constants for simulation parameters
const double MAX_TIME_STEP = 0.01;
const double WAVE_SPEED = 10.0;

// Grid dimensions
const int GRID_WIDTH = 50;
const int GRID_HEIGHT = 50;
const int TOTAL_VERTICES = GRID_WIDTH * GRID_HEIGHT;
const int NUM_QUADS_X = GRID_WIDTH - 1;
const int NUM_QUADS_Y = GRID_HEIGHT - 1;
const int TOTAL_QUADS = NUM_QUADS_X * NUM_QUADS_Y;

// Simulation state variables
double pressure[GRID_WIDTH][GRID_HEIGHT];
double velocityX[GRID_WIDTH][GRID_HEIGHT];
double velocityY[GRID_WIDTH][GRID_HEIGHT];
double accelerationX[GRID_WIDTH][GRID_HEIGHT];
double accelerationY[GRID_WIDTH][GRID_HEIGHT];

// Vertex data structure
struct Point {
    float x, y, z;
    float red, green, blue;
};

Point points[TOTAL_VERTICES];
unsigned int quadIndices[4 * TOTAL_QUADS];

// Initialize vertex positions and colors
void setupGridPoints() {
    for (int row = 0; row < GRID_HEIGHT; ++row) {
        for (int col = 0; col < GRID_WIDTH; ++col) {
            int index = row * GRID_WIDTH + col;

            // Position coordinates normalized to [-1, 1]
            points[index].x = static_cast<float>(col - GRID_WIDTH / 2) / static_cast<float>(GRID_WIDTH / 2);
            points[index].y = static_cast<float>(row - GRID_HEIGHT / 2) / static_cast<float>(GRID_HEIGHT / 2);
            points[index].z = 0.0f;

            // Color generation based on position pattern
            if ((col % 4 < 2) ^ (row % 4 < 2)) {
                points[index].red = 0.0f;
            } else {
                points[index].red = 1.0f;
            }

            points[index].green = static_cast<float>(row) / static_cast<float>(GRID_HEIGHT);
            points[index].blue = 1.0f - (static_cast<float>(col) / static_cast<float>(GRID_WIDTH) + 
                                        static_cast<float>(row) / static_cast<float>(GRID_HEIGHT)) / 2.0f;
        }
    }

    // Setup quad indices
    for (int row = 0; row < NUM_QUADS_Y; ++row) {
        for (int col = 0; col < NUM_QUADS_X; ++col) {
            int baseIndex = 4 * (row * NUM_QUADS_X + col);
            quadIndices[baseIndex + 0] = row * GRID_WIDTH + col;
            quadIndices[baseIndex + 1] = row * GRID_WIDTH + col + 1;
            quadIndices[baseIndex + 2] = (row + 1) * GRID_WIDTH + col + 1;
            quadIndices[baseIndex + 3] = (row + 1) * GRID_WIDTH + col;
        }
    }
}

// Initialize the wave simulation grid
void initializeSimulation() {
    for (int y = 0; y < GRID_HEIGHT; ++y) {
        for (int x = 0; x < GRID_WIDTH; ++x) {
            double dx = static_cast<double>(x - GRID_WIDTH / 2);
            double dy = static_cast<double>(y - GRID_HEIGHT / 2);
            double distance = std::sqrt(dx * dx + dy * dy);

            if (distance < 0.1 * static_cast<double>(GRID_WIDTH / 2)) {
                double normalizedDist = distance * 10.0;
                pressure[x][y] = -std::cos(normalizedDist * M_PI / static_cast<double>(GRID_WIDTH * 4)) * 100.0;
            } else {
                pressure[x][y] = 0.0;
            }

            velocityX[x][y] = 0.0;
            velocityY[x][y] = 0.0;
        }
    }
}

// Update vertex heights based on pressure values
void updateVertexHeights() {
    for (int row = 0; row < GRID_HEIGHT; ++row) {
        for (int col = 0; col < GRID_WIDTH; ++col) {
            int index = row * GRID_WIDTH + col;
            points[index].z = static_cast<float>(pressure[col][row] / 50.0);
        }
    }
}

// Calculate wave propagation using finite difference method
void calculateWavePropagation(double deltaTime) {
    // Compute accelerations from pressure differences
    for (int x = 0; x < GRID_WIDTH; ++x) {
        int nextX = (x + 1) % GRID_WIDTH;
        for (int y = 0; y < GRID_HEIGHT; ++y) {
            accelerationX[x][y] = pressure[x][y] - pressure[nextX][y];
        }
    }

    for (int y = 0; y < GRID_HEIGHT; ++y) {
        int nextY = (y + 1) % GRID_HEIGHT;
        for (int x = 0; x < GRID_WIDTH; ++x) {
            accelerationY[x][y] = pressure[x][y] - pressure[x][nextY];
        }
    }

    // Update velocities using accelerations
    for (int x = 0; x < GRID_WIDTH; ++x) {
        for (int y = 0; y < GRID_HEIGHT; ++y) {
            velocityX[x][y] += accelerationX[x][y] * deltaTime;
            velocityY[x][y] += accelerationY[x][y] * deltaTime;
        }
    }

    // Update pressures using velocity differences
    for (int x = 1; x < GRID_WIDTH; ++x) {
        int prevX = x - 1;
        for (int y = 1; y < GRID_HEIGHT; ++y) {
            int prevY = y - 1;
            pressure[x][y] += (velocityX[prevX][y] - velocityX[x][y] + 
                              velocityY[x][prevY] - velocityY[x][y]) * deltaTime;
        }
    }
}

// Main function demonstrating the wave simulation logic
int main() {
    // Initialize grid geometry
    setupGridPoints();

    // Initialize simulation state
    initializeSimulation();

    // Update vertex heights based on initial pressure
    updateVertexHeights();

    // Simulation time tracking
    double currentTime = 0.01;
    double previousTime = 0.0;
    double timeStep = 0.0;

    // Run simulation loop (simplified version without graphics)
    for (int frame = 0; frame < 100; ++frame) {
        timeStep = currentTime - previousTime;
        previousTime = currentTime;

        // Ensure stable time step for numerical accuracy
        while (timeStep > 0.0) {
            double currentStep = (timeStep > MAX_TIME_STEP) ? MAX_TIME_STEP : timeStep;
            timeStep -= currentStep;

            // Calculate wave propagation
            calculateWavePropagation(currentStep * WAVE_SPEED);
        }

        // Update vertex heights for visualization
        updateVertexHeights();

        // Increment time
        currentTime += 0.016; // Approximate 60 FPS
    }

    std::cout << "Wave simulation completed successfully." << std::endl;
    return 0;
}

