TSharedPtr<SGraphPin> FControlRigGraphPanelPinFactory::CreatePin(UEdGraphPin* InPin) const
{
	if (!InPin)
	{
		return nullptr;
	}

	UControlRigGraphNode* RigNode = Cast<UControlRigGraphNode>(InPin->GetOwningNode());
	if (!RigNode)
	{
		return nullptr;
	}

	UControlRigGraph* RigGraph = Cast<UControlRigGraph>(RigNode->GetGraph());
	if (!RigGraph)
	{
		return nullptr;
	}

	URigVMPin* ModelPin = RigNode->GetModelPinFromPinPath(InPin->GetName());
	if (ModelPin)
	{
		FName widgetName = ModelPin->GetCustomWidgetName();

		// Helper lambda to create name list pin with given getter method
		auto MakeNameListPin = [InPin, ModelPin, RigGraph](TArray<FString> (UControlRigGraph::*Getter)() const) -> TSharedPtr<SGraphPin>
		{
			return SNew(SControlRigGraphPinNameList, InPin)
				.ModelPin(ModelPin)
				.OnGetNameListContent_UObject(RigGraph, Getter);
		};

		if (widgetName == TEXT("BoneName"))
			return MakeNameListPin(&UControlRigGraph::GetBoneNameList);
		else if (widgetName == TEXT("ControlName"))
			return MakeNameListPin(&UControlRigGraph::GetControlNameList);
		else if (widgetName == TEXT("SpaceName"))
			return MakeNameListPin(&UControlRigGraph::GetSpaceNameList);
		else if (widgetName == TEXT("CurveName"))
			return MakeNameListPin(&UControlRigGraph::GetCurveNameList);
		else if (widgetName == TEXT("ElementName"))
			return MakeNameListPin(&UControlRigGraph::GetElementNameList);
		else if (widgetName == TEXT("DrawingName"))
			return MakeNameListPin(&UControlRigGraph::GetDrawingNameList);
		else if (widgetName == TEXT("VariableName"))
			return SNew(SControlRigGraphPinVariableName, InPin);
		else if (widgetName == TEXT("ParameterName"))
			return SNew(SControlRigGraphPinParameterName, InPin);
	}

	// Handle struct-based pins
	if (InPin->PinType.PinCategory == UEdGraphSchema_K2::PC_Struct)
	{
		UStruct* subCategory = Cast<UStruct>(InPin->PinType.PinSubCategoryObject);
		if (subCategory && subCategory->IsChildOf(FRigVMExecuteContext::StaticStruct()))
		{
			return SNew(SGraphPinExec, InPin);
		}
		else if (InPin->PinType.PinSubCategoryObject == FRuntimeFloatCurve::StaticStruct())
		{
			return SNew(SControlRigGraphPinCurveFloat, InPin);
		}
	}

	// Fallback to default K2 pin creation
	TSharedPtr<SGraphPin> fallbackPin = FNodeFactory::CreateK2PinWidget(InPin);
	return fallbackPin.IsValid() ? fallbackPin : nullptr;
}

