void UnitTests::UdpPingTest() {
  auto localConnection =
      MavLinkConnection::connectLocalUdp("jMavSim", "127.0.0.1", 14588);
  Semaphore received;
  auto id = localConnection->subscribe(
      [&](std::shared_ptr<MavLinkConnection> connection,
          const MavLinkMessage& msg) {
        printf("    Received message %d\n", msg.msgid);
        received.post();
      });

  auto remoteConnection = MavLinkConnection::connectRemoteUdp(
      "jMavSim", "127.0.0.1", "127.0.0.1", 14588);

  MavLinkHeartbeat hb;
  hb.autopilot = 0;
  hb.base_mode = 0;
  hb.custom_mode = 0;
  hb.mavlink_version = 3;
  hb.system_status = 1;
  hb.type = 1;

  auto node = std::make_shared<MavLinkNode>(166, 1);
  node->connect(remoteConnection);
  node->sendMessage(hb);

  if (!received.timed_wait(2000)) {
    throw std::runtime_error("heartbeat not received after 2 seconds");
  }

  localConnection->unsubscribe(id);
  localConnection->close();
  remoteConnection->close();
  node->close();
}

void UnitTests::TcpPingTest() {
  const int testPort = 45166;
  std::shared_ptr<MavLinkTcpServer> server =
      std::make_shared<MavLinkTcpServer>("127.0.0.1", testPort);

  std::future<int> future = std::async(std::launch::async, [=] {
    std::shared_ptr<MavLinkConnection> con = server->acceptTcp("test");
    std::shared_ptr<MavLinkNode> serverNode =
        std::make_shared<MavLinkNode>(1, 1);
    serverNode->connect(con);

    MavLinkHeartbeat hb;
    hb.autopilot = 0;
    hb.base_mode = 0;
    hb.custom_mode = 0;
    hb.mavlink_version = 3;
    hb.system_status = 1;
    hb.type = 1;
    serverNode->sendMessage(hb);
    return 0;
  });

  Semaphore received;
  auto client = MavLinkConnection::connectTcp("local", "127.0.0.1", "127.0.0.1",
                                              testPort);
  client->subscribe([&](std::shared_ptr<MavLinkConnection> connection,
                        const MavLinkMessage& msg) {
    printf("Received msg %d\n", msg.msgid);
    received.post();
  });

  if (!received.timed_wait(2000)) {
    throw std::runtime_error("heartbeat not received from server");
  }

  client->close();
}

void UnitTests::SerialPx4Test() {
  auto connection =
      MavLinkConnection::connectSerial("px4", com_port_, baud_rate_);
  int count = 0;
  Semaphore received;
  auto id = connection->subscribe(
      [&](std::shared_ptr<MavLinkConnection> con, const MavLinkMessage& msg) {
        count++;
        if (msg.msgid == 0) {
