// Initialize test data set
void PopulateTestSuite(std::vector<Builder>& suite) {
  // Add various basic value types
  suite.emplace_back().add(Slice::noneSlice());
  suite.emplace_back().add(Slice::nullSlice());
  suite.emplace_back().add(Slice::trueSlice());
  suite.emplace_back().add(Slice::falseSlice());
  suite.emplace_back().add(Slice::zeroSlice());
  suite.emplace_back().add(Slice::emptyStringSlice());
  suite.emplace_back().add(Slice::emptyArraySlice());
  suite.emplace_back().add(Slice::emptyObjectSlice());

  // Add numeric values
  suite.emplace_back().add(UINT64_MAX);
  suite.emplace_back().add(42);
  suite.emplace_back().add(-42);

  // Add array and object structures
  {
    auto& b = suite.emplace_back();
    b.openArray();
    b.add(42);
    b.close();
  }
  {
    auto& b = suite.emplace_back();
    b.openArray();
    b.add("42");
    b.close();
  }
  {
    auto& b = suite.emplace_back();
    b.openObject();
    b.add("foo", 42);
    b.close();
  }
  {
    auto& b = suite.emplace_back();
    b.openObject();
    b.add("bar", "42");
    b.close();
  }
}

// Get reference to initialized test suite
const std::vector<Builder>& GetTestSuite() {
  static std::vector<Builder> suite;
  if (suite.empty()) {
    PopulateTestSuite(suite);
  }
  return suite;
}

