// Wrapper to capture either result or exception from operations
template<typename T>
class Outcome {
public:
  template<typename Func>
  Outcome(Func&& func) {
    try {
      value.template emplace<T>(std::forward<Func>(func)());
    } catch (const Exception& e) {
      value.template emplace<Exception>(e);
    }
  }

  template<typename U>
  bool operator==(const Outcome<U>& other) const {
    constexpr bool leftIsSlice = std::is_same_v<Slice, std::decay_t<T>>;
    constexpr bool rightIsShared = false; // Simplified for this example

    if (value.index() != other.value.index()) {
      return false;
    }

    switch (value.index()) {
      case 0: {
        const auto& l = std::get<0>(value);
        const auto& r = std::get<0>(other.value);
        if constexpr (leftIsSlice && !rightIsShared) {
          return l.start() == r.buffer().get();
        } else {
          return l == r;
        }
      }
      case 1: {
        const auto& le = std::get<1>(value);
        const auto& re = std::get<1>(other.value);
        return le.errorCode() == re.errorCode();
      }
      default:
        throw std::runtime_error("Invalid variant state");
    }
  }

  friend std::ostream& operator<<(std::ostream& os, const Outcome& o) {
    switch (o.value.index()) {
      case 0: 
        return os << ::testing::PrintToString(std::get<0>(o.value));
      case 1: 
        return os << std::get<1>(o.value);
      default:
        throw std::runtime_error("Invalid variant state");
    }
  }

  std::variant<T, Exception> value;
};

// Helper macro to wrap expressions in Outcome
#define OUTCOME(expr) Outcome([&]() { return expr; }())

// Compare two outcomes for equality
#define VERIFY_OUTCOMES(left_expr, right_expr) \
  do { \
    auto l = OUTCOME(left_expr); \
    auto r = OUTCOME(right_expr); \
    ASSERT_EQ(l, r); \
  } while (false)

// Test framework for comparing Slice vs SharedSlice behavior
template<typename Callback>
void RunSliceTests(Callback&& callback) {
  for (const auto& builder : GetTestSuite()) {
    ASSERT_TRUE(builder.isClosed());

    Slice slice = builder.slice();
    SharedSlice shared = builder.sharedSlice();

    // Verify slices represent same data
    ASSERT_EQ(slice.byteSize(), shared.slice().byteSize());
    ASSERT_EQ(0, memcmp(slice.start(), shared.slice().start(), slice.byteSize()));

    // Make both point to same memory location
    slice = shared.slice();
    ASSERT_EQ(slice.start(), shared.slice().start());

    // Set up test context with descriptive message
    std::string desc = "Testing slice: " + DescribeSlice(slice);
    SCOPED_TRACE(desc.c_str());

    callback(slice, shared);
  }
}

// Test framework for refcount-specific scenarios
template<typename Callback>
void RunRefcountTests(Callback&& callback) {
  for (const auto& builder : GetTestSuite()) {
    Buffer buffer = builder.bufferRef();
    ASSERT_TRUE(builder.isClosed());

    SharedSlice shared{std::move(buffer)};
    ASSERT_EQ(1, shared.buffer().use_count());

    std::string desc = "Testing slice: " + DescribeSlice(shared.slice());
    SCOPED_TRACE(desc.c_str());

    callback(std::move(shared));
  }
}

// Basic comparison tests
TEST(SharedSliceComparisonTest, StartPointers) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.start(), sh.start().get());
  });
}

TEST(SharedSliceComparisonTest, HeadOperations) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.head(), sh.head());
  });
}

TEST(SharedSliceComparisonTest, BeginEndIterators) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.begin(), sh.begin().get());
    VERIFY_OUTCOMES(s.end(), sh.end().get());
  });
}

TEST(SharedSliceComparisonTest, TypeInformation) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    ASSERT_EQ(s.type(), sh.type());
    ASSERT_EQ(s.typeName(), sh.typeName());
  });
}

TEST(SharedSliceComparisonTest, HashFunctions) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    ASSERT_EQ(s.volatileHash(), sh.volatileHash());
    ASSERT_EQ(s.hash(), sh.hash());
    ASSERT_EQ(s.hashSlow(), sh.hashSlow());
  });
}

TEST(SharedSliceComparisonTest, StringOperations) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    if (s.isString()) {
      ASSERT_EQ(s.hashString(), sh.hashString());
    }
  });
}

TEST(SharedSliceComparisonTest, TypeChecks) {
  const std::vector<ValueType> types = {
    ValueType::None, ValueType::Null, ValueType::Bool,
    ValueType::Array, ValueType::Object, ValueType::Double,
    ValueType::Int, ValueType::UInt, ValueType::SmallInt, ValueType::String
  };

  RunSliceTests([&types](Slice s, SharedSlice sh) {
    for (auto type : types) {
      SCOPED_TRACE("Checking type: " + std::string(valueTypeName(type)));
      ASSERT_EQ(s.type() == type, sh.type() == type);
    }
  });
}

TEST(SharedSliceComparisonTest, ValueAccessors) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.getBool(), sh.getBool());
    VERIFY_OUTCOMES(s.getDouble(), sh.getDouble());
    VERIFY_OUTCOMES(s.getInt(), sh.getInt());
    VERIFY_OUTCOMES(s.getUInt(), sh.getUInt());
  });
}

TEST(SharedSliceComparisonTest, ArrayAccess) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    if (!s.isEmptyArray()) {
      VERIFY_OUTCOMES(s.at(0), sh.at(0));
    }
  });
}

TEST(SharedSliceComparisonTest, ObjectAccess) {
  using namespace std::string_literals;
  std::vector<std::string> keys = {"foo", "bar"};

  RunSliceTests([&keys](Slice s, SharedSlice sh) {
    for (const auto& key : keys) {
      VERIFY_OUTCOMES(s.get(key), sh.get(key));
      VERIFY_OUTCOMES(s.hasKey(key), !sh.get(key).isNone());
    }
  });
}

TEST(SharedSliceComparisonTest, SizeAndLength) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.byteSize(), sh.byteSize());
    VERIFY_OUTCOMES(s.length(), sh.length());
  });
}

TEST(SharedSliceComparisonTest, StringComparisons) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.compareString("42"), sh.compareString("42"));
    VERIFY_OUTCOMES(s.isEqualString("42"), sh.isEqualString("42"));
  });
}

TEST(SharedSliceComparisonTest, Serialization) {
  RunSliceTests([](Slice s, SharedSlice sh) {
    VERIFY_OUTCOMES(s.toJson(), sh.toJson());
    VERIFY_OUTCOMES(s.toString(), sh.toString());
  });
}

// Refcount-specific tests
TEST(SharedSliceRefcountTest, InitialState) {
  std::shared_ptr<const uint8_t> empty;
  SharedSlice s{empty};
  ASSERT_TRUE(s.isNone());
}

TEST(SharedSliceRefcountTest, FromEmptyBuilder) {
  Builder b;
  SharedSlice s = std::move(b).sharedSlice();
  ASSERT_TRUE(s.isNone());
}

TEST(SharedSliceRefcountTest, FromOpenBuilder) {
  Builder b;
  b.openObject();
  SharedSlice s;
  ASSERT_VPACK_EXCEPTION(s = std::move(b).sharedSlice(),
                        Exception::kBuilderNotSealed);
}

TEST(SharedSliceRefcountTest, CopySemantics) {
  RunRefcountTests([](SharedSlice&& ref) {
    ASSERT_EQ(1, ref.buffer().use_count());

    SharedSlice copy(ref);
    ASSERT_GE(2, ref.buffer().use_count());
    ASSERT_GE(2, copy.buffer().use_count());
    ASSERT_EQ(ref.buffer(), copy.buffer());
  });
}

TEST(SharedSliceRefcountTest, MoveSemantics) {
  RunRefcountTests([](SharedSlice&& ref) {
    auto original_ptr = ref.buffer().get();

    SharedSlice moved(std::move(ref));
    ASSERT_TRUE(ref.isNone());
    ASSERT_EQ(original_ptr, moved.buffer().get());
    ASSERT_EQ(1, moved.buffer().use_count());
  });
}

#include "string_util.h"
