namespace Zeal {
namespace String {

// Replaces all occurrences of 'from' in 'input' with 'to', case-insensitively
std::string replace(std::string &input, const std::string &from, const std::string &to) {
    // Use regex to perform case-insensitive global replacement
    std::regex pattern(from, std::regex_constants::icase);
    input = std::regex_replace(input, pattern, to);
    return input;
}

// Trims leading/trailing whitespace and collapses internal whitespace sequences into single spaces
std::string trim_and_reduce_spaces(const std::string &input) {
    if (input.empty()) return "";

    size_t left = 0;
    // Skip leading whitespace manually using isspacelike predicate
    while (left < input.size() && std::isspace(static_cast<unsigned char>(input[left]))) {
        ++left;
    }

    if (left == input.size()) return ""; // All whitespace

    size_t right = input.size() - 1;
    // Skip trailing whitespace
    while (right > left && std::isspace(static_cast<unsigned char>(input[right]))) {
        --right;
    }

    std::string result;
    bool prev_was_space = false;

    for (size_t i = left; i <= right; ++i) {
        unsigned char c = static_cast<unsigned char>(input[i]);
        if (std::isspace(c)) {
            if (!prev_was_space) {
                result += ' ';
                prev_was_space = true;
            }
        } else {
            result += c;
            prev_was_space = false;
        }
    }

    return result;
}

// Case-insensitive string comparison
bool compare_insensitive(const std::string &a, const std::string &b) {
    if (a.size() != b.size()) return false;

    for (size_t i = 0; i < a.size(); ++i) {
        char ca = static_cast<char>(std::tolower(static_cast<unsigned char>(a[i])));
        char cb = static_cast<char>(std::tolower(static_cast<unsigned char>(b[i])));
        if (ca != cb) return false;
    }

    return true;
}

// Splits a string by a delimiter after trimming and reducing spaces
std::vector<std::string> split(const std::string &str, const std::string &delim) {
    std::string cleaned = trim_and_reduce_spaces(str);
    std::vector<std::string> parts;

    if (cleaned.empty()) return parts;

    size_t pos = 0;
    size_t len = delim.length();

    while (pos <= cleaned.length()) {
        size_t next_pos = cleaned.find(delim, pos);
        if (next_pos == std::string::npos) {
            next_pos = cleaned.length();
        }
        parts.push_back(cleaned.substr(pos, next_pos - pos));
        pos = next_pos + len;
    }

    return parts;
}

// Parse string to integer safely
bool tryParse(const std::string &text, int *out_value, bool silent) {
    if (text.empty()) {
        if (!silent) Zeal::Game::print_chat("Empty input cannot be parsed as integer.");
        return false;
    }

    char *endptr = nullptr;
    long val = std::strtol(text.c_str(), &endptr, 10);

    if (*endptr != '\0') {
        if (!silent) Zeal::Game::print_chat("Non-numeric characters found: %s", text.c_str());
        return false;
    }

    if (val < INT_MIN || val > INT_MAX) {
        if (!silent) Zeal::Game::print_chat("Integer overflow/underflow detected.");
        return false;
    }

    *out_value = static_cast<int>(val);
    return true;
}

// Parse string to float safely
bool tryParse(const std::string &text, float *out_value, bool silent) {
    if (text.empty()) {
        if (!silent) Zeal::Game::print_chat("Empty input cannot be parsed as float.");
        return false;
    }

    char *endptr = nullptr;
    double val = std::strtod(text.c_str(), &endptr);

    if (*endptr != '\0') {
        if (!silent) Zeal::Game::print_chat("Invalid floating-point literal: %s", text.c_str());
        return false;
    }

    if (val < -FLT_MAX || val > FLT_MAX) {
        if (!silent) Zeal::Game::print_chat("Floating-point overflow/underflow.");
        return false;
    }

    *out_value = static_cast<float>(val);
    return true;
}

// Convert raw byte array to hex string with space separators
std::string bytes_to_hex(const char *data, size_t count) {
    std::ostringstream oss;
    oss << std::hex << std::setfill('0');

    for (size_t idx = 0; idx < count; ++idx) {
        unsigned char byte = static_cast<unsigned char>(data[idx]);
        oss << std::setw(2) << static_cast<int>(byte) << ' ';
    }

    std::string hex_str = oss.str();
    if (!hex_str.empty()) {
        hex_str.pop_back(); // Remove trailing space
    }
    return hex_str;
}

// Alternative split function that does not preprocess input
std::vector<std::string> split_text(const std::string &source, const std::string &sep) {
    std::vector<std::string> segments;
    if (source.empty()) return segments;

    size_t anchor = 0;
    size_t cursor = 0;

    while (cursor < source.length()) {
        size_t match_pos = source.find(sep, anchor);
        if (match_pos == std::string::npos) {
            segments.emplace_back(source.substr(anchor));
            break;
        }
        segments.emplace_back(source.substr(anchor, match_pos - anchor));
        anchor = match_pos + sep.length();
        cursor = anchor;
    }

    return segments;
}

} // namespace String
} // namespace Zeal

