// Helper: determine if any condition requires veins
bool requires_veins(const GalaxyCondition& config) {
    if (config.need_veins) return true;

    for (const auto& star : config.stars) {
        if (star.need_veins) return true;
        for (const auto& planet : star.planets) {
            if (planet.need_veins) return true;
        }
    }

    for (const auto& planet : config.planets) {
        if (planet.need_veins) return true;
    }

    return false;
}

// Helper: determine if any condition involves planets
bool requires_planets(const GalaxyCondition& config) {
    for (const auto& star : config.stars) {
        if (!star.planets.empty()) return true;
    }
    return !config.planets.empty();
}

// Determine required validation level based on conditions and speed preference
int compute_validation_level(const GalaxyCondition& config, bool prefer_speed) {
    if (requires_veins(config)) {
        return prefer_speed ? 3 : 4;
    } else {
        return requires_planets(config) ? 2 : 1;
    }
}

// Batch checking implementation using range-based loops and emplace_back
std::vector<std::string> validate_seeds_in_range(
    int seed_start, int seed_end,
    int star_start, int star_end,
    const GalaxyCondition& config,
    int level) {

    std::vector<std::string> matches;
    for (int s = seed_start; s < seed_end; ++s) {
        for (int n = star_start; n < star_end; ++n) {
            if (check_seed_level_1(s, n, config, level)) {
                matches.emplace_back(std::to_string(s) + "," + std::to_string(n));
            }
        }
    }
    return matches;
}

// Precise checking: iterate over paired vectors
std::vector<std::string> validate_precise_pairs(
    const std::vector<int>& seeds,
    const std::vector<int>& stars,
    const GalaxyCondition& config,
    int level) {

    std::vector<std::string> results;
    for (size_t idx = 0; idx < seeds.size(); ++idx) {
        int seed_val = seeds[idx];
        int star_val = stars[idx];
        if (check_seed_level_1(seed_val, star_val, config, level)) {
            results.emplace_back(std::to_string(seed_val) + "," + std::to_string(star_val));
        }
    }
    return results;
}

// Python-exposed batch validation wrapper
std::vector<std::string> validate_batch_py(
    int start_seed, int end_seed,
    int start_star_num, int end_star_num,
    const py::dict& condition_dict,
    bool quick_mode) {

    GalaxyCondition galaxy_config = galaxy_condition_to_struct(condition_dict);
    int lvl = compute_validation_level(galaxy_config, quick_mode);
    return validate_seeds_in_range(start_seed, end_seed, start_star_num, end_star_num, galaxy_config, lvl);
}

// Python-exposed precise validation wrapper
std::vector<std::string> validate_precise_py(
    const std::vector<int>& seed_list,
    const std::vector<int>& star_list,
    const py::dict& condition_dict,
    bool quick_mode) {

    GalaxyCondition galaxy_config = galaxy_condition_to_struct(condition_dict);
    int lvl = compute_validation_level(galaxy_config, quick_mode);
    return validate_precise_pairs(seed_list, star_list, galaxy_config, lvl);
}

