static int double_setter(void *struct_ptr, csv_value_t value) {
  double *double_ptr = (double *)struct_ptr;
  if (double_ptr == NULL || value.type != double_type) {
    return CSV_ERROR;
  }
  *double_ptr = value.data.double_value;
  return CSV_OK;
}

