        const char* msg;
    };
    static const ErrorMsg error_msgs[] = {
        {NDB_MGM_NO_ERROR, "No error"},
        {NDB_MGM_ILLEGAL_CONNECT_STRING, "Illegal connect string"},
        {NDB_MGM_ILLEGAL_BIND_ADDRESS, "Illegal bind address"},
