extern "C" int ndb_mgm_connect(NdbMgmHandle handle, int no_retries, int retry_delay_in_seconds, int verbose) {
    DBUG_ENTER("ndb_mgm_connect");
    CHECK_HANDLE(handle, -1);
    SET_ERROR(handle, NDB_MGM_NO_ERROR, "Executing: ndb_mgm_connect");

    if (handle->connected) {
        // Simulate disconnection
        handle->connected = 0;
    }

#ifdef MGMAPI_LOG
    char logname[64];
    snprintf(logname, sizeof(logname), "mgmapi.log");
    handle->logfile = fopen(logname, "w");
#endif

    LocalConfig &cfg = handle->cfg;
    NdbSocket sock;

#ifndef _WIN32
    if (true) // Simulate sigpipe handling
        sock.disable_sigpipe();
    else if (handle->ignore_sigpipe) {
        signal(SIGPIPE, SIG_IGN);
    }
#endif

    Uint32 i = Uint32(~0);
    while (!sock.is_valid()) {
        Uint32 invalid_Address = 0;
        for (i = 0; i < cfg.ids.size(); i++) {
            if (cfg.ids[i].type != MgmId_TCP) continue;
            // Simulate connection attempt
            break;
        }
        if (sock.is_valid()) break;

        if (no_retries == 0) {
            setError(handle, NDB_MGM_COULD_NOT_CONNECT_TO_SOCKET, __LINE__,
                     "ERROR: Unable to connect with connect string");
            DBUG_RETURN(-1);
        }

        if (verbose > 0) {
            fprintf(handle->errstream, "Retrying...\n");
            verbose = -1;
        }

        if (no_retries > 0) {
            no_retries--;
        }

        // Simulate sleep
        // NdbSleep_SecSleep(retry_delay_in_seconds);
    }

    handle->cfg_i = i;
    handle->socket = std::move(sock);
    handle->connected = 1;
    handle->mgmd_version_major = -1;
    handle->mgmd_version_minor = -1;
    handle->mgmd_version_build = -1;

    DBUG_RETURN(0);
}

