extern "C" struct ndb_mgm_cluster_state *ndb_mgm_get_status2(NdbMgmHandle handle, const enum ndb_mgm_node_type types[]) {
    DBUG_ENTER("ndb_mgm_get_status2");
    CHECK_HANDLE(handle, nullptr);
    SET_ERROR(handle, NDB_MGM_NO_ERROR, "Executing: ndb_mgm_get_status");
    CHECK_CONNECTED(handle, nullptr);

    // Simulate version check
    if (!get_mgmd_version(handle)) DBUG_RETURN(nullptr);

    char typestring[1024];
    typestring[0] = '\0';

    if (types != nullptr) {
        int pos = 0;
        for (Uint32 i = 0; types[i] != NDB_MGM_NODE_TYPE_UNKNOWN; i++) {
            if (int(types[i]) < NDB_MGM_NODE_TYPE_MIN ||
                int(types[i]) > NDB_MGM_NODE_TYPE_MAX) {
                SET_ERROR(handle, EINVAL,
                          "Incorrect node type for ndb_mgm_get_status2");
                DBUG_RETURN(nullptr);
            }

            for (Int32 j = i - 1; j >= 0; j--) {
                if (types[i] == types[j]) {
                    SET_ERROR(handle, EINVAL, "Duplicate types for ndb_mgm_get_status2");
                    DBUG_RETURN(nullptr);
                }
            }

            int left = sizeof(typestring) - pos;
            int len = snprintf(typestring + pos, left, "%s ",
                               ndb_mgm_get_node_type_string(types[i]));
            if (len >= left) {
                SET_ERROR(handle, EINVAL,
                          "Out of memory for type-string for ndb_mgm_get_status2");
                DBUG_RETURN(nullptr);
            }
            pos += len;
        }
    }

    SocketOutputStream out(handle->socket, handle->timeout);
    SocketInputStream in(handle->socket, handle->timeout);
    const char *get_status_str = "get status";
    out.println("%s", get_status_str);
    if (types) {
        out.println("types: %s", typestring);
    }
    out.println("%s", "");

    CHECK_TIMEDOUT_RET(handle, in, out, nullptr, get_status_str);

    char buf[1024];
    if (!in.gets(buf, sizeof(buf))) {
        CHECK_TIMEDOUT_RET(handle, in, out, nullptr, get_status_str);
        SET_ERROR(handle, NDB_MGM_ILLEGAL_SERVER_REPLY, "Probably disconnected");
        DBUG_RETURN(nullptr);
    }

    if (strcmp(buf, "OK") != 0) {
        DBUG_RETURN(nullptr);
    }

    DBUG_RETURN(nullptr); // Placeholder
}

#include <sycl/sycl.hpp>
#include "../utils.h"
#include "../dispatch_utils.h"

#define MAX_VAL(x, y) ((x) > (y) ? (x) : (y))
#define MIN_VAL(x, y) ((x) < (y) ? (x) : (y))

static constexpr int warp_size = 32;

namespace vllm {
namespace moe {

// ====================== Softmax Implementation ===============================
template <int threads_per_block, typename InputType>
class moeSoftmaxKernel {
 public:
  moeSoftmaxKernel(
      sycl::local_accessor<float, 1>& shared_mem,
      const InputType* input_data,
      const bool* row_mask,
      float* output_data,
      const int cols)
      : slm(shared_mem),
        input(input_data),
        finished(row_mask),
        output(output_data),
        num_cols(cols) {}

  void operator()
      [[sycl::reqd_sub_group_size(warp_size)]] (sycl::nd_item<1> item) const {
    void* slm_ptr = static_cast<void*>(
        slm.template get_multi_ptr<sycl::access::decorated::no>().get());
    float* normalization_const = reinterpret_cast<float*>(slm_ptr);
    float* max_val_buffer = normalization_const + 1;

    auto group = item.get_group();
    auto local_id = item.get_local_id(0);
    auto group_id = item.get_group(0);

    const int row_offset = group_id * num_cols;
    float local_max = -INFINITY;

    if ((finished != nullptr) && finished[group_id]) {
      return;
    }

    // Find maximum value in row
    for (int col = local_id; col < num_cols; col += threads_per_block) {
      int idx = row_offset + col;
      local_max = MAX_VAL(local_max, static_cast<float>(input[idx]));
    }

    float global_max = sycl::reduce_over_group(group, local_max, sycl::maximum<float>());
    if (local_id == 0) {
      *max_val_buffer = global_max;
    }
    item.barrier(sycl::access::fence_space::local_space);

    // Compute sum of exponentials
    float local_sum = 0.0f;
    for (int col = local_id; col < num_cols; col += threads_per_block) {
      int idx = row_offset + col;
      float diff = static_cast<float>(input[idx]) - *max_val_buffer;
      local_sum += sycl::exp(diff);
    }

    float total_sum = sycl::reduce_over_group(group, local_sum, sycl::plus<>());
    if (local_id == 0) {
      *normalization_const = 1.0f / total_sum;
    }
    item.barrier(sycl::access::fence_space::local_space);

    // Final softmax computation and write back
    for (int col = local_id; col < num_cols; col += threads_per_block) {
      int idx = row_offset + col;
      float val = sycl::exp(static_cast<float>(input[idx]) - (*max_val_buffer)) * (*normalization_const);
      output[idx] = val;
    }
  }

 private:
  sycl::local_accessor<float, 1> slm;
  const InputType* input;
  const bool* finished;
  float* output;
  const int num_cols;
};

// ====================== Top-K Selection ===============================
template <int threads_per_block, typename IndexType>
class moeTopKKernel {
 public:
  moeTopKKernel(
      const float* after_softmax,
      const bool* active_rows,
      float* topk_vals,
      IndexType* expert_indices,
      int* token_positions,
      const int experts_count,
      const int k_select,
      const int first_expert,
      const int last_expert,
      const bool do_renorm)
      : inputs(after_softmax),
        finished(active_rows),
        output(topk_vals),
        indices(expert_indices),
        src_rows(token_positions),
        num_experts(experts_count),
        k(k_select),
        start_idx(first_expert),
        end_idx(last_expert),
        renormalize(do_renorm) {}

  void operator()
      [[sycl::reqd_sub_group_size(warp_size)]] (sycl::nd_item<1> item) const {
    auto group = item.get_group();
    auto local_id = item.get_local_id(0);
    auto group_id = item.get_group(0);
    const int rows_total = item.get_group_range(0);
    const int current_row = group_id;
    const bool row_active = finished ? !finished[current_row] : true;
    const int row_base = current_row * num_experts;
    float running_sum = 0.0f;

    for (int pos = 0; pos < k; ++pos) {
      int best_idx = 0;
      float best_val = -1.0f;
      int candidate_idx;
      float candidate_val;

      for (int expert = local_id; expert < num_experts; expert += threads_per_block) {
        int idx = row_base + expert;
        candidate_idx = expert;
        candidate_val = inputs[idx];

        // Check against previously selected experts
        for (int prev = 0; prev < pos; ++prev) {
          int prev_selected = indices[k * current_row + prev];
          if (prev_selected == expert) {
            candidate_idx = best_idx;
            candidate_val = best_val;
          }
        }

        if (candidate_val > best_val) {
          best_idx = candidate_idx;
          best_val = candidate_val;
        }
      }

      float local_best = sycl::reduce_over_group(group, best_val, sycl::maximum<float>());
      int winning_expert = sycl::reduce_over_group(
          group, local_best == best_val ? best_idx : 0x7FFFFFFF, sycl::minimum<int>());

      running_sum += local_best;

      if (local_id == 0) {
        const bool node_uses_expert = winning_expert >= start_idx && winning_expert < end_idx;
        const bool should_process = row_active && node_uses_expert;
        int out_idx = k * current_row + pos;
        output[out_idx] = local_best;
        indices[out_idx] = should_process ? (winning_expert - start_idx) : num_experts;
        src_rows[out_idx] = pos * rows_total + current_row;
      }
      item.barrier(sycl::access::fence_space::local_space);
    }

    if (renormalize) {
      auto local_range = item.get_local_range(0);
      for (int pos = local_id; pos < k; pos += local_range) {
        int idx = k * current_row + pos;
        output[idx] /= running_sum;
      }
    }
  }

 private:
  const float* inputs;
  const bool* finished;
  float* output;
  IndexType* indices;
  int* src_rows;
  const int num_experts;
  const int k;
  const int start_idx;
  const int end_idx;
  const bool renormalize;
};

// ====================== Optimized Top-K Softmax for Power-of-2 Experts ===============================
template <
    int vecs_per_thread,
    int num_experts,
    int warps_per_cta,
    int bytes_per_load,
    int warp_size_param,
    typename InputType,
    typename IndexType>
class topkGatingSoftmaxKernel {
 public:
  topkGatingSoftmaxKernel(
      const InputType* input_data,
      const bool* row_mask,
      float* output_data,
      const int total_rows,
      IndexType* expert_indices,
      int* token_positions,
      const int k_select,
      const int first_expert,
      const int last_expert,
      const bool do_renorm)
      : input(input_data),
        finished(row_mask),
        output(output_data),
        num_rows(total_rows),
        indices(expert_indices),
        src_rows(token_positions),
        k(k_select),
        start_expert(first_expert),
        end_expert(last_expert),
        renormalize(do_renorm) {}

  void operator()
      [[sycl::reqd_sub_group_size(warp_size)]] (sycl::nd_item<2> item) const {
    auto sg = item.get_sub_group();
    auto lid_y = item.get_local_id(0);
    auto lid_x = item.get_local_id(1);
    auto gid_x = item.get_group(1);

    static_assert(
        (bytes_per_load & (bytes_per_load - 1)) == 0,
        "bytes_per_load must be power of 2");
    static_assert(bytes_per_load <= 16, "bytes_per_load must be <= 16");

    constexpr int elements_per_load = bytes_per_load / sizeof(InputType);
    constexpr int elements_per_row = num_experts;
    constexpr int threads_per_row = elements_per_row / vecs_per_thread;
    constexpr int loads_per_thread = vecs_per_thread / elements_per_load;

    static_assert(
        vecs_per_thread % elements_per_load == 0,
        "vecs_per_thread must be multiple of elements_per_load");
    static_assert(
        threads_per_row <= warp_size_param,
        "threads_per_row cannot exceed warp size");
    static_assert(
        (threads_per_row & (threads_per_row - 1)) == 0,
        "threads_per_row must be power of 2");

    constexpr int elements_per_warp = warp_size_param * vecs_per_thread;
    constexpr int rows_per_warp = elements_per_warp / elements_per_row;
    constexpr int rows_per_cta = warps_per_cta * rows_per_warp;

    const int cta_first_row = gid_x * rows_per_cta;
    const int warp_first_row = cta_first_row + lid_y * rows_per_warp;
    const int thread_row_in_warp = lid_x / threads_per_row;
    const int actual_row = warp_first_row + thread_row_in_warp;

    if (actual_row >= num_rows) return;

    const bool active_row = finished ? !finished[actual_row] : true;
    const InputType* row_ptr = input + actual_row * elements_per_row;
    const int group_idx = lid_x % threads_per_row;
    const int start_col = group_idx * elements_per_load;
    const InputType* load_ptr = row_ptr + start_col;

    InputType loaded_chunk[vecs_per_thread];
#pragma unroll
    for (int i = 0; i < loads_per_thread; ++i) {
#pragma unroll
      for (int j = 0; j < elements_per_load; ++j) {
        loaded_chunk[i * elements_per_load + j] =
            load_ptr[i * threads_per_row * elements_per_load + j];
      }
    }

    float chunk_float[vecs_per_thread];
#pragma unroll
    for (int i = 0; i < vecs_per_thread; ++i) {
      chunk_float[i] = static_cast<float>(loaded_chunk[i]);
    }

    float local_max = chunk_float[0];
#pragma unroll
    for (int i = 1; i < vecs_per_thread; ++i) {
      local_max = MAX_VAL(local_max, chunk_float[i]);
    }

#pragma unroll
    for (int mask = threads_per_row / 2; mask > 0; mask /= 2) {
      float other_max = sycl::permute_group_by_xor(sg, local_max, mask);
      local_max = MAX_VAL(local_max, other_max);
    }

    float local_sum = 0.0f;
#pragma unroll
    for (int i = 0; i < vecs_per_thread; ++i) {
      chunk_float[i] = sycl::exp(chunk_float[i] - local_max);
      local_sum += chunk_float[i];
    }

#pragma unroll
    for (int mask = threads_per_row / 2; mask > 0; mask /= 2) {
      local_sum += sycl::permute_group_by_xor(sg, local_sum, mask);
    }

    const float inv_sum = 1.0f / local_sum;
#pragma unroll
    for (int i = 0; i < vecs_per_thread; ++i) {
      chunk_float[i] *= inv_sum;
    }

    float running_sum = 0.0f;
    int start_pos = start_col;
    constexpr int cols_per_load = elements_per_load * threads_per_row;

    for (int k_idx = 0; k_idx < k; ++k_idx) {
      float max_val = chunk_float[0];
      int expert_pos = start_pos;
      int max_idx = 0;

#pragma unroll
      for (int ld = 0, col = start_pos; ld < loads_per_thread; ++ld, col += cols_per_load) {
#pragma unroll
        for (int i = 0; i < elements_per_load; ++i) {
          float val = chunk_float[ld * elements_per_load + i];
          if (val > max_val) {
            max_val = val;
            expert_pos = col + i;
            max_idx = ld * elements_per_load + i;
          }
        }
      }

      int expert_global = expert_pos;
#pragma unroll
      for (int mask = threads_per_row / 2; mask > 0; mask /= 2) {
        float other_max = sycl::permute_group_by_xor(sg, max_val, mask);
        int other_expert = sycl::permute_group_by_xor(sg, expert_global, mask);
        if (other_max > max_val ||
            (other_max == max_val && other_expert < expert_global)) {
          max_val = other_max;
          expert_global = other_expert;
        }
      }

      running_sum += max_val;

      if (group_idx == 0) {
        const bool node_uses_expert = expert_global >= start_expert && expert_global < end_expert;
        const bool process_row = active_row && node_uses_expert;
        int out_idx = k * actual_row + k_idx;
        output[out_idx] = max_val;
        indices[out_idx] = process_row ? (expert_global - start_expert) : num_experts;
        src_rows[out_idx] = k_idx * num_rows + actual_row;
      }

      if (expert_global == expert_pos) {
        chunk_float[max_idx] = -10000.0f;
      }
    }

    if (renormalize) {
      for (int k_idx = group_idx; k_idx < k; k_idx += threads_per_row) {
        int idx = k * actual_row + k_idx;
        output[idx] /= running_sum;
      }
    }
  }

 private:
  const InputType* input;
  const bool* finished;
  float* output;
  const int num_rows;
  IndexType* indices;
  int* src_rows;
  const int k;
  const int start_expert;
  const int end_expert;
  const bool renormalize;
};

namespace detail {
template <
    int experts,
    int bytes_per_load,
    int warp_size_param,
    typename InputType>
struct TopkCompileTimeConstants {
  static constexpr int elts_per_load = bytes_per_load / sizeof(InputType);
  static_assert(
      (experts % (elts_per_load * warp_size_param) == 0) ||
      (experts / (elts_per_load * warp_size_param) == 0),
      "");

  static constexpr int vecs_per_thread =
      MAX_VAL(1, experts / (elts_per_load * warp_size_param));
  static constexpr int vpt = vecs_per_thread * elts_per_load;
  static constexpr int threads_per_row = experts / vpt;
  static const int rows_per_warp = warp_size_param / threads_per_row;
};
}  // namespace detail

template <
    int num_experts,
    int warps_per_tb,
    int warp_size_param,
    int max_bytes_per_load,
    typename InputType,
    typename IndexType>
void launch_topk_gating_softmax(
    const InputType* input,
    const bool* finished,
    float* output,
    IndexType* indices,
    int* source_rows,
    const int total_rows,
    const int k_select,
    const int start_expert,
    const int end_expert,
    bool renormalize,
    sycl::queue& queue) {
  static constexpr int actual_bytes_per_load =
      MIN_VAL(max_bytes_per_load, static_cast<int>(sizeof(InputType) * num_experts));

  using Constants = detail::
      TopkCompileTimeConstants<num_experts, actual_bytes_per_load, warp_size_param, InputType>;
  static constexpr int vpt = Constants::vpt;
  static constexpr int rows_per_warp = Constants::rows_per_warp;

  const int num_warps = (total_rows + rows_per_warp - 1) / rows_per_warp;
  const int num_blocks = (num_warps + warps_per_tb - 1) / warps_per_tb;

  sycl::range<2> grid_dim(1, num_blocks);
  sycl::range<2> block_dim(warps_per_tb, warp_size_param);

  queue.submit([&](sycl::handler& cgh) {
    cgh.parallel_for(
        sycl::nd_range<2>(grid_dim * block_dim, block_dim),
        topkGatingSoftmaxKernel<
            vpt,
            num_experts,
            warps_per_tb,
            actual_bytes_per_load,
            warp_size_param,
            InputType,
            IndexType>(
            input,
            finished,
            output,
            total_rows,
            indices,
            source_rows,
            k_select,
            start_expert,
            end_expert,
            renormalize));
  });
}

#define LAUNCH_KERNEL(NUM_EXPERTS, WARPS_PER_TB, MAX_BYTES)                    \
  static_assert(                                                               \
      warp_size == 32, "Only 32-thread warps are supported on XPU");           \
  launch_topk_gating_softmax<                                                  \
      NUM_EXPERTS,                                                             \
      WARPS_PER_TB,                                                            \
      warp_size,                                                               \
      MAX_BYTES>(                                                              \
      gating_output,                                                           \
      nullptr,                                                                 \
      topk_weights,                                                            \
      topk_indices,                                                            \
      token_expert_indices,                                                    \
      num_tokens,                                                              \
      topk,                                                                    \
      0,                                                                       \
      num_experts,                                                             \
      renormalize,                                                             \
      queue);

template <typename InputType, typename IndexType>
void topkGatingSoftmaxLauncher(
    const InputType* gating_output,
    float* topk_weights,
    IndexType* topk_indices,
    int* token_expert_indices,
    float* workspace,
    const int num_tokens,
    const int num_experts,
    const int topk,
    const bool renormalize,
    sycl::queue& queue) {
  static constexpr int warps_per_block = 4;
  static constexpr int pow2_bytes = 16;
  static constexpr int mult64_bytes = 2 * sizeof(InputType);

  switch (num_experts) {
    case 1:
      LAUNCH_KERNEL(1, warps_per_block, pow2_bytes);
      break;
    case 2:
      LAUNCH_KERNEL(2, warps_per_block, pow2_bytes);
      break;
    case 4:
      LAUNCH_KERNEL(4, warps_per_block, pow2_bytes);
      break;
    case 8:
      LAUNCH_KERNEL(8, warps_per_block, pow2_bytes);
      break;
    case 16:
      LAUNCH_KERNEL(16, warps_per_block, pow2_bytes);
      break;
    case 32:
      LAUNCH_KERNEL(32, warps_per_block, pow2_bytes);
      break;
    case 64:
      LAUNCH_KERNEL(64, warps_per_block, pow2_bytes);
      break;
    case 128:
      LAUNCH_KERNEL(128, warps_per_block, pow2_bytes);
      break;
    case 256:
      LAUNCH_KERNEL(256, warps_per_block, pow2_bytes);
      break;
    case 512:
      LAUNCH_KERNEL(512, warps_per_block, pow2_bytes);
      break;
    case 192:
    case 320:
    case 384:
    case 448:
    case 576:
      LAUNCH_KERNEL(num_experts, warps_per_block, mult64_bytes);
      break;
    default: {
      TORCH_CHECK(
          workspace != nullptr,
          "workspace buffer required for non-power-of-two or large expert counts.");
      static constexpr int TPB = 256;
      sycl::range<1> grid(num_tokens);
      sycl::range<1> block(TPB);

      queue.submit([&](sycl::handler& cgh) {
        sycl::local_accessor<float, 1> slm(sycl::range<1>(2), cgh);
        cgh.parallel_for(
            sycl::nd_range<1>(grid * block, block),
            moeSoftmaxKernel<TPB, InputType>(
                slm, gating_output, nullptr, workspace, num_experts));
      });

      queue.submit([&](sycl::handler& cgh) {
        cgh.parallel_for(
            sycl::nd_range<1>(grid * block, block),
            moeTopKKernel<TPB, IndexType>(
                workspace,
                nullptr,
                topk_weights,
                topk_indices,
                token_expert_indices,
                num_experts,
                topk,
                0,
                num_experts,
                renormalize));
      });
    }
  }
}

}  // namespace moe
}  // namespace vllm

void topk_softmax(
    torch::Tensor& topk_weights,
    torch::Tensor& topk_indices,
    torch::Tensor& token_expert_indices,
    torch::Tensor& gating_output,
    const bool renormalize) {
  const int num_experts = gating_output.size(-1);
  const int num_tokens = gating_output.numel() / num_experts;
  const int topk = topk_weights.size(-1);

  const bool is_power_of_two = (num_experts != 0) && ((num_experts & (num_experts - 1)) == 0);
  const bool needs_workspace = !is_power_of_two || num_experts > 256;
  const int64_t workspace_size = needs_workspace ? num_tokens * num_experts : 0;

  const at::DeviceGuard guard(gating_output.device());
  auto& queue = vllm::xpu::vllmGetQueue();

  torch::Tensor workspace_tensor = torch::empty(
      {workspace_size}, gating_output.options().dtype(torch::kFloat));

#define LAUNCH_TOPK(INPUT_DTYPE, INDEX_DTYPE)                          \
  vllm::moe::topkGatingSoftmaxLauncher(                                \
      reinterpret_cast<INPUT_DTYPE*>(gating_output.mutable_data_ptr()),\
      topk_weights.data_ptr<float>(),                                  \
      topk_indices.data_ptr<INDEX_DTYPE>(),                            \
      token_expert_indices.data_ptr<int>(),                            \
      workspace_tensor.data_ptr<float>(),                              \
      num_tokens,                                                      \
      num_experts,                                                     \
      topk,                                                            \
      renormalize,                                                     \
      queue);

  if (topk_indices.scalar_type() == at::ScalarType::Int) {
    if (gating_output.scalar_type() == at::ScalarType::Float)
      LAUNCH_TOPK(float, int)
    else if (gating_output.scalar_type() == at::ScalarType::Half)
      LAUNCH_TOPK(sycl::half, int)
    else
      LAUNCH_TOPK(sycl::ext::oneapi::bfloat16, int)
  } else if (topk_indices.scalar_type() == at::ScalarType::UInt32) {
    if (gating_output.scalar_type() == at::ScalarType::Float)
      LAUNCH_TOPK(float, uint32_t)
    else if (gating_output.scalar_type() == at::ScalarType::Half)
      LAUNCH_TOPK(sycl::half, uint32_t)
    else
      LAUNCH_TOPK(sycl::ext::oneapi::bfloat16, uint32_t)
  } else {
    TORCH_CHECK(topk_indices.scalar_type() == at::ScalarType::Long);
    if (gating_output.scalar_type() == at::ScalarType::Float)
      LAUNCH_TOPK(float, int64_t)
    else if (gating_output.scalar_type() == at::ScalarType::Half)
      LAUNCH_TOPK(sycl::half, int64_t)
    else
      LAUNCH_TOPK(sycl::ext::oneapi::bfloat16, int64_t)
  }
#undef LAUNCH_TOPK
}

#include "capture_api.h"
