namespace {
void setError(std::string* err, const std::string& msg) {
    if (err != nullptr) {
        *err = msg;
    }
}

std::string formatErrorMessage(const char* step, DWORD code) {
    std::ostringstream stream;
    stream << step << " failed with error code: " << code;
    return stream.str();
}
}  // namespace

namespace infra {
namespace win {
namespace capture {

bool captureDesktopRectBgr(const RECT& rect, cv::Mat* result, std::string* err) {
    // Validate output parameter
    if (result == nullptr) {
        setError(err, "output image pointer is null");
        return false;
    }

    // Clear previous content
    result->release();

    // Compute dimensions
    int w = rect.right - rect.left;
    int h = rect.bottom - rect.top;

    // Validate dimensions
    if (w <= 1 || h <= 1 || w > 9999 || h > 9999) {
        std::ostringstream oss;
        oss << "invalid rectangle: left=" << rect.left 
            << ", top=" << rect.top 
            << ", right=" << rect.right 
            << ", bottom=" << rect.bottom;
        setError(err, oss.str());
        return false;
    }

    // Acquire screen DC
    HDC screenDC = GetDC(nullptr);
    if (screenDC == nullptr) {
        setError(err, formatErrorMessage("GetDC", GetLastError()));
        return false;
    }

    // Create memory DC
    HDC memDC = CreateCompatibleDC(screenDC);
    if (memDC == nullptr) {
        setError(err, formatErrorMessage("CreateCompatibleDC", GetLastError()));
        ReleaseDC(nullptr, screenDC);
        return false;
    }

    // Create bitmap
    HBITMAP bmp = CreateCompatibleBitmap(screenDC, w, h);
    if (bmp == nullptr) {
        setError(err, formatErrorMessage("CreateCompatibleBitmap", GetLastError()));
        DeleteDC(memDC);
        ReleaseDC(nullptr, screenDC);
        return false;
    }

    // Select bitmap into DC
    HGDIOBJ prevObj = SelectObject(memDC, bmp);
    if (prevObj == nullptr || prevObj == HGDI_ERROR) {
        setError(err, formatErrorMessage("SelectObject", GetLastError()));
        DeleteObject(bmp);
        DeleteDC(memDC);
        ReleaseDC(nullptr, screenDC);
        return false;
    }

    // Perform screen capture
    if (BitBlt(memDC, 0, 0, w, h,
               screenDC, rect.left, rect.top,
               SRCCOPY | CAPTUREBLT) == FALSE) {
        setError(err, formatErrorMessage("BitBlt", GetLastError()));
        SelectObject(memDC, prevObj);
        DeleteObject(bmp);
        DeleteDC(memDC);
        ReleaseDC(nullptr, screenDC);
        return false;
    }

    // Prepare BITMAPINFOHEADER for DIB extraction
    BITMAPINFOHEADER infoHeader{};
    infoHeader.biSize = sizeof(BITMAPINFOHEADER);
    infoHeader.biWidth = w;
    infoHeader.biHeight = -h;  // Top-down DIB
    infoHeader.biPlanes = 1;
    infoHeader.biBitCount = 32;
    infoHeader.biCompression = BI_RGB;

    // Allocate buffer for BGRA image
    cv::Mat bgraImg(h, w, CV_8UC4);

    // Extract DIB bits
    int readLines = GetDIBits(
        memDC,
        bmp,
        0,
        static_cast<UINT>(h),
        bgraImg.data,
        reinterpret_cast<BITMAPINFO*>(&infoHeader),
        DIB_RGB_COLORS);

    // Cleanup GDI resources
    SelectObject(memDC, prevObj);
    DeleteObject(bmp);
    DeleteDC(memDC);
    ReleaseDC(nullptr, screenDC);

    // Check for failure in GetDIBits
    if (readLines == 0) {
        setError(err, formatErrorMessage("GetDIBits", GetLastError()));
        return false;
    }

    // Convert BGRA to BGR
    cv::cvtColor(bgraImg, *result, cv::COLOR_BGRA2BGR);

    // Final validation
    if (result->empty()) {
        setError(err, "conversion produced empty image");
        return false;
    }

    return true;
}

