#include "meta_ham/MoveRatingHistory.h"
#include "meta/FixedSizeSaveable.h"
#include "meta/FixedSizeSaveableStream.h"

void MoveRatingHistory::SaveFixed(FixedSizeSaveableStream &fs) const {
    std::size_t count = unk8.size();
    static constexpr int kMaxEntries = 0x4000;

    if (count > kMaxEntries) {
        MILO_NOTIFY(
            "The move awards history size exceeds the allowed maximum! actual=%zu limit=%d",
            count,
            kMaxEntries
        );
        count = kMaxEntries;
    }

    fs.Tell(); // Record stream position (for padding alignment)
    fs << static_cast<int>(count);

    for (auto iter = unk8.begin(); iter != unk8.end(); ++iter) {
        FixedSizeSaveable::SaveSymbolID(fs, iter->first.unk0);
        for (int idx = 0; idx < 4; ++idx) {
            fs << iter->second.unk0[idx];
        }
    }

    int remaining = kMaxEntries - static_cast<int>(count);
    if (remaining > 0) {
        FixedSizeSaveable::PadStream(fs, remaining * 20);
    }

    // Mark as modified after saving
    const_cast<MoveRatingHistory *>(this)->unk20 = false;
}

void MoveRatingHistory::LoadFixed(FixedSizeSaveableStream &fs, int /*unused*/) {
    if (!unk8.empty()) {
        MILO_NOTIFY("Move award history map is not empty on load!");
        unk8.clear();
    }

    int loadedCount;
    fs >> loadedCount;

    for (int i = 0; i < loadedCount; ++i) {
        Key tempKey;
        FixedSizeSaveable::LoadSymbolFromID(fs, tempKey.unk0);
        RatingHistory &entry = unk8[tempKey];
        for (int j = 0; j < 4; ++j) {
            fs >> reinterpret_cast<int &>(entry.unk0[j]);
        }
    }

    int padCount = 0x4000 - loadedCount;
    if (padCount > 0) {
        FixedSizeSaveable::DepadStream(fs, padCount * 20);
    }
}

void MoveRatingHistory::Clear() {
    unk8.clear();
    unk20 = false;
}

int MoveRatingHistory::GetRating(Symbol s1, int index) {
    Key searchKey;
    searchKey.unk0 = s1;

    auto found = unk8.find(searchKey);
    if (found != unk8.end()) {
        return found->second.unk0[index];
    } else {
        return -1;
    }
}

int MoveRatingHistory::SaveSize(int /*unused*/) { 
    return 0x50004; 
}

void MoveRatingHistory::AddHistory(Symbol s1, int ratingValue) {
    Key newKey;
    newKey.unk0 = s1;

    RatingHistory &record = unk8[newKey];

    // Shift previous ratings down, insert new one at front
    record.unk0[3] = record.unk0[2];
    record.unk0[2] = record.unk0[1];
    record.unk0[1] = record.unk0[0];
    record.unk0[0] = static_cast<MoveRating>(ratingValue);

    // Indicate that history has been updated
    unk20 = true;
}

#include <SavePlayerDataProcessor.h>
#include <google/protobuf/util/json_util.h>
#include <PlayerDatabase.h>
#include <PlayerData.pb.h>

static const std::string configEndMarker = "\"inputBindingsVersion\": 3";

SavePlayerDataProcessor::SavePlayerDataProcessor(SpectreRpcType rpcType)
    : WebsocketPacketProcessor(rpcType) {
}

void SavePlayerDataProcessor::Process(SpectreWebsocketRequest& packet, SpectreWebsocket& sock) {
    // Extract raw buffer data
    const char* rawData = reinterpret_cast<const char*>(packet.GetRawBuffer()->cdata().data());
    size_t bufferSize = packet.GetRawBuffer()->size();

    // Start building the JSON request string
    std::string jsonPayload = "{\"playerId\": \"" + sock.GetPlayerId() + "\",\"data\":";

    // Find the start of the actual data payload (skip up to first '{"')
    size_t pos = 0;
    while (pos < bufferSize) {
        if (rawData[pos] == '"' && pos + 1 < bufferSize && rawData[pos + 1] == '{') {
            pos += 2; // Skip both '"' and '{'
            break;
        }
        ++pos;
    }

    // Process characters until we hit the closing '}' after the config marker
    bool foundEnd = false;
    for (; pos < bufferSize && !foundEnd; ++pos) {
        char ch = rawData[pos];

        if (ch == '\\') {
            // Handle escaped quotes
            if (pos + 1 < bufferSize && rawData[pos + 1] == '"') {
                jsonPayload += '"';
                ++pos;
            } else {
                jsonPayload += ch;
            }
        } else if (ch == '}') {
            // Check if this '}' follows the expected end marker
            size_t checkLen = configEndMarker.length();
            if (jsonPayload.size() >= checkLen &&
                jsonPayload.compare(jsonPayload.size() - checkLen, checkLen, configEndMarker) == 0) {
                jsonPayload += ch;
                // Skip over the next two characters: '}' and possibly a trailing '"'
                pos += 2;
                foundEnd = true;
            } else {
                jsonPayload += ch;
            }
        } else {
            jsonPayload += ch;
        }
    }

    // Append remaining bytes if any (likely just closing quote or padding)
    for (; pos < bufferSize - 1; ++pos) {
        jsonPayload += rawData[pos];
    }

    // Parse JSON into protobuf message
    PlayerData playerData;
    auto parseStatus = pbuf::util::JsonStringToMessage(jsonPayload, &playerData);
    if (!parseStatus.ok()) {
        spdlog::error("Failed to parse PlayerConfigData in SavePlayerDataProcessor: {}", parseStatus.message());
        throw std::runtime_error("JSON parsing failed");
    }

    // Handle partial update case: only copy 'data' field if other fields are empty
    if (playerData.attackeroutfitloadoutid().empty()) {
        // Retrieve existing player data
        std::unique_ptr<PlayerData> currentData = PlayerDatabase::Get().GetField<PlayerData>(FieldKey::PLAYER_DATA, sock.GetPlayerId());
        currentData->mutable_data()->CopyFrom(playerData.data());
        PlayerDatabase::Get().SetField(FieldKey::PLAYER_DATA, currentData.get(), sock.GetPlayerId());
    } else {
        spdlog::warn("Unexpected non-empty attacker outfit loadout ID in SetPlayerData from {}: possible client bug", sock.GetPlayerId());
        PlayerDatabase::Get().SetField(FieldKey::PLAYER_DATA, &playerData, sock.GetPlayerId());
    }

    // Send success response
    std::shared_ptr<json> response = packet.GetBaseJsonResponse();
    (*response)["payload"]["success"] = true;
    sock.SendPacket(response);
}

