Result<ThreadImpl, ThreadCreateErr> ThreadImpl::make(const ThreadConfig& cfg,
                                                     std::shared_ptr<PosixAPI> api) noexcept {
    ThreadImpl instance{cfg, api};

    // Initialize attributes — always succeeds on Linux per POSIX.1
    if (instance.api_->pthread_attr_init(&instance.attributes_) != 0) {
        return Err(ThreadCreateErr::internalOsError);
    }

    // Apply priority settings
    auto prioStatus = instance.applyPrioritySettings();
    if (prioStatus.isError()) {
        return Err(prioStatus.getError());
    }

    // Apply stack size if specified
    auto stackStatus = instance.applyStackSize();
    if (stackStatus.isError()) {
        return Err(stackStatus.getError());
    }

    return Ok(std::move(instance));
}

ThreadImpl::ThreadImpl(ThreadConfig config, std::shared_ptr<PosixAPI> api) noexcept
    : config_{std::move(config)}, api_{std::move(api)} {}

Result<void, ThreadCreateErr> ThreadImpl::run() noexcept {
    constexpr auto success = 0U;

    if (api_->pthread_create(&thread_, &attributes_, threadFunction, this) != success) {
        return Err(ThreadCreateErr::internalOsError);
    }

    // Clean up attributes after thread creation
    std::ignore = api_->pthread_attr_destroy(&attributes_);
    std::ignore = api_->pthread_setname_np(thread_, config_.name.c_str());

    // Set CPU affinity if required
    return configureAffinityForThread();
}

bool ThreadImpl::join() const noexcept {
    return api_->pthread_join(thread_, nullptr) == 0;
}

bool ThreadImpl::kill() const noexcept {
    return api_->pthread_cancel(thread_) == 0;
}

Result<void, ThreadCreateErr> ThreadImpl::applyPrioritySettings() noexcept {
    if (config_.priority == Priority::nominalMin) {
        return Ok();
    }

    int policy{};
    if (api_->pthread_attr_getschedpolicy(&attributes_, &policy) != 0) {
        return Err(ThreadCreateErr::internalOsError);
    }

    const auto minPrio = api_->sched_get_priority_min(policy);
    const auto maxPrio = api_->sched_get_priority_max(policy);

    if (minPrio == -1 || maxPrio == -1) {
        return Err(ThreadCreateErr::internalOsError);
    }

    sched_param param{};
    param.sched_priority = [&]() -> int {
        if (config_.priority == Priority::lowest) {
            return static_cast<int>(minPrio);
        } else if (config_.priority == Priority::highest) {
            return static_cast<int>(maxPrio);
        } else {
            const int nominalMin = 70;
            const int nominalMax = static_cast<int>(maxPrio) - 1;
            return nominalMin + (nominalMax - nominalMin) / 2;
        }
    }();

    if (api_->pthread_attr_setschedparam(&attributes_, &param) != 0) {
        return Err(ThreadCreateErr::internalOsError);
    }

    return Ok();
}

Result<void, ThreadCreateErr> ThreadImpl::applyStackSize() noexcept {
    if (config_.stackSize == 0U) {
        return Ok();
    }

    if (api_->pthread_attr_setstacksize(&attributes_, config_.stackSize) != 0) {
        return Err(ThreadCreateErr::invalidStackSize);
    }

    return Ok();
}

bool ThreadImpl::detach() const noexcept {
    return api_->pthread_detach(thread_) == 0;
}

Result<void, ThreadCreateErr> ThreadImpl::configureAffinityForThread() const noexcept {
    if (config_.affinity == 0U) {
        return Ok();
    }

    cpu_set_t mask{};
    CPU_ZERO(&mask);

    for (std::size_t cpu = 0; config_.affinity != 0; ++cpu, config_.affinity >>= 1) {
        if ((config_.affinity & 1U) != 0) {
            CPU_SET(cpu, &mask);  // NOLINT
        }
    }

    if (api_->pthread_setaffinity_np(thread_, sizeof(mask), &mask) != 0) {
        return Err(ThreadCreateErr::invalidAffinity);
    }

    return Ok();
}

void* ThreadImpl::threadFunction(void* arg) {
    auto* self = static_cast<ThreadImpl*>(arg);
    // Cancel type could be set here if needed — currently unused.
    self->config_.function(self->config_.arg);
    return nullptr;
}

