#include "yaml-cpp/yaml.h"
#include <iostream>

int main() {
    // First test block: parsing and basic manipulation
    {
        YAML::Value parsed = YAML::Parse("test.yaml");

        std::cout << parsed[0].as<std::string>();
        std::cout << YAML::Value::str(parsed[0]);
        std::cout << parsed[1]["primes"].as<int>() == 7;
        try {
            int val = parsed[1]["odds"][6].as<int>();
        } catch (...) {
            // Expected exception for out-of-bounds access
        }

        parsed[2].push_back(5);
        parsed.insert(3, "Hello, World");
        parsed[0].clear();
        parsed[0]["key"] = "value";
        std::cout << parsed;
    }

    // Second test block: copy semantics
    {
        YAML::Value rootVal = "Hello";
        rootVal = YAML::Sequence();
        rootVal.insert(0, 0);
        rootVal.insert(2, "two");

        YAML::Value aliasRef = rootVal;
        aliasRef[0] = 5;
        aliasRef.push_back(rootVal);
        aliasRef[3][0] = 0;
        aliasRef.push_back(YAML::Copy(rootVal));
        aliasRef[4][0] = 5;
    }

    // Third test block: auto-conversion behavior
    {
        YAML::Value container;
        container.insert(0, 1);
        container["key"] = 5;
        try {
            container.push_back(10);
        } catch (...) {
            // Expected error when converting map to sequence
        }
        container.erase("key");
        container = "Hello";
    }

    // Fourth test block: map vs sequence initialization
    {
        YAML::Value mapping;
        mapping[3] = 1;

        YAML::Value sequence;
        sequence = YAML::Sequence();
        sequence[3] = 1;
    }

    // Fifth test block: self-reference
    {
        YAML::Value selfRef;
        selfRef[0] = selfRef;
    }

    // Sixth test block: lazy instantiation
    {
        YAML::Value parent;
        YAML::Value child = parent["key"];
        child = "value";

        YAML::Value child2 = parent["key2"];
        parent["key3"] = child2;
        child2 = "monkey";
    }

    // Seventh test block: aliasing and unaliasing
    {
        YAML::Value list = YAML::Sequence();
        list[0] = "zero";
        list[1] = list[0];
        list[0] = list[1];

        bool equal1 = (list[0] == list[1]);
        list[1] = "one";
        YAML::UnAlias(list[1]);
        bool equal2 = (list[0] == list[1]);
    }

    // Eighth test block: node persistence after reassignment
    {
        YAML::Value container;
        container.push_back("zero");
        container.push_back("one");
        container.push_back("two");

        YAML::Value savedNode = container[2];
        container = "scalar";
    }

    // Ninth test block: resetting self-reference
    {
        YAML::Value container;
        container[0] = container;
        container[0] = 5;
    }

    // Tenth test block: key-value referencing
    {
        YAML::Value root;
        YAML::Value entry;
        entry["key"] = "value";
        root[entry] = entry;
    }

    // Eleventh test block: complex nested structure
    {
        YAML::Value root;
        root[0] = "hi";
        root[1][0] = "bye";
        root[1][1] = root;

        YAML::Value subnode = root[1];
        root = "gone";
    }

    return 0;
}

