BookmarkListItem::BookmarkListItem() {}

BookmarkListItem::BookmarkListItem(World& w, const BookmarkCompleteUndoData& undoData) {
    nameData = w.netObjMan.make_obj<NameData>();
    nameData->name = undoData.name;

    if (undoData.folderList.has_value()) {
        auto& srcFolderList = undoData.folderList.value();
        folderData = std::make_unique<BookmarkFolderData>();
        folderData->folderList = w.netObjMan.make_obj<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>();

        for (const auto& srcItem : srcFolderList) {
            auto newItemIt = folderData->folderList->emplace_back_direct(folderData->folderList, w, srcItem);
            w.undo.register_new_netid_to_existing_undoid(srcItem.undoID, newItemIt->obj.get_net_id());
        }
    } else {
        bookmarkData = std::make_unique<BookmarkData>(undoData.bookmarkData.value());
    }
}

BookmarkListItem::BookmarkListItem(NetworkingObjects::NetObjManager& netObjMan, const std::string& itemName, bool isFolder, const BookmarkData& itemBookmarkData) {
    if (isFolder) {
        folderData = std::make_unique<BookmarkFolderData>();
        folderData->folderList = netObjMan.make_obj<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>();
    } else {
        bookmarkData = std::make_unique<BookmarkData>(itemBookmarkData);
    }

    nameData = netObjMan.make_obj<NameData>();
    nameData->name = itemName;
}

BookmarkCompleteUndoData BookmarkListItem::get_complete_undo_data(WorldUndoManager& u) {
    BookmarkCompleteUndoData result;
    result.name = nameData->name;

    if (folderData) {
        result.folderList = std::vector<BookmarkCompleteUndoData>{};
        auto& outFolderList = result.folderList.value();

        for (auto& childItem : *folderData->folderList) {
            outFolderList.emplace_back(childItem.obj->get_complete_undo_data(u));
            outFolderList.back().undoID = u.get_undoid_from_netid(childItem.obj.get_net_id());
        }
    } else {
        result.bookmarkData = *bookmarkData;
    }

    return result;
}

void BookmarkListItem::reassign_netobj_ids_call() {
    if (folderData) {
        folderData->folderList.reassign_ids();
    }
    nameData.reassign_ids();
}

void BookmarkListItem::scale_up(const WorldScalar& scaleFactor) {
    if (folderData) {
        for (auto& childItem : *folderData->folderList) {
            childItem.obj->scale_up(scaleFactor);
        }
    } else {
        bookmarkData->scale_up(scaleFactor);
    }
}

