void BookmarkListItem::register_class(World& w) {
    auto readConstructorData = [&w](const NetworkingObjects::NetObjTemporaryPtr<BookmarkListItem>& obj, cereal::PortableBinaryInputArchive& archive, const std::shared_ptr<NetServer::ClientData>& client) {
        bool isFolder;
        archive(isFolder);

        if (isFolder) {
            obj->folderData = std::make_unique<BookmarkFolderData>();
            obj->folderData->folderList = obj.get_obj_man()->read_create_message<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>(archive, client);
        } else {
            obj->bookmarkData = std::make_unique<BookmarkData>();
            archive(*obj->bookmarkData);
        }

        obj->nameData = obj.get_obj_man()->read_create_message<NameData>(archive, client);
        canvas_scale_up_check(*obj, w, client);
    };

    w.netObjMan.register_class<BookmarkListItem, BookmarkListItem, BookmarkListItem, BookmarkListItem>({
        .writeConstructorFuncClient = write_constructor_data,
        .readConstructorFuncClient = readConstructorData,
        .readUpdateFuncClient = nullptr,
        .writeConstructorFuncServer = write_constructor_data,
        .readConstructorFuncServer = readConstructorData,
        .readUpdateFuncServer = nullptr
    });

    NetworkingObjects::register_ordered_list_class<BookmarkListItem>(w.netObjMan);
    w.delayedUpdateObjectManager.register_class<NameData>(w.netObjMan);
}

void BookmarkListItem::write_constructor_data(const NetObjTemporaryPtr<BookmarkListItem>& obj, cereal::PortableBinaryOutputArchive& archive) {
    archive(obj->is_folder());

    if (obj->is_folder()) {
        obj->folderData->folderList.write_create_message(archive);
    } else {
        archive(*obj->bookmarkData);
    }

    obj->nameData.write_create_message(archive);
}

void BookmarkListItem::save_file(cereal::PortableBinaryOutputArchive& archive) const {
    archive(*nameData);
    bool hasFolder = folderData != nullptr;
    archive(hasFolder);

    if (hasFolder) {
        uint32_t count = static_cast<uint32_t>(folderData->folderList->size());
        archive(count);
        for (auto& childItem : *folderData->folderList) {
            childItem.obj->save_file(archive);
        }
    } else {
        archive(*bookmarkData);
    }
}

void BookmarkListItem::load_file(cereal::PortableBinaryInputArchive& archive, VersionNumber version, BookmarkManager& bMan) {
    nameData = bMan.world.netObjMan.make_obj<NameData>();
    archive(*nameData);

    bool isFolder;
    archive(isFolder);

    if (isFolder) {
        folderData = std::make_unique<BookmarkFolderData>();
        folderData->folderList = bMan.world.netObjMan.make_obj<NetworkingObjects::NetObjOrderedList<BookmarkListItem>>();

        uint32_t itemCount;
        archive(itemCount);

        for (uint32_t i = 0; i < itemCount; ++i) {
            BookmarkListItem* newItem = new BookmarkListItem{};
            newItem->load_file(archive, version, bMan);
            folderData->folderList->push_back_and_send_create(folderData->folderList, newItem);
        }
    } else {
        bookmarkData = std::make_unique<BookmarkData>();
        archive(*bookmarkData);
    }
}

#include <torch/all.h>
