typedef at::BFloat16 bf16;

// External CUDA implementations
void cuda_forward(int batch, int seq_len, int channels, float* w, float* u, float* k, float* v, float* y);
void cuda_forward_bf16(int batch, int seq_len, int channels, float* w, bf16* u, bf16* k, bf16* v, bf16* y);
void cuda_forward_with_state(int batch, int seq_len, int channels, float* w, float* u, float* k, float* v, float* y, float* s);
void cuda_forward_with_state_bf16(int batch, int seq_len, int channels, float* w, bf16* u, bf16* k, bf16* v, bf16* y, float* s);
void cuda_backward(int batch, int seq_len, int channels,
                   float* w, float* u, float* k, float* v, float* y, float* gy,
                   float* gw, float* gu, float* gk, float* gv);
void cuda_backward_bf16(int batch, int seq_len, int channels,
                        float* w, bf16* u, bf16* k, bf16* v, bf16* y, bf16* gy,
                        bf16* gw, bf16* gu, bf16* gk, bf16* gv);

// Helper lambda to extract tensor dimensions consistently
auto get_dims = [](const torch::Tensor& t) {
    return std::make_tuple(t.size(0), t.size(1), t.size(2));
};

// Forward functions
void forward(torch::Tensor& w, torch::Tensor& u, torch::Tensor& k, torch::Tensor& v, torch::Tensor& y) {
    auto [batch, seq_len, channels] = get_dims(k);
    cuda_forward(batch, seq_len, channels,
                 w.data_ptr<float>(), u.data_ptr<float>(),
                 k.data_ptr<float>(), v.data_ptr<float>(), y.data_ptr<float>());
}

void forward_bf16(torch::Tensor& w, torch::Tensor& u, torch::Tensor& k, torch::Tensor& v, torch::Tensor& y) {
    auto [batch, seq_len, channels] = get_dims(k);
    cuda_forward_bf16(batch, seq_len, channels,
                      w.data_ptr<float>(), u.data_ptr<bf16>(),
                      k.data_ptr<bf16>(), v.data_ptr<bf16>(), y.data_ptr<bf16>());
}

void forward_with_state(torch::Tensor& w, torch::Tensor& u, torch::Tensor& k, torch::Tensor& v, torch::Tensor& y, torch::Tensor& s) {
    auto [batch, seq_len, channels] = get_dims(k);
    cuda_forward_with_state(batch, seq_len, channels,
                            w.data_ptr<float>(), u.data_ptr<float>(),
                            k.data_ptr<float>(), v.data_ptr<float>(), y.data_ptr<float>(), s.data_ptr<float>());
}

void forward_with_state_bf16(torch::Tensor& w, torch::Tensor& u, torch::Tensor& k, torch::Tensor& v, torch::Tensor& y, torch::Tensor& s) {
    auto [batch, seq_len, channels] = get_dims(k);
    cuda_forward_with_state_bf16(batch, seq_len, channels,
                                 w.data_ptr<float>(), u.data_ptr<bf16>(),
                                 k.data_ptr<bf16>(), v.data_ptr<bf16>(), y.data_ptr<bf16>(), s.data_ptr<float>());
}

// Backward functions
void backward(torch::Tensor& w, torch::Tensor& u, torch::Tensor& k, torch::Tensor& v, torch::Tensor& y,
              torch::Tensor& gy, torch::Tensor& gw, torch::Tensor& gu, torch::Tensor& gk, torch::Tensor& gv) {
    auto [batch, seq_len, channels] = get_dims(k);
    cuda_backward(batch, seq_len, channels,
                  w.data_ptr<float>(), u.data_ptr<float>(), k.data_ptr<float>(), v.data_ptr<float>(), y.data_ptr<float>(),
                  gy.data_ptr<float>(), gw.data_ptr<float>(), gu.data_ptr<float>(), gk.data_ptr<float>(), gv.data_ptr<float>());
}

void backward_bf16(torch::Tensor& w, torch::Tensor& u, torch::Tensor& k, torch::Tensor& v, torch::Tensor& y,
                   torch::Tensor& gy, torch::Tensor& gw, torch::Tensor& gu, torch::Tensor& gk, torch::Tensor& gv) {
    auto [batch, seq_len, channels] = get_dims(k);
    cuda_backward_bf16(batch, seq_len, channels,
                       w.data_ptr<float>(), u.data_ptr<bf16>(), k.data_ptr<bf16>(), v.data_ptr<bf16>(), y.data_ptr<bf16>(),
                       gy.data_ptr<bf16>(), gw.data_ptr<bf16>(), gu.data_ptr<bf16>(), gk.data_ptr<bf16>(), gv.data_ptr<bf16>());
}

// Torch extension registration
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, ops) {
    // Register forward variants
    ops.def("forward", forward)
       .impl("forward", torch::kCUDA, &forward);
    ops.def("forward_bf16", forward_bf16)
       .impl("forward_bf16", torch::kCUDA, &forward_bf16);
    ops.def("forward_with_state", forward_with_state)
       .impl("forward_with_state", torch::kCUDA, &forward_with_state);
    ops.def("forward_with_state_bf16", forward_with_state_bf16)
       .impl("forward_with_state_bf16", torch::kCUDA, &forward_with_state_bf16);

    // Register backward variants
    ops.def("backward", backward)
       .impl("backward", torch::kCUDA, &backward);
    ops.def("backward_bf16", backward_bf16)
       .impl("backward_bf16", torch::kCUDA, &backward_bf16);
}

