#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MAXN = 2000 + 5;
const int64 QUERY_LIMIT = 50000;
int n;
int64 k;
int64 cacheVal[MAXN][MAXN];
unsigned char knownVal[MAXN][MAXN];
unsigned char visitedCell[MAXN][MAXN];
int64 queriesUsed = 0;

int64 fetchValue(int row, int col) {
    if (!knownVal[row][col]) {
        cout << "QUERY " << row << " " << col << endl;
        cout.flush();
        int64 val;
        if (!(cin >> val)) {
            exit(0);
        }
        cacheVal[row][col] = val;
        knownVal[row][col] = true;
        ++queriesUsed;
    }
    return cacheVal[row][col];
}

void readAllAndSelect() {
    vector<int64> allValues;
    allValues.reserve(n * n);
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            allValues.push_back(fetchValue(i, j));
        }
    }
    nth_element(allValues.begin(), allValues.begin() + k - 1, allValues.end());
    int64 result = allValues[k - 1];
    cout << "DONE " << result << endl;
    cout.flush();
}

void smallK_BFS() {
    struct Cell {
        int64 value;
        int x, y;
    };
    struct GreaterValue {
        bool operator()(const Cell& a, const Cell& b) const {
            return a.value > b.value;
        }
    };

    memset(visitedCell, 0, sizeof(visitedCell));
    priority_queue<Cell, vector<Cell>, GreaterValue> minHeap;

    visitedCell[1][1] = true;
    int64 firstVal = fetchValue(1, 1);
    minHeap.push({firstVal, 1, 1});

    int64 processedCount = 0;
    int64 answer = firstVal;

    while (!minHeap.empty()) {
        Cell current = minHeap.top();
        minHeap.pop();
        ++processedCount;

        if (processedCount == k) {
            answer = current.value;
            break;
        }

        int r = current.x;
        int c = current.y;

        if (r + 1 <= n && !visitedCell[r + 1][c]) {
            visitedCell[r + 1][c] = true;
            int64 nextVal = fetchValue(r + 1, c);
            minHeap.push({nextVal, r + 1, c});
        }

        if (c + 1 <= n && !visitedCell[r][c + 1]) {
            visitedCell[r][c + 1] = true;
            int64 nextVal = fetchValue(r, c + 1);
            minHeap.push({nextVal, r, c + 1});
        }
    }

    cout << "DONE " << answer << endl;
    cout.flush();
}

void largeK_BFS() {
    struct Cell {
        int64 value;
        int x, y;
    };
    struct LessValue {
        bool operator()(const Cell& a, const Cell& b) const {
            return a.value < b.value;
        }
    };

    memset(visitedCell, 0, sizeof(visitedCell));
    priority_queue<Cell, vector<Cell>, LessValue> maxHeap;

    visitedCell[n][n] = true;
    int64 lastVal = fetchValue(n, n);
    maxHeap.push({lastVal, n, n});

    int64 totalElements = 1LL * n * n;
    int64 rankFromLargest = totalElements - k + 1;
    int64 processedCount = 0;
    int64 answer = lastVal;

    while (!maxHeap.empty()) {
        Cell current = maxHeap.top();
        maxHeap.pop();
        ++processedCount;

        if (processedCount == rankFromLargest) {
            answer = current.value;
            break;
        }

        int r = current.x;
        int c = current.y;

        if (r - 1 >= 1 && !visitedCell[r - 1][c]) {
            visitedCell[r - 1][c] = true;
            int64 nextVal = fetchValue(r - 1, c);
            maxHeap.push({nextVal, r - 1, c});
        }

        if (c - 1 >= 1 && !visitedCell[r][c - 1]) {
            visitedCell[r][c - 1] = true;
            int64 nextVal = fetchValue(r, c - 1);
            maxHeap.push({nextVal, r, c - 1});
        }
    }

    cout << "DONE " << answer << endl;
    cout.flush();
}

int64 countLessOrEqual(int64 threshold) {
    int row = n;
    int col = 1;
    int64 count = 0;

    while (row >= 1 && col <= n) {
        int64 val = fetchValue(row, col);
        if (val <= threshold) {
            count += row;
            ++col;
        } else {
            --row;
        }
    }
    return count;
}

void binarySearchApproach() {
    int64 minVal = fetchValue(1, 1);
    int64 maxVal = fetchValue(n, n);

    int64 low = minVal;
    int64 high = maxVal;

    int64 remainingQueries = QUERY_LIMIT - queriesUsed;
    int maxIterations = 0;
    if (2 * n > 0) {
        maxIterations = static_cast<int>(remainingQueries / (2 * n));
    }
    if (maxIterations > 60) {
        maxIterations = 60;
    }

    while (low < high && maxIterations > 0) {
        int64 mid = low + (high - low) / 2;
        int64 cnt = countLessOrEqual(mid);

        if (cnt >= k) {
            high = mid;
        } else {
            low = mid + 1;
        }
        --maxIterations;
    }

    cout << "DONE " << low << endl;
    cout.flush();
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    if (!(cin >> n >> k)) {
        return 0;
    }

    int64 totalCells = 1LL * n * n;

    if (totalCells <= QUERY_LIMIT) {
        readAllAndSelect();
    } else {
        int64 forwardRank = k;
        int64 backwardRank = totalCells - k + 1;
        int64 smallerSide = min(forwardRank, backwardRank);

        if (2 * smallerSide <= QUERY_LIMIT) {
            if (forwardRank <= backwardRank) {
                smallK_BFS();
            } else {
                largeK_BFS();
            }
        } else {
            binarySearchApproach();
        }
    }

    return 0;
}

