    //////////////////////////////////////////////////
    class GazeboSimROS2ControlPluginPrivate
    {
    public:
        /// \brief Retrieve URDF XML from the ROS parameter server
        std::string fetchRobotDescription() const;

        /// \brief Extract active, unique 1-axis joints from the model
        /// If no joint names are specified in plugin config, all valid 1-axis joints are returned
        /// \param[in] _entity Model entity the plugin is attached to
        /// \param[in] _ecm Gazebo Entity Component Manager
        /// \return Map of enabled joint names to their entity IDs
        std::map<std::string, sim::Entity> collectActiveJoints(
            const sim::Entity& _entity,
            sim::EntityComponentManager& _ecm) const;

        // Member variables
        sim::Entity entity_;
        std::shared_ptr<rclcpp::Node> node_{nullptr};
        std::thread spin_thread_;
        rclcpp::executors::MultiThreadedExecutor::SharedPtr executor_;
        rclcpp::Duration control_period_ = rclcpp::Duration(1, 0);
        std::shared_ptr<pluginlib::ClassLoader<gz_ros2_control::GazeboSimSystemInterface>> loader_{nullptr};
        std::shared_ptr<controller_manager::ControllerManager> controller_manager_{nullptr};
        std::string robot_param_name_ = "robot_description";
        std::string robot_param_node_ = "robot_state_publisher";
        rclcpp::Time last_update_sim_time_ros_ = rclcpp::Time(static_cast<int64_t>(0), RCL_ROS_TIME);
        sim::EntityComponentManager* ecm{nullptr};
        int update_rate = 100;  // Default update rate
    };

    //////////////////////////////////////////////////
    std::map<std::string, sim::Entity>
    GazeboSimROS2ControlPluginPrivate::collectActiveJoints(
        const sim::Entity& _entity,
        sim::EntityComponentManager& _ecm) const
    {
        std::map<std::string, sim::Entity> result;
        auto jointEntities = _ecm.ChildrenByComponents(_entity, sim::components::Joint());

        for (const auto& jointEntity : jointEntities)
        {
            const auto jointName = _ecm.Component<sim::components::Name>(jointEntity)->Data();
            const auto* jointType = _ecm.Component<sim::components::JointType>(jointEntity);

            switch (jointType->Data())
            {
                case sdf::JointType::PRISMATIC:
                case sdf::JointType::REVOLUTE:
                case sdf::JointType::CONTINUOUS:
                case sdf::JointType::GEARBOX:
                    result[jointName] = jointEntity;
                    break;

                case sdf::JointType::FIXED:
                    RCLCPP_INFO(
                        node_->get_logger(),
                        "[gz_ros2_control] Fixed joint [%s] (Entity=%lu)] is skipped",
                        jointName.c_str(), jointEntity);
                    break;

                case sdf::JointType::REVOLUTE2:
                case sdf::JointType::SCREW:
                case sdf::JointType::BALL:
                case sdf::JointType::UNIVERSAL:
                    RCLCPP_WARN(
                        node_->get_logger(),
                        "[gz_ros2_control] Joint [%s] (Entity=%lu)] is of unsupported type."
                        " Only joints with a single axis are supported.",
                        jointName.c_str(), jointEntity);
                    break;

                default:
                    RCLCPP_WARN(
                        node_->get_logger(),
                        "[gz_ros2_control] Joint [%s] (Entity=%lu)] is of unknown type",
                        jointName.c_str(), jointEntity);
                    break;
            }
        }
        return result;
    }

    //////////////////////////////////////////////////
    std::string GazeboSimROS2ControlPluginPrivate::fetchRobotDescription() const
    {
        std::string urdf_string;
        using namespace std::chrono_literals;
        auto parameters_client = std::make_shared<rclcpp::AsyncParametersClient>(
            node_, robot_param_node_);

        while (!parameters_client->wait_for_service(0.5s))
        {
            if (!rclcpp::ok())
            {
                RCLCPP_ERROR(
                    node_->get_logger(), 
                    "Interrupted while waiting for %s service. Exiting.",
                    robot_param_node_.c_str());
                return "";
            }
            RCLCPP_ERROR(
                node_->get_logger(), 
                "%s service not available, waiting again...",
                robot_param_node_.c_str());
        }

        RCLCPP_INFO(
            node_->get_logger(), 
            "connected to service!! %s asking for %s",
            robot_param_node_.c_str(),
            this->robot_param_name_.c_str());

        while (urdf_string.empty())
        {
            RCLCPP_DEBUG(node_->get_logger(), "param_name %s", this->robot_param_name_.c_str());
            try
            {
                auto future = parameters_client->get_parameters({this->robot_param_name_});
                future.wait();
                const std::vector<rclcpp::Parameter>& values = future.get();
                urdf_string = values[0].as_string();
            }
            catch (const std::exception& e)
            {
                RCLCPP_ERROR(node_->get_logger(), "%s", e.what());
            }

            if (!urdf_string.empty())
            {
                break;
            }

            RCLCPP_ERROR(
                node_->get_logger(), 
                "gz_ros2_control plugin is waiting for model URDF in parameter [%s] on the ROS param server.",
                this->robot_param_name_.c_str());
            std::this_thread::sleep_for(std::chrono::microseconds(100000));
        }

        RCLCPP_INFO(node_->get_logger(), "Received URDF from param server");
        return urdf_string;
    }

    //////////////////////////////////////////////////
    GazeboSimROS2ControlPlugin::GazeboSimROS2ControlPlugin()
        : dataPtr(std::make_unique<GazeboSimROS2ControlPluginPrivate>())
    {
    }

    //////////////////////////////////////////////////
    GazeboSimROS2ControlPlugin::~GazeboSimROS2ControlPlugin()
    {
        if (!this->dataPtr->controller_manager_)
        {
            return;
        }
        this->dataPtr->executor_->remove_node(this->dataPtr->controller_manager_);
        this->dataPtr->executor_->cancel();
        this->dataPtr->spin_thread_.join();
    }

    //////////////////////////////////////////////////
    void GazeboSimROS2ControlPlugin::Configure(
        const sim::Entity& _entity,
        const std::shared_ptr<const sdf::Element>& _sdf,
        sim::EntityComponentManager& _ecm,
        sim::EventManager&)
    {
        rclcpp::Logger logger = rclcpp::get_logger("GazeboSimROS2ControlPlugin");
        const auto model = sim::Model(_entity);

        if (!model.Valid(_ecm))
        {
            RCLCPP_ERROR(
                logger,
                "[gz_ros2_control] Failed to initialize because [%s] (Entity=%lu)] is not a model."
                "Please make sure that gz_ros2_control is attached to a valid model.",
                model.Name(_ecm).c_str(), _entity);
            return;
        }

        // Get parameters from SDF
        auto paramFileName = _sdf->Get<std::string>("parameters");
        if (paramFileName.empty())
        {
            RCLCPP_ERROR(
                logger,
                "gz_ros2_control found an empty parameters file. Failed to initialize.");
            return;
        }

        // Process robot_param_node
        auto robot_param_node = _sdf->Get<std::string>("robot_param_node");
        if (!robot_param_node.empty())
        {
            this->dataPtr->robot_param_node_ = robot_param_node;
        }
        RCLCPP_INFO(logger, "robot_param_node is %s", this->dataPtr->robot_param_node_.c_str());

        // Process robot_param
        auto robot_description = _sdf->Get<std::string>("robot_param");
        if (!robot_description.empty())
        {
            this->dataPtr->robot_param_name_ = robot_description;
        }
        RCLCPP_INFO(logger, "robot_param is %s", this->dataPtr->robot_param_name_.c_str());

        // Build command-line arguments
        std::vector<std::string> arguments = {"--ros-args"};
        auto sdfPtr = const_cast<sdf::Element*>(_sdf.get());
        sdf::ElementPtr argument_sdf = sdfPtr->GetElement("parameters");
        while (argument_sdf)
        {
            auto argument = argument_sdf->Get<std::string>();
            arguments.emplace_back(RCL_PARAM_FILE_FLAG);
            arguments.push_back(argument);
            argument_sdf = argument_sdf->GetNextElement("parameters");
        }

        // Controller manager node name
        std::string controllerManagerNodeName{"controller_manager"};
        if (sdfPtr->HasElement("controller_manager_name"))
        {
            controllerManagerNodeName = sdfPtr->GetElement("controller_manager_name")->Get<std::string>();
        }

        // Namespace handling
        std::string ns = "/";
        if (sdfPtr->HasElement("ros"))
        {
            sdf::ElementPtr sdfRos = sdfPtr->GetElement("ros");
            if (sdfRos->HasElement("namespace"))
            {
                ns = sdfRos->GetElement("namespace")->Get<std::string>();
                if (ns.empty() || ns[0] != '/')
                {
                    ns = '/' + ns;
                }
                if (ns.length() > 1)
                {
                    this->dataPtr->robot_param_node_ = ns + "/" + this->dataPtr->robot_param_node_;
                }
            }

            if (sdfRos->HasElement("remapping"))
            {
                sdf::ElementPtr remap_sdf = sdfRos->GetElement("remapping");
                arguments.emplace_back(RCL_ROS_ARGS_FLAG);
                while (remap_sdf)
                {
                    auto remap_rule = remap_sdf->Get<std::string>();
                    arguments.emplace_back(RCL_REMAP_FLAG);
                    arguments.push_back(remap_rule);
                    remap_sdf = remap_sdf->GetNextElement("remapping");
                }
            }
        }

        // Initialize ROS context if needed
        if (!rclcpp::ok())
        {
            RCLCPP_DEBUG_STREAM(logger, "Create default context");
            std::vector<const char*> argv;
            rclcpp::init(static_cast<int>(argv.size()), argv.data());
        }

        // Create node and executor
        std::string node_name = "gz_ros2_control";
        this->dataPtr->node_ = rclcpp::Node::make_shared(node_name, ns);
        this->dataPtr->executor_ = std::make_shared<rclcpp::executors::MultiThreadedExecutor>();
        this->dataPtr->executor_->add_node(this->dataPtr->node_);

        auto spin_func = [this]()
        {
            this->dataPtr->executor_->spin();
        };
        this->dataPtr->spin_thread_ = std::thread(spin_func);

        RCLCPP_DEBUG_STREAM(logger, "Create node " << node_name);

        // Fetch URDF from parameter server
        const auto urdf_string = this->dataPtr->fetchRobotDescription();
        if (urdf_string.empty())
        {
            RCLCPP_ERROR_STREAM(this->dataPtr->node_->get_logger(), "An empty URDF was passed. Exiting.");
            return;
        }

        // Clean URDF by removing comments
        const std::regex comment_pattern(R"(<!--[\s\S]*?-->)");
        const auto rb_arg = std::string("robot_description:=") + std::regex_replace(urdf_string, comment_pattern, "");
        arguments.emplace_back(RCL_PARAM_FLAG);
        arguments.push_back(rb_arg);

        // Set up arguments for rcl context
        std::vector<const char*> argv;
        argv.reserve(arguments.size());
        for (const auto& arg : arguments)
        {
            argv.push_back(arg.data());
        }

        rcl_arguments_t rcl_args = rcl_get_zero_initialized_arguments();
        rcl_ret_t rcl_ret = rcl_parse_arguments(
            static_cast<int>(argv.size()),
            argv.data(), rcl_get_default_allocator(), &rcl_args);

        auto rcl_context =
            this->dataPtr->node_->get_node_base_interface()->get_context()->get_rcl_context();
        rcl_context->global_arguments = rcl_args;

        if (rcl_ret != RCL_RET_OK)
        {
            RCLCPP_ERROR_STREAM(
                this->dataPtr->node_->get_logger(), 
                "Argument parser error: " << rcl_get_error_string().str);
            rcl_reset_error();
            return;
        }

        if (rcl_arguments_get_param_files_count(&rcl_args) < 1)
        {
            RCLCPP_ERROR(this->dataPtr->node_->get_logger(), "Failed to parse input yaml file(s)");
            return;
        }

        RCLCPP_DEBUG_STREAM(
            this->dataPtr->node_->get_logger(), 
            "[gz_ros2_control] Setting up controller for [" << model.Name(_ecm) << "] (Entity=" << _entity << ")].");

        // Collect active joints
        auto activeJoints = this->dataPtr->collectActiveJoints(_entity, _ecm);
        if (activeJoints.empty())
        {
            RCLCPP_DEBUG_STREAM(
                this->dataPtr->node_->get_logger(),
                "[gz_ros2_control] There are no available Joints.");
            return;
        }

        // Parse URDF for hardware info
        std::vector<hardware_interface::HardwareInfo> control_hardware_info;
        try
        {
            control_hardware_info = hardware_interface::parse_control_resources_from_urdf(urdf_string);
        }
        catch (const std::runtime_error& ex)
        {
            RCLCPP_ERROR_STREAM(
                this->dataPtr->node_->get_logger(),
                "Error parsing URDF in gz_ros2_control plugin, plugin not active : " << ex.what());
            return;
        }

        // Setup resource manager
        auto resource_manager_ = std::make_unique<hardware_interface::ResourceManager>();
        try
        {
            resource_manager_->load_urdf(urdf_string, false, false);
        }
        catch (...)
        {
            RCLCPP_ERROR(
                this->dataPtr->node_->get_logger(), 
                "Error initializing URDF to resource manager!");
        }

        // Load simulation interface plugins
        try
        {
            this->dataPtr->loader_ = std::make_shared<pluginlib::ClassLoader<GazeboSimSystemInterface>>(
                "gz_ros2_control",
                "gz_ros2_control::GazeboSimSystemInterface");
        }
        catch (pluginlib::LibraryLoadException& ex)
        {
            RCLCPP_ERROR(
                this->dataPtr->node_->get_logger(), 
                "Failed to create robot simulation interface loader: %s ", 
                ex.what());
            return;
        }

        // Initialize each component
        for (auto& i : control_hardware_info)
        {
            std::string hw_type_str = i.hardware_class_type;
            std::unique_ptr<GazeboSimSystemInterface> sim_system;

            RCLCPP_DEBUG(this->dataPtr->node_->get_logger(), "Load hardware interface %s ...", hw_type_str.c_str());

            try
            {
                sim_system = std::unique_ptr<GazeboSimSystemInterface>(
                    this->dataPtr->loader_->createUnmanagedInstance(hw_type_str));
            }
            catch (pluginlib::PluginlibException& ex)
            {
                RCLCPP_ERROR(
                    this->dataPtr->node_->get_logger(),
                    "The plugin failed to load for some reason. Error: %s\n",
                    ex.what());
                continue;
            }

            if (!sim_system->initSim(
                this->dataPtr->node_,
                activeJoints,
                i,
                _ecm,
                this->dataPtr->update_rate))
            {
                RCLCPP_FATAL(
                    this->dataPtr->node_->get_logger(), 
                    "Could not initialize robot simulation interface");
                return;
            }

            RCLCPP_DEBUG(
                this->dataPtr->node_->get_logger(), 
                "Initialized robot simulation interface %s!", 
                hw_type_str.c_str());

            resource_manager_->import_component(std::move(sim_system), i);
            rclcpp_lifecycle::State state(
                lifecycle_msgs::msg::State::PRIMARY_STATE_ACTIVE,
                hardware_interface::lifecycle_state_names::ACTIVE);
            resource_manager_->set_component_state(i.name, state);
        }

        // Create controller manager
        RCLCPP_INFO(this->dataPtr->node_->get_logger(), "Loading controller_manager");
        rclcpp::NodeOptions options = controller_manager::get_cm_node_options();
        arguments.emplace_back("-r");
        arguments.push_back("__node:=" + controllerManagerNodeName);
        arguments.emplace_back("-r");
        arguments.push_back("__ns:=" + ns);
        options.arguments(arguments);

        this->dataPtr->controller_manager_ = std::make_shared<controller_manager::ControllerManager>(
            std::move(resource_manager_),
            this->dataPtr->executor_,
            controllerManagerNodeName,
            this->dataPtr->node_->get_namespace());

        this->dataPtr->executor_->add_node(this->dataPtr->controller_manager_);

        if (!this->dataPtr->controller_manager_->has_parameter("update_rate"))
        {
            RCLCPP_ERROR_STREAM(
                this->dataPtr->node_->get_logger(),
                "controller manager doesn't have an update_rate parameter");
            return;
        }

        this->dataPtr->update_rate =
            this->dataPtr->controller_manager_->get_parameter("update_rate").as_int();

        this->dataPtr->control_period_ = rclcpp::Duration(
            std::chrono::duration_cast<std::chrono::nanoseconds>(
                std::chrono::duration<double>(1.0 / static_cast<double>(this->dataPtr->update_rate))));

        // Force use_sim_time
        this->dataPtr->controller_manager_->set_parameter(
            rclcpp::Parameter("use_sim_time", rclcpp::ParameterValue(true)));

        this->dataPtr->entity_ = _entity;
    }

    //////////////////////////////////////////////////
    void GazeboSimROS2ControlPlugin::PreUpdate(
        const sim::UpdateInfo& _info,
        sim::EntityComponentManager& /*_ecm*/)
    {
        if (!this->dataPtr->controller_manager_)
        {
            return;
        }

        static bool warned{false};
        if (!warned)
        {
            rclcpp::Duration gazebo_period(_info.dt);
            if (this->dataPtr->control_period_ < _info.dt)
            {
                RCLCPP_ERROR_STREAM(
                    this->dataPtr->node_->get_logger(),
                    "Desired controller update period (" << this->dataPtr->control_period_.seconds() <<
                    " s) is faster than the gazebo simulation period (" <<
                    gazebo_period.seconds() << " s).");
            }
            else if (this->dataPtr->control_period_ > gazebo_period)
            {
                RCLCPP_WARN_STREAM(
                    this->dataPtr->node_->get_logger(),
                    "Desired controller update period (" << this->dataPtr->control_period_.seconds() <<
                    " s) is slower than the gazebo simulation period (" <<
                    gazebo_period.seconds() << " s).");
            }
            warned = true;
        }

        rclcpp::Time sim_time_ros(std::chrono::duration_cast<std::chrono::nanoseconds>(_info.simTime).count(), RCL_ROS_TIME);
        rclcpp::Duration sim_period = sim_time_ros - this->dataPtr->last_update_sim_time_ros_;
        this->dataPtr->controller_manager_->write(sim_time_ros, sim_period);
    }

    //////////////////////////////////////////////////
    void GazeboSimROS2ControlPlugin::PostUpdate(
        const sim::UpdateInfo& _info,
        const sim::EntityComponentManager& /*_ecm*/)
    {
        if (!this->dataPtr->controller_manager_)
        {
            return;
        }

        rclcpp::Time sim_time_ros(std::chrono::duration_cast<std::chrono::nanoseconds>(_info.simTime).count(), RCL_ROS_TIME);
        rclcpp::Duration sim_period = sim_time_ros - this->dataPtr->last_update_sim_time_ros_;

        if (sim_period >= this->dataPtr->control_period_)
        {
            this->dataPtr->last_update_sim_time_ros_ = sim_time_ros;
            this->dataPtr->controller_manager_->read(sim_time_ros, sim_period);
            this->dataPtr->controller_manager_->update(sim_time_ros, sim_period);
        }
    }
