#include "Folder.h"
#include "File.h"

namespace Gorgon::Resource {

// Constructor delegating to File::Self()
Folder::Folder(File &file) : Folder(file.Self()) { }

// Initialize from weak_ptr<File>, default-construct base first
Folder::Folder(std::weak_ptr<File> fileRef) : Folder() {
    this->file = fileRef;
}

void Folder::Prepare() {
    Base::Prepare();
    if (shouldLoadNames) {
        for (auto &childNode : children) {
            const auto &name = childNode.GetName();
            if (!name.empty()) {
                namedList.emplace(name, &childNode);
            }
        }
    }
}

bool Folder::Load(bool shallowMode) {
    if (isFullyLoaded) return true;

    auto sptr = file.lock();
    if (!sptr) {
        return false;
    }

    auto &referencedFile = *sptr;
    if (!dataReader || !dataReader->TryOpen()) {
        return false;
    }

    dataReader->Seek(startOffset - 4);
    auto chunkSize = dataReader->ReadChunkSize();

    bool success = parseData(dataReader, chunkSize, false, shallowMode, true);
    if (success) {
        // Traverse and populate mapping table
        std::vector<Containers::Collection<Base>::ConstIterator> traversalStack;
        traversalStack.emplace_back(begin());

        while (!traversalStack.empty()) {
            auto &iter = traversalStack.back();
            if (!iter.IsValid()) {
                traversalStack.pop_back();
                continue;
            }

            auto &currentObj = *iter;
            iter.Next(); // advance before pushing children

            if (currentObj.Children.GetCount() > 0) {
                traversalStack.emplace_back(currentObj.begin());
            }

            referencedFile.mapping[currentObj.GetGuid()] = &currentObj;
        }

        resolveDependencies(referencedFile);

        if (isFullyLoaded) {
            dataReader->NoLongerNeeded();
            dataReader.reset();
        }
    }

    return success;
}

bool Folder::parseData(std::shared_ptr<Reader> reader, unsigned long totalBytes,
                       bool processOnlyFirst, bool shallowMode, bool performLoading) {
    startOffset = reader->Tell();
    auto limit = reader->Target(totalBytes); // end marker

    if (!performLoading || processOnlyFirst) {
        reader->KeepOpen();
        dataReader = reader;
    }

    auto sptr = file.lock();
    if (!sptr) {
        throw LoadError(LoadError::NoFileObject, "No associated file object exists for this folder.");
    }

    // Instead of while(!target), use position-based loop
    while (reader->Tell() < limit) {
        auto chunkId = reader->ReadGID();
        auto size = reader->ReadChunkSize();

        if (chunkId == GID::Folder_Names) {
            reader->EatChunk(size);
        } else if (chunkId == GID::Folder_Props) {
            shouldLoadNames = reader->ReadBool();
            reader->EatChunk(size - sizeof(bool));
        } else if (performLoading && chunkId == GID::Folder) {
            auto subFolder = new Folder(sptr);
            if (!subFolder->parseData(reader, size, false, false, !shallowMode)) {
                delete subFolder;
                return false;
            }
            children.Add(subFolder);
            if (processOnlyFirst) {
                reader->Seek(limit);
                break;
            }
        } else {
            auto resourcePtr = sptr->LoadChunk(*this, chunkId, size, !performLoading);
            if (resourcePtr) {
                children.Add(resourcePtr);
                if (processOnlyFirst) {
                    reader->Seek(limit);
                    break;
                }
            }
        }
    }

    if (!processOnlyFirst && performLoading) {
        isFullyLoaded = true;
    }

    return true;
}

void Folder::save(Writer &writer) const {
    auto objStart = writer.WriteObjectStart(this);

    writer.WriteChunkHeader(GID::Folder_Props, sizeof(bool));
    writer.WriteBool(shouldLoadNames);

    for (const auto &baseItem : children) {
        baseItem.Save(writer);
    }

    writer.WriteEnd(objStart);
}

Folder *Folder::LoadResource(std::weak_ptr<File> fileRef,
                             std::shared_ptr<Reader> stream,
                             unsigned long size) {
    auto folder = new Folder(fileRef);
    if (!folder->parseData(stream, size, false, false, true)) {
        delete folder;
        return nullptr;
    }
    return folder;
}

