int main(int argc, char *argv[])
{
    // Optional: suppress Qt WebEngine logging (commented out as in original)
    // QLoggingCategory::setFilterRules("qt.webengine*=false");

    // Conditional environment setup for Flatpak builds
#ifdef FLATPAK_BUILD
    QCoreApplication::setApplicationName("Jasmine");
    QCoreApplication::setOrganizationName("");
#else
    QCoreApplication::setApplicationName("Jasmine-local");
    QCoreApplication::setOrganizationName("Jasmine-local");
#endif

    // Load user settings to check GPU acceleration preference
    QSettings userConfig;
    bool gpuAccelerationDisabled = userConfig.value("gpu/disable_acceleration", false).toBool();

    // Apply Chromium flags if GPU acceleration is explicitly disabled
    if (gpuAccelerationDisabled) {
        qputenv("QTWEBENGINE_CHROMIUM_FLAGS", "--disable-gpu");
    }

    QApplication appInstance(argc, argv);

    MainWindow mainWindow;

    // Perform security check at startup; exit early if failed
