static const std::unordered_map<XXH128Hash, GameInfo> sGameDatabaseByHash = {
    {MakeXXH128Hash(0xCFA7E24F43C986F7, 0x051DAF831876C5FD), {.flags = Cart_DRAM48Mbit}}, // Heart of Darkness (Japan) (Prototype)
};

const GameInfo *GetGameInfo(std::string_view productCode, XXH128Hash hash) {
    // First try lookup by product code
    auto it = sGameDatabaseByCode.find(productCode);
    if (it != sGameDatabaseByCode.end()) {
        return &(it->second);
    }

    // Then fall back to hash-based lookup
    auto hashIt = sGameDatabaseByHash.find(hash);
    if (hashIt != sGameDatabaseByHash.end()) {
        return &(hashIt->second);
    }

    // No matching entry found
    return nullptr;
}
