namespace Clipper2Lib
{
  enum class EdgeType { free, upward, downward }; // upward & downward are 'fixed' edges
  enum class IntersectionType { no_intersection, collinear_edges, crossing };
  enum class VertexPosition { none, left_vertex, right_vertex };

  // Forward declarations
  class PointVertex;
  class ConnectionEdge;
  class TriangularFace;

  typedef std::vector<PointVertex*> VertexContainer;
  typedef std::vector<ConnectionEdge*> EdgeContainer;

  class PointVertex {
  public:
    Point64   coordinates;
    EdgeContainer incident_edges;
    bool      is_inner_local_minimum = false;

    PointVertex(const Point64& p64) : coordinates(p64) { 
      incident_edges.reserve(2); 
    };
  };

  class ConnectionEdge {
  public:
    PointVertex* vertex_left = nullptr;
    PointVertex* vertex_right = nullptr;
    PointVertex* vertex_bottom = nullptr;
    PointVertex* vertex_top = nullptr;
    EdgeType     type = EdgeType::free;
    TriangularFace* triangle_above = nullptr;
    TriangularFace* triangle_below = nullptr;
    bool         active_status = false;
    ConnectionEdge* next_in_list = nullptr;
    ConnectionEdge* previous_in_list = nullptr;
  };

  class TriangularFace {
  public:
    ConnectionEdge* sides[3];

    TriangularFace(ConnectionEdge* e1, ConnectionEdge* e2, ConnectionEdge* e3)
    {
      sides[0] = e1;
      sides[1] = e2;
      sides[2] = e3;
    }
  };

  /////////////////////////////////////////////////////////////////////////////
  // Delaunay triangulation class declaration
  /////////////////////////////////////////////////////////////////////////////
  class DelaunayTriangulator {
  private:
    VertexContainer             all_vertices;
    EdgeContainer               all_connections;
    std::vector<TriangularFace*> all_faces;
    std::stack<ConnectionEdge*> pending_delaunay_check;
    std::stack<ConnectionEdge*> horizontal_edge_stack;
    std::stack<PointVertex*> local_minima_stack;
    bool                        enforce_delaunay_condition = true;
    PointVertex*                lowest_vertex = nullptr;
    ConnectionEdge*             first_active_edge = nullptr;

    void AddPolygonPath(const Path64& path);
    bool AddMultiplePaths(const Paths64& paths);
    void CleanupResources();
    bool FixEdgeIntersections();
    void MergeDuplicateOrCollinearPoints();
    void DivideEdge(ConnectionEdge* long_edge, ConnectionEdge* short_edge);
    bool RemoveIntersection(ConnectionEdge* edge1, ConnectionEdge* edge2);
    ConnectionEdge* CreateEdge(PointVertex* v1, PointVertex* v2, EdgeType k);
    TriangularFace* CreateTriangle(ConnectionEdge* e1, ConnectionEdge* e2, ConnectionEdge* e3);
    ConnectionEdge* CreateInnerLocalMinimumFreeEdge(PointVertex* vertex_above);
    ConnectionEdge* HorizontalConnectionBetween(PointVertex* v1, PointVertex* v2);
    void ProcessTriangulationLeft(ConnectionEdge* edge, PointVertex* pivot, int64_t min_y);
    void ProcessTriangulationRight(ConnectionEdge* edge, PointVertex* pivot, int64_t min_y);
    void InsertEdgeIntoActiveList(ConnectionEdge* edge);
    void EraseEdgeFromActiveList(ConnectionEdge* edge);
    void EnsureDelaunayCompliance(ConnectionEdge* edge);

  public:
    explicit DelaunayTriangulator(bool enforce_delaunay = true) : enforce_delaunay_condition(enforce_delaunay) {};
    ~DelaunayTriangulator() { CleanupResources(); };
    Paths64 Execute(const Paths64& paths, TriangulateResult& tri_result);
  };

  /////////////////////////////////////////////////////////////////////////////
  // Utility functions
  /////////////////////////////////////////////////////////////////////////////
  static bool CompareVerticesByYThenX(const PointVertex* a, const PointVertex* b)
  {
    return (a->coordinates.y == b->coordinates.y) ? (a->coordinates.x < b->coordinates.x) : (a->coordinates.y > b->coordinates.y);
  }

  static bool CompareEdgesByLeftX(const ConnectionEdge* a, const ConnectionEdge* b)
  {
    return (a->vertex_left->coordinates.x < b->vertex_left->coordinates.x);
  }

  static bool IsFreeEdge(const ConnectionEdge& e)
  {
    return e.type == EdgeType::free;
  }

  static bool IsAscendingEdge(const ConnectionEdge& e)
  {
    // ascending edge (boundary) of a fill region
    // meaning fills on the **right** side of the edge
    // precondition - e is never a 'free' edge
    return e.type == EdgeType::upward;
  }

  static bool IsDescendingEdge(const ConnectionEdge& e)
  {
    // descending edge (boundary) of a fill region
    // still fills on the **right** side of the edge
    // precondition - e is never a 'free' edge
    return e.type == EdgeType::downward;
  }

  static bool IsHorizontalEdge(const ConnectionEdge& e)
  {
    return e.vertex_bottom->coordinates.y == e.vertex_top->coordinates.y;
  }

  static bool IsCounterClockwiseTurn(const Point64& p1, const Point64& p2, const Point64& p3)
  {
    return CrossProductSign(p1, p2, p3) < 0;
  }

  static bool IsClockwiseTurn(const Point64& p1, const Point64& p2, const Point64& p3)
  {
    return CrossProductSign(p1, p2, p3) > 0;
  }

  static bool IsEdgeComplete(ConnectionEdge* edge)
  {
    if (!edge->triangle_above) return false;
    if (edge->triangle_below) return true;
    return edge->type != EdgeType::free;
  }

  static VertexPosition GetEdgeVertexPosition(const ConnectionEdge* edge, const PointVertex* v)
  {
    if (edge->vertex_left == v) return VertexPosition::left_vertex;
    else if (edge->vertex_right == v) return VertexPosition::right_vertex;
    else return VertexPosition::none;
  }

  static double CalculateAngle(const Point64& a, const Point64& b, const Point64& c)
  {
    // https://stackoverflow.com/a/3487062/359538
    double abx = static_cast<double>(b.x - a.x);
    double aby = static_cast<double>(b.y - a.y);
    double bcx = static_cast<double>(b.x - c.x);
    double bcy = static_cast<double>(b.y - c.y);
    double dot_product = (abx * bcx + aby * bcy);
    double cross_product = (abx * bcy - aby * bcx);
    return std::atan2(cross_product, dot_product); // range between -Pi and Pi
  }

  static double CalculateLocalMinimumAngle(PointVertex* v)
  {
    // todo - recheck the result's sign compared to left vs right turning
    // (currently assumes left turning => positive values)
    // precondition - this function is called before processing local minimum.
    //Assert(v->incident_edges.size() == 2);
    int asc_idx, desc_idx;
    if (v->incident_edges[0]->type == EdgeType::upward)
    {
      asc_idx = 0;
      desc_idx = 1;
    }
    else
    {
      desc_idx = 0;
      asc_idx = 1;
    }
    // winding direction - descending to ascending
    return CalculateAngle(v->incident_edges[desc_idx]->vertex_top->coordinates, v->coordinates, v->incident_edges[asc_idx]->vertex_top->coordinates);
  }

  static void RemoveEdgeFromVertex(PointVertex* vert, ConnectionEdge* edge)
  {
    auto it = std::find(vert->incident_edges.begin(), vert->incident_edges.end(), edge);
    if (it == vert->incident_edges.end()) throw "unexpected error!";
    vert->incident_edges.erase(it);
  }

  static bool FindLocalMinimumIndex(const Path64& path, size_t length, size_t& index)
  {
    if (length < 3) return false;
    size_t start_idx = index, n = (index + 1) % length;
    while (path[n].y <= path[index].y) 
    {
      index = n; n = (n + 1) % length;
      if (index == start_idx) return false; // fails if the path is completely horizontal
    }
    while (path[n].y >= path[index].y)
    {
      index = n; n = (n + 1) % length;
    }
    return true;
  }

  static size_t GetPreviousIndex(size_t& idx, size_t len)
  {
    if (idx == 0) return len - 1; else return idx - 1;
  }

  static size_t GetNextIndex(size_t& idx, size_t len)
  {
    return (idx + 1) % len;
  }

  static ConnectionEdge* FindConnectingEdge(const PointVertex* vert1, const PointVertex* vert2, bool prefer_upward)
  {
    ConnectionEdge* result = nullptr;
    for (auto e : vert1->incident_edges)
    {
      if (e->vertex_left == vert2 || e->vertex_right == vert2)
      {
        if (e->type == EdgeType::free ||
          ((e->type == EdgeType::upward) == prefer_upward)) return e;
        result = e;
      }
    }
    return result;
  }

  static Path64 CreatePathFromTriangle(TriangularFace face)
  { 
    Path64 result_path;
    result_path.reserve(3);
    result_path.push_back(face.sides[0]->vertex_left->coordinates);
    result_path.push_back(face.sides[0]->vertex_right->coordinates);
    const ConnectionEdge& e = *face.sides[1];
    if (e.vertex_left->coordinates == result_path[0] || e.vertex_left->coordinates == result_path[1]) 
      result_path.push_back(e.vertex_right->coordinates);
    else
      result_path.push_back(e.vertex_left->coordinates);
    return result_path;
  }

  static double InCircleTest(const Point64& pointA, const Point64& pointB, 
    const Point64& pointC, const Point64& pointD)
  {
    // Return the determinant value of 3 x 3 matrix ...
    // | ax-dx    ay-dy    Sqr(ax-dx)+Sqr(ay-dy) |
    // | bx-dx    by-dy    Sqr(bx-dx)+Sqr(by-dy) |
    // | cx-dx    cy-dy    Sqr(cx-dx)+Sqr(cy-dy) |
    // The *sign* of the return value is determined by
    // the orientation (CW vs CCW) of ptA, ptB & ptC.
    // precondition - ptA, ptB & ptC make a *non-empty* triangle
    double m00 = static_cast<double>(pointA.x - pointD.x);
    double m01 = static_cast<double>(pointA.y - pointD.y);
    double m02 = (Sqr(m00) + Sqr(m01));
    double m10 = static_cast<double>(pointB.x - pointD.x);
    double m11 = static_cast<double>(pointB.y - pointD.y);
    double m12 = (Sqr(m10) + Sqr(m11));
    double m20 = static_cast<double>(pointC.x - pointD.x);
    double m21 = static_cast<double>(pointC.y - pointD.y);
    double m22 = (Sqr(m20) + Sqr(m21));
    return m00 * (m11 * m22 - m21 * m12) -
      m10 * (m01 * m22 - m21 * m02) +
      m20 * (m01 * m12 - m11 * m02);
  }

  static double DistanceSquaredToSegment(const Point64& point, const Point64& segment_start, const Point64& segment_end)
  {
    // precondition: segment_start ≠ segment_end
    double dx = static_cast<double>(segment_end.x - segment_start.x);
    double dy = static_cast<double>(segment_end.y - segment_start.y);
    //Assert((dx != 0) or (dy != 0)); // ie segment_start ≠ segment_end
    double ax = static_cast<double>(point.x - segment_start.x);
    double ay = static_cast<double>(point.y - segment_start.y);
    //q = (ax * dx + ay * dy) / (dx * dx + dy * dy);
    double q_num = ax * dx + ay * dy;
    if (q_num < 0)  // point is closest to segment_start
      return DistanceSqr(point, segment_start);
    else if (q_num > (Sqr(dx) + Sqr(dy))) // point is closest to segment_end
      return DistanceSqr(point, segment_end);
    else
       return Sqr(ax * dy - dx * ay) / (dx * dx + dy * dy);
  }

  static IntersectionType CheckSegmentsIntersection(const Point64 seg1_start, const Point64 seg1_end, 
    const Point64 seg2_start, const Point64 seg2_end)
  {
    double dy1 = static_cast<double>(seg1_end.y - seg1_start.y);
    double dx1 = static_cast<double>(seg1_end.x - seg1_start.x);
    double dy2 = static_cast<double>(seg2_end.y - seg2_start.y);
    double dx2 = static_cast<double>(seg2_end.x - seg2_start.x);
    double cross_product = dy1 * dx2 - dy2 * dx1;
    if (cross_product == 0) return IntersectionType::collinear_edges;
    double t_param = (static_cast<double>(seg1_start.x - seg2_start.x) * dy2 - 
      static_cast<double>(seg1_start.y - seg2_start.y) * dx2);
    //ignore segments that 'intersect' at an end-point
    if (t_param == 0) return IntersectionType::no_intersection;
    if (t_param > 0)
    {
      if (cross_product < 0 || t_param >= cross_product) return IntersectionType::no_intersection;
    }
    else
    {
      if (cross_product > 0 || t_param <= cross_product) return IntersectionType::no_intersection;
    }
    // so far, the *segment* 's1' intersects the *line* through 's2',
    // but now make sure it also intersects the *segment* 's2'
    t_param = ((seg1_start.x - seg2_start.x) * dy1 - (seg1_start.y - seg2_start.y) * dx1);
    if (t_param == 0) return IntersectionType::no_intersection;
    if (t_param > 0)
    {
      if (cross_product > 0 && t_param < cross_product) return IntersectionType::crossing;
    }
    else
    { 
      if (cross_product < 0 && t_param > cross_product) return IntersectionType::crossing;
    }
    return IntersectionType::no_intersection;
  }

