  void DelaunayTriangulator::CleanupResources()
  {
    for (auto v : all_vertices) delete v;
    all_vertices.clear();
    for (auto e : all_connections) delete e;
    all_connections.clear();
    for (auto t : all_faces) delete t;
    all_faces.clear();
    first_active_edge = nullptr;
    lowest_vertex = nullptr;
   }

  void DelaunayTriangulator::EnsureDelaunayCompliance(ConnectionEdge* edge)
  {
    // don't try to make empty triangles compliant with Delaunay condition
    if (!edge->triangle_above || !edge->triangle_below) return;

    // vertex_a will be assigned the vertex in edge's triangle_above
    // that is NOT an end vertex of edge
    // Likewise, vertex_b will be assigned the vertex in triangle_below
    // that is NOT an end vertex of edge
    // If edge is rotated, vertex_a & vertex_b will become its end vertices.
    PointVertex* vertex_a = nullptr;
    PointVertex* vertex_b = nullptr;

    // Excluding 'edge', edges_a will contain two edges (one from
    // triangle_above and one from triangle_below) that touch edge->vertex_left.
    // And edges_b will contain the two edges that touch edge->vertex_right.

    ConnectionEdge* edges_a[3] = { nullptr, nullptr, nullptr };
    ConnectionEdge* edges_b[3] = { nullptr, nullptr, nullptr };

    for (int i = 0; i < 3; ++i)
    {
      if (edge->triangle_above->sides[i] == edge) continue;
      switch (GetEdgeVertexPosition(edge->triangle_above->sides[i], edge->vertex_left))
      {
      case VertexPosition::left_vertex:
        edges_a[1] = edge->triangle_above->sides[i];
        vertex_a = edge->triangle_above->sides[i]->vertex_right;
        break;
      case VertexPosition::right_vertex:
        edges_a[1] = edge->triangle_above->sides[i];
        vertex_a = edge->triangle_above->sides[i]->vertex_left;
        break;
      default:
        edges_b[1] = edge->triangle_above->sides[i];
      }
    }

    for (int i = 0; i < 3; ++i)
    {
      if (edge->triangle_below->sides[i] == edge) continue;
      switch (GetEdgeVertexPosition(edge->triangle_below->sides[i], edge->vertex_left))
      {
      case VertexPosition::left_vertex:
        edges_a[2] = edge->triangle_below->sides[i];
        vertex_b = edge->triangle_below->sides[i]->vertex_right;
        break;
      case VertexPosition::right_vertex:
        edges_a[2] = edge->triangle_below->sides[i];
        vertex_b = edge->triangle_below->sides[i]->vertex_left;
        break;
      default:
        edges_b[2] = edge->triangle_below->sides[i];
      }
    }

    // InCircleTest requires triangle_above to be a valid triangle
    // if IsEmptyTriangle(triangle_above) then Exit; // slower
    if (CrossProductSign(vertex_a->coordinates, edge->vertex_left->coordinates, edge->vertex_right->coordinates) == 0) return;

    // ict_result - result sign depends on triangle_above's orientation
    double ict_result = InCircleTest(vertex_a->coordinates, edge->vertex_left->coordinates, edge->vertex_right->coordinates, vertex_b->coordinates);
    if (ict_result == 0 || // if on or outside circle then exit
      (IsClockwiseTurn(vertex_a->coordinates, edge->vertex_left->coordinates, edge->vertex_right->coordinates) == (ict_result < 0))) return;

    // TRIANGLES HERE ARE **NOT** DELAUNAY COMPLIANT, SO MAKE THEM SO.
    // NOTE: ONCE WE BEGIN DELAUNAY COMPLIANCE, vertex_left & vertex_right WILL
    // NO LONGER REPRESENT LEFT AND RIGHT VERTEX ORIENTATION.
    // THIS IS MINOR PERFORMANCE EFFICIENCY IS SAFE AS LONG AS
    // THE Triangulate() METHOD IS CALLED ONCE ONLY ON A GIVEN
    // SET OF PATHS

    edge->vertex_left = vertex_a;
    edge->vertex_right = vertex_b;
    edge->triangle_above->sides[0] = edge;

    for (int i = 1; i < 3; ++i)
    {
      edge->triangle_above->sides[i] = edges_a[i];
      if (!edges_a[i]) throw "unexpected error"; // stops compiler warnings 
      if (IsFreeEdge(*edges_a[i]))
        pending_delaunay_check.push(edges_a[i]);

      // since each edge has its own triangle_above and triangle_below, we have to be careful
      // to update the correct one ...
      if (edges_a[i]->triangle_above == edge->triangle_above || edges_a[i]->triangle_below == edge->triangle_above) continue;
      if (edges_a[i]->triangle_above == edge->triangle_below)
        edges_a[i]->triangle_above = edge->triangle_above;
      else if (edges_a[i]->triangle_below == edge->triangle_below)
        edges_a[i]->triangle_below = edge->triangle_above;
      else throw "unexpected error";
    }

    edge->triangle_below->sides[0] = edge;

    for (int i = 1; i < 3; ++i)
    {
      edge->triangle_below->sides[i] = edges_b[i];
      if (!edges_b[i]) throw "unexpected error"; // stops compiler warnings 
      if (IsFreeEdge(*edges_b[i]))
        pending_delaunay_check.push(edges_b[i]);

      // since each edge has its own triangle_above and triangle_below, we have to be careful
      // to update the correct one ...
      if (edges_b[i]->triangle_above == edge->triangle_below || edges_b[i]->triangle_below == edge->triangle_below) continue;
      if (edges_b[i]->triangle_above == edge->triangle_above)
        edges_b[i]->triangle_above = edge->triangle_below;
      else if (edges_b[i]->triangle_below == edge->triangle_above)
        edges_b[i]->triangle_below = edge->triangle_below;
      else throw "unexpected error";
    }
  }

  ConnectionEdge* DelaunayTriangulator::CreateEdge(PointVertex* v1, PointVertex* v2, EdgeType k)
  {
    ConnectionEdge* res = all_connections.emplace_back(new ConnectionEdge());

    if (v1->coordinates.y == v2->coordinates.y)
    {
      res->vertex_bottom = v1; res->vertex_top = v2;
    }
    else if (v1->coordinates.y < v2->coordinates.y)
    {
      res->vertex_bottom = v2; res->vertex_top = v1;
    }
    else
    {
      res->vertex_bottom = v1; res->vertex_top = v2;
    }

    if (v1->coordinates.x <= v2->coordinates.x)
    {
      res->vertex_left = v1; res->vertex_right = v2;
    }
    else
    {
      res->vertex_left = v2; res->vertex_right = v1;
    }

    res->type = k;
    v1->incident_edges.push_back(res);
    v2->incident_edges.push_back(res);

    if (k == EdgeType::free)
    {
      pending_delaunay_check.push(res);
      InsertEdgeIntoActiveList(res);
    }

    return res;
  }

  TriangularFace* DelaunayTriangulator::CreateTriangle(ConnectionEdge* e1, ConnectionEdge* e2, ConnectionEdge* e3)
  {
    TriangularFace* res = all_faces.emplace_back(new TriangularFace(e1, e2, e3));

    // nb: only expire free edges when both sides of these edges have triangles.
    for (int i = 0; i < 3; ++i)       
      if (res->sides[i]->triangle_above)
      {
        res->sides[i]->triangle_below = res;
        // this is the edge's second triangle hence no longer active
        EraseEdgeFromActiveList(res->sides[i]);
      }
      else
      {
        res->sides[i]->triangle_above = res;
        // this is the edge's first triangle, so only remove
        // this edge from actives if it's a fixed edge.
        if (!IsFreeEdge(*res->sides[i])) 
          EraseEdgeFromActiveList(res->sides[i]);
      }

    return res;
  }

  bool DelaunayTriangulator::RemoveIntersection(ConnectionEdge* e1, ConnectionEdge* e2)
  {
    // find which vertex is closest to the other segment
    // (ie not the vertex closest to the intersection point) ...
    PointVertex* v = e1->vertex_left;
    ConnectionEdge* temp_edge = e2;
    double distance = DistanceSquaredToSegment(e1->vertex_left->coordinates, e2->vertex_left->coordinates, e2->vertex_right->coordinates);
    double distance2 = DistanceSquaredToSegment(e1->vertex_right->coordinates, e2->vertex_left->coordinates, e2->vertex_right->coordinates);

    if (distance2 < distance) { distance = distance2; v = e1->vertex_right; }

    distance2 = DistanceSquaredToSegment(e2->vertex_left->coordinates, e1->vertex_left->coordinates, e1->vertex_right->coordinates);
    if (distance2 < distance) { distance = distance2; temp_edge = e1; v = e2->vertex_left; }

    distance2 = DistanceSquaredToSegment(e2->vertex_right->coordinates, e1->vertex_left->coordinates, e1->vertex_right->coordinates);
    if (distance2 < distance) { distance = distance2; temp_edge = e1; v = e2->vertex_right; }

    if (distance > 1.000)
      return false; // Oops - this is not just a simple 'rounding' intersection

    // split 'temp_edge' into 2 edges at 'v'
    PointVertex* v2 = temp_edge->vertex_top;
    RemoveEdgeFromVertex(v2, temp_edge);

    // replace v2 in temp_edge with v
    if (temp_edge->vertex_left == v2) temp_edge->vertex_left = v; 
    else temp_edge->vertex_right = v;

    temp_edge->vertex_top = v;
    v->incident_edges.push_back(temp_edge);
    v->is_inner_local_minimum = false; // #47

    // left turning is angle positive
    if (temp_edge->vertex_bottom->is_inner_local_minimum && CalculateLocalMinimumAngle(temp_edge->vertex_bottom) <= 0)
      temp_edge->vertex_bottom->is_inner_local_minimum = false; // #44, 52

    // finally create a new edge between v and v2 ...
    CreateEdge(v, v2, temp_edge->type);
    return true;
  }

  bool DelaunayTriangulator::FixEdgeIntersections()
  {
    // precondition - edge list must be sorted - ascending on edge->vertex_left->coordinates.x
    for (size_t i1 = 0; i1 < all_connections.size(); ++i1)
    {
      ConnectionEdge* e1 = all_connections[i1];
      // nb: we can safely ignore edges newly created inside this for loop
      for (size_t i2 = i1 + 1; i2 < all_connections.size(); ++i2)
      {
        ConnectionEdge* e2 = all_connections[i2];
        if (e2->vertex_left->coordinates.x >= e1->vertex_right->coordinates.x) 
          break; // all 'e' from now on are too far right

        // 'e2' is inside e1's horizontal region. If 'e2' is also inside
        // e1's vertical region, only then check for an intersection ...
        if (e2->vertex_top->coordinates.y < e1->vertex_bottom->coordinates.y && 
            e2->vertex_bottom->coordinates.y > e1->vertex_top->coordinates.y &&
            (CheckSegmentsIntersection(e2->vertex_left->coordinates, e2->vertex_right->coordinates,
              e1->vertex_left->coordinates, e1->vertex_right->coordinates) == IntersectionType::crossing))
        {
          if (!RemoveIntersection(e2, e1)) 
            return false; // oops!!
        }
        // nb: collinear edges are managed in MergeDuplicateOrCollinearPoints below
      }
    }
    return true;
  }

  void DelaunayTriangulator::DivideEdge(ConnectionEdge* long_edge, ConnectionEdge* short_edge)
  {
    auto old_top = long_edge->vertex_top, new_top = short_edge->vertex_top;

    // remove long_edge from long_edge->vertex_top->incident_edges
    RemoveEdgeFromVertex(old_top, long_edge);

    // shorten long_edge
    long_edge->vertex_top = new_top;
    if (long_edge->vertex_left == old_top) long_edge->vertex_left = new_top;
    else long_edge->vertex_right = new_top;

    // add shortened long_edge to new_top->incident_edges
    new_top->incident_edges.push_back(long_edge);

    // and create a new edge between new_top, old_top
    CreateEdge(new_top, old_top, long_edge->type);
  }

  void DelaunayTriangulator::MergeDuplicateOrCollinearPoints()
  {
    // note: this procedure may add new edges and change the
    // number of edges connected with a given vertex, but it 
    // won't add or delete vertices (so it's safe to use iterators)
    auto v_iter1 = all_vertices.begin();
    for (auto v_iter2 = all_vertices.begin() + 1; v_iter2 != all_vertices.end(); ++v_iter2)
    {
      if ((*v_iter1)->coordinates != (*v_iter2)->coordinates)
      {
        v_iter1 = v_iter2;
        continue;
      }

      // merge v1 & v2
      PointVertex* v1 = *v_iter1, * v2 = *v_iter2;
      if (!v1->is_inner_local_minimum || !v2->is_inner_local_minimum)
        v1->is_inner_local_minimum = false;

      // in all of v2's edges, replace links to v2 with links to v1
      for (auto e : v2->incident_edges)
      {
        if (e->vertex_bottom == v2) e->vertex_bottom = v1;
        else e->vertex_top = v1;
        if (e->vertex_left == v2) e->vertex_left = v1;
        else e->vertex_right = v1;
      }

      // move all of v2's edges to v1
      std::copy(v2->incident_edges.begin(), v2->incident_edges.end(), back_inserter(v1->incident_edges));
      v2->incident_edges.resize(0);

      // excluding horizontals, if pv->incident_edges contains two edges
      // that are *collinear* and share the same bottom coords
      // but have different lengths, split the longer edge at
      // the top of the shorter edge ...
      for (auto it_e = v1->incident_edges.begin(); it_e != v1->incident_edges.end(); ++it_e)
      {
        if (IsHorizontalEdge(*(*it_e)) || (*it_e)->vertex_bottom != v1) continue;

        for (auto it_e2 = it_e + 1; it_e2 != v1->incident_edges.end(); ++it_e2)
        {
          auto e1 = *it_e, e2 = *it_e2;
          if (e2->vertex_bottom != v1 || e1->vertex_top->coordinates.y == e2->vertex_top->coordinates.y ||
            (CrossProductSign(e1->vertex_top->coordinates, v1->coordinates, e2->vertex_top->coordinates) != 0)) continue;

          // we have parallel edges, both heading up from v1->coordinates.
          // split the longer edge at the top of the shorter edge.
          if (e1->vertex_top->coordinates.y < e2->vertex_top->coordinates.y) DivideEdge(e1, e2);
          else DivideEdge(e2, e1);
          break; // because only two edges can be collinear
        }
      }
    }
  }

  ConnectionEdge* DelaunayTriangulator::CreateInnerLocalMinimumFreeEdge(PointVertex* v_above)
  {
    if (!first_active_edge) return nullptr; // oops!!

    int64_t x_above = v_above->coordinates.x;
    int64_t y_above = v_above->coordinates.y;

    // find the closest 'active' edge with a vertex that's not above v_above
    ConnectionEdge* e = first_active_edge, *e_below = nullptr;
    double best_distance = -1.0;

    while (e) 
    { 
      if (e->vertex_left->coordinates.x <= x_above && e->vertex_right->coordinates.x >= x_above &&
        e->vertex_bottom->coordinates.y >= y_above && e->vertex_bottom != v_above && e->vertex_top != v_above &&
        !IsCounterClockwiseTurn(e->vertex_left->coordinates, v_above->coordinates, e->vertex_right->coordinates))
      {
        double d = DistanceSquaredToSegment(v_above->coordinates, e->vertex_left->coordinates, e->vertex_right->coordinates);
        if (!e_below || d < best_distance) // compare e with e_below
        {
          e_below = e;
          best_distance = d;
        }
      }
      e = e->next_in_list;
    }

    if (!e_below) return nullptr; // oops!!

    // get the best vertex from 'e_below'
    PointVertex* v_best = (e_below->vertex_top->coordinates.y <= y_above) ? e_below->vertex_bottom : e_below->vertex_top;
    int64_t x_best = v_best->coordinates.x;
    int64_t y_best = v_best->coordinates.y;

    // make sure no edges intersect 'v_above' and 'v_best' ...
    // todo: active_edges is currently *unsorted* but consider making it
    // a tree structure based on each edge's left and right bounds
    e = first_active_edge;

    if (x_best < x_above)
    {
      while (e)
      {
        if (e->vertex_right->coordinates.x > x_best && e->vertex_left->coordinates.x < x_above &&
          e->vertex_bottom->coordinates.y > y_above && e->vertex_top->coordinates.y < y_best &&
          (CheckSegmentsIntersection(e->vertex_bottom->coordinates, e->vertex_top->coordinates,
            v_best->coordinates, v_above->coordinates) == IntersectionType::crossing))
        {
          v_best = (e->vertex_top->coordinates.y > y_above) ? e->vertex_top : e->vertex_bottom;
          x_best = v_best->coordinates.x;
          y_best = v_best->coordinates.y;
        }
        e = e->next_in_list;
      }
    }
    else
    {
      while (e)
      {
        if (e->vertex_right->coordinates.x < x_best && e->vertex_left->coordinates.x > x_above &&
          e->vertex_bottom->coordinates.y > y_above && e->vertex_top->coordinates.y < y_best &&
          (CheckSegmentsIntersection(e->vertex_bottom->coordinates, e->vertex_top->coordinates,
            v_best->coordinates, v_above->coordinates) == IntersectionType::crossing))
        {
          v_best = e->vertex_top->coordinates.y > y_above ? e->vertex_top : e->vertex_bottom;
          x_best = v_best->coordinates.x;
          y_best = v_best->coordinates.y;
        }
        e = e->next_in_list;
      }
    }

    return CreateEdge(v_best, v_above, EdgeType::free);
  }

  ConnectionEdge* DelaunayTriangulator::HorizontalConnectionBetween(PointVertex* v1, PointVertex* v2)
  {
    int64_t y_coord = v1->coordinates.y, l, r;

    if (v1->coordinates.x > v2->coordinates.x)
    {
      l = v2->coordinates.x;
      r = v1->coordinates.x;
    } 
    else
    {
      l = v1->coordinates.x;
      r = v2->coordinates.x;
    }

    ConnectionEdge* res = first_active_edge;
    while (res)
    {
      if (res->vertex_left->coordinates.y == y_coord && res->vertex_right->coordinates.y == y_coord &&
        res->vertex_left->coordinates.x >= l && res->vertex_right->coordinates.x <= r &&
        (res->vertex_left->coordinates.x != l || res->vertex_right->coordinates.x != r)) break;
      res = res->next_in_list;
    }

    return res;
  }

