#include "PinService.h"

void PinService::setInput(uint8_t pin) {
    pinMode(pin, INPUT);
    pullState[pin] = NOPULL;
}

void PinService::setInputPullup(uint8_t pin) {
    pinMode(pin, INPUT_PULLUP);
    pullState[pin] = PULL_UP;
}

void PinService::setInputPullDown(uint8_t pin) {
    pinMode(pin, INPUT_PULLDOWN);
    pullState[pin] = PULL_DOWN;
}

void PinService::setOutput(uint8_t pin) {
    pinMode(pin, OUTPUT);
}

void PinService::setHigh(uint8_t pin) {
    digitalWrite(pin, HIGH);
    pinMode(pin, OUTPUT); // ensure output mode is set last
}

void PinService::setLow(uint8_t pin) {
    digitalWrite(pin, LOW);
    pinMode(pin, OUTPUT); // ensure output mode is set last
}

bool PinService::read(uint8_t pin) {
    return gpio_get_level(static_cast<gpio_num_t>(pin));
}

void PinService::togglePullup(uint8_t pin) {
    setInput(pullState[pin] == PULL_UP ? pin : pin);
    if (pullState[pin] != PULL_UP)
        setInputPullup(pin);
    else
        setInput(pin);
}

void PinService::togglePullDown(uint8_t pin) {
    setInput(pullState[pin] == PULL_DOWN ? pin : pin);
    if (pullState[pin] != PULL_DOWN)
        setInputPullDown(pin);
    else
        setInput(pin);
}

int PinService::readAnalog(uint8_t pin) {
    pinMode(pin, INPUT);
    return analogRead(pin);
}

bool PinService::setupPwm(uint8_t pin, uint32_t frequencyHz, uint8_t dutyCycle) {
    if (dutyCycle > 100U) dutyCycle = 100U;

    detachSignal(pin);

    uint8_t bitDepth;
    if (frequencyHz > 300000U)      bitDepth = 6;
    else if (frequencyHz > 150000U) bitDepth = 7;
    else if (frequencyHz > 60000U)  bitDepth = 8;
    else if (frequencyHz > 20000U)  bitDepth = 9;
    else                            bitDepth = 10;

    if (!ledcAttach(pin, frequencyHz, bitDepth)) {
        return false;
    }

    const uint32_t maxDuty = (1UL << bitDepth) - 1U;
    const uint32_t targetDuty = static_cast<uint32_t>(dutyCycle) * maxDuty / 100U;

    bool success = ledcWrite(pin, targetDuty);
    if (success) markActivePwmPin(pin);
    return success;
}

bool PinService::setServoAngle(uint8_t pin, uint8_t angle) {
    constexpr int servoFreq = 50;         // Hz
    constexpr int resolution = 14;        // bits

    detachSignal(pin);
    ledcAttach(pin, servoFreq, resolution);

    const uint32_t periodUs = 1000000UL / servoFreq;     // 20000 µs
    const uint32_t maxDuty = (1UL << resolution) - 1;

    uint32_t pulseWidthUs = map(angle, 0, 180, 1000, 2000);
    uint32_t dutyValue = (pulseWidthUs * maxDuty) / periodUs;

    bool ok = ledcWrite(pin, dutyValue);
    if (ok) markActivePwmPin(pin);
    return ok;
}

PinService::pullType PinService::getPullType(uint8_t pin) const {
    return pullState[pin];
}

std::vector<uint8_t> PinService::getConfiguredPullPins() const {
    std::vector<uint8_t> result;
    result.reserve(pullState.size());

    for (auto iter = pullState.begin(); iter != pullState.end(); ++iter) {
        result.push_back(iter->first);
    }
    return result;
}

void PinService::detachSignal(uint8_t pin) {
    if (!isActivePwmPin(pin)) return;

    ledcDetach(pin);
    unmarkActivePwmPin(pin);
}

bool PinService::isActivePwmPin(uint8_t pin) const {
    return std::any_of(activePwmPins.begin(), activePwmPins.end(),
                       [pin](uint8_t p) { return p == pin; });
}

void PinService::markActivePwmPin(uint8_t pin) {
    if (!isActivePwmPin(pin)) {
        activePwmPins.emplace_back(pin);
    }
}

void PinService::unmarkActivePwmPin(uint8_t pin) {
    auto newEnd = std::remove(activePwmPins.begin(), activePwmPins.end(), pin);
    if (newEnd != activePwmPins.end()) {
        activePwmPins.erase(newEnd, activePwmPins.end());
    }
}

