// Internal helper types & forward declarations
using SocketMap = std::map<std::pair<int, int>, nng_socket>;

class StateManager::Impl {
 public:
  explicit Impl(const Logger& logger);
  ~Impl() = default;

  void EstablishConnections();
  void TearDownConnections();
  void Setup(Scene* scene);
  bool IsTimeSource() const;
  bool AreSystemsLinked() const;
  bool IsNetworked() const;
  bool BelongsToThisInstance(const std::string& robot_id);
  bool IsTickActive() const;
  void ConfigureFromJson(const json& cfg);
  TimeNano GetSimTimestamp();
  void PropagateSimTime(TimeNano ts);
  void Activate();
  void Deactivate();
  void SyncPhysicsData(TimeNano timestamp);

 private:
  // Core state flags
  bool is_time_source_flag_;
  bool is_connected_flag_;
  bool is_distributed_flag_;
  bool is_active_flag_;

  // Logging & context
  Logger log_context_;
  Scene* current_scene_ptr_;

  // Network topology info
  int local_scene_index_;
  std::string local_scene_identifier_;
  json network_config_;
  int master_clock_instance_index_;

  // Robot mapping: robot ID → instance index
  std::unordered_map<std::string, int> robot_to_instance_map_;

  // Socket registry: (source_idx, dest_idx) → socket
  SocketMap socket_registry_;

  // Helper functions
  void OpenListeningPorts();
  void InitiateOutboundConnections();
  void CloseAllSockets();
  bool AwaitAcknowledgment(nng_socket&);
  void FetchPhysicsUpdate(int origin_idx);
  void DispatchPhysicsUpdate(const PhysicsStateMessage&);
};

// ============================================================================
// Public API wrappers
StateManager::StateManager(const Logger& logger)
    : pimpl_(std::make_shared<Impl>(logger)) {}

