// ============================================================================
// Implementation of StateManager::Impl

StateManager::Impl::Impl(const Logger& logger)
    : is_time_source_flag_(true),
      is_connected_flag_(false),
      is_distributed_flag_(false),
      is_active_flag_(false),
      log_context_(logger),
      current_scene_ptr_(nullptr),
      local_scene_index_(-1),
      local_scene_identifier_(""),
      network_config_("{}"_json),
      master_clock_instance_index_(-1) {}

void StateManager::Impl::EstablishConnections() {
  if (!is_distributed_flag_ || !is_active_flag_ || is_connected_flag_) {
    return;
  }

  const auto& scenes = network_config_["sim-scenes"];
  const auto& ports_table = network_config_["ports-simstate"];

  // Clear previous sockets
  socket_registry_.clear();

  // Step 1: Set up listening endpoints for incoming connections
  OpenListeningPorts(scenes.size(), ports_table);

  // Step 2: Connect outbound to other instances
  InitiateOutboundConnections(scenes, ports_table);

  is_connected_flag_ = true;
}

void StateManager::Impl::OpenListeningPorts(int num_instances, const json& port_matrix) {
  for (int src = 0; src < num_instances; ++src) {
    if (src == local_scene_index_) continue;

    int listen_port = port_matrix[src][local_scene_index_];
    std::string endpoint = "tcp://*:" + std::to_string(listen_port);

    nng_socket resp_sock{};
    int err = nng_rep0_open(&resp_sock);
    if (err != 0) {
      log_context_.LogWarning(local_scene_identifier_,
                              "[StateManager] Failed to open RESP socket: %d", err);
      continue;
    }

    err = nng_listen(resp_sock, endpoint.c_str(), nullptr, 0);
    if (err != 0) {
      log_context_.LogVerbose(local_scene_identifier_,
                              "[StateManager] Listening failed on %s (code %d)", endpoint.c_str(), err);
    }

    socket_registry_[{src, local_scene_index_}] = resp_sock;
  }
}

void StateManager::Impl::InitiateOutboundConnections(const json& scenes, const json& port_matrix) {
  for (int dst = 0; dst < static_cast<int>(scenes.size()); ++dst) {
    if (dst == local_scene_index_) continue;

    int remote_port = port_matrix[local_scene_index_][dst];
    std::string ip_addr = scenes[dst]["ip"].get<std::string>();
    std::string endpoint = "tcp://" + ip_addr + ":" + std::to_string(remote_port);

    nng_socket req_sock{};
    int err = nng_req0_open(&req_sock);
    if (err != 0) {
      log_context_.LogWarning(local_scene_identifier_,
                              "[StateManager] Failed to open REQ socket: %d", err);
      continue;
    }

    // Retry loop until connection succeeds or shutdown requested
    do {
      if (!is_active_flag_) {
        nng_close(req_sock);
        return;
      }

      err = nng_dial(req_sock, endpoint.c_str(), nullptr, 0);
      if (err != 0) {
        std::this_thread::sleep_for(std::chrono::milliseconds(100));
      }
    } while (err != 0);

    socket_registry_[{local_scene_index_, dst}] = req_sock;
  }
}

void StateManager::Impl::TearDownConnections() {
  for (const auto& [key, sock] : socket_registry_) {
    if (key.first != key.second) {
      int rv = nng_close(sock);
      if (rv != 0) {
        log_context_.LogVerbose(local_scene_identifier_,
                                "[StateManager] Socket close error: %d", rv);
      }
    }
  }
  socket_registry_.clear();
  is_connected_flag_ = false;
}

void StateManager::Impl::Setup(Scene* scene) {
  current_scene_ptr_ = scene;
  local_scene_index_ = -1;
  local_scene_identifier_ = "";
  network_config_ = "{}"_json;
  socket_registry_.clear();
  is_distributed_flag_ = false;
  is_active_flag_ = false;
  is_connected_flag_ = false;
  is_time_source_flag_ = true;
}

bool StateManager::Impl::IsTimeSource() const { return is_time_source_flag_; }
bool StateManager::Impl::AreSystemsLinked() const { return is_connected_flag_; }
bool StateManager::Impl::IsNetworked() const { return is_distributed_flag_; }

bool StateManager::Impl::BelongsToThisInstance(const std::string& robot_id) {
  auto it = robot_to_instance_map_.find(robot_id);
  if (it == robot_to_instance_map_.end()) return false;
  return it->second == local_scene_index_;
}

bool StateManager::Impl::IsTickActive() const { return is_active_flag_; }

void StateManager::Impl::ConfigureFromJson(const json& cfg) {
  if (!current_scene_ptr_) return;

  network_config_ = JsonUtils::GetJsonObject(cfg, Constant::Config::distributed_sim);
  if (network_config_.empty()) return;

  const auto& scenes = network_config_["sim-scenes"];
  local_scene_identifier_ = current_scene_ptr_->GetID();

  // Locate this instance in the list
  local_scene_index_ = -1;
  for (int i = 0; i < static_cast<int>(scenes.size()); ++i) {
    if (scenes[i]["id"] == local_scene_identifier_) {
      local_scene_index_ = i;
      break;
    }
  }
  if (local_scene_index_ == -1) return;

  is_distributed_flag_ = true;
  master_clock_instance_index_ = network_config_["simclock-source"];
  auto& actors = current_scene_ptr_->GetActors();

  // Clock source setup
  if (local_scene_index_ == master_clock_instance_index_) {
    is_time_source_flag_ = true;
    SimClock::Get()->SetExternallySteppedOnly(false);
  } else {
    is_time_source_flag_ = false;
    SimClock::Get()->SetExternallySteppedOnly(true);
  }

  // Populate robot-to-instance map
  robot_to_instance_map_.clear();
  for (auto& actor_ref : actors) {
    if (actor_ref.get().GetType() != ActorType::kRobot) continue;
    auto& robot = static_cast<Robot&>(actor_ref.get());
    const std::string& rid = robot.GetID();
    int inst_idx = -1;

    for (int idx = 0; idx < static_cast<int>(scenes.size()); ++idx) {
      const auto& local_list = scenes[idx]["local-robots"];
      for (const auto& lid : local_list) {
        if (lid == rid) {
          inst_idx = idx;
          break;
        }
      }
      if (inst_idx != -1) break;
    }
    robot_to_instance_map_[rid] = inst_idx;
  }

  // Disable non-local robots' physics/sensors
  for (auto& actor_ref : actors) {
    if (actor_ref.get().GetType() != ActorType::kRobot) continue;
    auto& robot = static_cast<Robot&>(actor_ref.get());
    if (!BelongsToThisInstance(robot.GetID())) {
      robot.SetPhysicsType(PhysicsType::kNonPhysics);
      for (auto& sensor_ref : robot.GetSensors()) {
        sensor_ref.get().SetEnabled(false);
      }
    }
  }
}

bool StateManager::Impl::AwaitAcknowledgment(nng_socket& sock) {
  bool* buffer = nullptr;
  size_t len = 0;
  int rc = NNG_EAGAIN;

  while (rc == NNG_EAGAIN && is_active_flag_) {
    rc = nng_recv(sock, &buffer, &len,
                  NNG_FLAG_ALLOC | NNG_FLAG_NONBLOCK);
  }

  bool success = false;
  if (rc != 0) {
    log_context_.LogWarning(local_scene_identifier_,
                            "[StateManager] Ack recv failed: %d", rc);
  } else if (len <= 0 || buffer == nullptr) {
    log_context_.LogWarning(local_scene_identifier_,
                            "[StateManager] Empty ack payload");
  } else {
    success = *buffer;
  }

  if (buffer) nng_free(buffer, len);
  return success;
}

void StateManager::Impl::FetchPhysicsUpdate(int origin_idx) {
  auto key = std::make_pair(origin_idx, local_scene_index_);
  auto it = socket_registry_.find(key);
  if (it == socket_registry_.end()) return;

  nng_socket& sock = it->second;
  char* raw_data = nullptr;
  size_t data_len = 0;
  int rc = NNG_EAGAIN;

  while (rc == NNG_EAGAIN && is_active_flag_) {
    rc = nng_recv(sock, &raw_data, &data_len,
                  NNG_FLAG_ALLOC | NNG_FLAG_NONBLOCK);
  }

  if (rc != 0 || raw_data == nullptr) {
    log_context_.LogVerbose(local_scene_identifier_,
                            "[StateManager] Physics recv failed: %d", rc);
    return;
  }

  std::string msg_str(raw_data, raw_data + data_len);
  nng_free(raw_data, data_len);

  PhysicsStateMessage msg;
  msg.Deserialize(msg_str);

  TimeNano ts = msg.GetTimeStamp();
  const auto& kinematics = msg.GetPhysicsState();
  const auto& rotors = msg.GetActuatedRotationsState();

  auto& actors = current_scene_ptr_->GetActors();
  for (auto& actor_ref : actors) {
    if (actor_ref.get().GetType() != ActorType::kRobot) continue;
    auto& robot = static_cast<Robot&>(actor_ref.get());
    const std::string& rid = robot.GetID();

    auto k_it = kinematics.find(rid);
    if (k_it != kinematics.end()) {
      robot.UpdateKinematics(k_it->second, ts);
    }

    auto r_it = rotors.find(rid);
    if (r_it != rotors.end()) {
      robot.SetActuatedRotations(r_it->second, ts);
    }
  }

  // Send ACK
  bool ok = true;
  nng_send(sock, &ok, sizeof(ok), 0);
}

TimeNano StateManager::Impl::GetSimTimestamp() {
  auto key = std::make_pair(master_clock_instance_index_, local_scene_index_);
  auto it = socket_registry_.find(key);
  if (it == socket_registry_.end()) return -1;

  nng_socket& sock = it->second;
  TimeNano* buf = nullptr;
  size_t len = 0;
  int rc = NNG_EAGAIN;

  while (rc == NNG_EAGAIN && is_active_flag_) {
    rc = nng_recv(sock, &buf, &len, NNG_FLAG_ALLOC | NNG_FLAG_NONBLOCK);
  }

  if (rc != 0 || buf == nullptr) {
    log_context_.LogVerbose(local_scene_identifier_,
                            "[StateManager] Time recv failed: %d", rc);
    return -1;
  }

  TimeNano new_ts = *buf;
  nng_free(buf, len);

  // Acknowledge receipt
  bool ok = true;
  nng_send(sock, &ok, sizeof(ok), 0);

  return new_ts;
}

void StateManager::Impl::PropagateSimTime(TimeNano ts) {
  void* ptr = &ts;
  for (const auto& [key, sock] : socket_registry_) {
    if (key.first != local_scene_index_ || key.second == local_scene_index_) continue;

    int rc = nng_send(sock, ptr, sizeof(ts), 0);
    if (rc != 0) {
      log_context_.LogVerbose(local_scene_identifier_,
                              "[StateManager] Time send failed: %d", rc);
      continue;
    }

    AwaitAcknowledgment(sock);
  }
}

void StateManager::Impl::DispatchPhysicsUpdate(const PhysicsStateMessage& msg) {
  std::string serialized = msg.Serialize();
  for (const auto& [key, sock] : socket_registry_) {
    if (key.first != local_scene_index_ || key.second == local_scene_index_) continue;

    int rc = nng_send(sock, serialized.data(), serialized.length(), 0);
    if (rc != 0) {
      log_context_.LogVerbose(local_scene_identifier_,
                              "[StateManager] Physics send failed: %d", rc);
    }
    AwaitAcknowledgment(sock);
  }
}

void StateManager::Impl::Activate() { is_active_flag_ = true; }

void StateManager::Impl::Deactivate() {
  is_active_flag_ = false;
  TearDownConnections();
}

void StateManager::Impl::SyncPhysicsData(TimeNano timestamp) {
  // Collect local robot states
  std::unordered_map<std::string, Kinematics> local_kinematics;
  std::unordered_map<std::string, ActuatedRotations> local_rotor_states;

  std::set<int> remote_sources_needed;
  auto& actors = current_scene_ptr_->GetActors();

  for (auto& actor_ref : actors) {
    if (actor_ref.get().GetType() != ActorType::kRobot) continue;
    auto& robot = static_cast<Robot&>(actor_ref.get());
    const std::string& rid = robot.GetID();

    if (BelongsToThisInstance(rid)) {
      local_kinematics.emplace(rid, robot.GetKinematics());

      ActuatedRotations rotor_data;
      for (auto& actuator_ref : robot.GetActuators()) {
        if (actuator_ref.get().GetType() != ActuatorType::kRotor) continue;
        const auto& rotor = static_cast<const Rotor&>(actuator_ref.get());
        const auto& av = rotor.GetActuatedRotations();
        rotor_data.insert(av.begin(), av.end());
      }
      local_rotor_states.emplace(rid, rotor_data);
    } else {
      int inst_idx = robot_to_instance_map_.at(rid);
      remote_sources_needed.insert(inst_idx);
    }
  }

  PhysicsStateMessage full_msg(timestamp, local_kinematics, local_rotor_states);

  // Process actors in original order to ensure deterministic sync sequence
  for (auto& actor_ref : actors) {
    if (actor_ref.get().GetType() != ActorType::kRobot) continue;
    auto& robot = static_cast<Robot&>(actor_ref.get());
    const std::string& rid = robot.GetID();
    int inst_idx = robot_to_instance_map_.at(rid);

    if (BelongsToThisInstance(rid)) {
      // Only send once per instance
      DispatchPhysicsUpdate(full_msg);
      break;
    } else if (remote_sources_needed.count(inst_idx)) {
      FetchPhysicsUpdate(inst_idx);
      remote_sources_needed.erase(inst_idx);
    }
  }
}

