// Helper structures for UV parameter storage
struct UVCoord {
    double x;
    double y;
    double z;
};

struct HomogeneousUVCoord {
    double x;
    double y;
    double z;
    double w;
};

namespace AliasToCoreTechUtils
{
    template<typename SurfaceType>
    CT_OBJECT_ID CreateCTNurbs(SurfaceType& surface, EAliasObjectReference refMode, AlMatrix4x4& transformMatrix)
    {
        constexpr CT_UINT32 ControlPointDimension = 4; // Rational: 4 coords per CV

        CT_UINT32 cvCountU = surface.uNumberOfCVsInclMultiples();
        CT_UINT32 cvCountV = surface.vNumberOfCVsInclMultiples();
        CT_UINT32 orderU = surface.uDegree() + 1;
        CT_UINT32 orderV = surface.vDegree() + 1;

        CT_UINT32 knotVecLenU = surface.realuNumberOfKnots() + 2;
        CT_UINT32 knotVecLenV = surface.realvNumberOfKnots() + 2;

        TArray<CT_DOUBLE> knotValuesU(knotVecLenU);
        TArray<CT_DOUBLE> knotValuesV(knotVecLenV);
        TArray<CT_UINT32> knotMultU(knotVecLenU);
        TArray<CT_UINT32> knotMultV(knotVecLenV);

        // Initialize multiplicity arrays
        knotMultU.Fill(1);
        knotMultV.Fill(1);

        // Fill knot vectors with padding
        surface.realuKnotVector(knotValuesU.GetData() + 1);
        surface.realvKnotVector(knotValuesV.GetData() + 1);

        knotValuesU[0] = knotValuesU[1];
        knotValuesV[0] = knotValuesV[1];

        knotValuesU[knotVecLenU - 1] = knotValuesU[knotVecLenU - 2];
        knotValuesV[knotVecLenV - 1] = knotValuesV[knotVecLenV - 2];

        // Prepare control points array
        int totalCoords = cvCountU * cvCountV * ControlPointDimension;
        TArray<CT_DOUBLE> controlPoints(totalCoords);

        switch (refMode)
        {
        case EAliasObjectReference::WorldReference:
            surface.CVsWorldPositionInclMultiples(controlPoints.GetData());
            break;
        case EAliasObjectReference::ParentReference:
        {
            AlTM worldToLocal(transformMatrix);
            surface.CVsAffectedPositionInclMultiples(worldToLocal, controlPoints.GetData());
            break;
        }
        default: // LocalReference
            surface.CVsUnaffectedPositionInclMultiples(controlPoints.GetData());
            break;
        }

        CT_OBJECT_ID surfaceId = 0;
        CT_IO_ERROR err = CT_SNURBS_IO::Create(
            surfaceId,
            orderU, orderV,
            knotVecLenU, knotVecLenV,
            cvCountU, cvCountV,
            ControlPointDimension,
            controlPoints.GetData(),
            knotValuesU.GetData(), knotValuesV.GetData(),
            knotMultU.GetData(), knotMultV.GetData()
        );

        return (err == IO_OK) ? surfaceId : 0;
    }
}

