CT_OBJECT_ID FAliasCoretechWrapper::Add3DCurve(AlCurve& curve)
{
    curveFormType form = curve.form();
    CT_UINT32 order = curve.degree() + 1;
    CT_UINT32 cvCount = curve.numberOfCVs();
    CT_UINT32 realKnotCount = curve.realNumberOfKnots() + 2;

    TArray<HomogeneousUVCoord> rawCVs(cvCount);
    using RawCVArray = double[4];
    curve.CVsUnaffectedPositionInclMultiples(reinterpret_cast<RawCVArray*>(rawCVs.GetData()));

    TArray<double> ctCVs(cvCount * 4);
    int idx = 0;
    for (CT_UINT32 i = 0; i < cvCount; ++i)
    {
        ctCVs[idx++] = rawCVs[i].x;
        ctCVs[idx++] = rawCVs[i].y;
        ctCVs[idx++] = rawCVs[i].z;
        ctCVs[idx++] = rawCVs[i].w;
    }

    TArray<CT_UINT32> knotMult(realKnotCount);
    knotMult.Fill(1);

    TArray<CT_DOUBLE> knots(realKnotCount);
    curve.realKnotVector(knots.GetData() + 1);
    knots[0] = knots[1];
    knots[realKnotCount - 1] = knots[realKnotCount - 2];

    CT_OBJECT_ID nurbsId;
    CT_IO_ERROR status = CT_CNURBS_IO::Create(
        nurbsId,
        order,
        realKnotCount,
        cvCount,
        4,
        ctCVs.GetData(),
        knots.GetData(),
        knotMult.GetData(),
        knots[0],
        knots[realKnotCount - 1]
    );

    return status ? nurbsId : 0;
}

CT_OBJECT_ID FAliasCoretechWrapper::AddTrimCurve(AlTrimCurve& trimCurve)
{
    boolean isReversed = trimCurve.isReversed();
    curveFormType form = trimCurve.form();
    CT_UINT32 order = trimCurve.degree() + 1;
    CT_UINT32 cvCount = trimCurve.numberOfCVs();
    CT_UINT32 realKnotCount = trimCurve.realNumberOfKnots() + 2;

    TArray<UVCoord> uvPositions(cvCount);
    TArray<double> weights(cvCount);

    using UV2 = double[3];
    trimCurve.CVsUVPosition(weights.GetData(), reinterpret_cast<UV2*>(uvPositions.GetData()));

    TArray<CT_UINT32> knotMult(realKnotCount);
    knotMult.Fill(1);

    TArray<CT_DOUBLE> knots(realKnotCount);
    trimCurve.realKnotVector(knots.GetData() + 1);
    knots[0] = knots[1];
    knots[realKnotCount - 1] = knots[realKnotCount - 2];

    CT_OBJECT_ID d3CurveId = 0;
    CT_OBJECT_ID coedgeId;
    CT_IO_ERROR res = CT_COEDGE_IO::Create(
        coedgeId,
        isReversed ? CT_ORIENTATION::CT_REVERSE : CT_ORIENTATION::CT_FORWARD,
        d3CurveId
    );
    if (res != IO_OK) return 0;

    res = CT_COEDGE_IO::SetUVCurve(
        coedgeId,
        order,
        realKnotCount,
        cvCount,
        3,
        reinterpret_cast<double*>(uvPositions.GetData()),
        knots.GetData(),
        knotMult.GetData(),
        knots[0],
        knots[realKnotCount - 1]
    );
    if (res != IO_OK) return 0;

    // Handle twin curve matching
    AlTrimCurve* twin = trimCurve.getTwinCurve();
    if (twin)
    {
        CT_OBJECT_ID* existingCoedge = AlEdge2CTEdge.Find(twin);
        if (existingCoedge)
        {
            CT_COEDGE_IO::MatchCoedges(*existingCoedge, coedgeId);
        }
        AlEdge2CTEdge.Add(&trimCurve, coedgeId);
    }

    return coedgeId;
}

CT_OBJECT_ID FAliasCoretechWrapper::AddTrimBoundary(AlTrimBoundary& boundary)
{
    AlTrimCurve* currentCurve = boundary.firstCurve();
    CT_LIST_IO coedges;

    while (currentCurve)
    {
        CT_OBJECT_ID coedgeId = AddTrimCurve(*currentCurve);
        if (coedgeId)
        {
            coedges.PushBack(coedgeId);
        }
        currentCurve = currentCurve->nextCurve();
    }

    CT_OBJECT_ID loopId;
    CT_IO_ERROR result = CT_LOOP_IO::Create(loopId, coedges);
    return (result == IO_OK) ? loopId : 0;
}

CT_OBJECT_ID FAliasCoretechWrapper::AddTrimRegion(AlTrimRegion& region, EAliasObjectReference refMode, AlMatrix4x4& matrix, bool orientation)
{
    CT_OBJECT_ID nurbsId = AliasToCoreTechUtils::CreateCTNurbs(region, refMode, matrix);
    if (!nurbsId) return 0;

    CT_LIST_IO boundaries;
    CT_OBJECT_ID faceId;
    CT_ORIENTATION faceOrient = orientation ? CT_ORIENTATION::CT_FORWARD : CT_ORIENTATION::CT_REVERSE;

    AlTrimBoundary* boundary = region.firstBoundary();
    while (boundary)
    {
        CT_OBJECT_ID loopId = AddTrimBoundary(*boundary);
        if (loopId)
        {
            boundaries.PushBack(loopId);
        }
        boundary = boundary->nextBoundary();
    }

    CT_IO_ERROR res = CT_FACE_IO::Create(faceId, nurbsId, faceOrient, boundaries);
    return (res == IO_OK) ? faceId : 0;
}

void FAliasCoretechWrapper::AddFace(AlSurface& surface, EAliasObjectReference refMode, AlMatrix4x4& matrix, bool orientation, CT_LIST_IO& outFaceList)
{
    AlTrimRegion* trimRegion = surface.firstTrimRegion();
    if (trimRegion)
    {
        do
        {
            CT_OBJECT_ID faceId = AddTrimRegion(*trimRegion, refMode, matrix, orientation);
            if (faceId)
            {
                outFaceList.PushBack(faceId);
            }
            trimRegion = trimRegion->nextRegion();
        } while (trimRegion);
        return;
    }

    CT_OBJECT_ID nurbsId = AliasToCoreTechUtils::CreateCTNurbs(surface, refMode, matrix);
    CT_LIST_IO emptyBoundaries;
    CT_OBJECT_ID faceId;
    CT_ORIENTATION faceOrient = orientation ? CT_ORIENTATION::CT_FORWARD : CT_ORIENTATION::CT_REVERSE;

    CT_IO_ERROR res = CT_FACE_IO::Create(faceId, nurbsId, faceOrient, emptyBoundaries);
    if (res == IO_OK)
    {
        outFaceList.PushBack(faceId);
    }
}

void FAliasCoretechWrapper::AddShell(AlShell& shell, EAliasObjectReference refMode, AlMatrix4x4& matrix, bool orientation, CT_LIST_IO& outFaceList)
{
    AlTrimRegion* trimRegion = shell.firstTrimRegion();
    while (trimRegion)
    {
        CT_OBJECT_ID faceId = AddTrimRegion(*trimRegion, refMode, matrix, orientation);
        if (faceId)
        {
            outFaceList.PushBack(faceId);
        }
        trimRegion = trimRegion->nextRegion();
    }
}

CT_IO_ERROR FAliasCoretechWrapper::AddBRep(TArray<AlDagNode*>& dagNodes, EAliasObjectReference refMode)
{
    if (!IsSessionValid())
        return IO_ERROR;

    CT_LIST_IO faceList;
    AlEdge2CTEdge.Empty();

    for (auto node : dagNodes)
    {
        if (!node) continue;

        boolean alOrientation;
        node->getSurfaceOrientation(alOrientation);
        bool orient = static_cast<bool>(alOrientation);

        AlMatrix4x4 localMatrix;
        if (refMode == EAliasObjectReference::ParentReference)
        {
            node->localTransformationMatrix(localMatrix);
        }

        switch (node->type())
        {
        case kShellNodeType:
        {
            AlShellNode* shellNode = node->asShellNodePtr();
            if (shellNode)
            {
                AlShell* shell = shellNode->shell();
                if (shell)
                {
                    AddShell(*shell, refMode, localMatrix, orient, faceList);
                }
            }
            break;
        }
        case kSurfaceNodeType:
        {
            AlSurfaceNode* surfNode = node->asSurfaceNodePtr();
            if (surfNode)
            {
                AlSurface* surface = surfNode->surface();
                if (surface)
                {
                    AddFace(*surface, refMode, localMatrix, orient, faceList);
                }
            }
            break;
        }
        }
    }

    if (faceList.IsEmpty())
        return IO_ERROR;

    CT_OBJECT_ID bodyId;
    CT_IO_ERROR res = CT_BODY_IO::CreateFromFaces(
        bodyId,
        CT_BODY_PROP::CT_BODY_PROP_EXACT | CT_BODY_PROP::CT_BODY_PROP_CLOSE,
        faceList
    );
    if (res != IO_OK)
        return res;

    CT_LIST_IO bodies;
    bodies.PushBack(bodyId);
    return CT_COMPONENT_IO::AddChildren(MainObjectId, bodies);
}

TSharedPtr<FAliasCoretechWrapper> FAliasCoretechWrapper::GetSharedSession()
{
    TSharedPtr<FAliasCoretechWrapper> session = SharedSession.Pin();
    if (!session.IsValid())
    {
        session = MakeShared<FAliasCoretechWrapper>(TEXT("Al2CTSharedSession"));
        SharedSession = session;
    }
    return session;
}

