#include "collision_trimesh_internal.h"

// largest number, double or float
#if defined(dSINGLE)
  #define MAXVALUE FLT_MAX
#else
  #define MAXVALUE DBL_MAX
#endif

// Vector operations macros - renamed for clarity
#define VECTOR_SUBTRACT(v1, v2, result) do { \
    (result)[0] = (v1)[0] - (v2)[0]; \
    (result)[1] = (v1)[1] - (v2)[1]; \
    (result)[2] = (v1)[2] - (v2)[2]; \
} while(0)

#define VECTOR_ASSIGN(dest, src) do { \
    (dest)[0] = (src)[0]; \
    (dest)[1] = (src)[1]; \
    (dest)[2] = (src)[2]; \
} while(0)

#define MATRIX_COLUMN_EXTRACT(matrix, col_index, vector) do { \
    (vector)[0] = (matrix)[(col_index)]; \
    (vector)[1] = (matrix)[(col_index) + 4]; \
    (vector)[2] = (matrix)[(col_index) + 8]; \
} while(0)

#define VECTOR_ADD(v1, v2, result) do { \
    (result)[0] = (v1)[0] + (v2)[0]; \
    (result)[1] = (v1)[1] + (v2)[1]; \
    (result)[2] = (v1)[2] + (v2)[2]; \
} while(0)

#define PLANE_DISTANCE(plane, point) \
    ((plane)[0] * (point)[0] + (plane)[1] * (point)[1] + (plane)[2] * (point)[2] + (plane)[3])

#define BUILD_PLANE(plane, normal, distance) do { \
    (plane)[0] = (normal)[0]; \
    (plane)[1] = (normal)[1]; \
    (plane)[2] = (normal)[2]; \
    (plane)[3] = (distance); \
} while(0)

#define VECTOR_MAGNITUDE(vec) \
    dSqrt((vec)[0] * (vec)[0] + (vec)[1] * (vec)[1] + (vec)[2] * (vec)[2])

// Data structures for collision detection
static dMatrix3 boxRotation;
static dVector3 boxPosition;
static dVector3 boxHalfExtents;

static dVector3 triangleVertex0;
static dVector3 triangleVertex1;
static dVector3 triangleVertex2;

static dVector3 bestCollisionNormal;
static dReal minimumPenetrationDepth;
static int bestAxisIndex = 0;
static int exitAxisIndex = -1;

static dVector3 edgeVector0, edgeVector1, edgeVector2, triangleNormal;

// Contact generation parameters
static int contactFlags;
static dContactGeom *contactPoints;
static int contactStride;
static dxGeom *geometry1;
static dxGeom *geometry2;
static int contactCount = 0;

// Test triangle face normal as potential separating axis
static bool testTriangleFaceNormal(dReal proj0, dReal radius, const dVector3 &faceNormal, int axisId) 
{
    dReal penetration = radius + proj0;

    if (penetration < 0.0f) {
        return false;
    }

    dReal normalLength = VECTOR_MAGNITUDE(faceNormal);
    if (normalLength > 0.0f) {
        dReal invLength = 1.0f / normalLength;
        penetration *= invLength;

        if (penetration < minimumPenetrationDepth) {
            bestCollisionNormal[0] = -faceNormal[0] * invLength;
            bestCollisionNormal[1] = -faceNormal[1] * invLength;
            bestCollisionNormal[2] = -faceNormal[2] * invLength;
            bestAxisIndex = axisId;
            minimumPenetrationDepth = penetration;
        }
    }
    return true;
}

// Test box face axes as potential separating axes
static bool testBoxFaceAxes(dReal p0, dReal p1, dReal p2, dReal halfSize, dReal planeDist,
                            dVector3 &axisVector, int axisId) 
{
    // Find triangle projection interval bounds
    dReal triMin, triMax;

    if (p0 <= p1 && p0 <= p2) {
        triMin = p0;
        if (p1 >= p2) triMax = p1; else triMax = p2;
    } else if (p1 <= p0 && p1 <= p2) {
        triMin = p1;
        if (p0 >= p2) triMax = p0; else triMax = p2;
    } else {
        triMin = p2;
        if (p0 >= p1) triMax = p0; else triMax = p1;
    }

    // Calculate overlap depths
    dReal depthNegative = halfSize - triMin;
    dReal depthPositive = triMax + halfSize;

    if (depthNegative < 0.0f || depthPositive < 0.0f) {
        return false;
    }

    dReal penetrationDepth;

    if (depthNegative > depthPositive) {
        penetrationDepth = depthPositive;
        // Flip normal direction
        axisVector[0] = -axisVector[0];
        axisVector[1] = -axisVector[1];
        axisVector[2] = -axisVector[2];
        planeDist = -planeDist;
    } else {
        penetrationDepth = depthNegative;
    }

    if (penetrationDepth < minimumPenetrationDepth) {
        VECTOR_ASSIGN(bestCollisionNormal, axisVector);
        bestAxisIndex = axisId;
        minimumPenetrationDepth = penetrationDepth;
    }
    return true;
}

// Test cross product axes (box edges × triangle edges) as potential separating axes
static bool testEdgeCrossProducts(dReal p0, dReal p1, dReal halfSize, dReal planeDist,
                                  dVector3 &axisVector, int axisId) 
{
    dReal triMin = (p0 <= p1) ? p0 : p1;
    dReal triMax = (p0 >= p1) ? p0 : p1;

    dReal depthNegative = halfSize - triMin;
    dReal depthPositive = triMax + halfSize;

    if (depthNegative < 0.0f || depthPositive < 0.0f) {
        return false;
    }

    dReal penetrationDepth;

    if (depthNegative > depthPositive) {
        penetrationDepth = depthPositive;
        axisVector[0] = -axisVector[0];
        axisVector[1] = -axisVector[1];
        axisVector[2] = -axisVector[2];
        planeDist = -planeDist;
    } else {
        penetrationDepth = depthNegative;
    }

    dReal axisLength = VECTOR_MAGNITUDE(axisVector);
    if (axisLength > 0.0f) {
        dReal invLength = 1.0f / axisLength;
        penetrationDepth *= invLength;
        planeDist *= invLength;

        // Favor face tests over edge tests by requiring better depth
        if (penetrationDepth * 1.5f < minimumPenetrationDepth) {
            bestCollisionNormal[0] = axisVector[0] * invLength;
            bestCollisionNormal[1] = axisVector[1] * invLength;
            bestCollisionNormal[2] = axisVector[2] * invLength;
            bestAxisIndex = axisId;
            minimumPenetrationDepth = penetrationDepth;
        }
    }
    return true;
}

// Clip polygon against plane using Sutherland-Hodgman algorithm
static void clipPolygonToPlane(dVector3 inputVertices[], int inputCount,
                               dVector3 outputVertices[], int &outputCount,
                               const dVector4 &plane) 
{
    outputCount = 0;
    int prevIndex = inputCount - 1;

    for (int currIndex = 0; currIndex < inputCount; prevIndex = currIndex, currIndex++) {
        dReal distPrev = PLANE_DISTANCE(plane, inputVertices[prevIndex]);
        dReal distCurr = PLANE_DISTANCE(plane, inputVertices[currIndex]);

        // If previous vertex is on front side, add it to output
        if (distPrev >= 0.0f) {
            VECTOR_ASSIGN(outputVertices[outputCount], inputVertices[prevIndex]);
            outputCount++;
        }

        // If vertices are on opposite sides, add intersection point
        if ((distPrev > 0.0f && distCurr < 0.0f) || (distPrev < 0.0f && distCurr > 0.0f)) {
            dVector3 intersectionPoint;
            dReal t = distPrev / (distPrev - distCurr);

            intersectionPoint[0] = inputVertices[prevIndex][0] + t * (inputVertices[currIndex][0] - inputVertices[prevIndex][0]);
            intersectionPoint[1] = inputVertices[prevIndex][1] + t * (inputVertices[currIndex][1] - inputVertices[prevIndex][1]);
            intersectionPoint[2] = inputVertices[prevIndex][2] + t * (inputVertices[currIndex][2] - inputVertices[prevIndex][2]);

            VECTOR_ASSIGN(outputVertices[outputCount], intersectionPoint);
            outputCount++;
        }
    }
}

// Main separation axis test function
static bool checkSeparatingAxes(const dVector3 &v0, const dVector3 &v1, const dVector3 &v2) 
{
    // Reset state
    bestAxisIndex = 0;
    exitAxisIndex = -1;
    minimumPenetrationDepth = MAXVALUE;

    // Compute triangle edges
    VECTOR_SUBTRACT(v1, v0, edgeVector0);
    VECTOR_SUBTRACT(v2, v0, edgeVector1);
    VECTOR_SUBTRACT(edgeVector1, edgeVector0, edgeVector2);

    // Compute triangle normal
    dCROSS(triangleNormal, =, edgeVector0, edgeVector1);

    // Extract box axes
    dVector3 boxAxes[3];
    MATRIX_COLUMN_EXTRACT(boxRotation, 0, boxAxes[0]);
    MATRIX_COLUMN_EXTRACT(boxRotation, 1, boxAxes[1]);
    MATRIX_COLUMN_EXTRACT(boxRotation, 2, boxAxes[2]);

    // Relative position vector
    dVector3 relPos;
    VECTOR_SUBTRACT(v0, boxPosition, relPos);

    // Triangle normal length
    dReal normalLen = VECTOR_MAGNITUDE(triangleNormal);

    // Test 1: Triangle face normal
    VECTOR_ASSIGN(bestCollisionNormal, triangleNormal);
    dReal proj0 = dDOT(triangleNormal, relPos);
    dReal radius = boxHalfExtents[0] * dFabs(dDOT(triangleNormal, boxAxes[0])) +
                   boxHalfExtents[1] * dFabs(dDOT(triangleNormal, boxAxes[1])) +
                   boxHalfExtents[2] * dFabs(dDOT(triangleNormal, boxAxes[2]));

    if (!testTriangleFaceNormal(proj0, radius, bestCollisionNormal, 1)) {
        exitAxisIndex = 1;
        return false;
    }

    // Test 2-4: Box face normals
    for (int i = 0; i < 3; i++) {
        VECTOR_ASSIGN(bestCollisionNormal, boxAxes[i]);
        dReal planeDist = dDOT(bestCollisionNormal, triangleNormal) / normalLen;
        dReal projV0 = dDOT(bestCollisionNormal, relPos);
        dReal projE0 = dDOT(boxAxes[i], edgeVector0);
        dReal projE1 = dDOT(boxAxes[i], edgeVector1);

        if (!testBoxFaceAxes(projV0, projV0 + projE0, projV0 + projE1, boxHalfExtents[i], planeDist, 
                            bestCollisionNormal, i + 2)) {
            exitAxisIndex = i + 2;
            return false;
        }
    }

    // Test 5-13: Edge cross products
    dVector3 crossProduct;

    // Box X-axis cross triangle edges
    dCROSS(crossProduct, =, boxAxes[0], edgeVector0);
    dReal pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    dReal projX0 = dDOT(crossProduct, relPos);
    dReal projXN = dDOT(boxAxes[0], triangleNormal);
    dReal radX0 = boxHalfExtents[1] * dFabs(dDOT(boxAxes[2], edgeVector0)) + 
                  boxHalfExtents[2] * dFabs(dDOT(boxAxes[1], edgeVector0));

    if (!testEdgeCrossProducts(projX0, projX0 + projXN, radX0, pd0, crossProduct, 5)) {
        exitAxisIndex = 5;
        return false;
    }

    dCROSS(crossProduct, =, boxAxes[0], edgeVector1);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal radX1 = boxHalfExtents[1] * dFabs(dDOT(boxAxes[2], edgeVector1)) + 
                  boxHalfExtents[2] * dFabs(dDOT(boxAxes[1], edgeVector1));

    if (!testEdgeCrossProducts(projX0 - projXN, projX0, radX1, pd0, crossProduct, 6)) {
        exitAxisIndex = 6;
        return false;
    }

    dCROSS(crossProduct, =, boxAxes[0], edgeVector2);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal radX2 = boxHalfExtents[1] * dFabs(dDOT(boxAxes[2], edgeVector2)) + 
                  boxHalfExtents[2] * dFabs(dDOT(boxAxes[1], edgeVector2));

    if (!testEdgeCrossProducts(projX0 - projXN, projX0 - projXN, radX2, pd0, crossProduct, 7)) {
        exitAxisIndex = 7;
        return false;
    }

    // Box Y-axis cross triangle edges
    dCROSS(crossProduct, =, boxAxes[1], edgeVector0);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal projYN = dDOT(boxAxes[1], triangleNormal);
    dReal radY0 = boxHalfExtents[0] * dFabs(dDOT(boxAxes[2], edgeVector0)) + 
                  boxHalfExtents[2] * dFabs(dDOT(boxAxes[0], edgeVector0));

    if (!testEdgeCrossProducts(projX0, projX0 + projYN, radY0, pd0, crossProduct, 8)) {
        exitAxisIndex = 8;
        return false;
    }

    dCROSS(crossProduct, =, boxAxes[1], edgeVector1);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal radY1 = boxHalfExtents[0] * dFabs(dDOT(boxAxes[2], edgeVector1)) + 
                  boxHalfExtents[2] * dFabs(dDOT(boxAxes[0], edgeVector1));

    if (!testEdgeCrossProducts(projX0 - projYN, projX0, radY1, pd0, crossProduct, 9)) {
        exitAxisIndex = 9;
        return false;
    }

    dCROSS(crossProduct, =, boxAxes[1], edgeVector2);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal radY2 = boxHalfExtents[0] * dFabs(dDOT(boxAxes[2], edgeVector2)) + 
                  boxHalfExtents[2] * dFabs(dDOT(boxAxes[0], edgeVector2));

    if (!testEdgeCrossProducts(projX0 - projYN, projX0 - projYN, radY2, pd0, crossProduct, 10)) {
        exitAxisIndex = 10;
        return false;
    }

    // Box Z-axis cross triangle edges
    dCROSS(crossProduct, =, boxAxes[2], edgeVector0);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal projZN = dDOT(boxAxes[2], triangleNormal);
    dReal radZ0 = boxHalfExtents[0] * dFabs(dDOT(boxAxes[1], edgeVector0)) + 
                  boxHalfExtents[1] * dFabs(dDOT(boxAxes[0], edgeVector0));

    if (!testEdgeCrossProducts(projX0, projX0 + projZN, radZ0, pd0, crossProduct, 11)) {
        exitAxisIndex = 11;
        return false;
    }

    dCROSS(crossProduct, =, boxAxes[2], edgeVector1);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal radZ1 = boxHalfExtents[0] * dFabs(dDOT(boxAxes[1], edgeVector1)) + 
                  boxHalfExtents[1] * dFabs(dDOT(boxAxes[0], edgeVector1));

    if (!testEdgeCrossProducts(projX0 - projZN, projX0, radZ1, pd0, crossProduct, 12)) {
        exitAxisIndex = 12;
        return false;
    }

    dCROSS(crossProduct, =, boxAxes[2], edgeVector2);
    pd0 = dDOT(crossProduct, triangleNormal) / normalLen;
    projX0 = dDOT(crossProduct, relPos);
    dReal radZ2 = boxHalfExtents[0] * dFabs(dDOT(boxAxes[1], edgeVector2)) + 
                  boxHalfExtents[1] * dFabs(dDOT(boxAxes[0], edgeVector2));

    if (!testEdgeCrossProducts(projX0 - projZN, projX0 - projZN, radZ2, pd0, crossProduct, 13)) {
        exitAxisIndex = 13;
        return false;
    }

    return true;
}

// Find closest points on two lines in 3D space
static bool findClosestPointsOnLines(const dVector3 &point1, const dVector3 &dir1,
                                     const dVector3 &point2, const dVector3 &dir2,
                                     dReal &param1, dReal &param2) 
{
    dVector3 diff;
    VECTOR_SUBTRACT(point2, point1, diff);

    dReal dotDirs = dDOT(dir1, dir2);
    dReal dot1 = dDOT(dir1, diff);
    dReal dot2 = -dDOT(dir2, diff);
    dReal denom = 1.0f - dotDirs * dotDirs;

    if (denom > 0.0f) {
        denom = 1.0f / denom;
        param1 = (dot1 + dotDirs * dot2) * denom;
        param2 = (dotDirs * dot1 + dot2) * denom;
        return true;
    } else {
        param1 = 0.0f;
        param2 = 0.0f;
        return false;
    }
}

// Generate contacts through clipping
static void generateContacts(const dVector3 &v0, const dVector3 &v1, const dVector3 &v2) 
{
    if (bestAxisIndex > 4) {
        // Edge-edge contact case
        dVector3 boxPoint;
        VECTOR_ASSIGN(boxPoint, boxPosition);

        // Calculate box edge point based on collision normal
        for (int i = 0; i < 3; i++) {
            dVector3 rotationCol;
            MATRIX_COLUMN_EXTRACT(boxRotation, i, rotationCol);
            dReal sign = dDOT(bestCollisionNormal, rotationCol) > 0 ? 1.0f : -1.0f;
            boxPoint[0] += sign * boxHalfExtents[i] * rotationCol[0];
            boxPoint[1] += sign * boxHalfExtents[i] * rotationCol[1];
            boxPoint[2] += sign * boxHalfExtents[i] * rotationCol[2];
        }

        int edgeIndex = (bestAxisIndex - 5) % 3;
        dVector3 triPoint, triDir;

        switch (edgeIndex) {
            case 0:
                VECTOR_ASSIGN(triPoint, v0);
                VECTOR_ASSIGN(triDir, edgeVector0);
                break;
            case 1:
                VECTOR_ASSIGN(triPoint, v2);
                VECTOR_ASSIGN(triDir, edgeVector1);
                break;
            default:
                VECTOR_ASSIGN(triPoint, v1);
                VECTOR_ASSIGN(triDir, edgeVector2);
                break;
        }

        dNormalize3(triDir);
        dReal param1, param2;

        int colIndex = (bestAxisIndex - 5) / 3;
        dVector3 boxDir;
        MATRIX_COLUMN_EXTRACT(boxRotation, colIndex, boxDir);

        findClosestPointsOnLines(boxPoint, boxDir, triPoint, triDir, param1, param2);

        boxPoint[0] += boxDir[0] * param1;
        boxPoint[1] += boxDir[1] * param1;
        boxPoint[2] += boxDir[2] * param1;

        triPoint[0] += triDir[0] * param2;
        triPoint[1] += triDir[1] * param2;
        triPoint[2] += triDir[2] * param2;

        dVector3 contactPos;
        VECTOR_ADD(boxPoint, triPoint, contactPos);
        contactPos[0] *= 0.5f;
        contactPos[1] *= 0.5f;
        contactPos[2] *= 0.5f;

        dContactGeom* contact = SAFECONTACT(contactFlags, contactPoints, contactCount, contactStride);
        contact->depth = minimumPenetrationDepth;
        VECTOR_ASSIGN(contact->normal, bestCollisionNormal);
        VECTOR_ASSIGN(contact->pos, contactPos);
        contact->g1 = geometry1;
        contact->g2 = geometry2;
        contactCount++;
    } 
    else if (bestAxisIndex == 1) {
        // Face contact case - clip box face to triangle
        dVector3 negNormal;
        negNormal[0] = -bestCollisionNormal[0];
        negNormal[1] = -bestCollisionNormal[1];
        negNormal[2] = -bestCollisionNormal[2];

        // Transform normal to box local space
        dMatrix3 transposed;
        transposed[0] = boxRotation[0]; transposed[1] = boxRotation[4]; transposed[2] = boxRotation[8];
        transposed[3] = boxRotation[1]; transposed[4] = boxRotation[5]; transposed[5] = boxRotation[9];
        transposed[6] = boxRotation[2]; transposed[7] = boxRotation[6]; transposed[8] = boxRotation[10];

        dVector3 localNormal;
        localNormal[0] = transposed[0] * negNormal[0] + transposed[1] * negNormal[1] + transposed[2] * negNormal[2];
        localNormal[1] = transposed[3] * negNormal[0] + transposed[4] * negNormal[1] + transposed[5] * negNormal[2];
        localNormal[2] = transposed[6] * negNormal[0] + transposed[7] * negNormal[1] + transposed[8] * negNormal[2];

        dVector3 absNormal;
        absNormal[0] = dFabs(localNormal[0]);
        absNormal[1] = dFabs(localNormal[1]);
        absNormal[2] = dFabs(localNormal[2]);

        // Determine primary axis
        int axis0, axis1, axis2;
        if (absNormal[1] > absNormal[0]) {
            if (absNormal[1] > absNormal[2]) {
                axis1 = 0; axis0 = 1; axis2 = 2;
            } else {
                axis1 = 0; axis2 = 1; axis0 = 2;
            }
        } else {
            if (absNormal[0] > absNormal[2]) {
                axis0 = 0; axis1 = 1; axis2 = 2;
            } else {
                axis1 = 0; axis2 = 1; axis0 = 2;
            }
        }

        // Get box face center
        dVector3 faceCenter;
        dVector3 colVec;
        MATRIX_COLUMN_EXTRACT(boxRotation, axis0, colVec);

        if (localNormal[axis0] > 0) {
            faceCenter[0] = boxPosition[0] - v0[0] - boxHalfExtents[axis0] * colVec[0];
            faceCenter[1] = boxPosition[1] - v0[1] - boxHalfExtents[axis0] * colVec[1];
            faceCenter[2] = boxPosition[2] - v0[2] - boxHalfExtents[axis0] * colVec[2];
        } else {
            faceCenter[0] = boxPosition[0] - v0[0] + boxHalfExtents[axis0] * colVec[0];
            faceCenter[1] = boxPosition[1] - v0[1] + boxHalfExtents[axis0] * colVec[1];
            faceCenter[2] = boxPosition[2] - v0[2] + boxHalfExtents[axis0] * colVec[2];
        }

        // Get four corners of box face
        dVector3 faceCorners[4];
        dVector3 colVec2;
        MATRIX_COLUMN_EXTRACT(boxRotation, axis1, colVec);
        MATRIX_COLUMN_EXTRACT(boxRotation, axis2, colVec2);

        for (int i = 0; i < 3; i++) {
            faceCorners[0][i] = faceCenter[i] + boxHalfExtents[axis1] * colVec[i] - boxHalfExtents[axis2] * colVec2[i];
            faceCorners[1][i] = faceCenter[i] - boxHalfExtents[axis1] * colVec[i] - boxHalfExtents[axis2] * colVec2[i];
            faceCorners[2][i] = faceCenter[i] - boxHalfExtents[axis1] * colVec[i] + boxHalfExtents[axis2] * colVec2[i];
            faceCorners[3][i] = faceCenter[i] + boxHalfExtents[axis1] * colVec[i] + boxHalfExtents[axis2] * colVec2[i];
        }

        // Clip with planes
        dVector3 tempBuffer1[9];
        dVector3 tempBuffer2[9];
        dVector4 clipPlane;
        int tempCount1 = 0;
        int tempCount2 = 0;

        // Initialize buffers
        for (int i = 0; i < 9; i++) {
            tempBuffer1[i][0] = tempBuffer1[i][1] = tempBuffer1[i][2] = 0;
            tempBuffer2[i][0] = tempBuffer2[i][1] = tempBuffer2[i][2] = 0;
        }

        // Clip with triangle face plane
        dVector3 tempVec;
        tempVec[0] = -triangleNormal[0];
        tempVec[1] = -triangleNormal[1];
        tempVec[2] = -triangleNormal[2];
        dNormalize3(tempVec);
        BUILD_PLANE(clipPlane, tempVec, 0);
        clipPolygonToPlane(faceCorners, 4, tempBuffer1, tempCount1, clipPlane);

        // Clip with edge planes
        dVector3 edgeVec;
        SUBTRACT(v1, v0, edgeVec);
        dCROSS(tempVec, =, triangleNormal, edgeVec);
        dNormalize3(tempVec);
        BUILD_PLANE(clipPlane, tempVec, 0);
        clipPolygonToPlane(tempBuffer1, tempCount1, tempBuffer2, tempCount2, clipPlane);

        SUBTRACT(v2, v1, edgeVec);
        dCROSS(tempVec, =, triangleNormal, edgeVec);
        dNormalize3(tempVec);
        SUBTRACT(v0, v2, edgeVec);
        BUILD_PLANE(clipPlane, tempVec, dDOT(edgeVec, tempVec));
        clipPolygonToPlane(tempBuffer2, tempCount2, tempBuffer1, tempCount1, clipPlane);

        SUBTRACT(v0, v2, edgeVec);
        dCROSS(tempVec, =, triangleNormal, edgeVec);
        dNormalize3(tempVec);
        BUILD_PLANE(clipPlane, tempVec, 0);
        clipPolygonToPlane(tempBuffer1, tempCount1, tempBuffer2, tempCount2, clipPlane);

        // Generate contacts from clipped polygon
        for (int i = 0; i < tempCount2; i++) {
            dReal depth = dDOT(negNormal, tempBuffer2[i]);
            if (depth > 0) depth = 0;

            dVector3 contactPos;
            ADD(tempBuffer2[i], v0, contactPos);

            if (contactCount < (contactFlags & NUMC_MASK)) {
                dContactGeom* contact = SAFECONTACT(contactFlags, contactPoints, contactCount, contactStride);
                contact->depth = -depth;
                VECTOR_ASSIGN(contact->normal, bestCollisionNormal);
                VECTOR_ASSIGN(contact->pos, contactPos);
                contact->g1 = geometry1;
                contact->g2 = geometry2;
                contactCount++;
            } else {
                break;
            }
        }
    }
}

#include <iostream>
