// Convert Z3 expression to unsigned 64-bit integer
uint64_t expr_to_uint(const z3::expr &e) {
  uint64_t result;
  bool success = Z3_get_numeral_uint64(e.ctx(), e, &result);
  (void)success;
  assert(success && "Failed to convert expression to uint64_t");
  return result;
}

// Convert Z3 expression to signed 64-bit integer
int64_t expr_to_int(const z3::expr &e) {
  uint64_t raw_val;
  bool success = Z3_get_numeral_uint64(e.ctx(), e, &raw_val);

  int64_t value = static_cast<int64_t>(raw_val);
  if (!success)
    std::cerr << "Conversion failed for expression: " << e << '\n';

  assert(success && "Failed to convert expression to int64_t");

  unsigned bitwidth = e.get_sort().bv_size();
  if (bitwidth < 64 && (value & (1LL << (bitwidth - 1)))) {
    // Perform sign extension for negative numbers
    value |= ~((1LL << bitwidth) - 1LL);
  }
  return value;
}

// Convert Z3 boolean expression to C++ bool
bool expr_to_bool(const z3::expr &e) {
  assert(e.is_const() && "Expression must be constant");
  assert(e.is_bool() && "Expression must be boolean");
  return z3::eq(e, e.ctx().bool_val(true));
}

// Check whether a model defines a given symbol
bool model_defines(const z3::model &model, const z3::symbol &sym) {
  for (unsigned i = 0; i < model.num_consts(); ++i) {
    if (model.get_const_decl(i).name() == sym)
      return true;
  }
  return false;
}

// Determine if an expression is unsatisfiable
bool is_unsat(z3::expr e) {
  z3::solver solver(e.ctx());
  solver.add(e);
  return solver.check() == z3::unsat;
}

// Extract all uninterpreted constants from a Z3 expression
std::vector<expr> expr_constants(const expr &e) {
  auto &ctx = e.ctx();

  // Comparator for ordering expressions by their declaration names
  auto compare_func = [](const expr &a, const expr &b) {
    Z3_symbol sa = a.decl().name();
    Z3_symbol sb = b.decl().name();
    return sa < sb;
  };

  std::set<expr, decltype(compare_func)> unique_syms(compare_func);

  // Recursive traversal function
  std::function<void(const expr &)> traverse = [&traverse, &unique_syms, &ctx](const expr &node) {
    assert(Z3_is_app(ctx, node));
    auto app = Z3_to_app(ctx, node);
    unsigned arity = Z3_get_app_num_args(ctx, app);
    auto fdecl = Z3_get_app_decl(ctx, app);

    if (arity == 0 && Z3_get_decl_kind(ctx, fdecl) == Z3_OP_UNINTERPRETED)
      unique_syms.insert(node);

    for (unsigned i = 0; i < arity; ++i) {
      z3::expr child(ctx, Z3_get_app_arg(ctx, app, i));
      traverse(child);
    }
  };

  traverse(e);
  return std::vector<expr>(unique_syms.begin(), unique_syms.end());
}

// Adjust bitwidth of a bitvector expression (truncate or extend)
z3::expr adjustBitwidth(z3::expr op, unsigned int target_width) {
  assert(op.is_bv() && "Only bitvector types supported");
  unsigned int current_width = op.get_sort().bv_size();

  if (target_width < current_width) {
    // Truncate: keep lower bits
    return z3_ext::extract(target_width - 1, 0, op);
  } else if (target_width > current_width) {
    // Zero-extend
    return z3_ext::zext(target_width - current_width, op);
  }
  return op;
}

// Create a Z3 constant from LLVM ConstantInt
z3::expr makeConstantInt(z3::context *ctx, const llvm::ConstantInt *value) {
  int bits = value->getType()->getIntegerBitWidth();
  assert(bits <= 64 && "Support for integers larger than 64 bits not implemented");

  uint64_t val = llvm::dyn_cast<llvm::ConstantInt>(value)->getLimitedValue();
  z3::expr cexpr = ctx->bv_val(val, bits);
  return cexpr;
}

// Helper to create tuple sort and associated constructor/projection functions
void makePairSort(z3::context &ctx, z3::sort &dest_sort,
                  z3::func_decl &dest_get_a, z3::func_decl &dest_get_b,
                  z3::func_decl &dest_constr,
                  const char *proj_a_name, z3::sort proj_a_sort,
                  const char *proj_b_name, z3::sort proj_b_sort,
                  const char *constructor_name) {
  Z3_symbol constr_sym = Z3_mk_string_symbol(ctx, constructor_name);
  Z3_symbol proj_names[2] = {
    Z3_mk_string_symbol(ctx, proj_a_name),
    Z3_mk_string_symbol(ctx, proj_b_name)
  };
  Z3_sort proj_sorts[2] = { proj_a_sort, proj_b_sort };

  Z3_func_decl constr_decl;
  Z3_func_decl proj_decls[2];
  Z3_sort tuple_res = Z3_mk_tuple_sort(ctx, constr_sym, 2, proj_names, proj_sorts,
                                       &constr_decl, proj_decls);

  dest_sort = z3::to_sort(ctx, tuple_res);
  dest_get_a = z3::to_func_decl(ctx, proj_decls[0]);
  dest_get_b = z3::to_func_decl(ctx, proj_decls[1]);
  dest_constr = z3::to_func_decl(ctx, constr_decl);
}

#ifndef _STLP_STRING_IO_C
#define _STLP_STRING_IO_C

#ifndef _STLP_STRING_IO_H
#  include <stl/_string_io.h>
#endif

#ifndef _STLP_INTERNAL_CTYPE_H
#  include <stl/_ctype.h>
#endif

_STLP_BEGIN_NAMESPACE

// Helper function to fill output stream buffer with a character
template <class _CharT, class _Traits>
bool _STLP_CALL
__stlp_string_fill(basic_ostream<_CharT, _Traits>& __os,
                   basic_streambuf<_CharT, _Traits>* __buf,
                   streamsize __count) {
  _CharT __fill_char = __os.fill();
  for (streamsize __idx = 0; __idx < __count; ++__idx) {
    if (_Traits::eq_int_type(__buf->sputc(__fill_char), _Traits::eof()))
      return false;
  }
  return true;
}

// Output stream insertion operator for basic_string
template <class _CharT, class _Traits, class _Alloc>
basic_ostream<_CharT, _Traits>& _STLP_CALL
operator << (basic_ostream<_CharT, _Traits>& __os, 
             const basic_string<_CharT,_Traits,_Alloc>& __str) {
  typedef basic_ostream<_CharT, _Traits> __ostream_type;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  // Compile-time check that size_type is unsigned
  typedef char __check_unsigned_size_type[__STATIC_CAST(size_type, -1) > 0];

  typename __ostream_type::sentry __sentry_obj(__os);
  bool __success = false;

  if (__sentry_obj) {
    __success = true;
    size_type __len = __str.size();

    const bool __left_justify = (__os.flags() & __ostream_type::left) != 0;
    const streamsize __field_width = __os.width(0);
    basic_streambuf<_CharT, _Traits>* __buffer = __os.rdbuf();

    const bool __requires_padding = 
        (((sizeof(streamsize) > sizeof(size_t)) && (__STATIC_CAST(streamsize, __len) < __field_width)) ||
         ((sizeof(streamsize) <= sizeof(size_t)) && (__len < __STATIC_CAST(size_t, __field_width))));

    streamsize __pad_count = __requires_padding ? __field_width - __len : 0;

    if (!__left_justify)
      __success = __stlp_string_fill(__os, __buffer, __pad_count);

    __success = __success && (__buffer->sputn(__str.data(), streamsize(__len)) == streamsize(__len));

    if (__left_justify)
      __success = __success && __stlp_string_fill(__os, __buffer, __pad_count);
  }

  if (!__success)
    __os.setstate(__ostream_type::failbit);

  return __os;
}

// Input stream extraction operator for basic_string
template <class _CharT, class _Traits, class _Alloc>
basic_istream<_CharT, _Traits>& _STLP_CALL 
operator >> (basic_istream<_CharT, _Traits>& __is,
             basic_string<_CharT,_Traits, _Alloc>& __str) {
  typedef basic_istream<_CharT, _Traits> __istream_type;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  // Compile-time check that size_type is unsigned
  typedef char __check_unsigned_size_type[__STATIC_CAST(size_type, -1) > 0];

  typename __istream_type::sentry __sentry_obj(__is);
  if (__sentry_obj) {
    basic_streambuf<_CharT, _Traits>* __buffer = __is.rdbuf();
    typedef ctype<_CharT> _C_type;
    const locale& __locale = __is.getloc();
    const _C_type& __ctype_facet = use_facet<_C_type>(__locale);

    __str.clear();
    streamsize __max_width = __is.width(0);
    size_type __limit;

    if (__max_width <= 0)
      __limit = __str.max_size();
    else if (sizeof(streamsize) > sizeof(size_type) && 
             (__max_width > __STATIC_CAST(streamsize, __str.max_size())))
      __limit = 0;
    else {
      __limit = __STATIC_CAST(size_type, __max_width);
      __str.reserve(__limit);
    }

    while (__limit-- > 0) {
      typename _Traits::int_type __char_code = __buffer->sbumpc();
      if (_Traits::eq_int_type(__char_code, _Traits::eof())) {
        __is.setstate(__istream_type::eofbit);
        break;
      } else {
        _CharT __current_char = _Traits::to_char_type(__char_code);
        if (__ctype_facet.is(_C_type::space, __current_char)) {
          if (_Traits::eq_int_type(__buffer->sputbackc(__current_char), _Traits::eof()))
            __is.setstate(__istream_type::failbit);
          break;
        } else {
          __str.push_back(__current_char);
        }
      }
    }

    if (__str.empty())
      __is.setstate(__istream_type::failbit);
  } else {
    __is.setstate(__istream_type::failbit);
  }

  return __is;
}

// Line-based input extraction for basic_string
template <class _CharT, class _Traits, class _Alloc>    
basic_istream<_CharT, _Traits>& _STLP_CALL 
getline(basic_istream<_CharT, _Traits>& __is,
        basic_string<_CharT,_Traits,_Alloc>& __str,
        _CharT __delimiter) {
  typedef basic_istream<_CharT, _Traits> __istream_type;
  typedef typename basic_string<_CharT, _Traits, _Alloc>::size_type size_type;

  size_type __chars_read = 0;
  typename __istream_type::sentry __sentry_obj(__is, true);

  if (__sentry_obj) {
    basic_streambuf<_CharT, _Traits>* __buffer = __is.rdbuf();
    __str.clear();

    while (__chars_read < __str.max_size()) {
      int __char_code = __buffer->sbumpc();
      if (_Traits::eq_int_type(__char_code, _Traits::eof())) {
        __is.setstate(__istream_type::eofbit);
        break;
      } else {
        ++__chars_read;
        _CharT __current_char = _Traits::to_char_type(__char_code);
        if (!_Traits::eq(__current_char, __delimiter)) {
          __str.push_back(__current_char);
        } else {
          break;  // Delimiter found and consumed but not added to string
        }
      }
    }
  }

  if (__chars_read == 0 || __chars_read >= __str.max_size())
    __is.setstate(__istream_type::failbit);

  return __is;
}

