#include <unistd.h>
#include "TestBed.hpp"
#include <rccl/rccl.h>

#define PIPE_WRITE(procIdx, val)                                        \
  ASSERT_EQ(write(childList[procIdx]->parentWriteFd, &val, sizeof(val)), sizeof(val))

#define PIPE_READ(procIdx, val)                                                         \
  {                                                                                     \
    if (ev.verbose) INFO("Calling PIPE_READ to Process %d\n", procIdx); \
    ssize_t retval = read(childList[procIdx]->parentReadFd, &val, sizeof(val)); \
    if (ev.verbose) INFO("Got PIPE_READ %ld from Process %d\n", retval, procIdx); \
    if (retval == -1)                                                                   \
    {                                                                                   \
      ERROR("Unable to read from process %d: Error %s\n", procIdx, strerror(errno));      \
      FAIL();                                                                           \
    }                                                                                   \
    else if (retval == 0)                                                               \
    {                                                                                   \
      ERROR("Process %d pipe closed unexpectedly\n", procIdx);                            \
      exit(1);                                                                          \
    }                                                                                   \
    else if (retval < sizeof(int))                                                      \
    {                                                                                   \
      ERROR("Process %d pipe read incomplete (%ld / %lu)\n", procIdx, retval, sizeof(val)); \
      exit(1);                                                                          \
    }                                                                                   \
  }

#define PIPE_CHECK(procIdx)                         \
  {                                                 \
    int response = 0;                               \
    PIPE_READ(procIdx, response);                   \
    if (response != TEST_SUCCESS)                   \
    {                                               \
      ERROR("Process %d reports failure\n", procIdx); \
      ASSERT_EQ(response, TEST_SUCCESS);            \
      FAIL();                                       \
    }                                               \
  }

namespace RcclUnitTesting
{
  TestBed::TestBed() :
    numDevicesAvailable(0),
    numActiveProcesses(0),
    numActiveRanks(0)
  {
    this->numDevicesAvailable = ev.maxGpus;
    if (ev.verbose) INFO("Detected %d GPUs\n", this->numDevicesAvailable);
  }

  void TestBed::InitComms(std::vector<std::vector<int>> const& deviceIdsPerProcess,
                          std::vector<int>              const& numCollectivesInGroup,
                          std::vector<int>              const& numStreamsPerGroup,
                          int                           const  numGroupCalls,
                          bool                          const  useBlocking)
  {
    InteractiveWait("Starting InitComms");

    this->numActiveProcesses = deviceIdsPerProcess.size();
    this->numActiveRanks = 0;
    this->numGroupCalls = numGroupCalls;
    this->numCollectivesInGroup = numCollectivesInGroup;
    this->useBlocking = useBlocking;
    this->numStreamsPerGroup = numStreamsPerGroup;

    rankToProcMap.clear();
    rankToDeviceMap.clear();

    if (ev.verbose) INFO("Setting up %d active processes\n", this->numActiveProcesses);

    // Count total ranks and build mappings
    auto procIter = deviceIdsPerProcess.begin();
    while (procIter != deviceIdsPerProcess.end())
    {
      auto devIter = procIter->begin();
      while (devIter != procIter->end())
      {
        rankToProcMap.push_back(static_cast<int>(std::distance(deviceIdsPerProcess.begin(), procIter)));
        rankToDeviceMap.push_back(*devIter);
        ++numActiveRanks;
        ++devIter;
      }
      ++procIter;
    }

    if (!childList.empty())
    {
      ERROR("DestroyComms must be called prior to subsequent call to InitComms\n");
      return;
    }

    childList.resize(numActiveProcesses);
    int procIdx = 0;
    while (procIdx < numActiveProcesses)
    {
      childList[procIdx] = new TestBedChild(procIdx, ev.verbose, ev.printValues, ev.useMultithreading);
      if (childList[procIdx]->InitPipes() != TEST_SUCCESS)
      {
        ERROR("Unable to create pipes to process %d\n", procIdx);
        return;
      }

      pid_t pid = fork();
      if (pid == 0)
      {
        childList[procIdx]->StartExecutionLoop();
        return;
      }
      else
      {
        childList[procIdx]->pid = pid;
        close(childList[procIdx]->childWriteFd);
        close(childList[procIdx]->childReadFd);
      }
      ++procIdx;
    }

    if (ev.debugPause)
    {
      INFO("============================================================\n");
      INFO(" Pausing for debug attach: (e.g. sudo rocgdb -p <PID>)\n");
      INFO("============================================================\n");
      int idx = 0;
      while (idx < numActiveProcesses)
      {
        INFO(" Process %02d: processID: %d\n", idx, childList[idx]->pid);
        ++idx;
      }
      INFO("============================================================\n");
      INFO("<Press enter to continue>\n");
      scanf("%*c");
    }

    std::set<int> unique_devices;
    for (auto dev : rankToDeviceMap)
      unique_devices.insert(dev);

    bool useMulti = unique_devices.size() < rankToDeviceMap.size();

    int getIdCmd = TestBedChild::CHILD_GET_UNIQUE_ID;
    PIPE_WRITE(0, getIdCmd);
    PIPE_CHECK(0);

    ncclUniqueId id;
    PIPE_READ(0, id);

    int const cmd = TestBedChild::CHILD_INIT_COMMS;
    int commRankOffset = 0;
    procIdx = 0;
    while (procIdx < numActiveProcesses)
    {
      if (ev.verbose) INFO("Sending InitComm event to process %d\n", procIdx);
      PIPE_WRITE(procIdx, cmd);
      PIPE_WRITE(procIdx, id);
      PIPE_WRITE(procIdx, numActiveRanks);
      PIPE_WRITE(procIdx, commRankOffset);
      PIPE_WRITE(procIdx, numGroupCalls);
      PIPE_WRITE(procIdx, numCollectivesInGroup);
      PIPE_WRITE(procIdx, useBlocking);
      PIPE_WRITE(procIdx, useMulti);
      PIPE_WRITE(procIdx, numStreamsPerGroup);

      int const numGpus = deviceIdsPerProcess[procIdx].size();
      PIPE_WRITE(procIdx, numGpus);
      int devIdx = 0;
      while (devIdx < numGpus)
      {
        PIPE_WRITE(procIdx, deviceIdsPerProcess[procIdx][devIdx]);
        ++devIdx;
      }
      commRankOffset += numGpus;
      ++procIdx;
    }

    procIdx = 0;
    while (procIdx < numActiveProcesses)
    {
      PIPE_CHECK(procIdx);
      ++procIdx;
    }

    InteractiveWait("Finishing InitComms");
  }

  void TestBed::InitComms(std::vector<std::vector<int>> const& deviceIdsPerProcess,
                          int const numCollectivesInGroup, int const numStreamsPerGroup, int const numGroupCalls, bool const useBlocking)
  {
    InitComms(deviceIdsPerProcess, TestBed::GetNumCollsPerGroup(numCollectivesInGroup, numGroupCalls), 
              TestBed::GetNumStreamsPerGroup(numStreamsPerGroup, numGroupCalls), numGroupCalls, useBlocking);
  }

  void TestBed::InitComms(int const numGpus, int const numCollectivesInGroup, int const numStreamsPerGroup, int const numGroupCalls, bool const useBlocking)
  {
     const std::vector<int>& gpuPriorityOrder = ev.GetGpuPriorityOrder();
     InitComms(GetDeviceIdsList(1, numGpus, gpuPriorityOrder), 
               TestBed::GetNumCollsPerGroup(numCollectivesInGroup, numGroupCalls), 
               TestBed::GetNumStreamsPerGroup(numStreamsPerGroup, numGroupCalls), 
               numGroupCalls, useBlocking);
  }

  void TestBed::SetCollectiveArgs(ncclFunc_t      const funcType,
                                  ncclDataType_t  const dataType,
                                  size_t          const numInputElements,
                                  size_t          const numOutputElements,
                                  OptionalColArgs const &optionalArgs,
                                  int             const collId,
                                  int             const groupId,
                                  int             const commRank,
                                  int             const streamIdx)
  {
    InteractiveWait("Starting SetCollectiveArgs");

    std::vector<int> rankList;
    int r = 0;
    while (r < this->numActiveRanks)
    {
      if (commRank == -1 || commRank == r)
        rankList.push_back(r);
      ++r;
    }

    if (streamIdx < 0 || streamIdx >= this->numStreamsPerGroup[groupId])
    {
      ERROR("StreamIdx for group %d collective %d is out of bounds (%d/%d):\n", groupId, collId, streamIdx, numStreamsPerGroup[groupId]);
      FAIL();
    }

    int const cmd = TestBedChild::CHILD_SET_COLL_ARGS;
    auto rankIt = rankList.begin();
    while (rankIt != rankList.end())
    {
      int const procIdx = rankToProcMap[*rankIt];
      PIPE_WRITE(procIdx, cmd);
      PIPE_WRITE(procIdx, *rankIt);
      PIPE_WRITE(procIdx, collId);
      PIPE_WRITE(procIdx, groupId);
      PIPE_WRITE(procIdx, funcType);
      PIPE_WRITE(procIdx, dataType);
      PIPE_WRITE(procIdx, numInputElements);
      PIPE_WRITE(procIdx, numOutputElements);
      PIPE_WRITE(procIdx, streamIdx);
      PIPE_WRITE(procIdx, optionalArgs);
      PIPE_CHECK(procIdx);
      ++rankIt;
    }

    InteractiveWait("Finishing SetCollectiveArgs");
  }

  void TestBed::AllocateMem(bool   const inPlace,
                            bool   const useManagedMem,
                            int    const groupId,
                            int    const collId,
                            int    const commRank,
                            bool   const userRegistered)
  {
    InteractiveWait("Starting AllocateMem");

    std::vector<int> rankList;
    int r = 0;
    while (r < this->numActiveRanks)
    {
      if (commRank == -1 || commRank == r)
        rankList.push_back(r);
      ++r;
    }

    std::vector<int> groupList;
    int g = 0;
    while (g < this->numGroupCalls)
    {
      if (groupId == -1 || groupId == g)
        groupList.push_back(g);
      ++g;
    }

    int const cmd = TestBedChild::CHILD_ALLOCATE_MEM;
    auto groupIt = groupList.begin();
    while (groupIt != groupList.end())
    {
      auto rankIt = rankList.begin();
      while (rankIt != rankList.end())
      {
        int const procIdx = rankToProcMap[*rankIt];
        PIPE_WRITE(procIdx, cmd);
        PIPE_WRITE(procIdx, *rankIt);
        PIPE_WRITE(procIdx, collId);
        PIPE_WRITE(procIdx, inPlace);
        PIPE_WRITE(procIdx, useManagedMem);
        PIPE_WRITE(procIdx, userRegistered);
        PIPE_WRITE(procIdx, *groupIt);
        PIPE_CHECK(procIdx);
        ++rankIt;
      }
      ++groupIt;
    }

    InteractiveWait("Finishing AllocateMem");
  }

