  void TestBed::ExecuteCollectives(std::vector<int> const &currentRanks, int const groupId,
                                   bool const useHipGraph)
  {
    InteractiveWait("Starting ExecuteCollectives");
    int const cmd = TestBedChild::CHILD_EXECUTE_COLL;
    ++TestBed::NumTestsRun();

    std::vector<std::vector<int>> ranksPerProc(this->numActiveProcesses);
    int rankIdx = 0;
    while (rankIdx < currentRanks.size())
    {
      int procIdx = rankToProcMap[currentRanks[rankIdx]];
      ranksPerProc[procIdx].push_back(rankIdx);
      ++rankIdx;
    }

    std::vector<int> groupList;
    int g = 0;
    while (g < this->numGroupCalls)
    {
      if (groupId == -1 || groupId == g)
        groupList.push_back(g);
      ++g;
    }

    auto groupIt = groupList.begin();
    while (groupIt != groupList.end())
    {
      int procIdx = 0;
      while (procIdx < this->numActiveProcesses)
      {
        if ((currentRanks.empty()) || (!ranksPerProc[procIdx].empty()))
        {
          InteractiveWait("Starting ExecuteCollectives for process " + std::to_string(procIdx));
          PIPE_WRITE(procIdx, cmd);
          PIPE_WRITE(procIdx, ev.timeoutUs);
          PIPE_WRITE(procIdx, *groupIt);
          PIPE_WRITE(procIdx, useHipGraph);
          int tempCurrentRanks = static_cast<int>(currentRanks.size());
          PIPE_WRITE(procIdx, tempCurrentRanks);
          int r = 0;
          while (r < currentRanks.size())
          {
            PIPE_WRITE(procIdx, currentRanks[r]);
            ++r;
          }
        }
        ++procIdx;
      }

      procIdx = 0;
      while (procIdx < this->numActiveProcesses)
      {
        if ((currentRanks.empty()) || (!ranksPerProc[procIdx].empty())) PIPE_CHECK(procIdx);
        ++procIdx;
      }

      ++groupIt;
    }

    InteractiveWait("Finishing ExecuteCollectives");
  }

  void TestBed::ValidateResults(bool& isCorrect, int const groupId, int const collId, int const commRank)
  {
    InteractiveWait("Starting ValidateResults");

    std::vector<int> rankList;
    int r = 0;
    while (r < this->numActiveRanks)
    {
      if (commRank == -1 || commRank == r)
        rankList.push_back(r);
      ++r;
    }

    std::vector<int> groupList;
    int g = 0;
    while (g < this->numGroupCalls)
    {
      if (groupId == -1 || groupId == g)
        groupList.push_back(g);
      ++g;
    }

    int const cmd = TestBedChild::CHILD_VALIDATE_RESULTS;
    isCorrect = true;

    auto groupIt = groupList.begin();
    while (groupIt != groupList.end())
    {
      auto rankIt = rankList.begin();
      while (rankIt != rankList.end())
      {
        int const procIdx = rankToProcMap[*rankIt];
        PIPE_WRITE(procIdx, cmd);
        PIPE_WRITE(procIdx, *rankIt);
        PIPE_WRITE(procIdx, *groupIt);
        PIPE_WRITE(procIdx, collId);
        int response = 0;
        ASSERT_EQ(read(childList[procIdx]->parentReadFd, &response, sizeof(int)), sizeof(int));
        isCorrect &= (response == TEST_SUCCESS);
        ++rankIt;
      }
      ++groupIt;
    }

    ASSERT_EQ(isCorrect, true) << "Output does not match expected";
    InteractiveWait("Finishing ValidateResults");
  }

  void TestBed::LaunchGraphs(int const groupId)
  {
    InteractiveWait("Starting LaunchGraphs");

    std::vector<int> groupList;
    int g = 0;
    while (g < this->numGroupCalls)
    {
      if (groupId == -1 || groupId == g)
        groupList.push_back(g);
      ++g;
    }

    int const cmd = TestBedChild::CHILD_LAUNCH_GRAPHS;
    auto groupIt = groupList.begin();
    while (groupIt != groupList.end())
    {
      int procIdx = 0;
      while (procIdx < this->numActiveProcesses)
      {
        PIPE_WRITE(procIdx, cmd);
        PIPE_WRITE(procIdx, *groupIt);
        PIPE_CHECK(procIdx);
        ++procIdx;
      }
      ++groupIt;
    }

    InteractiveWait("Finishing LaunchGraphs");
  }

  void TestBed::DeallocateMem(int const groupId, int const collId, int const commRank)
  {
    InteractiveWait("Starting DeallocateMem");

    std::vector<int> rankList;
    int r = 0;
    while (r < this->numActiveRanks)
    {
      if (commRank == -1 || commRank == r)
        rankList.push_back(r);
      ++r;
    }

    std::vector<int> groupList;
    int g = 0;
    while (g < this->numGroupCalls)
    {
      if (groupId == -1 || groupId == g)
        groupList.push_back(g);
      ++g;
    }

    int const cmd = TestBedChild::CHILD_DEALLOCATE_MEM;
    auto groupIt = groupList.begin();
    while (groupIt != groupList.end())
    {
      auto rankIt = rankList.begin();
      while (rankIt != rankList.end())
      {
        int const procIdx = rankToProcMap[*rankIt];
        PIPE_WRITE(procIdx, cmd);
        PIPE_WRITE(procIdx, *rankIt);
        PIPE_WRITE(procIdx, *groupIt);
        PIPE_WRITE(procIdx, collId);
        PIPE_CHECK(procIdx);
        ++rankIt;
      }
      ++groupIt;
    }

    InteractiveWait("Finishing DeallocateMem");
  }

  void TestBed::DestroyComms()
  {
    InteractiveWait("Starting DestroyComms");
    int const cmd = TestBedChild::CHILD_DESTROY_COMMS;
    int procIdx = 0;
    while (procIdx < this->numActiveProcesses)
    {
      PIPE_WRITE(procIdx, cmd);
      PIPE_CHECK(procIdx);
      ++procIdx;
    }
    Finalize();
    InteractiveWait("Finishing DestroyComms");
  }

  void TestBed::DestroyGraphs()
  {
    InteractiveWait("Starting DestroyGraphs");
    int const cmd = TestBedChild::CHILD_DESTROY_GRAPHS;
    int g = 0;
    while (g < this->numGroupCalls)
    {
      int procIdx = 0;
      while (procIdx < this->numActiveProcesses)
      {
        PIPE_WRITE(procIdx, cmd);
        PIPE_WRITE(procIdx, g);
        PIPE_CHECK(procIdx);
        ++procIdx;
      }
      ++g;
    }
    InteractiveWait("Finishing DestroyGraphs");
  }

  void TestBed::Finalize()
  {
    if (this->numActiveProcesses == 0)
      return;

    InteractiveWait("Starting Finalize");

    int const cmd = TestBedChild::CHILD_STOP;
    int procIdx = 0;
    while (procIdx < this->numActiveProcesses)
    {
      PIPE_WRITE(procIdx, cmd);
      close(childList[procIdx]->parentWriteFd);
      close(childList[procIdx]->parentReadFd);
      ++procIdx;
    }

    procIdx = 0;
    while (procIdx < this->numActiveProcesses)
    {
      int returnVal = 0;
      waitpid(childList[procIdx]->pid, &returnVal, 0);
      if (returnVal != 0)
      {
        ERROR("Process %d exited with code %d\n", procIdx, returnVal);
      }
      delete(childList[procIdx]);
      ++procIdx;
    }

    childList.clear();
    this->numActiveProcesses = 0;
    this->numActiveRanks = 0;

    InteractiveWait("Finishing Finalize");
  }

  TestBed::~TestBed()
  {
    Finalize();
  }

