namespace cv {

// Helper: sign function for Householder reflections
template<typename T>
inline int sgn(T val) {
    return (T(0) < val) - (val < T(0));
}

// LU decomposition with partial pivoting (wrapper)
template<typename T>
static inline int lu_decompose_impl(T* A, size_t astep, int m, T* b, size_t bstep, int n, T eps)
{
    // Normalize strides in terms of element count
    astep /= sizeof(T);
    bstep /= sizeof(T);

    int parity = 1;

    for (int row = 0; row < m; ++row) {
        // Find pivot
        int pivot_row = row;
        T max_val = std::abs(A[row * astep + row]);
        for (int r = row + 1; r < m; ++r) {
            T candidate = std::abs(A[r * astep + row]);
            if (candidate > max_val) {
                max_val = candidate;
                pivot_row = r;
            }
        }

        // Check singularity
        if (max_val < eps)
            return 0;

        // Swap rows if needed
        if (pivot_row != row) {
            for (int col = row; col < m; ++col)
                std::swap(A[row * astep + col], A[pivot_row * astep + col]);
            if (b) {
                for (int col = 0; col < n; ++col)
                    std::swap(b[row * bstep + col], b[pivot_row * bstep + col]);
            }
            parity = -parity;
        }

        // Elimination step
        T diag_inv = -T(1) / A[row * astep + row];
        for (int target_row = row + 1; target_row < m; ++target_row) {
            T multiplier = A[target_row * astep + row] * diag_inv;
            for (int col = row + 1; col < m; ++col)
                A[target_row * astep + col] += multiplier * A[row * astep + col];
            if (b) {
                for (int col = 0; col < n; ++col)
                    b[target_row * bstep + col] += multiplier * b[row * bstep + col];
            }
        }
    }

    // Back substitution for RHS (if present)
    if (b) {
        for (int i = m - 1; i >= 0; --i) {
            for (int j = 0; j < n; ++j) {
                T sum = b[i * bstep + j];
                for (int k = i + 1; k < m; ++k)
                    sum -= A[i * astep + k] * b[k * bstep + j];
                b[i * bstep + j] = sum / A[i * astep + i];
            }
        }
    }

    return parity;
}

// Public LU wrappers
int LU(float* A, size_t astep, int m, float* b, size_t bstep, int n) {
    return lu_decompose_impl(A, astep, m, b, bstep, n, FLT_EPSILON * 10);
}
int LU(double* A, size_t astep, int m, double* b, size_t bstep, int n) {
    return lu_decompose_impl(A, astep, m, b, bstep, n, DBL_EPSILON * 100);
}

// Cholesky decomposition (lower triangular factor L)
template<typename T>
static inline bool cholesky_impl(T* A, size_t astep, int m, T* B, size_t bstep, int n)
{
    astep /= sizeof(T);
    bstep /= sizeof(T);

    // Compute L such that A = L * L^T
    for (int i = 0; i < m; ++i) {
        // Off-diagonal elements
        for (int j = 0; j < i; ++j) {
            T val = A[i * astep + j];
            for (int k = 0; k < j; ++k)
                val -= A[i * astep + k] * A[j * astep + k];
            A[i * astep + j] = val * A[j * astep + j];
        }

        // Diagonal element
        T diag = A[i * astep + i];
        for (int k = 0; k < i; ++k) {
            T t = A[i * astep + k];
            diag -= t * t;
        }

        if (diag <= std::numeric_limits<T>::epsilon())
            return false;

        A[i * astep + i] = T(1) / std::sqrt(diag);
    }

    // If no RHS, just normalize diagonal to 1/L_ii
    if (!B) {
        for (int i = 0; i < m; ++i)
            A[i * astep + i] = T(1) / A[i * astep + i];
        return true;
    }

    // Solve L * Y = B
    for (int i = 0; i < m; ++i) {
        for (int col = 0; col < n; ++col) {
            T sum = B[i * bstep + col];
            for (int k = 0; k < i; ++k)
                sum -= A[i * astep + k] * B[k * bstep + col];
            B[i * bstep + col] = sum * A[i * astep + i];
        }
    }

    // Solve L^T * X = Y
    for (int i = m - 1; i >= 0; --i) {
        for (int col = 0; col < n; ++col) {
            T sum = B[i * bstep + col];
            for (int k = m - 1; k > i; --k)
                sum -= A[k * astep + i] * B[k * bstep + col];
            B[i * bstep + col] = sum * A[i * astep + i];
        }
    }

    // Final normalization of diagonal
    for (int i = 0; i < m; ++i)
        A[i * astep + i] = T(1) / A[i * astep + i];

    return true;
}

bool Cholesky(float* A, size_t astep, int m, float* B, size_t bstep, int n) {
    return cholesky_impl(A, astep, m, B, bstep, n);
}
bool Cholesky(double* A, size_t astep, int m, double* B, size_t bstep, int n) {
    return cholesky_impl(A, astep, m, B, bstep, n);
}

// QR decomposition via Householder reflections
template<typename T>
static inline int qr_decompose_impl(T* A, size_t astep, int m, int n, int k, T* B, size_t bstep, T* tau, T eps)
{
    astep /= sizeof(T);
    bstep /= sizeof(T);

    // Allocate buffer for Householder vectors
    std::unique_ptr<T[]> buf(new T[m + n]);
    T* v = buf.get();
    T* hvec = tau ? tau : v + m;

    for (int l = 0; l < n; ++l) {
        int len = m - l;
        // Compute norm of column segment
        T norm_sq = T(0);
        for (int i = 0; i < len; ++i) {
            v[i] = A[(l + i) * astep + l];
            norm_sq += v[i] * v[i];
        }

        T first = v[0];
        T sign_val = sgn(first);
        v[0] += sign_val * std::sqrt(norm_sq);
        T new_norm = std::sqrt(norm_sq + v[0] * v[0] - first * first);

        // Normalize vector
        for (int i = 0; i < len; ++i)
            v[i] /= new_norm;

        // Apply reflection to remaining columns: A := (I - 2vv^T)A
        for (int j = l; j < n; ++j) {
            T dot = T(0);
            for (int i = l; i < m; ++i)
                dot += v[i - l] * A[i * astep + j];
            for (int i = l; i < m; ++i)
                A[i * astep + j] -= T(2) * v[i - l] * dot;
        }

        // Store Householder vector info
        hvec[l] = v[0] * v[0];
        for (int i = 1; i < len; ++i)
            A[(l + i) * astep + l] = v[i] / v[0];
    }

    // Apply transformations to RHS if given
    if (B) {
        for (int l = 0; l < n; ++l) {
            // Reconstruct v
            v[0] = T(1);
            for (int i = 1; i < m - l; ++i)
                v[i] = A[(l + i) * astep + l];

            // Apply H_l to each column of B
            for (int col = 0; col < k; ++col) {
                T dot = T(0);
                for (int i = l; i < m; ++i)
                    dot += v[i - l] * B[i * bstep + col];
                for (int i = l; i < m; ++i)
                    B[i * bstep + col] -= T(2) * v[i - l] * dot * hvec[l];
            }
        }

        // Back substitution on R part
        for (int i = n - 1; i >= 0; --i) {
            for (int j = n - 1; j > i; --j) {
                for (int p = 0; p < k; ++p)
                    B[i * bstep + p] -= B[j * bstep + p] * A[i * astep + j];
            }
            if (std::abs(A[i * astep + i]) < eps)
                return 0;
            for (int p = 0; p < k; ++p)
                B[i * bstep + p] /= A[i * astep + i];
        }
    }

    return 1;
}

int QR(float* A, size_t astep, int m, int n, int k, float* B, size_t bstep, float* tau) {
    return qr_decompose_impl(A, astep, m, n, k, B, bstep, tau, FLT_EPSILON * 10);
}
int QR(double* A, size_t astep, int m, int n, int k, double* B, size_t bstep, double* tau) {
    return qr_decompose_impl(A, astep, m, n, k, B, bstep, tau, DBL_EPSILON * 100);
}

