  const Eigen::MatrixXd & positions,
  const Eigen::MatrixXi & triangles,
  const int target_count,
  const double push_factor,
  Eigen::MatrixXd & result_samples)
{
  using namespace Eigen;
  using namespace std;

  // Compute Euclidean distance between two points on mesh given in barycentric form
  const auto & compute_distance = [] (
    const Eigen::MatrixXd & pos,
    const Eigen::MatrixXi & tri,
    const int face_idx1,
    const Eigen::Vector3d & bary1,
    const int face_idx2,
    const Eigen::Vector3d & bary2) -> double
  {
    Eigen::Vector3d point1 = 
      bary1(0)*pos.row(tri(face_idx1,0)) +
      bary1(1)*pos.row(tri(face_idx1,1)) +
      bary1(2)*pos.row(tri(face_idx1,2));

    Eigen::Vector3d point2 = 
      bary2(0)*pos.row(tri(face_idx2,0)) +
      bary2(1)*pos.row(tri(face_idx2,1)) +
      bary2(2)*pos.row(tri(face_idx2,2));

    return (point1 - point2).norm();
  };

  // Handle tetrahedral meshes by extracting faces
  if(triangles.cols() == 4)
  {
    verbose("uniform_sample.h: processing tet mesh\n");
    MatrixXi T0 = triangles.col(0);
    MatrixXi T1 = triangles.col(1);
    MatrixXi T2 = triangles.col(2);
    MatrixXi T3 = triangles.col(3);

    MatrixXi face_list =
      cat(1,
        cat(1,
          cat(2,T0, cat(2,T1,T2)),
          cat(2,T0, cat(2,T2,T3))),
        cat(1,
          cat(2,T0, cat(2,T3,T1)),
          cat(2,T1, cat(2,T3,T2)))
      );

    assert(face_list.rows() == 4*triangles.rows());
    assert(face_list.cols() == 3);

    uniformly_sample_two_manifold(positions, face_list, target_count, push_factor, result_samples);
    return;
  }

  double start_time = get_seconds();
  VectorXi initial_indices;

  // Get initial sampling from vertices
  uniformly_sample_two_manifold_at_vertices(positions, target_count, push_factor, initial_indices);
  verbose("Initial partition: %g seconds\n", get_seconds() - start_time);

  slice(positions, initial_indices, colon<int>(0, positions.cols()-1), result_samples);

  // Build vertex-to-face adjacency information
  vector<vector<int> > vertex_to_faces, face_vertex_indices;
  vertex_triangle_adjacency(positions, triangles, vertex_to_faces, face_vertex_indices);

  // Store face indices and barycentric coordinates for each sample
  vector<vector<int> > sample_face_ids; sample_face_ids.resize(target_count);
  vector<vector<Eigen::Vector3d> > sample_bary_coords; sample_bary_coords.resize(target_count);
  vector<int> current_best_index; current_best_index.resize(target_count);

  // Distance matrices for optimization
  vector<MatrixXd> distance_matrices; distance_matrices.resize(target_count);

  // Identity matrix for corner computations
  MatrixXd identity_matrix(MatrixXd::Identity(positions.cols(), positions.cols()));

  // Initialize seed locations with face and barycentric data
  for(int idx = 0; idx < target_count; idx++)
  {
    assert(vertex_to_faces[initial_indices(idx)].size() > 0);
    sample_face_ids[idx].push_back(vertex_to_faces[initial_indices(idx)][0]);

    Eigen::Vector3d bary(0,0,0);
    bary(face_vertex_indices[initial_indices(idx)][0]) = 1;
    sample_bary_coords[idx].push_back(bary);
    current_best_index[idx] = 0;
  }

  // Iterative refinement parameters
  double current_radius = 1.0;
  const double min_radius = 1e-5;
  const int max_samples_per_face = 100;
  const int max_attempts_per_face = 1000;
  const int max_outer_iterations = 1000;

  // Refinement loop
  while(current_radius > min_radius)
  {
    // Process each seed
    for(int idx = 0; idx < target_count; idx++)
    {
      int face_id = sample_face_ids[idx][current_best_index[idx]];
      Eigen::Vector3d bary(sample_bary_coords[idx][current_best_index[idx]]);

      // Find vertex in face farthest from barycenter
      int vertex_in_face = 
        (bary(0) > bary(1) ? (bary(0) > bary(2) ? 0 : 2)
                           : (bary(1) > bary(2) ? 1 : 2));

      int mesh_vertex = triangles(face_id, vertex_in_face);
      vector<int> adjacent_faces = vertex_to_faces[mesh_vertex];

      // Reset sample storage for this seed
      sample_bary_coords[idx].clear();
      sample_face_ids[idx].clear();
      current_best_index[idx] = 0;

      sample_bary_coords[idx].push_back(bary);
      sample_face_ids[idx].push_back(face_id);

      // Current seed position in weight space
      VectorXd seed_position =
        bary(0)*positions.row(triangles(face_id,0)) +
        bary(1)*positions.row(triangles(face_id,1)) +
        bary(2)*positions.row(triangles(face_id,2));

#ifdef EXTREME_VERBOSE
      verbose("Processing seed %d\n", idx);
#endif

      // Generate random samples on adjacent faces
      for(int f=0; f<(int)adjacent_faces.size(); f++)
      {
        int current_face = adjacent_faces[f];
        int samples_on_face = 0;

        for(int attempt=0; attempt<max_attempts_per_face; attempt++)
        {
          // Generate random point in triangle using barycentric coordinates
          double u, v;
          double ru = (double)rand() / RAND_MAX;
          double rv = (double)rand() / RAND_MAX;

          if((ru+rv) > 1.0)
          {
            u = 1.0 - rv;
            v = 1.0 - ru;
          } else {
            u = ru;
            v = rv;
          }

          Eigen::Vector3d candidate_bary(u, v, 1.0-u-v);
          double dist = compute_distance(positions, triangles, face_id, bary, current_face, candidate_bary);

          if(dist < current_radius)
          {
            sample_face_ids[idx].push_back(current_face);
            sample_bary_coords[idx].push_back(candidate_bary);
            samples_on_face++;
          }

          if(samples_on_face >= max_samples_per_face)
            break;
        }
      }
    }

    // Precompute distances between samples and other seeds/corners
    for(int idx = 0; idx < target_count; idx++)
    {
      distance_matrices[idx].resize(sample_face_ids[idx].size(), target_count + positions.cols());

      for(int s = 0; s < (int)sample_face_ids[idx].size(); s++)
      {
        int sample_face = sample_face_ids[idx][s];
        Eigen::Vector3d sample_bary = sample_bary_coords[idx][s];

        // Distances to other seeds
        for(int j = 0; j < target_count; j++)
        {
          if(idx == j)
            distance_matrices[idx](s,j) = 10.0;  // Large value for self
          else
          {
            int seed_j_face = sample_face_ids[j][current_best_index[j]];
            Eigen::Vector3d seed_j_bary(sample_bary_coords[j][current_best_index[j]]);
            distance_matrices[idx](s,j) = 
              compute_distance(positions, triangles, sample_face, sample_bary, seed_j_face, seed_j_bary);
          }
        }

        // Distances to corners
        for(int j = 0; j < positions.cols(); j++)
        {
          Eigen::Vector3d sample_point = 
            sample_bary(0)*positions.row(triangles(sample_face,0)) +
            sample_bary(1)*positions.row(triangles(sample_face,1)) +
            sample_bary(2)*positions.row(triangles(sample_face,2));

          distance_matrices[idx](s, target_count + j) = 
            (sample_point - identity_matrix.row(j)).norm() / push_factor;
        }
      }
    }

    // Optimize seed positions
    int iteration_count = 0;
    while(true)
    {
      bool any_moved = false;

      for(int idx = 0; idx < target_count; idx++)
      {
        VectorXd min_distances = distance_matrices[idx].rowwise().minCoeff();
        int previous_best = current_best_index[idx];
        double best_distance = -2.0;

        for(int s = 0; s < (int)min_distances.size(); s++)
        {
          if(min_distances(s) > best_distance)
          {
            best_distance = min_distances(s);
            current_best_index[idx] = s;
          }
        }

        any_moved |= (previous_best != current_best_index[idx]);
      }

      if(!any_moved)
        break;

      iteration_count++;
      if(iteration_count >= max_outer_iterations)
      {
        verbose("Maximum iterations reached (%d)\n", iteration_count);
        break;
      }
    }

    current_radius *= 0.9;
  }

  // Finalize results
  result_samples.resize(target_count, positions.cols());
  for(int i = 0; i < target_count; i++)
  {
    int final_face = sample_face_ids[i][current_best_index[i]];
    Eigen::Vector3d final_bary(sample_bary_coords[i][current_best_index[i]]);

    result_samples.row(i) =
      final_bary(0)*positions.row(triangles(final_face,0)) +
      final_bary(1)*positions.row(triangles(final_face,1)) +
      final_bary(2)*positions.row(triangles(final_face,2));
  }

  verbose("Total computation time: %g seconds\n", get_seconds() - start_time);
}

IGL_INLINE void igl::uniformly_sample_two_manifold_at_vertices(
  const Eigen::MatrixXd & original_weights,
  const int k,
  const double push,
  Eigen::VectorXi & selected_vertices)
{
  using namespace Eigen;
  using namespace std;

  const MatrixXd& weights = original_weights;

  // Initial partitioning
  VectorXi group_assignment;
  Matrix<double,Dynamic,1> dummy;
  partition(weights, k + weights.cols(), group_assignment, selected_vertices, dummy);

  // Remove corner vertices (stored at beginning)
  selected_vertices = selected_vertices.segment(weights.cols(), k).eval();

  // Verify partition result
  MatrixXd sampled_weights;
  slice(weights, selected_vertices, colon<int>(0, weights.cols()-1), sampled_weights);

  int num_vertices = weights.rows();
  int dim = weights.cols();

  // Create corner matrix
  MatrixXd corner_matrix = MatrixXd::Identity(dim, dim);

  // Combine original weights with corners
  MatrixXd combined_weights(num_vertices + dim, dim);
  combined_weights << weights, corner_matrix;

  // Prepare seed and corner matrix
  MatrixXd seed_and_corner(k + dim, dim);
  for(int i = 0; i < k; i++)
    seed_and_corner.row(i) = weights.row(selected_vertices(i));
  for(int i = 0; i < dim; i++)
    seed_and_corner.row(i + k) = combined_weights.row(num_vertices + i);

  // Compute all pairwise squared distances
  MatrixXd squared_distances;
  all_pairs_distances(combined_weights, seed_and_corner, true, squared_distances);

  // Adjust corner distances
  squared_distances.block(0, k, squared_distances.rows(), dim) /= (push * push);

  // Lloyd relaxation iterations
  const int max_iterations = 30;
  for(int iter = 0; iter < max_iterations; iter++)
  {
    bool changed = false;

    for(int i = 0; i < k; i++)
    {
      int old_index = selected_vertices(i);

      // Set large distance to self
      squared_distances.col(i).setZero();
      squared_distances.col(i).array() += 10.0;

      // Find farthest point from other seeds
      MatrixXd min_distances = squared_distances.rowwise().minCoeff();
      MatrixXd::Index new_index, dummy_idx;
      min_distances.maxCoeff(&new_index, &dummy_idx);

      // Update distances for new index
      MatrixXd new_row;
      all_pairs_distances(combined_weights, combined_weights.row(new_index), true, new_row);
      squared_distances.col(i) = new_row;

      selected_vertices(i) = new_index;
      changed |= (new_index != old_index);
    }

    if(!changed)
      break;
  }
}

