#include "MovieSceneNiagaraParameterSectionTemplate.h"
#include "NiagaraComponent.h"
#include "NiagaraTypes.h"
#include "IMovieScenePlayer.h"

// Helper structure to hold per-component state during evaluation
struct FComponentState
{
	TWeakObjectPtr<UNiagaraComponent> NiagaraActor;
	TOptional<TArray<uint8>> SavedState;
};

// Persistent data container for the section
struct FParameterTrackData : IPersistentEvaluationData
{
	TArray<FComponentState> ComponentStates;
};

// Token used to restore previous parameter values after animation
struct FRestorePreviousValueToken : IMovieScenePreAnimatedToken
{
	FRestorePreviousValueToken(FNiagaraVariable InParam, TOptional<TArray<uint8>>&& InPrevData)
		: Param(InParam), PreviousData(MoveTemp(InPrevData))
	{
	}

	virtual void RestoreState(UObject& Target, IMovieScenePlayer& Player) override
	{
		UNiagaraComponent* NiagaraComp = Cast<UNiagaraComponent>(&Target);
		if (!PreviousData.IsSet())
		{
			NiagaraComp->GetOverrideParameters().RemoveParameter(Param);
		}
		else
		{
			NiagaraComp->GetOverrideParameters().SetParameterData(PreviousData.GetValue().GetData(), Param);
		}
	}

	FNiagaraVariable Param;
	TOptional<TArray<uint8>> PreviousData;
};

// Producer responsible for capturing current parameter state before override
struct FStateCaptureProducer : IMovieScenePreAnimatedTokenProducer
{
	FStateCaptureProducer(FNiagaraVariable InVar)
		: Variable(InVar)
	{
	}

	virtual IMovieScenePreAnimatedTokenPtr CacheExistingState(UObject& Object) const override
	{
		UNiagaraComponent* NiagaraComp = Cast<UNiagaraComponent>(&Object);
		const uint8* ExistingData = NiagaraComp->GetOverrideParameters().GetParameterData(Variable);

		TOptional<TArray<uint8>> CapturedData;
		if (ExistingData != nullptr)
		{
			TArray<uint8> TempBuffer;
			TempBuffer.SetNumUninitialized(Variable.GetSizeInBytes());
			FMemory::Memcpy(TempBuffer.GetData(), ExistingData, Variable.GetSizeInBytes());
			CapturedData.Emplace(MoveTemp(TempBuffer));
		}

		return MakeShared<FRestorePreviousValueToken>(Variable, MoveTemp(CapturedData));
	}

	FNiagaraVariable Variable;
};

// Execution token that applies animated parameter value and saves original state
struct FApplyAnimatedValueToken : IMovieSceneExecutionToken
{
	FApplyAnimatedValueToken(TWeakObjectPtr<UNiagaraComponent> InComp, FNiagaraVariable InVar, TArray<uint8>&& InVal)
		: ComponentRef(InComp), Parameter(InVar), ValueData(MoveTemp(InVal))
	{
	}

	virtual void Execute(const FMovieSceneContext& Context, const FMovieSceneEvaluationOperand& Operand, FPersistentEvaluationData& PersistentData, IMovieScenePlayer& Player) override
	{
		static FMovieSceneAnimTypeID TypeID = TMovieSceneAnimTypeID<FApplyAnimatedValueToken, 1>();

		UNiagaraComponent* NiagaraComp = ComponentRef.Get();
		if (NiagaraComp != nullptr)
		{
			Player.SavePreAnimatedState(*NiagaraComp, TypeID, FStateCaptureProducer(Parameter));
			NiagaraComp->GetOverrideParameters().AddParameter(Parameter, false);
			NiagaraComp->GetOverrideParameters().SetParameterData(ValueData.GetData(), Parameter);
		}
	}

	TWeakObjectPtr<UNiagaraComponent> ComponentRef;
	FNiagaraVariable Parameter;
	TArray<uint8> ValueData;
};

// Constructor implementations
FMovieSceneNiagaraParameterSectionTemplate::FMovieSceneNiagaraParameterSectionTemplate()
{
}

FMovieSceneNiagaraParameterSectionTemplate::FMovieSceneNiagaraParameterSectionTemplate(FNiagaraVariable InParam)
	: Parameter(InParam)
{
}

// Initialize phase: capture initial parameter states for all bound Niagara components
void FMovieSceneNiagaraParameterSectionTemplate::Initialize(const FMovieSceneEvaluationOperand& Operand, const FMovieSceneContext& Context, FPersistentEvaluationData& PersistentData, IMovieScenePlayer& Player) const
{
	FParameterTrackData& TrackData = PersistentData.GetOrAddSectionData<FParameterTrackData>();
	TrackData.ComponentStates.Empty();

	for (TWeakObjectPtr<> BoundObj : Player.FindBoundObjects(Operand))
	{
		UNiagaraComponent* NiagaraComp = Cast<UNiagaraComponent>(BoundObj.Get());
		if (NiagaraComp == nullptr)
			continue;

		const uint8* InitialData = NiagaraComp->GetOverrideParameters().GetParameterData(Parameter);
		if (InitialData == nullptr)
		{
			InitialData = NiagaraComp->GetAsset()->GetExposedParameters().GetParameterData(Parameter);
		}

		TArray<uint8> StoredValue;
		if (InitialData != nullptr)
		{
			StoredValue.SetNumUninitialized(Parameter.GetSizeInBytes());
			FMemory::Memcpy(StoredValue.GetData(), InitialData, Parameter.GetSizeInBytes());
		}
		else
		{
			StoredValue.SetNumZeroed(Parameter.GetSizeInBytes());
		}

		FComponentState State;
		State.NiagaraActor = NiagaraComp;
		State.SavedState.Emplace(MoveTemp(StoredValue));
		TrackData.ComponentStates.Add(State);
	}
}

// Evaluate phase: generate execution tokens with interpolated values
void FMovieSceneNiagaraParameterSectionTemplate::Evaluate(const FMovieSceneEvaluationOperand& Operand, const FMovieSceneContext& Context, const FPersistentEvaluationData& PersistentData, FMovieSceneExecutionTokens& ExecutionTokens) const
{
	FParameterTrackData const* TrackData = PersistentData.FindSectionData<FParameterTrackData>();
	if (TrackData == nullptr)
		return;

	for (const FComponentState& State : TrackData->ComponentStates)
	{
		if (State.SavedState.IsSet())
		{
			TArray<uint8> InterpolatedValue;
			GetParameterValue(Context.GetTime(), State.SavedState.GetValue(), InterpolatedValue);
			ExecutionTokens.Add(FApplyAnimatedValueToken(State.NiagaraActor, Parameter, MoveTemp(InterpolatedValue)));
		}
	}
}

#include "origo/serialization/ISerializer.h"

namespace Origo {

// Helper function to deserialize Vec3 components from serializer
static bool deserialize_vec3(ISerializer& ser, Vec3& vec) {
    bool success = true;

    // Attempt to read each component individually
    if (!ser.try_read("x", vec.x)) success = false;
    if (!ser.try_read("y", vec.y)) success = false;
    if (!ser.try_read("z", vec.z)) success = false;

    return success;
}

// Helper function to serialize Vec3 components to serializer
static void serialize_vec3(ISerializer& ser, const Vec3& vec) {
    ser.write("x", vec.x);
    ser.write("y", vec.y);
    ser.write("z", vec.z);
}

// Read Vec3 as an object with named fields
bool ISerializer::try_read(std::string_view field_name, Vec3& out_value) {
    begin_object(field_name);
    bool parsed_successfully = deserialize_vec3(*this, out_value);
    end_object();
    return parsed_successfully;
}

// Read Vec3 from array-style object (unnamed fields)
bool ISerializer::try_read_array_object(Vec3& out_value) {
    if (!try_begin_array_object_read()) {
        return false;
    }
    bool parsed_successfully = deserialize_vec3(*this, out_value);
    end_array_object();
    return parsed_successfully;
}

// Write Vec3 as an object with named fields
void ISerializer::write(std::string_view field_name, const Vec3& value) {
    begin_object(field_name);
    serialize_vec3(*this, value);
    end_object();
}

// Write Vec3 in array form (no field names)
void ISerializer::write(const Vec3& value) {
    begin_array_object();
    serialize_vec3(*this, value);
    end_array_object();
}

// Write OptionalAssetHandle as string or "0"
void ISerializer::write(std::string_view field_name, const OptionalAssetHandle& opt_handle) {
    if (!opt_handle) {
        write(field_name, std::string{"0"});
        return;
    }

    auto uuid_opt = AssetManager::get_instance().get_uuid(opt_handle.value());
    if (uuid_opt.has_value()) {
        write(field_name, uuid_opt->to_string());
    } else {
        write(field_name, std::string{"0"});
    }
}

// Write OptionalAssetHandle without field name (array context)
void ISerializer::write(const OptionalAssetHandle& opt_handle) {
    if (!opt_handle) {
        write(std::string{"0"});
        return;
    }

    auto uuid_opt = AssetManager::get_instance().get_uuid(opt_handle.value());
    if (uuid_opt.has_value()) {
        write(uuid_opt->to_string());
    } else {
        write(std::string{"0"});
    }
}

}

