// FeatureIdToGeoObjectIdOneWay --------------------------------------------------------------------
FeatureIdToGeoObjectIdOneWay::FeatureIdToGeoObjectIdOneWay(DataSource const & dataSource)
  : m_dataSource(dataSource)
  , m_reader(std::unique_ptr<ModelReader>())
{}

bool FeatureIdToGeoObjectIdOneWay::Load()
{
  auto worldHandle = indexer::FindWorld(m_dataSource);
  if (!worldHandle.IsAlive())
  {
    LOG(LWARNING, ("Unable to locate World map file."));
    return false;
  }

  // Already loaded for this MWM?
  if (worldHandle.GetId() == m_mwmId)
    return true;

  auto const& container = worldHandle.GetValue()->m_cont;
  if (!container.IsExist(FEATURE_TO_OSM_FILE_TAG))
  {
    LOG(LWARNING, ("Missing cities fid bimap in the world map."));
    return false;
  }

  bool loadOk = false;
  try
  {
    m_reader = container.GetReader(FEATURE_TO_OSM_FILE_TAG);
    loadOk = FeatureIdToGeoObjectIdSerDes::Deserialize(*m_reader.GetPtr(), *this);
  }
  catch (Reader::Exception const & ex)
  {
    LOG(LERROR, ("Failed to parse cities fid bimap from world map:", ex.Msg()));
    return false;
  }

  if (loadOk)
  {
    m_mwmId = worldHandle.GetId();
    return true;
  }

  return false;
}

bool FeatureIdToGeoObjectIdOneWay::GetGeoObjectId(FeatureID const & fid, base::GeoObjectId & id)
{
  // Validate MWM ID match
  if (fid.m_mwmId != m_mwmId)
  {
    LOG(LERROR, ("MWM mismatch: feature belongs to", fid.m_mwmId, ", expected:", m_mwmId));
    return false;
  }

  // Ensure all maps are initialized
  if (!m_mapNodes || !m_mapWays || !m_mapRelations)
    return false;

  uint64_t serialId;
  if (m_mapNodes->Get(fid.m_index, serialId))
  {
    id = base::MakeOsmNode(serialId);
    return true;
  }

  if (m_mapWays->Get(fid.m_index, serialId))
  {
    id = base::MakeOsmWay(serialId);
    return true;
  }

  if (m_mapRelations->Get(fid.m_index, serialId))
  {
    id = base::MakeOsmRelation(serialId);
    return true;
  }

  return false;
}

// FeatureIdToGeoObjectIdTwoWay --------------------------------------------------------------------
FeatureIdToGeoObjectIdTwoWay::FeatureIdToGeoObjectIdTwoWay(DataSource const & dataSource) 
  : m_dataSource(dataSource) {}

bool FeatureIdToGeoObjectIdTwoWay::Load()
{
  auto worldHandle = indexer::FindWorld(m_dataSource);
  if (!worldHandle.IsAlive())
  {
    LOG(LWARNING, ("Could not find World map file."));
    return false;
  }

  // Skip reload if already loaded for current MWM
  if (worldHandle.GetId() == m_mwmId)
    return true;

  auto const& container = worldHandle.GetValue()->m_cont;
  if (!container.IsExist(FEATURE_TO_OSM_FILE_TAG))
  {
    LOG(LWARNING, ("No cities fid bimap found in world map."));
    return false;
  }

  bool success = false;
  try
  {
    FilesContainerR::TReader reader = container.GetReader(FEATURE_TO_OSM_FILE_TAG);
    success = FeatureIdToGeoObjectIdSerDes::Deserialize(*reader.GetPtr(), m_map);
  }
  catch (Reader::Exception const & err)
  {
    LOG(LERROR, ("Error reading cities fid bimap from world map:", err.Msg()));
    return false;
  }

  if (success)
  {
    m_mwmId = worldHandle.GetId();
    return true;
  }

  return false;
}

bool FeatureIdToGeoObjectIdTwoWay::GetGeoObjectId(FeatureID const & fid, base::GeoObjectId & id)
{
  if (fid.m_mwmId != m_mwmId)
  {
    LOG(LERROR, ("Incorrect MWM: feature has", fid.m_mwmId, ", expected:", m_mwmId));
    return false;
  }

  return m_map.GetValue(fid.m_index, id);
}

bool FeatureIdToGeoObjectIdTwoWay::GetFeatureID(base::GeoObjectId const & id, FeatureID & fid)
{
  uint32_t index;
  if (!m_map.GetKey(id, index))
    return false;

  fid = FeatureID(m_mwmId, index);
  return true;
}
