        // Atomic version of second pass reduction
        compiler.compile<1>(fn_reduce_aabb_2_pass_atomic,
            [sa_block_bounds = lbvh_data->sa_block_bounds.view()]()
            {
                luisa::compute::set_block_size(256);
                const Uint thread_id = luisa::compute::dispatch_id().x;
                auto box = sa_block_bounds->read(thread_id);

                Var<float3> min_bound = AABB::get_minimum(box);
                Var<float3> max_bound = AABB::get_maximum(box);

                min_bound = ParallelIntrinsic::block_intrinsic_reduce(
                    thread_id, min_bound, ParallelIntrinsic::warp_reduce_op_min<float3>);
                max_bound = ParallelIntrinsic::block_intrinsic_reduce(
                    thread_id, max_bound, ParallelIntrinsic::warp_reduce_op_max<float3>);

                auto reduced_box = AABB::construct(min_bound, max_bound);

