                    sa_block_bounds->atomic(block_id).cols[0][2].fetch_min(reduced_box.cols[0][2]);
                    sa_block_bounds->atomic(block_id).cols[1][0].fetch_max(reduced_box.cols[1][0]);
                    sa_block_bounds->atomic(block_id).cols[1][1].fetch_max(reduced_box.cols[1][1]);
