EditChain::EditChain(QWidget *parent)
    : QWidget(parent), ui(new Ui::EditChain) {
    ui->setupUi(this);
}

EditChain::~EditChain() {
    delete ui;
}

void EditChain::onStart(std::shared_ptr<Configs::ProxyEntity> entity) {
    this->entity = entity;
    auto chainBean = entity->ChainBean();

    // Iterate through stored chain IDs and add valid profiles
    for (const auto& id : chainBean->list) {
        insertProfileIfValid(id);
    }
}

bool EditChain::onEnd() {
    if (get_edit_text_name().isEmpty()) {
        MessageBoxWarning(software_name, tr("Name cannot be empty."));
        return false;
    }

    auto chainBean = entity->ChainBean();
    QList<int> selectedIds;

    // Collect all current proxy IDs from the list widget
    for (int index = 0; index < ui->listWidget->count(); ++index) {
        auto item = ui->listWidget->item(index);
        selectedIds << item->data(114514).toInt();
    }

    chainBean->list = selectedIds;
    return true;
}

void EditChain::on_select_profile_clicked() {
    // Optional: hide edit dialog before showing selection dialog
    // get_edit_dialog()->hide();

    DialogGroupChooseProxy* selector = new DialogGroupChooseProxy(this);
    selector->setWindowTitle(QCoreApplication::translate(
        "DialogGroupChooseProxy", "Add proxy"));

    QObject::connect(selector, &DialogGroupChooseProxy::set_proxy,
        this, [this](int profileId) {
            insertProfileIfValid(profileId);
        });

    selector->show();
}

void EditChain::insertProfileIfValid(int profileId) {
    auto profileEntity = Configs::profileManager->GetProfile(profileId);
    if (profileEntity && profileEntity->type != "chain" && profileEntity->type != "extracore") {
        QListWidgetItem* listItem = new QListWidgetItem();
        listItem->setData(114514, profileId);

        ProxyItem* proxyWidget = new ProxyItem(this, profileEntity, listItem);
        ui->listWidget->addItem(listItem);
        ui->listWidget->setItemWidget(listItem, proxyWidget);

        // Setup replacement handler for this item
        connect(proxyWidget->get_change_button(), &QPushButton::clicked,
            this, [proxyWidget, this]() {
                DialogGroupChooseProxy* replacer = new DialogGroupChooseProxy(this);
                replacer->setWindowTitle(QCoreApplication::translate(
                    "DialogGroupChooseProxy", "Replace %1 proxy")
                    .arg(proxyWidget->ent->bean->DisplayName()));

                QObject::connect(replacer, &DialogGroupChooseProxy::set_proxy,
                    this, [proxyWidget](int newId) {
                        updateProxyItem(proxyWidget, newId);
                    });

                replacer->show();
            });
    }
}

void EditChain::updateProxyItem(ProxyItem* item, int newProfileId) {
    auto updatedEntity = Configs::profileManager->GetProfile(newProfileId);
    if (updatedEntity && updatedEntity->type != "chain" && updatedEntity->type != "extracore") {
        item->item->setData(114514, newProfileId);
        item->ent = updatedEntity;
        item->refresh_data();
    }
}

#include "locale.hpp"
#include <ostream>
#include <cctype>

namespace xdgpp {

Locale Locale::system() {
  setlocale(LC_MESSAGES, "");
  const char* localeStr = setlocale(LC_MESSAGES, nullptr);
  return Locale::parse(localeStr ? std::string_view(localeStr) : std::string_view{});
}

bool Locale::matchesOnly(const Locale& other, int requiredComponents) const {
  if (other.flags() != requiredComponents) return false;

  if ((requiredComponents & static_cast<int>(Component::LANG)) && m_lang != other.m_lang) return false;
  if ((requiredComponents & static_cast<int>(Component::COUNTRY)) && m_country != other.m_country) return false;
  if ((requiredComponents & static_cast<int>(Component::MODIFIER)) && m_modifier != other.m_modifier) return false;

  return true;
}

int Locale::flags() const {
  int result = static_cast<int>(Component::LANG);
  if (m_country.has_value()) result |= static_cast<int>(Component::COUNTRY);
  if (m_modifier.has_value()) result |= static_cast<int>(Component::MODIFIER);
  return result;
}

Locale Locale::parse(std::string_view input) {
  enum class ParseState { Language, Country, Encoding, Modifier } currentState = ParseState::Language;
  size_t index = 0;
  std::string langPart;
  std::string countryPart;
  std::string encodingPart;
  std::string modifierPart;

  while (index < input.size() && input[index] != ']') {
    char currentChar = input[index];

    switch (currentState) {
      case ParseState::Language: {
        if (std::isalpha(static_cast<unsigned char>(currentChar))) {
          langPart += currentChar;
        } else {
          if (currentChar == '_') {
            currentState = ParseState::Country;
          } else if (currentChar == '.') {
            currentState = ParseState::Encoding;
          } else if (currentChar == '@') {
            currentState = ParseState::Modifier;
          }
        }
        break;
      }
      case ParseState::Country: {
        if (std::isalpha(static_cast<unsigned char>(currentChar))) {
          countryPart += currentChar;
        } else {
          if (currentChar == '.') {
            currentState = ParseState::Encoding;
          } else if (currentChar == '@') {
            currentState = ParseState::Modifier;
          }
        }
        break;
      }
      case ParseState::Encoding: {
        if (std::isalnum(static_cast<unsigned char>(currentChar))) {
          encodingPart += currentChar;
        } else if (currentChar == '@') {
          currentState = ParseState::Modifier;
        }
        break;
      }
      case ParseState::Modifier: {
        if (std::isalpha(static_cast<unsigned char>(currentChar))) {
          modifierPart += currentChar;
        }
        break;
      }
    }
    ++index;
  }

  Locale result;
  result.setLang(langPart);
  if (!countryPart.empty()) result.setCountry(countryPart);
  if (!encodingPart.empty()) result.setEncoding(encodingPart);
  if (!modifierPart.empty()) result.setModifier(modifierPart);

  return result;
}

Locale::Locale() = default;
Locale::Locale(std::string_view data) { *this = Locale::parse(data); }

std::string Locale::toString() const {
  std::string output = lang();

  if (m_country.has_value()) {
    output += '_';
    output += *m_country;
  }

  if (m_encoding.has_value()) {
    output += '.';
    output += *m_encoding;
  }

  if (m_modifier.has_value()) {
    output += '@';
    output += *m_modifier;
  }

  return output;
}

std::ostream& operator<<(std::ostream& stream, const xdgpp::Locale& locale) {
  stream << locale.toString();
  return stream;
}

