// Helper to check if triangle key exists — avoids duplicate lookup
inline bool TriangleExists(TriangleKey<true> const& key, ETNonmanifoldMesh::TMap const& map) {
    return map.find(key) != map.end();
}

ETNonmanifoldMesh::~ETNonmanifoldMesh() = default;

ETNonmanifoldMesh::ETNonmanifoldMesh(ECreator eCreator, TCreator tCreator)
    : mECreator(eCreator ? eCreator : CreateEdge),
      mTCreator(tCreator ? tCreator : CreateTriangle)
{
}

ETNonmanifoldMesh::ETNonmanifoldMesh(ETNonmanifoldMesh const& mesh)
{
    *this = mesh;
}

ETNonmanifoldMesh& ETNonmanifoldMesh::operator=(ETNonmanifoldMesh const& mesh)
{
    Clear();
    mECreator = mesh.mECreator;
    mTCreator = mesh.mTCreator;

    // Copy triangles by re-inserting them
    for (auto const& pair : mesh.mTMap)
    {
        auto const& tri = pair.first;
        Insert(tri.V[0], tri.V[1], tri.V[2]);
    }

    return *this;
}

ETNonmanifoldMesh::EMap const& ETNonmanifoldMesh::GetEdges() const
{
    return mEMap;
}

ETNonmanifoldMesh::TMap const& ETNonmanifoldMesh::GetTriangles() const
{
    return mTMap;
}

std::shared_ptr<ETNonmanifoldMesh::Triangle> ETNonmanifoldMesh::Insert(int v0, int v1, int v2)
{
    TriangleKey<true> triKey(v0, v1, v2);

    if (TriangleExists(triKey, mTMap))
    {
        return nullptr; // Already present
    }

    // Create triangle first (but don't insert yet)
    auto newTri = mTCreator(v0, v1, v2);

    // Process each edge: ensure it's created/updated before associating with triangle
    for (int idx = 0; idx < 3; ++idx)
    {
        int vA = newTri->V[idx];
        int vB = newTri->V[(idx + 1) % 3];

        EdgeKey<false> edgeKey(vA, vB);
        auto iter = mEMap.find(edgeKey);

        std::shared_ptr<Edge> edgePtr;

        if (iter == mEMap.end())
        {
            edgePtr = mECreator(vA, vB);
            mEMap.emplace(edgeKey, edgePtr);
        }
        else
        {
            edgePtr = iter->second;
            if (!edgePtr)
            {
                LogError("Unexpected condition.");
                return nullptr;
            }
        }

        newTri->E[idx] = edgePtr;
        edgePtr->T.insert(newTri);
    }

    // Now safely insert triangle into map
    mTMap.emplace(triKey, newTri);
    return newTri;
}

bool ETNonmanifoldMesh::Remove(int v0, int v1, int v2)
{
    TriangleKey<true> triKey(v0, v1, v2);
    auto tIter = mTMap.find(triKey);

    if (tIter == mTMap.end())
    {
        return false;
    }

    auto tri = tIter->second;

    // Detach triangle from its edges
    for (int i = 0; i < 3; ++i)
    {
        auto edge = tri->E[i].lock();
        if (!edge)
        {
            LogError("Unexpected condition.");
            return false;
        }

        size_t erasedCount = edge->T.erase(tri);
        if (erasedCount != 1)
        {
            LogError("Unexpected condition.");
            return false;
        }

        if (edge->T.empty())
        {
            EdgeKey<false> ekey(edge->V[0], edge->V[1]);
            mEMap.erase(ekey);
        }
    }

    mTMap.erase(tIter);
    return true;
}

void ETNonmanifoldMesh::Clear()
{
    mEMap.clear();
    mTMap.clear();
}

bool ETNonmanifoldMesh::IsManifold() const
{
    for (auto const& pair : mEMap)
    {
        if (pair.second->T.size() > 2)
        {
            return false;
        }
    }
    return true;
}

bool ETNonmanifoldMesh::IsClosed() const
{
    for (auto const& pair : mEMap)
    {
        if (pair.second->T.size() != 2)
        {
            return false;
        }
    }
    return true;
}

void ETNonmanifoldMesh::GetComponents(std::vector<std::vector<std::shared_ptr<Triangle>>>& components) const
{
    std::map<std::shared_ptr<Triangle>, int> status;
    for (auto const& entry : mTMap)
    {
        status[entry.second] = 0;
    }

    for (auto const& entry : mTMap)
    {
        auto tri = entry.second;
        if (status[tri] == 0)
        {
            std::vector<std::shared_ptr<Triangle>> comp;
            DepthFirstSearch(tri, status, comp);
            components.push_back(comp);
        }
    }
}

void ETNonmanifoldMesh::GetComponents(std::vector<std::vector<TriangleKey<true>>>& components) const
{
    std::map<std::shared_ptr<Triangle>, int> status;
    for (auto const& entry : mTMap)
    {
        status[entry.second] = 0;
    }

    for (auto const& entry : mTMap)
    {
        auto tri = entry.second;
        if (status[tri] == 0)
        {
            std::vector<std::shared_ptr<Triangle>> comp;
            DepthFirstSearch(tri, status, comp);

            std::vector<TriangleKey<true>> keys;
            keys.reserve(comp.size());
            for (auto const& t : comp)
            {
                keys.emplace_back(t->V[0], t->V[1], t->V[2]);
            }
            components.push_back(keys);
        }
    }
}

void ETNonmanifoldMesh::DepthFirstSearch(
    std::shared_ptr<Triangle> const& start,
    std::map<std::shared_ptr<Triangle>, int>& visited,
    std::vector<std::shared_ptr<Triangle>>& component) const
{
    std::vector<std::shared_ptr<Triangle>> stack;
    stack.reserve(mTMap.size());
    stack.push_back(start);

    while (!stack.empty())
    {
        auto current = stack.back();

        if (visited[current] == 0)
        {
            visited[current] = 1;
        }

        bool pushed = false;
        for (int i = 0; i < 3; ++i)
        {
            auto edge = current->E[i].lock();
            if (!edge)
            {
                LogError("Unexpected condition.");
                return;
            }

            for (auto adjWeak : edge->T)
            {
                auto adj = adjWeak.lock();
                if (!adj)
                {
                    LogError("Unexpected condition.");
                    return;
                }

                if (visited[adj] == 0)
                {
                    stack.push_back(adj);
                    pushed = true;
                    break;
                }
            }

            if (pushed) break;
        }

        if (!pushed)
        {
            visited[current] = 2;
            component.push_back(current);
            stack.pop_back();
        }
    }
}

std::shared_ptr<ETNonmanifoldMesh::Edge> ETNonmanifoldMesh::CreateEdge(int v0, int v1)
{
    return std::make_shared<Edge>(v0, v1);
}

std::shared_ptr<ETNonmanifoldMesh::Triangle> ETNonmanifoldMesh::CreateTriangle(int v0, int v1, int v2)
{
    return std::make_shared<Triangle>(v0, v1, v2);
}

ETNonmanifoldMesh::Edge::~Edge() = default;

ETNonmanifoldMesh::Edge::Edge(int v0, int v1)
{
    V[0] = v0;
    V[1] = v1;
}

ETNonmanifoldMesh::Triangle::~Triangle() = default;

ETNonmanifoldMesh::Triangle::Triangle(int v0, int v1, int v2)
{
    V[0] = v0;
    V[1] = v1;
    V[2] = v2;
}

#include "ztimer.h"

ZTimer::ZTimer() : m_timerStarted(false), m_timerFinished(false), m_repeatingTimer(false) {
}

ZTimer::ZTimer(Duration duration_ms) 
    : m_timerDuration(duration_ms), m_timerStarted(false), m_timerFinished(false), m_repeatingTimer(false) {
}

ZTimer::ZTimer(Duration duration_ms, CallbackFunc callback)
    : m_timerDuration(duration_ms), m_callback(callback), 
      m_timerStarted(false), m_timerFinished(false), m_repeatingTimer(false) {
}

ZTimer::~ZTimer() {
    if (m_timerStarted) {
        Stop();
    }
}

void ZTimer::Start() {
    m_startTime = Clock::now();
    m_currentTime = m_startTime;
    m_timerStarted = true;
    m_timerFinished = false;
}

void ZTimer::Stop() {
    m_timerStarted = false;
}

void ZTimer::SetDuration(Duration duration_ms) {
    if (!m_timerStarted) {
        m_timerDuration = duration_ms;
    }
}

void ZTimer::SetCallback(std::function<void()> callback) {
    if (!m_timerStarted) {
        m_callback = std::move(callback);
    }
}

void ZTimer::SetRepeating(bool value) {
    if (!m_timerStarted) {
        m_repeatingTimer = value;
    }
}

void ZTimer::Update(Duration deltaTime) {
    if (!m_timerStarted) {
        return;
    }

    m_currentTime += deltaTime;

    if (m_currentTime >= m_startTime + m_timerDuration) {
        if (m_callback) {
            m_callback();
        }

        if (!m_repeatingTimer) {
            Stop();
            m_timerFinished = true;
        } else {
            Start();
        }
    }
}

