namespace fs = std::filesystem;

// Helper: Read file as wide string, assuming UTF-8 encoding
std::wstring LoadWStringFromUtf8File(const std::wstring& path)
{
    std::ifstream ifs(fs::path(path), std::ios::binary | std::ios::ate);
    if (!ifs)
        return L"";

    const auto size = ifs.tellg();
    ifs.seekg(0, std::ios::beg);

    std::string rawBytes(size, '\0');
    if (!ifs.read(rawBytes.data(), size))
        return L"";

    std::u16string utf16;
    try {
        utf8::unchecked::utf8to16(rawBytes.begin(), rawBytes.end(), std::back_inserter(utf16));
    } catch (...) {
        return L"";
    }

    return std::wstring(utf16.begin(), utf16.end());
}

// Helper: Replace placeholders like {0}, {1}, ..., {8} in template string
std::wstring ReplacePlaceholders(const std::wstring& templateStr,
                                 const std::vector<std::wstring>& replacements)
{
    std::wstring result = templateStr;
    for (size_t i = 0; i < replacements.size() && i < 9; ++i)
    {
        std::wstring placeholder = L"{" + std::to_wstring(i) + L"}";
        size_t pos = 0;
        while ((pos = result.find(placeholder, pos)) != std::wstring::npos)
        {
            result.replace(pos, placeholder.length(), replacements[i]);
            pos += replacements[i].length();
        }
    }
    return result;
}

int PrepareCandidateWindowSciterHtml()
{
    const auto appDataPath = CommonUtils::get_local_appdata_path();
    const fs::path baseDir = fs::path(string_to_wstring(appDataPath)) / GlobalIme::AppName;

    std::wstring verticalDarkNormal = L"vertical_candidate_window_dark_normal.html";
    std::wstring verticalDarkBody = L"vertical_candidate_window_dark.html";
    std::wstring horizontalDarkNormal = L"horizontal_candidate_window_dark_normal.html";
    std::wstring horizontalDarkBody = L"horizontal_candidate_window_dark.html";

    bool isHorizontal = false;
    bool isNormal = true;

    std::wstring entireHtml, bodyHtml;

    if (isHorizontal)
    {
        entireHtml = baseDir / L"html/sciter/default-themes" /
                     (isNormal ? horizontalDarkNormal : horizontalDarkBody);
        bodyHtml = baseDir / L"html/sciter/default-themes/body" /
                   (isNormal ? horizontalDarkNormal : horizontalDarkBody);
    }
    else
    {
        entireHtml = baseDir / L"html/sciter/default-themes" / verticalDarkBody;
        bodyHtml = baseDir / L"html/sciter/default-themes/body" / verticalDarkBody;
    }

    ::BodyString = LoadWStringFromUtf8File(bodyHtml.wstring());
    OutputDebugString(bodyHtml.wstring().c_str());

    return 0;
}

void InflateCandidateWindowSciter(std::wstring& input)
{
    std::wistringstream stream(input);
    std::vector<std::wstring> tokens;
    std::wstring token;

    while (std::getline(stream, token, L','))
        tokens.push_back(token);

    // Pad with empty strings up to 9 elements
    tokens.resize(9, L"");

    std::wstring rendered = ReplacePlaceholders(::BodyString, tokens);

    // Truncate after last valid anchor comment if fewer than 9 items
    if (tokens.size() < 9)
    {
        std::wstring anchorComment = L"<!--{" + std::to_wstring(tokens.size()) + L"}Anchor-->";
        size_t anchorPos = rendered.find(anchorComment);
        if (anchorPos != std::wstring::npos)
            rendered = rendered.substr(0, anchorPos) + L"</div>";
    }

    UpdateBodyContent(::global_hwnd, rendered.c_str());
}

SBOOL SC_CALLBACK UpdateBodyCallback(HELEMENT he, LPVOID param)
{
    const wchar_t* content = static_cast<const wchar_t*>(param);
    std::wstring ws(content);
    std::string utf8;
    try {
        utf8::unchecked::utf16to8(ws.begin(), ws.end(), std::back_inserter(utf8));
    } catch (...) {
        return FALSE;
    }

    SciterSetElementHtml(
        he,
        reinterpret_cast<const BYTE*>(utf8.c_str()),
        static_cast<UINT>(utf8.size()),
        SIH_REPLACE_CONTENT
    );
    return FALSE;
}

void UpdateBodyContent(HWND hwnd, const wchar_t* newContent)
{
    HELEMENT root = nullptr;
    if (SciterGetRootElement(hwnd, &root) != SCDOM_OK || !root)
        return;

    sciter::value dummy;
    SciterCallScriptingFunction(root, "ClearState", nullptr, 0, &dummy);

    SciterSelectElementsW(root, WSTR("body"), UpdateBodyCallback, (LPVOID)newContent);
}

int AdjustWndPosition(HWND hwnd, int cx, int cy, int w, int h, int outPos[2])
{
    outPos[0] = cx;
    outPos[1] = cy + 3;

    MonitorCoordinates bounds = GetMonitorCoordinates();

    // Clamp left/top edges
    if (outPos[0] < bounds.left) outPos[0] = bounds.left + 2;
    if (outPos[1] < bounds.top)  outPos[1] = bounds.top + 2;

    // Clamp right edge
    if (outPos[0] + w > bounds.right)
        outPos[0] = bounds.right - w - 2;

    // Clamp bottom edge (flip above if needed)
    if (outPos[1] + ::cand_window_height_array[7] > bounds.bottom)
        outPos[1] = outPos[1] - h - 30 - 2;

    return 0;
}

void SciterBridgeJs::adjustInitialWindowSize(sciter::value widthVal, sciter::value heightVal)
{
    int w = widthVal.is_int() ? widthVal.get<int>() : 0;
    int h = heightVal.is_int() ? heightVal.get<int>() : 0;

#ifdef FANY_DEBUG
    OutputDebugString(fmt::format(L"Candidate Window size: {} {}", w, h).c_str());
#endif

    ::CANDIDATE_WINDOW_WIDTH = w;
    ::DEFAULT_WINDOW_WIDTH = w;
    ::CANDIDATE_WINDOW_HEIGHT = h;
    ::cand_window_width_array[0] = w;
    ::cand_window_width_array[1] = w;

    UINT flags = SWP_NOZORDER | SWP_NOMOVE;
    SetWindowPos(
        ::global_hwnd,
        nullptr,
        0, 0,
        w + ::SHADOW_WIDTH,
        h + ::SHADOW_WIDTH,
        flags
    );
}

void SciterBridgeJs::preserveWindowSize(sciter::value idxVal, sciter::value wVal, sciter::value hVal)
{
    int idx = idxVal.is_int() ? idxVal.get<int>() : -1;
    int w = wVal.is_int() ? wVal.get<int>() : 0;
    int h = hVal.is_int() ? hVal.get<int>() : 0;

    if (idx >= 0 && idx < ::MAX_HAN_CHARS)
        ::cand_window_width_array[idx] = w;

    if (idx >= 2 && idx - 2 < ::MAX_HAN_CHARS)
        ::cand_window_height_array[idx - 2] = h;
}

