static const int kPowerTableSize = DOUBLE_CONVERSION_ARRAY_SIZE(powerTable);
static const int kBaseDecimalExponent = -348; // First entry's decimal exponent
static const double kLog10OverLog2 = 3.321928094887362; // lg(10)

void GetCachedPowerForBinaryExponentRange(
    int min_exp,
    int max_exp,
    DiyFp* result_power,
    int* result_decimal_exp) {
  const int precision = DiyFp::kSignificandSize;
  double approx_k = ceil((min_exp + precision - 1) * kLog10OverLog2);

  int base_offset = kBaseDecimalExponent;
  int step_size = kDecimalExponentDistance;
  int pos = (base_offset + static_cast<int>(approx_k) - 1) / step_size + 1;

  DOUBLE_CONVERSION_ASSERT(pos >= 0 && pos < kPowerTableSize);

  PowerTableEntry entry = powerTable[pos];
  DOUBLE_CONVERSION_ASSERT(min_exp <= entry.exp2);
  (void) max_exp;  // Suppress unused parameter warning

  DOUBLE_CONVERSION_ASSERT(entry.exp2 <= max_exp);
  *result_decimal_exp = entry.exp10;
  *result_power = DiyFp(entry.mantissa, entry.exp2);
}

void GetCachedPowerForDecimalExponent(int desired_exp,
                                      DiyFp* out_power,
                                      int* actual_exp) {
  DOUBLE_CONVERSION_ASSERT(kMinDecimalExponent <= desired_exp);
  DOUBLE_CONVERSION_ASSERT(desired_exp < kMaxDecimalExponent + kDecimalExponentDistance);

  int table_index = (desired_exp - kBaseDecimalExponent) / kDecimalExponentDistance;
  DOUBLE_CONVERSION_ASSERT(table_index >= 0 && table_index < kPowerTableSize);

  PowerTableEntry entry = powerTable[table_index];
  *out_power = DiyFp(entry.mantissa, entry.exp2);
  *actual_exp = entry.exp10;

  DOUBLE_CONVERSION_ASSERT(*actual_exp <= desired_exp);
  DOUBLE_CONVERSION_ASSERT(desired_exp < *actual_exp + kDecimalExponentDistance);
}
