#include "llvm/BinaryFormat/ELF.h"

using namespace eld;

HexagonELFDynamic::HexagonELFDynamic(GNULDBackend &pParent, LinkerConfig &pConfig)
    : ELFDynamic(pParent, pConfig) {}

HexagonELFDynamic::~HexagonELFDynamic() {}

void HexagonELFDynamic::reserveTargetEntries() {
  // Reserve entries for Hexagon-specific dynamic tags
  reserveOne(eld::DT_HEXAGON_VER);
  reserveOne(llvm::ELF::DT_RELACOUNT);
}

void HexagonELFDynamic::applyTargetEntries() {
  // Set the Hexagon version tag to a fixed value (0x3)
  applyOne(eld::DT_HEXAGON_VER, 0x3);

  // Count only RELATIVE relocations in .rela.dyn
  uint32_t relativeRelocCount = 0;
  const auto &relocations = m_Backend.getRelaDyn()->getRelocations();

  for (const auto &reloc : relocations) {
    if (reloc->type() == llvm::ELF::R_HEX_RELATIVE) {
      ++relativeRelocCount;
    }
  }

  // Apply the computed count to DT_RELACOUNT
  applyOne(llvm::ELF::DT_RELACOUNT, relativeRelocCount);
}

#include "flareqt/filefield.h"
#include "flareqt/dvdialog.h"
#include "flareqt/gutil.h"
#include "flareqt/lineedit.h"
#include "tfilepath.h"
#include <QHBoxLayout>
#include <QPushButton>
#include <QFileDialog>

using namespace DVGui;

// Static controller instance shared across all FileField instances
FileField::BrowserPopupController* FileField::m_browserPopupController = nullptr;

//=============================================================================
// FileField Implementation
//-----------------------------------------------------------------------------
FileField::FileField(QWidget* parent, QString initialPath, bool isReadOnly,
                     bool skipInitialBrowse, bool isCodePath)
    : QWidget(parent)
    , m_filters(QStringList())
    , m_fileMode(QFileDialog::Directory)  // Default: directory selection only
    , m_lastSelectedPath(std::move(initialPath))
    , m_codePath(isCodePath) {

    setMaximumHeight(WidgetHeight);

    // Initialize UI components
    m_inputField = new LineEdit(m_lastSelectedPath);
    m_browseBtn = new QPushButton(tr("..."));
    m_inputField->setReadOnly(isReadOnly);
    m_browseBtn->setMinimumSize(20, WidgetHeight);
    m_browseBtn->setObjectName("PushButton_NoPadding");

    // If initial content should not trigger browsing, store as description text
    if (skipInitialBrowse) {
        m_descriptionText = m_lastSelectedPath;
    }

    setFocusProxy(m_inputField);

    // Build layout
    QHBoxLayout* mainLayout = new QHBoxLayout();
    mainLayout->setContentsMargins(0, 0, 0, 0);
    mainLayout->setSpacing(1);

    mainLayout->addWidget(m_inputField, /*stretch*/5);
    mainLayout->addWidget(m_browseBtn, /*stretch*/1);

    setLayout(mainLayout);

    // Connect signals
    if (!isReadOnly) {
        connect(m_inputField, &LineEdit::editingFinished, this, &FileField::pathChanged);
    }
    connect(m_browseBtn, &QPushButton::pressed, this, &FileField::browseDirectory);
}
//-----------------------------------------------------------------------------
void FileField::setFileMode(const QFileDialog::FileMode& mode) {
    m_fileMode = mode;
}
//-----------------------------------------------------------------------------
void FileField::setFilters(const QStringList& filterList) {
    m_filters = filterList;
}
//-----------------------------------------------------------------------------
QString FileField::getPath() const {
    return m_inputField->text();
}
//-----------------------------------------------------------------------------
void FileField::setPath(const QString& newPath) {
    m_inputField->setText(newPath);
    m_lastSelectedPath = newPath;
}
//-----------------------------------------------------------------------------
void FileField::setBrowserPopupController(BrowserPopupController* controller) {
    m_browserPopupController = controller;
}
//-----------------------------------------------------------------------------
FileField::BrowserPopupController* FileField::getBrowserPopupController() {
    return m_browserPopupController;
}
//-----------------------------------------------------------------------------
void FileField::browseDirectory() {
    // Ensure button has focus before proceeding
    if (!m_browseBtn->hasFocus()) {
        return;
    }

    // Early exit if no popup controller is registered
    if (!m_browserPopupController) {
        return;
    }

    // Determine starting directory for dialog
    QString startDir;
    if (m_lastSelectedPath != m_descriptionText) {
        startDir = m_lastSelectedPath;
    }

    // Open the file browser popup
    m_browserPopupController->openPopup(
        m_filters,
        (m_fileMode == QFileDialog::Directory),
        startDir,
        this
    );

    // Retrieve selected path if dialog was accepted
    if (m_browserPopupController->isExecute()) {
        QString selectedPath = m_browserPopupController->getPath(m_codePath);
        if (!selectedPath.isEmpty()) {
            setPath(selectedPath);
            m_lastSelectedPath = selectedPath;
            emit pathChanged();
        }
    }
}

