// Copied from https://github.com/pytorch/pytorch/commit/7931eee5c5ebcdf468bff4d308510b03355cd909
// This is so that we can pass in torch.dtype as a parameter to the function.
#if TORCH_VERSION_MAJOR < 2 || (TORCH_VERSION_MAJOR == 2 && TORCH_VERSION_MINOR < 4)
#include <pybind11/pybind11.h>
#include <pybind11/stl.h>
namespace pybind11::detail {
    template <>
    struct type_caster<at::ScalarType> {
    public:
        // NOLINTNEXTLINE(cppcoreguidelines-non-private-member-variables-in-classes)
        PYBIND11_TYPE_CASTER(at::ScalarType, _("torch.dtype"));
        // PYBIND11_TYPE_CASTER defines a member field called value. at::ScalarType
        // cannot be default-initialized, we provide this constructor to explicitly
        // initialize that field. The value doesn't matter as it will be overwritten
        // after a successful call to load.
        type_caster() : value(at::kFloat) {}
        bool load(handle src, bool) {
            PyObject* obj = src.ptr();
            if (THPDtype_Check(obj)) {
                value = reinterpret_cast<THPDtype*>(obj)->scalar_type;
                return true;
            }
            return false;
        }
        static handle cast(
                           const at::ScalarType& src,
                           return_value_policy /* policy */,
                           handle /* parent */) {
            return Py_NewRef(torch::getTHPDtype(src));
        }
    };
} // namespace pybind11::detail
#endif

#define CHECK_DEVICE(x) TORCH_CHECK(x.is_cuda(), #x " must be on CUDA")
#define CHECK_SHAPE(x, ...) TORCH_CHECK(x.sizes() == torch::IntArrayRef({__VA_ARGS__}), #x " must have shape (" #__VA_ARGS__ ")")
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")

void configure_forward_params(Flash_fwd_params &params,
                              // dimensions
                              const int batch_size,
                              const int query_seq_len,
                              const int key_seq_len,
                              const int q_rounded,
                              const int k_rounded,
                              const int num_heads,
                              const int kv_heads,
                              const int head_dim,
                              const int d_rounded,
                              // device pointers
                              const at::Tensor q_tensor,
                              const at::Tensor k_tensor,
                              const at::Tensor v_tensor,
                              at::Tensor out_tensor,
                              void *q_seqlens_d,
                              void *k_seqlens_d,
                              void *q_used_mask,
                              void *k_used_mask,
                              void *softmax_lse_d,
                              float dropout_prob,
                              float scale_factor,
                              int window_left,
                              int window_right,
                              const float cap_value=0.f,
                              const int sm_reserved=0) {
    // Initialize parameters structure
    params = {};
    params.is_bf16 = q_tensor.dtype() == torch::kBFloat16;
    params.is_e4m3 = q_tensor.dtype() == torch::kFloat8_e4m3fn;

    // Set memory addresses
    params.q_ptr = q_tensor.data_ptr();
    params.k_ptr = k_tensor.data_ptr();
    params.v_ptr = v_tensor.data_ptr();

    // All strides are in elements, not bytes
    params.q_row_stride = q_tensor.stride(-3);
    params.k_row_stride = k_tensor.stride(-3);
    params.v_row_stride = v_tensor.stride(-3);
    params.q_head_stride = q_tensor.stride(-2);
    params.k_head_stride = k_tensor.stride(-2);
    params.v_head_stride = v_tensor.stride(-2);
    params.v_dim_stride = v_tensor.stride(-1);
    params.o_ptr = out_tensor.data_ptr();
    params.o_row_stride = out_tensor.stride(-3);
    params.o_head_stride = out_tensor.stride(-2);

    if (q_seqlens_d == nullptr) {
        params.q_batch_stride = q_tensor.stride(0);
        params.o_batch_stride = out_tensor.stride(0);
    }
    if (k_seqlens_d == nullptr) {
        params.k_batch_stride = k_tensor.stride(0);
        params.v_batch_stride = v_tensor.stride(0);
    }

    params.cu_seqlens_q = static_cast<int *>(q_seqlens_d);
    params.cu_seqlens_k = static_cast<int *>(k_seqlens_d);
    params.seqused_q = static_cast<int *>(q_used_mask);
    params.seqused_k = static_cast<int *>(k_used_mask);

    // Softmax sum storage
    params.softmax_lse_ptr = softmax_lse_d;

    // Configure dimensions
    params.b = batch_size;
    params.h = num_heads;
    params.h_k = kv_heads;
    params.seqlen_q = query_seq_len;
    params.seqlen_k = key_seq_len;
    params.seqlen_q_rounded = q_rounded;
    params.seqlen_k_rounded = k_rounded;
    params.d = head_dim;
    params.d_rounded = d_rounded;

    // Set scaling factors
    params.scale_softmax = scale_factor;
    params.softcap = cap_value;

    // Convert dropout probability for internal use
    params.p_dropout = 1.f - dropout_prob;
    params.p_dropout_in_uint8_t = uint8_t(std::floor(params.p_dropout * 255.0));
    params.rp_dropout = 1.f / params.p_dropout;
    TORCH_CHECK(dropout_prob < 1.f);

#ifdef FLASHATTENTION_DISABLE_DROPOUT
    TORCH_CHECK(dropout_prob == 0.0f, "This flash attention build does not support dropout.");
#endif

    // Determine attention pattern
    params.is_causal = window_left < 0 && window_right == 0;
    params.is_local = (window_left >= 0 || window_right >= 0) && !params.is_causal;

    // Adjust window sizes for special cases
    if (window_left < 0 && window_right >= 0) { window_left = key_seq_len - 1; }
    if (window_left >= 0 && window_right < 0) { window_right = query_seq_len - 1; }

    params.window_size_left = window_left;
    params.window_size_right = window_right;

    // Get GPU architecture info
    auto dev_props = at::cuda::getCurrentDeviceProperties();
    params.arch = dev_props->major * 10 + dev_props->minor;
    params.num_sm = dev_props->multiProcessorCount - sm_reserved;

#ifdef FLASHATTENTION_DISABLE_LOCAL
    TORCH_CHECK(!params.is_local, "This flash attention build does not support local attention.");
#endif
}

void configure_backward_params(Flash_bwd_params &params,
                               // dimensions
                               const int batch_size,
                               const int query_seq_len,
                               const int key_seq_len,
                               const int q_rounded,
                               const int k_rounded,
                               const int num_heads,
                               const int kv_heads,
                               const int head_dim,
                               const int d_rounded,
                               // device pointers
                               const at::Tensor q_tensor,
                               const at::Tensor k_tensor,
                               const at::Tensor v_tensor,
                               const at::Tensor out_tensor,
                               const at::Tensor grad_output,
                               at::Tensor grad_q,
                               at::Tensor grad_k,
                               at::Tensor grad_v,
                               void *q_seqlens_d,
                               void *k_seqlens_d,
                               void *q_used_mask,
                               void *k_used_mask,
                               void *dq_accum_d,
                               void *dk_accum_d,
                               void *dv_accum_d,
                               void *softmax_lse_d,
                               void *dsoftmax_sum_d,
                               float dropout_prob,
                               float scale_factor,
                               int window_left,
                               int window_right,
                               const float cap_value=0.f,
                               bool deterministic=false,
                               int const sm_reserved=0) {
    // Reuse forward configuration
    configure_forward_params(params,
                             batch_size, query_seq_len, key_seq_len, q_rounded, k_rounded, 
                             num_heads, kv_heads, head_dim, d_rounded,
                             q_tensor, k_tensor, v_tensor, out_tensor,
                             q_seqlens_d, k_seqlens_d, q_used_mask, k_used_mask,
                             softmax_lse_d, dropout_prob, scale_factor,
                             window_left, window_right, cap_value, sm_reserved);

    // Add gradient-specific pointers and strides
    params.do_ptr = grad_output.data_ptr();
    params.do_row_stride = grad_output.stride(-3);
    params.do_head_stride = grad_output.stride(-2);
    params.dq_ptr = grad_q.data_ptr();
    params.dk_ptr = grad_k.data_ptr();
    params.dv_ptr = grad_v.data_ptr();
    params.dq_row_stride = grad_q.stride(-3);
    params.dk_row_stride = grad_k.stride(-3);
    params.dv_row_stride = grad_v.stride(-3);
    params.dq_head_stride = grad_q.stride(-2);
    params.dk_head_stride = grad_k.stride(-2);
    params.dv_head_stride = grad_v.stride(-2);

    if (q_seqlens_d == nullptr) {
        params.do_batch_stride = grad_output.stride(0);
        params.dq_batch_stride = grad_q.stride(0);
        params.dk_batch_stride = grad_k.stride(0);
        params.dv_batch_stride = grad_v.stride(0);
    }

    params.dq_accum_ptr = dq_accum_d;
    params.dk_accum_ptr = dk_accum_d;
    params.dv_accum_ptr = dv_accum_d;
    params.dsoftmax_sum = dsoftmax_sum_d;
    params.deterministic = deterministic;
}

void execute_forward_kernel(Flash_fwd_params &params, cudaStream_t stream) {
    // Validate split configuration
    TORCH_CHECK(params.num_splits >= 1);

    // Architecture-specific dispatch
    ARCH_SWITCH(params.arch, Arch, [&] {
        SPLIT_SWITCH(params.num_splits > 1, Split, [&] {
            PAGEDKV_SWITCH(params.page_table && !params.pagedkv_tma, PagedKVNonTMA, [&] {
                PACKGQA_SWITCH(params.pack_gqa, PackGQA_, [&] {
                    // Enable PackGQA for older architectures or special cases
                    static constexpr bool PackGQA = PackGQA_ || Arch < 90 || PagedKVNonTMA || Split;

                    SOFTCAP_SWITCH(params.softcap > 0.0, Has_softcap, [&] {
                        if (!params.is_e4m3) {
                            if (params.is_bf16) {
                                #ifndef FLASHATTENTION_DISABLE_HDIM64
                                if (params.d <= 64) {
                                    if (params.dv > 256 && Arch == 90) {
                                        return run_mha_fwd_<Arch, cutlass::bfloat16_t, 64, 512, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    } else if (params.dv > 64 && Arch == 90) {
                                        return run_mha_fwd_<Arch, cutlass::bfloat16_t, 64, 256, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    } else {
                                        return run_mha_fwd_<Arch, cutlass::bfloat16_t, 64, 64, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    }
                                }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM96
                                if (params.d <= 96) { return run_mha_fwd_<Arch, cutlass::bfloat16_t, 96, 96, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM128
                                if (params.d <= 128) { return run_mha_fwd_<Arch, cutlass::bfloat16_t, 128, 128, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM192
                                if (params.d <= 192) {
                                    if (params.dv <= 128 && Arch == 90) {
                                        return run_mha_fwd_<Arch, cutlass::bfloat16_t, 192, 128, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    } else {
                                        return run_mha_fwd_<Arch, cutlass::bfloat16_t, 192, 192, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    }
                                }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM256
                                if (params.d <= 256) { return run_mha_fwd_<Arch, cutlass::bfloat16_t, 256, 256, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                                #endif
                            } else {
                                #ifndef FLASHATTENTION_DISABLE_FP16
                                #ifndef FLASHATTENTION_DISABLE_HDIM64
                                if (params.d <= 64) {
                                    if (params.dv > 256 && Arch == 90) {
                                        return run_mha_fwd_<Arch, cutlass::half_t, 64, 512, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    } else if (params.dv > 64 && Arch == 90) {
                                        return run_mha_fwd_<Arch, cutlass::half_t, 64, 256, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    } else {
                                        return run_mha_fwd_<Arch, cutlass::half_t, 64, 64, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    }
                                }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM96
                                if (params.d <= 96) { return run_mha_fwd_<Arch, cutlass::half_t, 96, 96, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM128
                                if (params.d <= 128) { return run_mha_fwd_<Arch, cutlass::half_t, 128, 128, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM192
                                if (params.d <= 192) {
                                    if (params.dv <= 128 && Arch == 90) {
                                        return run_mha_fwd_<Arch, cutlass::half_t, 192, 128, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    } else {
                                        return run_mha_fwd_<Arch, cutlass::half_t, 192, 192, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                    }
                                }
                                #endif
                                #ifndef FLASHATTENTION_DISABLE_HDIM256
                                if (params.d <= 256) { return run_mha_fwd_<Arch, cutlass::half_t, 256, 256, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                                #endif
                                #else
                                TORCH_CHECK(false, "This flash attention build does not support FP16.");
                                #endif
                            }
                        } else {
                            #ifndef FLASHATTENTION_DISABLE_FP8
                            #ifndef FLASHATTENTION_DISABLE_HDIM64
                            if (params.d <= 64) { return run_mha_fwd_<90, cutlass::float_e4m3_t, 64, 64, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                            #endif
                            #ifndef FLASHATTENTION_DISABLE_HDIM96
                            if (params.d <= 96) { return run_mha_fwd_<90, cutlass::float_e4m3_t, 96, 96, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                            #endif
                            #ifndef FLASHATTENTION_DISABLE_HDIM128
                            if (params.d <= 128) { return run_mha_fwd_<90, cutlass::float_e4m3_t, 128, 128, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                            #endif
                            #ifndef FLASHATTENTION_DISABLE_HDIM192
                            if (params.d <= 192) {
                                if (params.dv <= 128 && Arch == 90) {
                                    return run_mha_fwd_<90, cutlass::float_e4m3_t, 192, 128, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                } else {
                                    return run_mha_fwd_<90, cutlass::float_e4m3_t, 192, 192, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream);
                                }
                            }
                            #endif
                            #ifndef FLASHATTENTION_DISABLE_HDIM256
                            if (params.d <= 256) { return run_mha_fwd_<90, cutlass::float_e4m3_t, 256, 256, Split, PagedKVNonTMA, Has_softcap, PackGQA>(params, stream); }
                            #endif
                            #else
                            TORCH_CHECK(false, "This flash attention build does not support FP8.");
                            #endif
                        }
                    });
                });
            });
        });
    });
}

void execute_combine_kernel(Flash_fwd_params &params, cudaStream_t stream, bool enable_pdl=false) {
#ifndef FLASHATTENTION_DISABLE_SPLIT
    // Select block size based on head dimension and precision
    if (params.is_fp32) {
        if (params.dv <= 64) {
            run_mha_fwd_combine_<float, float, 64>(params, stream, enable_pdl);
        } else {
            run_mha_fwd_combine_<float, float, 128>(params, stream, enable_pdl);
        }
    } else if (params.is_bf16) {
        if (params.dv <= 64) {
            run_mha_fwd_combine_<cutlass::bfloat16_t, float, 64>(params, stream, enable_pdl);
        } else {
            run_mha_fwd_combine_<cutlass::bfloat16_t, float, 128>(params, stream, enable_pdl);
        }
    } else {
        if (params.dv <= 64) {
            run_mha_fwd_combine_<cutlass::half_t, float, 64>(params, stream, enable_pdl);
        } else {
            run_mha_fwd_combine_<cutlass::half_t, float, 128>(params, stream, enable_pdl);
        }
    }
#else
    TORCH_CHECK(false, "This flash attention build does not support combine kernels.");
#endif
}

inline bool check_pagedkv_tma(Flash_fwd_params const& params) {
    // TMA requires specific conditions
    if (params.arch < 90 || !params.page_table || params.leftpad_k || params.knew_ptr) { return false; }

    // Check kernel configuration compatibility
    auto kernel_config = tile_size_fwd_sm90(params.d_rounded, params.dv_rounded, params.is_causal, params.is_local, 
                                           params.is_e4m3 ? 1 : 2, false, false, params.softcap > 0.f);
    int const block_m = std::get<0>(kernel_config);
    int const block_n = std::get<1>(kernel_config);

    // Avoid TMA when sequence length is small relative to block size
    return params.page_size % block_n == 0 && params.seqlen_q * (params.h / params.h_k) > block_m;
}

inline bool determine_pack_gqa(Flash_fwd_params const& params) {
    // Always enable for older architectures or special cases
    if (params.arch < 90 || (params.page_table && !params.pagedkv_tma) || params.num_splits > 1) { return true; }

#ifdef FLASHATTENTION_DISABLE_PACKGQA
    return false;
#else
    // Skip GQA packing if heads match
    if (params.h == params.h_k) { return false; }

    // Check kernel configuration
    auto kernel_config = tile_size_fwd_sm90(params.d_rounded, params.dv_rounded, params.is_causal, params.is_local, 
                                           params.is_e4m3 ? 1 : 2, false, params.page_table && !params.pagedkv_tma, params.softcap > 0.f);
    int const block_m = std::get<0>(kernel_config);
    return should_pack_gqa(params.cu_seqlens_q || params.seqused_q, params.seqlen_q, params.h / params.h_k, block_m);
#endif
}

inline int calculate_num_splits(Flash_fwd_params const& params) {
#ifdef FLASHATTENTION_DISABLE_SPLIT
    return 1;
#else
    // Handle variable-length sequences
    bool varlen = params.cu_seqlens_q || params.cu_seqlens_k || params.seqused_q || params.seqused_k || params.leftpad_k;

    // Get kernel configurations for different architectures
    auto sm90_config = tile_size_fwd_sm90(params.d_rounded, params.dv_rounded, params.is_causal, params.is_local, 
                                         params.is_e4m3 ? 1 : 2, false, params.page_table && !params.pagedkv_tma, params.softcap > 0.f, use_one_mma_wg(params));
    auto sm8x_config = tile_size_fwd_sm8x(params.arch == 86 || params.arch == 89, params.d_rounded, params.dv_rounded, 
                                         params.is_causal, params.is_local, params.is_e4m3 ? 1 : 2, params.page_table, varlen, params.softcap > 0.f, params.knew_ptr);

    int const block_m = params.arch >= 90 ? std::get<0>(sm90_config) : std::get<0>(sm8x_config);
    int const block_n = params.arch >= 90 ? std::get<1>(sm90_config) : std::get<1>(sm8x_config);

    int seq_q_packed = params.seqlen_q * (params.h / params.h_k);

    // Calculate effective sequence length for local attention
    int effective_seq_k = !params.is_local
        ? params.seqlen_k
        : std::max(0, std::min(params.seqlen_k, params.window_size_right + params.window_size_left + 1 + block_m));

    int const num_n_blocks = (effective_seq_k + block_n - 1) / block_n;
    int const num_m_blocks = (seq_q_packed + block_m - 1) / block_m;
    int const kv_memory_per_head = params.seqlen_k * (params.d + params.dv) * (params.is_e4m3 ? 1 : 2);

    // Estimate total work for scheduling
    int total_mblocks = (params.num_splits_dynamic_ptr ? 1 : params.b) * params.h_k * num_m_blocks;
    return num_splits_heuristic(total_mblocks, params.num_sm, num_n_blocks, num_m_blocks, kv_memory_per_head, params.is_causal || params.is_local, 128);
#endif
}

inline int get_max_supported_head_dim() {
#ifndef FLASHATTENTION_DISABLE_HDIM256
    return 256;
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM192
    return 192;
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM128
    return 128;
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM96
    return 96;
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM64
    return 64;
#endif
    return 0;
}

inline int align_head_dim(int head_size) {
#ifndef FLASHATTENTION_DISABLE_HDIM64
    if (head_size <= 64) { return 64; }
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM96
    if (head_size <= 96) { return 96; }
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM128
    if (head_size <= 128) { return 128; }
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM192
    if (head_size <= 192) { return 192; }
#endif
#ifndef FLASHATTENTION_DISABLE_HDIM256
    if (head_size <= 256) { return 256; }
#endif
    return 256;
}

inline int align_head_dim_v(int head_size) {
    if (head_size <= 64) { return 64; }
    if (head_size <= 96) { return 96; }
    if (head_size <= 128) { return 128; }
    if (head_size <= 192) { return 192; }
    if (head_size <= 256) { return 256; }
    return 512;
}

// Only applicable when cache sequence lengths are available
at::Tensor
get_scheduler_metadata(
        int batch_size,
        int max_query_len,
        int max_key_len,
        int num_heads,
        int num_kv_heads,
        int head_dim,
        int head_dim_v,
        at::ScalarType dtype,
        const at::Tensor &cache_seqlens, // b
        std::optional<const at::Tensor> &query_cu_seqlens_,  // b+1
        std::optional<const at::Tensor> &key_cu_seqlens_,  // b+1
        std::optional<const at::Tensor> &new_key_cu_seqlens_,  // b+1
        std::optional<const at::Tensor> &query_seqlens_, // b. If given, only this many elements of each batch element's queries and outputs are used.
        std::optional<const at::Tensor> &leftpad_k_, // b
        std::optional<int> kv_page_size,
        int max_new_key_len,  // 0 means we're not appending new KV
        bool is_causal,
        int window_left,
        int window_right,
        bool has_softcap,
        int num_splits,
        std::optional<bool> pack_gqa_,
        int const sm_reserved
        ) {
    TORCH_CHECK(dtype == at::ScalarType::Half || dtype == at::ScalarType::BFloat16 || dtype == at::ScalarType::Float8_e4m3fn,
                "FlashAttention only supports fp16, bf16, and fp8_e4m3 data type");
    TORCH_CHECK(num_heads % num_kv_heads == 0, "Number of heads in key/value must divide number of heads in query");

    // Initialize parameters structure
    Flash_fwd_params params{};
    params.is_bf16 = dtype == at::ScalarType::BFloat16;
    params.is_e4m3 = dtype == at::ScalarType::Float8_e4m3fn;
    params.b = batch_size;
    params.seqlen_q = max_query_len;
    params.seqlen_k = max_key_len;
    params.h = num_heads;
    params.h_k = num_kv_heads;
    params.d = head_dim;
    params.dv = head_dim_v;
    params.d_rounded = align_head_dim(head_dim);
    params.dv_rounded = head_dim_v == head_dim ? params.d_rounded : align_head_dim_v(head_dim_v);
    params.seqlen_knew = max_new_key_len;

    // Setup sequence length pointers
    bool const has_varlen_q = query_cu_seqlens_.has_value();
    params.cu_seqlens_q = has_varlen_q ? query_cu_seqlens_.value().data_ptr<int>() : nullptr;
    bool const has_varlen_k = key_cu_seqlens_.has_value();
    params.cu_seqlens_k = has_varlen_k ? key_cu_seqlens_.value().data_ptr<int>() : nullptr;
    params.cu_seqlens_knew = new_key_cu_seqlens_.has_value() ? new_key_cu_seqlens_.value().data_ptr<int>() : nullptr;
    params.seqused_q = query_seqlens_.has_value() ? query_seqlens_.value().data_ptr<int>() : nullptr;
    params.seqused_k = cache_seqlens.data_ptr<int>();
    params.leftpad_k = leftpad_k_.has_value() ? leftpad_k_.value().data_ptr<int>() : nullptr;
    params.knew_ptr = params.seqlen_knew > 0 ? reinterpret_cast<int*>(1) : nullptr;

    // Adjust window sizes for edge cases
    if (window_left >= max_key_len - 1) { window_left = -1; }
    if (window_right >= max_query_len - 1) { window_right = -1; }

    // Special case: single token with full attention
    if (max_query_len == 1 && window_left == -1 && window_right == -1) {
        if ((head_dim <= 64 || head_dim > 128) || !kv_page_size.has_value()) {
            is_causal = false;
        }
    }

    // Set causal flag
    if (is_causal) { window_right = 0; }
    params.is_causal = window_left < 0 && window_right == 0;
    params.is_local = (window_left >= 0 || window_right >= 0) && !params.is_causal;

    // Finalize window sizes
    if (window_left < 0 && window_right >= 0) { window_left = max_key_len - 1; }
    if (window_left >= 0 && window_right < 0) { window_right = max_query_len - 1; }

    params.window_size_left = window_left;
    params.window_size_right = window_right;

    // Get GPU properties
    auto dev_props = at::cuda::getCurrentDeviceProperties();
    params.arch = dev_props->major * 10 + dev_props->minor;
    params.num_sm = dev_props->multiProcessorCount - sm_reserved;
    params.softcap = has_softcap ? 1.0f : 0.0f;
    params.page_size = kv_page_size.has_value() ? kv_page_size.value() : 1;
    params.page_table = !kv_page_size.has_value() ? nullptr : reinterpret_cast<int*>(1);

    // Dynamic split configuration
    bool const use_dynamic_split = params.b <= 992;
    params.num_splits_dynamic_ptr = !use_dynamic_split ? nullptr : reinterpret_cast<int*>(1);
    params.pagedkv_tma = check_pagedkv_tma(params);

    // Determine GQA packing strategy
    params.pack_gqa = pack_gqa_.has_value() ? pack_gqa_.value() : determine_pack_gqa(params);
    params.num_splits = num_splits <= 0 ? calculate_num_splits(params) : num_splits;

    // Force PackGQA for split execution
    params.pack_gqa = params.num_splits > 1;

    // Ensure correct device context
    at::cuda::CUDAGuard device_guard{(char)cache_seqlens.get_device()};
    auto opts = cache_seqlens.options();

    // Allocate semaphore for scheduling
    at::Tensor tile_count_semaphore;
    bool const needs_semaphore = params.arch >= 90 || params.num_splits > 1;
    if (needs_semaphore || use_dynamic_split) {
        tile_count_semaphore = torch::empty({int(needs_semaphore) + int(use_dynamic_split) * params.b}, opts.dtype(torch::kInt32));
        if (needs_semaphore) {
            if (!use_dynamic_split) { tile_count_semaphore.zero_(); }
            params.tile_count_semaphore = tile_count_semaphore.data_ptr<int>();
        } else {
            params.tile_count_semaphore = nullptr;
        }
        params.num_splits_dynamic_ptr = use_dynamic_split ? tile_count_semaphore.data_ptr<int>() + 1 : nullptr;
    }

    if (params.num_splits_dynamic_ptr) {
        auto sm90_config = tile_size_fwd_sm90(params.d_rounded, params.dv_rounded, params.is_causal, params.is_local, 
                                             params.is_e4m3 ? 1 : 2, false, params.page_table && !params.pagedkv_tma, params.softcap > 0.f, use_one_mma_wg(params));
        auto sm8x_config = tile_size_fwd_sm8x(params.arch == 86 || params.arch == 89, params.d_rounded, params.dv_rounded, 
                                             params.is_causal, params.is_local, params.is_e4m3 ? 1 : 2, params.page_table, true, params.softcap > 0.f,

