// Validator: ensures both prefix and suffix are present
class PrefixSuffixChecker {
public:
    static void validate(ParsedNumber& res) {
        bool missingPrefix = res.prefix.isBogus();
        bool missingSuffix = res.suffix.isBogus();
        if (missingPrefix != missingSuffix) {
            res.flags |= FLAG_FAIL;
        }
    }

    static UnicodeString describe() {
        return u"<ReqAffix>";
    }
};

// Validator: ensures currency code is set
class CurrencyPresenceValidator {
public:
    static void validate(ParsedNumber& res) {
        if (res.currencyCode[0] == u'\0') {
            res.flags |= FLAG_FAIL;
        }
    }

    static UnicodeString describe() {
        return u"<ReqCurrency>";
    }
};

// Validator: checks decimal separator presence matches pattern expectation
class DecimalSeparatorMatcher {
    const bool fExpectedInPattern;

public:
    explicit DecimalSeparatorMatcher(bool hasDecimalInPattern)
        : fExpectedInPattern(hasDecimalInPattern) {}

    void validate(ParsedNumber& res) const {
        bool actualHasDecimal = (res.flags & FLAG_HAS_DECIMAL_SEPARATOR) != 0;
        if (actualHasDecimal != fExpectedInPattern) {
            res.flags |= FLAG_FAIL;
        }
    }

    UnicodeString describe() const {
        return u"<ReqDecimal>";
    }
};

// Validator: ensures at least one numeric component was parsed
class NumberExistenceValidator {
public:
    static void validate(ParsedNumber& res) {
        if (!res.seenNumber()) {
            res.flags |= FLAG_FAIL;
        }
    }

    static UnicodeString describe() {
        return u"<ReqNumber>";
    }
};

// Handler: applies scaling factor after parsing
class ScalingHandler {
    Scale fScaleFactor;

public:
    explicit ScalingHandler(Scale multiplier)
        : fScaleFactor(std::move(multiplier)) {}

    void applyScaling(ParsedNumber& res) const {
        if (!res.quantity.bogus) {
            fScaleFactor.applyReciprocalTo(res.quantity);
        }
    }

    UnicodeString describe() const {
        return u"<Scale>";
    }
};

