#include "Intersection/IntersectionQueries3.h"

// Overloaded intersection tests between a halfspace and various geometric primitives
template<typename RealType>
bool UE::Geometry::TestIntersection(const THalfspace3<RealType>& Halfspace, const TSphere3<RealType>& Sphere)
{
	// Compute signed distance from sphere center to halfspace boundary
	RealType DistanceToCenter = Halfspace.Normal.Dot(Sphere.Center) - Halfspace.Constant;
	// Intersection occurs if the distance is within the radius (i.e., not fully outside)
	return (DistanceToCenter + Sphere.Radius >= 0);
}

template<typename RealType>
bool UE::Geometry::TestIntersection(const THalfspace3<RealType>& Halfspace, const TCapsule3<RealType>& Capsule)
{
	// Project both capsule segment endpoints onto the halfspace normal
	RealType DistStart = Halfspace.Normal.Dot(Capsule.Segment.StartPoint()) - Halfspace.Constant;
	RealType DistEnd   = Halfspace.Normal.Dot(Capsule.Segment.EndPoint()) - Halfspace.Constant;

	// The capsule intersects if the farthest endpoint (in direction of normal) plus radius is non-negative
	RealType MaxEndpointDist = (DistStart > DistEnd) ? DistStart : DistEnd;
	return (MaxEndpointDist + Capsule.Radius >= 0);
}

template<typename RealType>
bool UE::Geometry::TestIntersection(const THalfspace3<RealType>& Halfspace, const TOrientedBox3<RealType>& Box)
{
	// Compute signed distance from box center to halfspace boundary
	RealType CenterDist = Halfspace.Normal.Dot(Box.Frame.Origin) - Halfspace.Constant;

	// Get local axes of the oriented box
	FVector3<RealType> LocalX, LocalY, LocalZ;
	Box.Frame.GetAxes(LocalX, LocalY, LocalZ);

	// Compute projected half-extent along the halfspace normal using absolute dot products
	RealType ProjectedRadius =
		TMathUtil<RealType>::Abs(Box.Extents.X * Halfspace.Normal.Dot(LocalX)) +
		TMathUtil<RealType>::Abs(Box.Extents.Y * Halfspace.Normal.Dot(LocalY)) +
		TMathUtil<RealType>::Abs(Box.Extents.Z * Halfspace.Normal.Dot(LocalZ));

	// Intersection test: center distance plus projected radius must be non-negative
	return (CenterDist + ProjectedRadius >= 0);
}

