STHalfEdge::STHalfEdge(SkeletalTrapezoidationEdge data) : HalfEdge(data) {}

bool STHalfEdge::canGoUp(bool strict) const {
    // Direct upward check: strictly increasing distance
    if (to->data.distance_to_boundary > from->data.distance_to_boundary)
        return true;

    // Strict mode or downward edge → no upward path
    if (strict || to->data.distance_to_boundary < from->data.distance_to_boundary)
        return false;

    // Equidistant case: explore neighbors recursively
    auto* curr = next;
    while (curr != twin) {
        if (curr->canGoUp()) return true;
        assert(curr->twin);
        if (!curr->twin) return false;
        assert(curr->twin->next);
        if (!curr->twin->next) return true; // Boundary node — shouldn't happen
        curr = curr->twin->next;
    }
    return false;
}

bool STHalfEdge::isUpward() const {
    if (to->data.distance_to_boundary > from->data.distance_to_boundary)
        return true;
    if (to->data.distance_to_boundary < from->data.distance_to_boundary)
        return false;

    // Equidistant: compare minimal upward distances
    auto fwd_dist = distToGoUp();
    auto bwd_dist = twin->distToGoUp();

    if (fwd_dist && bwd_dist)
        return *fwd_dist < *bwd_dist;
    if (fwd_dist)
        return true;
    if (bwd_dist)
        return false;

    // Tie-breaker: lexicographic point order
    return to->p < from->p;
}

std::optional<coord_t> STHalfEdge::distToGoUp() const {
    if (to->data.distance_to_boundary > from->data.distance_to_boundary)
        return 0;
    if (to->data.distance_to_boundary < from->data.distance_to_boundary)
        return std::nullopt;

    std::optional<coord_t> min_up_dist;
    auto* curr = next;
    while (curr != twin) {
        auto sub_dist = curr->distToGoUp();
        if (sub_dist) {
            min_up_dist = min_up_dist ? std::min(*min_up_dist, *sub_dist) : sub_dist;
        }
        assert(curr->twin);
        if (!curr->twin) return std::nullopt;
        assert(curr->twin->next);
        if (!curr->twin->next) return 0; // Boundary node — shouldn't occur
        curr = curr->twin->next;
    }

    if (min_up_dist) {
        *min_up_dist += (to->p - from->p).cast<int64_t>().norm();
    }
    return min_up_dist;
}

STHalfEdge* STHalfEdge::getNextUnconnected() {
    auto* result = static_cast<STHalfEdge*>(this);
    do {
        if (!result->next) break;
        result = result->next;
        if (result == this) return nullptr;
    } while (true);
    return result->twin;
}

STHalfEdgeNode::STHalfEdgeNode(SkeletalTrapezoidationJoint data, Point p) : HalfEdgeNode(data, p) {}

bool STHalfEdgeNode::isMultiIntersection() {
    int central_count = 0;
    auto* curr = incident_edge;
    do {
        if (!curr) return false;
        if (curr->data.isCentral()) ++central_count;
        curr = curr->twin->next;
    } while (curr != incident_edge);
    return central_count > 2;
}

bool STHalfEdgeNode::isCentral() const {
    auto* curr = incident_edge;
    do {
        if (curr && curr->data.isCentral())
            return true;
        assert(curr && curr->twin);
        if (!curr || !curr->twin) return false;
        curr = curr->twin->next;
    } while (curr != incident_edge);
    return false;
}

bool STHalfEdgeNode::isLocalMaximum(bool strict) const {
    if (data.distance_to_boundary == 0)
        return false;

    auto* curr = incident_edge;
    do {
        if (!curr || !curr->twin || !curr->twin->next)
            return false;
        if (curr->canGoUp(strict))
            return false;
        curr = curr->twin->next;
    } while (curr != incident_edge);
    return true;
}

void SkeletalTrapezoidationGraph::collapseSmallEdges(coord_t snap_dist) {
    ankerl::unordered_dense::map<edge_t*, Edges::iterator> edge_map;
    ankerl::unordered_dense::map<node_t*, Nodes::iterator> node_map;

    for (auto it = edges.begin(); it != edges.end(); ++it)
        edge_map.emplace(&*it, it);
    for (auto it = nodes.begin(); it != nodes.end(); ++it)
        node_map.emplace(&*it, it);

    auto remove_edge_safely =
        [this, &edge_map](edge_t* e, Edges::iterator& cur_it, bool& updated) {
            if (cur_it != edges.end() && &*cur_it == e) {
                cur_it = edges.erase(cur_it);
                updated = true;
            } else {
                edges.erase(edge_map[e]);
            }
        };

    auto should_collapse = [snap_dist](node_t* a, node_t* b) {
        return shorter_then(a->p - b->p, snap_dist);
    };

    for (auto edge_it = edges.begin(); edge_it != edges.end();) {
        if (edge_it->prev) {
            ++edge_it;
            continue;
        }

        auto* quad_start = &*edge_it;
        auto* quad_end = quad_start;
        while (quad_end->next) quad_end = quad_end->next;
        auto* quad_mid = (quad_start->next == quad_end) ? nullptr : quad_start->next;

        bool updated = false;

        if (quad_mid && should_collapse(quad_mid->from, quad_mid->to)) {
            assert(quad_mid->twin);
            if (!quad_mid->twin) {
                BOOST_LOG_TRIVIAL(warning) << "Quad edge missing twin.";
                ++edge_it;
                continue;
            }

            int iter_limit = 0;
            for (auto* e = quad_end; e && e != quad_mid->twin; e = e->twin->next) {
                e->from = quad_mid->from;
                e->twin->to = quad_mid->from;
                if (++iter_limit > 1000) break;
            }

            if (quad_mid->from->incident_edge == quad_mid) {
                quad_mid->from->incident_edge = quad_mid->twin->next ?: quad_mid->prev->twin;
            }

            nodes.erase(node_map[quad_mid->to]);
            quad_mid->prev->next = quad_mid->next;
            quad_mid->next->prev = quad_mid->prev;
            quad_mid->twin->next->prev = quad_mid->twin->prev;
            quad_mid->twin->prev->next = quad_mid->twin->next;

            remove_edge_safely(quad_mid->twin, edge_it, updated);
            remove_edge_safely(quad_mid, edge_it, updated);
        }

        if (!updated && should_collapse(quad_start->from, quad_end->to) &&
                         should_collapse(quad_start->to, quad_end->from)) {
            quad_start->twin->to = quad_end->to;
            quad_end->to->incident_edge = quad_end->twin;

            if (quad_end->from->incident_edge == quad_end) {
                quad_end->from->incident_edge = quad_end->twin->next ?: quad_end->prev->twin;
            }

            nodes.erase(node_map[quad_start->from]);
            quad_start->twin->twin = quad_end->twin;
            quad_end->twin->twin = quad_start->twin;

            remove_edge_safely(quad_start, edge_it, updated);
            remove_edge_safely(quad_end, edge_it, updated);
        }

        if (!updated) ++edge_it;
    }
}

void SkeletalTrapezoidationGraph::makeRib(edge_t*& prev_edge,
                                          const Point& src_start,
                                          const Point& src_end) {
    Point proj;
    Line(src_start, src_end).distance_to_infinite_squared(prev_edge->to->p, &proj);
    coord_t dist = (prev_edge->to->p - proj).cast<int64_t>().norm();
    prev_edge->to->data.distance_to_boundary = dist;
    assert(dist >= 0);

    nodes.emplace_front(SkeletalTrapezoidationJoint(), proj);
    node_t* new_node = &nodes.front();
    new_node->data.distance_to_boundary = 0;

    edges.emplace_front(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::EXTRA_VD));
    edge_t* forward = &edges.front();

    edges.emplace_front(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::EXTRA_VD));
    edge_t* backward = &edges.front();

    prev_edge->next = forward;
    forward->prev = prev_edge;
    forward->from = prev_edge->to;
    forward->to = new_node;
    forward->twin = backward;
    backward->twin = forward;
    backward->from = new_node;
    backward->to = prev_edge->to;
    new_node->incident_edge = backward;

    prev_edge = backward;
}

std::pair<SkeletalTrapezoidationGraph::edge_t*, SkeletalTrapezoidationGraph::edge_t*>
SkeletalTrapezoidationGraph::insertRib(edge_t& base_edge, node_t* mid_node) {
    edge_t* before = base_edge.prev;
    edge_t* after = base_edge.next;
    node_t* left_node = base_edge.from;
    node_t* right_node = base_edge.to;

    Point mid_point = mid_node->p;
    Line source_line = getSource(base_edge);
    Point px;
    source_line.distance_to_squared(mid_point, &px);
    coord_t dist = (mid_point - px).cast<int64_t>().norm();
    assert(dist > 0);

    mid_node->data.distance_to_boundary = dist;
    mid_node->data.transition_ratio = 0;

    nodes.emplace_back(SkeletalTrapezoidationJoint(), px);
    node_t* src_node = &nodes.back();
    src_node->data.distance_to_boundary = 0;

    edge_t* first = &base_edge;
    edges.emplace_back(SkeletalTrapezoidationEdge());
    edge_t* second = &edges.back();
    edges.emplace_back(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::TRANSITION_END));
    edge_t* outward = &edges.back();
    edges.emplace_back(SkeletalTrapezoidationEdge(SkeletalTrapezoidationEdge::TRANSITION_END));
    edge_t* inward = &edges.back();

    // Link structure
    if (before) before->next = first;
    first->next = outward;
    outward->next = nullptr;
    inward->next = second;
    second->next = after;

    if (after) after->prev = second;
    second->prev = inward;
    outward->prev = first;
    first->prev = before;

    // Assign endpoints
    first->to = mid_node;
    outward->to = src_node;
    inward->to = mid_node;
    second->to = right_node;

    first->from = left_node;
    outward->from = mid_node;
    inward->from = src_node;
    second->from = mid_node;

    left_node->incident_edge = first;
    mid_node->incident_edge = outward;
    src_node->incident_edge = inward;
    if (after) right_node->incident_edge = after;

    first->data.setIsCentral(true);
    outward->data.setIsCentral(false);
    inward->data.setIsCentral(false);
    second->data.setIsCentral(true);

    outward->twin = inward;
    inward->twin = outward;
    first->twin = second->twin = nullptr;

    assert(second->prev->from->data.distance_to_boundary == 0);
    return {first, second};
}

SkeletalTrapezoidationGraph::edge_t*
SkeletalTrapezoidationGraph::insertNode(edge_t* input_edge, Point mid, coord_t bead_count) {
    edge_t* last_replaced = input_edge;
    nodes.emplace_back(SkeletalTrapezoidationJoint(), mid);
    node_t* mid_node = &nodes.back();

    edge_t* twin = last_replaced->twin;
    last_replaced->twin = twin->twin = nullptr;

    auto [left_first, left_last] = insertRib(*last_replaced, mid_node);
    auto [right_first, right_last] = insertRib(*twin, mid_node);

    left_first->twin = right_last;
    right_last->twin = left_first;
    left_last->twin = right_first;
    right_first->twin = left_last;

    mid_node->data.bead_count = bead_count;
    return left_last;
}

Line SkeletalTrapezoidationGraph::getSource(const edge_t& edge) const {
    const edge_t* start = &edge;
    while (start->prev) start = start->prev;

    const edge_t* end = &edge;
    while (end->next) end = end->next;

    return Line(start->from->p, end->to->p);
}

