void define_pointcloud(py::module& m) {
  // PointCloud binding with equivalent functionality but different implementation style
  py::class_<PointCloud, std::shared_ptr<PointCloud>>(m, "PointCloud")
    .def(
      py::init([](const Eigen::MatrixXd& input_points) {
        if (input_points.cols() != 3 && input_points.cols() != 4) {
          std::cerr << "Input matrix must have 3 or 4 columns" << std::endl;
          return std::make_shared<PointCloud>();
        }

        auto cloud = std::make_shared<PointCloud>();
        size_t n_rows = input_points.rows();
        cloud->resize(n_rows);

        if (input_points.cols() == 3) {
          for (size_t idx = 0; idx < n_rows; ++idx) {
            const auto row_data = input_points.row(idx);
            cloud->point(idx) << row_data.transpose(), 1.0;
          }
        } else {
          for (size_t idx = 0; idx < n_rows; ++idx) {
            const auto row_data = input_points.row(idx);
            cloud->point(idx) << row_data.transpose();
          }
        }

        return cloud;
      }),
      py::arg("points"),
      R"""(
      PointCloud(points: numpy.ndarray)
      Construct a PointCloud from a numpy array.
      Parameters
      ----------
      points : numpy.ndarray, shape (n, 3) or (n, 4)
          The input point cloud.
      )""")
    .def("__repr__", [](const PointCloud& cloud) {
      return "small_gicp.PointCloud (" + std::to_string(cloud.size()) + " points)";
    })
    .def("__len__", [](const PointCloud& cloud) { return cloud.size(); })
    .def(
      "empty",
      &PointCloud::empty,
      R"pbdoc(
        Check if the point cloud is empty
        Returns
        -------
        empty : bool
            True if the point cloud is empty.
        )pbdoc")
    .def(
      "size",
      &PointCloud::size,
      R"pbdoc(
        Get the number of points.
        Returns
        -------
        num_points : int
            Number of points.
        )pbdoc")
    .def(
      "points",
      [](const PointCloud& cloud) -> Eigen::MatrixXd {
        return Eigen::Map<const Eigen::Matrix<double, -1, -1, Eigen::RowMajor>>(
          cloud.points[0].data(), cloud.size(), 4);
      },
      R"pbdoc(
        Get the points as a Nx4 matrix.
        Returns
        -------
        points : numpy.ndarray
            Points.
        )pbdoc")
    .def(
      "normals",
      [](const PointCloud& cloud) -> Eigen::MatrixXd {
        return Eigen::Map<const Eigen::Matrix<double, -1, -1, Eigen::RowMajor>>(
          cloud.normals[0].data(), cloud.size(), 4);
      },
      R"pbdoc(
        Get the normals as a Nx4 matrix.
        Returns
        -------
        normals : numpy.ndarray
            Normals.
        )pbdoc")
    .def(
      "covs",
      [](const PointCloud& cloud) { return cloud.covs; },
      R"pbdoc(
        Get the covariance matrices as a list of 4x4 matrices.
        Returns
        -------
        covs : list of numpy.ndarray
            Covariance matrices.
        )pbdoc")
    .def(
      "point",
      [](const PointCloud& cloud, size_t index) -> Eigen::Vector4d {
        return cloud.point(index);
      },
      py::arg("i"),
      R"pbdoc(
        Get the i-th point.
        Parameters
        ----------
        i : int
            Index of the point.
        Returns
        -------
        point : numpy.ndarray, shape (4,)
            Point.
        )pbdoc")
    .def(
      "normal",
      [](const PointCloud& cloud, size_t index) -> Eigen::Vector4d {
        return cloud.normal(index);
      },
      py::arg("i"),
      R"pbdoc(
        Get the i-th normal.
        Parameters
        ----------
        i : int
            Index of the point.
        Returns
        -------
        normal : numpy.ndarray, shape (4,)
            Normal.
        )pbdoc")
    .def(
      "cov",
      [](const PointCloud& cloud, size_t index) -> Eigen::Matrix4d {
        return cloud.cov(index);
      },
      py::arg("i"),
      R"pbdoc(
        Get the i-th covariance matrix.
        Parameters
        ----------
        i : int
            Index of the point.
        Returns
        -------
        cov : numpy.ndarray, shape (4, 4)
            Covariance matrix.
        )pbdoc");
}

#include <uibase/linklabel.h>
#include <QApplication>

// Static member initialization for link color
QColor LinkLabel::m_linkColor;

// Constructor: initializes the label with optional parent widget
LinkLabel::LinkLabel(QWidget* parent) : QLabel(parent) {}

// Getter for the current link color
QColor LinkLabel::linkColor() const
{
  return m_linkColor;
}

// Setter for the link color, updates global palette if changed
void LinkLabel::setLinkColor(const QColor& newColor)
{
  if (m_linkColor != newColor) {
    m_linkColor = newColor;

    // Apply the new color globally via application palette since Qt lacks per-widget link color support
    if (QApplication::instance()) {
      auto palette = QApplication::instance()->palette();
      palette.setColor(QPalette::Link, newColor);
      palette.setColor(QPalette::LinkVisited, newColor);
      QApplication::instance()->setPalette(palette);
    }
  }
}

