    void add_versioninfo_classes(py::module_ m)
    {
        // Version class binding
        py::class_<Version> verBinder(m, "Version");

        // ReleaseType enum
        py::enum_<Version::ReleaseType> releaseEnum(verBinder, "ReleaseType");
        releaseEnum.value("DEV", Version::Development);
        releaseEnum.value("ALPHA", Version::Alpha);
        releaseEnum.value("BETA", Version::Beta);
        releaseEnum.value("RC", Version::ReleaseCandidate);
        releaseEnum.export_values();

        // ParseMode enum
        py::enum_<Version::ParseMode> parseEnum(verBinder, "ParseMode");
        parseEnum.value("STRICT", Version::ParseMode::SemVer);
        parseEnum.value("MO2_MODE", Version::ParseMode::MO2);

        // FormatMode enum with arithmetic support
        py::enum_<Version::FormatMode> fmtEnum(verBinder, "FormatMode", py::arithmetic{});
        fmtEnum.value("FULL_PATCH", Version::FormatMode::ForceSubPatch);
        fmtEnum.value("NO_SEP", Version::FormatMode::NoSeparator);
        fmtEnum.value("SHORT_ALPHA", Version::FormatMode::ShortAlphaBeta);
        fmtEnum.value("NO_META", Version::FormatMode::NoMetadata);
        fmtEnum.value("COMPACT",
                      static_cast<Version::FormatMode>(Version::FormatCondensed.toInt()));
        fmtEnum.export_values()
            .def("__xor__", [](Version::FormatMode lhs, Version::FormatModes rhs) { return lhs ^ rhs; })
            .def("__and__", [](Version::FormatMode lhs, Version::FormatModes rhs) { return lhs & rhs; })
            .def("__or__",  [](Version::FormatMode lhs, Version::FormatModes rhs) { return lhs | rhs; })
            .def("__rxor__", [](Version::FormatMode lhs, Version::FormatModes rhs) { return rhs ^ lhs; })
            .def("__rand__", [](Version::FormatMode lhs, Version::FormatModes rhs) { return rhs & lhs; })
            .def("__ror__",  [](Version::FormatMode lhs, Version::FormatModes rhs) { return rhs | lhs; });

        // Version constructors and methods
        verBinder
            .def_static("from_string", &Version::parse, "input"_a, "mode"_a = Version::ParseMode::SemVer)
            .def(py::init<int, int, int, QString>(), "major"_a, "minor"_a, "patch"_a, "meta"_a = "")
            .def(py::init<int, int, int, int, QString>(), "major"_a, "minor"_a, "patch"_a, "sub"_a, "meta"_a = "")
            .def(py::init<int, int, int, Version::ReleaseType, QString>(), "major"_a, "minor"_a, "patch"_a, "type"_a, "meta"_a = "")
            .def(py::init<int, int, int, int, Version::ReleaseType, QString>(), "major"_a, "minor"_a, "patch"_a, "sub"_a, "type"_a, "meta"_a = "")
            .def(py::init<int, int, int, Version::ReleaseType, int, QString>(), "major"_a, "minor"_a, "patch"_a, "type"_a, "pre_rel"_a, "meta"_a = "")
            .def(py::init<int, int, int, int, std::vector<std::variant<int, Version::ReleaseType>>, QString>(),
                 "major"_a, "minor"_a, "patch"_a, "sub"_a, "pre_releases"_a, "meta"_a = "")
            .def("is_release_candidate", &Version::isPreRelease)
            .def_property_readonly("major_num", &Version::major)
            .def_property_readonly("minor_num", &Version::minor)
            .def_property_readonly("patch_num", &Version::patch)
            .def_property_readonly("subpatch_num", &Version::subpatch)
            .def_property_readonly("prerelease_list", &Version::preReleases)
            .def_property_readonly("build_meta", &Version::buildMetadata)
            .def("to_string", &Version::string, "fmt"_a = Version::FormatModes{})
            .def("__repr__",
                 [](Version const& v) { return v.string(Version::FormatCondensed); })
            .def(py::self < py::self)
            .def(py::self > py::self)
            .def(py::self <= py::self)
            .def(py::self >= py::self)
            .def(py::self != py::self)
            .def(py::self == py::self);

        // VersionInfo class binding
        py::enum_<MOBase::VersionInfo::ReleaseType> viRelease(m, "ReleaseType");
        viRelease.value("FINAL", MOBase::VersionInfo::RELEASE_FINAL);
        viRelease.value("CANDIDATE", MOBase::VersionInfo::RELEASE_CANDIDATE);
        viRelease.value("BETA", MOBase::VersionInfo::RELEASE_BETA);
        viRelease.value("ALPHA", MOBase::VersionInfo::RELEASE_ALPHA);
        viRelease.value("PRE_ALPHA", MOBase::VersionInfo::RELEASE_PREALPHA);

        py::enum_<MOBase::VersionInfo::VersionScheme> viScheme(m, "VersionScheme");
        viScheme.value("AUTO", MOBase::VersionInfo::SCHEME_DISCOVER);
        viScheme.value("REGULAR", MOBase::VersionInfo::SCHEME_REGULAR);
        viScheme.value("DOT", MOBase::VersionInfo::SCHEME_DECIMALMARK);
        viScheme.value("ALPHANUM", MOBase::VersionInfo::SCHEME_NUMBERSANDLETTERS);
        viScheme.value("DATE", MOBase::VersionInfo::SCHEME_DATE);
        viScheme.value("LITERAL", MOBase::VersionInfo::SCHEME_LITERAL);

        py::class_<VersionInfo> viBinder(m, "VersionInfo");
        viBinder
            .def(py::init<>())
            .def(py::init<QString, VersionInfo::VersionScheme>(), "val"_a, "scheme"_a = VersionInfo::SCHEME_DISCOVER)
            .def(py::init<int, int, int, int, VersionInfo::ReleaseType>(), "major"_a, "minor"_a, "sub"_a, "subsub"_a, "rel"_a = VersionInfo::RELEASE_FINAL)
            .def(py::init<int, int, int, VersionInfo::ReleaseType>(), "major"_a, "minor"_a, "sub"_a, "rel"_a = VersionInfo::RELEASE_FINAL)
            .def("reset", &VersionInfo::clear)
            .def("analyze", &VersionInfo::parse, "val"_a, "scheme"_a = VersionInfo::SCHEME_DISCOVER, "manual"_a = false)
            .def("normalized", &VersionInfo::canonicalString)
            .def("pretty", &VersionInfo::displayString, "segments"_a = 2)
            .def("is_valid", &VersionInfo::isValid)
            .def("get_scheme", &VersionInfo::scheme)
            .def("__str__", &VersionInfo::canonicalString)
            .def(py::self < py::self)
            .def(py::self > py::self)
            .def(py::self <= py::self)
            .def(py::self >= py::self)
            .def(py::self != py::self)
            .def(py::self == py::self);
    }

