// Vertex shader: transforms positions and passes texture coordinates
static const char* vs_src = R"(
#version 330 core
layout (location = 0) in vec2 pos;
layout (location = 1) in vec2 uv;
out vec2 vUV;
uniform mat4 projMat;
void main()
{
    gl_Position = projMat * vec4(pos, 0.0, 1.0);
    vUV = uv;
}
)";

// Fragment shader: handles text, rectangles, shadows, rounded corners
static const char* fs_src = R"(
#version 330 core
in vec2 vUV;
out vec4 outColor;
uniform sampler2D texSampler;
uniform vec4 textCol;
uniform vec4 rectCol;
uniform int drawMode;
uniform vec4 boxDef; // center.xy, size.zw
uniform float blurDist; // shadow softness
uniform vec4 radii; // TL, TR, BR, BL

// Signed distance to axis-aligned box
float sdistBox(vec2 p, vec2 halfSize) {
    vec2 diff = abs(p) - halfSize;
    return length(max(diff, 0.0)) + min(max(diff.x, diff.y), 0.0);
}

// Rounded box SDF with uniform corner radius
float sdistRoundBox(vec2 p, vec2 halfSize, float r) {
    vec2 shifted = abs(p) - halfSize + r;
    return min(max(shifted.x, shifted.y), 0.0) + length(max(shifted, 0.0)) - r;
}

// Per-corner rounded box SDF
float sdistRoundedPerCorner(vec2 p, vec2 halfSize, vec4 rads) {
    float rad;
    if (p.x < 0.0 && p.y < 0.0)      rad = rads.x; // top-left
    else if (p.x >= 0.0 && p.y < 0.0) rad = rads.y; // top-right
    else if (p.x >= 0.0 && p.y >= 0.0) rad = rads.z; // bottom-right
    else                               rad = rads.w; // bottom-left

    vec2 adjusted = abs(p) - halfSize + rad;
    return min(max(adjusted.x, adjusted.y), 0.0) + length(max(adjusted, 0.0)) - rad;
}

void main() {
    if (drawMode == 0) { // Text mode
        float alpha = texture(texSampler, vUV).r;
        outColor = vec4(textCol.rgb * alpha, textCol.a * alpha);
    }
    else if (drawMode == 1) { // ColoredText
        outColor = texture(texSampler, vUV);
    }
    else if (drawMode == 2) { // Solid rectangle
        outColor = rectCol;
    }
    else if (drawMode == 3) { // Shadow on rectangular area
        vec2 center = boxDef.xy;
        vec2 size   = boxDef.zw;
        vec2 localCoord = gl_FragCoord.xy - center;
        float d = sdistBox(localCoord, size * 0.5);
        float fade = 1.0 - smoothstep(0.0, blurDist, d);
        outColor = vec4(0.0, 0.0, 0.0, 0.25 * fade);
    }
    else if (drawMode == 4) { // Rounded rectangle fill
        vec2 center = boxDef.xy;
        vec2 size   = boxDef.zw;
        vec2 localCoord = gl_FragCoord.xy - center;
        float d = sdistRoundedPerCorner(localCoord, size * 0.5, radii);
        float alpha = 1.0 - smoothstep(-1.0, 1.0, d);
        outColor = vec4(rectCol.rgb, rectCol.a * alpha);
    }
    else if (drawMode == 5) { // Rounded shadow
        vec2 center = boxDef.xy;
        vec2 size   = boxDef.zw;
        vec2 localCoord = gl_FragCoord.xy - center;
        float d = sdistRoundedPerCorner(localCoord, size * 0.5, radii);
        float fade = 1.0 - smoothstep(0.0, blurDist, d);
        outColor = vec4(0.0, 0.0, 0.0, 0.25 * fade);
    }
}
)";

namespace opengl {

ShaderProgram::ShaderProgram() : m_program_id(0) {}

void ShaderProgram::compile() {
    // Compile vertex shader
    GLuint vs = glCreateShader(GL_VERTEX_SHADER);
    glShaderSource(vs, 1, &vs_src, nullptr);
    glCompileShader(vs);
    GLint compile_ok = GL_FALSE;
    glGetShaderiv(vs, GL_COMPILE_STATUS, &compile_ok);
    if (compile_ok != GL_TRUE) {
        GLsizei log_len = 0;
        char log[512];
        glGetShaderInfoLog(vs, sizeof(log), &log_len, log);
        throw std::runtime_error("Vertex shader compilation failed: " + std::string(log, log_len));
    }

    // Compile fragment shader
    GLuint fs = glCreateShader(GL_FRAGMENT_SHADER);
    glShaderSource(fs, 1, &fs_src, nullptr);
    glCompileShader(fs);
    glGetShaderiv(fs, GL_COMPILE_STATUS, &compile_ok);
    if (compile_ok != GL_TRUE) {
        GLsizei log_len = 0;
        char log[512];
        glGetShaderInfoLog(fs, sizeof(log), &log_len, log);
        throw std::runtime_error("Fragment shader compilation failed: " + std::string(log, log_len));
    }

    // Link program
    m_program_id = glCreateProgram();
    glAttachShader(m_program_id, vs);
    glAttachShader(m_program_id, fs);
    glLinkProgram(m_program_id);

    GLint link_ok = GL_FALSE;
    glGetProgramiv(m_program_id, GL_LINK_STATUS, &link_ok);
    if (link_ok != GL_TRUE) {
        GLsizei log_len = 0;
        char log[512];
        glGetProgramInfoLog(m_program_id, sizeof(log), &log_len, log);
        throw std::runtime_error("Shader program linking failed: " + std::string(log, log_len));
    }

    // Cleanup shaders
    glDeleteShader(vs);
    glDeleteShader(fs);

    // Enable blending for transparency support
    glEnable(GL_BLEND);
    glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
}

void ShaderProgram::use() {
    glUseProgram(m_program_id);
}

void ShaderProgram::setRenderType(RenderType type) {
    setInt("drawMode", static_cast<int>(type));

    switch (type) {
        case RenderType::ColoredText:
            glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
            break;
        default:
            glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
    }
}

void ShaderProgram::setFloat(const std::string& name, float val) {
    glUniform1f(glGetUniformLocation(m_program_id, name.c_str()), val);
}

void ShaderProgram::setInt(const std::string& name, int val) {
    glUniform1i(glGetUniformLocation(m_program_id, name.c_str()), val);
}

void ShaderProgram::setVector4f(const std::string& name, float x, float y, float z, float w) {
    glUniform4f(glGetUniformLocation(m_program_id, name.c_str()), x, y, z, w);
}

void ShaderProgram::setMatrix4(const std::string& name, const glm::mat4& mat) {
    // Note: Despite parameter 'name', always use "projMat" as per original semantics
    glUniformMatrix4fv(glGetUniformLocation(m_program_id, "projMat"), 1, GL_FALSE, glm::value_ptr(mat));
}

