// Helper lambda to send/receive data safely with error handling
template<typename T>
bool safeSend(WindowsSocketClient* client, const T& data) {
    return client->Send(&data, sizeof(T));
}

template<typename T>
bool safeReceive(WindowsSocketClient* client, T& out) {
    return client->Receive(&out, sizeof(T));
}

// Read memory into a byte vector (vector-based output)
bool ReadProcessMemoryBytes(uint64_t memAddr, uint32_t byteCount,
                            std::vector<unsigned char>& buffer, PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int procHandle) -> bool {
        struct __attribute__((packed)) {
            unsigned char cmd;
            CeReadProcessMemoryInput req;
        } request;

        request.cmd = CMD_READPROCESSMEMORY;
        request.req.handle = procHandle;
        request.req.address = memAddr;
        request.req.size = byteCount;
        request.req.compress = 0;

        if (!safeSend(client, request))
            return false;

        CeReadProcessMemoryOutput response{};
        if (!safeReceive(client, response))
            return false;

        buffer.resize(byteCount);
        if (!client->Receive(buffer.data(), buffer.size()))
            return false;

        if (response.read <= 0) {
            buffer.clear();
            return false;
        }

        return true;
    });
}

// Write memory from a byte vector
bool WriteProcessMemoryBytes(uint64_t memAddr, uint32_t byteCount,
                             std::vector<unsigned char>& payload, PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int procHandle) -> bool {
        struct __attribute__((packed)) {
            unsigned char cmd;
            CeWriteProcessMemoryInput req;
        } request;

        request.cmd = CMD_WRITEPROCESSMEMORY;
        request.req.handle = procHandle;
        request.req.address = memAddr;
        request.req.size = byteCount;

        if (!safeSend(client, request))
            return false;

        if (!client->Send(payload.data(), payload.size()))
            return false;

        CeWriteProcessMemoryOutput result;
        if (!safeReceive(client, result))
            return false;

        return static_cast<uint32_t>(result.written) == byteCount;
    });
}

// Read memory directly into a user-provided buffer with actual bytes read reported
bool ReadProcessMemory_(uint64_t memAddr, uint32_t byteCount, void* destBuffer,
                        int32_t& bytesRead, PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int procHandle) -> bool {
        struct __attribute__((packed)) {
            unsigned char cmd;
            CeReadProcessMemoryInput req;
        } request;

        request.cmd = CMD_READPROCESSMEMORY;
        request.req.handle = procHandle;
        request.req.address = memAddr;
        request.req.size = byteCount;
        request.req.compress = 0;

        if (!safeSend(client, request))
            return false;

        if (!safeReceive(client, bytesRead))
            return false;

        if (bytesRead <= 0)
            return false;

        if (!client->Receive(destBuffer, byteCount))
            return false;

        return true;
    });
}

// Batch-read multiple memory regions (fixed-size chunks)
bool ReadBratchMemory(uint64_t baseAddr, uint32_t regionSize,
                      std::vector<std::pair<uint64_t, std::vector<uint8_t>>>& results,
                      PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int procHandle) -> bool {
        struct __attribute__((packed)) {
            unsigned char cmd;
            int handle;
            uint64_t addr;
            uint32_t size;
        } request;

        request.cmd = CMD_READBRATCHMEMORY;
        request.handle = procHandle;
        request.addr = baseAddr;
        request.size = regionSize;

        if (!safeSend(client, request))
            return false;

        int chunkCount = 0;
        if (!safeReceive(client, chunkCount))
            return false;

        if (chunkCount <= 0) {
            results.clear();
            return true;
        }

        results.clear();
        results.reserve(chunkCount);

        for (int i = 0; i < chunkCount; ++i) {
            uint64_t currentAddr = 0;
            std::vector<uint8_t> chunkData(4096);

            if (!client->Receive(&currentAddr, sizeof(currentAddr)))
                return false;
            if (!client->Receive(chunkData.data(), 4096))
                return false;

            results.emplace_back(currentAddr, std::move(chunkData));
        }

        return true;
    });
}

// Batch-read specific addresses with variable sizes
bool ReadBratchAddr(std::vector<std::pair<uint64_t, int32_t>>& addressList,
                    std::vector<std::pair<uint64_t, std::vector<uint8_t>>>& output,
                    PortType port) {
    return SocketCommand::execute(port, [&](WindowsSocketClient* client, int procHandle) -> bool {
        const unsigned char cmd = CMD_READBRATCHADDR;
        if (!SocketCommand::sendCommandWithHandle(client, cmd, procHandle))
            return false;

        int count = static_cast<int>(addressList.size());
        if (!safeSend(client, count))
            return false;

        std::vector<CeReadBratchAddr> requests(count);
        for (int i = 0; i < count; ++i) {
            requests[i].addr = addressList[i].first;
            requests[i].size = addressList[i].second;
        }

        if (!client->Send(requests.data(), count * sizeof(CeReadBratchAddr)))
            return false;

        output.clear();
        output.resize(count);

        int successFlag = 0;
        if (!safeReceive(client, successFlag))
            return false;

        for (int i = 0; i < count; ++i) {
            uint64_t addr = 0;
            int32_t len = requests[i].size;
            std::vector<uint8_t> data(len);

            if (!client->Receive(&addr, sizeof(addr)))
                return false;
            if (!client->Receive(data.data(), len))
                return false;

            output[i] = {addr, std::move(data)};
        }

        return true;
    });
}

#include "quadrants/rhi/amdgpu/amdgpu_device.h"
#include "quadrants/rhi/llvm/device_memory_pool.h"
#include "quadrants/jit/jit_module.h"

namespace quadrants {
namespace lang {
namespace amdgpu {

AmdgpuDevice::AmdgpuDevice() {
  // Set up memory management for AMDGPU
  DeviceMemoryPool::get_instance(Arch::amdgpu, false /*do not merge blocks on release*/);
}

AmdgpuDevice::AllocInfo AmdgpuDevice::get_alloc_info(const DeviceAllocation handle) {
  ensure_valid_allocation(handle);
  return allocations_[handle.alloc_id];
}

RhiResult AmdgpuDevice::allocate_memory(const AllocParams &params,
                                        DeviceAllocation *out_devalloc) {
  AllocInfo alloc_data;
  auto &mem_pool = DeviceMemoryPool::get_instance(Arch::amdgpu, false /*no merging upon release*/);

  const bool needs_managed_mem = params.host_read || params.host_write;
  void *raw_ptr = mem_pool.allocate(params.size, DeviceMemoryPool::page_size, needs_managed_mem);

  if (!raw_ptr) {
    return RhiResult::out_of_memory;
  }

  alloc_data.ptr = raw_ptr;
  alloc_data.size = params.size;
  alloc_data.is_imported = false;
  alloc_data.use_cached = false;
  alloc_data.use_preallocated = false;

  // Zero-initialize the newly allocated memory
  AMDGPUDriver::get_instance().memset(raw_ptr, 0, alloc_data.size);

  *out_devalloc = DeviceAllocation{};
  out_devalloc->alloc_id = static_cast<int>(allocations_.size());
  out_devalloc->device = this;
  allocations_.emplace_back(alloc_data);

  return RhiResult::success;
}

DeviceAllocation AmdgpuDevice::allocate_memory_runtime(const LlvmRuntimeAllocParams &params) {
  AllocInfo alloc_data;
  alloc_data.size = quadrants::iroundup(params.size, quadrants_page_size);

  if (params.host_read || params.host_write) {
    QD_NOT_IMPLEMENTED
  } else {
    alloc_data.ptr = DeviceMemoryPool::get_instance(Arch::amdgpu, false /*no merging upon release*/)
                         .allocate_with_cache(this, params);
    QD_ASSERT(alloc_data.ptr != nullptr);
    AMDGPUDriver::get_instance().memset(alloc_data.ptr, 0, alloc_data.size);
  }

  alloc_data.is_imported = false;
  alloc_data.use_cached = true;
  alloc_data.use_preallocated = true;

  DeviceAllocation new_alloc;
  new_alloc.alloc_id = static_cast<int>(allocations_.size());
  new_alloc.device = this;
  allocations_.push_back(alloc_data);

  return new_alloc;
}

uint64_t *AmdgpuDevice::allocate_llvm_runtime_memory_jit(const LlvmRuntimeAllocParams &params) {
  params.runtime_jit->call<void *, std::size_t, std::size_t>(
      "runtime_memory_allocate_aligned", params.runtime, params.size, quadrants_page_size, params.result_buffer);

  AMDGPUDriver::get_instance().stream_synchronize(nullptr);

  uint64_t *result_host = nullptr;
  AMDGPUDriver::get_instance().memcpy_device_to_host(&result_host, params.result_buffer, sizeof(uint64_t));
  return result_host;
}

void AmdgpuDevice::dealloc_memory(DeviceAllocation handle) {
  // Skip deallocation if no allocations exist
  if (allocations_.empty()) {
    return;
  }

  ensure_valid_allocation(handle);
  AllocInfo &info = allocations_[handle.alloc_id];

  if (!info.ptr) {
    QD_ERROR("attempting to free an already-deallocated device memory block");
  }

  QD_ASSERT(!info.is_imported);

  if (info.use_cached) {
    DeviceMemoryPool::get_instance(Arch::amdgpu, false /*no merging upon release*/)
        .release(info.size, reinterpret_cast<uint64_t*>(info.ptr), false);
  } else if (!info.use_preallocated) {
    DeviceMemoryPool::get_instance(Arch::amdgpu, false /*no merging upon release*/)
        .release(info.size, info.ptr);
  }

  info.ptr = nullptr;
}

RhiResult AmdgpuDevice::map(DeviceAllocation alloc, void **mapped_ptr) {
  AllocInfo &info = allocations_[alloc.alloc_id];
  size_t total_bytes = info.size;

  info.mapped = new char[total_bytes];
  // Copy data from device to host mapping buffer
  AMDGPUDriver::get_instance().memcpy_device_to_host(info.mapped, info.ptr, total_bytes);

  *mapped_ptr = info.mapped;
  return RhiResult::success;
}

void AmdgpuDevice::unmap(DeviceAllocation alloc) {
  AllocInfo &info = allocations_[alloc.alloc_id];
  AMDGPUDriver::get_instance().memcpy_host_to_device(info.ptr, info.mapped, info.size);
  delete[] static_cast<char *>(info.mapped);
  info.mapped = nullptr;
}

void AmdgpuDevice::memcpy_internal(DevicePtr dst,
                                   DevicePtr src,
                                   uint64_t size) {
  void *dst_addr = static_cast<char *>(allocations_[dst.alloc_id].ptr) + dst.offset;
  void *src_addr = static_cast<char *>(allocations_[src.alloc_id].ptr) + src.offset;

  AMDGPUDriver::get_instance().memcpy_device_to_device(dst_addr, src_addr, size);
}

DeviceAllocation AmdgpuDevice::import_memory(void *external_ptr, size_t extent) {
  AllocInfo info;
  info.ptr = external_ptr;
  info.size = extent;
  info.is_imported = true;

  DeviceAllocation imported_alloc;
  imported_alloc.alloc_id = static_cast<int>(allocations_.size());
  imported_alloc.device = this;
  allocations_.push_back(info);

  return imported_alloc;
}

