#include "cpy.hpp"
#include <float.h>
#include "dequantize.hpp"
#include "ggml-sycl/common.hpp"
#include "ggml-sycl/presets.hpp"
#include "ggml.h"

// Single-element copy kernels for different data types
static void cpy_1_f32_f32(const char * src, char * dst) {
    const float * input  = reinterpret_cast<const float *>(src);
    float *       output = reinterpret_cast<float *>(dst);
    *output = *input;
}

static void cpy_1_f32_f16(const char * src, char * dst) {
    const float * input  = reinterpret_cast<const float *>(src);
    sycl::half *  output = reinterpret_cast<sycl::half *>(dst);
    *output = sycl::vec<float, 1>(*input).convert<sycl::half, sycl::rounding_mode::automatic>()[0];
}

static void cpy_1_f16_f16(const char * src, char * dst) {
    const sycl::half * input  = reinterpret_cast<const sycl::half *>(src);
    sycl::half *       output = reinterpret_cast<sycl::half *>(dst);
    *output = *input;
}

static void cpy_1_f16_f32(const char * src, char * dst) {
    const sycl::half * input  = reinterpret_cast<const sycl::half *>(src);
    float *            output = reinterpret_cast<float *>(dst);
    *output = *input;
}

static void cpy_1_i16_i16(const char * src, char * dst) {
    const int16_t * input  = reinterpret_cast<const int16_t *>(src);
    int16_t *       output = reinterpret_cast<int16_t *>(dst);
    *output = *input;
}

static void cpy_1_i32_i32(const char * src, char * dst) {
    const int32_t * input  = reinterpret_cast<const int32_t *>(src);
    int32_t *       output = reinterpret_cast<int32_t *>(dst);
    *output = *input;
}

// Generic block-level copy for same-type conversions
template<typename T>
static void cpy_block_same_type(const char * src, char * dst) {
    const T * input  = reinterpret_cast<const T *>(src);
    T *       output = reinterpret_cast<T *>(dst);
    *output = *input;
}

// Quantized to float conversion helpers
static void cpy_block_q8_0_to_f32(const char * src, char * dst) {
    float * float_dst = reinterpret_cast<float *>(dst);
    for (int j = 0; j < QK8_0; j += 2) {
        dfloat2 dq;
        dequantize_q8_0(src, 0, j, dq);
        *(float_dst + j)     = dq.x();
        *(float_dst + j + 1) = dq.y();
    }
}

template <dequantize_kernel_t dequant_func, int quant_k>
static void cpy_block_q_to_f32(const char * src, char * dst) {
    float * float_dst = reinterpret_cast<float *>(dst);
    for (int j = 0; j < quant_k / 2; ++j) {
        dfloat2 dq;
        dequant_func(src, 0, j, dq);
        *(float_dst + j)          = dq.x();
        *(float_dst + j + quant_k / 2) = dq.y();
    }
}

// Main SYCL kernel for generic type conversions
template <cpy_kernel_t block_cpy_func>
static void cpy_generic_kernel(const char * src, char * dst,
                               const int total_elements,
                               const int src_dims0, const int src_dims1, const int src_dims2,
                               const int src_stride0, const int src_stride1, const int src_stride2, const int src_stride3,
                               const int dst_dims0, const int dst_dims1, const int dst_dims2,
                               const int dst_stride0, const int dst_stride1, const int dst_stride2, const int dst_stride3,
                               const sycl::nd_item<3>& item) {
    const int idx = item.get_local_range(2) * item.get_group(2) + item.get_local_id(2);
    if (idx >= total_elements) return;

    // Compute source indices from flattened index
    const int idx3_src = idx / (src_dims0 * src_dims1 * src_dims2);
    const int idx2_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2) / (src_dims0 * src_dims1);
    const int idx1_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0) / src_dims0;
    const int idx0_src = idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0 - idx1_src * src_dims0;

    const int src_offset = idx0_src * src_stride0 + idx1_src * src_stride1 + idx2_src * src_stride2 + idx3_src * src_stride3;

    // Compute destination indices from flattened index
    const int idx3_dst = idx / (dst_dims0 * dst_dims1 * dst_dims2);
    const int idx2_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2) / (dst_dims0 * dst_dims1);
    const int idx1_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0) / dst_dims0;
    const int idx0_dst = idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0 - idx1_dst * dst_dims0;

    const int dst_offset = idx0_dst * dst_stride0 + idx1_dst * dst_stride1 + idx2_dst * dst_stride2 + idx3_dst * dst_stride3;

    block_cpy_func(src + src_offset, dst + dst_offset);
}

// Block-level quantized copy kernels
template <typename T, int quant_k>
static void cpy_quantized_kernel(const char * src, char * dst,
                                 const int total_elements,
                                 const int src_dims0, const int src_dims1, const int src_dims2,
                                 const int src_stride0, const int src_stride1, const int src_stride2, const int src_stride3,
                                 const int dst_dims0, const int dst_dims1, const int dst_dims2,
                                 const int dst_stride0, const int dst_stride1, const int dst_stride2, const int dst_stride3,
                                 const sycl::nd_item<3>& item) {
    const int idx = (item.get_local_range(2) * item.get_group(2) + item.get_local_id(2)) * quant_k;
    if (idx >= total_elements) return;

    const int idx3_src = idx / (src_dims0 * src_dims1 * src_dims2);
    const int idx2_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2) / (src_dims0 * src_dims1);
    const int idx1_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0) / src_dims0;
    const int idx0_src = idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0 - idx1_src * src_dims0;

    const int src_offset = (idx0_src / quant_k) * src_stride0 + idx1_src * src_stride1 + idx2_src * src_stride2 + idx3_src * src_stride3;

    const int idx3_dst = idx / (dst_dims0 * dst_dims1 * dst_dims2);
    const int idx2_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2) / (dst_dims0 * dst_dims1);
    const int idx1_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0) / dst_dims0;
    const int idx0_dst = idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0 - idx1_dst * dst_dims0;

    const int dst_offset = (idx0_dst / quant_k) * dst_stride0 + idx1_dst * dst_stride1 + idx2_dst * dst_stride2 + idx3_dst * dst_stride3;

    cpy_block_same_type<T>(src + src_offset, dst + dst_offset);
}

// Float-to-quantized and quantized-to-float kernels
template <cpy_kernel_t block_cpy_func, int quant_k>
static void cpy_float_to_quantized_kernel(const char * src, char * dst,
                                          const int total_elements,
                                          const int src_dims0, const int src_dims1, const int src_dims2,
                                          const int src_stride0, const int src_stride1, const int src_stride2, const int src_stride3,
                                          const int dst_dims0, const int dst_dims1, const int dst_dims2,
                                          const int dst_stride0, const int dst_stride1, const int dst_stride2, const int dst_stride3,
                                          const sycl::nd_item<3>& item) {
    const int idx = (item.get_local_range(2) * item.get_group(2) + item.get_local_id(2)) * quant_k;
    if (idx >= total_elements) return;

    const int idx3_src = idx / (src_dims0 * src_dims1 * src_dims2);
    const int idx2_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2) / (src_dims0 * src_dims1);
    const int idx1_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0) / src_dims0;
    const int idx0_src = idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0 - idx1_src * src_dims0;

    const int src_offset = idx0_src * src_stride0 + idx1_src * src_stride1 + idx2_src * src_stride2 + idx3_src * src_stride3;

    const int idx3_dst = idx / (dst_dims0 * dst_dims1 * dst_dims2);
    const int idx2_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2) / (dst_dims0 * dst_dims1);
    const int idx1_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0) / dst_dims0;
    const int idx0_dst = idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0 - idx1_dst * dst_dims0;

    const int dst_offset = (idx0_dst / quant_k) * dst_stride0 + idx1_dst * dst_stride1 + idx2_dst * dst_stride2 + idx3_dst * dst_stride3;

    block_cpy_func(src + src_offset, dst + dst_offset);
}

template <cpy_kernel_t block_cpy_func, int quant_k>
static void cpy_quantized_to_float_kernel(const char * src, char * dst,
                                          const int total_elements,
                                          const int src_dims0, const int src_dims1, const int src_dims2,
                                          const int src_stride0, const int src_stride1, const int src_stride2, const int src_stride3,
                                          const int dst_dims0, const int dst_dims1, const int dst_dims2,
                                          const int dst_stride0, const int dst_stride1, const int dst_stride2, const int dst_stride3,
                                          const sycl::nd_item<3>& item) {
    const int idx = (item.get_local_range(2) * item.get_group(2) + item.get_local_id(2)) * quant_k;
    if (idx >= total_elements) return;

    const int idx3_src = idx / (src_dims0 * src_dims1 * src_dims2);
    const int idx2_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2) / (src_dims0 * src_dims1);
    const int idx1_src = (idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0) / src_dims0;
    const int idx0_src = idx - idx3_src * src_dims0 * src_dims1 * src_dims2 - idx2_src * src_dims1 * src_dims0 - idx1_src * src_dims0;

    const int src_offset = (idx0_src / quant_k) * src_stride0 + idx1_src * src_stride1 + idx2_src * src_stride2 + idx3_src * src_stride3;

    const int idx3_dst = idx / (dst_dims0 * dst_dims1 * dst_dims2);
    const int idx2_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2) / (dst_dims0 * dst_dims1);
    const int idx1_dst = (idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0) / dst_dims0;
    const int idx0_dst = idx - idx3_dst * dst_dims0 * dst_dims1 * dst_dims2 - idx2_dst * dst_dims1 * dst_dims0 - idx1_dst * dst_dims0;

    const int dst_offset = idx0_dst * dst_stride0 + idx1_dst * dst_stride1 + idx2_dst * dst_stride2 + idx3_dst * dst_stride3;

    block_cpy_func(src + src_offset, dst + dst_offset);
}

// High-level SYCL dispatch functions
static void ggml_cpy_f16_f32_sycl(const char * src, char * dst,
                                  const int total_elements,
                                  const int src_dims0, const int src_dims1, const int src_dims2,
                                  const int src_stride0, const int src_stride1, const int src_stride2, const int src_stride3,
                                  const int dst_dims0, const int dst_dims1, const int dst_dims2,
                                  const int dst_stride0, const int dst_stride1, const int dst_stride2, const int dst_stride3,
                                  queue_ptr stream) {
    const int block_count = (total_elements + SYCL_CPY_BLOCK_SIZE - 1) / SYCL_CPY_BLOCK_SIZE;
    {
        dpct::has_capability_or_fail(stream->get_device(), {sycl::aspect::fp16});
        stream->parallel_for(
            sycl::nd_range<3>(sycl::range<3>(1, 1, block_count) * sycl::range<3>(1, 1, SYCL_CPY_BLOCK_SIZE),
                              sycl::range<3>(1, 1, SYCL_CPY_BLOCK_SIZE)),
            [=](sycl::nd_item<3> item) {
                cpy_generic_kernel<cpy_1_f16_f32>(src, dst, total_elements,
                                                  src_dims0, src_dims1, src_dims2,
                                                  src_stride0, src_stride1, src_stride2, src_stride3,
                                                  dst_dims0, dst_dims1, dst_dims2,
                                                  dst_stride0, dst_stride1, dst_stride2, dst_stride3,
                                                  item);
            });
