// Helper macros for bit manipulation clarity
#define SET_BIT(var, pos) ((var) |= (1UL << (pos)))
#define CLEAR_BIT(var, pos) ((var) &= ~(1UL << (pos)))
#define TEST_BIT(var, pos) (((var) >> (pos)) & 1U)

