    String manufacturer;
    uint8_t battery_level;
    uint16_t vid_val;
    uint16_t pid_val;
    uint16_t ver_val;
    uint16_t appearance_val;
    bool is_connected;
    bool use_rand_uuid;
    uint32_t delay_ms_val;
    const uint8_t* layout_map;
};

static BleKeyboardState g_state = {};

BleKeyboard::BleKeyboard(String deviceName, String deviceManufacturer, uint8_t batteryLevel)
    : hid(nullptr), deviceName(deviceName), deviceManufacturer(deviceManufacturer), batteryLevel(batteryLevel) {}

void BleKeyboard::begin(const uint8_t* layout, uint16_t showAs) {
    g_state.appearance_val = showAs;
    g_state.layout_map = layout;
    g_state.dev_name = deviceName.substring(0, 15);
    g_state.manufacturer = deviceManufacturer.substring(0, 15);
    g_state.battery_level = batteryLevel;

    BLEDevice::init(g_state.dev_name.c_str());
    BLEServer* pServer = BLEDevice::createServer();
    pServer->setCallbacks(this);

    g_state.hid_dev = new BLEHIDDevice(pServer);
    g_state.input_kb = g_state.hid_dev->inputReport(KEYBOARD_ID);
    g_state.output_kb = g_state.hid_dev->outputReport(KEYBOARD_ID);
    g_state.input_media = g_state.hid_dev->inputReport(MEDIA_KEYS_ID);

    g_state.input_kb->setCallbacks(this);
    g_state.output_kb->setCallbacks(this);
    g_state.input_media->setCallbacks(this);

    g_state.hid_dev->manufacturer()->setValue(g_state.manufacturer);
    g_state.hid_dev->pnp(0x02, g_state.vid_val, g_state.pid_val, g_state.ver_val);
    g_state.hid_dev->hidInfo(0x00, 0x01);

#if defined(USE_NIMBLE)
    BLEDevice::setSecurityAuth(true, true, true);
#else
    BLESecurity* sec = new BLESecurity();
    sec->setAuthenticationMode(ESP_LE_AUTH_REQ_SC_MITM_BOND);
#endif

    g_state.hid_dev->reportMap((uint8_t*)_hidReportDescriptor, sizeof(_hidReportDescriptor));
    g_state.hid_dev->startServices();

    onStarted(pServer);

    g_state.adv = pServer->getAdvertising();
    g_state.adv->setAppearance(g_state.appearance_val);

    if (g_state.use_rand_uuid) {
        uint16_t uuid16 = static_cast<uint16_t>(ESP.getEfuseMac() & 0xFFFF);
        g_state.adv->addServiceUUID(BLEUUID(uuid16));
    } else {
        g_state.adv->addServiceUUID(g_state.hid_dev->hidService()->getUUID());
    }

    g_state.adv->setScanResponse(false);
    g_state.adv->start();
    g_state.hid_dev->setBatteryLevel(g_state.battery_level);
}

void BleKeyboard::end(void) {
    int connectedCount = 0;
    if (BLEServer* srv = BLEDevice::getServer()) {
        connectedCount = srv->getConnectedCount();
        for (int idx = 0; idx < connectedCount; ++idx) {
            srv->disconnect(srv->getPeerInfo(idx).getConnHandle());
        }
    }

    delete g_state.hid_dev;
    BLEDevice::deinit();
    g_state.is_connected = false;
}

bool BleKeyboard::isConnected(void) { return g_state.is_connected; }

void BleKeyboard::setBatteryLevel(uint8_t level) {
    g_state.battery_level = level;
    if (g_state.hid_dev) {
        g_state.hid_dev->setBatteryLevel(level);
    }
}

void BleKeyboard::setName(String deviceName) { g_state.dev_name = deviceName; }

void BleKeyboard::setDelay(uint32_t ms) { g_state.delay_ms_val = ms; }

void BleKeyboard::set_vendor_id(uint16_t vid) { g_state.vid_val = vid; }
void BleKeyboard::set_product_id(uint16_t pid) { g_state.pid_val = pid; }
void BleKeyboard::set_version(uint16_t version) { g_state.ver_val = version; }

// Refactored sendReport: uses local copy and checks subscribed count
template<typename T>
bool BleKeyboard::notifyIfSubscribed(BLECharacteristic* chr, const T& data) {
    if (!g_state.is_connected || chr->getSubscribedCount() == 0) return false;
    chr->setValue(reinterpret_cast<const uint8_t*>(&data), sizeof(T));
    chr->notify();
#if defined(USE_NIMBLE)
    delay_ms(g_state.delay_ms_val);
#endif
    return true;
}

void BleKeyboard::sendReport(KeyReport* keys) {
    notifyIfSubscribed(g_state.input_kb, *keys);
}

void BleKeyboard::sendReport(MediaKeyReport* keys) {
    notifyIfSubscribed(g_state.input_media, *keys);
}

// Helper: map ASCII to scan code
static inline uint8_t ascii_to_scancode(uint8_t c, const uint8_t* map) {
    uint8_t sc = pgm_read_byte(map + c);
    if (!sc) return 0;
    return sc;
}

size_t BleKeyboard::press(uint8_t k) {
    uint8_t mod = g_state.current_keys.modifiers;
    uint8_t* keys = g_state.current_keys.keys;

    if (k >= 0xE0 && k < 0xE8) {
        // Modifiers already handled as-is
    } else if (k >= 0x88) {
        k -= 0x88;
    } else if (k >= 0x80) {
        uint8_t shiftIdx = k - 0x80;
        SET_BIT(mod, shiftIdx);
        k = 0;
    } else {
        uint8_t sc = ascii_to_scancode(k, g_state.layout_map);
        if (!sc) {
            setWriteError();
            return 0;
        }

        if ((sc & 0xC0) == 0xC0) { // ALT_GR
            SET_BIT(mod, 6);       // right Alt
            sc &= 0x3F;
        } else if ((sc & 0x80) == 0x80) { // SHIFT
            SET_BIT(mod, 1);                // left Shift
            sc &= 0x7F;
        }

        if (sc == 0x32) sc = 0x64; // ISO_REPLACEMENT -> ISO_KEY
        k = sc;
    }

    // Insert into first free slot
    bool found = false;
    for (int i = 0; i < 6; ++i) {
        if (keys[i] == 0) {
            keys[i] = k;
            found = true;
            break;
        }
    }

    if (!found) {
        setWriteError();
        return 0;
    }

    sendReport(&g_state.current_keys);
    return 1;
}

size_t BleKeyboard::press(const MediaKeyReport k) {
    uint16_t incoming = (static_cast<uint16_t>(k[1]) << 8) | k[0];
    uint16_t existing = (static_cast<uint16_t>(g_state.current_media[1]) << 8) | g_state.current_media[0];
    uint16_t combined = existing | incoming;
    g_state.current_media[0] = static_cast<uint8_t>(combined & 0xFF);
    g_state.current_media[1] = static_cast<uint8_t>((combined >> 8) & 0xFF);
    sendReport(&g_state.current_media);
    return 1;
}

size_t BleKeyboard::release(uint8_t k) {
    uint8_t mod = g_state.current_keys.modifiers;
    uint8_t* keys = g_state.current_keys.keys;

    if (k >= 136) {
        k -= 136;
    } else if (k >= 128) {
        uint8_t bit = k - 128;
        CLEAR_BIT(mod, bit);
        k = 0;
    } else {
        uint8_t sc = ascii_to_scancode(k, g_state.layout_map);
        if (!sc) return 0;

        if ((sc & ALT_GR) == ALT_GR) {
            CLEAR_BIT(mod, 6);
            sc &= 0x3F;
        } else if ((sc & SHIFT) == SHIFT) {
            CLEAR_BIT(mod, 1);
            sc &= 0x7F;
        }

        if (sc == ISO_REPLACEMENT) sc = ISO_KEY;
        k = sc;
    }

    // Clear all occurrences of key
    for (int i = 0; i < 6; ++i) {
        if (keys[i] == k) keys[i] = 0;
    }

    sendReport(&g_state.current_keys);
    return 1;
}

size_t BleKeyboard::release(const MediaKeyReport k) {
    uint16_t incoming = (static_cast<uint16_t>(k[1]) << 8) | k[0];
    uint16_t existing = (static_cast<uint16_t>(g_state.current_media[1]) << 8) | g_state.current_media[0];
    uint16_t cleared = existing & ~incoming;
    g_state.current_media[0] = static_cast<uint8_t>(cleared & 0xFF);
    g_state.current_media[1] = static_cast<uint8_t>((cleared >> 8) & 0xFF);
    sendReport(&g_state.current_media);
    return 1;
}

void BleKeyboard::releaseAll(void) {
    for (int i = 0; i < 6; ++i) g_state.current_keys.keys[i] = 0;
    g_state.current_keys.modifiers = 0;
    g_state.current_media[0] = 0;
    g_state.current_media[1] = 0;
    sendReport(&g_state.current_keys);
    sendReport(&g_state.current_media);
}

size_t BleKeyboard::write(uint8_t c) {
    size_t res = press(c);
    release(c);
    return res;
}

size_t BleKeyboard::write(const MediaKeyReport c) {
    size_t res = press(c);
    release(c);
    return res;
}

size_t BleKeyboard::write(const uint8_t* buffer, size_t size) {
    size_t written = 0;
    while (size--) {
        uint8_t ch = *buffer++;
        if (ch != '\r') {
            if (write(ch)) ++written;
            else break;
        }
    }
    return written;
}

void BleKeyboard::onConnect(BLEServer* pServer) {
    Serial.println("lib connected");
#if !defined(USE_NIMBLE)
    BLE2902* desc_kb = (BLE2902*)g_state.input_kb->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    BLE2902* desc_med = (BLE2902*)g_state.input_media->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    if (desc_kb) desc_kb->setNotifications(true);
    if (desc_med) desc_med->setNotifications(true);
#endif
    g_state.is_connected = true;
}

void BleKeyboard::onDisconnect(BLEServer* pServer) {
    g_state.is_connected = false;
    Serial.println("lib disconnected");
#if !defined(USE_NIMBLE)
    BLE2902* desc_kb = (BLE2902*)g_state.input_kb->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    BLE2902* desc_med = (BLE2902*)g_state.input_media->getDescriptorByUUID(BLEUUID((uint16_t)0x2902));
    if (desc_kb) desc_kb->setNotifications(false);
    if (desc_med) desc_med->setNotifications(false);
    g_state.adv->start();
#endif
}

void BleKeyboard::onAuthenticationComplete(ble_gap_conn_desc* desc) {
    if (desc->sec_state.encrypted) {
        Serial.println("Paired successfully.");
        g_state.is_connected = true;
    } else {
        Serial.println("Pairing failed");
        g_state.is_connected = false;
    }
}

void BleKeyboard::onWrite(BLECharacteristic* me) {
    std::string val = me->getValue();
    if (!val.empty()) {
        ESP_LOGI(LOG_TAG, "special keys: %d", val[0]);
    }
}

void BleKeyboard::delay_ms(uint64_t ms) {
    uint64_t start = esp_timer_get_time();
    if (ms > 0) {
        uint64_t target = start + ms * 1000ULL;
        if (target < start) { // overflow case
            while (esp_timer_get_time() > target) {}
        }
        while (esp_timer_get_time() < target) {}
    }
}

void BleKeyboard::onSubscribe(
    NimBLECharacteristic* pCharacteristic, ble_gap_conn_desc* desc, uint16_t subValue
) {
    if (subValue == 0) {
        Serial.println("Client unsubscribed from notifications/indications.");
    } else {
        Serial.println("Client subscribed to notifications.");
    }
}

