#include "web_video_server/libav_streamer.h"
#include "async_web_server_cpp/http_reply.hpp"

// Compatibility macros for older FFmpeg versions
#define AV_CODEC_FLAG_GLOBAL_HEADER (1 << 22)
#define CODEC_FLAG_GLOBAL_HEADER AV_CODEC_FLAG_GLOBAL_HEADER

namespace web_video_server {

// Helper: Lock manager for FFmpeg thread safety
static int ffmpeg_mutex_handler(void **mutex_ptr, enum AVLockOp operation) {
    if (!mutex_ptr) return -1;

    switch (operation) {
        case AV_LOCK_CREATE: {
            *mutex_ptr = nullptr;
            auto *m = new boost::mutex();
            *mutex_ptr = static_cast<void*>(m);
            break;
        }
        case AV_LOCK_OBTAIN: {
            auto *m = static_cast<boost::mutex*>(*mutex_ptr);
            m->lock();
            break;
        }
        case AV_LOCK_RELEASE: {
            auto *m = static_cast<boost::mutex*>(*mutex_ptr);
            m->unlock();
            break;
        }
        case AV_LOCK_DESTROY: {
            auto *m = static_cast<boost::mutex*>(*mutex_ptr);
            delete m;
            break;
        }
        default:
            break;
    }
    return 0;
}

// Helper: Check if FFmpeg version is below a given threshold
inline bool is_ffmpeg_before(int major, int minor, int micro) {
#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(58,9,100)
    return false;
#else
    return true;
#endif
}

LibavStreamer::LibavStreamer(const async_web_server_cpp::HttpRequest &req,
                             async_web_server_cpp::HttpConnectionPtr conn,
                             ros::NodeHandle& nh,
                             const std::string &fmt_name,
                             const std::string &codec_name,
                             const std::string &content_type)
    : ImageTransportImageStreamer(req, conn, nh),
      output_fmt_(nullptr),
      fmt_ctx_(nullptr),
      enc_(nullptr),
      enc_ctx_(nullptr),
      vid_stream_(nullptr),
      av_frame_(nullptr),
      sws_ctx_(nullptr),
      first_frame_seen_(false),
      start_time_(),
      format_name_(fmt_name),
      codec_name_(codec_name),
      content_type_(content_type),
      opts_(nullptr),
      io_buf_(nullptr)
{
    bitrate_ = req.get_query_param_value_or_default<int>("bitrate", 100000);
    qmin_ = req.get_query_param_value_or_default<int>("qmin", 10);
    qmax_ = req.get_query_param_value_or_default<int>("qmax", 42);
    gop_size_ = req.get_query_param_value_or_default<int>("gop", 25);

    if (is_ffmpeg_before(58, 9, 100)) {
        av_lockmgr_register(&ffmpeg_mutex_handler);
        av_register_all();
    }
}

LibavStreamer::~LibavStreamer() {
    if (enc_ctx_) {
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(58,9,100)
        avcodec_close(enc_ctx_);
#else
        avcodec_free_context(&enc_ctx_);
#endif
    }

    if (av_frame_) {
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
        av_free(av_frame_);
        av_frame_ = nullptr;
#else
        av_frame_free(&av_frame_);
#endif
    }

    delete[] io_buf_;

    if (fmt_ctx_) {
        if (fmt_ctx_->pb) {
            av_free(fmt_ctx_->pb);
        }
        avformat_free_context(fmt_ctx_);
    }

    if (sws_ctx_) {
        sws_freeContext(sws_ctx_);
    }
}

// Custom IO callback for writing encoded data
static int send_encoded_data(void *opaque, uint8_t *buf, int size) {
    auto *conn = static_cast<async_web_server_cpp::HttpConnectionPtr*>(opaque);
    std::vector<uint8_t> chunk(buf, buf + size);
    (*conn)->write_and_clear(chunk);
    return 0;
}

void LibavStreamer::initialize(const cv::Mat &img) {
    // Allocate context
    fmt_ctx_ = avformat_alloc_context();
    if (!fmt_ctx_) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Failed to allocate FFmpeg format context");
    }

    // Guess output format
    output_fmt_ = av_guess_format(format_name_.c_str(), nullptr, nullptr);
    if (!output_fmt_) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Could not determine output format");
    }

    fmt_ctx_->oformat = output_fmt_;

    // Setup custom I/O buffer
    constexpr size_t io_size = 3 * 1024; // 3KB
    io_buf_ = new unsigned char[io_size];
    AVIOContext *io_ctx = avio_alloc_context(io_buf_, io_size, AVIO_FLAG_WRITE,
                                             &connection_, nullptr, send_encoded_data, nullptr);
    if (!io_ctx) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Failed to set up I/O context");
    }

    io_ctx->seekable = 0;
    fmt_ctx_->pb = io_ctx;
    fmt_ctx_->max_interleave_delta = 0;

    output_fmt_->flags |= AVFMT_FLAG_CUSTOM_IO | AVFMT_NOFILE;

    // Select encoder
    enc_ = codec_name_.empty()
               ? avcodec_find_encoder(output_fmt_->video_codec)
               : avcodec_find_encoder_by_name(codec_name_.c_str());
    if (!enc_) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Encoder lookup failed");
    }

    vid_stream_ = avformat_new_stream(fmt_ctx_, enc_);
    if (!vid_stream_) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Video stream creation failed");
    }

#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(58,9,100)
    enc_ctx_ = vid_stream_->codec;
#else
    enc_ctx_ = avcodec_alloc_context3(enc_);
#endif

    avcodec_get_context_defaults3(enc_ctx_, enc_);
    enc_ctx_->codec_id = enc_->id;
    enc_ctx_->bit_rate = bitrate_;
    enc_ctx_->width = output_width_;
    enc_ctx_->height = output_height_;
    enc_ctx_->delay = 0;
    vid_stream_->time_base = {1, 1000};
    enc_ctx_->time_base = {1, 1};
    enc_ctx_->gop_size = gop_size_;
    enc_ctx_->pix_fmt = AV_PIX_FMT_YUV420P;
    enc_ctx_->max_b_frames = 0;
    enc_ctx_->qmin = qmin_;
    enc_ctx_->qmax = qmax_;

#if LIBAVCODEC_VERSION_INT >= AV_VERSION_INT(58,9,100)
    if (avcodec_parameters_from_context(vid_stream_->codecpar, enc_ctx_) < 0) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Failed to copy codec parameters");
    }
#endif

    initializeEncoder();

    enc_ctx_->flags |= AV_CODEC_FLAG_LOW_DELAY;

    if (avcodec_open2(enc_ctx_, enc_, nullptr) < 0) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Could not open video codec");
    }

    // Allocate frame buffer
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
    av_frame_ = avcodec_alloc_frame();
#else
    av_frame_ = av_frame_alloc();
#endif
    av_image_alloc(av_frame_->data, av_frame_->linesize,
                   output_width_, output_height_,
                   enc_ctx_->pix_fmt, 1);
    av_frame_->width = output_width_;
    av_frame_->height = output_height_;
    av_frame_->format = enc_ctx_->pix_fmt;

    // Metadata
    av_dict_set(&fmt_ctx_->metadata, "author", "ROS web_video_server", 0);
    av_dict_set(&fmt_ctx_->metadata, "title", topic_.c_str(), 0);

    // Send HTTP headers
    async_web_server_cpp::HttpReply::builder(async_web_server_cpp::HttpReply::ok)
        .header("Connection", "close")
        .header("Server", "web_video_server")
        .header("Cache-Control", "no-cache, no-store, must-revalidate, pre-check=0, post-check=0, max-age=0")
        .header("Pragma", "no-cache")
        .header("Expires", "0")
        .header("Max-Age", "0")
        .header("Trailer", "Expires")
        .header("Content-type", content_type_)
        .header("Access-Control-Allow-Origin", "*")
        .write(connection_);

    // Write stream header
    if (avformat_write_header(fmt_ctx_, &opts_) < 0) {
        async_web_server_cpp::HttpReply::stock_reply(async_web_server_cpp::HttpReply::internal_server_error)(request_, connection_, nullptr, nullptr);
        throw std::runtime_error("Failed to write stream header");
    }
}

