    // Placeholder — can be overridden by subclasses
}

void LibavStreamer::sendImage(
    const cv::Mat &img,
    const std::chrono::steady_clock::time_point &timestamp) {

    boost::mutex::scoped_lock lock(encode_mutex_);

    if (!first_frame_seen_) {
        first_frame_seen_ = true;
        start_time_ = timestamp;
    }

#if (LIBAVUTIL_VERSION_MAJOR < 53)
    PixelFormat input_fmt = PIX_FMT_BGR24;
#else
    AVPixelFormat input_fmt = AV_PIX_FMT_BGR24;
#endif

#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
    AVPicture *raw_frame = new AVPicture;
    avpicture_fill(raw_frame, img.data, input_fmt, output_width_, output_height_);
#else
    AVFrame *raw_frame = av_frame_alloc();
    av_image_fill_arrays(raw_frame->data, raw_frame->linesize,
                         img.data, input_fmt, output_width_, output_height_, 1);
#endif

    // Initialize conversion context if needed
    if (!sws_ctx_) {
        static int flags = SWS_BICUBIC;
        sws_ctx_ = sws_getContext(output_width_, output_height_, input_fmt,
                                  output_width_, output_height_, enc_ctx_->pix_fmt,
                                  flags, nullptr, nullptr, nullptr);
        if (!sws_ctx_) {
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
            delete raw_frame;
#else
            av_frame_free(&raw_frame);
#endif
            throw std::runtime_error("Failed to create scaling context");
        }
    }

    sws_scale(sws_ctx_,
              reinterpret_cast<const uint8_t * const *>(raw_frame->data),
              raw_frame->linesize, 0,
              output_height_, av_frame_->data, av_frame_->linesize);

#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
    delete raw_frame;
#else
    av_frame_free(&raw_frame);
#endif

    // Encode frame
    AVPacket pkt{};
    av_init_packet(&pkt);
    int got_output = 0;

#if LIBAVCODEC_VERSION_MAJOR < 54
    int buf_len = 6 * output_width_ * output_height_;
    pkt.data = static_cast<uint8_t*>(av_malloc(buf_len));
    pkt.size = avcodec_encode_video(enc_ctx_, pkt.data, buf_len, av_frame_);
    got_output = pkt.size > 0;
#elif LIBAVCODEC_VERSION_MAJOR < 57
    pkt.data = nullptr;
    pkt.size = 0;
    if (avcodec_encode_video2(enc_ctx_, &pkt, av_frame_, &got_output) < 0) {
        throw std::runtime_error("Encoding error");
    }
#else
    int ret = avcodec_send_frame(enc_ctx_, av_frame_);
    if (ret == AVERROR_EOF) {
        ROS_DEBUG_STREAM("Encoder flushed");
    } else if (ret == AVERROR(EAGAIN)) {
        ROS_DEBUG_STREAM("Need to drain output first");
    }

    if (ret < 0) {
        throw std::runtime_error("Encoding error");
    }

    ret = avcodec_receive_packet(enc_ctx_, &pkt);
    got_output = (pkt.size > 0);
    if (ret == AVERROR_EOF) {
        ROS_DEBUG_STREAM("Encoder drained");
    } else if (ret == AVERROR(EAGAIN)) {
        ROS_DEBUG_STREAM("More input required");
        got_output = 0;
    }
#endif

    if (got_output) {
        double elapsed_sec = std::chrono::duration_cast<std::chrono::duration<double>>(timestamp - start_time_).count();
        pkt.pts = static_cast<int64_t>(elapsed_sec / av_q2d(vid_stream_->time_base) * 0.95);
        if (pkt.pts <= 0) pkt.pts = 1;
        pkt.dts = AV_NOPTS_VALUE;
        pkt.flags |= (pkt.flags & AV_PKT_FLAG_KEY) ? AV_PKT_FLAG_KEY : 0;
        pkt.stream_index = vid_stream_->index;

        if (av_write_frame(fmt_ctx_, &pkt) < 0) {
            throw std::runtime_error("Write frame failed");
        }
    }

#if LIBAVCODEC_VERSION_INT < 54
    av_free(pkt.data);
#endif
#if LIBAVCODEC_VERSION_INT < AV_VERSION_INT(55,28,1)
    av_free_packet(&pkt);
#else
    av_packet_unref(&pkt);
#endif

    // Send empty frame (no-op here, kept for compatibility)
    connection_->write_and_clear(std::vector<uint8_t>{});
}

LibavStreamerType::LibavStreamerType(const std::string &fmt_name,
                                     const std::string &codec_name,
                                     const std::string &content_type)
    : format_name_(fmt_name), codec_name_(codec_name), content_type_(content_type) {}

boost::shared_ptr<ImageStreamer> LibavStreamerType::create_streamer(
    const async_web_server_cpp::HttpRequest &req,
    async_web_server_cpp::HttpConnectionPtr conn,
    ros::NodeHandle& nh) {
    return boost::make_shared<LibavStreamer>(
        req, conn, nh, format_name_, codec_name_, content_type_);
}

std::string LibavStreamerType::create_viewer(const async_web_server_cpp::HttpRequest &req) {
    std::ostringstream oss;
    oss << "<video src=\"/stream?" << req.query << "\" autoplay=\"true\" preload=\"none\"></video>";
    return oss.str();
}

