using namespace MOBase;

DiagnosticsSettingsTab::DiagnosticsSettingsTab(Settings& s, SettingsDialog& d)
    : SettingsTab(s, d)
{
    initializeLogLevelSelection();
    initializeLootLogLevelSelection();
    initializeCrashDumpTypeSelection();

    ui->dumpsMaxEdit->setValue(settings().diagnostics().maxCoreDumps());

    const auto dataPath = qApp->property("dataPath").toString();
    const auto logDirW = QString::fromStdWString(AppConfig::logPath());
    const auto dumpDirW = QString::fromStdWString(AppConfig::dumpsDir());
    const auto logsUrl = QUrl::fromLocalFile(dataPath + "/" + logDirW).toString();
    const auto dumpsUrl = QUrl::fromLocalFile(
        QString::fromStdWString(OrganizerCore::getGlobalCoreDumpPath())
    ).toString();

    auto label = ui->diagnosticsExplainedLabel->text();
    label.replace("LOGS_FULL_PATH", logsUrl);
    label.replace("LOGS_DIR", logDirW);
    label.replace("DUMPS_FULL_PATH", dumpsUrl);
    label.replace("DUMPS_DIR", dumpDirW);
    ui->diagnosticsExplainedLabel->setText(label);
}

void DiagnosticsSettingsTab::initializeLogLevelSelection()
{
    ui->logLevelBox->clear();

    const auto levelMap = {
        std::make_pair(QObject::tr("Debug"), log::Debug),
        std::make_pair(QObject::tr("Info (recommended)"), log::Info),
        std::make_pair(QObject::tr("Warning"), log::Warning),
        std::make_pair(QObject::tr("Error"), log::Error)
    };

    for (const auto& [text, level] : levelMap) {
        ui->logLevelBox->addItem(text, static_cast<int>(level));
    }

    const int targetLevel = static_cast<int>(settings().diagnostics().logLevel());
    auto it = std::find_if(ui->logLevelBox->begin(), ui->logLevelBox->end(),
                           [targetLevel](int idx) {
                               return ui->logLevelBox->itemData(idx).toInt() == targetLevel;
                           });

    if (it != ui->logLevelBox->end()) {
        ui->logLevelBox->setCurrentIndex(*it);
    }
}

void DiagnosticsSettingsTab::initializeLootLogLevelSelection()
{
    using L = lootcli::LogLevels;

    ui->lootLogLevel->clear();

    const auto levelMap = {
        std::make_pair(QObject::tr("Trace"), L::Trace),
        std::make_pair(QObject::tr("Debug"), L::Debug),
        std::make_pair(QObject::tr("Info (recommended)"), L::Info),
        std::make_pair(QObject::tr("Warning"), L::Warning),
        std::make_pair(QObject::tr("Error"), L::Error)
    };

    for (const auto& [text, level] : levelMap) {
        ui->lootLogLevel->addItem(text, static_cast<int>(level));
    }

    const int desiredLevel = static_cast<int>(settings().diagnostics().lootLogLevel());
    auto it = std::find_if(ui->lootLogLevel->begin(), ui->lootLogLevel->end(),
                           [desiredLevel](int idx) {
                               return ui->lootLogLevel->itemData(idx).toInt() == desiredLevel;
                           });

    if (it != ui->lootLogLevel->end()) {
        ui->lootLogLevel->setCurrentIndex(*it);
    }
}

void DiagnosticsSettingsTab::initializeCrashDumpTypeSelection()
{
    ui->dumpsTypeBox->clear();

    const auto typeMap = {
        std::make_pair(QObject::tr("None"), env::CoreDumpTypes::None),
        std::make_pair(QObject::tr("Mini (recommended)"), env::CoreDumpTypes::Mini),
        std::make_pair(QObject::tr("Data"), env::CoreDumpTypes::Data),
        std::make_pair(QObject::tr("Full"), env::CoreDumpTypes::Full)
    };

    for (const auto& [text, type] : typeMap) {
        ui->dumpsTypeBox->addItem(text, static_cast<int>(type));
    }

    const int selectedType = static_cast<int>(settings().diagnostics().coreDumpType());
    auto it = std::find_if(ui->dumpsTypeBox->begin(), ui->dumpsTypeBox->end(),
                           [selectedType](int idx) {
                               return ui->dumpsTypeBox->itemData(idx).toInt() == selectedType;
                           });

    if (it != ui->dumpsTypeBox->end()) {
        ui->dumpsTypeBox->setCurrentIndex(*it);
    }
}

void DiagnosticsSettingsTab::update()
{
    auto& diagSettings = settings().diagnostics();

    diagSettings.setLogLevel(
        static_cast<log::Levels>(ui->logLevelBox->currentData().toInt()));

    diagSettings.setCoreDumpType(
        static_cast<env::CoreDumpTypes>(ui->dumpsTypeBox->currentData().toInt()));

    diagSettings.setMaxCoreDumps(ui->dumpsMaxEdit->value());

    diagSettings.setLootLogLevel(
        static_cast<lootcli::LogLevels>(ui->lootLogLevel->currentData().toInt()));
}

