// Case-insensitive character conversion helper
char tolower_char(char c) {
    return (c >= 'A' && c <= 'Z') ? (c + ('a' - 'A')) : c;
}

// Check if filename ends with ".cue" (case-insensitive)
bool is_cue_file(const char* path) {
    size_t len = strlen(path);
    if (len < 4) return false;

    const char* suffix = path + len - 4;
    return tolower_char(suffix[0]) == '.' &&
           tolower_char(suffix[1]) == 'c' &&
           tolower_char(suffix[2]) == 'u' &&
           tolower_char(suffix[3]) == 'e';
}

// Check if filename ends with ".mds"
bool is_mds_file(const char* path) {
    size_t len = strlen(path);
    if (len < 4) return false;

    const char* suffix = path + len - 4;
    return tolower_char(suffix[0]) == '.' &&
           tolower_char(suffix[1]) == 'm' &&
           tolower_char(suffix[2]) == 'd' &&
           tolower_char(suffix[3]) == 's';
}

// Check if filename ends with ".bin"
bool is_bin_file(const char* path) {
    size_t len = strlen(path);
    if (len < 4) return false;

    const char* suffix = path + len - 4;
    return tolower_char(suffix[0]) == '.' &&
           tolower_char(suffix[1]) == 'b' &&
           tolower_char(suffix[2]) == 'i' &&
           tolower_char(suffix[3]) == 'n';
}

// Check if filename ends with ".iso"
bool is_iso_file(const char* path) {
    size_t len = strlen(path);
    if (len < 4) return false;

    const char* suffix = path + len - 4;
    return tolower_char(suffix[0]) == '.' &&
           tolower_char(suffix[1]) == 'i' &&
           tolower_char(suffix[2]) == 's' &&
           tolower_char(suffix[3]) == 'o';
}

// Check if filename ends with ".chd"
bool is_chd_file(const char* path) {
    size_t len = strlen(path);
    if (len < 4) return false;

    const char* suffix = path + len - 4;
    return tolower_char(suffix[0]) == '.' &&
           tolower_char(suffix[1]) == 'c' &&
           tolower_char(suffix[2]) == 'h' &&
           tolower_char(suffix[3]) == 'd';
}

// Check if filename contains ".dvd." substring (case-insensitive)
bool has_dvd_indicator(const char* path) {
    for (size_t i = 0; path[i] != '\0'; ++i) {
        if (tolower_char(path[i]) == '.' &&
            tolower_char(path[i+1]) == 'd' &&
            tolower_char(path[i+2]) == 'v' &&
            tolower_char(path[i+3]) == 'd' &&
            tolower_char(path[i+4]) == '.') {
            return true;
        }
    }
    return false;
}

// Replace last 3 characters with ".bin"
void set_extension_to_bin(char* fullpath) {
    size_t len = strlen(fullpath);
    if (len >= 3) {
        fullpath[len - 3] = 'b';
        fullpath[len - 2] = 'i';
        fullpath[len - 1] = 'n';
    }
}

// Replace last 3 characters with ".cue"
void set_extension_to_cue(char* fullpath) {
    size_t len = strlen(fullpath);
    if (len >= 3) {
        fullpath[len - 3] = 'c';
        fullpath[len - 2] = 'u';
        fullpath[len - 1] = 'e';
    }
}

// Read entire file into heap-allocated string
bool slurp_file(const char* filepath, char** out_data) {
    if (!out_data) return false;

    FIL* fp = new FIL();
    FRESULT res = f_open(fp, filepath, FA_READ);
    if (res != FR_OK) {
        LOGERR("Failed to open file: %s", filepath);
        delete fp;
        return false;
    }

    DWORD filesize = f_size(fp);
    char* buffer = new char[filesize + 1];
    if (!buffer) {
        f_close(fp);
        delete fp;
        return false;
    }

    UINT bytes_read = 0;
    res = f_read(fp, buffer, filesize, &bytes_read);
    f_close(fp);
    delete fp;

    if (res != FR_OK || bytes_read != filesize) {
        delete[] buffer;
        return false;
    }

    buffer[filesize] = '\0';
    *out_data = buffer;
    return true;
}

// ============================================================================
// MDS Loader
// ============================================================================
IImageDevice* load_mds_image(const char* image_path) {
    LOGNOTE("Loading MDS image: %s", image_path);
    MEDIA_TYPE media_type = has_dvd_indicator(image_path) ? MEDIA_TYPE::DVD : MEDIA_TYPE::CD;

    char full_path[512];
    strncpy(full_path, image_path, sizeof(full_path) - 1);
    full_path[sizeof(full_path) - 1] = '\0';

    char* mds_content = nullptr;
    if (!slurp_file(full_path, &mds_content)) {
        LOGERR("Could not read MDS file: %s", full_path);
        return nullptr;
    }

    CMDSFileDevice* dev = new CMDSFileDevice(full_path, mds_content, media_type);
    if (!dev->Init()) {
        LOGERR("MDS device initialization failed: %s", image_path);
        delete dev;
        return nullptr;
    }

    LOGNOTE("Successfully loaded MDS device: %s (subchannels: %s)",
            image_path,
            dev->HasSubchannelData() ? "yes" : "no");
    return dev;
}

// ============================================================================
// CUE/BIN/ISO/TOAST Loader
// ============================================================================
IImageDevice* load_cue_bin_iso_image(const char* image_path) {
    LOGNOTE("Loading CUE/BIN/ISO image: %s", image_path);
    MEDIA_TYPE media_type = has_dvd_indicator(image_path) ? MEDIA_TYPE::DVD : MEDIA_TYPE::CD;

    char full_path[512];
    strncpy(full_path, image_path, sizeof(full_path) - 1);
    full_path[sizeof(full_path) - 1] = '\0';

    FIL* data_file = new FIL();
    char* cue_content = nullptr;

    // If .bin, assume matching .cue exists and switch to that first
    if (is_bin_file(full_path)) {
        LOGNOTE("BIN detected — looking for associated CUE");
        set_extension_to_cue(full_path);
    }

    // If now pointing at .cue, load it and then switch back to .bin/.iso
    if (is_cue_file(full_path)) {
        LOGNOTE("Reading CUE sheet from: %s", full_path);
        if (!slurp_file(full_path, &cue_content)) {
            LOGERR("Failed to read CUE file: %s", full_path);
            delete data_file;
            return nullptr;
        }
        LOGNOTE("CUE sheet loaded");
        set_extension_to_bin(full_path); // Try .bin next
    }

    // Open actual data file (.bin or .iso)
    LOGNOTE("Opening data file: %s", full_path);
    FRESULT result = f_open(data_file, full_path, FA_READ);
    if (result != FR_OK) {
        LOGERR("Failed to open data file: %s (error %d)", full_path, result);
        delete data_file;
        if (cue_content) delete[] cue_content;
        return nullptr;
    }

    LOGNOTE("Data file opened successfully");

    CCueBinFileDevice* device = new CCueBinFileDevice(data_file, cue_content, media_type);

    // Ownership transfer handled by constructor if cue_content non-null
    if (cue_content != nullptr)
        delete[] cue_content;

    LOGNOTE("Successfully loaded CUE/BIN/ISO device: %s", image_path);
    return device;
}

// ============================================================================
// CHD Loader
// ============================================================================
IImageDevice* load_chd_image(const char* image_path) {
    LOGNOTE("Loading CHD image: %s", image_path);
    MEDIA_TYPE media_type = has_dvd_indicator(image_path) ? MEDIA_TYPE::DVD : MEDIA_TYPE::CD;

    char full_path[512];
    strncpy(full_path, image_path, sizeof(full_path) - 1);
    full_path[sizeof(full_path) - 1] = '\0';

    CCHDFileDevice* chd_dev = new CCHDFileDevice(full_path, media_type);
    if (!chd_dev->Init()) {
        LOGERR("CHD device init failed: %s", image_path);
        delete chd_dev;
        return nullptr;
    }

    LOGNOTE("Successfully loaded CHD device: %s (subchannels: %s)",
            image_path,
            chd_dev->HasSubchannelData() ? "yes" : "no");
    return chd_dev;
}

// ============================================================================
// FatFs Optimizer Helpers
// ============================================================================
boolean FatFsOptimizer::EnableFastSeek(FIL* pFile, DWORD** ppCLMT, size_t clmtSize, const char* logPrefix) {
    if (!pFile || !ppCLMT) {
        return false;
    }

    *ppCLMT = new DWORD[clmtSize];
    if (!*ppCLMT) {
        LOGERR("%sFast seek: CLMT allocation failed", logPrefix);
        return false;
    }

    pFile->cltbl = *ppCLMT;
    (*ppCLMT)[0] = static_cast<DWORD>(clmtSize);

    FRESULT rc = f_lseek(pFile, CREATE_LINKMAP);
    if (rc == FR_OK) {
        f_lseek(pFile, 0);
        LOGNOTE("%sFast seek enabled (%u entries)", logPrefix, (*ppCLMT)[0]);
        return true;
    } else if (rc == FR_NOT_ENOUGH_CORE) {
        LOGERR("%sFast seek: insufficient memory for %u CLMT entries (requested %zu)",
               logPrefix, (*ppCLMT)[0], clmtSize);
    } else {
        LOGERR("%sFast seek: error %d during creation", logPrefix, rc);
    }

    delete[] *ppCLMT;
    *ppCLMT = nullptr;
    pFile->cltbl = nullptr;
    return false;
}

void FatFsOptimizer::DisableFastSeek(DWORD** ppCLMT) {
    if (ppCLMT && *ppCLMT) {
        delete[] *ppCLMT;
        *ppCLMT = nullptr;
    }
}

// ============================================================================
// Main Entry Point
// ============================================================================
IImageDevice* loadImageDevice(const char* image_path) {
    LOGNOTE("loadImageDevice invoked for: %s", image_path);

    if (is_mds_file(image_path)) {
        LOGNOTE("Format recognized as MDS");
        return load_mds_image(image_path);
    }
    else if (is_chd_file(image_path)) {
        LOGNOTE("Format recognized as CHD");
        return load_chd_image(image_path);
    }
    else if (is_cue_file(image_path) ||
             is_bin_file(image_path) ||
             is_iso_file(image_path) ||
             /* Optional: support toast extension */
             (strlen(image_path) >= 6 &&
              tolower_char(image_path[strlen(image_path)-6]) == '.' &&
              tolower_char(image_path[strlen(image_path)-5]) == 't' &&
              tolower_char(image_path[strlen(image_path)-4]) == 'o' &&
              tolower_char(image_path[strlen(image_path)-3]) == 'a' &&
              tolower_char(image_path[strlen(image_path)-2]) == 's' &&
              tolower_char(image_path[strlen(image_path)-1]) == 't')) {
        LOGNOTE("Format recognized as CUE/BIN/ISO/TOAST");
        return load_cue_bin_iso_image(image_path);
    }
    else {
        LOGERR("Unrecognized image format: %s", image_path);
        return nullptr;
    }
}

#include <ymir/hw/sh1/sh1_decode.hpp>
#include <ymir/util/bit_ops.hpp>

namespace ymir::sh1 {

DecodeTable::DecodeTable() {
    // Initialize all entries as illegal first
    opcodes[0].assign(0x10000, OpcodeType::Illegal);
    opcodes[1].assign(0x10000, OpcodeType::Illegal);

    for (uint16 instruction = 0; instruction < 0x10000; ++instruction) {
        auto& regularOpcode = opcodes[0][instruction];
        auto& delaySlotOpcode = opcodes[1][instruction];
        auto& operandInfo = DecodeTable::args[instruction];
        auto& memoryAccess = DecodeTable::mem[instruction];

        // Helper lambdas for setting opcodes
        auto assignRegularAndDelay = [&](OpcodeType base) {
            constexpr uint16 delayBase = static_cast<uint16>(OpcodeType::Delay_NOP);
            regularOpcode = base;
            delaySlotOpcode = static_cast<OpcodeType>(static_cast<uint16>(base) + delayBase);
        };

        auto assignOnlyRegular = [&](OpcodeType base) {
            regularOpcode = base;
            delaySlotOpcode = OpcodeType::IllegalSlot;
        };

        // Operand extraction helpers
        auto extractRN8 = [&] { operandInfo.rn = bit::extract<8, 11>(instruction); };
        auto extractRM8 = [&] { operandInfo.rm = bit::extract<8, 11>(instruction); };
        auto extractRN4 = [&] { operandInfo.rn = bit::extract<4, 7>(instruction); };
        auto extractRM4 = [&] { operandInfo.rm = bit::extract<4, 7>(instruction); };

        auto setUDisp4 = [&](uint16 shift) {
            operandInfo.dispImm = static_cast<sint16>(bit::extract<0, 3>(instruction)) << shift;
        };

        auto setUDispImm8 = [&](uint16 shift, uint16 offset) {
            operandInfo.dispImm = (bit::extract<0, 7>(instruction) << shift) + offset;
        };

        auto setSDispImm8 = [&](sint16 shift, sint16 offset) {
            operandInfo.dispImm = (bit::extract_signed<0, 7>(instruction) << shift) + offset;
        };

        auto setSDisp12 = [&](sint16 shift, sint16 offset) {
            operandInfo.dispImm = (bit::extract_signed<0, 11>(instruction) << shift) + offset;
        };

        // Memory access helpers
        auto configureMemAtReg = [&](DecodedMemAccesses& access, uint8 size, bool write, uint8 reg) {
            access.type = DecodedMemAccesses::Type::AtReg;
            access.size = size;
            access.write = write;
            access.reg = reg;
        };

        auto configureMemAtDispReg = [&](DecodedMemAccesses& access, uint8 size, bool write, uint8 reg, sint16 disp) {
            access.type = DecodedMemAccesses::Type::AtDispReg;
            access.size = size;
            access.write = write;
            access.reg = reg;
            access.disp = disp;
        };

        auto configureMemAtR0Reg = [&](DecodedMemAccesses& access, uint8 size, bool write, uint8 reg) {
            access.type = DecodedMemAccesses::Type::AtR0Reg;
            access.size = size;
            access.write = write;
            access.reg = reg;
        };

        auto configureMemAtR0GBR = [&](DecodedMemAccesses& access, uint8 size, bool write) {
            access.type = DecodedMemAccesses::Type::AtR0GBR;
            access.size = size;
            access.write = write;
        };

        auto configureMemAtDispGBR = [&](DecodedMemAccesses& access, uint8 size, bool write, sint16 disp) {
            access.type = DecodedMemAccesses::Type::AtDispGBR;
            access.size = size;
            access.write = write;
            access.disp = disp;
        };

        auto configureMemAtDispPC = [&](DecodedMemAccesses& access, uint8 size, sint16 disp) {
            access.type = DecodedMemAccesses::Type::AtDispPC;
            access.size = size;
            access.write = true;
            access.disp = disp;
        };

        // Specific memory access configurations
        auto loadFromRm = [&](uint8 sz) {
            configureMemAtReg(memoryAccess.second, sz, false, bit::extract<4, 7>(instruction));
        };

        auto loadFromRn = [&](uint8 sz) {
            configureMemAtReg(memoryAccess.first, sz, false, bit::extract<8, 11>(instruction));
        };

        auto storeToRn = [&](uint8 sz) {
            configureMemAtReg(memoryAccess.second, sz, true, bit::extract<8, 11>(instruction));
        };

        auto storeMinusRn = [&](uint8 sz) {
            configureMemAtDispReg(memoryAccess.second, sz, true, bit::extract<8, 11>(instruction), -static_cast<sint16>(sz));
        };

        auto loadFromR0Rm = [&](uint8 sz) {
            configureMemAtR0Reg(memoryAccess.first, sz, false, bit::extract<4, 7>(instruction));
        };

        auto storeToR0Rn = [&](uint8 sz) {
            configureMemAtR0Reg(memoryAccess.second, sz, true, bit::extract<8, 11>(instruction));
        };

        auto loadFromR0GBR = [&](uint8 sz) {
            configureMemAtR0GBR(memoryAccess.first, sz, false);
        };

        auto storeToR0GBR = [&](uint8 sz) {
            configureMemAtR0GBR(memoryAccess.second, sz, true);
        };

        auto loadFromDispRm = [&](uint8 sz) {
            configureMemAtDispReg(memoryAccess.first, sz, false,
                bit::extract<4, 7>(instruction),
                bit::extract<0, 3>(instruction) * static_cast<sint16>(sz));
        };

        auto storeToDispRn = [&](uint8 sz) {
            configureMemAtDispReg(memoryAccess.second, sz, true,
                bit::extract<8, 11>(instruction),
                bit::extract<0, 3>(instruction) * static_cast<sint16>(sz));
        };

        auto storeToDispRn4 = [&](uint8 sz) {
            configureMemAtDispReg(memoryAccess.second, sz, true,
                bit::extract<4, 7>(instruction),
                bit::extract<0, 3>(instruction) * static_cast<sint16>(sz));
        };

        auto loadFromDispGBR = [&](uint8 sz) {
            configureMemAtDispGBR(memoryAccess.first, sz, false,
                bit::extract<0, 7>(instruction) * static_cast<sint16>(sz));
        };

        auto storeToDispGBR = [&](uint8 sz) {
            configureMemAtDispGBR(memoryAccess.second, sz, true,
                bit::extract<0, 7>(instruction) * static_cast<sint16>(sz));
        };

        auto loadFromDispPC = [&](uint8 sz) {
            configureMemAtDispPC(memoryAccess.first, sz,
                bit::extract<0, 7>(instruction) * static_cast<sint16>(sz) + 4);
        };

        // Size-specific wrappers
        #define WRAP_LOAD_RM(SZ, SUFFIX) auto loadRm##SUFFIX = [&] { loadFromRm(SZ); }
        #define WRAP_STORE_RN(SZ, SUFFIX) auto storeRn##SUFFIX = [&] { storeToRn(SZ); }
        #define WRAP_STORE_MINUS_RN(SZ, SUFFIX) auto storeMinusRn##SUFFIX = [&] { storeMinusRn(SZ); }
        #define WRAP_LOAD_R0RM(SZ, SUFFIX) auto loadR0Rm##SUFFIX = [&] { loadFromR0Rm(SZ); }
        #define WRAP_STORE_R0RN(SZ, SUFFIX) auto storeR0Rn##SUFFIX = [&] { storeToR0Rn(SZ); }
        #define WRAP_LOAD_DISP_RM(SZ, SUFFIX) auto loadDispRm##SUFFIX = [&] { loadFromDispRm(SZ); }
        #define WRAP_STORE_DISP_RN(SZ, SUFFIX) auto storeDispRn##SUFFIX = [&] { storeToDispRn4(SZ); }
        #define WRAP_LOAD_DISP_GBRSZ(SZ, SUFFIX) auto loadDispGBR##SUFFIX = [&] { loadFromDispGBR(SZ); }
        #define WRAP_STORE_DISP_GBRSZ(SZ, SUFFIX) auto storeDispGBR##SUFFIX = [&] { storeToDispGBR(SZ); }
        #define WRAP_LOAD_DISP_PC(SZ, SUFFIX) auto loadDispPC##SUFFIX = [&] { loadFromDispPC(SZ); }

        WRAP_LOAD_RM(sizeof(uint8), _B);
        WRAP_LOAD_RM(sizeof(uint16), _W);
        WRAP_LOAD_RM(sizeof(uint32), _L);
        WRAP_STORE_RN(sizeof(uint8), _B);
        WRAP_STORE_RN(sizeof(uint16), _W);
        WRAP_STORE_RN(sizeof(uint32), _L);
        WRAP_STORE_MINUS_RN(sizeof(uint8), _B);
        WRAP_STORE_MINUS_RN(sizeof(uint16), _W);
        WRAP_STORE_MINUS_RN(sizeof(uint32), _L);
        WRAP_LOAD_R0RM(sizeof(uint8), _B);
        WRAP_LOAD_R0RM(sizeof(uint16), _W);
        WRAP_LOAD_R0RM(sizeof(uint32), _L);
        WRAP_STORE_R0RN(sizeof(uint8), _B);
        WRAP_STORE_R0RN(sizeof(uint16), _W);
        WRAP_STORE_R0RN(sizeof(uint32), _L);
        WRAP_LOAD_DISP_RM(sizeof(uint8), _B);
        WRAP_LOAD_DISP_RM(sizeof(uint16), _W);
        WRAP_LOAD_DISP_RM(sizeof(uint32), _L);
        WRAP_STORE_DISP_RN(sizeof(uint8), _B);
        WRAP_STORE_DISP_RN(sizeof(uint16), _W);
        WRAP_STORE_DISP_RN(sizeof(uint32), _L);
        WRAP_LOAD_DISP_GBRSZ(sizeof(uint8), _B);
        WRAP_LOAD_DISP_GBRSZ(sizeof(uint16), _W);
        WRAP_LOAD_DISP_GBRSZ(sizeof(uint32), _L);
        WRAP_STORE_DISP_GBRSZ(sizeof(uint8), _B);
        WRAP_STORE_DISP_GBRSZ(sizeof(uint16), _W);
        WRAP_STORE_DISP_GBRSZ(sizeof(uint32), _L);
        WRAP_LOAD_DISP_PC(sizeof(uint16), _W);
        WRAP_LOAD_DISP_PC(sizeof(uint32), _L);

        #undef WRAP_LOAD_RM
        #undef WRAP_STORE_RN
        #undef WRAP_STORE_MINUS_RN
        #undef WRAP_LOAD_R0RM
        #undef WRAP_STORE_R0RN
        #undef WRAP_LOAD_DISP_RM
        #undef WRAP_STORE_DISP_RN
        #undef WRAP_LOAD_DISP_GBRSZ
        #undef WRAP_STORE_DISP_GBRSZ
        #undef WRAP_LOAD_DISP_PC

        // Operand combination helpers
        auto decodeN = [&] { extractRN8(); };
        auto decodeM = [&] { extractRM8(); };
        auto decodeNM = [&] { extractRN8(); extractRM4(); };
        auto decodeMD = [&](uint16 sh) { extractRM4(); setUDisp4(sh); };
        auto decodeND4 = [&](uint16 sh) { extractRN4(); setUDisp4(sh); };
        auto decodeNMD = [&](uint16 sh) { extractRN8(); extractRM4(); setUDisp4(sh); };
        auto decodeD_U = [&](uint16 sh, uint16 off) { setUDispImm8(sh, off); };
        auto decodeD_S = [&](sint16 sh, sint16 off) { setSDispImm8(sh, off); };
        auto decodeD12 = [&](sint16 sh, sint16 off) { setSDisp12(sh, off); };
        auto decodeND8 = [&](uint16 sh, uint16 off) { extractRN8(); setUDispImm8(sh, off); };
        auto decodeI_U = [&](uint16 sh, uint16 off) { setUDispImm8(sh, off); };
        auto decodeI_S = [&](sint16 sh, sint16 off) { setSDispImm8(sh, off); };
        auto decodeNI = [&](sint16 sh, sint16 off) { extractRN8(); setSDispImm8(sh, off); };

        // Main decoding logic
        const uint16 topNibble = instruction >> 12u;

        switch (topNibble) {
        case 0x0: {
            switch (instruction) {
            case 0x0008: assignRegularAndDelay(OpcodeType::CLRT); break;
            case 0x0009: assignRegularAndDelay(OpcodeType::NOP); break;
            case 0x000B: assignOnlyRegular(OpcodeType::RTS); break;
            case 0x0018: assignRegularAndDelay(OpcodeType::SETT); break;
            case 0x0019: assignRegularAndDelay(OpcodeType::DIV0U); break;
            case 0x001B: assignRegularAndDelay(OpcodeType::SLEEP); break;
            case 0x0028: assignRegularAndDelay(OpcodeType::CLRMAC); break;
            case 0x002B: assignOnlyRegular(OpcodeType::RTE); break;
            default: {
                const uint8 lowByte = instruction & 0xFF;
                switch (lowByte) {
                case 0x02: assignRegularAndDelay(OpcodeType::STC_SR_R); decodeN(); break;
                case 0x0A: assignRegularAndDelay(OpcodeType::STS_MACH_R); decodeN(); break;
                case 0x12: assignRegularAndDelay(OpcodeType::STC_GBR_R); decodeN(); break;
                case 0x1A: assignRegularAndDelay(OpcodeType::STS_MACL_R); decodeN(); break;
                case 0x22: assignRegularAndDelay(OpcodeType::STC_VBR_R); decodeN(); break;
                case 0x29: assignRegularAndDelay(OpcodeType::MOVT); decodeN(); break;
                case 0x2A: assignRegularAndDelay(OpcodeType::STS_PR_R); decodeN(); break;
                default: {
                    const uint8 lowNybble = instruction & 0xF;
                    switch (lowNybble) {
                    case 0x4: assignRegularAndDelay(OpcodeType::MOVB_S0); decodeNM(); storeR0Rn_B(); break;
                    case 0x5: assignRegularAndDelay(OpcodeType::MOVW_S0); decodeNM(); storeR0Rn_W(); break;
                    case 0x6: assignRegularAndDelay(OpcodeType::MOVL_S0); decodeNM(); storeR0Rn_L(); break;
                    case 0xC: assignRegularAndDelay(OpcodeType::MOVB_L0); decodeNM(); loadR0Rm_B(); break;
                    case 0xD: assignRegularAndDelay(OpcodeType::MOVW_L0); decodeNM(); loadR0Rm_W(); break;
                    case 0xE: assignRegularAndDelay(OpcodeType::MOVL_L0); decodeNM(); loadR0Rm_L(); break;
                    case 0xF: assignRegularAndDelay(OpcodeType::MACL); decodeNM(); loadFromRn(sizeof(uint16)); loadFromRm(sizeof(uint16)); break;
                    }
                    break;
                }
                }
                break;
            }
            }
            break;
        }

        case 0x1:
            assignRegularAndDelay(OpcodeType::MOVL_S4);
            decodeNMD(2u);
            storeDispRn_L();
            break;

        case 0x2: {
            const uint8 lowNybble = instruction & 0xF;
            switch (lowNybble) {
            case 0x0: assignRegularAndDelay(OpcodeType::MOVB_S); decodeNM(); storeRn_B(); break;
            case 0x1: assignRegularAndDelay(OpcodeType::MOVW_S); decodeNM(); storeRn_W(); break;
            case 0x2: assignRegularAndDelay(OpcodeType::MOVL_S); decodeNM(); storeRn_L(); break;
            case 0x4: assignRegularAndDelay(OpcodeType::MOVB_M); decodeNM(); storeMinusRn_B(); break;
            case 0x5: assignRegularAndDelay(OpcodeType::MOVW_M); decodeNM(); storeMinusRn_W(); break;
            case 0x6: assignRegularAndDelay(OpcodeType::MOVL_M); decodeNM(); storeMinusRn_L(); break;
            case 0x7: assignRegularAndDelay(OpcodeType::DIV0S); decodeNM(); break;
            case 0x8: assignRegularAndDelay(OpcodeType::TST_R); decodeNM(); break;
            case 0x9: assignRegularAndDelay(OpcodeType::AND_R); decodeNM(); break;
            case 0xA: assignRegularAndDelay(OpcodeType::XOR_R); decodeNM(); break;
            case 0xB: assignRegularAndDelay(OpcodeType::OR_R); decodeNM(); break;
            case 0xC: assignRegularAndDelay(OpcodeType::CMP_STR); decodeNM(); break;
            case 0xD: assignRegularAndDelay(OpcodeType::XTRCT); decodeNM(); break;
            case 0xE: assignRegularAndDelay(OpcodeType::MULU); decodeNM(); break;
            case 0xF: assignRegularAndDelay(OpcodeType::MULS); decodeNM(); break;
            }
            break;
        }

        case 0x3: {
            const uint8 lowNybble = instruction & 0xF;
            switch (lowNybble) {
            case 0x0: assignRegularAndDelay(OpcodeType::CMP_EQ_R); decodeNM(); break;
            case 0x2: assignRegularAndDelay(OpcodeType::CMP_HS); decodeNM(); break;
            case 0x3: assignRegularAndDelay(OpcodeType::CMP_GE); decodeNM(); break;
            case 0x4: assignRegularAndDelay(OpcodeType::DIV1); decodeNM(); break;
            case 0x6: assignRegularAndDelay(OpcodeType::CMP_HI); decodeNM(); break;
            case 0x7: assignRegularAndDelay(OpcodeType::CMP_GT); decodeNM(); break;
            case 0x8: assignRegularAndDelay(OpcodeType::SUB); decodeNM(); break;
            case 0xA: assignRegularAndDelay(OpcodeType::SUBC); decodeNM(); break;
            case 0xB: assignRegularAndDelay(OpcodeType::SUBV); decodeNM(); break;
            case 0xC: assignRegularAndDelay(OpcodeType::ADD); decodeNM(); break;
            case 0xE: assignRegularAndDelay(OpcodeType::ADDC); decodeNM(); break;
            case 0xF: assignRegularAndDelay(OpcodeType::ADDV); decodeNM(); break;
            }
            break;
        }

        case 0x4: {
            if ((instruction & 0xF) == 0xF) {
                assignRegularAndDelay(OpcodeType::MACW);
                decodeNM();
                loadFromRn(sizeof(uint16));
                loadFromRm(sizeof(uint16));
            } else {
                const uint8 subOp = instruction & 0xFF;
                switch (subOp) {
                case 0x00: assignRegularAndDelay(OpcodeType::SHLL); decodeN(); break;
                case 0x01: assignRegularAndDelay(OpcodeType::SHLR); decodeN(); break;
                case 0x02: assignRegularAndDelay(OpcodeType::STS_MACH_M); decodeN(); storeMinusRn_L(); break;
                case 0x03: assignRegularAndDelay(OpcodeType::STC_SR_M); decodeN(); storeMinusRn_L(); break;
                case 0x04: assignRegularAndDelay(OpcodeType::ROTL); decodeN(); break;
                case 0x05: assignRegularAndDelay(OpcodeType::ROTR); decodeN(); break;
                case 0x06: assignRegularAndDelay(OpcodeType::LDS_MACH_M); decodeM(); loadFromRm(sizeof(uint32)); break;
                case 0x07: assignRegularAndDelay(OpcodeType::LDC_SR_M); decodeM(); loadFromRm(sizeof(uint32)); break;
                case 0x08: assignRegularAndDelay(OpcodeType::SHLL2); decodeN(); break;
                case 0x09: assignRegularAndDelay(OpcodeType::SHLR2); decodeN(); break;
                case 0x0A: assignRegularAndDelay(OpcodeType::LDS_MACH_R); decodeM(); break;
                case 0x0B: assignOnlyRegular(OpcodeType::JSR); decodeM(); break;
                case 0x0E: assignRegularAndDelay(OpcodeType::LDC_SR_R); decodeM(); break;
                case 0x11: assignRegularAndDelay(OpcodeType::CMP_PZ); decodeN(); break;
                case 0x12: assignRegularAndDelay(OpcodeType::STS_MACL_M); decodeN(); storeMinusRn_L(); break;
                case 0x13: assignRegularAndDelay(OpcodeType::STC_GBR_M); decodeN(); storeMinusRn_L(); break;
                case 0x15: assignRegularAndDelay(OpcodeType::CMP_PL); decodeN(); break;
                case 0x16: assignRegularAndDelay(OpcodeType::LDS_MACL_M); decodeM(); loadFromRm(sizeof(uint32)); break;
                case 0x17: assignRegularAndDelay(OpcodeType::LDC_GBR_M); decodeM(); loadFromRm(sizeof(uint32)); break;
                case 0x18: assignRegularAndDelay(OpcodeType::SHLL8); decodeN(); break;
                case 0x19: assignRegularAndDelay(OpcodeType::SHLR8); decodeN(); break;
                case 0x1A: assignRegularAndDelay(OpcodeType::LDS_MACL_R); decodeM(); break;
                case 0x1B: assignRegularAndDelay(OpcodeType::TAS); decodeN(); loadFromRn(sizeof(uint8)); storeToRn(sizeof(uint8)); break;
                case 0x1E: assignRegularAndDelay(OpcodeType::LDC_GBR_R); decodeM(); break;
                case 0x20: assignRegularAndDelay(OpcodeType::SHAL); decodeN(); break;
                case 0x21: assignRegularAndDelay(OpcodeType::SHAR); decodeN(); break;
                case 0x22: assignRegularAndDelay(OpcodeType::STS_PR_M); decodeN(); storeMinusRn_L(); break;
                case 0x23: assignRegularAndDelay(OpcodeType::STC_VBR_M); decodeN(); storeMinusRn_L(); break;
                case 0x24: assignRegularAndDelay(OpcodeType::ROTCL); decodeN(); break;
                case 0x25: assignRegularAndDelay(OpcodeType::ROTCR); decodeN(); break;
                case 0x26: assignRegularAndDelay(OpcodeType::LDS_PR_M); decodeM(); loadFromRm(sizeof(uint32)); break;
                case 0x27: assignRegularAndDelay(OpcodeType::LDC_VBR_M); decodeM(); loadFromRm(sizeof(uint32)); break;
                case 0x28: assignRegularAndDelay(OpcodeType::SHLL16); decodeN(); break;
                case 0x29: assignRegularAndDelay(OpcodeType::SHLR16); decodeN(); break;
                case 0x2A: assignRegularAndDelay(OpcodeType::LDS_PR_R); decodeM(); break;
                case 0x2B: assignOnlyRegular(OpcodeType::JMP); decodeM(); break;
                case 0x2E: assignRegularAndDelay(OpcodeType::LDC_VBR_R); decodeM(); break;
                }
            }
            break;
        }

        case 0x5:
            assignRegularAndDelay(OpcodeType::MOVL_L4);
            decodeNMD(2u);
            loadDispRm_L();
            break;

        case 0x6: {
            const uint8 lowNybble = instruction & 0xF;
            switch (lowNybble) {
            case 0x0: assignRegularAndDelay(OpcodeType::MOVB_L); decodeNM(); loadRm_B(); break;
            case 0x1: assignRegularAndDelay(OpcodeType::MOVW_L); decodeNM(); loadRm_W(); break;
            case 0x2: assignRegularAndDelay(OpcodeType::MOVL_L); decodeNM(); loadRm_L(); break;
            case 0x3: assignRegularAndDelay(OpcodeType::MOV_R); decodeNM(); break;
            case 0x4: assignRegularAndDelay(OpcodeType::MOVB_P); decodeNM(); loadRm_B(); break;
            case 0x5: assignRegularAndDelay(OpcodeType::MOVW_P); decodeNM(); loadRm_W(); break;
            case 0x6: assignRegularAndDelay(OpcodeType::MOVL_P); decodeNM(); loadRm_L(); break;
            case 0x7: assignRegularAndDelay(OpcodeType::NOT); decodeNM(); break;
            case 0x8: assignRegularAndDelay(OpcodeType::SWAPB); decodeNM(); break;
            case 0x9: assignRegularAndDelay(OpcodeType::SWAPW); decodeNM(); break;
            case 0xA: assignRegularAndDelay(OpcodeType::NEGC); decodeNM(); break;
            case 0xB: assignRegularAndDelay(OpcodeType::NEG); decodeNM(); break;
            case 0xC: assignRegularAndDelay(OpcodeType::EXTUB); decodeNM(); break;
            case 0xD: assignRegularAndDelay(OpcodeType::EXTUW); decodeNM(); break;
            case 0xE: assignRegularAndDelay(OpcodeType::EXTSB); decodeNM(); break;
            case 0xF: assignRegularAndDelay(OpcodeType::EXTSW); decodeNM(); break;
            }
            break;
        }

        case 0x7:
            assignRegularAndDelay(OpcodeType::ADD_I);
            decodeNI(0, 0);
            break;

        case 0x8: {
            const uint8 secondNibble = (instruction >> 8) & 0xF;
            switch (secondNibble) {
            case 0x0: assignRegularAndDelay(OpcodeType::MOVB_S4); decodeND4(0u); storeDispRn_B(); break;
            case 0x1: assignRegularAndDelay(OpcodeType::MOVW_S4); decodeND4(1u); storeDispRn_W(); break;
            case 0x4: assignRegularAndDelay(OpcodeType::MOVB_L4); decodeMD(0u); loadDispRm_B(); break;
            case 0x5: assignRegularAndDelay(OpcodeType::MOVW_L4); decodeMD(1u); loadDispRm_W(); break;
            case 0x8: assignRegularAndDelay(OpcodeType::CMP_EQ_I); decodeI_S(0, 0); break;
            case 0x9: assignOnlyRegular(OpcodeType::BT); decodeD_S(1, 4); break;
            case 0xB: assignOnlyRegular(OpcodeType::BF); decodeD_S(1, 4); break;
            case 0xD: assignOnlyRegular(OpcodeType::BTS); decodeD_S(1, 4); break;
            case 0xF: assignOnlyRegular(OpcodeType::BFS); decodeD_S(1, 4); break;
            }
            break;
        }

        case 0x9:
            assignRegularAndDelay(OpcodeType::MOVW_I);
            decodeND8(1u, 4u);
            loadDispPC_W();
            break;

        case 0xA:
            assignOnlyRegular(OpcodeType::BRA);
            decodeD12(1, 4);
            break;

        case 0xB:
            assignOnlyRegular(OpcodeType::BSR);
            decodeD12(1, 4);
            break;

        case 0xC: {
            const uint8 secondNibble = (instruction >> 8) & 0xF;
            switch (secondNibble) {
            case 0x0: assignRegularAndDelay(OpcodeType::MOVB_SG); decodeD_U(0u, 0u); storeDispGBR_B(); break;
            case 0x1: assignRegularAndDelay(OpcodeType::MOVW_SG); decodeD_U(1u, 0u); storeDispGBR_W(); break;
            case 0x2: assignRegularAndDelay(OpcodeType::MOVL_SG); decodeD_U(2u, 0u); storeDispGBR_L(); break;
            case 0x3: assignOnlyRegular(OpcodeType::TRAPA); decodeI_U(2u, 0u); break;
            case 0x4: assignRegularAndDelay(OpcodeType::MOVB_LG); decodeD_U(0u, 0u); loadDispGBR_B(); break;
            case 0x5: assignRegularAndDelay(OpcodeType::MOVW_LG); decodeD_U(1u, 0u); loadDispGBR_W(); break;
            case 0x6: assignRegularAndDelay(OpcodeType::MOVL_LG); decodeD_U(2u, 0u); loadDispGBR_L(); break;
            case 0x7: assignRegularAndDelay(OpcodeType::MOVA); decodeD_U(2u, 4u); break;
            case 0x8: assignRegularAndDelay(OpcodeType::TST_I); decodeI_U(0u, 0u); break;
            case 0x9: assignRegularAndDelay(OpcodeType::AND_I); decodeI_U(0u, 0u); break;
            case 0xA: assignRegularAndDelay(OpcodeType::XOR_I); decodeI_U(0u, 0u); break;
            case 0xB: assignRegularAndDelay(OpcodeType::OR_I); decodeI_U(0u, 0u); break;
            case 0xC: assignRegularAndDelay(OpcodeType::TST_M); decodeI_U(0u, 0u); loadFromR0GBR(sizeof(uint8)); storeToR0GBR(sizeof(uint8)); break;
            case 0xD: assignRegularAndDelay(OpcodeType::AND_M); decodeI_U(0u, 0u); loadFromR0GBR(sizeof(uint8)); storeToR0GBR(sizeof(uint8)); break;
            case 0xE: assignRegularAndDelay(OpcodeType::XOR_M); decodeI_U(0u, 0u); loadFromR0GBR(sizeof(uint8)); storeToR0GBR(sizeof(uint8)); break;
            case 0xF: assignRegularAndDelay(OpcodeType::OR_M); decodeI_U(0u, 0u); loadFromR0GBR(sizeof(uint8)); storeToR0GBR(sizeof(uint8)); break;
            }
            break;
        }

        case 0xD:
            assignRegularAndDelay(OpcodeType::MOVL_I);
            decodeND8(2u, 4u);
            loadDispPC_L();
            break;

        case 0xE:
            assignRegularAndDelay(OpcodeType::MOV_I);
            decodeNI(0, 0);
            break;

        default:
            // Should never reach here due to 16-bit range coverage
            break;
        }
    }
}

DecodeTable DecodeTable::s_instance{};

