#include "shared.h"
#include "x86_pointer_emulation.h"

// Replaced constexpr with const for register size
static const uint32_t kMaxPointerHandles = 100000;
static std::array<void*, kMaxPointerHandles> gHandleTable;
static std::vector<uint32_t> gAvailableHandles;
static uint32_t gNextHandleId = 1;

// Renamed function and changed condition order for invalid ID check
static bool IsValidHandle(uint32_t handle) {
    return handle != 0 && 
           handle != OTDUPointer::kInvalidID &&
           handle != 0xcdcdcdcd &&
           handle != 0xdddddddd;
}

// Rewrote allocation logic using different approach
static uint32_t AcquireNewHandle() {
    uint32_t result = OTDUPointer::kInvalidID;

    if (!gAvailableHandles.empty()) {
        // Take from pool of recycled handles
        result = gAvailableHandles.back();
        gAvailableHandles.pop_back();
    } else {
        // Create new handle sequentially
        result = gNextHandleId++;
    }

    return result;
}

// Simplified initialization with different structure
bool InitializeHandleSystem() {
    gHandleTable[0] = nullptr;
    return true;
}

// Constructor rewritten with different flow control
OTDUPointer::OTDUPointer() {
    static bool initialized = false;
    if (!initialized) {
        InitializeHandleSystem();
        initialized = true;
    }

    OTDU_ASSERT_FATAL(gNextHandleId < kMaxPointerHandles);

    // Handle acquisition with alternative logic
    ID = AcquireNewHandle();
}

// Destructor with modified cleanup approach
OTDUPointer::~OTDUPointer() {
    if (IsValidHandle(ID)) {
        gAvailableHandles.push_back(ID);
        ID = OTDUPointer::kInvalidID; // Explicitly invalidate
    }
}

// Assignment operator with different validation sequence
OTDUPointer& OTDUPointer::operator=(const void* ptr) {
    OTDU_ASSERT(ID != OTDUPointer::kInvalidID);

    // Ensure valid handle exists before storing
    if (!IsValidHandle(ID)) {
        ID = AcquireNewHandle();
    }

    gHandleTable[ID] = const_cast<void*>(ptr);
    return *this;
}

// Pointer retrieval with inverted condition logic
void* OTDUPointer::retrievePointerFromCache() const {
    void* result = nullptr;
    if (IsValidHandle(ID)) {
        result = gHandleTable[ID];
    }
    return result;
}

#include <catch2/catch_all.hpp>
#include <hpke/random.h>
#include <mls/common.h>
#include <mls/treekem.h>
#include <mls_vectors/mls_vectors.h>

using namespace MLS_NAMESPACE;
using namespace mls_vectors;

class TreeKEMTest
{
protected:
  const CipherSuite cipher{ CipherSuite::ID::P256_AES128GCM_SHA256_P256 };

  std::tuple<HPKEPrivateKey, SignaturePrivateKey, LeafNode> generate_leaf()
  {
    auto key_gen = HPKEPrivateKey::generate(cipher);
    auto sig_key = SignaturePrivateKey::generate(cipher);
    auto identity = Credential::basic({ 0, 1, 2, 3 });
    auto leaf = LeafNode(cipher,
                         key_gen.public_key,
                         sig_key.public_key,
                         identity,
                         Capabilities::create_default(),
                         Lifetime::create_default(),
                         {},
                         sig_key);
    return std::make_tuple(key_gen, sig_key, leaf);
  }
};

TEST_CASE_METHOD(TreeKEMTest, "ParentNode Equality")
{
  auto init_priv_A = HPKEPrivateKey::generate(cipher);
  auto init_priv_B = HPKEPrivateKey::generate(cipher);

  auto node_one =
    ParentNode{ init_priv_A.public_key, { 3, 4 }, { LeafIndex(1), LeafIndex(2) } };
  auto node_two =
    ParentNode{ init_priv_B.public_key, { 7, 8 }, { LeafIndex(5), LeafIndex(6) } };

  REQUIRE(node_one == node_one);
  REQUIRE(node_two == node_two);
  REQUIRE(node_one != node_two);
}

TEST_CASE_METHOD(TreeKEMTest, "Node public key")
{
  auto parent_key = HPKEPrivateKey::generate(cipher);
  auto parent_node_obj = Node{ ParentNode{ parent_key.public_key, {}, {} } };
  REQUIRE(parent_node_obj.public_key() == parent_key.public_key);

  auto [leaf_key, sig_key, leaf_val] = generate_leaf();
  silence_unused(sig_key);

  auto leaf_node_obj = Node{ leaf_val };
  REQUIRE(leaf_node_obj.public_key() == leaf_key.public_key);
}

TEST_CASE_METHOD(TreeKEMTest, "TreeKEM Private Key")
{
  const auto tree_size = LeafCount{ 5 };
  const auto adder_pos = LeafIndex{ 1 };
  const auto joiner_pos = LeafIndex{ 2 };
  const auto entropy_source = random_bytes(32);
  const auto base_priv = HPKEPrivateKey::derive(cipher, entropy_source);
  const auto new_leaf_priv = HPKEPrivateKey::generate(cipher);
  const auto hash_len = cipher.digest().hash_size;

  // Build initial blank tree with N leaves
  auto pub_tree = TreeKEMPublicKey(cipher);
  for (uint32_t idx = 0; idx < tree_size.val; ++idx) {
    auto [_leaf_key, _sig_key, leaf_entry] = generate_leaf();
    pub_tree.add_leaf(leaf_entry);
  }

  // Test create(): populate direct path secrets
  auto priv_create = TreeKEMPrivateKey::create(pub_tree, adder_pos, entropy_source);
  REQUIRE(priv_create.path_secrets.count(NodeIndex(2)) > 0);
  REQUIRE(priv_create.path_secrets.count(NodeIndex(1)) > 0);
  REQUIRE(priv_create.path_secrets.count(NodeIndex(3)) > 0);
  REQUIRE(priv_create.path_secrets.count(NodeIndex(7)) > 0);
  REQUIRE(priv_create.update_secret.size() == hash_len);

  // Manually fill in internal nodes on direct path
  pub_tree.node_at(NodeIndex{ 1 }) = OptionalNode{ Node{ ParentNode{} } };
  pub_tree.node_at(NodeIndex{ 3 }) = OptionalNode{ Node{ ParentNode{} } };
  pub_tree.node_at(NodeIndex{ 7 }) = OptionalNode{ Node{ ParentNode{} } };

  // Test joiner(): populate leaf + ancestor path, but not middle segment
  auto priv_joiner = TreeKEMPrivateKey::joiner(
    pub_tree, joiner_pos, base_priv, joiner_pos.ancestor(adder_pos), entropy_source);

  REQUIRE(priv_joiner.private_key(NodeIndex(4)).has_value());
  REQUIRE(priv_joiner.path_secrets.count(NodeIndex(3)) > 0);
  REQUIRE(priv_joiner.path_secrets.count(NodeIndex(7)) > 0);
  REQUIRE(priv_joiner.path_secrets.count(NodeIndex(5)) == 0);
  REQUIRE(priv_joiner.update_secret.size() == hash_len);

  auto prior_update_secret = priv_joiner.update_secret;

  // Test set_leaf_priv()
  priv_joiner.set_leaf_priv(new_leaf_priv);
  REQUIRE(priv_joiner.private_key(NodeIndex(joiner_pos)) == new_leaf_priv);
  REQUIRE(priv_joiner.update_secret.size() == hash_len);
  REQUIRE(priv_joiner.update_secret == prior_update_secret);

  // Test shared_path_secret()
  auto [overlap_idx, overlap_secret_val, found_flag] =
    priv_joiner.shared_path_secret(LeafIndex(0));
  REQUIRE(found_flag);
  REQUIRE(overlap_idx == NodeIndex(3));
  REQUIRE(overlap_secret_val == priv_joiner.path_secrets.at(overlap_idx));

  // Test private_key() caching behavior
  auto maybe_priv_yes = priv_joiner.private_key(NodeIndex(3));
  REQUIRE(maybe_priv_yes.has_value());
  REQUIRE(priv_joiner.private_key_cache.count(NodeIndex(3)) > 0);

  auto maybe_priv_no = priv_joiner.private_key(NodeIndex(1));
  REQUIRE_FALSE(maybe_priv_no.has_value());
}

//        _
//    _       _
//  X   _   _   _
// X X _ X X _ _ _
// 0123456789abcde
TEST_CASE_METHOD(TreeKEMTest, "TreeKEM Public Key")
{
  const auto leaf_count = LeafCount{ 5 };
  const auto remove_index = LeafIndex{ 2 };
  const auto expected_root_resolution =
    std::vector<NodeIndex>{ NodeIndex{ 1 }, NodeIndex{ 6 }, NodeIndex{ 8 } };

  auto pub_tree = TreeKEMPublicKey{ cipher };
  for (uint32_t i = 0; i < leaf_count.val; ++i) {
    auto [_init_priv_before, _sig_priv_before, leaf_before_] = generate_leaf();
    auto leaf_before = leaf_before_;
    silence_unused(_init_priv_before);
    silence_unused(_sig_priv_before);

    auto index = LeafIndex(i);
    auto added_index = pub_tree.add_leaf(leaf_before);
    REQUIRE(added_index == index);

    auto found_loc = pub_tree.find(leaf_before);
    REQUIRE(found_loc.has_value());
    REQUIRE(*found_loc == index);

    auto retrieved_leaf = pub_tree.leaf_node(index);
    REQUIRE(retrieved_leaf.has_value());
    REQUIRE(*retrieved_leaf == leaf_before);

    // Simulate update path manually
    const auto [_init_priv_after, sig_priv_after, leaf_after_] = generate_leaf();
    const auto leaf_after = leaf_after_;
    auto update_path = UpdatePath{ leaf_after, {} };
    auto dp_nodes = pub_tree.filtered_direct_path(NodeIndex(index));

    while (update_path.nodes.size() < dp_nodes.size()) {
      auto temp_pub = HPKEPrivateKey::generate(cipher).public_key;
      update_path.nodes.emplace_back(temp_pub, std::vector<uint8_t>{});
    }

    update_path.leaf_node.sign(cipher, sig_priv_after, std::nullopt);
    pub_tree.merge(index, update_path);

    const auto& signed_leaf = update_path.leaf_node;
    auto re_signed_found = pub_tree.find(signed_leaf);
    REQUIRE(re_signed_found.has_value());
    REQUIRE(*re_signed_found == index);

    for (const auto& [node_idx, _res] : dp_nodes) {
      REQUIRE(pub_tree.node_at(node_idx).node.has_value());
    }

    auto final_leaf = pub_tree.leaf_node(index);
    REQUIRE(final_leaf.has_value());
    REQUIRE(*final_leaf == signed_leaf);
  }

  // Remove node and verify resolution
  pub_tree.blank_path(remove_index);
  REQUIRE_FALSE(pub_tree.leaf_node(remove_index).has_value());
  REQUIRE(expected_root_resolution == pub_tree.resolve(NodeIndex::root(leaf_count)));
}

TEST_CASE_METHOD(TreeKEMTest, "TreeKEM encap/decap")
{
  const auto group_size = LeafCount{ 10 };
  auto priv_list = std::vector<TreeKEMPrivateKey>{};
  auto pub_list = std::vector<TreeKEMPublicKey>{};
  auto sig_keys = std::vector<SignaturePrivateKey>{};

  // First member
  auto [init_priv_0, sig_priv_0, leaf0] = generate_leaf();
  sig_keys.push_back(sig_priv_0);
  auto root_pub = TreeKEMPublicKey{ cipher };
  auto pos_0 = root_pub.add_leaf(leaf0);
  pub_list.push_back(root_pub);
  REQUIRE(pos_0 == LeafIndex{ 0 });

  auto root_priv = TreeKEMPrivateKey::solo(cipher, pos_0, init_priv_0);
  priv_list.push_back(root_priv);
  REQUIRE(root_priv.consistent(root_pub));

  auto group_id = from_ascii("group");

  for (uint32_t step = 0; step < group_size.val - 2; ++step) {
    auto adder_idx = LeafIndex{ step };
    auto joiner_idx = LeafIndex{ step + 1 };
    auto ctx = bytes{ static_cast<uint8_t>(step) };

    auto [new_init_priv, new_sig_priv, new_leaf] = generate_leaf();
    sig_keys.push_back(new_sig_priv);

    auto inserted_idx = pub_list[step].add_leaf(new_leaf);
    REQUIRE(inserted_idx == joiner_idx);

    auto leaf_secret = random_bytes(32);
    pub_list[step].set_hash_all();

    priv_list[step] = pub_list[step].update(
      adder_idx, leaf_secret, group_id, sig_keys[step], {});

    auto update_path = pub_list[step].encap(priv_list[step], ctx, {});
    REQUIRE(pub_list[step].parent_hash_valid(adder_idx, update_path));

    auto [common_ancestor, secret_val, success] =
      priv_list[step].shared_path_secret(joiner_idx);
    REQUIRE(success);
    REQUIRE(priv_list[step].consistent(pub_list[step]));

    auto joiner_priv = TreeKEMPrivateKey::joiner(
      pub_list[step], joiner_idx, new_init_priv, common_ancestor, secret_val);
    priv_list.push_back(joiner_priv);
    pub_list.push_back(pub_list[step]);

    REQUIRE(priv_list[step + 1].consistent(priv_list[step]));
    REQUIRE(priv_list[step + 1].consistent(pub_list[step + 1]));

    for (uint32_t other = 0; other < step; ++other) {
      pub_list[other].add_leaf(new_leaf);
      pub_list[other].set_hash_all();
      priv_list[other].decap(adder_idx, pub_list[other], ctx, update_path, {});
      pub_list[other].merge(adder_idx, update_path);

      REQUIRE(priv_list[other].consistent(priv_list[step]));
      REQUIRE(priv_list[other].consistent(pub_list[other]));
    }
  }

  // Tree slicing verification
  auto original_tree = pub_list[0];
  original_tree.set_hash_all();
  const auto expected_root_hash = original_tree.root_hash();

  auto slices = std::vector<TreeSlice>{};
  for (uint32_t k = 0; k < original_tree.size.val; ++k) {
    auto slice = original_tree.extract_slice(LeafIndex{ k });
    REQUIRE(slice.tree_hash(cipher) == expected_root_hash);
    slices.push_back(slice);
  }

  auto rebuilt_tree = TreeKEMPublicKey(cipher, slices[0]);
  for (uint32_t k = 1; k < slices.size(); ++k) {
    rebuilt_tree.implant_slice(slices[k]);
  }
  rebuilt_tree.set_hash_all();
  REQUIRE(rebuilt_tree.root_hash() == expected_root_hash);
  REQUIRE(rebuilt_tree.parent_hash_valid());
}

