#include "tstencilcontrol.h"
#include "tgl.h"
#include "tthreadmessage.h"
#include <vector>
#include <QThreadStorage>

namespace {
// Singleton manager for stencil controls per thread
class StencilManager {
  QThreadStorage<TStencilControl*> m_tls;
  StencilManager() = default;

public:
  static StencilManager& get() {
    static StencilManager instance;
    return instance;
  }

  TStencilControl* activeControl() {
    if (!m_tls.hasLocalData()) {
      m_tls.setLocalData(new TStencilControl);
    }
    return m_tls.localData();
  }
};
} // anonymous namespace

class TStencilControl::Imp {
public:
  int m_bitDepth;              // number of available stencil bits
  int m_depthLevel;            // current nesting level of masks
  int m_activePlaneIndex;      // currently written plane (-1 if none)
  int m_modeState;             // 0: closed/disabled, 1: enabled, 2: open

#ifdef _DEBUG
  std::vector<bool> m_history; // tracks previous states instead of stack
#endif

  unsigned char m_writeMask;         // which planes are being written to
  unsigned char m_screenWriteMask;   // which planes also draw to color buffer
  unsigned char m_enabledMask;       // which planes are currently active
  unsigned char m_insideMask;        // inside/outside selection per plane
  unsigned char m_singleDrawMask;    // whether to draw only once per plane

  Imp();
  void syncGLState();
  void enterMask(DrawMode mode);
  void exitMask();
  void activateMask(MaskType type);
  void deactivateMask();
  void pushLayer();
  void popLayer();

private:
  bool isPlaneActive(int idx) const { return (m_writeMask & (1 << idx)) != 0; }
  void clearCurrentPlane();
};

TStencilControl::Imp::Imp()
    : m_bitDepth(0), m_depthLevel(1), m_activePlaneIndex(-1),
      m_modeState(0), m_writeMask(0), m_screenWriteMask(0),
      m_enabledMask(0), m_insideMask(0), m_singleDrawMask(0) {
  glGetIntegerv(GL_STENCIL_BITS, &m_bitDepth);
  glStencilMask(~0u);
  glClear(GL_STENCIL_BUFFER_BIT);
}

TStencilControl* TStencilControl::instance() {
  return StencilManager::get().activeControl();
}

TStencilControl::TStencilControl() : m_imp(std::make_unique<Imp>()) {}
TStencilControl::~TStencilControl() = default;

void TStencilControl::Imp::syncGLState() {
  if (m_activePlaneIndex >= 0) {
    unsigned char planeBit = 1u << m_activePlaneIndex;
    bool oneShot = (planeBit & m_singleDrawMask) != 0;

    if (planeBit & m_screenWriteMask) {
      int prevPlane = m_activePlaneIndex - 1;
      for (; prevPlane >= 0; --prevPlane) {
        unsigned char prevBit = 1u << prevPlane;
        if (isPlaneActive(prevPlane)) break;
      }

      if (prevPlane < 0) {
        if (oneShot)
          m_enabledMask |= planeBit;
        else
          m_enabledMask &= ~planeBit;
      } else {
        tglMultColorMask(0, 0, 0, 0);
        oneShot = false;
        planeBit |= (1u << prevPlane);
      }
    } else {
      tglMultColorMask(0, 0, 0, 0);
    }

    glStencilMask(planeBit);

    if (oneShot) {
      glStencilFunc(GL_EQUAL, m_insideMask, m_enabledMask);
      glStencilOp(GL_KEEP, GL_INVERT, GL_INVERT);
    } else {
      glStencilFunc(GL_EQUAL, planeBit | m_insideMask, m_enabledMask);
      glStencilOp(GL_KEEP, GL_REPLACE, GL_REPLACE);
    }
  } else {
    glStencilMask(~0u);
    glStencilFunc(GL_EQUAL, m_insideMask, m_enabledMask);
    glStencilOp(GL_KEEP, GL_KEEP, GL_KEEP);
  }

  if (!m_enabledMask && m_activePlaneIndex < 0)
    glDisable(GL_STENCIL_TEST);
  else
    glEnable(GL_STENCIL_TEST);
}

void TStencilControl::Imp::pushLayer() {
  ++m_depthLevel;
}

void TStencilControl::Imp::popLayer() {
  --m_depthLevel;
  assert(m_depthLevel > 0);
}

void TStencilControl::Imp::clearCurrentPlane() {
  glClear(GL_STENCIL_BUFFER_BIT);
}

void TStencilControl::Imp::enterMask(DrawMode mode) {
  m_activePlaneIndex = m_depthLevel - 1;
  unsigned char mask = 1u << m_activePlaneIndex;

  m_writeMask |= mask;

  switch (mode) {
  case DRAW_ALSO_ON_SCREEN:
    m_screenWriteMask |= mask;
    break;
  case DRAW_ON_SCREEN_ONLY_ONCE:
    m_screenWriteMask |= mask;
    m_singleDrawMask |= mask;
    break;
  default:
    m_screenWriteMask &= ~mask;
    m_singleDrawMask &= ~mask;
  }

  glEnable(GL_STENCIL_TEST);
  glStencilMask(mask);
  clearCurrentPlane();
  syncGLState();
}

void TStencilControl::Imp::exitMask() {
  assert(m_depthLevel - 1 == m_activePlaneIndex);
  unsigned char mask = 1u << (m_depthLevel - 1);

  m_writeMask &= ~mask;
  m_enabledMask &= ~mask;
  m_screenWriteMask &= ~mask;
  m_singleDrawMask &= ~mask;

  m_activePlaneIndex = -1;
  for (int i = m_depthLevel - 2; i >= 0; --i) {
    if (isPlaneActive(i)) {
      m_activePlaneIndex = i;
      break;
    }
  }

  syncGLState();
}

void TStencilControl::Imp::activateMask(MaskType type) {
  unsigned char mask = 1u << (m_depthLevel - 1);

  if (!(m_enabledMask & mask))
    glPushAttrib(GL_ALL_ATTRIB_BITS);

  m_enabledMask |= mask;

  assert(type == SHOW_INSIDE || type == SHOW_OUTSIDE);
  if (type == SHOW_INSIDE)
    m_insideMask |= mask;
  else
    m_insideMask &= ~mask;

  syncGLState();
}

void TStencilControl::Imp::deactivateMask() {
  unsigned char mask = 1u << (m_depthLevel - 1);
  m_enabledMask &= ~mask;
  m_insideMask &= ~mask;
  syncGLState();
  glPopAttrib();
}

void TStencilControl::beginMask(DrawMode mode) {
  glPushAttrib(GL_ALL_ATTRIB_BITS);

  if (m_imp->m_modeState) {
#ifdef _DEBUG
    m_imp->m_history.push_back(m_imp->m_modeState == 2);
#endif
    m_imp->pushLayer();
  }

  m_imp->m_modeState = 2; // open

  if (m_imp->m_depthLevel <= m_imp->m_bitDepth)
    m_imp->enterMask(mode);
}

void TStencilControl::endMask() {
  if (!m_imp->m_modeState) {
    m_imp->popLayer();
#ifdef _DEBUG
    assert(!m_imp->m_history.empty());
    assert(m_imp->m_history.back()); // last state must have been open
    m_imp->m_history.pop_back();
#endif
  }

  assert(m_imp->m_modeState != 1); // cannot end an enabled-only mask
  m_imp->m_modeState = 0; // closed & disabled

  if (m_imp->m_depthLevel <= m_imp->m_bitDepth)
    m_imp->exitMask();

  glPopAttrib();
}

void TStencilControl::enableMask(MaskType type) {
  assert(m_imp->m_modeState != 2); // cannot enable an open mask
  m_imp->m_modeState = 1; // enabled

  if (m_imp->m_depthLevel <= m_imp->m_bitDepth)
    m_imp->activateMask(type);
}

void TStencilControl::disableMask() {
  assert(m_imp->m_modeState != 2); // cannot disable an open mask

  if (!m_imp->m_modeState) {
    m_imp->popLayer();
#ifdef _DEBUG
    assert(!m_imp->m_history.empty());
    assert(!m_imp->m_history.back()); // last state must have been enabled
    m_imp->m_history.pop_back();
#endif
  }

  m_imp->m_modeState = 0; // closed & disabled

  if (m_imp->m_depthLevel <= m_imp->m_bitDepth)
    m_imp->deactivateMask();
}

#include "clipper2/clipper.h"
#include "clipper2/clipper.rectclip.h"

namespace Clipper2Lib {

  //------------------------------------------------------------------------------
  // Helper functions for geometric operations
  //------------------------------------------------------------------------------

  inline bool PathContainsPath(const Path64& outer, const Path64& inner) {
    int containmentCounter = 0;
    // Assume no significant overlap between paths
    for (const Point64& point : inner) {
      PointInPolygonResult result = PointInPolygon(point, outer);
      if (result == PointInPolygonResult::IsOutside) ++containmentCounter;
      else if (result == PointInPolygonResult::IsInside) --containmentCounter;
      else continue; // On boundary or undefined

      if (std::abs(containmentCounter) > 1) break;
    }
    return containmentCounter <= 0;
  }

  inline bool DeterminePointLocation(const Rect64& rectangle,
                                      const Point64& point, Location& location) {
    // Check boundary conditions first
    if (point.x == rectangle.left && point.y >= rectangle.top && point.y <= rectangle.bottom) {
      location = Location::Left;
      return false;
    }
    else if (point.x == rectangle.right && point.y >= rectangle.top && point.y <= rectangle.bottom) {
      location = Location::Right;
      return false;
    }
    else if (point.y == rectangle.top && point.x >= rectangle.left && point.x <= rectangle.right) {
      location = Location::Top;
      return false;
    }
    else if (point.y == rectangle.bottom && point.x >= rectangle.left && point.x <= rectangle.right) {
      location = Location::Bottom;
      return false;
    }

    // Determine relative position to rectangle
    if (point.x < rectangle.left) location = Location::Left;
    else if (point.x > rectangle.right) location = Location::Right;
    else if (point.y < rectangle.top) location = Location::Top;
    else if (point.y > rectangle.bottom) location = Location::Bottom;
    else location = Location::Inside;

    return (location != Location::Inside);
  }

  inline bool ArePointsHorizontal(const Point64& pt1, const Point64& pt2) {
    return pt1.y == pt2.y;
  }

  bool ComputeSegmentIntersection(const Point64& seg1Start,
                                  const Point64& seg1End,
                                  const Point64& seg2Start,
                                  const Point64& seg2End,
                                  Point64& intersectionPoint) {
    int sign1 = CrossProductSign(seg1Start, seg2Start, seg2End);
    int sign2 = CrossProductSign(seg1End, seg2Start, seg2End);

    if (sign1 == 0) {
      intersectionPoint = seg1Start;
      if (sign2 == 0) return false; // Collinear segments
      else if (seg1Start == seg2Start || seg1Start == seg2End) return true;
      else if (ArePointsHorizontal(seg2Start, seg2End)) 
        return ((seg1Start.x > seg2Start.x) == (seg1Start.x < seg2End.x));
      else 
        return ((seg1Start.y > seg2Start.y) == (seg1Start.y < seg2End.y));
    }
    else if (sign2 == 0) {
      intersectionPoint = seg1End;
      if (seg1End == seg2Start || seg1End == seg2End) return true;
      else if (ArePointsHorizontal(seg2Start, seg2End)) 
        return ((seg1End.x > seg2Start.x) == (seg1End.x < seg2End.x));
      else 
        return ((seg1End.y > seg2Start.y) == (seg1End.y < seg2End.y));
    }

    if ((sign1 > 0) == (sign2 > 0)) return false;

    int sign3 = CrossProductSign(seg2Start, seg1Start, seg1End);
    int sign4 = CrossProductSign(seg2End, seg1Start, seg1End);

    if (sign3 == 0) {
      intersectionPoint = seg2Start;
      if (seg2Start == seg1Start || seg2Start == seg1End) return true;
      else if (ArePointsHorizontal(seg1Start, seg1End)) 
        return ((seg2Start.x > seg1Start.x) == (seg2Start.x < seg1End.x));
      else 
        return ((seg2Start.y > seg1Start.y) == (seg2Start.y < seg1End.y));
    }
    else if (sign4 == 0) {
      intersectionPoint = seg2End;
      if (seg2End == seg1Start || seg2End == seg1End) return true;
      else if (ArePointsHorizontal(seg1Start, seg1End)) 
        return ((seg2End.x > seg1Start.x) == (seg2End.x < seg1End.x));
      else 
        return ((seg2End.y > seg1Start.y) == (seg2End.y < seg1End.y));
    }

    if ((sign3 > 0) == (sign4 > 0)) return false;

    // Segments intersect - compute actual intersection point
    return GetLineIntersectPt(seg1Start, seg1End, seg2Start, seg2End, intersectionPoint);
  }

  inline bool FindIntersectionWithRectBoundary(const Path64& rectPath,
                                               const Point64& startPoint,
                                               const Point64& endPoint,
                                               Location& currentLoc,
                                               Point64& intersectionPoint) {
    // Find the closest intersection point with rectangle boundaries
    switch (currentLoc) {
      case Location::Left:
        if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[3], intersectionPoint))
          return true;
        else if ((startPoint.y < rectPath[0].y) && 
                 ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[1], intersectionPoint)) {
          currentLoc = Location::Top;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[2], rectPath[3], intersectionPoint)) {
          currentLoc = Location::Bottom;
          return true;
        }
        return false;

      case Location::Top:
        if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[1], intersectionPoint))
          return true;
        else if ((startPoint.x < rectPath[0].x) && 
                 ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[3], intersectionPoint)) {
          currentLoc = Location::Left;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[1], rectPath[2], intersectionPoint)) {
          currentLoc = Location::Right;
          return true;
        }
        return false;

      case Location::Right:
        if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[1], rectPath[2], intersectionPoint))
          return true;
        else if ((startPoint.y < rectPath[1].y) && 
                 ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[1], intersectionPoint)) {
          currentLoc = Location::Top;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[2], rectPath[3], intersectionPoint)) {
          currentLoc = Location::Bottom;
          return true;
        }
        return false;

      case Location::Bottom:
        if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[2], rectPath[3], intersectionPoint))
          return true;
        else if ((startPoint.x < rectPath[3].x) && 
                 ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[3], intersectionPoint)) {
          currentLoc = Location::Left;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[1], rectPath[2], intersectionPoint)) {
          currentLoc = Location::Right;
          return true;
        }
        return false;

      default: // Inside
        if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[3], intersectionPoint)) {
          currentLoc = Location::Left;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[0], rectPath[1], intersectionPoint)) {
          currentLoc = Location::Top;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[1], rectPath[2], intersectionPoint)) {
          currentLoc = Location::Right;
          return true;
        }
        else if (ComputeSegmentIntersection(startPoint, endPoint, rectPath[2], rectPath[3], intersectionPoint)) {
          currentLoc = Location::Bottom;
          return true;
        }
        return false;
    }
  }

  inline Location NextClockwiseLocation(Location current, bool clockwise) {
    int offset = (clockwise) ? 1 : 3;
    return static_cast<Location>((static_cast<int>(current) + offset) % 4);
  }

  inline bool IsClockwiseTransition(Location from, Location to) {
    return (static_cast<int>(from) + 1) % 4 == static_cast<int>(to);
  }

  inline bool AreOppositeDirections(Location dir1, Location dir2) {
    return std::abs(static_cast<int>(dir1) - static_cast<int>(dir2)) == 2;
  }

  inline bool DetermineRotationDirection(Location prevDir, Location currDir,
                                         const Point64& prevPoint, const Point64& currPoint,
                                         const Point64& rectCenter) {
    if (AreOppositeDirections(prevDir, currDir))
      return CrossProductSign(prevPoint, rectCenter, currPoint) < 0;
    else
      return IsClockwiseTransition(prevDir, currDir);
  }

  inline OutPt2* RemoveNode(OutPt2* node) {
    if (node->next == node) return nullptr;
    node->prev->next = node->next;
    node->next->prev = node->prev;
    return node->next;
  }

  inline OutPt2* RemoveBackNode(OutPt2* node) {
    if (node->next == node) return nullptr;
    node->prev->next = node->next;
    node->next->prev = node->prev;
    return node->prev;
  }

  inline uint32_t IdentifyEdgesForPoint(const Point64& point, const Rect64& rect) {
    uint32_t edgeFlags = 0;
    if (point.x == rect.left) edgeFlags = 1;
    else if (point.x == rect.right) edgeFlags = 4;

    if (point.y == rect.top) edgeFlags += 2;
    else if (point.y == rect.bottom) edgeFlags += 8;

    return edgeFlags;
  }

  inline bool IsEdgeTraversedClockwise(const Point64& start, const Point64& end, int edgeIndex) {
    switch (edgeIndex) {
      case 0: return end.y < start.y;
      case 1: return end.x > start.x;
      case 2: return end.y > start.y;
      default: return end.x < start.x;
    }
  }

  inline bool HorizontalOverlapExists(const Point64& left1, const Point64& right1,
                                     const Point64& left2, const Point64& right2) {
    return (left1.x < right2.x) && (right1.x > left2.x);
  }

  inline bool VerticalOverlapExists(const Point64& top1, const Point64& bottom1,
                                   const Point64& top2, const Point64& bottom2) {
    return (top1.y < bottom2.y) && (bottom1.y > top2.y);
  }

  inline void AttachToEdge(OutPt2List& edgeList, OutPt2* node) {
    if (node->edge) return;
    node->edge = &edgeList;
    edgeList.emplace_back(node);
  }

  inline void DetachFromEdge(OutPt2* node) {
    if (!node->edge) return;
    for (size_t i = 0; i < node->edge->size(); ++i) {
      if ((*node->edge)[i] == node) {
        (*node->edge)[i] = nullptr;
        break;
      }
    }
    node->edge = nullptr;
  }

  inline void UpdateOwnerIndex(OutPt2* node, size_t newIndex) {
    node->owner_idx = newIndex;
    OutPt2* nextNode = node->next;
    while (nextNode != node) {
      nextNode->owner_idx = newIndex;
      nextNode = nextNode->next;
    }
  }

  //----------------------------------------------------------------------------
  // RectClip64 implementation
  //----------------------------------------------------------------------------

  OutPt2* RectClip64::Add(Point64 pt, bool isNewPath) {
    size_t currentIndex = results_.size();
    OutPt2* newNode;

    if (currentIndex == 0 || isNewPath) {
      newNode = &op_container_.emplace_back(OutPt2());
      newNode->pt = pt;
      newNode->next = newNode;
      newNode->prev = newNode;
      results_.emplace_back(newNode);
    }
    else {
      --currentIndex;
      OutPt2* previousNode = results_[currentIndex];
      if (previousNode->pt == pt) return previousNode;

      newNode = &op_container_.emplace_back(OutPt2());
      newNode->owner_idx = currentIndex;
      newNode->pt = pt;
      newNode->next = previousNode->next;
      previousNode->next->prev = newNode;
      previousNode->next = newNode;
      newNode->prev = previousNode;
      results_[currentIndex] = newNode;
    }
    return newNode;
  }

  void RectClip64::AddCorner(Location from, Location to) {
    if (IsClockwiseTransition(from, to))
      Add(rect_as_path_[static_cast<size_t>(from)]);
    else
      Add(rect_as_path_[static_cast<size_t>(to)]);
  }

  void RectClip64::AddCorner(Location& loc, bool isClockwise) {
    if (isClockwise) {
      Add(rect_as_path_[static_cast<size_t>(loc)]);
      loc = NextClockwiseLocation(loc, true);
    }
    else {
      loc = NextClockwiseLocation(loc, false);
      Add(rect_as_path_[static_cast<size_t>(loc)]);
    }
  }

  void RectClip64::AdvanceToNextPoint(const Path64& path,
                                     Location& currentLoc, size_t& index, size_t maxIndex) {
    switch (currentLoc) {
      case Location::Left:
        while (index <= maxIndex && path[index].x <= rect_.left) ++index;
        if (index > maxIndex) break;
        else if (path[index].x >= rect_.right) currentLoc = Location::Right;
        else if (path[index].y <= rect_.top) currentLoc = Location::Top;
        else if (path[index].y >= rect_.bottom) currentLoc = Location::Bottom;
        else currentLoc = Location::Inside;
        break;

      case Location::Top:
        while (index <= maxIndex && path[index].y <= rect_.top) ++index;
        if (index > maxIndex) break;
        else if (path[index].y >= rect_.bottom) currentLoc = Location::Bottom;
        else if (path[index].x <= rect_.left) currentLoc = Location::Left;
        else if (path[index].x >= rect_.right) currentLoc = Location::Right;
        else currentLoc = Location::Inside;
        break;

      case Location::Right:
        while (index <= maxIndex && path[index].x >= rect_.right) ++index;
        if (index > maxIndex) break;
        else if (path[index].x <= rect_.left) currentLoc = Location::Left;
        else if (path[index].y <= rect_.top) currentLoc = Location::Top;
        else if (path[index].y >= rect_.bottom) currentLoc = Location::Bottom;
        else currentLoc = Location::Inside;
        break;

      case Location::Bottom:
        while (index <= maxIndex && path[index].y >= rect_.bottom) ++index;
        if (index > maxIndex) break;
        else if (path[index].y <= rect_.top) currentLoc = Location::Top;
        else if (path[index].x <= rect_.left) currentLoc = Location::Left;
        else if (path[index].x >= rect_.right) currentLoc = Location::Right;
        else currentLoc = Location::Inside;
        break;

      case Location::Inside:
        while (index <= maxIndex) {
          if (path[index].x < rect_.left) currentLoc = Location::Left;
          else if (path[index].x > rect_.right) currentLoc = Location::Right;
          else if (path[index].y > rect_.bottom) currentLoc = Location::Bottom;
          else if (path[index].y < rect_.top) currentLoc = Location::Top;
          else { Add(path[index]); ++index; continue; }
          break;
        }
        break;
    }
  }

  bool AreStartingLocationsClockwise(const std::vector<Location>& startLocations) {
    int directionSum = 0;
    for (size_t i = 1; i < startLocations.size(); ++i) {
      int diff = static_cast<int>(startLocations[i]) - static_cast<int>(startLocations[i-1]);
      switch (diff) {
        case -1: directionSum -= 1; break;
        case 1: directionSum += 1; break;
        case -3: directionSum += 1; break;
        case 3: directionSum -= 1; break;
      }
    }
    return directionSum > 0;
  }

  void RectClip64::ProcessPath(const Path64& path) {
    if (path.size() < 1) return;

    size_t lastIndex = path.size() - 1;
    Location previousLoc = Location::Inside, currentLoc;
    Location crossingLoc = Location::Inside;
    Location firstCrossingLoc = Location::Inside;

    if (!DeterminePointLocation(rect_, path[lastIndex], currentLoc)) {
      size_t idx = lastIndex;
      while (idx > 0 && !DeterminePointLocation(rect_, path[idx - 1], previousLoc)) --idx;

      if (idx == 0) {
        // Entire path is inside rectangle
        for (const auto& pt : path) Add(pt);
        return;
      }
      if (previousLoc == Location::Inside) currentLoc = Location::Inside;
    }

    Location initialLoc = currentLoc;
    size_t i = 0;

    while (i <= lastIndex) {
      previousLoc = currentLoc;
      Location prevCrossing = crossingLoc;
      AdvanceToNextPoint(path, currentLoc, i, lastIndex);

      if (i > lastIndex) break;

      Point64 intersection, secondIntersection;
      Point64 prevPoint = (i) ? path[i - 1] : path[lastIndex];
      crossingLoc = currentLoc;

      if (!FindIntersectionWithRectBoundary(rect_as_path_,
                                           path[i], prevPoint, crossingLoc, intersection)) {
        // Remaining outside rectangle
        if (prevCrossing == Location::Inside) {
          bool isClockwise = DetermineRotationDirection(previousLoc, currentLoc, prevPoint, path[i], rect_mp_);
          do {
            start_locs_.emplace_back(previousLoc);
            previousLoc = NextClockwiseLocation(previousLoc, isClockwise);
          } while (previousLoc != currentLoc);
          crossingLoc = prevCrossing;
        }
        else if (previousLoc != Location::Inside && previousLoc != currentLoc) {
          bool isClockwise = DetermineRotationDirection(previousLoc, currentLoc, prevPoint, path[i], rect_mp_);
          do {
            AddCorner(previousLoc, isClockwise);
          } while (previousLoc != currentLoc);
        }
        ++i;
        continue;
      }

      // We've crossed the rectangle boundary
      if (currentLoc == Location::Inside) { // Entering rectangle
        if (firstCrossingLoc == Location::Inside) {
          firstCrossingLoc = crossingLoc;
          start_locs_.emplace_back(previousLoc);
        }
        else if (previousLoc != crossingLoc) {
          bool isClockwise = DetermineRotationDirection(previousLoc, crossingLoc, prevPoint, path[i], rect_mp_);
          do {
            AddCorner(previousLoc, isClockwise);
          } while (previousLoc != crossingLoc);
        }
      }
      else if (previousLoc != Location::Inside) { // Passing through rectangle
        currentLoc = previousLoc;
        GetIntersection(rect_as_path_, prevPoint, path[i], currentLoc, secondIntersection);

        if (prevCrossing != Location::Inside && prevCrossing != currentLoc)
          AddCorner(prevCrossing, currentLoc);

        if (firstCrossingLoc == Location::Inside) {
          firstCrossingLoc = currentLoc;
          start_locs_.emplace_back(previousLoc);
        }

        currentLoc = crossingLoc;
        Add(secondIntersection);

        if (intersection == secondIntersection) {
          DeterminePointLocation(rect_, path[i], currentLoc);
          AddCorner(crossingLoc, currentLoc);
          crossingLoc = currentLoc;
          continue;
        }
      }
      else { // Exiting rectangle
        currentLoc = crossingLoc;
        if (firstCrossingLoc == Location::Inside)
          firstCrossingLoc = crossingLoc;
      }
      Add(intersection);
    }

    // Handle final cases
    if (firstCrossingLoc == Location::Inside) {
      if (initialLoc != Location::Inside) {
        if (path_bounds_.Contains(rect_) &&
            PathContainsPath(path, rect_as_path_)) {
          bool isClockwisePath = AreStartingLocationsClockwise(start_locs_);
          for (size_t j = 0; j < 4; ++j) {
            size_t k = isClockwisePath ? j : 3 - j;
            Add(rect_as_path_[k]);
            AttachToEdge(edges_[k * 2], results_[0]);
          }
        }
      }
    }
    else if (currentLoc != Location::Inside &&
             (currentLoc != firstCrossingLoc || start_locs_.size() > 2)) {
      if (start_locs_.size() > 0) {
        previousLoc = currentLoc;
        for (auto loc2 : start_locs_) {
          if (previousLoc == loc2) continue;
          AddCorner(previousLoc, IsClockwiseTransition(previousLoc, loc2));
          previousLoc = loc2;
        }
        currentLoc = previousLoc;
      }
      if (currentLoc != firstCrossingLoc)
        AddCorner(currentLoc, IsClockwiseTransition(currentLoc, firstCrossingLoc));
    }
  }

  void RectClip64::ValidateEdges() {
    for (size_t i = 0; i < results_.size(); ++i) {
      OutPt2* node = results_[i];
      if (!node) continue;

      OutPt2* currentNode = node;
      do {
        if (IsCollinear(currentNode->prev->pt, currentNode->pt, currentNode->next->pt)) {
          if (currentNode == node) {
            currentNode = RemoveBackNode(currentNode);
            if (!currentNode) break;
            node = currentNode->prev;
          }
          else {
            currentNode = RemoveBackNode(currentNode);
            if (!currentNode) break;
          }
        }
        else
          currentNode = currentNode->next;
      } while (currentNode != node);

      if (!currentNode) {
        results_[i] = nullptr;
        continue;
      }

      results_[i] = node;

      uint32_t edgeSet1 = IdentifyEdgesForPoint(node->prev->pt, rect_);
      currentNode = node;
      do {
        uint32_t edgeSet2 = IdentifyEdgesForPoint(currentNode->pt, rect_);
        if (edgeSet2 && !currentNode->edge) {
          uint32_t combinedSet = (edgeSet1 & edgeSet2);
          for (int j = 0; j < 4; ++j) {
            if (combinedSet & (1 << j)) {
              if (IsEdgeTraversedClockwise(currentNode->prev->pt, currentNode->pt, j))
                AttachToEdge(edges_[j * 2], currentNode);
              else
                AttachToEdge(edges_[j * 2 + 1], currentNode);
            }
          }
        }
        edgeSet1 = edgeSet2;
        currentNode = currentNode->next;
      } while (currentNode != node);
    }
  }

  void RectClip64::OptimizeEdges(size_t edgeIndex, OutPt2List& cwList, OutPt2List& ccwList) {
    if (ccwList.empty()) return;

    bool isHorizontal = ((edgeIndex == 1) || (edgeIndex == 3));
    bool cwMovesForward = ((edgeIndex == 1) || (edgeIndex == 2));

    size_t i = 0, j = 0;
    OutPt2* p1, * p2, * p1a, * p2a, * op, * op2;

    while (i < cwList.size()) {
      p1 = cwList[i];
      if (!p1 || p1->next == p1->prev) {
        cwList[i++] = nullptr;
        j = 0;
        continue;
      }

      size_t jLimit = ccwList.size();
      while (j < jLimit && (!ccwList[j] || ccwList[j]->next == ccwList[j]->prev)) ++j;

      if (j == jLimit) {
        ++i;
        j = 0;
        continue;
      }

      if (cwMovesForward) {
        p1 = cwList[i]->prev;
        p1a = cwList[i];
        p2 = ccwList[j];
        p2a = ccwList[j]->prev;
      }
      else {
        p1 = cwList[i];
        p1a = cwList[i]->prev;
        p2 = ccwList[j]->prev;
        p2a = ccwList[j];
      }

      if ((isHorizontal && !HorizontalOverlapExists(p1->pt, p1a->pt, p2->pt, p2a->pt)) ||
          (!isHorizontal && !VerticalOverlapExists(p1->pt, p1a->pt, p2->pt, p2a->pt))) {
        ++j;
        continue;
      }

      bool isRejoining = cwList[i]->owner_idx != ccwList[j]->owner_idx;
      if (isRejoining) {
        results_[p2->owner_idx] = nullptr;
        UpdateOwnerIndex(p2, p1->owner_idx);
      }

      if (cwMovesForward) {
        p1->next = p2;
        p2->prev = p1;
        p1a->prev = p2a;
        p2a->next = p1a;
      }
      else {
        p1->prev = p2;
        p2->next = p1;
        p1a->next = p2a;
        p2a->prev = p1a;
      }

      if (!isRejoining) {
        size_t newIdx = results_.size();
        results_.emplace_back(p1a);
        UpdateOwnerIndex(p1a, newIdx);
      }

      if (cwMovesForward) {
        op = p2;
        op2 = p1a;
      }
      else {
        op = p1;
        op2 = p2a;
      }

      results_[op->owner_idx] = op;
      results_[op2->owner_idx] = op2;

      bool opMovesForward, op2MovesForward;
      if (isHorizontal) {
        opMovesForward = op->pt.x > op->prev->pt.x;
        op2MovesForward = op2->pt.x > op2->prev->pt.x;
      }
      else {
        opMovesForward = op->pt.y > op->prev->pt.y;
        op2MovesForward = op2->pt.y > op2->prev->pt.y;
      }

      if ((op->next == op->prev) || (op->pt == op->prev->pt)) {
        if (op2MovesForward == cwMovesForward) {
          cwList[i] = op2;
          ccwList[j++] = nullptr;
        }
        else {
          ccwList[j] = op2;
          cwList[i++] = nullptr;
        }
      }
      else if ((op2->next == op2->prev) || (op2->pt == op2->prev->pt)) {
        if (opMovesForward == cwMovesForward) {
          cwList[i] = op;
          ccwList[j++] = nullptr;
        }
        else {
          ccwList[j] = op;
          cwList[i++] = nullptr;
        }
      }
      else if (opMovesForward == op2MovesForward) {
        if (opMovesForward == cwMovesForward) {
          cwList[i] = op;
          DetachFromEdge(op2);
          AttachToEdge(cwList, op2);
          ccwList[j++] = nullptr;
        }
        else {
          cwList[i++] = nullptr;
          ccwList[j] = op2;
          DetachFromEdge(op);
          AttachToEdge(ccwList, op);
          j = 0;
        }
      }
      else {
        if (opMovesForward == cwMovesForward)
          cwList[i] = op;
        else
          ccwList[j] = op;
        if (op2MovesForward == cwMovesForward)
          cwList[i] = op2;
        else
          ccwList[j] = op2;
      }
    }
  }

  Path64 RectClip64::ExtractPath(OutPt2*& node) {
    if (!node || node->next == node->prev) return Path64();

    OutPt2* currentNode = node->next;
    while (currentNode && currentNode != node) {
      if (IsCollinear(currentNode->prev->pt, currentNode->pt, currentNode->next->pt)) {
        if (currentNode == node) {
          currentNode = RemoveBackNode(currentNode);
          if (!currentNode) break;
          node = currentNode->prev;
        }
        else {
          currentNode = RemoveBackNode(currentNode);
          if (!currentNode) break;
        }
      }
      else
        currentNode = currentNode->next;
    }

    node = currentNode;
    if (!currentNode) return Path64();

    Path64 result;
    result.emplace_back(node->pt);
    currentNode = node->next;
    while (currentNode != node) {
      result.emplace_back(currentNode->pt);
      currentNode = currentNode->next;
    }
    return result;
  }

  Paths64 RectClip64::Clip(const Paths64& inputPaths) {
    Paths64 output;
    if (rect_.IsEmpty()) return output;

    for (const Path64& path : inputPaths) {
      if (path.size() < 3) continue;

      path_bounds_ = GetBounds(path);
      if (!rect_.Intersects(path_bounds_))
        continue;
      else if (rect_.Contains(path_bounds_)) {
        output.emplace_back(path);
        continue;
      }

      ProcessPath(path);
      ValidateEdges();
      for (size_t i = 0; i < 4; ++i)
        OptimizeEdges(i, edges_[i * 2], edges_[i * 2 + 1]);

      for (OutPt2*& node : results_) {
        Path64 temp = ExtractPath(node);
        if (!temp.empty())
          output.emplace_back(std::move(temp));
      }

      // Reset state for next iteration
      op_container_ = std::deque<OutPt2>();
      results_.clear();
      for (OutPt2List& edge : edges_) edge.clear();
      start_locs_.clear();
    }
    return output;
  }

  //------------------------------------------------------------------------------
  // RectClipLines64 implementation
  //------------------------------------------------------------------------------

  Paths64 RectClipLines64::Clip(const Paths64& inputPaths) {
    Paths64 output;
    if (rect_.IsEmpty()) return output;

    for (const auto& path : inputPaths) {
      Rect64 pathBounds = GetBounds(path);
      if (!rect_.Intersects(pathBounds)) continue;

      ProcessPath(path);
      for (OutPt2*& node : results_) {
        Path64 temp = ExtractPath(node);
        if (!temp.empty())
          output.emplace_back(std::move(temp));
      }

      results_.clear();
      op_container_ = std::deque<OutPt2>();
      start_locs_.clear();
    }
    return output;
  }

  void RectClipLines64::ProcessPath(const Path64& path) {
    if (rect_.IsEmpty() || path.size() < 2) return;

    results_.clear();
    op_container_ = std::deque<OutPt2>();
    start_locs_.clear();

    size_t i = 1, lastIndex = path.size() - 1;
    Location previousLoc = Location::Inside, currentLoc;
    Location crossingLoc;

    if (!DeterminePointLocation(rect_, path[0], currentLoc)) {
      while (i <= lastIndex && !DeterminePointLocation(rect_, path[i], previousLoc)) ++i;

      if (i > lastIndex) {
        for (const auto& pt : path) Add(pt);
        return;
      }
      if (previousLoc == Location::Inside) currentLoc = Location::Inside;
      i = 1;
    }

    if (currentLoc == Location::Inside) Add(path[0]);

    while (i <= lastIndex) {
      previousLoc = currentLoc;
      AdvanceToNextPoint(path, currentLoc, i, lastIndex);

      if (i > lastIndex) break;

      Point64 intersection, secondIntersection;
      Point64 prevPoint = path[i - 1];
      crossingLoc = currentLoc;

      if (!FindIntersectionWithRectBoundary(rect_as_path_,
                                           path[i], prevPoint, crossingLoc, intersection)) {
        ++i;
        continue;
      }

      if (currentLoc == Location::Inside) {
        Add(intersection, true);
      }
      else if (previousLoc != Location::Inside) {
        crossingLoc = previousLoc;
        GetIntersection(rect_as_path_, prevPoint, path[i], crossingLoc, secondIntersection);
        Add(secondIntersection, true);
        Add(intersection);
      }
      else {
        Add(intersection);
      }
    }
  }

  Path64 RectClipLines64::ExtractPath(OutPt2*& node) {
    Path64 result;
    if (!node || node == node->next) return result;

    node = node->next;
    result.emplace_back(node->pt);

    OutPt2* currentNode = node->next;
    while (currentNode != node) {
      result.emplace_back(currentNode->pt);
      currentNode = currentNode->next;
    }
    return result;
  }

