using namespace ImGuiToggleMath;

void ImGui::UnionPalette(ImGuiTogglePalette* target, const ImGuiTogglePalette* candidate, const ImVec4 colors[], bool state)
{
    // Initialize with default theme-based colors based on toggle state
    target->Knob = colors[ImGuiCol_Text];
    target->KnobHover = colors[ImGuiCol_Text];
    target->Frame = colors[state ? ImGuiCol_Button : ImGuiCol_FrameBg];
    target->FrameHover = colors[state ? ImGuiCol_ButtonHovered : ImGuiCol_FrameBgHovered];
    target->FrameBorder = colors[ImGuiCol_Border];
    target->FrameShadow = colors[ImGuiCol_BorderShadow];
    target->KnobBorder = colors[ImGuiCol_Border];
    target->KnobShadow = colors[ImGuiCol_BorderShadow];
    target->A11yGlyph = colors[state ? ImGuiCol_Text : ImGuiCol_FrameBg];

    // If no custom palette provided, use defaults only
    if (candidate == nullptr)
        return;

    // Override with non-zero values from candidate palette where available
    auto applyIfNonZero = [&](float& targetMember, const float& candidateMember) {
        if (IsNonZero(candidateMember))
            targetMember = candidateMember;
    };

    applyIfNonZero(target->Knob.x, candidate->Knob.x);
    applyIfNonZero(target->Knob.y, candidate->Knob.y);
    applyIfNonZero(target->Knob.z, candidate->Knob.z);
    applyIfNonZero(target->Knob.w, candidate->Knob.w);

    applyIfNonZero(target->KnobHover.x, candidate->KnobHover.x);
    applyIfNonZero(target->KnobHover.y, candidate->KnobHover.y);
    applyIfNonZero(target->KnobHover.z, candidate->KnobHover.z);
    applyIfNonZero(target->KnobHover.w, candidate->KnobHover.w);

    applyIfNonZero(target->Frame.x, candidate->Frame.x);
    applyIfNonZero(target->Frame.y, candidate->Frame.y);
    applyIfNonZero(target->Frame.z, candidate->Frame.z);
    applyIfNonZero(target->Frame.w, candidate->Frame.w);

    applyIfNonZero(target->FrameHover.x, candidate->FrameHover.x);
    applyIfNonZero(target->FrameHover.y, candidate->FrameHover.y);
    applyIfNonZero(target->FrameHover.z, candidate->FrameHover.z);
    applyIfNonZero(target->FrameHover.w, candidate->FrameHover.w);

    applyIfNonZero(target->FrameBorder.x, candidate->FrameBorder.x);
    applyIfNonZero(target->FrameBorder.y, candidate->FrameBorder.y);
    applyIfNonZero(target->FrameBorder.z, candidate->FrameBorder.z);
    applyIfNonZero(target->FrameBorder.w, candidate->FrameBorder.w);

    applyIfNonZero(target->FrameShadow.x, candidate->FrameShadow.x);
    applyIfNonZero(target->FrameShadow.y, candidate->FrameShadow.y);
    applyIfNonZero(target->FrameShadow.z, candidate->FrameShadow.z);
    applyIfNonZero(target->FrameShadow.w, candidate->FrameShadow.w);

    applyIfNonZero(target->KnobBorder.x, candidate->KnobBorder.x);
    applyIfNonZero(target->KnobBorder.y, candidate->KnobBorder.y);
    applyIfNonZero(target->KnobBorder.z, candidate->KnobBorder.z);
    applyIfNonZero(target->KnobBorder.w, candidate->KnobBorder.w);

    applyIfNonZero(target->KnobShadow.x, candidate->KnobShadow.x);
    applyIfNonZero(target->KnobShadow.y, candidate->KnobShadow.y);
    applyIfNonZero(target->KnobShadow.z, candidate->KnobShadow.z);
    applyIfNonZero(target->KnobShadow.w, candidate->KnobShadow.w);

    applyIfNonZero(target->A11yGlyph.x, candidate->A11yGlyph.x);
    applyIfNonZero(target->A11yGlyph.y, candidate->A11yGlyph.y);
    applyIfNonZero(target->A11yGlyph.z, candidate->A11yGlyph.z);
    applyIfNonZero(target->A11yGlyph.w, candidate->A11yGlyph.w);
}

void ImGui::BlendPalettes(ImGuiTogglePalette* result, const ImGuiTogglePalette& base, const ImGuiTogglePalette& overlay, float factor)
{
    // Early exit for edge cases
    if (ImApproximately(factor, 0.0f)) {
        *result = base;
        return;
    }
    if (ImApproximately(factor, 1.0f)) {
        *result = overlay;
        return;
    }

    // Linear interpolation per component
    auto lerpComponent = [](float a, float b, float t) -> float {
        return a + (b - a) * t;
    };

    for (int i = 0; i < 4; ++i) {
        result->Knob[i] = lerpComponent(base.Knob[i], overlay.Knob[i], factor);
        result->KnobHover[i] = lerpComponent(base.KnobHover[i], overlay.KnobHover[i], factor);
        result->Frame[i] = lerpComponent(base.Frame[i], overlay.Frame[i], factor);
        result->FrameHover[i] = lerpComponent(base.FrameHover[i], overlay.FrameHover[i], factor);
        result->FrameBorder[i] = lerpComponent(base.FrameBorder[i], overlay.FrameBorder[i], factor);
        result->FrameShadow[i] = lerpComponent(base.FrameShadow[i], overlay.FrameShadow[i], factor);
        result->KnobBorder[i] = lerpComponent(base.KnobBorder[i], overlay.KnobBorder[i], factor);
        result->KnobShadow[i] = lerpComponent(base.KnobShadow[i], overlay.KnobShadow[i], factor);
        result->A11yGlyph[i] = lerpComponent(base.A11yGlyph[i], overlay.A11yGlyph[i], factor);
    }
}

