// Helper class for primitive type calculations
class PrimitiveHelper {
private:
    std::vector<struct NumPrimitiveInfo*> cachedCounts;
    std::vector<struct LayoutInfo*> cachedLayouts;

public:
    // Calculate sum of elements before position i
    int calculatePrefixSum(const std::vector<int>& values, unsigned pos) {
        int total = 0;
        if (pos > values.size()) pos = values.size();
        for (int idx = pos - 1; idx >= 0; --idx)
            total += values[idx];
        return total;
    }

    // Get element type at index i within composite type
    Type* extractElementType(Type* baseType, int index) {
        if (baseType->isPointerTy())
            return baseType->getPointerElementType();
        else if (baseType->isArrayTy())
            return baseType->getArrayElementType();
        else if (baseType->isStructTy())
            return baseType->getStructElementType(index);
        else if (baseType->isVectorTy())
            return baseType->getScalarType();
        return nullptr;
    }

    // Count primitive elements in type
    int countPrimitives(Type* type) {
        // Check cache first
        for (auto& entry : cachedCounts) {
            if (entry->type == type) return entry->count;
        }

        int primitiveCount = 0;
        if (type->isArrayTy()) {
            int numElements = type->getArrayNumElements();
            Type* elemType = type->getArrayElementType();
            primitiveCount = numElements * countPrimitives(elemType);
        } else if (type->isStructTy()) {
            int numFields = type->getStructNumElements();
            primitiveCount = 0;
            for (int i = 0; i < numFields; ++i) {
                Type* fieldTy = type->getStructElementType(i);
                primitiveCount += countPrimitives(fieldTy);
            }
        } else if (type->isVectorTy()) {
            int numElements = cast<VectorType>(type)->getElementCount().getKnownMinValue();
            Type* scalarTy = type->getScalarType();
            primitiveCount = numElements * countPrimitives(scalarTy);
        } else {
            primitiveCount = type->getPrimitiveSizeInBits();
            if (primitiveCount == 0) primitiveCount = 1;
        }

        cachedCounts.push_back(new NumPrimitiveInfo(type, primitiveCount));
        return primitiveCount;
    }

    // Get layout vector for type
    std::vector<int> getLayout(Type* type) {
        // Check cache first
        for (auto& entry : cachedLayouts) {
            if (entry->type == type) return entry->layout;
        }

        std::vector<int> layout;
        if (type->isArrayTy()) {
            int numElements = type->getArrayNumElements();
            layout.resize(numElements);
            Type* elemType = type->getArrayElementType();
            int elemSize = countPrimitives(elemType);
            for (int i = 0; i < numElements; ++i) layout[i] = elemSize;
        } else if (type->isStructTy()) {
            int numFields = type->getStructNumElements();
            layout.resize(numFields);
            for (int i = 0; i < numFields; ++i) {
                Type* fieldTy = type->getStructElementType(i);
                layout[i] = countPrimitives(fieldTy);
            }
        } else if (type->isVectorTy()) {
            int numElements = cast<VectorType>(type)->getElementCount().getKnownMinValue();
            layout.resize(numElements);
            Type* scalarTy = type->getScalarType();
            int scalarSize = countPrimitives(scalarTy);
            for (int i = 0; i < numElements; ++i) layout[i] = scalarSize;
        } else {
            layout.push_back(1);
        }

        cachedLayouts.push_back(new LayoutInfo(type, layout));
        return layout;
    }
};

// Helper function for range comparison
bool rangesAreDisjoint(Range& r1, Range& r2) {
    if (r1.getLower().sgt(r2.getUpper())) return true;
    if (r2.getLower().sgt(r1.getUpper())) return true;
    return false;
}

// Main analysis class
class StrictRelationsAnalysis : public ModulePass {
private:
    float totalTime, phase1Time, phase2Time, phase3Time;
    float test1Time, test2Time, test3Time;

    std::map<const Value*, Variable*> varMap;
    std::map<const Value*, DepNode*> nodeMap;
    WorkListEngine* worklistEngine;
    InterProceduralRA<Cousot>* rangeAnalyzer;
    PrimitiveHelper helper;

public:
    static char ID;

    StrictRelationsAnalysis() : ModulePass(ID), 
                                totalTime(0), phase1Time(0), phase2Time(0), 
                                phase3Time(0), test1Time(0), test2Time(0), test3Time(0) {}

    ~StrictRelationsAnalysis() override {
        totalTime = test1Time + test2Time + test3Time;
        errs() << "------------------------------------------\n";
        errs() << "                Timing Report               \n";
        errs() << "------------------------------------------\n";
        errs() << "Total execution time: " << totalTime << "\n";
        errs() << "Constraint collection: " << phase1Time << "\n";
        errs() << "Dependency graph construction: " << phase2Time << "\n";
        errs() << "Worklist processing: " << phase3Time << "\n";
        errs() << "Test 1 execution time: " << test1Time << "\n";
        errs() << "Test 2 execution time: " << test2Time << "\n";
        errs() << "Test 3 execution time: " << test3Time << "\n";
        errs() << "------------------------------------------\n";
    }

    void getAnalysisUsage(AnalysisUsage& AU) const override {
        AU.addRequired<InterProceduralRA<Cousot>>();
        AU.setPreservesAll();
    }

    // Compare two values based on their ranges and constraints
    enum Comparison { LESS, GREATER, EQUAL, UNKNOWN };

    Comparison compareValues(const Value* val1, const Value* val2) {
        if (varMap.count(val1) && varMap.count(val2)) {
            if (varMap[val1]->greaterThanSet.count(varMap[val2])) return LESS;
            if (varMap[val1]->lessThanSet.count(varMap[val2])) return GREATER;
        }

        Range range1 = val1 ? rangeAnalyzer->getRange(val1) : Range(Zero, Zero);
        Range range2 = val2 ? rangeAnalyzer->getRange(val2) : Range(Zero, Zero);

        if (range1.getLower().eq(range2.getLower()) && 
            range1.getUpper().eq(range2.getUpper()))
            return EQUAL;
        else if (range1.getUpper().slt(range2.getLower()))
            return LESS;
        else if (range2.getUpper().slt(range1.getLower()))
            return GREATER;
        return UNKNOWN;
    }

    // Check if two GEP instructions access disjoint memory locations
    bool areGEPsDisjoint(const GetElementPtrInst* gep1, const GetElementPtrInst* gep2) {
        auto idx1 = gep1->idx_begin(), idx2 = gep2->idx_begin();
        auto end1 = gep1->idx_end(), end2 = gep2->idx_end();

        Comparison cmp = EQUAL;
        while (idx1 != end1 || idx2 != end2) {
            const Value* op1 = (idx1 == end1) ? nullptr : *idx1;
            const Value* op2 = (idx2 == end2) ? nullptr : *idx2;

            Comparison result = compareValues(op1, op2);
            if (result == LESS) {
                if (cmp == LESS || cmp == EQUAL) cmp = LESS;
                else return false;
            } else if (result == GREATER) {
                if (cmp == GREATER || cmp == EQUAL) cmp = GREATER;
                else return false;
            } else if (result == UNKNOWN) {
                return false;
            }

            if (idx1 != end1) ++idx1;
            if (idx2 != end2) ++idx2;
        }

        return (cmp == LESS || cmp == GREATER);
    }

    // Main alias query function
    AliasResult alias(const MemoryLocation& locA, const MemoryLocation& locB) override {
        NumQueries++;
        const Value* ptr1 = locA.Ptr;
        const Value* ptr2 = locB.Ptr;

        if (nodeMap[ptr1]->mustAliasGroup == nodeMap[ptr2]->mustAliasGroup)
            return AliasResult::MustAlias;

        if (test3Alias(ptr1, ptr2)) {
            NumNoAlias++;
            return AliasResult::NoAlias;
        }

        if (test2Alias(ptr1, ptr2)) {
            NumNoAlias++;
            return AliasResult::NoAlias;
        }

        if (test1Alias(ptr1, ptr2)) {
            NumNoAlias++;
            return AliasResult::NoAlias;
        }

        return AliasResult::MayAlias;
    }

    // First alias test: local tree verification
    bool test1Alias(const Value* p1, const Value* p2) {
        clock_t start = clock();

        if (nodeMap.count(p1) && nodeMap.count(p2)) {
            DepNode* nodeA = nodeMap[p1];
            DepNode* nodeB = nodeMap[p2];

            if (nodeA->localRoot == nodeB->localRoot) {
                int ancestorIndex = -1;
                DepNode* commonAncestor = nullptr;

                for (auto& pathEntry : nodeA->pathToRoot) {
                    if (ancestorIndex > -1 && pathEntry.second.first > ancestorIndex)
                        continue;
                    else if (nodeB->pathToRoot.count(pathEntry.first)) {
                        if (ancestorIndex == -1 || pathEntry.second.first < ancestorIndex) {
                            ancestorIndex = pathEntry.second.first;
                            commonAncestor = pathEntry.first;
                        }
                    }
                }

                if (commonAncestor && 
                    rangesAreDisjoint(nodeA->pathToRoot[commonAncestor].second,
                                     nodeB->pathToRoot[commonAncestor].second)) {
                    NumNoAlias1++;
                    float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
                    test1Time += elapsed;
                    return true;
                }
            }
        }

        float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
        test1Time += elapsed;
        return false;
    }

    // Second alias test: variable ordering check
    bool test2Alias(const Value* p1, const Value* p2) {
        clock_t start = clock();

        if (!varMap.count(p1)) varMap[p1] = new Variable(p1);
        if (!varMap.count(p2)) varMap[p2] = new Variable(p2);

        Variable* var1 = varMap[p1];
        Variable* var2 = varMap[p2];

        if (var1->lessThanSet.count(var2) || var1->greaterThanSet.count(var2)) {
            NumNoAlias2++;
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test2Time += elapsed;
            return true;
        }

        if (const GetElementPtrInst* g1 = dyn_cast<GetElementPtrInst>(p1))
            if (const GetElementPtrInst* g2 = dyn_cast<GetElementPtrInst>(p2)) {
                if (nodeMap[g1->getPointerOperand()]->mustAliasGroup == 
                    nodeMap[g2->getPointerOperand()]->mustAliasGroup) {
                    float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
                    test2Time += elapsed;
                    return areGEPsDisjoint(g1, g2);
                }
            }

        float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
        test2Time += elapsed;
        return false;
    }

    // Third alias test: structural analysis
    bool test3Alias(const Value* p1, const Value* p2) {
        clock_t start = clock();

        DepNode* nodeA = nodeMap[p1];
        DepNode* nodeB = nodeMap[p2];

        if (nodeA->unknown || nodeB->unknown) {
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test3Time += elapsed;
            return false;
        }

        if (nodeA->incomingEdges.empty() && !nodeA->argument && 
            !nodeA->alloca && !nodeA->global) {
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test3Time += elapsed;
            return false;
        }

        if (nodeB->incomingEdges.empty() && !nodeB->argument && 
            !nodeB->alloca && !nodeB->global) {
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test3Time += elapsed;
            return false;
        }

        if (nodeA->argument && !nodeB->argument && !nodeB->global) {
            NumNoAlias3++;
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test3Time += elapsed;
            return true;
        }

        if (nodeB->argument && !nodeA->argument && !nodeA->global) {
            NumNoAlias3++;
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test3Time += elapsed;
            return true;
        }

        if (nodeA->locations.empty() || nodeB->locations.empty()) {
            float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
            test3Time += elapsed;
            return false;
        }

        for (auto loc : nodeA->locations) {
            if (nodeB->locations.count(loc)) {
                float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
                test3Time += elapsed;
                return false;
            }
        }

        NumNoAlias3++;
        float elapsed = (float)(clock() - start) / CLOCKS_PER_SEC;
        test3Time += elapsed;
        return true;
    }

    // Process GEP indices to compute offset range
    Range processGEP(const Value* base, const Use* idxStart, const Use* idxEnd) {
        Range result;
        Type* baseType = base->getType();
        int baseElemCount = helper.countPrimitives(baseType->getPointerElementType());

        Value* indexVal = idxStart->get();
        if (ConstantInt* cInt = dyn_cast<ConstantInt>(indexVal)) {
            int constantOffset = cInt->getSExtValue();
            result.setLower(APInt(MAX_BIT_INT, baseElemCount * constantOffset));
            result.setUpper(APInt(MAX_BIT_INT, baseElemCount * constantOffset));
        } else {
            Range indexRange = rangeAnalyzer->getRange(indexVal);
            if (indexRange.getLower().eq(Min))
                result.setLower(Min);
            else
                result.setLower(APInt(MAX_BIT_INT, baseElemCount) * indexRange.getLower());

            if (indexRange.getUpper().eq(Max))
                result.setUpper(Max);
            else
                result.setUpper(APInt(MAX_BIT_INT, baseElemCount) * indexRange.getUpper());
        }

        int currentIndex = 0;
        for (int i = 1; (idxStart + i) != idxEnd; ++i) {
            baseType = helper.extractElementType(baseType, currentIndex);
            std::vector<int> layout = helper.getLayout(baseType);

            Value* indexVal = (idxStart + i)->get();
            if (ConstantInt* cInt = dyn_cast<ConstantInt>(indexVal)) {
                int constantIdx = cInt->getSExtValue();
                APInt offset(MAX_BIT_INT, helper.calculatePrefixSum(layout, constantIdx));
                result = result.add(Range(offset, offset));
                currentIndex = constantIdx;
            } else {
                Range indexRange = rangeAnalyzer->getRange(indexVal);
                APInt lower(MAX_BIT_INT, helper.calculatePrefixSum(layout, 
                    indexRange.getLower().getSExtValue()));
                APInt upper(MAX_BIT_INT, helper.calculatePrefixSum(layout, 
                    indexRange.getUpper().getSExtValue()));
                result = result.add(Range(lower, upper));
                currentIndex = 0;
            }
        }

        return result;
    }

    // Collect constraints from module
    void collectConstraints(Module& M) {
        std::map<const CmpInst*, std::pair<std::pair<const Value*, const Value*>,
                                          std::pair<const Value*, const Value*>>> sigmaMap;

        for (Module::iterator func = M.begin(), funcEnd = M.end(); func != funcEnd; ++func) {
            for (Function::iterator block = func->begin(), blockEnd = func->end(); 
                 block != blockEnd; ++block) {
                for (BasicBlock::iterator inst = block->begin(), instEnd = block->end(); 
                     inst != instEnd; ++inst) {
                    if (!varMap.count(&*inst))
                        varMap[&*inst] = new Variable(&*inst);

                    if (isa<BinaryOperator>(&*inst) && 
                        (&*inst)->getOpcode() == Instruction::Add) {
                        Value* op1 = (&*inst)->getOperand(0);
                        Value* op2 = (&*inst)->getOperand(1);
                        Range r1 = rangeAnalyzer->getRange(op1);
                        Range r2 = rangeAnalyzer->getRange(op2);

                        // Process first operand
                        if (r1.getLower().eq(Zero) && r1.getUpper().eq(Zero)) {
                            if (!varMap.count(op2)) varMap[op2] = new Variable(op2);
                            Constraint* c = new REQ(worklistEngine, varMap[&*inst], varMap[op2]);
                            varMap[&*inst]->coalesce(varMap[op2]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op2]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r1.getLower().sgt(Zero)) {
                            if (!varMap.count(op2)) varMap[op2] = new Variable(op2);
                            Constraint* c = new LT(worklistEngine, varMap[op2], varMap[&*inst]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op2]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r1.getLower().sge(Zero)) {
                            if (!varMap.count(op2)) varMap[op2] = new Variable(op2);
                            Constraint* c = new LE(worklistEngine, varMap[op2], varMap[&*inst]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op2]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r1.getUpper().slt(Zero)) {
                            if (!varMap.count(op2)) varMap[op2] = new Variable(op2);
                            Constraint* c = new LT(worklistEngine, varMap[&*inst], varMap[op2]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op2]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r1.getUpper().sle(Zero)) {
                            if (!varMap.count(op2)) varMap[op2] = new Variable(op2);
                            Constraint* c = new LE(worklistEngine, varMap[&*inst], varMap[op2]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op2]->constraints.insert(c);
                            worklistEngine->add(c);
                        }

                        // Process second operand
                        if (r2.getLower().eq(Zero) && r2.getUpper().eq(Zero)) {
                            if (!varMap.count(op1)) varMap[op1] = new Variable(op1);
                            Constraint* c = new REQ(worklistEngine, varMap[&*inst], varMap[op1]);
                            varMap[&*inst]->coalesce(varMap[op1]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op1]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r2.getLower().sgt(Zero)) {
                            if (!varMap.count(op1)) varMap[op1] = new Variable(op1);
                            Constraint* c = new LT(worklistEngine, varMap[op1], varMap[&*inst]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op1]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r2.getLower().sge(Zero)) {
                            if (!varMap.count(op1)) varMap[op1] = new Variable(op1);
                            Constraint* c = new LE(worklistEngine, varMap[op1], varMap[&*inst]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op1]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r2.getUpper().slt(Zero)) {
                            if (!varMap.count(op1)) varMap[op1] = new Variable(op1);
                            Constraint* c = new LT(worklistEngine, varMap[&*inst], varMap[op1]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op1]->constraints.insert(c);
                            worklistEngine->add(c);
                        } else if (r2.getUpper().sle(Zero)) {
                            if (!varMap.count(op1)) varMap[op1] = new Variable(op1);
                            Constraint* c = new LE(worklistEngine, varMap[&*inst], varMap[op1]);
                            NumConstraints++;
                            varMap[&*inst]->constraints.insert(c);
                            varMap[op1]->constraints.insert(c);
                            worklistEngine->add(c);
                        }
                    }
                    // Subtraction handling would follow similar pattern...
                }
            }
        }
    }

    bool runOnModule(Module& M) override {
        rangeAnalyzer = &getAnalysis<InterProceduralRACousot>();
        worklistEngine = new WorkListEngine();

        float startTime = (float)clock() / CLOCKS_PER_SEC;

        collectConstraints(M);
        NumVariablesConst = varMap.size();

        float phase1Duration = (float)clock() / CLOCKS_PER_SEC - startTime;
        phase1Time = phase1Duration;

        buildDepGraph(M);
        collectTypes();
        propagateTypes();

        for (auto& nodePair : nodeMap) {
            nodePair.second->computePathToRoot();
        }

        float phase2Duration = (float)clock() / CLOCKS_PER_SEC - startTime - phase1Time;
        phase2Time = phase2Duration;

        worklistEngine->solve();

        float phase3Duration = (float)clock() / CLOCKS_PER_SEC - startTime - phase1Time - phase2Time;
        phase3Time = phase3Duration;

        for (auto& varPair : varMap) {
            if (varPair.second->greaterThanSet.intersects(varPair.second->lessThanSet))
                NumEvil++;
        }

        errs() << "-------------------------\nResults: \n";
        for (auto& varPair : varMap) {
            varPair.second->printRelations(errs());
        }

        return false;
    }

    void buildDepGraph(Module& M) {
        // Implementation for building dependency graph
        // This would populate nodeMap with DepNode objects
    }

    void collectTypes() {
        // Implementation for collecting type information
    }

    void propagateTypes() {
        // Implementation for type propagation
    }
};

