#include "alignment.h"
#include "alignmentsummary.h"
#include <unordered_map>
#include <vector>

AlignmentSummary::AlignmentSummary(const Alignment* a,
                                   bool keepConstSites,
                                   bool keepBoringSites) {
    alignment = a;
    sequenceMatrix = nullptr;
    sequenceCount = a->getNSeq();
    totalFrequency = 0;
    totalFrequencyOfNonConstSites = 0;

    if (sequenceCount == 0) {
        minState = a->STATE_UNKNOWN;
        maxState = a->STATE_UNKNOWN;
        return;
    }

    // Helper structure to store per-site statistics
    struct SiteStats {
        bool     constant;
        int      freq;
        StateType lowState;
        StateType highState;
        SiteStats() : constant(false), freq(0), lowState(0), highState(0) {}
    };

    const std::size_t numSites = alignment->size();
    SiteStats* siteData = new SiteStats[numSites]; // Stack-allocated array for performance

#ifdef _OPENMP
#pragma omp parallel for
#endif
    for (std::size_t sIdx = 0; sIdx < numSites; ++sIdx) {
        auto siteIt = alignment->begin() + sIdx;
        SiteStats& stats = siteData[sIdx];

        StateType currMin = (*siteIt)[0];
        StateType currMax = currMin;
        stats.constant = siteIt->isConst();
        stats.freq = siteIt->frequency;

        for (std::size_t seqIdx = 1; seqIdx < sequenceCount; ++seqIdx) {
            StateType stateVal = (*siteIt)[seqIdx];
            if (stateVal < currMin) {
                currMin = stateVal;
            } else if (currMax < stateVal) {
                currMax = stateVal;
            }
        }

        stats.lowState = currMin;
        stats.highState = currMax;
    }

    sequenceLength = 0; // Count of retained non-trivial sites
    std::unordered_map<int, int> constStateFreqMap;

    for (std::size_t sIdx = 0; sIdx < numSites; ++sIdx) {
        SiteStats& stats = siteData[sIdx];
        bool includedInSummary = false;

        totalFrequency += stats.freq;
        if (!stats.constant) {
            totalFrequencyOfNonConstSites += stats.freq;
        }

        bool shouldInclude = (keepConstSites || !stats.constant);
        if (shouldInclude) {
            bool isInteresting = (0 < stats.freq && stats.lowState < stats.highState);
            if (keepBoringSites || isInteresting) {
                includedInSummary = true;

                if (sequenceLength == 0) {
                    minState = stats.lowState;
                    maxState = stats.highState;
                } else {
                    if (stats.lowState < minState) {
                        minState = stats.lowState;
                    }
                    if (maxState < stats.highState) {
                        maxState = stats.highState;
                    }
                }

                activeSiteIndices.push_back(sIdx);
                siteFrequencies.push_back(stats.freq);
                nonConstSiteFrequencies.push_back(stats.constant ? 0 : stats.freq);
                ++sequenceLength;
            }
        }

        // Accumulate frequencies for constant-only sites not included above
        if (stats.constant && !includedInSummary) {
            int stateKey = static_cast<int>(stats.lowState);
            auto existing = constStateFreqMap.find(stateKey);
            if (existing == constStateFreqMap.end()) {
                constStateFreqMap[stateKey] = stats.freq;
            } else {
                existing->second += stats.freq;
            }
        }
    }

    delete[] siteData;
}

AlignmentSummary::~AlignmentSummary() {
    delete[] sequenceMatrix;
    sequenceMatrix = nullptr;
    sequenceLength = 0;
    sequenceCount = 0;
}

size_t AlignmentSummary::getSumOfConstantSiteFrequenciesForState(int state) {
    auto iter = stateToSumOfConstantSiteFrequencies.find(state);
    return (iter == stateToSumOfConstantSiteFrequencies.end()) ? 0 : iter->second;
}

bool AlignmentSummary::constructSequenceMatrixNoisily(bool treatAllAmbiguousStatesAsUnknown,
                                                      const char* taskName,
                                                      const char* verb) {
    progress_display progress(sequenceCount, taskName, verb, "sequence");
    return constructSequenceMatrix(treatAllAmbiguousStatesAsUnknown, &progress);
}

bool AlignmentSummary::constructSequenceMatrix(bool treatAllAmbiguousStatesAsUnknown,
                                               progress_display* progress) {
    delete[] sequenceMatrix;
    sequenceMatrix = nullptr;

    if (minState < 0 || maxState > 127) {
        return false;
    }

    sequenceMatrix = new char[sequenceCount * sequenceLength];
    const std::vector<std::size_t>& siteMap = activeSiteIndices;

    if (treatAllAmbiguousStatesAsUnknown) {
#ifdef _OPENMP
#pragma omp parallel for
#endif
        for (std::size_t seqIdx = 0; seqIdx < sequenceCount; ++seqIdx) {
            char* outRow = sequenceMatrix + seqIdx * sequenceLength;
            for (std::size_t posIdx = 0; posIdx < sequenceLength; ++posIdx) {
                std::size_t originalSite = siteMap[posIdx];
                StateType rawState = alignment->at(originalSite)[seqIdx];
                if (rawState >= alignment->num_states) {
                    rawState = alignment->STATE_UNKNOWN;
                }
                outRow[posIdx] = static_cast<char>(rawState);
            }

            if (progress != nullptr && (seqIdx % 100) == 0) {
                *progress += 100;
            }
        }
    } else {
#ifdef _OPENMP
#pragma omp parallel for
#endif
        for (std::size_t seqIdx = 0; seqIdx < sequenceCount; ++seqIdx) {
            char* outRow = sequenceMatrix + seqIdx * sequenceLength;
            for (std::size_t posIdx = 0; posIdx < sequenceLength; ++posIdx) {
                std::size_t originalSite = siteMap[posIdx];
                outRow[posIdx] = static_cast<char>(alignment->at(originalSite)[seqIdx]);
            }

            if (progress != nullptr && (seqIdx % 100) == 0) {
                *progress += 100;
            }
        }
    }

    return true;
}

