bool FWmfMediaStreamSink::Create(const GUID& MajorType, TComPtr<FWmfMediaStreamSink>& OutSink)
{
	TComPtr<FWmfMediaStreamSink> NewStream = new FWmfMediaStreamSink(MajorType, 1);
	TComPtr<FWmfMediaSink> MediaSinkInstance = new FWmfMediaSink();
	if (!MediaSinkInstance->Initialize(NewStream))
	{
		return false;
	}
	OutSink = NewStream;
	return true;
}

/* FWmfMediaStreamSink structors
 *****************************************************************************/
FWmfMediaStreamSink::FWmfMediaStreamSink(const GUID& InMajorType, DWORD InStreamId)
	: Owner(nullptr)
	, Prerolling(false)
	, RefCount(0)
	, StreamIdentifier(InStreamId)
	, StreamKind(InMajorType)
	, PlaybackSpeed(1.0f)
	, TimerHandle(nullptr)
	, TextureSamplePool(nullptr)
	, DecodedFrameQueue(nullptr)
	, bSuppressSubtypeWarning(true)
{
	UE_LOG(LogWmfMedia, Verbose, TEXT("StreamSink %p: Created with stream type %s"), this, *WmfMedia::MajorTypeToString(StreamKind));
}

FWmfMediaStreamSink::~FWmfMediaStreamSink()
{
	check(RefCount == 0);
	UE_LOG(LogWmfMedia, Verbose, TEXT("StreamSink %p: Destroyed"), this);
}

/* FWmfMediaStreamSink interface
 *****************************************************************************/
bool FWmfMediaStreamSink::GetNextSample(TComPtr<IMFSample>& OutSample)
{
	FScopeLock Lock(&CriticalSection);
	for (int32 Index = 0; Index < SampleBuffer.Num(); ++Index)
	{
		FQueuedSample QueuedItem = SampleBuffer[Index];
		SampleBuffer.RemoveAt(Index);
		--Index;

		if (QueuedItem.Sample.IsValid())
		{
			OutSample = QueuedItem.Sample;
			return true;
		}
		else
		{
			// Handle pending marker
			QueueEvent(MEStreamSinkMarker, GUID_NULL, S_OK, QueuedItem.MarkerContext);
			PropVariantClear(QueuedItem.MarkerContext);
			delete QueuedItem.MarkerContext;
			UE_LOG(LogWmfMedia, Verbose, TEXT("StreamSink %p: Processed marker (%s)"), this, *WmfMedia::MarkerTypeToString(QueuedItem.MarkerType));
		}
	}
	return false;
}

bool FWmfMediaStreamSink::Initialize(FWmfMediaSink& InOwner)
{
	FScopeLock Lock(&CriticalSection);
	const HRESULT Result = ::MFCreateEventQueue(&EventQueue);
	if (FAILED(Result))
	{
		UE_LOG(LogWmfMedia, Verbose, TEXT("StreamSink %p: Failed to create event queue for stream sink: %s"), this, *WmfMedia::ResultToString(Result));
		return false;
	}
	Owner = &InOwner;
	return true;
}

HRESULT FWmfMediaStreamSink::Pause()
{
	FScopeLock Lock(&CriticalSection);
	return QueueEvent(MEStreamSinkPaused, GUID_NULL, S_OK, NULL);
}

HRESULT FWmfMediaStreamSink::Preroll()
{
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	IsPrerolling = true;
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p:Preroll Request Sample"), this);
	return QueueEvent(MEStreamSinkRequestSample, GUID_NULL, S_OK, NULL);
}

HRESULT FWmfMediaStreamSink::Restart()
{
	HRESULT Result = QueueEvent(MEStreamSinkStarted, GUID_NULL, S_OK, NULL);
	if (FAILED(Result))
	{
		return Result;
	}
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p:Restart Request Sample"), this);
	return QueueEvent(MEStreamSinkRequestSample, GUID_NULL, S_OK, NULL);
}

void FWmfMediaStreamSink::Shutdown()
{
	FScopeLock Lock(&CriticalSection);
	if (EventQueue.IsValid())
	{
		EventQueue->Shutdown();
		EventQueue.Reset();
	}
	ActiveMediaType.Reset();
	DestroyTimer();
}

HRESULT FWmfMediaStreamSink::Start()
{
	FScopeLock Lock(&CriticalSection);
	if (PlaybackSpeed != 0.0f && TimerHandle == nullptr)
	{
		timeBeginPeriod(1);
		TimerHandle = CreateWaitableTimer(NULL, FALSE, NULL);
		if (TimerHandle == nullptr)
		{
			HRESULT Result = HRESULT_FROM_WIN32(GetLastError());
			if (FAILED(Result))
			{
				return Result;
			}
		}
	}
	HRESULT Result = QueueEvent(MEStreamSinkStarted, GUID_NULL, S_OK, NULL);
	if (FAILED(Result))
	{
		return Result;
	}
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p:Start Request Sample"), this);
	return QueueEvent(MEStreamSinkRequestSample, GUID_NULL, S_OK, NULL);
}

HRESULT FWmfMediaStreamSink::Stop()
{
	Flush();
	FScopeLock Lock(&CriticalSection);
	timeEndPeriod(1);
	DestroyTimer();
	return QueueEvent(MEStreamSinkStopped, GUID_NULL, S_OK, NULL);
}

void FWmfMediaStreamSink::DestroyTimer()
{
	if (TimerHandle != nullptr)
	{
		CloseHandle(TimerHandle);
		TimerHandle = nullptr;
	}
}

