 *****************************************************************************/
STDMETHODIMP FWmfMediaStreamSink::GetCurrentMediaType(_Outptr_ IMFMediaType** ppMediaType)
{
	FScopeLock Lock(&CriticalSection);
	if (ppMediaType == NULL)
	{
		return E_POINTER;
	}
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	if (!ActiveMediaType.IsValid())
	{
		return MF_E_NOT_INITIALIZED;
	}
	*ppMediaType = ActiveMediaType;
	(*ppMediaType)->AddRef();
	return S_OK;
}

STDMETHODIMP FWmfMediaStreamSink::GetMajorType(__RPC__out GUID* pguidMajorType)
{
	if (pguidMajorType == NULL)
	{
		return E_POINTER;
	}
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	if (!ActiveMediaType.IsValid())
	{
		return MF_E_NOT_INITIALIZED;
	}
	return ActiveMediaType->GetGUID(MF_MT_MAJOR_TYPE, pguidMajorType);
}

STDMETHODIMP FWmfMediaStreamSink::GetMediaTypeByIndex(DWORD dwIndex, _Outptr_ IMFMediaType** ppType)
{
	if (ppType == NULL)
	{
		return E_POINTER;
	}
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	TArray<TComPtr<IMFMediaType>> SupportedTypes = WmfMedia::GetSupportedMediaTypes(StreamKind);
	if (!SupportedTypes.IsValidIndex(dwIndex))
	{
		return MF_E_NO_MORE_TYPES;
	}
	TComPtr<IMFMediaType> MediaTypeCandidate = SupportedTypes[dwIndex];
	if (!MediaTypeCandidate.IsValid())
	{
		return MF_E_INVALIDMEDIATYPE;
	}
	TComPtr<IMFMediaType> OutputType;
	{
		HRESULT Result = ::MFCreateMediaType(&OutputType);
		if (FAILED(Result))
		{
			return Result;
		}
		Result = MediaTypeCandidate->CopyAllItems(OutputType);
		if (FAILED(Result))
		{
			return Result;
		}
	}
	*ppType = OutputType;
	(*ppType)->AddRef();
	return S_OK;
}

STDMETHODIMP FWmfMediaStreamSink::GetMediaTypeCount(__RPC__out DWORD* pdwTypeCount)
{
	if (pdwTypeCount == NULL)
	{
		return E_POINTER;
	}
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	*pdwTypeCount = (DWORD)WmfMedia::GetSupportedMediaTypes(StreamKind).Num();
	return S_OK;
}

STDMETHODIMP FWmfMediaStreamSink::IsMediaTypeSupported(IMFMediaType* pMediaType, _Outptr_opt_result_maybenull_ IMFMediaType** ppMediaType)
{
	if (ppMediaType != NULL)
	{
		*ppMediaType = NULL;
	}
	if (pMediaType == NULL)
	{
		return E_POINTER;
	}
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Checking if media type is supported:\n%s"), this, *WmfMedia::DumpAttributes(*pMediaType));
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	GUID RequestedMajorType;
	{
		const HRESULT Result = pMediaType->GetGUID(MF_MT_MAJOR_TYPE, &RequestedMajorType);
		if (FAILED(Result))
		{
			return Result;
		}
	}
	if (RequestedMajorType != StreamKind)
	{
		UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Media type doesn't match stream type %s"), this, *WmfMedia::MajorTypeToString(StreamKind));
		return MF_E_INVALIDMEDIATYPE;
	}
	const DWORD CompareFlagsData = MF_MEDIATYPE_EQUAL_MAJOR_TYPES | MF_MEDIATYPE_EQUAL_FORMAT_TYPES | MF_MEDIATYPE_EQUAL_FORMAT_DATA;
	const DWORD CompareFlagsUserData = MF_MEDIATYPE_EQUAL_MAJOR_TYPES | MF_MEDIATYPE_EQUAL_FORMAT_TYPES | MF_MEDIATYPE_EQUAL_FORMAT_USER_DATA;
	for (const TComPtr<IMFMediaType>& MediaType : WmfMedia::GetSupportedMediaTypes(StreamKind))
	{
		if (!MediaType.IsValid())
		{
			continue;
		}
		DWORD Flags = 0;
		const HRESULT Result = MediaType->IsEqual(pMediaType, &Flags);
		if (SUCCEEDED(Result) && (((Flags & CompareFlagsData) == CompareFlagsData) || ((Flags & CompareFlagsUserData) == CompareFlagsUserData)))
		{
			UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Media type is supported"), this, *WmfMedia::MajorTypeToString(RequestedMajorType));
			return S_OK;
		}
	}
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Media type is not supported"), this);
	return MF_E_INVALIDMEDIATYPE;
}

STDMETHODIMP FWmfMediaStreamSink::SetCurrentMediaType(IMFMediaType* pMediaType)
{
	if (pMediaType == NULL)
	{
		return E_POINTER;
	}
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Setting current media type:\n%s"), this, *WmfMedia::DumpAttributes(*pMediaType));
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	const HRESULT Result = IsMediaTypeSupported(pMediaType, NULL);
	if (FAILED(Result))
	{
		UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Tried to set unsupported media type"), this);
		return Result;
	}
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p: Current media type set"), this);
	ActiveMediaType = pMediaType;
	return S_OK;
}

