STDMETHODIMP FWmfMediaStreamSink::Flush()
{
	FScopeLock Lock(&CriticalSection);
	if (!EventQueue.IsValid())
	{
		return MF_E_SHUTDOWN;
	}
	UE_LOG(LogWmfMedia, Verbose, TEXT("StreamSink %p: Flushing samples & markers"), this);
	while (SampleBuffer.Num() > 0)
	{
		FQueuedSample QueuedItem = SampleBuffer.Pop();
		if (QueuedItem.Sample.IsValid())
		{
			continue;
		}
		QueueEvent(MEStreamSinkMarker, GUID_NULL, E_ABORT, QueuedItem.MarkerContext);
		PropVariantClear(QueuedItem.MarkerContext);
		delete QueuedItem.MarkerContext;
	}
	return S_OK;
}

