bool FWmfMediaStreamSink::IsDecodedFrameQueueFull() const
{
	const int32 MaxFramesToBuffer = 3;
	const int32 MinAllowedDepth = FMath::Min(MaxFramesToBuffer, FMediaPlayerQueueDepths::MaxVideoSinkDepth);
	return (DecodedFrameQueue->Num() >= MinAllowedDepth);
}

void FWmfMediaStreamSink::CopyTextureAndEnqueueSample(IMFSample* pSample)
{
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("Queue Size: %d"), DecodedFrameQueue->Num());
	if (IsDecodedFrameQueueFull())
	{
		UE_LOG(LogWmfMedia, VeryVerbose, TEXT("Queue is full, dropping samples"));
		return;
	}
	DWORD BufferCount = 0;
	IMFMediaBuffer* Buffer = nullptr;
	IMFDXGIBuffer* DXGIBuffer = nullptr;
	UINT SubresourceIndex = 0;
	ID3D11Texture2D* SourceTexture = nullptr;
	HRESULT Result = pSample->GetBufferCount(&BufferCount);
	if (FAILED(Result))
	{
		return;
	}
	if (1 == BufferCount)
	{
		Result = pSample->GetBufferByIndex(0, &Buffer);
		if (FAILED(Result))
		{
			return;
		}
	}
	Result = Buffer->QueryInterface(__uuidof(IMFDXGIBuffer), (LPVOID*)&DXGIBuffer);
	if (FAILED(Result))
	{
		return;
	}
	Result = DXGIBuffer->GetResource(__uuidof(ID3D11Texture2D), (LPVOID*)&SourceTexture);
	if (FAILED(Result))
	{
		return;
	}
	Result = DXGIBuffer->GetSubresourceIndex(&SubresourceIndex);
	if (FAILED(Result))
	{
		return;
	}
	UINT32 Width;
	UINT32 Height;
	MFGetAttributeSize(ActiveMediaType, MF_MT_FRAME_SIZE, &Width, &Height);
	LONGLONG SampleTime = 0;
	LONGLONG SampleDuration = 0;
	pSample->GetSampleTime(&SampleTime);
	pSample->GetSampleDuration(&SampleDuration);
	GUID SubtypeGuid;
	if (SUCCEEDED(ActiveMediaType->GetGUID(MF_MT_SUBTYPE, &SubtypeGuid)))
	{
		const TSharedRef<FWmfMediaHardwareVideoDecodingTextureSample, ESPMode::ThreadSafe> TextureSample = TextureSamplePool->AcquireShared();
		check(TextureSample->GetMediaTextureSampleConverter()!=nullptr);
		EPixelFormat PixelFormat = PF_Unknown;
		EMediaTextureSampleFormat MediaTextureSampleFormat = EMediaTextureSampleFormat::Undefined;
		if (SubtypeGuid == MFVideoFormat_NV12)
		{
			PixelFormat = PF_NV12;
			MediaTextureSampleFormat = EMediaTextureSampleFormat::CharNV12;
		}
		else if (SubtypeGuid == MFVideoFormat_ARGB32)
		{
			PixelFormat = PF_B8G8R8A8;
			MediaTextureSampleFormat = EMediaTextureSampleFormat::CharBGRA;
		}
		else // if (SubtypeGuid == MFVideoFormat_Y416)
		{
			PixelFormat = PF_A16B16G16R16;
			MediaTextureSampleFormat = EMediaTextureSampleFormat::Y416;
		}
		ID3D11Texture2D* SharedTexture = TextureSample->InitializeSourceTexture(
			Owner->GetDevice(),
			FTimespan::FromMicroseconds(SampleTime / 10),
			FTimespan::FromMicroseconds(SampleDuration / 10),
			FIntPoint(Width, Height),
			PixelFormat,
			MediaTextureSampleFormat);
		D3D11_BOX SrcBox;
		SrcBox.left = 0;
		SrcBox.top = 0;
		SrcBox.front = 0;
		SrcBox.right = Width;
		SrcBox.bottom = Height;
		SrcBox.back = 1;
		UE_LOG(LogWmfMedia, VeryVerbose, TEXT("CopySubresourceRegion() ViewIndex:%d"), SubresourceIndex);
		TComPtr<IDXGIKeyedMutex> KeyedMutex;
		SharedTexture->QueryInterface(_uuidof(IDXGIKeyedMutex), (void**)&KeyedMutex);
		if (KeyedMutex)
		{
			if (KeyedMutex->AcquireSync(0, 0) == S_OK)
			{
				Owner->GetImmediateContext()->CopySubresourceRegion(SharedTexture, 0, 0, 0, 0, SourceTexture, SubresourceIndex, &SrcBox);
				KeyedMutex->ReleaseSync(1);
				DecodedFrameQueue->Enqueue(TextureSample);
			}
		}
	}
	else
	{
		if (bSuppressSubtypeWarning)
		{
			UE_LOG(LogWmfMedia, Log, TEXT("StreamSink %p: Unable to query MF_MT_SUBTYPE GUID of current media type"), this);
			bSuppressSubtypeWarning = false;
		}
	}
	if (SourceTexture)
	{
		SourceTexture->Release();
	}
	if (DXGIBuffer)
	{
		DXGIBuffer->Release();
	}
	if (Buffer)
	{
		Buffer->Release();
	}
}

STDMETHODIMP FWmfMediaStreamSink::Invoke(IMFAsyncResult* pAsyncResult)
{
	UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p:Invoke"), this);
	FScopeLock Lock(&CriticalSection);
	TComPtr<IMFSample> NextSample;
	if (GetNextSample(NextSample))
	{
		ScheduleWaitForNextSample(NextSample);
		return S_OK;
	}
	else
	{
		UE_LOG(LogWmfMedia, VeryVerbose, TEXT("StreamSink %p:Invoke Request Sample"), this);
		return QueueEvent(MEStreamSinkRequestSample, GUID_NULL, S_OK, NULL);
	}
}

