namespace quadrotor_msgs
{

bool decodeOutputData(const std::vector<uint8_t>& input_bytes,
                      quadrotor_msgs::OutputData& output_struct)
{
  struct OUTPUT_DATA raw_data;
  if(input_bytes.size() != sizeof(raw_data))
    return false;

  std::memcpy(&raw_data, input_bytes.data(), sizeof(raw_data));

  output_struct.loop_rate = raw_data.loop_rate;
  output_struct.voltage   = static_cast<double>(raw_data.voltage) / 1000.0;

  const double roll_rad  = raw_data.roll  * M_PI / (180.0 * 100.0);
  const double pitch_rad = raw_data.pitch * M_PI / (180.0 * 100.0);
  const double yaw_rad   = raw_data.yaw   * M_PI / (180.0 * 100.0);

  // Asctec (2012 firmware) uses Z-Y-X Euler angle convention
  Eigen::Quaterniond q = Eigen::AngleAxisd(yaw_rad,   Eigen::Vector3d::UnitZ()) *
                         Eigen::AngleAxisd(pitch_rad, Eigen::Vector3d::UnitY()) *
                         Eigen::AngleAxisd(roll_rad,  Eigen::Vector3d::UnitX());

  output_struct.orientation.w = q.w();
  output_struct.orientation.x = q.x();
  output_struct.orientation.y = q.y();
  output_struct.orientation.z = q.z();

  const double ang_vel_scale = 0.0154 * M_PI / 180.0;
  output_struct.angular_velocity.x = raw_data.ang_vel[0] * ang_vel_scale;
  output_struct.angular_velocity.y = raw_data.ang_vel[1] * ang_vel_scale;
  output_struct.angular_velocity.z = raw_data.ang_vel[2] * ang_vel_scale;

  const double acc_scale = 9.81 / 1000.0;
  output_struct.linear_acceleration.x = raw_data.acc[0] * acc_scale;
  output_struct.linear_acceleration.y = raw_data.acc[1] * acc_scale;
  output_struct.linear_acceleration.z = raw_data.acc[2] * acc_scale;

  output_struct.pressure_dheight = raw_data.dheight / 1000.0;
  output_struct.pressure_height  = raw_data.height  / 1000.0;

  const double mag_scale = 1.0 / 2500.0;
  output_struct.magnetic_field.x = raw_data.mag[0] * mag_scale;
  output_struct.magnetic_field.y = raw_data.mag[1] * mag_scale;
  output_struct.magnetic_field.z = raw_data.mag[2] * mag_scale;

  // Copy radio channels using standard algorithm
  std::copy_n(raw_data.radio, 8, output_struct.radio_channel);

  // Motor RPM decoding is commented out in original — left unchanged
  // for(int i = 0; i < 4; ++i)
  //   output_struct.motor_rpm[i] = raw_data.rpm[i];

  output_struct.seq = raw_data.seq;
  return true;
}

bool decodeStatusData(const std::vector<uint8_t>& input_bytes,
                      quadrotor_msgs::StatusData& status_struct)
{
  struct STATUS_DATA raw_data;
  if(input_bytes.size() != sizeof(raw_data))
    return false;

  std::memcpy(&raw_data, input_bytes.data(), sizeof(raw_data));

  status_struct.loop_rate = raw_data.loop_rate;
  status_struct.voltage   = static_cast<double>(raw_data.voltage) / 1000.0;
  status_struct.seq       = raw_data.seq;

  return true;
}

bool decodePPROutputData(const std::vector<uint8_t>& input_bytes,
                         quadrotor_msgs::PPROutputData& output_struct)
{
  struct PPR_OUTPUT_DATA raw_data;
  if(input_bytes.size() != sizeof(raw_data))
    return false;

  std::memcpy(&raw_data, input_bytes.data(), sizeof(raw_data));

  output_struct.quad_time     = raw_data.time;
  output_struct.des_thrust    = raw_data.des_thrust * 1e-4;
  output_struct.des_roll      = raw_data.des_roll   * 1e-4;
  output_struct.des_pitch     = raw_data.des_pitch  * 1e-4;
  output_struct.des_yaw       = raw_data.des_yaw    * 1e-4;
  output_struct.est_roll      = raw_data.est_roll   * 1e-4;
  output_struct.est_pitch     = raw_data.est_pitch  * 1e-4;
  output_struct.est_yaw       = raw_data.est_yaw    * 1e-4;
  output_struct.est_angvel_x  = raw_data.est_angvel_x * 1e-3;
  output_struct.est_angvel_y  = raw_data.est_angvel_y * 1e-3;
  output_struct.est_angvel_z  = raw_data.est_angvel_z * 1e-3;
  output_struct.est_acc_x     = raw_data.est_acc_x * 1e-4;
  output_struct.est_acc_y     = raw_data.est_acc_y * 1e-4;
  output_struct.est_acc_z     = raw_data.est_acc_z * 1e-4;

  output_struct.pwm[0] = raw_data.pwm1;
  output_struct.pwm[1] = raw_data.pwm2;
  output_struct.pwm[2] = raw_data.pwm3;
  output_struct.pwm[3] = raw_data.pwm4;

  return true;
}

