#include "client/entity/Entity.hpp"
#include "world/CT_World.hpp"

Entity::Entity(World* world) : worldRef(world) {}

void Entity::MoveTo(mc::Vector3f newPos, float newYaw, float newPitch) {
    newPos.y += verticalOffset;
    currentPos = newPos;
    prevPos = newPos;
    motionDelta = newPos;
    yawAngle = newYaw;
    pitchAngle = newPitch;
    UpdatePosition(newPos);
}

void Entity::MoveRelative(float dx, float dz, float moveSpeed) {
    float magSq = dx * dx + dz * dz;
    if (magSq < 0.01f) return;

    float scale = moveSpeed / std::sqrt(magSq);
    dx *= scale;
    dz *= scale;

    float yawRad = yawAngle * M_PI / 180.0f;
    float sYaw = std::sin(yawRad);
    float cYaw = std::cos(yawRad);

    motionDelta.x += dx * cYaw - dz * sYaw;
    motionDelta.z += dz * cYaw + dx * sYaw;
}

void Entity::SetRotation(float newYaw, float newPitch) {
    yawAngle = newYaw;
    pitchAngle = newPitch;
}

void Entity::UpdatePosition(mc::Vector3f const& pos) {
    currentPos = pos;
    float halfWidth = bodyWidth * 0.5f;
    float minY = pos.y - verticalOffset + slideYOffset;
    boundingBox = AABB(
        pos.x - halfWidth, minY,
        pos.z - halfWidth,
        pos.x + halfWidth, minY + bodyHeight,
        pos.z + halfWidth
    );
}

void Entity::RestorePosition() {}

void Entity::AdjustDimensions(float width, float height) {
    bodyWidth = width;
    bodyHeight = height;
}

void Entity::Rotate(float deltaYaw, float deltaPitch) {
    yawAngle += deltaYaw * 0.15f;
    pitchAngle -= deltaPitch * 0.15f;
    // Clamp pitch manually
    if (pitchAngle < -90.0f) pitchAngle = -90.0f;
    else if (pitchAngle > 90.0f) pitchAngle = 90.0f;

    // Normalize yaw to [0, 360)
    yawAngle = std::fmod(yawAngle, 360.0f);
    if (yawAngle < 0.0f) yawAngle += 360.0f;
}

void Entity::HandleFall(float dy, bool landed) {
    if (landed && fallDistance > 0.0f) {
        ApplyFallDamage(fallDistance);
        fallDistance = 0.0f;
    } else if (!landed && dy < 0.0f) {
        fallDistance -= dy;
    }
}

void Entity::ApplyFallDamage(float dist) {}

void Entity::UpdateState() {
    motionDelta = currentPos;
}

