// Helper typedefs
typedef HRESULT(WINAPI* p_SetThreadDesc)(void*, const wchar_t*);
#define THREAD_NAME_EXCEPTION_CODE ((DWORD)0x406D1388)

struct ThreadNameInfo {
    DWORD type;        // Must be 0x1000
    const char* name;  // UTF-8 / ASCII thread name
    DWORD threadId;
    DWORD flags;       // Reserved, must be zero
};

// Set thread name using modern API if available, fallback to legacy method
void AssignThreadName(DWORD targetThreadId, const char* threadName)
{
    if (!threadName) return;

    HMODULE hKernel = GetModuleHandleW(L"kernel32");
    if (!hKernel) return;

    p_SetThreadDesc setDesc = (p_SetThreadDesc)GetProcAddress(hKernel, "SetThreadDescription");
    if (setDesc)
    {
        HANDLE hThread = OpenThread(THREAD_SET_LIMITED_INFORMATION, FALSE, targetThreadId);
        if (!hThread)
            goto legacyFallback;

        wchar_t wideName[16] = {0};
        int converted = MultiByteToWideChar(CP_ACP, 0, threadName, -1, wideName, 16);
        if (converted > 0)
            setDesc(hThread, wideName);

        CloseHandle(hThread);
        return;
    }

legacyFallback:
    ThreadNameInfo info{};
    info.type = 0x1000;
    info.name = threadName;
    info.threadId = targetThreadId;
    info.flags = 0;

    __try {
        RaiseException(THREAD_NAME_EXCEPTION_CODE, 0, sizeof(info)/sizeof(DWORD), (DWORD*)&info);
    }
    __except (EXCEPTION_EXECUTE_HANDLER) {
        // Ignore exceptions during naming
    }
}
#endif

