HRESULT ProduceMiniDump(MINIDUMP_TYPE dumpFlags, EXCEPTION_POINTERS* sehData)
{
    HRESULT hr = S_OK;

    // Gather system metadata
    SYSTEMTIME currentTime;
    GetSystemTime(&currentTime);

    char computerName[MAX_COMPUTERNAME_LENGTH + 1] = {};
    DWORD compNameSize = ARRAYSIZE(computerName);
    GetComputerNameA(computerName, &compNameSize);

    // Format extra info manually (avoid snprintf dependency)
    char extraBuffer[1024];
    int written = sprintf_s(extraBuffer, sizeof(extraBuffer),
        "hostname=%s;datetime=%02u-%02u-%02u_%02u-%02u-%02u",
        computerName,
        currentTime.wDay, currentTime.wMonth, currentTime.wYear,
        currentTime.wHour, currentTime.wMinute, currentTime.wSecond);

    if (written < 0 || written >= (int)sizeof(extraBuffer))
        return E_FAIL;

    // Open core dump file
    HANDLE hFile = CreateFileA("core", GENERIC_READ | GENERIC_WRITE,
        FILE_SHARE_DELETE | FILE_SHARE_READ | FILE_SHARE_WRITE,
        nullptr, CREATE_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (hFile == INVALID_HANDLE_VALUE)
        return HRESULT_FROM_WIN32(GetLastError());

    HANDLE hProcess = GetCurrentProcess();
    DWORD processId = GetCurrentProcessId();

    // Prepare optional SEH data
    MINIDUMP_EXCEPTION_INFORMATION sehInfo = {};
    MINIDUMP_EXCEPTION_INFORMATION* sehPtr = nullptr;

    if (sehData)
    {
        sehInfo.ThreadId = GetCurrentThreadId();
        sehInfo.ExceptionPointers = sehData;
        sehInfo.ClientPointers = FALSE;
        sehPtr = &sehInfo;
    }

    // Prepare custom user stream
    MINIDUMP_USER_STREAM userStream = {};
    userStream.Type = CommentStreamA;
    userStream.Buffer = extraBuffer;
    userStream.BufferSize = static_cast<ULONG>(strlen(extraBuffer) + 1);

    MINIDUMP_USER_STREAM_INFORMATION userInfo = {};
    userInfo.UserStreamCount = 1;
    userInfo.UserStreamArray = &userStream;

    // Write dump
    BOOL success = MiniDumpWriteDump(hProcess, processId, hFile, dumpFlags,
        sehPtr, &userInfo, nullptr);

    if (!success)
        hr = HRESULT_FROM_WIN32(GetLastError());

    CloseHandle(hFile);
    return hr;
}

// Global SEH handler for fatal crashes
LONG WINAPI CrashHandler(EXCEPTION_POINTERS* exInfo)
{
    MessageBoxA(nullptr,
        "Critical failure detected. A crash dump has been saved as 'core'.\n"
        "Please upload this file when reporting issues.",
        "Fatal Exception", MB_ICONERROR | MB_TOPMOST);

    ProduceMiniDump(
        MiniDumpWithFullMemory |
        MiniDumpWithHandleData |
        MiniDumpWithThreadInfo |
        MiniDumpWithProcessThreadData |
        MiniDumpWithFullMemoryInfo |
        MiniDumpWithUnloadedModules |
        MiniDumpWithAuxiliaryState |
        MiniDumpIgnoreInaccessibleMemory |
        MiniDumpWithTokenInformation,
        exInfo);

    ExitProcess(127);
    return 0;
}
