void LineEdit::DeleteSelectedText()
{
    if (GetSelectionLength() == 0)
        return;

    int sel_begin = selection_anchor;
    int sel_end = selection_anchor + selection_extent;
    if (sel_begin > sel_end)
        std::swap(sel_begin, sel_end);

    content_text = content_text.substr(0, sel_begin) + 
                   content_text.substr(sel_end, content_text.size());

    caret_position = sel_begin;
    SetTextSelection(0, 0);

    int old_caret = GetCursorPos();
    SetCursorPos(0);
    SetCursorPos(old_caret);
}

void LineEdit::SetCursorPos(int pos)
{
    caret_position = pos;
    UpdateTextClipping();
    Update();
}

