void LineEdit::OnMouseMove(const Point& pos)
{
    if (drag_selecting)
    {
        if (pos.x < 0.0 || pos.x >= GetWidth())
        {
            if (pos.x < 0.0)
                drag_direction_left = true;
            else
                drag_direction_left = false;

            if (!is_readonly)
                drag_scroll_timer->Start(50, true);
        }
        else
        {
            drag_scroll_timer->Stop();
            caret_position = GetCharacterIndex(pos.x);
            SetSelectionLength(caret_position - selection_anchor);
            Update();
        }
    }
}

bool LineEdit::OnMouseDown(const Point& pos, InputKey key)
{
    if (key == InputKey::LeftMouse)
    {
        if (HasFocus())
        {
            SetPointerCapture();
            drag_selecting = true;
            caret_position = GetCharacterIndex(pos.x);
            SetTextSelection(caret_position, 0);
        }
        else
        {
            SetFocus();
        }
        Update();
    }
    return true;
}

bool LineEdit::OnMouseDoubleclick(const Point& pos, InputKey key)
{
    return true;
}

bool LineEdit::OnMouseUp(const Point& pos, InputKey key)
{
    if (drag_selecting && key == InputKey::LeftMouse)
    {
        drag_scroll_timer->Stop();
        ReleasePointerCapture();
        drag_selecting = false;

        int end_selection = GetCharacterIndex(pos.x);
        SetSelectionLength(end_selection - selection_anchor);
        caret_position = end_selection;
        Update();
    }
    return true;
}

void LineEdit::OnKeyChar(std::string chars)
{
    if (FuncFilterKeyChar)
    {
        chars = FuncFilterKeyChar(chars);
        if (chars.empty())
            return;
    }

    if (!chars.empty() && !(chars[0] >= 0 && chars[0] < 32))
    {
        if (FuncBeforeEditChanged)
            FuncBeforeEditChanged();

        DeleteSelectedText();

        if (input_mask_pattern.empty())
        {
            if (numeric_input_mode)
            {
                // '-' can only be added once, and only as the first character.
                if (chars == "-" && caret_position == 0 && content_text.find("-") == std::string::npos)
                {
                    if (InsertText(caret_position, chars))
                        caret_position += static_cast<int>(chars.size());
                }
                else if (allow_decimals_in_numeric && chars == decimal_separator && caret_position > 0)
                {
                    if (content_text.find(decimal_separator) == std::string::npos)
                    {
                        if (InsertText(caret_position, chars))
                            caret_position += static_cast<int>(chars.size());
                    }
                }
                else if (numeric_characters.find(chars) != std::string::npos)
                {
                    if (InsertText(caret_position, chars))
                        caret_position += static_cast<int>(chars.size());
                }
            }
            else
            {
                if (InsertText(caret_position, chars))
                    caret_position += static_cast<int>(chars.size());
            }
        }
        else
        {
            if (InputMaskAcceptsInput(caret_position, chars))
            {
                if (InsertText(caret_position, chars))
                    caret_position += static_cast<int>(chars.size());
            }
        }

        UpdateTextClipping();
        if (FuncAfterEditChanged)
            FuncAfterEditChanged();
    }
}

void LineEdit::OnKeyDown(InputKey key)
{
    if (FuncIgnoreKeyDown && FuncIgnoreKeyDown(key))
        return;

    if (key == InputKey::Enter)
    {
        if (FuncEnterPressed)
            FuncEnterPressed();
        return;
    }

    if (!is_readonly)
    {
        caret_visible = true;
        blink_timer->Start(500);
    }

    if (key == InputKey::Enter || key == InputKey::Escape || key == InputKey::Tab)
    {
        return;
    }
    else if (key == InputKey::A && GetKeyState(InputKey::Ctrl))
    {
        SetTextSelection(0, static_cast<int>(content_text.size()));
        caret_position = selection_extent;
        UpdateTextClipping();
        Update();
    }
    else if (key == InputKey::C && GetKeyState(InputKey::Ctrl))
    {
        if (!is_password_field)
        {
            std::string str = GetSelection();
            SetClipboardText(str);
        }
    }
    else if (is_readonly)
    {
        return;
    }
    else if (key == InputKey::Left)
    {
        Move(-1, GetKeyState(InputKey::Ctrl), GetKeyState(InputKey::Shift));
    }
    else if (key == InputKey::Right)
    {
        Move(1, GetKeyState(InputKey::Ctrl), GetKeyState(InputKey::Shift));
    }
    else if (key == InputKey::Backspace)
    {
        Backspace();
        UpdateTextClipping();
    }
    else if (key == InputKey::Delete)
    {
        Del();
        UpdateTextClipping();
    }
    else if (key == InputKey::Home)
    {
        SetSelectionStart(caret_position);
        caret_position = 0;
        if (GetKeyState(InputKey::Shift))
            SetSelectionLength(-selection_anchor);
        else
            SetTextSelection(0, 0);
        UpdateTextClipping();
        Update();
    }
    else if (key == InputKey::End)
    {
        SetSelectionStart(caret_position);
        caret_position = static_cast<int>(content_text.size());
        if (GetKeyState(InputKey::Shift))
            SetSelectionLength(static_cast<int>(content_text.size()) - selection_anchor);
        else
            SetTextSelection(0, 0);
        UpdateTextClipping();
        Update();
    }
    else if (key == InputKey::X && GetKeyState(InputKey::Ctrl))
    {
        std::string str = GetSelection();
        DeleteSelectedText();
        SetClipboardText(str);
        UpdateTextClipping();
    }
    else if (key == InputKey::V && GetKeyState(InputKey::Ctrl))
    {
        std::string str = GetClipboardText();
        std::string::const_iterator end_str = std::remove(str.begin(), str.end(), '\n');
        str.resize(end_str - str.begin());
        end_str = std::remove(str.begin(), str.end(), '\r');
        str.resize(end_str - str.begin());

        DeleteSelectedText();

        if (input_mask_pattern.empty())
        {
            if (numeric_input_mode)
            {
                std::string current_text = GetText();
                bool has_minus = current_text.find('-') != std::string::npos;
                bool paste_has_minus = str.find('-') != std::string::npos;

                if (!has_minus || !paste_has_minus)
                {
                    if ((!has_minus && !paste_has_minus) ||
                        (paste_has_minus && caret_position == 0 && str[0] == '-') ||
                        (has_minus && caret_position > 0))
                    {
                        if (allow_decimals_in_numeric)
                        {
                            std::string::size_type decimal_point_pos;
                            if ((decimal_point_pos = str.find_first_not_of(numeric_characters, str[0] == '-' ? 1 : 0)) == std::string::npos)
                            {
                                if (InsertText(caret_position, str))
                                    SetCursorPos(caret_position + static_cast<int>(str.length()));
                            }
                            else
                            {
                                if (current_text.find(decimal_separator) == std::string::npos &&
                                    str[decimal_point_pos] == decimal_separator[0] &&
                                    str.find_first_not_of(numeric_characters, decimal_point_pos + 1) == std::string::npos)
                                {
                                    if (InsertText(caret_position, str))
                                        SetCursorPos(caret_position + static_cast<int>(str.length()));
                                }
                            }
                        }
                        else
                        {
                            if (str.find_first_not_of(numeric_characters, str[0] == '-' ? 1 : 0) == std::string::npos)
                            {
                                if (InsertText(caret_position, str))
                                    SetCursorPos(caret_position + static_cast<int>(str.length()));
                            }
                        }
                    }
                }
            }
            else
            {
                if (InsertText(caret_position, str))
                    SetCursorPos(caret_position + static_cast<int>(str.length()));
            }
        }
        else
        {
            if (InputMaskAcceptsInput(caret_position, str))
            {
                if (InsertText(caret_position, str))
                    SetCursorPos(caret_position + static_cast<int>(str.length()));
            }
        }
        UpdateTextClipping();
    }
    else if (GetKeyState(InputKey::Ctrl) && key == InputKey::Z)
    {
        if (!is_readonly)
        {
            std::string tmp = undo_info.undo_text;
            undo_info.undo_text = GetText();
            SetText(tmp);
        }
    }
    else if (key == InputKey::Shift)
    {
        if (selection_anchor == -1)
            SetTextSelection(caret_position, 0);
    }

    if (FuncAfterEditChanged)
        FuncAfterEditChanged();
}

void LineEdit::OnKeyUp(InputKey key)
{
}

void LineEdit::OnSetFocus()
{
    if (!is_readonly)
        blink_timer->Start(500);

    if (select_all_on_focus)
        SelectAll();

    caret_position = static_cast<int>(content_text.length());
    Update();

    if (FuncFocusGained)
        FuncFocusGained();
}

void LineEdit::OnLostFocus()
{
    blink_timer->Stop();
    SetTextSelection(0, 0);
    Update();

    if (FuncFocusLost)
        FuncFocusLost();
}

void LineEdit::Move(int steps, bool ctrl, bool shift)
{
    if (shift && selection_extent == 0)
        SetSelectionStart(caret_position);

    if (ctrl)
    {
        if (steps < 0)
            steps = FindPreviousBreakCharacter(caret_position - 1) - caret_position;
        else
            steps = FindNextBreakCharacter(caret_position + 1) - caret_position;

        caret_position += steps;
        if (caret_position < 0)
            caret_position = 0;
        if (caret_position > static_cast<int>(content_text.size()))
            caret_position = static_cast<int>(content_text.size());
    }
    else
    {
        UTF8Reader utf8_reader(content_text.data(), content_text.length());
        utf8_reader.set_position(caret_position);

        if (steps > 0)
        {
            for (int i = 0; i < steps; i++)
                utf8_reader.next();
        }
        else if (steps < 0)
        {
            for (int i = 0; i < -steps; i++)
                utf8_reader.prev();
        }

        caret_position = static_cast<int>(utf8_reader.position());
    }

    if (shift)
        SetSelectionLength(caret_position - selection_anchor);
    else
        SetTextSelection(-1, 0);

    UpdateTextClipping();
    Update();
    undo_info.first_text_insert = true;
}

bool LineEdit::InsertText(int pos, const std::string& str)
{
    undo_info.first_erase = false;
    if (undo_info.first_text_insert)
    {
        undo_info.undo_text = GetText();
        undo_info.first_text_insert = false;
    }

    if (UTF8Reader::utf8_length(content_text) + UTF8Reader::utf8_length(str) > static_cast<size_t>(maximum_length))
    {
        return false;
    }

    if (force_lowercase)
        content_text.insert(pos, ConvertToLowercase(str));
    else if (force_uppercase)
        content_text.insert(pos, ConvertToUppercase(str));
    else
        content_text.insert(pos, str);

    UpdateTextClipping();
    Update();
    return true;
}

void LineEdit::Backspace()
{
    if (undo_info.first_erase)
    {
        undo_info.first_erase = false;
        undo_info.undo_text = GetText();
    }

    if (GetSelectionLength() != 0)
    {
        DeleteSelectedText();
        Update();
    }
    else
    {
        if (caret_position > 0)
        {
            UTF8Reader utf8_reader(content_text.data(), content_text.length());
            utf8_reader.set_position(caret_position);
            utf8_reader.prev();
            size_t length = utf8_reader.char_length();
            content_text.erase(caret_position - length, length);
            caret_position -= static_cast<int>(length);
            Update();
        }
    }

    int old_caret = GetCursorPos();
    SetCursorPos(0);
    SetCursorPos(old_caret);
}

void LineEdit::Del()
{
    if (undo_info.first_erase)
    {
        undo_info.first_erase = false;
        undo_info.undo_text = GetText();
    }

    if (GetSelectionLength() != 0)
    {
        DeleteSelectedText();
        Update();
    }
    else
    {
        if (caret_position < static_cast<int>(content_text.size()))
        {
            UTF8Reader utf8_reader(content_text.data(), content_text.length());
            utf8_reader.set_position(caret_position);
            size_t length = utf8_reader.char_length();
            content_text.erase(caret_position, length);
            Update();
        }
    }
}

int LineEdit::GetCharacterIndex(double mouse_x)
{
    if (content_text.size() <= 1)
    {
        return static_cast<int>(content_text.size());
    }

    Canvas* canvas = GetCanvas();
    if (!canvas)
        return 0;

    UTF8Reader utf8_reader(content_text.data(), content_text.length());
    int seek_start = clip_start_offset;
    int seek_end = static_cast<int>(content_text.size());
    int seek_center = (seek_start + seek_end) / 2;

    while (true)
    {
        utf8_reader.set_position(seek_center);
        utf8_reader.move_to_leadbyte();
        seek_center = static_cast<int>(utf8_reader.position());
        Size text_size = CalculateVisualTextSize(canvas, clip_start_offset, seek_center - clip_start_offset);

        if (text_size.width > mouse_x)
            seek_end = seek_center;
        else
            seek_start = seek_center;

        if (seek_end - seek_start < 7)
            break;

        seek_center = (seek_start + seek_end) / 2;
    }

    utf8_reader.set_position(seek_start);
    utf8_reader.move_to_leadbyte();

    while (true)
    {
        seek_center = static_cast<int>(utf8_reader.position());
        Size text_size = CalculateVisualTextSize(canvas, clip_start_offset, seek_center - clip_start_offset);

        if (text_size.width > mouse_x || utf8_reader.is_end())
            break;

        utf8_reader.next();
    }

    return seek_center;
}

void LineEdit::UpdateTextClipping()
{
    Canvas* canvas = GetCanvas();
    if (!canvas)
        return;

    if (caret_position < clip_start_offset)
        clip_start_offset = caret_position;

    Rect cursor_rect = GetCursorRect();
    UTF8Reader utf8_reader(content_text.data(), content_text.length());
    double width = GetWidth();

    while (cursor_rect.x + cursor_rect.width > width)
    {
        utf8_reader.set_position(clip_start_offset);
        utf8_reader.next();
        clip_start_offset = static_cast<int>(utf8_reader.position());
        if (clip_start_offset == static_cast<int>(content_text.size()))
            break;
        cursor_rect = GetCursorRect();
    }

    int search_upper = static_cast<int>(content_text.size());
    int search_lower = clip_start_offset;

    while (true)
    {
        int midpoint = (search_lower + search_upper) / 2;
        utf8_reader.set_position(midpoint);
        utf8_reader.move_to_leadbyte();

        if (midpoint != static_cast<int>(utf8_reader.position()))
            utf8_reader.next();

        midpoint = static_cast<int>(utf8_reader.position());

        if (midpoint == search_lower || midpoint == search_upper)
            break;

        Size midpoint_size = CalculateVisualTextSize(canvas, clip_start_offset, midpoint - clip_start_offset);

        if (width < midpoint_size.width)
            search_upper = midpoint;
        else
            search_lower = midpoint;
    }

    clip_end_offset = search_upper;

    if (cursor_rect.x < 0.0)
    {
        clip_start_offset = caret_position;
    }
}

Rect LineEdit::GetCursorRect()
{
    Canvas* canvas = GetCanvas();
    if (!canvas)
        return Rect::xywh(0.0, 0.0, 0.0, 0.0);

    int substr_end = caret_position - clip_start_offset;
    if (substr_end < 0)
        substr_end = 0;

    std::string clipped_text = content_text.substr(clip_start_offset, substr_end);

    if (is_password_field)
    {
        clipped_text = CreatePassword(UTF8Reader::utf8_length(clipped_text));
    }

    Size text_size_before_cursor = canvas->measureText(clipped_text).size();
    Rect cursor_rect;
    cursor_rect.x = text_size_before_cursor.width;
    cursor_rect.width = 1.0f;
    cursor_rect.y = vertical_text_align.top;
    cursor_rect.height = vertical_text_align.bottom - vertical_text_align.top;

    return cursor_rect;
}

Rect LineEdit::GetSelectionRect()
{
    Canvas* canvas = GetCanvas();
    if (!canvas)
        return Rect::xywh(0.0, 0.0, 0.0, 0.0);

    std::string txt_before = GetVisibleTextBeforeSelection();
    Size text_size_before_selection = canvas->measureText(txt_before).size();

    std::string txt_selected = GetVisibleSelectedText();
    Size text_size_selection = canvas->measureText(txt_selected).size();

    Rect selection_rect;
    selection_rect.x = text_size_before_selection.width;
    selection_rect.width = text_size_selection.width;
    selection_rect.y = vertical_text_align.top;
    selection_rect.height = vertical_text_align.bottom - vertical_text_align.top;

    return selection_rect;
}

int LineEdit::FindNextBreakCharacter(int search_start)
{
    if (search_start >= static_cast<int>(content_text.size()) - 1)
        return static_cast<int>(content_text.size());

    size_t pos = content_text.find_first_of(break_characters, search_start);
    if (pos == std::string::npos)
        return static_cast<int>(content_text.size());

    return static_cast<int>(pos);
}

int LineEdit::FindPreviousBreakCharacter(int search_start)
{
    if (search_start <= 0)
        return 0;

    size_t pos = content_text.find_last_of(break_characters, search_start);
    if (pos == std::string::npos)
        return 0;

    return static_cast<int>(pos);
}

void LineEdit::HandleBlinkTimeout()
{
    if (!IsVisible())
    {
        blink_timer->Stop();
        return;
    }

    if (caret_visible)
        blink_timer->Start(500);
    else
        blink_timer->Start(500);

    caret_visible = !caret_visible;
    Update();
}

void LineEdit::OnGeometryChanged()
{
    Canvas* canvas = GetCanvas();
    if (!canvas)
        return;

    vertical_text_align = canvas->verticalTextAlign();
    clip_start_offset = 0;
    caret_position = 0;
    UpdateTextClipping();
}

std::string LineEdit::GetVisibleTextBeforeSelection()
{
    std::string ret;
    int sel_begin = std::min(selection_anchor, selection_anchor + selection_extent);
    int start = std::min(sel_begin, clip_start_offset);

    if (start < clip_start_offset)
        return ret;

    int end = std::min(sel_begin, clip_end_offset);
    ret = content_text.substr(start, end - start);

    if (is_password_field)
        ret = CreatePassword(UTF8Reader::utf8_length(ret));

    return ret;
}

std::string LineEdit::GetVisibleSelectedText()
{
    std::string ret;

    if (selection_extent == 0)
        return ret;

    int sel_begin = std::min(selection_anchor, selection_anchor + selection_extent);
    int sel_end = std::max(selection_anchor, selection_anchor + selection_extent);

    int end = std::min(clip_end_offset, sel_end);
    int start = std::max(clip_start_offset, sel_begin);

    if (start > end)
        return ret;
    if (start == end)
        return ret;

    ret = content_text.substr(start, end - start);

    if (is_password_field)
        ret = CreatePassword(UTF8Reader::utf8_length(ret));

    return ret;
}

void LineEdit::SetSelectionStart(int start)
{
    if (FuncSelectionChanged && selection_extent && selection_anchor != start)
        FuncSelectionChanged();

    selection_anchor = start;
}

void LineEdit::SetSelectionLength(int length)
{
    if (FuncSelectionChanged && selection_extent != length)
        FuncSelectionChanged();

    selection_extent = length;
}

void LineEdit::SetTextSelection(int start, int length)
{
    if (FuncSelectionChanged && (selection_extent != length || (selection_extent && selection_anchor != start)))
        FuncSelectionChanged();

    selection_anchor = start;
    selection_extent = length;
}

std::string LineEdit::GetVisibleTextAfterSelection()
{
    std::string ret;
    int sel_end = std::max(selection_anchor, selection_anchor + selection_extent);
    int start = std::max(clip_start_offset, sel_end);
    int end = clip_end_offset;

    if (start > end)
        return ret;
    if (clip_end_offset == sel_end)
        return ret;
    if (sel_end <= 0)
        return ret;
    else
    {
        ret = content_text.substr(start, end - start);
        if (is_password_field)
            ret = CreatePassword(UTF8Reader::utf8_length(ret));
        return ret;
    }
}

void LineEdit::OnPaint(Canvas* canvas)
{
    std::string txt_before = GetVisibleTextBeforeSelection();
    std::string txt_selected = GetVisibleSelectedText();
    std::string txt_after = GetVisibleTextAfterSelection();

    if (txt_before.empty() && txt_selected.empty() && txt_after.empty())
    {
        txt_after = content_text.substr(clip_start_offset, clip_end_offset - clip_start_offset);
        if (is_password_field)
            txt_after = CreatePassword(UTF8Reader::utf8_length(txt_after));
    }

    Size size_before = canvas->measureText(txt_before).size();
    Size size_selected = canvas->measureText(txt_selected).size();

    if (!txt_selected.empty())
    {
        Rect selection_rect = GetSelectionRect();
        canvas->fillRect(selection_rect, HasFocus() ? GetStyleColor("selection-color") : GetStyleColor("no-focus-selection-color"));
    }

    if (!txt_before.empty())
    {
        canvas->drawText(Point(0.0, canvas->verticalTextAlign().baseline), GetStyleColor("color"), txt_before);
    }

    if (!txt_selected.empty())
    {
        canvas->drawText(Point(size_before.width, canvas->verticalTextAlign().baseline), GetStyleColor("selection-text"), txt_selected);
    }

    if (!txt_after.empty())
    {
        canvas->drawText(Point(size_before.width + size_selected.width, canvas->verticalTextAlign().baseline), GetStyleColor("color"), txt_after);
    }

    if (HasFocus())
    {
        if (caret_visible)
        {
            Rect cursor_rect = GetCursorRect();
            canvas->fillRect(cursor_rect, GetStyleColor("color"));
        }
    }
}

