std::string LineEdit::FormatFixedPoint(float number, int num_decimal_places)
{
    for (int i = 0; i < num_decimal_places; i++)
        number *= 10.0f;

    std::string val = std::to_string(static_cast<int>(std::round(number)));

    if (static_cast<int>(val.size()) < num_decimal_places)
        val.resize(num_decimal_places + 1, 0);

    return val.substr(0, val.size() - num_decimal_places) + "." + 
           val.substr(val.size() - num_decimal_places);
}

