HttpThread::HttpThread(std::string const & url, downloader::IHttpThreadCallback & cb,
                       int64_t startOffset, int64_t endOffset, int64_t totalSize,
                       std::string const & payload)
  : m_callback(cb)
  , m_startPos(startOffset)
  , m_endPos(endOffset)
  , m_bytesReceived(0)
  , m_expectedTotal(totalSize)
{
  QUrl const qUrl(url.c_str());
  QNetworkRequest req(qUrl);

  // Apply Range header only when partial content is requested
  bool const needRange = !(startOffset == 0 && endOffset < 0);
  if (needRange)
  {
    if (endOffset > 0)
    {
      LOG(LDEBUG, (url, "fetching byte range [", startOffset, ",", endOffset, "]"));
      QString rangeHeader = QString("bytes=%1-%2")
                              .arg(static_cast<qint64>(startOffset))
                              .arg(static_cast<qint64>(endOffset));
      req.setRawHeader("Range", rangeHeader.toUtf8());
    }
    else
    {
      LOG(LDEBUG, (url, "resuming from offset", startOffset));
      QString resumeHeader = QString("bytes=%1-")
                               .arg(static_cast<qint64>(startOffset));
      req.setRawHeader("Range", resumeHeader.toUtf8());
    }
  }

  static QNetworkAccessManager netMgr;
  if (payload.empty())
  {
    m_reply = netMgr.get(req);
  }
  else
  {
    req.setRawHeader("Content-Type", "application/json");
    req.setRawHeader("Content-Length", QString::number(payload.size()).toLocal8Bit());
    m_reply = netMgr.post(req, QByteArray::fromStdString(payload));
  }

  connect(m_reply, &QNetworkReply::metaDataChanged, this, &HttpThread::OnHeadersProcessed);
  connect(m_reply, &QNetworkReply::readyRead, this, &HttpThread::OnDataArrived);
  connect(m_reply, &QNetworkReply::finished, this, &HttpThread::OnTransferCompleted);

  LOG(LDEBUG, ("Initiating request to", url, "[", startOffset, ",", endOffset, "] size=", totalSize));
}

HttpThread::~HttpThread()
{
  LOG(LDEBUG, ("Releasing HttpThread resources"));
  disconnect(m_reply, &QNetworkReply::metaDataChanged, this, &HttpThread::OnHeadersProcessed);
  disconnect(m_reply, &QNetworkReply::readyRead, this, &HttpThread::OnDataArrived);
  disconnect(m_reply, &QNetworkReply::finished, this, &HttpThread::OnTransferCompleted);
  m_reply->deleteLater();
}

void HttpThread::OnHeadersProcessed()
{
  if (m_reply->error())
    return;

  int const statusCode = m_reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();

  bool const isPartial = !(m_startPos == 0 && m_endPos < 0);
  bool const isValidStatus = isPartial ? (statusCode == 206) : (statusCode == 200);

  if (!isValidStatus)
  {
    LOG(LWARNING, ("HTTP request to", m_reply->url().toEncoded().constData(),
                   "failed: expected", isPartial ? "206" : "200", "got", statusCode));
    m_reply->abort();
  }
  else if (m_expectedTotal > 0)
  {
    bool sizeVerified = false;

    if (m_reply->hasRawHeader("Content-Range"))
    {
      QList<QByteArray> parts = m_reply->rawHeader("Content-Range").split('/');
      if (parts.size() >= 2)
      {
        qint64 const serverSize = parts.back().toLongLong();
        if (serverSize != m_expectedTotal)
        {
          LOG(LWARNING, ("Content-Range mismatch:", serverSize, "vs expected", m_expectedTotal));
          m_reply->abort();
        }
        else
        {
          sizeVerified = true;
        }
      }
    }

    if (!sizeVerified && m_reply->hasRawHeader("Content-Length"))
    {
      qint64 const len = m_reply->rawHeader("Content-Length").toLongLong();
      if (len != m_expectedTotal)
      {
        LOG(LWARNING, ("Content-Length mismatch:", len, "vs expected", m_expectedTotal));
        m_reply->abort();
      }
      else
      {
        sizeVerified = true;
      }
    }

    if (!sizeVerified)
    {
      LOG(LWARNING, ("Server did not provide valid size information"));
      m_reply->abort();
    }
  }
}

void HttpThread::OnDataArrived()
{
  QByteArray chunk = m_reply->readAll();
  int const bytesRead = chunk.size();
  m_bytesReceived += bytesRead;

  int64_t const currentOffset = m_startPos + m_bytesReceived - bytesRead;
  m_callback.OnWrite(currentOffset, chunk.constData(), bytesRead);
}

void HttpThread::OnTransferCompleted()
{
  if (m_reply->error() != QNetworkReply::NoError)
  {
    int const httpCode = m_reply->attribute(QNetworkRequest::HttpStatusCodeAttribute).toInt();
    LOG(LWARNING, ("Download terminated with status", httpCode,
                   "and error:", m_reply->errorString().toStdString()));
    m_callback.OnFinish(httpCode, m_startPos, m_endPos);
  }
  else
  {
    m_callback.OnFinish(200, m_startPos, m_endPos);
  }
}

