#include "lz4.h"
#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>

// Configuration constants
enum {
    BLOCK_SIZE = 8 * 1024,  // 8KB blocks (same as original BLOCK_BYTES)
};

// Helper functions for file I/O
size_t write_integer(FILE* fp, int value) {
    return fwrite(&value, sizeof(value), 1, fp);
}

size_t write_bytes(FILE* fp, const void* data, size_t byteCount) {
    return fwrite(data, 1, byteCount, fp);
}

size_t read_integer(FILE* fp, int* outValue) {
    return fread(outValue, sizeof(*outValue), 1, fp);
}

size_t read_bytes(FILE* fp, void* buffer, size_t byteCount) {
    return fread(buffer, 1, byteCount, fp);
}

// Compress input file to LZ4 stream format
void compress_data(FILE* output, FILE* input) {
    LZ4_stream_t compressionContext;
    LZ4_initStream(&compressionContext);

    char inputBuffer[2][BLOCK_SIZE];
    int currentInputIndex = 0;

    for (;;) {
        char* currentInputPtr = inputBuffer[currentInputIndex];
        int bytesRead = (int)read_bytes(input, currentInputPtr, BLOCK_SIZE);

        if (bytesRead == 0) {
            break;  // End of input
        }

        // Compress the block
        char compressedBuffer[LZ4_COMPRESSBOUND(BLOCK_SIZE)];
        int compressedSize = LZ4_compress_fast_continue(
            &compressionContext,
            currentInputPtr,
            compressedBuffer,
            bytesRead,
            LZ4_COMPRESSBOUND(BLOCK_SIZE),
            1  // acceleration factor
        );

        if (compressedSize <= 0) {
            break;  // Compression failed
        }

        // Write compressed size and data
        write_integer(output, compressedSize);
        write_bytes(output, compressedBuffer, (size_t)compressedSize);

        // Toggle buffer index
        currentInputIndex = (currentInputIndex + 1) % 2;
    }

    // End marker: zero-sized block
    write_integer(output, 0);
}

// Decompress LZ4 stream back to original data
void decompress_data(FILE* output, FILE* input) {
    LZ4_streamDecode_t decompressionContext;
    LZ4_initStreamDecode(&decompressionContext, NULL, 0);

    char outputBuffer[2][BLOCK_SIZE];
    int currentOutputIndex = 0;

    for (;;) {
        char compressedBlock[LZ4_COMPRESSBOUND(BLOCK_SIZE)];
        int compressedSize = 0;

        // Read compressed block size
        if (read_integer(input, &compressedSize) != 1 || compressedSize <= 0) {
            break;  // End of stream or error
        }

        // Read compressed data
        if (read_bytes(input, compressedBlock, (size_t)compressedSize) != (size_t)compressedSize) {
            break;  // Incomplete read
        }

        // Decompress
        char* currentOutputPtr = outputBuffer[currentOutputIndex];
        int decompressedSize = LZ4_decompress_safe_continue(
            &decompressionContext,
            compressedBlock,
            currentOutputPtr,
            compressedSize,
            BLOCK_SIZE
        );

        if (decompressedSize <= 0) {
            break;  // Decompression failed
        }

        // Write decompressed data
        write_bytes(output, currentOutputPtr, (size_t)decompressedSize);

        // Toggle buffer index
        currentOutputIndex = (currentOutputIndex + 1) % 2;
    }
}

// Compare two files byte-by-byte
int compare_files(FILE* fileA, FILE* fileB) {
    while (true) {
        unsigned char bufferA[65536];
        unsigned char bufferB[65536];

        size_t bytesReadA = read_bytes(fileA, bufferA, sizeof(bufferA));
        size_t bytesReadB = read_bytes(fileB, bufferB, sizeof(bufferB));

        if (bytesReadA != bytesReadB) {
            return (int)(bytesReadA - bytesReadB);
        }

        if (bytesReadA == 0) {
            return 0;  // Both ended at same time
        }

        int diff = memcmp(bufferA, bufferB, bytesReadA);
        if (diff != 0) {
            return diff;
        }
    }
}

int main(int argc, char* argv[]) {
    char inputFile[256] = {0};
    char lz4File[256] = {0};
    char outputFile[256] = {0};

    if (argc < 2) {
        printf("Usage: %s <input_file>\n", argv[0]);
        return 1;
    }

    // Generate filenames
    snprintf(inputFile, sizeof(inputFile), "%s", argv[1]);
    snprintf(lz4File, sizeof(lz4File), "%s.lz4s-%d", argv[1], BLOCK_SIZE);
    snprintf(outputFile, sizeof(outputFile), "%s.lz4s-%d.dec", argv[1], BLOCK_SIZE);

    printf("Input file   : %s\n", inputFile);
    printf("Compressed   : %s\n", lz4File);
    printf("Decompressed : %s\n", outputFile);

    // Step 1: Compress
    {
        FILE* inFp = fopen(inputFile, "rb");
        FILE* outFp = fopen(lz4File, "wb");

        if (!inFp || !outFp) {
            printf("Error opening files for compression\n");
            return 1;
        }

        printf("Compressing...\n");
        compress_data(outFp, inFp);
        printf("Compression complete.\n");

        fclose(inFp);
        fclose(outFp);
    }

    // Step 2: Decompress
    {
        FILE* inFp = fopen(lz4File, "rb");
        FILE* outFp = fopen(outputFile, "wb");

        if (!inFp || !outFp) {
            printf("Error opening files for decompression\n");
            return 1;
        }

        printf("Decompressing...\n");
        decompress_data(outFp, inFp);
        printf("Decompression complete.\n");

        fclose(inFp);
        fclose(outFp);
    }

    // Step 3: Verify
    {
        FILE* origFp = fopen(inputFile, "rb");
        FILE* decFp = fopen(outputFile, "rb");

        if (!origFp || !decFp) {
            printf("Error opening files for verification\n");
            return 1;
        }

        printf("Verifying integrity...\n");
        int result = compare_files(origFp, decFp);

        if (result == 0) {
            printf("Verification successful: files match.\n");
        } else {
            printf("Verification failed: files differ.\n");
        }

        fclose(origFp);
        fclose(decFp);
    }

    return 0;
}

#include "WrappedValue.h"
#include "Parser/ValueType.h"

WrappedValue::WrappedValue() { }

// Helper lambda to create an alloca + store sequence for non-pointer values
static auto makeAllocaWithStore = [](llvm::IRBuilder<>& builder, llvm::Type* type, llvm::Value* val) -> llvm::AllocaInst* {
    auto* alloc = builder.CreateAlloca(type, nullptr);
    builder.CreateStore(val, alloc);
    return alloc;
};

shared_ptr<WrappedValue> WrappedValue::wrappedValue(shared_ptr<llvm::Module> module,
                                                    shared_ptr<llvm::IRBuilder<>> builder,
                                                    llvm::Value *value,
                                                    shared_ptr<ValueType> valueType) {
    auto result = make_shared<WrappedValue>();
    result->valueType = valueType;

    if (auto* load = llvm::dyn_cast<llvm::LoadInst>(value)) {
        result->valueLambda = [load]() { return load; };
        result->pointerValueLambda = [load]() { return load->getPointerOperand(); };
        result->type = load->getType();
    }
    else if (auto* alloc = llvm::dyn_cast<llvm::AllocaInst>(value)) {
        result->valueLambda = [builder, alloc]() {
            return builder->CreateLoad(alloc->getAllocatedType(), alloc);
        };
        result->pointerValueLambda = [alloc]() { return alloc; };
        result->type = alloc->getAllocatedType();
    }
    else if (auto* call = llvm::dyn_cast<llvm::CallInst>(value)) {
        auto* funTy = call->getFunctionType();
        auto* retTy = funTy->getReturnType();

        if (retTy->isVoidTy()) {
            result->valueLambda = [retTy]() { return llvm::UndefValue::get(retTy); };
            result->pointerValueLambda = [retTy]() { return llvm::UndefValue::get(retTy); };
        } else {
            result->valueLambda = [call]() { return call; };
            result->pointerValueLambda = [builder, retTy, call]() {
                return makeAllocaWithStore(*builder, retTy, call);
            };
        }
        result->type = retTy;
    }
    else if (auto* arg = llvm::dyn_cast<llvm::Argument>(value)) {
        auto* ty = arg->getType();
        result->valueLambda = [arg]() { return arg; };
        result->pointerValueLambda = [builder, ty, arg]() {
            return makeAllocaWithStore(*builder, ty, arg);
        };
        result->type = ty;
    }
    else if (auto* global = llvm::dyn_cast<llvm::GlobalVariable>(value)) {
        result->valueLambda = [global]() { return global; };
        result->pointerValueLambda = [global]() { return global; };
        result->type = global->getValueType();
    }
    else if (auto* constant = llvm::dyn_cast<llvm::Constant>(value)) {
        if (constant->getType()->isVoidTy()) {
            return wrappedNone(constant->getType(), valueType);
        }
        result->valueLambda = [constant]() { return constant; };
        result->pointerValueLambda = [module, constant]() {
            return new llvm::GlobalVariable(
                *module,
                constant->getType(),
                /* isConstant */ true,
                llvm::GlobalValue::LinkageTypes::PrivateLinkage,
                constant
            );
        };
        result->type = constant->getType();
    }
    else {
        // Fallback: any other value type
        auto* valTy = value->getType();
        result->valueLambda = [value]() { return value; };
        result->pointerValueLambda = [builder, valTy, value]() {
            return makeAllocaWithStore(*builder, valTy, value);
        };
        result->type = valTy;
    }

    return result;
}

shared_ptr<WrappedValue> WrappedValue::wrappedUIntValue(llvm::Type *type, uint64_t value, shared_ptr<ValueType> valueType) {
    auto res = make_shared<WrappedValue>();
    res->valueLambda = [type, value]() {
        return llvm::ConstantInt::get(type, value, false);
    };
    res->pointerValueLambda = [type, value]() {
        return llvm::ConstantInt::get(type, value, false);
    };
    res->type = type;
    res->valueType = valueType;
    return res;
}

shared_ptr<WrappedValue> WrappedValue::wrappedNone(llvm::Type *type, shared_ptr<ValueType> valueType) {
    auto res = make_shared<WrappedValue>();
    res->valueLambda = [type]() { return llvm::UndefValue::get(type); };
    res->pointerValueLambda = [type]() { return llvm::UndefValue::get(type); };
    res->type = type;
    res->valueType = valueType;
    return res;
}

llvm::Value *WrappedValue::getValue() {
    if (!value) {
        value = valueLambda();
    }
    return value;
}

llvm::Value *WrappedValue::getPointerValue() {
    if (!pointerValue) {
        pointerValue = pointerValueLambda();
    }
    return pointerValue;
}

llvm::Constant *WrappedValue::getConstantValue() {
    return llvm::dyn_cast<llvm::Constant>(getValue());
}

llvm::GlobalVariable *WrappedValue::getGlobalValue() {
    return llvm::dyn_cast<llvm::GlobalVariable>(getValue());
}

llvm::Type *WrappedValue::getType() {
    return type;
}

llvm::ArrayType *WrappedValue::getArrayType() {
    return llvm::dyn_cast<llvm::ArrayType>(type);
}

llvm::StructType *WrappedValue::getStructType() {
    return llvm::dyn_cast<llvm::StructType>(type);
}

shared_ptr<ValueType> WrappedValue::getValueType() {
    return valueType;
}

bool WrappedValue::isArray() {
    return valueType->isData();
}

bool WrappedValue::isPointer() {
    return valueType->isPointer();
}

bool WrappedValue::isStruct() {
    return valueType->isBlob();
}

