GlyphLines GlyphLinesBuilder::build(const Lines& lines, Font* font, FontManager* font_manager)
{
    std::vector<GlyphLine> result_lines;
    result_lines.reserve(lines.size());

    int idx = 0;
    while (idx < static_cast<int>(lines.size())) {
        result_lines.emplace_back(build(lines.getLines()[idx], font, font_manager));
        ++idx;
    }

    float height = font->getLineHeight();
    return GlyphLines(result_lines, height);
}

GlyphLine GlyphLinesBuilder::build(const Line& line, Font* font, FontManager* font_manager)
{
    std::vector<GlyphAtom> atoms;
    atoms.reserve(line.size());

    auto raw_atoms = line.getAtoms();
    int pos = 0;
    while (pos < static_cast<int>(line.size())) {
        atoms.emplace_back(build(raw_atoms[pos], font, font_manager));
        ++pos;
    }

    return GlyphLine(atoms);
}

GlyphAtom GlyphLinesBuilder::build(const Atom& atom, Font* font, FontManager* font_manager)
{
    auto text_content = atom.getContents();
    bool needs_bold = atom.getFace().hasAttribute(Attribute::Bold);
    bool needs_italic = atom.getFace().hasAttribute(Attribute::Italic);

    Font* current_font = font;

    if (needs_bold || needs_italic) {
        FontStyle requested_style;
        if (needs_bold && needs_italic) {
            requested_style = FontStyle::BoldItalic;
        } else if (needs_bold) {
            requested_style = FontStyle::Bold;
        } else {
            requested_style = FontStyle::Italic;
        }

        Font* alt_font = font_manager->getFontStyleVariant(font, requested_style);
        if (alt_font != nullptr) {
            current_font = alt_font;
        }
    }

    auto glyph_runs = buildGlyphRuns(text_content, current_font, font_manager);
    return GlyphAtom(glyph_runs, atom.getFace());
}

std::vector<GlyphRun> GlyphLinesBuilder::buildGlyphRuns(const UTF8String& contents, Font* font, FontManager* font_manager)
{
    std::vector<GlyphRun> output_runs;
    if (contents.empty()) {
        return output_runs;
    }

    std::vector<GlyphMetrics> batch_glyphs;
    Font* active_font = nullptr;

    int i = 0;
    while (i < static_cast<int>(contents.size())) {
        Codepoint cp;
        char ch = contents.at(i);

        if (ch == '\n') {
            cp = ' ';
        } else if (isControlCharacter(ch)) {
            ++i;
            continue;
        } else {
            cp = ch;
        }

        auto glyph_info = font_manager->getGlyphWithFont(cp, font);
        if (active_font == nullptr || active_font == glyph_info.font) {
            active_font = glyph_info.font;
            batch_glyphs.push_back(glyph_info.glyph);
        } else {
            output_runs.emplace_back(batch_glyphs, active_font);
            batch_glyphs.clear();
            active_font = glyph_info.font;
            batch_glyphs.push_back(glyph_info.glyph);
        }

        ++i;
    }

    if (!batch_glyphs.empty()) {
        output_runs.emplace_back(batch_glyphs, active_font);
    }

    return output_runs;
}

std::vector<GlyphRun> GlyphLinesBuilder::buildGlyphRuns(const UTF8String& contents, Font* font)
{
    std::vector<GlyphMetrics> glyphs;
    glyphs.reserve(contents.size());

    int j = 0;
    while (j < static_cast<int>(contents.size())) {
        font->loadGlyph(contents.at(j));
        glyphs.push_back(font->getGlyphMetrics(contents.at(j)));
        ++j;
    }

    std::vector<GlyphRun> runs;
    if (!glyphs.empty()) {
        runs.emplace_back(glyphs, font);
    }

    return runs;
}

GlyphLines GlyphLinesBuilder::build(const Lines& lines, Font* font)
{
    std::vector<GlyphLine> glyph_lines;
    glyph_lines.reserve(lines.size());

    int k = 0;
    while (k < static_cast<int>(lines.size())) {
        glyph_lines.emplace_back(build(lines.getLines()[k], font));
        ++k;
    }

    float h = font->getLineHeight();
    return GlyphLines(glyph_lines, h);
}

GlyphLine GlyphLinesBuilder::build(const Line& line, Font* font)
{
    std::vector<GlyphAtom> atoms;
    atoms.reserve(line.size());

    auto raw_atoms = line.getAtoms();
    int m = 0;
    while (m < static_cast<int>(line.size())) {
        atoms.emplace_back(build(raw_atoms[m], font));
        ++m;
    }

    return GlyphLine(atoms);
}

GlyphAtom GlyphLinesBuilder::build(const Atom& atom, Font* font)
{
    auto content = atom.getContents();
    auto runs = buildGlyphRuns(content, font);
    return GlyphAtom(runs, atom.getFace());
}

