unsigned packet_decoder_mp3_common::parseDecoderSetup( const GUID & ownerID, t_size param1, const void * param2, t_size param2Size )
{
    if (ownerID == owner_MP3) return 3;
    else if (ownerID == owner_MP2) return 2;
    else if (ownerID == owner_MP1) return 1;
    else if (ownerID == owner_MP4)
    {
        switch(param1)
        {
            case 0x6B:
                return 3;
            case 0x69:
                return 3;
            default:
                return 0;
        }
    }
    else if (ownerID == owner_matroska)
    {
        if (param2Size == sizeof(matroska_setup))
        {
            const matroska_setup * setup = static_cast<const matroska_setup*>(param2);
            if (setup->codec_id && strcmp(setup->codec_id, "A_MPEG/L3") == 0) return 3;
            else if (setup->codec_id && strcmp(setup->codec_id, "A_MPEG/L2") == 0) return 2;
            else if (setup->codec_id && strcmp(setup->codec_id, "A_MPEG/L1") == 0) return 1;
            else return 0;
        }
        return 0;
    }
    return 0;
}

unsigned packet_decoder_mp3_common::layer_from_frame(const void * frameData, size_t frameSize) {
    using namespace mp3_utils;
    TMPEGFrameInfo info;
    if (!ParseMPEGFrameHeader(info, frameData, frameSize)) throw exception_io_data();
    return info.m_layer;
}

