// Return pointer to CRC32 lookup table
const unsigned long* get_crc_table(void) {
    return crc32_lookup;
}

// Process single byte using CRC32 algorithm
inline void process_byte(unsigned long& state, const unsigned char* data, size_t index) {
    state = crc32_lookup[(state ^ data[index]) & 0xFF] ^ (state >> 8);
}

// Process 2 bytes
inline void process_pair(unsigned long& state, const unsigned char* data, size_t index) {
    process_byte(state, data, index);
    process_byte(state, data, index + 1);
}

// Process 4 bytes
inline void process_quartet(unsigned long& state, const unsigned char* data, size_t index) {
    process_pair(state, data, index);
    process_pair(state, data, index + 2);
}

// Process 8 bytes
inline void process_octet(unsigned long& state, const unsigned char* data, size_t index) {
    process_quartet(state, data, index);
    process_quartet(state, data, index + 4);
}

// Process 16 bytes
inline void process_block(unsigned long& state, const unsigned char* data, size_t index) {
    process_octet(state, data, index);
    process_octet(state, data, index + 8);
}

// Main CRC32 computation function
unsigned long compute_crc32(unsigned long initial, const unsigned char* data, size_t length) {
    if (data == nullptr) {
        return 0;
    }

    unsigned long crc_state = initial ^ 0xFFFFFFFFUL;

    // Process data in 16-byte blocks when possible
    while (length >= 16) {
        process_block(crc_state, data, 0);
        data += 16;
        length -= 16;
    }

    // Handle remaining bytes one by one
    while (length > 0) {
        process_byte(crc_state, data, 0);
        data++;
        length--;
    }

    return crc_state ^ 0xFFFFFFFFUL;
}

#include <gtest/gtest.h>
#include "SmallVector.h"

// Test fixture for SmallVector unit tests
class SmallVectorTest : public ::testing::Test {
};

// Verify push_back and clear operations on a SmallVector with inline capacity
TEST_F(SmallVectorTest, PushBackClear) {
    SmallVector<int, 3> container;
    container.push_back(10);
    container.push_back(20);
    container.push_back(30);
    container.push_back(40);
    container.push_back(50);

    EXPECT_EQ(container.size(), 5u);
    EXPECT_EQ(container[0], 10);
    EXPECT_EQ(container[1], 20);
    EXPECT_EQ(container[2], 30);
    EXPECT_EQ(container[3], 40);
    EXPECT_EQ(container[4], 50);

    container.clear();
    EXPECT_EQ(container.size(), 0u);
}

// Ensure correct behavior when elements fit within small buffer
TEST_F(SmallVectorTest, SmallCapacity) {
    SmallVector<int, 4> buffer;
    buffer.push_back(7);
    buffer.push_back(14);

    EXPECT_EQ(buffer.size(), 2u);
    EXPECT_EQ(buffer[0], 7);
    EXPECT_EQ(buffer[1], 14);
}

// Check empty state transitions: initial, after insert, after clear
TEST_F(SmallVectorTest, Empty) {
    SmallVector<int, 4> storage;
    EXPECT_TRUE(storage.empty());

    storage.push_back(99);
    EXPECT_FALSE(storage.empty());

    storage.clear();
    EXPECT_TRUE(storage.empty());
}

// Validate growth beyond inline capacity and subsequent reuse
TEST_F(SmallVectorTest, Grow) {
    SmallVector<int, 4> vec;

    // Initial fill up to capacity
    vec.push_back(1);
    vec.push_back(2);
    EXPECT_EQ(vec.size(), 2u);
    EXPECT_EQ(vec[0], 1);
    EXPECT_EQ(vec[1], 2);

    // Force heap allocation by exceeding inline capacity
    vec.push_back(3);
    vec.push_back(4);
    vec.push_back(5);
    EXPECT_EQ(vec.size(), 5u);
    EXPECT_EQ(vec[0], 1);
    EXPECT_EQ(vec[1], 2);
    EXPECT_EQ(vec[2], 3);
    EXPECT_EQ(vec[3], 4);
    EXPECT_EQ(vec[4], 5);

    // Clear and reuse
    vec.clear();
    EXPECT_EQ(vec.size(), 0u);

    vec.push_back(6);
    vec.push_back(7);
    vec.push_back(8);
    EXPECT_EQ(vec.size(), 3u);
    EXPECT_EQ(vec[0], 6);
    EXPECT_EQ(vec[1], 7);
    EXPECT_EQ(vec[2], 8);

    // Grow again
    vec.push_back(9);
    vec.push_back(10);
    vec.push_back(11);
    EXPECT_EQ(vec.size(), 6u);
    EXPECT_EQ(vec[0], 6);
    EXPECT_EQ(vec[1], 7);
    EXPECT_EQ(vec[2], 8);
    EXPECT_EQ(vec[3], 9);
    EXPECT_EQ(vec[4], 10);
    EXPECT_EQ(vec[5], 11);

    vec.clear();
    EXPECT_EQ(vec.size(), 0u);
}

// Compare iterator-based traversal against std::vector
TEST_F(SmallVectorTest, Iterator) {
    constexpr size_t BUFFER_SIZE = 4;
    std::vector<int> referenceVec;
    SmallVector<int, BUFFER_SIZE> testVec;

    // Fill both containers identically
    for (size_t idx = 0; idx < BUFFER_SIZE; ++idx) {
        testVec.push_back(static_cast<int>(idx));
        referenceVec.push_back(static_cast<int>(idx));
    }

    EXPECT_EQ(testVec.size(), referenceVec.size());
    EXPECT_EQ(testVec, referenceVec);

    // Range-based iteration check
    size_t pos = 0;
    for (const auto& val : testVec) {
        EXPECT_EQ(val, referenceVec[pos]);
        ++pos;
    }

    // Explicit iterator traversal
    pos = 0;
    for (auto iter = testVec.begin(); iter != testVec.end(); ++iter, ++pos) {
        EXPECT_EQ(*iter, referenceVec[pos]);
    }
}

// Test map functionality with large input
TEST_F(SmallVectorTest, Map) {
    constexpr size_t TOTAL_ITEMS = 100000;
    SmallVector<int, 100> sourceVec;

    for (size_t i = 0; i < TOTAL_ITEMS; ++i) {
        sourceVec.push_back(static_cast<int>(i));
    }

    std::vector<int> targetVec;
    sourceVec.map([&targetVec](int value) {
        targetVec.push_back(value);
    });

    EXPECT_EQ(sourceVec.size(), targetVec.size());
    EXPECT_EQ(sourceVec, targetVec);
}

#include "Rect2i.h"
