Rect2i::Rect2i(int x, int y, int w, int h) {
    xPos   = x;
    yPos   = y;
    width  = w;
    height = h;
}

Rect2i* Rect2i::intersect(const Rect2i* other) {
    // Extract coordinates of the current rectangle
    int left1  = xPos;
    int top1   = yPos;
    int right1 = xPos + width;
    int bottom1 = yPos + height;

    // Extract coordinates of the other rectangle
    int left2  = other->getX();
    int top2   = other->getY();
    int right2 = other->getX() + other->getWidth();
    int bottom2 = other->getY() + other->getHeight();

    // Compute intersection boundaries
    int newLeft   = std::max(left1, left2);
    int newTop    = std::max(top1, top2);
    int newRight  = std::min(right1, right2);
    int newBottom = std::min(bottom1, bottom2);

    // Update dimensions (ensure non-negative size)
    xPos   = newLeft;
    yPos   = newTop;
    width  = std::max(0, newRight - newLeft);
    height = std::max(0, newBottom - newTop);

    return this;
}

int Rect2i::getX() const { return xPos; }
int Rect2i::getY() const { return yPos; }
void Rect2i::setX(int x) { xPos = x; }
void Rect2i::setY(int y) { yPos = y; }
int Rect2i::getWidth() const { return width; }
int Rect2i::getHeight() const { return height; }
void Rect2i::setWidth(int w) { width = w; }
void Rect2i::setHeight(int h) { height = h; }
void Rect2i::setPosition(int x, int y) {
    xPos = x;
    yPos = y;
}

