        if (std::any_of(option->nullStrings.begin(), option->nullStrings.end(),
                [&](const std::string& nullStr) { return nullStr == strVal; })) {
            vector->setNull(position, true);
            return;
        }
    } break;
    default: {
        if (isNull(strVal)) {
            vector->setNull(position, true);
            return;
        }
    } break;
    }
    vector->setNull(position, false);
}

