    currentRow = Row{totalWidth, 0, totalWidth - padX * 2 - padX * itemCount};
    relX = padX;
    relY = 0;
}

void Gui::EndRow() { 
    winY += currentRow.highestElement + padY; 
}

void Gui::Label(float size, bool shadow, Amy::Color color, bool center, const char* text, ...) {
    int wrapLimit = size <= 0.f ? (currentRow.width - relX - padX) : relativeToAbsoluteSize(size);
    int textHeight = 0;
    va_list args;
    va_start(args, text);

    int xOffset = 0;
    if (center) {
        // int txtW = SpriteBatch_CalcTextWidthVargs(text, args); // commented out original
        // if (txtW <= wrapLimit)
        //     xOffset = wrapLimit / 2 - txtW / 2;
        xOffset = 0; // placeholder for now
    }

    DrawString(text, winX + relX + xOffset, winY + relY, Amy::Color(255, 255, 255, 255));
    // int txtW2 = SpriteBatch_PushTextVargs(...); // omitted
    va_end(args);

    relX += (size <= 0.f ? /*txtW2*/ wrapLimit : wrapLimit) + padX;
    currentRow.highestElement = std::max(currentRow.highestElement, textHeight);
}

bool Gui::Button(float size, const char* label, ...) {
    va_list args;
    va_start(args, label);
    // int txtW = SpriteBatch_CalcTextWidthVargs(label, args); // omitted
    int txtW = 100; // placeholder

    int btnX = winX + relX;
    int btnY = winY + relY - BUTTON_TEXT_PADDING;
    int btnW = (size <= 0.f) ? txtW + SliceSize : relativeToAbsoluteSize(size);

    bool isPressed = IsCursorInside(btnX, btnY, btnW, BUTTON_HEIGHT);
    int midPart = btnW - SliceSize * 2;

    auto texMgr = ReCraftCore::GetInstance()->GetAssetManager();
    auto guiTex = texMgr->Get<Amy::Texture>("GuiTexture_Widgets");
    renderList->DrawTex(guiTex);

    int baseTexY = 66 + (isPressed * BUTTON_HEIGHT);
    DrawTexturedModalRect(btnX, btnY, 0, baseTexY, SliceSize, BUTTON_HEIGHT);
    DrawTexturedModalRect(btnX + SliceSize, btnY, SliceSize, baseTexY, midPart, BUTTON_HEIGHT);
    DrawTexturedModalRect(btnX + SliceSize + midPart, btnY, 192, baseTexY, SliceSize, BUTTON_HEIGHT);

    Amy::Color textColor = isPressed ? Amy::Color(255, 255, 160, 255) : Amy::Color(224, 224, 224, 255);
    DrawCenteredString(label, btnX + (btnW * 0.5f), btnY + (BUTTON_HEIGHT * 0.5f), textColor);
    va_end(args);

    relX += btnW + padX;
    currentRow.highestElement = std::max(currentRow.highestElement, BUTTON_HEIGHT);

    return Input::isKeyUp(KEY_TOUCH) && WasCursorInside(btnX, btnY, btnW, BUTTON_HEIGHT);
}

