bool Gui::IsCursorInside(int x, int y, int w, int h) {
    int touchX = Input::getTouch().px / 2;
    int touchY = Input::getTouch().py / 2;
    return touchX != 0 && touchY != 0 &&
           touchX >= x && touchX < x + w &&
           touchY >= y && touchY < y + h;
}

bool Gui::WasCursorInside(int x, int y, int w, int h) {
    int prevTouchX = Input::getTouchPrev().px / 2;
    int prevTouchY = Input::getTouchPrev().py / 2;
    return prevTouchX != 0 && prevTouchY != 0 &&
           prevTouchX >= x && prevTouchX < x + w &&
           prevTouchY >= y && prevTouchY < y + h;
}

bool Gui::EnteredCursorInside(int x, int y, int w, int h) {
    int prevTouchX = Input::getTouchPrev().px / 2;
    int prevTouchY = Input::getTouchPrev().py / 2;
    return (prevTouchX == 0 && prevTouchY == 0) && IsCursorInside(x, y, w, h);
}

void Gui::GetCursorMovement(int* dx, int* dy) {
    if ((Input::getTouch().px == 0 && Input::getTouch().py == 0) ||
        (Input::getTouchPrev().px == 0 && Input::getTouchPrev().py == 0)) {
        *dx = 0;
        *dy = 0;
        return;
    }
    *dx = Input::getTouch().px / 2 - Input::getTouchPrev().px / 2;
    *dy = Input::getTouch().py / 2 - Input::getTouchPrev().py / 2;
}

