Amy::Color fancyFontShadow(const Amy::Color& col) {
    uint32_t rgba = (col.r << 24) | (col.g << 16) | (col.b << 8) | col.a;
    uint32_t shifted = (rgba & 16579836) >> 2 | rgba & -16777216;
    return Amy::Color(static_cast<uint8_t>(shifted >> 24),
                      static_cast<uint8_t>(shifted >> 16),
                      static_cast<uint8_t>(shifted >> 8),
                      static_cast<uint8_t>(shifted));
}

void Gui::DrawStringWithShadow(const std::string& text, int x, int y, const Amy::Color& color) const {
    DrawString(text, x + 1, y + 1, fancyFontShadow(color));
    DrawString(text, x, y, color);
}

void Gui::DrawCenteredString(const std::string& text, int x, int y, const Amy::Color& color, bool shadow) const {
    if (shadow) {
        renderList->DrawTextEx(Amy::ivec2((x + 1) * 2, (y + 1) * 2), text, fancyFontShadow(color),
                               AmyTextFlags_AlignMid);
    }
    renderList->DrawTextEx(Amy::fvec2(x * 2, y * 2), text, color, AmyTextFlags_AlignMid);
}

