    auto texMgr = ReCraftCore::GetInstance()->GetAssetManager();
    auto bgTex = texMgr->Get<Amy::Texture>("GuiTexture_DefaultBG");
    renderList->DrawTex(bgTex);

    int rows = 160 / 32 + 1;
