An extension with circular structuring element is attempted - unfortunately I
could
not retrieve a copy of Miyataka's paper about that, which seemingly claimed
O(rows * cols) too. The implemented algorithm is a sub-optimal
O(rows*cols*radius).
*/
//********************************************************
//    Auxiliary  functions
//********************************************************
namespace {
template <typename Pix>
void transferAlpha(const TRasterPT<Pix> &src,
                   const TRasterPT<typename Pix::Channel> &matte) {
  typedef typename Pix::Channel Chan;
  int height = src->getLy(), width = src->getLx();
  for (int row = 0; row < height; ++row) {
    Pix *srcRow = src->pixels(row);
    Chan *alphaRow = matte->pixels(row);
    for (int col = 0; col < width; ++col) {
      alphaRow[col] = srcRow[col].m;
    }
  }
}
//--------------------------------------------------------------
template <typename Pix>
void reconstructWithErosion(const TRasterPT<Pix> &original,
                            const TRasterPT<typename Pix::Channel> &newAlpha,
                            const TRasterPT<Pix> &result) {
  typedef typename Pix::Channel Chan;
  double scale;
  int height = original->getLy(), width = original->getLx();
  for (int row = 0; row < height; ++row) {
    const Pix *origLine = original->pixels(row);
    Pix *outLine = result->pixels(row);
    Chan *alphaLine = newAlpha->pixels(row);
    for (int col = 0; col < width; ++col) {
      scale = static_cast<double>(alphaLine[col]) / static_cast<double>(origLine[col].m);
      outLine[col].r = scale * origLine[col].r;
      outLine[col].g = scale * origLine[col].g;
      outLine[col].b = scale * origLine[col].b;
      outLine[col].m = alphaLine[col];
    }
  }
}
//--------------------------------------------------------------
template <typename Pix>
void reconstructWithDilation(const TRasterPT<Pix> &original,
                             const TRasterPT<typename Pix::Channel> &newAlpha,
                             const TRasterPT<Pix> &result) {
  typedef typename Pix::Channel Chan;
  double maxVal = Pix::maxChannelValue;
  int height = original->getLy(), width = original->getLx();
  for (int row = 0; row < height; ++row) {
    const Pix *origLine = original->pixels(row);
    Pix *outLine = result->pixels(row);
    const Chan *alphaLine = newAlpha->pixels(row);
    for (int col = 0; col < width; ++col) {
      outLine[col] = origLine[col];
      outLine[col].m = origLine[col].m + (1.0 - static_cast<double>(origLine[col].m) / maxVal) * alphaLine[col];
    }
  }
}
}  // namespace
