//    EroDilate  algorithms
//********************************************************
namespace {
template <typename T>
class MaxSelector {
public:
  inline T apply(const T& first, const T& second) const {
    return (first > second) ? first : second;
  }
};
template <typename T>
class MinSelector {
public:
  inline T apply(const T& first, const T& second) const {
    return (first < second) ? first : second;
  }
};
//--------------------------------------------------------------
// NOTE: src and dst must be NOT OVERLAPPING (eg src != dst)
template <typename T, typename Op>
void process_scanline(int size, const T* input, int inputStep, T* output, int outputStep,
                      int radius, double fractionalRadius, Op operation) {
  assert(radius >= 0);
  // Divide scanline into segments based on window size
  int windowSize = 2 * radius + 1;
  int segmentCount = size / windowSize + 1;
  int segmentInputStep = windowSize * inputStep;
  int centerOffsetInput = radius * inputStep;
  int segmentOutputStep = windowSize * outputStep;
  int centerOffsetOutput = radius * outputStep;

  const T* inPtr = input;
  const T* inEnd = input + size * inputStep;
  T* outPtr = output;
  T* outEnd = output + size * outputStep;
  double one_minus_frac = 1.0 - fractionalRadius;

  for (int seg = 0; seg < segmentCount; ++seg) {
    T* outSegStart = output + seg * segmentOutputStep;
    T* outSegEnd = std::min(outSegStart + segmentOutputStep, outEnd);

    // Process prefix (left-to-right within segment)
    const T* inSegStart = input + std::max(seg * segmentInputStep - centerOffsetInput - inputStep, 0);
    const T* inSegEnd = input + std::min(seg * segmentInputStep + centerOffsetInput + inputStep, size * inputStep);

    // Start from end of segment range
    inPtr = inSegEnd - inputStep;
    outPtr = output + ((inPtr - input) / inputStep) * outputStep + centerOffsetOutput;

    T currentVal = *inPtr;
    T prevVal;

    // Backward pass for prefix
    for (inPtr -= inputStep; (outPtr >= outEnd) && (inPtr >= inSegStart);
         inPtr -= inputStep, outPtr -= outputStep) {
      assert(inPtr >= input);
      assert(inPtr < inEnd);
      assert((inPtr - input) % inputStep == 0);
      assert(outPtr >= output);
      assert((outPtr - output) % outputStep == 0);
      currentVal = operation.apply(prevVal = currentVal, *inPtr);
    }

    // Continue backward pass within bounds
    for (; inPtr >= inSegStart; inPtr -= inputStep, outPtr -= outputStep) {
      assert(inPtr >= input);
      assert(inPtr < inEnd);
      assert((inPtr - input) % inputStep == 0);
      assert(outPtr >= output);
      assert(outPtr < outEnd);
      assert((outPtr - output) % outputStep == 0);
      currentVal = operation.apply(prevVal = currentVal, *inPtr);
      *outPtr = (prevVal == currentVal) ? currentVal : one_minus_frac * prevVal + fractionalRadius * currentVal;
    }

    // Fill remaining positions with zero-padding
    for (outPtr = std::min(outPtr, outEnd - outputStep); outPtr >= outSegStart; outPtr -= outputStep) {
      assert(outPtr >= output);
      assert(outPtr < outEnd);
      assert((outPtr - output) % outputStep == 0);
      currentVal = operation.apply(prevVal = currentVal, 0);
      *outPtr = (prevVal == currentVal) ? currentVal : one_minus_frac * prevVal + fractionalRadius * currentVal;
    }

    // Process suffix (right-to-left within segment)
    inSegStart = input + seg * segmentInputStep + centerOffsetInput;
    inSegEnd = std::min(inSegStart + segmentInputStep + inputStep, inEnd);

    if (inSegStart >= inSegEnd) continue;

    inPtr = inSegStart;
    outPtr = outSegStart;
    currentVal = *inPtr;

    // Forward pass for suffix
    for (inPtr += inputStep; inPtr < inSegEnd; inPtr += inputStep, outPtr += outputStep) {
      assert(inPtr >= input);
      assert(inPtr < inEnd);
      assert((inPtr - input) % inputStep == 0);
      assert(outPtr >= output);
      assert(outPtr < outEnd);
      assert((outPtr - output) % outputStep == 0);
      currentVal = operation.apply(prevVal = currentVal, *inPtr);
      *outPtr = operation.apply(*outPtr, (prevVal == currentVal) ? currentVal : one_minus_frac * prevVal + fractionalRadius * currentVal);
    }

    // Fill remaining positions with zero-padding
    for (; outPtr < outSegEnd; outPtr += outputStep) {
      assert(outPtr >= output);
      assert(outPtr < outEnd);
      assert((outPtr - output) % outputStep == 0);
      currentVal = operation.apply(prevVal = currentVal, 0);
      *outPtr = operation.apply(*outPtr, (prevVal == currentVal) ? currentVal : one_minus_frac * prevVal + fractionalRadius * currentVal);
    }
  }
}
//--------------------------------------------------------------
template <typename Pix, typename Chan>
void channel_process(const TRasterPT<Pix> &input, const TRasterPT<Chan> &output,
                     double r, bool isDilation) {
  assert(r > 0.0);
  int integerRadius = tfloor(r);
  double fractionalPart = r - integerRadius;

  int width = input->getLx(), height = input->getLy();

  // Use transposed temporary raster for cache-friendly processing
  TRasterPT<Chan> temp(height, width);

  // First pass: process rows
  if (isDilation) {
    for (int y = 0; y < height; ++y) {
      ::process_scanline(width, &input->pixels(y)->m, 4, temp->pixels(0) + y, height,
                        integerRadius, fractionalPart, MaxSelector<Chan>());
    }
  } else {
    for (int y = 0; y < height; ++y) {
      ::process_scanline(width, &input->pixels(y)->m, 4, temp->pixels(0) + y, height,
                        integerRadius, fractionalPart, MinSelector<Chan>());
    }
  }

  // Second pass: process columns
  if (isDilation) {
    for (int x = 0; x < width; ++x) {
      ::process_scanline(height, temp->pixels(x), 1, output->pixels(0) + x,
                        output->getWrap(), integerRadius, fractionalPart, MaxSelector<Chan>());
    }
  } else {
    for (int x = 0; x < width; ++x) {
      ::process_scanline(height, temp->pixels(x), 1, output->pixels(0) + x,
                        output->getWrap(), integerRadius, fractionalPart, MinSelector<Chan>());
    }
  }
}
//--------------------------------------------------------------
template <typename Pix>
void rectangular_operation(const TRasterPT<Pix> &input, const TRasterPT<Pix> &output,
                           double r) {
  typedef typename Pix::Channel Chan;
  if (r == 0.0) {
    // Identity case
    TRop::copy(output, input);
    return;
  }

  bool isDilation = (r >= 0.0);

  // Create intermediate storage
  TRasterPT<Chan> temp(input->getLx(), input->getLy());
  ::channel_process(input, temp, std::abs(r), isDilation);

  // Apply computed alpha values to RGB channels
  if (isDilation)
    ::reconstructWithDilation(input, temp, output);
  else
    ::reconstructWithErosion(input, temp, output);
}
}  // namespace
//********************************************************
//    EroDilate  round algorithm
//********************************************************
namespace {
template <typename T, typename Op>
void quadrant_processing(int width, int height, T* source, int stepX, int stepY,
                         T* dest, int outStepX, int outStepY, double rad,
                         double offset, Op operation) {
  double radiusSquared = rad * rad;
  double diagonalLength = rad * M_SQRT1_2;
  int diagonalInt = tfloor(diagonalLength);

  // Iterate through arc points
  for (int arcY = -diagonalInt; arcY <= diagonalInt; ++arcY) {
    double arcYSquared = arcY * arcY;
    assert(radiusSquared >= arcYSquared);

    double arcXFloat = offset + sqrt(radiusSquared - arcYSquared) - diagonalLength;
    int arcX = tfloor(arcXFloat);
    double weight = arcXFloat - arcX;
    double invWeight = 1.0 - weight;

    // Determine affected region
    TRect bounds(0, 0, width, height);
    TRect dRect(bounds * (bounds + TPoint(-arcX, -arcY)));
    TRect sRect(bounds * (bounds + TPoint(arcX, arcY)));

    int sy, dy;

    // Handle area before valid region
    for (dy = 0; dy < dRect.y0; ++dy) {
      T* destRow = dest + dy * outStepY;
      for (int dx = 0; dx < width; ++dx) {
        destRow[dx * outStepX] = operation.apply(destRow[dx * outStepX], 0);
      }
    }

    // Handle area after valid region
    for (dy = dRect.y1; dy < height; ++dy) {
      T* destRow = dest + dy * outStepY;
      for (int dx = 0; dx < width; ++dx) {
        destRow[dx * outStepX] = operation.apply(destRow[dx * outStepX], 0);
      }
    }

    // Process valid region
    for (dy = dRect.y0, sy = sRect.y0; dy != dRect.y1; ++dy, ++sy) {
      T* destRow = dest + dy * outStepY;
      T* srcRow = source + sy * stepY;

      T* destCol = destRow + dRect.x0 * outStepX;
      T* srcCol = srcRow + sRect.x0 * stepX;
      T* srcLast = srcRow + sRect.x1 * stepX - stepX;

      for (; srcCol != srcLast; ++destCol, srcCol += stepX) {
        *destCol = operation.apply(*destCol, srcCol[0] * invWeight + srcCol[stepX] * weight);
      }

      *destCol = operation.apply(*destCol, srcCol[0] * invWeight);
    }
  }
}
//--------------------------------------------------------------
template <typename Pix>
void circular_operation(const TRasterPT<Pix> &input, const TRasterPT<Pix> &output,
                        double radius) {
  typedef typename Pix::Channel Chan;
  if (radius == 0.0) {
    // Identity case
    TRop::copy(output, input);
    return;
  }

  bool isDilation = (radius >= 0.0);
  radius = std::abs(radius);

  // Compute parameters for decomposition
  double innerSquareSize = radius * M_SQRT2;
  double shift = 0.25 * innerSquareSize;
  double rowFilterRadius = 0.5 * (innerSquareSize - shift);
  double cseShift = 0.5 * shift;

  int width = input->getLx(), height = input->getLy();
  TRasterPT<Chan> buffer1(width, height), buffer2(width, height);

  int intRadius = tfloor(rowFilterRadius);
  double fracRadius = rowFilterRadius - intRadius;

  if (isDilation) {
    buffer2->fill(0);  // Neutral element for max

    if (rowFilterRadius > 0.0) {
      for (int y = 0; y < height; ++y) {
        ::process_scanline(width, &input->pixels(y)->m, 4, buffer1->pixels(y), 1,
                          intRadius, fracRadius, MaxSelector<Chan>());
      }
    } else {
      transferAlpha(input, buffer1);
    }

    // Process four quadrants
    quadrant_processing(width, height, buffer1->pixels(0), 1, width, 
                       buffer2->pixels(0), 1, width, radius, cseShift, MaxSelector<Chan>());
    quadrant_processing(width, height, buffer1->pixels(0) + width - 1, -1, width,
                       buffer2->pixels(0) + width - 1, -1, width, radius, cseShift, MaxSelector<Chan>());

    if (rowFilterRadius > 0.0) {
      for (int x = 0; x < width; ++x) {
        ::process_scanline(height, &input->pixels(0)[x].m, 4 * input->getWrap(),
                          buffer1->pixels(0) + x, width, intRadius, fracRadius, MaxSelector<Chan>());
      }
    } else {
      transferAlpha(input, buffer1);
    }

    quadrant_processing(height, width, buffer1->pixels(0), width, 1,
                       buffer2->pixels(0), width, 1, radius, cseShift, MaxSelector<Chan>());
    quadrant_processing(height, width, buffer1->pixels(0) + width * height - 1, -width, -1,
                       buffer2->pixels(0) + width * height - 1, -width, -1, radius, cseShift, MaxSelector<Chan>());
  } else {
    buffer2->fill((std::numeric_limits<Chan>::max)());  // Neutral element for min

    if (rowFilterRadius > 0.0) {
      for (int y = 0; y < height; ++y) {
        ::process_scanline(width, &input->pixels(y)->m, 4, buffer1->pixels(y), 1,
                          intRadius, fracRadius, MinSelector<Chan>());
      }
    } else {
      transferAlpha(input, buffer1);
    }

    // Process four quadrants
    quadrant_processing(width, height, buffer1->pixels(0), 1, width,
                       buffer2->pixels(0), 1, width, radius, cseShift, MinSelector<Chan>());
    quadrant_processing(width, height, buffer1->pixels(0) + width - 1, -1, width,
                       buffer2->pixels(0) + width - 1, -1, width, radius, cseShift, MinSelector<Chan>());

    if (rowFilterRadius > 0.0) {
      for (int x = 0; x < width; ++x) {
        ::process_scanline(height, &input->pixels(0)[x].m, 4 * input->getWrap(),
                          buffer1->pixels(0) + x, width, intRadius, fracRadius, MinSelector<Chan>());
      }
    } else {
      transferAlpha(input, buffer1);
    }

    quadrant_processing(height, width, buffer1->pixels(0), width, 1,
                       buffer2->pixels(0), width, 1, radius, cseShift, MinSelector<Chan>());
    quadrant_processing(height, width, buffer1->pixels(0) + width * height - 1, -width, -1,
                       buffer2->pixels(0) + width * height - 1, -width, -1, radius, cseShift, MinSelector<Chan>());
  }

  // Apply computed alpha values to RGB channels
  if (isDilation)
    ::reconstructWithDilation(input, buffer2, output);
  else
    ::reconstructWithErosion(input, buffer2, output);
}
}  // namespace
//********************************************************
//    EroDilate  main functions
//********************************************************
void TRop::erodilate(const TRasterP &src, const TRasterP &dst, double radius,
                     ErodilateMaskType type) {
  assert(src->getSize() == dst->getSize());
  src->lock(), dst->lock();

  if ((TRaster32P)src && (TRaster32P)dst) switch (type) {
    case ED_rectangular:
      ::rectangular_operation<TPixel32>(src, dst, radius);
      break;
    case ED_circular:
      ::circular_operation<TPixel32>(src, dst, radius);
      break;
    default:
      assert(!"Unknown mask type");
      break;
    }
  else if ((TRaster64P)src && (TRaster64P)dst)
    switch (type) {
    case ED_rectangular:
      ::rectangular_operation<TPixel64>(src, dst, radius);
      break;
    case ED_circular:
      ::circular_operation<TPixel64>(src, dst, radius);
      break;
    default:
      assert(!"Unknown mask type");
      break;
    }
  else
    assert(!"Unsupported raster type!");

  src->unlock(), dst->unlock();
}

