namespace MLS_NAMESPACE {

///
/// Extensions
///
const Extension::Type RequiredCapabilitiesExtension::type =
  ExtensionType::required_capabilities;
const Extension::Type ApplicationIDExtension::type =
  ExtensionType::application_id;

// Default supported extensions list
const std::array<uint16_t, 5> default_extensions = {
  ExtensionType::application_id,
  ExtensionType::ratchet_tree,
  ExtensionType::required_capabilities,
  ExtensionType::external_pub,
  ExtensionType::external_senders,
};

// Default supported proposal types
const std::array<uint16_t, 8> default_proposals = {
  ProposalType::add,
  ProposalType::update,
  ProposalType::remove,
  ProposalType::psk,
  ProposalType::reinit,
  ProposalType::external_init,
  ProposalType::group_context_extensions,
};

// Supported protocol versions
const std::array<ProtocolVersion, 1> all_supported_versions = {
  ProtocolVersion::mls10
};

// Supported cipher suites
const std::array<CipherSuite::ID, 6> all_supported_ciphersuites = {
  CipherSuite::ID::X25519_AES128GCM_SHA256_Ed25519,
  CipherSuite::ID::P256_AES128GCM_SHA256_P256,
  CipherSuite::ID::X25519_CHACHA20POLY1305_SHA256_Ed25519,
  CipherSuite::ID::X448_AES256GCM_SHA512_Ed448,
  CipherSuite::ID::P521_AES256GCM_SHA512_P521,
  CipherSuite::ID::X448_CHACHA20POLY1305_SHA512_Ed448,
};

// Supported credential types
const std::array<CredentialType, 4> all_supported_credentials = {
  CredentialType::basic,
  CredentialType::x509,
  CredentialType::userinfo_vc_draft_00,
  CredentialType::multi_draft_00
};

// Create default capabilities object
Capabilities
Capabilities::create_default()
{
  return {
    { all_supported_versions.begin(), all_supported_versions.end() },
    { all_supported_ciphersuites.begin(), all_supported_ciphersuites.end() },
    { /* No non-default extensions */ },
    { /* No non-default proposals */ },
    { all_supported_credentials.begin(), all_supported_credentials.end() },
  };
}

// Check if all required extensions are supported
bool
Capabilities::extensions_supported(
  const std::vector<Extension::Type>& needed) const
{
  for (const auto& ext_type : needed) {
    bool found = false;
    // First check built-in defaults
    for (auto def_ext : default_extensions) {
      if (def_ext == static_cast<uint16_t>(ext_type)) {
        found = true;
        break;
      }
    }
    if (!found) {
      // Then check custom extensions
      for (const auto& ext : extensions) {
        if (ext.type == ext_type) {
          found = true;
          break;
        }
      }
    }
    if (!found) {
      return false;
    }
  }
  return true;
}

// Check if all required proposals are supported
bool
Capabilities::proposals_supported(
  const std::vector<Proposal::Type>& needed) const
{
  for (const auto& prop_type : needed) {
    bool found = false;
    // First check built-in defaults
    for (auto def_prop : default_proposals) {
      if (def_prop == static_cast<uint16_t>(prop_type)) {
        found = true;
        break;
      }
    }
    if (!found) {
      // Then check custom proposals
      for (const auto& prop : proposals) {
        if (prop == prop_type) {
          found = true;
          break;
        }
      }
    }
    if (!found) {
      return false;
    }
  }
  return true;
}

// Check if given credential type is supported
bool
Capabilities::credential_supported(const Credential& cred) const
{
  auto cred_type = cred.type();
  for (const auto& supported : credentials) {
    if (supported == cred_type) {
      return true;
    }
  }
  return false;
}

// Default lifetime: infinite validity window
Lifetime
Lifetime::create_default()
{
  return Lifetime{ 0x0000000000000000ULL, 0xffffffffffffffffULL };
}

// Add or replace extension in list
void
ExtensionList::add(uint16_t ext_type, bytes data)
{
  auto it = std::find_if(extensions.begin(), extensions.end(),
                         [&](const Extension& ext) { return ext.type == ext_type; });
  if (it != extensions.end()) {
    it->data = std::move(data);
    return;
  }
  extensions.emplace_back(ext_type, std::move(data));
}

// Check if extension exists
bool
ExtensionList::has(uint16_t ext_type) const
{
  return std::any_of(extensions.begin(), extensions.end(),
                     [ext_type](const Extension& ext) { return ext.type == ext_type; });
}

///
/// LeafNode
///
LeafNode::LeafNode(CipherSuite cipher_suite,
                   HPKEPublicKey encryption_key_in,
                   SignaturePublicKey signature_key_in,
                   Credential credential_in,
                   Capabilities capabilities_in,
                   Lifetime lifetime_in,
                   ExtensionList extensions_in,
                   const SignaturePrivateKey& sig_priv)
  : encryption_key(std::move(encryption_key_in))
  , signature_key(std::move(signature_key_in))
  , credential(std::move(credential_in))
  , capabilities(std::move(capabilities_in))
  , content(lifetime_in)
  , extensions(std::move(extensions_in))
{
  grease(extensions);
  grease(capabilities, extensions);
  sign(cipher_suite, sig_priv, std::nullopt);
}

void
LeafNode::set_capabilities(Capabilities new_caps)
{
  capabilities = std::move(new_caps);
  grease(capabilities, extensions);
}

LeafNode
LeafNode::for_update(CipherSuite suite,
                     const bytes& group_id,
                     LeafIndex leaf_idx,
                     HPKEPublicKey enc_key_in,
                     const LeafNodeOptions& opts,
                     const SignaturePrivateKey& sig_priv) const
{
  auto clone = clone_with_options(std::move(enc_key_in), opts);
  clone.content = Empty{};
  clone.sign(suite, sig_priv, { { group_id, leaf_idx } });
  return clone;
}

LeafNode
LeafNode::for_commit(CipherSuite suite,
                     const bytes& group_id,
                     LeafIndex leaf_idx,
                     HPKEPublicKey enc_key_in,
                     const bytes& parent_hash,
                     const LeafNodeOptions& opts,
                     const SignaturePrivateKey& sig_priv) const
{
  auto clone = clone_with_options(std::move(enc_key_in), opts);
  clone.content = ParentHash{ parent_hash };
  clone.sign(suite, sig_priv, { { group_id, leaf_idx } });
  return clone;
}

LeafNodeSource
LeafNode::source() const
{
  return tls::variant<LeafNodeSource>::type(content);
}

void
LeafNode::sign(CipherSuite suite,
               const SignaturePrivateKey& priv,
               const std::optional<MemberBinding>& binding)
{
  const auto tbs = to_be_signed(binding);
  if (priv.public_key != signature_key) {
    throw InvalidParameterError("Signature key mismatch");
  }
  if (!credential.valid_for(signature_key)) {
    throw InvalidParameterError("Credential not valid for signature key");
  }
  signature = priv.sign(suite, sign_label::leaf_node, tbs);
}

bool
LeafNode::verify(CipherSuite suite,
                 const std::optional<MemberBinding>& binding) const
{
  const auto tbs = to_be_signed(binding);
  if (CredentialType::x509 == credential.type()) {
    const auto& x509_cred = credential.get<X509Credential>();
    if (x509_cred.signature_scheme() !=
        tls_signature_scheme(suite.sig().id)) {
      throw std::runtime_error("Signature algorithm invalid");
    }
  }
  return signature_key.verify(
    suite, sign_label::leaf_node, tbs, signature);
}

bool
LeafNode::verify_expiry(uint64_t current_time) const
{
  struct ValidityChecker {
    uint64_t now;
    bool operator()(const Lifetime& lt) const {
      return lt.not_before <= now && now <= lt.not_after;
    }
    template<typename T>
    bool operator()(const T&) const { return false; }
  };

  return var::visit(ValidityChecker{ current_time }, content);
}

bool
LeafNode::verify_extension_support(const ExtensionList& ext_list) const
{
  // Extract extension types from input list
  std::vector<Extension::Type> ext_types;
  std::transform(ext_list.extensions.begin(), ext_list.extensions.end(),
                 std::back_inserter(ext_types),
                 [](const auto& ext) { return ext.type; });

  if (!capabilities.extensions_supported(ext_types)) {
    return false;
  }

  // If RequiredCapabilities present, verify further constraints
  const auto maybe_req_capas = ext_list.find<RequiredCapabilitiesExtension>();
  if (!maybe_req_capas) {
    return true;
  }

  const auto& req_capas = opt::get(maybe_req_capas);
  return capabilities.extensions_supported(req_capas.extensions) &&
         capabilities.proposals_supported(req_capas.proposals);
}

LeafNode
LeafNode::clone_with_options(HPKEPublicKey enc_key_in,
                             const LeafNodeOptions& opts) const
{
  auto clone = *this;
  clone.encryption_key = std::move(enc_key_in);

  if (opts.credential) {
    clone.credential = opt::get(opts.credential);
  }
  if (opts.capabilities) {
    clone.capabilities = opt::get(opts.capabilities);
  }
  if (opts.extensions) {
    clone.extensions = opt::get(opts.extensions);
  }
  return clone;
}

// TBS structure for signing
struct LeafNodeTBS
{
  const HPKEPublicKey& enc_key;
  const SignaturePublicKey& sig_key;
  const Credential& cred;
  const Capabilities& caps;
  const var::variant<Lifetime, Empty, ParentHash>& content_field;
  const ExtensionList& exts;

  TLS_SERIALIZABLE(enc_key, sig_key, cred, caps, content_field, exts)
  TLS_TRAITS(tls::pass, tls::pass, tls::pass, tls::pass,
             tls::variant<LeafNodeSource>, tls::pass)
};

bytes
LeafNode::to_be_signed(const std::optional<MemberBinding>& binding) const
{
  tls::ostream writer;
  writer << LeafNodeTBS{
    encryption_key, signature_key, credential,
    capabilities,   content,       extensions,
  };

  switch (source()) {
    case LeafNodeSource::key_package:
      break;
    case LeafNodeSource::update:
    case LeafNodeSource::commit:
      writer << opt::get(binding);
      break;
  }
  return writer.bytes();
}

///
/// NodeType, ParentNode, and KeyPackage
///
bytes
ParentNode::hash(CipherSuite suite) const
{
  return suite.digest().hash(tls::marshal(this));
}

KeyPackage::KeyPackage()
  : version(ProtocolVersion::mls10)
  , cipher_suite(CipherSuite::ID::unknown)
{
}

KeyPackage::KeyPackage(CipherSuite suite_in,
                       HPKEPublicKey init_key_in,
                       LeafNode leaf_node_in,
                       ExtensionList extensions_in,
                       const SignaturePrivateKey& sig_priv_in)
  : version(ProtocolVersion::mls10)
  , cipher_suite(suite_in)
  , init_key(std::move(init_key_in))
  , leaf_node(std::move(leaf_node_in))
  , extensions(std::move(extensions_in))
{
  grease(extensions);
  sign(sig_priv_in);
}

KeyPackageRef
KeyPackage::ref() const
{
  return cipher_suite.ref(*this);
}

void
KeyPackage::sign(const SignaturePrivateKey& priv)
{
  auto tbs = to_be_signed();
  signature = priv.sign(cipher_suite, sign_label::key_package, tbs);
}

bool
KeyPackage::verify() const
{
  // Verify inner leaf node first
  if (!leaf_node.verify(cipher_suite, std::nullopt)) {
    return false;
  }

  // Ensure leaf node is intended for use in a KeyPackage
  if (leaf_node.source() != LeafNodeSource::key_package) {
    return false;
  }

  // Verify full KeyPackage signature
  const auto tbs = to_be_signed();
  if (CredentialType::x509 == leaf_node.credential.type()) {
    const auto& x509_cred = leaf_node.credential.get<X509Credential>();
    if (x509_cred.signature_scheme() !=
        tls_signature_scheme(cipher_suite.sig().id)) {
      throw std::runtime_error("Signature algorithm invalid");
    }
  }

  return leaf_node.signature_key.verify(
    cipher_suite, sign_label::key_package, tbs, signature);
}

bytes
KeyPackage::to_be_signed() const
{
  tls::ostream out;
  out << version << cipher_suite << init_key << leaf_node << extensions;
  return out.bytes();
}

