#define BUF_SIZE 512

const char *BinStream::Name() const { return "<unnamed>"; }

BinStream::BinStream(bool b)
    : mLittleEndian(b), mCrypto(nullptr), mRevStack(nullptr) {}

// Helper: Function table for endianness swapping based on size
using SwapFunc = void (*)(const void*, void*);
static void Swap2(const void* src, void* dst) {
    unsigned short s = EndianSwap(*reinterpret_cast<const unsigned short*>(src));
    *reinterpret_cast<unsigned short*>(dst) = s;
}
static void Swap4(const void* src, void* dst) {
    unsigned int i = EndianSwap(*reinterpret_cast<const unsigned int*>(src));
    *reinterpret_cast<unsigned int*>(dst) = i;
}
static void Swap8(const void* src, void* dst) {
    unsigned long long l = EndianSwap(*reinterpret_cast<const unsigned long long*>(src));
    *reinterpret_cast<unsigned long long*>(dst) = l;
}

static void (*const s_Swappers[])(const void*, void*) = {
    nullptr, nullptr, Swap2, nullptr, Swap4, nullptr, nullptr, nullptr, Swap8
};

void SwapData(const void *src, void *dst, int sz) {
    if (sz >= 0 && sz < static_cast<int>(sizeof(s_Swappers)/sizeof(s_Swappers[0]))) {
        SwapFunc fn = s_Swappers[sz];
        if (fn) {
            fn(src, dst);
            return;
        }
    }
    MILO_ASSERT(0, 0xAC);
}

void BinStream::DisableEncryption() {
    MILO_ASSERT(mCrypto, 0xDC);
    delete mCrypto;
    mCrypto = nullptr;
}

void BinStream::Write(const void *raw_data, int len) {
    if (Fail()) {
        MILO_PRINT_ONCE("Stream error: Can't write to %s\n", Name());
        return;
    }

    const unsigned char *buf = static_cast<const unsigned char*>(raw_data);

    if (!mCrypto) {
        WriteImpl(raw_data, len);
    } else {
        char temp[BUF_SIZE];
        for (int idx = 0; idx < len; ) {
            int chunk = std::min(BUF_SIZE, len - idx);
            for (int j = 0; j < chunk; ++j) {
                u8 mask = mCrypto->Int();
                temp[j] = buf[idx + j] ^ mask;
            }
            WriteImpl(temp, chunk);
            idx += chunk;
        }
    }
}

void BinStream::Seek(int offset, SeekType type) {
    MILO_ASSERT(!Fail(), 0x11F);
    MILO_ASSERT(!mCrypto, 0x122);
    SeekImpl(offset, type);
}

void BinStream::WriteEndian(const void *src, int sz) {
    if (mLittleEndian) {
        alignas(8) u64 tmp[2] = {};
        SwapData(src, tmp, sz);
        Write(tmp, sz);
    } else {
        Write(src, sz);
    }
}

bool BinStream::AddSharedInlined(const class FilePath &) {
    MILO_FAIL("BinStream::AddSharedInlined is a PC dev tool only !!");
    return false;
}

BinStream &BinStream::operator<<(const char *str) {
    MILO_ASSERT(str, 0x60);
    int len = std::strlen(str);
    *this << len;
    Write(str, len);
    return *this;
}

BinStream &BinStream::operator<<(const Symbol &sym) {
    const char *text = sym.Str();
    unsigned int textLen = std::strlen(text);
    MILO_ASSERT(textLen < BUF_SIZE, 0x6C);
    *this << textLen;
    Write(text, textLen);
    return *this;
}

BinStream &BinStream::operator<<(const class String &str) {
    int len = static_cast<int>(str.length());
    *this << len;
    Write(str.c_str(), len);
    return *this;
}

void BinStream::EnableWriteEncryption() {
    MILO_ASSERT(!mCrypto, 0xC8);
    int seed = RandomInt();
    *this << seed;
    mCrypto = new Rand2(seed);
}

int BinStream::PopRev(Hmx::Object *obj) {
    MILO_ASSERT(mRevStack, 0x34);
    ObjVersion &entry = mRevStack->back();

    while (!entry.obj) {
        MILO_NOTIFY("hey object got deleted!");
        mRevStack->pop_back();
        entry = mRevStack->back();
    }

    int revCount = entry.revs;

    if (obj != entry.obj) {
        MILO_LOG("rev stack $this mismatch (%08x != %08x\n", obj, entry.obj);
        MILO_LOG("curr obj: %s %s\n", obj->ClassName(), PathName(obj));
        MILO_LOG("stack obj: %s %s\n", entry.obj->ClassName(), PathName(entry.obj));
        MILO_FAIL(
            "rev stack (%08x %s %s != %08x %s %s)\n",
            obj,
            obj->ClassName(),
            PathName(obj),
            entry.obj,
            entry.obj->ClassName(),
            PathName(entry.obj)
        );
    }

    mRevStack->pop_back();
    return revCount;
}

void BinStream::Read(void *dest, int len) {
    if (Fail()) {
        MILO_NOTIFY_ONCE("Stream error: Can't read from %s", Name());
        std::memset(dest, 0, len);
        return;
    }

    AutoGlitchReport report(50.0f, __FUNCTION__);
    ReadImpl(dest, len);

    if (mCrypto) {
        unsigned char *ptr = static_cast<unsigned char*>(dest);
        unsigned char *end = ptr + len;
        for (; ptr < end; ++ptr) {
            *ptr ^= mCrypto->Int();
        }
    }
}

int BinStream::ReadAsync(void *buf, int len) {
    Read(buf, len);
    return Fail() ? 0 : len;
}

void BinStream::ReadEndian(void *dst, int sz) {
    Read(dst, sz);
    if (mLittleEndian) {
        SwapData(dst, dst, sz);
    }
}

void BinStream::ReadString(char *out, int maxChars) {
    unsigned int strLen;
    *this >> strLen;

    if (strLen >= static_cast<unsigned int>(maxChars)) {
        MILO_FAIL("String chars %u > %d", strLen + 1, maxChars);
    }

    Read(out, strLen);
    out[strLen] = '\0';
}

BinStream &BinStream::operator>>(Symbol &sym) {
    char buffer[BUF_SIZE];
    ReadString(buffer, BUF_SIZE);
    sym = buffer;
    return *this;
}

BinStream &BinStream::operator>>(String &str) {
    int len;
    *this >> len;
    str.resize(len);
    Read(const_cast<char*>(str.c_str()), len);
    return *this;
}

void BinStream::EnableReadEncryption() {
    MILO_ASSERT(!mCrypto, 0xC0);
    int seed;
    *this >> seed;
    mCrypto = new Rand2(seed);
}

BinStream::~BinStream() {
    delete mCrypto;
    delete mRevStack;
}

void BinStream::PushRev(int revs, Hmx::Object *obj) {
    if (!mRevStack) {
        mRevStack = new std::vector<ObjVersion>();
    }
    mRevStack->emplace_back(revs, obj);
}

