/*---------------------------------------------------------------------------*/
void TTWAIN_RecordError(void) {
    // Local buffer for intermediate formatting
    char TempBuffer[1024];

    // Fetch result and condition codes
    TTwainData.ErrRC = TTWAIN_GetResultCode();

    // Determine condition code only if relevant
    if (TTwainData.ErrRC == TWRC_FAILURE || TTwainData.ErrRC == TWRC_CHECKSTATUS) {
        TTwainData.ErrCC = TTWAIN_GetConditionCode();
    } else {
        TTwainData.ErrCC = -1;
    }

    // Format result code string
    size_t rc_index = (size_t)TTwainData.ErrRC;
    size_t rc_count = sizeof(ResultCodeStrings) / sizeof(ResultCodeStrings[0]);
    if (rc_index < rc_count) {
        snprintf(ErrorBuffer, sizeof(ErrorBuffer), "RC: %s(%d)",
                 ResultCodeStrings[rc_index], (int)TTwainData.ErrRC);
    } else {
        snprintf(ErrorBuffer, sizeof(ErrorBuffer), "RC: %s(%d)", "unknown",
                 (int)TTwainData.ErrRC);
    }

    // Append condition code string if valid
    if (TTwainData.ErrCC >= 0) {
        size_t cc_index = (size_t)TTwainData.ErrCC;
        size_t cc_count = sizeof(ConditionCodeStrings) / sizeof(ConditionCodeStrings[0]);
        if (cc_index < cc_count) {
            snprintf(TempBuffer, sizeof(TempBuffer), " CC: %s(%d)",
                     ConditionCodeStrings[cc_index], (int)TTwainData.ErrCC);
        } else {
            snprintf(TempBuffer, sizeof(TempBuffer), " CC: %s(%d)",
                     "unknown", (int)TTwainData.ErrCC);
        }
        strncat(ErrorBuffer, TempBuffer, sizeof(ErrorBuffer) - strlen(ErrorBuffer) - 1);
    }

    // Special handling for failure with operation error: log appropriately
    if (TTwainData.ErrRC == TWRC_FAILURE && TTwainData.ErrCC == TWCC_OPERATIONERROR) {
#ifdef _WIN32
        OutputDebugStringA(ErrorBuffer);
#else
#ifdef TOONZDEBUG
        fprintf(stderr, "%s\n", ErrorBuffer);
#endif
#endif
    }
}
/*---------------------------------------------------------------------------*/
char *TTWAIN_GetLastError(TUINT32 *out_rc, TUINT32 *out_cc) {
    assert(out_rc != NULL && out_cc != NULL);
    *out_rc = TTwainData.ErrRC;
    *out_cc = TTwainData.ErrCC;
    return ErrorBuffer;
}
