namespace Clipper2Lib {
  static const Rect64 null_rect = Rect64(false);

  // Scanline structure for sweep-line algorithm
  struct ScanLineNode {
    int64_t y_coord = 0;
    ScanLineNode* next_node = nullptr;
    explicit ScanLineNode(int64_t y_val) : y_coord(y_val) {}
  };

  // Horizontal segment sorting comparator
  struct HorzSegmentComparator {
    inline bool operator()(const HorzSegment& seg1, const HorzSegment& seg2) const
    {
      if (!seg1.right_op || !seg2.right_op) return (seg1.right_op);
      return seg2.left_op->pt.x > seg1.left_op->pt.x;
    }
  };

  // Local minimum sorting comparator
  struct MinimaComparator {
    inline bool operator()(const LocalMinima_ptr& min1,
                          const LocalMinima_ptr& min2) const
    {
      if (min2->vertex->pt.y != min1->vertex->pt.y)
        return min2->vertex->pt.y < min1->vertex->pt.y;
      else
        return min2->vertex->pt.x > min1->vertex->pt.x;
    }
  };

  // Utility functions for checking odd/even values
  inline bool IsOddValue(int val)
  {
    return (val & 1) ? true : false;
  }

  // Check if edge is part of output polygon
  inline bool IsPartOfOutput(const Active& edge)
  {
    return (edge.outrec != nullptr);
  }

  // Check if edge belongs to an open path
  inline bool IsOpenPath(const Active& edge)
  {
    return (edge.local_min->is_open);
  }

  // Check if vertex marks start/end of open path
  inline bool IsOpenEndpoint(const Vertex& vert)
  {
    return (vert.flags & (VertexFlags::OpenStart | VertexFlags::OpenEnd)) !=
      VertexFlags::Empty;
  }

  // Check if active edge ends an open path
  inline bool IsOpenEndpoint(const Active& ae)
  {
    return IsOpenEndpoint(*ae.vertex_top);
  }

  // Find previous hot edge in active edge list
  inline Active* FindPreviousHotEdge(const Active& edge)
  {
    Active* prev = edge.prev_in_ael;
    while (prev && (IsOpenPath(*prev) || !IsPartOfOutput(*prev)))
      prev = prev->prev_in_ael;
    return prev;
  }

  // Check if edge is at front of output record
  inline bool IsLeadingEdge(const Active& edge)
  {
    return (&edge == edge.outrec->front_edge);
  }

  // Validate output path
  inline bool IsValidLoop(OutPt* op)
  {
    return (!op || op->next == op);
  }

  // Calculate direction vector component
  inline double GetSlope(const Point64& pt1, const Point64& pt2)
  {
    double dy = double(pt2.y - pt1.y);
    if (dy != 0)
      return double(pt2.x - pt1.x) / dy;
    else if (pt2.x > pt1.x)
      return -std::numeric_limits<double>::max();
    else
      return std::numeric_limits<double>::max();
  }

  // Calculate X coordinate at given Y level
  inline int64_t GetXAtY(const Active& ae, const int64_t currentY)
  {
    if ((currentY == ae.top.y) || (ae.top.x == ae.bot.x)) return ae.top.x;
    else if (currentY == ae.bot.y) return ae.bot.x;
    else return ae.bot.x + static_cast<int64_t>(nearbyint(ae.dx * (currentY - ae.bot.y)));
  }

  // Check if edge is horizontal
  inline bool IsFlatEdge(const Active& e)
  {
    return (e.top.y == e.bot.y);
  }

  // Check if horizontal edge points right
  inline bool IsRightwardHorz(const Active& e)
  {
    return e.dx == -std::numeric_limits<double>::max();
  }

  // Check if horizontal edge points left
  inline bool IsLeftwardHorz(const Active& e)
  {
    return e.dx == std::numeric_limits<double>::max();
  }

  // Swap two active edges
  inline void ExchangeActives(Active*& e1, Active*& e2)
  {
    Active* temp = e1;
    e1 = e2;
    e2 = temp;
  }

  // Get polygon type from active edge
  inline PathType GetPolygonType(const Active& e)
  {
    return e.local_min->polytype;
  }

  // Check if two edges have same polygon type
  inline bool HaveSameType(const Active& e1, const Active& e2)
  {
    return e1.local_min->polytype == e2.local_min->polytype;
  }

  // Update slope calculation for edge
  inline void RecalcSlope(Active& e)
  {
    e.dx = GetSlope(e.bot, e.top);
  }

  // Get next vertex along edge
  inline Vertex* AdvanceToNextVertex(const Active& e)
  {
    if (e.wind_dx > 0)
      return e.vertex_top->next;
    else
      return e.vertex_top->prev;
  }

  // Get previous vertex (for alternate bound)
  inline Vertex* RetreatToPrevVertex(const Active& ae)
  {
    if (ae.wind_dx > 0)
      return ae.vertex_top->prev->prev;
    else
      return ae.vertex_top->next->next;
  }

  // Extract node from sorted edge list
  inline Active* RemoveFromSEL(Active* node)
  {
    Active* result = node->next_in_sel;
    if (result)
      result->prev_in_sel = node->prev_in_sel;
    node->prev_in_sel->next_in_sel = result;
    return result;
  }

  // Insert node before another in SEL
  inline void InsertBeforeInSEL(Active* new_node, Active* target)
  {
    new_node->prev_in_sel = target->prev_in_sel;
    if (new_node->prev_in_sel)
      new_node->prev_in_sel->next_in_sel = new_node;
    new_node->next_in_sel = target;
    target->prev_in_sel = new_node;
  }

  // Check if vertex is local maximum
  inline bool IsPeak(const Vertex& v)
  {
    return ((v.flags & VertexFlags::LocalMax) != VertexFlags::Empty);
  }

  // Check if active edge terminates at local maximum
  inline bool IsPeak(const Active& e)
  {
    return IsPeak(*e.vertex_top);
  }

  // Get maxima vertex for open paths
  inline Vertex* GetCurrentMaxVertex_Open(const Active& e)
  {
    Vertex* result = e.vertex_top;
    if (e.wind_dx > 0)
      while ((result->next->pt.y == result->pt.y) &&
        ((result->flags & (VertexFlags::OpenEnd |
          VertexFlags::LocalMax)) == VertexFlags::Empty))
            result = result->next;
    else
      while (result->prev->pt.y == result->pt.y &&
        ((result->flags & (VertexFlags::OpenEnd |
          VertexFlags::LocalMax)) == VertexFlags::Empty))
          result = result->prev;
    if (!IsPeak(*result)) result = nullptr;
    return result;
  }

  // Get maxima vertex for closed paths
  inline Vertex* GetCurrentMaxVertex(const Active& e)
  {
    Vertex* result = e.vertex_top;
    if (e.wind_dx > 0)
      while (result->next->pt.y == result->pt.y) result = result->next;
    else
      while (result->prev->pt.y == result->pt.y) result = result->prev;
    if (!IsPeak(*result)) result = nullptr;
    return result;
  }

  // Find matching maxima edge
  Active* FindMatchingMaxima(const Active& e)
  {
    Active* pair = e.next_in_ael;
    while (pair)
    {
      if (pair->vertex_top == e.vertex_top) return pair;
      pair = pair->next_in_ael;
    }
    return nullptr;
  }

  // Count vertices in output loop
  inline int CountLoopPoints(OutPt* op)
  {
    OutPt* current = op;
    int count = 0;
    do
    {
      current = current->next;
      ++count;
    } while (current != op);
    return count;
  }

  // Duplicate output point
  inline OutPt* CloneOp(OutPt* op, bool insert_after)
  {
    OutPt* result = new OutPt(op->pt, op->outrec);
    if (insert_after)
    {
      result->next = op->next;
      result->next->prev = result;
      result->prev = op;
      op->next = result;
    }
    else
    {
      result->prev = op->prev;
      result->prev->next = result;
      result->next = op;
      op->prev = result;
    }
    return result;
  }

  // Remove output point from loop
  inline OutPt* RemoveOpNode(OutPt* op)
  {
    OutPt* result = op->next;
    op->prev->next = op->next;
    op->next->prev = op->prev;
    delete op;
    return result;
  }

  // Clear all output points for a region
  inline void ClearLoopPoints(OutRec* outrec)
  {
    OutPt* op = outrec->pts;
    op->prev->next = nullptr;
    while (op)
    {
      OutPt* tmp = op;
      op = op->next;
      delete tmp;
    };
    outrec->pts = nullptr;
  }

  // Sort intersect nodes by position
  bool IntersectNodeSorter(const IntersectNode& a, const IntersectNode& b)
  {
    return (a.pt.y == b.pt.y) ? (a.pt.x < b.pt.x) : (a.pt.y > b.pt.y);
  }

  // Set sides for output record
  inline void AssignSides(OutRec& outrec, Active& start_edge, Active& end_edge)
  {
    outrec.front_edge = &start_edge;
    outrec.back_edge = &end_edge;
  }

  // Swap output records between edges
  void SwapOutputRecords(Active& e1, Active& e2)
  {
    OutRec* rec1 = e1.outrec;
    OutRec* rec2 = e2.outrec;
    if (rec1 == rec2)
    {
      Active* temp = rec1->front_edge;
      rec1->front_edge = rec1->back_edge;
      rec1->back_edge = temp;
      return;
    }
    if (rec1)
    {
      if (&e1 == rec1->front_edge)
        rec1->front_edge = &e2;
      else
        rec1->back_edge = &e2;
    }
    if (rec2)
    {
      if (&e2 == rec2->front_edge)
        rec2->front_edge = &e1;
      else
        rec2->back_edge = &e1;
    }
    e1.outrec = rec2;
    e2.outrec = rec1;
  }

  // Calculate area using shoelace formula
  double CalculateArea(OutPt* op)
  {
    double result = 0.0;
    OutPt* current = op;
    do
    {
      result += static_cast<double>(current->prev->pt.y + current->pt.y) *
        static_cast<double>(current->prev->pt.x - current->pt.x);
      current = current->next;
    } while (current != op);
    return result * 0.5;
  }

  // Calculate triangle area
  inline double TriangleArea(const Point64& pt1,
    const Point64& pt2, const Point64& pt3)
  {
    return (static_cast<double>(pt3.y + pt1.y) * static_cast<double>(pt3.x - pt1.x) +
      static_cast<double>(pt1.y + pt2.y) * static_cast<double>(pt1.x - pt2.x) +
      static_cast<double>(pt2.y + pt3.y) * static_cast<double>(pt2.x - pt3.x));
  }

  // Reverse output loop direction
  void ReverseLoopDirection(OutPt* op)
  {
    if (!op) return;
    OutPt* first = op;
    OutPt* second;
    do
    {
      second = first->next;
      first->next = first->prev;
      first->prev = second;
      first = second;
    } while (first != op);
  }

  // Swap front/back sides of output record
  inline void FlipSides(OutRec& outrec)
  {
    Active* temp = outrec.front_edge;
    outrec.front_edge = outrec.back_edge;
    outrec.back_edge = temp;
    outrec.pts = outrec.pts->next;
  }

  // Get actual output record (skip empty ones)
  inline OutRec* GetValidRecord(OutRec* outrec)
  {
    while (outrec && !outrec->pts) outrec = outrec->owner;
    return outrec;
  }

  // Check ownership validity
  inline bool ValidOwnership(OutRec* outrec, OutRec* testOwner)
  {
    while (testOwner && testOwner != outrec) testOwner = testOwner->owner;
    return !testOwner;
  }

  // Disconnect output record from edges
  inline void DetachOutputRecord(Active ae)
  {
    OutRec* outrec = ae.outrec;
    if (!outrec) return;
    outrec->front_edge->outrec = nullptr;
    outrec->back_edge->outrec = nullptr;
    outrec->front_edge = nullptr;
    outrec->back_edge = nullptr;
  }

  // Check if points are very close
  inline bool ArePointsNear(const Point64& pt1, const Point64& pt2)
  {
    return (std::llabs(pt1.x - pt2.x) < 2) && (std::llabs(pt1.y - pt2.y) < 2);
  }

  // Check if triangle is very small
  inline bool IsTinyTriangle(const OutPt& op)
  {
    return op.next->next == op.prev &&
      (ArePointsNear(op.prev->pt, op.next->pt) ||
        ArePointsNear(op.pt, op.next->pt) ||
        ArePointsNear(op.pt, op.prev->pt));
  }

  // Check if path is valid and closed
  inline bool IsValidClosedLoop(const OutPt* op)
  {
    return op && (op->next != op) && (op->next != op->prev) &&
      !IsTinyTriangle(*op);
  }

  // Check if output record follows ascending order
  inline bool IsAscendingOrder(const Active* hotEdge)
  {
    return (hotEdge == hotEdge->outrec->front_edge);
  }

  // Swap front/back sides
  inline void SwapSides(OutRec& outrec)
  {
    Active* temp = outrec.front_edge;
    outrec.front_edge = outrec.back_edge;
    outrec.back_edge = temp;
    outrec.pts = outrec.pts->next;
  }

  // Check if intersecting edges are adjacent in AEL
  inline bool AreEdgesAdjacent(const IntersectNode& inode)
  {
    return (inode.edge1->next_in_ael == inode.edge2) || (inode.edge1->prev_in_ael == inode.edge2);
  }

  // Check if edge has join operation
  inline bool HasJoin(const Active& e)
  {
    return e.join_with != JoinWith::NoJoin;
  }

  // Set owner for output record
  inline void AssignOwner(OutRec* outrec, OutRec* new_owner)
  {
    new_owner->owner = GetValidRecord(new_owner->owner);
    OutRec* temp = new_owner;
    while (temp && temp != outrec) temp = temp->owner;
    if (temp) new_owner->owner = outrec->owner;
    outrec->owner = new_owner;
  }

  // Point-in-polygon test
  static PointInPolygonResult PointInPolygonTest(const Point64& pt, OutPt* op)
  {
    if (op == op->next || op->prev == op->next)
      return PointInPolygonResult::IsOutside;
    OutPt* current = op;
    do
    {
      if (op->pt.y != pt.y) break;
      op = op->next;
    } while (op != current);
    if (op->pt.y == pt.y)
      return PointInPolygonResult::IsOutside;
    bool is_above = op->pt.y < pt.y, starting_above = is_above;
    int val = 0;
    current = op->next;
    while (current != op)
    {
      if (is_above)
        while (current != op && current->pt.y < pt.y) current = current->next;
      else
        while (current != op && current->pt.y > pt.y) current = current->next;
      if (current == op) break;
      if (current->pt.y == pt.y)
      {
        if (current->pt.x == pt.x || (current->pt.y == current->prev->pt.y &&
          (pt.x < current->prev->pt.x) != (pt.x < current->pt.x)))
          return PointInPolygonResult::IsOn;
        current = current->next;
        if (current == op) break;
        continue;
      }
      if (pt.x < current->pt.x && pt.x < current->prev->pt.x);
      else if ((pt.x > current->prev->pt.x && pt.x > current->pt.x))
        val = 1 - val;
      else
      {
        int i = CrossProductSign(current->prev->pt, current->pt, pt);
        if (i == 0) return PointInPolygonResult::IsOn;
        if ((i < 0) == is_above) val = 1 - val;
      }
      is_above = !is_above;
      current = current->next;
    }
    if (is_above != starting_above)
    {
      int i = CrossProductSign(current->prev->pt, current->pt, pt);
      if (i == 0) return PointInPolygonResult::IsOn;
      if ((i < 0) == is_above) val = 1 - val;
    }
    if (val == 0) return PointInPolygonResult::IsOutside;
    else return PointInPolygonResult::IsInside;
  }

  // Clean path by removing redundant points
  inline Path64 SimplifyPath(OutPt* op)
  {
    Path64 result;
    OutPt* current = op;
    while (current->next != op &&
      ((current->pt.x == current->next->pt.x && current->pt.x == current->prev->pt.x) ||
        (current->pt.y == current->next->pt.y && current->pt.y == current->prev->pt.y))) 
      current = current->next;
    result.emplace_back(current->pt);
    OutPt* lastPoint = current;
    current = current->next;
    while (current != op)
    {
      if ((current->pt.x != current->next->pt.x || current->pt.x != lastPoint->pt.x) &&
        (current->pt.y != current->next->pt.y || current->pt.y != lastPoint->pt.y))
      {
        result.emplace_back(current->pt);
        lastPoint = current;
      }
      current = current->next;
    }
    return result;
  }

  // Check if one path contains another
  inline bool ContainsPath(OutPt* inner, OutPt* outer)
  {
    PointInPolygonResult containment = PointInPolygonResult::IsOn;
    OutPt* current = inner;
    do {
      switch (PointInPolygonTest(current->pt, outer))
      {
      case PointInPolygonResult::IsOutside:
        if (containment == PointInPolygonResult::IsOutside) return false;
        containment = PointInPolygonResult::IsOutside;
        break;
      case PointInPolygonResult::IsInside:
        if (containment == PointInPolygonResult::IsInside) return true;
        containment = PointInPolygonResult::IsInside;
        break;
      default: break;
      }
      current = current->next;
    } while (current != inner);
    return ContainsPath(SimplifyPath(inner), SimplifyPath(outer));
  }

  // Add local minimum to list
  void AddMinimum(LocalMinimaList& list,
    Vertex& vert, PathType polytype, bool is_open)
  {
    if ((VertexFlags::LocalMin & vert.flags) != VertexFlags::Empty) return;
    vert.flags = (vert.flags | VertexFlags::LocalMin);
    list.emplace_back(std::make_unique <LocalMinima>(&vert, polytype, is_open));
  }

  // Process paths to extract local minima
  void ProcessPaths_(const Paths64& paths, PathType polytype, bool is_open,
    std::vector<Vertex*>& vertexLists, LocalMinimaList& locMinList)
  {
    const auto total_vertex_count =
      std::accumulate(paths.begin(), paths.end(), size_t(0),
        [](const auto& a, const Path64& path)
        {return a + path.size(); });
    if (total_vertex_count == 0) return;
    Vertex* vertices = new Vertex[total_vertex_count], * v = vertices;
    for (const Path64& path : paths)
    {
      Vertex* v0 = v, * curr_v = v, * prev_v = nullptr;
      if (path.empty())
        continue;
      v->prev = nullptr;
      int cnt = 0;
      for (const Point64& pt : path)
      {
        if (prev_v)
        {
          if (prev_v->pt == pt) continue;
          prev_v->next = curr_v;
        }
        curr_v->prev = prev_v;
        curr_v->pt = pt;
        curr_v->flags = VertexFlags::Empty;
        prev_v = curr_v++;
        cnt++;
      }
      if (!prev_v || !prev_v->prev) continue;
      if (!is_open && prev_v->pt == v0->pt)
        prev_v = prev_v->prev;
      prev_v->next = v0;
      v0->prev = prev_v;
      v = curr_v;
      if (cnt < 2 || (cnt == 2 && !is_open)) continue;

      // Find local minima
      bool going_up, going_up0;
      if (is_open)
      {
        curr_v = v0->next;
        while (curr_v != v0 && curr_v->pt.y == v0->pt.y)
          curr_v = curr_v->next;
        going_up = curr_v->pt.y <= v0->pt.y;
        if (going_up)
        {
          v0->flags = VertexFlags::OpenStart;
          AddMinimum(locMinList , *v0, polytype, true);
        }
        else
          v0->flags = VertexFlags::OpenStart | VertexFlags::LocalMax;
      }
      else
      {
        prev_v = v0->prev;
        while (prev_v != v0 && prev_v->pt.y == v0->pt.y)
          prev_v = prev_v->prev;
        if (prev_v == v0)
          continue;
        going_up = prev_v->pt.y > v0->pt.y;
      }
      going_up0 = going_up;
      prev_v = v0;
      curr_v = v0->next;
      while (curr_v != v0)
      {
        if (curr_v->pt.y > prev_v->pt.y && going_up)
        {
          prev_v->flags = (prev_v->flags | VertexFlags::LocalMax);
          going_up = false;
        }
        else if (curr_v->pt.y < prev_v->pt.y && !going_up)
        {
          going_up = true;
          AddMinimum(locMinList, *prev_v, polytype, is_open);
        }
        prev_v = curr_v;
        curr_v = curr_v->next;
      }
      if (is_open)
      {
        prev_v->flags = prev_v->flags | VertexFlags::OpenEnd;
        if (going_up)
          prev_v->flags = prev_v->flags | VertexFlags::LocalMax;
        else
          AddMinimum(locMinList, *prev_v, polytype, is_open);
      }
      else if (going_up != going_up0)
      {
        if (going_up0) AddMinimum(locMinList, *prev_v, polytype, false);
        else prev_v->flags = prev_v->flags | VertexFlags::LocalMax;
      }
    }
    vertexLists.emplace_back(vertices);
  }

