  void ClipperBase::RemoveEdges(Active*& e)
  {
    while (e)
    {
      Active* temp = e;
      e = e->next_in_ael;
      delete temp;
    }
  }

  void ClipperBase::Cleanup()
  {
    RemoveEdges(actives_);
    scanline_list_ = std::priority_queue<int64_t>();
    intersect_nodes_.clear();
    DisposeAllRecords();
    horz_seg_list_.clear();
    horz_join_list_.clear();
  }

  void ClipperBase::Clear()
  {
    Cleanup();
    ReleaseVerticesAndMinima();
    current_locmin_iter_ = minima_list_.begin();
    minima_list_sorted_ = false;
    has_open_paths_ = false;
  }

  void ClipperBase::ResetState()
  {
    if (!minima_list_sorted_)
    {
      std::stable_sort(minima_list_.begin(), minima_list_.end(), MinimaComparator());
      minima_list_sorted_ = true;
    }
    LocalMinimaList::const_reverse_iterator iter;
    for (iter = minima_list_.rbegin(); iter != minima_list_.rend(); ++iter)
      InsertScanline((*iter)->vertex->pt.y);
    current_locmin_iter_ = minima_list_.begin();
    actives_ = nullptr;
    sel_ = nullptr;
    succeeded_ = true;
  }

