  {
    succeeded_ = false;
    minima_list_sorted_ = false;
    LocalMinimaList::const_iterator iter;
    for (iter = reuseable_data.minima_list_.cbegin(); iter != reuseable_data.minima_list_.cend(); ++iter)
    {
      minima_list_.emplace_back(std::make_unique <LocalMinima>((*iter)->vertex, (*iter)->polytype, (*iter)->is_open));
      if ((*iter)->is_open) has_open_paths_ = true;
    }
