  bool ClipperBase::IsContributingClosed(const Active& e) const
  {
    switch (fillrule_)
    {
    case FillRule::EvenOdd:
      break;
    case FillRule::NonZero:
      if (abs(e.wind_cnt) != 1) return false;
      break;
    case FillRule::Positive:
      if (e.wind_cnt != 1) return false;
      break;
    case FillRule::Negative:
      if (e.wind_cnt != -1) return false;
      break;
    default:
      break;
    }
    switch (cliptype_)
    {
    case ClipType::NoClip:
      return false;
    case ClipType::Intersection:
      switch (fillrule_)
      {
      case FillRule::Positive:
        return (e.wind_cnt2 > 0);
      case FillRule::Negative:
        return (e.wind_cnt2 < 0);
      default:
        return (e.wind_cnt2 != 0);
      }
      break;
    case ClipType::Union:
      switch (fillrule_)
      {
      case FillRule::Positive:
        return (e.wind_cnt2 <= 0);
      case FillRule::Negative:
        return (e.wind_cnt2 >= 0);
      default:
        return (e.wind_cnt2 == 0);
      }
      break;
    case ClipType::Difference:
      bool outcome;
      switch (fillrule_)
      {
      case FillRule::Positive:
        outcome = (e.wind_cnt2 <= 0);
        break;
      case FillRule::Negative:
        outcome = (e.wind_cnt2 >= 0);
        break;
      default:
        outcome = (e.wind_cnt2 == 0);
      }
      if (GetPolygonType(e) == PathType::Subject)
        return outcome;
      else
        return !outcome;
      break;
    case ClipType::Xor: return true;
    default:
      break;
    }
    return false;
  }

  inline bool ClipperBase::IsContributingOpen(const Active& e) const
  {
    bool in_clip, in_subject;
    switch (fillrule_)
    {
    case FillRule::Positive:
      in_clip = e.wind_cnt2 > 0;
      in_subject = e.wind_cnt > 0;
      break;
    case FillRule::Negative:
      in_clip = e.wind_cnt2 < 0;
      in_subject = e.wind_cnt < 0;
      break;
    default:
      in_clip = e.wind_cnt2 != 0;
      in_subject = e.wind_cnt != 0;
    }
    switch (cliptype_)
    {
    case ClipType::Intersection: return in_clip;
    case ClipType::Union: return (!in_subject && !in_clip);
    default: return !in_clip;
    }
  }

