#include "tiger_parser.hpp"
#include "geometry/distance_on_sphere.hpp"
#include <algorithm>
namespace tiger
{
using namespace strings;
void ParseGeometry(std::string_view s, std::vector<ms::LatLon> & geom)
{
    std::string_view constexpr prefix = "LINESTRING(";
    if (!s.ends_with(')') || !s.starts_with(prefix))
        return;
    s.remove_prefix(prefix.size());
    s.remove_suffix(1);
    ms::LatLon currentPoint;

    // Helper function to determine if we should skip adding a point based on distance
    auto const shouldSkipPoint = [&currentPoint, &geom]()
    {
        // Check simple distance (meters) threshold.
        return !geom.empty() && ms::DistanceOnEarth(geom.back(), currentPoint) < 10.0;
    };

    Tokenize(s, ",", [&](std::string_view token)
    {
        auto spacePos = token.find(' ');
        CHECK(spacePos != std::string_view::npos, (token));
        CHECK(to_double(token.substr(0, spacePos), currentPoint.m_lon), (token));
        CHECK(to_double(token.substr(spacePos + 1), currentPoint.m_lat), (token));

        if (!shouldSkipPoint())
            geom.push_back(currentPoint);
    });

    // Handle final point when skipping is needed
    if (shouldSkipPoint())
    {
        auto & lastElement = geom.back();
        if (geom.size() == 1)
        {
            // Set one middle point address.
            lastElement = ms::LatLon{(lastElement.m_lat + currentPoint.m_lat) / 2.0, 
                                    (lastElement.m_lon + currentPoint.m_lon) / 2.0};
        }
        else
        {
            // Replace last point.
            lastElement = currentPoint;
        }
    }
}

feature::InterpolType ParseInterpolation(std::string_view s)
{
    if (s == "all")
        return feature::InterpolType::Any;
    if (s == "odd")
        return feature::InterpolType::Odd;
    if (s == "even")
        return feature::InterpolType::Even;
    return feature::InterpolType::None;
}

bool ParseLine(std::string_view line, AddressEntry & e)
{
    // from;to;interpolation;street;city;state;postcode;geometry
    // Basic check.
    if (std::count(line.begin(), line.end(), ';') != 7)
        return false;

    TokenizeIterator<SimpleDelimiter, std::string_view::const_iterator, true /* KeepEmptyTokens */> it(line.begin(),
                                                                                                     line.end(), ";");
    e.m_from = *it;
    ++it;
    e.m_to = *it;
    ++it;
    e.m_interpol = ParseInterpolation(*it);
    ++it;
    e.m_street = *it;
    ++it;
    ++it;
    ++it;
    e.m_postcode = *it;
    ++it;
    ParseGeometry(*it, e.m_geom);

    if (e.m_interpol == feature::InterpolType::None || e.m_geom.empty())
        return false;

    // Check and order house numbers.
    auto const range = e.GetHNRange();
    if (range == AddressEntry::kInvalidRange)
        return false;
    if (range.second < range.first)
    {
        std::swap(e.m_from, e.m_to);
        std::reverse(e.m_geom.begin(), e.m_geom.end());
    }
    return true;
}
