using namespace db;

void CommitHistoryRebaser::rebase(const MetadataRebaser& metadataRebaser,
                                  DataPartRebaser& dataPartRebaser,
                                  const CommitHistory& prevHistory) {
    // Clear journal entries to ensure fresh state after rebasing
    _history.journal().clear();

    // Prepare updated list of all data parts
    std::vector<std::unique_ptr<DataPart>> updatedParts = prevHistory._allDataparts;
    const size_t newCommitsCount = _history._commitDataparts.size();

    // Extend the vector to accommodate newly committed parts
    updatedParts.reserve(updatedParts.size() + newCommitsCount);
    for (const auto& part : _history._commitDataparts) {
        updatedParts.push_back(std::move(part));
    }

    // Update internal state with merged data parts
    _history._allDataparts = std::move(updatedParts);

    // Reassign commit dataparts span to point to the tail of the full list
    const size_t baseIndex = _history._allDataparts.size() - newCommitsCount;
    _history._commitDataparts = {_history._allDataparts.data() + baseIndex, newCommitsCount};

    // Skip rebasing if no previous parts exist
    const auto& priorParts = prevHistory._allDataparts;
    if (priorParts.empty()) {
        return;
    }

    // Sequentially rebase each newly committed part against its predecessor
    const DataPart* lastPart = priorParts.back().get();
    for (size_t i = 0; i < newCommitsCount; ++i) {
        DataPart& currentPart = *_history._allDataparts[baseIndex + i];
        dataPartRebaser.rebase(metadataRebaser, *lastPart, currentPart);
        lastPart = &currentPart;
    }
}

void CommitHistoryRebaser::removeCreatedDataParts() {
    // Compute how many parts remain after removing those created in this commit
    size_t remainingCount = _history._allDataparts.size() - _history._commitDataparts.size();
    resizeDataParts(remainingCount);
    resetCommitDataParts();
}

void CommitHistoryRebaser::resizeDataParts(size_t newSize) {
    _history._allDataparts.resize(newSize);
}

void CommitHistoryRebaser::resetCommitDataParts() {
    // Reset commit dataparts span to zero-length while preserving original pointer
    _history._commitDataparts = {_history._commitDataparts.data(), 0};
}

