    // Helper function to validate basic xrange behavior for [begin, end)
    void TestBasicXRange(size_t begin, size_t end) {
        size_t counter = 0;
        size_t total = 0;
        size_t startVal = 42;
        bool firstSet = false;
        size_t finalVal = 0;

        for (auto idx : xrange(begin, end)) {
            ++counter;
            total += idx;
            finalVal = idx;
            if (!firstSet) {
                startVal = idx;
                firstSet = true;
            }
        }

        UNIT_ASSERT_VALUES_EQUAL(counter, end - begin);
        UNIT_ASSERT_VALUES_EQUAL(startVal, begin);
        UNIT_ASSERT_VALUES_EQUAL(finalVal, end - 1);
        UNIT_ASSERT_VALUES_EQUAL(total, counter * (startVal + finalVal) / 2);
    }

    // Helper function to validate stepped xrange against expected values
    void TestSteppedXRange(int begin, int end, int step, const TVector<int>& expected) {
        size_t idx = 0;
        for (auto val : xrange(begin, end, step)) {
            UNIT_ASSERT(idx < expected.size());
            UNIT_ASSERT_VALUES_EQUAL(val, expected[idx]);
            ++idx;
        }
        UNIT_ASSERT_VALUES_EQUAL(idx, expected.size());
    }

    Y_UNIT_TEST(IncrementWorks) {
        TestBasicXRange(0, 10);
        TestBasicXRange(10, 20);
