// Test iteration over const std::map and std::unordered_map values
TEST(IterateValues, ConstMappingIteration) {
    const std::map<int, int> squares{
        {1, 1},
        {2, 4},
        {3, 9},
    };

    // Extract values from map using IterateValues
    std::vector<int> mapValues;
    for (const auto& val : IterateValues(squares)) {
        mapValues.push_back(val);
    }
    EXPECT_THAT(mapValues, ElementsAre(1, 4, 9));

    const std::unordered_map<int, int> roots{
        {49, 7},
        {36, 6},
        {25, 5},
    };

    // Extract values from unordered_map using IterateValues
    std::vector<int> unorderedMapValues;
    for (const auto& val : IterateValues(roots)) {
        unorderedMapValues.push_back(val);
    }
    EXPECT_THAT(unorderedMapValues, UnorderedElementsAre(5, 6, 7));

    const std::map<int, std::string> translations{
        {1, "one"},
        {2, "two"},
        {3, "three"},
    };

    // Concatenate string values using Accumulate
    std::string concatenated;
    for (const auto& str : IterateValues(translations)) {
        concatenated += str;
    }
    EXPECT_EQ(concatenated, "onetwothree");
}

