#include <pangolin/plot/loaders/csv_table_loader.h>
#include <fstream>
#include <memory>

namespace pangolin {

CsvTableLoader::CsvTableLoader(const std::vector<std::string>& csv_files, char delimiter, char comment_char)
    : delim(delimiter), comment(comment_char)
{
    for (const auto& filepath : csv_files) {
        if (filepath == "-") {
            streams.emplace_back(&std::cin);
        } else {
            auto file_ptr = std::make_unique<std::ifstream>(filepath);
            PANGO_ASSERT(file_ptr->is_open());
            owned_streams.push_back(std::move(file_ptr));
            streams.emplace_back(owned_streams.back().get());
        }
    }
}

bool CsvTableLoader::SkipLines(const std::vector<size_t>& skip_counts)
{
    if (!skip_counts.empty()) {
        PANGO_ASSERT(skip_counts.size() == streams.size());

        std::vector<std::string> placeholder;
        for (size_t idx = 0; idx < streams.size(); ++idx) {
            const size_t count = skip_counts[idx];
            for (size_t line_num = 0; line_num < count; ++line_num) {
                if (!DiscardRow(*streams[idx], delim)) {
                    return false;
                }
            }
        }
    }
    return true;
}

bool CsvTableLoader::ReadRow(std::vector<std::string>& output_row)
{
    output_row.clear();
    for (auto* stream_ptr : streams) {
        if (!ExtractFields(output_row, *stream_ptr, delim, comment)) {
            return false;
        }
    }
    return true;
}

// Helper: Discard one logical row (skipping comments)
bool CsvTableLoader::DiscardRow(std::istream& input, char delimiter)
{
    std::string buffer;
    do {
        if (!std::getline(input, buffer)) {
            return false;
        }
    } while (!buffer.empty() && buffer[0] == comment);

    // Even if we read an empty line after EOF, it's still considered "consumed"
    return true;
}

// Helper: Parse one logical row into fields, respecting delimiters and comments
bool CsvTableLoader::ExtractFields(std::vector<std::string>& target, std::istream& input,
                                   char delimiter, char comment_marker)
{
    std::string raw_line;
    do {
        if (!std::getline(input, raw_line)) {
            return false;
        }
    } while (!raw_line.empty() && raw_line[0] == comment_marker);

    std::istringstream line_stream(raw_line);
    std::string field;

    while (std::getline(line_stream, field, delimiter)) {
        target.push_back(field);
    }

    // Handle trailing empty field (e.g., "a,b," -> ["a", "b", ""])
    if (line_stream.eof() && field.empty() && !target.empty()) {
        target.push_back("");
    }

    return true;
}

}

#include "common/mem_pool.h"
#include <gtest/gtest.h>

namespace zen::test {
using namespace zen;
using namespace common;

// Test CodeMemPool allocation behavior and boundary conditions
TEST(Mempool, CodeMemPool) {
  CodeMemPool allocator;
  auto initialBase = allocator.getMemStart();

  // Initial state: start, end, and page end should all point to base
  EXPECT_EQ(allocator.getMemStart(), initialBase);
  EXPECT_EQ(allocator.getMemEnd(), initialBase);
  EXPECT_EQ(allocator.getMemPageEnd(), initialBase);

  // First allocation: 10 bytes
  void* firstBlock = allocator.allocate(10);
  EXPECT_EQ(allocator.getMemStart(), initialBase);
  EXPECT_EQ(allocator.getMemEnd(), initialBase + 10);
  EXPECT_EQ(firstBlock, initialBase);
  EXPECT_EQ(allocator.getMemPageEnd(), initialBase + 4096);

  // Second allocation: another 10 bytes (with alignment padding)
  void* secondBlock = allocator.allocate(10);
  EXPECT_EQ(allocator.getMemStart(), initialBase);
  EXPECT_EQ(allocator.getMemEnd(), initialBase + 26); // 10 + 6 (padding) + 10
  EXPECT_EQ(secondBlock, initialBase + 16);           // aligned at 16-byte boundary
  EXPECT_EQ(allocator.getMemPageEnd(), initialBase + 4096);

  // Third allocation: large block (4096 bytes), triggers new page
  void* largeBlock = allocator.allocate(4096);
  EXPECT_EQ(allocator.getMemStart(), initialBase);
  EXPECT_EQ(allocator.getMemEnd(), initialBase + 32 + 4096); // 26 + 6 (padding) + 4096
  EXPECT_EQ(largeBlock, initialBase + 32);                   // aligned after previous block
  EXPECT_EQ(allocator.getMemPageEnd(), initialBase + 4096 * 2);

  // Final check: attempt to exceed max allowed size should fail
  EXPECT_DEATH(allocator.allocate(CodeMemPool::MaxCodeSize), "");
}

} // namespace zen::test

int main(int argc, char **argv) {
  ::testing::InitGoogleTest(&argc, argv);
  return RUN_ALL_TESTS();
}

#include "simulation.h"
#include <algorithm>
#include <thread>
#include <limits>
#include <vector>

namespace unravel
{
using namespace std::chrono_literals;

simulation::simulation()
{
    // Ensure max_inactive_fps_ is at least as large as max_fps_ if initially zero
    if (max_inactive_fps_ == 0)
    {
        max_inactive_fps_ = max_fps_;
    }
}

void simulation::run_one_frame(bool is_active)
{
    auto const now = clock_t::now();
    duration_t elapsed = now - last_frame_timepoint_;

    // Determine effective FPS cap based on activity state
    uint32_t current_max_fps = max_fps_;
    if (!is_active && current_max_fps > 0)
    {
        current_max_fps = std::min(max_inactive_fps_, current_max_fps);
    }

    // Throttle frame rate if needed
    if (current_max_fps > 0)
    {
        duration_t const min_frame_duration = 1000ms / current_max_fps;

        while (true)
        {
            auto const current_time = clock_t::now();
            elapsed = current_time - last_frame_timepoint_;

            // Exit if enough time has passed or time went backward (e.g., system clock adjustment)
            if (elapsed >= min_frame_duration || elapsed < duration_t::zero())
            {
                break;
            }

            // Compute remaining sleep time
            duration_t const remaining = min_frame_duration - elapsed;
            if (remaining > std::chrono::microseconds(1000))
            {
                auto const ms = std::chrono::duration_cast<std::chrono::milliseconds>(remaining);
                if (ms.count() > 0)
                {
                    // Distribute sleep into smaller chunks to reduce overshoot
                    duration_t const chunk = remaining / static_cast<duration_t::rep>(ms.count());
                    std::this_thread::sleep_for(chunk);
                }
            }
        }
    }

    // Clamp negative elapsed times to zero
    if (elapsed < duration_t::zero())
    {
        elapsed = duration_t::zero();
    }

    // Update frame timestamp
    last_frame_timepoint_ = clock_t::now();

    // Enforce minimum FPS by clamping elapsed time
    if (min_fps_ > 0)
    {
        duration_t const max_allowed_dt = 1000ms / min_fps_;
        if (elapsed > max_allowed_dt)
        {
            elapsed = max_allowed_dt;
        }
    }

    // Apply time-step smoothing if enabled
    if (smoothing_step_ > 0)
    {
        timestep_ = duration_t::zero();

        // Store new delta
        recent_deltas_.push_back(elapsed);

        // Trim older entries beyond smoothing window
        if (recent_deltas_.size() > smoothing_step_)
        {
            recent_deltas_.erase(recent_deltas_.begin(),
                                 recent_deltas_.begin() + (recent_deltas_.size() - smoothing_step_));
        }

        // Average over retained deltas
        for (auto const& dt : recent_deltas_)
        {
            timestep_ += dt;
        }
        timestep_ /= static_cast<duration_t::rep>(recent_deltas_.size());
    }
    else
    {
        timestep_ = elapsed;
    }

    ++frame_count_;
}

auto simulation::get_frame() const -> uint64_t
{
    return frame_count_;
}

void simulation::set_min_fps(uint32_t fps)
{
    min_fps_ = std::max<uint32_t>(fps, 0u);
}

void simulation::set_max_fps(uint32_t fps)
{
    max_fps_ = std::max<uint32_t>(fps, 0u);
}

void simulation::set_max_inactive_fps(uint32_t fps)
{
    max_inactive_fps_ = std::max<uint32_t>(fps, 0u);
}

void simulation::set_time_smoothing_step(uint32_t step)
{
    smoothing_step_ = step;
}

auto simulation::get_time_since_launch() const -> duration_t
{
    return clock_t::now() - launch_timepoint_;
}

auto simulation::get_fps() const -> float
{
    auto const dt_ms = std::chrono::duration_cast<std::chrono::duration<float, std::milli>>(get_delta_time()).count();
    return (std::abs(dt_ms) < std::numeric_limits<float>::epsilon()) ? 0.0f : 1000.0f / dt_ms;
}

auto simulation::get_delta_time() const -> delta_t
{
    return std::chrono::duration_cast<delta_t>(timestep_) * time_scale_;
}

void simulation::set_time_scale(float scale)
{
    time_scale_ = scale;
}

auto simulation::get_time_scale() const -> float
{
    return time_scale_;
}

