void nccl_check(ncclResult_t status, const char* file, int line) {
    if (status != ncclSuccess) {
        throw std::runtime_error(fmt::format("NCCL error at {}:{}: {}", file, line, ncclGetErrorString(status)));
    }
}
#define ncclCheck(cmd) (nccl_check((cmd), __FILE__, __LINE__))

struct NCCLCommunicator::CommandBuffer {
    struct GatherOp {
        std::byte* src_ptr;
        std::byte* dst_ptr;
        std::size_t byte_count;
    };

    struct ScatterReduceOp {
        ETensorDType dtype;
        std::byte* tensor_data;
        std::size_t element_count;
    };

    struct SendOp {
        const std::byte* buffer;
        std::size_t size_bytes;
        int destination_rank;
    };

    struct RecvOp {
        std::byte* output_buffer;
        std::size_t size_bytes;
        int source_rank;
    };

    std::vector<std::function<void(NCCLCommunicator*)>> operations;
    cudaEvent_t completion_event = nullptr;
};

NCCLCommunicator::NCCLCommunicator(int my_rank, int total_ranks, const void* unique_id) :
    mRank(my_rank), mWorld(total_ranks), mNcclComm(nullptr), mCmdBuf(std::make_unique<CommandBuffer>())
{
    CUDA_CHECK(cudaSetDevice(mRank));
    ncclCheck(ncclCommInitRank(&mNcclComm, mWorld, *reinterpret_cast<const ncclUniqueId*>(unique_id), mRank));
    mCommsStream = create_named_stream("nccl_stream");
    mCommsSync = create_named_event("nccl_sync");
}

#include <pthread.h>

NCCLCommunicator::~NCCLCommunicator() {
    auto shutdown_task = std::async(std::launch::async, [this]() {
        this->terminate_nccl();
    });

    if (shutdown_task.wait_for(std::chrono::seconds(2)) == std::future_status::timeout) {
        fprintf(stderr, "NCCL termination timed out, detaching\n");
        new auto(std::move(shutdown_task)); // leak to avoid hang
    }

    CUDA_CHECK(cudaEventDestroy(mCommsSync));
    CUDA_CHECK(cudaStreamDestroy(mCommsStream));
}

void NCCLCommunicator::terminate_nccl() {
    ncclResult_t async_err;
    ncclCheck(ncclCommGetAsyncError(mNcclComm, &async_err));

    if (!std::uncaught_exceptions() && async_err == ncclSuccess) {
        CUDA_CHECK(cudaStreamSynchronize(mCommsStream));
        CUDA_CHECK(cudaDeviceSynchronize());
        ncclCheck(ncclCommFinalize(mNcclComm));
        ncclCheck(ncclCommDestroy(mNcclComm));
    } else {
        ncclCheck(ncclCommAbort(mNcclComm));
    }
}

void NCCLCommunicator::begin_transaction(cudaEvent_t ready_event) {
    if (!mCmdBuf->operations.empty()) {
        throw std::runtime_error("start_comms: Buffer not empty");
    }
    mCmdBuf->completion_event = ready_event;
}

void NCCLCommunicator::begin_transaction(cudaStream_t wait_stream) {
    CUDA_CHECK(cudaEventRecord(mCommsSync, wait_stream));
    begin_transaction(mCommsSync);
}

void NCCLCommunicator::execute_transaction(cudaEvent_t signal_event) {
    _launch_queue_throttle_sync();
    on_execute_transaction(*mCmdBuf);

    for (auto& op : mCmdBuf->operations) {
        op(this);
    }

    on_finish_transaction(signal_event);
    _launch_queue_throttle_sync();
    mCmdBuf->operations.clear();
}

void NCCLCommunicator::reduce_scatter(Tensor& tensor, cudaStream_t stream, cudaEvent_t signal) {
    begin_transaction(stream);
    schedule_reduce_scatter(tensor);
    execute_transaction(signal);
}

void NCCLCommunicator::reduce_scatter(SimpleTensorContainer& container, cudaStream_t stream, cudaEvent_t signal) {
    begin_transaction(stream);
    visit([&](Tensor& t){ schedule_reduce_scatter(t); }, container);
    execute_transaction(signal);
}

void NCCLCommunicator::schedule_reduce_scatter(Tensor& tensor) {
    if (tensor.empty()) return;
    mCmdBuf->operations.emplace_back([this, dtype = tensor.DType, data = tensor.Data, nelem = tensor.nelem()](NCCLCommunicator* comm) {
        switch (dtype) {
            case ETensorDType::FP32:
                comm->scatter_grad(reinterpret_cast<float*>(data), nelem);
                break;
            case ETensorDType::BF16:
                comm->scatter_grad(reinterpret_cast<nv_bfloat16*>(data), nelem);
                break;
            default:
                throw std::runtime_error("scatter: Unsupported dtype");
        }
    });
}

void NCCLCommunicator::schedule_all_gather(const TensorShard& src, Tensor& tgt) {
    if (!src.Data || !tgt.Data || src.DType != tgt.DType) {
        throw std::runtime_error("gather: Invalid arguments");
    }
    mCmdBuf->operations.emplace_back([this, src_ptr = src.Data, dst_ptr = tgt.Data, bytes = tgt.bytes()](NCCLCommunicator* comm) {
        comm->gather_weight(src_ptr, dst_ptr, bytes);
    });
}

void NCCLCommunicator::reduce_mean(float* values, int count, cudaStream_t stream) {
    ncclCheck(ncclAllReduce(values, values, count, ncclFloat, ncclAvg, mNcclComm, stream ? stream : mCommsStream));
}

void NCCLCommunicator::reduce_max(float* values, int count, cudaStream_t stream) {
    ncclCheck(ncclAllReduce(values, values, count, ncclFloat, ncclMax, mNcclComm, stream ? stream : mCommsStream));
}

void NCCLCommunicator::reduce_norm(float* norm_squared, cudaStream_t stream) {
    ncclCheck(ncclAllReduce(norm_squared, norm_squared, 1, ncclFloat, ncclSum, mNcclComm, stream));
}

void NCCLCommunicator::scatter_grad(float* value, std::size_t total_elements) {
    assert(total_elements % mWorld == 0);
    std::size_t shard_size = total_elements / mWorld;
    ptrdiff_t offset = static_cast<ptrdiff_t>(shard_size) * mRank;
    ncclCheck(ncclReduceScatter(value, value + offset, shard_size, ncclFloat, ncclAvg, mNcclComm, mCommsStream));
}

void NCCLCommunicator::scatter_grad(nv_bfloat16* value, std::size_t total_elements) {
    assert(total_elements % mWorld == 0);
    std::size_t shard_size = total_elements / mWorld;
    ptrdiff_t offset = static_cast<ptrdiff_t>(shard_size) * mRank;
    ncclCheck(ncclReduceScatter(value, value + offset, shard_size, ncclBfloat16, ncclAvg, mNcclComm, mCommsStream));
}

void NCCLCommunicator::gather_weight(const std::byte* src, std::byte* dst, std::size_t total_bytes) {
    assert(total_bytes % mWorld == 0);
    std::size_t shard_size = total_bytes / mWorld;

    if (src == dst) {
        src += shard_size * mRank;
    }

    ncclCheck(ncclAllGather(src, dst, shard_size, ncclInt8, mNcclComm, mCommsStream));
}

void NCCLCommunicator::send(const std::byte* src, int peer, std::size_t size) {
    ncclCheck(ncclSend(src, size, ncclInt8, peer, mNcclComm, mCommsStream));
}

void NCCLCommunicator::recv(std::byte* dst, int peer, std::size_t size) {
    ncclCheck(ncclRecv(dst, size, ncclInt8, peer, mNcclComm, mCommsStream));
}

void NCCLCommunicator::wait_on_comms(cudaStream_t compute_stream) {
    CUDA_CHECK(cudaStreamWaitEvent(compute_stream, mCommsSync, 0));
}

#if USE_MPI
#undef HOST
#include <mpi.h>

void mpi_check(int status, const char* file, int line) {
    if (status != MPI_SUCCESS) {
        char msg[4096];
        int len = 0;
        if (MPI_Error_string(status, msg, &len) == MPI_SUCCESS) {
            throw std::runtime_error(fmt::format("Failed to format MPI error at {}:{} ({})", file, line, status));
        }
        throw std::runtime_error(fmt::format("MPI error at {}:{}: {}", file, line, msg));
    }
}
#define mpiCheck(call) (mpi_check((call), __FILE__, __LINE__))

class NCCLCommunicatorMPI : public NCCLCommunicator {
public:
    using NCCLCommunicator::NCCLCommunicator;
    ~NCCLCommunicatorMPI() override;
    void barrier() override;
    void _launch_queue_throttle_sync() override {};
    void gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t sz) override;
    void all_gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t sz) override;
    void on_execute_transaction(const CommandBuffer&) override;
    void on_finish_transaction(cudaEvent_t sig) override;
};

NCCLCommunicatorMPI::~NCCLCommunicatorMPI() {
    int initialized = 0;
    mpiCheck(MPI_Initialized(&initialized));
    if (initialized && !std::uncaught_exceptions()) {
        mpiCheck(MPI_Finalize());
    }
}

void NCCLCommunicatorMPI::barrier() {
    mpiCheck(MPI_Barrier(MPI_COMM_WORLD));
}

void NCCLCommunicatorMPI::gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t sz) {
    mpiCheck(MPI_Gather(obj, sz, MPI_BYTE, recv, sz, MPI_BYTE, 0, MPI_COMM_WORLD));
}

void NCCLCommunicatorMPI::all_gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t sz) {
    mpiCheck(MPI_Allgather(obj, sz, MPI_BYTE, recv, sz, MPI_BYTE, MPI_COMM_WORLD));
}

void NCCLCommunicatorMPI::on_execute_transaction(const CommandBuffer& buf) {
    CUDA_CHECK(cudaStreamWaitEvent(stream(), buf.completion_event));
    ncclCheck(ncclGroupStart());
}

void NCCLCommunicatorMPI::on_finish_transaction(cudaEvent_t signal) {
    ncclCheck(ncclGroupEnd());
    CUDA_CHECK(cudaEventRecord(signal, stream()));
}

std::unique_ptr<NCCLCommunicator> NCCLCommunicator::make_mpi_communicator() {
    mpiCheck(MPI_Init(nullptr, nullptr));
    int rank, world;
    mpiCheck(MPI_Comm_rank(MPI_COMM_WORLD, &rank));
    mpiCheck(MPI_Comm_size(MPI_COMM_WORLD, &world));
    ncclUniqueId id;
    if (rank == 0) {
        ncclCheck(ncclGetUniqueId(&id));
    }
    mpiCheck(MPI_Bcast(&id, sizeof(id), MPI_BYTE, 0, MPI_COMM_WORLD));
    return std::make_unique<NCCLCommunicatorMPI>(rank, world, &id);
}
