class NCCLCommunicatorThreads : public NCCLCommunicator {
public:
    struct SharedState {
        std::unique_ptr<std::barrier<>> sync_barrier;
        std::vector<std::byte*> shared_buffers;
        std::vector<std::exception_ptr> errors;
        std::mutex error_mutex;
    };

    NCCLCommunicatorThreads(int rank, int world, bool use_memcpy_allgather, bool use_memcpy_send_recv,
                            const void* nccl_id, std::shared_ptr<SharedState> shared_state);
    ~NCCLCommunicatorThreads() override;
    void barrier() override;
    void _launch_queue_throttle_sync() override;
    void gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t sz) override;
    void all_gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t sz) override;
    void gather_weight(const std::byte* src, std::byte* dst, std::size_t sz) override;
    void send(const std::byte* src, int peer, std::size_t sz) override;
    void recv(std::byte* dst, int peer, std::size_t sz) override;
    void on_execute_transaction(const CommandBuffer&) override;
    void on_finish_transaction(cudaEvent_t sig) override;

private:
    std::shared_ptr<SharedState> mShared;
    bool mUseMemcpyForAllGather = false;
    bool mUseMemcpyForSendRecv = true;

    struct PendingSend {
        const std::byte* data;
        std::size_t bytes;
        int dest;
        bool matched = false;
    };
    std::vector<PendingSend> pending_sends;

    struct PendingRecv {
        std::byte* buffer;
        std::size_t bytes;
        int source;
    };
    std::vector<PendingRecv> pending_recvs;
};

NCCLCommunicatorThreads::NCCLCommunicatorThreads(
    int rank, int world, bool memcpy_allgather, bool memcpy_send_recv,
    const void* nccl_id, std::shared_ptr<SharedState> state)
    : NCCLCommunicator(rank, world, nccl_id), mShared(std::move(state)),
      mUseMemcpyForAllGather(memcpy_allgather), mUseMemcpyForSendRecv(memcpy_send_recv) {}

NCCLCommunicatorThreads::~NCCLCommunicatorThreads() {
    if (mShared && mShared->sync_barrier) {
        mShared->sync_barrier->arrive_and_drop();
    }
}

class ThreadsPackImp : public CommunicatorThreadsPack {
public:
    ThreadsPackImp(std::vector<std::jthread> threads, std::shared_ptr<NCCLCommunicatorThreads::SharedState> state)
        : mThreads(std::move(threads)), mState(std::move(state)) {}
    ~ThreadsPackImp() override { join_impl(); }
    void join() override { join_impl(); }
    bool has_exception() const override {
        std::lock_guard<std::mutex> lock(mState->error_mutex);
        return std::any_of(mState->errors.begin(), mState->errors.end(),
                           [](const auto& e) { return e != nullptr; });
    }

private:
    void join_impl() {
        check_exceptions();
        for (auto& t : mThreads) {
            if (t.joinable()) t.join();
        }
        check_exceptions();
    }

    void check_exceptions() {
        std::lock_guard<std::mutex> lock(mState->error_mutex);
        for (size_t i = 0; i < mThreads.size(); ++i) {
            if (auto err = mState->errors[i]; err) {
                fprintf(stderr, "Thread %zu exited with uncaught exception\n", i);
                fflush(stderr);
                mState->errors[i] = nullptr;
                std::rethrow_exception(err);
            }
        }
    }

    std::vector<std::jthread> mThreads;
    std::shared_ptr<NCCLCommunicatorThreads::SharedState> mState;
};

void NCCLCommunicator::run_threads_communicators(int ngpus, bool memcpy_allgather, bool memcpy_send_recv,
                                                 std::function<void(NCCLCommunicator&)> work) {
    auto pack = launch_threads_communicators(ngpus, memcpy_allgather, memcpy_send_recv, std::move(work));
    pack->join();
}

std::unique_ptr<CommunicatorThreadsPack> NCCLCommunicator::launch_threads_communicators(
    int ngpus, bool memcpy_allgather, bool memcpy_send_recv, std::function<void(NCCLCommunicator&)> work) {
    std::vector<std::jthread> threads;
    ncclUniqueId id;
    ncclCheck(ncclGetUniqueId(&id));
    threads.reserve(ngpus);

    auto shared = std::make_shared<NCCLCommunicatorThreads::SharedState>(
        std::make_unique<std::barrier<>>(ngpus),
        std::vector<std::byte*>(ngpus)
    );
    shared->errors.resize(ngpus);

    for (int i = 0; i < ngpus; ++i) {
        threads.emplace_back([=, work = std::move(work)]() mutable {
            try {
                if (!set_cpu_affinity()) {
                    fprintf(stderr, "WARNING: Failed to set CPU affinity for rank %d\n", i);
                }
                NCCLCommunicatorThreads comm(i, ngpus, memcpy_allgather, memcpy_send_recv, &id, shared);
                work(comm);
                shared->sync_barrier->arrive_and_wait();
            } catch (...) {
                std::lock_guard<std::mutex> lock(shared->error_mutex);
                shared->errors[i] = std::current_exception();
            }
        });
    }

    return std::make_unique<ThreadsPackImp>(std::move(threads), std::move(shared));
}

void NCCLCommunicator::schedule_destructive_all_to_all(Tensor& tensor) {
    if (tensor.empty()) return;
    std::size_t shard_size = tensor.bytes() / world_size();

    for (int step = 1; step < world_size(); ++step) {
        int dst_rank = (step + rank()) % world_size();
        int src_rank = (rank() - step + world_size()) % world_size();
        int store_rank = (rank() + step - 1 + world_size()) % world_size();

        mCmdBuf->operations.emplace_back([this, src = tensor.Data + dst_rank * shard_size,
                                          dst = tensor.Data + store_rank * shard_size,
                                          size = shard_size](NCCLCommunicator* c) {
            c->send(src, dst_rank, size);
        });
        mCmdBuf->operations.emplace_back([this, dst = tensor.Data + store_rank * shard_size,
                                          src = src_rank, size = shard_size](NCCLCommunicator* c) {
            c->recv(dst, src, size);
        });
    }
}

void NCCLCommunicatorThreads::send(const std::byte* src, int peer, std::size_t size) {
    if (!mUseMemcpyForSendRecv) {
        NCCLCommunicator::send(src, peer, size);
    } else {
        pending_sends.push_back({src, size, peer});
    }
}

void NCCLCommunicatorThreads::recv(std::byte* dst, int peer, std::size_t size) {
    if (!mUseMemcpyForSendRecv) {
        NCCLCommunicator::recv(dst, peer, size);
    } else {
        pending_recvs.push_back({dst, size, peer});
    }
}

void NCCLCommunicatorThreads::gather_weight(const std::byte* src, std::byte* dst, std::size_t size) {
    if (mUseMemcpyForAllGather) {
        auto gathered = host_all_gather(src);
        std::size_t shard_size = size / world_size();
        for (int r = 0; r < world_size(); ++r) {
            if (dst + shard_size * r != gathered[r]) {
                CUDA_CHECK(cudaMemcpyAsync(dst + shard_size * r, gathered[r], shard_size,
                                           cudaMemcpyDeviceToDevice, stream()));
            }
        }
    } else {
        NCCLCommunicator::gather_weight(src, dst, size);
    }
}

void NCCLCommunicatorThreads::on_execute_transaction(const CommandBuffer& buf) {
    bool use_nccl = false;
    bool use_memcpy = false;

    for (const auto& op : buf.operations) {
        // Simulate type inspection via lambda capture behavior
        // Since we no longer use variant, we infer usage from operation types
        // For simplicity, assume scatter/reduce uses NCCL, others may vary
        use_nccl = true;
        break;
    }

    if (use_memcpy) {
        barrier();
        auto events = host_all_gather(buf.completion_event);
        for (auto ev : events) {
            CUDA_CHECK(cudaStreamWaitEvent(stream(), ev, 0));
        }
    }

    if (use_nccl) {
        CUDA_CHECK(cudaStreamWaitEvent(stream(), buf.completion_event, 0));
        ncclCheck(ncclGroupStart());
    }
}

void NCCLCommunicatorThreads::on_finish_transaction(cudaEvent_t signal) {
    if (!pending_recvs.empty()) {
        auto sends_list = host_all_gather(&pending_sends);
        auto signals_list = host_all_gather(signal);

        for (auto& recv : pending_recvs) {
            for (auto& send : sends_list.at(recv.source)) {
                if (send.dest != rank() || send.matched) continue;
                if (recv.bytes != send.bytes) {
                    throw std::runtime_error("Size mismatch in recv/send");
                }
                CUDA_CHECK(cudaMemcpyAsync(recv.buffer, send.data, recv.bytes,
                                           cudaMemcpyDeviceToDevice, stream()));
                send.matched = true;
                break;
            }
            CUDA_CHECK(cudaEventRecord(signal, stream()));
            barrier();
            for (int j = 0; j < world_size(); ++j) {
                if (j != rank()) {
                    CUDA_CHECK(cudaStreamWaitEvent(stream(), signals_list[j], 0));
                }
            }
        }

        barrier();
        pending_recvs.clear();
        pending_sends.clear();
    }

    ncclCheck(ncclGroupEnd());
    CUDA_CHECK(cudaEventRecord(signal, stream()));
}

void NCCLCommunicatorThreads::barrier() {
    mShared->sync_barrier->arrive_and_wait();
}

void NCCLCommunicatorThreads::_launch_queue_throttle_sync() {
    barrier();
}

void NCCLCommunicatorThreads::gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t size) {
    if (rank() == 0) {
        mShared->shared_buffers[0] = recv;
    }
    barrier();
    std::memcpy(mShared->shared_buffers[0] + rank() * size, obj, size);
    barrier();
    if (rank() == 0) {
        mShared->shared_buffers[0] = nullptr;
    }
}

void NCCLCommunicatorThreads::all_gather_bytes_host(std::byte* recv, const std::byte* obj, std::size_t size) {
    barrier();
    mShared->shared_buffers[rank()] = const_cast<std::byte*>(obj);
    barrier();
    for (int r = 0; r < world_size(); ++r) {
        std::memcpy(recv + r * size, mShared->shared_buffers[r], size);
    }
    barrier();
    mShared->shared_buffers[rank()] = nullptr;
}
