// Helper: generic write wrapper for fixed-size primitives (non-zero N)
template<typename T, std::size_t N>
struct FixedWriter {
  static size_t encode(unsigned char* dst, const T& val) {
    if constexpr (N == 1) { *dst = static_cast<unsigned char>(val); return 1; }
    else if constexpr (N == 2) { int2store(dst, val); return 2; }
    else if constexpr (N == 3) { int3store(dst, val); return 3; }
    else if constexpr (N == 4) { int4store(dst, val); return 4; }
    else if constexpr (N == 5) { int5store(dst, val); return 5; }
    else if constexpr (N == 6) { int6store(dst, val); return 6; }
    else if constexpr (N == 7) { int7store(dst, val); return 7; }
    else if constexpr (N == 8) { int8store(dst, val); return 8; }
    else { return 0; }
  }
};

// Specialization for float/double with fixed sizes
template<>
struct FixedWriter<float, 4> {
  static size_t encode(unsigned char* dst, const float& val) {
    float4store(dst, val);
    return 4;
  }
};

template<>
struct FixedWriter<double, 8> {
  static size_t encode(unsigned char* dst, const double& val) {
    float8store(dst, val);
    return 8;
  }
};

// Specialization for dynamic size (N == 0): delegate to variable-length writer
template<typename T>
struct DynamicWriter {
  static size_t encode(unsigned char* dst, const T& val) {
    return detail::write_varlen_bytes(dst, val);
  }
};

