// --- Read helpers ---

template<typename T, std::size_t N>
struct FixedReader {
  static size_t decode(const unsigned char* src, std::size_t avail, T& out) {
    if (avail < N) return 0;

    if constexpr (N == 1) { out = static_cast<T>(*src); return 1; }
    else if constexpr (N == 2) { out = uint2korr(src); return 2; }
    else if constexpr (N == 3) { out = uint3korr(src); return 3; }
    else if constexpr (N == 4) { out = uint4korr(src); return 4; }
    else if constexpr (N == 5) { out = uint5korr(src); return 5; }
    else if constexpr (N == 6) { out = uint6korr(src); return 6; }
    else if constexpr (N == 7) { out = uint7korr(src); return 7; }
    else if constexpr (N == 8) { out = uint8korr(src); return 8; }
    else { return 0; }
  }
};

template<>
struct FixedReader<float, 4> {
  static size_t decode(const unsigned char* src, std::size_t avail, float& out) {
    if (avail < 4) return 0;
    out = float4get(src);
    return 4;
  }
};

template<>
struct FixedReader<double, 8> {
  static size_t decode(const unsigned char* src, std::size_t avail, double& out) {
    if (avail < 8) return 0;
    out = float8get(src);
    return 8;
  }
};

