// FUdpMessageTransport implementation – refactored for clarity and robustness
struct FUdpMessageTransport::FInternalState
{
    FUdpMessageProcessor* Processor = nullptr;
    FUdpSocketReceiver* MulticastReceiver = nullptr;
    FUdpSocketReceiver* UnicastReceiver = nullptr;
    FGuid InstanceId;
    FIPv4Endpoint Unicast;
    FIPv4Endpoint Multicast;
    uint8 McastTtl = 0;

#if PLATFORM_DESKTOP
    class USocket* UnicastSocket = nullptr;
#endif
    class USocket* MulticastSocket = nullptr;

    TMap<FIPv4Endpoint, bool> StaticEndpointsMap;
    TArray<FIPv4Endpoint> StaticEndpointsList;

    ~FInternalState()
    {
        delete Processor;
        delete MulticastReceiver;
        delete UnicastReceiver;
    }
};

FUdpMessageTransport::FUdpMessageTransport(
    const FIPv4Endpoint& InUnicast,
    const FIPv4Endpoint& InMulticast,
    TArray<FIPv4Endpoint>&& InStatic,
    uint8 InMcastTtl)
    : MessageProcessor(nullptr)
    , MessageProcessorThread(nullptr)
    , SocketSubsystem(ISocketSubsystem::Get(PLATFORM_SOCKETSUBSYSTEM))
    , TransportHandler(nullptr)
{
    InternalState = MakeUnique<FInternalState>();
    InternalState->Unicast = InUnicast;
    InternalState->Multicast = InMulticast;
    InternalState->McastTtl = InMcastTtl;
    InternalState->InstanceId = FGuid::NewGuid();

    // Transfer static endpoints into both list and map for fast lookup
    for (const auto& Endpoint : InStatic)
    {
        bool bInserted = false;
        InternalState->StaticEndpointsMap.Add(Endpoint, &bInserted);
        if (!bInserted)
        {
            InternalState->StaticEndpointsList.Add(Endpoint);
        }
    }
}

FUdpMessageTransport::~FUdpMessageTransport()
{
    StopTransport();
}

void FUdpMessageTransport::OnAppPreExit()
{
    TransportErrorDelegate.Unbind();

    if (InternalState && InternalState->Processor)
    {
        InternalState->Processor->WaitAsyncTaskCompletion();
    }
}

void FUdpMessageTransport::AddStaticEndpoint(const FIPv4Endpoint& Endpoint)
{
    bool bExists = false;
    InternalState->StaticEndpointsMap.Add(Endpoint, &bExists);
    if (!bExists)
    {
        InternalState->StaticEndpointsList.Add(Endpoint);
        if (InternalState->Processor)
        {
            InternalState->Processor->AddStaticEndpoint(Endpoint);
        }
    }
}

void FUdpMessageTransport::RemoveStaticEndpoint(const FIPv4Endpoint& Endpoint)
{
    int32 CountRemoved = InternalState->StaticEndpointsMap.Remove(Endpoint);
    if (CountRemoved > 0)
    {
        InternalState->StaticEndpointsList.RemoveAll([&](const FIPv4Endpoint& E) { return E == Endpoint; });
        if (InternalState->Processor)
        {
            InternalState->Processor->RemoveStaticEndpoint(Endpoint);
        }
    }
}

bool FUdpMessageTransport::RestartTransport()
{
    IMessageTransportHandler* CurrentHandler = TransportHandler;
    StopTransport();
    return StartTransport(*CurrentHandler);
}

/* IMessageTransport interface */
FName FUdpMessageTransport::GetDebugName() const
{
    return "UdpMessageTransport";
}

bool FUdpMessageTransport::StartTransport(IMessageTransportHandler& Handler)
{
    TransportHandler = &Handler;

    // Initialize sockets
#if PLATFORM_DESKTOP
    InternalState->UnicastSocket = FUdpSocketBuilder(TEXT("UdpMessageUnicastSocket"))
        .AsNonBlocking()
        .BoundToEndpoint(InternalState->Unicast)
        .WithMulticastLoopback()
        .WithMulticastTtl(InternalState->McastTtl)
        .WithReceiveBufferSize(UDP_MESSAGING_RECEIVE_BUFFER_SIZE)
        .Build();

    if (!InternalState->UnicastSocket)
    {
        UE_LOG(LogUdpMessaging, Error, TEXT("Failed to create unicast socket at %s"), *InternalState->Unicast.ToString());
        return false;
    }
#endif

    InternalState->MulticastSocket = FUdpSocketBuilder(TEXT("UdpMessageMulticastSocket"))
        .AsNonBlocking()
        .AsReusable()
#if PLATFORM_WINDOWS
        .BoundToAddress(InternalState->Unicast.Address)
#endif
        .BoundToPort(InternalState->Multicast.Port)
#if PLATFORM_SUPPORTS_UDP_MULTICAST_GROUP
        .JoinedToGroup(InternalState->Multicast.Address, InternalState->Unicast.Address)
        .WithMulticastLoopback()
        .WithMulticastTtl(InternalState->McastTtl)
        .WithMulticastInterface(InternalState->Unicast.Address)
#endif
        .WithReceiveBufferSize(UDP_MESSAGING_RECEIVE_BUFFER_SIZE)
        .Build();

    if (!InternalState->MulticastSocket)
    {
        UE_LOG(LogUdpMessaging, Warning, TEXT("Failed to create multicast socket on port %d (joined to %s, TTL=%d)"),
            InternalState->Multicast.Port, *InternalState->Multicast.ToString(), InternalState->McastTtl);
#if !PLATFORM_DESKTOP
        return false;
#endif
    }

    // Create message processor
#if PLATFORM_DESKTOP
    InternalState->Processor = new FUdpMessageProcessor(*InternalState->UnicastSocket, InternalState->InstanceId, InternalState->Multicast);
#else
    InternalState->Processor = new FUdpMessageProcessor(*InternalState->MulticastSocket, InternalState->InstanceId, InternalState->Multicast);
#endif

    // Register static endpoints with processor
    for (const auto& Ep : InternalState->StaticEndpointsList)
    {
        InternalState->Processor->AddStaticEndpoint(Ep);
    }

    // Bind processor events
    InternalState->Processor->OnMessageReassembled().BindRaw(this, &FUdpMessageTransport::HandleProcessorMessageReassembled);
    InternalState->Processor->OnNodeDiscovered().BindRaw(this, &FUdpMessageTransport::HandleProcessorNodeDiscovered);
    InternalState->Processor->OnNodeLost().BindRaw(this, &FUdpMessageTransport::HandleProcessorNodeLost);
    InternalState->Processor->OnError().BindRaw(this, &FUdpMessageTransport::HandleProcessorError);

    // Setup receivers
    const FTimespan WaitTime = FTimespan::FromMilliseconds(100);

    if (InternalState->MulticastSocket)
    {
        InternalState->MulticastReceiver = new FUdpSocketReceiver(InternalState->MulticastSocket, WaitTime, TEXT("UdpMessageMulticastReceiver"));
        InternalState->MulticastReceiver->OnDataReceived().BindRaw(this, &FUdpMessageTransport::HandleSocketDataReceived);
        InternalState->MulticastReceiver->SetMaxReadBufferSize(2048);
        InternalState->MulticastReceiver->Start();
    }

#if PLATFORM_DESKTOP
    InternalState->UnicastReceiver = new FUdpSocketReceiver(InternalState->UnicastSocket, WaitTime, TEXT("UdpMessageUnicastReceiver"));
    InternalState->UnicastReceiver->OnDataReceived().BindRaw(this, &FUdpMessageTransport::HandleSocketDataReceived);
    InternalState->UnicastReceiver->SetMaxReadBufferSize(2048);
    InternalState->UnicastReceiver->Start();
#endif

    return true;
}

void FUdpMessageTransport::StopTransport()
{
    // Clean up receivers first
    delete InternalState->MulticastReceiver;
    InternalState->MulticastReceiver = nullptr;

#if PLATFORM_DESKTOP
    delete InternalState->UnicastReceiver;
    InternalState->UnicastReceiver = nullptr;
#endif

    delete InternalState->Processor;
    InternalState->Processor = nullptr;

    // Destroy sockets
    if (InternalState->MulticastSocket)
    {
        SocketSubsystem->DestroySocket(InternalState->MulticastSocket);
        InternalState->MulticastSocket = nullptr;
    }

#if PLATFORM_DESKTOP
    if (InternalState->UnicastSocket)
    {
        SocketSubsystem->DestroySocket(InternalState->UnicastSocket);
        InternalState->UnicastSocket = nullptr;
    }
#endif

    TransportHandler = nullptr;
    ErrorFuture.Reset();
}

bool FUdpMessageTransport::TransportMessage(const TSharedRef<IMessageContext, ESPMode::ThreadSafe>& Context, const TArray<FGuid>& Recipients)
{
    if (!InternalState || !InternalState->Processor)
    {
        return false;
    }

    if (Context->GetRecipients().Num() > UDP_MESSAGING_MAX_RECIPIENTS)
    {
        return false;
    }

    return InternalState->Processor->EnqueueOutboundMessage(Context, Recipients);
}

/* Event handlers */
void FUdpMessageTransport::HandleProcessorMessageReassembled(
    const FUdpReassembledMessage& Reassembled,
    const TSharedPtr<IMessageAttachment, ESPMode::ThreadSafe>& Attachment,
    const FGuid& NodeId)
{
    TSharedRef<FUdpDeserializedMessage, ESPMode::ThreadSafe> Deserialized =
        MakeShared<FUdpDeserializedMessage, ESPMode::ThreadSafe>(Attachment);

    if (Deserialized->Deserialize(Reassembled))
    {
        TransportHandler->ReceiveTransportMessage(Deserialized, NodeId);
    }
}

void FUdpMessageTransport::HandleProcessorNodeDiscovered(const FGuid& NodeId)
{
    TransportHandler->DiscoverTransportNode(NodeId);
}

void FUdpMessageTransport::HandleProcessorNodeLost(const FGuid& NodeId)
{
    TransportHandler->ForgetTransportNode(NodeId);
}

void FUdpMessageTransport::HandleProcessorError()
{
    if (!ErrorFuture.IsValid() && TransportErrorDelegate.IsBound())
    {
        ErrorFuture = Async(EAsyncExecution::TaskGraphMainThread, [Delegate = TransportErrorDelegate]()
        {
            Delegate.ExecuteIfBound();
        });
    }
}

void FUdpMessageTransport::HandleSocketDataReceived(
    const TSharedPtr<FArrayReader, ESPMode::ThreadSafe>& Data,
    const FIPv4Endpoint& Sender)
{
    if (InternalState && InternalState->Processor)
    {
        InternalState->Processor->EnqueueInboundSegment(Data, Sender);
    }
}

#include "config.h"
