#include <format>
#include <iostream>
#include <logger/logger.h>
#include <process/process.h>
#include <spdlog/spdlog.h>

auto main() -> int {
    logger::initialize();

    const auto app_title = std::format("{} {}", PROJECT_NAME, PROJECT_VERSION);
    spdlog::info("{} developed by jonah/nopjo", app_title);
    spdlog::info("Repository: https://github.com/nopjo/roblox-dumper\n");

    // Attempt to attach to Roblox process
    if (!process::g_process.attach("RobloxPlayerBeta.exe")) {
        MessageBoxA(
            nullptr,
            "Unable to attach to Roblox. Please restart the dumper after Roblox has fully started.",
            app_title.c_str(), MB_OK | MB_ICONERROR);
        return 1;
    }

    spdlog::info("Successfully attached to Roblox. Process ID: {}\n", process::g_process.get_pid());

    // Initialize control server
    if (!control::g_control.start(8080)) {
        MessageBoxA(nullptr,
                    "Control server failed to start. Ensure no other programs are using port 8080.",
                    app_title.c_str(), MB_OK | MB_ICONERROR);
        return 1;
    }

    spdlog::info("Control server operational on port 8080\n");

    // Measure dump duration
    const auto begin_timestamp = std::chrono::steady_clock::now();
    dumper::g_dumper.start();
    const auto finish_timestamp = std::chrono::steady_clock::now();

    const auto duration_ms = std::chrono::duration_cast<std::chrono::milliseconds>(
        finish_timestamp - begin_timestamp);

    spdlog::info("Dump completed in {} ms ({:.2f} seconds)", 
                 duration_ms.count(), 
                 static_cast<double>(duration_ms.count()) / 1000.0);

    // Write output files
    dumper::writer::g_header_writer.write("offsets", duration_ms);
    dumper::writer::g_json_writer.write("offsets", duration_ms);
    dumper::writer::g_python_writer.write("offsets", duration_ms);
    dumper::writer::g_csharp_writer.write("offsets", duration_ms);

    logger::print_error_summary();
    return 0;
}

#include "mwm_diff/diff.hpp"
#include "base/cancellable.hpp"
#include <cstring>
#include <iostream>

int main(int argc, char ** argv)
{
  auto const PrintUsage = [argv]()
  {
    std::cerr << "Usage: " << argv[0] 
              << " make|apply olderMWMPath newerMWMPath diffPath\n"
                 "Commands:\n"
                 "  make   - Generate a diff file between older and newer MWMs\n"
                 "  apply  - Apply the diff to update an older MWM to newer version\n"
                 "WARNING: No validation of MWM integrity is performed!\n";
  };

  if (argc != 5)
  {
    PrintUsage();
    return -1;
  }

  char const * const command = argv[1];
  char const * const oldFilePath = argv[2];
  char const * const newFilePath = argv[3];
  char const * const diffFilePath = argv[4];

  if (std::strcmp(command, "make") == 0)
  {
    if (generator::mwm_diff::MakeDiff(oldFilePath, newFilePath, diffFilePath))
      return 0;
  }
  else if (std::strcmp(command, "apply") == 0)
  {
    base::Cancellable cancelToken;
    auto const result = generator::mwm_diff::ApplyDiff(oldFilePath, newFilePath, diffFilePath, cancelToken);
    if (result == generator::mwm_diff::DiffApplicationResult::Ok)
      return 0;
  }

  PrintUsage();
  return -1;  // Error occurred or operation was cancelled
}

