// Helper lambda to create and initialize a new HTTP/2 stream
auto make_initialized_stream = [](uint32_t id) -> Http2Stream {
  Http2Stream s{id, kDefaultInitialWindowSize};
  [[maybe_unused]] auto _ = s.onRecvHeaders(false);
  return s;
};

// ---------------------------------------------------------------------------
// Stream window consume/increase cycle
// ---------------------------------------------------------------------------
void BM_StreamWindowConsume(benchmark::State& state) {
  Http2Stream stream{make_initialized_stream(1)};
  for ([[maybe_unused]] auto _ : state) {
    bool consumed = stream.consumeRecvWindow(1024);
    benchmark::DoNotOptimize(consumed);
    (void)stream.increaseRecvWindow(1024); // ignore error code as before
  }
}
BENCHMARK(BM_StreamWindowConsume);

void BM_StreamWindowIncreaseSend(benchmark::State& state) {
  Http2Stream stream{make_initialized_stream(1)};
  for ([[maybe_unused]] auto _ : state) {
    bool sent_ok = stream.consumeSendWindow(4096);
    benchmark::DoNotOptimize(sent_ok);
    auto ec = stream.increaseSendWindow(4096);
    benchmark::DoNotOptimize(ec);
  }
}
BENCHMARK(BM_StreamWindowIncreaseSend);

// ---------------------------------------------------------------------------
// Stream state transitions
// ---------------------------------------------------------------------------
void BM_StreamStateTransitions(benchmark::State& state) {
  for ([[maybe_unused]] auto _ : state) {
    Http2Stream s{1, kDefaultInitialWindowSize};
    auto e1 = s.onRecvHeaders(false);
    benchmark::DoNotOptimize(e1);
    auto e2 = s.onSendHeaders(false);
    benchmark::DoNotOptimize(e2);
    auto e3 = s.onRecvData(true);
    benchmark::DoNotOptimize(e3);
    auto e4 = s.onSendData(true);
    benchmark::DoNotOptimize(e4);
  }
}
BENCHMARK(BM_StreamStateTransitions);

// ---------------------------------------------------------------------------
// Stream map insert/erase (flat_hash_map throughput)
// ---------------------------------------------------------------------------
void BM_StreamMapInsertErase(benchmark::State& state) {
  const std::size_t count = static_cast<std::size_t>(state.range(0));
  for ([[maybe_unused]] auto _ : state) {
    flat_hash_map<uint32_t, Http2Stream> streams;
    std::size_t idx = 1;
    while (idx <= count * 2) {
      streams.emplace(idx, Http2Stream(idx, kDefaultInitialWindowSize));
      idx += 2;
    }
    idx = 1;
    while (idx <= count * 2) {
      streams.erase(idx);
      idx += 2;
    }
    benchmark::DoNotOptimize(streams.size());
  }
  state.SetItemsProcessed(static_cast<int64_t>(state.iterations()) * count * 2);
}
BENCHMARK(BM_StreamMapInsertErase)->Arg(10)->Arg(100)->Arg(500);

// ---------------------------------------------------------------------------
// WriteWindowUpdateFrame throughput (the auto-update hot path)
// ---------------------------------------------------------------------------
void BM_WindowUpdateFrameWrite(benchmark::State& state) {
  RawBytes buffer;
  for ([[maybe_unused]] auto _ : state) {
    buffer.clear();
    WriteWindowUpdateFrame(buffer, 0, 16384);
    WriteWindowUpdateFrame(buffer, 1, 16384);
    benchmark::DoNotOptimize(buffer.data());
  }
  state.SetItemsProcessed(static_cast<int64_t>(state.iterations()) * 2);
}
BENCHMARK(BM_WindowUpdateFrameWrite);

// ---------------------------------------------------------------------------
// Full connection SETTINGS exchange (processInput hot path)
// ---------------------------------------------------------------------------
void BM_ConnectionSettingsExchange(benchmark::State& state) {
  RawBytes client_input;
  client_input.append(reinterpret_cast<const std::byte*>(kConnectionPreface.data()), kConnectionPreface.size());
  WriteSettingsFrame(client_input, {});
  auto input_span = std::span{client_input.begin(), client_input.end()};
  for ([[maybe_unused]] auto _ : state) {
    Http2Connection conn(Http2Config{}, true);
    auto res = conn.processInput(input_span);
    benchmark::DoNotOptimize(res);
  }
}
BENCHMARK(BM_ConnectionSettingsExchange);

// ---------------------------------------------------------------------------
// Connection: process N DATA frames (simulated fast path)
// ---------------------------------------------------------------------------
void BM_ConnectionProcessDataFrames(benchmark::State& state) {
  const int num_frames = static_cast<int>(state.range(0));
  constexpr std::size_t payload_len = 128;

  RawBytes full_request;
  full_request.append(reinterpret_cast<const std::byte*>(kConnectionPreface.data()), kConnectionPreface.size());
  WriteSettingsFrame(full_request, {});
  WriteSettingsAckFrame(full_request);

  HpackEncoder encoder;
  RawBytes hpack_block;
  encoder.encode(hpack_block, ":method", "POST");
  encoder.encode(hpack_block, ":path", "/benchmark");
  encoder.encode(hpack_block, ":scheme", "http");
  encoder.encode(hpack_block, ":authority", "localhost");

  WriteHeadersFrameWithPriority(full_request, /*streamId=*/1,
                                std::span{hpack_block.begin(), hpack_block.end()},
                                /*streamDependency=*/0, /*weight=*/16, /*exclusive=*/false,
                                /*endStream=*/false, /*endHeaders=*/true);

  std::string data_payload(payload_len, 'D');
  auto payload_span = std::span{reinterpret_cast<const std::byte*>(data_payload.data()), data_payload.size()};

  for (int i = 0; i < num_frames; ++i) {
    bool is_last = (i == num_frames - 1);
    WriteDataFrame(full_request, /*streamId=*/1, payload_span, is_last);
  }

  auto full_input = std::span{full_request.begin(), full_request.end()};
  for ([[maybe_unused]] auto _ : state) {
    Http2Connection conn(Http2Config{}, true);
    conn.setOnHeadersDecoded([](uint32_t, const HeadersViewMap&, bool) {});
    conn.setOnData([](uint32_t, std::span<const std::byte>, bool) {});
    auto result = conn.processInput(full_input);
    benchmark::DoNotOptimize(result);
  }
  state.SetItemsProcessed(static_cast<int64_t>(state.iterations()) * num_frames);
}
