class Solution {
public:
    bool isPalindrome(int x) {
        // Negative numbers are not palindromes
        if (x < 0) return false;
        // Zero is a palindrome
        if (x == 0) return true;

        // Store original number for comparison later
        int original = x;
        long long reversed = 0;

        // Reverse the digits of x
        while (x > 0) {
            int digit = x % 10;     // Extract rightmost digit
            x /= 10;                // Remove rightmost digit from x
            reversed = reversed * 10 + digit;  // Append digit to reversed number
        }

        // Check if original number equals its reverse
        return (long long)original == reversed;
    }
};

#include "Face3D.hpp"

using std::inner_product;
using namespace MadVoro;

MadVoro::Face3D::Face3D(point_vec_v const& vert, std::size_t neighbor1, std::size_t neighbor2)
  : vertices(vert), neighbors(neighbor1, neighbor2) {}

Face3D& MadVoro::Face3D::operator=(const Face3D& other)
{
    vertices = other.vertices;
    neighbors = other.neighbors;
    return *this;
}

MadVoro::Face3D::Face3D()
  : vertices(), neighbors() {}

MadVoro::Face3D::~Face3D() {}

MadVoro::Face3D::Face3D(const Face3D& other)
  : vertices(other.vertices),
    neighbors(other.neighbors) {}

double MadVoro::Face3D::GetArea() const
{
    const Point3D& reference = vertices[0];
    auto accumulator = [](const double x, const double y) { return x + y; };
    auto triangle_area = [&reference](const Point3D& u, const Point3D& v) {
        return 0.5 * fastabs(CrossProduct(u - reference, v - reference));
    };
    return inner_product(vertices.begin() + 1,
                         vertices.end() - 1,
                         vertices.begin() + 2,
                         0.0,
                         accumulator,
                         triangle_area);
}

Point3D calc_centroid(const Face3D& face)
{
    const Point3D& reference = face.vertices[0];
    auto sum_points = [](const Point3D& x, const Point3D& y) { return x + y; };
    auto weighted_contrib = [&reference](const Point3D& u, const Point3D& v) {
        double area = 0.5 * fastabs(CrossProduct(u - reference, v - reference));
        return area * (u + v + reference) / 3.0;
    };
    return inner_product(face.vertices.begin() + 1,
                         face.vertices.end() - 1,
                         face.vertices.begin() + 2,
                         Point3D(0.0, 0.0, 0.0),
                         sum_points,
                         weighted_contrib);
}

