suites& suites::instance() noexcept
{
    class suites_impl : public suites
    {
        std::vector<any_suite const*> v_;
    public:
        virtual ~suites_impl() = default;
        void insert(any_suite const& t) override
        {
            v_.push_back(&t);
        }
        iterator begin() const noexcept override
        {
            return v_.empty() ? nullptr : &v_[0];
        }
        iterator end() const noexcept override
        {
            return v_.empty() ? nullptr : &v_[0] + v_.size();
        }
        void sort() override
        {
            std::sort(
                v_.begin(),
                v_.end(),
                []( any_suite const* p0, any_suite const* p1 )
                {
                    auto s0 = p0->name();
                    auto n0 = std::strlen(s0);
                    auto s1 = p1->name();
                    auto n1 = std::strlen(s1);
                    return std::lexicographical_compare(
                        s0, s0 + n0, s1, s1 + n1 );
                });
        }
    };
    static suites_impl impl;
    return impl;
}

