// Thread managing PDB access across processes
class pdb_thread_t {
public:
  pdb_remote_session_t *pdb_rsess;
  void *thread_handle;
  void *accepting_request;
  void *request_available;
  void *opener_mutex;

  pdb_thread_t();
  ~pdb_thread_t();

  bool is_running() const;
  void kill();
};

// Helper class for handling remote read requests from the PDB thread
class pdb_remote_session_t::client_read_request_t {
public:
  enum pdb_rr_kind_t kind;
  uint64 off_ea;
  void *buffer;
  uint32 size;
  bool result;
  void *read_req;
  void *read_resp;

  client_read_request_t();
  ~client_read_request_t();

  bool request_read(pdb_rr_kind_t _kind, uint64 _off_ea, uint32 _count,
                    void *_buffer, uint32 *_nread);
};

// Global instance
pdb_thread_t pdb_thread;

//----------------------------------------------------------------------------
pdb_thread_t::pdb_thread_t()
  : pdb_rsess(nullptr), thread_handle(nullptr)
{
  accepting_request = qsem_create(nullptr, 0);
  request_available = qsem_create(nullptr, 0);
  opener_mutex = qmutex_create();
}

//----------------------------------------------------------------------------
pdb_thread_t::~pdb_thread_t()
{
  kill();
  qsem_free(accepting_request);
  qsem_free(request_available);
  qmutex_free(opener_mutex);
}

//----------------------------------------------------------------------------
pdb_remote_session_t::client_read_request_t::client_read_request_t()
  : kind(NONE),
    off_ea(BADADDR),
    buffer(nullptr),
    size(0),
    result(false)
{
  read_req = qsem_create(nullptr, 0);
  read_resp = qsem_create(nullptr, 0);
}

//--------------------------------------------------------------------------
pdb_remote_session_t::client_read_request_t::~client_read_request_t()
{
  qsem_free(read_req);
  qsem_free(read_resp);
  read_req = nullptr;
  read_resp = nullptr;
  buffer = nullptr;
}

//----------------------------------------------------------- pdb thread ---
bool pdb_remote_session_t::client_read_request_t::request_read(
        pdb_rr_kind_t _kind,
        uint64  _off_ea,
        uint32  _count,
        void   *_buffer,
        uint32 *_nread)
{
  off_ea = _off_ea;
  size   = _count;
  buffer = _buffer;
  kind   = _kind;
  qsem_post(read_req);
  qsem_wait(read_resp, INFINITE);
  if ( _nread != nullptr )
    *_nread = size;
  return result;
}

//----------------------------------------------------------- pdb thread ---
int pdb_remote_session_t::pack_symbol(IDiaSymbol *symbol)
{
  sym_storage.qclear();
  DWORD id = 0;
  if ( symbol->get_symIndexId((DWORD *) &id) != S_OK )
    return E_FAIL;
  storage.pack_dd(id);

  DWORD tag;
  symbol->get_symTag(&tag);
#define EXTRACT_PROPERTY(type, name, suffix, cast_type) \
  do {                                                  \
    type val;                                           \
    if ( symbol->ge##name(&val) == S_OK ) {            \
      sym_storage.pack_##suffix((cast_type) val);       \
      present |= name;                                  \
    }                                                   \
  } while ( false )

  token_mask_t present = 0;

#define EXTRACT_BOOL(name) EXTRACT_PROPERTY(BOOL, name, db, uchar)
  EXTRACT_BOOL(t_constType);
  EXTRACT_BOOL(t_isStatic);
  EXTRACT_BOOL(t_virtual);
  EXTRACT_BOOL(t_volatileType);
  EXTRACT_BOOL(t_code);
  EXTRACT_BOOL(t_hasAssignmentOperator);
  EXTRACT_BOOL(t_hasCastOperator);
  EXTRACT_BOOL(t_function);
  EXTRACT_BOOL(t_constructor);
#undef EXTRACT_BOOL

#define EXTRACT_DWORD(name) EXTRACT_PROPERTY(DWORD, name, dd, uint32)
  EXTRACT_DWORD(t_backEndMajor);
  EXTRACT_DWORD(t_baseType);
  EXTRACT_DWORD(t_bitPosition);
  EXTRACT_DWORD(t_callingConvention);
  EXTRACT_DWORD(t_count);
  EXTRACT_DWORD(t_dataKind);
  EXTRACT_DWORD(t_locationType);
  EXTRACT_DWORD(t_registerId);
  EXTRACT_DWORD(t_relativeVirtualAddress);
  EXTRACT_DWORD(t_symIndexId);
  EXTRACT_DWORD(t_symTag);
  EXTRACT_DWORD(t_udtKind);
  EXTRACT_DWORD(t_virtualBaseOffset);
#undef EXTRACT_DWORD

#define FETCH_ID_FROM_SYM(method, token_flag)             \
  do {                                                    \
    DWORD child_id;                                       \
    IDiaSymbol *child_sym;                                \
    if ( symbol->method(&child_sym) == S_OK ) {          \
      if ( child_sym->get_symIndexId(&child_id) == S_OK ) { \
        sym_storage.pack_dd(child_id);                   \
        present |= token_flag;                           \
      }                                                  \
      child_sym->Release();                              \
    }                                                     \
  } while ( false )

  // IMPORTANT: Do NOT change this pattern — using get_*Id() directly on
  // symbols can cause ID mismatches later due to dynamic ID generation.
  FETCH_ID_FROM_SYM(get_classParent, t_classParentId);
  FETCH_ID_FROM_SYM(get_type, t_typeId);
  FETCH_ID_FROM_SYM(get_lexicalParent, t_lexicalParentId);
#undef FETCH_ID_FROM_SYM

#define EXTRACT_QWORD(name) EXTRACT_PROPERTY(DWORD64, name, dq, uint64)
  EXTRACT_QWORD(t_length);
#undef EXTRACT_QWORD

#define EXTRACT_WSTR(method, token_flag)                  \
  do {                                                    \
    BSTR tmp_wstr;                                        \
    qstring tmp_utf8;                                     \
    if ( symbol->method(&tmp_wstr) == S_OK ) {           \
      utf16_utf8(&tmp_utf8, tmp_wstr);                   \
      SysFreeString(tmp_wstr);                            \
      sym_storage.pack_str(tmp_utf8.c_str());            \
      present |= token_flag;                             \
    }                                                     \
  } while ( false )

  EXTRACT_WSTR(get_name, t_name);
#undef EXTRACT_WSTR

#define EXTRACT_LONG(name) EXTRACT_PROPERTY(LONG, name, dd, LONG)
  EXTRACT_LONG(t_offset);
#undef EXTRACT_LONG

#define EXTRACT_ULL(name) EXTRACT_PROPERTY(ULONGLONG, name, dq, LONG)
  EXTRACT_ULL(t_virtualAddress);
#undef EXTRACT_ULL

  VARIANT var;
  VariantInit(&var);
  if ( symbol->get_value(&var) == S_OK )
  {
    bytevec_t variant_blob;
    if ( varser_t::serialize(variant_blob, var) )
    {
      sym_storage.append(variant_blob.begin(), variant_blob.end());
      present |= t_value;
    }
#ifdef _DEBUG
    else
    {
      msg("Failed to serialize variant\n");
    }
#endif
  }

#undef EXTRACT_PROPERTY

  size_t blob_size = sym_storage.size();
  storage.pack_dq(present);
  storage.pack_dd(blob_size);
  storage.append(sym_storage.begin(), blob_size);
  return 0;
}

//-------------------------------------------------------------------------
int pdb_remote_session_t::last_id = 0;
//-------------------------------------------------------------------------
pdb_remote_session_t::pdb_remote_session_t()
  : fetch_type(FT_NONE),
    fetch_id(0),
    fetch_va(BADADDR),
    fetch_length(0),
    fetch_file_id(0),
    fetch_lnnum(0),
    fetch_colnum(0),
    fetch_symbol_type(SymTagNull),
    fetch_ok(false),
    is_opening(false)
{
  memset(&compiler_info, 0, sizeof(compiler_info));
  session_id = ++last_id;
  fetch_complete = qsem_create(nullptr, 0);
  msg("PDB: started session (%d)\n", session_id);
}

//-------------------------------------------------------------------------
pdb_remote_session_t::~pdb_remote_session_t()
{
  qsem_free(fetch_complete);
  fetch_complete = nullptr;
  msg("PDB: terminated session (%d)\n", session_id);
}

//----------------------------------------------------------------------------
bool pdb_remote_session_t::request_pdb_thread(bool wait_for_completion)
{
  qsem_wait(pdb_thread.accepting_request, INFINITE);
  pdb_thread.pdb_rsess = this;
  qsem_post(pdb_thread.request_available);
  if ( wait_for_completion )
    qsem_wait(fetch_complete, INFINITE);
  return fetch_ok;
}

//----------------------------------------------------------------------------
bool pdb_remote_session_t::open(const compiler_info_t &_cc, const pdbargs_t &_args)
{
  compiler_info = _cc;
  args = _args;
  fetch_type = FT_OPEN;
  return request_pdb_thread(/*wait=*/false);
}

//----------------------------------------------------------------------------
bool pdb_remote_session_t::fetch_symbol(uint32 id)
{
  fetch_type = FT_SYMBOL;
  fetch_id = id;
  fetch_symbol_type = SymTagNull;
  return request_pdb_thread();
}

//----------------------------------------------------------------------------
bool pdb_remote_session_t::fetch_children(uint32 id, enum SymTagEnum children_type)
{
  fetch_type = FT_CHILDREN;
  fetch_id = id;
  fetch_symbol_type = children_type;
  return request_pdb_thread();
}

//-------------------------------------------------------------------------
bool pdb_remote_session_t::fetch_lines_by_va(ea_t va, uint64 length)
{
  fetch_type = FT_LINES_BY_VA;
  fetch_va = va;
  fetch_length = length;
  return request_pdb_thread();
}

//-------------------------------------------------------------------------
bool pdb_remote_session_t::fetch_lines_by_coords(uint32 file_id, uint32 lnnum, uint32 colnum)
{
  fetch_type = FT_LINES_BY_COORDS;
  fetch_file_id = file_id;
  fetch_lnnum = lnnum;
  fetch_colnum = colnum;
  return request_pdb_thread();
}

