StopMotionSerial::StopMotionSerial() 
    : m_serialPort(new QSerialPort(this)) {}

StopMotionSerial::~StopMotionSerial() {
    if (m_serialPort && m_serialPort->isOpen()) {
        m_serialPort->close();
    }
    delete m_serialPort;
}

//-----------------------------------------------------------------
QStringList StopMotionSerial::listAvailablePorts() {
    QList<QSerialPortInfo> portList = QSerialPortInfo::availablePorts();
    QStringList portNames;
    portNames << tr("No Device");

    for (const QSerialPortInfo& info : portList) {
        portNames << info.portName();

        // Optional: log identifiers if needed later
        if (info.hasProductIdentifier()) {
            [[maybe_unused]] quint16 pid = info.productIdentifier();
        }
        if (info.hasVendorIdentifier()) {
            [[maybe_unused]] quint16 vid = info.vendorIdentifier();
        }
    }

    return portNames;
}

//-----------------------------------------------------------------
bool StopMotionSerial::connectToPort(const QString& portName) {
    if (m_serialPort->isOpen()) {
        m_serialPort->close();
    }

    bool matched = false;
    const QList<QSerialPortInfo> available = QSerialPortInfo::availablePorts();

    for (const QSerialPortInfo& info : available) {
        if (portName == info.portName()) {
            m_serialPort->setPort(info);
            matched = true;
            break;
        }
    }

    if (!matched) {
        return false;
    }

    bool opened = m_serialPort->open(QIODevice::ReadWrite);
    if (!opened) {
        return false;
    }

    // Configure serial settings
    bool configOk = m_serialPort->setBaudRate(QSerialPort::Baud9600) &&
                    m_serialPort->setParity(QSerialPort::NoParity) &&
                    m_serialPort->setDataBits(QSerialPort::Data8) &&
                    m_serialPort->setStopBits(QSerialPort::OneStop) &&
                    m_serialPort->setFlowControl(QSerialPort::NoFlowControl);

    if (!configOk) {
        m_serialPort->close();
        return false;
    }

    // Send current frame number
    int frameNum = StopMotion::instance()->getXSheetFrameNumber();
    QString frameStr = QString::number(frameNum);
    m_serialPort->write(frameStr.toUtf8());
    m_serialPort->waitForBytesWritten(50);

    // Read response
    QByteArray receivedData;
    while (m_serialPort->waitForReadyRead(25)) {
        receivedData += m_serialPort->readAll();
    }

    // Optional: process or store response if needed in future
    [[maybe_unused]] QString responseStr = QString::fromUtf8(receivedData);
    [[maybe_unused]] std::string responseText = receivedData.toStdString();

    return configOk;
}

//-----------------------------------------------------------------
void StopMotionSerial::transmitFrameUpdate() {
    if (!m_serialPort || !m_serialPort->isOpen()) {
        return;
    }

    int currentFrame = StopMotion::instance()->getXSheetFrameNumber();
    QString frameStr = QString::number(currentFrame);
    m_serialPort->write(frameStr.toUtf8());
    m_serialPort->waitForBytesWritten(50);

    QByteArray buffer;
    while (m_serialPort->waitForReadyRead(25)) {
        buffer += m_serialPort->readAll();
    }

    [[maybe_unused]] QString reply = QString::fromUtf8(buffer);
    [[maybe_unused]] std::string replyStr = buffer.toStdString();
}

