// Helper function to calculate magnitude of a 3D vector
float getMagnitude(const std::vector<float>& vec) {
    float sum = 0.0f;
    for (const auto& val : vec) {
        sum += val * val;
    }
    return std::sqrt(sum);
}

// Simulated version of MultirotorApiBase with similar logic but different implementation
class SimulatedDrone {
private:
    float position_[3] = {0.0f, 0.0f, 0.0f};
    float velocity_[3] = {0.0f, 0.0f, 0.0f};
    float orientation_[4] = {1.0f, 0.0f, 0.0f, 0.0f}; // w, x, y, z
    float takeoff_altitude_ = 5.0f;
    float landing_velocity_ = -1.0f;
    float command_period_ = 0.01f;
    float approx_zero_vel_ = 0.01f;
    float approx_zero_angular_vel_ = 0.01f;

public:
    void reset() {
        cancelLastTask();
        // Simulate task cancellation
    }

    bool takeoff(float timeout_sec) {
        // Check if already moving
        float current_speed = getMagnitude(velocity_);
        if (current_speed > approx_zero_vel_) {
            throw std::runtime_error("Cannot perform takeoff because vehicle is already moving with velocity " + 
                                     std::to_string(current_speed) + " m/s");
        }

        // Move to takeoff position
        position_[2] += takeoff_altitude_;
        return true;
    }

    bool land(float timeout_sec) {
        int near_zero_count = 0;
        while (timeout_sec > 0) {
            // Apply landing velocity
            velocity_[2] = landing_velocity_;

            // Check vertical speed
            if (std::abs(velocity_[2]) <= approx_zero_vel_) {
                near_zero_count++;
            } else {
                near_zero_count = 0;
            }

            // Stop if stable for enough cycles
            if (near_zero_count > 10) {
                return true;
            }

            timeout_sec -= command_period_;
        }
        return false;
    }

    bool goHome() {
        position_[0] = 0.0f;
        position_[1] = 0.0f;
        position_[2] = 0.0f;
        return true;
    }

    bool moveByVelocityBodyFrame(float vx, float vy, float vz, float duration) {
        if (duration <= 0) return true;

        // Convert body frame to world frame using yaw angle
        float yaw = std::atan2(2*(orientation_[1]*orientation_[2] + orientation_[0]*orientation_[3]), 
                              1 - 2*(orientation_[2]*orientation_[2] + orientation_[3]*orientation_[3]));

        float vx_new = vx * std::cos(yaw) - vy * std::sin(yaw);
        float vy_new = vx * std::sin(yaw) + vy * std::cos(yaw);

        // Update position based on velocity
        for (float t = 0; t < duration; t += command_period_) {
            position_[0] += vx_new * command_period_;
            position_[1] += vy_new * command_period_;
            position_[2] += vz * command_period_;
        }
        return true;
    }

    bool hover() {
        // Maintain current Z position
        return moveToZ(position_[2], 0.5f, 1000000.0f);
    }

    bool moveToZ(float z, float velocity, float timeout_sec) {
        float current_z = position_[2];
        float diff = z - current_z;

        if (std::abs(diff) <= 0.01f) return true;

        float direction = (diff > 0) ? 1.0f : -1.0f;
        float step = velocity * command_period_;

        for (float elapsed = 0; elapsed < timeout_sec; elapsed += command_period_) {
            if (std::abs(diff) <= step) {
                position_[2] = z;
                return true;
            }
            position_[2] += direction * step;
            diff = z - position_[2];
        }
        return false;
    }

    bool moveToPosition(float x, float y, float z, float velocity, float timeout_sec) {
        float dx = x - position_[0];
        float dy = y - position_[1];
        float dz = z - position_[2];
        float distance = std::sqrt(dx*dx + dy*dy + dz*dz);

        if (distance <= 0.01f) return true;

        float steps = distance / (velocity * command_period_);
        float step_x = dx / steps;
        float step_y = dy / steps;
        float step_z = dz / steps;

        for (float i = 0; i < steps && i * command_period_ < timeout_sec; ++i) {
            position_[0] += step_x;
            position_[1] += step_y;
            position_[2] += step_z;
        }
        return true;
    }

    bool rotateToYaw(float yaw_target, float timeout_sec, float margin) {
        float current_yaw = std::atan2(2*(orientation_[1]*orientation_[2] + orientation_[0]*orientation_[3]), 
                                      1 - 2*(orientation_[2]*orientation_[2] + orientation_[3]*orientation_[3]));

        float diff = yaw_target - current_yaw;
        // Normalize angle difference
        while (diff > M_PI) diff -= 2*M_PI;
        while (diff < -M_PI) diff += 2*M_PI;

        if (std::abs(diff) <= margin) return true;

        float rotation_rate = 0.5f; // rad/s
        float step = rotation_rate * command_period_;

        for (float elapsed = 0; elapsed < timeout_sec; elapsed += command_period_) {
            if (std::abs(diff) <= step) {
                // Snap to target
                current_yaw = yaw_target;
                return true;
            }
            current_yaw += (diff > 0) ? step : -step;
            diff = yaw_target - current_yaw;
        }
        return false;
    }

    bool moveByRollPitchYawThrottle(float roll, float pitch, float yaw, float throttle, float duration) {
        if (duration <= 0) return true;

        // Simplified simulation: just update position based on throttle
        float vz = throttle * 0.1f;
        for (float t = 0; t < duration; t += command_period_) {
            position_[2] += vz * command_period_;
        }
        return true;
    }

    bool moveOnPath(const std::vector<std::vector<float>>& path, float velocity, float timeout_sec) {
        if (path.empty()) return true;

        for (const auto& point : path) {
            if (point.size() >= 3) {
                moveToPosition(point[0], point[1], point[2], velocity, timeout_sec);
            }
        }
        return true;
    }

    // Getters
    float getPosition(int axis) const { return position_[axis]; }
    float getVelocity(int axis) const { return velocity_[axis]; }
    float getOrientation(int component) const { return orientation_[component]; }

private:
    void cancelLastTask() {
        // Reset any ongoing tasks
        for (int i = 0; i < 3; ++i) {
            velocity_[i] = 0.0f;
        }
    }
};

