// Example usage demonstrating the same functionality as original code
int main() {
    msr::airlib::SimulatedDrone drone;

    // Takeoff sequence
    try {
        drone.takeoff(5.0f);
        std::cout << "Takeoff successful" << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Takeoff failed: " << e.what() << std::endl;
    }

    // Hover at current altitude
    drone.hover();

    // Go home
    drone.goHome();

    // Land
    drone.land(5.0f);

    std::cout << "Simulation completed successfully" << std::endl;
    return 0;
}

#include "../backend/src/QuantumRegister.hpp"
#include <benchmark/benchmark.h>
#include <iostream>
#include <vector>

// Benchmark for applying Hadamard gate on first qubit
static void BM_Antigravity_ApplyHadamard(benchmark::State &state) {
  size_t qubit_count = state.range(0);

  try {
    // Initialize quantum register with specified number of qubits
    QuantumRegister qr(qubit_count);

    for (auto _ : state) {
      // Apply Hadamard transformation to the first qubit
      qr.applyHadamard(0);

      // Ensure compiler doesn't optimize away the operation
      benchmark::DoNotOptimize(qr.getStateVector().data());
      benchmark::ClobberMemory();
    }
  } catch (const std::exception &err) {
    state.SkipWithError(err.what());
  }
}

// Register benchmarks for different system sizes
