#define UPDATENOTIFIER_DEBUG DEBUG_FLAGS_NONE
#ifdef DEBUGALL
#undef UPDATENOTIFIER_DEBUG
#define UPDATENOTIFIER_DEBUG DEBUG_FLAGS_EVERYTHING
#endif

UINT updatenotifier_debug = UPDATENOTIFIER_DEBUG;

// GitHub API endpoint for latest release
const char* szGitHubRepoReleases = "https://api.github.com/repos/sc2kfix/sc2kfix/releases?per_page=1";

// Required HTTP headers
const char* szGitHubAPIType[] = { "Accept: application/vnd.github+json", NULL };

// Stores parsed latest release tag
char szLatestRelease[24] = { 0 };

// Flag indicating if an update is available
BOOL bUpdateAvailable = FALSE;

// Thread entry point to perform update check asynchronously
DWORD WINAPI UpdaterThread(LPVOID lpParameter) {
    // Delay to let main initialization complete
    Sleep(200);
    bUpdateAvailable = UpdaterCheckForUpdates();
    return EXIT_SUCCESS;
}

// Buffer sizes for download
#define FETCHBUF_SIZE 4096
#define BUF_SIZE (FETCHBUF_SIZE * 4)

// Main update-checking function
BOOL UpdaterCheckForUpdates(void) {
    HINTERNET hInet = nullptr;
    HINTERNET hRequest = nullptr;
    BOOL bResult = FALSE;
    char* szDownloadBuffer = nullptr;
    DWORD dwBytesRead = 0;
    DWORD dwTotalBytes = 0;
    char szTempChunk[FETCHBUF_SIZE + 1];

    // Initialize WinINet session
    hInet = InternetOpen("sc2kfix Update Notifier", INTERNET_OPEN_TYPE_DIRECT, NULL, NULL, NULL);
    if (!hInet) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Failed to open Internet session.\n");
        goto Cleanup;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  InternetOpen() succeeded.\n");

    // Set connection timeout to 3 seconds
    DWORD dwTimeout = 3000;
    InternetSetOption(hInet, INTERNET_OPTION_CONNECT_TIMEOUT, &dwTimeout, sizeof(DWORD));

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Timeout set to 3000ms.\n");

    // Open URL request with custom header
    DWORD dwContext = 0;
    hRequest = InternetOpenUrl(hInet, szGitHubRepoReleases,
                               "X-GitHub-Api-Version: 2022-11-28\r\n", -1L,
                               INTERNET_FLAG_SECURE, (DWORD_PTR)&dwContext);

    if (!hRequest) {
        DWORD err = GetLastError();
        if (err == ERROR_INTERNET_TIMEOUT || err == 12002)
            ConsoleLog(LOG_WARNING, "UPD:  Request timed out after 3000 ms.\n");
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  InternetOpenUrl failed, error 0x%08X.\n", err);
        goto Cleanup;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  InternetOpenUrl() succeeded.\n");

    // Allocate buffer for full response
    szDownloadBuffer = (char*)malloc(BUF_SIZE + 1);
    if (!szDownloadBuffer) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Memory allocation for download buffer failed.\n");
        goto Cleanup;
    }

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Download buffer allocated (%u bytes).\n", BUF_SIZE);

    // Clear buffer and prepare for chunked read
    ZeroMemory(szDownloadBuffer, BUF_SIZE + 1);
    ZeroMemory(szTempChunk, sizeof(szTempChunk));

    // Read data in chunks until done or buffer full
    do {
        if (!InternetReadFile(hRequest, szTempChunk, FETCHBUF_SIZE, &dwBytesRead))
            break;

        if (dwBytesRead == 0)
            break;

        // Prevent overflow
        if (dwTotalBytes + dwBytesRead > BUF_SIZE)
            break;

        // Append chunk safely
        strncat_s(szDownloadBuffer, BUF_SIZE + 1, szTempChunk, dwBytesRead);
        dwTotalBytes += dwBytesRead;

        // Reset temp buffer
        ZeroMemory(szTempChunk, sizeof(szTempChunk));
    } while (dwBytesRead > 0);

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  InternetReadFile() completed. Total bytes: %u.\n", dwTotalBytes);

    // Parse JSON for tag_name
    char* pTagStart = strstr(szDownloadBuffer, "\"tag_name\"");
    if (!pTagStart) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Could not find \"tag_name\" in response.\n");
        goto Cleanup;
    }

    // Find closing quote after tag value
    char* pEndQuote = strstr(pTagStart, "\",");
    if (!pEndQuote) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Malformed tag_name field (no closing comma/quote).\n");
        goto Cleanup;
    }

    // Extract substring between quotes
    size_t len = pEndQuote - pTagStart - 1; // exclude quotes
    if (len >= sizeof(szLatestRelease)) {
        if (updatenotifier_debug)
            ConsoleLog(LOG_ERROR, "UPD:  Tag name too long.\n");
        goto Cleanup;
    }

    strncpy_s(szLatestRelease, sizeof(szLatestRelease),
              pTagStart + 11, len); // skip '"tag_name":"'
    szLatestRelease[len] = '\0';

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Parsed latest release tag: '%s'\n", szLatestRelease);

    // Compare current vs latest version
    if (strcmp(szSC2KFixReleaseTag, szLatestRelease) != 0) {
        ConsoleLog(LOG_INFO, "UPD:  New release available: %s (running %s)\n",
                   szLatestRelease, szSC2KFixReleaseTag);

        if (dwDetectedVersion == VERSION_SC2K_1996)
            PostMessage(hwndMainDialog_SC2K1996, WM_SC2KFIX_UPDATE, 0, 1);

        bResult = TRUE;
    }

Cleanup:
    if (szDownloadBuffer)
        free(szDownloadBuffer);

    if (hRequest)
        InternetCloseHandle(hRequest);

    if (hInet)
        InternetCloseHandle(hInet);

    if (updatenotifier_debug)
        ConsoleLog(LOG_DEBUG, "UPD:  Cleanup completed.\n");

    return bResult;
}

