// Helper function to convert HRESULT to human-readable string representation
void DQRNetworkManager::LogComment(Platform::String^ strText)
{
#ifndef _CONTENT_PACKAGE
    static int64_t startTime = 0;
    wchar_t buffer[64];
    int64_t currentTime = System::currentTimeMillis();

    if (startTime != 0)
    {
        int64_t elapsed = currentTime - startTime;
        _i64tow_s(elapsed, buffer, 64, 10);
        OutputDebugString(buffer);
        OutputDebugString(L" ms: ");
    }
    else
    {
        startTime = currentTime;
    }

    OutputDebugString(strText->Data());
    OutputDebugString(L"\n");
#endif
}

// Format and log a message with variable arguments
void DQRNetworkManager::LogCommentFormat(LPCWSTR strMsg, ...)
{
    WCHAR formattedBuffer[2048];
    va_list arguments;
    va_start(arguments, strMsg);
    _vsnwprintf_s(formattedBuffer, 2048, _TRUNCATE, strMsg, arguments);
    formattedBuffer[2047] = L'\0';
    va_end(arguments);

    LogComment(ref new Platform::String(formattedBuffer));
}

// Log a message along with its associated error code
void DQRNetworkManager::LogCommentWithError(Platform::String^ text, HRESULT hr)
{
    Platform::String^ combinedMessage = text + GetErrorDescription(hr);
    LogComment(combinedMessage);
}

// Convert an HRESULT value to its symbolic name
Platform::String^ DQRNetworkManager::GetErrorDescription(HRESULT hr)
{
    Platform::String^ description = FormatString(L" %s [0x%0.8x]", ConvertHResultToSymbolicName(hr)->Data(), hr);
    return description;
}

// Create formatted wide string from format and arguments
Platform::String^ DQRNetworkManager::FormatString(LPCWSTR formatStr, ...)
{
    WCHAR tempBuffer[2048];
    va_list argList;
    va_start(argList, formatStr);
    _vsnwprintf_s(tempBuffer, 2048, _TRUNCATE, formatStr, argList);
    tempBuffer[2047] = L'\0';
    va_end(argList);

    return ref new Platform::String(tempBuffer);
}

