#include "HKDF.h"
#include <HKDF.h>
#include <SHA256.h>
#include <stdexcept>

using namespace RNS;

const Bytes RNS::Cryptography::hkdf(size_t out_len, const Bytes& input_key, const Bytes& salt /*= {Bytes::NONE}*/, const Bytes& info /*= {Bytes::NONE}*/) {
    if (out_len == 0) {
        throw std::invalid_argument("Output key length must be greater than zero");
    }
    if (input_key.empty()) {
        throw std::invalid_argument("Input key material cannot be empty");
    }

    HKDF<SHA256> hkdf_obj;

    if (!salt.empty()) {
        hkdf_obj.setKey(input_key.data(), input_key.size(), salt.data(), salt.size());
    } else {
        hkdf_obj.setKey(input_key.data(), input_key.size());
    }

    Bytes output(out_len);
    hkdf_obj.extract(output.data(), out_len);
    return output;
}

