//-----------------------------------------------------------------
#ifdef WITH_CANON
EdsError CanonController::initializeSDK() {
  m_lastError = EdsInitializeSDK();
  if (m_lastError == EDS_ERR_OK) {
    m_sdkInitialized = true;
  }
  if (!m_lastError)
    m_lastError =
        EdsSetCameraAddedHandler(CanonController::handleNewCameraEvent, (EdsVoid*)this);
  return m_lastError;
}

//-----------------------------------------------------------------
EdsCameraListRef CanonController::getConnectedCameras() {
  if (!m_sdkInitialized) initializeSDK();
  if (m_sdkInitialized) {
    m_lastError = EdsGetCameraList(&m_cameraList);
  }
  return m_cameraList;
}

//-----------------------------------------------------------------
EdsError CanonController::releaseCameraList() {
  if (m_cameraList != NULL) m_lastError = EdsRelease(m_cameraList);
  return m_lastError;
}

//-----------------------------------------------------------------
int CanonController::countConnectedDevices() {
  if (m_cameraList == NULL) {
    getConnectedCameras();
  }
  if (m_cameraList != NULL) {
    m_lastError = EdsGetChildCount(m_cameraList, &m_deviceCount);
    if (m_deviceCount == 0) {
      m_lastError = EDS_ERR_DEVICE_NOT_FOUND;
      if (m_sessionActive) {
        StopMotion::instance()->m_liveViewStatus = 0;
        m_sessionActive                            = false;
      }
    }
    return m_deviceCount;
  } else
    return -1;
}

//-----------------------------------------------------------------
EdsError CanonController::selectCamera(int index) {
  if (m_deviceCount == 0) {
    m_lastError = EDS_ERR_DEVICE_NOT_FOUND;
  }
  if (m_deviceCount > 0) {
    m_lastError = EdsGetChildAtIndex(m_cameraList, index, &m_activeCamera);
  }
  return m_lastError;
}

//-----------------------------------------------------------------
EdsError CanonController::deselectCamera() {
  if (m_activeCamera != NULL) {
    m_lastError = EdsRelease(m_activeCamera);
  }
  return m_lastError;
}

//-----------------------------------------------------------------
void CanonController::onCameraConnected() { 
  StopMotion::instance()->refreshCameraList(); 
}

//-----------------------------------------------------------------
void CanonController::shutdownSDK() {
  if (m_sdkInitialized) {
    EdsTerminateSDK();
  }
}

//-----------------------------------------------------------------
void CanonController::cleanupAllResources() {
#ifdef WITH_CANON
  if (m_activeCamera) deselectCamera();
  if (m_cameraList != NULL) releaseCameraList();
  if (m_sdkInitialized) shutdownSDK();
#endif
}

//-----------------------------------------------------------------
void CanonController::resetSystem(bool keepLiveView) {
#ifdef WITH_CANON
  m_dpiScale             = TPointD(0.0, 0.0);
  m_imageDimensions      = TDimension(0, 0);
  if (m_sessionActive && countConnectedDevices() > 0) {
    if (keepLiveView) {
      stopLiveView();
    }
    endSession();
  }
#endif
}

//-----------------------------------------------------------------
EdsError CanonController::startSession() {
  if (m_activeCamera != NULL) {
    m_lastError = EdsOpenSession(m_activeCamera);
    if (m_lastError == EDS_ERR_OK) m_sessionActive = true;
  }
  m_lastError = EdsSetObjectEventHandler(m_activeCamera, kEdsObjectEvent_All,
                                     CanonController::handleObjectEvent, (EdsVoid*)this);
  m_lastError =
      EdsSetPropertyEventHandler(m_activeCamera, kEdsPropertyEvent_All,
                                 CanonController::handlePropertyChange, (EdsVoid*)this);
  m_lastError = EdsSetCameraStateEventHandler(
      m_activeCamera, kEdsStateEvent_All, CanonController::handleStateChange, (EdsVoid*)this);

  // Ensure JPEG output instead of RAW
  if (getCurrentImageFormat().contains("RAW"))
    setImageFormat("Large Fine Jpeg");

  EdsUInt32 storageLocation = kEdsSaveTo_Host;
  m_lastError                 = EdsSetPropertyData(m_activeCamera, kEdsPropID_SaveTo, 0,
                               sizeof(EdsUInt32), &storageLocation);

  EdsCapacity bufferCapacity = {0x7FFFFFFF, 0x1000, 1};
  m_lastError                 = EdsSetCapacity(m_activeCamera, bufferCapacity);
  return m_lastError;
}

//-----------------------------------------------------------------
EdsError CanonController::endSession() {
  if (m_activeCamera != NULL) {
    m_lastError       = EdsCloseSession(m_activeCamera);
    m_sessionActive = false;
  }
  return m_lastError;
}

