//-----------------------------------------------------------------
QString CanonController::getCurrentBatteryStatus() {
  EdsError status = EDS_ERR_OK;
  EdsDataType batteryLevelType;
  EdsUInt32 sizeInfo;
  EdsUInt32 dataValue;
  QString result;
  status = EdsGetPropertySize(m_activeCamera, kEdsPropID_BatteryLevel, 0,
                           &batteryLevelType, &sizeInfo);
  status = EdsGetPropertyData(m_activeCamera, kEdsPropID_BatteryLevel, 0, sizeof(sizeInfo),
                           &dataValue);
  if (dataValue == 0xffffffff) {
    result = tr("AC Power");
  } else if (dataValue >= 80) {
    result = tr("Full");
  } else {
    // Handle battery reporting quirks
    if (dataValue % 10 == 9) dataValue += 1;
    result = QString::number(dataValue) + "%";
  }
  return result;
}

//-----------------------------------------------------------------
EdsError CanonController::setShutterSpeed(QString speed) {
  EdsError status = EDS_ERR_OK;
  EdsUInt32 value;
  auto iter = m_shutterTable.begin();
  while (iter != m_shutterTable.end()) {
    if (iter->second == speed.toStdString()) {
      value = iter->first;
      break;
    }
    iter++;
  }
  status = EdsSetPropertyData(m_activeCamera, kEdsPropID_Tv, 0, sizeof(value), &value);
  emit(shutterSpeedChangedSignal(speed));
  return status;
}

