//-----------------------------------------------------------------
EdsError CanonController::setAperture(QString aperture) {
  EdsError status = EDS_ERR_OK;
  EdsUInt32 value;
  auto iter = m_apertureTable.begin();
  while (iter != m_apertureTable.end()) {
    if (iter->second == aperture.toStdString()) {
      value = iter->first;
      status =
          EdsSetPropertyData(m_activeCamera, kEdsPropID_Av, 0, sizeof(value), &value);
      if (status == EDS_ERR_OK) {
        break;
      } else {
        // Handle duplicate aperture entries
        iter++;
        value = iter->first;
        status   = EdsSetPropertyData(m_activeCamera, kEdsPropID_Av, 0, sizeof(value),
                                 &value);
        break;
      }
    }
    iter++;
  }
  emit(apertureChangedSignal(aperture));
  return status;
}

