//-----------------------------------------------------------------
bool CanonController::downloadImageFromCamera(EdsBaseRef imageObject) {
  EdsError status        = EDS_ERR_OK;
  EdsStreamRef stream = NULL;
  EdsDirectoryItemInfo fileInfo;
  status = EdsGetDirectoryItemInfo(imageObject, &fileInfo);
  status = EdsCreateMemoryStream(0, &stream);
  status = EdsDownload(imageObject, fileInfo.size, stream);
  EdsDownloadComplete(imageObject);

  // Image processing code
#ifdef MACOSX
  UInt64 imageSize = 0;
#else
  unsigned __int64 imageSize = 0;
#endif
  unsigned char* imageData = NULL;
  status                 = EdsGetPointer(stream, (EdsVoid**)&imageData);
  status                 = EdsGetLength(stream, &imageSize);
  int width, height, pixelFormat;
  int subsampling, colorspace;
  tjhandle decompressor = NULL;
  unsigned char* decodedBuffer = NULL;
  decompressor            = tjInitDecompress();
  tjDecompressHeader3(decompressor, imageData, imageSize, &width, &height, &subsampling,
                      &colorspace);
  pixelFormat = TJPF_BGRX;
  decodedBuffer = (unsigned char*)tjAlloc(width * height * tjPixelSize[pixelFormat]);
  int flags = 0;
  flags |= TJFLAG_BOTTOMUP;
  int finalWidth, finalHeight;
  if (m_useResizedImages) {
    int factorCount;
    tjscalingfactor scaleFactor = {1, 1};
    tjscalingfactor* factors = tjGetScalingFactors(&factorCount);
    int aspectRatio = (float)width / (float)height * 100.0;
    int idx = 0;
    TCamera* camera =
        TApp::instance()->getCurrentScene()->getScene()->getCurrentCamera();
    TDimension resolution = camera->getRes();
    while (idx < factorCount) {
      scaleFactor = factors[idx];
      finalWidth     = TJSCALED(width, scaleFactor);
      if (finalWidth < resolution.lx && idx > 0) {
        scaleFactor = factors[idx - 1];
        break;
      }
      idx++;
    }
    while (idx >= 0) {
      finalWidth  = TJSCALED(width, scaleFactor);
      finalHeight = TJSCALED(height, scaleFactor);
      if ((int)((float)finalWidth / (float)finalHeight * 100.0) == aspectRatio) {
        break;
      }
      idx--;
      scaleFactor = factors[idx];
    }
  } else {
    finalWidth  = width;
    finalHeight = height;
  }
  if (m_useResizedImages || !getCurrentImageFormat().contains("Large")) {
    TCamera* camera =
        TApp::instance()->getCurrentScene()->getScene()->getCurrentCamera();
    TDimensionD physicalSize       = camera->getSize();
    m_imageDimensions = TDimension(finalWidth, finalHeight);
    double minimumDpi      = std::min(m_imageDimensions.lx / physicalSize.lx,
                                 m_imageDimensions.ly / physicalSize.ly);
    m_dpiScale             = TPointD(minimumDpi, minimumDpi);
  }
  tjDecompress2(decompressor, imageData, imageSize, decodedBuffer, finalWidth,
                finalWidth * tjPixelSize[pixelFormat], finalHeight, pixelFormat,
                flags);
  StopMotion::instance()->m_newImage = TRaster32P(finalWidth, finalHeight);
  StopMotion::instance()->m_newImage->lock();
  uchar* rawData = StopMotion::instance()->m_newImage->getRawData();
  memcpy(rawData, decodedBuffer, finalWidth * finalHeight * tjPixelSize[pixelFormat]);
  StopMotion::instance()->m_newImage->unlock();
  tjFree(decodedBuffer);
  decodedBuffer = NULL;
  tjDestroy(decompressor);
  decompressor = NULL;

  // Save full image if needed
  if (m_useResizedImages) {
    QFile fullImage(StopMotion::instance()->m_tempFile);
    fullImage.open(QIODevice::WriteOnly);
    QDataStream dataStream(&fullImage);
    dataStream.writeRawData((const char*)imageData, imageSize);
    fullImage.close();
  }
  EdsRelease(stream);
  stream = NULL;
  if (imageObject) EdsRelease(imageObject);
  if (status == EDS_ERR_OK) {
    emit(newCanonImageReady());
  }
  return status;
}

