//-----------------------------------------------------------------
EdsError CanonController::startLiveView() {
  if (m_activeCamera && m_sessionActive) {
    EdsError status = EDS_ERR_OK;
    EdsUInt32 outputDevice;
    status = EdsGetPropertyData(m_activeCamera, kEdsPropID_Evf_OutputDevice, 0,
                             sizeof(outputDevice), &outputDevice);
    if (status == EDS_ERR_OK) {
      outputDevice |= kEdsEvfOutputDevice_PC;
      status = EdsSetPropertyData(m_activeCamera, kEdsPropID_Evf_OutputDevice, 0,
                               sizeof(outputDevice), &outputDevice);
    }
    if (status == EDS_ERR_OK) {
      StopMotion::instance()->m_liveViewStatus = 1;
    }
    return status;
  } else
    return EDS_ERR_DEVICE_NOT_FOUND;
}

//-----------------------------------------------------------------
EdsError CanonController::stopLiveView() {
  EdsError status = EDS_ERR_OK;
  EdsUInt32 outputDevice;
  status = EdsGetPropertyData(m_activeCamera, kEdsPropID_Evf_OutputDevice, 0,
                           sizeof(outputDevice), &outputDevice);
  if (status == EDS_ERR_OK) {
    outputDevice &= ~kEdsEvfOutputDevice_PC;
    status = EdsSetPropertyData(m_activeCamera, kEdsPropID_Evf_OutputDevice, 0,
                             sizeof(outputDevice), &outputDevice);
  }
  StopMotion::instance()->m_liveViewStatus = 0;
  return status;
}

//-----------------------------------------------------------------
EdsError CanonController::adjustLiveViewZoom() {
  if (!m_sessionActive || !StopMotion::instance()->m_liveViewStatus > 0)
    return EDS_ERR_DEVICE_INVALID;
  EdsError status = EDS_ERR_OK;
  if (m_pickZoomPosition) toggleZoomSelection();
  if (m_zoomLevel == 1) {
    m_zoomLevel = 5;
    m_isZooming      = true;
    StopMotion::instance()->toggleNumpadForFocusCheck(true);
  } else if (m_zoomLevel == 5) {
    m_zoomLevel = 1;
    m_isZooming      = false;
    StopMotion::instance()->toggleNumpadForFocusCheck(false);
  }
  status = EdsSetPropertyData(m_activeCamera, kEdsPropID_Evf_Zoom, 0,
                           sizeof(m_zoomLevel), &m_zoomLevel);
  if (m_zoomLevel == 5) setZoomPosition();
  emit(focusCheckToggled(m_zoomLevel > 1));
  return status;
}

