//-----------------------------------------------------------------
void CanonController::toggleZoomSelection() {
  if (m_sessionActive && StopMotion::instance()->m_liveViewStatus > 0 &&
      !m_isZooming) {
    if (m_pickZoomPosition) {
      m_pickZoomPosition = false;
      StopMotion::instance()->toggleNumpadForFocusCheck(false);
    } else {
      m_pickZoomPosition = true;
      if (m_zoomPickPoint == TPointD(0.0, 0.0)) {
        setZoomPosition(m_zoomPickPoint);
      }
      StopMotion::instance()->toggleNumpadForFocusCheck(true);
    }
  }
  emit(pickFocusCheckToggled(m_pickZoomPosition));
}

