// Renamed class: CoordinateFunctor -> VertexAccessor
class VertexAccessor {
    const std::vector<Vec3f>* m_coords;
public:
    explicit VertexAccessor(const std::vector<Vec3f>* coords) : m_coords(coords) {}
    VertexAccessor() : m_coords(nullptr) {}

    float operator()(size_t index, size_t component) const {
        return (*m_coords)[index][component];
    }
};

// Renamed function: sgn -> signum
template<typename T>
int signum(T value) {
    return (T(0) < value) - (value < T(0));
}

/// Local coordinate frame aligned to a given normal vector
class OrientationFrame {
    Vec3f m_u, m_v, m_w; // u = binormal, v = tangent, w = normal

public:
    OrientationFrame()
        : m_u{1, 0, 0}, m_v{0, 1, 0}, m_w{0, 0, 1} {}

    OrientationFrame(const Vec3f& u, const Vec3f& v, const Vec3f& w)
        : m_u{u}, m_v{v}, m_w{w} {}

    void align_to_normal(const Vec3f& z_dir) {
        m_w = z_dir.normalized();
        Vec3f tempZ = m_w;
        Vec3f tempX = (std::abs(tempZ.x()) > 0.99f) ? Vec3f(0, 1, 0) : Vec3f(1, 0, 0);
        m_v = (tempZ.cross(tempX)).normalized();
        m_u = m_v.cross(tempZ);
    }

    Vec3f world_from_local(const Vec3f& local) const {
        return local.x() * m_u + local.y() * m_v + local.z() * m_w;
    }

    Vec3f local_from_world(const Vec3f& world) const {
        return Vec3f(m_u.dot(world), m_v.dot(world), m_w.dot(world));
    }

    const Vec3f& get_binormal() const { return m_u; }
    const Vec3f& get_tangent()  const { return m_v; }
    const Vec3f& get_normal()   const { return m_w; }
};

// Uniform sampling on unit sphere
Vec3f sample_full_sphere(const Vec2f& rand_vals) {
    float phi = 2.0f * float(PI) * rand_vals.x();
    float cos_theta = 1.0f - 2.0f * rand_vals.y();
    float sin_theta = sqrt(std::max(0.0f, 1.0f - cos_theta * cos_theta));
    return {sin_theta * cos(phi), sin_theta * sin(phi), cos_theta};
}

// Uniform sampling on upper hemisphere
Vec3f sample_upper_hemisphere(const Vec2f& rand_vals) {
    float phi = 2.0f * float(PI) * rand_vals.x();
    float z = std::abs(1.0f - 2.0f * rand_vals.y());
    float r = sqrt(std::max(0.0f, 1.0f - z * z));
    return {r * cos(phi), r * sin(phi), z};
}

// Power cosine hemisphere distribution (Beckmann-like)
Vec3f sample_power_cosine_hemisphere(const Vec2f& rand_vals, float exponent) {
    float phi = 2.f * float(PI) * rand_vals.x();
    float cos_theta = pow(rand_vals.y(), 1.f / (exponent + 1.f));
    float sin_theta = sqrt(std::max(0.0f, 1.f - cos_theta * cos_theta));
    return Vec3f(sin_theta * cos(phi), sin_theta * sin(phi), cos_theta);
}

// Main visibility computation routine
std::vector<float> compute_raycast_visibility(
    const AABBTreeIndirect::Tree<3, float>& tree,
    const indexed_triangle_set& mesh,
    const TriangleSetSamples& samples,
    size_t neg_volume_start_idx,
    const Visibility::Params& cfg
) {
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: raycast visibility of " << samples.positions.size() << " samples over "
                             << mesh.indices.size() << " triangles: start";

    // Precompute directions for Monte Carlo integration over hemisphere
    size_t num_dirs = cfg.sqr_rays_per_sample_point * cfg.sqr_rays_per_sample_point;
    std::vector<Vec3f> dir_list(num_dirs);
    float step = 1.0f / cfg.sqr_rays_per_sample_point;

    for (size_t i = 0; i < cfg.sqr_rays_per_sample_point; ++i) {
        float sx = i * step + step / 2.0f;
        for (size_t j = 0; j < cfg.sqr_rays_per_sample_point; ++j) {
            float sy = j * step + step / 2.0f;
            dir_list[i * cfg.sqr_rays_per_sample_point + j] = sample_upper_hemisphere({sx, sy});
        }
    }

    bool has_negative_parts = neg_volume_start_idx < mesh.indices.size();
    std::vector<float> visibility_scores(samples.positions.size(), 1.0f);

    tbb::parallel_for(
        tbb::blocked_range<size_t>(0, visibility_scores.size()),
        [&](const tbb::blocked_range<size_t>& range) {
            std::vector<igl::Hit> hit_buffer;
            for (size_t idx = range.begin(); idx < range.end(); ++idx) {
                float decrement = 1.0f / static_cast<float>(num_dirs);
                const Vec3f& pt = samples.positions[idx];
                const Vec3f& nrm = samples.normals[idx];

                OrientationFrame frame;
                frame.align_to_normal(nrm);

                for (const auto& d : dir_list) {
                    Vec3f ray_dir = frame.world_from_local(d);
                    if (!has_negative_parts) {
                        igl::Hit hit;
                        Vec3d origin_d = (pt + nrm * 0.01f).cast<double>();
                        Vec3d direction_d = ray_dir.cast<double>();

                        bool intersected = AABBTreeIndirect::intersect_ray_first_hit(
                            mesh.vertices, mesh.indices, tree, origin_d, direction_d, hit);

                        if (intersected && its_face_normal(mesh, hit.id).dot(ray_dir) <= 0.0) {
                            visibility_scores[idx] -= decrement;
                        }
                    } else {
                        bool from_neg_vol = samples.triangle_indices[idx] >= neg_volume_start_idx;
                        Vec3d origin_d = (from_neg_vol ? pt - nrm * 0.01f : pt + nrm * 0.01f).cast<double>();
                        Vec3d direction_d = (from_neg_vol ? -ray_dir : ray_dir).cast<double>();

                        hit_buffer.clear();
                        bool any_hit = AABBTreeIndirect::intersect_ray_all_hits(
                            mesh.vertices, mesh.indices, tree, origin_d, direction_d, hit_buffer);

                        if (any_hit) {
                            int winding_counter = 0;
                            for (int k = static_cast<int>(hit_buffer.size()) - 1; k >= 0; --k) {
                                const auto& h = hit_buffer[k];
                                Vec3f face_n = its_face_normal(mesh, h.id);
                                int contribution = signum(face_n.dot(direction_d));

                                if (h.id >= static_cast<int>(neg_volume_start_idx)) {
                                    winding_counter -= contribution;
                                } else {
                                    winding_counter += contribution;
                                }
                            }
                            if (winding_counter == 0) {
                                visibility_scores[idx] -= decrement;
                            }
                        }
                    }
                }
            }
        });

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: raycast visibility of " << samples.positions.size() << " samples over "
                             << mesh.indices.size() << " triangles: end";
    return visibility_scores;
}
} // namespace Impl

Visibility::Visibility(const Transform3d& obj_xform, const ModelVolumePtrs& vols, const Params& params,
                       const std::function<void(void)>& cancel_check) {
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: gather occlusion meshes: start";

    indexed_triangle_set positive_mesh, negative_mesh;
    for (const ModelVolume* vol : vols) {
        if (vol->type() == ModelVolumeType::MODEL_PART ||
            vol->type() == ModelVolumeType::NEGATIVE_VOLUME) {
            auto transform = vol->get_matrix();
            auto mesh_its = vol->mesh().its;
            its_transform(mesh_its, transform);

            if (vol->type() == ModelVolumeType::MODEL_PART)
                its_merge(positive_mesh, mesh_its);
            else
                its_merge(negative_mesh, mesh_its);
        }
    }

    cancel_check();

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: gather occlusion meshes: end";
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: decimate: start";

    its_short_edge_collpase(positive_mesh, params.fast_decimation_triangle_count_target);
    its_short_edge_collpase(negative_mesh, params.fast_decimation_triangle_count_target);

    size_t neg_start_idx = positive_mesh.indices.size();
    its_merge(positive_mesh, negative_mesh);
    its_transform(positive_mesh, obj_xform);

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: decimate: end";

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: Compute visibility sample points: start";
    this->mesh_samples = sample_its_uniform_parallel(params.raycasting_visibility_samples_count, positive_mesh);
    this->mesh_samples_coord_func = Impl::VertexAccessor(&this->mesh_samples.positions);
    this->mesh_samples_tree = KDTreeIndirect<3, float, Impl::VertexAccessor>(
        this->mesh_samples_coord_func, this->mesh_samples.positions.size());

    // Estimate search radius using exponential distribution approximation
    float prob = 0.9f;
    float target_samples = 4;
    float density = params.raycasting_visibility_samples_count / this->mesh_samples.total_area;
    float area = target_samples / (-logf(prob) * density);
    this->mesh_samples_radius = sqrt(area / PI);

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: Compute visiblity sample points: end";
    cancel_check();
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: Mesh sample raidus: " << this->mesh_samples_radius;

    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: build AABB tree: start";
    auto aabb_tree = AABBTreeIndirect::build_aabb_tree_over_indexed_triangle_set(
        positive_mesh.vertices, positive_mesh.indices);
    cancel_check();
    BOOST_LOG_TRIVIAL(debug) << "SeamPlacer: build AABB tree: end";

    this->mesh_samples_visibility = Impl::compute_raycast_visibility(
        aabb_tree, positive_mesh, this->mesh_samples, neg_start_idx, params);
    cancel_check();
}

float Visibility::point_visibility(const Vec3f& pos) const {
    std::vector<size_t> nearby = find_nearby_points(mesh_samples_tree, pos, mesh_samples_radius);
    if (nearby.empty()) return 1.0f;

    auto dist_to_plane = [](const Vec3f& p, const Vec3f& origin, const Vec3f& normal) {
        return std::abs((p - origin).dot(normal));
    };

    float weighted_sum = 0.0f;
    float weight_total = 0.0f;

    for (size_t i : nearby) {
        Vec3f sample_pt = mesh_samples.positions[i];
        Vec3f sample_nm = mesh_samples.normals[i];

        float d1 = dist_to_plane(pos, sample_pt, sample_nm);
        float d2 = (pos - sample_pt).norm();
        float w = (mesh_samples_radius - d1) + (mesh_samples_radius - d2);

        weighted_sum += w * mesh_samples_visibility[i];
        weight_total += w;
    }

    return weighted_sum / weight_total;
}
