// Helper function to shift data within a string buffer
template <class TStringType, class TReplacement, bool bInsert>
static Y_FORCE_INLINE void TransferData(typename TStringType::value_type* buffer, size_t& readIdx, size_t& writeIdx, const size_t boundary, const TReplacement& replacement, const size_t replLen) {
    const size_t stablePart = boundary - readIdx;

    if (writeIdx < readIdx) {
        // Need to move data backward
        for (size_t k = 0; k < stablePart; ++k) {
            buffer[writeIdx++] = buffer[readIdx++];
        }
    } else {
        // No actual movement needed, just advance pointers
        writeIdx += stablePart;
        readIdx += stablePart;
    }

    if (bInsert) {
        // Insert replacement string
        for (size_t k = 0; k < replLen; ++k) {
            buffer[writeIdx++] = replacement[k];
        }
    }
}

// Check if two string buffers share memory space
template <typename T1, typename T2>
static bool Overlaps(const T1& first, const T2& second) noexcept {
    if (second.data() < first.data()) {
        return Overlaps(second, first);
    }
    return !first.empty() && !second.empty() &&
           ((first.data() <= second.data() && second.data() < first.data() + first.size()) ||
            (first.data() < second.data() + second.size() && second.data() + second.size() <= first.data() + first.size()));
}

/**
 * Performs global substitution of all occurrences of 'from' with 'to' in string 's'.
 * Implements two strategies: one for growing strings, another for shrinking/same-size cases.
 */
template <class TStringType, typename TStringViewType = TBasicStringBuf<typename TStringType::value_type>>
static inline size_t ReplaceAllImpl(TStringType& str, const TStringViewType pattern, const TStringViewType replacement, size_t startPos = 0) {
    if (pattern.empty()) {
        return 0;
    }

    Y_ASSERT(!Overlaps(str, pattern));
    Y_ASSERT(!Overlaps(str, replacement));

    const size_t patternLength = pattern.size();
    const size_t replacementLength = replacement.size();
    size_t count = 0;
    size_t scanPos = startPos;
    size_t copyPos = 0;

    if (replacementLength > patternLength) {
        // String will expand: build new string by appending
        TStringType output;

        for (; (scanPos = TStringViewType(str).find(pattern, scanPos)) != TStringType::npos; scanPos += patternLength) {
            if (!count) {
                // First match found, pre-allocate extra space
                output.reserve(str.size() + str.size() / 3);
            }

            // Copy unchanged portion before match
            output.append(str.begin() + copyPos, str.begin() + scanPos);
            // Add replacement
            output.append(replacement.data(), replacementLength);
            copyPos = scanPos + patternLength;
            ++count;
        }

        if (count) {
            // Append remaining part after last match
            output.append(str.begin() + copyPos, str.end());
            str = std::move(output);
        }

        return count;
    }

    // In-place modification: no expansion needed
    size_t targetPos = 0;
    typename TStringType::value_type* dataPtr = &*str.begin();

    for (; (scanPos = TStringViewType(str).find(pattern, scanPos)) != TStringType::npos; scanPos += patternLength) {
        Y_ASSERT(targetPos <= copyPos);
        TransferData<TStringType, TStringViewType, true>(dataPtr, copyPos, targetPos, scanPos, replacement, replacementLength);
        copyPos = scanPos + patternLength;
        ++count;
    }

    if (count) {
        // Handle remaining tail
        TransferData<TStringType, TStringViewType, false>(dataPtr, copyPos, targetPos, str.size(), replacement, replacementLength);
        str.resize(targetPos);
    }

    return count;
}

/// Replaces all occurrences of character 'from' with character 'to' in string 's'
template <class TStringType>
inline size_t ReplaceCharAllImpl(TStringType& str, typename TStringType::value_type searchChar, typename TStringType::value_type replaceChar, size_t startPos = 0) {
    if (startPos >= str.size()) {
        return 0;
    }

    size_t resultCount = 0;
    startPos = str.find(searchChar, startPos);

    if (startPos != TStringType::npos) {
        auto* current = &*str.begin() + startPos;
        *current = replaceChar;
        ++resultCount;

        // Use end pointer to avoid repeated calls
        const auto* const finish = &*str.end();

        // Process in groups of 4 for better performance (loop unrolling)
        for (const auto* const groupEnd = finish - (finish - current) % 4; current < groupEnd;) {
            if (*current == searchChar) {
                *current = replaceChar;
                ++resultCount;
            }
            ++current;

            if (*current == searchChar) {
                *current = replaceChar;
                ++resultCount;
            }
            ++current;

            if (*current == searchChar) {
                *current = replaceChar;
                ++resultCount;
            }
            ++current;

            if (*current == searchChar) {
                *current = replaceChar;
                ++resultCount;
            }
            ++current;
        }

        // Handle remaining characters
        for (; current < finish; ++current) {
            if (*current == searchChar) {
                *current = replaceChar;
                ++resultCount;
            }
        }
    }

    return resultCount;
}

// Compile-time assertions for character type compatibility
static_assert(sizeof(wchar16) == sizeof(char16_t), "");
static_assert(sizeof(wchar32) == sizeof(char32_t), "");
static_assert(std::is_unsigned<wchar16>::value == std::is_unsigned<char16_t>::value, "");
static_assert(std::is_unsigned<wchar32>::value == std::is_unsigned<char32_t>::value, "");

// Public interface functions
size_t SubstGlobal(TCowString& text, const TStringBuf what, const TStringBuf with, size_t from) {
    return ReplaceAllImpl(text, what, with, from);
}

size_t SubstGlobal(TUtf16CowString& text, const TWtringBuf what, const TWtringBuf with, size_t from) {
    return ReplaceAllImpl(text, what, with, from);
}

size_t SubstGlobal(TUtf32CowString& text, const TUtf32StringBuf what, const TUtf32StringBuf with, size_t from) {
    return ReplaceAllImpl(text, what, with, from);
}

size_t SubstGlobal(TCowString& text, char what, char with, size_t from) {
    return ReplaceCharAllImpl(text, what, with, from);
}

size_t SubstGlobal(TUtf16CowString& text, wchar16 what, wchar16 with, size_t from) {
    return ReplaceCharAllImpl(text, static_cast<char16_t>(what), static_cast<char16_t>(with), from);
}

size_t SubstGlobal(TUtf32CowString& text, wchar32 what, wchar32 with, size_t from) {
    return ReplaceCharAllImpl(text, static_cast<char32_t>(what), static_cast<char32_t>(with), from);
}

#include "scope_filter.hpp"
#include "core/exception.hpp"
#include <regex>

namespace rocprofsys
{
namespace binary
{
bool scope_filter::operator()(std::string_view _value) const
{
    // Handle empty expression differently based on filter mode
    if (mode == FILTER_INCLUDE)
    {
        return expression.empty() ? true : 
               !std::regex_search(_value.data(), std::regex{ expression }) ? false : true;
    }
    else if (mode == FILTER_EXCLUDE)
    {
        return expression.empty() ? false : 
               std::regex_search(_value.data(), std::regex{ expression }) ? false : true;
    }

    // Throw exception for invalid mode
    throw exception<std::runtime_error>{ "invalid scope filter mode" };
}
}  // namespace binary
}  // namespace rocprofsys

