namespace mousefx::platform::scaffold {

bool SettingsRequestHandler::TryHandleStaticRequest(
    const HttpRequest& request,
    const std::string& pathOnly,
    HttpResponse& response) {

    // Only handle GET requests
    if (request.method != "GET") {
        return false;
    }

    // Handle favicon.ico specially
    if (pathOnly == "/favicon.ico") {
        response.statusCode = 204;
        response.contentType = "text/plain; charset=utf-8";
        response.body.clear();
        return true;
    }

    // Determine the actual web path to serve
    std::string requestedPath = request.path;
    if (IsHtmlPath(pathOnly, route_)) {
        requestedPath = "/index.html";
    }

    // Attempt to load the requested asset
    WebUiAsset asset;
    if (!TryLoadWebUiAsset(webUiBaseDirs_, requestedPath, &asset)) {
        return false;
    }

    // Prepare successful response
    response.statusCode = 200;
    response.contentType = asset.contentType;
    response.body.assign(
        reinterpret_cast<const char*>(asset.bytes.data()),
        asset.bytes.size()
    );
    return true;
}

} // namespace mousefx::platform::scaffold

