// Global driver instances (initialized once at startup)
static CWatchdogDriver_Sample g_watchdogInstance;
static CServerDriver_Sample g_serverInstance;

//-----------------------------------------------------------------------------
// Purpose: Factory function to instantiate VR driver interfaces
//-----------------------------------------------------------------------------
HMD_DLL_EXPORT void *HmdDriverFactory(const char *pInterfaceName, int *pReturnCode)
{
    // Check for server tracked device provider interface
    if (std::strcmp(IServerTrackedDeviceProvider_Version, pInterfaceName) == 0) {
        return &g_serverInstance;
    }

    // Check for watchdog provider interface
    if (std::strcmp(IVRWatchdogProvider_Version, pInterfaceName) == 0) {
        return &g_watchdogInstance;
    }

    // Interface not found - set error code if requested
    if (pReturnCode != nullptr) {
        *pReturnCode = VRInitError_Init_InterfaceNotFound;
    }

    return nullptr;
}

