// Check if the given vertex factory type is supported for lightmap ray tracing
bool IsSupportedVertexFactoryType(const FVertexFactoryType* VertexFactoryType)
{
	// Define supported vertex factory names
	static FName LocalVfName = FName(TEXT("FLocalVertexFactory"), FNAME_Find);
	static FName InstancedVfName = FName(TEXT("FInstancedStaticMeshVertexFactory"), FNAME_Find);
	static FName LandscapeVfName = FName(TEXT("FLandscapeVertexFactory"), FNAME_Find);
	static FName LandscapeFixedGridVfName = FName(TEXT("FLandscapeFixedGridVertexFactory"), FNAME_Find);
	static FName LandscapeXYOffsetVfName = FName(TEXT("FLandscapeXYOffsetVertexFactory"), FNAME_Find);

	const FVertexFactoryType* localVF = FindVertexFactoryType(LocalVfName);
	const FVertexFactoryType* instancedVF = FindVertexFactoryType(InstancedVfName);
	const FVertexFactoryType* landscapeVF = FindVertexFactoryType(LandscapeVfName);
	const FVertexFactoryType* landscapeFixedGridVF = FindVertexFactoryType(LandscapeFixedGridVfName);
	const FVertexFactoryType* landscapeXYOffsetVF = FindVertexFactoryType(LandscapeXYOffsetVfName);

	return VertexFactoryType == localVF ||
		   VertexFactoryType == instancedVF ||
		   VertexFactoryType == landscapeVF ||
		   VertexFactoryType == landscapeFixedGridVF ||
		   VertexFactoryType == landscapeXYOffsetVF;
}

