// Helper function to select appropriate hit shader based on material properties
static TShaderRef<FLightmapMaterialCHS> SelectLightmapHitShader(const FMaterial& RESTRICT MaterialResource, const FVertexFactory* VertexFactory)
{
	const bool bRequiresAnyHit = MaterialResource.IsMasked() || MaterialResource.GetBlendMode() == BLEND_Translucent;
	return bRequiresAnyHit 
		? MaterialResource.GetShader<TLightmapMaterialCHS<true>>(VertexFactory->GetType())
		: MaterialResource.GetShader<TLightmapMaterialCHS<false>>(VertexFactory->GetType());
}

// Process mesh batch for lightmap ray tracing
void FLightmapRayTracingMeshProcessor::Process(
	const FMeshBatch& RESTRICT MeshBatch,
	uint64 BatchElementMask,
	const FPrimitiveSceneProxy* RESTRICT PrimitiveSceneProxy,
	const FMaterialRenderProxy& RESTRICT MaterialRenderProxy,
	const FMaterial& RESTRICT MaterialResource,
	FMaterialShadingModelField ShadingModels,
	const FUniformLightMapPolicy& RESTRICT LightMapPolicy,
	const typename FUniformLightMapPolicy::ElementDataType& RESTRICT LightMapElementData)
{
	const FVertexFactory* VertexFactory = MeshBatch.VertexFactory;

	// Setup ray tracing shaders
	TMeshProcessorShaders<
		FMeshMaterialShader,
		FMeshMaterialShader,
		FMeshMaterialShader,
		FMeshMaterialShader,
		FMeshMaterialShader,
		FLightmapMaterialCHS> RayTracingShaders;

	RayTracingShaders.RayHitGroupShader = SelectLightmapHitShader(MaterialResource, VertexFactory);

	// Configure render state
	PassDrawRenderState.SetBlendState(TStaticBlendState<CW_RGBA, BO_Add, BF_One, BF_One, BO_Add, BF_Zero, BF_One>::GetRHI());
	PassDrawRenderState.SetDepthStencilState(TStaticDepthStencilState<false, CF_DepthNearOrEqual>::GetRHI());

	// Initialize shader element data
	TBasePassShaderElementData<FUniformLightMapPolicy> ShaderElementData(LightMapElementData);
	ShaderElementData.InitializeMeshMaterialData(ViewIfDynamicMeshCommand, PrimitiveSceneProxy, MeshBatch, -1, true);

	// Build ray tracing commands
	BuildRayTracingMeshCommands(
		MeshBatch,
		BatchElementMask,
		PrimitiveSceneProxy,
		MaterialRenderProxy,
		MaterialResource,
		PassDrawRenderState,
		RayTracingShaders,
		ShaderElementData);
}

