#include "PeakFinder.h"

using namespace soundtouch;

PeakFinder::PeakFinder()
{
    minPosition = maxPosition = 0;
}

// Locate the base level (ground) of a peak by stepping from 'peakIndex' in given direction,
// stopping when the signal starts rising again after a local minimum.
int PeakFinder::findGround(const float* signal, int peakIndex, int stepDirection) const
{
    float referenceAmplitude = signal[peakIndex];
    int lowestIndex = peakIndex;
    int currentIndex = peakIndex;
    int uphillStreak = 0;

    while (currentIndex > minPosition && currentIndex < maxPosition)
    {
        int previousIndex = currentIndex;
        currentIndex += stepDirection;

        float slope = signal[currentIndex] - signal[previousIndex];

        if (slope <= 0.0f)
        {
            // Moving downward or flat: reset climb counter
            if (uphillStreak > 0)
                --uphillStreak;

            if (signal[currentIndex] < referenceAmplitude)
            {
                lowestIndex = currentIndex;
                referenceAmplitude = signal[currentIndex];
            }
        }
        else
        {
            // Moving upward: increment climb counter
            ++uphillStreak;
            if (uphillStreak >= 5)
                break; // Too long going up — likely next peak
        }
    }

    return lowestIndex;
}

// Find index where the signal crosses a specified amplitude threshold,
// moving from 'peakIndex' in the given direction.
int PeakFinder::findCrossingLevel(const float* signal, float targetLevel, int peakIndex, int moveDirection) const
{
    float currentAmplitude = signal[peakIndex];
    assert(currentAmplitude >= targetLevel);

    int scanIndex = peakIndex;
    while (scanIndex >= minPosition && scanIndex < maxPosition)
    {
        int nextIndex = scanIndex + moveDirection;
        if (nextIndex < minPosition || nextIndex >= maxPosition)
            break;

        if (signal[nextIndex] < targetLevel)
            return scanIndex;

        scanIndex = nextIndex;
    }

    return -1; // No crossing found
}

// Compute center of mass of data points between firstIdx and lastIdx inclusive.
double PeakFinder::calcCenterOfMass(const float* values, int firstIdx, int lastIdx) const
{
    double weightedSum = 0.0;
    double totalWeight = 0.0;

    for (int idx = firstIdx; idx <= lastIdx; ++idx)
    {
        weightedSum += static_cast<double>(idx) * static_cast<double>(values[idx]);
        totalWeight += static_cast<double>(values[idx]);
    }

    if (totalWeight < 1e-6)
        return 0.0;

    return weightedSum / totalWeight;
}

// Determine precise peak location using center-of-mass around the peak hump.
double PeakFinder::getPeakCenter(const float* signal, int peakIndex) const
{
    float groundAmplitude1, groundAmplitude2;
    int baseLeft, baseRight;

    // Find valley points on both sides
    baseLeft = findGround(signal, peakIndex, -1);
    baseRight = findGround(signal, peakIndex, 1);

    groundAmplitude1 = signal[baseLeft];
    groundAmplitude2 = signal[baseRight];
    float baseline = std::max(groundAmplitude1, groundAmplitude2);

    float peakAmplitude = signal[peakIndex];

    if (baseline < 1e-6)
        return 0.0; // Insufficient signal contrast

    if (peakAmplitude / baseline < 1.3)
        return 0.0; // Peak too shallow relative to baseline

    // Define cut level at 70% of peak + 30% of baseline
    float threshold = 0.70f * peakAmplitude + 0.30f * baseline;

    int leftCross = findCrossingLevel(signal, threshold, peakIndex, -1);
    int rightCross = findCrossingLevel(signal, threshold, peakIndex, 1);

    if (leftCross < 0 || rightCross < 0)
        return 0.0; // Incomplete hump

    return calcCenterOfMass(signal, leftCross, rightCross);
}

// Detect dominant peak position via harmonic analysis and center-of-mass refinement.
double PeakFinder::detectPeak(const float* signal, int minPosInput, int maxPosInput)
{
    minPosition = minPosInput;
    maxPosition = maxPosInput;

    // Find absolute maximum
    int bestIndex = minPosition;
    float highestValue = signal[minPosition];

    for (int i = minPosition + 1; i < maxPosition; ++i)
    {
        if (signal[i] > highestValue)
        {
            highestValue = signal[i];
            bestIndex = i;
        }
    }

    // Refine using center-of-mass method
    double refinedLocation = getPeakCenter(signal, bestIndex);
    double finalLocation = refinedLocation;

    // Check for harmonic interference: maybe the true beat is a submultiple
    for (int harmonic = 2; harmonic < 10; ++harmonic)
    {
        int candidateIndex = static_cast<int>(refinedLocation / static_cast<double>(harmonic) + 0.5);
        if (candidateIndex < minPosition)
            break;

        double candidateLocation = getPeakCenter(signal, candidateIndex);
        int roundedRefined = static_cast<int>(refinedLocation + 0.5);
        int roundedCandidate = static_cast<int>(candidateLocation + 0.5);

        double val1 = signal[roundedRefined];
        double val2 = signal[roundedCandidate];
        double diffRatio = 2.0 * (val2 - val1) / (val2 + val1);

        if (std::fabs(diffRatio) < 0.1)
        {
            // Harmonic is close enough in amplitude — prefer the lower-frequency peak
            finalLocation = candidateLocation;
        }
    }

    return finalLocation;
}

