#include <stdlib.h>
#include <stdint.h>
#include "lock.h"
#include "fork_impl.h"

// Modified lagged Fibonacci generator implementation with improved seeding
static uint32_t seed_table[] = {
    0x00000000, 0x5851f42d, 0xc0b18ccf, 0xcbb5f646,
    0xc7033129, 0x30705b04, 0x20fd5db4, 0x9a8b7f78,
    0x502959d8, 0xab894868, 0x6c0356a7, 0x88cdb7ff,
    0xb477d43f, 0x70a3a52b, 0xa8e4baf1, 0xfd8341fc,
    0x8ae16fd9, 0x742d2f7a, 0x0d1f0796, 0x76035e09,
    0x40f7702c, 0x6fa72ca5, 0xaaa84157, 0x58a0df74,
    0xc74a0364, 0xae533cc4, 0x04185faf, 0x6de3b115,
    0x0cab8628, 0xf043bfa4, 0x398150e9, 0x37521657
};

static int buffer_size = 31;
static int index_i = 3;
static int index_j = 0;
static uint32_t *state_array = seed_table + 1;
static volatile int mutex_lock[1];
volatile int *const __random_mutex_ptr = mutex_lock;

// Linear congruential generator for 31-bit numbers
static uint32_t lcg_step_31(uint32_t value) {
    return (1103515245 * value + 12345) & 0x7fffffff;
}

// Linear congruential generator for 64-bit numbers
static uint64_t lcg_step_64(uint64_t value) {
    return 6364136223846793005ull * value + 1;
}

// Save current state to memory
static void *capture_state() {
    state_array[-1] = (buffer_size << 16) | (index_i << 8) | index_j;
    return state_array - 1;
}

// Restore state from memory
static void restore_state(uint32_t *saved_state) {
    state_array = saved_state + 1;
    buffer_size = state_array[-1] >> 16;
    index_i = (state_array[-1] >> 8) & 0xff;
    index_j = state_array[-1] & 0xff;
}

// Internal random seed initialization function
static void internal_srandom(unsigned seed_value) {
    int k;
    uint64_t temp_seed = seed_value;

    if (buffer_size == 0) {
        state_array[0] = temp_seed;
        return;
    }

    // Set initial indices based on buffer size
    index_i = (buffer_size == 31 || buffer_size == 7) ? 3 : 1;
    index_j = 0;

    // Fill the state array using LCG
    for (k = 0; k < buffer_size; k++) {
        temp_seed = lcg_step_64(temp_seed);
        state_array[k] = temp_seed >> 32;
    }

    // Ensure at least one odd number in the state
    state_array[0] |= 1;
}

// Public function to set random seed with thread safety
void srandom(unsigned seed_value) {
    LOCK(mutex_lock);
    internal_srandom(seed_value);
    UNLOCK(mutex_lock);
}

// Initialize random state buffer with given seed
char *initstate(unsigned seed_value, char *buffer, size_t size) {
    void *previous_state;

    if (size < 8)
        return 0;

    LOCK(mutex_lock);
    previous_state = capture_state();

    // Determine buffer size based on provided buffer size
    if (size < 32)
        buffer_size = 0;
    else if (size < 64)
        buffer_size = 7;
    else if (size < 128)
        buffer_size = 15;
    else if (size < 256)
        buffer_size = 31;
    else
        buffer_size = 63;

    state_array = (uint32_t*)buffer + 1;
    internal_srandom(seed_value);
    capture_state();
    UNLOCK(mutex_lock);

    return (char*)previous_state;
}

// Set new random state and return previous state
char *setstate(char *new_state) {
    void *previous_state;

    LOCK(mutex_lock);
    previous_state = capture_state();
    restore_state((uint32_t*)new_state);
    UNLOCK(mutex_lock);

    return (char*)previous_state;
}

// Generate next random number
long random(void) {
    long result;

    LOCK(mutex_lock);

    if (buffer_size == 0) {
        // Use simple LCG when no buffer is configured
        result = state_array[0] = lcg_step_31(state_array[0]);
        goto unlock_and_return;
    }

    // Lagged Fibonacci step
    state_array[index_i] += state_array[index_j];
    result = state_array[index_i] >> 1;

    // Update indices with wrap-around
    if (++index_i == buffer_size)
        index_i = 0;
    if (++index_j == buffer_size)
        index_j = 0;

unlock_and_return:
    UNLOCK(mutex_lock);
    return result;
}

