extern BOOL PrepareDialogSpriteGraphic_SC2K1996(CGraphics *pGraphic, HWND hWnd, sprite_header_t *pSprHead, __int16 nSpriteID, CMFC3XRect *pDlgRect);
extern HWND hWndExt;

BOOL CALLBACK SpriteBrowserDialogProc(HWND hWndDialog, UINT uMsg, WPARAM wParam, LPARAM lParam) {
    HWND hComboCtrl;
    CMFC3XRect rcCmd, rcClient, rcPaint;
    __int16 nCurrentSpriteID;
    char szEntryBuffer[80 + 1];
    int iIndex;
    sprite_header_t *pHeader;
    PAINTSTRUCT ps;
    std::string strLabel;
    int xPos, yPos;
    static __int16 nSelectedSpriteBase = -1;
    static CGraphics *pImgSmall = NULL;
    static CGraphics *pImgMedium = NULL;
    static CGraphics *pImgLarge = NULL;
    static BOOL bLoadFailSmall = FALSE;
    static BOOL bLoadFailMedium = FALSE;
    static BOOL bLoadFailLarge = FALSE;

    switch (uMsg) {
        case WM_INITDIALOG:
            hComboCtrl = GetDlgItem(hWndDialog, IDC_SPRITEBROWSER_COMBOCTRL);
            GetWindowRect(hComboCtrl, &rcCmd);

            pImgSmall = new CGraphics();
            pImgMedium = new CGraphics();
            pImgLarge = new CGraphics();

            ComboBox_AddString(hComboCtrl, "(Select Sprite ID)");
            unsigned idx = 1;
            while (idx < SPRITE_ENTRY_COUNT) {
                ZeroMemory(szEntryBuffer, sizeof(szEntryBuffer));
                sprintf_s(szEntryBuffer, sizeof(szEntryBuffer) - 1, "%d - %s", idx, szSpriteNames[idx]);
                ComboBox_AddString(hComboCtrl, szEntryBuffer);
                ++idx;
            }
            ComboBox_SetCurSel(hComboCtrl, 0);
            SetWindowPos(hComboCtrl, HWND_TOP, 0, 0, rcCmd.right - rcCmd.left, 200, SWP_NOZORDER | SWP_NOMOVE);
            CenterDialogBox(hWndDialog);
            return TRUE;

        case WM_PAINT:
            BeginPaint(hWndDialog, &ps);
            GetClientRect(hWndDialog, &rcClient);

            rcPaint.left = 10;
            rcPaint.top = 160;
            rcPaint.bottom = 180;
            rcPaint.right = 180;

            SelectFont(ps.hdc, hFontMSSansSerifRegular8);
            SetTextAlign(ps.hdc, TA_RIGHT | TA_TOP); // ETO_OPAQUE + align=8 implies right+top
            SetBkColor(ps.hdc, colBtnFace);
            SetTextColor(ps.hdc, RGB(0, 0, 0));

            if (nSelectedSpriteBase > 0) {
                // Small sprite section
                nCurrentSpriteID = nSelectedSpriteBase + SPRITE_SMALL_START;
                strLabel = "Small Sprite: ";
                strLabel += szInternalSpriteName[nCurrentSpriteID];
                strLabel += " / ";
                strLabel += std::to_string(nCurrentSpriteID);
                strLabel += " (";
                strLabel += HexPls(nCurrentSpriteID, 4);
                strLabel += ")";
                if (bLoadFailSmall)
                    strLabel += " - Not found.";
                FillRect(ps.hdc, &rcPaint, (HBRUSH)MainBrushFace->m_hObject);
                ExtTextOutA(ps.hdc, rcPaint.left, rcPaint.top, ETO_OPAQUE, &rcPaint, strLabel.c_str(), strLabel.length(), 0);

                pHeader = &pArrSpriteHeaders[nCurrentSpriteID];
                if (pHeader) {
                    xPos = rcClient.right - 40;
                    yPos = (rcClient.bottom - pHeader->wHeight) - 20;
                    if (pImgSmall && !bLoadFailSmall) {
                        Game_Graphics_SetColorTableFromApplicationPalette(pImgSmall);
                        Game_Graphics_Paint(pImgSmall, ps.hdc, xPos, yPos);
                    }
                }

                // Medium sprite section
                nCurrentSpriteID = nSelectedSpriteBase + SPRITE_MEDIUM_START;
                strLabel = "Medium Sprite: ";
                strLabel += szInternalSpriteName[nCurrentSpriteID];
                strLabel += " / ";
                strLabel += std::to_string(nCurrentSpriteID);
                strLabel += " (";
                strLabel += HexPls(nCurrentSpriteID, 4);
                strLabel += ")";
                if (bLoadFailMedium)
                    strLabel += " - Not found.";
                rcPaint.top += 40;
                rcPaint.bottom += 40;
                FillRect(ps.hdc, &rcPaint, (HBRUSH)MainBrushFace->m_hObject);
                ExtTextOutA(ps.hdc, rcPaint.left, rcPaint.top, ETO_OPAQUE, &rcPaint, strLabel.c_str(), strLabel.length(), 0);

                pHeader = &pArrSpriteHeaders[nCurrentSpriteID];
                if (pHeader) {
                    xPos -= (40 * 2);
                    yPos = (rcClient.bottom - pHeader->wHeight) - 20;
                    if (pImgMedium && !bLoadFailMedium) {
                        Game_Graphics_SetColorTableFromApplicationPalette(pImgMedium);
                        Game_Graphics_Paint(pImgMedium, ps.hdc, xPos, yPos);
                    }
                }

                // Large sprite section
                nCurrentSpriteID = nSelectedSpriteBase + SPRITE_LARGE_START;
                strLabel = "Large Sprite: ";
                strLabel += szInternalSpriteName[nCurrentSpriteID];
                strLabel += " / ";
                strLabel += std::to_string(nCurrentSpriteID);
                strLabel += " (";
                strLabel += HexPls(nCurrentSpriteID, 4);
                strLabel += ")";
                if (bLoadFailLarge)
                    strLabel += " - Not found.";
                rcPaint.top += 40;
                rcPaint.bottom += 40;
                FillRect(ps.hdc, &rcPaint, (HBRUSH)MainBrushFace->m_hObject);
                ExtTextOutA(ps.hdc, rcPaint.left, rcPaint.top, ETO_OPAQUE, &rcPaint, strLabel.c_str(), strLabel.length(), 0);

                pHeader = &pArrSpriteHeaders[nCurrentSpriteID];
                if (pHeader) {
                    xPos -= (40 * 4);
                    yPos = (rcClient.bottom - pHeader->wHeight) - 20;
                    if (pImgLarge && !bLoadFailLarge) {
                        Game_Graphics_SetColorTableFromApplicationPalette(pImgLarge);
                        Game_Graphics_Paint(pImgLarge, ps.hdc, xPos, yPos);
                    }
                }
            }

            EndPaint(hWndDialog, &ps);
            return FALSE;

        case WM_COMMAND: {
            WORD wNotifyCode = HIWORD(wParam);
            WORD wID = LOWORD(wParam);

            switch (wID) {
                case IDC_SPRITEBROWSER_COMBOCTRL:
                    if (wNotifyCode == CBN_KILLFOCUS ||
                        wNotifyCode == CBN_CLOSEUP ||
                        wNotifyCode == CBN_SELENDOK ||
                        wNotifyCode == CBN_SELENDCANCEL) {
                        UpdateWindow(hWndDialog);
                        if (!hWndExt)
                            hWndExt = hWndDialog;
                        return TRUE;
                    } else if (wNotifyCode == CBN_DROPDOWN) {
                        hWndExt = NULL;
                    }
                    return FALSE;

                case IDC_SPRITEBROWSER_SELBUT:
                    if (wNotifyCode == BN_CLICKED) {
                        if (!hWndExt)
                            hWndExt = hWndDialog;

                        hComboCtrl = GetDlgItem(hWndDialog, IDC_SPRITEBROWSER_COMBOCTRL);

                        ZeroMemory(szEntryBuffer, sizeof(szEntryBuffer));

                        if (pImgSmall)
                            pImgSmall->DeleteStored_SC2K1996();
                        if (pImgMedium)
                            pImgMedium->DeleteStored_SC2K1996();
                        if (pImgLarge)
                            pImgLarge->DeleteStored_SC2K1996();

                        nSelectedSpriteBase = -1;

                        iIndex = ComboBox_GetCurSel(hComboCtrl);
                        if (iIndex > 0) {
                            GetWindowRect(hWndDialog, &rcClient);
                            ScreenToClient(hWndDialog, (LPPOINT)&rcClient);
                            ScreenToClient(hWndDialog, (LPPOINT)&rcClient.right);
                            GetWindowText(hComboCtrl, szEntryBuffer, 5);
                            nSelectedSpriteBase = atoi(szEntryBuffer);

                            if (nSelectedSpriteBase > 0) {
                                nCurrentSpriteID = nSelectedSpriteBase + SPRITE_SMALL_START;
                                bLoadFailSmall = PrepareDialogSpriteGraphic_SC2K1996(pImgSmall, hWndDialog,
                                    &pArrSpriteHeaders[nCurrentSpriteID], nCurrentSpriteID, &rcClient);

                                nCurrentSpriteID = nSelectedSpriteBase + SPRITE_MEDIUM_START;
                                bLoadFailMedium = PrepareDialogSpriteGraphic_SC2K1996(pImgMedium, hWndDialog,
                                    &pArrSpriteHeaders[nCurrentSpriteID], nCurrentSpriteID, &rcClient);

                                nCurrentSpriteID = nSelectedSpriteBase + SPRITE_LARGE_START;
                                bLoadFailLarge = PrepareDialogSpriteGraphic_SC2K1996(pImgLarge, hWndDialog,
                                    &pArrSpriteHeaders[nCurrentSpriteID], nCurrentSpriteID, &rcClient);
                            }
                        }

                        InvalidateRect(hWndDialog, NULL, TRUE);
                        UpdateWindow(hWndDialog);
                        return TRUE;
                    }
                    break;

                case IDOK:
                    EndDialog(hWndDialog, 1);
                    return TRUE;

                case IDCANCEL:
                    EndDialog(hWndDialog, 0);
                    return TRUE;
            }
            break;
        }

        case WM_DESTROY:
            hWndExt = NULL;

            if (pImgSmall) {
                pImgSmall->DeleteStored_SC2K1996();
                delete pImgSmall;
                pImgSmall = nullptr;
            }
            if (pImgMedium) {
                pImgMedium->DeleteStored_SC2K1996();
                delete pImgMedium;
                pImgMedium = nullptr;
            }
            if (pImgLarge) {
                pImgLarge->DeleteStored_SC2K1996();
                delete pImgLarge;
                pImgLarge = nullptr;
            }

            nSelectedSpriteBase = -1;
            break;
    }

    return FALSE;
}

