// Global singleton instance
WebSvcMgrCurl gWebSvcMgr;
WebSvcMgr &TheWebSvcMgr = gWebSvcMgr;

// Destructor: cleans up curl multi handle safely
WebSvcMgrCurl::~WebSvcMgrCurl() {
    if (nullptr != mMultiHandle) {
        MILO_ASSERT(CURLM_OK == curl_multi_cleanup(mMultiHandle), 0x28);
        mMultiHandle = nullptr;
    }
}

// Initialize base class and underlying CURL infrastructure
void WebSvcMgrCurl::Init() {
    WebSvcMgr::Init();
    SetupCurlLayer();
}

// Poll active requests and process completed ones
void WebSvcMgrCurl::Poll() {
    WebSvcMgr::Poll();
    MILO_ASSERT(nullptr != mMultiHandle, 0xFE);

    int activeTransfers = 0;
    if (CURLM_OK == curl_multi_perform(mMultiHandle, &activeTransfers)) {
        static int sLastActiveCount = -1;
        if (sLastActiveCount != activeTransfers) {
            sLastActiveCount = activeTransfers;
        }

        int pendingMessages = 0;
        CURLMsg *transferResult;
        int maxIterations = 100; // prevent infinite loop

        while ((transferResult = curl_multi_info_read(mMultiHandle, &pendingMessages)) != nullptr && maxIterations > 0) {
            if (CURLMSG_DONE == transferResult->msg) {
                CURL *reqHandle = transferResult->easy_handle;
                bool successFlag = false;
                unsigned long httpStatusCode = 0;

                MILO_ASSERT(nullptr != reqHandle, 0x11D);
                if (0 == transferResult->data.result &&
                    0 == curl_easy_getinfo(reqHandle, (CURLINFO)0x200002, &httpStatusCode) &&
                    200 == httpStatusCode) {
                    successFlag = true;
                }

                CompleteRequest(reqHandle, successFlag, httpStatusCode);
            }

            --maxIterations;
            if (0 == maxIterations)
                break;
        }
    }
}

// Perform an HTTP request using the manager
bool WebSvcMgrCurl::DoRequest(
    ReqType type,
    unsigned int ip_addr,
    unsigned short port,
    const char *url,
    const char *extraHeaders,
    unsigned int timeout_ms,
    const char *bodyData,
    unsigned int bodySize
) {
    MILO_ASSERT(0 != ip_addr, 0x51);
    MILO_ASSERT(0 != port, 0x52);

    WebSvcRequest request(url, extraHeaders, nullptr);
    PrepareRequest(&request, type, ip_addr, port, bodyData, bodySize);
    request.Start();
    request.SetTimeout(timeout_ms);
    request.Perform();
    return request.IsSuccessful();
}

// Overload: IP-based initialization
bool WebSvcMgrCurl::InitRequest(
    WebSvcRequest *req,
    ReqType req_type,
    unsigned int ip_addr,
    unsigned short port,
    const char *payload,
    unsigned int payload_len
) {
    MILO_ASSERT(0 != ip_addr, 0x91);
    MILO_ASSERT(0 != port, 0x92);
    MILO_ASSERT(nullptr != req, 0x93);
    return InitRequest(req, req_type, nullptr, ip_addr, port, payload, payload_len);
}

// Overload: hostname-based initialization
bool WebSvcMgrCurl::InitRequest(
    WebSvcRequest *req,
    ReqType req_type,
    const char *hostname,
    unsigned short port,
    const char *payload,
    unsigned int payload_len
) {
    MILO_ASSERT(0 < strlen(hostname), 0xA0);
    MILO_ASSERT(0 != port, 0xA1);
    MILO_ASSERT(nullptr != req, 0xA2);
    return InitRequest(req, req_type, hostname, 0, port, payload, payload_len);
}

// Start a request within the multi-handle context
void WebSvcMgrCurl::Start(WebSvcRequest *req) {
    WebSvcMgr::Start(req);
    MILO_ASSERT(nullptr != req->GetUnderlyingRequest(), 0x40);
    CURL *curlHandle = req->GetUnderlyingRequest();
    MILO_ASSERT(CURLM_OK == curl_multi_add_handle(mMultiHandle, curlHandle), 0x42);
}

// Initialize the CURL multi handle
void WebSvcMgrCurl::SetupCurlLayer() {
    mMultiHandle = curl_multi_init();
    MILO_ASSERT(nullptr != mMultiHandle, 0x31);
}

// Core request setup logic (final overload)
bool WebSvcMgrCurl::InitRequest(
    WebSvcRequest *req,
    ReqType req_type,
    const char *hostname,
    unsigned int ip_addr,
    unsigned short port,
    const char *payload,
    unsigned int payload_len
) {
    MILO_ASSERT(0 != port, 0x6D);

    HttpReqCurl *curlImpl;
    if (0 != ip_addr) {
        curlImpl = new HttpReqCurl(req_type, ip_addr, port, req->GetBaseURL());
    } else {
        curlImpl = new HttpReqCurl(req_type, hostname, port, req->GetBaseURL());
    }

    MILO_ASSERT(nullptr != curlImpl, 0x79);

    if (0 != payload_len) {
        MILO_ASSERT(nullptr != payload && kHttpReqType_POST == req_type, 0x7E);
        curlImpl->SetBody(payload);
        curlImpl->SetBodyLength(payload_len);
    }

    curlImpl->SetCookies(req->GetCookies());
    req->AssignHttpImplementation(curlImpl);

    return true;
}

