TArray<FSequencerTrackInstanceInput> USequencerTrackInstanceBP::GetInputs() const
{
    using namespace UE::MovieScene;
    TArray<FSequencerTrackInstanceInput> OutputArray;

    // Retrieve raw inputs from parent class
    TArrayView<const FMovieSceneTrackInstanceInput> RawInputs = Super::GetInputs();
    OutputArray.Reserve(RawInputs.Num());

    for (int32 Idx = 0; Idx < RawInputs.Num(); ++Idx)
    {
        const FMovieSceneTrackInstanceInput& OriginalInput = RawInputs[Idx];

        FSequencerTrackInstanceInput ConvertedInput;
        ConvertedInput.Section = CastChecked<USequencerSectionBP>(OriginalInput.Section);

        const FInstanceRegistry* Registry = GetLinker()->GetInstanceRegistry();
        if (ensure(Registry && Registry->IsHandleValid(OriginalInput.InstanceHandle)))
        {
            ConvertedInput.Context = Registry->GetInstance(OriginalInput.InstanceHandle).GetContext();
        }

        OutputArray.Add(ConvertedInput);
    }

    return OutputArray;
}

