    if (!RawInputs.IsValidIndex(Index))
    {
        FFrame::KismetExecutionMessage(
            *FString::Printf(TEXT("Attempting to access input %d from an array of size %d."), Index, RawInputs.Num()),
            ELogVerbosity::Error
        );
        return FSequencerTrackInstanceInput{};
    }

    const FMovieSceneTrackInstanceInput& RawInput = RawInputs[Index];
    FSequencerTrackInstanceInput Output;
    Output.Section = CastChecked<USequencerSectionBP>(RawInput.Section);

    const FInstanceRegistry* Registry = GetLinker()->GetInstanceRegistry();
    if (ensure(Registry && Registry->IsHandleValid(RawInput.InstanceHandle)))
    {
        Output.Context = Registry->GetInstance(RawInput.InstanceHandle).GetContext();
    }

    return Output;
}

