// Internal conversion from Win32 flags to internal enum
popup_message_v3::query_t popup_message_v3::setupMessageBox(fb2k::hwnd_t parent, const char* msg, const char* title, unsigned flags) {
    query_t q = {};
    q.title = title;
    q.msg = msg;
    q.wndParent = parent;

    // Button mapping
    switch (flags & MB_TYPEMASK) {
    case MB_OK:
        q.buttons = buttonOK;
        q.defButton = buttonOK;
        break;
    case MB_OKCANCEL:
        q.buttons = buttonOK | buttonCancel;
        q.defButton = (flags & MB_DEFBUTTON2) ? buttonCancel : buttonOK;
        break;
    case MB_ABORTRETRYIGNORE:
        q.buttons = buttonAbort | buttonRetry | buttonIgnore;
        if (flags & MB_DEFBUTTON3) q.defButton = buttonIgnore;
        else if (flags & MB_DEFBUTTON2) q.defButton = buttonRetry;
        else q.defButton = buttonAbort;
        break;
    case MB_YESNOCANCEL:
        q.buttons = buttonYes | buttonNo | buttonCancel;
        if (flags & MB_DEFBUTTON3) q.defButton = buttonCancel;
        else if (flags & MB_DEFBUTTON2) q.defButton = buttonNo;
        else q.defButton = buttonYes;
        break;
    case MB_YESNO:
        q.buttons = buttonYes | buttonNo;
        q.defButton = (flags & MB_DEFBUTTON2) ? buttonNo : buttonYes;
        break;
    case MB_RETRYCANCEL:
        q.buttons = buttonRetry | buttonCancel;
        q.defButton = (flags & MB_DEFBUTTON2) ? buttonCancel : buttonRetry;
        break;
    }

    // Icon mapping
    switch (flags & MB_ICONMASK) {
    case MB_ICONHAND:
        q.icon = iconError;
        break;
    case MB_ICONQUESTION:
        q.icon = iconQuestion;
        break;
    case MB_ICONEXCLAMATION:
        q.icon = iconWarning;
        break;
    case MB_ICONASTERISK:
        q.icon = iconInformation;
        break;
    }

    return q;
}

// Map internal button status to Win32 return codes
int popup_message_v3::messageBoxReply(uint32_t resultFlags) {
    if (resultFlags & buttonOK) return IDOK;
    if (resultFlags & buttonCancel) return IDCANCEL;
    if (resultFlags & buttonYes) return IDYES;
    if (resultFlags & buttonNo) return IDNO;
    if (resultFlags & buttonRetry) return IDRETRY;
    if (resultFlags & buttonAbort) return IDABORT;
    if (resultFlags & buttonIgnore) return IDIGNORE;
    return IDCANCEL; // default fallback
}

// Async version
void popup_message_v3::messageBoxAsync(fb2k::hwnd_t parent, const char* msg, const char* title, unsigned flags, std::function<void(int)> callback) {
    PFC_ASSERT(core_api::is_main_thread());
    auto q = setupMessageBox(parent, msg, title, flags);

    if (callback) {
        q.reply = fb2k::makeCompletionNotify([callback](unsigned code) {
            callback(messageBoxReply(code));
        });
    }

    this->show_query(q);
}

// Synchronous blocking version
int popup_message_v3::messageBox(fb2k::hwnd_t parent, const char* msg, const char* title, unsigned flags) {
    PFC_ASSERT(core_api::is_main_thread());
    auto q = setupMessageBox(parent, msg, title, flags);
    uint32_t result = this->show_query_modal(q);
    return messageBoxReply(result);
}

#if MODE_METABALLS
#include "modes/MetaballsMode.h"
#include "extensions/MicrophoneExtension.h"
#include "services/DisplayService.h" // NOLINT(misc-include-cleaner)

void MetaballsMode::configure()
{
    // Precompute contribution values based on distance squared
    for (uint16_t idx = 0; idx < contributions.size(); ++idx)
    {
        const uint16_t diff = UINT8_MAX - idx;
        contributions[idx] = (diff * diff * 64U) >> 16U;
    }

    // Initialize balls with random positions and velocities
    for (Ball &ball : balls)
    {
        ball.x = static_cast<float>(random(GRID_COLUMNS));
        ball.y = static_cast<float>(random(GRID_ROWS));

        int8_t dirX = (random(2) * 2) - 1;
        int8_t dirY = (random(2) * 2) - 1;
        float speedFactorX = static_cast<float>(random(1, multiplier));
        float speedFactorY = static_cast<float>(random(1, multiplier));

        ball.xVelocity = speed * speedFactorX * static_cast<float>(dirX);
        ball.yVelocity = speed * speedFactorY * static_cast<float>(dirY);
    }
}

void MetaballsMode::handle()
{
#if EXTENSION_MICROPHONE
    if (!Microphone->isTriggered())
    {
        return;
    }
#endif // EXTENSION_MICROPHONE

#if PITCH_HORIZONTAL != PITCH_VERTICAL
    const bool isRotated = (static_cast<uint8_t>(Display.getOrientation()) & 1U) != 0U;
    const float horizontalScale = static_cast<float>(2 * (isRotated ? PITCH_VERTICAL : PITCH_HORIZONTAL)) /
                                  static_cast<float>(PITCH_VERTICAL + PITCH_HORIZONTAL);
    const float verticalScale   = static_cast<float>(2 * (isRotated ? PITCH_HORIZONTAL : PITCH_VERTICAL)) /
                                  static_cast<float>(PITCH_VERTICAL + PITCH_HORIZONTAL);
#endif // PITCH_HORIZONTAL == PITCH_VERTICAL

    // Update each pixel within the bounding boxes of all metaballs
    for (const Ball &ball : balls)
    {
        const int8_t xStart = max<int8_t>(static_cast<int8_t>(floorf(ball.x - radius - max<float>(ball.xVelocity, 0.0f))), 0);
        const int8_t yStart = max<int8_t>(static_cast<int8_t>(floorf(ball.y - radius - max<float>(ball.yVelocity, 0.0f))), 0);
        const int8_t xEnd   = min<int8_t>(static_cast<int8_t>(ceilf(ball.x + radius - min<float>(ball.xVelocity, 0.0f))), GRID_COLUMNS - 1);
        const int8_t yEnd   = min<int8_t>(static_cast<int8_t>(ceilf(ball.y + radius - min<float>(ball.yVelocity, 0.0f))), GRID_ROWS - 1);

        for (int8_t x = xStart; x <= xEnd; ++x)
        {
            for (int8_t y = yStart; y <= yEnd; ++y)
            {
                uint8_t accumulatedBrightness = 0;

                for (const Ball &otherBall : balls)
                {
#if PITCH_HORIZONTAL == PITCH_VERTICAL
                    const float dx = otherBall.x - static_cast<float>(x);
                    const float dy = otherBall.y - static_cast<float>(y);
#else
                    const float dx = (otherBall.x - static_cast<float>(x)) * horizontalScale;
                    const float dy = (otherBall.y - static_cast<float>(y)) * verticalScale;
#endif // PITCH_HORIZONTAL == PITCH_VERTICAL

                    const float distSq = dx * dx + dy * dy;
                    if (distSq < radiusSq)
                    {
                        const uint8_t normalizedDist = static_cast<uint8_t>((distSq * UINT8_MAX) / radiusSq);
                        accumulatedBrightness = min<uint8_t>(
                            accumulatedBrightness + contributions[normalizedDist],
                            UINT8_MAX
                        );
                        if (accumulatedBrightness >= UINT8_MAX)
                        {
                            break;
                        }
                    }
                }

                Display.setPixel(static_cast<uint8_t>(x), static_cast<uint8_t>(y), accumulatedBrightness);
            }
        }
    }

    // Move balls and handle boundary collisions
    for (Ball &ball : balls)
    {
        ball.x += ball.xVelocity;
        ball.y += ball.yVelocity;

        if (ball.x < 0.0f)
        {
            ball.x = 0.0f;
            ball.xVelocity = speed * static_cast<float>(random(1, multiplier));
        }
        else if (ball.x > GRID_COLUMNS - 1)
        {
            ball.x = GRID_COLUMNS - 1;
            ball.xVelocity = -speed * static_cast<float>(random(1, multiplier));
        }

        if (ball.y < 0.0f)
        {
            ball.y = 0.0f;
            ball.yVelocity = speed * static_cast<float>(random(1, multiplier));
        }
        else if (ball.y > GRID_ROWS - 1)
        {
            ball.y = GRID_ROWS - 1;
            ball.yVelocity = -speed * static_cast<float>(random(1, multiplier));
        }
    }
}
#endif // MODE_METABALLS

