// Global log interface pointer
static vr::IVRDriverLog* g_driverLogContext = nullptr;

#if !defined(_WIN32)
// Map vsnprintf_s to vsnprintf on non-Windows platforms
#define vsnprintf_s vsnprintf
#endif

// Initialize the logging system - returns true if successful
bool InitDriverLog(vr::IVRDriverLog* pLogInstance)
{
    // Check if already initialized
    if (g_driverLogContext != nullptr) {
        return false;
    }

    // Set the new log instance
    g_driverLogContext = pLogInstance;

    // Verify assignment succeeded
    return g_driverLogContext != nullptr;
}

// Shutdown logging by clearing the pointer
void CleanupDriverLog()
{
    g_driverLogContext = nullptr;
}

// Core logging function using variable arguments
static void LogMessageVa(const char* formatString, va_list argumentList)
{
    char messageBuffer[1024];
    vsnprintf_s(messageBuffer, sizeof(messageBuffer), formatString, argumentList);

    // Write to log if interface is available
    if (g_driverLogContext != nullptr) {
        g_driverLogContext->Log(messageBuffer);
    }
}

// Public logging function - always active
void DriverLog(const char* formatString, ...)
{
    va_list args;
    va_start(args, formatString);
    LogMessageVa(formatString, args);
    va_end(args);
}

// Debug-only logging function
void DebugDriverLog(const char* formatString, ...)
{
#ifdef _DEBUG
    va_list args;
    va_start(args, formatString);
    LogMessageVa(formatString, args);
    va_end(args);
#endif
}

