// Count how many visual lines are in the given UTF-8 string; returns 0 on decode error
static size_t count_utf8_lines(std::string_view input)
{
	size_t line_count = 1;

	const char* iter = input.data();
	const char* end = iter + input.size();

	while (iter < end) {
		uint32_t codepoint;
		int decode_error = 0;
		iter = utf8_decode(iter, &codepoint, &decode_error);
		if (decode_error != 0) return 0;
		if (codepoint == '\n') ++line_count;
	}

	return line_count;
}


void ws_source::track_cursor_position(const char* buffer, int cursor_index)
{
	if (m_cursor_line_index == cursor_index) return;
	m_cursor_line_index = cursor_index;
	m_current_line = count_utf8_lines({ buffer, static_cast<size_t>(cursor_index) });
}


void ws_source::reset_state()
{
	m_needs_refresh = true;
}


static void extract_source_code(const oper_block& blk, std::string& output_buffer)
{
	output_buffer.clear();

	std::ostringstream stream;
	ims_precision precision(stream);
	precision.template max<DefNumTypes::Real>();

	ims_write_block(stream, &blk);

	output_buffer = stream.str();
}

