void ws_source::commit(bool is_js_mode)
{
	if (!is_js_mode) {
		const oper_block* current = get_cur_block();
		if (current != m_visible.b || (current && current->m_flags.from_js)) {
			report_generic_error();
			return;
		}
	}

	m_editor = m_visible;
	m_editor.js_mode = is_js_mode;
	try_open_file([this]() {
		open_file("", "", true, false, &m_editor);
	}, false);
}


void ws_source::insert_new()
{
	m_editor.b = nullptr;
	m_editor.src = m_visible.src;
	m_editor.js_mode = false;
	try_open_file([this]() {
		open_file("", "", true, false, &m_editor);
	}, false);
}


void ws_source::render(int& unique_id, bool is_js_mode)
{
	const oper_block* current_block = nullptr;

	auto& js_source_data = ims_info_get().m_js_src;

	m_needs_refresh = m_needs_refresh || m_visible.js_mode != is_js_mode;

	if (!is_js_mode) {
		current_block = get_cur_block();

		if (m_needs_refresh || current_block != m_visible.b) {
			m_visible.b = current_block;
			if (current_block) extract_source_code(*current_block, m_visible.src);
			else m_visible.src.clear();
		}
	}
	else {
		if (m_needs_refresh) {
			m_visible.src = js_source_data;
			m_visible.b = nullptr;
		}
	}

	m_needs_refresh = false;
	m_visible.js_mode = is_js_mode;

	/////////////////////////////////////////////////////////////////

	if (!is_js_mode) {
		SAME_LINE();
		if (ims_button("+Block", "Persist edits as new block", &unique_id)) {
			insert_new();
		}
	}

	enum ActionId
	{
		ACTION_ClipboardCut,
		ACTION_ClipboardCopy,
		ACTION_ClipboardPaste,
		ACTION_EditUndo,
		ACTION_EditRedo,
		ACTION_SelectAll,
	};

	static int s_last_action = ACTION_ClipboardCopy;

	{
		SAME_LINE();
		ImGui::PushID(unique_id++);
		ImGui::PushItemWidth(70 * get_ui_scale());
		static constexpr auto action_labels = { "Cut","Copy", "Paste", "Undo", "Redo", "Select All" };
		ImGui::Combo("", &s_last_action, action_labels.begin(), (int)action_labels.size(), (int)action_labels.size());
		ImGui::PopItemWidth();
		ImGui::PopID();
	}

	bool action_triggered = false;

	{
		SAME_LINE();
		action_triggered = ims_button("Apply", "", &unique_id);
	}

	{
		SAME_LINE();
		ImGui::Text(":%zu", m_current_line);
		set_tooltip("Current line number under cursor");
	}

	int editor_command = 0;

	if (action_triggered) {
		switch (s_last_action) {
		case ACTION_ClipboardCut:
			editor_command = 1;
			s_last_action = ACTION_ClipboardPaste;
			break;
		case ACTION_ClipboardCopy:
			editor_command = 2;
			s_last_action = ACTION_ClipboardPaste;
			break;
		case ACTION_ClipboardPaste:
			editor_command = 3;
			s_last_action = ACTION_ClipboardCopy;
			break;
		case ACTION_EditUndo:
			editor_command = 4;
			break;
		case ACTION_EditRedo:
			editor_command = 5;
			break;
		case ACTION_SelectAll:
			//simulate_ctrl_a_input();
			editor_command = 6;
			s_last_action = ACTION_ClipboardCopy;
			break;
		}
	}

	ImGui::g_edit_hook = editor_command;
	IMS_SCOPE([] {ImGui::g_edit_hook = 0; });

	// Expand InputTextMultiline to fill available space
	auto win_size = ImGui::GetWindowSize();
	auto cursor_origin = ImGui::GetCursorPos();

	win_size.x -= cursor_origin.x * 2.0f;
	win_size.y -= cursor_origin.y + cursor_origin.x;

	ImGuiInputTextFlags edit_flags = ImGuiInputTextFlags_AllowTabInput;
	edit_flags |= ImGuiInputTextFlags_CallbackAlways;

	auto callback_fn = [](ImGuiInputTextCallbackData* ctx) -> int {
		ws_source* self = static_cast<ws_source*>(ctx->UserData);
		self->track_cursor_position(ctx->Buf, ctx->CursorPos);
		return 0;
	};

	// Prevent padding artifacts around border/frame
	ImGui::PushStyleVar(ImGuiStyleVar_WindowPadding, ImVec2(0, 0));
	ImGui::PushStyleColor(ImGuiCol_Border, ImGui::GetStyle().Colors[ImGuiCol_ChildBg]);
	ImGui::PushStyleColor(ImGuiCol_FrameBg, ImGui::GetStyle().Colors[ImGuiCol_ChildBg]);

	if (action_triggered) {
		ImGui::SetItemDefaultFocus();
		ImGui::SetKeyboardFocusHere();
	}

	ImGui::InputTextMultiline("###source", &m_visible.src, win_size, edit_flags, callback_fn, this);

	ImGui::PopStyleColor(2);
	ImGui::PopStyleVar(1);
}

