void Snapshot::clear() {
    this->identifier.clear();
    this->timestamp_captured = 0;
    this->slic3r_version_captured = Semver::invalid();
    this->note.clear();
    this->trigger = SNAPSHOT_UNKNOWN;
    this->print_preset.clear();
    this->sla_print_preset.clear();
    this->filaments.clear();
    this->sla_material_preset.clear();
    this->printer_preset.clear();
    this->physical_printer_preset.clear();
}

void Snapshot::load_ini(const std::string &filepath) {
    this->clear();

    auto report_error = [&filepath](const std::string &msg) {
        throw file_parser_error(std::string("Failed loading the snapshot file. Reason: ") + msg, filepath);
    };

    boost::property_tree::ptree root;
    try {
        boost::nowide::ifstream input(filepath);
        boost::property_tree::read_ini(input, root);
    } catch (const std::ifstream::failure &err) {
        throw file_parser_error(std::string("The snapshot file cannot be loaded. Reason: ") + err.what(), filepath);
    } catch (const std::runtime_error &err) {
        report_error(err.what());
    }

    const std::string vendor_prefix = "Vendor:";
    const std::string filament_key = "filament";
    const std::string model_prefix = "model_";

    for (auto &section : root) {
        if (section.first == "snapshot") {
            for (auto &entry : section.second) {
                if (entry.first == "id")
                    this->identifier = entry.second.data();
                else if (entry.first == "time_captured") {
                    this->timestamp_captured = Slic3r::Utils::parse_iso_utc_timestamp(entry.second.data());
                    if (this->timestamp_captured == (time_t)-1)
                        report_error("invalid timestamp");
                }
                else if (entry.first == "slic3r_version_captured") {
                    auto parsed_semver = Semver::parse(entry.second.data());
                    if (!parsed_semver)
                        report_error("invalid slic3r_version_captured semver");
                    this->slic3r_version_captured = *parsed_semver;
                }
                else if (entry.first == "comment") {
                    this->note = entry.second.data();
                }
                else if (entry.first == "reason") {
                    std::string rsn = entry.second.data();
                    if (rsn == "upgrade")
                        this->trigger = SNAPSHOT_UPGRADE;
                    else if (rsn == "downgrade")
                        this->trigger = SNAPSHOT_DOWNGRADE;
                    else if (rsn == "before_rollback")
                        this->trigger = SNAPSHOT_BEFORE_ROLLBACK;
                    else if (rsn == "user")
                        this->trigger = SNAPSHOT_USER;
                    else
                        this->trigger = SNAPSHOT_UNKNOWN;
                }
            }
        }
        else if (section.first == "presets") {
            for (auto &entry : section.second) {
                if (entry.first == "print")
                    this->print_preset = entry.second.data();
                else if (entry.first == "sla_print")
                    this->sla_print_preset = entry.second.data();
                else if (boost::starts_with(entry.first, filament_key)) {
                    int index = 0;
                    if (entry.first == "filament" || sscanf(entry.first.c_str(), "filament_%d", &index) == 1) {
                        if (static_cast<int>(this->filaments.size()) <= index)
                            this->filaments.resize(index + 1, std::string());
                        this->filaments[index] = entry.second.data();
                    }
                }
                else if (entry.first == "sla_material")
                    this->sla_material_preset = entry.second.data();
                else if (entry.first == "printer")
                    this->printer_preset = entry.second.data();
                else if (entry.first == "physical_printer")
                    this->physical_printer_preset = entry.second.data();
            }
        }
        else if (boost::starts_with(section.first, vendor_prefix) &&
                 section.first.size() > vendor_prefix.size()) {
            VendorConfig vc;
            vc.name = section.first.substr(vendor_prefix.size());
            for (auto &entry : section.second) {
                if (entry.first == "version" || entry.first == "min_slic3r_version" || entry.first == "max_slic3r_version") {
                    auto semver = Semver::parse(entry.second.data());
                    if (!semver)
                        report_error("invalid " + entry.first + " format for " + section.first);
                    if (entry.first == "version")
                        vc.version.config_version = *semver;
                    else if (entry.first == "min_slic3r_version")
                        vc.version.min_slic3r_version = *semver;
                    else
                        vc.version.max_slic3r_version = *semver;
                }
                else if (boost::starts_with(entry.first, model_prefix) && entry.first.size() > model_prefix.size()) {
                    auto &variant_set = vc.models_variants_installed[entry.first.substr(model_prefix.size())];
                    std::vector<std::string> variants;
                    if (unescape_strings_cstyle(entry.second.data(), variants))
                        for (auto &v : variants)
                            variant_set.insert(std::move(v));
                }
            }
            this->vendor_configs.emplace_back(std::move(vc));
        }
    }

    // Sort vendors lexicographically by name
    std::sort(this->vendor_configs.begin(), this->vendor_configs.end(),
              [](const VendorConfig &a, const VendorConfig &b) { return a.name < b.name; });
}

static std::string reason_to_string(const Snapshot::Reason trigger) {
    switch (trigger) {
    case Snapshot::SNAPSHOT_UPGRADE:
        return "upgrade";
    case Snapshot::SNAPSHOT_DOWNGRADE:
        return "downgrade";
    case Snapshot::SNAPSHOT_BEFORE_ROLLBACK:
        return "before_rollback";
    case Snapshot::SNAPSHOT_USER:
        return "user";
    case Snapshot::SNAPSHOT_UNKNOWN:
    default:
        return "unknown";
    }
}

void Snapshot::save_ini(const std::string &filepath) {
    boost::nowide::ofstream output;
    output.open(filepath, std::ios::out | std::ios::trunc);
    output << "# " << Slic3r::header_slic3r_generated() << std::endl;

    output << std::endl << "[snapshot]" << std::endl;
    output << "id = " << this->identifier << std::endl;
    output << "time_captured = " << Slic3r::Utils::iso_utc_timestamp(this->timestamp_captured) << std::endl;
    output << "slic3r_version_captured = " << this->slic3r_version_captured.to_string() << std::endl;
    output << "comment = " << this->note << std::endl;
    output << "reason = " << reason_to_string(this->trigger) << std::endl;

    output << std::endl << "[presets]" << std::endl;
    output << "print = " << this->print_preset << std::endl;
    output << "sla_print = " << this->sla_print_preset << std::endl;
    output << "filament = " << (this->filaments.empty() ? "" : this->filaments.front()) << std::endl;
    for (size_t i = 1; i < this->filaments.size(); ++i)
        output << "filament_" << i << " = " << this->filaments[i] << std::endl;
    output << "sla_material = " << this->sla_material_preset << std::endl;
    output << "printer = " << this->printer_preset << std::endl;
    output << "physical_printer = " << this->physical_printer_preset << std::endl;

    for (const VendorConfig &vc : this->vendor_configs) {
        output << std::endl << "[Vendor:" << vc.name << "]" << std::endl;
        output << "version = " << vc.version.config_version.to_string() << std::endl;
        output << "min_slic3r_version = " << vc.version.min_slic3r_version.to_string() << std::endl;
        output << "max_slic3r_version = " << vc.version.max_slic3r_version.to_string() << std::endl;

        for (const auto &model_entry : vc.models_variants_installed) {
            if (model_entry.second.empty())
                continue;
            const std::vector<std::string> variants(model_entry.second.begin(), model_entry.second.end());
            const auto escaped = escape_strings_cstyle(variants);
            output << "model_" << model_entry.first << " = " << escaped << std::endl;
        }
    }
    output.close();
}

void Snapshot::export_selections(AppConfig &config) const {
    assert(!filaments.empty());
    config.clear_section("presets");
    config.set("presets", "print", print_preset);
    config.set("presets", "sla_print", sla_print_preset);
    config.set("presets", "filament", filaments.front());
    for (unsigned idx = 1; idx < filaments.size(); ++idx) {
        char buffer[64];
        snprintf(buffer, sizeof(buffer), "filament_%u", idx);
        config.set("presets", buffer, filaments[idx]);
    }
    config.set("presets", "sla_material", sla_material_preset);
    config.set("presets", "printer", printer_preset);
    config.set("presets", "physical_printer", physical_printer_preset);
}

void Snapshot::export_vendor_configs(AppConfig &config) const {
    std::map<std::string, std::map<std::string, std::set<std::string>>> vendor_map;
    for (const VendorConfig &vc : vendor_configs)
        vendor_map[vc.name] = vc.models_variants_installed;
    config.set_vendors(std::move(vendor_map));
}

static constexpr const char* preset_subdirs[] = {"print", "sla_print", "filament", "sla_material",
                                                 "printer", "physical_printer", "vendor"};

bool Snapshot::equal_to_active(const AppConfig &app_config) const {
    // Compare vendor configs
    {
        std::set<std::string> matched_vendors;
        for (const VendorConfig &vc : this->vendor_configs) {
            auto it = app_config.vendors().find(vc.name);
            if (it == app_config.vendors().end() || it->second != vc.models_variants_installed)
                return false;
            matched_vendors.insert(vc.name);
        }
        for (const auto &v : app_config.vendors())
            if (matched_vendors.find(v.first) == matched_vendors.end() && !v.second.empty())
                return false;
    }

    // Compare ini files in each subdir
    boost::filesystem::path data_dir = boost::filesystem::path(Slic3r::data_dir());
    boost::filesystem::path snapshot_path = data_dir / SLIC3R_SNAPSHOTS_DIR / this->identifier;

    for (const char *subdir : preset_subdirs) {
        boost::filesystem::path src_dir = data_dir / subdir;
        boost::filesystem::path snap_dir = snapshot_path / subdir;

        std::vector<std::string> list_src, list_snap;
        if (boost::filesystem::is_directory(src_dir))
            for (auto &entry : boost::filesystem::directory_iterator(src_dir))
                if (Slic3r::is_ini_file(entry))
                    list_src.push_back(entry.path().filename().string());

        if (boost::filesystem::is_directory(snap_dir))
            for (auto &entry : boost::filesystem::directory_iterator(snap_dir))
                if (Slic3r::is_ini_file(entry))
                    list_snap.push_back(entry.path().filename().string());

        std::sort(list_src.begin(), list_src.end());
        std::sort(list_snap.begin(), list_snap.end());

        if (list_src != list_snap)
            return false;

        for (const std::string &filename : list_src) {
            FILE *fp1 = boost::nowide::fopen((src_dir / filename).string().c_str(), "rb");
            FILE *fp2 = boost::nowide::fopen((snap_dir / filename).string().c_str(), "rb");

            bool identical = true;
            if (fp1 && fp2) {
                char buf1[4096], buf2[4096];
                do {
                    size_t n1 = fread(buf1, 1, 4096, fp1);
                    size_t n2 = fread(buf2, 1, 4096, fp2);
                    if (n1 != n2 || memcmp(buf1, buf2, n1)) {
                        identical = false;
                        break;
                    }
                } while (!feof(fp1) || !feof(fp2));
            } else {
                identical = false;
            }

            if (fp1) fclose(fp1);
            if (fp2) fclose(fp2);

            if (!identical)
                return false;
        }
    }

    return true;
}

size_t SnapshotDB::load_db() {
    boost::filesystem::path db_path = SnapshotDB::create_db_dir();
    m_snapshots.clear();

    std::string error_log;
    for (auto &entry : boost::filesystem::directory_iterator(db_path)) {
        if (boost::filesystem::is_directory(entry.status())) {
            boost::filesystem::path ini_path = entry.path() / SLIC3R_SNAPSHOT_FILE;
            Snapshot snap;
            try {
                snap.load_ini(ini_path.string());
            } catch (const std::runtime_error &e) {
                error_log += e.what();
                error_log += "\n";
                continue;
            }

            if (entry.path().filename().string() != snap.identifier) {
                error_log += std::string("Snapshot ID ") + snap.identifier +
                             " does not match directory " + entry.path().filename().string() + "\n";
                continue;
            }

            m_snapshots.emplace_back(std::move(snap));
        }
    }

    std::sort(m_snapshots.begin(), m_snapshots.end(),
              [](const Snapshot &a, const Snapshot &b) { return a.timestamp_captured < b.timestamp_captured; });

    if (!error_log.empty())
        throw Slic3r::RuntimeError(error_log);

    return m_snapshots.size();
}

void SnapshotDB::update_slic3r_versions(std::vector<Index> &index_db) {
    for (Snapshot &snap : m_snapshots) {
        for (Snapshot::VendorConfig &vendor_cfg : snap.vendor_configs) {
            auto it_idx = std::find_if(index_db.begin(), index_db.end(),
                                       [&vendor_cfg](const Index &idx) { return idx.vendor() == vendor_cfg.name; });
            if (it_idx != index_db.end()) {
                Index::const_iterator it_ver = it_idx->find(vendor_cfg.version.config_version);
                if (it_ver != it_idx->end()) {
                    vendor_cfg.version.min_slic3r_version = it_ver->min_slic3r_version;
                    vendor_cfg.version.max_slic3r_version = it_ver->max_slic3r_version;
                }
            }
        }
    }
}

static void copy_single_level(const boost::filesystem::path &src,
                              const boost::filesystem::path &dst) {
    if (!boost::filesystem::is_directory(dst) && !boost::filesystem::create_directory(dst))
        throw Slic3r::RuntimeError(std::string("Directory creation failed at ") + dst.string());

    for (auto &entry : boost::filesystem::directory_iterator(src))
        if (Slic3r::is_ini_file(entry)) {
            std::string err_msg;
            if (copy_file(entry.path().string(), (dst / entry.path().filename()).string(), err_msg, false) != SUCCESS)
                throw Slic3r::RuntimeError(format("Failed copying \"%1%\" to \"%2%\": %3%",
                                                  src.string(), dst.string(), err_msg));
        }
}

static void remove_ini_files(const boost::filesystem::path &path) {
    if (!boost::filesystem::is_directory(path))
        return;
    for (auto &entry : boost::filesystem::directory_iterator(path))
        if (boost::filesystem::is_regular_file(entry.status()) &&
            boost::algorithm::iends_with(entry.path().filename().string(), ".ini"))
            boost::filesystem::remove(entry.path());
}

const Snapshot &SnapshotDB::take_snapshot(const AppConfig &app_config, Snapshot::Reason reason,
                                          const std::string &comment) {
    boost::filesystem::path data_dir = Slic3r::data_dir();
    boost::filesystem::path db_dir = SnapshotDB::create_db_dir();

    Snapshot snap;
    snap.timestamp_captured = Slic3r::Utils::get_current_time_utc();
    snap.identifier = Slic3r::Utils::iso_utc_timestamp(snap.timestamp_captured);
    snap.slic3r_version_captured = Slic3r::SEMVER;
    snap.note = comment;
    snap.trigger = reason;

    snap.print_preset = app_config.get("presets", "print");
    snap.sla_print_preset = app_config.get("presets", "sla_print");
    snap.filaments.emplace_back(app_config.get("presets", "filament"));
    snap.sla_material_preset = app_config.get("presets", "sla_material");
    snap.printer_preset = app_config.get("presets", "printer");
    snap.physical_printer_preset = app_config.get("presets", "physical_printer");

    for (unsigned idx = 1; idx < 1000; ++idx) {
        char key[64];
        snprintf(key, sizeof(key), "filament_%u", idx);
        if (!app_config.has("presets", key))
            break;
        snap.filaments.emplace_back(app_config.get("presets", key));
    }

    for (const auto &vendor_pair : app_config.vendors()) {
        Snapshot::VendorConfig cfg;
        cfg.name = vendor_pair.first;
        cfg.models_variants_installed = vendor_pair.second;

        for (auto it = cfg.models_variants_installed.begin(); it != cfg.models_variants_installed.end();) {
            if (it->second.empty())
                it = cfg.models_variants_installed.erase(it);
            else
                ++it;
        }

        PresetBundle bundle;
        bundle.load_configbundle((data_dir / "vendor" / (cfg.name + ".ini")).string(),
                                 PresetBundle::LoadConfigBundleAttribute::LoadVendorOnly,
                                 ForwardCompatibilitySubstitutionRule::EnableSilent);
        for (const auto &vp : bundle.vendors)
            if (vp.second.id == cfg.name)
                cfg.version.config_version = vp.second.config_version;

        try {
            Index idx;
            idx.load(data_dir / "vendor" / (cfg.name + ".idx"));
            auto it = idx.find(cfg.version.config_version);
            if (it != idx.end()) {
                cfg.version.min_slic3r_version = it->min_slic3r_version;
                cfg.version.max_slic3r_version = it->max_slic3r_version;
            }
        } catch (...) {}

        snap.vendor_configs.emplace_back(std::move(cfg));
    }

    boost::filesystem::path snap_dir = db_dir / snap.identifier;
    try {
        boost::filesystem::create_directory(snap_dir);
        for (const char *subdir : preset_subdirs)
            copy_single_level(data_dir / subdir, snap_dir / subdir);
        snap.save_ini((snap_dir / "snapshot.ini").string());
        m_snapshots.emplace_back(std::move(snap));
    } catch (...) {
        if (boost::filesystem::is_directory(snap_dir)) {
            try { boost::filesystem::remove_all(snap_dir); }
            catch (...) {
                BOOST_LOG_TRIVIAL(error) << "Cleanup failed for snapshot dir: " << snap_dir;
            }
        }
        throw;
    }

    return m_snapshots.back();
}

const Snapshot &SnapshotDB::restore_snapshot(const std::string &id, AppConfig &app_config) {
    for (const Snapshot &snap : m_snapshots)
        if (snap.identifier == id) {
            this->restore_snapshot(snap, app_config);
            return snap;
        }
    throw Slic3r::RuntimeError(std::string("Snapshot with id ") + id + " was not found.");
}

void SnapshotDB::restore_snapshot(const Snapshot &snap, AppConfig &app_config) {
    boost::filesystem::path data_dir = Slic3r::data_dir();
    boost::filesystem::path snap_dir = SnapshotDB::create_db_dir() / snap.identifier;

    for (const char *subdir : preset_subdirs) {
        boost::filesystem::path src = snap_dir / subdir;
        boost::filesystem::path dst = data_dir / subdir;
        remove_ini_files(dst);
        if (boost::filesystem::is_directory(src))
            copy_single_level(src, dst);
    }

    snap.export_selections(app_config);
    snap.export_vendor_configs(app_config);
}

bool SnapshotDB::is_on_snapshot(AppConfig &app_config) const {
    std::string current_id = app_config.get("on_snapshot");
    if (current_id.empty())
        return false;

    auto it = this->snapshot(current_id);
    if (it != this->end() && it->equal_to_active(app_config))
        return true;

    app_config.set("on_snapshot", "");
    return false;
}

SnapshotDB::const_iterator SnapshotDB::snapshot_with_vendor_preset(const std::string &vendor_name,
                                                                   const Semver &config_version) {
    Snapshot::VendorConfig search_key;
    search_key.name = vendor_name;

    const_iterator result = m_snapshots.end();
    for (auto it = m_snapshots.begin(); it != m_snapshots.end(); ++it) {
        const Snapshot &snap = *it;
        auto it_vendor = std::lower_bound(snap.vendor_configs.begin(), snap.vendor_configs.end(), search_key,
                                          [](const Snapshot::VendorConfig &a, const Snapshot::VendorConfig &b) {
                                              return a.name < b.name;
                                          });
        if (it_vendor != snap.vendor_configs.end() &&
            it_vendor->name == vendor_name &&
            config_version == it_vendor->version.config_version) {
            result = it;
        }
    }
    return result;
}

SnapshotDB::const_iterator SnapshotDB::snapshot(const std::string &id) const {
    for (const_iterator it = m_snapshots.begin(); it != m_snapshots.end(); ++it)
        if (it->identifier == id)
            return it;
    return m_snapshots.end();
}

boost::filesystem::path SnapshotDB::create_db_dir() {
    boost::filesystem::path data_dir = Slic3r::data_dir();
    boost::filesystem::path snapshots_dir = data_dir / SLIC3R_SNAPSHOTS_DIR;
    for (const boost::filesystem::path &p : {data_dir, snapshots_dir}) {
        p.make_preferred();
        if (!boost::filesystem::is_directory(p) && !boost::filesystem::create_directory(p))
            throw Slic3r::RuntimeError(std::string("Failed to create directory at ") + p.string());
    }
    return snapshots_dir;
}

SnapshotDB &SnapshotDB::singleton() {
    static SnapshotDB instance;
    static bool initialized = false;
    if (!initialized) {
        try {
            initialized = true;
            instance.load_db();
            std::vector<Index> indices = Index::load_db();
            instance.update_slic3r_versions(indices);
        } catch (...) {}
    }
    return instance;
}

const Snapshot *take_config_snapshot_report_error(const AppConfig &app_config, Snapshot::Reason reason,
                                                  const std::string &comment) {
    try {
        return &SnapshotDB::singleton().take_snapshot(app_config, reason, comment);
    } catch (const std::exception &e) {
        show_error(static_cast<wxWindow *>(wxGetApp().mainframe),
                   _L("Taking a configuration snapshot failed.") + "\n\n" + from_u8(e.what()));
        return nullptr;
    }
}

bool take_config_snapshot_cancel_on_error(const AppConfig &app_config, Snapshot::Reason reason,
                                          const std::string &comment, const std::string &message,
                                          Snapshot const **psnapshot) {
    try {
        const Snapshot *snap = &SnapshotDB::singleton().take_snapshot(app_config, reason, comment);
        if (psnapshot)
            *psnapshot = snap;
        return true;
    } catch (const std::exception &e) {
        RichMessageDialog dlg(static_cast<wxWindow *>(wxGetApp().mainframe),
                              _L("preFlight has encountered an error while taking a configuration snapshot.") + "\n\n" +
                                  from_u8(e.what()) + "\n\n" + from_u8(message),
                              _L("preFlight error"), wxYES_NO);
        dlg.SetYesNoLabels(_L("Continue"), _L("Abort"));
        return dlg.ShowModal() == wxID_YES;
    }
}

