#include "esptypes.h"
#include <cstdint>
#include <cstring>
#include <string>
#include <unordered_map>

ESP::SubRecord::SubRecord() : m_Type(TYPE_UNKNOWN), m_Data() {}

bool ESP::SubRecord::readFrom(std::istream& stream, uint32_t sizeOverride)
{
    // Predefined mapping of record type strings to enum values
    static std::unordered_map<std::string, EType> s_TypeMap = {
        {"HEDR", TYPE_HEDR},
        {"CNAM", TYPE_CNAM},
        {"MAST", TYPE_MAST},
        {"ONAM", TYPE_ONAM},
        {"SNAM", TYPE_SNAM}
    };

    char typeString[5];

    // Read the 4-byte type identifier
    if (!stream.read(typeString, 4)) {
        if (stream.gcount() == 0) {
            return false; // End of stream reached
        } else {
            throw ESP::InvalidRecordException("sub-record incomplete (unknown type)");
        }
    }

    // Verify full 4 bytes were read
    if (stream.gcount() != 4) {
        throw ESP::InvalidRecordException(
            std::string("sub-record type incomplete (invalid type ") + typeString + ")");
    }

    // Null-terminate for safe string operations
    typeString[4] = '\0';

    // Look up the type in the map
    auto iter = s_TypeMap.find(std::string(typeString));
    if (iter != s_TypeMap.end()) {
        m_Type = iter->second;
    } 
    // Special handling for XXXX records (nested subrecords)
    else if (std::strncmp(typeString, "XXXX", 4) == 0) {
        if (readType<uint16_t>(stream) != 4) {
            throw ESP::InvalidRecordException(
                "XXXX record is supposed to be 4 bytes in size");
        }
        // Recursively process the nested record with its actual size
        return readFrom(stream, readType<uint32_t>(stream));
    } 
    else {
        // Unknown but valid record type
        m_Type = TYPE_UNKNOWN;
    }

    // Read data size field
    uint32_t dataSize = readType<uint16_t>(stream);

    // Apply override if provided
    if (sizeOverride != 0UL) {
        dataSize = sizeOverride;
    }

    // Resize buffer and read data
    m_Data.resize(dataSize);
    if (dataSize > 0) {
        stream.read(reinterpret_cast<char*>(m_Data.data()), dataSize);
    }

    // Validate that all data was successfully read
    if (!stream) {
        throw ESP::InvalidRecordException(std::string("sub-record incomplete: ") + typeString);
    }

    return true;
}

