// Convert a 64-bit unsigned integer into big-endian byte representation
::mlspp::bytes_ns::bytes EncodeUInt64AsBE(uint64_t input) noexcept
{
    ::mlspp::bytes_ns::bytes result;
    result.resize(sizeof(input));
    for (size_t idx = 0; idx < sizeof(input); ++idx) {
        size_t shiftAmount = (sizeof(input) - 1 - idx) * 8;
        result[idx] = static_cast<uint8_t>((input >> shiftAmount) & 0xFF);
    }
    return result;
}

// Return a fixed cipher suite regardless of protocol version
::mlspp::CipherSuite SelectCiphersuite([[maybe_unused]] ProtocolVersion /*unused*/) noexcept
{
    return ::mlspp::CipherSuite{::mlspp::CipherSuite::ID::P256_AES128GCM_SHA256_P256};
}

ExternalSender::ExternalSender(discord::dave::ProtocolVersion version, uint64_t groupId)
{
    suite_ = SelectCiphersuite(version);
    auto beGroup = EncodeUInt64AsBE(groupId);
    groupId_.assign(beGroup.begin(), beGroup.end());

    sigPrivKey_ = std::make_shared<::mlspp::SignaturePrivateKey>(
      ::mlspp::SignaturePrivateKey::generate(suite_));
    externalSender_.signature_key = sigPrivKey_->public_key;
    externalSender_.credential = ::mlspp::Credential::basic({0x00, 0x01, 0x01, 0x00});
}

std::vector<uint8_t> ExternalSender::GetMarshalledExternalSender()
{
    return ::mlspp::tls::marshal(externalSender_);
}

std::vector<uint8_t> ExternalSender::ProposeAdd(uint32_t epoch,
                                                std::vector<uint8_t> const& keyPackage)
{
    const auto kpBytes = ::mlspp::bytes_ns::bytes(keyPackage);
    auto addProposal =
      ::mlspp::Proposal{::mlspp::Add{{::mlspp::tls::get<::mlspp::KeyPackage>(kpBytes)}}};

    auto msg = ::mlspp::external_proposal(
      suite_, groupId_, epoch, addProposal, signerIndex_, *sigPrivKey_);

    bool const isRevocation = false;
    ::mlspp::tls::ostream stream;
    stream << isRevocation;
    stream << std::vector<::mlspp::MLSMessage>{msg};
    return stream.bytes();
}

std::pair<std::vector<uint8_t>, std::vector<uint8_t>> ExternalSender::SplitCommitWelcome(
  std::vector<uint8_t> const& serializedCommitWelcome)
{
    auto buffer = ::mlspp::bytes_ns::bytes(serializedCommitWelcome);
    ::mlspp::tls::istream reader(buffer);

    ::mlspp::MLSMessage commitMsg;
    ::mlspp::Welcome welcomeMsg;
    reader >> commitMsg;
    reader >> welcomeMsg;

    ::mlspp::tls::ostream commitStream;
    commitStream << commitMsg;
    auto commitBuf = commitStream.bytes();

    ::mlspp::tls::ostream welcomeStream;
    welcomeStream << welcomeMsg;
    auto welcomeBuf = welcomeStream.bytes();

    return std::make_pair(commitBuf, welcomeBuf);
}

