TXsheetHandle::TXsheetHandle() : m_zoomFactor(100), m_xsheet(nullptr) {}
//-----------------------------------------------------------------------------
TXsheetHandle::~TXsheetHandle() {}
//-----------------------------------------------------------------------------
TXsheet* TXsheetHandle::getXsheet() const { return m_xsheet; }
//-----------------------------------------------------------------------------
void TXsheetHandle::setXsheet(TXsheet *newXsheet) {
    // Skip if the new sheet is the same as current one
    if (newXsheet == m_xsheet) {
        return;
    }

    // Update the internal reference
    TXsheet* oldXsheet = m_xsheet;
    m_xsheet = newXsheet;

    // If we now have a valid sheet, invalidate its textures and notify listeners
    if (m_xsheet != nullptr) {
        texture_utils::invalidateTextures(m_xsheet);
        emit xsheetSwitched();
    }
}

