// Helper function to test parsing with validation and expected validity flag
template<typename T>
static void ValidateParse(bool expected_validity, const std::string& input_str) {
  bool parsed_ok;
  T parsed_value = sdb::number_utils::Atoi<T>(
    input_str.c_str(), input_str.c_str() + input_str.size(), parsed_ok);

  EXPECT_EQ(expected_validity, parsed_ok);

  if (expected_validity) {
    EXPECT_EQ(input_str, std::to_string(parsed_value));

    // Also verify the unchecked version yields same result
    T unchecked_result = sdb::number_utils::AtoiUnchecked<T>(
      input_str.c_str(), input_str.c_str() + input_str.size());
    EXPECT_EQ(input_str, std::to_string(unchecked_result));
  }
}

// Helper function to test parsing with known expected numeric value
template<typename T>
static void VerifyNumericValue(T expected_val, const std::string& input_str) {
  bool parsed_ok;
  T parsed_val = sdb::number_utils::Atoi<T>(
    input_str.c_str(), input_str.c_str() + input_str.size(), parsed_ok);

  EXPECT_TRUE(parsed_ok);
  EXPECT_EQ(expected_val, parsed_val);

  // Confirm unchecked version matches
  T unchecked_val = sdb::number_utils::AtoiUnchecked<T>(
    input_str.c_str(), input_str.c_str() + input_str.size());
  EXPECT_EQ(expected_val, unchecked_val);
}

