FDisplayClusterDeviceTopBottomBase::FDisplayClusterDeviceTopBottomBase()
{
}

FDisplayClusterDeviceTopBottomBase::~FDisplayClusterDeviceTopBottomBase()
{
}

void FDisplayClusterDeviceTopBottomBase::AdjustViewRect(enum EStereoscopicPass StereoPassType, int32& X, int32& Y, uint32& SizeX, uint32& SizeY) const
{
	const int ViewportIdx = DecodeViewportIndex(StereoPassType);
	const EStereoscopicPass EyePass = DecodeStereoscopicPass(StereoPassType);
	const uint32 ViewId = DecodeViewIndex(StereoPassType);

	// Access current viewport data
	FDisplayClusterRenderViewport& ActiveViewport = RenderViewports[ViewportIdx];

	// Extract viewport rectangle from the active viewport
	const FIntRect& ViewRect = ActiveViewport.GetRect();

	// Compute vertical offset based on eye type
	if (EyePass == EStereoscopicPass::eSSP_LEFT_EYE)
	{
		Y = ViewRect.Min.Y / 2;
	}
	else if (EyePass == EStereoscopicPass::eSSP_RIGHT_EYE)
	{
		Y = SizeY / 2 + ViewRect.Min.Y / 2;
	}

	// Set horizontal position and dimensions
	X = ViewRect.Min.X;
	SizeX = ViewRect.Width();
	SizeY = ViewRect.Height() / 2;

	// Update rendering context with adjusted rectangle
	FDisplayClusterRenderViewContext& Context = ActiveViewport.GetContext(ViewId);
	Context.RenderTargetRect = FIntRect(X, Y, X + SizeX, Y + SizeY);

	// Log adjusted rectangle for debugging
	const FIntRect& AdjustedRect = Context.RenderTargetRect;
	UE_LOG(LogDisplayClusterRender, Verbose, TEXT("Adjusted view rect: ViewportIdx=%d, ViewIndex=%d, [%d,%d - %d,%d]"), 
		ViewportIdx, ViewId, AdjustedRect.Min.X, AdjustedRect.Min.Y, AdjustedRect.Max.X, AdjustedRect.Max.Y);
}

