    // Cloth creation helpers
    JPH::Ref<JPH::SoftBodySharedSettings> generate_cloth(
        JPH::uint grid_width,
        JPH::uint grid_depth,
        float spacing,
        const std::function<float(JPH::uint, JPH::uint)>& inv_mass_func,
        const std::function<JPH::Vec3(JPH::uint, JPH::uint)>& perturbation_func,
        JPH::SoftBodySharedSettings::EBendType bend_type,
        const JPH::SoftBodySharedSettings::VertexAttributes& vertex_attrs
    ) {
        const float offset_x = -0.5f * spacing * (grid_width - 1);
        const float offset_z = -0.5f * spacing * (grid_depth - 1);

        JPH::SoftBodySharedSettings* settings = new JPH::SoftBodySharedSettings;

        for (JPH::uint z = 0; z < grid_depth; ++z) {
            for (JPH::uint x = 0; x < grid_width; ++x) {
                JPH::SoftBodySharedSettings::Vertex v;
                JPH::Vec3 position = perturbation_func(x, z) +
                                     JPH::Vec3(
                                         offset_x + x * spacing,
                                         0.0f,
                                         offset_z + z * spacing
                                     );
                position.StoreFloat3(&v.mPosition);
                v.mInvMass = inv_mass_func(x, z);
                settings->mVertices.push_back(v);
            }
        }

        auto get_vertex_index = [grid_width](JPH::uint x, JPH::uint y) -> JPH::uint {
            return x + y * grid_width;
        };

        for (JPH::uint z = 0; z < grid_depth - 1; ++z) {
            for (JPH::uint x = 0; x < grid_width - 1; ++x) {
                JPH::SoftBodySharedSettings::Face f;
                f.mVertex[0] = get_vertex_index(x, z);
                f.mVertex[1] = get_vertex_index(x, z + 1);
                f.mVertex[2] = get_vertex_index(x + 1, z + 1);
                settings->AddFace(f);

                f.mVertex[1] = get_vertex_index(x + 1, z + 1);
                f.mVertex[2] = get_vertex_index(x + 1, z);
                settings->AddFace(f);
            }
        }

        settings->CreateConstraints(&vertex_attrs, 1, bend_type);
        settings->Optimize();
        return settings;
    }

    JPH::Ref<JPH::SoftBodySharedSettings> create_cloth_with_fixed_corners(
        JPH::uint grid_width, JPH::uint grid_depth, float spacing
    ) {
        auto inv_mass_func = [grid_width, grid_depth](JPH::uint x, JPH::uint z) {
            bool corner = (x == 0 && z == 0) ||
                          (x == grid_width - 1 && z == 0) ||
                          (x == 0 && z == grid_depth - 1) ||
                          (x == grid_width - 1 && z == grid_depth - 1);
            return corner ? 0.0f : 1.0f;
        };

        return ::generate_cloth(
            grid_width,
            grid_depth,
            spacing,
            inv_mass_func,
            [](JPH::uint, JPH::uint) { return JPH::Vec3::sZero(); },
            JPH::SoftBodySharedSettings::EBendType::None,
            { 1.0e-5f, 1.0e-5f, 1.0e-5f }
        );
    }

    JPH::Ref<JPH::SoftBodySharedSettings> create_cloth_cylinder(
        const JPH::SoftBodySharedSettings::EBendType bend_type,
        const JPH::SoftBodySharedSettings::VertexAttributes& vertex_attrs,
        const double radius,
        const double height,
        const int width_count,
        const int height_count
    ) {
        MIRINAE_ASSERT(width_count >= 3);
        MIRINAE_ASSERT(height_count >= 2);

        const auto half_h = height * 0.5;
        auto settings = std::make_unique<JPH::SoftBodySharedSettings>();

        for (int h = 0; h < height_count; ++h) {
            const auto y_pos = height * h / (height_count - 1) - half_h;
            for (int w = 0; w < width_count; ++w) {
                JPH::SoftBodySharedSettings::Vertex v;
                const auto theta = SUNG_TAU * w / width_count;
                const JPH::Vec3 pos(
                    radius * std::cos(theta), y_pos, radius * std::sin(theta)
                );

                if (h >= height_count - 1)
                    v.mInvMass = 0;
                else
                    v.mInvMass = 1;

                pos.StoreFloat3(&v.mPosition);
                settings->mVertices.push_back(v);
            }
        }

        auto get_idx = [width_count, height_count](JPH::uint w, JPH::uint h) -> JPH::uint {
            w = w % width_count;
            h = h % height_count;
            return w + h * width_count;
        };

        for (int h = 0; h < height_count - 1; ++h) {
            for (int w = 0; w < width_count; ++w) {
                JPH::SoftBodySharedSettings::Face f;
                f.mVertex[0] = get_idx(w, h);
                f.mVertex[1] = get_idx(w, h + 1);
                f.mVertex[2] = get_idx(w + 1, h + 1);
                settings->AddFace(f);

                f.mVertex[1] = get_idx(w + 1, h + 1);
                f.mVertex[2] = get_idx(w + 1, h);
                settings->AddFace(f);
            }
        }

        settings->CreateConstraints(&vertex_attrs, 1, bend_type);
        settings->Optimize();
        return settings.release();
    }

