    class BPLayerInterfaceImpl final : public JPH::BroadPhaseLayerInterface {
    public:
        BPLayerInterfaceImpl() {
            mObjectToBroadPhase[PhysicsLayers::STATIC_OBJECT] =
                BroadPhaseLayers::STATIC_LAYER;
            mObjectToBroadPhase[PhysicsLayers::DYNAMIC_OBJECT] =
                BroadPhaseLayers::DYNAMIC_LAYER;
        }

        JPH::uint GetNumBroadPhaseLayers() const override {
            return BroadPhaseLayers::LAYER_COUNT;
        }

        JPH::BroadPhaseLayer GetBroadPhaseLayer(
            JPH::ObjectLayer layer
        ) const override {
            JPH_ASSERT(layer < PhysicsLayers::LAYER_COUNT);
            return mObjectToBroadPhase[layer];
        }

#if defined(JPH_EXTERNAL_PROFILE) || defined(JPH_PROFILE_ENABLED)
        const char* GetBroadPhaseLayerName(
            BroadPhaseLayer layer
        ) const override {
            switch ((BroadPhaseLayer::Type)layer) {
                case (BroadPhaseLayer::Type)BroadPhaseLayers::STATIC_LAYER:
                    return "STATIC";
                case (BroadPhaseLayer::Type)BroadPhaseLayers::DYNAMIC_LAYER:
                    return "DYNAMIC";
                default:
                    JPH_ASSERT(false);
                    return "INVALID";
            }
        }
#endif

    private:
        JPH::BroadPhaseLayer mObjectToBroadPhase[PhysicsLayers::LAYER_COUNT];
    };

    class ObjectVsBroadPhaseLayerFilterImpl
        : public JPH::ObjectVsBroadPhaseLayerFilter {
    public:
        bool ShouldCollide(
            JPH::ObjectLayer obj_layer,
            JPH::BroadPhaseLayer bp_layer
        ) const override {
            switch (obj_layer) {
                case PhysicsLayers::STATIC_OBJECT:
                    return bp_layer == BroadPhaseLayers::DYNAMIC_LAYER;
                case PhysicsLayers::DYNAMIC_OBJECT:
                    return true;
                default:
                    JPH_ASSERT(false);
                    return false;
            }
        }
    };

    class ObjectLayerPairFilterImpl : public JPH::ObjectLayerPairFilter {
    public:
        bool ShouldCollide(
            JPH::ObjectLayer layer1,
            JPH::ObjectLayer layer2
        ) const override {
            switch (layer1) {
                case PhysicsLayers::STATIC_OBJECT:
                    return layer2 == PhysicsLayers::DYNAMIC_OBJECT;
                case PhysicsLayers::DYNAMIC_OBJECT:
                    return true;
                default:
                    JPH_ASSERT(false);
                    return false;
            }
        }
    };

