#ifdef MIRINAE_JOLT_DEBUG_RENDERER
    class DebugRendererImpl : public JPH::DebugRenderer {
    private:
        class BatchImpl : public JPH::RefTargetVirtual {
        public:
            void AddRef() override { ++ref_count_; }
            void Release() override { --ref_count_; }
            void append(const mirinae::DebugMesh::Vertex& v) {
                mesh_.idx_.push_back(mesh_.vtx_.size());
                mesh_.vtx_.push_back(v);
            }
            mirinae::DebugMesh mesh_;
            std::atomic_size_t ref_count_;
        };

    public:
        DebugRendererImpl() {
            this->Initialize();
        }

        void DrawLine(
            const JPH::RVec3& from,
            const JPH::RVec3& to,
            const JPH::Color& color
        ) override {}

        void DrawTriangle(
            const JPH::RVec3& v1,
            const JPH::RVec3& v2,
            const JPH::RVec3& v3,
            const JPH::Color& color,
            const ECastShadow shadow
        ) override {
            if (!debug_renderer_)
                return;
            debug_renderer_->tri(
                ::convert_to_glm_vec3(v1),
                ::convert_to_glm_vec3(v2),
                ::convert_to_glm_vec3(v3),
                ::convert_to_glm_vec4(color.ToVec4())
            );
        }

        void DrawGeometry(
            const JPH::RMat44& model_matrix,
            const JPH::AABox& world_bounds,
            const float lod_scale_sq,
            const JPH::Color& model_color,
            const GeometryRef& geometry,
            const ECullMode cull_mode,
            const ECastShadow shadow,
            const EDrawMode draw_mode
        ) override {
            if (!debug_renderer_)
                return;
            auto ptr = geometry->mLODs[0].mTriangleBatch.GetPtr();
            auto batch = static_cast<const BatchImpl*>(ptr);
            if (!batch)
                return;
            debug_renderer_->mesh(batch->mesh_, ::convert_to_glm_mat4(model_matrix));
        }

        Batch CreateTriangleBatch(
            const Triangle* triangles,
            const int triangle_count
        ) override {
            auto batch = std::make_unique<BatchImpl>();
            for (int i = 0; i < triangle_count; ++i) {
                auto& src_tri = triangles[i];
                for (int j = 0; j < 3; ++j) {
                    mirinae::DebugMesh::Vertex dst_vtx;
                    auto& src_vtx = src_tri.mV[j];
                    dst_vtx.pos_ = ::convert_to_glm_vec3(src_vtx.mPosition);
                    dst_vtx.color_ = ::convert_to_glm_vec4(src_vtx.mColor.ToVec4());
                    batch->append(dst_vtx);
                }
            }
            return batch.release();
        }

        Batch CreateTriangleBatch(
            const Vertex* vertices,
            const int vertex_count,
            const JPH::uint32* indices,
            const int index_count
        ) override {
            auto batch = std::make_unique<BatchImpl>();
            batch->mesh_.vtx_.reserve(vertex_count);
            for (int i = 0; i < vertex_count; ++i) {
                auto& v = batch->mesh_.vtx_.emplace_back();
                v.pos_ = ::convert_to_glm_vec3(vertices[i].mPosition);
                v.color_ = ::convert_to_glm_vec4(vertices[i].mColor.ToVec4());
            }
            batch->mesh_.idx_.assign(indices, indices + index_count);
            return batch.release();
        }

        void DrawText3D(
            const JPH::RVec3& position,
            const JPH::string_view& text,
            const JPH::Color& color,
            const float height
        ) override {}

        mirinae::IDebugRen* debug_renderer_ = nullptr;
    };
#endif

