        void initialize(JPH::BodyInterface& interface) {
            using namespace JPH::literals;
            JPH::BoxShapeSettings floor_shape_settings(
                JPH::Vec3(1000, 20, 1000)
            );
            floor_shape_settings.SetEmbedded();
            auto result = floor_shape_settings.Create();
            floor_shape = result.Get();
            JPH::BodyCreationSettings floor_settings(
                floor_shape,
                JPH::RVec3(0, -18, 0),
                JPH::Quat::sIdentity(),
                JPH::EMotionType::Static,
                ::PhysicsLayers::STATIC_OBJECT
            );
            floor_body = interface.CreateBody(floor_settings);
