    class CharacterController : public mirinae::ICharacterPhysBody {
    public:
        void initialize(
            const mirinae::cpnt::CharacterPhys& phys,
            const mirinae::cpnt::Transform* transform,
            JPH::PhysicsSystem& physics_system
        ) {
            half_height_ = static_cast<float>(phys.height_ * 0.5);
            radius_ = static_cast<float>(phys.radius_);

            JPH::CharacterVirtualSettings settings;
            settings.mShape = new JPH::CapsuleShape(half_height_, radius_);
            settings.mMaxSlopeAngle = JPH::DegreesToRadians(45);
            settings.mSupportingVolume = JPH::Plane(
                JPH::Vec3::sAxisY(), -half_height_ * 0.75f
            );
            settings.mMass = 70;
            settings.mInnerBodyShape = settings.mShape;

            JPH::RVec3 position(0, 0, 0);
            auto rotation = JPH::Quat::sIdentity();

            if (transform) {
                position = ::convert_to_glm_vec3(transform->pos_);
                rotation = ::convert_to_glm_quat(transform->rot_);
            }

            character_ = new JPH::CharacterVirtual(
                &settings, position + this->get_offset_vector(), rotation, &physics_system
            );
        }

        void extended_update(
            float dt,
            JPH::TempAllocatorImpl& temp_allocator,
            JPH::PhysicsSystem& physics_system
        ) {
            if (!character_)
                return;
            character_->ExtendedUpdate(
                static_cast<float>(dt),
                physics_system.GetGravity(),
                update_settings_,
                physics_system.GetDefaultBroadPhaseLayerFilter(PhysicsLayers::DYNAMIC_OBJECT),
                physics_system.GetDefaultLayerFilter(PhysicsLayers::DYNAMIC_OBJECT),
                {},
                {},
                temp_allocator
            );
        }

        void set_linear_velocity(const JPH::RVec3& vel) {
            if (!character_)
                return;
            character_->SetLinearVelocity(vel);
        }

        JPH::CharacterVirtual& get_character() { return *character_; }

        JPH::RVec3 get_world_position() const {
            return character_->GetPosition() - this->get_offset_vector();
        }

    private:
        float get_offset() const { return half_height_ + radius_; }

        JPH::RVec3 get_offset_vector() const {
            return JPH::RVec3(0, this->get_offset(), 0);
        }

        JPH::CharacterVirtual::ExtendedUpdateSettings update_settings_;
        JPH::CharacterVirtual* character_;
        float half_height_ = 0;
        float radius_ = 0;
    };

