namespace {

    class PreSyncMeshTask : public mirinae::DependingTask {
    public:
        void init(
            ::PhysWorldStateFlags& flags,
            entt::registry& registry,
            JPH::BodyInterface& body_interface
        ) {
            state_flags_ = &flags;
            registry_ = &registry;
            body_interface_ = &body_interface;
        }

        void prepare() {
            this->set_size(registry_->view<::cpnt::MeshBodyComponent>().size());
        }

        void ExecuteRange(enki::TaskSetPartition range, uint32_t tid) override {
            namespace cpnt = mirinae::cpnt;
            bool preparing = false;
            bool completed = false;

            if (!registry_ || !body_interface_)
                return;

            auto view = registry_->view<::cpnt::MeshBodyComponent>();
            auto begin = view.begin() + range.start;
            auto end = view.begin() + range.end;

            for (auto it = begin; it != end; ++it) {
                entt::entity entity = *it;
                auto& component = view.get<::cpnt::MeshBodyComponent>(entity);

                if (component.ready_)
                    continue;

                auto transform = registry_->try_get<cpnt::Transform>(entity);
                auto model = registry_->try_get<cpnt::MdlActorStatic>(entity);

                if (component.try_initialize(model, transform, *body_interface_)) {
                    completed = true;
                } else {
                    preparing = true;
                }
            }

            if (preparing)
                state_flags_->no_simulation_.store(true);
            if (completed)
                state_flags_->need_optimization_.store(true);
        }

    private:
        ::PhysWorldStateFlags* state_flags_ = nullptr;
        entt::registry* registry_ = nullptr;
        JPH::BodyInterface* body_interface_ = nullptr;
    };

