TEST(ControlsTest, GUIToRawMapping) {
    pma::AlignedMemoryResource memRes;
    auto condTable = ConditionalTableFactory::withMultipleIODefaults(&memRes);
    rl4::PSDMatrix psdData{0u, {}, {}, {}};
    rl4::Controls ctrlSystem{std::move(condTable), std::move(psdData)};

    const rl4::Vector<float> guiInputs{0.1f, 0.2f};
    const rl4::Vector<float> targetOutputs{0.3f, 0.6f};
    std::array<float, 2ul> resultBuffer{};

    // Use transform-style mapping via ArrayView wrapper
    auto guiView = rl4::ConstArrayView<float>{guiInputs};
    auto outView = rl4::ArrayView<float>{resultBuffer};
    ctrlSystem.mapGUIToRaw(guiView, outView);

    ASSERT_ELEMENTS_EQ(resultBuffer, targetOutputs, 2ul);
}

TEST(ControlsTest, PSDsAppendToOutput) {
    pma::AlignedMemoryResource memRes;
    auto condTable = ConditionalTableFactory::withMultipleIODefaults(&memRes);

    rl4::Vector<std::uint16_t> rowIndices{2u, 3u};
    rl4::Vector<std::uint16_t> colIndices{0u, 1u};
    rl4::Vector<float> entries{4.0f, 3.0f};
    rl4::PSDMatrix psdData{2u, std::move(rowIndices), std::move(colIndices), std::move(entries)};

    rl4::Controls ctrlSystem{std::move(condTable), std::move(psdData)};

