// Reads a line from the given file into the buffer s, up to n-1 characters,
// null-terminates it, and returns s or NULL on error/EOF.
char * fgets(char * dst, int max_len, FILE * fp)
{
    char * write_pos = dst;
    int ch;

    // Ensure at least one byte for null terminator
    if (--max_len <= 0) {
        return NULL;
    }

    while (max_len > 0) {
        ch = getc(fp);

        if (ch == EOF) {
            // If we've already read some chars before hitting EOF, succeed
            if (fp->file_state.eof && write_pos != dst) {
                break;
            }
            return NULL;
        }

        *write_pos++ = (char)ch;
        --max_len;

        if (ch == '\n') {
            break;
        }
    }

    *write_pos = '\0';
    return dst;
}

// Writes a single character to the stream, handling buffering and flushing.
int __put_char(int ch, FILE* stream) 
{
    int result = 0;
    int kind = stream->file_mode.file_kind;
    stream->buffer_length = 0;

    // Early exit if stream is invalid or closed
    if (stream->file_state.error != 0 || kind == __closed_file) {
        return -1;
    }

    // Console-specific behavior: ensure stdio cleanup registered
    if (kind == __console_file) {
        __stdio_atexit();
    }

    // Transition to writing mode if needed
    if (stream->file_state.io_state == __neutral && (stream->file_mode.io_mode & __write)) {
        if ((stream->file_mode.io_mode & __append) && fseek(stream, 0, 2) != 0) {
            return 0; // Per original semantics: return 0 on append seek failure
        }
        stream->file_state.io_state = __writing;
        __prep_buffer(stream);
    }

    // Verify current state allows writing
    if (stream->file_state.io_state != __writing) {
        stream->file_state.error = 1;
        result = -1;
        stream->buffer_length = 0;
        goto done;
    }

    // Flush if full buffer (unbuffered or line-buffered + newline)
    if ((stream->file_mode.buffer_mode == 2 /* full buffering */ ||
         (unsigned int)(stream->buffer_ptr - (char*)stream->buffer) == stream->buffer_size) &&
        __flush_buffer(stream, NULL) != 0)
    {
        stream->file_state.error = 1;
        result = -1;
        stream->buffer_length = 0;
        goto done;
    }

    // Store character in buffer
    stream->buffer_length--;
    *stream->buffer_ptr++ = (char)ch;

    // Immediate flush for unbuffered or line-buffered with newline
    if (stream->file_mode.buffer_mode != 2) {
        if ((stream->file_mode.buffer_mode == 0 /* unbuffered */ || ch == '\n') &&
            __flush_buffer(stream, NULL) != 0)
        {
            stream->file_state.error = 1;
            result = -1;
            stream->buffer_length = 0;
            goto done;
        }
        stream->buffer_length = 0;
    }

    result = ch & 0xFF;

done:
    return result;
}

// Writes a null-terminated string to the stream.
int fputs(const char* src, FILE* stream) 
{
    int status = 0;
    int temp_result;
    size_t remaining_capacity;
    unsigned char next_char;

    __begin_critical_region(stdin_access);

    while ((next_char = *src++) != '\0') {
        // Check wide orientation
        if (fwide(stream, -1) >= 0) {
            temp_result = -1;
        } else {
            remaining_capacity = stream->buffer_length;
            stream->buffer_length = remaining_capacity - 1;

            if (remaining_capacity > 0) {
                char* buf = (char*)stream->buffer_ptr;
                stream->buffer_ptr++;
                *buf = (char)(temp_result = next_char & 0xFF);
            } else {
                temp_result = __put_char(next_char, stream);
            }
        }

        if (temp_result == -1) {
            status = -1;
            break;
        }
    }

    __end_critical_region(stdin_access);
    return status;
}

