// Consume one Soul Food item if available, applying its effects.
// Returns true only when an item was successfully consumed.
bool consumeOneSoulFood()
{
  if (!g_app.inventory.hasItem(ITEM_SOUL_FOOD))
    return false;

  pet.hunger = constrain(pet.hunger + 20, 0, 100);
  pet.happiness = constrain(pet.happiness + 10, 0, 100);
  pet.energy = constrain(pet.energy + 10, 0, 100);

  g_app.inventory.removeItem(ITEM_SOUL_FOOD, 1);
  pet.lastFedTime = millis();
  saveManagerMarkDirty();

  return true;
}

// Get the display label for the current food type
static const char *getFoodName()
{
  const char *label = g_app.inventory.getItemLabelForType(ITEM_SOUL_FOOD);
  return (label && label[0] != '\0') ? label : "Soul Food";
}

// Display a message indicating no food is available
static void notifyNoFood()
{
  char buffer[48];
  snprintf(buffer, sizeof(buffer), "No %s!", getFoodName());
  ui_showMessage(buffer);
}

// Automatically feed until hunger is maxed or out of items
int feedUntilHungryIsZero()
{
  int count = 0;
  while (pet.hunger < 100)
  {
    if (!consumeOneSoulFood())
      break;
    count++;
    if (count >= 99) // Prevent infinite loop in case of bugs
      break;
  }
  return count;
}

// Handle user selection from the feed menu
void feedUseSelected()
{
  if (feedMenuIndex == 0)
  {
    if (pet.hunger >= 100)
    {
      ui_showMessage("Already full!");
      return;
    }

    if (!consumeOneSoulFood())
      notifyNoFood();
    else
    {
      char msg[48];
      snprintf(msg, sizeof(msg), "Ate %s!", getFoodName());
      ui_showMessage(msg);
    }
    return;
  }

  if (feedMenuIndex == 1)
  {
    if (pet.hunger >= 100)
    {
      ui_showMessage("Already full!");
      return;
    }

    int amount = feedUntilHungryIsZero();
    if (amount == 0)
      notifyNoFood();
    else
    {
      String result = "Ate x" + String(amount);
      ui_showMessage(result.c_str());
    }
    return;
  }
}

