	void HotkeySystem::RegisterCommands()
	{
		auto& cmd_map = Commands::GetCommands();
		for (auto iter = cmd_map.begin(); iter != cmd_map.end(); ++iter)
		{
			CommandLink link;
			m_CommandHotkeys.insert(std::make_pair(iter->first, link));
		}

		// Ensure chat helper always has default binding
		auto it = m_CommandHotkeys.find("chathelper"_J);
		if (it != m_CommandHotkeys.end())
		{
			it->second.m_Chain.clear();
			it->second.m_Chain.push_back(0x54);
		}
	}

	bool HotkeySystem::ListenAndApply(int& out_key, const std::vector<int>& blacklist)
	{
		// Inline blacklisted check instead of lambda
		for (int vk_code = 0; vk_code < VK_OEM_CLEAR; ++vk_code)
		{
			if ((GetKeyState(vk_code) & 0x8000) && vk_code != 1)
			{
				bool is_blacklisted = false;
				for (size_t i = 0; i < blacklist.size(); ++i)
				{
					if (blacklist[i] == vk_code)
					{
						is_blacklisted = true;
						break;
					}
				}
				if (!is_blacklisted)
				{
					out_key = vk_code;
					return true;
				}
			}
		}
		return false;
	}

	std::string HotkeySystem::GetHotkeyLabel(int vk_code)
	{
		char key_name[32] = { 0 };
		int scan_code = MapVirtualKey(vk_code, MAPVK_VK_TO_VSC) << 16;
		GetKeyNameTextA(scan_code, key_name, sizeof(key_name));

		std::string result(key_name);
		if (result.empty())
		{
			result = std::to_string(vk_code);
		}
		return result;
	}

	void HotkeySystem::CreateHotkey(std::vector<int>& chain)
	{
		int pressed_key = 0;
		if (ListenAndApply(pressed_key, chain))
		{
			MarkStateDirty();

			bool already_present = false;
			for (size_t i = 0; i < chain.size(); ++i)
			{
				if (chain[i] == pressed_key)
				{
					already_present = true;
					break;
				}
			}

			if (!already_present)
			{
				chain.push_back(pressed_key);
			}
		}
	}

	void HotkeySystem::RunScriptImpl()
	{
		while (g_Running)
		{
			if (GetForegroundWindow() == *Pointers.Hwnd &&
				!HUD::IS_PAUSE_MENU_ACTIVE() &&
				!HUD::IS_SOCIAL_CLUB_ACTIVE() &&
				!m_BeingModified &&
				!GUI::IsUsingKeyboard())
			{
				for (auto iter = m_CommandHotkeys.begin(); iter != m_CommandHotkeys.end(); ++iter)
				{
					const auto& hash = iter->first;
					auto& link = iter->second;

					if (link.m_Chain.empty())
						continue;

					bool all_pressed = true;
					for (size_t i = 0; i < link.m_Chain.size(); ++i)
					{
						if (!(GetAsyncKeyState(link.m_Chain[i]) & 0x8000))
						{
							all_pressed = false;
							break;
						}
					}

					if (all_pressed)
					{
						auto now = std::chrono::system_clock::now();
						if (now - m_LastHotkeyTriggerTime > 100ms)
						{
							auto command = Commands::GetCommand(hash);
							if (command)
							{
								if (hash != "chathelper"_J)
								{
									command->Call();
								}
								else
								{
									FiberPool::Push([cmd = command] {
										cmd->Call();
									});
								}
							}
							m_LastHotkeyTriggerTime = now;
						}
					}
				}
			}
			ScriptMgr::Yield();
		}
	}

	void HotkeySystem::RunScript()
	{
		g_HotkeySystem.RunScriptImpl();
	}

	void HotkeySystem::SaveStateImpl(nlohmann::json& state)
	{
		for (auto iter = m_CommandHotkeys.begin(); iter != m_CommandHotkeys.end(); ++iter)
		{
			uint32_t hash_val = iter->first;
			const auto& chain = iter->second.m_Chain;

			std::string key_str = std::to_string(hash_val);

			if (!chain.empty())
			{
				state[key_str] = chain;
			}
			else if (state.contains(key_str))
			{
				state.erase(key_str);
			}
		}
	}

	void HotkeySystem::LoadStateImpl(const nlohmann::json& state)
	{
		for (auto iter = state.begin(); iter != state.end(); ++iter)
		{
			try
			{
				uint32_t hash_val = static_cast<uint32_t>(std::stoul(iter.key()));
				if (m_CommandHotkeys.find(hash_val) != m_CommandHotkeys.end())
				{
					m_CommandHotkeys[hash_val].m_Chain = iter.value().get<std::vector<int>>();
				}
			}
			catch (const std::exception&)
			{
				// Skip invalid keys
			}
		}
	}

	void HotkeySystem::SetBeingModifed(bool being_modified)
	{
		g_HotkeySystem.m_BeingModified = being_modified;
	}
}

#include "decoders/processor/operators/cpu/debayer_ahd.hpp"

#include <opencv2/calib3d.hpp>
#include <opencv2/core.hpp>
#include <opencv2/core/mat.hpp>
#include <opencv2/core/types.hpp>
#include <opencv2/highgui.hpp>
#include <opencv2/imgproc.hpp>
#include <opencv2/opencv.hpp>

#include <vector>
#include <cmath>

namespace puerhlab {
namespace CPU {

void BayerRGGB2RGB_AHD(cv::Mat& bayer) {
    // Pattern mapping: [R, Gr, B, Gb] → indices 0–3 based on (row%2, col%2)
    static const int pattern_map[4] = {0, 1, 3, 2};

    const int height = bayer.rows;
    const int width  = bayer.cols;

    // Initialize per-channel masks as float matrices
    cv::Mat1f mask_red(height, width, 0.0f);
    cv::Mat1f mask_green_r(height, width, 0.0f);
    cv::Mat1f mask_green_b(height, width, 0.0f);
    cv::Mat1f mask_blue(height, width, 0.0f);

    // Build masks by scanning pixel positions explicitly
    for (int row = 0; row < height; ++row) {
        for (int col = 0; col < width; ++col) {
            int idx = pattern_map[((row % 2) << 1) | (col % 2)];
            switch (idx) {
                case 0:
                    mask_red(row, col) = 1.0f;
                    break;
                case 1:
                    mask_green_r(row, col) = 1.0f;
                    break;
                case 2:
                    mask_blue(row, col) = 1.0f;
                    break;
                case 3:
                    mask_green_b(row, col) = 1.0f;
                    break;
            }
        }
    }

    cv::Mat1f raw_data = bayer.clone();

    // Intermediate green channel estimate (G_final)
    cv::Mat1f G_estimated = bayer.clone();

#pragma omp parallel for collapse(2) schedule(static)
    for (int y = 2; y < height - 2; ++y) {
        for (int x = 2; x < width - 2; ++x) {
            if (mask_red(y, x) > 0.5f || mask_blue(y, x) > 0.5f) {
                const float center_val = raw_data(y, x);
                const float left       = raw_data(y, x - 1);
                const float right      = raw_data(y, x + 1);
                const float up         = raw_data(y - 1, x);
                const float down       = raw_data(y + 1, x);
                const float left2      = raw_data(y, x - 2);
                const float right2     = raw_data(y, x + 2);
                const float up2        = raw_data(y - 2, x);
                const float down2      = raw_data(y + 2, x);

                const float h_average = 0.5f * (left + right);
                const float v_average = 0.5f * (up + down);
                const float h_diff    = 0.25f * (2.0f * center_val - left2 - right2);
                const float v_diff    = 0.25f * (2.0f * center_val - up2 - down2);

                const float Dh = std::abs(left - right);
                const float Dv = std::abs(up - down);

                G_estimated(y, x) = (Dh <= Dv) ? (h_average + h_diff) : (v_average + v_diff);
            }
        }
    }

    // Initialize R and B channels only at their native positions
    cv::Mat1f R_channel = bayer.mul(mask_red);
    cv::Mat1f B_channel = bayer.mul(mask_blue);

    // Interpolate missing R and B values
#pragma omp parallel for collapse(2) schedule(static)
    for (int y = 1; y < height - 1; ++y) {
        for (int x = 1; x < width - 1; ++x) {
            // Fill missing red
            if (mask_red(y, x) <= 0.5f) {
                float r_val = 0.0f;

                if (mask_green_r(y, x) > 0.5f) {
                    // Red estimated from horizontal neighbors on same row
                    float l_diff = R_channel(y, x - 1) - G_estimated(y, x - 1);
                    float r_diff = R_channel(y, x + 1) - G_estimated(y, x + 1);
                    r_val = G_estimated(y, x) + 0.5f * (l_diff + r_diff);
                } else if (mask_green_b(y, x) > 0.5f) {
                    // Red estimated from vertical neighbors on adjacent rows
                    float u_diff = R_channel(y - 1, x) - G_estimated(y - 1, x);
                    float d_diff = R_channel(y + 1, x) - G_estimated(y + 1, x);
                    r_val = G_estimated(y, x) + 0.5f * (u_diff + d_diff);
                } else if (mask_blue(y, x) > 0.5f) {
                    // Red estimated from diagonal neighbors
                    float d1 = R_channel(y - 1, x - 1) - G_estimated(y - 1, x - 1);
                    float d2 = R_channel(y - 1, x + 1) - G_estimated(y - 1, x + 1);
                    float d3 = R_channel(y + 1, x - 1) - G_estimated(y + 1, x - 1);
                    float d4 = R_channel(y + 1, x + 1) - G_estimated(y + 1, x + 1);
                    r_val = G_estimated(y, x) + 0.25f * (d1 + d2 + d3 + d4);
                } else {
                    // Fallback: average all four directions
                    float l_diff = R_channel(y, x - 1) - G_estimated(y, x - 1);
                    float r_diff = R_channel(y, x + 1) - G_estimated(y, x + 1);
                    float u_diff = R_channel(y - 1, x) - G_estimated(y - 1, x);
                    float d_diff = R_channel(y + 1, x) - G_estimated(y + 1, x);
                    r_val = G_estimated(y, x) + 0.25f * (l_diff + r_diff + u_diff + d_diff);
                }
                R_channel(y, x) = r_val;
            }

            // Fill missing blue
            if (mask_blue(y, x) <= 0.5f) {
                float b_val = 0.0f;

                if (mask_green_b(y, x) > 0.5f) {
                    // Blue from horizontal neighbors
                    float l_diff = B_channel(y, x - 1) - G_estimated(y, x - 1);
                    float r_diff = B_channel(y, x + 1) - G_estimated(y, x + 1);
                    b_val = G_estimated(y, x) + 0.5f * (l_diff + r_diff);
                } else if (mask_green_r(y, x) > 0.5f) {
                    // Blue from vertical neighbors
                    float u_diff = B_channel(y - 1, x) - G_estimated(y - 1, x);
                    float d_diff = B_channel(y + 1, x) - G_estimated(y + 1, x);
                    b_val = G_estimated(y, x) + 0.5f * (u_diff + d_diff);
                } else if (mask_red(y, x) > 0.5f) {
                    // Blue from diagonals
                    float d1 = B_channel(y - 1, x - 1) - G_estimated(y - 1, x - 1);
                    float d2 = B_channel(y - 1, x + 1) - G_estimated(y - 1, x + 1);
                    float d3 = B_channel(y + 1, x - 1) - G_estimated(y + 1, x - 1);
                    float d4 = B_channel(y + 1, x + 1) - G_estimated(y + 1, x + 1);
                    b_val = G_estimated(y, x) + 0.25f * (d1 + d2 + d3 + d4);
                } else {
                    // Fallback average
                    float l_diff = B_channel(y, x - 1) - G_estimated(y, x - 1);
                    float r_diff = B_channel(y, x + 1) - G_estimated(y, x + 1);
                    float u_diff = B_channel(y - 1, x) - G_estimated(y - 1, x);
                    float d_diff = B_channel(y + 1, x) - G_estimated(y + 1, x);
                    b_val = G_estimated(y, x) + 0.25f * (l_diff + r_diff + u_diff + d_diff);
                }
                B_channel(y, x) = b_val;
            }
        }
    }

    // Combine into final RGB image
    std::vector<cv::Mat> rgb_channels = {R_channel, G_estimated, B_channel};
    cv::merge(rgb_channels, bayer);
}

