#include "KernelRewriter.h"
#include <clang/astmatchers/ASTMatchers.h>
#include <clang/astmatchers/ASTMatchFinder.h>
#include <clang/AST/TextNodeDumper.h>

KernelRewriter::KernelRewriter(clang::ASTContext* ctx, std::vector<PendingEdit>& edits)
	: m_pASTContext(ctx), m_PendingEdits(edits) {}

std::optional<std::string> KernelRewriter::glslTypeForVecBase(clang::QualType qt) {
	qt = qt.getNonReferenceType().getUnqualifiedType().getCanonicalType();
	const auto* recType = qt->getAs<clang::RecordType>();
	if (!recType) return std::nullopt;

	const auto* recordDecl = recType->getAsCXXRecordDecl();
	if (!recordDecl) return std::nullopt;

	const auto* specDecl = llvm::dyn_cast<clang::ClassTemplateSpecializationDecl>(recordDecl);
	if (!specDecl) return std::nullopt;

	const auto* primaryTemplate = specDecl->getSpecializedTemplate();
	if (!primaryTemplate || primaryTemplate->getQualifiedNameAsString() != "tc::vec_base")
		return std::nullopt;

	const auto& templateArgs = specDecl->getTemplateArgs().asArray();
	if (templateArgs.size() != 2) return std::nullopt;

	if (templateArgs[0].getKind() != clang::TemplateArgument::Type ||
		templateArgs[1].getKind() != clang::TemplateArgument::Integral)
		return std::nullopt;

	clang::QualType elemType = templateArgs[0].getAsType();
	unsigned vecSize = static_cast<unsigned>(templateArgs[1].getAsIntegral().getLimitedValue());

	if (vecSize < 2 || vecSize > 4) return std::nullopt;

	auto scalarGLSL = glslTypeForElement(elemType);
	if (!scalarGLSL) return std::nullopt;

	std::string prefix;
	const std::string& baseScalar = *scalarGLSL;
	if (baseScalar == "float")   prefix = "vec";
	else if (baseScalar == "double") prefix = "dvec";
	else if (baseScalar == "int")    prefix = "ivec";
	else if (baseScalar == "uint")   prefix = "uvec";
	else if (baseScalar == "bool")   prefix = "bvec";
	else return std::nullopt;

	return prefix + std::to_string(vecSize);
}

std::optional<std::string> KernelRewriter::glslTypeForElement(clang::QualType elemType) {
	elemType = elemType.getCanonicalType();

	if (elemType->isBooleanType()) return std::string("bool");
	if (elemType->isUnsignedIntegerType()) return std::string("uint");
	if (elemType->isIntegerType()) return std::string("int");
	if (elemType->isFloatingType()) return std::string("float");
	if (elemType->isDoubleType()) return std::string("double");

	return glslTypeForVecBase(elemType);
}

GLSLDataType KernelRewriter::getGLSLDataType(clang::QualType elemType) {
	elemType = elemType.getCanonicalType();

	if (elemType->isBooleanType()) return GLSLDataType::BOOL;
	if (elemType->isUnsignedIntegerType()) return GLSLDataType::UINT;
	if (elemType->isIntegerType()) return GLSLDataType::INT;
	if (elemType->isDoubleType()) return GLSLDataType::DOUBLE;
	if (elemType->isFloatingType()) return GLSLDataType::FLOAT;

	return GLSLDataType::OTHER;
}

std::string KernelRewriter::getGLSLDataTypeAsString(GLSLDataType type) {
	switch (type) {
	case GLSLDataType::BOOL: return "bool";
	case GLSLDataType::INT: return "int";
	case GLSLDataType::UINT: return "uint";
	case GLSLDataType::FLOAT: return "float";
	case GLSLDataType::DOUBLE: return "double";
	default: return "other";
	}
}

unsigned int KernelRewriter::getGSLDataTypeRank(GLSLDataType type) {
	switch (type) {
	case GLSLDataType::BOOL: return 0;
	case GLSLDataType::INT: return 1;
	case GLSLDataType::UINT: return 2;
	case GLSLDataType::FLOAT: return 3;
	case GLSLDataType::DOUBLE: return 4;
	default: return 0;
	}
}

std::optional<std::string> KernelRewriter::getUnqualifiedEnumType(const clang::TemplateArgument& ta) {
	llvm::APSInt val = ta.getAsIntegral();
	clang::QualType enumQT = ta.getIntegralType();

	if (const clang::EnumType* ET = enumQT->getAs<clang::EnumType>()) {
		const clang::EnumDecl* ED = ET->getDecl();
		for (const clang::EnumConstantDecl* EC : ED->enumerators()) {
			if (EC->getInitVal() == val) {
				return EC->getName().str();
			}
		}
	}
	return {};
}

bool KernelRewriter::isInNamespace(const clang::NamedDecl* ND, llvm::StringRef NS) {
	const clang::DeclContext* DC = ND->getDeclContext();
	while (DC) {
		if (const auto* NSD = llvm::dyn_cast<clang::NamespaceDecl>(DC)) {
			if (NSD->getName() == NS) return true;
		}
		DC = DC->getParent();
	}
	return false;
}

std::string KernelRewriter::printTypeNoNS(clang::QualType& qt) {
	clang::PrintingPolicy policy(m_pASTContext->getLangOpts());
	policy.SuppressScope = true;
	policy.SuppressUnwrittenScope = true;
	return qt.getAsString(policy);
}

bool KernelRewriter::rewriteBufferBinding(const clang::FieldDecl* FD) {
	using namespace clang;
	const SourceManager& SM = m_pASTContext->getSourceManager();
	const QualType QT = FD->getType();
	const TemplateSpecializationType* TST = QT->getAs<TemplateSpecializationType>();
	if (!TST) return true;

	QualType elemType;
	unsigned bindingIdx = 0, setIdx = 0;

	if (const auto* CTSDecl = dyn_cast<ClassTemplateSpecializationDecl>(
		TST->getAsRecordDecl())) {
		const auto& Args = CTSDecl->getTemplateArgs();
		if (Args.size() >= 3) {
			elemType = Args[0].getAsType();
			if (Args[1].getKind() == clang::TemplateArgument::Integral)
				bindingIdx = static_cast<unsigned>(Args[1].getAsIntegral().getZExtValue());
			if (Args[2].getKind() == clang::TemplateArgument::Integral)
				setIdx = static_cast<unsigned>(Args[2].getAsIntegral().getZExtValue());

			auto glslElemOpt = glslTypeForElement(elemType);
			std::string glslElem = glslElemOpt ? *glslElemOpt : typeNameNoScope(elemType, *m_pASTContext);
			std::string varName = FD->getNameAsString();

			std::string glslDecl = "layout(set = " + std::to_string(setIdx) +
				", binding = " + std::to_string(bindingIdx) + ") buffer _" + varName + "Layout { "
				+ glslElem + " " + varName + "[]; };";

			SourceLocation endLoc = Lexer::getLocForEndOfToken(
				FD->getSourceRange().getEnd(), 0, SM, m_pASTContext->getLangOpts());
			SourceRange fullRange(FD->getSourceRange().getBegin(), endLoc);

			m_PendingEdits.emplace_back(PendingEdit{ fullRange, glslDecl });
			return false;
		}
	}
	return true;
}

bool KernelRewriter::VisitFieldDecl(clang::FieldDecl* pField) {
	if (checkBufferBinding(pField)) {
		rewriteBufferBinding(pField);
	} else if (checkImageBinding(pField)) {
		rewriteImageBinding(pField);
	} else if (checkUniformField(pField)) {
		rewriteUniform(pField);
	} else if (checkStdArrayField(pField)) {
		rewriteStdArray(pField);
	} else {
		rewriteField(pField);
	}
	return true;
}

bool KernelRewriter::VisitFunctionDecl(clang::FunctionDecl* pFunc) {
	if (pFunc->getNameAsString().starts_with("_")) return false;

	clang::QualType retType = pFunc->getReturnType();
	auto glslRet = glslTypeForElement(retType);
	if (glslRet.has_value()) {
		m_PendingEdits.emplace_back(PendingEdit{
			pFunc->getReturnTypeSourceRange(),
			glslRet.value()
		});
	}
	return true;
}

bool KernelRewriter::checkBufferBinding(const clang::FieldDecl* pField) {
	using namespace clang::ast_matchers;
	auto matcher = fieldDecl(
		hasType(qualType(hasDeclaration(
			classTemplateSpecializationDecl(hasName("BufferBinding"))
		)))
	).bind("bufBind");

	auto matches = match(matcher, *pField, *m_pASTContext);
	return !matches.empty();
}

bool KernelRewriter::rewriteUniform(const clang::FieldDecl* FD) {
	using namespace clang;
	const SourceManager& SM = m_pASTContext->getSourceManager();
	const QualType QT = FD->getType();
	const TemplateSpecializationType* TST = QT->getAs<TemplateSpecializationType>();
	if (!TST) return true;

	if (const auto* CTSDecl = dyn_cast<ClassTemplateSpecializationDecl>(
		TST->getAsRecordDecl())) {
		const auto& Args = CTSDecl->getTemplateArgs();
		if (Args.size() >= 2) {
			QualType elemType = Args[0].getAsType();
			auto glslElemOpt = glslTypeForElement(elemType);
			if (!glslElemOpt) return true;

			std::string glslElem = *glslElemOpt;
			unsigned locationIdx = 0;
			if (Args[1].getKind() == clang::TemplateArgument::Integral)
				locationIdx = static_cast<unsigned>(Args[1].getAsIntegral().getZExtValue());

			std::string varName = FD->getNameAsString();
			std::string uniformDecl = "layout(location = " + std::to_string(locationIdx) +
				") uniform " + glslElem + " " + varName + ";";

			SourceLocation endLoc = Lexer::getLocForEndOfToken(
				FD->getSourceRange().getEnd(), 0, SM, m_pASTContext->getLangOpts());
			SourceRange fullRange(FD->getSourceRange().getBegin(), endLoc);

			m_PendingEdits.emplace_back(PendingEdit{ fullRange, uniformDecl });
			return false;
		}
	}
	return true;
}

bool KernelRewriter::checkStdArrayField(const clang::FieldDecl* pField) {
	using namespace clang::ast_matchers;
	auto matcher = fieldDecl(
		hasType(classTemplateSpecializationDecl(hasName("::std::array")))
	);

	auto matches = match(matcher, *pField, *m_pASTContext);
	return !matches.empty();
}

bool KernelRewriter::rewriteStdArray(const clang::FieldDecl* pField) {
	const QualType QT = pField->getType();
	const TemplateSpecializationType* TST = QT->getAs<TemplateSpecializationType>();
	if (!TST) return true;

	if (const auto* CTSDecl = dyn_cast<ClassTemplateSpecializationDecl>(
		TST->getAsRecordDecl())) {
		const auto& Args = CTSDecl->getTemplateArgs();
		QualType elemType = Args[0].getAsType();
		unsigned size = 0;
		if (Args[1].getKind() == clang::TemplateArgument::Integral)
			size = static_cast<unsigned>(Args[1].getAsIntegral().getZExtValue());

		auto glslTypeOpt = glslTypeForElement(elemType);
		std::string arrayType = glslTypeOpt ? *glslTypeOpt : elemType.getAsString();

		std::string replacement = "const " + arrayType + " " +
			pField->getDeclName().getAsString() + "[" + std::to_string(size) + "] = " +
			arrayType + "[" + std::to_string(size) + "]";

		SourceManager& sm = m_pASTContext->getSourceManager();
		clang::SourceLocation B = sm.getSpellingLoc(pField->getLocation());
		clang::SourceLocation E = Lexer::getLocForEndOfToken(B, 1, sm, m_pASTContext->getLangOpts());
		SourceRange sr{ pField->getBeginLoc(), E };

		m_PendingEdits.emplace_back(PendingEdit{ sr, replacement });
	}
	return true;
}

bool KernelRewriter::VisitInitListExpr(clang::InitListExpr* pInitList) {
	SourceLocation bl = pInitList->getLBraceLoc();
	SourceLocation br = pInitList->getRBraceLoc();

	if (pInitList->isSemanticForm()) return true;
	if (bl.isInvalid() || br.isInvalid()) {
		llvm::errs() << "Invalid braces\n";
		return true;
	}

	m_PendingEdits.emplace_back(PendingEdit{ bl, "(" });
	m_PendingEdits.emplace_back(PendingEdit{ br, ")" });
	return true;
}

bool KernelRewriter::VisitCXXMemberCallExpr(clang::CXXMemberCallExpr* pMemberCall) {
	using namespace clang::ast_matchers;
	auto matcher = cxxMemberCallExpr(
		callee(cxxMethodDecl(
			hasName("size"),
			ofClass(classTemplateSpecializationDecl(
				hasName("std::array")
			).bind("arrSpec"))
		))
	).bind("call");

	auto matches = match(matcher, *pMemberCall, *m_pASTContext);
	if (!matches.empty()) {
		const auto* arrSpec = matches[0].getNodeAs<clang::ClassTemplateSpecializationDecl>("arrSpec");
		const auto& args = arrSpec->getTemplateArgs();
		if (args.size() >= 2 && args[1].getKind() == clang::TemplateArgument::Integral) {
			unsigned size = static_cast<unsigned>(args[1].getAsIntegral().getZExtValue());
			m_PendingEdits.emplace_back(PendingEdit{
				pMemberCall->getSourceRange(),
				std::to_string(size)
			});
		}
	}
	return true;
}

bool KernelRewriter::rewriteField(const clang::FieldDecl* pField) {
	if (pField->getNameAsString() == "local_size") return true;

	if (auto* TSI = pField->getTypeSourceInfo()) {
		TypeLoc TL = TSI->getTypeLoc();

		if (auto ETL = TL.getAs<ElaboratedTypeLoc>()) {
			if (auto Q = ETL.getQualifierLoc()) {
				m_PendingEdits.emplace_back(PendingEdit{ Q.getSourceRange(), "" });
				return true;
			}
		}
		if (auto DT = TL.getAs<DependentNameTypeLoc>()) {
			if (auto Q = DT.getQualifierLoc()) {
				m_PendingEdits.emplace_back(PendingEdit{ Q.getSourceRange(), "" });
				return true;
			}
		}
		if (auto DTS = TL.getAs<DependentTemplateSpecializationTypeLoc>()) {
			if (auto Q = DTS.getQualifierLoc()) {
				m_PendingEdits.emplace_back(PendingEdit{ Q.getSourceRange(), "" });
				return true;
			}
		}
	}
	return true;
}

bool KernelRewriter::checkUniformField(clang::FieldDecl* pField) {
	using namespace clang::ast_matchers;
	auto matcher = fieldDecl(
		hasType(qualType(hasDeclaration(
			classTemplateSpecializationDecl(hasName("Uniform"))
		)))
	);

	auto matches = match(matcher, *pField, *m_pASTContext);
	return !matches.empty();
}

bool KernelRewriter::rewriteImageBinding(const clang::FieldDecl* FD) {
	const SourceManager& SM = m_pASTContext->getSourceManager();
	const QualType QT = FD->getType();
	const TemplateSpecializationType* TST = QT->getAs<TemplateSpecializationType>();
	if (!TST) return true;

	if (const auto* CTSDecl = dyn_cast<ClassTemplateSpecializationDecl>(
		TST->getAsRecordDecl())) {
		const auto& Args = CTSDecl->getTemplateArgs();
		if (Args.size() >= 5) {
			auto imageFormatOpt = getUnqualifiedEnumType(Args[0]);
			auto dimensionOpt = getUnqualifiedEnumType(Args[1]);
			if (!imageFormatOpt || !dimensionOpt) return true;

			unsigned bindingIdx = 0, setIdx = 0;
			if (Args[3].getKind() == clang::TemplateArgument::Integral)
				bindingIdx = static_cast<unsigned>(Args[3].getAsIntegral().getZExtValue());
			if (Args[4].getKind() == clang::TemplateArgument::Integral)
				setIdx = static_cast<unsigned>(Args[4].getAsIntegral().getZExtValue());

			std::string varName = FD->getNameAsString();
			const ImageFormatDescriptor& desc = m_ImageFormats.at(imageFormatOpt.value());
			std::string glsl = "layout(binding=" + std::to_string(bindingIdx) +
				"," + desc.imageIdentifier + ") uniform " +
				m_TypePrefix.at(desc.scalar) + "image" + m_DimensionSuffix.at(dimensionOpt.value()) +
				" " + varName;

			SourceLocation endLoc = Lexer::getLocForEndOfToken(
				FD->getSourceRange().getEnd(), 1, SM, m_pASTContext->getLangOpts());
			SourceRange fullRange(FD->getSourceRange().getBegin(), endLoc);

			m_PendingEdits.emplace_back(PendingEdit{ fullRange, glsl });
			return false;
		}
	}
	return true;
}

bool KernelRewriter::checkImageBinding(const clang::FieldDecl* pField) {
	using namespace clang::ast_matchers;
	auto matcher = fieldDecl(
		hasType(qualType(hasDeclaration(
			classTemplateSpecializationDecl(hasName("ImageBinding"))
		)))
	);

	auto matches = match(matcher, *pField, *m_pASTContext);
	return !matches.empty();
}

bool KernelRewriter::VisitVarDecl(clang::VarDecl* pVar) {
	clang::QualType type = pVar->getType();
	auto glslType = glslTypeForElement(type);
	if (glslType.has_value()) {
		if (auto* TSI = pVar->getTypeSourceInfo()) {
			clang::SourceRange typeRange = TSI->getTypeLoc().getSourceRange();
			if (typeRange.isValid()) {
				m_PendingEdits.emplace_back(PendingEdit{ typeRange, glslType.value() });
			}
		}
	}
	return true;
}

bool KernelRewriter::VisitDeclRefExpr(clang::DeclRefExpr* pRef) {
	if (pRef->getQualifier()) {
		if (pRef->getDecl()) {
			auto qualRange = pRef->getQualifierLoc().getSourceRange();
			m_PendingEdits.emplace_back(PendingEdit{ qualRange, "" });
		}
	}
	return true;
}

void KernelRewriter::castTo(clang::Expr* pExpr, GLSLDataType targetCast) {
	if (targetCast == GLSLDataType::OTHER) return;

	clang::SourceRange sr = pExpr->IgnoreParenImpCasts()->getSourceRange();
	std::string castStr;
	switch (targetCast) {
	case GLSLDataType::BOOL:   castStr = "bool"; break;
	case GLSLDataType::INT:    castStr = "int"; break;
	case GLSLDataType::UINT:   castStr = "uint"; break;
	case GLSLDataType::FLOAT:  castStr = "float"; break;
	case GLSLDataType::DOUBLE: castStr = "double"; break;
	default: return;
	}

	clang::SourceManager& SM = m_pASTContext->getSourceManager();
	const clang::LangOptions& LO = m_pASTContext->getLangOpts();
	auto exprText = Lexer::getSourceText(CharSourceRange::getTokenRange(sr), SM, LO);

	PendingEdit before{
		clang::SourceRange{sr.getBegin(), sr.getBegin()},
		castStr + "( ", true
	};
	clang::SourceLocation endLoc = Lexer::getLocForEndOfToken(sr.getEnd(), 0, SM, LO);
	PendingEdit after{
		clang::SourceRange{endLoc, endLoc},
		" )", true, true
	};

	m_PendingEdits.emplace_back(before);
	m_PendingEdits.emplace_back(after);
}

bool KernelRewriter::VisitImplicitCastExpr(clang::ImplicitCastExpr* pImplicitCast) {
	auto subExpr = pImplicitCast->getSubExpr();
	clang::QualType srcType = subExpr->getType()->getCanonicalTypeUnqualified();
	clang::QualType dstType = pImplicitCast->getType()->getCanonicalTypeUnqualified();

	GLSLDataType src = getGLSLDataType(srcType);
	GLSLDataType dst = getGLSLDataType(dstType);

	unsigned srcRank = getGSLDataTypeRank(src);
	unsigned dstRank = getGSLDataTypeRank(dst);

	if (src != dst && ((srcRank > dstRank) || src == GLSLDataType::BOOL || dst == GLSLDataType::BOOL)) {
		if (src != GLSLDataType::OTHER && dst != GLSLDataType::OTHER) {
			castTo(subExpr, dst);
		}
	}
	return true;
}

bool KernelRewriter::VisitCallExpr(clang::CallExpr* callExpr) {
	if (auto* callee = callExpr->getDirectCallee()) {
		if (isInNamespace(callee, "tc")) {
			if (auto* DRE = llvm::dyn_cast<clang::DeclRefExpr>(
				callExpr->getCallee()->IgnoreParenImpCasts())) {
				if (auto Q = DRE->getQualifierLoc()) {
					m_PendingEdits.emplace_back(PendingEdit{ Q.getSourceRange(), "" });
				}
			}
		}
	}
	return true;
}

bool KernelRewriter::VisitUsingDirectiveDecl(clang::UsingDirectiveDecl* pUsing) {
	m_PendingEdits.emplace_back(PendingEdit{ pUsing->getSourceRange(), "//", true });
	return true;
}

void KernelRewriter::focusedDump(const clang::Stmt* S, clang::ASTContext& Ctx) {
	clang::TextNodeDumper D(llvm::errs(), Ctx, /*ShowColors=*/true);
	D.Visit(S);
}

void KernelRewriter::rewriteVecCtorType(const clang::Expr* E) {
	if (!E) return;

	if (auto* TO = dyn_cast<CXXTemporaryObjectExpr>(E->IgnoreParenImpCasts())) {
		if (auto* TSI = TO->getTypeSourceInfo()) {
			QualType QT = TSI->getType();
			if (auto glsl = glslTypeForVecBase(QT)) {
				TypeLoc TL = TSI->getTypeLoc();
				m_PendingEdits.emplace_back(PendingEdit{ TL.getSourceRange(), glsl.value() });
			}
		}
		if (TO->isListInitialization()) {
			SourceRange braces = TO->getParenOrBraceRange();
			m_PendingEdits.emplace_back(PendingEdit{ braces.getBegin(), "(" });
			m_PendingEdits.emplace_back(PendingEdit{ braces.getEnd(), ")" });
		}
		return;
	}

	if (auto* FC = dyn_cast<CXXFunctionalCastExpr>(E->IgnoreParenImpCasts())) {
		if (auto* TSI = FC->getTypeInfoAsWritten()) {
			QualType QT = TSI->getType();
			if (auto glsl = glslTypeForVecBase(QT)) {
				TypeLoc TL = TSI->getTypeLoc();
				m_PendingEdits.emplace_back(PendingEdit{ TL.getSourceRange(), *glsl });
			}
		}
	}
}

bool KernelRewriter::VisitCXXConstructExpr(clang::CXXConstructExpr* pConstructorCall) {
	rewriteVecCtorType(pConstructorCall);
	return true;
}

bool KernelRewriter::VisitCXXFunctionalCastExpr(clang::CXXFunctionalCastExpr* pCastExpr) {
	rewriteVecCtorType(pCastExpr);
	return true;
}

clang::SourceLocation KernelRewriter::afterLSquare(const clang::Expr* Base) {
	return Lexer::findLocationAfterToken(Base->getEndLoc(), tok::l_square,
		m_pASTContext->getSourceManager(), m_pASTContext->getLangOpts(),
		/*SkipTrailingWhitespaceAndNewLine=*/true);
}

clang::SourceLocation KernelRewriter::afterRSquare(const clang::Expr* Index) {
	return Lexer::findLocationAfterToken(Index->getEndLoc(), tok::r_square,
		m_pASTContext->getSourceManager(), m_pASTContext->getLangOpts(),
		/*SkipTrailingWhitespaceAndNewLine=*/true);
}

bool KernelRewriter::VisitCXXOperatorCallExpr(clang::CXXOperatorCallExpr* E) {
	if (E->getOperator() != OO_Subscript) return true;

	auto* UDL = dyn_cast<clang::UserDefinedLiteral>(E->getArg(1)->IgnoreParenImpCasts());
	if (!UDL) return true;

	auto* ID = UDL->getUDSuffix();
	if (!ID || ID->getName() != "_sw") return true;

	auto& SM = m_pASTContext->getSourceManager();
	auto& LO = m_pASTContext->getLangOpts();

	std::string swizzle;
	CharSourceRange swRange = CharSourceRange::getTokenRange(UDL->getSourceRange());
	auto txt = Lexer::getSourceText(swRange, SM, LO);
	auto l = txt.find('"'), r = (l == StringRef::npos) ? StringRef::npos : txt.find('"', l + 1);
	if (l != StringRef::npos && r != StringRef::npos)
		swizzle = txt.substr(l + 1, r - l - 1).str();

	if (swizzle.empty()) return true;

	std::string repl = "." + swizzle;
	SourceLocation beginLoc = Lexer::getLocForEndOfToken(
		E->getArg(0)->getEndLoc(), 0, SM, LO);
	SourceRange range = { beginLoc, E->getEndLoc() };

	m_PendingEdits.emplace_back(PendingEdit{ range, repl });
	return true;
}

