// Helper: compute year from tm_year (1900-based)
inline int64_t extractYearFromTm(const std::tm& t) {
    return 1900LL + t.tm_year;
}

// Helper: floor division for negative numbers
inline int64_t floordiv(int64_t a, int64_t b) {
    if (b == 0) return 0;
    int64_t q = a / b;
    int64_t r = a % b;
    if ((r != 0) && ((r > 0) != (b > 0))) {
        --q;
    }
    return q;
}

// Extract millennium: returns the current millennium number (1-based)
template<typename T>
struct MillenniumExtractor : public InitSessionTimezone<T>,
                             public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE int64_t getMillenniumNumber(const std::tm& time) {
    int64_t yr = extractYearFromTm(time);
    if (yr > 0) {
      // Equivalent to ceil(yr / 1000.0), but integer-safe
      return (yr - 1) / 1000 + 1;
    } else {
      return floordiv(yr, 1000);
    }
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& out,
                                const arg_type<Timestamp>& ts) {
    out = getMillenniumNumber(getDateTime(ts, this->timeZone_));
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& out, const arg_type<Date>& d) {
    out = getMillenniumNumber(getDateTime(d));
  }

  FOLLY_ALWAYS_INLINE void call(
      int64_t& out, const arg_type<TimestampWithTimezone>& tz_ts) {
    auto ts = this->toTimestamp(tz_ts);
    out = getMillenniumNumber(getDateTime(ts, nullptr));
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& out,
                                const arg_type<Interval>& packed_interval) {
    auto iv = UnpackInterval(packed_interval);
    out = iv.month / 12000;  // 1000 years = 12000 months
  }
};

// Extract century: returns current century (1-based)
template<typename T>
struct CenturyExtractor : public InitSessionTimezone<T>,
                          public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE int64_t getCenturyNumber(const std::tm& time) {
    int64_t yr = extractYearFromTm(time);
    if (yr > 0) {
      return (yr - 1) / 100 + 1;
    } else {
      return floordiv(yr, 100);
    }
  }

  FOLLY_ALWAYS_INLINE void call(int64_t& out,
                                const arg_type<Timestamp>& ts) {
    out = getCenturyNumber(getDateTime(ts, this->timeZone_));
