// Second with sub-second precision
template<typename T>
struct SubSecondExtractor : public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE void call(double& out,
                                const arg_type<Timestamp>& ts) {
    auto dt = getDateTime(ts, nullptr);
    double sec = dt.tm_sec;
    double usec = static_cast<double>(ts.getNanos()) / 1000.0;
    usec = std::fmod(usec, 1'000'000.0);
    out = sec + usec / 1'000'000.0;
  }

  FOLLY_ALWAYS_INLINE void call(double& out, const arg_type<Date>& d) {
    auto dt = getDateTime(d);
    out = dt.tm_sec;
  }

  FOLLY_ALWAYS_INLINE void call(
      double& out, const arg_type<TimestampWithTimezone>& tz_ts) {
    auto ts = this->toTimestamp(tz_ts);
    auto dt = getDateTime(ts, nullptr);
    double sec = dt.tm_sec;
    double usec = static_cast<double>(ts.getNanos()) / 1000.0;
    usec = std::fmod(usec, 1'000'000.0);
    out = sec + usec / 1'000'000.0;
  }

  FOLLY_ALWAYS_INLINE void call(double& out,
                                const arg_type<Interval>& packed_interval) {
    auto iv = UnpackInterval(packed_interval);
    double total_sec = static_cast<double>(iv.time) / 1'000'000.0;
    out = std::fmod(total_sec, 60.0);
  }
};

// Milliseconds component (0–59999)
template<typename T>
struct MilliSecondExtractor : public TimestampWithTimezoneSupport<T> {
  VELOX_DEFINE_FUNCTION_TYPES(T);

  FOLLY_ALWAYS_INLINE void call(double& out,
                                const arg_type<Timestamp>& ts) {
    auto dt = getDateTime(ts, nullptr);
    double sec = dt.tm_sec;
    double usec = static_cast<double>(ts.getNanos()) / 1000.0;
    usec = std::fmod(usec, 1'000'000.0);
    out = sec * 1000.0 + usec / 1000.0;
  }

  FOLLY_ALWAYS_INLINE void call(
      double& out, const arg_type<TimestampWithTimezone>& tz_ts) {
    auto ts = this->toTimestamp(tz_ts);
    auto dt = getDateTime(ts, nullptr);
    double sec = dt.tm_sec;
    double usec = static_cast<double>(ts.getNanos()) / 1000.0;
