// Timezone ID → minutes offset
template<typename T>
struct TimezoneOffsetMinutesExtractor {
  VELOX_DEFINE_FUNCTION_TYPES(T);
  FOLLY_ALWAYS_INLINE void call(
      int64_t& out, const arg_type<TimestampWithTimezone>& tz_ts) {
    auto zone_id = unpackZoneKeyId(*tz_ts);
    out = zone_id * 60;
  }
};

// Timezone hours part
template<typename T>
struct TimezoneHoursExtractor {
  VELOX_DEFINE_FUNCTION_TYPES(T);
  FOLLY_ALWAYS_INLINE void call(
      int64_t& out, const arg_type<TimestampWithTimezone>& tz_ts) {
    auto zone_id = unpackZoneKeyId(*tz_ts);
    out = zone_id / 60;
  }
};

// Timezone minutes part
template<typename T>
struct TimezoneMinutesExtractor {
  VELOX_DEFINE_FUNCTION_TYPES(T);
  FOLLY_ALWAYS_INLINE void call(
      int64_t& out, const arg_type<TimestampWithTimezone>& tz_ts) {
    auto zone_id = unpackZoneKeyId(*tz_ts);
    out = zone_id % 60;
  }
};

