// Helper to check if window position saving is enabled
static bool is_position_remembering_enabled()
{
	return standard_config_objects::query_remember_window_positions();
}

// Enumerate monitors and compute bounding box of all visible displays
static BOOL CALLBACK monitor_union_enum_proc(
	HMONITOR hMonitor,
	HDC hdcMonitor,
	LPRECT lprcMonitor,
	LPARAM dwData)
{
	RECT* combined = reinterpret_cast<RECT*>(dwData);
	if (combined == nullptr) return FALSE;

	// Manual union: expand combined rect to include lprcMonitor
	LONG left   = std::min(combined->left,   lprcMonitor->left);
	LONG top    = std::min(combined->top,    lprcMonitor->top);
	LONG right  = std::max(combined->right,  lprcMonitor->right);
	LONG bottom = std::max(combined->bottom, lprcMonitor->bottom);

	combined->left   = left;
	combined->top    = top;
	combined->right  = right;
	combined->bottom = bottom;

	return TRUE;
}

// Validate whether a rectangle lies within screen bounds (with safety margin)
static bool is_rect_within_screens(const RECT* rc)
{
	if (rc == nullptr) return false;

	RECT full_clip = { LONG_MAX, LONG_MAX, LONG_MIN, LONG_MIN };
	if (!EnumDisplayMonitors(nullptr, nullptr, monitor_union_enum_proc, reinterpret_cast<LPARAM>(&full_clip))) {
		return false;
	}

	// Skip validation if any dimension is zero or negative
	if (rc->left >= rc->right || rc->top >= rc->bottom) return false;

	const LONG width  = rc->right - rc->left;
	const LONG height = rc->bottom - rc->top;

	const LONG clip_width  = full_clip.right - full_clip.left;
	const LONG clip_height = full_clip.bottom - full_clip.top;

	// Reject rectangles significantly larger than total display area
	if (clip_width > 0 && width > clip_width * 4) return false;
	if (clip_height > 0 && height > clip_height * 4) return false;

	// Final check: ensure at least part of rect intersects some monitor
	return MonitorFromRect(rc, MONITOR_DEFAULTTONULL) != nullptr;
}

// Read current window placement into config object
bool cfg_window_placement::read_from_window(HWND window)
{
	WINDOWPLACEMENT wp = {};
	wp.length = sizeof(WINDOWPLACEMENT);

	if (is_position_remembering_enabled()) {
		if (!GetWindowPlacement(window, &wp)) {
			PFC_ASSERT(!"GetWindowPlacement failed!");
			ZeroMemory(&wp, sizeof(wp));
		} else {
			// If window not visible, force hide state
			if (!IsWindowVisible(window)) {
				wp.showCmd = SW_HIDE;
			}
		}
	}

	try { set(wp); } catch (...) {}
	return wp.length == sizeof(wp);
}

// Apply saved placement to a window; optionally allow hidden state
bool apply_window_placement(HWND window, const WINDOWPLACEMENT& wp, bool permit_hidden)
{
	bool success = false;

	if (wp.length != sizeof(WINDOWPLACEMENT)) return false;
	if (!is_rect_within_screens(&wp.rcNormalPosition)) return false;

	if (permit_hidden || wp.showCmd != SW_HIDE) {
		if (wp.showCmd == SW_HIDE && (wp.flags & WPF_RESTORETOMAXIMIZED)) {
			// Special case: restore from maximized but hidden
			WINDOWPLACEMENT adjusted = wp;
			adjusted.showCmd = SW_SHOWMINIMIZED;

			if (SetWindowPlacement(window, &adjusted)) {
				ShowWindow(window, SW_HIDE);
				success = true;
			}
		} else {
			success = SetWindowPlacement(window, &wp);
		}
	}

	return success;
}

// Public wrapper to apply stored placement
bool cfg_window_placement::apply_to_window(HWND window, bool permit_hidden)
{
	bool applied = false;
	if (is_position_remembering_enabled()) {
		auto saved = get();
		applied = apply_window_placement(window, saved, permit_hidden);
	}
	return applied;
}

// Hook for silent creation (no action needed)
void cfg_window_placement::on_window_creation_silent(HWND window)
{
	// Intentionally empty
}

// Hook for normal creation: apply placement
bool cfg_window_placement::on_window_creation(HWND window, bool permit_hidden)
{
	return apply_to_window(window, permit_hidden);
}

// Hook on window destruction: save current placement
void cfg_window_placement::on_window_destruction(HWND window)
{
	read_from_window(window);
}

// Helper to resize window without moving or activating
static bool set_window_dimensions(HWND hwnd, unsigned width, unsigned height)
{
	if (width == ~0u || height == ~0u) return false;
	return SetWindowPos(hwnd, nullptr, 0, 0, width, height,
		SWP_NOACTIVATE | SWP_NOMOVE | SWP_NOZORDER) != FALSE;
}

// Apply saved size to window
bool cfg_window_size::apply_to_window(HWND hwnd)
{
	bool result = false;
	if (is_position_remembering_enabled()) {
		auto sz = get();
		if (sz.cx > 0 && sz.cy > 0) {
			result = set_window_dimensions(hwnd, static_cast<unsigned>(sz.cx), static_cast<unsigned>(sz.cy));
		}
	}
	return result;
}

// Hook on window creation: apply size
bool cfg_window_size::on_window_creation(HWND hwnd)
{
	return apply_to_window(hwnd);
}

// Hook on window destruction: record current size
void cfg_window_size::on_window_destruction(HWND hwnd)
{
	read_from_window(hwnd);
}

// Capture current window size
bool cfg_window_size::read_from_window(HWND hwnd)
{
	SIZE val = { 0, 0 };

	if (is_position_remembering_enabled()) {
		RECT r;
		if (GetWindowRect(hwnd, &r)) {
			val.cx = r.right - r.left;
			val.cy = r.bottom - r.top;
		}
	}

	set(val);
	return val.cx > 0 && val.cy > 0;
}

