#include "compiler/frontend/lexer.h"
#include "compiler/common/common_defs.h"
#include <string>
#include <unordered_map>

using namespace COMPILER;

// Build a mapping from reserved words to their token kinds
static std::unordered_map<std::string, Token::Kind> buildKeywordMap() {
    std::unordered_map<std::string, Token::Kind> map;

#define OPCODE(STR) map[#STR] = Token::TK_OP_##STR;
#include "compiler/mir/opcodes.def"
#undef OPCODE

#define PRIM_TYPE(TEXT, KIND, SIZE) map[#TEXT] = Token::TK_PT_##TEXT;
#include "compiler/mir/prim_types.def"
#undef PRIM_TYPE

#define KEYWORD(STR) map[#STR] = Token::TK_KW_##STR;
#include "compiler/mir/keywords.def"
#undef KEYWORD

#define CONDCODE(TEXT, PREDICATE, VALUE) map[#TEXT] = Token::TK_CC_##TEXT;
#include "compiler/mir/cond_codes.def"
#undef CONDCODE

    return map;
}

static const std::unordered_map<std::string, Token::Kind> keywordToTokenMap = buildKeywordMap();

class Lexer::Impl {
public:
  Impl(const char *begin, const char *finish)
      : _begin(begin), _pos(begin), _finish(finish) {}

  Token nextToken() {
    ZEN_ASSERT(_pos <= _finish);
    skipSpacesAndComments();
    _beginToken = _pos;

    if (isAtEnd())
      return makeToken(Token::_EOF);

    char currentChar = fetchNext();

    if (isLetter(currentChar))
      return parseIdentifierOrKeyword();

    if (isNumeric(currentChar) || (currentChar == '-' && isNumeric(peekNext())))
      return parseNumber();

    switch (currentChar) {
    case '(':
      return makeToken(Token::LPAR);
    case ')':
      return makeToken(Token::RPAR);
    case '[':
      return makeToken(Token::LBRACKET);
    case ']':
      return makeToken(Token::RBRACKET);
    case '{':
      return makeToken(Token::LBRACE);
    case '}':
      return makeToken(Token::RBRACE);
    case '%':
      return makeToken(Token::PERCENT);
    case '$':
      return makeToken(Token::DOLLAR);
    case '@':
      return makeToken(Token::AT);
    case '-':
      return makeToken(consumeIfMatched('>') ? Token::ARROW : Token::MINUS);
    case '=':
      return makeToken(Token::EQUAL);
    case ':':
      return makeToken(Token::COLON);
    case ',':
      return makeToken(Token::COMMA);
    case '.':
      return makeToken(Token::DOT);
    case '*':
      return makeToken(Token::STAR);
    case '\0':
      return makeToken(Token::_EOF);
    default:
      throw getError(ErrorCode::UnsupportedToken);
    }
  }

private:
  class LexerException {};

  bool consumeIfMatched(char expected) {
    ZEN_ASSERT(!isAtEnd());
    if (*_pos != expected)
      return false;
    ++_pos;
    return true;
  }

  char peekNext() const { return *_pos; }

  char fetchNext() {
    ZEN_ASSERT(_pos < _finish);
    return *_pos++;
  }

  bool isLetter(char c) const {
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
  }

  bool isNumeric(char c) const { return c >= '0' && c <= '9'; }

  Token parseIdentifierOrKeyword() {
    while (true) {
      char nextChar = peekNext();
      if (isLetter(nextChar) || isNumeric(nextChar) || nextChar == '_')
        fetchNext();
      else
        break;
    }

    std::string identifier(_beginToken, _pos - _beginToken);
    auto iter = keywordToTokenMap.find(identifier);
    if (iter != keywordToTokenMap.end()) {
      return makeToken(iter->second);
    }
    return makeToken(Token::IDENTIFIER);
  }

  Token parseNumber() {
    while (isNumeric(peekNext()))
      fetchNext();

    if (peekNext() == '.') {
      fetchNext();
      while (isNumeric(peekNext()))
        fetchNext();
    }

    return makeToken(Token::NUMBER);
  }

  bool isAtEnd() const { return _pos == _finish; }

  Token makeToken(Token::Kind type) const {
    return {type, _beginToken, static_cast<size_t>(_pos - _beginToken)};
  }

  void skipSpacesAndComments() {
    while (true) {
      char current = peekNext();
      switch (current) {
      case ' ':
      case '\r':
      case '\t':
      case '\n':
        fetchNext();
        break;
      case ';': // line comment
        while (peekNext() != '\n' && !isAtEnd())
          fetchNext();
        break;
      default:
        return;
      }
    }
  }

private:
  const char *_beginToken;
  const char *_begin;
  const char *_pos;
  const char *_finish;
};

Lexer::Lexer(const char *start, const char *end)
    : _impl(new Impl(start, end)) {}

Lexer::~Lexer() = default;

Token Lexer::nextToken() { 
    return _impl->nextToken(); 
}

