UOptionalMobileFeaturesBPLibrary::UOptionalMobileFeaturesBPLibrary(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
}

int UOptionalMobileFeaturesBPLibrary::GetVolumeState()
{
#if PLATFORM_ANDROID
	// Retrieve volume level from Android (range 0–15) and scale to percentage (0–100)
	int rawVolume = FAndroidMisc::GetVolumeState();
	int normalizedVolume = (rawVolume * 100) / 15;
	return normalizedVolume;
#elif PLATFORM_IOS
	// Use iOS-specific API for device volume
	return FPlatformMisc::GetDeviceVolume();
#else
	// Return default value for unsupported platforms
	return 0;
#endif
}

int UOptionalMobileFeaturesBPLibrary::GetBatteryLevel()
{
#if PLATFORM_ANDROID
	// Extract battery level from Android battery state
	return FAndroidMisc::GetBatteryState().Level;
#elif PLATFORM_IOS
	// Use iOS-specific method for battery level
	return FIOSPlatformMisc::GetBatteryLevel();
#else
	// Default fallback for non-mobile platforms
	return 0;
#endif
}

float UOptionalMobileFeaturesBPLibrary::GetBatteryTemperature()
{
#if PLATFORM_ANDROID
	// Get temperature directly from Android battery state
	return FAndroidMisc::GetBatteryState().Temperature;
#elif PLATFORM_IOS
	// No public API available currently — placeholder returns zero
	return 0.0f;
#else
	// Unsupported platform fallback
	return 0.0f;
#endif
}

bool UOptionalMobileFeaturesBPLibrary::AreHeadphonesPluggedIn()
{
#if PLATFORM_ANDROID
	// Query Android system for headphone connection status
	return FAndroidMisc::AreHeadPhonesPluggedIn();
#elif PLATFORM_IOS
	// Use iOS-specific function to check headphone status
	return FIOSPlatformMisc::AreHeadphonesPluggedIn();
#else
	// Assume no headphones on unsupported platforms
	return false;
#endif
}

