{
  static jclass const dateUtilsClass = jni::GetGlobalClassRef(env, "app/organicmaps/sdk/util/DateUtils");
  static jmethodID const is24HourFormatMethod =
      jni::GetStaticMethodID(env, dateUtilsClass, "is24HourFormat", "(Landroid/content/Context;)Z");

  jobject context = android::Platform::Instance().GetContext();
  jboolean const use24Hour = env->CallStaticBooleanMethod(dateUtilsClass, is24HourFormatMethod, context);

  jobject result = env->NewObject(g_classHoursMinutes, g_ctorHoursMinutes, hourVal, minuteVal, use24Hour);
  ASSERT(result, (jni::DescribeException()));
  return result;
}

// Overload: Create Timespan from two Java HoursMinutes
jobject CreateJavaTimespan(JNIEnv * env, jobject startTime, jobject endTime)
{
  jobject span = env->NewObject(g_classTimespan, g_ctorTimespan, startTime, endTime);
  ASSERT(span, (jni::DescribeException()));
  return span;
}

// Overload: Create Timespan from native Timespan
jobject CreateJavaTimespan(JNIEnv * env, osmoh::Timespan const & nativeSpan)
{
  auto const start = nativeSpan.GetStart();
  auto const end = nativeSpan.GetEnd();
  return CreateJavaTimespan(
      env,
      CreateJavaHoursMinutes(env, start.GetHoursCount(), start.GetMinutesCount()),
      CreateJavaHoursMinutes(env, end.GetHoursCount(), end.GetMinutesCount())
  );
}

// Create Timetable from raw Java objects
jobject CreateJavaTimetable(JNIEnv * env, jobject workingTime, jobject closedList, bool isFullDay, jintArray weekdayArr)
{
  jobject tt = env->NewObject(g_classTimetable, g_ctorTimetable, workingTime, closedList, isFullDay, weekdayArr);
  ASSERT(tt, (jni::DescribeException()));
  return tt;
}

// Create Timetable from native TimeTable
jobject CreateJavaTimetable(JNIEnv * env, TimeTable const & nativeTt)
{
  auto const excludeSpans = nativeTt.GetExcludeTime();
  std::set<Weekday> weekdaysSet = nativeTt.GetOpeningDays();

  std::vector<int> weekdayInts;
  weekdayInts.reserve(weekdaysSet.size());
  std::transform(weekdaysSet.begin(), weekdaysSet.end(), std::back_inserter(weekdayInts),
                 [](Weekday wd) { return static_cast<int>(wd); });

  jintArray jWeekdays = env->NewIntArray(static_cast<jsize>(weekdayInts.size()));
  env->SetIntArrayRegion(jWeekdays, 0, static_cast<jsize>(weekdayInts.size()), weekdayInts.data());

  jobjectArray jClosedSpans = jni::ToJavaArray(
      env,
      g_classTimespan,
      excludeSpans,
      [env](JNIEnv * e, osmoh::Timespan const & ts) { return CreateJavaTimespan(e, ts); }
  );

  return CreateJavaTimetable(
      env,
      CreateJavaTimespan(env, nativeTt.GetOpeningTime()),
      jClosedSpans,
      nativeTt.IsTwentyFourHours(),
      jWeekdays
  );
}

// Convert array of Timetables to Java array
jobjectArray CreateJavaTimetables(JNIEnv * env, TimeTableSet & nativeTts)
{
  size_t count = nativeTts.Size();
  jobjectArray result = env->NewObjectArray(static_cast<jsize>(count), g_classTimetable, nullptr);

  for (size_t idx = 0; idx < count; ++idx)
  {
    jni::TScopedLocalRef jTable(env, CreateJavaTimetable(env, nativeTts.Get(idx)));
    env->SetObjectArrayElement(result, static_cast<jsize>(idx), jTable.get());
  }

  return result;
}

// Convert Java HoursMinutes to native HourMinutes
HourMinutes ExtractNativeHoursMinutes(JNIEnv * env, jobject javaHM)
{
  jlong hours = env->GetLongField(javaHM, g_fieldHours);
  jlong minutes = env->GetLongField(javaHM, g_fieldMinutes);
  return HourMinutes{THours(hours) + TMinutes(minutes)};
}

// Convert Java Timespan to native Timespan
Timespan ExtractNativeTimespan(JNIEnv * env, jobject javaSpan)
{
  Timespan span;
  jobject startObj = env->GetObjectField(javaSpan, g_fieldStart);
  jobject endObj = env->GetObjectField(javaSpan, g_fieldEnd);
  span.SetStart(ExtractNativeHoursMinutes(env, startObj));
  span.SetEnd(ExtractNativeHoursMinutes(env, endObj));
  return span;
}

// Convert Java Timetable to native TimeTable
TimeTable ExtractNativeTimetable(JNIEnv * env, jobject javaTt)
{
  TimeTable tt = TimeTable::GetPredefinedTimeTable();

  // Extract weekdays
  jintArray jWeekdays = static_cast<jintArray>(env->GetObjectField(javaTt, g_fieldWeekdays));
  int * weekdayData = env->GetIntArrayElements(jWeekdays, nullptr);
  jint length = env->GetArrayLength(jWeekdays);

  std::set<Weekday> weekdays;
  for (int i = 0; i < length; ++i)
    weekdays.insert(ToWeekday(weekdayData[i]));

  tt.SetOpeningDays(weekdays);
  env->ReleaseIntArrayElements(jWeekdays, weekdayData, 0);

  // Set full-day flag
  tt.SetTwentyFourHours(env->GetBooleanField(javaTt, g_fieldIsFullDay));

  // Set opening time
  jobject workingSpan = env->GetObjectField(javaTt, g_fieldWorkingSpan);
  tt.SetOpeningTime(ExtractNativeTimespan(env, workingSpan));

  // Add excluded timespans
  jobjectArray jClosedSpans = static_cast<jobjectArray>(env->GetObjectField(javaTt, g_fieldClosedSpans));
  jint closedCount = env->GetArrayLength(jClosedSpans);
  for (int i = 0; i < closedCount; ++i)
  {
    jni::TScopedLocalRef jSpan(env, env->GetObjectArrayElement(jClosedSpans, i));
    if (jSpan.get())
      tt.AddExcludeTime(ExtractNativeTimespan(env, jSpan.get()));
  }

  return tt;
}

// Convert Java Timetable[] to native TimeTableSet
TimeTableSet ExtractNativeTimetableSet(JNIEnv * env, jobjectArray javaTts)
{
  TimeTableSet tts;
  int total = env->GetArrayLength(javaTts);

  if (total > 0)
  {
    jni::TScopedLocalRef firstTt(env, env->GetObjectArrayElement(javaTts, 0));
    tts.Replace(ExtractNativeTimetable(env, firstTt.get()), 0);
  }

  for (int i = 1; i < total; ++i)
  {
    jni::TScopedLocalRef timetable(env, env->GetObjectArrayElement(javaTts, i));
    tts.Append(ExtractNativeTimetable(env, timetable.get()));
  }

  return tts;
}

