Screen::Screen()
    : current_color_pair_(INVALID),
      canRun_(false),
      current_state_(State::RenderMessage),
      highlight_direction_(0),
      current_render_obj_(nullptr) {}

Screen::~Screen() {
  current_render_obj_ = nullptr;
  endwin();
}

inline bool Screen::IsInit(void) const { return (stdscr != nullptr); }

void Screen::Init(void) {
  initscr();
  if (stdscr == nullptr) {
    return;
  }
  nodelay(stdscr, true);
  keypad(stdscr, true);
  meta(stdscr, true);
  curs_set(0);
  noecho();
  bkgd(COLOR_BLACK);
  start_color();
  init_pair(GREEN_BLACK, COLOR_GREEN, COLOR_BLACK);
  init_pair(YELLOW_BLACK, COLOR_YELLOW, COLOR_BLACK);
  init_pair(RED_BLACK, COLOR_RED, COLOR_BLACK);
  init_pair(WHITE_BLACK, COLOR_WHITE, COLOR_BLACK);
  init_pair(BLACK_WHITE, COLOR_BLACK, COLOR_WHITE);
  refresh();
  clear();
  canRun_ = true;
}

int Screen::Width(void) const { return COLS; }
int Screen::Height(void) const { return LINES; }

void Screen::SetCurrentColor(ColorPair color) const {
  if (color == INVALID || !IsInit()) {
    return;
  }
  current_color_pair_ = color;
  attron(COLOR_PAIR(color));
}

void Screen::AddStr(int x, int y, const char* str) const {
  if (IsInit()) {
    mvaddstr(y, x, str);
  }
}

void Screen::AddStr(const char* str) const {
  if (IsInit()) {
    addstr(str);
  }
}

void Screen::ClearCurrentColor(void) const {
  if (IsInit() && current_color_pair_ != INVALID) {
    attroff(COLOR_PAIR(current_color_pair_));
    current_color_pair_ = INVALID;
  }
}

void Screen::AddStr(int x, int y, ColorPair color, const char* str) const {
  if (IsInit()) {
    attron(COLOR_PAIR(color));
    mvaddstr(y, x, str);
    attroff(COLOR_PAIR(color));
  }
}

void Screen::MoveOffsetXY(int offsetX, int offsetY) const {
  if (IsInit()) {
    int x, y;
    getyx(stdscr, y, x);
    move(y + offsetY, x + offsetX);
  }
}

void Screen::HighlightLine(int line_no) {
  if (!IsInit() || line_no >= Height()) {
    return;
  }

  // Highlight current line with BLACK_WHITE
  SetCurrentColor(BLACK_WHITE);
  for (int x = 0; x < Width(); ++x) {
    chtype ch = mvinch(line_no, x);
    mvaddch(line_no, x, ch & A_CHARTEXT);
  }
  ClearCurrentColor();

  // Restore previous highlight direction line
  if (line_no + highlight_direction_ >= 0 &&
      line_no + highlight_direction_ < Height()) {
    SetCurrentColor(WHITE_BLACK);
    for (int x = 0; x < Width(); ++x) {
      chtype ch = mvinch(line_no + highlight_direction_, x);
      ch &= A_CHARTEXT;
      if (ch == ' ') {
        mvaddch(line_no + highlight_direction_, x, ch);
      }
    }
    ClearCurrentColor();
  }
}

int Screen::SwitchState(int inputKey) {
  switch (current_state_) {
    case State::RenderInterCmdInfo:
      if (KEY_BACKSPACE == inputKey) {
        current_state_ = State::RenderMessage;
        clear();
        inputKey = 27;
      }
      break;
    case State::RenderMessage:
      if ('h' == inputKey || 'H' == inputKey) {
        current_state_ = State::RenderInterCmdInfo;
        clear();
      }
      break;
    default:
      break;
  }
  return inputKey;
}

void Screen::Run() {
  if (!IsInit() || current_render_obj_ == nullptr) {
    return;
  }

  highlight_direction_ = 0;

  auto renderFuncs = std::make_pair(&Screen::ShowRenderMessage,
                                    &Screen::ShowInteractiveCmd);

  while (canRun_) {
    int inputKey = getch();

    if ('q' == inputKey || 'Q' == inputKey || 27 == inputKey) {
      canRun_ = false;
      break;
    }

    inputKey = SwitchState(inputKey);

    (this->*renderFuncs.first)(inputKey);
    if (current_state_ == State::RenderInterCmdInfo) {
      (this->*renderFuncs.second)(inputKey);
    }

    double fr = current_render_obj_->frame_ratio();
    if (fr < MinHalfFrameRatio) {
      fr = MinHalfFrameRatio;
    }
    int delayMs = static_cast<int>(1000.0 / fr / 2.0);
    std::this_thread::sleep_for(std::chrono::milliseconds(delayMs));
  }
}

void Screen::Resize(void) {
  if (IsInit()) {
    clear();
    refresh();
  }
}

void Screen::ShowRenderMessage(int inputKey) {
  erase();
  int totalLines = current_render_obj_->Render(this, inputKey);
  int maxVisibleLines = std::min(Height(), totalLines);

  int* currentY = current_render_obj_->line_no();
  HighlightLine(*currentY);
  move(*currentY, 0);
  refresh();

  switch (inputKey) {
    case 's':
    case 'S':
    case KEY_DOWN:
      ++(*currentY);
      highlight_direction_ = -1;
      if (*currentY >= maxVisibleLines) {
        *currentY = maxVisibleLines - 1;
      }
      break;
    case 'w':
    case 'W':
    case KEY_UP:
      --(*currentY);
      highlight_direction_ = 1;
      if (*currentY < 1) {
        *currentY = 1;
      }
      if (*currentY < 0) {
        *currentY = 0;
      }
      break;
    case 'a':
    case 'A':
    case KEY_BACKSPACE:
    case KEY_LEFT: {
      RenderableMessage* parent = current_render_obj_->parent();
      if (parent) {
        current_render_obj_ = parent;
        currentY = parent->line_no();
        clear();
      }
      break;
    }
    case '\n':
    case '\r':
    case 'd':
    case 'D':
    case KEY_RIGHT: {
      RenderableMessage* child = current_render_obj_->Child(*currentY);
      if (child) {
        child->reset_line_page();
        current_render_obj_ = child;
        currentY = child->line_no();
        clear();
      }
      break;
    }
  }
}

void Screen::ShowInteractiveCmd(int) {
  unsigned y = 0;
  SetCurrentColor(Screen::WHITE_BLACK);
  AddStr((Width() - 19) / 2, y++, "Interactive Command");

  std::istringstream stream(InteractiveCmdStr);
  std::string line;
  while (std::getline(stream, line)) {
    AddStr(0, y++, line.c_str());
  }

  ClearCurrentColor();
}

#include <iostream>
#include <cmath>
#include <cstring>
#include <algorithm>

// Simplified decimal structure with similar functionality
struct Decimal {
    int sign;
    short exponent;
    unsigned char digits[32];
    int digitCount;

    Decimal() : sign(0), exponent(0), digitCount(0) {
        std::memset(digits, 0, sizeof(digits));
    }
};

// Helper function to count trailing zeros using bit manipulation
int countTrailingZeros(unsigned long value) {
    if (value == 0) return 64;
    int count = 0;
    while ((value & 1) == 0) {
        count++;
        value >>= 1;
    }
    return count;
}

// Round decimal number according to standard rules
void roundDecimal(Decimal& d, int precision) {
    if (precision <= 0 || precision >= d.digitCount) return;

    // Check if we need to round up
    bool shouldRoundUp = false;
    if (d.digits[precision] > 5) {
        shouldRoundUp = true;
    } else if (d.digits[precision] == 5) {
        // Check remaining digits
        for (int i = precision + 1; i < d.digitCount; ++i) {
            if (d.digits[i] != 0) {
                shouldRoundUp = true;
                break;
            }
        }
        // If all remaining are zero, check if we need to round to even
        if (!shouldRoundUp && (d.digits[precision - 1] & 1)) {
            shouldRoundUp = true;
        }
    }

    // Truncate to desired precision
    d.digitCount = precision;

    if (shouldRoundUp) {
        // Increment from right to left
        for (int i = precision - 1; i >= 0; --i) {
            if (d.digits[i] < 9) {
                d.digits[i]++;
                break;
            } else {
                d.digits[i] = 0;
                if (i == 0) {
                    // Need to shift left
                    for (int j = precision - 1; j > 0; --j) {
                        d.digits[j] = d.digits[j-1];
                    }
                    d.digits[0] = 1;
                    d.exponent++;
                    break;
                }
            }
        }
    }
}

// Convert unsigned long long to decimal representation
void convertIntegerToDecimal(Decimal& result, unsigned long long value) {
    result.sign = (value < 0) ? 1 : 0;
    if (value == 0) {
        result.exponent = 0;
        result.digitCount = 1;
        result.digits[0] = 0;
        return;
    }

    if (result.sign) value = -value;

    result.digitCount = 0;
    while (value > 0) {
        result.digits[result.digitCount++] = value % 10;
        value /= 10;
    }

    // Reverse the digits
    for (int i = 0; i < result.digitCount / 2; ++i) {
        unsigned char temp = result.digits[i];
        result.digits[i] = result.digits[result.digitCount - 1 - i];
        result.digits[result.digitCount - 1 - i] = temp;
    }

    result.exponent = result.digitCount - 1;
}

// Multiply two decimal numbers
void multiplyDecimals(Decimal& result, const Decimal& x, const Decimal& y) {
    unsigned long accumulator = 0;
    unsigned char product[64] = {0};
    int productStart = x.digitCount + y.digitCount - 1;

    // Perform multiplication digit by digit
    for (int i = productStart; i >= 0; --i) {
        int startJ = (i >= y.digitCount) ? i - y.digitCount + 1 : 0;
        int endJ = (i < x.digitCount) ? i : x.digitCount - 1;

        for (int j = startJ; j <= endJ; ++j) {
            int k = i - j;
            accumulator += x.digits[j] * y.digits[k];
        }

        product[i] = accumulator % 10;
        accumulator /= 10;
    }

    // Copy result
    result.sign = 0;
    result.exponent = x.exponent + y.exponent;

    int copyStart = 0;
    if (accumulator > 0) {
        product[0] = accumulator;
        result.exponent++;
        copyStart = 0;
    } else {
        copyStart = 1;
    }

    int copyCount = std::min(32, x.digitCount + y.digitCount);
    result.digitCount = 0;
    for (int i = copyStart; i < copyStart + copyCount; ++i) {
        if (result.digitCount < 32) {
            result.digits[result.digitCount++] = product[i];
        }
    }

    // Handle rounding if needed
    if (copyStart + copyCount < 64 && product[copyStart + copyCount] >= 5) {
        roundDecimal(result, result.digitCount);
    }
}

// Convert double to decimal
void convertDoubleToDecimal(double value, Decimal& result) {
    result.sign = (value < 0) ? 1 : 0;
    if (value == 0.0) {
        result.exponent = 0;
        result.digitCount = 1;
        result.digits[0] = 0;
        return;
    }

    if (std::isnan(value) || !std::isfinite(value)) {
        result.sign = (value < 0) ? 1 : 0;
        result.exponent = 0;
        result.digitCount = 1;
        result.digits[0] = 'I'; // Infinity
        return;
    }

    if (result.sign) value = -value;

    // Extract exponent and mantissa
    int exp;
    double mantissa = std::frexp(value, &exp);

    // Get integer part of scaled mantissa
    double intPart;
    std::modf(std::ldexp(mantissa, DBL_MANT_DIG), &intPart);

    // Create power of 2 decimal
    Decimal pow2;
    pow2.sign = 0;
    pow2.exponent = exp - DBL_MANT_DIG;
    pow2.digitCount = 1;
    pow2.digits[0] = 1;

    // Convert integer part to decimal
    Decimal intDecimal;
    convertIntegerToDecimal(intDecimal, static_cast<unsigned long long>(intPart));

    // Multiply to get final result
    multiplyDecimals(result, intDecimal, pow2);
    result.sign = (value < 0) ? 1 : 0;
}

// Compare two decimals
bool compareDecimals(const Decimal& a, const Decimal& b) {
    if (a.digits[0] == 0 && b.digits[0] == 0) return true;
    if (a.digits[0] == 0 || b.digits[0] == 0) return false;

    if (a.exponent != b.exponent) return a.exponent < b.exponent;

    int minLen = std::min(a.digitCount, b.digitCount);
    for (int i = 0; i < minLen; ++i) {
        if (a.digits[i] != b.digits[i]) {
            return a.digits[i] < b.digits[i];
        }
    }

    if (a.digitCount == b.digitCount) return true;

    // Check remaining digits
    if (a.digitCount < b.digitCount) {
        for (int i = minLen; i < b.digitCount; ++i) {
            if (b.digits[i] != 0) return true;
        }
        return false;
    } else {
        for (int i = minLen; i < a.digitCount; ++i) {
            if (a.digits[i] != 0) return false;
        }
        return true;
    }
}

// Subtract decimals
void subtractDecimals(Decimal& result, const Decimal& a, const Decimal& b) {
    result = a;

    if (b.digits[0] == 0) return;

    int maxLen = std::max(a.digitCount, b.digitCount);
    int diff = a.exponent - b.exponent;

    // Pad with zeros if necessary
    while (result.digitCount < maxLen + diff) {
        result.digits[result.digitCount++] = 0;
    }

    // Perform subtraction
    for (int i = result.digitCount - 1; i >= diff; --i) {
        int bIndex = i - diff;
        if (bIndex < b.digitCount) {
            if (result.digits[i] < b.digits[bIndex]) {
                // Borrow
                int j = i - 1;
                while (j >= 0 && result.digits[j] == 0) {
                    result.digits[j] = 9;
                    --j;
                }
                if (j >= 0) {
                    result.digits[j]--;
                    result.digits[i] += 10;
                }
            }
            result.digits[i] -= b.digits[bIndex];
        }
    }

    // Remove leading zeros
    int firstNonZero = 0;
    while (firstNonZero < result.digitCount && result.digits[firstNonZero] == 0) {
        ++firstNonZero;
    }

    if (firstNonZero > 0) {
        result.exponent -= firstNonZero;
        for (int i = 0; i < result.digitCount - firstNonZero; ++i) {
            result.digits[i] = result.digits[i + firstNonZero];
        }
        result.digitCount -= firstNonZero;
    }

    // Trim trailing zeros
    while (result.digitCount > 1 && result.digits[result.digitCount - 1] == 0) {
        --result.digitCount;
    }
}

// Main conversion function
void convertNumberToDecimal(short precision, double value, Decimal& result) {
    convertDoubleToDecimal(value, result);

    if (result.digits[0] > 9) return;

    if (precision > 32) precision = 32;

    roundDecimal(result, precision);

    while (result.digitCount < precision) {
        result.digits[result.digitCount++] = 0;
    }

    result.exponent -= result.digitCount - 1;

    // Convert to ASCII representation
    for (int i = 0; i < result.digitCount; ++i) {
        result.digits[i] += '0';
    }
}

// Convert decimal back to double
double convertDecimalToNumber(const Decimal& d) {
    if (d.digitCount <= 0) {
        return std::copysign(0.0, d.sign == 0 ? 1.0 : -1.0);
    }

    if (d.digits[0] == '0') {
        return std::copysign(0.0, d.sign == 0 ? 1.0 : -1.0);
    }

    if (d.digits[0] == 'I') {
        return std::copysign(INFINITY, d.sign == 0 ? 1.0 : -1.0);
    }

    if (d.digits[0] == 'N') {
        // Handle NaN
        unsigned long long* ll = reinterpret_cast<unsigned long long*>(new double);
        *ll = 0x7FF8000000000000ULL;
        if (d.sign) *ll |= 0x8000000000000000ULL;
        double result = *reinterpret_cast<double*>(ll);
        delete reinterpret_cast<double*>(ll);
        return result;
    }

    // Convert ASCII digits back to numeric values
    Decimal working = d;
    for (int i = 0; i < working.digitCount; ++i) {
        working.digits[i] -= '0';
    }
    working.exponent += working.digitCount - 1;

    // Calculate result using powers of 10
    double result = 0.0;
    double powersOf10[] = {1e1, 1e2, 1e3, 1e4, 1e5, 1e6, 1e7, 1e8};

    for (int i = 0; i < working.digitCount; ++i) {
        result = result * 10 + working.digits[i];
    }

    // Apply exponent
    int exp = working.exponent;
    if (exp < 0) {
        for (int i = 0; i < -exp; ++i) {
            result /= 10.0;
        }
    } else if (exp > 0) {
        for (int i = 0; i < exp; ++i) {
            result *= 10.0;
        }
    }

    if (working.sign) {
        result = -result;
    }

    return result;
}

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#include "doctest.h"
#include <toml11/spec.hpp>

TEST_CASE("constructing semantic_version objects")
{
    constexpr auto version = toml::semantic_version(1, 2, 3);
    CHECK(version.major == 1);
    CHECK(version.minor == 2);
    CHECK(version.patch == 3);
}

TEST_CASE("comparing semantic_version instances")
{
    constexpr auto ver_1_0_0 = toml::semantic_version(1, 0, 0);
    constexpr auto ver_1_0_1 = toml::semantic_version(1, 0, 1);
    constexpr auto ver_1_1_0 = toml::semantic_version(1, 1, 0);
    constexpr auto ver_1_1_2 = toml::semantic_version(1, 1, 2);
    constexpr auto ver_1_2_1 = toml::semantic_version(1, 2, 1);

    // Reflexivity tests for equality
    CHECK(ver_1_0_0 == ver_1_0_0);
    CHECK(ver_1_0_0 >= ver_1_0_0);
    CHECK(ver_1_0_0 <= ver_1_0_0);
    CHECK_FALSE(ver_1_0_0 != ver_1_0_0);
    CHECK_FALSE(ver_1_0_0 >  ver_1_0_0);
    CHECK_FALSE(ver_1_0_0 <  ver_1_0_0);

    // Comparison: 1.0.0 vs 1.0.1
    CHECK(ver_1_0_0 != ver_1_0_1);
    CHECK(ver_1_0_0 <= ver_1_0_1);
    CHECK(ver_1_0_0 <  ver_1_0_1);
    CHECK_FALSE(ver_1_0_0 == ver_1_0_1);
    CHECK_FALSE(ver_1_0_0 >= ver_1_0_1);
    CHECK_FALSE(ver_1_0_0 >  ver_1_0_1);

    // Comparison: 1.0.1 vs 1.1.0
    CHECK(ver_1_0_1 != ver_1_1_0);
    CHECK(ver_1_0_1 <  ver_1_1_0);
    CHECK(ver_1_0_1 <= ver_1_1_0);
    CHECK_FALSE(ver_1_0_1 == ver_1_1_0);
    CHECK_FALSE(ver_1_0_1 >  ver_1_1_0);
    CHECK_FALSE(ver_1_0_1 >= ver_1_1_0);

    // Comparison: 1.1.0 vs 1.0.1 (reverse order)
    CHECK(ver_1_1_0 != ver_1_0_1);
    CHECK(ver_1_1_0 >  ver_1_0_1);
    CHECK(ver_1_1_0 >= ver_1_0_1);
    CHECK_FALSE(ver_1_1_0 == ver_1_0_1);
    CHECK_FALSE(ver_1_1_0 <  ver_1_0_1);
    CHECK_FALSE(ver_1_1_0 <= ver_1_0_1);

    // Comparison: 1.1.2 vs 1.2.1
    CHECK(ver_1_1_2 != ver_1_2_1);
    CHECK(ver_1_1_2 <  ver_1_2_1);
    CHECK(ver_1_1_2 <= ver_1_2_1);
    CHECK(ver_1_2_1 != ver_1_1_2);
    CHECK(ver_1_2_1 >  ver_1_1_2);
    CHECK(ver_1_2_1 >= ver_1_1_2);
}

#include "wayland_display_window.h"
