// Helper lambda for scaling dimensions
inline auto scale_dimension = [](int base, double factor) -> int {
    return static_cast<int>(base * factor + 0.5);
};

WaylandDisplayWindow::WaylandDisplayWindow(WaylandDisplayBackend* hostBackend, DisplayWindowHost* delegate, bool isPopup, WaylandDisplayWindow* parent, RenderAPI api)
	: backend(hostBackend), m_owner(parent), windowHost(delegate), m_PopupWindow(isPopup), m_renderAPI(api)
{
	m_WindowSurface = backend->m_waylandCompositor.create_surface();
	m_NativeHandle.display = backend->s_waylandDisplay;
	m_NativeHandle.surface = m_WindowSurface;

	if (backend->m_FractionalScaleManager)
	{
		m_ScaleController = backend->m_FractionalScaleManager.get_fractional_scale(m_WindowSurface);
		m_ScaleController.on_preferred_scale() = [&](uint32_t numerator) {
			m_ScaleFactor = numerator / 120.0;
			m_DirtyGeometry = true;
			windowHost->OnWindowDpiScaleChanged();
		};
	}

	m_XdgSurface = backend->m_XDGWMBase.get_xdg_surface(m_WindowSurface);
	m_XdgSurface.on_configure() = [&](uint32_t serial) {
		m_XdgSurface.ack_configure(serial);
	};

	m_ActivationToken = backend->m_XDGActivation.get_activation_token();
	m_ActivationToken.on_done() = [&](const std::string& token) {
		m_ActivationTokenString = token;
	};
	m_ActivationToken.set_surface(m_WindowSurface);

	if (isPopup)
	{
		SetupPopupWindow();
	}
	else
	{
		SetupToplevelWindow();
	}

	backend->OnWindowCreated(this);
	DrawFrame();
}

WaylandDisplayWindow::~WaylandDisplayWindow()
{
	backend->OnWindowDestroyed(this);
}

void WaylandDisplayWindow::SetupToplevelWindow()
{
	m_XdgToplevel = m_XdgSurface.get_toplevel();
	m_XdgToplevel.set_title("ZWidget Window");

	if (m_owner)
		m_XdgToplevel.set_parent(m_owner->m_XdgToplevel);

	if (backend->m_XdgDecorationManager)
	{
		m_ToplevelDecoration = backend->m_XdgDecorationManager.get_toplevel_decoration(m_XdgToplevel);
		m_ToplevelDecoration.set_mode(wayland::zxdg_toplevel_decoration_v1_mode::server_side);
	}

	m_WindowSurface.commit();
	backend->s_waylandDisplay.roundtrip();

	m_XdgToplevel.on_configure() = [&](int32_t w, int32_t h, wayland::array_t states) {
		OnXdgToplevelResize(w, h);
	};
	m_XdgToplevel.on_close() = [&]() {
		OnWindowCloseRequested();
	};
	m_XdgToplevel.on_configure_bounds() = [this](int32_t w, int32_t h) {};

	m_ExportedSurface = backend->m_XdgExporter.export_toplevel(m_WindowSurface);
	m_ExportedSurface.on_handle() = [&](std::string handle) {
		m_WindowId = handle;
	};
}

void WaylandDisplayWindow::SetupPopupWindow()
{
	if (!m_owner)
		throw std::runtime_error("Popup must have an owner!");

	wayland::xdg_positioner_t pos = backend->m_XDGWMBase.create_positioner();
	pos.set_anchor(wayland::xdg_positioner_anchor::bottom);
	pos.set_anchor_rect(0, 0, 1, 30);
	pos.set_size(1, 1);

	m_XdgPopup = m_XdgSurface.get_popup(m_owner->m_XdgSurface, pos);
	m_XdgPopup.on_configure() = [&](int32_t x, int32_t y, int32_t w, int32_t h) {
		SetClientBounds(Rect::xywh(x, y, w, h));
	};
	m_XdgPopup.on_popup_done() = [&]() {
		OnWindowCloseRequested();
	};

	m_WindowSurface.commit();
	backend->s_waylandDisplay.roundtrip();
}

void WaylandDisplayWindow::SetWindowTitle(const std::string& label)
{
	if (m_XdgToplevel)
		m_XdgToplevel.set_title(label);
}

void WaylandDisplayWindow::SetWindowIcon(const std::vector<std::shared_ptr<Image>>& icons)
{
	if (backend->m_XdgIconManager)
	{
		if (icons.empty())
		{
			backend->m_XdgIconManager.set_icon(m_XdgToplevel, nullptr);
			return;
		}

		m_WindowIcon = backend->m_XdgIconManager.create_icon();
		GenerateIconBuffers(icons);

		for (auto& buffer : m_IconBuffers)
		{
			m_WindowIcon.add_buffer(buffer, 1);
		}
		backend->m_XdgIconManager.set_icon(m_XdgToplevel, m_WindowIcon);
	}
}

void WaylandDisplayWindow::SetWindowFrame(const Rect& bounds)
{
	ReallocateBuffers(bounds.width, bounds.height);
	windowHost->OnWindowGeometryChanged();
	m_DirtyGeometry = true;
	m_WindowSurface.commit();
}

void WaylandDisplayWindow::SetClientBounds(const Rect& bounds)
{
	SetWindowFrame(bounds);
}

void WaylandDisplayWindow::Show()
{
	m_WindowSurface.attach(m_WindowBuffer, 0, 0);
	m_WindowSurface.damage(0, 0, m_WindowSize.width, m_WindowSize.height);
	m_WindowSurface.commit();
}

void WaylandDisplayWindow::ShowFullscreen()
{
	if (m_XdgToplevel)
	{
		m_XdgToplevel.set_fullscreen(backend->m_waylandOutput);
		m_IsFullscreen = true;
	}
}

