void WaylandDisplayWindow::DrawFrame(uint32_t /* serial */)
{
	m_WindowSurface.attach(m_WindowBuffer, 0, 0);
	m_WindowSurface.damage(0, 0, m_WindowSize.width, m_WindowSize.height);

	if (m_renderAPI == RenderAPI::Unspecified || m_renderAPI == RenderAPI::Bitmap)
	{
		m_FrameCallback = m_WindowSurface.frame();
		m_FrameCallback.on_done() = [this]() { DrawFrame(); };
	}

	m_WindowSurface.commit();
}

void WaylandDisplayWindow::ReallocateBuffers(int32_t w, int32_t h)
{
	if (w == 0 || h == 0)
		return;

	if (m_SharedMemory)
		m_SharedMemory.reset();

	int scaledW = scale_dimension(w, m_ScaleFactor);
	int scaledH = scale_dimension(h, m_ScaleFactor);

	m_SharedMemory = std::make_shared<SharedMemHelper>(scaledW * scaledH * 4);
	auto pool = backend->m_waylandSHM.create_pool(m_SharedMemory->get_fd(), scaledW * scaledH * 4);
	m_WindowBuffer = pool.create_buffer(0, scaledW, scaledH, scaledW * 4, wayland::shm_format::xrgb8888);
	m_WindowSize = Size(scaledW, scaledH);
}

void WaylandDisplayWindow::GenerateIconBuffers(const std::vector<std::shared_ptr<Image>>& images)
{
	if (images.empty())
		return;

	m_IconBuffers.clear();
	m_IconMemories.clear();

	for (auto& img : images)
	{
		const int size = img->GetWidth() * img->GetHeight() * 4;
		const int stride = img->GetWidth() * 4;

		auto mem = std::make_shared<SharedMemHelper>(size);
		auto pool = backend->m_waylandSHM.create_pool(mem->get_fd(), size);
		auto buf = pool.create_buffer(0, img->GetWidth(), img->GetHeight(), stride, wayland::shm_format::argb8888);

		std::memcpy(mem->get_mem(), img->GetData(), size);
		m_IconMemories.push_back(mem);
		m_IconBuffers.push_back(buf);
	}
}

