// Minimal Vulkan stubs to avoid external dependencies
#ifndef VK_VERSION_1_0
#define VKAPI_CALL
#define VKAPI_PTR VKAPI_CALL
typedef uint32_t VkFlags;
typedef enum VkStructureType {
	VK_STRUCTURE_TYPE_WAYLAND_SURFACE_CREATE_INFO_KHR = 1000006000,
	VK_OBJECT_TYPE_MAX_ENUM = 0x7FFFFFFF
} VkStructureType;
typedef enum VkResult {
	VK_SUCCESS = 0,
	VK_RESULT_MAX_ENUM = 0x7FFFFFFF
} VkResult;
typedef struct VkAllocationCallbacks VkAllocationCallbacks;
typedef void (VKAPI_PTR* PFN_vkVoidFunction)(void);
typedef PFN_vkVoidFunction(VKAPI_PTR* PFN_vkGetInstanceProcAddr)(VkInstance, const char*);
#ifndef VK_KHR_wayland_surface
typedef VkFlags VkWaylandSurfaceCreateFlagsKHR;
typedef struct VkWaylandSurfaceCreateInfoKHR {
	VkStructureType sType;
	const void* pNext;
	VkWaylandSurfaceCreateFlagsKHR flags;
	struct wl_display* display;
	struct wl_surface* surface;
} VkWaylandSurfaceCreateInfoKHR;
typedef VkResult(VKAPI_PTR* PFN_vkCreateWaylandSurfaceKHR)(VkInstance, const VkWaylandSurfaceCreateInfoKHR*, const VkAllocationCallbacks*, VkSurfaceKHR*);
#endif
#endif

class VulkanLoaderHelper
{
public:
	VulkanLoaderHelper()
	{
#if defined(__APPLE__)
		handle = dlopen("libvulkan.dylib", RTLD_NOW | RTLD_LOCAL);
		if (!handle) handle = dlopen("libvulkan.1.dylib", RTLD_NOW | RTLD_LOCAL);
		if (!handle) handle = dlopen("libMoltenVK.dylib", RTLD_NOW | RTLD_LOCAL);
#else
		handle = dlopen("libvulkan.so.1", RTLD_NOW | RTLD_LOCAL);
		if (!handle) handle = dlopen("libvulkan.so", RTLD_NOW | RTLD_LOCAL);
#endif
		if (!handle)
			throw std::runtime_error("Failed to load Vulkan library");

		vkGetInstanceProcAddr = (PFN_vkGetInstanceProcAddr)dlsym(handle, "vkGetInstanceProcAddr");
		if (!vkGetInstanceProcAddr)
		{
			dlclose(handle);
			throw std::runtime_error("vkGetInstanceProcAddr not found");
		}
	}

	~VulkanLoaderHelper()
	{
		if (handle)
			dlclose(handle);
	}

	PFN_vkGetInstanceProcAddr vkGetInstanceProcAddr = nullptr;
	void* handle = nullptr;
};

VkSurfaceKHR WaylandDisplayWindow::CreateVulkanSurface(VkInstance instance)
{
	static VulkanLoaderHelper loader;
	auto createWaylandSurface = (PFN_vkCreateWaylandSurfaceKHR)loader.vkGetInstanceProcAddr(instance, "vkCreateWaylandSurfaceKHR");
	if (!createWaylandSurface)
		throw std::runtime_error("Could not resolve vkCreateWaylandSurfaceKHR");

	VkWaylandSurfaceCreateInfoKHR info = {};
	info.sType = VK_STRUCTURE_TYPE_WAYLAND_SURFACE_CREATE_INFO_KHR;
	info.display = m_NativeHandle.display;
	info.surface = m_NativeHandle.surface;

	VkSurfaceKHR surface = {};
	VkResult res = createWaylandSurface(instance, &info, nullptr, &surface);
	if (res != VK_SUCCESS)
		throw std::runtime_error("Failed to create Vulkan surface");

	return surface;
}

