// Helper: allocate raster and lock memory for processing
template <typename T>
TRasterGR8P createAndLockRaster(T** outBuffer, TDimensionI size) {
  TRasterGR8P raster(size.lx * sizeof(T), size.ly);
  raster->lock();
  *outBuffer = static_cast<T*>(raster->getRawData());
  return raster;
}

// Unlock all rasters in list
void unlockAllRasters(QList<TRasterGR8P>& rasters) {
  for (int idx = 0; idx < rasters.size(); ++idx)
    rasters[idx]->unlock();
}

// Unlock rasters and free FFT plans
void cleanupResources(QList<TRasterGR8P>& rasters, QList<kiss_fftnd_cfg>& fftPlans) {
  unlockAllRasters(rasters);
  for (int pIdx = 0; pIdx < fftPlans.size(); ++pIdx)
    kiss_fft_free(fftPlans[pIdx]);
}
