// Convert RGB depth map to grayscale unsigned char
template <typename RASTER, typename PIXEL>
void Iwa_BokehRefFx::setDepthRaster(const RASTER srcRas, unsigned char* dstMem,
                                    TDimensionI dims) {
  unsigned char* outPtr = dstMem;
  for (int y = 0; y < dims.ly; ++y) {
    PIXEL* pixelRow = srcRas->pixels(y);
    for (int x = 0; x < dims.lx; ++x, ++pixelRow, ++outPtr) {
      double intensity = (static_cast<double>(pixelRow->r) * 0.3 +
                          static_cast<double>(pixelRow->g) * 0.59 +
                          static_cast<double>(pixelRow->b) * 0.11) /
                         static_cast<double>(PIXEL::maxChannelValue);
      *outPtr = static_cast<unsigned char>(intensity * UCHAR_MAX + 0.5);
    }
  }
}

// Convert grayscale depth map to unsigned char
template <typename RASTER, typename PIXEL>
void Iwa_BokehRefFx::setDepthRasterGray(const RASTER srcRas,
                                        unsigned char* dstMem,
                                        TDimensionI dims) {
  unsigned char* outPtr = dstMem;
  for (int y = 0; y < dims.ly; ++y) {
    PIXEL* pixelRow = srcRas->pixels(y);
    for (int x = 0; x < dims.lx; ++x, ++pixelRow, ++outPtr) {
      double normalized = static_cast<double>(pixelRow->value) /
                          static_cast<double>(PIXEL::maxChannelValue);
      *outPtr = static_cast<unsigned char>(normalized * UCHAR_MAX + 0.5);
    }
  }
}

