Iwa_BokehRefFx::Iwa_BokehRefFx()
    : m_distancePrecision(10), m_fillGap(true), m_doMedian(true) {
  addInputPort("Source", m_source);
  addInputPort("Depth", m_depth);

  bindParam(this, "on_focus_distance", m_onFocusDistance, false);
  bindParam(this, "bokeh_amount", m_bokehAmount, false);
  bindParam(this, "hardness", m_hardness, false);
  bindParam(this, "gamma", m_gamma, false);
  bindParam(this, "gammaAdjust", m_gammaAdjust, false);
  bindParam(this, "distance_precision", m_distancePrecision, false);
  bindParam(this, "fill_gap", m_fillGap, false);
  bindParam(this, "fill_gap_with_median_filter", m_doMedian, false);
  bindParam(this, "linearizeMode", m_linearizeMode, false);

  m_distancePrecision->setValueRange(3, 128);
  enableComputeInFloat(true);

  setFxVersion(3); // Default version
}

//--------------------------------------------

void Iwa_BokehRefFx::onFxVersionSet() {
  bool useGammaParam = getFxVersion() == 2;

  if (getFxVersion() == 1) {
    m_linearizeMode->setValue(Hardness);
    setFxVersion(3);
  } else if (getFxVersion() == 2) {
    if (m_linearizeMode->getValue() == Hardness ||
        (m_gamma->getKeyframeCount() == 0 &&
         areAlmostEqual(m_gamma->getDefaultValue(), 2.2))) {
      useGammaParam = false;
      setFxVersion(3);
    }
  }

  auto gammaParam = getParams()->getParamVar("gamma");
  auto gammaAdjParam = getParams()->getParamVar("gammaAdjust");

  gammaParam->setIsHidden(!useGammaParam);
  gammaAdjParam->setIsHidden(useGammaParam);
}

//--------------------------------------------

void Iwa_BokehRefFx::doCompute(TTile& outputTile, double frame,
                               const TRenderSettings& settings) {
  // Early exit if required inputs are missing
  if (!m_iris.isConnected() || !m_source.isConnected() ||
      !m_depth.isConnected()) {
    outputTile.getRaster()->clear();
    return;
  }

  QList<TRasterGR8P> managedRasters;

  // Compute effective bokeh radius in pixels
  double bokehPixelScale = BokehUtils::getBokehPixelAmount(
      m_bokehAmount->getValue(frame), settings.m_affine);

  // Determine max blur radius based on focus distance
  double focusDist = m_onFocusDistance->getValue(frame);
  double maxBlurRadius = bokehPixelScale * std::max(1.0 - focusDist, focusDist);
  int padding =
      (maxBlurRadius > 1.0f) ? static_cast<int>(std::ceil((maxBlurRadius - 1.0) / 2.0)) : 0;

  // Define computation region with padding
  TRectD tileRect(outputTile.m_pos, TDimensionD(outputTile.getRaster()->getLx(),
                                                outputTile.getRaster()->getLy()));
  tileRect = tileRect.enlarge(static_cast<double>(padding));
  TDimensionI tileSize(static_cast<int>(tileRect.getLx() + 0.5),
                       static_cast<int>(tileRect.getLy() + 0.5));

  // Optimize dimensions for kissFFT (powers of 2,3,5)
  if (tileSize.lx < 10000 && tileSize.ly < 10000) {
    int newX = kiss_fft_next_fast_size(tileSize.lx);
    int newY = kiss_fft_next_fast_size(tileSize.ly);

    // Ensure even padding difference
    while ((newX - tileSize.lx) % 2 != 0)
      newX = kiss_fft_next_fast_size(newX + 1);
    while ((newY - tileSize.ly) % 2 != 0)
      newY = kiss_fft_next_fast_size(newY + 1);

    tileRect = tileRect.enlarge(static_cast<double>(newX - tileSize.lx) / 2.0,
                                static_cast<double>(newY - tileSize.ly) / 2.0);
    tileSize.lx = newX;
    tileSize.ly = newY;
  }

  // --- Source Tile ---
  LayerValue layerData;
  layerData.sourceTile = new TTile();
  m_source->allocateAndCompute(*layerData.sourceTile, tileRect.getP00(), tileSize,
                               outputTile.getRaster(), frame, settings);

  // --- Iris Tile ---
  TRectD irisBBox;
  m_iris->getBBox(frame, irisBBox, settings);

  TTile irisTile;
  m_iris->allocateAndCompute(
      irisTile, irisBBox.getP00(),
      TDimension(static_cast<int>(irisBBox.getLx() + 0.5),
                 static_cast<int>(irisBBox.getLy() + 0.5)),
      outputTile.getRaster(), frame, settings);

  if (settings.m_isCanceled && *settings.m_isCanceled) {
    unlockAllRasters(managedRasters);
    outputTile.getRaster()->clear();
    return;
  }

  // Determine effective gamma value
  double effectiveGamma;
  if (m_linearizeMode->getValue() == Hardness)
    effectiveGamma = m_hardness->getValue(frame);
  else { // Gamma mode
    if (getFxVersion() == 2)
      effectiveGamma = m_gamma->getValue(frame);
    else
      effectiveGamma = std::max(1.0, settings.m_colorSpaceGamma + m_gammaAdjust->getValue(frame));
    if (outputTile.getRaster()->isLinear())
      effectiveGamma /= settings.m_colorSpaceGamma;
  }

  // --- Depth Map Processing ---
  QMap<int, unsigned char*> depthBuffers;
  unsigned char* depthMem;
  managedRasters.append(createAndLockRaster<unsigned char>(&depthMem, tileSize));

  {
    TTile depthTile;
    m_depth->allocateAndCompute(depthTile, tileRect.getP00(), tileSize,
                                outputTile.getRaster(), frame, settings);

    if (settings.m_isCanceled && *settings.m_isCanceled) {
      unlockAllRasters(managedRasters);
      outputTile.getRaster()->clear();
      return;
    }

    TRasterGR8P ras8   = dynamic_cast<TRasterGR8P>(depthTile.getRaster());
    TRasterGR16P ras16 = dynamic_cast<TRasterGR16P>(depthTile.getRaster());
    TRaster32P ras32   = dynamic_cast<TRaster32P>(depthTile.getRaster());
    TRaster64P ras64   = dynamic_cast<TRaster64P>(depthTile.getRaster());
    TRasterFP rasF     = dynamic_cast<TRasterFP>(depthTile.getRaster());

    s_lock.lockForRead();
    if (ras8)
      setDepthRasterGray<TRasterGR8P, TPixelGR8>(ras8, depthMem, tileSize);
    else if (ras16)
      setDepthRasterGray<TRasterGR16P, TPixelGR16>(ras16, depthMem, tileSize);
    else if (ras32)
      BokehUtils::setDepthRaster<TRaster32P, TPixel32>(ras32, depthMem, tileSize);
    else if (ras64)
      BokehUtils::setDepthRaster<TRaster64P, TPixel64>(ras64, depthMem, tileSize);
    else if (rasF)
      BokehUtils::setDepthRaster<TRasterFP, TPixelF>(rasF, depthMem, tileSize);
    s_lock.unlock();
  }

  depthBuffers[1] = depthMem;

  // Prepare layer configuration
  layerData.premultiply       = false;
  layerData.layerGamma        = effectiveGamma;
  layerData.depth_ref         = 1;
  layerData.distance          = 0.5;
  layerData.bokehAdjustment   = 1.0;
  layerData.depthRange        = 1.0;
  layerData.distancePrecision = m_distancePrecision->getValue();
  layerData.fillGap           = m_fillGap->getValue();
  layerData.doMedian          = m_doMedian->getValue();

  QList<LayerValue> layers;
  layers.append(layerData);

  // Perform main bokeh computation
  Iwa_BokehCommonFx::doFx(outputTile, frame, settings, bokehPixelScale, padding,
                          tileSize, irisBBox, irisTile, layers, depthBuffers);

  // Cleanup
  unlockAllRasters(managedRasters);
  delete layerData.sourceTile;
}

