		[_PC_VDISABLE] = 0L,
		[_PC_SYNC_IO] = 1L,
		[_PC_ASYNC_IO] = -1L,
		[_PC_PRIO_IO] = -1L,
		[_PC_SOCK_MAXBUF] = -1L,
		[_PC_FILESIZEBITS] = FILESIZEBITS,
		[_PC_REC_INCR_XFER_SIZE] = 4096L,
		[_PC_REC_MAX_XFER_SIZE] = 4096L,
		[_PC_REC_MIN_XFER_SIZE] = 4096L,
		[_PC_REC_XFER_ALIGN] = 4096L,
