#include <iostream>
#include <deque>
using namespace std;

class FrontMiddleBackQueue {
public:
    deque<int> frontPart, backPart;

    FrontMiddleBackQueue() {}

    // Maintain balance so that frontPart has either same number of elements as backPart or one more
    void adjust() {
        while (frontPart.size() > backPart.size() + 1) {
            backPart.push_front(frontPart.back());
            frontPart.pop_back();
        }
        while (frontPart.size() < backPart.size()) {
            frontPart.push_back(backPart.front());
            backPart.pop_front();
        }
    }

    void addFront(int value) {
        frontPart.push_front(value);
        adjust();
    }

    void addMiddle(int value) {
        if (frontPart.size() > backPart.size()) {
            backPart.push_front(frontPart.back());
            frontPart.pop_back();
        }
        frontPart.push_back(value);
        adjust();
    }

    void addRear(int value) {
        backPart.push_back(value);
        adjust();
    }

    int removeFront() {
        if (frontPart.empty() && backPart.empty()) return -1;
        int val;
        if (!frontPart.empty()) {
            val = frontPart.front();
            frontPart.pop_front();
        } else {
            val = backPart.front();
            backPart.pop_front();
        }
        adjust();
        return val;
    }

    int removeMiddle() {
        if (frontPart.empty() && backPart.empty()) return -1;
        int val = frontPart.back();
        frontPart.pop_back();
        adjust();
        return val;
    }

    int removeRear() {
        if (frontPart.empty() && backPart.empty()) return -1;
        int val;
        if (!backPart.empty()) {
            val = backPart.back();
            backPart.pop_back();
        } else {
            val = frontPart.back();
            frontPart.pop_back();
        }
        adjust();
        return val;
    }
};

