#include "MsDbMgr.h"
#include <cstdio>
#include <string>
#include <mutex>
#include <memory>

// Singleton instance and mutex for thread-safe initialization
std::unique_ptr<MsDbMgr> MsDbMgr::m_instance;
std::mutex MsDbMgr::m_mutex;

// Constructor: initialize database handle to nullptr
MsDbMgr::MsDbMgr() : m_sql(nullptr) {}

// Destructor: ensure database connection is closed properly
MsDbMgr::~MsDbMgr() {
    if (m_sql != nullptr) {
        sqlite3_close(m_sql);
        m_sql = nullptr;
    }
}

// Initialize the database: open and create required tables if not exist
int MsDbMgr::Init() {
    int rc = sqlite3_open("conf/media_server.db", &m_sql);
    if (rc != SQLITE_OK) {
        std::fprintf(stderr, "Can't open database: %s\n", sqlite3_errmsg(m_sql));
        return -1;
    }

    char* zErrMsg = nullptr;

    // Table: t_file — stores media file metadata
    std::string sql1 =
        "CREATE TABLE IF NOT EXISTS t_file ("
        "file_id    INTEGER PRIMARY KEY,"
        "name       TEXT    NOT NULL,"
        "size       INTEGER NOT NULL,"
        "codec      TEXT    NOT NULL,"
        "res        TEXT    NOT NULL,"
        "duration   REAL    DEFAULT 0,"
        "frame_rate REAL    DEFAULT 0"
        ")";
    rc = sqlite3_exec(m_sql, sql1.c_str(), nullptr, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        std::fprintf(stderr, "database error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        return 1;
    }

    // Table: device — stores device configuration and ONVIF info
    std::string sql2 =
        "CREATE TABLE IF NOT EXISTS device ("
        "id           INTEGER PRIMARY KEY,"
        "device_id    TEXT    NOT NULL UNIQUE,"
        "parent_id    TEXT    NOT NULL,"
        "domain_id    TEXT    NOT NULL,"
        "name         TEXT    NOT NULL,"
        "status       TEXT    NOT NULL,"
        "manufacturer TEXT    NOT NULL,"
        "model        TEXT    NOT NULL,"
        "owner        TEXT    NOT NULL,"
        "civil_code   TEXT    NOT NULL,"
        "address      TEXT    NOT NULL,"
        "ip_addr      TEXT    NOT NULL,"
        "user         TEXT    NOT NULL,"
        "pass         TEXT    NOT NULL,"
        "longitude    TEXT    NOT NULL,"
        "latitude     TEXT    NOT NULL,"
        "url          TEXT    NOT NULL,"
        "ptz_type     INTEGER NOT NULL,"
        "type         INTEGER NOT NULL,"
        "protocol     INTEGER NOT NULL,"
        "port         INTEGER NOT NULL,"
        "bind_ip      TEXT    NOT NULL,"
        "remark       TEXT    NOT NULL,"
        "codec        TEXT    DEFAULT 'unknown',"
        "resolution   TEXT    DEFAULT 'unknown',"
        "onvif_profile TEXT   DEFAULT '',"
        "onvif_ptz_url TEXT   DEFAULT ''"
        ")";
    rc = sqlite3_exec(m_sql, sql2.c_str(), nullptr, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        std::fprintf(stderr, "database error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        return 1;
    }

    // Table: group_dev — many-to-many mapping between groups and devices
    std::string sql3 =
        "CREATE TABLE IF NOT EXISTS group_dev ("
        "group_id  TEXT NOT NULL,"
        "device_id TEXT NOT NULL,"
        "name      TEXT NOT NULL,"
        "type      INTEGER NOT NULL,"
        "PRIMARY KEY(group_id, device_id)"
        ")";
    rc = sqlite3_exec(m_sql, sql3.c_str(), nullptr, 0, &zErrMsg);
    if (rc != SQLITE_OK) {
        std::fprintf(stderr, "database error: %s\n", zErrMsg);
        sqlite3_free(zErrMsg);
        return 1;
    }

    return 0;
}

// Thread-safe access to the underlying SQLite handle
sqlite3* MsDbMgr::GetSql() {
    m_sqlMutex.lock();
    return m_sql;
}

// Release lock on the SQLite handle
void MsDbMgr::RelSql() {
    m_sqlMutex.unlock();
}

// Lazy-initialized singleton accessor with double-checked locking
MsDbMgr* MsDbMgr::Instance() {
    // First check without locking (fast path)
    if (m_instance) {
        return m_instance.get();
    }

    // Lock only if instance is null (slow path)
    std::lock_guard<std::mutex> lock(m_mutex);

    // Re-check after acquiring lock
    if (m_instance) {
        return m_instance.get();
    }

    // Create instance
    m_instance = std::make_unique<MsDbMgr>();
    return m_instance.get();
}

#include "sdfg/symbolic/sets.h"
#include <gtest/gtest.h>
#include "sdfg/symbolic/maps.h"
#include "sdfg/types/scalar.h"

using namespace sdfg;

TEST(MapsTest, IsDisjoint_Stencil7P_Variant) {
    types::Scalar int32_desc(types::PrimitiveType::Int32);
    types::Scalar int64_desc(types::PrimitiveType::Int32); // Note: Int32 used consistently as in original

    // Symbol definitions with assumptions
    auto sym_a = symbolic::symbol("_19");
    auto assume_a = symbolic::Assumption::create(sym_a, int32_desc);
    assume_a.lower_bound_deprecated(symbolic::one());
    assume_a.constant(true);

    auto sym_b = symbolic::symbol("_1");
    auto assume_b = symbolic::Assumption::create(sym_b, int64_desc);
    assume_b.lower_bound_deprecated(symbolic::one());
    assume_b.constant(true);

    auto sym_c = symbolic::symbol("_2");
    auto assume_c = symbolic::Assumption::create(sym_c, int64_desc);
    assume_c.lower_bound_deprecated(symbolic::one());
    assume_c.constant(true);

    auto sym_d = symbolic::symbol("_3");
    auto assume_d = symbolic::Assumption::create(sym_d, int64_desc);
    assume_d.lower_bound_deprecated(symbolic::one());
    assume_d.constant(true);

    // Induction variables with bounds and mapping
    auto iv_0 = symbolic::symbol("_13");
    auto iv0_assume = symbolic::Assumption::create(iv_0, int64_desc);
    iv0_assume.lower_bound_deprecated(symbolic::zero());
    iv0_assume.upper_bound_deprecated(symbolic::sub(sym_a, symbolic::one()));
    iv0_assume.map(symbolic::add(iv_0, symbolic::one()));

    auto iv_1 = symbolic::symbol("_24");
    auto iv1_assume = symbolic::Assumption::create(iv_1, int64_desc);
    iv1_assume.lower_bound_deprecated(symbolic::zero());
    iv1_assume.upper_bound_deprecated(symbolic::sub(sym_b, symbolic::one()));
    iv1_assume.map(symbolic::add(iv_1, symbolic::one()));

    auto iv_2 = symbolic::symbol("_28");
    auto iv2_assume = symbolic::Assumption::create(iv_2, int64_desc);
    iv2_assume.lower_bound_deprecated(symbolic::zero());
    iv2_assume.upper_bound_deprecated(symbolic::sub(sym_c, symbolic::one()));
    iv2_assume.map(symbolic::add(iv_2, symbolic::one()));

    auto iv_3 = symbolic::symbol("_32");
    auto iv3_assume = symbolic::Assumption::create(iv_3, int64_desc);
    iv3_assume.lower_bound_deprecated(symbolic::zero());
    iv3_assume.upper_bound_deprecated(symbolic::sub(sym_d, symbolic::one()));
    iv3_assume.map(symbolic::add(iv_3, symbolic::one()));

    // Collect all assumptions
    symbolic::Assumptions global_assum;
    global_assum.insert({iv_0, iv0_assume});
    global_assum.insert({iv_1, iv1_assume});
    global_assum.insert({iv_2, iv2_assume});
    global_assum.insert({iv_3, iv3_assume});
    global_assum.insert({sym_a, assume_a});
    global_assum.insert({sym_b, assume_b});
    global_assum.insert({sym_c, assume_c});
    global_assum.insert({sym_d, assume_d});

    auto second_set = global_assum;  // Duplicate for comparison

    // Compute strides and offsets
    auto s1 = symbolic::add(symbolic::integer(2), sym_a);
    auto s2 = symbolic::add(symbolic::integer(2), sym_c);
    auto s3 = symbolic::add(symbolic::integer(2), sym_d);

    auto o32 = symbolic::add(symbolic::one(), iv_3);
    auto o28 = symbolic::add(symbolic::one(), iv_2);
    auto o24 = symbolic::add(symbolic::one(), iv_1);

    // expr1: 1 + _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto exprA = symbolic::add(o32, symbolic::mul(s3, o28));
    exprA = symbolic::add(exprA, symbolic::mul(symbolic::mul(s3, s2), o24));
    exprA = symbolic::add(exprA, symbolic::mul(symbolic::mul(symbolic::mul(s3, s2), s1), iv_0));

    // expr2: 1 + _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*_24 + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto exprB = symbolic::add(o32, symbolic::mul(s3, o28));
    exprB = symbolic::add(exprB, symbolic::mul(symbolic::mul(s3, s2), iv_1));
    exprB = symbolic::add(exprB, symbolic::mul(symbolic::mul(symbolic::mul(s3, s2), s1), iv_0));

    EXPECT_FALSE(symbolic::maps::intersects({exprA}, {exprB}, iv_0, global_assum, second_set));
    EXPECT_TRUE(symbolic::maps::intersects({exprA}, {exprB}, iv_1, global_assum, second_set));

    // expr3: 1 + _32 + (2 + _3)*_28 + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto exprC = symbolic::add(o32, symbolic::mul(s3, iv_2));
    exprC = symbolic::add(exprC, symbolic::mul(symbolic::mul(s3, s2), o24));
    exprC = symbolic::add(exprC, symbolic::mul(symbolic::mul(symbolic::mul(s3, s2), s1), iv_0));

    EXPECT_FALSE(symbolic::maps::intersects({exprA}, {exprC}, iv_0, global_assum, second_set));
    EXPECT_TRUE(symbolic::maps::intersects({exprA}, {exprC}, iv_2, global_assum, second_set));

    // expr4: _32 + (2 + _3)*(1 + _28) + (2 + _3)*(2 + _2)*(1 + _24) + (2 + _3)*(2 + _2)*(2 + _1)*_13
    auto exprD = symbolic::add(iv_3, symbolic::mul(s3, o28));
    exprD = symbolic::add(exprD, symbolic::mul(symbolic::mul(s3, s2), o24));
    exprD = symbolic::add(exprD, symbolic::mul(symbolic::mul(symbolic::mul(s3, s2), s1), iv_0));

    EXPECT_FALSE(symbolic::maps::intersects({exprA}, {exprD}, iv_0, global_assum, second_set));
    EXPECT_TRUE(symbolic::maps::intersects({exprA}, {exprD}, iv_3, global_assum, second_set));
}

#include "test.h"
