#include <cstdint>

// Helper function to compute 128-bit MurmurHash3 of the input data
template <typename T>
Array<uint64_t, 2> computeMurmurHash(const T &element) noexcept {
    auto buffer = memory::viewCast(element);
    Array<uint64_t, 2> result;
    MurmurHash3_x64_128(buffer, _nc<int>(buffer.size()), 0, result.data());
    return result;
}

// Compute the nth hash position using double hashing scheme
uint64_t probePosition(uint8_t index, uint64_t primary, uint64_t secondary,
                       uint64_t tableSize) noexcept {
    return (primary + static_cast<uint64_t>(index) * secondary) % tableSize;
}

class BloomFilterImpl {
public:
    BloomFilterImpl(uint64_t capacity, uint8_t hashCount) noexcept
        : m_capacity(capacity), m_hashCount(hashCount),
          m_bitset(capacity, false) {}

    template <typename T>
    void insert(const T &value) noexcept {
        auto rawData = memory::viewCast(value);
        auto hashes = computeMurmurHash(rawData);
        for (uint8_t i = 0; i < m_hashCount; ++i) {
            size_t idx = static_cast<size_t>(
                probePosition(i, hashes[0], hashes[1], m_capacity));
            m_bitset[idx] = true;
        }
    }

    template <typename T>
    bool mightContain(const T &value) const noexcept {
        auto rawData = memory::viewCast(value);
        auto hashes = computeMurmurHash(rawData);
        for (uint8_t i = 0; i < m_hashCount; ++i) {
            size_t idx = static_cast<size_t>(
                probePosition(i, hashes[0], hashes[1], m_capacity));
            if (!m_bitset[idx]) {
                return false;
            }
        }
        return true;
    }

private:
    uint64_t m_capacity;
    uint8_t m_hashCount;
    std::vector<bool> m_bitset;
};

TEST_CASE("util::BloomFilter") {
    BloomFilterImpl filter(1'000, 13);

    // Insert all even numbers from 0 to 999
    int insertedCount = 0;
    for (int value = 0; value < 1000; ++value) {
        if (value % 2 == 0) {
            filter.insert(value);
            insertedCount++;
        }
    }

    // Test membership for all numbers in range
    int likelyFound = 0, definitelyNot = 0, falseNegatives = 0;
    for (int value = 0; value < 1000; ++value) {
        bool result = filter.mightContain(value);
        if (result) {
            likelyFound++;
        } else {
            definitelyNot++;
            if (value % 2 == 0) {
                LOG(Test, "False negative: Filter reports {} as absent", value);
                falseNegatives++;
            }
        }
    }

    LOG(Test, "Possibly present: {,c} | Definitely absent: {,c} | Inserted: "
              "{,c} | Errors: {,c}",
        likelyFound, definitelyNot, insertedCount, falseNegatives);
}

