    bool InputField::IsNextCharacterFit()
    {
        const auto currentText = m_label.GetString();
        const auto caretPos = m_caret.Index;
        const auto selLen = m_caret.SelectionLength;

        // Temporarily erase selection if any
        if (selLen != 0)
        {
            const auto insertPos = (caretPos > 0) ? caretPos - 1 : 0;
            Erase(insertPos, selLen);
        }

        // Test insertion of space
        auto testText = m_label.GetString();
        testText.insert(caretPos, " ");
        m_label.SetString(testText);

        const bool fits = m_label.GetLocalBounds().size.x <= m_bounds.size.x;

        // Restore original text
        m_label.SetString(currentText);
        return fits;
    }

    void InputField::Select(const std::size_t index, const int selectionLength)
    {
