    sf::String InputField::GetSelectedText() const
    {
        auto caretPos = m_caret.Index - 1;
        const auto selLen = m_caret.SelectionLength;

        if (selLen == 0)
            return {};

        if (selLen < 0)
            caretPos += selLen + 1;
        else
            caretPos++;

        return m_label.GetString().substring(caretPos, std::abs(selLen));
    }

    size_t InputField::Insert(size_t index, const std::uint32_t unicode, const int selectionLength)
    {
        // Ignore control characters
        if (unicode <= 31 || unicode == 127)
            return index;

        // Check maximum length constraint
        if (m_maxLength > 0 && selectionLength == 0 && m_label.GetString().getSize() >= m_maxLength)
            return index;

        // Check visual bounds
        if (IsNextCharacterFit())
        {
            if (m_caret.SelectionLength != 0)
                index = Erase(index - 1, selectionLength);

            auto text = m_label.GetString();
            text.insert(index, sf::String(static_cast<char32_t>(unicode)));
            m_label.SetString(text);
            return ++index;
        }
        return index;
    }

    std::size_t InputField::Erase(std::size_t index, const int length)
    {
        if (length == 0)
            return index;

        if (length < 0)
            index += length + 1;
        else
            index++;

        auto text = m_label.GetString();
        text.erase(index, std::abs(length));
        m_label.SetString(text);
        return index;
    }

