    void InputField::OnControlClick(Control& sender, const sf::Event::MouseButtonReleased& ev)
    {
        float minDistance = -1.0f;
        size_t selectIndex = m_caret.Index;
        const auto bounds = GetGlobalBounds();

        for (size_t i = 0; i <= m_label.GetString().getSize(); i++)
        {
            const float xPos = FindCharacterPosition(i).x + bounds.position.x;
            const float distance = std::abs(xPos - static_cast<float>(ev.position.x));

            if (minDistance == -1.0f || distance < minDistance)
            {
                selectIndex = i;
                minDistance = distance;
            }
            else if (distance > minDistance)
                break;
        }

        Select(selectIndex, 0);
        Control::OnControlClick(sender, ev);
    }

