    void InputField::OnKeyPressed(const sf::Event::KeyPressed& ev)
    {
        if (!IsEnabled() || !IsFocused())
            return;

        bool control = ev.control;
#ifdef __APPLE__
        control = ev.system;
#endif

        // Handle backspace and delete
        if (ev.code == sf::Keyboard::Key::Backspace || 
           (ev.code == sf::Keyboard::Key::Delete && m_caret.SelectionLength != 0))
        {
            if (m_caret.Index == 0 && m_caret.SelectionLength == 0)
                return;

            int eraseLen = (m_caret.SelectionLength == 0) ? -1 : m_caret.SelectionLength;

            if (m_caret.SelectionLength == 0 && control)
            {
                if (!ev.shift)
                {
                    const size_t wordStart = FindWordStart(m_label.GetString(), static_cast<size_t>(m_caret.Index));
                    eraseLen = -static_cast<int>(static_cast<size_t>(m_caret.Index) - wordStart);
                }
                else
                {
                    eraseLen = -static_cast<int>(static_cast<size_t>(m_caret.Index));
                }
            }

            m_caret.Index = static_cast<int>(Erase(m_caret.Index - 1, eraseLen));
            m_caret.SelectionLength = 0;
        }
        else if (ev.code == sf::Keyboard::Key::Delete)
        {
            if (m_caret.Index >= static_cast<int>(m_label.GetString().getSize()))
                return;

            if (control && ev.shift)
            {
                const size_t from = static_cast<size_t>(m_caret.Index);
                const size_t end = m_label.GetString().getSize();
                const int delta = static_cast<int>(end - from);
                if (delta <= 0)
                    return;
                m_caret.Index = static_cast<int>(Erase(m_caret.Index - 1, delta));
                m_caret.SelectionLength = 0;
            }
            else if (control)
            {
                const size_t from = static_cast<size_t>(m_caret.Index);
                const size_t wordEnd = FindWordEnd(m_label.GetString(), from);
                const int delta = static_cast<int>(wordEnd - from);
                if (delta <= 0)
                    return;
                m_caret.Index = static_cast<int>(Erase(m_caret.Index - 1, delta));
                m_caret.SelectionLength = 0;
            }
            else
            {
                auto text = m_label.GetString();
                if (m_caret.Index < static_cast<int>(text.getSize()))
                    text.erase(m_caret.Index);
                m_label.SetString(text);
                m_caret.SelectionLength = 0;
            }
        }
        else if (ev.code == sf::Keyboard::Key::Enter)
        {
            const sf::String trimmed = StringHelper::Trim(m_label.GetString());
            if (!trimmed.isEmpty() && m_onTextEntered)
                m_onTextEntered(*this, trimmed);
            m_label.SetString("");
            m_caret.SelectionLength = 0;
        }
        else if (control || ev.shift)
        {
            if (ev.shift)
            {
                if (control && ev.code == sf::Keyboard::Key::Left)
                {
                    if (m_caret.Index <= 0)
                        return;
                    const size_t from = static_cast<size_t>(m_caret.Index);
                    const size_t wordStart = FindWordStart(m_label.GetString(), from);
                    const int delta = static_cast<int>(from - wordStart);
                    if (delta <= 0)
                        return;
                    m_caret.Index -= delta;
                    m_caret.SelectionLength += delta;
                }
                else if (control && ev.code == sf::Keyboard::Key::Right)
                {
                    if (m_caret.Index >= static_cast<int>(m_label.GetString().getSize()))
                        return;
                    const size_t from = static_cast<size_t>(m_caret.Index);
                    const size_t wordEnd = FindWordEnd(m_label.GetString(), from);
                    const int delta = static_cast<int>(wordEnd - from);
                    if (delta <= 0)
                        return;
                    m_caret.Index += delta;
                    m_caret.SelectionLength -= delta;
                }
                else if (ev.code == sf::Keyboard::Key::Left)
                {
                    if (m_caret.Index <= 0)
                        return;
                    m_caret.Index--;
                    m_caret.SelectionLength++;
                }
                else if (ev.code == sf::Keyboard::Key::Right)
                {
                    if (m_caret.Index >= static_cast<int>(m_label.GetString().getSize()))
                        return;
                    m_caret.Index++;
                    m_caret.SelectionLength--;
                }
            }

            if (control)
            {
                if (ev.code == sf::Keyboard::Key::C || ev.code == sf::Keyboard::Key::X)
                {
                    sf::Clipboard::setString(GetSelectedText());
                    if (ev.code == sf::Keyboard::Key::X)
                    {
                        m_caret.Index = static_cast<int>(Erase(m_caret.Index - 1, m_caret.SelectionLength));
                        m_caret.SelectionLength = 0;
                    }
                }
                else if (ev.code == sf::Keyboard::Key::V)
                {
                    std::string clipboardText = sf::Clipboard::getString();
                    auto text = sf::String::fromUtf32(clipboardText.begin(), clipboardText.end());
                    for (size_t i = 0; i < text.getSize(); i++)
                        m_caret.Index = static_cast<int>(Insert(m_caret.Index, text[i]));
                }
                else if (ev.code == sf::Keyboard::Key::A)
                {
                    SelectAll();
                }
                else if (!ev.shift && ev.code == sf::Keyboard::Key::Left)
                {
                    const size_t wordStart = FindWordStart(m_label.GetString(), static_cast<size_t>(m_caret.Index));
                    m_caret.Index = static_cast<int>(wordStart);
                    m_caret.SelectionLength = 0;
                }
                else if (!ev.shift && ev.code == sf::Keyboard::Key::Right)
                {
                    const size_t wordEnd = FindWordEnd(m_label.GetString(), static_cast<size_t>(m_caret.Index));
                    m_caret.Index = static_cast<int>(wordEnd);
                    m_caret.SelectionLength = 0;
                }
            }
        }
        else if (ev.code == sf::Keyboard::Key::Left)
        {
            m_caret.Index--;
            m_caret.SelectionLength = 0;
            m_label.SetColor(m_label.GetColor());
        }
        else if (ev.code == sf::Keyboard::Key::Right)
        {
            m_caret.Index++;
            m_caret.SelectionLength = 0;
            m_label.SetColor(m_label.GetColor());
        }
        else
            return;

        Invalidate();
    }

    void InputField::OnTextEntered(const sf::Event::TextEntered& ev)
    {
        if (!IsEnabled() || !IsFocused())
            return;

        // Ignore control characters
        if (ev.unicode <= 31)
            return;

#ifdef __APPLE__
        // Delete key
        if (ev.unicode == 127)
            return;
#endif

        // Only accept numbers in numeric mode
        if (m_numeric && (ev.unicode < 48 || ev.unicode > 57))
            return;

        m_caret.Index = static_cast<int>(Insert(m_caret.Index, ev.unicode, m_caret.SelectionLength));
        m_caret.SelectionLength = 0;
        Invalidate();
    }

    void InputField::Invalidate()
    {
        m_caret.Invalidate();
        m_caret.Reset(true);

        size_t start = m_caret.Index;
        if (m_caret.SelectionLength < 0)
            start += m_caret.SelectionLength;

        m_label.SetColor(m_label.GetColor());

        if (m_caret.SelectionLength != 0)
        {
            const auto text = m_label.GetString();
            const size_t end = start + std::abs(m_caret.SelectionLength);
            for (size_t i = 0; i < text.getSize(); i++)
            {
                if (i >= start && i < end)
                    m_label.SetColor(m_highlightColor, i);
            }
        }
    }
}

namespace Gx
{
    InputField::Caret::Caret(InputField& instance) :
        Instance(instance),
        Index(0),
        SelectionLength(0),
        m_cursor(),
        m_highlight(),
        m_visible(true),
        m_elapsed(0.0)
    {
        SetHighlightColor(sf::Color::Transparent);
        Invalidate();
    }

    void InputField::Caret::Reset(const bool visible)
    {
        m_elapsed = 0.0;
        m_visible = visible;
    }

    const Rectangle& InputField::Caret::GetHighlight() const
    {
        return m_highlight;
    }

    void InputField::Caret::SetHighlightColor(const sf::Color color)
    {
        m_highlight.SetColor(color);
    }

    RenderStates InputField::Caret::Render(RenderSurface& surface, RenderStates states) const
    {
        if (!m_visible)
            return states;
        surface.Render(m_cursor, states);
        return states;
    }

    void InputField::Caret::Update(const double delta)
    {
        m_elapsed += delta;
        if (m_elapsed >= BLINK_THRESHOLD)
        {
            m_elapsed = 0.0;
            m_visible = !m_visible;
        }
    }

    void InputField::Caret::Invalidate()
    {
        // Clamp index to valid range
        if (Index < 0)
            Index = 0;
        if (Index > static_cast<int>(Instance.GetString().getSize()))
            Index = static_cast<int>(Instance.GetString().getSize());

        if (Instance.GetFont())
        {
            const auto glyph = Instance.GetFont()->GetGlyph('|', 0, Instance.GetCharacterSize(), false);
            m_cursor.SetSize(sf::Vector2f(glyph.bounds.size.x * 0.65f, static_cast<float>(Instance.GetCharacterSize())));
        }

        m_cursor.SetPosition(Instance.FindCharacterPosition(Index) + sf::Vector2f(0.f, 1.5f));
        m_cursor.SetColor(Instance.GetColor());

        if (SelectionLength != 0)
        {
            size_t pos = Index - 1;
            const int len = SelectionLength;

            if (len < 0)
                pos += len + 1;
            else if (len > 0)
                pos++;

            const auto charPos = Instance.FindCharacterPosition(pos);
            const auto endPos = Instance.FindCharacterPosition(pos + std::abs(len));

            m_highlight.SetPosition(sf::Vector2f(charPos.x, m_cursor.GetPosition().y));
            m_highlight.SetSize(sf::Vector2f(std::abs(charPos.x - endPos.x), static_cast<float>(Instance.GetCharacterSize())));
        }
        else
        {
            m_highlight.SetSize(sf::Vector2f());
        }
    }
}

#include "fonticon.h"
#include "resources.h"
#include <QIconEngine>
#include <QPainter>
#include <QPixmapCache>

using namespace OCC::Resources;

namespace {

class IconFontRenderer : public QIconEngine
{
public:
    IconFontRenderer(FontIcon::FontFamily family, QChar symbol, FontIcon::Size scale, const QColor &ink)
        : _fontFamily(family)
        , _glyphCode(symbol)
        , _fontSizeLevel(scale)
        , _inkColor(ink.isValid() ? ink : OCC::Resources::tint())
    {
    }

    void render(QPainter *canvas, const QRect &target, QIcon::Mode, QIcon::State) override
    {
        canvas->save();
        canvas->setRenderHint(QPainter::Antialiasing);

        auto currentPen = canvas->pen();
        currentPen.setColor(_inkColor);
        canvas->setPen(currentPen);

        auto currentFont = canvas->font();

        switch (_fontFamily) {
        case FontIcon::FontFamily::FontAwesome:
            currentFont.setFamily(QStringLiteral("Font Awesome 6 Free"));
            break;
        case FontIcon::FontFamily::RemixIcon:
            currentFont.setFamily(QStringLiteral("remixicon"));
            break;
        }

        int targetHeight = target.height();
        switch (_fontSizeLevel) {
        case FontIcon::Size::Normal:
            currentFont.setPixelSize(targetHeight);
            break;
        case FontIcon::Size::Half:
            currentFont.setPixelSize(static_cast<int>(targetHeight / 2.0));
            break;
        }

        // Center alignment for rendering
        const Qt::Alignment alignFlags = Qt::AlignCenter;

        QFontMetricsF fontMetrics(currentFont);
        QRectF glyphBounds = fontMetrics.boundingRect(target, static_cast<int>(alignFlags), _glyphCode);

        // Adjust font size if glyph overflows bounds
        if (glyphBounds.width() > target.width()) {
            double scaleFactor = qMin(
                target.width() * 0.95 / glyphBounds.width(),
                fontMetrics.height() * 0.95 / glyphBounds.height()
            );
            int adjustedSize = static_cast<int>(currentFont.pixelSize() * scaleFactor);
            currentFont.setPixelSize(adjustedSize);
        }

        canvas->setFont(currentFont);
        canvas->drawText(target, static_cast<int>(alignFlags), _glyphCode);
        canvas->restore();
    }

    QPixmap generatePixmap(const QSize &dimensions, QIcon::Mode mode, QIcon::State state) override
    {
        QPixmap result;
        const QString cacheKey = buildCacheKey(dimensions, mode, state);

        if (QPixmapCache::find(cacheKey, &result)) {
            return result;
        }

        result = QPixmap(dimensions);
        result.fill(Qt::transparent);
        QPainter painter(&result);
        render(&painter, {{0, 0}, dimensions}, mode, state);
        painter.end();

        QPixmapCache::insert(cacheKey, result);
        return result;
    }

    QIconEngine *duplicate() const override
    {
        return new IconFontRenderer(this->_fontFamily, this->_glyphCode, this->_fontSizeLevel, this->_inkColor);
    }

    QString buildCacheKey(const QSize &size, QIcon::Mode mode, QIcon::State state) const
    {
        return QStringLiteral("FontIcon:%1")
            .arg(QString::number(qHashMulti(0, _fontFamily, _glyphCode, _fontSizeLevel, _inkColor.rgb(), size, mode, state), 16));
    }

private:
    const FontIcon::FontFamily _fontFamily;
    const QChar _glyphCode;
    const FontIcon::Size _fontSizeLevel;
    const QColor _inkColor;
};

} // anonymous namespace

// Public API implementations
FontIcon::FontIcon() { }

FontIcon::FontIcon(QChar symbol, Size scale, const QColor &ink)
    : QIcon(new IconFontRenderer(FontFamily::FontAwesome, symbol, scale, ink))
{
}

FontIcon::FontIcon(DefaultGlyphes symbol, Size scale, const QColor &ink)
    : FontIcon(static_cast<std::underlying_type_t<DefaultGlyphes>>(symbol), scale, ink)
{
}

FontIcon::FontIcon(FontFamily family, QChar symbol, Size scale, const QColor &ink)
    : QIcon(new IconFontRenderer(family, symbol, scale, ink))
{
}

#include "sdfg/targets/highway/codegen/highway_map_dispatcher.h"
#include "sdfg/targets/highway/schedule.h"
#include "sdfg/transformations/highway_transform.h"
#include <sdfg/analysis/loop_analysis.h>
#include <sdfg/analysis/users.h>
#include <sdfg/codegen/dispatchers/node_dispatcher_registry.h>
#include <sdfg/codegen/dispatchers/sequence_dispatcher.h>
#include <sdfg/codegen/instrumentation/instrumentation_info.h>
#include <sdfg/codegen/utils.h>
#include <sdfg/helpers/helpers.h>
#include <sdfg/structured_control_flow/map.h>

namespace sdfg {
namespace highway {

HighwayMapDispatcher::HighwayMapDispatcher(
    codegen::LanguageExtension& lang_ext,
    StructuredSDFG& graph_sdfg,
    analysis::AnalysisManager& analysis_mgr,
    structured_control_flow::Map& map_node,
    codegen::InstrumentationPlan& instr_plan,
    codegen::ArgCapturePlan& arg_capture_plan
)
    : NodeDispatcher(lang_ext, graph_sdfg, analysis_mgr, map_node, instr_plan, arg_capture_plan),
      map_node_(map_node), index_var_(map_node.indvar()), args_(), args_decl_(), args_lookup_(), locals_(),
      local_syms_(), simd_type_(types::PrimitiveType::Double) {

    auto& args_analysis = analysis_mgr.get<analysis::ArgumentsAnalysis>();
    for (auto& entry : args_analysis.arguments(analysis_mgr, map_node_)) {
        args_.push_back(entry.first);
        args_lookup_.insert(entry.first);
        auto& type = graph_sdfg.type(entry.first);
        codegen::Reference ref_type(type);
        args_decl_.push_back(this->lang_ext_.declaration(entry.first, ref_type));
    }

    for (auto& local_var : args_analysis.locals(analysis_mgr, map_node_)) {
        locals_.insert(local_var);
        if (local_var == index_var_->get_name()) {
            continue;
        }
        auto& type = graph_sdfg.type(local_var);
        if (types::is_integer(type.primitive_type())) {
            local_syms_.insert(symbolic::symbol(local_var));
        }
    }
};

void HighwayMapDispatcher::emit_kernel_call(codegen::PrettyPrinter& main_stream, const std::string& func_name) {
    main_stream << func_name << "(" << helpers::join(args_, ", ") << ");" << std::endl;
};

void HighwayMapDispatcher::
    emit_kernel_signature(codegen::PrettyPrinter& globals_stream, const std::string& func_name) {
    if (this->lang_ext_.language() == "C") {
        globals_stream << "void " << func_name << "(" << helpers::join(args_decl_, ", ") << ");"
                       << std::endl;
    } else {
        globals_stream << "extern \"C\" void " << func_name << "(" << helpers::join(args_decl_, ", ")
                       << ");" << std::endl;
    }
};

void HighwayMapDispatcher::emit_kernel_header(codegen::PrettyPrinter& lib_stream, const std::string& func_name) {
    lib_stream << "HWY_ATTR void ";
    lib_stream << func_name;
    lib_stream << "(";
    lib_stream << helpers::join(args_decl_, ", ");
    lib_stream << ")" << std::endl;
};

void HighwayMapDispatcher::
    emit_kernel_implementation(codegen::CodeSnippetFactory& snippet_factory, codegen::PrettyPrinter& lib_stream) {
    // Define SIMD vector types
    lib_stream << "const hn::ScalableTag<uint8_t> vec_u8;" << std::endl;
    lib_stream << "const hn::ScalableTag<uint16_t> vec_u16;" << std::endl;
    lib_stream << "const hn::ScalableTag<uint32_t> vec_u32;" << std::endl;
    lib_stream << "const hn::ScalableTag<uint64_t> vec_u64;" << std::endl;
    lib_stream << "const hn::ScalableTag<int8_t> vec_s8;" << std::endl;
    lib_stream << "const hn::ScalableTag<int16_t> vec_s16;" << std::endl;
    lib_stream << "const hn::ScalableTag<int32_t> vec_s32;" << std::endl;
    lib_stream << "const hn::ScalableTag<int64_t> vec_s64;" << std::endl;
    lib_stream << "const hn::ScalableTag<float> vec_f32;" << std::endl;
    lib_stream << "const hn::ScalableTag<double> vec_f64;" << std::endl;
    lib_stream << std::endl;

    // Declare induction variable
    auto& idx_type = graph_sdfg().type(index_var_->get_name());
    lib_stream << this->lang_ext_.declaration(index_var_->get_name(), idx_type);
    lib_stream << " = " << lang_ext_.expression(map_node_.init()) << ";" << std::endl;

    // Vectorized loop section
    lib_stream << "{" << std::endl;
    lib_stream.setIndent(lib_stream.indent() + 4);

    // Local variable declarations
    for (auto& local_var : locals_) {
        if (local_var == index_var_->get_name()) {
            continue;
        }
        lib_stream << this->declaration(local_var, dynamic_cast<const types::Scalar&>(graph_sdfg.type(local_var))) << ";"
                   << std::endl;
    }

    // Vectorized iteration logic
    auto update_width = symbolic::symbol("hn::Lanes(" + get_simd_tag(simd_type_) + ")");
    auto condition_expr = symbolic::subs(map_node_.condition(), index_var_, symbolic::add(index_var_, update_width));

    lib_stream << "for";
    lib_stream << "(";
    lib_stream << ";";
    lib_stream << lang_ext_.expression(condition_expr);
    lib_stream << ";";
    lib_stream << lang_ext_.expression(index_var_);
    lib_stream << " = ";
    lib_stream << lang_ext_.expression(symbolic::add(index_var_, update_width));
    lib_stream << ")" << std::endl;

    // Vectorized loop body
    lib_stream << "{" << std::endl;
    lib_stream.setIndent(lib_stream.indent() + 4);
    this->process_highway_nodes(snippet_factory, lib_stream, map_node_.root());
    lib_stream.setIndent(lib_stream.indent() - 4);
    lib_stream << "}" << std::endl;
    lib_stream.setIndent(lib_stream.indent() - 4);
    lib_stream << "}" << std::endl;

    // Scalar cleanup loop for remaining elements
    lib_stream << "{" << std::endl;
    lib_stream.setIndent(lib_stream.indent() + 4);

    // Local variable declarations for scalar loop
    for (auto& local_var : locals_) {
        if (local_var == index_var_->get_name()) {
            continue;
        }
        lib_stream << this->lang_ext_.declaration(local_var, graph_sdfg.type(local_var)) << ";" << std::endl;
    }

    // Scalar loop header
    lib_stream << "for";
    lib_stream << "(";
    lib_stream << ";";
    lib_stream << lang_ext_.expression(map_node_.condition());
    lib_stream << ";";
    lib_stream << lang_ext_.expression(index_var_);
    lib_stream << " = ";
    lib_stream << lang_ext_.expression(map_node_.update());
    lib_stream << ")" << std::endl;

    // Scalar loop body
    lib_stream << "{" << std::endl;
    lib_stream.setIndent(lib_stream.indent() + 4);
    codegen::SequenceDispatcher seq_disp(
        lang_ext_, graph_sdfg(), analysis_manager_, map_node_.root(), instrumentation_plan_, arg_capture_plan_
    );
    seq_disp.dispatch(lib_stream, lib_stream, snippet_factory);
    lib_stream.setIndent(lib_stream.indent() - 4);
    lib_stream << "}" << std::endl;
    lib_stream.setIndent(lib_stream.indent() - 4);
    lib_stream << "}" << std::endl;
};

void HighwayMapDispatcher::dispatch_node(
    codegen::PrettyPrinter& main_stream,
    codegen::PrettyPrinter& globals_stream,
    codegen::CodeSnippetFactory& snippet_factory
) {
    std::string kernel_id = "highway_kernel_" + std::to_string(map_node_.element_id());

    // Emit kernel invocation
    this->emit_kernel_call(main_stream, kernel_id);
    this->emit_kernel_signature(globals_stream, kernel_id);

    // Generate kernel implementation
    auto& lib_stream = snippet_factory.require(kernel_id, "cpp", true).stream();
    std::filesystem::path sdfg_path = graph_sdfg().metadata("sdfg_file");
    std::filesystem::path kernel_file = sdfg_path.parent_path() / (kernel_id + ".cpp");
    lib_stream << "#include " << snippet_factory.header_path().filename() << std::endl;
    lib_stream << "#include <hwy/highway.h>" << std::endl;
    lib_stream << "#include <hwy/contrib/math/math-inl.h>" << std::endl;
    lib_stream << std::endl;

    // Namespace wrapper
    lib_stream << "namespace HWY_NAMESPACE {" << std::endl;
    lib_stream << "namespace hn = hwy::HWY_NAMESPACE;" << std::endl << std::endl;

    // Kernel function header
    this->emit_kernel_header(lib_stream, kernel_id);
    lib_stream << "{" << std::endl;
    lib_stream.setIndent(lib_stream.indent() + 4);
    this->emit_kernel_implementation(snippet_factory, lib_stream);
    lib_stream.setIndent(lib_stream.indent() - 4);
    lib_stream << "}" << std::endl;

    // End namespace
    lib_stream << std::endl;
    lib_stream << "}" << std::endl;

    // Wrapper function for dispatch
    lib_stream << std::endl;
    lib_stream << "extern \"C\" void " << kernel_id;
    lib_stream << "(";
    lib_stream << helpers::join(args_decl_, ", ");
    lib_stream << ")" << std::endl;
    lib_stream << "{" << std::endl;
    lib_stream.setIndent(lib_stream.indent() + 4);
    lib_stream << "HWY_STATIC_DISPATCH";
    lib_stream << "(" << kernel_id << ")";
    lib_stream << "(";
    lib_stream << helpers::join(args_, ", ");
    lib_stream << ");" << std::endl;
    lib_stream.setIndent(lib_stream.indent() - 4);
    lib_stream << "}" << std::endl << std::endl;
};

void HighwayMapDispatcher::process_highway_nodes(
    codegen::CodeSnippetFactory& snippet_factory,
    codegen::PrettyPrinter& lib_stream,
    structured_control_flow::ControlFlowNode& node
) {
    if (auto block_node = dynamic_cast<structured_control_flow::Block*>(&node)) {
        this->process_highway_nodes(snippet_factory, lib_stream, *block_node);
    } else if (auto sequence_node = dynamic_cast<structured_control_flow::Sequence*>(&node)) {
        this->process_highway_nodes(snippet_factory, lib_stream, *sequence_node);
    } else {
        throw InvalidSDFGException(
            "Schedule type Highway applied on unsupported control flow node: " + std::string(typeid(node).name())
        );
    }
}

void HighwayMapDispatcher::process_highway_nodes(
    codegen::CodeSnippetFactory& snippet_factory,
    codegen::PrettyPrinter& lib_stream,
    structured_control_flow::Sequence& node
) {
    for (size_t i = 0; i < node.size(); i++) {
        if (!node.at(i).second.assignments().empty()) {
            throw InvalidSDFGException("Highway schedule does not support transitions with assignments");
        }
        auto& child_node = node.at(i).first;
        this->process_highway_nodes(snippet_factory, lib_stream, child_node);
    }
}

void HighwayMapDispatcher::process_highway_nodes(
    codegen::CodeSnippetFactory& snippet_factory,
    codegen::PrettyPrinter& lib_stream,
    structured_control_flow::Block& node
) {
    auto& args_analysis = analysis_manager_.get<analysis::ArgumentsAnalysis>();
    auto locals = args_analysis.locals(analysis_manager_, map_node_);
    symbolic::SymbolSet local_symbols;
    for (auto& local_var : locals) {
        auto& type = graph_sdfg().type(local_var);
        if (types::is_integer(type.primitive_type())) {
            local_symbols.insert(symbolic::symbol(local_var));
        }
    }

    auto& dataflow_graph = node.dataflow();
    for (auto& dnode : dataflow_graph.topological_sort()) {
        if (auto access_node = dynamic_cast<data_flow::AccessNode*>(dnode)) {
            continue;
        }

        lib_stream << "{" << std::endl;
        lib_stream.setIndent(lib_stream.indent() + 4);

        // Input edge processing
        for (auto& iedge : dataflow_graph.in_edges(*dnode)) {
            this->process_input_edge(lib_stream, iedge);
        }

        // Output connector declaration
        auto& oedge = *dataflow_graph.out_edges(*dnode).begin();
        auto& dst_node = static_cast<data_flow::AccessNode&>(oedge.dst());
        lib_stream << "auto " << oedge.src_conn() << " = hn::Undefined(";
        lib_stream << get_simd_tag(oedge.base_type().primitive_type()) << ");" << std::endl;
        lib_stream << std::endl;

        // Process data flow nodes
        if (auto tasklet = dynamic_cast<data_flow::Tasklet*>(dnode)) {
            std::string tasklet_code;
            if (tasklet->is_fptosi(this->graph_sdfg()) || tasklet->is_sitofp(this->graph_sdfg()) || 
                tasklet->is_uitofp(this->graph_sdfg()) || tasklet->is_fptoui(this->graph_sdfg())) {
                tasklet_code = tasklet->output() + " = hn::ConvertTo(" +
                               get_simd_tag(oedge.base_type().primitive_type()) + ", " +
                               tasklet->input(0) + ");";
            } else {
                tasklet_code = process_tasklet(*tasklet);
            }
            if (tasklet_code.empty()) {
                throw InvalidSDFGException("Schedule type Highway applied on unsupported tasklet node");
            }
            lib_stream << tasklet_code << std::endl;
        } else if (auto cmath_node = dynamic_cast<math::cmath::CMathNode*>(dnode)) {
            std::string cmath_code = process_cmath_node(*cmath_node);
            if (cmath_code.empty()) {
                throw InvalidSDFGException("Schedule type Highway applied on unsupported CMath node");
            }
            lib_stream << cmath_code << std::endl;
        } else {
            throw InvalidSDFGException("Schedule type Highway applied on unsupported data flow node");
        }

        lib_stream << std::endl;

        // Store result
        if (locals.find(dst_node.data()) != locals.end()) {
            // Local variable assignment
            lib_stream << dst_node.data() << " = " << oedge.src_conn() << ";" << std::endl;
        } else {
            // Store to memory
            lib_stream << "hn::StoreU(" << oedge.src_conn() << ", ";
            lib_stream << get_simd_tag(oedge.base_type().primitive_type()) << ", ";
            lib_stream << "&";
            lib_stream << "(" << this->lang_ext_.type_cast(dst_node.data(), oedge.base_type()) << ")";
            lib_stream << this->lang_ext_.subset(oedge.base_type(), oedge.subset());
            lib_stream << ");" << std::endl;
        }

        lib_stream.setIndent(lib_stream.indent() - 4);
        lib_stream << "}" << std::endl;
    }
};

std::string HighwayMapDispatcher::get_simd_tag(const types::PrimitiveType& type) {
    switch (type) {
        case types::PrimitiveType::Int8:
            return "vec_s8";
        case types::PrimitiveType::Int16:
            return "vec_s16";
        case types::PrimitiveType::Int32:
            return "vec_s32";
        case types::PrimitiveType::Int64:
            return "vec_s64";
        case types::PrimitiveType::UInt8:
            return "vec_u8";
        case types::PrimitiveType::UInt16:
            return "vec_u16";
        case types::PrimitiveType::UInt32:
            return "vec_u32";
        case types::PrimitiveType::UInt64:
            return "vec_u64";
        case types::PrimitiveType::Float:
            return "vec_f32";
        case types::PrimitiveType::Double:
            return "vec_f64";
        default:
            throw InvalidSDFGException("Schedule type Highway applied on unsupported types");
    }
}

