using namespace wowee;

void printUsage(const char* progName) {
    std::cerr << "Usage:\n"
              << "  " << progName << " <host> <port> <account> <major> <minor> <patch> <build> <proto> <locale> [platform] [os]\n"
              << "Example:\n"
              << "  " << progName << " logon.turtle-server-eu.kz 3724 test 1 12 1 5875 8 enGB x86 Win\n";
}

int main(int argc, char** argv) {
    if (argc < 10) {
        printUsage(argv[0]);
        return EXIT_FAILURE;
    }

    // Parse command-line arguments
    const std::string serverHost{argv[1]};
    const int serverPort = std::atoi(argv[2]);
    const std::string accountName{argv[3]};
    const int verMajor = std::atoi(argv[4]);
    const int verMinor = std::atoi(argv[5]);
    const int verPatch = std::atoi(argv[6]);
    const int buildNum = std::atoi(argv[7]);
    const int protoVer = std::atoi(argv[8]);
    const std::string localeCode{argv[9]};
    const std::string platformArch = (argc > 10) ? argv[10] : "x86";
    const std::string osName = (argc > 11) ? argv[11] : "Win";

    // Construct client info structure
    auth::ClientInfo clientInfo{};
    clientInfo.majorVersion = static_cast<uint8_t>(verMajor);
    clientInfo.minorVersion = static_cast<uint8_t>(verMinor);
    clientInfo.patchVersion = static_cast<uint8_t>(verPatch);
    clientInfo.build = static_cast<uint16_t>(buildNum);
    clientInfo.protocolVersion = static_cast<uint8_t>(protoVer);
    clientInfo.locale = localeCode;
    clientInfo.platform = platformArch;
    clientInfo.os = osName;

    // Synchronization flags for async response handling
    std::atomic<bool> completed{false};
    std::atomic<int> statusResult{0xFF};
    std::atomic<bool> receivedResponse{false};

    network::TCPSocket socket;
    socket.setPacketCallback([&](const network::Packet& incoming) {
        if (incoming.getSize() < 3U) {
            return;
        }

        const uint8_t opCode = incoming.readUInt8();
        if (opCode != static_cast<uint8_t>(auth::AuthOpcode::LOGON_CHALLENGE)) {
            return;
        }

        auth::LogonChallengeResponse parsedResp{};
        if (!auth::LogonChallengeResponseParser::parse(incoming, parsedResp)) {
            std::cerr << "Failed to parse authentication response packet\n";
            statusResult = 0xFE;
        } else {
            statusResult = static_cast<int>(parsedResp.result);
            if (parsedResp.isSuccess()) {
                std::cerr << "Authentication succeeded. Security flags: 0x"
                          << std::hex << static_cast<int>(parsedResp.securityFlags)
                          << std::dec << '\n';
            } else {
                std::cerr << "Authentication failed. Error code: 0x"
                          << std::hex << static_cast<int>(parsedResp.result)
                          << std::dec << " (" << auth::getAuthResultString(parsedResp.result) << ")\n";
            }
        }

        receivedResponse = true;
        completed = true;
    });

    // Attempt connection
    if (!socket.connect(serverHost, static_cast<uint16_t>(serverPort))) {
        std::cerr << "Connection to server failed\n";
        return EXIT_FAILURE + 1;
    }

    // Send login challenge
    auto loginPacket = auth::LogonChallengePacket::build(accountName, clientInfo);
    socket.send(loginPacket);

    // Wait for response with timeout
    constexpr auto TIMEOUT_MS = std::chrono::milliseconds(4000);
    auto startTime = std::chrono::steady_clock::now();

    while (!completed) {
        socket.update();
        std::this_thread::sleep_for(std::chrono::milliseconds(10));

        auto elapsed = std::chrono::steady_clock::now() - startTime;
        if (std::chrono::duration_cast<std::chrono::milliseconds>(elapsed).count() > TIMEOUT_MS.count()) {
            break;
        }
    }

    socket.disconnect();

    if (!receivedResponse) {
        std::cerr << "Timed out waiting for server response\n";
        return EXIT_FAILURE + 2;
    }

    return statusResult.load();
}

