// Helper to simulate global state for arguments (since arg_0 is used across functions)
struct Context {
    unsigned int arg0;
    int result;
};

Context ctx{};

// Original _simple_math: computes arg0 = arg1^2 + 42
void simpleMath(unsigned int arg1) {
    unsigned int product = arg1 * arg1;
    ctx.arg0 = product + 42;
}

// Original _diamond_cfg: if (tmp2 <= 0) decrement arg0, else increment
void diamondCfg(int condition) {
    if (condition <= 0) {
        --ctx.arg0;
    } else {
        ++ctx.arg0;
    }
}

// Original _loop_cfg: simulates loop via arithmetic
void loopCfg(int flag) {
    unsigned int temp1 = 0;
    unsigned int temp2 = 0;

    // Simulate initialization
    temp1 = temp2; // both zero
    temp2 -= temp1; // still zero

    if (flag >= 0) {
        ctx.arg0 = temp2;
    } else {
        temp1 = temp2;
        temp2 += temp1;
        ctx.arg0 = temp2 + 1;
    }
}

// Original _nested_cfg: returns 3, 2, or 1 based on nested conditions
void nestedCfg(int val) {
    if (val <= 0) {
        ctx.arg0 = 3;
    } else {
        if (val >= 0) {
            ctx.arg0 = 2;
        } else {
            ctx.arg0 = 1;
        }
    }
}

int main() {
    unsigned int localVar = 0;
    int returnVal = 0;

    // Simulate stack frame setup
    unsigned long stackPtr = reinterpret_cast<unsigned long>(new char[96]);
    unsigned long frameBase = stackPtr + 80;

    // Initialize context
    ctx.arg0 = 0;
    ctx.result = 0;

    // First call: simpleMath(2)
    simpleMath(2);

    // Second call: diamondCfg(5) → arg0 incremented
    diamondCfg(5);

    // Third call: loopCfg(-1) → arg0 set to 1
    loopCfg(-1);

    // Fourth call: nestedCfg(0) → arg0 = 3
    nestedCfg(0);

    // Print final value of arg0
    std::cout << ctx.arg0 << std::endl;

    delete[] reinterpret_cast<char*>(stackPtr);
    return returnVal;
}

