// Helper to extract required command-line argument value by key
template <typename T>
T fetchArg(const vector<string>& args, const string& flagName) {
    auto pos = find(args.begin(), args.end(), "--" + flagName);
    if (pos != args.end() && next(pos) != args.end()) {
        return boost::lexical_cast<T>(*next(pos));
    }
    throw runtime_error("Missing required argument: --" + flagName);
}

// Specialization for boolean flags (present = true)
template <>
bool fetchArg<bool>(const vector<string>& args, const string& flagName) {
    return find(args.begin(), args.end(), "--" + flagName) != args.end();
}

// Optional argument with default fallback
template <typename T>
T fetchOptionalArg(const vector<string>& args, const string& flagName, T defaultValue) {
    try {
        return fetchArg<T>(args, flagName);
    } catch (const runtime_error&) {
        return defaultValue;
    }
}

// Map CLI log level string to internal loot::LogLevel
loot::LogLevel determineLogLevel(const vector<string>& args) {
    const string logLevelStr = fetchOptionalArg<string>(args, "logLevel", "");
    auto cliLevel = lootcli::logLevelFromString(logLevelStr);
    return lootcli::toLootLogLevel(cliLevel);
}

