MemoryBuffer::MemoryBuffer() = default;
MemoryBuffer::~MemoryBuffer() = default;

std::optional<std::string> MemoryBuffer::init() {
    return std::nullopt;
}

size_t MemoryBuffer::size() const {
    return m_total_size;
}

std::optional<std::string> MemoryBuffer::push(U8View data) {
    // Convert U8View to vector and delegate to the vector overload
    std::vector<uint8_t> buffer(data.data(), data.data() + data.size());
    return push(std::move(buffer));
}

std::optional<std::string> MemoryBuffer::push(std::vector<uint8_t> data) {
    if (!data.empty()) {
        m_total_size += data.size();
        m_chunks.push(std::move(data));  // Use push instead of emplace for clarity
    }
    return std::nullopt;
}

BufferPeekResult MemoryBuffer::peek() {
    U8View chunk_view;

    if (!m_chunks.empty()) {
        const auto& front_chunk = m_chunks.front();
        chunk_view = U8View{front_chunk.data(), front_chunk.size()};
    }

    return BufferPeekResult{std::nullopt, chunk_view};
}

void MemoryBuffer::drain(size_t length) {
    assert(length <= m_total_size);

    m_total_size -= length;

    while (length > 0 && !m_chunks.empty()) {
        auto& current_chunk = m_chunks.front();
        size_t remove_count = std::min(current_chunk.size(), length);

        current_chunk.erase(current_chunk.begin(), current_chunk.begin() + remove_count);
        length -= remove_count;

        if (current_chunk.empty()) {
            m_chunks.pop();
        }
    }
}

