// Replaced recursive traversal with iterative approach using stack
void getAllInternalBranches(pllInstance* tr, std::vector<void*>& branchList) {
    // Simulating: pllGetAllInBran(tr, branchList);
    // Original used recursion; here we use explicit stack for clarity
    std::vector<void*> stack;
    void* startNode = tr->start;
    if (startNode) {
        stack.push_back(((nodeptr)startNode)->back);
    }

    while (!stack.empty()) {
        void* current = stack.back();
        stack.pop_back();
        if (!isTip(((nodeptr)current)->number, tr->mxtips) &&
            !isTip(((nodeptr)((nodeptr)current)->back)->number, tr->mxtips)) {
            branchList.push_back(current);
        }
        // Traverse children
        void* next = ((nodeptr)current)->next;
        while (next != current) {
            stack.push_back(next->back);
            next = next->next;
        }
    }
}

// Replaced quicksort_nni with std::sort + lambda
void sortNNIMoves(std::vector<pllNNIMove>& moves) {
    std::sort(moves.begin(), moves.end(), [](const pllNNIMove& a, const pllNNIMove& b) {
        return a.likelihood < b.likelihood;
    });
}

// Simplified string generation for branch representation
std::string encodeBranch(void* p) {
    auto* nodeP = static_cast<nodeptr>(p);
    auto* nodeQ = nodeP->back;
    std::ostringstream oss;
    if (nodeP->number < nodeQ->number) {
        oss << nodeP->number << "-" << nodeQ->number;
    } else {
        oss << nodeQ->number << "-" << nodeP->number;
    }
    return oss.str();
}

// Updated affected nodes collection using set and loops
std::set<int> collectAffectedNodes(pllInstance* tr, void* p) {
    std::set<int> affected;
    auto* nodeP = static_cast<nodeptr>(p);
    auto* nodeQ = nodeP->back;

    affected.insert(nodeP->number);
    affected.insert(nodeQ->number);

    auto* neighbor = nodeP->next;
    while (neighbor != nodeP) {
        auto* neiBack = neighbor->back;
        if (isTip(neiBack->number, tr->mxtips)) {
            affected.insert(neiBack->number);
        } else {
            affected.insert(neiBack->number);
            affected.insert(neiBack->next->back->number);
            affected.insert(neiBack->next->next->back->number);
        }
        neighbor = neighbor->next;
    }

    neighbor = nodeQ->next;
    while (neighbor != nodeQ) {
        auto* neiBack = neighbor->back;
        if (isTip(neiBack->number, tr->mxtips)) {
            affected.insert(neiBack->number);
        } else {
            affected.insert(neiBack->number);
            affected.insert(neiBack->next->back->number);
            affected.insert(neiBack->next->next->back->number);
        }
        neighbor = neighbor->next;
    }

    return affected;
}

// Main NNI search refactored with clearer structure and modern C++
double executeNNISearch(pllInstance* tr, partitionList* pr, SearchInfo& info) {
    double initialLH = tr->likelihood;
    double finalLH = initialLH;
    std::vector<pllNNIMove> chosenNNIs;
    std::unordered_set<int> lockedNodes;

    int numBranches = pr->perGeneBranchLengths ? pr->numberOfPartitions : 1;

    // Save current tree state (mocked)
    // topol* savedTree = saveCurrentTopology(tr);

    // Evaluate all NNIs
    evaluateAllNNIs(tr, pr, info);

    if (info.posNNIList.empty()) {
        info.curNumAppliedNNIs = 0;
        return finalLH;
    }

    // Sort positive NNIs descending by likelihood
    sortNNIMoves(info.posNNIList);
    std::reverse(info.posNNIList.begin(), info.posNNIList.end());

    // Select non-conflicting moves
    for (auto it = info.posNNIList.rbegin(); it != info.posNNIList.rend(); ++it) {
        auto* p = static_cast<nodeptr>((*it).p);
        auto* q = p->back;
        if (lockedNodes.find(p->number) == lockedNodes.end() &&
            lockedNodes.find(q->number) == lockedNodes.end()) {
            chosenNNIs.push_back(*it);
            lockedNodes.insert(p->number);
            lockedNodes.insert(q->number);
        }
    }

    info.curNumAppliedNNIs = chosenNNIs.size();

    // Apply selected NNIs
    for (auto& move : chosenNNIs) {
        applySingleNNI(tr, pr, move.p, move.nniType, TOPO_ONLY);
        updateBranchLengthsForNNI(tr, pr, move);
        // Update partials...
    }

    // Optimize after application
    // pllOptimizeBranchLengths(...);

    // Check if likelihood improved significantly
    if (tr->likelihood > finalLH + 0.1) {
        finalLH = tr->likelihood;
    } else {
        info.curNumAppliedNNIs = 0;
    }

    return finalLH;
}

