NgMat* NgMat::sCurrent = nullptr;

// Texture wrap clamp mapping: [kTexWrapNone, kTexWrapClamp, kTexWrapMirror, ...]
static RndRenderState::ClampMode sTextureWrapModes[6] = {
    RndRenderState::kClampRepeat,     // index 0 → repeat
    RndRenderState::kClampClamp,      // index 1 → clamp
    RndRenderState::kClampMirror,     // index 2 → mirror
    RndRenderState::kClampMirrorOnce, // index 3 → mirror once
    RndRenderState::kClampBorder,     // index 4 → border
    RndRenderState::kClampClamp       // index 5 → fallback to clamp
};

NgMat::NgMat() : mDirty(0) {}

NgMat::~NgMat() {
    if (sCurrent == this) {
        sCurrent = nullptr;
    }
}

bool NgMat::CanApplyFog() const {
    return !(mBlend == kBlendDest || mBlend == kBlendAdd || 
             mBlend == kBlendSubtract || mBlend == kBlendSrcAlphaAdd);
}

bool NgMat::CanProcessHDR() const {
    bool noAlphaBlending = (mBlend != kBlendSrcAlpha && 
                            mBlend != kBlendSrcAlphaAdd && 
                            mBlend != kPreMultAlpha);
    return noAlphaBlending && !mAlphaCut && !mAlphaWrite;
}

void NgMat::ConfigureShader(bool needsAmbient, bool needsConstants) {
    if (needsAmbient) {
        ApplyAmbientLighting();
    }

    if (this != sCurrent || mDirty) {
        if (mDirty & 0x2) {
            UpdateRenderState();
        }
        ApplyFixedPipelineState();
        if (needsConstants) {
            SetupShaderConstants(needsAmbient);
        }
        mDirty = 0;
        sCurrent = this;
    }
}

void NgMat::ApplyFixedPipelineState() {
    RndRenderState::CullMode cullMode;
    switch (mCull) {
        case kCullNone:
            cullMode = RndRenderState::kCullNone;
            break;
        case kCullRegular:
            cullMode = RndRenderState::kCullFront;
            break;
        case kCullBackwards:
            cullMode = RndRenderState::kCullBack;
            break;
        default:
            cullMode = RndRenderState::kCullFront;
            break;
    }

    TheRenderState.SetCullMode(cullMode);
    TheRenderState.SetBlendEnable(mBlendEnable);
    TheRenderState.SetBlendOp(mBlendOp);
    TheRenderState.SetBlend(mSrcBlend, mDestBlend, mSrcBlend, mDestBlend);
    TheRenderState.SetAlphaTestEnable(mAlphaCut);

    if (mAlphaCut) {
        TheRenderState.SetAlphaFunc(RndRenderState::kTestGreaterEqual, mAlphaThreshold);
    }

    TheRenderState.SetDepthTestEnable(mDepthTestEnable);
    TheRenderState.SetDepthWriteEnable(mDepthWriteEnable);
    TheRenderState.SetDepthFunc(mDepthFunc);

    if (mStencilMode == kStencilIgnore) {
        TheRenderState.SetStencilTestEnable(false);
    } else {
        TheRenderState.SetStencilTestEnable(true);
        TheRenderState.SetStencilFunc(mStencilFunc, 0xFF);
        TheRenderState.SetStencilOp(
            RndRenderState::kStencilKeep,
            RndRenderState::kStencilKeep,
            mStencilFailOp
        );
    }

    RndRenderState::ClampMode currentClamp = sTextureWrapModes[mTexWrap];

    if (mDiffuseTex) {
        TheRenderState.SetTextureClamp(0, currentClamp);
    }
    if (mDiffuseTex2) {
        TheRenderState.SetTextureClamp(6, currentClamp);
    }
    if (mNormalMap) {
        TheRenderState.SetTextureClamp(1, currentClamp);
    }
    if (mSpecularMap) {
        TheRenderState.SetTextureClamp(2, currentClamp);
    }
    if (mEmissiveMap) {
        TheRenderState.SetTextureClamp(3, currentClamp);
    }

    if (currentClamp == RndRenderState::kClampBorder) {
        bool useWhiteBorder = (mTexWrap == kTexBorderWhite);
        TheRenderState.SetBorderColor(0, useWhiteBorder);
        TheRenderState.SetBorderColor(6, useWhiteBorder);
        TheRenderState.SetBorderColor(1, useWhiteBorder);
        TheRenderState.SetBorderColor(2, useWhiteBorder);
        TheRenderState.SetBorderColor(3, useWhiteBorder);
    }
}

void NgMat::ApplyAmbientLighting() {
    if (mUseEnviron) {
        const Vector4& ambient = reinterpret_cast<const Vector4&>(
            RndEnviron::Current()->AmbientColor()
        );
        TheShaderMgr.SetVConstant(VShaderConstant::kAmbientColor, ambient);
        TheShaderMgr.SetPConstant(PShaderConstant::kAmbientColor, ambient);
    } else {
        Vector4 white(1.0f, 1.0f, 1.0f, 1.0f);
        TheShaderMgr.SetVConstant(VShaderConstant::kAmbientColor, white);
        TheShaderMgr.SetPConstant(PShaderConstant::kAmbientColor, white);
    }
}

#include "WebAssemblyTypeUtilities.h"
#include "llvm/ADT/StringSwitch.h"

// Get register classes enum.
#define GET_REGINFO_ENUM
#include "WebAssemblyGenRegisterInfo.inc"

using namespace llvm;

MVT WebAssembly::parseMVT(StringRef Type) {
  // Map string representations to MVT types
  if (Type == "i32") return MVT::i32;
  if (Type == "i64") return MVT::i64;
  if (Type == "f32") return MVT::f32;
  if (Type == "f64") return MVT::f64;
  if (Type == "v16i8") return MVT::v16i8;
  if (Type == "v8i16") return MVT::v8i16;
  if (Type == "v4i32") return MVT::v4i32;
  if (Type == "v2i64") return MVT::v2i64;
  if (Type == "funcref") return MVT::funcref;
  if (Type == "externref") return MVT::externref;

  return MVT::INVALID_SIMPLE_VALUE_TYPE;
}

wasm::ValType WebAssembly::toValType(MVT Type) {
  switch (Type.SimpleTy) {
    case MVT::i32:
      return wasm::ValType::I32;
    case MVT::i64:
      return wasm::ValType::I64;
    case MVT::f32:
      return wasm::ValType::F32;
    case MVT::f64:
      return wasm::ValType::F64;
    case MVT::v16i8:
    case MVT::v8i16:
    case MVT::v4i32:
    case MVT::v2i64:
    case MVT::v4f32:
    case MVT::v2f64:
      return wasm::ValType::V128;
    case MVT::funcref:
      return wasm::ValType::FUNCREF;
    case MVT::externref:
      return wasm::ValType::EXTERNREF;
    default:
      llvm_unreachable("unexpected type");
  }
}

void WebAssembly::wasmSymbolSetType(MCSymbolWasm *Sym, const Type *GlobalVT,
                                    const ArrayRef<MVT> &VTs) {
  assert(!Sym->getType());

  wasm::ValType ValTy;
  bool IsTable = false;

  // Handle table types — represented as arrays in LLVM IR with reference element types
  if (WebAssembly::isWebAssemblyTableType(GlobalVT)) {
    IsTable = true;
    const Type *ElTy = GlobalVT->getArrayElementType();

    if (WebAssembly::isWebAssemblyExternrefType(ElTy))
      ValTy = wasm::ValType::EXTERNREF;
    else if (WebAssembly::isWebAssemblyFuncrefType(ElTy))
      ValTy = wasm::ValType::FUNCREF;
    else
      report_fatal_error("unhandled reference type");
  } 
  // Handle scalar types
  else if (VTs.size() == 1) {
    ValTy = WebAssembly::toValType(VTs.front());
  } 
  // Fallback for unsupported cases
  else {
    report_fatal_error("Aggregate globals not yet implemented");
  }

  // Set symbol type accordingly
  if (IsTable) {
    Sym->setType(wasm::WASM_SYMBOL_TYPE_TABLE);
    Sym->setTableType(ValTy);
  } else {
    Sym->setType(wasm::WASM_SYMBOL_TYPE_GLOBAL);
    Sym->setGlobalType(wasm::WasmGlobalType{static_cast<uint8_t>(ValTy), /*Mutable=*/true});
  }
}

#include "MavLinkLog.hpp"
#include <chrono>
#include "Utils.hpp"

using namespace mavlinkcom;
using namespace mavlink_utils;

// Helper to compute timestamp in microseconds
uint64_t getMicrosecondsSinceEpoch() {
    auto now = std::chrono::high_resolution_clock::now().time_since_epoch();
    return std::chrono::duration_cast<std::chrono::microseconds>(now).count();
}

// Reversed byte order conversion for compatibility with QGC
uint64_t reverseByteOrder(uint64_t value) {
    uint64_t out = 0;
    for (int i = 0; i < 8; ++i) {
        out <<= 8;
        out |= (value & 0xFF);
        value >>= 8;
    }
    return out;
}

MavLinkFileLog::MavLinkFileLog()
    : ptr_(nullptr)
    , reading_(false)
    , writing_(false)
    , json_(false)
{}

MavLinkFileLog::~MavLinkFileLog() {
    close();
}

bool MavLinkFileLog::isOpen() const {
    return reading_ || writing_;
}

void MavLinkFileLog::openForReading(const std::string& filename) {
    close();
    file_name_ = filename;
    FILE* f = fopen(filename.c_str(), "rb");
    if (!f) {
        throw std::runtime_error(Utils::stringf(
            "Failed to open %s for reading: error %d", filename.c_str(), errno));
    }
    ptr_ = f;
    reading_ = true;
    writing_ = false;
}

void MavLinkFileLog::openForWriting(const std::string& filename, bool asJson) {
    close();
    json_ = asJson;
    file_name_ = filename;
    FILE* f = fopen(filename.c_str(), "wb");
    if (!f) {
        throw std::runtime_error(Utils::stringf(
            "Failed to open %s for writing: error %d", filename.c_str(), errno));
    }
    ptr_ = f;
    if (json_) {
        fprintf(ptr_, "{ \"rows\": [\n");
    }
    reading_ = false;
    writing_ = true;
}

void MavLinkFileLog::close() {
    FILE* old = ptr_;
    if (old != nullptr) {
        if (json_) {
            fprintf(old, "    {}\n"); // avoids trailing comma issue
            fprintf(old, "]}\n");
        }
        fclose(old);
    }
    ptr_ = nullptr;
    reading_ = false;
    writing_ = false;
}

void MavLinkFileLog::write(const mavlinkcom::MavLinkMessage& msg, uint64_t ts) {
    if (!ptr_) return;

    if (reading_) {
        throw std::runtime_error("Attempted write on read-only log file");
    }

    if (json_) {
        MavLinkMessageBase* typedMsg = MavLinkMessageBase::lookup(msg);
        if (typedMsg) {
            typedMsg->timestamp = ts ? ts : getMicrosecondsSinceEpoch();
            std::string line = typedMsg->toJSon();
            fprintf(ptr_, "    %s\n", line.c_str());
            delete typedMsg;
        }
    } else {
        uint64_t t = ts ? ts : getMicrosecondsSinceEpoch();
        uint64_t bigEndianTime = reverseByteOrder(t);

        fwrite(&bigEndianTime, sizeof(uint64_t), 1, ptr_);
        fwrite(&msg.magic, sizeof(uint8_t), 1, ptr_);
        fwrite(&msg.len, sizeof(uint8_t), 1, ptr_);
        fwrite(&msg.seq, sizeof(uint8_t), 1, ptr_);
        fwrite(&msg.sysid, sizeof(uint8_t), 1, ptr_);
        fwrite(&msg.compid, sizeof(uint8_t), 1, ptr_);
        uint8_t mid = static_cast<uint8_t>(msg.msgid & 0xFF);
        fwrite(&mid, sizeof(uint8_t), 1, ptr_);
        fwrite(msg.payload64.data(), sizeof(uint8_t), msg.len, ptr_);
        fwrite(&msg.checksum, sizeof(uint16_t), 1, ptr_);
    }
}

bool MavLinkFileLog::read(mavlinkcom::MavLinkMessage& msg, uint64_t& ts) {
    if (!ptr_) return false;
    if (writing_) {
        throw std::runtime_error("Attempted read on write-only log file");
    }

    uint64_t rawTime;
    size_t n = fread(&rawTime, sizeof(uint8_t), sizeof(uint64_t), ptr_);
    if (n < sizeof(uint64_t)) return false;

    ts = reverseByteOrder(rawTime);

    if (fread(&msg.magic, sizeof(uint8_t), 1, ptr_) != 1) return false;
    if (fread(&msg.len, sizeof(uint8_t), 1, ptr_) != 1) return false;
    if (fread(&msg.seq, sizeof(uint8_t), 1, ptr_) != 1) return false;
    if (fread(&msg.sysid, sizeof(uint8_t), 1, ptr_) != 1) return false;
    if (fread(&msg.compid, sizeof(uint8_t), 1, ptr_) != 1) return false;

    uint8_t mid = 0;
    if (fread(&mid, sizeof(uint8_t), 1, ptr_) != 1) return false;
    msg.msgid = mid;

    if (msg.len > sizeof(msg.payload64)) return false;
    if (fread(msg.payload64.data(), sizeof(uint8_t), msg.len, ptr_) < static_cast<size_t>(msg.len))
        return false;

    if (fread(&msg.checksum, sizeof(uint16_t), 1, ptr_) != 1) return false;

    return true;
}

#include "ipc/event_listener.h"
#include "log/fanylog.h"
#include "window/ime_windows.h"
#include <thread>
#include "ipc/ipc.h"
#include "config/ime_config.h"

int CALLBACK WinMain(_In_ HINSTANCE hInstance, _In_ HINSTANCE hPrevInstance, _In_ LPSTR lpCmdLine, _In_ int nCmdShow)
{
    // Set DPI awareness for high-DPI support
    SetProcessDpiAwarenessContext(DPI_AWARENESS_CONTEXT_PER_MONITOR_AWARE_V2);

    // #ifdef FANY_DEBUG
    InitializeSpdLog();  // Setup logging system
    // #endif

    // Load configuration and initialize IPC infrastructure
    InitImeConfig();
    ::InitIpc();
    ::InitNamedPipe();

    // Instantiate dictionary query handler
    g_dictQuery = std::make_shared<DictionaryUlPb>();

    // Register custom window message for candidate list interaction
    RegisterCandidateWindowMessage();

    // Prepare window class registration data
    WNDCLASSEX windowClassInfo = {};
    RegisterIMEWindowsClass(windowClassInfo, hInstance);

    // Launch background threads for inter-process communication via named pipes
    std::thread workerThread(FanyNamedPipe::WorkerThread);
    std::thread mainListenerThread(FanyNamedPipe::EventListenerLoopThread);
    std::thread toTsfListenerThread(FanyNamedPipe::ToTsfPipeEventListenerLoopThread);

    // Store thread handles globally for external management
    ::mainPipeThread = mainListenerThread.native_handle();
    ::toTsfPipeThread = toTsfListenerThread.native_handle();

    // Additional listener for TSF worker thread communication
    std::thread toTsfWorkerListenerThread(FanyNamedPipe::ToTsfWorkerThreadPipeEventListenerLoopThread);
    ::toTsfWorkerThreadPipeThread = toTsfWorkerListenerThread.native_handle();

    // Auxiliary pipe listener for automatic reconnection handling
    std::thread auxListenerThread(FanyNamedPipe::AuxPipeEventListenerLoopThread);

    // Create candidate window UI
    int result = CreateCandidateWindow(hInstance);

    // Signal shutdown of pipe services
    pipe_running = false;
    pipe_queueCv.notify_one();

    // Synchronize all worker threads before exit
    workerThread.join();
    mainListenerThread.join();
    toTsfListenerThread.join();
    toTsfWorkerListenerThread.join();
    auxListenerThread.join();

    return result;
}

