// Constructor implementation
DD::DD(Flow2D3D* flw, XmlTree* cfg) {
    flow = flw;
    config = cfg;
    clock = flow->DH->clock;
    log = flow->DH->log;
    mappersOnThisNode = 0;
    nodeID = -1;
    nodeSet = new NodeSet();
    numCategories = 0;
    numSubdomains = 0;
    numIterators = 0;
    numJoins = 0;
    numNodes = 0;
    role = DD::ROLE_UNDEFINED;
    initbar = nullptr;
    gawsbar = nullptr;
    dredgem = nullptr;
    rtc = nullptr;
    initbarCat = nullptr;
    gawsbarCat = nullptr;
    dredgeCat = nullptr;
    rtcCat = nullptr;
    processCat = nullptr;
    processList = nullptr;
    processDict = nullptr;
    mapperCat = nullptr;
    mapperList = nullptr;

    log->Write(Log::MAJOR, "Initializing single-process multi-domain simulation");
    nodeSet->AddNodesFromString("localhost");
    role = DD::ROLE_SINGLE;

#if defined(WIN32)
    throw Exception("Multi-node simulations not supported on Windows");
#endif

    nodeSet->CreateNodeTable();
    numNodes = nodeSet->numNodes;

    pthread_attr_init(&thattr);
    categoryDict = new Dictionary("Category");
    iteratorDict = new Dictionary("Iterator");
    joinDict = new Dictionary("Join");
}

DD::~DD() {
    delete nodeSet;
    delete categoryDict;
    delete iteratorDict;
    delete joinDict;
}

void DD::Run() {
    if (role == DD::ROLE_SINGLE)
        SingleProcess();
    else if (role == DD::ROLE_MASTER)
        ; // MasterProcess();
    else if (role == DD::ROLE_SLAVE)
        ; // SlaveProcess();
}

void DD::SingleProcess() {
    log->Write(Log::MAJOR, "Starting single-process DD");
    masterStart = clock->Start();
    nodeID = 0;
    CreateFixedEntities();
    ReadConfig();

    for (int jid = 0; jid < numJoins; ++jid) {
        join[jid].local = true;
    }

    categoryList = new List();
    for (int cid = 0; cid < numCategories; ++cid) {
        categoryList->Append((void*)category[cid].category);
    }

    iteratorList = new List();
    for (int itid = 0; itid < numIterators; ++itid) {
        iteratorList->Append((void*)iterator[itid].iterator);
    }

    PrintJoinTable();
    InitializeLocalMessageBuffers();
    StartLocalIteratorThreads();
    RunSimulation();
    log->Write(Log::MAJOR, "All iterators terminated in single-process mode");
}

void DD::CreateFixedEntities() {
    processCat = new Category(this, DD::processCategoryName);
    processList = new List();
    processDict = new Dictionary("Process");

    mapperCat = new Category(this, DD::mapperCategoryName);
    mapperList = new List();

    initbar = new Iterator(this, DD::initBarCategoryName, nullptr, initbarCat, &InitBarrier_Function);
    initbar->Place(nodeSet->node[0]);
    initbar->Detach();

    gawsbar = new Iterator(this, DD::gawsBarCategoryName, nullptr, gawsbarCat, &GawsBarrier_Function);
    gawsbar->Place(nodeSet->node[0]);
    gawsbar->Detach();

    dredgem = new Iterator(this, DD::dredgeMergeCategoryName, nullptr, dredgeCat, &DredgeMerge_Function);
    dredgem->Place(nodeSet->node[0]);
    dredgem->Detach();

    rtc = new Iterator(this, DD::rtcCategoryName, nullptr, rtcCat, &Rtc_Function);
    rtc->Place(nodeSet->node[0]);
    rtc->Detach();
}

void DD::ReadConfig() {
    const char* ddbfile = config->GetElement("ddbFile");
    if (!ddbfile)
        throw Exception("DD-bounds file not specified");

    log->Write(Log::CONFIG_MAJOR, "Reading DD-bounds file \"%s\"...", ddbfile);

    FILE* input = fopen(ddbfile, "r");
    if (!input)
        throw Exception("Cannot open DD-bounds file \"%s\"", ddbfile);

    char buffer[DD::MAXSTRING];
    if (!fgets(buffer, DD::MAXSTRING, input))
        throw Exception("Failed to read first line of DD-bounds file");

    rewind(input);
    const char* xmlhead = "<?xml ";
    if (strncmp(buffer, xmlhead, strlen(xmlhead)) == 0) {
#if defined(WIN32)
        throw Exception("XML DD-bounds files are not supported on Windows");
#else
        throw Exception("XML DD-bounds files are work-in-progress");
#endif
    }

    ReadDDBounds(input, ddbfile);
    fclose(input);
    log->Write(Log::CONFIG_MAJOR, "Finished reading DD-bounds file");
}

void DD::ReadDDBounds(FILE* fp, const char* fname) {
    int lineNum = 0;
    char buffer[DD::MAXSTRING];
    char left[DD::MAXSTRING], right[DD::MAXSTRING];
    int l1, l2, l3, l4, r1, r2, r3, r4;
    char leftname[DD::MAXSTRING], rightname[DD::MAXSTRING];
    char mapname[DD::MAXSTRING];
    int nextNode = 0;
    int mapperCount = 0;

    while (fgets(buffer, DD::MAXSTRING, fp)) {
        lineNum++;
        String::Chomp(buffer);

        char word[DD::MAXSTRING];
        sscanf(buffer, "%s", word);
        if (word[0] == '#' || word[0] == '\0') continue;

        if (sscanf(buffer, "%s %d %d %d %d %s %d %d %d %d",
                   left, &l1, &l2, &l3, &l4,
                   right, &r1, &r2, &r3, &r4) != 10)
            throw Exception("Syntax error in DD-bounds file at line %d", lineNum);

        check_md_file(left);
        check_md_file(right);

        sprintf(mapname, "M%d=%s=%s",
                ++mapperCount,
                extract_proc_name(left, leftname),
                extract_proc_name(right, rightname));

        Iterator* leftProc = (Iterator*)processDict->Lookup(leftname);
        if (leftProc == (Iterator*)Dictionary::NOTFOUND) {
            leftProc = AddProcess(leftname, left, nextNode++);
            nextNode %= numNodes;
        }

        Iterator* rightProc = (Iterator*)processDict->Lookup(rightname);
        if (rightProc == (Iterator*)Dictionary::NOTFOUND) {
            rightProc = AddProcess(rightname, right, nextNode++);
            nextNode %= numNodes;
        }

        AddMapper(mapname, buffer, leftProc, rightProc, leftProc->node->nodeID);
    }
}

Iterator* DD::AddProcess(const char* name, const char* cfg, int nodeId) {
    Blob* blob = new Blob(cfg, strlen(cfg));
    Iterator* proc = new Iterator(this, name, blob, processCat, &FlowDD_Process);
    delete blob;

    processDict->Insert(name, (void*)proc);
    processList->Append((void*)proc);
    numSubdomains++;

    proc->Place(nodeSet->node[nodeId]);
    JoinIterators(proc, gawsbar);
    JoinIterators(proc, initbar);
    JoinIterators(proc, dredgem);
    JoinIterators(proc, rtc);
    return proc;
}

Iterator* DD::AddMapper(const char* name, const char* cfg, Iterator* left, Iterator* right, int nodeId) {
    int len = strlen(cfg);
    char* copy = new char[len + 1];
    strcpy(copy, cfg);
    Blob* blob = new Blob(copy, len + 1);
    Iterator* mapper = new Iterator(this, name, blob, mapperCat, &FlowDD_Mapper);

    mapperList->Append((void*)mapper);
    mapper->Place(nodeSet->node[nodeId]);

    if (nodeId == nodeID)
        mappersOnThisNode++;

    JoinIterators(mapper, left);
    JoinIterators(mapper, right);
    return mapper;
}

void DD::JoinIterators(Iterator* it1, Iterator* it2) {
    if (!it1 || !it2)
        throw Exception("Null iterator passed to JoinIterators");

    const char* n1 = it1->name ? it1->name : "";
    long id1 = (long)iteratorDict->Lookup(n1);
    if (id1 == Dictionary::NOTFOUND)
        throw Exception("Unknown iterator \"%s\" in JoinIterators", n1);

    const char* n2 = it2->name ? it2->name : "";
    long id2 = (long)iteratorDict->Lookup(n2);
    if (id2 == Dictionary::NOTFOUND)
        throw Exception("Unknown iterator \"%s\" in JoinIterators", n2);

    if (iterator[id1].catID == iterator[id2].catID)
        throw Exception("Iterators \"%s\" and \"%s\" belong to same category", n1, n2);

    int jid;
    for (jid = 0; jid < numJoins; ++jid) {
        if ((id1 == join[jid].iter1 && id2 == join[jid].iter2) ||
            (id1 == join[jid].iter2 && id2 == join[jid].iter1))
            break;
    }

    if (jid == numJoins) {
        if (numJoins >= DD::MAXJOINS)
            throw Exception("Join table overflow (> %d entries)", DD::MAXJOINS);

        join[jid].iter1 = id1;
        join[jid].iter2 = id2;
        join[jid].local = false;
        join[jid].leader = false;
        join[jid].follower = false;
        join[jid].stream = nullptr;
        join[jid].handle[0] = '\0';
        numJoins++;

        char key[1000];
        sprintf(key, "%ld:%ld", std::min(id1, id2), std::max(id1, id2));
        joinDict->Insert(key, (void*)jid);
    }

    it1->AddNeigh(it2);
    it2->AddNeigh(it1);
    log->Write(Log::CONFIG_MINOR, "Joined \"%s\" and \"%s\"", n1, n2);
}

void DD::PrintJoinTable() {
    for (int jid = 0; jid < numJoins; ++jid) {
        log->Write(Log::CONFIG_MINOR,
            "Join #%d %-6s iter1=%s:%d, iter2=%s:%d, handle=\"%s\"",
            jid,
            join[jid].local ? "local" : join[jid].leader ? "lead" : "follow",
            iterator[join[jid].iter1].name,
            iterator[join[jid].iter1].iterator->node->nodeID,
            iterator[join[jid].iter2].name,
            iterator[join[jid].iter2].iterator->node->nodeID,
            join[jid].handle);
    }
}

// Utility functions
static void check_md_file(char* filename) {
    size_t len = strlen(filename);
    if (len >= DD::MAXSTRING)
        throw Exception("Filename too long in DD-bounds file");

    int dotIdx = -1;
    for (int i = len; i >= 0; --i) {
        if (filename[i] == '.') {
            dotIdx = i;
            break;
        }
    }

    if (dotIdx <= 0)
        throw Exception("Invalid filename format in DD-bounds file");

    if (dotIdx + 4 >= DD::MAXSTRING)
        throw Exception("MD filename would overflow buffer");

    strncpy(filename + dotIdx, ".mdf", 4);
    if (!is_readable_file(filename))
        throw Exception("Subdomain input file not found: \"%s\"", filename);
}

static bool is_readable_file(const char* path) {
    int fd = open(path, O_RDONLY);
    if (fd == -1) return false;

    struct stat st;
    if (fstat(fd, &st) != 0) {
        close(fd);
        return false;
    }
    close(fd);

#if defined(WIN32)
    if (st.st_mode & _S_IFDIR) return false;
#else
    if (S_ISDIR(st.st_mode)) return false;
#endif
    return true;
}

static char* extract_proc_name(const char* filepath, char* out) {
    int lastDot = -1;
    int lastSlash = -1;

    for (int i = strlen(filepath) - 1; i >= 0; --i) {
        if (filepath[i] == '.') lastDot = i;
        if (filepath[i] == '/') {
            lastSlash = i;
            break;
        }
    }

    if (lastDot == lastSlash)
        strcpy(out, filepath);
    else if (lastDot == -1)
        strcpy(out, &filepath[lastSlash + 1]);
    else {
        int length = lastDot - lastSlash - 1;
        strncpy(out, &filepath[lastSlash + 1], length);
        out[length] = '\0';
    }
    return out;
}

