QtGroupingProxy::QtGroupingProxy(QModelIndex rootNode, int groupedColumn,
                                 int groupedRole, unsigned int flags, int aggregateRole)
    : QAbstractProxyModel(), m_rootNode(rootNode), m_groupedColumn(0),
      m_groupedRole(groupedRole), m_aggregateRole(aggregateRole), m_flags(flags)
{
  if (groupedColumn != -1) {
    setGroupedColumn(groupedColumn);
  }
}

QtGroupingProxy::~QtGroupingProxy() {}

void QtGroupingProxy::setSourceModel(QAbstractItemModel* model)
{
  if (sourceModel()) {
    disconnect(sourceModel(), nullptr, this, nullptr);
  }

  QAbstractProxyModel::setSourceModel(model);

  if (sourceModel()) {
    connect(sourceModel(), SIGNAL(rowsInserted(const QModelIndex&, int, int)),
            SLOT(modelRowsInserted(const QModelIndex&, int, int)));
    connect(sourceModel(), SIGNAL(rowsAboutToBeInserted(const QModelIndex&, int, int)),
            SLOT(modelRowsAboutToBeInserted(const QModelIndex&, int, int)));
    connect(sourceModel(), SIGNAL(rowsRemoved(const QModelIndex&, int, int)),
            SLOT(modelRowsRemoved(const QModelIndex&, int, int)));
    connect(sourceModel(), SIGNAL(rowsAboutToBeRemoved(const QModelIndex&, int, int)),
            SLOT(modelRowsAboutToBeRemoved(QModelIndex, int, int)));
    connect(sourceModel(), SIGNAL(layoutChanged()), SLOT(buildTree()));
    connect(sourceModel(), SIGNAL(dataChanged(QModelIndex, QModelIndex)),
            SLOT(modelDataChanged(QModelIndex, QModelIndex)));
    connect(sourceModel(), SIGNAL(modelReset()), this, SLOT(resetModel()));

    buildTree();
  }
}

void QtGroupingProxy::setGroupedColumn(int groupedColumn)
{
  m_groupedColumn = groupedColumn;
  buildTree();
}

QList<QtGroupingProxy::RowData> QtGroupingProxy::belongsTo(const QModelIndex& idx)
{
  QList<RowData> rowDataList;

  ItemData itemData = sourceModel()->itemData(idx);
  if (m_groupedRole != Qt::DisplayRole) {
    itemData[Qt::DisplayRole] = itemData[m_groupedRole];
  }

  if (!itemData[Qt::DisplayRole].isValid()) {
    return rowDataList;
  }

  QMapIterator<int, QVariant> i(itemData);
  while (i.hasNext()) {
    i.next();
    int role         = i.key();
    QVariant variant = i.value();

    if (variant.typeId() == QMetaType::QVariantList) {
      QVariantList list = variant.toList();
      for (int j = 0; j < list.length(); j++) {
        RowData rowData = (rowDataList.count() > j) ? rowDataList.takeAt(j) : RowData();

        ItemData indexData = rowData.contains(0) ? rowData.take(0) : ItemData();
        indexData.insert(role, list.value(j));
        rowData.insert(0, indexData);
        rowData.insert(m_groupedColumn, indexData);
        rowDataList.insert(j, rowData);
      }
      break;
    } else if (!variant.isNull()) {
      RowData rowData;
      rowData.insert(0, itemData);
      rowDataList << rowData;
      break;
    }
  }

  return rowDataList;
}

void QtGroupingProxy::buildTree()
{
  if (!sourceModel())
    return;
  beginResetModel();

  m_groupMap.clear();
  m_parentCreateList.clear();

  int max = sourceModel()->rowCount(m_rootNode);

  for (int row = 0; row < max; row++) {
    QModelIndex idx = sourceModel()->index(row, m_groupedColumn, m_rootNode);
    addSourceRow(idx);
  }

  if (m_flags & FLAG_NOSINGLE) {
    quint32 quint32max = std::numeric_limits<quint32>::max();
    std::vector<int> rmgroups;
    QMap<quint32, QList<int>> temp;
    int currentKey = 0;

    for (auto iter = m_groupMap.begin(); iter != m_groupMap.end(); ++iter) {
      if ((iter.key() == quint32max) || (iter->count() < 2)) {
        temp[quint32max].append(iter.value());
        if (iter.key() != quint32max) {
          rmgroups.push_back(iter.key());
        }
      } else {
        temp[currentKey++] = *iter;
      }
    }
    m_groupMap = temp;

    std::sort(rmgroups.begin(), rmgroups.end(), [](int lhs, int rhs) {
      return rhs < lhs;
    });
    for (auto iter = rmgroups.begin(); iter != rmgroups.end(); ++iter) {
      m_groupMaps.removeAt(*iter);
    }
  }

  endResetModel();
}

QList<int> QtGroupingProxy::addSourceRow(const QModelIndex& idx)
{
  QList<int> updatedGroups;
  QList<RowData> groupData = belongsTo(idx);

  if (groupData.isEmpty()) {
    updatedGroups << -1;
    if (!m_groupMap.keys().contains(std::numeric_limits<quint32>::max()))
      m_groupMap.insert(std::numeric_limits<quint32>::max(),
                        QList<int>());
  }

  foreach (RowData data, groupData) {
    int updatedGroup = -1;
    if (!data.isEmpty()) {
      foreach (const RowData& cachedData, m_groupMaps) {
        if (data[0][Qt::DisplayRole] == cachedData[0][Qt::DisplayRole]) {
          data = cachedData;
          break;
        }
      }

      updatedGroup = m_groupMaps.indexOf(data);
      if (updatedGroup == -1) {
        m_groupMaps << data;
        updatedGroup = m_groupMaps.count() - 1;
      }

      if (!m_groupMap.keys().contains(updatedGroup))
        m_groupMap.insert(updatedGroup, QList<int>());
    }

    if (!updatedGroups.contains(updatedGroup))
      updatedGroups << updatedGroup;
  }

  QMutableMapIterator<quint32, QList<int>> i(m_groupMap);
  while (i.hasNext()) {
    i.next();
    QList<int>& groupList = i.value();
    int insertedProxyRow  = groupList.count();
    for (; insertedProxyRow > 0; insertedProxyRow--) {
      int& rowValue = groupList[insertedProxyRow - 1];
      if (idx.row() <= rowValue) {
        rowValue++;
      } else {
        break;
      }
    }

    if (updatedGroups.contains(i.key())) {
      groupList.insert(insertedProxyRow, idx.row());
    }
  }

  return updatedGroups;
}

int QtGroupingProxy::indexOfParentCreate(const QModelIndex& parent) const
{
  if (!parent.isValid())
    return -1;

  struct ParentCreate pc;
  for (int i = 0; i < m_parentCreateList.size(); i++) {
    pc = m_parentCreateList[i];
    if (pc.parentCreateIndex == parent.internalId() && pc.row == parent.row())
      return i;
  }
  pc.parentCreateIndex = parent.internalId();
  pc.row               = parent.row();
  m_parentCreateList << pc;

  return m_parentCreateList.size() - 1;
}

QModelIndex QtGroupingProxy::index(int row, int column, const QModelIndex& parent) const
{
  if (!hasIndex(row, column, parent)) {
    return QModelIndex();
  }

  if (parent.column() > 0) {
    return QModelIndex();
  }

  int parentCreateIndex = indexOfParentCreate(parent);

  return createIndex(row, column, parentCreateIndex);
}

QModelIndex QtGroupingProxy::parent(const QModelIndex& index) const
{
  if (!index.isValid())
    return QModelIndex();

  int parentCreateIndex = index.internalId();
  if (parentCreateIndex == -1 || parentCreateIndex >= m_parentCreateList.count())
    return QModelIndex();

  struct ParentCreate pc = m_parentCreateList[parentCreateIndex];

  return createIndex(pc.row, 0, pc.parentCreateIndex);
}

int QtGroupingProxy::rowCount(const QModelIndex& index) const
{
  if (!index.isValid()) {
    int rows = m_groupMaps.count() +
               m_groupMap.value(std::numeric_limits<quint32>::max()).count();
    return rows;
  }

  if (isGroup(index)) {
    qint64 groupIndex = index.row();
    int rows          = m_groupMap.value(groupIndex).count();
    return rows;
  } else {
    QModelIndex originalIndex = mapToSource(index);
    int rowCount              = sourceModel()->rowCount(originalIndex);
    return rowCount;
  }
}

int QtGroupingProxy::columnCount(const QModelIndex& index) const
{
  if (!index.isValid())
    return sourceModel()->columnCount(m_rootNode);

  if (index.column() != 0)
    return 0;

  return sourceModel()->columnCount(mapToSource(index));
}

static bool variantLess(const QVariant& LHS, const QVariant& RHS)
{
  if ((LHS.typeId() == RHS.typeId()) &&
      ((LHS.typeId() == QMetaType::Int) || (LHS.typeId() == QMetaType::UInt))) {
    return LHS.toInt() < RHS.toInt();
  }

  return LHS.toString() < RHS.toString();
}

static QVariant variantMax(const QVariantList& variants)
{
  QVariant result = variants.first();
  foreach (const QVariant& iter, variants) {
    if (variantLess(result, iter)) {
      result = iter;
    }
  }
  return result;
}

static QVariant variantMin(const QVariantList& variants)
{
  QVariant result = variants.first();
  foreach (const QVariant& iter, variants) {
    if (variantLess(iter, result)) {
      result = iter;
    }
  }
  return result;
}

QVariant QtGroupingProxy::data(const QModelIndex& index, int role) const
{
  if (!index.isValid())
    return QVariant();

  int row    = index.row();
  int column = index.column();
  if (isGroup(index)) {
    if ((role != Qt::DisplayRole) && (role != Qt::EditRole)) {
      switch (role) {
      case Qt::ForegroundRole: {
        return QBrush(Qt::gray);
      } break;
      case Qt::FontRole: {
        QFont font(m_groupMaps[row][column].value(Qt::FontRole).value<QFont>());
        font.setItalic(true);
        return font;
      } break;
      case Qt::TextAlignmentRole: {
        return Qt::AlignHCenter;
      } break;
      case Qt::UserRole: {
        return m_groupMaps[row][column].value(Qt::DisplayRole).toString();
      } break;
      case Qt::CheckStateRole: {
        if (column != 0)
          return QVariant();
        int childCount          = m_groupMap.value(row).count();
        int checked             = 0;
        QModelIndex parentIndex = this->index(row, 0, index.parent());
        for (int childRow = 0; childRow < childCount; ++childRow) {
          QModelIndex childIndex = this->index(childRow, 0, parentIndex);
          QVariant data          = mapToSource(childIndex).data(Qt::CheckStateRole);
          if (data.toInt() == 2)
            ++checked;
        }
        if (checked == childCount)
          return Qt::Checked;
        else if (checked == 0)
          return Qt::Unchecked;
        else
          return Qt::PartiallyChecked;
      } break;
      default: {
        QModelIndex parentIndex = this->index(row, 0, index.parent());
        if (m_groupMap.value(row).count() > 0) {
          return this->index(0, column, parentIndex).data(role);
        } else {
          return QVariant();
        }
      } break;
      }
    }

    if (m_groupMaps[row][column].contains(Qt::DisplayRole)) {
      if ((m_flags & FLAG_NOGROUPNAME) != 0) {
        QModelIndex parentIndex = this->index(row, 0, index.parent());
        QModelIndex childIndex  = this->index(0, column, parentIndex);
        return childIndex.data(role).toString();
      } else {
        return m_groupMaps[row][column].value(role).toString();
      }
    }

    if (column == 0)
      column = m_groupedColumn;

    QVariantList variantsOfChildren;
    int childCount = m_groupMap.value(row).count();
    if (childCount == 0)
      return QVariant();

    int function = AGGR_NONE;
    if (m_aggregateRole >= Qt::UserRole) {
      QModelIndex parentIndex = this->index(row, 0, index.parent());
      QModelIndex childIndex  = this->index(0, column, parentIndex);
      function                = mapToSource(childIndex).data(m_aggregateRole).toInt();
    }

    QModelIndex parentIndex = this->index(row, 0, index.parent());
    for (int childRow = 0; childRow < childCount; childRow++) {
      QModelIndex childIndex = this->index(childRow, column, parentIndex);
      QVariant data          = mapToSource(childIndex).data(role);

      if (data.isValid() && !variantsOfChildren.contains(data))
        variantsOfChildren << data;
    }

    ItemData roleMap = m_groupMaps[row].value(column);
    foreach (const QVariant& variant, variantsOfChildren) {
      if (roleMap[role] != variant) {
        roleMap.insert(role, variantsOfChildren);
      }
    }

    if (variantsOfChildren.count() == 0)
      return QVariant();

    switch (function) {
    case AGGR_EMPTY:
      return QVariant();
    case AGGR_FIRST:
      return variantsOfChildren.first();
    case AGGR_MAX:
      return variantMax(variantsOfChildren);
    case AGGR_MIN:
      return variantMin(variantsOfChildren);
    default: {
      if (variantsOfChildren.count() == 1)
        return variantsOfChildren.first();

      return variantsOfChildren;
    } break;
    }
  }

  return mapToSource(index).data(role);
}

bool QtGroupingProxy::setData(const QModelIndex& idx, const QVariant& value, int role)
{
  if (!idx.isValid())
    return false;

  if (idx.data(role) == value)
    return false;

  if (isGroup(idx)) {
    ItemData columnData = m_groupMaps[idx.row()][idx.column()];

    columnData.insert(role, value);
    if (role == Qt::EditRole)
      columnData.insert(Qt::DisplayRole, value);

    m_groupMaps[idx.row()].insert(idx.column(), columnData);

    int columnToChange = idx.column() ? idx.column() : m_groupedColumn;
    foreach (int originalRow, m_groupMap.value(idx.row())) {
      QModelIndex childIdx =
          sourceModel()->index(originalRow, columnToChange, m_rootNode);
      if (childIdx.isValid())
        sourceModel()->setData(childIdx, value, role);
    }

    emit dataChanged(idx, idx);
    return true;
  }

  return sourceModel()->setData(mapToSource(idx), value, role);
}

bool QtGroupingProxy::isGroup(const QModelIndex& index) const
{
  int parentCreateIndex = index.internalId();
  if (parentCreateIndex == -1 && index.row() < m_groupMaps.count())
    return true;
  return false;
}

QModelIndex QtGroupingProxy::mapToSource(const QModelIndex& index) const
{
  if (!index.isValid()) {
    return m_rootNode;
  }

  if (isGroup(index)) {
    return m_rootNode;
  }

  QModelIndex proxyParent    = index.parent();
  QModelIndex originalParent = mapToSource(proxyParent);

  int originalRow = index.row();
  if (originalParent == m_rootNode) {
    int indexInGroup = index.row();
    if (!proxyParent.isValid())
      indexInGroup -= m_groupMaps.count();

    QList<int> childRows = m_groupMap.value(proxyParent.row());
    if (childRows.isEmpty() || indexInGroup >= childRows.count() || indexInGroup < 0)
      return QModelIndex();

    originalRow = childRows.at(indexInGroup);
  }
  return sourceModel()->index(originalRow, index.column(), originalParent);
}

QModelIndexList QtGroupingProxy::mapToSource(const QModelIndexList& list) const
{
  QModelIndexList originalList;
  foreach (const QModelIndex& index, list) {
    QModelIndex originalIndex = mapToSource(index);
    if (originalIndex.isValid())
      originalList << originalIndex;
  }
  return originalList;
}

QModelIndex QtGroupingProxy::mapFromSource(const QModelIndex& idx) const
{
  if (!idx.isValid())
    return QModelIndex();

  QModelIndex proxyParent;
  QModelIndex sourceParent = idx.parent();

  int proxyRow  = idx.row();
  int sourceRow = idx.row();

  if (sourceParent.isValid() && (sourceParent != m_rootNode)) {
    proxyParent = mapFromSource(sourceParent);
  } else {
    int groupRow = -1;
    QMapIterator<quint32, QList<int>> iterator(m_groupMap);
    while (iterator.hasNext()) {
      iterator.next();
      if (iterator.value().contains(sourceRow)) {
        groupRow = iterator.key();
        break;
      }
    }

    if (groupRow != -1) {
      proxyParent = this->index(groupRow, 0, QModelIndex());
      proxyRow    = m_groupMap.value(groupRow).indexOf(sourceRow);
    } else {
      proxyParent = QModelIndex();
      int groupLength = m_groupMaps.count();
      int i = m_groupMap.value(std::numeric_limits<quint32>::max()).indexOf(sourceRow);

      proxyRow = groupLength + i;
    }
  }

  return this->index(proxyRow, idx.column(), proxyParent);
}

Qt::ItemFlags QtGroupingProxy::flags(const QModelIndex& idx) const
{
  if (!idx.isValid()) {
    Qt::ItemFlags rootFlags = sourceModel()->flags(m_rootNode);
    if (rootFlags.testFlag(Qt::ItemIsDropEnabled))
      return Qt::ItemFlags(Qt::ItemIsDropEnabled);

    return Qt::ItemFlags(0);
  }

  if (isGroup(idx)) {
    Qt::ItemFlags defaultFlags(Qt::ItemIsEnabled | Qt::ItemIsSelectable);
    bool groupIsEditable = true;

    if (idx.column() == 0) {
      bool checkable = true;
      foreach (int originalRow, m_groupMap.value(idx.row())) {
        QModelIndex originalIdx =
            sourceModel()->index(originalRow, 0, m_rootNode.parent());
        if ((originalIdx.flags() & Qt::ItemIsUserCheckable) == 0) {
          checkable = false;
        }
      }

      if (checkable) {
        defaultFlags |= Qt::ItemIsUserCheckable;
      }
    }

    if (m_groupMap.value(idx.row()).count() == 0) {
      QModelIndex originalRootNode =
          sourceModel()->index(m_rootNode.row(), m_groupedColumn, m_rootNode.parent());
      groupIsEditable = originalRootNode.flags().testFlag(Qt::ItemIsEditable);
    } else {
      foreach (int originalRow, m_groupMap.value(idx.row())) {
        QModelIndex originalIdx =
            sourceModel()->index(originalRow, m_groupedColumn, m_rootNode);

        groupIsEditable =
            groupIsEditable ? originalIdx.flags().testFlag(Qt::ItemIsEditable) : false;
        if (!groupIsEditable)
          break;
      }
    }
    if (groupIsEditable)
      return (defaultFlags | Qt::ItemIsEditable | Qt::ItemIsDropEnabled);
    return defaultFlags;
  }

  QModelIndex originalIdx         = mapToSource(idx);
  Qt::ItemFlags originalItemFlags = sourceModel()->flags(originalIdx);

  QModelIndex groupedColumnIndex =
      sourceModel()->index(originalIdx.row(), m_groupedColumn, originalIdx.parent());
  bool groupIsEditable =
      sourceModel()->flags(groupedColumnIndex).testFlag(Qt::ItemIsEditable);

  if (groupIsEditable)
    return originalItemFlags | Qt::ItemIsDragEnabled;
  return originalItemFlags;
}

QVariant QtGroupingProxy::headerData(int section, Qt::Orientation orientation,
                                     int role) const
{
  return sourceModel()->headerData(section, orientation, role);
}

bool QtGroupingProxy::canFetchMore(const QModelIndex& parent) const
{
  if (!parent.isValid())
    return false;

  if (isGroup(parent))
    return false;

  return sourceModel()->canFetchMore(mapToSource(parent));
}

void QtGroupingProxy::fetchMore(const QModelIndex& parent)
{
  if (!parent.isValid())
    return;

  if (isGroup(parent))
    return;

  return sourceModel()->fetchMore(mapToSource(parent));
}

QModelIndex QtGroupingProxy::addEmptyGroup(const RowData& data)
{
  int newRow = m_groupMaps.count();
  beginInsertRows(QModelIndex(), newRow, newRow);
  m_groupMaps << data;
  endInsertRows();
  return index(newRow, 0, QModelIndex());
}

bool QtGroupingProxy::removeGroup(const QModelIndex& idx)
{
  beginRemoveRows(idx.parent(), idx.row(), idx.row());
  m_groupMap.remove(idx.row());
  m_groupMaps.removeAt(idx.row());
  m_parentCreateList.removeAt(idx.internalId());
  endRemoveRows();

  return true;
}

bool QtGroupingProxy::hasChildren(const QModelIndex& parent) const
{
  if (!parent.isValid()) {
    return true;
  }

  if (isGroup(parent)) {
    return !m_groupMap.value(parent.row()).isEmpty();
  }

  return sourceModel()->hasChildren(mapToSource(parent));
}

bool QtGroupingProxy::dropMimeData(const QMimeData* data, Qt::DropAction action,
                                   int row, int column, const QModelIndex& parent)
{
  QModelIndex idx = index(row, column, parent);
  if (isGroup(idx)) {
    QList<int> childRows = m_groupMap.value(idx.row());
    int max              = *std::max_element(childRows.begin(), childRows.end());

    QModelIndex newIdx = mapToSource(index(max, column, idx));
    return sourceModel()->dropMimeData(data, action, max, column, newIdx);
  } else {
    if (row == -1) {
      return sourceModel()->dropMimeData(data, action, -1, -1, mapToSource(parent));
    } else {
      QModelIndex idx = mapToSource(index(row, column, parent));
      return sourceModel()->dropMimeData(data, action, idx.row(), idx.column(),
                                         idx.parent());
    }
  }
}

void QtGroupingProxy::modelRowsAboutToBeInserted(const QModelIndex& parent, int start,
                                                 int end)
{
  if (parent != m_rootNode) {
    QModelIndex proxyParent = mapFromSource(parent);
    beginInsertRows(proxyParent, start, end);
  }
}

void QtGroupingProxy::modelRowsInserted(const QModelIndex& parent, int start, int end)
{
  if (parent == m_rootNode) {
    for (int modelRow = start; modelRow <= end; modelRow++) {
      addSourceRow(sourceModel()->index(modelRow, m_groupedColumn, m_rootNode));
    }
  } else {
    QModelIndex proxyParent = mapFromSource(parent);

    QString s;
    QDebug debug(&s);
    debug << proxyParent;
    log::debug("{}", s);

    endInsertRows();
  }
}

void QtGroupingProxy::modelRowsAboutToBeRemoved(const QModelIndex& parent, int start,
                                                int end)
{
  if (parent == m_rootNode) {
    QMap<quint32, QList<int>>::const_iterator i;
    for (i = m_groupMap.constBegin(); i != m_groupMap.constEnd(); ++i) {
      int groupIndex              = i.key();
      const QList<int>& groupList = i.value();
      QModelIndex proxyParent     = index(groupIndex, 0);
      foreach (int originalRow, groupList) {
        if (originalRow >= start && originalRow <= end) {
          int proxyRow = groupList.indexOf(originalRow);
          if (groupIndex == -1)
            proxyRow += m_groupMaps.count();
          beginRemoveRows(proxyParent, proxyRow, proxyRow);
        }
      }
    }
  } else {
    QModelIndex proxyParent = mapFromSource(parent);
    beginRemoveRows(proxyParent, start, end);
  }
}

void QtGroupingProxy::modelRowsRemoved(const QModelIndex& parent, int start, int end)
{
  if (parent == m_rootNode) {
    for (int i = start; i <= end; i++) {
      QMutableMapIterator<quint32, QList<int>> iter(m_groupMap);
      iter.toBack();
      while (iter.hasPrevious()) {
        iter.previous();
        int groupIndex = iter.key();
        QList<int>& groupList = iter.value();
        int rowIndex          = groupList.indexOf(start);
        if (rowIndex != -1) {
          QModelIndex proxyParent = index(groupIndex, 0);
          groupList.removeAt(rowIndex);
        }
        for (int j = 0; j < groupList.count(); j++) {
          int sourceRow = groupList.at(j);
          if (sourceRow > start)
            groupList.replace(j, sourceRow - 1);
        }
        if (rowIndex != -1)
          endRemoveRows();
      }
    }

    return;
  }

  endRemoveRows();
}

void QtGroupingProxy::resetModel()
{
  buildTree();
}

void QtGroupingProxy::modelDataChanged(const QModelIndex& topLeft,
                                       const QModelIndex& bottomRight)
{
  QModelIndex proxyTopLeft = mapFromSource(topLeft);
  if (!proxyTopLeft.isValid())
    return;

  if (topLeft == bottomRight) {
    emit dataChanged(proxyTopLeft, proxyTopLeft);
  } else {
    QModelIndex proxyBottomRight = mapFromSource(bottomRight);
    emit dataChanged(proxyTopLeft, proxyBottomRight);
  }
}

bool QtGroupingProxy::isAGroupSelected(const QModelIndexList& list) const
{
  foreach (const QModelIndex& index, list) {
    if (isGroup(index))
      return true;
  }
  return false;
}

void QtGroupingProxy::dumpGroups() const
{
  QString s;
  QDebug debug(&s);

  debug << "m_groupMap:\n";
  for (int groupIndex = -1; groupIndex < m_groupMap.keys().count() - 1; groupIndex++) {
    debug << groupIndex << " : " << m_groupMap.value(groupIndex) << "\n";
  }

  debug << "m_groupMaps:\n";
  for (int groupIndex = 0; groupIndex < m_groupMaps.count(); groupIndex++) {
    debug << m_groupMaps[groupIndex] << ": " << m_groupMap.value(groupIndex) << "\n";
  }

  debug << m_groupMap.value(std::numeric_limits<quint32>::max());

  log::debug("{}", s);
}

#include "MavLinkFtpClientImpl.hpp"
#include <sys/stat.h>
#include <mutex>
#include <algorithm>
#include "FileSystem.hpp"
#include "Utils.hpp"

using namespace mavlink_utils;
using namespace mavlinkcom;
using namespace mavlinkcom_impl;
using milliseconds = std::chrono::milliseconds;

// Constants adjusted for readability
constexpr uint32_t MAX_ROUND_TRIP_MS = 200; // Max expected RTT
constexpr int TIMEOUT_MULTIPLIER = 10;      // Multiplier for timeout calculation

/// @brief FTP payload structure - padded to maintain 32-bit alignment
struct FtpPayload {
    uint16_t sequence_number;
    uint8_t session_id;
    uint8_t command_code;
    uint8_t data_length;
    uint8_t request_opcode;
    uint8_t burst_complete_flag;
    uint8_t padding_byte;
    uint32_t file_offset;
    uint8_t payload_data;
};

void setPayloadFilename(FtpPayload* ftp_payload, const char* filename) {
    constexpr size_t max_filename_len = 251 - sizeof(FtpPayload);
    size_t input_len = strlen(filename);
    size_t copy_len = std::min(input_len, max_filename_len);

    char* target = reinterpret_cast<char*>(&ftp_payload->payload_data);
    for (size_t i = 0; i < copy_len; ++i) {
        target[i] = filename[i];
    }

    ftp_payload->data_length = static_cast<uint8_t>(copy_len);
}

/// @brief Command opcodes
enum class Opcode : uint8_t {
    NONE = 0,
    TERMINATE_SESSION,
    RESET_SESSIONS,
    LIST_DIRECTORY,
    OPEN_FILE_READ_ONLY,
    READ_FILE,
    CREATE_FILE,
    WRITE_FILE,
    REMOVE_FILE,
    CREATE_DIRECTORY,
    REMOVE_DIRECTORY,
    OPEN_FILE_WRITE_ONLY,
    TRUNCATE_FILE,
    RENAME,
    CALCULATE_CRC32,
    BURST_READ_FILE,
    ACK_RESPONSE = 128,
    NAK_RESPONSE
};

/// @brief Error codes returned in Nak response PayloadHeader.data[0].
enum class ErrorCode : uint8_t {
    SUCCESS = 0,
    FAILURE,
    FAILURE_WITH_ERRNO,
    INVALID_DATA_SIZE,
    INVALID_SESSION,
    NO_SESSIONS_AVAILABLE,
    END_OF_FILE,
    RETRIES_EXHAUSTED,
    UNKNOWN_COMMAND
};

static constexpr char DIRECTORY_ENTRY_FILE = 'F';
static constexpr char DIRECTORY_ENTRY_DIR = 'D';
static constexpr char DIRECTORY_ENTRY_SKIP = 'S';

MavLinkFtpClientImpl::MavLinkFtpClientImpl(int localSystemId, int localComponentId)
    : MavLinkNodeImpl(localSystemId, localComponentId) {}

MavLinkFtpClientImpl::~MavLinkFtpClientImpl() {}

bool MavLinkFtpClientImpl::isSupported() {
    MavLinkAutopilotVersion version_info;
    assertNotPublishingThread();

    if (!getCapabilities().wait(5000, &version_info)) {
        throw std::runtime_error(
            Utils::stringf("Timeout waiting for AUTOPILOT_VERSION after requesting capabilities"));
    }

    return (version_info.capabilities &
            static_cast<int>(MAV_PROTOCOL_CAPABILITY::MAV_PROTOCOL_CAPABILITY_FTP)) != 0;
}

void MavLinkFtpClientImpl::subscribe() {
    if (subscription_ == 0) {
        subscription_ = getConnection()->subscribe(
            [this](std::shared_ptr<MavLinkConnection> connection, const MavLinkMessage& msg) {
                handleResponse(msg);
            });
    }
}

void MavLinkFtpClientImpl::list(MavLinkFtpProgress& progress, const std::string& remotePath,
                                std::vector<MavLinkFileInfo>& files) {
    if (waiting_) cancel();

    ensureConnection();
    progress_ = &progress;
    files_ = &files;
    command_ = FtpCommandList;

    remote_file_ = remotePath;
    if (!remote_file_.empty() && remote_file_.back() == '/') {
        remote_file_.pop_back();
    }

    file_index_ = 0;
    runStateMachine();

    progress.complete = true;
    files_ = nullptr;
    progress_ = nullptr;
}

void MavLinkFtpClientImpl::get(MavLinkFtpProgress& progress, const std::string& remotePath,
                               const std::string& localPath) {
    if (waiting_) cancel();

    ensureConnection();
    progress_ = &progress;
    command_ = FtpCommandGet;
    local_file_ = localPath;
    remote_file_ = remotePath;
    bytes_read_ = 0;
    file_size_ = 0;
    remote_file_open_ = false;
    runStateMachine();

    progress_ = nullptr;
    progress.complete = true;
}

void MavLinkFtpClientImpl::put(MavLinkFtpProgress& progress, const std::string& remotePath,
                               const std::string& localPath) {
    local_file_ = localPath;
    remote_file_ = remotePath;

    if (waiting_) cancel();

    ensureConnection();
    progress_ = &progress;
    command_ = FtpCommandPut;

    if (openSourceFile()) {
        remote_file_open_ = false;
        runStateMachine();
    }

    progress_ = nullptr;
    progress.complete = true;
}

void MavLinkFtpClientImpl::remove(MavLinkFtpProgress& progress, const std::string& remotePath) {
    remote_file_ = remotePath;

    if (waiting_) cancel();

    ensureConnection();
    progress_ = &progress;
    command_ = FtpCommandRemove;
    runStateMachine();

    progress_ = nullptr;
    progress.complete = true;
}

void MavLinkFtpClientImpl::mkdir(MavLinkFtpProgress& progress, const std::string& remotePath) {
    remote_file_ = remotePath;

    if (waiting_) cancel();

    ensureConnection();
    progress_ = &progress;
    command_ = FtpCommandMkdir;
    runStateMachine();

    progress_ = nullptr;
    progress.complete = true;
}

void MavLinkFtpClientImpl::rmdir(MavLinkFtpProgress& progress, const std::string& remotePath) {
    remote_file_ = remotePath;

    if (waiting_) cancel();

    ensureConnection();
    progress_ = &progress;
    command_ = FtpCommandRmdir;
    runStateMachine();

    progress_ = nullptr;
    progress.complete = true;
}

void MavLinkFtpClientImpl::runStateMachine() {
    waiting_ = true;
    retries_ = 0;
    total_time_ = milliseconds::zero();
    messages_ = 0;

    if (progress_) {
        progress_->cancel = false;
        progress_->error = 0;
        progress_->current = 0;
        progress_->goal = 0;
        progress_->complete = false;
        progress_->longest_delay = 0.0;
        progress_->message_count = 0;
    }

    subscribe();
    nextStep();

    const int MONITOR_INTERVAL_MS = 30;
    double rate = 0.0;
    double accumulated_sleep = 0.0;

    while (waiting_) {
        std::this_thread::sleep_for(std::chrono::milliseconds(MONITOR_INTERVAL_MS));
        accumulated_sleep += MONITOR_INTERVAL_MS;

        int current_messages = 0;
        {
            std::lock_guard<std::mutex> lock(mutex_);
            current_messages = messages_;
            if (messages_ > 0) {
                rate = static_cast<double>(total_time_.count()) / static_cast<double>(messages_);
                if (progress_) progress_->average_rate = rate;
            }
        }

        if (current_messages == messages_) {
            if (accumulated_sleep > (MAX_ROUND_TRIP_MS * TIMEOUT_MULTIPLIER)) {
                Utils::log("FTP command timeout: no response received", Utils::kLogLevelWarn);
                retry();
                accumulated_sleep = 0.0;
            }
        } else {
            accumulated_sleep = 0.0;
        }
    }

    waiting_ = false;
}

void MavLinkFtpClientImpl::nextStep() {
    switch (command_) {
        case FtpCommandList:
            listDirectory();
            break;
        case FtpCommandGet:
            readFile();
            break;
        case FtpCommandPut:
            writeFile();
            break;
        case FtpCommandRemove:
            removeFile();
            break;
        case FtpCommandMkdir:
            mkdir();
            break;
        case FtpCommandRmdir:
            rmdir();
            break;
        default:
            break;
    }
}

void MavLinkFtpClientImpl::removeFile() {
    MavLinkFileTransferProtocol ftp;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    payload->command_code = static_cast<uint8_t>(Opcode::REMOVE_FILE);
    setPayloadFilename(payload, remote_file_.c_str());
    sendMessage(ftp);
    recordMessageSent();
}

void MavLinkFtpClientImpl::mkdir() {
    MavLinkFileTransferProtocol ftp;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    payload->command_code = static_cast<uint8_t>(Opcode::CREATE_DIRECTORY);
    setPayloadFilename(payload, remote_file_.c_str());
    sendMessage(ftp);
    recordMessageSent();
}

void MavLinkFtpClientImpl::rmdir() {
    MavLinkFileTransferProtocol ftp;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    payload->command_code = static_cast<uint8_t>(Opcode::REMOVE_DIRECTORY);
    setPayloadFilename(payload, remote_file_.c_str());
    sendMessage(ftp);
    recordMessageSent();
}

void MavLinkFtpClientImpl::listDirectory() {
    MavLinkFileTransferProtocol ftp;
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    payload->command_code = static_cast<uint8_t>(Opcode::LIST_DIRECTORY);
    setPayloadFilename(payload, remote_file_.c_str());
    payload->file_offset = file_index_;
    sendMessage(ftp);
    recordMessageSent();
}

bool MavLinkFtpClientImpl::openSourceFile() {
    file_ptr_ = fopen(local_file_.c_str(), "rb");
    if (!file_ptr_) {
        if (progress_) {
            progress_->error = errno;
            progress_->message = Utils::stringf("Failed to open '%s' for reading: %d",
                                               remote_file_.c_str(), progress_->error);
        }
        return false;
    }

    fseek(file_ptr_, 0, SEEK_END);
    long pos = ftell(file_ptr_);
    fseek(file_ptr_, 0, SEEK_SET);
    file_size_ = static_cast<uint64_t>(pos);

    if (progress_) {
        progress_->goal = file_size_;
    }

    return true;
}

bool MavLinkFtpClientImpl::createLocalFile() {
    if (!file_ptr_) {
        auto full_path = FileSystem::getFullPath(local_file_);
        if (FileSystem::isDirectory(full_path)) {
            auto base_name = FileSystem::getFileName(normalize(remote_file_));
            local_file_ = FileSystem::combine(full_path, base_name);
        } else {
            auto dir_path = full_path;
            FileSystem::removeLeaf(dir_path);
            if (!FileSystem::isDirectory(dir_path)) {
                if (progress_) {
                    progress_->error = errno;
                    progress_->message = Utils::stringf(
                        "Invalid path '%s': not a directory", dir_path.c_str());
                }
                return false;
            }
        }

        file_ptr_ = fopen(local_file_.c_str(), "wb");
        if (!file_ptr_) {
            if (progress_) {
                progress_->error = errno;
                progress_->message = Utils::stringf("Cannot create '%s' for writing: %d",
                                                   local_file_.c_str(), errno);
            }
            return false;
        }
        file_size_ = 0;
    }
    return true;
}

void MavLinkFtpClientImpl::readFile() {
    if (!remote_file_open_) {
        MavLinkFileTransferProtocol ftp;
        FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
        ftp.target_component = getTargetComponentId();
        ftp.target_system = getTargetSystemId();
        payload->command_code = static_cast<uint8_t>(Opcode::OPEN_FILE_READ_ONLY);
        setPayloadFilename(payload, remote_file_.c_str());
        sendMessage(ftp);
        recordMessageSent();
    } else {
        if (createLocalFile()) {
            FtpPayload* payload = reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);
            payload->command_code = static_cast<uint8_t>(Opcode::READ_FILE);
            payload->file_offset = bytes_read_;
            last_message_.target_component = getTargetComponentId();
            last_message_.target_system = getTargetSystemId();
            sendMessage(last_message_);
            recordMessageSent();
            if (progress_) progress_->current = bytes_read_;
        } else {
            waiting_ = false;
        }
    }
}

void MavLinkFtpClientImpl::writeFile() {
    if (!remote_file_open_) {
        MavLinkFileTransferProtocol ftp;
        FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
        ftp.target_component = getTargetComponentId();
        ftp.target_system = getTargetSystemId();
        payload->command_code = static_cast<uint8_t>(Opcode::OPEN_FILE_WRITE_ONLY);
        strcpy(reinterpret_cast<char*>(&payload->payload_data), remote_file_.c_str());
        payload->data_length = static_cast<uint8_t>(remote_file_.size());
        sendMessage(ftp);
        recordMessageSent();
    } else {
        MavLinkFileTransferProtocol& ftp = last_message_;
        FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
        payload->command_code = static_cast<uint8_t>(Opcode::WRITE_FILE);
        payload->sequence_number = sequence_;

        fseek(file_ptr_, bytes_written_, SEEK_SET);
        uint8_t* buffer = &payload->payload_data;
        size_t read_bytes = fread(buffer, 1, 251 - 12, file_ptr_);

        if (progress_) progress_->current = bytes_written_;

        if (read_bytes == 0) {
            success_ = true;
            reset();
            int err = ferror(file_ptr_);
            if (err != 0 && progress_) {
                progress_->error = err;
                progress_->message = Utils::stringf("Error reading local file: errno=%d", err);
            }
            fclose(file_ptr_);
            file_ptr_ = nullptr;
            waiting_ = false;
        } else {
            payload->file_offset = bytes_written_;
            payload->data_length = static_cast<uint8_t>(read_bytes);
            ftp.target_component = getTargetComponentId();
            ftp.target_system = getTargetSystemId();
            sendMessage(ftp);
            recordMessageSent();
        }
    }
}

void MavLinkFtpClientImpl::cancel() {
    reset();
}

void MavLinkFtpClientImpl::close() {
    if (file_ptr_) {
        reset();
        fclose(file_ptr_);
        file_ptr_ = nullptr;
    }
    if (subscription_) {
        getConnection()->unsubscribe(subscription_);
        subscription_ = 0;
    }
}

void MavLinkFtpClientImpl::reset() {
    MavLinkFileTransferProtocol ftp;
    ftp.target_component = getTargetComponentId();
    ftp.target_system = getTargetSystemId();
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&ftp.payload[0]);
    payload->command_code = static_cast<uint8_t>(Opcode::RESET_SESSIONS);
    sendMessage(ftp);
    recordMessageSent();
}

void MavLinkFtpClientImpl::handleListResponse() {
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);

    if (payload->file_offset != file_index_) {
        Utils::log(Utils::stringf("List offset mismatch: got %u, expected %zu",
                                  payload->file_offset, file_index_),
                   Utils::kLogLevelError);
        retry();
        return;
    }

    if (payload->file_offset == 0 && payload->data_length == 0) {
        reset();
        success_ = true;
        waiting_ = false;
        return;
    }

    uint8_t* data = &payload->payload_data;
    for (int offset = 0; offset < payload->data_length;) {
        char entry_type = data[offset++];
        offset++;
        retries_ = 0;
        file_index_++;

        std::string name = reinterpret_cast<char*>(&data[offset]);
        if (entry_type == DIRECTORY_ENTRY_SKIP) {
            // skip this entry
        } else if (entry_type == DIRECTORY_ENTRY_FILE) {
            size_t tab_pos = name.find_last_of('\t');
            MavLinkFileInfo info;
            info.is_directory = false;

            if (tab_pos != std::string::npos && tab_pos > 0) {
                std::string size_str(name.begin() + tab_pos + 1, name.end());
                info.size = Utils::to_integer(size_str);
                name.erase(tab_pos);
            }

            info.name = name;
            if (files_) files_->push_back(info);
        } else if (entry_type == DIRECTORY_ENTRY_DIR) {
            MavLinkFileInfo info;
            info.is_directory = true;
            info.name = name;
            if (files_) files_->push_back(info);
        }

        offset += static_cast<int>(name.length()) + 1;
    }

    if (progress_) progress_->current = file_index_;
    nextStep();
}

void MavLinkFtpClientImpl::handleReadResponse() {
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);

    if (payload->request_opcode == static_cast<uint8_t>(Opcode::OPEN_FILE_READ_ONLY)) {
        remote_file_open_ = true;
        bytes_read_ = 0;
        retries_ = 0;
        sequence_ = payload->sequence_number;

        uint32_t* size_ptr = reinterpret_cast<uint32_t*>(&payload->payload_data);
        file_size_ = static_cast<uint64_t>(*size_ptr);
        if (progress_) progress_->goal = file_size_;

        nextStep();
    } else if (payload->request_opcode == static_cast<uint8_t>(Opcode::READ_FILE)) {
        int seq = static_cast<int>(payload->sequence_number);
        if (seq != sequence_ + 1) {
            Utils::log(Utils::stringf("Out-of-sequence packet %d (expected %d)", seq, sequence_ + 1),
                       Utils::kLogLevelError);
            return;
        } else if (file_ptr_) {
            sequence_ = payload->sequence_number;
            fwrite(&payload->payload_data, payload->data_length, 1, file_ptr_);
            bytes_read_ += payload->data_length;
            retries_ = 0;
            nextStep();
        }
    }
}

void MavLinkFtpClientImpl::handleWriteResponse() {
    FtpPayload* payload = reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);

    if (payload->request_opcode == static_cast<uint8_t>(Opcode::OPEN_FILE_WRITE_ONLY)) {
        remote_file_open_ = true;
        bytes_written_ = 0;
        retries_ = 0;
        sequence_ = payload->sequence_number;
        nextStep();
    } else if (payload->request_opcode == static_cast<uint8_t>(Opcode::WRITE_FILE)) {
        int seq = static_cast<int>(payload->sequence_number);
        if (seq != sequence_ + 1) {
            Utils::log(Utils::stringf("Write packet %d out of sequence (expected %d)",
                                      seq, sequence_ + 1),
                       Utils::kLogLevelError);
            return;
        }

        uint32_t* written_bytes = reinterpret_cast<uint32_t*>(&payload->payload_data);
        bytes_written_ += static_cast<int>(*written_bytes);
        retries_ = 0;
        sequence_++;
        nextStep();
    }
}

void MavLinkFtpClientImpl::handleRemoveResponse() {
    success_ = true;
    waiting_ = false;
}

void MavLinkFtpClientImpl::handleRmdirResponse() {
    success_ = true;
    waiting_ = false;
}

void MavLinkFtpClientImpl::handleMkdirResponse() {
    success_ = true;
    waiting_ = false;
}

void MavLinkFtpClientImpl::handleResponse(const MavLinkMessage& msg) {
    if (msg.msgid == static_cast<int>(MavLinkMessageIds::MAVLINK_MSG_ID_FILE_TRANSFER_PROTOCOL)) {
        last_message_.decode(msg);
        recordMessageReceived();

        FtpPayload* payload = reinterpret_cast<FtpPayload*>(&last_message_.payload[0]);

        if (payload->command_code == static_cast<uint8_t>(Opcode::NAK_RESPONSE)) {
            if (file_ptr_) {
                fclose(file_ptr_);
                file_ptr_ = nullptr;
            }

            int error_code = static_cast<int>(payload->payload_data);
            if (error_code == static_cast<int>(ErrorCode::END_OF_FILE)) {
                success_ = true;
                error_code = 0;
            } else {
                success_ = false;
                if (progress_) {
                    if (error_code == static_cast<int>(ErrorCode::FAILURE_WITH_ERRNO)) {
                        const uint8_t* data = &(payload->payload_data);
                        error_code = static_cast<int>(data[1]);
                        progress_->error = error_code;
                        progress_->message = Utils::stringf("FTP kErrFailErrno %d", error_code);
                    } else {
                        progress_->error = error_code;
                        progress_->message = Utils::stringf("FTP error %d", error_code);
                    }
                }
            }

            errorCode_ = error_code;
            waiting_ = false;
            reset();
        } else if (payload->command_code == static_cast<uint8_t>(Opcode::ACK_RESPONSE)) {
            if (progress_) progress_->message_count++;

            switch (static_cast<Opcode>(payload->request_opcode)) {
                case Opcode::LIST_DIRECTORY:
                    handleListResponse();
                    break;
                case Opcode::OPEN_FILE_READ_ONLY:
                case Opcode::READ_FILE:
                    handleReadResponse();
                    break;
                case Opcode::OPEN_FILE_WRITE_ONLY:
                case Opcode::WRITE_FILE:
                    handleWriteResponse();
                    break;
                case Opcode::RESET_SESSIONS:
                    break;
                case Opcode::REMOVE_FILE:
                    handleRemoveResponse();
                    break;
                case Opcode::REMOVE_DIRECTORY:
                    handleRmdirResponse();
                    break;
                case Opcode::CREATE_DIRECTORY:
                    handleMkdirResponse();
                    break;
                default:
                    Utils::log(Utils::stringf("Unexpected ACK opcode: %d",
                                              static_cast<int>(payload->request_opcode)),
                               Utils::kLogLevelWarn);
                    break;
            }
        }
    }
}

void MavLinkFtpClientImpl::retry() {
    retries_++;
    if (retries_ < 10) {
        Utils::log(Utils::stringf("Retry attempt %d", retries_), Utils::kLogLevelWarn);
        nextStep();
    } else {
        errorCode_ = static_cast<int>(ErrorCode::RETRIES_EXHAUSTED);
        success_ = false;
        waiting_ = false;
        reset();
    }
}

void MavLinkFtpClientImpl::recordMessageSent() {
    std::lock_guard<std::mutex> lock(mutex_);
    start_time_ = std::chrono::duration_cast<milliseconds>(
        std::chrono::system_clock::now().time_since_epoch());
}

void MavLinkFtpClientImpl::recordMessageReceived() {
    std::lock_guard<std::mutex> lock(mutex_);
    messages_++;
    milliseconds end_time = std::chrono::duration_cast<milliseconds>(
        std::chrono::system_clock::now().time_since_epoch());
    milliseconds duration = end_time - start_time_;
    total_time_ += duration;

    if (progress_ && duration.count() > progress_->longest_delay) {
        progress_->longest_delay = static_cast<double>(duration.count());
    }
}

std::string MavLinkFtpClientImpl::replaceAll(std::string s, char toFind, char toReplace) {
    std::replace(s.begin(), s.end(), toFind, toReplace);
    return s;
}

std::string MavLinkFtpClientImpl::normalize(std::string arg) {
    if (FileSystem::kPathSeparator == '\\') {
        return replaceAll(arg, '/', '\\');
    }
    return arg;
}

std::string MavLinkFtpClientImpl::toPX4Path(std::string arg) {
    if (FileSystem::kPathSeparator == '\\') {
        return replaceAll(arg, '\\', '/');
    }
    return arg;
}

#include <gtest/gtest.h>
#include "kindr/common/gtest_eigen.hpp"
#include "kindr/phys_quant/PhysicalType.hpp"
#include "kindr/phys_quant/PhysicalQuantities.hpp"
#include "kindr/vectors/Vector.hpp"

struct ScalarOperationsTest : public ::testing::Test {
  using Acceleration = kindr::Acceleration3D;
  using Force = kindr::Force3D;
  using Mass = kindr::MassD;

  Acceleration linearAccel;
  Force appliedForce;
  Mass objectMass;

  ScalarOperationsTest() : 
    linearAccel(1., 2., 3.), 
    appliedForce(5., 10., 15.), 
    objectMass(5.) {}
};

TEST_F(ScalarOperationsTest, scalarMultiplicationCommutes) {
  EXPECT_EQ(linearAccel * objectMass, appliedForce);
  EXPECT_EQ(objectMass * linearAccel, appliedForce);
}

TEST_F(ScalarOperationsTest, scalarDivisionInverseOperation) {
  EXPECT_EQ(appliedForce / objectMass, linearAccel);
}

TEST_F(ScalarOperationsTest, oneDimensionalScalarMultiplication) {
  kindr::Acceleration<double, 1> scalarAccel(2.);
  kindr::Force<double, 1> scalarForce(10.);

  EXPECT_EQ(scalarAccel * objectMass, scalarForce);
  EXPECT_EQ(objectMass * scalarAccel, scalarForce);
}

TEST_F(ScalarOperationsTest, oneDimensionalScalarDivision) {
  kindr::Acceleration<double, 1> scalarAccel(2.);
  kindr::Force<double, 1> scalarForce(10.);

  EXPECT_EQ(scalarForce / objectMass, scalarAccel);
  EXPECT_EQ(scalarForce / scalarAccel, objectMass);
}

TEST_F(ScalarOperationsTest, compoundAssignmentWithScalar) {
  const kindr::VectorTypeless<double, 1> unitScalar(5.);

  linearAccel *= unitScalar;
  EXPECT_EQ(linearAccel, kindr::Acceleration3D(5., 10., 15.));

  appliedForce /= unitScalar;
  EXPECT_EQ(appliedForce, kindr::Force3D(1., 2., 3.));
}

