namespace async_web_server_cpp
{
WebsocketConnection::WebsocketConnection(HttpConnectionPtr connection)
    : connection_(connection)
{
}

void WebsocketConnection::set_message_handler(MessageHandler& handler)
{
    handler_ = handler;
}

bool WebsocketConnection::sendTextMessage(const std::string& content)
{
    WebsocketMessage msg;
    msg.type = WebsocketMessage::type_text;
    msg.content = content;
    return transmitFrame(msg);
}

bool WebsocketConnection::sendPingMessage(const std::string& content)
{
    WebsocketMessage msg;
    msg.type = WebsocketMessage::type_ping;
    msg.content = content;
    return transmitFrame(msg);
}

bool WebsocketConnection::transmitFrame(const WebsocketMessage& message)
{
    WebsocketFrame frame;
    if (frame.fromMessage(message))
    {
        return deliverFrame(frame);
    }
    return false;
}

bool WebsocketConnection::deliverFrame(WebsocketFrame& frame)
{
    std::vector<unsigned char> buffer;
    if (frame.serialize(buffer))
    {
        connection_->write_and_clear(buffer);
        return true;
    }
    return false;
}

void WebsocketConnection::static_handle_read(
    WebsocketConnectionWeakPtr weak_this, const char* data_start, const char* data_end)
{
    WebsocketConnectionPtr self = weak_this.lock();
    if (self)
        self->processIncomingData(data_start, data_end);
}

void WebsocketConnection::processIncomingData(const char* data_start, const char* data_end)
{
    boost::tribool parse_status;
    const char* current_pos = data_start;

    while (current_pos < data_end)
    {
        boost::tie(parse_status, current_pos) =
            frame_parser_.parse(current_frame_, current_pos, data_end);

        if (parse_status)
        {
            frame_parser_.reset();
            boost::tribool message_status =
                frame_buffer_.consume(current_message_, current_frame_);

            if (message_status && handler_)
            {
                handler_(current_message_);
            }
        }
        else if (!boost::logic::indeterminate(parse_status))
        {
            frame_parser_.reset();
            current_message_.type = WebsocketMessage::type_unknown;
        }
    }

    WebsocketConnectionWeakPtr self_weak(shared_from_this());
    connection_->async_read(boost::bind(
        &WebsocketConnection::static_handle_read, self_weak, 
        boost::placeholders::_1, boost::placeholders::_2));
}
