void XmlImportTest::parseMinimalReclassXml() {
    // Generate a temporary XML file with minimal valid ReClass structure
    QTemporaryFile xmlFile;
    xmlFile.setAutoRemove(true);
    QVERIFY(xmlFile.open());

    const char* xmlContent = R"(<?xml version="1.0" encoding="UTF-8"?>
<ReClass>
    <!--ReClassEx-->
    <Class Name="TestClass" Type="28" Comment="" Offset="0" strOffset="0" Code="">
        <Node Name="vtable" Type="9" Size="8" bHidden="false" Comment=""/>
        <Node Name="health" Type="13" Size="4" bHidden="false" Comment=""/>
        <Node Name="name" Type="18" Size="32" bHidden="false" Comment=""/>
        <Node Name="position" Type="23" Size="12" bHidden="false" Comment=""/>
        <Node Name="pNext" Type="8" Size="8" bHidden="false" Comment="" Pointer="TestClass"/>
    </Class>
</ReClass>)";

    xmlFile.write(xmlContent);
    xmlFile.flush();

    QString errorMsg;
    NodeTree parsedTree = importReclassXml(xmlFile.fileName(), &errorMsg);

    // Verify parsing succeeded and produced expected node count
    QVERIFY2(!parsedTree.nodes.empty(), qPrintable(errorMsg));
    QCOMPARE(parsedTree.nodes.size(), 6);

    // Validate root struct node
    QCOMPARE(parsedTree.nodes[0].kind, NodeKind::Struct);
    QCOMPARE(parsedTree.nodes[0].name, QStringLiteral("TestClass"));

    // First child: vtable (Int64)
    QCOMPARE(parsedTree.nodes[1].kind, NodeKind::Int64);
    QCOMPARE(parsedTree.nodes[1].name, QStringLiteral("vtable"));
    QCOMPARE(parsedTree.nodes[1].offset, 0);

    // Second child: health (Float)
    QCOMPARE(parsedTree.nodes[2].kind, NodeKind::Float);
    QCOMPARE(parsedTree.nodes[2].name, QStringLiteral("health"));
    QCOMPARE(parsedTree.nodes[2].offset, 8);

    // Third child: name (UTF8, length 32)
    QCOMPARE(parsedTree.nodes[3].kind, NodeKind::UTF8);
    QCOMPARE(parsedTree.nodes[3].strLen, 32);
    QCOMPARE(parsedTree.nodes[3].offset, 12);

    // Fourth child: position (Vec3)
    QCOMPARE(parsedTree.nodes[4].kind, NodeKind::Vec3);
    QCOMPARE(parsedTree.nodes[4].offset, 44);

    // Fifth child: pNext (Pointer64 to TestClass)
    QCOMPARE(parsedTree.nodes[5].kind, NodeKind::Pointer64);
    QCOMPARE(parsedTree.nodes[5].name, QStringLiteral("pNext"));
    QVERIFY(parsedTree.nodes[5].refId != 0);
    QCOMPARE(parsedTree.nodes[5].refId, parsedTree.nodes[0].id); // Ensure pointer resolves correctly
}

