// Helper to configure signal handlers with error checking
static void ConfigureSignal(int sigNum, void (*handler)(int, siginfo_t *, void *)) {
    struct sigaction action;
    std::memset(&action, 0, sizeof(action));
    action.sa_sigaction = handler;
    if (sigaction(sigNum, &action, nullptr) != 0) {
        Printf("libFuzzer: failed to set signal handler for %d: %s\n", sigNum, std::strerror(errno));
        std::exit(EXIT_FAILURE);
    }
}

// Set alarm-based timeout using itimerval
static void ArmAlarmTimer(int seconds) {
    struct itimerval timer{};
    timer.it_value.tv_sec = seconds;
    timer.it_interval.tv_sec = seconds;

    if (setitimer(ITIMER_REAL, &timer, nullptr) != 0) {
        Printf("libFuzzer: setitimer failed: %s\n", std::strerror(errno));
        std::exit(EXIT_FAILURE);
    }
}

void SetTimer(int durationSeconds) {
    // Use half the unit timeout plus one second as interval
    int interval = (durationSeconds > 0) ? (durationSeconds / 2 + 1) : 0;
    if (interval > 0) {
        ArmAlarmTimer(interval);
        ConfigureSignal(SIGALRM, AlarmHandler);
    }
}

void SetSignalHandler(const FuzzingOptions& opts) {
    if (opts.UnitTimeoutSec > 0)
        SetTimer(opts.UnitTimeoutSec);

    if (opts.HandleInt)
        ConfigureSignal(SIGINT, InterruptHandler);
    if (opts.HandleTerm)
        ConfigureSignal(SIGTERM, InterruptHandler);
    if (opts.HandleSegv)
        ConfigureSignal(SIGSEGV, CrashHandler);
    if (opts.HandleBus)
        ConfigureSignal(SIGBUS, CrashHandler);
    if (opts.HandleAbrt)
        ConfigureSignal(SIGABRT, CrashHandler);
    if (opts.HandleIll)
        ConfigureSignal(SIGILL, CrashHandler);
    if (opts.HandleFpe)
        ConfigureSignal(SIGFPE, CrashHandler);
}

