#include <bits/stdc++.h>
using namespace std;

// Helper: Block structure for sqrt decomposition
struct Block {
    int start, end;          // inclusive [start, end)
    vector<pair<int, int>> sorted_unique;  // (value, index) sorted by value, unique values only
};

class Solution {
public:
    int longestBalanced(vector<int>& nums) {
        int n = nums.size();
        if (n == 0) return 0;

        const int BLOCK_SIZE = static_cast<int>(sqrt(n)) + 1;
        const int NUM_BLOCKS = (n + BLOCK_SIZE) / BLOCK_SIZE;

        vector<long long> base(n);           // raw array values
        vector<long long> block_lazy(NUM_BLOCKS, 0);
        vector<Block> blocks(NUM_BLOCKS);

        // Initialize blocks
        for (int b = 0; b < NUM_BLOCKS; ++b) {
            blocks[b].start = b * BLOCK_SIZE;
            blocks[b].end = min((b + 1) * BLOCK_SIZE, n);
            blocks[b].sorted_unique.reserve(blocks[b].end - blocks[b].start + 5);
        }

        // Function to rebuild one block's sorted unique list
        auto rebuild_block = [&](int b) {
            vector<pair<int, int>> temp;
            temp.reserve(blocks[b].end - blocks[b].start);
            for (int i = blocks[b].start; i < blocks[b].end; ++i) {
                temp.emplace_back(static_cast<int>(base[i] + block_lazy[b]), i);
            }
            sort(temp.begin(), temp.end(), [](const auto& a, const auto& b) {
                if (a.first != b.first) return a.first < b.first;
                return a.second < b.second;
            });
            blocks[b].sorted_unique.clear();
            int prev_val = INT_MIN;
            for (auto& p : temp) {
                if (p.first != prev_val) {
                    prev_val = p.first;
                    blocks[b].sorted_unique.emplace_back(p.first, p.second);
                }
            }
        };

        // Rebuild all blocks initially
        for (int b = 0; b < NUM_BLOCKS; ++b) rebuild_block(b);

        // Get actual value at index i (including lazy offset)
        auto get_value = [&](int i) -> int {
            int blk = i / BLOCK_SIZE;
            return static_cast<int>(base[i] + block_lazy[blk]);
        };

        // Find leftmost index <= r with value == target
        auto find_leftmost = [&](int r, int target) -> int {
            int blk_r = r / BLOCK_SIZE;
            int key = target;

            // Check earlier blocks
            for (int b = 0; b < blk_r; ++b) {
                int needed = key - block_lazy[b];
                auto& vec = blocks[b].sorted_unique;
                auto it = lower_bound(vec.begin(), vec.end(), make_pair(needed, 0));
                if (it != vec.end() && it->first == needed) {
                    return it->second;
                }
            }

            // Scan current block manually
            for (int i = blocks[blk_r].start; i <= r; ++i) {
                if (get_value(i) == target) return i;
            }

            return -1;
        };

        // Apply delta to subarray [l, r)
        auto apply_delta = [&](int l, int r, int delta) {
            if (l >= r) return;

            int b_l = l / BLOCK_SIZE;
            int b_r = (r - 1) / BLOCK_SIZE;

            if (b_l == b_r) {
                for (int i = l; i < r; ++i) base[i] += delta;
                rebuild_block(b_l);
            } else {
                // Left partial block
                if (l != blocks[b_l].start) {
                    for (int i = l; i < blocks[b_l].end; ++i) base[i] += delta;
                    rebuild_block(b_l);
                } else {
                    block_lazy[b_l] += delta;
                }

                // Full middle blocks
                for (int b = b_l + 1; b < b_r; ++b) {
                    block_lazy[b] += delta;
                }

                // Right partial block
                if (r != blocks[b_r].end) {
                    for (int i = blocks[b_r].start; i < r; ++i) base[i] += delta;
                    rebuild_block(b_r);
                } else {
                    block_lazy[b_r] += delta;
                }
            }
        };

        // Main logic
        vector<int> last_occurrence(100001, -1);
        int max_len = 0;

        for (int right = 0; right < n; ++right) {
            int val = nums[right];
            int prev = last_occurrence[val];
            int delta = (val % 2 == 1) ? 1 : -1;

            apply_delta(prev + 1, right + 1, delta);
            last_occurrence[val] = right;

            int cur_sum = get_value(right);
            int left_idx = find_leftmost(right, cur_sum);
            if (left_idx != -1) {
                max_len = max(max_len, right - left_idx + 1);
            }
        }

        return max_len;
    }
};

