// Helper lambda to extract and log server error messages if present
static void LogServerErrorIfPresent(const ResponseMessage& rm) {
    auto err_code = rm.GetErrorCode();
    if (err_code != 0) {
        auto result_val = rm.GetResult();
        json json_msg = result_val["message"];
        if (json_msg.is_string()) {
