// Wrapper class for converting async results via message-based providers
class AsyncResultMessageConverter : public AsyncResult {
public:
    AsyncResultMessageConverter(AsyncResultMessageConverter&& other)
        : AsyncResult(std::move(other)) {}

    explicit AsyncResultMessageConverter(const TAsyncResult<Message>& ar_msg)
        : AsyncResult(new AsyncResultProviderMessageConverter(ar_msg)) {}

    explicit AsyncResultMessageConverter(TAsyncResult<Message>&& ar_msg)
        : AsyncResult(
              new AsyncResultProviderMessageConverter(std::move(ar_msg))) {}

    bool IsCompleted() const override {
        return reinterpret_cast<AsyncResultProviderMessageConverter*>(piref_counted_)->IsCompleted();
    }

    Status AwaitCompletion() override {
        return reinterpret_cast<AsyncResultProviderMessageConverter*>(piref_counted_)->AwaitCompletion();
    }
};

// Internal provider implementation that wraps raw async result and handles deserialization
class AsyncResultProviderMessageConverter : public TRefCounted {
private:
    TAsyncResultProvider<Message>* piasyncresultprovider_ = nullptr;

public:
    explicit AsyncResultProviderMessageConverter(const TAsyncResult<Message>& ar_msg)
        : TRefCounted(),
          piasyncresultprovider_(reinterpret_cast<TAsyncResultProvider<Message>*>(
              AsyncResultManager::GetPSelfDelete(ar_msg))) {
        if (piasyncresultprovider_) piasyncresultprovider_->AddRef();
    }

    explicit AsyncResultProviderMessageConverter(TAsyncResult<Message>&& ar_msg)
        : TRefCounted(),
          piasyncresultprovider_(reinterpret_cast<TAsyncResultProvider<Message>*>(
              AsyncResultManager::GetPSelfDelete(ar_msg))) {
        // Transfer ownership by nullifying original pointer
        AsyncResultManager::GetPSelfDelete(ar_msg) = nullptr;
    }

    ~AsyncResultProviderMessageConverter() override {
        if (piasyncresultprovider_) {
            piasyncresultprovider_->Release();
            piasyncresultprovider_ = nullptr;
        }
    }

    void Cancel() override {
        if (piasyncresultprovider_) piasyncresultprovider_->Cancel();
    }

    bool IsCompleted() const override {
        return piasyncresultprovider_ ? piasyncresultprovider_->IsCompleted() : false;
    }

    Status AwaitCompletion() override {
        if (!piasyncresultprovider_) return Status::Failed;

        Status status = piasyncresultprovider_->AwaitCompletion();
        if (status == Status::OK) {
            const Message& msg = piasyncresultprovider_->GetResult();
            ResponseMessage resp;
            try {
                resp.Deserialize(msg);
            } catch (...) {
                return Status::RejectedByServer;
            }

            LogServerErrorIfPresent(resp);
            status = (resp.GetErrorCode() != 0) ? Status::RejectedByServer : Status::OK;
        }

        return status;
    }
};

// Callback invocation handler for asynchronous responses
void TAsyncResultProvider<Message>::InvokeCallback(const Message& msg) {
    if (!fn_response_callback) return;

    ResponseMessage response;
    try {
        response.Deserialize(msg);
    } catch (const std::exception& ex) {
        client::log.ErrorF(
            "Caught exception deserializing server reply: %s",
            ex.what());
        return;
    }

    try {
        fn_response_callback(response.GetErrorCode(), response.GetResult().dump());
    } catch (const std::exception& ex) {
        client::log.ErrorF(
            "Exception thrown in async callback handler: %s",
            ex.what());
    }
}

