// Device interface GUID for COM ports
static const GUID COM_PORT_INTERFACE_GUID = {0x4d36e978, 0xe325, 0x11ce, 
                                             0xBF, 0xC1, 0x08, 0x00, 0x2B, 0xE1, 0x03, 0x18};

// Extracts Vendor ID and Product ID from a device interface string like "...VID_XXXX&PID_YYYY..."
bool extractVidPid(const std::wstring& devicePath, int* outVid, int* outPid) {
    if (!devicePath.empty() && outVid && outPid) {
        const wchar_t* start = devicePath.c_str();
        const wchar_t* vidMarker = wcsstr(start, L"VID_");
        if (!vidMarker) return false;

        const wchar_t* afterVid = vidMarker + 4;
        wchar_t* endPtr = nullptr;
        long vidVal = wcstol(afterVid, &endPtr, 16);
        *outVid = static_cast<int>(vidVal);

        const wchar_t* pidMarker = wcsstr(endPtr, L"PID_");
        if (!pidMarker) return false;

        const wchar_t* afterPid = pidMarker + 4;
        endPtr = nullptr;
        long pidVal = wcstol(afterPid, &endPtr, 16);
        *outPid = static_cast<int>(pidVal);

        return true;
    }
    return false;
}

// Parses human-readable display name and extracts port name from parentheses, e.g., "(COM3)"
void extractPortInfo(const std::wstring& displayName, SerialPortInfo& info) {
    info.displayName = displayName;
    const wchar_t* openParen = wcsrchr(displayName.c_str(), L'(');
    if (openParen) {
        ++openParen;
        const wchar_t* closeParen = wcschr(openParen, L')');
        if (closeParen) {
            info.portName.assign(openParen, closeParen);
        }
    }
}

// Helper to collect all present COM port interfaces via CM API
std::vector<SerialPortInfo> gatherSerialInterfaces() {
    std::vector<SerialPortInfo> ports;
    ULONG bufferSize = 0;

    // First call to get required buffer size
    CONFIGRET result = CM_Get_Device_Interface_List_SizeW(
        &bufferSize,
        const_cast<GUID*>(&GUID_DEVINTERFACE_COMPORT),
        nullptr,
        CM_GET_DEVICE_INTERFACE_LIST_PRESENT
    );

    if (result != CR_SUCCESS || bufferSize == 0) {
        return ports;
    }

    std::vector<wchar_t> buffer(bufferSize, L'\0');

    // Second call to retrieve actual interface list
    result = CM_Get_Device_Interface_ListW(
        const_cast<GUID*>(&GUID_DEVINTERFACE_COMPORT),
        nullptr,
        buffer.data(),
        static_cast<ULONG>(buffer.size()),
        CM_GET_DEVICE_INTERFACE_LIST_PRESENT
    );

    if (result != CR_SUCCESS || buffer[0] == L'\0') {
        return ports;
    }

    // Iterate over null-terminated strings in buffer
    for (PCWSTR currentInterface = buffer.data(); *currentInterface; ) {
        SerialPortInfo entry;
        entry.vid = 0;
        entry.pid = 0;
        entry.portName = currentInterface;

        // Try to parse VID/PID from raw interface string
        int tempVid = 0, tempPid = 0;
        if (extractVidPid(entry.portName, &tempVid, &tempPid)) {
            entry.vid = tempVid;
            entry.pid = tempPid;
        }

        // Try to fetch friendly name / display name
        DEVPROPTYPE propType;
        WCHAR portNameBuffer[512];
        ULONG propSize = sizeof(portNameBuffer);
        result = CM_Get_Device_Interface_PropertyW(
            currentInterface,
            &PKEY_DeviceInterface_Serial_PortName,
            &propType,
            reinterpret_cast<BYTE*>(portNameBuffer),
            &propSize,
            0
        );

        if (result == CR_SUCCESS && propType == DEVPROP_TYPE_STRING) {
            entry.displayName = portNameBuffer;
        } else {
            // Fallback: try extracting from display name if available elsewhere
            // (not implemented here — kept minimal)
        }

        printf("Detected: %S\n", currentInterface);
        ports.push_back(std::move(entry));

        // Move to next string
        currentInterface += wcslen(currentInterface) + 1;
    }

    return ports;
}

// Public API: find serial ports matching optional VID/PID filters
std::vector<SerialPortInfo> MavLinkConnection::findSerialPorts(int targetVid, int targetPid) {
    std::vector<SerialPortInfo> filteredList;

    auto allPorts = gatherSerialInterfaces();

    for (auto& port : allPorts) {
        bool match = (targetVid == 0 && targetPid == 0) ||
                     (port.vid == targetVid && port.pid == targetPid);
        if (match) {
            filteredList.push_back(std::move(port));
        }
    }

    return filteredList;
}

