// Retrieve a symbol for a given Unicode code point
FontModule::Symbol LargeFont::getChar(uint32_t character) const
{
    // Handle ASCII printable characters (0x20 to 0x7F)
    if (character >= 0x20 && character <= 0x7F && 
        (character - 0x20) < static_cast<int>(ascii.size()))
    {
        return ascii[character - 0x20];
    }

    // Handle extended Unicode characters (0x80 and above)
    if (character >= 0x80 && character <= 0x10FFFF)
    {
        for (const auto& entry : unicode)
        {
            if (entry.hex == character)
            {
                return entry.symbol;
            }
        }
    }

    // Return empty symbol if no match found
    return {};
}

