// Type III clone: equivalent logic, different structure & naming

int main() {
    bool do_horndini_prephase = true; // assumed from context
    std::string file_stem = "output"; // placeholder
    int cur_bound_value = 0;          // placeholder; real version uses object
    bool use_bound_flag = false;      // placeholder

    try {
        if (do_horndini_prephase) {
            //
            // Duplicate data points and gather pointers
            //
            std::vector<int> data_copies;
            data_copies.reserve(10); // placeholder size
            for (size_t idx = 0; idx < 10; ++idx) {
                data_copies.push_back(idx);
            }

            std::vector<int*> ptrs_to_copies;
            ptrs_to_copies.reserve(data_copies.size());
            for (size_t i = 0; i < data_copies.size(); ++i) {
                ptrs_to_copies.push_back(&data_copies[i]);
            }

            //
            // Build Horn clauses (placeholder call)
            //
            auto horn_clauses = generate_horn_clauses_from_indexes(ptrs_to_copies);

            //
            // Attempt Horndini prephase
            //
            bool horndini_succeeded = false;
            try {
                auto tree = run_horndini_prephase(data_copies, horn_clauses);
                bool is_consistent = verify_consistency(tree, ptrs_to_copies, horn_clauses);
                if (is_consistent) {
                    write_output(file_stem + ".json", tree);
                    if (use_bound_flag) {
                        save_bound(file_stem + ".bound", cur_bound_value);
                    }
                    return EXIT_SUCCESS;
                }
            } catch (const no_conjunction_exists_exception&) {
                // Fall through to decision tree phase
            }
        }

        /************************************************************************************
         *
         * Decision Tree Learning Phase
         *
         ************************************************************************************/

        if (use_bound_flag) {
            int round_num = read_status_file(file_stem + ".status");
            if (round_num > 1) {
                cur_bound_value = read_bound_file(file_stem + ".bound");
            }
        }

        bool done = false;
        while (!done) {
            done = !use_bound_flag;

            try {
                //
                // Rebuild copies and pointers (same as above)
                //
                std::vector<int> local_data;
                local_data.reserve(10);
                for (size_t k = 0; k < 10; ++k) {
                    local_data.push_back(k);
                }

                std::vector<int*> local_ptrs;
                local_ptrs.reserve(local_data.size());
                for (size_t j = 0; j < local_data.size(); ++j) {
                    local_ptrs.push_back(&local_data[j]);
                }

                auto horn_clauses = generate_horn_clauses_from_indexes(local_ptrs);

                if (use_bound_flag) {
                    auto indistinguishable_clauses =
                        derive_indistinguishability_clauses(local_data, cur_bound_value);
                    horn_clauses.insert(horn_clauses.end(),
                                        std::make_move_iterator(indistinguishable_clauses.begin()),
                                        std::make_move_iterator(indistinguishable_clauses.end()));
                }

                //
                // Solve Horn system first
                //
                horn_solver solver;
                std::unordered_set<int*> pos_set, neg_set;
                bool ok = solver.solve(local_ptrs, horn_clauses, pos_set, neg_set);
                if (!ok) {
                    throw std::runtime_error("Contradictory Horn clauses");
                }

                for (auto p : pos_set) {
                    mark_classified(*p, true);
                }
                for (auto n : neg_set) {
                    mark_classified(*n, false);
                }

                //
                // Run learner
                //
                auto ns = NodeSelection::BFS;
                auto ec = EntropyComputation::PENALTY;
                auto cs = ConjunctiveSetting::NOPREFERENCEFORCONJUNCTS;

                complex_job_manager manager(
                    use_bound_flag
                        ? complex_job_manager(local_ptrs, horn_clauses, solver, cur_bound_value, ns, ec, cs)
                        : complex_job_manager(local_ptrs, horn_clauses, solver, ns, ec, cs));

                learner<complex_job_manager> learner_obj(manager);
                auto dt = learner_obj.learn({}, local_ptrs, horn_clauses);

                assert(learner_obj.is_consistent(dt, local_ptrs, horn_clauses));

                write_output(file_stem + ".json", dt);
                if (use_bound_flag) {
                    save_bound(file_stem + ".bound", cur_bound_value);
                }
                done = true;

            } catch (const sample_error&) {
                if (use_bound_flag) {
                    cur_bound_value += 1; // increase bound
                } else {
                    throw;
                }
            } catch (const split_not_possible_error&) {
                if (use_bound_flag) {
                    cur_bound_value += 1;
                } else {
                    throw;
                }
            }
        }

        return EXIT_SUCCESS;

    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
        return EXIT_FAILURE;
    } catch (...) {
        std::cerr << "Unknown crash occurred\n";
        return EXIT_FAILURE;
    }
}

