    typedef HRESULT(__stdcall *RoInitializeFunc)(int);
    typedef HRESULT(__stdcall *RoUninitializeFunc)();
    typedef HRESULT(__stdcall *RoActivateInstanceFunc)(HSTRING, IInspectable**);
    typedef HRESULT(__stdcall *RoGetActivationFactoryFunc)(HSTRING, REFIID, void**);
    typedef HRESULT(__stdcall *WindowsCreateStringFunc)(LPCWSTR, UINT32, HSTRING*);
    typedef HRESULT(__stdcall *WindowsDeleteStringFunc)(HSTRING);
}

namespace Slic3r {

    // Runtime library handles and function pointers
    static HMODULE g_runtimeLib = nullptr;
    static RoInitializeFunc g_roInit = nullptr;
    static RoUninitializeFunc g_roUninit = nullptr;
    static RoActivateInstanceFunc g_roActivate = nullptr;
    static RoGetActivationFactoryFunc g_roGetFactory = nullptr;
    static WindowsCreateStringFunc g_winStrCreate = nullptr;
    static WindowsDeleteStringFunc g_winStrDelete = nullptr;

    bool load_winrt_runtime() {
        if (!g_runtimeLib) {
            g_runtimeLib = LoadLibraryW(L"ComBase.dll");
        }
        if (g_runtimeLib) {
            g_roInit = (RoInitializeFunc)GetProcAddress(g_runtimeLib, "RoInitialize");
            g_roUninit = (RoUninitializeFunc)GetProcAddress(g_runtimeLib, "RoUninitialize");
            g_roActivate = (RoActivateInstanceFunc)GetProcAddress(g_runtimeLib, "RoActivateInstance");
            g_roGetFactory = (RoGetActivationFactoryFunc)GetProcAddress(g_runtimeLib, "RoGetActivationFactory");
            g_winStrCreate = (WindowsCreateStringFunc)GetProcAddress(g_runtimeLib, "WindowsCreateString");
            g_winStrDelete = (WindowsDeleteStringFunc)GetProcAddress(g_runtimeLib, "WindowsDeleteString");
        }

        return g_roInit && g_roUninit && g_roActivate && g_winStrCreate && g_winStrDelete;
    }

    static HRESULT create_winrt_instance(const std::wstring& className, IInspectable** instance) {
        HSTRING hClassName;
        HRESULT hr = g_winStrCreate(className.c_str(), static_cast<UINT32>(className.size()), &hClassName);
        if (FAILED(hr)) return hr;

        hr = g_roActivate(hClassName, instance);
        g_winStrDelete(hClassName);
        return hr;
    }

    template<typename T>
    static HRESULT create_winrt_instance(const std::wstring& className, T** instance) {
        IInspectable* raw = nullptr;
        HRESULT hr = create_winrt_instance(className, &raw);
        if (FAILED(hr)) return hr;

        hr = raw->QueryInterface(__uuidof(T), reinterpret_cast<void**>(instance));
        raw->Release();
        return hr;
    }

    static HRESULT get_activation_factory(const std::wstring& className, REFIID iid, void** factory) {
        HSTRING hClassName;
        HRESULT hr = g_winStrCreate(className.c_str(), static_cast<UINT32>(className.size()), &hClassName);
        if (FAILED(hr)) return hr;

        hr = g_roGetFactory(hClassName, iid, factory);
        g_winStrDelete(hClassName);
        return hr;
    }

    template<typename T>
    static HRESULT get_activation_factory(const std::wstring& className, T** factory) {
        return get_activation_factory(className, __uuidof(T), reinterpret_cast<void**>(factory));
    }

    static HRESULT open_file_stream(
        const std::wstring& path,
        ABI::Windows::Storage::FileAccessMode mode,
        ABI::Windows::Storage::Streams::IRandomAccessStream** stream,
        const std::function<void()>& cancelCheck,
        int pollIntervalMs = 100
    ) {
        Microsoft::WRL::ComPtr<ABI::Windows::Storage::IStorageFileStatics> fileFactory;
        HRESULT hr = get_activation_factory(L"Windows.Storage.StorageFile", fileFactory.GetAddressOf());
        if (FAILED(hr)) return hr;

        HSTRING hPath;
        hr = g_winStrCreate(path.c_str(), static_cast<UINT32>(path.size()), &hPath);
        if (FAILED(hr)) return hr;

        Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Storage::StorageFile*>> opOpen;
        hr = fileFactory->GetFileFromPathAsync(hPath, opOpen.GetAddressOf());
        g_winStrDelete(hPath);
        if (FAILED(hr)) return hr;

        AsyncStatus status = await_async_operation(opOpen, cancelCheck, pollIntervalMs);
        Microsoft::WRL::ComPtr<ABI::Windows::Storage::IStorageFile> file;
        if (status == AsyncStatus::Completed) {
            hr = opOpen->GetResults(file.GetAddressOf());
        } else {
            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncInfo> info;
            hr = opOpen.As(&info);
            if (FAILED(hr)) return hr;
            HRESULT errCode;
            hr = info->get_ErrorCode(&errCode);
            return FAILED(hr) ? hr : errCode;
        }

        Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Storage::Streams::IRandomAccessStream*>> opStream;
        hr = file->OpenAsync(mode, opStream.GetAddressOf());
        if (FAILED(hr)) return hr;

        status = await_async_operation(opStream, cancelCheck, pollIntervalMs);
        if (status == AsyncStatus::Completed) {
            hr = opStream->GetResults(stream);
        } else {
            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncInfo> info;
            hr = opStream.As(&info);
            if (FAILED(hr)) return hr;
            HRESULT errCode;
            hr = info->get_ErrorCode(&errCode);
            if (SUCCEEDED(hr)) hr = errCode;
        }
        return hr;
    }

    static AsyncStatus await_async_operation(
        const Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncInfo>& asyncOp,
        const std::function<void()>& cancelCheck,
        int pollIntervalMs = 100
    ) {
        AsyncStatus status;
        while (true) {
            asyncOp->get_Status(&status);
            if (status != AsyncStatus::Started) break;
            cancelCheck();
            Sleep(pollIntervalMs);
        }
        return status;
    }

    bool is_windows_10() {
        HKEY key;
        LONG res = RegOpenKeyExW(HKEY_LOCAL_MACHINE, L"SOFTWARE\\Microsoft\\Windows NT\\CurrentVersion", 0, KEY_READ, &key);
        if (res == ERROR_SUCCESS) {
            WCHAR buffer[512];
            DWORD size = sizeof(buffer);
            res = RegQueryValueExW(key, L"ProductName", nullptr, nullptr, reinterpret_cast<LPBYTE>(buffer), &size);
            if (res == ERROR_SUCCESS) {
                return wcsncmp(buffer, L"Windows 10", 10) == 0;
            }
            RegCloseKey(key);
        }
        return false;
    }

    class CancellationException : public std::runtime_error {
    public:
        CancellationException() : std::runtime_error("Model repair has been canceled") {}
    };

    void fix_model_by_win10_sdk(
        const std::string& srcPath,
        const std::string& dstPath,
        const std::function<void(const char*, unsigned)>& progressCallback,
        const std::function<void()>& cancelCheck
    ) {
        if (!is_windows_10())
            throw Slic3r::RuntimeError("fix_model_by_win10_sdk called on non-Windows 10 system");

        if (!load_winrt_runtime())
            throw Slic3r::RuntimeError("Failed to initialize WinRT runtime.");

        HRESULT hr = g_roInit(RO_INIT_MULTITHREADED);

        try {
            progressCallback(L("Exporting source model"), 20);

            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IRandomAccessStream> stream;
            hr = open_file_stream(boost::nowide::widen(srcPath),
                                  ABI::Windows::Storage::FileAccessMode::FileAccessMode_Read,
                                  &stream, cancelCheck);
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to open source file.");

            Microsoft::WRL::ComPtr<ABI::Windows::Graphics::Printing3D::IPrinting3D3MFPackage> pkg;
            hr = create_winrt_instance(L"Windows.Graphics.Printing3D.Printing3D3MFPackage", &pkg);
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to activate 3MF package.");

            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Graphics::Printing3D::Printing3DModel*>> modelOp;
            hr = pkg->LoadModelFromPackageAsync(stream.Get(), modelOp.GetAddressOf());
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to start model loading.");

            AsyncStatus status = await_async_operation(modelOp.As<ABI::Windows::Foundation::IAsyncInfo>(), cancelCheck);
            Microsoft::WRL::ComPtr<ABI::Windows::Graphics::Printing3D::IPrinting3DModel> model;
            if (status == AsyncStatus::Completed) {
                hr = modelOp->GetResults(model.GetAddressOf());
            } else {
                throw Slic3r::RuntimeError("Failed to load input model.");
            }

            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::Collections::IVector<ABI::Windows::Graphics::Printing3D::Printing3DMesh*>> meshes;
            hr = model->get_Meshes(meshes.GetAddressOf());
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to retrieve meshes.");

            unsigned meshCount = 0;
            hr = meshes->get_Size(&meshCount);
            progressCallback(L("Repairing model by Windows repair algorithm"), 40);

            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncAction> repairOp;
            hr = model->RepairAsync(repairOp.GetAddressOf());
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to start repair operation.");

            status = await_async_operation(repairOp.As<ABI::Windows::Foundation::IAsyncInfo>(), cancelCheck);
            if (status != AsyncStatus::Completed)
                throw Slic3r::RuntimeError("Mesh repair failed.");

            hr = repairOp->GetResults();

            progressCallback(L("Loading repaired model"), 60);

            meshes.Reset();
            hr = model->get_Meshes(meshes.GetAddressOf());
            hr = meshes->get_Size(&meshCount);

            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncAction> saveToPkgOp;
            hr = pkg->SaveModelToPackageAsync(model.Get(), saveToPkgOp.GetAddressOf());
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to save model into package.");

            status = await_async_operation(saveToPkgOp.As<ABI::Windows::Foundation::IAsyncInfo>(), cancelCheck);
            if (status != AsyncStatus::Completed)
                throw Slic3r::RuntimeError("Saving to 3MF container failed.");

            hr = saveToPkgOp->GetResults();

            Microsoft::WRL::ComPtr<ABI::Windows::Foundation::IAsyncOperation<ABI::Windows::Storage::Streams::IRandomAccessStream*>> genStreamOp;
            hr = pkg->SaveAsync(genStreamOp.GetAddressOf());
            if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to generate output stream.");

            status = await_async_operation(genStreamOp.As<ABI::Windows::Foundation::IAsyncInfo>(), cancelCheck);
            if (status != AsyncStatus::Completed)
                throw Slic3r::RuntimeError("Saving final stream failed.");

            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IRandomAccessStream> outStream;
            hr = genStreamOp->GetResults(outStream.GetAddressOf());

            outStream->Seek(0);

            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IInputStream> inStream;
            hr = outStream.As(&inStream);

            Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IBufferFactory> bufFactory;
            hr = get_activation_factory(L"Windows.Storage.Streams.Buffer", bufFactory.GetAddressOf());

            FILE* fout = boost::nowide::fopen(dstPath.c_str(), "wb");
            if (!fout) throw Slic3r::RuntimeError("Failed to open destination file.");

            try {
                Microsoft::WRL::ComPtr<ABI::Windows::Storage::Streams::IBuffer> buffer;
                byte* bufferData = nullptr;
                hr = bufFactory->Create(65536 * 2048, buffer.GetAddressOf());
                if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to allocate buffer.");

                {
                    Microsoft::WRL::ComPtr<Windows::Storage::Streams::IBufferByteAccess> byteAccess;
                    buffer.As(&byteAccess);
                    hr = byteAccess->Buffer(&bufferData);
                    if (FAILED(hr)) throw Slic3r::RuntimeError("Failed to access buffer data.");
                }

                uint32_t readLen = 0;
                hr = buffer->get_Length(&readLen);

                Microsoft::WRL::ComPtr<
                    ABI::Windows::Foundation::IAsyncOperationWithProgress<ABI::Windows::Storage::Streams::IBuffer*, UINT32>> readOp;

                while (true) {
                    hr = inStream->ReadAsync(buffer.Get(), 65536 * 2048,
                                             ABI::Windows::Storage::Streams::InputStreamOptions_ReadAhead,
                                             readOp.GetAddressOf());
                    if (FAILED(hr)) throw Slic3r::RuntimeError("Read operation failed.");

                    status = await_async_operation(readOp.As<ABI::Windows::Foundation::IAsyncInfo>(), cancelCheck);
                    if (status != AsyncStatus::Completed)
                        throw Slic3r::RuntimeError("Read operation did not complete.");

                    hr = buffer->get_Length(&readLen);
                    if (readLen == 0) break;

                    fwrite(bufferData, 1, readLen, fout);
                }
            } catch (...) {
                fclose(fout);
                throw;
            }
            fclose(fout);
        } catch (...) {
            g_roUninit();
            throw;
        }

        g_roUninit();
    }

    bool fix_model_by_win10_sdk_gui(
        ModelObject& object,
        int volumeIndex,
        wxProgressDialog& dialog,
        const wxString& header,
        std::string& result
    ) {
        std::mutex mtx;
        std::condition_variable cv;
        struct UpdateState {
            std::string msg;
            int percent = 0;
            bool updated = false;
        } state;

        std::atomic<bool> cancelled(false);
        std::atomic<bool> completed(false);
        std::vector<ModelVolume*> vols;
        if (volumeIndex == -1) {
            vols = object.volumes;
        } else {
            vols.emplace_back(object.volumes[volumeIndex]);
        }

        bool success = false;
        size_t volIdx = 0;

        auto updateProgress = [&](const char* msg, unsigned pct) {
            std::unique_lock<std::mutex> lock(mtx);
            state.msg = msg;
            state.percent = static_cast<int>(
                std::floor((static_cast<float>(pct) + static_cast<float>(volIdx) * 100.f) / static_cast<float>(vols.size()))
            );
            state.updated = true;
            cv.notify_all();
        };

        auto worker = boost::thread([&]() {
            try {
                std::vector<TriangleMesh> repairedMeshes;
                repairedMeshes.reserve(vols.size());

                for (; volIdx < vols.size(); ++volIdx) {
                    updateProgress(L("Exporting source model"), 0);

                    boost::filesystem::path tempSrc = boost::filesystem::temp_directory_path() /
                                                      boost::filesystem::unique_path();
                    tempSrc += ".3mf";

                    Model dummyModel;
                    ModelObject* mo = dummyModel.add_object();
                    mo->add_volume(*vols[volIdx]);
                    mo->volumes.back()->set_transformation(Geometry::Transformation());
                    mo->add_instance();

                    if (!Slic3r::store_3mf(tempSrc.string().c_str(), &dummyModel, nullptr, false, nullptr, false)) {
                        boost::filesystem::remove(tempSrc);
                        throw Slic3r::RuntimeError("Temporary 3MF export failed.");
                    }

                    dummyModel.clear_objects();
                    dummyModel.clear_materials();

                    boost::filesystem::path tempDst = boost::filesystem::temp_directory_path() /
                                                      boost::filesystem::unique_path();
                    tempDst += ".3mf";

                    fix_model_by_win10_sdk(tempSrc.string(), tempDst.string(), updateProgress,
                        [&cancelled]() {
                            if (cancelled) throw CancellationException();
                        });

                    boost::filesystem::remove(tempSrc);

                    updateProgress(L("Loading repaired model"), 80);

                    DynamicPrintConfig cfg;
                    ConfigSubstitutionContext subs{ForwardCompatibilitySubstitutionRule::EnableSilent};
                    boost::optional<Semver> genVer;
                    bool loaded = Slic3r::load_3mf(tempDst.string().c_str(), cfg, subs, &dummyModel, false, genVer);
                    boost::filesystem::remove(tempDst);

                    if (!loaded || dummyModel.objects.empty() ||
                        dummyModel.objects.size() > 1 ||
                        dummyModel.objects.front()->volumes.empty() ||
                        dummyModel.objects.front()->volumes.size() > 1) {
                        throw Slic3r::RuntimeError("Repaired 3MF file invalid.");
                    }

                    repairedMeshes.emplace_back(std::move(dummyModel.objects.front()->volumes.front()->mesh()));
                }

                for (size_t i = 0; i < vols.size(); ++i) {
                    vols[i]->set_mesh(std::move(repairedMeshes[i]));
                    vols[i]->calculate_convex_hull();
                    vols[i]->set_new_unique_id();
                }

                object.invalidate_bounding_box();
                --volIdx;
                updateProgress(L("Model repair finished"), 100);
                success = true;
                completed = true;

            } catch (CancellationException&) {
                cancelled = true;
                completed = true;
                updateProgress(L("Model repair canceled"), 100);
            } catch (const std::exception& ex) {
                success = false;
                completed = true;
                updateProgress(ex.what(), 100);
            }
        });

        while (!completed) {
            std::unique_lock<std::mutex> lock(mtx);
            cv.wait_for(lock, std::chrono::milliseconds(250), [&state] { return state.updated; });

            if (!dialog.Update(state.percent - 1, header + _(state.msg))) {
                cancelled = true;
            } else {
                dialog.Fit();
            }
            state.updated = false;
        }

        if (cancelled) {
            // Do nothing
        } else if (success) {
            result.clear();
        } else {
            result = state.msg;
        }

        worker.join();
        return !cancelled;
    }

} // namespace Slic3r

