#include "vglib.h"

/**
 * VGLib Native Method Implementations - Modified Version
 */
namespace VGLibNative {
    Value native_donut(std::vector<Value>& args) {
        if (args.size() < 2) throw std::runtime_error("donut() requires A and B arguments");

        // Clear screen and hide cursor
        std::printf("\x1b[H\x1b[?25l\x1b[J");

        float angleA = static_cast<float>(args[0].asFloat());
        float angleB = static_cast<float>(args[1].asFloat());

        // Initialize buffers
        float depthBuffer[1760];
        char displayBuffer[1760];

        // Fill background with spaces
        for (int i = 0; i < 1760; ++i) {
            displayBuffer[i] = ' ';
            depthBuffer[i] = 0.0f;
        }

        // Precompute trigonometric values
        float sinA = std::sin(angleA), cosA = std::cos(angleA);
        float sinB = std::sin(angleB), cosB = std::cos(angleB);

        // Torus rendering loop
        for (float torusAngle = 0; torusAngle < 6.28f; torusAngle += 0.07f) {
            float cosTorus = std::cos(torusAngle);
            float sinTorus = std::sin(torusAngle);

            for (float tubeAngle = 0; tubeAngle < 6.28f; tubeAngle += 0.02f) {
                float cosTube = std::cos(tubeAngle);
                float sinTube = std::sin(tubeAngle);

                float radiusOffset = cosTorus + 2.0f;
                float inverseDepth = 1.0f / (sinTube * radiusOffset * sinA + cosTorus * cosA + 5.0f);
                float transformedZ = sinTube * radiusOffset * cosA - cosTorus * sinA;

                int pixelX = static_cast<int>(40 + 30 * inverseDepth * (cosTube * radiusOffset * cosB - transformedZ * sinB));
                int pixelY = static_cast<int>(12 + 15 * inverseDepth * (cosTube * radiusOffset * sinB + transformedZ * cosB));
                int bufferIndex = pixelX + 80 * pixelY;

                // Calculate lighting/brightness index
                int brightnessIndex = static_cast<int>(8 * ((cosTorus * sinA - sinTube * cosTorus * cosA) * cosB 
                                                          - sinTube * cosTorus * sinA 
                                                          - cosTorus * cosA 
                                                          - cosTube * cosTorus * sinB));

                // Check bounds and depth buffer
                if (pixelY > 0 && pixelY < 22 && pixelX > 0 && pixelX < 80 && 
                    inverseDepth > depthBuffer[bufferIndex]) {
                    depthBuffer[bufferIndex] = inverseDepth;

                    // Map brightness to ASCII characters
                    int charIndex = (brightnessIndex > 0) ? (brightnessIndex < 12 ? brightnessIndex : 11) : 0;
                    displayBuffer[bufferIndex] = ".,-~:;=!*#$@"[charIndex];
                }
            }
        }

        // Output the rendered image
        char finalOutput[2000];
        int outputPos = 0;
        for (int row = 0; row < 22; ++row) {
            for (int col = 0; col < 80; ++col) {
                finalOutput[outputPos++] = displayBuffer[col + row * 80];
            }
            finalOutput[outputPos++] = '\n';
        }

        std::fwrite(finalOutput, 1, outputPos, stdout);
        std::fflush(stdout);

        return Value();
    }
}

void setupVGLib(SymbolContainer& env, StringPool& pool) {
    const std::string& path = "vglib";

    if (env.find(path) == env.end()) {
        env[path] = SymbolTable();
    }
    auto& vglib = env[path];

    // Register native methods
    vglib[pool.intern("donut")] = Value(VGLibNative::native_donut);

    // Register version property
    vglib[pool.intern("version")] = Value("v0.0.1-alpha").setReadOnly();
}

#include <fuerte/connection.h>
#include <yaclib/algo/wait_group.hpp>
#include "basics/logger/logger.h"

namespace sdb::fuerte {

Connection::~Connection() {
  SDB_DEBUG("xxxxx", Logger::FUERTE, "Destroying Connection");
}

// Send a request and synchronously wait for its completion
std::unique_ptr<Response> Connection::sendRequest(
    std::unique_ptr<Request> request) {
  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): before send");

  // Use a one-shot event to signal completion
  yaclib::OneShotEvent done_event;
  std::unique_ptr<Response> result;
  Error status = Error::NoError;

  // Callback invoked upon request completion
  auto handler = [&](Error err, std::unique_ptr<Request>, 
                     std::unique_ptr<Response> resp) {
    result = std::move(resp);
    status = err;
    done_event.Set();
  };

  // Initiate the asynchronous send operation
  sendRequest(std::move(request), handler);

  // Block until the operation completes
  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): before wait");
  done_event.Wait();

  SDB_TRACE("xxxxx", Logger::FUERTE, "sendRequest (sync): done");

  if (status != Error::NoError) {
    throw status;
  }

  return result;
}

std::string Connection::endpoint() const {
  std::string addr;
  addr.reserve(64);  // Increase reserved size for safety

  // Protocol prefix: e.g., "http"
  addr.append(fuerte::ToString(_config.protocol_type));
  addr.push_back('+');

  // Transport type: e.g., "tcp", "ssl", or "unix"
  addr.append(fuerte::ToString(_config.socket_type));
  addr.append("://");

  // Host part: domain or IP address
  addr.append(_config.host);

  // Append port only if not using Unix socket
  if (_config.socket_type != SocketType::Unix) {
    addr.push_back(':');
    addr.append(_config.port);
  }

  return addr;
}

}  // namespace sdb::fuerte

#include "stringpiece.h"
#include <ostream>
#include "util.h"

namespace lbug {
namespace regex {

// Initialize static member npos (as per definition in stringpiece.h)
const StringPiece::size_type StringPiece::npos;

// Copy up to n characters starting at pos into buf; returns actual number copied
StringPiece::size_type StringPiece::copy(char* buf, size_type n, size_type pos) const {
    size_type available = size_ - pos;
    size_type to_copy = (n < available) ? n : available;
    if (to_copy > 0) {
        std::memcpy(buf, data_ + pos, to_copy);
    }
    return to_copy;
}

// Return a substring starting at pos with length n (clamped appropriately)
StringPiece StringPiece::substr(size_type pos, size_type n) const {
    if (pos > size_) {
        pos = size_;
    }
    if (n > size_ - pos) {
        n = size_ - pos;
    }
    return StringPiece(data_ + pos, n);
}

// Find first occurrence of s starting at pos; return npos if not found
StringPiece::size_type StringPiece::find(const StringPiece& s, size_type pos) const {
    if (pos > size_) {
        return npos;
    }
    const_pointer begin = data_ + pos;
    const_pointer end = data_ + size_;
    const_pointer match = std::search(begin, end, s.data_, s.data_ + s.size_);
    size_type offset = match - data_;
    return (offset + s.size_ <= size_) ? offset : npos;
}

// Find first occurrence of character c starting at pos; return npos if not found
StringPiece::size_type StringPiece::find(char c, size_type pos) const {
    if (size_ == 0 || pos >= size_) {
        return npos;
    }
    const_pointer begin = data_ + pos;
    const_pointer end = data_ + size_;
    const_pointer found = std::find(begin, end, c);
    return (found != end) ? (found - data_) : npos;
}

// Find last occurrence of s before or at pos; return npos if not found
StringPiece::size_type StringPiece::rfind(const StringPiece& s, size_type pos) const {
    if (size_ < s.size_) {
        return npos;
    }
    if (s.size_ == 0) {
        return (size_ < pos) ? size_ : pos;
    }
    size_type max_start = (size_ - s.size_ < pos) ? size_ - s.size_ : pos;
    const_pointer start = data_;
    const_pointer search_end = data_ + max_start + s.size_;
    const_pointer last_match = std::find_end(start, search_end, s.data_, s.data_ + s.size_);
    return (last_match != search_end) ? (last_match - data_) : npos;
}

// Find last occurrence of character c before or at pos; return npos if not found
StringPiece::size_type StringPiece::rfind(char c, size_type pos) const {
    if (size_ == 0) {
        return npos;
    }
    size_type limit = (pos + 1 < size_) ? pos + 1 : size_;
    for (size_type i = limit; i > 0; ) {
        --i;
        if (data_[i] == c) {
            return i;
        }
    }
    return npos;
}

// Output operator: writes the piece's contents to the stream
std::ostream& operator<<(std::ostream& o, const StringPiece& p) {
    if (p.size() > 0) {
        o.write(p.data(), p.size());
    }
    return o;
}

} // namespace regex
} // namespace lbug

