static const ColorRGBA DEFAULT_PLANE_COLOR = {0.9f, 0.9f, 0.9f, 0.5f};
static const ColorRGBA DEFAULT_HOVER_PLANE_COLOR = {0.9f, 0.9f, 0.9f, 0.75f};

GLGizmoFlatten::GLGizmoFlatten(GLCanvas3D &parent, const std::string &icon_filename, unsigned int sprite_id)
    : GLGizmoBase(parent, icon_filename, sprite_id) {}

bool GLGizmoFlatten::on_mouse(const wxMouseEvent &mouse_event) {
    if (mouse_event.LeftDown()) {
        if (m_hover_id != -1) {
            Selection &selection = m_parent.get_selection();
            if (selection.is_single_full_instance()) {
                selection.flattening_rotate(m_planes[m_hover_id].normal);
                m_parent.do_rotate(L("Gizmo-Place on Face"));
                wxGetApp().obj_manipul()->set_dirty();
            }
            return true;
        }
    } else if (mouse_event.LeftUp()) {
        return m_hover_id != -1;
    }
    return false;
}

void GLGizmoFlatten::data_changed(bool is_serializing) {
    const Selection &selection = m_parent.get_selection();
    const ModelObject *model_object = nullptr;
    int instance_id = -1;

    if (selection.is_single_full_instance() || selection.is_from_single_object()) {
        model_object = selection.get_model()->objects[selection.get_object_idx()];
        instance_id = selection.get_instance_idx();
    }

    set_flattening_data(model_object, instance_id);
}

bool GLGizmoFlatten::on_init() {
    m_shortcut_key = WXK_CONTROL_F;
    return true;
}

void GLGizmoFlatten::on_set_state() {}

CommonGizmosDataID GLGizmoFlatten::on_get_requirements() const {
    return CommonGizmosDataID::SelectionInfo;
}

std::string GLGizmoFlatten::on_get_name() const {
    return _u8L("Place on face");
}

bool GLGizmoFlatten::on_is_activable() const {
    return m_parent.get_selection().is_single_full_instance();
}

void GLGizmoFlatten::on_render() {
    const Selection &selection = m_parent.get_selection();
    GLShaderProgram *shader = wxGetApp().get_shader("flat");
    if (!shader) return;

    shader->start_using();
    glsafe(::glClear(GL_DEPTH_BUFFER_BIT));
    glsafe(::glEnable(GL_DEPTH_TEST));
    glsafe(::glEnable(GL_BLEND));

    if (selection.is_single_full_instance()) {
        const Transform3d &inst_matrix = selection.get_first_volume()->get_instance_transformation().get_matrix();
        const Camera &camera = wxGetApp().plater()->get_camera();

        const Transform3d model_matrix =
            Geometry::translation_transform(selection.get_first_volume()->get_sla_shift_z() * Vec3d::UnitZ()) * inst_matrix;
        const Transform3d view_model_matrix = camera.get_view_matrix() * model_matrix;

        shader->set_uniform("view_model_matrix", view_model_matrix);
        shader->set_uniform("projection_matrix", camera.get_projection_matrix());

        if (this->is_plane_update_necessary())
            update_planes();

        for (int i = 0; i < (int)m_planes.size(); ++i) {
            m_planes[i].vbo.model.set_color(i == m_hover_id ? DEFAULT_HOVER_PLANE_COLOR : DEFAULT_PLANE_COLOR);
            m_planes[i].vbo.model.render();
        }
    }

    glsafe(::glEnable(GL_CULL_FACE));
    glsafe(::glDisable(GL_BLEND));
    shader->stop_using();
}

void GLGizmoFlatten::on_register_raycasters_for_picking() {
    m_parent.set_raycaster_gizmos_on_top(true);
    assert(m_planes_casters.empty());

    if (!m_planes.empty()) {
        const Selection &selection = m_parent.get_selection();
        const Transform3d matrix =
            Geometry::translation_transform(selection.get_first_volume()->get_sla_shift_z() * Vec3d::UnitZ()) *
            selection.get_first_volume()->get_instance_transformation().get_matrix();

        for (int i = 0; i < (int)m_planes.size(); ++i) {
            m_planes_casters.emplace_back(
                m_parent.add_raycaster_for_picking(SceneRaycaster::EType::Gizmo, i,
                                                   *m_planes[i].vbo.mesh_raycaster, matrix));
        }
    }
}

void GLGizmoFlatten::on_unregister_raycasters_for_picking() {
    m_parent.remove_raycasters_for_picking(SceneRaycaster::EType::Gizmo);
    m_parent.set_raycaster_gizmos_on_top(false);
    m_planes_casters.clear();
}

void GLGizmoFlatten::set_flattening_data(const ModelObject *model_object, int instance_id) {
    if (model_object != m_old_model_object || instance_id != m_old_instance_id) {
        m_planes.clear();
        on_unregister_raycasters_for_picking();
    }
}

void GLGizmoFlatten::update_planes() {
    const ModelObject *mo = m_c->selection_info()->model_object();
    TriangleMesh ch;

    for (const ModelVolume *vol : mo->volumes) {
        if (vol->type() != ModelVolumeType::MODEL_PART) continue;
        TriangleMesh vol_ch = vol->get_convex_hull();
        vol_ch.transform(vol->get_matrix());
        ch.merge(vol_ch);
    }

    ch = ch.convex_hull_3d();
    m_planes.clear();
    on_unregister_raycasters_for_picking();

    const Transform3d inst_matrix = mo->instances.front()->get_matrix_no_offset();

    const float minimal_area = 5.f;
    const float minimal_side = 1.f;

    const int num_of_facets = ch.facets_count();
    const std::vector<Vec3f> face_normals = its_face_normals(ch.its);
    const std::vector<Vec3i> face_neighbors = its_face_neighbors(ch.its);

    std::vector<int> facet_queue(num_of_facets, 0);
    std::vector<bool> facet_visited(num_of_facets, false);
    int facet_queue_cnt = 0;
    const stl_normal *normal_ptr = nullptr;
    int facet_idx = 0;

    while (true) {
        for (; facet_idx < num_of_facets; ++facet_idx)
            if (!facet_visited[facet_idx]) {
                facet_queue[facet_queue_cnt++] = facet_idx;
                facet_visited[facet_idx] = true;
                normal_ptr = &face_normals[facet_idx];
                m_planes.emplace_back();
                break;
            }

        if (facet_idx == num_of_facets) break;

        while (facet_queue_cnt > 0) {
            int current_facet = facet_queue[--facet_queue_cnt];
            const stl_normal &this_normal = face_normals[current_facet];

            if (std::abs(this_normal(0) - (*normal_ptr)(0)) < 0.001 &&
                std::abs(this_normal(1) - (*normal_ptr)(1)) < 0.001 &&
                std::abs(this_normal(2) - (*normal_ptr)(2)) < 0.001) {
                const Vec3i face = ch.its.indices[current_facet];
                for (int j = 0; j < 3; ++j)
                    m_planes.back().vertices.emplace_back(ch.its.vertices[face[j]].cast<double>());

                facet_visited[current_facet] = true;
                for (int j = 0; j < 3; ++j) {
                    int neighbor_idx = face_neighbors[current_facet][j];
                    if (neighbor_idx >= 0 && !facet_visited[neighbor_idx])
                        facet_queue[facet_queue_cnt++] = neighbor_idx;
                }
            }
        }

        m_planes.back().normal = normal_ptr->cast<double>();
        Pointf3s &verts = m_planes.back().vertices;

        verts = transform(verts, inst_matrix);

        if (verts.size() == 3 &&
            ((verts[0] - verts[1]).norm() < minimal_side ||
             (verts[0] - verts[2]).norm() < minimal_side ||
             (verts[1] - verts[2]).norm() < minimal_side))
            m_planes.pop_back();
    }

    const Matrix3d normal_matrix = inst_matrix.matrix().block(0, 0, 3, 3).inverse().transpose();

    for (unsigned int polygon_id = 0; polygon_id < m_planes.size(); ++polygon_id) {
        Pointf3s &polygon = m_planes[polygon_id].vertices;
        const Vec3d &normal = m_planes[polygon_id].normal;

        const Vec3d normal_transformed = normal_matrix * normal;

        Eigen::Quaterniond q;
        Transform3d m = Transform3d::Identity();
        m.matrix().block(0, 0, 3, 3) = q.setFromTwoVectors(normal_transformed, Vec3d::UnitZ()).toRotationMatrix();
        polygon = transform(polygon, m);

        Vec3d bb_size = BoundingBoxf3(polygon).size();
        float sf = std::min(1. / bb_size(0), 1. / bb_size(1));
        Transform3d tr = Geometry::scale_transform({sf, sf, 1.f});
        polygon = transform(polygon, tr);
        polygon = Slic3r::Geometry::convex_hull(polygon);
        polygon = transform(polygon, tr.inverse());

        float &area = m_planes[polygon_id].area;
        area = 0.f;
        for (unsigned int i = 0; i < polygon.size(); ++i)
            area += polygon[i](0) * polygon[(i + 1) % polygon.size()](1) -
                    polygon[(i + 1) % polygon.size()](0) * polygon[i](1);
        area = 0.5f * std::abs(area);

        bool discard = false;
        if (area < minimal_area)
            discard = true;
        else {
            const double angle_threshold = ::cos(10.0 * (double)PI / 180.0);
            for (unsigned int i = 0; i < polygon.size(); ++i) {
                const Vec3d &prec = polygon[(i == 0) ? polygon.size() - 1 : i - 1];
                const Vec3d &curr = polygon[i];
                const Vec3d &next = polygon[(i == polygon.size() - 1) ? 0 : i + 1];
                if ((prec - curr).normalized().dot((next - curr).normalized()) > angle_threshold) {
                    discard = true;
                    break;
                }
            }
        }

        if (discard) {
            m_planes[polygon_id--] = std::move(m_planes.back());
            m_planes.pop_back();
            continue;
        }

        Vec3d centroid = std::accumulate(polygon.begin(), polygon.end(), Vec3d(0.0, 0.0, 0.0));
        centroid /= (double)polygon.size();
        for (auto &vertex : polygon)
            vertex = 0.9f * vertex + 0.1f * centroid;

        const unsigned int k = 10;
        const float aggressivity = 0.2f;
        const unsigned int N = polygon.size();
        std::vector<std::pair<unsigned int, unsigned int>> neighbours;

        if (k != 0) {
            Pointf3s points_out(2 * k * N);
            for (unsigned int j = 0; j < N; ++j) {
                points_out[j * 2 * k] = polygon[j];
                neighbours.push_back(std::make_pair(
                    (int)(j * 2 * k - k) < 0 ? (N - 1) * 2 * k + k : j * 2 * k - k,
                    j * 2 * k + k));
            }

            for (unsigned int i = 0; i < k; ++i) {
                for (unsigned int j = 0; j < N; ++j) {
                    if (i == 0)
                        points_out[j * 2 * k + k] = 0.5f * (points_out[j * 2 * k] +
                                                            points_out[j == N - 1 ? 0 : (j + 1) * 2 * k]);
                    else {
                        float r = 0.2 + 0.3 / (k - 1) * i;
                        points_out[neighbours[j].first] = r * points_out[j * 2 * k] +
                                                          (1 - r) * points_out[neighbours[j].first - 1];
                        points_out[neighbours[j].second] = r * points_out[j * 2 * k] +
                                                           (1 - r) * points_out[neighbours[j].second + 1];
                    }
                }

                for (unsigned int j = 0; j < N; ++j)
                    points_out[2 * k * j] = (1 - aggressivity) * points_out[2 * k * j] +
                                            aggressivity * 0.5f *
                                                (points_out[neighbours[j].first] + points_out[neighbours[j].second]);

                for (auto &n : neighbours) {
                    ++n.first;
                    --n.second;
                }
            }
            polygon = points_out;
        }

        for (auto &b : polygon)
            b(2) += 0.1f;

        polygon = transform(polygon, inst_matrix.inverse() * m.inverse());
    }

    std::sort(m_planes.rbegin(), m_planes.rend(),
              [](const PlaneData &a, const PlaneData &b) { return a.area < b.area; });
    m_planes.resize(std::min((int)m_planes.size(), 254));

    m_volumes_matrices.clear();
    m_volumes_types.clear();
    for (const ModelVolume *vol : mo->volumes) {
        m_volumes_matrices.push_back(vol->get_matrix());
        m_volumes_types.push_back(vol->type());
    }

    m_first_instance_scale = mo->instances.front()->get_scaling_factor();
    m_first_instance_mirror = mo->instances.front()->get_mirror();
    m_old_model_object = mo;
    m_old_instance_id = m_c->selection_info()->get_active_instance();

    for (auto &plane : m_planes) {
        indexed_triangle_set its;
        its.vertices.reserve(plane.vertices.size());
        its.indices.reserve(plane.vertices.size() / 3);

        for (size_t i = 0; i < plane.vertices.size(); ++i)
            its.vertices.emplace_back((Vec3f)plane.vertices[i].cast<float>());

        for (size_t i = 1; i < plane.vertices.size() - 1; ++i)
            its.indices.emplace_back(0, i, i + 1);

        plane.vbo.model.init_from(its);

        if (Geometry::Transformation(inst_matrix).is_left_handed()) {
            for (stl_triangle_vertex_indices &face : its.indices) {
                if (its_face_normal(its, face).cast<double>().dot(plane.normal) < 0.0)
                    std::swap(face[1], face[2]);
            }
        }

        plane.vbo.mesh_raycaster = std::make_unique<MeshRaycaster>(
            std::make_shared<const TriangleMesh>(std::move(its)));

        plane.vertices = std::vector<Vec3d>();
    }

    on_register_raycasters_for_picking();
}

bool GLGizmoFlatten::is_plane_update_necessary() const {
    const ModelObject *mo = m_c->selection_info()->model_object();
    if (m_state != On || !mo || mo->instances.empty())
        return false;

    if (m_planes.empty() || mo != m_old_model_object || mo->volumes.size() != m_volumes_matrices.size())
        return true;

    if (!mo->instances.front()->get_scaling_factor().isApprox(m_first_instance_scale) ||
        !mo->instances.front()->get_mirror().isApprox(m_first_instance_mirror))
        return true;

    for (unsigned int i = 0; i < mo->volumes.size(); ++i)
        if (!mo->volumes[i]->get_matrix().isApprox(m_volumes_matrices[i]) ||
            mo->volumes[i]->type() != m_volumes_types[i])
            return true;

    return false;
}

