#include "layoutmanager.hpp"

Rect::Rect(float x_pos, float y_pos, float w, float h) 
    : x(x_pos), y(y_pos), width(w), height(h) { }

LayoutManager::LayoutManager(float x_pos, float y_pos, float w, float h) 
    : m_current(x_pos, y_pos, w, h) { }

const Rect& LayoutManager::current() const {
    return m_current;
}

LayoutManager LayoutManager::copy() const {
    return LayoutManager(m_current.x, m_current.y, m_current.width, m_current.height);
}

void LayoutManager::pad(float padding) {
    pad(padding, padding);
}

void LayoutManager::pad(float paddingY, float paddingX) {
    m_current.x += paddingX;
    m_current.y += paddingY;
    m_current.width -= paddingX * 2;
    m_current.height -= paddingY * 2;
}

void LayoutManager::padLeft(float padding) {
    m_current.x += padding;
    m_current.width -= padding;
}

void LayoutManager::padRight(float padding) {
    m_current.width -= padding;
}

void LayoutManager::padUp(float padding) {
    m_current.y += padding;
    m_current.height -= padding;
}

void LayoutManager::padDown(float padding) {
    m_current.height -= padding;
}

void LayoutManager::border(float border_width) {
    m_current.x += border_width;
    m_current.y += border_width;
    m_current.width -= border_width * 2;
    m_current.height -= border_width * 2;
}

void LayoutManager::gapX(float gap_size) {
    m_current.x += gap_size;
    m_current.width -= gap_size;
}

void LayoutManager::gapY(float gap_size) {
    m_current.y += gap_size;
    m_current.height -= gap_size;
}

LayoutManager LayoutManager::sliceTop(float slice_height) {
    LayoutManager slice(m_current.x, m_current.y, m_current.width, slice_height);
    m_current.y += slice_height;
    m_current.height -= slice_height;
    return slice;
}

LayoutManager LayoutManager::sliceLeft(float slice_width) {
    LayoutManager slice(m_current.x, m_current.y, slice_width, m_current.height);
    m_current.x += slice_width;
    m_current.width -= slice_width;
    return slice;
}

