// Global flags initialized from settings
bool hmd_enabled = GetBoolFromSettingsByKey("enable hmd");
bool left_controller_enabled = GetBoolFromSettingsByKey("enable cl");
bool right_controller_enabled = GetBoolFromSettingsByKey("enable cr");

EVRInitError CServerDriver_Sample::Init(vr::IVRDriverContext* pDriverContext)
{
    VR_INIT_SERVER_DRIVER_CONTEXT(pDriverContext);

    // Re-read settings after context initialization
    hmd_enabled = GetBoolFromSettingsByKey("enable hmd");
    left_controller_enabled = GetBoolFromSettingsByKey("enable cl");
    right_controller_enabled = GetBoolFromSettingsByKey("enable cr");

    // Initialize HMD if enabled
    if (hmd_enabled) {
        m_pNullHmdLatest = new CSampleDeviceDriver();
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            m_pNullHmdLatest->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_HMD,
            m_pNullHmdLatest
        );
    }

    // Initialize left controller if enabled
    if (left_controller_enabled) {
        m_pController = new CSampleControllerDriver();
        m_pController->SetControllerIndex(false);
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            m_pController->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_Controller,
            m_pController
        );
    }

    // Initialize right controller if enabled
    if (right_controller_enabled) {
        m_pController2 = new CSampleControllerDriver();
        m_pController2->SetControllerIndex(true);
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            m_pController2->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_Controller,
            m_pController2
        );
    }

    // Add generic trackers based on configured count
    int tracker_quantity = GetIntFromSettingsByKey("trackers num");
    for (int idx = 0; idx < tracker_quantity; ++idx) {
        CSampleTracker* pNewTracker = new CSampleTracker();
        pNewTracker->SetTrackerIndex(idx);
        vr::VRServerDriverHost()->TrackedDeviceAdded(
            pNewTracker->GetSerialNumber().c_str(),
            vr::TrackedDeviceClass_GenericTracker,
            pNewTracker
        );
        m_vecTrackers.emplace_back(pNewTracker);
    }

    return VRInitError_None;
}

void CServerDriver_Sample::Cleanup()
{
    // Release HMD resources
    if (hmd_enabled) {
        delete m_pNullHmdLatest;
        m_pNullHmdLatest = nullptr;
    }

    // Release left controller resources
    if (left_controller_enabled) {
        delete m_pController;
        m_pController = nullptr;
    }

    // Release right controller resources
    if (right_controller_enabled) {
        delete m_pController2;
        m_pController2 = nullptr;
    }

    // Delete all trackers and clear container
    for (auto pTracker : m_vecTrackers) {
        delete pTracker;
    }
    m_vecTrackers.clear();
}

void CServerDriver_Sample::RunFrame()
{
    // Update active devices each frame
    if (m_pNullHmdLatest && hmd_enabled) {
        m_pNullHmdLatest->RunFrame();
    }

    if (m_pController && left_controller_enabled) {
        m_pController->RunFrame();
    }

    if (m_pController2 && right_controller_enabled) {
        m_pController2->RunFrame();
    }

    // Iterate over all trackers and run their frame logic
    for (CSampleTracker* pTracker : m_vecTrackers) {
        pTracker->RunFrame();
    }
}

#include "AsyncMqttClient.hpp"

// Helper function to generate unique client ID based on platform
static std::string _generateClientId() {
#ifdef ESP32
    char buf[32];
    sprintf(buf, "esp32-%06llx", ESP.getEfuseMac());
    return std::string(buf);
#elif defined(ESP8266)
    char buf[32];
    sprintf(buf, "esp8266-%06x", ESP.getChipId());
    return std::string(buf);
#else
    return "unknown-client";
#endif
}

AsyncMqttClient::AsyncMqttClient()
: _tcpClient()
, _head(nullptr)
, _tail(nullptr)
, _bytesSent(0)
, _connectionState(DISCONNECTED)
, _lastDisconnectReason(AsyncMqttClientDisconnectReason::TCP_DISCONNECTED)
, _lastActivityClient(0)
, _lastActivityServer(0)
, _pingTimestamp(0)
, _generatedId(_generateClientId())
, _serverIp()
, _hostname(nullptr)
, _usingIpAddress(false)
#if ASYNC_TCP_SSL_ENABLED
, _sslEnabled(false)
#endif
, _serverPort(0)
, _keepAliveInterval(15)
, _cleanSessionFlag(true)
, _clientIdentifier(nullptr)
, _authUsername(nullptr)
, _authPassword(nullptr)
, _lastWillTopic(nullptr)
, _lastWillData(nullptr)
, _lastWillSize(0)
, _willMessageQos(0)
, _willRetainFlag(false)
#if ASYNC_TCP_SSL_ENABLED
, _trustedFingerprints()
#endif
, _connectHandlers()
, _disconnectHandlers()
, _subscribeHandlers()
, _unsubscribeHandlers()
, _messageHandlers()
, _publishHandlers()
, _parserContext { .state = AsyncMqttClientInternals::BufferState::NONE, .maxAllowedTopicLength = 128, .topicStorage = NULL, .msgType = 0, .headerFlags = 0, .remainingBytes = 0 }
, _activePacket(nullptr)
, _remLenBufIdx(0)
, _remLenBuf{0}
, _pendingPubRelList() {

  // Register TCP callbacks
  _tcpClient.onConnect([](void* self, AsyncClient*) {
      static_cast<AsyncMqttClient*>(self)->_handleTcpConnected();
  }, this);

  _tcpClient.onDisconnect([](void* self, AsyncClient*) {
      static_cast<AsyncMqttClient*>(self)->_handleTcpDisconnected();
  }, this);

  _tcpClient.onAck([](void* self, AsyncClient*, size_t len, uint32_t) {
      static_cast<AsyncMqttClient*>(self)->_handleTcpAck(len);
  }, this);

  _tcpClient.onData([](void* self, AsyncClient*, void* data, size_t len) {
      static_cast<AsyncMqttClient*>(self)->_handleIncomingData(static_cast<char*>(data), len);
  }, this);

  _tcpClient.onPoll([](void* self, AsyncClient*) {
      static_cast<AsyncMqttClient*>(self)->_handlePeriodicTask();
  }, this);

  _tcpClient.setNoDelay(true); // Ensure small packets are sent immediately

#ifdef ESP32
  _mutex = xSemaphoreCreateMutex();
#elif defined(ESP8266)
  // No mutex needed for ESP8266 in this simplified version
#endif

  _clientIdentifier = const_cast<char*>(_generatedId.c_str());
  resizeMaxTopicLength(128);
}

AsyncMqttClient::~AsyncMqttClient() {
  delete _activePacket;
  delete[] _parserContext.topicStorage;
  _resetInternalState();
  _pendingPubRelList.clear();
  _pendingPubRelList.shrink_to_fit();
  _flushQueue(false); // Discard session data if needed
#ifdef ESP32
  vSemaphoreDelete(_mutex);
#endif
}

