void AsyncMqttClient::_freeActivePacket() {
  delete _activePacket;
  _activePacket = nullptr;
}

void AsyncMqttClient::_resetInternalState() {
  _pingTimestamp = 0;
  _freeActivePacket();
  _flushQueue(true); // Keep session data temporarily
  _parserContext.state = AsyncMqttClientInternals::BufferState::NONE;
  _tcpClient.setRxTimeout(0);
}

/* TCP Event Handlers */
void AsyncMqttClient::_handleTcpConnected() {
  log_i("TCP connected, sending MQTT CONNECT");
#if ASYNC_TCP_SSL_ENABLED
  if (_sslEnabled && !_trustedFingerprints.empty()) {
    SSL* ssl = _tcpClient.getSSL();
    bool matchFound = false;
    for (const auto& fp : _trustedFingerprints) {
      if (ssl_match_fingerprint(ssl, fp.data()) == SSL_OK) {
        matchFound = true;
        break;
      }
    }
    if (!matchFound) {
      _lastDisconnectReason = AsyncMqttClientDisconnectReason::TLS_BAD_FINGERPRINT;
      _tcpClient.close(true);
      return;
    }
  }
#endif

  auto* connectMsg = new AsyncMqttClientInternals::ConnectOutPacket(
      _cleanSessionFlag,
      _authUsername,
      _authPassword,
      _lastWillTopic,
      _willRetainFlag,
      _willMessageQos,
      _lastWillData,
      _lastWillSize,
      _keepAliveInterval,
      _clientIdentifier
  );
  _prependPacket(connectMsg);
  _processQueue();
}

void AsyncMqttClient::_handleTcpDisconnected() {
  log_i("TCP disconnected");
  _connectionState = DISCONNECTED;
  _resetInternalState();

  for (auto& handler : _disconnectHandlers) {
    handler(_lastDisconnectReason);
  }
}

void AsyncMqttClient::_handleTcpAck(size_t len) {
  log_i("ACK received (%u bytes)", len);
  _processQueue();
}

void AsyncMqttClient::_handleIncomingData(char* buffer, size_t size) {
  log_i("Received %u bytes", size);
  size_t idx = 0;
  char currentByte;

  _lastActivityServer = millis();

  while (idx < size) {
    switch (_parserContext.state) {
      case AsyncMqttClientInternals::BufferState::NONE:
        currentByte = buffer[idx++];
        _parserContext.msgType = currentByte >> 4;
        _parserContext.headerFlags = currentByte & 0x0F;
        _parserContext.state = AsyncMqttClientInternals::BufferState::REMAINING_LENGTH;

        switch (_parserContext.msgType) {
          case AsyncMqttClientInternals::PacketType::CONNACK:
            log_i("RCVD CONNACK");
            _activePacket = new AsyncMqttClientInternals::ConnAckPacket(&_parserContext,
                [this](bool sessionPresent, uint8_t code) { _onConnAck(sessionPresent, code); });
            _tcpClient.setRxTimeout(0);
            break;
          case AsyncMqttClientInternals::PacketType::PINGRESP:
            log_i("RCVD PINGRESP");
            _activePacket = new AsyncMqttClientInternals::PingRespPacket(&_parserContext,
                [this]() { _onPingResponse(); });
            break;
          case AsyncMqttClientInternals::PacketType::SUBACK:
            log_i("RCVD SUBACK");
            _activePacket = new AsyncMqttClientInternals::SubAckPacket(&_parserContext,
                [this](uint16_t pid, char status) { _onSubAck(pid, status); });
            break;
          case AsyncMqttClientInternals::PacketType::UNSUBACK:
            log_i("RCVD UNSUBACK");
            _activePacket = new AsyncMqttClientInternals::UnsubAckPacket(&_parserContext,
                [this](uint16_t pid) { _onUnsubAck(pid); });
            break;
          case AsyncMqttClientInternals::PacketType::PUBLISH:
            log_i("RCVD PUBLISH");
            _activePacket = new AsyncMqttClientInternals::PublishPacket(&_parserContext,
                [this](char* t, char* p, uint8_t q, bool d, bool r, size_t l, size_t i, size_t tot, uint16_t pid) {
                    _onMessage(t, p, q, d, r, l, i, tot, pid);
                },
                [this](uint16_t pid, uint8_t q) { _onPublish(pid, q); });
            break;
          case AsyncMqttClientInternals::PacketType::PUBREL:
            log_i("RCVD PUBREL");
            _activePacket = new AsyncMqttClientInternals::PubRelPacket(&_parserContext,
                [this](uint16_t pid) { _onPubRel(pid); });
            break;
          case AsyncMqttClientInternals::PacketType::PUBACK:
            log_i("RCVD PUBACK");
            _activePacket = new AsyncMqttClientInternals::PubAckPacket(&_parserContext,
                [this](uint16_t pid) { _onPubAck(pid); });
            break;
          case AsyncMqttClientInternals::PacketType::PUBREC:
            log_i("RCVD PUBREC");
            _activePacket = new AsyncMqttClientInternals::PubRecPacket(&_parserContext,
                [this](uint16_t pid) { _onPubRec(pid); });
            break;
          case AsyncMqttClientInternals::PacketType::PUBCOMP:
            log_i("RCVD PUBCOMP");
            _activePacket = new AsyncMqttClientInternals::PubCompPacket(&_parserContext,
                [this](uint16_t pid) { _onPubComp(pid); });
            break;
          default:
            log_i("RCVD UNKNOWN - Protocol Violation");
            disconnect(true);
            break;
        }
        break;

      case AsyncMqttClientInternals::BufferState::REMAINING_LENGTH:
        currentByte = buffer[idx++];
        _remLenBuf[_remLenBufIdx++] = currentByte;
        if ((currentByte & 0x80) == 0) {
          _parserContext.remainingBytes = AsyncMqttClientInternals::Helpers::decodeRemainingLength(_remLenBuf);
          _remLenBufIdx = 0;
          if (_parserContext.remainingBytes > 0) {
            _parserContext.state = AsyncMqttClientInternals::BufferState::VARIABLE_HEADER;
          } else {
            // Special case: PINGRESP has zero remaining length
            _parserContext.state = AsyncMqttClientInternals::BufferState::NONE;
            _onPingResponse();
          }
        }
        break;

      case AsyncMqttClientInternals::BufferState::VARIABLE_HEADER:
        _activePacket->parseVariableHeader(buffer, size, &idx);
        break;

      case AsyncMqttClientInternals::BufferState::PAYLOAD:
        _activePacket->parsePayload(buffer, size, &idx);
        break;

      default:
        idx = size; // Exit loop
        break;
    }
  }
}

void AsyncMqttClient::_handlePeriodicTask() {
  // Check for ping timeout
  if (_pingTimestamp != 0 && (millis() - _pingTimestamp) >= (_keepAliveInterval * 2000)) {
    log_w("Ping timeout — disconnecting");
    disconnect(true);
    return;
  }

  // Send periodic PINGREQ if idle too long
  if (_connectionState == CONNECTED && _pingTimestamp == 0) {
    uint32_t now = millis();
    if ((now - _lastActivityClient) >= (_keepAliveInterval * 700) ||
        (now - _lastActivityServer) >= (_keepAliveInterval * 700)) {
      _sendPingRequest();
    }
  }

  _processQueue();
}

/* Queue Management */
void AsyncMqttClient::_insertPacket(AsyncMqttClientInternals::OutPacket* pkt) {
  // Used only for QoS2 PUBREL; assumes head exists (PUBLISH)
  SEMAPHORE_ACQUIRE();
  log_i("INSERT #%u", pkt->packetType());
  pkt->next = _head->next;
  _head->next = pkt;
  if (_head == _tail) {
    _tail = pkt;
  }
  SEMAPHORE_RELEASE();
  _processQueue();
}

void AsyncMqttClient::_prependPacket(AsyncMqttClientInternals::OutPacket* pkt) {
  // For CONNECT packet only; ensures it goes first
  SEMAPHORE_ACQUIRE();
  log_i("PREPEND #%u", pkt->packetType());
  if (!_head) {
    _tail = pkt;
  } else {
    pkt->next = _head;
  }
  _head = pkt;
  SEMAPHORE_RELEASE();
  _processQueue();
}

void AsyncMqttClient::_appendPacket(AsyncMqttClientInternals::OutPacket* pkt) {
  SEMAPHORE_ACQUIRE();
  log_i("APPEND #%u", pkt->packetType());
  if (!_tail) {
    _head = pkt;
  } else {
    _tail->next = pkt;
  }
  _tail = pkt;
  _tail->next = nullptr;
  SEMAPHORE_RELEASE();
  _processQueue();
}

void AsyncMqttClient::_processQueue() {
  SEMAPHORE_ACQUIRE();
  bool shouldDisconnect = false;

  while (_head && _tcpClient.space() > 10) {
    if (_head->totalSize() > _bytesSent) {
      size_t toSend = std::min(_head->totalSize() - _bytesSent, static_cast<size_t>(_tcpClient.space()));
      size_t actualSent = _tcpClient.add(reinterpret_cast<const char*>(_head->getData(_bytesSent)), toSend, ASYNC_WRITE_FLAG_COPY);
      _bytesSent += toSend;
      (void)actualSent;
      _tcpClient.send();
      _lastActivityClient = millis();
      _pingTimestamp = 0;

#if ASYNC_TCP_SSL_ENABLED
      log_i("SENT #%u (tls: %u) %zu/%zu", _head->packetType(), actualSent, _bytesSent, _head->totalSize());
#else
      log_i("SENT #%u %zu/%zu", _head->packetType(), _bytesSent, _head->totalSize());
#endif

      if (_head->packetType() == AsyncMqttClientInternals::PacketType::DISCONNECT) {
        shouldDisconnect = true;
      }
    }

    if (_head->totalSize() == _bytesSent) {
      if (_head->isReleased()) {
        log_i("RELEASE #%d", _head->packetType());
        AsyncMqttClientInternals::OutPacket* temp = _head;
        _head = _head->next;
        if (!_head) _tail = nullptr;
        delete temp;
        _bytesSent = 0;
      } else {
        break; // Wait for MQTT ACK before proceeding
      }
    }
  }

  SEMAPHORE_RELEASE();

  if (shouldDisconnect) {
    log_i("DISCONNECT sent, closing connection");
    _tcpClient.close();
  }
}

void AsyncMqttClient::_flushQueue(bool preserveSession) {
  SEMAPHORE_ACQUIRE();
  AsyncMqttClientInternals::OutPacket* cursor = _head;
  _head = nullptr;
  _tail = nullptr;

  while (cursor) {
    AsyncMqttClientInternals::OutPacket* next = cursor->next;

    if (preserveSession) {
      if ((cursor->qosLevel() > 0 && cursor->totalSize() <= _bytesSent) ||
          cursor->packetType() == AsyncMqttClientInternals::PacketType::PUBREC ||
          cursor->packetType() == AsyncMqttClientInternals::PacketType::PUBCOMP) {
        if (cursor->packetType() == AsyncMqttClientInternals::PacketType::PUBLISH) {
          reinterpret_cast<AsyncMqttClientInternals::PublishOutPacket*>(cursor)->setDuplicateFlag();
        }
        SEMAPHORE_RELEASE();
        _appendPacket(cursor);
        SEMAPHORE_ACQUIRE();
      } else {
        delete cursor;
      }
    } else {
      delete cursor;
    }

    cursor = next;
  }

  _bytesSent = 0;
  SEMAPHORE_RELEASE();
}

/* MQTT Callbacks */
void AsyncMqttClient::_onPingResponse() {
  log_i("PINGRESP received");
  _freeActivePacket();
  _pingTimestamp = 0;
}

void AsyncMqttClient::_onConnAck(bool sessionPresent, uint8_t connCode) {
  log_i("CONNACK rc=%u", connCode);
  _freeActivePacket();

  if (!sessionPresent) {
    _pendingPubRelList.clear();
    _pendingPubRelList.shrink_to_fit();
    _flushQueue(false);
  }

  if (connCode == 0) {
    _connectionState = CONNECTED;
    for (auto& cb : _connectHandlers) cb(sessionPresent);
  } else {
    _lastDisconnectReason = static_cast<AsyncMqttClientDisconnectReason>(connCode);
    return;
  }

  _processQueue();
}

void AsyncMqttClient::_onSubAck(uint16_t packetId, char status) {
  log_i("SUBACK rc=%d", status);
  _freeActivePacket();

  SEMAPHORE_ACQUIRE();
  if (_head && _head->packetId() == packetId) {
    _head->release();
    log_i("SUB released");
  }
  SEMAPHORE_RELEASE();

  for (auto& cb : _subscribeHandlers) cb(packetId, status);
  _processQueue();
}

void AsyncMqttClient::_onUnsubAck(uint16_t packetId) {
  log_i("UNSUBACK");
  _freeActivePacket();

  SEMAPHORE_ACQUIRE();
  if (_head && _head->packetId() == packetId) {
    _head->release();
    log_i("UNSUB released");
  }
  SEMAPHORE_RELEASE();

  for (auto& cb : _unsubscribeHandlers) cb(packetId);
  _processQueue();
}

void AsyncMqttClient::_onMessage(char* topic, char* payload, uint8_t qos, bool dup, bool retain, size_t len, size_t index, size_t total, uint16_t packetId) {
  bool notify = true;
  if (qos == 2) {
    for (const auto& item : _pendingPubRelList) {
      if (item.packetId == packetId) {
        notify = false;
        break;
      }
    }
  }

  if (notify) {
    AsyncMqttClientMessageProperties props;
    props.qos = qos;
    props.dup = dup;
    props.retain = retain;
    for (auto& cb : _messageHandlers) cb(topic, payload, props, len, index, total);
  }
}

void AsyncMqttClient::_onPublish(uint16_t packetId, uint8_t qos) {
  AsyncMqttClientInternals::PendingAck ack;
  if (qos == 1) {
    ack.packetType = AsyncMqttClientInternals::PacketType::PUBACK;
    ack.flags = AsyncMqttClientInternals::HeaderFlag::PUBACK_RESERVED;
    ack.packetId = packetId;
    _appendPacket(new AsyncMqttClientInternals::PubAckOutPacket(ack));
  } else if (qos == 2) {
    ack.packetType = AsyncMqttClientInternals::PacketType::PUBREC;
    ack.flags = AsyncMqttClientInternals::HeaderFlag::PUBREC_RESERVED;
    ack.packetId = packetId;
    _appendPacket(new AsyncMqttClientInternals::PubAckOutPacket(ack));

    bool alreadyAwaiting = false;
    for (const auto& item : _pendingPubRelList) {
      if (item.packetId == packetId) {
        alreadyAwaiting = true;
        break;
      }
    }

    if (!alreadyAwaiting) {
      AsyncMqttClientInternals::PendingPubRel rel;
      rel.packetId = packetId;
      _pendingPubRelList.push_back(rel);
    }
  }

  _freeActivePacket();
}

void AsyncMqttClient::_onPubRel(uint16_t packetId) {
  _freeActivePacket();

  AsyncMqttClientInternals::PendingAck ack;
  ack.packetType = AsyncMqttClientInternals::PacketType::PUBCOMP;
  ack.flags = AsyncMqttClientInternals::HeaderFlag::PUBCOMP_RESERVED;
  ack.packetId = packetId;

  if (_head && _head->packetId() == packetId) {
    _head->release();
    _insertPacket(new AsyncMqttClientInternals::PubAckOutPacket(ack));
    log_i("PUBREL released");
  }

  for (size_t i = 0; i < _pendingPubRelList.size(); ++i) {
    if (_pendingPubRelList[i].packetId == packetId) {
      _pendingPubRelList.erase(_pendingPubRelList.begin() + i);
      _pendingPubRelList.shrink_to_fit();
      break;
    }
  }
}

void AsyncMqttClient::_onPubAck(uint16_t packetId) {
  _freeActivePacket();
  if (_head && _head->packetId() == packetId) {
    _head->release();
    log_i("PUB released");
  }
  for (auto& cb : _publishHandlers) cb(packetId);
}

void AsyncMqttClient::_onPubRec(uint16_t packetId) {
  _freeActivePacket();

  AsyncMqttClientInternals::PendingAck ack;
  ack.packetType = AsyncMqttClientInternals::PacketType::PUBREL;
  ack.flags = AsyncMqttClientInternals::HeaderFlag::PUBREL_RESERVED;
  ack.packetId = packetId;

  log_i("SENDING PUBREL");
  if (_head && _head->packetId() == packetId) {
    _head->release();
    log_i("PUB released");
  }
  _insertPacket(new AsyncMqttClientInternals::PubAckOutPacket(ack));
}

void AsyncMqttClient::_onPubComp(uint16_t packetId) {
  _freeActivePacket();
  if (_head && _head->packetId() == packetId) {
    _head->release();
    log_i("PUBREL released");
  }
  for (auto& cb : _publishHandlers) cb(packetId);
}

void AsyncMqttClient::_sendPingRequest() {
  log_i("PINGREQ");
  _pingTimestamp = millis();
  _appendPacket(new AsyncMqttClientInternals::PingReqOutPacket);
}

bool AsyncMqttClient::connected() const {
  return _connectionState == CONNECTED;
}

void AsyncMqttClient::connect() {
  if (_connectionState != DISCONNECTED) return;

  log_i("Connecting...");
  _connectionState = CONNECTING;
  _lastDisconnectReason = AsyncMqttClientDisconnectReason::TCP_DISCONNECTED;
  _tcpClient.setRxTimeout(_keepAliveInterval);

#if ASYNC_TCP_SSL_ENABLED
  if (_usingIpAddress) {
    _tcpClient.connect(_serverIp, _serverPort, _sslEnabled);
  } else {
    _tcpClient.connect(_hostname, _serverPort, _sslEnabled);
  }
#else
  if (_usingIpAddress) {
    _tcpClient.connect(_serverIp, _serverPort);
  } else {
    _tcpClient.connect(_hostname, _serverPort);
  }
#endif
}

void AsyncMqttClient::disconnect(bool force) {
  if (_connectionState == DISCONNECTED) return;

  log_i("DISCONNECT (force=%d)", force);

  if (force) {
    _connectionState = DISCONNECTED;
    _tcpClient.close(true);
  } else if (_connectionState != DISCONNECTING) {
    _connectionState = DISCONNECTING;
    _appendPacket(new AsyncMqttClientInternals::DisconnOutPacket);
  }
}

uint16_t AsyncMqttClient::subscribe(const char* topic, uint8_t qos) {
  if (_connectionState != CONNECTED) return 0;
  log_i("SUBSCRIBE %s", topic);
  auto* msg = new AsyncMqttClientInternals::SubscribeOutPacket(topic, qos);
  _appendPacket(msg);
  return msg->packetId();
}

uint16_t AsyncMqttClient::unsubscribe(const char* topic) {
  if (_connectionState != CONNECTED) return 0;
  log_i("UNSUBSCRIBE %s", topic);
  auto* msg = new AsyncMqttClientInternals::UnsubscribeOutPacket(topic);
  _appendPacket(msg);
  return msg->packetId();
}

uint16_t AsyncMqttClient::publish(const char* topic, uint8_t qos, bool retain, const char* payload, size_t length, bool dup, uint16_t mid) {
  if (_connectionState != CONNECTED) return 0;
  log_i("PUBLISH %s", topic);
  auto* msg = new AsyncMqttClientInternals::PublishOutPacket(topic, qos, retain, payload, length);
  _appendPacket(msg);
  return msg->packetId();
}

bool AsyncMqttClient::clearQueue() {
  if (_connectionState != DISCONNECTED) return false;
  _flushQueue(false);
  return true;
}

const char* AsyncMqttClient::getClientId() const {
  return _clientIdentifier;
}

