static constexpr int InvalidIndex = -1;

void X3DGeoHelper::coordIdx_str2faces_arr(const std::vector<int32_t> &pCoordIdx, std::vector<aiFace> &pFaces, unsigned int &pPrimitiveTypes) {
    std::vector<int32_t> f_data(pCoordIdx);
    std::vector<unsigned int> inds;
    unsigned int prim_type = 0;

    if (!f_data.empty() && f_data.back() != InvalidIndex) {
        f_data.push_back(InvalidIndex);
    }

    pFaces.reserve(f_data.size() / 3);
    inds.reserve(4);

    for (auto it = f_data.begin(); it != f_data.end(); ++it) {
        if (*it == InvalidIndex) {
            if (inds.empty()) goto mg_m_err;

            aiFace tface;
            size_t ts = inds.size();

            if (ts == 1) {
                prim_type |= aiPrimitiveType_POINT;
            } else if (ts == 2) {
                prim_type |= aiPrimitiveType_LINE;
            } else if (ts == 3) {
                prim_type |= aiPrimitiveType_TRIANGLE;
            } else {
                prim_type |= aiPrimitiveType_POLYGON;
            }

            tface.mNumIndices = static_cast<unsigned int>(ts);
            tface.mIndices = new unsigned int[ts];
            std::memcpy(tface.mIndices, inds.data(), ts * sizeof(unsigned int));
            pFaces.push_back(tface);
            inds.clear();
        } else {
            inds.push_back(static_cast<unsigned int>(*it));
        }
    }

    pPrimitiveTypes = prim_type;
    return;

mg_m_err:
    for (auto &face : pFaces) {
        delete[] face.mIndices;
    }
    pFaces.clear();
}

void X3DGeoHelper::coordIdx_str2lines_arr(const std::vector<int32_t> &pCoordIdx, std::vector<aiFace> &pFaces) {
    std::vector<int32_t> f_data(pCoordIdx);
    if (!f_data.empty() && f_data.back() != InvalidIndex) {
        f_data.push_back(InvalidIndex);
    }

    pFaces.reserve(f_data.size() / 2);

    auto startIt = f_data.cbegin();
    for (auto endIt = f_data.cbegin(); endIt != f_data.cend(); ++endIt) {
        if (*endIt != -1) continue;

        std::size_t numIndices = std::distance(startIt, endIt);
        if (numIndices <= 1) goto mg_m_err;

        int32_t prevIdx = *startIt++;
        for (; startIt != endIt; ++startIt) {
            int32_t currIdx = *startIt;
            aiFace tface;
            tface.mNumIndices = 2;
            tface.mIndices = new unsigned int[2];
            tface.mIndices[0] = static_cast<unsigned int>(prevIdx);
            tface.mIndices[1] = static_cast<unsigned int>(currIdx);
            pFaces.push_back(tface);
            prevIdx = currIdx;
        }
        ++startIt;
    }

    return;

mg_m_err:
    for (auto &face : pFaces) {
        delete[] face.mIndices;
    }
    pFaces.clear();
}

void X3DGeoHelper::add_color(aiMesh &pMesh, const std::list<aiColor3D> &pColors, const bool pColorPerVertex) {
    std::list<aiColor4D> rgbaColors;
    for (const auto &color : pColors) {
        rgbaColors.emplace_back(color.r, color.g, color.b, static_cast<ai_real>(1.0));
    }
    add_color(pMesh, rgbaColors, pColorPerVertex);
}

void X3DGeoHelper::add_color(aiMesh &pMesh, const std::list<aiColor4D> &pColors, const bool pColorPerVertex) {
    auto colIt = pColors.begin();

    if (pColorPerVertex) {
        if (pColors.size() < pMesh.mNumVertices) {
            throw DeadlyImportError("AddColor: Not enough colors for all vertices.");
        }

        pMesh.mColors[0] = new aiColor4D[pMesh.mNumVertices];
        for (size_t i = 0; i < pMesh.mNumVertices; ++i) {
            pMesh.mColors[0][i] = *colIt++;
        }
    } else {
        if (pColors.size() < pMesh.mNumFaces) {
            throw DeadlyImportError("AddColor: Not enough colors for all faces.");
        }

        pMesh.mColors[0] = new aiColor4D[pMesh.mNumVertices];
        for (size_t fi = 0; fi < pMesh.mNumFaces; ++fi) {
            aiColor4D faceColor = *colIt;
            for (size_t vi = 0; vi < pMesh.mFaces[fi].mNumIndices; ++vi) {
                pMesh.mColors[0][pMesh.mFaces[fi].mIndices[vi]] = faceColor;
            }
            ++colIt;
        }
    }
}

void X3DGeoHelper::add_color(aiMesh &pMesh, const std::vector<int32_t> &pCoordIdx,
        const std::vector<int32_t> &pColorIdx, const std::list<aiColor3D> &pColors, const bool pColorPerVertex) {
    std::list<aiColor4D> rgbaColors;
    for (const auto &color : pColors) {
        rgbaColors.emplace_back(color.r, color.g, color.b, static_cast<ai_real>(1.0));
    }
    add_color(pMesh, pCoordIdx, pColorIdx, rgbaColors, pColorPerVertex);
}

void X3DGeoHelper::add_color(aiMesh &pMesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &colorIdx, const std::list<aiColor4D> &colors, bool colorPerVertex) {
    std::vector<aiColor4D> colorArray;
    colorArray.reserve(colors.size());
    for (const auto &c : colors) {
        colorArray.push_back(c);
    }

    if (colorPerVertex) {
        if (!colorIdx.empty()) {
            if (colorIdx.size() < coordIdx.size()) {
                throw DeadlyImportError("AddColor: Insufficient color indices.");
            }

            std::vector<aiColor4D> targetColors(pMesh.mNumVertices);
            auto cIt = colorIdx.begin();
            auto vIt = coordIdx.begin();

            for (; cIt != colorIdx.end(); ++cIt, ++vIt) {
                if (*cIt == -1) continue;
                if (static_cast<size_t>(*vIt) >= pMesh.mNumVertices ||
                    static_cast<size_t>(*cIt) >= colorArray.size()) {
                    throw DeadlyImportError("AddColor: Index out of range.");
                }
                targetColors[*vIt] = colorArray[*cIt];
            }

            pMesh.mColors[0] = new aiColor4D[pMesh.mNumVertices];
            for (size_t i = 0; i < pMesh.mNumVertices; ++i) {
                pMesh.mColors[0][i] = targetColors[i];
            }
        } else {
            if (colors.size() < pMesh.mNumVertices) {
                throw DeadlyImportError("AddColor: Not enough colors for all vertices.");
            }

            pMesh.mColors[0] = new aiColor4D[pMesh.mNumVertices];
            for (size_t i = 0; i < pMesh.mNumVertices; ++i) {
                pMesh.mColors[0][i] = colorArray[i];
            }
        }
    } else {
        if (!colorIdx.empty()) {
            if (colorIdx.size() < pMesh.mNumFaces) {
                throw DeadlyImportError("AddColor: Not enough color indices for faces.");
            }

            std::vector<aiColor4D> targetColors(pMesh.mNumFaces);
            for (size_t fi = 0; fi < pMesh.mNumFaces; ++fi) {
                if (static_cast<size_t>(colorIdx[fi]) >= colorArray.size()) {
                    throw DeadlyImportError("AddColor: Face color index out of range.");
                }
                targetColors[fi] = colorArray[colorIdx[fi]];
            }

            pMesh.mColors[0] = new aiColor4D[pMesh.mNumVertices];
            for (size_t fi = 0; fi < pMesh.mNumFaces; ++fi) {
                aiColor4D faceColor = targetColors[fi];
                for (size_t vi = 0; vi < pMesh.mFaces[fi].mNumIndices; ++vi) {
                    pMesh.mColors[0][pMesh.mFaces[fi].mIndices[vi]] = faceColor;
                }
            }
        } else {
            if (colors.size() < pMesh.mNumFaces) {
                throw DeadlyImportError("AddColor: Not enough colors for all faces.");
            }

            pMesh.mColors[0] = new aiColor4D[pMesh.mNumVertices];
            for (size_t fi = 0; fi < pMesh.mNumFaces; ++fi) {
                aiColor4D faceColor = colorArray[fi];
                for (size_t vi = 0; vi < pMesh.mFaces[fi].mNumIndices; ++vi) {
                    pMesh.mColors[0][pMesh.mFaces[fi].mIndices[vi]] = faceColor;
                }
            }
        }
    }
}

void X3DGeoHelper::add_normal(aiMesh &pMesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &normalIdx, const std::list<aiVector3D> &normals, const bool normalPerVertex) {
    std::vector<aiVector3D> normArray;
    normArray.reserve(normals.size());
    for (const auto &n : normals) {
        normArray.push_back(n);
    }

    if (normalPerVertex) {
        if (!normalIdx.empty()) {
            if (normalIdx.size() != coordIdx.size()) {
                throw DeadlyImportError("AddNormal: Normal and coordinate indices must match.");
            }

            std::vector<size_t> validIndices;
            for (int32_t idx : normalIdx) {
                if (idx != -1) validIndices.push_back(static_cast<size_t>(idx));
            }

            pMesh.mNormals = new aiVector3D[pMesh.mNumVertices];
            for (size_t i = 0; i < pMesh.mNumVertices && i < validIndices.size(); ++i) {
                if (validIndices[i] >= normArray.size()) {
                    throw DeadlyImportError("AddNormal: Normal index out of range.");
                }
                pMesh.mNormals[i] = normArray[validIndices[i]];
            }
        } else {
            if (normals.size() != pMesh.mNumVertices) {
                throw DeadlyImportError("AddNormal: Normals count must match vertices.");
            }

            pMesh.mNormals = new aiVector3D[pMesh.mNumVertices];
            auto nIt = normals.begin();
            for (size_t i = 0; i < pMesh.mNumVertices; ++i) {
                pMesh.mNormals[i] = *nIt++;
            }
        }
    } else {
        std::vector<size_t> faceNormIndices;
        if (!normalIdx.empty()) {
            if (normalIdx.size() != pMesh.mNumFaces) {
                throw DeadlyImportError("AddNormal: Face normals count mismatch.");
            }
            for (int32_t idx : normalIdx) {
                faceNormIndices.push_back(static_cast<size_t>(idx));
            }
        } else {
            for (size_t i = 0; i < pMesh.mNumFaces; ++i) {
                faceNormIndices.push_back(i);
            }
        }

        pMesh.mNormals = new aiVector3D[pMesh.mNumVertices];
        for (size_t fi = 0; fi < pMesh.mNumFaces; ++fi) {
            aiVector3D faceNormal = normArray[faceNormIndices[fi]];
            for (size_t vi = 0; vi < pMesh.mFaces[fi].mNumIndices; ++vi) {
                pMesh.mNormals[pMesh.mFaces[fi].mIndices[vi]] = faceNormal;
            }
        }
    }
}

void X3DGeoHelper::add_normal(aiMesh &pMesh, const std::list<aiVector3D> &normals, const bool normalPerVertex) {
    auto nIt = normals.begin();

    if (normalPerVertex) {
        if (normals.size() != pMesh.mNumVertices) {
            throw DeadlyImportError("AddNormal: Normals and vertices count mismatch.");
        }

        pMesh.mNormals = new aiVector3D[pMesh.mNumVertices];
        for (size_t i = 0; i < pMesh.mNumVertices; ++i) {
            pMesh.mNormals[i] = *nIt++;
        }
    } else {
        if (normals.size() != pMesh.mNumFaces) {
            throw DeadlyImportError("AddNormal: Normals and faces count mismatch.");
        }

        pMesh.mNormals = new aiVector3D[pMesh.mNumVertices];
        for (size_t fi = 0; fi < pMesh.mNumFaces; ++fi) {
            aiVector3D faceNormal = *nIt;
            for (size_t vi = 0; vi < pMesh.mFaces[fi].mNumIndices; ++vi) {
                pMesh.mNormals[pMesh.mFaces[fi].mIndices[vi]] = faceNormal;
            }
            ++nIt;
        }
    }
}

void X3DGeoHelper::add_tex_coord(aiMesh &pMesh, const std::vector<int32_t> &coordIdx,
        const std::vector<int32_t> &texCoordIdx, const std::list<aiVector2D> &texCoords) {
    std::vector<aiVector3D> texArray;
    texArray.reserve(texCoords.size());
    for (const auto &tc : texCoords) {
        texArray.emplace_back(tc.x, tc.y, static_cast<ai_real>(0));
    }

    std::vector<aiFace> faces;
    unsigned int primType;

    if (!texCoordIdx.empty()) {
        coordIdx_str2faces_arr(texCoordIdx, faces, primType);
        if (faces.empty()) {
            throw DeadlyImportError("AddTexCoord: Failed to parse texture coordinates.");
        }
        if (faces.size() != pMesh.mNumFaces) {
            throw DeadlyImportError("AddTexCoord: Texture face count mismatch.");
        }
    } else {
        coordIdx_str2faces_arr(coordIdx, faces, primType);
    }

    pMesh.mTextureCoords[0] = new aiVector3D[pMesh.mNumVertices];
    pMesh.mNumUVComponents[0] = 2;

    for (size_t fi = 0; fi < faces.size(); ++fi) {
        if (faces[fi].mNumIndices != pMesh.mFaces[fi].mNumIndices) {
            throw DeadlyImportError("AddTexCoord: Face index count mismatch.");
        }
        for (size_t ii = 0; ii < faces[fi].mNumIndices; ++ii) {
            size_t vertIdx = pMesh.mFaces[fi].mIndices[ii];
            size_t tcIdx = faces[fi].mIndices[ii];
            pMesh.mTextureCoords[0][vertIdx] = texArray[tcIdx];
        }
    }
}

void X3DGeoHelper::add_tex_coord(aiMesh &pMesh, const std::list<aiVector2D> &texCoords) {
    if (texCoords.size() != pMesh.mNumVertices) {
        throw DeadlyImportError("AddTexCoord: Texture coordinates and vertex count mismatch.");
    }

    std::vector<aiVector3D> texArray;
    texArray.reserve(texCoords.size());
    for (const auto &tc : texCoords) {
        texArray.emplace_back(tc.x, tc.y, static_cast<ai_real>(0));
    }

    pMesh.mTextureCoords[0] = new aiVector3D[pMesh.mNumVertices];
    pMesh.mNumUVComponents[0] = 2;

    for (size_t i = 0; i < pMesh.mNumVertices; ++i) {
        pMesh.mTextureCoords[0][i] = texArray[i];
    }
}

aiMesh *X3DGeoHelper::make_mesh(const std::vector<int32_t> &coordIdx, const std::list<aiVector3D> &vertices) {
    std::vector<aiFace> faces;
    unsigned int primType = 0;

    coordIdx_str2faces_arr(coordIdx, faces, primType);
    if (faces.empty()) {
        throw DeadlyImportError("MakeMesh: No faces generated.");
    }

    aiMesh *mesh = new aiMesh();
    mesh->mNumFaces = static_cast<unsigned int>(faces.size());
    mesh->mFaces = new aiFace[mesh->mNumFaces];
    for (size_t i = 0; i < faces.size(); ++i) {
        mesh->mFaces[i] = faces[i];
    }

    mesh->mNumVertices = static_cast<unsigned int>(vertices.size());
    mesh->mVertices = new aiVector3D[mesh->mNumVertices];
    auto vIt = vertices.begin();
    for (size_t i = 0; i < vertices.size(); ++i) {
        mesh->mVertices[i] = *vIt++;
    }

    mesh->mPrimitiveTypes = primType;
    return mesh;
}

aiMesh *X3DGeoHelper::make_line_mesh(const std::vector<int32_t> &coordIdx, const std::list<aiVector3D> &vertices) {
    std::vector<aiFace> faces;
    coordIdx_str2lines_arr(coordIdx, faces);
    if (faces.empty()) {
        throw DeadlyImportError("MakeLineMesh: No faces generated.");
    }

    aiMesh *mesh = new aiMesh();
    mesh->mNumFaces = static_cast<unsigned int>(faces.size());
    mesh->mFaces = new aiFace[mesh->mNumFaces];
    for (size_t i = 0; i < faces.size(); ++i) {
        mesh->mFaces[i] = faces[i];
    }

    mesh->mNumVertices = static_cast<unsigned int>(vertices.size());
    mesh->mVertices = new aiVector3D[mesh->mNumVertices];
    auto vIt = vertices.begin();
    for (size_t i = 0; i < vertices.size(); ++i) {
        mesh->mVertices[i] = *vIt++;
    }

    mesh->mPrimitiveTypes = aiPrimitiveType_LINE;
    return mesh;
}

