namespace HVT_NS {

Engine::Engine() : _taskContext() {}
Engine::~Engine() = default;

void Engine::SetTaskContextData(TfToken const& key, VtValue const& value)
{
    // Attempt insertion; if key already exists, update instead.
    auto iter = _taskContext.find(key);
    if (iter != _taskContext.end()) {
        iter->second = value;
    } else {
        _taskContext.emplace(key, value);
    }
}

bool Engine::GetTaskContextData(TfToken const& key, VtValue* outValue) const
{
    if (!TF_VERIFY(outValue, "Output pointer for data is null"))
        return false;

    auto found = _taskContext.find(key);
    if (found != _taskContext.end()) {
        *outValue = found->second;
        return true;
    }
    return false;
}

void Engine::RemoveTaskContextData(TfToken const& key)
{
    _taskContext.erase(key);
}

void Engine::ClearTaskContextData()
{
    _taskContext.clear();
}

void Engine::Execute(HdRenderIndex* index, HdTaskSharedPtrVector* tasks)
{
    TRACE_FUNCTION();

    // Early exit if invalid inputs
    if (!index || !tasks) {
        TF_CODING_ERROR("Nullptr passed to Engine::Execute()");
        return;
    }

    // Inject driver list into context before execution
    _taskContext[HdTokens->drivers] = VtValue(index->GetDrivers());

    // ========================
    // PHASE 1: DATA DISCOVERY
    // ========================
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Data Discovery Phase](RenderIndex::SyncAll)         \n"
             "--------------------------------------------------------------\n");

    {
        TRACE_FUNCTION_SCOPE("Data Discovery");
        index->SyncAll(tasks, &_taskContext);
    }

    // ========================
    // PHASE 2: PREPARATION
    // ========================
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Prepare Phase](Task::Prepare)                       \n"
             "--------------------------------------------------------------\n");

    {
        TRACE_FUNCTION_SCOPE("Task Prepare");
        for (auto&& taskPtr : *tasks) {
            taskPtr->Prepare(&_taskContext, index);
        }
    }

    // ========================
    // PHASE 3: RESOURCE COMMIT
    // ========================
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Data Commit Phase](RenderDelegate::CommitResources) \n"
             "--------------------------------------------------------------\n");

    {
        TRACE_FUNCTION_SCOPE("Data Commit");
        HdRenderDelegate* delegate = index->GetRenderDelegate();
        delegate->CommitResources(&index->GetChangeTracker());
    }

    // ========================
    // PHASE 4: EXECUTION
    // ========================
    TF_DEBUG(HD_ENGINE_PHASE_INFO)
        .Msg("\n"
             "==============================================================\n"
             "  Engine [Execute Phase](Task::Execute)                       \n"
             "--------------------------------------------------------------\n");

    {
        TRACE_FUNCTION_SCOPE("Task Execution");
        for (auto&& taskPtr : *tasks) {
            taskPtr->Execute(&_taskContext);
        }
    }
}

void Engine::Execute(HdRenderIndex* const index, SdfPathVector const& paths)
{
    HdTaskSharedPtrVector selectedTasks;
    selectedTasks.reserve(paths.size());

    for (SdfPath const& path : paths) {
        if (path.IsEmpty()) {
            TF_CODING_ERROR("Empty task path in Engine::Execute()");
            continue;
        }

        HdTaskSharedPtr task = index->GetTask(path);
        if (!task) {
            TF_CODING_ERROR(
                "Missing task at %s in render index (Engine::Execute)", path.GetText());
            continue;
        }

        selectedTasks.push_back(std::move(task));
    }

    Execute(index, &selectedTasks);
}

bool Engine::AreTasksConverged(HdRenderIndex* const index, SdfPathVector const& paths)
{
    for (SdfPath const& path : paths) {
        if (path.IsEmpty()) {
            TF_CODING_ERROR("Empty task path in Engine::AreTasksConverged()");
            continue;
        }

        HdTaskSharedPtr task = index->GetTask(path);
        if (!task) {
            TF_CODING_ERROR(
                "No task at %s in render index (Engine::AreTasksConverged)", path.GetText());
            continue;
        }

        if (!task->IsConverged()) {
            return false;
        }
    }

    return true;
}

