using namespace llvm;

namespace llvm {
// Global flag controlling debug output activation
bool DebugFlag = false;
static ManagedStatic<std::vector<std::string>> ActiveDebugTypes;

// Check if provided debug type matches any currently active types
bool isCurrentDebugType(const char *typeName) {
  if (ActiveDebugTypes->empty())
    return true;

  // Linear search through active debug types
  for (const auto& entry : *ActiveDebugTypes) {
    if (entry == typeName)
      return true;
  }
  return false;
}

// Set multiple debug types at once
void setCurrentDebugTypes(const char **types, unsigned count);
// Set single debug type
void setCurrentDebugType(const char *type) {
  setCurrentDebugTypes(&type, 1);
}
void setCurrentDebugTypes(const char **types, unsigned count) {
  ActiveDebugTypes->clear();
  for (unsigned idx = 0; idx < count; ++idx) {
    ActiveDebugTypes->emplace_back(types[idx]);
  }
}
} // namespace llvm

#ifndef NDEBUG
namespace {
// Create -debug command line option
struct DebugOptionInitializer {
  static void *instantiate() {
    return new cl::opt<bool, true>("debug", 
                                   cl::desc("Activate debug output messages"),
                                   cl::Hidden, 
                                   cl::location(DebugFlag));
  }
};

// Create -debug-buffer-size command line option
struct DebugBufferSizeInitializer {
  static void *instantiate() {
    return new cl::opt<unsigned>(
        "debug-buffer-size",
        cl::desc("Hold last N characters of debug output "
                 "until program ends. "
                 "[default 0 -- print immediately]"),
        cl::Hidden, 
        cl::init(0));
  }
};
} // namespace

// Command line options for debug functionality
static ManagedStatic<cl::opt<bool, true>, DebugOptionInitializer> DebugOption;
static ManagedStatic<cl::opt<unsigned>, DebugBufferSizeInitializer> DebugBufferOption;

namespace {
// Parser for -debug-only option
struct DebugOnlyParser {
  void assign(const std::string &input) const {
    if (input.empty())
      return;

    DebugFlag = true;
    SmallVector<StringRef, 8> typeList;
    StringRef(input).split(typeList, ',', -1, false);

    for (StringRef type : typeList) {
      ActiveDebugTypes->push_back(std::string(type));
    }
  }
};
} // namespace

static DebugOnlyParser DebugOnlyParserInstance;

namespace {
// Initialize -debug-only command line option
struct DebugOnlyOptionInitializer {
  static void *instantiate() {
    return new cl::opt<DebugOnlyParser, true, cl::parser<std::string>>(
        "debug-only",
        cl::desc("Enable specific debug output categories (comma-separated list)"),
        cl::Hidden, 
        cl::value_desc("category names"),
        cl::location(DebugOnlyParserInstance), 
        cl::ValueRequired);
  }
};
} // namespace

static ManagedStatic<cl::opt<DebugOnlyParser, true, cl::parser<std::string>>,
                     DebugOnlyOptionInitializer>
    DebugOnlyOption;

void llvm::initDebugOptions() {
  *DebugOption;
  *DebugBufferOption;
  *DebugOnlyOption;
}

// Signal handler for dumping debug buffer on termination
static void debugOutputHandler(void *unused) {
  llvm::circular_raw_ostream &debugStream =
      static_cast<circular_raw_ostream &>(llvm::dbgs());
  debugStream.flushBufferWithBanner();
}

// Get debug output stream
raw_ostream &llvm::dbgs() {
  static struct DebugStreamHolder {
    circular_raw_ostream stream;
    DebugStreamHolder()
        : stream(errs(), "*** Debug Log Output ***\n",
                 (!EnableDebugBuffering || !DebugFlag) ? 0 : *DebugBufferOption) {
      if (EnableDebugBuffering && DebugFlag && *DebugBufferOption != 0)
        sys::AddSignalHandler(&debugOutputHandler, nullptr);
    }
  } theDebugStream;
  return theDebugStream.stream;
}
#else
// In release builds, dbgs() just returns error stream
namespace llvm {
  raw_ostream &dbgs() {
    return errs();
  }
}
void llvm::initDebugOptions() {}
#endif

