    // Helper lambda to dispatch based on device type — avoids repeated switch statements
    template<typename Func>
    auto dispatch_by_device_type(const input_device& dev, Func&& func) -> float
    {
        const auto type = dev.get_device_type();
        if (type == device_type::gamepad)
            return func(static_cast<const gamepad&>(dev));
        else if (type == device_type::keyboard)
            return func(static_cast<const keyboard&>(dev));
        else if (type == device_type::mouse)
            return func(static_cast<const mouse&>(dev));
        return 0.0f;
    }

    template<typename Func>
    auto dispatch_by_device_type_bool(const input_device& dev, Func&& func) -> bool
    {
        const auto type = dev.get_device_type();
        if (type == device_type::gamepad)
            return func(static_cast<const gamepad&>(dev));
        else if (type == device_type::keyboard)
            return func(static_cast<const keyboard&>(dev));
        else if (type == device_type::mouse)
            return func(static_cast<const mouse&>(dev));
        return false;
    }

