    auto action_map::get_analog_value(const action_id_t& action, const input_device& device) const -> float
    {
        return dispatch_by_device_type(device, [&](const auto& d) -> float {
            if constexpr (std::is_same_v<std::decay_t<decltype(d)>, gamepad>)
                return gamepad_map.get_analog_value(action, d);
            else if constexpr (std::is_same_v<std::decay_t<decltype(d)>, keyboard>)
                return keyboard_map.get_analog_value(action, d);
            else if constexpr (std::is_same_v<std::decay_t<decltype(d)>, mouse>)
