GCodeSender::GCodeSender()
    : m_io(), m_serial(m_io), m_can_transmit(false), m_line_number(0), m_is_open(false), m_has_error(false), m_is_connected(false), m_queue_suspended(false)
{
#ifdef DEBUG_SERIAL
    std::srand(static_cast<unsigned>(std::time(nullptr)));
#endif
}

GCodeSender::~GCodeSender()
{
    this->disconnect();
}

bool GCodeSender::connect(std::string device_path, unsigned int baud_rate)
{
    this->disconnect();
    this->set_error_flag(false);

    try {
        // First open with odd parity for initialization
        m_serial.open(device_path);
        m_serial.set_option(boost::asio::serial_port_base::parity(boost::asio::serial_port_base::parity::odd));
        m_serial.set_option(boost::asio::serial_port_base::character_size(8));
        m_serial.set_option(boost::asio::serial_port_base::flow_control::none);
        m_serial.set_option(boost::asio::serial_port_base::stop_bits::one);
        this->configure_baud(baud_rate);

        // Close and reopen with no parity
        m_serial.close();
        m_serial.open(device_path);
        m_serial.set_option(boost::asio::serial_port_base::parity(boost::asio::serial_port_base::parity::none));
        this->configure_baud(baud_rate);

        m_is_open = true;
        this->reset_hardware();
    }
    catch (boost::system::system_error&) {
        this->set_error_flag(true);
        return false;
    }

    m_line_number = 0;
    m_sent_history.clear();

#ifdef DEBUG_SERIAL
    debug_stream.open("serial.txt", std::fstream::out | std::fstream::trunc);
#endif

    boost::asio::post(m_io, [this]() { this->start_async_read(); });
    boost::thread worker_thread([this]() { m_io.run(); });
    m_worker.swap(worker_thread);

    return true;
}

void GCodeSender::configure_baud(unsigned int rate)
{
    try {
        m_serial.set_option(boost::asio::serial_port_base::baud_rate(rate));
    }
    catch (boost::system::system_error&) {
        auto handle = m_serial.native_handle();
#if __APPLE__
        termios ios;
        ::tcgetattr(handle, &ios);
        speed_t newSpeed = rate;
        ioctl(handle, IOSSIOSPEED, &newSpeed);
#elif __linux__
        termios2 ios;
        if (ioctl(handle, TCGETS2, &ios))
            fprintf(stderr, "Error in TCGETS2: %s\n", strerror(errno));
        ios.c_ispeed = ios.c_ospeed = rate;
        ios.c_cflag &= ~CBAUD;
        ios.c_cflag |= BOTHER | CLOCAL | CREAD;
        ios.c_cc[VMIN] = 1;
        ios.c_cc[VTIME] = 1;
        if (ioctl(handle, TCSETS2, &ios))
            fprintf(stderr, "Error in TCSETS2: %s\n", strerror(errno));
#elif __OpenBSD__
        struct termios ios;
        ::tcgetattr(handle, &ios);
        ::cfsetspeed(&ios, rate);
        if (::tcsetattr(handle, TCSAFLUSH, &ios) != 0)
            fprintf(stderr, "Failed to set baud rate: %s\n", strerror(errno));
#else
        // throw Slic3r::InvalidArgument("OS does not currently support custom bauds");
#endif
    }
}

void GCodeSender::disconnect()
{
    if (!m_is_open) return;

    m_is_open = false;
    m_is_connected = false;
    m_io.post([this]() { this->close_port(); });
    m_worker.join();
    m_io.reset();

#ifdef DEBUG_SERIAL
    debug_stream << "DISCONNECTED" << std::endl << std::flush;
    debug_stream.close();
#endif
}

bool GCodeSender::is_connected() const
{
    return m_is_connected;
}

bool GCodeSender::wait_connected(unsigned int timeout_seconds) const
{
    using namespace boost::posix_time;
    ptime deadline = second_clock::local_time() + seconds(timeout_seconds);
    while (!m_is_connected) {
        if (second_clock::local_time() > deadline)
            return false;
        boost::this_thread::sleep(boost::posix_time::milliseconds(100));
    }
    return true;
}

size_t GCodeSender::queue_length() const
{
    boost::lock_guard<boost::mutex> lock(m_mutex_queue);
    return m_queue_commands.size();
}

void GCodeSender::suspend_queue()
{
    boost::lock_guard<boost::mutex> lock(m_mutex_queue);
    m_queue_suspended = true;
}

void GCodeSender::resume_queue()
{
    {
        boost::lock_guard<boost::mutex> lock(m_mutex_queue);
        m_queue_suspended = false;
    }
    this->transmit_pending();
}

void GCodeSender::clear_queue(bool priority_only)
{
    boost::lock_guard<boost::mutex> lock(m_mutex_queue);
    if (priority_only) {
        decltype(m_queue_priority) empty_list;
        m_queue_priority.swap(empty_list);
    } else {
        decltype(m_queue_commands) empty_queue;
        m_queue_commands.swap(empty_queue);
        m_queue_suspended = false;
    }
}

std::vector<std::string> GCodeSender::flush_log()
{
    boost::lock_guard<boost::mutex> lock(m_mutex_log);
    std::vector<std::string> result;
    result.reserve(m_log_messages.size());
    while (!m_log_messages.empty()) {
        result.push_back(m_log_messages.front());
        m_log_messages.pop();
    }
    return result;
}

std::string GCodeSender::get_hotend_temp() const
{
    boost::lock_guard<boost::mutex> lock(m_mutex_log);
    return m_hotend_temp_str;
}

std::string GCodeSender::get_bed_temp() const
{
    boost::lock_guard<boost::mutex> lock(m_mutex_log);
    return m_bed_temp_str;
}

void GCodeSender::close_port()
{
    this->set_error_flag(false);
    boost::system::error_code ec;
    m_serial.cancel(ec);
    if (ec) this->set_error_flag(true);
    m_serial.close(ec);
    if (ec) this->set_error_flag(true);
}

void GCodeSender::set_error_flag(bool flag)
{
    boost::lock_guard<boost::mutex> lock(m_mutex_error);
    m_has_error = flag;
}

bool GCodeSender::has_error() const
{
    boost::lock_guard<boost::mutex> lock(m_mutex_error);
    return m_has_error;
}

void GCodeSender::start_async_read()
{
    boost::asio::async_read_until(m_serial, m_read_buffer, '\n',
        [this](const boost::system::error_code& err, size_t bytes) {
            this->handle_read(err, bytes);
        });
}

void GCodeSender::handle_read(const boost::system::error_code& error, size_t bytes_transferred)
{
    this->set_error_flag(false);
    if (error) {
#ifdef __APPLE__
        if (error.value() == 45) {
            this->start_async_read();
            return;
        }
#endif
        if (m_is_open) {
            this->close_port();
            this->set_error_flag(true);
        }
        return;
    }

    std::istream stream(&m_read_buffer);
    std::string line;
    std::getline(stream, line);

    if (!line.empty()) {
#ifdef DEBUG_SERIAL
        debug_stream << "<< " << line << std::endl << std::flush;
#endif

        // Detect connection status
        if (!m_is_connected && (
            boost::starts_with(line, "start") ||
            boost::starts_with(line, "Grbl ") ||
            boost::starts_with(line, "ok") ||
            boost::contains(line, "T:")
        )) {
            m_is_connected = true;
            {
                boost::lock_guard<boost::mutex> lock(m_mutex_queue);
                m_can_transmit = true;
            }
            this->transmit_pending();
        }
        else if (boost::starts_with(line, "ok")) {
            {
                boost::lock_guard<boost::mutex> lock(m_mutex_queue);
                m_can_transmit = true;
            }
            this->transmit_pending();
        }
        else if (boost::istarts_with(line, "resend") || boost::istarts_with(line, "rs")) {
            std::string trimmed = line;
            boost::algorithm::trim_left_if(trimmed, [](char c) { return !boost::algorithm::is_digit()(c); });
            size_t requested_line = boost::lexical_cast<size_t>(
                trimmed.substr(0, trimmed.find_first_not_of("0123456789"))
            );

#ifdef DEBUG_SERIAL
            debug_stream << "!! line num out of sync: req=" << requested_line
                         << ", sent=" << m_line_number
                         << ", history size=" << m_sent_history.size() << std::endl;
#endif

            size_t oldest_available = m_line_number - m_sent_history.size();
            if (requested_line > oldest_available && requested_line <= m_line_number) {
                size_t count_to_resend = m_line_number - requested_line + 1;
#ifdef DEBUG_SERIAL
                debug_stream << "!! resending " << count_to_resend << " lines" << std::endl;
#endif
                auto start_iter = m_sent_history.begin() + (m_sent_history.size() - count_to_resend);
                m_queue_priority.insert(m_queue_priority.begin(), start_iter, m_sent_history.end());
                m_sent_history.clear();
                m_line_number = requested_line - 1;
                {
                    boost::lock_guard<boost::mutex> lock(m_mutex_queue);
                    m_can_transmit = true;
                }
                this->transmit_pending();
            } else {
                fprintf(stderr, "Cannot resend %zu (oldest we have is %zu)\n", requested_line, oldest_available);
            }
        }
        else if (boost::starts_with(line, "wait")) {
            // ignore
        }
        else {
            boost::lock_guard<boost::mutex> lock(m_mutex_log);
            m_log_messages.push(line);
        }

        // Parse temperature info
        {
            size_t pos = line.find("T:");
            if (pos != std::string::npos && line.length() > pos + 2) {
                size_t end_pos = line.find_first_not_of("0123456789.", pos + 2);
                std::string temp_str = line.substr(pos + 2, end_pos - (pos + 2));
                {
                    boost::lock_guard<boost::mutex> lock(m_mutex_log);
                    m_hotend_temp_str = temp_str;
                }
                size_t bed_pos = line.find("B:");
                if (bed_pos != std::string::npos && line.length() > bed_pos + 2) {
                    size_t bed_end = line.find_first_not_of("0123456789.", bed_pos + 2);
                    m_bed_temp_str = line.substr(bed_pos + 2, bed_end - (bed_pos + 2));
                }
            }
        }
    }

    this->start_async_read();
}

void GCodeSender::submit(const std::vector<std::string>& commands, bool high_priority)
{
    boost::lock_guard<boost::mutex> lock(m_mutex_queue);
    for (const auto& cmd : commands) {
        if (high_priority)
            m_queue_priority.push_back(cmd);
        else
            m_queue_commands.push(cmd);
    }
    this->transmit_pending();
}

void GCodeSender::submit(const std::string& command, bool high_priority)
{
    boost::lock_guard<boost::mutex> lock(m_mutex_queue);
    if (high_priority)
        m_queue_priority.push_back(command);
    else
        m_queue_commands.push(command);
    this->transmit_pending();
}

void GCodeSender::transmit_pending()
{
    m_io.post([this]() { this->do_transmit(); });
}

void GCodeSender::do_transmit()
{
    boost::lock_guard<boost::mutex> lock(m_mutex_queue);

    if (!m_can_transmit) return;

    std::string next_command;
    while (!m_queue_priority.empty() || (!m_queue_commands.empty() && !m_queue_suspended)) {
        if (!m_queue_priority.empty()) {
            next_command = m_queue_priority.front();
            m_queue_priority.pop_front();
        } else {
            next_command = m_queue_commands.front();
            m_queue_commands.pop();
        }

        // Strip comments
        size_t comment_idx = next_command.find_first_of(';');
        if (comment_idx != std::string::npos)
            next_command.erase(comment_idx);

        boost::algorithm::trim(next_command);
        if (!next_command.empty())
            break;
    }

    if (next_command.empty()) return;

    ++m_line_number;

#ifndef DEBUG_SERIAL
    const auto current_line_num = m_line_number;
#else
    const auto current_line_num = (std::rand() < RAND_MAX / 4) ? 0 : m_line_number;
#endif

    std::string full_line = "N" + boost::lexical_cast<std::string>(current_line_num) + " " + next_command;

    // Compute checksum
    int checksum = 0;
    for (char c : full_line)
        checksum ^= static_cast<unsigned char>(c);

    full_line += "*" + boost::lexical_cast<std::string>(checksum) + "\n";

#ifdef DEBUG_SERIAL
    debug_stream << ">> " << full_line << std::flush;
#endif

    m_sent_history.push_back(next_command);
    m_can_transmit = false;

    while (m_sent_history.size() > MAX_HISTORY_LINES)
        m_sent_history.pop_front();

    std::ostream os(&m_write_buffer);
    os << full_line;

    boost::asio::async_write(m_serial, m_write_buffer,
        [this](const boost::system::error_code& err, size_t /*bytes*/) {
            this->on_write_complete(err);
        });
}

void GCodeSender::on_write_complete(const boost::system::error_code& error)
{
    this->set_error_flag(false);
    if (error) {
        if (m_is_open) {
            this->close_port();
            this->set_error_flag(true);
        }
        return;
    }
    this->do_transmit();
}

void GCodeSender::set_DTR(bool active)
{
#if defined(_WIN32) && !defined(__SYMBIAN32__)
    auto handle = m_serial.native_handle();
    if (active)
        EscapeCommFunction(handle, SETDTR);
    else
        EscapeCommFunction(handle, CLRDTR);
#else
    int fd = m_serial.native_handle();
    int status;
    ioctl(fd, TIOCMGET, &status);
    if (active)
        status |= TIOCM_DTR;
    else
        status &= ~TIOCM_DTR;
    ioctl(fd, TIOCMSET, &status);
#endif
}

void GCodeSender::reset_hardware()
{
    set_DTR(false);
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    set_DTR(true);
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    set_DTR(false);
    std::this_thread::sleep_for(std::chrono::milliseconds(500));
}

