#include "zonelabeltexturebuilder.h"
#include <QPainter>
#include <QPainterPath>
#include <QFont>
#include <QFontMetricsF>
#include "../../core/constants.h"

namespace PlasmaZones {
namespace {

// Grid unit constant — aligned with Kirigami.Units.gridUnit
constexpr int kGridUnit = 8;

// Determine outline color based on contrast between text and background
QColor computeContrastingOutline(const QColor& textColor, const QColor& bgColor)
{
    // Compute relative luminance using standard weights
    const qreal lum = textColor.redF() * 0.299 +
                      textColor.greenF() * 0.587 +
                      textColor.blueF() * 0.114;

    if (lum > 0.5) {
        // Darker outline for light text
        return QColor::fromRgbF(
            bgColor.redF() * 0.2,
            bgColor.greenF() * 0.2,
            bgColor.blueF() * 0.2,
            0.8
        );
    } else {
        // Lighter outline for dark text
        return QColor::fromRgbF(
            1.0 - bgColor.redF() * 0.2,
            1.0 - bgColor.greenF() * 0.2,
            1.0 - bgColor.blueF() * 0.2,
            0.8
        );
    }
}

} // anonymous namespace

QImage ZoneLabelTextureBuilder::build(const QVariantList& zones,
                                      const QSize& targetSize,
                                      const QColor& fontColor,
                                      bool displayNumbers,
                                      const QColor& bgCol,
                                      const QString& fontFamilyName,
                                      qreal scaleFactor,
                                      int fontWeightVal,
                                      bool italicStyle,
                                      bool underlineStyle,
                                      bool strikeoutStyle)
{
    // Early exit conditions: no drawing needed
    if (!displayNumbers || zones.isEmpty() ||
        targetSize.width() <= 0 || targetSize.height() <= 0) {
        return QImage();
    }

    QImage result(targetSize, QImage::Format_ARGB32_Premultiplied);
    result.fill(Qt::transparent);

    QPainter painter(&result);
    painter.setRenderHint(QPainter::Antialiasing);
    painter.setRenderHint(QPainter::TextAntialiasing);
    painter.setRenderHint(QPainter::SmoothPixmapTransform);

    const QColor borderCol = computeContrastingOutline(fontColor, bgCol);
    const QColor fillCol = fontColor;

    // Iterate over zones manually instead of range-based for
    int idx = 0;
    const int totalZones = zones.size();
    while (idx < totalZones) {
        const QVariant zoneData = zones.at(idx++);
        const QVariantMap zone = zoneData.toMap();

        const qreal xPos = zone.value(QLatin1String(JsonKeys::X), 0).toDouble();
        const qreal yPos = zone.value(QLatin1String(JsonKeys::Y), 0).toDouble();
        const qreal width = zone.value(QLatin1String(JsonKeys::Width), 0).toDouble();
        const qreal height = zone.value(QLatin1String(JsonKeys::Height), 0).toDouble();
        const int zoneId = zone.value(QLatin1String(JsonKeys::ZoneNumber), 0).toInt();

        // Skip invalid or zero-sized zones
        if (width <= 0 || height <= 0) {
            continue;
        }

        const QString label = QString::number(zoneId);
        const qreal minDim = qMin(width, height);
        const qreal fontSize = qMax(static_cast<qreal>(kGridUnit), minDim * 0.25) * scaleFactor;

        QFont currentFont;
        if (!fontFamilyName.isEmpty()) {
            currentFont.setFamily(fontFamilyName);
        }
        currentFont.setPixelSize(static_cast<int>(fontSize));
        currentFont.setWeight(static_cast<QFont::Weight>(qBound(100, fontWeightVal, 900)));
        currentFont.setItalic(italicStyle);

        const QRectF zoneRect(xPos, yPos, width, height);
        const QPointF centerPt = zoneRect.center();

        QPainterPath glyphPath;
        glyphPath.addText(0, 0, currentFont, label);
        const QRectF glyphBounds = glyphPath.boundingRect();

        // Adjust translation to center text within zone rectangle
        const qreal offsetX = centerPt.x() - glyphBounds.center().x();
        const qreal offsetY = centerPt.y() - glyphBounds.center().y();
        glyphPath.translate(offsetX, offsetY);

        // Draw stroke first, then fill
        const QPen borderPen(borderCol, 2.0, Qt::SolidLine, Qt::RoundCap, Qt::RoundJoin);
        painter.setPen(borderPen);
        painter.setBrush(Qt::NoBrush);
        painter.drawPath(glyphPath);

        painter.setPen(Qt::NoPen);
        painter.setBrush(fillCol);
        painter.drawPath(glyphPath);

        // Manually render text decorations if requested
        if (underlineStyle || strikeoutStyle) {
            const QFontMetricsF metrics(currentFont);
            const qreal strokeWidth = qMax(1.0, metrics.lineWidth());

            const qreal baseLineY = offsetY;
            const qreal startX = glyphBounds.left() + offsetX;
            const qreal endX = startX + glyphBounds.width();

            auto drawDecorationLine = [&](qreal verticalOffset) {
                const qreal yCenter = baseLineY + verticalOffset;
                const QRectF lineRect(startX, yCenter - strokeWidth / 2.0,
                                      endX - startX, strokeWidth);
                QPainterPath linePath;
                linePath.addRect(lineRect);

                painter.setPen(borderPen);
                painter.setBrush(Qt::NoBrush);
                painter.drawPath(linePath);

                painter.setPen(Qt::NoPen);
                painter.setBrush(fillCol);
                painter.drawPath(linePath);
            };

            if (underlineStyle) {
                drawDecorationLine(metrics.underlinePos());
            }
            if (strikeoutStyle) {
                drawDecorationLine(-metrics.strikeOutPos());
            }
        }
    }

    painter.end();
    return result;
}

} // namespace PlasmaZones

#include "quadrants/util/testing.h"
#include "quadrants/util/bit.h"

namespace quadrants {
namespace bit {

Bitset::Bitset() : vec_() {}

Bitset::Bitset(int n) {
  if (n % kBits != 0) {
    n += kBits - (n % kBits);
  }
  vec_.resize(n / kBits, 0);
}

std::size_t Bitset::size() const {
  return vec_.size() * kBits;
}

void Bitset::reset() {
  std::fill(vec_.begin(), vec_.end(), 0);
}

void Bitset::flip(int x) {
  vec_[x / kBits] ^= (static_cast<value_t>(1) << (x % kBits));
}

bool Bitset::any() const {
  for (const auto &val : vec_) {
    if (val != 0) return true;
  }
  return false;
}

bool Bitset::none() const {
  return !any();
}

Bitset::reference Bitset::operator[](int x) {
  return reference(vec_, x);
}

Bitset &Bitset::operator&=(const Bitset &other) {
  QD_ASSERT(vec_.size() == other.vec_.size());
  for (size_t i = 0; i < vec_.size(); ++i) {
    vec_[i] &= other.vec_[i];
  }
  return *this;
}

Bitset Bitset::operator&(const Bitset &other) const {
  Bitset temp(*this);
  temp &= other;
  return temp;
}

Bitset &Bitset::operator|=(const Bitset &other) {
  QD_ASSERT(vec_.size() == other.vec_.size());
  for (size_t i = 0; i < vec_.size(); ++i) {
    vec_[i] |= other.vec_[i];
  }
  return *this;
}

Bitset Bitset::operator|(const Bitset &other) const {
  Bitset temp(*this);
  temp |= other;
  return temp;
}

Bitset &Bitset::operator^=(const Bitset &other) {
  QD_ASSERT(vec_.size() == other.vec_.size());
  for (size_t i = 0; i < vec_.size(); ++i) {
    vec_[i] ^= other.vec_[i];
  }
  return *this;
}

Bitset Bitset::operator~() const {
  Bitset temp(size());
  for (size_t i = 0; i < vec_.size(); ++i) {
    temp.vec_[i] = ~vec_[i];
  }
  return temp;
}

int Bitset::find_first_one() const {
  return lower_bound(0);
}

int Bitset::lower_bound(int x) const {
  const int total_bits = static_cast<int>(vec_.size()) * kBits;
  if (x >= total_bits) return -1;
  if (x < 0) x = 0;

  int idx = x / kBits;
  int offset = x % kBits;

  if (offset != 0) {
    value_t mask = kMask ^ ((static_cast<value_t>(1) << offset) - 1);
    value_t masked = vec_[idx] & mask;
    if (masked) {
      return idx * kBits + log2int(lowbit(masked));
    }
    ++idx;
  }

  for (; idx < static_cast<int>(vec_.size()); ++idx) {
    if (vec_[idx]) {
      return idx * kBits + log2int(lowbit(vec_[idx]));
    }
  }

  return -1;
}

std::vector<int> Bitset::or_eq_get_update_list(const Bitset &other) {
  QD_ASSERT(vec_.size() == other.vec_.size());
  std::vector<int> updates;

  for (size_t i = 0; i < vec_.size(); ++i) {
    value_t new_bits = other.vec_[i] & ~vec_[i];
    if (new_bits) {
      vec_[i] |= new_bits;
      for (int j = 0; j < kBits; ++j) {
        if ((new_bits >> j) & 1) {
          updates.push_back(static_cast<int>(i * kBits + j));
        }
      }
    }
  }

  return updates;
}

Bitset::reference::reference(std::vector<value_t> &vec, int pos)
    : pos_(&vec[pos / kBits]),
      digit_(static_cast<value_t>(1) << (pos % kBits)) {}

Bitset::reference::operator bool() const {
  return (*pos_ & digit_) != 0;
}

bool Bitset::reference::operator~() const {
  return (*pos_ & digit_) == 0;
}

Bitset::reference &Bitset::reference::operator=(bool val) {
  if (val) {
    *pos_ |= digit_;
  } else {
    *pos_ &= (~digit_);
  }
  return *this;
}

Bitset::reference &Bitset::reference::operator=(
    const Bitset::reference &other) {
  *this = static_cast<bool>(other);
  return *this;
}

Bitset::reference &Bitset::reference::flip() {
  *pos_ ^= digit_;
  return *this;
}

std::ostream &operator<<(std::ostream &os, const Bitset &b) {
  for (auto val : b.vec_) {
    for (int i = 0; i < kBits; ++i) {
      os << ((val >> i) & 1 ? '1' : '0');
    }
  }
  return os;
}

