// Helper to count rows in DB using DuckDB API
auto CountDatabaseEntries(const std::filesystem::path& dbPath, const std::string& query) -> int64_t {
  duckdb_database   databaseHandle = nullptr;
  duckdb_connection connection     = nullptr;

  if (duckdb_open(dbPath.string().c_str(), &databaseHandle) != DuckDBSuccess) {
    return -1;
  }
  if (duckdb_connect(databaseHandle, &connection) != DuckDBSuccess) {
    duckdb_close(&databaseHandle);
    return -1;
  }

  int64_t       rowCount = -1;
  duckdb_result result;

  if (duckdb_query(connection, query.c_str(), &result) == DuckDBSuccess) {
    rowCount = duckdb_row_count(&result) > 0
                   ? duckdb_value_int64(&result, 0, 0)
                   : 0;
  }

  duckdb_destroy_result(&result);
  duckdb_disconnect(&connection);
  duckdb_close(&databaseHandle);

  return rowCount;
}

// Wait until import completes or timeout occurs
void AwaitImportCompletion(AlbumBackend& backend, int maxWaitMs = 30000) {
  QSignalSpy spy(&backend, &AlbumBackend::ImportStateChanged);
  constexpr int pollingInterval = 200;
  int elapsed = 0;

  while (backend.ImportRunning() && elapsed < maxWaitMs) {
    spy.wait(pollingInterval);
    elapsed += pollingInterval;
  }
  ProcessEvents(600);
}

// Create and load a new project from scratch
bool InitializeNewProject(AlbumBackend& backend,
                          const std::filesystem::path& dbPath,
                          const std::filesystem::path& metaPath) {
  {
    ProjectService project(dbPath, metaPath, ProjectOpenMode::kCreateNew);
    project.SaveProject(metaPath);
  }

  QSignalSpy projectChangeSpy(&backend, &AlbumBackend::ProjectChanged);
  if (!backend.LoadProject(PathToQString(metaPath))) {
    return false;
  }

  WaitForSignal(projectChangeSpy, 15000);
  ProcessEvents(500);
  return backend.ServiceReady();
}

TEST_F(DeleteTests, DeleteImages_RemovesImageAndRelatedRows) {
  sl_element_id_t removedElementId = 0;
  image_id_t      removedImageId   = 0;
  QVariantMap     deleteResult;
  int             visibleCountPostDeletion = -1;

  {
    AlbumBackend backend;
    ASSERT_TRUE(InitializeNewProject(backend, db_path_, meta_path_));

    auto rawImages = CollectRawTestImages("airplane", 1);
    if (rawImages.empty()) {
      GTEST_SKIP() << "No RAW images available in raw/airplane/";
    }

    backend.StartImport(PathsToQStringList(rawImages));
    AwaitImportCompletion(backend);

    ASSERT_FALSE(backend.Thumbnails().isEmpty());

    const QVariantMap firstThumbnail = backend.Thumbnails().front().toMap();
    removedElementId = static_cast<sl_element_id_t>(firstThumbnail.value("elementId").toUInt());
    removedImageId   = static_cast<image_id_t>(firstThumbnail.value("imageId").toUInt());

    ASSERT_NE(removedElementId, 0u);
    ASSERT_NE(removedImageId, 0u);

    // Open editor to ensure pipeline/history entries are persisted
    backend.OpenEditor(static_cast<uint>(removedElementId), static_cast<uint>(removedImageId));
    ProcessEvents(400);

    QVariantList deletionTargets;
    deletionTargets.push_back(QVariantMap{
        {"elementId", static_cast<uint>(removedElementId)},
        {"imageId", static_cast<uint>(removedImageId)}
    });

    deleteResult = backend.DeleteImages(deletionTargets);
    ProcessEvents(500);

    visibleCountPostDeletion = backend.ShownCount();
  }

  EXPECT_TRUE(deleteResult.value("success").toBool());
  EXPECT_EQ(deleteResult.value("deletedCount").toInt(), 1);
  EXPECT_EQ(deleteResult.value("failedCount").toInt(), 0);
  EXPECT_EQ(visibleCountPostDeletion, 0);

  EXPECT_EQ(CountDatabaseEntries(db_path_, std::format("SELECT COUNT(*) FROM Image WHERE id={}", removedImageId)), 0);
  EXPECT_EQ(CountDatabaseEntries(db_path_, std::format("SELECT COUNT(*) FROM FileImage WHERE file_id={}", removedElementId)), 0);
  EXPECT_EQ(CountDatabaseEntries(db_path_, std::format("SELECT COUNT(*) FROM EditHistory WHERE file_id={}", removedElementId)), 0);
  EXPECT_EQ(CountDatabaseEntries(db_path_, std::format("SELECT COUNT(*) FROM PipelineParam WHERE file_id={}", removedElementId)), 0);
}

