// Helper wrapper for managing Java byte arrays in scope
class JByteArrayGuard
{
  JNIEnv* m_env;
  jbyteArray m_array;

public:
  JByteArrayGuard(JNIEnv* env) : m_env(env), m_array(nullptr) {}

  void Assign(jsize size, std::string const& data)
  {
    if (size > 0)
    {
      m_array = m_env->NewByteArray(size);
      if (m_array)
        m_env->SetByteArrayRegion(m_array, 0, size,
                                  reinterpret_cast<jbyte const*>(data.c_str()));
    }
  }

  jbyteArray Get() const { return m_array; }

  ~JByteArrayGuard()
  {
    if (m_array)
      m_env->DeleteLocalRef(m_array);
  }
};

// Internal representation of an active HTTP chunk task
class HttpChunkExecutor
{
  jobject m_javaTask;
  jclass m_taskClass;

public:
  HttpChunkExecutor(std::string const& url,
                    downloader::IHttpThreadCallback& callback,
                    int64_t startOffset,
                    int64_t endOffset,
                    int64_t expectedSize,
                    std::string const& postData)
  {
    JNIEnv* env = jni::GetEnv();
    static jclass const taskClassRef = jni::GetGlobalClassRef(env, "app/organicmaps/sdk/downloader/ChunkTask");
    m_taskClass = taskClassRef;

    // Prepare Java String and byte array arguments
    jni::TScopedLocalRef<jstring> jUrl(env, jni::ToJavaString(env, url.c_str()));
    JByteArrayGuard jPostBody(env);
    jsize const postBodyLen = static_cast<jsize>(postData.size());
    jPostBody.Assign(postBodyLen, postData);

    // Constructor: ChunkTask(long, String, long, long, long, byte[], String)
    static jmethodID const ctorId = jni::GetConstructorID(env, taskClassRef,
                                                          "(JLjava/lang/String;JJJ[B)V");
    static jmethodID const startMethod = env->GetMethodID(taskClassRef, "start", "()V");

    // Instantiate Java object and store global reference
    m_javaTask = env->NewObject(taskClassRef, ctorId,
                                reinterpret_cast<jlong>(&callback),
                                jUrl.get(),
                                static_cast<jlong>(startOffset),
                                static_cast<jlong>(endOffset),
                                static_cast<jlong>(expectedSize),
                                jPostBody.Get());
    ASSERT(m_javaTask, ("Failed to create ChunkTask instance"));

    m_javaTask = env->NewGlobalRef(m_javaTask);
    env->CallVoidMethod(m_javaTask, startMethod);
  }

  ~HttpChunkExecutor()
  {
    JNIEnv* env = jni::GetEnv();
    static jmethodID const cancelMethod = env->GetMethodID(m_taskClass, "cancel", "(Z)Z");
    env->CallBooleanMethod(m_javaTask, cancelMethod, false);
    env->DeleteGlobalRef(m_javaTask);
  }
};

