extern "C" {

JNIEXPORT jboolean JNICALL Java_app_organicmaps_sdk_downloader_ChunkTask_nativeOnWrite(
    JNIEnv* env, jclass clazz,
    jlong callbackPtr,
    jlong offset,
    jbyteArray dataArray,
    jlong length)
{
  auto* cb = reinterpret_cast<downloader::IHttpThreadCallback*>(callbackPtr);
  if (!cb)
    return false;

  jbyte* buffer = env->GetByteArrayElements(dataArray, nullptr);
  if (!buffer)
    return false;

  bool success = false;
  try
  {
    success = cb->OnWrite(offset, buffer, static_cast<jsize>(length));
  }
  catch (std::exception const& ex)
  {
    LOG(LERROR, ("Exception during OnWrite:", ex.what()));
  }

  env->ReleaseByteArrayElements(dataArray, buffer, JNI_ABORT);
  return success;
}

JNIEXPORT void JNICALL Java_app_organicmaps_sdk_downloader_ChunkTask_nativeOnFinish(
    JNIEnv* env, jclass clazz,
    jlong callbackPtr,
    jlong httpStatus,
    jlong startRange,
    jlong endRange)
{
  auto* cb = reinterpret_cast<downloader::IHttpThreadCallback*>(callbackPtr);
  if (cb)
    cb->OnFinish(static_cast<long>(httpStatus), startRange, endRange);
}

} // extern "C"

