using namespace small_gicp;

class HelperTest : public testing::Test, public testing::WithParamInterface<const char*> {
public:
  void SetUp() override {
    // Load point clouds from PLY files
    target_raw = std::make_shared<PointCloud>(read_ply("data/target.ply"));
    source_raw = std::make_shared<PointCloud>(read_ply("data/source.ply"));

    // Load transformation matrix from text file
    std::ifstream ifs("data/T_target_source.txt");
    if (!ifs) {
      std::cerr << "error: failed to open T_target_source.txt" << std::endl;
    }
    for (int row = 0; row < 4; ++row) {
      for (int col = 0; col < 4; ++col) {
        ifs >> T_target_source(row, col);
      }
    }
  }

  // Compare two transformations with tolerance thresholds
  bool compare_transforms(const Eigen::Isometry3d& T1, const Eigen::Isometry3d& T2) {
    const Eigen::Isometry3d diff = T1.inverse() * T2;
    const double rot_error = Eigen::AngleAxisd(diff.linear()).angle();
    const double trans_error = diff.translation().norm();
    constexpr double ROT_TOL = 2.5 * M_PI / 180.0;
    constexpr double TRANS_TOL = 0.2;

    EXPECT_NEAR(rot_error, 0.0, ROT_TOL);
    EXPECT_NEAR(trans_error, 0.0, TRANS_TOL);

    return (rot_error < ROT_TOL) && (trans_error < TRANS_TOL);
  }

protected:
  PointCloud::Ptr target_raw;         ///< Target point cloud
  PointCloud::Ptr source_raw;         ///< Source point cloud
  Eigen::Isometry3d T_target_source;  ///< Ground truth transform from source to target
};

// Basic loading verification
TEST_F(HelperTest, LoadCheck) {
  ASSERT_FALSE(target_raw->empty());
  ASSERT_FALSE(source_raw->empty());
}

// Test preprocessing on empty input
