TEST_P(HelperTest, AlignEigen) {
  const std::string method = GetParam();
  RegistrationSetting setting;

  if (method == "ICP") {
    setting.type = RegistrationSetting::ICP;
  } else if (method == "PLANE_ICP") {
    setting.type = RegistrationSetting::PLANE_ICP;
  } else if (method == "GICP") {
    setting.type = RegistrationSetting::GICP;
  } else if (method == "VGICP") {
    setting.type = RegistrationSetting::VGICP;
  } else {
    std::cerr << "error: unknown registration method " << method << std::endl;
  }

  // Forward alignment: target -> source
  auto result_fwd = align(target_raw->points, source_raw->points, Eigen::Isometry3d::Identity(), setting);
  EXPECT_TRUE(compare_transforms(T_target_source, result_fwd.T_target_source));

  // Backward alignment: source -> target
  auto result_bwd = align(source_raw->points, target_raw->points, Eigen::Isometry3d::Identity(), setting);
  EXPECT_TRUE(compare_transforms(T_target_source, result_bwd.T_target_source.inverse()));
