    setting.type = RegistrationSetting::VGICP;
  } else {
    std::cerr << "error: unknown registration method " << method << std::endl;
  }

  // Preprocess both clouds
  auto [target_preproc, target_kdtree] = preprocess_points(*target_raw, 0.1, 10, 1);
  auto [source_preproc, source_kdtree] = preprocess_points(*source_raw, 0.1, 10, 1);

  RegistrationResult result;

  // Forward alignment
  if (method != "VGICP") {
    result = align(*target_preproc, *source_preproc, *target_kdtree, Eigen::Isometry3d::Identity(), setting);
  } else {
