  if (method != "VGICP") {
    result = align(*source_preproc, *target_preproc, *source_kdtree, Eigen::Isometry3d::Identity(), setting);
  } else {
    auto source_voxelmap = create_gaussian_voxelmap(*source_preproc, 1.0);
    result = align(*source_voxelmap, *target_preproc, Eigen::Isometry3d::Identity(), setting);
  }
