#include "humanoid_controllers/humanoidController.h"
#include <thread>
#include <chrono>
#include <ctime>
#include <iostream>

// Global flag to control execution pause state
bool isPaused = false;

// Callback to toggle pause state based on incoming message
void onPauseCommand(const std_msgs::Bool::ConstPtr& msg)
{
    isPaused = msg->data;
    std::cerr << "[PAUSE] State changed to: " << (isPaused ? "PAUSED" : "RUNNING") << std::endl;
}

int main(int argc, char** argv)
{
    ros::init(argc, argv, "humanoid_controller_node");
    ros::NodeHandle nh;

    // Declare robot hardware interface pointer (will be assigned later)
    humanoid_controller::HybridJointInterface* robot_hw = nullptr;

    // Subscribe to pause commands
    ros::Subscriber pause_sub = nh.subscribe<std_msgs::Bool>("pauseFlag", 1, onPauseCommand);

    // Instantiate controller
    humanoid_controller::humanoidCheaterController controller;

    // Initialize controller; exit if failed
    if (!controller.init(robot_hw, nh))
    {
        ROS_ERROR("Failed to initialize humanoid controller!");
        return -1;
    }

    // Record start times for both high-res clock and ROS time
    auto systemStart = std::chrono::high_resolution_clock::now();
    auto rosStart = ros::Time::now();

    // Notify controller of startup
    controller.starting(rosStart);

    // Set up timing variables
    double desiredHz = 500.0;
    nh.getParam("/wbc_frequency", desiredHz);
    std::cout << "[INFO] WBC Control frequency set to: " << desiredHz << " Hz" << std::endl;

    const double period_sec = 1.0 / desiredHz;
    auto lastCycleStart = systemStart;

    // Start ROS spinning in background thread
    std::thread spinner([]()
                        { ros::spin(); });
    spinner.detach();

    // Timing loop
    while (ros::ok())
    {
        if (!isPaused)
        {
            auto now = std::chrono::high_resolution_clock::now();
            auto elapsed = std::chrono::duration<double>(now - lastCycleStart).count();
            ros::Duration dt(elapsed);

            // Update controller
            controller.update(ros::Time::now(), dt);

            // Compute next target time for periodic execution
            auto targetTime = lastCycleStart + std::chrono::duration_cast<decltype(now)::duration>(
                std::chrono::duration<double>(period_sec));

            // Sleep until target time (or minimal sleep if already passed)
            if (targetTime > now)
            {
                std::this_thread::sleep_until(targetTime);
            }

            // Update tracking timestamp
            lastCycleStart = std::chrono::high_resolution_clock::now();

            // Diagnostic logging for large cycle delays
            auto cycleEnd = std::chrono::high_resolution_clock::now();
            auto actualCycleMs = std::chrono::duration_cast<std::chrono::milliseconds>(cycleEnd - now).count();
            if (actualCycleMs > 1000)
            {
                ROS_WARN_STREAM("[WARNING] Cycle took too long: " << actualCycleMs << " ms");
                auto procTimeMs = std::chrono::duration_cast<std::chrono::milliseconds>(now - lastCycleStart).count();
                auto sleepTimeMs = std::chrono::duration_cast<std::chrono::milliseconds>(targetTime - now).count();
                ROS_INFO_STREAM("  -> Processing time: " << procTimeMs << " ms");
                ROS_INFO_STREAM("  -> Intended sleep duration: " << sleepTimeMs << " ms");
            }
        }
        else
        {
            // Brief sleep when paused to avoid busy-waiting
            std::this_thread::sleep_for(std::chrono::milliseconds(10));
        }
    }

    return 0;
}

