GfVec4i ConvertToVec4i(GfVec4d const& inputVector)
{
    return GfVec4i(static_cast<int>(inputVector[0]),
                   static_cast<int>(inputVector[1]),
                   static_cast<int>(inputVector[2]),
                   static_cast<int>(inputVector[3]));
}

bool IsUsingStormRenderDelegate(HdRenderIndex const* renderIdx)
{
    auto const* delegate = renderIdx->GetRenderDelegate();
    return dynamic_cast<HdStRenderDelegate*>(delegate) != nullptr;
}

TfToken DetermineRenderingBackend(HdRenderIndex const* renderIdx)
{
    HdDriverVector const& drivers = renderIdx->GetDrivers();

    auto const foundIt = std::find_if(drivers.begin(), drivers.end(),
        [](HdDriver* drv) -> bool {
            return drv->name == HgiTokens->renderDriver &&
                   drv->driver.IsHolding<Hgi*>();
        });

    if (foundIt != drivers.end())
    {
        return (*foundIt)->driver.UncheckedGet<Hgi*>()->GetAPIName();
    }

    return HgiTokens->OpenGL;
}

void ConfigureBlendStateForMaterialTag(TfToken const& materialTag, HdxRenderTaskParams& params)
{
    // Additive blending setup
    if (materialTag == HdStMaterialTagTokens->additive)
    {
        params.blendEnable               = true;
        params.blendColorOp              = HdBlendOpAdd;
        params.blendColorSrcFactor       = HdBlendFactorOne;
        params.blendColorDstFactor       = HdBlendFactorOne;
        params.blendAlphaOp              = HdBlendOpAdd;
        params.blendAlphaSrcFactor       = HdBlendFactorZero;
        params.blendAlphaDstFactor       = HdBlendFactorOne;
        params.depthMaskEnable           = false;
        params.enableAlphaToCoverage     = false;
    }
    // Draw order blending setup
    else if (materialTag == HdStMaterialTagTokens->draworder)
    {
        params.blendEnable               = true;
        params.blendColorOp              = HdBlendOpAdd;
        params.blendColorSrcFactor       = HdBlendFactorSrcAlpha;
        params.blendColorDstFactor       = HdBlendFactorOneMinusSrcAlpha;
        params.blendAlphaOp              = HdBlendOpAdd;
        params.blendAlphaSrcFactor       = HdBlendFactorOne;
        params.blendAlphaDstFactor       = HdBlendFactorZero;
        params.depthMaskEnable           = false;
        params.enableAlphaToCoverage     = false;
    }
    // Default / masked materials
    else if (materialTag == HdStMaterialTagTokens->defaultMaterialTag ||
             materialTag == HdStMaterialTagTokens->masked)
    {
        params.blendEnable               = false;
        params.depthMaskEnable           = true;
        params.enableAlphaToCoverage     = true;
    }
}

SdfPath ConstructRenderTaskPath(SdfPath const& controllerId, TfToken const& tag)
{
    TfToken leafName = GenerateRenderTaskLeafName(tag);
    return controllerId.AppendChild(leafName);
}

TfToken GenerateRenderTaskLeafName(TfToken const& materialTag)
{
    std::ostringstream oss;
    oss << "renderTask_" << materialTag.GetText();
    std::string nameStr = oss.str();
    for (char& c : nameStr)
    {
        if (c == ':')
            c = '_';
    }
    return TfToken(nameStr);
}

SdfPath BuildAovIdentifier(SdfPath const& parentPath, TfToken const& aovName)
{
    std::string sanitized = TfMakeValidIdentifier(aovName.GetString());
    std::string fullId = "aov_" + sanitized;
    return parentPath.AppendChild(TfToken(fullId));
}

HdRprimCollection CreateDefaultRprimCollection(
    BasicLayerParams const* layerSettings, TfToken const& materialTag)
{
    HdRprimCollection collection = layerSettings->collection;
    collection.SetMaterialTag(materialTag);
    return collection;
}

bool ShouldClearAovs(TaskManager const& tmgr,
                     TfToken const& taskName,
                     RenderBufferSettingsProvider const& rbSettings)
{
    SdfPathVector renderTasks;
    tmgr.GetTaskPaths(TaskFlagsBits::kRenderTaskBit, true, renderTasks);

    bool firstTask = !renderTasks.empty() && renderTasks[0].GetNameToken() == taskName;

    if (firstTask && rbSettings.IsProgressiveRenderingEnabled())
    {
        firstTask = rbSettings.GetAovParamCache().hasNoAovInputs;
    }

    return firstTask;
}

bool SupportsMsaa(TfToken const& materialTag)
{
    return materialTag != HdStMaterialTagTokens->translucent &&
           materialTag != HdStMaterialTagTokens->volume;
}

TfToken RetrieveFirstRenderTaskName(TaskManager const& tmgr)
{
    SdfPathVector renderTasks;
    tmgr.GetTaskPaths(TaskFlagsBits::kRenderTaskBit, true, renderTasks);
    return renderTasks.empty() ? TfToken{} : renderTasks[0].GetNameToken();
}

HdRenderPassAovBindingVector PrepareAovBindings(TaskManager const& tmgr,
                                                TfToken const& taskName,
                                                RenderBufferSettingsProvider const& rbSettings)
{
    AovParams const& aovParams = rbSettings.GetAovParamCache();
    bool const shouldClear = ShouldClearAovs(tmgr, taskName, rbSettings);

    HdRenderPassAovBindingVector bindings =
        shouldClear ? aovParams.aovBindingsClear : aovParams.aovBindingsNoClear;

    for (size_t idx = 0; idx < bindings.size(); ++idx)
    {
        auto const& bufId = bindings[idx].renderBufferId;
        auto it = aovParams.outputClearValues.find(bufId);
        if (it != aovParams.outputClearValues.end())
        {
            bindings[idx].clearValue = shouldClear ? it->second : VtValue{};
        }
    }

    return bindings;
}
