// Verify that two containers hold the same elements in the same order
template <typename T>
bool are_equal(const std::vector<T>& vec1, const std::vector<T>& vec2) {
  if (vec1.size() != vec2.size()) {
    return false;
  }
  for (size_t idx = 0; idx < vec1.size(); ++idx) {
    if (vec1[idx] != vec2[idx]) {
      return false;
    }
  }
  return true;
}

// Generic test function for radix sort using TBB backend
template <typename ValueType>
void validate_radix_sort_behavior(std::mt19937& rng_engine) {
  std::uniform_int_distribution<int> size_generator(0, 8192);

  // Test case 1: Sort raw values
  for (int trial = 0; trial < 20; ++trial) {
    std::vector<ValueType> input(size_generator(rng_engine));
    std::generate(input.begin(), input.end(), [&rng_engine] { return rng_engine(); });

    std::vector<ValueType> reference = input;
    std::stable_sort(reference.begin(), reference.end());

    std::vector<ValueType> tbb_result = input;
    radix_sort_tbb(tbb_result.data(), tbb_result.data() + tbb_result.size(),
                   [](ValueType val) { return val; });

    EXPECT_TRUE(are_equal(reference, tbb_result))
        << fmt::format("Trial {} failed with N={}", trial, input.size());
  }

  // Test case 2: Sort pairs by first element
  for (int trial = 0; trial < 20; ++trial) {
    using PairType = std::pair<ValueType, std::uint64_t>;
    std::vector<PairType> input(size_generator(rng_engine));
    std::generate(input.begin(), input.end(), [&rng_engine] {
      return std::make_pair<ValueType, std::uint64_t>(rng_engine(), rng_engine());
    });

    std::vector<PairType> reference = input;
    std::stable_sort(reference.begin(), reference.end(),
                     [](const auto& a, const auto& b) { return a.first < b.first; });

    std::vector<PairType> tbb_result = input;
    radix_sort_tbb(tbb_result.data(), tbb_result.data() + tbb_result.size(),
                   [](const PairType& p) -> ValueType { return p.first; });

    EXPECT_TRUE(are_equal(reference, tbb_result))
        << fmt::format("Pair test trial {} failed with N={}", trial, input.size());
  }
}

// Unit test suite for TBB-based radix sort
TEST(SortTBB, RadixSortValidation) {
  std::mt19937 engine;
  validate_radix_sort_behavior<std::uint8_t>(engine);
  validate_radix_sort_behavior<std::uint16_t>(engine);
  validate_radix_sort_behavior<std::uint32_t>(engine);
  validate_radix_sort_behavior<std::uint64_t>(engine);

  // Edge case: empty range
  std::vector<std::uint64_t> empty_data;
  radix_sort_tbb(empty_data.data(), empty_data.data() + empty_data.size(),
                 [](std::uint64_t x) { return x; });
  EXPECT_TRUE(empty_data.empty()) << "Empty vector should remain unchanged";
}

