#define ALLOCA dALLOCA16

//****************************************************************************
// Auto disabling logic — handles idle body detection and auto-disabling
void dInternalHandleAutoDisabling(dxWorld *world, dReal timestep)
{
    dxBody *currentBody = world->firstbody;
    while (currentBody) {
        // Skip unless body is enabled and has auto-disable flag set
        if ((currentBody->flags & (dxBodyAutoDisable | dxBodyDisabled)) != dxBodyAutoDisable) {
            currentBody = (dxBody*)currentBody->next;
            continue;
        }

        bool isIdle = true;

        // Check linear speed
        dReal linSpeedSq = dDOT(currentBody->lvel, currentBody->lvel);
        if (linSpeedSq > currentBody->adis.linear_threshold) {
            isIdle = false;
        }
        else {
            // Check angular speed
            dReal angSpeedSq = dDOT(currentBody->avel, currentBody->avel);
            if (angSpeedSq > currentBody->adis.angular_threshold) {
                isIdle = false;
            }
        }

        // Update idle counters
        if (isIdle) {
            --(currentBody->adis_stepsleft);
            currentBody->adis_timeleft -= timestep;
        }
        else {
            currentBody->adis_stepsleft = currentBody->adis.idle_steps;
            currentBody->adis_timeleft = currentBody->adis.idle_time;
        }

        // Disable if idle duration exceeded both step and time thresholds
        if (currentBody->adis_stepsleft < 0 && currentBody->adis_timeleft < 0) {
            currentBody->flags |= dxBodyDisabled;
        }

        currentBody = (dxBody*)currentBody->next;
    }
}

//****************************************************************************
// Sinc function: sin(x)/x with special handling near zero
static inline dReal sinc(dReal angle)
{
    if (dFabs(angle) < 1.0e-4) {
        return REAL(1.0) - angle * angle * REAL(0.166666666666666666667);
    }
    return dSin(angle) / angle;
}

//****************************************************************************
// Integrate body motion over one timestep
void dxStepBody(dxBody *body, dReal h)
{
    int idx;

    // Linear position update
    for (idx = 0; idx < 3; ++idx) {
        body->pos[idx] += h * body->lvel[idx];
    }

    if (body->flags & dxBodyFlagFiniteRotation) {
        dVector3 rotVecInf;     // Infinitesimal rotation part
        dQuaternion qStep;      // Finite rotation quaternion

        if (body->flags & dxBodyFlagFiniteRotationAxis) {
            // Decompose angular velocity into parallel/perpendicular components
            dVector3 frv;         // Finite rotation vector (along axis)
            dReal proj = dDOT(body->finite_rot_axis, body->avel);
            frv[0] = body->finite_rot_axis[0] * proj;
            frv[1] = body->finite_rot_axis[1] * proj;
            frv[2] = body->finite_rot_axis[2] * proj;

            rotVecInf[0] = body->avel[0] - frv[0];
            rotVecInf[1] = body->avel[1] - frv[1];
            rotVecInf[2] = body->avel[2] - frv[2];

            // Build finite rotation quaternion
            h *= REAL(0.5);
            dReal theta = proj * h;
            qStep[0] = dCos(theta);
            dReal scale = sinc(theta) * h;
            qStep[1] = frv[0] * scale;
            qStep[2] = frv[1] * scale;
            qStep[3] = frv[2] * scale;
        }
        else {
            // Full finite rotation from angular velocity magnitude
            dReal wLen = dSqrt(
                body->avel[0] * body->avel[0] +
                body->avel[1] * body->avel[1] +
                body->avel[2] * body->avel[2]
            );
            h *= REAL(0.5);
            dReal theta = wLen * h;
            qStep[0] = dCos(theta);
            dReal scale = sinc(theta) * h;
            qStep[1] = body->avel[0] * scale;
            qStep[2] = body->avel[1] * scale;
            qStep[3] = body->avel[2] * scale;
        }

        // Apply finite rotation
        dQuaternion qNew;
        dQMultiply0(qNew, qStep, body->q);
        for (idx = 0; idx < 4; ++idx) body->q[idx] = qNew[idx];

        // Add infinitesimal correction if needed
        if (body->flags & dxBodyFlagFiniteRotationAxis) {
            dReal dq[4];
            dWtoDQ(rotVecInf, body->q, dq);
            for (idx = 0; idx < 4; ++idx) body->q[idx] += h * dq[idx];
        }
    }
    else {
        // Standard infinitesimal rotation
        dReal dq[4];
        dWtoDQ(body->avel, body->q, dq);
        for (idx = 0; idx < 4; ++idx) body->q[idx] += h * dq[idx];
    }

    // Normalize and convert to matrix
    dNormalize4(body->q);
    dQtoR(body->q, body->R);

    // Notify attached geoms of movement
    for (dxGeom *geom = body->geom; geom; geom = dGeomGetBodyNext(geom)) {
        dGeomMoved(geom);
    }
}

//****************************************************************************
// Island processing: group connected bodies/joints for separate simulation
void dxProcessIslands(dxWorld *world, dReal stepsize, dstepper_fn_t stepper)
{
    dxBody *b, *bb;
    dxJoint *j;

    if (world->nb <= 0) return;

    // Handle auto-disabling before island formation
    dInternalHandleAutoDisabling(world, stepsize);

    // Allocate temporary arrays for island bodies and joints
    dxBody **bodyList = (dxBody**) ALLOCA(world->nb * sizeof(dxBody*));
    dxJoint **jointList = (dxJoint**) ALLOCA(world->nj * sizeof(dxJoint*));

    int bodyCount = 0;
    int jointCount = 0;

    // Reset tags
    for (b = world->firstbody; b; b = (dxBody*)b->next) b->tag = 0;
    for (j = world->firstjoint; j; j = (dxJoint*)j->next) j->tag = 0;

    // Stack allocation for DFS traversal
    int maxStack = (world->nj < world->nb) ? world->nj : world->nb;
    dxBody **stack = (dxBody**) ALLOCA(maxStack * sizeof(dxBody*));

    // Traverse each unvisited enabled body as root of new island
    for (bb = world->firstbody; bb; bb = (dxBody*)bb->next) {
        if (bb->tag || (bb->flags & dxBodyDisabled)) continue;

        bb->tag = 1;
        bodyList[0] = bb;
        bodyCount = 1;
        jointCount = 0;

        int stackSize = 0;
        b = bb;

        do {
            // Pop body from stack
            if (stackSize > 0) {
                b = stack[--stackSize];
                bodyList[bodyCount++] = b;
            }

            // Explore joints connected to current body
            for (dxJointNode *node = b->firstjoint; node; node = node->next) {
                if (!node->joint->tag) {
                    node->joint->tag = 1;
                    jointList[jointCount++] = node->joint;

                    // Push unvisited connected bodies onto stack
                    if (node->body && !node->body->tag) {
                        node->body->tag = 1;
                        stack[stackSize++] = node->body;
                    }
                }
            }

            dIASSERT(stackSize <= world->nb);
            dIASSERT(stackSize <= world->nj);
        } while (stackSize > 0);

        // Run solver on this island
        stepper(world, bodyList, bodyCount, jointList, jointCount, stepsize);

        // Ensure all processed objects are marked active
        for (int i = 0; i < bodyCount; ++i) {
            bodyList[i]->tag = 1;
            bodyList[i]->flags &= ~dxBodyDisabled;
        }
        for (int i = 0; i < jointCount; ++i) {
            jointList[i]->tag = 1;
        }
    }

#ifndef dNODEBUG
    // Debug validation: verify tagging correctness
    for (b = world->firstbody; b; b = (dxBody*)b->next) {
        if (b->flags & dxBodyDisabled) {
            if (b->tag) dDebug(0, "disabled body tagged");
        }
        else {
            if (!b->tag) dDebug(0, "enabled body not tagged");
        }
    }

    for (j = world->firstjoint; j; j = (dxJoint*)j->next) {
        bool attachedToActiveBody =
            (j->node[0].body && !(j->node[0].body->flags & dxBodyDisabled)) ||
            (j->node[1].body && !(j->node[1].body->flags & dxBodyDisabled));

        if (attachedToActiveBody) {
            if (!j->tag) dDebug(0, "attached enabled joint not tagged");
        }
        else {
            if (j->tag) dDebug(0, "unattached or disabled joint tagged");
        }
    }
#endif
}

