        // Helper to build font with optional Cyrillic support
        ImFont* BuildFontWithCyrillicSupport(ImGuiIO& io,
                                             const std::uint8_t* fontData,
                                             std::size_t dataSize,
                                             float fontSize,
                                             const char* fallbackFontPath = nullptr)
        {
            ImFontConfig cfg{};
            cfg.FontDataOwnedByAtlas = false;

            auto primary = io.Fonts->AddFontFromMemoryTTF(const_cast<std::uint8_t*>(fontData), static_cast<int>(dataSize), fontSize, &cfg, io.Fonts->GetGlyphRangesDefault());

            if (fallbackFontPath && std::filesystem::exists(fallbackFontPath))
            {
                cfg.MergeMode = true;
                io.Fonts->AddFontFromFileTTF(fallbackFontPath, fontSize, &cfg, GetGlyphRangesCyrillicOnly());
            }

            io.Fonts->Build();
            return primary;
        }

        // Predefined Cyrillic ranges (unchanged semantics)
        const ImWchar* GetCyrillicRanges()
        {
            static const ImWchar rangeTable[] =
            {
                0x0400, 0x052F, // Basic Cyrillic + Supplement
                0x2DE0, 0x2DFF, // Extended A
                0xA640, 0xA69F, // Extended B
                0
            };
            return rangeTable;
        }
    }

    void Menu::Initialize()
    {
        ApplyStyleSettings();

