        menuList.emplace_back(std::make_shared<Submenus::Vehicle>());
        menuList.emplace_back(std::make_shared<Submenus::Teleport>());
        menuList.emplace_back(std::make_shared<Submenus::Network>());
        menuList.emplace_back(std::make_shared<Submenus::Players>());
        menuList.emplace_back(std::make_shared<Submenus::World>());
        menuList.emplace_back(std::make_shared<Submenus::Recovery>());
        menuList.emplace_back(std::make_shared<Submenus::Settings>());
        menuList.emplace_back(std::make_shared<Submenus::Debug>());

        for (auto& menu : menuList)
            UIManager::AddSubmenu(std::move(menu));

        // Register render callback with explicit name
        auto renderCallback = [&]()
        {
            HandleOnboardingStep();
            if (!GUI::IsOpen())
                return;

            ImGui::PushFont(Font::g_DefaultFont);
            ImGui::PushStyleColor(ImGuiCol_WindowBg, ImU32(ImColor(15, 15, 15)));

