            ImGui::PopStyleColor();
            ImGui::PopFont();
        };

        Renderer::AddRendererCallBack(renderCallback, -1);
    }

    void Menu::SetupFonts()
    {
        auto& io = ImGui::GetIO();

        // Set config file paths
        const auto appDataPath = std::getenv("APPDATA") ? std::filesystem::path(std::getenv("APPDATA")) : std::filesystem::path{};
        const auto configPath = appDataPath / "ChronixV2" / "imgui.ini";
        io.IniFilename = configPath.string().c_str();
        io.LogFilename = nullptr;

        // Clear existing fonts
        io.Fonts->Clear();

        // Define font sizes
        constexpr float defaultSize = Font::g_DefaultFontSize;
        constexpr float optionsSize = Font::g_OptionsFontSize;
        constexpr float childTitleSize = Font::g_ChildTitleFontSize;
        constexpr float chatSize = Font::g_ChatFontSize;
        constexpr float overlaySize = Font::g_OverlayFontSize;
        constexpr float iconSize = Font::g_AwesomeFontSize;

        // Load main fonts with fallback
        Font::g_DefaultFont = BuildFontWithCyrillicSupport(io, Fonts::MainFont, sizeof(Fonts::MainFont), defaultSize);
        Font::g_OptionsFont = BuildFontWithCyrillicSupport(io, Fonts::MainFont, sizeof(Fonts::MainFont), optionsSize);
        Font::g_ChildTitleFont = BuildFontWithCyrillicSupport(io, Fonts::MainFont, sizeof(Fonts::MainFont), childTitleSize);
        Font::g_ChatFont = BuildFontWithCyrillicSupport(io, Fonts::MainFont, sizeof(Fonts::MainFont), chatSize);
        Font::g_OverlayFont = BuildFontWithCyrillicSupport(io, Fonts::MainFont, sizeof(Fonts::MainFont), overlaySize);

        // Load icon font separately
        ImFontConfig iconCfg{};
        iconCfg.FontDataOwnedByAtlas = false;
        static const ImWchar fullRange[] = {0x0020, 0xFFFF, 0};
        Font::g_AwesomeFont = io.Fonts->AddFontFromMemoryTTF(const_cast<std::uint8_t*>(Fonts::IconFont), sizeof(Fonts::IconFont), iconSize, &iconCfg, fullRange);

        // Finalize UI manager state
        UIManager::SetOptionsFont(Font::g_OptionsFont);
        Renderer::NotifyFontsUpdated();
    }
}

