// Helper function to determine rounding direction for decimal truncation
static int evaluate_rounding(const decimal* d, int keep_digits) {
    const u8* current_digit = d->sig.text + keep_digits;

    if (*current_digit > 5) return 1;
    if (*current_digit < 5) return -1;

    // Check remaining digits after the 5
    const u8* end_ptr = d->sig.text + d->sig.length;
    for (const u8* p = current_digit + 1; p < end_ptr; ++p) {
        if (*p != 0) return 1;
    }

    // If all remaining digits are zero, check parity of last kept digit
    return (d->sig.text[keep_digits - 1] & 1) ? 1 : -1;
}

// Perform increment with carry propagation in decimal representation
void increment_with_carry(decimal* d, int pos) {
    u8* digits = d->sig.text;
    int idx = pos - 1;

    while (true) {
        if (digits[idx] < 9) {
            digits[idx]++;
            break;
        }
        if (idx == 0) {
            // Shift entire mantissa left and increase exponent
            for (int k = d->sig.length; k > 0; --k) {
                digits[k] = digits[k - 1];
            }
            digits[0] = 1;
            d->exp++;
            d->sig.length++;
            break;
        }
        digits[idx--] = 0;
    }
}

// Multiply two decimal numbers stored in decimal format
void multiply_decimals(decimal* dest, const decimal* a, const decimal* b) {
    u32 temp_accumulator = 0;
    u8 product_buffer[SIGDIGLEN * 2];
    int total_length = a->sig.length + b->sig.length - 1;
    u8* write_pos = product_buffer + total_length + 1;
    u8* buffer_end = write_pos;

    dest->sign = 0;

    for (int i = total_length; i > 0; --i) {
        int y_index = b->sig.length - 1;
        int x_index = i - y_index - 1;
        int min_len;

        if (x_index < 0) {
            x_index = 0;
            y_index = i - 1;
        }

        const u8* x_ptr = a->sig.text + x_index;
        const u8* y_ptr = b->sig.text + y_index;
        int x_remaining = a->sig.length - x_index;
        int y_remaining = y_index + 1;

        min_len = (x_remaining < y_remaining) ? x_remaining : y_remaining;

        for (int j = 0; j < min_len; ++j) {
            temp_accumulator += x_ptr[j] * y_ptr[-j];
        }

        *(--write_pos) = static_cast<u8>(temp_accumulator % 10);
        temp_accumulator /= 10;
    }

    dest->exp = a->exp + b->exp;

    if (temp_accumulator != 0) {
        *(--write_pos) = static_cast<u8>(temp_accumulator);
        dest->exp++;
    }

    int copied = 0;
    for (; copied < SIGDIGLEN && write_pos < buffer_end; ++copied) {
        dest->sig.text[copied] = *write_pos++;
    }
    dest->sig.length = static_cast<u8>(copied);

    // Rounding logic
    if (write_pos < buffer_end && *write_pos >= 5) {
        bool should_round_up = true;

        if (*write_pos == 5) {
            bool has_nonzero = false;
            for (const u8* r = write_pos + 1; r < buffer_end; ++r) {
                if (*r != 0) {
                    has_nonzero = true;
                    break;
                }
            }
            if (!has_nonzero && ((*(write_pos - 1) & 1) == 0)) {
                should_round_up = false;
            }
        }

        if (should_round_up) {
            increment_with_carry(dest, dest->sig.length);
        }
    }
}

// Convert double to internal decimal representation
void convert_double_to_decimal(decimal* output, double value) {
    s8 sign_bit = (s8)(SIGNBIT(value) != 0);

    if (value == 0.0) {
        output->sign = sign_bit;
        output->exp = 0;
        output->sig.length = 1;
        output->sig.text[0] = 0;
        return;
    }

    if (!isfinite(value)) {
        output->sign = sign_bit;
        output->exp = 0;
        output->sig.length = 1;
        output->sig.text[0] = (fpclassify(value) == FP_NAN) ? 'N' : 'I';
        return;
    }

    if (sign_bit) {
        value = -value;
    }

    int bin_exp;
    double fractional_part = frexp(value, &bin_exp);
    int used_bits = DBL_MANT_DIG - __count_trailing_zero(fractional_part);
    double integer_part;
    decimal int_dec, pow2_dec;

    __two_exp(&pow2_dec, bin_exp - used_bits);
    fractional_part = modf(ldexp(fractional_part, used_bits), &integer_part);
    __ull2dec(&int_dec, static_cast<u64>(integer_part));
    multiply_decimals(output, &int_dec, &pow2_dec);
    output->sign = sign_bit;
}

// Format decimal number according to specified digit count
void format_decimal(const decform* fmt, double input, decimal* result) {
    s16 precision = fmt->digits;
    int idx;

    convert_double_to_decimal(result, input);

    if (result->sig.text[0] > 9) {
        return;
    }

    if (precision > SIGDIGLEN) {
        precision = SIGDIGLEN;
    }

    if (precision > 0 && precision < result->sig.length) {
        int round_dir = evaluate_rounding(result, precision);
        result->sig.length = precision;
        if (round_dir >= 0) {
            increment_with_carry(result, precision);
        }
    }

    while (result->sig.length < precision) {
        result->sig.text[result->sig.length++] = 0;
    }

    result->exp -= result->sig.length - 1;

    for (idx = 0; idx < result->sig.length; ++idx) {
        result->sig.text[idx] += '0';
    }
}

// Subtract two decimal numbers: z = x - y
void subtract_decimals(decimal* z, const decimal* x, const decimal* y) {
    *z = *x;

    if (y->sig.text[0] == 0) {
        return;
    }

    int max_len = (z->sig.length < y->sig.length) ? y->sig.length : z->sig.length;
    int exp_diff = z->exp - y->exp;
    max_len += exp_diff;

    if (max_len > SIGDIGLEN) {
        max_len = SIGDIGLEN;
    }

    while (z->sig.length < max_len) {
        z->sig.text[z->sig.length++] = 0;
    }

    u8* z_start = z->sig.text;
    u8* z_current = z_start + max_len;

    if (y->sig.length + exp_diff < max_len) {
        z_current = z_start + (y->sig.length + exp_diff);
    }

    const u8* y_start = y->sig.text;
    const u8* y_current = y_start + (z_current - z_start - exp_diff);
    const u8* y_end = y_current;

    while (z_current > z_start && y_current > y_start) {
        --z_current;
        --y_current;

        if (*z_current < *y_current) {
            u8* borrow_ptr = z_current - 1;
            while (*borrow_ptr == 0) {
                borrow_ptr--;
            }
            while (borrow_ptr != z_current) {
                --(*borrow_ptr);
                *(++borrow_ptr) += 10;
            }
        }

        *z_current -= *y_current;
    }

    if (y_end - y_start < y->sig.length) {
        bool truncate_down = false;

        if (*y_end < 5) {
            truncate_down = true;
        } else if (*y_end == 5) {
            const u8* tail_ptr = y->sig.text + y->sig.length;
            for (const u8* p = y_end + 1; p < tail_ptr; ++p) {
                if (*p != 0) goto finalize_subtraction;
            }

            u8* check_digit = z_start + (y_end - y_start) + exp_diff - 1;
            if (*check_digit & 1) {
                truncate_down = true;
            }
        }

        if (truncate_down) {
            u8* digit_ptr = z_start + (y_end - y_start) + exp_diff - 1;
            if (*digit_ptr < 1) {
                u8* borrow_ptr = digit_ptr - 1;
                while (*borrow_ptr == 0) {
                    borrow_ptr--;
                }
                while (borrow_ptr != digit_ptr) {
                    --(*borrow_ptr);
                    *(++borrow_ptr) += 10;
                }
            }
            *digit_ptr -= 1;
        }
    }

finalize_subtraction:
    // Normalize leading zeros
    u8* non_zero_start = z_start;
    while (*non_zero_start == 0 && non_zero_start < z_start + z->sig.length) {
        non_zero_start++;
    }

    if (non_zero_start > z_start) {
        u8 shift_amount = static_cast<u8>(non_zero_start - z_start);
        z->exp -= shift_amount;
        u8* dst = z_start;
        u8* src = non_zero_start;
        u8* end = z_start + z->sig.length;

        while (src < end) {
            *dst++ = *src++;
        }
        z->sig.length -= shift_amount;
    }

    // Trim trailing zeros
    u8* tail = z_start + z->sig.length;
    while (tail > z_start) {
        --tail;
        if (*tail != 0) break;
    }
    z->sig.length = static_cast<u8>(tail - z_start + 1);
}

