    // --- MidiDevice Implementation ---
    MidiDevice::MidiDevice()
    {
        m_Handle = nullptr;
        m_SelectedDeviceId = 0;
    }

    MidiDevice::~MidiDevice()
    {
        Shutdown();
    }

    BOOL MidiDevice::Activate(UINT deviceId)
    {
        if (m_Handle != nullptr)
        {
            if (m_SelectedDeviceId != deviceId)
            {
                Shutdown();
            }
            else
            {
                return FALSE;
            }
        }
        m_SelectedDeviceId = deviceId;
        MMRESULT result = midiOutOpen(&m_Handle, deviceId, (DWORD_PTR)g_Supervisor.m_HwndGameWindow, NULL, CALLBACK_WINDOW);
        return (result != MMSYSERR_NOERROR);
    }

    ZunResult MidiDevice::Shutdown()
    {
        if (m_Handle == nullptr)
        {
            return ZUN_ERROR;
        }
        midiOutReset(m_Handle);
        midiOutClose(m_Handle);
        m_Handle = nullptr;
        return ZUN_SUCCESS;
    }

    BOOL MidiDevice::TransmitLong(LPMIDIHDR pHeader)
    {
        if (m_Handle == nullptr)
        {
            return FALSE;
        }
        if (midiOutPrepareHeader(m_Handle, pHeader, sizeof(*pHeader)) != MMSYSERR_NOERROR)
        {
            return TRUE;
        }
        MMRESULT res = midiOutLongMsg(m_Handle, pHeader, sizeof(*pHeader));
        return (res != MMSYSERR_NOERROR);
    }

    union ShortMidiPacket {
        struct
        {
            u8 statusByte;
            i8 data1;
            i8 data2;
            i8 padding;
        } fields;
        DWORD rawValue;
    };

    BOOL MidiDevice::TransmitShort(u8 status, u8 byte1, u8 byte2)
    {
        ShortMidiPacket packet;
        if (m_Handle == nullptr)
        {
            return FALSE;
        }
        packet.fields.statusByte = status;
        packet.fields.data1 = byte1;
        packet.fields.data2 = byte2;
        MMRESULT res = midiOutShortMsg(m_Handle, packet.rawValue);
        return (res != MMSYSERR_NOERROR);
    }

    // --- MidiTimer Implementation ---
    MidiTimer::MidiTimer()
    {
        timeGetDevCaps(&m_Capabilities, sizeof(TIMECAPS));
        m_EventId = 0;
    }

    MidiTimer::~MidiTimer()
    {
        CancelTimerInternal();
        timeEndPeriod(m_Capabilities.wPeriodMin);
    }

    UINT MidiTimer::ActivateTimerInternal(u32 delayMs, LPTIMECALLBACK callback, DWORD_PTR userData)
    {
        CancelTimerInternal();
        timeBeginPeriod(m_Capabilities.wPeriodMin);

        if (callback != nullptr)
        {
            m_EventId = timeSetEvent(delayMs, m_Capabilities.wPeriodMin, callback, userData, TIME_PERIODIC);
        }
        else
        {
            m_EventId = timeSetEvent(
                delayMs,
                m_Capabilities.wPeriodMin,
                (LPTIMECALLBACK)MidiTimer::DefaultTickHandler,
                (DWORD_PTR)this,
                TIME_PERIODIC
            );
        }
        return m_EventId;
    }

    BOOL MidiTimer::CancelTimerInternal()
    {
        if (m_EventId != 0)
        {
            timeKillEvent(m_EventId);
            m_EventId = 0;
        }
        timeEndPeriod(m_Capabilities.wPeriodMin);
        return TRUE;
    }

    void CALLBACK MidiTimer::DefaultTickHandler(u32 id, u32 msg, DWORD_PTR user, DWORD_PTR dw1, DWORD_PTR dw2)
    {
        MidiTimer* timerInstance = reinterpret_cast<MidiTimer*>(user);
        if (timerInstance != nullptr)
        {
            timerInstance->OnTimerElapsed();
        }
    }

    // --- MidiOutput Implementation ---
    u16 MidiOutput::SwapBytes(u16 value)
    {
        u8 buffer[2];
        buffer[0] = reinterpret_cast<u8*>(&value)[1];
        buffer[1] = reinterpret_cast<u8*>(&value)[0];
        return *reinterpret_cast<const u16*>(buffer);
    }

    u32 MidiOutput::DecodeVariableLengthField(LPBYTE* ppData)
    {
        u32 total = 0;
        u8 currentByte;
        do
        {
            currentByte = **ppData;
            (*ppData)++;
            total = (total << 7) | (currentByte & 0x7F);
        } while ((currentByte & 0x80) != 0);
        return total;
    }

    MidiOutput::MidiOutput()
    {
        m_TrackArray = nullptr;
        m_ScaleDivisions = 0;
        m_BPM = 500000;
        m_CountTracks = 0;
        m_KeyShiftOffset = 0;
        m_FadeScale = 1.0f;
        m_LastVolumeSetting = 0;
        m_TimerCounter = 0;
        m_PitchBendState = 0;
        m_PanState = 0;
        m_EffectDepth = 0;
        m_IsFadingOut = FALSE;

        for (size_t i = 0; i < ARRAY_SIZE(m_FileBuffers); i++)
        {
            m_FileBuffers[i] = nullptr;
        }

        for (size_t i = 0; i < ARRAY_SIZE(m_HeaderPool); i++)
        {
            m_HeaderPool[i] = nullptr;
        }

        m_ActiveFileIndex = -1;
        m_NextHeaderSlot = 0;
    }

    MidiOutput::~MidiOutput()
    {
        TerminatePlayback();
        DiscardTrackData();
        for (int i = 0; i < 32; i++)
        {
            FreeFileBuffer(i);
        }
    }

    ZunResult MidiOutput::LoadFileIntoBuffer(int slot, LPCSTR path)
    {
        if (m_ActiveFileIndex == slot)
        {
            TerminatePlayback();
        }
        FreeFileBuffer(slot);

        m_FileBuffers[slot] = FileSystem::OpenFile(const_cast<LPSTR>(path), nullptr, false);
        if (m_FileBuffers[slot] == nullptr)
        {
            g_GameErrorContext.Log(TH_ERR_MIDI_FAILED_TO_READ_FILE, path);
            return ZUN_ERROR;
        }
        return ZUN_SUCCESS;
    }

    void MidiOutput::FreeFileBuffer(int slot)
    {
        if (m_FileBuffers[slot] != nullptr)
        {
            g_ZunMemory.Free(m_FileBuffers[slot]);
            m_FileBuffers[slot] = nullptr;
        }
    }

    void MidiOutput::DiscardTrackData()
    {
        if (m_TrackArray == nullptr)
        {
            return;
        }
        for (int i = 0; i < m_CountTracks; i++)
        {
            if (m_TrackArray[i].pData != nullptr)
            {
                g_ZunMemory.Free(m_TrackArray[i].pData);
                m_TrackArray[i].pData = nullptr;
            }
        }
        g_ZunMemory.Free(m_TrackArray);
        m_TrackArray = nullptr;
        m_CountTracks = 0;
    }

#pragma var_order(trackIdx, pDataCursor, pTrackCursor, pBufferBase, chunkSize, rawHeader, trackSize, pEndOfHeader)
    ZunResult MidiOutput::AnalyzeMidiData(int fileSlot)
    {
        u8 rawHeader[8];
        u32 trackSize;
        LPBYTE pDataCursor, pTrackCursor, pEndOfHeader;
        int trackIdx;
        LPBYTE pBufferBase;
        u32 chunkSize;

        DiscardTrackData();

        pDataCursor = m_FileBuffers[fileSlot];
        pBufferBase = pDataCursor;

        if (pDataCursor == nullptr)
        {
            utils::DebugPrint(TH_ERR_MIDI_NOT_LOADED);
            return ZUN_ERROR;
        }

        // Parse header chunk
        memcpy(rawHeader, pDataCursor, 8);
        pDataCursor += 8;
        chunkSize = Ntohl(*(u32*)(rawHeader + 4));
        pEndOfHeader = pDataCursor;
        pDataCursor += chunkSize;

        m_Format = SwapBytes(*(u16*)pEndOfHeader);
        m_ScaleDivisions = SwapBytes(*(u16*)(pEndOfHeader + 4));
        m_CountTracks = SwapBytes(*(u16*)(pEndOfHeader + 2));

        m_TrackArray = (MidiTrack*)g_ZunMemory.Alloc(sizeof(MidiTrack) * m_CountTracks, "midi_tracks");
        memset(m_TrackArray, 0, sizeof(MidiTrack) * m_CountTracks);

        for (trackIdx = 0; trackIdx < m_CountTracks; trackIdx++)
        {
            pTrackCursor = pDataCursor;
            pDataCursor += 8;

            trackSize = Ntohl(*(u32*)&pTrackCursor[4]);
            m_TrackArray[trackIdx].dataSize = trackSize;
            m_TrackArray[trackIdx].pData = (LPBYTE)g_ZunMemory.Alloc(trackSize, "midi_track_data");
            m_TrackArray[trackIdx].isActive = TRUE;
            memcpy(m_TrackArray[trackIdx].pData, pDataCursor, trackSize);
            pDataCursor += trackSize;
        }

        m_BPM = 1000000;
        m_ActiveFileIndex = fileSlot;
        utils::DebugPrint(" midi open %d\n", fileSlot);
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::Initialize(LPCSTR midiPath)
    {
        if (LoadFileIntoBuffer(0x1f, midiPath) != ZUN_SUCCESS)
        {
            return ZUN_ERROR;
        }
        AnalyzeMidiData(0x1f);
        FreeFileBuffer(0x1f);
        return ZUN_SUCCESS;
    }

    void MidiOutput::PrepareTracks()
    {
        int trackIndex;
        MidiTrack* pTrack = m_TrackArray;
        m_FadeScale = 1.0f;
        m_TimerCounter = 0;
        m_IsFadingOut = FALSE;
        m_MasterVolume = 0;
        m_TempoAccumulator = 0;

        for (trackIndex = 0; trackIndex < m_CountTracks; trackIndex++, pTrack++)
        {
            pTrack->pCurrent = pTrack->pData;
            pTrack->pStart = pTrack->pCurrent;
            pTrack->isActive = TRUE;
            pTrack->nextEventDelay = DecodeVariableLengthField(&pTrack->pCurrent);
        }
    }

    ZunResult MidiOutput::Start()
    {
        if (m_TrackArray == nullptr)
        {
            return ZUN_ERROR;
        }
        PrepareTracks();
        m_Device.Activate(MIDI_MAPPER);
        ActivateTimerInternal(1, nullptr, nullptr);
        utils::DebugPrint(" midi play\n");
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::TerminatePlayback()
    {
        if (m_TrackArray == nullptr)
        {
            return ZUN_ERROR;
        }

        for (int i = 0; i < ARRAY_SIZE(m_HeaderPool); i++)
        {
            if (m_HeaderPool[i] != nullptr)
            {
                CleanupHeader(m_HeaderPool[i]);
            }
        }

        CancelTimerInternal();
        m_Device.Shutdown();
        m_ActiveFileIndex = -1;
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::CleanupHeader(LPMIDIHDR pHdr)
    {
        if (pHdr == nullptr)
        {
            utils::DebugPrint("error : null header\r\n");
        }
        if (m_Device.m_Handle == nullptr)
        {
            utils::DebugPrint("error : device not open\r\n");
        }

        for (int i = 0; i < ARRAY_SIZE(m_HeaderPool); i++)
        {
            if (m_HeaderPool[i] == pHdr)
            {
                m_HeaderPool[i] = nullptr;
                goto success;
            }
        }
        return ZUN_ERROR;

    success:
        MMRESULT res = midiOutUnprepareHeader(m_Device.m_Handle, pHdr, sizeof(*pHdr));
        if (res != MMSYSERR_NOERROR)
        {
            utils::DebugPrint("error : unprepare failed\r\n");
        }
        g_ZunMemory.Free(pHdr->lpData);
        g_ZunMemory.Free(pHdr);
        return ZUN_SUCCESS;
    }

    ZunResult MidiOutput::SetFadeOutDuration(u32 durationMs)
    {
        m_FadeScale = 0.0f;
        m_FadeDuration = durationMs;
        m_FadeTimer = 0;
        m_TimerCounter = 0;
        m_IsFadingOut = TRUE;
        return ZUN_SUCCESS;
    }

#pragma var_order(trackIdx, localTimeAccumulator, anyActiveTrack)
    void MidiOutput::OnTimerElapsed()
    {
        BOOL anyActiveTrack = FALSE;
        ULONGLONG localTimeAccumulator = m_TempoAccumulator + (m_MasterVolume * m_ScaleDivisions * 1000) / m_BPM;

        if (m_IsFadingOut != FALSE)
        {
            if (m_FadeTimer < m_FadeDuration)
            {
                m_FadeScale = 1.0f - (f32)m_FadeTimer / (f32)m_FadeDuration;
                u8 newVol = (u8)(m_FadeScale * 128.0f);
                if (newVol != m_LastVolumeSetting)
                {
                    ApplyFadeVolume(0);
                    m_LastVolumeSetting = newVol;
                }
                m_FadeTimer++;
            }
            else
            {
                m_FadeScale = 0.0f;
                return;
            }
        }

        for (int trackIdx = 0; trackIdx < m_CountTracks; trackIdx++)
        {
            if (m_TrackArray[trackIdx].isActive)
            {
                anyActiveTrack = TRUE;
                while (m_TrackArray[trackIdx].isActive)
                {
                    if (m_TrackArray[trackIdx].nextEventDelay <= localTimeAccumulator)
                        {
                        HandleEvent(&m_TrackArray[trackIdx]);
                        localTimeAccumulator = m_TempoAccumulator + (m_MasterVolume * m_ScaleDivisions * 1000 / m_BPM);
                        continue;
                    }
                    break;
                }
            }
        }

        m_MasterVolume++;

        if (!anyActiveTrack)
        {
            PrepareTracks();
        }
    }

#pragma var_order(nextDelta, idx, param2, delta, statusHigh, statusLow, status, param1, currentHeader, cVar1, unk24, local_2c, local_30)
    void MidiOutput::HandleEvent(MidiTrack* pTrack)
    {
        int delta;
        int nextDelta;
        MidiTrack* local_30;
        MidiTrack* local_2c;
        u8 param1, param2;
        u8 status, statusHigh, statusLow;
        u8 cVar1;
        LPMIDIHDR currentHeader;
        int idx;
        int unk24;

        status = *pTrack->pCurrent;
        if (status < MIDI_OPCODE_NOTE_OFF)
        {
            status = pTrack->lastStatus;
        }
        else
        {
            pTrack->pCurrent += 1;
        }

        statusHigh = status & 0xF0;
        statusLow = status & 0x0F;

        switch (statusHigh)
        {
        case MIDI_OPCODE_SYSTEM_EXCLUSIVE:
            if (status == MIDI_OPCODE_SYSTEM_EXCLUSIVE)
            {
                if (m_HeaderPool[m_NextHeaderSlot] != nullptr)
                {
                    CleanupHeader(m_HeaderPool[m_NextHeaderSlot]);
                }

                currentHeader = m_HeaderPool[m_NextHeaderSlot] = (LPMIDIHDR)g_ZunMemory.Alloc(sizeof(MIDIHDR), "midiHDR");
                delta = DecodeVariableLengthField(&pTrack->pCurrent);

                memset(currentHeader, 0, sizeof(MIDIHDR));
                currentHeader->lpData = (LPSTR)g_ZunMemory.Alloc(delta + 1, "midiHDR->lpData");
                currentHeader->lpData[0] = MIDI_OPCODE_SYSTEM_EXCLUSIVE;
                currentHeader->dwFlags = 0;
                currentHeader->dwBufferLength = delta + 1;

                for (idx = 0; idx < delta; idx++)
                {
                    currentHeader->lpData[idx + 1] = *pTrack->pCurrent;
                    pTrack->pCurrent++;
                }

                if (m_Device.TransmitLong(currentHeader))
                {
                    g_ZunMemory.Free(currentHeader->lpData);
                    g_ZunMemory.Free(currentHeader);
                    m_HeaderPool[m_NextHeaderSlot] = nullptr;
                }

                m_NextHeaderSlot = (m_NextHeaderSlot + 1) % 32;
            }
            else if (status == MIDI_OPCODE_SYSTEM_RESET)
            {
                cVar1 = *pTrack->pCurrent;
                pTrack->pCurrent += 1;
                delta = DecodeVariableLengthField(&pTrack->pCurrent);

                if (cVar1 == 0x2f)
                {
                    pTrack->isActive = FALSE;
                    return;
                }

                if (cVar1 == 0x51)
                {
                    m_TempoAccumulator += (m_MasterVolume * m_ScaleDivisions * 1000 / m_BPM);
                    m_MasterVolume = 0;
                    m_BPM = 0;
                    for (idx = 0; idx < delta; idx++)
                    {
                        m_BPM = (m_BPM << 8) + *pTrack->pCurrent;
                        pTrack->pCurrent++;
                    }
                    unk24 = 60000000 / m_BPM;
                    break;
                }
                pTrack->pCurrent += delta;
            }
            break;

        case MIDI_OPCODE_NOTE_OFF:
        case MIDI_OPCODE_NOTE_ON:
        case MIDI_OPCODE_POLYPHONIC_AFTERTOUCH:
        case MIDI_OPCODE_MODE_CHANGE:
        case MIDI_OPCODE_PITCH_BEND_CHANGE:
            param1 = *pTrack->pCurrent;
            pTrack->pCurrent += 1;
            param2 = *pTrack->pCurrent;
            pTrack->pCurrent += 1;
            break;

        case MIDI_OPCODE_PROGRAM_CHANGE:
        case MIDI_OPCODE_CHANNEL_AFTERTOUCH:
            param1 = *pTrack->pCurrent;
            pTrack->pCurrent += 1;
            param2 = 0;
            break;
        }

        switch (statusHigh)
        {
        case MIDI_OPCODE_NOTE_ON:
            if (param2 != 0)
            {
                param1 += m_KeyShiftOffset;
                m_Channels[statusLow].keyPressedFlags[param1 >> 3] |= (u8)(1 << (param1 & 7));
                break;
            }
        case MIDI_OPCODE_NOTE_OFF:
            param1 += m_KeyShiftOffset;
            m_Channels[statusLow].keyPressedFlags[param1 >> 3] &= (u8)(~(1 << (param1 & 7)));
            break;

        case MIDI_OPCODE_PROGRAM_CHANGE:
            m_Channels[statusLow].instrument = param1;
            break;

        case MIDI_OPCODE_MODE_CHANGE:
            switch (param1)
            {
            case 0:
                m_Channels[statusLow].bankSelect = param2;
                break;
            case 7:
                m_Channels[statusLow].channelVolume = param2;
                delta = (int)(param2 * m_FadeScale);
                if (delta < 0) delta = 0;
                else if (delta > 0x7F) delta = 0x7F;
                param2 = m_Channels[statusLow].modifiedVolume = (u8)delta;
                break;
            case 91:
                m_Channels[statusLow].effectOneDepth = param2;
                break;
            case 93:
                m_Channels[statusLow].effectThreeDepth = param2;
                break;
            case 10:
                m_Channels[statusLow].pan = param2;
                break;
            case 2:
                for (local_2c = &m_TrackArray[0], idx = 0; idx < m_CountTracks; idx++, local_2c++)
                {
                    local_2c->pStart = local_2c->pCurrent;
                    local_2c->savedNextEventDelay = local_2c->nextEventDelay;
                }
                m_TempoAtLoopPoint = m_BPM;
                m_VolumeAtLoopPoint = m_MasterVolume;
                m_LoopAccumulator = m_TempoAccumulator;
                break;
            case 4:
                for (local_30 = &m_TrackArray[0], idx = 0; idx < m_CountTracks; idx++, local_30++)
                {
                    local_30->pCurrent = local_30->pStart;
                    local_30->nextEventDelay = local_30->savedNextEventDelay;
                }
                m_BPM = m_TempoAtLoopPoint;
                m_MasterVolume = m_VolumeAtLoopPoint;
                m_TempoAccumulator = m_LoopAccumulator;
                break;
            }
            break;
        }

        if (status < MIDI_OPCODE_SYSTEM_EXCLUSIVE)
        {
            m_Device.TransmitShort(status, param1, param2);
        }

        pTrack->lastStatus = status;
        nextDelta = DecodeVariableLengthField(&pTrack->pCurrent);
        pTrack->nextEventDelay += nextDelta;
    }

#pragma var_order(param1, idx, volumeByte, midiStatus, volumeClamped)
    void MidiOutput::ApplyFadeVolume(int baseVolume)
    {
        int volumeClamped;
        u32 volumeByte;
        int idx;
        int param1;
        u32 midiStatus;

        if (m_PitchBendState != 0)
        {
            return;
        }

        param1 = 7;
        for (idx = 0; idx < ARRAY_SIZE(m_Channels); idx++)
        {
            midiStatus = (u8)(idx + 0xB0);
            volumeClamped = (int)(m_Channels[idx].channelVolume * m_FadeScale) + baseVolume;
            if (volumeClamped < 0) volumeClamped = 0;
            else if (volumeClamped > 127) volumeClamped = 127;
            volumeByte = (u8)volumeClamped;
            m_Device.TransmitShort(midiStatus, param1, volumeByte);
        }
    }

