Engine::Engine(const std::filesystem::path &gltfPath)
{
    I = std::make_unique<Init>(gltfPath);
    descUpdater = std::make_unique<DescriptorUpdater>(I->device);
    lightsManager = std::make_unique<LightsManager>(I->device, I->allocator);
}

Engine::~Engine()
{
    // Destroy all remaining lights
    for (auto& l : lightsManager->lights) {
        l.destroy();
    }
    I->clean();
}

void Engine::run()
{
    update_descriptors();

    SDL_Event e;
    bool done = false;
    int keyCount;
    const bool* keyboardState = SDL_GetKeyboardState(&keyCount);

    float deltaTime;
    uint64_t now, prevTime{SDL_GetPerformanceCounter()};
    const float perfFreq = static_cast<float>(SDL_GetPerformanceFrequency());

    do {
        now = SDL_GetPerformanceCounter();
        deltaTime = static_cast<float>(now - prevTime) / perfFreq;
        prevTime = now;

        while (SDL_PollEvent(&e)) {
            switch (e.type) {
                case SDL_EVENT_QUIT:
                    done = true;
                    break;
                case SDL_EVENT_WINDOW_PIXEL_SIZE_CHANGED:
                    shouldResize = true;
                    [[fallthrough]];
                case SDL_EVENT_KEY_DOWN:
                    I->camera->process_event(keyboardState, deltaTime);
                    break;
            }
            ImGui_ImplSDL3_ProcessEvent(&e);
        }

        if (shouldResize) {
            resize();
        }

        update_imgui();
        draw();
    } while (!done);
}

void Engine::update_imgui()
{
    static SpecializationConstantsClosestHit constantsCH{};
    static SpecializationConstantsMiss constantsMiss{};

    bool randomFlag = static_cast<bool>(constantsCH.random);
    bool presampleFlag = static_cast<bool>(constantsCH.presampled);
    bool envMapFlag = static_cast<bool>(constantsMiss.envMap);
    bool dirLightOn = false;

    int recursionDepth = constantsCH.recursionDepth;
    int numBounces = constantsCH.numBounces;

    float scaleVal{1.f}, rotX{0.f}, rotY{0.f}, rotZ{0.f};
    std::filesystem::path hdrPath{std::string(PROJECT_DIR) + std::string("/assets/rogland_clear_night_4k.hdr")};

    ImGui_ImplVulkan_NewFrame();
    ImGui_ImplSDL3_NewFrame();
    ImGui::NewFrame();

    const float frameTimeMs = ImGui::GetIO().DeltaTime * 1000.f;
    const float fpsVal = 1.0f / (frameTimeMs * 0.001f); // same as 1000.0f / frameTimeMs

    ImGuiViewport* mainView = ImGui::GetMainViewport();
    ImVec2 workOrigin = mainView->WorkPos;
    ImVec2 workExtent = mainView->WorkSize;
    ImVec2 windowPos = ImVec2(workOrigin.x + workExtent.x - 10, workOrigin.y + 10);

    ImGui::SetNextWindowPos(windowPos, ImGuiCond_Always, ImVec2(1.0f, 0.0f));
    ImGui::SetNextWindowBgAlpha(0.35f);

    static constexpr ImGuiWindowFlags perfFlags = ImGuiWindowFlags_NoDecoration
                                                  | ImGuiWindowFlags_AlwaysAutoResize
                                                  | ImGuiWindowFlags_NoSavedSettings
                                                  | ImGuiWindowFlags_NoFocusOnAppearing
                                                  | ImGuiWindowFlags_NoNav;

    ImGui::Begin("Performance", nullptr, perfFlags);
    ImGui::Text("%.1f FPS", fpsVal);
    ImGui::Text("%.2f ms", frameTimeMs);
    ImGui::End();

    ImGui::Begin("Controls");
    ImGui::ColorEdit3("Background color", reinterpret_cast<float*>(&rayPush.clearColor));
    ImGui::Separator();

    ImGui::Checkbox("EnvMap", &envMapFlag);
    ImGui::SameLine();
    if (ImGui::Button("Load from file")) {
        const std::filesystem::path newHdrPath = utils::load_file_from_window({{"HDRI", "hdr"}});
        I->device.waitIdle();
        utils::destroy_image(I->device, I->allocator, I->backgroundImage);
        I->load_background(newHdrPath);
        descUpdater->clean();
        for (const auto& f : I->frames) {
            descUpdater->add_combined_image(f.descriptorSetRt, 5, {I->backgroundImage});
        }
        descUpdater->update();
        hdrPath = newHdrPath;
    }

    if (envMapFlag) {
        ImGui::SameLine();
        ImGui::Text("%s", hdrPath.c_str());
    }

    ImGui::Checkbox("Random", &randomFlag);
    ImGui::Checkbox("Presample", &presampleFlag);
    ImGui::InputInt("Maximum recursion depth", &recursionDepth, 1, 1);
    recursionDepth = std::max(recursionDepth, 1);
    ImGui::InputInt("Bounces", &numBounces, 2, 4);
    numBounces = std::max(numBounces, 2);

    if (ImGui::Button("Apply Changes")) {
        constantsCH.recursionDepth = static_cast<uint32_t>(recursionDepth);
        constantsCH.numBounces = static_cast<uint32_t>(numBounces);
        constantsCH.random = static_cast<vk::Bool32>(randomFlag);
        constantsCH.presampled = static_cast<vk::Bool32>(presampleFlag);
        constantsMiss.envMap = static_cast<vk::Bool32>(envMapFlag);
        I->rebuid_rt_pipeline(constantsCH, constantsMiss);
    }

    ImGui::Separator();

    const float oldScale = scaleVal;
    if (ImGui::InputFloat("Scale", &scaleVal, 0.1f, 0.5f, "%.2f")) {
        scaleVal = std::max(scaleVal, 0.01f);
        const float dScale = scaleVal / oldScale;
        const glm::mat4 S = glm::scale(glm::mat4{1.f}, glm::vec3(dScale));
        I->asBuilder->updateTLAS(I->tlas, S);
        rayPush.globalScale = scaleVal;
    }

    const float oldRotX = rotX;
    if (ImGui::SliderAngle("X-axis Rotation", &rotX, -180.f, 180.f)) {
        const float dRot = rotX - oldRotX;
        const glm::mat4 R = glm::rotate(dRot, glm::vec3(1.f, 0.f, 0.f));
        I->asBuilder->updateTLAS(I->tlas, R);
    }

    const float oldRotY = rotY;
    if (ImGui::SliderAngle("Y-axis Rotation", &rotY, -180.f, 180.f)) {
        const float dRot = rotY - oldRotY;
        const glm::mat4 R = glm::rotate(dRot, glm::vec3(0.f, -1.f, 0.f));
        I->asBuilder->updateTLAS(I->tlas, R);
    }

    const float oldRotZ = rotZ;
    if (ImGui::SliderAngle("Z-axis Rotation", &rotZ, -180.f, 180.f)) {
        const float dRot = rotZ - oldRotZ;
        const glm::mat4 R = glm::rotate(dRot, glm::vec3(0.f, 0.f, 1.f));
        I->asBuilder->updateTLAS(I->tlas, R);
    }

    lightsManager->run();
    assert(lightsManager->lightBuffers.size() == lightsManager->lights.size());

    bool needsDescUpdate = false;
    for (auto& f : I->frames) {
        needsDescUpdate |= (f.lightsCount != lightsManager->lights.size());
        f.lightsCount = lightsManager->lights.size();
    }

    if (needsDescUpdate && !lightsManager->lightBuffers.empty()) {
        descUpdater->clean();
        for (const auto& f : I->frames) {
            descUpdater->add_uniform(f.descriptorSetUAB, 3, lightsManager->lightBuffers);
        }
        descUpdater->update();
    }

    rayPush.nLights = static_cast<uint32_t>(lightsManager->lights.size());
    ImGui::End();

    ImGui::Render();
}

void Engine::update_descriptors()
{
    descUpdater->clean();

    const bool hasTextures = I->scene->samplers.size() > 0 && I->scene->images.size() > 0;

    for (const auto& frame : I->frames) {
        const vk::DescriptorSet uabSet = frame.descriptorSetUAB;
        const vk::DescriptorSet rtSet = frame.descriptorSetRt;

        descUpdater->add_uniform(uabSet, 0, I->scene->surfaceUniformBuffers);

        if (hasTextures) {
            descUpdater->add_sampler(uabSet, 1, I->scene->samplers);
            descUpdater->add_sampled_image(uabSet, 2, I->scene->images);
        }

        if (!lightsManager->lightBuffers.empty())
            descUpdater->add_uniform(uabSet, 3, lightsManager->lightBuffers);

        descUpdater->add_as(rtSet, 0, I->tlas.as.AS);
        descUpdater->add_storage_image(rtSet, 1, {frame.imageDraw});
        descUpdater->add_uniform(rtSet, 2, {I->camera->cameraBuffer});
        descUpdater->add_combined_image(rtSet, 3, {I->presampler->hemisphereImage});
        descUpdater->add_combined_image(rtSet, 4, {I->presampler->ggxImage});
        descUpdater->add_combined_image(rtSet, 5, {I->backgroundImage});
        descUpdater->add_storage(rtSet, 6, {I->scene->instancesBuffer});
    }

    descUpdater->update();
}

void Engine::draw()
{
    vk::Semaphore acquireSem = get_current_frame().renderSemaphore;
    vk::Fence renderFence = get_current_frame().renderFence;
    ImageData drawTarget = get_current_frame().imageDraw;

    vk::Result fenceRes = I->device.waitForFences(renderFence, vk::True, FENCE_TIMEOUT);
    if (fenceRes != vk::Result::eSuccess) {
        std::println("Skipping frame");
        return;
    }

    vk::AcquireNextImageInfoKHR acquireInfo{};
    acquireInfo.setSwapchain(I->swapchain);
    acquireInfo.setSemaphore(acquireSem);
    acquireInfo.setFence(nullptr);
    acquireInfo.setTimeout(FENCE_TIMEOUT);
    acquireInfo.setDeviceMask(1);

    vk::Result acquireRes = I->device.acquireNextImage2KHR(&acquireInfo, &swapchainImageIndex);
    VK_CHECK_RES(acquireRes);

    if (acquireRes == vk::Result::eErrorOutOfDateKHR) {
        shouldResize = true;
        return;
    }

    I->device.resetFences(renderFence);

    vk::Semaphore submitSem = acquireSem;

    vk::MemoryBarrier2 memBarrier{};
    vk::DependencyInfo depInfo{};
    depInfo.setMemoryBarriers(memBarrier);

    vk::CommandBuffer cmdBuf = get_current_frame().mainCommandBuffer;
    cmdBuf.reset();

    vk::CommandBufferBeginInfo beginInfo{};
    beginInfo.setFlags(vk::CommandBufferUsageFlagBits::eOneTimeSubmit);
    cmdBuf.begin(beginInfo);

    utils::transition_image(cmdBuf,
                            I->swapchainImages[swapchainImageIndex],
                            vk::ImageLayout::eUndefined,
                            vk::ImageLayout::eGeneral,
                            vk::PipelineStageFlagBits2::eTopOfPipe,
                            vk::PipelineStageFlagBits2::eRayTracingShaderKHR);

    raytrace(cmdBuf);

    memBarrier.setSrcStageMask(vk::PipelineStageFlagBits2::eRayTracingShaderKHR);
    memBarrier.setDstStageMask(vk::PipelineStageFlagBits2::eBlit);
    memBarrier.setSrcAccessMask(vk::AccessFlagBits2::eMemoryWrite);
    memBarrier.setDstAccessMask(vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite);
    cmdBuf.pipelineBarrier2(depInfo);

    utils::copy_image(cmdBuf,
                      drawTarget.image,
                      I->swapchainImages[swapchainImageIndex].image,
                      vk::Extent2D{drawTarget.extent.width, drawTarget.extent.height},
                      I->swapchainExtent);

    memBarrier.setSrcStageMask(vk::PipelineStageFlagBits2::eBlit);
    memBarrier.setDstStageMask(vk::PipelineStageFlagBits2::eAllGraphics);
    memBarrier.setSrcAccessMask(vk::AccessFlagBits2::eMemoryWrite);
    memBarrier.setDstAccessMask(vk::AccessFlagBits2::eMemoryRead | vk::AccessFlagBits2::eMemoryWrite);
    cmdBuf.pipelineBarrier2(depInfo);

    draw_imgui(cmdBuf, I->swapchainImages[swapchainImageIndex].imageView);

    utils::transition_image(cmdBuf,
                            I->swapchainImages[swapchainImageIndex],
                            vk::ImageLayout::eGeneral,
                            vk::ImageLayout::ePresentSrcKHR,
                            vk::PipelineStageFlagBits2::eAllGraphics,
                            vk::PipelineStageFlagBits2::eBottomOfPipe);

    cmdBuf.end();

    vk::CommandBufferSubmitInfo cmdSubmit{};
    cmdSubmit.setDeviceMask(1);
    cmdSubmit.setCommandBuffer(cmdBuf);

    vk::SemaphoreSubmitInfo waitSem{};
    waitSem.setSemaphore(acquireSem);
    waitSem.setStageMask(vk::PipelineStageFlagBits2::eAllGraphics | vk::PipelineStageFlagBits2::eRayTracingShaderKHR);
    waitSem.setDeviceIndex(0);
    waitSem.setValue(1);

    vk::SemaphoreSubmitInfo signalSem{};
    signalSem.setSemaphore(submitSem);
    signalSem.setStageMask(vk::PipelineStageFlagBits2::eAllGraphics | vk::PipelineStageFlagBits2::eRayTracingShaderKHR);
    signalSem.setDeviceIndex(0);
    signalSem.setValue(1);

    vk::SubmitInfo2 submitInfo{};
    submitInfo.setCommandBufferInfos(cmdSubmit);
    submitInfo.setWaitSemaphoreInfos(waitSem);
    submitInfo.setSignalSemaphoreInfos(signalSem);

    I->graphicsQueue.submit2(submitInfo, nullptr);

    vk::SwapchainPresentFenceInfoKHR presentFenceInfo{};
    presentFenceInfo.setFences(renderFence);
    presentFenceInfo.setSwapchainCount(1);

    vk::PresentInfoKHR presentInfo{};
    presentInfo.setSwapchains(I->swapchain);
    presentInfo.setWaitSemaphores(submitSem);
    presentInfo.setImageIndices(swapchainImageIndex);
    presentInfo.setPNext(&presentFenceInfo);

    vk::Result presentRes = I->graphicsQueue.presentKHR(presentInfo);
    VK_CHECK_RES(presentRes);

    if (presentRes == vk::Result::eErrorOutOfDateKHR)
        shouldResize = true;

    frameNumber = (frameNumber + 1) % I->frameOverlap;
}

void Engine::raytrace(const vk::CommandBuffer& cmd)
{
    cmd.bindPipeline(vk::PipelineBindPoint::eRayTracingKHR, I->simpleRtPipeline.pipeline);

    vk::DescriptorSet uabSet = get_current_frame().descriptorSetUAB;
    vk::DescriptorSet rtSet = get_current_frame().descriptorSetRt;
    vk::ImageView imgView = get_current_frame().imageDraw.imageView;
    vk::AccelerationStructureKHR tlas = I->tlas.as.AS;

    std::vector<vk::DescriptorSet> sets = {rtSet, uabSet};

    vk::BindDescriptorSetsInfo bindInfo{};
    bindInfo.setDescriptorSets(sets);
    bindInfo.setStageFlags(vk::ShaderStageFlagBits::eRaygenKHR
                           | vk::ShaderStageFlagBits::eClosestHitKHR
                           | vk::ShaderStageFlagBits::eMissKHR);
    bindInfo.setLayout(I->simpleRtPipeline.pipelineLayout);
    bindInfo.setFirstSet(0);
    cmd.bindDescriptorSets2(bindInfo);

    vk::PushConstantsInfo pushInfo{};
    pushInfo.setLayout(I->simpleRtPipeline.pipelineLayout);
    pushInfo.setStageFlags(vk::ShaderStageFlagBits::eRaygenKHR
                           | vk::ShaderStageFlagBits::eClosestHitKHR
                           | vk::ShaderStageFlagBits::eMissKHR);
    pushInfo.setSize(sizeof(RayPush));
    pushInfo.setValues<RayPush>(rayPush);
    pushInfo.setOffset(0);
    cmd.pushConstants2(pushInfo);

    I->camera->update();

    cmd.traceRaysKHR(I->sbtHelper->rgenRegion,
                     I->sbtHelper->missRegion,
                     I->sbtHelper->hitRegion,
                     vk::StridedDeviceAddressRegionKHR{},
                     I->swapchainExtent.width,
                     I->swapchainExtent.height,
                     1);
}

void Engine::draw_imgui(const vk::CommandBuffer& cmd, const vk::ImageView& targetView)
{
    vk::RenderingAttachmentInfo colorAttach{};
    colorAttach.setImageView(targetView);
    colorAttach.setImageLayout(vk::ImageLayout::eGeneral);
    colorAttach.setLoadOp(vk::AttachmentLoadOp::eLoad);
    colorAttach.setStoreOp(vk::AttachmentStoreOp::eStore);

    vk::RenderingInfo renderInfo{};
    renderInfo.setColorAttachments(colorAttach);
    renderInfo.setLayerCount(1);
    renderInfo.setRenderArea(vk::Rect2D{vk::Offset2D{0, 0}, I->swapchainExtent});

    cmd.beginRendering(renderInfo);
    ImGui_ImplVulkan_RenderDrawData(ImGui::GetDrawData(), cmd);
    cmd.endRendering();
}

void Engine::resize()
{
    I->device.waitIdle();
    I->recreate_swapchain();
    I->recreate_draw_data();

    descUpdater->clean();
    for (const auto& f : I->frames) {
        descUpdater->add_storage_image(f.descriptorSetRt, 1, {f.imageDraw});
    }
    descUpdater->update();

    I->recreate_camera();
    shouldResize = false;
}

