namespace YimMenu
{
	ListCommandItem::ListCommandItem(joaat_t id, std::optional<std::string> label_override) :
	    m_Command(Commands::GetCommand<ListCommand>(id)),
	    m_LabelOverride(label_override)
	{
	}

	void ListCommandItem::Draw()
	{
		if (!m_Command)
		{
			ImGui::Text("Unknown list!");
			return;
		}

		int current_state = m_Command->GetState();
		auto& entries = m_Command->GetList();

		std::optional<std::string> selected_label;
		std::optional<float> combo_width;

		// First pass: determine max text width and locate current selection
		if (!selected_label.has_value() || !combo_width.has_value())
		{
			const char* widest_text = "";
			std::size_t max_len = 0;

			for (const auto& entry : entries)
			{
				if (entry.first == current_state)
					selected_label = entry.second;

				std::size_t len = strlen(entry.second);
				if (len > max_len)
				{
					widest_text = entry.second;
					max_len = len;
				}
			}

			if (!selected_label.has_value())
				selected_label = "";

			ImGuiSize size = ImGui::CalcTextSize(widest_text);
			combo_width = size.x + 40.0f;
		}

		ImGui::SetNextItemWidth(combo_width.value());

		std::string title = m_LabelOverride.has_value() ?
		                    *m_LabelOverride : m_Command->GetLabel();

		if (ImGui::BeginCombo(title.c_str(), selected_label.value().c_str()))
		{
			for (auto& entry : entries)
			{
				bool is_selected = (entry.first == current_state);

				if (ImGui::Selectable(entry.second, is_selected))
				{
					current_state = entry.first;
					m_Command->SetState(entry.first);
				}

				if (is_selected)
				{
					selected_label = entry.second; // ensure consistency
					ImGui::SetItemDefaultFocus();
				}
			}
			ImGui::EndCombo();
		}
	}
}

#include "script-output-tokenizer.hpp"
#include <utility>
#include <algorithm>
#include "ui/omni-painter/omni-painter.hpp"

// Helper: Check if character is valid inside a URL segment
static bool isUrlChar(QChar c) {
    return c.isPrint() && !c.isSpace() && c != '"' && c != '\'' && c != ')' && c != '(';
}

// Helper: Map ANSI color codes to internal color representation
static ColorLike ansiToColor(std::uint8_t code) {
    static const ColorLike palette[] = {
        QColor(Qt::transparent),     // 0
        SemanticColor::Red,          // 31
        SemanticColor::Green,        // 32
        SemanticColor::Yellow,       // 33
        SemanticColor::Blue,         // 34
        SemanticColor::Magenta,      // 35
        SemanticColor::Cyan,         // 36
        SemanticColor::TextPrimary   // default fallback
    };

    if (code == 30) return QColor(Qt::black);
    if (code == 97) return QColor(Qt::white);
    if (code >= 31 && code <= 36) return palette[code - 31];
    if (code >= 90 && code <= 97) return palette[code - 90 + 6]; // map 90..97 to white-like colors

    return SemanticColor::TextPrimary;
}

ScriptOutputTokenizer::ScriptOutputTokenizer(QStringView input) : m_input(input), m_pos(0) {}

std::optional<ScriptOutputTokenizer::Token> ScriptOutputTokenizer::advance() {
    if (m_pos >= m_input.size()) return std::nullopt;

    Token result;
    std::vector<std::uint8_t> ansiStack;

    while (m_pos < m_input.size()) {
        QChar current = m_input[m_pos];
        QStringView remaining = m_input.mid(static_cast<int>(m_pos));

        switch (m_mode) {
            case Mode::Text: {
                if (current == '\033') {
                    if (!result.text.isEmpty()) {
                        ++m_pos;
                        return result;
                    }
                    m_mode = Mode::Escaped;
                } else {
                    bool potentialLink = false;
                    for (const auto& scheme : {QStringLiteral("http://"), QStringLiteral("https://")}) {
                        if (remaining.startsWith(scheme)) {
                            potentialLink = true;
                            break;
                        }
                    }

                    if (potentialLink) {
                        m_mode = Mode::Hyperlink;
                        return result;
                    }

                    result.text.append(current);
                }
                break;
            }

            case Mode::Hyperlink: {
                if (isUrlChar(current)) {
                    result.text.append(current);
                } else {
                    result.link = true;
                    m_mode = Mode::Text;
                    return result;
                }
                break;
            }

            case Mode::Escaped: {
                if (current == '[') {
                    if (!result.text.isEmpty()) {
                        ++m_pos;
                        return result;
                    }
                    ansiStack.clear();
                    ansiStack.push_back(0);
                    m_mode = Mode::AnsiSequence;
                }
                break;
            }

            case Mode::AnsiSequence: {
                if (current.isDigit()) {
                    int digit = current.toLatin1() - '0';
                    ansiStack.back() = ansiStack.back() * 10 + digit;
                } else if (current == ';') {
                    ansiStack.push_back(0);
                } else if (current == 'm') {
                    result.style = interpretAnsi(ansiStack);
                    m_mode = Mode::Text;
                    return result;
                }
                break;
            }
        }

        ++m_pos;
    }

    return result;
}

size_t ScriptOutputTokenizer::position() const { return m_pos; }

void ScriptOutputTokenizer::setPosition(size_t pos) { m_pos = pos; }

ScriptOutputTokenizer::Style ScriptOutputTokenizer::interpretAnsi(const std::vector<std::uint8_t>& codes) {
    Style s{};
    for (auto code : codes) {
        if (code == 0) {
            s.reset = true;
        } else if (code == 1) {
            // Brightening ignored per spec
        } else if (code >= 30 && code <= 37) {
            s.foreground = OmniPainter::resolveColor(ansiToColor(code));
        } else if (code >= 40 && code <= 47) {
            s.background = OmniPainter::resolveColor(ansiToColor(code - 10));
        } else if (code >= 90 && code <= 97) {
            s.foreground = OmniPainter::resolveColor(ansiToColor(code - 60));
        }
    }
    return s;
}

QColor ScriptOutputTokenizer::resolveBg(int code) {
    return OmniPainter::resolveColor(ansiToColor(code));
}

QColor ScriptOutputTokenizer::resolveFg(std::uint8_t code) {
    return OmniPainter::resolveColor(ansiToColor(code));
}

