HgiCompareFunction _GetDepthComparisonMode(BasicLayerParams const& layerSettings [[maybe_unused]])
{
#ifdef AGP_CONTROLABLE_DEPTH_COMPOSITING
    return layerSettings.depthCompare;
#else
    return HgiCompareFunctionLEqual;
#endif
}

HgiPresentInteropHandle _ExtractInteropDestination(PresentationParams const& presentParams)
{
    if (presentParams.framebufferHandle.IsHolding<HgiPresentInteropHandle>())
    {
        return presentParams.framebufferHandle.UncheckedGet<HgiPresentInteropHandle>();
    }

#if defined(PXR_GL_SUPPORT_ENABLED)
    uint32_t fb = 0;
    if (presentParams.framebufferHandle.IsHolding<uint32_t>())
    {
        fb = presentParams.framebufferHandle.UncheckedGet<uint32_t>();
    }
    return HgiPresentGLInteropHandle{fb};
#else
    TF_WARN("OpenGL interop not supported");
    return HgiPresentNullInteropHandle{};
#endif
}

HgiPresentWindowParams _BuildWindowPresentationConfig(
    RenderBufferSettingsProvider const& renderParams, BasicLayerParams const& layerSettings)
{
    PresentationParams const& pp = renderParams.GetPresentationParams();
    HgiPresentWindowParams wp{};
    wp.wantVsync = pp.windowVsync;

    if (pp.windowHandle.IsHolding<HgiPresentWindowHandle>())
    {
        wp.window = pp.windowHandle.UncheckedGet<HgiPresentWindowHandle>();
    }
    else
    {
        TF_CODING_ERROR("Invalid window handle in PresentationParams.");
    }

    std::string const& mode = layerSettings.colorspace;
    if (mode.empty() || mode == HdxColorCorrectionTokens->disabled)
    {
        wp.srcColorSpace     = GfColorSpaceNames->LinearRec709;
        wp.surfaceColorSpace = GfColorSpaceNames->SRGBRec709;
    }
    else if (mode == HdxColorCorrectionTokens->sRGB)
    {
        wp.srcColorSpace     = GfColorSpaceNames->SRGBRec709;
        wp.surfaceColorSpace = GfColorSpaceNames->SRGBRec709;
    }
    else if (mode == HdxColorCorrectionTokens->openColorIO)
    {
        wp.srcColorSpace     = GfColorSpaceNames->Raw;
        wp.surfaceColorSpace = GfColorSpaceNames->Raw;
    }
    else
    {
        TF_CODING_ERROR("Unknown color correction mode: %s", mode.c_str());
    }

    return wp;
}

HgiPresentInteropParams _BuildInteropPresentationConfig(
    RenderBufferSettingsProvider const& renderParams, BasicLayerParams const& layerSettings)
{
    PresentationParams const& pp = renderParams.GetPresentationParams();
    GfVec2i const& size = renderParams.GetRenderBufferSize();

    HgiPresentInteropParams dst{};
    if (pp.compositionParams.IsHolding<HgiPresentCompositionParams>())
    {
        dst.composition = pp.compositionParams.UncheckedGet<HgiPresentCompositionParams>();
    }
    else
    {
        dst.composition = HgiPresentCompositionParams{};
        dst.composition.colorSrcBlendFactor = HgiBlendFactorOne;
        dst.composition.colorDstBlendFactor = HgiBlendFactorOneMinusSrcAlpha;
        dst.composition.colorBlendOp        = HgiBlendOpAdd;
        dst.composition.alphaSrcBlendFactor = HgiBlendFactorOne;
        dst.composition.alphaDstBlendFactor = HgiBlendFactorOneMinusSrcAlpha;
        dst.composition.alphaBlendOp        = HgiBlendOpAdd;
        dst.composition.depthFunc           = _GetDepthComparisonMode(layerSettings);
    }

    dst.composition.dstRegion = GfRect2i({0, 0}, size[0], size[1]);
    dst.destination           = _ExtractInteropDestination(pp);
    return dst;
}
