std::tuple<SdfPathVector, SdfPathVector> CreateDefaultTasks(
    TaskManagerPtr& taskManager,
    RenderBufferSettingsProviderWeakPtr const& renderSettings,
    LightingSettingsProviderWeakPtr const& lightingSettings,
    SelectionSettingsProviderWeakPtr const& selectionSettings,
    FnGetLayerSettings const& getLayerSettings)
{
    bool webgpuEnabled = _IsWebGPUModeActive(taskManager);
    static constexpr bool gpuCapable = true;

    SdfPathVector allTaskIds, renderPassIds;

    SdfPath visualizeAovId, presentTaskId;

    if (IsStormRenderDelegate(taskManager->GetRenderIndex()))
    {
        allTaskIds.push_back(CreateLightingTask(taskManager, lightingSettings, getLayerSettings));
        allTaskIds.push_back(CreateShadowTask(taskManager, getLayerSettings));

        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->defaultMaterialTag));
        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->masked));
        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->additive));

#if defined(DRAW_ORDER)
        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->draworder));
#endif

        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->translucent));

        if (renderSettings.lock()->IsAovSupported())
        {
            allTaskIds.push_back(CreateAovInputTask(taskManager, renderSettings));
            allTaskIds.push_back(CreateBoundingBoxTask(taskManager, renderSettings));
        }

        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->volume));

        if (renderSettings.lock()->IsAovSupported())
        {
            allTaskIds.push_back(CreateOitResolveTask(taskManager, renderSettings));
            if (!webgpuEnabled)
            {
                allTaskIds.push_back(CreateSelectionTask(taskManager, selectionSettings));
            }
            allTaskIds.push_back(CreateColorizeSelectionTask(taskManager, selectionSettings));
            allTaskIds.push_back(CreateColorCorrectionTask(taskManager, renderSettings, getLayerSettings));

            visualizeAovId = CreateVisualizeAovTask(taskManager, renderSettings);
            allTaskIds.push_back(visualizeAovId);

            presentTaskId = CreatePresentTask(taskManager, renderSettings, getLayerSettings);
            allTaskIds.push_back(presentTaskId);

            if (!webgpuEnabled)
            {
                allTaskIds.push_back(CreatePickTask(taskManager, getLayerSettings));
            }
        }
    }
    else
    {
        renderPassIds.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, TfToken()));

        if (renderSettings.lock()->IsAovSupported() && gpuCapable)
        {
            allTaskIds.push_back(CreateAovInputTask(taskManager, renderSettings));
            allTaskIds.push_back(CreateBoundingBoxTask(taskManager, renderSettings));
            allTaskIds.push_back(CreateColorizeSelectionTask(taskManager, selectionSettings));
            allTaskIds.push_back(CreateColorCorrectionTask(taskManager, renderSettings, getLayerSettings));

            visualizeAovId = CreateVisualizeAovTask(taskManager, renderSettings);
            allTaskIds.push_back(visualizeAovId);

            presentTaskId = CreatePresentTask(taskManager, renderSettings, getLayerSettings);
            allTaskIds.push_back(presentTaskId);

            allTaskIds.push_back(CreatePickFromRenderBufferTask(taskManager, selectionSettings, getLayerSettings));
        }
    }

#if defined(ADSK_OPENUSD_PENDING)
    if (!visualizeAovId.IsEmpty() && !presentTaskId.IsEmpty())
    {
        if (auto vt = taskManager->GetTask(visualizeAovId))
        {
            if (auto casted = std::dynamic_pointer_cast<HdxVisualizeAovTask>(vt))
            {
                casted->SetPresentTaskId(presentTaskId);
            }
        }
    }
#endif

    return {allTaskIds, renderPassIds};
}

std::tuple<SdfPathVector, SdfPathVector> CreateMinimalTasks(
    TaskManagerPtr& taskManager,
    RenderBufferSettingsProviderWeakPtr const& renderSettings,
    LightingSettingsProviderWeakPtr const& lightingSettings,
    FnGetLayerSettings const& getLayerSettings)
{
    SdfPathVector tasks, renders;

    tasks.push_back(CreateLightingTask(taskManager, lightingSettings, getLayerSettings));
    renders.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->defaultMaterialTag));
    renders.push_back(CreateRenderTask(taskManager, renderSettings, getLayerSettings, HdStMaterialTagTokens->additive));

    if (renderSettings.lock()->IsAovSupported())
    {
        tasks.push_back(CreateAovInputTask(taskManager, renderSettings));
        tasks.push_back(CreatePresentTask(taskManager, renderSettings, getLayerSettings));
    }

    return {tasks, renders};
}

SdfPath CreateOitResolveTask(
    TaskManagerPtr& tm, RenderBufferSettingsProviderWeakPtr const& settings)
{
    auto commitFn = [settings](TaskManager::GetTaskValueFn const& getVal,
                               TaskManager::SetTaskValueFn const& setVal)
    {
        if (auto ptr = settings.lock())
        {
            auto params = getVal(HdTokens->params).Get<HdxOitResolveTaskParams>();
#if defined(ADSK_OPENUSD_PENDING)
            params.screenSize = ptr->GetRenderBufferSize();
#endif
            setVal(HdTokens->params, VtValue(params));
        }
    };

    HdxOitResolveTaskParams init;
    init.useAovMultiSample = false;

    return tm->AddTask<HdxOitResolveTask>(_taskTokens->transparencyResolver, init, commitFn);
}

SdfPath CreateSelectionTask(
    TaskManagerPtr& tm, SelectionSettingsProviderWeakPtr const& selSettings)
{
    auto commitFn = [selSettings](TaskManager::GetTaskValueFn const& getVal,
                                  TaskManager::SetTaskValueFn const& setVal)
    {
        if (auto ptr = selSettings.lock())
        {
            auto params = getVal(HdTokens->params).Get<HdxSelectionTaskParams>();
            SelectionSettings const& s = ptr->GetSettings();
            params.enableSelectionHighlight = s.enableSelection;
            params.selectionColor           = s.selectionColor;
            params.locateColor              = s.locateColor;
            setVal(HdTokens->params, VtValue(params));
        }
    };

    HdxSelectionTaskParams init;
    init.enableSelectionHighlight = true;
    init.enableLocateHighlight    = true;
    init.selectionColor           = GfVec4f(1.f, 1.f, 0.f, 1.f);
    init.locateColor              = GfVec4f(0.f, 0.f, 1.f, 1.f);

    return tm->AddTask<HdxSelectionTask>(_taskTokens->selectionRenderer, init, commitFn);
}

SdfPath CreateColorizeSelectionTask(
    TaskManagerPtr& tm, SelectionSettingsProviderWeakPtr const& selSettings)
{
    auto commitFn = [selSettings](TaskManager::GetTaskValueFn const& getVal,
                                  TaskManager::SetTaskValueFn const& setVal)
    {
        if (auto ptr = selSettings.lock())
        {
            auto params = getVal(HdTokens->params).Get<HdxColorizeSelectionTaskParams>();
            SelectionSettings const& s = ptr->GetSettings();
            params.locateColor         = s.locateColor;
            params.enableOutline       = s.enableOutline;
            params.outlineRadius       = s.outlineRadius;
            params.enableSelectionHighlight = s.enableSelection || s.enableOutline;
            params.selectionColor      = s.selectionColor;

            SelectionBufferPaths const& paths = ptr->GetBufferPaths();
            params.primIdBufferPath     = paths.primIdBufferPath;
            params.instanceIdBufferPath = paths.instanceIdBufferPath;
            params.elementIdBufferPath  = paths.elementIdBufferPath;

            setVal(HdTokens->params, VtValue(params));
        }
    };

    HdxColorizeSelectionTaskParams init;
    init.enableSelectionHighlight = true;
    init.selectionColor           = GfVec4f(1.f, 1.f, 0.f, 1.f);
    init.locateColor              = GfVec4f(0.f, 0.f, 1.f, 1.f);

    return tm->AddTask<HdxColorizeSelectionTask>(_taskTokens->highlightOverlay, init, commitFn);
}

SdfPath CreateLightingTask(
    TaskManagerPtr& tm,
    LightingSettingsProviderWeakPtr const& lightSettings,
    FnGetLayerSettings const& getLayer)
{
    auto commitFn = [lightSettings, getLayer](TaskManager::GetTaskValueFn const&,
                                              TaskManager::SetTaskValueFn const& setVal)
    {
        if (auto ptr = lightSettings.lock())
        {
            HdxSimpleLightTaskParams p;
            p.cameraPath = getLayer()->renderParams.camera;
            p.lightExcludePaths = ptr->GetExcludedLights();
            p.enableShadows = ptr->GetShadowsEnabled();

            auto ctx = ptr->GetLightingContext();
            if (ctx)
            {
                p.sceneAmbient = ctx->GetSceneAmbient();
                p.material     = ctx->GetMaterial();
            }

            setVal(HdTokens->params, VtValue(p));
        }
    };

    return tm->AddTask<HdxSimpleLightTask>(_taskTokens->lightingController, {}, commitFn);
}

SdfPath CreateShadowTask(TaskManagerPtr& tm, FnGetLayerSettings const& getLayer)
