        }
    };

    return tm->AddTask<HdxBoundingBoxTask>(_taskTokens->boundsVisualizer, {}, commitFn);
}

SdfPath CreateAovInputTask(
    TaskManagerPtr& tm, RenderBufferSettingsProviderWeakPtr const& renderSettings)
{
    auto commitFn = [renderSettings](TaskManager::GetTaskValueFn const&,
                                     TaskManager::SetTaskValueFn const& setVal)
    {
        if (auto ptr = renderSettings.lock())
        {
            AovInputTaskParams p;
            auto const& cache = ptr->GetAovParamCache();
            p.aovBufferPath   = cache.aovBufferPath;
            p.depthBufferPath = cache.depthBufferPath;
            p.neyeBufferPath  = cache.neyeBufferPath;
            p.aovBuffer       = cache.aovBuffer;
            p.depthBuffer     = cache.depthBuffer;
            p.neyeBuffer      = cache.neyeBuffer;
            setVal(HdTokens->params, VtValue(p));
        }
    };

    return tm->AddTask<AovInputTask>(_taskTokens->aovSource, {}, commitFn);
}

SdfPath CreatePresentTask(
    TaskManagerPtr& tm,
    RenderBufferSettingsProviderWeakPtr const& renderSettings,
    FnGetLayerSettings const& getLayer)
{
    auto commitFn = [getLayer, renderSettings](TaskManager::GetTaskValueFn const&,
                                               TaskManager::SetTaskValueFn const& setVal)
    {
        if (auto ptr = renderSettings.lock())
        {
            HdxPresentTaskParams p;
#if defined(ADSK_OPENUSD_PENDING)
            auto const& pp = ptr->GetPresentationParams();
            p.enabled = getLayer()->enablePresentation;

            if (!pp.windowHandle.IsEmpty())
            {
                p.destinationParams = _BuildWindowPresentationConfig(*ptr, *getLayer());
            }
            else
            {
                p.destinationParams = _BuildInteropPresentationConfig(*ptr, *getLayer());
            }
#else
            GfVec2i const& size = ptr->GetRenderBufferSize();
            p.enabled = getLayer()->enablePresentation;
            auto const& pp = ptr->GetPresentationParams();
            p.dstApi          = pp.api;
            p.dstFramebuffer  = pp.framebufferHandle;
            p.dstRegion       = GfVec4i(0, 0, size[0], size[1]);
#endif
            setVal(HdTokens->params, VtValue(p));
        }
    };

    return tm->AddTask<HdxPresentTask>(_taskTokens->framePresenter, {}, commitFn);
}

HVT_API extern SdfPath CreateRenderTask(
    TaskManagerPtr& tm,
    RenderBufferSettingsProviderWeakPtr const& renderSettings,
    FnGetLayerSettings const& getLayer,
    TfToken const& materialTag)
{
    UpdateRenderTaskFnInput cbData;
    cbData.taskName              = GetRenderTaskPathLeaf(materialTag);
    cbData.materialTag           = materialTag;
    cbData.pTaskManager          = tm.get();
    cbData.getLayerSettings      = getLayer;

    if (materialTag == HdStMaterialTagTokens->translucent)
    {
        return CreateRenderTask<HdxOitRenderTask>(renderSettings, cbData);
    }
    else if (materialTag == HdStMaterialTagTokens->volume)
    {
        return CreateRenderTask<HdxOitVolumeRenderTask>(renderSettings, cbData);
    }

    return CreateRenderTask<HdxRenderTask>(renderSettings, cbData);
}

SdfPath CreateSkyDomeTask(
    TaskManagerPtr& tm,
    RenderBufferSettingsProviderWeakPtr const& renderSettings,
    FnGetLayerSettings const& getLayer,
    SdfPath const& atPos,
    TaskManager::InsertionOrder order)
{
    UpdateRenderTaskFnInput cbData;
    cbData.taskName              = _taskTokens->skyDomeRenderer;
    cbData.materialTag           = HdStMaterialTagTokens->defaultMaterialTag;
    cbData.pTaskManager          = tm.get();
    cbData.getLayerSettings      = getLayer;

    return CreateRenderTask<HdxSkydomeTask>(
        renderSettings, cbData, DefaultRenderTaskUpdateFn, atPos, order);
}

RenderTaskData DefaultRenderTaskUpdateFn(
    RenderBufferSettingsProvider* rbSettings,
    UpdateRenderTaskFnInput const& input)
{
    RenderTaskData out;
    out.params = input.getLayerSettings()->renderParams;
    SetBlendStateForMaterialTag(input.materialTag, out.params);
    out.params.viewport = kDefaultViewport;
    out.params.camera   = input.getLayerSettings()->renderParams.camera;

    if (!CanUseMsaa(input.materialTag))
    {
        out.params.useAovMultiSample = false;
    }

    out.params.aovBindings =
        GetDefaultAovBindings(*input.pTaskManager, input.taskName, *rbSettings);

    if (input.materialTag == HdStMaterialTagTokens->volume)
    {
        out.params.aovInputBindings = rbSettings->GetAovParamCache().aovInputBindings;
    }

    out.renderTags = input.getLayerSettings()->renderTags;
    out.collection = GetDefaultCollection(input.getLayerSettings(), input.materialTag);

    return out;
}
