extern "C" void Hook_SCURK1996_winscurkMDIClient_CycleColors(winscurkMDIClient *pThis) {
    TBC45XPalette *palettePtr;
    TBC45XClientDC clientDC;
    TBC45XMDIChild *activeMDIChild;
    HWND targetWindowOne, targetWindowTwo, targetWindowThree;
    unsigned redrawFlags;
    BOOL needsRedraw, skipChildren;

    needsRedraw = FALSE;

    // Only animate palette if window is not minimized
    if (!IsIconic(pThis->pWnd->HWindow)) {
        palettePtr = GameMain_winscurkApp_GetPalette_SCURK1996(gScurkApplication_SCURK1996);
        GameMain_BCClientDC_Construct_SCURK1996(&clientDC, pThis->pWnd->HWindow);
        GameMain_BCDC_SelectObjectPalette_SCURK1996(&clientDC, palettePtr, 0);

        // Fast color rotation logic
        if (wColFastCnt_SCURK1996 == 5) {
            GameMain_winscurkMDIClient_RotateColors_SCURK1996(pThis, 1);
            AnimatePalette((HPALETTE)palettePtr->Handle, 0xAB, 0x31, pThis->mFastColors);
            wColFastCnt_SCURK1996 = 0;
            needsRedraw = TRUE;
        }

        // Slow color rotation logic
        if (wColSlowCnt_SCURK1996 == 30) {
            GameMain_winscurkMDIClient_RotateColors_SCURK1996(pThis, 0);
            AnimatePalette((HPALETTE)palettePtr->Handle, 0xE0, 0x10, pThis->mSlowColors);
            wColSlowCnt_SCURK1996 = 0;
            needsRedraw = TRUE;
        }

        ++wColFastCnt_SCURK1996;
        ++wColSlowCnt_SCURK1996;
        GameMain_BCWindowDC_Destruct_SCURK1996(&clientDC, 0);

        // Redraw only the active MDI child to reduce flicker
        if (needsRedraw) {
            activeMDIChild = GameMain_BCMDIClient_GetActiveMDIChild_SCURK1996(pThis);
            if (activeMDIChild) {
                skipChildren = FALSE;
                targetWindowOne = nullptr;
                targetWindowTwo = nullptr;
                targetWindowThree = nullptr;

                // Determine which windows need redrawing based on active window type
                if (activeMDIChild == (TBC45XMDIChild *)pThis->mPlaceWindow) {
                    targetWindowOne = pThis->mPlaceWindow->__wndHead.pWnd->HWindow;
                    if (pThis->mPlaceWindow->pPlaceTileListDlg && pThis->mPlaceWindow->pPlaceTileListDlg->pListBox)
                        targetWindowTwo = pThis->mPlaceWindow->pPlaceTileListDlg->pListBox->HWindow;
                }
                else if (activeMDIChild == (TBC45XMDIChild *)pThis->mMoverWindow) {
                    if (pThis->mMoverWindow->pTileSourceWindow)
                        targetWindowOne = pThis->mMoverWindow->pTileSourceWindow->HWindow;
                    if (pThis->mMoverWindow->pTileWorkingWindow)
                        targetWindowTwo = pThis->mMoverWindow->pTileWorkingWindow->HWindow;
                }
                else if (activeMDIChild == (TBC45XMDIChild *)pThis->mEditWindow) {
                    skipChildren = TRUE;
                    targetWindowOne = pThis->mEditWindow->__wndHead.pWnd->HWindow;
                    if (pThis->mEditWindow->pPaintWindow)
                        targetWindowTwo = pThis->mEditWindow->pPaintWindow->HWindow;
                    if (pThis->mEditWindow->pPaletteWindow)
                        targetWindowThree = pThis->mEditWindow->pPaletteWindow->HWindow;
                }

                redrawFlags = RDW_INVALIDATE;
                if (!skipChildren)
                    redrawFlags |= RDW_ALLCHILDREN;

                if (targetWindowOne)
                    RedrawWindow(targetWindowOne, nullptr, nullptr, redrawFlags);
                if (targetWindowTwo)
                    RedrawWindow(targetWindowTwo, nullptr, nullptr, RDW_ALLCHILDREN | RDW_INVALIDATE);
                if (targetWindowThree)
                    RedrawWindow(targetWindowThree, nullptr, nullptr, RDW_ALLCHILDREN | RDW_INVALIDATE);
            }
        }
    }
}

extern "C" void __cdecl Hook_SCURK1996_DebugOut(char const *format, ...) {
    va_list args;
    int bufferSize;
    char* buffer;

    if (!IsDebugFlagSet(DEBUG_FLAG_INTERNAL))
        return;

    va_start(args, format);
    bufferSize = _vscprintf(format, args) + 1;
    buffer = (char*)malloc(bufferSize);

    if (buffer) {
        vsprintf_s(buffer, bufferSize, format, args);
        ConsoleLog(LOG_DEBUG, "0x%06X -> gDebugOut(): %s", _ReturnAddress(), buffer);
        free(buffer);
    }
    va_end(args);
}

extern "C" void __cdecl Hook_SCURK1996_PlaceTileListDlg_SetupWindow(TPlaceTileListDlg *pThis) {
    char tileString[81];
    int itemIndex, maxItems;
    int indexCounter;
    int scrollWidth, dialogRight, dialogBottom, listboxWidth, listboxHeight;
    TBC45XRect dialogRect;

    if (IsDebugFlagSet(DEBUG_FLAG_PICKPLACE))
        ConsoleLog(LOG_DEBUG, "0x%06X -> PlaceTileListDlg_SetupWindow(0x%06X)\n", _ReturnAddress(), pThis);

    strcpy_s(tileString, sizeof(tileString) - 1, "Tile");
    GameMain_BCDialog_SetupWindow_SCURK1996(pThis);

    scrollWidth = GetSystemMetrics(SM_CXHSCROLL);

    // Resize dialog first
    GetClientRect(pThis->pWnd->HWindow, &dialogRect);
    dialogRight = pThis->nMaxHitArea + scrollWidth - dialogRect.right;
    dialogBottom = pThis->nLBButtonWidth - dialogRect.bottom;

    GetWindowRect(pThis->pWnd->HWindow, &dialogRect);
    dialogRect.right += dialogRight + 8;
    dialogRect.bottom += dialogBottom + 8;

    SetWindowPos(pThis->pWnd->HWindow, HWND_TOP, 
                 dialogRect.left, dialogRect.top, 
                 dialogRect.right - dialogRect.left, dialogRect.bottom - dialogRect.top, 
                 SWP_NOZORDER | SWP_NOMOVE);

    // Resize listbox control carefully to avoid issues on Windows 11 24H2+
    listboxWidth = (dialogRect.right - dialogRect.left) - 8;
    listboxHeight = (dialogRect.bottom - dialogRect.top) - 8;

    GetClientRect(pThis->pWnd->HWindow, &dialogRect);
    SetWindowPos(pThis->pListBox->HWindow, HWND_TOP, 
                 dialogRect.left + 3, dialogRect.top + 3, 
                 listboxWidth - 4, listboxHeight + 2, 
                 SWP_NOZORDER);

    GameMain_BCWindow_HandleMessage_SCURK1996(pThis->pListBox, LB_SETCOLUMNWIDTH, pThis->nMaxHitArea, 0);

    maxItems = wTileObjects_SCURK1996[3 * pThis->mNumTiles] + wTileObjects_SCURK1996[3 * pThis->mNumTiles + 1] - 1;

    if (IsDebugFlagSet(DEBUG_FLAG_PICKPLACE))
        ConsoleLog(LOG_DEBUG, "pThis->mNumTiles(%d), maxItems(%d), pThis->nTileRow(%d)\n", 
                   pThis->mNumTiles, maxItems, pThis->nTileRow);

    for (itemIndex = wTileObjects_SCURK1996[3 * pThis->mNumTiles]; itemIndex < maxItems; itemIndex += pThis->nTileRow) {
        sprintf_s(tileString, sizeof(tileString) - 1, "Tile%04d%04d", itemIndex, itemIndex + pThis->nTileRow - 1);
        indexCounter = GameMain_BCListBox_AddString_SCURK1996(pThis->pListBox, tileString);

        if (IsDebugFlagSet(DEBUG_FLAG_PICKPLACE))
            ConsoleLog(LOG_DEBUG, "itemIndex(%d), tileString[%s], indexCounter(%d)\n", 
                       itemIndex, tileString, indexCounter);

        GameMain_BCListBox_SetItemData_SCURK1996(pThis->pListBox, indexCounter, itemIndex);
    }
}

