extern "C" void __declspec(naked) Hook_SCURK1996_MoverWindow_DisableMaximizeBox(void) {
    TBC45XWindow *windowPtr;
    __asm {
        mov eax, [ebx + 0x4]
        mov [windowPtr], eax
    }

    if (IsDebugFlagSet(DEBUG_FLAG_PLACECOPY))
        ConsoleLog(LOG_DEBUG, "0x%06X -> DisableMaximizeBox()\n", _ReturnAddress());

    if (GetSystemMetrics(SM_CXSCREEN) > 700)
        windowPtr->Attr.Style &= ~WS_MAXIMIZEBOX;
    else
        windowPtr->Attr.Style |= WS_MAXIMIZE;

    __asm {
        mov eax, windowPtr
        mov [ebx + 0x4], eax
    }
    GAMEJMP(0x44E55A);
}

