static char *L_SCURK1996_ProcessCmdLine(char *pMainPath, char *pCmdLineParms, BOOL *bValidFileEntry) {
    int argCount;
    std::string commandLineStr;
    static char fileArgument[MAX_PATH + 1];

    memset(fileArgument, 0, sizeof(fileArgument));
    commandLineStr = "\"";
    commandLineStr += pMainPath;
    commandLineStr += "\" ";
    commandLineStr += pCmdLineParms;

    std::wstring wideStr(commandLineStr.begin(), commandLineStr.end());
    LPWSTR *argArray;
    argArray = CommandLineToArgvW(wideStr.c_str(), &argCount);

    if (argArray) {
        // Extract last argument (drag-and-drop file)
        WideCharToMultiByte(CP_UTF8, 0, argArray[argCount - 1], -1, fileArgument, MAX_PATH, NULL, NULL);
        _strlwr_s(fileArgument, sizeof(fileArgument) - 1);
        free(argArray);
    }

    *bValidFileEntry = FALSE;
    if (argCount > 1) {
        if (strlen(fileArgument) > 0) {
