// Helper macro to verify uint32 hex conversion correctness
#define VERIFY_UINT32_HEX_CONVERSION(input, expected, buf)                \
  size_t len1 = StringUInt32HexInPlace((uint32_t)(input), (char*)(buf));  \
  EXPECT_EQ(len1, strlen((expected)));                                    \
  EXPECT_STREQ((buf), (expected))

// Helper macro to verify uint64 hex conversion correctness  
#define VERIFY_UINT64_HEX_CONVERSION(input, expected, buf)                \
  size_t len2 = StringUInt64HexInPlace((uint64_t)(input), (char*)(buf));  \
  EXPECT_EQ(len2, strlen((expected)));                                    \
  EXPECT_STREQ((buf), (expected))

TEST(CConversionsTest, test_uint32_hex_conversion) {
  char tempBuffer[128];

  // Test cases for 32-bit unsigned integer to hex string conversion
  VERIFY_UINT32_HEX_CONVERSION(0UL, "0", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(1UL, "1", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(9UL, "9", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(10UL, "A", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(128UL, "80", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(3254UL, "CB6", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(65535UL, "FFFF", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(65536UL, "10000", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(68863UL, "10CFF", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(465765536ULL, "1BC304A0", tempBuffer);
  VERIFY_UINT32_HEX_CONVERSION(UINT32_MAX, "FFFFFFFF", tempBuffer);
}

