    // Convert ViewMatrix_t to DirectX matrix using transposed layout
    inline XMMATRIX TransformToDirectXMatrix(const ViewMatrix_t& vm) {
        return XMMATRIX{
            vm.arrData[0][0], vm.arrData[1][0], vm.arrData[2][0], vm.arrData[3][0],
            vm.arrData[0][1], vm.arrData[1][1], vm.arrData[2][1], vm.arrData[3][1],
            vm.arrData[0][2], vm.arrData[1][2], vm.arrData[2][2], vm.arrData[3][2],
            vm.arrData[0][3], vm.arrData[1][3], vm.arrData[2][3], vm.arrData[3][3]
        };
    }

    // Helper: Print formatted text onto ImGui draw list
    void PrintText(ImDrawList* canvas, ImVec2 location, ImU32 color, const char* format, ...) {
        char buffer[512];
        va_list arguments;
        va_start(arguments, format);
        vsnprintf(buffer, sizeof(buffer), format, arguments);
        va_end(arguments);

        canvas->AddText(location, color, buffer);
    }

    // Reusable hitbox metadata cache per player slot
    struct HitboxMetadata {
        int headBoneIndex = -1;
        int footBoneIndex = -1;
        bool isReady = false;
        void* cachedModelAddress = nullptr;

        void Reset() {
            headBoneIndex = -1;
            footBoneIndex = -1;
            isReady = false;
            cachedModelAddress = nullptr;
        }
    };

    // Persistent cache array for up to 64 players
    static HitboxMetadata s_PlayerHitboxCache[64] = {};

    // Determine if point lies within view frustum (with tolerance)
    inline bool IsPointVisibleInFrustum(const Vector3& worldPos, const XMMATRIX& projection, float safetyMargin = 1.1f) {
        XMVECTOR clipCoords = XMVector4Transform(XMLoadFloat3(&worldPos), projection);
        float wComponent = XMVectorGetW(clipCoords);

        if (wComponent <= 0.001f) return false; // Behind camera plane

        float x = XMVectorGetX(clipCoords) / wComponent;
        float y = XMVectorGetY(clipCoords) / wComponent;

        return (x >= -safetyMargin && x <= safetyMargin &&
                y >= -safetyMargin && y <= safetyMargin);
    }

    void Esp::Render(ImVec2 displaySize, ImVec2 cursorPos, bool bMouseReleased, View3D* view3D) {
        auto foregroundCanvas = ImGui::GetForegroundDrawList();
        auto pEntitySystem = ::CS2::I::pGameResourceService->GetGameEntitySystem();
        auto viewMatrix = TransformToDirectXMatrix(::CS2::ViewMatrixResolver::GetViewMatrix());

        view3D->SetViewMatrix(viewMatrix);

        XMMATRIX combinedMatrix = viewMatrix;

        // Iterate through all possible player slots
        for (int index = 1; index < 65; ++index) {
            auto& entityRef = ::CS2::CGameEntitySystem::vEntityList[index];

            if (!entityRef.m_bIsValid || !entityRef.m_bIsAlive ||
                !entityRef.m_pPawn || entityRef.m_bIsLocalPlayer ||
                entityRef.m_iBoneCount <= 0 || entityRef.headBoneIdx < 0)
                continue;

            auto& cacheEntry = s_PlayerHitboxCache[index - 1];
            void* currentModelPtr = entityRef.m_pPawn->GetCModel_Imp();

            // Refresh cache only when model changes
            if (!cacheEntry.isReady || cacheEntry.cachedModelAddress != currentModelPtr) {
                auto pModelData = ::CS2::pModelManager->GetHitboxAndBoneData(
                    reinterpret_cast<::CS2::resourcesystem::CModel_Imp*>(currentModelPtr));

                auto headHbx = pModelData.m_Hitboxes["head_0"];
                auto ankleHbx = pModelData.m_Hitboxes["ankle_r"];

                cacheEntry.headBoneIndex = headHbx.m_iBoneIdx;
                cacheEntry.footBoneIndex = ankleHbx.m_iBoneIdx;
                cacheEntry.cachedModelAddress = currentModelPtr;
                cacheEntry.isReady = true;
            }

            if (cacheEntry.headBoneIndex < 0 || cacheEntry.footBoneIndex < 0)
                continue;

            auto boneArray = entityRef.m_pPawn->GetGameSceneNodeExtended()->pGameSceneNodeBonePtr->m_Bones;
            auto topPos = boneArray[cacheEntry.headBoneIndex].GetOrigin();
            auto bottomPos = boneArray[cacheEntry.footBoneIndex].GetOrigin();

            Vector3 midPoint{ topPos.x, topPos.y, (topPos.z + bottomPos.z) * 0.5f };
            if (!IsPointVisibleInFrustum(midPoint, combinedMatrix))
                continue;

            float totalHeight = topPos.z - bottomPos.z;

            // Determine border color based on team
            XMFLOAT4 outlineColor;
            if (entityRef.m_pPawn->m_iTeamNum == 2)
                outlineColor = { 235.f / 255.f, 35.f / 255.f, 0.f / 255.f, 1.0f };
            else
                outlineColor = { 0.f / 255.f, 35.f / 255.f, 235.f / 255.f, 1.0f };

            // Adjusted bounding box parameters
            Vector3 centerOffset = { midPoint.x, midPoint.y, midPoint.z + 2.0f };
            Vector3 dimensions = { 30.0f, 30.0f, totalHeight + 12.0f };

            view3D->DrawBox(centerOffset, dimensions, { 0.35f, 0.35f, 0.35f, 0.2f });
            view3D->DrawWireBox(centerOffset, dimensions, outlineColor);
        }
    }

    // World-space left-aligned health bar
    void Esp::DrawHealthBarWorldLeft(View3D* view3D, const XMFLOAT3& position, float maxHp, float curHp, const XMFLOAT3& size) {
        float ratio = curHp / maxHp;

        XMVECTOR direction = XMVectorSet(-1.0f, 0.0f, 0.0f, 0.0f);
        float offset = size.x * 0.5f + 0.5f;
        XMVECTOR basePos = XMLoadFloat3(&position) + direction * offset;

        XMFLOAT3 bgCenter;
        XMStoreFloat3(&bgCenter, basePos);
        view3D->DrawBox(bgCenter, size, { 0.35f, 0.35f, 0.35f, 0.86f });

        float filledHeight = size.z * ratio;
        XMFLOAT3 fillCenter;
        XMStoreFloat3(&fillCenter, basePos);
        fillCenter.z -= (size.z - filledHeight) / 2.0f;

        XMFLOAT4 fillColors[] = {
            { 96.f / 255, 246.f / 255, 113.f / 255, 1.0f }, // >50%
            { 247.f / 255, 214.f / 255, 103.f / 255, 1.0f }, // >25%
            { 255.f / 255, 95.f / 255, 95.f / 255, 1.0f }   // else
        };
        int colorIdx = ratio > 0.5f ? 0 : (ratio > 0.25f ? 1 : 2);

        view3D->DrawBox(fillCenter, { size.x, size.y, filledHeight }, fillColors[colorIdx]);
    }

    // Screen-aligned health bar (left of entity relative to camera)
    void Esp::DrawHealthBarScreenAligned(View3D* view3D, const XMFLOAT3& pos, float maxHp, float curHp, const XMFLOAT3& dims) {
        float ratio = curHp / maxHp;

        XMMATRIX viewMat = view3D->cpuView;
        XMVECTOR camRight = XMVectorSet(viewMat.r[0].m128_f32[0], viewMat.r[1].m128_f32[0], viewMat.r[2].m128_f32[0], 0.0f);
        XMVECTOR offset = -camRight * (dims.x * 0.5f + 0.1f);

        XMVECTOR finalPos = XMLoadFloat3(&pos) + offset;
        XMFLOAT3 center;
        XMStoreFloat3(&center, finalPos);

        float fullHeight = dims.z;
        float filledHeight = fullHeight * ratio;
        Vector3 fillCenter = { center.x, center.y, center.z - (fullHeight - filledHeight) / 2.0f };

        XMFLOAT4 colors[] = {
            { 96.f / 255, 246.f / 255, 113.f / 255, 1.0f },
            { 247.f / 255, 214.f / 255, 103.f / 255, 1.0f },
            { 255.f / 255, 95.f / 255, 95.f / 255, 1.0f }
        };
        int idx = ratio > 0.5f ? 0 : (ratio > 0.25f ? 1 : 2);

        view3D->DrawBox({ center.x, center.y, center.z }, dims, { 0.35f, 0.35f, 0.35f, 0.86f });
        view3D->DrawBox(fillCenter, { dims.x, dims.y, filledHeight }, colors[idx]);
    }

    // Top-down world-aligned health bar
    void Esp::DrawHealthBarWorld(View3D* view3D, Vector3 top, float maxHp, float curHp, Vector3 size) {
        float ratio = curHp / maxHp;
        float filledHeight = size.z * ratio;

        Vector3 fillCenter = { top.x, top.y, top.z - (size.z - filledHeight) / 2.0f };

        XMFLOAT4 colors[] = {
            { 96.f / 255, 246.f / 255, 113.f / 255, 0.10f },
            { 247.f / 255, 214.f / 255, 103.f / 255, 0.10f },
            { 255.f / 255, 95.f / 255, 95.f / 255, 0.10f }
        };
        int idx = ratio > 0.5f ? 0 : (ratio > 0.25f ? 1 : 2);

        view3D->DrawBox(fillCenter, { size.x, size.y, filledHeight }, colors[idx]);
    }
}

