// Reinterpret as 64-bit value for atomic operations
uint64_t ims_operator::as64() const {
    return *reinterpret_cast<const uint64_t*>(this);
}

void ims_operator::clear() {
    *reinterpret_cast<uint64_t*>(this) = 0;
    assert(is_xundef());
}

// Extract 24-bit unsigned integer from byte array (little-endian)
size_t ims_operator::get_u24() const {
    size_t result = u24[0];
    result |= static_cast<size_t>(u24[1]) << 8;
    result |= static_cast<size_t>(u24[2]) << 16;
    return result;
}

// Set 24-bit unsigned integer into byte array (little-endian)
void ims_operator::set_u24(size_t val) {
    assert(val < 0x1000000u);
    u24[0] = static_cast<uint8_t>(val & 0xFF);
    u24[1] = static_cast<uint8_t>((val >> 8) & 0xFF);
    u24[2] = static_cast<uint8_t>((val >> 16) & 0xFF);
}

// Interpret 24-bit value as signed integer (two’s complement)
intptr_t ims_operator::get_i24() const {
    auto raw = static_cast<intptr_t>(get_u24());
    if (raw <= 0x7FFFFF) return raw;
    return raw - static_cast<intptr_t>(0x1000000);
}

// Check if value fits in 24-bit signed range
bool ims_operator::is_i24(intptr_t val) {
    return val >= -0x800000 && val < 0x800000;
}

// Attempt to encode signed 24-bit integer; returns false on overflow
bool ims_operator::set_i24(intptr_t val) {
    if (!is_i24(val)) return false;

    u24[0] = static_cast<uint8_t>(val & 0xFF);
    u24[1] = static_cast<uint8_t>((val >> 8) & 0xFF);
    u24[2] = static_cast<uint8_t>((val >> 16) & 0xFF);

    return true;
}

// Store signed 32-bit integer directly
void ims_operator::set_i32(intptr_t val) {
    i32 = static_cast<int32_t>(val);
}

// Store unsigned 32-bit integer directly
void ims_operator::set_u32(size_t val) {
    u32 = static_cast<uint32_t>(val);
}

////////////////////////////////////////////////////////////////////////////////

// Type checks and setters
bool ims_operator::is_xempty() const { return tt == ETYPE::empty; }
void ims_operator::set_xempty() { tt = ETYPE::empty; }

bool ims_operator::is_id() const { return tt == ETYPE::id; }
void ims_operator::set_id() { tt = ETYPE::id; }

void ims_operator::set_color() { tt = ETYPE::color_style; }
void ims_operator::set_thickness() { tt = ETYPE::thickness; }
void ims_operator::set_xundef() { tt = ETYPE::undef; }
bool ims_operator::is_xundef() const { return tt == ETYPE::undef; }

bool ims_operator::is_closed() const {
    return false; // reserved for future use (e.g., unit ball)
}

bool ims_operator::is_template() const {
    return tt >= ETYPE::template_first && tt <= ETYPE::template_last;
}

// Set small integer literal
void ims_operator::set_small_int(int32_t val) {
    tt = ETYPE::number_imm;
    ts = ESUBTYPE::integer;
    i32 = val;
}

// Set rational number literal
void ims_operator::set_small_rational(int16_t num, int16_t den) {
    tt = ETYPE::number_imm;
    ts = ESUBTYPE::rational;
    r16[0] = num;
    r16[1] = den;
}

// Check for predefined normal distribution
bool ims_operator::is_distirib_def() const {
    return tt == ETYPE::distribution_int && ts == ESUBTYPE::dist_normal_def;
}

// Extract exponent from power immediate node
intptr_t ims_operator::get_pow_exponent_imm() const {
    assert(tt == ETYPE::power_imm);
    return get_i24();
}

// Extract index from index immediate node
intptr_t ims_operator::get_elem_index() const {
    assert(tt == ETYPE::index_imm);
    return get_i24();
}

// Get number of arguments for built-in function
size_t ims_operator::get_builtin_args() const {
    return built_in_func::num_args(get_builtin_func());
}

// Set reference type with offset and subtype
void ims_operator::set_reference(size_t off, ESUBTYPE st) {
    tt = ETYPE::reference;
    ts = st;
    set_u32(off);
}

// Set plain offset (used by various types)
void ims_operator::set_offset(size_t off) {
    set_u32(off);
}

// Generic setter: type + primary + secondary fields
void ims_operator::set(ETYPE t_, size_t prim, size_t sec) {
    tt = t_;
    set_u32(prim);
    set_u24(sec);
}

// Decode immediate numeric value (int or rational)
bool ims_operator::get_int_imm(int64_t& num, int64_t& den) const {
    assert(tt == ETYPE::number_imm);

    switch (ts) {
    case ESUBTYPE::integer:
        num = i32;
        den = 1;
        return true;
    case ESUBTYPE::rational:
        num = r16[0];
        den = r16[1];
        return true;
    default:
        return false;
    }
}

