// Static keyword mapping initialization
ims_static std::array<std::string, (size_t)ETYPE::min_priority> s_keywords;
ims_static ankerl::unordered_dense::map<
    std::string, ETYPE, string_view_hash_dense, std::equal_to<> > s_map;

static void init_keyword_tables() {
    static bool initialized = false;
    if (initialized) return;
    initialized = true;

    // Map each ETYPE enum to its keyword string
    for (size_t idx = 0; idx < s_keywords.size(); ++idx) {
        auto etype = static_cast<ETYPE>(idx);
        std::string kw;

        switch (etype) {
        case ETYPE::empty:				kw = "e"; break;
        case ETYPE::id:					kw = "i"; break;
        case ETYPE::pi:					kw = "pi"; break;
        case ETYPE::set_interval:		kw = "number"; break;
        case ETYPE::set_semigroup:		kw = "semigroup"; break;
        case ETYPE::set_vector:			kw = "vector"; break;
        case ETYPE::set_binary:			kw = "binary"; break;
        case ETYPE::set_permutation:	kw = "permutation"; break;
        case ETYPE::distribution_int:	kw = "integer"; break;
        case ETYPE::distribution_real:	kw = "real"; break;
        case ETYPE::companion:			kw = "companion"; break;
        case ETYPE::vector_union:		kw = "union"; break;
        case ETYPE::vector_func:		kw = ""; break;
        case ETYPE::charpoly:			kw = "charpoly"; break;
        case ETYPE::diagonal:			kw = "diagonal"; break;
        case ETYPE::exchange:			kw = "exchange"; break;
        case ETYPE::csg:				kw = "csg"; break;
        case ETYPE::inversion:			kw = "inversion"; break;
        case ETYPE::color_style:		kw = "style"; break;
        case ETYPE::thickness:			kw = "thickness"; break;
        case ETYPE::condition:			kw = "if"; break;
        case ETYPE::call:				kw = "new"; break;
        default: continue;
        }

        s_keywords[idx] = kw;
        s_map[kw] = etype;
    }
}

std::string_view ims_operator::to_string(ETYPE t) {
    init_keyword_tables();
    return s_keywords[static_cast<size_t>(t)];
}

ETYPE ims_operator::from_string(std::string_view str) {
    init_keyword_tables();

    auto it = s_map.find(str);
    if (it == s_map.end()) return ETYPE::undef;
    return it->second;
}

