// Hash combination helper
void ims_operator::hash_combine(size_t& h) const {
    boost::hash_combine(h, tt);

    switch (tt) {
    case ETYPE::reference:
    case ETYPE::unk_reference:
        boost::hash_combine(h, get_offset());
        break;
    case ETYPE::number_imm:
        boost::hash_combine(h, ts);
        boost::hash_combine(h, u32);
        break;
    case ETYPE::set_vector:
    case ETYPE::set_permutation:
    case ETYPE::call_built_in:
    case ETYPE::power_imm:
    case ETYPE::index_imm:
        boost::hash_combine(h, get_i24());
        break;
    case ETYPE::distribution_int:
    case ETYPE::distribution_real:
        boost::hash_combine(h, ts);
        break;
    default:
        break;
    }
}

// Integer comparison returning difference if unequal
template<typename T>
bool cmp_int(T v1, T v2, intptr_t& diff) {
    diff = static_cast<intptr_t>(v1) - static_cast<intptr_t>(v2);
    return diff != 0;
}

// Lexicographic comparison between two operators
intptr_t ims_operator::lexic_compare(ims_operator h1, ims_operator h2) {
    intptr_t diff = 0;

    if (cmp_int(h1.tt, h2.tt, diff)) return diff;

    switch (h1.tt) {
    case ETYPE::reference:
    case ETYPE::unk_reference:
        if (cmp_int(h1.get_offset(), h2.get_offset(), diff)) return diff;
        break;
    case ETYPE::number_imm:
        if (cmp_int(h1.ts, h2.ts, diff)) return diff;
        if (cmp_int(h1.u32, h2.u32, diff)) return diff;
        break;
    case ETYPE::set_vector:
    case ETYPE::set_permutation:
    case ETYPE::call_built_in:
    case ETYPE::power_imm:
    case ETYPE::index_imm:
        cmp_int(h1.get_i24(), h2.get_i24(), diff);
        break;
    case ETYPE::distribution_int:
    case ETYPE::distribution_real:
        if (cmp_int(h1.ts, h2.ts, diff)) return diff;
        break;
    default:
        break;
    }

    return diff;
}

// Number of data arguments required (not operator args)
size_t ims_operator::data_args() const {
    switch (tt) {
    case ETYPE::number:
        return 1;
    case ETYPE::distribution_int:
    case ETYPE::distribution_real:
        return 2;
    case ETYPE::vector_imm:
        return num_args();
    default:
        return 0;
    }
}

// Number of operator arguments (arity)
size_t ims_operator::oper_args() const {
    switch (tt) {
    // Nullary operators
    case ETYPE::reference:
    case ETYPE::unk_reference:
    case ETYPE::number_imm:
    case ETYPE::undef:
    case ETYPE::number:
    case ETYPE::vector_imm:
    case ETYPE::exchange:
    case ETYPE::inversion:
    case ETYPE::pi:
    case ETYPE::id:
    case ETYPE::empty:
    case ETYPE::this_vector:
    case ETYPE::distribution_int:
    case ETYPE::distribution_real:
        return 0;

    // Unary operators
    case ETYPE::power_imm:
    case ETYPE::index_imm:
    case ETYPE::neg:
    case ETYPE::inv:
    case ETYPE::charpoly:
    case ETYPE::set_interval:
    case ETYPE::set_vector:
    case ETYPE::set_permutation:
    case ETYPE::color_style:
    case ETYPE::thickness:
    case ETYPE::set_semigroup:
        return 1;

    // Binary operators
    case ETYPE::power:
        return 2;

    // Quaternary operators
    case ETYPE::csg:
        return 4;

    // Built-in calls
    case ETYPE::call_built_in:
        return get_builtin_args();

    // Variable-arity operators
    case ETYPE::call:
    case ETYPE::mul:
    case ETYPE::mod:
    case ETYPE::sum:
    case ETYPE::uni:
    case ETYPE::vector:
    case ETYPE::vector_func:
    case ETYPE::vector_union:
    case ETYPE::companion:
    case ETYPE::diagonal:
    case ETYPE::index:
    case ETYPE::condition:
        return num_args();

    default:
        assert(false);
        return 0;
    }
}

