{
    std::string data = args.at(0)->get<std::string>(), proxy = parseProxy(global.proxyConfig);
    writeLog(0, "Template called fetch with url '" + data + "'.", LOG_LEVEL_INFO);
    return webGet(data, proxy, global.cacheConfig);
}
