void
UUIDColumnDelegate::paint(QPainter* painter, const QStyleOptionViewItem& option,
                          const QModelIndex& index) const
{
    if (!painter)
        return;

    painter->save();

    QStyleOptionViewItem viewItemOpt = option;
    initStyleOption(&viewItemOpt, index);

    // Render background using primitive drawing
    QApplication::style()->drawControl(QStyle::CE_ItemViewItem, &viewItemOpt, painter);

    // Compute area for icon placement
    QRect targetRect = viewItemOpt.rect;
    int metric = QApplication::style()->pixelMetric(QStyle::PM_SmallIconSize);
    QPixmap pixmap = QApplication::style()->standardIcon(QStyle::SP_FileDialogDetailedView).pixmap(metric, metric);

    // Center the pixmap manually
    int x = targetRect.left() + (targetRect.width() - pixmap.width()) / 2;
    int y = targetRect.top() + (targetRect.height() - pixmap.height()) / 2;
    painter->drawPixmap(x, y, pixmap);

    painter->restore();
}

QSize
UUIDColumnDelegate::sizeHint(const QStyleOptionViewItem& option,
                             const QModelIndex& index) const
{
    Q_UNUSED(option);
    Q_UNUSED(index);

    int baseSize = QApplication::style()->pixelMetric(QStyle::PM_SmallIconSize);
    int margin = 6; // increased spacing for visual balance
    return QSize(baseSize + margin, baseSize + margin);
}

bool
UUIDColumnDelegate::editorEvent(QEvent* event, QAbstractItemModel* model,
                                const QStyleOptionViewItem& option,
                                const QModelIndex& index)
{
    if (!index.isValid())
        return false;

    QString identifier = index.data(Qt::UserRole).toString();
    if (identifier.isEmpty())
        return QStyledItemDelegate::editorEvent(event, model, option, index);

    if (event->type() != QEvent::MouseButtonRelease)
        return QStyledItemDelegate::editorEvent(event, model, option, index);

    QMouseEvent* mouseEvent = static_cast<QMouseEvent*>(event);
    if (!mouseEvent || mouseEvent->button() != Qt::LeftButton)
        return QStyledItemDelegate::editorEvent(event, model, option, index);

    QApplication::clipboard()->setText(identifier);
    QPoint globalPos = mouseEvent->globalPosition().toPoint();
    QToolTip::showText(globalPos, tr("UUID copied to clipboard."));

    return true;
}

