// Helper: assign invalid texture ID to all icons if shared ownership detected
static void clear(IconManager::Icons &icons) {
    std::string issue_list;
    bool any_issues = false;

    for (const auto& icon : icons) {
        if (icon.use_count() > 1) {
            icon->tex_id = 0;
            std::string desc = std::to_string(icon.use_count() - 1) + "x" +
                               std::to_string(icon->size.x) + "x" + std::to_string(icon->size.y);
            if (!issue_list.empty()) issue_list += ", ";
            issue_list += desc;
            any_issues = true;
        }
    }

    if (any_issues)
        BOOST_LOG_TRIVIAL(warning) << "Active icons still referenced: " << issue_list;
}

// Return state list based on raster type
static const std::vector<std::pair<int, bool>>& get_states(IconManager::RasterType type) {
    static const std::vector<std::pair<int, bool>> color{{0, false}};
    static const std::vector<std::pair<int, bool>> white{{1, false}};
    static const std::vector<std::pair<int, bool>> gray{{2, false}};
    static const std::vector<std::pair<int, bool>> mixed{
        {1, false}, // Activable
        {0, false}, // Hovered
        {2, false}  // Disabled
    };

    switch (type) {
        case IconManager::RasterType::color: return color;
        case IconManager::RasterType::white_only_data: return white;
        case IconManager::RasterType::gray_only_data: return gray;
        case IconManager::RasterType::color_wite_gray: return mixed;
        default: return color;
    }
}

// Draw transparent placeholder when icon is hovered but not fully rendered
static void draw_transparent_icon(const IconManager::Icon &icon) {
    if (!icon.is_valid()) {
        BOOST_LOG_TRIVIAL(warning) << "Attempted to draw invalid icon.";
        ImGui::Text("?");
        return;
    }

    ImVec2 uv_size(icon.br.x - icon.tl.x, icon.br.y - icon.tl.y);
    ImVec2 px_step(uv_size.x / icon.size.x, uv_size.y / icon.size.y);

    IconManager::Icon px_icon = icon;
    px_icon.tl = ImVec2(0.0f, 0.0f);
    px_icon.br = ImVec2(px_step.x, px_step.y);
    draw(px_icon);
}
} // namespace priv

