namespace {
NSVGimage* load_svg(const char* path) {
    FILE* fp = boost::nowide::fopen(path, "rb");
    if (!fp) return nullptr;

    Slic3r::ScopeGuard cleanup([fp]() { fclose(fp); });

    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    fseek(fp, 0, SEEK_SET);

    if (file_size <= 0) return nullptr;

    auto buffer = std::make_unique<char[]>(file_size + 1);
    buffer[file_size] = '\0';

    size_t bytes_read = fread(buffer.get(), 1, file_size, fp);
    if (bytes_read != static_cast<size_t>(file_size)) return nullptr;

    return nsvgParse(buffer.get(), "px", 96.0f);
}

void copy_icon_to_texture(unsigned char* dst, int dst_stride,
                          const std::vector<unsigned char>& src, int src_row_width) {
    for (int y = 0; y < src_row_width; ++y) {
        ::memcpy(dst + y * dst_stride, src.data() + y * src_row_width, src_row_width);
    }
}
} // namespace

IconManager::Icons IconManager::init(const InitTypes &input) {
    if (input.empty()) return {};

    if (m_id != 0) {
        glsafe(::glDeleteTextures(1, &m_id));
        m_id = 0;
    }

    // Compute total area needed
    int total_area = 0;
    for (const auto& item : input)
        total_area += item.size.x * item.size.y;

    int approx_dim = static_cast<int>(std::sqrt(static_cast<float>(total_area))) + 1;
    int tex_width = (approx_dim >= 4096 * 0.7f) ? 4096 :
                    (approx_dim >= 2048 * 0.7f) ? 2048 :
                    (approx_dim >= 1024 * 0.7f) ? 1024 : 512;

    const int max_height = 1024 * 32;
    std::vector<stbrp_node> nodes(tex_width);
    stbrp_context ctx;
    stbrp_init_target(&ctx, tex_width, max_height, nodes.data(), tex_width);

    ImVector<stbrp_rect> rects(input.size());
    for (size_t i = 0; i < input.size(); ++i) {
        rects[i].w = input[i].size.x;
        rects[i].h = input[i].size.y;
        rects[i].id = i;
    }

    int packed = stbrp_pack_rects(&ctx, rects.data(), rects.size());
    if (packed == 0) return {};

    ImVec2 actual_tex_size(tex_width, max_height);
    for (const auto& rect : rects) {
        float right = rect.x + rect.w;
        float bottom = rect.y + rect.h;
        if (right > actual_tex_size.x) actual_tex_size.x = right;
        if (bottom > actual_tex_size.y) actual_tex_size.y = bottom;
    }

    Icons result(input.size());
    for (size_t i = 0; i < rects.size(); ++i) {
        const auto& r = rects[i];
        if (!r.was_packed) return {};

        ImVec2 tl(r.x / actual_tex_size.x, r.y / actual_tex_size.y);
        ImVec2 br((r.x + r.w) / actual_tex_size.x, (r.y + r.h) / actual_tex_size.y);

        Icon icon{input[i].size, tl, br};
        result[i] = std::make_shared<Icon>(std::move(icon));
    }

    NSVGrasterizer* rasterizer = nsvgCreateRasterizer();
    if (!rasterizer) return {};
    Slic3r::ScopeGuard raster_cleanup([rasterizer]() { nsvgDeleteRasterizer(rasterizer); });

    const int channels = 4;
    int total_pixels = static_cast<int>(actual_tex_size.x * actual_tex_size.y);
    std::vector<unsigned char> tex_data(total_pixels * channels, 0);

    // Group inputs by filepath to minimize parsing
    std::vector<size_t> indices(input.size());
    for (size_t i = 0; i < input.size(); ++i) indices[i] = i;

    std::sort(indices.begin(), indices.end(),
              [&input](size_t a, size_t b) { return input[a].filepath < input[b].filepath; });

    for (size_t idx : indices) {
        const auto& item = input[idx];
        if (item.filepath.empty()) continue;

        if (!boost::filesystem::exists(item.filepath)) continue;
        if (!boost::algorithm::iends_with(item.filepath, ".svg")) continue;

        NSVGimage* svg = load_svg(item.filepath.c_str());
        if (!svg) return {};

        Slic3r::ScopeGuard svg_cleanup([svg]() { nsvgDelete(svg); });

        float scale = item.size.y / svg->height;
        if (!Slic3r::is_approx(scale, item.size.y / svg->width)) continue;

        const stbrp_rect& rect = rects[idx];
        int icon_pixels = rect.w * rect.h;
        std::vector<unsigned char> icon_rgba(icon_pixels * channels, 0);

        nsvgRasterize(rasterizer, svg, 0, 0, scale,
                      icon_rgba.data(), rect.w, rect.h, rect.w * channels);

        // Convert non-black pixels to white or gray as requested
        if (item.type == RasterType::white_only_data || item.type == RasterType::gray_only_data) {
            unsigned char val = (item.type == RasterType::white_only_data) ? 255 : 127;
            for (int p = 0; p < icon_pixels; ++p) {
                int base = p * channels;
                if (icon_rgba[base] != 0 || icon_rgba[base+1] != 0 || icon_rgba[base+2] != 0) {
                    icon_rgba[base] = icon_rgba[base+1] = icon_rgba[base+2] = val;
                }
            }
        }

        int start_offset = (rect.y * static_cast<int>(actual_tex_size.x) + rect.x) * channels;
        int stride = static_cast<int>(actual_tex_size.x) * channels;
        copy_icon_to_texture(tex_data.data() + start_offset, stride, icon_rgba, rect.w * channels);
    }

    if (m_id != 0) glsafe(::glDeleteTextures(1, &m_id));

    glsafe(::glPixelStorei(GL_UNPACK_ALIGNMENT, 1));
    glsafe(::glGenTextures(1, &m_id));
    glsafe(::glBindTexture(GL_TEXTURE_2D, m_id));
    glsafe(::glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MIN_FILTER, GL_LINEAR));
    glsafe(::glTexParameteri(GL_TEXTURE_2D, GL_TEXTURE_MAG_FILTER, GL_LINEAR));
    glsafe(::glTexImage2D(GL_TEXTURE_2D, 0, GL_RGBA,
                          static_cast<GLsizei>(actual_tex_size.x),
                          static_cast<GLsizei>(actual_tex_size.y),
                          0, GL_RGBA, GL_UNSIGNED_BYTE, tex_data.data()));
    glsafe(::glBindTexture(GL_TEXTURE_2D, 0));

    for (auto& icon_ptr : result)
        icon_ptr->tex_id = m_id;

    return result;
}

std::vector<IconManager::Icons> IconManager::init(const std::vector<std::string>& paths,
                                                  const ImVec2& size,
                                                  RasterType type) {
    if (paths.empty() || size.x < 1 || size.x >= 256 * 16) return {};
    if (size.x != size.y) return {}; // only square icons supported

    unsigned int dim = static_cast<unsigned int>(std::round(size.x));
    if (size.x != static_cast<float>(dim)) return {};

    const auto& states = priv::get_states(type);
    bool compressed = false;
    bool loaded = m_icons_texture.load_from_svg_files_as_sprites_array(paths, states, dim, compressed);

    if (!loaded ||
        static_cast<size_t>(m_icons_texture.get_width()) < (states.size() * dim) ||
        static_cast<size_t>(m_icons_texture.get_height()) < (paths.size() * dim)) {
        m_icons_texture.reset();
        return {};
    }

    std::vector<Icons> result;
    result.reserve(paths.size());

    float tex_h = static_cast<float>(m_icons_texture.get_height());
    float tex_w = static_cast<float>(m_icons_texture.get_width());

    Icon base_icon;
    base_icon.tex_id = m_icons_texture.get_id();
    base_icon.size = size;

    for (size_t file_idx = 0; file_idx < paths.size(); ++file_idx) {
        Icons file_icons;
        file_icons.reserve(states.size());

        unsigned start_y = file_idx * (dim + 1) + 1;
        float y1 = start_y / tex_h;
        float y2 = (start_y + dim) / tex_h;

        for (size_t state_idx = 0; state_idx < states.size(); ++state_idx) {
            unsigned start_x = state_idx * (dim + 1) + 1;
            float x1 = start_x / tex_w;
            float x2 = (start_x + dim) / tex_w;

            auto icon = std::make_shared<Icon>(base_icon);
            icon->tl = ImVec2(x1, y1);
            icon->br = ImVec2(x2, y2);

            file_icons.push_back(icon);
            m_icons.push_back(icon);
        }

        result.emplace_back(std::move(file_icons));
    }

    return result;
}

