namespace Slic3r::GUI {
void draw(const IconManager::Icon &icon, const ImVec2 &size, const ImVec4 &tint_col, const ImVec4 &border_col) {
    if (!icon.is_valid()) {
        BOOST_LOG_TRIVIAL(warning) << "Invalid icon passed to draw().";
        ImGui::Text("?");
        return;
    }

    ImTextureID tex_id = reinterpret_cast<ImTextureID>(static_cast<intptr_t>(icon.tex_id));
    ImVec2 final_size = (size.x < 1 || size.y < 1) ? icon.size : size;

    ImGui::Image(tex_id, final_size, icon.tl, icon.br, tint_col, border_col);
}

bool clickable(const IconManager::Icon &normal, const IconManager::Icon &hover) {
    ImGuiWindow* win = ImGui::GetCurrentWindow();
    float cursor_x = ImGui::GetCursorPosX() - win->DC.GroupOffset.x - win->DC.ColumnsOffset.x;

    priv::draw_transparent_icon(normal);
    ImGui::SameLine(cursor_x);

    bool hovered = ImGui::IsItemHovered();
    if (hovered) draw(hover);
    else         draw(normal);

    return ImGui::IsItemClicked();
}

bool button(const IconManager::Icon &activ, const IconManager::Icon &hover,
            const IconManager::Icon &disable, bool disabled) {
    if (disabled) {
        draw(disable);
        return false;
    }
    return clickable(activ, hover);
}
} // namespace Slic3r::GUI

