namespace X11DPI {
    typedef struct _XDisplay Display;
    using XOpenDisplayPtr = Display* (*)(const char*);
    using XGetDefaultPtr = char* (*)(Display*, const char*, const char*);
    using XCloseDisplayPtr = int (*)(Display*);
}

SDL2DisplayBackend::SDL2DisplayBackend()
{
    if (SDL_Init(SDL_INIT_VIDEO | SDL_INIT_EVENTS | SDL_INIT_JOYSTICK | SDL_INIT_GAMECONTROLLER) != 0)
        throw std::runtime_error(std::string("Unable to initialize SDL: ") + SDL_GetError());

    SDL2DisplayWindow::PaintEventNumber = SDL_RegisterEvents(1);

#if !defined(WIN32) && !defined(__APPLE__)
    // Attempt to detect DPI via X11 when using X11 backend
    const char* videoDriver = SDL_GetCurrentVideoDriver();
    if (videoDriver && std::string(videoDriver) == "x11") {
        void* libX11 = dlopen("libX11.so", RTLD_NOW | RTLD_LOCAL);
        if (libX11) {
            auto openDisplay = reinterpret_cast<X11DPI::XOpenDisplayPtr>(dlsym(libX11, "XOpenDisplay"));
            auto getDefault = reinterpret_cast<X11DPI::XGetDefaultPtr>(dlsym(libX11, "XGetDefault"));
            auto closeDisplay = reinterpret_cast<X11DPI::XCloseDisplayPtr>(dlsym(libX11, "XCloseDisplay"));

            if (openDisplay && getDefault && closeDisplay) {
                Display* display = openDisplay(nullptr);
                if (display) {
                    char* dpiStr = getDefault(display, "Xft", "dpi");
                    if (dpiStr) {
                        int rawDpi = std::atoi(dpiStr);
                        if (rawDpi > 0) {
                            UIScale = static_cast<double>(rawDpi) / 96.0;
                        }
                    }
                    closeDisplay(display);
                }
            }
            dlclose(libX11);
        }
    }
#endif

    // Initialize game controllers
    int numJoysticks = SDL_GetNumJoysticks();
    int index = 0;
    while (index < numJoysticks) {
        if (SDL_GameControllerOpen(index)) {
            ++index;
        } else {
            // Skip failed opens silently or log if needed
            ++index;
        }
    }
}

