// Main client/server runner
int run_client(const char* server_host) {
  if (!server_host) return -10;

  Client client(server_host);
  NdbSocket& plainSocket = client.connectPlain();
  NdbSocket& tlsSocket = client.connectTLS();

  std::vector<ClientTest*> tests = {
      new SendRecvTest(plainSocket, "plain", true),
      new SendRecvTest(tlsSocket, "tls", false),
      new ReadLineTest(plainSocket, "plain readline"),
      new ReadLineTest(tlsSocket, "tls readline"),
      new KeyUpdateTest(tlsSocket, "key update"),
      new SendTest(plainSocket, "plain send"),
      new SendTest(tlsSocket, "tls send"),
      new WritevTest(plainSocket, "plain writev", 4096),
      new WritevTest(tlsSocket, "tls writev", 4096),
      new BigWritevTest(plainSocket, "plain big writev"),
      new BigWritevTest(tlsSocket, "tls big writev")};

  if (false /* opt_list */) {
    for (size_t i = 0; i < tests.size(); ++i) {
      tests[i]->printName(i + 1);
      puts("");
    }
    return 0;
  }

  // Run warmups
  if (true /* !opt_skip_warmup */) {
    WarmupTest(plainSocket).execute(0);
    WarmupTest(tlsSocket).execute(1);
    puts("");
  }

  int finalResult = 0;
  for (size_t i = 0; i < tests.size(); ++i) {
    finalResult = tests[i]->execute(i + 1);
  }

  for (auto t : tests) delete t;
  client.disconnect();
  return finalResult;
}

void run_server(bool standalone = false) {
  // Simulate server startup
  PlainService* s1 = new PlainService(false);
