int main(int argc, char** argv) {
  char exePath[PATH_MAX] = {0};
  platform_specific(exePath, argv);

  // Simulate option parsing
  const char* serverHost = nullptr;
  bool isServer = false;

  for (int i = 1; i < argc; ++i) {
    if (strcmp(argv[i], "--server") == 0) {
      isServer = true;
    } else if (strcmp(argv[i], "--host") == 0 && i + 1 < argc) {
      serverHost = argv[++i];
    }
  }

  if (isServer) {
    run_server();
  } else if (serverHost) {
    return run_client(serverHost);
  } else {
    run_server(true);
  }

  return 0;
}

