size_t SPrintArg(char* out_buffer, size_t buffer_capacity, voidptr_t sp, u8 type_code)
{
    int written = 0;
    *out_buffer = '\0';

    if (type_code == c_m3Type_i32)
        written = snprintf(out_buffer, buffer_capacity, "%" PRIi32, *(i32*)sp);
    else if (type_code == c_m3Type_i64)
        written = snprintf(out_buffer, buffer_capacity, "%" PRIi64, *(i64*)sp);

#if d_m3HasFloat
    else if (type_code == c_m3Type_f32)
        written = snprintf(out_buffer, buffer_capacity, "%" PRIf32, *(f32*)sp);
    else if (type_code == c_m3Type_f64)
        written = snprintf(out_buffer, buffer_capacity, "%" PRIf64, *(f64*)sp);
#endif

    written = M3_MAX(0, written);
    return written;
}

cstr_t SPrintFunctionArgList(IM3Function func, m3stack_t sp)
{
    static char buffer[256];
    char* pos = buffer;
    const char* end = buffer + sizeof(buffer) - 1;

    int len = snprintf(pos, end - pos, "(");
    pos += M3_MAX(0, len);

    u64* arg_sp = (u64*)sp;
    IM3FuncType ftype = func->funcType;

    if (ftype)
    {
        u32 argcnt = ftype->numArgs;
        for (u32 idx = 0; idx < argcnt; ++idx)
        {
            u8 typ = d_FuncArgType(ftype, idx);
            len = snprintf(pos, end - pos, "%s: ", c_waTypes[typ]);
            pos += M3_MAX(0, len);

            pos += SPrintArg(pos, end - pos, arg_sp + idx, typ);

            if (idx != argcnt - 1)
            {
                len = snprintf(pos, end - pos, ", ");
                pos += M3_MAX(0, len);
            }
        }
    }
    else
    {
        printf("null signature");
    }

    len = snprintf(pos, end - pos, ")");
    pos += M3_MAX(0, len);

    return buffer;
}
#endif // DEBUG || strace >= 2

