static OpInfo find_operation_info(IM3Operation op)
{
    OpInfo result = { NULL, 0 };

    if (!op)
        return result;

    for (u32 opc = 0; opc <= 0xff; ++opc)
    {
        IM3OpInfo oi = GetOpInfo(opc);
        if (oi->type != c_m3Type_unknown)
        {
            for (u32 slot = 0; slot < 4; ++slot)
            {
                if (oi->operations[slot] == op)
                {
                    result.info = oi;
                    result.opcode = opc;
                    break;
                }
            }
        }
        else
            break;
    }

    return result;
}

#undef fetch
#define fetch(TYPE) (* (TYPE *) ((*o_pc)++))

#define d_m3Decoder(FUNC) void Decode_##FUNC(char * o_str, u8 i_opcode, IM3Operation i_op, IM3OpInfo i_info, pc_t * o_pc)

d_m3Decoder(Call)
{
    void* fn_ptr = fetch(void*);
    i32 stack_off = fetch(i32);
    sprintf(o_str, "%p; stack-offset: %d", fn_ptr, stack_off);
}

d_m3Decoder(Entry)
{
    IM3Function func = fetch(IM3Function);
    sprintf(o_str, "%s", m3_GetFunctionName(func));
}

d_m3Decoder(f64_Store)
{
    if (i_operation == i_opInfo->operations[0])
    {
        u32 operand = fetch(u32);
        u32 imm_offset = fetch(u32);
        sprintf(o_str, "offset= slot:%d + immediate:%d", operand, imm_offset);
    }
}

d_m3Decoder(Branch)
{
    void* target = fetch(void*);
    sprintf(o_str, "%p", target);
}

d_m3Decoder(BranchTable)
{
    u32 slot = fetch(u32);
    o_string += sprintf(o_string, "slot: %" PRIu32 "; targets: ", slot);

    i32 num_targets = fetch(i32);
    for (i32 t = 0; t < num_targets; ++t)
    {
        pc_t addr = fetch(pc_t);
        o_string += sprintf(o_string, "%" PRIi32 "=%p, ", t, addr);
    }

    pc_t default_addr = fetch(pc_t);
    sprintf(o_string, "def=%p ", default_addr);
}

d_m3Decoder(Const)
{
    u64 value = fetch(u64);
    i32 offset = fetch(i32);
    sprintf(o_str, " slot [%d] = %" PRIu64, offset, value);
}

#undef fetch

void DecodeOperation(char* out_str, u8 opcode, IM3Operation op, IM3OpInfo info, pc_t* pc)
{
    #define d_m3Decode(OPC, FUNC) case OPC: Decode_##FUNC(out_str, opcode, op, info, pc); break;
    switch (opcode)
    {
        d_m3Decode(0xc5, Entry)
        d_m3Decode(c_waOp_call, Call)
        d_m3Decode(c_waOp_branch, Branch)
        d_m3Decode(c_waOp_branchTable, BranchTable)
        d_m3Decode(0x39, f64_Store)
    }
    #undef d_m3Decode
}

void dump_code_page(IM3CodePage page, pc_t start_pc)
{
    m3log(code, "code page seq: %d", page->info.sequence);
    pc_t pc = start_pc ? start_pc : GetPageStartPC(page);
    pc_t end = GetPagePC(page);

    m3log(code, "---------------------------------------------------------------------------------------");

    while (pc < end)
    {
        pc_t instr_pc = pc;
        IM3Operation op = (IM3Operation)(*pc++);
        OpInfo oi = find_operation_info(op);

        if (oi.info)
        {
            char info_str[8 * 1024] = { 0 };
            DecodeOperation(info_str, oi.opcode, op, oi.info, &pc);
            m3log(code, "%p | %20s  %s", instr_pc, oi.info->name, info_str);
        }
        else
        {
            m3log(code, "%p | %p", instr_pc, op);
        }
    }

    m3log(code, "---------------------------------------------------------------------------------------");
    m3log(code, "free-lines: %d", page->info.numLines - page->info.lineIndex);
}

void dump_type_stack(IM3Compilation comp)
{
    i32 reg_state[2] = { (i32)IsRegisterAllocated(comp, 0), (i32)IsRegisterAllocated(comp, 1) };

    d_m3Log(stack, "\n");
    d_m3Log(stack, "        ");
    printf("%s %s    ", reg_state[0] ? "(r0)" : "    ", reg_state[1] ? "(fp0)" : "     ");
    printf("\n");

    for (u16 pass = 1; pass <= 2; ++pass)
    {
        d_m3Log(stack, "        ");
        for (u16 idx = 0; idx < comp->stackIndex; ++idx)
        {
            if (idx > 0 && idx == comp->stackFirstDynamicIndex)
                printf("#");
            if (idx == comp->block.blockStackIndex)
                printf(">");

            const char* type_tag = c_waCompactTypes[comp->typeStack[idx]];
            const char* loc_tag = "";
            i32 slot_val = comp->wasmStack[idx];

            if (IsRegisterSlotAlias(slot_val))
            {
                bool is_fp = IsFpRegisterSlotAlias(slot_val);
                loc_tag = is_fp ? "/f" : "/r";
                reg_state[is_fp]--;
                slot_val = -1;
            }
            else
            {
                if (slot_val < comp->slotFirstDynamicIndex)
                {
                    if (slot_val >= comp->slotFirstConstIndex)
                        loc_tag = "c";
                    else if (slot_val >= comp->function->numRetAndArgSlots)
                        loc_tag = "L";
                    else
                        loc_tag = "a";
                }
            }

            char item_str[100];
            if (slot_val >= 0)
                sprintf(item_str, "%s%s%d", type_tag, loc_tag, slot_val);
            else
                sprintf(item_str, "%s%s", type_tag, loc_tag);

            if (pass == 1)
            {
                size_t orig_len = strlen(item_str);
                sprintf(item_str, "%d", idx);
                while (strlen(item_str) < orig_len)
                    strcat(item_str, " ");
            }

            printf("|%s ", item_str);
        }
        printf("\n");
    }

    u16 max_slot = GetMaxUsedSlotPlusOne(comp);
    if (max_slot > comp->slotFirstDynamicIndex)
    {
        d_m3Log(stack, "                      -");
        for (u16 s = comp->slotFirstDynamicIndex; s < max_slot; ++s)
            printf("----");
        printf("\n");

        d_m3Log(stack, "                 slot |");
        for (u16 s = comp->slotFirstDynamicIndex; s < max_slot; ++s)
            printf("%3d|", s);
        printf("\n");

        d_m3Log(stack, "                alloc |");
        for (u16 s = comp->slotFirstDynamicIndex; s < max_slot; ++s)
            printf("%3d|", comp->m3Slots[s]);
        printf("\n");
    }

    d_m3Log(stack, "\n");
}

static const char* GetOpcodeIndentation(i32 depth)
{
    depth += 1;
    if (depth < 0) depth = 0;

    static const char spaces[] = ".......................................................................................";
    const char* indent = spaces + strlen(spaces);
    indent -= (depth * 2);
    if (indent < spaces)
        indent = spaces;
    return indent;
}

const char* get_indention_string(IM3Compilation comp)
{
    return GetOpcodeIndentation(comp->block.depth + 4);
}

void log_opcode(IM3Compilation comp, m3opcode_t opcode)
{
    i32 depth = comp->block.depth;
    if (opcode == c_waOp_end || opcode == c_waOp_else)
        depth--;

    m3log(compile, "%4d | 0x%02x  %s %s",
          comp->numOpcodes++, opcode,
          GetOpcodeIndentation(depth),
          GetOpInfo(opcode)->name);
}

void log_emit(IM3Compilation comp, IM3Operation op)
{
    OpInfo oi = find_operation_info(op);
    d_m3Log(emit, "");

    if (oi.info)
    {
        printf("%p: %s\n", GetPagePC(comp->page), oi.info->name);
    }
    else
    {
        printf("not found: %p\n", op);
    }
}

