typedef struct M3ProfilerSlot
{
    cstr_t      opName;
    u64         hitCount;
} M3ProfilerSlot;

static M3ProfilerSlot s_opProfilerCounts[d_m3ProfilerSlotMask + 1] = {};

void ProfileHit(cstr_t op_name)
{
    u64 ptr = (u64)op_name;
    M3ProfilerSlot* slot = &s_opProfilerCounts[ptr & d_m3ProfilerSlotMask];

    if (slot->opName)
    {
        if (slot->opName != op_name)
        {
            m3_Abort("profiler slot collision; increase d_m3ProfilerSlotMask");
        }
    }

    slot->opName = op_name;
    slot->hitCount++;
}

void m3_PrintProfilerInfo()
{
    M3ProfilerSlot dummy;
    M3ProfilerSlot* max_slot = &dummy;

    do
    {
        max_slot->hitCount = 0;
        for (u32 i = 0; i <= d_m3ProfilerSlotMask; ++i)
        {
            M3ProfilerSlot* slot = &s_opProfilerCounts[i];
            if (slot->opName)
            {
                if (slot->hitCount > max_slot->hitCount)
                    max_slot = slot;
            }
        }

        if (max_slot->opName)
        {
            fprintf(stderr, "%13llu  %s\n", max_slot->hitCount, max_slot->opName);
            max_slot->opName = NULL;
        }
    } while (max_slot->hitCount);
}

