            iCompoundProps[0].getPropertyHeader("visible");
    stitchScalarProp(*propHeaderPtr, iCompoundProps, oCompoundProp, iTimeMap);
}

// Generic template to extract geometry parameter samples
template< class IPARAM, class IPARAMSAMP, class OPARAMSAMP >
void extractGeomParamSample(IPARAM & iGeomParam, IPARAMSAMP & iGeomSamp,
                          OPARAMSAMP & oGeomSamp, index_t iIndex)
{
    if (iGeomParam.isIndexed())
    {
        iGeomParam.getIndexed(iGeomSamp, iIndex);
        oGeomSamp.setVals(*(iGeomSamp.getVals()));
        oGeomSamp.setScope(iGeomSamp.getScope());
        oGeomSamp.setIndices(*(iGeomSamp.getIndices()));
    }
    else
    {
        iGeomParam.getExpanded(iGeomSamp, iIndex);
        oGeomSamp.setVals(*(iGeomSamp.getVals()));
        oGeomSamp.setScope(iGeomSamp.getScope());
    }
}

// Initialize output schema and validate input consistency
template< class IData, class IDataSchema, class OData, class ODataSchema >
void setup(std::vector< IObject > & iObjects, OObject & oParentObj,
           ODataSchema & oSchema, const TimeAndSamplesMap & iTimeMap,
           std::size_t & oTotalSamples)
{
    // Locate first valid input object
    IObject inObj;
    for (std::size_t i = 0; i < iObjects.size(); ++i)
    {
        if (iObjects[i].valid())
        {
            inObj = iObjects[i];
            break;
        }
    }

    const std::string fullNodeName = inObj.getFullName();

    // Extract schema and time sampling from first object
    IDataSchema iSchema0 = IData(inObj, Alembic::Abc::kWrapExisting).getSchema();
    TimeSamplingPtr tsPtr0 = iTimeMap.get(iSchema0.getTimeSampling(),
                                          oTotalSamples);
    TimeSamplingType tsType0 = tsPtr0->getTimeSamplingType();
    checkAcyclic(tsType0, fullNodeName);

    // Prepare compound property vectors
    ICompoundPropertyVec iCompoundProps;
    iCompoundProps.reserve(iObjects.size());
    ICompoundPropertyVec iArbGeomCompoundProps;
    iArbGeomCompoundProps.reserve(iObjects.size());
    ICompoundPropertyVec iUserCompoundProps;
    iUserCompoundProps.reserve(iObjects.size());
    ICompoundPropertyVec iSchemaProps;
    iSchemaProps.reserve(iObjects.size());

    // Handle child bounds property
    Abc::IBox3dProperty childBounds = iSchema0.getChildBoundsProperty();
    TimeSamplingPtr ctsPtr0;
    TimeSamplingType ctsType0;
    if (childBounds)
    {
        ctsPtr0 = childBounds.getTimeSampling();
        ctsType0 = ctsPtr0->getTimeSamplingType();
        std::string nameAndBounds = fullNodeName + " child bounds";
        checkAcyclic(ctsType0, nameAndBounds);
    }

    bool hasVisible = inObj.getProperties().getPropertyHeader("visible") != NULL;

    // Validate all objects have compatible time sampling
    for (size_t i = 0; i < iObjects.size(); i++)
    {
        if (!iObjects[i].valid())
        {
            continue;
        }

        IDataSchema iSchema =
            IData(iObjects[i], Alembic::Abc::kWrapExisting).getSchema();
        TimeSamplingPtr tsPtr = iSchema.getTimeSampling();
        TimeSamplingType tsType = tsPtr->getTimeSamplingType();
        checkAcyclic(tsType, fullNodeName);

        if (!(tsType0 == tsType))
        {
            std::cerr << "Incompatible sampling type for node \"" 
                << fullNodeName << "\"" << std::endl;

            if (tsType.getNumSamplesPerCycle() != tsType0.getNumSamplesPerCycle())
            {
                std::cerr << "\tnumSamplesPerCycle mismatch" << std::endl;
            }
            if (tsType.getTimePerCycle() != tsType0.getTimePerCycle())
            {
                std::cerr << "\ttimePerCycle mismatch" << std::endl;
            }
            exit(1);
        }

        ICompoundProperty cp = iObjects[i].getProperties();
        iCompoundProps.push_back(cp);

        ICompoundProperty arbProp = iSchema.getArbGeomParams();
        if (arbProp)  
            iArbGeomCompoundProps.push_back(arbProp);

        ICompoundProperty userProp = iSchema.getUserProperties();
        if (userProp)  
            iUserCompoundProps.push_back(userProp);

        Abc::IBox3dProperty childBounds = iSchema.getChildBoundsProperty();
        TimeSamplingPtr ctsPtr;
        TimeSamplingType ctsType;
        if (childBounds)
        {
            ctsPtr = childBounds.getTimeSampling();
            ctsType = ctsPtr->getTimeSamplingType();
            iSchemaProps.push_back(iSchema);
        }

        if (!(ctsType0 == ctsType))
        {
            std::cerr << "Incompatible child bounds sampling on \"" 
                << fullNodeName << "\"" << std::endl;

            if (ctsType.getNumSamplesPerCycle() != ctsType0.getNumSamplesPerCycle())
            {
                std::cerr << "\tnumSamplesPerCycle mismatch" << std::endl;
            }
            if (ctsType.getTimePerCycle() != ctsType0.getTimePerCycle())
            {
                std::cerr << "\ttimePerCycle mismatch" << std::endl;
            }
            if (!ctsPtr0 || !ctsPtr)
            {
                std::cerr << "\tchild bounds missing on some archives" << std::endl;
            }
            exit(1);
        }
    }

    // Create output object and schema
    OData oData(oParentObj, inObj.getName(), tsPtr0);
    oSchema = oData.getSchema();

    // Transfer visibility property if present
    if (hasVisible)
    {
        OCompoundProperty oCompoundProp = oData.getProperties();
        transferVisibility(iCompoundProps, oCompoundProp, iTimeMap);
    }

    // Transfer arbitrary geometry properties
    if (iArbGeomCompoundProps.size() == iObjects.size())
    {
        OCompoundProperty oArbGeomCompoundProp = oSchema.getArbGeomParams();
        stitchCompoundProp(iArbGeomCompoundProps, oArbGeomCompoundProp, iTimeMap);
    }

    // Transfer user properties
    if (iUserCompoundProps.size() == iObjects.size())
    {
        OCompoundProperty oUserCompoundProp = oSchema.getUserProperties();
        stitchCompoundProp(iUserCompoundProps, oUserCompoundProp, iTimeMap);
    }

    // Transfer child bounds if available
    if (!iSchemaProps.empty())
    {
        stitchScalarProp(childBounds.getHeader(), iSchemaProps, oSchema, iTimeMap);
    }
}

}

#include "ggml-backend-impl.h"
#if defined(__s390x__)
#include <sys/auxv.h>

// Define hardware capability flags if not already defined
#ifndef HWCAP_VXRS_EXT2
#define HWCAP_VXRS_EXT2 (1U << 15)
#endif
#ifndef HWCAP_NNPA
#define HWCAP_NNPA (1U << 20)
#endif

// Structure to capture s390x CPU features at runtime
struct s390x_cpu_caps {
    bool vxrs_ext2_present = false;
    bool nnpa_present      = false;

    s390x_cpu_caps() {
        unsigned long hwcap_val = getauxval(AT_HWCAP);
        // Check for vector extensions (VXE2) and NNPA support
        vxrs_ext2_present = (hwcap_val & HWCAP_VXRS_EXT2) != 0;
        nnpa_present      = (hwcap_val & HWCAP_NNPA)     != 0;
    }
};

// Compute a compatibility score based on available features
static int ggml_backend_cpu_s390x_score() {
    int result = 1;  // Base score

    s390x_cpu_caps caps;

#ifdef GGML_USE_VXE2
    if (!caps.vxrs_ext2_present) {
        return 0;
    }
    result += (1 << 1);
#endif

#ifdef GGML_USE_NNPA
    if (!caps.nnpa_present) {
        return 0;
    }
    result += (1 << 2);
#endif

    return result;
}

GGML_BACKEND_DL_SCORE_IMPL(ggml_backend_cpu_s390x_score)
#endif  // __s390x__

#include "facade.h"
#include "transformmatrixbuilder.h"

Facade::Facade(std::unique_ptr<BaseFileReader> inputReader, std::unique_ptr<SceneDrawerBase> renderer)
    : fileReader(std::move(inputReader)), sceneDrawer(std::move(renderer)) {}

FacadeOperationResult Facade::LoadScene(std::filesystem::path& filePath, NormalizationParameters& normParams) {
    currentMove = {Constants::DEFAULT_VALUE, Constants::DEFAULT_VALUE, Constants::DEFAULT_VALUE};
    currentScale = {Constants::DEFAULT_SCALE, Constants::DEFAULT_SCALE, Constants::DEFAULT_SCALE};

    if (!(normParams.max > normParams.min && normParams.step >= 1))
        return FacadeOperationResult::InvaidParams();

    if (filePath.extension().string() != ".csv")
        return FacadeOperationResult::InvalidFile();

    auto loadedScene = fileReader->ReadScene(filePath, normParams);
    scene = std::move(loadedScene);

    return scene ? FacadeOperationResult::Success() : FacadeOperationResult::InvalidFile();
}

FacadeOperationResult Facade::DrawScene() {
    if (!scene || !sceneDrawer)
        return FacadeOperationResult::DrawError();

    sceneDrawer->clear();
    sceneDrawer->DrawScene(*scene);
    return FacadeOperationResult::Success();
}

FacadeOperationResult Facade::MoveScene(float dx, float dy, float dz) {
    if (!scene)
        return FacadeOperationResult::InvalidData();

    float tx = currentMove.x + dx;
    float ty = currentMove.y + dy;
    float tz = currentMove.z + dz;

    if (std::abs(tx) <= Constants::MAX_TRANSLATE &&
        std::abs(ty) <= Constants::MAX_TRANSLATE &&
        std::abs(tz) <= Constants::MAX_TRANSLATE) {
        currentMove.x = tx;
        currentMove.y = ty;
        currentMove.z = tz;

        auto moveMat = TransformMatrixBuilder::CreateMoveMatrix(dx, dy, dz);
        transformScene(moveMat);
        return FacadeOperationResult::Success();
    }

    return FacadeOperationResult::TranslationLimit();
}

FacadeOperationResult Facade::RotateScene(float degX, float degY, float degZ) {
    if (!scene)
        return FacadeOperationResult::InvalidData();

    double radX = degX * (Constants::PI / 180.0);
    double radY = degY * (Constants::PI / 180.0);
    double radZ = degZ * (Constants::PI / 180.0);

    auto rotMat = TransformMatrixBuilder::CreateRotationMatrix(radX, radY, radZ);
    transformScene(rotMat);
    return FacadeOperationResult::Success();
}

FacadeOperationResult Facade::ScaleScene(float sx, float sy, float sz) {
    if (!scene)
        return FacadeOperationResult::InvalidData();

    float nsx = currentScale.x * sx;
    float nsy = currentScale.y * sy;
    float nsz = currentScale.z * sz;

    if (nsx >= Constants::MIN_SCALE && nsx <= Constants::MAX_SCALE &&
        nsy >= Constants::MIN_SCALE && nsy <= Constants::MAX_SCALE &&
        nsz >= Constants::MIN_SCALE && nsz <= Constants::MAX_SCALE) {
        currentScale.x = nsx;
        currentScale.y = nsy;
        currentScale.z = nsz;

        // Note: Original had scaleY twice — preserved as-is for fidelity
        auto scaleMat = TransformMatrixBuilder::CreateScaleMatrix(sx, sy, sz);
        transformScene(scaleMat);
        return FacadeOperationResult::Success();
    }

    return FacadeOperationResult::ScaleLimit();
}

void Facade::transformScene(TransformMatrix& matrix) {
    if (scene) {
        scene->TranformFigures(matrix);
    }
}

#include "UniversalFileSystem.h"
#include <Utilities/OS.h>
#include <Log.h>

#ifdef ARDUINO

// Helper to open file for reading/writing based on mode
static bool open_file_handle(File& handle, const char* path, const char* mode) {
#ifdef BOARD_ESP32
    handle = SPIFFS.open(path, mode);
#elif defined(BOARD_NRF52)
    // For nRF52, use InternalFS.open with explicit mode mapping
    int internal_mode = 0;
    if (mode == FILE_READ || mode == "r") internal_mode = FILE_O_READ;
    else if (mode == FILE_WRITE || mode == "w") internal_mode = FILE_O_WRITE;
    else if (mode == FILE_APPEND || mode == "a") internal_mode = FILE_O_WRITE; // default write mode
    else return false;
    return handle.open(path, internal_mode);
#else
    return false;
#endif
    return static_cast<bool>(handle);
}

void UniversalFileSystem::listDir(const char* dir) {
    Serial.print("DIR: ");
    Serial.println(dir);

#ifdef BOARD_ESP32
    File root = SPIFFS.open(dir);
#elif defined(BOARD_NRF52)
    File root = InternalFS.open(dir);
#else
    return;
#endif

    if (!root) {
        Serial.println("Failed to open directory");
        return;
    }

    File child = root.openNextFile();
    while (child) {
        Serial.print(child.isDirectory() ? "  DIR: " : "  FILE: ");
        Serial.println(child.name());
        child.close();
        child = root.openNextFile();
    }
    root.close();
}

#else

void UniversalFileSystem::listDir(const char*) {}

#endif // ARDUINO

/*virtual*/ bool UniversalFileSystem::init() {
    TRACE("UniversalFileSystem initializing...");

#ifdef ARDUINO
#ifdef BOARD_ESP32
    INFO("SPIFFS mounting FileSystem");
    if (!SPIFFS.begin(true)) {
        ERROR("SPIFFS FileSystem mount failed");
        return false;
    }

    uint32_t totalMB = SPIFFS.totalBytes() / (1024 * 1024);
    uint32_t usedMB = SPIFFS.usedBytes() / (1024 * 1024);
    Serial.print("size: "); Serial.print(totalMB); Serial.println(" MB");
    Serial.print("used: "); Serial.print(usedMB); Serial.println(" MB");

    RNS::Bytes test("test");
    size_t wrote = write_file("/test", test);
    INFO("SPIFFS write test: wrote " + std::to_string(wrote) + " bytes");

    if (wrote < 4) {
        WARNING("SPIFFS FileSystem is being formatted, please wait...");
        SPIFFS.format();
    } else {
        remove_file("/test");
        INFO("SPIFFS FileSystem write test passed");
    }
    DEBUG("SPIFFS FileSystem is ready");

#elif defined(BOARD_NRF52)
    INFO("InternalFS mounting FileSystem");
    InternalFS.begin();
    INFO("InternalFS FileSystem is ready");
#endif
#endif
    return true;
}

/*virtual*/ bool UniversalFileSystem::file_exists(const char* file_path) {
#ifdef ARDUINO
    File f;
    if (!open_file_handle(f, file_path, FILE_READ)) {
        ERROR("file_exists: failed to open file " + std::string(file_path));
        return false;
    }
    f.close();
    return true;
#else
    FILE* fp = fopen(file_path, "r");
    if (fp) {
        fclose(fp);
        return true;
    }
    ERROR("file_exists: failed to open file " + std::string(file_path));
    return false;
#endif
}

/*virtual*/ size_t UniversalFileSystem::read_file(const char* file_path, RNS::Bytes& data) {
    size_t read_bytes = 0;

#ifdef ARDUINO
    File f;
    if (!open_file_handle(f, file_path, FILE_READ)) {
        ERROR("read_file: failed to open input file " + std::string(file_path));
        return 0;
    }
    size_t file_size = f.size();
    read_bytes = f.readBytes(reinterpret_cast<char*>(data.writable(file_size)), file_size);
    f.close();

#else
    FILE* fp = fopen(file_path, "rb");
    if (!fp) {
        ERROR("read_file: failed to open input file " + std::string(file_path));
        return 0;
    }

    fseek(fp, 0, SEEK_END);
    long size = ftell(fp);
    rewind(fp);

    read_bytes = fread(data.writable(size), 1, size, fp);
    fclose(fp);
#endif

    if (read_bytes != 0 && read_bytes != data.size()) {
        ERROR("read_file: incomplete read from " + std::string(file_path));
        data.clear();
    }

    TRACE("read_file: read " + std::to_string(read_bytes) + " bytes from " + std::string(file_path));
    return read_bytes;
}

/*virtual*/ size_t UniversalFileSystem::write_file(const char* file_path, const RNS::Bytes& data) {
    remove_file(file_path); // Ensure overwrite

    size_t written = 0;

#ifdef ARDUINO
    File f;
    if (!open_file_handle(f, file_path, FILE_WRITE)) {
        ERROR("write_file: failed to open output file " + std::string(file_path));
        return 0;
    }
    written = f.write(data.data(), data.size());
    f.close();

#else
    FILE* fp = fopen(file_path, "wb");
    if (!fp) {
        ERROR("write_file: failed to open output file " + std::string(file_path));
        return 0;
    }
    written = fwrite(data.data(), 1, data.size(), fp);
    fclose(fp);
#endif

    if (written < data.size()) {
        WARNING("write_file: only " + std::to_string(written) + " of " +
                std::to_string(data.size()) + " bytes written to " + std::string(file_path));
    }

    TRACE("write_file: wrote " + std::to_string(written) + " bytes to " + std::string(file_path));
    return written;
}

/*virtual*/ RNS::FileStream UniversalFileSystem::open_file(const char* file_path, RNS::FileStream::MODE mode) {
    TRACEF("open_file: opening %s in mode %d", file_path, mode);

#ifdef ARDUINO
#ifdef BOARD_ESP32
    const char* mode_str = nullptr;
    switch (mode) {
        case RNS::FileStream::MODE_READ:   mode_str = FILE_READ; break;
        case RNS::FileStream::MODE_WRITE:  mode_str = FILE_WRITE; break;
        case RNS::FileStream::MODE_APPEND: mode_str = FILE_APPEND; break;
        default:
            ERRORF("open_file: unsupported mode %d", mode);
            return {RNS::Type::NONE};
    }

    File* f = new File(SPIFFS.open(file_path, mode_str));
    if (!f || !(*f)) {
        delete f;
        ERRORF("open_file: failed to open %s", file_path);
        return {RNS::Type::NONE};
    }
    return RNS::FileStream(new UniversalFileStream(f));

#elif defined(BOARD_NRF52)
    int internal_mode = 0;
    switch (mode) {
        case RNS::FileStream::MODE_READ:   internal_mode = FILE_O_READ; break;
        case RNS::FileStream::MODE_WRITE:  internal_mode = FILE_O_WRITE; break;
        case RNS::FileStream::MODE_APPEND: internal_mode = FILE_O_WRITE; break;
        default:
            ERRORF("open_file: unsupported mode %d", mode);
            return {RNS::Type::NONE};
    }

    // Truncate if writing
    if (mode == RNS::FileStream::MODE_WRITE && InternalFS.exists(file_path)) {
        InternalFS.remove(file_path);
    }

    File* f = new File(InternalFS);
    if (!f->open(file_path, internal_mode)) {
        delete f;
        ERRORF("open_file: failed to open %s", file_path);
        return {RNS::Type::NONE};
    }
    return RNS::FileStream(new UniversalFileStream(f));

#else
    return RNS::FileStream(RNS::Type::NONE);
#endif

#else // Native
    const char* mode_str = nullptr;
    switch (mode) {
        case RNS::FileStream::MODE_READ:   mode_str = "r"; break;
        case RNS::FileStream::MODE_WRITE:  mode_str = "w"; break;
        case RNS::FileStream::MODE_APPEND: mode_str = "a"; break;
        default:
            ERRORF("open_file: unsupported mode %d", mode);
            return {RNS::Type::NONE};
    }

    FILE* f = fopen(file_path, mode_str);
    if (!f) {
        ERRORF("open_file: failed to open %s", file_path);
        return {RNS::Type::NONE};
    }
    return RNS::FileStream(new UniversalFileStream(f));
#endif
}

/*virtual*/ bool UniversalFileSystem::remove_file(const char* file_path) {
#ifdef ARDUINO
#ifdef BOARD_ESP32
    return SPIFFS.remove(file_path);
#elif defined(BOARD_NRF52)
    return InternalFS.remove(file_path);
#else
    return false;
#endif
#else
    return (std::remove(file_path) == 0);
#endif
}

/*virtual*/ bool UniversalFileSystem::rename_file(const char* from_path, const char* to_path) {
#ifdef ARDUINO
#ifdef BOARD_ESP32
    return SPIFFS.rename(from_path, to_path);
#elif defined(BOARD_NRF52)
    return InternalFS.rename(from_path, to_path);
#else
    return false;
#endif
#else
    return (std::rename(from_path, to_path) == 0);
#endif
}

/*virtual*/ bool UniversalFileSystem::directory_exists(const char* dir_path) {
    TRACE("directory_exists: checking " + std::string(dir_path));

#ifdef ARDUINO
    File f;
    if (!open_file_handle(f, dir_path, FILE_READ)) {
        return false;
    }
    bool is_dir = f.isDirectory();
    f.close();
    return is_dir;
#else
    struct stat st;
    return (stat(dir_path, &st) == 0 && S_ISDIR(st.st_mode));
#endif
}

/*virtual*/ bool UniversalFileSystem::create_directory(const char* dir_path) {
#ifdef ARDUINO
#ifdef BOARD_ESP32
    // SPIFFS doesn't truly support directories, but mkdir may be called for compatibility
    SPIFFS.mkdir(dir_path);
    DEBUG("create_directory: attempted mkdir for " + std::string(dir_path));
    return true;
#elif defined(BOARD_NRF52)
    return InternalFS.mkdir(dir_path);
#else
    return false;
#endif
#else
    struct stat st;
    if (stat(dir_path, &st) == 0) return true;
    return (mkdir(dir_path, 0700) == 0);
#endif
}

/*virtual*/ bool UniversalFileSystem::remove_directory(const char* dir_path) {
    TRACE("remove_directory: removing " + std::string(dir_path));

#ifdef ARDUINO
#ifdef BOARD_ESP32
    return SPIFFS.rmdir(dir_path);
#elif defined(BOARD_NRF52)
    return InternalFS.rmdir_r(dir_path);
#else
    return false;
#endif
#else
    return (rmdir(dir_path) == 0);
#endif
}

/*virtual*/ std::list<std::string> UniversalFileSystem::list_directory(const char* dir_path) {
    TRACE("list_directory: listing " + std::string(dir_path));
    std::list<std::string> entries;

#ifdef ARDUINO
    File root;
#ifdef BOARD_ESP32
    root = SPIFFS.open(dir_path);
#elif defined(BOARD_NRF52)
    root = InternalFS.open(dir_path);
#endif

    if (!root) {
        ERROR("list_directory: failed to open directory " + std::string(dir_path));
        return entries;
    }

    File entry = root.openNextFile();
    while (entry) {
        if (!entry.isDirectory()) {
            entries.emplace_back(entry.name());
        }
        entry.close();
        entry = root.openNextFile();
    }
    root.close();
#endif

    return entries;
}

