#include "Object_229.hpp"

Object_229* Object_229::create() {
    return new Object_229();
}

// Function pointer table for state handlers — renamed for clarity
void (Object_229::*state_handlers_ov099[4])() = {
    &Object_229::handle_state_0,
    &Object_229::handle_state_1,
    &Object_229::handle_state_2,
    &Object_229::handle_state_3,
};

// Another function pointer table used in transition setup
void (Object_229::*transition_table_ov099[4])() = {
    &Object_229::transition_to_1,
    &Object_229::transition_to_2,
    &Object_229::transition_to_3,
    &Object_229::transition_to_4,
};

struct TempFlags {
    u32 flag_a;
    u32 flag_b;
};

u32 global_flags_array[2];
u8 global_status_byte;

bool Object_229::onCreate() {
    // Extract direction from settings
    this->direction = (this->settings >> 0x1c) & 1;

    // Set uniform scale
    this->scale.x = this->scale.y = this->scale.z = 0x1000;

    // Parse setting_1: clamp to [1,4]
    i32 s1_raw = ((this->settings << 4) >> 0x1c);
    this->setting_1 = (s1_raw < 1) ? 1 : ((s1_raw > 4) ? 4 : s1_raw);

    // Parse setting_2 mask: clamp index to [1,3], then compute bit mask
    i32 idx = (u8)((this->settings << 8) >> 0x1c);
    idx = (idx < 1) ? 1 : ((idx > 3) ? 3 : idx);
    this->setting_2 = static_cast<char>(1 << (idx - 1));

    // Check combined flags
    u32 condA = global_flags_array[0] & this->_334;
    u32 condB = global_flags_array[1] & this->_338;

    if (!(condA && condB)) {
        this->_404 = 3;
        this->triggerStateChange(2);
        global_status_byte |= this->setting_2;
    } else {
        this->_404 = 0;
        this->triggerStateChange(0);
        global_status_byte &= ~this->setting_2;
    }

    this->_3b4 = 1;
    return true;
