#define DEFAULT_STROKE_SETTINGS ((plutovg_stroke_style_t){1.f, PLUTOVG_LINE_CAP_BUTT, PLUTOVG_LINE_JOIN_MITER, 10.f})

static plutovg_state_t* allocate_new_state(void)
{
    plutovg_state_t* state = (plutovg_state_t*)malloc(sizeof(plutovg_state_t));
    if (state) {
        state->paint = NULL;
        state->font_face = NULL;
        state->color = PLUTOVG_BLACK_COLOR;
        state->matrix = PLUTOVG_IDENTITY_MATRIX;
        state->stroke.style = DEFAULT_STROKE_SETTINGS;
        state->stroke.dash.offset = 0.f;
        plutovg_array_init(state->stroke.dash.array);
        plutovg_span_buffer_init(&state->clip_spans);
        state->winding = PLUTOVG_FILL_RULE_NON_ZERO;
        state->op = PLUTOVG_OPERATOR_SRC_OVER;
        state->font_size = 12.f;
        state->opacity = 1.f;
        state->clipping = false;
        state->next = NULL;
    }
    return state;
}

static void reset_current_state(plutovg_state_t* state)
{
    if (state) {
        plutovg_paint_destroy(state->paint);
        plutovg_font_face_destroy(state->font_face);
        state->paint = NULL;
        state->font_face = NULL;
        state->color = PLUTOVG_BLACK_COLOR;
        state->matrix = PLUTOVG_IDENTITY_MATRIX;
        state->stroke.style = DEFAULT_STROKE_SETTINGS;
        state->stroke.dash.offset = 0.f;
        plutovg_array_clear(state->stroke.dash.array);
        plutovg_span_buffer_reset(&state->clip_spans);
        state->winding = PLUTOVG_FILL_RULE_NON_ZERO;
        state->op = PLUTOVG_OPERATOR_SRC_OVER;
        state->font_size = 12.f;
        state->opacity = 1.f;
        state->clipping = false;
    }
}

static void duplicate_state(plutovg_state_t* target, const plutovg_state_t* source)
{
    if (!target || !source) return;

    target->paint = plutovg_paint_reference(source->paint);
    target->font_face = plutovg_font_face_reference(source->font_face);
    target->color = source->color;
    target->matrix = source->matrix;
    target->stroke.style = source->stroke.style;
    target->stroke.dash.offset = source->stroke.dash.offset;
    plutovg_array_clear(target->stroke.dash.array);
    plutovg_array_append(target->stroke.dash.array, source->stroke.dash.array);
    plutovg_span_buffer_copy(&target->clip_spans, &source->clip_spans);
    target->winding = source->winding;
    target->op = source->op;
    target->font_size = source->font_size;
    target->opacity = source->opacity;
    target->clipping = source->clipping;
}

static void release_state(plutovg_state_t* state)
{
    if (state) {
        plutovg_paint_destroy(state->paint);
        plutovg_font_face_destroy(state->font_face);
        plutovg_array_destroy(state->stroke.dash.array);
        plutovg_span_buffer_destroy(&state->clip_spans);
        free(state);
    }
}

plutovg_canvas_t* plutovg_canvas_create(plutovg_surface_t* surface)
{
    if (!surface) return NULL;

    plutovg_canvas_t* canvas = (plutovg_canvas_t*)malloc(sizeof(plutovg_canvas_t));
    if (!canvas) return NULL;

    plutovg_init_reference(canvas);
    canvas->surface = plutovg_surface_reference(surface);
    canvas->path = plutovg_path_create();
    canvas->state = allocate_new_state();
    canvas->freed_state = NULL;
    canvas->face_cache = NULL;
    canvas->clip_rect = PLUTOVG_MAKE_RECT(0, 0, surface->width, surface->height);
    plutovg_span_buffer_init(&canvas->clip_spans);
    plutovg_span_buffer_init(&canvas->fill_spans);

    return canvas;
}

plutovg_canvas_t* plutovg_canvas_reference(plutovg_canvas_t* canvas)
{
    if (canvas) {
        plutovg_increment_reference(canvas);
    }
    return canvas;
}

void plutovg_canvas_destroy(plutovg_canvas_t* canvas)
{
    if (canvas && plutovg_destroy_reference(canvas)) {
        // Free all saved states
        while (canvas->state) {
            plutovg_state_t* current = canvas->state;
            canvas->state = current->next;
            release_state(current);
        }

        // Free recycled states
        while (canvas->freed_state) {
            plutovg_state_t* current = canvas->freed_state;
            canvas->freed_state = current->next;
            release_state(current);
        }

        // Clean up caches and buffers
        plutovg_font_face_cache_destroy(canvas->face_cache);
        plutovg_span_buffer_destroy(&canvas->fill_spans);
        plutovg_span_buffer_destroy(&canvas->clip_spans);
        plutovg_surface_destroy(canvas->surface);
        plutovg_path_destroy(canvas->path);
        free(canvas);
    }
}

