float plutovg_canvas_add_glyph(plutovg_canvas_t* canvas, plutovg_codepoint_t codepoint, float x, float y)
{
    if (!canvas || !canvas->state->font_face || canvas->state->font_size <= 0.f) return 0.f;

    return plutovg_font_face_get_glyph_path(canvas->state->font_face, canvas->state->font_size, x, y, codepoint, canvas->path);
}

float plutovg_canvas_add_text(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    if (!canvas || !canvas->state->font_face || canvas->state->font_size <= 0.f) return 0.f;

    plutovg_text_iterator_t it;
    plutovg_text_iterator_init(&it, text, length, encoding);

    float advance_width = 0.f;
    while (plutovg_text_iterator_has_next(&it)) {
        plutovg_codepoint_t codepoint = plutovg_text_iterator_next(&it);
        advance_width += plutovg_font_face_get_glyph_path(canvas->state->font_face, canvas->state->font_size,
                                                          x + advance_width, y, codepoint, canvas->path);
    }
    return advance_width;
}

float plutovg_canvas_fill_text(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    if (!canvas) return 0.f;

    plutovg_canvas_new_path(canvas);
    float advance_width = plutovg_canvas_add_text(canvas, text, length, encoding, x, y);
    plutovg_canvas_fill(canvas);
    return advance_width;
}

float plutovg_canvas_stroke_text(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    if (!canvas) return 0.f;

    plutovg_canvas_new_path(canvas);
    float advance_width = plutovg_canvas_add_text(canvas, text, length, encoding, x, y);
    plutovg_canvas_stroke(canvas);
    return advance_width;
}

float plutovg_canvas_clip_text(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, float x, float y)
{
    if (!canvas) return 0.f;

    plutovg_canvas_new_path(canvas);
    float advance_width = plutovg_canvas_add_text(canvas, text, length, encoding, x, y);
    plutovg_canvas_clip(canvas);
    return advance_width;
}

void plutovg_canvas_font_metrics(const plutovg_canvas_t* canvas, float* ascent, float* descent, float* line_gap, plutovg_rect_t* extents)
{
    if (!canvas || !canvas->state->font_face || canvas->state->font_size <= 0.f) {
        if (ascent) *ascent = 0.f;
        if (descent) *descent = 0.f;
        if (line_gap) *line_gap = 0.f;
        if (extents) {
            extents->x = 0.f;
            extents->y = 0.f;
            extents->w = 0.f;
            extents->h = 0.f;
        }
        return;
    }

    plutovg_font_face_get_metrics(canvas->state->font_face, canvas->state->font_size, ascent, descent, line_gap, extents);
}

void plutovg_canvas_glyph_metrics(plutovg_canvas_t* canvas, plutovg_codepoint_t codepoint, float* advance_width, float* left_side_bearing, plutovg_rect_t* extents)
{
    if (!canvas || !canvas->state->font_face || canvas->state->font_size <= 0.f) {
        if (advance_width) *advance_width = 0.f;
        if (left_side_bearing) *left_side_bearing = 0.f;
        if (extents) {
            extents->x = 0.f;
            extents->y = 0.f;
            extents->w = 0.f;
            extents->h = 0.f;
        }
        return;
    }

    plutovg_font_face_get_glyph_metrics(canvas->state->font_face, canvas->state->font_size, codepoint, advance_width, left_side_bearing, extents);
}

float plutovg_canvas_text_extents(plutovg_canvas_t* canvas, const void* text, int length, plutovg_text_encoding_t encoding, plutovg_rect_t* extents)
{
    if (!canvas || !canvas->state->font_face || canvas->state->font_size <= 0.f) {
        if (extents) {
            extents->x = 0.f;
            extents->y = 0.f;
            extents->w = 0.f;
            extents->h = 0.f;
        }
        return 0.f;
    }

    return plutovg_font_face_text_extents(canvas->state->font_face, canvas->state->font_size, text, length, encoding, extents);
}

#include <stdio.h>
#include <assert.h>

// Simulated DDS API stubs for demonstration (in real use, these would be actual DDS headers)
typedef int dds_entity_t;
typedef struct dds_qos dds_qos_t;
typedef struct dds_listener dds_listener_t;
typedef enum dds_return {
    DDS_RETCODE_OK = 0,
    DDS_RETCODE_BAD_PARAMETER = -1,
    DDS_RETCODE_PRECONDITION_NOT_MET = -2
} dds_return_t;

extern "C" {
    dds_entity_t dds_create_participant(int domain_id, const dds_qos_t* qos, void* arg);
    dds_entity_t dds_create_subscriber(dds_entity_t parent, const dds_qos_t* qos, dds_listener_t* listener);
    dds_qos_t* dds_create_qos(void);
    void dds_delete_qos(dds_qos_t* qos);
    dds_listener_t* dds_create_listener(void* arg);
    void dds_delete_listener(dds_listener_t* listener);
    void dds_lset_data_available(dds_listener_t* listener, void (*cb)(void));
    void dds_lset_publication_matched(dds_listener_t* listener, void (*cb)(void));
    void dds_qset_presentation(dds_qos_t* qos, int kind, bool coherent_access, bool ordered_access);
    void dds_qset_destination_order(dds_qos_t* qos, int order);
    void dds_delete(dds_entity_t entity);
}

// Dummy callbacks
static void on_data_available(void) {}
static void on_publication_matched(void) {}

void test_subscriber_validations() {
    dds_entity_t participant = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    assert(participant > 0);

    // Test 1: Null participant → expect BAD_PARAMETER
    dds_entity_t sub = dds_create_subscriber(0, NULL, NULL);
    assert(sub == DDS_RETCODE_BAD_PARAMETER);

    // Test 2: Valid participant, no QoS/listener
    sub = dds_create_subscriber(participant, NULL, NULL);
    assert(sub > 0);
    dds_delete(sub);

    // Test 3: Valid participant + default QoS
    dds_qos_t* q = dds_create_qos();
    sub = dds_create_subscriber(participant, q, NULL);
    assert(sub > 0);
    dds_delete(sub);
    dds_delete_qos(q);

    // Test 4: Invalid destination order (ignored for subscriber, should still succeed)
    q = dds_create_qos();
    dds_qset_destination_order(q, 3); // Invalid value, but ignored
    sub = dds_create_subscriber(participant, q, NULL);
    assert(sub > 0);
    dds_delete(sub);
    dds_delete_qos(q);

    // Test 5: Invalid presentation policy → BAD_PARAMETER
    q = dds_create_qos();
    dds_qset_presentation(q, 123, true, true); // Invalid access scope
    sub = dds_create_subscriber(participant, q, NULL);
    assert(sub == DDS_RETCODE_BAD_PARAMETER);
    dds_delete_qos(q);

    // Test 6: Default listener (all unset)
    dds_listener_t* lst = dds_create_listener(NULL);
    sub = dds_create_subscriber(participant, NULL, lst);
    assert(sub > 0);
    dds_delete(sub);
    dds_delete_listener(lst);

    // Test 7: Listener with data_available callback
    lst = dds_create_listener(NULL);
    dds_lset_data_available(lst, on_data_available);
    sub = dds_create_subscriber(participant, NULL, lst);
    assert(sub > 0);
    dds_delete(sub);
    dds_delete_listener(lst);

    // Test 8: Listener with publication_matched (ignored for subscriber)
    lst = dds_create_listener(NULL);
    dds_lset_publication_matched(lst, on_publication_matched);
    sub = dds_create_subscriber(participant, NULL, lst);
    assert(sub > 0);
    dds_delete(sub);
    dds_delete_listener(lst);

    // Cleanup
    dds_delete(participant);
}

void test_invalid_qos_policy() {
    dds_entity_t part = dds_create_participant(DDS_DOMAIN_DEFAULT, NULL, NULL);
    assert(part > 0);

    dds_qos_t* bad_qos = dds_create_qos();
    assert(bad_qos != NULL);

    // Set invalid presentation scope
    dds_qset_presentation(bad_qos, (dds_presentation_access_scope_kind_t)123, false, false);
    dds_entity_t sub = dds_create_subscriber(part, bad_qos, NULL);
    assert(sub == DDS_RETCODE_BAD_PARAMETER);

    dds_delete_qos(bad_qos);
    dds_return_t rc = dds_delete(part);
    assert(rc == 0);
}

#include <gtest/gtest.h>
#include "chromaprint3d/kdtree.h"
#include "chromaprint3d/color.h"
#include <cstddef>
#include <vector>

using namespace ChromaPrint3D;

// Alternative projection that returns the input unchanged (same semantics)
struct LabIdentityMap {
    const Lab& operator()(const Lab& lab) const { return lab; }
};

// Reuse the same KDTree type but with a different template alias name
using TestKDTree = kdt::KDTree<Lab, 3, LabIdentityMap, std::size_t, float>;

// Test single point nearest neighbor search
TEST(KDTree, SinglePointSearch) {
    std::vector<Lab> dataPoints      = {Lab(50.0f, 0.0f, 0.0f)};
    std::vector<std::size_t> idxList = {0};
    TestKDTree tree;
    tree.Reset(dataPoints, idxList, LabIdentityMap{});
    auto queryResult = tree.Nearest(Lab(51.0f, 0.0f, 0.0f));
    EXPECT_EQ(queryResult.index, 0u);
    EXPECT_NEAR(queryResult.dist2, 1.0f, 1e-5f);
}

// Test correctness of nearest neighbor selection among multiple points
TEST(KDTree, NearestNeighborAccuracy) {
    std::vector<Lab> samplePoints = {
        Lab(0.0f, 0.0f, 0.0f),
        Lab(50.0f, 0.0f, 0.0f),
        Lab(100.0f, 0.0f, 0.0f),
    };
    std::vector<std::size_t> sampleIndices = {0, 1, 2};
    TestKDTree tree;
    tree.Reset(samplePoints, sampleIndices, LabIdentityMap{});

    auto res0 = tree.Nearest(Lab(10.0f, 0.0f, 0.0f));
    EXPECT_EQ(res0.index, 0u);

    auto res1 = tree.Nearest(Lab(48.0f, 0.0f, 0.0f));
    EXPECT_EQ(res1.index, 1u);

    auto res2 = tree.Nearest(Lab(90.0f, 0.0f, 0.0f));
    EXPECT_EQ(res2.index, 2u);
}

// Test k-nearest neighbors functionality
TEST(KDTree, KNearestSearch) {
    std::vector<Lab> testPoints;
    std::vector<std::size_t> testIndices;

    for (int i = 0; i < 20; ++i) {
        testPoints.emplace_back(static_cast<float>(i * 5), 0.0f, 0.0f);
        testIndices.push_back(static_cast<std::size_t>(i));
    }

    TestKDTree tree;
    tree.Reset(testPoints, testIndices, LabIdentityMap{});

    std::vector<kdt::Neighbor<std::size_t, float>> foundNeighbors;
    tree.KNearest(Lab(52.0f, 0.0f, 0.0f), 3, foundNeighbors);

    EXPECT_EQ(foundNeighbors.size(), 3u);

    bool closestFound = false;
    for (const auto& neighbor : foundNeighbors) {
        if (neighbor.index == 10) {
            closestFound = true;
        }
    }
    EXPECT_TRUE(closestFound);
}

// Test exact match scenario
TEST(KDTree, ExactMatchCase) {
    std::vector<Lab> referencePoints   = {Lab(42.0f, 10.0f, -5.0f)};
    std::vector<std::size_t> refIndices = {0};
    TestKDTree tree;
    tree.Reset(referencePoints, refIndices, LabIdentityMap{});

    auto matchResult = tree.Nearest(Lab(42.0f, 10.0f, -5.0f));
    EXPECT_EQ(matchResult.index, 0u);
    EXPECT_NEAR(matchResult.dist2, 0.0f, 1e-10f);
}

#include <iostream>
#include <cmath>

// Type III clone: equivalent computation with different variable naming and structure
int main() {
    // Assume omega is an array of 3 elements, upsilon is an array of 3 elements
    double omega[3] = {1.0, 2.0, 3.0}; // example values
    double upsilon[3] = {0.5, 0.3, 0.7}; // example values
    double result[42] = {0}; // initialize all to zero

    // Precompute squared components
    double s0 = omega[0] * omega[0];
    double s1 = omega[1] * omega[1];
    double s2 = omega[2] * omega[2];

    // Sum of squares and related quantities
    double sum_sq = s0 + s1 + s2;
    double norm = std::sqrt(sum_sq);
    double inv_norm = 1.0 / norm;
    double half_norm = 0.5 * norm;

    // Trigonometric terms
    double sin_half = std::sin(half_norm);
    double cos_half = std::cos(half_norm);
    double sin_norm = std::sin(norm);
    double one_minus_cos = 1.0 - cos_half;

    // Powers for scaling factors
    double inv_sum_sq_32 = std::pow(sum_sq, -1.5);
    double inv_sum_sq_52 = std::pow(sum_sq, -2.5);
    double inv_sum_sq_2 = 1.0 / (sum_sq * sum_sq);

    // Intermediate expressions for matrix entries
    double termA = sin_half * inv_norm;
    double termB = inv_sum_sq_32 * sin_half;
    double termC = 0.5 * inv_sum_sq * std::cos(half_norm);

    // Off-diagonal rotation terms
    double d01 = omega[0] * omega[1];
    double d02 = omega[0] * omega[2];
    double d12 = omega[1] * omega[2];

    // Diagonal correction terms
    double diag0 = s0 * (termC - termB) + termA;
    double diag1 = s1 * (termC - termB) + termA;
    double diag2 = s2 * (termC - termB) + termA;

    // Assign fixed positions (first 18 entries)
    result[0] = diag0;
    result[5] = d01 * (termC - termB) - omega[0] * omega[1] * termB;
    result[10] = diag1;
    result[15] = d02 * (termC - termB) - omega[0] * omega[2] * termB;
    result[20] = diag2;
    result[25] = d12 * (termC - termB) - omega[1] * omega[2] * termB;

    // Fill remaining diagonal entries
    result[1] = result[5]; result[2] = result[10]; result[3] = result[15];
    result[4] = result[5]; result[6] = result[15]; result[7] = result[20];
    result[8] = result[10]; result[9] = result[15]; result[11] = result[20];
    result[12] = result[25]; result[13] = result[25]; result[14] = result[25];

    // Rotation vector contribution (entries 21-23)
    double scale = -0.5 * termA;
    result[21] = scale * omega[0];
    result[22] = scale * omega[1];
    result[23] = scale * omega[2];

    // Remaining entries computed via linear combinations
    // Simplified representation using reused subexpressions
    double common_factor = (norm - sin_norm) * inv_sum_sq_32;

    // Entries 24-26: first row of Jacobian-like block
    result[24] = 1.0 + common_factor * (s1 + s2);
    result[25] = common_factor * d01 * omega[0] - inv_norm * omega[0] * omega[1] * (1.0 - cos_half);
    result[26] = common_factor * d02 * omega[0] + inv_norm * omega[0] * omega[2] * (1.0 - cos_half);

    // Entries 27-29: second row of Jacobian-like block
    result[27] = upsilon[0] * (common_factor * omega[0] * omega[1] * omega[0] - inv_norm * omega[0] * omega[1] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * (omega[0]*omega[0] - omega[2]*omega[2]) + inv_norm * omega[2] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * omega[0]*omega[2] - inv_norm * omega[0] * omega[2] * (1.0 - cos_half));
    result[28] = upsilon[0] * (common_factor * omega[1]*omega[1] - inv_norm * omega[1] * omega[1] * (1.0 - cos_half) + 2*omega[1]*omega[0]) +
                 upsilon[1] * (common_factor * d01 * omega[1] + inv_norm * omega[0] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * d12 * omega[1] - inv_norm * omega[2] * (1.0 - cos_half));
    result[29] = upsilon[0] * (common_factor * omega[2]*omega[2] - inv_norm * omega[2] * omega[2] * (1.0 - cos_half) + 2*omega[2]*omega[0]) +
                 upsilon[1] * (common_factor * d02 * omega[2] - inv_norm * omega[1] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * d12 * omega[2] + inv_norm * omega[1] * (1.0 - cos_half));

    // Entries 30-32: third row of Jacobian-like block
    result[30] = -result[25];
    result[31] = 1.0 + common_factor * (s0 + s2);
    result[32] = common_factor * d12 * omega[1] - inv_norm * omega[1] * omega[2] * (1.0 - cos_half);

    // Entries 33-35: fourth row of Jacobian-like block
    result[33] = upsilon[0] * (common_factor * d01 * omega[0] + inv_norm * omega[1] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * (omega[1]*omega[1] - omega[2]*omega[2]) + inv_norm * omega[2] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * d02 * omega[0] - inv_norm * omega[0] * omega[2] * (1.0 - cos_half));
    result[34] = upsilon[0] * (common_factor * d01 * omega[1] - inv_norm * omega[0] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * omega[1]*omega[1] - inv_norm * omega[1] * omega[1] * (1.0 - cos_half) + 2*omega[1]*omega[2]) +
                 upsilon[2] * (common_factor * d12 * omega[1] + inv_norm * omega[0] * (1.0 - cos_half));
    result[35] = upsilon[0] * (common_factor * d02 * omega[2] + inv_norm * omega[1] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * d12 * omega[2] - inv_norm * omega[0] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * omega[2]*omega[2] - inv_norm * omega[2] * omega[2] * (1.0 - cos_half) + 2*omega[2]*omega[0]);

    // Entries 36-38: fifth row of Jacobian-like block
    result[36] = -result[26];
    result[37] = -result[32];
    result[38] = 1.0 + common_factor * (s0 + s1);

    // Final entries 39-41: sixth row of Jacobian-like block
    result[39] = upsilon[0] * (common_factor * d02 * omega[0] - inv_norm * omega[2] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * d12 * omega[0] + inv_norm * omega[2] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * (omega[0]*omega[0] - omega[1]*omega[1]) + inv_norm * omega[1] * (1.0 - cos_half));
    result[40] = upsilon[0] * (common_factor * d02 * omega[1] + inv_norm * omega[2] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * d12 * omega[1] - inv_norm * omega[0] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * omega[1]*omega[1] - inv_norm * omega[1] * omega[1] * (1.0 - cos_half) + 2*omega[1]*omega[0]);
    result[41] = upsilon[0] * (common_factor * d02 * omega[2] - inv_norm * omega[1] * (1.0 - cos_half)) +
                 upsilon[1] * (common_factor * d12 * omega[2] + inv_norm * omega[0] * (1.0 - cos_half)) +
                 upsilon[2] * (common_factor * omega[2]*omega[2] - inv_norm * omega[2] * omega[2] * (1.0 - cos_half) + 2*omega[2]*omega[1]);

    // Output result for demonstration
    for (int i = 0; i < 42; ++i) {
        std::cout << "result[" << i << "] = " << result[i] << "\n";
    }

    return 0;
}

#include <string>
