extern int gCacheConfig;
extern std::string gProxyConfig;

std::string parseProxy(const std::string &source);

// Resolves relative path segments like "../" by removing parent directories
std::string normalizePath(const std::string &inputPath) {
    std::string result = inputPath;
    size_t cursor = 0;

    while (true) {
        size_t dotDotPos = result.find("../", cursor);
        if (dotDotPos == std::string::npos) break;

        // Skip leading "../"
        if (dotDotPos == 0) {
            cursor = dotDotPos + 3;
            continue;
        }

        // Find last slash before ".."
        size_t prevSlash = result.rfind('/', dotDotPos - 1);
        if (prevSlash != std::string::npos) {
            // Try to find second-to-last slash
            size_t prevPrevSlash = result.rfind('/', prevSlash - 1);
            if (prevPrevSlash != std::string::npos) {
                result.erase(prevPrevSlash + 1, dotDotPos - prevPrevSlash + 2);
            } else {
                result.erase(0, dotDotPos + 3);
            }
        } else {
            cursor = dotDotPos + 3;
        }
    }

    return result;
}

// Helper: extract string arguments from Duktape stack
bool extractStringArgs(duk_context *ctx, int minArgs, int maxArgs, ...) {
    int actualCount = duk_get_top(ctx);
    if ((minArgs >= 0 && actualCount < minArgs) || (maxArgs >= 0 && actualCount > maxArgs)) {
        return false;
    }

    va_list args;
    va_start(args, maxArgs);
    for (int i = 0; i < actualCount; ++i) {
        std::string* outPtr = va_arg(args, std::string*);
        if (outPtr) {
            *outPtr = duk_safe_to_string(ctx, i);
        }
    }
    va_end(args);
    return true;
}

// Module resolution callback
duk_ret_t resolveModuleCallback(duk_context *ctx) {
    const char *requestedId = duk_get_string(ctx, 0);
    const char *parentId = duk_get_string(ctx, 1);

    std::string resolvedId;
    std::string parentPath(parentId ? parentId : "");

    if (!parentPath.empty()) {
        size_t lastSlash = parentPath.rfind('/');
        if (lastSlash != std::string::npos) {
            resolvedId += parentPath.substr(0, lastSlash + 1);
        }
    }

    resolvedId += requestedId;

    if (!endsWith(resolvedId, ".js")) {
        resolvedId += ".js";
    }

    resolvedId = normalizePath(resolvedId);

    if (fileExist(resolvedId)) {
        duk_push_string(ctx, resolvedId.c_str());
    } else {
        duk_push_undefined(ctx);
    }

    return 1;
}

// Module loading callback
duk_ret_t loadModuleCallback(duk_context *ctx) {
    const char *resolvedPath = duk_get_string(ctx, 0);
    std::string sourceCode = fileGet(resolvedPath, true);
    duk_push_string(ctx, sourceCode.c_str());
    return 1;
}

// Custom print function
duk_ret_t customPrint(duk_context *ctx) {
    duk_push_string(ctx, " ");
    duk_insert(ctx, 0);
    duk_join(ctx, duk_get_top(ctx) - 1);
    printf("%s\n", duk_safe_to_string(ctx, -1));
    return 0;
}

// Fetch implementation supporting GET/POST
duk_ret_t fetchHandler(duk_context *ctx) {
    std::string url, proxy, method = "GET", postData;

    if (!extractStringArgs(ctx, 1, 4, &url, &proxy, &method, &postData)) {
        return 0;
    }

    std::string responseContent;

    switch (hash_(method)) {
        case "POST"_hash:
            webPost(url, postData, proxy, string_array{}, &responseContent);
            break;
        default:
            responseContent = fetchFile(url, proxy, gCacheConfig);
            break;
    }

    duk_push_lstring(ctx, responseContent.c_str(), responseContent.size());
    return 1;
}

// atob: base64 encode
duk_ret_t atobHandler(duk_context *ctx) {
    std::string input = duk_safe_to_string(ctx, -1);
    std::string encoded = base64Encode(input);
    duk_push_string(ctx, encoded.c_str());
    return 1;
}

// btoa: base64 decode
duk_ret_t btoaHandler(duk_context *ctx) {
    std::string input = duk_safe_to_string(ctx, -1);
    std::string decoded = base64Decode(input, true);
    duk_push_lstring(ctx, decoded.c_str(), decoded.size());
    return 1;
}

// geoip lookup
duk_ret_t geoipLookup(duk_context *ctx) {
    std::string ipOrHost, proxy;
    if (!extractStringArgs(ctx, 1, 2, &ipOrHost, &proxy)) {
        duk_push_undefined(ctx);
        return 1;
    }

    if (!isIPv4(ipOrHost) && !isIPv6(ipOrHost)) {
        ipOrHost = hostnameToIPAddr(ipOrHost);
    }

    if (ipOrHost.empty()) {
        duk_push_undefined(ctx);
    } else {
        std::string apiUrl = "https://api.ip.sb/geoip/" + ipOrHost;
        std::string result = fetchFile(apiUrl, parseProxy(proxy), gCacheConfig);
        duk_push_string(ctx, result.c_str());
    }

    return 1;
}

// Initialize Duktape environment
duk_context* createDuktapeContext() {
    duk_context *ctx = duk_create_heap_default();
    if (!ctx) return nullptr;

    // Setup module loader
    duk_push_object(ctx);
    duk_push_c_function(ctx, resolveModuleCallback, DUK_VARARGS);
    duk_put_prop_string(ctx, -2, "resolve");
    duk_push_c_function(ctx, loadModuleCallback, DUK_VARARGS);
    duk_put_prop_string(ctx, -2, "load");
    duk_module_node_init(ctx);

    // Expose global functions
    duk_push_c_function(ctx, customPrint, DUK_VARARGS);
    duk_put_global_string(ctx, "print");

    duk_push_c_function(ctx, fetchHandler, DUK_VARARGS);
    duk_put_global_string(ctx, "fetch");

    duk_push_c_function(ctx, atobHandler, 1);
    duk_put_global_string(ctx, "atob");

    duk_push_c_function(ctx, btoaHandler, 1);
    duk_put_global_string(ctx, "btoa");

    duk_push_c_function(ctx, geoipLookup, DUK_VARARGS);
    duk_put_global_string(ctx, "geoip");

    return ctx;
}

// Evaluate script safely
int evalScript(duk_context *ctx, const std::string &code) {
    return duk_peval_string(ctx, code.c_str());
}

// Call JS function by name with variadic arguments
int invokeJsFunction(duk_context *ctx, const std::string &funcName, size_t argCount, ...) {
    duk_get_global_string(ctx, funcName.c_str());

    va_list ap;
    va_start(ap, argCount);
    for (size_t i = 0; i < argCount; ++i) {
        std::string *arg = va_arg(ap, std::string*);
        if (arg) {
            duk_push_string(ctx, arg->c_str());
        } else {
            duk_push_undefined(ctx);
        }
    }
    va_end(ap);

    return duk_pcall(ctx, static_cast<duk_idx_t>(argCount));
}

// Push node info object onto stack
int pushNodeInfo(duk_context *ctx, const nodeInfo &info) {
    duk_push_object(ctx);

    duk_push_string(ctx, info.group.c_str());
    duk_put_prop_string(ctx, -2, "Group");

    duk_push_int(ctx, info.groupID);
    duk_put_prop_string(ctx, -2, "GroupID");

    duk_push_int(ctx, info.id);
    duk_put_prop_string(ctx, -2, "Index");

    duk_push_string(ctx, info.remarks.c_str());
    duk_put_prop_string(ctx, -2, "Remark");

    duk_push_string(ctx, info.proxyStr.c_str());
    duk_put_prop_string(ctx, -2, "ProxyInfo");

    return 0;
}

// Alternative way to push node info using defineProperty pattern
int pushNodeInfoWithDefProp(duk_context *ctx, const nodeInfo &info, duk_idx_t objIdx) {
    duk_push_object(ctx);

    duk_push_string(ctx, "Group");
    duk_push_string(ctx, info.group.c_str());
    duk_def_prop(ctx, objIdx, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "GroupID");
    duk_push_int(ctx, info.groupID);
    duk_def_prop(ctx, objIdx, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "Index");
    duk_push_int(ctx, info.id);
    duk_def_prop(ctx, objIdx, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "Remark");
    duk_push_string(ctx, info.remarks.c_str());
    duk_def_prop(ctx, objIdx, DUK_DEFPROP_HAVE_VALUE);

    duk_push_string(ctx, "ProxyInfo");
    duk_push_string(ctx, info.proxyStr.c_str());
    duk_def_prop(ctx, objIdx, DUK_DEFPROP_HAVE_VALUE);

    return 0;
}

// Extract integer result from top of stack
int popIntResult(duk_context *ctx) {
    int val = duk_to_int(ctx, -1);
    duk_pop(ctx);
    return val;
}

// Extract string result from top of stack
std::string popStringResult(duk_context *ctx) {
    if (duk_is_null_or_undefined(ctx, -1)) return "";
    std::string res = duk_safe_to_string(ctx, -1);
    duk_pop(ctx);
    return res;
}

// Extract boolean result from top of stack
bool popBoolResult(duk_context *ctx) {
    bool val = duk_to_boolean(ctx, -1);
    duk_pop(ctx);
    return val;
}

// Get error stack trace
std::string getErrorStack(duk_context *ctx) {
    duk_get_prop_string(ctx, -1, "stack");
    std::string stackTrace = duk_get_string(ctx, -1);
    duk_pop(ctx);
    return stackTrace;
}

#include "TypeCheckerImpl.h"
using namespace Cangjie;
using namespace AST;

Ptr<Ty> TypeChecker::TypeCheckerImpl::SynParenExpr(ASTContext& ctx, ParenExpr& pe)
{
    (void)Synthesize(ctx, pe.expr.get());

    // Validate the synthesized expression's type
    if (!pe.expr || !Ty::IsTyCorrect(pe.expr->ty)) {
        pe.ty = TypeManager::GetInvalidTy();
        return TypeManager::GetInvalidTy();
    }

    // Handle ideal types by replacing them with concrete ones
    if (pe.expr->ty->IsIdeal()) {
        ReplaceIdealTy(*pe.expr);
    }

    // Propagate type and constness information
    pe.ty = pe.expr->ty;
    if (pe.expr->isConst) {
        pe.isConst = true;
        pe.constNumValue = pe.expr->constNumValue;
    }

    return pe.ty;
}

bool TypeChecker::TypeCheckerImpl::ChkParenExpr(ASTContext& ctx, Ty& target, ParenExpr& pe)
{
    if (Check(ctx, &target, pe.expr.get())) {
        // Post-condition: Check() returning true guarantees pe.expr is non-null
        CJC_NULLPTR_CHECK(pe.expr);

        // Assign type from inner expression
        pe.ty = pe.expr->ty;

        // Preserve constant value propagation if applicable
        if (pe.expr->isConst) {
            pe.isConst = true;
            pe.constNumValue = pe.expr->constNumValue;
        }

        return true;
    } else {
        // On failure, mark as invalid type and return false
        pe.ty = TypeManager::GetInvalidTy();
        return false;
    }
}

