// Helper lambda to extract string values from map
static auto getStr = [](const std::map<std::string,std::string>& store,
                       const char* key,
                       std::string& result) -> bool {
    auto iter = store.find(key);
    if (iter == store.end()) return false;
    result = iter->second;
    return true;
};

// Helper lambda to parse unsigned 32-bit integers
static auto parseU32 = [](const std::string& input, uint32_t& output) -> bool {
    if (input.empty()) return false;
    char* terminator = nullptr;
    unsigned long temp = std::strtoul(input.c_str(), &terminator, 10);
    if (!terminator || *terminator != '\0') return false;
    output = static_cast<uint32_t>(temp);
    return true;
};

// Helper lambda to parse unsigned 16-bit integers
static auto parseU16 = [](const std::string& input, uint16_t& output) -> bool {
    uint32_t temp = 0;
    if (!parseU32(input, temp) || temp > 0xFFFF) return false;
    output = static_cast<uint16_t>(temp);
    return true;
};

// Helper lambda to parse unsigned 8-bit integers
static auto parseU8 = [](const std::string& input, uint8_t& output) -> bool {
    uint32_t temp = 0;
    if (!parseU32(input, temp) || temp > 0xFF) return false;
    output = static_cast<uint8_t>(temp);
    return true;
};

// Helper lambda to parse boolean from "0"/"1"
static auto parseBool01 = [](const std::string& input, bool& output) -> bool {
    if (input == "1") { output = true; return true; }
    if (input == "0") { output = false; return true; }
    return false;
};

// Helper lambda to parse float values
static auto parseF32 = [](const std::string& input, float& output) -> bool {
    if (input.empty()) return false;
    char* terminator = nullptr;
    output = std::strtof(input.c_str(), &terminator);
    if (!terminator || *terminator != '\0') return false;
    return true;
};

