std::map<std::string, std::string>
ProfileTransformer::parse(const std::string& text) {
    std::map<std::string, std::string> result;
    std::istringstream stream(text);
    std::string line;

    while (std::getline(stream, line)) {
        // Trim leading whitespace
        size_t start = line.find_first_not_of(" \t\r\n");
        if (start != std::string::npos) {
            line.erase(0, start);
        } else {
            continue;
        }

        // Trim trailing whitespace
        size_t end = line.find_last_not_of(" \t\r\n");
        if (end != std::string::npos) {
            line.erase(end + 1);
        } else {
            line.clear();
        }

        if (line.empty() || line[0] == '#') continue;

        size_t eqPos = line.find('=');
        if (eqPos == std::string::npos) continue;

        std::string key = line.substr(0, eqPos);
        std::string value = line.substr(eqPos + 1);
        result[key] = value;
    }

    return result;
}

#include "ncbind.hpp"
#include <algorithm>
#include <cmath>
#include <cstdlib>
#include <cstring>
#define NCB_MODULE_NAME TJS_W("layerExImage.dll")
#ifndef _WIN32
typedef unsigned char uint8;
typedef unsigned short uint16;
struct RGBQuad {
    uint8 blue;
    uint8 green;
    uint8 red;
    uint8 alpha;
};
#endif
#include "layerExBase_wamsoft.hpp"

// ---------- layerExImage class ----------
class layerExImage : public layerExBase
{
public:
    layerExImage(DispatchT obj) : layerExBase(obj) {}
    virtual void reset() override {
        layerExBase::reset();
        _buffer += _clipTop * _pitch + _clipLeft * 4;
        _width  = _clipWidth;
        _height = _clipHeight;
    }

    void applyLUT(uint8* lut);
    void adjustLight(int brightness, int contrast);
    void tintImage(int hue, int saturation, double factor);
    void transformHSL(int hue, int sat, int lum);
    void addNoise(int amount);
    void fillWhiteNoise();
    void applyGaussianBlur(float radius);
};

// ---------- LUT ----------
void layerExImage::applyLUT(uint8* lut) {
    uint8* scanline = reinterpret_cast<uint8*>(_buffer);
    for (int row = 0; row < _height; ++row) {
        uint8* pixel = scanline;
        for (int col = 0; col < _width; ++col) {
            pixel[0] = lut[pixel[0]];
            pixel[1] = lut[pixel[1]];
            pixel[2] = lut[pixel[2]];
            pixel += 4;
        }
        scanline += _pitch;
    }
}

// ---------- Light/Brightness/Contrast ----------
void layerExImage::adjustLight(int brightness, int contrast) {
    float factor = (100.0f + contrast) / 100.0f;
    brightness += 128;

    uint8 table[256];
    for (int i = 0; i < 256; ++i) {
        int val = static_cast<int>((i - 128) * factor + brightness);
        table[i] = static_cast<uint8>(std::max(0, std::min(255, val)));
    }

    applyLUT(table);
    redraw();
}

// ---------- HSL conversion utilities ----------
static RGBQuad rgbToHsl(RGBQuad rgb) {
    uint8 r = rgb.red;
    uint8 g = rgb.green;
    uint8 b = rgb.blue;

    uint8 maxVal = std::max({r, g, b});
    uint8 minVal = std::min({r, g, b});

    uint8 lightness = static_cast<uint8>(((maxVal + minVal) * 255 + 255) / (2 * 255));
    uint8 hue = 0, saturation = 0;

    if (maxVal == minVal) {
        saturation = 0;
        hue = 170; // undefined ~ 2/3 * 255
    } else {
        if (lightness <= 127)
            saturation = static_cast<uint8>(((maxVal - minVal) * 255 + (maxVal + minVal)/2) / (maxVal + minVal));
        else
            saturation = static_cast<uint8>(((maxVal - minVal) * 255 + (510 - maxVal - minVal)/2) / (510 - maxVal - minVal));

        uint16 rd = static_cast<uint16>(((maxVal - r) * 42 + (maxVal - minVal)/2) / (maxVal - minVal));
        uint16 gd = static_cast<uint16>(((maxVal - g) * 42 + (maxVal - minVal)/2) / (maxVal - minVal));
        uint16 bd = static_cast<uint16>(((maxVal - b) * 42 + (maxVal - minVal)/2) / (maxVal - minVal));

        if (r == maxVal) hue = static_cast<uint8>(bd - gd);
        else if (g == maxVal) hue = static_cast<uint8>(85 + rd - bd);
        else hue = static_cast<uint8>(170 + gd - rd);

        if (hue > 255) hue -= 255;
    }

    return {lightness, saturation, hue, 0};
}

static float hueInterpolate(float n1, float n2, float h) {
    if (h > 360) h -= 360;
    else if (h < 0) h += 360;

    if (h < 60)         return n1 + (n2 - n1) * h / 60.0f;
    else if (h < 180)   return n2;
    else if (h < 240)   return n1 + (n2 - n1) * (240 - h) / 60.0f;
    else                return n1;
}

static RGBQuad hslToRgb(RGBQuad hsl) {
    float h = hsl.red * 360.0f / 255.0f;
    float s = hsl.green / 255.0f;
    float l = hsl.blue / 255.0f;

    float m2 = (l <= 0.5f) ? l * (1 + s) : l + s - l * s;
    float m1 = 2 * l - m2;

    uint8 r, g, b;
    if (s == 0) {
        r = g = b = static_cast<uint8>(l * 255.0f);
    } else {
        r = static_cast<uint8>(hueInterpolate(m1, m2, h + 120) * 255.0f);
        g = static_cast<uint8>(hueInterpolate(m1, m2, h) * 255.0f);
        b = static_cast<uint8>(hueInterpolate(m1, m2, h - 120) * 255.0f);
    }

    return {b, g, r, 0};
}

// ---------- Colorize (tint with blending) ----------
void layerExImage::tintImage(int hue, int saturation, double blend) {
    if (blend < 0.0) blend = 0.0;
    if (blend > 1.0) blend = 1.0;

    int alpha0 = static_cast<int>(256 * blend);
    int alpha1 = 256 - alpha0;
    bool fullBlend = (blend > 0.999);

    uint8* scanline = reinterpret_cast<uint8*>(_buffer);
    for (int y = 0; y < _height; ++y) {
        uint8* pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            RGBQuad color = {pixel[0], pixel[1], pixel[2], 0};
            RGBQuad hsl;

            if (fullBlend) {
                color = rgbToHsl(color);
                color.red = static_cast<uint8>(hue);
                color.green = static_cast<uint8>(saturation);
                color = hslToRgb(color);
            } else {
                hsl = rgbToHsl(color);
                hsl.red = static_cast<uint8>(hue);
                hsl.green = static_cast<uint8>(saturation);
                RGBQuad result = hslToRgb(hsl);
                pixel[2] = static_cast<uint8>((result.red   * alpha0 + color.red   * alpha1) >> 8);
                pixel[0] = static_cast<uint8>((result.blue  * alpha0 + color.blue  * alpha1) >> 8);
                pixel[1] = static_cast<uint8>((result.green * alpha0 + color.green * alpha1) >> 8);
            }

            pixel += 4;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- Modulate helpers ----------
static int modulateChannel(double n1, double n2, double hue) {
    if (hue < 0) hue += 1.0;
    else if (hue > 1.0) hue -= 1.0;

    if (hue < 1.0 / 6.0)       return static_cast<int>(n1 + (n2 - n1) * hue * 6.0 * 255.0);
    else if (hue < 0.5)        return static_cast<int>(n2 * 255.0);
    else if (hue < 2.0 / 3.0)  return static_cast<int>(n1 + (n2 - n1) * (2.0/3.0 - hue) * 6.0 * 255.0);
    else                       return static_cast<int>(n1 * 255.0);
}

static void adjustPixel(int& b, int& g, int& r, double hOffset, double sScale, double lShift) {
    double red   = r / 255.0;
    double green = g / 255.0;
    double blue  = b / 255.0;

    double maxC = std::max({red, green, blue});
    double minC = std::min({red, green, blue});
    double delta = maxC - minC;
    double sum = maxC + minC;
    double luminance = sum / 2.0;
    double hue = 0.0, saturation = 0.0;

    if (delta != 0) {
        saturation = (luminance < 0.5) ? delta / sum : delta / (2.0 - sum);
        if (red == maxC) hue = (green - blue) / delta;
        else if (green == maxC) hue = 2.0 + (blue - red) / delta;
        else hue = 4.0 + (red - green) / delta;
        hue /= 6.0;
    }

    hue += hOffset;
    while (hue < 0) hue += 1.0;
    while (hue > 1.0) hue -= 1.0;

    if (sScale > 0) saturation += (1.0 - saturation) * sScale;
    else saturation += saturation * sScale;

    if (lShift > 0) luminance += (1.0 - luminance) * lShift;
    else luminance += luminance * lShift;

    if (saturation == 0.0) {
        r = g = b = static_cast<int>(luminance * 255.0);
    } else {
        double m2 = (luminance <= 0.5) ? luminance * (1 + saturation) : luminance + saturation - luminance * saturation;
        double m1 = 2 * luminance - m2;
        r = modulateChannel(m1, m2, hue + 1.0/3.0);
        g = modulateChannel(m1, m2, hue);
        b = modulateChannel(m1, m2, hue - 1.0/3.0);
    }
}

// ---------- Modulate ----------
void layerExImage::transformHSL(int hue, int saturation, int luminance) {
    double h = hue / 360.0;
    double s = saturation / 100.0;
    double l = luminance / 100.0;

    uint8* scanline = reinterpret_cast<uint8*>(_buffer);
    for (int y = 0; y < _height; ++y) {
        uint8* pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            int b = pixel[0], g = pixel[1], r = pixel[2];
            adjustPixel(b, g, r, h, s, l);
            pixel[0] = static_cast<uint8>(b);
            pixel[1] = static_cast<uint8>(g);
            pixel[2] = static_cast<uint8>(r);
            pixel += 4;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- Noise ----------
void layerExImage::addNoise(int amount) {
    uint8* scanline = reinterpret_cast<uint8*>(_buffer);
    for (int y = 0; y < _height; ++y) {
        uint8* pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            int noise = static_cast<int>((rand() / static_cast<double>(RAND_MAX) - 0.5) * amount);
            pixel[0] = static_cast<uint8>(std::max(0, std::min(255, static_cast<int>(pixel[0]) + noise)));
            noise = static_cast<int>((rand() / static_cast<double>(RAND_MAX) - 0.5) * amount);
            pixel[1] = static_cast<uint8>(std::max(0, std::min(255, static_cast<int>(pixel[1]) + noise)));
            noise = static_cast<int>((rand() / static_cast<double>(RAND_MAX) - 0.5) * amount);
            pixel[2] = static_cast<uint8>(std::max(0, std::min(255, static_cast<int>(pixel[2]) + noise)));
            pixel += 4;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- White Noise ----------
void layerExImage::fillWhiteNoise() {
    uint8* scanline = reinterpret_cast<uint8*>(_buffer);
    for (int y = 0; y < _height; ++y) {
        uint8* pixel = scanline;
        for (int x = 0; x < _width; ++x) {
            uint8 value = static_cast<uint8>(rand() / (RAND_MAX / 255));
            pixel[0] = pixel[1] = pixel[2] = value;
            pixel += 4;
        }
        scanline += _pitch;
    }
    redraw();
}

// ---------- Gaussian Blur ----------
static int32_t buildKernel(float radius, float*& kernel) {
    int32_t size;
    float stddev = std::abs(0.5f * radius) + 0.25f;
    radius = stddev * 2;

    size = static_cast<int32_t>(2 * std::ceil(radius - 0.5f) + 1);
    if (size <= 0) size = 1;

    kernel = new float[size];
    float* k = kernel;

    for (int32_t i = size / 2 + 1; i < size; ++i) {
        float pos = i - static_cast<float>(std::floor(size / 2.0)) - 0.5f;
        float sum = 0;
        for (int32_t j = 1; j <= 50; ++j) {
            if (pos + 0.02f * j <= radius)
                sum += std::exp(-(pos + 0.02f * j) * (pos + 0.02f * j) / (2 * stddev * stddev));
        }
        k[i] = sum / 50;
    }

    for (int32_t i = 0; i <= size / 2; ++i)
        k[i] = k[size - 1 - i];

    float centerSum = 0;
    for (int32_t j = 0; j <= 50; ++j)
        centerSum += std::exp(-(0.5f + 0.02f * j) * (0.5f + 0.02f * j) / (2 * stddev * stddev));
    k[size / 2] = centerSum / 51;

    float total = 0;
    for (int32_t i = 0; i < size; ++i) total += k[i];
    for (int32_t i = 0; i < size; ++i) k[i] /= total;

    return size;
}

static float* buildLut(float* kernel, int32_t len) {
    float* lut = new float[len * 256];
    float* p = lut;
    for (int32_t i = 0; i < len; ++i) {
        for (int32_t v = 0; v < 256; ++v)
            *(p++) = kernel[i] * v;
    }
    return lut;
}

static void convolveRow(float* lut, float* kernel, int32_t klen,
                        uint8* src, uint8* dst, int32_t rows, int32_t cols) {
    int32_t mid = klen / 2;
    if (klen > rows) {
        for (int32_t r = 0; r < rows; ++r) {
            float scale = 0;
            for (int32_t j = 0; j < rows; ++j)
                if (j + mid - r >= 0 && j + mid - r < klen)
                    scale += kernel[j + mid - r];

            for (int32_t c = 0; c < cols; ++c) {
                float sum = 0;
                for (int32_t j = 0; j < rows; ++j)
                    if (j >= r - mid && j <= r + mid)
                        sum += src[j * cols + c] * kernel[j];
                dst[r * cols + c] = static_cast<uint8>(0.5f + sum / scale);
            }
        }
    } else {
        for (int32_t r = 0; r < mid; ++r) {
            float scale = 0;
            for (int32_t j = mid - r; j < klen; ++j)
                scale += kernel[j];
            for (int32_t c = 0; c < cols; ++c) {
                float sum = 0;
                for (int32_t j = mid - r; j < klen; ++j)
                    sum += src[(r + j - mid) * cols + c] * kernel[j];
                dst[r * cols + c] = static_cast<uint8>(0.5f + sum / scale);
            }
        }

        for (int32_t r = mid; r < rows - mid; ++r) {
            uint8* sp = (r - mid) * cols + src;
            uint8* dp = r * cols + dst;
            for (int32_t c = 0; c < cols; ++c) {
                float sum = 0;
                float* lp = lut;
                for (int32_t j = 0; j < klen; ++j) {
                    sum += lp[*sp];
                    sp += cols;
                    lp += 256;
                }
                *dp++ = static_cast<uint8>(0.5f + sum);
            }
        }

        for (int32_t r = rows - mid; r < rows; ++r) {
            float scale = 0;
            for (int32_t j = 0; j < rows - r + mid; ++j)
                scale += kernel[j];
            for (int32_t c = 0; c < cols; ++c) {
                float sum = 0;
                for (int32_t j = 0; j < rows - r + mid; ++j)
                    sum += src[(r + j - mid) * cols + c] * kernel[j];
                dst[r * cols + c] = static_cast<uint8>(0.5f + sum / scale);
            }
        }
    }
}

static void extractColumn(uint8* src, uint8* dst, int height, int pitch) {
    pitch -= 4;
    for (int i = 0; i < height; ++i) {
        *dst++ = *src++;
        *dst++ = *src++;
        *dst++ = *src++;
        *dst++ = *src++;
        src += pitch;
    }
}

static void restoreColumn(uint8* src, uint8* dst, int height, int pitch) {
    pitch -= 4;
    for (int i = 0; i < height; ++i) {
        *src++ = *dst++;
        *src++ = *dst++;
        *src++ = *dst++;
        *src++ = *dst++;
        src += pitch;
    }
}

void layerExImage::applyGaussianBlur(float radius) {
    int stride = _width * 4;
    uint8* buffer = new uint8[stride * _height];

    float* kernel = nullptr;
    int32_t klen = buildKernel(radius, &kernel);
    float* lut = buildLut(kernel, klen);

    for (int y = 0; y < _height; ++y)
        convolveRow(lut, kernel, klen, _buffer + _pitch * y, buffer + stride * y, _width, 4);

    uint8* colSrc = new uint8[_height * 4];
    uint8* colDst = new uint8[_height * 4];

    for (int x = 0; x < _width; ++x) {
        extractColumn(buffer + x * 4, colSrc, _height, stride);
        convolveRow(lut, kernel, klen, colSrc, colDst, _height, 4);
        restoreColumn(_buffer + x * 4, colDst, _height, _pitch);
    }

    delete[] colSrc;
    delete[] colDst;
    delete[] kernel;
    delete[] lut;
    delete[] buffer;
    redraw();
}

