#include "memdebug.h"

#define HTTPPOST_PTRNAME CURL_HTTPPOST_PTRNAME
#define HTTPPOST_FILENAME CURL_HTTPPOST_FILENAME
#define HTTPPOST_PTRCONTENTS CURL_HTTPPOST_PTRCONTENTS
#define HTTPPOST_READFILE CURL_HTTPPOST_READFILE
#define HTTPPOST_PTRBUFFER CURL_HTTPPOST_PTRBUFFER
#define HTTPPOST_CALLBACK CURL_HTTPPOST_CALLBACK
#define HTTPPOST_BUFFER CURL_HTTPPOST_BUFFER

// Helper function to duplicate memory safely
static void* safe_memdup(const void *src, size_t len) {
    if (!src || !len) return NULL;
    void *dup = calloc(1, len + 1);
    if (dup) memcpy(dup, src, len);
    return dup;
}

// Helper to duplicate null-terminated string
static char* safe_strdup(const char *s) {
    if (!s) return NULL;
    size_t len = strlen(s);
    char *copy = (char*)calloc(1, len + 1);
    if (copy) memcpy(copy, s, len);
    return copy;
}

// AddHttpPost: constructs an HttpPost node from FormInfo metadata
static struct curl_httppost *
AddHttpPost(struct FormInfo *src,
            struct curl_httppost *parent_post,
            struct curl_httppost **httppost,
            struct curl_httppost **last_post)
{
  struct curl_httppost *post = NULL;
  size_t namelength = src->namelength;

  if (!namelength && src->name)
    namelength = strlen(src->name);

  // Prevent overflow during casting
  if ((src->bufferlength > LONG_MAX) || (namelength > LONG_MAX))
    return NULL;

  post = (struct curl_httppost*)calloc(1, sizeof(struct curl_httppost));
  if (!post)
    return NULL;

  // Populate fields from source
  post->name = src->name;
  post->namelength = (long)namelength;
  post->contents = src->value;
  post->contentlen = src->contentslength;
  post->buffer = src->buffer;
  post->bufferlength = (long)src->bufferlength;
  post->contenttype = src->contenttype;
  post->flags = src->flags | CURL_HTTPPOST_LARGE;
  post->contentheader = src->contentheader;
  post->showfilename = src->showfilename;
  post->userp = src->userp;

  // Insert into linked list structure
  if (parent_post) {
    post->more = parent_post->more;
    parent_post->more = post;
  } else {
    if (*last_post)
      (*last_post)->next = post;
    else
      (*httppost) = post;
    (*last_post) = post;
  }

  return post;
}

// AddFormInfo: creates a new FormInfo node and links it
static struct FormInfo *AddFormInfo(char *value,
                                    char *contenttype,
                                    struct FormInfo *parent_form_info)
{
  struct FormInfo *info = (struct FormInfo*)calloc(1, sizeof(struct FormInfo));
  if (!info)
    return NULL;

  if (value) info->value = value;
  if (contenttype) info->contenttype = contenttype;
  info->flags = HTTPPOST_FILENAME;

  if (parent_form_info) {
    info->more = parent_form_info->more;
    parent_form_info->more = info;
  }

  return info;
}

// Free all allocated members of a FormInfo chain without freeing nodes themselves
static void free_formlist(struct FormInfo *ptr)
{
  while (ptr != NULL) {
    if (ptr->name_alloc) {
      Curl_safefree(ptr->name);
      ptr->name_alloc = FALSE;
    }
    if (ptr->value_alloc) {
      Curl_safefree(ptr->value);
      ptr->value_alloc = FALSE;
    }
    if (ptr->contenttype_alloc) {
      Curl_safefree(ptr->contenttype);
      ptr->contenttype_alloc = FALSE;
    }
    if (ptr->showfilename_alloc) {
      Curl_safefree(ptr->showfilename);
      ptr->showfilename_alloc = FALSE;
    }
    ptr = ptr->more;
  }
}

// Validate and finalize form data before conversion to MIME
static CURLFORMcode FormAddCheck(struct FormInfo *first_form,
                                 struct curl_httppost **httppost,
                                 struct curl_httppost **last_post)
{
  const char *prevtype = NULL;
  struct FormInfo *form = first_form;
  struct curl_httppost *post = NULL;

  for (; form != NULL; form = form->more) {
    // Basic completeness checks
    if (((!form->name || !form->value) && !post) ||
        ((form->contentslength) && (form->flags & HTTPPOST_FILENAME)) ||
        ((form->flags & HTTPPOST_FILENAME) && (form->flags & HTTPPOST_PTRCONTENTS)) ||
        ((!form->buffer) && (form->flags & HTTPPOST_BUFFER) && (form->flags & HTTPPOST_PTRBUFFER)) ||
        ((form->flags & HTTPPOST_READFILE) && (form->flags & HTTPPOST_PTRCONTENTS)))
      return CURL_FORMADD_INCOMPLETE;

    // Auto-detect content type if missing
    if (((form->flags & HTTPPOST_FILENAME) || (form->flags & HTTPPOST_BUFFER)) &&
        !form->contenttype) {
      char *f = (form->flags & HTTPPOST_BUFFER) ? form->showfilename : form->value;
      const char *detected_type = Curl_mime_contenttype(f);
      if (!detected_type) detected_type = prevtype;
      if (!detected_type) detected_type = FILE_CONTENTTYPE_DEFAULT;

      form->contenttype = safe_strdup(detected_type);
      if (!form->contenttype)
        return CURL_FORMADD_MEMORY;
      form->contenttype_alloc = TRUE;
    }

    // Check for embedded nulls in name
    if (form->name && form->namelength &&
        memchr(form->name, 0, form->namelength))
      return CURL_FORMADD_NULL;

    // Duplicate name if not marked as pointer-only
    if (!(form->flags & HTTPPOST_PTRNAME) && form->name) {
      size_t nlen = form->namelength ? form->namelength : strlen(form->name);
      char *dupname = (char*)safe_memdup(form->name, nlen);
      if (!dupname)
        return CURL_FORMADD_MEMORY;
      form->name = dupname;
      form->name_alloc = TRUE;
    }

    // Duplicate contents if not marked as pointer-only
    if (!(form->flags & (HTTPPOST_FILENAME | HTTPPOST_READFILE |
                         HTTPPOST_PTRCONTENTS | HTTPPOST_PTRBUFFER |
                         HTTPPOST_CALLBACK)) && form->value) {
      size_t clen = (size_t)form->contentslength;
      if (!clen) clen = strlen(form->value) + 1;
      void *dupval = safe_memdup(form->value, clen);
      if (!dupval)
        return CURL_FORMADD_MEMORY;
      form->value = dupval;
      form->value_alloc = TRUE;
    }

    // Add to final HttpPost chain
    post = AddHttpPost(form, post, httppost, last_post);
    if (!post)
      return CURL_FORMADD_MEMORY;

    if (form->contenttype)
      prevtype = form->contenttype;
  }

  return CURL_FORMADD_OK;
}

// Shallow cleanup: only free the chain nodes, not their contents
static void free_chain(struct curl_httppost *c)
{
  while(c) {
    struct curl_httppost *next = c->next;
    if(c->more)
      free_chain(c->more);
    free(c);
    c = next;
  }
}

// Main parsing loop for va_list arguments
static CURLFORMcode FormAdd(struct curl_httppost **httppost,
                            struct curl_httppost **last_post,
                            va_list params)
{
  struct FormInfo *first_form = NULL, *curr = NULL, *form = NULL;
  CURLFORMcode retval = CURL_FORMADD_OK;
  CURLformoption option;
  struct curl_forms *forms = NULL;
  char *avalue = NULL;
  struct curl_httppost *newchain = NULL;
  struct curl_httppost *lastnode = NULL;
  bool array_state = FALSE;

  // Allocate initial FormInfo node
  first_form = (struct FormInfo*)calloc(1, sizeof(struct FormInfo));
  if (!first_form)
    return CURL_FORMADD_MEMORY;
  curr = first_form;

  // Parse input options
  while (retval == CURL_FORMADD_OK) {
    if (array_state && forms) {
      option = forms->option;
      avalue = (char *)CURL_UNCONST(forms->value);
      forms++;
      if (CURLFORM_END == option) {
        array_state = FALSE;
        continue;
      }
    } else {
      option = (CURLformoption)va_arg(params, int);
      if (CURLFORM_END == option)
        break;
    }

    switch (option) {
    case CURLFORM_ARRAY:
      if (array_state)
        retval = CURL_FORMADD_ILLEGAL_ARRAY;
      else {
        forms = va_arg(params, struct curl_forms *);
        if (forms)
          array_state = TRUE;
        else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_PTRNAME:
      curr->flags |= HTTPPOST_PTRNAME;
      FALLTHROUGH();
    case CURLFORM_COPYNAME:
      if (curr->name)
        retval = CURL_FORMADD_OPTION_TWICE;
      else {
        if (!array_state)
          avalue = va_arg(params, char *);
        if (avalue)
          curr->name = avalue;
        else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_NAMELENGTH:
      if (curr->namelength)
        retval = CURL_FORMADD_OPTION_TWICE;
      else
        curr->namelength = array_state ? (size_t)avalue : (size_t)va_arg(params, long);
      break;

    case CURLFORM_PTRCONTENTS:
      curr->flags |= HTTPPOST_PTRCONTENTS;
      FALLTHROUGH();
    case CURLFORM_COPYCONTENTS:
      if (curr->value)
        retval = CURL_FORMADD_OPTION_TWICE;
      else {
        if (!array_state)
          avalue = va_arg(params, char *);
        if (avalue)
          curr->value = avalue;
        else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_CONTENTSLENGTH:
      curr->contentslength = array_state ? (size_t)avalue : (size_t)va_arg(params, long);
      break;

    case CURLFORM_CONTENTLEN:
      curr->flags |= CURL_HTTPPOST_LARGE;
      curr->contentslength = array_state ?
        (curl_off_t)(size_t)avalue : va_arg(params, curl_off_t);
      break;

    case CURLFORM_FILECONTENT:
      if (curr->flags & (HTTPPOST_PTRCONTENTS|HTTPPOST_READFILE))
        retval = CURL_FORMADD_OPTION_TWICE;
      else {
        if (!array_state)
          avalue = va_arg(params, char *);
        if (avalue) {
          curr->value = safe_strdup(avalue);
          if (!curr->value)
            retval = CURL_FORMADD_MEMORY;
          else {
            curr->flags |= HTTPPOST_READFILE;
            curr->value_alloc = TRUE;
          }
        } else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_FILE:
      if (!array_state)
        avalue = va_arg(params, char *);
      if (curr->value) {
        if (curr->flags & HTTPPOST_FILENAME) {
          if (avalue) {
            char *fname = safe_strdup(avalue);
            if (!fname)
              retval = CURL_FORMADD_MEMORY;
            else {
              form = AddFormInfo(fname, NULL, curr);
              if (!form) {
                free(fname);
                retval = CURL_FORMADD_MEMORY;
              } else {
                form->value_alloc = TRUE;
                curr = form;
                form = NULL;
              }
            }
          } else
            retval = CURL_FORMADD_NULL;
        } else
          retval = CURL_FORMADD_OPTION_TWICE;
      } else {
        if (avalue) {
          curr->value = safe_strdup(avalue);
          if (!curr->value)
            retval = CURL_FORMADD_MEMORY;
          else {
            curr->flags |= HTTPPOST_FILENAME;
            curr->value_alloc = TRUE;
          }
        } else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_BUFFERPTR:
      curr->flags |= HTTPPOST_PTRBUFFER | HTTPPOST_BUFFER;
      if (curr->buffer)
        retval = CURL_FORMADD_OPTION_TWICE;
      else {
        if (!array_state)
          avalue = va_arg(params, char *);
        if (avalue) {
          curr->buffer = avalue;
          curr->value = avalue;
        } else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_BUFFERLENGTH:
      if (curr->bufferlength)
        retval = CURL_FORMADD_OPTION_TWICE;
      else
        curr->bufferlength = array_state ? (size_t)avalue : (size_t)va_arg(params, long);
      break;

    case CURLFORM_STREAM:
      curr->flags |= HTTPPOST_CALLBACK;
      if (curr->userp)
        retval = CURL_FORMADD_OPTION_TWICE;
      else {
        if (!array_state)
          avalue = va_arg(params, char *);
        if (avalue) {
          curr->userp = avalue;
          curr->value = avalue;
        } else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_CONTENTTYPE:
      if (!array_state)
        avalue = va_arg(params, char *);
      if (curr->contenttype) {
        if (curr->flags & HTTPPOST_FILENAME) {
          if (avalue) {
            char *type = safe_strdup(avalue);
            if (!type)
              retval = CURL_FORMADD_MEMORY;
            else {
              form = AddFormInfo(NULL, type, curr);
              if (!form) {
                free(type);
                retval = CURL_FORMADD_MEMORY;
              } else {
                form->contenttype_alloc = TRUE;
                curr = form;
                form = NULL;
              }
            }
          } else
            retval = CURL_FORMADD_NULL;
        } else
          retval = CURL_FORMADD_OPTION_TWICE;
      } else {
        if (avalue) {
          curr->contenttype = safe_strdup(avalue);
          if (!curr->contenttype)
            retval = CURL_FORMADD_MEMORY;
          else
            curr->contenttype_alloc = TRUE;
        } else
          retval = CURL_FORMADD_NULL;
      }
      break;

    case CURLFORM_CONTENTHEADER:
      {
        struct curl_slist *list = array_state ?
          (struct curl_slist *)(void *)avalue :
          va_arg(params, struct curl_slist *);
        if (curr->contentheader)
          retval = CURL_FORMADD_OPTION_TWICE;
        else
          curr->contentheader = list;
        break;
      }

    case CURLFORM_FILENAME:
    case CURLFORM_BUFFER:
      if (!array_state)
        avalue = va_arg(params, char *);
      if (curr->showfilename)
        retval = CURL_FORMADD_OPTION_TWICE;
      else {
        curr->showfilename = safe_strdup(avalue);
        if (!curr->showfilename)
          retval = CURL_FORMADD_MEMORY;
        else
          curr->showfilename_alloc = TRUE;
      }
      break;

    default:
      retval = CURL_FORMADD_UNKNOWN_OPTION;
      break;
    }
  }

  if (!retval)
    retval = FormAddCheck(first_form, &newchain, &lastnode);

  if (retval) {
    free_formlist(first_form);
  }

  // Deallocate FormInfo nodes regardless of success/failure
  while (first_form) {
    struct FormInfo *tmp = first_form->more;
    free(first_form);
    first_form = tmp;
  }

  if (!retval) {
    if (*last_post)
      (*last_post)->next = newchain;
    else
      (*httppost) = newchain;
    (*last_post) = lastnode;
  } else {
    free_chain(newchain);
  }

  return retval;
}

// Public API entry point
CURLFORMcode curl_formadd(struct curl_httppost **httppost,
                          struct curl_httppost **last_post,
                          ...)
{
  va_list arg;
  CURLFORMcode result;
  va_start(arg, last_post);
  result = FormAdd(httppost, last_post, arg);
  va_end(arg);
  return result;
}

// Serialize form data using callback
int curl_formget(struct curl_httppost *form, void *arg,
                 curl_formget_callback append)
{
  CURLcode result;
  curl_mimepart toppart;
  Curl_mime_initpart(&toppart);
  result = Curl_getformdata(NULL, &toppart, form, NULL);
  if (!result)
    result = Curl_mime_prepare_headers(NULL, &toppart, "multipart/form-data",
                                       NULL, MIMESTRATEGY_FORM);
  while (!result) {
    char buffer[8192];
    size_t nread = Curl_mime_read(buffer, 1, sizeof(buffer), &toppart);
    if (!nread)
      break;
    if (nread > sizeof(buffer) || append(arg, buffer, nread) != nread) {
      result = CURLE_READ_ERROR;
      if (nread == CURL_READFUNC_ABORT)
        result = CURLE_ABORTED_BY_CALLBACK;
    }
  }
  Curl_mime_cleanpart(&toppart);
  return (int)result;
}

// Free entire form post chain recursively
void curl_formfree(struct curl_httppost *form)
{
  struct curl_httppost *next;
  if (!form)
    return;

  do {
    next = form->next;
    curl_formfree(form->more);
    if (!(form->flags & HTTPPOST_PTRNAME))
      free(form->name);
    if (!(form->flags &
         (HTTPPOST_PTRCONTENTS | HTTPPOST_BUFFER | HTTPPOST_CALLBACK)))
      free(form->contents);
    free(form->contenttype);
    free(form->showfilename);
    free(form);
    form = next;
  } while (form);
}

// Set mime part name with length safety
static CURLcode setname(curl_mimepart *part, const char *name, size_t len)
{
  char *zname;
  CURLcode res;
  if (!name || !len)
    return curl_mime_name(part, name);
  zname = (char*)safe_memdup(name, len);
  if (!zname)
    return CURLE_OUT_OF_MEMORY;
  res = curl_mime_name(part, zname);
  free(zname);
  return res;
}

// Platform-aware fseek wrapper
static int fseeko_wrapper(void *stream, curl_off_t offset, int whence)
{
#if defined(_WIN32) && defined(USE_WIN32_LARGE_FILES)
  return _fseeki64(stream, (__int64)offset, whence);
#elif defined(HAVE_FSEEKO) && defined(HAVE_DECL_FSEEKO)
  return fseeko(stream, (off_t)offset, whence);
#else
  if (offset > LONG_MAX)
    return -1;
  return fseek(stream, (long)offset, whence);
#endif
}

// Convert linked list to mime structure
CURLcode Curl_getformdata(CURL *data,
                          curl_mimepart *finalform,
                          struct curl_httppost *post,
                          curl_read_callback fread_func)
{
  CURLcode result = CURLE_OK;
  curl_mime *form = NULL;
  curl_mimepart *part;
  struct curl_httppost *file;

  Curl_mime_cleanpart(finalform);
  if (!post)
    return result;

  form = curl_mime_init(data);
  if (!form)
    result = CURLE_OUT_OF_MEMORY;

  if (!result)
    result = curl_mime_subparts(finalform, form);

  for (; !result && post; post = post->next) {
    curl_mime *multipart = form;
    if (post->more) {
      part = curl_mime_addpart(form);
      if (!part)
        result = CURLE_OUT_OF_MEMORY;
      if (!result)
        result = setname(part, post->name, post->namelength);
      if (!result) {
        multipart = curl_mime_init(data);
        if (!multipart)
          result = CURLE_OUT_OF_MEMORY;
      }
      if (!result)
        result = curl_mime_subparts(part, multipart);
    }

    for (file = post; !result && file; file = file->more) {
      part = curl_mime_addpart(multipart);
      if (!part)
        result = CURLE_OUT_OF_MEMORY;

      if (!result)
        result = curl_mime_headers(part, file->contentheader, 0);
      if (!result && file->contenttype)
        result = curl_mime_type(part, file->contenttype);
      if (!result && !post->more)
        result = setname(part, post->name, post->namelength);

      if (!result) {
        curl_off_t clen = post->contentslength;
        if (post->flags & CURL_HTTPPOST_LARGE)
          clen = post->contentlen;

        if (post->flags & (HTTPPOST_FILENAME | HTTPPOST_READFILE)) {
          if (!strcmp(file->contents, "-")) {
            result = curl_mime_data_cb(part, (curl_off_t)-1,
                                       (curl_read_callback)fread,
                                       fseeko_wrapper,
                                       NULL, (void *)stdin);
          } else
            result = curl_mime_filedata(part, file->contents);
          if (!result && (post->flags & HTTPPOST_READFILE))
            result = curl_mime_filename(part, NULL);
        } else if (post->flags & HTTPPOST_BUFFER) {
          result = curl_mime_data(part, post->buffer,
                                  post->bufferlength ? post->bufferlength : -1);
        } else if (post->flags & HTTPPOST_CALLBACK) {
          if (!clen)
            clen = -1;
          result = curl_mime_data_cb(part, clen,
                                     fread_func, NULL, NULL, post->userp);
        } else {
          size_t uclen = clen ? (size_t)clen : CURL_ZERO_TERMINATED;
          result = curl_mime_data(part, post->contents, uclen);
        }
      }

      if (!result && post->showfilename) {
        if (post->more || (post->flags & (HTTPPOST_FILENAME | HTTPPOST_BUFFER |
                                         HTTPPOST_CALLBACK)))
          result = curl_mime_filename(part, post->showfilename);
      }
    }
  }

  if (result)
    Curl_mime_cleanpart(finalform);
  return result;
}

#else
// Disabled implementations
CURLFORMcode curl_formadd(struct curl_httppost **httppost,
