namespace CTRPF = CTRPluginFramework;
using InventorySlot = Minecraft::Inventory::InventorySlot;
using Item = Game::Item;

// ============================================================================
//$Game.LocalPlayer.Inventory.Slots
// Accesses inventory slots by numeric index or special key like "hand"
// ============================================================================
static int l_Inventory_Slots_Get(lua_State* L) {
    int slotIndex = -1;

    // Determine requested slot index from argument
    if (lua_isnumber(L, 2)) {
        slotIndex = static_cast<int>(lua_tointeger(L, 2));
    } else if (lua_isstring(L, 2)) {
        const char* keyStr = lua_tostring(L, 2);
        uint32_t h = hash(keyStr);

        if (h == hash("hand")) {
            slotIndex = Minecraft::GetHeldSlotNumber();
        }
    }

    // If no valid index found, return nil
    if (slotIndex < 0 || slotIndex > 36) {
        lua_pushnil(L);
        return 1;
    }

    void* addr = Minecraft::GetSlotAddress(slotIndex);
    LuaObjectUtils::NewObjectCheck(L, "InventorySlot", reinterpret_cast<InventorySlot*>(addr));
    return 1;
}

// ============================================================================
//$Game.LocalPlayer.Inventory.ArmorSlots
// Maps armor slot names ("helmet", etc.) or numbers to actual memory addresses
// ============================================================================
static int l_Inventory_ArmorSlots_Get(lua_State* L) {
    int armorIndex = 0;

    if (lua_isnumber(L, 2)) {
        armorIndex = static_cast<int>(lua_tointeger(L, 2));
    } else if (lua_isstring(L, 2)) {
        const char* name = lua_tostring(L, 2);
        uint32_t h = hash(name);

        if (h == hash("helmet"))      armorIndex = 1;
        else if (h == hash("chestplate")) armorIndex = 2;
        else if (h == hash("leggings"))   armorIndex = 3;
        else if (h == hash("boots"))      armorIndex = 4;
        else {
            lua_pushnil(L);
            return 1;
        }
    }

    void* addr = Minecraft::GetArmorSlotAddress(armorIndex);
    LuaObjectUtils::NewObjectCheck(L, "InventorySlot", reinterpret_cast<InventorySlot*>(addr));
    return 1;
}

// ============================================================================
// InventorySlot methods
// ============================================================================

/*
## return: boolean
### InventorySlot:isEmpty
*/
static int l_InventorySlot_IsEmpty(lua_State* L) {
    auto slot = LuaObjectUtils::CheckObject<InventorySlot>(L, 1, "InventorySlot");
    bool empty = (slot->itemCount == 0 || slot->itemData == nullptr);
    lua_pushboolean(L, empty);
    return 1;
}

/*
## item: GameItem
## value: integer?
## return: boolean
### InventorySlot:setItem
*/
static int l_InventorySlot_SetItem(lua_State* L) {
    auto instance = LuaObjectUtils::CheckObject<MC3DSPluginFramework::ItemInstance>(L, 1, "InventorySlot");
    auto itemObj  = LuaObjectUtils::CheckObject<Item>(L, 2, "GameItem");

    u16 damageValue = 0;
    if (lua_gettop(L) >= 3 && lua_isnumber(L, 3)) {
        damageValue = static_cast<u16>(luaL_checkinteger(L, 3));
    }

    u8 stackSize = instance->mCount;
    u8 maxStack  = itemObj->maxStackSize;
    if (stackSize > maxStack) {
        stackSize = maxStack;
    }

    instance->init(
        static_cast<MC3DSPluginFramework::ItemId>(itemObj->itemId),
        stackSize,
        damageValue
    );

    return 1;
}

// ============================================================================
// Type registration helpers
// ============================================================================
template<>
struct LuaTypeName<Item> {
    static constexpr const char* value = "GameItem";
};

// ============================================================================
// Module registration entry point
// ============================================================================
bool Core::Module::LocalPlayer::RegisterInventoryModule(lua_State* L) {
    // Register InventorySlot class with properties and methods
    ClassBuilder<InventorySlot>(L, "InventorySlot")
        .property("Item", &InventorySlot::itemData)
        .property("ItemCount", &InventorySlot::itemCount)
        .property("ItemData", &InventorySlot::dataValue)
        .method("isEmpty", l_InventorySlot_IsEmpty)
        .method("setItem", l_InventorySlot_SetItem)
        .build();

    // Create custom tables for Slots and ArmorSlots
    LuaCustomTable::RegisterNewCustomTable(L, "Inventory");
    LuaCustomTable::RegisterNewCustomTable(L, "Inventory.Slots", l_Inventory_Slots_Get);
    LuaCustomTable::RegisterNewCustomTable(L, "Inventory.ArmorSlots", l_Inventory_ArmorSlots_Get);

    // Build hierarchy: LocalPlayer.Inventory.Slots / ArmorSlots
    LuaCustomTable::GetIndexTable(L, "Inventory"); // Stack: [Inventory]
    LuaCustomTable::NewCustomTable(L, "Inventory.Slots"); // Stack: [Inventory, Slots]
    lua_setfield(L, -2, "Slots"); // Inventory.Slots = ...

    LuaCustomTable::NewCustomTable(L, "Inventory.ArmorSlots"); // Stack: [Inventory, ArmorSlots]
    lua_setfield(L, -2, "ArmorSlots"); // Inventory.ArmorSlots = ...

    lua_pop(L, 1); // Pop Inventory index table

    // Assign Inventory to LocalPlayer
    LuaCustomTable::SetNewCustomTable(L, -1, "Inventory");
    return true;
}

