  void Sdl2WsiDriver::getWindowSize(
        HWND      hWindow,
        uint32_t* pWidth,
        uint32_t* pHeight) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    int widthPx = 0;
    int heightPx = 0;

    SDL_GetWindowSize(sdlWindow, &widthPx, &heightPx);

    if (pWidth != nullptr)
      *pWidth = static_cast<uint32_t>(widthPx);
    if (pHeight != nullptr)
      *pHeight = static_cast<uint32_t>(heightPx);
  }

  void Sdl2WsiDriver::resizeWindow(
          HWND             hWindow,
          DxvkWindowState* pState,
          uint32_t         newWidth,
          uint32_t         newHeight) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    SDL_SetWindowSize(sdlWindow, static_cast<int>(newWidth), static_cast<int>(newHeight));
  }

  bool Sdl2WsiDriver::setWindowMode(
          HMONITOR         hMonitor,
          HWND             hWindow,
          DxvkWindowState* pState,
    const WsiMode&         modeInfo) {
    const int displayIndex = fromHmonitor(hMonitor);
    if (!isDisplayValid(displayIndex))
      return false;

    SDL_Window* sdlWindow = fromHwnd(hWindow);

    SDL_DisplayMode desiredMode{};
    desiredMode.w            = modeInfo.width;
    desiredMode.h            = modeInfo.height;
    desiredMode.refresh_rate = (modeInfo.refreshRate.numerator != 0)
      ? static_cast<float>(modeInfo.refreshRate.numerator) / modeInfo.refreshRate.denominator
      : 0.0f;

    SDL_DisplayMode closestMode{};
    if (SDL_GetClosestDisplayMode(displayIndex, &desiredMode, &closestMode) == nullptr) {
      Logger::err(str::format("SDL2 WSI: setWindowMode: SDL_GetClosestDisplayMode failed — ", SDL_GetError()));
      return false;
    }

    if (SDL_SetWindowDisplayMode(sdlWindow, &closestMode) != 0) {
      Logger::err(str::format("SDL2 WSI: setWindowMode: SDL_SetWindowDisplayMode failed — ", SDL_GetError()));
      return false;
    }

    return true;
  }

  bool Sdl2WsiDriver::enterFullscreenMode(
          HMONITOR         hMonitor,
          HWND             hWindow,
          DxvkWindowState* pState,
          bool             performModeSwitch) {
    const int displayIdx = fromHmonitor(hMonitor);
    if (!isDisplayValid(displayIdx))
      return false;

    SDL_Window* sdlWindow = fromHwnd(hWindow);

    Uint32 fullscreenFlags = performModeSwitch
      ? SDL_WINDOW_FULLSCREEN
      : SDL_WINDOW_FULLSCREEN_DESKTOP;

    // Note: Monitor assignment not yet implemented per TODO.
    if (SDL_SetWindowFullscreen(sdlWindow, fullscreenFlags) != 0) {
      Logger::err(str::format("SDL2 WSI: enterFullscreenMode: SDL_SetWindowFullscreen failed — ", SDL_GetError()));
      return false;
    }

    return true;
  }

  bool Sdl2WsiDriver::leaveFullscreenMode(
          HWND             hWindow,
          DxvkWindowState* pState,
          bool             restoreCoords) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    if (SDL_SetWindowFullscreen(sdlWindow, 0) != 0) {
      Logger::err(str::format("SDL2 WSI: leaveFullscreenMode: SDL_SetWindowFullscreen failed — ", SDL_GetError()));
      return false;
    }
    return true;
  }

  bool Sdl2WsiDriver::restoreDisplayMode() {
    // No-op for SDL2 backend
    return true;
  }

  HMONITOR Sdl2WsiDriver::getWindowMonitor(HWND hWindow) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    const int displayIndex = SDL_GetWindowDisplayIndex(sdlWindow);
    return toHmonitor(displayIndex);
  }

  bool Sdl2WsiDriver::isWindow(HWND hWindow) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    return sdlWindow != nullptr;
  }

  bool Sdl2WsiDriver::isMinimized(HWND hWindow) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    const Uint32 flags = SDL_GetWindowFlags(sdlWindow);
    return (flags & SDL_WINDOW_MINIMIZED) != 0;
  }

  bool Sdl2WsiDriver::isOccluded(HWND hWindow) {
    return false; // Always report not occluded in SDL2 implementation
  }

  void Sdl2WsiDriver::updateFullscreenWindow(
          HMONITOR hMonitor,
          HWND     hWindow,
          bool     forceTopmost) {
    // Not required for SDL2-based WSI
  }

  VkResult Sdl2WsiDriver::createSurface(
          HWND                      hWindow,
          PFN_vkGetInstanceProcAddr pfnVkGetInstanceProcAddr,
          VkInstance                instance,
          VkSurfaceKHR*             pSurface) {
    SDL_Window* sdlWindow = fromHwnd(hWindow);
    const bool success = SDL_Vulkan_CreateSurface(sdlWindow, instance, pSurface);
    return success ? VK_SUCCESS : VK_ERROR_OUT_OF_HOST_MEMORY;
  }

}
