#include "USBMIDIParser.h"

// Map CIN codes to expected MIDI message lengths in bytes
uint8_t USBMIDICinToMIDIByteCount(uint8_t cinCode)
{
    if (cinCode == kCIN_Misc || cinCode == kCIN_CableEvent) {
        return 0;
    }
    else if (cinCode == kCIN_SystemCommon2Byte || 
             cinCode == kCIN_ProgramChange || 
             cinCode == kCIN_ChannelPressure) {
        return 2;
    }
    else if (cinCode == kCIN_SysExStart ||
             cinCode == kCIN_NoteOff ||
             cinCode == kCIN_NoteOn ||
             cinCode == kCIN_PolyAftertouch ||
             cinCode == kCIN_ControlChange ||
             cinCode == kCIN_PitchBend ||
             cinCode == kCIN_SysExEnd3Byte) {
        return 3;
    }
    else if (cinCode == kCIN_SysExEnd1Byte || 
             cinCode == kCIN_SingleByte) {
        return 1;
    }
    else if (cinCode == kCIN_SysExEnd2Byte) {
        return 2;
    }
    return 0; // fallback for unknown or unhandled cases
}

// Derive CIN from MIDI status byte
uint8_t MIDIStatusToCin(uint8_t status)
{
    if (status < 0x80U) {
        return kCIN_Misc;
    }

    uint8_t topNibble = status >> 4;

    if (topNibble == 0x8U) {
        return kCIN_NoteOff;
    } else if (topNibble == 0x9U) {
        return kCIN_NoteOn;
    } else if (topNibble == 0xAU) {
        return kCIN_PolyAftertouch;
    } else if (topNibble == 0xBU) {
        return kCIN_ControlChange;
    } else if (topNibble == 0xCU) {
        return kCIN_ProgramChange;
    } else if (topNibble == 0xDU) {
        return kCIN_ChannelPressure;
    } else if (topNibble == 0xEU) {
        return kCIN_PitchBend;
    } else if (topNibble == 0xFU) {
        switch (status) {
            case 0xF0U: return kCIN_SysExStart;
            case 0xF1U:
            case 0xF3U: return kCIN_SystemCommon2Byte;
            case 0xF2U: return kCIN_SystemCommon3Byte;
            case 0xF6U:
            case 0xF7U: return kCIN_SysExEnd1Byte;
            case 0xF8U: case 0xF9U: case 0xFAU: case 0xFBU: 
            case 0xFCU: case 0xFEU: case 0xFFU:
                return kCIN_SingleByte;
            default:
                return kCIN_Misc;
        }
    }

    return kCIN_Misc;
}

// Parse bulk-in data into individual MIDI messages
void USBMIDIParseBulkIn(const uint8_t *inputData,
                        uint32_t totalBytes,
                        USBMIDIParseCallback handler,
                        void *userData)
{
    if (!inputData || !handler) return;

    for (uint32_t idx = 0; idx + 4 <= totalBytes; idx += 4) {
        uint8_t headerByte = inputData[idx];
        uint8_t packetType = headerByte & 0x0F;
        uint8_t cableId = (headerByte >> 4) & 0x0F;

        uint8_t payloadSize = USBMIDICinToMIDIByteCount(packetType);
        if (payloadSize == 0) continue;

        const uint8_t *messagePayload = inputData + idx + 1;
        handler(cableId, messagePayload, payloadSize, userData);
    }
}

// Determine length of standard channel voice messages
static uint8_t determineChannelMsgLength(uint8_t statusByte)
{
    uint8_t opcode = statusByte & 0xF0;
    if (opcode == 0xC0 || opcode == 0xD0) {
        return 2;
    }
    return 3;
}

// Convert raw MIDI bytes into USB-MIDI bulk-out packets
uint32_t USBMIDIBuildBulkOut(const uint8_t *midiInput,
                             uint32_t inputLen,
                             uint8_t cableIndex,
                             uint8_t *outputBuffer,
                             uint32_t bufferCapacity)
{
    if (!midiInput || !outputBuffer || inputLen == 0) return 0;

    uint32_t outPos = 0;
    uint32_t inPos = 0;
    bool sysexActive = false;
    uint8_t sysexBuffer[3] = {0};
    uint8_t sysexFilled = 0;

    while (inPos < inputLen && outPos + 4 <= bufferCapacity) {
        uint8_t currentByte = midiInput[inPos];

        if (currentByte == 0xF0) {
            sysexActive = true;
            sysexBuffer[0] = currentByte;
            sysexFilled = 1;
            ++inPos;
        } else if (sysexActive) {
            if (currentByte == 0xF7) {
                sysexBuffer[sysexFilled++] = currentByte;

                uint8_t cinCode;
                if (sysexFilled == 1) cinCode = kCIN_SysExEnd1Byte;
                else if (sysexFilled == 2) cinCode = kCIN_SysExEnd2Byte;
                else if (sysexFilled == 3) cinCode = kCIN_SysExEnd3Byte;
                else cinCode = kCIN_SysExEnd1Byte;

                outputBuffer[outPos + 0] = (cableIndex << 4) | cinCode;
                outputBuffer[outPos + 1] = (sysexFilled > 0) ? sysexBuffer[0] : 0;
                outputBuffer[outPos + 2] = (sysexFilled > 1) ? sysexBuffer[1] : 0;
                outputBuffer[outPos + 3] = (sysexFilled > 2) ? sysexBuffer[2] : 0;
                outPos += 4;

                sysexActive = false;
                sysexFilled = 0;
                ++inPos;
            } else if (currentByte >= 0x80 && currentByte != 0xF7) {
                // Real-time message inside SysEx
                outputBuffer[outPos + 0] = (cableIndex << 4) | kCIN_SingleByte;
                outputBuffer[outPos + 1] = currentByte;
                outputBuffer[outPos + 2] = 0;
                outputBuffer[outPos + 3] = 0;
                outPos += 4;
                ++inPos;
            } else {
                sysexBuffer[sysexFilled++] = currentByte;
                ++inPos;

                if (sysexFilled == 3) {
                    outputBuffer[outPos + 0] = (cableIndex << 4) | kCIN_SysExStart;
                    outputBuffer[outPos + 1] = sysexBuffer[0];
                    outputBuffer[outPos + 2] = sysexBuffer[1];
                    outputBuffer[outPos + 3] = sysexBuffer[2];
                    outPos += 4;
                    sysexFilled = 0;
                }
            }
        } else if (currentByte >= 0x80) {
            if (currentByte >= 0xF8) {
                outputBuffer[outPos + 0] = (cableIndex << 4) | kCIN_SingleByte;
                outputBuffer[outPos + 1] = currentByte;
                outputBuffer[outPos + 2] = 0;
                outputBuffer[outPos + 3] = 0;
                outPos += 4;
                ++inPos;
            } else if (currentByte >= 0xF0) {
                uint8_t cinCode = MIDIStatusToCin(currentByte);
                uint8_t msgLen = USBMIDICinToMIDIByteCount(cinCode);

                if (inPos + msgLen > inputLen) break;

                outputBuffer[outPos + 0] = (cableIndex << 4) | cinCode;
                outputBuffer[outPos + 1] = midiInput[inPos];
                outputBuffer[outPos + 2] = (msgLen >= 2) ? midiInput[inPos + 1] : 0;
                outputBuffer[outPos + 3] = (msgLen >= 3) ? midiInput[inPos + 2] : 0;
                outPos += 4;
                inPos += msgLen;
            } else {
                uint8_t msgLen = determineChannelMsgLength(currentByte);
                if (inPos + msgLen > inputLen) break;

                uint8_t cinCode = MIDIStatusToCin(currentByte);
                outputBuffer[outPos + 0] = (cableIndex << 4) | cinCode;
                outputBuffer[outPos + 1] = midiInput[inPos];
                outputBuffer[outPos + 2] = (msgLen >= 2) ? midiInput[inPos + 1] : 0;
                outputBuffer[outPos + 3] = (msgLen >= 3) ? midiInput[inPos + 2] : 0;
                outPos += 4;
                inPos += msgLen;
            }
        } else {
            ++inPos; // Skip non-status/data-only bytes
        }
    }

    return outPos;
}

