bool OPNMIDIplay::LoadMIDI_post()
{
    Synth &synth = *m_synth;
    MidiSequencer &seq = *m_sequencer;

    // Determine file format and handle accordingly
    switch (static_cast<int>(seq.getFormat()))
    {
        case static_cast<int>(MidiSequencer::Format_CMF):
            errorStringOut = "OPNMIDI doesn't supports CMF, use ADLMIDI to play this file!";
            /* As joke, why not to try implemented the converter of patches from OPL3 into OPN2? */
            return false;

        case static_cast<int>(MidiSequencer::Format_RSXX):
            synth.m_musicMode     = Synth::MODE_RSXX;
            synth.m_volumeScale   = Synth::VOLUME_Generic;
            synth.m_numChips      = 2;
            break;

        case static_cast<int>(MidiSequencer::Format_IMF):
            errorStringOut = "OPNMIDI doesn't supports IMF, use ADLMIDI to play this file!";
            /* Same as for CMF */
            return false;

        case static_cast<int>(MidiSequencer::Format_XMIDI):
            synth.m_musicMode = Synth::MODE_XMIDI;
            break;

        default:
            // Unknown format — treat as unsupported
            errorStringOut = "OPNMIDI: Unsupported MIDI file format.";
            return false;
    }

    m_setup.tick_skip_samples_delay = 0;
    synth.reset(m_setup.emulator, m_setup.PCM_RATE, synth.chipFamily(), this); // Reset OPN2 chip

    // Reinitialize chip channel state
    m_chipChannels.clear();
    m_chipChannels.resize(synth.m_numChannels);

    resetMIDIDefaults();

#ifdef OPNMIDI_MIDI2VGM
    // Assign loop hooks if available
    auto &iface = *m_sequencerInterface;
    iface.onloopStart       = synth.m_loopStartHook;
    iface.onloopStart_userData = synth.m_loopStartHookData;
    iface.onloopEnd         = synth.m_loopEndHook;
    iface.onloopEnd_userData   = synth.m_loopEndHookData;
    seq.setLoopHooksOnly(iface.onloopStart != nullptr);
#endif

    return true;
}
bool OPNMIDIplay::LoadMIDI(const std::string &filename)
{
    FileAndMemReader file;
    if (!file.openFile(filename.c_str()))
        return false;

    if (!LoadMIDI_pre())
        return false;

    MidiSequencer &seq = *m_sequencer;
    if (!seq.loadMIDI(file))
    {
        errorStringOut = seq.getErrorString();
        return false;
    }

    if (!LoadMIDI_post())
        return false;

    return true;
}
bool OPNMIDIplay::LoadMIDI(const void *data, size_t size)
{
    FileAndMemReader file;
    if (!file.openData(data, size))
        return false;

    if (!LoadMIDI_pre())
        return false;

    MidiSequencer &seq = *m_sequencer;
    if (!seq.loadMIDI(file))
    {
        errorStringOut = seq.getErrorString();
        return false;
    }

    if (!LoadMIDI_post())
        return false;

    return true;
}
