#include "AsmWriterInst.h"
#include "CodeGenInstruction.h"
#include "llvm/ADT/StringExtras.h"
#include "llvm/TableGen/Error.h"
#include "llvm/TableGen/Record.h"

using namespace llvm;

// Helper: checks if character is valid in identifier context
static bool isValidIdentifierChar(char c) {
    return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
}

// Helper: escapes special characters for literal string output
static std::string escapeForLiteral(char c) {
    switch (c) {
        case '\n':  return "\\n";
        case '\t':  return "\\t";
        case '"':   return "\\\"";
        case '\\':  return "\\\\";
        default:    return std::string(1, c);
    }
}

// Helper: processes escaped sequences like \n, \t, etc.
static void handleEscapedChar(const CodeGenInstruction &CGI,
                              const std::string &asmStr,
                              std::size_t pos,
                              std::size_t &lastEmitted) {
    if (pos + 1 >= asmStr.size()) {
        PrintFatalError(CGI.TheDef->getLoc(),
                        "Trailing backslash at end of asm string in '" +
                            CGI.TheDef->getName() + "'");
    }

    char next = asmStr[pos + 1];
    if (next == 'n') {
        AsmWriterOperand::AddLiteralString("\\n");
    } else if (next == 't') {
        AsmWriterOperand::AddLiteralString("\\t");
    } else if (std::string("${|}\\").find(next) != std::string::npos) {
        AsmWriterOperand::AddLiteralString(std::string(1, next));
    } else {
        PrintFatalError(CGI.TheDef->getLoc(),
                        "Unsupported escape sequence '\\"
                        + std::string(1, next)
                        + "' in instruction '" + CGI.TheDef->getName() + "'");
    }
    lastEmitted = pos + 2;
}

// Helper: extracts operand name and optional modifier from ${name:mod} syntax
static std::pair<std::string, std::string>
extractVarAndModifier(const CodeGenInstruction &CGI,
                      const std::string &asmStr,
                      std::size_t startIdx,
                      std::size_t &endIdx) {
    std::string varName;
    std::string modifier;

    // Skip leading '{' if present
    bool hasBraces = false;
    if (startIdx < asmStr.size() && asmStr[startIdx] == '{') {
        hasBraces = true;
        ++startIdx;
    }

    // Extract variable name
    std::size_t nameEnd = startIdx;
    while (nameEnd < asmStr.size() && isValidIdentifierChar(asmStr[nameEnd])) {
        ++nameEnd;
    }
    varName = asmStr.substr(startIdx, nameEnd - startIdx);

    // Handle modifier if any
    if (hasBraces) {
        if (nameEnd >= asmStr.size())
            PrintFatalError(CGI.TheDef->getLoc(),
                            "Missing closing brace '}' after variable in '" +
                                CGI.TheDef->getName() + "'");
        if (asmStr[nameEnd] == ':') {
            ++nameEnd;
            if (nameEnd >= asmStr.size())
                PrintFatalError(CGI.TheDef->getLoc(),
                                "Unexpected end after ':' in modifier for '" +
                                    CGI.TheDef->getName() + "'");
            std::size_t modStart = nameEnd;
            while (nameEnd < asmStr.size() && isValidIdentifierChar(asmStr[nameEnd]))
                ++nameEnd;
            modifier = asmStr.substr(modStart, nameEnd - modStart);
            if (modifier.empty())
                PrintFatalError(CGI.TheDef->getLoc(),
                                "Empty modifier in '" + CGI.TheDef->getName() + "'");
        }
        if (nameEnd >= asmStr.size() || asmStr[nameEnd] != '}')
            PrintFatalError(CGI.TheDef->getLoc(),
                            "Unmatched '{' in '" + CGI.TheDef->getName() + "'");
        ++nameEnd;
    }

    endIdx = nameEnd;
    return {varName, modifier};
}

// Main constructor implementation — rewritten with clearer structure
AsmWriterInst::AsmWriterInst(const CodeGenInstruction &CGI, unsigned idx,
                             unsigned variant)
    : CGI(&CGI), CGIIndex(idx) {

    std::string asmStr = CGI.FlattenAsmStringVariants(CGI.AsmString, variant);
    std::size_t lastPos = 0;

    auto emitFragment = [&](std::size_t begin, std::size_t end) {
        for (std::size_t i = begin; i < end; ++i) {
            AsmWriterOperand::AddLiteralString(escapeForLiteral(asmStr[i]));
        }
    };

    while (lastPos < asmStr.size()) {
        std::size_t dollarIdx = asmStr.find_first_of("$\\", lastPos);
        if (dollarIdx == std::string::npos) {
            emitFragment(lastPos, asmStr.size());
            break;
        }

        // Emit plain text before $ or \
        if (dollarIdx > lastPos) {
            emitFragment(lastPos, dollarIdx);
            lastPos = dollarIdx;
        }

        if (asmStr[lastPos] == '\\') {
            handleEscapedChar(CGI, asmStr, lastPos, lastPos);
            continue;
        }

        // Handle "$$" -> "$"
        if (lastPos + 1 < asmStr.size() && asmStr[lastPos + 1] == '$') {
            AsmWriterOperand::AddLiteralString("$");
            lastPos += 2;
            continue;
        }

        // Parse variable reference: $name or ${name:mod}
        std::size_t nextPos = lastPos + 1;
        auto [varName, mod] = extractVarAndModifier(CGI, asmStr, nextPos, nextPos);

        if (varName.empty() && mod.empty()) {
            PrintFatalError(CGI.TheDef->getLoc(),
                            "Dangling '$' in '" + CGI.TheDef->getName() +
                                "', perhaps you meant '$$'?");
        }

        if (varName.empty()) {
            Operands.emplace_back("PrintSpecial", ~0U, mod);
        } else {
            unsigned opIdx = CGI.Operands.getOperandNamed(varName);
            const auto &opInfo = CGI.Operands[opIdx];
            Operands.emplace_back(opInfo.PrinterMethodName,
                                  opInfo.MIOperandNo,
                                  mod,
                                  AsmWriterOperand::isMachineInstrOperand,
                                  opInfo.OperandType == "MCOI::OPERAND_PCREL");
        }

        lastPos = nextPos;
    }

    Operands.emplace_back("return;", AsmWriterOperand::isLiteralStatementOperand);
}

// Clone of MatchesAllButOneOp with renamed variables and minor restructuring
unsigned AsmWriterInst::MatchesAllButOneOp(const AsmWriterInst &other) const {
    if (Operands.size() != other.Operands.size())
        return ~1U;

    unsigned diffIdx = ~0U;
    for (unsigned i = 0, n = Operands.size(); i < n; ++i) {
        if (!(Operands[i] == other.Operands[i])) {
            if (diffIdx != ~0U)
                return ~1U;
            diffIdx = i;
        }
    }
    return diffIdx;
}

#include "cangjie/CHIR/Transformation/UselessAllocateElimination.h"
#include "cangjie/CHIR/Analysis/Utils.h"
#include "cangjie/CHIR/CHIRCasting.h"
#include "cangjie/CHIR/Expression/Terminator.h"

using namespace Cangjie::CHIR;

void UselessAllocateElimination::RunOnPackage(const Package& package, bool verbose) {
    for (const auto& globalFunc : package.GetGlobalFuncs()) {
        ProcessFunction(*globalFunc, verbose);
    }
}

void UselessAllocateElimination::ProcessFunction(const Func& func, bool verbose) {
    const auto* body = func.GetBody();
    if (!body) return;

    for (auto* block : body->GetBlocks()) {
        // Traverse expressions in reverse to safely erase during iteration
        auto exprs = block->GetExpressions();
        for (auto it = exprs.rbegin(); it != exprs.rend(); ++it) {
            auto* expr = *it;
            if (expr->GetExprKind() != ExprKind::ALLOCATE) {
                continue;
            }

            auto* allocExpr = StaticCast<Allocate*>(expr);
            auto* allocatedType = allocExpr->GetType();

            // Skip if the allocated type is a class with a finalizer
            if (allocatedType->IsClass()) {
                auto* classDef = StaticCast<ClassType*>(allocatedType)->GetClassDef();
                if (classDef->GetFinalizer()) {
                    continue;
                }
            }

            auto* allocResult = allocExpr->GetResult();

            // Skip if allocation result is function's return value
            if (func.GetReturnValue() == allocResult) {
                continue;
            }

            // Check whether all users only write to the result (or are debug expressions)
            bool hasNonWriteUser = false;
            for (auto* user : allocResult->GetUsers()) {
                if (user->GetExprKind() == ExprKind::DEBUGEXPR) {
                    continue;
                }
                if (user->GetExprKind() == ExprKind::STORE) {
                    auto* storeExpr = StaticCast<Store*>(user);
                    if (storeExpr->GetLocation() != allocResult) {
                        hasNonWriteUser = true;
                        break;
                    }
                } else if (user->GetExprKind() == ExprKind::STORE_ELEMENT_REF) {
                    auto* storeRefExpr = StaticCast<StoreElementRef*>(user);
                    if (storeRefExpr->GetLocation() != allocResult) {
                        hasNonWriteUser = true;
                        break;
                    }
                } else {
                    hasNonWriteUser = true;
                    break;
                }
            }

            if (!hasNonWriteUser) {
                // Erase the allocation and its users
                allocExpr->RemoveSelfFromBlock();
                for (auto* user : allocResult->GetUsers()) {
                    user->RemoveSelfFromBlock();
                }

                if (verbose && !allocExpr->GetDebugLocation().GetBeginPos().IsZero()) {
                    std::string msg = "[UselessAllocateElimination] Allocation at ";
                    msg += ToPosInfo(allocExpr->GetDebugLocation());
                    msg += " and associated users removed\n";
                    std::cout << msg;
                }
            }
        }
    }
}

