#include "line_field_missmatch.h"
#include <igl/comb_line_field.h>
#include <igl/rotate_vectors.h>
#include <igl/comb_cross_field.h>
#include <igl/per_face_normals.h>
#include <igl/is_border_vertex.h>
#include <igl/vertex_triangle_adjacency.h>
#include <igl/triangle_triangle_adjacency.h>
#include <igl/rotation_matrix_from_directions.h>
#include <igl/local_basis.h>
#include <igl/PI.h>

namespace igl {

template <typename DerivedV, typename DerivedF, typename DerivedO>
class LineFieldMismatchEstimator {
public:
    const Eigen::PlainObjectBase<DerivedV>& vertexPositions;
    const Eigen::PlainObjectBase<DerivedF>& faceIndices;
    const Eigen::PlainObjectBase<DerivedV>& primaryDirection;
    const Eigen::PlainObjectBase<DerivedV>& secondaryDirection;

    DerivedV faceNormals;

private:
    std::vector<bool> isVertexOnBoundary;
    std::vector<std::vector<int>> vertexToFaces;
    std::vector<std::vector<int>> vertexToFaceIndex;
    DerivedF triangleAdjacency;
    DerivedF triangleAdjacencyInverse;

public:
    LineFieldMismatchEstimator(
        const Eigen::PlainObjectBase<DerivedV>& V,
        const Eigen::PlainObjectBase<DerivedF>& F,
        const Eigen::PlainObjectBase<DerivedV>& PD1,
        const Eigen::PlainObjectBase<DerivedV>& PD2)
        : vertexPositions(V),
          faceIndices(F),
          primaryDirection(PD1),
          secondaryDirection(PD2)
    {
        // Compute per-face normals
        igl::per_face_normals(vertexPositions, faceIndices, faceNormals);

        // Determine boundary vertices
        isVertexOnBoundary = igl::is_border_vertex(vertexPositions, faceIndices);

        // Build vertex–face adjacency
        igl::vertex_triangle_adjacency(vertexPositions, faceIndices, vertexToFaces, vertexToFaceIndex);

        // Compute triangle–triangle adjacency
        igl::triangle_triangle_adjacency(faceIndices, triangleAdjacency, triangleAdjacencyInverse);
    }

    // Estimate mismatch between two adjacent faces along shared edge
    inline int estimateMismatch(const int faceA, const int faceB) const {
        // Directions in world space
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> vecA = primaryDirection.row(faceA);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> vecB = primaryDirection.row(faceB);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> normA = faceNormals.row(faceA);
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> normB = faceNormals.row(faceB);

        // Rotate vecB into faceA's local frame
        Eigen::Matrix<typename DerivedV::Scalar, 3, 1> rotatedVecB =
            igl::rotation_matrix_from_directions(normB, normA) * vecB;
        rotatedVecB.normalize();

        // Project onto local basis of faceA: use PD1 and PD2 as orthonormal basis vectors
        const auto& basisX = primaryDirection.row(faceA);
        const auto& basisY = secondaryDirection.row(faceA);

        double projX = rotatedVecB.dot(basisX);
        double projY = rotatedVecB.dot(basisY);

        // Compute angle difference using atan2
        double angleDiff = std::atan2(projY, projX);

        // Normalize angle to [-π, π]
        constexpr double PI_val = igl::PI;
        while (angleDiff <= -PI_val) angleDiff += 2 * PI_val;
        while (angleDiff > PI_val) angleDiff -= 2 * PI_val;

        // Determine how many half-turns (π) fit into the angle difference
        double stepSize = PI_val;
        int halfTurns = static_cast<int>(std::round(angleDiff / stepSize));

        // Clamp to valid range [-2, 2]
        if (halfTurns < -2) halfTurns = -2;
        if (halfTurns >  2) halfTurns =  2;

        // Map to mismatch value: even numbers only (0 or 2)
        int mismatch = 0;
        if (halfTurns % 2 != 0) {
            mismatch = 2;
        }
        return mismatch;
    }

    // Fill output matrix with mismatches per face-edge
    inline void computeMismatch(Eigen::PlainObjectBase<DerivedO>& result) const {
        result.setConstant(faceIndices.rows(), 3, -1);

        for (std::size_t i = 0; i < static_cast<std::size_t>(faceIndices.rows()); ++i) {
            for (int edge = 0; edge < 3; ++edge) {
                int neighbor = triangleAdjacency(i, edge);
                if (neighbor == -1 || neighbor == static_cast<int>(i)) {
                    result(i, edge) = 0;
                } else {
                    result(i, edge) = estimateMismatch(static_cast<int>(i), neighbor);
                }
            }
        }
    }
};

} // namespace igl

template <typename DerivedV, typename DerivedF, typename DerivedO>
IGL_INLINE void igl::line_field_missmatch(
    const Eigen::PlainObjectBase<DerivedV>& V,
    const Eigen::PlainObjectBase<DerivedF>& F,
    const Eigen::PlainObjectBase<DerivedV>& PD1,
    const bool alreadyCombed,
    Eigen::PlainObjectBase<DerivedO>& mismatchOutput)
{
    DerivedV combedPD1;
    DerivedV combedPD2;

    if (!alreadyCombed) {
        igl::comb_line_field(V, F, PD1, combedPD1);
    } else {
        combedPD1 = PD1;
    }

    // Get local orthonormal basis per face
    Eigen::MatrixXd Bx, By, Bz;
    igl::local_basis(V, F, Bx, By, Bz);

    // Generate orthogonal direction by rotating PD1 by +90 degrees in tangent plane
    combedPD2 = igl::rotate_vectors(combedPD1, Eigen::VectorXd::Constant(1, igl::PI / 2), Bx, By);

    // Instantiate estimator and compute mismatches
    igl::LineFieldMismatchEstimator<DerivedV, DerivedF, DerivedO> estimator(V, F, combedPD1, combedPD2);
    estimator.computeMismatch(mismatchOutput);
}

