// Replaced array of magic constants — same structure, renamed identifiers
static const uint32 zero_code_pattern1[] = { ZERO_CODE1 };
static const uint32 zero_code_pattern2[] = { ZERO_CODE2 };
static const uint32* const all_zero_patterns[] = { zero_code_pattern1, zero_code_pattern2 };

//--------------------------------------------------------------------------
// Inverts byte order of header fields in-place using pointer traversal
static void endian_swap_header(aif_header_t *header)
{
    uint32 *field_ptr = reinterpret_cast<uint32*>(header);
    const int field_count = sizeof(aif_header_t) / sizeof(uint32);
    for (int idx = 0; idx < field_count; ++idx, ++field_ptr)
        *field_ptr = swap32(*field_ptr);
}
//--------------------------------------------------------------------------
// Returns: 0 = no match, 1 = matched as-is, 2 = matched after swapping
static int check_zero_code_match(aif_header_t *header)
{
    bool swapped_once = false;
    for (int pattern_idx = 0; pattern_idx < static_cast<int>(sizeof(all_zero_patterns)/sizeof(all_zero_patterns[0])); ++pattern_idx)
    {
        const uint32* expected = all_zero_patterns[pattern_idx];
        if (std::memcmp(header->zero_code, expected, sizeof(header->zero_code)) == 0)
            return swapped_once ? 2 : 1;

        endian_swap_header(header);
        swapped_once = !swapped_once;

        if (std::memcmp(header->zero_code, expected, sizeof(header->zero_code)) == 0)
            return swapped_once ? 2 : 1;
    }
    return 0;
}
//--------------------------------------------------------------------------
// Determine whether input stream points to a valid AIF file
bool is_aif_file(linput_t *stream)
{
    aif_header_t header;
    qlseek(stream, 0);
    if (qlread(stream, &header, sizeof(header)) != sizeof(header))
        return false;
    return check_zero_code_match(&header) != 0;
}
//--------------------------------------------------------------------------
// Swap endianness of section fields individually
static void endian_swap_section(section_t *section)
{
    section->codestart = swap32(section->codestart);
    section->datastart = swap32(section->datastart);
    section->codesize  = swap32(section->codesize);
    section->datasize  = swap32(section->datasize);
    section->fileinfo  = swap32(section->fileinfo);
    section->debugsize = swap32(section->debugsize);
    section->name      = swap32(section->name);
}
//--------------------------------------------------------------------------
// Swap endianness of debug symbol entry
static void endian_swap_dsym(dsym_t *dsym)
{
    dsym->sym   = swap32(dsym->sym);
    dsym->value = swap32(dsym->value);
}
//--------------------------------------------------------------------------
// Analyze debug symbols to infer calling convention (Pascal vs C)
// Returns true if Pascal-style symbols dominate
static bool detect_pascal_symbols(dsym_t *dsym_array, char *string_pool, uchar *end_of_strings, size_t total_syms)
{
    int pascal_count = 0;
    int c_count = 0;

    for (size_t i = 0; i < total_syms; ++i, ++dsym_array)
    {
        if (is_mf())
            endian_swap_dsym(dsym_array);

        if (dsym_array->sym & ASD_16BITSYM)
            continue;

        size_t name_offset = dsym_array->sym & ASD_SYMOFF;
        char *symbol_name = string_pool + name_offset;

        if (symbol_name >= reinterpret_cast<char*>(end_of_strings))
            continue;

        // Check for Pascal-style length-prefixed string: first byte == strlen(name+1)
        if (symbol_name[0] == static_cast<char>(std::strlen(symbol_name + 1)))
            ++pascal_count;
        else
            ++c_count;
    }

    return pascal_count > c_count;
}

