TextEdit::TextEdit(Widget* parent) : Widget(parent)
{
	SetStyleClass("textedit");
	selectionBG = GetStyleColor("selection-color");
	selectionFG = GetStyleColor("selection-text");

	timer = new Timer(this);
	timer->FuncExpired = [this]() { OnTimerExpired(); };

	scroll_timer = new Timer(this);
	scroll_timer->FuncExpired = [this]() { OnScrollTimerExpired(); };

	SetCursor(StandardCursor::ibeam);
	CreateComponents();
}

TextEdit::~TextEdit()
{
}

bool TextEdit::IsReadOnly() const
{
	return readonly;
}

bool TextEdit::IsLowercase() const
{
	return lowercase;
}

bool TextEdit::IsUppercase() const
{
	return uppercase;
}

int TextEdit::GetMaxLength() const
{
	return max_length;
}

std::string TextEdit::GetLineText(int line) const
{
	if (line >= 0 && line < static_cast<int>(lines.size()))
		return lines[line].text;
	else
		return std::string{};
}

std::string TextEdit::GetText() const
{
	size_t total_chars = 0;
	for (const auto& l : lines)
		total_chars += l.text.length();
	total_chars += lines.size() > 0 ? lines.size() - 1 : 0;

	std::string result;
	result.reserve(total_chars);

	for (size_t idx = 0; idx < lines.size(); ++idx)
	{
		if (idx > 0)
			result.push_back('\n');
		result += lines[idx].text;
	}
	return result;
}

int TextEdit::GetLineCount() const
{
	return static_cast<int>(lines.size());
}

std::string TextEdit::GetSelection() const
{
	size_t base_offset = ToOffset(selection_start);
	int start_idx = static_cast<int>(std::min(base_offset, base_offset + selection_length));
	return GetText().substr(start_idx, std::abs(selection_length));
}

int TextEdit::GetSelectionStart() const
{
	return static_cast<int>(ToOffset(selection_start));
}

int TextEdit::GetSelectionLength() const
{
	return selection_length;
}

int TextEdit::GetCursorPos() const
{
	return static_cast<int>(ToOffset(cursor_pos));
}

int TextEdit::GetCursorLineNumber() const
{
	return cursor_pos.y;
}

void TextEdit::SelectAll()
{
	size_t total_len = 0;
	for (const auto& l : lines)
		total_len += l.text.length();
	total_len += lines.size() > 1 ? lines.size() - 1 : 0;
	SetSelection(0, static_cast<int>(total_len));
}

void TextEdit::SetReadOnly(bool enable)
{
	if (readonly != enable)
	{
		readonly = enable;
		Update();
	}
}

void TextEdit::SetLowercase(bool enable)
{
	if (lowercase != enable)
	{
		lowercase = enable;
		Update();
	}
}

void TextEdit::SetUppercase(bool enable)
{
	if (uppercase != enable)
	{
		uppercase = enable;
		Update();
	}
}

void TextEdit::SetMaxLength(int length)
{
	if (max_length != length)
	{
		max_length = length;
		size_t current_len = 0;
		for (const auto& l : lines)
			current_len += l.text.length();
		current_len += lines.size() > 1 ? lines.size() - 1 : 0;

		if (static_cast<int>(current_len) > length)
		{
			if (FuncBeforeEditChanged)
				FuncBeforeEditChanged();

			SetSelection(length, static_cast<int>(current_len) - length);
			DeleteSelectedText();

			if (FuncAfterEditChanged)
				FuncAfterEditChanged();
		}
		Update();
	}
}

void TextEdit::SetText(const std::string& text)
{
	lines.clear();
	size_t begin = 0;
	size_t pos = text.find('\n');

	while (pos != std::string::npos)
	{
		TextEdit::Line new_line{ this };
		new_line.text = text.substr(begin, pos - begin);
		lines.push_back(new_line);
		begin = pos + 1;
		pos = text.find('\n', begin);
	}

	TextEdit::Line final_line{ this };
	final_line.text = text.substr(begin);
	lines.push_back(final_line);

	clip_start_offset = 0;
	SetCursorPos(0);
	ClearSelection();
	Update();
}

void TextEdit::AddText(const std::string& text)
{
	size_t begin = 0;
	size_t pos = text.find('\n');

	while (pos != std::string::npos)
	{
		TextEdit::Line new_line{ this };
		new_line.text = text.substr(begin, pos - begin);
		lines.push_back(new_line);
		begin = pos + 1;
		pos = text.find('\n', begin);
	}

	TextEdit::Line final_line{ this };
	final_line.text = text.substr(begin);
	lines.push_back(final_line);

	ClearSelection();
	Update();
}

void TextEdit::SetSelection(int pos, int len)
{
	selection_start = ivec2(pos, 0);
	selection_length = len;
	Update();
}

void TextEdit::ClearSelection()
{
	SetSelection(0, 0);
	Update();
}

void TextEdit::DeleteSelectedText()
{
	if (GetSelectionLength() == 0)
		return;

	size_t base_offset = ToOffset(selection_start);
	int start_idx = static_cast<int>(std::min(base_offset, base_offset + selection_length));
	int len = std::abs(selection_length);

	ClearSelection();
	std::string full_text = GetText();
	SetText(full_text.substr(0, start_idx) + full_text.substr(start_idx + len));
	SetCursorPos(start_idx);
}

void TextEdit::SetCursorPos(int pos)
{
	cursor_pos = FromOffset(pos);
	Update();
}

void TextEdit::SetInputMask(const std::string& mask)
{
	input_mask = mask;
}

void TextEdit::SetCursorDrawingEnabled(bool enable)
{
	if (!readonly)
		timer->Start(500);
}

void TextEdit::SetSelectAllOnFocusGain(bool enable)
{
	select_all_on_focus_gain = enable;
}

void TextEdit::OnMouseMove(const Point& pos)
{
	if (mouse_selecting && !ignore_mouse_events)
	{
		if (pos.x < 0.0 || pos.x > GetWidth())
		{
			mouse_moves_left = (pos.x < 0.0);
			if (!readonly)
				scroll_timer->Start(50, true);
		}
		else
		{
			scroll_timer->Stop();
			cursor_pos = GetCharacterIndex(pos);
			selection_length = static_cast<int>(ToOffset(cursor_pos)) - static_cast<int>(ToOffset(selection_start));
			Update();
		}
	}
}

bool TextEdit::OnMouseDown(const Point& pos, InputKey key)
{
	if (key == InputKey::LeftMouse)
	{
		SetPointerCapture();
		mouse_selecting = true;
		cursor_pos = GetCharacterIndex(pos);
		selection_start = cursor_pos;
		selection_length = 0;
		Update();
	}
	return true;
}

bool TextEdit::OnMouseDoubleclick(const Point& pos, InputKey key)
{
	return true;
}

bool TextEdit::OnMouseUp(const Point& pos, InputKey key)
{
	if (mouse_selecting && key == InputKey::LeftMouse)
	{
		if (ignore_mouse_events)
		{
			ReleasePointerCapture();
			ignore_mouse_events = false;
			mouse_selecting = false;
		}
		else
		{
			scroll_timer->Stop();
			ReleasePointerCapture();
			mouse_selecting = false;
			ivec2 end_sel = GetCharacterIndex(pos);
			selection_length = static_cast<int>(ToOffset(end_sel)) - static_cast<int>(ToOffset(selection_start));
			cursor_pos = end_sel;
			SetFocus();
			Update();
		}
	}
	return true;
}

void TextEdit::OnKeyChar(std::string chars)
{
	if (!readonly && !chars.empty() && !(chars[0] >= 0 && chars[0] < 32))
	{
		if (FuncBeforeEditChanged)
			FuncBeforeEditChanged();

		DeleteSelectedText();
		ClearSelection();

		if (input_mask.empty())
		{
			InsertText(cursor_pos, chars);
			cursor_pos.x += static_cast<int>(chars.size());
		}
		else
		{
			if (InputMaskAcceptsInput(cursor_pos, chars))
			{
				InsertText(cursor_pos, chars);
				cursor_pos.x += static_cast<int>(chars.size());
			}
		}

		if (FuncAfterEditChanged)
			FuncAfterEditChanged();
	}
}

void TextEdit::OnKeyDown(InputKey key)
{
	if (!readonly && key == InputKey::Enter)
	{
		if (FuncEnterPressed)
		{
			FuncEnterPressed();
		}
		else
		{
			ClearSelection();
			InsertText(cursor_pos, "\n");
			SetCursorPos(GetCursorPos() + 1);
		}
		return;
	}

	if (!readonly)
	{
		cursor_blink_visible = true;
		timer->Start(500);
	}

	if (key == InputKey::Enter || key == InputKey::Escape || key == InputKey::Tab)
	{
		return;
	}
	else if (key == InputKey::A && GetKeyState(InputKey::Ctrl))
	{
		SelectAll();
	}
	else if (key == InputKey::C && GetKeyState(InputKey::Ctrl))
	{
		std::string sel = GetSelection();
		SetClipboardText(sel);
	}
	else if (readonly)
	{
		return;
	}
	else if (key == InputKey::Up)
	{
		if (GetKeyState(InputKey::Shift) && selection_length == 0)
			selection_start = cursor_pos;

		if (cursor_pos.y > 0)
		{
			cursor_pos.y--;
			cursor_pos.x = std::min(lines[cursor_pos.y].text.size(), static_cast<size_t>(cursor_pos.x));
		}

		if (GetKeyState(InputKey::Shift))
		{
			selection_length = static_cast<int>(ToOffset(cursor_pos)) - static_cast<int>(ToOffset(selection_start));
		}
		else
		{
			selection_start = ivec2(0, 0);
			selection_length = 0;
		}

		MoveVerticalScroll();
		Update();
		undo_info.first_text_insert = true;
	}
	else if (key == InputKey::Down)
	{
		if (GetKeyState(InputKey::Shift) && selection_length == 0)
			selection_start = cursor_pos;

		if (cursor_pos.y < static_cast<int>(lines.size()) - 1)
		{
			cursor_pos.y++;
			cursor_pos.x = std::min(lines[cursor_pos.y].text.size(), static_cast<size_t>(cursor_pos.x));
		}

		if (GetKeyState(InputKey::Shift))
		{
			selection_length = static_cast<int>(ToOffset(cursor_pos)) - static_cast<int>(ToOffset(selection_start));
		}
		else
		{
			selection_start = ivec2(0, 0);
			selection_length = 0;
		}

		MoveVerticalScroll();
		Update();
		undo_info.first_text_insert = true;
	}
	else if (key == InputKey::Left)
	{
		Move(-1, GetKeyState(InputKey::Shift), GetKeyState(InputKey::Ctrl));
	}
	else if (key == InputKey::Right)
	{
		Move(1, GetKeyState(InputKey::Shift), GetKeyState(InputKey::Ctrl));
	}
	else if (key == InputKey::Backspace)
	{
		Backspace();
	}
	else if (key == InputKey::Delete)
	{
		Del();
	}
	else if (key == InputKey::Home)
	{
		if (GetKeyState(InputKey::Ctrl))
			cursor_pos = ivec2(0, 0);
		else
			cursor_pos.x = 0;

		if (GetKeyState(InputKey::Shift))
			selection_length = static_cast<int>(ToOffset(cursor_pos)) - static_cast<int>(ToOffset(selection_start));
		else
			ClearSelection();

		Update();
		MoveVerticalScroll();
	}
	else if (key == InputKey::End)
	{
		if (GetKeyState(InputKey::Ctrl))
			cursor_pos = ivec2(lines.back().text.length(), static_cast<int>(lines.size()) - 1);
		else
			cursor_pos.x = lines[cursor_pos.y].text.size();

		if (GetKeyState(InputKey::Shift))
			selection_length = static_cast<int>(ToOffset(cursor_pos)) - static_cast<int>(ToOffset(selection_start));
		else
			ClearSelection();

		Update();
	}
	else if (key == InputKey::X && GetKeyState(InputKey::Ctrl))
	{
		std::string sel = GetSelection();
		DeleteSelectedText();
		SetClipboardText(sel);
	}
	else if (key == InputKey::V && GetKeyState(InputKey::Ctrl))
	{
		std::string clipboard = GetClipboardText();
		auto new_end = std::remove(clipboard.begin(), clipboard.end(), '\r');
		clipboard.resize(new_end - clipboard.begin());

		DeleteSelectedText();

		if (input_mask.empty())
		{
			InsertText(cursor_pos, clipboard);
			SetCursorPos(GetCursorPos() + static_cast<int>(clipboard.length()));
		}
		else
		{
			if (InputMaskAcceptsInput(cursor_pos, clipboard))
			{
				InsertText(cursor_pos, clipboard);
				SetCursorPos(GetCursorPos() + static_cast<int>(clipboard.length()));
			}
		}
		MoveVerticalScroll();
	}
	else if (GetKeyState(InputKey::Ctrl) && key == InputKey::Z)
	{
		if (!readonly)
		{
			std::string tmp = undo_info.undo_text;
			undo_info.undo_text = GetText();
			SetText(tmp);
		}
	}
	else if (key == InputKey::Shift)
	{
		if (selection_length == 0)
			selection_start = cursor_pos;
	}

	if (FuncAfterEditChanged)
		FuncAfterEditChanged();
}

void TextEdit::OnKeyUp(InputKey key)
{
}

void TextEdit::OnSetFocus()
{
	if (!readonly)
		timer->Start(500);

	if (select_all_on_focus_gain)
		SelectAll();

	ignore_mouse_events = true;
	cursor_pos.y = static_cast<int>(lines.size()) - 1;
	cursor_pos.x = lines[cursor_pos.y].text.length();
	Update();

	if (FuncFocusGained)
		FuncFocusGained();
}

void TextEdit::OnLostFocus()
{
	timer->Stop();
	ClearSelection();
	Update();

	if (FuncFocusLost)
		FuncFocusLost();
}

void TextEdit::CreateComponents()
{
	vert_scrollbar = new Scrollbar(this);
	vert_scrollbar->FuncScroll = [this]() { OnVerticalScroll(); };
	vert_scrollbar->SetVisible(false);
	vert_scrollbar->SetVertical();
}

void TextEdit::OnVerticalScroll()
{
}

void TextEdit::UpdateVerticalScroll()
{
	Rect rect(
		GetWidth() - vert_scrollbar->GetPreferredWidth(),
		0.0,
		vert_scrollbar->GetPreferredWidth(),
		GetHeight()
	);
	vert_scrollbar->SetFrameGeometry(rect);

	double total_height = GetTotalLineHeight();
	double line_height = std::max(1.0, total_height / std::max(1.0, static_cast<double>(lines.size())));
	bool visible = total_height > GetHeight();

	vert_scrollbar->SetRanges(
		static_cast<int>(std::round(GetHeight() / line_height)),
		static_cast<int>(std::round(total_height / line_height))
	);
	vert_scrollbar->SetLineStep(1);
	vert_scrollbar->SetVisible(visible);

	if (!visible)
		vert_scrollbar->SetPosition(0);
}

void TextEdit::MoveVerticalScroll()
{
	double total_height = GetTotalLineHeight();
	double line_height = std::max(1.0, total_height / std::max(static_cast<size_t>(1), lines.size()));
	int lines_fit = static_cast<int>(GetHeight() / line_height);

	if (cursor_pos.y >= static_cast<int>(vert_scrollbar->GetPosition()) + lines_fit)
	{
		vert_scrollbar->SetPosition(cursor_pos.y - lines_fit + 1);
	}
	else if (cursor_pos.y < static_cast<int>(vert_scrollbar->GetPosition()))
	{
		vert_scrollbar->SetPosition(cursor_pos.y);
	}
}

double TextEdit::GetTotalLineHeight()
{
	double sum = 0.0;
	for (const auto& line : lines)
		sum += line.layout.GetSize().height;
	return sum;
}

void TextEdit::Move(int steps, bool shift, bool ctrl)
{
	if (shift && selection_length == 0)
		selection_start = cursor_pos;

	if (ctrl)
	{
		if (steps < 0 && cursor_pos.x == 0 && cursor_pos.y > 0)
		{
			cursor_pos.x = static_cast<int>(lines[cursor_pos.y - 1].text.size());
			cursor_pos.y--;
		}
		else if (steps > 0 && cursor_pos.x == static_cast<int>(lines[cursor_pos.y].text.size()) && cursor_pos.y + 1 < static_cast<int>(lines.size()))
		{
			cursor_pos.x = 0;
			cursor_pos.y++;
		}

		ivec2 new_pos;
		if (steps < 0)
			new_pos = FindPreviousBreakCharacter(cursor_pos);
		else
			new_pos = FindNextBreakCharacter(cursor_pos);

		cursor_pos = new_pos;
	}
	else if (steps < 0 && cursor_pos.x == 0 && cursor_pos.y > 0)
	{
		cursor_pos.x = static_cast<int>(lines[cursor_pos.y - 1].text.size());
		cursor_pos.y--;
	}
	else if (steps > 0 && cursor_pos.x == static_cast<int>(lines[cursor_pos.y].text.size()) && cursor_pos.y + 1 < static_cast<int>(lines.size()))
	{
		cursor_pos.x = 0;
		cursor_pos.y++;
	}
	else
	{
		UTF8Reader utf_reader(lines[cursor_pos.y].text.data(), lines[cursor_pos.y].text.length());
		utf_reader.set_position(cursor_pos.x);

		if (steps > 0)
		{
			for (int i = 0; i < steps; ++i)
				utf_reader.next();
		}
		else if (steps < 0)
		{
			for (int i = 0; i < -steps; ++i)
				utf_reader.prev();
		}

		cursor_pos.x = static_cast<int>(utf_reader.position());
	}

	if (shift)
	{
		selection_length = static_cast<int>(ToOffset(cursor_pos)) - static_cast<int>(ToOffset(selection_start));
	}
	else
	{
		selection_start = ivec2(0, 0);
		selection_length = 0;
	}

	MoveVerticalScroll();
	Update();
	undo_info.first_text_insert = true;
}

std::string TextEdit::break_characters = " ::;,.-";

TextEdit::ivec2 TextEdit::FindNextBreakCharacter(ivec2 search_start)
{
	search_start.x++;
	if (search_start.x >= static_cast<int>(lines[search_start.y].text.size()) - 1)
		return ivec2(lines[search_start.y].text.size(), search_start.y);

	size_t found_pos = lines[search_start.y].text.find_first_of(break_characters, static_cast<size_t>(search_start.x));
	if (found_pos == std::string::npos)
		return ivec2(lines[search_start.y].text.size(), search_start.y);

	return ivec2(static_cast<int>(found_pos), search_start.y);
}

TextEdit::ivec2 TextEdit::FindPreviousBreakCharacter(ivec2 search_start)
{
	search_start.x--;
	if (search_start.x <= 0)
		return ivec2(0, search_start.y);

	size_t found_pos = lines[search_start.y].text.find_last_of(break_characters, static_cast<size_t>(search_start.x));
	if (found_pos == std::string::npos)
		return ivec2(0, search_start.y);

	return ivec2(static_cast<int>(found_pos), search_start.y);
}

void TextEdit::InsertText(ivec2 pos, const std::string& str)
{
	undo_info.first_erase = false;
	if (undo_info.first_text_insert)
	{
		undo_info.undo_text = GetText();
		undo_info.first_text_insert = false;
	}

	if (ToOffset(ivec2(static_cast<int>(lines.back().text.size()), static_cast<int>(lines.size()) - 1)) + str.length() > static_cast<size_t>(max_length))
		return;

	size_t start_idx = 0;
	while (true)
	{
		size_t next_newline = str.find('\n', start_idx);
		lines[pos.y].text.insert(pos.x, str.substr(start_idx, next_newline - start_idx));
		lines[pos.y].invalidated = true;

		if (next_newline == std::string::npos)
			break;

		pos.x += static_cast<int>(next_newline - start_idx);
		Line new_line{ this };
		new_line.text = lines[pos.y].text.substr(pos.x);
		lines.insert(lines.begin() + pos.y + 1, new_line);
		lines[pos.y].text = lines[pos.y].text.substr(0, pos.x);
		lines[pos.y].invalidated = true;

		pos = ivec2(0, pos.y + 1);
		start_idx = next_newline + 1;
	}

	MoveVerticalScroll();
	Update();
}

void TextEdit::Backspace()
{
	if (undo_info.first_erase)
	{
		undo_info.first_erase = false;
		undo_info.undo_text = GetText();
	}

	if (GetSelectionLength() != 0)
	{
		DeleteSelectedText();
		ClearSelection();
		Update();
	}
	else
	{
		if (cursor_pos.x > 0)
		{
			UTF8Reader utf_reader(lines[cursor_pos.y].text.data(), lines[cursor_pos.y].text.length());
			utf_reader.set_position(cursor_pos.x);
			utf_reader.prev();
			int char_len = utf_reader.char_length();
			lines[cursor_pos.y].text.erase(cursor_pos.x - char_len, char_len);
			lines[cursor_pos.y].invalidated = true;
			cursor_pos.x -= char_len;
			Update();
		}
		else if (cursor_pos.y > 0)
		{
			selection_start = ivec2(lines[cursor_pos.y - 1].text.length(), cursor_pos.y - 1);
			selection_length = 1;
			DeleteSelectedText();
		}
	}

	MoveVerticalScroll();
}

void TextEdit::Del()
{
	if (undo_info.first_erase)
	{
		undo_info.first_erase = false;
		undo_info.undo_text = GetText();
	}

	if (GetSelectionLength() != 0)
	{
		DeleteSelectedText();
		ClearSelection();
		Update();
	}
	else
	{
		if (cursor_pos.x < static_cast<int>(lines[cursor_pos.y].text.size()))
		{
			UTF8Reader utf_reader(lines[cursor_pos.y].text.data(), lines[cursor_pos.y].text.length());
			utf_reader.set_position(cursor_pos.x);
			int char_len = utf_reader.char_length();
			lines[cursor_pos.y].text.erase(cursor_pos.x, char_len);
			lines[cursor_pos.y].invalidated = true;
			Update();
		}
		else if (cursor_pos.y + 1 < static_cast<int>(lines.size()))
		{
			selection_start = ivec2(static_cast<int>(lines[cursor_pos.y].text.length()), cursor_pos.y);
			selection_length = 1;
			DeleteSelectedText();
		}
	}

	MoveVerticalScroll();
}

void TextEdit::OnTimerExpired()
{
	if (!IsVisible())
	{
		timer->Stop();
		return;
	}

	cursor_blink_visible = !cursor_blink_visible;
	timer->Start(500);
	Update();
}

void TextEdit::OnGeometryChanged()
{
	Canvas* canvas = GetCanvas();
	for (auto& line : lines)
		line.invalidated = true;

	vertical_text_align = canvas->verticalTextAlign();
	clip_start_offset = 0;
	UpdateVerticalScroll();
}

void TextEdit::OnScrollTimerExpired()
{
	if (mouse_moves_left)
		Move(-1, false, false);
	else
		Move(1, false, false);
}

void TextEdit::OnEnableChanged()
{
	bool enabled = IsEnabled();
	if (!enabled)
	{
		cursor_blink_visible = false;
		timer->Stop();
	}
	Update();
}

bool TextEdit::InputMaskAcceptsInput(ivec2 cursor_pos, const std::string& str)
{
	return str.find_first_not_of(input_mask) == std::string::npos;
}

size_t TextEdit::ToOffset(ivec2 pos) const
{
	if (pos.y < static_cast<int>(lines.size()))
	{
		size_t offset = 0;
		for (int line = 0; line < pos.y; ++line)
		{
			offset += lines[line].text.size() + 1;
		}
		return offset + std::min(lines[pos.y].text.size(), static_cast<size_t>(pos.x));
	}
	else
	{
		size_t offset = 0;
		for (size_t line = 0; line < lines.size(); ++line)
		{
			offset += lines[line].text.size() + 1;
		}
		return offset > 0 ? offset - 1 : 0;
	}
}

TextEdit::ivec2 TextEdit::FromOffset(size_t offset) const
{
	int line_offset = 0;
	for (int line = 0; line < static_cast<int>(lines.size()); ++line)
	{
		if (offset <= static_cast<size_t>(line_offset + lines[line].text.size()))
		{
			return ivec2(static_cast<int>(offset - line_offset), line);
		}
		line_offset += static_cast<int>(lines[line].text.size() + 1);
	}
	return ivec2(lines.back().text.size(), static_cast<int>(lines.size()) - 1);
}

double TextEdit::GetTotalHeight()
{
	Canvas* canvas = GetCanvas();
	LayoutLines(canvas);
	if (!lines.empty())
	{
		return lines.back().box.bottom();
	}
	else
	{
		return GetHeight();
	}
}

void TextEdit::LayoutLines(Canvas* canvas)
{
	ivec2 sel_start;
	ivec2 sel_end;

	if (selection_length > 0)
	{
		sel_start = selection_start;
		sel_end = FromOffset(ToOffset(selection_start) + selection_length);
	}
	else if (selection_length < 0)
	{
		sel_start = FromOffset(ToOffset(selection_start) + selection_length);
		sel_end = selection_start;
	}

	Colorf textColor = GetStyleColor("color");
	Point draw_pos;

	for (size_t i = static_cast<size_t>(vert_scrollbar->GetPosition()); i < lines.size(); ++i)
	{
		Line& line = lines[i];
		if (line.invalidated)
		{
			line.layout.Clear();
			if (!line.text.empty())
				line.layout.AddText(line.text, font, textColor);
			else
				line.layout.AddText(" ", font, textColor);

			line.layout.Layout(canvas, GetWidth() - vert_scrollbar->GetPreferredWidth());
			line.box = Rect(draw_pos, line.layout.GetSize());
			line.invalidated = false;
		}

		if (sel_start != sel_end && sel_start.y <= static_cast<int>(i) && sel_end.y >= static_cast<int>(i))
		{
			line.layout.SetSelectionRange(
				sel_start.y < static_cast<int>(i) ? 0 : sel_start.x,
				sel_end.y > static_cast<int>(i) ? line.text.size() : sel_end.x
			);
		}
		else
		{
			line.layout.SetSelectionRange(0, 0);
		}

		line.layout.HideCursor();

		if (HasFocus())
		{
			if (cursor_blink_visible && cursor_pos.y == static_cast<int>(i))
			{
				line.layout.SetCursorPos(cursor_pos.x);
				line.layout.SetCursorColor(textColor);
				line.layout.ShowCursor();
			}
		}

		line.box.x = draw_pos.x;
		line.box.y = draw_pos.y;
		line.layout.SetPosition(line.box.topLeft());
		draw_pos = line.box.bottomLeft();
	}

	UpdateVerticalScroll();
}

void TextEdit::OnPaint(Canvas* canvas)
{
	LayoutLines(canvas);
	for (size_t i = static_cast<size_t>(vert_scrollbar->GetPosition()); i < lines.size(); ++i)
		lines[i].layout.DrawLayout(canvas);
}

TextEdit::ivec2 TextEdit::GetCharacterIndex(Point mouse_wincoords)
{
	Canvas* canvas = GetCanvas();
	for (size_t i = 0; i < lines.size(); ++i)
	{
		Line& line = lines[i];
		if (line.box.top() <= mouse_wincoords.y && line.box.bottom() > mouse_wincoords.y)
		{
			SpanLayout::HitTestResult result = line.layout.HitTest(canvas, mouse_wincoords);
			switch (result.type)
			{
			case SpanLayout::HitTestResult::inside:
				return ivec2(clamp(result.offset, static_cast<size_t>(0), line.text.size()), i);
			case SpanLayout::HitTestResult::outside_left:
				return ivec2(0, i);
			default:
			case SpanLayout::HitTestResult::outside_right:
				return ivec2(line.text.size(), i);
			}
		}
	}
	return ivec2(lines.back().text.size(), static_cast<int>(lines.size()) - 1);
}

#include "WALRUS.hh"
#include <fstream>
#include <algorithm>

/*! @file
 * @brief implements the try and check of a time step
*/

// Helper: compute linear interpolation factor for limiting time step
inline double interpolate_factor(double start_val, double end_val, double limit) {
    return (start_val - limit) / (start_val - end_val);
}

double WALRUS::fGS_dG(double dG) {
    double diff = cD - dG;
    double lower_bound = _hS;
    double max_term = std::max(diff, lower_bound);
    return (cD - _dG - _hS) * max_term / cG;
}

void WALRUS::calctryvalues(double tend) {
    // Accumulated inputs over interval [_time, tend]
    double cumP = get_cum(fc_P, _time, tend);
    double cumETpot = get_cum(fc_ETpot, _time, tend);

    P_try = cumP;
    ETpot_try = cumETpot;
    fXG_try = get_cum(fc_XG, _time, tend);
    fXS_try = get_cum(fc_XS, _time, tend);
    fXSact_try = fXS_try;

    // Derived state variables
    _W = W_dV(_dV);
    _dVeq = dVeq_dG(_dG);

    // Fluxes scaled by area and fraction
    PQ_try = cumP * _W * aG;
    PV_try = cumP * (1.0 - _W) * aG;
    PS_try = cumP * aS;
    ETV_try = cumETpot * beta_dV(_dV) * aG;

    // Evaporation from soil only if sufficient surface height
    if (_hS > hSzeroforET) {
        ETS_try = cumETpot * aS;
    } else {
        ETS_try = 0.0;
    }

    // Time step in hours
    double dt = (tend - _time) / 3600.0;

    ETact_try = ETV_try + ETS_try;
    fQS_try = (_hQ / cQ) * dt;
    fGS_try = fGS_dG(_dG) * dt;
    Q_try = Q_hS(_hS) * dt;

    // Tentative new states
    dV_try = _dV + (-fXG_try - PV_try + ETV_try + fGS_try) / aG;
    hQ_try = _hQ + (PQ_try - fQS_try) / aG;

    // Stability corrections (March2018, May2021)
    if (hQ_try < min_h) {
        double deficit = min_h - hQ_try;
        fQS_try += deficit * aG;
        hQ_try = min_h;
    }

    hS_try = _hS + (fXSact_try + PS_try - ETS_try + fGS_try + fQS_try - Q_try) / aS;

    // Soil surface correction (non-negative depth)
    if (hS_try < 0.0 && fXSact_try < 0.0) {
        double shortfall = -hS_try * aS;
        fXSact_try -= shortfall;
        hS_try = 0.0;
    }

    // Groundwater storage change
    dG_try = _dG + (_dV - _dVeq) / cV * dt;

    // Large-scale ponding/flooding handling
    bool ponding = (dV_try < 0.0);
    bool flooding = (hS_try > cD);

    if (ponding || flooding) {
        if (ponding && !flooding) {
            // Ponding only: adjust surface water height, set dV=0
            hS_try -= dV_try * aG / aS;
            dV_try = 0.0;

            // Ensure hS doesn't exceed cD due to numerical overshoot
            if (hS_try > cD) {
                double excess_vol = (hS_try - cD) * aS;
                dV_try = -excess_vol / aG;
                hS_try = cD;
            }
        }
        else if (!ponding && flooding) {
            // Flooding only: all excess goes into soil, cap at cD
            dV_try += (-hS_try + cD) * aS / aG;
            hS_try = cD;
        }
        else if (ponding && flooding) {
            // Both: combine effects
            double flood_vol = (hS_try - cD) * aS;
            dV_try -= flood_vol / aG;
            hS_try = cD;
        }

        // If still negative volume, assign to groundwater
        if (dV_try < 0.0) {
            dG_try = dV_try;
        }
    }
}

double WALRUS::pred_time_tries_OK(double tend) {
    // Minimum allowed time increment
    if (tend < _time + min_deltime) {
        return tend;
    }

    double tc = tend;

    // Limit time step based on hS dropping below min_h
    if (hS_try < min_h) {
        double f = interpolate_factor(_hS, hS_try, min_h);
        double thS = f * tend + (1.0 - f) * _time;
        if (thS < tc) tc = thS;
        hS_try = min_h; // clamp to avoid negative values
    }

    // Same for hQ
    if (hQ_try < min_h) {
        double f = interpolate_factor(_hQ, hQ_try, min_h);
        double thQ = f * tend + (1.0 - f) * _time;
        if (thQ < tc) tc = thQ;
        hQ_try = min_h;
    }

    // Step-size limits for cumulative fluxes
    double P_step = get_cum(fc_P, _time, tend);
    if (P_step > max_Pstep) {
        double f = max_Pstep / P_step;
        double tP = f * tend + (1.0 - f) * _time;
        if (tP < tc) tc = tP;
    }

    double ETpot_step = get_cum(fc_ETpot, _time, tend);
    if (ETpot_step > max_Pstep) {
        double f = max_Pstep / ETpot_step;
        double tETpot = f * tend + (1.0 - f) * _time;
        if (tETpot < tc) tc = tETpot;
    }

    double fXG_step = get_cum(fc_XG, _time, tend);
    if (fXG_step > max_Pstep) {
        double f = max_Pstep / fXG_step;
        double tfXG = f * tend + (1.0 - f) * _time;
        if (tfXG < tc) tc = tfXG;
    }

    double fXS_step = get_cum(fc_XS, _time, tend);
    if (fXS_step > max_Pstep) {
        double f = max_Pstep / fXS_step;
        double tfXS = f * tend + (1.0 - f) * _time;
        if (tfXS < tc) tc = tfXS;
    }

    // State change limits
    double abs_hS_change = std::fabs(hS_try - _hS);
    if (abs_hS_change > max_h_change) {
        double f = max_h_change / abs_hS_change;
        double thS_change = f * tend + (1.0 - f) * _time;
        if (thS_change < tc) tc = thS_change;
    }

    double abs_hQ_change = std::fabs(hQ_try - _hQ);
    if (abs_hQ_change > max_h_change) {
        double f = max_h_change / abs_hQ_change;
        double thQ_change = f * tend + (1.0 - f) * _time;
        if (thQ_change < tc) tc = thQ_change;
    }

    double abs_dG_change = std::fabs(dG_try - _dG);
    if (abs_dG_change > max_h_change) {
        double f = max_h_change / abs_dG_change;
        double tdG_change = f * tend + (1.0 - f) * _time;
        if (tdG_change < tc) tc = tdG_change;
    }

    // Final safety checks
    if (tc <= _time) {
        tc = _time + min_deltime;
    }
    if (tc > tend) {
        tc = tend;
    }

    return tc;
}

