// Helper class to wrap track list for v3 info source interface
class track_info_source_v3 : public track_property_provider_v3_info_source {
public:
	track_info_source_v3(trackListRef tracks) : m_tracks(tracks) {}

	trackInfoContainer::ptr get_info(size_t idx) override {
		return trackGetInfoRef(m_tracks, idx);
	}

private:
	trackListRef m_tracks;
};

// Adapter to bridge v2 callback into v3 callback interface
class callback_adapter_v2_to_v3 : public track_property_callback_v2 {
public:
	callback_adapter_v2_to_v3(track_property_callback& base) : m_base(base) {}

	void set_property(const char* group, double priority, const char* name, const char* value) override {
		m_base.set_property(group, priority, name, value);
	}

	bool is_group_wanted(const char*) override {
		return true;
	}

private:
	track_property_callback& m_base;
};

// Wrapper for v5 info source that chains to v3 info source
class info_source_v5_from_v3 : public track_property_provider_v5_info_source {
public:
	info_source_v5_from_v3(track_property_provider_v3_info_source& upstream, trackListRef tracks)
		: m_upstream(upstream), m_tracks(tracks) {}

	metadb_v2_rec_t get_info(size_t index) override {
		metadb_v2_rec_t result = m_tracks[index]->query_v2_();
		result.info = m_upstream.get_info(index);
		return result;
	}

private:
	track_property_provider_v3_info_source& m_upstream;
	trackListRef m_tracks;
};

// V3 info source wrapper used when only v5 info source is available
class info_source_v3_from_v5 : public track_property_provider_v3_info_source {
public:
	info_source_v3_from_v5(track_property_provider_v5_info_source* chain)
		: m_chain(chain), m_fallback(fb2k::service_new<metadb_info_container_const_impl>()) {}

	trackInfoContainer::ptr get_info(size_t index) override {
		auto info = m_chain->get_info(index).info;
		if (info.is_empty()) {
			info = m_fallback;
		}
		return info;
	}

private:
	track_property_provider_v5_info_source* m_chain;
	metadb_info_container::ptr m_fallback;
};

