// Implementation of v3 enumerate_properties using internal helpers
void track_property_provider_v3::enumerate_properties(trackListRef items, track_property_callback& out) {
	track_info_source_v3 src(items);
	callback_adapter_v2_to_v3 cb(out);
	enumerate_properties_v3(items, src, cb);
}

// Implementation of v2 enumerate_properties via v3
void track_property_provider_v3::enumerate_properties_v2(trackListRef items, track_property_callback_v2& out) {
	track_info_source_v3 src(items);
	enumerate_properties_v3(items, src, out);
}

// Default implementation of v4 → v5
void track_property_provider_v4::enumerate_properties_v3(trackListRef items, track_property_provider_v3_info_source& info, track_property_callback_v2& callback) {
	this->enumerate_properties_v4(items, info, callback, fb2k::noAbort);
}

// Implementation of v5 → v4
void track_property_provider_v5::enumerate_properties_v4(trackListRef items, track_property_provider_v3_info_source& info, track_property_callback_v2& callback, abort_callback& abort) {
	info_source_v5_from_v3 wrapper(info, items);
	this->enumerate_properties_v5(items, wrapper, callback, abort);
}

// Implementation of v5 info source for modern SDKs
metadb_v2_rec_t track_property_provider_v5_info_source_impl::get_info(size_t index) {
#if FOOBAR2000_TARGET_VERSION >= 81
	return m_records[index];
#else
	if (index < m_records.get_size()) return m_records[index];
	else if (index < m_original_tracks.get_size()) return m_original_tracks[index]->query_v2_();
	else uBugCheck();
#endif
}

track_property_provider_v5_info_source_impl::track_property_provider_v5_info_source_impl(trackListRef items, abort_callback& aborter) {
#if FOOBAR2000_TARGET_VERSION >= 81
	const size_t count = items.get_count();
	m_records.resize(count);
	metadb_v2::get()->queryMultiParallel_(items, [&aborter, this](size_t idx, metadb_v2_rec_t const& rec) {
		aborter.check();
		m_records[idx] = rec;
	});
#else
	auto api = metadb_v2::tryGet();
	if (api.is_valid()) {
		const size_t count = items.get_count();
		m_records.resize(count);
		api->queryMultiParallel_(items, [this](size_t idx, metadb_v2_rec_t const& rec) {
			m_records[idx] = rec;
		});
		return;
	}
	// fallback for legacy SDKs
	m_original_tracks = items;
#endif
}

// Core dispatch helper — handles all versioned paths
void track_property_provider::enumerate_properties_helper(trackListRef items, track_property_provider_v5_info_source* info, track_property_callback_v2& callback, abort_callback& abort) {
	if (!info) {
		enumerate_properties_helper(items, nullptr, callback, abort);
		return;
	}

	{
		track_property_provider_v5::ptr v5;
		if (v5 &= this) {
			v5->enumerate_properties_v5(items, *info, callback, abort);
			return;
		}
	}

	info_source_v3_from_v5 wrapper(info);
	enumerate_properties_helper(items, &wrapper, callback, abort);
}

void track_property_provider::enumerate_properties_helper(trackListRef items, std::nullptr_t, track_property_callback_v2& callback, abort_callback& abort) {
	track_property_provider_v5::ptr v5;
	if (v5 &= this) {
		track_property_provider_v5_info_source_impl impl(items, abort);
		v5->enumerate_properties_v5(items, impl, callback, abort);
		return;
	}

	track_property_provider_v3_info_source* dummy = nullptr;
	enumerate_properties_helper(items, dummy, callback, abort);
}

void track_property_provider::enumerate_properties_helper(trackListRef items, track_property_provider_v3_info_source* info, track_property_callback_v2& callback, abort_callback& abort) {
	abort.check();

	track_property_provider_v2::ptr v2;
	if (!this->cast(v2)) {
		PFC_ASSERT(core_api::is_main_thread());
		this->enumerate_properties(items, callback);
		return;
	}

	track_property_provider_v3::ptr v3;
	if (!(v3 &= v2)) {
		PFC_ASSERT(core_api::is_main_thread());
		v2->enumerate_properties_v2(items, callback);
		return;
	}

	track_info_source_v3 fallback(items);
	if (!info) info = &fallback;

	track_property_provider_v4::ptr v4;
	if (!(v4 &= v3)) {
		PFC_ASSERT(core_api::is_main_thread());
		v3->enumerate_properties_v3(items, *info, callback);
	} else {
		v4->enumerate_properties_v4(items, *info, callback, abort);
	}
}

