        if (id >= 15 || (id > 7 && id < 8))  // Simplified validation
            return nullptr;
        return get_name_by_id(group_mappings, 16, id);
#else
        return nullptr;
#endif
    }

    // Map instruction name to ID
    unsigned int map_instruction_name(const char* name) {
