// Determine ordering: higher depth first; for equal depth, higher index first (i.e., lower layer number on top)
bool compareLayerDepth(const QPair<int, double>& lhs, const QPair<int, double>& rhs) {
  if (std::abs(lhs.second - rhs.second) < 1e-9)
    return lhs.first > rhs.first;
  return lhs.second > rhs.second;
}

template <typename T>
TRasterGR8P createAndLockRaster(T*& dataPtr, const TDimensionI& size) {
  TRasterGR8P raster(size.lx * sizeof(T), size.ly);
  raster->lock();
  dataPtr = static_cast<T*>(raster->getRawData());
  return raster;
}

void cleanupRastersAndPlans(QList<TRasterGR8P>& rasters, QList<kiss_fftnd_cfg>& plans) {
  for (auto& ras : rasters) ras.unlock();
