//--------------------------------------------
// Retrieve sorted list of connected source indices based on depth (farthest first)
QList<int> Iwa_BokehAdvancedFx::getSortedSourceIndices(double frame) {
  QList<QPair<int, double>> activeLayers;

  for (int idx = 0; idx < LAYER_NUM; ++idx) {
    if (m_layerParams[idx].m_source.isConnected()) {
      double dist = m_layerParams[idx].m_distance->getValue(frame);
      activeLayers.emplace_back(idx, dist);
    }
  }

  if (activeLayers.isEmpty()) return {};

  std::sort(activeLayers.begin(), activeLayers.end(), compareLayerDepth);

  QList<int> resultIndices;
  for (const auto& pair : activeLayers)
    resultIndices << pair.first;

  return resultIndices;
}

//--------------------------------------------
// Compute bokeh size per layer and determine maximum absolute size
QMap<int, double> Iwa_BokehAdvancedFx::getIrisSizes(
    const double frame,
    const QList<int>& sortedIndices,
    const double bokehPixelAmount,
    double& outMaxSize) {

  QList<int> availableDepthPorts;
  for (int portIdx = 0; portIdx < getInputPortCount(); ++portIdx) {
    QString name = QString::fromStdString(getInputPortName(portIdx));
    if (name.startsWith("Depth") && getInputPort(portIdx)->isConnected())
      availableDepthPorts << name.mid(5).toInt();
  }

  double focusDist = m_onFocusDistance->getValue(frame);
  double maxAbsSize = 0.0;
  QMap<int, double> irisMap;

  for (int sIdx = 0; sIdx < sortedIndices.size(); ++sIdx) {
    int layerIdx = sortedIndices[sIdx];
    double layerDepth = m_layerParams[layerIdx].m_distance->getValue(frame);
    double adjustment = m_layerParams[layerIdx].m_bokehAdjustment->getValue(frame);
    double refDepthVal = m_layerParams[layerIdx].m_depth_ref->getValue();

    double computedSize;
    bool useRef = (refDepthVal != 0) && availableDepthPorts.contains(static_cast<int>(refDepthVal));

    if (!useRef) {
      computedSize = (focusDist - layerDepth) * bokehPixelAmount * adjustment;
    } else {
      double halfRange = m_layerParams[layerIdx].m_depthRange->getValue(frame) * 0.5;
      double nearOffset = focusDist - layerDepth + halfRange;
      double farOffset  = focusDist - layerDepth - halfRange;
      computedSize = (std::abs(nearOffset) >= std::abs(farOffset)) 
                     ? nearOffset * bokehPixelAmount * adjustment 
                     : farOffset * bokehPixelAmount * adjustment;
    }

    irisMap[layerIdx] = computedSize;
    maxAbsSize = std::max(maxAbsSize, std::abs(computedSize));
  }

  outMaxSize = maxAbsSize;
  return irisMap;
}

//-----------------------------------------------------
// Check whether a given depth control port is actively used by any layer
bool Iwa_BokehAdvancedFx::portIsUsed(int portIndex) {
  for (int layer = 0; layer < LAYER_NUM; ++layer) {
    if (m_layerParams[layer].m_source.isConnected() &&
        m_layerParams[layer].m_depth_ref->getValue() == portIndex)
      return true;
  }
  return false;
}

//--------------------------------------------
Iwa_BokehAdvancedFx::Iwa_BokehAdvancedFx()
    : m_hardnessPerSource(false), m_control("Depth") {
  // Bind global parameters
  bindParam(this, "on_focus_distance", m_onFocusDistance, false);
  bindParam(this, "bokeh_amount", m_bokehAmount, false);
  bindParam(this, "masterHardness", m_hardness, false);
  bindParam(this, "masterGamma", m_gamma, false);
  bindParam(this, "masterGammaAdjust", m_gammaAdjust, false);
  bindParam(this, "hardnessPerSource", m_hardnessPerSource, false);
  bindParam(this, "linearizeMode", m_linearizeMode, false);

  // Initialize and bind per-layer parameters
  for (int layer = 0; layer < LAYER_NUM; ++layer) {
    m_layerParams[layer].m_distance        = TDoubleParamP(0.5);
    m_layerParams[layer].m_bokehAdjustment = TDoubleParamP(1.0);
    m_layerParams[layer].m_hardness        = TDoubleParamP(0.3);
    m_layerParams[layer].m_gamma           = TDoubleParamP(2.2);
    m_layerParams[layer].m_gammaAdjust     = TDoubleParamP(0.0);
    m_layerParams[layer].m_depth_ref       = TIntParamP(0);
    m_layerParams[layer].m_depthRange      = TDoubleParamP(1.0);
    m_layerParams[layer].m_fillGap         = TBoolParamP(true);
    m_layerParams[layer].m_doMedian        = TBoolParamP(false);

    std::string srcName = "Source" + std::to_string(layer + 1);
    addInputPort(srcName, m_layerParams[layer].m_source);

    bindParam(this, "distance" + std::to_string(layer + 1),
              m_layerParams[layer].m_distance);
    bindParam(this, "bokeh_adjustment" + std::to_string(layer + 1),
              m_layerParams[layer].m_bokehAdjustment);
    bindParam(this, "gamma" + std::to_string(layer + 1),
              m_layerParams[layer].m_gamma);
    bindParam(this, "gammaAdjust" + std::to_string(layer + 1),
              m_layerParams[layer].m_gammaAdjust);
    bindParam(this, "hardness" + std::to_string(layer + 1),
              m_layerParams[layer].m_hardness);
    bindParam(this, "depth_ref" + std::to_string(layer + 1),
              m_layerParams[layer].m_depth_ref);
    bindParam(this, "depthRange" + std::to_string(layer + 1),
              m_layerParams[layer].m_depthRange);
    bindParam(this, "fillGap" + std::to_string(layer + 1),
              m_layerParams[layer].m_fillGap);
    bindParam(this, "doMedian" + std::to_string(layer + 1),
              m_layerParams[layer].m_doMedian);

    // Set value ranges
    m_layerParams[layer].m_distance->setValueRange(0.0, 1.0);
    m_layerParams[layer].m_bokehAdjustment->setValueRange(0.0, 2.0);
    m_layerParams[layer].m_hardness->setValueRange(0.05, 3.0);
    m_layerParams[layer].m_gamma->setValueRange(1.0, 10.0);
    m_layerParams[layer].m_gammaAdjust->setValueRange(-5.0, 5.0);
    m_layerParams[layer].m_depthRange->setValueRange(0.0, 1.0);
  }

  addInputPort("Depth1", new TRasterFxPort, 0);
  enableComputeInFloat(true);
  setFxVersion(3); // Version 3 supports both Hardness and Gamma modes
}

//--------------------------------------------
void Iwa_BokehAdvancedFx::onFxVersionSet() {
  bool useGamma = getFxVersion() == 2;
  if (getFxVersion() == 1) {
    m_linearizeMode->setValue(Hardness);
    setFxVersion(3);
  } else if (getFxVersion() == 2) {
    if (m_linearizeMode->getValue() == Hardness) {
      useGamma = false;
      setFxVersion(3);
    }
  }

  auto* masterGammaParam = getParams()->getParamVar("masterGamma");
  auto* masterGammaAdj   = getParams()->getParamVar("masterGammaAdjust");
  masterGammaParam->setIsHidden(!useGamma);
  masterGammaAdj->setIsHidden(useGamma);

  for (int layer = 0; layer < LAYER_NUM; ++layer) {
    std::string gammaName = "gamma" + std::to_string(layer + 1);
    std::string adjName   = "gammaAdjust" + std::to_string(layer + 1);
    getParams()->getParamVar(gammaName)->setIsHidden(!useGamma);
    getParams()->getParamVar(adjName)->setIsHidden(useGamma);
  }
}

//--------------------------------------------
void Iwa_BokehAdvancedFx::doCompute(TTile& tile, double frame,
                                    const TRenderSettings& settings) {
  // Early exit if no iris input
  if (!m_iris.isConnected()) {
    tile.getRaster()->clear();
    return;
  }

  // Early exit if no sources connected
  bool hasActiveSources = false;
  for (int i = 0; i < LAYER_NUM; ++i) {
    if (m_layerParams[i].m_source.isConnected()) {
      hasActiveSources = true;
      break;
    }
  }
  if (!hasActiveSources) {
    tile.getRaster()->clear();
    return;
  }

  // Sort layers by depth
  QList<int> sortedIndices = getSortedSourceIndices(frame);

  // Compute pixel scaling factor for bokeh
  double bokehScale = BokehUtils::getBokehPixelAmount(
      m_bokehAmount->getValue(frame), settings.m_affine);

  // Determine required margin and tile dimensions
  double maxBokehSize;
  QMap<int, double> bokehSizes =
      getIrisSizes(frame, sortedIndices, bokehScale, maxBokehSize);
  int margin = static_cast<int>(std::ceil(std::abs(maxBokehSize) * 0.5));

  TRectD outputRect(tile.m_pos, TDimensionD(tile.getRaster()->getLx(),
                                            tile.getRaster()->getLy()));
  outputRect = outputRect.enlarge(static_cast<double>(margin));
  TDimensionI dimOut(static_cast<int>(outputRect.getLx() + 0.5),
                     static_cast<int>(outputRect.getLy() + 0.5));

  // Optimize FFT sizes (powers of 2,3,5)
  if (dimOut.lx < 10000 && dimOut.ly < 10000) {
    int nx = kiss_fft_next_fast_size(dimOut.lx);
    int ny = kiss_fft_next_fast_size(dimOut.ly);
    while ((nx - dimOut.lx) % 2 != 0) nx = kiss_fft_next_fast_size(nx + 1);
    while ((ny - dimOut.ly) % 2 != 0) ny = kiss_fft_next_fast_size(ny + 1);
    double dx = static_cast<double>(nx - dimOut.lx) / 2.0;
    double dy = static_cast<double>(ny - dimOut.ly) / 2.0;
    outputRect = outputRect.enlarge(dx, dy);
    dimOut.lx = nx;
    dimOut.ly = ny;
  }

  // Compute source tiles
  QMap<int, TTile*> sourceTiles;
  for (int idx : sortedIndices) {
    TTile* layerTile = new TTile();
    m_layerParams[idx].m_source->allocateAndCompute(
        *layerTile, outputRect.getP00(), dimOut, tile.getRaster(), frame, settings);
    sourceTiles[idx] = layerTile;
  }

  // Compute iris tile
  TRectD irisBBox;
  m_iris->getBBox(frame, irisBBox, settings);
  TTile irisTile;
  m_iris->allocateAndCompute(
      irisTile, irisBBox.getP00(),
      TDimension(static_cast<int>(irisBBox.getLx() + 0.5),
                 static_cast<int>(irisBBox.getLy() + 0.5)),
      tile.getRaster(), frame, settings);

  // Prepare reference depth maps
  std::vector<TRasterGR8P> depthRasters;
  QMap<int, unsigned char*> depthBuffers;

  for (int portIdx = 0; portIdx < getInputPortCount(); ++portIdx) {
    QString portName = QString::fromStdString(getInputPortName(portIdx));
    if (portName.startsWith("Depth") && getInputPort(portIdx)->isConnected()) {
      int portNum = portName.mid(5).toInt();
      if (portIsUsed(portNum)) {
        TTile tmpTile;
        TRasterFxPort* ctrlPort = dynamic_cast<TRasterFxPort*>(getInputPort(portIdx));
        (*ctrlPort)->allocateAndCompute(tmpTile, outputRect.getP00(), dimOut,
                                        tile.getRaster(), frame, settings);

        TRasterGR8P depthRaster(dimOut.lx, dimOut.ly);
        depthRaster->lock();
        unsigned char* buffer = static_cast<unsigned char*>(depthRaster->getRawData());

        TRaster32P ras32 = TRaster32P(tmpTile.getRaster());
        TRaster64P ras64 = TRaster64P(tmpTile.getRaster());
        TRasterFP  rasF  = TRasterFP(tmpTile.getRaster());

        lock.lockForRead();
        if (ras32)
          BokehUtils::setDepthRaster<TRaster32P, TPixel32>(ras32, buffer, dimOut);
        else if (ras64)
          BokehUtils::setDepthRaster<TRaster64P, TPixel64>(ras64, buffer, dimOut);
        else if (rasF)
          BokehUtils::setDepthRaster<TRasterFP, TPixelF>(rasF, buffer, dimOut);
        lock.unlock();

        depthRasters.push_back(depthRaster);
        depthBuffers[portNum] = buffer;
      }
    }
  }

  // Determine effective gamma/hardness
  double effectiveGamma;
  if (m_linearizeMode->getValue() == Hardness)
    effectiveGamma = m_hardness->getValue(frame);
  else { // Gamma mode
    if (getFxVersion() == 2)
      effectiveGamma = m_gamma->getValue(frame);
    else
      effectiveGamma = std::max(1.0, settings.m_colorSpaceGamma +
                                      m_gammaAdjust->getValue(frame));
    if (tile.getRaster()->isLinear())
      effectiveGamma /= settings.m_colorSpaceGamma;
  }

  // Build per-layer configuration
  QList<LayerValue> layerConfigs;
  for (int idx : sortedIndices) {
    LayerValue cfg;
    cfg.sourceTile = sourceTiles[idx];
    cfg.premultiply = false;

    if (m_hardnessPerSource->getValue()) {
      if (m_linearizeMode->getValue() == Hardness)
        cfg.layerGamma = m_layerParams[idx].m_hardness->getValue(frame);
      else {
        if (getFxVersion() == 2)
          cfg.layerGamma = m_layerParams[idx].m_gamma->getValue(frame);
        else
          cfg.layerGamma = std::max(1.0, settings.m_colorSpaceGamma +
                                           m_layerParams[idx].m_gammaAdjust->getValue(frame));
        if (tile.getRaster()->isLinear())
          cfg.layerGamma /= settings.m_colorSpaceGamma;
      }
    } else {
      cfg.layerGamma = effectiveGamma;
    }

    cfg.depth_ref            = m_layerParams[idx].m_depth_ref->getValue();
    cfg.irisSize             = bokehSizes.value(idx);
    cfg.distance             = m_layerParams[idx].m_distance->getValue(frame);
    cfg.bokehAdjustment      = m_layerParams[idx].m_bokehAdjustment->getValue(frame);
    cfg.depthRange           = m_layerParams[idx].m_depthRange->getValue(frame);
    cfg.distancePrecision    = 10;
    cfg.fillGap              = m_layerParams[idx].m_fillGap->getValue();
    cfg.doMedian             = m_layerParams[idx].m_doMedian->getValue();

    layerConfigs.append(cfg);
  }

  // Perform main bokeh computation
  Iwa_BokehCommonFx::doFx(tile, frame, settings, bokehScale, margin,
                          dimOut, irisBBox, irisTile, layerConfigs, depthBuffers);

  // Cleanup
  for (auto& ras : depthRasters) ras.unlock();
  qDeleteAll(sourceTiles);
}

