// Generate expected signal message string
std::string BuildSignalMessage(const std::string& sigName, const std::string& stage)
{
    auto it = STAGE_MAPPING.find(stage);
    if (it == STAGE_MAPPING.end()) {
        return "";
    }

    std::string prefix = Cangjie::ICE::MSG_PART_ONE + Cangjie::SIGNAL_MSG_PART_ONE;
    std::string suffix = Cangjie::SIGNAL_MSG_PART_TWO + Cangjie::ICE::MSG_PART_TWO +
                         std::to_string(it->second) + "\n";

    if (sigName == "StackOverflow") {
#ifdef __unix__
        return CANGJIE_COMPILER_VERSION + "\n" + prefix + std::to_string(SIGSEGV) + suffix;
#elif _WIN32
        return CANGJIE_COMPILER_VERSION + "\n" + prefix + std::to_string(STACK_OVERFLOW_EXIT_CODE) + suffix;
#endif
    }

    auto sigIt = SIGNAL_CODE_MAP.find(sigName);
    if (sigIt != SIGNAL_CODE_MAP.end()) {
        return CANGJIE_COMPILER_VERSION + "\n" + prefix + std::to_string(sigIt->second) + suffix;
    }

    return "";
}

// Verify no temporary files remain
void CheckNoTempFiles()
{
#ifdef _WIN32
    FILE* proc = _popen("dir", "r");
#else
    FILE* proc = popen("ls", "r");
#endif

    if (!proc) {
        return;
    }

    std::string output;
    int ch;
    while ((ch = fgetc(proc)) != EOF) {
        output.push_back(static_cast<char>(ch));
    }

#ifdef _WIN32
    _pclose(proc);
#else
    pclose(proc);
#endif

    const std::string tempPrefix = "cangjie-tmp-";
    EXPECT_TRUE(output.find(tempPrefix) == std::string::npos);
}

// Validate error output content
void ValidateErrorOutput(const std::string& sigName, const std::string& stage)
{
    std::ifstream errFile(ERROR_LOG_PATH);
    std::string content((std::istreambuf_iterator<char>(errFile)), std::istreambuf_iterator<char>());
    errFile.close();

    std::string expected = BuildSignalMessage(sigName, stage);
    EXPECT_EQ(content, expected);

    CheckNoTempFiles();
}

// Process execution logic
#ifdef __unix__
#define MAX_PATH_LEN 4096

int RunProcess(const std::string& sigName, const std::string& stage)
{
    std::ostringstream cmdStream;
    cmdStream << sigName << "_" << stage << "_" << ERROR_LOG_PATH;
    std::string args = cmdStream.str();

    char exePath[MAX_PATH_LEN] = {0};
    ssize_t len = readlink("/proc/self/exe", exePath, MAX_PATH_LEN);
    if (len == -1) {
        return -1;
    }

    std::string binaryPath = FileUtil::GetDirPath(std::string(exePath)) + "/SignalTestCJC";

    pid_t childPid = fork();
    if (childPid == 0) {
        if (execl(binaryPath.c_str(), binaryPath.c_str(), CJ_TEST_FILE.c_str(), args.c_str(), nullptr) == -1) {
            _exit(1);
        }
    } else if (childPid > 0) {
        int status;
        waitpid(childPid, &status, 0);

        if (WIFEXITED(status)) {
            return WEXITSTATUS(status);
        } else if (WIFSIGNALED(status)) {
            return WTERMSIG(status) + 128;
        }
    }

    return -1;
}

#elif _WIN32

DWORD RunProcess(const std::string& sigName, const std::string& stage)
{
    char exePath[MAX_PATH];
    GetModuleFileNameA(NULL, exePath, MAX_PATH);
    std::string binPath = FileUtil::GetDirPath(std::string(exePath)) + "\\SignalTestCJC.exe";

    std::ostringstream cmdStream;
    cmdStream << binPath << " " << CJ_TEST_FILE << " " << sigName << "_" << stage << "_" << ERROR_LOG_PATH;
    std::string commandLine = cmdStream.str();

    STARTUPINFOA si = {};
    si.cb = sizeof(si);
    PROCESS_INFORMATION pi = {};

    if (!CreateProcessA(binPath.c_str(), commandLine.data(), NULL, NULL, FALSE, 0, NULL, NULL, &si, &pi)) {
        return 1;
    }

    WaitForSingleObject(pi.hProcess, INFINITE);

    DWORD exitCode;
    if (!GetExitCodeProcess(pi.hProcess, &exitCode)) {
        CloseHandle(pi.hProcess);
        CloseHandle(pi.hThread);
        return 1;
    }

    CloseHandle(pi.hProcess);
    CloseHandle(pi.hThread);

    return exitCode;
}
#endif

// Test macros
#define RUN_TEST(sig, stage)                                                                                           \
    TEST_F(SignalTests, stage##Signal##sig)                                                                            \
    {                                                                                                                  \
        EXPECT_EQ(RunProcess(#sig, #stage), sig + 128);                                                                \
        ValidateErrorOutput(#sig, #stage);                                                                             \
    }

#define RUN_STACKOVERFLOW_TEST(stage)                                                                                  \
    TEST_F(SignalTests, stage##StackOverflow)                                                                          \
    {                                                                                                                  \
        EXPECT_EQ(RunProcess("StackOverflow", #stage), STACK_OVERFLOW_EXIT_CODE);                                      \
        ValidateErrorOutput("StackOverflow", #stage);                                                                  \
    }

