// Helper macro to simplify zeroing register
#define ZERO_REG(r) la_xvxor_v(r, r, r)

bool translate_vpslldq(IR1_INST * pir1) {
    IR1_OPND * dst_op = ir1_get_opnd(pir1, 0);
    IR1_OPND * src_op = ir1_get_opnd(pir1, 1);
    IR1_OPND * imm_op = ir1_get_opnd(pir1, 2);

    lsassert((ir1_opnd_is_xmm(dst_op) && ir1_opnd_is_xmm(src_op)) ||
             (ir1_opnd_is_ymm(dst_op) && ir1_opnd_is_ymm(src_op)));
    lsassert(ir1_opnd_is_imm(imm_op));

    IR2_OPND dest_reg = load_freg256_from_ir1(dst_op);
    IR2_OPND source_reg = load_freg256_from_ir1(src_op);
    uint8_t shift_amount = ir1_opnd_uimm(imm_op);

    if (shift_amount > 15) {
        ZERO_REG(dest_reg);
        return true;
    }

    la_xvbsll_v(dest_reg, source_reg, shift_amount);
    if (ir1_opnd_is_xmm(dst_op)) {
        set_high128_xreg_to_zero(dest_reg);
    }
    return true;
}

bool translate_vpsllx(IR1_INST * pir1) {
    IR1_OPND * dst_op = ir1_get_opnd(pir1, 0);
    IR1_OPND * src_op = ir1_get_opnd(pir1, 1);
    IR1_OPND * cnt_op = ir1_get_opnd(pir1, 2);

    lsassert((ir1_opnd_is_xmm(dst_op) && ir1_opnd_is_xmm(src_op)) ||
             (ir1_opnd_is_ymm(dst_op) && ir1_opnd_is_ymm(src_op)));

    IR2_OPND dest_reg = load_freg256_from_ir1(dst_op);
    IR2_OPND source_reg = load_freg256_from_ir1(src_op);

    IR2_INST * (*rep_func)(IR2_OPND, IR2_OPND);
    IR2_INST * (*imm_func)(IR2_OPND, IR2_OPND, int);
    IR2_INST * (*var_func)(IR2_OPND, IR2_OPND, IR2_OPND);
    int max_shift;

    switch (ir1_opcode(pir1)) {
        case dt_X86_INS_VPSLLW:
            rep_func = la_xvreplve0_h;
            imm_func = la_xvslli_h;
            var_func = la_xvsll_h;
            max_shift = 15;
            break;
        case dt_X86_INS_VPSLLD:
            rep_func = la_xvreplve0_w;
            imm_func = la_xvslli_w;
            var_func = la_xvsll_w;
            max_shift = 31;
            break;
        case dt_X86_INS_VPSLLQ:
            rep_func = la_xvreplve0_d;
            imm_func = la_xvslli_d;
            var_func = la_xvsll_d;
            max_shift = 63;
            break;
        default:
            lsassert(0);
            return false;
    }

    if (ir1_opnd_is_imm(cnt_op)) {
        uint8_t amount = ir1_opnd_uimm(cnt_op);
        if (amount > max_shift) {
            ZERO_REG(dest_reg);
        } else {
            imm_func(dest_reg, source_reg, amount);
        }
    } else {
        IR2_OPND src_cnt = load_freg256_from_ir1(cnt_op);
        IR2_OPND mask = ra_alloc_ftemp();
        IR2_OPND tmp_val = ra_alloc_ftemp();

        // Broadcast low element for comparison
        la_xvreplve0_d(mask, src_cnt);
        if (max_shift == 63) {
            la_xvldi(tmp_val, VLDI_IMM_TYPE0(3, 63));
            la_xvsle_du(mask, mask, tmp_val);
        } else {
            la_xvslei_du(mask, mask, max_shift);
        }

        rep_func(tmp_val, src_cnt);
        var_func(dest_reg, source_reg, tmp_val);
        la_xvand_v(dest_reg, dest_reg, mask);
    }

    if (ir1_opnd_is_xmm(dst_op)) {
        set_high128_xreg_to_zero(dest_reg);
    }
    return true;
}

