#include <cmath>
#include <format>
#include <gtest/gtest.h>
#include "maths/vector3.h"
#include "utils/formatter.h"

// Test: default constructor initializes all components to zero
TEST(vector3, empty_ctor)
{
    const auto v = ufps::Vector3{};
    EXPECT_FLOAT_EQ(v.x, 0.0f);
    EXPECT_FLOAT_EQ(v.y, 0.0f);
    EXPECT_FLOAT_EQ(v.z, 0.0f);
}

// Test: single-value constructor sets all components to the same value
TEST(vector3, single_value_ctor)
{
    const auto v = ufps::Vector3{1.1f};
    EXPECT_FLOAT_EQ(v.x, 1.1f);
    EXPECT_FLOAT_EQ(v.y, 1.1f);
    EXPECT_FLOAT_EQ(v.z, 1.1f);
}

// Test: full component constructor assigns values correctly
TEST(vector3, all_components_ctor)
{
    const auto v = ufps::Vector3{1.1f, 2.2f, 3.3f};
    EXPECT_FLOAT_EQ(v.x, 1.1f);
    EXPECT_FLOAT_EQ(v.y, 2.2f);
    EXPECT_FLOAT_EQ(v.z, 3.3f);
}

// Test: normalization produces unit vector in same direction
TEST(vector3, normalise)
{
    const float len = std::sqrt(3.0f * 3.0f + 4.0f * 4.0f + 5.0f * 5.0f);
    const auto v = ufps::Vector3{3.0f, 4.0f, 5.0f};
    const auto n = ufps::Vector3::normalise(v);
    EXPECT_NEAR(n.x, v.x / len, 0.0001f);
    EXPECT_NEAR(n.y, v.y / len, 0.0001f);
    EXPECT_NEAR(n.z, v.z / len, 0.0001f);
}

// Test: cross product computes correct perpendicular vector
TEST(vector3, cross)
{
    const auto a = ufps::Vector3{1.0f, 2.0f, 3.0f};
    const auto b = ufps::Vector3{4.0f, 5.0f, 6.0f};
    const auto expected = ufps::Vector3(-3.0f, 6.0f, -3.0f);
    ASSERT_EQ(ufps::Vector3::cross(a, b), expected);
}

// Test: vector addition works component-wise
TEST(vector3, addition)
{
    const auto a = ufps::Vector3{1.0f, 2.0f, 3.0f};
    const auto b = ufps::Vector3{4.0f, 5.0f, 6.0f};
    ASSERT_EQ(a + b, ufps::Vector3(5.0f, 7.0f, 9.0f));
}

// Test: compound addition assignment operator
TEST(vector3, addition_assignment)
{
    auto v = ufps::Vector3{1.0f, 2.0f, 3.0f};
    v += ufps::Vector3{4.0f, 5.0f, 6.0f};
    ASSERT_EQ(v, ufps::Vector3(5.0f, 7.0f, 9.0f));
}

// Test: vector subtraction works component-wise
TEST(vector3, subtraction)
{
    const auto a = ufps::Vector3{2.0f, 10.0f, 12.0f};
    const auto b = ufps::Vector3{4.0f, 5.0f, 6.0f};
    ASSERT_EQ(a - b, ufps::Vector3(-2.0f, 5.0f, 6.0f));
}

// Test: compound subtraction assignment operator
TEST(vector3, subtraction_assignment)
{
    auto v = ufps::Vector3{2.0f, 10.0f, 12.0f};
    v -= ufps::Vector3{4.0f, 5.0f, 6.0f};
    ASSERT_EQ(v, ufps::Vector3(-2.0f, 5.0f, 6.0f));
}

// Test: component-wise multiplication (Hadamard product)
TEST(vector3, multiplication)
{
    const auto a = ufps::Vector3{2.0f, 10.0f, 12.0f};
    const auto b = ufps::Vector3{4.0f, 5.0f, 6.0f};
    ASSERT_EQ(a * b, ufps::Vector3(8.0f, 50.0f, 72.0f));
}

// Test: compound multiplication assignment operator
TEST(vector3, multiplication_assignment)
{
    auto v = ufps::Vector3{2.0f, 10.0f, 12.0f};
    v *= ufps::Vector3{4.0f, 5.0f, 6.0f};
    ASSERT_EQ(v, ufps::Vector3(8.0f, 50.0f, 72.0f));
}

// Test: unary negation flips sign of each component
TEST(vector3, negate)
{
    const auto v = ufps::Vector3{1.0f, 2.0f, 3.0f};
    const auto expected = ufps::Vector3{-1.0f, -2.0f, -3.0f};
    ASSERT_EQ(-v, expected);
}

// Test: string representation matches expected format
TEST(vector3, to_string)
{
    const auto v = ufps::Vector3{1.0f, 2.0f, 3.0f};
    const auto str = v.to_string();
    ASSERT_EQ(str, "x=1 y=2 z=3");
}

// Test: std::format integration for Vector3
TEST(vector3, format)
{
    const auto v = ufps::Vector3{1.0f, 2.0f, 3.0f};
    const auto formatted = std::format("{}", v);
    ASSERT_EQ(formatted, "x=1 y=2 z=3");
}

