        String ProcessOutColorLocations(const String& glslCode) {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            // Manual regex replacement for pattern: \n(out highp vec4 outColor)(\d+);
            String result;
            size_t pos = 0;
            while (pos < glslCode.size()) {
                size_t found = glslCode.find("\n(out highp vec4 outColor)", pos);
                if (found == String::npos || found + 25 >= glslCode.size()) {
                    result += glslCode.substr(pos);
                    break;
                }

                result += glslCode.substr(pos, found - pos);

                // Extract digit(s) after 'outColor'
                size_t digitStart = found + 25;
                size_t digitEnd = digitStart;
                while (digitEnd < glslCode.size() && isdigit(glslCode[digitEnd])) {
                    ++digitEnd;
                }

                String digits = glslCode.substr(digitStart, digitEnd - digitStart);
                result += "\nlayout(location=" + digits + ") out highp vec4 outColor" + digits + ";";

                pos = digitEnd;
            }
            return result;
        }

        String ForceSupporterOutput(const String& glslCode) {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            bool hasFloatPrecision = false;
            bool hasIntPrecision = false;

            // Check for existing precision declarations
            size_t floatPos = glslCode.find("precision highp float;");
            size_t intPos = glslCode.find("precision highp int;");

            if (floatPos != String::npos) hasFloatPrecision = true;
            if (intPos != String::npos) hasIntPrecision = true;

            String processed;
            std::istringstream iss(glslCode);
            String line;

            while (std::getline(iss, line)) {
                // Skip lines that are already precision statements
                if ((line.find("precision highp float;") != String::npos) ||
                    (line.find("precision highp int;") != String::npos)) {
                    continue;
                }
                processed += (processed.empty() ? "" : "\n") + line;
            }

            String newPrecisionLines;
            if (!hasFloatPrecision) newPrecisionLines += "precision highp float;\n";
            if (!hasIntPrecision)   newPrecisionLines += "precision highp int;\n";

            if (newPrecisionLines.empty()) {
                return processed;
            }

            // Insert after last #extension or after first newline
            size_t extPos = processed.rfind("#extension");
            size_t insertAt = 0;

            if (extPos != String::npos) {
                size_t nextNL = processed.find('\n', extPos);
                insertAt = (nextNL != String::npos) ? nextNL + 1 : processed.length();
            } else {
                size_t firstNL = processed.find('\n');
                insertAt = (firstNL != String::npos) ? firstNL + 1 : 0;
            }

            if (insertAt == 0 && processed.empty()) {
                return newPrecisionLines;
            }

            return processed.substr(0, insertAt) + newPrecisionLines + processed.substr(insertAt);
        }

        String RemoveLayoutBinding(const String& glslCode) {
#ifdef TRACY_ENABLE
            ZoneScopedC(TRACY_ZONECOLOR_BACKEND);
#endif
            String result = glslCode;

            // Replace layout(binding=N) with empty string
            static const char bindingPattern1[] = "layout(binding=";
            size_t idx = 0;
            while ((idx = result.find(bindingPattern1, idx)) != String::npos) {
                size_t endIdx = result.find(')', idx + sizeof(bindingPattern1) - 1);
                if (endIdx != String::npos) {
                    result.erase(idx, endIdx - idx + 1);
                } else {
                    break;
                }
            }

            // Replace layout(binding=N, with layout(
            static const char bindingPattern2[] = "layout(binding=";
            idx = 0;
            while ((idx = result.find(bindingPattern2, idx)) != String::npos) {
                size_t commaIdx = result.find(',', idx + sizeof(bindingPattern2) - 1);
                if (commaIdx != String::npos) {
                    result.replace(idx, commaIdx - idx + 1, "layout(");
                } else {
                    break;
                }
            }

            return result;
        }
