            case GL_TEXTURE_CUBE_MAP_ARRAY:
                return GL_TEXTURE_BINDING_CUBE_MAP_ARRAY;
            case GL_TEXTURE_RECTANGLE:
                return GL_TEXTURE_BINDING_RECTANGLE;
            case GL_TRANSFORM_FEEDBACK:
                return GL_TRANSFORM_FEEDBACK_BINDING;
            case GL_SAMPLES_PASSED:
                return GL_SAMPLES_PASSED;
            case GL_PRIMITIVES_GENERATED:
                return GL_PRIMITIVES_GENERATED;
            case GL_DEBUG_OUTPUT:
                return GL_DEBUG_OUTPUT;
            case GL_DEBUG_OUTPUT_SYNCHRONOUS:
                return GL_DEBUG_OUTPUT_SYNCHRONOUS;
            default:
                return 0;
            }
        }
    } // namespace Utils
} // namespace MobileGL::MG_Backend::DirectGLES

#include "disassembler_scudsp.hpp"
#include "fetcher.hpp"
#include <ymir/hw/scu/scu_dsp_disasm.hpp>

struct SCUDSPDisassembler {
    explicit SCUDSPDisassembler(Disassembler &d) : dis(d) {}

    SCUDSPDisassembler &SetAddress() {
        dis.Address(addr);
        return *this;
    }

    SCUDSPDisassembler &SetOpcode(uint32 op) {
        dis.Opcode(op);
        return *this;
    }

    SCUDSPDisassembler &ImmediateByte(uint8 val) {
        dis.ImmHex(val, "#");
        return *this;
    }

    SCUDSPDisassembler &ImmediateSignedByte(sint8 val) {
        dis.ImmHexSignAfterPrefix(val, "#");
        return *this;
    }

    SCUDSPDisassembler &ImmediateSignedWord(sint32 val) {
        dis.ImmHexSignAfterPrefix(val, "#");
        return *this;
    }

    SCUDSPDisassembler &ImmediateWord(uint32 val) {
        dis.ImmHex(val, "#");
        return *this;
    }

    SCUDSPDisassembler &SetMnemonic(std::string_view name) {
        dis.Mnemonic(name);
        return *this;
    }

    SCUDSPDisassembler &SetCondition(ymir::scu::SCUDSPInstruction::Cond c) {
        dis.Cond(ymir::scu::ToString(c));
        return *this;
    }

    SCUDSPDisassembler &AddComma() {
        dis.Comma();
        return *this;
    }

    SCUDSPDisassembler &ReadOperand(std::string_view op) {
        dis.OperandRead(op);
        return *this;
    }

    SCUDSPDisassembler &WriteOperand(std::string_view op) {
        dis.OperandWrite(op);
        return *this;
    }

    SCUDSPDisassembler &ProcessInstruction(const ymir::scu::SCUDSPInstruction &inst) {
        using InstrKind = ymir::scu::SCUDSPInstruction::Type;

        switch (inst.type) {
        case InstrKind::Operation: {
            if (inst.operation.aluOp == ymir::scu::SCUDSPInstruction::ALUOp::NOP) {
                dis.NOP("NOP");
            } else {
                SetMnemonic(ymir::scu::ToString(inst.operation.aluOp));
            }
            dis.Align(5);

            using XBusAction = ymir::scu::SCUDSPInstruction::XBusPOp;
            switch (inst.operation.xbusPOp) {
            case XBusAction::NOP:
                dis.NOP("NOP");
                break;
            case XBusAction::MOV_MUL_P:
                dis.Mnemonic("MOV ").OperandRead("MUL").Comma().OperandWrite("P");
                break;
            case XBusAction::MOV_S_P:
                SetMnemonic("MOV ")
                    .OperandRead(ymir::scu::ToString(inst.operation.xbusSrc))
                    .Comma()
                    .OperandWrite("P");
                break;
            }

            dis.Align(17);
            if (inst.operation.xbusXOp) {
                SetMnemonic("MOV ")
                    .OperandRead(ymir::scu::ToString(inst.operation.xbusSrc))
                    .Comma()
                    .OperandWrite("X");
            } else {
                dis.NOP("NOP");
            }

            dis.Align(29);

            using YBusAction = ymir::scu::SCUDSPInstruction::YBusAOp;
            switch (inst.operation.ybusAOp) {
            case YBusAction::NOP:
                dis.NOP("NOP");
                break;
            case YBusAction::CLR_A:
                dis.Mnemonic("CLR ").OperandWrite("A");
                break;
            case YBusAction::MOV_ALU_A:
                dis.Mnemonic("MOV ").OperandRead("ALU").Comma().OperandWrite("A");
                break;
            case YBusAction::MOV_S_A:
                SetMnemonic("MOV ")
                    .OperandRead(ymir::scu::ToString(inst.operation.xbusSrc))
                    .Comma()
                    .OperandWrite("A");
                break;
            }

            dis.Align(41);

            if (inst.operation.ybusYOp) {
                SetMnemonic("MOV ")
                    .OperandRead(ymir::scu::ToString(inst.operation.ybusSrc))
                    .Comma()
                    .OperandWrite("Y");
            } else {
                dis.NOP("NOP");
            }

            dis.Align(53);

            using D1BusAction = ymir::scu::SCUDSPInstruction::D1BusOp;
            switch (inst.operation.d1BusOp) {
            case D1BusAction::NOP:
                dis.NOP("NOP");
                break;
            case D1BusAction::MOV_SIMM_D: {
                SetMnemonic("MOV ");
                auto imm = inst.operation.d1BusSrc.imm;
                switch (inst.operation.d1BusDst) {
                case ymir::scu::SCUDSPInstruction::OpDst::MC0:
                case ymir::scu::SCUDSPInstruction::OpDst::MC1:
                case ymir::scu::SCUDSPInstruction::OpDst::MC2:
                case ymir::scu::SCUDSPInstruction::OpDst::MC3:
                    ImmediateSignedByte(imm);
                    break;
                case ymir::scu::SCUDSPInstruction::OpDst::RX:
                    ImmediateSignedByte(imm);
                    break;
                case ymir::scu::SCUDSPInstruction::OpDst::P:
                    ImmediateSignedByte(imm);
                    break;
                case ymir::scu::SCUDSPInstruction::OpDst::RA0:
                case ymir::scu::SCUDSPInstruction::OpDst::WA0:
                    ImmediateWord((imm << 2) & 0x7FF'FFFC);
                    break;
                case ymir::scu::SCUDSPInstruction::OpDst::LOP:
                    ImmediateWord(imm & 0xFFF);
                    break;
                case ymir::scu::SCUDSPInstruction::OpDst::TOP:
                    ImmediateByte(imm);
                    break;
                case ymir::scu::SCUDSPInstruction::OpDst::CT0:
                case ymir::scu::SCUDSPInstruction::OpDst::CT1:
                case ymir::scu::SCUDSPInstruction::OpDst::CT2:
                case ymir::scu::SCUDSPInstruction::OpDst::CT3:
                    ImmediateByte(imm & 0x3F);
                    break;
                default:
                    ImmediateSignedByte(imm);
                    break;
                }
                AddComma().WriteOperand(ymir::scu::ToString(inst.operation.d1BusDst));
                break;
            }
            case D1BusAction::MOV_S_D:
                SetMnemonic("MOV ")
                    .OperandRead(ymir::scu::ToString(inst.operation.d1BusSrc.reg))
                    .AddComma()
                    .WriteOperand(ymir::scu::ToString(inst.operation.d1BusDst));
                break;
            }
            break;
        }

        case InstrKind::MVI: {
            SetMnemonic("MVI ");
            auto imm = inst.mvi.imm;
            switch (inst.mvi.dst) {
            case ymir::scu::SCUDSPInstruction::MVIDst::MC0:
            case ymir::scu::SCUDSPInstruction::MVIDst::MC1:
            case ymir::scu::SCUDSPInstruction::MVIDst::MC2:
            case ymir::scu::SCUDSPInstruction::MVIDst::MC3:
                ImmediateWord(imm & 0x3F);
                break;
            case ymir::scu::SCUDSPInstruction::MVIDst::RX:
                ImmediateWord(imm);
                break;
            case ymir::scu::SCUDSPInstruction::MVIDst::P:
                ImmediateSignedWord(imm);
                break;
            case ymir::scu::SCUDSPInstruction::MVIDst::RA0:
            case ymir::scu::SCUDSPInstruction::MVIDst::WA0:
                ImmediateWord((imm << 2) & 0x7FF'FFFC);
                break;
            case ymir::scu::SCUDSPInstruction::MVIDst::LOP:
                ImmediateWord(imm & 0xFFF);
                break;
            case ymir::scu::SCUDSPInstruction::MVIDst::PC:
                ImmediateWord(imm & 0xFF);
                break;
            default:
                ImmediateSignedWord(imm);
                break;
            }
            AddComma().WriteOperand(ymir::scu::ToString(inst.mvi.dst));
            if (inst.mvi.cond != ymir::scu::SCUDSPInstruction::Cond::None) {
                AddComma().SetCondition(inst.mvi.cond);
            }
            break;
        }

        case InstrKind::DMA: {
            SetMnemonic(inst.dma.hold ? "DMAH " : "DMA ");
            if (inst.dma.toD0) {
                ReadOperand(ymir::scu::ToString(inst.dma.ramOp));
            } else {
                ReadOperand("D0");
            }
            AddComma();
            if (inst.dma.toD0) {
                WriteOperand("D0");
            } else {
                WriteOperand(ymir::scu::ToString(inst.dma.ramOp));
            }
            AddComma();
            if (inst.dma.countType) {
                std::string reg = fmt::format("M{}{}", (inst.dma.count.ct < 4 ? "" : "C"), inst.dma.count.ct & 3);
                ReadOperand(reg);
            } else {
                ImmediateByte(inst.dma.count.imm);
            }
            break;
        }

        case InstrKind::JMP: {
            SetMnemonic("JMP ");
            if (inst.jmp.cond != ymir::scu::SCUDSPInstruction::Cond::None) {
                SetCondition(inst.jmp.cond).AddComma();
            }
            ImmediateByte(inst.jmp.target);
            break;
        }

        case InstrKind::LPS:
            SetMnemonic("LPS");
            break;

        case InstrKind::BTM:
            SetMnemonic("BTM");
            break;

        case InstrKind::END:
            SetMnemonic("END");
            break;

        case InstrKind::ENDI:
            SetMnemonic("ENDI");
            break;

        default:
            dis.IllegalMnemonic();
            break;
        }

        return *this;
    }

    SCUDSPDisassembler &Decode(uint32 opcode) {
        const auto &instruction = ymir::scu::Disassemble(opcode);
        SetAddress().SetOpcode(opcode).ProcessInstruction(instruction);
        dis.NewLine();
        ++addr;
        return *this;
    }

    Disassembler &dis;
    uint8 addr = 0;
};

using SCUDSPOpcode = uint32;
using SCUDSPOpcodeFetcher = IOpcodeFetcher<SCUDSPOpcode>;
using CommandLineSCUDSPOpcodeFetcher = CommandLineOpcodeFetcher<SCUDSPOpcode>;
using StreamSCUDSPOpcodeFetcher = StreamOpcodeFetcher<SCUDSPOpcode>;

bool DisassembleSCUDSP(Disassembler &dis, std::string_view origin,
                       const std::vector<std::string> &args,
                       const std::string &inputFile) {
    auto maybeAddress = ParseHex<uint8>(origin);
    if (!maybeAddress) {
        fmt::println("Invalid origin address: {}", origin);
        return false;
    }

    SCUDSPDisassembler scuDis{dis};
    scuDis.addr = *maybeAddress;

    auto fetcher =
        MakeFetcher<SCUDSPOpcodeFetcher, CommandLineSCUDSPOpcodeFetcher, StreamSCUDSPOpcodeFetcher>(args, inputFile);
    if (!fetcher) {
        return false;
    }

    bool running = true;
    const auto handleResult = [&](auto &&value) {
        using T = std::decay_t<decltype(value)>;
        if constexpr (std::is_same_v<T, SCUDSPOpcode>) {
            scuDis.Decode(value);
        } else if constexpr (std::is_same_v<T, OpcodeFetchError>) {
            fmt::println("{}", value.message);
            running = false;
        } else if constexpr (std::is_same_v<T, OpcodeFetchEnd>) {
            running = false;
        }
    };

    while (running) {
        auto result = fetcher->Fetch();
        std::visit(handleResult, result);
    }

    return true;
}

#include "ReCraftCore.hpp"
#include "client/gui/screens/GuiInGame.hpp"
#include "client/gui/screens/SelectWorldScreen.hpp"
#include "client/gui/screens/StartScreen.hpp"
#include "client/renderer/block/ModelBakery.hpp"
#include "client/renderer/block/ModelBlock.hpp"
#include "input/InputManager.hpp"

bool showDebugInfo = true;

ReCraftCore* ReCraftCore::m_theReCraftCore = nullptr;
const std::string ReCraftCore::m_root = "sdmc:/3ds/recraft";

ReCraftCore::ReCraftCore() {
    // Ensure root directory exists
    {
        std::error_code errCode;
        std::filesystem::create_directories(m_root, errCode);
    }

    m_theReCraftCore = this;
    m_currentGameState = GameState::SelectWorld;

    // Graphics & system initialization
    gfxInitDefault();
    osSetSpeedupEnable(true);  // Enable N3DS overclocking if available
    gfxSet3D(true);
    romfsInit();

    SuperChunk_InitPools();
    SaveManager::InitFileSystem();
    BlockRegistry::GetInstance().Init();

    // Setup worker handlers
    m_chunkWorker.AddHandler(WorkerItemType::PolyGen, {&PolyGen_GeneratePolygons, nullptr, true});
    sino_init();

    // Initialize world and player
    m_world = new World(&m_chunkWorker.GetQueue());
    m_player = new Player(m_world);

    // Initialize world generators
    m_flatGen.Init(m_world);
    m_smeaGen.Init(m_world);
    m_emptyGen.Init(m_world);

    // Asset loading setup
    m_AssetMgr.AppendPath("romfs:");
    m_AssetMgr.AppendPath("sdmc:/3ds/recraft");

    auto fontPtr = Iron::Font::New();
    fontPtr->LoadBMF("romfs:/assets/minecraft/textures/font/ascii.png");
    m_AssetMgr.Add("font", fontPtr);

    m_AssetMgr.AutoLoad("GuiTexture_Widgets", "romfs:/assets/minecraft/textures/gui/widgets.png");
    m_AssetMgr.AutoLoad("GuiTexture_DefaultBG", "romfs:/assets/minecraft/textures/gui/options_background.png");
    auto* bgTex = m_AssetMgr.Get<Amy::Texture>("GuiTexture_DefaultBG");
    if (bgTex) bgTex->Wrap(Amy::Texture::Repeat);

    // Renderer and UI setup
    m_renderer = new Renderer(m_world, m_player, &m_chunkWorker.GetQueue());
    m_debugUI = new DebugUI();

    SetScreen(new StartTopScreen, true);
    SetScreen(new StartBotScreen, false);

    // Save manager setup
    m_savemgr.Init(m_player, m_world);
    m_chunkWorker.AddHandler(WorkerItemType::Load, {SaveManager::LoadChunkCallback, &m_savemgr, true});
    m_chunkWorker.AddHandler(WorkerItemType::Save, {SaveManager::SaveChunkCallback, &m_savemgr, true});

    // Model baking
    auto* bakery = new ModelBakery("romfs:/assets/minecraft");
    bakery->bakeAll();

    ResourceLocation resLoc("minecraft", "stone");
    ModelResourceLocation mrl(resLoc, "normal");
    const BakedBlockVariant* variant = bakery->getVariant(mrl);
    if (variant && variant->rotation.has_value()) {
        const ModelRotation& rot = variant->rotation.value();
        // Rotation data available — could be used later
        (void)rot; // Suppress unused warning
    }

    // Register debug UI callback
    ImGuiManager::GetInstance()->RegisterCallback("DebugUI", [=, this]() {
        ImGui::Begin("Game Info");
        ImGui::Text("Performance");
        ImGui::Spacing();
        ImGui::Text("FPS: %.2f, DT: %.3f", 1000.f / Delta(), Delta());
        ImGui::Text("CPU: %5.2f%%", C3D_GetProcessingTime() * 6.f);
        ImGui::Text("GPU: %5.2f%%", C3D_GetDrawingTime() * 6.f);
        ImGui::Text("Buffer: %5.2f%%", C3D_GetCmdBufUsage() * 100.f);

#ifndef NDEBUG
        ImGui::Text("Heap: %s [%d] Allocations", Amy::Utils::FormatBytes(Amy::Memory::GetTotalAllocated()).c_str(),
                    Amy::Memory::GetAllocationCount());
        ImGui::Text("malloc: %lld - free: %lld\ncalloc: %lld - realloc: %lld\nmemalign: "
                    "%lld",
                    Amy::Memory::GetMetrics()._malloc, Amy::Memory::GetMetrics()._free,
                    Amy::Memory::GetMetrics()._calloc, Amy::Memory::GetMetrics()._realloc,
                    Amy::Memory::GetMetrics()._memalign);
#endif

        ImGui::Text("Linear Heap: %s", Amy::Utils::FormatBytes(linearSpaceFree()).c_str());
        ImGui::Separator();
        ImGui::Text("Amethyst");
        ImGui::Text("VI: [%d, %d]", Amy::Iron::VerticesDrawn(), Amy::Iron::IndicesDrawn());
        ImGui::Text("Drawcalls: %d", Amy::Iron::GetDrawCalls());
        ImGui::Separator();
        ImGui::Text("Player");
        ImGui::Spacing();
        ImGui::Text("Position: %.2f, %.2f, %.2f", m_player->position.x, m_player->position.y, m_player->position.z);
        ImGui::Text("Spawn: %.2f, %.2f, %.2f", m_player->spawnPos.x, m_player->spawnPos.y, m_player->spawnPos.z);
        ImGui::Text("HP: %i", m_player->hp);
        ImGui::Text("Hunger: %i (Timer: %i)", m_player->hunger, m_player->hungertimer);
        ImGui::Text("Velocity Y: %.3f, RndY: %.3f", m_player->velocity.y, m_player->rndy);
        ImGui::Spacing();
        ImGui::Text("Move Pad: u%i d%i l%i r%i", m_player->getCtrlMove()->up, m_player->getCtrlMove()->down,
                    m_player->getCtrlMove()->left, m_player->getCtrlMove()->right);
        ImGui::Separator();
        ImGui::Text("ModelBakery");
        ImGui::Spacing();
        for (const auto& [key, val] : bakery->getAllVariants())
            ImGui::Text("Baked: %s", key.c_str());
        ImGui::End();
    });
}

ReCraftCore::~ReCraftCore() {
    ImGuiManager::GetInstance()->UnregisterCallback("DebugUI");

    if (m_currentGameState == GameState::Playing)
        ExitSinglePlayer();
    else if (m_currentGameState == GameState::Playing_OnLine)
        ExitMultiplayer();

    m_savemgr.~SaveManager();
    SuperChunk_DeinitPools();
    delete m_debugUI;
    delete m_world;
    sino_exit();
    delete m_renderer;
    m_chunkWorker.~ChunkWorker();
    BlockRegistry::GetInstance().~BlockRegistry();
    romfsExit();
    gfxExit();
}

void ReCraftCore::InitSinglePlayer(char* path, char* name, const WorldGenType* worldType, Gamemode mode,
                                   bool newWorld) {
    m_chunkWorker.AddHandler(WorkerItemType::BaseGen, {&SuperFlatGen::Generate, &m_flatGen, true});
    m_chunkWorker.AddHandler(WorkerItemType::BaseGen, {&SmeaGen::Generate, &m_smeaGen, true});

    strcpy(m_world->name, name);
    m_world->genSettings.type = *worldType;
    m_savemgr.Load(path);

    m_chunkWorker.SetHandlerActive(WorkerItemType::BaseGen, &m_flatGen,
                                   m_world->genSettings.type == WorldGenType::SuperFlat);
    m_chunkWorker.SetHandlerActive(WorkerItemType::BaseGen, &m_smeaGen,
                                   m_world->genSettings.type == WorldGenType::Smea);

    // Update chunk cache origin
    m_world->cacheTranslationX = WorldToChunkCoord(FastFloor(m_player->position.x));
    m_world->cacheTranslationZ = WorldToChunkCoord(FastFloor(m_player->position.z));

    // Preload chunk cache
    int i = 0;
    while (i < World::ChunkCacheSize) {
        int j = 0;
        while (j < World::ChunkCacheSize) {
            m_world->columnCache[i][j] = m_world->LoadChunk(
                i - World::ChunkCacheSize / 2 + m_world->cacheTranslationX,
                j - World::ChunkCacheSize / 2 + m_world->cacheTranslationZ);
            ++j;
        }
        ++i;
    }

    // Run initial ticks
    int tickCount = 0;
    while (tickCount < 3) {
        while (m_chunkWorker.IsWorking() || !m_chunkWorker.GetQueue().queue.empty()) {
            svcSleepThread(50000000); // ~1 tick delay
        }
        m_world->Tick();
        ++tickCount;
    }

    if (newWorld) {
        int highestY = 0;
        int x = -1;
        while (x <= 1) {
            int z = -1;
            while (z <= 1) {
                int h = m_world->GetHeight(x, z);
                if (h > highestY) highestY = h;
                ++z;
            }
            ++x;
        }

        m_player->gamemode = mode;
        m_player->hunger = 20;
        m_player->hp = 20;
        m_player->position.y = static_cast<float>(highestY) + 0.2f;
    }

    SetScreen(new GuiInGameTop, true);
    SetScreen(new GuiInGameBot, false);
    m_currentGameState = GameState::Playing;
}

void ReCraftCore::RunSinglePlayer() {
    while (m_timeAccum >= 20.0f) {
        m_world->Tick();
        m_timeAccum -= 20.0f;
    }

    m_player->UpdateMovement(m_debugUI, Delta() * 0.001f);
    m_world->UpdateChunkCache(
        WorldToChunkCoord(FastFloor(m_player->position.x)),
        WorldToChunkCoord(FastFloor(m_player->position.z)));
}

void ReCraftCore::ExitSinglePlayer() {
    if (m_world)
        m_world->Release(&m_chunkWorker, &m_savemgr);
    SetScreen(new StartTopScreen, true);
    SetScreen(new SelectWorldBotScreen, false);
}

void ReCraftCore::InitMultiPlayer() {
    m_chunkWorker.AddHandler(WorkerItemType::BaseGen, {&EmptyGen::Generate, &m_emptyGen, true});

    SwkbdState keyboard;
    char username[256];
    swkbdInit(&keyboard, SWKBD_TYPE_NORMAL, 2, -1);
    swkbdSetHintText(&keyboard, "Username");
    if (swkbdInputText(&keyboard, username, sizeof(username)) != SWKBD_BUTTON_CONFIRM || username[0] == '\0') {
        SetScreen(new StartBotScreen, false);
        return;
    }
    m_mcBridge.SetUsername(username);

    char ipAddr[256];
    swkbdInit(&keyboard, SWKBD_TYPE_NORMAL, 2, -1);
    swkbdSetHintText(&keyboard, "Server IP (xxx.xxx.xxx.xxx)");
    if (swkbdInputText(&keyboard, ipAddr, sizeof(ipAddr)) != SWKBD_BUTTON_CONFIRM || ipAddr[0] == '\0') {
        SetScreen(new StartBotScreen, false);
        return;
    }
    m_mcBridge.SetIPAddress(ipAddr);

    m_mcBridge.connect();
    m_world->genSettings.type = WorldGenType::Empty;
    m_player->hunger = 20;
    m_player->hp = 20;
    m_player->gamemode = Gamemode::Creative;

    m_chat = new GuiChat(m_mcBridge.getClient()->GetDispatcher(), m_mcBridge.getClient());
    m_networkWorld = new NetworkWorld(m_world, m_mcBridge.getClient()->GetDispatcher());

    m_chunkWorker.SetHandlerActive(WorkerItemType::BaseGen, &m_emptyGen, true);

    // Chunk cache init
    m_world->cacheTranslationX = WorldToChunkCoord(FastFloor(m_player->position.x));
    m_world->cacheTranslationZ = WorldToChunkCoord(FastFloor(m_player->position.z));

    int row = 0;
    while (row < World::ChunkCacheSize) {
        int col = 0;
        while (col < World::ChunkCacheSize) {
            m_world->columnCache[row][col] = m_world->LoadChunk(
                row - World::ChunkCacheSize / 2 + m_world->cacheTranslationX,
                col - World::ChunkCacheSize / 2 + m_world->cacheTranslationZ);
            ++col;
        }
        ++row;
    }

    int ticks = 0;
    while (ticks < 3) {
        while (m_chunkWorker.IsWorking() || !m_chunkWorker.GetQueue().queue.empty()) {
            svcSleepThread(50000000);
        }
        m_world->Tick();
        ++ticks;
    }

    m_player->SetPos(mc::Vector3f(0, 63, 0));
    m_mcBridge.startBackgroundThread();

    SetScreen(new GuiInGameTop, true);
    SetScreen(new GuiInGameBot, false);
    m_currentGameState = GameState::Playing_OnLine;
}

void ReCraftCore::ExitMultiplayer() {
    m_mcBridge.stopBackgroundThread();
    m_mcBridge.disconnect();
    SetScreen(new StartTopScreen, true);
    SetScreen(new SelectWorldBotScreen, false);
}

void ReCraftCore::RunMultiPlayer() {
    if (m_mcBridge.isConnected()) {
        m_mcBridge.withClient([&](mc::core::Client* client, mc::protocol::packets::PacketDispatcher* dispatcher) {
            mc::protocol::packets::out::PlayerPositionAndLookPacket packet(
                ToVector3d(m_player->position),
                RAD_TO_DEG(m_player->yRot), RAD_TO_DEG(m_player->xRot),
                m_player->onGround);
            client->GetConnection()->SendPacket(&packet);

            bool showChat = true;
            m_chat->Render(&showChat);
        });
    }

    while (m_timeAccum >= 20.0f) {
        m_world->Tick();
        m_timeAccum -= 20.0f;
    }

    m_player->UpdateMovement(m_debugUI, Delta() * 0.001f);
    m_world->UpdateChunkCache(
        WorldToChunkCoord(FastFloor(m_player->position.x)),
        WorldToChunkCoord(FastFloor(m_player->position.z)));
}

void ReCraftCore::Main() {
    m_renderer->Render(m_debugUI);

    if (Input::isKeyDown(KEY_START)) {
        if (m_currentGameState == GameState::SelectWorld) {
            Exit();
        } else if (m_currentGameState == GameState::Playing) {
            ExitSinglePlayer();
            m_currentGameState = GameState::SelectWorld;
        } else if (m_currentGameState == GameState::Playing_OnLine) {
            ExitMultiplayer();
            m_currentGameState = GameState::SelectWorld;
        }
    }

    Input::getMgr()->poll();
    m_timeAccum += Delta();

    // Top screen update
    if (TopScreen) {
        m_bTopUsingCurrScreen = true;
        TopScreen->UpdateEvents();
        m_bTopUsingCurrScreen = false;

        if (m_bTopHaveQueuedScreen) {
            SetScreen(m_pTopQueuedScreen, true);
            m_pTopQueuedScreen = nullptr;
            m_bTopHaveQueuedScreen = false;
        }
    }

    // Bottom screen update
    if (BotScreen) {
        m_bBotUsingCurrScreen = true;
        BotScreen->UpdateEvents();
        m_bBotUsingCurrScreen = false;

        if (m_bBotHaveQueuedScreen) {
            SetScreen(m_pBotQueuedScreen, false);
            m_pBotQueuedScreen = nullptr;
            m_bBotHaveQueuedScreen = false;
        }
    }

    switch (m_currentGameState) {
        case GameState::Playing:
            RunSinglePlayer();
            break;
        case GameState::Playing_OnLine:
            RunMultiPlayer();
            break;
        case GameState::SelectWorld:
            // WorldSelect_Update(m_player);
            break;
        default:
            break;
    }
}

void ReCraftCore::SetScreen(Screen* pScreen, bool top) {
    bool& usingCurr = top ? m_bTopUsingCurrScreen : m_bBotUsingCurrScreen;
    bool& haveQueued = top ? m_bTopHaveQueuedScreen : m_bBotHaveQueuedScreen;
    Screen*& queued = top ? m_pTopQueuedScreen : m_pBotQueuedScreen;
    Screen*& current = top ? TopScreen : BotScreen;

    int width = top ? static_cast<int>(400 * 0.5f) : static_cast<int>(320 * 0.5);
    int height = static_cast<int>(240 * 0.5);

    if (usingCurr) {
        haveQueued = true;
        queued = pScreen;
    } else if (!pScreen || !pScreen->IsErrorScreen()) {
        if (current) {
            current->Removed();
            delete current;
        }
        current = pScreen;
        if (pScreen) {
            pScreen->Init(this, width, height);
        }
    } else {
        delete pScreen;
    }
}

