    void ToolTip::Show(Control* owner)
    {
        sf::Vector2f pos;
        Alignment align = Alignment::Left;

        if (owner)
        {
            auto bounds = owner->GetLocalBounds();
            pos.x = static_cast<float>(static_cast<int>(bounds.size.x / 2));
            pos.y = static_cast<float>(static_cast<int>(bounds.size.y / 2));
            align = Alignment::Center;
        }

        Show(pos, align);
    }

    void ToolTip::Show(const sf::Vector2f position, const Alignment alignment)
    {
        if (alignment == Alignment::Center || alignment == Alignment::Right)
        {
            Invalidate();
            if (alignment == Alignment::Center)
                SetOrigin(m_box.GetSize().x * 0.5f, m_box.GetSize().y * 0.5f);
            else
                SetOrigin(m_box.GetSize().x, m_box.GetSize().y);
        }
        else
            SetOrigin({});

        SetPosition(position);
        Show();
    }

    void ToolTip::Show()
    {
        m_activeTime = sf::Time::Zero;
        Invalidate();
    }

