    }

    const sf::Time& ToolTip::GetDuration() const
    {
        return m_lifeSpan;
    }

    void ToolTip::SetDuration(const sf::Time& span)
    {
        if (m_lifeSpan != span)
        {
            bool wasVisible = m_activeTime < m_lifeSpan;
            m_lifeSpan = span;
            m_activeTime = wasVisible ? sf::Time::Zero : span;
        }
    }

