    {
        if (m_backColor != color)
        {
            m_backColor = color;
            Invalidate();
        }
    }

    const sf::Color& ToolTip::GetContainerOutlineColor() const
    {
        return m_edgeColor;
    }

    void ToolTip::SetContainerOutlineColor(const sf::Color& color)
    {
        if (m_edgeColor != color)
        {
            m_edgeColor = color;
            Invalidate();
        }
    }

    float ToolTip::GetContainerOutlineThickness() const
    {
        return m_edgeWidth;
    }

    void ToolTip::SetContainerOutlineThickness(const float width)
    {
        if (m_edgeWidth != width)
        {
            m_edgeWidth = width;
            Invalidate();
        }
    }

    RenderStates ToolTip::Render(RenderSurface& target, const RenderStates state) const
    {
        if (IsVisible() && !GetString().isEmpty())
        {
            RenderStates localState = state;
            localState.transform *= GetTransform();
            target.Render(m_box, localState);
        }
        return Label::Render(target, state);
    }

    void ToolTip::Update(const double dt)
    {
        Label::Update(dt);
        if (m_activeTime < m_lifeSpan)
            m_activeTime += sf::milliseconds(static_cast<int>(dt));

        if (IsVisible())
            Invalidate();
    }

    void ToolTip::Invalidate()
    {
        Label::Invalidate();

        auto textMetrics = Text::GetLocalBounds();
        auto totalSize   = sf::Vector2f(textMetrics.size.x + m_spacing.x * 2,
                                        textMetrics.size.y + m_spacing.y * 2);

        m_box.SetSize({ std::ceil(totalSize.x), std::ceil(totalSize.y) });
        m_box.SetPosition({ 0.0f, std::ceil(m_spacing.y * 1.5f) });
        m_box.SetFillColor(m_backColor);
        m_box.SetOutlineColor(m_edgeColor);
        m_box.SetOutlineThickness(m_edgeWidth);

        SetVisible(m_activeTime < m_lifeSpan);
    }
}

#include "Distance/DistLine3Circle3.h"
#include "ThirdParty/GTEngine/Mathematics/GteDistLine3Circle3.h"
