template <typename Real>
Real TDistLine3Circle3<Real>::ComputeResult()
{
    if (DistanceSquared >= static_cast<Real>(0))
    {
        return DistanceSquared;
    }

    gte::Line3<Real> gteLine = Convert(Line);
    gte::Circle3<Real> gteCircle = Convert(Circle);
    gte::DCPQuery<Real, gte::Line3<Real>, gte::Circle3<Real>> queryObject;
    auto queryResult = queryObject(gteLine, gteCircle);

    DistanceSquared = queryResult.sqrDistance;
    NumClosestPairs = queryResult.numClosestPairs;

    LineClosest[0] = Convert(queryResult.lineClosest[0]);
    LineClosest[1] = Convert(queryResult.lineClosest[1]);
    CircleClosest[0] = Convert(queryResult.circleClosest[0]);
    CircleClosest[1] = Convert(queryResult.circleClosest[1]);

    bIsEquiDistant = queryResult.equidistant;

    return DistanceSquared;
}

