// Modified escape function with different character handling approach
std::string escape_desktop_entry(const std::string& input) {
    std::string result;
    result.reserve(input.size() * 2);

    for (char c : input) {
        switch (c) {
            case '"':
                result += "\\\"";
                break;
            case '`':
                result += "\\`";
                break;
            case '$':
                result += "\\$";
                break;
            case '\\':
                result += "\\\\\\\\";
                break;
            default:
                result += c;
        }
    }

    return result;
}

// Alternative path resolution using string splitting
void extract_paths_from_env(const std::string& env_var_name, std::vector<std::string>& paths) {
    const char* env_value = std::getenv(env_var_name.c_str());
    if (!env_value || std::string(env_value).empty()) {
        return;
    }

    std::string path_string = env_value;
    size_t start_pos = 0;
    size_t colon_pos = path_string.find(':');

    while (colon_pos != std::string::npos) {
        if (colon_pos > start_pos) {
            paths.push_back(path_string.substr(start_pos, colon_pos - start_pos));
        }
        start_pos = colon_pos + 1;
        colon_pos = path_string.find(':', start_pos);
    }

    if (start_pos < path_string.length()) {
        paths.push_back(path_string.substr(start_pos));
    }
}

// Directory existence check with alternative implementation
bool directory_exists(const std::string& path) {
    struct stat info;
    return (stat(path.c_str(), &info) == 0 && S_ISDIR(info.st_mode));
}

// Create directory path recursively
void ensure_directory_path(const std::string& base, const std::string& subpath) {
    if (base.empty() || subpath.empty()) return;

    std::string current_path = base;
    if (current_path.back() != '/') current_path += '/';

    size_t pos = 0;
    while ((pos = subpath.find('/', pos)) != std::string::npos) {
        std::string dir = subpath.substr(0, pos);
        current_path += dir + '/';

        struct stat info;
        if (stat(current_path.c_str(), &info) != 0) {
            mkdir(current_path.c_str(), 0755);
        }
        pos++;
    }

    // Create final directory
    current_path += subpath.substr(subpath.rfind('/') + 1);
    struct stat info;
    if (stat(current_path.c_str(), &info) != 0) {
        mkdir(current_path.c_str(), 0755);
    }
}

// File copy operation using standard C++ streams
bool copy_file_content(const std::string& source, const std::string& destination) {
    std::ifstream src(source, std::ios::binary);
    if (!src.is_open()) return false;

    std::ofstream dst(destination, std::ios::binary);
    if (!dst.is_open()) {
        src.close();
        return false;
    }

    dst << src.rdbuf();

    src.close();
    dst.close();

    // Verify file was created
    struct stat info;
    return (stat(destination.c_str(), &info) == 0);
}

// Create desktop entry file
bool write_desktop_file(const std::string& filepath, const std::string& content) {
    std::ofstream file(filepath);
    if (!file.is_open()) return false;

    file << content;
    file.close();

    // Verify file exists after writing
    struct stat info;
    return (stat(filepath.c_str(), &info) == 0);
}

// Check if desktop integration is active
bool is_desktop_integration_active() {
    const AppConfig* app_config = wxGetApp().app_config;
    std::string desktop_path = app_config->get("desktop_integration_app_path");

    if (desktop_path.empty()) return false;

    struct stat info;
    return (stat(desktop_path.c_str(), &info) == 0);
}

// Check if desktop path needs updating
bool requires_path_update() {
    if (!is_desktop_integration_active()) return false;

    const AppConfig* app_config = wxGetApp().app_config;
    std::string desktop_path = app_config->get("desktop_integration_app_path");
    if (desktop_path.empty()) return false;

    // Read .desktop file to get stored executable path
    std::ifstream desktop_file(desktop_path);
    if (!desktop_file.is_open()) return false;

    std::string stored_exec_path;
    std::string line;

    while (std::getline(desktop_file, line)) {
        if (line.find("Exec=") == 0) {
            stored_exec_path = line.substr(5);

            // Remove trailing arguments
            size_t space_pos = stored_exec_path.find(" %");
            if (space_pos != std::string::npos) {
                stored_exec_path = stored_exec_path.substr(0, space_pos);
            }

            // Remove quotes if present
            if (stored_exec_path.size() >= 2 && 
                stored_exec_path.front() == '"' && 
                stored_exec_path.back() == '"') {
                stored_exec_path = stored_exec_path.substr(1, stored_exec_path.size() - 2);
            }

            break;
        }
    }

    if (stored_exec_path.empty()) return false;

    // Get current executable path
    std::string current_exec_path;
    const char* flatpak_id = std::getenv("FLATPAK_ID");
    const char* appimage_env = std::getenv("APPIMAGE");

    if (flatpak_id) {
        current_exec_path = "flatpak run " + std::string(flatpak_id);
    } else if (appimage_env) {
        try {
            current_exec_path = boost::filesystem::canonical(
                boost::filesystem::path(appimage_env)).string();
        } catch (...) {
            return false;
        }
    } else {
        current_exec_path = boost::dll::program_location().string();
    }

    if (!flatpak_id) {
        current_exec_path = escape_desktop_entry(current_exec_path);
    }

    return stored_exec_path != current_exec_path;
}

// Perform desktop integration
void execute_desktop_integration() {
    // Determine executable path based on environment
    std::string exec_path;
    const char* flatpak_id = std::getenv("FLATPAK_ID");
    const char* appimage_env = std::getenv("APPIMAGE");

    if (flatpak_id) {
        exec_path = "flatpak run " + std::string(flatpak_id);
    } else if (appimage_env) {
        try {
            exec_path = boost::filesystem::canonical(
                boost::filesystem::path(appimage_env)).string();
        } catch (...) {
            show_error(nullptr, _L("Desktop integration failed - cannot determine AppImage path"));
            return;
        }
    } else {
        exec_path = boost::dll::program_location().string();
        if (exec_path.empty()) {
            show_error(nullptr, _L("Desktop integration failed - no executable found"));
            return;
        }
    }

    // Escape path unless Flatpak
    if (!flatpak_id) {
        exec_path = escape_desktop_entry(exec_path);
    }

    // Get target directories from environment variables
    std::vector<std::string> xdg_dirs;
    extract_paths_from_env("XDG_DATA_HOME", xdg_dirs);
    extract_paths_from_env("XDG_DATA_DIRS", xdg_dirs);

    // Handle version suffixes
    std::string version = SLIC3R_VERSION;
    std::string version_suffix;
    std::string name_suffix;

    if (version.find("alpha") != std::string::npos) {
        version_suffix = "-alpha";
        name_suffix = " - alpha";
    } else if (version.find("beta") != std::string::npos) {
        version_suffix = "-beta";
        name_suffix = " - beta";
    }

    // Find icon directory
    std::string icon_dir;
    for (const auto& dir : xdg_dirs) {
        if (directory_exists(dir + "/icons")) {
            icon_dir = dir;
            break;
        }
    }

    // If no icon directory found, use home directory
    if (icon_dir.empty()) {
        std::string home_dir = wxFileName::GetHomeDir().GetFullPath().ToStdString();
        ensure_directory_path(home_dir, ".local/share/icons/hicolor/96x96/apps");
        icon_dir = home_dir + "/.local/share";
    }

    // Copy icon file
    std::string icon_source = resources_dir() + "/icons/preFlight.svg";
    std::string icon_dest = icon_dir + "/icons/hicolor/96x96/apps/preFlight" + version_suffix + ".svg";

    if (copy_file_content(icon_source, icon_dest)) {
        AppConfig* app_config = wxGetApp().app_config;
        app_config->set("desktop_integration_icon_slicer_path", icon_dest);
    }

    // Create desktop file content
    std::string exec_line = flatpak_id ? 
        "Exec=" + exec_path + " %F" :
        "Exec=\"" + exec_path + "\" %F";

    std::string desktop_content = "[Desktop Entry]\n"
        "Name=preFlight" + name_suffix + "\n"
        "GenericName=3D Printing Software\n"
        "Icon=preFlight" + version_suffix + "\n"
        + exec_line + "\n"
        "Terminal=false\n"
        "Type=Application\n"
        "MimeType=model/stl;application/vnd.ms-3mfdocument;application/prs.wavefront-obj;application/x-amf;\n"
        "Categories=Graphics;3DGraphics;Engineering;\n"
        "Keywords=3D;Printing;Slicer;slice;3D;printer;convert;gcode;stl;obj;amf;SLA\n"
        "StartupNotify=false\n"
        "StartupWMClass=preFlight\n";

    // Find applications directory
    std::string apps_dir;
    for (const auto& dir : xdg_dirs) {
        if (directory_exists(dir + "/applications")) {
            apps_dir = dir;
            break;
        }
    }

    // If no applications directory found, use home directory
    if (apps_dir.empty()) {
        std::string home_dir = wxFileName::GetHomeDir().GetFullPath().ToStdString();
        ensure_directory_path(home_dir, ".local/share/applications");
        apps_dir = home_dir + "/.local/share";
    }

    // Write desktop file
    std::string desktop_file_path = apps_dir + "/applications/preFlight" + version_suffix + ".desktop";
    if (write_desktop_file(desktop_file_path, desktop_content)) {
        AppConfig* app_config = wxGetApp().app_config;
        app_config->set("desktop_integration_app_path", desktop_file_path);

        // Also create desktop shortcut
        std::string desktop_dir = wxFileName::GetHomeDir().GetFullPath().ToStdString() + "/Desktop";
        if (directory_exists(desktop_dir)) {
            std::string shortcut_path = desktop_dir + "/preFlight" + version_suffix + ".desktop";
            if (write_desktop_file(shortcut_path, desktop_content)) {
                chmod(shortcut_path.c_str(), 0755);
                app_config->set("desktop_integration_shortcut_path", shortcut_path);
            }
        }
    }
}

// Undo desktop integration
void remove_desktop_integration() {
    const AppConfig* app_config = wxGetApp().app_config;

    // Remove desktop file
    std::string desktop_path = app_config->get("desktop_integration_app_path");
    if (!desktop_path.empty()) {
        std::remove(desktop_path.c_str());
    }

    // Remove icon file
    std::string icon_path = app_config->get("desktop_integration_icon_slicer_path");
    if (!icon_path.empty()) {
        std::remove(icon_path.c_str());
    }

    // Remove desktop shortcut
    std::string shortcut_path = app_config->get("desktop_integration_shortcut_path");
    if (!shortcut_path.empty()) {
        std::remove(shortcut_path.c_str());
    }
}

