class TransformMessage::Impl : public MessageImpl {
 public:
  Impl();
  Impl(TimeNano timestamp, std::string parent_id, std::string child_id,
       Vector3 pos, Quaternion orient);
  ~Impl() override {}

  Vector3 GetPosition() const;
  Quaternion GetOrientation() const;
  std::string GetParentFrame() const;
  std::string GetChildFrame() const;

  std::string Serialize() override;
  void Deserialize(const std::string& raw_data) override;

  MSGPACK_DEFINE_MAP(time_stamp, parent_frame, child_frame, translation_vec,
                     rotation_quat);

 private:
  TimeNano time_stamp;
  std::string parent_frame;
  std::string child_frame;
  Vector3Msgpack translation_vec;
  QuaternionMsgpack rotation_quat;

  // Helper to extract data from msgpack object
  void unpack_from_msgpack(const msgpack::object& obj);
};

// Public constructors
TransformMessage::TransformMessage()
    : Message(std::make_shared<TransformMessage::Impl>()) {}

TransformMessage::TransformMessage(
    TimeNano timestamp, std::string parent_id, std::string child_id,
    Vector3 position, Quaternion orientation)
    : Message(std::make_shared<TransformMessage::Impl>(
          timestamp, parent_id, child_id, position, orientation)) {}

TransformMessage::~TransformMessage() {}

// Public getters — delegate through pimpl
Vector3 TransformMessage::GetTranslation() const {
  auto* impl_ptr = static_cast<Impl*>(pimpl_.get());
  return impl_ptr->GetPosition();
}

Quaternion TransformMessage::GetRotation() const {
  auto* impl_ptr = static_cast<Impl*>(pimpl_.get());
  return impl_ptr->GetOrientation();
}

std::string TransformMessage::GetParentFrameId() const {
  auto* impl_ptr = static_cast<Impl*>(pimpl_.get());
  return impl_ptr->GetParentFrame();
}

std::string TransformMessage::GetChildFrameId() const {
  auto* impl_ptr = static_cast<Impl*>(pimpl_.get());
  return impl_ptr->GetChildFrame();
}

std::string TransformMessage::Serialize() const {
  auto* impl_ptr = static_cast<Impl*>(pimpl_.get());
  return impl_ptr->Serialize();
}

void TransformMessage::Deserialize(const std::string& buffer) {
  auto* impl_ptr = static_cast<Impl*>(pimpl_.get());
  impl_ptr->Deserialize(buffer);
}

// Implementation details of Impl
TransformMessage::Impl::Impl() : MessageImpl(MessageType::kTransform) {}

TransformMessage::Impl::Impl(TimeNano timestamp, std::string parent_id,
                             std::string child_id, Vector3 position,
                             Quaternion orientation)
    : MessageImpl(MessageType::kTransform),
      time_stamp(timestamp),
      parent_frame(std::move(parent_id)),
      child_frame(std::move(child_id)),
      translation_vec(position),
      rotation_quat(orientation) {}

Vector3 TransformMessage::Impl::GetPosition() const {
  return translation_vec.ToVector3();
}

Quaternion TransformMessage::Impl::GetOrientation() const {
  return rotation_quat.ToQuaternion();
}

std::string TransformMessage::Impl::GetParentFrame() const {
  return parent_frame;
}

std::string TransformMessage::Impl::GetChildFrame() const {
  return child_frame;
}

std::string TransformMessage::Impl::Serialize() {
  std::ostringstream oss;
  msgpack::packer<std::ostringstream> packer(oss);
  this->msgpack_pack(packer);
  return oss.str();
}

void TransformMessage::Impl::Deserialize(const std::string& raw_data) {
  msgpack::object_handle handle =
      msgpack::unpack(raw_data.data(), raw_data.size());
  msgpack::object obj = handle.get();
  unpack_from_msgpack(obj);
}

// New helper method for deserialization logic
void TransformMessage::Impl::unpack_from_msgpack(const msgpack::object& obj) {
  // Use switch or conditional logic instead of direct assignment if needed
  if (obj.type == msgpack::type::MAP) {
    for (size_t i = 0; i < obj.via.map.size; ++i) {
      std::string key;
      obj.via.map.ptr[i].key.convert(key);
      if (key == "time_stamp") {
        obj.via.map.ptr[i].val.convert(time_stamp);
      } else if (key == "parent_frame_id") {
        obj.via.map.ptr[i].val.convert(parent_frame);
      } else if (key == "child_frame_id") {
        obj.via.map.ptr[i].val.convert(child_frame);
      } else if (key == "translation") {
        obj.via.map.ptr[i].val.convert(translation_vec);
      } else if (key == "rotation") {
        obj.via.map.ptr[i].val.convert(rotation_quat);
      }
    }
  }
}

