// Structure to accumulate RGBA color values during blurring
struct ColorAccumulator
{
	ColorAccumulator& operator +=(const ColorAccumulator& other)
	{
		r += other.r;
		g += other.g;
		b += other.b;
		a += other.a;
		return *this;
	}

	ColorAccumulator& operator -=(const ColorAccumulator& other)
	{
		r -= other.r;
		g -= other.g;
		b -= other.b;
		a -= other.a;
		return *this;
	}

	ColorAccumulator& operator -=(const uint8_t* ptr)
	{
		r -= ptr[0];
		g -= ptr[1];
		b -= ptr[2];
		a -= ptr[3];
		return *this;
	}

	void Accumulate(const uint8_t* data, uint8_t weight = 1)
	{
		r += data[0] * weight;
		g += data[1] * weight;
		b += data[2] * weight;
		a += data[3] * weight;
	}

	void Clear()
	{
		r = g = b = a = 0;
	}

	uint32_t r{}, g{}, b{}, a{};
};

StackBlur::StackBlur(uint8_t radius_param, const D2D1_SIZE_U& image_dimensions) 
    : blur_radius(std::clamp<uint8_t>(radius_param, 2, 254)), 
      dimensions(image_dimensions)
{
	// Calculate the size of the sliding window (diameter)
	window_size = (blur_radius * 2U) + 1U;

	// Determine optimal number of threads based on hardware concurrency
	thread_count = std::max(1U, std::thread::hardware_concurrency());

	// Retrieve precomputed shift and multiplier values
	shift_value = blur_shifts[blur_radius];
	multiplier_value = blur_multipliers[blur_radius];
}

void StackBlur::Execute(uint8_t* image_data) noexcept
{
	const size_t buffer_capacity = window_size * 4U * thread_count;
	std::vector<uint8_t> thread_buffer(buffer_capacity);
	std::vector<std::thread> worker_threads(thread_count);

	// First pass: horizontal blur
	for (uint32_t thread_id = 0; thread_id < thread_count; ++thread_id)
	{
		worker_threads[thread_id] = std::thread(
			[this, thread_id, image_data, &thread_buffer]()
			{
				const size_t buffer_offset = window_size * 4U * thread_id;
				ProcessPass(1, thread_id, image_data, &thread_buffer[buffer_offset]);
			}
		);
	}

	for (auto& worker : worker_threads)
	{
		worker.join();
	}

	// Second pass: vertical blur
	for (uint32_t thread_id = 0; thread_id < thread_count; ++thread_id)
	{
		worker_threads[thread_id] = std::thread(
			[this, thread_id, image_data, &thread_buffer]()
			{
				const size_t buffer_offset = window_size * 4U * thread_id;
				ProcessPass(2, thread_id, image_data, &thread_buffer[buffer_offset]);
			}
		);
	}

	for (auto& worker : worker_threads)
	{
		worker.join();
	}
}

void StackBlur::ApplyResult(uint8_t* output, const ColorAccumulator& accumulator) noexcept
{
	output[0] = static_cast<uint8_t>((accumulator.r * multiplier_value) >> shift_value);
	output[1] = static_cast<uint8_t>((accumulator.g * multiplier_value) >> shift_value);
	output[2] = static_cast<uint8_t>((accumulator.b * multiplier_value) >> shift_value);
	output[3] = static_cast<uint8_t>((accumulator.a * multiplier_value) >> shift_value);
}

void StackBlur::ProcessPass(uint32_t pass_type, uint32_t thread_id, uint8_t* image, uint8_t* buffer) noexcept
{
	ColorAccumulator total_sum, incoming_sum, outgoing_sum;
	uint8_t* buffer_ptr;
	uint8_t* image_ptr;
	uint8_t* dest_ptr;

	const uint32_t width_limit = dimensions.width - 1;
	const uint32_t height_limit = dimensions.height - 1;
	const uint32_t row_stride = dimensions.width * 4;

	uint32_t buffer_index = 0;
	uint32_t start_index = 0;

	if (pass_type == 1) // Horizontal pass
	{
		const uint32_t row_start = thread_id * dimensions.height / thread_count;
		const uint32_t row_end = (thread_id + 1) * dimensions.height / thread_count;

		for (uint32_t row = row_start; row < row_end; ++row)
		{
			total_sum.Clear();
			incoming_sum.Clear();
			outgoing_sum.Clear();

			image_ptr = image + row_stride * row;

			// Initialize the sliding window
			for (uint8_t i = 0; i <= blur_radius; ++i)
			{
				buffer_ptr = &buffer[i * 4];
				memcpy(buffer_ptr, image_ptr, 4);
				total_sum.Accumulate(image_ptr, i + 1);
				outgoing_sum.Accumulate(image_ptr);
			}

			for (uint8_t i = 1; i <= blur_radius; ++i)
			{
				if (i <= width_limit) image_ptr += 4;
				buffer_ptr = &buffer[4 * (i + blur_radius)];
				memcpy(buffer_ptr, image_ptr, 4);
				total_sum.Accumulate(image_ptr, blur_radius + 1 - i);
				incoming_sum.Accumulate(image_ptr);
			}

			buffer_index = blur_radius;
			uint32_t pixel_x = std::min<uint32_t>(blur_radius, width_limit);
			image_ptr = image + 4 * (pixel_x + row * dimensions.width);
			dest_ptr = image + row * row_stride;

			for (uint32_t col = 0; col < dimensions.width; ++col)
			{
				ApplyResult(dest_ptr, total_sum);
				dest_ptr += 4;

				start_index = buffer_index + window_size - blur_radius;
				if (start_index >= window_size)
					start_index -= window_size;

				buffer_ptr = &buffer[4 * start_index];

				if (pixel_x < width_limit)
				{
					image_ptr += 4;
					++pixel_x;
				}

				total_sum -= outgoing_sum;
				outgoing_sum -= buffer_ptr;
				memcpy(buffer_ptr, image_ptr, 4);
				incoming_sum.Accumulate(image_ptr);
				total_sum += incoming_sum;

				++buffer_index;
				if (buffer_index >= window_size)
					buffer_index = 0;

				buffer_ptr = &buffer[buffer_index * 4];
				outgoing_sum.Accumulate(buffer_ptr);
				incoming_sum -= buffer_ptr;
			}
		}
	}
	else if (pass_type == 2) // Vertical pass
	{
		const uint32_t col_start = thread_id * dimensions.width / thread_count;
		const uint32_t col_end = (thread_id + 1) * dimensions.width / thread_count;

		for (uint32_t col = col_start; col < col_end; ++col)
		{
			total_sum.Clear();
			incoming_sum.Clear();
			outgoing_sum.Clear();

			image_ptr = image + 4 * col;

			// Initialize the sliding window
			for (uint8_t i = 0; i <= blur_radius; ++i)
			{
				buffer_ptr = &buffer[i * 4];
				memcpy(buffer_ptr, image_ptr, 4);
				total_sum.Accumulate(image_ptr, i + 1);
				outgoing_sum.Accumulate(image_ptr);
			}

			for (uint8_t i = 1; i <= blur_radius; ++i)
			{
				if (i <= height_limit) image_ptr += row_stride;
				buffer_ptr = &buffer[4 * (i + blur_radius)];
				memcpy(buffer_ptr, image_ptr, 4);
				total_sum.Accumulate(image_ptr, blur_radius + 1 - i);
				incoming_sum.Accumulate(image_ptr);
			}

			buffer_index = blur_radius;
			uint32_t pixel_y = std::min<uint32_t>(blur_radius, height_limit);
			image_ptr = image + 4 * (col + pixel_y * dimensions.width);
			dest_ptr = image + 4 * col;

			for (uint32_t row = 0; row < dimensions.height; ++row)
			{
				ApplyResult(dest_ptr, total_sum);
				dest_ptr += row_stride;

				start_index = buffer_index + window_size - blur_radius;
				if (start_index >= window_size)
					start_index -= window_size;

				buffer_ptr = &buffer[4 * start_index];

				if (pixel_y < height_limit)
				{
					image_ptr += row_stride;
					++pixel_y;
				}

				total_sum -= outgoing_sum;
				outgoing_sum -= buffer_ptr;
				memcpy(buffer_ptr, image_ptr, 4);
				incoming_sum.Accumulate(image_ptr);
				total_sum += incoming_sum;

				++buffer_index;
				if (buffer_index >= window_size)
					buffer_index = 0;

				buffer_ptr = &buffer[buffer_index * 4];
				outgoing_sum.Accumulate(buffer_ptr);
				incoming_sum -= buffer_ptr;
			}
		}
	}
}

