#include <string.h>

/**
 * @brief Initialize the matrix with two random tiles
 */
void init_matrix_num(uint16_t matrix_size, uint16_t **matrix)
{
    // Zero out the entire matrix using memset for efficiency
    size_t total_cells = (size_t)matrix_size * matrix_size;
    memset(matrix[0], 0, total_cells * sizeof(uint16_t));

    // Place two random tiles
    add_random(matrix_size, matrix);
    add_random(matrix_size, matrix);
}

/**
 * @brief Add a random tile (2 or 4) to the matrix
 */
void add_random(uint16_t matrix_size, uint16_t **matrix)
{
    static bool rng_seeded = false;
    if (!rng_seeded) {
        srand((unsigned int)time(nullptr));
        rng_seeded = true;
    }

    // Flatten coordinates into a list of empty positions
    uint16_t empty_coords[256]; // max: 16x16 => 256 cells; store as [x0,y0,x1,y1,...]
    uint16_t count = 0;

    for (uint8_t i = 0; i < matrix_size; ++i) {
        for (uint8_t j = 0; j < matrix_size; ++j) {
            if (matrix[i][j] == 0) {
                empty_coords[count++] = (i << 8) | j; // pack x,y into one uint16
            }
        }
    }

    if (count > 0) {
        uint16_t idx = rand() % count;
        uint8_t x = empty_coords[idx] >> 8;
        uint8_t y = empty_coords[idx] & 0xFF;

        // 90% chance for 2, 10% for 4 (note: original had 10% for 4)
        uint16_t val = ((rand() % 10) == 0) ? 4 : 2;
        matrix[x][y] = val;
    }
}

/**
 * @brief Slide and merge a single row/column array (leftward)
 *        Modifies in-place and updates score.
 */
bool slide_array(uint16_t *score, uint16_t size, uint16_t *row)
{
    // Step 1: compress non-zero elements to front
    uint16_t temp[16]; // assume max size <= 16
    uint16_t new_len = 0;

    for (uint8_t i = 0; i < size; ++i) {
        if (row[i] != 0) {
            temp[new_len++] = row[i];
        }
    }

    // Step 2: merge adjacent equal values
    uint16_t merged[16];
    uint16_t m_len = 0;
    for (uint8_t i = 0; i < new_len; ) {
        if (i + 1 < new_len && temp[i] == temp[i + 1]) {
            uint16_t combined = temp[i] << 1;
            merged[m_len++] = combined;
            *score += combined;
            i += 2;
        } else {
            merged[m_len++] = temp[i++];
        }
    }

    // Step 3: pad with zeros to original size
    bool changed = (m_len != new_len || memcmp(row, merged, m_len * sizeof(uint16_t)) != 0);
    for (uint8_t i = 0; i < size; ++i) {
        row[i] = (i < m_len) ? merged[i] : 0;
    }

    return changed;
}

/**
 * @brief Move up (or left/right/down via rotation)
 */
bool move_up(uint16_t *score, uint16_t matrix_size, uint16_t **matrix)
{
    bool moved = false;
    for (uint8_t col = 0; col < matrix_size; ++col) {
        uint16_t column_data[16];
        for (uint8_t row = 0; row < matrix_size; ++row) {
            column_data[row] = matrix[row][col];
        }

        moved |= slide_array(score, matrix_size, column_data);

        for (uint8_t row = 0; row < matrix_size; ++row) {
            matrix[row][col] = column_data[row];
        }
    }
    return moved;
}

bool move_down(uint16_t *score, uint16_t matrix_size, uint16_t **matrix)
{
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    bool result = move_up(score, matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    return result;
}

bool move_left(uint16_t *score, uint16_t matrix_size, uint16_t **matrix)
{
    rotate_matrix(matrix_size, matrix);
    bool result = move_up(score, matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    return result;
}

bool move_right(uint16_t *score, uint16_t matrix_size, uint16_t **matrix)
{
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    bool result = move_up(score, matrix_size, matrix);
    rotate_matrix(matrix_size, matrix);
    return result;
}

/**
 * @brief Check if the game is over (no moves left)
 *        Does not mutate the original matrix
 */
bool game_over(uint16_t matrix_size, const uint16_t **matrix)
{
    if (count_empty(matrix_size, matrix) > 0) return false;

    // Helper lambda-like: check for any adjacent equal pair vertically
    auto has_vertical_match = [](uint16_t sz, const uint16_t **mat) -> bool {
        for (uint8_t x = 0; x < sz; ++x) {
            for (uint8_t y = 0; y < sz - 1; ++y) {
                if (mat[x][y] == mat[x][y + 1]) return true;
            }
        }
        return false;
    };

    if (has_vertical_match(matrix_size, matrix)) return false;

    // Simulate rotations and check again
    uint16_t **temp = lv_malloc(matrix_size * sizeof(uint16_t*));
    for (uint16_t i = 0; i < matrix_size; ++i) {
        temp[i] = lv_malloc(matrix_size * sizeof(uint16_t));
        for (uint16_t j = 0; j < matrix_size; ++j) {
            temp[i][j] = matrix[i][j];
        }
    }

    for (int rot = 0; rot < 4; ++rot) {
        if (has_vertical_match(matrix_size, (const uint16_t **)temp)) {
            for (uint16_t i = 0; i < matrix_size; ++i) lv_free(temp[i]);
            lv_free(temp);
            return false;
        }
        rotate_matrix(matrix_size, temp);
    }

    for (uint16_t i = 0; i < matrix_size; ++i) lv_free(temp[i]);
    lv_free(temp);
    return true;
}

/**
 * @brief Get the current score
 */
uint32_t twoeleven_get_score(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    return game_2048 ? game_2048->score : 0u;
}

/**
 * @brief Get the game over status
 */
bool twoeleven_get_status(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    return !game_2048 || game_2048->game_over;
}

/**
 * @brief Get the best tile value
 */
uint16_t twoeleven_get_best_tile(lv_obj_t * obj)
{
    const twoeleven_t * game_2048 = (const twoeleven_t *)lv_obj_get_user_data(obj);
    if (!game_2048) return 0;

    uint16_t max_power = 0;
    for (uint8_t x = 0; x < game_2048->matrix_size; ++x) {
        for (uint8_t y = 0; y < game_2048->matrix_size; ++y) {
            uint16_t val = game_2048->matrix[x][y];
            if (val > 0) {
                // Compute log2(val) efficiently
                uint16_t p = 0;
                while ((val >>= 1)) ++p;
                if (p > max_power) max_power = p;
            }
        }
    }
    return (uint16_t)(1u << max_power);
}

#include <SDL3/SDL.h>
