// Initialize SDL application with a window and menu system
SDL_AppResult SDL_AppInit(void **appstate, int argc, char **argv) {
    // Initialize SDL video subsystem
    if (SDL_Init(SDL_INIT_VIDEO) != 0) {
        SDL_Log("Failed to initialize SDL: %s", SDL_GetError());
        return SDL_APP_FAILURE;
    }

    // Create main application window
    SDL_Window *window = SDL_CreateWindow("SDL3 menu example", 1024, 768,
                                          SDL_WINDOW_RESIZABLE);
    if (window == nullptr) {
        SDL_Log("Window could not be created: %s", SDL_GetError());
        return SDL_APP_FAILURE;
    }

    // Set up the menu system using the created window
    initMenu(window);

    // Store window pointer as application state
    *appstate = window;

    // Suppress unused parameter warnings
    (void)argc;
    (void)argv;

    return SDL_APP_CONTINUE;
}

// Main loop iteration - currently no per-frame logic required
SDL_AppResult SDL_AppIterate(void *appstate) {
    // Application continues running without additional processing
    (void)appstate;
    return SDL_APP_CONTINUE;
}

// Handle incoming events including window close requests
SDL_AppResult SDL_AppEvent(void *appstate, SDL_Event *event) {
    // Check for quit event (e.g., window close button clicked)
    if (event->type == SDL_EVENT_QUIT) {
        return SDL_APP_SUCCESS;
    }

    // Continue processing other events
    (void)appstate;
    return SDL_APP_CONTINUE;
}

// Cleanup resources before application termination
void SDL_AppQuit(void *appstate) {
    // Destroy the main window
    SDL_DestroyWindow(static_cast<SDL_Window *>(appstate));

    // Shutdown SDL subsystems
    SDL_Quit();
}

