    // Replaces copyIndicesToNode with modified logic
    void transferPolygonIndices(MIntArray& indices, const MObject& node,
                               MObject& targetSet)
    {
        MStatus status;
        MFnDagNode dagNode(node);
        MDagPath shapePath;
        status = dagNode.getPath(shapePath);

        // Handle intermediate objects - find the active shape for shading
        if (dagNode.isIntermediateObject())
        {
            MDagPath activeShape = shapePath;
            activeShape.pop();
            if (activeShape.extendToShape())
                shapePath = activeShape;
        }

        // Clear existing members from the set
        MFnSet fnSet(targetSet);
        MSelectionList currentMembers;
        fnSet.getMembers(currentMembers, false);
        MItSelectionList memberIterator(currentMembers);

        for (; !memberIterator.isDone(); memberIterator.next())
        {
            MDagPath currentPath;
            MObject component;
            memberIterator.getDagPath(currentPath, component);
            if ((currentPath == shapePath) && component.isNull())
                fnSet.removeMember(currentPath, component);
        }

        // Prepare new indexed component
        MFnSingleIndexedComponent compFn;
        MObject polygonComp = compFn.create(MFn::kMeshPolygonComponent);
        compFn.addElements(indices);

        // Enforce exclusivity by removing from other sets
        MObjectArray connectedSGs(getOutConnectedSG(shapePath));
        MObject sgObj;
        MFnSet otherSetFn;
        MSelectionList currentSetList, otherSetList, xorList;
        currentSetList.add(shapePath, polygonComp);

        int sgCount = connectedSGs.length();
        for (int i = 0; i < sgCount; ++i)
        {
            sgObj = connectedSGs[i];
            if (sgObj != targetSet)
            {
                otherSetFn.setObject(sgObj);
                otherSetFn.getMembers(otherSetList, false);

                // Check for full partition scenario
                if (otherSetList.length() >= 1)
                {
                    MItSelectionList itList(otherSetList);
                    for (; !itList.isDone(); itList.next())
                    {
                        MDagPath path;
                        MObject compObj;
                        itList.getDagPath(path, compObj);
                        if (!(path == shapePath) || !compObj.isNull())
                            continue;

                        otherSetFn.removeMember(path, compObj);

                        // Create full component for partition
                        MFnMesh meshFn(shapePath);
                        MFnSingleIndexedComponent fullCompFn;
                        compObj = fullCompFn.create(MFn::kMeshPolygonComponent);
                        fullCompFn.setCompleteData(meshFn.numPolygons());

                        otherSetList.clear();
                        otherSetList.add(shapePath, compObj);
                        break;
                    }
                }

                xorList = otherSetList;
                xorList.merge(currentSetList, MSelectionList::kXORWithList);
                otherSetList.merge(xorList, MSelectionList::kRemoveFromList);

                if (!otherSetList.isEmpty())
                    otherSetFn.removeMembers(otherSetList);
            }
        }

        // Add the new members to target set
        fnSet.addMember(shapePath, polygonComp);
    }

    // Modified version of addFaceSets with different structure
    void establishFaceSets(MObject & node, Alembic::Abc::IObject & abcObj)
    {
        MStatus status;
        MFnDependencyNode mesh(node, &status);
        if (status != MS::kSuccess)
            return;

        std::size_t childCount = abcObj.getNumChildren();
        for (std::size_t idx = 0; idx < childCount; ++idx)
        {
            Alembic::Abc::IObject child = abcObj.getChild(idx);
            if (Alembic::AbcGeom::IFaceSet::matches(child.getHeader()))
            {
                Alembic::AbcGeom::IFaceSet faceSet(child,
                    Alembic::Abc::kWrapExisting);

                // Create or retrieve shading group
                MObject shadingGroup;
                const MString& faceSetName(faceSet.getName().c_str());

                // Check if SG already exists
                status = getObjectByName(faceSetName, shadingGroup);
                if (shadingGroup.isNull())
                {
                    shadingGroup = createShadingGroup(faceSetName);
                }

                // Set AbcFacesetName attribute
                MFnDependencyNode depNode(shadingGroup);
                MPlug namePlug = depNode.findPlug("AbcFacesetName", true);
                if (namePlug.isNull())
                {
                    MFnStringData strData;
                    MString attrName("AbcFacesetName");
                    MObject strAttr = strData.create("");
                    MFnTypedAttribute attr;
                    MObject attrObj = attr.create(attrName, attrName,
                                              MFnData::kString, strAttr);
                    depNode.addAttribute(attrObj);
                    namePlug = depNode.findPlug(attrObj, true);
                }
                namePlug.setValue(faceSetName);

                // Get face indices
                Alembic::AbcGeom::IFaceSetSchema::Sample sample;
                faceSet.getSchema().get(sample);
                MFnIntArrayData arrData;
                const int* faceBuffer((int *)sample.getFaces()->getData());
                const size_t count = sample.getFaces()->size();
                MIntArray indices(faceBuffer, static_cast<unsigned int>(count));

                // Transfer indices to set
                transferPolygonIndices(indices, node, shadingGroup);

                // Process properties
                Alembic::Abc::ICompoundProperty arbProp =
                    faceSet.getSchema().getArbGeomParams();
                Alembic::Abc::ICompoundProperty userProp =
                    faceSet.getSchema().getUserProperties();
                applyProperties(arbProp, shadingGroup, false);
                applyProperties(userProp, shadingGroup, false);
            }
        }
    }

