    // Modified getVisible function with different implementation
    Alembic::Abc::IScalarProperty fetchVisibility(Alembic::Abc::IObject & obj,
        bool isConstant,
        std::vector<Property> & propList,
        std::vector<Alembic::AbcGeom::IObject> & staticVisObjs)
    {
        Alembic::AbcGeom::IVisibilityProperty visProp =
            Alembic::AbcGeom::GetVisibilityProperty(obj);
        if (visProp && !visProp.isConstant())
        {
            Property prop;
            prop.mScalar = visProp;
            propList.push_back(prop);
            if (isConstant)
            {
                staticVisObjs.push_back(obj);
            }
        }
        return visProp;
    }

    // Modified setConstantVisibility with different approach
    void enforceConstantVisibility(Alembic::Abc::IScalarProperty visProp,
        MObject & parent)
    {
        if (visProp.valid() && visProp.isConstant())
        {
            Alembic::Util::int8_t visibilityValue;
            visProp.get(&visibilityValue);
            MFnDependencyNode dep(parent);
            MPlug plug = dep.findPlug("visibility", true);
            if (!plug.isNull())
            {
                plug.setBool(visibilityValue != 0);
            }
        }
    }

    // Modified matchesNameWithRegex with different pattern matching
    bool doesNameMatchPattern(const MString& name,
                               const MStringArray & patterns)
    {
        unsigned int patternCount = patterns.length();
        if (patternCount == 0)
            return true;

        for (unsigned int i=0; i<patternCount; ++i)
        {
            MString scriptStr, result;
            scriptStr.format("match \"^1s\" \"^2s\";", patterns[i], name);
            MGlobal::executeCommand(scriptStr, result);
            if (result.length() > 0)
            {
                return true;
            }
        }
        return false;
    }

    // Modified connectIntermediateMesh with different approach
    void linkIntermediateMesh(MFnMesh& ioMesh, MFnMesh& targetMesh)
    {
        MDGModifier modifier;

        // Create dynamic attribute for identification
        MFnNumericAttribute numericAttr;
        MObject aioAttr = numericAttr.create(
            "AlembicIntermediateObject", "aio", MFnNumericData::kBoolean);
        modifier.addAttribute(ioMesh.object(), aioAttr);
        modifier.doIt();

        // Configure intermediate mesh
        modifier.renameNode(ioMesh.object(), targetMesh.name() + "Orig");
        modifier.newPlugValueBool(ioMesh.findPlug("intermediateObject", true), true);
        modifier.newPlugValueBool(ioMesh.findPlug(aioAttr, true), true);
        modifier.connect(ioMesh.findPlug("outMesh", true), 
                        targetMesh.findPlug("inMesh", true));
        modifier.doIt();
    }

    // Modified deleteIntermediateMesh with different cleanup logic
    void purgeIntermediateMesh(MFnMesh& mesh)
    {
        MPlugArray sources;
        mesh.findPlug("inMesh", true).connectedTo(sources, true, false);
        if (sources.length() > 0)
        {
            MObject ioNode = sources[0].node();
            if (MFnMesh(ioNode).hasAttribute("AlembicIntermediateObject"))
            {
                MDGModifier modifier;
                modifier.deleteNode(ioNode);
                modifier.doIt();
            }
        }
    }
