    LISTEN_QUEUE_DEPTH = 10,
    MAX_RECONNECT_ATTEMPTS = 20,
    RECONNECT_DELAY_MS = 250,
    START_PORT = 17000,
    END_PORT = ((1 << (sizeof(IPport) * 8)) - 1),
    MPI_MAGIC_NUMBER = 17400000
};

