//------------------------------------------------------------------------------
// Public constructors and destructor
Stream::Stream(
    StreamType type,
    void (*err_handler)(char *),
    void (*trace_handler)(char *))
{
    initialize_class();
    error_callback = err_handler;
    trace_callback = trace_handler;
    memset(&local_endpoint, 0, sizeof(local_endpoint));
    memset(&remote_endpoint, 0, sizeof(remote_endpoint));
    connection_status = false;
    stream_kind = type;

    switch (type)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        setup_MPI_connection();
        break;
#endif
    case Stream::TCPIP:
        setup_TCPIP_connection();
        break;
    default:
        report_error("Unsupported stream type in primary constructor");
        break;
    }
}

Stream::Stream(
    StreamType type,
    const char *connection_info,
    void (*err_handler)(char *),
    void (*trace_handler)(char *))
{
    initialize_class();
    error_callback = err_handler;
    trace_callback = trace_handler;
    memset(&local_endpoint, 0, sizeof(local_endpoint));
    memset(&remote_endpoint, 0, sizeof(remote_endpoint));
    stream_kind = type;

    switch (type)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        establish_MPI_connection(connection_info);
        break;
#endif
    case Stream::TCPIP:
        establish_TCPIP_connection(connection_info);
        break;
    default:
        report_error("Unsupported stream type in secondary constructor");
        break;
    }
}

Stream::~Stream()
{
    switch (stream_kind)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        if (local_endpoint.handle != nullptr)
            delete[] local_endpoint.handle;
        if (remote_endpoint.handle != nullptr)
            delete[] remote_endpoint.handle;
        break;
#endif
    case Stream::TCPIP:
        close_socket(local_endpoint.sock);
        close_socket(remote_endpoint.sock);
        if (local_endpoint.handle != nullptr)
            delete[] local_endpoint.handle;
        if (remote_endpoint.handle != nullptr)
            delete[] remote_endpoint.handle;
        break;
    default:
        report_error("Unsupported stream type in destructor");
        break;
    }
}

//------------------------------------------------------------------------------
// Private TCP/IP setup functions
void Stream::setup_TCPIP_connection()
{
    IPport candidate_port; // Declared outside branches

    // Attempt IPv6 first
    local_endpoint.sock = socket(AF_INET6, SOCK_STREAM, IPPROTO_TCP);
    using_ipv6 = (local_endpoint.sock != -1);

    if (using_ipv6)
    {
        int disable_v6_only = 0;
        setsockopt(local_endpoint.sock, IPPROTO_IPV6, IPV6_V6ONLY, (char *)&disable_v6_only, sizeof(disable_v6_only));

        struct sockaddr_in6 *addr6 = reinterpret_cast<struct sockaddr_in6 *>(&local_endpoint.addr);
        addr6->sin6_family = AF_INET6;
        addr6->sin6_addr = IN6ADDR_ANY_INIT;

        bool success = false;
        for (candidate_port = START_PORT; candidate_port < END_PORT; ++candidate_port)
        {
            addr6->sin6_port = htons(candidate_port);
            if (bind(local_endpoint.sock, reinterpret_cast<struct sockaddr *>(addr6), sizeof(struct sockaddr_in6)) == 0)
            {
                success = true;
                break;
            }
        }

        if (!success)
        {
            report_error("Failed to bind IPv6 socket on ports [%d-%d]", START_PORT, END_PORT - 1);
        }
    }
    else
    {
        local_endpoint.sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (local_endpoint.sock == -1)
            report_error("Unable to create IPv4 socket");

        struct sockaddr_in *addr4 = reinterpret_cast<struct sockaddr_in *>(&local_endpoint.addr);
        addr4->sin_family = AF_INET;
        addr4->sin_addr.s_addr = INADDR_ANY;

        bool success = false;
        for (candidate_port = START_PORT; candidate_port < END_PORT; ++candidate_port)
        {
            addr4->sin_port = htons(candidate_port);
            if (bind(local_endpoint.sock, reinterpret_cast<struct sockaddr *>(addr4), sizeof(struct sockaddr_in)) == 0)
            {
                success = true;
                break;
            }
        }

        if (!success)
        {
            report_error("Failed to bind IPv4 socket on ports [%d-%d]", START_PORT, END_PORT - 1);
        }
    }

    char temp_buffer[MAX_BUFFER_SIZE];
    snprintf(temp_buffer, MAX_BUFFER_SIZE, "%s:%d", get_hostname(), candidate_port);
    local_endpoint.handle = new char[strlen(temp_buffer) + 1];
    strcpy(local_endpoint.handle, temp_buffer);
    log_trace("Local handle created: %s", local_endpoint.handle);
}

void Stream::establish_TCPIP_connection(const char *info)
{
    if (info == nullptr || info[0] == '\0')
        report_error("Invalid or empty connection info string");

    char host_part[MAX_BUFFER_SIZE];
    char *hp = host_part;
    int port_number;

    while (*info && *info != ':')
        *hp++ = *info++;
    *hp = '\0';
    port_number = atoi(info + 1);

    char *ip_address = resolve_host(host_part);

    // Try IPv6 first
    remote_endpoint.sock = socket(AF_INET6, SOCK_STREAM, IPPROTO_TCP);
    using_ipv6 = (remote_endpoint.sock != -1);

    if (using_ipv6)
    {
        struct sockaddr_in6 *addr6 = reinterpret_cast<struct sockaddr_in6 *>(&remote_endpoint.addr);
        addr6->sin6_family = AF_INET6;
        addr6->sin6_port = htons(port_number);

        struct in6_addr ipv6_addr;
        if (inet_pton(AF_INET6, ip_address, &ipv6_addr) != 1)
        {
            // Fallback to IPv4-mapped address
            struct in_addr ipv4_addr;
            if (inet_pton(AF_INET, ip_address, &ipv4_addr) != 1)
            {
                report_error("Invalid IP format for host '%s'", host_part);
            }
            memset(&ipv6_addr, 0, sizeof(ipv6_addr));
            ipv6_addr.s6_addr[10] = 0xFF;
            ipv6_addr.s6_addr[11] = 0xFF;
            memcpy(&ipv6_addr.s6_addr[12], &ipv4_addr, sizeof(ipv4_addr));
        }
        addr6->sin6_addr = ipv6_addr;
    }
    else
    {
        remote_endpoint.sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
        if (remote_endpoint.sock == -1)
            report_error("Cannot create IPv4 remote socket");

        struct sockaddr_in *addr4 = reinterpret_cast<struct sockaddr_in *>(&remote_endpoint.addr);
        addr4->sin_family = AF_INET;
        addr4->sin_port = htons(port_number);

        if (inet_pton(AF_INET, ip_address, &addr4->sin_addr) != 1)
        {
            report_error("Invalid IPv4 address for host '%s'", host_part);
        }
    }

    char buffer[MAX_BUFFER_SIZE];
    snprintf(buffer, MAX_BUFFER_SIZE, "%s:%d", host_part, port_number);
    remote_endpoint.handle = new char[strlen(buffer) + 1];
    strcpy(remote_endpoint.handle, buffer);

    // Retry connection with exponential backoff
    log_trace("Connecting to %s", remote_endpoint.handle);
    int retries;
    for (retries = 0; retries < MAX_RECONNECT_ATTEMPTS; ++retries)
    {
        socklen_t len = using_ipv6 ? sizeof(struct sockaddr_in6) : sizeof(struct sockaddr_in);
        if (connect(remote_endpoint.sock, reinterpret_cast<struct sockaddr *>(&remote_endpoint.addr), len) == 0)
            break;
        usleep(RECONNECT_DELAY_MS * 1000);
    }

    if (retries == MAX_RECONNECT_ATTEMPTS)
        report_error("Connection failed to %s after %d attempts: %s",
                     remote_endpoint.handle, MAX_RECONNECT_ATTEMPTS, strerror(errno));

    int bytes_read = recv(remote_endpoint.sock, buffer, MAX_BUFFER_SIZE, 0);
    if (bytes_read <= 0)
        report_error("Failed to receive peer info: %s", strerror(errno));

    local_endpoint.handle = new char[strlen(buffer) + 1];
    strcpy(local_endpoint.handle, buffer);
    connection_status = true;
    log_trace("Connected local handle %s to remote %s", local_endpoint.handle, remote_endpoint.handle);
}

//------------------------------------------------------------------------------
// Private MPI functions
#if defined(WITH_MPI)
void Stream::setup_MPI_connection()
{
    local_endpoint.sequence = increment_sequence();

#if defined(NO_CPP_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &local_endpoint.rank);
#else
    local_endpoint.rank = MPI::COMM_WORLD.Get_rank();
#endif

    local_endpoint.handle = new char[Stream::MAXHANDLE];
    snprintf(local_endpoint.handle, Stream::MAXHANDLE, "%s:%d:%d", get_hostname(), local_endpoint.rank, local_endpoint.sequence);
    connection_status = false;
    log_trace("MPI local handle: %s", local_endpoint.handle);
}

void Stream::establish_MPI_connection(const char *info)
{
    remote_endpoint.handle = new char[Stream::MAXHANDLE];
    strcpy(remote_endpoint.handle, info);

    if (sscanf(info, "%*[^:]:%d:%d", &remote_endpoint.rank, &remote_endpoint.sequence) != 2)
        report_error("Malformed MPI handle: \"%s\"", info);

    local_endpoint.sequence = increment_sequence();

#if defined(NO_CPP_MPI)
    MPI_Comm_rank(MPI_COMM_WORLD, &local_endpoint.rank);
#else
    local_endpoint.rank = MPI::COMM_WORLD.Get_rank();
#endif

    local_endpoint.handle = new char[Stream::MAXHANDLE];
    snprintf(local_endpoint.handle, Stream::MAXHANDLE, "%s:%d:%d", get_hostname(), local_endpoint.rank, local_endpoint.sequence);
    connection_status = true;

#if defined(NO_CPP_MPI)
    MPI_Send((void *)local_endpoint.handle, Stream::MAXHANDLE, MPI_CHAR, remote_endpoint.rank,
             MPI_MAGIC_NUMBER + remote_endpoint.sequence, MPI_COMM_WORLD);
#else
    MPI::COMM_WORLD.Send((void *)local_endpoint.handle, Stream::MAXHANDLE, MPI::CHAR,
                         remote_endpoint.rank, MPI_MAGIC_NUMBER + remote_endpoint.sequence);
#endif

    log_trace("MPI connected: local=%s, remote=%s", local_endpoint.handle, remote_endpoint.handle);
}
#endif

//------------------------------------------------------------------------------
// Public methods
void Stream::Connect()
{
    switch (stream_kind)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        wait_for_MPI_peer();
        break;
#endif
    case Stream::TCPIP:
        wait_for_TCPIP_peer();
        break;
    default:
        report_error("Unknown stream type in Connect()");
        break;
    }
}

void Stream::Send(const char *data, int size)
{
    if (!connection_status)
        report_error("Attempted send on unconnected stream (%s)", local_endpoint.handle);

    log_trace("Sending %d bytes from %s to %s", size, local_endpoint.handle, remote_endpoint.handle);

    switch (stream_kind)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
#if defined(NO_CPP_MPI)
        MPI_Send((void *)data, size, MPI_CHAR, remote_endpoint.rank, remote_endpoint.sequence, MPI_COMM_WORLD);
#else
        MPI::COMM_WORLD.Send((void *)data, size, MPI::CHAR, remote_endpoint.rank, remote_endpoint.sequence);
#endif
        break;
#endif
    case Stream::TCPIP:
        if (send(remote_endpoint.sock, data, size, 0) != size)
            report_error("Send failed to %s: %s", remote_endpoint.handle, strerror(errno));
        break;
    default:
        report_error("Unknown stream type in Send()");
        break;
    }

    log_trace("Sent %d bytes from %s to %s", size, local_endpoint.handle, remote_endpoint.handle);
}

void Stream::Receive(char *buffer, int length)
{
    switch (stream_kind)
    {
#if defined(WITH_MPI)
    case Stream::MPI:
        read_MPI_data(buffer, length);
        break;
#endif
    case Stream::TCPIP:
        read_TCPIP_data(buffer, length);
        break;
    default:
        report_error("Unknown stream type in Receive()");
        break;
    }
}

//------------------------------------------------------------------------------
// Private TCP/IP receive functions
void Stream::wait_for_TCPIP_peer()
{
    if (listen(local_endpoint.sock, LISTEN_QUEUE_DEPTH) != 0)
        report_error("Listen failed on socket");

    log_trace("Listening on %s", local_endpoint.handle);

    socklen_t addrlen = using_ipv6 ? sizeof(struct sockaddr_in6) : sizeof(struct sockaddr_in);
    remote_endpoint.sock = accept(local_endpoint.sock, reinterpret_cast<struct sockaddr *>(&remote_endpoint.addr), &addrlen);
    if (remote_endpoint.sock == -1)
        report_error("Accept failed");

    char ip_str[INET6_ADDRSTRLEN];
    IPport port;

    if (using_ipv6)
    {
        inet_ntop(AF_INET6, &reinterpret_cast<struct sockaddr_in6 *>(&remote_endpoint.addr)->sin6_addr, ip_str, sizeof(ip_str));
        port = reinterpret_cast<struct sockaddr_in6 *>(&remote_endpoint.addr)->sin6_port;
    }
    else
    {
        inet_ntop(AF_INET, &reinterpret_cast<struct sockaddr_in *>(&remote_endpoint.addr)->sin_addr, ip_str, sizeof(ip_str));
        port = reinterpret_cast<struct sockaddr_in *>(&remote_endpoint.addr)->sin_port;
    }

    remote_endpoint.handle = new char[Stream::MAXHANDLE];
    snprintf(remote_endpoint.handle, Stream::MAXHANDLE, "%s:%d", map_ip_to_shortname(ip_str), ntohs(port));

    if (send(remote_endpoint.sock, remote_endpoint.handle, Stream::MAXHANDLE, 0) != Stream::MAXHANDLE)
        report_error("Failed to send local handle to peer: %s", strerror(errno));

    connection_status = true;
    log_trace("Accepted connection: local=%s, remote=%s", local_endpoint.handle, remote_endpoint.handle);
}

void Stream::read_TCPIP_data(char *buf, int len)
{
    log_trace("Receiving %d bytes from %s to %s", len, remote_endpoint.handle, local_endpoint.handle);

    int remaining = len;
    while (remaining > 0)
    {
        int received = recv(remote_endpoint.sock, buf, remaining, 0);
        if (received < 0)
            report_error("Recv failed from %s: %s", remote_endpoint.handle, strerror(errno));
        if (received == 0)
            report_error("Connection closed by peer %s", remote_endpoint.handle);
        remaining -= received;
        buf += received;
    }

    log_trace("Received %d bytes from %s to %s", len, remote_endpoint.handle, local_endpoint.handle);
}

//------------------------------------------------------------------------------
// Private MPI receive functions
#if defined(WITH_MPI)
void Stream::wait_for_MPI_peer()
{
    remote_endpoint.handle = new char[Stream::MAXHANDLE];

#if defined(NO_CPP_MPI)
    MPI_Status status;
    MPI_Recv((void *)remote_endpoint.handle, Stream::MAXHANDLE, MPI_CHAR, MPI_ANY_SOURCE,
             MPI_MAGIC_NUMBER + local_endpoint.sequence, MPI_COMM_WORLD, &status);
#else
    MPI::Status status;
    MPI::COMM_WORLD.Recv((void *)remote_endpoint.handle, Stream::MAXHANDLE, MPI::CHAR,
                         MPI::ANY_SOURCE, MPI_MAGIC_NUMBER + local_endpoint.sequence, status);
#endif

    if (sscanf(remote_endpoint.handle, "%*[^:]:%d:%d", &remote_endpoint.rank, &remote_endpoint.sequence) != 2)
        report_error("Invalid MPI handle received: \"%s\"", remote_endpoint.handle);

    connection_status = true;
    log_trace("MPI connection established: local=%s, remote=%s", local_endpoint.handle, remote_endpoint.handle);
}

void Stream::read_MPI_data(char *buf, int len)
{
    log_trace("Waiting for %d bytes from %s to %s", len, remote_endpoint.handle, local_endpoint.handle);

#if defined(NO_CPP_MPI)
    MPI_Status status;
    MPI_Recv((void *)buf, len, MPI_CHAR, remote_endpoint.rank, local_endpoint.sequence, MPI_COMM_WORLD, &status);
    int actual_len;
    MPI_Get_count(&status, MPI_CHAR, &actual_len);
    if (actual_len != len)
        report_error("MPI receive mismatch: expected %d bytes, got %d", len, actual_len);
#else
    MPI::Status status;
    MPI::COMM_WORLD.Recv((void *)buf, len, MPI::CHAR, remote_endpoint.rank, local_endpoint.sequence, status);
    if (status.Get_count(MPI::CHAR) != len)
        report_error("MPI receive mismatch: expected %d bytes, got %d", len, status.Get_count(MPI::CHAR));
#endif

    log_trace("Received %d bytes from %s to %s", len, remote_endpoint.handle, local_endpoint.handle);
}
#endif

//------------------------------------------------------------------------------
// Other public methods
char *Stream::LocalHandle() { return local_endpoint.handle; }

char *Stream::RemoteHandle()
{
    if (connection_status)
        return remote_endpoint.handle;
    else
    {
        switch (stream_kind)
        {
#if defined(WITH_MPI)
        case Stream::MPI:
            return (char *)"[mpi]:*:*";
#endif
        case Stream::TCPIP:
            return (char *)"[unknown]:0";
        default:
            return nullptr;
        }
    }
}

//------------------------------------------------------------------------------
// Utility/private functions
void Stream::initialize_class()
{
    if (!Stream::initialized)
    {
        Stream::initialized = true;

#if defined(_WIN32)
        WORD version = MAKEWORD(2, 2);
        WSADATA wsa_data;
        if (WSAStartup(version, &wsa_data) != 0)
            report_error("Winsock initialization failed: %d", WSAGetLastError());
#else
        if (pthread_mutex_init(&Stream::mutex, nullptr) != 0)
            report_error("Mutex creation failed: errno=%d", errno);
#endif
    }
}

int Stream::increment_sequence()
{
    static int seq_counter = 101;

#if defined(_WIN32)
    // No locking needed on Windows
#else
    if (pthread_mutex_lock(&Stream::mutex) != 0)
        report_error("Mutex lock failed: errno=%d", errno);
#endif

    int current = seq_counter++;

#if defined(_WIN32)
    // No unlocking needed on Windows
#else
    if (pthread_mutex_unlock(&Stream::mutex) != 0)
        report_error("Mutex unlock failed: errno=%d", errno);
#endif

    return current;
}

void Stream::log_trace(const char *fmt, ...)
{
    if (trace_callback != nullptr)
    {
        va_list args;
        char msg[MAX_BUFFER_SIZE];
        va_start(args, fmt);
        vsnprintf(msg, MAX_BUFFER_SIZE, fmt, args);
        va_end(args);
        trace_callback(msg);
    }
}

char *Stream::get_hostname()
{
    static char name[MAX_BUFFER_SIZE + 1];
    static bool initialized = false;

    if (!initialized)
    {
        initialized = true;
        name[MAX_BUFFER_SIZE] = '\0';

        if (gethostname(name, sizeof(name)) != 0)
            report_error("gethostname() failed");

        if (strlen(name) == MAX_BUFFER_SIZE)
            report_error("Hostname too long");

        for (char *p = name; *p != '\0'; ++p)
        {
            if (*p == '.')
            {
                *p = '\0';
                break;
            }
        }
    }

    return name;
}

void Stream::split_address(char *input, char *host_out, int *port_out)
{
    if (input == nullptr)
        report_error("Null input to split_address");

    while (*input && *input != ':')
        *host_out++ = *input++;
    *host_out = '\0';
    *port_out = atoi(input + 1);
}

char *Stream::resolve_host(const char *hostname)
{
    static char ip_string[INET6_ADDRSTRLEN];
    struct addrinfo hints = {};
    struct addrinfo *res = nullptr;

    hints.ai_family = AF_INET6;
    hints.ai_socktype = SOCK_STREAM;
    hints.ai_protocol = IPPROTO_TCP;

    int ret = getaddrinfo(hostname, nullptr, &hints, &res);
    if (ret == 0 && res != nullptr)
    {
        if (res->ai_addrlen == sizeof(sockaddr_in6))
        {
            auto *v6 = reinterpret_cast<sockaddr_in6 *>(res->ai_addr);
            inet_ntop(AF_INET6, &v6->sin6_addr, ip_string, sizeof(ip_string));
            freeaddrinfo(res);
            return ip_string;
        }
        freeaddrinfo(res);
    }

    // Fallback to IPv4
    hints.ai_family = AF_INET;
    ret = getaddrinfo(hostname, nullptr, &hints, &res);
    if (ret != 0)
        report_error("DNS resolution failed for '%s': %s", hostname, gai_strerror(ret));

    if (res == nullptr || res->ai_addrlen != sizeof(sockaddr_in))
    {
        freeaddrinfo(res);
        report_error("No valid IPv4 address found for '%s'", hostname);
        return nullptr;
    }

    auto *v4 = reinterpret_cast<sockaddr_in *>(res->ai_addr);
    inet_ntop(AF_INET, &v4->sin_addr, ip_string, sizeof(ip_string));
    freeaddrinfo(res);
    return ip_string;
}

char *Stream::map_ip_to_shortname(const char *ip_str)
{
    static char short_name[MAX_BUFFER_SIZE];
    char full_name[MAX_BUFFER_SIZE];
    struct sockaddr_in6 addr6 = {};
    addr6.sin6_family = AF_INET6;

    if (inet_pton(AF_INET6, ip_str, &addr6.sin6_addr) == 1)
    {
        if (IN6_IS_ADDR_UNSPECIFIED(&addr6.sin6_addr))
            return (char *)"localhost";

        socklen_t len = sizeof(addr6);
        int status = getnameinfo(reinterpret_cast<sockaddr *>(&addr6), len, full_name, MAX_BUFFER_SIZE, nullptr, 0, NI_NAMEREQD);
        if (status != 0)
        {
            strncpy(short_name, ip_str, MAX_BUFFER_SIZE);
            short_name[MAX_BUFFER_SIZE - 1] = '\0';
            return short_name;
        }
    }
    else
    {
        struct sockaddr_in addr4 = {};
        addr4.sin_family = AF_INET;
        if (inet_pton(AF_INET, ip_str, &addr4.sin_addr) == 1)
        {
            socklen_t len = sizeof(addr4);
            int status = getnameinfo(reinterpret_cast<sockaddr *>(&addr4), len, full_name, MAX_BUFFER_SIZE, nullptr, 0, NI_NAMEREQD);
            if (status != 0)
            {
                strncpy(short_name, ip_str, MAX_BUFFER_SIZE);
                short_name[MAX_BUFFER_SIZE - 1] = '\0';
                return short_name;
            }
        }
    }

    char *dst = short_name;
    const char *src = full_name;
    while (*src && *src != '.')
        *dst++ = *src++;
    *dst = '\0';

    return short_name;
}

char *Stream::format_ipv6(const struct in6_addr &addr)
{
    static char dotted[INET6_ADDRSTRLEN];

    if (IN6_IS_ADDR_V4MAPPED(&addr))
    {
        uint32_t ipv4_val = ntohl(*reinterpret_cast<const uint32_t *>(&addr.s6_addr[12]));
        snprintf(dotted, sizeof(dotted), "%u.%u.%u.%u",
                 (ipv4_val >> 24) & 0xFF,
                 (ipv4_val >> 16) & 0xFF,
                 (ipv4_val >> 8) & 0xFF,
                 ipv4_val & 0xFF);
    }
    else
    {
        if (inet_ntop(AF_INET6, &addr, dotted, sizeof(dotted)) == nullptr)
            strcpy(dotted, "[invalid]");
    }

    return dotted;
}

void Stream::report_error(const char *fmt, ...)
{
    va_list args;
    char message[MAX_BUFFER_SIZE];
    va_start(args, fmt);
    vsnprintf(message, MAX_BUFFER_SIZE, fmt, args);
    va_end(args);

    if (error_callback != nullptr)
    {
        error_callback(message);
    }
    else
    {
        fflush(stdout);
        fprintf(stderr, "Fatal error: %s\n", message);
        fflush(stderr);
        exit(EXIT_FAILURE);
    }
}

#include <iostream>
#include <cstring>
#include <cstdlib>
#include <cassert>
#include <cmath>

// Simplified Value class implementation for demonstration
class Value {
public:
    enum ValueType {
        nullValue,
        intValue,
        uintValue,
        realValue,
        booleanValue,
        stringValue,
        arrayValue,
        objectValue
    };

private:
    ValueType type_;
    bool allocated_;

    union Data {
        int int_;
        unsigned uint_;
        double real_;
        bool bool_;
        char* string_;
        void* map_;
    } value_;

    // Helper function to duplicate string with length
    static char* copyString(const char* src, size_t len) {
        if (len >= static_cast<size_t>(1073741823)) // maxInt - 1 approximation
            len = 1073741823;

        char* buffer = static_cast<char*>(malloc(len + 1));
        if (!buffer) {
            std::cerr << "Memory allocation failed" << std::endl;
            exit(1);
        }

        memcpy(buffer, src, len);
        buffer[len] = '\0';
        return buffer;
    }

public:
    // Default constructor
    Value() : type_(nullValue), allocated_(false) {
        memset(&value_, 0, sizeof(value_));
    }

    // Constructor for specific type
    Value(ValueType t) : type_(t), allocated_(false) {
        switch (t) {
            case nullValue:
                break;
            case intValue:
                value_.int_ = 0;
                break;
            case uintValue:
                value_.uint_ = 0;
                break;
            case realValue:
                value_.real_ = 0.0;
                break;
            case booleanValue:
                value_.bool_ = false;
                break;
            case stringValue:
                value_.string_ = const_cast<char*>("");
                break;
            case arrayValue:
            case objectValue:
                value_.map_ = nullptr;
                break;
        }
    }

    // Constructor for integer
    Value(int num) : type_(intValue), allocated_(false) {
        value_.int_ = num;
    }

    // Constructor for unsigned integer
    Value(unsigned num) : type_(uintValue), allocated_(false) {
        value_.uint_ = num;
    }

    // Constructor for double
    Value(double num) : type_(realValue), allocated_(false) {
        value_.real_ = num;
    }

    // Constructor for boolean
    Value(bool flag) : type_(booleanValue), allocated_(false) {
        value_.bool_ = flag;
    }

    // Constructor for C-string
    Value(const char* str) : type_(stringValue), allocated_(true) {
        if (str == nullptr) {
            std::cerr << "Null pointer passed to string constructor" << std::endl;
            exit(1);
        }
        value_.string_ = copyString(str, strlen(str));
    }

    // Copy constructor
    Value(const Value& other) : type_(other.type_), allocated_(false) {
        switch (type_) {
            case nullValue:
                break;
            case intValue:
                value_.int_ = other.value_.int_;
                break;
            case uintValue:
                value_.uint_ = other.value_.uint_;
                break;
            case realValue:
                value_.real_ = other.value_.real_;
                break;
            case booleanValue:
                value_.bool_ = other.value_.bool_;
                break;
            case stringValue:
                if (other.allocated_ && other.value_.string_) {
                    value_.string_ = copyString(other.value_.string_, strlen(other.value_.string_));
                    allocated_ = true;
                } else {
                    value_.string_ = other.value_.string_;
                    allocated_ = false;
                }
                break;
            case arrayValue:
            case objectValue:
                value_.map_ = nullptr;
                break;
        }
    }

    // Destructor
    ~Value() {
        if (type_ == stringValue && allocated_ && value_.string_) {
            free(value_.string_);
        }
    }

    // Assignment operator
    Value& operator=(const Value& other) {
        if (this != &other) {
            // Clean up current resources
            if (type_ == stringValue && allocated_ && value_.string_) {
                free(value_.string_);
            }

            // Copy new data
            type_ = other.type_;
            allocated_ = false;

            switch (type_) {
                case nullValue:
                    break;
                case intValue:
                    value_.int_ = other.value_.int_;
                    break;
                case uintValue:
                    value_.uint_ = other.value_.uint_;
                    break;
                case realValue:
                    value_.real_ = other.value_.real_;
                    break;
                case booleanValue:
                    value_.bool_ = other.value_.bool_;
                    break;
                case stringValue:
                    if (other.allocated_ && other.value_.string_) {
                        value_.string_ = copyString(other.value_.string_, strlen(other.value_.string_));
                        allocated_ = true;
                    } else {
                        value_.string_ = other.value_.string_;
                        allocated_ = false;
                    }
                    break;
                case arrayValue:
                case objectValue:
                    value_.map_ = nullptr;
                    break;
            }
        }
        return *this;
    }

    // Type checking methods
    bool isNull() const { return type_ == nullValue; }
    bool isInt() const { return type_ == intValue; }
    bool isUInt() const { return type_ == uintValue; }
    bool isDouble() const { return type_ == realValue; }
    bool isBool() const { return type_ == booleanValue; }
    bool isString() const { return type_ == stringValue; }
    bool isArray() const { return type_ == arrayValue; }
    bool isObject() const { return type_ == objectValue; }

    // Conversion methods
    int asInt() const {
        if (type_ == intValue) return value_.int_;
        if (type_ == uintValue) return static_cast<int>(value_.uint_);
        if (type_ == realValue) return static_cast<int>(value_.real_);
        if (type_ == booleanValue) return value_.bool_ ? 1 : 0;
        return 0;
    }

    unsigned asUInt() const {
        if (type_ == uintValue) return value_.uint_;
        if (type_ == intValue) return static_cast<unsigned>(value_.int_);
        if (type_ == realValue) return static_cast<unsigned>(value_.real_);
        if (type_ == booleanValue) return value_.bool_ ? 1 : 0;
        return 0;
    }

    double asDouble() const {
        if (type_ == realValue) return value_.real_;
        if (type_ == intValue) return static_cast<double>(value_.int_);
        if (type_ == uintValue) return static_cast<double>(value_.uint_);
        if (type_ == booleanValue) return value_.bool_ ? 1.0 : 0.0;
        return 0.0;
    }

    bool asBool() const {
        if (type_ == booleanValue) return value_.bool_;
        if (type_ == nullValue) return false;
        if (type_ == intValue) return value_.int_ != 0;
        if (type_ == uintValue) return value_.uint_ != 0;
        if (type_ == realValue) return value_.real_ != 0.0;
        return false;
    }

    const char* asString() const {
        if (type_ == stringValue) return value_.string_ ? value_.string_ : "";
        return "";
    }

    // Comparison operators
    bool operator==(const Value& other) const {
        if (type_ != other.type_) return false;

        switch (type_) {
            case nullValue: return true;
            case intValue: return value_.int_ == other.value_.int_;
            case uintValue: return value_.uint_ == other.value_.uint_;
            case realValue: return value_.real_ == other.value_.real_;
            case booleanValue: return value_.bool_ == other.value_.bool_;
            case stringValue: 
                if (!value_.string_ && !other.value_.string_) return true;
                if (!value_.string_ || !other.value_.string_) return false;
                return strcmp(value_.string_, other.value_.string_) == 0;
            default: return false;
        }
    }

    bool operator!=(const Value& other) const {
        return !(*this == other);
    }

    // Get type
    ValueType getType() const { return type_; }
};

// Main function demonstrating usage
int main() {
    // Create various types of values
    Value nullVal;
    Value intVal(42);
    Value uintVal(100u);
    Value doubleVal(3.14);
    Value boolVal(true);
    Value stringVal("Hello, World!");

    // Test conversions
    std::cout << "Integer value: " << intVal.asInt() << std::endl;
    std::cout << "Unsigned value: " << uintVal.asUInt() << std::endl;
    std::cout << "Double value: " << doubleVal.asDouble() << std::endl;
    std::cout << "Boolean value: " << (boolVal.asBool() ? "true" : "false") << std::endl;
    std::cout << "String value: " << stringVal.asString() << std::endl;

    // Test equality
    Value intCopy(intVal);
    std::cout << "intVal == intCopy: " << (intVal == intCopy ? "true" : "false") << std::endl;

    return 0;
}

