// Rational type definition remains unchanged in structure but renamed internally
struct ExifRational {
    std::uint32_t num;
    std::uint32_t denom;

    operator double() const {
        if (denom < 1e-20) {
            return 0.0;
        }
        return static_cast<double>(num) / static_cast<double>(denom);
    }
};

// IF Entry class — refactored with manual memory management using unique_ptr
class IFEntry {
public:
    using byte_array = std::vector<std::uint8_t>;
    using ascii_str = std::string;
    using short_arr = std::vector<std::uint16_t>;
    using long_arr = std::vector<std::uint32_t>;
    using rational_arr = std::vector<ExifRational>;

    IFEntry()
        : tag_id_(0xFFFF),
          format_id_(0xFF),
          data_val_(0),
          elem_count_(0),
          bytes_(nullptr),
          strings_(nullptr),
          shorts_(nullptr),
          longs_(nullptr),
          rationals_(nullptr) {}

    ~IFEntry() {
        reset_fields();
    }

    // Move constructor
    IFEntry(IFEntry&& other) noexcept
        : tag_id_(other.tag_id_),
          format_id_(other.format_id_),
          data_val_(other.data_val_),
          elem_count_(other.elem_count_),
          bytes_(std::move(other.bytes_)),
          strings_(std::move(other.strings_)),
          shorts_(std::move(other.shorts_)),
          longs_(std::move(other.longs_)),
          rationals_(std::move(other.rationals_)) {
        other.tag_id_ = 0xFFFF;
        other.format_id_ = 0xFF;
        other.data_val_ = 0;
        other.elem_count_ = 0;
    }

    // Disable copy
    IFEntry(const IFEntry&) = delete;
    IFEntry& operator=(const IFEntry&) = delete;

    unsigned short get_tag() const { return tag_id_; }
    void set_tag(unsigned short t) { tag_id_ = t; }

    unsigned short get_format() const { return format_id_; }

    bool set_format(unsigned short fmt) {
        switch (fmt) {
            case 0x01: case 0x02: case 0x03:
            case 0x04: case 0x05: case 0x07:
            case 0x09: case 0x0a: case 0xff:
                break;
            default:
                return false;
        }
        reset_fields();
        format_id_ = fmt;
        allocate_fields();
        return true;
    }

    unsigned get_data_offset() const { return data_val_; }
    void set_data_offset(unsigned off) { data_val_ = off; }

    unsigned get_length() const { return elem_count_; }
    void set_length(unsigned len) { elem_count_ = len; }

    // Accessors
    byte_array& get_bytes() { return *bytes_; }
    ascii_str& get_string() { return *strings_; }
    short_arr& get_shorts() { return *shorts_; }
    long_arr& get_longs() { return *longs_; }
    rational_arr& get_rationals() { return *rationals_; }

private:
    void reset_fields() {
        switch (format_id_) {
            case 0x01: bytes_.reset(); break;
            case 0x02: strings_.reset(); break;
            case 0x03: shorts_.reset(); break;
            case 0x04: longs_.reset(); break;
            case 0x05: rationals_.reset(); break;
            default: break;
        }
    }

    void allocate_fields() {
        switch (format_id_) {
            case 0x01: bytes_ = std::make_unique<byte_array>(); break;
            case 0x02: strings_ = std::make_unique<ascii_str>(); break;
            case 0x03: shorts_ = std::make_unique<short_arr>(); break;
            case 0x04: longs_ = std::make_unique<long_arr>(); break;
            case 0x05: rationals_ = std::make_unique<rational_arr>(); break;
            default: break;
        }
    }

    unsigned short tag_id_;
    unsigned short format_id_;
    unsigned data_val_;
    unsigned elem_count_;

    std::unique_ptr<byte_array> bytes_;
    std::unique_ptr<ascii_str> strings_;
    std::unique_ptr<short_arr> shorts_;
    std::unique_ptr<long_arr> longs_;
    std::unique_ptr<rational_arr> rationals_;
};

// Template-based parsing functions — reordered and slightly refactored
template <typename T, bool littleEndian>
T read_value(const unsigned char* ptr);

template <>
std::uint8_t read_value<std::uint8_t, false>(const unsigned char* p) {
    return *p;
}

template <>
std::uint8_t read_value<std::uint8_t, true>(const unsigned char* p) {
    return *p;
}

template <>
std::uint16_t read_value<std::uint16_t, false>(const unsigned char* p) {
    return (static_cast<std::uint16_t>(p[0]) << 8) | p[1];
}

template <>
std::uint16_t read_value<std::uint16_t, true>(const unsigned char* p) {
    return (static_cast<std::uint16_t>(p[1]) << 8) | p[0];
}

template <>
std::uint32_t read_value<std::uint32_t, false>(const unsigned char* p) {
    return (static_cast<std::uint32_t>(p[0]) << 24) |
           (static_cast<std::uint32_t>(p[1]) << 16) |
           (static_cast<std::uint32_t>(p[2]) << 8) | p[3];
}

template <>
std::uint32_t read_value<std::uint32_t, true>(const unsigned char* p) {
    return (static_cast<std::uint32_t>(p[3]) << 24) |
           (static_cast<std::uint32_t>(p[2]) << 16) |
           (static_cast<std::uint32_t>(p[1]) << 8) | p[0];
}

template <>
ExifRational read_value<ExifRational, true>(const unsigned char* p) {
    ExifRational r;
    r.num = read_value<std::uint32_t, true>(p);
    r.denom = read_value<std::uint32_t, true>(p + 4);
    return r;
}

template <>
ExifRational read_value<ExifRational, false>(const unsigned char* p) {
    ExifRational r;
    r.num = read_value<std::uint32_t, false>(p);
    r.denom = read_value<std::uint32_t, false>(p + 4);
    return r;
}

// Extract values into container — rewritten using while loop instead of for
template <typename T, bool littleEndian, typename Container>
bool extract_into(Container& out, const unsigned char* base,
                  unsigned offset_base, unsigned total_len, const IFEntry& entry) {
    const unsigned char* src;
    std::uint32_t temp_data = 0;

    if (sizeof(T) * entry.get_length() <= 4) {
        if (littleEndian) {
            temp_data = entry.get_data_offset();
        } else {
            temp_data = entry.get_data_offset();
            unsigned char* tmp = reinterpret_cast<unsigned char*>(&temp_data);
            std::swap(tmp[0], tmp[3]);
            std::swap(tmp[1], tmp[2]);
        }
        src = reinterpret_cast<const unsigned char*>(&temp_data);
    } else {
        src = base + offset_base + entry.get_data_offset();
        if (src + sizeof(T) * entry.get_length() > base + total_len) {
            return false;
        }
    }

    out.resize(entry.get_length());
    size_t idx = 0;
    while (idx < entry.get_length()) {
        out[idx] = read_value<T, littleEndian>(src + sizeof(T) * idx);
        ++idx;
    }
    return true;
}

// Helper to parse IFD header fields
template <bool littleEndian>
void parse_header(const unsigned char* buf,
                  unsigned short& tag, unsigned short& fmt,
                  unsigned& count, unsigned& off) {
    tag = read_value<std::uint16_t, littleEndian>(buf);
    fmt = read_value<std::uint16_t, littleEndian>(buf + 2);
    count = read_value<std::uint32_t, littleEndian>(buf + 4);
    off = read_value<std::uint32_t, littleEndian>(buf + 8);
}

template <bool littleEndian>
void parse_header(const unsigned char* buf, IFEntry& ent) {
    unsigned short t, f;
    unsigned c, o;
    parse_header<littleEndian>(buf, t, f, c, o);
    ent.set_tag(t);
    ent.set_format(f);
    ent.set_length(c);
    ent.set_data_offset(o);
}

// Main parsing function for one IF entry
template <bool littleEndian>
IFEntry parse_entry(const unsigned char* buf, unsigned offset,
                    unsigned base, unsigned length) {
    IFEntry result;

    if (offset + 12 > length || !buf) {
        result.set_tag(0xFFFF);
        return result;
    }

    parse_header<littleEndian>(buf + offset, result);

    switch (result.get_format()) {
        case 1:
            if (!extract_into<std::uint8_t, littleEndian>(result.get_bytes(), buf, base, length, result)) {
                result.set_tag(0xFFFF);
            }
            break;
        case 2:
            if (!extract_into<std::uint8_t, littleEndian>(result.get_string(), buf, base, length, result)) {
                result.set_tag(0xFFFF);
            } else {
                auto& s = result.get_string();
                if (!s.empty() && s.back() == '\0') {
                    s.pop_back();
                }
            }
            break;
        case 3:
            if (!extract_into<std::uint16_t, littleEndian>(result.get_shorts(), buf, base, length, result)) {
                result.set_tag(0xFFFF);
            }
            break;
        case 4:
            if (!extract_into<std::uint32_t, littleEndian>(result.get_longs(), buf, base, length, result)) {
                result.set_tag(0xFFFF);
            }
            break;
        case 5:
            if (!extract_into<ExifRational, littleEndian>(result.get_rationals(), buf, base, length, result)) {
                result.set_tag(0xFFFF);
            }
            break;
        case 7: case 9: case 10:
            break;
        default:
            result.set_tag(0xFFFF);
    }

    return result;
}

// Wrapper for generic parsing
template <typename T>
T read_single(const unsigned char* ptr, bool little) {
    return little ? read_value<T, true>(ptr) : read_value<T, false>(ptr);
}

void read_header(const unsigned char* ptr, bool little,
                 unsigned short& tag, unsigned short& fmt,
                 unsigned& cnt, unsigned& off) {
    if (little)
        parse_header<true>(ptr, tag, fmt, cnt, off);
    else
        parse_header<false>(ptr, tag, fmt, cnt, off);
}

IFEntry parse_single_entry(const unsigned char* buf, unsigned off,
                           bool little, unsigned base, unsigned len) {
    return little ? parse_entry<true>(buf, off, base, len)
                  : parse_entry<false>(buf, off, base, len);
}

