struct GeoLocationData {
    double Latitude, Longitude, Altitude;
    unsigned char AltitudeRef;
    double DOP;
    GeoComponents LatComponents, LonComponents;
};
struct LensInfoData {
    double FocalLengthMin, FocalLengthMax, FStopMin, FStopMax;
    double FocalPlaneXResolution, FocalPlaneYResolution;
    unsigned short FocalPlaneResolutionUnit;
    std::string Make, Model;
    int FocalLengthIn35mm;
};
struct EXIFInfo {
    // Strings
    std::string ImageDescription, Make, Model, Software, DateTime;
    std::string DateTimeOriginal, DateTimeDigitized, SubSecTimeOriginal, Copyright[redacted]

    // Shorts / unsigned / double
    unsigned ByteAlign, Orientation, BitsPerSample, ExposureProgram, ISOSpeedRatings;
    unsigned Flash, FlashReturnedLight, FlashMode, MeteringMode, ColorSpace;
    double ExposureTime, FNumber, ShutterSpeedValue, ExposureBiasValue, SubjectDistance, FocalLength;
    unsigned ImageWidth, ImageHeight;

    // Geolocation
    GeoLocationData GeoLocation;

    // Lens info
    LensInfoData LensInfo;

    int parseFrom(const unsigned char* buf, unsigned len);
    int parseFrom(const std::string& data);
    int parseFromEXIFSegment(const unsigned char* buf, unsigned len);
    void clear();
};
}

#define PARSE_EXIF_SUCCESS 0
#define PARSE_EXIF_ERROR_NO_JPEG -1
#define PARSE_EXIF_ERROR_NO_EXIF -2
#define PARSE_EXIF_ERROR_CORRUPT -3
#define PARSE_EXIF_ERROR_UNKNOWN_BYTEALIGN -4

int easyexif::EXIFInfo::parseFrom(const unsigned char* buf, unsigned len) {
    if (!buf || len < 4) return PARSE_EXIF_ERROR_NO_JPEG;
    if (buf[0] != 0xFF || buf[1] != 0xD8) return PARSE_EXIF_ERROR_NO_JPEG;

    while (len > 2) {
        if (buf[len - 1] == 0xD9 && buf[len - 2] == 0xFF) break;
        --len;
    }
    if (len <= 2) return PARSE_EXIF_ERROR_NO_JPEG;

    clear();

    unsigned i = 0;
    while (i < len - 1) {
        if (buf[i] == 0xFF && buf[i + 1] == 0xE1) break;
        ++i;
    }
    if (i + 4 > len) return PARSE_EXIF_ERROR_NO_EXIF;

    i += 2;
    unsigned section_len = read_single<std::uint16_t>(buf + i, false);
    if (i + section_len > len || section_len < 16) return PARSE_EXIF_ERROR_CORRUPT;
    i += 2;

    return parseFromEXIFSegment(buf + i, len - i);
}

int easyexif::EXIFInfo::parseFrom(const std::string& data) {
    return parseFrom(
        reinterpret_cast<const unsigned char*>(data.data()),
        static_cast<unsigned>(data.size()));
}

int easyexif::EXIFInfo::parseFromEXIFSegment(const unsigned char* buf, unsigned len) {
    bool intel_byte_order = true;
    unsigned offset = 0;

    if (!buf || len < 6) return PARSE_EXIF_ERROR_NO_EXIF;
    if (std::memcmp(buf, "Exif\0\0", 6) != 0) return PARSE_EXIF_ERROR_NO_EXIF;
    offset += 6;

    unsigned tiff_start = offset;
    if (buf[offset] == 'I' && buf[offset + 1] == 'I')
        intel_byte_order = true;
    else if (buf[offset] == 'M' && buf[offset + 1] == 'M')
        intel_byte_order = false;
    else
        return PARSE_EXIF_ERROR_UNKNOWN_BYTEALIGN;

    this->ByteAlign = intel_byte_order;
    offset += 2;

    if (read_single<std::uint16_t>(buf + offset, intel_byte_order) != 0x2A)
        return PARSE_EXIF_ERROR_CORRUPT;
    offset += 2;

    unsigned first_ifd = read_single<std::uint32_t>(buf + offset, intel_byte_order);
    offset += first_ifd - 4;
    if (offset >= len) return PARSE_EXIF_ERROR_CORRUPT;

    if (offset + 2 > len) return PARSE_EXIF_ERROR_CORRUPT;
    int num_entries = read_single<std::uint16_t>(buf + offset, intel_byte_order);
    if (offset + 6 + 12 * num_entries > len) return PARSE_EXIF_ERROR_CORRUPT;
    offset += 2;

    unsigned exif_sub_offset = len;
    unsigned gps_sub_offset = len;

    while (num_entries-- > 0) {
        IFEntry entry = parse_single_entry(buf, offset, intel_byte_order, tiff_start, len);
        offset += 12;

        switch (entry.get_tag()) {
            case 0x102: // Bits per sample
                if (entry.get_format() == 3 && !entry.get_shorts().empty())
                    this->BitsPerSample = entry.get_shorts()[0];
                break;
            case 0x10E: // Image description
                if (entry.get_format() == 2) this->ImageDescription = entry.get_string();
                break;
            case 0x10F: // Digicam make
                if (entry.get_format() == 2) this->Make = entry.get_string();
                break;
            case 0x110: // Digicam model
                if (entry.get_format() == 2) this->Model = entry.get_string();
                break;
            case 0x112: // Orientation
                if (entry.get_format() == 3 && !entry.get_shorts().empty())
                    this->Orientation = entry.get_shorts()[0];
                break;
            case 0x131: // Software
                if (entry.get_format() == 2) this->Software = entry.get_string();
                break;
            case 0x132: // Date/Time
                if (entry.get_format() == 2) this->DateTime = entry.get_string();
                break;
            case 0x8298: // Copyright
                [redacted]
                break;
            case 0x8825: // GPS IFD
                gps_sub_offset = tiff_start + entry.get_data_offset();
                break;
            case 0x8769: // EXIF SubIFD
                exif_sub_offset = tiff_start + entry.get_data_offset();
                break;
        }
    }

    // Parse EXIF SubIFD
    if (exif_sub_offset + 4 <= len) {
        offset = exif_sub_offset;
        int sub_count = read_single<std::uint16_t>(buf + offset, intel_byte_order);
        if (offset + 6 + 12 * sub_count > len) return PARSE_EXIF_ERROR_CORRUPT;
        offset += 2;

        while (sub_count-- > 0) {
            IFEntry entry = parse_single_entry(buf, offset, intel_byte_order, tiff_start, len);
            offset += 12;

            switch (entry.get_tag()) {
                case 0x829A: // Exposure time
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->ExposureTime = entry.get_rationals()[0];
                    break;
                case 0x829D: // F-number
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->FNumber = entry.get_rationals()[0];
                    break;
                case 0x8822: // Exposure program
                    if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->ExposureProgram = entry.get_shorts()[0];
                    break;
                case 0x8827: // ISO speed
                    if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->ISOSpeedRatings = entry.get_shorts()[0];
                    break;
                case 0x9003: // Original date/time
                    if (entry.get_format() == 2) this->DateTimeOriginal = entry.get_string();
                    break;
                case 0x9004: // Digitization date/time
                    if (entry.get_format() == 2) this->DateTimeDigitized = entry.get_string();
                    break;
                case 0x9201: // Shutter speed
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->ShutterSpeedValue = entry.get_rationals()[0];
                    break;
                case 0x9204: // Exposure bias
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->ExposureBiasValue = entry.get_rationals()[0];
                    break;
                case 0x9206: // Subject distance
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->SubjectDistance = entry.get_rationals()[0];
                    break;
                case 0x9209: // Flash
                    if (entry.get_format() == 3 && !entry.get_shorts().empty()) {
                        unsigned short val = entry.get_shorts()[0];
                        this->Flash = val & 1;
                        this->FlashReturnedLight = (val & 6) >> 1;
                        this->FlashMode = (val & 24) >> 3;
                    }
                    break;
                case 0x920A: // Focal length
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->FocalLength = entry.get_rationals()[0];
                    break;
                case 0xA405: // Focal length in 35mm
                    if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->LensInfo.FocalLengthIn35mm = entry.get_shorts()[0];
                    break;
                case 0x9207: // Metering mode
                    if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->MeteringMode = entry.get_shorts()[0];
                    break;
                case 0x9291: // Subsecond original
                    if (entry.get_format() == 2) this->SubSecTimeOriginal = entry.get_string();
                    break;
                case 0xA001: // Color space
                    if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->ColorSpace = entry.get_shorts()[0];
                    break;
                case 0xA002: // Width
                    if (entry.get_format() == 4 && !entry.get_longs().empty())
                        this->ImageWidth = entry.get_longs()[0];
                    else if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->ImageWidth = entry.get_shorts()[0];
                    break;
                case 0xA003: // Height
                    if (entry.get_format() == 4 && !entry.get_longs().empty())
                        this->ImageHeight = entry.get_longs()[0];
                    else if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->ImageHeight = entry.get_shorts()[0];
                    break;
                case 0xA20E: // Focal plane X res
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->LensInfo.FocalPlaneXResolution = entry.get_rationals()[0];
                    break;
                case 0xA20F: // Focal plane Y res
                    if (entry.get_format() == 5 && !entry.get_rationals().empty())
                        this->LensInfo.FocalPlaneYResolution = entry.get_rationals()[0];
                    break;
                case 0xA210: // Focal plane res unit
                    if (entry.get_format() == 3 && !entry.get_shorts().empty())
                        this->LensInfo.FocalPlaneResolutionUnit = entry.get_shorts()[0];
                    break;
                case 0xA432: // Focal length range
                    if (entry.get_format() == 5) {
                        auto& vec = entry.get_rationals();
                        if (vec.size() > 0) this->LensInfo.FocalLengthMin = vec[0];
                        if (vec.size() > 1) this->LensInfo.FocalLengthMax = vec[1];
                        if (vec.size() > 2) this->LensInfo.FStopMin = vec[2];
                        if (vec.size() > 3) this->LensInfo.FStopMax = vec[3];
                    }
                    break;
                case 0xA433: // Lens make
                    if (entry.get_format() == 2) this->LensInfo.Make = entry.get_string();
                    break;
                case 0xA434: // Lens model
                    if (entry.get_format() == 2) this->LensInfo.Model = entry.get_string();
                    break;
            }
        }
    }

    // Parse GPS IFD
    if (gps_sub_offset + 4 <= len) {
        offset = gps_sub_offset;
        int gps_count = read_single<std::uint16_t>(buf + offset, intel_byte_order);
        if (offset + 6 + 12 * gps_count > len) return PARSE_EXIF_ERROR_CORRUPT;
        offset += 2;

        while (gps_count-- > 0) {
            unsigned short tag, fmt;
            unsigned cnt, off;
            read_header(buf + offset, intel_byte_order, tag, fmt, cnt, off);

            switch (tag) {
                case 1: // NS direction
                    this->GeoLocation.LatComponents.direction = *(buf + offset + 8);
                    if (this->GeoLocation.LatComponents.direction == 0)
                        this->GeoLocation.LatComponents.direction = '?';
                    if (this->GeoLocation.LatComponents.direction == 'S')
                        this->GeoLocation.Latitude = -this->GeoLocation.Latitude;
                    break;
                case 2: // Latitude
                    if ((fmt == 5 || fmt == 10) && cnt == 3) {
                        this->GeoLocation.LatComponents.degrees =
                            read_single<ExifRational>(buf + off + tiff_start, intel_byte_order);
                        this->GeoLocation.LatComponents.minutes =
                            read_single<ExifRational>(buf + off + tiff_start + 8, intel_byte_order);
                        this->GeoLocation.LatComponents.seconds =
                            read_single<ExifRational>(buf + off + tiff_start + 16, intel_byte_order);
                        this->GeoLocation.Latitude =
                            this->GeoLocation.LatComponents.degrees +
                            this->GeoLocation.LatComponents.minutes / 60.0 +
                            this->GeoLocation.LatComponents.seconds / 3600.0;
                        if (this->GeoLocation.LatComponents.direction == 'S')
                            this->GeoLocation.Latitude = -this->GeoLocation.Latitude;
                    }
                    break;
                case 3: // EW direction
                    this->GeoLocation.LonComponents.direction = *(buf + offset + 8);
                    if (this->GeoLocation.LonComponents.direction == 0)
                        this->GeoLocation.LonComponents.direction = '?';
                    if (this->GeoLocation.LonComponents.direction == 'W')
                        this->GeoLocation.Longitude = -this->GeoLocation.Longitude;
                    break;
                case 4: // Longitude
                    if ((fmt == 5 || fmt == 10) && cnt == 3) {
                        this->GeoLocation.LonComponents.degrees =
                            read_single<ExifRational>(buf + off + tiff_start, intel_byte_order);
                        this->GeoLocation.LonComponents.minutes =
                            read_single<ExifRational>(buf + off + tiff_start + 8, intel_byte_order);
                        this->GeoLocation.LonComponents.seconds =
                            read_single<ExifRational>(buf + off + tiff_start + 16, intel_byte_order);
                        this->GeoLocation.Longitude =
                            this->GeoLocation.LonComponents.degrees +
                            this->GeoLocation.LonComponents.minutes / 60.0 +
                            this->GeoLocation.LonComponents.seconds / 3600.0;
                        if (this->GeoLocation.LonComponents.direction == 'W')
                            this->GeoLocation.Longitude = -this->GeoLocation.Longitude;
                    }
                    break;
                case 5: // Altitude ref
                    this->GeoLocation.AltitudeRef = *(buf + offset + 8);
                    if (this->GeoLocation.AltitudeRef == 1)
                        this->GeoLocation.Altitude = -this->GeoLocation.Altitude;
                    break;
                case 6: // Altitude
                    if (fmt == 5 || fmt == 10) {
                        this->GeoLocation.Altitude =
                            read_single<ExifRational>(buf + off + tiff_start, intel_byte_order);
                        if (this->GeoLocation.AltitudeRef == 1)
                            this->GeoLocation.Altitude = -this->GeoLocation.Altitude;
                    }
                    break;
                case 11: // DOP
                    if (fmt == 5 || fmt == 10)
                        this->GeoLocation.DOP =
                            read_single<ExifRational>(buf + off + tiff_start, intel_byte_order);
                    break;
            }
            offset += 12;
        }
    }

    return PARSE_EXIF_SUCCESS;
}

