enum TokenClass : uint32_t
{
    TC_EOF          = 1 << 0,
    TC_LineBreak    = 1 << 1,
    TC_LBrace       = 1 << 2,
    TC_RBrace       = 1 << 3,
    TC_Assign       = 1 << 4,
    TC_SemiColon    = 1 << 5,
    TC_CommaTok     = 1 << 6,
    TC_RParen       = 1 << 7,
    TC_CommentTok   = 1 << 8,
    TC_Name         = 1 << 9,
    TC_NumLiteral   = 1 << 10,
    TC_ParenList    = 1 << 11,
    TC_QuotedStr    = 1 << 12,
    TC_SyntaxWord   = 1 << 13,
    TC_ColonTok     = 1 << 14,
    TC_LBracket     = 1 << 15,
    TC_RBracket     = 1 << 16,
    TC_HexIndy      = 1 << 17,

    /* Composite token types */
    TCC_AnyKey      = TC_Name | TC_NumLiteral | TC_ParenList | TC_QuotedStr | TC_SyntaxWord,
    TCC_DataValue   = TC_NumLiteral | TC_QuotedStr | TC_SyntaxWord,
    TCC_Terminals   = TC_EOF | TC_LineBreak | TC_LBrace | TC_RBrace | TC_CommentTok | TC_SemiColon,
    TCC_Distinct    = TC_CommentTok | TC_Name | TC_NumLiteral | TC_ParenList | TC_QuotedStr | TC_SyntaxWord
};

