#include <OTwo/UI/Playing/ComboCounter.hpp>
#include <OTwo/States/State.hpp>
#include <Genode/Tasks/Action.hpp>
#include <Genode/Tasks/Scheduler.hpp>
#include <Genode/Tween/Move.hpp>

ComboCounter::ComboCounter(Gx::Animation* titleSprite, Gx::BitmapNumber* digitDisplay) :
    m_title(titleSprite),
    m_digit(digitDisplay)
{
    if (m_title)
        AddChild(*m_title);
    if (m_digit)
        AddChild(*m_digit);
}

void ComboCounter::Initialize()
{
    Gx::Node::Initialize();
    SetPosition(sf::Vector2f(0.f, -6.f)); // -30 / 5 = -6

    // Build animation sequence: hide → reset & show → bounce up → wait
    m_sequence = Gx::Sequence([this]
        {
            if (m_title)
                m_title->Stop();
            SetVisible(false);
        },
        Gx::TaskGroup
        (
            Gx::Action([this]
            {
                if (m_title)
                    m_title->Reset();
                SetVisible(true);
            }),
            Gx::Move(*m_title,
                     sf::Vector2f(m_title->GetPosition().x, m_title->GetPosition().y - 8.f),
                     sf::seconds(1.f / 60.f * 5)),
            Gx::Move(*m_digit,
                     sf::Vector2f(m_digit->GetPosition().x, m_digit->GetPosition().y - 23.f),
                     sf::seconds(1.f / 60.f * 5))
        ),
        Gx::Delay(sf::milliseconds(1000))
    );

    // Pre-record initial transform state
    m_sequence.Update(0.0);
    m_sequence.Stop();
    SetVisible(false);
}

unsigned int ComboCounter::GetCurrentCount() const
{
    return m_digit ? m_digit->GetValue() : 0u;
}

void ComboCounter::SetCurrentCount(const unsigned int count)
{
    if (m_digit)
        m_digit->SetValue(count);

    if (count != 0u)
    {
        SetVisible(true);
        m_sequence.Reset();
    }
    else
    {
        SetVisible(false);
        m_sequence.Complete();
    }
}

void ComboCounter::Tick(const double elapsed)
{
    m_sequence.Update(elapsed);
    Gx::UpdatableContainer::Tick(elapsed);
}

Gx::RenderStates ComboCounter::Draw(Gx::RenderSurface& target, Gx::RenderStates ctx) const
{
    if (!IsVisible())
        return ctx;

    ctx.transform *= GetTransform();

    if (m_title)
        target.Render(*m_title, ctx);
    if (m_digit)
        target.Render(*m_digit, ctx);

    return ctx;
}

