// Static instance for singleton access
Frustum* Frustum::frustum = new Frustum();

Frustum::Frustum() {
    _projectionMatrix = MemoryTracker::createFloatBuffer(16);
    _modelviewMatrix  = MemoryTracker::createFloatBuffer(16);
    _combinedClip     = MemoryTracker::createFloatBuffer(16);
}

Frustum::~Frustum() {
    delete _projectionMatrix;
    delete _modelviewMatrix;
    delete _combinedClip;
}

FrustumData* Frustum::getFrustum() {
    computeViewVolume();
    return frustum;
}

// Helper: Normalize a plane vector (A, B, C, D) to unit length
void Frustum::normalizePlane(float (**planes), int index) {
    float length = std::sqrt(
        planes[index][X] * planes[index][X] +
        planes[index][Y] * planes[index][Y] +
        planes[index][Z] * planes[index][Z]
    );

    if (length != 0.0f) {
        planes[index][X] /= length;
        planes[index][Y] /= length;
        planes[index][Z] /= length;
        planes[index][W] /= length;
    }
}

void Frustum::computeViewVolume() {
    // Clear buffers before use
    _projectionMatrix->clear();
    _modelviewMatrix->clear();
    _combinedClip->clear();

    // Retrieve current OpenGL matrices
    glGetFloat(GL_PROJECTION_MATRIX, _projectionMatrix);
    glGetFloat(GL_MODELVIEW_MATRIX,  _modelviewMatrix);

    // Prepare matrices for reading
    _projectionMatrix->flip()->limit(16);
    _projectionMatrix->get(&_projArray[0]);

    _modelviewMatrix->flip()->limit(16);
    _modelviewMatrix->get(&_modlArray[0]);

    // Compute combined clip matrix: clip = modelview × projection
    // Row-major multiplication: each row of result is linear combo of proj rows weighted by modl row
    for (int r = 0; r < 4; ++r) {
        for (int c = 0; c < 4; ++c) {
            float acc = 0.0f;
            for (int k = 0; k < 4; ++k) {
                acc += _modlArray[r * 4 + k] * _projArray[k * 4 + c];
            }
            _clipArray[r * 4 + c] = acc;
        }
    }

    // Extract frustum planes from clip matrix
    // Right plane: clip[3] - clip[0]
    m_Frustum[RIGHT][X] = _clipArray[3] - _clipArray[0];
    m_Frustum[RIGHT][Y] = _clipArray[7] - _clipArray[4];
    m_Frustum[RIGHT][Z] = _clipArray[11] - _clipArray[8];
    m_Frustum[RIGHT][W] = _clipArray[15] - _clipArray[12];

    // Left plane: clip[3] + clip[0]
    m_Frustum[LEFT][X] = _clipArray[3] + _clipArray[0];
    m_Frustum[LEFT][Y] = _clipArray[7] + _clipArray[4];
    m_Frustum[LEFT][Z] = _clipArray[11] + _clipArray[8];
    m_Frustum[LEFT][W] = _clipArray[15] + _clipArray[12];

    // Bottom plane: clip[3] + clip[1]
    m_Frustum[BOTTOM][X] = _clipArray[3] + _clipArray[1];
    m_Frustum[BOTTOM][Y] = _clipArray[7] + _clipArray[5];
    m_Frustum[BOTTOM][Z] = _clipArray[11] + _clipArray[9];
    m_Frustum[BOTTOM][W] = _clipArray[15] + _clipArray[13];

    // Top plane: clip[3] - clip[1]
    m_Frustum[TOP][X] = _clipArray[3] - _clipArray[1];
    m_Frustum[TOP][Y] = _clipArray[7] - _clipArray[5];
    m_Frustum[TOP][Z] = _clipArray[11] - _clipArray[9];
    m_Frustum[TOP][W] = _clipArray[15] - _clipArray[13];

    // Back plane: clip[3] - clip[2]
    m_Frustum[BACK][X] = _clipArray[3] - _clipArray[2];
    m_Frustum[BACK][Y] = _clipArray[7] - _clipArray[6];
    m_Frustum[BACK][Z] = _clipArray[11] - _clipArray[10];
    m_Frustum[BACK][W] = _clipArray[15] - _clipArray[14];

    // Front plane: clip[3] + clip[2]
    m_Frustum[FRONT][X] = _clipArray[3] + _clipArray[2];
    m_Frustum[FRONT][Y] = _clipArray[7] + _clipArray[6];
    m_Frustum[FRONT][Z] = _clipArray[11] + _clipArray[10];
    m_Frustum[FRONT][W] = _clipArray[15] + _clipArray[14];

    // Normalize all six planes
    normalizePlane(m_Frustum, RIGHT);
    normalizePlane(m_Frustum, LEFT);
    normalizePlane(m_Frustum, BOTTOM);
    normalizePlane(m_Frustum, TOP);
    normalizePlane(m_Frustum, BACK);
    normalizePlane(m_Frustum, FRONT);
}

