// Helper: safely copy string into fixed-size char buffer
inline std::vector<char> prepare_buffer(const std::string& input, size_t buf_size) {
    std::vector<char> buffer(buf_size, '\0');
    if (!input.empty()) {
        size_t len = std::min(input.size(), buf_size - 1);
        std::copy_n(input.begin(), len, buffer.data());
    }
    return buffer;
}

// Helper: extract payload as variant-like object
inline py::object try_accept_payload(InfGUIContext& ctx, const std::string& type) {
    // Try uint64 first
    uint64_t int_data = 0;
    if (ctx.AcceptDragDropPayload(type, &int_data)) {
        return py::cast(int_data);
    }

    // Then try string
    std::string str_data;
    if (ctx.AcceptDragDropPayload(type, &str_data)) {
        return py::cast(str_data);
    }

    return py::none();
}

// Wrapper class for overriding OnRender in Python
class PyGUIRenderable : public InfGUIRenderable {
public:
    using InfGUIRenderable::InfGUIRenderable;
    void OnRender(InfGUIContext* ctx) override {
        PYBIND11_OVERRIDE_NAME(void, InfGUIRenderable, "on_render", OnRender, ctx);
    }
};

