/*****************************************************************************
 NdbSchemaOp(Ndb* aNdb)
 Return Value:  None
 Parameters:    aNdb: Pointer to the Ndb object.
 Remark:        Constructs an NdbSchemaOp instance.
*****************************************************************************/
NdbSchemaOp::NdbSchemaOp(Ndb *aNdb)
    : theNdb(aNdb),
      theSchemaCon(nullptr),
      m_currentTable(nullptr) {}

/*****************************************************************************
 ~NdbSchemaOp()
 Remark:        Destructor; cleans up internal resources.
*****************************************************************************/
NdbSchemaOp::~NdbSchemaOp() {}

/*****************************************************************************
 int createTable(const char* tableName, ...)
 Return Value:  0 on success, -1 if table already being built.
 Parameters:    Various table creation parameters.
 Remark:        Begins construction of a new table definition.
*****************************************************************************/
int NdbSchemaOp::createTable(const char *tblName, Uint32 tblSize,
                             KeyType keyType, int nrOfPages,
                             FragmentType fragType, int kVal,
                             int minLF, int maxLF,
                             int memType, bool storedFlag) {
  if (!m_currentTable) {
    m_currentTable = new NdbDictionary::Table(tblName);
    m_currentTable->setKValue(kVal);
    m_currentTable->setMinLoadFactor(minLF);
    m_currentTable->setMaxLoadFactor(maxLF);
    m_currentTable->setLogging(storedFlag);
    m_currentTable->setFragmentType(NdbDictionary::Object::FragAllMedium);
    return 0;
  }
  return -1;
}

/*****************************************************************************
 int createAttribute(...)
 Return Value:  0 on success, -1 if no active table.
 Parameters:    Column definition parameters.
 Remark:        Adds a column to the current table under construction.
*****************************************************************************/
int NdbSchemaOp::createAttribute(
    const char *colName, KeyType pkFlag, int colSize, int arrayLen,
    AttrType typeCode, StorageMode storageMode, bool isNullable,
    int storageAttr, int distKeyFlag, int distGroupFlag,
    int distGroupBits, bool autoInc, const char *defaultValue) {
  if (!m_currentTable) {
    return -1;
  }

  NdbDictionary::Column column(colName);

  // Map logical types to dictionary column types
  if (typeCode == Signed) {
    column.setType(colSize == 64 ? NdbDictionary::Column::Bigint
                                 : NdbDictionary::Column::Int);
  } else if (typeCode == UnSigned) {
    column.setType(colSize == 64 ? NdbDictionary::Column::Bigunsigned
                                 : NdbDictionary::Column::Unsigned);
  } else if (typeCode == Float) {
    column.setType(colSize == 64 ? NdbDictionary::Column::Double
                                 : NdbDictionary::Column::Float);
  } else if (typeCode == String) {
    column.setType(NdbDictionary::Column::Char);
  } else {
    abort(); // Unsupported type
  }

  column.setLength(arrayLen);
  column.setNullable(isNullable);
  column.setPrimaryKey(pkFlag != NoKey);
  column.setDistributionKey(distKeyFlag);
  column.setAutoIncrement(autoInc);
  column.setDefaultValue(defaultValue ? defaultValue : "");

  m_currentTable->addColumn(column);
  return 0;
}

/*****************************************************************************
 void release()
 Remark:        Placeholder for releasing schema-related resources.
*****************************************************************************/
void NdbSchemaOp::release() {}

/*****************************************************************************
 int sendRec()
 Return Value:  0 on successful table creation, -1 otherwise.
 Parameters:    None.
 Remark:        Submits the constructed table to the database.
*****************************************************************************/
int NdbSchemaOp::sendRec() {
  if (!m_currentTable) {
    return -1;
  }

  int result = theNdb->getDictionary()->createTable(*m_currentTable);
  delete m_currentTable;
  m_currentTable = nullptr;

  if (theSchemaCon) {
    theSchemaCon->theError.code = theNdb->getDictionary()->getNdbError().code;
  }

  return result == 0 ? 0 : -1;
}

/*****************************************************************************
 int init(NdbSchemaCon*)
 Return Value:  Always returns 0.
 Parameters:    Schema connection pointer.
 Remark:        Initializes internal schema connection reference.
*****************************************************************************/
int NdbSchemaOp::init(NdbSchemaCon *schemaConn) {
  theSchemaCon = schemaConn;
  return 0;
}

const NdbError &NdbSchemaOp::getNdbError() const {
  static const NdbError dummyError;
  return theSchemaCon ? theSchemaCon->getNdbError() : dummyError;
}

