    // Helper to convert Alembic trim curve data into Maya-compatible MObjectArray
    void extractTrimCurves(const Alembic::AbcGeom::INuPatchSchema::Sample &sample,
                           MObjectArray &outCurves) {
        const auto numLoops = sample.getTrimNumLoops();
        if (numLoops == 0) return;

        const auto numCurvesPerLoop = sample.getTrimNumCurves();
        const auto numVerticesPerCurve = sample.getTrimNumVertices();
        const auto curveOrders = sample.getTrimOrders();
        const auto knotValues = sample.getTrimKnots();
        const auto uCoords = sample.getTrimU();
        const auto vCoords = sample.getTrimV();
        const auto wCoords = sample.getTrimW();

        size_t globalCurveIdx = 0;
        size_t globalVertexIdx = 0;
        size_t globalKnotIdx = 0;

        for (size_t loopIdx = 0; loopIdx < numLoops; ++loopIdx) {
            MObjectArray currentLoop;
            const auto numCurvesInThisLoop = (*numCurvesPerLoop)[loopIdx];

            for (size_t curveIdx = 0; curveIdx < numCurvesInThisLoop; ++curveIdx, ++globalCurveIdx) {
                const unsigned int order = static_cast<unsigned int>((*curveOrders)[globalCurveIdx]);
                const unsigned int degree = order - 1;
                const auto numVerts = static_cast<unsigned int>((*numVerticesPerCurve)[globalCurveIdx]);
                const auto numKnots = numVerts + degree + 1;

                MPointArray cvs;
                cvs.setLength(numVerts);

                for (unsigned int vertIdx = 0; vertIdx < numVerts; ++vertIdx, ++globalVertexIdx) {
                    const double x = (*uCoords)[globalVertexIdx];
                    const double y = (*vCoords)[globalVertexIdx];
                    const double w = (*wCoords)[globalVertexIdx];
                    cvs.set(vertIdx, x, y, 0.0, w);
                }

                MDoubleArray knots;
                knots.setLength(numKnots - 2);
                ++globalKnotIdx;
                for (unsigned int k = 1; k < numKnots - 1; ++k, ++globalKnotIdx) {
                    knots.set((*knotValues)[globalKnotIdx], k - 1);
                }
                ++globalKnotIdx;

                MFnNurbsCurve fnCurve;
                MFnNurbsCurveData dataCreator;
                MObject curveDataObj = dataCreator.create();
                MStatus status;
                MObject createdCurve = fnCurve.create(cvs, knots, degree,
                    MFnNurbsCurve::kOpen, true, true, curveDataObj, &status);

                if (status == MS::kSuccess) {
                    currentLoop.append(curveDataObj);
                }
            }

            outCurves.append(currentLoop);
        }
    }

    // Determine whether a given closed loop is an outer boundary
    bool isOuterBoundary(const MFnNurbsCurve &loop) {
        const double totalLength = loop.length();
        const unsigned int numSamples = std::max(loop.numCVs(), 10u);
        MPointArray sampledPoints;
        sampledPoints.setLength(numSamples);

        for (unsigned int i = 0; i < numSamples; ++i) {
            const double param = loop.findParamFromLength(totalLength * i / numSamples);
            loop.getPointAtParam(param, sampledPoints[i]);
        }

        // Find rightmost point
        MPoint rightMost = sampledPoints[0];
        unsigned int rightMostIdx = 0;
        for (unsigned int i = 1; i < sampledPoints.length(); ++i) {
            if (sampledPoints[i].x > rightMost.x) {
                rightMost = sampledPoints[i];
                rightMostIdx = i;
            }
        }

        // Find neighbors around rightmost point
        int prevIdx = (rightMostIdx == 0) ? static_cast<int>(sampledPoints.length()) - 1 : rightMostIdx - 1;
        int nextIdx = (rightMostIdx == sampledPoints.length() - 1) ? 0 : rightMostIdx + 1;

        // Adjust indices in case of near-zero spacing
        while (fabs(sampledPoints[prevIdx].x - rightMost.x) < 1e-5) {
            prevIdx = (prevIdx == 0) ? static_cast<int>(sampledPoints.length()) - 1 : prevIdx - 1;
        }
        while (fabs(sampledPoints[nextIdx].x - rightMost.x) < 1e-5) {
            nextIdx = (nextIdx == static_cast<int>(sampledPoints.length()) - 1) ? 0 : nextIdx + 1;
        }

        // Validate closure
        if (fabs(sampledPoints[nextIdx].x - rightMost.x) < 1e-5 ||
            fabs(sampledPoints[prevIdx].x - rightMost.x) < 1e-5) {
            return false;
        }

        // Compute winding direction via cross product
        MVector v1 = sampledPoints[prevIdx] - rightMost;
        MVector v2 = sampledPoints[nextIdx] - rightMost;
        MVector cross = v1 ^ v2;

        return cross.z < 0.0;
    }

    // Repack trim curves and apply trimming to surface
    void applyTrimming(Alembic::AbcGeom::INuPatchSchema::Sample &sample,
                       MFnNurbsSurface &surfaceFn) {
        MTrimBoundaryArray fullBoundaryList;
        extractTrimCurves(sample, fullBoundaryList);

        MTrimBoundaryArray currentRegion;
        for (unsigned int i = 0; i < fullBoundaryList.length(); ++i) {
            if (i > 0) {
                MStatus status;
                MObject merged = fullBoundaryList.getMergedBoundary(i, &status);
                if (status != MS::kSuccess) continue;

                MFnNurbsCurve loop(merged, &status);
                if (status != MS::kSuccess) continue;

                if (isOuterBoundary(loop)) {
#if MAYA_API_VERSION < 201300
                    status = surfaceFn.trimWithBoundaries(currentRegion);
#else
                    status = surfaceFn.trimWithBoundaries(currentRegion, false, 1e-3, 1e-5, true);
#endif
                    if (status != MS::kSuccess) {
                        MGlobal::displayError("Failed to trim outer boundary.");
                    }
                    currentRegion.clear();
                }
            }
            currentRegion.append(fullBoundaryList[i]);
        }

#if MAYA_API_VERSION < 201300
        MStatus finalStatus = surfaceFn.trimWithBoundaries(currentRegion);
#else
        MStatus finalStatus = surfaceFn.trimWithBoundaries(currentRegion, false, 1e-3, 1e-5, true);
#endif
        if (finalStatus != MS::kSuccess) {
            MGlobal::displayError("Final surface trimming failed.");
        }
    }

}

MObject loadNurbsSurface(double timeSample,
                         Alembic::AbcGeom::INuPatch &abcNode,
                         MObject &parentObj) {
    MStatus status;
    MFnNurbsSurface surfaceFn;
    MObject resultObj;

    const auto schema = abcNode.getSchema();
    Alembic::AbcCoreAbstract::index_t baseIndex, ceilIndex;
    getWeightAndIndex(timeSample, schema.getTimeSampling(),
                      schema.getNumSamples(), baseIndex, ceilIndex);

    Alembic::AbcGeom::INuPatchSchema::Sample samp;
    schema.get(samp, Alembic::Abc::ISampleSelector(baseIndex));

    const auto positionsPtr = samp.getPositions();
    const auto weightsPtr = samp.getPositionWeights();

    const MString name(abcNode.getName().c_str());

    const unsigned int orderU = samp.getUOrder();
    const unsigned int orderV = samp.getVOrder();
    const unsigned int degreeU = orderU > 0 ? orderU - 1 : 0;
    const unsigned int degreeV = orderV > 0 ? orderV - 1 : 0;

    const unsigned int numCVsU = samp.getNumU();
    const unsigned int numCVsV = samp.getNumV();
    const unsigned int totalCVs = numCVsU * numCVsV;

    MPointArray cvs;
    cvs.setLength(totalCVs);

    for (unsigned int v = 0; v < numCVsV; ++v) {
        for (unsigned int u = 0; u < numCVsU; ++u) {
            const size_t abeIdx = u * numCVsV + v;
            const size_t mayaIdx = u * numCVsV + (numCVsV - v - 1);

            const auto &p = (*positionsPtr)[abeIdx];
            MPoint pt(p.x, p.y, p.z);
            if (weightsPtr) {
                pt.w = (*weightsPtr)[abeIdx];
            }
            cvs.set(pt, mayaIdx);
        }
    }

    // Detect periodicity/closure in U and V directions
    auto detectForm = [&](unsigned int degree, unsigned int dimSize,
                          const std::function<MPoint(unsigned int, unsigned int)> &getPt) -> MFnNurbsSurface::Form {
        bool isPeriodic = true;
        for (unsigned int i = 0; i < dimSize && isPeriodic; ++i) {
            for (unsigned int j = 0; j < degree; ++j) {
                if (!getPt(j, i).isEquivalent(getPt(dimSize - degree + j, i))) {
                    isPeriodic = false;
                    break;
                }
            }
        }
        if (!isPeriodic) {
            bool isClosed = true;
            for (unsigned int i = 0; i < dimSize && isClosed; ++i) {
                if (!getPt(0, i).isEquivalent(getPt(dimSize - 1, i))) {
                    isClosed = false;
                    break;
                }
            }
            return isClosed ? MFnNurbsSurface::kClosed : MFnNurbsSurface::kOpen;
        }
        return MFnNurbsSurface::kPeriodic;
    };

    auto getCV = [&](unsigned int u, unsigned int v) -> MPoint {
        return cvs[u * numCVsV + (numCVsV - v - 1)];
    };

    const auto formU = detectForm(degreeU, numCVsU, getCV);
    const auto formV = detectForm(degreeV, numCVsV, getCV);

    // Extract knot vectors
    const auto uknots = samp.getUKnot();
    const auto vknots = samp.getVKnot();

    MDoubleArray uKnotSeq, vKnotSeq;

    if (uknots->size() > 2) {
        uKnotSeq.setLength(static_cast<unsigned int>(uknots->size() - 2));
        for (unsigned int i = 0; i < uKnotSeq.length(); ++i)
            uKnotSeq.set((*uknots)[i + 1], i);
    }

    if (vknots->size() > 2) {
        vKnotSeq.setLength(static_cast<unsigned int>(vknots->size() - 2));
        for (unsigned int i = 0; i < vKnotSeq.length(); ++i)
            vKnotSeq.set((*vknots)[i + 1], i);
    }

    // Try creating surface with detected forms first
    resultObj = surfaceFn.create(cvs, uKnotSeq, vKnotSeq,
                                 degreeU, degreeV, formU, formV,
                                 true, parentObj, &status);

    // Fallback to open/open if initial creation failed
    if (status != MS::kSuccess &&
        (formU != MFnNurbsSurface::kOpen || formV != MFnNurbsSurface::kOpen)) {
        resultObj = surfaceFn.create(cvs, uKnotSeq, vKnotSeq,
                                     degreeU, degreeV,
                                     MFnNurbsSurface::kOpen, MFnNurbsSurface::kOpen,
                                     true, parentObj, &status);
    }

    if (status == MS::kSuccess) {
        surfaceFn.setName(name);
    } else {
        MGlobal::displayError(status.errorString());
        MString err = "Failed to create Nurbs Surface: ";
        err += name;
        MGlobal::displayError(err);
    }

    applyTrimming(samp, surfaceFn);
    return resultObj;
}

MObject generateNurbs(double frameTime,
                      Alembic::AbcGeom::INuPatch &node,
                      MObject &parent) {
    MObject obj = loadNurbsSurface(frameTime, node, parent);
    if (!obj.isNull()) {
        MFnNurbsSurface fn(obj);
        setInitialShadingGroup(fn.partialPathName());
    }
    return obj;
}

#include "runsmap.h"
//---------------------------------------------------------------------------------------------
void RunsMap::setRunLength(TPixelGR8 *pix, TUINT32 len) {
  TPixelGR8 *startPix = pix;
  TPixelGR8 *endPix   = startPix + len - 1;
  --len;

  if (len < 3) {
    startPix->value = endPix->value = (static_cast<TUINT8>(len << 6));
  } else {
    startPix->value = endPix->value = (3 << 6);
    ++startPix;
    --endPix;

    if (len < 255) {
      startPix->value = endPix->value = static_cast<TUINT8>(len);
    } else {
      startPix->value = endPix->value = 255;
      ++startPix;
      endPix -= 4;
      TUINT32 *lengthPtr = reinterpret_cast<TUINT32*>(startPix);
      *lengthPtr         = len;
    }
  }
  assert(runLength(pix) == (len + 1));
}
//---------------------------------------------------------------------------------------------
TUINT32 RunsMap::runLength(const TPixelGR8 *pix, bool reverse) const {
  int count = pix->value >> 6;
  if (count >= 3) {
    pix += (reverse) ? -1 : 1;
    count = pix->value;

    if (count >= 255) {
      pix += (reverse) ? -4 : 1;
      const TUINT32 *dataPtr = reinterpret_cast<const TUINT32*>(pix);
      count = *dataPtr;
    }
  }
  return count + 1;
}

