// Constructor initializes the object to a default state
ParsedNumber::ParsedNumber() {
    resetState();
}

// Resets all internal fields to their initial values
void ParsedNumber::resetState() {
    quantity.bogus = true;
    charEnd = 0;
    flags = 0;
    prefix.setToBogus();
    suffix.setToBogus();
    currencyCode[0] = '\0';
}

// Updates the end position based on current segment offset
void ParsedNumber::setCharsConsumed(const StringSegment& segment) {
    charEnd = segment.getOffset();
}

// Applies sign if negative flag is set and number is valid
void ParsedNumber::postProcess() {
    if (!quantity.bogus && (flags & FLAG_NEGATIVE)) {
        quantity.negate();
    }
}

// Determines whether parsing succeeded: must have consumed at least one char and not failed
bool ParsedNumber::success() const {
    return charEnd > 0 && !(flags & FLAG_FAIL);
}

// Checks if any numeric value was detected (including special values)
bool ParsedNumber::seenNumber() const {
    return !quantity.bogus || (flags & FLAG_NAN) || (flags & FLAG_INFINITY);
}

// Returns double representation of parsed number, handling special cases explicitly
double ParsedNumber::getDouble(UErrorCode& status) const {
    bool isNaN = (flags & FLAG_NAN);
    bool isInf = (flags & FLAG_INFINITY);

    // Handle NaN first
    if (isNaN) {
        return uprv_getNaN();
    }

    // Handle infinity with correct sign
    if (isInf) {
        return (flags & FLAG_NEGATIVE) ? -INFINITY : INFINITY;
    }

    // Error case: no valid number
    if (quantity.bogus) {
        status = U_INVALID_STATE_ERROR;
        return 0.0;
    }

    // Handle signed zero
    if (quantity.isZeroish() && quantity.isNegative()) {
        return -0.0;
    }

    // Convert to double using optimal path
    if (quantity.fitsInLong()) {
        return static_cast<double>(quantity.toLong());
    } else {
        return quantity.toDouble();
    }
}

// Populates a Formattable object with the parsed value
void ParsedNumber::populateFormattable(Formattable& output, parse_flags_t parseFlags) const {
    bool isNaN = (flags & FLAG_NAN);
    bool isInf = (flags & FLAG_INFINITY);
    bool integerOnly = (parseFlags & PARSE_FLAG_INTEGER_ONLY);

    // Special values handling
    if (isNaN) {
        output.setDouble(uprv_getNaN());
        return;
    }
    if (isInf) {
        output.setDouble((flags & FLAG_NEGATIVE) ? -INFINITY : INFINITY);
        return;
    }

    U_ASSERT(!quantity.bogus);

    // Signed zero for non-integer-only parsing
    if (quantity.isZeroish() && quantity.isNegative() && !integerOnly) {
        output.setDouble(-0.0);
        return;
    }

    // General case: adopt decimal quantity
    output.adoptDecimalQuantity(new DecimalQuantity(quantity));
}

// Compares two parsed results; higher character count wins
bool ParsedNumber::isBetterThan(const ParsedNumber& other) {
    return charEnd > other.charEnd;
}

