#include "pruning.h"
#include <algorithm>

/*********************************************
	class Pruning
*********************************************/
/**
	Steffen Klaere's pruning algorithm — variant implementation
*/
void Pruning::execute(Params &cfg, std::vector<PDTaxaSet> &result_set)
{
	// Ensure minimum retained size matches desired subtree size
	if (cfg.min_size < 2) 
		cfg.min_size = cfg.sub_size;

	// Compute target leaf list capacity based on remaining nodes
	capacity = 2 * (leafCount - cfg.sub_size) - 1;

	// Initialize special nodes if provided
	if (!seed_nodes.empty()) {
		setupSeedNodes();
	}

	// Traverse tree to collect initial leaves
	collectLeaves();

	// Iteratively reduce tree until only 'sub_size' leaves remain
	for (int current_count = leafCount; current_count > cfg.sub_size; --current_count) {
		LeafSet::iterator victim = selectClosestLeaf();
		removeExternalNode(victim);
		capacity -= 2;
	}

	// Finalize output
	result_set.resize(1);
	result_set[0].setTree(*this);
}

void Pruning::setupSeedNodes() {
	for (NodeVector::iterator iter = seed_nodes.begin(); iter != seed_nodes.end(); ++iter) {
		(*iter)->depth = 1;
	}
}

void Pruning::displayLeaves() const
{
	for (LeafSet::const_iterator iter = leaf_pool.begin(); iter != leaf_pool.end(); ++iter) {
		Node *node = *iter;
		std::cout << node->id << " " << node->adjacentEdges[0]->weight << std::endl;
	}
}

void Pruning::collectLeaves(Node *curr, Node *parent)
{
	if (!curr) curr = root;
	if (curr->isLeaf()) {
		registerLeaf(curr);
	}
	FOR_NEIGHBOR_IT(curr, parent, iter)
		collectLeaves((*iter)->target, curr);
}

LeafSet::iterator Pruning::locateLeaf(Node *target)
{
	std::pair<LeafSet::iterator, LeafSet::iterator>
		bounds = leaf_pool.equal_range(target);
	for (LeafSet::iterator iter = bounds.first; iter != bounds.second; ++iter) {
		if (*iter == target) return iter;
	}
	return leaf_pool.end();
}

void Pruning::removeExternalNode(LeafSet::iterator pos)
{
	Node *leaf = *pos;
	Node *internal = leaf->adjacentEdges[0]->target;
	Node *other_branches[2] = { nullptr, nullptr };
	int branch_count = 0;
	double combined_length = 0.0;
	bool can_compress = true;

	FOR_NEIGHBOR(internal, leaf, iter) {
		combined_length += (*iter)->weight;
		if (branch_count < 2) {
			other_branches[branch_count++] = (*iter)->target;
		} else {
			can_compress = false;
		}
	}

	if (can_compress) {
		// Remove any leaf references before merging
		for (int idx = 0; idx < 2; ++idx) {
			if (other_branches[idx]->isLeaf()) {
				LeafSet::iterator temp = locateLeaf(other_branches[idx]);
				if (temp != leaf_pool.end())
					leaf_pool.erase(temp);
			}
		}

		// Reconnect neighbors to merged edge
		for (int idx = 0; idx < 2; ++idx) {
			for (auto &edge : other_branches[idx]->adjacentEdges) {
				if (edge->target == internal) {
					edge->target = other_branches[1 - idx];
					edge->weight = combined_length;
				}
			}
		}
	} else {
		// Simple deletion: just remove the leaf's connection
		for (auto iter = internal->adjacentEdges.begin(); iter != internal->adjacentEdges.end(); ++iter) {
			if ((*iter)->target == leaf) {
				internal->adjacentEdges.erase(iter);
				break;
			}
		}
	}

	// Erase the removed leaf from pool
	leaf_pool.erase(pos);

	if (can_compress) {
		for (int idx = 0; idx < 2; ++idx) {
			if (other_branches[idx]->isLeaf()) {
				registerLeaf(other_branches[idx]);
			}
		}
	}

	// Trim excess leaves if needed
	if (leaf_pool.size() > static_cast<size_t>(capacity) && leaf_pool.size() > 1) {
		auto last_iter = leaf_pool.end();
		--last_iter;
		leaf_pool.erase(last_iter);
	}

	// Update root if it was deleted
	if (leaf == root) {
		root = *leaf_pool.begin();
	}
}

LeafSet::iterator Pruning::selectClosestLeaf()
{
	return leaf_pool.begin();
}

/**
	Register a new leaf into the active set
*/
void Pruning::registerLeaf(Node* candidate) {
	// Skip seeds marked as fixed
	if (candidate->depth == 1) {
		return;
	}

	if (capacity <= 0) return;

	if (leaf_pool.size() < static_cast<size_t>(capacity)) {
		leaf_pool.insert(candidate);
	} else {
		auto end_iter = leaf_pool.end();
		--end_iter;
		Node* furthest = *end_iter;
		if (candidate->adjacentEdges[0]->weight < furthest->adjacentEdges[0]->weight) {
			leaf_pool.erase(end_iter);
			leaf_pool.insert(candidate);
		}
	}
}

#include "math/Rand2.h"

Rand2::Rand2(int i) {
    if (i == 0) {
        mSeed = 1;
    } else if (i < 0) {
        mSeed = -i;
    } else {
        mSeed = i;
    }
}

int Rand2::Int() {
    int quotient = mSeed / 127773;
    int remainder = mSeed % 127773;
    int test = (remainder * 0x41A7) - (quotient * 0xB14);

    if (test >= 0) {
        mSeed = test;
    } else {
        mSeed = test + 0x7FFFFFFF;
    }

    return mSeed;
}

