// Type name mapping helper - returns short type identifiers
template <typename T>
constexpr const char* get_type_short_name();

template <>
const char* get_type_short_name<float32>() {
  return "f";
}

template <>
const char* get_type_short_name<float64>() {
  return "d";
}

template <>
const char* get_type_short_name<int>() {
  return "i";
}

template <>
const char* get_type_short_name<int64>() {
  return "I";
}

template <>
const char* get_type_short_name<uint64>() {
  return "U";
}

// Dimension extractor for vector types
template <typename T>
struct extract_dimension {};

template <int dim, typename T, InstSetExt ISE>
struct extract_dimension<VectorND<dim, T, ISE>> {
  static constexpr int value = dim;
};

// Vector constructor initializer templates based on dimensionality
template <int dim, typename T>
struct construct_vector {};

template <typename T>
struct construct_vector<1, T> {
  static auto create() {
    return py::init<T>();
  }
};

template <typename T>
struct construct_vector<2, T> {
  static auto create() {
    return py::init<T, T>();
  }
};

template <typename T>
struct construct_vector<3, T> {
  static auto create() {
    return py::init<T, T, T>();
  }
};

template <typename T>
struct construct_vector<4, T> {
  static auto create() {
    return py::init<T, T, T, T>();
  }
};

// Field accessor helpers for vector components
template <int idx, typename VecType>
struct access_component {};

template <typename VecType>
struct access_component<0, VecType> {
  static auto fetch() {
    return &VecType::x;
  }
};

template <typename VecType>
struct access_component<1, VecType> {
  static auto fetch() {
    return &VecType::y;
  }
};

template <typename VecType>
struct access_component<2, VecType> {
  static auto fetch() {
    return &VecType::z;
  }
};

template <typename VecType>
struct access_component<3, VecType> {
  static auto fetch() {
    return &VecType::w;
  }
};

// Conditional registration of vector fields (SFINAE-based)
template <int idx, typename VecType, typename PyClass,
          std::enable_if_t<extract_dimension<VecType>::value < idx + 1, int> = 0>
void bind_field(PyClass&) {}

template <int idx, typename VecType, typename PyClass,
          std::enable_if_t<extract_dimension<VecType>::value >= idx + 1, int> = 0>
void bind_field(PyClass& cls) {
  static const char* field_names[4] = {"x", "y", "z", "w"};
  cls.def_readwrite(field_names[idx], access_component<idx, VecType>::fetch());
}

// Main registration logic for vector types
template <typename T>
struct register_vector_type {};

template <int dim, typename T, InstSetExt ISE>
struct register_vector_type<VectorND<dim, T, ISE>> {
  static void execute(py::module& mod) {
    using VectorType = VectorND<dim, T, ISE>;

    // Construct class name like Vector3f
    std::string class_name = std::string("Vector") + 
                             std::to_string(dim) + 
                             get_type_short_name<T>();

    auto cls = py::class_<VectorType>(mod, class_name.c_str());

    // Register constructors
    cls.def(construct_vector<dim, T>::create())
       .def(py::init<T>())
       .def("__len__", [](VectorType*) { return VectorType::dim; })
       .def("__getitem__", [](VectorType* v, int i) { return (*v)[i]; });

    // Bind all possible fields conditionally
    bind_field<0, VectorType>(cls);
    bind_field<1, VectorType>(cls);
    bind_field<2, VectorType>(cls);
    bind_field<3, VectorType>(cls);
  }
};

// Export math module functions
void export_math(py::module& m) {
  register_vector_type<Vector2f>::execute(m);
  register_vector_type<Vector3f>::execute(m);
  register_vector_type<Vector4f>::execute(m);
  register_vector_type<Vector2d>::execute(m);
  register_vector_type<Vector3d>::execute(m);
  register_vector_type<Vector4d>::execute(m);
  register_vector_type<Vector2i>::execute(m);
  register_vector_type<Vector3i>::execute(m);
  register_vector_type<Vector4i>::execute(m);
}

