    // Traverse DAG subtree to collect nurbs curves; mark group as animated if any curve or its transform is animated
    void gatherNurbsCurves(const MDagPath &rootPath, bool bSkipInvisible,
        MDagPathArray &outPaths, bool & outIsAnimated)
    {
        MStatus status;
        MItDag iter(MItDag::kDepthFirst, MFn::kNurbsCurve, &status);
        status = iter.reset(rootPath, MItDag::kDepthFirst, MFn::kNurbsCurve);
        if (status != MS::kSuccess) return;

        while (!iter.isDone())
        {
            MDagPath currentPath;
            status = iter.getPath(currentPath);
            if (status != MS::kSuccess || !currentPath.isValid())
            {
                iter.next();
                continue;
            }

            MObject node = currentPath.node();
            bool bIsValidCurve = node.hasFn(MFn::kNurbsCurve);
            bool bNotIntermediate = !util::isIntermediate(node);
            bool bRenderable = util::isRenderable(node);

            if (bIsValidCurve && bNotIntermediate &&
                (!bSkipInvisible || bRenderable))
            {
                outPaths.append(currentPath);

                // Early exit: only need one animated component to flag whole group
                if (!outIsAnimated)
                {
                    if (util::isAnimated(node, true))
                    {
                        outIsAnimated = true;
                    }
                    else
                    {
                        MObject xformObj = currentPath.transform();
                        if (util::isAnimated(xformObj, true))
                        {
                            outIsAnimated = true;
                        }
                    }
                }
            }

            iter.next();
        }
    }  // end gatherNurbsCurves
}

MayaNurbsCurveWriter::MayaNurbsCurveWriter(
    MDagPath & iRootDag,
    Alembic::Abc::OObject & iParent,
    Alembic::Util::uint32_t iTimeIndex,
    bool iIsCurveGrp,
    const JobArgs & iArgs)
    : mIsAnimated(false), mRootDagPath(iRootDag), mIsCurveGrp(iIsCurveGrp)
{
    MStatus stat;
    MFnDependencyNode depNode(iRootDag.node(), &stat);
    MString name = depNode.name();

    if (mIsCurveGrp)
    {
        gatherNurbsCurves(mRootDagPath, iArgs.excludeInvisible,
            mNurbsCurves, mIsAnimated);

        if (mNurbsCurves.length() == 0)
            return;
    }
    else
    {
        MObject shapeNode = iRootDag.node();
        if (iTimeIndex != 0 && util::isAnimated(shapeNode))
        {
            mIsAnimated = true;
        }
        else
        {
            iTimeIndex = 0;
        }
    }

    name = util::stripNamespaces(name, iArgs.stripNamespace);
    Alembic::AbcGeom::OCurves abcCurve(iParent, name.asChar(), iTimeIndex);
    mSchema = abcCurve.getSchema();

    Alembic::Abc::OCompoundProperty arbParams, userProps;
    if (AttributesWriter::hasAnyAttr(depNode, iArgs))
    {
        arbParams = mSchema.getArbGeomParams();
        userProps = mSchema.getUserProperties();
    }

    mAttrs = AttributesWriterPtr(new AttributesWriter(
        arbParams, userProps, abcCurve, depNode, iTimeIndex, iArgs, true));

    if (!mIsAnimated || iArgs.setFirstAnimShape)
    {
        write();
    }
}

unsigned int MayaNurbsCurveWriter::getNumCVs() const
{
    return mCVCount;
}

unsigned int MayaNurbsCurveWriter::getNumCurves() const
{
    return mIsCurveGrp ? mNurbsCurves.length() : 1u;
}

bool MayaNurbsCurveWriter::isAnimated() const
{
    return mIsAnimated;
}

void MayaNurbsCurveWriter::write()
{
    Alembic::AbcGeom::OCurvesSchema::Sample sample;
    sample.setBasis(Alembic::AbcGeom::kBsplineBasis);

    MStatus status;
    mCVCount = 0;

    MMatrix invWorldXform = mRootDagPath.exclusiveMatrixInverse(&status);
    std::size_t totalCurves = mIsCurveGrp ? mNurbsCurves.length() : 1u;

    std::vector<Alembic::Util::int32_t> cvCounts(totalCurves);
    std::vector<float> positions;
    std::vector<float> widths;
    std::vector<float> knotValues;
    std::vector<Alembic::Util::uint8_t> degrees(totalCurves);

    MMatrix localMatrix;
    bool useUniformWidth = false;
    MFnDependencyNode rootDep(mRootDagPath.transform());
    MPlug widthPlug = rootDep.findPlug("width", true);
    if (!widthPlug.isNull())
    {
        useUniformWidth = true;
        widths.push_back(static_cast<float>(widthPlug.asFloat()));
    }

    unsigned int idx = 0;
    while (idx < totalCurves)
    {
        MFnNurbsCurve fnCurve;
        if (mIsCurveGrp)
        {
            fnCurve.setObject(mNurbsCurves[idx]);
            MMatrix worldXform = mNurbsCurves[idx].inclusiveMatrix(&status);
            localMatrix = worldXform * invWorldXform;
        }
        else
        {
            fnCurve.setObject(mRootDagPath.node());
        }

        if (idx == 0)
        {
            switch (fnCurve.form())
            {
                case MFnNurbsCurve::kOpen:
                    sample.setWrap(Alembic::AbcGeom::kNonPeriodic);
                    break;
                default:
                    sample.setWrap(Alembic::AbcGeom::kPeriodic);
                    break;
            }

            switch (fnCurve.degree())
            {
                case 3:
                    sample.setType(Alembic::AbcGeom::kCubic);
                    break;
                case 1:
                    sample.setType(Alembic::AbcGeom::kLinear);
                    break;
                default:
                    sample.setType(Alembic::AbcGeom::kVariableOrder);
                    break;
            }
        }
        else
        {
            bool mismatch = false;
            switch (sample.getType())
            {
                case Alembic::AbcGeom::kCubic:
                    mismatch = (fnCurve.degree() != 3);
                    break;
                case Alembic::AbcGeom::kLinear:
                    mismatch = (fnCurve.degree() != 1);
                    break;
                default:
                    break;
            }

            if (mismatch)
                sample.setType(Alembic::AbcGeom::kVariableOrder);
        }

        degrees[idx] = static_cast<Alembic::Util::uint8_t>(fnCurve.degree() + 1);

        Alembic::Util::int32_t numCVs = fnCurve.numCVs(&status);
        MPointArray cvs;
        status = fnCurve.getCVs(cvs, MSpace::kObject);
        mCVCount += numCVs;
        cvCounts[idx] = numCVs;

        for (Alembic::Util::int32_t cvidx = 0; cvidx < numCVs; ++cvidx)
        {
            MPoint transformedPt = cvs[cvidx];
            if (mIsCurveGrp)
                transformedPt *= localMatrix;

            positions.emplace_back(static_cast<float>(transformedPt.x));
            positions.emplace_back(static_cast<float>(transformedPt.y));
            positions.emplace_back(static_cast<float>(transformedPt.z));
        }

        MDoubleArray knotArr;
        fnCurve.getKnots(knotArr);

        // Prepend/append extrapolated knots per NURBS convention
        if (knotArr.length() > 1)
        {
            size_t len = knotArr.length();
            float firstKnot = static_cast<float>(knotArr[0]);
            float secondKnot = static_cast<float>(knotArr[1]);
            float lastKnot = static_cast<float>(knotArr[len - 1]);
            float prevLastKnot = static_cast<float>(knotArr[len - 2]);

            if (firstKnot == lastKnot || firstKnot == secondKnot)
            {
                knotValues.push_back(firstKnot);
            }
            else
            {
                knotValues.push_back(2.0f * firstKnot - secondKnot);
            }

            for (size_t k = 0; k < len; ++k)
            {
                knotValues.push_back(static_cast<float>(knotArr[k]));
            }

            if (lastKnot == firstKnot || lastKnot == prevLastKnot)
            {
                knotValues.push_back(lastKnot);
            }
            else
            {
                knotValues.push_back(2.0f * lastKnot - prevLastKnot);
            }
        }

        // Handle per-curve width plug
        MPlug curveWidthPlug = fnCurve.findPlug("width", true);
        if (!useUniformWidth && !curveWidthPlug.isNull())
        {
            MObject widthDataObj;
            MStatus plugStat = curveWidthPlug.getValue(widthDataObj);
            if (plugStat == MS::kSuccess)
            {
                MFnDoubleArrayData arrayData(widthDataObj, &plugStat);
                MDoubleArray doubleData = arrayData.array();
                if (static_cast<int>(doubleData.length()) == numCVs)
                {
                    for (int w = 0; w < numCVs; ++w)
                    {
                        widths.push_back(static_cast<float>(doubleData[w]));
                    }
                }
                else
                {
                    MString warnMsg = "Curve ";
                    warnMsg += fnCurve.partialPathName();
                    warnMsg += " has incorrect width vector size.";
                    warnMsg += "\nFalling back to constant width 0.1.";
                    MGlobal::displayWarning(warnMsg);

                    widths.clear();
                    widths.push_back(0.1f);
                    useUniformWidth = true;
                }
            }
            else
            {
                widths.push_back(static_cast<float>(curveWidthPlug.asFloat()));
            }
        }
        else if (!useUniformWidth)
        {
            widths.clear();
            widths.push_back(0.1f);
            useUniformWidth = true;
        }

        ++idx;
    }

    Alembic::AbcGeom::GeometryScope widthScope;
    if (!useUniformWidth && widths.size() > 1 && widths.size() == totalCurves)
    {
        widthScope = Alembic::AbcGeom::kUniformScope;
    }
    else if (widths.size() == 1)
    {
        widthScope = Alembic::AbcGeom::kConstantScope;
    }
    else
    {
        widthScope = Alembic::AbcGeom::kVertexScope;
    }

    sample.setCurvesNumVertices(Alembic::Abc::Int32ArraySample(cvCounts));
    sample.setPositions(Alembic::Abc::V3fArraySample(
        reinterpret_cast<const Imath::V3f*>(positions.data()), positions.size() / 3));

    sample.setWidths(Alembic::AbcGeom::OFloatGeomParam::Sample(
        Alembic::Abc::FloatArraySample(widths), widthScope));

    if (sample.getType() == Alembic::AbcGeom::kVariableOrder)
    {
        sample.setOrders(Alembic::Abc::UcharArraySample(degrees));
    }

    if (!knotValues.empty())
    {
        sample.setKnots(Alembic::Abc::FloatArraySample(knotValues));
    }

    mSchema.set(sample);
}

