void recordCommand(const std::string& cmd) {
    if (cmd.empty()) return;

    // Skip duplicate consecutive entries
    if (histSize > 0 && cmdHistory[(histPos - 1 + MAX_HISTORY) % MAX_HISTORY] == cmd) return;

    cmdHistory[histPos] = cmd;
    histPos = (histPos + 1) % MAX_HISTORY;
    if (histSize < MAX_HISTORY) histSize++;
}

void displayHistory() {
    if (histSize == 0) {
        printLine("No command history.");
        return;
    }

    printLine("Command history:");
    int firstIdx = (histPos - histSize + MAX_HISTORY) % MAX_HISTORY;

    for (int i = 0; i < histSize; ++i) {
        int idx = (firstIdx + i) % MAX_HISTORY;
        printLine(std::to_string(i + 1) + ": " + cmdHistory[idx]);
    }
}

void convertToHex(const std::string& numStr) {
    long value = std::stol(numStr);
    char hexBuffer[20];
    sprintf(hexBuffer, "0x%lX", value);

    printLine("Decimal: " + std::to_string(value));
    printLine("Hexadecimal: " + std::string(hexBuffer));
}

void convertToBinary(const std::string& numStr) {
    long number = std::stol(numStr);
    std::string binaryResult = "";

    if (number == 0) {
        binaryResult = "0";
    } else {
        long temp = number;
        while (temp > 0) {
            binaryResult = std::to_string(temp % 2) + binaryResult;
            temp /= 2;
        }
    }

    printLine("Decimal: " + std::to_string(number));
    printLine("Binary: 0b" + binaryResult);
}

std::string encodeBase64(const std::string& input) {
    std::string output = "";
    int buffer = 0;
    int bitCount = -6;

    const char base64_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz012345689+/";

    for (size_t i = 0; i < input.length(); ++i) {
        unsigned char ch = input[i];
        buffer = (buffer << 8) + ch;
        bitCount += 8;

        while (bitCount >= 0) {
            output += base64_chars[(buffer >> bitCount) & 0x3F];
            bitCount -= 6;
        }
    }

    if (bitCount > -6) {
        output += base64_chars[((buffer << 8) >> (bitCount + 8)) & 0x3F];
    }

    while (output.length() % 4) {
        output += '=';
    }

    return output;
}

std::string decodeBase64(const std::string& input) {
    std::string result = "";
    int buffer = 0;
    int bitCount = -8;

    const char base64_chars[] = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";

    for (size_t i = 0; i < input.length(); ++i) {
        char ch = input[i];
        if (ch == '=') break;

        int index = -1;
        for (int j = 0; j < 64; ++j) {
            if (base64_chars[j] == ch) {
                index = j;
                break;
            }
        }

        if (index == -1) continue;

        buffer = (buffer << 6) + index;
        bitCount += 6;

        if (bitCount >= 0) {
            result += static_cast<char>((buffer >> bitCount) & 0xFF);
            bitCount -= 8;
        }
    }

    return result;
}

void handleBase64(const std::string& operation, const std::string& text) {
    if (operation == "encode") {
        std::string encoded = encodeBase64(text);
        printLine("Encoded: " + encoded);
    } else if (operation == "decode") {
        std::string decoded = decodeBase64(text);
        printLine("Decoded: " + decoded);
    } else {
        printLine("Usage: base64 encode <text>");
        printLine("       base64 decode <text>");
    }
}

