int getPrecedence(char op) {
    if (op == '+' || op == '-') return 1;
    if (op == '*' || op == '/' || op == '%') return 2;
    if (op == '^') return 3;
    return 0;
}

bool isRightAssociative(char op) {
    return (op == '^');
}

float performOperation(float a, float b, char op) {
    switch (op) {
        case '+': return a + b;
        case '-': return a - b;
        case '*': return a * b;
        case '/': 
            if (b == 0) {
                printLine("Error: Division by zero");
                return 0;
            }
            return a / b;
        case '%': 
            if (b == 0) {
                printLine("Error: Modulo by zero");
                return 0;
            }
            return static_cast<int>(a) % static_cast<int>(b);
        case '^': return pow(a, b);
    }
    return 0;
}

bool checkFunction(const std::string& expr, int pos, const std::string& funcName) {
    if (pos + funcName.length() > expr.length()) return false;
    std::string substr = expr.substr(pos, funcName.length());
    std::transform(substr.begin(), substr.end(), substr.begin(), ::tolower);
    return substr == funcName;
}

std::string extractFunctionName(const std::string& expr, int pos) {
    std::string functions[] = {
        "sqrt", "sin", "cos", "tan", "asin", "acos", "atan",
        "sinh", "cosh", "tanh", "log", "ln", "exp",
        "abs", "ceil", "floor", "round"
    };

    for (int i = 0; i < 17; ++i) {
        if (checkFunction(expr, pos, functions[i])) {
            return functions[i];
        }
    }
    return "";
}

float executeFunction(const std::string& func, float value) {
    if (func == "sqrt") return sqrt(value);
    if (func == "sin") return sin(value);
    if (func == "cos") return cos(value);
    if (func == "tan") return tan(value);
    if (func == "asin") return asin(value);
    if (func == "acos") return acos(value);
    if (func == "atan") return atan(value);
    if (func == "sinh") return sinh(value);
    if (func == "cosh") return cosh(value);
    if (func == "tanh") return tanh(value);
    if (func == "log") return log10(value);
    if (func == "ln") return log(value);
    if (func == "exp") return exp(value);
    if (func == "abs") return abs(value);
    if (func == "ceil") return ceil(value);
    if (func == "floor") return floor(value);
    if (func == "round") return round(value);
    return value;
}

void calculateExpression(const std::string& expression_in) {
    std::string expression = expression_in;

    // Replace pi and e constants
    size_t pos = expression.find("pi");
    while (pos != std::string::npos) {
        expression.replace(pos, 2, std::to_string(PI));
        pos = expression.find("pi", pos + std::to_string(PI).length());
    }

    pos = expression.find("e");
    while (pos != std::string::npos) {
        expression.replace(pos, 1, std::to_string(E));
        pos = expression.find("e", pos + std::to_string(E).length());
    }

    if (expression.empty()) {
        printLine("Error: Empty expression");
        return;
    }

    float values[50];
    char operators[50];
    std::string funcs[50];
    int valTop = -1;
    int opTop = -1;
    int funcTop = -1;

    int len = expression.length();

    for (int i = 0; i < len; ++i) {
        std::string funcName = extractFunctionName(expression, i);
        if (!funcName.empty()) {
            i += funcName.length();
            funcs[++funcTop] = funcName;
            continue;
        }

        if (expression[i] == '(') {
            operators[++opTop] = '(';
        }
        else if (expression[i] == ')') {
            while (opTop >= 0 && operators[opTop] != '(') {
                float operand2 = values[valTop--];
                float operand1 = values[valTop--];
                char oper = operators[opTop--];
                values[++valTop] = performOperation(operand1, operand2, oper);
            }
            if (opTop >= 0) --opTop;

            if (funcTop >= 0) {
                float val = values[valTop--];
                val = executeFunction(funcs[funcTop--], val);
                values[++valTop] = val;
            }
        }
        else if (isdigit(expression[i]) || expression[i] == '.') {
            float number = 0;
            float fraction = 0;
            bool decimalFound = false;
            int decimalDigits = 0;

            while (i < len && (isdigit(expression[i]) || expression[i] == '.')) {
                if (expression[i] == '.') {
                    decimalFound = true;
                } else {
                    if (decimalFound) {
                        fraction = fraction * 10 + (expression[i] - '0');
                        decimalDigits++;
                    } else {
                        number = number * 10 + (expression[i] - '0');
                    }
                }
                i++;
            }
            i--;

            if (decimalFound && decimalDigits > 0) {
                number += fraction / pow(10, decimalDigits);
            }

            values[++valTop] = number;
        }
        else if (expression[i] == '-' && 
                (i == 0 || expression[i-1] == '(' || expression[i-1] == '+' || 
                 expression[i-1] == '-' || expression[i-1] == '*' || 
                 expression[i-1] == '/' || expression[i-1] == '^')) {
            values[++valTop] = 0;
            operators[++opTop] = '-';
        }
        else if (expression[i] == '+' || expression[i] == '-' || 
                 expression[i] == '*' || expression[i] == '/' || 
                 expression[i] == '%' || expression[i] == '^') {
            while (opTop >= 0 && operators[opTop] != '(' && 
                   (getPrecedence(operators[opTop]) > getPrecedence(expression[i]) ||
                    (getPrecedence(operators[opTop]) == getPrecedence(expression[i]) && 
                     !isRightAssociative(expression[i])))) {
                float operand2 = values[valTop--];
                float operand1 = values[valTop--];
                char oper = operators[opTop--];
                values[++valTop] = performOperation(operand1, operand2, oper);
            }
            operators[++opTop] = expression[i];
        }
        else {
            printLine("Error: Invalid character '" + std::string(1, expression[i]) + "'");
            return;
        }
    }

    while (opTop >= 0) {
        if (operators[opTop] == '(') {
            printLine("Error: Mismatched parentheses");
            return;
        }
        float operand2 = values[valTop--];
        float operand1 = values[valTop--];
        char oper = operators[opTop--];
        values[++valTop] = performOperation(operand1, operand2, oper);
    }

    if (valTop != 0) {
        printLine("Error: Invalid expression");
        return;
    }

    float finalResult = values[valTop];

    if (finalResult == static_cast<int>(finalResult) && std::abs(finalResult) < 1000000) {
        printLine("Result: " + std::to_string(static_cast<int>(finalResult)));
    } else {
        char buffer[32];
        sprintf(buffer, "Result: %.6f", finalResult);
        printLine(buffer);
    }
}

