struct CommandStructure {
    std::string command;
    std::string param1;
    std::string param2;
    std::string remaining;
};

CommandStructure parseInput(const std::string& input_in) {
    CommandStructure result;
    std::string input = input_in;

    // Trim leading whitespace
    size_t start = input.find_first_not_of(" \t\n\r\f\v");
    if (start != std::string::npos) {
        input.erase(0, start);
    } else {
        input.clear();
    }

    // Trim trailing whitespace
    size_t end = input.find_last_not_of(" \t\n\r\f\v");
    if (end != std::string::npos) {
        input.erase(end + 1);
    } else {
        input.clear();
    }

    // Extract command
    size_t spacePos = input.find(' ');
    if (spacePos == std::string::npos) {
        result.command = input;
        return result;
    }

    result.command = input.substr(0, spacePos);
    std::string rest = input.substr(spacePos + 1);

    // Trim rest
    start = rest.find_first_not_of(" \t\n\r\f\v");
    if (start != std::string::npos) {
        rest.erase(0, start);
    } else {
        rest.clear();
    }

    end = rest.find_last_not_of(" \t\n\r\f\v");
    if (end != std::string::npos) {
        rest.erase(end + 1);
    } else {
        rest.clear();
    }

    // Extract first parameter
    spacePos = rest.find(' ');
    if (spacePos == std::string::npos) {
        result.param1 = rest;
        return result;
    }

    result.param1 = rest.substr(0, spacePos);
    result.remaining = rest.substr(spacePos + 1);

    // Trim remaining
    start = result.remaining.find_first_not_of(" \t\n\r\f\v");
    if (start != std::string::npos) {
        result.remaining.erase(0, start);
    } else {
        result.remaining.clear();
    }

    end = result.remaining.find_last_not_of(" \t\n\r\f\v");
    if (end != std::string::npos) {
        result.remaining.erase(end + 1);
    } else {
        result.remaining.clear();
    }

    // Extract second parameter if exists
    spacePos = result.remaining.find(' ');
    if (spacePos != std::string::npos) {
        result.param2 = result.remaining.substr(0, spacePos);
        result.remaining = result.remaining.substr(spacePos + 1);

        // Trim remaining again
        start = result.remaining.find_first_not_of(" \t\n\r\f\v");
        if (start != std::string::npos) {
            result.remaining.erase(0, start);
        } else {
            result.remaining.clear();
        }

        end = result.remaining.find_last_not_of(" \t\n\r\f\v");
        if (end != std::string::npos) {
            result.remaining.erase(end + 1);
        } else {
            result.remaining.clear();
        }
    } else if (!result.remaining.empty()) {
        result.param2 = result.remaining;
        result.remaining.clear();
    }

    return result;
}

void executeCommand(const std::string& cmd_in) {
    std::string cmd = cmd_in;

    // Trim command
    size_t start = cmd.find_first_not_of(" \t\n\r\f\v");
    if (start != std::string::npos) {
        cmd.erase(0, start);
    } else {
        cmd.clear();
    }

    size_t end = cmd.find_last_not_of(" \t\n\r\f\v");
    if (end != std::string::npos) {
        cmd.erase(end + 1);
    } else {
        cmd.clear();
    }

    if (cmd.empty()) {
        if (currentCursorY >= MAX_Y) {
            clearScreen();
            currentCursorY = 0;
        }
        return;
    }

    recordCommand(cmd);

    CommandStructure args = parseInput(cmd);
    std::string mainCmd = args.command;
    std::transform(mainCmd.begin(), mainCmd.end(), mainCmd.begin(), ::tolower);

    if (mainCmd == "write") {
        if (args.param1.empty() || args.param2.empty()) {
            printLine("Usage: write <filename> <text>");
            return;
        }
        writeFile(args.param1, args.param2 + args.remaining);
    }
    else if (mainCmd == "append") {
        if (args.param1.empty() || args.param2.empty()) {
            printLine("Usage: append <filename> <text>");
            return;
        }
        appendFile(args.param1, args.param2 + args.remaining);
    }
    else if (mainCmd == "read") {
        if (args.param1.empty()) {
            printLine("Usage: read <filename>");
            return;
        }
        readFile(args.param1);
    }
    else if (mainCmd == "delete" || mainCmd == "rm") {
        if (args.param1.empty()) {
            printLine("Usage: delete <filename>");
            return;
        }
        deleteFile(args.param1);
    }
    else if (mainCmd == "ls" || mainCmd == "dir") {
        listFiles();
    }
    else if (mainCmd == "mv" || mainCmd == "rename") {
        if (args.param1.empty() || args.param2.empty()) {
            printLine("Usage: mv <old> <new>");
            return;
        }
        renameFile(args.param1, args.param2);
    }
    else if (mainCmd == "cp" || mainCmd == "copy") {
        if (args.param1.empty() || args.param2.empty()) {
            printLine("Usage: cp <src> <dst>");
