namespace search {

ViewportSearchCallback::ViewportSearchCallback(m2::RectD const & viewport, Delegate & delegate, OnResults onResults)
  : m_viewport(viewport)
  , m_delegate(delegate)
  , m_onResults(std::move(onResults))
  , m_firstCall(true)
  , m_lastResultsSize(0)
{
  // m_onResults may be empty (current Android)
}

void ViewportSearchCallback::operator()(Results const & results)
{
  ASSERT_LESS_OR_EQUAL(m_lastResultsSize, results.GetCount(), ());

  // Determine whether to show new results:
  // - Only if viewport search is still active
  // - And either:
  //   * search ended normally, OR
  //   * not an end marker AND there are new results
  bool shouldShowNewResults = false;
  if (m_delegate.IsViewportSearchActive()) {
    bool const isNormalEnd = results.IsEndedNormal();
    bool const hasNewData = !results.IsEndMarker() && results.GetCount() > m_lastResultsSize;
    shouldShowNewResults = isNormalEnd || hasNewData;
  }

  auto const lastSize = m_lastResultsSize;
  auto const firstTime = m_firstCall;
  auto const onResultsFn = m_onResults;

  m_delegate.RunUITask([this, shouldShowNewResults, lastSize, firstTime, onResultsFn]() mutable
  {
    if (shouldShowNewResults) {
      // Show only newly added results since last batch
      auto beginIt = m_results.begin() + lastSize;
      auto endIt = m_results.end();
      m_delegate.ShowViewportSearchResults(beginIt, endIt, firstTime);
    }

    if (onResultsFn && m_results.IsEndMarker())
      onResultsFn(std::move(m_results));
  });

  m_lastResultsSize = results.GetCount();
  m_firstCall = false;
}

}  // namespace search

