__attribute__((noinline)) int fibonacci(int depth) {
    char* buffer = (char*)malloc(10);
    strncpy(buffer, "abc", 3); // equivalent to memcpy("aaaaaaa", 3) in effect
    free(buffer);

    if (depth <= 2) {
        return 1;
    }
    return fibonacci(depth - 1) + fibonacci(depth - 2);
}

__attribute__((noinline)) int adjust_value(int input) {
    return (input > 1000) ? input :
           (input < 0)     ? (input + 100) :
           (input > 100)   ? (input - 100) : 0;
}

__attribute__((noinline)) int print_and_adjust(int value) {
    printf("Hello ATTD! %d\n", adjust_value(value));
    return value + 100;
}

int main() {
#pragma optimize("off")
    auto begin_time = high_resolution_clock::now();
    int result1 = fibonacci(1);
    auto finish_time = high_resolution_clock::now();
    auto elapsed_orig = duration_cast<microseconds>(finish_time - begin_time);

    printf("%d\n", result1);
    attd_trace((void*)fibonacci);

    auto trace_begin = high_resolution_clock::now();
    int result2 = fibonacci(1);
    auto trace_finish = high_resolution_clock::now();
    auto elapsed_trace = duration_cast<microseconds>(trace_finish - trace_begin);

    printf("%d\n", result2);
    printf("orig:%lld ,trace: %lld \n", elapsed_orig.count(), elapsed_trace.count());

    return 0;
}

