// Constants for memory slot status flags
constexpr int MEM_LOCKED_FLAG = 1;
constexpr int MEM_SPECIAL_FLAG = 2;

void MemSlotVector::init(PhyloTree *tree, int num_slots) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    // Pre-allocate space and resize vector
    reserve(num_slots + 2);
    resize(num_slots);

    const size_t partial_lh_size = tree->getPartialLhSize();
    const size_t scale_num_size = tree->getScaleNumSize();

    reset();

    // Assign pointers to each slot based on base addresses from tree
    for (size_t idx = 0; idx < size(); ++idx) {
        iterator current_slot = begin() + idx;
        current_slot->partial_lh = tree->central_partial_lh + partial_lh_size * idx;
        current_slot->scale_num = tree->central_scale_num + scale_num_size * idx;
    }
}

void MemSlotVector::reset() {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    for (auto &slot : *this) {
        slot.status = 0;
        slot.nei = nullptr;
    }

    nei_id_map.clear();
    free_count = 0;
}

MemSlotVector::iterator MemSlotVector::findNei(PhyloNeighbor *nei) {
    auto found = nei_id_map.find(nei);
    ASSERT(found != nei_id_map.end());
    return begin() + found->second;
}

void MemSlotVector::addNei(PhyloNeighbor *nei, iterator slot_it) {
    // Link neighbor to memory slot
    nei->partial_lh = slot_it->partial_lh;
    nei->scale_num = slot_it->scale_num;
    slot_it->nei = nei;
    nei_id_map[nei] = std::distance(begin(), slot_it);
}

void MemSlotVector::addSpecialNei(PhyloNeighbor *nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    MemSlot new_slot;
    new_slot.status = MEM_SPECIAL_FLAG | MEM_LOCKED_FLAG;
    new_slot.nei = nei;
    new_slot.partial_lh = nei->partial_lh;
    new_slot.scale_num = nei->scale_num;

    push_back(new_slot);
    nei_id_map[nei] = static_cast<int>(size()) - 1;
}

void MemSlotVector::eraseSpecialNei() {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    while (!empty() && (back().status & MEM_SPECIAL_FLAG)) {
        nei_id_map.erase(back().nei);
        pop_back();
    }
}

bool MemSlotVector::lock(PhyloNeighbor *nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return false;

    if (nei->node->isLeaf())
        return false;

    iterator slot = findNei(nei);
    if (slot->status & MEM_SPECIAL_FLAG)
        return false;

    ASSERT(!(slot->status & MEM_LOCKED_FLAG));
    slot->status |= MEM_LOCKED_FLAG;
    return true;
}

void MemSlotVector::unlock(PhyloNeighbor *nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    if (nei->node->isLeaf())
        return;

    iterator slot = findNei(nei);
    if (slot->status & MEM_SPECIAL_FLAG)
        return;

    ASSERT(slot->status & MEM_LOCKED_FLAG);
    slot->status &= ~MEM_LOCKED_FLAG;
}

bool MemSlotVector::locked(PhyloNeighbor *nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return false;

    if (nei->node->isLeaf())
        return false;

    iterator slot = findNei(nei);
    if (slot->status & MEM_SPECIAL_FLAG)
        return false;

    return (slot->status & MEM_LOCKED_FLAG) != 0;
}

int MemSlotVector::allocate(PhyloNeighbor *nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return -1;

    // Try to use next free slot first
    if (free_count < static_cast<int>(size()) && !(at(free_count).status & MEM_SPECIAL_FLAG)) {
        iterator slot = begin() + free_count;
        ASSERT(slot->nei == nullptr);
        addNei(nei, slot);
        ++free_count;
        return static_cast<int>(std::distance(begin(), slot));
    }

    // Otherwise, find best unlocked non-special slot with minimal size
    int min_size = INT_MAX;
    iterator best_slot = end();

    for (auto it = begin(); it != end(); ++it) {
        if ((it->status & (MEM_LOCKED_FLAG | MEM_SPECIAL_FLAG)) == 0 &&
            it->nei && it->nei->size < min_size) {
            best_slot = it;
            min_size = it->nei->size;
            if (min_size <= 2) break; // Early exit: minimum possible size
        }
    }

    if (best_slot == end())
        return -1;

    // Reuse this slot: clear old neighbor's partial likelihood data
    best_slot->nei->clearPartialLh();
    addNei(nei, best_slot);
    return static_cast<int>(std::distance(begin(), best_slot));
}

void MemSlotVector::update(PhyloNeighbor *nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator slot = findNei(nei);
    if (slot->nei != nei) {
        slot->nei->clearPartialLh();
        addNei(nei, slot);
    }
}

