void MemSlotVector::takeover(PhyloNeighbor *new_nei, PhyloNeighbor *old_nei) {
    ASSERT(old_nei->partial_lh);

    // Transfer memory references
    new_nei->partial_lh = old_nei->partial_lh;
    new_nei->scale_num = old_nei->scale_num;

    old_nei->partial_lh = nullptr;
    old_nei->scale_num = nullptr;
    old_nei->partial_lh_computed &= ~1;

    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator slot = findNei(old_nei);
    nei_id_map.erase(old_nei);
    nei_id_map[new_nei] = static_cast<int>(std::distance(begin(), slot));

    if (slot->nei == old_nei) {
        slot->nei = new_nei;
    }
}

void MemSlotVector::replace(PhyloNeighbor *new_nei, PhyloNeighbor *old_nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator slot = findNei(old_nei);
    ASSERT(slot->partial_lh == old_nei->partial_lh);

    slot->saved_nei = slot->nei;
    slot->nei = new_nei;
    slot->partial_lh = new_nei->partial_lh;
    slot->scale_num = new_nei->scale_num;
    slot->status = MEM_LOCKED_FLAG | MEM_SPECIAL_FLAG;

    nei_id_map[new_nei] = static_cast<int>(std::distance(begin(), slot));
    // Note: old_nei is not removed from map yet

    std::cout << "slot " << std::distance(begin(), slot) << " replaced" << std::endl;
}

void MemSlotVector::restore(PhyloNeighbor *new_nei, PhyloNeighbor *old_nei) {
    if (Params::getInstance().lh_mem_save != LM_MEM_SAVE)
        return;

    iterator slot = findNei(new_nei);
    ASSERT(slot->nei == new_nei);
    ASSERT(nei_id_map.count(old_nei) && nei_id_map[old_nei] == static_cast<int>(std::distance(begin(), slot)));

    slot->nei = slot->saved_nei;
    slot->saved_nei = nullptr;
    slot->partial_lh = old_nei->partial_lh;
    slot->scale_num = old_nei->scale_num;
    slot->status = 0;

    nei_id_map.erase(new_nei);
    // Restore mapping for old_nei (commented out original line)

    std::cout << "slot " << std::distance(begin(), slot) << " restored" << std::endl;
}

#include "Utils/Parallel/MultiThreading.h"

// Constructor: creates and initializes a pthread mutex
PPMutex::PPMutex() {
  int result = pthread_mutex_init(&mutex, nullptr);
  is_valid = (result == 0);
}

// Destructor: destroys the pthread mutex
PPMutex::~PPMutex() {
  pthread_mutex_destroy(&mutex);
  is_valid = false;
}

// Checks whether the mutex object is in a valid state
bool PPMutex::isValid() { return is_valid; }

// Attempts to acquire exclusive lock on the mutex
bool PPMutex::lock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_mutex_lock(&mutex);
  return (result == 0);
}

// Releases the exclusive lock held on the mutex
bool PPMutex::unlock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_mutex_unlock(&mutex);
  return (result == 0);
}

// Constructor: initializes a pthread read-write lock
PPReadWriteLock::PPReadWriteLock() {
  int result = pthread_rwlock_init(&mutex, nullptr);
  is_valid = (result == 0);
}

// Destructor: destroys the pthread read-write lock
PPReadWriteLock::~PPReadWriteLock() {
  pthread_rwlock_destroy(&mutex);
  is_valid = false;
}

// Reports if the read-write lock was successfully created
bool PPReadWriteLock::isValid() { return is_valid; }

// Acquires shared (read) access to the resource
bool PPReadWriteLock::rdLock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_rdlock(&mutex);
  return (result == 0);
}

// Acquires exclusive (write) access to the resource
bool PPReadWriteLock::wrLock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_wrlock(&mutex);
  return (result == 0);
}

// Releases a previously acquired read lock
bool PPReadWriteLock::rdUnlock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_unlock(&mutex);
  return (result == 0);
}

// Releases a previously acquired write lock
bool PPReadWriteLock::wrUnlock() {
  if (!isValid()) {
    return false;
  }
  int result = pthread_rwlock_unlock(&mutex);
  return (result == 0);
}

// Constructor: creates a thread-specific data key with optional destructor
PPThreadData::PPThreadData(void (*destructor)(void *)) {
  int result = pthread_key_create(&key, destructor);
  is_valid = (result == 0);
}

// Destructor: deletes the thread-specific data key
PPThreadData::~PPThreadData() {
  pthread_key_delete(key);
  is_valid = false;
}

// Indicates whether the thread data key was properly initialized
bool PPThreadData::isValid() { return is_valid; }

// Associates a value with the current thread for this key
bool PPThreadData::setValue(void *data) {
  if (!isValid()) {
    return false;
  }
  int result = pthread_setspecific(key, data);
  return (result == 0);
}

// Retrieves the value associated with the current thread for this key
void *PPThreadData::getValue() {
  if (!isValid()) {
    return nullptr;
  }
  return pthread_getspecific(key);
}

// Returns the identifier of the calling thread
PPThreadIDType getCurrentThreadID() { return pthread_self(); }

#include "ftpdaemon.h"
#include <circle/logger.h>
