#include <circle/string.h>
#include "ftpworker.h"

LOGMODULE("ftpd");

constexpr u16 ControlPort = 21;
constexpr u8 MaxSimultaneousClients = 1;

CFTPDaemon::CFTPDaemon(const char* pUser, const char* pPassword)
    : CTask(TASK_STACK_SIZE, true),
      m_pControlSocket(nullptr),
      m_pUsername(pUser),
      m_pCredential(pPassword) {
}

CFTPDaemon::~CFTPDaemon() {
    if (m_pControlSocket)
        delete m_pControlSocket;
}

bool CFTPDaemon::Initialize() {
    CNetSubSystem* const pNetwork = CNetSubSystem::Get();
    if ((m_pControlSocket = new CSocket(pNetwork, IPPROTO_TCP)) == nullptr)
        return false;

    if (m_pControlSocket->Bind(ControlPort) != 0) {
        LOGERR("Failed to bind control socket to port %u", ControlPort);
        return false;
    }

    if (m_pControlSocket->Listen() != 0) {
        LOGERR("Control socket listen operation failed");
        return false;
    }

    Start();  // Resume task after successful setup
    return true;
}

void CFTPDaemon::Run() {
    assert(m_pControlSocket != nullptr);
    LOGNOTE("FTP daemon listening started");

    while (true) {
        CIPAddress remoteAddress;
        u16 remotePort;

        LOGDBG("Awaiting incoming connection...");
        CSocket* pClientSocket = m_pControlSocket->Accept(&remoteAddress, &remotePort);

        if (pClientSocket == nullptr) {
            LOGERR("Connection acceptance failed");
            continue;
        }

        CString ipString;
        remoteAddress.Format(&ipString);
        LOGNOTE("Accepted connection from %s:%d", static_cast<const char*>(ipString), remotePort);

        if (CFTPWorker::GetInstanceCount() >= MaxSimultaneousClients) {
            pClientSocket->Send("421 Too many connections. Try again later.\r\n", 47, 0);
            delete pClientSocket;
            LOGWARN("Connection limit exceeded; rejecting new client");
            continue;
        }

        // Create and initialize new worker for the client
        new CFTPWorker(pClientSocket, m_pUsername, m_pCredential);
    }
}

#include <charPipeline/structures/dolphinString.h>

// Concatenates two strings into a destination buffer
u8 ConcatenateStrings(char* first, char* second, char* destination) {
    char* sourcePointer = first;
    char* destPointer = destination;

    if (!destination) {
        return 0;
    }
    if (!first) {
        return 0;
    }
    if (!second) {
        return 0;
    }

    // Copy first string
    while ((s8)*sourcePointer != 0) {
        *destPointer = *sourcePointer;
        destPointer++;
        sourcePointer++;
    }

    // Append second string
    sourcePointer = second;
    while ((s8)*sourcePointer != 0) {
        *destPointer = *sourcePointer;
        destPointer++;
        sourcePointer++;
    }

    // Null-terminate the result
    *destPointer = 0;
    return 1;
}

// Copies source string to destination (including null terminator)
void CopyString(char* destination, char* source) {
    do {
        *destination = *source;
        destination++;
        source++;
    } while ((s8)*source != 0);
}

// Compares two strings lexicographically
// Returns: -1 if str1 > str2, 1 if str1 < str2, 0 if equal
s8 CompareStrings(char* string1, char* string2) {
    char* ptr1 = string1;
    char* ptr2 = string2;

    while (true) {
        s8 byte1 = (s8)*ptr1;
        s8 byte2 = (s8)*ptr2;

        if (byte1 < byte2) {
            return 1;
        }
        if (byte1 > byte2) {
            return -1;
        }

        ptr1++;
        ptr2++;

        // Stop when either string ends
        if (byte1 == 0 || byte2 == 0) {
            return 0;
        }
    }
}

// Calculates length of a null-terminated string
u32 StringLength(char* str) {
    char* index = str;
    u32 count = 0;

    if (!str) {
        return 0;
    }

    while ((s8)*index != 0) {
        index++;
        count++;
    }

    return count;
}

