#define STRCASECMP(LHS, RHS) strcasecmp_P(LHS, reinterpret_cast<const char*>(RHS))
#define STRLEN(PTR) strlen_P(PTR)
#else
#define STRCASECMP strcasecmp
#define STRLEN(PTR) strlen(PTR)
