/// Reverse the order of bits in a value
/// @param[in] value Input bit pattern
/// @param[in] bitCount Number of bits to reverse
/// @return Reversed bit pattern
uint64_t reverseBits(uint64_t value, uint16_t bitCount) {
  if (bitCount <= 1) return value;

  // Limit bit count to maximum possible bits
  const uint16_t maxBits = sizeof(value) * 8;
  bitCount = std::min(bitCount, maxBits);

  uint64_t result = 0;
  uint16_t position = 0;

  // Extract and reverse bits one by one
  while (position < bitCount) {
    result <<= 1;
    result |= (value & 1);
    value >>= 1;
    position++;
  }

  // Combine remaining bits with reversed portion
  return (value << bitCount) | result;
}

/// Convert unsigned 64-bit integer to string representation
/// @param[in] number Value to convert
/// @param[in] radix Output base (2-36)
/// @returns String representation
String uint64ToString(uint64_t number, uint8_t radix) {
  String output = "";

  // Validate base parameter
  if (radix < 2) radix = 10;
  if (radix > 36) radix = 10;

  // Reserve memory for efficiency
  output.reserve(16);

  // Handle zero case
  if (number == 0) {
    output = '0';
    return output;
  }

  // Convert digits from right to left
  do {
    uint64_t remainder = number % radix;
    number /= radix;

    char digit;
    if (remainder < 10) {
      digit = '0' + remainder;
    } else {
      digit = 'A' + (remainder - 10);
    }
    output = digit + output;
  } while (number > 0);

  return output;
}

/// Convert signed 64-bit integer to string representation
/// @param[in] number Value to convert
/// @param[in] radix Output base (2-36)
/// @returns String representation
String int64ToString(int64_t number, uint8_t radix) {
  if (number < 0) {
    return String(kDashStr) + uint64ToString(-number, radix);
  }
  return uint64ToString(number, radix);
}

