/// Convert protocol name string to decode_type_t enum
/// @param[in] name Protocol name string
/// @return decode_type_t enum value
decode_type_t strToDecodeType(const char * const name) {
  const char* protocolNames = reinterpret_cast<const char*>(kAllProtocolNamesStr);
  uint16_t nameLength = STRLEN(protocolNames);

  // Search through protocol names array
  for (uint16_t index = 0; nameLength > 0; index++) {
    if (!STRCASECMP(name, protocolNames)) {
      return static_cast<decode_type_t>(index);
    }
    protocolNames += nameLength + 1;
    nameLength = STRLEN(protocolNames);
  }

  // Try parsing as integer protocol number
  decode_type_t numericResult = strToDecodeType(
      typeToString(static_cast<decode_type_t>(atoi(name))).c_str());
  if (numericResult > 0) {
    return numericResult;
  }

  return decode_type_t::UNKNOWN;
}

/// Convert protocol enum to human-readable string
/// @param[in] protocol Protocol type enum
/// @param[in] isRepeat Flag indicating repeat message
/// @return Protocol name string
String typeToString(const decode_type_t protocol, const bool isRepeat) {
  String output = "";
  output.reserve(30);  // Space for longest protocol name + "(Repeat)"

  if (protocol > kLastDecodeType || protocol == decode_type_t::UNKNOWN) {
    output = kUnknownStr;
  } else {
    const char* protocolNames = reinterpret_cast<const char*>(kAllProtocolNamesStr);
    for (uint16_t index = 0; index <= protocol && STRLEN(protocolNames); index++) {
      if (index == protocol) {
        output = FPSTR(protocolNames);
        break;
      }
      protocolNames += STRLEN(protocolNames) + 1;
    }
  }

  if (isRepeat) {
    output += kSpaceLBraceStr;
    output += kRepeatStr;
    output += ')';
  }

  return output;
}

