/// Calculate corrected raw buffer length after expansion
/// @param[in] results Pointer to decode results
/// @return Corrected length
uint16_t getCorrectedRawLength(const decode_results * const results) {
  uint16_t extendedLength = results->rawlen - 1;

  for (uint16_t i = 0; i < results->rawlen - 1; i++) {
    uint32_t usecs = results->rawbuf[i] * kRawTick;
    // Add extra entries for values exceeding UINT16_MAX
    extendedLength += (usecs / (UINT16_MAX + 1)) * 2;
  }

  return extendedLength;
}

/// Generate source code representation of decode results
/// @param[in] results Pointer to decode results
/// @return Source code formatted string
String resultToSourceCode(const decode_results * const results) {
  String output = "";
  const uint16_t length = getCorrectedRawLength(results);
  const bool hasState = hasACState(results->decode_type);

  // Estimate required space
  size_t reserveSize = 55 + (length * 7);
  if (hasState) {
    reserveSize += 25 + (results->bits / 8) * 6;
  } else {
    reserveSize += 116;
  }
  output.reserve(reserveSize);

  // Start declaration
  output += F("uint16_t ");
  output += F("rawData[");
  output += uint64ToString(length, 10);
  output += F("] = {");

  // Dump raw timing data
  for (uint16_t i = 1; i < results->rawlen; i++) {
    uint32_t usecs = results->rawbuf[i] * kRawTick;

    // Split large values into multiple entries
    while (usecs > UINT16_MAX) {
      output += uint64ToString(UINT16_MAX);
      if (i % 2) {
        output += F(", 0,  ");
      } else {
        output += F(",  0, ");
      }
      usecs -= UINT16_MAX;
    }

    output += uint64ToString(usecs, 10);
    if (i < results->rawlen - 1) {
      output += kCommaSpaceStr;
    }
    if (i % 2 == 0) {
      output += ' ';
    }
  }
  output += F("};");

  // Add comment with protocol info
  output += F("  // ");
  output += typeToString(results->decode_type, results->repeat);

  if (!hasState) {
    output += ' ' + uint64ToString(results->value, 16);
  }
  output += F("\n");

  // Add state or simple protocol data
  if (results->decode_type != UNKNOWN) {
    if (hasState) {
#if DECODE_AC
      uint16_t byteCount = ceil(static_cast<float>(results->bits) / 8.0);
      output += F("uint8_t state[");
      output += uint64ToString(byteCount);
      output += F("] = {");

      for (uint16_t i = 0; i < byteCount; i++) {
        output += F("0x");
        if (results->state[i] < 0x10) output += '0';
        output += uint64ToString(results->state[i], 16);
        if (i < byteCount - 1) output += kCommaSpaceStr;
      }
      output += F("};\n");
#endif
    } else {
      // Simple protocols with address/command
      if (results->address > 0 || results->command > 0) {
        output += F("uint32_t address = 0x");
        output += uint64ToString(results->address, 16);
        output += F(";\n");
        output += F("uint32_t command = 0x");
        output += uint64ToString(results->command, 16);
        output += F(";\n");
      }

      // Data value
      output += F("uint64_t data = 0x");
      output += uint64ToString(results->value, 16);
      output += F(";\n");
    }
  }

  return output;
}

/// Convert decode results to timing information string
/// @param[in] results Pointer to decode results
/// @return Timing information string
String resultToTimingInfo(const decode_results * const results) {
  String output = "";
  String value = "";

  // Reserve space for output
  output.reserve(19 + 12 * results->rawlen);
  value.reserve(6);

  output += F("Raw Timing[");
  output += uint64ToString(results->rawlen - 1, 10);
  output += F("]:\n");

  for (uint16_t i = 1; i < results->rawlen; i++) {
    if (i % 2 == 0) {
      output += kDashStr;  // even
    } else {
      output += F("   +");  // odd
    }

    value = uint64ToString(results->rawbuf[i] * kRawTick);
    // Pad value to at least 6 characters
    while (value.length() < 6) {
      value = ' ' + value;
    }
    output += value;

    if (i < results->rawlen - 1) {
      output += kCommaSpaceStr;
    }

    if (!(i % 8)) {
      output += '\n';  // Newline every 8 entries
    }
  }
  output += '\n';

  return output;
}

/// Convert decode results to hexadecimal string
/// @param[in] result Pointer to decode results
/// @return Hexadecimal string representation
String resultToHexidecimal(const decode_results * const result) {
  String output = F("0x");
  output.reserve(2 * kStateSizeMax + 2);

  if (hasACState(result->decode_type)) {
#if DECODE_AC
    for (uint16_t i = 0; result->bits > i * 8; i++) {
      if (result->state[i] < 0x10) output += '0';
      output += uint64ToString(result->state[i], 16);
    }
#endif
  } else {
    output += uint64ToString(result->value, 16);
  }

  return output;
}

/// Generate basic human-readable output from decode results
/// @param[in] results Pointer to decode results
/// @return Human readable string
String resultToHumanReadableBasic(const decode_results * const results) {
  String output = "";
  output.reserve(2 * kStateSizeMax + 70);

  // Protocol line
  output += kProtocolStr;
  output += F("  : ");
  output += typeToString(results->decode_type, results->repeat);
  output += '\n';

  // Code line
  output += kCodeStr;
  output += F("      : ");
  output += resultToHexidecimal(results);
  output += kSpaceLBraceStr;
  output += uint64ToString(results->bits);
  output += ' ';
  output += kBitsStr;
  output += F(")\n");

  return output;
}

/// Convert decode results to sendRaw-compatible array
/// @param[in] decode Pointer to decode results
/// @return Dynamically allocated array (caller must free)
uint16_t* resultToRawArray(const decode_results * const decode) {
  uint16_t arrayLength = getCorrectedRawLength(decode);
  uint16_t* result = new uint16_t[arrayLength];

  if (result != NULL) {
    uint16_t position = 0;
    for (uint16_t i = 1; i < decode->rawlen; i++) {
      uint32_t usecs = decode->rawbuf[i] * kRawTick;

      // Split large values
      while (usecs > UINT16_MAX) {
        result[position++] = UINT16_MAX;
        result[position++] = 0;
        usecs -= UINT16_MAX;
      }
      result[position++] = usecs;
    }
  }

  return result;
}

/// Sum bytes in array and return LSB of result
/// @param[in] start Pointer to start of array
/// @param[in] length Number of bytes to sum
/// @param[in] init Initial sum value
/// @return 8-bit sum result
uint8_t sumBytes(const uint8_t * const start, const uint16_t length,
                 const uint8_t init) {
  uint8_t checksum = init;
  const uint8_t* ptr;

  for (ptr = start; ptr - start < length; ptr++) {
    checksum += *ptr;
  }

  return checksum;
}

/// XOR all bytes in array
/// @param[in] start Pointer to start of array
/// @param[in] length Number of bytes to process
/// @param[in] init Initial XOR value
/// @return 8-bit XOR result
uint8_t xorBytes(const uint8_t * const start, const uint16_t length,
                 const uint8_t init) {
  uint8_t checksum = init;
  const uint8_t* ptr;

  for (ptr = start; ptr - start < length; ptr++) {
    checksum ^= *ptr;
  }

  return checksum;
}

/// Count specific bits in byte array
/// @param[in] start Pointer to start of array
/// @param[in] length Number of bytes to process
/// @param[in] ones If true count 1-bits, else count 0-bits
/// @param[in] init Initial count value
/// @return Number of bits found
uint16_t countBits(const uint8_t * const start, const uint16_t length,
                   const bool ones, const uint16_t init) {
  uint16_t count = init;

  for (uint16_t offset = 0; offset < length; offset++) {
    uint8_t currentByte = *(start + offset);
    while (currentByte) {
      if (currentByte & 1) count++;
      currentByte >>= 1;
    }
  }

  if (ones || length == 0) {
    return count;
  } else {
    return (length * 8) - count;
  }
}

/// Count specific bits in integer value
/// @param[in] data Value to examine
/// @param[in] length Number of bits to examine (from LSB)
/// @param[in] ones If true count 1-bits, else count 0-bits
/// @param[in] init Initial count value
/// @return Number of bits found
uint16_t countBits(const uint64_t data, const uint8_t length, const bool ones,
                   const uint16_t init) {
  uint16_t count = init;
  uint8_t bitsRemaining = length;

  for (uint64_t remainder = data; remainder && bitsRemaining;
       remainder >>= 1, bitsRemaining--) {
    if (remainder & 1) count++;
  }

  if (ones || length == 0) {
    return count;
  } else {
    return length - count;
  }
}

/// Invert/flipping bits in value
/// @param[in] data Value to invert
/// @param[in] nbits Number of bits to invert (from LSB)
/// @return Inverted value
uint64_t invertBits(const uint64_t data, const uint16_t nbits) {
  if (nbits == 0) return data;

  uint64_t result = ~data;

  if (nbits >= sizeof(data) * 8) {
    return result;
  }

  // Mask off unwanted bits
  return (result & ((1ULL << nbits) - 1));
}

/// Convert Celsius to Fahrenheit
float celsiusToFahrenheit(const float degrees) {
  return (degrees * 9.0) / 5.0 + 32.0;
}

/// Convert Fahrenheit to Celsius
float fahrenheitToCelsius(const float degrees) {
  return (degrees - 32.0) * 5.0 / 9.0;
}

namespace irutils {
/// Create colon-separated label:value pair
/// @param[in] value Value to include
/// @param[in] label Label text
/// @param[in] precomma Include leading comma-space
/// @return Formatted string
String addLabeledString(const String value, const String label,
                        const bool precomma) {
