/// @param[in] precomma Include leading comma-space
/// @param[in] isSensorTemp Is this a sensor reading?
/// @return Formatted temperature string
String addTempFloatToString(const float degrees, const bool celsius,
                            const bool precomma, const bool isSensorTemp) {
  String result = "";
  result.reserve(21);
  result += addIntToString(degrees, (isSensorTemp)?
                           kSensorTempStr : kTempStr, precomma);

  // Check for half-degree increments
  if (static_cast<uint16_t>(2 * degrees) % 2) {
