#include <iostream>
#include <string>
#include <vector>
#include <map>
#include <stack>
#include <cassert>
using namespace std;

// Represents a chamber in the structure
struct Room {
    int identifier;
    int predecessor;      
    int incoming_tunnel;  
    int next_tunnel_to_try; 
    int obstacle_side;     // 0 for left, 1 for right
    int obstacle_tunnel;  
    bool explored;
};

int total_tunnels;
int room_counter = 0;
vector<Room> rooms;
map<pair<int, int>, int> fingerprint_map; // (obstacle_side, obstacle_tunnel) -> room_id
stack<int> exploration_stack;

// Read stone configuration from input
void read_obstacle(string& side_name, int& tunnel_index) {
    cin >> side_name;
    if (side_name == "center") {
        tunnel_index = -1;
    } else if (side_name == "left" || side_name == "right") {
        cin >> tunnel_index;
    } else if (side_name == "treasure") {
        tunnel_index = -1;
    }
}

// Convert string direction to integer representation
int direction_to_index(const string& dir) {
    if (dir == "left") return 0;
    if (dir == "right") return 1;
    return -1;
}

// Convert integer direction back to string
string index_to_direction(int idx) {
    return idx == 0 ? "left" : "right";
}

// Calculate circular distance between two tunnel indices
int circular_distance(int start, int end) {
    return (end - start + total_tunnels) % total_tunnels;
}

int main() {
    cin >> total_tunnels;
    string side_name;
    int tunnel_index;

    // Initialize starting position
    read_obstacle(side_name, tunnel_index);
    assert(side_name == "center");

    Room initial_room;
    initial_room.identifier = room_counter++;
    initial_room.predecessor = -1;
    initial_room.incoming_tunnel = -1;
    initial_room.next_tunnel_to_try = 0;
    initial_room.obstacle_side = 0;
    initial_room.obstacle_tunnel = 0;
    initial_room.explored = false;

    rooms.push_back(initial_room);
    fingerprint_map[{0, 0}] = initial_room.identifier;
    exploration_stack.push(initial_room.identifier);

    cout << "0 left 0" << endl;

    // Main exploration loop
    while (true) {
        read_obstacle(side_name, tunnel_index);

        if (side_name == "treasure") {
            break;
        }

        int current_room_id;

        if (side_name == "center") {
            // Create new room when encountering center
            Room new_room;
            new_room.identifier = room_counter++;
            new_room.predecessor = exploration_stack.top();
            new_room.incoming_tunnel = -1;
            new_room.next_tunnel_to_try = 0;
            new_room.explored = false;

            // Compute fingerprint based on room ID
            int fp_side, fp_tunnel;
            if (new_room.identifier < total_tunnels) {
                fp_side = 0;
                fp_tunnel = new_room.identifier;
            } else if (new_room.identifier - total_tunnels < total_tunnels) {
                fp_side = 1;
                fp_tunnel = new_room.identifier - total_tunnels;
            } else {
                fp_side = (new_room.identifier / total_tunnels) % 2;
                fp_tunnel = new_room.identifier % total_tunnels;
            }

            new_room.obstacle_side = fp_side;
            new_room.obstacle_tunnel = fp_tunnel;

            rooms.push_back(new_room);
            fingerprint_map[{fp_side, fp_tunnel}] = new_room.identifier;
            current_room_id = new_room.identifier;
            exploration_stack.push(current_room_id);
        } else {
            // Handle side-specific encounter
            int dir_idx = direction_to_int(side_name);
            auto key = make_pair(dir_idx, tunnel_index);

            if (fingerprint_map.find(key) == fingerprint_map.end()) {
                // New room found
                Room new_room;
                new_room.identifier = room_counter++;
                new_room.predecessor = -1;
                new_room.incoming_tunnel = -1;
                new_room.next_tunnel_to_try = 0;
                new_room.obstacle_side = dir_idx;
                new_room.obstacle_tunnel = tunnel_index;
                new_room.explored = false;

                rooms.push_back(new_room);
                fingerprint_map[key] = new_room.identifier;
                current_room_id = new_room.identifier;
                exploration_stack.push(current_room_id);
            } else {
                // Existing room referenced
                current_room_id = fingerprint_map[key];
            }
        }

        // Process current room
        Room& current = rooms[current_room_id];

        if (current.next_tunnel_to_try < total_tunnels) {
            // Still exploring tunnels from this room
            int tunnel_num = current.next_tunnel_to_try;
            current.next_tunnel_to_try++;

            int move_dist = circular_distance(current.obstacle_tunnel, tunnel_num);
            cout << move_dist << " left " << move_dist << endl;

            current.obstacle_side = 0;
            current.obstacle_tunnel = tunnel_num;
            fingerprint_map[{0, tunnel_num}] = current_room_id;
        } else {
            // Finished exploring tunnels in this room
            current.explored = true;

            if (current.predecessor == -1) {
                // Root room: exit via right side
                int move_dist = circular_distance(current.obstacle_tunnel, current.obstacle_tunnel);
                cout << move_dist << " right " << 0 << endl;
                current.obstacle_side = 1;
                fingerprint_map[{1, current.obstacle_tunnel}] = current_room_id;
            } else {
                // Non-root room: return to parent
                Room& prev = rooms[current.predecessor];
                int enter_dist = circular_distance(current.obstacle_tunnel, current.incoming_tunnel);
                int exit_dist = circular_distance(current.obstacle_tunnel, current.incoming_tunnel);

                cout << enter_dist << " right " << exit_dist << endl;
                current.obstacle_side = 1;
                current.obstacle_tunnel = current.incoming_tunnel;
                fingerprint_map[{1, current.incoming_tunnel}] = current_room_id;
                exploration_stack.pop();
            }
        }
    }

    return 0;
}

#include "tserverproxy.h"
#include <iostream>
#include <winsock2.h>
#include <fcntl.h>
#include <errno.h>
#include <cstdio>
#include <cstring>
#include <ctime>
#include <cassert>
#include <vector>
#include <string>

using namespace std;

// Error codes remain unchanged for compatibility
enum {
  OK,
  WSASTARTUP_FAILED,
  HOST_UNKNOWN,
  SOCKET_CREATION_FAILED,
  CONNECTION_FAILED,
  SEND_FAILED,
  RECEIVE_FAILED
};

// Helper function to resolve hostname — returns nullptr on failure
const char* getHostAddress(const string& hostname) {
    hostent* he = gethostbyname(hostname.c_str());
    return he ? reinterpret_cast<const char*>(he->h_addr_list[0]) : nullptr;
}

// Helper to build socket address structure
sockaddr_in createSocketAddress(int family, unsigned short port, const char* ipBytes, size_t len) {
    sockaddr_in addr{};
    addr.sin_family = family;
    addr.sin_port   = htons(port);
    memcpy(&addr.sin_addr.s_addr, ipBytes, min(len, static_cast<size_t>(4)));
    return addr;
}

//=============================================================================
int askServer(const string& hostName, int portId, const string& question, string& answer) {
    // Resolve hostname
    const char* ipAddr = getHostAddress(hostName);
    if (!ipAddr) return HOST_UNKNOWN;

    // Create socket
    SOCKET sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock == INVALID_SOCKET) return SOCKET_CREATION_FAILED;

    // Prepare connection parameters
    sockaddr_in serverAddr = createSocketAddress(AF_INET, static_cast<unsigned short>(portId), ipAddr, 4);

    // Attempt connection
    if (connect(sock, reinterpret_cast<sockaddr*>(&serverAddr), sizeof(serverAddr)) == SOCKET_ERROR) {
        closesocket(sock);
        return CONNECTION_FAILED;
    }

    // Send request
    int bytesSent = send(sock, question.c_str(), static_cast<int>(question.size()), 0);
    if (bytesSent == SOCKET_ERROR) {
        closesocket(sock);
        return SEND_FAILED;
    }

    // Receive response
    vector<char> buffer(1024, 0);
    int bytesRead = recv(sock, buffer.data(), static_cast<int>(buffer.size()) - 1, 0);
    if (bytesRead == SOCKET_ERROR) {
        closesocket(sock);
        return RECEIVE_FAILED;
    }

    // Null-terminate and assign
    buffer[bytesRead] = '\0';
    answer = buffer.data();

    closesocket(sock);
    return OK;
}
//=============================================================================

TServerProxy::TServerProxy(const string& hostName, int portId)
    : m_hostName(hostName), m_portId(portId) {
#ifdef _WIN32
    WSADATA wsaData{};
    WORD version = MAKEWORD(2, 2);  // Updated to Winsock 2.2
    int result = WSAStartup(version, &wsaData);
    if (result != 0) {
        // Optionally log or handle startup failure
    }
#endif
}

//-----------------------------------------------------------------------------
TServerProxy::~TServerProxy() {
#ifdef _WIN32
    WSACleanup();
#endif
}

//-----------------------------------------------------------------------------
bool TServerProxy::testConnection() const {
    const char* ipAddr = getHostAddress(m_hostName);
    if (!ipAddr) return false;

    SOCKET sock = socket(AF_INET, SOCK_STREAM, IPPROTO_TCP);
    if (sock == INVALID_SOCKET) return false;

    sockaddr_in serverAddr = createSocketAddress(AF_INET, static_cast<unsigned short>(m_portId), ipAddr, 4);
    bool connected = (connect(sock, reinterpret_cast<sockaddr*>(&serverAddr), sizeof(serverAddr)) != SOCKET_ERROR);

    closesocket(sock);
    return connected;
}

//-----------------------------------------------------------------------------
int TServerProxy::exec(int argc, char* argv[], string& reply) {
    assert(argc >= 0);
    string command;

    if (argc > 0) {
        command = argv[0];
        // Use pointer arithmetic instead of index-based loop
        char** argPtr = argv + 1;
        for (int i = 1; i < argc; ++i, ++argPtr) {
            command += ",";
            command += *argPtr;
        }
    }

    return askServer(m_hostName, m_portId, command, reply);
}

#include <iostream>
#include <vector>
#include <unordered_map>
using namespace std;

// Leetcode 3: Longest substring without repeating characters
class Solution {
public:
    int lengthOfLongestSubstring(string s) {
        int len = s.size();
        int maxLen = 0;
        unordered_map<char, int> lastIndex;
        int start = 0;

        for (int end = 0; end < len; end++) {
            char currentChar = s[end];

            // If character seen and index is within current window, move start
            if (lastIndex.find(currentChar) != lastIndex.end() && lastIndex[currentChar] >= start) {
                start = lastIndex[currentChar] + 1;
            }

            // Update last seen index of current character
            lastIndex[currentChar] = end;

            // Update maximum length
            maxLen = max(maxLen, end - start + 1);
        }

        return maxLen;
    }
};

