// Helper functions to mimic registry behavior via INI files
void WritePrivateProfileString(const std::string& section, const std::string& key, const std::string& value, const std::string& ini_path) {
    std::ofstream file(ini_path, std::ios::app);
    if (file.is_open()) {
        file << "[" << section << "]" << std::endl;
        file << key << "=" << value << std::endl;
        file.close();
    }
}

std::string GetPrivateProfileString(const std::string& section, const std::string& key, const std::string& def, const std::string& ini_path) {
    std::ifstream file(ini_path);
    std::string line;
    std::string current_section;
    std::map<std::string, std::string> entries;

    if (!file.is_open()) return def;

    while (std::getline(file, line)) {
        if (line.empty() || line[0] == ';' || line[0] == '#') continue;

        // Trim whitespace
        size_t start = line.find_first_not_of(" \t\r\n");
        size_t end = line.find_last_not_of(" \t\r\n");
        if (start != std::string::npos && end != std::string::npos)
            line = line.substr(start, end - start + 1);

        if (line.front() == '[' && line.back() == ']') {
            current_section = line.substr(1, line.length() - 2);
            continue;
        }

        size_t eq_pos = line.find('=');
        if (eq_pos != std::string::npos) {
            std::string k = line.substr(0, eq_pos);
            std::string v = line.substr(eq_pos + 1);
            entries[k] = v;
        }
    }

    auto it = entries.find(key);
    return (it != entries.end()) ? it->second : def;
}

int GetPrivateProfileInt(const std::string& section, const std::string& key, int def, const std::string& ini_path) {
    std::string val = GetPrivateProfileString(section, key, "", ini_path);
    return val.empty() ? def : std::stoi(val);
}

void WritePrivateProfileInt(const std::string& section, const std::string& key, int value, const std::string& ini_path) {
    WritePrivateProfileString(section, key, std::to_string(value), ini_path);
}

