// Installation logic
bool InstallSC2KDefaults() {
    std::string ini_file = "sc2kfix.ini";

    // Check existing installation status
    bool installed = (GetPrivateProfileInt("Portable", "Installed", 0, ini_file) == 1);
    std::string mayor = GetPrivateProfileString("Registration", "Mayor Name", "", ini_file);
    std::string company = GetPrivateProfileString("Registration", "Company Name", "", ini_file);

    // If already fully configured, skip
    if (installed && !mayor.empty() && !company.empty()) {
        std::cout << "Already installed with valid settings." << std::endl;
        return false;
    }

    // Update installation flag
    WritePrivateProfileInt("Portable", "Installed", 1, ini_file);

    // Prompt user (simulated here as default values)
    // In real scenario, this would show dialog box
    szSettingsMayorName = "Marvin Maxis"; // Default
    szSettingsCompanyName = "Q37 Space Modulator Mfg."; // Default

    // Write version info
    WritePrivateProfileInt("Version", "SCURK", 0x00000100, ini_file);
    WritePrivateProfileInt("Version", "SimCity 2000", 0x00000100, ini_file);

    // Language
    WritePrivateProfileString("Localize", "Language", "USA", ini_file);

    // Options
    WritePrivateProfileInt("Options", "Disasters", 1, ini_file);
    WritePrivateProfileInt("Options", "Music", 1, ini_file);
    WritePrivateProfileInt("Options", "Sound", 1, ini_file);
    WritePrivateProfileInt("Options", "AutoGoto", 1, ini_file);
    WritePrivateProfileInt("Options", "AutoBudget", 0, ini_file);
    WritePrivateProfileInt("Options", "AutoSave", 0, ini_file);
    WritePrivateProfileInt("Options", "Speed", 5, ini_file); // LLAMA speed

    // SCURK options
    WritePrivateProfileInt("SCURK", "CycleColors", 1, ini_file);
    WritePrivateProfileInt("SCURK", "GridHeight", 2, ini_file);
    WritePrivateProfileInt("SCURK", "GridWidth", 2, ini_file);
    WritePrivateProfileInt("SCURK", "ShowClipRegion", 0, ini_file);
    WritePrivateProfileInt("SCURK", "ShowDrawGrid", 0, ini_file);
    WritePrivateProfileInt("SCURK", "SnapToGrid", 0, ini_file);
    WritePrivateProfileInt("SCURK", "Sound", 1, ini_file);

    // Reset file associations
    ResetFileAssociations();

    return true;
}

