// Helper to check extension support with fallback to instance-level extensions
bool VulkanDevice::IsExtensionAvailable(const char* ext) const
{
    auto foundInDevice = std::find(EnabledDeviceExtensions.begin(), EnabledDeviceExtensions.end(), ext);
    if (foundInDevice != EnabledDeviceExtensions.end()) return true;

    auto foundInInstance = std::find(Instance->EnabledExtensions.begin(), Instance->EnabledExtensions.end(), ext);
    return foundInInstance != Instance->EnabledExtensions.end();
}

// Constructor: Initialize device resources safely with exception handling
VulkanDevice::VulkanDevice(std::shared_ptr<VulkanInstance> instance, std::shared_ptr<VulkanSurface> surface, const VulkanCompatibleDevice& selectedDevice)
    : Instance(instance), Surface(surface)
{
    PhysicalDevice = selectedDevice.Device.value(); // dereference via .value() for safety
    EnabledDeviceExtensions = selectedDevice.EnabledDeviceExtensions;
    EnabledFeatures = selectedDevice.EnabledFeatures;
    GraphicsFamily = selectedDevice.GraphicsFamily;
    PresentFamily = selectedDevice.PresentFamily;
    GraphicsTimeQueries = selectedDevice.GraphicsTimeQueries;

    try {
        SetupLogicalDevice();
        SetupMemoryAllocator();
    } catch (...) {
        CleanupAllResources();
        throw;
    }
}

// Destructor: Ensure clean-up on destruction
VulkanDevice::~VulkanDevice()
{
    CleanupAllResources();
}

// Memory allocator creation using optional features based on extension support
void VulkanDevice::SetupMemoryAllocator()
{
    VmaAllocatorCreateInfo allocInfo = {};
    allocInfo.vulkanApiVersion = Instance->ApiVersion;

    // Enable dedicated allocation if both required extensions are present
    if (IsExtensionAvailable(VK_KHR_DEDICATED_ALLOCATION_EXTENSION_NAME) &&
        IsExtensionAvailable(VK_KHR_GET_MEMORY_REQUIREMENTS_2_EXTENSION_NAME)) {
        allocInfo.flags |= VMA_ALLOCATOR_CREATE_KHR_DEDICATED_ALLOCATION_BIT;
    }

    // Enable buffer device address support if available
    if (IsExtensionAvailable(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME)) {
        allocInfo.flags |= VMA_ALLOCATOR_CREATE_BUFFER_DEVICE_ADDRESS_BIT;
    }

    allocInfo.physicalDevice = PhysicalDevice.Device;
    allocInfo.device = device;
    allocInfo.instance = Instance->Instance;
    allocInfo.preferredLargeHeapBlockSize = 64_MB; // Using literal suffix or constexpr

    VkResult res = vmaCreateAllocator(&allocInfo, &allocator);
    if (res != VK_SUCCESS) {
        VulkanError("Failed to create VMA allocator");
    }
}

// Logical device setup: queue creation, feature chaining, and extension loading
void VulkanDevice::SetupLogicalDevice()
{
    const float queuePriority = 1.0f;
    std::vector<VkDeviceQueueCreateInfo> queueInfos;

    // Collect unique queue family indices needed
    std::set<int> requiredFamilies;
    if (GraphicsFamily >= 0) requiredFamilies.insert(GraphicsFamily);
    if (PresentFamily >= 0) requiredFamilies.insert(PresentFamily);

    // Build queue create info structs
    for (int idx : requiredFamilies) {
        VkDeviceQueueCreateInfo qci = {};
        qci.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO;
        qci.queueFamilyIndex = idx;
        qci.queueCount = 1u;
        qci.pQueuePriorities = &queuePriority;
        queueInfos.push_back(qci);
    }

    // Convert extension strings to C-style array
    std::vector<const char*> extNames;
    extNames.reserve(EnabledDeviceExtensions.size());
    for (const auto& ext : EnabledDeviceExtensions) {
        extNames.emplace_back(ext.c_str());
    }

    // Main device creation structure
    VkPhysicalDeviceFeatures2 devFeatures2 = { VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2 };
    devFeatures2.features = EnabledFeatures.Features;

    void* chainHead = nullptr;
    void** currentLink = &chainHead;

    // Chain features conditionally depending on API version and extensions
    if (IsExtensionAvailable(VK_KHR_GET_PHYSICAL_DEVICE_PROPERTIES_2_EXTENSION_NAME)) {
        *currentLink = &devFeatures2;
        currentLink = &devFeatures2.pNext;
    } else {
        // Fallback for Vulkan 1.0: direct pointer in main struct
        // (Note: this assumes no further chained features exist in legacy mode)
        // We'll handle only basic features here
        // For simplicity, assume no additional extensions used in legacy path
    }

    // Append extension-specific feature structs
    if (IsExtensionAvailable(VK_KHR_BUFFER_DEVICE_ADDRESS_EXTENSION_NAME)) {
        *currentLink = &EnabledFeatures.BufferDeviceAddress;
        currentLink = &EnabledFeatures.BufferDeviceAddress.pNext;
    }

    if (IsExtensionAvailable(VK_KHR_ACCELERATION_STRUCTURE_EXTENSION_NAME)) {
        *currentLink = &EnabledFeatures.AccelerationStructure;
        currentLink = &EnabledFeatures.AccelerationStructure.pNext;
    }

    if (IsExtensionAvailable(VK_KHR_RAY_QUERY_EXTENSION_NAME)) {
        *currentLink = &EnabledFeatures.RayQuery;
        currentLink = &EnabledFeatures.RayQuery.pNext;
    }

    if (IsExtensionAvailable(VK_EXT_DESCRIPTOR_INDEXING_EXTENSION_NAME)) {
        *currentLink = &EnabledFeatures.DescriptorIndexing;
        currentLink = &EnabledFeatures.DescriptorIndexing.pNext;
    }

    VkDeviceCreateInfo devCI = { VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO };
    devCI.queueCreateInfoCount = static_cast<uint32_t>(queueInfos.size());
    devCI.pQueueCreateInfos = queueInfos.data();
    devCI.enabledExtensionCount = static_cast<uint32_t>(extNames.size());
    devCI.ppEnabledExtensionNames = extNames.data();
    devCI.enabledLayerCount = 0u;
    devCI.pNext = chainHead;

    VkResult result = vkCreateDevice(PhysicalDevice.Device, &devCI, nullptr, &device);
    CheckVulkanError(result, "Failed to create Vulkan logical device");

    volkLoadDevice(device);

    // Retrieve queues after device creation
    if (GraphicsFamily >= 0) {
        vkGetDeviceQueue(device, GraphicsFamily, 0u, &GraphicsQueue);
    }
    if (PresentFamily >= 0) {
        vkGetDeviceQueue(device, PresentFamily, 0u, &PresentQueue);
    }
}

// Safe resource cleanup with idle wait and nullification
void VulkanDevice::CleanupAllResources()
{
    if (device != nullptr) {
        vkDeviceWaitIdle(device);
    }

    if (allocator != nullptr) {
        vmaDestroyAllocator(allocator);
        allocator = nullptr;
    }

    if (device != nullptr) {
        vkDestroyDevice(device, nullptr);
        device = nullptr;
    }
}

// Optional debug object naming utility
void VulkanDevice::SetObjectName(const char* name, uint64_t handle, VkObjectType type)
{
    if (!DebugLayerActive) return;

    VkDebugUtilsObjectNameInfoEXT objNameInfo = {};
    objNameInfo.sType = VK_STRUCTURE_TYPE_DEBUG_UTILS_OBJECT_NAME_INFO_EXT;
    objNameInfo.objectHandle = handle;
    objNameInfo.objectType = type;
    objNameInfo.pObjectName = name;

    VkResult res = vkSetDebugUtilsObjectNameEXT(device, &objNameInfo);
    if (res != VK_SUCCESS) {
        // Optionally log warning or ignore silently
    }
}

