// Helper: combine two vectors into one (same as concatenate_vector)
template<typename T>
inline std::vector<T> merge_vectors(const std::vector<T>& first,
                                    const std::vector<T>& second) {
    std::vector<T> combined;
    combined.reserve(first.size() + second.size());
    for (const auto& item : first) combined.push_back(item);
    for (const auto& item : second) combined.push_back(item);
    return combined;
}

// Recursive helper to convert vector to fixed-size array (alternative to index_sequence)
template<std::size_t... Is>
constexpr auto make_array_from_vec(const std::vector<int>& src,
                                   std::index_sequence<Is...>) {
    return std::array<int, sizeof...(Is)>{src[Is]...};
}

