LaunchContextBuilder::LaunchContextBuilder(CallableBase* kernel)
    : kernel_(kernel),
      owned_ctx_(std::make_unique<RuntimeContext>()),
      ctx_(owned_ctx_.get()),
      arg_buffer_(std::make_unique<char[]>(kernel->args_size)),
      result_buffer_(std::make_unique<char[]>(kernel->ret_size)),
      ret_type_(kernel->ret_type),
      arg_buffer_size(kernel->args_size),
      args_type(kernel->args_type),
      result_buffer_size(kernel->ret_size) {
  ctx_->result_buffer = reinterpret_cast<uint64*>(result_buffer_.get());
  ctx_->arg_buffer = arg_buffer_.get();
}

void LaunchContextBuilder::copy(const LaunchContextBuilder& other) {
  QD_ASSERT(kernel_ == other.kernel_);
  QD_ASSERT(array_runtime_sizes.empty());
  QD_ASSERT(device_allocation_type.empty());
  QD_ASSERT(array_ptrs.empty());

  std::memcpy(arg_buffer_.get(), other.arg_buffer_.get(), kernel_->args_size);

  array_runtime_sizes = other.array_runtime_sizes;
  device_allocation_type = other.device_allocation_type;
  array_ptrs = other.array_ptrs;
}

void LaunchContextBuilder::set_arg_float(int arg_id, float64 value) {
  auto dtype = kernel_->args_type->get_element_type(std::array{arg_id});
  QD_ASSERT_INFO(dtype->is<PrimitiveType>(),
                 "Cannot assign scalar to external array argument.");

  PrimitiveTypeID tid = dtype->as<PrimitiveType>()->type;

  if (tid == PrimitiveTypeID::f16) {
    uint16 half_val = fp16_ieee_from_fp32_value(static_cast<float32>(value));
    set_arg(arg_id, half_val);
  } else {
    bool handled = false;
#define TRY_SET_CTYPE(tp, ctype) \
    if (!handled && tid == PrimitiveTypeID::tp) { \
        set_arg(arg_id, static_cast<ctype>(value)); \
        handled = true; \
    }
#include "quadrants/inc/data_type_with_c_type.inc.h"
#undef TRY_SET_CTYPE

    if (!handled) {
        QD_NOT_IMPLEMENTED;
    }
  }
}

void LaunchContextBuilder::set_args_float(const std::vector<int>& ids,
                                          const std::vector<float64>& values) {
  QD_ASSERT(ids.size() == values.size());
  for (size_t idx = 0; idx < ids.size(); ++idx) {
    set_arg_float(ids[idx], values[idx]);
  }
}

template <typename T, std::size_t N>
void LaunchContextBuilder::set_struct_arg(const std::array<int, N>& indices,
                                          T val) {
  auto dtype = kernel_->args_type->get_element_type(indices);
  QD_ASSERT(dtype->template is<PrimitiveType>() ||
            dtype->template is<PointerType>());

  if (dtype->template is<PointerType>()) {
    set_struct_arg_impl(indices, static_cast<uint64>(val));
    return;
  }

  PrimitiveTypeID tid = dtype->template as<PrimitiveType>()->type;

  if (tid == PrimitiveTypeID::f16) {
    uint16 half_val = fp16_ieee_from_fp32_value(static_cast<float32>(val));
    set_struct_arg_impl(indices, half_val);
  } else {
    bool done = false;
#define TRY_SET(tp, ctype) \
    if (!done && tid == PrimitiveTypeID::tp) { \
        set_struct_arg_impl(indices, static_cast<ctype>(val)); \
        done = true; \
    }
#include "quadrants/inc/data_type_with_c_type.inc.h"
#undef TRY_SET

    if (!done) {
        QD_NOT_IMPLEMENTED;
    }
  }
}

// Overload for vector-based indices using dispatch via size
template <typename T>
void LaunchContextBuilder::set_struct_arg(const std::vector<int>& indices,
                                          T val) {
  switch (indices.size()) {
    case 1:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<1>{}), val);
      break;
    case 2:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<2>{}), val);
      break;
    case 3:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<3>{}), val);
      break;
    case 4:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<4>{}), val);
      break;
    case 5:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<5>{}), val);
      break;
    case 6:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<6>{}), val);
      break;
    case 7:
      set_struct_arg(make_array_from_vec(indices, std::make_index_sequence<7>{}), val);
      break;
    default:
      QD_NOT_IMPLEMENTED;
  }
}

void LaunchContextBuilder::set_ndarray_ptrs(int arg_id,
                                            uint64 data_ptr,
                                            uint64 grad_ptr) {
  set_struct_arg(std::array{arg_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY}, data_ptr);
  if (kernel_->nested_parameters[arg_id].needs_grad) {
    set_struct_arg(std::array{arg_id, TypeFactory::GRAD_PTR_POS_IN_NDARRAY}, grad_ptr);
  }
}

