void LaunchContextBuilder::set_arg_int(int arg_id, int64 val) {
  auto dtype = kernel_->args_type->get_element_type(std::array{arg_id});
  QD_ASSERT_INFO(dtype->is<PrimitiveType>(),
                 "Cannot assign scalar to external array argument.");

  if (dtype->is_primitive(PrimitiveTypeID::i8)) {
    set_arg(arg_id, static_cast<int8>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::i16)) {
    set_arg(arg_id, static_cast<int16>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::i32)) {
    set_arg(arg_id, static_cast<int32>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::i64)) {
    set_arg(arg_id, static_cast<int64>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::u1)) {
    set_arg(arg_id, static_cast<uint1>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::u8)) {
    set_arg(arg_id, static_cast<uint8>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::u16)) {
    set_arg(arg_id, static_cast<uint16>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::u32)) {
    set_arg(arg_id, static_cast<uint32>(val));
  } else if (dtype->is_primitive(PrimitiveTypeID::u64)) {
    set_arg(arg_id, static_cast<uint64>(val));
  } else {
    QD_INFO(dtype->to_string());
    QD_NOT_IMPLEMENTED;
  }
}

