template <>
void LaunchContextBuilder::set_arg<TypedConstant>(int arg_id, TypedConstant c) {
  if (is_real(c.dt)) {
    set_arg_float(arg_id, c.val_float());
  } else if (is_signed(c.dt)) {
    set_arg_int(arg_id, c.val_int());
  } else {
    set_arg_uint(arg_id, c.val_uint());
  }
}

template <typename T, std::size_t N>
void LaunchContextBuilder::set_struct_arg_impl(const std::array<int, N>& indices,
                                               T val) {
  int offset = args_type->get_element_offset(indices);
  QD_ASSERT(offset + sizeof(T) <= arg_buffer_size);
  *reinterpret_cast<T*>(ctx_->arg_buffer + offset) = val;
}

template <typename T>
T LaunchContextBuilder::get_arg(const std::vector<int>& indices) {
  return get_struct_arg<T>(indices);
}

template <typename T>
T LaunchContextBuilder::get_struct_arg(std::vector<int> indices) {
  int offset = args_type->get_element_offset(indices);
  QD_ASSERT(offset + sizeof(T) <= arg_buffer_size);
  return *reinterpret_cast<T*>(ctx_->arg_buffer + offset);
}

template <typename T>
void LaunchContextBuilder::set_arg(int arg_id, T val) {
  set_struct_arg_impl(std::array{arg_id}, val);
  set_array_device_allocation_type(arg_id, DevAllocType::kNone);
}

template <typename T>
T LaunchContextBuilder::get_ret(int idx) {
  return quadrants_union_cast_with_different_sizes<T>(ctx_->result_buffer[idx]);
}

