void LaunchContextBuilder::set_arg_external_array_with_shape(
    int arg_id,
    uintptr_t ptr,
    uint64 total_size,
    const std::vector<int64>& dims,
    uintptr_t grad_ptr) {
  QD_ASSERT_INFO(kernel_->nested_parameters[arg_id].is_array,
                 "External array cannot be assigned to scalar argument.");
  QD_ASSERT_INFO(dims.size() <= quadrants_max_num_indices,
                 "Array dimension exceeds maximum allowed indices.");

  array_ptrs[{arg_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY}] = reinterpret_cast<void*>(ptr);
  if (grad_ptr != 0) {
    array_ptrs[{arg_id, TypeFactory::GRAD_PTR_POS_IN_NDARRAY}] =
        reinterpret_cast<void*>(grad_ptr);
  }

  set_array_runtime_size(arg_id, total_size);
  for (int dim_idx = 0; dim_idx < static_cast<int>(dims.size()); ++dim_idx) {
    set_struct_arg(std::array{arg_id, 0, dim_idx}, static_cast<int32>(dims[dim_idx]));
  }
}

