void LaunchContextBuilder::set_arg_ndarray_impl(int arg_id,
                                                intptr_t dev_alloc_ptr,
                                                const std::vector<int>& shape,
                                                intptr_t grad_dev_alloc_ptr) {
  array_ptrs[{arg_id, TypeFactory::DATA_PTR_POS_IN_NDARRAY}] =
      reinterpret_cast<void*>(dev_alloc_ptr);
  if (grad_dev_alloc_ptr != 0) {
    array_ptrs[{arg_id, TypeFactory::GRAD_PTR_POS_IN_NDARRAY}] =
        reinterpret_cast<void*>(grad_dev_alloc_ptr);
  }

  set_array_device_allocation_type(arg_id, DevAllocType::kNdarray);
  QD_ASSERT(shape.size() <= quadrants_max_num_indices);

  size_t total_elem_count = 1;
  for (int dim = 0; dim < static_cast<int>(shape.size()); ++dim) {
    set_struct_arg(std::array{arg_id, 0, dim}, static_cast<int32>(shape[dim]));
    total_elem_count *= shape[dim];
  }
  set_array_runtime_size(arg_id, total_elem_count);
}

void LaunchContextBuilder::set_arg_matrix(int arg_id, const Matrix& matrix) {
  int elem_size = data_type_size(matrix.dtype());
  for (int i = 0; i < matrix.length(); ++i) {
    void* raw_data = matrix.data();
    switch (elem_size) {
      case 1: {
        int8 val = quadrants_union_cast_with_different_sizes<int8>(
            reinterpret_cast<uint8_t*>(raw_data)[i]);
        set_struct_arg_impl(std::array{arg_id, i}, val);
        break;
      }
      case 2: {
        int16 val = quadrants_union_cast_with_different_sizes<int16>(
            reinterpret_cast<uint16_t*>(raw_data)[i]);
        set_struct_arg_impl(std::array{arg_id, i}, val);
        break;
      }
      case 4: {
        int32 val = quadrants_union_cast_with_different_sizes<int32>(
            reinterpret_cast<uint32_t*>(raw_data)[i]);
        set_struct_arg_impl(std::array{arg_id, i}, val);
        break;
      }
      case 8: {
        int64 val = quadrants_union_cast_with_different_sizes<int64>(
            reinterpret_cast<uint64_t*>(raw_data)[i]);
        set_struct_arg_impl(std::array{arg_id, i}, val);
        break;
      }
      default:
        QD_ERROR("Unsupported element size: {}", elem_size);
    }
  }
}

TypedConstant LaunchContextBuilder::fetch_ret(const std::vector<int>& index) {
  const Type* dtype = ret_type_->get_element_type(index);
  int offset = ret_type_->get_element_offset(index);
  return fetch_ret_impl(offset, dtype);
}

float64 LaunchContextBuilder::get_struct_ret_float(const std::vector<int>& index) {
  return fetch_ret(index).val_float();
}

int64 LaunchContextBuilder::get_struct_ret_int(const std::vector<int>& index) {
  return fetch_ret(index).val_int();
}

uint64 LaunchContextBuilder::get_struct_ret_uint(const std::vector<int>& index) {
  return fetch_ret(index).val_uint();
}

TypedConstant LaunchContextBuilder::fetch_ret_impl(int offset, const Type* dtype) {
  QD_ASSERT(dtype->is<PrimitiveType>());
  auto prim_type = dtype->as<PrimitiveType>();
  char* buf = result_buffer_.get() + offset;

  switch (prim_type->type) {
#define CASE_TYPE(tp, ctype) \
    case PrimitiveTypeID::tp: \
      return TypedConstant(*reinterpret_cast<ctype*>(buf));

#include "quadrants/inc/data_type_with_c_type.inc.h"
#undef CASE_TYPE

    case PrimitiveTypeID::f16: {
      uint16 raw_half = *reinterpret_cast<uint16*>(buf);
      float32 f32_val = fp16_ieee_to_fp32_value(raw_half);
      return TypedConstant(f32_val);
    }

    default:
      QD_NOT_IMPLEMENTED;
  }
}

