using namespace std;

// Helper function to remove leading zeros from number string
string cleanNumber(string num) {
    if (num.empty()) return "0";

    int idx = 0;
    while (idx < num.length() && num[idx] == '0') idx++;

    return (idx == num.length()) ? "0" : num.substr(idx);
}

// Add two large numbers represented as strings
string addLargeNumbers(string first, string second) {
    if (first == "0") return second;
    if (second == "0") return first;

    // Reverse both strings for easier digit-by-digit addition
    reverse(first.begin(), first.end());
    reverse(second.begin(), second.end());

    int maxLength = max(first.size(), second.size());
    first.resize(maxLength, '0');
    second.resize(maxLength, '0');

    string result(maxLength + 1, '0');
    int carry = 0;

    for (int i = 0; i < maxLength; i++) {
        int digitSum = (first[i] - '0') + (second[i] - '0') + carry;
        result[i] = char((digitSum % 10) + '0');
        carry = digitSum / 10;
    }

    result[maxLength] = char(carry + '0');
    reverse(result.begin(), result.end());

    return cleanNumber(result);
}

// Subtract two large numbers (assumes first >= second)
string subtractLargeNumbers(string minuend, string subtrahend) {
    if (subtrahend == "0") return minuend;
    if (minuend == subtrahend) return "0";

    reverse(minuend.begin(), minuend.end());
    reverse(subtrahend.begin(), subtrahend.end());

    int length = minuend.size();
    subtrahend.resize(length, '0');

    string difference(length, '0');
    int borrow = 0;

    for (int i = 0; i < length; i++) {
        int digitDiff = (minuend[i] - '0') - (subtrahend[i] - '0') - borrow;

        if (digitDiff < 0) {
            digitDiff += 10;
            borrow = 1;
        } else {
            borrow = 0;
        }

        difference[i] = char(digitDiff + '0');
    }

    reverse(difference.begin(), difference.end());
    return cleanNumber(difference);
}

// Compare two large number strings: returns 1 if x > y, -1 if x < y, 0 if equal
int compareBigNumbers(const string& x, const string& y) {
    if (x.length() != y.length()) {
        return x.length() > y.length() ? 1 : -1;
    }
    if (x > y) return 1;
    if (x < y) return -1;
    return 0;
}

int main() {
    int itemCount;
    string capacityStr;
    cin >> itemCount >> capacityStr;
    capacityStr = cleanNumber(capacityStr);

    vector<string> weights(itemCount);
    for (int i = 0; i < itemCount; i++) {
        cin >> weights[i];
        weights[i] = cleanNumber(weights[i]);
    }

    // Create pairs of (weight, original_index)
    vector<pair<string, int>> indexedItems;
    for (int i = 0; i < itemCount; i++) {
        indexedItems.push_back({weights[i], i});
    }

    // Sort in descending order by weight
    sort(indexedItems.begin(), indexedItems.end(), 
         [](const pair<string, int>& a, const pair<string, int>& b) {
             return compareBigNumbers(a.first, b.first) > 0;
         });

    vector<int> selected(itemCount, 0);
    string totalWeight = "0";

    // Greedy selection: take items while not exceeding capacity
    for (auto& item : indexedItems) {
        string newTotal = addLargeNumbers(totalWeight, item.first);
        if (compareBigNumbers(newTotal, capacityStr) <= 0) {
            totalWeight = newTotal;
            selected[item.second] = 1;
        }
    }

    // Calculate remaining capacity
    string remainingCapacity = subtractLargeNumbers(capacityStr, totalWeight);

    // Try to improve by adding smallest unused item if it helps
    if (compareBigNumbers(remainingCapacity, "0") > 0) {
        string smallestUnused = "";
        int bestIndex = -1;

        // Find smallest unused positive-weight item
        for (int i = 0; i < itemCount; i++) {
            if (selected[i] == 0 && compareBigNumbers(weights[i], "0") > 0) {
                if (bestIndex == -1 || compareBigNumbers(weights[i], smallestUnused) < 0) {
                    smallestUnused = weights[i];
                    bestIndex = i;
                }
            }
        }

        // If found, check if adding it improves the solution
        if (bestIndex != -1) {
            string tentativeTotal = addLargeNumbers(totalWeight, smallestUnused);
            string excess = subtractLargeNumbers(tentativeTotal, capacityStr);

            if (compareBigNumbers(excess, remainingCapacity) < 0) {
                selected[bestIndex] = 1;
            }
        }
    }

    // Output selection result
    for (int i = 0; i < itemCount; i++) {
        if (i > 0) cout << " ";
        cout << selected[i];
    }
    cout << endl;

    return 0;
}

#if TS_MODEL == TS_MODEL_FT6X36
    #include "FT6X36.h"

FT6X36* FT6X36::_instance = nullptr;

FT6X36::FT6X36(TwoWire* bus, int8_t irqPin) {
    _instance = this;
    _wire = bus;
    _intPin = irqPin;
}

FT6X36::~FT6X36() {
    detachInterrupt(digitalPinToInterrupt(_intPin));
}

void ISR_ATTR FT6X36::isr() {
    if (_instance != nullptr) {
        _instance->onInterrupt();
    }
}

bool FT6X36::begin(uint8_t sensitivity) {
    // Verify vendor ID
    if (readRegister8(FT6X36_REG_PANEL_ID) != FT6X36_VENDID) {
        return false;
    }

    uint8_t chipId = readRegister8(FT6X36_REG_CHIPID);
    bool supported = (chipId == FT6206_CHIPID ||
                      chipId == FT6236_CHIPID ||
                      chipId == FT6336_CHIPID);
    if (!supported) {
        return false;
    }

    pinMode(_intPin, INPUT_PULLUP);
    attachInterrupt(digitalPinToInterrupt(_intPin), FT6X36::isr, FALLING);

    writeRegister8(FT6X36_REG_DEVICE_MODE, 0x00);         // Normal operation
    writeRegister8(FT6X36_REG_THRESHHOLD, sensitivity);   // Set touch threshold
    writeRegister8(FT6X36_REG_TOUCHRATE_ACTIVE, 0x0E);    // Active mode polling rate

    return true;
}

void FT6X36::registerIsrHandler(void (*handler)()) {
    _isrHandler = handler;
}

void FT6X36::registerTouchHandler(void (*handler)(TPoint, TEvent)) {
    _touchHandler = handler;
}

uint8_t FT6X36::touched() {
    uint8_t count = readRegister8(FT6X36_REG_NUM_TOUCHES);
    return (count > 2) ? 0 : count;
}

void FT6X36::loop() {
    if (_irqPending) {
        _irqPending = false;
        handleTouchEvents();
    }
}

void FT6X36::handleTouchEvents() {
    fetchTouchData();

    uint8_t touchCount = 0;
    TRawEvent evt = static_cast<TRawEvent>(_touchEvent[touchCount]);
    TPoint pos{_touchX[touchCount], _touchY[touchCount]};

    if (evt == TRawEvent::PressDown) {
        _points[0] = pos;
        _pointIdx = 1;
        _dragMode = false;
        _touchStartTime = millis();
        triggerEvent(pos, TEvent::TouchStart);
    } 
    else if (evt == TRawEvent::Contact) {
        if (_pointIdx < 10) {
            _points[_pointIdx] = pos;
            ++_pointIdx;
        }

        bool nearOriginal = _points[0].aboutEqual(pos);
        bool heldLongEnough = (millis() - _touchStartTime) > 300;

        if (!_dragMode && nearOriginal && heldLongEnough) {
            _dragMode = true;
            triggerEvent(pos, TEvent::DragStart);
        }

        if (_dragMode) {
            triggerEvent(pos, TEvent::DragMove);
        }
        triggerEvent(pos, TEvent::TouchMove);
    } 
    else if (evt == TRawEvent::LiftUp) {
        _points[9] = pos;
        _touchEndTime = millis();
        triggerEvent(pos, TEvent::TouchEnd);

        if (_dragMode) {
            triggerEvent(pos, TEvent::DragEnd);
            _dragMode = false;
        }

        bool tapDetected = _points[0].aboutEqual(pos) &&
                           ((_touchEndTime - _touchStartTime) <= 300);
        if (tapDetected) {
            triggerEvent(pos, TEvent::Tap);
            _points[0] = {0, 0};
            _touchStartTime = 0;
        }
    }
}

void FT6X36::onInterrupt() {
    _irqPending = true;
    if (_isrHandler) {
        _isrHandler();
    }
}

void FT6X36::fetchTouchData() {
    constexpr uint8_t bufferSize = 16;
    uint8_t buffer[bufferSize];

    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(0x00);
    _wire->endTransmission();

    _wire->requestFrom(static_cast<uint8_t>(FT6X36_ADDR), bufferSize);
    for (uint8_t idx = 0; idx < bufferSize; ++idx) {
        buffer[idx] = Wire.read();
    }

#ifdef FT6X36_DEBUG
    Serial.println("REGISTER DUMP:");
    for (int i = 0; i < bufferSize; ++i) {
        Serial.print("0x");
        Serial.print(i, HEX);
        Serial.print(": 0x");
        Serial.println(buffer[i], HEX);
    }
    Serial.println();
    Serial.print("TOUCH COUNT: ");
    Serial.println(buffer[FT6X36_REG_NUM_TOUCHES]);
    Serial.print("GESTURE ID: ");
    Serial.println(buffer[FT6X36_REG_GESTURE_ID]);
#endif

    _touches = buffer[FT6X36_REG_NUM_TOUCHES];

    const uint8_t stride = 6;
    for (uint8_t finger = 0; finger < 2; ++finger) {
        uint8_t base = FT6X36_REG_P1_XH + finger * stride;

        // X coordinate
        _touchX[finger] = buffer[base] & 0x0F;
        _touchX[finger] <<= 8;
        _touchX[finger] |= buffer[base + 1];

        // Y coordinate
        _touchY[finger] = buffer[base + 2] & 0x0F;
        _touchY[finger] <<= 8;
        _touchY[finger] |= buffer[base + 3];

        // Event type (top 2 bits)
        _touchEvent[finger] = buffer[base] >> 6;
    }
}

void FT6X36::writeRegister8(uint8_t regAddr, uint8_t value) {
    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(regAddr);
    _wire->write(value);
    _wire->endTransmission();
}

uint8_t FT6X36::readRegister8(uint8_t regAddr) {
    _wire->beginTransmission(FT6X36_ADDR);
    _wire->write(regAddr);
    _wire->endTransmission();

    _wire->requestFrom(static_cast<uint8_t>(FT6X36_ADDR), 1);
    uint8_t result = _wire->read();

#ifdef I2C_DEBUG
    Serial.print("REG 0x");
    Serial.print(regAddr, HEX);
    Serial.print(": 0x");
    Serial.println(result, HEX);
#endif

    return result;
}

void FT6X36::triggerEvent(TPoint location, TEvent eventType) {
    if (_touchHandler) {
        _touchHandler(location, eventType);
    }
}

