#include "test/jemalloc_test.h"
#include "jemalloc/internal/ph.h"

typedef struct heap_node_s heap_node_t;

// Define heap structure using alternative naming
struct heap_node_s {
    #define NODE_SIGNATURE 0x9823af7e
    uint32_t signature;
    heap_link_t link_field;
    uint64_t priority_value;
};

// Custom comparison function with signature verification
static int
compare_heap_nodes(const heap_node_t *first, const heap_node_t *second) {
    int result = (first->priority_value > second->priority_value) - 
                 (first->priority_value < second->priority_value);

    if (result == 0) {
        // Enforce deterministic ordering for equal keys
        uintptr_t addr1 = (uintptr_t)first;
        uintptr_t addr2 = (uintptr_t)second;
        result = (addr1 > addr2) - (addr1 < addr2);
    }
    return result;
}

// Wrapper that validates node signatures before comparison
static int
safe_compare_nodes(const heap_node_t *a, const heap_node_t *b) {
    expect_u32_eq(a->signature, NODE_SIGNATURE, "Invalid node signature");
    expect_u32_eq(b->signature, NODE_SIGNATURE, "Invalid node signature");
    return compare_heap_nodes(a, b);
}

// Explicitly define heap operations instead of using ph_gen
ph_structs(heap_data, heap_node_t);
ph_proto(static, heap_extract_min, heap_data, heap_node_t, link_field, safe_compare_nodes);

// Helper functions for tree navigation
static heap_node_t *
get_child_node(const heap_node_t *node) {
    return phn_lchild_get((heap_node_t *)node, offsetof(heap_node_t, link_field));
}

static heap_node_t *
get_next_sibling(const heap_node_t *node) {
    return phn_next_get((heap_node_t *)node, offsetof(heap_node_t, link_field));
}

static heap_node_t *
get_prev_sibling(const heap_node_t *node) {
    return phn_prev_get((heap_node_t *)node, offsetof(heap_node_t, link_field));
}

// Recursive tree printing function
static void
display_heap_structure(const heap_node_t *node, unsigned level) {
    for (unsigned i = 0; i < level; ++i) {
        malloc_printf("\t");
    }
    malloc_printf("%2"FMTu64"\n", node->priority_value);

    heap_node_t *first_child = get_child_node(node);
    if (first_child == NULL) {
        return;
    }

    display_heap_structure(first_child, level + 1);

    for (heap_node_t *sibling = get_next_sibling(first_child); 
         sibling != NULL; 
         sibling = get_next_sibling(sibling)) {
        display_heap_structure(sibling, level + 1);
    }
}

// Display entire heap state
static void
show_heap_state(const heap_data_t *heap) {
    heap_node_t *auxiliary;
    malloc_printf("=== heap %p ===\n", heap);

    if (heap->ph.root == NULL) {
        goto cleanup;
    }

    display_heap_structure(heap->ph.root, 0);

    for (auxiliary = get_next_sibling(heap->ph.root); 
         auxiliary != NULL; 
         auxiliary = get_next_sibling(auxiliary)) {
        expect_ptr_eq(get_next_sibling(get_prev_sibling(auxiliary)), auxiliary,
            "Link integrity violation in aux list");
        display_heap_structure(auxiliary, 0);
    }

cleanup:
    malloc_printf("=================\n");
}

// Validate heap properties recursively
static unsigned
verify_heap_properties(const heap_node_t *node, const heap_node_t *parent) {
    unsigned count = 1;
    heap_node_t *child, *sibling;

    if (parent != NULL) {
        expect_d_ge(safe_compare_nodes(node, parent), 0,
            "Heap property violated: child < parent");
    }

    child = get_child_node(node);
    if (child == NULL) {
        return count;
    }

    expect_ptr_eq(get_prev_sibling(child), (void*)node,
        "Child-parent link mismatch");

    count += verify_heap_properties(child, node);

    for (sibling = get_next_sibling(child); sibling != NULL; 
         sibling = get_next_sibling(sibling)) {
        expect_ptr_eq(get_next_sibling(get_prev_sibling(sibling)), sibling,
            "Sibling link corruption detected");
        count += verify_heap_properties(sibling, node);
    }

    return count;
}

// Full heap validation routine
static unsigned
validate_complete_heap(const heap_data_t *heap) {
    unsigned total_nodes = 0;
    heap_node_t *auxiliary;

    if (heap->ph.root == NULL) {
        goto done;
    }

    total_nodes += verify_heap_properties(heap->ph.root, NULL);

    for (auxiliary = get_next_sibling(heap->ph.root); 
         auxiliary != NULL; 
         auxiliary = get_next_sibling(auxiliary)) {
        expect_ptr_eq(get_next_sibling(get_prev_sibling(auxiliary)), auxiliary,
            "Auxiliary list link error");
        total_nodes += verify_heap_properties(auxiliary, NULL);
    }

done:
    if (false) {
        show_heap_state(heap);
    }
    return total_nodes;
}

TEST_BEGIN(test_empty_heap) {
    heap_data_t heap;
    heap_new(&heap);

    expect_true(heap_empty(&heap), "New heap should be empty");
    expect_ptr_null(heap_first(&heap), "First element should be null");
    expect_ptr_null(heap_any(&heap), "Any element should be null");
}
TEST_END

// Remove specific node from heap
static void
remove_specific_node(heap_data_t *heap, heap_node_t *node) {
    heap_remove(heap, node);
    node->signature = 0;
}

// Extract minimum node
static heap_node_t *
extract_minimum(heap_data_t *heap) {
    heap_node_t *node = heap_remove_first(heap);
    node->signature = 0;
    return node;
}

// Extract arbitrary node
static heap_node_t *
extract_arbitrary(heap_data_t *heap) {
    heap_node_t *node = heap_remove_any(heap);
    node->signature = 0;
    return node;
}

TEST_BEGIN(test_random_operations) {
#define ELEMENT_COUNT 25
#define TEST_ITERATIONS 250
#define RANDOM_SEED 42

    sfmt_t *random_generator;
    uint64_t test_values[ELEMENT_COUNT];
    heap_data_t heap;
    heap_node_t nodes[ELEMENT_COUNT];
    unsigned i, j, k;

    random_generator = init_gen_rand(RANDOM_SEED);

    for (i = 0; i < TEST_ITERATIONS; i++) {
        switch (i) {
            case 0:
                // Sequential insertion
                for (j = 0; j < ELEMENT_COUNT; j++) {
                    test_values[j] = j;
                }
                break;

            case 1:
                // Reverse sequential insertion
                for (j = 0; j < ELEMENT_COUNT; j++) {
                    test_values[j] = ELEMENT_COUNT - j - 1;
                }
                break;

            default:
                // Random values
                for (j = 0; j < ELEMENT_COUNT; j++) {
                    test_values[j] = gen_rand64_range(random_generator, ELEMENT_COUNT);
                }
                break;
        }

        for (j = 1; j <= ELEMENT_COUNT; j++) {
            // Initialize heap and nodes
            heap_new(&heap);
            expect_u_eq(validate_complete_heap(&heap), 0, "Initial node count incorrect");

            for (k = 0; k < j; k++) {
                nodes[k].signature = NODE_SIGNATURE;
                nodes[k].priority_value = test_values[k];
            }

            // Insert nodes into heap
            for (k = 0; k < j; k++) {
                heap_insert(&heap, &nodes[k]);

                // Periodically trigger internal operations
                if (i % 13 == 12) {
                    expect_ptr_not_null(heap_any(&heap), "Heap should have elements");
                    expect_ptr_not_null(heap_first(&heap), "Heap should have elements");
                }

                expect_u_eq(validate_complete_heap(&heap), k + 1, "Node count mismatch after insert");
            }

            expect_false(heap_empty(&heap), "Heap should contain elements");

            // Test various removal strategies
            switch (i % 6) {
                case 0:
                    // Remove in insertion order
                    for (k = 0; k < j; k++) {
                        expect_u_eq(validate_complete_heap(&heap), j - k, "Count before removal");
                        remove_specific_node(&heap, &nodes[k]);
                        expect_u_eq(validate_complete_heap(&heap), j - k - 1, "Count after removal");
                    }
                    break;

                case 1:
                    // Remove in reverse insertion order
                    for (k = j; k > 0; k--) {
                        remove_specific_node(&heap, &nodes[k-1]);
                        expect_u_eq(validate_complete_heap(&heap), k - 1, "Count after removal");
                    }
                    break;

                case 2: {
                    heap_node_t *previous = NULL;
                    for (k = 0; k < j; k++) {
                        heap_node_t *current = extract_minimum(&heap);
                        expect_u_eq(validate_complete_heap(&heap), j - k - 1, "Count after extraction");

                        if (previous != NULL) {
                            expect_d_ge(safe_compare_nodes(current, previous), 0,
                                "Extraction order violation");
                        }
                        previous = current;
                    }
                    break;
                }

                case 3: {
                    heap_node_t *previous = NULL;
                    for (k = 0; k < j; k++) {
                        heap_node_t *current = heap_first(&heap);
                        expect_u_eq(validate_complete_heap(&heap), j - k, "Count before removal");

                        if (previous != NULL) {
                            expect_d_ge(safe_compare_nodes(current, previous), 0,
                                "Removal order violation");
                        }
                        remove_specific_node(&heap, current);
                        expect_u_eq(validate_complete_heap(&heap), j - k - 1, "Count after removal");
                        previous = current;
                    }
                    break;
                }

                case 4: {
                    for (k = 0; k < j; k++) {
                        extract_arbitrary(&heap);
                        expect_u_eq(validate_complete_heap(&heap), j - k - 1, "Count after extraction");
                    }
                    break;
                }

                case 5: {
                    for (k = 0; k < j; k++) {
                        heap_node_t *current = heap_any(&heap);
                        expect_u_eq(validate_complete_heap(&heap), j - k, "Count before removal");
                        remove_specific_node(&heap, current);
                        expect_u_eq(validate_complete_heap(&heap), j - k - 1, "Count after removal");
                    }
                    break;
                }

                default:
                    not_reached();
            }

            expect_ptr_null(heap_first(&heap), "Heap should be empty");
            expect_ptr_null(heap_any(&heap), "Heap should be empty");
            expect_true(heap_empty(&heap), "Heap should be empty");
        }
    }

    fini_gen_rand(random_generator);
#undef ELEMENT_COUNT
#undef TEST_ITERATIONS
#undef RANDOM_SEED
}
TEST_END

int
main(void) {
    return test(
        test_empty_heap,
        test_random_operations
    );
}

