DEFINE_bool(enable_metrics, false, "Enable metrics");
DEFINE_string(metrics_port, "18081", "Metrics port");

bool DataSubstrate::InitializeMetrics(const INIReader &config_reader)
{
    // Parse metrics configuration from INI file
    bool metrics_enabled = config_reader.GetBoolean("metrics", "enable_metrics", false);
    DLOG(INFO) << "Metrics system: " << (metrics_enabled ? "enabled" : "disabled");

    if (!metrics_enabled)
        return true;

    // Override default port using config value
    int port_from_config = config_reader.GetInteger("metrics", "metrics_port", std::stoi(FLAGS_metrics_port));
    FLAGS_metrics_port = std::to_string(port_from_config);
    LOG(INFO) << "Metrics listening on port: " << FLAGS_metrics_port;

    // Set environment variable for external access
    setenv("ELOQ_METRICS_PORT", FLAGS_metrics_port.c_str(), false);

    // Memory usage tracking
    metrics::enable_memory_usage = config_reader.GetBoolean("metrics", "enable_memory_usage", true);
    LOG(INFO) << "Memory usage monitoring: " << (metrics::enable_memory_usage ? "active" : "inactive");
    if (metrics::enable_memory_usage)
    {
        metrics::collect_memory_usage_round = config_reader.GetInteger("metrics", "collect_memory_usage_round", 10000);
        LOG(INFO) << "Memory stats collected every " << metrics::collect_memory_usage_round << " rounds";
    }

    // Cache hit rate monitoring
    metrics::enable_cache_hit_rate = config_reader.GetBoolean("metrics", "enable_cache_hit_rate", true);
    LOG(INFO) << "Cache hit rate tracking: " << (metrics::enable_cache_hit_rate ? "ON" : "OFF");

    // Transaction metrics
    metrics::enable_tx_metrics = config_reader.GetBoolean("metrics", "enable_tx_metrics", true);
    LOG(INFO) << "Transaction metrics: " << (metrics::enable_tx_metrics ? "enabled" : "disabled");
    if (metrics::enable_tx_metrics)
    {
        metrics::collect_tx_duration_round = config_reader.GetInteger("metrics", "collect_tx_duration_round", 100);
        LOG(INFO) << "Tx duration sampled every " << metrics::collect_tx_duration_round << " rounds";
    }

    // Busy round detection
    metrics::enable_busy_round_metrics = config_reader.GetBoolean("metrics", "enable_busy_round_metrics", true);
    LOG(INFO) << "Busy round detection: " << (metrics::enable_busy_round_metrics ? "enabled" : "disabled");
    if (metrics::enable_busy_round_metrics)
    {
        metrics::busy_round_threshold = config_reader.GetInteger("metrics", "busy_round_threshold", 10);
        LOG(INFO) << "Threshold for busy round logging set to " << metrics::busy_round_threshold;
    }

    // Remote request metrics (defaults to tx metrics flag if not specified)
    metrics::enable_remote_request_metrics = config_reader.GetBoolean(
        "metrics", "enable_remote_request_metrics", metrics::enable_tx_metrics);
    LOG(INFO) << "Remote request metrics: " << (metrics::enable_remote_request_metrics ? "ON" : "OFF");

    // Store-specific metrics
    if (core_config_.enable_data_store)
    {
        metrics::enable_kv_metrics = config_reader.GetBoolean("metrics", "enable_kv_metrics", true);
        LOG(INFO) << "KV store metrics: " << (metrics::enable_kv_metrics ? "enabled" : "disabled");

        metrics::enable_eloqstore_metrics = config_reader.GetBoolean("metrics", "enable_eloqstore_metrics", true);
        LOG(INFO) << "EloqStore metrics: " << (metrics::enable_eloqstore_metrics ? "enabled" : "disabled");
    }

#if (WITH_LOG_SERVICE)
    if (core_config_.enable_wal)
    {
        metrics::enable_log_service_metrics = config_reader.GetBoolean("metrics", "enable_log_service_metrics", true);
        LOG(INFO) << "Log service metrics: " << (metrics::enable_log_service_metrics ? "ON" : "OFF");
    }
#endif

    // Standby/failure forwarding metrics
    metrics::enable_standby_metrics = config_reader.GetBoolean("metrics", "enable_standby_metrics", true);
    LOG(INFO) << "Standby failure metrics: " << (metrics::enable_standby_metrics ? "enabled" : "disabled");
    if (metrics::enable_standby_metrics)
    {
        metrics::collect_standby_metrics_round = config_reader.GetInteger("metrics", "collect_standby_metrics_round", 10000);
        LOG(INFO) << "Standby metrics gathered every " << metrics::collect_standby_metrics_round << " rounds";
    }

#ifdef ELOQ_MODULE_ELOQSQL
    metrics::enable_mysql_tx_metrics = config_reader.GetBoolean("metrics", "enable_mysql_tx_metrics", true);
    metrics::enable_mysql_dml_metrics = config_reader.GetBoolean("metrics", "enable_mysql_dml_metrics", true);
#endif

    // Initialize metrics registry
    eloq_metrics_app::MetricsRegistryImpl::MetricsRegistryResult reg_result =
        eloq_metrics_app::MetricsRegistryImpl::GetRegistry();
    if (reg_result.not_ok_ != nullptr)
    {
        LOG(ERROR) << "!!! Metrics registry initialization failed !!!";
        return false;
    }
    metrics_registry_ = reg_result.metrics_registry_;

#ifdef ELOQ_MODULE_ELOQSQL
    metrics::CommonLabels mysql_labels{};
    mysql_labels["node_ip"]   = network_config_.local_ip;
    mysql_labels["node_port"] = std::to_string(network_config_.local_port);
    metrics::register_mysql_metrics(metrics_registry_.get(), mysql_labels);
#endif

#ifdef ELOQ_MODULE_ELOQKV
    metrics::CommonLabels redis_labels{};
    redis_labels["node_ip"]   = network_config_.local_ip;
    redis_labels["node_port"] = std::to_string(network_config_.local_port);
    redis_labels["node_id"]   = std::to_string(network_config_.node_id);
    metrics::register_redis_metrics(metrics_registry_.get(), redis_labels, core_config_.core_num);
    metrics::redis_meter->Collect(metrics::NAME_MAX_CONNECTION, core_config_.maxclients);
#endif

    // Common labels for transaction service
    tx_service_common_labels_["node_ip"]   = network_config_.local_ip;
    tx_service_common_labels_["node_port"] = std::to_string(network_config_.local_port);
    tx_service_common_labels_["node_id"]   = std::to_string(network_config_.node_id);

    return true;
}

bool DataSubstrate::RegisterKvStoreMetrics()
{
    // Skip registration if metrics are disabled or registry unavailable
    if (!metrics::enable_metrics || !metrics_registry_)
        return true;

    // Register KV store metrics only if data store is active and handler exists
    if (core_config_.enable_data_store && store_hd_)
    {
        metrics::CommonLabels kv_labels{};
        kv_labels["node_ip"]   = network_config_.local_ip;
        kv_labels["node_port"] = std::to_string(network_config_.local_port);
        store_hd_->RegisterKvMetrics(metrics_registry_.get(), kv_labels);
    }

    return true;
}

#include <ankerl/unordered_dense.h>
#include <fuzz/provider.h>
#include <fuzz/run.h>
#include <app/doctest.h>
#include <unordered_map>
#include <deque>

namespace {
// Perform fuzzing tests comparing ankerl::unordered_dense maps with std::unordered_map for string keys/values
template <typename DenseMap>
void test_string_operations(fuzz::provider p) {
    DenseMap dense_map;
    std::unordered_map<std::string, std::string> standard_map;

    while (p.has_remaining_bytes()) {
        // Test try_emplace with "hello!" value
        auto key1 = p.string(32);
        auto dense_result = dense_map.try_emplace(key1, "hello!");
        auto standard_result = standard_map.try_emplace(key1, "hello!");
        REQUIRE(dense_result.second == standard_result.second);

        // Test find operation
        auto key2 = p.string(32);
        auto dense_it = dense_map.find(key2);
        auto standard_it = standard_map.find(key2);
        REQUIRE((dense_it == dense_map.end()) == (standard_it == standard_map.end()));

        // If found, erase the element from both maps
        if (dense_it != dense_map.end()) {
            dense_map.erase(dense_it);
            standard_map.erase(standard_it);
        }

        // Verify size consistency after operations
        REQUIRE(dense_map.size() == standard_map.size());

        // Test another try_emplace with "huh" value
        auto key3 = p.string(32);
        REQUIRE(dense_map.try_emplace(key3, "huh").second == standard_map.try_emplace(key3, "huh").second);

        // Test erase by key
        auto key4 = p.string(32);
        REQUIRE(dense_map.erase(key4) == standard_map.erase(key4));
    }

    // Final verification: convert dense map to std::unordered_map and compare contents
    REQUIRE(std::unordered_map<std::string, std::string>(dense_map.begin(), dense_map.end()) == standard_map);
}
} // namespace

TEST_CASE("fuzz_string" * doctest::test_suite("fuzz")) {
    fuzz::run([](fuzz::provider p) {
        // Test different map implementations
        test_string_operations<ankerl::unordered_dense::map<std::string, std::string>>(p.copy());
        test_string_operations<ankerl::unordered_dense::segmented_map<std::string, std::string>>(p.copy());
        test_string_operations<
            ankerl::unordered_dense::map<
                std::string,
                std::string,
                ankerl::unordered_dense::hash<std::string>,
                std::equal_to<std::string>,
                std::deque<std::pair<std::string, std::string>>
            >
        >(p.copy());
    });
}

#include "kbm_config_dialog.h"
#include "kbm_help_dialog.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include "common/config.h"
#include "common/path_util.h"
#include "game_info.h"
#include <QCheckBox>
#include <QCloseEvent>
#include <QComboBox>
#include <QFile>
#include <QHBoxLayout>
#include <QMessageBox>
#include <QPushButton>
#include <QTextStream>
#include <QVBoxLayout>

QString lastSelectedGame = "default";
bool helpWindowActive = false;
HelpDialog* helpWinRef = nullptr;

EditorDialog::EditorDialog(QWidget* parent)
    : QDialog(parent), originalContent(""), editor(nullptr), gameComboBox(nullptr) {
    setWindowTitle(tr("Modify Keyboard + Mouse & Controller Bindings"));
    resize(600, 400);

    // Setup text editor
    editor = new QPlainTextEdit(this);
    QFont editFont;
    editFont.setPointSize(10);
    editor->setFont(editFont);

    // Game selector setup
    gameComboBox = new QComboBox(this);
    gameComboBox->addItem("default");
    populateAvailableGames();

    // Unified input toggle
    QCheckBox* unifiedToggle = new QCheckBox(tr("Enable Per-Game Configurations"), this);
    unifiedToggle->setChecked(Config::GetUseUnifiedInputConfig() == false);
    connect(unifiedToggle, &QCheckBox::toggled, [this](bool enabled) {
        Config::SetUseUnifiedInputConfig(!enabled);
        Common::FS::Path userConfigPath = Common::FS::GetUserPath(Common::FS::PathType::UserDir);
        Config::save(userConfigPath / "config.toml");
    });

    // Button creation
    QPushButton* confirmBtn = new QPushButton("Save", this);
    QPushButton* discardBtn = new QPushButton("Cancel", this);
    QPushButton* infoBtn = new QPushButton("Help", this);
    QPushButton* resetBtn = new QPushButton("Restore Defaults", this);

    // Top layout: checkbox, combobox, buttons
    QHBoxLayout* headerLayout = new QHBoxLayout();
    headerLayout->addWidget(unifiedToggle);
    headerLayout->addWidget(gameComboBox);
    headerLayout->addStretch();
    headerLayout->addWidget(confirmBtn);
    headerLayout->addWidget(discardBtn);
    headerLayout->addWidget(resetBtn);
    headerLayout->addWidget(infoBtn);

    // Main layout
    QVBoxLayout* mainLayout = new QVBoxLayout(this);
    mainLayout->addLayout(headerLayout);
    mainLayout->addWidget(editor);

    // Load initial config
    refreshEditorContent(gameComboBox->currentText());

    // Signal connections
    connect(confirmBtn, &QPushButton::clicked, this, &EditorDialog::handleSaveRequest);
    connect(discardBtn, &QPushButton::clicked, this, &EditorDialog::handleCancelRequest);
    connect(infoBtn, &QPushButton::clicked, this, &EditorDialog::handleHelpRequest);
    connect(resetBtn, &QPushButton::clicked, this, &EditorDialog::handleResetRequest);
    connect(gameComboBox, &QComboBox::currentTextChanged,
            this, &EditorDialog::onGameSwitched);
}

// Helper to read file content into editor
void EditorDialog::readConfigIntoEditor(const QString& gameName) {
    std::string filePath = Config::GetFoolproofInputConfigFile(gameName.toStdString());
    QFile srcFile(QString::fromStdString(filePath));
    if (srcFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
        QTextStream reader(&srcFile);
        editor->setPlainText(reader.readAll());
        originalContent = editor->toPlainText();
        srcFile.close();
    } else {
        QMessageBox::warning(this, tr("Error"), tr("Failed to open configuration file for reading"));
    }
}

// Helper to write current editor content to file
void EditorDialog::writeEditorToFile(const QString& gameName) {
    std::string filePath = Config::GetFoolproofInputConfigFile(gameName.toStdString());
    QFile dstFile(QString::fromStdString(filePath));
    if (dstFile.open(QIODevice::WriteOnly | QIODevice::Text)) {
        QTextStream writer(&dstFile);
        writer << editor->toPlainText();
        dstFile.close();
    } else {
        QMessageBox::warning(this, tr("Error"), tr("Failed to open configuration file for writing"));
    }
}

// Override close event with conditional save prompt
void EditorDialog::closeEvent(QCloseEvent* event) {
    if (helpWindowActive) {
        helpWinRef->close();
        helpWindowActive = false;
    }

    if (hasPendingModifications()) {
        QMessageBox::StandardButton choice = QMessageBox::question(
            this, tr("Unsaved Changes"), tr("Would you like to save before closing?"),
            QMessageBox::Yes | QMessageBox::No | QMessageBox::Cancel);

        if (choice == QMessageBox::Yes) {
            writeEditorToFile(gameComboBox->currentText());
            event->accept();
        } else if (choice == QMessageBox::No) {
            event->accept();
        } else {
            event->ignore();
        }
    } else {
        event->accept();
    }
}

// Handle Escape key press
void EditorDialog::keyPressEvent(QKeyEvent* event) {
    if (event->key() == Qt::Key_Escape) {
        if (helpWindowActive) {
            helpWinRef->close();
            helpWindowActive = false;
        }
        reject(); // Equivalent to clicking Cancel/Close
    } else {
        QDialog::keyPressEvent(event);
    }
}

// Save button handler
void EditorDialog::handleSaveRequest() {
    if (helpWindowActive) {
        helpWinRef->close();
        helpWindowActive = false;
    }
    writeEditorToFile(gameComboBox->currentText());
    accept();
}

// Cancel button handler
void EditorDialog::handleCancelRequest() {
    if (helpWindowActive) {
        helpWinRef->close();
        helpWindowActive = false;
    }
    reject();
}

// Help dialog management
void EditorDialog::handleHelpRequest() {
    if (!helpWindowActive) {
        helpWinRef = new HelpDialog(&helpWindowActive, this);
        helpWinRef->setWindowTitle(tr("Help"));
        helpWinRef->setAttribute(Qt::WA_DeleteOnClose);

        QRect ownerRect = geometry();
        int x = ownerRect.x() + ownerRect.width() + 12;
        int y = ownerRect.y();
        helpWinRef->move(x, y);
        helpWinRef->show();
        helpWindowActive = true;
    } else {
        helpWinRef->close();
        helpWindowActive = false;
    }
}

// Reset to default handler
void EditorDialog::handleResetRequest() {
    bool isDefaultSelection = (gameComboBox->currentText() == "default");
    QString message = isDefaultSelection
        ? tr("Restore the default config to factory settings?")
        : tr("Overwrite current config with your saved default?");

    QMessageBox::StandardButton answer = QMessageBox::question(
        this, tr("Confirm Reset"), message,
        QMessageBox::Yes | QMessageBox::No);

    if (answer == QMessageBox::Yes) {
        if (isDefaultSelection) {
            std::string defPath = Config::GetFoolproofInputConfigFile("default");
            std::filesystem::remove(defPath);
        }

        std::string defaultPath = Config::GetFoolproofInputConfigFile("default");
        QFile srcFile(QString::fromStdString(defaultPath));
        if (srcFile.open(QIODevice::ReadOnly | QIODevice::Text)) {
            QTextStream in(&srcFile);
            editor->setPlainText(in.readAll());
            srcFile.close();
        } else {
            QMessageBox::warning(this, tr("Error"), tr("Could not load default config"));
        }
    }
}

// Check for unsaved changes
bool EditorDialog::hasPendingModifications() const {
    return editor->toPlainText() != originalContent;
}

// Populate list of installed games
void EditorDialog::populateAvailableGames() {
    lastSelectedGame = "default";
    for (const auto& installLoc : Config::getGameInstallDirs()) {
        QString installDir;
        Common::FS::PathToQString(installDir, installLoc);
        QDir dir(installDir);
        QFileInfoList entries = dir.entryInfoList(QDir::Dirs | QDir::NoDotAndDotDot);

        for (const QFileInfo& item : entries) {
            if (item.isDir()) {
                QString name = item.fileName();
                if (!name.endsWith("-UPDATE") && !name.endsWith("-patch")) {
                    gameComboBox->addItem(name);
                }
            }
        }
    }
}

// Switch between game configs
void EditorDialog::onGameSwitched(const QString& selectedGame) {
    writeEditorToFile(lastSelectedGame);
    refreshEditorContent(selectedGame);
    lastSelectedGame = selectedGame;
}

#include <iostream>
#include <random>
#include <any>
#include <string>
#include <vector>
#include <optional>
#include <stdexcept>
#include <cmath>

namespace MayaFlux::Kinesis::Stochastic {

class Stochastic {
public:
    enum class Algorithm {
        UNIFORM,
        NORMAL,
        EXPONENTIAL,
        POISSON,
        PERLIN,
        GENDY,
        BROWNIAN,
        PINK,
        BLUE
    };

    Stochastic(Algorithm algo);
    void seed(uint64_t seed);
    void set_algorithm(Algorithm algo);
    void configure(const std::string& key, std::any value);
    std::optional<std::any> retrieve_config(const std::string& key) const;
    double operator()(double min, double max);
    double at(double x, double y, double z = 0.0);
    std::vector<double> sample_batch(double min, double max, size_t count);

private:
    uint64_t xorshift64star();
    double uniform_raw();
    void ensure_distribution_ready(double lo, double hi);
    void validate_bounds(double lo, double hi) const;
    double compute_memoryless(double lo, double hi);
    double compute_stateful(double lo, double hi);
    double perlin_interpolate(double t);
    double perlin_noise_3d(double x, double y, double z);
    double brownian_step(double lo, double hi);
    double colored_noise_sample(double lo, double hi);

    std::mt19937 m_rng_engine;
    Algorithm m_algo_type{Algorithm::UNIFORM};
    uint64_t m_xorshift_seed{0xDEADBEEFCAFEBABE};

    mutable std::map<std::string, std::any> m_settings;
    struct State {
        double current_value{0.0};
        size_t steps{0};
        void reset() { current_value = 0.0; steps = 0; }
    } m_internal_state;

    std::normal_distribution<double> m_norm_dist{0.0, 1.0};
    std::exponential_distribution<double> m_exp_dist{1.0};
    bool m_rebuild_needed{true};
    double m_last_lo{-1.0}, m_last_hi{-1.0};
};

// Constructor: Initialize engine and fallback seed
Stochastic::Stochastic(Algorithm algo)
    : m_rng_engine(std::random_device{}())
    , m_algo_type(algo)
    , m_xorshift_seed(std::random_device{}() | (static_cast<uint64_t>(std::random_device{}()) << 32))
{
    if (m_xorshift_seed == 0)
        m_xorshift_seed = 0xDEADBEEFCAFEBABE;
}

// Seed both engines and reset internal state
void Stochastic::seed(uint64_t new_seed) {
    m_rng_engine.seed(static_cast<std::mt19937::result_type>(new_seed));
    m_xorshift_seed = new_seed;
    if (m_xorshift_seed == 0)
        m_xorshift_seed = 0xDEADBEEFCAFEBABE;
    m_internal_state.reset();
    m_rebuild_needed = true;
}

// Change algorithm and reset state
void Stochastic::set_algorithm(Algorithm algo) {
    if (m_algo_type != algo) {
        m_algo_type = algo;
        m_internal_state.reset();
        m_rebuild_needed = true;
    }
}

// Store configuration setting
void Stochastic::configure(const std::string& key, std::any value) {
    m_settings[key] = std::move(value);
    m_rebuild_needed = true;
}

// Retrieve optional configuration entry
std::optional<std::any> Stochastic::retrieve_config(const std::string& key) const {
    auto iter = m_settings.find(key);
    return (iter != m_settings.end()) ? std::optional{iter->second} : std::nullopt;
}

// Main sampling operator
double Stochastic::operator()(double lo, double hi) {
    validate_bounds(lo, hi);
    switch (m_algo_type) {
    case Algorithm::UNIFORM:
    case Algorithm::NORMAL:
    case Algorithm::EXPONENTIAL:
    case Algorithm::POISSON:
        return compute_memoryless(lo, hi);
    case Algorithm::PERLIN:
        return perlin_noise_3d(m_internal_state.current_value, 0.0, 0.0);
    case Algorithm::GENDY:
        return uniform_raw() * (hi - lo) + lo;
    case Algorithm::BROWNIAN:
        return brownian_step(lo, hi);
    case Algorithm::PINK:
    case Algorithm::BLUE:
        return colored_noise_sample(lo, hi);
    default:
        return uniform_raw() * (hi - lo) + lo;
    }
}

// Multi-dimensional access (only for PERLIN)
double Stochastic::at(double x, double y, double z) {
    if (m_algo_type != Algorithm::PERLIN)
        throw std::runtime_error("Multi-dimensional access only valid for PERLIN mode");
    return perlin_noise_3d(x, y, z);
}

// Batch sampling
std::vector<double> Stochastic::sample_batch(double lo, double hi, size_t n) {
    validate_bounds(lo, hi);
    std::vector<double> samples;
    samples.reserve(n);
    for (size_t idx = 0; idx < n; ++idx) {
        samples.push_back((*this)(lo, hi));
    }
    return samples;
}

// Reset internal state
void Stochastic::reset_state() {
    m_internal_state.reset();
}

// Xorshift64* generator
uint64_t Stochastic::xorshift64star() {
    uint64_t x = m_xorshift_seed;
    x ^= x >> 12;
    x ^= x << 25;
    x ^= x >> 27;
    m_xorshift_seed = x;
    return x * 2685821657736338717ULL;
}

// Raw uniform [0,1)
double Stochastic::uniform_raw() {
    return (xorshift64star() >> 11) * (1.0 / 9007199254740992.0); // 53-bit mantissa
}

// Validate range
void Stochastic::validate_bounds(double lo, double hi) const {
    if (lo > hi)
        throw std::invalid_argument("Stochastic: lower bound must be <= upper bound");
}

// Prepare distributions when needed
void Stochastic::ensure_distribution_ready(double lo, double hi) {
    if (!m_rebuild_needed && lo == m_last_lo && hi == m_last_hi)
        return;

    m_last_lo = lo;
    m_last_hi = hi;
    m_rebuild_needed = false;

    double span = hi - lo;
    if (m_algo_type == Algorithm::NORMAL) {
        double spread = 4.0;
        if (auto cfg = retrieve_config("spread"); cfg.has_value()) {
            spread = std::any_cast<double>(*cfg);
        }
        m_norm_dist = std::normal_distribution<double>{0.0, span / spread};
    } else if (m_algo_type == Algorithm::EXPONENTIAL) {
        m_exp_dist = std::exponential_distribution<double>{1.0};
    }
}

// Memoryless generation logic
double Stochastic::compute_memoryless(double lo, double hi) {
    ensure_distribution_ready(lo, hi);
    switch (m_algo_type) {
    case Algorithm::UNIFORM:
        return lo + uniform_raw() * (hi - lo);
    case Algorithm::NORMAL: {
        double raw = m_norm_dist(m_rng_engine);
        return std::clamp(raw, lo, hi);
    }
    case Algorithm::EXPONENTIAL: {
        double raw = m_exp_dist(m_rng_engine);
        raw /= hi;
        return lo + raw * (hi - lo);
    }
    case Algorithm::POISSON: {
        std::poisson_distribution<int> dist(static_cast<int>(hi - lo));
        return static_cast<double>(dist(m_rng_engine));
    }
    default:
        return lo + uniform_raw() * (hi - lo);
    }
}

// Placeholder for stateful generation (unused currently)
double Stochastic::compute_stateful(double, double) {
    m_internal_state.steps++;
    return m_internal_state.current_value;
}

// Simple cubic interpolation for Perlin-style noise
double Stochastic::perlin_interpolate(double t) {
    return t * t * (3 - 2 * t);
}

// Minimal 3D Perlin-like noise (placeholder with interpolation)
double Stochastic::perlin_noise_3d(double x, double y, double z) {
    int ix = static_cast<int>(std::floor(x));
    int iy = static_cast<int>(std::floor(y));
    int iz = static_cast<int>(std::floor(z));

    double fx = x - ix;
    double fy = y - iy;
    double fz = z - iz;

    double u = perlin_interpolate(fx);
    double v = perlin_interpolate(fy);
    double w = perlin_interpolate(fz);

    auto hash = [&](int i, int j, int k) -> double {
        return ((i * 31 + j) * 31 + k) % 256;
    };

    double g000 = (hash(ix, iy, iz) & 1) ? 1.0 : -1.0;
    double g001 = (hash(ix, iy, iz + 1) & 1) ? 1.0 : -1.0;
    double g010 = (hash(ix, iy + 1, iz) & 1) ? 1.0 : -1.0;
    double g011 = (hash(ix, iy + 1, iz + 1) & 1) ? 1.0 : -1.0;
    double g100 = (hash(ix + 1, iy, iz) & 1) ? 1.0 : -1.0;
    double g101 = (hash(ix + 1, iy, iz + 1) & 1) ? 1.0 : -1.0;
    double g110 = (hash(ix + 1, iy + 1, iz) & 1) ? 1.0 : -1.0;
    double g111 = (hash(ix + 1, iy + 1, iz + 1) & 1) ? 1.0 : -1.0;

    auto dot = [](double gx, double gy, double gz, double dx, double dy, double dz) {
        return gx * dx + gy * dy + gz * dz;
    };

    double n000 = dot(g000, fx, fy, fz);
    double n100 = dot(g100, fx - 1, fy, fz);
    double n010 = dot(g010, fx, fy - 1, fz);
    double n110 = dot(g110, fx - 1, fy - 1, fz);
    double n001 = dot(g001, fx, fy, fz - 1);
    double n101 = dot(g101, fx - 1, fy, fz - 1);
    double n011 = dot(g011, fx, fy - 1, fz - 1);
    double n111 = dot(g111, fx - 1, fy - 1, fz - 1);

    double nx00 = n000 + u * (n100 - n000);
    double nx10 = n010 + u * (n110 - n010);
    double nx01 = n001 + u * (n101 - n001);
    double nx11 = n011 + u * (n111 - n011);

    double nxy0 = nx00 + v * (nx10 - nx00);
    double nxy1 = nx01 + v * (nx11 - nx01);

    return nxy0 + w * (nxy1 - nxy0);
}

// Gendy-style generator (just uniform here)
double Stochastic::brownian_step(double lo, double hi) {
    double step_size = 0.01;
    if (auto cfg = retrieve_config("step_size"); cfg.has_value()) {
        step_size = std::any_cast<double>(cfg.value());
    }

    double delta = (uniform_raw() - 0.5) * 2.0 * step_size;
    m_internal_state.current_value += delta;
    m_internal_state.current_value = std::clamp(m_internal_state.current_value, lo, hi);
    m_internal_state.steps++;
    return m_internal_state.current_value;
}

// Colored noise stubs (currently same as uniform)
double Stochastic::colored_noise_sample(double lo, double hi) {
    return lo + uniform_raw() * (hi - lo);
}

}

#include "bishengir/Dialect/HIVM/Transforms/InjectSync/MoveSyncState.h"
#include "bishengir/Dialect/HIVM/Transforms/InjectSync/SyncCommon.h"
#include "llvm/ADT/STLExtras.h"
#define DEBUG_TYPE "hivm-inject-sync"

using namespace mlir;
using namespace mlir::hivm;

void MoveSyncState::StateOptimize() {
  MoveOutBranchSync();
  MoveForSync();
}

void MoveSyncState::MoveOutBranchSync() {
  for (auto &elem : syncIR) {
    if (auto *branchElem = dyn_cast<BranchInstanceElement>(elem.get())) {
      if (branchElem->getBranchKind() == KindOfBranch::IF_BEGIN) {
        std::pair<unsigned, unsigned> scope = {branchElem->beginId,
                                               branchElem->endId};

        // Process elements between begin and branch point
        for (unsigned idx = branchElem->beginId + 1;
             idx < branchElem->branchId; ++idx) {
          PlanMoveOutBranchSync(
              syncIR[idx].get(),
              {branchElem->beginId, branchElem->branchId}, scope);
        }

        if (branchElem->endId == branchElem->branchId) continue;

        // Process elements between branch point and end
        for (unsigned idx = branchElem->branchId + 1;
             idx < branchElem->endId; ++idx) {
          PlanMoveOutBranchSync(syncIR[idx].get(),
                                {branchElem->branchId, branchElem->endId},
                                scope);
        }
      }
    }
  }
}

void MoveSyncState::PlanMoveOutBranchSync(
    InstanceElement *elem,
    std::pair<unsigned int, unsigned int> range,
    std::pair<unsigned int, unsigned int> scope) {

  checkCondition(
      range.first < elem->GetIndex() && elem->GetIndex() < range.second,
      "PlanMoveOutBranchSync expected element to be within range bounds");

  SyncOps newBefore;
  for (auto &op : elem->pipeBefore) {
    PlanMoveOutIfWaitSync(newBefore, op.get(), range, scope);
  }

  SyncOps newAfter;
  for (auto it = elem->pipeAfter.rbegin(); it != elem->pipeAfter.rend(); ++it) {
    PlanMoveOutIfSetSync(newAfter, it->get(), range, scope);
  }

  elem->pipeAfter = std::move(newAfter);
  elem->pipeBefore = std::move(newBefore);
}

void MoveSyncState::PlanMoveOutIfWaitSync(
    SyncOps &newBefore, SyncOperation *op,
    std::pair<unsigned int, unsigned int> range,
    std::pair<unsigned int, unsigned int> scope) {

  auto type = op->GetType();
  if (type != SyncOperation::TYPE::WAIT_EVENT &&
      type != SyncOperation::TYPE::SYNC_BLOCK_WAIT) {
    newBefore.push_back(op);
    return;
  }

  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(!syncPair.empty(), "expected syncPair not to be empty");
  auto *setOp = syncPair[0].get();

  if ((setOp->GetSyncIRIndex() >= range.second) ||
      (setOp->GetSyncIRIndex() <= range.first)) {
    // Scenario:
    //   setFlag
    //   if():
    //     waitFlag
    //     compound
    // Transform to:
    //   setFlag
    //   waitFlag
    //   if():
    //     compound
    checkSyncIRIndex(syncIR, scope.first);
    syncIR[scope.first]->pipeBefore.push_back(op);
    op->SetSyncIRIndex(scope.first);
  } else {
    newBefore.push_back(op);
  }
}

void MoveSyncState::PlanMoveOutIfSetSync(
    SyncOps &newAfter, SyncOperation *op,
    std::pair<unsigned int, unsigned int> range,
    std::pair<unsigned int, unsigned int> scope) {

  auto type = op->GetType();
  if (type != SyncOperation::TYPE::SET_EVENT &&
      type != SyncOperation::TYPE::SYNC_BLOCK_SET) {
    newAfter.push_back(op);
    return;
  }

  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(syncPair.size() > 1, "expected syncPair size > 1");
  auto *waitOp = syncPair[1].get();

  if ((waitOp->GetSyncIRIndex() >= range.second) ||
      (waitOp->GetSyncIRIndex() <= range.first)) {
    // Scenario:
    //   if():
    //     compound
    //     setFlag
    //   waitFlag
    // Transform to:
    //   if():
    //     compound
    //   setFlag
    //   waitFlag
    checkSyncIRIndex(syncIR, scope.second);
    syncIR[scope.second]->pipeAfter.push_front(op);
    op->SetSyncIRIndex(scope.second);
  } else {
    newAfter.push_back(op);
  }
}

void MoveSyncState::MoveForSync() {
  for (auto &elem : syncIR) {
    if (auto *loopElem = dyn_cast<LoopInstanceElement>(elem.get())) {
      if (loopElem->getLoopKind() == KindOfLoop::LOOP_END) {
        if (loopElem->ignore_block_sync_move_out) {
          continue;
        }

        unsigned i = loopElem->beginId + 1;
        while (i < loopElem->endId) {
          MoveOutSync(syncIR[i].get(),
                      {loopElem->beginId, loopElem->endId});
          ++i;
        }
      }
    }
  }
}

void MoveSyncState::MoveOutSync(InstanceElement *elem,
                                std::pair<unsigned int, unsigned int> range) {
  checkCondition(range.first < elem->GetIndex() && elem->GetIndex() < range.second,
                 "MoveOutSync expected element to be within range bounds");

  SyncOps newBefore;
  for (auto &op : elem->pipeBefore) {
    PlanMoveOutWaitSync(newBefore, op.get(), range);
  }

  SyncOps newAfter;
  for (auto it = elem->pipeAfter.rbegin(); it != elem->pipeAfter.rend(); ++it) {
    PlanMoveOutSetSync(newAfter, it->get(), range);
  }

  elem->pipeAfter = std::move(newAfter);
  elem->pipeBefore = std::move(newBefore);
}

void MoveSyncState::PlanMoveOutWaitSync(
    SyncOps &newBefore, SyncOperation *op,
    std::pair<unsigned int, unsigned int> range) {

  auto type = op->GetType();
  if (type != SyncOperation::TYPE::WAIT_EVENT &&
      type != SyncOperation::TYPE::SYNC_BLOCK_WAIT) {
    newBefore.push_back(op);
    return;
  }

  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(!syncPair.empty(), "expected syncPair not to be empty");
  auto *setOp = syncPair[0].get();

  if ((setOp->GetSyncIRIndex() > range.second) ||
      (setOp->GetSyncIRIndex() < range.first)) {
    // Scenario:
    //   setFlag
    //   for():
    //     waitFlag
    //     compound
    // Transform to:
    //   setFlag
    //   waitFlag
    //   for():
    //     compound
    checkSyncIRIndex(syncIR, range.first);
    syncIR[range.first]->pipeBefore.push_back(op);
    op->SetSyncIRIndex(range.first);
    return;
  }

  newBefore.push_back(op);
}

void MoveSyncState::PlanMoveOutSetSync(
    SyncOps &newAfter, SyncOperation *op,
    const std::pair<unsigned int, unsigned int> range) {

  auto type = op->GetType();
  if (type != SyncOperation::TYPE::SET_EVENT &&
      type != SyncOperation::TYPE::SYNC_BLOCK_SET) {
    newAfter.push_back(op);
    return;
  }

  auto &syncPair = syncOperations[op->GetSyncIndex()];
  checkCondition(syncPair.size() > 1, "expected syncPair size > 1");
  auto *waitOp = syncPair[1].get();

  if ((waitOp->GetSyncIRIndex() > range.second) ||
      (waitOp->GetSyncIRIndex() < range.first)) {
    // Scenario:
    //   for():
    //     compound
    //     setFlag
    //   waitFlag
    // Transform to:
    //   for():
    //     compound
    //   setFlag
    //   waitFlag
    checkSyncIRIndex(syncIR, range.second);
    syncIR[range.second]->pipeAfter.push_front(op);
    op->SetSyncIRIndex(range.second);
    return;
  }

  newAfter.push_back(op);
}

#include <sycl/sycl.hpp>
#include "../utils.h"
#include "../dispatch_utils.h"

namespace vllm {
namespace GroupedTopKImpl {

enum class ScoringMode {
  NONE = 0,
  SOFTMAX_MODE = 1,
  SIGMOID_MODE = 2,
};

template <typename T, int MAX_GROUPS>
struct Fused_Grouped_Topk {
  static constexpr int warp_size = 32;
  static constexpr int max_warp_capacity = 1024;
  static constexpr int items_per_thread = MAX_GROUPS;
  static constexpr float NEG_INF = -INFINITY;

  Fused_Grouped_Topk(
      float* out_weights,
      int* out_indices,
      const T* gate_vals,
      const T* expert_bias,
      const double scale_factor,
      const ScoringMode mode,
      const bool do_renorm,
      const int batch_size,
      const int total_experts,
      const int k_select,
      const int num_groups,
      const int top_per_group)
      : weights(out_weights),
        ids(out_indices),
        gating(gate_vals),
        corrections(expert_bias),
        scaling(scale_factor),
        scoring(mode),
        renorm(do_renorm),
        tokens(batch_size),
        experts(total_experts),
        k(k_select),
        groups(num_groups),
        group_topk(top_per_group) {}

  static inline sycl::nd_range<3>
  compute_launch_dims(const int batch, const int experts_per_batch) {
    int work_per_warp = (experts_per_batch + warp_size - 1) / warp_size;
    int local_dim = (experts_per_batch + work_per_warp - 1) / work_per_warp;
    local_dim = std::min(local_dim, warp_size);
    local_dim = std::min(local_dim, max_warp_capacity);

    int warps_per_group = (local_dim + warp_size - 1) / warp_size;
    local_dim = warps_per_group * warp_size;

    int global_threads = (batch + warps_per_group - 1) / warps_per_group;
    sycl::range<3> local(1, 1, local_dim);
    sycl::range<3> global(1, 1, global_threads);
    return sycl::nd_range<3>(global * local, local);
  }

  static inline float sigmoid(float x) {
    return 1.0f / (1.0f + sycl::native::exp(-x));
  }

  [[sycl::reqd_sub_group_size(warp_size)]]
  void operator()(sycl::nd_item<3> item) const {
    int group_id = item.get_group_linear_id();
    int local_range = item.get_local_range(2);
    int warps_per_block = local_range / warp_size;
    int work_per_warp = (experts + warp_size - 1) / warp_size;
    int experts_per_partition = experts / groups;

    auto sg = item.get_sub_group();
    int warp_id = sg.get_group_id();
    int lane_id = sg.get_local_id();

    int token_idx = group_id * warps_per_block + warp_id;
    if (token_idx >= tokens) return;

    // Load data into local arrays
    T local_values[items_per_thread];
    int local_positions[items_per_thread];
    T local_biases[items_per_thread];

    int base_offset = lane_id * work_per_warp;
    int count = work_per_warp;
    if (base_offset + count > experts) {
      count = experts - base_offset;
      if (count < 0) count = 0;
    }

    for (int i = 0; i < work_per_warp; ++i) {
      local_values[i] = NEG_INF;
      local_positions[i] = -1;
      local_biases[i] = 0.0f;
    }

    for (int i = 0; i < count; ++i) {
      local_values[i] = gating[token_idx * experts + base_offset + i];
    }

    // Copy loaded values to working array
    T working_values[items_per_thread];
    for (int i = 0; i < count; ++i) {
      working_values[i] = local_values[i];
      local_positions[i] = base_offset + i;
    }

    // Apply scoring function
    if (scoring == ScoringMode::SOFTMAX_MODE) {
      float max_val = NEG_INF;
      for (int i = 0; i < count; ++i) {
        max_val = (max_val > working_values[i]) ? max_val : working_values[i];
      }

      for (int offset = warp_size / 2; offset > 0; offset /= 2) {
        float peer = sycl::permute_group_by_xor(sg, max_val, offset);
        max_val = (max_val > peer) ? max_val : peer;
      }

      float exp_sum = 0.0f;
      for (int i = 0; i < count; ++i) {
        exp_sum += sycl::native::exp(working_values[i] - max_val);
      }
      for (int offset = warp_size / 2; offset > 0; offset /= 2) {
        exp_sum += sycl::permute_group_by_xor(sg, exp_sum, offset);
      }

      for (int i = 0; i < count; ++i) {
        working_values[i] = sycl::native::exp(working_values[i] - max_val) / exp_sum;
      }
    } else if (scoring == ScoringMode::SIGMOID_MODE) {
      for (int i = 0; i < count; ++i) {
        working_values[i] = sigmoid(working_values[i]);
      }
    }

    bool has_bias = corrections != nullptr;
    if (has_bias) {
      for (int i = 0; i < count; ++i) {
        local_biases[i] = corrections[base_offset + i];
      }
    }

    // Compute per-group scores
    float group_scores[items_per_thread * 2];
    for (int i = 0; i < groups * 2; ++i) {
      group_scores[i] = NEG_INF;
    }

    for (int i = 0; i < count; ++i) {
      float score = working_values[i] + local_biases[i];
      int group_idx = (work_per_warp * lane_id + i) / experts_per_partition;
      float& best = group_scores[group_idx];
      float& second = group_scores[groups + group_idx];

      if (score > best) {
        second = best;
        best = score;
      } else if (score > second) {
        second = score;
      }
      group_scores[group_idx] = best;
      group_scores[groups + group_idx] = second;
    }

    // Reduce within warp to get top two per group
    for (int g = 0; g < groups; ++g) {
      float top1 = group_scores[g];
      float top2 = group_scores[groups + g];
      float combined = top1 + (has_bias ? top2 : 0.0f);
      float max_combined = sycl::reduce_over_group(
          sg, sycl::max(combined, combined), sycl::maximum<>());
      group_scores[g] = max_combined;
    }

    // Select top-performing groups
    int selected_groups[items_per_thread];
    for (int k = 0; k < group_topk; ++k) {
      float best_score = NEG_INF;
      int best_idx = 0;
      for (int g = 1; g < groups; ++g) {
        if (group_scores[g] > best_score) {
          best_score = group_scores[g];
          best_idx = g;
        }
      }
      group_scores[best_idx] = NEG_INF;
      selected_groups[k] = best_idx;
    }

    // Mask out non-selected groups
    for (int i = 0; i < work_per_warp; ++i) {
      bool keep = false;
      for (int k = 0; k < group_topk; ++k) {
        if ((local_positions[i] / experts_per_partition) == selected_groups[k]) {
          keep = true;
          break;
        }
      }
      if (!keep) {
        working_values[i] = NEG_INF;
      }
    }

    // Perform final top-k selection
    T final_weights[items_per_thread];
    int final_ids[items_per_thread];
    for (int k = 0; k < k; ++k) {
      float best_val = NEG_INF;
      int best_pos = -1;
      int remove_idx = -1;

      for (int i = 0; i < work_per_warp; ++i) {
        float val = working_values[i] + local_biases[i];
        int pos = local_positions[i];

        for (int offset = warp_size / 2; offset > 0; offset /= 2) {
          float peer_val = sycl::permute_group_by_xor(sg, val, offset);
          int peer_pos = sycl::permute_group_by_xor(sg, pos, offset);
          if (peer_val > val || (peer_val == val && peer_pos < pos)) {
            val = peer_val;
            pos = peer_pos;
          }
        }

        if (val > best_val || (val == best_val && pos < best_pos)) {
          best_val = val;
          best_pos = pos;
          if (pos == local_positions[i]) {
            remove_idx = i;
          }
        }
      }

      int slot = best_pos / work_per_warp;
      int elem = best_pos % work_per_warp;
      best_val = working_values[elem];
      best_val = sycl::group_broadcast(sg, best_val, slot);

      if (remove_idx != -1) {
        working_values[remove_idx] = NEG_INF;
        local_positions[remove_idx] = -1;
      }

      final_weights[k] = best_val;
      final_ids[k] = (best_pos < 0 || best_pos >= experts) ? k : best_pos;
    }

    if (renorm) {
      float total = 0.0f;
      for (int i = 0; i < k; ++i) {
        total += final_weights[i];
      }
      if (total > 0.0f) {
        for (int i = 0; i < k; ++i) {
          final_weights[i] /= total;
        }
      }
    }

    if (lane_id == 0) {
      int out_offset = token_idx * k;
      for (int i = 0; i < k; ++i) {
        weights[out_offset + i] = final_weights[i] * scaling;
        if (final_ids[i] < 0 || final_ids[i] >= experts) {
          ids[out_offset + i] = 0;
        } else {
          ids[out_offset + i] = final_ids[i];
        }
      }
    }
  }

  float* weights;
  int* ids;
  const T* gating;
  const T* corrections;
  const double scaling;
  const ScoringMode scoring;
  const bool renorm;
  const int tokens;
  const int experts;
  const int k;
  const int groups;
  const int group_topk;
};

template <typename T, int MAX_GROUPS>
void launch_fused_grouped_topk(
    sycl::queue& queue,
    float* out_weights,
    int* out_indices,
    const T* gate_vals,
    const T* expert_bias,
    const double scale,
    const ScoringMode mode,
    const bool do_renorm,
    const int batch,
    const int experts,
    const int k,
    const int num_groups,
    const int top_per_group) {
  using Kernel = Fused_Grouped_Topk<T, MAX_GROUPS>;
  auto range = Kernel::compute_launch_dims(batch, experts);
  queue.submit([&](sycl::handler& cgh) {
    Kernel task(
        out_weights,
        out_indices,
        gate_vals,
        expert_bias,
        scale,
        mode,
        do_renorm,
        batch,
        experts,
        k,
        num_groups,
        top_per_group);
    cgh.parallel_for(range, task);
  });
}

template <typename T>
void fused_grouped_topk(
    float* out_weights,
    int* out_indices,
    const T* gate_vals,
    const T* expert_bias,
    const double scale,
    const ScoringMode mode,
    const bool do_renorm,
    const int batch,
    const int experts,
    const int k,
    const int num_groups,
    const int top_per_group) {
  auto& queue = vllm::xpu::vllmGetQueue();
  TORCH_CHECK(
      top_per_group <= num_groups,
      "top_per_group must be <= num_groups");
  TORCH_CHECK(
      experts % num_groups == 0,
      "experts must be divisible by num_groups");

  int padded_groups = ((num_groups + 7) / 8) * 8;

#define CASE_GROUP(G) \
  case G:             \
    launch_fused_grouped_topk<T, G>( \
        queue, out_weights, out_indices, gate_vals, expert_bias, \
        scale, mode, do_renorm, batch, experts, k, num_groups, top_per_group); \
    break;

  switch (padded_groups) {
    CASE_GROUP(8)
    CASE_GROUP(16)
    default:
      TORCH_CHECK(false, "Unsupported num_groups: ", num_groups);
  }
#undef CASE_GROUP
}

}; // namespace GroupedTopKImpl
} // namespace vllm

std::tuple<torch::Tensor, torch::Tensor> fused_grouped_topk(
    const torch::Tensor& hidden_states,
    const torch::Tensor& gating_output,
    const int64_t n_topk,
    const bool renormalize,
    const int64_t n_expert_group,
    const int64_t n_topk_group,
    const c10::string_view scoring_func,
    const double routed_scaling_factor,
    const c10::optional<torch::Tensor>& bias) {
  auto shape = gating_output.sizes().vec();
  TORCH_CHECK(
      hidden_states.sizes()[0] == gating_output.sizes()[0],
      "Token count mismatch in hidden_states and gating_output");
  TORCH_CHECK(
      shape.size() == 2,
      "gating_output must be 2D, got ",
      shape.size(),
      "D");

  if (bias.has_value()) {
    auto bshape = bias->sizes().vec();
    TORCH_CHECK(
        bshape[0] == shape[1],
        "Bias dimension mismatch: expected ",
        shape[1],
        ", got ",
        bshape[0]);
  }

  int n_tokens = shape[0];
  int n_experts = shape[1];

  vllm::GroupedTopKImpl::ScoringFunc mode;
  if (scoring_func == "sigmoid") {
    mode = vllm::GroupedTopKImpl::ScoringFunc::SIGMOID;
  } else if (scoring_func == "softmax") {
    mode = vllm::GroupedTopKImpl::ScoringFunc::SOFTMAX;
  } else {
    mode = vllm::GroupedTopKImpl::ScoringFunc::DEFAULT;
  }

  auto topk_weights =
      torch::empty({n_tokens, n_topk}, at::dtype(at::kFloat).device(at::kXPU));
  auto topk_indices =
      torch::empty({n_tokens, n_topk}, at::dtype(at::kInt).device(at::kXPU));

  auto dtype = gating_output.scalar_type();
  if (dtype == at::kBFloat16) {
    using scalar_t = sycl::ext::oneapi::bfloat16;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr()) : nullptr,
        routed_scaling_factor,
        mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  } else if (dtype == at::kHalf) {
    using scalar_t = sycl::half;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr()) : nullptr,
        routed_scaling_factor,
        mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  } else {
    using scalar_t = float;
    vllm::GroupedTopKImpl::fused_grouped_topk<scalar_t>(
        reinterpret_cast<float*>(topk_weights.data_ptr()),
        reinterpret_cast<int*>(topk_indices.data_ptr()),
        reinterpret_cast<scalar_t*>(gating_output.data_ptr()),
        bias.has_value() ? reinterpret_cast<scalar_t*>(bias->data_ptr()) : nullptr,
        routed_scaling_factor,
        mode,
        renormalize,
        n_tokens,
        n_experts,
        n_topk,
        n_expert_group,
        n_topk_group);
  }

  return std::make_tuple(topk_weights, topk_indices);
}

