    // Draw background rectangle for sequencer area
    void RenderNeoSequencerBackground(const ImVec4 &tint, const ImVec2 &pos, const ImVec2 &dims, ImDrawList *canvas, float cornerRadius) {
        if (!canvas) canvas = GetWindowDrawList();
        const ImRect bounds{pos, pos + dims};
        canvas->AddRectFilled(bounds.Min, bounds.Max, ColorConvertFloat4ToU32(tint), cornerRadius);
    }

    // Draw top bar background
    void RenderNeoSequencerTopBarBackground(const ImVec4 &tint, const ImVec2 &pos, const ImVec2 &dims,
                                            ImDrawList *canvas, float cornerRadius) {
        if (!canvas) canvas = GetWindowDrawList();
        const ImRect region{pos, pos + dims};
        canvas->AddRectFilled(region.Min, region.Max, ColorConvertFloat4ToU32(tint), cornerRadius);
    }

    // Draw frame lines and labels on top bar
    void RenderNeoSequencerTopBarOverlay(float zoomFactor, float labelWidth,
                                         unsigned firstFrame, unsigned lastFrame, unsigned frameOffset,
                                         const ImVec2 &origin, const ImVec2 &extent,
                                         ImDrawList *canvas, bool showTicks, bool showNumbers, float maxTickSpacing) {
        if (!canvas) canvas = GetWindowDrawList();

        const auto& styleRef = GetStyle();
        const ImRect headerRect{
            origin + ImVec2{styleRef.FramePadding.x + labelWidth, styleRef.FramePadding.y},
            origin + extent
        };

        const unsigned viewFirst = firstFrame + frameOffset;
        const unsigned viewLast  = lastFrame  + frameOffset;

        if (showTicks) {
            const int totalFrames = static_cast<int>((viewLast + 1) - viewFirst);
            const float rawPixelPerFrame = GetPerFrameWidth(extent.x, labelWidth, lastFrame, firstFrame, zoomFactor);
            if (rawPixelPerFrame <= 0.0f) return;

            int powerIndex = 0;
            unsigned majorStep = static_cast<unsigned>(pow(10.0, powerIndex++));
            unsigned minorStep = static_cast<unsigned>(pow(10.0, powerIndex));

            float effectiveSpacing = rawPixelPerFrame * static_cast<float>(majorStep);

            while (effectiveSpacing < maxTickSpacing) {
                majorStep = static_cast<unsigned>(pow(10.0, powerIndex++));
                minorStep = static_cast<unsigned>(pow(10.0, powerIndex));
                effectiveSpacing = rawPixelPerFrame * static_cast<float>(majorStep);
            }

            if (majorStep == 0 || minorStep == 0) {
                majorStep = 1;
                minorStep = 10;
            }

            for (int idx = 0; idx < totalFrames; ++idx) {
                const unsigned currentFrame = viewFirst + idx;
                const bool isMajor = (currentFrame % majorStep) == 0;
                const bool isMinor = (currentFrame % minorStep) == 0;

                if (!isMajor && !isMinor) continue;

                const float lineHeight = isMinor ? headerRect.GetSize().y : headerRect.GetSize().y / 2.0f;
                const float xPos = headerRect.Min.x + static_cast<float>(idx) * (effectiveSpacing / static_cast<float>(majorStep));

                const ImVec2 start{xPos, headerRect.Max.y};
                const ImVec2 end{xPos, headerRect.Max.y - lineHeight};

                canvas->AddLine(start, end, IM_COL32_WHITE, 1.0f);

                if (showNumbers && isMinor) {
                    char buffer[16];
                    const int written = snprintf(buffer, sizeof(buffer), "%u", currentFrame);
                    if (written > 0) {
                        canvas->AddText(nullptr, 0.0f, {start.x + 2.0f, headerRect.Min.y}, IM_COL32_WHITE, buffer);
                    }
                }
            }
        }
    }

    // Render timeline label with optional arrow for groups
    void RenderNeoTimelineLabel(const char *text, const ImVec2 &pos, const ImVec2 &dim,
                                const ImVec4 &tint, bool isGroup, bool expanded, ImDrawList *canvas) {
        const auto& uiStyle = GetStyle();
        if (!canvas) canvas = GetWindowDrawList();

        ImVec2 cursor = pos;
        if (isGroup) {
            RenderArrow(canvas, cursor, IM_COL32_WHITE, expanded ? ImGuiDir_Down : ImGuiDir_Right);
            cursor.x += dim.y + uiStyle.ItemSpacing.x;
        }

        canvas->AddText(cursor, ColorConvertFloat4ToU32(tint), text, FindRenderedTextEnd(text));
    }

    // Draw border around timelines
    void RenderNeoTimelinesBorder(const ImVec4 &borderColor, const ImVec2 &origin, const ImVec2 &dims,
                                  ImDrawList *canvas, float radius, float thickness) {
        if (!canvas) canvas = GetWindowDrawList();
        canvas->AddRect(origin, origin + dims, ColorConvertFloat4ToU32(borderColor), radius, 0, thickness);
    }

    // Highlight selected timeline lane
    void RenderNeoTimelane(bool isActive, const ImVec2 &origin, const ImVec2 &dims,
                           const ImVec4 &accentColor, ImDrawList *canvas) {
        if (!canvas) canvas = GetWindowDrawList();
        if (isActive) {
            const ImRect fillArea{origin, origin + dims};
            canvas->AddRectFilled(fillArea.Min, fillArea.Max, ColorConvertFloat4ToU32(accentColor));
        }
    }

    // Compute width per frame in pixels
    float GetPerFrameWidth(float totalWidth, float labelWidth, unsigned lastFrame, unsigned firstFrame, float zoom) {
        const auto& style = GetStyle();
        const float usableWidth = totalWidth - labelWidth - style.FramePadding.x;
        const unsigned frameCount = (lastFrame + 1) - firstFrame;
        return (usableWidth / static_cast<float>(frameCount)) * zoom;
    }

    // Helper structure for line endpoints
    struct LineEndpoints {
        ImVec2 head;
        ImVec2 tail;
    };

    // Generate vertical line for current frame indicator
    static LineEndpoints BuildCurrentFrameLine(const ImRect &box, float laneHeight) {
        const ImVec2 midX = ImVec2{box.Min.x + box.GetSize().x * 0.5f, box.Max.y};
        return LineEndpoints{midX, midX + ImVec2{0.0f, laneHeight}};
    }

    // Draw current frame marker (vertical line + top pointer)
    void RenderNeoSequencerCurrentFrame(const ImVec4 &lineColor, const ImVec4 &pointerColor,
                                        const ImRect &hitBox, float laneHeight, float strokeWidth, ImDrawList *canvas) {
        if (!canvas) canvas = GetWindowDrawList();

        const auto linePair = BuildCurrentFrameLine(hitBox, laneHeight);
        canvas->AddLine(linePair.head, linePair.tail, ColorConvertFloat4ToU32(lineColor), strokeWidth);
        canvas->PopClipRect();

        // Custom triangle-like pointer shape at top
        const ImVec2 size = hitBox.GetSize();
        ImVec2 polyPoints[5];
        polyPoints[0] = hitBox.Min;
        polyPoints[1] = hitBox.Min + ImVec2{size.x, 0.0f};
        polyPoints[2] = hitBox.Min + ImVec2{size.x, size.y * 0.85f};
        polyPoints[3] = hitBox.Min + ImVec2{size.x * 0.5f, size.y};
        polyPoints[4] = hitBox.Min + ImVec2{0.0f, size.y * 0.85f};

        canvas->AddConvexPolyFilled(polyPoints, 5, ColorConvertFloat4ToU32(pointerColor));
    }

}

