// Helper function to convert Python dict to PlanetCondition struct
PlanetCondition convert_planet_dict_to_struct(const py::dict& input) {
    PlanetCondition result{};
    result.satisfy_num   = input["satisfy_num"].cast<uint8_t>();
    result.dsp_level     = input["dsp_level"].cast<uint8_t>();
    result.type          = input["type"].cast<uint8_t>();
    result.liquid        = input["liquid"].cast<uint8_t>();
    result.singularity   = input["singularity"].cast<uint8_t>();
    result.need_veins    = input["need_veins"].cast<uint16_t>();
    result.veins_group   = input["veins_group"].cast<vector<int>>();
    result.veins_point   = input["veins_point"].cast<vector<int>>();

    auto moons_list = input["moons"].cast<py::list>();
    for (const auto& moon_item : moons_list) {
        result.moons.push_back(convert_planet_dict_to_struct(moon_item.cast<py::dict>()));
    }
    return result;
}

// Helper function to convert Python dict to StarCondition struct
StarCondition convert_star_dict_to_struct(const py::dict& input) {
    StarCondition result{};
    result.satisfy_num      = input["satisfy_num"].cast<uint8_t>();
    result.type             = input["type"].cast<uint8_t>();
    result.distance         = input["distance"].cast<float>();
    result.dyson_lumino     = input["dyson_lumino"].cast<float>();
    result.need_veins       = input["need_veins"].cast<uint16_t>();
    result.veins_group      = input["veins_group"].cast<vector<int>>();
    result.veins_point      = input["veins_point"].cast<vector<int>>();

    auto planets_list = input["planets"].cast<py::list>();
    for (const auto& planet_item : planets_list) {
        result.planets.push_back(convert_planet_dict_to_struct(planet_item.cast<py::dict>()));
    }
    return result;
}

// Main conversion function from Python dict to GalaxyCondition struct
GalaxyCondition convert_galaxy_dict_to_struct(const py::dict& input) {
    GalaxyCondition result{};
    result.need_veins   = input["need_veins"].cast<uint16_t>();
    result.veins_group  = input["veins_group"].cast<vector<int>>();
    result.veins_point  = input["veins_point"].cast<vector<int>>();

    // Process stars
    auto stars_list = input["stars"].cast<py::list>();
    for (const auto& star_item : stars_list) {
        result.stars.push_back(convert_star_dict_to_struct(star_item.cast<py::dict>()));
    }

    // Process standalone planets
    auto planets_list = input["planets"].cast<py::list>();
    for (const auto& planet_item : planets_list) {
        result.planets.push_back(convert_planet_dict_to_struct(planet_item.cast<py::dict>()));
    }

    return result;
}

