XMLBuffer::XMLBuffer(std::string path, std::string base_uri, duckdb::FileSystem *fs, const bool strict_parsing,
                     const bool expand_prefixes, const ITriplesBuffer::FileType file_type)
    : ITriplesBuffer(path, base_uri, strict_parsing, expand_prefixes),
      _parser([this](const RdfStatement &s) { this->handleTriple(s); },
              [this](const std::string &prefix, const std::string &uri) { this->handleNamespace(prefix, uri); },
              [this](const std::string &msg) { this->handleParseError(msg); }, base_uri) {
	if (!fs) {
		throw std::runtime_error("XMLBuffer requires a valid DuckDB FileSystem pointer");
	}
	_file_system = fs;
	try {
		_input_stream = _file_system->OpenFile(_file_path, duckdb::FileFlags::FILE_FLAGS_READ);
	} catch (const std::exception &err) {
		throw std::runtime_error("Failed to open RDF file '" + _file_path + "': " + err.what());
	}
	_parser.setBlankNodePrefix("genid");
}

XMLBuffer::~XMLBuffer() {
	// Destructor intentionally left empty; resources managed by RAII
}

void XMLBuffer::PopulateChunk(duckdb::DataChunk &target) {
	_active_chunk = &target;
	_entries_in_current_batch = 0;

	// First, drain any leftover rows from overflow buffer
	for (; !_overflow_queue.empty() && _entries_in_current_batch < STANDARD_VECTOR_SIZE; ++_entries_in_current_batch) {
		const auto &row = _overflow_queue.front();
		target.SetValue(0, _entries_in_current_batch, duckdb::Value(row.graph));
		target.SetValue(1, _entries_in_current_batch, duckdb::Value(row.subject));
		target.SetValue(2, _entries_in_current_batch, duckdb::Value(row.predicate));
		target.SetValue(3, _entries_in_current_batch, duckdb::Value(row.object));
		target.SetValue(4, _entries_in_current_batch, duckdb::Value(row.datatype));
		target.SetValue(5, _entries_in_current_batch, duckdb::Value(row.lang));
		_overflow_queue.pop_front();
	}

	char temp_buffer[PARSING_CHUNK_SIZE];
	for (; _entries_in_current_batch < STANDARD_VECTOR_SIZE && !_end_of_file; ) {
		const auto bytes_read = _input_stream->Read(temp_buffer, PARSING_CHUNK_SIZE);
		if (bytes_read < PARSING_CHUNK_SIZE) {
			_end_of_file = true;
		}
		_parser.parseChunk(temp_buffer, static_cast<int>(bytes_read), _end_of_file);
	}

	target.SetCardinality(_entries_in_current_batch);
	_active_chunk = nullptr;
}

void XMLBuffer::StartParse() {
	// Initialization already handled in constructor; no-op here
}

void XMLBuffer::appendToStringVector(duckdb::Vector &vec, idx_t position, const std::string &value) {
	if (value.empty()) {
		duckdb::FlatVector::SetNull(vec, position, true);
		return;
	}
	const auto str_handle = duckdb::StringVector::AddString(vec, value);
	duckdb::FlatVector::GetData<duckdb::string_t>(vec)[position] = str_handle;
}

void XMLBuffer::handleTriple(const RdfStatement &stmt) {
	// If current chunk is full, store row in overflow queue instead
	if (_entries_in_current_batch >= STANDARD_VECTOR_SIZE) {
		RDFRow row;
		row.subject = stmt.subject;
		row.predicate = stmt.predicate;
		row.object = stmt.object;
		row.graph.clear();
		row.datatype = stmt.datatype;
		row.lang = stmt.language;
		_overflow_queue.emplace_back(std::move(row));
		return;
	}

	// Fill columns for current row
	appendToStringVector(_active_chunk->data[0], _entries_in_current_batch, "");
	appendToStringVector(_active_chunk->data[1], _entries_in_current_batch, stmt.subject);
	appendToStringVector(_active_chunk->data[2], _entries_in_current_batch, stmt.predicate);
	appendToStringVector(_active_chunk->data[3], _entries_in_current_batch, stmt.object);
	appendToStringVector(_active_chunk->data[4], _entries_in_current_batch, stmt.datatype);
	appendToStringVector(_active_chunk->data[5], _entries_in_current_batch, stmt.language);

	++_entries_in_current_batch;
}

void XMLBuffer::handleNamespace(const std::string &prefix, const std::string &uri) {
	_parser.addNameSpace(prefix, uri);
}

void XMLBuffer::handleParseError(const std::string &message) {
	throw duckdb::SyntaxException("XML parse error: " + message);
}

#include "core/cancellation.h"
#include "gtest/gtest.h"

namespace slop {
namespace {

// Test that a newly constructed CancellationRequest is not in cancelled state
TEST(CancellationRequestTest, InitialState) {
  CancellationRequest request;
  EXPECT_FALSE(request.IsCancelled());
}

// Test that calling Cancel transitions the request to cancelled state
TEST(CancellationRequestTest, Cancel) {
  CancellationRequest request;
  request.Cancel();
  EXPECT_TRUE(request.IsCancelled());
}

// Test that calling Cancel multiple times still leaves the request in cancelled state
TEST(CancellationRequestTest, MultipleCancel) {
  CancellationRequest request;
  request.Cancel();
  request.Cancel(); // Second cancel should be harmless
  EXPECT_TRUE(request.IsCancelled());
}

// Test that callbacks registered before cancellation are invoked upon cancellation
TEST(CancellationRequestTest, RegisterCallbackBeforeCancel) {
  CancellationRequest request;
  bool executed = false;
  request.RegisterCallback([&] { executed = true; });
  EXPECT_FALSE(executed);
  request.Cancel();
  EXPECT_TRUE(executed);
}

// Test that callbacks registered after cancellation are invoked immediately
TEST(CancellationRequestTest, RegisterCallbackAfterCancel) {
  CancellationRequest request;
  request.Cancel();
  bool executed = false;
  request.RegisterCallback([&] { executed = true; });
  EXPECT_TRUE(executed); // Should be called immediately since already cancelled
}

// Test that multiple callbacks are all invoked on cancellation
TEST(CancellationRequestTest, MultipleCallbacks) {
  CancellationRequest request;
  int counter = 0;
  request.RegisterCallback([&] { counter++; });
  request.RegisterCallback([&] { counter++; });
  request.Cancel();
  EXPECT_EQ(counter, 2);
}

