// Constants remain largely unchanged but are slightly reordered for variety
constexpr float NEG_INF = -INFINITY;
constexpr int32_t WARP_WIDTH = 32;
constexpr int32_t THREADS_PER_BLOCK = 512;
constexpr int32_t WARPS_PER_GRID = THREADS_PER_BLOCK / WARP_WIDTH;

namespace warp_topk {

// Helper: Align length to next multiple of 'align_val'
template <typename T>
inline T align_up(T value, T align_val) {
  if (value == 0) return 0;
  return ((value - 1) / align_val + 1) * align_val;
}

// Helper: Check if a number is a power of two
template <typename T>
inline bool is_power_of_two(T x) {
  return (x > 0) && ((x & (x - 1)) == 0);
}

// Comparison logic for selection (max/min)
template <bool greater>
[[intel::device_indirectly_callable]] inline bool compare_better(
    float val_a, float val_b) {
  return greater ? (val_a > val_b) : (val_a < val_b);
}

template <bool greater>
[[intel::device_indirectly_callable]] inline bool compare_better(
    float val_a, float val_b, int idx_a, int idx_b) {
  bool better = compare_better<greater>(val_a, val_b);
  if (!better && val_a == val_b) {
    // Tie-breaker: prefer smaller index for stability
    better = (idx_a < idx_b);
  }
  return better;
}

// Calculate shared memory size needed per block for top-k operations
int calc_smem_size(int num_warps, int64_t k) {
  uint64_t topk_mem = (sizeof(float) + sizeof(int)) * num_warps * k;
  uint64_t temp_buf = std::max<int>(
      num_warps / 2 * k,
      num_warps * WARP_WIDTH);
  uint64_t aligned_temp = align_up(temp_buf * sizeof(float), 256);
  return std::max((int)topk_mem, (int)(aligned_temp + temp_buf * sizeof(int)));
}

// Recursive Bitonic Sort Implementation (Refactored structure)
template <int N, bool ASC, typename T, typename I>
struct BitonicSorter {
  static void run(T* vals, I* ids, sycl::sub_group const& sg, int tid) {
    constexpr int half = N / 2;
    // First half ascending, second descending -> bitonic sequence
    BitonicSorter<half, true, T, I>::run(vals, ids, sg, tid);
    BitonicSorter<half, false, T, I>::run(vals + half, ids + half, sg, tid);
    Merger<N, ASC, T, I>::merge(vals, ids, sg, tid);
  }
};

// Base case for bitonic sort (32 elements = one warp)
template <bool ASC, typename T, typename I>
struct BitonicSorter<32, ASC, T, I> {
  static void run(T* vals, I* ids, sycl::sub_group const& sg, int tid) {
    int lane = tid % WARP_WIDTH;
    for (int stage = 0; stage < 5; ++stage) {
      int stride = 1 << stage;
      if (stride >= WARP_WIDTH) break;
      bool rev = (lane >> stage) & 2;
      bool sec = lane & stride;
      T other_val = sycl::permute_group_by_xor(sg, *vals, stride);
      I other_id = sycl::permute_group_by_xor(sg, *ids, stride);

      bool cond = (*vals != other_val) &&
                  ((*vals > other_val) != (rev != sec));
      if (cond) {
        *vals = other_val;
        *ids = other_id;
      }
    }
    Merger<32, ASC, T, I>::merge(vals, ids, sg, tid);
  }
};

// Merge step for bitonic sequences
template <int N, bool ASC, typename T, typename I>
struct Merger {
  static void merge(T* vals, I* ids, sycl::sub_group const& sg, int tid) {
    constexpr int half = N / 2;
    for (int i = 0; i < half; ++i) {
      int j = i + half;
      T tmp_v = vals[i];
      T tmp_o = vals[j];
      I tmp_i = ids[i];
      I tmp_j = ids[j];

      bool better = compare_better<ASC>(tmp_v, tmp_o, tmp_i, tmp_j);
      if (better) {
        vals[i] = tmp_o;
        vals[j] = tmp_v;
        ids[i] = tmp_j;
        ids[j] = tmp_i;
      }
    }
    Merger<half, ASC, T, I>::merge(vals, ids, sg, tid);
    Merger<half, ASC, T, I>::merge(vals + half, ids + half, sg, tid);
  }
};

// Specialization for base case merger (32 elements)
template <bool ASC, typename T, typename I>
struct Merger<32, ASC, T, I> {
  static void merge(T* vals, I* ids, sycl::sub_group const& sg, int tid) {
    int lane = tid % WARP_WIDTH;
    for (int stride = WARP_WIDTH / 2; stride > 0; stride >>= 1) {
      bool sec = lane & stride;
      T val = *vals;
      T oth = sycl::permute_group_by_xor(sg, val, stride);
      I idx = *ids;
      I odx = sycl::permute_group_by_xor(sg, idx, stride);

      bool cond = (val != oth) && ((val > oth) == (ASC != sec));
      if (cond) {
        *vals = oth;
        *ids = odx;
      }
    }
  }
};

// Warp-level Top-K selector class
template <int CAP, bool GREATER, typename T, typename I, bool STABLE>
class WarpSelector {
 public:
  WarpSelector(I k, T dummy, char* smem, int tid, int range)
      : lane_(tid % WARP_WIDTH),
        k_(k),
        dummy_(dummy),
        warp_id_(tid / WARP_WIDTH) {
    int n_warp = range / WARP_WIDTH;
    val_smem_ = reinterpret_cast<T*>(smem) + warp_id_ * WARP_WIDTH;
    idx_smem_ = reinterpret_cast<I*>(
                    smem +
                    align_up(n_warp * sizeof(T) * WARP_WIDTH, 256)) +
                warp_id_ * WARP_WIDTH;
    reset();
  }

  void add(T val, I idx, sycl::sub_group const& sg, int tid) {
    bool do_add = compare_better<GREATER>(val, k_th_, idx, k_th_idx_);
    auto mask = sycl::ext::oneapi::group_ballot(sg, do_add);
    if (mask == 0) return;

    int pos = buf_len_ + (mask & ((1u << lane_) - 1)).count();
    if (do_add && pos < WARP_WIDTH) {
      val_smem_[pos] = val;
      idx_smem_[pos] = idx;
      do_add = false;
    }
    buf_len_ += mask.count();

    if (buf_len_ >= WARP_WIDTH) {
      flush_(val_smem_[lane_], idx_smem_[lane_], sg, tid);
      buf_len_ -= WARP_WIDTH;
    }
    if (do_add) {
      int new_pos = pos - WARP_WIDTH;
      val_smem_[new_pos] = val;
      idx_smem_[new_pos] = idx;
    }
  }

  void done(sycl::sub_group const& sg, int tid) {
    if (buf_len_ > 0) {
      T val = (lane_ < buf_len_) ? val_smem_[lane_] : dummy_;
      I idx = (lane_ < buf_len_) ? idx_smem_[lane_] : 0;
      flush_(val, idx, sg, tid);
    }
  }

  void dump(T* out, I* out_idx) const {
    for (int i = 0; i < CAPACITY; ++i) {
      I pos = i * WARP_WIDTH + lane_;
      if (pos < k_) {
        out[pos] = values_[i];
        out_idx[pos] = indices_[i];
      }
    }
  }

 private:
  void reset() {
    for (int i = 0; i < CAPACITY; ++i) {
      values_[i] = dummy_;
      indices_[i] = 0;
    }
    k_th_ = dummy_;
    k_th_idx_ = 0;
    buf_len_ = 0;
  }

  void flush_(T val, I idx, sycl::sub_group const& sg, int tid) {
    BitonicSorter<WARP_WIDTH, GREATER, T, I>::run(&val, &idx, sg, tid);
    T& old = values_[CAPACITY - 1];
    if (compare_better<GREATER>(val, old, idx, indices_[CAPACITY - 1])) {
      old = val;
      indices_[CAPACITY - 1] = idx;
    }
    Merger<CAP, GREATER, T, I>::merge(values_, indices_, sg, tid);
    update_kth_(sg);
  }

  void update_kth_(sycl::sub_group const& sg) {
    k_th_ = sycl::select_from_group(sg, values_[CAPACITY - 1], k_lane_);
    if (STABLE) {
      k_th_idx_ = sycl::select_from_group(sg, indices_[CAPACITY - 1], k_lane_);
    }
  }

  static constexpr int CAPACITY = CAP / WARP_WIDTH;
  T values_[CAPACITY];
  I indices_[CAPACITY];
  int const lane_;
  I const k_;
  T const dummy_;
  int const warp_id_;
  T* val_smem_;
  I* idx_smem_;
  int buf_len_;
  T k_th_;
  I k_th_idx_;
  static constexpr int k_lane_ = (WARP_WIDTH - 1); // last lane holds k-th
};

