// Utility cast for different types
template <typename TO, typename FROM>
[[intel::device_indirectly_callable]] inline TO convert(FROM val) {
  return static_cast<TO>(val);
}

template <>
[[intel::device_indirectly_callable]] inline float
convert<float, sycl::ext::oneapi::bfloat16>(
    sycl::ext::oneapi::bfloat16 val) {
  return static_cast<float>(val);
}

// Kernel to compute top-2 scores per thread
template <typename T>
class top2_kernel {
 public:
  top2_kernel(
      T* out,
      T const* in,
      int64_t tokens,
      int64_t cases,
      int64_t groups,
      int64_t experts_per_group)
      : output(out),
        input(in),
        token_count(tokens),
        case_count(cases),
        group_count(groups),
        experts_per_group(experts_per_group) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_WIDTH)]] (sycl::nd_item<1> item) const {
    int local_id = item.get_local_id(0);
    int group_id = item.get_group(0);
    int warp_id = local_id / WARP_WIDTH;
    int lane_id = local_id % WARP_WIDTH;
    int case_id = group_id * WARPS_PER_GRID + warp_id;

    if (case_id >= case_count) return;

    T const* current_in = input + case_id * experts_per_group;
    T* current_out = output + case_id;
    auto sg = item.get_sub_group();

    float max1 = NEG_INF;
    float max2 = NEG_INF;

    if (experts_per_group > WARP_WIDTH) {
      for (int i = lane_id; i < experts_per_group; i += WARP_WIDTH) {
        float val = convert<float, T>(current_in[i]);
        if (val > max1) {
          max2 = max1;
          max1 = val;
        } else if (val > max2) {
          max2 = val;
        }
      }
    } else {
      for (int i = lane_id; i < experts_per_group; i += WARP_WIDTH) {
        float val = convert<float, T>(current_in[i]);
        max1 = std::max(max1, val);
      }
      max2 = max1;
    }

    float global_max1 = sycl::reduce_over_group(sg, max1, sycl::maximum<float>());
    float global_max2 = global_max1;

    int count_max1 = sycl::reduce_over_group(
        sg, (max1 == global_max1) ? 1 : 0, sycl::plus<>());

    if (count_max1 == 1) {
      float candidate = (max1 == global_max1) ? max2 : max1;
      global_max2 = sycl::reduce_over_group(sg, candidate, sycl::maximum<float>());
    }

    if (lane_id == 0) {
      *current_out = convert<T, float>(global_max1 + global_max2);
    }
  }

 private:
  T* output;
  T const* input;
  int64_t token_count;
  int64_t case_count;
  int64_t group_count;
  int64_t experts_per_group;
};

// Main kernel for grouped top-k selection
template <typename T, typename IdxT>
class group_topk_kernel {
 public:
  group_topk_kernel(
      sycl::local_accessor<char, 1>& slm,
      T* scores,
      T const* group_scores,
      T* topk_vals,
      IdxT* topk_ids,
      T* scores_with_bias,
      int64_t tokens,
      int64_t groups,
      int64_t topk_groups,
      int64_t k,
      int64_t experts,
      int64_t experts_per_group,
      bool renorm,
      double scale_factor)
      : slm(slm),
        scores(scores),
        group_scores(group_scores),
        topk_vals(topk_vals),
        topk_ids(topk_ids),
        scores_with_bias(scores_with_bias),
        token_count(tokens),
        group_count(groups),
        topk_group(topk_groups),
        k_(k),
        expert_count(experts),
        experts_per_group(experts_per_group),
        do_renorm(renorm),
        scaling(scale_factor) {}

  void operator()
      [[sycl::reqd_sub_group_size(WARP_WIDTH)]] (sycl::nd_item<1> item) const {
    int local_id = item.get_local_id(0);
    int group_id = item.get_group(0);
    int warp_id = local_id / WARP_WIDTH;
    int lane_id = local_id % WARP_WIDTH;
    int case_id = group_id * WARPS_PER_GRID + warp_id;

    T* sbias = scores_with_bias + case_id * expert_count;
    T* scrs = scores + case_id * expert_count;
    T* gscrs = group_scores + case_id * group_count;
    T* out_vals = topk_vals + case_id * k_;
    IdxT* out_ids = topk_ids + case_id * k_;

    int padded_experts =
        warp_topk::align_up(experts_per_group, WARP_WIDTH);
    auto sg = item.get_sub_group();
    char* smem_ptr =
        slm.template get_multi_ptr<sycl::access::decorated::no>().get();
    int* s_ids = reinterpret_cast<int*>(smem_ptr);
    T* s_vals = reinterpret_cast<T*>(s_ids + WARPS_PER_GRID * k_) +
                warp_id * k_;
    s_ids += warp_id * k_;

    T cur_val = NEG_INF;
    T group_top_val = NEG_INF;
    int equal_count = 0;

    if (case_id < token_count) {
      int target_min = WARP_WIDTH - group_count + topk_group;
      if (lane_id < group_count && std::isfinite(convert<float, T>(gscrs[lane_id]))) {
        cur_val = gscrs[lane_id];
      }

      int cnt_eq = WARP_WIDTH - group_count;
      int prev_cnt = 0;

      while (cnt_eq < target_min) {
        float cur_f = convert<float, T>(cur_val);
        float top_f = sycl::reduce_over_group(sg, cur_f, sycl::maximum<float>());
        group_top_val = convert<T, float>(top_f);
        if (cur_f == top_f) {
          cur_val = NEG_INF;
        }
        prev_cnt = cnt_eq;
        cnt_eq = sycl::reduce_over_group(
            sg, (cur_val == NEG_INF) ? 1 : 0, sycl::plus<>());
      }
      equal_count = target_min - prev_cnt;
    }

    item.barrier(sycl::access::fence_space::local_space);

    warp_topk::WarpSelector<
        WARP_WIDTH, true, T, int, true>
        selector(k_, NEG_INF, smem_ptr, local_id, item.get_local_range(0));

    bool proceed = (group_top_val != NEG_INF);
    if (case_id < token_count && proceed) {
      int eq_counter = 0;
      for (int grp = 0; grp < group_count; ++grp) {
        bool is_better =
            (gscrs[grp] > group_top_val) ||
            ((gscrs[grp] == group_top_val) && (eq_counter < equal_count));
        if (is_better) {
          int offset = grp * experts_per_group;
          for (int i = lane_id; i < padded_experts; i += WARP_WIDTH) {
            T cand = (i < experts_per_group) &&
                     std::isfinite(convert<float, T>(sbias[offset + i]))
                         ? sbias[offset + i]
                         : convert<T, float>(NEG_INF);
            selector.add(cand, offset + i, sg, local_id);
          }
          if (gscrs[grp] == group_top_val) {
            ++eq_counter;
          }
        }
      }
      selector.done(sg, local_id);
    }

    item.barrier(sycl::access::fence_space::local_space);

    float sum = 1e-20f;
    if (case_id < token_count && proceed) {
      selector.dumpIdx(s_ids);
      for (int i = lane_id; i < warp_topk::align_up(k_, WARP_WIDTH); i += WARP_WIDTH) {
        T val = (i < k_) ? scrs[s_ids[i]] : convert<T, float>(0.0f);
        s_vals[i] = val;
        sum += sycl::reduce_over_group(
            sg, convert<float, T>(val), sycl::plus<>());
      }
    }

    item.barrier(sycl::access::fence_space::local_space);

    if (case_id < token_count) {
      if (proceed) {
        for (int i = lane_id; i < k_; i += WARP_WIDTH) {
          float val = convert<float, T>(s_vals[i]);
          if (do_renorm) {
            val = val / sum * scaling;
          } else {
            val = val * scaling;
          }
          out_ids[i] = s_ids[i];
          out_vals[i] = convert<T, float>(val);
        }
      } else {
        // Default fallback when no valid group found
        for (int i = lane_id; i < k_; i += WARP_WIDTH) {
          out_ids[i] = i;
          out_vals[i] = convert<T, float>(1.0f / k_);
        }
      }
    }
  }

 private:
  sycl::local_accessor<char, 1> slm;
  T* scores;
  T const* group_scores;
  T* topk_vals;
  IdxT* topk_ids;
  T* scores_with_bias;
  int64_t token_count;
  int64_t group_count;
  int64_t topk_group;
  int64_t k_;
  int64_t expert_count;
  int64_t experts_per_group;
  bool do_renorm;
  double scaling;
};

// Host-side launcher function
template <typename T, typename IdxT>
void launch_noaux(
    T* scores,
    T* group_scores,
    T* topk_vals,
    IdxT* topk_ids,
    T* scores_with_bias,
    int64_t tokens,
    int64_t experts,
    int64_t groups,
    int64_t topk_groups,
    int64_t k,
    bool renorm,
    double scale,
    bool pdl_enabled,
    sycl::queue& q) {
  int64_t total_cases = tokens * groups;
  int64_t blocks1 = (total_cases - 1) / WARPS_PER_GRID + 1;
  sycl::range<1> grid1(blocks1);
  sycl::range<1> blk1(THREADS_PER_BLOCK);

  q.submit([&](sycl::handler& h) {
    h.parallel_for(
        sycl::nd_range<1>(grid1 * blk1, blk1),
        top2_kernel<T>(
            group_scores,
            scores_with_bias,
            tokens,
            total_cases,
            groups,
            experts / groups));
  });

  int64_t blocks2 = (tokens - 1) / WARPS_PER_GRID + 1;
  size_t smem_bytes = warp_topk::calc_smem_size(WARPS_PER_GRID, k);
  sycl::range<1> grid2(blocks2);
  sycl::range<1> blk2(THREADS_PER_BLOCK);

  q.submit([&](sycl::handler& h) {
    sycl::local_accessor<char, 1> slm(
        sycl::range<1>(smem_bytes), h);
    h.parallel_for(
        sycl::nd_range<1>(grid2 * blk2, blk2),
        group_topk_kernel<T, IdxT>(
            slm,
            scores,
            group_scores,
            topk_vals,
            topk_ids,
            scores_with_bias,
            tokens,
            groups,
            topk_groups,
            k,
            experts,
            experts / groups,
            renorm,
            scale));
  });
}

#define INSTANTIATE_LAUNCH(T, IdxT) \
  template void launch_noaux<T, IdxT>( \
      T*, T*, T*, IdxT*, T*, \
      int64_t, int64_t, int64_t, int64_t, int64_t, \
      bool, double, bool, sycl::queue&);

INSTANTIATE_LAUNCH(float, int32_t);
INSTANTIATE_LAUNCH(sycl::half, int32_t);
INSTANTIATE_LAUNCH(sycl::ext::oneapi::bfloat16, int32_t);

