std::tuple<torch::Tensor, torch::Tensor> grouped_topk(
    torch::Tensor const& scores,
    torch::Tensor const& scores_with_bias,
    int64_t n_group,
    int64_t topk_group,
    int64_t topk,
    bool renormalize,
    double routed_scaling_factor) {
  auto dtype = scores_with_bias.scalar_type();
  auto shape = scores_with_bias.sizes();
  int64_t num_tokens = shape[0];
  int64_t num_experts = shape[1];

  TORCH_CHECK(shape.size() == 2, "scores_with_bias must be 2D");
  TORCH_CHECK(num_experts % n_group == 0, "num_experts must be divisible by n_group");
  TORCH_CHECK(n_group <= 32, "n_group must be <= 32");
  TORCH_CHECK(topk <= 32, "topk must be <= 32");

  torch::Tensor group_scores = torch::empty(
      {num_tokens, n_group}, torch::dtype(dtype).device(torch::kXPU));
  torch::Tensor topk_values = torch::empty(
      {num_tokens, topk}, torch::dtype(dtype).device(torch::kXPU));
  torch::Tensor topk_indices = torch::empty(
      {num_tokens, topk}, torch::dtype(torch::kInt32).device(torch::kXPU));

  auto& queue = vllm::xpu::vllmGetQueue();

  switch (dtype) {
    case torch::kFloat16:
      vllm::moe::launch_noaux<sycl::half, int32_t>(
          reinterpret_cast<sycl::half*>(scores.mutable_data_ptr()),
          reinterpret_cast<sycl::half*>(group_scores.mutable_data_ptr()),
          reinterpret_cast<sycl::half*>(topk_values.mutable_data_ptr()),
          reinterpret_cast<int32_t*>(topk_indices.mutable_data_ptr()),
          reinterpret_cast<sycl::half*>(scores_with_bias.data_ptr()),
          num_tokens,
          num_experts,
          n_group,
          topk_group,
          topk,
          renormalize,
          routed_scaling_factor,
          false,
          queue);
      break;
    case torch::kFloat32:
      vllm::moe::launch_noaux<float, int32_t>(
          reinterpret_cast<float*>(scores.mutable_data_ptr()),
          reinterpret_cast<float*>(group_scores.mutable_data_ptr()),
          reinterpret_cast<float*>(topk_values.mutable_data_ptr()),
          reinterpret_cast<int32_t*>(topk_indices.mutable_data_ptr()),
          reinterpret_cast<float*>(scores_with_bias.data_ptr()),
          num_tokens,
          num_experts,
          n_group,
          topk_group,
          topk,
          renormalize,
          routed_scaling_factor,
          false,
          queue);
      break;
    case torch::kBFloat16:
      vllm::moe::launch_noaux<sycl::ext::oneapi::bfloat16, int32_t>(
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(
              scores.mutable_data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(
              group_scores.mutable_data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(
              topk_values.mutable_data_ptr()),
          reinterpret_cast<int32_t*>(topk_indices.mutable_data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(
              scores_with_bias.data_ptr()),
          num_tokens,
          num_experts,
          n_group,
          topk_group,
          topk,
          renormalize,
          routed_scaling_factor,
          false,
          queue);
      break;
    default:
      throw std::invalid_argument("Unsupported dtype");
  }

  return {topk_values, topk_indices};
}

