/* FWmfMediaByteStream structors
 *****************************************************************************/
FWmfMediaByteStream::FWmfMediaByteStream(const TSharedRef<FArchive, ESPMode::ThreadSafe>& InArchive)
	: AsyncReadInProgress(false)
	, Archive(InArchive)
	, RefCount(0)
{ }

FWmfMediaByteStream::~FWmfMediaByteStream()
{
	checkSlow(RefCount == 0);
}

/* IMFAsyncCallback interface
 *****************************************************************************/
STDMETHODIMP_(ULONG) FWmfMediaByteStream::AddRef()
{
	return FPlatformAtomics::InterlockedIncrement(&RefCount);
}

STDMETHODIMP FWmfMediaByteStream::GetParameters(unsigned long*, unsigned long*)
{
	return E_NOTIMPL;
}

STDMETHODIMP FWmfMediaByteStream::Invoke(IMFAsyncResult* AsyncResult)
{
	if (!AsyncResult)
	{
		return S_OK;
	}

	IUnknown* pState = nullptr;
	HRESULT hr = AsyncResult->GetState(&pState);
	if (FAILED(hr) || !pState)
	{
		SafeRelease(pState);
		return S_OK;
	}

	IMFAsyncResult* pCallerResult = nullptr;
	hr = pState->QueryInterface(IID_IMFAsyncResult, reinterpret_cast<void**>(&pCallerResult));
	if (FAILED(hr) || !pCallerResult)
	{
		SafeRelease(pState);
		return S_OK;
	}

	IUnknown* pReadStateUnknown = nullptr;
	hr = pCallerResult->GetObject(&pReadStateUnknown);
	if (FAILED(hr) || !pReadStateUnknown)
	{
		SafeRelease(pCallerResult);
		SafeRelease(pState);
		return S_OK;
	}

	FWmfMediaReadState* pReadState = static_cast<FWmfMediaReadState*>(pReadStateUnknown);

	ULONG bytesActuallyRead = 0;
	Read(pReadState->GetReadBuffer(), 
	     pReadState->GetReadBufferSize() - pReadState->GetBytesRead(),
		 &bytesActuallyRead);
	pReadState->IncrementBytesRead(bytesActuallyRead);

	if (pCallerResult)
	{
		pCallerResult->SetStatus(S_OK);
		::MFInvokeCallback(pCallerResult);
	}

	SafeRelease(pCallerResult);
	SafeRelease(pReadStateUnknown);
	SafeRelease(pState);

	return S_OK;
}

#if _MSC_VER == 1900
	#pragma warning(push)
	#pragma warning(disable:4838)
