	#pragma warning(pop)
#endif

STDMETHODIMP_(ULONG) FWmfMediaByteStream::Release()
{
	int32 NewRefCount = FPlatformAtomics::InterlockedDecrement(&RefCount);
	if (NewRefCount == 0)
	{
		delete this;
	}
	return NewRefCount;
}

/* IMFByteStream interface
 *****************************************************************************/
STDMETHODIMP FWmfMediaByteStream::BeginRead(BYTE* pb, ULONG cb, IMFAsyncCallback* pCallback, IUnknown* punkState)
{
	if (!pb || !pCallback)
	{
		return E_INVALIDARG;
	}

	TComPtr<FWmfMediaReadState> pReadState = MakeShareable(new FWmfMediaReadState(pb, cb));
	if (!pReadState.IsValid())
	{
		return E_OUTOFMEMORY;
	}

	IMFAsyncResult* pAsyncResult = nullptr;
	HRESULT hr = ::MFCreateAsyncResult(pReadState.Get(), pCallback, punkState, &pAsyncResult);
	if (SUCCEEDED(hr))
	{
		FScopeLock Lock(&CriticalSection);
		AsyncReadInProgress = true;

		hr = ::MFPutWorkItem(MFASYNC_CALLBACK_QUEUE_STANDARD, this, pAsyncResult);
		pAsyncResult->Release();
	}
	return hr;
}

STDMETHODIMP FWmfMediaByteStream::BeginWrite(const BYTE* pb, ULONG cb, IMFAsyncCallback* pCallback, IUnknown* punkState)
{
	return E_NOTIMPL;
}

STDMETHODIMP FWmfMediaByteStream::Close()
{
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::EndRead(IMFAsyncResult* pResult, ULONG* pcbRead)
{
	if (!pcbRead)
	{
		return E_INVALIDARG;
	}

	IUnknown* pUnknown = nullptr;
	HRESULT hr = pResult->GetObject(&pUnknown);
	if (FAILED(hr) || !pUnknown)
	{
		return hr;
	}

	FWmfMediaReadState* pReadState = static_cast<FWmfMediaReadState*>(pUnknown);
	*pcbRead = static_cast<ULONG>(pReadState->GetBytesRead());
	pUnknown->Release();

	{
		FScopeLock Lock(&CriticalSection);
		AsyncReadInProgress = false;
	}

	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::EndWrite(IMFAsyncResult* pResult, ULONG* pcbWritten)
{
	return E_NOTIMPL;
}

STDMETHODIMP FWmfMediaByteStream::Flush()
{
	return E_NOTIMPL;
}

STDMETHODIMP FWmfMediaByteStream::GetCapabilities(DWORD* pdwCapabilities)
{
	if (!pdwCapabilities)
	{
		return E_POINTER;
	}

	FScopeLock Lock(&CriticalSection);
	*pdwCapabilities = MFBYTESTREAM_IS_READABLE | MFBYTESTREAM_IS_SEEKABLE;
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::GetCurrentPosition(QWORD* pqwPosition)
{
	if (!pqwPosition)
	{
		return E_POINTER;
	}

	FScopeLock Lock(&CriticalSection);
	*pqwPosition = static_cast<QWORD>(Archive->Tell());
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::GetLength(QWORD* pqwLength)
{
	if (!pqwLength)
	{
		return E_POINTER;
	}

	FScopeLock Lock(&CriticalSection);
	*pqwLength = static_cast<QWORD>(Archive->TotalSize());
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::IsEndOfStream(BOOL* pfEndOfStream)
{
	if (!pfEndOfStream)
	{
		return E_INVALIDARG;
	}

	FScopeLock Lock(&CriticalSection);
	*pfEndOfStream = Archive->AtEnd() ? TRUE : FALSE;
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::Read(BYTE* pb, ULONG cb, ULONG* pcbRead)
{
	if (!pb)
	{
		return E_INVALIDARG;
	}

	FScopeLock Lock(&CriticalSection);

	int64 CurrentPos = Archive->Tell();
	int64 TotalSize = Archive->TotalSize();
	ULONG BytesRequested = cb;

	// Clamp to available size
	if (BytesRequested > static_cast<ULONG>(TotalSize))
	{
		BytesRequested = static_cast<ULONG>(TotalSize);
	}

	// Prevent overflow or reading past EOF
	int64 Remaining = TotalSize - CurrentPos;
	if (Remaining < 0)
	{
		Remaining = 0;
	}
	if (BytesRequested > static_cast<ULONG>(Remaining))
	{
		BytesRequested = static_cast<ULONG>(Remaining);
	}

	if (BytesRequested > 0)
	{
		Archive->Serialize(pb, BytesRequested);
	}

	if (pcbRead)
	{
		*pcbRead = BytesRequested;
	}

	Archive->Seek(CurrentPos + BytesRequested);
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::Seek(MFBYTESTREAM_SEEK_ORIGIN SeekOrigin, LONGLONG qwSeekOffset, DWORD dwSeekFlags, QWORD* pqwCurrentPosition)
{
	FScopeLock Lock(&CriticalSection);

	if (AsyncReadInProgress)
	{
		return S_FALSE;
	}

	switch (SeekOrigin)
	{
	case msoCurrent:
		Archive->Seek(Archive->Tell() + qwSeekOffset);
		break;
	default:
		Archive->Seek(qwSeekOffset);
		break;
	}

	if (pqwCurrentPosition)
	{
		*pqwCurrentPosition = static_cast<QWORD>(Archive->Tell());
	}

	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::SetLength(QWORD qwLength)
{
	return E_NOTIMPL;
}

STDMETHODIMP FWmfMediaByteStream::SetCurrentPosition(QWORD qwPosition)
{
	FScopeLock Lock(&CriticalSection);

	if (AsyncReadInProgress)
	{
		return S_FALSE;
	}

	int64 MaxPos = Archive->TotalSize();
	if (qwPosition > static_cast<QWORD>(MaxPos))
	{
		qwPosition = static_cast<QWORD>(MaxPos); // clamp per MSDN guidance
	}

	Archive->Seek(static_cast<int64>(qwPosition));
	return S_OK;
}

STDMETHODIMP FWmfMediaByteStream::Write(const BYTE* pb, ULONG cb, ULONG* pcbWritten)
{
	return E_NOTIMPL;
}

