TEST_F(PrestoHasherTest, maps) {
  // Simple map: key -> single-element array
  auto mapVector = createMapOfArraysVector<int64_t, int64_t>(
      {{{1, {{1}}}}, {{2, {{2}}}}, {{3, {{3}}}}});
  assertHash(
      mapVector,
      {9155312661752487122, -6461599496541202183, 5488675304642487510});

  // Map with non-empty arrays
  auto mapOfArrays = createMapOfArraysVector<int64_t, int64_t>(
      {{{1, {{1, 2, 3}}}}, {{2, {{4, 5, 6}}}}, {{3, {{7, 8, 9}}}}});
  assertHash(
      mapOfArrays,
      {-6691024575166067114, -7912800814947937532, -5636922976001735986});

  // Map containing nulls in keys/values/arrays
  auto mapWithNullArrays = createMapOfArraysVector<int64_t, int64_t>(
      {{{1, std::nullopt}},
       {{2, {{4, 5, std::nullopt}}}},
       {{std::nullopt, {{7, 8, 9}}}}});
  assertHash(
      mapWithNullArrays,
      {9155312661752487122, 6562918552317873797, 2644717257979355699});
}

TEST_F(PrestoHasherTest, rows) {
  // Row vector with two non-nullable columns
  auto rowVec = makeRowVector({
      makeFlatVector<int64_t>({1, 3}),
      makeFlatVector<int64_t>({2, 4}),
  });
  assertHash(rowVec, {4329740752828761434, 655643799837772474});

  // Nullable row vector with mixed nulls
  rowVec = makeRowVector({
      makeNullableFlatVector<int64_t>({1, std::nullopt}),
      makeNullableFlatVector<int64_t>({std::nullopt, 4}),
  });
  assertHash(rowVec, {7113531408683827503, -1169223928725763049});

  // Set first column to null for all rows
  rowVec->setNull(0, true);
  assertHash(rowVec, {0, -1169223928725763049});

  // Now also set second column to null for all rows
  rowVec->setNull(1, true);
  assertHash(rowVec, {0, 0});
}

TEST_F(PrestoHasherTest, wrongVectorType) {
  PrestoHasher hasher(ARRAY(BIGINT()));
  auto inputVector = makeNullableFlatVector<StringView>({"abc"_sv});
  SelectivityVector activeRows(1);
  BufferPtr outputHashes = AlignedBuffer::allocate<int64_t>(1, pool_.get());

  EXPECT_ANY_THROW(hasher.hash(inputVector, activeRows, outputHashes));
}

TEST_F(PrestoHasherTest, timestampWithTimezone) {
  // Helper lambda to build TIMESTAMP_WITH_TIME_ZONE RowVector from string pairs
  auto constructTimestampTZVector =
      [&](const std::vector<std::optional<std::pair<int64_t, std::string>>>&
              tzInputs) -> VectorPtr {
    std::vector<std::optional<int64_t>> tsValues;
    std::vector<std::optional<int16_t>> tzIds;
    size_t count = tzInputs.size();

    BufferPtr nulls = AlignedBuffer::allocate<uint64_t>(bits::nwords(count), pool());
    auto rawNulls = nulls->asMutable<uint64_t>();

    for (size_t idx = 0; idx < count; ++idx) {
      const auto& entry = tzInputs[idx];
      if (entry.has_value()) {
        const auto& [ts, tzStr] = entry.value();
        const int16_t zoneId = tz::getTimeZoneID(tzStr);
        tzIds.push_back(zoneId);
        tsValues.push_back(ts);
        bits::clearNull(rawNulls, idx);
      } else {
        tzIds.push_back(std::nullopt);
        tsValues.push_back(std::nullopt);
        bits::setNull(rawNulls, idx);
      }
    }

    return std::make_shared<RowVector>(
        pool(),
        TIMESTAMP_WITH_TIME_ZONE(),
        nulls,
        count,
        std::vector<VectorPtr>{
            makeNullableFlatVector(tsValues),
            makeNullableFlatVector(tzIds)});
  };

  auto tzData = constructTimestampTZVector(
      {std::optional(std::pair{1639426440000, "+01:00"}),
       std::optional(std::pair{1639426440000, "+03:00"}),
       std::optional(std::pair{1549770072000, "-14:00"}),
       std::nullopt});

  assertHash(
      tzData,
      {-3461822077982309083, -3461822077982309083, -8497890125589769483, 0});
}

