void FDisplayClusterDeviceSideBySideBase::AdjustViewRect(enum EStereoscopicPass StereoPassType, int32& X, int32& Y, uint32& SizeX, uint32& SizeY) const
{
	const int ViewportIdx = DecodeViewportIndex(StereoPassType);
	const EStereoscopicPass EyePass = DecodeStereoscopicPass(StereoPassType);
	const uint32 ViewId = DecodeViewIndex(StereoPassType);

	// Access current viewport configuration
	FDisplayClusterRenderViewport& ActiveViewport = RenderViewports[ViewportIdx];
	const FIntRect& ViewportBounds = ActiveViewport.GetRect();

	// Compute horizontal offset based on eye type
	if (EyePass == EStereoscopicPass::eSSP_LEFT_EYE)
	{
		X = ViewportBounds.Min.X / 2;
	}
	else if (EyePass == EStereoscopicPass::eSSP_RIGHT_EYE)
	{
		X = SizeX / 2 + ViewportBounds.Min.X / 2;
	}

	// Vertical position remains unchanged
	Y = ViewportBounds.Min.Y;

	// Adjust dimensions for side-by-side layout
	SizeX = ViewportBounds.Width() / 2;
	SizeY = ViewportBounds.Height();

	// Update rendering context with new rectangle
	FDisplayClusterRenderViewContext& ViewCtx = ActiveViewport.GetContext(ViewId);
	ViewCtx.RenderTargetRect = FIntRect(X, Y, X + SizeX, Y + SizeY);

	// Log adjusted rectangle details
	const FIntRect& FinalRect = ViewCtx.RenderTargetRect;
	UE_LOG(LogDisplayClusterRender, Verbose, TEXT("Adjusted view rect: ViewportIdx=%d, ViewIndex=%d, [%d,%d - %d,%d]"), 
		ViewportIdx, ViewId, FinalRect.Min.X, FinalRect.Min.Y, FinalRect.Max.X, FinalRect.Max.Y);
}

