void Input::getInput() {
    inputButtons.clear();
    mousePointer.isPressed = false;

#ifdef PLATFORM_HAS_KEYBOARD
    int totalKeys = 0;
    Uint8* keyboardState = SDL_GetKeyState(&totalKeys);
    for (int idx = 0; idx < SDLK_LAST; ++idx) {
        if (keyboardState[idx]) {
            const char* keyLabel = SDL_GetKeyName(static_cast<SDLKey>(idx));
            if (keyLabel && *keyLabel) {
                std::string normalized = normalizeKeyName(keyLabel);
                inputButtons.emplace_back(std::move(normalized));
            }
        }
    }
#endif

#ifdef PLATFORM_HAS_CONTROLLER
    if (controller) {
        Uint8 dpadState = SDL_JoystickGetHat(controller, 0);

        if (dpadState & SDL_HAT_UP) {
            buttonPress("dpadUp");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(controller, 4)) mousePointer.y += 3;
#endif
        }
        if (dpadState & SDL_HAT_DOWN) {
            buttonPress("dpadDown");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(controller, 4)) mousePointer.y -= 3;
#endif
        }
        if (dpadState & SDL_HAT_LEFT) {
            buttonPress("dpadLeft");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(controller, 4)) mousePointer.x -= 3;
#endif
        }
        if (dpadState & SDL_HAT_RIGHT) {
            buttonPress("dpadRight");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(controller, 4)) mousePointer.x += 3;
#endif
        }

        // Button presses
        if (SDL_JoystickGetButton(controller, 0)) buttonPress("A");
        if (SDL_JoystickGetButton(controller, 1)) buttonPress("B");
        if (SDL_JoystickGetButton(controller, 2)) buttonPress("X");
        if (SDL_JoystickGetButton(controller, 3)) buttonPress("Y");

        if (SDL_JoystickGetButton(controller, 4)) {
            buttonPress("shoulderL");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            mousePointer.isMoving = true;
#endif
        } else {
            mousePointer.isMoving = false;
        }

        if (SDL_JoystickGetButton(controller, 5)) {
            buttonPress("shoulderR");
#if !defined(PLATFORM_HAS_MOUSE) && !defined(PLATFORM_HAS_TOUCH)
            if (SDL_JoystickGetButton(controller, 4)) mousePointer.isPressed = true;
#endif
        }

        if (SDL_JoystickGetButton(controller, 7)) buttonPress("start");
        if (SDL_JoystickGetButton(controller, 6)) buttonPress("back");
        if (SDL_JoystickGetButton(controller, 8)) buttonPress("LeftStickPressed");
        if (SDL_JoystickGetButton(controller, 9)) buttonPress("RightStickPressed");

        // Left stick axes
        float lsX = SDL_JoystickGetAxis(controller, 0);
        float lsY = SDL_JoystickGetAxis(controller, 1);
        if (lsX > CONTROLLER_DEADZONE_X) buttonPress("LeftStickRight");
        if (lsX < -CONTROLLER_DEADZONE_X) buttonPress("LeftStickLeft");
        if (lsY > CONTROLLER_DEADZONE_Y) buttonPress("LeftStickDown");
        if (lsY < -CONTROLLER_DEADZONE_Y) buttonPress("LeftStickUp");

        // Right stick axes
        float rsX = SDL_JoystickGetAxis(controller, 2);
        float rsY = SDL_JoystickGetAxis(controller, 3);
        if (rsX > CONTROLLER_DEADZONE_X) buttonPress("RightStickRight");
        if (rsX < -CONTROLLER_DEADZONE_X) buttonPress("RightStickLeft");
        if (rsY > CONTROLLER_DEADZONE_Y) buttonPress("RightStickDown");
        if (rsY < -CONTROLLER_DEADZONE_Y) buttonPress("RightStickUp");

        // Triggers
        if (SDL_JoystickGetAxis(controller, 4) > CONTROLLER_DEADZONE_TRIGGER) buttonPress("LT");
        if (SDL_JoystickGetAxis(controller, 5) > CONTROLLER_DEADZONE_TRIGGER) buttonPress("RT");
    }
#endif

    if (!inputButtons.empty()) {
        inputButtons.push_back("any");
    }

    BlockExecutor::executeKeyHats();

#ifdef PLATFORM_HAS_MOUSE
    auto rawPos = getTouchPosition();
    auto scaledCoords = Scratch::screenToScratchCoords(rawPos[0], rawPos[1], Render::getWidth(), Render::getHeight());
    mousePointer.x = scaledCoords.first;
    mousePointer.y = scaledCoords.second;

    Uint32 mouseButtons = SDL_GetMouseState(nullptr, nullptr);
    mousePointer.isPressed = (mouseButtons & (SDL_BUTTON(SDL_BUTTON_LEFT) | SDL_BUTTON(SDL_BUTTON_RIGHT))) != 0;
#endif

    BlockExecutor::doSpriteClicking();
}

std::string Input::openSoftwareKeyboard(const char* prompt) {
    std::unique_ptr<TextObject> displayText = createTextObject(std::string(prompt), 0, 0);
    displayText->setCenterAligned(true);
    displayText->setColor(Math::color(0, 0, 0, 170));

    // Adjust scale if text too wide
    auto textSize = displayText->getSize();
    if (textSize[0] > Render::getWidth() * 0.85f) {
        float scaleFactor = Render::getWidth() / (textSize[0] * 1.15f);
        displayText->setScale(scaleFactor);
    }

    std::unique_ptr<TextObject> label = createTextObject("ENTER TEXT:", 0, 0);
    label->setCenterAligned(true);
    label->setColor(Math::color(0, 0, 0, 255));

    std::string currentInput = "";
    bool running = true;
    SDL_Event evt;

    while (running) {
        while (SDL_PollEvent(&evt)) {
            switch (evt.type) {
            case SDL_KEYDOWN: {
                SDL_keysym ks = evt.key.keysym;
                // Unicode input for printable ASCII
                if (ks.unicode != 0 &&
                    (ks.unicode & 0xFF80) == 0 &&
                    ks.unicode >= ' ') {
                    currentInput += static_cast<char>(ks.unicode);
                    displayText->setText(currentInput);
                    displayText->setColor(Math::color(0, 0, 0, 255));
                }

                switch (ks.sym) {
                case SDLK_RETURN:
                case SDLK_KP_ENTER:
                case SDLK_ESCAPE:
                    running = false;
                    break;
                case SDLK_BACKSPACE:
                    if (!currentInput.empty()) {
                        currentInput.pop_back();
                    }
                    if (currentInput.empty()) {
                        displayText->setText(std::string(prompt));
                        displayText->setColor(Math::color(0, 0, 0, 170));
                    } else {
                        displayText->setText(currentInput);
                    }
                    break;
                default:
                    break;
                }
                break;
            }
            case SDL_QUIT:
                OS::toExit = true;
                running = false;
                break;
            }
        }

        // Auto-resize text if needed
        displayText->setScale(1.0f);
        auto dims = displayText->getSize();
        if (dims[0] > Render::getWidth() * 0.95f) {
            float newScale = Render::getWidth() / (dims[0] * 1.05f);
            displayText->setScale(newScale);
        }

        // Render loop
        Render::beginFrame(0, 117, 77, 117);
        displayText->render(Render::getWidth() / 2, Render::getHeight() * 0.25f);
        label->render(Render::getWidth() / 2, Render::getHeight() * 0.15f);
        Render::endFrame(false);
    }

    return currentInput;
}

