  RightWristPitch = 27,  // Not valid for G1 23dof
  RightWristYaw = 28     // Not valid for G1 23dof
};

inline uint32_t ComputeCRC32(uint32_t *buffer, uint32_t length) {
  uint32_t bit_mask = 0;
  uint32_t input_data = 0;
  uint32_t crc_register = 0xFFFFFFFF;
  const uint32_t poly = 0x04c11db7;

  for (uint32_t i = 0; i < length; ++i) {
    bit_mask = 1 << 31;
    input_data = buffer[i];
    for (uint32_t j = 0; j < 32; ++j) {
      if (crc_register & 0x80000000) {
        crc_register <<= 1;
        crc_register ^= poly;
      } else {
        crc_register <<= 1;
      }
      if (input_data & bit_mask) {
        crc_register ^= poly;
      }
      bit_mask >>= 1;
    }
  }
  return crc_register;
}

class G1DemoController {
 private:
  double simulation_time_;
  double control_period_;  // [s], typically 2ms
  double transition_duration_;  // [s]
  int update_counter_;
  ControlMode current_pr_mode_;
  uint8_t robot_mode_;
  Gamepad controller_;
  REMOTE_DATA_RX remote_input_;

  ThreadSafeBuffer<JointFeedback> joint_state_cache_;
  ThreadSafeBuffer<JointCommand> joint_command_cache_;
  ThreadSafeBuffer<ImuData> imu_data_cache_;

  ChannelPublisherPtr<LowCmd_> command_pub_;
  ChannelSubscriberPtr<LowState_> state_sub_;
  ChannelSubscriberPtr<IMUState_> torso_imu_sub_;

  ThreadPtr command_sender_thread_, motion_control_thread_;
  std::shared_ptr<unitree::robot::b2::MotionSwitcherClient> motion_controller_;

 public:
  explicit G1DemoController(const std::string& network_interface)
      : simulation_time_(0.0),
        control_period_(0.002),
        transition_duration_(3.0),
        update_counter_(0),
        current_pr_mode_(ControlMode::PR_MODE),
        robot_mode_(0) {

    ChannelFactory::Instance()->Init(0, network_interface);

    // Attempt to release any active motion control services
    motion_controller_ = std::make_shared<unitree::robot::b2::MotionSwitcherClient>();
    motion_controller_->SetTimeout(5.0f);
    motion_controller_->Init();

    std::string form_name, active_mode_name;
    while (motion_controller_->CheckMode(form_name, active_mode_name), !active_mode_name.empty()) {
      if (!motion_controller_->ReleaseMode()) {
        std::cout << "Failed to switch to Release Mode\n";
      }
      sleep(5);
    }

    // Initialize publisher and subscriber
    command_pub_.reset(new ChannelPublisher<LowCmd_>(HG_CMD_TOPIC));
    command_pub_->InitChannel();

    state_sub_.reset(new ChannelSubscriber<LowState_>(HG_STATE_TOPIC));
    state_sub_->InitChannel(std::bind(&G1DemoController::ProcessLowState, this, std::placeholders::_1), 1);

    torso_imu_sub_.reset(new ChannelSubscriber<IMUState_>(HG_IMU_TORSO));
    torso_imu_sub_->InitChannel(std::bind(&G1DemoController::HandleTorsoIMU, this, std::placeholders::_1), 1);

    // Start threads
    command_sender_thread_ = CreateRecurrentThreadEx("command_sender", UT_CPU_ID_NONE, 2000, &G1DemoController::SendCommand, this);
    motion_control_thread_ = CreateRecurrentThreadEx("motion_controller", UT_CPU_ID_NONE, 2000, &G1DemoController::ExecuteControlLoop, this);
  }

  void HandleTorsoIMU(const void *message) {
    IMUState_ imu_msg = *(const IMUState_ *)message;
    auto &rpy = imu_msg.rpy();
    if (update_counter_ % 500 == 0) {
      printf("IMU.torso.rpy: %.2f %.2f %.2f\n", rpy[0], rpy[1], rpy[2]);
    }
  }

  void ProcessLowState(const void *message) {
    LowState_ low_state = *(const LowState_ *)message;

    // Validate CRC
    uint32_t expected_crc = ComputeCRC32((uint32_t *)&low_state, (sizeof(LowState_) >> 2) - 1);
    if (low_state.crc() != expected_crc) {
      std::cout << "[ERROR] CRC Error" << std::endl;
      return;
    }

    // Extract motor states
    JointFeedback feedback;
    for (int i = 0; i < G1_MOTOR_COUNT; ++i) {
      feedback.position.at(i) = low_state.motor_state()[i].q();
      feedback.velocity.at(i) = low_state.motor_state()[i].dq();

      if (low_state.motor_state()[i].motorstate() && i <= RightAnkleRoll) {
        std::cout << "[ERROR] motor " << i << " with code " << low_state.motor_state()[i].motorstate() << "\n";
      }
    }
    joint_state_cache_.Update(feedback);

    // Extract IMU data
    ImuData imu_feedback;
    imu_feedback.angular_velocity = low_state.imu_state().gyroscope();
    imu_feedback.orientation = low_state.imu_state().rpy();
    imu_data_cache_.Update(imu_feedback);

    // Update gamepad input
    memcpy(remote_input_.buff, &low_state.wireless_remote()[0], 40);
    controller_.update(remote_input_.RF_RX);

    // Monitor mode changes
    if (robot_mode_ != low_state.mode_machine()) {
      if (robot_mode_ == 0) {
        std::cout << "G1 type: " << unsigned(low_state.mode_machine()) << std::endl;
      }
      robot_mode_ = low_state.mode_machine();
    }

    // Periodic status reporting
    if (++update_counter_ % 500 == 0) {
      update_counter_ = 0;

      // IMU
      auto &rpy = low_state.imu_state().rpy();
      printf("IMU.pelvis.rpy: %.2f %.2f %.2f\n", rpy[0], rpy[1], rpy[2]);

      // Controller buttons
      printf("gamepad_.A.pressed: %d\n", static_cast<int>(controller_.A.pressed));
      printf("gamepad_.B.pressed: %d\n", static_cast<int>(controller_.B.pressed));
      printf("gamepad_.X.pressed: %d\n", static_cast<int>(controller_.X.pressed));
      printf("gamepad_.Y.pressed: %d\n", static_cast<int>(controller_.Y.pressed));

      // Motor details
      auto &motor_states = low_state.motor_state();
      printf("All %d Motors:", G1_MOTOR_COUNT);
      printf("\nmode: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%u,", motor_states[i].mode());
      printf("\npos: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%.2f,", motor_states[i].q());
      printf("\nvel: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%.2f,", motor_states[i].dq());
      printf("\ntau_est: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%.2f,", motor_states[i].tau_est());
      printf("\ntemperature: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%d,%d;", motor_states[i].temperature()[0], motor_states[i].temperature()[1]);
      printf("\nvol: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%.2f,", motor_states[i].vol());
      printf("\nsensor: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%u,%u;", motor_states[i].sensor()[0], motor_states[i].sensor()[1]);
      printf("\nmotorstate: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%u,", motor_states[i].motorstate());
      printf("\nreserve: ");
      for (int i = 0; i < G1_MOTOR_COUNT; ++i) printf("%u,%u,%u,%u;", motor_states[i].reserve()[0], motor_states[i].reserve()[1], motor_states[i].reserve()[2], motor_states[i].reserve()[3]);
      printf("\n");
    }
  }

  void SendCommand() {
    LowCmd_ dds_command;
    dds_command.mode_pr() = static_cast<uint8_t>(current_pr_mode_);
    dds_command.mode_machine() = robot_mode_;

    const std::shared_ptr<const JointCommand> cmd = joint_command_cache_.Fetch();
    if (cmd) {
      for (size_t i = 0; i < G1_MOTOR_COUNT; ++i) {
        dds_command.motor_cmd().at(i).mode() = 1;  // Enable
        dds_command.motor_cmd().at(i).tau() = cmd->feedforward_torque.at(i);
        dds_command.motor_cmd().at(i).q() = cmd->position_cmd.at(i);
        dds_command.motor_cmd().at(i).dq() = cmd->velocity_cmd.at(i);
        dds_command.motor_cmd().at(i).kp() = cmd->kp_gains.at(i);
        dds_command.motor_cmd().at(i).kd() = cmd->kd_gains.at(i);
      }
      dds_command.crc() = ComputeCRC32((uint32_t *)&dds_command, (sizeof(dds_command) >> 2) - 1);
      command_pub_->Write(dds_command);
    }
  }

  void ExecuteControlLoop() {
    JointCommand output_command;

    // Initialize default values
    for (int i = 0; i < G1_MOTOR_COUNT; ++i) {
      output_command.feedforward_torque.at(i) = 0.0f;
      output_command.position_cmd.at(i) = 0.0f;
      output_command.velocity_cmd.at(i) = 0.0f;
      output_command.kp_gains.at(i) = stiffness[i];
      output_command.kd_gains.at(i) = damping[i];
    }

    const std::shared_ptr<const JointFeedback> feedback = joint_state_cache_.Fetch();
    if (feedback) {
      simulation_time_ += control_period_;

      if (simulation_time_ < transition_duration_) {
        // Phase 1: Move to zero posture
        for (int i = 0; i < G1_MOTOR_COUNT; ++i) {
          double progress = std::clamp(simulation_time_ / transition_duration_, 0.0, 1.0);
          output_command.position_cmd.at(i) = (1.0 - progress) * feedback->position.at(i);
        }
      } else if (simulation_time_ < transition_duration_ * 2) {
        // Phase 2: Ankle swing using PR mode
        current_pr_mode_ = ControlMode::PR_MODE;

        double max_pitch = M_PI * 30.0 / 180.0;
        double max_roll = M_PI * 10.0 / 180.0;
        double elapsed = simulation_time_ - transition_duration_;
        double sin_val = std::sin(2.0 * M_PI * elapsed);

        double L_P_des = max_pitch * sin_val;
        double L_R_des = max_roll * sin_val;
        double R_P_des = max_pitch * sin_val;
        double R_R_des = -max_roll * sin_val;

        output_command.position_cmd.at(LeftAnklePitch) = L_P_des;
        output_command.position_cmd.at(LeftAnkleRoll) = L_R_des;
        output_command.position_cmd.at(RightAnklePitch) = R_P_des;
        output_command.position_cmd.at(RightAnkleRoll) = R_R_des;
      } else {
        // Phase 3: Ankle swing using AB mode
        current_pr_mode_ = ControlMode::AB_MODE;

        double max_A = M_PI * 30.0 / 180.0;
        double max_B = M_PI * 10.0 / 180.0;
        double elapsed = simulation_time_ - transition_duration_ * 2;
        double sin_val = std::sin(M_PI * elapsed);
        double cos_val = std::sin(M_PI * elapsed + M_PI);

        double L_A_des = +max_A * sin_val;
        double L_B_des = +max_B * cos_val;
        double R_A_des = -max_A * sin_val;
        double R_B_des = -max_B * cos_val;

        output_command.position_cmd.at(LeftAnkleA) = L_A_des;
        output_command.position_cmd.at(LeftAnkleB) = L_B_des;
        output_command.position_cmd.at(RightAnkleA) = R_A_des;
        output_command.position_cmd.at(RightAnkleB) = R_B_des;
      }

      joint_command_cache_.Update(output_command);
    }
  }
};

int main(int argc, char const *argv[]) {
  if (argc < 2) {
    std::cout << "Usage: g1_ankle_swing_example network_interface" << std::endl;
    exit(0);
  }

  std::string network_interface = argv[1];
  G1DemoController controller(network_interface);

  while (true) {
    sleep(10);
  }

  return 0;
}

