// Helper: determine compressed file size via fstat (POSIX) or fallback
static long long get_file_size(FILE* fp) {
#if defined(_WIN64)
    fseek(fp, 0, SEEK_END);
    return _ftelli64(fp);
#elif defined(_WIN32)
    fseek(fp, 0, SEEK_END);
    return ftell(fp);
#else
    struct stat st;
    if (fstat(fileno(fp), &st) == 0)
        return static_cast<long long>(st.st_size);
    else {
        fseek(fp, 0, SEEK_END);
        return ftello(fp);
    }
#endif
}

// --------------------------------------
// class gzstreambuf:
// --------------------------------------
gzstreambuf* gzstreambuf::open(const char* path, int flags, int compLevel) {
    if (is_open()) return nullptr;

    mode = flags;

    // Reject invalid combinations: append, read/write simultaneously
    if ((mode & std::ios::ate) || (mode & std::ios::app) ||
        ((mode & std::ios::in) && (mode & std::ios::out))) {
        return nullptr;
    }

    // Build mode string: e.g., "rb", "wb1", "wb0"
    char modeStr[8];
    char* p = modeStr;
    *p++ = (mode & std::ios::in) ? 'r' : (mode & std::ios::out) ? 'w' : '\0';
    if (*p != '\0') *p++ = 'b';

    // Compression level indicator
    if (mode & GZ_NO_COMPRESSION) {
        *p++ = '0';
    } else {
        *p++ = '1'; // fast compression
    }
    *p = '\0';

    // Measure compressed length only for input streams
    if (mode & std::ios::in) {
        FILE* tmpFp = fopen(path, "rb");
        if (tmpFp) {
            compLen = get_file_size(tmpFp);
            fclose(tmpFp);
        } else {
            compLen = 0;
        }
    }

    file = gzopen(path, modeStr);
    if (!file) {
        return nullptr;
    }

    opened = true;

    if (mode & std::ios::out) {
        gzsetparams(file, compLevel, Z_DEFAULT_STRATEGY);
    }

    return this;
}

gzstreambuf* gzstreambuf::close() {
    if (is_open()) {
        sync();
        opened = false;
        return (gzclose(file) == Z_OK) ? this : nullptr;
    }
    return nullptr;
}

int gzstreambuf::underflow() { // Input buffer refill
    // Already have data available?
    if (gptr() < egptr()) {
        return static_cast<int>(*reinterpret_cast<unsigned char*>(gptr()));
    }

    // Not readable or closed?
    if (!(mode & std::ios::in) || !opened) {
        return EOF;
    }

    // Preserve up to 4 bytes of putback area
    const int putbackMax = 4;
    int putbackCount = gptr() - eback();
    if (putbackCount > putbackMax) putbackCount = putbackMax;

    // Copy putback data to start of buffer + offset
    if (putbackCount > 0) {
        std::memcpy(buffer + (putbackMax - putbackCount), gptr() - putbackCount, putbackCount);
    }

    // Read new data into buffer after putback area
    const int bytesRead = gzread(file, buffer + putbackMax, bufSize - putbackMax);
    if (bytesRead <= 0) {
        return EOF;
    }

    compressed_position = gzoffset(file);

    // Reset get-area pointers
    setg(buffer + (putbackMax - putbackCount),
         buffer + putbackMax,
         buffer + putbackMax + bytesRead);

    return static_cast<int>(*reinterpret_cast<unsigned char*>(gptr()));
}

int gzstreambuf::flush_buffer() {
    const int writtenBytes = static_cast<int>(pptr() - pbase());
    if (writtenBytes == 0) return 0;

    const int wrote = static_cast<int>(gzwrite(file, pbase(), writtenBytes));
    pbump(-writtenBytes);

    return (wrote == writtenBytes) ? writtenBytes : EOF;
}

int gzstreambuf::overflow(int ch) { // Output buffer overflow handler
    if (!(mode & std::ios::out) || !opened) {
        return EOF;
    }

    if (ch != EOF) {
        *pptr() = static_cast<char>(ch);
        pbump(1);
    }

    return (flush_buffer() == EOF) ? EOF : ch;
}

int gzstreambuf::sync() {
    if (pptr() && pptr() > pbase()) {
        if (flush_buffer() == EOF) return -1;
    }
    return 0;
}

size_t gzstreambuf::getCompressedLength() {
    return compLen;
}

size_t gzstreambuf::getCompressedPosition() {
    return compressed_position;
}

