// Helper function to read a byte from input buffer
inline void ReadInputByte(unsigned char& outputByte, bool& hasData, 
                          unsigned char* readBuffer, size_t& readStart, size_t& readEnd,
                          std::istream& inputStream) {
    if (hasData) {
        --hasData;
        if (readStart < readEnd) {
            outputByte = readBuffer[readStart++];
        } else {
            readEnd = inputStream.readsome(reinterpret_cast<char*>(readBuffer), sizeof(readBuffer));
            if (readEnd > 0) {
                outputByte = readBuffer[0];
                readStart = 1;
            } else {
                hasData = false;
            }
        }
    }
}

// Pull a byte into the bit accumulator
inline void AccumulateBits(unsigned int& holdValue, unsigned int& bitCount,
                          unsigned char* readBuffer, size_t& readStart, size_t& readEnd,
                          std::istream& inputStream, bool& hasData) {
    unsigned char nextByte;
    ReadInputByte(nextByte, hasData, readBuffer, readStart, readEnd, inputStream);
    holdValue += static_cast<unsigned int>(nextByte) << bitCount;
    bitCount += 8;
}

// Ensure there are at least n bits available in the accumulator
inline void EnsureBitsAvailable(unsigned int& holdValue, unsigned int& bitCount,
                               unsigned int requiredBits,
                               unsigned char* readBuffer, size_t& readStart, size_t& readEnd,
                               std::istream& inputStream, bool& hasData) {
    while (bitCount < requiredBits) {
        AccumulateBits(holdValue, bitCount, readBuffer, readStart, readEnd, inputStream, hasData);
    }
}

// Extract the low n bits from the accumulator
inline unsigned int GetLowBits(unsigned int holdValue, unsigned int bitCount, unsigned int numBits) {
    return (holdValue & ((1U << numBits) - 1));
}

// Remove n bits from the accumulator
inline void DiscardBits(unsigned int& holdValue, unsigned int& bitCount, unsigned int numBits) {
    holdValue >>= numBits;
    bitCount -= numBits;
}

// Read and extract n bits into output variable
inline void ReadBitsFromAccumulator(unsigned int& output, unsigned int& holdValue, 
                                   unsigned int& bitCount, unsigned int numBits,
                                   unsigned char* readBuffer, size_t& readStart, size_t& readEnd,
                                   std::istream& inputStream, bool& hasData) {
    EnsureBitsAvailable(holdValue, bitCount, numBits, readBuffer, readStart, readEnd, inputStream, hasData);
    output = GetLowBits(holdValue, bitCount, numBits);
    DiscardBits(holdValue, bitCount, numBits);
}

// Bit reversal lookup table for Shannon-Fano coding
static const unsigned char ReverseNibble[] = {
    0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
    0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
};

// Constants for tree structure
constexpr unsigned int TopLevelBits = 8;
constexpr unsigned int SubLevelBits = 4;

// Insert a code into the Huffman decoder table
void InsertHuffmanCode(std::vector<struct HuffmanNode>& decoderTable, 
                      unsigned int position, int currentBits, 
                      unsigned short codeValue, int remainingLength, 
                      unsigned char nodeValue) {
    assert(remainingLength > 0);

    unsigned int currentIndex = position + (codeValue & ((1 << currentBits) - 1));

    if (remainingLength > currentBits) {
        // Code requires deeper nesting
        unsigned int childIndex = decoderTable[currentIndex].ChildTable;

        if (childIndex == 0) {
            // Create new child table
            childIndex = InitializeDecoderTable(decoderTable, 1 << SubLevelBits);
            decoderTable[currentIndex].ChildTable = childIndex;
            decoderTable[currentIndex].Depth = currentBits;
            decoderTable[currentIndex].LeafValue = 0;
        } else {
            assert(decoderTable[currentIndex].Depth == currentBits);
            assert(decoderTable[currentIndex].LeafValue == 0);
        }

        InsertHuffmanCode(decoderTable, childIndex, SubLevelBits, 
                         codeValue >> currentBits, remainingLength - currentBits, nodeValue);
    } else {
        // Fill all permutations that match this prefix
        for (int i = (1 << (currentBits - remainingLength)); --i >= 0; ) {
            unsigned int targetIndex = currentIndex + (i << remainingLength);
            decoderTable[targetIndex].Depth = remainingLength;
            decoderTable[targetIndex].LeafValue = nodeValue;
            assert(decoderTable[targetIndex].ChildTable == 0);
        }
    }
}

// Initialize a new decoder table section
unsigned int InitializeDecoderTable(std::vector<HuffmanNode>& decoderTable, int tableSize) {
    size_t startIndex = decoderTable.size();
    decoderTable.resize(startIndex + tableSize);
    memset(&decoderTable[startIndex], 0, sizeof(HuffmanNode) * tableSize);
    return static_cast<unsigned int>(startIndex);
}

// Comparison function for sorting by length then value
int CompareHuffmanEntries(const void* first, const void* second) {
    const HuffmanEntry* entry1 = static_cast<const HuffmanEntry*>(first);
    const HuffmanEntry* entry2 = static_cast<const HuffmanEntry*>(second);

    int diff = entry1->CodeLength - entry2->CodeLength;
    if (diff == 0) {
        diff = entry1->SymbolValue - entry2->SymbolValue;
    }
    return diff;
}

// Build the Shannon-Fano decoder table from symbol data
int ConstructShannonFanoDecoder(std::vector<HuffmanNode>& decoderTable, 
                               HuffmanEntry* entries, int entryCount) {
    // Sort entries by length and value
    qsort(entries, entryCount, sizeof(HuffmanEntry), CompareHuffmanEntries);

    // Generate codes using Shannon-Fano algorithm
    unsigned short currentCode = 0;
    unsigned short codeIncrement = 0;
    unsigned short previousLength = 0;

    for (int i = entryCount - 1; i >= 0; --i) {
        currentCode += codeIncrement;

        if (entries[i].CodeLength != previousLength) {
            previousLength = entries[i].CodeLength;
            codeIncrement = 1 << (16 - previousLength);
        }

        // Reverse bits in the code
        entries[i].EncodedCode = ReverseNibble[currentCode >> 12] |
                                (ReverseNibble[(currentCode >> 8) & 0xF] << 4) |
                                (ReverseNibble[(currentCode >> 4) & 0xF] << 8) |
                                (ReverseNibble[currentCode & 0xF] << 12);
    }

    // Build the hierarchical decoder table
    InitializeDecoderTable(decoderTable, 1 << TopLevelBits);

    for (int i = 0; i < entryCount; ++i) {
        InsertHuffmanCode(decoderTable, 0, TopLevelBits, 
                         entries[i].EncodedCode, entries[i].CodeLength, 
                         entries[i].SymbolValue);
    }

    return 0;
}

// Decode a single value using the constructed decoder table
int DecodeShannonFanoValue(const std::vector<HuffmanNode>& decoderTable) {
    unsigned int lookupWidth = TopLevelBits;
    unsigned int tableOffset = 0;
    unsigned int codeValue;
    const HuffmanNode* currentNode;

    do {
        EnsureBitsAvailable(currentHold, currentBitCount, lookupWidth, 
                           readBuffer, readStart, readEnd, inputStream, hasData);
        codeValue = GetLowBits(currentHold, currentBitCount, lookupWidth);
        lookupWidth = SubLevelBits;
        currentNode = &decoderTable[tableOffset + codeValue];
        DiscardBits(currentHold, currentBitCount, currentNode->Depth);
        tableOffset = currentNode->ChildTable;
    } while (tableOffset != 0);

    return currentNode->LeafValue;
}

// Build decoder from compressed format
int BuildShannonFanoDecoder(std::vector<HuffmanNode>& decoderTable, 
                           int expectedSymbols) {
    HuffmanEntry builderTable[256];
    unsigned char tempByte, symbolCount;
    int index, count, symbolValue = 0;

    ReadInputByte(tempByte, hasData, readBuffer, readStart, readEnd, inputStream);
    count = tempByte + 1;

    for (index = 0; index < count; ++index) {
        int runLength, codeLength;
        ReadInputByte(tempByte, hasData, readBuffer, readStart, readEnd, inputStream);
        runLength = ((tempByte >> 4) & 0x0F) + 1;
        codeLength = (tempByte & 0x0F) + 1;

        while (runLength--) {
            builderTable[symbolValue].CodeLength = codeLength;
            builderTable[symbolValue].SymbolValue = symbolValue;
            symbolValue++;
        }
    }

    if (symbolValue != expectedSymbols) {
        return 1; // Invalid table
    }

    return ConstructShannonFanoDecoder(decoderTable, builderTable, symbolValue);
}

// Main decompression routine
int DecompressShannonFano(unsigned char* outputBuffer, unsigned int outputSize,
                         std::istream& inputStream, unsigned int inputSize,
                         int compressionFlags) {
    int currentByte, index, minMatchLength = 3, matchLength, distance;
    int lowDistanceBits;
    unsigned int outputIndex = 0;

    currentHold = 0;
    currentBitCount = 0;
    inputStreamPtr = &inputStream;
    remainingInput = inputSize;
    readStart = readEnd = 0;
    hasData = true;

    if (compressionFlags & 4) {
        minMatchLength = 3;
        if (BuildShannonFanoDecoder(literalDecoder, 256)) {
            return 1;
        }
    } else {
        minMatchLength = 2;
    }

    if (BuildShannonFanoDecoder(lengthDecoder, 64)) {
        return 1;
    }

    if (BuildShannonFanoDecoder(distanceDecoder, 64)) {
        return 1;
    }

    lowDistanceBits = (compressionFlags & 2) ? 7 : 6; // 8k or 4k dictionary

    while (outputIndex < outputSize) {
        ReadBitsFromAccumulator(currentByte, currentHold, currentBitCount, 1,
                               readBuffer, readStart, readEnd, inputStream, hasData);

        if (currentByte) {
            // Literal byte
            if (compressionFlags & 4) {
                currentByte = DecodeShannonFanoValue(literalDecoder);
            } else {
                ReadBitsFromAccumulator(currentByte, currentHold, currentBitCount, 8,
                                       readBuffer, readStart, readEnd, inputStream, hasData);
            }
            outputBuffer[outputIndex++] = static_cast<unsigned char>(currentByte);
        } else {
            // Match data
            ReadBitsFromAccumulator(distance, currentHold, currentBitCount, lowDistanceBits,
                                   readBuffer, readStart, readEnd, inputStream, hasData);
            currentByte = DecodeShannonFanoValue(distanceDecoder);
            distance |= (currentByte << lowDistanceBits);

            matchLength = DecodeShannonFanoValue(lengthDecoder);
            if (matchLength == 63) {
                ReadBitsFromAccumulator(currentByte, currentHold, currentBitCount, 8,
                                       readBuffer, readStart, readEnd, inputStream, hasData);
                matchLength += currentByte;
            }

            matchLength += minMatchLength;
            distance++;

            if (outputIndex + matchLength > outputSize) {
                return -1;
            }

            if (static_cast<unsigned int>(distance) > outputIndex) {
                // Handle zero-fill for initial matches
                int zeroCount = distance - outputIndex;
                if (matchLength < zeroCount) {
                    zeroCount = matchLength;
                }
                for (int i = 0; i < zeroCount; ++i) {
                    outputBuffer[outputIndex++] = 0;
                }
                matchLength -= zeroCount;
            }

            // Copy matched bytes
            for (int i = 0; i < matchLength; ++i, ++outputIndex) {
                outputBuffer[outputIndex] = outputBuffer[outputIndex - distance];
            }
        }
    }

    return 0;
}

