// Helper lambda to handle keyed mutex synchronization for shared texture access
auto AcquireAndCopySharedTexture = [](ID3D11Device* Device, ID3D11DeviceContext* Context,
                                      TComPtr<ID3D11Texture2D> const& SourceTex,
                                      ID3D11Resource* DestRes) -> bool
{
    LLM_SCOPE(ELLMTag::MediaStreaming);
    TComPtr<IDXGIResource> SharedResourceAsDXGI;
    if (FAILED(SourceTex->QueryInterface(__uuidof(IDXGIResource), (void**)&SharedResourceAsDXGI)))
        return false;

    HANDLE SharedHandle = nullptr;
    if (FAILED(SharedResourceAsDXGI->GetSharedHandle(&SharedHandle)) || !SharedHandle)
        return false;

    TComPtr<ID3D11Resource> OpenedSharedResource;
    if (FAILED(Device->OpenSharedResource(SharedHandle, __uuidof(ID3D11Texture2D), (void**)&OpenedSharedResource)))
        return false;

    TComPtr<IDXGIKeyedMutex> Mutex;
    if (FAILED(OpenedSharedResource->QueryInterface(_uuidof(IDXGIKeyedMutex), (void**)&Mutex)))
        return false;

    // Try acquiring key 1 first (new data ready); if not possible, wait for key 2 (data already copied)
    if (SUCCEEDED(Mutex->AcquireSync(1, 0)))
    {
        Context->CopyResource(DestRes, OpenedSharedResource.Get());
        Mutex->ReleaseSync(2);
        return true;
    }
    else if (SUCCEEDED(Mutex->AcquireSync(2, INFINITE)))
    {
        Mutex->ReleaseSync(2);
        return true;
    }

    return false;
};

struct FRHICommandCopyResource final : public FRHICommand<FRHICommandCopyResource>
{
	TComPtr<ID3D11Texture2D> SampleTexture;
	FTexture2DRHIRef SampleDestinationTexture;

	FRHICommandCopyResource(ID3D11Texture2D* InSampleTexture, FRHITexture2D* InSampleDestinationTexture)
		: SampleTexture(InSampleTexture)
		, SampleDestinationTexture(InSampleDestinationTexture)
	{
	}

	void Execute(FRHICommandListBase& CmdList) override
	{
		ID3D11Device* D3D11Device = static_cast<ID3D11Device*>(GDynamicRHI->RHIGetNativeDevice());
		ID3D11DeviceContext* ImmediateContext = nullptr;
		D3D11Device->GetImmediateContext(&ImmediateContext);

		if (ImmediateContext)
		{
			ID3D11Resource* DestinationResource = reinterpret_cast<ID3D11Resource*>(SampleDestinationTexture->GetNativeResource());
			if (DestinationResource)
			{
				(void)AcquireAndCopySharedTexture(D3D11Device, ImmediateContext, SampleTexture, DestinationResource);
			}
			ImmediateContext->Release();
		}
	}
};

bool FWmfMediaHardwareVideoDecodingParameters::ConvertTextureFormat_RenderThread(FWmfMediaHardwareVideoDecodingTextureSample* InSample, FTexture2DRHIRef InDstTexture)
{
	LLM_SCOPE(ELLMTag::MediaStreaming);
	if (!InSample || !InDstTexture.IsValid())
	{
		return false;
	}

	check(IsInRenderingThread());

	TComPtr<ID3D11Texture2D> SourceTexture = InSample->GetSourceTexture();
	ID3D11Device* D3DDevice = static_cast<ID3D11Device*>(GDynamicRHI->RHIGetNativeDevice());
	ID3D11DeviceContext* ImmediateCtx = nullptr;
	D3DDevice->GetImmediateContext(&ImmediateCtx);

	if (!ImmediateCtx)
	{
		return false;
	}

	FRHICommandListImmediate& RHICmdList = FRHICommandListExecutor::GetImmediateCommandList();
	SCOPED_DRAW_EVENT(RHICmdList, FWmfMediaHardwareVideoDecodingParameters_Convert);
	SCOPED_GPU_STAT(RHICmdList, MediaTextureConversion);

	FTexture2DRHIRef TargetTexture = InSample->GetOrCreateDestinationTexture();

	FRHIRenderPassInfo RPInfo(InDstTexture, ERenderTargetActions::DontLoad_Store);
	RHICmdList.BeginRenderPass(RPInfo, TEXT("ConvertTextureFormat"));

	RHICmdList.SetViewport(0, 0, 0.f, InSample->GetDim().X, InSample->GetDim().Y, 1.f);

	FGraphicsPipelineStateInitializer GraphicsPSOInit;
	RHICmdList.ApplyCachedRenderTargets(GraphicsPSOInit);
	GraphicsPSOInit.DepthStencilState = TStaticDepthStencilState<false, CF_Always>::GetRHI();
	GraphicsPSOInit.BlendState = TStaticBlendState<>::GetRHI();
	GraphicsPSOInit.RasterizerState = TStaticRasterizerState<>::GetRHI();
	GraphicsPSOInit.PrimitiveType = PT_TriangleList;
	GraphicsPSOInit.BoundShaderState.VertexDeclarationRHI = GetVertexDeclarationFVector4();

	if (RHICmdList.Bypass())
	{
		FRHICommandCopyResource Cmd(SourceTexture.Get(), TargetTexture.Get());
		Cmd.Execute(RHICmdList);
	}
	else
	{
		new (RHICmdList.AllocCommand<FRHICommandCopyResource>()) FRHICommandCopyResource(SourceTexture.Get(), TargetTexture.Get());
	}

	FGlobalShaderMap* ShaderMap = GetGlobalShaderMap(GMaxRHIFeatureLevel);

	switch (InSample->GetFormat())
	{
	case EMediaTextureSampleFormat::CharNV12:
	{
		TShaderMapRef< FHardwareVideoDecodingVS > VertexShader(ShaderMap);
		TShaderMapRef< FHardwareVideoDecodingPS > PixelShader(ShaderMap);
		GraphicsPSOInit.BoundShaderState.VertexShaderRHI = VertexShader.GetVertexShader();
		GraphicsPSOInit.BoundShaderState.PixelShaderRHI = PixelShader.GetPixelShader();
		SetGraphicsPipelineState(RHICmdList, GraphicsPSOInit);

		FShaderResourceViewRHIRef Y_SRV = RHICreateShaderResourceView(TargetTexture, 0, 1, PF_G8);
		FShaderResourceViewRHIRef UV_SRV = RHICreateShaderResourceView(TargetTexture, 0, 1, PF_R8G8);
		VertexShader->SetParameters(RHICmdList, VertexShader.GetVertexShader(), Y_SRV, UV_SRV, InSample->IsOutputSrgb());
		PixelShader->SetParameters(RHICmdList, PixelShader.GetPixelShader(), Y_SRV, UV_SRV, InSample->IsOutputSrgb());
		break;
	}
	case EMediaTextureSampleFormat::CharBGRA:
	{
		TShaderMapRef< FHardwareVideoDecodingVS > VertexShader(ShaderMap);
		TShaderMapRef< FHardwareVideoDecodingPassThroughPS > PixelShader(ShaderMap);
		GraphicsPSOInit.BoundShaderState.VertexShaderRHI = VertexShader.GetVertexShader();
		GraphicsPSOInit.BoundShaderState.PixelShaderRHI = PixelShader.GetPixelShader();
		SetGraphicsPipelineState(RHICmdList, GraphicsPSOInit);

		FShaderResourceViewRHIRef SRV = RHICreateShaderResourceView(TargetTexture, 0, 1, PF_B8G8R8A8);
		VertexShader->SetParameters(RHICmdList, VertexShader.GetVertexShader(), SRV, InSample->IsOutputSrgb());
		PixelShader->SetParameters(RHICmdList, PixelShader.GetPixelShader(), SRV, InSample->IsOutputSrgb());
		break;
	}
	case EMediaTextureSampleFormat::Y416:
	{
		TShaderMapRef< FHardwareVideoDecodingVS > VertexShader(ShaderMap);
		TShaderMapRef< FHardwareVideoDecodingY416PS > PixelShader(ShaderMap);
		GraphicsPSOInit.BoundShaderState.VertexShaderRHI = VertexShader.GetVertexShader();
		GraphicsPSOInit.BoundShaderState.PixelShaderRHI = PixelShader.GetPixelShader();
		SetGraphicsPipelineState(RHICmdList, GraphicsPSOInit);

		FShaderResourceViewRHIRef SRV = RHICreateShaderResourceView(TargetTexture, 0, 1, PF_A16B16G16R16);
		VertexShader->SetParameters(RHICmdList, VertexShader.GetVertexShader(), SRV, InSample->IsOutputSrgb());
		PixelShader->SetParameters(RHICmdList, PixelShader.GetPixelShader(), SRV, InSample->IsOutputSrgb());
		break;
	}
	default:
		break;
	}

	RHICmdList.DrawPrimitive(0, 2, 1);
	RHICmdList.EndRenderPass();
	ImmediateCtx->Release();

	return true;
}
