#include <jni.h>
#include <string>
#include <vector>
#include <thread>
#include <cstdlib>
#include <android/log.h>
#include <sys/mman.h>
#include <sys/prctl.h>

#define NOINLINE __attribute__((noinline))
#define LOG_TAG "NativeLeakTest"
#define THREAD_COUNT 10
#define LOOP_ITERATIONS 10
#define KB(val) ((val) * 1024L)
#define MB(val) (KB(val) * 1024L)
#define INFO(...) __android_log_print(ANDROID_LOG_INFO, LOG_TAG, __VA_ARGS__)

// Helper macro to conditionally log or free memory
template<typename T>
static inline void MaybeLogOrFree(T* ptr, int idx, const char* funcName, size_t actualSize = 0) {
    if (idx % 2 == 0) {
        free(ptr);
    } else {
        INFO("%s %p size %zu", funcName, ptr, actualSize ? actualSize : sizeof(*ptr));
    }
}

NOINLINE static void LeakMalloc() {
    for (int step = 0; step < LOOP_ITERATIONS; ++step) {
        size_t bytes = MB(std::rand() % 10);
        void* block = std::malloc(bytes);
        MaybeLogOrFree(block, step, __FUNCTION__, bytes);
    }
}

NOINLINE static void LeakRealloc() {
    for (int step = 0; step < LOOP_ITERATIONS; ++step) {
        size_t bytes = KB(std::rand() % 1000);
        void* block = std::realloc(nullptr, bytes);
        MaybeLogOrFree(block, step, __FUNCTION__, bytes);
    }
}

NOINLINE static void LeakCalloc() {
    for (int step = 0; step < LOOP_ITERATIONS; ++step) {
        size_t count = std::rand() % 1000;
        size_t elemSize = 8;
        void* block = std::calloc(count, elemSize);
        MaybeLogOrFree(block, step, __FUNCTION__, count * elemSize);
    }
}

NOINLINE static void LeakMemalign() {
    for (int step = 0; step < LOOP_ITERATIONS; ++step) {
        size_t bytes = KB(std::rand() % 1000);
        void* block = std::memalign(16, bytes);
        MaybeLogOrFree(block, step, __FUNCTION__, bytes);
    }
}

NOINLINE static void LeakNewString() {
    for (int step = 0; step < LOOP_ITERATIONS; ++step) {
        auto str = new std::string("test_leak_string");
        MaybeLogOrFree(str, step, __FUNCTION__, str->size());
    }
}

NOINLINE static void LeakNewArray() {
    for (int step = 0; step < LOOP_ITERATIONS; ++step) {
        size_t len = std::rand() % 1000;
        auto arr = new std::string[len];
        MaybeLogOrFree(arr, step, __FUNCTION__, len * sizeof(std::string));
    }
}

NOINLINE static void LeakContainer() {
    std::vector<std::string*> container;
    container.reserve(LOOP_ITERATIONS);
    for (int i = 0; i < LOOP_ITERATIONS; ++i) {
        container.emplace_back(new std::string("test_leak_container"));
    }
}

NOINLINE static jlong CreateJavaRefHolder() {
    void** holder = static_cast<void**>(std::malloc(sizeof(void*) * THREAD_COUNT));
    INFO("%s Holder addr %p", __FUNCTION__, holder);
    for (int i = 0; i < THREAD_COUNT; ++i) {
        size_t size = std::rand() % 1000;
        holder[i] = std::malloc(size);
        INFO("%s %p size %zu", __FUNCTION__, holder[i], size);
    }
    return reinterpret_cast<jlong>(holder);
}

extern "C" JNIEXPORT jlong JNICALL
Java_com_kwai_koom_demo_nativeleak_NativeLeakTest_triggerLeak(
    JNIEnv* env,
    jclass,
    jobject unused) {

    auto runAllTests = []() {
        LeakMalloc();
        LeakCalloc();
        LeakRealloc();
        LeakMemalign();
        LeakNewString();
        LeakNewArray();
        LeakContainer();
    };

    std::vector<std::thread> threads;
    threads.reserve(THREAD_COUNT);
    for (int t = 0; t < THREAD_COUNT; ++t) {
        threads.emplace_back(runAllTests);
        threads.back().detach();
    }

    return CreateJavaRefHolder();
}

#include "Core/Utils/FileLoader.hpp"
#include <algorithm>
#include <string>
#include <vector>
#include "Core/Utils/Utils.hpp"
#include "CoreConstants.hpp"

// Helper to extract module path from dot-separated name
static std::string ConvertModuleNameToPath(const std::string& moduleName) {
    std::string result = moduleName;
    std::replace(result.begin(), result.end(), '.', '/');
    return result;
}

// Helper to load and compile a script from a given path; returns true on success
static bool TryLoadAndCompile(lua_State* L, const std::string& path, const std::string& chunkName) {
    std::string content = Core::Utils::LoadFile(path);
    if (content.empty()) return false;
    return luaL_loadbuffer(L, content.c_str(), content.size(), chunkName.c_str()) == 0;
}

// Custom loadfile implementation
static int l_custom_loadfile(lua_State* L) {
    const char* filename = luaL_checkstring(L, 1);
    std::string rawFilename = filename;
    std::string scriptContent = Core::Utils::LoadFile(filename);

    if (scriptContent.empty()) {
        lua_pushfstring(L, "cannot open %s", filename);
        return lua_error(L);
    }

    // Strip known prefix for cleaner error/debug info
    std::string cleanFilename = rawFilename;
    Core::Utils::Replace(cleanFilename, PLUGIN_FOLDER "/", "");

    if (luaL_loadbuffer(L, scriptContent.c_str(), scriptContent.size(), cleanFilename.c_str()) != 0)
        return lua_error(L);

    return 1;
}

// Custom dofile implementation
static int l_custom_dofile(lua_State* L) {
    // Simulate loadfile + pcall + env setup
    lua_getglobal(L, "loadfile");
    lua_pushvalue(L, 1);

    if (lua_pcall(L, 1, 1, 0) != 0)
        return lua_error(L);

    if (!lua_isfunction(L, -1))
        return luaL_error(L, "Failed to load function");

    // Setup environment: try current stack frame first, fallback to globals
    lua_Debug ar;
    if (lua_getstack(L, 1, &ar) && lua_getinfo(L, "f", &ar)) {
        lua_getfenv(L, -1);
        lua_remove(L, -2); // remove function
    } else {
        lua_pushvalue(L, LUA_GLOBALSINDEX);
    }
    lua_setfenv(L, -2); // apply env to function

    // Execute the loaded function
    lua_remove(L, 1); // remove loadfile arg
    int initialTop = lua_gettop(L);
    if (lua_pcall(L, 0, LUA_MULTRET, 0) != 0)
        return lua_error(L);

    int finalTop = lua_gettop(L);
    return finalTop - initialTop + 1;
}

// Custom loader for require() — searches package.path
static int l_custom_loader(lua_State* L) {
    const char* moduleName = luaL_checkstring(L, 1);
    std::string modPath = ConvertModuleNameToPath(moduleName);

    // Retrieve package.path
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "path");
    const char* pathTemplate = lua_tostring(L, -1);
    lua_pop(L, 2); // pop path and package table

    if (!pathTemplate) {
        lua_pushstring(L, "package.path not set");
        return lua_error(L);
    }

    std::string paths(pathTemplate);
    std::vector<std::string> candidates;

    // Split paths by ';'
    size_t start = 0;
    for (size_t i = 0; i <= paths.size(); ++i) {
        if (i == paths.size() || paths[i] == ';') {
            candidates.push_back(paths.substr(start, i - start));
            start = i + 1;
        }
    }

    std::string errorMsg = "\n\tno file with name '" + std::string(moduleName) + "' found";
    for (const auto& tmpl : candidates) {
        std::string fullpath = tmpl;
        size_t qmark = fullpath.find('?');
        if (qmark != std::string::npos) {
            fullpath.replace(qmark, 1, modPath);
        }

        if (TryLoadAndCompile(L, fullpath, fullpath)) {
            return 1;
        }
    }

    lua_pushstring(L, errorMsg.c_str());
    return lua_error(L);
}

// Register custom file loading functions into Lua
bool Core::RegisterCustomFileLoader(lua_State* L) {
    // Replace global loadfile/dofile
    lua_pushcfunction(L, l_custom_loadfile);
    lua_setglobal(L, "loadfile");

    lua_pushcfunction(L, l_custom_dofile);
    lua_setglobal(L, "dofile");

    // Insert custom loader at front of package.loaders
    lua_getglobal(L, "package");
    lua_getfield(L, -1, "loaders");

    if (!lua_istable(L, -1)) {
        lua_pop(L, 2);
        return false;
    }

    // Shift existing loaders down and insert new one at index 1
    int len = lua_objlen(L, -1);
    for (int i = len; i >= 1; --i) {
        lua_rawgeti(L, -1, i);
        lua_rawseti(L, -2, i + 1);
    }

    lua_pushcfunction(L, l_custom_loader);
    lua_rawseti(L, -2, 1);

    lua_pop(L, 2); // pop loaders table and package table
    return true;
}

#include "ParseHelper.h"

namespace glslang {

//
// Visitor to detect modifications to the loop's induction variable.
//
class LoopModificationsChecker : public TIntermTraverser {
public:
    LoopModificationsChecker(long long varId, TSymbolTable& symTab)
        : targetVarId(varId), symbolTable(symTab), foundIssue(false) { }

    bool visitBinary(TVisit, TIntermBinary*) override;
    bool visitUnary(TVisit, TIntermUnary*) override;
    bool visitAggregate(TVisit, TIntermAggregate*) override;

    long long targetVarId;
    TSymbolTable& symbolTable;
    bool foundIssue;
    TSourceLoc issueLocation;
protected:
    LoopModificationsChecker(const LoopModificationsChecker&) = delete;
    LoopModificationsChecker& operator=(const LoopModificationsChecker&) = delete;
};

// Detect assignments or operations that modify the loop index in binary expressions
bool LoopModificationsChecker::visitBinary(TVisit /*unused*/, TIntermBinary* expr)
{
    if (expr->modifiesState()) {
        auto* leftSide = expr->getLeft()->getAsSymbolNode();
        if (leftSide && leftSide->getId() == targetVarId) {
            foundIssue = true;
            issueLocation = expr->getLoc();
        }
    }
    return true;
}

// Detect unary increments/decrements affecting the loop index
bool LoopModificationsChecker::visitUnary(TVisit /*unused*/, TIntermUnary* op)
{
    if (op->modifiesState()) {
        auto* operand = op->getOperand()->getAsSymbolNode();
        if (operand && operand->getId() == targetVarId) {
            foundIssue = true;
            issueLocation = op->getLoc();
        }
    }
    return true;
}

// Examine function calls for out/inout arguments referencing the loop index
bool LoopModificationsChecker::visitAggregate(TVisit /*unused*/, TIntermAggregate* call)
{
    if (call->getOp() == EOpFunctionCall) {
        const auto& params = call->getSequence();
        for (size_t idx = 0; idx < params.size(); ++idx) {
            auto* paramSym = params[idx]->getAsSymbolNode();
            if (paramSym && paramSym->getId() == targetVarId) {
                TSymbol* funcSym = symbolTable.find(call->getName());
                if (funcSym) {
                    const TType* argType = (*funcSym->getAsFunction())[static_cast<int>(idx)].type;
                    if (argType->getQualifier().storage == EvqOut ||
                        argType->getQualifier().storage == EvqInOut) {
                        foundIssue = true;
                        issueLocation = call->getLoc();
                    }
                }
            }
        }
    }
    return true;
}

//
// Public interface to check whether the loop body modifies its induction variable.
//
void TParseContext::inductiveLoopBodyCheck(TIntermNode* bodyStmt, long long loopVarId, TSymbolTable& symTab)
{
    LoopModificationsChecker checker(loopVarId, symTab);
    if (!bodyStmt)
        return;
    bodyStmt->traverse(&checker);
    if (checker.foundIssue)
        error(checker.issueLocation, "inductive loop index modified", "limitations", "");
}

//
// Visitor to verify that only allowed loop indices appear in index expressions.
//
class IndexExpressionValidator : public TIntermTraverser {
public:
    IndexExpressionValidator(const TIdSetType& validIds)
        : allowedIndices(validIds), hasInvalidIndex(false) { }

    void visitSymbol(TIntermSymbol*) override;
    bool visitAggregate(TVisit, TIntermAggregate*) override;

    const TIdSetType& allowedIndices;
    bool hasInvalidIndex;
    TSourceLoc invalidLocation;
protected:
    IndexExpressionValidator(const IndexExpressionValidator&) = delete;
    IndexExpressionValidator& operator=(const IndexExpressionValidator&) = delete;
};

// Ensure referenced symbols are known inductive loop variables
void IndexExpressionValidator::visitSymbol(TIntermSymbol* sym)
{
    if (allowedIndices.find(sym->getId()) == allowedIndices.end()) {
        hasInvalidIndex = true;
        invalidLocation = sym->getLoc();
    }
}

// Disallow function calls in index expressions (per spec constraints)
bool IndexExpressionValidator::visitAggregate(TVisit /*unused*/, TIntermAggregate* node)
{
    if (node->getOp() == EOpFunctionCall) {
        hasInvalidIndex = true;
        invalidLocation = node->getLoc();
    }
    return true;
}

//
// Public interface to validate constant-index-expression rules.
//
void TParseContext::constantIndexExpressionCheck(TIntermNode* indexExpr)
{
#ifndef GLSLANG_WEB
    IndexExpressionValidator validator(inductiveLoopIds);
    indexExpr->traverse(&validator);
    if (validator.hasInvalidIndex)
        error(validator.invalidLocation, "Non-constant-index-expression", "limitations", "");
#endif
}

