// Helper lambda to count LFS blocks during traversal
inline int _countLfsBlock(void* p, lfs_block_t block) {
    auto* counter = static_cast<lfs_size_t*>(p);
    ++(*counter);
    return 0;
}

lfs_ssize_t usedBlocks() {
    lfs_size_t count = 0;
    lfs_traverse(FS._getFS(), _countLfsBlock, &count);
    return static_cast<lfs_ssize_t>(count);
}

size_t usedBytes() {
    const auto* cfg = FS._getFS()->cfg;
    return cfg->block_size * static_cast<size_t>(usedBlocks());
}

size_t totalBytes() {
    const auto* cfg = FS._getFS()->cfg;
    return cfg->block_size * cfg->block_count;
}

