bool FileSystem::init() {
    TRACE("Initializing filesystem...");

    try {
        switch (FS_TYPE) {
            case FS_TYPE_SPIFFS: {
                INFO("SPIFFS mounting filesystem");
                if (!SPIFFS.begin(true, "")) {
                    ERROR("SPIFFS filesystem mount failed");
                    return false;
                }
                INFO("SPIFFS filesystem is ready");
                break;
            }
            case FS_TYPE_LITTLEFS: {
                INFO("LittleFS mounting filesystem");
                if (!LittleFS.begin(true, "")) {
                    ERROR("LittleFS filesystem mount failed");
                    return false;
                }
                DEBUG("LittleFS filesystem is ready");
                break;
            }
            case FS_TYPE_INTERNALFS: {
                INFO("InternalFS mounting filesystem");
                if (!InternalFS.begin()) {
                    ERROR("InternalFS filesystem mount failed");
                    return false;
                }
                INFO("InternalFS filesystem is ready");
                break;
            }
            case FS_TYPE_FLASHFS: {
                INFO("FlashFS mounting filesystem");
                if (!g_flash.begin(&g_RAK15001)) {
                    ERROR("FlashFS failed to initialize");
                    return false;
                }
                if (!FlashFS.begin(&g_flash)) {
                    ERROR("FlashFS filesystem mount failed");
                    return false;
                }
                break;
            }
            default:
                ERROR("Unsupported filesystem type");
                return false;
        }

        // Test write operation
        RNS::Bytes test("test");
        if (write_file("/test", test) < 4) {
            HEAD("Failed to write test file, filesystem is being reformatted...", RNS::LOG_CRITICAL);
            reformat();
        } else {
            remove_file("/test");
        }
    }
    catch (const std::exception& e) {
        //ERROR("FileSystem init Exception: " + std::string(e.what()));
        return false;
    }

    TRACE("Finished initializing");
    return true;
}

bool FileSystem::format() {
    INFO("Formatting filesystem...");
    try {
        if (!FS.format()) {
            ERROR("Format failed!");
            return false;
        }
        return true;
    }
    catch (const std::exception& e) {
        ERROR("FileSystem reformat Exception: " + std::string(e.what()));
    }
    return false;
}

bool FileSystem::reformat() {
    INFO("Reformatting filesystem...");
    try {
        RNS::Bytes preservedData[2];
        read_file("/eeprom", preservedData[0]);
        read_file("/transport_identity", preservedData[1]);

        if (!FS.format()) {
            ERROR("Format failed!");
            return false;
        }

        for (int i = 0; i < 2; ++i) {
            if (preservedData[i].size() > 0) {
                const char* paths[] = {"/eeprom", "/transport_identity"};
                write_file(paths[i], preservedData[i]);
            }
        }

        return true;
    }
    catch (const std::exception& e) {
        ERROR("FileSystem reformat Exception: " + std::string(e.what()));
    }
    return false;
}

#ifndef NDEBUG

void FileSystem::listDir(const char* dir, const char* prefix /*= ""*/) {
    Serial.print(prefix);
    std::string full_dir(dir);
    if (full_dir != "/") {
        full_dir += "/";
    }
    Serial.println(full_dir.c_str());

    std::string indent(prefix);
    indent.append("  ");

    try {
        File root = FS.open(dir);
        if (!root) {
            Serial.print(indent.c_str());
            Serial.println("(failed to open directory)");
            return;
        }

        File child = root.openNextFile();
        while (child) {
            const char* name = child.name();
            std::string next_path(full_dir);
            if (child.isDirectory()) {
                next_path += name;
                listDir(next_path.c_str(), indent.c_str());
            } else {
                Serial.print(indent.c_str());
                Serial.print(name);
                Serial.print(" (");
                Serial.print(child.size());
                Serial.println(" bytes)");
            }
            child.close();
            child = root.openNextFile();
        }
        root.close();
    }
    catch (const std::exception& e) {
        Serial.print("listDir Exception: ");
        Serial.println(e.what());
    }
}

void FileSystem::dumpDir(const char* dir) {
    Serial.print("DIR: ");
    std::string full_dir(dir);
    if (full_dir != "/") {
        full_dir += "/";
    }
    Serial.println(full_dir.c_str());

    try {
        File root = FS.open(dir);
        if (!root) {
            Serial.println("(failed to open directory)");
            return;
        }

        File child = root.openNextFile();
        while (child) {
            const char* name = child.name();
            if (child.isDirectory()) {
                std::string subpath(full_dir);
                subpath += name;
                dumpDir(subpath.c_str());
            } else {
                Serial.print("\nFILE: ");
                Serial.print(name);
                Serial.print(" (");
                Serial.print(child.size());
                Serial.print(" bytes)");

                char buffer[4096];
                size_t remaining = child.size();
                size_t chunk = std::min(remaining, sizeof(buffer));
                size_t totalRead = 0;

                while (chunk > 0 && totalRead < remaining) {
                    size_t readNow = child.readBytes(buffer, chunk);
                    Serial.write(buffer, readNow);
                    totalRead += readNow;
                    chunk = std::min(remaining - totalRead, sizeof(buffer));
                }
                Serial.println("");
            }
            child.close();
            child = root.openNextFile();
        }
        root.close();
    }
    catch (const std::exception& e) {
        Serial.print("dumpDir Exception: ");
        Serial.println(e.what());
    }
}
