/*virtual*/ bool FileSystem::file_exists(const char* file_path) {
    TRACEF("file_exists: checking for existence of file %s", file_path);
    return FS.exists(file_path);
}

/*virtual*/ size_t FileSystem::read_file(const char* file_path, RNS::Bytes& data) {
    TRACEF("read_file: reading from file %s", file_path);
    size_t bytesRead = 0;

#if FS_TYPE == FS_TYPE_INTERNALFS || FS_TYPE == FS_TYPE_FLASHFS
    File file(FS);
    if (file.open(file_path, FILE_O_READ)) {
#else
    File file = FS.open(file_path, FILE_READ);
    if (file) {
#endif
        size_t expectedSize = file.size();
        bytesRead = file.readBytes(reinterpret_cast<char*>(data.writable(expectedSize)), expectedSize);
        TRACEF("read_file: read %u bytes from file %s", bytesRead, file_path);

        if (bytesRead != expectedSize) {
            ERRORF("read_file: failed to read file %s", file_path);
            data.resize(bytesRead);
        }
        file.close();
    } else {
        ERRORF("read_file: failed to open input file %s", file_path);
    }

    return bytesRead;
}

/*virtual*/ size_t FileSystem::write_file(const char* file_path, const RNS::Bytes& data) {
    TRACEF("write_file: writing to file %s", file_path);

    if (FS.exists(file_path)) {
        FS.remove(file_path);
    }

    size_t bytesWritten = 0;

#if FS_TYPE == FS_TYPE_INTERNALFS || FS_TYPE == FS_TYPE_FLASHFS
    File file(FS);
    if (file.open(file_path, FILE_O_WRITE)) {
#else
    File file = FS.open(file_path, FILE_WRITE);
    if (file) {
#endif
        bytesWritten = file.write(data.data(), data.size());
        TRACEF("write_file: wrote %u bytes to file %s", bytesWritten, file_path);

        if (bytesWritten < data.size()) {
            WARNINGF("write_file: not all data was written to file %s", file_path);
        }
        file.close();
    } else {
        ERRORF("write_file: failed to open output file %s", file_path);
    }

    return bytesWritten;
}

/*virtual*/ RNS::FileStream FileSystem::open_file(const char* file_path, RNS::FileStream::MODE file_mode) {
    TRACEF("open_file: opening file %s", file_path);

#if FS_TYPE == FS_TYPE_INTERNALFS || FS_TYPE == FS_TYPE_FLASHFS
    int mode;
    switch (file_mode) {
        case RNS::FileStream::MODE_READ:
            mode = FILE_O_READ;
            break;
        case RNS::FileStream::MODE_WRITE:
            mode = FILE_O_WRITE;
            if (FS.exists(file_path)) FS.remove(file_path);
            break;
        case RNS::FileStream::MODE_APPEND:
            mode = FILE_O_WRITE;
            break;
        default:
            ERRORF("open_file: unsupported mode %d", file_mode);
            return {RNS::Type::NONE};
    }

    File* fptr = new File(FS);
    if (!fptr->open(file_path, mode)) {
        delete fptr;
        ERRORF("open_file: failed to open output file %s", file_path);
        return {RNS::Type::NONE};
    }

    TRACEF("open_file: successfully opened file %s", file_path);
    return RNS::FileStream(new FileStream(fptr));

#else
    const char* modeStr;
    switch (file_mode) {
        case RNS::FileStream::MODE_READ:
            modeStr = FILE_READ;
            break;
        case RNS::FileStream::MODE_WRITE:
            modeStr = FILE_WRITE;
            break;
        case RNS::FileStream::MODE_APPEND:
            modeStr = FILE_APPEND;
            break;
        default:
            ERRORF("open_file: unsupported mode %d", file_mode);
            return {RNS::Type::NONE};
    }

    TRACEF("open_file: opening file %s in mode %s", file_path, modeStr);

    File base = FS.open(file_path, modeStr);
    if (!base) {
        ERRORF("open_file: failed to open output file %s", file_path);
        return {RNS::Type::NONE};
    }

    File* fptr = new File(base);
    if (!fptr || !(*fptr)) {
        delete fptr;
        ERRORF("open_file: failed to open output file %s", file_path);
        return {RNS::Type::NONE};
    }

    TRACEF("open_file: successfully opened file %s", file_path);
    return RNS::FileStream(new FileStream(fptr));
#endif
}

