// AutoSensor: handles multiple sources with priority
AutoSensor::AutoSensor() {
    memset(values, 0, sizeof(values));
}

void AutoSensor::update(const double value, const Source src) {
    if ((this->source == SOURCE_AUTO) && (src != SOURCE_NA)) {
        if (value != values[src]) {
            Sensor::update(value, this->source);
            values[src] = value;
        }
    }
    else
        Sensor::update(value, src);
}

// Outside temperature via OpenWeatherMap
OutsideTemp::OutsideTemp():
        nextUpdate(0),
        httpState(HTTP_IDLE) {
    client.onData([this](void *, AsyncClient *, void *data, size_t len) {
        buffer += String((char*) data, len);
    });
    client.onDisconnect([](void *, AsyncClient *) {
        // ignore
    });
    client.onError([](void *, AsyncClient *, int8_t) {
        // ignore
    });
}

void OutsideTemp::configure(JsonObject &config) {
    Sensor::configure(config);
    latitude = config[F("lat")];
    longitude = config[F("lon")];
    apiKey = config[F("apikey")].as<String>();
    period = (uint16_t) config[F("interval")] * 1000;
    if (period == 0)
        period = 30000;
    owStatus.clear();
    nextUpdate = 0;
}

void OutsideTemp::tick() {
    if (source != SOURCE_OPENWEATHER)
        return;
    switch (httpState) {
    case HTTP_IDLE:
        if (millis() > nextUpdate) {
            client.connect("api.openweathermap.org", 80);
            httpState = HTTP_CONNECTING;
            nextUpdate = millis() + 5000;
        }
        break;

    case HTTP_CONNECTING:
        if (client.connected()) {
            httpState = HTTP_RECEIVING;
            String request = "GET /data/2.5/weather/?units=metric";
            request += "&lat=" + String(latitude);
            request += "&lon=" + String(longitude);
            request += "&appid=" + apiKey + "\r\n\r\n";
            buffer.clear();
            client.write(request.c_str());
            nextUpdate = millis() + 5000;
        }
        else {
            if (millis() > nextUpdate) {
                nextUpdate = millis() + period;
                client.close(true);
                httpState = HTTP_IDLE;
            }
        }
        break;
    case HTTP_RECEIVING: {
        if (millis() > nextUpdate)
            client.close();
        if (!client.connected()) {
            JsonDocument doc;
            owStatus.clear();

            if (deserializeJson(doc, buffer) == DeserializationError::Ok) {
                if (doc[F("main")][F("temp")].is<JsonFloat>()) {
                    value = doc[F("main")][F("temp")];
                    updated = true;
                    owStatus = F("Ok");
                }
                else
                    updated = false;
            }
            if (owStatus.isEmpty())
                owStatus = buffer;
            buffer.clear();
            nextUpdate = millis() + period;
            httpState = HTTP_IDLE;
        }
        break;
    }
    default:
        break;
    }
}

// Addressable sensors base class
AddressableSensor::AddressableSensor(const uint8_t *address, const uint8_t len, AddressableSensor **prev):
        next(*prev) {
    *prev = this;
    addressLength = len;
    memcpy(addressBuffer, address, len);
}

void AddressableSensor::init() {
    mutex = xSemaphoreCreateMutex();
}

String AddressableSensor::getAddress() const {
    String result;
    for (uint8_t i=0; i<addressLength; i++) {
        if (addressBuffer[i] < 0x10)
            result += '0';
        result += String(addressBuffer[i], 16);
    }
    return result;
}

AddressableSensor* AddressableSensor::locate(String addr, AddressableSensor *start) {
    AddressableSensor *node = start;
    while (node) {
        if (node->getAddress() == addr)
            break;
        node = node->next;
    }
    return node;
}

void AddressableSensor::writeAllToJson(JsonObject &status, AddressableSensor *head) {
    BusGuard guard;
    if (!guard)
        return;
    AddressableSensor *node = head;
    while (node) {
        String addrStr = node->getAddress();
        JsonVariant var = status[addrStr].to<JsonVariant>();
        node->toJson(var);            
        node = node->next;
    }
}

bool AddressableSensor::publishDiscoveryAll(AddressableSensor *head) {
    BusGuard guard;
    if (!guard)
        return false;
    bool success = true;

    AddressableSensor *node = head;
    while (node) {
        success &= node->publishDiscovery();  
        node = node->next;
    }
    return success;
}

// 1-Wire sensor node
OneWireNode::OneWireNode(uint8_t *addr):
        AddressableSensor(addr, 8, (AddressableSensor**) &tail) {
    temp = DEVICE_DISCONNECTED_C;
}

void OneWireNode::init() {
    bus.reset_search();
    uint8_t addr[8];
    while (bus.search(addr))
        new OneWireNode(addr);
    tick();
}

void OneWireNode::tick() {
    static uint32_t nextTick = 0;
    if (millis() > nextTick) {
        OneWireNode *node = tail;
        DallasTemperature ds(&bus);
        ds.requestTemperatures();
        while (node) {
            node->temp = round(ds.getTempC(node->adr) * 10) / 10;
            if (node->temp != DEVICE_DISCONNECTED_C) {
                for (int i=0; i<sizeof(roomTemperature) / sizeof(roomTemperature[0]); i++) {
                    if (roomTemperature[i].ownNode == node)
                        roomTemperature[i].set(node->temp, Sensor::SOURCE_1WIRE);
                }
                if (ambientTemp.ownNode == node)
                    ambientTemp.set(node->temp, Sensor::SOURCE_1WIRE);
            }
            node = static_cast<OneWireNode*>(node->next);
        }
        nextTick = millis() + 5000;
    }
}

void OneWireNode::toJson(JsonVariant val) {
    if (this->temp != DEVICE_DISCONNECTED_C)
        val.set(this->temp);
    else
        val.set(nullptr);
}

OneWireNode *OneWireNode::locate(String addr) {
    return static_cast<OneWireNode*>(AddressableSensor::locate(addr, tail));
}

bool OneWireNode::publishDiscoveryAll() {
    return AddressableSensor::publishDiscoveryAll(tail);
}

bool OneWireNode::publishDiscovery() {
    String id = F("1w_");
    id += getAddress();
    String name = F("1wire ");
    name += getAddress();
    haDisc.createTempSensor(name, id);
    String path = F("{{ value_json['1wire']['");
    path += getAddress();
    path += F("'] }}");
    haDisc.setValueTemplate(path);
    return haDisc.publish();
}

void OneWireNode::writeAllToJson(JsonObject &status) {
    AddressableSensor::writeAllToJson(status, tail);
}

