    scanner->setMaxResults(0);
    scanner->setInterval(160);
    scanner->setWindow(80);
    scanner->start(0, false, true);
}

void BLESensor::onDiscover(const NimBLEAdvertisedDevice* dev) {
    auto srvdata = dev->getServiceData(NimBLEUUID("fcd2"));
    if (srvdata.length() == 0)
        return;
    if (srvdata[0] != 0x40)
        return;
    BusGuard guard;
    if (!guard)
        return;
    BLESensor *sensor = locate(dev->getAddress().getVal());
    if (sensor == nullptr) {
        sensor = new BLESensor(dev->getAddress().getVal());
        sensor->publishDiscovery();
    }

    sensor->decode(srvdata);
    sensor->rssi = dev->getRSSI();
}

void BLESensor::decode(std::string &data) {
    size_t pos = 1;
    while (pos < data.length()) {
        switch (data[pos++]) {
        case 0x00:
            // packet ID
            pos++;
            break;
        case 0x01:
            battery = data[pos++];
            break;
        case 0x02: {
            int16_t raw = ((data[pos] | (data[pos+1] << 8)) + 5) / 10;
            temp = raw / 10.0;
            pos += 2;
            break;
        }
        case 0x03: {
            rh = (data[pos] | (data[pos+1] << 8)) / 100;
            pos += 2;
            break;
        }
        case 0x0C: {
            //uint16_t v = data[pos] | (data[pos+1] << 8);
            pos += 2;
            break;
        }
        default:
            return;
        }
    }
}

BLESensor* BLESensor::locate(const uint8_t *adr) {
    BLESensor *node = latest;
    while (node) {
        if (memcmp(adr, node->adr, 6) == 0)
            return node;
        node = static_cast<BLESensor*>(node->next);
    }
    return nullptr;
}

void BLESensor::writeAllToJson(JsonObject &status) {
    AddressableSensor::writeAllToJson(status, latest);
}

void BLESensor::toJson(JsonVariant val) {
    JsonObject obj = val.to<JsonObject>();
    obj[F("temp")] = this->temp;
    obj[F("rh")] = this->rh;
    obj[F("bat")] = this->battery;
    obj[F("rssi")] = this->rssi;
}

bool BLESensor::publishDiscoveryAll() {
    return AddressableSensor::publishDiscoveryAll(latest);
}

bool BLESensor::publishDiscovery() {
    bool ok = true;
    String pathBase = F("{{ value_json['BLE']['");
    pathBase += getAddress();
    pathBase += F("']['?'] }}");
    String id = F("ble_t_");
    id += getAddress();
    haDisc.createTempSensor(F("BLE temp"), id);
    String path = pathBase;
    path.replace("?", F("temp"));
    haDisc.setValueTemplate(path);
    ok &= haDisc.publish();
    id = F("ble_rh_");
    id += getAddress();
    haDisc.createSensor(F("BLE RH"), id);
    haDisc.setDeviceClass(F("humidity"));
    haDisc.setUnit(F("%"));
    path = pathBase;
    path.replace("?", F("rh"));
    haDisc.setValueTemplate(path);
    ok &= haDisc.publish();
    id = F("ble_bat_");
    id += getAddress();
    haDisc.createSensor(F("BLE bat."), id);
    haDisc.setDeviceClass(F("battery"));
    haDisc.setUnit(F("%"));
    path = pathBase;
    path.replace("?", F("bat"));
    haDisc.setValueTemplate(path);
    ok &= haDisc.publish();
    id = F("ble_rssi_");
    id += getAddress();
    haDisc.createSensor(F("BLE RSSI"), id);
    haDisc.setDeviceClass(F("signal_strength"));
    haDisc.setUnit(F("dBm"));
    path = pathBase;
    path.replace("?", F("rssi"));
    haDisc.setValueTemplate(path);
    ok &= haDisc.publish();
    return ok;
}

