// Intersect multiple edge sets by projecting edges to (src, dst) pairs and computing intersection
std::unordered_set<std::pair<int, int>, IntPairHasher> intersectResults(
    const std::vector<std::unordered_set<Edge, EdgeHasher>> &edgeSets) {
  if (edgeSets.empty()) return {};

  std::unordered_set<std::pair<int, int>, IntPairHasher> commonPairs;
  for (const auto& e : edgeSets[0]) {
    int src = std::get<0>(e);
    int dst = std::get<2>(e);
    if (src != dst) {
      commonPairs.emplace(src, dst);
    }
  }

  for (size_t idx = 1; idx < edgeSets.size(); ++idx) {
    std::unordered_set<std::pair<int, int>, IntPairHasher> temp;
    for (const auto& e : edgeSets[idx]) {
      int src = std::get<0>(e);
      int dst = std::get<2>(e);
      if (commonPairs.count({src, dst})) {
        temp.emplace(src, dst);
      }
    }
    commonPairs = std::move(temp);
  }

  return commonPairs;
}

// Assign unique integer IDs to symbol/node names in order of first appearance
std::unordered_map<std::string, int>
assignIndices(const std::vector<std::string>& identifiers) {
  std::unordered_map<std::string, int> mapping;
  int nextId = 0;
  for (const auto& id : identifiers) {
    if (mapping.find(id) == mapping.end()) {
      mapping[id] = nextId++;
    }
  }
  return mapping;
}

// Invert a map: key ↔ value
template <typename K, typename V>
std::unordered_map<V, K> invertMap(const std::unordered_map<K, V>& original) {
  std::unordered_map<V, K> inverted;
  for (const auto& [key, val] : original) {
    inverted[val] = key;
  }
  return inverted;
}

// Parse raw grammars from file format: { ... | production ... }
std::vector<std::vector<std::vector<std::string>>>
parseRawGrammars(const std::string& filename) {
  std::ifstream input(filename);
  std::vector<std::vector<std::vector<std::string>>> allGrammars;
  std::vector<std::vector<std::string>> currentGrammar;

  std::string line;
  while (std::getline(input, line)) {
    if (line.empty()) continue;

    if (line.front() == '{') {
      currentGrammar.clear();
    } else if (line.front() == '|') {
      std::istringstream stream(line.substr(1));
      std::vector<std::string> tokens;
      std::string token;
      while (stream >> token) {
        tokens.push_back(std::move(token));
      }
      currentGrammar.push_back(std::move(tokens));
    } else if (line.front() == '}') {
      allGrammars.push_back(std::move(currentGrammar));
    }
  }

  return allGrammars;
}

// Parse raw graph from DOT-like format: node1 -> node2 [label="label"]
std::vector<std::tuple<std::string, std::string, std::string>>
parseRawGraph(const std::string& filename) {
  std::ifstream input(filename);
  std::vector<std::tuple<std::string, std::string, std::string>> edges;

  std::string line;
  while (std::getline(input, line)) {
    size_t arrowPos = line.find("->");
    if (arrowPos == std::string::npos) continue;

    size_t bracketStart = line.find('[');
    size_t eqPos = line.find('=');
    size_t bracketEnd = line.find(']', eqPos);

    std::string src = line.substr(0, arrowPos - 1);
    std::string label = line.substr(eqPos + 2, bracketEnd - eqPos - 3);
    std::string dst = line.substr(arrowPos + 2, bracketStart - arrowPos - 3);

    edges.emplace_back(src, label, dst);
  }

  return edges;
}

// Encode raw grammars and graph into internal representation
std::tuple<std::vector<Grammar>, size_t, std::unordered_set<Edge, EdgeHasher>>
encodeData(
    std::vector<std::vector<std::vector<std::string>>> rawGrammars,
    std::vector<std::tuple<std::string, std::string, std::string>> rawEdges) {

  // Collect all symbols for encoding
  std::vector<std::string> allSymbols;
  for (const auto& grammar : rawGrammars) {
    for (const auto& rule : grammar) {
      for (const auto& sym : rule) {
        allSymbols.push_back(sym);
      }
    }
  }

  auto symbolToIndex = assignIndices(allSymbols);
  auto indexToSymbol = invertMap(symbolToIndex);

  // Collect all nodes for encoding
  std::vector<std::string> allNodes;
  for (const auto& [u, _, v] : rawEdges) {
    allNodes.push_back(u);
    allNodes.push_back(v);
  }

  auto nodeToIndex = assignIndices(allNodes);
  auto indexToNode = invertMap(nodeToIndex);

  // Build grammars
  std::vector<Grammar> grammars;
  for (auto& rawGrammar : rawGrammars) {
    Grammar gm;

    // Classify terminals/nonterminals
    for (const auto& rule : rawGrammar) {
      for (const auto& sym : rule) {
        char firstChar = sym[0];
        if (isupper(firstChar)) {
          gm.addNonterminal(symbolToIndex[sym]);
        } else {
          assert(islower(firstChar));
          gm.addTerminal(symbolToIndex[sym]);
        }
      }
    }

    // Add productions
    for (size_t i = 1; i < rawGrammar.size(); ++i) {
      const auto& prod = rawGrammar[i];
      if (prod.size() == 1) {
        gm.addEmptyProduction(symbolToIndex[prod[0]]);
      } else if (prod.size() == 2) {
        gm.addUnaryProduction(symbolToIndex[prod[0]], symbolToIndex[prod[1]]);
      } else {
        assert(prod.size() == 3);
        gm.addBinaryProduction(symbolToIndex[prod[0]],
                               symbolToIndex[prod[1]],
                               symbolToIndex[prod[2]]);
      }
    }

    gm.addStartSymbol(symbolToIndex[rawGrammar[0][0]]);
    gm.initFastIndices();
    grammars.push_back(std::move(gm));
  }

  // Build encoded edge set
  std::unordered_set<Edge, EdgeHasher> encodedEdges;
  for (const auto& [u, label, v] : rawEdges) {
    encodedEdges.emplace(nodeToIndex[u], symbolToIndex[label], nodeToIndex[v]);
  }

  return std::make_tuple(std::move(grammars), nodeToIndex.size(), std::move(encodedEdges));
}

// Main execution logic
void execute(int argc, char* argv[]) {
  if (argc != 4) {
    std::cerr << "Usage: " << argv[0]
              << " <grammar-file> <graph-file> <\"naive\"|\"refine\">\n";
    return;
  }

  std::string grammarPath = argv[1];
  std::string graphPath = argv[2];
  std::string mode = argv[3];

  auto [grammars, numNodes, initialEdges] =
      encodeData(parseRawGrammars(grammarPath), parseRawGraph(graphPath));

  size_t grammarCount = grammars.size();

  if (mode == "naive") {
    std::vector<Graph> graphs(grammarCount);
    std::vector<std::unordered_set<Edge, EdgeHasher>> results(grammarCount);

    for (size_t i = 0; i < grammarCount; ++i) {
      graphs[i].reinit(numNodes, initialEdges);
      results[i] = graphs[i].runCFLReachability(grammars[i]);
    }

    std::cout << "Number of Reachable Pairs (Excluding Self-loops): "
              << intersectResults(results).size() << '\n';

  } else if (mode == "refine") {
    std::unordered_set<Edge, EdgeHasher> activeEdgeSet = initialEdges;
    size_t initialSize = activeEdgeSet.size();
    size_t prevSize = 0;
    std::vector<Graph> graphs(grammarCount);
    std::vector<std::unordered_set<Edge, EdgeHasher>> results(grammarCount);
    size_t iterations = 0;

    do {
      prevSize = activeEdgeSet.size();
      for (size_t i = 0; i < grammarCount; ++i) {
        graphs[i].reinit(numNodes, activeEdgeSet);
        std::unordered_map<Edge, std::unordered_set<int>, EdgeHasher> unaryMap;
        std::unordered_map<Edge, std::unordered_set<std::tuple<int,int,int>, IntTripleHasher>, EdgeHasher> binaryMap;

        results[i] = graphs[i].runCFLReachability(grammars[i], unaryMap, binaryMap);
        activeEdgeSet = graphs[i].getEdgeClosure(grammars[i], results[i], unaryMap, binaryMap);
      }
      ++iterations;
    } while (activeEdgeSet.size() != prevSize);

    std::cout << "Edge Set Reduction: " << initialSize << " -> " << activeEdgeSet.size() << '\n';
    std::cout << "Refinement Iterations: " << iterations << '\n';
    std::cout << "Number of Reachable Pairs (Excluding Self-loops): "
              << intersectResults(results).size() << '\n';
  }
}

// Extract peak memory usage from /proc/self/status
std::string fetchPeakMemory() {
  std::ifstream status("/proc/self/status");
  std::string line;
  std::string peakValue;

  while (std::getline(status, line)) {
    std::istringstream iss(line);
    std::string tag;
    if ((iss >> tag) && tag == "VmPeak:") {
      iss >> peakValue;
      break;
    }
  }

  return peakValue;
}

// Entry point with timing and resource reporting
int mutual_refinement_main(int argc, char* argv[]) {
  auto startTime = std::chrono::steady_clock::now();
  execute(argc, argv);
  auto endTime = std::chrono::steady_clock::now();

  double elapsed = std::chrono::duration<double>(endTime - startTime).count();
  std::cout << "*** Resource Consumption ***\n"
            << "Total Time (Seconds): " << elapsed << '\n'
            << "Peak Space (kB): " << fetchPeakMemory() << '\n';

  return 0;
}

#include <iostream>
#include <cmath>

// Custom namespace for utility functions
namespace helpers {
    // Compute greatest common divisor using Euclidean algorithm
    int computeGCD(int x, int y) {
        while (y != 0) {
            int temp = y;
            y = x % y;
            x = temp;
        }
        return std::abs(x);
    }
}

// Structure to represent a rational number
struct Fraction {
    int top;      // numerator
    int bottom;   // denominator
};

// Normalize the fraction by reducing to lowest terms
void simplifyFraction(Fraction& frac) {
    if (frac.bottom == 0) return;

    int common = helpers::computeGCD(frac.top, frac.bottom);
    frac.top /= common;
    frac.bottom /= common;

    // Ensure denominator is positive
    if (frac.bottom < 0) {
        frac.top = -frac.top;
        frac.bottom = -frac.bottom;
    }
}

// Add two fractions
Fraction sumFractions(const Fraction& f1, const Fraction& f2) {
    Fraction result;
    result.bottom = f1.bottom * f2.bottom;
    result.top = f1.top * f2.bottom + f1.bottom * f2.top;
    simplifyFraction(result);
    return result;
}

// Subtract two fractions
Fraction differenceFractions(const Fraction& f1, const Fraction& f2) {
    Fraction result;
    result.bottom = f1.bottom * f2.bottom;
    result.top = f1.top * f2.bottom - f1.bottom * f2.top;
    simplifyFraction(result);
    return result;
}

// Multiply two fractions
Fraction productFractions(const Fraction& f1, const Fraction& f2) {
    Fraction result;
    result.top = f1.top * f2.top;
    result.bottom = f1.bottom * f2.bottom;
    simplifyFraction(result);
    return result;
}

// Divide two fractions
Fraction quotientFractions(const Fraction& f1, const Fraction& f2) {
    // Check for division by zero
    if (f2.top == 0) {
        return {0, 1};  // Return zero as default
    }

    Fraction reciprocal = {f2.bottom, f2.top};
    return productFractions(f1, reciprocal);
}

// Validate that denominator is non-zero
bool checkValidFraction(const Fraction& frac) {
    return frac.bottom != 0;
}

// Check if the fraction represents a whole number
bool isInteger(const Fraction& frac) {
    return frac.bottom != 0 && (frac.top % frac.bottom == 0);
}

// Display a fraction in formatted way
void showFraction(const Fraction& frac) {
    bool negTop = frac.top < 0;
    bool negBottom = frac.bottom < 0;
    bool isNegative = (negTop ^ negBottom);  // XOR: true if exactly one is negative

    int absTop = std::abs(frac.top);
    int absBottom = std::abs(frac.bottom);

    if (isNegative) {
        std::cout << "-(" << absTop << "/" << absBottom << ")\n";
    } else {
        std::cout << absTop << "/" << absBottom << "\n";
    }
}

int main() {
    Fraction first{1, 2};
    Fraction second{3, 4};

    showFraction(sumFractions(first, second));       // 5/4
    showFraction(differenceFractions(first, second)); // -(1/4)
    showFraction(productFractions(first, second));   // 3/8
    showFraction(quotientFractions(first, second));  // 2/3
    showFraction({-1, -2});                          // 1/2

    return 0;
}

#include "wndproc.hpp"

// Static instance pointer for singleton-like access
memory::hooks::WndProc* memory::hooks::WndProc::_instance = nullptr;

// Constructor: registers current instance and stores window handle
memory::hooks::WndProc::WndProc(HWND windowHandle) : Hook("WndProc", nullptr, nullptr, nullptr)
{
    _instance = this;
    _windowHandle = windowHandle;
}

// Destructor: disables hook and clears static instance if needed
memory::hooks::WndProc::~WndProc()
{
    deactivate(false);
    if (_instance == this)
    {
        _instance = nullptr;
    }
}

// Activates the hook by replacing the window procedure
bool memory::hooks::WndProc::activate()
{
    WNDPROC prevProc = reinterpret_cast<WNDPROC>(
        SetWindowLongPtr(
            _windowHandle,
            GWLP_WNDPROC,
            reinterpret_cast<LONG_PTR>(hookEntry)
        )
    );

    if (!prevProc)
    {
        return false;
    }

    _originalProc = prevProc;
    return true;
}

// Deactivates the hook by restoring the original window procedure
bool memory::hooks::WndProc::deactivate(bool cleanup)
{
    SetWindowLongPtr(_windowHandle, GWLP_WNDPROC, reinterpret_cast<LONG_PTR>(_originalProc));
    return true;
}

// Registers a new callback function to be invoked on message processing
void memory::hooks::WndProc::registerHandler(const std::function<uintptr_t(HWND, UINT, WPARAM, LPARAM)>& handler)
{
    _handlers.emplace_back(handler);
}

// Core logic: invokes all registered handlers; decides whether to forward to original proc
LRESULT memory::hooks::WndProc::processMessage(HWND hwnd, const UINT message, const WPARAM wparam, const LPARAM lparam) const
{
    bool proceedWithDefault = true;

    for (const auto& handler : _handlers)
    {
        if (handler(hwnd, message, wparam, lparam) == 0)
        {
            proceedWithDefault = false;
        }
    }

    if (!proceedWithDefault)
    {
        return 0;
    }

    return CallWindowProc(_originalProc, hwnd, message, wparam, lparam);
}

// Entry point called by Windows when a message arrives
LRESULT memory::hooks::WndProc::hookEntry(HWND hwnd, const UINT msg, const WPARAM wParam, const LPARAM lParam)
{
    if (!_instance)
    {
        return 0;
    }

    return _instance->processMessage(hwnd, msg, wParam, lParam);
}

