std::vector<std::string> StrUtils::readFile(std::istream& is, char comment) {
    std::vector<std::string> result;
    std::string currentLine;

    // Read lines until EOF
    while (is.good() && !is.eof()) {
        if (std::getline(is, currentLine)) {
            // Remove comment portion if present
            std::size_t commentPos = currentLine.find(comment);
            if (commentPos != std::string::npos) {
                currentLine = currentLine.substr(0, commentPos);
            }

            // Trim trailing whitespace
            while (!currentLine.empty() && 
                   (currentLine.back() == ' ' || currentLine.back() == '\t' || 
                    currentLine.back() == '\r')) {
                currentLine.pop_back();
            }

            // Add non-empty lines
            if (!currentLine.empty()) {
                result.push_back(currentLine);
            }
        }
    }

    return result;
}

std::vector<std::string> StrUtils::splitIntoLines(const std::string& input) {
    std::vector<std::string> result;
    std::size_t start = 0;
    std::size_t length = input.length();

    for (std::size_t i = 0; i < length; ++i) {
        bool isEndOfLine = (input[i] == '\n' || input[i] == '\r' || input[i] == '\0');

        if (isEndOfLine || i == length - 1) {
            // Calculate end position accounting for line endings
            std::size_t end = i;
            if (i > 0 && input[i-1] == '\r' && input[i] == '\n') {
                end = i - 1;
            } else if (i == length - 1 && input[i] != '\n' && input[i] != '\r') {
                end = i + 1;
            }

            // Extract line if it has content
            if (end > start) {
                result.push_back(input.substr(start, end - start));
            }

            // Move past the line ending
            start = i + 1;
            if (isEndOfLine && i + 1 < length && input[i+1] == '\n' && input[i] == '\r') {
                start = i + 2;
            }
        }
    }

    return result;
}

std::vector<std::vector<std::string>> StrUtils::tokenizeFile(std::istream& is, char comment) {
    std::vector<std::vector<std::string>> result;

    // Get non-comment lines
    std::vector<std::string> lines = readFile(is, comment);

    // Process each line
    for (const auto& line : lines) {
        if (line.empty()) continue;

        // Tokenize the line
        std::vector<std::string> tokens;
        std::size_t pos = 0;

        while (pos < line.length()) {
            // Skip whitespace
            while (pos < line.length() && 
                   (line[pos] == ' ' || line[pos] == '\t' || line[pos] == '\n')) {
                ++pos;
            }

            if (pos >= line.length()) break;

            // Find next token
            std::size_t tokenStart = pos;
            while (pos < line.length() && 
                   line[pos] != ' ' && line[pos] != '\t' && line[pos] != '\n') {
                ++pos;
            }

            tokens.push_back(line.substr(tokenStart, pos - tokenStart));
        }

        if (!tokens.empty()) {
            result.push_back(tokens);
        }
    }

    return result;
}

bool StrUtils::readLine(std::istream& is, std::string& line) {
    if (is.eof()) return false;

    std::getline(is, line);

    // Handle Windows-style line endings
    if (!line.empty() && line.back() == '\r') {
        line.pop_back();
    }

    return !is.eof() || !line.empty();
}

std::vector<std::string> StrUtils::getTokensPlusWhitespace(const std::string& str) {
    std::vector<std::string> result;
    std::size_t pos = 0;

    while (pos < str.length()) {
        // Check for whitespace
        bool isWhitespace = (str[pos] == ' ' || str[pos] == '\t' || str[pos] == '\n');

        if (isWhitespace) {
            // Collect consecutive whitespace
            std::size_t start = pos;
            while (pos < str.length() && 
                   (str[pos] == ' ' || str[pos] == '\t' || str[pos] == '\n')) {
                ++pos;
            }
            result.push_back(str.substr(start, pos - start));
        } else {
            // Collect non-whitespace characters
            std::size_t start = pos;
            while (pos < str.length() && 
                   str[pos] != ' ' && str[pos] != '\t' && str[pos] != '\n') {
                ++pos;
            }
            result.push_back(str.substr(start, pos - start));
        }
    }

    return result;
}

std::vector<std::string> StrUtils::stringTokenizer(const std::string& str) {
    std::vector<std::string> result;
    std::size_t pos = 0;

    while (pos < str.length()) {
        // Skip whitespace
        while (pos < str.length() && 
               (str[pos] == ' ' || str[pos] == '\t' || str[pos] == '\n')) {
            ++pos;
        }

        if (pos >= str.length()) break;

        // Find next token
        std::size_t start = pos;
        while (pos < str.length() && 
               str[pos] != ' ' && str[pos] != '\t' && str[pos] != '\n') {
            ++pos;
        }

        result.push_back(str.substr(start, pos - start));
    }

    return result;
}

std::string StrUtils::reassembleFromTokens(const std::vector<std::string>& tokens, int iStart) {
    std::string result;

    for (std::size_t i = static_cast<std::size_t>(iStart); i < tokens.size(); ++i) {
        if (i > static_cast<std::size_t>(iStart)) {
            result += " ";
        }
        result += tokens[i];
    }

    return result;
}

void StrUtils::splitList(const std::string& big, std::vector<std::string>& list) {
    list.clear();

    // If not starting with '[', treat entire string as single element
    if (big.empty() || big[0] != '[') {
        list.push_back(big);
        return;
    }

    int parenDepth = 0;
    std::string currentElement;

    // Start from index 1 to skip opening bracket
    for (std::size_t i = 1; i < big.length(); ++i) {
        char c = big[i];

        if (c == '(') {
            parenDepth++;
        } else if (c == ')') {
            parenDepth--;
        } else if (c == ']') {
            // End of list
            if (!currentElement.empty() || i == 1) {
                list.push_back(currentElement);
            }
            break;
        } else if (c == ',' && parenDepth == 0) {
            // Separator between elements
            list.push_back(currentElement);
            currentElement.clear();
        } else {
            currentElement += c;
        }
    }
}

int StrUtils::findNextWhitespace(const std::string& str, int offset) {
    for (std::size_t i = static_cast<std::size_t>(offset); i < str.length(); ++i) {
        if (str[i] == ' ' || str[i] == '\t' || str[i] == '\n') {
            return static_cast<int>(i);
        }
    }
    return static_cast<int>(str.length());
}

int StrUtils::findNextNonWhitespace(const std::string& str, int offset) {
    for (std::size_t i = static_cast<std::size_t>(offset); i < str.length(); ++i) {
        if (str[i] != ' ' && str[i] != '\t' && str[i] != '\n') {
            return static_cast<int>(i);
        }
    }
    return static_cast<int>(str.length());
}

std::string StrUtils::varTableSubstitute(const std::string& rawLine,
    const std::vector<std::string>& varNames,
    const std::vector<std::string>& varValues) {

    TEUCHOS_TEST_FOR_EXCEPTION(varNames.size() != varValues.size(),
        std::runtime_error,
        "mismatched variable tables in varTableSubstitute");

    std::string result = rawLine;

    for (std::size_t i = 0; i < varNames.size(); ++i) {
        result = varSubstitute(result, varNames[i], varValues[i]);
    }

    return result;
}

std::string StrUtils::varSubstitute(const std::string& rawLine,
    const std::string& varName,
    const std::string& varValue) {

    std::string result = rawLine;

    // Replace all occurrences of varName with varValue
    std::size_t pos = 0;
    while ((pos = result.find(varName, pos)) != std::string::npos) {
        result.replace(pos, varName.length(), varValue);
        pos += varValue.length();
    }

    return result;
}

std::string StrUtils::before(const std::string& str, char sub) {
    return before(str, std::string(1, sub));
}

std::string StrUtils::before(const std::string& str, const std::string& sub) {
    TEUCHOS_TEST_FOR_EXCEPTION(sub.empty(),
        std::runtime_error, "String::before: arg is null pointer");

    std::size_t pos = str.find(sub);
    if (pos == std::string::npos) {
        return str;
    }

    return str.substr(0, pos);
}

std::string StrUtils::after(const std::string& str, const std::string& sub) {
    TEUCHOS_TEST_FOR_EXCEPTION(sub.empty(),
        std::runtime_error, "String::after: arg is null pointer");

    std::size_t pos = str.find(sub);
    if (pos == std::string::npos) {
        return std::string();
    }

    return str.substr(pos + sub.length());
}

int StrUtils::find(const std::string& str, const std::string& sub) {
    std::size_t pos = str.find(sub);
    if (pos == std::string::npos) {
        return -1;
    }
    return static_cast<int>(pos);
}

bool StrUtils::isWhite(const std::string& str) {
    for (char c : str) {
        unsigned char uc = static_cast<unsigned char>(c);
        if (uc >= 33 && uc <= 126) {
            return false;
        }
    }
    return true;
}

std::string StrUtils::fixUnprintableCharacters(const std::string& str) {
    std::string result = str;

    for (std::size_t i = 0; i < result.length(); ++i) {
        unsigned char c = static_cast<unsigned char>(result[i]);

        // Replace unprintable characters except common whitespace
        if ((c < 33 || c > 126) && 
            c != '\t' && c != '\n' && c != '\r' && c != '\f' && c != ' ') {
            result[i] = ' ';
        }
    }

    return result;
}

std::string StrUtils::between(const std::string& str, const std::string& begin,
    const std::string& end, std::string& front,
    std::string& back) {

    front = before(str, begin);
    std::string afterBegin = after(str, begin);
    std::string middle = before(afterBegin, end);
    back = after(str, end);

    return middle;
}

std::string StrUtils::subString(const std::string& str, int begin, int end) {
    if (begin < 0) begin = 0;
    if (end > static_cast<int>(str.length())) end = static_cast<int>(str.length());
    if (begin >= end) return "";

    return str.substr(begin, end - begin);
}

std::string StrUtils::readFromStream(std::istream& is) {
    TEUCHOS_TEST_FOR_EXCEPTION(true, std::logic_error,
        "StrUtils::readFromStream isn't implemented yet");
    return "";
}

std::string StrUtils::allCaps(const std::string& s) {
    std::string result = s;

    for (char& c : result) {
        c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    }

    return result;
}

double StrUtils::atof(const std::string& s) {
    return std::atof(s.c_str());
}

int StrUtils::atoi(const std::string& s) {
    return std::atoi(s.c_str());
}

std::ostream& StrUtils::printLines(
    std::ostream             &os,
    const std::string       &linePrefix,
    const std::string       &lines) {

    std::vector<std::string> lineArray = splitIntoLines(lines);

    for (const auto& line : lineArray) {
        os << linePrefix << line << "\n";
    }

    return os;
}

std::string StrUtils::removeAllSpaces(std::string stringToClean) {
    std::string result;

    for (char c : stringToClean) {
        if (c != ' ') {
            result += c;
        }
    }

    return result;
}

