// Type III clone: Modified logic using a different approach to find the error message
const char* MessageHandling::getErrorCodeMessage(const returnValue _returnValue) {
    #ifndef __SUPPRESSANYOUTPUT__
        int_t index = 0;
        const char* result = "No message for this error code";

        // Traverse the list until terminal marker or match found
        while (true) {
            if (returnValueList[index].key == TERMINAL_LIST_ELEMENT) {
                result = "Unknown error code";
                break;
            }
            if (returnValueList[index].key == _returnValue) {
                result = (returnValueList[index].data != 0) 
                         ? returnValueList[index].data 
                         : "No message for this error code";
                break;
            }
            ++index;
        }

        return result;
    #else /* __SUPPRESSANYOUTPUT__ */
        return "No message for this error code";
    #endif /* __SUPPRESSANYOUTPUT__ */
}

