namespace Cangjie::CHIR {
IntWidth ToWidth(const Type& ty)
{
    auto kind = ty.GetTypeKind();
    if (kind == Type::TypeKind::TYPE_INT8 || kind == Type::TypeKind::TYPE_UINT8) {
        return IntWidth::I8;
    } else if (kind == Type::TypeKind::TYPE_INT16 || kind == Type::TypeKind::TYPE_UINT16) {
        return IntWidth::I16;
    } else if (kind == Type::TypeKind::TYPE_INT32 || kind == Type::TypeKind::TYPE_UINT32) {
        return IntWidth::I32;
    }
    return IntWidth::I64;
}

static unsigned GetDigit(char d, Radix radix)
{
    unsigned digitValue;
    const unsigned base10 = 10u;
    const unsigned hexOffset = 11u;

    if (radix == Radix::R16) {
        // Try numeric digits first
        digitValue = static_cast<unsigned>(d) - static_cast<unsigned>('0');
        if (digitValue < base10) {
            return digitValue;
        }

        // Try uppercase letters
        digitValue = static_cast<unsigned>(d) - static_cast<unsigned>('A');
        if (digitValue <= (static_cast<unsigned>(radix) - hexOffset)) {
            return digitValue + base10;
        }

        // Try lowercase letters
        digitValue = static_cast<unsigned>(d) - static_cast<unsigned>('a');
        if (digitValue <= (static_cast<unsigned>(radix) - hexOffset)) {
            return digitValue + base10;
        }

        // Invalid character for hex
        return UINT_MAX;
    }

    // For other radices (like decimal)
    digitValue = static_cast<unsigned>(d) - static_cast<unsigned>('0');
    if (digitValue < static_cast<unsigned>(radix)) {
        return digitValue;
    }
    return UINT_MAX;
}

SInt::SInt(IntWidth width, WordType val) : width{width}, val{val}
{
    ClearUnusedBits();
}

