void SInt::AShrInPlace(unsigned count)
{
    CJC_ASSERT(count <= width);
    int64_t sextVal = SignExtend64(val, width);
    if (count == width) {
        val = static_cast<uint64_t>(sextVal >> (BITS_PER_WORD - 1));
    } else {
        val = static_cast<uint64_t>(sextVal >> count);
    }
    ClearUnusedBits();
}

