SInt SInt::Concat(const SInt& v) const
{
    unsigned nw = width + v.width;
    switch (nw) {
        case IntWidth::I8:
        case IntWidth::I16:
        case IntWidth::I32:
        case IntWidth::I64:
            break;
        default:
            CJC_ABORT();
            break;
    }
    return {FromUnsigned(nw), (val << v.width) | v.val};
}

