#include <llarp/path/path.hpp>
#include <catch2/catch.hpp>

using Path_t   = llarp::path::Path;
using Path_ptr = llarp::path::Path_ptr;
using Set_t    = llarp::path::Path::UniqueEndpointSet_t;
using RC_t     = llarp::RelayContact;

static RC_t
GenerateHop(char identifier)
{
  RC_t hop_rc;
  hop_rc.pubkey.Fill(identifier);
  return hop_rc;
}

static Path_ptr
ConstructPath(const std::vector< char >& hop_ids)
{
  std::vector< RC_t > intermediate_hops;
  for (const auto& id : hop_ids)
    intermediate_hops.push_back(GenerateHop(id));
  return std::make_shared< Path_t >(intermediate_hops, std::weak_ptr<llarp::path::PathSet>{}, 0, "test");
}

TEST_CASE("UniqueEndpointSet_t ensures distinct endpoints", "[path]")
{
  Set_t endpoint_set;
  REQUIRE(endpoint_set.empty());

  const auto path_a = ConstructPath({'a', 'b', 'c', 'd'});
  const auto [iter1, success1] = endpoint_set.emplace(path_a);
  REQUIRE(success1);

  const auto path_b = ConstructPath({'a', 'b', 'c', 'd'});
  const auto [iter2, success2] = endpoint_set.emplace(path_b);
  REQUIRE(not success2);

  const auto path_c = ConstructPath({'d', 'c', 'b', 'a'});
  const auto [iter3, success3] = endpoint_set.emplace(path_c);
  REQUIRE(success3);
}

