using namespace gte;

// Destructor: clean up resources (none explicitly needed beyond member destruction)
ETManifoldMesh::~ETManifoldMesh() = default;

// Constructor with custom creators; fallback to defaults if not provided
ETManifoldMesh::ETManifoldMesh(ECreator eCreator, TCreator tCreator)
    : mEdgeFactory(eCreator ? eCreator : DefaultEdgeCreator),
      mTriFactory(tCreator ? tCreator : DefaultTriangleCreator),
      mStrictInsertion(true)
{
}

// Copy constructor delegates to assignment operator
ETManifoldMesh::ETManifoldMesh(ETManifoldMesh const& other)
{
    *this = other;
}

// Assignment operator: deep copy of mesh structure
ETManifoldMesh& ETManifoldMesh::operator=(ETManifoldMesh const& other)
{
    Clear();
    mEdgeFactory = other.mEdgeFactory;
    mTriFactory = other.mTriFactory;
    mStrictInsertion = other.mStrictInsertion;

    // Recreate all triangles by re-inserting their vertex triples
    for (auto const& entry : other.mTriangles)
    {
        auto const& triKey = entry.first;
        Insert(triKey.V[0], triKey.V[1], triKey.V[2]);
    }

    return *this;
}

// Accessors for edges and faces
ETManifoldMesh::EdgeContainer const& ETManifoldMesh::GetEdges() const
{
    return mEdges;
}

ETManifoldMesh::FaceContainer const& ETManifoldMesh::GetTriangles() const
{
    return mTriangles;
}

// Toggle strict mode on non-manifold insertions; returns previous setting
bool ETManifoldMesh::SetStrictMode(bool flag)
{
    bool oldFlag = mStrictInsertion;
    mStrictInsertion = flag;
    return oldFlag;
}

// Attempt to insert triangle defined by vertices v0, v1, v2
std::shared_ptr<ETManifoldMesh::Triangle> ETManifoldMesh::Insert(int v0, int v1, int v2)
{
    TriangleKey<true> faceKey(v0, v1, v2);

    // Early exit if triangle already exists
    if (mTriangles.find(faceKey) != mTriangles.end())
    {
        return nullptr;
    }

    // Create new triangle object
    std::shared_ptr<Triangle> newFace = mTriFactory(v0, v1, v2);

    // Process each edge of the triangle
    for (int idx0 = 2, idx1 = 0; idx1 < 3; idx0 = idx1++)
    {
        EdgeKey<false> edgeKey(newFace->V[idx0], newFace->V[idx1]);
        std::shared_ptr<Edge> existingEdge;

        auto iter = mEdges.find(edgeKey);
        if (iter == mEdges.end())
        {
            // First occurrence: create new edge
            existingEdge = mEdgeFactory(newFace->V[idx0], newFace->V[idx1]);
            mEdges[edgeKey] = existingEdge;

            // Link edge to triangle
            existingEdge->T[0] = newFace;
            newFace->E[idx0] = existingEdge;
        }
        else
        {
            // Second occurrence: link to existing edge
            existingEdge = iter->second;
            if (!existingEdge)
            {
                LogError("Null edge pointer encountered unexpectedly.");
                return nullptr;
            }

            // Check manifoldness before linking second triangle
            if (existingEdge->T[1].lock())
            {
                if (mStrictInsertion)
                {
                    LogInformation("Non-manifold insertion attempted.");
                }
                return nullptr;
            }

            existingEdge->T[1] = newFace;

            // Update adjacency between triangles via shared edge
            auto prevTri = existingEdge->T[0].lock();
            if (!prevTri)
            {
                LogError("Invalid adjacency state.");
                return nullptr;
            }

            for (int j = 0; j < 3; ++j)
            {
                if (prevTri->E[j].lock() == existingEdge)
                {
                    prevTri->T[j] = newFace;
                    break;
                }
            }

            // Link current triangle back to edge and adjacent triangle
            newFace->E[idx0] = existingEdge;
            newFace->T[idx0] = prevTri;
        }
    }

    // Finalize insertion into triangle map
    mTriangles[faceKey] = newFace;
    return newFace;
}

// Remove triangle specified by its vertex indices
bool ETManifoldMesh::Remove(int v0, int v1, int v2)
{
    TriangleKey<true> faceKey(v0, v1, v2);
    auto iter = mTriangles.find(faceKey);
    if (iter == mTriangles.end())
    {
        return false;
    }

    auto face = iter->second;

    // For each edge of the face, update connections and possibly delete edge
    for (int i = 0; i < 3; ++i)
    {
        auto edge = face->E[i].lock();
        if (!edge)
        {
            LogError("Missing edge reference during removal.");
            return false;
        }

        // Unlink this triangle from the edge
        if (edge->T[0].lock() == face)
        {
            edge->T[0] = edge->T[1];
            edge->T[1].reset();
        }
        else if (edge->T[1].lock() == face)
        {
            edge->T[1].reset();
        }
        else
        {
            LogError("Inconsistent triangle-edge relationship.");
            return false;
        }

        // Delete edge only if no longer used
        if (!edge->T[0].lock() && !edge->T[1].lock())
        {
            EdgeKey<false> ekey(edge->V[0], edge->V[1]);
            mEdges.erase(ekey);
        }

        // Notify adjacent triangle that this face is gone
        auto neighbor = face->T[i].lock();
        if (neighbor)
        {
            for (int j = 0; j < 3; ++j)
            {
                if (neighbor->T[j].lock() == face)
                {
                    neighbor->T[j].reset();
                    break;
                }
            }
        }
    }

    // Erase triangle from container
    mTriangles.erase(faceKey);
    return true;
}

// Reset mesh to empty state
void ETManifoldMesh::Clear()
{
    mEdges.clear();
    mTriangles.clear();
}

// Determine whether mesh forms a closed surface (every edge has two incident triangles)
bool ETManifoldMesh::IsClosed() const
{
    for (auto const& pair : mEdges)
    {
        auto const& edge = pair.second;
        if (!edge->T[0].lock() || !edge->T[1].lock())
        {
            return false;
        }
    }
    return true;
}

// Verify consistency of triangle orientations across shared edges
bool ETManifoldMesh::IsOriented() const
{
    for (auto const& pair : mEdges)
    {
        auto edge = pair.second;
        if (edge->T[0].lock() && edge->T[1].lock())
        {
            bool forward[2] = { false };
            int oppositeVertex[2] = { -1, -1 };

            for (int k = 0; k < 2; ++k)
            {
                auto tri = edge->T[k].lock();
                for (int i = 0; i < 3; ++i)
                {
                    if (tri->V[i] == pair.first.V[0])
                    {
                        int nextIdx = tri->V[(i + 1) % 3];
                        if (nextIdx == pair.first.V[1])
                        {
                            forward[k] = true;
                            oppositeVertex[k] = tri->V[(i + 2) % 3];
                        }
                        else
                        {
                            forward[k] = false;
                            oppositeVertex[k] = nextIdx;
                        }
                        break;
                    }
                }
            }

            // Oriented correctly iff directions differ AND opposite vertices differ
            if (forward[0] == forward[1] || oppositeVertex[0] == oppositeVertex[1])
            {
                return false;
            }
        }
    }
    return true;
}

// Extract connected components using DFS over triangle adjacency
void ETManifoldMesh::GetComponents(
    std::vector<std::vector<std::shared_ptr<Triangle>>>& outComponents) const
{
    std::map<std::shared_ptr<Triangle>, int> status;
    for (auto const& item : mTriangles)
    {
        status[item.second] = 0; // unvisited
    }

    for (auto const& item : mTriangles)
    {
        auto tri = item.second;
        if (status[tri] == 0)
        {
            std::vector<std::shared_ptr<Triangle>> comp;
            TraverseDepthFirst(tri, status, comp);
            outComponents.push_back(comp);
        }
    }
}

// Variant returning component keys instead of shared pointers
void ETManifoldMesh::GetComponents(
    std::vector<std::vector<TriangleKey<true>>>& outComponents) const
{
    std::map<std::shared_ptr<Triangle>, int> visited;
    for (auto const& item : mTriangles)
    {
        visited[item.second] = 0;
    }

    for (auto const& item : mTriangles)
    {
        auto tri = item.second;
        if (visited[tri] == 0)
        {
            std::vector<std::shared_ptr<Triangle>> comp;
            TraverseDepthFirst(tri, visited, comp);

            std::vector<TriangleKey<true>> keyList;
            keyList.reserve(comp.size());
            for (auto const& t : comp)
            {
                keyList.emplace_back(t->V[0], t->V[1], t->V[2]);
            }
            outComponents.push_back(keyList);
        }
    }
}

// Internal depth-first traversal helper
void ETManifoldMesh::TraverseDepthFirst(std::shared_ptr<Triangle> start,
    std::map<std::shared_ptr<Triangle>, int>& visited,
    std::vector<std::shared_ptr<Triangle>>& result) const
{
    std::vector<std::shared_ptr<Triangle>> stack(mTriangles.size());
    int top = -1;

    stack[++top] = start;

    while (top >= 0)
    {
        auto current = stack[top];
        visited[current] = 1;

        int i;
        for (i = 0; i < 3; ++i)
        {
            auto neighbor = current->T[i].lock();
            if (neighbor && visited[neighbor] == 0)
            {
                stack[++top] = neighbor;
                break;
            }
        }

        if (i == 3)
        {
            visited[current] = 2;
            result.push_back(current);
            --top;
        }
    }
}

// Factory methods for creating basic primitives
std::shared_ptr<ETManifoldMesh::Edge> ETManifoldMesh::DefaultEdgeCreator(int v0, int v1)
{
    return std::make_shared<Edge>(v0, v1);
}

std::shared_ptr<ETManifoldMesh::Triangle> ETManifoldMesh::DefaultTriangleCreator(int v0, int v1, int v2)
{
    return std::make_shared<Triangle>(v0, v1, v2);
}

// Edge and Triangle destructors (default behavior sufficient)
ETManifoldMesh::Edge::~Edge() = default;
ETManifoldMesh::Triangle::~Triangle() = default;

// Edge constructor
ETManifoldMesh::Edge::Edge(int v0, int v1)
{
    V[0] = v0;
    V[1] = v1;
}

// Triangle constructor
ETManifoldMesh::Triangle::Triangle(int v0, int v1, int v2)
{
    V[0] = v0;
    V[1] = v1;
    V[2] = v2;
}

#include <cmath>
// DDS
#include <unitree/robot/channel/channel_publisher.hpp>
#include <unitree/robot/channel/channel_subscriber.hpp>
// IDL
#include <unitree/idl/hg/LowCmd_.hpp>
#include <unitree/idl/hg/LowState_.hpp>

static const std::string HG_CMD_TOPIC = "rt/lowcmd";
static const std::string HG_STATE_TOPIC = "rt/lowstate";

using namespace unitree::common;
using namespace unitree::robot;

const int H1_NUM_MOTOR = 27;

enum ControlMode { POSITION_ROTATION = 0, ABSOLUTE = 1 };

inline uint32_t CalculateCRC32(uint32_t *buffer, uint32_t length) {
  uint32_t crc = 0xFFFFFFFF;
  const uint32_t poly = 0x04c11db7;

  for (uint32_t i = 0; i < length; ++i) {
    uint32_t current = buffer[i];
    for (int bit = 0; bit < 32; ++bit) {
      bool xor_flag = (crc & 0x80000000) != 0;
      crc <<= 1;
      if (current & (1u << (31 - bit))) {
        crc ^= poly;
      }
      if (xor_flag) {
        crc ^= poly;
      }
    }
  }
  return crc;
}

class H1AnkleController {
 private:
  double elapsed_time_;
  double control_period_;   // [2ms]
  double transition_time_;  // [3s]
  ControlMode control_mode_;

  unitree_hg::msg::dds_::LowState_ robot_state_;
  ChannelPublisherPtr<unitree_hg::msg::dds_::LowCmd_> command_publisher_;
  ChannelSubscriberPtr<unitree_hg::msg::dds_::LowState_> state_subscriber_;
  ThreadPtr control_loop_thread_;

 public:
  H1AnkleController(const std::string& interface)
      : elapsed_time_(0.0),
        control_period_(0.002),
        transition_time_(3.0),
        control_mode_(POSITION_ROTATION) {
    ChannelFactory::Instance()->Init(0, interface);

    // Initialize publisher for low-level commands
    command_publisher_.reset(
        new ChannelPublisher<unitree_hg::msg::dds_::LowCmd_>(HG_CMD_TOPIC));
    command_publisher_->InitChannel();

    // Initialize subscriber for robot state feedback
    state_subscriber_.reset(
        new ChannelSubscriber<unitree_hg::msg::dds_::LowState_>(HG_STATE_TOPIC));
    state_subscriber_->InitChannel(
        [this](const void* msg) { this->OnRobotStateUpdate(msg); }, 1);

    // Start control loop thread
    control_loop_thread_ = CreateRecurrentThreadEx(
        "ankle_control", UT_CPU_ID_NONE, 2000, &H1AnkleController::RunControl, this);
  }

  void OnRobotStateUpdate(const void* message) {
    robot_state_ = *(const unitree_hg::msg::dds_::LowState_*)message;

    // Verify CRC integrity of received state
    uint32_t computed_crc = CalculateCRC32(
        (uint32_t*)&robot_state_, 
        (sizeof(unitree_hg::msg::dds_::LowState_) >> 2) - 1
    );
    if (computed_crc != robot_state_.crc()) {
      std::cout << "Warning: LowState CRC mismatch detected" << std::endl;
    }
  }

  void RunControl() {
    unitree_hg::msg::dds_::LowCmd_ command_msg;

    command_msg.mode_pr() = control_mode_;
    command_msg.mode_machine() = robot_state_.mode_machine();

    // Initialize all motor commands with default values
    for (int idx = 0; idx < H1_NUM_MOTOR; ++idx) {
      command_msg.motor_cmd().at(idx).mode() = 1;     // Enable motor
      command_msg.motor_cmd().at(idx).tau() = 0.0;
      command_msg.motor_cmd().at(idx).q() = 0.0;
      command_msg.motor_cmd().at(idx).dq() = 0.0;
      command_msg.motor_cmd().at(idx).kp() = (idx < 13) ? 100.0 : 50.0;
      command_msg.motor_cmd().at(idx).kd() = 1.0;
    }

    elapsed_time_ += control_period_;

    if (elapsed_time_ < transition_time_) {
      // Phase 1: Smoothly transition to zero posture
      double progress = std::clamp(elapsed_time_ / transition_time_, 0.0, 1.0);
      for (int idx = 0; idx < H1_NUM_MOTOR; ++idx) {
        command_msg.motor_cmd().at(idx).q() = 
            (1.0 - progress) * robot_state_.motor_state().at(idx).q();
      }
    } else {
      // Phase 2: Ankle oscillation in PR mode
      control_mode_ = POSITION_ROTATION;

      // Define oscillation parameters
      double amplitude_P = 0.25;  // Pitch amplitude [rad]
      double amplitude_R = 0.25;  // Roll amplitude [rad]
      double time_offset = elapsed_time_ - transition_time_;
      double angular_freq = 2.0 * M_PI;

      // Compute desired trajectories
      double left_pitch_desired = amplitude_P * std::cos(angular_freq * time_offset);
      double left_roll_desired = amplitude_R * std::sin(angular_freq * time_offset);
      double right_pitch_desired = amplitude_P * std::cos(angular_freq * time_offset);
      double right_roll_desired = -amplitude_R * std::sin(angular_freq * time_offset);

      // Configure left ankle joints
      constexpr float kp_ankle = 80.0f;
      constexpr float kd_ankle = 1.0f;

      command_msg.motor_cmd().at(4).q() = left_pitch_desired;   // LeftAnklePitch
      command_msg.motor_cmd().at(4).dq() = 0.0;
      command_msg.motor_cmd().at(4).kp() = kp_ankle;
      command_msg.motor_cmd().at(4).kd() = kd_ankle;
      command_msg.motor_cmd().at(4).tau() = 0.0;

      command_msg.motor_cmd().at(5).q() = left_roll_desired;    // LeftAnkleRoll
      command_msg.motor_cmd().at(5).dq() = 0.0;
      command_msg.motor_cmd().at(5).kp() = kp_ankle;
      command_msg.motor_cmd().at(5).kd() = kd_ankle;
      command_msg.motor_cmd().at(5).tau() = 0.0;

      // Configure right ankle joints
      command_msg.motor_cmd().at(10).q() = right_pitch_desired; // RightAnklePitch
      command_msg.motor_cmd().at(10).dq() = 0.0;
      command_msg.motor_cmd().at(10).kp() = kp_ankle;
      command_msg.motor_cmd().at(10).kd() = kd_ankle;
      command_msg.motor_cmd().at(10).tau() = 0.0;

      command_msg.motor_cmd().at(11).q() = right_roll_desired;  // RightAnkleRoll
      command_msg.motor_cmd().at(11).dq() = 0.0;
      command_msg.motor_cmd().at(11).kp() = kp_ankle;
      command_msg.motor_cmd().at(11).kd() = kd_ankle;
      command_msg.motor_cmd().at(11).tau() = 0.0;

      // Output current and desired positions for debugging
      float L_P_actual = robot_state_.motor_state().at(4).q();
      float L_R_actual = robot_state_.motor_state().at(5).q();
      float R_P_actual = robot_state_.motor_state().at(10).q();
      float R_R_actual = robot_state_.motor_state().at(11).q();

      printf("%f,%f,%f,%f,%f,%f,%f,%f\n",
             left_pitch_desired, L_P_actual, 
             left_roll_desired, L_R_actual,
             right_pitch_desired, R_P_actual,
             right_roll_desired, R_R_actual);
    }

    // Compute and set CRC for command message
    command_msg.crc() = CalculateCRC32(
        (uint32_t*)&command_msg, 
        (sizeof(command_msg) >> 2) - 1
    );

    // Send command to robot
    command_publisher_->Write(command_msg);
  }
};

int main(int argc, char const *argv[]) {
  if (argc < 2) {
    std::cout << "Usage: h1_2_ankle_track network_interface_name" << std::endl;
    return 0;
  }

  std::string networkInterface = argv[1];
  H1AnkleController controller(networkInterface);

  while (true) {
    sleep(10);
  }
  return 0;
}

