void plutovg_path_iterator_init(plutovg_path_iterator_t* it, const plutovg_path_t* path)
{
    it->elements = path->elements.data;
    it->total_elements = path->elements.size;
    it->current_pos = 0;
}

bool plutovg_path_iterator_has_next(const plutovg_path_iterator_t* it)
{
    return it->current_pos < it->total_elements;
}

plutovg_path_command_t plutovg_path_iterator_next(plutovg_path_iterator_t* it, plutovg_point_t points[3])
{
    const plutovg_path_element_t* current = it->elements + it->current_pos;
    plutovg_path_command_t cmd = current->header.command;

    switch(cmd) {
    case PLUTOVG_PATH_COMMAND_MOVE_TO:
    case PLUTOVG_PATH_COMMAND_LINE_TO:
    case PLUTOVG_PATH_COMMAND_CLOSE:
        points[0] = current[1].point;
        break;
    case PLUTOVG_PATH_COMMAND_CUBIC_TO:
        points[0] = current[1].point;
        points[1] = current[2].point;
        points[2] = current[3].point;
        break;
    }

    it->current_pos += current->header.length;
    return cmd;
}

plutovg_path_t* plutovg_path_create(void)
{
    plutovg_path_t* path = static_cast<plutovg_path_t*>(malloc(sizeof(plutovg_path_t)));
    if(path) {
        plutovg_init_reference(path);
        path->num_points = 0;
        path->num_contours = 0;
        path->num_curves = 0;
        path->start_point = PLUTOVG_EMPTY_POINT;
        plutovg_array_init(path->elements);
    }
    return path;
}

plutovg_path_t* plutovg_path_reference(plutovg_path_t* path)
{
    plutovg_increment_reference(path);
    return path;
}

void plutovg_path_destroy(plutovg_path_t* path)
{
    if(plutovg_destroy_reference(path)) {
        if(path->elements.data) {
            free(path->elements.data);
            path->elements.data = NULL;
        }
        path->elements.size = 0;
        path->elements.capacity = 0;
        free(path);
    }
}

int plutovg_path_get_reference_count(const plutovg_path_t* path)
{
    return plutovg_get_reference_count(path);
}

int plutovg_path_get_elements(const plutovg_path_t* path, const plutovg_path_element_t** elements)
{
    if(elements) {
        *elements = path->elements.data;
    }
    return path->elements.size;
}

static plutovg_path_element_t* plutovg_path_add_command_internal(plutovg_path_t* path, plutovg_path_command_t command, int npoints)
{
    const int required_length = npoints + 1;
    const int current_size = path->elements.size;
    const int new_size = current_size + required_length;

    if(new_size > path->elements.capacity) {
        int new_capacity = path->elements.capacity;
        if(new_capacity == 0) new_capacity = 8;
        while(new_capacity < new_size) {
            new_capacity *= 2;
        }
        path->elements.data = static_cast<plutovg_path_element_t*>(
            realloc(path->elements.data, new_capacity * sizeof(plutovg_path_element_t)));
        path->elements.capacity = new_capacity;
    }

    path->elements.size = new_size;
    plutovg_path_element_t* element = &path->elements.data[current_size];
    element->header.command = command;
    element->header.length = required_length;

    path->num_points += npoints;
    return &path->elements.data[current_size + 1];
}

void plutovg_path_move_to(plutovg_path_t* path, float x, float y)
{
    if(path->elements.size == 0 || 
       (path->elements.data[path->elements.size-1].header.command != PLUTOVG_PATH_COMMAND_MOVE_TO &&
        path->elements.data[path->elements.size-1].header.command != PLUTOVG_PATH_COMMAND_LINE_TO)) {
        plutovg_path_element_t* point_data = plutovg_path_add_command_internal(path, PLUTOVG_PATH_COMMAND_MOVE_TO, 1);
        point_data[0].point = PLUTOVG_MAKE_POINT(x, y);
        path->start_point = PLUTOVG_MAKE_POINT(x, y);
        path->num_contours += 1;
    } else {
        // Update existing move_to
        path->elements.data[path->elements.size-1].point = PLUTOVG_MAKE_POINT(x, y);
        path->start_point = PLUTOVG_MAKE_POINT(x, y);
    }
}

void plutovg_path_line_to(plutovg_path_t* path, float x, float y)
{
    if(path->elements.size == 0) {
        plutovg_path_move_to(path, 0, 0);
    }
    plutovg_path_element_t* point_data = plutovg_path_add_command_internal(path, PLUTOVG_PATH_COMMAND_LINE_TO, 1);
    point_data[0].point = PLUTOVG_MAKE_POINT(x, y);
}

void plutovg_path_quad_to(plutovg_path_t* path, float x1, float y1, float x2, float y2)
{
    float current_x = 0.f, current_y = 0.f;
    plutovg_path_get_current_point(path, &current_x, &current_y);

    float cp1x = (2.f/3.f) * x1 + (1.f/3.f) * current_x;
    float cp1y = (2.f/3.f) * y1 + (1.f/3.f) * current_y;
    float cp2x = (2.f/3.f) * x1 + (1.f/3.f) * x2;
    float cp2y = (2.f/3.f) * y1 + (1.f/3.f) * y2;

    plutovg_path_cubic_to(path, cp1x, cp1y, cp2x, cp2y, x2, y2);
}

void plutovg_path_cubic_to(plutovg_path_t* path, float x1, float y1, float x2, float y2, float x3, float y3)
{
    if(path->elements.size == 0) {
        plutovg_path_move_to(path, 0, 0);
    }
    plutovg_path_element_t* point_data = plutovg_path_add_command_internal(path, PLUTOVG_PATH_COMMAND_CUBIC_TO, 3);
    point_data[0].point = PLUTOVG_MAKE_POINT(x1, y1);
    point_data[1].point = PLUTOVG_MAKE_POINT(x2, y2);
    point_data[2].point = PLUTOVG_MAKE_POINT(x3, y3);
    path->num_curves += 1;
}

void plutovg_path_arc_to(plutovg_path_t* path, float rx, float ry, float angle, bool large_arc_flag, bool sweep_flag, float x, float y)
{
    float current_x = 0.f, current_y = 0.f;
    plutovg_path_get_current_point(path, &current_x, &current_y);

    if(rx == 0.f || ry == 0.f || (current_x == x && current_y == y)) {
        plutovg_path_line_to(path, x, y);
        return;
    }

    if(rx < 0.f) rx = -rx;
    if(ry < 0.f) ry = -ry;

    float dx = (current_x - x) * 0.5f;
    float dy = (current_y - y) * 0.5f;

    plutovg_matrix_t rotation_matrix;
    plutovg_matrix_init_rotate(&rotation_matrix, -angle);
    plutovg_matrix_map(&rotation_matrix, dx, dy, &dx, &dy);

    float rx_squared = rx * rx;
    float ry_squared = ry * ry;
    float dx_squared = dx * dx;
    float dy_squared = dy * dy;

    float radius_check = dx_squared / rx_squared + dy_squared / ry_squared;
    if(radius_check > 1.f) {
        rx *= sqrtf(radius_check);
        ry *= sqrtf(radius_check);
    }

    plutovg_matrix_t transform_matrix;
    plutovg_matrix_init_scale(&transform_matrix, 1.f/rx, 1.f/ry);
    plutovg_matrix_rotate(&transform_matrix, -angle);

    float x1_prime, y1_prime;
    float x2_prime, y2_prime;
    plutovg_matrix_map(&transform_matrix, current_x, current_y, &x1_prime, &y1_prime);
    plutovg_matrix_map(&transform_matrix, x, y, &x2_prime, &y2_prime);

    float dx1_diff = x2_prime - x1_prime;
    float dy1_diff = y2_prime - y1_prime;
    float distance_sq = dx1_diff * dx1_diff + dy1_diff * dy1_diff;

    float scale_factor_sq = 1.f / distance_sq - 0.25f;
    if(scale_factor_sq < 0.f) scale_factor_sq = 0.f;
    float scale_factor = sqrtf(scale_factor_sq);

    if(sweep_flag == large_arc_flag) {
        scale_factor = -scale_factor;
    }

    float cx_prime = 0.5f * (x1_prime + x2_prime) - scale_factor * dy1_diff;
    float cy_prime = 0.5f * (y1_prime + y2_prime) + scale_factor * dx1_diff;

    float theta1 = atan2f(y1_prime - cy_prime, x1_prime - cx_prime);
    float theta2 = atan2f(y2_prime - cy_prime, x2_prime - cx_prime);
    float theta_arc = theta2 - theta1;

    if(theta_arc < 0.f && sweep_flag) {
        theta_arc += PLUTOVG_TWO_PI;
    } else if(theta_arc > 0.f && !sweep_flag) {
        theta_arc -= PLUTOVG_TWO_PI;
    }

    plutovg_matrix_t final_transform;
    plutovg_matrix_init_rotate(&final_transform, angle);
    plutovg_matrix_scale(&final_transform, rx, ry);

    int num_segments = static_cast<int>(ceilf(fabsf(theta_arc) / (PLUTOVG_HALF_PI + 0.001f)));

    for(int i = 0; i < num_segments; ++i) {
        float theta_start = theta1 + i * theta_arc / num_segments;
        float theta_end = theta1 + (i + 1) * theta_arc / num_segments;

        float t = (8.f/6.f) * tanf(0.25f * (theta_end - theta_start));

        float cos_theta_end = cosf(theta_end);
        float sin_theta_end = sinf(theta_end);
        float cos_theta_start = cosf(theta_start);
        float sin_theta_start = sinf(theta_start);

        float px3 = cos_theta_end + cx_prime;
        float py3 = sin_theta_end + cy_prime;
        float cp2x = px3 + t * sin_theta_end;
        float cp2y = py3 - t * cos_theta_end;
        float cp1x = cos_theta_start - t * sin_theta_start;
        float cp1y = sin_theta_start + t * cos_theta_start;

        cp1x += cx_prime;
        cp1y += cy_prime;

        plutovg_matrix_map(&final_transform, cp1x, cp1y, &cp1x, &cp1y);
        plutovg_matrix_map(&final_transform, cp2x, cp2y, &cp2x, &cp2y);
        plutovg_matrix_map(&final_transform, px3, py3, &px3, &py3);

        plutovg_path_cubic_to(path, cp1x, cp1y, cp2x, cp2y, px3, py3);
    }
}

void plutovg_path_close(plutovg_path_t* path)
{
    if(path->elements.size == 0) {
        return;
    }

    plutovg_path_element_t* element = plutovg_path_add_command_internal(path, PLUTOVG_PATH_COMMAND_CLOSE, 1);
    element[0].point = path->start_point;
}

void plutovg_path_get_current_point(const plutovg_path_t* path, float* x, float* y)
{
    float xx = 0.f;
    float yy = 0.f;

    if(path->num_points > 0) {
        int last_index = path->elements.size - 1;
        while(last_index >= 0) {
            const plutovg_path_element_t* element = &path->elements.data[last_index];
            if(element->header.command == PLUTOVG_PATH_COMMAND_MOVE_TO ||
               element->header.command == PLUTOVG_PATH_COMMAND_LINE_TO ||
               element->header.command == PLUTOVG_PATH_COMMAND_CLOSE) {
                xx = element[1].point.x;
                yy = element[1].point.y;
                break;
            } else if(element->header.command == PLUTOVG_PATH_COMMAND_CUBIC_TO) {
                xx = element[3].point.x;
                yy = element[3].point.y;
                break;
            }
            last_index -= element->header.length;
        }
    }

    if(x) *x = xx;
    if(y) *y = yy;
}

void plutovg_path_reserve(plutovg_path_t* path, int count)
{
    int current_size = path->elements.size;
    int new_size = current_size + count;

    if(new_size > path->elements.capacity) {
        int new_capacity = path->elements.capacity;
        if(new_capacity == 0) new_capacity = 8;
        while(new_capacity < new_size) {
            new_capacity *= 2;
        }
        path->elements.data = static_cast<plutovg_path_element_t*>(
            realloc(path->elements.data, new_capacity * sizeof(plutovg_path_element_t)));
        path->elements.capacity = new_capacity;
    }
}

void plutovg_path_reset(plutovg_path_t* path)
{
    if(path->elements.data) {
        free(path->elements.data);
        path->elements.data = NULL;
    }
    path->elements.size = 0;
    path->elements.capacity = 0;
    path->start_point = PLUTOVG_EMPTY_POINT;
    path->num_points = 0;
    path->num_contours = 0;
    path->num_curves = 0;
}

void plutovg_path_add_rect(plutovg_path_t* path, float x, float y, float w, float h)
{
    plutovg_path_reserve(path, 10);
    plutovg_path_move_to(path, x, y);
    plutovg_path_line_to(path, x + w, y);
    plutovg_path_line_to(path, x + w, y + h);
    plutovg_path_line_to(path, x, y + h);
    plutovg_path_line_to(path, x, y);
    plutovg_path_close(path);
}

void plutovg_path_add_round_rect(plutovg_path_t* path, float x, float y, float w, float h, float rx, float ry)
{
    rx = fminf(rx, w * 0.5f);
    ry = fminf(ry, h * 0.5f);

    if(rx == 0.f && ry == 0.f) {
        plutovg_path_add_rect(path, x, y, w, h);
        return;
    }

    float right = x + w;
    float bottom = y + h;
    float cpx = rx * PLUTOVG_KAPPA;
    float cpy = ry * PLUTOVG_KAPPA;

    plutovg_path_reserve(path, 30);
    plutovg_path_move_to(path, x, y+ry);
    plutovg_path_cubic_to(path, x, y+ry-cpy, x+rx-cpx, y, x+rx, y);
    plutovg_path_line_to(path, right-rx, y);
    plutovg_path_cubic_to(path, right-rx+cpx, y, right, y+ry-cpy, right, y+ry);
    plutovg_path_line_to(path, right, bottom-ry);
    plutovg_path_cubic_to(path, right, bottom-ry+cpy, right-rx+cpx, bottom, right-rx, bottom);
    plutovg_path_line_to(path, x+rx, bottom);
    plutovg_path_cubic_to(path, x+rx-cpx, bottom, x, bottom-ry+cpy, x, bottom-ry);
    plutovg_path_line_to(path, x, y+ry);
    plutovg_path_close(path);
}

void plutovg_path_add_ellipse(plutovg_path_t* path, float cx, float cy, float rx, float ry)
{
    float left = cx - rx;
    float top = cy - ry;
    float right = cx + rx;
    float bottom = cy + ry;
    float cpx = rx * PLUTOVG_KAPPA;
    float cpy = ry * PLUTOVG_KAPPA;

    plutovg_path_reserve(path, 20);
    plutovg_path_move_to(path, cx, top);
    plutovg_path_cubic_to(path, cx+cpx, top, right, cy-cpy, right, cy);
    plutovg_path_cubic_to(path, right, cy+cpy, cx+cpx, bottom, cx, bottom);
    plutovg_path_cubic_to(path, cx-cpx, bottom, left, cy+cpy, left, cy);
    plutovg_path_cubic_to(path, left, cy-cpy, cx-cpx, top, cx, top);
    plutovg_path_close(path);
}

void plutovg_path_add_circle(plutovg_path_t* path, float cx, float cy, float r)
{
    plutovg_path_add_ellipse(path, cx, cy, r, r);
}

void plutovg_path_add_arc(plutovg_path_t* path, float cx, float cy, float r, float a0, float a1, bool ccw)
{
    float da = a1 - a0;
    if(fabsf(da) > PLUTOVG_TWO_PI) {
        da = PLUTOVG_TWO_PI;
    } else if(da != 0.f && ccw != (da < 0.f)) {
        da += PLUTOVG_TWO_PI * (ccw ? -1 : 1);
    }

    int seg_n = static_cast<int>(ceilf(fabsf(da) / PLUTOVG_HALF_PI));
    if(seg_n == 0) return;

    float a = a0;
    float ax = cx + cosf(a) * r;
    float ay = cy + sinf(a) * r;
    float seg_a = da / seg_n;
    float d = (seg_a / PLUTOVG_HALF_PI) * PLUTOVG_KAPPA * r;

    plutovg_path_reserve(path, 2 + 4 * seg_n);

    if(path->elements.size == 0) {
        plutovg_path_move_to(path, ax, ay);
    } else {
        plutovg_path_line_to(path, ax, ay);
    }

    for(int i = 0; i < seg_n; i++) {
        float cp1x = ax + (-sinf(a) * d);
        float cp1y = ay + (cosf(a) * d);
        a += seg_a;
        ax = cx + cosf(a) * r;
        ay = cy + sinf(a) * r;
        float cp2x = ax - (-sinf(a) * d);
        float cp2y = ay - (cosf(a) * d);

        plutovg_path_cubic_to(path, cp1x, cp1y, cp2x, cp2y, ax, ay);
    }
}

void plutovg_path_transform(plutovg_path_t* path, const plutovg_matrix_t* matrix)
{
    for(int i = 0; i < path->elements.size; ) {
        const plutovg_path_element_t* element = &path->elements.data[i];
        int length = element->header.length;

        switch(element->header.command) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
        case PLUTOVG_PATH_COMMAND_LINE_TO:
        case PLUTOVG_PATH_COMMAND_CLOSE:
            plutovg_matrix_map_point(matrix, &element[1].point, &element[1].point);
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            plutovg_matrix_map_point(matrix, &element[1].point, &element[1].point);
            plutovg_matrix_map_point(matrix, &element[2].point, &element[2].point);
            plutovg_matrix_map_point(matrix, &element[3].point, &element[3].point);
            break;
        }
        i += length;
    }
}

void plutovg_path_add_path(plutovg_path_t* path, const plutovg_path_t* source, const plutovg_matrix_t* matrix)
{
    if(matrix == NULL) {
        int source_size = source->elements.size;
        if(source_size > 0) {
            plutovg_path_reserve(path, source_size);
            for(int i = 0; i < source_size; ++i) {
                path->elements.data[path->elements.size + i] = source->elements.data[i];
            }
            path->elements.size += source_size;
        }
        path->start_point = source->start_point;
        path->num_points += source->num_points;
        path->num_contours += source->num_contours;
        path->num_curves += source->num_curves;
        return;
    }

    plutovg_path_iterator_t it;
    plutovg_path_iterator_init(&it, source);
    plutovg_point_t points[3];

    while(plutovg_path_iterator_has_next(&it)) {
        switch(plutovg_path_iterator_next(&it, points)) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
            plutovg_matrix_map_points(matrix, points, points, 1);
            plutovg_path_move_to(path, points[0].x, points[0].y);
            break;
        case PLUTOVG_PATH_COMMAND_LINE_TO:
            plutovg_matrix_map_points(matrix, points, points, 1);
            plutovg_path_line_to(path, points[0].x, points[0].y);
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            plutovg_matrix_map_points(matrix, points, points, 3);
            plutovg_path_cubic_to(path, points[0].x, points[0].y, points[1].x, points[1].y, points[2].x, points[2].y);
            break;
        case PLUTOVG_PATH_COMMAND_CLOSE:
            plutovg_path_close(path);
            break;
        }
    }
}

void plutovg_path_traverse(const plutovg_path_t* path, plutovg_path_traverse_func_t traverse_func, void* closure)
{
    plutovg_path_iterator_t it;
    plutovg_path_iterator_init(&it, path);
    plutovg_point_t points[3];

    while(plutovg_path_iterator_has_next(&it)) {
        switch(plutovg_path_iterator_next(&it, points)) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_MOVE_TO, points, 1);
            break;
        case PLUTOVG_PATH_COMMAND_LINE_TO:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_LINE_TO, points, 1);
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_CUBIC_TO, points, 3);
            break;
        case PLUTOVG_PATH_COMMAND_CLOSE:
            traverse_func(closure, PLUTOVG_PATH_COMMAND_CLOSE, points, 1);
            break;
        }
    }
}

typedef struct {
    float x1; float y1;
    float x2; float y2;
    float x3; float y3;
    float x4; float y4;
} bezier_curve_t;

static inline void subdivide_bezier(const bezier_curve_t* original, bezier_curve_t* first_half, bezier_curve_t* second_half)
{
    float mid_x = (original->x2 + original->x3) * 0.5f;
    float mid_y = (original->y2 + original->y3) * 0.5f;

    first_half->x2 = (original->x1 + original->x2) * 0.5f;
    second_half->x3 = (original->x3 + original->x4) * 0.5f;
    first_half->x1 = original->x1;
    second_half->x4 = original->x4;

    first_half->x3 = (first_half->x2 + mid_x) * 0.5f;
    second_half->x2 = (second_half->x3 + mid_x) * 0.5f;
    first_half->x4 = second_half->x1 = (first_half->x3 + second_half->x2) * 0.5f;

    mid_y = (original->y2 + original->y3) * 0.5f;

    first_half->y2 = (original->y1 + original->y2) * 0.5f;
    second_half->y3 = (original->y3 + original->y4) * 0.5f;
    first_half->y1 = original->y1;
    second_half->y4 = original->y4;

    first_half->y3 = (first_half->y2 + mid_y) * 0.5f;
    second_half->y2 = (second_half->y3 + mid_y) * 0.5f;
    first_half->y4 = second_half->y1 = (first_half->y3 + second_half->y2) * 0.5f;
}

void plutovg_path_traverse_flatten(const plutovg_path_t* path, plutovg_path_traverse_func_t traverse_func, void* closure)
{
    if(path->num_curves == 0) {
        plutovg_path_traverse(path, traverse_func, closure);
        return;
    }

    const float tolerance = 0.25f;
    plutovg_path_iterator_t it;
    plutovg_path_iterator_init(&it, path);
    bezier_curve_t curve_stack[32];
    plutovg_point_t points[3];
    plutovg_point_t last_point = {0, 0};

    while(plutovg_path_iterator_has_next(&it)) {
        plutovg_path_command_t cmd = plutovg_path_iterator_next(&it, points);
        switch(cmd) {
        case PLUTOVG_PATH_COMMAND_MOVE_TO:
        case PLUTOVG_PATH_COMMAND_LINE_TO:
        case PLUTOVG_PATH_COMMAND_CLOSE:
            traverse_func(closure, cmd, points, 1);
            last_point = points[0];
            break;
        case PLUTOVG_PATH_COMMAND_CUBIC_TO:
            curve_stack[0].x1 = last_point.x;
            curve_stack[0].y1 = last_point.y;
            curve_stack[0].x2 = points[0].x;
            curve_stack[0].y2 = points[0].y;
            curve_stack[0].x3 = points[1].x;
            curve_stack[0].y3 = points[1].y;
            curve_stack[0].x4 = points[2].x;
            curve_stack[0].y4 = points[2].y;

            bezier_curve_t* current_curve = curve_stack;

            while(current_curve >= curve_stack) {
                float diff_x = current_curve->x4 - current_curve->x1;
                float diff_y = current_curve->y4 - current_curve->y1;
                float perimeter = fabsf(diff_x) + fabsf(diff_y);
                float deviation;

                if(perimeter > 1.f) {
                    deviation = fabsf(diff_x * (current_curve->y1 - current_curve->y2) - 
                                    diff_y * (current_curve->x1 - current_curve->x2)) +
                               fabsf(diff_x * (current_curve->y1 - current_curve->y3) - 
                                    diff_y * (current_curve->x1 - current_curve->x3));
                } else {
                    deviation = fabsf(current_curve->x1 - current_curve->x2) + 
                               fabsf(current_curve->y1 - current_curve->y2) +
                               fabsf(current_curve->x1 - current_curve->x3) + 
                               fabsf(current_curve->y1 - current_curve->y3);
                    perimeter = 1.f;
                }

                if(deviation < tolerance * perimeter || current_curve == curve_stack + 31) {
                    plutovg_point_t endpoint = { current_curve->x4, current_curve->y4 };
                    traverse_func(closure, PLUTOVG_PATH_COMMAND_LINE_TO, &endpoint, 1);
                    --current_curve;
                } else {
                    subdivide_bezier(current_curve, current_curve + 1, current_curve);
                    ++current_curve;
                }
            }
            last_point = points[2];
            break;
        }
    }
}

typedef struct {
    const float* dash_pattern; 
    int pattern_length;
    float phase_offset; 
    float current_phase;
    int pattern_index;
    bool segment_state;
    plutovg_point_t previous_point;
    plutovg_path_traverse_func_t callback;
    void* user_data;
} dash_processor_t;

static void process_dashed_segment(void* closure, plutovg_path_command_t command, const plutovg_point_t* points, int npoints)
{
    dash_processor_t* processor = static_cast<dash_processor_t*>(closure);

    if(command == PLUTOVG_PATH_COMMAND_MOVE_TO) {
        if(processor->segment_state) {
            processor->callback(processor->user_data, PLUTOVG_PATH_COMMAND_MOVE_TO, points, npoints);
        }
        processor->previous_point = points[0];
        processor->current_phase = processor->phase_offset;
        processor->pattern_index = processor->pattern_length;
        processor->segment_state = processor->segment_state;
        return;
    }

    assert(command == PLUTOVG_PATH_COMMAND_LINE_TO || command == PLUTOVG_PATH_COMMAND_CLOSE);

    plutovg_point_t start = processor->previous_point;
    plutovg_point_t end = points[0];
    float delta_x = end.x - start.x;
    float delta_y = end.y - start.y;
    float total_distance = sqrtf(delta_x * delta_x + delta_y * delta_y);
    float processed_distance = 0.f;

    while(total_distance - processed_distance > processor->dash_pattern[processor->pattern_index % processor->pattern_length] - processor->current_phase) {
        processed_distance += processor->dash_pattern[processor->pattern_index % processor->pattern_length] - processor->current_phase;
        float ratio = processed_distance / total_distance;
        plutovg_point_t intermediate = { start.x + ratio * delta_x, start.y + ratio * delta_y };

        if(processor->segment_state) {
            processor->callback(processor->user_data, PLUTOVG_PATH_COMMAND_LINE_TO, &intermediate, 1);
        } else {
            processor->callback(processor->user_data, PLUTOVG_PATH_COMMAND_MOVE_TO, &intermediate, 1);
        }

        processor->current_phase = 0.f;
        processor->segment_state = !processor->segment_state;
        processor->pattern_index++;
    }

    if(processor->segment_state) {
        processor->callback(processor->user_data, PLUTOVG_PATH_COMMAND_LINE_TO, &end, 1);
    }

    processor->current_phase += total_distance - processed_distance;
    processor->previous_point = end;
}

void plutovg_path_traverse_dashed(const plutovg_path_t* path, float offset, const float* dashes, int ndashes, plutovg_path_traverse_func_t traverse_func, void* closure)
{
    float total_dash_length = 0.f;
    for(int i = 0; i < ndashes; ++i) {
        total_dash_length += dashes[i];
    }

    if(ndashes % 2 == 1) {
        total_dash_length *= 2.f;
    }

    if(total_dash_length <= 0.f) {
        plutovg_path_traverse(path, traverse_func, closure);
        return;
    }

    dash_processor_t processor;
    processor.dash_pattern = dashes;
    processor.pattern_length = ndashes;
    processor.phase_offset = fmodf(offset, total_dash_length);

    if(processor.phase_offset < 0.f) {
        processor.phase_offset += total_dash_length;
    }

    processor.pattern_index = 0;
    processor.segment_state = true;
    processor.current_phase = processor.phase_offset;

    while(processor.current_phase > 0.f && processor.pattern_index < processor.pattern_length) {
        if(processor.current_phase >= processor.dash_pattern[processor.pattern_index]) {
            processor.current_phase -= processor.dash_pattern[processor.pattern_index];
            processor.segment_state = !processor.segment_state;
            processor.pattern_index++;
        } else {
            break;
        }
    }

    processor.previous_point = PLUTOVG_EMPTY_POINT;
    processor.callback = traverse_func;
    processor.user_data = closure;

    plutovg_path_traverse_flatten(path, process_dashed_segment, &processor);
}

plutovg_path_t* plutovg_path_clone(const plutovg_path_t* path)
{
    plutovg_path_t* copy = plutovg_path_create();
    if(copy && path->elements.size > 0) {
        int size = path->elements.size;
        plutovg_path_reserve(copy, size);
        for(int i = 0; i < size; ++i) {
            copy->elements.data[i] = path->elements.data[i];
        }
        copy->elements.size = size;
        copy->start_point = path->start_point;
        copy->num_points = path->num_points;
        copy->num_contours = path->num_contours;
        copy->num_curves = path->num_curves;
    }
    return copy;
}

static void copy_element_callback(void* closure, plutovg_path_command_t command, const plutovg_point_t* points, int npoints)
{
    plutovg_path_t* target = static_cast<plutovg_path_t*>(closure);

    switch(command) {
    case PLUTOVG_PATH_COMMAND_MOVE_TO:
        plutovg_path_move_to(target, points[0].x, points[0].y);
        break;
    case PLUTOVG_PATH_COMMAND_LINE_TO:
        plutovg_path_line_to(target, points[0].x, points[0].y);
        break;
    case PLUTOVG_PATH_COMMAND_CUBIC_TO:
        plutovg_path_cubic_to(target, points[0].x, points[0].y, points[1].x, points[1].y, points[2].x, points[2].y);
        break;
    case PLUTOVG_PATH_COMMAND_CLOSE:
        plutovg_path_close(target);
        break;
    }
}

plutovg_path_t* plutovg_path_clone_flatten(const plutovg_path_t* path)
{
    plutovg_path_t* copy = plutovg_path_create();
    if(copy) {
        int estimated_size = path->elements.size + path->num_curves * 32;
        plutovg_path_reserve(copy, estimated_size);
        plutovg_path_traverse_flatten(path, copy_element_callback, copy);
    }
    return copy;
}

plutovg_path_t* plutovg_path_clone_dashed(const plutovg_path_t* path, float offset, const float* dashes, int ndashes)
{
    plutovg_path_t* copy = plutovg_path_create();
    if(copy) {
        int estimated_size = path->elements.size + path->num_curves * 32;
        plutovg_path_reserve(copy, estimated_size);
        plutovg_path_traverse_dashed(path, offset, dashes, ndashes, copy_element_callback, copy);
    }
    return copy;
}

