UK2Node_LatentAbilityCall::UK2Node_LatentAbilityCall(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	if (!HasAnyFlags(RF_ClassDefaultObject))
		return;

	UK2Node_LatentGameplayTaskCall::RegisterSpecializedTaskNodeClass(GetClass());
}

bool UK2Node_LatentAbilityCall::IsHandling(TSubclassOf<UGameplayTask> TaskClass) const
{
	return TaskClass && TaskClass->IsChildOf(UAbilityTask::StaticClass());
}

bool UK2Node_LatentAbilityCall::IsCompatibleWithGraph(UEdGraph const* TargetGraph) const
{
	const EGraphType GraphKind = TargetGraph->GetSchema()->GetGraphType(TargetGraph);
	const bool bIsPermittedGraph = (GT_Ubergraph == GraphKind || GT_Macro == GraphKind);

	if (!bIsPermittedGraph)
		return false;

	UBlueprint* BlueprintPtr = FBlueprintEditorUtils::FindBlueprintForGraph(TargetGraph);
	if (!BlueprintPtr || !BlueprintPtr->GeneratedClass)
		return false;

	return BlueprintPtr->GeneratedClass->IsChildOf(UGameplayAbility::StaticClass());
}

void UK2Node_LatentAbilityCall::GetMenuActions(FBlueprintActionDatabaseRegistrar& ActionRegistrar) const
{
	struct LocalHelpers
	{
		static void ApplyCustomization(UEdGraphNode* NewNode, bool /*bIsTemplate*/, TWeakObjectPtr<UFunction> FuncPtr)
		{
			UK2Node_LatentAbilityCall* Node = CastChecked<UK2Node_LatentAbilityCall>(NewNode);
			if (!FuncPtr.IsValid())
				return;

			UFunction* Func = FuncPtr.Get();
			FObjectProperty* ReturnProp = CastFieldChecked<FObjectProperty>(Func->GetReturnProperty());

			Node->ProxyFactoryFunctionName = Func->GetFName();
			Node->ProxyFactoryClass        = Func->GetOuterUClass();
			Node->ProxyClass               = ReturnProp->PropertyClass;
		}
	};

	const UClass* DerivedClass = GetClass();
	ActionRegistrar.RegisterClassFactoryActions<UAbilityTask>(
		FBlueprintActionDatabaseRegistrar::FMakeFuncSpawnerDelegate::CreateLambda(
			[DerivedClass](const UFunction* FactoryFunc) -> UBlueprintNodeSpawner*
			{
				UBlueprintNodeSpawner* Spawner = UBlueprintFunctionNodeSpawner::Create(FactoryFunc);
				check(Spawner != nullptr);
				Spawner->NodeClass = DerivedClass;

				TWeakObjectPtr<UFunction> WeakFuncPtr = MakeWeakObjectPtr(const_cast<UFunction*>(FactoryFunc));
				Spawner->CustomizeNodeDelegate = UBlueprintNodeSpawner::FCustomizeNodeDelegate::CreateStatic(
					LocalHelpers::ApplyCustomization, WeakFuncPtr);
				return Spawner;
			})
	);
}

void UK2Node_LatentAbilityCall::ValidateNodeDuringCompilation(class FCompilerResultsLog& MessageLog) const
{
	Super::ValidateNodeDuringCompilation(MessageLog);

	for (TFieldIterator<FProperty> PropIt(ProxyClass); PropIt; ++PropIt)
	{
		FMulticastDelegateProperty* DelegateProp = CastField<FMulticastDelegateProperty>(*PropIt);
		if (!DelegateProp)
			continue;

		if (!DelegateProp->GetBoolMetaData(FK2Node_LatentAbilityCallHelper_RequiresConnection))
			continue;

		UEdGraphPin* ExecPin = FindPin(DelegateProp->GetFName());
		if (!ExecPin || ExecPin->LinkedTo.Num() > 0)
			continue;

		const FText MissingConnectionMsg = FText::Format(
			LOCTEXT("NoConnectionToRequiredExecPin", "@@ - Unhandled event.  You need something connected to the '{0}' pin"),
			FText::FromName(DelegateProp->GetFName())
		);
		MessageLog.Warning(*MissingConnectionMsg.ToString(), this);
	}
}

