namespace {
// Status enumeration for tracking request progress
enum class RequestState {
  PENDING,
  SUCCESS,
  FAILED,
};
}

// Test case: Verify basic lifecycle of async socket communication
TEST(AsyncSocket, BasicAsyncSocketInteraction) {
  const std::string test_message = "ping";
  auto ioLoop = std::make_unique<folly::ScopedEventBaseThread>();

  std::string received_payload;
  std::atomic<RequestState> server_status(RequestState::PENDING);

  ctran::bootstrap::AsyncServerSocket listener(*ioLoop->getEventBase());

  // Bind server to localhost IPv6 with dynamic port
  auto listen_addr_future = listener.start(
      folly::SocketAddress("::1", 0),
      test_message.size(),
      [&received_payload, &server_status](std::unique_ptr<folly::IOBuf> buffer) {
        received_payload = buffer->moveToFbString().toStdString();
        server_status.store(RequestState::SUCCESS);
      });

  // Validate server binding
  auto server_endpoint = std::move(listen_addr_future).get();
  EXPECT_EQ(server_endpoint.getFamily(), AF_INET6);
  EXPECT_NE(server_endpoint.getPort(), 0);
  EXPECT_EQ(server_endpoint.getIPAddress().str(), "::1");

  // Initiate client-side send
  std::atomic<RequestState> client_status(RequestState::PENDING);
  ctran::bootstrap::AsyncClientSocket::send(
      *ioLoop->getEventBase(),
      server_endpoint,
      test_message.data(),
      test_message.size(),
      [&client_status](const folly::AsyncSocketException* exception) {
        client_status.store(exception ? RequestState::FAILED : RequestState::SUCCESS);
      });

  // Poll until client operation completes
  while (client_status.load() == RequestState::PENDING) {
    std::this_thread::yield();
  }
  EXPECT_EQ(client_status.load(), RequestState::SUCCESS);

  // Poll until server receives message
  while (server_status.load() == RequestState::PENDING) {
    std::this_thread::yield();
  }
  EXPECT_EQ(server_status.load(), RequestState::SUCCESS);
  EXPECT_EQ(received_payload, test_message);

  // Gracefully shut down server
  auto shutdown_future = listener.stop();
  EXPECT_EQ(folly::unit, std::move(shutdown_future).get());
}

// Test case: Ensure ordered delivery of multiple messages via async server
TEST(AsyncSocket, OrderedMultiMessageDelivery) {
  struct MessagePacket {
    char content;
    int sequence_id;
  };

  const std::string original_data = "abcdefghijk";
  auto ioLoop = std::make_unique<folly::ScopedEventBaseThread>();

  std::atomic<int> total_received(0);
  int expected_sequence = 0;
  std::unordered_map<int, char> out_of_order_buffer;
  std::string assembled_output;

  ctran::bootstrap::AsyncServerSocket listener(*ioLoop->getEventBase());

  auto listen_addr_future = listener.start(
      folly::SocketAddress("::1", 0),
      sizeof(MessagePacket),
      [&total_received, &expected_sequence, &out_of_order_buffer, &assembled_output](
          std::unique_ptr<folly::IOBuf> buffer) {
        MessagePacket packet;
        std::memcpy(&packet, buffer->data(), sizeof(MessagePacket));

        out_of_order_buffer[packet.sequence_id] = packet.content;

        // Assemble in-order output
        while (out_of_order_buffer.find(expected_sequence) != out_of_order_buffer.end()) {
          assembled_output += out_of_order_buffer[expected_sequence];
          out_of_order_buffer.erase(expected_sequence++);
        }

        total_received.fetch_add(1);
      });

  auto server_endpoint = std::move(listen_addr_future).get();
  EXPECT_EQ(server_endpoint.getFamily(), AF_INET6);
  EXPECT_NE(server_endpoint.getPort(), 0);
  EXPECT_EQ(server_endpoint.getIPAddress().str(), "::1");

  // Prepare and dispatch all messages
  std::vector<std::atomic<RequestState>> send_results(original_data.size());
  for (auto& result : send_results) {
    result.store(RequestState::PENDING);
  }

  std::vector<MessagePacket> packets(original_data.size());
  for (size_t i = 0; i < original_data.size(); ++i) {
    packets[i] = {original_data[i], static_cast<int>(i)};

    ctran::bootstrap::AsyncClientSocket::send(
        *ioLoop->getEventBase(),
        server_endpoint,
        &packets[i],
        sizeof(MessagePacket),
        [status = &send_results[i]](const folly::AsyncSocketException* err) {
          status->store(err ? RequestState::FAILED : RequestState::SUCCESS);
        });
  }

  // Wait for all sends to complete
  for (size_t i = 0; i < original_data.size(); ++i) {
    while (send_results[i].load() == RequestState::PENDING) {
      std::this_thread::yield();
    }
    EXPECT_EQ(send_results[i].load(), RequestState::SUCCESS);
  }

  // Wait for full reception and ordering
  while (total_received.load() < static_cast<int>(original_data.size())) {
    std::this_thread::yield();
  }

  EXPECT_EQ(assembled_output, original_data);

  // Cleanup server resources
  auto shutdown_future = listener.stop();
  EXPECT_EQ(folly::unit, std::move(shutdown_future).get());
}

// Test case: Confirm failure handling when connecting to invalid endpoint
TEST(AsyncSocket, ConnectionFailureHandling) {
  const std::string test_message = "ping";
  auto ioLoop = std::make_unique<folly::ScopedEventBaseThread>();

  folly::SocketAddress invalid_address;
  std::atomic<RequestState> outcome(RequestState::PENDING);

  ctran::bootstrap::AsyncClientSocket::send(
      *ioLoop->getEventBase(),
      invalid_address,
      test_message.data(),
      test_message.size(),
      [&outcome](const folly::AsyncSocketException* error) {
        outcome.store(error ? RequestState::FAILED : RequestState::SUCCESS);
      });

  // Wait for connection attempt to fail
  while (outcome.load() == RequestState::PENDING) {
    std::this_thread::yield();
  }

  EXPECT_EQ(outcome.load(), RequestState::FAILED);
}

// Test case: Server timeout on idle connections without data transfer
TEST(AsyncSocket, ServerTimeoutOnNoData) {
  const std::string test_message = "ping";
  auto ioLoop = std::make_unique<folly::ScopedEventBaseThread>();

  std::atomic<bool> callback_executed(false);
  ctran::bootstrap::AsyncServerSocket listener(*ioLoop->getEventBase());

  auto listen_addr_future = listener.start(
      folly::SocketAddress("::1", 0),
      test_message.size(),
      [&callback_executed](std::unique_ptr<folly::IOBuf>) {
        XLOGF(INFO, "Unexpected receive callback triggered");
        callback_executed.store(true);
      },
      std::chrono::milliseconds(500)); // Short timeout

  auto server_endpoint = std::move(listen_addr_future).get();

  // Establish connection but do not send data
  ctran::bootstrap::Socket silent_client;
  ASSERT_EQ(0, silent_client.connect(server_endpoint, "lo"));
  XLOG(INFO) << "Client connected but will not transmit";

  // Allow sufficient time for timeout to trigger
  std::this_thread::sleep_for(std::chrono::milliseconds(1000));

  EXPECT_FALSE(callback_executed.load())
      << "Callback should not be invoked before receiving expected data";

  // Clean up
  silent_client.close();
  auto shutdown_future = listener.stop();
  std::move(shutdown_future).get();
}

// Test case: Server timeout when only partial data arrives
TEST(AsyncSocket, ServerTimeoutWithPartialData) {
  constexpr size_t expected_bytes = 100;
  auto ioLoop = std::make_unique<folly::ScopedEventBaseThread>();

  std::atomic<bool> callback_executed(false);
  ctran::bootstrap::AsyncServerSocket listener(*ioLoop->getEventBase());

  auto listen_addr_future = listener.start(
      folly::SocketAddress("::1", 0),
      expected_bytes,
      [&callback_executed](std::unique_ptr<folly::IOBuf>) {
        XLOGF(INFO, "Unexpected receive callback triggered");
        callback_executed.store(true);
      },
      std::chrono::milliseconds(500));

  auto server_endpoint = std::move(listen_addr_future).get();

  // Connect and send only half the required bytes
  ctran::bootstrap::Socket partial_sender;
  ASSERT_EQ(0, partial_sender.connect(server_endpoint, "lo"));

  const std::string insufficient_data(50, 'x');
  ASSERT_EQ(0, partial_sender.send(insufficient_data.data(), insufficient_data.size()));
  XLOGF(INFO, "Sent {} bytes (expected {})", insufficient_data.size(), expected_bytes);

  // Wait for timeout period
  std::this_thread::sleep_for(std::chrono::milliseconds(1000));

  EXPECT_FALSE(callback_executed.load())
      << "Callback should not execute with incomplete data before timeout";

  // Final cleanup
  partial_sender.close();
  auto shutdown_future = listener.stop();
  std::move(shutdown_future).get();
}

#include <Python.h>

// Custom iterator structure for bytearray objects
typedef struct {
    PyObject_HEAD
    Py_ssize_t current_index;
    PyByteArrayObject *bytearray_ref; /* NULL when iteration is complete */
} bytearray_iterator;

// Cleanup function: untrack from GC, release reference to bytearray, free memory
static void
bytearray_iterator_dealloc(bytearray_iterator *iter)
{
    _PyObject_GC_UNTRACK(iter);
    Py_XDECREF(iter->bytearray_ref);
    PyObject_GC_Del(iter);
}

// Garbage collector traversal: visit the referenced bytearray object
static int
bytearray_iterator_traverse(bytearray_iterator *iter, visitproc visit, void *arg)
{
    Py_VISIT(iter->bytearray_ref);
    return 0;
}

// Return next item in iteration
static PyObject *
bytearray_iterator_next(bytearray_iterator *iter)
{
    PyByteArrayObject *ba;
    PyObject *val;

    if (iter == NULL)
        return NULL;

    ba = iter->bytearray_ref;
    if (ba == NULL)
        return NULL;

    if (!PyByteArray_Check(ba))
        return NULL;

    if (iter->current_index < PyByteArray_GET_SIZE(ba)) {
        unsigned char byte_val = (unsigned char)ba->ob_bytes[iter->current_index];
        val = PyLong_FromLong((long)byte_val);  // Use PyLong instead of deprecated PyInt
        if (val != NULL)
            ++iter->current_index;
        return val;
    }

    // Exhausted: clear reference and decrement refcount
    iter->bytearray_ref = NULL;
    Py_DECREF(ba);
    return NULL;
}

// Provide length hint: remaining items count
static PyObject *
bytearray_iterator_length_hint(bytearray_iterator *iter)
{
    Py_ssize_t remaining = 0;
    if (iter->bytearray_ref != NULL) {
        remaining = PyByteArray_GET_SIZE(iter->bytearray_ref) - iter->current_index;
    }
    return PyLong_FromSsize_t(remaining);
}

// Method definition for __length_hint__
PyDoc_STRVAR(length_hint_doc,
    "Private method returning an estimate of len(list(it)).");

static PyMethodDef bytearray_iterator_methods[] = {
    {"__length_hint__", (PyCFunction)bytearray_iterator_length_hint, METH_NOARGS,
     length_hint_doc},
    {NULL, NULL}
};

// Define the type object for bytearray iterator
PyTypeObject PyByteArrayIter_Type = {
    PyVarObject_HEAD_INIT(&PyType_Type, 0)
    "bytearray_iterator",              /* tp_name */
    sizeof(bytearray_iterator),        /* tp_basicsize */
    0,                                 /* tp_itemsize */
    (destructor)bytearray_iterator_dealloc, /* tp_dealloc */
    0,                                 /* tp_print */
    0,                                 /* tp_getattr */
    0,                                 /* tp_setattr */
    0,                                 /* tp_compare */
    0,                                 /* tp_repr */
    0,                                 /* tp_as_number */
    0,                                 /* tp_as_sequence */
    0,                                 /* tp_as_mapping */
    0,                                 /* tp_hash */
    0,                                 /* tp_call */
    0,                                 /* tp_str */
    PyObject_GenericGetAttr,           /* tp_getattro */
    0,                                 /* tp_setattro */
    0,                                 /* tp_as_buffer */
    Py_TPFLAGS_DEFAULT | Py_TPFLAGS_HAVE_GC, /* tp_flags */
    "Iterator over bytearray elements", /* tp_doc */
    (traverseproc)bytearray_iterator_traverse, /* tp_traverse */
    0,                                 /* tp_clear */
    0,                                 /* tp_richcompare */
    0,                                 /* tp_weaklistoffset */
    PyObject_SelfIter,                 /* tp_iter */
    (iternextfunc)bytearray_iterator_next, /* tp_iternext */
    bytearray_iterator_methods,        /* tp_methods */
};

// Factory function to create a new bytearray iterator
static PyObject *
bytearray_new_iterator(PyObject *seq)
{
    bytearray_iterator *iter;

    if (!PyByteArray_Check(seq)) {
        PyErr_BadInternalCall();
        return NULL;
    }

    iter = PyObject_GC_New(bytearray_iterator, &PyByteArrayIter_Type);
    if (iter == NULL)
        return NULL;

    iter->current_index = 0;
    Py_INCREF(seq);
    iter->bytearray_ref = (PyByteArrayObject *)seq;
    _PyObject_GC_TRACK(iter);

    return (PyObject *)iter;
}

