    OperationStatus current_state;
    int message_id;
    std::string method_name;
    json parameters;
  };

 private:
  static std::string HandleRequest(TimeNano start_time, const Task* task);
  static std::string ExecuteServiceCall(
      TimeNano start_time, int msg_id, std::string method,
      MethodHandler handler, json args,
      const std::map<std::string, ParamsList>& param_registry,
      const std::string& service_name, const Logger& logger,
      const ClientAuthorization* auth_ptr);

  static void PipeEventCallback(nng_pipe pipe, nng_pipe_ev ev, void* arg) {
    reinterpret_cast<ServiceManager::Impl*>(arg)->OnPipeEvent(pipe, ev);
  }

  template <typename T>
  static std::string EncodeResponse(const T& response_obj);

  struct MethodSorter {
    bool operator()(const ServiceMethod& lhs, const ServiceMethod& rhs) const {
      return lhs.GetName().size() < rhs.GetName().size();
    }
  };

  void SpawnTask(nng_socket sock, const Impl* owner, Task* new_task);
  static void ClearTask(Task* t);
  static void DispatchTask(Task* t);
  static void TaskDispatcher(void* data);
  void OnPipeEvent(nng_pipe pipe, nng_pipe_ev ev);

  static constexpr const char* kDefaultBindAddress = "*";
  static constexpr int kDefaultPort = 8990;

  nng_socket socket_ = NNG_SOCKET_INITIALIZER;

  static constexpr int kMaxTasks = 64;
  static constexpr float kApiVersionNumber = 1.0f;
  static constexpr EncodingFormat kEncoding = EncodingFormat::kMsgpackJSON;

  std::string component_name_;
  Logger logger_;
  std::string bind_address_;
  int port_number_;
  nng_socket communication_socket_;
  ClientAuthorization authorization_;
  std::atomic<bool> running_flag_;
  std::map<std::string, MethodHandler> method_table_;
  std::map<std::string, ParamsList> parameter_table_;
  mutable std::shared_timed_mutex mutex_;
  Task tasks_[kMaxTasks];
};

// ============================================================================
ServiceManager::ServiceManager(const Logger& logger,
                               const ClientAuthorization& client_auth)
    : pimpl_(std::make_shared<Impl>(logger, client_auth)) {}

ServiceManager::ServiceManager(const Logger& logger)
    : pimpl_(std::make_shared<Impl>(logger, ClientAuthorization())) {}

void ServiceManager::Load(const json& cfg) { pimpl_->Load(cfg); }

void ServiceManager::RegisterMethod(const ServiceMethod& method,
                                    MethodHandler handler) {
  pimpl_->RegisterMethod(method, handler);
}

void ServiceManager::RemoveMethod(const ServiceMethod& method) {
  pimpl_->RemoveMethod(method);
}

void ServiceManager::ClearAllMethods() { pimpl_->ClearAllMethods(); }

void ServiceManager::Activate() { pimpl_->Activate(); }

void ServiceManager::Deactivate() { pimpl_->Deactivate(); }

// ============================================================================
ServiceManager::Impl::Impl(const Logger& logger,
                           const ClientAuthorization& auth)
    : logger_(logger),
      component_name_(Constant::Component::service_manager),
      port_number_(kDefaultPort),
      communication_socket_(socket_),
      authorization_(auth) {}

void ServiceManager::Impl::Load(const json& cfg) {
  bind_address_ = JsonUtils::GetString(cfg, Constant::Config::ip, kDefaultBindAddress);
  port_number_ = JsonUtils::GetInteger(cfg, Constant::Config::port, kDefaultPort);
}

void ServiceManager::Impl::Activate() {
  std::unique_lock<std::shared_timed_mutex> lock(mutex_);
  logger_.LogTrace(component_name_, "Initializing service manager");

  int status = nng_rep0_open(&communication_socket_);
  if (status != 0) {
    std::string err_msg = nng_strerror(status);
    logger_.LogError(component_name_, "Failed to open REP socket: %s", err_msg.c_str());
    throw Error("Socket initialization failed.");
  }

  // Initialize task slots
  for (int i = 0; i < kMaxTasks; ++i) {
    SpawnTask(communication_socket_, this, &tasks_[i]);
  }

  // Set up pipe event listener
  status = nng_pipe_notify(communication_socket_, NNG_PIPE_EV_REM_POST,
                           &Impl::PipeEventCallback, this);
  if (status != 0) {
    std::string err_msg = nng_strerror(status);
    logger_.LogError(component_name_, "Pipe notification setup failed: %s", err_msg.c_str());
    throw Error("Pipe notification setup failed.");
  }

  std::ostringstream addr_stream;
  addr_stream << "tcp://" << bind_address_ << ":" << port_number_;
  std::string endpoint = addr_stream.str();

  if ((status = nng_listen(communication_socket_, endpoint.c_str(), nullptr, 0)) != 0) {
    std::string err_msg = "Listen failed with code: " + std::to_string(status);
    logger_.LogError(component_name_, "%s", err_msg.c_str());
    throw Error(err_msg);
  }

  running_flag_ = true;

  // Kick off async processing
  for (int i = 0; i < kMaxTasks; ++i) {
    TaskDispatcher(&tasks_[i]);
  }

  logger_.LogTrace(component_name_, "Listening on %s", endpoint.c_str());
}

void ServiceManager::Impl::Deactivate() {
  std::unique_lock<std::shared_timed_mutex> lock(mutex_);
  logger_.LogTrace(component_name_, "Shutting down service manager");
  running_flag_ = false;

  int close_result = nng_close(communication_socket_);
  if (close_result != 0) {
    logger_.LogError(component_name_, "Close error: %s", nng_strerror(close_result));
  }

  for (int i = 0; i < kMaxTasks; ++i) {
    nng_aio_free(tasks_[i].aio_handle);
  }

  communication_socket_ = socket_;
}

void ServiceManager::Impl::RegisterMethod(const ServiceMethod& method,
                                          MethodHandler handler) {
  method_table_.emplace(method.GetName(), handler);
  parameter_table_.emplace(method.GetName(), method.GetParamsList());
}

void ServiceManager::Impl::RemoveMethod(const ServiceMethod& method) {
  const auto& name = method.GetName();
  auto it = method_table_.find(name);
  if (it == method_table_.end()) {
    logger_.LogWarning(component_name_, "Method '%s' not found in registry.", name.c_str());
    return;
  }
  method_table_.erase(it);
  logger_.LogVerbose(component_name_, "Removed method '%s'", name.c_str());
}

void ServiceManager::Impl::ClearAllMethods() {
  method_table_.clear();
  logger_.LogVerbose(component_name_, "Cleared all registered methods");
}

std::string ServiceManager::Impl::HandleRequest(TimeNano start_time,
                                                const Task* task) {
  int id = task->message_id;
  const auto& requested_method = task->method_name;
  auto iter = task->registered_methods->find(requested_method);

  if (iter == task->registered_methods->end()) {
    std::string msg = "Unsupported method: " + requested_method;
    json error = {{"code", 1.0}, {"message", msg}};
    return EncodeResponse(ResponseFailureMessage(id, error, kApiVersionNumber));
  }

  MethodHandler handler = iter->second;
  std::string full_name = *(task->owner_name) + ":::" + requested_method;

  return ExecuteServiceCall(start_time, id, requested_method, handler,
                            task->parameters, *(task->registered_params),
                            full_name, *(task->logging_service),
                            task->auth_checker);
}

std::string ServiceManager::Impl::ExecuteServiceCall(
    TimeNano start_time, int id, std::string method_name,
    MethodHandler handler, json params,
    const std::map<std::string, ParamsList>& param_registry,
    const std::string& service_name, const Logger& logger,
    const ClientAuthorization* auth_ptr) {
  std::vector<json> positional_args;
  bool valid = true;
  std::string error_message;

  const auto& expected_params = param_registry.at(method_name);

  for (const auto& param_name : expected_params) {
    if (param_name == "_service_method_start_time") {
      positional_args.emplace_back(json(start_time));
      continue;
    }

    if (!param_name.empty()) {
      if (!params.contains(param_name)) {
        error_message = "Missing required parameter '" + param_name +
                        "' when calling " + method_name +
                        ". Provided: " + params.dump();
        valid = false;
        break;
      }
      positional_args.emplace_back(params.at(param_name));
    }
  }

  if (valid) {
    if (!auth_ptr->IsAuthorizedMethod(method_name)) {
      json error{{"code", 4.0}, {"message", "Unauthorized access"}};
      return EncodeResponse(ResponseFailureMessage(id, error, kApiVersionNumber));
    }

    try {
      auto result = handler(positional_args);
      return EncodeResponse(ResponseSuccessMessage(id, result, kApiVersionNumber));
    } catch (const Error& e) {
      json error{{"code", 1.0}, {"message", e.what()}};
      return EncodeResponse(ResponseFailureMessage(id, error, kApiVersionNumber));
    } catch (const std::exception& e) {
      json error{{"code", 2.0}, {"message", e.what()}};
      return EncodeResponse(ResponseFailureMessage(id, error, kApiVersionNumber));
    } catch (...) {
      json error{{"code", 2.0}, {"message", "[ServiceManager] Unknown exception"}};
      return EncodeResponse(ResponseFailureMessage(id, error, kApiVersionNumber));
    }
  } else {
    json error{{"code", 3.0}, {"message", error_message}};
    return EncodeResponse(ResponseFailureMessage(id, error, kApiVersionNumber));
  }
}

void ServiceManager::Impl::TaskDispatcher(void* data) {
  DispatchTask(static_cast<Task*>(data));
}

void ServiceManager::Impl::DispatchTask(Task* task) {
  if (!task->owner_liveness->load()) return;

  RequestMessage request_msg;
  const char* raw_buffer;
  std::string buffer_str;
  std::string response_str;
  nng_msg* incoming_msg = nullptr;
  nng_msg* outgoing_msg = nullptr;
  int rv;
  TimeNano call_start = SimClock::Get()->NowSimNanos();

  if (task->current_state == OperationStatus::kIdle) {
    // Handle previous send completion
    if ((rv = nng_aio_result(task->aio_handle)) != 0) {
      // Optional: log send failure
    }

    ClearTask(task);
    task->current_state = OperationStatus::kActive;
    nng_ctx_recv(task->context, task->aio_handle);
    return;
  }

  if (task->current_state == OperationStatus::kActive) {
    if ((rv = nng_aio_result(task->aio_handle)) != 0) {
      // Optional: log receive failure
    }

    incoming_msg = nng_aio_get_msg(task->aio_handle);
    if (!incoming_msg) {
      response_str = "Invalid request received.";
    } else {
      raw_buffer = static_cast<const char*>(nng_msg_body(incoming_msg));
      size_t len = nng_msg_len(incoming_msg);
      buffer_str.assign(raw_buffer, len);

      if (len < 1) {
        response_str = "Empty or malformed request.";
      } else {
        try {
          switch (kEncoding) {
            case EncodingFormat::kPureJSON:
              request_msg.DeserializeFromJsonStr(buffer_str);
              break;
            case EncodingFormat::kMsgpackJSON:
            default:
              request_msg.Deserialize(buffer_str);
              break;
          }

          task->message_id = request_msg.GetID();
          task->method_name = request_msg.GetMethod();
          task->parameters = request_msg.GetParams();

          response_str = HandleRequest(call_start, task);
        } catch (...) {
          response_str = "Malformed request.";
        }
      }
    }

    if ((rv = nng_msg_alloc(&outgoing_msg, response_str.size())) != 0) {
      // Allocation failed — cleanup
      if (outgoing_msg) nng_msg_free(outgoing_msg);
    } else {
      std::memcpy(nng_msg_body(outgoing_msg), response_str.c_str(),
                  response_str.size());
      nng_aio_set_msg(task->aio_handle, outgoing_msg);
    }

    task->current_state = OperationStatus::kIdle;
    nng_ctx_send(task->context, task->aio_handle);
    return;
  }

  // Invalid state — do nothing
}

void ServiceManager::Impl::SpawnTask(nng_socket sock, const Impl* owner,
                                     Task* new_task) {
  if (!new_task) return;

  int rv;
  if ((rv = nng_aio_alloc(&new_task->aio_handle, &Impl::TaskDispatcher,
                          new_task)) != 0) {
    logger_.LogError(owner->component_name_, "AIO allocation failed: %d", rv);
  }

  if ((rv = nng_ctx_open(&new_task->context, sock)) != 0) {
    logger_.LogError(owner->component_name_, "Context open failed: %d", rv);
  }

  new_task->registered_methods = &owner->method_table_;
  new_task->registered_params = &owner->parameter_table_;
  new_task->owner_name = &owner->component_name_;
  new_task->owner_liveness = &owner->running_flag_;
  new_task->logging_service = &owner->logger_;
  new_task->auth_checker = &owner->authorization_;
  new_task->current_state = OperationStatus::kIdle;
  ClearTask(new_task);
}

void ServiceManager::Impl::ClearTask(Task* t) {
  t->message_id = -1;
  t->method_name.clear();
  t->parameters = json();
}

void ServiceManager::Impl::OnPipeEvent(nng_pipe pipe, nng_pipe_ev ev) {
  if (ev == NNG_PIPE_EV_REM_POST) {
    logger_.LogVerbose(component_name_,
                       "Client disconnected — resetting authorization");
    authorization_.SetToken(nullptr, 0);
  }
}

template <typename T>
std::string ServiceManager::Impl::EncodeResponse(const T& msg) {
  switch (kEncoding) {
    case EncodingFormat::kPureJSON:
      return msg.SerializeToJsonStr();
    case EncodingFormat::kMsgpackJSON:
    default:
      return msg.Serialize();
  }
}

