#include <stdlib.h>

// Helper macro to get pointer to the i-th element (1-indexed)
#define table_ptr(i) (((char*)table_base) + (member_size * ((i)-1)))

// Swap two memory blocks of given size using temporary buffer
void swap_blocks(char* dst, char* src, size_t cnt) {
    char* p = src;
    char* q = dst;
    for (size_t n = cnt; n > 0; --n) {
        char temp = *p;
        *p++ = *q;
        *q++ = temp;
    }
}

// Comparison function type definition (assumed from usage)
typedef int (*_compare_function)(const void*, const void*);

// Heap-based sorting implementation (heap sort)
void qsort(void* table_base, size_t num_members, size_t member_size, _compare_function compare_members) {
    if (num_members < 2)
        return;

    // Build max heap
    for (size_t i = num_members / 2; i >= 1; --i) {
        size_t j = i;
        while (j * 2 <= num_members) {
            size_t child = j * 2;
            char* parent_ptr = table_ptr(j);
            char* left_child_ptr = table_ptr(child);

            // Find larger child if right child exists and is greater
            if (child < num_members && compare_members(left_child_ptr, table_ptr(child + 1)) < 0) {
                child++;
                left_child_ptr += member_size;
            }

            // If parent is smaller than largest child, swap and continue
            if (compare_members(parent_ptr, left_child_ptr) < 0) {
                swap_blocks(parent_ptr, left_child_ptr, member_size);
                j = child;
            } else {
                break;
            }
        }
    }

    // Extract elements one by one
    for (size_t end = num_members; end > 1; --end) {
        // Move current root to end
        swap_blocks(table_ptr(1), table_ptr(end), member_size);

        // Restore heap property for reduced heap
        size_t j = 1;
        while (j * 2 <= end - 1) {
            size_t child = j * 2;
            char* parent_ptr = table_ptr(j);
            char* left_child_ptr = table_ptr(child);

            // Find larger child
            if (child < end - 1 && compare_members(left_child_ptr, table_ptr(child + 1)) < 0) {
                child++;
                left_child_ptr += member_size;
            }

            // Swap if necessary
            if (compare_members(parent_ptr, left_child_ptr) < 0) {
                swap_blocks(parent_ptr, left_child_ptr, member_size);
                j = child;
            } else {
                break;
            }
        }
    }
}

