// variable names, and control flow while preserving functionality.
TEST(InifileParserTest, test_options_refactored) {
  using namespace sdb::options;

  // Initialize configuration variables with alternate initial values
  uint64_t buffer_size = 0;
  uint64_t total_buffer_size = 1;
  uint64_t max_buffers = 2;
  uint64_t wal_size_limit = 3;
  uint64_t cache_capacity = 4;
  bool enforce_cache_limit = false;
  uint64_t global_cache_size = 5;
  uint64_t unused_option = 6;
  uint64_t suffixed_val1 = 7;
  uint64_t suffixed_val2 = 8;
  uint64_t suffixed_val3 = 9;
  uint64_t suffixed_val4 = 10;
  uint64_t gb_value = 11;
  uint64_t comment_val = 12;
  bool flag_true = true;
  bool flag_false = false;
  bool flag_unset = true;
  bool flag_default = false;
  double dbl_val1 = -1.0;
  double dbl_val2 = -1.0;
  double dbl_val3 = -1.0;
  std::string str_empty = "default";
  std::string str_val = "initial";
  std::string str_commented = "base";
  std::string str_commented2 = "base2";
  std::string str_notset = "fallback";

  containers::FlatHashSet<std::string> valid_sounds = {
    "foo", "bar", "blub", "snuggles", "slurp", "oink"};
  std::vector<std::string> selected_sounds = {"default_sound"};
  std::vector<std::string> unusual_sounds = {"default_unusual"};

  ProgramOptions cfg("testi", "testi [options]", "description", "/tmp/test");
  cfg.addSection("rocksdb", "RocksDB settings");
  cfg.addOption("--rocksdb.write-buffer-size", "Buffer size",
                new UInt64Parameter(&buffer_size));
  cfg.addOption("--rocksdb.total-write-buffer-size", "Total buffer",
                new UInt64Parameter(&total_buffer_size));
  cfg.addOption("--rocksdb.max-write-buffer-number", "Max buffers",
                new UInt64Parameter(&max_buffers));
  cfg.addOption("--rocksdb.max-total-wal-size", "WAL limit",
                new UInt64Parameter(&wal_size_limit));
  cfg.addOption("--rocksdb.block-cache-size", "Cache capacity",
                new UInt64Parameter(&cache_capacity));
  cfg.addOption("--rocksdb.enforce-block-cache-size-limit", "Enforce limit",
                new BooleanParameter(&enforce_cache_limit));

  cfg.addSection("cache", "Cache section");
  cfg.addOption("--cache.size", "Global cache", new UInt64Parameter(&global_cache_size));
  cfg.addOption("--cache.unused-option", "Unused", new UInt64Parameter(&unused_option));

  cfg.addSection("pork", "Pig options");
  cfg.addOption("--pork.flag-true", "Always true", new BooleanParameter(&flag_true, true));
  cfg.addOption("--pork.flag-false", "Always false", new BooleanParameter(&flag_false, true));
  cfg.addOption("--pork.flag-unset", "Not set", new BooleanParameter(&flag_unset, true));
  cfg.addOption("--pork.flag-default", "Default value", new BooleanParameter(&flag_default, true));
  cfg.addOption("--pork.suffix-mb", "MB suffix", new UInt64Parameter(&suffixed_val1));
  cfg.addOption("--pork.suffix-mib", "MiB suffix", new UInt64Parameter(&suffixed_val2));
  cfg.addOption("--pork.suffix-mb-alt", "Alternative MB", new UInt64Parameter(&suffixed_val3));
  cfg.addOption("--pork.suffix-kb", "KB suffix", new UInt64Parameter(&suffixed_val4));
  cfg.addOption("--pork.suffix-gb", "GB suffix", new UInt64Parameter(&gb_value));
  cfg.addOption("--pork.value-comment", "With comment", new UInt64Parameter(&comment_val));
  cfg.addOption("--pork.double-val", "Double value", new DoubleParameter(&dbl_val1));
  cfg.addOption("--pork.double-comment", "Double with comment", new DoubleParameter(&dbl_val2));
  cfg.addOption("--pork.double-notset", "Double not set", new DoubleParameter(&dbl_val3));
  cfg.addOption("--pork.string-empty", "Empty string", new StringParameter(&str_empty));
  cfg.addOption("--pork.string-value", "String value", new StringParameter(&str_val));
  cfg.addOption("--pork.string-comment", "String with comment", new StringParameter(&str_commented));
  cfg.addOption("--pork.string-comment2", "Another comment", new StringParameter(&str_commented2));
  cfg.addOption("--pork.string-notset", "Not set string", new StringParameter(&str_notset));
  cfg.addOption("--pork.sounds", "Pig sounds",
                new DiscreteValuesVectorParameter<StringParameter>(&selected_sounds, valid_sounds),
                sdb::options::MakeDefaultFlags(options::Flags::FlushOnFirst));
  cfg.addOption("--pork.unusual-sounds", "Unusual pig sounds",
                new DiscreteValuesVectorParameter<StringParameter>(&unusual_sounds, valid_sounds),
                sdb::options::MakeDefaultFlags(options::Flags::FlushOnFirst));

  const char* config_data = R"data(
[rocksdb]
write-buffer-size = 2048000
total-write-buffer-size = 536870912
max-write-buffer-number = 4
max-total-wal-size = 1024000
block-cache-size = 268435456
enforce-block-cache-size-limit = true
[cache]
size = 268435456
[pork]
flag-true = true
flag-false = false
flag-unset = false
suffix-mb = 1M
suffix-mib = 1MiB
suffix-mb-alt = 12MB
suffix-kb = 256kb
suffix-gb = 256GB
value-comment = 12345#1234M
double-val = 335.25
double-comment = 2948.434#343
string-empty =
string-value = 486hbsbq,r
string-comment = abc#def h
string-comment2 = abc  #def h
sounds = foo
sounds = oink
sounds = snuggles
)data";

  IniFileParser parser(&cfg);
  bool parse_ok = parser.parseContent("config.conf", config_data, true);
  ASSERT_TRUE(parse_ok);

  // Verify parsed values
  EXPECT_EQ(2048000U, buffer_size);
  EXPECT_EQ(536870912U, total_buffer_size);
  EXPECT_EQ(4U, max_buffers);
  EXPECT_EQ(1024000U, wal_size_limit);
  EXPECT_EQ(268435456U, cache_capacity);
  EXPECT_TRUE(enforce_cache_limit);
  EXPECT_EQ(268435456U, global_cache_size);
  EXPECT_EQ(UINT64_MAX, unused_option);
  EXPECT_TRUE(flag_true);
  EXPECT_FALSE(flag_false);
  EXPECT_FALSE(flag_unset);
  EXPECT_FALSE(flag_default);
  EXPECT_EQ(1000000U, suffixed_val1);
  EXPECT_EQ(1048576U, suffixed_val2);
  EXPECT_EQ(12000000U, suffixed_val3);
  EXPECT_EQ(256000U, suffixed_val4);
  EXPECT_EQ(256000000000U, gb_value);
  EXPECT_EQ(12345U, comment_val);
  EXPECT_DOUBLE_EQ(335.25, dbl_val1);
  EXPECT_DOUBLE_EQ(2948.434, dbl_val2);
  EXPECT_DOUBLE_EQ(-1.0, dbl_val3);
  EXPECT_EQ("", str_empty);
  EXPECT_EQ("486hbsbq,r", str_val);
  EXPECT_EQ("abc#def h", str_commented);
  EXPECT_EQ("abc  #def h", str_commented2);
  EXPECT_EQ("fallback", str_notset);

  // Check sound vectors
  auto find_sound = [&selected_sounds](const std::string& s) {
    return std::find(selected_sounds.begin(), selected_sounds.end(), s);
  };
  EXPECT_EQ(selected_sounds.size(), 3U);
  EXPECT_EQ(find_sound("meow"), selected_sounds.end());
  EXPECT_EQ(find_sound("default_sound"), selected_sounds.end());
  auto iter = selected_sounds.begin();
  EXPECT_EQ(find_sound("foo"), iter);
  ++iter;
  EXPECT_EQ(find_sound("oink"), iter);
  ++iter;
  EXPECT_EQ(find_sound("snuggles"), iter);

  // Check unusual sounds
  auto find_unusual = [&unusual_sounds](const std::string& s) {
    return std::find(unusual_sounds.begin(), unusual_sounds.end(), s);
  };
  EXPECT_EQ(unusual_sounds.size(), 2U);
  iter = unusual_sounds.begin();
  EXPECT_EQ(find_unusual("default_unusual"), iter);
  ++iter;
  EXPECT_EQ(find_unusual("snuggles"), iter);
  EXPECT_EQ(find_unusual("blub"), unusual_sounds.end());
}

TEST(InifileParserTest, test_exit_codes_valid_alternate) {
  using namespace sdb::options;
  uint64_t test_value = 0;

  // Test valid large value
  {
    const char* data = R"data(
[section]
param = 18446744073709551615
)data";
    ProgramOptions opts("test", "test [opts]", "", "/tmp");
    opts.addOption("--section.param", "desc", new UInt64Parameter(&test_value));
    IniFileParser parser(&opts);
    bool ok = parser.parseContent("test.conf", data, true);
    ASSERT_TRUE(ok);
    EXPECT_EQ(0, opts.processingResult().exitCode());
    EXPECT_EQ(EXIT_FAILURE, opts.processingResult().exitCodeOrFailure());
  }

  // Test valid small value
