// Compute interpolated tangent using cubic Hermite basis
void InterpTangent(
    const Vector3& p0,
    const Vector3& p1,
    const Vector3& p2,
    const Vector3& p3,
    float t,
    Vector3& result
) {
    float t6 = t * 6.0f;
    float t2 = t * t;

    // Coefficient for p0: 6t^2 - 6t
    Scale(p0, (t2 * 6.0f) - t6, result);

    Vector3 temp;
    float t3 = t2 * 3.0f;

    // Coefficient for p1: 1 + (3t^2 - 4t)
    Scale(p1, 1.0f + (t3 - (t * 4.0f)), temp);
    Add(result, temp, result);

    // Coefficient for p2: -6t^2 + 6t
    Scale(p2, (t2 * -6.0f) + t6, temp);
    Add(result, temp, result);

    // Coefficient for p3: 3t^2 - 2t
    Scale(p3, (t3 - (t * 2.0f)), temp);
    Add(result, temp, result);
}

// Compute tangent for spline interpolation at index i
void SplineTangent(const Keys<Vector3, Vector3>& keyList, int index, Vector3& outTangent) {
    int count = keyList.size();
    MILO_ASSERT(count > 1, 0x17);

    if (count == 2) {
        Subtract(keyList[1].value, keyList[0].value, outTangent);
    } else if (index <= 0) {
        // Forward difference scaled by 1.5 minus correction term
        Subtract(keyList[1].value, keyList[0].value, outTangent);
        Scale(outTangent, 1.5f, outTangent);

        Vector3 correction;
        Subtract(keyList[2].value, keyList[0].value, correction);
        Scale(correction, 0.25f, correction);
        Subtract(outTangent, correction, outTangent);
    } else if (index >= count - 1) {
        // Backward difference scaled by 1.5 minus correction term
        Subtract(keyList[count - 1].value, keyList[count - 2].value, outTangent);
        Scale(outTangent, 1.5f, outTangent);

        Vector3 correction;
        Subtract(keyList[count - 1].value, keyList[count - 3].value, correction);
        Scale(correction, 0.25f, correction);
        Subtract(outTangent, correction, outTangent);
    } else {
        // Central difference scaled by 0.5
        Subtract(keyList[index + 1].value, keyList[index - 1].value, outTangent);
        Scale(outTangent, 0.5f, outTangent);
    }
}

// Interpolate vector between two keys, optionally using spline or linear interpolation
void InterpVector(
    const Keys<Vector3, Vector3>& keyList,
    const Key<Vector3>* preceding,
    const Key<Vector3>* succeeding,
    float param,
    bool useSpline,
    Vector3& outValue,
    Vector3* outDerivative
) {
    if (keyList.size() < 3) {
        useSpline = false;
        if (keyList.size() < 2) {
            if (outDerivative)
                outDerivative->Set(0.0f, 1.0f, 0.0f);
            if (!keyList.empty())
                outValue = preceding->value;
            else
                outValue.Set(0.0f, 0.0f, 0.0f);
            return;
        }
    }

    int idx = preceding - &keyList.front();

    if (useSpline) {
        float t2 = param * param;
        float t3 = t2 * param;
        float threeT2 = t2 * 3.0f;

        // Basis function for p0: 2t^3 - 3t^2 + 1
        Scale(preceding->value, (t3 * 2.0f - threeT2) + 1.0f, outValue);

        Vector3 tanStart, tanEnd;
        SplineTangent(keyList, idx, tanStart);
        SplineTangent(keyList, idx + 1, tanEnd);

        // Hermite blending terms
        Vector3 blendStart, blendEnd;
        Scale(tanStart, param + t2 * -2.0f + t3, blendStart);
        Add(outValue, blendStart, outValue);

        Scale(succeeding->value, t3 * -2.0f + threeT2, blendEnd);
        Add(outValue, blendEnd, outValue);

        Scale(tanEnd, t3 - t2, blendEnd);
        Add(outValue, blendEnd, outValue);

        if (outDerivative) {
            InterpTangent(preceding->value, tanStart, succeeding->value, tanEnd, param, *outDerivative);
        }
    } else {
        // Linear interpolation
        Interp(preceding->value, succeeding->value, param, outValue);

        if (outDerivative) {
            int localIdx = idx;
            if (localIdx == keyList.size() - 1)
                --localIdx;
            Subtract(keyList[localIdx + 1].value, keyList[localIdx].value, *outDerivative);
        }
    }
}

// Convenience overload that resolves key indices from frame number
void InterpVector(
    const Keys<Vector3, Vector3>& keyList,
    bool useSpline,
    float time,
    Vector3& outValue,
    Vector3* outDerivative
) {
    const Key<Vector3>* prevKey;
    const Key<Vector3>* nextKey;
    float tParam;
    keyList.AtFrame(time, prevKey, nextKey, tParam);
    InterpVector(keyList, prevKey, nextKey, tParam, useSpline, outValue, outDerivative);
}

// Spherical cubic interpolation for quaternions
void QuatSpline(
    const Keys<Hmx::Quat, Hmx::Quat>& keyList,
    const Key<Hmx::Quat>* preceding,
    const Key<Hmx::Quat>* succeeding,
    float t,
    Hmx::Quat& outQuat
) {
    MILO_ASSERT(!keyList.empty(), 0x9B);

    if (preceding == succeeding) {
        outQuat = preceding->value;
    } else {
        int idx = preceding - &keyList.front();
        Hmx::Quat q0 = preceding->value;
        Hmx::Quat q1 = succeeding->value;
        Hmx::Quat qPrev = (idx == 0) ? q0 : keyList[idx - 1].value;
        Hmx::Quat qNext = (idx + 1 == keyList.size() - 1) ? q1 : keyList[idx + 2].value;

        NormalizeTo(q0, qPrev);
        NormalizeTo(q0, q1);
        NormalizeTo(q0, qNext);

        for (int comp = 0; comp < 4; ++comp) {
            float p0 = q0[comp];
            float p1 = q1[comp];
            float pm = qPrev[comp];
            float pn = qNext[comp];

            float d1 = p1 - pm;
            float d2 = pn - p1 * 3.0f + pm;
            float c3 = d2 - d1;
            float c2 = (p1 * 4.0f + p0 * 2.0f - pm * 5.0f) - pn;
            float c1 = d1 * 0.5f;
            float c0 = p0 * 2.0f;

            outQuat[comp] = ((c3 * t + c2) * t + c1) * t + c0;
        }

        Normalize(outQuat, outQuat);
    }
}

