extern "C" int LLVMFuzzerTestOneInput(const uint8_t* data, size_t size)
{
    // Initialize fuzzing input handler
    FuzzedDataProvider provider(data, size);

    // Consume media type within valid range [0, 2]
    int rawMediaType = provider.ConsumeIntegralInRange(0, 2);
    MediaType mediaType = static_cast<MediaType>(rawMediaType);

    // Extract remaining bytes as input frame
    std::vector<uint8_t> inputData = provider.ConsumeRemainingBytes<uint8_t>();

    // Create decryptor instance
    Decryptor decryptor;

    // Compute maximum possible output size
    size_t maxOutputSize = decryptor.GetMaxPlaintextByteSize(mediaType, inputData.size());

    // Allocate output buffer
    std::unique_ptr<uint8_t[]> outputBuffer(new uint8_t[maxOutputSize]);

    // Perform decryption using array views
    auto decryptFunc = [&](MediaType type, const uint8_t* inPtr, size_t inSize,
                           uint8_t* outPtr, size_t outSize) -> int {
        return static_cast<int>(
            decryptor.Decrypt(type,
                              MakeArrayView(inPtr, inSize),
                              MakeArrayView(outPtr, outSize))
        );
    };

    [[maybe_unused]] int result = decryptFunc(
        mediaType,
        inputData.data(),
        inputData.size(),
        outputBuffer.get(),
        maxOutputSize
    );

    return 0;
}

#include "Utils/LLVM/RecursiveTimer.h"

// Tracks the current nesting level for timing output indentation
static unsigned TimeRecorderDepth = 0;
bool RecursiveTimer::Enabled = true;

// Generates a string with N levels of indentation (4 spaces per level)
static inline std::string Indent(unsigned Levels) {
  std::string result;
  for (unsigned i = 0; i < Levels; ++i)
    result += "    ";
  return result;
}

// Constructor for C-string prefix
RecursiveTimer::RecursiveTimer(const char *Label)
    : Begin(std::chrono::steady_clock::now()), Prefix(Label) {
  if (!Enabled)
    return;
  Active = true;
  outs() << Indent(TimeRecorderDepth++) << Label << "...\n";
}

// Constructor for std::string prefix
RecursiveTimer::RecursiveTimer(const std::string &Label)
    : Begin(std::chrono::steady_clock::now()), Prefix(Label) {
  if (!Enabled)
    return;
  Active = true;
  outs() << Indent(TimeRecorderDepth++) << Label << "...\n";
}

// Destructor outputs elapsed time when timer goes out of scope
RecursiveTimer::~RecursiveTimer() {
  if (!Active)
    return;

  std::chrono::steady_clock::time_point Finish = std::chrono::steady_clock::now();
  auto DurationMs = std::chrono::duration_cast<std::chrono::milliseconds>(Finish - Begin).count();

  // Convert to seconds if duration >= 1000ms
  double DisplayTime = DurationMs;
  const char *TimeUnit = "ms";

  if (DurationMs >= 1000) {
    DisplayTime = DurationMs / 1000.0;
    TimeUnit = "s";
  }

  outs() << Indent(--TimeRecorderDepth) << Prefix << " took " 
         << DisplayTime << TimeUnit << "!\n";
}

