#define ENSURE_SYSTEM_OP(expr)                                            \
    do {                                                                  \
        if (!(expr)) {                                                    \
            Y_ABORT(#expr ", errno=%d", LastSystemError());                \
        }                                                                 \
    } while (false)

    class TPortGuard : public NTesting::IPort, TNonCopyable {
    public:
        TPortGuard(ui16 p, THolder<TFileLock> l)
            : Lock(std::move(l))
            , Port(p)
        {
        }

        ~TPortGuard() override {
            try {
                if (!NFs::Remove(Lock->GetName())) {
                    Lock->Release();
                }
            } catch (const TSystemError& e) {
                Y_ABORT("Failed to unlock port %d, error=%d", Port, e.Status());
            }
        }

        ui16 Get() override {
            return Port;
        }

    private:
        THolder<TFileLock> Lock;
        ui16 Port;
    };

    std::pair<ui16, ui16> FetchEphemeralRange() {
        std::pair<ui16, ui16> result{(1 << 15) + (1 << 14), (1 << 16) - 1};

#ifdef _linux_
        TString path = "/proc/sys/net/ipv4/ip_local_port_range";
        if (NFs::Exists(path)) {
            TIFStream stream(path);
            stream >> result.first >> result.second;
        }
#endif

#ifdef _darwin_
        ui32 low = 0, high = 0;
        size_t len = sizeof(ui32);
        sysctlbyname("net.inet.ip.portrange.first", &low, &len, nullptr, 0);
        sysctlbyname("net.inet.ip.portrange.last", &high, &len, nullptr, 0);
        result.first = static_cast<ui16>(low);
        result.second = static_cast<ui16>(high);
#endif

        return result;
    }

    TVector<std::pair<ui16, ui16>> DetermineAvailableRanges() {
        TString envRange = GetEnv("VALID_PORT_RANGE");
        TVector<std::pair<ui16, ui16>> ranges;

        if (envRange.Contains(':')) {
            auto parts = StringSplitter(envRange).Split(':').Limit(2).ToList<TString>();
            if (parts.size() == 2) {
                ranges.emplace_back(FromString<ui16>(parts[0]), FromString<ui16>(parts[1]));
            }
        } else {
            const ui16 minStandard = 1025;
            const ui16 maxStandard = Max<ui16>();
            auto [lowEph, highEph] = FetchEphemeralRange();

            const ui16 startBlocked = Max(lowEph, minStandard);
            const ui16 endBlocked = Min(highEph, maxStandard);

            if (startBlocked > minStandard) {
                ranges.emplace_back(minStandard, startBlocked - 1);
            }
            if (endBlocked < maxStandard) {
                ranges.emplace_back(endBlocked + 1, maxStandard);
            }
        }

        return ranges;
    }

    class TPortManager {
        static constexpr size_t MaxAttempts = 20;

    public:
        TPortManager() {
            InitializeFromEnvironment();
        }

        void InitializeFromEnvironment() {
            TString syncPath = GetEnv("PORT_SYNC_PATH");
            SyncDirectory = TFsPath(syncPath.IsDefined() ? syncPath : (TFsPath(GetSystemTempDir()) / "testing_port_locks"));
            Y_ABORT_UNLESS(SyncDirectory.IsDefined());

            NFs::MakeDirectoryRecursive(SyncDirectory);
            Chmod(SyncDirectory.c_str(), NFs::FP_COMMON_FILE);

            AvailableRanges = DetermineAvailableRanges();
            TotalPorts = 0;
            for (const auto& [lo, hi] : AvailableRanges) {
                TotalPorts += (hi - lo);
            }
            Y_ABORT_UNLESS(TotalPorts != 0);

            UseRandomPorts = GetEnv("NO_RANDOM_PORTS").empty();
        }

        NTesting::TPortHolder ObtainFreePort() const {
            ui16 offset = RandomNumber<ui16>();
            for (ui16 attempt = 0; attempt < TotalPorts; ++attempt) {
                ui16 candidate = (offset + attempt) % TotalPorts;

                ui16 selectedPort = 0;
                bool found = false;
                for (const auto& [lo, hi] : AvailableRanges) {
                    ui16 span = hi - lo;
                    if (candidate >= span) {
                        candidate -= span;
                    } else {
                        selectedPort = lo + candidate;
                        found = true;
                        break;
                    }
                }

                if (!found) continue;

                auto guard = AttemptReservePort(selectedPort);
                if (guard) {
                    return NTesting::TPortHolder{std::move(guard)};
                }
            }
            Y_ABORT("Unable to allocate a free port.");
        }

        TVector<NTesting::TPortHolder> AcquireSequentialPorts(size_t needed) const {
            Y_ABORT_UNLESS(needed > 0);
            TVector<NTesting::TPortHolder> collected;
            collected.Reserve(needed);

            for (size_t trial = 0; trial < MaxAttempts; ++trial) {
                for (const auto& [lo, hi] : AvailableRanges) {
                    if (hi - lo < needed) continue;

                    ui16 base = lo + RandomNumber<ui16>((hi - lo) / 2);
                    if (hi - base < needed) continue;

                    collected.clear();
                    for (ui16 probe = base; probe < hi && collected.size() < needed; ++probe) {
                        auto guard = AttemptReservePort(probe);
                        if (guard) {
                            collected.emplace_back(std::move(guard));
                        } else {
                            collected.clear();
                            break;
                        }
                    }

                    if (collected.size() == needed) {
                        return collected;
                    }
                }
            }

            Y_ABORT("Failed to reserve %zu consecutive ports.", needed);
        }

        NTesting::TPortHolder RequestSpecificPort(ui16 desired) const {
            if (desired && !UseRandomPorts) {
                auto guard = AttemptReservePort(desired);
                if (guard) {
                    return NTesting::TPortHolder{std::move(guard)};
                }
                Y_ABORT("Cannot reserve requested port %hu!", desired);
            }
            return ObtainFreePort();
        }

    private:
        THolder<NTesting::IPort> AttemptReservePort(ui16 port) const {
            TString lockPath = SyncDirectory / ::ToString(port);
            auto lock = MakeHolder<TFileLock>(lockPath);
            if (!lock->TryAcquire()) {
                return nullptr;
            }

            TInet6StreamSocket socket;
            ENSURE_SYSTEM_OP(INVALID_SOCKET != static_cast<SOCKET>(socket));

            TSockAddrInet6 addr("::", port);
            if (socket.Bind(&addr) != 0) {
                lock->Release();
                int err = LastSystemError();
                Y_ABORT_UNLESS(err == EADDRINUSE, "Unexpected bind error: %d on port %d", err, port);
                return nullptr;
            }

            return MakeHolder<TPortGuard>(port, std::move(lock));
        }

    private:
        TFsPath SyncDirectory;
        TVector<std::pair<ui16, ui16>> AvailableRanges;
        size_t TotalPorts;
        bool UseRandomPorts;
    };
}

namespace NTesting {
    void InitPortManagerFromEnv() {
        Singleton<TPortManager>()->InitializeFromEnvironment();
    }

    TPortHolder GetFreePort() {
        return Singleton<TPortManager>()->ObtainFreePort();
    }

    namespace NLegacy {
        TPortHolder GetPort(ui16 port) {
            return Singleton<TPortManager>()->RequestSpecificPort(port);
        }

        TVector<TPortHolder> GetFreePortsRange(size_t count) {
            return Singleton<TPortManager>()->AcquireSequentialPorts(count);
        }
    }

    IOutputStream& operator<<(IOutputStream& out, const TPortHolder& holder) {
        return out << static_cast<ui16>(holder);
    }
}

