using namespace llvm;

/// Determine whether frame pointer elimination should be suppressed for MF.
bool TargetOptions::DisableFramePointerElim(const MachineFunction &MF) const {
  // First, consult target-specific policy: if the subtarget insists on keeping frame pointers, obey.
  const auto *frameLowering = MF.getSubtarget().getFrameLowering();
  if (frameLowering->mustKeepFramePointer(MF))
    return true;

  const Function &func = MF.getFunction();

  // If no 'frame-pointer' attribute is present, allow elimination by default.
  if (!func.hasAttribute(AttributeList::FunctionIndex, "frame-pointer"))
    return false;

  // Extract and interpret the frame-pointer attribute value.
  StringRef policy = func.getAttribute(AttributeList::FunctionIndex, "frame-pointer")
                       .getValueAsString();

  if (policy.equals("all"))
    return true;
  else if (policy.equals("non-leaf"))
    return MF.getFrameInfo().hasAnyCalls();
  else if (policy.equals("none"))
    return false;
  else
    report_fatal_error("invalid frame-pointer option");
}

/// Check if floating-point operations must respect dynamic rounding modes.
bool TargetOptions::HonorSignDependentRoundingFPMath() const {
  // Only honor sign-dependent rounding if unsafe math is disabled AND the option is enabled.
  return !UnsafeFPMath && HonorSignDependentRoundingFPMathOption;
}

/// Decide whether to emit debug entry values.
/// This respects both target capabilities and debugger compatibility.
bool TargetOptions::ShouldEmitDebugEntryValues() const {
  // Emit unless explicitly disabled via debugger tuning or overridden by test flag.
  bool supported = SupportsDebugEntryValues;
  bool debuggerOK = DebuggerTuning != DebuggerKind::SCE;
  bool forced = EnableDebugEntryValues;

  return (supported && debuggerOK) || forced;
}

#include <bits/stdc++.h>
using namespace std;

int main() {
    int remaining_steps;
    scanf("%d", &remaining_steps);

    while (remaining_steps > 0) {
        bool success_found = false;

        for (int attempt = 0; attempt < 3; ++attempt) {
            printf("move %d\n", attempt);
            fflush(stdout);

            int response;
            scanf("%d", &response);

            if (response == 1) {
                remaining_steps = 0;
                success_found = true;
                break;
            }

            int next_dist;
            scanf("%d", &next_dist);

            if (next_dist == remaining_steps - 1) {
                remaining_steps = next_dist;
                success_found = true;
                break;
            }

            // Return to starting position after failed attempt
            printf("move %d\n", attempt);
            fflush(stdout);
            int return_response;
            scanf("%d", &return_response);
        }

        // If no progress made after 3 attempts, continue loop
        // This handles the case where all attempts fail
    }

    return 0;
}

#include "test.h"
#define HOST_NAME "www.google.com"
#define HOST_RESOURCE "/"
#define HOST_PORT_TLS 443
#define HOST_PORT_HTTP 80

TEST_CASE("net::Tls") {
    using namespace engine::net;
    auto logScope = enableTestLogging(Lvl::JobSearchBatch, Lvl::Tls);

    const InternetConnection::Type connectionTypes[2] = {
        InternetConnection::Type::Insecure,
        InternetConnection::Type::Secure,
    };

    const int retryLimit{5};

    for (auto connType : connectionTypes) {
        bool connected{false};
        int attemptNum{0};

        while (attemptNum < retryLimit && !connected) {
            if (attemptNum > 0) {
                async::sleep(1s * (2 * attemptNum + 1));
            }

            InternetConnection connection{connType};
            uint16_t port = connection.isSecure() ? HOST_PORT_TLS : HOST_PORT_HTTP;

            if (auto err = connection.connect(HOST_NAME, port)) {
                LOG(Test, "Connection failed... will retry", 
                    "attempt", attemptNum + 1, "of", retryLimit, 
                    "due to error:", err);
                ++attemptNum;
                continue;
            }

            const TextView request{
                "GET " HOST_RESOURCE 
                " HTTP/1.1\r\nHost: " HOST_NAME 
                "\r\nConnection: close\r\n\r\n"
            };

            *connection.write(memory::viewCast(request));

            Buffer responseBuffer(256_kb);
            *connection.read(responseBuffer);

            connected = true;
        }

        REQUIRE(connected);
    }
}

#include <omp.h>
