static constexpr int numStates = 20;
static constexpr int statesSquared = numStates * numStates;
static constexpr int spanLength = numStates * 4;
static constexpr int maxStateIdx = 23;

// Helper lambda for masked load/store with broadcast
inline void apply_fma_block(const double* src, double* dst, const double* mul, __mmask8 maskLow, __mmask8 maskHigh) {
    __m512d t = _mm512_extload_pd(src, _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);
    __m512d m = _mm512_load_pd(mul);
    __m512d acc = _mm512_load_pd(dst);
    __m512d r = _mm512_fmadd_pd(t, m, acc);
    _mm512_store_pd(dst, r);

    m = _mm512_load_pd(mul + 8);
    acc = _mm512_load_pd(dst + 8);
    r = _mm512_fmadd_pd(t, m, acc);
    _mm512_store_pd(dst + 8, r);

    t = _mm512_mask_extload_pd(t, maskLow, src, _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);
    t = _mm512_mask_extload_pd(t, maskHigh, src + 20, _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);

    m = _mm512_load_pd(mul + 16);
    acc = _mm512_load_pd(dst + 16);
    r = _mm512_fmadd_pd(t, m, acc);
    _mm512_store_pd(dst + 16, r);

    t = _mm512_extload_pd(src + 20, _MM_UPCONV_PD_NONE, _MM_BROADCAST_1X8, _MM_HINT_NONE);
    m = _mm512_load_pd(mul + 24);
    acc = _mm512_load_pd(dst + 24);
    r = _mm512_fmadd_pd(t, m, acc);
    _mm512_store_pd(dst + 24, r);

    m = _mm512_load_pd(mul + 32);
    acc = _mm512_load_pd(dst + 32);
    r = _mm512_fmadd_pd(t, m, acc);
    _mm512_store_pd(dst + 32, r);
}

void newviewGTRGAMMAPROT_MIC(int tipCase,
                  double *x1, double *x2, double *x3, double *extEV, double *tipVector,
                  int *ex3, unsigned char *tipX1, unsigned char *tipX2,
                  int n, double *left, double *right, int *wgt, int *scalerIncrement, const pllBoolean fastScaling)
{
  __m512d minlikelihood_MIC = _mm512_set1_pd(PLL_MINLIKELIHOOD);
  __m512d twotothe256_MIC = _mm512_set1_pd(PLL_TWOTOTHE256);
  __m512i absMask_MIC = _mm512_set1_epi64(0x7fffffffffffffffULL);
  int addScale = 0;
  double aEV[1600] __attribute__((align(PLL_BYTE_ALIGNMENT)));

  // Precompute rearranged EV matrix
  for (int idx = 0; idx < 1600; ++idx) {
      int row = idx / spanLength;
      int col = idx % numStates;
      aEV[idx] = extEV[row * numStates + col];
  }

  switch(tipCase)
  {
    case PLL_TIP_TIP:
      {
        double umpX1[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        double umpX2[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        for (int stateIdx = 0; stateIdx < maxStateIdx; ++stateIdx) {
            for (int k = 0; k < spanLength; ++k) {
                umpX1[stateIdx * spanLength + k] = 0.0;
                umpX2[stateIdx * spanLength + k] = 0.0;
                for (int l = 0; l < numStates; ++l) {
                    umpX1[stateIdx * spanLength + k] += tipVector[stateIdx * numStates + l] * left[k * numStates + l];
                    umpX2[stateIdx * spanLength + k] += tipVector[stateIdx * numStates + l] * right[k * numStates + l];
                }
            }
        }

        for (int siteIdx = 0; siteIdx < n; ++siteIdx) {
            const double* uX1 = &umpX1[spanLength * tipX1[siteIdx]];
            const double* uX2 = &umpX2[spanLength * tipX2[siteIdx]];
            double uX[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double* v3 = &x3[siteIdx * spanLength];

            for (int j = 0; j < spanLength; ++j) {
                uX[j] = uX1[j] * uX2[j];
                v3[j] = 0.0;
            }

            for (int k = 0; k < numStates; ++k) {
                for (int j = 0; j < spanLength; j += 8)
                    _mm_prefetch((const char*)&aEV[spanLength*(k+1) + j], _MM_HINT_T0);

                __mmask8 k1 = _mm512_int2mask(0x0F);
                __mmask8 k2 = _mm512_int2mask(0xF0);
                apply_fma_block(&uX[k], v3, &aEV[k * spanLength], k1, k2);
            }

            if (!fastScaling)
                ex3[siteIdx] = 0;
        }
      }
      break;

    case PLL_TIP_INNER:
      {
        double umpX1[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        for (int stateIdx = 0; stateIdx < maxStateIdx; ++stateIdx) {
            for (int k = 0; k < spanLength; ++k) {
                umpX1[stateIdx * spanLength + k] = 0.0;
                for (int l = 0; l < numStates; ++l) {
                    umpX1[stateIdx * spanLength + k] += tipVector[stateIdx * numStates + l] * left[k * numStates + l];
                }
            }
        }

        double aRight[4 * statesSquared] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        for (int block = 0; block < 4; ++block) {
            for (int row = 0; row < numStates; ++row) {
                for (int col = 0; col < numStates; ++col) {
                    aRight[row * spanLength + block * numStates + col] =
                        right[block * statesSquared + col * numStates + row];
                }
            }
        }

        for (int siteIdx = 0; siteIdx < n; ++siteIdx) {
            for (int j = 0; j < spanLength; j += 8)
                _mm_prefetch((const char*)&x2[spanLength*(siteIdx+1) + j], _MM_HINT_T1);

            double* uX1 = &umpX1[spanLength * tipX1[siteIdx]];
            double uX2[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double uX[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double* v3 = &(x3[spanLength * siteIdx]);
            const double* v2 = &(x2[spanLength * siteIdx]);

            for (int j = 0; j < spanLength; ++j)
                uX2[j] = 0.0;

            for (int k = 0; k < numStates; ++k) {
                for (int j = 0; j < spanLength; j += 8)
                    _mm_prefetch((const char*)&aRight[spanLength*(k+1) + j], _MM_HINT_T0);

                __mmask8 k1 = _mm512_int2mask(0x0F);
                __mmask8 k2 = _mm512_int2mask(0xF0);
                apply_fma_block(&v2[k], uX2, &aRight[k * spanLength], k1, k2);
            }

            for (int j = 0; j < spanLength; ++j) {
                uX[j] = uX1[j] * uX2[j];
                v3[j] = 0.0;
            }

            for (int k = 0; k < numStates; ++k) {
                for (int j = 0; j < spanLength; j += 8)
                    _mm_prefetch((const char*)&aEV[spanLength*(k+1) + j], _MM_HINT_T0);

                __mmask8 k1 = _mm512_int2mask(0x0F);
                __mmask8 k2 = _mm512_int2mask(0xF0);
                apply_fma_block(&uX[k], v3, &aEV[k * spanLength], k1, k2);
            }

            __m512d t1 = _mm512_load_pd(&v3[0]);
            t1 = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t1), absMask_MIC));
            double vmax = _mm512_reduce_gmax_pd(t1);

            for (int l = 8; l < spanLength; l += 8) {
                __m512d t = _mm512_load_pd(&v3[l]);
                t = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t), absMask_MIC));
                double vmax2 = _mm512_reduce_gmax_pd(t);
                vmax = (vmax > vmax2) ? vmax : vmax2;
            }

            if (vmax < PLL_MINLIKELIHOOD) {
                for (int j = 0; j < spanLength; ++j)
                    v3[j] *= PLL_TWOTOTHE256;
                if (!fastScaling)
                    ex3[siteIdx] += 1;
                else
                    addScale += wgt[siteIdx];
            }
        }
      }
      break;

    case PLL_INNER_INNER:
      {
        double aLeft[4 * statesSquared] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        double aRight[4 * statesSquared] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        for (int block = 0; block < 4; ++block) {
            for (int row = 0; row < numStates; ++row) {
                for (int col = 0; col < numStates; ++col) {
                    aLeft[row * spanLength + block * numStates + col] =
                        left[block * statesSquared + col * numStates + row];
                    aRight[row * spanLength + block * numStates + col] =
                        right[block * statesSquared + col * numStates + row];
                }
            }
        }

        for (int siteIdx = 0; siteIdx < n; ++siteIdx) {
            for (int j = 0; j < spanLength; j += 8) {
                _mm_prefetch((const char*)&x1[spanLength*(siteIdx+1) + j], _MM_HINT_T1);
                _mm_prefetch((const char*)&x2[spanLength*(siteIdx+1) + j], _MM_HINT_T1);
            }

            double uX1[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double uX2[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double uX[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
            double* v3 = &(x3[spanLength * siteIdx]);
            const double* v1 = &(x1[spanLength * siteIdx]);
            const double* v2 = &(x2[spanLength * siteIdx]);

            for (int j = 0; j < spanLength; ++j) {
                uX1[j] = 0.0;
                uX2[j] = 0.0;
            }

            for (int k = 0; k < numStates; ++k) {
                for (int j = 0; j < spanLength; j += 8) {
                    _mm_prefetch((const char*)&aLeft[spanLength*(k+1) + j], _MM_HINT_T0);
                    _mm_prefetch((const char*)&aRight[spanLength*(k+1) + j], _MM_HINT_T0);
                }

                __mmask8 k1 = _mm512_int2mask(0x0F);
                __mmask8 k2 = _mm512_int2mask(0xF0);
                apply_fma_block(&v1[k], uX1, &aLeft[k * spanLength], k1, k2);
                apply_fma_block(&v2[k], uX2, &aRight[k * spanLength], k1, k2);
            }

            for (int j = 0; j < spanLength; ++j) {
                uX[j] = uX1[j] * uX2[j];
                v3[j] = 0.0;
            }

            for (int k = 0; k < numStates; ++k) {
                for (int j = 0; j < spanLength; j += 8)
                    _mm_prefetch((const char*)&aEV[spanLength*(k+1) + j], _MM_HINT_T0);

                __mmask8 k1 = _mm512_int2mask(0x0F);
                __mmask8 k2 = _mm512_int2mask(0xF0);
                apply_fma_block(&uX[k], v3, &aEV[k * spanLength], k1, k2);
            }

            __m512d t1 = _mm512_load_pd(&v3[0]);
            t1 = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t1), absMask_MIC));
            double vmax = _mm512_reduce_gmax_pd(t1);

            for (int l = 8; l < spanLength; l += 8) {
                __m512d t = _mm512_load_pd(&v3[l]);
                t = _mm512_castsi512_pd(_mm512_and_epi64(_mm512_castpd_si512(t), absMask_MIC));
                double vmax2 = _mm512_reduce_gmax_pd(t);
                vmax = (vmax > vmax2) ? vmax : vmax2;
            }

            if (vmax < PLL_MINLIKELIHOOD) {
                for (int j = 0; j < spanLength; ++j)
                    v3[j] *= PLL_TWOTOTHE256;
                if (!fastScaling)
                    ex3[siteIdx] += 1;
                else
                    addScale += wgt[siteIdx];
            }
        }
      } break;

    default:
      break;
  }
  *scalerIncrement = addScale;
}

double evaluateGTRGAMMAPROT_MIC(int *ex1, int *ex2, int *wgt, double *x1_start, double *x2_start, double *tipVector,
                 unsigned char *tipX1, const int n, double *diagptable, const pllBoolean fastScaling)
{
    double totalSum = 0.0;

    if (tipX1 != nullptr) {
        double aTipVec[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        for (int s = 0; s < maxStateIdx; ++s) {
            for (int l = 0; l < numStates; ++l) {
                double val = tipVector[s * numStates + l];
                aTipVec[s * spanLength + l] =
                aTipVec[s * spanLength + numStates + l] =
                aTipVec[s * spanLength + 2 * numStates + l] =
                aTipVec[s * spanLength + 3 * numStates + l] = val;
            }
        }

        for (int i = 0; i < n; ++i) {
            const double *x1 = &(aTipVec[spanLength * tipX1[i]]);
            const double *x2 = &(x2_start[spanLength * i]);
            double term = 0.0;

            for (int j = 0; j < spanLength; ++j)
                term += x1[j] * x2[j] * diagptable[j];

            if (!fastScaling)
                term = std::log(0.25 * std::fabs(term)) + (ex2[i] * std::log(PLL_MINLIKELIHOOD));
            else
                term = std::log(0.25 * std::fabs(term));

            totalSum += wgt[i] * term;
        }
    } else {
        for (int i = 0; i < n; ++i) {
            _mm_prefetch((const char*) &x1_start[spanLength*(i+8)], _MM_HINT_T1);
            _mm_prefetch((const char*) &x1_start[spanLength*(i+8) + 8], _MM_HINT_T1);
            _mm_prefetch((const char*) &x2_start[spanLength*(i+8)], _MM_HINT_T1);
            _mm_prefetch((const char*) &x2_start[spanLength*(i+8) + 8], _MM_HINT_T1);
            _mm_prefetch((const char*) &x1_start[spanLength*(i+1)], _MM_HINT_T0);
            _mm_prefetch((const char*) &x1_start[spanLength*(i+1) + 8], _MM_HINT_T0);
            _mm_prefetch((const char*) &x2_start[spanLength*(i+1)], _MM_HINT_T0);
            _mm_prefetch((const char*) &x2_start[spanLength*(i+1) + 8], _MM_HINT_T0);

            const double *x1 = &(x1_start[spanLength * i]);
            const double *x2 = &(x2_start[spanLength * i]);
            double term = 0.0;

            for (int j = 0; j < spanLength; ++j)
                term += x1[j] * x2[j] * diagptable[j];

            if (!fastScaling)
                term = std::log(0.25 * std::fabs(term)) + ((ex1[i] + ex2[i]) * std::log(PLL_MINLIKELIHOOD));
            else
                term = std::log(0.25 * std::fabs(term));

            totalSum += wgt[i] * term;
        }
    }
    return totalSum;
}

void sumGTRGAMMAPROT_MIC(int tipCase, double *sumtable, double *x1_start, double *x2_start, double *tipVector,
    unsigned char *tipX1, unsigned char *tipX2, int n)
{
    double aTipVec[1840] __attribute__((align(PLL_BYTE_ALIGNMENT)));
    for (int s = 0; s < maxStateIdx; ++s) {
        for (int l = 0; l < numStates; ++l) {
            double val = tipVector[s * numStates + l];
            aTipVec[s * spanLength + l] =
            aTipVec[s * spanLength + numStates + l] =
            aTipVec[s * spanLength + 2 * numStates + l] =
            aTipVec[s * spanLength + 3 * numStates + l] = val;
        }
    }

    switch(tipCase)
    {
      case PLL_TIP_TIP:
        for (int i = 0; i < n; ++i) {
            const double *left  = &(aTipVec[spanLength * tipX1[i]]);
            const double *right = &(aTipVec[spanLength * tipX2[i]]);
            for (int l = 0; l < spanLength; ++l)
                sumtable[i * spanLength + l] = left[l] * right[l];
        }
        break;

      case PLL_TIP_INNER:
        for (int i = 0; i < n; ++i) {
            _mm_prefetch((const char *) &x2_start[spanLength*(i+16)], _MM_HINT_T1);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+16) + 8], _MM_HINT_T1);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+2)], _MM_HINT_T0);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+2) + 8], _MM_HINT_T0);

            const double *left = &(aTipVec[spanLength * tipX1[i]]);
            const double *right = &(x2_start[spanLength * i]);
            for (int l = 0; l < spanLength; ++l)
                sumtable[i * spanLength + l] = left[l] * right[l];
        }
        break;

      case PLL_INNER_INNER:
        for (int i = 0; i < n; ++i) {
            _mm_prefetch((const char *) &x1_start[spanLength*(i+16)], _MM_HINT_T1);
            _mm_prefetch((const char *) &x1_start[spanLength*(i+16) + 8], _MM_HINT_T1);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+16)], _MM_HINT_T1);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+16) + 8], _MM_HINT_T1);
            _mm_prefetch((const char *) &x1_start[spanLength*(i+2)], _MM_HINT_T0);
            _mm_prefetch((const char *) &x1_start[spanLength*(i+2) + 8], _MM_HINT_T0);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+2)], _MM_HINT_T0);
            _mm_prefetch((const char *) &x2_start[spanLength*(i+2) + 8], _MM_HINT_T0);

            const double *left  = &(x1_start[spanLength * i]);
            const double *right = &(x2_start[spanLength * i]);
            for (int l = 0; l < spanLength; ++l)
                sumtable[i * spanLength + l] = left[l] * right[l];
        }
        break;
    }
}

void coreGTRGAMMAPROT_MIC(const int upper, double *sumtable,
    volatile double *ext_dlnLdlz,  volatile double *ext_d2lnLdlz2, double *EIGN, double *gammaRates, double lz, int *wgt)
{
    double diagptable0[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
    double diagptable1[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
    double diagptable2[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
    double diagptable01[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));
    double diagptable02[spanLength] __attribute__((align(PLL_BYTE_ALIGNMENT)));

    for (int block = 0; block < 4; ++block) {
        double ki = gammaRates[block];
        double kisqr = ki * ki;
        diagptable0[block * numStates] = 1.0;
        diagptable1[block * numStates] = 0.0;
        diagptable2[block * numStates] = 0.0;
        for (int l = 1; l < numStates; ++l) {
            diagptable0[block * numStates + l]  = std::exp(EIGN[l] * ki * lz);
            diagptable1[block * numStates + l] = EIGN[l] * ki;
            diagptable2[block * numStates + l] = EIGN[l] * EIGN[l] * kisqr;
        }
    }

    for (int i = 0; i < spanLength; ++i) {
        diagptable01[i] = diagptable0[i] * diagptable1[i];
        diagptable02[i] = diagptable0[i] * diagptable2[i];
    }

    const int aligned_width = (upper % PLL_VECTOR_WIDTH == 0) ? (upper / PLL_VECTOR_WIDTH) : (upper / PLL_VECTOR_WIDTH + 1);
    double dlnLdlz = 0.0;
    double d2lnLdlz2 = 0.0;

    for (int i = 0; i < aligned_width; ++i) {
        _mm_prefetch((const char *) &sumtable[i * spanLength * 8], _MM_HINT_T0);
        _mm_prefetch((const char *) &sumtable[i * spanLength * 8 + 8], _MM_HINT_T0);

        const double *sum = &sumtable[i * spanLength * PLL_VECTOR_WIDTH];
        double invBuf[PLL_VECTOR_WIDTH] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        double d1Buf[PLL_VECTOR_WIDTH] __attribute__((align(PLL_BYTE_ALIGNMENT)));
        double d2Buf[PLL_VECTOR_WIDTH] __attribute__((align(PLL_BYTE_ALIGNMENT)));

        __m512d invVec = _mm512_setzero_pd();
        __m512d d1Vec = _mm512_setzero_pd();
        __m512d d2Vec = _mm512_setzero_pd();

        int mask = 0x01;
        for (int j = 0; j < PLL_VECTOR_WIDTH; ++j) {
            _mm_prefetch((const char *) &sum[spanLength*(j+8)], _MM_HINT_T1);
            _mm_prefetch((const char *) &sum[spanLength*(j+8) + 8], _MM_HINT_T1);
            _mm_prefetch((const char *) &sum[spanLength*(j+1)], _MM_HINT_T0);
            _mm_prefetch((const char *) &sum[spanLength*(j+1) + 8], _MM_HINT_T0);

            __m512d inv_1 = _mm512_setzero_pd();
            __m512d d1_1 = _mm512_setzero_pd();
            __m512d d2_1 = _mm512_setzero_pd();

            for (int offset = 0; offset < spanLength; offset += 8) {
                __m512d d0_1 = _mm512_load_pd(&diagptable0[offset]);
                __m512d d01_1 = _mm512_load_pd(&diagptable01[offset]);
                __m512d d02_1 = _mm512_load_pd(&diagptable02[offset]);
                __m512d s_1 = _mm512_load_pd(&sum[j*spanLength + offset]);
                inv_1 = _mm512_fmadd_pd(d0_1, s_1, inv_1);
                d1_1 = _mm512_fmadd_pd(d01_1, s_1, d1_1);
                d2_1 = _mm512_fmadd_pd(d02_1, s_1, d2_1);
            }

            __mmask8 k1 = _mm512_int2mask(mask);
            mask <<= 1;

            inv_1 = _mm512_add_pd(inv_1, _mm512_swizzle_pd(inv_1, _MM_SWIZ_REG_CDAB));
            inv_1 = _mm512_add_pd(inv_1, _mm512_swizzle_pd(inv_1, _MM_SWIZ_REG_BADC));
            inv_1 = _mm512_add_pd(inv_1, _mm512_castsi512_pd(_mm512_permute4f128_epi32(_mm512_castpd_si512(inv_1), _MM_PERM_BADC)));
            invVec = _mm512_mask_mov_pd(invVec, k1, inv_1);

            d1_1 = _mm512_add_pd(d1_1, _mm512_swizzle_pd(d1_1, _MM_SWIZ_REG_CDAB));
            d1_1 = _mm512_add_pd(d1_1, _mm512_swizzle_pd(d1_1, _MM_SWIZ_REG_BADC));
            d1_1 = _mm512_add_pd(d1_1, _mm512_castsi512_pd(_mm512_permute4f128_epi32(_mm512_castpd_si512(d1_1), _MM_PERM_BADC)));
            d1Vec = _mm512_mask_mov_pd(d1Vec, k1, d1_1);

            d2_1 = _mm512_add_pd(d2_1, _mm512_swizzle_pd(d2_1, _MM_SWIZ_REG_CDAB));
            d2_1 = _mm512_add_pd(d2_1, _mm512_swizzle_pd(d2_1, _MM_SWIZ_REG_BADC));
            d2_1 = _mm512_add_pd(d2_1, _mm512_castsi512_pd(_mm512_permute4f128_epi32(_mm512_castpd_si512(d2_1), _MM_PERM_BADC)));
            d2Vec = _mm512_mask_mov_pd(d2Vec, k1, d2_1);
        }

        _mm512_store_pd(&invBuf[0], invVec);
        _mm512_store_pd(&d1Buf[0], d1Vec);
        _mm512_store_pd(&d2Buf[0], d2Vec);

        for (int j = 0; j < PLL_VECTOR_WIDTH; ++j) {
            const double inv_Li = 1.0 / invBuf[j];
            const double d1 = d1Buf[j] * inv_Li;
            const double d2 = d2Buf[j] * inv_Li;
            dlnLdlz += wgt[i * PLL_VECTOR_WIDTH + j] * d1;
            d2lnLdlz2 += wgt[i * PLL_VECTOR_WIDTH + j] * (d2 - d1 * d1);
        }
    }

    *ext_dlnLdlz   = dlnLdlz;
    *ext_d2lnLdlz2 = d2lnLdlz2;
}

