// Helper for throwing exceptions with function name context
inline void __string_conv_error_out_of_range(const string& func_name) {
  std::__throw_out_of_range(func_name + ": result out of range");
}

inline void __string_conv_error_invalid(const string& func_name) {
  std::__throw_invalid_argument(func_name + ": invalid input");
}

// Generic integer conversion helper using libc functions
template <typename IntType, typename StringType, typename ConvFunc>
IntType __convert_to_int(const string& func_name, const StringType& input_str, size_t* end_idx, int base, ConvFunc conv_fn) {
  using char_type = typename StringType::value_type;

  char_type const* begin_ptr = input_str.c_str();
  char_type* end_pos         = nullptr;

  int saved_errno = errno;
  errno         = 0;

  IntType result = conv_fn(begin_ptr, &end_pos, base);

  swap(errno, saved_errno);

  if (saved_errno == ERANGE)
    __string_conv_error_out_of_range(func_name);
  if (end_pos == begin_ptr)
    __string_conv_error_invalid(func_name);

  if (end_idx != nullptr)
    *end_idx = static_cast<size_t>(end_pos - begin_ptr);

  return result;
}

