// String formatting helpers for to_string
template <typename StrType, typename ValType>
StrType __format_numeric(ValType val) {
  constexpr size_t buf_capacity = numeric_limits<ValType>::digits10 + 3; // +2 safety margin
  char buffer[buf_capacity];
  auto conv_result = to_chars(buffer, buffer + buf_capacity, val);
  _LIBCPP_ASSERT_INTERNAL(conv_result.ec == errc(), "buffer overflow in to_string");

  return StrType(buffer, conv_result.ptr);
}

#if _LIBCPP_HAS_WIDE_CHARACTERS
typedef int (*wide_printf_func)(wchar_t* __restrict, size_t, const wchar_t* __restrict, ...);

inline wide_printf_func __get_wide_snprintf() {
#  ifndef _LIBCPP_MSVCRT
  return swprintf;
#  else
  return static_cast<int(__cdecl*)(wchar_t* __restrict, size_t, const wchar_t* __restrict, ...)>(_snwprintf);
#  endif
}
#endif

template <typename StrType, typename PrintfFunc, typename ValType>
StrType __format_float(PrintfFunc printf_fn, ValType val) {
  StrType tmp;
  size_t current_capacity = tmp.size();
  while (true) {
    int written = printf_fn(&tmp[0], current_capacity + 1, "%f", val);
    if (written >= 0) {
      size_t used = static_cast<size_t>(written);
      if (used <= current_capacity) {
        tmp.resize(used);
        break;
      }
      current_capacity = used;
    } else {
      current_capacity = current_capacity * 2 + 1;
    }
    tmp.resize(current_capacity);
  }
  return tmp;
}

