#include "Scope.h"

Scope::Scope() {
    enterNewLevel();
}

void Scope::enterNewLevel() {
    scopeStack.emplace(ScopeLevel{});
}

void Scope::exitLevel() {
    scopeStack.pop();
}

bool Scope::bindVariable(const std::string& varName, std::shared_ptr<WrappedValue> value) {
    auto& currentMap = scopeStack.top().variableBindings;
    if (currentMap.find(varName) != currentMap.end() && currentMap[varName] != nullptr)
        return false;
    currentMap[varName] = std::move(value);
    return true;
}

std::shared_ptr<WrappedValue> Scope::findVariable(const std::string& varName) const {
    std::stack<ScopeLevel> tempStack = scopeStack;
    while (!tempStack.empty()) {
        const auto& map = tempStack.top().variableBindings;
        auto it = map.find(varName);
        if (it != map.end() && it->second != nullptr)
            return it->second;
        tempStack.pop();
    }
    return nullptr;
}

bool Scope::registerFunction(const std::string& funcName, llvm::Function* funcPtr) {
    auto& currentMap = scopeStack.top().functionTable;
    if (currentMap.find(funcName) != currentMap.end() && currentMap[funcName] != nullptr)
        return false;
    currentMap[funcName] = funcPtr;
    return true;
}

llvm::Function* Scope::lookupFunction(const std::string& funcName) const {
    std::stack<ScopeLevel> tempStack = scopeStack;
    while (!tempStack.empty()) {
        const auto& map = tempStack.top().functionTable;
        auto it = map.find(funcName);
        if (it != map.end() && it->second != nullptr)
            return it->second;
        tempStack.pop();
    }
    return nullptr;
}

bool Scope::storeInlineAsm(const std::string& asmLabel, llvm::InlineAsm* inlineAsmPtr) {
    auto& currentMap = scopeStack.top().asmTable;
    if (currentMap.find(asmLabel) != currentMap.end() && currentMap[asmLabel] != nullptr)
        return false;
    currentMap[asmLabel] = inlineAsmPtr;
    return true;
}

llvm::InlineAsm* Scope::retrieveInlineAsm(const std::string& asmLabel) const {
    std::stack<ScopeLevel> tempStack = scopeStack;
    while (!tempStack.empty()) {
        const auto& map = tempStack.top().asmTable;
        auto it = map.find(asmLabel);
        if (it != map.end() && it->second != nullptr)
            return it->second;
        tempStack.pop();
    }
    return nullptr;
}

bool Scope::defineStruct(const std::string& structTag, llvm::StructType* structType, std::vector<std::string> fieldNames) {
    auto& topLevel = scopeStack.top();
    topLevel.structTypeRegistry[structTag] = structType;
    topLevel.structFieldList[structTag] = std::move(fieldNames);
    return true;
}

llvm::StructType* Scope::resolveStructType(const std::string& structTag) const {
    std::stack<ScopeLevel> tempStack = scopeStack;
    while (!tempStack.empty()) {
        const auto& map = tempStack.top().structTypeRegistry;
        auto it = map.find(structTag);
        if (it != map.end() && it->second != nullptr)
            return it->second;
        tempStack.pop();
    }
    return nullptr;
}

std::optional<int> Scope::getFieldIndex(const std::string& structTag, const std::string& fieldName) const {
    std::stack<ScopeLevel> tempStack = scopeStack;
    while (!tempStack.empty()) {
        const auto& structMap = tempStack.top().structFieldList;
        auto structIt = structMap.find(structTag);
        if (structIt != structMap.end()) {
            const auto& fields = structIt->second;
            for (size_t idx = 0; idx < fields.size(); ++idx) {
                if (fields[idx] == fieldName)
                    return static_cast<int>(idx);
            }
        }
        tempStack.pop();
    }
    return std::nullopt;
}

#include "TuringTest.h"
#include "ByteBuffer.h"
#include "ByteBufferIterator.h"
using namespace turing::test;

class ByteBufferIteratorTest : public TuringTest {
protected:
    void setup() override {
        // Initialization logic (if needed)
    }
    void cleanup() override {
        // Cleanup logic (if needed)
    }
};

// Helper function to append a single value of trivial type
template <fs::TrivialPrimitive T>
void addValueToBuffer(fs::ByteBuffer& buffer, const T& value) {
    const size_t currentSize = buffer.size();
    const size_t addedSize = sizeof(T);
    buffer.resize(currentSize + addedSize);
    std::memcpy(buffer.data() + currentSize, &value, addedSize);
}

// Helper function to append multiple values of trivial type
template <fs::TrivialPrimitive T>
void addValuesToBuffer(fs::ByteBuffer& buffer, const std::vector<T>& values) {
    const size_t currentSize = buffer.size();
    const size_t addedSize = values.size() * sizeof(T);
    buffer.resize(currentSize + addedSize);
    if (!values.empty()) {
        std::memcpy(buffer.data() + currentSize, values.data(), addedSize);
    }
}

// Helper function to append string view data
template <fs::CharPrimitive T>
void addStringToBuffer(fs::ByteBuffer& buffer, std::basic_string_view<T> str) {
    const size_t currentSize = buffer.size();
    const size_t addedSize = str.size() * sizeof(T);
    buffer.resize(currentSize + addedSize);
    if (!str.empty()) {
        std::memcpy(buffer.data() + currentSize, str.data(), addedSize);
    }
}

TEST_F(ByteBufferIteratorTest, General) {
    using namespace std::literals;
    fs::ByteBuffer buffer;

    // Prepare test data
    std::vector<uint16_t> intList = {0u, 1u, 2u, 3u, 4u};
    std::vector<float> floatList = {3.14159f, 1.61803f};

    // Append data to buffer
    addValuesToBuffer(buffer, intList);
    addValuesToBuffer(buffer, floatList);
    addValueToBuffer(buffer, 2.71828);
    addStringToBuffer(buffer, "Hello world"sv);

    // Read and verify data
    fs::ByteBufferIterator iter(buffer);

    // Extract first three uint16_t values as span
    std::span<const uint16_t> part1 = iter.get<uint16_t>(3);
    EXPECT_EQ(part1[0], 0u);
    EXPECT_EQ(part1[1], 1u);
    EXPECT_EQ(part1[2], 2u);

    // Extract remaining uint16_t values individually
    EXPECT_EQ(iter.get<uint16_t>(), 3u);
    EXPECT_EQ(iter.get<uint16_t>(), 4u);

    // Extract floats with tolerance
    EXPECT_NEAR(iter.get<float>(), 3.14159f, 1e-5f);
    EXPECT_NEAR(iter.get<float>(), 1.61803f, 1e-5f);

    // Extract double value
    EXPECT_NEAR(iter.get<double>(), 2.71828, 1e-5);

    // Extract and compare character sequence
    auto chars = iter.get<char>(11);
    EXPECT_TRUE(std::string_view(reinterpret_cast<const char*>(chars.data()), chars.size()) == "Hello world"sv);
}

int main(int argc, char** argv) {
    return turing::test::turingTestMain(argc, argv, [] {
        testing::GTEST_FLAG(repeat) = 4;
    });
}

#include <gtest/gtest.h>
#include <ocs2_core/ComputationRequest.h>
#include <ocs2_core/PreComputation.h>

using Request = ocs2::Request;

// Test the convenient interface for requesting computations
TEST(testPrecomputation, convenientInterface) {
  ocs2::PreComputation preComp;
  // Request various computation types through the interface
  preComp.request(Request::Dynamics | Request::Approximation, 0.0, ocs2::vector_t(), ocs2::vector_t());
  preComp.requestPreJump(Request::Dynamics | Request::Approximation, 0.0, ocs2::vector_t());
  preComp.requestFinal(Request::Approximation, 0.0, ocs2::vector_t());
}

// Verify that request sets correctly identify contained components
TEST(testPrecomputation, contains) {
  constexpr auto reqSet1 = Request::Dynamics | Request::Cost | Request::Constraint | 
                           Request::SoftConstraint | Request::Approximation;

  EXPECT_TRUE(reqSet1.contains(Request::Dynamics));
  EXPECT_TRUE(reqSet1.contains(Request::Cost));
  EXPECT_TRUE(reqSet1.contains(Request::Constraint));
  EXPECT_TRUE(reqSet1.contains(Request::SoftConstraint));
  EXPECT_TRUE(reqSet1.contains(Request::Approximation));

  constexpr ocs2::RequestSet reqSet2 = Request::Dynamics;
  EXPECT_TRUE(reqSet2.contains(Request::Dynamics));
  EXPECT_FALSE(reqSet2.contains(Request::Cost));
  EXPECT_FALSE(reqSet2.contains(Request::Constraint));
  EXPECT_FALSE(reqSet2.contains(Request::SoftConstraint));
  EXPECT_FALSE(reqSet2.contains(Request::Approximation));

  constexpr auto reqSet3 = Request::Cost | Request::Constraint;
  EXPECT_FALSE(reqSet3.contains(Request::Dynamics));
  EXPECT_TRUE(reqSet3.contains(Request::Constraint));
  EXPECT_TRUE(reqSet3.contains(Request::Cost));
  EXPECT_FALSE(reqSet3.contains(Request::SoftConstraint));
  EXPECT_FALSE(reqSet3.contains(Request::Approximation));
}

// Test containsAny and containsAll functionality
TEST(testPrecomputation, containsAnyAll) {
  constexpr auto reqA = Request::Dynamics | Request::Cost;
  constexpr auto reqB = Request::Constraint | Request::Cost;

  EXPECT_TRUE(reqA.containsAny(reqB));
  EXPECT_FALSE(reqA.containsAll(reqB));

  constexpr auto reqC = Request::Constraint | Request::Cost | Request::Approximation;
  EXPECT_TRUE(reqC.containsAll(reqB));
}

