// Constructor initializes the backend with an output stream
TStreamLogBackend::TStreamLogBackend(IOutputStream* targetStream)
    : Slave_(targetStream)
{
}

// Destructor performs cleanup
TStreamLogBackend::~TStreamLogBackend() {
}

// Write a log record to the underlying stream
void TStreamLogBackend::WriteData(const TLogRecord& entry) {
    // Direct write of the record's data buffer
    Slave_->Write(entry.Data, entry.Len);
}

// Reopen log file - no-op in this implementation
void TStreamLogBackend::ReopenLog() {
}

// Constructor for context-aware backend
TStreamWithContextLogBackend::TStreamWithContextLogBackend(IOutputStream* targetStream)
    : Slave_(targetStream)
{
}

// Destructor for context-aware backend
TStreamWithContextLogBackend::~TStreamWithContextLogBackend() {
}

// Write log record with additional metadata
void TStreamWithContextLogBackend::WriteData(const TLogRecord& entry) {
    // First write the main record data
    Slave_->Write(entry.Data, entry.Len);

    // Add delimiter after main data
    Slave_->Write(DELIMITER);

    // Iterate through all metadata key-value pairs
    auto iter = rec.MetaFlags.begin();
    auto endIter = rec.MetaFlags.end();
    while (iter != endIter) {
        const TString& key = iter->first;
        const TString& value = iter->second;

        // Write key=value pair
        Slave_->Write(TString::Join(key, "=", value));

        // Add delimiter after each metadata entry
        Slave_->Write(DELIMITER);

        ++iter;
    }
}

// Reopen log file - no-op in this implementation
void TStreamWithContextLogBackend::ReopenLog() {
}

#include "plugin_tile_interface.h"
#include "ttile.h"

// Retrieve raw memory pointer without safety checks
int tile_interface_get_raw_address_unsafe(toonz_tile_handle_t handle,
                                          void **address) {
  // Validate parameters first
  if (!handle || !address) return -1;

  TTile *rasterTile = static_cast<TTile *>(handle);
  rasterTile->getRaster()->lock();
  *address = rasterTile->getRaster()->getRawData();
  return 0;
}

// Release lock on tile raster
int tile_interface_safen(toonz_tile_handle_t handle) {
  if (!handle) return -1;

  TTile *rasterTile = static_cast<TTile *>(handle);
  rasterTile->getRaster()->unlock();
  return 0;
}

// Calculate byte stride based on raster properties
int tile_interface_get_raw_stride(toonz_tile_handle_t handle, int *stride) {
  if (!handle || !stride) return -1;

  TTile *rasterTile = static_cast<TTile *>(handle);
  TRasterP rast     = rasterTile->getRaster();
  // Compute stride: wrap (pixels per line) * pixel size (bytes per pixel)
  *stride = rast->getWrap() * rast->getPixelSize();
  return 0;
}

// Determine pixel format type of the raster
int tile_interface_get_element_type(toonz_tile_handle_t handle, int *element) {
  if (!handle || !element) return -1;

  TTile *rasterTile = static_cast<TTile *>(handle);
  TRasterP rast     = rasterTile->getRaster();

  // Use switch-like pattern with early returns for clarity
  if (TRaster32P(rast)) {
    *element = TOONZ_TILE_TYPE_32P;
    return 0;
  }
  if (TRaster64P(rast)) {
    *element = TOONZ_TILE_TYPE_64P;
    return 0;
  }
  if (TRasterGR8P(rast)) {
    *element = TOONZ_TILE_TYPE_GR8P;
    return 0;
  }
  if (TRasterGR16P(rast)) {
    *element = TOONZ_TILE_TYPE_GR16P;
    return 0;
  }
  if (TRasterGRDP(rast)) {
    *element = TOONZ_TILE_TYPE_GRDP;
    return 0;
  }
  if (TRasterYUV422P(rast)) {
    *element = TOONZ_TILE_TYPE_YUV422P;
    return 0;
  }

  // Unknown format
  *element = TOONZ_TILE_TYPE_NONE;
  return -1;
}

// Copy rectangular area to external buffer
int tile_interface_copy_rect(toonz_tile_handle_t handle, int left, int top,
                             int width, int height, void *dst, int dststride) {
  // Parameter validation
  if (!handle || !dst || !dststride) return -1;
  if (width <= 0 || height <= 0) return 0;  // Nothing to copy

  TTile *rasterTile = static_cast<TTile *>(handle);
  TRasterP rast     = rasterTile->getRaster();

  // Bounds checking for source rectangle
  if (!(left >= 0 && top >= 0 && 
        left + width <= rast->getLx() && 
        top + height <= rast->getLy())) {
    return -1;
  }

  // Perform row-by-row copy
  for (int y = 0; y < height; ++y) {
    UCHAR *srcLine = static_cast<UCHAR*>(rast->getRawData(left, top + y));
    UCHAR *dstLine = static_cast<UCHAR*>(dst) + y * dststride;

    std::memcpy(dstLine, srcLine, width * rast->getPixelSize());
  }
  return 0;
}

// Create new tile as copy of existing one
int tile_interface_create_from(toonz_tile_handle_t handle,
                               toonz_tile_handle_t *newhandle) {
  if (!handle || !newhandle) return -1;

  TTile *sourceTile = static_cast<TTile *>(handle);
  TTile *copyTile   = new TTile(sourceTile->getRaster());
  *newhandle        = reinterpret_cast<toonz_tile_handle_t>(copyTile);
  return 0;
}

// Create new empty tile
int tile_interface_create(toonz_tile_handle_t *newhandle) {
  if (!newhandle) return -1;

  TTile *emptyTile = new TTile();
  *newhandle       = reinterpret_cast<toonz_tile_handle_t>(emptyTile);
  return 0;
}

// Destroy tile and free memory
int tile_interface_destroy(toonz_tile_handle_t handle) {
  if (!handle) return -1;

  TTile *tileToDelete = static_cast<TTile *>(handle);
  delete tileToDelete;
  return 0;
}

// Get bounding rectangle of tile in world coordinates
int tile_interface_get_rectangle(toonz_tile_handle_t handle,
                                 toonz_rect_t *rect) {
  if (!handle || !rect) return -1;

  TTile *tile = static_cast<TTile *>(handle);
  TRasterP rast = tile->getRaster();

  rect->x0 = tile->m_pos.x;
  rect->y0 = tile->m_pos.y;
  rect->x1 = rect->x0 + rast->getLx();
  rect->y1 = rect->y0 + rast->getLy();
  return 0;
}

#include "client/renderer/block/Variant.hpp"
#include <sstream>
#include <stdexcept>
#include <functional>

// Helper to construct block model ResourceLocation with domain/path formatting
static ResourceLocation buildBlockModelPath(const std::string& rawModel) {
    ResourceLocation temp(rawModel);
    return ResourceLocation(temp.getResourceDomain(), "block/" + temp.getResourcePath());
}

// Parse rotation from JSON, defaulting x/y to 0 if missing; throws on invalid values
static ModelRotation extractRotation(const nlohmann::json& data) {
    int angleX = data.value("x", 0);
    int angleY = data.value("y", 0);
    auto rotOpt = ModelRotation::getModelRotation(angleX, angleY);
    if (!rotOpt.has_value()) {
        throw nlohmann::json::parse_error::create(
            101, 0,
            "Invalid BlockModelRotation: x=" + std::to_string(angleX) + ", y=" + std::to_string(angleY),
            nullptr
        );
    }
    return *rotOpt;
}

// Extract weight value, ensuring it's at least 1
static unsigned int extractWeight(const nlohmann::json& data) {
    int w = data.value("weight", 1);
    if (w <= 0) {
        throw nlohmann::json::parse_error::create(
            101, 0,
            "Weight must be positive integer, got: " + std::to_string(w),
            nullptr
        );
    }
    return static_cast<unsigned int>(w);
}

// Constructor implementation remains unchanged in behavior
Variant::Variant(ResourceLocation modelLoc, const ModelRotation& rot, bool lockUV, int w) :
    m_modelLocation(std::move(modelLoc)), m_rotation(rot), m_uvLock(lockUV), m_weight(w) {}

// Accessors
const ResourceLocation& Variant::getBlockModel() const { return m_modelLocation; }
const ModelRotation& Variant::getOrientation() const { return m_rotation; }
bool Variant::isUVLocked() const { return m_uvLock; }
int Variant::getStrength() const { return m_weight; }

// Equality comparison
bool Variant::operator==(const Variant& rhs) const {
    return m_modelLocation == rhs.m_modelLocation &&
           m_rotation == rhs.m_rotation &&
           m_uvLock == rhs.m_uvLock &&
           m_weight == rhs.m_weight;
}

bool Variant::operator!=(const Variant& rhs) const { return !(*this == rhs); }

// Hash function using polynomial rolling hash (31-based)
std::size_t Variant::hashValue() const {
    std::size_t seed = ResourceLocation::Hash{}(m_modelLocation);
    seed = 31 * seed + m_rotation.hashValue();
    seed = 31 * seed + std::hash<bool>{}(m_uvLock);
    seed = 31 * seed + static_cast<std::size_t>(m_weight);
    return seed;
}

// String representation
std::string Variant::describe() const {
    std::ostringstream buffer;
    buffer << "Variant{"
           << "model=" << m_modelLocation.toString() << ", "
           << "rotation=" << m_rotation.toString() << ", "
           << "uvlock=" << (m_uvLock ? "true" : "false") << ", "
           << "weight=" << m_weight << "}";
    return buffer.str();
}

// JSON deserialization helpers
Variant Variant::fromJSON(const nlohmann::json& input) {
    std::string modelPath = input.at("model").get<std::string>();
    ModelRotation orientation = extractRotation(input);
    bool uvLockFlag = input.value("uvlock", false);
    unsigned int strength = extractWeight(input);

    return Variant(buildBlockModelPath(modelPath), orientation, uvLockFlag, static_cast<int>(strength));
}

// Free function for nlohmann::json integration
void from_json(const nlohmann::json& j, Variant& out) {
    out = Variant::fromJSON(j);
}

// Serialization back to JSON
void to_json(nlohmann::json& j, const Variant& v) {
    j = nlohmann::json{
        {"model", v.getBlockModel().toString()},
        {"x", v.getOrientation().getX()},
        {"y", v.getOrientation().getY()},
        {"uvlock", v.isUVLocked()},
        {"weight", v.getStrength()}
    };
}

