void VolumeCreator::process(Ctl &ctl)
{
    if (!validate(m_input))
        throw std::runtime_error("Bad input data for EmbossCreateVolumeJob.");
    m_result = build_mesh(*m_input.base, is_cancelled(ctl, *m_input.base), ctl);
}

void VolumeCreator::finalize(bool canceled, std::exception_ptr &eptr)
{
    if (!::complete_job(canceled, eptr, *m_input.base))
        return;
    if (m_result.its.empty())
        return show_message("Can't create empty volume.");
