SurfaceVolumeData::ModelSources prepare_volume_sources(const ModelVolume &text_volume)
{
    const ModelVolumePtrs &volumes = text_volume.get_object()->volumes;
    // no other volume in object
    if (volumes.size() <= 1)
        return {};
    return ::gather_sources(volumes, text_volume.id().id);
}

bool initiate_volume_creation(CreateVolumeParams &input, const Vec2d &mouse_pos)
{
    if (input.data == nullptr)
        return false;
    if (!validate(input))
        return false;
    if (input.gl_volume == nullptr)
        // object is not under mouse position soo create object on plater
        return ::initiate_object_creation_job(input, mouse_pos);
    bool try_no_coor = true;
    return ::initiate_volume_on_surface_job(input, mouse_pos, try_no_coor);
}

bool initiate_volume_without_position(CreateVolumeParams &input)
{
    assert(input.data != nullptr);
    if (input.data == nullptr)
        return false;
    if (!validate(input))
        return false;

    // select position by camera position and view direction
    const Selection &selection = input.canvas.get_selection();
    int object_idx = selection.get_object_idx();
    Size s = input.canvas.get_canvas_size();
    Vec2d screen_center(s.get_width() / 2., s.get_height() / 2.);
    const ModelObjectPtrs &objects = selection.get_model()->objects;

    // No selected object so create new object
    if (selection.is_empty() || object_idx < 0 || static_cast<size_t>(object_idx) >= objects.size())
        // create Object on center of screen
        // when ray throw center of screen not hit bed it create object on center of bed
        return ::initiate_object_creation_job(input, screen_center);

    // create volume inside of selected object
    Vec2d coor;
    const Camera &camera = wxGetApp().plater()->get_camera();
    input.gl_volume = ::locate_nearest(selection, screen_center, camera, objects, &coor);
    if (input.gl_volume == nullptr)
        return ::initiate_object_creation_job(input, screen_center);

    bool try_no_coor = false;
    return ::initiate_volume_on_surface_job(input, coor, try_no_coor);
}

#ifdef EXECUTE_UPDATE_ON_MAIN_THREAD
namespace
{
// Run Job on main thread (blocking) - ONLY DEBUG
static inline bool execute_job_direct(std::shared_ptr<Job> j)
{
    struct MyCtl : public Job::Ctl
    {
        void update_status(int st, const std::string &msg = "") override {};
        bool was_canceled() const override { return false; }
        std::future<void> call_on_main_thread(std::function<void()> fn) override { return std::future<void>{}; }
    } ctl;
    j->process(ctl);
    wxGetApp().plater()->CallAfter(
        [j]()
        {
            std::exception_ptr e_ptr = nullptr;
            j->finalize(false, e_ptr);
        });
    return true;
}
} // namespace
#endif

bool initiate_volume_update(DataUpdate &&data, const ModelVolume &volume, const Selection &selection,
                            RaycastManager &raycaster)
{
    assert(data.volume_id == volume.id());

    // check cutting from source mesh
    bool &use_surface = data.base->shape.projection.use_surface;
    if (use_surface && volume.is_the_only_one_part())
        use_surface = false;

    std::unique_ptr<Job> job = nullptr;
    if (use_surface)
    {
        // Model to cut surface from.
        SurfaceVolumeData::ModelSources sources = prepare_volume_sources(volume);
        if (sources.empty())
            return false;

        Transform3d volume_transform = volume.get_matrix();
        const std::optional<Transform3d> &fix_3mf = volume.emboss_shape->fix_3mf_tr;
        if (fix_3mf.has_value())
            volume_transform = volume_transform * fix_3mf->inverse();

        // when it is new applying of use surface than move origin onto surface
        if (!volume.emboss_shape->projection.use_surface)
        {
            auto offset = calc_surface_offset(selection, raycaster);
            if (offset.has_value())
                volume_transform *= Eigen::Translation<double, 3>(*offset);
        }

        UpdateSurfaceVolumeData surface_data{std::move(data), {volume_transform, std::move(sources)}};
        job = std::make_unique<UpdateSurfaceVolumeJob>(std::move(surface_data));
    }
    else
    {
        job = std::make_unique<UpdateJob>(std::move(data));
    }

#ifndef EXECUTE_UPDATE_ON_MAIN_THREAD
    auto &worker = wxGetApp().plater()->get_ui_job_worker();
    return queue_job(worker, std::move(job));
#else
    // Run Job on main thread (blocking) - ONLY DEBUG
    return execute_job_direct(std::move(job));
#endif // EXECUTE_UPDATE_ON_MAIN_THREAD
}
