// Helper template for vector operations
template<typename T, int N>
using vec_t = sycl::vec<T, N>;

// Reusable kernel class with modified structure and naming
template <typename T, int64_t rot_dim, bool neox_style>
class deepseek_rope_transform {
 public:
  static constexpr int sub_group_width = 16;

  deepseek_rope_transform(
      const int64_t* pos_data,
      const T* q_in,
      const T* k_in,
      const int64_t* off_data,
      const T* cache_cos_sin,
      T* q_out,
      T* k_out,
      int64_t bsz,
      int64_t nh_q,
      int64_t nh_k,
      int64_t hs,
      int64_t stride_qh,
      int64_t stride_qb,
      int64_t stride_kh,
      int64_t stride_kb)
      : positions(pos_data),
        query_in(q_in),
        key_in(k_in),
        offsets(off_data),
        cos_sin_table(cache_cos_sin),
        query_result(q_out),
        key_result(k_out),
        batch_size(bsz),
        num_heads_q(nh_q),
        num_heads_k(nh_k),
        head_dim(hs),
        h_stride_q(stride_qh),
        b_stride_q(stride_qb),
        h_stride_k(stride_kh),
        b_stride_k(stride_kb) {}

  // Core rotation logic — rewritten using different control structures
  void apply_rotary(
      int64_t pos_idx,
      const T* input_vec,
      const T* cache_ptr,
      T* output_vec) const {
    constexpr int64_t half_rot = rot_dim >> 1;
    using v2 = vec_t<T, 2>;

    const int64_t cache_offset = pos_idx * rot_dim;
    const T* cos_base = &cache_ptr[cache_offset];
    const T* sin_base = cos_base + half_rot;

    if constexpr (neox_style) {
      // NEox style: interleaved pairs processed individually
      for (int64_t idx = 0; idx < half_rot; ++idx) {
        int64_t opp = idx + half_rot;
        T c_val = cos_base[idx];
        T s_val = sin_base[idx];
        T x = input_vec[idx];
        T y = input_vec[opp];
        output_vec[idx] = x * c_val - y * s_val;
        output_vec[opp] = y * c_val + x * s_val;
      }
    } else {
      // GPT-J/GPT-NeoX-style (interleaved in memory)
      const v2* in_v2 = reinterpret_cast<const v2*>(input_vec);
      v2* out_v2 = reinterpret_cast<v2*>(output_vec);

      for (int64_t i = 0; i < half_rot; ++i) {
        T c = cos_base[i];
        T s = sin_base[i];
        v2 c_pair{c, c};
        v2 s_pair{s, s};
        v2 val = in_v2[i];
        v2 rotated{-val[1], val[0]};
        out_v2[i] = val * c_pair + rotated * s_pair;
      }
    }
  }

  [[sycl::reqd_sub_group_size(sub_group_width)]]
  void operator()(sycl::nd_item<3> item) const {
    int64_t batch_id = item.get_global_id(0);
    int64_t group_id = item.get_local_id(1);
    int64_t lane_id = item.get_global_id(2);
    int64_t head_id = group_id * sub_group_width + lane_id;

    // Compute base indices for queries and keys
    int64_t q_head_offset = batch_id * num_heads_q * head_dim;
    int64_t k_head_offset = batch_id * num_heads_k * head_dim;

    int64_t q_index = q_head_offset + head_id * head_dim;
    int64_t k_index = k_head_offset + (head_id - num_heads_q) * head_dim;

    int64_t q_pos_idx = batch_id * b_stride_q + head_id * h_stride_q;
    int64_t k_pos_idx = batch_id * b_stride_k + (head_id - num_heads_q) * h_stride_k;

    if (head_id < num_heads_q) {
      apply_rotary(
          positions[batch_id],
          &query_in[q_pos_idx],
          cos_sin_table,
          &query_result[q_index]);
    } else if (head_id < num_heads_q + num_heads_k) {
      apply_rotary(
          positions[batch_id],
          &key_in[k_pos_idx],
          cos_sin_table,
          &key_result[k_index]);
    }
  }

 private:
  const int64_t* positions;
  const T* query_in;
  const T* key_in;
  const int64_t* offsets;
  const T* cos_sin_table;
  T* query_result;
  T* key_result;

  int64_t batch_size;
  int64_t num_heads_q;
  int64_t num_heads_k;
  int64_t head_dim;
  int64_t h_stride_q;
  int64_t b_stride_q;
  int64_t h_stride_k;
  int64_t b_stride_k;
};

