// Dispatch function — refactored with alternative dispatch mechanism
template <typename T>
void launch_deepseek_rope(
    const int64_t* pos,
    const T* q_in,
    const T* k_in,
    const int64_t* off,
    const T* cache,
    T* q_out,
    T* k_out,
    int64_t bsz,
    int64_t nh_q,
    int64_t nh_k,
    int64_t hs,
    int64_t rot_dim,
    bool use_neox,
    int64_t h_stride_q,
    int64_t b_stride_q,
    int64_t h_stride_k,
    int64_t b_stride_k) {

  constexpr std::array<int64_t, 5> valid_dims = {32, 64, 96, 128, 256};
  auto found = std::find(valid_dims.begin(), valid_dims.end(), rot_dim);
  TORCH_CHECK(
      found != valid_dims.end(),
      "Unsupported rotary dimension: ", rot_dim,
      ". Allowed values are 32, 64, 96, 128, 256.");

  TORCH_CHECK(
      rot_dim == hs,
      "Rotary dimension (", rot_dim, ") must match head size (", hs, ").");

  int dim_idx = std::distance(valid_dims.begin(), found);
  int mode_idx = use_neox ? 1 : 0;
  int table_idx = mode_idx * valid_dims.size() + dim_idx;

  using KernelLauncher = void (*)(
      sycl::queue&,
      const int64_t*, const T*, const T*, const int64_t*, const T*, T*, T*,
      int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t, int64_t);

#define CASE(dim, neox) \
  [](sycl::queue& q, \
     const int64_t* p, \
     const T* qi, \
     const T* ki, \
     const int64_t* o, \
     const T* c, \
     T* qo, \
     T* ko, \
     int64_t b, \
     int64_t nq, \
     int64_t nk, \
     int64_t d, \
     int64_t sqh, \
     int64_t sqb, \
     int64_t skh, \
     int64_t skb) { \
    constexpr int sg = 16; \
    int groups_per_head = (nq + nk + sg - 1) / sg; \
    sycl::range<3> local(1, groups_per_head, sg); \
    sycl::range<3> global(b, groups_per_head, sg); \
    at::DeviceGuard guard(at::Device(at::kXPU, at::xpu::current_device())); \
    q.submit([&](sycl::handler& h) { \
      h.parallel_for( \
        sycl::nd_range<3>(global, local), \
        vllm::deepseek_rope_transform<T, dim, neox>{ \
          p, qi, ki, o, c, qo, ko, b, nq, nk, d, sqh, sqb, skh, skb}); \
    }); \
  }

  static constexpr std::array<KernelLauncher, 10> dispatch_table = {{
    CASE(32, false),
    CASE(64, false),
    CASE(96, false),
    CASE(128, false),
    CASE(256, false),
    CASE(32, true),
    CASE(64, true),
    CASE(96, true),
    CASE(128, true),
    CASE(256, true)
  }};

#undef CASE

  auto& queue = vllm::xpu::vllmGetQueue();
  dispatch_table[table_idx](
      queue,
      pos,
      q_in,
      k_in,
      off,
      cache,
      q_out,
      k_out,
      bsz,
      nh_q,
      nh_k,
      hs,
      h_stride_q,
      b_stride_q,
      h_stride_k,
      b_stride_k);
}

// Public API wrapper — rewritten with equivalent semantics
std::tuple<torch::Tensor, torch::Tensor> deepseek_scaling_rope(
    const torch::Tensor& positions,
    const torch::Tensor& query,
    const torch::Tensor& key,
    const c10::optional<torch::Tensor>& offsets_opt,
    const torch::Tensor& cos_sin_cache,
    int64_t rotary_dim,
    bool is_neox) {

  auto q_shape = query.sizes();
  auto q_strides = query.strides();
  int64_t hs = q_shape[2];
  int64_t nh_q = q_shape[1];
  int64_t bsz = q_shape[0];
  int64_t sqh = q_strides[1];
  int64_t sqb = q_strides[0];

  auto k_shape = key.sizes();
  auto k_strides = key.strides();
  int64_t nh_k = k_shape[1];
  int64_t skh = k_strides[1];
  int64_t skb = k_strides[0];

  auto query_out = at::empty_like(query);
  auto key_out = at::empty_like(key);

  if (is_neox) {
    query_out = query_out.view({1, bsz, nh_q, hs});
    key_out = key_out.view({1, bsz, nh_k, hs});
  }

  TORCH_CHECK(
      cos_sin_cache.size(1) == hs,
      "cos_sin_cache second dimension (", cos_sin_cache.size(1),
      ") must match head size (", hs, ").");

  const c10::MaybeOwned<torch::Tensor> offsets_maybe =
      at::borrow_from_optional_tensor(offsets_opt);
  const torch::Tensor& offsets = *offsets_maybe;
  void* off_ptr = offsets.defined() ? offsets.data_ptr() : nullptr;

  switch (query.scalar_type()) {
    case torch::kFloat32:
      launch_deepseek_rope<float>(
          reinterpret_cast<int64_t*>(positions.data_ptr()),
          reinterpret_cast<float*>(query.data_ptr()),
          reinterpret_cast<float*>(key.data_ptr()),
          reinterpret_cast<int64_t*>(off_ptr),
          reinterpret_cast<float*>(cos_sin_cache.data_ptr()),
          reinterpret_cast<float*>(query_out.data_ptr()),
          reinterpret_cast<float*>(key_out.data_ptr()),
          bsz,
          nh_q,
          nh_k,
          hs,
          rotary_dim,
          is_neox,
          sqh,
          sqb,
          skh,
          skb);
      break;

    case torch::kFloat16:
      launch_deepseek_rope<sycl::half>(
          reinterpret_cast<int64_t*>(positions.data_ptr()),
          reinterpret_cast<sycl::half*>(query.data_ptr()),
          reinterpret_cast<sycl::half*>(key.data_ptr()),
          reinterpret_cast<int64_t*>(off_ptr),
          reinterpret_cast<sycl::half*>(cos_sin_cache.data_ptr()),
          reinterpret_cast<sycl::half*>(query_out.data_ptr()),
          reinterpret_cast<sycl::half*>(key_out.data_ptr()),
          bsz,
          nh_q,
          nh_k,
          hs,
          rotary_dim,
          is_neox,
          sqh,
          sqb,
          skh,
          skb);
      break;

    case torch::kBFloat16:
      launch_deepseek_rope<sycl::ext::oneapi::bfloat16>(
          reinterpret_cast<int64_t*>(positions.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(query.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(key.data_ptr()),
          reinterpret_cast<int64_t*>(off_ptr),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(
              cos_sin_cache.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(query_out.data_ptr()),
          reinterpret_cast<sycl::ext::oneapi::bfloat16*>(key_out.data_ptr()),
          bsz,
          nh_q,
          nh_k,
          hs,
          rotary_dim,
          is_neox,
          sqh,
          sqb,
          skh,
          skb);
      break;

    default:
      throw std::invalid_argument(
          "Unsupported dtype. Only float32, float16, and bfloat16 are supported.");
  }

  return std::make_tuple(query_out, key_out);
}

