    static void TerminateEditing(HWND hwndEdit, t_uint32 reason) {
        CWindow parent = ::GetParent(hwndEdit);
        parent.SendMessage(MSG_DISABLE_EDITING);
        parent.PostMessage(MSG_COMPLETION, reason, 0);
    }

    static bool AreInSamePopup(CWindow w1, CWindow w2) {
        return pfc::findOwningPopup(w1) == pfc::findOwningPopup(w2);
    }

    static void HandleMouseInteraction(HWND targetHwnd, CPoint pt, bool isWheelEvent) {
        auto shouldCancel = [&](HWND editBox) -> bool {
            if (targetHwnd != editBox && AreInSamePopup(targetHwnd, editBox)) {
                return true;
            }
            if (isWheelEvent) {
                CWindow hitTest = WindowFromPoint(pt);
                return hitTest != editBox && AreInSamePopup(hitTest, editBox);
            }
            return false;
        };

        for (auto& edit : g_activeEditBoxes) {
            if (shouldCancel(edit)) {
                TerminateEditing(edit, KEditLostFocus);
            }
        }
    }

    static LRESULT CALLBACK MouseFilterProc(int nCode, WPARAM wParam, LPARAM lParam) {
        if (nCode == HC_ACTION) {
            auto const mhs = reinterpret_cast<const MOUSEHOOKSTRUCT*>(lParam);
            switch (wParam) {
            case WM_NCLBUTTONDOWN: case WM_NCRBUTTONDOWN: case WM_NCMBUTTONDOWN: case WM_NCXBUTTONDOWN:
            case WM_LBUTTONDOWN:   case WM_RBUTTONDOWN:   case WM_MBUTTONDOWN:   case WM_XBUTTONDOWN:
                HandleMouseInteraction(mhs->hwnd, mhs->pt, false);
                break;
            case WM_MOUSEWHEEL: case WM_MOUSEHWHEEL:
                HandleMouseInteraction(mhs->hwnd, mhs->pt, true);
                break;
            }
        }
        return CallNextHookEx(g_mouseHook, nCode, wParam, lParam);
    }

    static void RegisterEditBox(HWND hwnd) {
        g_activeEditBoxes.push_front(hwnd);
        if (!g_mouseHook) {
            g_mouseHook = SetWindowsHookEx(WH_MOUSE, MouseFilterProc, NULL, GetCurrentThreadId());
        }
    }

    static void UnregisterEditBox(HWND hwnd) {
        auto it = std::find(g_activeEditBoxes.begin(), g_activeEditBoxes.end(), hwnd);
        if (it != g_activeEditBoxes.end()) {
            g_activeEditBoxes.erase(it);
        }
        if (g_activeEditBoxes.empty() && g_mouseHook) {
            UnhookWindowsHookEx(g_mouseHook);
            g_mouseHook = nullptr;
        }
    }

    class EditBoxImpl : public CWindowImpl<EditBoxImpl, CEdit> {
    public:
        explicit EditBoxImpl(uint32_t flags) : m_flags(flags) {}

        BEGIN_MSG_MAP_EX(EditBoxImpl)
            MSG_WM_DESTROY(OnDestroy)
            MSG_WM_GETDLGCODE(OnGetDlgCode)
            MSG_WM_KILLFOCUS(OnKillFocus)
            MSG_WM_CHAR(OnChar)
            MSG_WM_KEYDOWN(OnKeyDown)
            MSG_WM_PASTE(OnPaste)
        END_MSG_MAP()

        void OnCreation() { RegisterEditBox(m_hWnd); }

    private:
        void OnDestroy() {
            m_selfDestruct = true;
            UnregisterEditBox(m_hWnd);
            SetMsgHandled(FALSE);
        }

        int OnCreate(LPCREATESTRUCT lpcs) {
            OnCreation();
            SetMsgHandled(FALSE);
            return 0;
        }

        UINT OnGetDlgCode(LPMSG lpMsg) {
            if (!lpMsg) { SetMsgHandled(FALSE); return 0; }

            switch (lpMsg->message) {
            case WM_KEYDOWN: case WM_SYSKEYDOWN:
                switch (lpMsg->wParam) {
                case VK_TAB: case VK_ESCAPE: case VK_RETURN:
                    return DLGC_WANTMESSAGE;
                default:
                    SetMsgHandled(FALSE); return 0;
                }
            default:
                SetMsgHandled(FALSE); return 0;
            }
        }

        void OnKillFocus(CWindow wndFocus) {
            if (wndFocus) ForwardCompletion(KEditLostFocus);
            SetMsgHandled(FALSE);
        }

        bool ValidatePasteInput(const char* input) const {
            if (m_flags & InPlaceEdit::KFlagNumberSigned) {
                if (pfc::string_is_numeric(input)) return true;
                if (input[0] == '-' && pfc::string_is_numeric(input + 1) && GetWindowTextLength() == 0) return true;
                return false;
            }
            if (m_flags & InPlaceEdit::KFlagNumber) {
                return pfc::string_is_numeric(input);
            }
            return true;
        }

        void OnPaste() {
            if (m_flags & (InPlaceEdit::KFlagNumber | InPlaceEdit::KFlagNumberSigned)) {
                pfc::string8 temp;
                ClipboardHelper::OpenScope scope; scope.Open(m_hWnd);
                if (ClipboardHelper::GetString(temp) && !ValidatePasteInput(temp)) {
                    return;
                }
            }
            SetMsgHandled(FALSE);
        }

        bool ValidateChar(UINT ch) const {
            if (ch < ' ') return true;

            if (m_flags & InPlaceEdit::KFlagNumberSigned) {
                if (pfc::char_is_numeric(ch)) return true;
                if (ch == '-' && GetWindowTextLength() == 0) return true;
                return false;
            }
            if (m_flags & InPlaceEdit::KFlagNumber) {
                return pfc::char_is_numeric(ch);
            }
            return true;
        }

        void OnChar(UINT ch, UINT repeat, UINT flags) {
            (void)repeat;
            if (m_suppressedKey != 0 && (flags & 0xFF) == m_suppressedKey) return;

            if (!ValidateChar(ch)) {
                MessageBeep(0);
                return;
            }

            SetMsgHandled(FALSE);
        }

        void OnKeyDown(UINT vk, UINT repeat, UINT flags) {
            (void)repeat;
            m_suppressedKey = flags & 0xFF;

            switch (vk) {
            case VK_BACK:
                if (GetHotkeyModifierFlags() == MOD_CONTROL) {
                    CEditPPHooks::DeleteLastWord(*this);
                    return;
                }
                break;
            case 'A':
                if (GetHotkeyModifierFlags() == MOD_CONTROL) {
                    this->SetSelAll(); return;
                }
                break;
            case VK_RETURN:
                if (!IsKeyPressed(VK_LCONTROL) && !IsKeyPressed(VK_RCONTROL)) {
                    ForwardCompletion(KEditEnter);
                    return;
                }
                break;
            case VK_TAB:
                ForwardCompletion(IsKeyPressed(VK_SHIFT) ? KEditShiftTab : KEditTab);
                return;
            case VK_ESCAPE:
                ForwardCompletion(KEditAborted);
                return;
            }

            m_suppressedKey = 0;
            SetMsgHandled(FALSE);
        }

        void ForwardCompletion(t_uint32 reason) {
            if (IsWindowEnabled()) {
                CWindow owner = GetParent();
                owner.SendMessage(MSG_DISABLE_EDITING);
                owner.PostMessage(MSG_COMPLETION, reason, 0);
                EnableWindow(FALSE);
            }
        }

        const uint32_t m_flags;
        bool m_selfDestruct = false;
        UINT m_suppressedKey = 0;
    };

    class ContainerWindow : public CWindowImpl<ContainerWindow> {
    public:
        DECLARE_WND_CLASS_EX(_T("{54340C80-248C-4b8e-8CD4-D624A8E9377B}"), 0, -1);

        HWND Create(CWindow parent) {
            RECT clippedRect;
            {
                RECT client;
                WIN32_OP_D(parent.GetClientRect(&client));
                IntersectRect(&clippedRect, &client, &m_initialRect);
            }

            const DWORD style = WS_BORDER | WS_CHILD;
            AdjustWindowRect(&clippedRect, style, FALSE);

            WIN32_OP(__super::Create(parent, clippedRect, NULL, style) != NULL);

            try {
                CRect clientArea;
                WIN32_OP_D(GetClientRect(clientArea));

                DWORD editStyle = WS_CHILD | WS_VISIBLE;
                if (m_flags & KFlagMultiLine) {
                    editStyle |= WS_VSCROLL | ES_MULTILINE;
                } else {
                    editStyle |= ES_AUTOHSCROLL;
                }
                if (m_flags & KFlagReadOnly) editStyle |= ES_READONLY;
                if (m_flags & KFlagAlignCenter) editStyle |= ES_CENTER;
                else if (m_flags & KFlagAlignRight) editStyle |= ES_RIGHT;
                else editStyle |= ES_LEFT;

                CEdit editControl;
                WIN32_OP(editControl.Create(*this, clientArea, NULL, editStyle, ID_EDIT_BOX) != NULL);
                editControl.SetFont(parent.GetFont());

                if ((m_flags & KFlagDark) != 0) DarkMode::DarkenEditLite(editControl);

                if (m_acData) InitializeSimpleAC(editControl, m_acData.get_ptr(), m_acOptions);
                m_edit.SubclassWindow(editControl);
                m_edit.OnCreation();

                pfc::setWindowText(m_edit, *m_content);
                m_edit.SetSelAll();
            } catch (...) {
                PostMessage(MSG_COMPLETION, InPlaceEdit::KEditAborted, 0);
                return m_hWnd;
            }

            ShowWindow(SW_SHOW);
            m_edit.SetFocus();
            m_initialized = true;
            PFC_ASSERT(m_hWnd != NULL);
            return m_hWnd;
        }

        ContainerWindow(const RECT& rect, t_uint32 flags, pfc::rcptr_t<pfc::string_base> content, reply_t notify, IUnknown* acData, DWORD acOpts)
            : m_content(content), m_notify(notify), m_initialRect(rect),
              m_flags(flags), m_acData(acData), m_acOptions(acOpts),
              m_edit(flags) {}

        enum { ID_EDIT_BOX = 666 };

        BEGIN_MSG_MAP_EX(ContainerWindow)
            MESSAGE_HANDLER_EX(WM_CTLCOLOREDIT, MsgForwardToParent)
            MESSAGE_HANDLER_EX(WM_CTLCOLORSTATIC, MsgForwardToParent)
            MESSAGE_HANDLER_EX(WM_MOUSEWHEEL, MsgLostFocus)
            MESSAGE_HANDLER_EX(WM_MOUSEHWHEEL, MsgLostFocus)
            MESSAGE_HANDLER_SIMPLE(MSG_DISABLE_EDITING, OnMsgDisableEditing)
            MESSAGE_HANDLER_EX(MSG_COMPLETION, OnMsgCompletion)
            COMMAND_HANDLER_EX(ID_EDIT_BOX, EN_CHANGE, OnEditChange)
            MSG_WM_DESTROY(OnDestroy)
        END_MSG_MAP()

        HWND GetEditBoxHandle() const { return m_edit; }

    private:
        void OnDestroy() { m_selfDestruct = true; }

        LRESULT MsgForwardToParent(UINT msg, WPARAM wp, LPARAM lp) {
            return GetParent().SendMessage(msg, wp, lp);
        }

        LRESULT MsgLostFocus(UINT, WPARAM, LPARAM) {
            PostMessage(MSG_COMPLETION, InPlaceEdit::KEditLostFocus, 0);
            return 0;
        }

        void OnMsgDisableEditing() {
            ShowWindow(SW_HIDE);
            GetParent().UpdateWindow();
            m_editingDisabled = true;
        }

        LRESULT OnMsgCompletion(UINT, WPARAM wParam, LPARAM) {
            PFC_ASSERT(m_initialized);
            if ((wParam & KEditMaskReason) != KEditLostFocus) {
                GetParent().SetFocus();
            }
            if (m_modified && m_edit != NULL) {
                *m_content = pfc::getWindowText(m_edit);
            }
            FinalizeCompletion(static_cast<unsigned>(wParam));
            if (!m_selfDestruct) {
                m_selfDestruct = true;
                DestroyWindow();
            }
            return 0;
        }

        void OnEditChange(UINT, int, CWindow src) {
            if (m_initialized && !m_editingDisabled) {
                *m_content = pfc::getWindowText(src);
                m_modified = true;
            }
        }

        void FinalizeCompletion(unsigned status) {
            if (!m_completed) {
                m_completed = true;
                unsigned finalStatus = status & KEditMaskReason;
                if (m_modified && finalStatus != KEditAborted) {
                    finalStatus |= KEditFlagContentChanged;
                }
                if (m_notify) m_notify(finalStatus);
            }
        }

        const pfc::rcptr_t<pfc::string_base> m_content;
        const reply_t m_notify;
        bool m_completed = false;
        bool m_initialized = false, m_modified = false;
        bool m_editingDisabled = false;
        bool m_selfDestruct = false;
        const CRect m_initialRect;
        const t_uint32 m_flags;
        EditBoxImpl m_edit;

        const pfc::com_ptr_t<IUnknown> m_acData;
        const DWORD m_acOptions;
    };
}

