bool InPlaceEdit::TableEditAdvance_ListView(HWND listView, unsigned colBase, unsigned& item, unsigned& col, unsigned itemCount, unsigned colCount, unsigned event) {
    if (col >= colCount) return false;

    pfc::array_t<t_size> reverseOrder;
    {
        pfc::array_t<unsigned> order;
        const unsigned totalColumns = ListView_GetColumnCount(listView);
        PFC_ASSERT(totalColumns >= colBase + colCount);
        pfc::array_t<int> columnOrder; columnOrder.set_size(totalColumns);
        if (!ListView_GetColumnOrderArray(listView, totalColumns, columnOrder.get_ptr())) {
            PFC_ASSERT(!"Failed to get column order array");
            return false;
        }
        order.set_size(colCount);
        for (unsigned i = 0; i < colCount; ++i) order[i] = columnOrder[colBase + i];

        reverseOrder.set_size(colCount);
        order_helper::g_fill(reverseOrder);
        pfc::sort_get_permutation_t(order, pfc::compare_t<unsigned, unsigned>, colCount, reverseOrder.get_ptr());
    }

    unsigned visibleCol = static_cast<unsigned>(reverseOrder[col]);

    if (!TableEditAdvance(item, visibleCol, itemCount, colCount, event)) return false;

    col = static_cast<unsigned>(order_helper::g_find_reverse(reverseOrder.get_ptr(), visibleCol));
    return true;
}

bool InPlaceEdit::TableEditAdvance(unsigned& item, unsigned& col, unsigned itemCount, unsigned colCount, unsigned event) {
    if (item >= itemCount || col >= colCount) return false;
    int delta = 0;

    switch (event & KEditMaskReason) {
    case KEditEnter:     delta = colCount; break;
    case KEditTab:       delta = 1;        break;
    case KEditShiftTab:  delta = -1;       break;
    default:             return false;
    }

    while (delta > 0) {
        ++col;
        if (col >= colCount) {
            col = 0;
            ++item;
            if (item >= itemCount) return false;
        }
        --delta;
    }

    while (delta < 0) {
        if (col == 0) {
            if (item == 0) return false;
            --item;
            col = colCount;
        }
        --col;
        ++delta;
    }

    return true;
}

HWND InPlaceEdit::StartEx(HWND parent, const RECT& rect, unsigned flags, pfc::rcptr_t<pfc::string_base> content, reply_t notify, IUnknown* acData, DWORD acOpts) {
    try {
        PFC_ASSERT((CWindow(parent).GetWindowLong(GWL_STYLE) & WS_CLIPCHILDREN) != 0);
        return (new CWindowCreateAndDelete<ContainerWindow>(parent, rect, flags, content, notify, acData, acOpts))->GetEditBoxHandle();
    } catch (...) {
        ReportFailure(notify);
        return NULL;
    }
}

void InPlaceEdit::Start_FromListViewEx(HWND listView, unsigned item, unsigned subitem, unsigned lines, unsigned flags, pfc::rcptr_t<pfc::string_base> content, reply_t notify) {
    try {
        ListView_EnsureVisible(listView, item, FALSE);
        RECT itemRect;
        WIN32_OP_D(ListView_GetSubItemRect(listView, item, subitem, LVIR_LABEL, &itemRect));

        const bool isMultiline = lines > 1;
        if (isMultiline) {
            itemRect.bottom = itemRect.top + (itemRect.bottom - itemRect.top) * lines;
        }

        StartEx(listView, itemRect, flags | (isMultiline ? KFlagMultiLine : 0), content, notify);
    } catch (...) {
        ReportFailure(notify);
    }
}

