// Helper function to locate substring positions with specific conditions
size_t locatePatternPosition(std::string &sequence, const std::string &pattern1, const std::string &pattern2) {
    size_t first_pos = std::string::npos;
    size_t second_pos = std::string::npos;

    // Search for first pattern
    for (size_t idx = 0; idx != std::string::npos; idx++) {
        idx = sequence.find(pattern1, idx);
        if (idx == std::string::npos) break;
        if (idx+2 >= sequence.length() || !isalpha(sequence[idx+2])) {
            first_pos = idx;
            break;
        }
    }

    // Search for second pattern
    for (size_t jdx = 0; jdx != std::string::npos; jdx++) {
        jdx = sequence.find(pattern2, jdx);
        if (jdx == std::string::npos) break;
        if (jdx+2 >= sequence.length() || !isalpha(sequence[jdx+2])) {
            second_pos = jdx;
            break;
        }
    }

    // Return earliest valid position
    if (first_pos != std::string::npos && second_pos != std::string::npos) {
        return (first_pos < second_pos) ? first_pos : second_pos;
    } else if (first_pos != std::string::npos) {
        return first_pos;
    } else {
        return second_pos;
    }
}

// Find position of heterotachy rate model in model name
size_t findHeterotachyPosition(std::string &model_name) {
    return locatePatternPosition(model_name, "+H", "*H");
}

// Find position of free rate model in model name
size_t findFreeRatePosition(std::string &model_name) {
    return locatePatternPosition(model_name, "+R", "*R");
}

// Find position of PoMo model in model name
size_t findPoMoPosition(std::string &model_name) {
    return locatePatternPosition(model_name, "+P", "*P");
}

ModelsBlock *readModelsDefinition(Params &params) {
    ModelsBlock *models_block = new ModelsBlock;
    try
    {
        // loading internal model definitions
        std::stringstream input_stream(builtin_mixmodels_definition);
        ASSERT(input_stream && "stringstream is OK");
        NxsReader nexus;
        nexus.Add(models_block);
        MyToken token(input_stream);
        nexus.Execute(token);
    } catch (...) {
        ASSERT(0 && "predefined mixture models not initialized");
    }
    try
    {
        // loading internal protein model definitions
        std::stringstream prot_stream(builtin_prot_models);
        ASSERT(prot_stream && "stringstream is OK");
        NxsReader nexus;
        nexus.Add(models_block);
        MyToken token(prot_stream);
        nexus.Execute(token);
    } catch (...) {
        ASSERT(0 && "predefined protein models not initialized");
    }
    if (params.model_def_file) {
        std::cout << "Reading model definition file " << params.model_def_file << " ... ";
        MyReader nexus(params.model_def_file);
        nexus.Add(models_block);
        MyToken token(nexus.inf);
        nexus.Execute(token);
        int num_model = 0, num_freq = 0;
        for (ModelsBlock::iterator it = models_block->begin(); it != models_block->end(); it++)
            if (it->second.flag & NM_FREQ) num_freq++; else num_model++;
        std::cout << num_model << " models and " << num_freq << " frequency vectors loaded" << std::endl;
    }
    return models_block;
}

