namespace {

bool supervisor_done = false;
pid_t child_process_id = 0;

constexpr const char* restart_msg = "will now start a new child process";
constexpr const char* no_restart_msg =
  "will intentionally not start a new child process";
constexpr const char* fix_error_msg =
  "please check what causes the child process to fail and fix the error "
  "first";

auto stop_handler = [](int) {
  SDB_INFO("xxxxx", Logger::STARTUP,
           "received SIGINT for supervisor); commanding client [", child_process_id,
           "] to shut down.");
  int rc = kill(child_process_id, SIGTERM);
  if (rc < 0) {
    SDB_ERROR("xxxxx", Logger::STARTUP, "commanding client [", child_process_id,
              "] to shut down failed: [", errno, "] ", strerror(errno));
  }
  supervisor_done = true;
};

auto hup_handler = [](int) {
  SDB_INFO("xxxxx", Logger::STARTUP,
           "received SIGHUP for supervisor); commanding client [", child_process_id,
           "] to logrotate.");
  int rc = kill(child_process_id, SIGHUP);
  if (rc < 0) {
    SDB_ERROR("xxxxx", Logger::STARTUP, "commanding client [", child_process_id,
              "] to logrotate failed: [", errno, "] ", strerror(errno));
  }
};

} // namespace

SupervisorFeature::SupervisorFeature(Server& server)
  : SerenedFeature{server, name()}, _is_supervisor(false), _child_pid(0) {
  setOptional(true);
}

void SupervisorFeature::collectOptions(
  std::shared_ptr<ProgramOptions> options) {
  options
    ->addOption(
      "--supervisor",
      "Start the server in supervisor mode. Requires --pid-file to be set.",
      new BooleanParameter(&_is_supervisor),
      sdb::options::MakeDefaultFlags(sdb::options::Flags::Uncommon))
    .setLongDescription(R"(Runs an serened process as supervisor with another
serened process as child, which acts as the server. In the event that the server
unexpectedly terminates due to an internal error, the supervisor automatically
restarts the server. Enabling this option implies that the server runs as a
daemon.)");
}

void SupervisorFeature::validateOptions(
  std::shared_ptr<ProgramOptions> options) {
  if (_is_supervisor) {
    try {
      DaemonFeature& daemon = server().getFeature<DaemonFeature>();
      daemon.setDaemon(true);
      daemon.validateOptions(options);
    } catch (...) {
      SDB_FATAL("xxxxx", sdb::Logger::FIXME,
                "daemon mode not available, cannot start supervisor");
    }
  }
}

void SupervisorFeature::daemonize() {
  static constexpr time_t min_survival_threshold_sec = 30;
  if (!_is_supervisor) {
    return;
  }

  time_t initial_start_time = time(nullptr);
  time_t current_time;
  bool termination_required = false;
  int exit_code = EXIT_SUCCESS;

  sdb::signals::UnmaskAllSignals();

  if (!server().hasFeature<LoggerFeature>()) {
    SDB_FATAL("xxxxx", Logger::STARTUP, "unknown feature 'Logger', giving up");
  }

  LoggerFeature& logger_instance = server().getFeature<LoggerFeature>();
  logger_instance.setSupervisor(true);
  logger_instance.prepare();

  SDB_DEBUG("xxxxx", Logger::STARTUP, "starting supervisor loop");

  do {
    logger_instance.setSupervisor(false);
    signal(SIGINT, SIG_DFL);
    signal(SIGTERM, SIG_DFL);

    SDB_DEBUG("xxxxx", Logger::STARTUP,
              "supervisor will now try to fork a new child process");

    _child_pid = fork();
    if (_child_pid < 0) {
      SDB_FATAL("xxxxx", Logger::STARTUP, "fork failed, giving up");
    }

    if (_child_pid > 0) {
      // Parent process: supervisor
      signal(SIGINT, stop_handler);
      signal(SIGTERM, stop_handler);
      signal(SIGHUP, hup_handler);

      SDB_INFO("xxxxx", Logger::STARTUP,
               "supervisor has forked a child process with pid ", _child_pid);

      SetProcessTitle("serenedb [supervisor]");
      SDB_DEBUG("xxxxx", Logger::STARTUP, "supervisor mode: within parent");

      child_process_id = _child_pid;
      supervisor_done = false;

      int wait_status = 0;
      int wait_result = waitpid(_child_pid, &wait_status, 0);
      bool abnormal_termination = true;

      SDB_INFO("xxxxx", Logger::STARTUP, "waitpid woke up with return value ",
               wait_result, " and status ", wait_status,
               " and DONE = ", (supervisor_done ? "true" : "false"));

      if (supervisor_done) {
        termination_required = true;
        abnormal_termination = false;
      } else {
        if (WIFEXITED(wait_status)) {
          int exit_val = WEXITSTATUS(wait_status);
          if (exit_val == 0) {
            SDB_INFO("xxxxx", Logger::STARTUP, "child process ", _child_pid,
                     " terminated normally. ", no_restart_msg);
            termination_required = true;
            abnormal_termination = false;
          } else {
            current_time = time(nullptr) - initial_start_time;
            if (current_time < min_survival_threshold_sec) {
              SDB_ERROR(
                "xxxxx", Logger::STARTUP, "child process ", _child_pid,
                " terminated unexpectedly, exit status ", exit_val,
                ". the child process only survived for ", current_time,
                " seconds. this is lower than the minimum threshold value "
                "of ",
                min_survival_threshold_sec, " s. ", no_restart_msg, ". ",
                fix_error_msg);
              termination_required = true;
            } else {
              SDB_ERROR("xxxxx", Logger::STARTUP, "child process ", _child_pid,
                        " terminated unexpectedly, exit status ",
                        exit_val, ". ", restart_msg);
              termination_required = false;
            }
          }
        } else if (WIFSIGNALED(wait_status)) {
          int term_signal = WTERMSIG(wait_status);
          switch (term_signal) {
            case 2:   // SIGINT
            case 9:   // SIGKILL
            case 15:  // SIGTERM
              SDB_INFO("xxxxx", Logger::STARTUP, "child process ", _child_pid,
                       " terminated normally, signal ", term_signal, " (",
                       sdb::signals::Name(term_signal), "). ", no_restart_msg);
              termination_required = true;
              abnormal_termination = false;
              break;
            default:
              current_time = time(nullptr) - initial_start_time;
              if (current_time < min_survival_threshold_sec) {
                SDB_ERROR("xxxxx", Logger::STARTUP, "child process ",
                          _child_pid, " terminated unexpectedly, signal ", term_signal,
                          " (", sdb::signals::Name(term_signal),
                          "). the child process only survived for ", current_time,
                          " seconds. this is lower than the minimum threshold "
                          "value of ",
                          min_survival_threshold_sec, " s. ", no_restart_msg, ". ",
                          fix_error_msg);
                termination_required = true;
#ifdef WCOREDUMP
                if (WCOREDUMP(wait_status)) {
                  SDB_WARN("xxxxx", Logger::STARTUP, "child process ",
                           _child_pid, " also produced a core dump");
                }
#endif
              } else {
                SDB_ERROR("xxxxx", Logger::STARTUP, "child process ",
                          _child_pid, " terminated unexpectedly, signal ", term_signal,
                          " (", sdb::signals::Name(term_signal), "). ", restart_msg);
                termination_required = false;
              }
              break;
          }
        } else {
          SDB_ERROR("xxxxx", Logger::STARTUP, "child process ", _child_pid,
                    " terminated unexpectedly, unknown cause. ", restart_msg);
          termination_required = false;
        }
      }

      exit_code = abnormal_termination ? EXIT_FAILURE : EXIT_SUCCESS;
    } else {
      // Child process: actual server
      log::Shutdown();
      log::Appender::allowStdLogging(false);
      DaemonFeature::remapStandardFileDescriptors();
      SDB_DEBUG("xxxxx", Logger::STARTUP, "supervisor mode: within child");
      SetProcessTitle("serenedb [server]");

#ifdef SERENEDB_HAVE_PRCTL
      prctl(PR_SET_PDEATHSIG, SIGTERM, 0, 0, 0);
#endif

      try {
        DaemonFeature& daemon = server().getFeature<DaemonFeature>();
        daemon.setDaemon(false);
      } catch (...) {
        // Ignore exceptions during child setup
      }

      return; // Child continues execution outside supervisor loop
    }
  } while (!termination_required);

  SDB_DEBUG("xxxxx", Logger::STARTUP, "supervisor mode: finished (exit ",
            exit_code, ")");
  log::Flush();
  log::Shutdown();
  exit(exit_code);
}

