#pragma intrinsic(_ReturnAddress)

// Debug flag constants
#define MCI_LOG_CALLS     1
#define MCI_LOG_DUMPS     2
#define MCI_LOG_SONGS     4
#define MCI_LOG_THREADS   8

// Default debug level: none
#define MCI_DEFAULT_DEBUG DEBUG_FLAGS_NONE

#ifdef DEBUGALL
    #undef MCI_DEFAULT_DEBUG
    #define MCI_DEFAULT_DEBUG DEBUG_FLAGS_EVERYTHING
#endif

UINT mci_debug_level = MCI_DEFAULT_DEBUG;

// Convert MCI message codes to human-readable strings
static const char* TranslateMciMessage(UINT msgCode) {
    switch (msgCode) {
        case MCI_OPEN:      return "MCI_OPEN";
        case MCI_CLOSE:     return "MCI_CLOSE";
        case MCI_PLAY:      return "MCI_PLAY";
        case MCI_SEEK:      return "MCI_SEEK";
        case MCI_STOP:      return "MCI_STOP";
        case MCI_PAUSE:     return "MCI_PAUSE";
        case MCI_INFO:      return "MCI_INFO";
        case MCI_STATUS:    return "MCI_STATUS";
        case MCI_RESUME:    return "MCI_RESUME";
        default:            return HexPls(msgCode, 8);
    }
}

// Hook function called before actual MCI call
extern "C" BOOL __stdcall PreHook_mciSendCommandA(void* callerAddr, MCIERROR* outResult,
                                                  MCIDEVICEID devId, UINT cmdCode,
                                                  DWORD_PTR flags, DWORD_PTR param) {
    if (mci_debug_level & MCI_LOG_CALLS) {
        ConsoleLog(LOG_DEBUG, "MCI: 0x%08p <-- invoking mciSendCommand(0x%08X, %s, 0x%08X, 0x%08X)\n",
                   callerAddr, devId, TranslateMciMessage(cmdCode), flags, param);
    }

    switch (cmdCode) {
        case MCI_OPEN: {
            if (mci_debug_level & (MCI_LOG_CALLS | MCI_LOG_DUMPS)) {
                auto* openParams = reinterpret_cast<MCI_OPEN_PARMS*>(param);
                ConsoleLog(LOG_NONE,
                    "MCI_OPEN_PARMS {\n"
                    "    dwCallback       = 0x%08X,\n"
                    "    wDeviceID        = 0x%08X,\n"
                    "    lpstrDeviceType  = %s,\n"
                    "    lpstrElementName = %s,\n"
                    "    lpstrAlias       = %s\n"
                    "}\n\n",
                    openParams->dwCallback,
                    openParams->wDeviceID,
                    ((UINT)(openParams->lpstrDeviceType) > 4096 && (INT)(openParams->lpstrDeviceType) != MCI_ALL_DEVICE_ID)
                        ? openParams->lpstrDeviceType : HexPls((UINT)(openParams->lpstrDeviceType), 8),
                    openParams->lpstrElementName,
                    (openParams->lpstrAlias == nullptr || (UINT)(openParams->lpstrAlias) == 0) ? "NULL" : openParams->lpstrAlias);
            }
            break;
        }

        case MCI_STATUS: {
            if (mci_debug_level & (MCI_LOG_CALLS | MCI_LOG_DUMPS)) {
                auto* statusParams = reinterpret_cast<MCI_STATUS_PARMS*>(param);
                ConsoleLog(LOG_NONE,
                    "MCI_STATUS_PARMS {\n"
                    "    dwCallback = 0x%08X,\n"
                    "    dwReturn   = 0x%08X,\n"
                    "    dwItem     = 0x%08X,\n"
                    "    dwTrack    = 0x%08X\n"
                    "}\n\n",
                    statusParams->dwCallback,
                    statusParams->dwReturn,
                    statusParams->dwItem,
                    statusParams->dwTrack);
            }
            break;
        }

        case MCI_PLAY: {
            if (mci_debug_level & (MCI_LOG_CALLS | MCI_LOG_DUMPS)) {
                auto* playParams = reinterpret_cast<MCI_PLAY_PARMS*>(param);
                ConsoleLog(LOG_NONE,
                    "MCI_PLAY_PARMS {\n"
                    "    dwCallback = 0x%08X,\n"
                    "    dwFrom     = 0x%08X,\n"
                    "    dwTo       = 0x%08X\n"
                    "}\n\n",
                    playParams->dwCallback,
                    playParams->dwFrom,
                    playParams->dwTo);
            }
            break;
        }

        case MCI_CLOSE:
            // No special handling needed
            break;

        default:
            if (mci_debug_level & MCI_LOG_CALLS) {
                ConsoleLog(LOG_WARNING, "MCI: unexpected command %s received.\n", TranslateMciMessage(cmdCode));
            }
            break;
    }

    *outResult = 0;
    return TRUE;
}

// Post-hook function (currently no-op)
extern "C" BOOL __stdcall PostHook_mciSendCommandA(void* callerAddr, MCIERROR* result,
                                                   MCIDEVICEID devId, UINT cmdCode,
                                                   DWORD_PTR flags, DWORD_PTR param) {
    return TRUE;
}

// Actual implementation of mciSendCommandA wrapper
extern "C" MCIERROR __stdcall _mciSendCommandA(MCIDEVICEID deviceID, UINT command,
                                               DWORD_PTR flags, DWORD_PTR parameters) {
    MCIERROR localResult = 0;

    // Pre-hook
    if (!PreHook_mciSendCommandA(_ReturnAddress(), &localResult, deviceID, command, flags, parameters)) {
        return localResult;
    }

    // Inline assembly to invoke original WinMM hook
    __asm {
        push parameters
        push flags
        push command
        push deviceID
        call fpWinMMHookList[41 * 4]
        mov [localResult], eax
    }

    // Post-hook
    PostHook_mciSendCommandA(_ReturnAddress(), &localResult, deviceID, command, flags, parameters);

    return localResult;
}

