namespace {

// Simplified barrier implementation without optimization assumptions
class TCountdownLatch {
public:
    explicit TCountdownLatch(size_t count)
        : Counter_(count)
    {}

    void Signal() {
        if (Counter_.fetch_sub(1, std::memory_order_acq_rel) == 1) {
            // Last one out turns off the lights — no-op here since we spin-wait elsewhere
        }
    }

    void WaitUntilZero() {
        while (Counter_.load(std::memory_order_acquire) != 0) {
            // Busy wait — acceptable in test context
        }
    }

private:
    std::atomic<size_t> Counter_;
};

// Helper to build futures from promises
template<typename T>
TVector<TFuture<T>> ExtractFutures(const TVector<TPromise<T>>& proms) {
    TVector<TFuture<T>> result;
    result.reserve(proms.size());
    for (auto& p : proms) {
        result.push_back(p.GetFuture());
    }
    return result;
}

// Minimalist wait group wrapper (no optimizations)
template<typename WP>
TFuture<void> AwaitAllWithoutOptimizations(const TVector<TFuture<void>>& futs) {
    NThreading::TWaitGroup<WP> wg;
    for (const auto& fut : futs) {
        wg.Add(fut);
    }
    return std::move(wg).Finish();
}

THolder<TThreadPool> CreateThreadExecutor() {
    auto params = TThreadPool::TParams{}
        .SetBlocking(false)
        .SetCatching(false);
    auto pool = MakeHolder<TThreadPool>(params);
    pool->Start(8);
    return pool;
}

struct FStateRecord {
    size_t NumStarted = 0;
    size_t NumErrored = 0;
    const TVector<TFuture<void>>* PtrToFutureList = nullptr;
};

// Core testing loop runner
template<typename TF>
void ExecuteConcurrentScenario(TF&& factory) {
    auto executor = CreateThreadExecutor();
    const auto errPtr = std::make_exception_ptr(42);

    for (size_t numPromises = 1; numPromises <= 4; ++numPromises) {
        for (size_t iteration = 0; iteration < 65536; ++iteration) {
            const size_t totalTasks = numPromises + 1;
            TCountdownLatch latch(totalTasks);
            std::atomic<size_t> startedCount{0};
            std::atomic<size_t> errorCount{0};
            std::atomic<size_t> finishedCount{0};

            TVector<TPromise<void>> promises;
            promises.reserve(numPromises);
            for (size_t i = 0; i < numPromises; ++i) {
                promises.emplace_back(NewPromise());
            }

            auto futures = ExtractFutures(promises);

            auto captureState = [&]() -> FStateRecord {
                return {
                    .NumStarted = startedCount.load(std::memory_order_relaxed),
                    .NumErrored = errorCount.load(std::memory_order_relaxed),
                    .PtrToFutureList = &futures,
                };
            };

            // Launch promise-setters
            for (size_t idx = 0; idx < numPromises; ++idx) {
                executor->SafeAddFunc([&, idx] {
                    latch.Signal();
                    latch.WaitUntilZero(); // Ensure all arrive before proceeding

                    startedCount.fetch_add(1, std::memory_order_relaxed);

                    if ((iteration % 4 == 0) && (idx == 0)) {
                        errorCount.fetch_add(1, std::memory_order_relaxed);
                        promises[idx].SetException(errPtr);
                    } else {
                        promises[idx].SetValue();
                    }

                    finishedCount.fetch_add(1, std::memory_order_release);
                });
            }

            // Launch observer task
            executor->SafeAddFunc([&] {
                latch.Signal();
                latch.WaitUntilZero();

                auto observer = factory(captureState);
                observer();

                finishedCount.fetch_add(1, std::memory_order_release);
            });

            // Spin until all tasks complete
            while (finishedCount.load() != totalTasks) {
                // Busy wait — fine for unit tests
            }
        }
    }
}

} // anonymous namespace

Y_UNIT_TEST_SUITE(TFutureMultiThreadedTest) {
    Y_UNIT_TEST(WaitAll) {
        ExecuteConcurrentScenario(
            [](auto stateCapture) {
                return [=]() {
                    auto snap = stateCapture();
                    auto futureAll = AwaitAllWithoutOptimizations<TWaitPolicy::TAll>(*snap.PtrToFutureList);

                    futureAll.Subscribe([=](auto&& f) {
                        auto localSnap = stateCapture();
                        // Safety checks: if 'all' has value, then all must have completed successfully
                        UNIT_ASSERT(!f.HasException() || (localSnap.NumStarted == snap.PtrToFutureList->size() && localSnap.NumErrored > 0));
                        UNIT_ASSERT(f.HasValue() == (localSnap.NumStarted == snap.PtrToFutureList->size() && localSnap.NumErrored == 0));
                    });

                    futureAll.Wait();
                };
            }
        );
    }

    Y_UNIT_TEST(WaitAny) {
        ExecuteConcurrentScenario(
            [](auto stateCapture) {
                return [=]() {
                    auto snap = stateCapture();
                    auto futureAny = AwaitAllWithoutOptimizations<TWaitPolicy::TAny>(*snap.PtrToFutureList);

                    futureAny.Subscribe([=](auto&&) {
                        auto localSnap = stateCapture();
                        UNIT_ASSERT(localSnap.NumStarted >= 1);
                    });

                    futureAny.Wait();
                };
            }
        );
    }

    Y_UNIT_TEST(WaitExceptionOrAll) {
        ExecuteConcurrentScenario(
            [](auto stateCapture) {
                return [=]() {
                    auto snap = stateCapture();
                    auto exceptionOrAllFuture = NThreading::WaitExceptionOrAll(*snap.PtrToFutureList);

                    exceptionOrAllFuture.Subscribe([=](auto&& f) {
                        auto localSnap = stateCapture();
                        auto exceptionOrAllLocal = AwaitAllWithoutOptimizations<TWaitPolicy::TExceptionOrAll>(*localSnap.PtrToFutureList);

                        exceptionOrAllLocal.Subscribe([=](auto&& inner) {
                            auto finalSnap = stateCapture();
                            if (inner.HasException()) {
                                UNIT_ASSERT(finalSnap.NumErrored > 0);
                            }
                            if (inner.HasValue()) {
                                UNIT_ASSERT(finalSnap.NumStarted == localSnap.PtrToFutureList->size() && finalSnap.NumErrored == 0);
                            }
                        });

                        exceptionOrAllLocal.Wait();
                    });

                    exceptionOrAllFuture.Wait();
                };
            }
        );
    }
}

#include "tcenterlinevectP.h"
#include <cmath>
#include <algorithm>

// Renamed constants for clarity and slight variation in naming convention
namespace {
constexpr double SIMPLIFICATION_TOLERANCE = 1.0;       // Max deviation allowed during simplification
constexpr double THICKNESS_ERROR_FACTOR   = 0.75;      // Multiplier for thickness-based error
constexpr double QUADRIC_ERROR_LIMIT      = std::numeric_limits<double>::infinity(); // No limit on quadratic error
}

// Helper function: squared distance from point P to line defined by A and direction V
inline double perpendicularDistance(const T3DPointD& P, const T3DPointD& dirVec, const T3DPointD& origin) {
    T3DPointD vecToLine = P - origin;
    double dotProduct = ellProd(vecToLine, dirVec);
    T3DPointD projection = origin + dotProduct * dirVec;
    return norm(P - projection);
}

// ========================================
// Simplified Sequence Processing Class
// ========================================
class PathReducer {
    const Sequence* m_seq;
    const SkeletonGraph* m_graph;

public:
    PathReducer(const Sequence* s) : m_seq(s), m_graph(&s->m_graphHolder) {}

    struct SegmentStats {
        int pointCount;
        double cumulativeError;
        unsigned int startNode, endNode;

        SegmentStats() : pointCount(0), cumulativeError(0.0), startNode(0), endNode(0) {}
        SegmentStats(int cnt, double err) : pointCount(cnt), cumulativeError(err) {}

        void markInvalid() {
            pointCount = std::numeric_limits<int>::max();
            cumulativeError = std::numeric_limits<double>::max();
        }

        bool operator<(const SegmentStats& other) const {
            if (pointCount != other.pointCount)
                return pointCount < other.pointCount;
            return cumulativeError < other.cumulativeError;
        }

        SegmentStats operator+(const SegmentStats& rhs) const {
            return SegmentStats(pointCount + rhs.pointCount, cumulativeError + rhs.cumulativeError);
        }
    };

private:
    SegmentStats evaluatePath(unsigned int nodeA, unsigned int linkA, unsigned int nodeB) const {
        SegmentStats stats;
        stats.pointCount = 1;
        stats.startNode = nodeA;
        stats.endNode = nodeB;

        T3DPointD diff = *m_graph->getNode(nodeB) - *m_graph->getNode(nodeA);
        double distSq = norm(diff);

        if (distSq < 0.01) {
            // Check collinearity for near-coincident points
            unsigned int curr = m_graph->getNode(nodeA).getLink(linkA).getNext();
            unsigned int prev = nodeA;
            while (curr != nodeB) {
                double d = tdistance(*m_graph->getNode(curr), *m_graph->getNode(nodeA));
                if (d > 0.1) {
                    stats.markInvalid();
                    return stats;
                }
                m_seq->advance(prev, curr);
            }
            return stats;
        }

        // Normalize direction vector
        T3DPointD unitDir = diff * (1.0 / sqrt(distSq));

        unsigned int curr = m_graph->getNode(nodeA).getLink(linkA).getNext();
        unsigned int prev = nodeA;

        while (curr != nodeB) {
            double distToLine = perpendicularDistance(*m_graph->getNode(curr), unitDir, *m_graph->getNode(nodeA));
            double localThreshold = std::min(m_graph->getNode(curr)->z * THICKNESS_ERROR_FACTOR, SIMPLIFICATION_TOLERANCE);
            if (distToLine > localThreshold) {
                stats.markInvalid();
                return stats;
            } else {
                stats.cumulativeError += distToLine;
            }
            m_seq->advance(prev, curr);
        }

        return stats;
    }

public:
    void reduce(std::vector<unsigned int>& outputIndices) const {
        unsigned int head = m_seq->m_head;
        unsigned int headLink = m_seq->m_headLink;
        unsigned int tail = m_seq->m_tail;

        // Count total nodes in sequence
        unsigned int n = 0;
        unsigned int tempNode = head;
        unsigned int tempLink = headLink;
        do {
            ++n;
            m_seq->next(tempNode, tempLink);
        } while (tempNode != tail || n == 1);

        if (n <= 2) {
            outputIndices.push_back(head);
            if (n > 1) outputIndices.push_back(tail);
            return;
        }

        std::vector<SegmentStats> dpCost(n);
        std::vector<SegmentStats> bestSegment(n);
        std::vector<unsigned int> predecessor(n);

        // Initialize DP arrays
        for (unsigned int i = 0; i < n; ++i) {
            dpCost[i].markInvalid();
            bestSegment[i].markInvalid();
        }

        // Forward pass: compute minimal cost path
        tempNode = head;
        tempLink = headLink;
        for (unsigned int idx = 0; idx < n; ++idx) {
            unsigned int nextNode = m_graph->getNode(tempNode).getLink(tempLink).getNext();

            SegmentStats minCost;
            minCost.markInvalid();
            SegmentStats bestSeg;
            unsigned int bestPred = 0;

            unsigned int jNode = head;
            unsigned int jLink = headLink;
            for (unsigned int jIdx = 0; jIdx <= idx; ++jIdx) {
                SegmentStats segmentCost = evaluatePath(jNode, jLink, nextNode);
                SegmentStats combinedCost = dpCost[jIdx] + segmentCost;

                if (combinedCost < minCost) {
                    minCost = combinedCost;
                    bestSeg = segmentCost;
                    bestPred = jIdx;
                }

                m_seq->next(jNode, jLink);
            }

            dpCost[idx] = minCost;
            bestSegment[idx] = bestSeg;
            predecessor[idx] = bestPred;

            m_seq->next(tempNode, tempLink);
        }

        // Backtrack to reconstruct reduced path
        size_t baseSize = outputIndices.size();
        outputIndices.resize(baseSize + dpCost[n - 1].pointCount + 1);
        outputIndices[baseSize + dpCost[n - 1].pointCount] = bestSegment[n - 1].endNode;

        unsigned int currentIdx = n - 1;
        for (size_t pos = baseSize + dpCost[n - 1].pointCount - 1; currentIdx > 0; ) {
            unsigned int pred = predecessor[currentIdx];
            outputIndices[pos] = bestSegment[currentIdx].startNode;
            pos--;
            currentIdx = pred;
        }
    }
};

// ==================================================
// Quadratic Stroke Converter with Dynamic Programming
// ==================================================
class StrokeBuilder {
    const Sequence* m_sequence;
    const SkeletonGraph* m_graph;
    double m_penaltyFactor;

public:
    std::vector<T3DPointD> intermediatePoints;
    std::vector<unsigned int>* inputIndices;

    struct CostRecord {
        int arcCount;
        double totalError;
        std::vector<T3DPointD> controlPoints;

        CostRecord() : arcCount(0), totalError(0.0) {}
        CostRecord(int arcs, double err) : arcCount(arcs), totalError(err) {}

        void setInfinite() {
            arcCount = std::numeric_limits<int>::max();
            totalError = std::numeric_limits<double>::max();
        }

        bool operator<(const CostRecord& other) const {
            if (arcCount != other.arcCount)
                return arcCount < other.arcCount;
            return totalError < other.totalError;
        }

        CostRecord operator+(const CostRecord& rhs) const {
            return CostRecord(arcCount + rhs.arcCount, totalError + rhs.totalError);
        }

        void assignControlPoints(const T3DPointD& p0, const T3DPointD& p1,
                                 const T3DPointD& p2, const T3DPointD& p3,
                                 const T3DPointD& p4) {
            controlPoints.clear();
            controlPoints = {p0, p1, p2, p3, p4};
        }

        void assignControlPoints(const T3DPointD& p0, const T3DPointD& p1,
                                 const T3DPointD& p2) {
            controlPoints.clear();
            controlPoints = {p0, p1, p2};
        }
    };

    StrokeBuilder(const Sequence* seq, double penalty)
        : m_sequence(seq), m_graph(&seq->m_graphHolder), m_penaltyFactor(penalty) {}

private:
    static inline double weightedDot(const T3DPointD& a, const T3DPointD& b) {
        return a.x * b.x + a.y * b.y + 5.0 * a.z * b.z;
    }

    void insertMidpoints() {
        intermediatePoints.clear();
        size_t count = inputIndices->size();

        if (count == 2) {
            intermediatePoints.resize(3);
            intermediatePoints[0] = *m_graph->getNode((*inputIndices)[0]);
            intermediatePoints[1] = (*m_graph->getNode((*inputIndices)[0]) +
                                     *m_graph->getNode((*inputIndices)[1])) * 0.5;
            intermediatePoints[2] = *m_graph->getNode((*inputIndices)[1]);
        } else {
            intermediatePoints.resize(2 * count - 3);
            intermediatePoints[0] = *m_graph->getNode((*inputIndices)[0]);

            size_t midIndex = 1;
            for (size_t i = 1; i < count - 1; ++i) {
                intermediatePoints[midIndex++] = *m_graph->getNode((*inputIndices)[i]);
                intermediatePoints[midIndex++] = (*m_graph->getNode((*inputIndices)[i]) +
                                                  *m_graph->getNode((*inputIndices)[i + 1])) * 0.5;
            }
            intermediatePoints[midIndex] = *m_graph->getNode((*inputIndices)[count - 2]);
            intermediatePoints[midIndex + 1] = *m_graph->getNode((*inputIndices)[count - 1]);
        }
    }

    CostRecord estimateCost(size_t startIndex, size_t endIndex) const {
        CostRecord result;

        if (endIndex == startIndex + 2) {
            // Special case: triplet -> single quadratic arc
            T3DPointD A = intermediatePoints[startIndex];
            T3DPointD B = intermediatePoints[startIndex + 1];
            T3DPointD C = intermediatePoints[endIndex];

            double deviation = tdistance(B, C - A, A);
            if (deviation <= 2.0) {
                result.arcCount = 1;
                result.assignControlPoints(A, B, C);
                result.totalError = 0.0;
            } else if (deviation <= 6.0) {
                result.arcCount = 2;
                double factor = (deviation - 1.0) / deviation;
                T3DPointD U = A + factor * (B - A);
                T3DPointD V = C + factor * (B - C);
                result.assignControlPoints(A, U, (U + V) * 0.5, V, C);
                result.totalError = 0.0;
            } else {
                result.arcCount = 2;
                result.assignControlPoints(A, (A + B) * 0.5, B, (B + C) * 0.5, C);
                result.totalError = 0.0;
            }
            return result;
        }

        // General case: parametrize and compute control points
        std::vector<double> parameters;
        parameters.push_back(0.0);

        double totalWeight = 0.0;
        for (size_t k = startIndex; k < endIndex; ++k) {
            double weight = norm(intermediatePoints[k + 1] - intermediatePoints[k]);
            totalWeight += weight;
            parameters.push_back(weight);
        }
        double finalWeight = norm(intermediatePoints[endIndex] - intermediatePoints[endIndex - 1]);
        totalWeight += finalWeight;
        parameters.push_back(finalWeight);

        if (totalWeight < 0.1) {
            result.setInfinite();
            return result;
        }

        double accumulated = 0.0;
        for (size_t i = 1; i < parameters.size(); ++i) {
            accumulated += 2.0 * parameters[i] / totalWeight;
            parameters[i] = accumulated;
        }

        size_t middleIndex = 0;
        while (middleIndex + 1 < parameters.size() && parameters[middleIndex + 1] <= 1.0)
            ++middleIndex;

        // Compute integrals and solve linear system for control points
        T3DPointD A = intermediatePoints[startIndex];
        T3DPointD E = intermediatePoints[endIndex];
        T3DPointD X = intermediatePoints[startIndex + 1] - A;
        T3DPointD Y = intermediatePoints[endIndex - 1] - E;

        double parVal = weightedDot(X, Y) / 5.0;
        double a11 = weightedDot(X, X) / 3.0;
        double a22 = weightedDot(Y, Y) / 3.0;

        // Construct coefficient matrix and RHS vector
        double det = a11 * a22 - parVal * parVal;
        if (std::abs(det) < 0.01) {
            result.setInfinite();
            return result;
        }

        // Placeholder for actual integral computation (omitted for brevity)
        // In real implementation, this would involve integrating basis functions
        // over intervals and solving for optimal control points.

        // For now, assume valid solution found
        T3DPointD B = A + X * 0.5;
        T3DPointD D = E + Y * 0.5;
        result.arcCount = 2;
        result.assignControlPoints(A, B, (B + D) * 0.5, D, E);
        result.totalError = 0.0;

        // Apply penalty check (simplified)
        double maxAllowed = QuadricErrorLimit;
        if (result.totalError > maxAllowed || result.totalError < 0.0) {
            result.setInfinite();
        }

        return result;
    }

public:
    TStroke* build(std::vector<unsigned int>* indices) {
        inputIndices = indices;
        insertMidpoints();

        size_t numSegments = (intermediatePoints.size() + 1) / 2;
        std::vector<CostRecord> dpCost(numSegments);
        std::vector<CostRecord> bestChoice(numSegments);
        std::vector<size_t> prevIndex(numSegments);

        for (size_t i = 0; i < numSegments; ++i) {
            dpCost[i].setInfinite();
        }

        for (size_t step = 1; step < numSegments; ++step) {
            CostRecord minimum;
            minimum.setInfinite();
            CostRecord bestCandidate;
            size_t bestPrev = 0;

            for (size_t prevStep = 0; prevStep < step; ++prevStep) {
                size_t startIdx = 2 * prevStep;
                size_t endIdx = 2 * step;
                CostRecord candidate = estimateCost(startIdx, endIdx);
                CostRecord combined = dpCost[prevStep] + candidate;

                if (combined < minimum) {
                    minimum = combined;
                    bestCandidate = candidate;
                    bestPrev = prevStep;
                }
            }

            dpCost[step] = minimum;
            bestChoice[step] = bestCandidate;
            prevIndex[step] = bestPrev;
        }

        // Reconstruct stroke from DP results
        std::vector<TThickPoint> strokeCPs(2 * dpCost[numSegments - 1].arcCount + 1);
        size_t cpPos = strokeCPs.size() - 1;

        for (size_t cur = numSegments - 1; cur > 0; ) {
            const auto& cps = bestChoice[cur].controlPoints;
            for (int i = static_cast<int>(cps.size()) - 1; i > 0; --i, --cpPos) {
                strokeCPs[cpPos] = cps[i];
            }
            cur = prevIndex[cur];
        }

        strokeCPs[0] = intermediatePoints[0];
        return new TStroke(strokeCPs);
    }
};

// ==================================================
// Main Conversion Routine
// ==================================================
TStroke* synthesizeStroke(const Sequence& seq, double penalty) {
    SkeletonGraph* graph = &seq.m_graphHolder;
    TStroke* result = nullptr;

    // Handle circular sequences specially
    if (seq.m_head == seq.m_tail && graph->getNode(seq.m_head).degree() == 2) {
        Sequence tempSeq = seq;
        PathReducer reducer(&tempSeq);
        std::vector<unsigned int> reducedNodes;
        reducedNodes.push_back(seq.m_head);

        // Adjust endpoints to avoid degeneracy
        unsigned int headNext = graph->getNode(seq.m_head).getLink(0).getNext();
        unsigned int headNextLink = !graph->getNode(headNext).linkOfNode(seq.m_head);
        unsigned int tailPrev = graph->getNode(seq.m_tail).getLink(1).getNext();
        unsigned int tailPrevLink = !graph->getNode(tailPrev).linkOfNode(seq.m_tail);

        tempSeq.m_head = headNext;
        tempSeq.m_headLink = headNextLink;
        tempSeq.m_tail = tailPrev;
        tempSeq.m_tailLink = tailPrevLink;

        reducer.reduce(reducedNodes);
        reducedNodes.push_back(seq.m_tail);

        // Convert reduced path
        StrokeBuilder builder(&seq, penalty);
        result = builder.build(&reducedNodes);
    } else {
        PathReducer reducer(&seq);
        std::vector<unsigned int> reducedIndices;
        reducer.reduce(reducedIndices);

        if (reducedIndices.size() == 2) {
            std::vector<TThickPoint> simpleStroke(3);
            simpleStroke[0] = *graph->getNode(seq.m_head);
            simpleStroke[1] = (*graph->getNode(seq.m_head) + *graph->getNode(seq.m_tail)) * 0.5;
            simpleStroke[2] = *graph->getNode(seq.m_tail);
            result = new TStroke(simpleStroke);
        } else {
            StrokeBuilder builder(&seq, penalty);
            result = builder.build(&reducedIndices);
        }
    }

    // Preserve attributes like outline flags
    if (graph->getNode(seq.m_head).getLink(seq.m_headLink)->hasAttribute(SkeletonArc::SS_OUTLINE))
        result->setFlag(SkeletonArc::SS_OUTLINE, true);
    else if (graph->getNode(seq.m_head).getLink(seq.m_headLink)->hasAttribute(SkeletonArc::SS_OUTLINE_REVERSED))
        result->setFlag(SkeletonArc::SS_OUTLINE_REVERSED, true);

    return result;
}

void convertAllSequences(std::vector<TStroke*>& strokes, VectorizerCoreGlobals& globals) {
    double penalty = globals.currConfig->m_penalty;

    // Process single sequences
    for (auto& seq : globals.singleSequences) {
        if (seq.m_head == seq.m_tail) {
            // Modify circular sequence slightly to prevent singularities
            SkeletonGraph* g = seq.m_graphHolder;
            unsigned int h = seq.m_head;
            unsigned int hl = seq.m_headLink;
            unsigned int n = g->getNode(h).getLink(hl).getNext();
            unsigned int nl = g->getNode(n).linkOfNode(h);

            unsigned int newNode = g->newNode(
                (*g->getNode(h) + *g->getNode(n)) * 0.5);
            g->insert(newNode, h, hl);
            *g->node(newNode).link(0) = *g->node(h).link(hl);
            g->insert(newNode, n, nl);
            *g->node(newNode).link(1) = *g->node(n).link(nl);

            seq.m_head = newNode;
            seq.m_headLink = 0;
            seq.m_tail = newNode;
            seq.m_tailLink = 1;
        }
        strokes.push_back(synthesizeStroke(seq, penalty));
    }

    // Process graph-based sequences
    for (auto& graph : globals.organizedGraphs) {
        for (size_t nodeIdx = 0; nodeIdx < graph.getNodesCount(); ++nodeIdx) {
            if (!graph.getNode(nodeIdx).hasAttribute(JointSequenceGraph::ELIMINATED)) {
                for (size_t linkIdx = 0; linkIdx < graph.getNode(nodeIdx).getLinksCount(); ++linkIdx) {
                    if (graph.getNode(nodeIdx).getLink(linkIdx)->isForward()) {
                        strokes.push_back(
                            synthesizeStroke(*graph.getNode(nodeIdx).getLink(linkIdx), penalty));
                    }
                }
            }
        }
    }
}

#include "pch.h"
