HWND WindowFinder::FindGameWindow() noexcept
{
    const DWORD processId = GetCurrentProcessId();
    const HWND consoleWindow = GetConsoleWindow();
    EnumData searchParams{ processId, consoleWindow, nullptr };
    EnumWindows(EnumerateWindows, reinterpret_cast<LPARAM>(&searchParams));
    return searchParams.bestHandle;
}

BOOL CALLBACK WindowFinder::EnumerateWindows(const HWND hwnd, const LPARAM lParam) noexcept
{
    const auto params = reinterpret_cast<EnumData*>(lParam);

    // Skip console window and other known non-game windows
    if (hwnd == params->consoleHwnd || IsConsoleApplicationWindow(hwnd)) 
        return TRUE;

    // Verify the window belongs to our process
    DWORD foundProcessId = 0;
    GetWindowThreadProcessId(hwnd, &foundProcessId);
    if (foundProcessId != params->processId) 
        return TRUE;

    // Check if this is a candidate main window
    if (!IsCandidateMainWindow(hwnd, params->consoleHwnd)) 
        return TRUE;

    // Update best match
    params->bestHandle = hwnd;
    return FALSE; // Stop enumeration after finding first valid match
}

bool WindowFinder::IsCandidateMainWindow(const HWND hwnd, const HWND consoleWindow) noexcept
{
    // Exclude console window explicitly
    if (hwnd == consoleWindow) 
        return false;

    // Must be visible
    if (!IsWindowVisible(hwnd)) 
        return false;

    // Must not be a child window
    if (GetParent(hwnd) != nullptr) 
        return false;

    // Minimum size check
    RECT bounds;
    GetWindowRect(hwnd, &bounds);
    constexpr int MIN_DIMENSION = 100;
    const int width = bounds.right - bounds.left;
    const int height = bounds.bottom - bounds.top;
    if (width < MIN_DIMENSION || height < MIN_DIMENSION) 
        return false;

    return true;
}

bool WindowFinder::IsConsoleApplicationWindow(const HWND hwnd) noexcept
{
    wchar_t buffer[256] = {0};
    if (GetClassNameW(hwnd, buffer, 256) == 0) 
        return false;

    return wcscmp(buffer, L"ConsoleWindowClass") == 0;
}

#include <bits/stdc++.h>
using namespace std;
using ll = long long;
using pii = pair<int, int>;
using piii = pair<int, pii>;

inline int readInt() {
    int val = 0, sign = 1;
    char c = getchar();
    while (!isdigit(c)) {
        if (c == '-') sign = -1;
        c = getchar();
    }
    while (isdigit(c)) {
        val = val * 10 + (c - '0');
        c = getchar();
    }
    return val * sign;
}

inline void printNum(int x) {
    if (x < 0) {
        putchar('-');
        printNum(-x);
        return;
    }
    if (x >= 10) printNum(x / 10);
    putchar('0' + (x % 10));
}

const int MAX_SIZE = 25;
char gridA[MAX_SIZE][MAX_SIZE];
char gridB[MAX_SIZE][MAX_SIZE];
char pattern[MAX_SIZE][MAX_SIZE][MAX_SIZE];
int patternRows[MAX_SIZE], patternCols[MAX_SIZE];
int patternCharCount[MAX_SIZE][256];
int globalCharFreq[256];
int visited[MAX_SIZE][MAX_SIZE];
vector<piii> operations;

char fetchChar() {
    char c = getchar();
    while (!((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || isdigit(c))) {
        c = getchar();
    }
    return c;
}

void moveCharacter(int &curRow, int &curCol, int targetRow, int targetCol, int direction) {
    switch (direction) {
        case -3: // Down
            operations.push_back({-3, {curRow, curCol}});
            swap(gridB[curRow][curCol], gridB[curRow + 1][curCol]);
            curRow++;
            break;
        case -1: // Right
            operations.push_back({-1, {curRow, curCol}});
            swap(gridB[curRow][curCol], gridB[curRow][curCol + 1]);
            curCol++;
            break;
        case -2: // Left
            operations.push_back({-2, {curRow, curCol}});
            swap(gridB[curRow][curCol], gridB[curRow][curCol - 1]);
            curCol--;
            break;
        case -4: // Up
            operations.push_back({-4, {curRow, curCol}});
            swap(gridB[curRow][curCol], gridB[curRow - 1][curCol]);
            curRow--;
            break;
    }
}

bool canApplyPattern(int idx, int totalSpaces) {
    int needed = 0;
    bool hasRelevantChar = false;
    for (int ch = 0; ch < 256; ++ch) {
        if (patternCharCount[idx][ch] > globalCharFreq[ch]) {
            needed += patternCharCount[idx][ch] - globalCharFreq[ch];
        }
        if (patternCharCount[idx][ch] > 0 && globalCharFreq[ch] > 0) {
            hasRelevantChar = true;
        }
    }
    return (needed <= totalSpaces) && hasRelevantChar;
}

int main() {
    int rows = readInt(), cols = readInt(), patternsCount = readInt();

    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= cols; ++j) {
            gridA[i][j] = fetchChar();
        }
    }

    for (int i = 1; i <= rows; ++i) {
        for (int j = 1; j <= cols; ++j) {
            gridB[i][j] = fetchChar();
            globalCharFreq[gridB[i][j]]++;
        }
    }

    for (int p = 1; p <= patternsCount; ++p) {
        patternRows[p] = readInt();
        patternCols[p] = readInt();
        for (int i = 1; i <= patternRows[p]; ++i) {
            for (int j = 1; j <= patternCols[p]; ++j) {
                pattern[p][i][j] = fetchChar();
                patternCharCount[p][pattern[p][i][j]]++;
            }
        }
    }

    while (true) {
        int selectedPattern = 0;
        int spaceCount = globalCharFreq[' '];

        for (int p = 1; p <= patternsCount; ++p) {
            if (canApplyPattern(p, spaceCount)) {
                selectedPattern = p;
                break;
            }
        }

        if (!selectedPattern) break;

        memset(visited, 0, sizeof(visited));

        int pr = patternRows[selectedPattern];
        int pc = patternCols[selectedPattern];

        for (int i = 1; i <= pr; ++i) {
            for (int j = 1; j <= pc; ++j) {
                int srcRow = 0, srcCol = 0;

                // Find first occurrence of required character
                for (int r = 1; r <= rows; ++r) {
                    for (int c = 1; c <= cols; ++c) {
                        if (visited[r][c]) continue;
                        if (gridB[r][c] == pattern[selectedPattern][i][j]) {
                            srcRow = r;
                            srcCol = c;
                            goto foundTarget;
                        }
                    }
                }

                // If not found, use space as placeholder
                for (int r = 1; r <= rows; ++r) {
                    for (int c = 1; c <= cols; ++c) {
                        if (visited[r][c]) continue;
                        if (gridB[r][c] == ' ') {
                            srcRow = r;
                            srcCol = c;
                            goto foundTarget;
                        }
                    }
                }

                foundTarget:
                if (!srcRow) continue;

                // Move character to position (i,j)
                while (srcRow < i) moveCharacter(srcRow, srcCol, i, j, -3);
                while (srcCol < j) moveCharacter(srcRow, srcCol, i, j, -1);
                while (srcCol > j) moveCharacter(srcRow, srcCol, i, j, -2);
                while (srcRow > i) moveCharacter(srcRow, srcCol, i, j, -4);

                visited[i][j] = true;
                globalCharFreq[gridB[i][j]]--;
                gridB[i][j] = ' ';
                globalCharFreq[' ']++;
            }
        }

        operations.push_back({selectedPattern, {1, 1}});

        while (true) {
            int srcRow = 0, srcCol = 0;
            for (int r = 1; r <= rows; ++r) {
                for (int c = 1; c <= cols; ++c) {
                    if (visited[r][c]) continue;
                    if (patternCharCount[selectedPattern][gridB[r][c]] > 0) {
                        srcRow = r;
                        srcCol = c;
                        goto findNextMatch;
                    }
                }
            }
            break;

            findNextMatch:
            if (!srcRow) break;

            bool matched = false;
            for (int i = 1; i <= pr && !matched; ++i) {
                for (int j = 1; j <= pc && !matched; ++j) {
                    if (pattern[selectedPattern][i][j] == gridB[srcRow][srcCol]) {
                        matched = true;

                        // Re-position to (i,j)
                        while (srcRow < i) moveCharacter(srcRow, srcCol, i, j, -3);
                        while (srcCol < j) moveCharacter(srcRow, srcCol, i, j, -1);
                        while (srcCol > j) moveCharacter(srcRow, srcCol, i, j, -2);
                        while (srcRow > i) moveCharacter(srcRow, srcCol, i, j, -4);

                        globalCharFreq[gridB[i][j]]--;
                        gridB[i][j] = ' ';
                        globalCharFreq[' ']++;
                        operations.push_back({selectedPattern, {1, 1}});
                    }
                }
            }
            if (!matched) break;
        }
    }

    // Final alignment to match gridA exactly
    memset(visited, 0, sizeof(visited));
    bool success = true;

    for (int i = 1; i <= rows && success; ++i) {
        for (int j = 1; j <= cols && success; ++j) {
            int srcRow = 0, srcCol = 0;

            // Try to find exact match first
            for (int r = 1; r <= rows; ++r) {
                for (int c = 1; c <= cols; ++c) {
                    if (visited[r][c]) continue;
                    if (gridB[r][c] == gridA[i][j]) {
                        srcRow = r;
                        srcCol = c;
                        goto locateSource;
                    }
                }
            }

            // Fallback to empty cell
            for (int r = 1; r <= rows; ++r) {
                for (int c = 1; c <= cols; ++c) {
                    if (visited[r][c]) continue;
                    if (gridB[r][c] == ' ') {
                        srcRow = r;
                        srcCol = c;
                        goto locateSource;
                    }
                }
            }

            locateSource:
            if (!srcRow) {
                success = false;
                break;
            }

            // Move to destination
            while (srcRow < i) moveCharacter(srcRow, srcCol, i, j, -3);
            while (srcCol < j) moveCharacter(srcRow, srcCol, i, j, -1);
            while (srcCol > j) moveCharacter(srcRow, srcCol, i, j, -2);
            while (srcRow > i) moveCharacter(srcRow, srcCol, i, j, -4);

            visited[i][j] = true;
        }
    }

    if (!success) {
        puts("-1");
        return 0;
    }

    reverse(operations.begin(), operations.end());
    printNum((int)operations.size());
    putchar('\n');

    for (auto op : operations) {
        printNum(op.first);
        putchar(' ');
        printNum(op.second.first);
        putchar(' ');
        printNum(op.second.second);
        putchar('\n');
    }

    return 0;
}

