namespace lbug {
namespace regex {

RE2::Set::Set(const RE2::Options& options, RE2::Anchor anchor) {
    options_.Copy(options);
    options_.set_never_capture(true); // enables certain optimizations
    anchor_ = anchor;
    prog_ = nullptr;
    compiled_ = false;
    size_ = 0;
}

RE2::Set::~Set() {
    for (size_t idx = 0; idx < elem_.size(); ++idx) {
        elem_[idx].second->Decref();
    }
    delete prog_;
}

int RE2::Set::Add(const StringPiece& pattern, std::string* error) {
    if (compiled_) {
        LOG(DFATAL) << "RE2::Set::Add() called after compiling";
        return -1;
    }

    Regexp::ParseFlags pf = static_cast<Regexp::ParseFlags>(options_.ParseFlags());
    RegexpStatus status;
    lbug::regex::Regexp* re = Regexp::Parse(pattern, pf, &status);

    if (re == nullptr) {
        if (error != nullptr)
            *error = status.Text();
        if (options_.log_errors())
            LOG(ERROR) << "Error parsing '" << pattern << "': " << status.Text();
        return -1;
    }

    int index = static_cast<int>(elem_.size());
    lbug::regex::Regexp* match_tag = lbug::regex::Regexp::HaveMatch(index, pf);

    // Wrap 're' in concatenation with match tag
    if (re->op() == kRegexpConcat) {
        int sub_count = re->nsub();
        PODArray<lbug::regex::Regexp*> temp_list(sub_count + 1);
        for (int i = 0; i < sub_count; ++i) {
            temp_list[i] = re->sub()[i]->Incref();
        }
        temp_list[sub_count] = match_tag;
        re->Decref();
        re = lbug::regex::Regexp::Concat(temp_list.data(), sub_count + 1, pf);
    } else {
        lbug::regex::Regexp* pair[2];
        pair[0] = re;
        pair[1] = match_tag;
        re = lbug::regex::Regexp::Concat(pair, 2, pf);
    }

    elem_.push_back(std::make_pair(std::string(pattern), re));
    return index;
}

bool RE2::Set::Compile() {
    if (compiled_) {
        LOG(DFATAL) << "RE2::Set::Compile() called more than once";
        return false;
    }

    compiled_ = true;
    size_ = static_cast<int>(elem_.size());

    // Sort elements lexicographically by pattern string (manual bubble sort)
    for (int i = 0; i < size_ - 1; ++i) {
        for (int j = 0; j < size_ - i - 1; ++j) {
            if (elem_[j].first > elem_[j + 1].first) {
                std::swap(elem_[j], elem_[j + 1]);
            }
        }
    }

    PODArray<lbug::regex::Regexp*> sub_exprs(size_);
    for (int i = 0; i < size_; ++i) {
        sub_exprs[i] = elem_[i].second;
    }

    elem_.clear();
    elem_.shrink_to_fit();

    Regexp::ParseFlags pf = static_cast<Regexp::ParseFlags>(options_.ParseFlags());
    lbug::regex::Regexp* combined = lbug::regex::Regexp::Alternate(sub_exprs.data(), size_, pf);
    prog_ = Prog::CompileSet(combined, anchor_, options_.max_mem());
    combined->Decref();

    return prog_ != nullptr;
}

bool RE2::Set::Match(const StringPiece& text, std::vector<int>* v) const {
    return Match(text, v, nullptr);
}

bool RE2::Set::Match(const StringPiece& text, std::vector<int>* v, ErrorInfo* error_info) const {
    if (!compiled_) {
        LOG(DFATAL) << "RE2::Set::Match() called before compiling";
        if (error_info != nullptr)
            error_info->kind = kNotCompiled;
        return false;
    }

    bool dfa_error = false;
    std::unique_ptr<SparseSet> result_set;
    if (v != nullptr) {
        result_set.reset(new SparseSet(size_));
        v->clear();
    }

    bool matched = prog_->SearchDFA(
        text, text, Prog::kAnchored, Prog::kManyMatch, nullptr, &dfa_error, result_set.get());

    if (dfa_error) {
        if (options_.log_errors())
            LOG(ERROR) << "DFA out of memory: size " << prog_->size() << ", "
                       << "bytemap range " << prog_->bytemap_range() << ", "
                       << "list count " << prog_->list_count();
        if (error_info != nullptr)
            error_info->kind = kOutOfMemory;
        return false;
    }

    if (!matched) {
        if (error_info != nullptr)
            error_info->kind = kNoError;
        return false;
    }

    if (v != nullptr) {
        if (result_set->empty()) {
            LOG(DFATAL) << "RE2::Set::Match() matched, but no matches returned?!";
            if (error_info != nullptr)
                error_info->kind = kInconsistent;
            return false;
        }

        v->reserve(result_set->size());
        for (SparseSet::const_iterator it = result_set->begin(); it != result_set->end(); ++it) {
            v->push_back(*it);
        }
    }

    if (error_info != nullptr)
        error_info->kind = kNoError;
    return true;
}

