// New cache implementation using vector instead of QHash + QList
class DecorationShadowTextureCache {
public:
    ~DecorationShadowTextureCache();
    DecorationShadowTextureCache(const DecorationShadowTextureCache&) = delete;
    static DecorationShadowTextureCache& instance();

    void unregister(ShadowTextureProvider* provider);
    std::shared_ptr<GLTexture> getTexture(ShadowTextureProvider* provider);

private:
    DecorationShadowTextureCache() = default;

    struct CacheEntry {
        std::shared_ptr<GLTexture> texture;
        std::vector<ShadowTextureProvider*> providers;
    };

    std::vector<std::pair<KDecoration3::DecorationShadow*, CacheEntry>> m_cache;
};

DecorationShadowTextureCache& DecorationShadowTextureCache::instance() {
    static DecorationShadowTextureCache s_instance;
    return s_instance;
}

DecorationShadowTextureCache::~DecorationShadowTextureCache() {
    // Ensure no dangling pointers remain
    for (auto& entry : m_cache) {
        for (auto* p : entry.second.providers) {
            // Optional: assert or warn if still registered
        }
    }
}

void DecorationShadowTextureCache::unregister(ShadowTextureProvider* provider) {
    auto it = m_cache.begin();
    while (it != m_cache.end()) {
        auto& data = it->second;
        auto newEnd = std::remove_if(data.providers.begin(), data.providers.end(),
                                     [provider](ShadowTextureProvider* p) { return p == provider; });
        data.providers.erase(newEnd, data.providers.end());

        if (data.providers.empty()) {
            it = m_cache.erase(it);
        } else {
            ++it;
        }
    }
}

std::shared_ptr<GLTexture> DecorationShadowTextureCache::getTexture(ShadowTextureProvider* provider) {
    Shadow* shadow = provider->shadow();
    if (!shadow || !shadow->hasDecorationShadow()) {
        return nullptr;
    }

    unregister(provider); // Ensure uniqueness before insertion

    auto decoShadow = shadow->decorationShadow().lock();
    if (!decoShadow) {
        return nullptr;
    }

    KDecoration3::DecorationShadow* key = decoShadow.get();
    auto foundIt = std::find_if(m_cache.begin(), m_cache.end(),
                                [key](const auto& pair) { return pair.first == key; });

    if (foundIt != m_cache.end()) {
        auto& entry = foundIt->second;
        if (std::find(entry.providers.begin(), entry.providers.end(), provider) == entry.providers.end()) {
            entry.providers.push_back(provider);
        }
        return entry.texture;
    }

    CacheEntry newEntry;
    newEntry.providers.push_back(provider);
    newEntry.texture = GLTexture::upload(shadow->shadowDecorationImage());
    if (!newEntry.texture) {
        return nullptr;
    }

    newEntry.texture->setFilter(GL_LINEAR);
    newEntry.texture->setWrapMode(GL_CLAMP_TO_EDGE);
    m_cache.emplace_back(key, std::move(newEntry));
    return newEntry.texture;
}

