};

// OpenGL-specific shadow texture provider
class OpenGLShadowTextureProvider : public ShadowTextureProvider {
public:
    explicit OpenGLShadowTextureProvider(Shadow* shadow)
        : ShadowTextureProvider(shadow), m_texture() {}

    ~OpenGLShadowTextureProvider() override {
        if (m_texture) {
            auto* compositor = Compositor::Self::self();
            if (compositor && compositor->scene()) {
                compositor->scene()->makeOpenGLContextCurrent();
            }
            DecorationShadowTextureCache::instance().unregister(this);
            m_texture.reset();
        }
    }

    void update() {
        Shadow* shadow = this->shadow();
        if (!shadow) return;

        if (shadow->hasDecorationShadow()) {
            m_texture = DecorationShadowTextureCache::instance().getTexture(this);
            return;
        }

        // Compute total dimensions
        auto getDim = [](const ShadowElement& el) { return el.size(); };

        const auto top = getDim(shadow->shadowElement(ShadowElements::Top));
        const auto topRight = getDim(shadow->shadowElement(ShadowElements::TopRight));
        const auto right = getDim(shadow->shadowElement(ShadowElements::Right));
        const auto bottom = getDim(shadow->shadowElement(ShadowElements::Bottom));
        const auto bottomLeft = getDim(shadow->shadowElement(ShadowElements::BottomLeft));
        const auto left = getDim(shadow->shadowElement(ShadowElements::Left));
        const auto topLeft = getDim(shadow->shadowElement(ShadowElements::TopLeft));
        const auto bottomRight = getDim(shadow->shadowElement(ShadowElements::BottomRight));

        const int width = std::max({topLeft.width(), left.width(), bottomLeft.width()})
                        + std::max(top.width(), bottom.width())
                        + std::max({topRight.width(), right.width(), bottomRight.width()});
        const int height = std::max({topLeft.height(), top.height(), topRight.height()})
                         + std::max(left.height(), right.height())
                         + std::max({bottomLeft.height(), bottom.height(), bottomRight.height()});

        if (width <= 0 || height <= 0) {
            return;
        }

        QImage image(width, height, QImage::Format_ARGB32);
        image.fill(Qt::transparent);

        const int innerRectTop = std::max({topLeft.height(), top.height(), topRight.height()});
        const int innerRectLeft = std::max({topLeft.width(), left.width(), bottomLeft.width()});

        QPainter painter(&image);
        painter.drawImage(QRectF(0, 0, topLeft.width(), topLeft.height()), shadow->shadowElement(ShadowElements::TopLeft));
        painter.drawImage(QRectF(innerRectLeft, 0, top.width(), top.height()), shadow->shadowElement(ShadowElements::Top));
        painter.drawImage(QRectF(width - topRight.width(), 0, topRight.width(), topRight.height()), shadow->shadowElement(ShadowElements::TopRight));
        painter.drawImage(QRectF(0, innerRectTop, left.width(), left.height()), shadow->shadowElement(ShadowElements::Left));
        painter.drawImage(QRectF(width - right.width(), innerRectTop, right.width(), right.height()), shadow->shadowElement(ShadowElements::Right));
        painter.drawImage(QRectF(0, height - bottomLeft.height(), bottomLeft.width(), bottomLeft.height()), shadow->shadowElement(ShadowElements::BottomLeft));
        painter.drawImage(QRectF(innerRectLeft, height - bottom.height(), bottom.width(), bottom.height()), shadow->shadowElement(ShadowElements::Bottom));
        painter.drawImage(QRectF(width - bottomRight.width(), height - bottomRight.height(), bottomRight.width(), bottomRight.height()), shadow->shadowElement(ShadowElements::BottomRight));
        painter.end();

        // Convert to alpha-only if possible
        const auto context = OpenGlContext::currentContext();
        if (context && !context->isOpenGLES() && context->supportsTextureSwizzle() && context->supportsRGTextures()) {
            QImage alphaImage(image.size(), QImage::Format_Alpha8);
            bool alphaOnly = true;

            for (int y = 0; y < image.height(); ++y) {
                const uint32_t* src = reinterpret_cast<const uint32_t*>(image.scanLine(y));
                uint8_t* dst = reinterpret_cast<uint8_t*>(alphaImage.scanLine(y));
                for (int x = 0; x < image.width(); ++x) {
                    if (src[x] & 0x00ffffff) {
                        alphaOnly = false;
                    }
                    dst[x] = qAlpha(src[x]);
                }
            }

            if (alphaOnly) {
                image = std::move(alphaImage);
            }
        }

        m_texture = GLTexture::upload(image);
        if (!m_texture) {
            return;
        }

        m_texture->setFilter(GL_LINEAR);
        m_texture->setWrapMode(GL_CLAMP_TO_EDGE);

        if (m_texture->internalFormat() == GL_R8) {
            m_texture->bind();
            m_texture->setSwizzle(GL_ZERO, GL_ZERO, GL_ZERO, GL_RED);
        }
    }

private:
    std::shared_ptr<GLTexture> m_texture;
};

// Renderer implementation
class SceneOpenGLDecorationRenderer : public DecorationRenderer {
public:
    explicit SceneOpenGLDecorationRenderer(Decoration::DecoratedWindowImpl* client)
        : DecorationRenderer(client), m_texture() {}

    ~SceneOpenGLDecorationRenderer() override {
        if (WorkspaceScene* scene = Compositor::Self::self()->scene()) {
            scene->makeOpenGLContextCurrent();
        }
    }

    void render(const QRegion& region) override {
        if (areImageSizesDirty()) {
            resizeTexture();
            resetImageSizesDirty();
        }

        if (!m_texture) {
            return;
        }

        QRectF left, top, right, bottom;
        client()->window()->layoutDecorationRects(left, top, right, bottom);

        const qreal dpr = effectiveDevicePixelRatio();
        const int topHeight = std::round(top.height() * dpr);
        const int bottomHeight = std::round(bottom.height() * dpr);
        const int leftWidth = std::round(left.width() * dpr);

        const QPoint topPos(0, 0);
        const QPoint bottomPos(0, topPos.y() + topHeight + (2 * TexturePad));
        const QPoint leftPos(0, bottomPos.y() + bottomHeight + (2 * TexturePad));
        const QPoint rightPos(0, leftPos.y() + leftWidth + (2 * TexturePad));

        const QRect dirtyRect = region.boundingRect();

        renderPart(top.intersected(dirtyRect), top, topPos, dpr);
        renderPart(bottom.intersected(dirtyRect), bottom, bottomPos, dpr);
        renderPart(left.intersected(dirtyRect), left, leftPos, dpr, true);
        renderPart(right.intersected(dirtyRect), right, rightPos, dpr, true);
    }

private:
    void renderPart(const QRectF& rect, const QRectF& partRect,
                    const QPoint& textureOffset,
                    qreal devicePixelRatio, bool rotated = false) {
        if (!rect.isValid() || !m_texture) {
            return;
        }

        const QMargins padding = texturePadForPart(rect, partRect);
        int verticalPadding = padding.top() + padding.bottom();
        int horizontalPadding = padding.left() + padding.right();

        QSize imageSize(toNativeSize(rect.width()), toNativeSize(rect.height()));
        if (rotated) {
            std::swap(imageSize.width(), imageSize.height());
        }

        QSize paddedSize = imageSize;
        paddedSize.rheight() += verticalPadding;
        paddedSize.rwidth() += horizontalPadding;

        QImage image(paddedSize, QImage::Format_ARGB32_Premultiplied);
        image.setDevicePixelRatio(devicePixelRatio);
        image.fill(Qt::transparent);

        QRect clip(padding.left(), padding.top(), imageSize.width(), imageSize.height());
        QPainter painter(&image);
        const qreal invScale = 1.0 / devicePixelRatio;
        painter.scale(invScale, invScale);
        painter.setRenderHint(QPainter::Antialiasing);
        painter.setClipRect(clip);
        painter.translate(padding.left(), padding.top());

        if (rotated) {
            painter.translate(0, imageSize.height());
            painter.rotate(-90);
        }

        painter.scale(devicePixelRatio, devicePixelRatio);
        painter.translate(-rect.topLeft());
        renderToPainter(&painter, rect);
        painter.end();

        clamp(image, clip);

        QPoint dirtyOffset = ((rect.topLeft() - partRect.topLeft()) * devicePixelRatio).toPoint();
        if (padding.top() == 0) {
            dirtyOffset.ry() += TexturePad;
        }
        if (padding.left() == 0) {
            dirtyOffset.rx() += TexturePad;
        }

        m_texture->update(image, image.rect(), textureOffset + dirtyOffset);
    }

    static QMargins texturePadForPart(const QRectF& rect, const QRectF& partRect) {
        QMargins result;
        if (rect.top() == partRect.top()) result.setTop(TexturePad);
        if (rect.bottom() == partRect.bottom()) result.setBottom(TexturePad);
        if (rect.left() == partRect.left()) result.setLeft(TexturePad);
        if (rect.right() == partRect.right()) result.setRight(TexturePad);
        return result;
    }

    static void clampRow(int left, int width, int right, const uint32_t* src, uint32_t* dest) {
        std::fill_n(dest, left, *src);
        std::copy_n(src, width, dest + left);
        std::fill_n(dest + left + width, right, *(src + width - 1));
    }

    static void clampSides(int left, int width, int right, const uint32_t* src, uint32_t* dest) {
        std::fill_n(dest, left, *src);
        std::fill_n(dest + left + width, right, *(src + width - 1));
    }

    static void clamp(QImage& image, const QRect& viewport) {
        Q_ASSERT(image.depth() == 32);
        if (viewport.isEmpty()) {
            image = QImage{};
            return;
        }

        const QRect rect = image.rect();
        const int left = viewport.left() - rect.left();
        const int top = viewport.top() - rect.top();
        const int right = rect.right() - viewport.right();
        const int bottom = rect.bottom() - viewport.bottom();
        const int width = rect.width() - left - right;
        const int height = rect.height() - top - bottom;

        const uint32_t* firstRow = reinterpret_cast<const uint32_t*>(image.scanLine(top));
        const uint32_t* lastRow = reinterpret_cast<const uint32_t*>(image.scanLine(top + height - 1));

        for (int i = 0; i < top; ++i) {
            uint32_t* dest = reinterpret_cast<uint32_t*>(image.scanLine(i));
            clampRow(left, width, right, firstRow + left, dest);
        }

        for (int i = 0; i < height; ++i) {
            uint32_t* dest = reinterpret_cast<uint32_t*>(image.scanLine(top + i));
            clampSides(left, width, right, dest + left, dest);
        }

        for (int i = 0; i < bottom; ++i) {
            uint32_t* dest = reinterpret_cast<uint32_t*>(image.scanLine(top + height + i));
            clampRow(left, width, right, lastRow + left, dest);
        }
    }

    void resizeTexture() {
        QRectF left, top, right, bottom;
        client()->window()->layoutDecorationRects(left, top, right, bottom);

        QSize size;
        size.rwidth() = toNativeSize(std::max({top.width(), bottom.width(), left.height(), right.height()}));
        size.rheight() = toNativeSize(top.height()) + toNativeSize(bottom.height()) + toNativeSize(left.width()) + toNativeSize(right.width());
        size.rheight() += 4 * (2 * TexturePad);
        size.rwidth() += 2 * TexturePad;
        size.rwidth() = align(size.width(), 128);

        if (m_texture && m_texture->size() == size) {
            return;
        }

        if (!size.isEmpty()) {
            m_texture = GLTexture::allocate(GL_RGBA8, size);
            if (!m_texture) {
                return;
            }
            m_texture->setContentTransform(OutputTransform::FlipY);
            m_texture->setFilter(GL_LINEAR);
            m_texture->setWrapMode(GL_CLAMP_TO_EDGE);
        } else {
            m_texture.reset();
        }
    }

    int toNativeSize(double size) const {
        return std::round(size * effectiveDevicePixelRatio());
    }

    static int align(int value, int alignment) {
        return (value + alignment - 1) & ~(alignment - 1);
    }

private:
    std::shared_ptr<GLTexture> m_texture;
};

