// Thread-safe-ish va() using round-robin buffer selection
const char* va(const char* fmt, ...) {
    static constexpr std::size_t BUFFER_COUNT = 64;
    static constexpr std::size_t BUFFER_SIZE = 65536;
    static char buffers[BUFFER_COUNT][BUFFER_SIZE];
    static thread_local std::size_t next_index = 0;

    va_list args;
    va_start(args, fmt);
    const auto current = next_index % BUFFER_COUNT;
    vsnprintf(buffers[current], BUFFER_SIZE, fmt, args);
    next_index = (next_index + 1) % BUFFER_COUNT;
    va_end(args);

    return buffers[current];
}

// Convert string to lowercase using locale-aware transform
std::string str_to_lower(std::string input) {
    std::ranges::transform(input, input.begin(),
        [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
    return input;
}

// Wide string to narrow string conversion
std::string convert_wstring(const std::wstring& wstr) {
    std::ostringstream oss;
    for (wchar_t wc : wstr) {
        oss << static_cast<char>(wc);
    }
    return oss.str();
}

// Narrow string to wide string conversion (UTF-8)
std::wstring string_to_wstring(const std::string& str) {
#ifdef _WIN32
    const int size_needed = MultiByteToWideChar(CP_UTF8, 0, str.c_str(), -1, nullptr, 0);
    if (size_needed <= 0) return {};
    std::wstring wstr(size_needed, L'\0');
    MultiByteToWideChar(CP_UTF8, 0, str.c_str(), -1, &wstr[0], size_needed);
    return wstr;
#else
    // Fallback: simple cast (not safe for multi-byte chars)
    std::wstring result;
    result.reserve(str.size());
    for (char c : str) {
        result.push_back(static_cast<wchar_t>(c));
    }
    return result;
#endif
}

// Portable space detection
int is_space(int c) {
    return (c >= 0 && std::isspace(static_cast<unsigned char>(c))) ? 1 : 0;
}

// Trim from left
std::string& ltrim(std::string& s) {
    auto it = std::find_if(s.begin(), s.end(), [](int ch) { return !is_space(ch); });
    s.erase(s.begin(), it);
    return s;
}

// Trim from right
std::string& rtrim(std::string& s) {
    auto rit = std::find_if(s.rbegin(), s.rend(), [](int ch) { return !is_space(ch); });
    s.erase(rit.base(), s.end());
    return s;
}

// Trim both ends
std::string& trim(std::string& s) {
    return ltrim(rtrim(s));
}

// Safe integer conversion
int try_stoi(const std::string& str, int fallback) {
    try {
        std::size_t pos;
        int val = std::stoi(str, &pos);
        if (pos == str.length()) return val;
    } catch (...) {}
    return fallback;
}

// Safe float conversion
float try_stof(const std::string& str, float fallback) {
    try {
        std::size_t pos;
        float val = std::stof(str, &pos);
        if (pos == str.length()) return val;
    } catch (...) {}
    return fallback;
}

// Transpose 3x4 matrix into D3DXMATRIX
void transpose_float3x4_to_d3dxmatrix(const float3x4& src, D3DXMATRIX& dest) {
    dest = {};
    dest._11 = src.m[0][0]; dest._12 = src.m[1][0]; dest._13 = src.m[2][0];
    dest._21 = src.m[0][1]; dest._22 = src.m[1][1]; dest._23 = src.m[2][1];
    dest._31 = src.m[0][2]; dest._32 = src.m[1][2]; dest._33 = src.m[2][2];
    dest._41 = src.m[0][3]; dest._42 = src.m[1][3]; dest._43 = src.m[2][3];
    dest._44 = 1.0f;
}

// Transpose multiple matrices
void transpose_d3dxmatrix(const D3DXMATRIX* input, D3DXMATRIX* output, std::uint32_t count) {
    for (std::uint32_t i = 0; i < count; ++i) {
        const auto& in = input[i];
        auto& out = output[i];
        out._11 = in.m[0][0]; out._12 = in.m[1][0]; out._13 = in.m[2][0]; out._14 = in.m[3][0];
        out._21 = in.m[0][1]; out._22 = in.m[1][1]; out._23 = in.m[2][1]; out._24 = in.m[3][1];
        out._31 = in.m[0][2]; out._32 = in.m[1][2]; out._33 = in.m[2][2]; out._34 = in.m[3][2];
        out._41 = in.m[0][3]; out._42 = in.m[1][3]; out._43 = in.m[2][3]; out._44 = in.m[3][3];
    }
}

// Transpose 4x4 row-major to column-major
void transpose_float4x4(const float* row_major, float* column_major) {
    for (int i = 0; i < 4; ++i) {
        for (int j = 0; j < 4; ++j) {
            column_major[j * 4 + i] = row_major[i * 4 + j];
        }
    }
}

// Robust float comparison
bool float_equal(float a, float b, float eps) {
    return std::abs(a - b) <= eps;
}

// Remap value within range clamped
float map_range_clamped(float value, float in_min, float in_max, float out_min, float out_max) {
    if (in_min == in_max) return out_min;
    float t = (value - in_min) / (in_max - in_min);
    t = std::max(0.0f, std::min(t, 1.0f));
    return out_min + t * (out_max - out_min);
}

// Open file relative to root path
bool open_file_homepath(const std::string& sub_dir, const std::string& file_name, std::ifstream& file) {
    namespace fs = std::filesystem;
    const auto full_path = fs::path(shared::globals::root_path) / sub_dir / file_name;
    file.open(full_path);
    return file.is_open();
}

// FNV-1a 32-bit hash over raw bytes
std::uint32_t data_hash32(const void* data, std::size_t size) {
    constexpr std::uint32_t fnv_prime = 16777619u;
    constexpr std::uint32_t offset_basis = 2166136261u;
    std::uint32_t hash = offset_basis;
    const auto* bytes = static_cast<const std::uint8_t*>(data);
    for (std::size_t i = 0; i < size; ++i) {
        hash ^= bytes[i];
        hash *= fnv_prime;
    }
    return hash;
}

// FNV-1a 64-bit hash over string view
std::uint64_t string_hash64(const std::string_view& str) {
    constexpr std::uint64_t fnv_prime = 1099511628211ull;
    constexpr std::uint64_t offset_basis = 14695981039346656037ull;
    std::uint64_t hash = offset_basis;
    for (char c : str) {
        hash ^= static_cast<std::uint64_t>(static_cast<unsigned char>(c));
        hash *= fnv_prime;
    }
    return hash;
}

// FNV-1a 32-bit hash over string view
std::uint32_t string_hash32(const std::string_view& str) {
    constexpr std::uint32_t fnv_prime = 16777619u;
    constexpr std::uint32_t offset_basis = 2166136261u;
    std::uint32_t hash = offset_basis;
    for (char c : str) {
        hash ^= static_cast<std::uint32_t>(static_cast<unsigned char>(c));
        hash *= fnv_prime;
    }
    return hash;
}

// Combine hashes using SipHash-like mixing
std::uint32_t hash32_combine(std::uint32_t seed, const char* str) {
    while (*str) {
        seed ^= static_cast<std::uint32_t>(*str++);
        seed *= 0x5bd1e995;
        seed ^= seed >> 15;
    }
    return seed;
}

std::uint32_t hash32_combine(std::uint32_t seed, int val) {
    seed ^= std::hash<int>{}(val) + 0x9e3779b9 + (seed << 6) + (seed >> 2);
    return seed;
}

std::uint32_t hash32_combine(std::uint32_t seed, float val) {
    union { float f; std::uint32_t u; } conv{val};
    seed ^= conv.u + 0x9e3779b9 + (seed << 6) + (seed >> 2);
    return seed;
}

// Debug helper to inspect vertex declaration
void lookat_vertex_decl([[maybe_unused]] IDirect3DDevice9* dev) {
#ifdef DEBUG
    IDirect3DVertexDeclaration9* decl = nullptr;
    if (SUCCEEDED(dev->GetVertexDeclaration(&decl))) {
        D3DVERTEXELEMENT9 elements[MAX_FVF_DECL_SIZE];
        UINT count = 0;
        decl->GetDeclaration(elements, &count);
        for (UINT i = 0; i < count; ++i) {
            const auto& e = elements[i];
            std::cout << "Elem[" << i << "]: Stream=" << e.Stream
                      << ", Offset=" << e.Offset
                      << ", Type=" << e.Type
                      << ", Usage=" << e.Usage
                      << ", UsageIdx=" << e.UsageIndex << "\n";
        }
        decl->Release();
    }
#endif
}

