HighFiveGestureFilter::HighFiveGestureFilter() 
    : mHighFived(false) {}

HighFiveGestureFilter::~HighFiveGestureFilter() {}

bool HighFiveGestureFilter::CheckHighFive() {
    // Toggle state if high-five was previously detected
    bool result = mHighFived;
    if (result) {
        mHighFived = false;
    }
    return result;
}

void HighFiveGestureFilter::Update(Skeleton const *leftSkeleton, Skeleton const *rightSkeleton) {
    if (!leftSkeleton || !rightSkeleton) {
        return;
    }

    Vector3 leftShoulderPos, rightShoulderPos;

    // Retrieve shoulder center positions from both skeletons
    leftSkeleton->JointPos(kCoordCamera, kJointShoulderCenter, leftShoulderPos);
    rightSkeleton->JointPos(kCoordCamera, kJointShoulderCenter, rightShoulderPos);

    // Iterate through hand joints (4 sides: left/right hand + left/right elbow)
    int sideIndex = 0;
    while (sideIndex < 4) {
        TrackedJoint leftHandJoint = leftSkeleton->HandJoint(static_cast<SkeletonSide>(sideIndex));
        TrackedJoint rightHandJoint = rightSkeleton->HandJoint(static_cast<SkeletonSide>(sideIndex));
        ++sideIndex;
    }
}

#include "ArcKnowledgeFilter.h"
#include "ArcKnowledgeEntry.h"
#include "ArcKnowledgeQuery.h"

bool FArcKnowledgeFilter_MaxDistance::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
    // Compute squared distance between entry location and query origin
    const FVector Delta = Entry.Location - Context.QueryOrigin;
    const float DistSq = Delta.SizeSquared();

    // Compare against squared maximum distance threshold
    const float MaxDistSq = MaxDistance * MaxDistance;
    return DistSq <= MaxDistSq;
}

bool FArcKnowledgeFilter_MinRelevance::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
    // Check if entry's relevance meets or exceeds minimum required value
    return Entry.Relevance >= MinRelevance;
}

bool FArcKnowledgeFilter_MaxAge::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
    // Calculate age in seconds based on current time and entry timestamp
    const double ElapsedTime = Context.CurrentTime - Entry.Timestamp;
    return ElapsedTime <= MaxAgeSeconds;
}

bool FArcKnowledgeFilter_PayloadType::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
    // If no specific payload type is required, all entries pass
    if (!RequiredPayloadType)
    {
        return true;
    }

    // Verify payload exists and its script struct inherits from required type
    return Entry.Payload.IsValid() && 
           Entry.Payload.GetScriptStruct()->IsChildOf(RequiredPayloadType);
}

bool FArcKnowledgeFilter_NotClaimed::PassesFilter(const FArcKnowledgeEntry& Entry, const FArcKnowledgeQueryContext& Context) const
{
    // Only allow entries that have not been claimed
    return !Entry.bClaimed;
}

#include <guik/screen_capture.hpp>
#include <glk/io/png_io.hpp>
#include <glk/io/jpeg_io.hpp>
#include <glk/pixel_buffer.hpp>
#include <glk/console_colors.hpp>
#include <guik/viewer/light_viewer.hpp>

namespace guik {

ScreenCapture::ScreenCapture(
  const Eigen::Vector2i& img_dims,
  int num_encoder_workers,
  int num_scratch_buffers,
  std::shared_ptr<guik::ConcurrentQueue<std::pair<std::string, PixelsPtr>>> work_queue)
: image_size(img_dims),
  frame_counter(0),
  shutdown_flag(false),
  pending_queue(work_queue) {

  dst_paths.resize(num_encoder_workers);
  scratch_buffers.resize(num_scratch_buffers);

  // Initialize pixel buffers
  for (auto& buf : scratch_buffers) {
    buf = std::make_shared<glk::PixelBuffer>(img_dims, sizeof(unsigned char) * 4);
  }

  encoder_threads.resize(num_encoder_workers);
  for (auto& worker : encoder_threads) {
    worker = std::thread([this] { background_encode_loop(); });
  }
}

ScreenCapture::~ScreenCapture() {
  // Flush remaining pending captures before shutting down threads
  for (int idx = 0; idx < static_cast<int>(dst_paths.size()); ++idx) {
    if (!dst_paths[idx].empty()) {
      auto pixels = std::make_shared<std::vector<unsigned char>>(
        std::move(scratch_buffers[idx]->read_pixels<unsigned char>())
      );
      pending_queue->push(std::make_pair(dst_paths[idx], pixels));
    }
  }

  shutdown_flag = true;
  for (auto& worker : encoder_threads) {
    if (worker.joinable()) {
      worker.join();
    }
  }
}

size_t ScreenCapture::queue_length() const {
  return pending_queue->size();
}

void ScreenCapture::capture(const std::string& target_path) {
  auto viewer = guik::viewer();
  capture(target_path, viewer->color_buffer());
}

void ScreenCapture::capture(const std::string& target_path, const glk::Texture& tex) {
  const int slot_index = frame_counter % static_cast<int>(scratch_buffers.size());

  if (tex.size() != image_size) {
    std::cerr << glk::console::yellow << "warning: image dimensions mismatch!" << glk::console::reset << std::endl;
    return;
  }

  // If there's an existing pending capture in this slot, flush it first
  if (!dst_paths[slot_index].empty()) {
    const std::string saved_path = dst_paths[slot_index];
    auto pixels = std::make_shared<std::vector<unsigned char>>(
      std::move(scratch_buffers[slot_index]->read_pixels<unsigned char>())
    );
    pending_queue->push(std::make_pair(saved_path, pixels));
  }

  dst_paths[slot_index] = target_path;
  scratch_buffers[slot_index]->copy_from_texture(tex, GL_RGBA, GL_UNSIGNED_BYTE);
  ++frame_counter;
}

void ScreenCapture::background_encode_loop() {
  while (true) {
    auto batch = pending_queue->try_pop(4);
    if (batch.empty()) {
      if (shutdown_flag) break;
      std::this_thread::sleep_for(std::chrono::milliseconds(10));
      continue;
    }

    for (const auto& [path, pixel_data] : batch) {
      // Flip image vertically (row-swapping)
      std::vector<unsigned char> temp_row(image_size[0] * 4);
      int top_row = 0;
      int bottom_row = image_size[1] - 1;

      while (top_row < bottom_row) {
        unsigned char* row_top = pixel_data->data() + (top_row * image_size[0] * 4);
        unsigned char* row_bottom = pixel_data->data() + (bottom_row * image_size[0] * 4);

        std::memcpy(temp_row.data(), row_top, image_size[0] * 4);
        std::memcpy(row_top, row_bottom, image_size[0] * 4);
        std::memcpy(row_bottom, temp_row.data(), image_size[0] * 4);

        ++top_row;
        --bottom_row;
      }

      // Determine format by extension
      std::string_view ext(path);
      size_t dot_pos = path.rfind('.');
      if (dot_pos != std::string::npos) {
        ext = path.substr(dot_pos);
      }

      bool success = false;
      if (ext == ".png") {
        success = glk::save_png(path, image_size[0], image_size[1], *pixel_data);
      } else if (ext == ".jpg" || ext == ".jpeg") {
        success = glk::save_jpeg(path, image_size[0], image_size[1], *pixel_data);
      }

      if (!success) {
        std::cerr << glk::console::yellow << "warning: failed to save " << path << glk::console::reset << std::endl;
      }
    }
  }
}

}

#include "tests.h"
#include "peg-parser.h"
