#include <stdio.h>
#include <string.h>
#include <algorithm>
#include <deque>
#include <string>
#include <utility>
#include <vector>
#include "logging.h"
#include "pod_array.h"
#include "prog.h"
#include "regexp.h"
#include "sparse_array.h"
#include "sparse_set.h"
#include "strutil.h"

namespace lbug {
namespace regex {

static const bool ExtraDebug = false;

class NFA {
public:
    NFA(Prog* prog);
    ~NFA();

    bool Search(const StringPiece& text, const StringPiece& context, bool anchored, bool longest,
        StringPiece* submatch, int nsubmatch);

private:
    struct Thread {
        union {
            int ref_count;
            Thread* next_free; // when on free list
        };
        const char** capture_data;
    };

    struct StackFrame {
        int inst_id;     // instruction to process
        Thread* saved_t; // if not null, set t0 = t before processing id
    };

    typedef SparseArray<Thread*> StateQueue;

    inline Thread* CreateThread();
    inline Thread* IncrementRef(Thread* t);
    inline void DecrementRef(Thread* t);

    void ExpandState(
        StateQueue* q, int inst_id, int byte_val, const StringPiece& context, const char* pos, Thread* base_thread);

    int ProcessStep(StateQueue* current_q, StateQueue* next_q, int byte_val, const StringPiece& context, const char* pos);

    std::string FormatCaptures(const char** captures);
    void DuplicateCaptures(const char** dst, const char** src) {
        memmove(dst, src, num_captures_ * sizeof(src[0]));
    }

    Prog* program_;               // underlying program
    int initial_inst_;            // start instruction in program
    int num_captures_;            // number of submatches to track
    bool find_longest_;           // whether searching for longest match
    bool require_end_match_;      // whether match must end at text.end()
    const char* text_begin_;      // beginning of text (for FormatSubmatch)
    const char* text_end_;        // end of text (for endmatch_)
    StateQueue queue_a_, queue_b_; // pre-allocated for Search.
    PODArray<StackFrame> stack_buffer_; // pre-allocated for ExpandState
    std::deque<Thread> memory_pool_; // thread arena
    Thread* free_list_;           // thread freelist
    const char** best_match_;     // best match so far
    bool has_found_match_;        // any match so far?

    NFA(const NFA&) = delete;
    NFA& operator=(const NFA&) = delete;
};

NFA::NFA(Prog* prog) {
    program_ = prog;
    initial_inst_ = prog_->start();
    num_captures_ = 0;
    find_longest_ = false;
    require_end_match_ = false;
    text_begin_ = nullptr;
    text_end_ = nullptr;
    queue_a_.resize(prog_->size());
    queue_b_.resize(prog_->size());

    int stack_needed = 2 * prog_->inst_count(kInstCapture) + 
                       prog_->inst_count(kInstEmptyWidth) +
                       prog_->inst_count(kInstNop) + 1;
    stack_buffer_ = PODArray<StackFrame>(stack_needed);

    free_list_ = nullptr;
    best_match_ = nullptr;
    has_found_match_ = false;
}

NFA::~NFA() {
    delete[] best_match_;
    for (const Thread& t : memory_pool_)
        delete[] t.capture_data;
}

NFA::Thread* NFA::CreateThread() {
    Thread* t = free_list_;
    if (t != nullptr) {
        free_list_ = t->next_free;
        t->ref_count = 1;
        return t;
    }
    memory_pool_.emplace_back();
    t = &memory_pool_.back();
    t->ref_count = 1;
    t->capture_data = new const char*[num_captures_];
    return t;
}

NFA::Thread* NFA::IncrementRef(Thread* t) {
    DCHECK(t != nullptr);
    t->ref_count++;
    return t;
}

void NFA::DecrementRef(Thread* t) {
    DCHECK(t != nullptr);
    t->ref_count--;
    if (t->ref_count > 0)
        return;
    DCHECK_EQ(t->ref_count, 0);
    t->next_free = free_list_;
    free_list_ = t;
}

void NFA::ExpandState(
    StateQueue* q, int inst_id, int byte_val, const StringPiece& context, const char* pos, Thread* base_thread) {
    if (inst_id == 0)
        return;

    StackFrame* frame_stack = stack_buffer_.data();
    int stack_top = 0;
    frame_stack[stack_top++] = {inst_id, nullptr};

    while (stack_top > 0) {
        DCHECK_LE(stack_top, stack_buffer_.size());
        StackFrame current = frame_stack[--stack_top];

    ContinueProcessing:
        if (current.saved_t != nullptr) {
            DecrementRef(base_thread);
            base_thread = current.saved_t;
        }

        int id = current.inst_id;
        if (id == 0)
            continue;

        if (q->has_index(id)) {
            if (ExtraDebug)
                fprintf(stderr, "  [%d%s]\n", id, FormatCaptures(base_thread->capture_data).c_str());
            continue;
        }

        q->set_new(id, nullptr);
        Thread** slot = &q->get_existing(id);
        int capture_idx;
        Thread* t;

        Prog::Inst* ip = program_->inst(id);
        switch (ip->opcode()) {
        default:
            LOG(DFATAL) << "unhandled " << ip->opcode() << " in ExpandState";
            break;

        case kInstFail:
            break;

        case kInstAltMatch:
            t = IncrementRef(base_thread);
            *slot = t;
            DCHECK(!ip->last());
            current = {id + 1, nullptr};
            goto ContinueProcessing;

        case kInstNop:
            if (!ip->last())
                frame_stack[stack_top++] = {id + 1, nullptr};
            current = {ip->out(), nullptr};
            goto ContinueProcessing;

        case kInstCapture:
            if (!ip->last())
                frame_stack[stack_top++] = {id + 1, nullptr};
            if ((capture_idx = ip->cap()) < num_captures_) {
                frame_stack[stack_top++] = {0, base_thread};
                t = CreateThread();
                DuplicateCaptures(t->capture_data, base_thread->capture_data);
                t->capture_data[capture_idx] = pos;
                base_thread = t;
            }
            current = {ip->out(), nullptr};
            goto ContinueProcessing;

        case kInstByteRange:
            if (!ip->Matches(byte_val))
                goto NextBranch;
            t = IncrementRef(base_thread);
            *slot = t;
            if (ExtraDebug)
                fprintf(stderr, " + %d%s\n", id, FormatCaptures(base_thread->capture_data).c_str());
            if (ip->hint() == 0)
                break;
            current = {id + ip->hint(), nullptr};
            goto ContinueProcessing;

        case kInstMatch:
            t = IncrementRef(base_thread);
            *slot = t;
            if (ExtraDebug)
                fprintf(stderr, " ! %d%s\n", id, FormatCaptures(base_thread->capture_data).c_str());
        NextBranch:
            if (ip->last())
                break;
            current = {id + 1, nullptr};
            goto ContinueProcessing;

        case kInstEmptyWidth:
            if (!ip->last())
                frame_stack[stack_top++] = {id + 1, nullptr};
            if (ip->empty() & ~Prog::EmptyFlags(context, pos))
                break;
            current = {ip->out(), nullptr};
            goto ContinueProcessing;
        }
    }
}

int NFA::ProcessStep(StateQueue* current_q, StateQueue* next_q, int byte_val, const StringPiece& context, const char* pos) {
    next_q->clear();
    for (StateQueue::iterator iter = current_q->begin(); iter != current_q->end(); ++iter) {
        Thread* t = iter->value();
        if (t == nullptr)
            continue;

        if (find_longest_) {
            if (has_found_match_ && best_match_[0] < t->capture_data[0]) {
                DecrementRef(t);
                continue;
            }
        }

        int id = iter->index();
        Prog::Inst* ip = program_->inst(id);

        switch (ip->opcode()) {
        default:
            LOG(DFATAL) << "Unhandled " << ip->opcode() << " in step";
            break;

        case kInstByteRange:
            ExpandState(next_q, ip->out(), byte_val, context, pos, t);
            break;

        case kInstAltMatch:
            if (iter != current_q->begin())
                break;
            if (ip->greedy(program_) || find_longest_) {
                DuplicateCaptures(best_match_, t->capture_data);
                has_found_match_ = true;
                DecrementRef(t);
                for (++iter; iter != current_q->end(); ++iter) {
                    if (iter->value() != nullptr)
                        DecrementRef(iter->value());
                }
                current_q->clear();
                if (ip->greedy(program_))
                    return ip->out1();
                return ip->out();
            }
            break;

        case kInstMatch: {
            if (pos == nullptr) {
                DuplicateCaptures(best_match_, t->capture_data);
                best_match_[1] = pos;
                has_found_match_ = true;
                break;
            }
            if (require_end_match_ && pos - 1 != text_end_)
                break;
            if (find_longest_) {
                if (!has_found_match_ || t->capture_data[0] < best_match_[0] ||
                    (t->capture_data[0] == best_match_[0] && pos - 1 > best_match_[1])) {
                    DuplicateCaptures(best_match_, t->capture_data);
                    best_match_[1] = pos - 1;
                    has_found_match_ = true;
                }
            } else {
                DuplicateCaptures(best_match_, t->capture_data);
                best_match_[1] = pos - 1;
                has_found_match_ = true;
                DecrementRef(t);
                for (++iter; iter != current_q->end(); ++iter) {
                    if (iter->value() != nullptr)
                        DecrementRef(iter->value());
                }
                current_q->clear();
                return 0;
            }
            break;
        }
        }
        DecrementRef(t);
    }
    current_q->clear();
    return 0;
}

std::string NFA::FormatCaptures(const char** captures) {
    std::string result;
    for (int i = 0; i < num_captures_; i += 2) {
        if (captures[i] == nullptr)
            result += "(?,?)";
        else if (captures[i + 1] == nullptr)
            result += StringPrintf("(%td,?)", captures[i] - text_begin_);
        else
            result += StringPrintf("(%td,%td)", captures[i] - text_begin_, captures[i + 1] - text_begin_);
    }
    return result;
}

bool NFA::Search(const StringPiece& text, const StringPiece& const_context, bool anchored,
    bool longest, StringPiece* submatch, int nsubmatch) {
    if (initial_inst_ == 0)
        return false;

    StringPiece context = const_context;
    if (context.data() == nullptr)
        context = text;

    if (BeginPtr(text) < BeginPtr(context) || EndPtr(text) > EndPtr(context)) {
        LOG(DFATAL) << "context does not contain text";
        return false;
    }

    if (program_->anchor_start() && BeginPtr(context) != BeginPtr(text))
        return false;

    if (program_->anchor_end() && EndPtr(context) != EndPtr(text))
        return false;

    anchored |= program_->anchor_start();
    if (program_->anchor_end()) {
        longest = true;
        require_end_match_ = true;
    }

    if (nsubmatch < 0) {
        LOG(DFATAL) << "Bad args: nsubmatch=" << nsubmatch;
        return false;
    }

    num_captures_ = 2 * nsubmatch;
    find_longest_ = longest;

    if (nsubmatch == 0) {
        num_captures_ = 2;
    }

    best_match_ = new const char*[num_captures_];
    memset(best_match_, 0, num_captures_ * sizeof(best_match_[0]));
    has_found_match_ = false;

    text_begin_ = context.data();
    text_end_ = text.data() + text.size();

    if (ExtraDebug)
        fprintf(stderr, "NFA::Search %s (context: %s) anchored=%d longest=%d\n",
            std::string(text).c_str(), std::string(context).c_str(), anchored, longest);

    StateQueue* active_queue = &queue_a_;
    StateQueue* next_queue = &queue_b_;
    active_queue->clear();
    next_queue->clear();

    for (const char* pos = text.data();; pos++) {
        if (ExtraDebug) {
            int c = 0;
            if (pos == text_begin_)
                c = '^';
            else if (pos > text_end_)
                c = '$';
            else if (pos < text_end_)
                c = pos[0] & 0xFF;
            fprintf(stderr, "%c:", c);
            for (StateQueue::iterator iter = active_queue->begin(); iter != active_queue->end(); ++iter) {
                Thread* t = iter->value();
                if (t == nullptr)
                    continue;
                fprintf(stderr, " %d%s", iter->index(), FormatCaptures(t->capture_data).c_str());
            }
            fprintf(stderr, "\n");
        }

        int shortcut_id = ProcessStep(active_queue, next_queue, 
            pos < text_end_ ? pos[0] & 0xFF : -1, context, pos);
        DCHECK_EQ(active_queue->size(), 0);
        using std::swap;
        swap(next_queue, active_queue);
        next_queue->clear();

        if (shortcut_id != 0) {
            pos = text_end_;
            for (;;) {
                Prog::Inst* ip = program_->inst(shortcut_id);
                switch (ip->opcode()) {
                default:
                    LOG(DFATAL) << "Unexpected opcode in short circuit: " << ip->opcode();
                    break;
                case kInstCapture:
                    if (ip->cap() < num_captures_)
                        best_match_[ip->cap()] = pos;
                    shortcut_id = ip->out();
                    continue;
                case kInstNop:
                    shortcut_id = ip->out();
                    continue;
                case kInstMatch:
                    best_match_[1] = pos;
                    has_found_match_ = true;
                    break;
                }
                break;
            }
            break;
        }

        if (pos > text_end_)
            break;

        if (!has_found_match_ && (!anchored || pos == text.data())) {
            if (!anchored && active_queue->size() == 0 && pos < text_end_ && program_->can_prefix_accel()) {
                pos = reinterpret_cast<const char*>(program_->PrefixAccel(pos, text_end_ - pos));
                if (pos == nullptr)
                    pos = text_end_;
            }

            Thread* t = CreateThread();
            DuplicateCaptures(t->capture_data, best_match_);
            t->capture_data[0] = pos;
            ExpandState(active_queue, initial_inst_, 
                pos < text_end_ ? pos[0] & 0xFF : -1, context, pos, t);
            DecrementRef(t);
        }

        if (active_queue->size() == 0) {
            if (ExtraDebug)
                fprintf(stderr, "dead\n");
            break;
        }

        if (pos == nullptr) {
            (void)ProcessStep(active_queue, next_queue, -1, context, pos);
            DCHECK_EQ(active_queue->size(), 0);
            using std::swap;
            swap(next_queue, active_queue);
            next_queue->clear();
            break;
        }
    }

    for (StateQueue::iterator iter = active_queue->begin(); iter != active_queue->end(); ++iter) {
        if (iter->value() != nullptr)
            DecrementRef(iter->value());
    }

    if (has_found_match_) {
        for (int i = 0; i < nsubmatch; i++)
            submatch[i] =
                StringPiece(best_match_[2 * i], static_cast<size_t>(best_match_[2 * i + 1] - best_match_[2 * i]));
        if (ExtraDebug)
            fprintf(stderr, "match (%td,%td)\n", best_match_[0] - text_begin_, best_match_[1] - text_begin_);
        return true;
    }

    return false;
}

bool Prog::SearchNFA(const StringPiece& text, const StringPiece& context, Anchor anchor,
    MatchKind kind, StringPiece* match, int nmatch) {
    if (ExtraDebug)
        Dump();

    NFA nfa(this);
    StringPiece temp_sp;

    if (kind == kFullMatch) {
        anchor = kAnchored;
        if (nmatch == 0) {
            match = &temp_sp;
            nmatch = 1;
        }
    }

    if (!nfa.Search(text, context, anchor == kAnchored, kind != kFirstMatch, match, nmatch))
        return false;

    if (kind == kFullMatch && EndPtr(match[0]) != EndPtr(text))
        return false;

    return true;
}

void Prog::Fanout(SparseArray<int>* fanout) {
    DCHECK_EQ(fanout->max_size(), size());
    SparseSet reachable_nodes(size());
    fanout->clear();
    fanout->set_new(start(), 0);

    for (SparseArray<int>::iterator outer_iter = fanout->begin(); outer_iter != fanout->end(); ++outer_iter) {
        int* count_ptr = &outer_iter->value();
        reachable_nodes.clear();
        reachable_nodes.insert(outer_iter->index());

        for (SparseSet::iterator inner_iter = reachable_nodes.begin(); inner_iter != reachable_nodes.end(); ++inner_iter) {
            int node_id = *inner_iter;
            Prog::Inst* ip = inst(node_id);

            switch (ip->opcode()) {
            default:
                LOG(DFATAL) << "unhandled " << ip->opcode() << " in Prog::Fanout()";
                break;

            case kInstByteRange:
                if (!ip->last())
                    reachable_nodes.insert(node_id + 1);
                (*count_ptr)++;
                if (!fanout->has_index(ip->out())) {
                    fanout->set_new(ip->out(), 0);
                }
                break;

            case kInstAltMatch:
                DCHECK(!ip->last());
                reachable_nodes.insert(node_id + 1);
                break;

            case kInstCapture:
            case kInstEmptyWidth:
            case kInstNop:
                if (!ip->last())
                    reachable_nodes.insert(node_id + 1);
                reachable_nodes.insert(ip->out());
                break;

            case kInstMatch:
                if (!ip->last())
                    reachable_nodes.insert(node_id + 1);
                break;

            case kInstFail:
                break;
            }
        }
    }
}

