namespace {
struct EmptyColorHandler {
  void faceColor(int /*f*/, int /*m*/) {}
  void edgeColor(int /*e*/, int /*m*/) {}
  void vertexColor(int /*v*/, int /*m*/) {}
};
} // namespace

//-------------------------------------------------------------------------------
template <typename VerticesContainer, typename PointT, typename ColorFunc>
inline void drawMeshEdges(const TTextureMesh &mesh,
                          const VerticesContainer &verts,
                          ColorFunc &&colorFn) {
  glBegin(GL_LINES);
  auto eIt = mesh.edges().begin();
  auto eEnd = mesh.edges().end();
  for (; eIt != eEnd; ++eIt) {
    const auto &edge = *eIt;
    int v0 = edge.vertex(0), v1 = edge.vertex(1);
    const PointT &pt0 = verts[v0];
    const PointT &pt1 = verts[v1];

    colorFn.edgeColor(eIt.index(), -1);
    colorFn.vertexColor(v0, -1);
    glVertex2d(tcg::point_traits<PointT>::x(pt0),
               tcg::point_traits<PointT>::y(pt0));
    colorFn.vertexColor(v1, -1);
    glVertex2d(tcg::point_traits<PointT>::x(pt1),
               tcg::point_traits<PointT>::y(pt1));
  }
  glEnd();
}
//-------------------------------------------------------------------------------
template <typename ColorFunc>
inline void drawMeshFaces(const TMeshImage &mi, ColorFunc &&colorFn) {
  glBegin(GL_TRIANGLES);
  int mCount = mi.meshes().size();
  for (int m = 0; m < mCount; ++m) {
    const TTextureMesh &mesh = *mi.meshes()[m];
    const tcg::list<TTextureVertex> &vertices = mesh.vertices();

    auto fIt = mesh.faces().begin();
    auto fEnd = mesh.faces().end();
    for (; fIt != fEnd; ++fIt) {
      int v0, v1, v2;
      mesh.faceVertices(fIt.index(), v0, v1, v2);

      const TTextureVertex &p0 = vertices[v0];
      const TTextureVertex &p1 = vertices[v1];
      const TTextureVertex &p2 = vertices[v2];

      colorFn.faceColor(fIt.index(), m);
      colorFn.vertexColor(v0, m); glVertex2d(p0.P().x, p0.P().y);
      colorFn.vertexColor(v1, m); glVertex2d(p1.P().x, p1.P().y);
      colorFn.vertexColor(v2, m); glVertex2d(p2.P().x, p2.P().y);
    }
  }
  glEnd();
}
//-------------------------------------------------------------------------------
template <typename ColorFunc>
inline void drawDeformedFaces(const TMeshImage &mi,
                              const PlasticDeformerDataGroup *grp,
                              ColorFunc &&colorFn) {
  glBegin(GL_TRIANGLES);

  using FacePair = std::pair<int, int>;
  const std::vector<FacePair> &sortedList = grp->m_sortedFaces;
  const std::vector<TTextureMeshP> &meshVec = mi.meshes();

  int currentMeshIdx = -1;
  const TTextureMesh *currentMesh = nullptr;
  const double *outputCoords = nullptr;

  for (const auto &pair : sortedList) {
    int faceIdx = pair.first;
    int meshIdx = pair.second;

    if (meshIdx != currentMeshIdx) {
      currentMeshIdx = meshIdx;
      currentMesh = meshVec[meshIdx].getPointer();
      outputCoords = grp->m_datas[meshIdx].m_output.get();
    }

    int v0, v1, v2;
    currentMesh->faceVertices(faceIdx, v0, v1, v2);

    const double *coord0 = outputCoords + (v0 << 1);
    const double *coord1 = outputCoords + (v1 << 1);
    const double *coord2 = outputCoords + (v2 << 1);

    colorFn.faceColor(faceIdx, meshIdx);
    colorFn.vertexColor(v0, meshIdx); glVertex2d(*coord0, *(coord0 + 1));
    colorFn.vertexColor(v1, meshIdx); glVertex2d(*coord1, *(coord1 + 1));
    colorFn.vertexColor(v2, meshIdx); glVertex2d(*coord2, *(coord2 + 1));
  }

  glEnd();
}
}  // namespace

//********************************************************************************************
//    Mesh Image Utility Functions
//********************************************************************************************
void applyAffineToMesh(TMeshImageP &mi, const TAffine &aff) {
  const auto &meshes = mi->meshes();
  for (auto &meshPtr : meshes) {
    TTextureMesh &mesh = *meshPtr;
    auto &vertexList = mesh.vertices();
    for (auto &vert : vertexList) {
      vert.P() = aff * vert.P();
    }
  }
}
//-------------------------------------------------------------------------------
void drawEdges(const TMeshImage &mi, const PlasticDeformerDataGroup *grp) {
  const auto &meshes = mi.meshes();
  int count = meshes.size();

  if (grp) {
    for (int i = 0; i < count; ++i) {
      const TPointD *coords = reinterpret_cast<const TPointD *>(
          grp->m_datas[i].m_output.get());
      drawMeshEdges<const TPointD *, TPointD, EmptyColorHandler>(
          *meshes[i], coords, EmptyColorHandler{});
    }
  } else {
    for (int i = 0; i < count; ++i) {
      const TTextureMesh &mesh = *meshes[i];
      drawMeshEdges<tcg::list<TTextureMesh::vertex_type>, TTextureVertex,
                    EmptyColorHandler>(mesh, mesh.vertices(),
                                       EmptyColorHandler{});
    }
  }
}
//-------------------------------------------------------------------------------
void drawFaces(const TMeshImage &mi, const PlasticDeformerDataGroup *grp) {
  if (grp)
    drawDeformedFaces(mi, grp, EmptyColorHandler{});
  else
    drawMeshFaces(mi, EmptyColorHandler{});
}

//********************************************************************************************
//    Colored Drawing Implementations
//********************************************************************************************
namespace {
struct LinearColorMapper {
  using ValueGetter = double (*)(const LinearColorMapper *, int, int);

  const TMeshImage &m_image;
  const PlasticDeformerDataGroup *m_group;
  double m_minVal, m_maxVal;
  double *m_colorMin, *m_colorMax;
  double m_delta;
  bool m_isFlat;
  ValueGetter m_getValue;

  LinearColorMapper(const TMeshImage &img,
                    const PlasticDeformerDataGroup *grp,
                    double minV, double maxV,
                    double *cMin, double *cMax,
                    ValueGetter getter)
      : m_image(img)
      , m_group(grp)
      , m_minVal(minV)
      , m_maxVal(maxV)
      , m_colorMin(cMin)
      , m_colorMax(cMax)
      , m_delta(maxV - minV)
      , m_isFlat(m_delta < 1e-4)
      , m_getValue(getter) {}

  void operator()(int primIdx, int meshIdx) const {
    if (m_isFlat) {
      glColor4d(0.5 * (m_colorMin[0] + m_colorMax[0]),
                0.5 * (m_colorMin[1] + m_colorMax[1]),
                0.5 * (m_colorMin[2] + m_colorMax[2]),
                0.5 * (m_colorMin[3] + m_colorMax[3]));
      return;
    }

    double val = m_getValue(this, meshIdx, primIdx);
    double t = (val - m_minVal) / m_delta;
    double oneMinusT = 1.0 - t;

    glColor4d(oneMinusT * m_colorMin[0] + t * m_colorMax[0],
              oneMinusT * m_colorMin[1] + t * m_colorMax[1],
              oneMinusT * m_colorMin[2] + t * m_colorMax[2],
              oneMinusT * m_colorMin[3] + t * m_colorMax[3]);
  }
};

struct VertexColorMapper final : public LinearColorMapper, EmptyColorHandler {
  using LinearColorMapper::LinearColorMapper;
  void vertexColor(int v, int m) override { (*this)(v, m); }
};

struct FaceColorMapper final : public LinearColorMapper, EmptyColorHandler {
  using LinearColorMapper::LinearColorMapper;
  void faceColor(int f, int m) override { (*this)(f, m); }
};
}  // namespace

//===============================================================================
void drawSO(const TMeshImage &image,
            double minColor[4], double maxColor[4],
            const PlasticDeformerDataGroup *group,
            bool useDeformedDomain) {
  auto soGetter = [](const LinearColorMapper *mapper, int m, int f) -> double {
    return mapper->m_group->m_datas[m].m_so[f];
  };

  double minVal = group ? group->m_soMin : 0.0;
  double maxVal = group ? group->m_soMax : 0.0;

  FaceColorMapper colorFn(image, group, minVal, maxVal, minColor, maxColor,
                          soGetter);

  if (group && useDeformedDomain)
    drawDeformedFaces(image, group, colorFn);
  else
    drawMeshFaces(image, colorFn);
}
//-------------------------------------------------------------------------------
void drawRigidity(const TMeshImage &image,
                  double minColor[4], double maxColor[4],
                  const PlasticDeformerDataGroup *group,
                  bool useDeformedDomain) {
  auto rigidityGetter = [](const LinearColorMapper *mapper, int m, int v) -> double {
    return mapper->m_image.meshes()[m]->vertex(v).P().rigidity;
  };

  VertexColorMapper colorFn(image, group, 1.0, 1e4, minColor, maxColor,
                            rigidityGetter);

  if (group && useDeformedDomain)
    drawDeformedFaces(image, group, colorFn);
  else
    drawMeshFaces(image, colorFn);
}

//********************************************************************************************
//    Texturized Drawing Implementation
//********************************************************************************************
void drawTextured(const TMeshImage &meshImage,
                  const DrawableTextureData &texData,
                  const TAffine &meshToTexAff,
                  const PlasticDeformerDataGroup &group) {
  using TileData = MeshTexturizer::TextureData::TileData;

  glPushAttrib(GL_COLOR_BUFFER_BIT | GL_LINE_BIT | GL_HINT_BIT);
  glEnable(GL_BLEND);
  glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
  glEnable(GL_LINE_SMOOTH);
  glLineWidth(1.0f);
  glHint(GL_LINE_SMOOTH_HINT, GL_NICEST);

  const auto &meshes = meshImage.meshes();
  const MeshTexturizer::TextureData *td = texData.m_textureData;
  const std::vector<std::pair<int, int>> &sortedFaces = group.m_sortedFaces;

  int tileCount = td->m_tileDatas.size();
  std::vector<TAffine> tileTransforms(tileCount);
  for (int t = 0; t < tileCount; ++t) {
    const TileData &tile = td->m_tileDatas[t];
    const TRectD &rect = tile.m_tileGeometry;
    tileTransforms[t] =
        TScale(1.0 / (rect.x1 - rect.x0), 1.0 / (rect.y1 - rect.y0)) *
        TTranslation(-rect.x0, -rect.y0) * meshToTexAff;
  }

  GLuint boundTexture = ~0u;
  int currentMesh = -1;
  const TTextureMesh *activeMesh = nullptr;
  const double *deformedCoords = nullptr;

  for (const auto &faceEntry : sortedFaces) {
    int faceIndex = faceEntry.first;
    int meshIndex = faceEntry.second;

    if (meshIndex != currentMesh) {
      currentMesh = meshIndex;
      activeMesh = meshes[meshIndex].getPointer();
      deformedCoords = group.m_datas[meshIndex].m_output.get();
    }

    const auto &face = activeMesh->face(faceIndex);
    const auto &e0 = activeMesh->edge(face.edge(0));
    const auto &e1 = activeMesh->edge(face.edge(1));
    const auto &e2 = activeMesh->edge(face.edge(2));

    int v0 = e0.vertex(0);
    int v1 = e0.vertex(1);
    int v2 = e1.vertex((e1.vertex(0) == v0) || (e1.vertex(0) == v1));
    int e1OtherVert = (e1.vertex(0) == v1) || (e1.vertex(1) == v1);
    int e2OtherVert = 1 - e1OtherVert;

    const TPointD &p0 = activeMesh->vertex(v0).P();
    const TPointD &p1 = activeMesh->vertex(v1).P();
    const TPointD &p2 = activeMesh->vertex(v2).P();

    for (int t = 0; t < tileCount; ++t) {
      const TileData &tile = td->m_tileDatas[t];
      TPointD mapped[3] = {
          tileTransforms[t] * p0,
          tileTransforms[t] * p1,
          tileTransforms[t] * p2
      };

      double minX = std::min({mapped[0].x, mapped[1].x, mapped[2].x});
      double minY = std::min({mapped[0].y, mapped[1].y, mapped[2].y});
      double maxX = std::max({mapped[0].x, mapped[1].x, mapped[2].x});
      double maxY = std::max({mapped[0].y, mapped[1].y, mapped[2].y});

      if (minX > 1.0 || minY > 1.0 || maxX < 0.0 || maxY < 0.0)
        continue;

      if (tile.m_textureId != boundTexture) {
        boundTexture = tile.m_textureId;
        glBindTexture(GL_TEXTURE_2D, boundTexture);
      }

      const double *coords[3] = {
          deformedCoords + (v0 << 1),
          deformedCoords + (v1 << 1),
          deformedCoords + (v2 << 1)
      };

      bool drawE0 = (e0.facesCount() < 2);
      bool drawE1 = (e1.facesCount() < 2);
      bool drawE2 = (e2.facesCount() < 2);

      // Draw edges — RGB pass
      glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_FALSE);
      glBegin(GL_LINES);
      if (drawE0) {
        glTexCoord2d(mapped[0].x, mapped[0].y);
        glVertex2d(coords[0][0], coords[0][1]);
        glTexCoord2d(mapped[1].x, mapped[1].y);
        glVertex2d(coords[1][0], coords[1][1]);
      }
      if (drawE1) {
        glTexCoord2d(mapped[e1OtherVert].x, mapped[e1OtherVert].y);
        glVertex2d(coords[e1OtherVert][0], coords[e1OtherVert][1]);
        glTexCoord2d(mapped[2].x, mapped[2].y);
        glVertex2d(coords[2][0], coords[2][1]);
      }
      if (drawE2) {
        glTexCoord2d(mapped[e2OtherVert].x, mapped[e2OtherVert].y);
        glVertex2d(coords[e2OtherVert][0], coords[e2OtherVert][1]);
        glTexCoord2d(mapped[2].x, mapped[2].y);
        glVertex2d(coords[2][0], coords[2][1]);
      }
      glEnd();

      // Draw edges — Alpha pass
      glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
      glBegin(GL_LINES);
      if (drawE0) {
        glTexCoord2d(mapped[0].x, mapped[0].y);
        glVertex2d(coords[0][0], coords[0][1]);
        glTexCoord2d(mapped[1].x, mapped[1].y);
        glVertex2d(coords[1][0], coords[1][1]);
      }
      if (drawE1) {
        glTexCoord2d(mapped[e1OtherVert].x, mapped[e1OtherVert].y);
        glVertex2d(coords[e1OtherVert][0], coords[e1OtherVert][1]);
        glTexCoord2d(mapped[2].x, mapped[2].y);
        glVertex2d(coords[2][0], coords[2][1]);
      }
      if (drawE2) {
        glTexCoord2d(mapped[e2OtherVert].x, mapped[e2OtherVert].y);
        glVertex2d(coords[e2OtherVert][0], coords[e2OtherVert][1]);
        glTexCoord2d(mapped[2].x, mapped[2].y);
        glVertex2d(coords[2][0], coords[2][1]);
      }
      glEnd();

      // Draw face — RGB pass
      glBlendFunc(GL_SRC_ALPHA, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_TRUE, GL_TRUE, GL_TRUE, GL_FALSE);
      glBegin(GL_TRIANGLES);
      glTexCoord2d(mapped[0].x, mapped[0].y);
      glVertex2d(coords[0][0], coords[0][1]);
      glTexCoord2d(mapped[1].x, mapped[1].y);
      glVertex2d(coords[1][0], coords[1][1]);
      glTexCoord2d(mapped[2].x, mapped[2].y);
      glVertex2d(coords[2][0], coords[2][1]);
      glEnd();

      // Draw face — Alpha pass
      glBlendFunc(GL_ONE, GL_ONE_MINUS_SRC_ALPHA);
      glColorMask(GL_FALSE, GL_FALSE, GL_FALSE, GL_TRUE);
      glBegin(GL_TRIANGLES);
      glTexCoord2d(mapped[0].x, mapped[0].y);
      glVertex2d(coords[0][0], coords[0][1]);
      glTexCoord2d(mapped[1].x, mapped[1].y);
      glVertex2d(coords[1][0], coords[1][1]);
      glTexCoord2d(mapped[2].x, mapped[2].y);
      glVertex2d(coords[2][0], coords[2][1]);
      glEnd();
    }
  }

  glBindTexture(GL_TEXTURE_2D, 0);
  glPopAttrib();
}

