StudentImpl::StudentImpl(std::string name, std::string surName, std::string firstName)
  : Parent(std::move(name), std::move(surName), std::move(firstName))
{
  // Initialize noise generators with unique seeds based on student identity and randomness
  focusLevelNoise_.seed(sen::hashCombine(sen::crc32("focusLevel"), sen::crc32(name), rand()));        // NOLINT
  snortingLevelNoise_.seed(sen::hashCombine(sen::crc32("snortingLevel"), sen::crc32(name), rand()));  // NOLINT
  setNextStatus(DoingNothing {});
}

StudentImpl::~StudentImpl() = default;

void StudentImpl::update(sen::kernel::RunApi& runApi)
{
  PersonImpl::update(runApi);

  // Dispatch current activity handling based on active state
  std::visit(
    sen::Overloaded{
      [&](const DoingNothing& act) { handleIdleState(runApi.getTime(), act); },
      [&](const DoingSomething& act) { handleActiveTask(runApi.getTime(), act); },
      [&](const Sleeping& act) { handleSleepState(runApi.getTime(), act); }
    },
    getStatus()
  );
}

std::string StudentImpl::askImpl(const std::string& question)
{
  std::ignore = question;  // ignore input as per typical student behavior

  return std::visit(
    sen::Overloaded{
      [&](const DoingNothing&) -> std::string {
        static const std::array<const char*, 3> responses = {"Yes", "No", "I don't know..."};
        return responses[rand() % responses.size()];  // NOLINT
      },
      [&](const DoingSomething&) -> std::string {
        static const std::array<const char*, 3> replies = {"I'm busy!", "Can't say right now", "Hold on, I need to finish this first"};
        return replies[rand() % replies.size()];  // NOLINT
      },
      [&](const Sleeping&) -> std::string {
        setNextStatus(DoingNothing{getLastCommitTime()});  // wake up immediately
        static const std::array<const char*, 3> grogginess = {"mhhhh??", "zfghhh... ??", ".....zZzZzZz"};
        return grogginess[rand() % grogginess.size()];  // NOLINT
      }
    },
    getStatus()
  );
}

bool StudentImpl::startDoingTaskImpl(const std::string& taskName, float32_t difficulty)
{
  if (std::holds_alternative<DoingSomething>(getStatus()))
    return false;  // already occupied

  setNextStatus(DoingSomething{this->getLastCommitTime(), taskName, difficulty, 0.0f});
  return true;
}

void StudentImpl::handleIdleState(const sen::TimeStamp& now, const DoingNothing& current)
{
  // Focus level fluctuates slightly due to internal noise
  setNextFocusLevel((static_cast<float32_t>(focusLevelNoise_({now.sinceEpoch().toSeconds()})) + 1.0f) * 0.5f * 0.1f);

  // Track how long we've been idle
  if (current.since.sinceEpoch().getNanoseconds() == 0)
  {
    setNextStatus(DoingNothing{now});
  }
  else if ((now - current.since) > sen::Duration(std::chrono::seconds(5)))
  {
    // After 5 seconds of idleness, fall asleep
    setNextStatus(Sleeping{now});
    setNextFocusLevel(0.0f);
  }
  else if (rand() % 10 == 0)  // NOLINT
  {
    // Randomly express boredom
    static const std::array<const char*, 4> comments = {"I'm bored", "lalala...", "hey, the teacher is dumb", "this sucks"};
    saidSomething(comments[rand() % comments.size()]);  // NOLINT
  }
}

void StudentImpl::handleActiveTask(const sen::TimeStamp& now, const DoingSomething& current)
{
  float32_t newProgress = current.progress + current.difficulty;
  setNextFocusLevel((static_cast<float32_t>(focusLevelNoise_({now.sinceEpoch().toSeconds()})) + 1.0f) * 0.5f);

  if (newProgress >= 1.0f)
  {
    setNextStatus(DoingNothing{now});
    saidSomething("done with " + current.taskName);
  }
  else
  {
    DoingSomething updated = current;
    updated.progress = newProgress;
    setNextStatus(std::move(updated));
    if (rand() % 7 == 0)  // NOLINT
    {
      saidSomething("this " + current.taskName + " thing is not easy...");
    }
  }
}

void StudentImpl::handleSleepState(const sen::TimeStamp& now, const Sleeping& current)
{
  auto elapsedSecs = now.sinceEpoch().toSeconds();

  // Wake up after sleeping for 3 seconds
  if ((now - current.since) > std::chrono::seconds(3))
  {
    setNextStatus(DoingNothing{now});
    saidSomething("was I sleeping?");
    return;
  }

  float64_t snortIntensity = snortingLevelNoise_({elapsedSecs});
  if (snortIntensity < 0.9)
  {
    Sleeping next = current;
    next.snortingVolume = static_cast<float32_t>(snortIntensity);
    setNextStatus(next);
  }
  else
  {
    static const std::array<const char*, 4> snores = {"hrghh..hfmmf", "mmhmm.ghfnf", "mmmh?...zzzZzz", "grr..ffwg"};
    static const std::array<float32_t, 5> volumes = {0.1f, 0.7f, 0.33f, 1.3f, 0.41f};

    setNextStatus(DoingNothing{now});
    madeSomeNoise(snores[rand() % snores.size()], volumes[rand() % volumes.size()]);  // NOLINT
  }
}

void StudentImpl::hearSomeNoise(const std::string& sound, float32_t intensity)
{
  if (rand() % 2 == 0)  // NOLINT
  {
    std::string reason;
    reason += "heard a noise '";
    reason += sound;
    reason += "' with volume ";
    reason += std::to_string(intensity);
    gotDistracted(reason);
  }
}
