// Function to evaluate the VDE model using provided callback
void VDE_fun_model(const double* input, double* output,
                      int (*vde_callback)(const double**, double**, int*, double*,
                                 int)) {
    // Define dimensions
    const int STATE_DIM = 4;
    const int INPUT_DIM = 1;

    // Partition input array into components
    const double* state = input;
    const double* input_sens = input + STATE_DIM;
    const double* state_sens = input + STATE_DIM + INPUT_DIM * STATE_DIM;
    const double* control_input = input + STATE_DIM + STATE_DIM * (STATE_DIM + INPUT_DIM);

    // Partition output array into components
    double* next_state = output;
    double* next_state_sens = output + STATE_DIM;
    double* next_input_sens = output + STATE_DIM + INPUT_DIM * STATE_DIM;

    // Prepare arguments for the VDE solver
    const double* casadi_inputs[4];
    double* casadi_outputs[3];

    casadi_inputs[0] = state;
    casadi_inputs[1] = state_sens;
    casadi_inputs[2] = input_sens;
    casadi_inputs[3] = control_input;

    casadi_outputs[0] = next_state;
    casadi_outputs[1] = next_state_sens;
    casadi_outputs[2] = next_input_sens;

    // Workspace pointers (unused in this context)
    int* integer_work = nullptr;
    double* real_work = nullptr;
    int memory_id = 0;

    // Invoke the VDE solver
    vde_callback(casadi_inputs, casadi_outputs, integer_work, real_work, memory_id);
}

