TEST_CASE("fwd_count", "[alg][algorithm][seq_fwd]") {
    for (auto vec_size : test_arr_sizes) {
        auto data = iota_vector(vec_size);

        // Test std::count with a specific value
        {
            int target = 5;
            auto sequential_result = std::count(data.cbegin(), data.cend(), target);
            auto parallel_result = std::count(poolstl::seq_fwd, data.cbegin(), data.cend(), target);
            REQUIRE(sequential_result == parallel_result);
        }

        // Test std::count_if with a predicate
        {
            auto is_even = [](auto value) { return value % 2 == 0; };
            auto sequential_result = std::count_if(data.cbegin(), data.cend(), is_even);
            auto parallel_result = std::count_if(poolstl::seq_fwd, data.cbegin(), data.cend(), is_even);
            REQUIRE(sequential_result == parallel_result);
        }
    }
}

TEST_CASE("fwd_for_each", "[alg][algorithm][seq_fwd]") {
    std::atomic<int> counter{0};

    for (auto array_size : test_arr_sizes) {
        auto elements = iota_vector(array_size);

        for (auto implementation : {0, 1}) {
            counter = 0;
            auto increment_op = [&](auto) { ++counter; };

            if (implementation == 0) {
                std::for_each(elements.cbegin(), elements.cend(), increment_op);
            } else {
                std::for_each(poolstl::seq_fwd, elements.cbegin(), elements.cend(), increment_op);
            }

            REQUIRE(counter == array_size);
        }
    }
}

